INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '분위기가 너무 좋아서 들어서는 순간부터 기분이 확 좋아졌어요! 공간이 넓고 쾌적해서 답답함 없이 여유롭게 앉아 있을 수 있었고, 테이블 간 간격도 넓어서 프라이빗하게 대화하기에도 좋더라고요! 인테리어도 세련되고 포토존 같은 자리도 많아서 사진 찍기에도 제격이었어요! 무엇보다 커피 맛이 진짜 좋았는데 향부터 진하고 깊어서 한 모금 마실 때마다 만족스러웠어요! 디저트도 같이 곁들였는데 커피랑 너무 잘 어울려서 시간 가는 줄 모르고 즐겼답니다!ㅎㅎㅎ', 90, 17, 'GOOD', SYSTIMESTAMP);
