INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '대형카페는 처음 방문하는데 카페 들어오는 입구부터 독특하고 직원분들께서 커피종류도 친절하게 설명해주시고! 무엇보다 커피랑 디저트 전부 맛있어서 만족스러워요! 다음에 재방문의사 100%있습니다!', 47, 8, 'GOOD', SYSTIMESTAMP);
