INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '공간자체가 너무 좋아서 또 가고싶어요! 이번에는 친구랑 갔는데, 다음번에는 혼자와서 상대방이 아닌 저의 내면에만 집중해서 다시 한 번 즐겨보고 싶은 곳입니다 👍🤍 글귀나 메뉴설명 등이 영어로도 적혀있어서 외국인 친구랑 오기에도 정말 좋을 것 같아요~', 123, 20, 'GOOD', SYSTIMESTAMP);
