INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '🖼 내면의 발견 작품 앞에 서면 말없이도 전해지는 감정이 마음속에 잔잔히 번집니다. 이우환 작가님의 세계를 연상시키는 절제와 고요 속에서 차분한 사색이 필요한 날, 꼭 들러보길 추천합니다.', 4, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '홍대입구역에서 가깝고 서교동에 있는 대형 갤러리 카페 내면의 발견해 갔다. 정말 커피가 굉장하다 맛도 좋고 원두 커피도 원두가 시즌마다 바뀐다 커피를 좋아하는 사람 여기 꼭 와 봐야 한다. 영어가 능통한 직원도 있어서 미국인이 와도 좋다. English speakers welcome.', 101, 21, 'GOOD', SYSTIMESTAMP);
