INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '네이버 MY플레이스 에서 팔로잉한 린에스테틱a 님의 리뷰를 보고 방문한 내면의 발견 카페익니다, 저는 주로 음식점을 많이 다니고 카페는 많은곳을 방문을 해보진 않았지만 여기는 단층도 아닌 1~2층과 옥상에도 다양한 조경과 건축물이 있고 커피를 만드는곳에도 책과 글귀 등이 있어서 카페건물안에서 사색을 위해서 의자에 앉아서 음악들 듣거나 커피한잔과 달달 디저트를 맛보면서 혼자만의 시간을 가질수도 있고 아니면 여럿이와서 한바탕 수다를 풀고 갈수도 있는 공간입니다,, 분위기는 전자에 가까운 곳인것 같은데 각자 취향껏 공간에서 시간을 보내면 될듯 싶습니다, 갈려고했던 시간보다 1시간을 늦게와서 조금 급하게 둘러봤지만, 여유롭게 머물다 갔으면 하는 아쉬움이 들기도 합니다, 커피 잘마시고 갑니다 ☕️ 🍰', 46, 2, 'GOOD', SYSTIMESTAMP);
