INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '요즘에 카페가보면 커피는 맛없고 인테리어만 신경쓴 곳 많은데 여기는 다르다는걸 느꼈습니다! 커피도 맛있고 음료도 맛있어요 디저트 솔드아웃이라 다음에 꼭 먹으러 오겠습니다!! 매장이 넓은데 전시장 같은 느낌이라서 좋았습니다!! 가는 곳곳마다 사진찍기도 너무 좋아요!! 진짜 추천추천드려요!!', 31, 8, 'GOOD', SYSTIMESTAMP);
