INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '특별함을 좋아하는 나  오늘은 지인소개로  내면의발견카페 방문 👍🥰마치 갤러리 를 연상케해서  지친일상을 음악과  작품으로 힐링되게하는 공간💚🤩 메뉴도 다양하지만 오늘은 블랙수트 핸드드립  스파이스  티라미수 주문했는데 너무단아하고 예쁜  커피한상❤️💜❤️인테리어도 분위기있고  소품하나하나  스며드네요🫰사장님도 친절! 블랙수트는 담백하고 깔끔한맛 스파이스는 건강한맛의 음료ㆍ 티라미수숲은  커피와 케이크의조합  달콤한 사랑의느낌!❤️💚🥰 담번에는베리베리  스파이스라떼  여름한컵 라임그라니따  소만판나코타  먹어보러  오려구요❤️🫰 여기 화장실 가본중  역대급  특별함을 경험하실수있어요💚💜🩵💙', 42, 8, 'GOOD', SYSTIMESTAMP);
