INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '공간이 정말 넓고 커피도 진짜 맛있어요 웰컴 커피까지 주셔서 잘 먹었어요 층마다 공간마다 인테리어가 멋지고 이런 카페는 처음이라 새롭고 좋았어요 디저트도 맛있어서 다음번에 재방문의사 10000%예요ㅎㅎ잘 먹고 갑니다^^', 50, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '여긴 카페이기도하지만 예술공간입니다. 맛집블로그하면서 진짜 여러 카페를 다녀봤지만 여긴 어나더레벨이었어요. 마치 미술관에 들어온 느낌이고 정말 생각을 할수 있는 여러 포인트들과 문구들이 있었습니다. 그냥 한잔의 커피가 아니라 느끼고 생각하고 상상하는 커피! 플레이팅도 디저트도 정말 크레레이지하다는 말밖엔... 외국인들이 한국의 카페를 현대적으로 느끼기도 좋고 정말 멋진 곳이 있어 자랑스럽습니다. 이런 서울시에서 홍보해줘야하는거 아닌가 싶을 정도입니다.', 66, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '왔는데 정말 생각보다 너무 좋아서 다음번에 또 와야겠다 생각이 든 곳입니다! 공간이 주는 평온함과 함께 음료와 디저트도 맛있어서 소음에 민감한 저희 부부는 너무 좋았어요 :)', 33, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '너무 마음에 드는 곳이에요 ! 저는 지독한 카페 예민러거든요 사실 디저트가 화려하거나 식기에 신경을 많이 쓰는 곳 치고 맛에 집중도가 높은 곳은 본 적 없어서 컨셉 자체에 호감도를 두고 방문 했는데요 내면의 발견 덕에 커피의 새로운 발견을 할 수 있었던 거 같아요 시그니처인 맛의 발견 말 그대로 다채롭고 풍부한 과실향에 찾아 온 보람 가득했어요 티라미수는 아묻따 강추에요 부드럽고 짭단한 크림이 킥인데 눅눅함 없이 오래 커피와 즐기기 좋았습니다 친절함은 말 뭐 ! 근처에 거주했다면 정말 자주 방문하고 싶은 곳이에요 !', 22, 0, 'GOOD', SYSTIMESTAMP);
