INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '전시장 같은 느낌의 카페인데 드립커피를 다양한 원두로 판매해요 조용한 대형카페인데 디저트도 맛있고 라떼도 맛있어서 분위기 좋은 카페를 찾으신다면 방문해 보시면 좋을 것 같아요', 28, 10, 'GOOD', SYSTIMESTAMP);
