INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '커피 티라미수 전시까지 모두 완벽했던 카페..💕커피 원두 종류가 다양하고 시음,시향해서 고를 수 있었어요.  원두를 직접 블랜딩 하셔서 그런지 마셔보지 못한 커피맛이여서 더 좋았구요 마음이 편안해지는 전시도 즐기고 잘 힐링하다 갑니다☺️🤍', 10, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '무더운 여름날 한없이 걸어가며 우연히 찾은 내면의 발견 카페. 😋 사장님이 친절히 디저트 설명을 잘해주시고 시원하고 분위기가 편안해요🌿 숲을 모티브로 한 티라미수 한번 씩 맛보고 가면 좋을 것 같아요 :)', 95, 22, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '집근처라 지나치기만 하다 우연히 들렀는데 입구부터 메뉴까지 컨셉이 느껴져서 좋았어요! 사진 찍기도 좋은데 편안하게 대화하기 좋은 카페였어서 일행과 좋은 시간 보냈습니다. 재방문 의사 있어요 🥰', 4, 1, 'GOOD', SYSTIMESTAMP);
