INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '카패가 감각적이고 차분하여 들어오면서도 마음이 편안해지네요. 여백의 미에 디테일이 살아있는 세련된 느낌을 줍니다. 모닝 메뉴로 커피와 디저트 세트를 먹었는데, 커피도 원두도 좋고 디카페인인데도 맛에 신경써서 만족스러웠습니다. 디저트도 너무 예쁘고 커피랑 잘 어울려서 맛있게 먹었어요. 여기는 혼자 와소 책 읽기도 좋고, 좋아하는 친구랑 와서 담소 나누기도 좋을 것 같아요. :)', 61, 14, 'GOOD', SYSTIMESTAMP);
