INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '우아아아아…. 서교동에 이렇게 숨어 있는 #내돈내산 #핸드드립 커피발견..! 뚜두둥..! 어 마 무 시 드 립 커 피 맛 집 🏠 대 발 견!! 이라니!! 🧑🏻‍🍳 우선 바리스타쌤들 경력과 포스가 남다르고요! ☕️ 핸드립으로 기본급 이상 원두 & 찐 손맛의 조화! 퍼펙트! 🌿 1층에서 3층까지 전문적인 공간 분리와 인테리어 콘셉트! 🤫 내면의발견에서만 가능한 호기심 자극. 맛의발견 메뉴! 🎵 음악 선정. 넘 죠쿠요. 혼자로든. 동행으로든. 좋은 공간! 뭐랄까 서촌 이도림 느낌인데 드립 수준은 그 이상이고 인테리어는 덜어내고 정제되었다랄까…. 게다가 공간 구성이 프라이빗해서 사람 바글바글해도 프라이빗한 너낌 조만간 또 봐유😇 #빈브라더스 #커피맛집 #홍대데이트 #홍대까페 #서교동카페', 3, 1, 'GOOD', SYSTIMESTAMP);
