INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '우연히 들르게된 까페.내면의 발견. 까페이름부터 끌려 미로같은 입구를 통해 들어오게됐어요. 멋진 건축 인테리어 커피 맛까지 너무 좋네요.', 40, 10, 'GOOD', SYSTIMESTAMP);
