INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '갤러리에 온 느낌이에요. 커피맛도 너무 좋고 무엇보다 티라미슈가 짱 맛있네요 곳곳 포토스팟이 있어 갤러리 느낌나고 인테리어가 독특하니 좋네요. 데이트 코스로 와서 사진으로 추억남기기 좋아요', 114, 20, 'GOOD', SYSTIMESTAMP);
