INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '처음에 무슨 향수 가게인줄 알았을정도로 매장이 너무 예쁘고 좋은 향이 나요..홀린듯 들어와서 커피 한잔 하고 가요☺️☺️ 더 유명해지기 전에 얼른 들려 다행이에요! 카페 분위기만큼 좋은 시간 보내다 갑니다~~', 84, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '우연히 발견한 정말 멋진곳! 사진의 첫장이 화장실사진인데..화장실만 봐도 알듯... 장소가 너무 멋져서 그자체만으로도  갤러리에 들어와서 하나의 작품을 보는듯!', 61, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '건축물 전체가 아름답습니다.  층층마다의 작은  정원은 개성과 의미가 있고. 작은 건물 하나에 발걸음을 옮길 때마다 감탄이 나올 인테리어입니다. 커피의 맛까지 작은 디테일의 섬세함이 훌륭합니다.', 25, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'INDUSTRIAL');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '개화 블렌드 / brewing, hot / 7000원 카페 외관과 내부가 너무 멋져서 그냥 지나치지 못하고 들러봤는데, 바리스타님이 너무 친절하게 시음 도와주시고 설명해주셔서 원래 마실 생각 없었던 커피 한잔 충동적으로 시켜버렸습니다. 개화 블렌드는 에티오피아+페루 베이스의 블렌딩인데, 페루 원두 특유의 꽃과 과일 맛이 잘 느껴져서 아주 잘 마셨습니다! 산미 좋아하는 분들은 꼭 시켜먹을만 한거같아요. 산미 쨍하거나 부담스럽지 않고 부드러워서 오후 커피로 딱입니다 ㅎㅎ 싱글오리진 brewing 가격도 만 원 미만대라 합리적이고 좋습니다. 자주 들를듯해요', 35, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '마치 제주 섭지코지 글라스하우스를 떠올리게 하는 공간이네요.  동선 방향이 정해져 있는 편인데 층마다 마치 정원을 거니는 느낌이 나요. 지나가는 공간마저 아름답네요. 음료는 차처럼 전용 모듈에 컵이 담겨 나옵니다. 커피는 산미와 향이 있는걸 골랐는데 부드럽고 좋았어요. 라떼는 바닐라 시럽을 추가했는데 바닐라빈이 둥둥 떠있어서 좋은거 쓰시네 했어요 ㅎㅎ 3층은 옥상정원이고 멍하니 있기 좋았구요.  다만 좌석들이 안락의자같은 오래 편히 있는 의자는 아니에요.', 30, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '입구부터 모든공간이 연결되어 있는게 인상적이에요. 인테리어가 너무 멋져요. 커피나오는동안 한바퀴 둘러보니 기분이 좋네요. 주문한 커피도 상당히 멋지게 나왔어요. 컨셉이 확실한 카페네요.', 81, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '커피도 너무 맛있고  티라미슈도 정말 맛있었습니다. 그 날 추천해주시는 커피를 맛보고 커피를 선택하는 것도 너무 좋았어요. 두 번째 방문인데 그때그때 추천해주시는 커피로 마셨습니다. 티라미슈는 정말 순삭하게 만드는 맛이에요. 숲 같기도 하고 건물과 잘 어울리는 디저트였습니다. 일행이 오기 전에 혼자서 이곳저곳 돌아다녔는데 이곳은 옥상까지 꼭 가보시길 바래요. 이거 저곳 기웃기웃 하면서 천천히 건물을 음미해 보시면 좋을 것 같습니다.', 101, 23, 'GOOD', SYSTIMESTAMP);
