INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '실외,실내,옥상 인테리어 다 너무 예쁘고 예술적이에요. 인센트 향도 좋습니다. 커피도 진짜 맛있어요! 사진 찍기 좋고 친구들, 연인들 오기 좋은 곳입니다.', 6, 8, 'GOOD', SYSTIMESTAMP);
