INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '새로운 가능성의 발견은 안정적이고 고요한 공간 속에서 가능합니다. 이 공간 ‘내면의 발견’은 방문자들의 내면에서 희망 하나씩, 꺼내 들고 돌아갈 것 같아요. 이토록 아름다운 공간에 감탄하고 갑니다.', 24, 8, NULL, SYSTIMESTAMP);
