INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '설치미술의 작은 전시에 온 기분에 음료도 마시고 디저트도 먹기 신기한 장소. 둘러보기 좋고 구경하기 좋아서 지금 날씨 좋을때 구경하기 딱 좋다.', 84, 14, NULL, SYSTIMESTAMP);
