INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '입구를 찾기 처음에는 힘들었지만 전시장엔 느낌의 멋진 카페네요. 너무 조용해서 대화하기가 조심스런 느낌도 있지만 손님 모시기 좋은 곳입니다. 모던심플 좋아하시는 분이라면 추천하는 예쁜 카페.', 77, 17, 'GOOD', SYSTIMESTAMP);
