INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '공간적 만족도 최상입니다 이런 공간이 서울 한복판에 있다는게 놀라울정도 커피맛과 디저트 또한 퀄리티가 높음 지인들과 함께 이 공간을 즐겼으면 좋겠다는 생각이 들면서도 나만의 공간이길 바라는 마음이 동시에 듦', 34, 3, 'GOOD', SYSTIMESTAMP);
