INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '인테리어가 예쁘고 원두에 대해 친절하게 설명해주셔서 좋아요! 카페가 미술관 같아요 커피 좋아하시는 부모님모시고 또 방문하고 싶어요 .,🪽🤍', 21, 6, 'GOOD', SYSTIMESTAMP);
