INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '친구 집 근처라서 와봤는데  너무  좋더라구요~ 메뉴 설명도  디테일하게 해주시고 커피맛이  너무  맛있었어요!_!   여름 한컵 꼭 드셔보세요!!!!!👍😋', 7, 9, 'GOOD', SYSTIMESTAMP);
