INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '평소에 홍대 부근을 자주 배회하는지라 숨겨진 카페 찾는 걸 좋아하는데요 다른 장소를 찾다가 갑자기 새로오픈했다고 뜬 카페가 있었습니다 바로 여기.. 리뷰가 얼마 없는데도 보자마자 어떻고저떻고 판단할 겨를도 없이 걍 가봐야겠다. 라는 결심이 섰고 퇴근하자마자 바로 방문했습니다 우선 들어가는 입구에서부터 카페보다 미술관/전시회 느낌이 강한 인테리어에 너무나도 반해버렸어요 문화공간을 좋아하는 저로서는 걸음마다 제 눈과 발을 사로잡는 문구들에 정신을 못 차렸다죠,, 총 4층 건물인데 어느 한 곳 빼놓을 수 없이 다 멋진 공간이었습니다 근데 카페가 공간만 예쁘면 안 되죠 맛이 중요하죠 말해뭐해 전 카페인 못 먹는 찌질이인데 마침 디카페인이 있었는데요 걍 맛있었어요 더쓰고싶은데글자수가부족하대서나머지는직접가보심이어떨지', 55, 14, 'GOOD', SYSTIMESTAMP);
