INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '합정 느좋 카페로 추천합니다!! 커피 향도 너무좋아요 다른데와는 차원이 다릅니다! 인테리어 너무 멋져서 사진찍기도 좋으네요 ㅎㅎㅎ', 79, 12, 'GOOD', SYSTIMESTAMP);
