INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '커피도 너무 맛있고 원두가 다양해서 취향따라 먹기 너무 좋아요! 분위기도 너무 좋아서 꼭 전시보러 온 것 같은 느낌이라 기분이 너무 좋아지는 공간이네요🩷 사장님도 너무 친절하셔서 진짜 또 다시 올게요!!', 16, 5, 'GOOD', SYSTIMESTAMP);
