INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '서교동 거리를 걷던 중 깔끔한 외관의 건물이 눈에 띄어 호기심에 들어가 보았습니다. 내부가 전시장처럼 아름답고 마음이 편안해지는 분위기에 커피의 향과 맛도 기대 이상이었어요. 겉모습만 번지르르한 곳이 아닐까 했는데 기분 좋은 반전이 있는 공간이었습니다. 뜻밖의 내면 챙김과 만족감을 충족하고 나올 수 있었던 장소였어요.', 1, 9, 'GOOD', SYSTIMESTAMP);
