INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '각 음료랑 디저트마다 개성이 넘쳤어요!! 흔히 맛보지 못 한 맛이었어요. 라떼도 계피향이 나서 느끼하지 않았고, 여름 한 컵이 라임의 맛이랑 커피향이랑 잘 어울려서 찐찐 추천합니다❤️‍🔥👍👍', 114, 20, 'GOOD', SYSTIMESTAMP);
