INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '진짜 이런 카페 처음 보는 것 같아요 🙊 입구부터 공간 곳곳, 하나하나 신경 안쓰신 곳이 없다고 느껴졌어요 👍🏻 지나가다가 우연히 들어왔는데 공간을 둘러보는 것만으로도 너무 좋았고 음료도 너무 맛있어서 놀랐습니다 🔥 다음에 또 찾아올게요!!!', 68, 12, 'GOOD', SYSTIMESTAMP);
