INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '미팅 일정이 있어 잠시 들렀는데, 커피도 맛있고 인테리어가 상당했습니다. 커피를 들고 올라가는 길목이 인상깊었고 우연히 들어갔다 놀랐네요. 사장님도 친절하고 멋지십니다. 좋은 볼펜도 하나 챙겨주셨네요 :)', 5, 4, 'GOOD', SYSTIMESTAMP);
