INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '지나가다 우연히 본 카페입니다. 꼭 가봐야지 하다가 바로 다음날 오게 되었네요. 사람의 뇌는 가보지 못한 장소를 가봄으로 성장한다고 합니다. 이 장소는 뇌를 성장하게 만드는 특이한 구조안에 마음을 편케하는 인테리어가 있네요. 다른 사람들에게도 추천하고 싶어요.', 41, 5, 'GOOD', SYSTIMESTAMP);
