INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '전시회 왔다가 커피 한 잔 하는 느낌이예요~! 공간 자체로도 힐링되고, 커피도 맛있는데 나온 트레이 구성도 넘 예뻐요~!>< 또 올게요~', 5, 5, 'GOOD', SYSTIMESTAMP);
