INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '여기 추천으로 왔는데 갤러리 느낌의 인테리어와 가득한 포토존이 마음에 들었습니다. 음료와 디저트는 good을 넘어서는 great한 맛입니다. 구석구석 나를 만나는 듯한 글귀도 좋았습니다.', 20, 1, 'GOOD', SYSTIMESTAMP);
