INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '너티 우마미 라떼 마셨어요. 월드스타 챔피언이 내려주는 커피를 마셔볼수 있는 이벤트가 있어서 찾아왔습니다 고소함이 살아있는 커피였어요. 좋은 경험 하고 갑니다.', 22, 7, 'GOOD', SYSTIMESTAMP);
