INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '카페를 많이 다니는대 그중에서도 너무 만족스러운 카페였어요~👍👍 오기전에 사람많을까 걱정했는대 없어서 다행(?)이였어요😂 인기 많아지기전에 빨리 몇 번더 와야할거 같네여 ㅋㅎㅎㅋㅋ', 90, 16, 'GOOD', SYSTIMESTAMP);
