INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '예뻐요. 테라스도 뷰가 좋고, 가로수길 바로 옆이라, 오가는 풍경이 여유로워요~내부에 이끼랑 돌들 푸릇푸릇하구요. 티라미숲 디저트 맛있어요~!', 6, 4, 'GOOD', SYSTIMESTAMP);
