INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '깔끔하고 멋드러진 공간에서 마실때마다 놀라는 커피향과 맛은 내면의 발견에 또 방문할 수 밖에 없는 이유가 되기에 충분합니다:) 시그니처 진심 너무 맛있네요☕️♥️', 20, 1, 'GOOD', SYSTIMESTAMP);
