INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '공간도 너무 예쁘고, 디저트랑 커피도 기대 안했는데 너무 맛있었어요!!다른 카페들보다 가격도 저렴한데, 디저트도 훨씬 고급지고 다른 곳에서 안먹어본 맛이었어요!!❤️다른 사람들한테 추천해 주고 싶었습니다👍🏼', 70, 13, 'GOOD', SYSTIMESTAMP);
