INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '서교동에 새로생긴 멍때리기 좋은 정말 분위기 있는 까페  아무생각없이 들어갔다가  많은생각을하고 나올수있는 까페임이 틀림없다.  누구든 오면 반할수있는 까페라고  엄지 👍 척 하고싶네요  오늘은  바빠서 이정도만.....', 123, 24, 'GOOD', SYSTIMESTAMP);
