INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내면의 발견'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '콜드브루가 다른곳과는 다르게 과일향이 나면서, 색다른맛을 느낄수가있었습니다. 매장 또한 깔끔하며 직원분들도 친절하게 설명해주시고 색다른 카페를 찾는다면 추천드립니다.', 55, 12, 'GOOD', SYSTIMESTAMP);
