INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '오래 걸릴 것 같아서 웨이팅 걸고 근처에서 놀다보니 30분?정도 걸려서 들어왔어요. 되게 찐한 초코 빙순데 일반 빙수느낌?이 없고 너무 맛있었어요😆 기다렸던 시간이 다 이해되는 맛이더라고요.', 7, 8, 'GOOD', SYSTIMESTAMP);
