INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '홍대 초콜릿 디저트 전문점이에요. 초콜릿 매니아들 사이에 유명한지,, 대기가 길더라구요. 초코빙수가 진하고 맛있어요. 우유빙수에 초코를 뿌려주는게 아니고,, 빙수자체가 초코우유로 되어있어요.  다크초콜릿 음료도 카카오만 진하게 녹여서 쌉싸름하니 풍미가 좋으네요.', 11, 1, NULL, SYSTIMESTAMP);
