INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '캐치테이블로 등록 후 한 15분 뒤에 입장했어요. 빙수도 맛있고 넛이랑 크런치로 물리지 않게 끝까지 맛있게 먹을 수 있어서 좋았습니다. 시원한 물도 친절하게 주시고 화장실도 깨끗해서 좋았습니다.', 50, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '대기 없이 바로 입장한 건 처음이었는데 확실히 이사 후 매장이 넓어진 덕인 것 같네요! 여름 맞이해 초코빙수(오리지널)과 아이스크림을 처음으로 먹어봤는데 진짜 너무 맛있었습니다. 가족은 빙수가 의외로 너무 맛있다고 극찬했습니다. 개인적으로 토핑은 초코볼 외의 토핑이 더 잘 어우러지는 느낌. 묽지 않고 정말 초코만이 느껴지는 산뜻한 초코빙수와 리치리치한 초코아이스크림에 행복했습니다 ㅎㅎ 초코아이스크림은 끝에 프루티한 향이 느껴질 정도로 초코를 농축한 느낌이었습니다.', 20, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '일요일 오후 2시12분에 캐치테이블 웨이팅 등록, 오후 5시32분 입장해서 45분에 빙수 받았어요 주말에는 입장하고픈 시간에서 3시간전쯤 미리 웨이팅 걸어놓고 느긋하게 오시는것을 추천합니다. 다크 초콜릿 빙수 정말 맛있게 씁쓸하니 오리지널보단 다크 드시는걸 추천드려봅니다. 빙수 너무맛있구요 아이스크림도 풍부한 맛이라서 너무좋았어요', 71, 13, NULL, SYSTIMESTAMP);
