INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '오랜만에 먹었는데 웨이팅이 길어 힘들었지만 맛있어요 ㅎ 가격은 사악해졌네요^^ 16,000원 일때부터 먹었는데, 이사하기 전에요^^', 16, 1, NULL, SYSTIMESTAMP);
