INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '추울 때는 초콜릿만한 게 없는 것 같아요 시나몬 파우더 뿌려서 저어 먹으면 은은한 향 나고 좋네요 봉봉은 2월 말에 재판매하실 수 있으시대요 초콜릿만으로도 충분히 초콜릿의 풍미를 느낄 수 있어 좋았어요', 19, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '고등학생 때 몇 번 방문했었는데 약 5년 사이에 너무 유명해져서 이제는 웨이팅을 마음 먹지 않으면 자주 못 오게 된 17도씨...🍫 여름이 가기 전에 빙수 먹으러 방문했어요! 초코 진하기 차이점에 대해 세심하게 알려주시는 친절함에 주문할 때부터 감동하고... 진한 초콜릿 맛에 다시 한 번 감동... 저는 카페모카를 시켰는데 타 메뉴에 비해 초코 맛이 덜한 건 아쉽지만 초콜릿은 너무 달아서 커피 시키길 잘한 것 같아요 초코 케이크 크림 맛은 단연 17도씨가 최고네요 다음에 또 방문하겠습니다!🤎', 37, 8, 'GOOD', SYSTIMESTAMP);
