INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '추우니까 단거로 몸보신하러 왔어요 몽블랑 초콜릿에 밤맛이 찐하게나요 겨울엔 진짜진한 초콜릿 음료랑 몽블랑 번갈아가며 먹으러 와야겠어요! 역시 17도씨입니다!', 105, 24, 'GOOD', SYSTIMESTAMP);
