INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '너무맛있다!!! 이거 먹으러 홍대입구 왔는데 이게 무슨 맛 👀👀👀 퉁퉁부은날에도 눈이 떠지는 맛?!! 초코빙수 가격이 친근하진 않긴 한데 넘 맛있음 살면서 이런 고퀄빙수 (얼음맛나지않는부드러운데진한초코의물과얼음사이상태) 는 처음먹어봐요 정말 멋있는맛이야😖😎😎', 90, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '친구들 손에 끌려가서 몰랐는데 점심시간 조금만 지나도 웨이팅 생기는 카페더라구요! 초코빙수랑 진한초콜릿라떼 진짜 한입먹고 컬쳐쇼크먹었습니다 진짜 연남오면 가봐야하는 카페에요 초코빙수도 부드럽달다구리 진득한 초코맛이 느껴져서 넘 맛있는데 진짜진짜 찐은 초콜릿라떼에요... 친구가 이거 꼭 먹어봐야한다 그래서 생크림까지 같이 시켜서 한입 먹어보는데 와 달다?쓰다? 그거보다도 진짜 진해요 진하고 맛있습니다🍫🍫 하지만 아메리카노도 꼭 같이 시키세요 ...... 지금 리뷰쓰는데 또 한입 먹고싶네요 암튼 강추합니다👍👍', 21, 10, 'GOOD', SYSTIMESTAMP);
