INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '사람 정말 많네요. 현장에 웨이팅 기계 있고 3분만 늦어도 웨이팅 취소시킨다는 무시무시한 공지를 덕지덕지 붙여 놓으셨더라고요. 맛은 진한 초코맛이긴 한데, 원래 단 걸 좋아하지 않아서 그런지 그 이상 특별한 건 모르겠네요. 가심비가 쫌… ㅎ 단 거, 초코 엄청 좋아하시는 거 아니라면 굳이?', 41, 9, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '3시간을 기다려 방문했지만 별로였습니다. 입장 알림 1분도 채 되지 않아 입장했음에도 웨이팅 시스템에서 다음 번호로 넘어가는 점이 불편했습니다. 사장님께서‘아.. 그냥 해드릴게요’라는 다소 불친절한 태도와 좋지않은 표정으로 안내해주셨고 상황이 불편하고 음식은 취향에 맞지 않아 30분도 안돼 음식의 대부분을 남기고 그냥 나왔습니다."제가 좀 늦었죠?"라고 말한 부분은 불편했던 상황에 예의상 말한 것이었습니다. 웨이팅 시스템이 불편하다고 느끼는부분에 대해 말했을때 ''저희도 계속 건의중이다'' 라며 직원분도 현 웨이팅 시스템의 문제점을 인지하고 계셨습니다. 그럼에도 개선되지 않은 시스템을 고객에게 그대로 적용하며 오히려 손님에게 불편함을 느꼈다는 점에 대해 책임을 지기보다는 손님을 탓하는 듯한 태도로 보이네요.', 25, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '토요일 1:10웨이팅해서 3:35입장햇습니다 정리가 다 된 상태로 불러주셔서 편햇구요 들어가자마자 대기번호 확인합니당! 바쁘실텐데도 직원분들 친절하시고 매장 깨끗합니다 빙수를 다크랑 오리지널 둘 다 먹엇는데 다크2, 오리지널3으로 오리지널쪽이 좀 더 인기가 많앗어요… 다크는 쌉쌀합니다!', 4, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '역시나 소문대로 초코빙수는 진리였습니다 처음엔 빙수만 먹고 차례차례 토핑 뿌려먹었는데 순삭했네요 가게 이전하고 더 넓어져서 훨씬 이용하기 좋았어요 그리고 웨이팅 할때 가게 앞 그늘에 앉아있을수 있어서 더워도 괜찮았어요! 더위에 당 충전하고 왔어요', 39, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '초콜릿 빙수(친구들 픽), 오리지널 초콜릿(제 픽) 먹었어요! 대기를 꽤 오래한 것 같은데 테이크아웃 가능 메뉴를 먹으면 손해보는 느낌(?)일 것 같아서 테이크아웃 불가 메뉴만 먹었어요! 저는 원래 초콜릿을 좋아해서 만족스러웠어요! 다음엔 매니아로 맛보고 싶어요! 빙수도 괜찮았지만, 빙수보다는 초콜릿 자체가 더 매력적인 곳일 것 같아요👍👍', 17, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '중학생 때 서울디저트소개서적을 통해 알게 된 가게예요 사장님이 아직도 영업하고 계시다는 사실에 놀랐어요 맛은 말할 것도 없습니다…..초코가 메인인 카페 중 단언 1티어 전 비오는 날에 갔는데도 30분 넘게 대기했으니 참고하세요 메뉴는 쇼콜라봉봉(얼그레이)과 여름한정빙수(오리지널) 주문했습니다 이곳 메뉴는 뭘 고르든 맛이 있으니 안심하고 먹고 싶은 거 드세요!!', 2, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '금요일 4시반 웨이팅 36팀 2시간 10분 소모 입장 6시 40분 카톡알림 알아서 와서 근처에서 놀다가 2팀남았다고 알람 오면 가면 되는데 난 2팀 남았을때부터 20분인가 기다렸음... 오리지널 품절돼서 다크 초코 빙수 주문 토핑으로 크런키볼, 엄청 빠싹한 아몬드 슬라이스, 상큼한 멜팅초코? 같이 주는데 내 입맛에는 빙수랑 좀 안어울리는 거 같아서 빙수 다 먹고나서 따로 먹음 빙수는 텁텁하지 않고 사르르 녹는 식감이라 토핑 있으면 뭔가 방해됨 트위터에서 본거처럼 시나몬가루 뿌려먹는게 향 확 살면서 식감 유지돼서 너무 좋았고 토핑은 그냥 초콜릿에 아몬드랑 크런키볼 넣어서 토핑끼리만 먹는게 맛있었음', 39, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '보기와는 다르게 찐한맛 토요일 1시쯤 웨이팅걸어서 4시입장 21,000원 + 3시간 기다릴맛인가? 그건 또아님 음료 가격대도 많이 높아서 좀 부담됨', 109, 24, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '남자친구가 초콜릿을 워낙 좋아해서 갔는데 진짜 완전 초코여서 신기하고 달달했어요 카페웨이팅은 처음이였는데 웨이팅 한 보람있는 맛입니다!! 특히 저 초코빙수는 꼭 드세요 말그대로 산더미초코빙수입니다 단걸 엄청 좋아하는 사람은 아닌데도 진짜 맛있게 먹었어요 저 조각 초콜릿과 초코음료 안먹으면 생각나고 후회할 맛이에요 다음에 기회되면 또 방문하고싶어요ㅎ😋👍', 27, 1, 'GOOD', SYSTIMESTAMP);
