INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '초콜릿빙수 진짜 개ㅐㅐㅐ맛있어요 제가 그동안 먹었던 빙수는 다 가짜였다는 걸 깨달았습니다. 싼 가격은 아닌데 그만큼 정말…..👍', 28, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '평일날 운 좋게 또보겠지떡볶이 먹고 나왔더니 12:30. 사람들이 어디로 막 들어가길래 뭐지? 하고 봤더니 블루리본💙🎀 오픈시간 12:30 웨이팅 해야하는줄 알고 밖에 계신 직원분께 여쭤봤더니 테이크아웃 하는거면 바로 가능하다고 하셔서 들어감. 🍫초코아이스크림 6처넌.. 블루리본이니까🙃 - 아이스크림 주문하고 기다리면서 사람들이 주문한거 봤는데 초코빙수,, 담에 널 먹어보겠어😋 - 초콜렛 하나에 3,000원 안 사먹었지만 궁금하넿 👉🏻와 개맛있는데? 는 아니고 그냥 부드러운, 별로 안 단 초코아이스크림. 고D바가 더 맛있을지도..?👉🏻👈🏻 더운날이라 밖에서는 다 녹으니 매장에서 드시길! 다음에 간다면 초코 아이스크림은 안먹을듯?', 64, 17, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '평일 애매한 시간이라 손님이 없을 줄 알았는데 여전히 인기가 엄청 많아서 매장이용은 못하고 나왔습니다. 4월한정으로 나온 음료는 생각보다 너무 비싸서 놀랐지만, 한번쯤은 먹어볼만 한 것 같아요. 첫 방문이라 초콜릿 추천 부탁드렸는데 바쁜 와중에도 친절히 설명해주셔서 감사했습니다. 다음엔 매장이용하러 와보고싶어요.', 20, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '진짜진짜진한초콜릿 음료는 그 찰리와 초콜릿공장에 나오는 초콜릿 강물 떠마시는 느낌이었구요... 단맛도 살짝 나게 선택 가능해서 맛있고 좋았습니다! 초코 아이스크림도 맛있었는데, 진하고 달콤한 초콜릿 음료는 살짝 산미가 느껴지더라구요! 그 점만 살짝 호불호가 갈릴 듯 합니다.', 48, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '이곳은  여러번 지나가다 늘~~~ 사람들이 많길래 호기심에 들어가봤는데 역쉬~~~ 대기가 많은 이유를 알겠네요 넘넘 맛있는 빙수와 초코디져트가 짱입니다 자주 오고싶은곳 이에요', 18, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '진짜 진한 초콜릿 음료 노말로 먹었어요! 정말 진하고 맛있어요😍 사장님이 친절하게 설명도 잘 해주셔서 메뉴 고를 때 도움이 되었답니다! 리뷰 보면 웨이팅 있다는 말이 있어서 걱정했는데 오늘은 웨이팅 없고 자리도 넉넉히 있었어요~', 53, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '17도씨 초콜릿이 유명하다고 해서 찬바람 부는 계절이 끝나기 전에 방문했어요. 처음이니까 기본맛으로 했는데, 개인적으로 수제 핫초코를 녹여먹은 이력이 있어서인가 기대만큼 찐~하진 않았어서 매니아 맛으로 먹어볼걸 싶었어요. 츄러스도 조금 더 바싹 튀겼으면 더 취향이였을것 같아 아쉽...하지만 저 농도는 진짜다... 초콜릿 좋아하는 분께는 꼬옥 추천. 다음에는 꼭 초코아이스를 먹어보고 싶어요.', 81, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '직원에 화풀이하지말라 완전 감정적으로 답글 다셨던거 다 수정하셨네요. 친구가 가겠다면 뜯어 말릴거같네요. 주변 빙수맛집 많습니다. 다른곳 추천드립니다. — 덧붙입니다 안에들어갔을때는 3분이 되어있는걸 보고 들어갔고 대기 취소되었다는 카톡도 없는데 다음순차까지 대기해야할것같다 우리 시스템은 원래 그렇다 어쩔수없다. 처음부터 죄송한 내색 혹은 친절을 전혀 찾아볼수없게 말씀하셨어요. 직원분의 응대때문에 더 불쾌햇어요. 제가 어떤 화풀이를 했다고 하시는지 이해가 안되네요.다시 20분을 기다려서 들어갔구요. 씨씨티비 돌려보시고 확인 바랍니다. 제가 화풀이를 한 손님으로 모욕하시고 계시네요. 리뷰는 맛에대해서 말하고 저희말고 다 여중고생이였던 사실을 서술했구요 직원이 아니고 사장님이셨다면 굳이 할말 없구요.', 36, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '음료 종류가 많지는 않아요~ 정말 초콜릿 전문점입니다. 정말 유명한 진짜 친한 초콜릿 음료를 먹었는데, 신기한 게 단맛이 거의 안 느껴지더라구요. 그래도 어느 정도는 단맛이 나지 않을까 했는데 신기하고 놀랐어요. 상상했던 맛은 아니었지만 만족! 아이스크림은 정말 무난한 초콜릿 아이스크림이었어요. 초콜릿 음료와 세트로 주문한 츄러스는 아이스크림이랑 먹었어요. 달콤한 맛을 좋아하시는 분들은 음료보다 이쪽이 더 취향이실 것 같기도 하구요~ 온통 초콜릿이다 보니 입가심할 물도 함께 주셔서 감동...🥹❤ 재방문 의사 있습니다~', 63, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '인기가 너무 많아서 초저녁에 가니 이미 웨이팅마감이었어욥 ㅠ ㅠ 아쉬운 대로 진한초콜릿음료 따시게 테잌아웃해서 왔습니다 정말 진하고 맛있었어요 다음엔 진짜진한/진하고달콤한초콜릿음료들이랑 초코빙수까지 먹어보고 싶어여', 84, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '드디어 초콜렛으로 유명한 17도씨에 갔어요!! 초콜렛 소프트 아이스크림은 일반 아이스크림보다 훨씬 쫀득한 느낌이고 약간 젤라또와 아이스크림 중간 느낌?이었어요. 확실히 일반 초코 아이스크림보다 맛이 좀 더 밀도 있었고, 엄청 달지 않아서 물리지 않고 먹었습니다!', 57, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '원래도 좋아하던 집인데 요즘 진짜 진한이 핫하다 그래서 맛보러갔어요 처음맛보는 달달구리 신세계네요 온몸에 당 채워주는 맛이예요 사장님이 먹는법 친절히 알려주셔서 그대로 먹었더니 너무 맛있어요 한결같이 맛있는 곳입니다', 13, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '깔끔한 초코맛이라 좋아요 웨이팅이 길어서 홍대에 도착하자마자 웨이팅을 걸고 다른일보다 오는걸 추천... 대기 17팀은 1시간, 대기 29팀은 2시간 걸렸어요', 109, 20, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), 'sns에서 보고 와봐야지 했던 곳입니다. 진짜진한 초콜릿음료 노멀에 츄러스 추가 탄산수 추가 했어요! 탄산수 추가 안 하면 따뜻한 물과 함께 줍니다. 시나몬파우더는 뿌려져서 나오는게 아니라 취향껏 뿌려먹을 수 있게 통을 따로 주시더라구요. 매장에 따로 행거가 있어서 겨울철 롱패딩을 의자에 걸어뒀다가 치이거나 바닥에 떨어지는 일이 없어서 좋았구요. 가방을 담을 수 있는 바구니도 행거쪽에 있어서 가지고와서 의자 밑에 쏙 넣어둘수 있어 좋았습니다!', 32, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PARKING');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '초콜릿 맛이 진하고 풍미가 깊어서 좋았습니다! 전에 왔을땐 품절이었는데 오늘은 정신차리고 일찍가서 아이스크림 드디어 먹어서 소원성취 했어요!!👍👍', 6, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '지인짜 추울때 가보고싶었는데 매번 대기때문에 포기했던 17도씨... 날 풀려서야 먹어보다 앞에 8팀일때부터 30분정도 대기하고 들어갔어요 그냥 인스타 맛집 요론 느낌일줄 알았는데 생각보다 안에서 도란도란 대화 나누는 분위기라 따뜻한 분위기랄까 그래서 회전이 빠르진 않은거 같습니다ㅋㅋㅋ 유우명한 스페인 츄러스도 먹어봤었는데 탄산수에 생크림 조합까지는 좀 처음 먹어봐서 츄러스 하나를 아주 알차게 먹은 느낌에 만족스러움 그치만 특!별!히! 맛이 너무너무너무 있다 라고 하기엔 그냥 상상하던 맛있는 츄러스에 초코 맛이어서 대기 오래하면서까지 오지는 않을거 같슴둥 갠적으로 탄산수를 좋아하지는 않는지라 생크림 추가를 더 추천합니다!', 122, 25, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '웨이팅 걸어두고 다른 카페 있다 왔지만, 초콜렛 만큼은 정말 진심인 곳. 아이스크림까지 먹을 수 있어서 좋았어요. 핫초코는 매니아와 일반 두가지 모두 먹어봤는데 단맛의 정도 차이라 엄청난 차이가 있지는 않았습니다. 특히 츄러스랑 먹어서 맛이 좋았어요. 케잌은 시트가 정말 촉촉하고 부드러워서 맛있었습니다.', 37, 5, 'GOOD', SYSTIMESTAMP);
