INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '드디어 와 본 17도씨~~~~ﾟ+(人・∀・*)+｡♪ 정말 초코음료에 츄러스 조합 궁금했구요, 꿈꾸던 그 맛이라 아쥬 행복했습니당 제 추천은 초코츄러스 세트 노말에 브랙퍼스트 티 조합! 아이스로 먹으면 초코가 너무 헤비할때 싸악 씻어줍니다ㅎㅎ', 1, 3, 'GOOD', SYSTIMESTAMP);
