INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '진한 초코음료와 추러스 먹으러 왔는데 위에 자신이 없어서 한잔은 우유를 시켰더니 초코음료 양이 엄청 적더라구요 ㅎㅎ따뜻한 물도 챙겨주시니 다음엔 1인 1잔해스 먹어야겠어요! 겨울엔 짧은 기간 판매하신다는 초콜릿 아이스크림도 맛났는데 콘이 다 떨어져서 컵으로 먹었네요. 맛있었습니다! 위가 좀더 나아지면 한번 더 재방문 하려구요 ㅎㅎ', 109, 20, NULL, SYSTIMESTAMP);
