INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '초코 노멀버전으로 먹었는데 다음번엔 메니아 도전해보고싶어요! 정말 첫입 딱 먹자마자 온몸이 풀리는 듯한 그 녹진한 느낌 너무 좋았어요 으슬으슬할때 한 입 먹고싶다고 할까? 그리고 입가심용 탄산수 꼭 추가하세요. 탄산수까지 존맛!', 40, 2, 'GOOD', SYSTIMESTAMP);
