INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '메뉴판에 발로나라고 브랜드 적혀 있고 채식주의 핫/아이스 다 구비해 놓은 소중한 초콜릿 가게입니다.. 이사 가기 전에 갔는데 야외석에서 공원도 보이고 좋았어요! 이사 간 곳은 좀 더 골목이에요~', 12, 6, 'GOOD', SYSTIMESTAMP);
