INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '언제나처럼 사람이… 넘칩니다. 진한 초콜렛 맛을 느낄 수 있으나, 진하기 때문에 호불호는 존재할 수 있다 생각합니다. 요즘은 공휴일 등에 방문하면 기본 2-3시간 대기를 각오해야 할 가 같습니다', 41, 0, NULL, SYSTIMESTAMP);
