INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '매니아 초콜릿에 생크림에 츄러스 먹었는데 정말 후회없는 맛이에요.. 같이 주시는 따뜻한 물 마시면 입이 싹 정리돼서 계속 먹을수 있어요ㅋㅋㅋ😊😊', 72, 17, 'GOOD', SYSTIMESTAMP);
