INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '친구 추천으로 갔는데 다행히 평일이라 자리가 있었어요 이날도 사람들 많았는데, 주말에는 웨이팅 있다고 들어서그런지 운이 좋았다는 생각을 했죠ㅋㅋ 초콜릿 전문점이라 그런지 음료도 맛있어요👍 다른 테이블보니 다른 인기메뉴를 시키는데, 전 배불러서 음료만 마셨어요ㅠㅜ 다음에 가면 다른것도 먹어보려구요 음료도 진짜 맛있어서 추천해요!', 44, 0, 'GOOD', SYSTIMESTAMP);
