INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '매니아 기준 드림카카오72%? 82%? 정도 녹인 것 같은 진함이고 산미가 좀 있는 편이다 생크림이 맛있고 탄산수가 입안을 씻어줘서 추가하는 것을 추천', 38, 10, 'GOOD', SYSTIMESTAMP);
