INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '생각보다 초코음료의 양이 적어서 아쉬웠지만 달달하거나 씁쓸한 정도를 선택할 수 있어서 여유롭게 시간 보내고 싶을때 있기 좋은 곳입니다~ 눈이 오는 날이어서 밖을 보며 여유를 즐길 수 있었어요~', 82, 17, NULL, SYSTIMESTAMP);
