INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '초콜릿 음료가 정말 진하고 맛있어요. 얼그레이초콜릿 음료도 시켜봤는데 괜찮네요. 하나씩 파는 초콜릿도 맛있고 웨이팅만 없으면 자주 오고 싶은 곳이에요.', 136, 53, 'GOOD', SYSTIMESTAMP);
