INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '초코렛 빙수와 초코 아이스크림을 시켰다 초코렛빙수는 처음 접해보는 비주얼이라 뭔가 신선한 느낌이 들어 좋았고 아이스크림 역시 진한맛이 느껴졌다 매장은 그리 크지 않으며 초코렛 맛을 제외한 특별한 맛은 없다 초콜릿을 좋아하는 사람이라면 자주 가겠지만 개인적으로는 자주 찾지 않은 메뉴인것 같다 전반적인 가성비는 무난하다', 353, 99, NULL, SYSTIMESTAMP);
