INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '초콜릿빙수 오리지널로 시켰더니 생초콜릿과 아몬드 슬라이스가 토핑으로 나왔습니다. 달콤한 초코 얼음 덕분에 끝까지 밍밍하지 않아요. 아이스초코도 진하고 달콤쌉싸름해서 맛있습니다.', 129, 21, 'GOOD', SYSTIMESTAMP);
