INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '어후…이 걸쭉함을 맛 보려고 서울 간 김에 가봤습니다. 속이 아파서 한 잔만 마시고 왔는데 다음엔 일찍 가서 품절된 메뉴들도 먹어보고 싶네요ㅠㅠ', 1, 2, NULL, SYSTIMESTAMP);
