INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '웨이팅도 좀 있는 듯 해서 쵸콜릿만 포장주문 했는데 직원분이 두명 있으신데도 불구하고 쵸콜릿 포장까지 꽤 기다렸습니다 거한 포장을 바란건 아니지만 총5개 구입했는데 그냥 비닐 하나에 한꺼번에 담아주시더라구요 저렴한 쵸콜릿은 아닌데 말이죠 입소문이 난 만큼 조금은 서비스에 신경 쓰실 필요는 상당하다고 봅니다', 103, 26, 'BAD', SYSTIMESTAMP);
