INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '손님대응이 별로였어서 또 가고싶진 않네요. 일행보다 일찍도착했고 자리가 없어서 밖에서 좀 대기했습니다. 3명이었기에 4인석이 나서 가방을 두고, 제 음료를 먼저 주문 했습니다. 앞팀 이용하고 자리 정리가 안돼있던 테이블이라 휴지에 물을 묻혀와서 덕지덕지 붙은 초코를 닦아내고 있는데 사장님으로 보이는 분이 오셔서 몇 분 이세요, 언제 오시나요, 얼마나 걸리시나요, 끊임없이 질문을 하시더군요. 답변 다 해드리니 그냥 뒤돌아서 가십니다. 그 후에 5분가까이 서서 물뭍힌 휴지로 초코 계속 닦아내고 있으니 그제사 와서 테이블 닦아드리겠다 합니다. 혼자와서 4인테이블 차지하는거 별로인거 이해합니다. 근데 순서가 그게 맞는건가요? sns에 뜨길래, 유쾌한 경험이 아니었던게 생각났네요.', 90, 15, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '더위에 녹아내려갈즈음 찾아낸 보석같은 초코빙수! 파는 곳!! 매장도 진짜 시원하고 초코의 진한 맛이 넘나 잘 느껴져서 진심 한톨도 냄기지 않고 흡입했어요 ㅋㅋ 초코빙수 먹다가 토핑들 넣어서 먹으라했는데 그냥 먹어도 너무 맛있더라구용! 그렇다고 토핑 안넣고 드시면 안되여~ 토핑 넣으면 넣는대로 핵존맛😋', 17, 3, 'GOOD', SYSTIMESTAMP);
