INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '초콜릿을 매우매우 좋아하는 친구에게 추천받아서 가본 곳이에요. 초콜릿 음료는 진하고 달콤한 걸로 주문했어요. 메뉴가 상세해서 고르기 좋았어요. 그리고 중국 차를 이용한 초콜릿은 처음봤는데 맛이 상당히 좋았습니다. 향도 그렇구요. 선물용으로도 좋을 것 같아요. 사장님이 매우 친절하십니다.', 102, 21, 'GOOD', SYSTIMESTAMP);
