INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '초코 좋아하는 친구 추천으로 갔다가 초코음료를 너무 맛있게 먹어서 이번엔 다른 친구들이랑 초코빙수, 초코아이스크림 먹었는데 초코덕후들이 찐으로 행복해했어요...♡', 15, 0, 'GOOD', SYSTIMESTAMP);
