INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '촉촉한 초콜릿 케이크(6500원)과 아이스 아메리카노(5500원)를 시켰다 초콜릿 전문점이지만 케이크의 초코맛이 너무나 연했다. 꾸덕하고 강한 초코맛을 기대한다면 케이크를 추천하지 않는다. 아메리카노는 산미가 약간 있었다. 무난무난 다음에 간다면 꾸덕한 초코음료를 먹어볼 예정', 3, 6, NULL, SYSTIMESTAMP);
