INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '손님이 대빵 많아요 초콜렛 관련 달달구리 먹으려구 드갔다가 만석이라서 초콜릿 두 개만 사가지구 나왔어용 유자 가나슈랑 코코넛 둘 다 맛있고 필링이 진~한 편이에요!', 47, 3, 'GOOD', SYSTIMESTAMP);
