INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '이 장소를 알게 된 후로 네 번째 방문. 집에서 거리가 꾀 있는 편인데 식사 후에 디저트 겸 이거 하나를 먹기 위해 차 타고 30분이 넘는 거리를 운전해왔다. 다 먹는데는 10분도 안걸리지만 자꾸 자꾸 생각나는 맛. 겨울에도 쭉 계속 만들어 주세요ㅜㅜ', 4, 8, 'GOOD', SYSTIMESTAMP);
