INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '초콜릿 음료 진지하게 너무 맛있어요 여태 먹었던 초코 음료는 그냥 초코향 설탕물처럼 느껴질만큼 찐하고 넘 맛있습니다 근처에 살았으면 매일 가고싶어요', 12, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '초콜릿이 막 끔찍하게 단맛이 아니라 고급스럽고 적당히 달아서 좋았어요!ㅎㅎ 초코빙수는 초코우유로 만든 우유빙수 같은 느낌이에요~ 혀에 닿기만 해도 사르르 녹는 부드럽고 폭신한 우유얼음이 가득한데 처음부터 끝까지 모두 같은 맛과 식감이라 아쉬웠어요. 초코볼이나 아몬드 토핑을 함께 주시긴 했지만 빙수 자체는 너무 같은 단맛의 연속이라 먹다보니 좀 질리더라고요ㅠ 함께 주문한 수제 초콜릿은 기본 밀크는 평범했지만, 얼그레이나 차이티는 차 향이 단맛과 어우러져 정말 좋았고 커피랑 잘 어울릴 것 같았어요. 랍상소우총은 호불호가 갈릴 맛인데 독특하고 스모크 향이 단맛을 중화시켜줘서 개인적으로 맛있었습니다^^ 빙수 말고도 아이스크림을 많이들 주문하시던데 다음에는 소프트 아이스크림을 꼭 먹어보고 싶네요', 41, 8, NULL, SYSTIMESTAMP);
