INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '빙수만 생각하고 가서 빙수만 먹고 온 게 아쉽네요. 빙수 맛있었어요. 다음에는 음료와 다른 디저트도 먹어보고 싶어요. 빙수가 엄청 금방 밑으로 꺼져요ㅋㅋ', 20, 0, NULL, SYSTIMESTAMP);
