INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '초콜릿 맛있어서 15종 다 샀지만 테이블 그렇게 작은거 두고 컵 카운터에 갖다주지 말라는 거 좀 말이 안 됨. 일 줄이고 싶으면 아예 테이블 빼세요.', 27, 7, 'BAD', SYSTIMESTAMP);
