INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '초콜렛 맛은 말할것두 없어요.최고입니다. 믿고 먹는 초콜렛!! 연말 지인들에게 줄 최고의 선물 잘 챙겼어요!!  무엇보다도 사장님의 친절한 설명 최고예요!!!!', 47, 2, 'GOOD', SYSTIMESTAMP);
