INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '발렌타인데이 초콜릿 구매했어요. 친절하셔서 기분 좋게 구매했네요. 받는 사람도 좋아했음 좋겠구요. 사면서 둘러보니 초콜릿 이용한 다양한 음료가 많던데 나중에 꼭 방문해서 맛봐야겠어요. 흔한 음료가 아니라 더 끌리더라구요.', 16, 2, NULL, SYSTIMESTAMP);
