INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '실력자 쇼콜라티에님 혼자 계시는 것 부터가 간지. 직접 만들어주시는 초코 음료는 진짜... 이 돈 주고 먹어도 되나? 싶게 고급스럽고 맛있다 이 달의 초코음료 라는 매 달 바뀌는 메뉴와 시즌메뉴가 정말 독특하고 맛잇다❤️ 아ㅏ아아아ㅏㅏ 진짜 나만 알고싶네........', 32, 7, 'GOOD', SYSTIMESTAMP);
