INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '#연남동초코렛 #카페 #홍대입구 #초콜렛 강추하는 장소입니다. 최애 초코음료 카페 매달 이달의 음료로 새로운 메뉴 계발도 해주시고 초코케익 초코마카롱 초코렛 초코음료 다다다 맛있어요.', 62, 18, 'GOOD', SYSTIMESTAMP);
