INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '17도씨'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '초콜렛이 정말 맛있는 17도씨입니다 여른 시즌메뉴인 초코빙수 꼭 드세요! 원래 오리지널 버전은 없어지고 더 작고 살얼음이 느껴지는 빙수가 아쉽긴하지만 그래도 맛있긴합니다 ㅋ 금액도 좀 비싼 듯 하지만 그래도 맛이 있으니..ㅋㅋ 아메리카노랑 찰떡입니다~ 핫초코랑 초코아이스크림도 맛나요!', 36, 10, 'GOOD', SYSTIMESTAMP);
