INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이고 수플레 합정본점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '커피도 수플레랑 어울리고 오리지널 수플레 먹어봤는데 계란 모양이 귀엽고 크림도 맛있어요. 다음엔 크렘브륄레 수플레도 먹어보고 싶어요.', 11, 1, 'GOOD', SYSTIMESTAMP);
