INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이고 수플레 합정본점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '친한동생과 식사 후 방문했어요 이고 수플레, 이고커피, 아이스 아메리카노 주문했어요 이고커피는 약간 고소하면서 맛은 무난했어요 수플레 맛집답게 푹신하고 베이컨의 짠맛이랑 계란의 크리미한 맛이 적절하게 잘 어울려서 맛있었어요', 75, 14, 'GOOD', SYSTIMESTAMP);
