INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이고 수플레 합정본점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '수플레가 유명하다고해서 가봤어요~ 가게는 크지 않았고 수플레 주문이 계속 들어오는지 반죽기(?)가 계속 돌아가더라고요~ 주방 바로 앞에 앉아서 조금 시끄럽긴 했는데 맛은 있었습니다 계란 냄새 날까봐 걱정했는데 별로 안나더라고요 ㅎㅎ 음료도 괜찮았습니다! 같이 간 친구가 먹은 시그니처 라떼도 괜찮았다고 해요 ㅎㅎ', 84, 18, 'GOOD', SYSTIMESTAMP);
