INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이고 수플레 합정본점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '수플레 맛집~ 합정역부근에 위치한 EGO.  크림브휠레 수플레가 사르르 입안에 달콤하게 녹아서 기분이 UP됨^^ 사장님도 친절하시고 커피도 맛있어요~매장안이 그리 넓지 않고 포근하고 아늑한 느낌.', 90, 12, 'GOOD', SYSTIMESTAMP);
