INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이고 수플레 합정본점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '수플레가 다른 가게보다 훨씬 크고 퐁실해요 ㅠㅠ 진짜 미친놈이에요,, 여기 왔는데 수플레 안 드시면 진짜 후회하실 거예요.. 진짜…미친놈이거든요;; 딸기라떼도 딸기청?을 많이 넣어주셔서 우유 맛 1도 안 나고 진짜 존맛이에요 ㅠㅠ 마시면 감동 조져요 ;,,,', 82, 15, 'GOOD', SYSTIMESTAMP);
