INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이고 수플레 합정본점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '두번째 방문인데 후기는 처음써요 여기만큼 맛있는데 못찾았어요 자리는 부족하지만 수플레가 진짜 존맛탱 …!̤̫!̤̫ 딸기라떼는 딸기우유 맛이에요', 64, 18, 'GOOD', SYSTIMESTAMP);
