INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이고 수플레 합정본점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '카페 내부 분위기도 좋고~! 특히 ego카페 팬케이크 크림브륄레 수플레 팬케이크 너무 맛있어요~ 세상 부드러운 식감에 커스터드크림 듬뿍 들어있어서 좋았고 팬케이크 속 빵이 정말 입에서 녹았어요. 빵 자체를 잘 구워주셔서 완전 부드럽고..중간중간 설탕 씹히는데 달달하면서 담백, 고소하니 너무나 맛있었어요. 로제 에이드도 시원하면서 상큼하니 더운날씨에 최고~!! 잘 먹다 갑니다.', 32, 5, 'GOOD', SYSTIMESTAMP);
