INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이고 수플레 합정본점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '수플레팬케이크 먹으러 왔어요!! 합정쪽에서는 처음 먹은 수플레였는데 커피랑 같이 먹으니까 정말 맛있었어요!! > 수플레 위에 노른자 같은거 달달할 줄 알았는뎈ㅋㅋㅋ 시큼해서 놀랐어욬ㅋㅋㅋ > 근데 진짜 맛있어서 다 긁어먹고 왔어요(''-''*  )', 33, 5, 'GOOD', SYSTIMESTAMP);
