INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이고 수플레 합정본점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '매장 내부 적당히 테이블 있고 작은 야외 테이블도 있었어요. 야외에서 애견동반 가능해서 요즘같은 따듯한 날씨에 데려가기 좋을 것 같아요! 디저트가 달달해서 맛있고 음료도 괜찮았습니다 :)', 0, 8, 'GOOD', SYSTIMESTAMP);
