INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이고 수플레 합정본점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '합정역 갈때마다 꼭 들리는 카페 다른카페보다 원두향이 깊고 늘 청결하고 따뜻한 카페 분위기에끌려 와이프랑 연애초기부터 지금까지 이용중입니다. 남사장님 늘~친절하게 서비스해주셔서 방문할때 마다 기분이좋아지는 카페입니다^^ 커피 & 디저트 너무 맛있네요~ #합정카페 #합정역 5번출구 #맛있는 커피', 12, 0, 'GOOD', SYSTIMESTAMP);
