INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '배스킨라빈스 홍대상상마당'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '우쥬라이크봉봉! 맛있어요ㅎㅎ 생각보다 아몬드봉봉 맛은 느끼지 못했는데 엄마는외계인 베이스 초코맛이라 초코 좋아하시는 분들은 무조건 추천', 23, 6, 'GOOD', SYSTIMESTAMP);
