INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '배스킨라빈스 홍대상상마당'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '쪄죽어가던 중 당장 시원한 게 마셔야 할 것 같아 바로 앞에 있는 배라에 들어왔어요... 에어컨을 아주 빵빵하게 틀어놔서 너무 시원해서 십 분 앉아있었는데 땀이 다 식엇뜸 아이스크림 가게에 걸맞은 시원한 온도 아주 좋아요👍', 31, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '배스킨라빈스 홍대상상마당'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '테이블이 더럽고 직원들 유니폼 앞에 아이스크림, 시럽 잔뜩 묻어있고 바빠도 그렇지 말투가 날카롭네요 사람 많은 매장이라 그런가 정신없습니다 아이스크림 하나먹기 불편하네요', 87, 15, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '배스킨라빈스 홍대상상마당'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '제발 키오스크좀 늘려주세요ㅠㅠ 외국인에 맛고르기에 할인 적립 결제 등등 하면 한팀당 5분 이상 걸리고 줄이 너무 길어요 키오스크 자체의 불편함도 있고(주문처리가 복잡함)개수자체가 손님에 비해 너무 적어요', 6, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '배스킨라빈스 홍대상상마당'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '컵아이스크림이 꼭 와플 아이스크림이라 비싸서 좀 아쉽ㅜ 가끔 그냥 와플아닌거 깔끔하게 먹고싶은데ㅜ 그래도 아이스크림 맛은 괜찮아여ㅎㅎ', 61, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '배스킨라빈스 홍대상상마당'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '홍대 갔다가 아이스크림이 먹고 싶어서 방문하게 됐어요ㅎ 수도권에만 있는 시그니처 라길래 먹어봤는데 생각보다 그냥 그랬네요ㅋㅋㅋ한번쯤 먹어 볼만해요ㅎ', 28, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '배스킨라빈스 홍대상상마당'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '🎈추천 메뉴 -자모카 아몬드 훠지 🎈매장 특징 1. 불편한 외부 화장실: 상상마당 건물 이용, 비번 없음 2. 달달한 매장 냄새: 팝콘 향 3. 주문 대기 시간 적음: 키오스크 2대, 직원 3명 🎈TMI 와플 신기해서 먹어봤는데 걍 과자같음', 54, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '배스킨라빈스 홍대상상마당'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '지금까지 방문한 배스킨 매장 중에 가장 불친절했어요~ 다신 가고 싶지 않네요. 주문을 하고 계속 기다리는데도 아이스크림 케이크 정리한다고 아직 준비중이라고 말하고, 테이블을 닦아주지도 않고, 휴지를 요청해도 말도 없이 어디 있는지만 가리키고..  사장님은 안 계신 것 같았지만 직원 교육 잘 시키셔야 할 것 같아요.', 32, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '배스킨라빈스 홍대상상마당'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '오래간만에 먹으니 너무 맛있네요 일본인 친구랑 같이 가서 가게 안에서 먹고싶은데 가게 안이 자리가 몇자리 없어서 금방 차고 사람이 너무 많아서 키오스크로 주문도 꽤 많이 기다렸습니다 먹고가기로 주문했는데 가게 안에서 아무리 기다려도 먹을수가 없어서 직원에게 밖에서 먹을테니 수저랑 그릇을 일회용으로 (다회용 사용의 그릇과 수저였기에) 바꿔달라고 하니 스텐레스 수저를 개수대에다가 화내듯이 던지시고 짜증나는 표정 지으면서 목소리만 상냥하게? 말하시더군요..같이 갔던 일본인 친구도 놀래서 자신이 일본인이어서 화내는줄 알더라고요 외국인도 많이 오고 가는 매장에 바쁜건 알겠지만 말이 안통하는 매장인 만큼 표정 관리, 물건 집어 던지는 일이 없게끔 직원관리 좀 부탁드립니다 같은 한국인으로서 너무 부끄럽네요…', 43, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '배스킨라빈스 홍대상상마당'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '베스킨은 화장실이 없는 건물이라네요. 건물에 화장실이 없어서 길건너 상상마당으로 가야하는 불편함이 있네오. 화장실없는 건물이라니 23년도에도 이런건물이 있네요', 55, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '배스킨라빈스 홍대상상마당'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '사람이 굉장히 많았습니다. 자리가 직원분들 일하는곳에서 안보이는 곳에 있더라고요. 그래서인지 테이블 등 청결하지 못하더라고요.', 47, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '배스킨라빈스 홍대상상마당'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '아몬드 봉봉, 슈팅스타, 피나콜라다(시즌한정) 봉봉(5.0), 슈스(4.0), 피나콜라다(1.5) 봉봉은 여지없이 1등 슈스는 옛날이 더 맛있음 피나콜라다는 대실망 파인애플맛이 너무 강함', 39, 4, 'BAD', SYSTIMESTAMP);
