INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '배스킨라빈스 홍대상상마당'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '원래 배라에선 아이스크림만 먹었는데, 블라스트를 주문해서 먹게 되었어요! 맛있더라고요?! 음료도 맛있는 배라,, 추천해요 :-)⭐️', 6, 4, 'GOOD', SYSTIMESTAMP);
