INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '종종 방문 하지만 리뷰는 처음이네요. 자리가 넓고 다양하게 있어요. 의자와쇼파 말고도 계단식 자리도 있어서 취향에 맞게 앉으면 돼요! 사람이 많긴 하지만 그래도 한두자리는 꼭 남어 있어요~ 혼자 끄적거릴 일이 있어 최근에는 러저브 자리에 앉아서 먹었는데, 부담스럽지 않고 괜찮아요! 옛날 옛날 초콜릿 주었을 때 좋왔는데 왜 없앨까요..~ 최근엔 양송이스프도 없어졌던데 제가 좋아하는것들만 사라져서 ㅜ 개인적으로는 속상 하네요;', 44, 10, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '매장이 넓고 쾌적해요.계단식으로 테이블이 있어서 한결 넓어 보여요.모바일상품권으로 사이렌오더하면 12월3일에 1+1 증정프로모션이 있네요.잘 활용했어요.친절한 직원분 도움받아했어요.', 39, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '홍대입구에서의 여유를 찾아봅니다. 다크초콜릿의 원두를 선택해서 먹으니 더 진한 느낌이 아주 좋습니다. 원두를 선택 할 수 있다는게 정말 좋은곳 입니다. 이곳을 추천 드립니다.', 13, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '스타벅스가 매장마다 다른 느낌인데요 이곳은 확트인 느낌이라 복잡하다는 느낌보다 편안한 느낌이었습니다 오늘의  커피를 주문했는데요 시원하고 향이 좋은 커피를 직접 내려주시는 직원님의 친절이 기분 좋은 매장으로 기억이 되는곳입니다. 덕분에 비즈니스 미팅도 잘하고 왔습니다', 16, 4, 'GOOD', SYSTIMESTAMP);
