INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '리저브 원두로 먹었는데 맛있었어요! 치즈케이크도 맛있었습니다~매장에 테이블이 다양해서 좋았어요 화장실은 상가 공용화장실이라 별로였어요ㅠ', 17, 10, 'GOOD', SYSTIMESTAMP);
