INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '서비스가 제가 무료로 이용하는 사람처럼 대우해서 정말 불만입니다. 저와 직접 대화하시는 것도 아니고, 60세인 저희 부모님께 예의 없이 대하는 점이 정말 불만스럽습니다. 제가 외국인이라서 그런지도 모르지만 고객에게 이런 식으로 서비스를 제공하는 것은 옳지 않은 것 같아요.', 94, 21, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '직원분들 넘넘 친절하시고😊😁💝 시음커피(?) 2번이나 받았어욬ㅋㅋㅋㅋ 들어왔을때 톨사이즈로 주문했는데 다행이에요🤣🤣🤣 아침에오니 사람이 별루 없어서 조용해서 넘넘 좋아용😆👍❤️‍🩹', 106, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '스벅 홍대입구역사거리점은 매장 인테리어가 고급스러워 계단위쪽에 앉는 독특한 장소가 있기도 해요. 공부하기도 좋고 대화나누기도 좋은 공간 같아요. 달닳한 돌체라떼와 아이스카페바닐라라떼도 맛있었어요. 이상 평일엔 서초동 일개미, 주말엔 가평신상글램핑 🌸 글램탐다오🌸 지기의 리뷰였어요.70미터 길이의 풀엑세스 온수풀, 프라이빗한 야외 개별자쿠지가 있는 글램탐다오도 관심부탁드려요 💕', 398, 61, 'GOOD', SYSTIMESTAMP);
