INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '파트너님들이 컨디바(?)도 자주자주 치우시고 한잔 더 주문했는데 슈크림라떼에 슈크림휘핑 많이주셨어요 ㅎㅎㅎㅎ혜자롭다😍😍💛 직원이 친절해요~~', 28, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '사람이생각보다많아서 조그만테이블에 앉게됨..전체적으로  콘센트는 없는듯하다. 리저브매장이라 고급원두를선택가능하다 추가금액이있으며,마셔본결과 (저가형아닌)일반카페수준의 원두임. 기본원두는 강배전탄원두...', 11, 1, NULL, SYSTIMESTAMP);
