INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '오픈 직후 방문인데 매장테이블에 먼저 손님이 디저트 먹다 설탕코팅? 흘렸는지 하얀게 있고 쓰레기통 휴지가 꽉 찼네요..어제꺼인가? 그리고 카운터 직원분 서비스가 그냥 그래요', 109, 22, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '리저브 매장은 첨인데 잘 몰라서 추천 받아서 주문했구요. 비싼만큼 맛은 있었고 매장도 일반 스벅이랑은 조금 달라서 특이하고 좋았어요.리저브 메뉴 주문한 사람만 따로 앉을수 있는것도 특별했고 바리스타 분과 대화도 나누고 원두 내리는 것도 보고 즐건 경험이었음.', 18, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '매장이 굉장히 이뻐요!!! 계단식으로 되어있어서 이쁘지만 계단식 의자는 딱딱하고 등 기댈 수 없고 탁자도 좁아서 아쉬워요. 소파 좌석은 좋아요. 다른 스타벅스보다 직원분들이 친절한 것 같아요🫶🏻', 84, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '새로운 메뉴 푸른용 얼그레이케잌.아메리카노와 잘 어울림.R점이라 넓찍하고 한가한편. 그러나 자리는 없다는거.중앙 테이블앉았는데 쫒겨남 ㅜㅜ 자리가 없어서 앉았고 운영안하는줄.. 안내부족인듯함.', 37, 8, 'BAD', SYSTIMESTAMP);
