INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '스타벅스 기프티콘이 있어서 들어왔다가 클래식 밀크티가 새로 나온 듯하여 밀크티 러버로서 주문했어요. 어쩌다 보니 이번주에 밀크티만 세 번째인데, 새로 나온 클래식 밀크티 맛이 부드럽고 잉글리시 브렉퍼스트 베이스라 진하고 괜찮네요. 다음에 또 먹게 된다면 조금만 덜 달게 주문할 것 같아요.', 4, 7, 'GOOD', SYSTIMESTAMP);
