INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), 'DT점 좋아요. 직원도 상냥하고 친절해요. ^^ 높은자리 쇼파 앉아보고 싶었는데 자리가 안나더라고요. 디저트 맛나요. 하...그런데 앞자리 학생 양말 벗고 의자에 다리 뻗는건 좀 아닌듯.. 배고파서 정신없이 먹다가 앞에 보고서는 식욕이 뚝 떨어져서 더는 못먹겠더라고요. 인간이라면 밀폐된 공공장소에서 적어도 👟은 벗지 맙시다. 이런 🍞같은 🐕매너🤬😼😡', 65, 17, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '리저브 메뉴 <나이트로> 질소투입으로, 얼음 없이도 시원하고 목넘김이 편안하다. 만들어주시는 과정 보면서 신기했음 미니 파이도 맛있었네요 리저브 No.10', 50, 10, NULL, SYSTIMESTAMP);
