INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '한적하고 직원분들이 전부 친절하세요!! 다만 혼자 앉아 공부할만한 마땅한 자리는 없어요 ㅜㅜ 계단식으로 되어있는 곳, 긴 테이블로 된 곳(리저브 한정)만 있어서 대화하기 좋을 것 같아요~!', 8, 6, NULL, SYSTIMESTAMP);
