INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '좌석수가 넉넉하면서도 내부 분위기가 유니크합니다 커피맛도 항상 좋고 파트너분들이 정말 친절하십니다 개방감 좋은 유리창으로 홍대거리를 구경할 수 있어 좋아요', 54, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '한가롭고 여유로운 스벅R점.다른곳은 도떼기시장같고 시끄럽고 도서관처럼 자리차지해서 놋북쓰던데 왜 한가한가 했는데 이곳은 콘센트가 없다는거. 와~~~넘좋다.럭셔리하다.자주 와서 여유롭게 차한잔 해야겠다', 18, 6, 'GOOD', SYSTIMESTAMP);
