INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '무엇을 시킬까? 고민하는 고객을 외면하지 않고 먼저 말을 걸어주는 친절함.  많은 질문에도 미소를 잃지 않는 자상함 . 메뉴를 골랐으나 그 맛에 의구심을 갖는 고객에게 확신을 주는 냉철함. 손은 바삐 움직이면서도 주문 업그레이까지 완벽하게 끝내는 ... 서교동에서 가장 갓벽한 스타벅스 May님💎💎💎💎💎', 30, 9, 'GOOD', SYSTIMESTAMP);
