INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '리저브 매장이라 음료 다양해서 조흠. 근데 자리가 대부분 불편해욤. 계단식 자리는 매우 허리 나가지만 자리 없어서 걍 앉아야함', 46, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '리저브매장 , 역시 넓고 쾌적하고 고급져요~ 가끔 오는 곳인데 리뷰는 처음 써요~ 리저브바닐라라떼 맛있구요~ 함께 주는 초콜릿도 고급지고 고소하면서 맛나네요~ 직원분도 친절하셔서 좋습니다. 주차가 좀 힘든데 , 건물 뒷편에 공용주차장 있어요~', 39, 5, 'GOOD', SYSTIMESTAMP);
