INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '리저브 텀블러 구입하고 받은 무료음료쿠폰 사용하러 옴. 근데 쿠폰바코드가 많이 지워져있었음 더지워지기전에 사진으로 찍어놨던거 보고 쿠폰번호를 불러주겠다고 하니 사진은 안된다고 함 실물이 있어야한다고 함  그래서 바로 지갑에서 꺼내서 보여줌 사진으로는 다른사람꺼 몰래 가져와서 쓸려고 할 수 있어서라고 함. 그런논리면 영수증도 마찬가지 아님? 내가 남의것 몰래 훔쳐다가 사용하는 인간으로 보였나봄.', 11, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '여성 직원분이 정말 친절하세요. 추천해주신 메뉴로 먹었는데 맛있네요.:) 근처 방문할 때 스타벅스는 요 지점으로만 올 것 같아요.', 56, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '오더 실수로 받으셔서 난감, 프리퀀시 물어봐주는것도 잊지마세요, 권하는건 정상 임,일부러 안하나? 기프티콘 쓰고 잘못 오더받아서 나중에 또 결재 그런데 프리퀀시 묻지않음 안경쓰고 등치큰 포스찍는분 ㅠ', 43, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대입구역사거리R점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '아이스얼그레이바닐라티라떼 돌체시럽 3으로 했는데도 달아서 시럽 좀 더 빼도 괜찮겠다 싶었네요 직원분들 너무 친절하시고 좋았습니다.', 25, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '예쁜 시로츄 체키가 너무 마음에 드네요ㅎㅎ 원격 체키가 아니라 실제로 보고 싶습니다ㅋㅋㅋ 이제는 오마이 왕국 공무원이 되셔서 매일 출근하시군요. 금요일에는 주간, 야간 당직도 서신다니... 너무 감동적이네요ㅠㅠ 정년까지 쭉 출근해주세요', 24, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '코하루 여신님의 마지막 졸업식을 함께할 수 있어서 너무 행복했습니다. 앞으로 갓반인으로 돌아가셔서 행복하게 지내셨으면 좋겠습니다ㅎㅎ 위드하트에서 마지막 졸업까지 함께 할 수 있어서 저도 너무 행복했습니다.', 14, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '처음 가보는 메이드 카페! 아이랑 방문해서 낯설고 걱정되었는데요~ 메이드님들이 모두 친절하게 대해 주셔서 기분 좋게 방문할 수 있었어요. 아이도 신기한 듯 재미있게 놀다왔습니다. 음료도 특이하고 맛있고 이색카페로 놀러가기 딱 좋아요. 다음번에는 집사카페도 가보고 싶네요~', 49, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '이야~ 시야와세~ 근처에 업무가 있어서, 업무 끝나고 저녁 시간에 오마이에 들릴 수 있었습니다. 시로님과 체키, 역체키, 샤메를 남길 수 있어서 즐거운 시간을 보낼 수 있었습니다ㅎㅎ 오늘은 특별히 시로님이 허락해줘서, 페니님과도 체키를 남길 수 있었습니다. 체키 스타일에 중력 차이가 정말 큰 것 같네요ㅋㅋㅋ', 67, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '대부분 친절 유쾌하셨는데 딱 아라 라는 분만 태도도 말투도 너무 건성건성이라 당황스러웠어요... 아까 좌석안내때 제 이름 들으셨죠? 하고 명함에 자기 이름만 쓰고 바로 자리 뜨시더라고요 (참고로 사진은 다른 메이드 분 명함입니다) 웃음기가 전혀 없으시고 손님인 제 말투가 더 친절해서 놀라웠어요. 사실 메이드카페는 먹으러 가기보단 그곳 특유의 특별한 문화와 컨텐츠를 즐기고 싶어서 가는거잖아요...? 대단한 대접 원하는 것도 아니고 적당한 친절도 못느끼고 간다는게 신선한 경험이었네요... 다른 분들은 다 좋았습니다', 64, 13, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '홍대 메이드카페에 다녀왔습니다 정말 하고 싶은 말이 많은데 아래 링크로 들어오시면 다양한 정보를 얻으실 수 있어요 . . https://m.blog.naver.com/gmltjddl0927/223975132118', 89, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '제가 거기서 히비스커스 음료를 시켜서 마셨는데, 맛있어서 힘이 났어요. 그리고 메이드들이 그림이 잘 그리네요. 캐릭터 하나 제시해 주더니, 거의 똑같이 그려줘서 놀랐어요. 그래서 오마이! 갓 추천합니다.', 34, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '오랜만에 방문하니 정말 새롭네요! 오늘은 마음 편하게 잠들 수 있겠네요! 그리고 이젠 평일에 와도 주말급의 혜택을 받을 수 있어서 정말 좋다고 생각하구요! 저는 집사카페에 가는것도 정말 좋아하는데 이런 소소한 영수증 이벤트까지 해주시니 정말 좋네요! 하하! 아하하 하하 아랫층에 있는 손님한테 영수증 천원에 팔아 먹어야지~! 라는 나쁜 생각은 절대 하지 않았어요!!', 21, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '친구들이랑 호기심에 6명에서 놀러갔는데 다들 먼저 말 걸어주고 재밌게 좋은 추억 경험 남기고 갑니다 ㅋ꙼̈ㅋ꙼̈ㅋ꙼̈ㅋ꙼̈ 👍🏻', 39, 0, 'GOOD', SYSTIMESTAMP);
