INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '냥냥하게 귀엽고 가끔혼자가도 부담없는메이드카페라서 그런지 너무 좋아요  뭐 처음가보면 항마력이 떨어지겟지만 ㅋㅋㅋ 경험상 나쁘진않을것같아요^^ 꼭 한번쯤 용기를 내서 가보시는것도 추천!!!', 52, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '최고의 메이드카페..✨ 홍대에 메이드카페 여러군데 생겼는데 여기가 젤 만족했어요..ㅜㅜ 메이드님들 넘 귀엽고 사랑스러우심🥺💓 예쁜 여자얘들이랑 떠드니까 기분이 날아갈 것 같아요 - ! 또 가고싶다아..', 15, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '원격으로 시로님 체키를 신청할 수 있다니 정말 놀랍군요ㅎㅎ 위드하트, 넷키 파레에도 활동, 오마이에서 뵐 때 뭔가 다 느낌이 다르니 신선하네요', 3, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '하루여신님 보러 오마이 왕국을 방문했습니다. 아이돌별에 계실 때부터 자주 뵜었는데, 아이돌, 천사 겸 악마로 계실 때랑 또 다른 느낌이라 새로웠습니다. 오늘도 하루여신님의 풀 J-pop 라이브를 감상하고 체키를 남길 수 있어서 정말 기쁘네요. 천재 과학자 페로님과도 체키를 남길 수 있어서 좋았습니다. 앞으로도 훌륭한 연구를 수행하셔서 대한민국 기초과학을 위해 SCIE급 논문을 많이 출판하시길 기원하겠습니다.', 47, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '매미를 좋아하는 분들이 늘어서 정말 뿌듯합니다! 언젠간 매미왕국도 생기지 않을까 기대 중입니다! 하지만 매미냉모밀이라니.. 상상하고 싶지도 않네요..!', 89, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '홍대를 지나가던 중 우연히 방문했습니다. 절대 UFO UFO가 자꾸 생각나서 그런 건 아닙니다. 1인 라이브 세트를 주문했지만! UFO UFO를 신청했지만!! 솔직히 자꾸 생각나긴 했지만!! 딱히 UFO UFO 금단 현상 때문에 온 건 아닙니다. 사실 레모님의 UFO UFO 보러 온 거 맞구요. 정말 재밌는 춤이라고 생각합니다.', 5, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '하루여신님 탄생일을 기념해서 오마이 왕국에 방문했습니다. 하루여신님 생일 전이라서 그런지 머무는 동안 계속 용사님들이 입장하셔서, 13시부터 만석이라 정말 즐거웠습니다. 만석임에도 Kpop 여우야 보컬 하프 콘서트랑 Jpop 아이돌 댄스 하프 콘서트도 정성스럽게 준비해주셨던 게 기억에 남네요ㅎㅎ 하루여신님과 체키를 남기시는 분들이 많아서, 앞으로는 용사님들을 부르는 피리 부는 코하루님이라고 불러야 될 것 같습니다ㅋㅋㅋ 코하루님이 피리를 불면, 용사님들이 착석할 수밖에 없... 오늘 천재 페로님은 얼굴만 뵐 수 있었지만, 플라워 왕국에서 오신 나비님과 체키를 남길 수 있어서 정말 뿌듯하네요. 앞으로도 자주 뵐 수 있으면 좋겠습니다ㅎㅎ 요약: 코하루 여신님과 나비님, 페로님은 아름답다!', 42, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '#생일날 방문^^햇네요##뜻깊구 1주년하루#정말즐겁구행복하게되네요^^#모두들축하해주시니 감지덕지하구#시간가는줄모르구#연속라이브구경두하구 #재밋엇어요^^#항상번창하시구파이팅입니닷^^@', 80, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '어떤 곳인지는 소식으루 접해 알고있었어요! 실제 방문은 첨이였는데 분위기가 신기하고 친절했고 서울에 있는 동안은 자주는 아니더라도 또 가구싶어요~', 13, 5, 'GOOD', SYSTIMESTAMP);
