INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '첫번째 방문이였는데 모든 메이드분들이 열성적으로 이끌어주셔서 너무 좋았습니다. 각 메이드분의 특성도 독창적이고 흥미로웠습니다. 다만, 마나포션 먹었는데 색소 때문인지 예전 불량식품인 페인트 발바닥 사탕 먹은 듯이 되어서 조금 별로였습니다. 블루레몬이라면 블루 큐라소를 사용하면 더 좋을 듯 합니다. 하이볼처럼요.', 46, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '오마이 5번째 방문인데 4월24일, 4월30일에 방문 했을 땐 체키로 연장 할려면 기존 주문에 포함 시켜야 한다 했고 6월4일에 방문 했을땐 체키로 연장 할 때는 연장 할 때 연장체키로 신청하라고 했었고 어제도 그렇게 했는데 영수증엔 일반체키 1장+1시간 연장으로  돼있어서 인스타 계정에 문의 했더니 처음 주문 할 때 연장체키로 연장하겠다고 하는게 규정이라 환불 안 된다, 모든 손님들이 그렇게 연장을 하신다 라는 답변이 돌아오길래 궁금해서 커뮤니티에 체키로 연장할 때 어떻게 하냐 했더니 연장할 때 연장체키 주문한다는 답글이 달리니 도대체 뭐가 제대로 된 규정인지 이해가 안 되네요. 매장 가격표에 체키 두 장으로 연장을 원할 시 이용시간 1시간 중 50분 부터 주문가능 이라 적혀있는건 뭡니까 대체.', 127, 19, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '머글 동생 데려갔는데, 안에 큐트한 메이드들이 대부분인데, 한국에서 아이돌 연습생하던 냉미녀 쿨걸이 있어서 머글 동생이 거부감 없이 즐길수 있었습니다 ㅎㅎ 전 상냥하고 사랑스러운 메이드가 좋지만 일반인 친구들 데리고 가려면 역시 좀 한국에서 인기 많은 스타일의 메이드가 있는게 좋은거 같아요', 21, 8, 'GOOD', SYSTIMESTAMP);
