INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '처음 방문해서 조금 어색하고 그랫지만 메이드분들도 친철하게 응대해주셔서 금방어색함이 사라진거같습니다! 노래랑 춤도 잘구경하다가 갑니다. 예약하시면 예약시간에 맟춰서 입장이 가능하니 참고하시고 한번 가보시길 추천드립니다 ~', 29, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '오랜만의 방문이라 저주의 기운을 잔뜩 끌고 와버렸어요! 우하하! 오늘은 재밌는 일이 많았던 거 같아요! 제 턱살에 대한 고민을 해결해주셔서 감사합니다! 그리고 제가 어르신 컨셉 좋아하는 거 어떻게 아시고! 어르신 컨셉 야시장체키? 까지 준비해두시고! 와! 완전 센스 넘치잖아요! 최고잖아요! 크하하하하 카하하하하하하핳 캬ㅏ하하하ㅏ하 아 그리고 체키찍는 카메라가 강해져서 그런지 예전보다 사진이 더 간지나게 나오는 것 같아요! 이것은 아주 만족스럽습니다! 이제 체키를 보고 슬퍼지지 않아요!', 25, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '오늘은 누군가의 졸업식이라 방문했습니다! 마지막이라 물어보고 싶은 거 있었는데! 물어보는 거 까먹었어요!!! 하지만 괜찮아요! 분명 내일이 되면 또 잊어버릴 테니까요! 이젠 멀리 떠나버리셨지만 올해까지는 기억할게요!', 23, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '만우절이라고 집사카페 분들이 메이드 카페에서 메이드로 계셨는데 서비스가 실망스러웠습니다 중간중간 말을 걸어주긴 하셨으나, 라이브를 입장하자마자 주문했음에도 불구하고 30분 넘게 아무런 준비나 안내가 없어서 여쭤봐야 했고, 저희 타임이 다 끝나감에도 불구하고 더 늦게 입장해서 신청하신 분 라이브를 먼저 진행해서 저희는 타임 끝나고 그냥 나갔습니다 다른 분들에게는 서비스 잘해주시던데 저희가 음료랑 라이브만 신청하고 체키같은건 안해서 그런가 싶네요 단골 분들께는 잘해주시는 것 같으니 자주 가실 분들이라면 괜찮을 것 같습니다', 93, 22, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '메이드카페 여러군데 다녀봤지만 여기가 제일 넓고 좋아요 위 아래로 집사카페와 메이드카페가 있어 이성이랑 와서 두 군데 다 가보는 것도 괜찮을 거 같네요 물론 전.. 없어서 혼자 메이드카페나 갈랍니다.', 42, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '긴 꿈을 꾸다 온 느낌이였습니다... 메이드카페 자체가 처음은 아니고 이게 두번째인데 첫번째로 갔던 메이드카페는 유명 코스어가 일일메이드로 근무한대서 갔더니 매장이 엄청 좁고 바쁘다보니 방치 당하는 경우가 많았어요. 그래서 이번엔 유키님을 보러가러 가는건데 방치 당하고 대화를 얼마 못해보는거 아닌가 걱정이 많았습니다. 근데 여기도 체키를 어느 메이드랑 찍을건지 적는게 있는데 제가그걸 유키님으로 적은걸 다른 메이드분들이 알아챈건지 아니면 바쁜 상황이 아니라 운이 좋아서 그런건지 몰라도 원하는 메이드인 유키님이랑 제일 많이 대화를 해서 좋았어요. 그리고 매장도 넓고 쾌적하고 테이블 사이 간격도 좁지 않아서 좋았어요. 무엇보다 평일에 가니까 여유가 있어서 바쁜 메이드분들 부르기 미안한 상황이 없어서 좋았습니다.', 33, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '메이드카페는 처음이였는데 1시간 뚝딱이였어요 메이드분들도 너무 친절하시고, 대화할 때도 재밌어서 시간이 빨리 갔네요 이런곳은 음료랑 디저트가 맛없기마련인데 귀여운 그림 덕분인지 다 맛있게 먹고 왔어요 바깥에 포토존도 있어서 부끄럽지않게 사진까지 알차게 찍고올 수 있어요 ㅋㅋ 메이드분들이 너무 귀여워서 또 오고 싶어요 오래오래 흥하세요 ~💛', 70, 12, 'GOOD', SYSTIMESTAMP);
