INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '고양이의 뒷모습은 오랜만에 보는 것 같네요. 오목 실력이 많이 늘었더군요. 패배를 인정합니다! 608년에 태어나 지금까지 살아오신 분을 이기기엔 저는 아직 많이 부족하군요!! 멋있어요! 위대해요! 간지나요! 살아있는 역사! 잘생겼어요! 강력해요! 608년생 최고!!', 22, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '두달만에 방문했는데도 시간이 금방 지나가더라구요 ㅎㅎ 새로운근무하시는메이드분들하고도 안면트게되고 여러번방문해서 낯익은 메이드분들하고는 못왔던날들동안 있었던 근황 서로 묻고 답하기 좋았던것같았습니다', 41, 7, 'GOOD', SYSTIMESTAMP);
