INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '이땐 몰랐죠. 오늘 본 고양이의 모습이.. 제가 보게 될 마지막.. 아뇨 고양이는 아름답습니다. 고양이는 정말 최고의 생물이라 생각해요. 상당한 전투력을 갖고있죠.', 105, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '메이드 언니들이 다 밝고 예뻐요!!!!! 컨셉도 독특하고 넘 귀여워요 오므라이스도 넘 마시써요~~ 또 오고 싶어요 ❣️❣️❣️', 19, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '한 메이드의 마지막을 보기 위해 방문했습니다. 저녁에 간신히 도착했는데 역시 인기 완전 많으시더라구요!! 6시 반에 간신히 예약했어요! 마지막 체키를 남길 수 있어서 다행이었습니다! 쓰러질 것 같은 몸을 이끌고 온 보람이 있었어요!! 次は君だ。', 10, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '더운데 이색 카페와서 시원하고 재밌게 놀다가요 커플들끼리도, 친구들끼리도, 혼자서도 많이들 와서 편하게 입장해도 좋을것 같아요', 42, 6, 'GOOD', SYSTIMESTAMP);
