INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '여자친구랑 데이트로 메이드카페를 갔지요. 전혀 부담스럽지 않게 안내해주시고 안에 사람들도 재미있게 즐기고 있고 전혀 어색하지 않게 즐길수 있습니다. 메이드분들도 한분씩 오셔서 인사해주시고 자기소개도 해주시고 해피한 에너지를 느낄수 있습니다. 색다른 카페데이트로 좋더라구요. 만약에 혼자가신다면 1인메뉴도 있어서 알차게 시간을 보내실수 있을거 같아요. 나중에 또 가고 싶었습니다.', 65, 16, 'GOOD', SYSTIMESTAMP);
