INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '이곳에 올 때마다 느끼는 거지만 케챂으로 이런 화려한 그림을 그릴 수 있다니! 정말 멋지다고 생각해요! 오늘은 오목은 2번을 도전했고 결과는 1승 1패.. 이걸로 오마이왕국에서 저는  2번 패배했습니다. 승리는 기억하지 않을겁니다! 제가 기억하는 것은 패배뿐! 저를 오목으로 패배를 안겨준 메이드 분들은 세상이 끝나는 그 순간까지도 기억할 겁니다! 영원히.. 절대로 잊지 않아요..!', 79, 14, 'GOOD', SYSTIMESTAMP);
