INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '아예 지식 없이 체험하려고 왔는데, 메이드 분들도 다 친절하시고 재밌습니다! 이쪽에 관심 없더라도 특별한 경험 하고 싶다면 추천합니다!', 20, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '처음 방문 해봤는데 다들 너무 착하시구 디저트도 너무 맛있어요 ㅠㅠ게임도 재미있게 해주시고 매장 설명도 너무 친절히 해주시더라구요!!😄좋은 추억 만들도 갑니다!!☺️', 27, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '모에왕국 단골인데 오마이왕국이 커서 친구들 데리고 오마이로 처음 갔는데 주말이었긴 하지만 모에에 비해 너무 어수선하고 메이드님이 용사보다 부끄러움을 타셔서 안내가 잘 안들리고 다들 바빠서 테이블에 잘 안 오시기도 하고 시간도 빠듯해서 밥도 허겁지겁 먹다 남기고 뭔가 아쉬웠어요.. 😢', 33, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '국내에서 현존하는 메이드 컨셉카페 중에 가장 넓고 깔끔하며 깨끗하고 쾌적한 곳이예요. 오므라이스도 켸찹으로 그림그려주시는 거 보는 재미가 있지만 저는 개인적으로 카레가 맛있더라고요. 칵테일도 맛있는 편이고... 라이브쇼도 재밌고 보드게임류를 플레이할수도 있는 등 다른 곳엔 없는 컨텐츠들 있는 만큼 가장 인싸픽!! 폐쇄적이지 않고 대중적이란 느낌이에요. 메이드분들과 말도 잘 통하고(언어장벽 없다는 뜻) 부담스럽지도 않아요. 다른 곳에서는 제 태블릿 훔쳐보고 저 잘못한 것도 하나 없는데 뒤에서 험담 오간 적이 있어서 속상했는데(못들을거라고 생각했나...) 이곳은 그런 거 전혀 없고, 퇴폐업소나 풍속점 느낌 전혀 없고 에버랜드~♡ 테마파크같은 느낌이라 심심할 때마다 오게 되었어요. 오마이왕국 최고!! ^^', 61, 14, 'GOOD', SYSTIMESTAMP);
