INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '메이드카페 처음 방문해봣는데ㅔ 정말,,, 기대이상으로 너무 기엽고,,,,, 정말,,,, 여기가 천귝인가 봐요,,,,,,,,,,,,,,,, 예뿐 메이드쨩들이 와서 소개 해쥬시는데 기절할뻔 햇습니다,,,,,,, 너무,,, 조아요,,,, 제발 방문 해보 세요,,,-ㅁ ㅔ이드가 되 볼수 잇는 절호의 기 회,, 두둥,,,,', 27, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '우왁 우리의 첫 메이드카페.. 운좋게 당일예약 성공해서 갔는데, 좀 일찍 도착해서 안에서 대기 후 시간 맞춰 자리에 안내해주셨습니다. 여러분, 왜 안 가세요? 항마력에 못 다할 메이드카페가 아니었습니다. 메이드들도 엄청난 하이텐션과 미들텐션 로우텐션 다 달라서 메이드들과 대화가 꿀잼.. 솔직히 하이텐션 힘들지않을까 했는데, e i 반반인간인 저에게는 오오~~ 할 정도였습니다. 역할극놀이, 어릴때 했던 소꿉장난정도로 생각하시면 충분히 즐기실 수 있습니다. 또 갈 예정!', 50, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '메이드분들 전부 다 친절하시고 너무 귀여우세요 저는 친구랑 갔는데 혼자 와도 재밌게 놀 수 있을 것 같아요 두 번째 방문인데 처음이랑 두 번째 모두 너무 만족스러웠어요♡ 일본에서도 메이드 카페 몇 번 가봤는데 오마이 메이드카페가 최고네용 담에 또 올게요', 34, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '친구가 가자고 해서 가보았는데 다들 친절하고 좋아요! 이곳에선 사용금액도 친절하게 누적하여 더욱 좋은 서비스를 해주십니다. 자주 오고 싶은분들에거도 좋은곳!', 61, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '우와 오늘 가봤는데 뽑기로 3등이 나오더라고요!!!!! 기대도 안 했는데 이게 되는 거였구나~~ㅎㅎ 싶고 기분이 좋네요 칼바사 소세지도 맛있었습니다. 메이드 분들 라이브 공연도 엄청나게 수준이 높습니다. 춤을 굉장히 잘 추세요. 👍👍👍😎 친구랑 오기 좋은 곳입니다~!', 14, 7, 'GOOD', SYSTIMESTAMP);
