INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '레미짱의 환상적인 라이브 아주 그냥 죽여줘요. 다음에 언제또 올지모르지만 제가 포항에 살다보니 열시미 모아서  또 놀러올게요. 그때까지 다들 아프지말고 건강하게 행복하게 보내세요. 이성준용사님이', 25, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '처음 방문해봤는데 매장에 계신 메이드 분들 모두 친절하시고 잘 대해주셔서 재미나게 보냈습니다. 오므라이스와 하이볼도 다 맛있게 먹었습니다.', 15, 8, 'GOOD', SYSTIMESTAMP);
