INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '메이드카페가 궁금해서 한번다녀왔는데 너무 재미있고 신기한 경험이였어요 메이드분들도 엄청 친절하시고 대화하기너무 잼있어요. 단 항마력이 어마무시하게 필요하지만 이런거 좋아하시는분들은 진짜 좋아하시는 듯 음식은 큰기대 안하는게 좋을지도', 43, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '처음으로 가본 메이드 카페! 친구들이랑 호기심에 가봤는데 너무 재밌고 친절하셔서.. 즐겁게 놀다왔어요 ㅋㅋ 사실 메이드카페 음식은 기대 안 하고 갔는데 음식도 너무너무 맛있고 그림을 되게 잘 그려주시더라구요. 다음에 기회되면 또 놀러오겠습니다! 너무 재밌어서 사진까지 같이 찍고 ㅋㅋ 편지도 받았네요', 12, 5, 'GOOD', SYSTIMESTAMP);
