INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '메이드 얼굴만 보면, 한국 메이드들이 훨씬 귀엽구 이쁜거 같아요. 음식두 여기가 훨씬 맛있네요 ㅎㅎㅎㅎ 아키바 메이드 카페 가서는 사진만 찍구 먹지는 못했는뎅 여긴 밥 먹으러 두번째 왔어요. 올때마다 귀여운 메이드 분들이 여섯분 이상씩 보여서 너무 좋아영. 또 오고 시퍼용', 26, 5, 'GOOD', SYSTIMESTAMP);
