INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '쳐음 친구랑 온 메이드카페인데 리츠링,묘아메이드님,유메메이드님 다들 너무 친절 하시고  다들 너무 예뻐요..ㅠㅠㅠ  진짜 너무 예뻐요! 다들 친절하시구! 안내도 잘해주시고! 핫케익에 그림도 그려주시고 대화도 잘이끌어 주시고 항상 존댓말로 예쁘게 말해주셔서 친구랑 재미있게 즐겼다 갔습니다!!❤❤ 다음에 친구랑 또 방문할게요!!♡', 34, 2, 'GOOD', SYSTIMESTAMP);
