INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '메이드들도 너무 친절하시구, 매장도 이쁘고 재밌었습니다! 말도 많이 걸어주시고 해서 좋았어요! 아직 어색했던 것도 있었지만 장난도 치고 하다 보니 조금은 더 친해지고 재밌었던 거 같습니다!', 56, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '친구랑 오늘 첫 메이드카페 탐방★ 기대 이상으로 즐거웠습니다. 다들 금손!!! 케찹이나 초코시럽아트 실력이 스고이하셔서 깜짝 놀랐어요. 역시 메이드시다보니 친절함은 기본장착 ㅋㅎㅋㅎ 다음에는 후배님 모시고 올게요^^ 냥냥~^^', 41, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '너무 즐거운 시간이었습니다! 유튜브보고 한 번 관심이 생겨서 이용하게되었습니다! 다들 친절하게 응대해주시고 즐거운 이벤트를 경험하는 기분이었습니다! 라이브쇼도 열정적으로 해주시고 오므라이스 진짜 맛있고 그림 너무 귀여워요 ㅜㅜ 파르페도 귀엽고 특별 랜덤음료 너무 즐거웠습니다! 뽑기도 했는데 다음에는 꼭 1등이나 2등하고싶네요!! 단체체키도 찍어보고 싶고 너무 즐거워서 다음에도 또 가고싶습니다! 혼자 오시는 분들도 넘 잘해주셔서 좋아요~~👍👍🥰', 30, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '근처에 볼일 있어서 들렸는데 독특한 분위기 좋습니다 😁 처음 와봤는데 재밌습니다 ㅋㅋ 👍 다음에 시간된다면 다시 오도록하겠습니당', 26, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '지난번에 친구들과 놀러오고 이번엔 혼자 놀러왔는데 언제 와도 재미있게 즐기고 가는 것 같아요! 3월 초에도 친구들과 또 놀러올게요😆', 49, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '메이드 분들도 친절하고, 디저트와 음료도 맛있었어요!! 디저트에 그려주신 그림도 귀여웠고요..💖 재방문 의사 있습니다..!!!!! 이쁜 메이드 언니들 체고👑✨🩷🙈', 10, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '메이드 언니들이 넘 이쁘고 친절하세요💕 프로의식 철저합니다. 메이드 카페가 궁금하시다면 친구들과 함께 방문하는거 추천합니다. 메론소다 맛있어요!🍈멋있는 공연 감사합니다!✨', 110, 20, NULL, SYSTIMESTAMP);
