INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '너무너무 와보고 싶던 메이드카페 드디어 입성! 친구랑 왔는데 예쁜 메이드님이 친절하게 반겨주셨어요! 저희는 세트메뉴로 먹어서 식사,디저트,음료 이용했구요 메이드복 체험도 추가했어요! 오므라이스가 기대이상으로 맛있어요! 어려운 그림 주문에도 정성스레 그려주시던 리리짱 최고에용❤❤ 너무너무 즐거운 시간이었습니다~☺️🩷', 76, 14, 'GOOD', SYSTIMESTAMP);
