INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '노아짱이 안내해주고 주디 레미 루나가 인사하러 와줬어요 루나짱 딸기 향수가 맘에 들어서 정보 얻으려고 할리갈리 도전했는데 win^^ 메이드복도 입어보니까 재밌었어요 i이긴 한데 재밌는 경험이었고 돈만 많으면 전메뉴 다 시켜보고 싶을만큼 서비스가 좋았어요 모에모에뀽 이거 처음에는 좀 그랬는데 듣다보니 중독됩니다 주변에도 다 평범하신 여성/ 남성분들이 8:2정도 있으심 한번쯤 경험해봐도 재밌을듯여', 34, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '세상에서 제일 귀여운 메이드분들이 계신 오마이왕국점...💞 오무라이스 그림도 너무 귀엽고 라이브도 체키도 다 너무너무 좋았어요!!!중간중간 메이드분들이 명함을 주시러 오는데 그 시간도 다 너무 소중했습니다🥹💞 메이드카페로 파산? 어렵지 않다 재산을 몰빵합니다', 40, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '메이드 카페는 처음 가봤습니다. 신선한 충격입니다. 그림을 정말 잘 그려주시는 분이 계십니다. 금발이십니다. 텐션도 가장 높아서 재밌습니다. 처음이라 잘 모르겠으나 다른 메이드 분들도 친절하게 응대해주셨습니다.', 28, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '친구랑 같이 궁금해서 한번 가봤어요! 기대 이상으로 너무 재밌었구 메이드 언니분들 너무너무 귀여우시고 이쁘셔요.. 친구랑 한번씩 가서 재밌는 경험 하고 오시는거 추천드려요 !! 너무 만족스러운 하루였습니당😽', 46, 6, 'GOOD', SYSTIMESTAMP);
