INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '크리스마스는 오마이메이드카페와 함께지요ㅎㅎ 다들 친절하고 음식도 맛있고 라이브도 너무 멋져요ㅎㅎ 메이드분들이 모든 손님분들끼 최선을 다 하시니 다들 놀러오에요ㅎㅎ', 45, 3, NULL, SYSTIMESTAMP);
