INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '메이드 카페가 생겼다길래 구경왔어요! 다들 너무 예쁘고 귀여워서 좋았습니다~ 독특한 컨셉이라 특별한 경험이 되네요. 메이드마다 컨셉이나 설정도 달라서 너무 재미있는 것 같아요!', 26, 1, NULL, SYSTIMESTAMP);
