INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), 'オムライスが美味しかったです。 私は日本人ですが、日本語が少し話せるメイドさんがいて説明もわかりやすかったです。 アニメ好きのメイドさんが居てアニメが好きな人はいいと思いました。 오므라이스가 맛있었어요. 저는 일본인입니다만, 일본어를 조금 할 수 있는 메이드가 있어서 설명도 알기 쉬웠습니다. 애니메이션을 좋아하는 메이드가 있고 애니메이션을 좋아하는 사람은 좋다고 생각했습니다.', 30, 9, NULL, SYSTIMESTAMP);
