INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '메이드분들이 정말 귀엽고!! 루나? 님이랑 체키를 찍었는데 체키 완전 귀엽게 꾸며주시고 몸에서 딸기향이 폴폴나셨어요ㅠㅠ 진짜 몰입 완전 잘되고 진짜 오마이왕국에 온뜻한 기분이였습니다', 126, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '메이드 카페는 처음 방문인데 너무 행복해요 예쁜 메이드 분들이 많아서 여기가 천국이 아닐까 싶습니다 기분이 좋아서 웃음이 멈추지 않네요 사람들에게 행복을 전파하는 메이드님들도 행복한 날만 가득 하셨으면 좋겠습니다💖', 129, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '모에모에큥만 갔었는데 저랑 친한 메이드짱들이 다 떠나서 오마이 한번 가볼까 했는데 너무 만족해요 매장도 넓고 인테리어도 이쁘고 무엇보다 가격이 부담스럽지 않아서 좋아요 비싼 선물도 금지고 건전해서 너무 만족해요 이제 오마이로 갈아탈게요❤️💚🧡', 2, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '처음오는 곳이라 기대반 걱정반이었는데 막상 와보니까 너무좋았어요!!😆😁특히 열심히 해주시는 메이드 분들이 이것저것 알려주시고 함께해주셔서 좋았습니당☺️😁 한번 더 와도 좋을거같아요!! 즐거운 경험이었습니다아아😁', 46, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '여자친구와 데이트를 왔는데 너무 친절한 메이드분들과 함께 좋은 경험 했습니다! 한분 한분 처음 온 저희를 챙겨주시고 여러가지 설명을 유쾌하게 해주신 것에 감동 받았습니다. 홍대 데이크 코스로 강추드립니다!!', 15, 9, 'GOOD', SYSTIMESTAMP);
