INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '행복해요 진짜 인생이 너무 행복해요 진짜 너무 좋아요 진짜… 너무 맛있고 친절하고.. 귀엽고.. 사랑스럽고… 제가 죽었나봐요 여기가 천국인거 보니까 그래도 착하게 살았나봐요 감사합니다 진짜 행복해요', 15, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '로미 닌자 메이드님 안내를 받아 들어와서 주문도 외우고 오무라이스에 그림도 받고!!!! 너무 황홀헌...경험이었읍니다...이 할머니...세월에 죽었던 가슴이 다시 뛰기 시작했습니다.... ㅜ 유이 메이드님 오무라이스 꾸미기도 정말 예뻐서 넋놓고 봤습니다!!!!!! 담엔 유키님 오무라이스 꾸미기도 받아보고 싶어요!!!!! 다들 너무 친절하시고....그냥 엔젤 그자체....행복하구요...행복합니다....', 4, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '처음 와서 어색한데 어색함 풀어주시려고 계속 말 걸어주시고 모두 친절하시구 예쁘시구... 의외로 음식이 맛있어요!! 오므라이스 맛집 ♡', 75, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '정말 다들 친절하시고 분위기도 좋고 다들 이쁘고 저의 필력이 부족해서 많이 쓰지못하지만 혼자도 재미있고 둘이와도 좋고 단체로와도 재밌습니다. 같이 체키쩩고 꾸며준다는것이 너무 좋네요ㅎㅎ 꼭 한번만이 아닌 여러번 방문해보시길 권장합니다ㅎㅎ', 10, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '친구랑 같이 왔는데 메이드가 생각보다 친절하고 웃겨서 재밌게 잘 놀고 가는거 같아요 가격도 그렇게 나쁘지도 않고 괜찮게 놀거리 찾으시면 여기 가게 추천드립니다', 83, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '메이드님들이 너무x100 이쁘고 귀여우세요 눈이 피로하다면 이곳을 오는걸 추천함 메이드분들을 보면 눈이 편안해지기 때문입니다 +시력도 올라감 오늘 처음 온 사람인데 여기서 살고싶어요 감사합니다 제 인생이 행복해졌어요.🤤🥰❤️', 125, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오마이 메이드카페 오마이왕국점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '다른 메이드 카페 갔다가 마상 입고 이 곳을 방문했는데 친절하고 분위기도 좋아요 매장도 넓고 편안한 느낌에 메이드분들도 이쁘십니다!!', 23, 0, 'GOOD', SYSTIMESTAMP);
