INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '종종 테이크아웃하는 곳인데 홍대거리 가운데있어서 그런지 작은 공간에 손님이 엄청 많아서 대기가 있는편 초코멜로우샌드는 초코파이를 크림화해서 빵에 발라 먹는 듯하다', 7, 3, NULL, SYSTIMESTAMP);
