INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '딸기바나나주스 먹었어요! 부드럽게 넘어가고 바나나 맛이 진해서 넘넘 좋았어요🤩 홍대 주변 코인노래방 가기 전에 늘 방문하는 곳이에요😊😊', 73, 15, 'GOOD', SYSTIMESTAMP);
