INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '홍대에 있어서 그런지 사람이 엄청 많더라구요. 포장기다리는데 사람들 엄청 줄서서 구매했어요 ㅎㅎ  저렴한 가격에 커피를 살수 있어서 그런지 인기가 좋네요.', 20, 9, NULL, SYSTIMESTAMP);
