INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '다른 지점에서 먹는것보다 홍대점에서 마신 수박화채스무디는 정말 수박화채맛이라서 놀랐어요!! 이게 진정한 수박화채스무디 구나 싶었어요', 43, 2, 'GOOD', SYSTIMESTAMP);
