INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '여기 알바분 말 참 ㅈ같이 하시네요 ㅎ 1. 밖 선반 위에 올려주면 당연히 번호표와 올려두셔야지 않햇깔리지 않을까요?? 2. ㅅㅂ 표정… 가는 말이 고아야 오는말이 고와요 ㅆㄴㅇ~ 24.12.25 13시 10분에 일하시는 분임 ㅅㅂ', 40, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '베이글 먹고 싶어서  왔는데  이렇게  맛있는 베이글은 처음이에요👍😄❤️  깔끔한 인테리어와 매장도 넓고 직원분도 너무 친절하세요 💕🥰~  외국분들이 많아서 뉴욕에서 먹는 베이글 느낌이 나네요 🎵🎵~', 32, 3, 'GOOD', SYSTIMESTAMP);
