INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), 'It is my third time here today. Love love love their bagels!! I wanna try every flavor they offer. Everything is just on point:)', 8, 1, 'GOOD', SYSTIMESTAMP);
