INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '성수점에 갔다가 품절이여서 온 홍대점! 월요일 2시라 그런지 빵이 아직 많이 남아 있었어요! 유명한 도넛 2 개 먹었는데, 진짜 왜 유명한지 알겠고 당충전 제대로 되는 맛이에요…. 무조건 커피가 필요한 맛.. 그만큼 맛있다는 이야기 ♥️ 카다이프가 그득그득해서 좋았고 두바이도넛보단 오레오가 훨씬 달아요!!! 분위기도 좋고 직원분들도 친절하셔서 또 방문 할 거 같아요♥️♥️', 9, 5, 'GOOD', SYSTIMESTAMP);
