INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '혼자 나들이 온 기념으로 베이글이 먹고 싶어 들렀습니다. 베이글랜드라는 이름처럼 베이글 나라에 온 듯한 인테리어와 베이글 천국에 온 듯한 여러가지 베이글들 저와 같은 빵덕이라면 행복할 것 같습니다. 쪽파 베이글을 골라 먹어봤는데 참 크림치즈가 고소하니 참으로 맛있습니다 여러분이 상상하는 그 맛. 또 먹고 싶습니다.', 77, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '너무 맛있어서 3회차방문... 맛나보이는게 넘많아서 리뷰이벤트 하려다가도 배부르게 골라버려서 이제야 해봅니다 ㅋㅋㅋㅋ 직원분들 모두 너무너무 친절하시구 한국어 넘나 유창하신 ....직원분 성함을 못봤는데 그 분께서 제가 여러번 방문한 걸 기억해주시고 인사건네주셔서 방가왔어요. 오늘은 아는분 선물로 베이글 드리려구 대파베이컨크림치즈샌드베이글 사갑니당 ㅎㅎ', 41, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '남자친구랑 오랜만에 베이글 먹으러 왔는데 역시나 여기 직원 분은 너무 친절하세용! 잘못 주문 했는데 잘 도와주셔서 ㅠㅠ 뻘쭘 하지 않게 잘 다시 주문 했어요! 처음 왔을 때부터 외국인 직원 분 안 잊혀졌는데 ㅎㅎ 다시 또 봬서 뭔가 반가웠어요! 맛도 친절도 다 있는 베이글 맛집! ㅎㅎ', 36, 4, 'GOOD', SYSTIMESTAMP);
