INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '구글평점 1위라고 홍보하고 있어 확인해 보니 4.9점이긴 한데..그 정도 인가?? 맛은 일부러 찾아 올 정도의 베이글 맛은 아닌 듯. 크림치즈없이 베이글 그 자체의 식감을 즐기는 편이라 블루베리 베이글 시켰는데 적당히 쫄깃. 베이글은 런베, 코베, 베리가 아직 까진 top3인듯. 커피 맛은 기대 안했는데 의외로 괜찮음.', 33, 6, NULL, SYSTIMESTAMP);
