INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '페페로니피자 베이글에 페페로니도 마니 들어있고 맛나요 초코베이글도 맛잇어용 가게 안에 오븐이랑 전자레인지가 잇어서 직접 오븐에 돌린담에 먹으먄 돼서 조아요!!!!! 직원분도 친절하세요 굿ㄱ굿 그리고 무엇보다 가게가 넓어서 앉을자리가 넉넉해서 좋아요', 8, 7, 'GOOD', SYSTIMESTAMP);
