INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '친구 추천으로 처음 와봤는데 분위기가 너무 좋고 빵순이인 저는.. 눈돌아가는 비주얼에 욕심부려서 다 먹으려다 검은깨 베이글 하나만 주문..ㅎㅎ 커피도 고소한 편이고 정말 맛있습니다!!! 주변에 빵 좋아하는 친구있으면 데려올 것같아요~', 37, 7, 'GOOD', SYSTIMESTAMP);
