INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '예쁜만큼 맛있는 매장💖 베이글 빵만 먹다가 샌드위치 첨 먹어봤는데 역시나 맛있어요. 빵도 넘 맛있게 생겨서 다 먹어 보고 싶구 매장도 넓고 예뻐서 사진찍기에도 좋고 대화 나누기 넘 좋아요 !!!!!', 26, 0, 'GOOD', SYSTIMESTAMP);
