INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '카페 외관부터 완전 뉴욕 분위기 좔좔~ 베이글도 맛있고 내부도 크고 쾌적해서 친구들끼리, 연인들끼리 오기 좋을 것 같아요! 직원분들도 모두 친절하셔서 좋았어요!', 2, 8, 'GOOD', SYSTIMESTAMP);
