INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '맛과 메뉴, 인테리어와 분위기 모든것이 완벽한 홍대카페네요!! 베이글에 빠져사는데 베이글 종류도 많고 크림치즈도 다양하구요!! 푸짐한 베이글 샌드위치까지~~ 매일와서 도장깨기해서 못먹어본 베이글 없게하고싶은 베이글 맛집이네요!! 데이트하러 와도 좋고 친구들과 수다떨고 싶을때도 좋고 혼자와도 좋을 베이글랜드~ 맛있고 즐거운 시간 만들고 갑니다~또올께요👍', 47, 8, 'GOOD', SYSTIMESTAMP);
