INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '앤티크하고 뉴욕 갬성 나는 홍대 베이글 맛집! 종류도 30가지 이상 다양한 맛의 베이글이 있어서 골라먹는 재미가 있고요🥯 먹어본 애들 중에 제 원픽은 바질 리코타 베이글이랑 치즈올리브베이글! 은은한 바질향에 고소한 캐슈넛+리코타 조합과 올리브 꽉꽉 들어있는게 딱 제 스타일입니다ㅎㅎ 매장 내부도 자유의 여신상부터 샹들리에, 빈티지한 소품까지 하나하나 예뻐서 사진 찍기 딱이고요~ 분위기 맛집이라 친구랑 수다 떨기도 좋고, 혼자 여유롭게 앉아도 힐링되는 그런 곳이였어요ㅎㅎ 베이글 샌드위치 종류도 굉장히 다양했는데, 요건 다음에 먹어보려고요!😆', 90, 15, 'GOOD', SYSTIMESTAMP);
