INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '블루베리 베이글 맛이 크림치즈 랑  잘어울리고 맛이 고급지고 대파크림치즈도 맛있어요 인테리어 도 엔틱하고 홍대 디저트중 최고네요 데이트하기에도 좋고 음료도  맛있어요 브런치하기에도 좋고  포토존 이 이뻐요', 37, 5, 'GOOD', SYSTIMESTAMP);
