INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '베이글 진짜 맛있어요. 두바이초콜릿을 안먹어봤는데 여기서 맛을 느껴보네요 진짜 맛있어요 다음에 다른 베이글도 먹어볼게요 커피는 평범해요.', 44, 6, NULL, SYSTIMESTAMP);
