INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '맛있는 베이글이 많아서 뭘 고를지 넘 고민했는데 감자 베이글이랑 시즌 한정 블루베리블 베이글 먹었어요 넘 맛있게 잘먹고 가요~💛', 62, 18, 'GOOD', SYSTIMESTAMP);
