INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '딸이 맛집 디저트 찾아다니는걸 좋아해요. 두바이베이글은 아쉽게 품절ㅠ 오후6시에 왔는데 이시간에 두바이는 못먹는데요. 다행히 다른 메뉴 크림븨릴레, 쿠키앤크림은 있어서~  먹을수 있었어요. 분위기 좋아서~  사진찍기좋아요~~', 46, 5, NULL, SYSTIMESTAMP);
