INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '학원 점심시간에 🥯베이글 샌드위치🥯 먹고 싶어서 친구들과 방문했습니다. 매장도 넓고 시원하고 분위기 좋아요! 저는 잠봉 버터, 친구들은 연어, 불고기 주문했는데 전부 다 속도 알차고 너무 맛있었어요. 개인적으로 헐렁헐렁 느낌의 베이글은 선호하지 않는데 베이글도 밀도 높은 쫀쫀한 느낌이라 한끼 식사로 딱일 것 같아요. 추천🩵', 9, 3, 'GOOD', SYSTIMESTAMP);
