INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '홍대에서 아침일찍 문여는 카페찾다가 방문하게 되었는데, 완전 기대이상입니다! 인테리어도 이국적이고 베이글 커피 전부 맛있어요.', 72, 11, 'GOOD', SYSTIMESTAMP);
