INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '입구의 자유의 여신상이 날 반기는 베이글랜드 홍대점-여기 왜 이제왔는지ㅜㅜㅜ!! 엄마랑 둘이 먹으면서 너무 맛있어서 눈물 흘렸어요..ㅠㅠ 일단 실내 넓고 인테리어 너무 예쁘고 베이글 종류 다양하고 심지어 커피랑 슾도 맛있어요.. 홍대 근처 살면 진짜 매일 와서 먹을텐데 인천주민은 울고갑니다..ㅠㅠ 가족친구연인 누구와 와도 맛있게먹으며 즐거운 시간 보내실거에요, 홍대 베이글랜드 오니 여기가 뉴욕!! 강력추천합니다😍👍', 16, 0, 'GOOD', SYSTIMESTAMP);
