INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '베이글 맛집 추천해요 ! 홍대입구역 근처이고 베이글 특히 샌드위치 종류가 많아서 너무 좋았어요 😙 바질베이글 추천추천욥 !! 레몸크림치즈 대박적이에요..', 129, 22, 'GOOD', SYSTIMESTAMP);
