INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '평일 아침 먹으러 왔는데 한적하고 좋아요 지나가면서 보기만 했는데 겉으로 보는것보다 매장이 꽤 커요 (안쪽에 공간이 더 있음) 베이글 종류도 정말 많고 셀프로 사용할 수 있는 오븐도 있어서 따뜻하게 데워먹을 수 있었어요 다음에는 다른종류도 먹으러 와야겠어요', 72, 16, 'GOOD', SYSTIMESTAMP);
