INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '방문했던 베이글집은 갓 구운 베이글의 쫄깃한 식감과 고소한 풍미가 정말 인상적이었습니다. 속이 꽉 찬 크림치즈도 신선하고 부드러워서 베이글과 완벽하게 어울렸어요. 가게 분위기도 아늑해 커피와 함께 여유롭게 즐기기 좋았습니다.', 2, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '처음 방문했는데 너무 만족스러워요. 베이글 종류도 다양하고, 직접 구운 느낌이 살아 있어서 하나하나 식감도 좋고 속도 꽉 차 있어요. 영수증 리뷰 이벤트로 플레인 베이글도 추가로 받아서 너무 좋았어요. 이런 센스 있는 이벤트 자주 있었으면 좋겠어요ㅎㅎ 담백한 플레인 베이글 덕분에 집에서도 다양하게 즐길 수 있어서 완전 만족! 다음엔 다른 베이글도 도전해보려고요. 추천합니다💛', 21, 3, 'GOOD', SYSTIMESTAMP);
