INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '베이글 샌드위치도 너무 맛있고 분위기나 인테리어도 예뻐요! 맛있는 베이글 샌드위치가 먹고싶어 방문했는데 너무 만족스럽습니다ㅎㅎ 홍대에서 간단하게 식사해야할 때 또 찾아올 것 같아요!🍀', 97, 20, 'GOOD', SYSTIMESTAMP);
