INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '베이글이 엄청 쫄깃해요 친절하고 매장도 넓고 깨끗해서 좋아요! 외국인이 압도적으로 많아서 맛집인거 같아요 아침에 간단히 먹기도 좋아요', 51, 13, 'GOOD', SYSTIMESTAMP);
