INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '아침일찍 우연히 방문안 베이글랜드 분위기도 완전 이국적이고 손님들도 온통 외국인이며 심지어 직원도 백인의 귀여운 여자분이네요 ~^^ 베이글샌드위치 맛도 너무너무 좋았어요 ❤️ 앞으로 자주 방문할게요 ^^', 12, 5, 'GOOD', SYSTIMESTAMP);
