INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '토요일 오전 11:40기준 웨이팅 없이 입장 할 수 있었습니다! 8번출구에서 도보 3분이면 도착해요! 치킨샌드위치를 시켰는데, 간이 막 자극적이지 않아서 너무너무 맛있게 먹었습니다. 샌드위치의 베이글은 에브리띵베이글이어서 씹는 식감도 너무 좋았어용!! 기대 안하고 왔었는데 너무 맛있어서 포장도 몇개 하고 갑니다!!', 121, 24, 'GOOD', SYSTIMESTAMP);
