INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '베이글을 좋아해서 찾아왔어요!! 맛있어요!! 베이글 종류가 다양한데 품절된 베이글도 있네요~ 맛있는 베이글이 먹고 싶을때 또 와야겠어요 ^^', 111, 20, 'GOOD', SYSTIMESTAMP);
