INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '블루베리 스무디 너무 좋아하는 사람인데 너무 너무 맛있고요 더워서 막 돌아다니다가 프렌차이즈 카페들은 다 사람 꽉차서 한 3군데 돌아다니다 포기하고 올영에서 쉬다가 제일 가까운 카페 들어왔는데 맛집 발견 ㄷㄷ 인테이리어랑 조명도 이뻐서 사진찍기 좋았어용♡', 45, 7, 'GOOD', SYSTIMESTAMP);
