INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '베이글랜드 방문으로 베이글 성지 투어 다 해봤는데 빵 자체로 베이글랜드가 최고네요. 박물관도, 엘리펀트도, 그 외 몇몇군데들….. 여기 랜드가 제일 졸깃퐁신부드러운게 맛있네요. 토마토스프 매콤하니 맛있으니 셋트 강추합니다. 연어베이글은 내용물 참 알차고요, 다른 베이글들도 다 맛있었어요!!', 32, 0, 'GOOD', SYSTIMESTAMP);
