INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '베이글도 너무 맛있고 매장분위기도 차분해서 좋았습니당 베이글 고를때 다 너무 먹고 싶어서 결정하는데 시간이 좀 걸렸네요ㅠㅠ 식사대용으로도 먹기 좋은것 같아요!!', 44, 4, 'GOOD', SYSTIMESTAMP);
