INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '크림치즈가 너무 부드럽고 빵도 폭신하고 쫄깃해요 🖤 커피도 맛있고 빨리 나와서 좋아요 ㅎㅎ 계산해주시는 직원분도 밝게 응대해주셔서 너무 좋았어요! 나중에 베이글 먹고싶을 때 또 방문하겠습니다! 플레인 베이글도 궁금하네용 ✨', 69, 15, 'GOOD', SYSTIMESTAMP);
