INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '진짜 그냥 맛있습니당 빵이 엄청 부드럽고 고소하고 쫄깃해서 진짜 자주 올것같아요 블루베리 블라썸 베이글 먹고싶었는데 아쉽게 품절이라서 나중에 또 오겠습니다 ㅎㅎ☺️', 7, 2, 'GOOD', SYSTIMESTAMP);
