INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '쫄깃한 베이글을 맛볼수 있어서 좋았어요! 전통 베이글 만드는 방식으로 설탕 무첨가라서 더 굳굳👍👍 기본인 플레인 베이글은 고소 담백 쫄깃 고구마베이글은 달달 쫄깃 크림치즈도 들어가서 부드러웠어요 샌드위치 종류도 많던데 다음에는 샌드위치 베이글도 먹고 싶어요🤤', 7, 4, 'GOOD', SYSTIMESTAMP);
