INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '맨날 지나가면서 보기만 하다기 처음으로 방문해본 곳인데 직원분도 친절하시고 사람이 많은 이유를 알겠어요 진짜 저 베이글샌드위치 진짜 아침마다 먹고 싶어요... 햄버거랑은 또 다른 매력ㅠㅠㅠㅠ 블루베리크림치즈도 크림치즈가 진짜 꾸덕 묵직하고 마지막으로 달달하게 쿠앤크로 마무리하면 진짜 천상입니다... 다음엔 다른 것도 먹어보고싶어요 제발 다들 오셔서 드시길...', 21, 0, 'GOOD', SYSTIMESTAMP);
