INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '친구 통해서 알게되어서 홍대 올때마다 종종 방문하는데요 항상 느끼는 거지만 인테리어가 정말 이뻐요😍 고급지고 아늑한 느낌 .. 그리고 베이글이 정말 존맛인데요 황치즈 베이글 강력 추천드립니다 올때마다 먹어요 진짜 🐶맛있음', 33, 0, 'GOOD', SYSTIMESTAMP);
