INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '점심으로 샌드위치가 먹고 싶어서 혼밥하러 왔는데 연어베이글 샌드위치 너무 맛있고 신선하고 빵이 엄청 쫀득해서 일반 샌드위치보다 더 맛있는것 같아요 점심식사로 프레시한 샌드위치랑 커피세트 추천합니다!', 6, 1, 'GOOD', SYSTIMESTAMP);
