INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '너무 맛있어요 진짜 … 베이글 유명한 집들 몇개 먹어봤는데 젤 맛있어요!!!!! 점심으로 샌드위치 먹었는데 대만족했구요 다음엔 고구마베이글 먹으러 다시 올거에요!ㅠㅠ💗', 23, 10, 'GOOD', SYSTIMESTAMP);
