INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '베이글에서 정성이 느껴지고 너무 맛있어요. 많이 못먹을 즐 알았는데 한 자리에서 2개를 해치워버렸네요... 넘 맛있어요! 추천추천', 4, 7, 'GOOD', SYSTIMESTAMP);
