INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '우연히 알게 된 이후로 홍대에서 쉬거나 베이글 먹고 싶을 때마다 찾아서 와요 ㅋㅋㅋ 세트 메뉴가 ㄹㅇ 맛도리고 가성비 괜찮아서 브런치 먹기에도 좋은 것 같아요 내부도 꽤 넓고 무엇보다 내부 화장실이 쾌적해서 진짜 좋음!! 직원분들도 친절해요', 20, 5, 'GOOD', SYSTIMESTAMP);
