INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '주말에 딸과 데이트로 홍대 나와서 구글 리뷰 평점 1등인 베이글랜드 찾아왔어요. 쪽파 프랫즐 빵도 부드럽고, 크림치즈와 쪽파 비율도 좋아서 맛있었어요!!', 31, 6, 'GOOD', SYSTIMESTAMP);
