INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '분위기도 뭔가 외국에 있는것같이 너무 좋고 바닐라라떼랑 베이글 시켰는데 라떼는 너무 달지않고 커피맛 적당히 나면서 딱 좋고 베이글들은 너무 쫀득하구 맛있어요 그리고 생각보다 넓어서 답답하지 않고 좋았습니당🫶🏻', 19, 8, 'GOOD', SYSTIMESTAMP);
