INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '생각보다 공간이 넓어서 시간보내기도 좋고 베이글 종류도 다양해서 고르는 재미가 있어요! 다른 빵집들보다  베이글 퀄리티가 좋아서 만족스러워요', 10, 3, 'GOOD', SYSTIMESTAMP);
