INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '저희는 배불러서 베이글은 안먹었지만 다른테이블은 다 드시더라고여 엄청 맛있어보이게 생겼어요ㅜㅜ 담에 오면 꼭 먹으랴고요 커피도 맛있어요 👍🏻👍🏻👍🏻👍🏻 인테리어도 이뻐용 재방문의사 있습니다~', 75, 15, 'GOOD', SYSTIMESTAMP);
