INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '샌드위치랑 베이글 너무 맛있어요. 치킨 들어간 메뉴는 햄버거 같고, BELT는 샌드위치같아서 다른 맛에 먹었어요~ 토마토 스프도 맛있어서 같이 나오는 바게트 찍어 먹으면 좋아요. 쪽파 크림치즈 진짜 맛있어요 강추', 22, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '베이글이랑 커피 같이 주문했는데 조합이 딱이네요. 베이글은 겉은 바삭하고 속은 쫄깃해서 맛있었고, 커피도 깔끔하고 향이 좋아서 잘 어울렸어요. 카페 분위기도 편안해서 잠깐 쉬기 좋았습니다', 11, 4, 'GOOD', SYSTIMESTAMP);
