INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '고기만두베이글, 김치만두베이글이 있는 곳. 진짜 만두 맛이 났다. 뭔가 우육면 파는 집에 있어야 할 것 같은메뉴. 끼니 간단하게 때우고 싶다면 추천하는 메뉴.  카페는 앉을 자리도 굉장히 많고 베이글 샌드위치메뉴도 많이 있다. 샌드위치메뉴는 냉장고에 있는데 다 모형이므로 필요하면 직원한테 달라고 요청하기.', 35, 6, 'GOOD', SYSTIMESTAMP);
