INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '브런치카페 찾아보다가 일찍 열길래 방문했는데 매장이 넓고 쾌적했어요! 더운 날씨에 딱 좋은 온도..😁 베이글 종류도 다양하고 식사할만한 메뉴들도 많았어요!! 그중 고구마 크림치즈 베이글 최고였습니다 ㅜㅜ 다른 메뉴들 도장깨기 하러올게요 💛', 44, 2, 'GOOD', SYSTIMESTAMP);
