INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '베이글을 좋아해서 주기적으로 여러군데 다니는데 종류도 다양하고 데워먹을수도 있어서 너무 좋았어요. 토마토 스프도 후추맛까지 너무 잘어우려져서 맛있게 먹었습니다! 커피는 산미가 적고 전반적으로 카라멜 풍미가 좀 강하게 느껴져서 라떼로 마시면 맛있을 맛이라 다음엔 라떼로 도전해봐야겠어요!', 2, 10, 'GOOD', SYSTIMESTAMP);
