INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '베이글 맛집 인죵!!@ 종류도 다양하고 쪽파가 특히 맛있어요. 애매한 끼니 떼우러 왔는데 가볍고 담백한 베이글 식감이 마음에 듭니다. 오븐에 2분 굽는게 훨씬 맛있어요! 저는 감자 좋아해서 감자치즈 했는데 대만족. 감자샐러드가 따끈따끈 고소 달콤 짭짤하게 어우러져 있어 포장욕구 잔뜩', 64, 14, 'GOOD', SYSTIMESTAMP);
