INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '베이글 둘이서 6만원치 뿌셨는데 제 순위는 1. 쪽파크림치즈 2. 플레인+메이플피칸크림치즈 3. 아보카도 샌드위치 4. 블루베리 입니당 두바이 초코는 좀 기대했는데. 카다이프가 많이 볶아져서 굉장히 헤비한 풍미가 나는 느낌이었어요. 던킨 두바이도 먹어봤는데 전 던킨이 좀 더..ㅎㅎ 같이 온 친구는 시나몬이 1등이니 모두 오셔서 다양하게 드셔보세옹~ 잘 먹고 갑니당', 61, 11, 'GOOD', SYSTIMESTAMP);
