INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '직원분이 친절하시고 베이글이 폭신하고 쫀득하고 정말 맛있어요ㅋㅋㅋㅋ 가게 인테리어가 너무 멋져요. 샌드위치랑 올리브 베이글 황치즈베이글 특히 너무 맛있어요.', 18, 7, 'GOOD', SYSTIMESTAMP);
