INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '홍대 데이트할겸 찾다 발견한곳이예요. 두바이 베이글이 있다해서 맛이 궁금해 와봤죠. 같이 주문한 잠봉버터도 맛있어용!! 여름에 딱인 수박주스는 꼭 드셔보세용. 리얼수박주스네요♡ 카운터 서버언니도 넘 친절하세요. 한국말넘 잘하시네요🫰', 13, 10, 'GOOD', SYSTIMESTAMP);
