INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '홍대 베이글랜드에서 플레인베이글이랑 솔트프레첼을 먹었어요! 쫄깃쫄깃한 식감에 고소한 맛이 살아있어서 정말 만족스러웠어요. 솔트프레첼은 겉은 짭짤하고 속은 부드러워서 커피랑 찰떡궁합이었어요☕ 베이글도 맛있지만 매장 분위기도 좋고 직원분들도 친절해서 기분 좋게 다녀왔요. 베이글랜드 베이글 찾는 분들께 추천해요!', 27, 3, 'GOOD', SYSTIMESTAMP);
