INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '아보카드 베이글과 따뜻한 아메리카노를 시켰어요 풍부한 아보카드와 커피맛이 잘 어울러져서 좋았어요 직원분도 친절하시고 메뉴도 다양해 다음에 또 오고싶어요', 9, 0, 'GOOD', SYSTIMESTAMP);
