INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '베이글이랑 커피 다 맛있어요. 매장이 넓고 손님도 많아서 딱 봐도 맛집입니다. 오전에 오시는거 추천해요. 늦게 오면 다 팔리고 없대요ㅠ', 45, 9, 'GOOD', SYSTIMESTAMP);
