INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '블랙올리브 베이글 먹었습니다. 베이글이 질기지 않고 부드럽네요. 가끔 생각날 때 와서 먹고 갑니다. 혼밥하기 좋은 분위기입니다.', 33, 1, 'GOOD', SYSTIMESTAMP);
