INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '약속 전에 홍대를 떠돌다가 발견한 베이글집이에요 혼자 와도 자리가 많아서 편하게 있을 수 있네요! 지인끼리 오시는 분들이 많아 홍대베이글카페 찾으시는 분들 적격입니다', 55, 12, 'GOOD', SYSTIMESTAMP);
