INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '먹고싶은게 생각이 안나서 찾다가 메뉴 사진보고 바로 들어왔습니다. 두명이서 저녁 약속 전에 아점 먹을 겸 온거라 연어 샌드위치랑 아보카도 샌드위치 밖에 못시켰는데 베이글들 구경해보고나니 왜 두 명이서 왔지 여럿 데려와서 하나씩 시키고 다 먹어보고싶다했습니다..🫤 종류가 많아서 다음에 도장깨기하러 올 생각입니다. 주문한 베이글 샌드위치들은 두툼하니 한 입에 넣으려면 입을 좍 벌려야하지만 넣고나면 들어오는 속재료 맛이 . . 쥑입니다. 연어는 살살 녹고 아보카도는 부드럽게 들어오는데 입안이 너무 행복하고 서비스인건지 같이 주시는 칩들도 서비스라기엔 너무 맛있습니다. 인테리어가 약간 놀이공원 식당가에서 식사하는 느낌이라 사가는 것보다는 먹고가는 쪽을 더 추천합니다🥯', 29, 1, 'GOOD', SYSTIMESTAMP);
