INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '늦게 방문해서 빵 종류는 많이 없었어요🥯 그만큼 인기가 많다는 뜻이겠죠ㅠㅠ 손님들 계속 오더라구요 다음에 방문해서는 샌드위치 먹어보고 싶어요ㅎㅎ!', 46, 2, NULL, SYSTIMESTAMP);
