INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '평소 베이글 좋아해서 자주 방문하는 곳. 베이글 종류도 다양하고 맛있고 공간도 넓어서, 혼자 카페에 있고 싶을 때 와서 베이글이랑 커피 먹으면서 시간 보내곤 해요. 저의 최애 카페 줄 하나 !', 41, 8, 'GOOD', SYSTIMESTAMP);
