INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '베이글을 너무 좋아해서 괜찮은 베이글 가게가 있다길래 왔는데 종류도 엄청 많고 너무 맛있어요! 홍대에 올때 종종 방문해서 사먹으려구요🥰 직원분도 친절하시구 인테리어도 넘 좋아요! 다음엔 샌드위치류로 먹어보겠습니다💕', 322, 97, 'GOOD', SYSTIMESTAMP);
