INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '친구와 놀러나와와서 찾은 맛있는 베이글 맛집이예요~ 크힘브륄레 페페로니 툭이하고 맛있네요~ 다음에 또 만나면 여기로ㅠ오려구요!!', 77, 17, 'GOOD', SYSTIMESTAMP);
