INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '베이글이 쫀득쫀득하고 연어도 안 비려요 :) 소스도 양껏 들어있어 잘 안 흐르기에 잡고 먹기 편했습니다 평일 점심엔 웨이팅도 없어서 간단하게 끼니 해결하기에 좋습니다👍', 3, 8, 'GOOD', SYSTIMESTAMP);
