INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '매장이 넓고 좌석이 많아서 여유롭게 식사할 수 있었어요. 혼자 식사하시는 분들도 몇 분 계셔서 혼자 먹는 것도 전혀 불편하지 않았고 편하게 잘 먹었어요. 베이글 종류도 다양하고, 베이글 샌드위치 메뉴도 풍부해서 만족스러웠습니다.', 83, 17, 'GOOD', SYSTIMESTAMP);
