INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '들어오자마자 분위기가 있으면서 쾌적한 넓은 매장에 기분부터 좋았어요! 베이글 종류도 다양한데 비주얼도 모두 맛있어 보여서 고르는 시간도 즐거웠어요. 여기 바질 리코타 베이글이 바질향이 깊게 나서 맛있네요! 직접 오븐에 구워서 먹을 수 있게 되어 있어서 진열되어 있더라도 금방 따듯하게 만들어 먹는 점도 마음에 들어요 홍대쪽에서 베이글 먹고 싶으면 앞으로 여기로 자주 올거 같아요ㅎㅎ', 87, 16, 'GOOD', SYSTIMESTAMP);
