INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '직원분이 친절해요^^ 메뉴가 맛있어요 인테리어가 멋져요 친구들과 데이트하기 좋아요! 물도 시원하고 레몬이 떠 있어서 호감! 인스타 맛집이라 걱정했는데 맛있네요~^^.', 30, 5, 'GOOD', SYSTIMESTAMP);
