INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '전부터 맛있다고 해서 가보고싶은 곳이었는데 매장 넓고 베이글 종류도 다양하고 좋아요! 혼밥러들도 편안하게 있을 수 있는 분위기라 좋아용 점심으로 치킨베이컨 샌드위치를 먹었는데 내용물도 알차고 베이글도 플레인이 아니라 에브리띵 베이글이라 더 맛있었어요😍 바질리코타가 유명한 것 같아서 하나 포장했는데 맛있어보여요😊 덕분에 주말 행복하게 보냈습니당', 45, 2, 'GOOD', SYSTIMESTAMP);
