INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '이 근처를 자주 지나다니는데 볼 때마다 와봐야지 했던 곳을 드디어 와봤어요✨ 오픈하고 바로 와서 종류는 많이 못 본 게 아쉬웠지만 그래도 베이글 때깔과 매장 음악, 분위기도 너무 좋아서 나중에 이른 시간에 업무하러 오기도 좋을 듯한!', 2, 5, 'GOOD', SYSTIMESTAMP);
