INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '홍대 핫플 베이글 맛집👍 역시 핫플답게 사람 많긴해도 내부가 넓어서 편하게 즐길 수 있었어요! 베이글 종류가 엄청 다양하고 샌드위치, 음료까지 있어서 취향대로 먹을 수 있을 듯! 저는 갈릭이랑 플레인베이글에 플레인 크림치즈로 먹었는데 둘 다 너무 맛있었어요💕😘 크림치즈가 꾸덕하니 맛있어서 꼭 한번 드셔보세요! 매장도 넓고 분위기도 외국에 온 것 처럼 좋아서 데이트하기 좋았답니다~~~ 포장하면 20프로 할인도 가능하고 세트메뉴도 있으니까 가성비있게 즐길 수 있을 것 같아요‼️', 357, 88, 'GOOD', SYSTIMESTAMP);
