INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '좌석끼리 너무 붙어있지 않고 분위기도 좋아요! 베이글 샌드위치는 주문 받고 바로 만든다는데 생각보다 오래 걸리지도 않고 따끈한 베이글 바로 먹을 수 있어서 좋았습니다 ㅎㅎ', 74, 15, 'GOOD', SYSTIMESTAMP);
