INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '홍대에 이렇게 넓고 쾌적한 베이글 가게가 있다니 💓 베이글이 겉바 속쫀 맛있고 커피도 맛있어요! 다음에는 베이글 샌드위치 먹으러 올 거예요 👍❤️', 2, 0, 'GOOD', SYSTIMESTAMP);
