INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '분위기도 너무 좋고 빵도 안질기고 너무 맛있네요 종류가 다양해서 선택할 수 있는 폭이 커서 좋았어요 시간이 걸려서 온 만큼 후회 없어서 다음번에도 방문하려구요!!', 49, 7, 'GOOD', SYSTIMESTAMP);
