INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '지나가다가 간판이랑 가게 분위기에 홀려서 들어갔는데 생각보다 너무 맛있었어요!! 특히 BELT 샌드위치가 너무 맛있습니다 엄마도 카페 분위기가 너무 좋다고 하시네요 맛있게 잘 먹었습니당', 39, 6, 'GOOD', SYSTIMESTAMP);
