INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '이른 시간에 오픈해 있어서 들어왔는데 직원분도 너무 친절하시고 음식이 빨리 나와서 좋았어요. 게다가 맛있기까지 하고요. 매장이 넓어 편안히 쉴 수 있었습니다!', 58, 12, 'GOOD', SYSTIMESTAMP);
