INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '베이글도 쫄깃하고 크림치즈랑 너무 잘어울려용💖 커피도 넘 맛있고 맛있어서 집에 또 포장하려구용! 너무 친절하시고 또 재방문할게용ㅎ.ㅎ', 42, 7, 'GOOD', SYSTIMESTAMP);
