INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '샌드위치 진짜 신선하니 구성도 알차고 스프도 뜨겁게 나왔어요!! 진짜 든든하고 넘 맛있는데 직원분들도 너무 친절하셔서 기분이 너무 좋았습니다🫶 매장이 넓어 쾌적하게 느껴졌고 화장실도 매우매우 깔끔했어요! 청결에 많이 신경쓴게 느껴졌습니다😊 영업시간이 길어 언제든 드나들기 좋은 장소인 것 같아요👍', 40, 3, 'GOOD', SYSTIMESTAMP);
