INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '늦은 오후에 왔는데도 베이글 종류도 많고, 직원분들도 친절해요! 매장도 넓어서 앉을 자리도 많아서 좋아요. 고구마 베이글 구매했는데 빵도 쫀득하고 한끼 식사로 딱입니다🤤😍!!', 4, 0, 'GOOD', SYSTIMESTAMP);
