INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '오랫만에 홍대 놀러왔다가 들렀어요. 시그니처인 만두베이글은 포장했어요. 매장이 넓고 쾌적해서 편안했고, 직원분들 친절하시니 기분이 좋아집니다. 샌드위치 종류가 다양해서 식사로 오기에도 좋을 듯', 24, 8, 'GOOD', SYSTIMESTAMP);
