INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '어떻게 이렇게 맛있을 수가 있죠? 월요일에도 영업해주셔서 감사합니다. 빵순이인 저에게 한줄기의 빛입니다. 이렇게 무더운 여름. 버틸 수 있는 맛입니다.', 51, 15, 'GOOD', SYSTIMESTAMP);
