INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '매장이 깨끗하고 좌석도 생각보다 많아요! 주말 12시 30분 쯤 왔을때에는 베이글 메뉴도 많고 인기메뉴인 두바이 베이글이랑 크림 브륄레 메뉴도 있었어요! 베일글 맛도 맛있었습니다!', 88, 16, 'GOOD', SYSTIMESTAMP);
