INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '볼일이 있어서 나왔다가..갑자기 베이글 샌드위치가 끌려수 검색해서 왔어요. 메뉴판도 제대로 안보고 샌드위치 하나, 아아메 하나 시켰는데 영수증 보고 세트가 있다는걸 깨달았어요 ㅎㅎ 세트라고 말 안하면 세트변경 안해주는 가게도 가끔 있던데.. 알아서 세트적용해주셔서 감사했어요🫶🏻 샌드위치 옆에 베이글칩이 몇개 같이 나왔는데 다 다른맛이라.. 먹어보지 못한 베이글들 샘플러 먹은 기분이었어요! 잠깐 머물렀지만 편안하고 기분좋은 점심이었습니다:) 다음에 또 올게요!', 32, 4, 'GOOD', SYSTIMESTAMP);
