INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '더운 여름에 방문했는데 너무너무 시원하고 직원분도 너무 친절하셨어요 ㅎㅎ!!! 베이글도 가성비 좋고 다 맛있어보여요 !!! 방문해보세용', 24, 10, 'GOOD', SYSTIMESTAMP);
