INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '홍대 올 때 이제 꼭 들리게 된 곳이에요! 베이글은 당연히 맛있고 샌드위치도 맛있어서 자꾸 찾아오게 되는 곳..🥹 다음에 또 기회가 되면 오고싶습니다!', 124, 21, 'GOOD', SYSTIMESTAMP);
