INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '체더 할라피뇨 베이글이랑 베이글 칩 시켜봤는데 원래 할라피뇨 안좋아하는데도 적당이 매콤하고 맛있고 베이글칩은 여러가지 베이글 다 먹어볼 수 있고 바삭해서 계속 먹게되요', 36, 2, 'GOOD', SYSTIMESTAMP);
