INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '너무 맛있을 것 같아서 왔는데 딱 원하는 메뉴가 다 남아있더라구용ㅜㅜ 다행이었어요! Sns 영상으로 본 거랑 똑같아서 더 좋았어용', 72, 11, 'GOOD', SYSTIMESTAMP);
