INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '홍대에서 우연히 들른 베이글랜드, 기대 이상이었어요! 베이글 종류도 다양하고 속재료도 신선해서 하나하나 골라 먹는 재미가 있네요. 식감은 쫄깃하고 담백해서 커피랑 찰떡이고, 매장 분위기도 아늑하고 깔끔해서 친구랑 수다 떨기 딱 좋아요. 다음엔 다른 메뉴도 먹으러 또 올 예정입니다 :)', 36, 8, 'GOOD', SYSTIMESTAMP);
