INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '베이글 좋아하는데 여기는 특색있는베이글이 있어서 좋아요 ㅎ 크림브릴뤠 베이글 먹고싶어서 얼른뛰어갔는데 마지막하나 있는거 겨우 득! 해서 먹었어요 ㅎ 너무맛있어서 베이글 종류별로 포장하고 가네요 ㅎㅎ 음료도 너무맛있고 친구 가족 연인 배우자랑 같이오면 좋을거같아요 ㅎㅎ 연어베이글도 지나가면서 하나씩 사먹는데 맛있어서 보이면 한번씩 꼭 사먹게되네요 ㅎ', 12, 4, 'GOOD', SYSTIMESTAMP);
