INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '연어 샌드위치가 먹고 싶어서 방문했어요! 음식도 너무 맛있고, 제 옆에 외국인 손님과 작은 대화를 주고 받았는데 스몰토크가 가능한 분위기여서 꼭 작은 뉴욕 같았습니다..❤️ 오늘 방문해서 너무너무 행복했어요! 재방문 의사 가득합니다~!!', 32, 0, 'GOOD', SYSTIMESTAMP);
