INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베이글랜드 홍대점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '베이글을 너무 좋아해 가지고 오랜만에 홍대 지나가는 길에 베이글 맛집을 찾았습니다. 아점 겸 방문했는데 맛있는 베이글이 있어서 너무 좋았어요. 블루베리 베이글이랑 솔트 플랫 주문해서 포장했어요! 베이글 맛집 답게 사람이 너무 많았고 외국인들도 많네요!!! 존맛탱 베이글', 51, 17, 'GOOD', SYSTIMESTAMP);
