INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '손님이 많네요~^^  주문하고 좀 기다렸다가 받았어요 요거트망고 아이스크림하고 망고요거트 믹스아이스크림 먹었는데 새콤달콤하고 너무 맛있어요~^^', 33, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '여름엔 고망고망고🥭💛 🏡 공간- 경희선숲길 초입 홍대지하철출구 앞쪽 길변에 있는 테이크아웃전문점이에요. 🍽️ 맛- 망난희 컵빙수, 식후땡 망고 주문. 빙수는 망고아이스크림,냉동망고,망고퓨레,코코넛밀크,얼음 구성으로 시원상큼달달💛 먹다보면 망고 아이스크림과 코코넛밀크 섞여서 살짝 무거워지는 느낌도 있어요. 개인적으론 할로할로가 과일도 여러가지고 더 라이트해서 맛있! 식후땡망고는 다 아는 망고주스맛🧡 고망고 걸어다니거나 잠깐 공원 앉아서 먹기 딱이고 가성비 아주 좋아요! (지극히 개인적인 후기입니다)', 71, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '곧 여름☀️망고 덕후라면 꼭 들르는 고망고🍹🥭 🏡 공간 - 홍대역(공항철도)출구 바로앞에 벤스쿠키 옆라인에 있는 노랑노랑한 작은가게에요. 🍽️ 맛 - 할로할로, 망고in망고 주문. 할로할로 맛있을꺼 같아서 시켜봤는데 굿굿👍🏻 우베아이스크림 처음인데 고구마+타로맛 같은? 고소달콤해서 정말 맛있어요! 코코넛 젤리, 팜씨드, 망고, 용과, 펄,떡등 다양한 재료가 들어가 있어서 식감도 다양하고 달콤하면서 시원한게 베리굿이에요💜 망고in망고는 냉고망고가 꽂혀있는 망고주스. 냉동망고여도 망고고유의 맛도 살아있고 상큼한 맛이 잘 살아있어요. 더워서 그런지 오히여 몰캉몰캉하지 않고 망고 아이스크림 느낌이어서 좋았어요. 🤵🏻‍♀️서비스 - 키오스크 주문이고 찾아서 바로 나오는 시스템이에요. (지극히 개인적인 후기입니다)', 76, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '망고 하나 집어먹고 찍은 양. 3000원에 주는 망고 요거트 아이스크림인데 망고양이 제법 괜찮음. 가성비 굿. 망고는 어떤건 달고 어떤건 맹맹.', 37, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '고망고는 사랑이에요ㅠㅠㅠㅠㅠㅠㅠㅠ 진짜 망고맛 너무 잘 나고 맛잇ㅅ어요😍😍 점심 지난 오후에 들른 것 같은데 망고아이스크림은 품절이라 못 먹었어요ㅜㅠ 근데 집에 돌아갈 따 되니까 다시 하는 것 같더라구요 고망고 아이스크림은 진짜 맛있어요.. 다음엔... 꼭 먹으러갈게여', 27, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '맥주 한 잔 하고 후식으로 아이스크림 먹기 좋아요. 초코 시럽은 좀 별로긴 합니다만... 손님 진짜 많아서 주문 먼저하고 대기해야해요.', 20, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '예전에 한번 저녁에갔을때 여자분이 제가주문하고 잘 안들려서 부르셨는데 안갔더니 탁자을 탁!치시면서 몇번아니세요?이래서 그게 좀..제 마음에크게마상으로된것같아서 안갔는데 인스타랑입소문으로계속뜨기도하고 날이덥기도해서 갔는데 ~이번엔남자분이받으셨는데 친절하시더라구요 제옆에50대로보이는부부도서비스측면에서만족해하시면서가시는것같았어요~양도많고!망고만족했고 가성비에서도좋았습니다', 37, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '신메뉴들이 다 신박하고 바로옆 화단에 앉아 먹으니 너무 좋아요. 가격도 딴데보다 싸요. 지금 이게 5900원인가 그랬어요 미친가성비. 맨날가고싶어요', 51, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), 'Q빙수가 3500원이라 1인분인줄알앗어요 근데 스푼을 두 개 주실때부터 알아봣어여햇됴… 양이진짜많네요 2인분이엇군요 혼자먹는데배부르고춥고머리아파서혼낫어요 하지만너무나도맛잇어요 아이스크림이왜이리부드럽나요 냠ㅁ냠굿', 9, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '여기서 파는 제일 작은 망고주스가 한 번 마시기에 딱 적당한 양이고, 맛도 맛있어서 종종 사먹어요! 요새 날씨가 더워서 집에서 시원하게 마시려고 한 번에 4개씩 사두기도 하는데, 오늘은 안경 쓰신 직원분께서 친절하게 음료를 건네주시면서 먼저 담아드릴까요? 하고 물어봐 주셔서 감사했어요😊 덕분에 집에 와서 기분 좋게 마셨습니다!', 40, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '요즘 연남동에 오면 고망고 꼭 먹어야 된다는 말 아시죠? 저는 정말 기대도 안 했는데 직접 먹어보니 망고가 맛있다는 동남아보다 훨씬 맛있었어요 망고맛이 정말 찐하고 가격도 착해서 가성비도 좋고 한번 맛보면 아마 앞으로 연남동 가면 무조건 고망고 가시게 될듯!!', 14, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '주말 낮에 방문했습니다 줄이 엄청길어요 ㅠㅠ 대기하고 먹었는데 징쨔 맛있게 먹었어요 다른곳이 비해 망고맛이 많이나서 좋아요 다음에 또 올게요', 65, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '할로할로빙수 궁금해서 먹어봤어요 타로 아이스크림이랑 우유얼음으로 되어 있고 토핑이 알차게 들어있어요 ㅎㅎ 양도 꽤 많고 많이 달지 않아서 맛있어요 !', 127, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '가성비 최고.. 이 가격에 어디서도 이런 퀄리티 못 먹어요! 홍대 갈때마다 들르는 곳이에요 웨이팅 있어도 기다릴만 한 곳 ㅎㅎ', 42, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '오늘도 마라탕 먹구나서- 디저트는 고망고에서 해결하는ㅎㅅㅎ 쵸코🍫 망고 아이스크림 시켰는데, 시럽을 넉넉히 뿌려주셔서 달콤한 게 너무 좋았어요오👍밖에서 먹긴 좀 추웠지만ㅋ맛있게 먹었습니당:3', 26, 6, 'GOOD', SYSTIMESTAMP);
