INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '원래 아이스쿠림은 추울 때 먹어야 제맛입니다~ㅋㅋ 여기 GO망고 매장은 마라탕 먹구나서 자주 들러용! 오늘은 초코 망고로 시켰는데, 달달구리해서 맛있었어요ㅎㅎ 망고🥭는 그저 사랑입니댜아-💛✨️', 12, 7, 'GOOD', SYSTIMESTAMP);
