INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '지나가다가 할로할로 보기만 했지 처음으로 먹어봤는데 망고랑 다양한 과일, 그레놀라, 타피오카펄, 미니펄 다 들어 있어서 알차게 잘 먹었습니다!', 11, 8, 'GOOD', SYSTIMESTAMP);
