INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '매번 식후땡 망고만 마시다 망고 코코넛 처음 마셨는데 너무 제 취향이었어요! 부드러운 코코넛과 망고가 정말 잘 어울리더라구요👍 요새 날이 점점 차가워지는데 더 추워지기 전에 얼른 고망고 드세요!', 40, 10, 'GOOD', SYSTIMESTAMP);
