INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '빙수 완전 크고 갓성비인데 맛은 없어요… 망고인데 홍시맛나고 연유도 안뿌려주셔서 무맛이었어요 망고사고는 대존맛입니다!!!🧡 연유낭낭해서 진하고 달달한 편이에요 나중에 두개 섞어먹었다는…', 107, 25, 'BAD', SYSTIMESTAMP);
