INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '평소에 먹던 거 말고 망고코코넛 먹어봤는데 코코넛폼이 망고랑 너무 잘 어울리고 맛있었어요 :) 연남동 근처 산책하고 돌아다니면서 한잔 하기 좋고 주문하고 음료가 정말 빨리 나와요', 12, 9, 'GOOD', SYSTIMESTAMP);
