INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '눈에 띄는 노란색 인테리어와 합리적인 가격때문에 몇 번 구입해서 마셔봤는데 맛있어요~ 식후땡 망고는 1,500원에 식후에 마시기 적당한 양이었고 이번에 먹어본 망고in망고는 망고스무디+생크림+망고 한 조각이 올려져 있는데 이것도 맛있었어요:) 사진만큼 푸짐한 양은 아니었지만 3500원에 이 정도면 혜자라고 생각해요 ㅎㅎ 재방문 의사 있습니다!', 28, 10, 'GOOD', SYSTIMESTAMP);
