INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '둘이 먹다 둘이 살아도 모를 맛 무슨 소리냐구요? 맛있다는 소리입니다! 망고맛만 있는 줄 알았는데 코코넛도 있어서 너무 좋아요', 89, 15, 'GOOD', SYSTIMESTAMP);
