INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '사진을 깜빡하다니.. 홍대가면 종종 들르는 곳이에요. 연트럴파크 바로 앞이라 매장좌석이 없어도 공원 벤치에 앉아 자연?을 즐기며 저렴하고 맛있는 망고주스을 먹을 수 있습니다.', 22, 7, 'GOOD', SYSTIMESTAMP);
