INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '앞에 앉아 있는 사람 80프로가 음료 기다리는 사람입니당. 포장 하고 싶은데 포장은 안 되는 것 같아요. 알바생 분들 힘내세요ㅜ', 109, 21, NULL, SYSTIMESTAMP);
