INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '저렴하고 맛있어요! 우유얼음이였으면 더 맛있었겠지만 저렴해서 쏙들어감,, 요즘 날씨에 시원하게 앞에서 앉아서 여유롭게 먹으니까 좋네요~!!', 53, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '궁금해서 먹어봐요. 1리터망고수박 양 많고 올려진 망고도 맛있어요. 넘 더웠는데 딱이네요. 망고아이스크림은 맛있었는데 생크림인지는 모르겠는데 안들어가도 맛있을거 같아요.', 48, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '밥 먹고 배부른 상태였는데 깔끔하게 후식으로 좋았어요! 다만, 키오스크에서 삼성페이로 결제하려니까 안되는 번거로움이 있었어요🥲', 47, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '망고디저트? 전문점 사람 꽤 많더라고요 외국분들도 사드시고 1500원에 이 정도 퀄리티 망고쥬스 연남동에서 마실 수 있으면 가성비 좋은 것 같아요 테이크아웃했고 먹는 장소는 따로 없는 것 같았어요 여름에 인기 더 많아질 것 같네요', 100, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '테이크아웃밖에 안되지만 손에 들고 다니며 먹기 좋아요~ 너무 큰사이즈는 부담되는데 작은 사이즈도 있어서 좋아요!!! 길가에 있어서 사람이 몰리면 조금 불편하지만 그뿐 음료는 맛있어서 만족!', 51, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '300ml에 1500원이라는 숫자만 보고 주문했는데 생각보다 엄청 작고 목만 살짝 축이고 싶을 때 사먹으면 좋을 것 같아요. 컨셉이 망고라서 노란 과일 포장지에 싸서 나온게 귀여워요. 맛은 너무 달지 않은 얼린 망고 간 맛이에요!', 33, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '망고 주스/빙수/음료 다 너무너무 맛있어서 낮에먹고 밤에 또먹음 ㅋㅋㅋ 날씨가 점점 더워지는데 계속 맨날 먹을듯!! 망고코코넛이 제일 맛있어요 강추', 45, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '연남동 필수코스 :) 동네에도 고망고있는데 맛이 연해서 늘 홍대 올 때만 줄서서 사서 마셔요. 같은 고망곤데 망고는 왜 묽을까요? 마곡도  개선되면 좋겠어요.ㅜㅜ', 81, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '대기 한참~~ 없는줄 알았더니 반대편에 서있는 사람들이 다 주문하고 받을려고 기다리는 사람들이었어요. 직원이 호출번호 잘못 눌러서 우리보다 늦게 주문한 사람이 받아가고 몇번 얘기 했는데도 계속 이미 픽업한 번호 연신 눌러대고 바쁜거 이해하지만 고객말은 들은듯 만듯 대답만 하나봐요. 맛있고 가성비 너무 좋은데 오래 기다리고 그것도 이해되는데 직원 때문에 기분 상했어요', 62, 12, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '⭐️내돈내산⭐️ 제가 사는 곳 근처는 없어서 들어만 보다가 처음 먹어본 곳인데 맛있네요! 특히 식후땡 망고라는 메뉴가 있어서 좋았어요. 밥 먹고 음료까지 먹으면 배부른데 식후땡은 말 그대로 후식으로 먹기에 알맞은 양이더라고요. 평소에 망고류의 음료를 좋아하신다면 추천합니다🥭', 23, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '연남동 갔다가 시간이 좀 애매해서 어슬렁 거리던 중에 사람들이 많이 모여있길래 가봤더니 망고디저트 전문 테이크아웃점이더라구요~ 궁금해서 먹어봤는데 가격대비 나쁘지 않았어요^^ 가맹점 창업에 급 관심 생겨서 대리점문의 전화번호 찍어왔습니다~', 46, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '연트럴파크 초입인데다가, 홍대입구역 바로 근처라 사람이 많습니다. 그래도 바로 앞 공원이 있아서 벤치에 앉아 기다리거나 먹을 수 있어서 좋네요~', 54, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '망고로 시작해 망고로 끝장을 볼 수 있어 좋았고 그외에 다양한 음료, 커피 등을 팔고 있어 골라 먹는 재미를 즐길 수 있었습니다. 이날은 망난희케이크와 식후땡망고를 주문해서 맛봤는데 둘 다 추운 날씨를 뚫고 찾아가서 맛 본 보람이 느껴질정도로 맛있었습니다. 망난희케이크는 시원하게 해서 맛을 보면 볼수록 취향저격이었고 식후땡망고는 말그대로 식사를 마치고 달달한 음료로 입가심하기 너무나 좋았습니다. 감사합니다.', 29, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
