INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '연남동 가면 하나씩 다 들고있는 🥭🥭 지난번에는 망고빙수 먹었는데 이번에는 망고주스~ 둘 다 시원하니 맛있었어요. 망고주스가 1500원이라니..🤭🤭', 41, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '망고케이크가 아주 실하네요 망고를 아끼지 않고 다 때려부었어요 비주얼도 이쁘고 맛도 좋습니다 시트는 우유생크림으로 되어있어 폭신폭신 맛있어요 케이크가 묵직해서 두 손 가볍게 오는것을 추천합니다 재구매의사 있습니다', 76, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '홍대 갈때마다 늘 들렸는데 이젠 안갈려구요... 여자 직원분이 소리 지르시면서 “도로에 있으면 음료 안줄꺼에요!!!!”, ”제말 이해 안되시나요??? 가시라구요!!!” 하고 손님들한테 고래고래 윽박 지르시는데 돈 내고 혼나는 기분 유쾌하지 못했습니다 다신 안가요ㅎ 음료는 참 저렴하고 맛있어요', 76, 12, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '망고밥이 진짜 망고 + 밥인줄 몰랐어요… 밥 형태? 모양? 연상하는 빙수일줄 알았는데 ㅋㅋㅋㅋㅋㅋㅋㅋㅋ ㄹㅇ 밥.. 보자마자 당황했네요 ㅋ튜ㅠ 제 입맛엔 너무… 별로여서 망고만 먹고 밥은 매장에 가서 버려달라 했습니다… 실제 있는 음식이니.. 좋아하는 사람은 좋아할듯한.. 호불호 갈릴 음식 같아요.. 네..', 86, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '연남동 가면 다 이거 들고있더라구요🤣🤣 근처 벤치에 앉아서 요거 하나들고 먹으면서 사람구경하기 좋아요! 냉동망고지만 아이스크림도 맛있고 가격도 정말 저렴해서 시원하게 즐기기 좋아요:)', 10, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '사람들이 줄서서 먹길래 인터넷을 검색해보니 맛있다는 리뷰가 많아서 식후땡 망고와 고망고밥을 주문했는데 둘 다 맛있었어요 식후땡 망고는 식사후 먹기 딱 좋은 양인거 같아요', 68, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '사람들이 바글바글 하길래 궁금해서 봤더니 망고쥬스를 저렴하게 팔아 주문해봤어요~ 양도 많고 맛있습니다. 사람이 좀 적은 시간에 가면 기다리는 시간도 줄꺼같아 다음엔 피크시간 피해서 가보려구요. 참고로 테이크아웃 전문점입니다!', 33, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 연남점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '아메리카노도 가격착하고 망고 작은 사이즈는 들고다니면서 먹기에 딱좋은 양이에요 아이디어 너무좋아요 단거 마시고싶을때 많이 마시는건 물릴수있는데 양이 아주 적절해요', 9, 10, 'GOOD', SYSTIMESTAMP);
