INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '하우스키루'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '통유리 창으로 따스로운 햇빛이 들어와서 좋았우요 인기가 많아서 그런지 평일에도 사람들로 가득하더라고요 책 읽기에도 편안하고 커피도 깔끔하면서 프렌치 토스트가 촉촉한게 정말 맛있네요🩵', 40, 8, 'GOOD', SYSTIMESTAMP);
