INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '하우스키루'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '어제 방문했을 때 카페 강아지가 저를 물었습니다. 다행히 큰 부상은 아니었지만 다른 손님들도 같은 일을 겪을 수 있을 것 같아 조심해야할 것 같아요. 전화로 말씀드리려 했지만 연결되지 않아 리뷰로 남깁니다. 강아지가 사람을 물 가능성이 있다면 보호자 분께서 더 신경 써주시면 좋을 것 같아요. 강아지를 좋아하시는 마음 이해는 하지만, 손님들이 안전하게 방문할 수 있도록 관리가 필요해 보입니다.', 37, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '하우스키루'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '음료값이 저렴하지도 않은데 양도 적어요ㅠ 커피는 원두에 문제가 있었는지 추출한 지 오래된 걸 부어줬는지 모르겠는데 크레마가 아예 없어서 놀랐네요,, 매실차 비주얼😅 밀크티도 생각보다 밍밍했지만 마들렌은 맛있었습니다', 0, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '하우스키루'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '코스타리카 브루잉은 맛있었는데 과테말라는 좀 아쉬웠슨.. 노트북 작업하기 좋았고 식물이 많아서 구경하는 재미가 있어요. 매장 인테리어 구경하는 맛도 있고 집이랑 가까웠으면 종종 갔을 것 같아요. 직원분도 들어갈때부터 나갈때까지 친절하셔서 불편함 없이 잘 이용했습니다.', 26, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '하우스키루'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '프렌치토스트를 주문했는데 먹다보니 짧은 머리카락이 나왔습니다. 남자 직원분께 말씀드렸지만 음식을 자세히 확인하지도 않고 접시를 바로 치워버리시더라구요 바로 비위 상해서 나왔습니다 나갈때도 사과 한마디 없으시더라고요 다신 안갈 것 같네요', 19, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '하우스키루'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '아메리카노가 핸드드립 맛이 나는 신기한 카페*_* 너무 맛있어요! 키루가 반겨주는 곳ㅎㅎ 똑똑한 보더콜이 넘 예뻐요! 햇볕 드리우는 공간도 좋아요~', 5, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '하우스키루'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '키루가 매너있어요 . 같이 데려간 반려견이 큰 개를 무서워하는 것 같으니 가까이 오지 않고 적정거리 유지해주면서 얌전히 잘 있어요 :) 아이컨택 하면서 기다려주는 스윗강아지 역시 🥦', 8, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '하우스키루'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '신촌과 홍대입구역 사이에 위치해 있는 감성카페 하우스키루 키루는 사장님의 반려동물인 강아지 이름으로 손님들이 오래 키루를 기억해주셨음 하는 마음으로 가게 이름에 넣으셨다고 한다. 들어서기전부터 입구에 앉아 맞이해주는 키루🐶 대전에서 이사를 왔다고 하는 하우스키루 대전도 언제 한번 카페투어 가보고 싶었는데 커피도 분위기도 요 근래 제일 마음에 드는 곳 중 하나인 하우스키루 집 근처였다면 정말 자주 갔을텐데🥺 더 자세한 정보는 최제로 블로그🙇🏻‍♂️🌼', 69, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '하우스키루'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '강아지 키루가 반겨주는 나른한 감성 카페🐕 대전 탄방동에 있던 카페 하우스키루가 서교동 경의선숲길 근방에 이전 오픈! 예쁜 가구와 조명으로 꾸며져 밝은 우드 톤에 컬러포인트가 있는 공간으로 통창으로 서교동 거리를 보며 멍때리기 좋았어요 주문한 커피가 모두 맛있어서 만족스러웠는데 필터커피, 라떼 모두 퀄리티가 좋아 커피를 주문하길 추천할게요👍', 13, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '하우스키루'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '홍대입구역과 신촌 사이 경의선 책거리와 가까운 위치에 있는 카페입니다. 메뉴로 핸드드립을 마셨는데, 6 가지 원두중 산미톤에 복숭아라 적혀있는 컵노트로 마셨는데, 취향에 맞아 맛있게 마셨습니다. 인테리어도 우드에 조합이 아름답고, 각 자리마다 매력이 있어 보는 즐거움이 있는 카페였습니다. 거기에 볕이 이쁘게 들어 마음까지 편안함을 주는 카페였습니다.', 13, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '하우스키루'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '대전에서 만날 수 있었던 하우스키루! 홍대에서 만나니 색달랐어요ㅎㅎ 강아지 키루의 얼음먹방을 코앞에서 볼 수 있는곳!! 디저트는 제 스타일은 아니었지만, 무더운 더위 식히기 좋은 공간이었습니다:) 인테리어가 마음에 들었어요!', 39, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '하우스키루'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '키루에 이끌려 오게된 카페 진짜 근래 본 강아지 중에 젤 활발하고 잘생겼음 (?) 카페 내부는 작은데 좌석이 많아서 앉는덴 불편하지 않았어요 바나나 푸딩은 굳히는 중이여서 아쉽게 못먹었습니다 ㅠ 친구는 카페라떼 전 플랫화이트 시켰는데 첨에 덜 섞였을때 먹을땐 쫌 산미 느껴져서 엥 별론가 .. 싶었지만 먹다보니 우유랑 섞이면서 맛있게 먹었어요 ☕️', 39, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '하우스키루'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '커피☕️가 산미 가득한데 그게 너무 맛있어요😋 레몬주스같은 산미 가득한 커피 한입에 푸딩🍮 한입 먹으면서 키루🐶도 보고 머무르는 내내 좋았어요🤍🫧', 44, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '하우스키루'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '아이씨 장난하나...가지마세요. 들어갈 때도 나갈 때도 사장은 손님인 우리에게 인사를 하지 않았다. 오히려 손님인 우리만 사장에게 인사를했다. 최소한의 친절함도 갖춰지지 않으면 맛도 별로라는 나만의 가설을 입증이라도 해주듯이, 자신있게 선보인 5가지가 넘는 싱글오리진 필터커피들 중 2가지를 맛 보았으나 전부 지나치게 쓰고 전혀 원두에 대한 이해가 느껴지지 않았다. 즉 원두가 아깝다고도 느껴지는 맛이었다. 나도 개를 좋아하지만 들어가자마자 몸을 털고 여기저기 누비는 이 집의 개는 귀여움과는 별도로 위생적인 측면에서 한자리에 묶어두는게 맞다고 나만의 결론을 내렸다. 물론 이 모든 결론은 불친절한 사장이 나는 싫어졌으니 전달하지 않았고, 재방문 의사 전혀 없음으로 표출해내기로 결론지었다.', 35, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '하우스키루'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '멋쟁이 강아지 키루가 있는 곳🐾 머무는 동안 강아지 동반 손님이 많이 오셨는데 저만 강아지가 없어서 아쉬웠어요🥲 매장 채광이 좋고 인테리어가 깔끔해요, 음료는 무난한 맛입니다!', 21, 8, 'GOOD', SYSTIMESTAMP);
