INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '하우스키루'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '밀크티 맛있어요 개인적으론 레몬말차타르트보단 딸기말차타르트가 타르트지, 말차크림의 매력을 더 살려줘서 좋았던 것 같아요. 분위기도 좋아요', 11, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '하우스키루'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '샌드위치가 먹고싶었는데 재료 소진이라 못먹어서 아쉬웠어요ㅠㅠ 프렌치 토스트는 다른곳에서 먹어봤던것들과 다르게 계란찜같이 부들부들하고 입에 넣자마자 녹았습니다...☁️ 키루도 너무 귀여워요 🖤🤍🖤🤍', 17, 8, NULL, SYSTIMESTAMP);
