INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '하우스키루'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '커피가 맛있어요 (산미맛이 강해요) 디카페인이 산미 맛이 약한 것 같아여:) 디저트 진짜 달콤하고 입에서 사르르르르르녹아여 키루가 킬포인트임다 🐶🐶🐶', 3, 1, 'GOOD', SYSTIMESTAMP);
