INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '홍대 브런치 맛집으로 핫해서  주말에 늦잠자고 브런치 먹으러 왔어요! 다양하게 주문했는데 한꺼번에 써빙되서 나와서 좋았어요~ 마카다미아 커피가 잠이 확 달아나게 달콤하면서도 고소해서 맛있었어요. 메뉴들이 하나같이 맛있고 흔한 감튀까지 바삭 달콤해서 디저트가게 들리지 않고 블루베리 갈레트까지 싹 먹고 왔어요 🥰😍😙', 108, 26, 'GOOD', SYSTIMESTAMP);
