INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '오늘은 브런치에요. 갓성비 런치콤보(@15,900) *로제파스타 살짝 매콤, 치즈의 짭짤, 베이컨이 씹히면서 식감을 살리고, 로제소스가 스프처럼 듬뿍들어가 느끼함 없이계속 음미하면서 먹게돼요 *아보카도토스트:통밀빵?에 바질페스토,루꼴라 아보카도 듬뿍, 홀그레인 머스타드,홀토마토마리네이드가 색감 좋게 올라와있고 건강하게 맛있어요 *프렌치 프라이 :얇은 스틱감자에 치즈가 뿌려나오는데 새콤달콤한 치즈맛 *쿠폰으로 받은 콘치즈프라이는 쭉쭉 늘어나는 치즈와 바삭 감튀, 옥수수에 치즈시즈닝이 솔솔 맛을 잘 잡아줘서 안받았으면 서운할뻔 했어요 *오늘의 쥬스는 내가 좋아하는 자몽인것 같아요. 맛있었던 순서 적어봤어요~ 어떤메뉴하나 소홀함 없이 맛과 비쥬얼,가격,양까지 챙긴것 같은 홀리건 브런치 양이 많아 다 못먹었네요 ㅎ', 43, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '훌리건은 몇번을 검색해서 찾아온 곳입니다. 골목 끝에 자리해서 무심코 지나면 놓치기 쉬운곳 입니다. 일요일. 아침도 점심도 아닌 애매한... 그야말로 브런치타임입니다. 생각보다 손님들이 꽤(?) 있습니다. 코르곤졸라 파스타와 아이스아메리카노를 주문하고 여기저기 사진을 찍는데 요즘 사진 이미지의 삭제와 생성기능이 있어도 여러사람을 지우기는 마음이 편치 않아 사람 없는 곳만 몇면 찍어봅니다. 사장님인지 직원인지 모르지만 그 누구도 훌리건 스럽지 않고 오히려 부드러운... 매장 구석구석도 훌리건 스럽지는 않고 오히려 편안합니다. 파스타면도 알단테!!! 소스도 꾸덕하니 맛있습니다. 조금 늦었으면 맛도 못 봤을... 일요일이니만큼 여유롭게 즐기고 싶은데 손님이 너무 몰려서 그냥 가야겠습니다. 잘 먹고 갑니다.', 16, 10, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '우현히 홍대 브런치카페 찾다가 알게된 곳인데 너무 맛잇네요!  제가 먹은 조합으로 드셔보시길 추천드려요 ㅎㅎ 분위기도 좋고 친절하셔서 담에 재방문 의사 있습니다 가벼운 한끼로도 좋아서 브런치 카페 찾으시면 방문해보세요⌒°(ᴖ◡ᴖ)°⌒', 39, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '홍대브런치카페로 유명한 훌리건커피 친구랑 주말에 방문했는데 역시 사람이 무지 많았음 외국 사람들도 진짜 많았고 가족 단위로 온 사람들도 있었고 메뉴가 진짜 다양한데 길티 플레이트랑 아보카도 플레이트 시켰는데 너무 예쁘게 나왔다. 에이드도 예뻐서 사진 찍는데 다 예쁘게 나옴 ㅎㅎ 브런치 메뉴부터 디저트까지 먹을 수 있는 곳이다. 크레이프 디저트 인 갈레트도 주문해서 먹었는데 아이스크림이랑 같이 먹으니 맛있었다.복숭아 진짜 달고 살살 녹음. 홍대 맛집이자 카페로 완전 추천!', 100, 20, 'GOOD', SYSTIMESTAMP);
