INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '홍대 브런치 맛집이라고 해서 찾아왔는데 진짜 너어무 맛잇는거 잇죠 ..!!! 진짜 무조건 방문하세요 !!! 요기 특히 미트 플레이트가 진짜 너어무 맛도리입니다아!! 브런치는 요기에용 !!! ⭐️♥️♥️ 특히 스크램블 진짜 무우조건 드세욥 !!!!', 59, 17, 'GOOD', SYSTIMESTAMP);
