INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '인테리어가 엄청 힙해요! 다른 곳과 다르게 신선한 메뉴도 많이 있어요😘 직원분들도 친절하고, 커피가 5천원 이라 가격도 비싸지 않아 좋아요❣️', 1, 6, 'GOOD', SYSTIMESTAMP);
