INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '아아는 진하고 깔끔해서 한 모금 마시자마자 잠이 확 깨는 맛✨ 복숭아 갈레트는 겉은 바삭, 안은 촉촉하고 달콤한 복숭아가 가득 들어 있어서 디저트로 딱이었어요 🍑 분위기도 조용하고 mZ감성 넘쳐서 느좋카페였어요!', 10, 2, 'GOOD', SYSTIMESTAMP);
