INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '너무 맛있어요! 모든 메뉴가 맛있고 배도 든든해져서 좋습니다 살짝씩 단 맛으로 킥을 넣어주는데(감튀가 진짜 최고) 재료도 신선하고 듬뿍듬뿍 있어서 너무 맛있게 절 먹었습니다 다음에 홍대 약속 생길 때마다 일행 데리고 오고 싶은 곳이에요 공간도 느낌 좋고 자리도 많아요', 27, 10, 'GOOD', SYSTIMESTAMP);
