INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '스테이크 맛집입니다! ⭐️길티플레이트 ⭐️스테이크 봄바 중 하나 꼭 드세요!! 추천 메뉴에 ✅️ 표시 있는데 그거 보고 시키기 잘했어요. 애쉬라떼도 진짜 맛있어요! 커피도 안 쓰고, 가벼우면서도 고소해요! 흑임자 갈레트 위에 올라간 아이스크림은 우유가 많이 들어가서 진하고 맛있어요!! 쿠키와 인절미까지 씹는 즐거움도 있답니다. 외국인 손님 70% 한국인 30%인데 왜 우리나라 맛집이 외국인에게 더 소문나서 그들만 많이 다녔나 억울해질 정도에요. 남편이랑 대만족하고 맛있고 즐거운 데이트하고 왔습니다!!', 58, 16, 'GOOD', SYSTIMESTAMP);
