INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '연남동에 위치한 카페답게 너무 분위기도 좋고 매장도 깨끗해요!ㅎㅎ 커피도 맛있고 덥고 입맛없는 날 오기 딱인 것 같습니다 💕 완전 강추요~~~', 21, 0, 'GOOD', SYSTIMESTAMP);
