INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '인스타 dm으로 1시 예약하고 왔습니다! 10분정도 늦었지만 받아주셔서 다행이에요!! 친절하고 맛있고 대화하기 좋은 장소에요 점심가 디저트를 한곳에서 한번에 해결할 수 있는 시간절약 가성비 플레이스 입니다! 홍대에 친구랑 먹으면서 떠들고 싶을때 딱이에요!', 104, 23, 'GOOD', SYSTIMESTAMP);
