INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '홍대 브런치 맛집이네요!! 다른 브런치 집들과 달리 메뉴 구성도 좋고 양도 많고 무엇보다 다 맛있어요! 인원수에 따라 세트 구성이 있어 다양하게 먹을 수 있어요~~ 홍대 브런치 완전 추천이요~~👍🏼👍🏼👍🏼', 10, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '벼르고 벼르던 훌리건 브런치를 드뎌 맛봤어요. 홍대에서 유명해서 줄서서 먹는다해서 오픈런 하려했는데 쩨금 늦었더니 벌써 서너팀이 와서 자리잡고 있더라고요. 그래도 넓은 자리에 앉아서 아주 맛있는 브런치를 먹고 커피까지 마시고 만족해서 나왔습니다. 아보카도과카몰리 빵 넘 맛있네요. 알바분들이신지 직원분들이신지 암튼 젊은 분들이 친절하게 맞아주시고 주방장님이 직접 서빙도 하더라고요. 기분좋게 즐기고 대접받고 나왔습니다.', 11, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '힙한 홍대앞 홀리건 커피에 브런치 먹으러 왔어요 아침 영화를 보고 들르기에 딱 좋아요 메뉴도 다양하고 맛도 좋아서 자주 찾아요 특히 직접 재배한 복숭아로 만드는 요리와 음료 강추', 72, 17, 'GOOD', SYSTIMESTAMP);
