INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '비주얼도 미쳤고 맛도 제대로였어요. 특히 에그인헬은 식빵 찍어 먹으면 진짜 최고예요🔥 분위기 좋고 조용해서 오래 머물기도 딱~ 브런치 좋아하는 분들 무조건 가보세요🙌 #홀리건커피 #브런치맛집 #서울카페추천 #에그인헬맛집 #감성카페', 12, 4, 'GOOD', SYSTIMESTAMP);
