INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '쇼콜라 갈레트는 이번에 처음 먹어봤는데 너ㅓㅓㅓ무 맛있어요 🥺🤍🤍🤍🤍 특히 바나나 위에 달콤한 코팅이 너무너무 맛있어서 아껴먹었어요 🤎😭🤍 그리고 올때마다 직원분들이 너무 친절하세요 추울때는 담요도 챙겨주세요 🥺🤍 좋아하는 곳이라 자주 왔는데 앞으로 더 자주 올게용🐱🤍🤎🤍 (그리고 모자쓰신 분이 너무 잘생기셨어요😳😳)', 15, 10, 'GOOD', SYSTIMESTAMP);
