INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '여기는 런치콤보가 다양한 메뉴를 먹어볼 수 있어서 너무 좋아요 특히 감튀 제취향이라서 맛있어요ㅎㅎ 쥬스도 올때마다 종류 달라서 재밌어요', 77, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '역과 가까워서 접근성도 좋고 근처 주차장들이랑도 가까워요! 좌석도 위아래 반층으로 넉넉합니다 음식 구성이 좋고 맛있어요 음료중에 애쉬라떼 완전 호!! 먹어본 더치라떼중에서 젤 맛있었어요!! 추천합니당👍', 26, 7, 'GOOD', SYSTIMESTAMP);
