INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '홍대에서 외국감성을 느끼고 싶다면 가야하는 곳. 일단 건물이나 내부가 감각적인 모습이 돋보이고, 이용객들 대부분이 외국인이었음. 말이 브런치지 푸짐한 양때문에 든든한 한끼 식사로도 충분. 스테이크 봄바는 너무 부드러워서 햄버거처럼 먹을 수 있어서 편했다. 날 좋을때 유럽감성 내러 가면 좋을 듯.', 99, 26, 'GOOD', SYSTIMESTAMP);
