INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '벌써 두번째 방문이예요! 우연히 찾은 장소인데 너무 맛있어서 데이트때 찾았습니당 : ) 모든 메뉴가 맛있는데 특히 스테이크봄바가 대박이예요... 커피도 맛있고 콘치즈프라이 미친맛... 꼭 드세요!!', 4, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '가성비 대박인 브런치 콤보 세트 진짜 넘 훌륭합니다👏👏👏 애견동반이되서 좋았고 라떼도 제가 좋아하는 고소한 맛이라 더 좋앟어요!! 브런치를 이렇게 좋은 가격에 즐길수있어서 너무 좋았어요!!', 55, 15, 'GOOD', SYSTIMESTAMP);
