INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '브런치 먹고 대만족, 아이스크림 먹고 대대만족..🩵 지난번에 구성 좋은 브런치에 반해서 맛집으로 픽했던 훌리건 커피 :> 오늘은 애쉬 아이스크림을 주문했어요! 올 때마다 직원분들 넘 친절하시구.. 애쉬 아이스크림도 맛있었습니당 아이스크림에 달달한 초코 커피 부은 맛이에요. 6천 원이라 그런가 아이스크림 양도 많아서 먹다 보니까 살짝 질림ㅋㅋㅋㅋㅠ 아이스크림만 먹고 싶기도 하네요.. 하지만 다 먹었답니다 ~ 강아지 동반도 되구 분위기도 좋은 멋쟁이 카페예용', 83, 13, 'GOOD', SYSTIMESTAMP);
