INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '비오는 날에 여자친구하고 늦은 점심먹으려고 간 곳인데 음식이 엄청 맛있어요...😭 진짜 크림파스타하고 저 옥수수 감자는 꼭 시켜드세요 세트메뉴로 시켜서 같이 드시면 정말 후회없을것 같아요', 22, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '음식도 물론 맛있지만 음향과 분위기가 좋아서 재재재방문하게 되는 것 같아요! 커피도 제 취향에 딱이고 브런치 메뉴들도 전부 깔끔하고 적당합니다! 앞으로도 계속 올 예정..', 46, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '올데이 2인 콤보 먹었어요~ 봄바, 파스타 다 맛있고 커피도 맛나고, 가게 분위기도 좋아요 외국인 분들도 많이 찾으시는데 이유가 있는 듯 ㅎㅎ', 23, 10, NULL, SYSTIMESTAMP);
