INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '분위기도, 맛도 너무 좋아서 자주 오는 곳인데 처음 먹어보는 수비드 치킨 바질크림 파스타도 맛있네요!! 메뉴가 전체적으로 다 맛있고 음악도 좋아요!', 47, 8, 'GOOD', SYSTIMESTAMP);
