INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '간만에 만나는 반가운 지인과 오랜만에 찾은 홍대 브런치 카페!!! 오픈하자마자 사람도 진짜 많고!! 음식도 너무 맛있어서 대만족이예요♥️ 홍대 브런치 먹고싶을때마다 찾을 곳이예요:) 대신 인기가 넘 많아서 무조건 오픈런 하셔야합니다😂', 20, 5, 'GOOD', SYSTIMESTAMP);
