INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '힙한 분위기에 복층구조라 아지트같은 느낌을 주는 카페였어요! 크림커피 맛집이면서 브런치, 식사메뉴,디저트까지 메뉴가 다양해서 좋았네요! 저녁 먹을겸 찾았는데 넘 만족스럽게 먹고 왔어요!❤️👍🏻홍대 디저트 맛집 브런치 맛집으로 강추해요!', 43, 1, 'GOOD', SYSTIMESTAMP);
