INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '주말 낮에 방문했어요 처음 와봤는데 힙하고 이국적인 느낌이 너무 마음에 들어요!! 음식도 너무 맛있고 외국인들도 많아서 마치 외국에 온 느낌!! 접해보지 못한 다양한 메뉴도 있어서 좋네용', 20, 8, 'GOOD', SYSTIMESTAMP);
