INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '카페 분위기도 좋고 음식도 다양하고 카페음료도 있어서 언제든지 와도 좋을 것 같아요 배고픈데 카페 감성도 챙기고 싶어서 빠르게 찾아봤는데 생각보다 분위기가 좋아서 또 올 것 같아요', 23, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '처음 방문한 브런치카페였는데 커피도 맛있고 브런치메뉴도 맛있어요!! 팬케이크 이런거는 이제 너무많아서 질렸는데 색다르게 먹었어요~!! 완전 강츄~~!', 3, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '분위기부터 맛까지 진짜 최고에요 갈레트 먹으러 또 갈거에요 !! ㅠㅠ 홍대에서 분위기 좋은 브런치집 찾고 계시면 완전 강추합니다 ><', 3, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '음식 정말 맛있네요 브런치를 먹고싶어서 홍대근처 음식점늘 찾아서 왔는데 정말 최고에요!! 바질 파스타랑 커피가 특히 맛나네요 다음에 꼭 다시 올 것 같아요 ㅎㅎ 가성비도 최고 !', 73, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '분위기도 좋고, 음식도 정성스럽게 나와서 친구들이랑 수다 떨기에도 딱이에요. 다음엔 다른 메뉴도 꼭 도전해보고 싶어요 :)😊😊🤍', 45, 10, 'GOOD', SYSTIMESTAMP);
