INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '친구가 추천해 줘서 왔는데 정말 맛있었어요! 유명한 곳이라 그런지 사람이 많아 대기를 좀 해야 했지만 기다린 보람이 있네요😚 직원분들도 친절하셨고 시킨 음식도 다 맛있어서 다음에 재방문 의사 있어요!👍🏻', 99, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '날이 좋아서 여유 즐길 겸 재방문했어요! 언제나 구성이 알차고 맛있는 훌리건 카페입니다! 또한 매장이 청결하고 인테리어가 감각적이에요 매장 음악도 좋아요', 22, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '일단 직원분들이 너무 친절하셨고 음식 가성비가 미쳤습니다!! 너무너무 맛있고 친구랑 대화하기도 좋아요 ㅎㅎ 재방문 의사 100!!', 25, 0, 'GOOD', SYSTIMESTAMP);
