INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '자주 오던 카페인데 항상 올때마다 친절하고 카페 분위기가 너무 이쁘고 음료나 디저트도 너무 맛있어서 홍대 올때 마다 오는거 같아용🩷😊', 27, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '음료 넘 맛있게 먹었습니다!! 매장 분위기도 좋아서 남친이랑 즐겁게 다녀왔어요 조명도 예뻐서 사진 잘나옵니다ㅎㅎ👊 리뷰이벤트로 나온 콘치즈프라이 맛있어요^^', 75, 12, 'GOOD', SYSTIMESTAMP);
