INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '가성비 너무 좋았던 훌리건  런치콤보😋😋 여러가지 옵션 있어서 선택할 수 있어 좋았고 다 맛있어어 최고🥰🥰 다음에 또 올거에요😘😘', 50, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '우연히 알게된 곳이어서 들렸는데 너무너무 맛있었어요 메뉴구성도 엄청알차고 편하고 아늑해서 분위기 맛집 음식맛집 커피맛집이에요👍👍👍✌️✌️✌️ 홍대 또 오면 재방문 100%입니다', 24, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '인스타에서 핫해서 방문했어요! 런치콤보로 주문했는데 메뉴 실하고 무엇보다 싸다고 맛이 뒤쳐지지 않아서 좋았어요 알찬구성에 가성비있어서 좋았구 재방문할게요!!', 29, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '음식맛있고 가격도 나름 합리적인데 그래서그른가 사람 많아서 음식을 30분정도 기다려서 받았어요ㅜ 여유좀 가지고 가시든가 한 오후 2시 이후로 가셔야할것같아요! 그 외엔 나무랄데없이 너무 만족스러웠습니다 :))', 15, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '인스타 릴스에서 평일 런치 메뉴를 보고 오려고 했으나 주말이라 런치 메뉴는 못 먹었어요 하지만 메뉴 자체가 비주얼과 퀄리티에 비해서 엄청 가성비가 좋았습니다 음식이 너무 맛있어서 뚝딱 먹었네요 연인과 데이트 하기에 너무 좋습니다 훌리건 커피 강추!', 46, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '씨푸드 아보카도 봄바랑 오늘의 수프(콘) 먹었는데 정말 맛있었어요🫶🏻 다음에 또 와서 다른 메뉴인 미트볼 볼로네제 파스타를 먹어보려고요:)', 43, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '인생 디저트 맛집 중 하나 찾았어요~~^^ 카페 분위기와 음악 선곡도 너무 좋고 음료 포함 갈레트까지 정성 가득 은은한 달콤함이 정말 맛있었어요! 다른 디저트들 맛보러 재방문할 예정입니다!!!', 75, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '아점으로 브런치 선택했는데 신의 한수 였습니다. 사장님 너무 친절 하시구여 음식이 개맛도리입니다! 에이드도 미쳤어요. 친구랑 먹으면서 인상 막 찌푸리고 이거이거 먹어봐 서로 이러고 진짜 행복한 아점이었어요..🙂‍↕️💖 콘치즈가 진짜 맛있으니까 다들 꼭 드셔보셨으면 좋겠어요 담에 또 찾아뵙겠습니다. 감사합니다 사장님🙇🏻‍♂️', 345, 89, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '유튜브 인스타에 동시에 뜨길래 궁금해서 와봤어요! 커피 맛있고, 런치콤보로 다양한 메뉴 시켜봤는데 아보카도토스트, 오늘의 수프 강추합니다!! 남는게 있으실지... 의문이 들 정도로 퀄리티에 비해 가격이 정말 저렴해요!! 근처 올 일 있으면 또 방문할 것 같네요! 아 런치콤보는 1인기준입니다! 인원수가 많다면 메뉴를 더 추가하시던지 콤보를 인원수대로 시키셔야해요!! 강추강추!! 그리고 가게음악 플레이리스트가 굉장히 취저임..', 113, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '식사도 해보고 디저트도 먹어보고 커피도 마셔봤는데, 디저트는 감동이었고, 커피는 만족이었으며, 식사는 나쁘지 않았습니다. 또 간다면 디저트 먹으러!', 33, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '사장님 추천으로 시킨 스크램블 플레이트! 맛이 없을수가 없는 메뉴다 따뜻한 아메리노에 잘 어울리면서 맛있게 잘 먹었습니다! 😋 다양한 메뉴들도 있는데 넘 궁금,,, 다음에 먹으러 올게영~', 5, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '요즘 인스타 릴스에서 홍대 가성비 런치세트 맛집이라고 가장 많이 뜨는 홍대 훌리건 ! 분위기도 좋고 커피도 맛있고 , 브런치로 먹을 샌드위치도 푸짐하고 굿굿 💛💛', 117, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '분위기도 너무 힙하고 메뉴들이 가성비가 너무 좋아요 !!! 직원분들도 다들 친절하시고 음악도 최고입니다 >< 🫶 음식도 너무 맛있었어요 😭👍 최애 브런치집 될 너낌…', 46, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '매장 분위기도 좋고 브런치 카페라서 먹고 싶은 디저트랑 같이 식사를 할 수 있어서 좋았어요! 음식도 다 맛있어서 다음에 또 가려고요! 런치 콤보는 평일 점심에만 가능해요!', 116, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '카페 분위기도 중요하지만 저는 맛있는지가 제—일 중요한데, 진짜 맛있었어요🙌🏻 런치 세트 알차고 흑임자 갈레트도 맛있었어요ㅠㅠ 이벤트로 받은 콘치즈도 jmt👍🏻 분위기도 좋고 사장님도 친절하셔서 모든 부분에서 만족했습니다:) 재방문 의사 완전 있어용!! 평일 오전에 왔을때 대기 없이 들어왔습니다~ 층도 나눠져 있어서 자리도 충분하고 대화나누기 좋았어용! 굳굳 완전 잘 왔다고 생각드네요ㅎ', 84, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '친구에게 추천받아 방문했어요. 전반적으로 다 맛있었어요. 빵위에 아보카도소스? 상태는 좀 아쉬웠지만, 나머지는 다좋았어요. 런치세트는 가성비도 좋고요. 양도 먹어보면 든든하네요. 잘먹었습니다~', 39, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '입장은 대기없이 들어왔어요.런치주문이 11시14분인데 커피는 11시 59분에 음식은 12시35분에 나왔습니다.대기가 있을꺼라 말은 했지만 식사를 1시간반을 기다려먹게될줄은 몰랐네요.음식도 기대했던것보다는 그냥 그랬어요.아쉬웠습니다.', 19, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '런치콤보 가성비 엄청나네유 배가 너무 불러요~~ 다 맛있습니다!!! 사장님 친절하시고, 매장 분위기 편안하고 전체적으로 좋아요~ 대박나세유~🫠', 55, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '점심때쯤 브런치 생각하고 홍대 브런치 맛집 검색하다 가게 됐는데 ㅠㅠㅠ 진짜 존맛이네요. 다음에 또 갈거임. 런치세트 선택 범위 커서 가성비좋게 맛있는거 취향대로 골라먹을 수 있어서 너무 좋았습니다. 그리고 기본적으로 커피가 진짜 맛있어요. 산미없고 다크하면서 깔끔한 맛! 아주 흡족 스러운 한끼였어요 ㅠㅠㅠ❤', 9, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '홍대브런치 카페 찾다가 방문했는데 이미 너무나도 유명한 카페였네요 :) 브런치와 디저트, 커피가 모두 있어서 식사와 디저트까지 한번에 해결 가능한 곳이여서 주말에 방문하기 넘 좋았어요 ☺️ 게다가 가성비도 좋고, 카페도 넓고 무엇보다 음악이 너무 좋아서 분위기 짱이었어요! 반려동물 동반 카페여서 나중에는 강아지랑 같이 또 오고 싶어요 🥰🎶', 79, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '금요일 12시 54분에 도착했는데 1시 42분에 음식을 받을  수 있었어요..! 그만큼 맛집 인증합니다 !! 파스타도 양념이 맛있고 콘치즈감튀가 진짜 맛도리입니다🥹 그냥 다 맛있어요.. 웨이팅 외에도 완벽한 곳', 47, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '분위기 정말 힙하구 메뉴도 하나하나 정성 가득해요ㅜㅜㅜㅜ 재방문 의사 20000% 사장님 오래오래 일해주세요(?) 건강보다 가게가 우선!', 4, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '사장님이 너무너무너무 친절하셔서 완전 좋았습니다!!!ㅎㅎㅎ 음식도 당연히 맛있었습니다:) 분위기도 좋고 노래 정말 제 스타일 ㅎ,, 다음에 또 방문하겠습니당', 35, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '친구랑 너무 즐거운 시간 보냈어요~ 이쁜데 맛도 좋고 음식나오는데 시간이 오래걸리긴했지만 너무 좋았어요~새우도 튼실하고 음식 퀄 좋아요!', 73, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '외국친구가 한국 카페 체험하고 싶다고 해서 브런치도 먹을겸 왔는데 음료도 메뉴도 하나같이 너무 맛있어요 👏🏻 타지에 살아서 자주는 못 오지만 홍대 오면 꼭 방문하고 싶은 곳이에요 !! ✨ 분위기도 짱 좋아요 😚', 25, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '아보카도 좋아하면 아보카도 토스트 꼭 드세요ㅜㅜ 아낌없이 뿌려져 있는 아보카도는 물론 토스트 두개가 다른 버전임요 하나는 새콤하고 하나는 블루베리쨈이 들어가 있어서 새콤달콤 동시에 느낄 수 있답니다ㅠ', 48, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '맛이 친절하고 사장님이 맛있어요 이번이 두 번째 방문인데 브런치가 너무 맛있어서 브런치 메뉴 도장깨기 하고 있어요! 인테리어도 너무 멋지고 커피도 진짜 맛있어요.. 근본.. 양도 많고 무엇보다 감튀 맛집임…😋', 17, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '스테이크 봄바랑 에그인헬 정말 맛있어요 !! 같이 나온 통감자랑 마요소스가 어울려서 추천합니당 ☺️💓 매장 구조가 특이해서 데이트하기에도 좋을 것 같아용 다음에 또 올 예정입니다 🥰', 32, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), 'I discovered this place through instagram and I’m so glad I came! The food is really good. Everything looked so delicious! There are a variety of food on the menu from brunch to side dishes to desserts. The music is also fitting to the interior. It is very spacious with different seating area. Definitely check this place out! 😋', 394, 41, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '여기 진짜 힙하고 가성비 대박이에요ㅜㅜ 천번째 사진 가격이 14500인게 말이 되나요..? 커피 한잔에 4~5천원인데 파스타,샌드위치,감자튀김,커피가 14500원이라니ㅜㅜ 여기는 찐입니다🔥🔥 다른 메뉴도 존맛이고 인테리어도 힙해서 사진이 진짜 잘 나와요!!! 사장님,직원분들도 완전 친절하시고 홍대 가시면 꼭 가보세요!!! 다음에 다른메뉴 또 뿌시러 갈게용❤️', 355, 39, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '브런치가 너무 먹고싶어서 찾아보던중에 발견한 훌리건커피! 매장도 넓고 맛있어요! 무엇보다 직원분들이 친절하셔서 너무 좋습니다. 크림파스타랑 아보카도 .... 맛있어요!!!!', 53, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '홍대 핫플레이스 카페 훌리건커피 방문했어여 비주얼대박인 존맛땡 디저트와커피 힙한분위기연출 음식 사진촬영하기도 좋아요 데이트코스로 강추입니다 번창하세요', 35, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '홍대 브런치 맛집!! 런치세트로 파스타와 토스트 그리고 감자튀김을 함께 맛볼 수 있어서 구성이 정말 좋아요ㅎㅎ 스테이크 붐바도 짜지 않고 맛있고 감자튀김도 따끈따끈해서 함께 먹기에 잘어울려용', 85, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '여기저기 돌아다니다가 발견한 카페에요🌝 이찬혁 영감의샘터 건물 옆에 있는데 봄바 맛집이네요 여기 👍🏻👍🏻 최고임!!! 안에 새우랑 이거저거 속재료도 실하고 무엇보다도 봄바 안에 소스도 전맛탱 ㅠㅠㅠㅠ 사이드로 감튀도 있어서 한끼식사로 아주 딱임둥 그리고 마카다미아크림라떼도 첨 먹어보는데 크림에 마카다미아 갈린게 들어있어서 넘나 꼬숩고 달달하고 최고임 ㅠㅠ 도라방스... 여기 단골예정입니다...🩷❤️🩷 사장님도 넘넘 친절하시구 조와요 다음에 또 올게요!!!:)', 44, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '홍대입구역 8번출구에서 가까운 힙한 감성카페였어요! 매장 자체가 힙하면서도 깔끔하고 분위기 있어서 좋더라고요. 노래 선곡도 좋았어요 ㅎㅎ 브런치 메뉴나 디저트도 유명한데 저는 아보카도 플레이트 먹었어요! 두개 다 맛이 달른데 하나는 루꼴라가 들어가고 하나는 블루베리 잼이 들어가요! 두가지 맛이 다른것도 좋았습니다ㅎㅎ 시그니처 메뉴인 애쉬라떼도 다크초코여서 그런지 많이 달지 않아서 브런치 메뉴랑 충분히 드실 수 있어요! 따뜻한 라떼는 말해뭐해 조합입니다. 요즘같이 추운 날씨에 몸녹일 수 있는💛 매장 내에 제작 굿즈도 있었는데 인스타로 주문이 가능하다고 하더라구요! 컵이나 후드가 귀여워서 구매하고싶었어요 ㅎㅎ 브런치 카페로 아주 굿이였습니다:-)!!', 45, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '매장 분위기가 힙하고 음식도 다양해서 무드 있게 브런치 즐기기에 딱 좋아요! 골목 안 쪽에 위치해 있어서 뭔가 아늑한 느낌도 들고요 ㅎㅎㅎ 그리고 메뉴가 정말 다양해서 여러번 방문하고 싶다는 생각이 듭니다! 재방문 의사 200%예요 :)', 14, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '층이 나누어져 있어서 분위기 엄청 좋고 갈레트랑 마카다미아 라떼는 처음인데 너무 맛있었어요🥲 주신 콘치즈도 맛있게 잘 먹었습니다!', 59, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '봄바를 맛있게 먹었던 기억이 있어서 재방문 했어요! 봄바에 이어서 갈레트도 처음 먹어보는 메뉴였는데 엄청 특별하고 맛있었어요. 시즈널 갈레트의 과일이 무화과라서 더 좋았어요 🤤 콘치즈도 엄청 푸짐하고 맛있고.. 에이드도 언제나 맛있네요 🫶🏻🫶🏻', 43, 6, 'GOOD', SYSTIMESTAMP);
