INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '친구와 브런치하러 방문했는데 분위기도 좋고 음악도 좋고 브런치도 너무 맛있어요! 특히 씨푸드 아보카도봄바 샌드위치 너무 맛있게 먹었어요 :))) 재방문 할것같아요!!', 472, 100, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '직원 언니가 굉장히 이쁘시고, 선택장애라서 귀찮으셨을텐데 메뉴선택도 도와주심🥹 노래랑 공간이 다 힙하고 브런치도👍🏻 혼자가서 메뉴를 다양하게 못 먹어봤지만 흑임자쉐이크 맛있..🥹🥹 흑임자가 먹다보면 느끼? 좀 물리는데 양도 적당해서 호로록 다 마심ㅎㅎ 담에 다른 메뉴도 먹어보곱..💓', 20, 5, 'GOOD', SYSTIMESTAMP);
