INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '진짜 홍대의 숨은 브런치 맛집입니다~~ 갈레트도 너무 맛있고 다양하게 먹고싶다면 런치메뉴도 추천해요!! 매장도 깨끗하고 힙해요ㅎㅎ', 33, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '양이 작을 줄 알았는데 양이 진짜 많았어요💕 커피도 맛있어요 라떼도 꼬숩구요 ㅎㅎㅎ 수요일 아침 일찍 가니 자리는 여유 많았어요! ****사실 비쥬얼이 넘 귀엽고 예쁘니 맛은 그냥 평타일거라 생각했는데 파스타 두 개 다 진짜 파스타집가서 단품 먹는것처럼 맛있었어요!!!!! 특히 토마토 아보카도 오픈 샌드위치는 완전 프레쉬하고 싹 내려가는 기분., 진짜 젤맛있었어욬ㅋㅋㅋㅋ2쪽 단품으로 팔아도 뮤조건 사먹을 맛이에요 재료도 얇게 올린게아니고 엄청 가득해서 놀랐어요 ***** 콘치즈는 달달하고 맛있어요 일반 프라이엔 칠리소스 따로나오거나 뿌릴지말지 선택할 수 있어도 좋을 것 같아요 또 오고 싶어요! ㅠ__ㅜ 주말은 주말가격으로 3,000 정도 올려서 팔아도 방문의사 200%입니다!! 번창하세요!!', 20, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '평일 런치콤보+스크램블 플레이트 추가해서 메뉴 주문했어요! 처음가보는곳이라 런치 콤보 어떻게 조합해서 시켜야할지 몰라 직원분께 여쭤봤는데 친절하게 안내해주셔서 좋았어요! 커피도 디저트도 전부 맛있었어요! 1층만 있는줄 알았는데 들어가보니 지하까지 자리가 있더라구요 참고하시면 좋을듯 합니당!', 88, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '친구랑 홍대 놀러와서 들른곳인데 가성비도 좋고 맛도 좋아용!! 고르곤졸라 크림 파스타가 진짜진짜 맛있어요!! 다음에 홍대 오면 한번 더 들를거 같아용!!', 112, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '마시멜로가 들어간 고디바 핫초코 너무 맛있었어요! 직원 분들이 다 친절하시고 분위기 너무 힙해요. 힙한데 편한 분위기😉 커피는 말모말모 완전 부드러운 라떼💕 파스타 신메뉴 생긴대서 기대중이에요 다음엔 파스타랑 브런치 먹으러 올거에요🥹 아 그리고 매장 음악도 짱 좋아요', 45, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '지난번에 흑임자 갈레트 먹고 너무 맛있어서 🥹 오늘은 시즈널 갈레트를 먹으러 왔어요! 갈레트는 크레이프 주머니에 카스테라가 담겨 있는 메인에, 아이스크림과 토핑이 얹어 있는 메뉴인데요. 사장님이 맛잘알이신지 시즈널메뉴였던 무화과에는 호두마루st 호두크림과 꿀이 토핑되어 조합이 좋았고, 흑임자 갈레트에는 크럼블과 인절미 토핑이 열일해여 🖤 앞에 있는 이찬혁의 영감 아지트 감성과 어울리게 힙한 카페 훌리건의 갈레트 몹시 매우 추천드려효!', 42, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '진짜 나 여기 왜 이제 와봤냐 ? 커피 너무 고소하고 진하고 맛있어요 ㅠㅠㅠ 무화과 갈레트 .. 아이스크림 우유맛 진하고 푸짐한 무화과까지 완벽합니다 💡👍🏻👍🏻', 56, 16, 'GOOD', SYSTIMESTAMP);
