INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '콘치즈프라이, 쉬림프로제, 에그인헬 먹었는데 셋 다 너무 맛있고 그 중 콘치즈프라이가 진짜 맛있었어요 음료도 시럽 그런 게 아니라 진짜 과일이 들어가 있어서 넘 맛있어요🥺', 7, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '포슬포슬한 감자가 맛있었어요. 전체적으로 메뉴가 맛있고, 양도 구성도 알차서 좋았습니다. 추운 날 방황하다 찾은 리뷰 좋은 가게라고 해서 왔는데 오길 잘한 것 같네요👍🏻👍🏻👍🏻👍🏻👍🏻👍🏻', 3, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '점심에 가면 먹을 수 있는 가성비 런치세트 먹었는데 너무 만족스러워요 ! 남는게 있으실지 모르겠네요 ㅜㅜ 파스타도 맛있고 토스트랑 감튀 아메리카노까지 14900원 믿을 수가 없어요🤍❤️', 8, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '별점이었으면 별 하나 뺐을 거 같아요. 음식은 일단 맛있는 편입니다. 스테이크 봄바는 제 입에는 살짝 짠 거 빼고는 맛있었어요. 다만 메뉴 두 개 시켰는데 두 메뉴 나오는 시간 차이가 너무 길었네요. 둘 다 늦게나오는 게 아니고 제 친구가 먹는 속도가 많이 느린편인데도 거의 다 먹었을 때 제 메뉴가 나왔어요. 같이 식사하는 느낌은 아니었네요 😂', 4, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '너무너무 힙하고 멋진 곳!! 골목에 위치해 있어서 찾기 어려울 줄 알았는데 완전 찾기 쉽고! 가자마자 외국인들 앉아 있어서 너무 외국스러웠어요 ㅎ 음싣 다 맛있고 커피도 고퀄이라 또 방문 할것같아요!! 음악도 완전 라운지바 앉아서 노는 듯 기분좋았어요!', 47, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '힙한 홍대 카페입니다👍🏻 사진 찍고 싶은 핫스팟이 한두군데가 아니에요ㅎㅎ 브런치 먹을 겸 가서 스크럼블 플레이트 주문했습니다! 맛있어요:) 빵은 계란 스크램블 올려진 상태로 적당히 자르고, 베이컨, 버섯이랑 함께 먹으면 조합 너무 좋아요❣️깔끔 그 자체입니당! 앉을 수 있는 자리도 다양해서 취향에 따라 골라 앉으시면 돼요~ 저희는 한 층 아래 벙커 컨셉 자리에 앉았답니다-! 구석진 곳을 좋아해서...⭐️', 10, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '음식 플레이팅 넘 이쁘고 맛있어요 ! 브런치 메뉴랑 디저트 메뉴랑 다양하게 있어서 좋았고 커피도 맛있었어요 ㅎㅎ 저희는 음식을 많이 시켜서 매장 안에서 먹었는데 야외 테이블도 있어서 메뉴 조금 시키시면 밖에서 드시는걸 추천드립니다 ! 인생샷 쌉가능 ㅎㅎ 너무 잘 먹었습니다 ~', 7, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'TERRACE');
