INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '너무너무 맛있었어요!! 블루베리 좋아하기도하고 대표메뉴인거같아서 주문했는데 아이스크림 듬뿍 올려주셨어요 ㅎㅎ 그리고 그래놀라가 너무 맛ㄹ있었어요!🤩🤩 앗 여기 냉동블루베리 아닙니다!! 생 블루베리에요😘 그리고 베리에이드랑 조합 너무 좋으니까 드셔보세요 추천함니다 ㅎㅎㅎ', 59, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '커피도 고소하고 맛있는데 브런치 메뉴도 건강하게 맛있는 느낌이에요! 카페 인테리어가 너무 힙해서 리프레쉬하면서 작업하기도 좋고 수다떨기도 좋았습니다 :)', 47, 8, 'GOOD', SYSTIMESTAMP);
