INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '여기 진짜 찐브런치맛집이에요 커피가 맛있어서 오 맛있네했는데 브런치 진짜 푸짐하고 맛있게 잘나와요 브런치즐기러 오기 딱 좋을듯!', 4, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '홍대 메인 거리에 이런 카페 맛집이! 대표 메뉴인 흑임자 갈레트 그리고 마카다미아 크림 라떼 트리플베리 에이드를 주문했어요🫶☕️🍦🍨 흑임자 갈레트도 넘 꼬소하구 얇은 크레페 안에 들어있는 카스테라와 크림, 아이스크림을 얌얌 그리고 인절미도 쏭쏭 있어 먹는 재미가 있었습니다! 마카다미아 크림 라떼 추천드려용! 진한 크리미한 크림맛과 작게 씹히는 마카다미아 그리고 고소한 너티한 넛과 커피가 잘 어울리는 시그니처 음료! ☕️ 맛도리 카페 하나 또 알아갑니당💓', 46, 8, 'GOOD', SYSTIMESTAMP);
