INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '스크램블 플레이트 (14.0) 아이스 아메리카노 (5.0) 브런치는 무난, 커피 깔끔하고 괜찮음. 분위기와 추구미가 좋은데 매장이 좁은 편이라 테이블간 간격이 좁은데 나름 구획을 잘해놓으셔서 개성있고 좋음.', 31, 10, NULL, SYSTIMESTAMP);
