INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '디저트도 맛있구 커피도 맛있는 훌리건커피 ..♥️ 아이스크림과 흑임자 조합이 짱이에용 빵도 맛있어서 남기지 않고 다 먹었네요 히히', 72, 18, 'GOOD', SYSTIMESTAMP);
