INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '인테리어가 멋있어요~!! 지상층이랑 지하층 복층으로 이루어져있는데 지하층은 다른 테이블 한 테이블만 있어도 울려서 얘기하니까 말소리가 잘 안 들리고 좀 더웠어요ㅠㅠ 여름이고 비 오는 날은 지상층 추천해용 :)', 12, 2, NULL, SYSTIMESTAMP);
