INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '분위기가 좋아요! 디저트도 맛있고 에이드가 진짜 제스탈이었습니다 콘치즈프라이도 맛있어보였는데 다음에 또 갈꺼니까 그때 주문할게여 :)', 40, 2, 'GOOD', SYSTIMESTAMP);
