INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '매장인테리어, 분위기 진짜 좋고 음료랑 디저트도 다 감탄하면서 먹었어요!! 인스타카페인줄 알았는데 사진만 잘나오는게 아니라 찐맛집이었어요ㅋ 스테이크 완전 부드럽고 바게트, 소스, 치즈 미쳤습니다 강강추추', 10, 2, 'GOOD', SYSTIMESTAMP);
