INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '헙 ,, 저 이카페 완전 사랑할거같아요 .. 인테리어도 넘 멋찌고 갈라트 라는 디저트 처음 먹어보는데ㅡ크레페 위에 아이스크림 위에 블루베리 팡팡 .. 🫐 미친맛도리에오 ㅜㅜ 이걸 왜 이제알있즤 .. 애쉬라떼는 꼬소하니 맛있어서 계속 드링킹해버림 ㅜㅜ 또 먹구 싶어요 ! !', 51, 15, 'GOOD', SYSTIMESTAMP);
