INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '훌리건커피 외과부터 힙한 느낌 낭낭한데 내부인테리어도 넘 힙한 거 같아요ㅎㅎ 특히 여기저기 그려진 그림들이랑 시그니처 문구들이 귀엽네요😆 사장님도 넘 친절하시구요. 브런치로 배 채우기 좋은 메뉴들이 많아서 한번씩 다 시켜먹어보고싶어요. 음식 플레이팅도 음료도 맛깔스럽게 나와서 사진 막찍어두 잘나와서 좋와요  👍 제가 주문한 스테이크봄바는 겉은 바삭한 빵에 부드러운 스테이크가 먹기 좋은 사이즈로 잘려서 올라가는데 입에서 살살 녹아 없어지구 기본으로 발려있는 소스들이 자극적인데 맛도리네요😆', 74, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), 'BGM도 좋고 인테리어도 멋졌어요 자리도 많고 굿즈도 있어서 구경하기 좋았고 음식도 너무너무 맛있었어요 :) 친구들과 와도 좋을 거 같아요 스테이크붐바 그냥 먹어도 맛있고 소스도 찍먹해도 맛있고 아보카도플레이트는 비쥬얼부터 합격 맛있어요', 42, 8, 'GOOD', SYSTIMESTAMP);
