INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '지하부터 테라스 석까지 좌석이 넉넉하고, 그라피티 갤러리같은 멋스러운 느낌이에요! ✨ - 흑임자 갈레트 얇은 갈레트 반죽이 복주머니 모양으로 동그랗게 모양을 잡고 있어요. 반을 가르면 맛있는 카스텔라가 가득! 우유 맛 아이스크림+ 흑임자 크림+ 흑임자 가루 + 크럼블 + 인절미 떡이 어우러져 있어요. 시원하고 부드러워서 빙수를 먹는 기분🤍 흑임자 크림은 진하면서 짭조롬하고, 폭신~하고 흐르는 느낌이에요. 추천해요! - 트리플 에이드 청을 직접 담그신다고 해요. 농도가 진하고 양이 많습니다. 블루베리, 오디, 라즈베리 조합인가요  달달한데 물리지 않고 산뜻하면서 씨앗이 톡톡하게 씹혀요 🫶🏻 공간 구성이 멋지고 독특해요. 카운터는 스피커 모양ㅎㅎ🎵 즐거운 분위기를 느껴보세요!', 37, 8, 'GOOD', SYSTIMESTAMP);
