INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '거의 5번째 방문이에요!!! 귀찮아서 영수증 리뷰 안하다가 여긴 해야한다!!! 싶어서 합니다! 음료도 맛있고 디저트도 맛있어요! 오늘은 밥 먹고 거의 바로 와서 디저트를 안 시켰는데 진짜 디저트도 맛있고 음료도 맛있습니다👍🏻 커피류를 안 마시는 제가 마실만한 음료도 많아서 너무 좋아요! 앞으로도 자주 올거에여🫶🏻', 66, 11, 'GOOD', SYSTIMESTAMP);
