INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '고기 진쨔 부드럽구 맛잇어여 :-) 빵두 바삭하구 고소햇던 브런치! 혼자와서 식사겸 먹엇는데 가격 아깝지 않은 풍성한 양에 감자튀김 조금 남겼어요,, 홍대라인에 이렇게 깔끔하고 매장 넓은 곳이 잇었네요💖', 67, 12, 'GOOD', SYSTIMESTAMP);
