INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '새로운 스타일의 브런치입니다😊 스테이크 봄바는 고기가 부드럽고 사이드로 나온 감자도너무 맛있었어요:) 시푸드 아보카도 봄바는 들어있는 재료도 신선하고 치즈도 맛있었습니다ㅎㅎ', 65, 12, 'GOOD', SYSTIMESTAMP);
