INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '흑임자 갈레트 크림이 엄청 진하고 맛있어요! 마카다미아 크림 라떼도 커피가 진하구 맛있습니당 갈레트 크림이 굉장히 진해서 라떼 종류보다는 아아가 더 잘 어울릴 것 같아요 매장도 꽤 커서 답답하지 않고 얘기하기에도 좋은 카페 같아요 안쪽에 있어서 외부에 통행량이 많지도 않아서 좋네요!', 15, 8, 'GOOD', SYSTIMESTAMP);
