INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '가게가 깔끔하고 잘 꾸며져있어서 좋았습니다 블루베리 갈레트도 상큼하고 에이드도 너무 달지않고 맛있더라구요 다음에는 스테이크봄바 먹어보고싶네용', 26, 7, 'GOOD', SYSTIMESTAMP);
