INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '진짜 다 맛있어요🙊👍🏻👍🏻 갈라트도 이번에 처음먹어봤는데, 반했어요! 그리고 씨푸드 아보카도 봄바도 재료 아낌없이 넣은게 분명해요! 너무 맛있어요. 여긴 두번세번 추천해요!!!!!!!!!👍🏻👍🏻', 24, 2, 'GOOD', SYSTIMESTAMP);
