INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '음식 진짜 맛있었어요🧡 메인 메뉴인 흑임자 크림도 맛있고, 바게트와 고기도 맛있고, 심지어 사이드 감자튀김도 소스에 찍어먹으니 완전 맛있었어요! 음료도 비쥬얼 굿입니다요💛', 94, 25, 'GOOD', SYSTIMESTAMP);
