INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '이번 주말은 뭐 먹지? 고민하면서 검색하던중에, 이전에 디저트 먹으러 방문했던 훌리건카페에서, 식사를 할수 있는 메뉴가 추가됐다네요? 오호! 궁금한데? 사진상으론 그럴싸해보여서 방문해서 먹어봤는데... 사진하고 똑같이 나옴!ㅋ 맛도 좋고, 식사대용으로 하기에 딱 좋았네요. 못 먹어본 메뉴 먹으러 재방문의사 있어요! 사장님! 추가메뉴 또 개발해주세요!ㅋ', 17, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '메뉴와 디저트를 다 시켜봤는데 블루베리 갈레트 추천!!! 외관부터 힙하고 내부도 깔끔해요!!! 음료 너뮤너뮤 상큼 모든메뉴 먹어보고 싶어요', 34, 7, 'GOOD', SYSTIMESTAMP);
