INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '매장 분위기도 좋고 음식도 정말 맛있는 브런치맛집! 스테디셀러인 스테이크 봄바도 고기 진짜 많고 감자까지 쫀맛이고! 가게에서 추천해주신 메뉴인 콘치즈프라이도 정말 취향저격이에요! 묵직한 샌드위치와 감자 좋아하시는 분들께 정말 정말 추천드리는 맛집입니다!', 48, 8, 'GOOD', SYSTIMESTAMP);
