INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '힙한 인테리어가 멋있고 매장 음악도 좋아요! 무엇보다 시그니처 커피와 음료, 브런치 메뉴까지 비주얼부터 맛까지 다 완벽해요!!', 42, 1, 'GOOD', SYSTIMESTAMP);
