INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '감자 후라이도 진짜 부드럽고 봄바도 미쳤네요 빵도 부드럽고 소시지도 맛있고 소스랑도 찰떡으로 어울리고 우연히 들어와서 먹어봤는데 너무 맛있어서 깜놀', 39, 3, 'GOOD', SYSTIMESTAMP);
