INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '홍대 골목 구석진 곳에 있는 카페입니다 갈레트라는 걸 처음 먹어봤는데 시즌메뉴로 딸기 갈레트가 있어서 먹어봤어요~ 무슨 맛인지는 모르겠는데 맛있어요!! ㅋㅋㅋ 빵의 쫄깃함도 있고 딸기랑 아이스크림도 맛나고 전체적으로 맛있어요~~!', 44, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '갈레트 존맛이어요 🥹 순삭했습니닷 ... 원조 갈레트와는 다르게 크레페 안에 커스터드 케익이 있는데 그게 있어서 더 풍부한 맛으로 즐겼던 것 같아요 ! 크레페의 쫀득함 + 커스터드의 부드러움 + 딸기와 블루베리의 새콤달콤 + 아이스크림 = ❤️ 케익이랑 같이 딸기시럽도 듬뿍 들어가있어서 생과일이랑 아이스크림이랑도 궁합이 좋았습니다 👍🏻 바질 피치 에이드 궁금해서 시켜봤는데 시럽이 잘 안 섞여서 애먹었지만 .. ㅜㅜ 바질향이 부담스럽지도 않고 은은하게 복숭아랑 잘 어울려서 프레쉬한 맛이었어요 ! 추천 👍🏻', 75, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '음료도 맛있고, 디저트도 너무 맛있었어요! 특히 시즈널 갈레트 저 딸기 올라간 디저트는 딸기도 달고 아이스크림도 달아서 기분 안좋을 때 먹으면 기분이 좋아질 거 같이 맛있더라구요 🤍 팬케이크안에 딸기케이크가 들어간 느낌이던데 처음 먹어봐서 그런지 신기했어요 직원분들도 너무 친절하셔서 기분이 좋아졌어요 👍 바질복숭아에이드는 바질향보다 복숭아맛이 강해서 바질 초급자가 도전하기 적당한 바질향이었습니다 🤍 도장 쾅쾅쾅!!!', 107, 25, 'GOOD', SYSTIMESTAMP);
