INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '인테리어도 깔끔해서 사진 찍기좋고 음료도 예쁘고 너무 맛있어요! 아이스크림까지 짱맛.. 분위기랑 노래 힙해서 좋아요! 홍대에서 힙한 카페 찾으시면 추천합니당!!', 36, 2, 'GOOD', SYSTIMESTAMP);
