INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '다양한 종류의 갈레트 디저트가 파는 곳이에요! 딸기와 흑임자 중 고민하다가 흑임자를 먹었는데 고소함 그 자체^_^ 안에는 카스테라 빵, 바삭한 과자, 빙수떡이 들어가있는데 식감도 좋고 독특한 디저트라 새로운 느낌 가득했어요😊', 47, 2, 'GOOD', SYSTIMESTAMP);
