INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '카페 내부가 엄청 깔끔하고 멋져서 사진찍기 좋았어요~ 덕분에 인생사진 많이 건졌어요~ 흑임자크림갈레트랑 스크램블 플레이트 가격도 합리적이고  넘 신선하고 맛있엇어요 좋은 추억 만들고 가요', 117, 19, 'GOOD', SYSTIMESTAMP);
