INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '진짜 이런 곳을 왜 이제야 안 건지 모르겠어요ㅜㅜ 진짜 디저트 좋아한다면 꼭 와봐야해요 갈레트가 뭔지 몰랐는데 먹자마자 같이 간 친구들이랑 같이 감탄하면서 다 먹고 흑임자도 추가로 시켰습니다 인테리어도 깔끔하게 예쁘고 직원분들이 너무 친절하세요 쿠키도 짱 맛있어요', 102, 25, 'GOOD', SYSTIMESTAMP);
