INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '매우 친절하시고 적당히 조용해서 좋아요. 특히 디저트가 너무 맛있고, 커피는 산미가 도는데 달달한 디저트랑 잘 어울려요 나중에 또 들릴거같아요🥰', 90, 14, 'GOOD', SYSTIMESTAMP);
