INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '갈레트 처음 먹어봤는ㄷㅔ 맛있었어요! 빳빳한 크레페 종이안에 스폰지 케이크 + 블루베리 크림치즈가 포장된것처럼 들어있었고 위에 엑셀렌트 아이스크림 + 바나나+ 블루베리! 토핑되있었어요 새로워서 맛있었어요 음료는 아메리카노 , 바질에이드 , 애쉬 커피 다 시그니처로 시켰는데 그건 쏘쏘했어요 분위기는 전체적으로 어둡지만 블랙 성애자인 제컨셉하고는 찰떡이었어용 ㅎㅎㅎ', 41, 8, 'GOOD', SYSTIMESTAMP);
