INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '새로 생긴 카페라서 한번 방문해 봤어요, 직원분들이 친절해서 첫인상 좋았고요. 바닐라 라떼 & 말차 라떼 아이스 둘 다 맛있네요, 블루베리 크림치즈 갈레트 & 쇼콜라 갈레트도 같이 먹었는데, 맛도 맛이지만 정말 이쁘게 나오네요.^^ 같이 간 분이 사진 찍기 전에는 절대! 손대지 말라고 하네요.ㅎㅎ; 저 처럼 주차 찾는 분들이 계실거 같은데요. 주차는 동교1노상공용주차장 이용하시면 됩니다. 다만, 주차 자리가 많지 않아서 기다릴수 있어요. 저는 평일 낮에 가서 바로 주차했어요. 다시 방문할 의향 많은곳이네요!', 30, 3, 'GOOD', SYSTIMESTAMP);
