INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '무심코 들어선 골목에서 찾은 보물 같은 카페였습니다. 오픈한 지 얼마 안 된 곳 같아 보였는데 주문한 메뉴들 맛은 말할 것도 없이 모두 훌륭했고, 분위기도 좋았습니다. 메뉴에 맥주도 있어서 신기했어요. 얼마 안 되는 시간이었지만, 여러가지로 힐링하고 갑니다.', 19, 0, 'GOOD', SYSTIMESTAMP);
