INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '홍대 신상카페라고 찾아갔는데 매장이 분위기 있고 메뉴도 다 예쁘고 맛있었어요. 특히 디저트중에 블루베리 갈레트가 특히!! 직원분들도 친절하시고 제가 제일 요즘 좋아하는 직접 가져다 주는 서비스를 해주시더라고요! 서비스가 잘 유지되면 좋겠네요~', 90, 18, 'GOOD', SYSTIMESTAMP);
