INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '오매불망 오픈 하시는 날 만을 기다렸자나요 정말🥹 작은 상점들과 고기 냄새 가득한 골목 사이에 숨겨져 있는 보물 같은 곳이네요 사실 주변에 가보고싶거나, 갈만한 카페가 이상하게도 없는 쪽이라 친구들과 본격적으로 놀아재끼기전 워밍업 할 수 있는 공간으로 딱인듯해요 그리고 다름 아닌 듁스 원두를 쓰신다니……. 후! 커피는 말 할 것도 없고 디저트까지 너무 맛있었고 인테리어도 간결하면서 멋지고 야외자리까지 갖춰져있는 힙한 신상 카페 훌리건에서 정말 좋은 시간 보내고 왔답니다!  아 사장님께서 알려주신 카페 즐기기 꿀팁! 오후 시간 여기 저기로 열심히 돌아다니는 무지개 찾아 사진찍기 미션도 성공했쥬! 좀 더 선선해지면 테라스에서 가을 바람 즐기러 또 가려구요!', 20, 0, 'GOOD', SYSTIMESTAMP);
