INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '햇살 좋은날 야외에서 마실수도 있고 분위기도 좋아요 :) 커피맛은 물론이고 디저트에도 공을 많이 들이신 것 같은데 쿠키도 정말 맛있네요….! 다음번엔 다른 테이블들이 하나씩은 꼭 먹는 갈레트를 시켜보고 싶어요. 오픈한지 얼마 안되신줄 알고 있는데 주말엔 거의 만석이네요….평일을 노려봐야겠어요. 야외자리에서 한가할때 멍때리면 좋을것 같아요…', 31, 0, 'GOOD', SYSTIMESTAMP);
