INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '조금 찾기 어려운 위치에 있지만 카페 분위기가 완전 힙하고 직원분들이 너무 친절하셔서 기분이 너무 좋았어요💕 오늘 첫 방문인데 자주 방문할 거 같아요! :)', 104, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '신기한 식감의 디저트였어요!! 달달하고 쫄깃하고 맛났어요 커피도 맛있고 무화과 철이 짧아서 아쉽지만 다음 무화과 철에 또 먹으러 갈래용', 49, 8, 'GOOD', SYSTIMESTAMP);
