INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '훌리건 커피'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '회의 할게 있어서 찾아오게 되었는데 직원 분도 친절하시고 음료도 맛있어요 되게 깔끔한 느낌! 분위기도 좋고 자리도 편해서 자주 오게 될것 같아요 🌝', 43, 9, 'GOOD', SYSTIMESTAMP);
