INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '블루보틀 홍대 카페'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '블루보틀은 뭐 크게 실망은 안하는 것 같아요. 기본은 하고 갑니다. : ) 커피맛도 그렇고 디저트 맛도 그렇고!! 그래서 프랜차이즈 하나봐염~ 사람들이 좋아하는 포인트를 잘 알고 있는 느낌이랄까...', 8, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '블루보틀 홍대 카페'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '매장이 작아서 모르고 지나칠뻔! 호텔로비같은데 카페같기도하고 약간 애매해요. 창가쪽 자리는 바깥 뷰도 볼수있고 저녁쯤되니 조명도 켜져서 예쁘네요^__^', 100, 19, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '블루보틀 홍대 카페'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '호텔 1층에 있는 블루보틀 천장이 넓어서 되게 여유있는 공간이에요! 커피는 좀 가격이 있는 편이지만 한번쯤 먹을만한만큼 맛있네요~~', 8, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '블루보틀 홍대 카페'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '클로브 라떼 먹어봤는데 향이 좀 독특해요. 바닐라에 고수향이랄까 그리고 좀 진하게 달다 싶어요. 저는 기존 라떼가 좋은 것 같아요!', 94, 22, 'BAD', SYSTIMESTAMP);
