INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '블루보틀 홍대 카페'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '카페라떼를 먹었는데 라떼 아트를 잘 그리셨다 하겠어요. 라이즈 호텔 1층에 있어서 호텔 주차장 이용하면 되니 주차하기 편해요. 단 주차장 들어가는 입구는 좁아서 난이도가 좀 있어요. 일단 들어가면 시원한 공간이긴 하지만요. 관광객이 많아도 앉을 자리는 있는 편인게 유동 고객이라 그런 것 같아요. 매장 내 있는 화장실은 장애인용 혹은 겸용같은 데 엄청 깨끗해서 좋아요. 홍대 가서 누군가를 대기하거나 급하게 회의해야 할 때 가기 좋은 곳인 것 같아요', 193, 47, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PARKING');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'MEETING');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '블루보틀 홍대 카페'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '더현대 블루보틀 방문했습니다🩵 더현대를 지하부터 다 돌고 블루보틀 방문해서 아메리카노 마시면 커피가 생명수처럼 느껴지는 매직✨ㅋㅋ 더현대 블루보틀 방문은 처음인데, 포장을 하더라도 주문하려면 테이블링을 해야 하더라고요~! 포장도 테이블링이라니 ㅠ.ㅠ 포장 전에도 웨이팅을 해야 했지만, 그래서 매장이 정돈되는 느낌은 있었어요. 그리고 주문 및 웨이팅 안내해주시는 분이 친절하게 안내해주시더라고요:) 블루보틀의 커피는 워낙 유명하기 때문에 맛을 논하는 건 무의미하지만, 다만 커피가 산미가 강하거나 쓴 건 잘 못 마시는 사람인데 블루보틀 커피는 그러지 않아서 좋아요 !! 커피 아이스크림은 블로그에서 보고 주문해봤는데 더*위*사냥 맛이었어요. 블루보틀을 재방문한다면 음료를 마시려고요 ㅎㅎ 잘 마셨습니당 ~', 59, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '블루보틀 홍대 카페'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '유명한 블루보틀 첫 방문이었어요 놀라 플로트라는 아이스크림 라떼 먹었어요 가격이 좀 세긴 하네요 아이스크림이 막 달지 않고 맛있었어요 직원분도 엄청 친절하셨구요 ㅎㅎ 다음엔 그냥 라떼 마셔보려구요!', 58, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '블루보틀 홍대 카페'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '라떼가 맛있다는 리뷰 보고 카운터에서 라떼가 뭐냐고 물었다가.. 드립이라 라떼는 없고 라떼랑 비슷한 게 있다.. 그래서 드립집이면 드립 먹어야지! 했는데... 라떼 먹을 걸 했네요.', 36, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '블루보틀 홍대 카페'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '커피가 점점 맛이 없어진다... 블루보틀맞니,, 게다가 직원들도 좀 어리버리 음료종유도 적은데, 안내도 제대로 못하구, 조금 실망이네요', 26, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '블루보틀 홍대 카페'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '지갑을 여기서 분실할거라 생각도 못했는데 마감시 연락주신 직원분들과 응대에 감동 받았습니다. 메리크리스마스! 새해 복 많이 받으세요ㅎㅎ 고맙습니다.', 81, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '블루보틀 홍대 카페'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '블루보틀 홍대☕️ 디카페인 원두 아메리카노 깔끔한 맛이 마시기 좋아요 주변 홍대 카페들에 비해 번잡스럽지 않아 조용히 대화하기 좋은 분위기에요', 16, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '블루보틀 홍대 카페'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '커피 맛있고 매장 깔끔하고 편한데 마시던 커피 테이크 아웃으로 부탁하니까 그냥 컵에다가 확 부으면서 1/3가량은 그냥 쏟아지고 테이크 아웃 컵도 커피 때문에 더러워졌는데 그냥 주시더라구요... 바쁘신 상황인지 모르겠으나 주의 좀 해주시던지 테이크 아웃 용기에 커피를 옮길 때 다른 방법을 쓰셔야 할 듯 합니다.', 29, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '블루보틀 홍대 카페'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '두분이 커피내리시니...바쁘셔서 물어보기가 좀 그랬네요 ㅋ 원두설명 해주시는 분도 계셨음 좋겠어여~ 싱글원두가 딱 한봉지씩 남아 많이없어서 좀 그랬네요 ...블루보틀 한번씩가서 갈때마다 원두 한봉씩 사오는데... 커피맛은 넘 맛있었어요 ^^ 분위기도 편안 ~', 39, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '블루보틀 홍대 카페'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '홍대 팝업스토어는 붐비지 않아서 쾌적😘😘👍💕 놀라는 스벅 바크콜 느낌, 아메 싱글오리진은 산미가 강해서 좋와영❤️❤️ 팝업이라 아메 라떼류 정도만 있는건 좀 아쉬웠어옹 ㅎㅎ 그래두 직원분들 다른지점보다 친절해서 좋아야!!', 50, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '블루보틀 홍대 카페'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '호텔건물에 있는 카페 자리배치가 독특 자리마다 콘센트가 있는 편인데 주의하지 않음 선에 걸릴 수 있을 듯함 친절한 편 커피가격이 좀 있음', 56, 14, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PLUG');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '블루보틀 홍대 카페'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '미국에서 자주 보았었던 블루보틀(Blue Bottle) 카페를 한국에서 처음으로 방문해 커피를 마셔보게 됩니다. 안타깝게도 홍대입구 블루보틀은 팝업 매장이기 때문에 애용하는 아이스 카페 라떼가 없어 콜드브루(6,000원)를 주문하였습니다. 콜드브루 자체는 자주 마시지 않아 블루보틀의 커피에 대해 자세한 의견은 내리기가 아직 어렵지만 개인적인 생각으로 괜찮은 편에 속하기 합니다. 다만, 미국과 마찬가지로 다른 카페보다 분명히 가격은 비싼 편에 속하고 사이즈도 위 사진에 나와있는 것이 전부라 가성비를 생각하면 뛰어난 편은 아닙니다. 그래도 멀리서 온 만큼 자주 접해보지 않은 카페를 방문하고 내부 디자인도 나름 미국이랑 얼핏 비슷해서 괜찮았었습니다. 감사합니다.', 37, 5, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '블루보틀 홍대 카페'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '블루보틀은 산미가 있는 편이라고 해서 안 갔었는데 근처 갔다가 가게됐어요. 직원 분이 콜드브루 라떼 추천해주시면서 원두에서 단 맛이 난다고 하시더라구요. 그냥 그런가보다.. 하고 한 입 먹었는데 헐.. 진짜 맛있어요.. 시럽 넣은 게 아닌데 이 정도로 달달할 수 있나? 깜짝 놀랐어요.. 콜드부르 라떼 따뜻한 것도 돼서 좋았는데 기대 이상으로 너무 맛있었어요. 콜드부르 라떼 추천입니다!', 4, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '블루보틀 홍대 카페'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '홍대팝업이 생겨서 다녀와봤는데 직원분들이 정말정말 친절하세요:-) 디카페인을 드립으로 마셔봤는데 또 새롭네요ㅎㅎ 따뜻한 원목테이블이라던가 층고가 높고 통창이라 공간 활용을 블루보틀답게 잘 활용해서그런지 매장 분위기가 전반적으로 따뜻하고 답답하지 않아 좋았습니다. 다음에 또 방문하고싶네요.:-)ㅎㅎ', 26, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'INDUSTRIAL');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '블루보틀 홍대 카페'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '팝업이라 라떼가 없어서 좀 아쉬웠어요~🥲 팝업은 팝업만의 느낌이 있어서 새롭내용~ 개인적으로, 팝업에서 판매하는 커피보다 그냥 매장이 더 맛있었던것 가타효🙄 그래도 맛있게 먹었습니다~☕️👍🏻', 20, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '블루보틀 홍대 카페'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '홍대 팝업카페가 열렸다기에 방문 했어요:) 직원분들도 친절하시고 커피도 역시 맛있었습니다! 그치만 그 중에 쵝오는 역시 아이스크림!!', 24, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '블루보틀 홍대 카페'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '팝업이라 카페라떼는 없어요! 하지만 놀라 마시면 됩니당💕💕 직원분께서 친절하게 얘기도 해주시도 너무 좋았어용😁 바스크 치즈케이크도 훌륭👍🏻 콜드 브루도 커피맛이 세상 좋네요❤️🤭', 43, 8, 'GOOD', SYSTIMESTAMP);
