INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '블루보틀 홍대 카페'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '직원분들 정말 너무 친절하세요!!! 완전 감동,,,☺️ 제가 달지 않은 라테가 먹고 싶었는데 홍대점에는 없는대신 다른 옵션에 대해서 알려주시더라구요. 덕분에 다음에는 그 옵션을 도전해볼까라는 생각도 하게 됐구요 !! 전에는 블루보틀에 대해서 아무 생각 없었는데 블루보틀이 좋아졌어요!!🥰🥰 커피 맛도 부드러워 만족합니다. 감사합니다 ~!', 31, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '2층까지 있어서 좌석이 널널한 카페였고, 디저트부터 음료 종류까지 다양해서 너무좋았어요! 얼그레이 티 너무 맛있게 잘먹었습니다!', 19, 1, 'GOOD', SYSTIMESTAMP);
