INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '더워서 길걷다가 우연히 들어간 곳인데 진짜 넘 좋았어요!!!!!! 1,2층으로 이뤄져 있어서 테이블도 많고 공간도 넓습니다! 그리고 에어컨 특히 빵빵해서 시원해서 좋아요! 디저트 라인업도 상당히 다양하고, 저는 에그타르트랑 블루베리스콘 먹었는데 둘다 넘 맛있었어요!! 스콘 종류가 많아서 고르는데 결정장애 올뻔 했답니다 😎😎 연남동 오시면 꼭 들려보세요~~~!!', 48, 10, 'GOOD', SYSTIMESTAMP);
