INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '낙랑크렘 모에요?? 너무 맛있어요🙊 커피숍 잘안가고 아이못먹는1인인데 쓸까봐 걱정했는데 달달구리 쵸코 시나몬크림?맛나요!😆맛있어요 또 생각날것같아요 디저트는 아쉬워요', 21, 3, 'GOOD', SYSTIMESTAMP);
