INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '지나가다가 우연히 들린 카페인데 레트로 느낌도 짱짱하고 무엇보다 커피가 진짜 너무 맛있어서 순삭이에요! 디저트도 맛있지만 커피가 정말 진하고 부드러워서 커피 꼭 드시길 추천합니다 ㅎㅎ', 21, 6, 'GOOD', SYSTIMESTAMP);
