INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '연트럴파크 골목갬성 우연히 방문했는데 매장도 엄청넓고 작업하기 혼커하기 좋아여 내부 인테리어도 이뻐서 인스타갬성사진 마구 찍고왔어여 이색적인 커피메뉴도 다양하니 골라먹는 잼도있네여', 86, 17, 'GOOD', SYSTIMESTAMP);
