INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '낙랑크렘 (아인슈페너. 크림맛있고 땅콩라떼 (고소하면서 땅콩샌드쿠키맛이 생각나는? 블랙 포레스트 (달달하고 부드러운 초코케익 커피. 디저트 종류 맛있어요 ! 디저트종류 다양하고 빈티지스럽고 대화하기좋아요 :)', 15, 0, 'GOOD', SYSTIMESTAMP);
