INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '가게가 전혀 혼잡하지도 않은데 손님 올때 갈때 응대가 전혀없고 음료를 픽업할때도 반납할때도 안내가 전혀 없습니다ㅎ 손님이 인사하고문의하면 답이라도 제대로 해주세요~ 음료 구분없이 띡 있길래 물어봐도 단답.. 재방문 의사 없는 카페에요', 36, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '낙랑파라 아현점이 없어져서 섭섭해하고 있던 찰나 연남점을 방문하게 됨 ! 지하1층은 앤틱+ 의자가 앉을 때 푹꺼지는 의자 1층은 베이커리 + 좌석 및 주문 2층은 좌석있고 중간중간 룸처럼 들어가는 곳 있음 진대할 공간이 필요했는데 중간에 룸처럼 공간이 나뉘어 있어서 진대 하기 적당한 카페였음 블랙포레스트 - 포레누아랑 비슷한데 딸기맛이 강하게 남 딸기에이드 - 딸기청들어간 에이드 나머지는 내가 안 먹어봄ㅠ 추석맞이로 갔었는데 휘낭시에를 송편처럼 만들어서 판매하고 있었는데 아이디어 👍🏻 근데,사장님 콜라에 진심이신가여 코카콜라 가 많이 보이네여 앤틱한 제품들도 보여서 눈도 호화를 누릴 수 있는 카페', 4, 7, 'GOOD', SYSTIMESTAMP);
