INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '밤라떼 맛있어요! 치즈케이크도 드리즐도 뿌려주시고 예쁘게 플레이팅 되어 나와서 좋았어요 케이크 외에도 베이커리류가 좀 더 있고, 무엇보다 매장이 넓고 예뻐요! 근처 가시게 되면 방문해보셔도 좋을 것 같습니당 👍', 56, 15, 'GOOD', SYSTIMESTAMP);
