INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '☕️ 점심 마치고 어디가지? 하다가 분위기가 이뻐보이는 낙랑파라에 왔어요 ☕️ 저희는 아메리카노2, 쇼콜라 버터쿠키, 그리고 피칸 휘낭시에 이렇게 주문했어요. 아메리카노에 산미가 있어 좋았고 디저트는 둘다 너무 맛있었어요!(두 디저트 모두 초코향이 나던데, 저희 입맛에 잘 맞았어요) ☕️ 2층에 가면 비밀의 방 같은 공간이 있는데 사진찍으며 놀기 좋은 공간 같아요. 음료와 음식은..허겁지겁 먹느라 못찍었네요😂', 42, 1, 'GOOD', SYSTIMESTAMP);
