INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '가려던 카페 몇군데가 있었는데 거짓말 안하고 만석이거나 3명 앉을 자리가 하나도 없어서 간 곳인데, 케이크 맛있고 커피도 괜찮았어요. 아이스티엔 얼음이 과해서 그게 좀 아쉬웠다는~~~', 221, 52, NULL, SYSTIMESTAMP);
