INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '지하 1층부터 지상 2층까지있고 자리가 다양했어요 2층은 제가 갔을때 조금 덥긴했습니다 날씨가 괜찮았으면 구석자리도 있고 좋았을꺼같습니다. 아이스초코와 아메리카노를 마셨는데 아메리카노는 많이진하진 않았고 2천원 추가금을 내면 리필도 가능했습니다.', 32, 6, 'GOOD', SYSTIMESTAMP);
