INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '빈티지한 인테리어가 너무 예쁘고 여러가지 소품도 판매하고 있어서 구경도 재밌었어요! 지하와 2층에도 좌석이 있어서 좋았고 음료케잌 다 맛있어요 추천입니다 🐱', 9, 7, 'GOOD', SYSTIMESTAMP);
