INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '이용할 수 있는 테이블이 다양하긴 하나, 직원들이 돌아다니며 정리하는 스타일이 아니라 테이블이 지저분함. 주문 받는 남성 직원도 친절하진 않음. 차라리 다른 카페 이용하는게 나았던것 같음', 47, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '커피 맛 좋고 분위기 좋고 직원분들 넘 친절하세요 연남동 오면 무조건 또 가고싶은 카페입니다! 카페 마스코트 낙랑이도 넘 귀엽고 사랑스러워요..❤️', 80, 11, 'GOOD', SYSTIMESTAMP);
