INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '가려던 카페가 만석이라 또 알아뒀던 낙랑파라 방문! 분위기가 넘 좋아서 어디 앉을까 고민하다가 지하 공간 이용했는데 넘 좋았어요🥰 재방문 각!! 🫶🏻✨️', 118, 25, 'GOOD', SYSTIMESTAMP);
