INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '연남동에 사람많아서 아무 카페나 들어온거였는데 이렇게나 좋을 수가! 곳곳에 포인트들이 숨어있고 카페 분위기에 매장까지 넓어서 정말 만족스러웠어요 직원분들도 친절하고 음료도 맛있네요! 다음에 또 방문해서 디저트도 먹어보고싶어요 ㅎㅎ', 13, 4, 'GOOD', SYSTIMESTAMP);
