INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '아늑한 공간에서 맛있는 커피 잘 마셨습니다 ☺️ 지하 공간, 1층 공간, 2층 햇볕 많이 받는 공간이 있어서 취향대로 가면 좋을 것 같아요~ 주말엔 사람이 많은데 오늘은 운좋게 평일 낮이라서 그런지 매장이 한산했어요.', 28, 6, 'GOOD', SYSTIMESTAMP);
