INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '귀여운 빈티지 소품들이 많은 카페에요! 직접만든 컵도 예뻐서 살까말까 고민했는데,,집에 컵이 많아서 패스! 땅콩라떼는 땅콩이 씹히고 고소해서 정말 맛있었어요ㅎㅎ자리도 많고 분위기도 좋아요~ 또오고싶을듯', 87, 14, 'GOOD', SYSTIMESTAMP);
