INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '몇년만에 방문한 낙랑파라, 항상 좌석이 없었는데 ㅎㅎ 비가와서 그런지 점심먹고 갔을때 자리가 있었어요! 금방 꽉 차긴 했지만! 분위기가 좋고 디저트도 맛있게 먹었습니다~', 48, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '가게가 아늑하고 좋아요! 할머니댁에 놀러온 기분🤗 말차라떼랑 말차카라멜 롤케이크도 아주 맛있어요! 음료가 담긴 잔들이 너무 예뻐서 좋았어요!', 20, 5, 'GOOD', SYSTIMESTAMP);
