INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '디저트(케익) 얼었다고 말해주신분있져?????? 검정목티 입고 눈큰 직원, 마감시간에 와서 그런지 굉장히 불친절, 귀찮으니 먹을거면 먹고 갈람 가라? 평소 자주방문했고 첨본 분인데 알바분이 커피만 안뽑았음 저희도 집어치우고 취소하고 나가고싶었음여^^^^ 취소영수증 인증합니다. 그렇게 불친절할거면 일을하지마세요.', 24, 3, 'BAD', SYSTIMESTAMP);
