INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '사장님? 직원분이 정말 친절하세요. ☺️ 4단계 거리두기 수칙도 찾아봐 주시고 같이 기뻐해주시고(?) 참 감사했습니다. 음료는 땅콩커피인가 그거 맛났습니다. 🥜☕️실제 땅콩 알이 씹혀서 음료 겸 디저트로 잘 먹었어요. 생각보다 안 달았는데 잘 안 저어 드시면 밑에 베이스가 몰려 있어 달 수도 있을 것 같습니다. 밖에서 보이는 것보다 매장이 넓고 좌석 수가 많아요. 지하에도 자리가 있는 것 같더라고요. 거리두기만 아니면 단체로 모이기도 좋을 것 같아요.', 45, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '아침에 가면 한적하니 좋습니다 ☺️ 망고네 사진관 바로 옆이라 산책하는 댕댕이도 볼 수 있어요! 🐶♥️ 인터넷은 살짝 오락가락 합니다 ㅠㅠ', 1, 4, NULL, SYSTIMESTAMP);
