INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '오렌지 에이드가 맛있네요 응대해주신 직원분 친절하셨습니다:) 가게가 지하도 있고 2층도 있는데 넓직넓직해서 앉을 자리가 많아 좋았습니다 분위기도 예뻤어요 담에 지나가면 또 들릴게요', 18, 1, 'GOOD', SYSTIMESTAMP);
