INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '평일 11:30분정도 방문했는데 바쁜시간이 아닌데도 불구하고 손님와도 뒤도 안돌아보시고 자기일만 하심 주문한다니까 그제서야 뒤돌아보고 큐알 하라고 하네요^^ 진심 이렇게 불친절한데는 첨이네요 사장님인지 직원인지 사장님이시면 더 문제잇는곳', 1, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '저번 바닐라라떼는 그냥 무난했는데 땅콩라떼 시그니처라고 하기에는 그닥 ㅜㅜ 씁쓸한 커피맛과 땅콩잼 같은 땅콩향이 각자 노는 느낌이라 조금 아쉬웠어요 일행이 먹은 자몽ㅇㅔ이드는 괜찮았ㄷㅐ요!', 15, 5, 'BAD', SYSTIMESTAMP);
