INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '장소가 널찍하니 좋네요 인테리어나 공간구분도 잘해놓으신 듯 땅콩라떼 먹었어요 달달하고 땅콩맛이많이 나네요 카푸치노 믹스 그런거 탄거랑 비슷한 맛이에요', 23, 1, 'GOOD', SYSTIMESTAMP);
