INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '낙랑파라'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '생자몽에이드는 탄산없어요 케익은 어디서 떼온맛입니다 글고 지하엔 와이파이 엄청느리고 엘티이도안터짐...내속도터짐....다른집들 꽉꽉차있는시간에 빈자리가있을때부터 알아봤어야했음.....모든일엔 이유가있다는걸....', 69, 11, 'BAD', SYSTIMESTAMP);
