INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '식후땡망고가 진짜 식후에 넘나 먹기 딱이예요ㅋㅋ 진짜 센스메뉴! 밥 먹고 자주 먹을 것 같네요 망고퓨레 말고 진짜 망고만 쓴다는 것도 맛 보자마자 알겠더라고요 번창하세요!', 2, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '인테리어 귀욤뽀쨕 자리는 많이 없지만 망고빙수가 3500원 !! 가성비 오브 가성비 맛도 좋아여 ㅎㅎ 다른 메누들도 도장깨기 하고 싶네요', 15, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '매장이 조금 좁아서 아쉽긴 하지만 고망고 너무 좋아요ㅠ 망고 음료는 여기가 최고인듯 합니다. 많이 드시는 편이 아니면 두명이서 먹기에는 컵빙수가 딱인듯요.', 13, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '고망고 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '메뉴에 아쉬운점이 있다면 생크림이 너무 많아요ㅠ 메뉴구성을 재대로 확인안한 제 잘못이지만.. ㅠㅠ 생크림만 빼면 진짜 맛있게 잘먹었어요!!', 35, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '눈내리는숲, 설래임 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '🥄✨  홍대 골목에서 잠시 쉬어가듯 들른 눈내리는숲, 설래임 홍대본점 ⛄️🍧 여기서 주문한 설램 팥빙수(1인) 은 이름처럼 정말 마음까지 설레게 했습니다 💕 고소한 우유 얼음에 달지 않고 은은하게 퍼지는 팥의 맛, 쫀득한 떡과 함께 먹으니 한입 한입이 작은 행복 같았어요 팥이 예술입니다  😋❄️ 혼자서도 부담 없는 양이라 가볍게 즐기기 딱 좋고, 인테리어도 포근해서 빙수와 함께 머무는 시간이 참 따뜻했습니다 🌿☕ 사장님도 친절해서 기분 좋은 여운이 남았어요. 빙수 좋아하신다면 꼭 추천드리고 싶은 공간입니다~👍💯👏 #홍대카페 #눈내리는숲 #설래임홍대본점 #설램팥빙수 #홍대빙수맛집 #1인빙수 #홍대디저트 #달콤휴식 #감성카페 #홍대데이트', 11, 6, 'GOOD', SYSTIMESTAMP);
