INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '눈내리는숲, 설래임 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '커피안마시면 정신못차리는 아줌마입니다. 가게입구에 대기명단있어서 카페에 무슨 대기명단이 있지?🤭 갸우뚱하며 들어갔어요. 들어가보니 빙수종류가 엄청 많더라구요. 설빙에 없는메뉴 먹어보기로ㅋㅋㅋㅋ 진짜 맛있어요 그냥 빙수에 꿀뿌린게 다인데 저 꿀이 정말맛있어요👍👍👍 그리고 꿀부터 먹다가 연유뿌리시고 드시다가 팥넣으래요. 로얄허니빙수 1인분으로 3가지 빙수를 맛본느낌이에요 커피도 구수하니 맛있었어요 더위에 지쳐 녹아내려 들어갔다가 나올땐 오돌오돌 떨며 나왔어요ㅋㅋㅋㅋㅋ 대기명단이 왜있는지 바로 이해되는 빙수맛집입니다😆👍', 124, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '눈내리는숲, 설래임 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '한라봉요거트빙수2인! 1인빙수와 2인빙수 고를 수 있어서 좋아요 요거트 향이 새콤하게 맛있고 요거트 소스? 를 한 컵 더 주셔서 좋았어요! 그치만 양이 너무 작은 것이나 3명이서가면 2인 빙수에 음료 하나 더 시켜야하는건 좀 아쉽!', 39, 6, NULL, SYSTIMESTAMP);
