INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '눈내리는숲, 설래임 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '눈내리는숲, 설래임 홍대본점에서 딸기빙수와 녹차빙수를 맛봤어요. 딸기빙수는 신선한 딸기와 부드러운 우유 얼음이 어우러져 달콤하고 상큼했어요. 녹차빙수는 진한 녹차 아이스크림의 풍미와 팥 조화가 일품! 분위기도 좋아요.', 101, 24, 'GOOD', SYSTIMESTAMP);
