INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '눈내리는숲, 설래임 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '식사하고 후식을 찾다가 들렸는데 너무 맛있게 잘 먹었습니다. 딸기도 맛있고 시럽에도 채썬 딸기가 있어서 딸기맛이 폭발하는 빙수였어요. 게다가 반려동물동반까지되어서 정말 좋았습니다.', 48, 7, 'GOOD', SYSTIMESTAMP);
