INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '눈내리는숲, 설래임 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '쌤과 점심식사로 일본가정식 배불리 먹고 소화시킬 겸 빙수 생각에 찾아감...딸기 두배 빙수와 딸기 생크림 크로와상 주문하고 점심 간이 조금 짰는지 갈증나서 아아도 주문...  딸기빙수는 생각보다 덜 달고 딸기가 푸짐해서 마지막까지 계속 딸기가 따라 왔고 눈꽃빙수라서 얼음만 퍼먹어도 맛있었다. 추가로 곁들여나온 연유스런 소스는 농도가 연유보다 묽게 느껴졌으나 맛은 꽤 진해서 한숟가락씩 추가로 얹어가며 맛있게 먹었다.  크로와상은 사방으로 부서져 나이프로도 깔끔하게 먹기 어려웠으나 빵결이 얇고 바삭하고 딸기와 크림과의 조화가 너무좋고 너무 맛있어서 놀랐다.', 41, 6, 'GOOD', SYSTIMESTAMP);
