INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '눈내리는숲, 설래임 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '하카다분코 라멘 배불리 뿌시고 기름진 입을 닦으러 찾아감. 한라봉 빙수 너무 상큼하고 인절미 크로플은 고소하나 느끼해서 내 입엔 소소... 깔끔한 분위기에 한식 앉은뱅이 좌석까지 넓지 않은 실내를 깔끔하고 예쁘게 꾸며 놓음. 끝까지 너무 맛있게 다먹음', 13, 6, 'GOOD', SYSTIMESTAMP);
