INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '눈내리는숲, 설래임 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '🧾 한라봉요거트빙수(2인) / 두유미숫가루빙수(2인) 2인용 빙수는 딱 2인이서 먹기 좋은 사이즈라서 좋았고, 특히 두유미숫가루빙수가 팥도 적당히 달고 우유얼음과 조화가 너무 좋아서 맛있게 먹었습니다🩷 합정 홍대쪽에서 빙수 찾으신다면 추천드려요!!👍🏻', 36, 5, 'GOOD', SYSTIMESTAMP);
