INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '눈내리는숲, 설래임 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '한라봉빙수가 생각보다 너무 맛있었던 홍대 빙수집🍧 • 한라봉요거트빙수•플레인크로플 • 요즘 더워서 맨날 빙수가 땡기시는지 홍대와서 남자친구가 찾은 빙수집 중 한 곳! 홍대 클럽거리 쪽에 있고, 역시나 거의 만석이었는데 운좋게 바로 앉았다! 딸기빙수는 얼마 전에 시즌 끝났다고 해서 한라봉빙수라는 걸 첨 먹어봤는데, 요거트와의 조화가 생각보다 너무 좋아서 넘 맛있게 먹었다🤤 그리고 크로플도 넘 맛도리였던,, 사람이 많아서 주문이 밀려서 그런지 나오는데는 좀 오래걸렸지만, 사장님 응대도 넘 친절하시고 만족스러웠다ㅎㅎ 역시 여름엔 빙수가 더 럽,,🫶', 74, 13, 'GOOD', SYSTIMESTAMP);
