INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '눈내리는숲, 설래임 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '올해 첫 빙수!! 말차빙수 떡도 너무 쫀득말랑하고 말차맛과 너무 달지만은 않은 팥조합이 미쳤습니다ㅠㅜ! 특히 인절미크로플 꼭 드셔보세요 떡으로 만드신건지? 떡이들어있는 건지 잘 모르겠지만 떡이같이 있어서 더 쫀득바삭하니 맛있습니다!!', 0, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '눈내리는숲, 설래임 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '빙수가 맛있어용 좌식은 자리가 좀 불편하고 해가 많이 들어오더라구욘 ㅠ 그리고 인당 수만큼 빙수를 주문해야해요 2인 1인 빙수 있는데 저희 3명이서 방문해서 2인 1개랑 1인 1개 이렇게 주문 했어요. 각각 1인 빙수 먹어도 괜찮은데 가격이 더 비싸오.', 92, 24, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '눈내리는숲, 설래임 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '덥고 습해서 시원한 음식 먹으려고 들어왔는데 와서 시키고 좀 있으니 통창을 다 열어버리네요,,, 저희 습해서 들어온거라고 말했는데 문을 꼭 열어야 한다 하심... ㅎㅎ 꿉꿉해서 빙수 무슨 맛인지도 모르겠어요 습도 80인 날에 에어컨 틀고 문 다 열어놓는 빙수집...', 26, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '눈내리는숲, 설래임 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '흑임자 빙수 고소하니 맛있어요 먹다가 따로 주신 달달한 연유 뿌리면 더 맛있어용 팥도 아래 더 있어서 끝까지 맛있게 먹을 수 있어요!', 22, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '눈내리는숲, 설래임 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '여자친구가 빙수먹고싶대서 왔어요 1인빙수 2인빙수 있는데 1인으로 다양하게 맛볼 수 있어서 좋은데 빙수도 너무 맛있었고 개방감이 좋아요!! 여자친구도 넘 만족스러워 했어용', 406, 80, 'GOOD', SYSTIMESTAMP);
