INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '눈내리는숲, 설래임 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '로얄허니빙수 정말 맛있어요^^시그니처 메뉴도 아니었는데 시그니처는 얼마나 더 맛있다는건지 또 가고싶어요! 주인분 정말 친절하시고 늦게까지 영업해서 좋아요♡따뜻한 음료는  식지말라고 밑에 촛불해주는데 세심한 배려가 느껴져서 좋았어요 재방문 의사 있습니다', 24, 3, 'GOOD', SYSTIMESTAMP);
