INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '눈내리는숲, 설래임 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '불친절한게 컨셉인가요? 매장들어오고 5분동안 직원이 카운터에 안나오길래 "주문할게요" 직원을 셀프로 호출해야했던.. 독특한 컨셉의 매장.. 우리 이후의 손님분들도 다 호출해서 주문을 하더라구요.. 드디어 직원이 카운터로 나와서 주문했고, 기다리던 빙수와 음료 나왔다. 헌데 스푼을 두개주심.. 분명 주문할 때 몇명인지 물어봤는데도 불구하고 두개를 주셔서 당황했지만 본격 당황은 가서 스푼 달라고 말씀드리니 대꾸도 없이 수저를 먹는 방향으로 찌르기(?)하듯 주시더라구요ㅠㅠㅠ 이런 응대는 살다 처음보네요 가격은 합리적이고 인테리어도 나름 괜찮은데.. 다신 안올 곳.. 검은모자 쓰신분 분발합시다^_^ 사장님은 무슨 죄가 있어요', 109, 24, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '눈내리는숲, 설래임 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '🔹메뉴추천 : 두유 인절미 빙수 🔹개인적 의견 : 오... 우유 얼음이 아니라 두유 얼음인거 같은데 너무 맛있음.. 얼음 너무 부드럽고 팥이랑 인절미 가루랑 완전 잘어울림! 아이스크림에 아몬드 곰도리 귀처럼 올려주는거 완전 센스있고 너무 귀여움🫶🏻 두유로 만드는 빙수는 처음인데 우유보다 비린 맛도 없고 깔끔하고 더 고소한 느낌! 마치 비건을 위한 빙수랄까🩵 난 비건은 아니지만 맛있는건 다 좋아하니까 이것도 또 먹으러 와야지😋 어른들 모시고와도 좋아할맛, 다이어트하는 친구 데려와도 좋아할맛, 삐진 여자친구 데려오면 좋아할지는 모르겠지만 곰도리 귀가 귀여워서 풀릴지도 모르는 맛😂 🩵장길동의 맛도리로드🩵', 16, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '눈내리는숲, 설래임 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '3명이서 빙수를 2개를 시켰는데 1인 1메뉴를 주문해야된다고 하셔서 1인 빙수를 2개(일반 커피에 대략 1.5배~2배) 구매했는데도 안되냐고 여쭤보니 안된다고 하심😒 덕분에 먹지도 않는 커피를 반강제로 어쩔수앖이 구매함  너무 융통성 없다고 느낌 가게 방침이겠지만 융통성 없이 장사하시는 느낌이라 다음에는 절대 방문 안할듯 🤭   빙수 맛도 별로였고 가격대비 양도 너무 적었음 ❌❌ 다시 말하지만 1인빙수를 2개 구매하려 했지만 거절당함(3명이라는 이유로)', 9, 2, 'BAD', SYSTIMESTAMP);
