INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '눈내리는숲, 설래임 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '날이 좋아서 테라스에서 먹었는데 외국인담ㅂㅐ냄새도 잘 컷트해주시구 너무 친절하시고 짱짱맨!! 빙수 짱귀엽고 맛있어요. 속 시릴까봐 대추차랑 같이먹었는데 안쓰고 맛있어서 대추까지 다 씹어먹었네요ㅋㅋ', 1, 8, 'GOOD', SYSTIMESTAMP);
