INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '눈내리는숲, 설래임 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '소프트한 전통미가 느껴지는 인테리어와 거기에 맞춰 빙수도 도자기 그릇에 담겨져 나오는게 인상적. 두유 미숫가루 빙수는 담백하고. 토핑된 아이스크림의 유분이 자칫 밍밍할수 있는 맛에 밸런스를 맞춰준다. 빙수 가격 13900원은 재료, 양.. 뭘로 보나 넘치는 가격. 에어컨 인심은 후해 몸에 밴 한기에 매장에서 나와 한동안 무더위를 못 느낄수 있다. >재방문의사: 0%(가격대비 특별함이 없..)', 107, 25, NULL, SYSTIMESTAMP);
