INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '눈내리는숲, 설래임 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '두유맛이 연하고 수제팥인데 덜 삶아져서 통조림 팥처럼 딱딱한 부분들도 많아서 아쉬웠어요. 그래도 평타는 치는 것 같아요. 다음엔 다른 메뉴 먹어봐야겠어요.', 118, 19, NULL, SYSTIMESTAMP);
