INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '눈내리는숲, 설래임 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '지나가다가 탁 트인 인테리어에 시선이 머물러서 들렸어요. 빛이 참 예쁜 매장이고, 정성이 들어간 재료들을 많이 사용한다는 점에 더 끌렸습니다. 너무 늦은 시간이라 빙수를 못먹었던게 며칠째 아쉬워서 꼭 먹으러 다시 갈게요^^ 프리오픈이던데 대박나셨으면 좋겠습니다!', 1, 5, 'GOOD', SYSTIMESTAMP);
