INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '인테리어가 아기자기해서 소품샵같고 이뻐용ㅎㅎ 그리고 메뉴가 다양한데 푸딩파르페가 특히 맛있어요!! 망고+커스터드 추천합니다🥰🥰', 95, 26, 'GOOD', SYSTIMESTAMP);
