INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '주디마리 푸딩 먹고 싶어서 20분 걸어왔어욯 아쉽게도 순수우유푸딩은 품절이지만 나머지 푸딩 포장했습니다. 오늘 시간 없어서 매장에서 못 먹어봐서 아쉬웠어요. 매장도 아기자기하고 너무 귀엽습니다.', 39, 6, NULL, SYSTIMESTAMP);
