INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '광주에 있을 때부터 택배로 시켜먹었는데 연남에 생겨서 너무 좋아요💟 맛 여전히 맛있고 매장내부도 너무 너무 귀여워서 사진도 잘나와요🐱 真漂亮😍 可爱😍', 71, 13, 'GOOD', SYSTIMESTAMP);
