INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '푸딩을 좋아하는 사람으로써, 여기 푸딩 정말 깔끔단백하게 맛도리입니다. 너무 느끼하거나 달아서 못드시는분들도, 여기서 드시면 푸딩의 매력이 무엇인지 느낄수있는 첫걸음이 될수있는 가게입니다.', 6, 1, 'GOOD', SYSTIMESTAMP);
