INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '제가 너무 애정하는 홍대 푸딩 맛집입니다🍮❤️ 커스터드랑 라즈베리 너무 추천해요!! 인테리어도 진짜 이쁘고 귀염 뽀짝해서 귀여운거 좋아하시는 분들 사진도 잘나오니 꼭 가보세요ㅠㅠ', 24, 9, 'GOOD', SYSTIMESTAMP);
