INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '푸딩온탑 추천드려요. 가성비로 좋아요! 푸딩하나, 음료하나 이케 세트메뉴라고 생각하시면 편한데, 저는 아아,말차푸딩 해서 7000원 나왔어요😆😆 매장은 귀염뽀짝하고, 인테리어가 너무 아늑하고 좋아요👍 인기가 많은 곳이라 캐치테이블로 웨이팅예약 했구요. 손님이 끊임없이 오더라고요...ㄷㄷ 1인1메뉴 원칙입니다! 내부는 좁아서 시끄럽고 불편할 수 있어요🤣🤣 참고로 화장실은 좁지만 깨끗합니다☺️🫶', 34, 6, 'GOOD', SYSTIMESTAMP);
