INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '알바생인지 사장님인지 모르겠는데 너무 불친절해요 파르페 시킬때 푸딩 바꿀 수 있냐고 물어봤는데 한숨 푹푹 쉬면서 대답해서 기분 나빴어요 돈내고 사먹는 소비자가 더 친절한듯. 푸딩파르페는 맛있었어요ㅜ', 115, 19, 'BAD', SYSTIMESTAMP);
