INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '이런 아기자기한 카페가 흔치 않은데 보는 것 만으로도 재미있어요 사실 푸딩만 보고 온 건데 커피도 맛있어서 놀랐어요 파르페도 옛날(?) 생각나서 추억에 빠지고 갑니다!', 20, 7, 'GOOD', SYSTIMESTAMP);
