INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '매장 자체가 너무 귀엽구 이뻐서 동화속에 들어온 것 같아요!! ㅠㅠ 너무 이쁘고 맛있어서 인터넷에서 시켜 먹어보고 반해가지구 방문한건데 매장 자체도 너무 이뻐서 자주 올 것 같아요', 12, 0, 'GOOD', SYSTIMESTAMP);
