INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '홍대 푸딩맛집이라고 해서 방문했는데 푸딩 찐찐맛집입니당🩷 꾸덕하면서도 망고랑 같이 먹으니까 더 맛있었어요!! 누텔라+크로플 조합도 최고,,❤️ 인테리어도 아기자기해서 예쁘고 동화속에 있는 것 같았어요! 음료도 다 너무 맛있었습니댱ㅎㅎㅎ', 6, 0, 'GOOD', SYSTIMESTAMP);
