INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '친구랑 놀러왔어용! 분위기는 하이틴 느낌 낭낭하니 넘 좋았고 음료도 맛있었어요 😆 아기자기한 소품들도 많아서 구경하는 재미도 있어요!', 23, 8, 'GOOD', SYSTIMESTAMP);
