INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '너무 예쁘고 귀염 귀염한 디저트 주디마리🥺🩷 카페 외관부터 눈길 사로잡혀 호로록 들어갔는데, 만원이라 캐치테이블로 예약하고 10분도 안되어서 매장에 들어갔어요! ✨ 푸딩파르페 바나나/망고 있는데 저는 바나나에 초코우유로 변경하고🍮 크림소다에 아이스크림 추가해서🍹 크로플이랑 같이 냠냠했습니다🥸🖤 비쥬얼 만큼 맛도 꿈꾸는 맛이라고 할까요.. 환상적이에요 오버아니고 진.짜. 존맛탱탱탱구리입니다🤪💓 다음에도 쿠폰채우러 방문해야겠어요..!!!!! 👍 +리뷰작성하고 받은 쿠키 귀엽고 맛있고 최고에요!!🐱🍒', 81, 15, 'GOOD', SYSTIMESTAMP);
