INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '푸딩을 너무 좋아하는데 지나가다가 푸딩카페가 있길래 호다닥 들어왔는데 인테리어도 너무 귀엽고 푸딩도 탱글탱글 맛있어요! 푸딩파르페 당충전 갑❤️✨', 38, 2, 'GOOD', SYSTIMESTAMP);
