INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '친구들이랑 놀다가 추천으로 왔는데 인테리어가 너무 귀엽습니다!!! 아기자기하게 볼게 많고 디저트류와 메뉴도 너무 알차서 결정하는데 너무 행복한 고민이었습니다🥺 직원분들도 친절하게 응대해주시고 깔끔해서 너무 좋았습니다! 데이트하기도 너무 좋을 거 같아요!', 80, 18, 'GOOD', SYSTIMESTAMP);
