INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '푸딩 파르페 메뉴가 정말 귀엽고 달콤 맛있어요💗 매장 인테리어도 짱 귀엽고 사진 찍기 좋아요! 깨끗하고 쾌적한 분위기에요 ㅎㅎ 추천합니다 ꒰ঌ(⃔ ⌯'' ''⌯)⃕໒꒱❤︎ꔛ❜', 12, 0, 'GOOD', SYSTIMESTAMP);
