INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '디저트 가격이 저렴한 편이고 여기 푸딩이 정말 맛있네요~~!! 민트초코 드셔보세요 진짜 편견을 뿌십니다 편견이 없었다면야 네 미안합니다. 도넛도 맛있었구 코튼바닐라라떼는 좀 달았어요 매장 분위기도 귀엽고 화장실도 깨끗했어요!', 13, 2, 'GOOD', SYSTIMESTAMP);
