INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '푸딩 톡톡 치는 재미가 있어요! 그릇도 너무 귀여워서 기분이 좋았어요 ㅎㅎㅎ 캬라멜 푸딩이 베스트인 이유가 있네요 제일 맛있었어요!', 267, 67, 'GOOD', SYSTIMESTAMP);
