INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '푸딩이 맛있음 특히 초코가 쫀득함 커스터드도 적당히 달고 맛있음 안 더우면 세트로 사가도 괜찮을 듯 가게 크기에 비해 좌석도 꽤 있고 다 컬러풀하고 귀엽다 아기자기하게 꾸며져 있어서 사진 찍기 좋음', 34, 5, 'GOOD', SYSTIMESTAMP);
