INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '주디마리 푸딩은 믿고먹는🥹🥹 어느 맛이나 시켜도 실패없구 매장도 너무너무 귀여워서 푸딩이 먹고싶으면 무조건 주디마리에 오는 것 같아요❣️오늘도 잘 먹구 갑니다>_<', 30, 4, 'GOOD', SYSTIMESTAMP);
