INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '주디마리 푸딩 너무 맛있어요🤍 여태 먹어봤던 푸딩 중에 제일 쫀득하고 식감 좋구 달달하니 맛있었습니다🫢 푸딩 파르페는 말해 모해,, 인테리어두 너무 예쁘고 홍대 오면 무조건 주디마리 올꺼에요💗', 110, 21, 'GOOD', SYSTIMESTAMP);
