INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '저번부터 너무 오고 싶어서 이번 기회에 친구랑 같이 와봤는데 정말 맛있어요!! 푸딩이 유명한 만큼 탱글말랑하고 맛도 진해요 ❤️ 에이드는 정말 상큼해서 푸딩이랑 잘 어울립니다. 친구가 아메리카노도 아주 맛있대요~~', 23, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
