INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '푸딩으로 유~명한 주디마리 드디어 갔다! 종류별로 다양한 푸딩에 잠시 눈 돌아갔지만 금전을 생각해서... 먹고 싶은거 2개만 주문 ㅜㅜ 바나나 푸딩 파르페는 푸딩의 종류를 바꿀수 있어 좋아하는 말차로 바꿔 봤는데... 의외로? 좋았다! 쌉싸름한 말차의 맛이 달디단 파르페의 맛을 중화 시켜줘 물리지 않게 다 먹었다. 처음보는 민초 푸딩은 똑같이 탱글탱글~ 화~한 시원함 + 초코의 달달 = 이거 좋은데?! 다음엔 네이버 메뉴에서 본 푸딩온탑을 먹으러 방문해야겠당', 18, 8, 'GOOD', SYSTIMESTAMP);
