INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '매장이 아늑하고 분위기가 좋아서 친구들과 수다 떨기 너무 좋은 곳이예요!! 사장님도 친절하시구 음료도 맛있습니당 재방문 의사 있습니다!! 인테리어 너무 귀여워요😀🤩', 107, 24, 'GOOD', SYSTIMESTAMP);
