INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '매장 분위기도 넘 예쁘구 디저트, 음료도 맛나용! 푸딩파르페 꼭 시켜 드셔 보셔요 마히따... 푸딩 따루 시켜 드시는 것두 추천 ㅎ 맛있어서 얼그레이랑 블루베리 푸딩 추가로 시켰어요!ㅎㅎ', 61, 16, 'GOOD', SYSTIMESTAMP);
