INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '푸딩이 미쳤어요 너무너무 맛있어요 광주에서 먹어보고 너무 맛있어서 홍대점까지 찾아오게됐는데 그냥 똑같아요 서울분들 광주안가고 서울에서 드세용 푸딩최고 라떼도 꼬숩고 넘 맛있어요 하트 스트로우 최고 💕 가게 분위기도 아기자기해서 방문 추천합니당', 18, 4, 'GOOD', SYSTIMESTAMP);
