INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '남자친구랑 놀러 왔는데 너무 아기자기 귀엽고 푸딩도 맛있고 직원분들이 엄청엄청 친절하십니다 우리집을 이렇게 꾸미고 싶을 정도로.. 짱이에요🥺🥺🥺🤍🤍', 65, 17, 'GOOD', SYSTIMESTAMP);
