INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '아기자기하고 예뻐요 푸딩은 덜 달고 젤리 같아요 딸기셰이크는 맛있었지만 내 취향은 아니었던... 푸딩 파르페도 맛있지만 뭔가 더 씹히는 게 많았으면 하는 아쉬움 가게는 사진 잘 나오고 예쁘지만 다시 방문하기엔 망설여질 것 같다', 24, 8, NULL, SYSTIMESTAMP);
