INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '푸딩 좋아해서 나름 여러집 가봤지만... 여기처럼 비주얼도 맛도 역대급인곳은 처음... 메론소다도 보이시나요... 이 비주얼... 진짜 사진을 안찍을 수가 없었음... 리뷰 길게 남ㄱㄹ 필요없음. 어차피 여긴 또와서 또 리뷰 남길꺼니까....', 23, 1, 'GOOD', SYSTIMESTAMP);
