INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '생각보다 유명한 거에 비해서 그렇게 푸딩이 특별하게 맛있다고 생각되진 않았어요..! 오히려 커피가 생각보다 맛있었네용 인테리어가 예쁘고 사람도 많지 않아서 편하게 있다 갔습니다', 3, 7, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '주디마리에 홍대에서 지점이 생겼다고 해서 제가 가봤는데요! 최고였습니다! 푸딩의 맛! 키치하고 귀욤뽀작한 인테리어! 깨끗한 화장실(그러나 컨셉은 확실히 지킨)! 탱글푸딩보다는 쫀득푸딩에 가깝고요 무엇보다 푸딩파르페가 있다는 점이 정말 최고가 아닐까 싶습니다... 푸딩 종류가 많다는 것도 좋고 쿠키류도 있어서 더 더 좋은 주디마리...♡', 21, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '지나가다 외관이 예뻐서 들어왔는데 최고예요...ദ്ദി=´∀｀) 푸딩이랑 크로플이 주 디저트인 거 같아요! 비주얼도 귀엽고 맛도 있었습니다. 외관도 그렇고 안도 귀여워서 친구랑 사진 계속 찍었습니당! 아, 그리고 서비스로 푸딩을 주셔서 먹어봤는데 그것도 맛있었어요! 다음에 오면 푸딩 시켜서 먹어보려구요ㅎㅎ 추천추천합니닷!', 2, 9, 'GOOD', SYSTIMESTAMP);
