INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '푸딩이 너무 맛있어보여서 왔는데 매장이 정말 아기자기하고 귀여워서 기분이 좋아졌어요😆그리고 직원분께서 너무너무너무 친절하셔서 마음이 따뜻해졌어요☺️푸딩파르페 진짜 맛있고 스무디랑 쿠키도 맛있었어용 다음에 또 오고 싶어요🤍🤍', 15, 7, 'GOOD', SYSTIMESTAMP);
