INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '매장이 아기자기 하니 귀욤귀욤합니다 음료도 종류가 많고 쿠키도 먹기 아까울 만큼 깜찍하네요 푸딩은 후회하지 않을만큼 맛있습니다', 106, 23, 'GOOD', SYSTIMESTAMP);
