INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '매장이 앙큼함 . 푸딩이 달콤함. 근데 진짜, 적당히 한국인이 좋아할 당도의 푸딩이라 별의 커비가 되,. 초코,커스타드 푸딩 너무 은혜롭다.., 근데 크림소다는 좀 머리가 아플정도로 달아서 다음에는 다른 음료를 마셔보겠습니다.', 125, 22, NULL, SYSTIMESTAMP);
