INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '팝업으로 먼저 맛보고 서울에도 매장으 있다길래 호다닥 방문했어용 😚😚😚🩷 푸딩 말해뭐해~~~  포동포동하고 부드럽구 달달한게 너무 맛있었습니당 🍮🩷 특히 푸딩파르페가 너무 좋았어요🥹👍 첨 주문했던거 다 먹고 아쉬워서 또 주문했네용 🤭🤭🤭 쿠키류도 엄청 귀엽고 맛있었어용 선물용으로도 너무 좋울둣!!!!!🤎💛 푸딩 포장한다니까 따로 체크했다가 나중에 매장 나가기 전에 주심!! 👍👍👍 직원분들두 친절하시구 화장실두 깨끗해서 좋았어여🫶', 71, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '솜사탕 올라간 라떼는 조금 과하게 달았고 커스터드 푸딩도 기대보다는 쏘쏘했어용 근데 민초 푸딩이 찐이예요 민초 러버로써 민초 푸딩만 몇번을 포장해먹은지 몰라요 지금도 민초 푸딩 먹고 싶어요ㅠㅠㅠ 라즈베리?도 저번에 서비스 주셔서 먹어봤는데 괜찮았던 것 같아요 근데 민초 푸딩 드세요 제발', 39, 9, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '푸딩이 먹고 싶어서 찾아온 카페입니다. 푸딩 전문이고 1인 1음료가 필수여서 3명이서 딸기푸딩파르페로 세 개 주문했습니다. 외부 인테리어부터 비비드한 컬러로 키치한 느낌으로 내부가 꾸며져 있습니다. 간만에 먹는 파르페라 너무 맛있네요. 푸딩+과자+아이스트림+생크림을 한큐에 잡을 수 있어요. 직원분도 옷을 키치하게 귀엽게 입으셨어요. 푸딩 드시고 싶으실 때 추천합니다.', 73, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '푸딩이 정말 탱글탱글하고 뒤에 커스타드 맛이 달콤하게 올라오는데 입에 남는 맛은 무겁지 않아서 넘 좋았어요 특히 개인적으로 딸기파르페에 후르츠링 넣는 걸 좋아하는데 그 점까지 완벽했어용 사장님도 넘 친절하게 안내해주셨습니다 ^_^', 21, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '딸기푸딩파르페가 시즌메뉴라 있을 때 꼭 먹으러 와야할 정도로 정말 맛있고 이뻐요!! 커스터드 푸딩도 정말 맛있고 우유푸딩도 정말정말 맛있어요!! 그리고 외관도 동화속에 온 것 같고 내부도 아기자기해서 정말 귀여워요!!🍮🎀', 3, 8, 'GOOD', SYSTIMESTAMP);
