INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '밖에서부터 눈에 확 띄는 주디마리... 푸딩 맨날 택배로 시켜먹다 광주까지 가야 하나 했었는데 홍대에 생겨서 너무 좋아요!! 푸딩은 포장하려고 메론소다만 시켜서 먹었는데 음료도 맛있네요 🍮💚', 78, 13, 'GOOD', SYSTIMESTAMP);
