INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '푸딩 맛집이라고 소문나서 먹으러 왔는데 소문처럼 진짜 맛있어요!! 한국에서 이런 커스타드푸딩 먹을일이 많지 않은데 좋은 곳을 찾게 되어서 너무 기뻐요 매장이랑도 가까워서 자주 사러 올 것 같아요!! 사장님도 너무 친절해요💖', 32, 0, 'GOOD', SYSTIMESTAMP);
