INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '인테리어가 너무 귀여움 쿠키가 귀여워여!!! 사장님이 신메뉴 나온다고 서비스로 푸딩도 주셨어요😆 넘나리 맛있음!! 다음에 후배들 데리고 올 예정이에용', 42, 4, 'GOOD', SYSTIMESTAMP);
