INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '추천받았던 가겐데 우연히 지나가다 들렸어요~ 인테리어도 귀엽고 쿠키 포장이 특히 귀여워요!! 푸딩은 당연히 유명한 만큼 맛있어서 근처 지나갈 일 있으면 또 방문 하려구요~', 0, 9, 'GOOD', SYSTIMESTAMP);
