INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '들어가자마자 분위기가 너무 예뻐서 감탄이 나왔어요 직원분께선 너무너무 친절하게 대해주시고 푸딩도 서비스로 주셔서 너무 좋았어요 사진도 예쁘게 잘 나오고 첫 방문 아주 만족스럽습니다!', 31, 7, 'GOOD', SYSTIMESTAMP);
