INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '인테리어도 좋고 디저트도 최고고 주말마다 항상 오는 카페인데 알바분들도 너무 친절해서 절로 기분이 좋아요☺️☺️☺️💕 꼭 번창하셨음 해요 응원합니다!!', 45, 4, 'GOOD', SYSTIMESTAMP);
