INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '매장도 너무 귀엽고 사장님도 진짜 친절하셔요🥹🥹,, 서비스도 주시고 정말 행복했습니다.. 이렇게 귀여운 디저트는 처음이예요진짜로최고의푸딩..... 다먹고 백개 싸가고 싶은 가게예요🥹❤️‍🔥❤️‍🔥', 0, 9, 'GOOD', SYSTIMESTAMP);
