INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '다들 맛있다고해서 기대하고 왔는데 기대한거보다 더더 맛있었어요 🥹 너무 맛있어서 서울 올때마다 먹고싶을 거 같아요 .. 파르페도 제가 먹은 파르페 중에 가장 맛있었고 뭔가 쫀득한 푸딩이라 맘에 들었어요 가성비도 최고 🩷🩷', 15, 2, 'GOOD', SYSTIMESTAMP);
