INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '일단 인테리어가 무지 예뻐요 정말 아기자기해서 동화 속에 들어온 기분이 들었어요! 사장님도 무지 친절하시고 메뉴에 특이한 푸딩들이 많아서 너무 좋았어요 말차랑 민트초코 둘 다 너무 맛났답니다,, 녹차푸딩은 시키지 않은건데 서비스로 주셔서 너무 감사하고 놀랐어요  다음에 오면 다른 맛들도 꼭 먹어보고싶어요 🥹🩷', 33, 6, 'GOOD', SYSTIMESTAMP);
