INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '매니저님이 맛있고 푸딩이 친절해요... 💗 매장 너무 키치하고 메인 벽에 있는 사장님이 손수 그리셨다는 귀여운 그림...! 사진 못 찍은 게 너무 아쉬워요 🥹 너무 너무 귀엽고 또 올 거예요!! 푸딩도 짱 맛 탱 ♥️', 4, 9, 'GOOD', SYSTIMESTAMP);
