INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '주디마리가 가보고싶어서 광주까지 다녀왔었는데 홍대에 생겼다고해서 달려왔습니다❤️❤️ 푸딩 파르페를 먹어봤는데 다시먹어봐도 푸딩이 맛잇고 …이렇게 례쁜 가게에서 파르페를 먹어보는 로망? 이있었는데 실현해서 기뻐요.^_^ 가게 내부도 키치하게 잘 꾸며져있습니다.🥰', 0, 9, 'GOOD', SYSTIMESTAMP);
