INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), 'sns를 통해서 알게 된 이후로 항상 오고 싶었던 곳인데 드디어 오늘 오게 됐어요🥹 푸딩 파르페가 정말정말 맛있어요,, 매장에서 드시는 분들께는 푸딩파르페를 드시길,,, 강추합니다💖🍓 인테리어두 넘 아기자기하구 예뻐요! 알바생 분들도 너무너무 친절하셔서 좋습니당〰️😆', 185, 80, 'GOOD', SYSTIMESTAMP);
