INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '웨이팅은 길었지만🥲 들어가는 순간 아기자기한 인테리어에 종류많은 푸딩이 있는 곳이에요 :) 기본인 카라멜커스타드푸딩 먹었는데 먹어본 푸딩 중에 쫀득하고 적당히 달아서 정말 맛있게 먹었어요 ㅠㅠㅠㅠ 푸딩파르페 비주얼 미쳤어요 사진 너무 예쁘게 나옴💕💛', 50, 0, 'GOOD', SYSTIMESTAMP);
