INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '크로플을 받자마자 너무 이뻐서 기절할뻔했어요..! 매장 분위기도 뽀짝하고 알바생 분들도 너무 친절하셔서 혼자 행복한 시간 보내다가요 😋', 61, 15, 'GOOD', SYSTIMESTAMP);
