INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '푸딩맛집! 카페 알록달록 색감도 이쁘교 매장 안쪽 인테리어도 귀여워요~!! 일요일인데 운좋게 웨이팅없이 입장 성공! 다음에도 또 방문할 예정입니다>_<', 81, 18, 'GOOD', SYSTIMESTAMP);
