INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '딸아이가 와보고 싶다고해서 왔는데 평일인데도 사람이 많았어요 직원분 아주 친절하구요 매장에서 먹을땐 1인1음료 필수랍니다 음료도 맛있고 얼그레이랑 말차 푸딩 시켰는데 굿굿! 크로플도 맛있습니다', 97, 22, 'GOOD', SYSTIMESTAMP);
