INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '지나가던 길에 너무 아기자기해서 들어와봤요!! 밖에서도 귀여운데 내부 인테리어도 너무 귀여웠어요! 크로플도 맛있었어요! 우연히 들렸는데 좋은 곳 발견한것 같아요✨', 3, 6, 'GOOD', SYSTIMESTAMP);
