INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '푸딩 참 잘허는 집. 민트초?코 이건 이해 할 수 없디만, 다른건 따봉따봉 .  커스타드,초코,얼그레이,말차,딸기 다 맛있습니다.', 80, 13, 'GOOD', SYSTIMESTAMP);
