INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '푸딩🍮이 쫀쫀하고 달달하니 맛있어용☺️ 사는 곳이랑 멀리 있어서 항상 인스타로 보다가 홍대점 생기고 방문했는데 상상한 그대로라 참 좋숩니댜~ 오렌지 비앙코도 색다른 맛이라 넘 신기하고 맛있습니댜 :D', 31, 5, NULL, SYSTIMESTAMP);
