INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '처음 가봐서 주문할 때 조금 시간이 걸렸음에도 불구하고 너무 친절하게 대해주시고 푸딩도 너무 맛있어서 넘 넘 좋았어요 ㅠ . ㅠ 재방문 100% 확정이예요!! ❤︎', 21, 8, NULL, SYSTIMESTAMP);
