INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '푸딩파르페  커스타트푸딩과 얼그레이푸딩으로 주문 둘다 너무 맛있습니다. 웨이팅이 길었지만 시즌푸딩 꼭드세요. 포장도 가능하네요.', 23, 2, 'GOOD', SYSTIMESTAMP);
