INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '너무 맛있어요!!!! 노래도 좋고 분위기도 좋아요 ◡̈  궂은날씨에 방문해주셔서 감사하다고 우유푸딩도 서비스로 주셨어요!! 다음에 재방문의사 완전 있어요! 번창하세요~~!🍀🍀', 80, 14, 'GOOD', SYSTIMESTAMP);
