INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '카페 너무 귀엽고 !!! 분위기도 좋아요 !! 푸딩 안달고 땡글땡글해서 너무 맛있고 식감도 좋았어요 ! 푸딩맛집이에요 ㅋㅋㅋ 추천합니다 !!', 49, 4, 'GOOD', SYSTIMESTAMP);
