INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '딸기우유푸딩이 신메뉴로 나왔길래 방문했어요! 접시도 푸딩도 벚꽃같아서 너무 귀여워요 (*⌒３⌒*) 메론소다에 아이스크림도 너무 맛있어용 최고♡♡', 5, 8, 'GOOD', SYSTIMESTAMP);
