INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '가게가 너무 예쁘고 디저트도 맛있어요🥺🤍🤍 인테리어도 귀엽고 깜찍해서 사진도 잘 나와요..💓 푸딩라떼 꼭 드시길… 귀엽고 맛있음!!!!', 10, 9, 'GOOD', SYSTIMESTAMP);
