INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '푸딩으로 유명하다해서 친구랑 같이 왔어요! 푸딩 종류도 다양하고 파르페도 있어서 좋았어요ㅜㅜ 담에 푸딩 먹고싶을때 또 방문할 것 같아요💕 사진도 대충찍는데 뭔가 느낌있게 찍히는 기분이 드는 그런 곳이에요😊', 39, 7, 'GOOD', SYSTIMESTAMP);
