INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '내부도 외부도 예쁘고 파르페가 진짜 맛있었어요 푸딩이 바로 부서지는 흐물한 푸딩이 아니고 쫀득한 느낌이라 너무 좋았어요 재방문 의사 너무 있어요', 411, 80, 'GOOD', SYSTIMESTAMP);
