INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '우유푸딩 너무 맛있어서 또 왔어요..💗 얼그레이는 오늘 처음 먹어봤는데 우유랑 투탑으로 맛있는 거 같아요!!! 분위기도 아늑해서 오랜만에 친구랑 즐겁게 얘기하다 가요ㅎㅎ 완전 강추! 알바생분도 완전 친절하시구 귀여우세요.. 여러모로 너무 좋았어서 재방문 의사 만땅입니다😚', 40, 10, 'GOOD', SYSTIMESTAMP);
