INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '파르페 첨 먹어봤는데 너무 맛있었어요🤭🤭 친구랑 같이 블루소다 시켜먹었는데 이것도 맛있어요💋💋 가격도 적당하고 무엇보다 인테리어 넘넘 이뻐요!!!!! 쿠키도 귀엽고 직원분들도 완전 친절하셔서 기분 좋았어요😉😉', 118, 20, 'GOOD', SYSTIMESTAMP);
