INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '푸딩 맛집이라구 그래서 기대했는데 홍대에 생겼다는 소리에 후다닥 방문했습니다! 음료도 다 너무 귀엽고 예쁘게 나오고 매장도 벽지나 꾸며둔 게 엔틱해서 너무 좋았어요! 어머니랑 방문했는데 보기 좋다구 서비스로 푸딩 하나 주셨어요 다음에 친구랑 또 와야지... 라즈베리 푸딩이랑 초코푸딩 짱 맛있어요 홍대에 유명한 푸딩집 다 가봤는데 진짜 원탑 🥹🩷🩷🩷', 31, 6, 'GOOD', SYSTIMESTAMP);
