INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '문익점 푸딩으로 유명한 주디마리가 홍대에 왔다는 것은 제가 앞으로 홍대 갈 때마다 들른다는 이야기가 될것입니다 넘넘 맛있고 다음엔 포장할거예욤-!!!!', 16, 6, 'GOOD', SYSTIMESTAMP);
