INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '주디마리 홍대점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '집 근처에 새로 카페가 생겨서 와봤는데 분위기가 아기자기하고 푸딩도 너무 맛있어 보였어용! 메론소다 파는 카페도 몇 없는데 다양한 음료 메뉴도 있어서 너무 좋은 거 같아용😀 자주 방문하겠습니당 :)', 3, 1, 'GOOD', SYSTIMESTAMP);
