INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바이앤드커피'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '분위기 커피 맛집 바이엔드커피💛 시그니처메뉴인 바이앤드라떼 아이스와 아인슈페너 아이스와 화이트치즈케이크를 먹었는데 와..넘 힐링되는 맛과 공간. LP음악과 식물, 감각적인 인테리어가 이 공간에서 커피를 마시는 시간의 행복을 느끼게 해주었당 꼭 가보세요 자주 찾고싶은 공간💕', 110, 22, 'GOOD', SYSTIMESTAMP);
