INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바이앤드커피'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '유럽 어느 가정집에 놀러온 듯한 편안하고 멋진 공간입니다. 음료는 전반적으로 괜찮은 편이고, 베이커리도 준수한 편이예요. 그럼에도 불구하고 여기를 꼭 방문해야하는 이유는 바로 치즈케이크에 있습니다. 은은한 단맛에 징한 치즈의 향 그리고 쫀득한 식감응 묘한 카타르시스를 느끼게해줘요. 지금 이틀 연속 방문 중이고, 당분간 계속 오게될것 같아요! 👍', 39, 1, 'GOOD', SYSTIMESTAMP);
