INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바이앤드커피'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '커피랑 디저트 다 맛있구 분위기도 넘 좋아용. 해가 잘 들어와서 자연광이 예쁜 곳이에요. 멍푸치노가 있는 걸 보니 강아지도 같이 올 수 있나봐여. 다음엔 같이 와야겠어여><', 18, 8, 'GOOD', SYSTIMESTAMP);
