INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바이앤드커피'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '디저트 맛집이네요..꾸덕하고 얼그레이향 찌인한 파운드케이크 진짜 맛있고 바치케도 촉촉해서 맛있었어요! 특히 시그니처 바이앤드 라떼는 고소해서 정말 맛있었습니다!!! 합정역 최애카페가 될 거 같아요😍', 9, 3, 'GOOD', SYSTIMESTAMP);
