INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바이앤드커피'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '아담하고 아늑한 분위기의 쉼터 같은 카페입니다😁 홍대 돌아다니다 사람들에게 이리저리 치이고 더워서 지쳐있을 때 방문했는데요! 시원한 에이드랑 다양하게 준비된 커피 메뉴들, 든든한 잠봉뵈르랑 치즈케이크 하나씩 먹으니 다시 기운 만땅이네요🔥 특히 잠봉뵈르가 진짜 맛있는데 방문하시는 분들은 꼭 드셔보시길 추천드립니다👍', 83, 18, 'GOOD', SYSTIMESTAMP);
