INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바이앤드커피'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '☕️ 바이앤드라떼 5,000원 🍹피치앤드체리 에이드  6,000원 🍞 바닐라빈파운드 3,500원 커피는 맛있는데 에이드는 너무 달고 파운드도 달고.. 크림은 느끼하고ㅠ 아쉬웠어요', 80, 16, 'BAD', SYSTIMESTAMP);
