INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바이앤드커피'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '우연히 들어간 카펜데 라떼도 짱 맛있구 음료도 맛있었어요 편한 쇼파 의자도 있어서 잠깐 쉬고가기에 딱 이었습니다 ^_^ 음악도 좋고  lp 컵받침이 인상적이었던 바이앤드커피 ☕️  담번에 홍대에 오게되면 또 들릴려구요~💖', 38, 2, 'GOOD', SYSTIMESTAMP);
