INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바이앤드커피'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '분위기도 외국온거같고 소품들도 힙합니다ㅎㅎㅎ바이앤드라떼는 블렌딩한우유가 들어가서 너무 맛있고 잠봉뵈르랑 흑임자파운드도 맛도리입니다!!!! 흑임자파운드 위에 크림이 꾸덕꾸덕해서 할미입맛들에게는 강츄!!', 314, 95, 'GOOD', SYSTIMESTAMP);
