INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바이앤드커피'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '분위기 너무 좋은 카페라 완전 반했어요. LP직접 틀어주시고 조명도 시간에 따라 변해서 분위기 넘 좋더라구요. 시그니처 라떼도 정말 맛있고 케이크도 크로플도 정말 맛있었습니다.', 40, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바이앤드커피'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '좌석 한 서너개 되는 작은 카페입니다. 좌석 한 개는 전면 유리를 보고 앉게 되어 있어서 연인끼리 와도 좋을 분위기이고요, 감성 있게 LP판(레코드 판)을 틀어 놓았더라고요, 쿠바 해변에 있는 카페에 온 느낌이랄까... ㅎ 라떼 시켰는데 커피 맛이 유난히 부드러운게, 뭔가 비법이 있는 듯 합니다. 특히 1시까지 점심시간 할인이 들어가서, 값싸게 맛있는 커피 즐길 수 있어요! 주문/써빙 하시는 분 한 분이시던데, 대학생 정도로 워낙 어려 보이는 여자분이라 직원분인지 사장님인지는 모르겠으나, 친절하시고 상냥해서 좋았습니다. 이 근처 직장인이라면 점심 식사 후 커피 한 잔 좋을거 같아요~^^!', 316, 69, 'GOOD', SYSTIMESTAMP);
