INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바이앤드커피'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '🏅🏅🏅 ♡ 멜론바이애플 (6,000) ♡ 아메리카노 (4,500) ♥ 맛 - 멜론바이애플 : 목이 너무 말라서 그런지 너무 시원하게 원샷해버림. - 아메리카노 : 커피는 살짝 연하다는 일행의 말이 있었지만 아무렴, 분위기 때문에 다 좋게 느껴짐. ♥ 내부 : 좌석이 많진 않았지만 아늑한 느낌이 좋았습니다. 인테리어가 굉장히 마음에 들었던 곳. 사장님이 디자인을 아시는 분 같음!ㅎ ♥ 총평 : 우연히 지나가다 갑자기 들어온 곳인데 크리스마스 분위기가 너무 느낌 있게 인테리어 되어 있어서 좋았습니다🎄🎅🏻 분위기가 너무 좋아서 좋은 시간 보냈습니다!', 128, 24, 'GOOD', SYSTIMESTAMP);
