INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바이앤드커피'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '좋아하는 동네카페 입니다. 편한 분위기와 서비스 친절합니다! ^^ (혹시 원두와 디저트레시피 변경됐을까요? 커피와 디저트가 이전과 맛에서 변한것 같네요~^^;; 예전에 깊고 진한맛이 좀 그립습니다!!) 그래도 맛있게 먹었어요!!', 28, 5, NULL, SYSTIMESTAMP);
