INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바이앤드커피'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '인테리어 너무 깔끔하고 의자도 편해서 자주가기 좋아요 커피도 넘맛있어요 직원분들도 다들 친절하셔서 좋네요😀다음에 또 올게요!!', 2, 0, 'GOOD', SYSTIMESTAMP);
