INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바이앤드커피'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '사장님도 친절하고 자몽에이드 킬러로써 여기 넘나 맛있었어여! ㅋㅋㅋ 혼자가도 부담스럽지 않아서 좋음 저녁에는 하우스와인도 파셔서 간단하게 마시기도 좋았어요ㅎㅎ 여러모로 자주 갈 예정👏🏻', 20, 3, 'GOOD', SYSTIMESTAMP);
