INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '크림뷔릴레도넛의 크림이 부드럽고 달지않아 먹기좋네요 버터넛도 그렇게 달지않고 빵이 다른도넛에 비해 쫄깃해서 새로워요. 아메리카노랑 같이 먹으면 맛있어요 인테리어가 귀엽고 깔끔한데 2층도 분위기가 달라 대화하기 좋아요', 19, 8, 'GOOD', SYSTIMESTAMP);
