INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '주말에 홍대 나들이 갔는데 카페마다 사람이 너무 많아 들어갈 곳이 없어 골목골목을 헤헤던 중 만난 올드페리도넛! 우리 동네에서 보던 도넛집을 홍대에서 보니 너무 반갑다~ 도넛 너무 맛있어~~~~', 51, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '매장이 귀엽고 깨끗하고 시원해서 더운 날씨에 머무르기 편안했어요.. 직원 분들도 많이 친절하세요. 도넛 가격이 비싸다 싶었는데, 그만큼 맛있어서 괜찮았어요. ㅎㅎㅎ 저녁 시간에 갔더니 도넛 대부분 sold out이라서 아쉬웠어요. 종류별로 먹어보고 싶었는데요. 유자레몬티은 기대 없었는데 생각보다 맛있어요. 가까운 다른 지점으로 또 가보고 싶으네요.', 18, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '2층 매장이라 은근 큼 ! 근데 사람이 짱 많 ! (주말낮) 도넛은 말모.. 달달구리 마싯음.. 피넛버터 크림브뢸레... 🍩 🤤 🍩 (가격이 결코 저렴하지 않은) 말차라떼도 참 진하고 맛있엇음 !', 25, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '사람이 많다고 들었었는데 주말인덷ㅎ 오픈어택 때리니까 아무도 없었어요!ㅎㅎ 하긴 너무 아침이긴 했습니다😂 크림브륄레를 기대했었는데 피넛버터가 지인짜 맛있었어요🍩 어엄청 달지도 않고 퐁신해서 딱 좋아요! 그리고 기대 안했는데 커피가 맛있었어요! 도넛이랑 찰떡궁합! 대표4구포장 선물용으로 바아로 구매해갔습니다✨', 26, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '마감 가까운 시간에 방문해서 원하는 도넛이 없어서 라떼와 아메리카노만 먹었는데요. 이 집은 특히 산미가 적어서 커피가 입에 딱 맞았어요. 자연도소금빵 올려서 사진만 찍어 봤습니다. ㅎㅎ 일층 야외공간은 선선하고 분위기가 좋지만 카페 앞에 오토바이 동호회가 자주 오는 바 같은 곳이 있어서 소음 공해가 좀 있어요.', 45, 7, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '종종 생각날 때가 있는데 연남동에 올드페리도넛이 생겨서 좋아용! 젤 많이 나가는 우유크림도넛 먹었어용! 역시 쫄깃하고 맛있어오!🤤 한 개 구매해도 도시락 케이크 포장상자에 포장해주셔서 간단하게 선물용으로도 좋을거 같아요! 넘 귀여워용!', 11, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '기대하면서 포장해왔는데 집에와서 열어보니 머리카락이 붙어있네요ㅜㅜ 테이프로 여는부분을 봉해주셔서 매장에서는 받고 바로 열어보지 못했는데... 담아주실때 확인을 잘해주셔야 할거같아요... 다시 가서 환불해올수 있는 거리도 아닌지라 좀 속상하네요... 다음부터는 꼼꼼히 확인 부탁드려요', 10, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '유명한 도넛들 많지만 제가 유일하게 좋아하는곳이 올드페리에요💙🧡 연남동 매장은 처음방문이었는데 장소가 넓고 여기저기 포토스팟이 많아서 즐거운 시간이었습니다:)', 4, 9, 'GOOD', SYSTIMESTAMP);
