INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '우유크림도넛브레드 무금 저번애 티라미수 먹고 넘 맛나서 컬리로 주문하려다가 컬리는 냉동이라해서 걍 내가 직접와서 사먹음 무엇보다 저 캐릭터가 자꾸 생각나서 보고옴 나랑 몸매가 좀 비슷한 저녀석..', 20, 1, 'GOOD', SYSTIMESTAMP);
