INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '피스타치오와 버터도넛 각각 먹었는데 둘 다 맛있었어요 근데 버터도넛이 좀 더 적당한 단맛이 살아있어 개인적으론 버터도넛이 더 맛있었어요 피스타치오는 훨씬 더 단맛이 강해요 창가자리에 앉아 먹으니 맛이 배가 되었네요', 59, 18, 'GOOD', SYSTIMESTAMP);
