INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '랜디스보다 100배 맛있고 친절합니당 피스타치오 ? 맛있어요, 외국인많고 2층에는 노트북 키고 카페처럼 이용하는분들 많네요 근데 화장실이…80년대도 시장통도 아니고 변기통 다 뜯어져있고 휴지없고 개판5분전', 416, 67, 'BAD', SYSTIMESTAMP);
