INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '자꾸 생각나는 맛!! 코코넛이랑 피넛버터, 보스턴은 항상 고정으로 사먹는 메뉴입니다!! 매장에는 구운도넛류도 있어서 크런치한 초코 도넛 먹었는데 맛있었어요', 32, 5, 'GOOD', SYSTIMESTAMP);
