INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '용산 아이파클몰 갔을때 사서 먹고 또 생각이 났는데 컬리서 주문할까 하다 오늘 마침 연남동 가니까 꾹참고 드디어 샀네요~ 피넛버터 안먹었는데 여기껀 맛있더라구요~ 피스타치오는 원체 좋아해서 무조건 맛있구요~ 우유크림도 접때 맛있어서 골랐고 보스턴크림은 이번에 첨사봐요~~ 연남동에 올드페리까지 있어서 너무 좋네요~', 20, 1, 'GOOD', SYSTIMESTAMP);
