INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '매우 좋아하는 도넛 가격이 저렴하지 않다고 생각합니다만.. 워낙 도넛이 실속있고 맛있어서 자주 갑니다.. 연남점 처음 방문 위치가 매우 좋은 것 같습니다.. 맛있어요~', 32, 9, 'GOOD', SYSTIMESTAMP);
