INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '보스톤 크림 맛있네요! 아메리카노도 단 도넛이랑 같이 먹기 좋은 맛이라서 페어링이 좋았어요 다만 조금 비싸다는 점이 있는데 적당한 가격이라 생각해요 가끔 생각날것같아료호호', 121, 19, 'GOOD', SYSTIMESTAMP);
