INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '늦게 가서 사고 싶은게 다 품절이라 라즈베리 도넛 포장해왔어요~ 늠나 맛있네요! 라즈베리 필링이 가득하고 노티드랑은 또 다른맛이에요! 뜨아랑 찰떡이에요~', 10, 1, 'GOOD', SYSTIMESTAMP);
