INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '서울 3대 도넛인지, 세계 3대도넛인지.. 아무튼 그 3대 도넛중에 하나인 올드페리도넛입니다. 최근에 연남동에 오픈했다고 해서 다녀와봤는데, 우와...역시나 3대 500보다 위대한 맛이었어요. 사람들도 어찌나 많은지 줄서서 도넛을 구매해야 합니다. 매장도 크고 넓어서 데이트코스로도 추천드릴게요. 대부분의 도넛이 다 맛있었지만, 개인적으로는 피넛버터를 추천드립니다. 너무 고소하고 너무 맛있었어요. 또 먹고 싶어지는 맛이었습니다. 근처 가실일 있으면 꼭 들려보세요.', 85, 18, 'GOOD', SYSTIMESTAMP);
