INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '카페였는데 올드페리도넛집이 생겼네요. 독채이고 매장넓고 훌룽하네요.친절하고 좋아요. 근처 랜디스도넛.노티드도넛과 좀더 색다른 느낌도넛카페네요.2층도 상당히넓고 창이넓어서 좋네요.도넛이 꾸덕꾸덕 특이한식감.맛괜찮네요. 단지 종류가 다양하질않아서 아쉬워요.', 38, 6, NULL, SYSTIMESTAMP);
