INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '우유크림, 보스톤크림, 버터크림 먹고 왔는데 소문대로 도넛빵이 쫀득쫀득하고 맛있네요ㅎㅎ 단거 각오하고 먹었는데 생각보다 느글거리지 않는 달달함이여서 괜찮았어요! 카페 공간도 넓고 좋아요~~', 50, 8, 'GOOD', SYSTIMESTAMP);
