INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '주택을 개조해서 인테리어 한 부분이 멋졌어요 눈에 띄고 들어가고 싶게 꾸며져있습니다 커피와 함께 당충전 잘했는데 아쉬웠던 점은 그날만 그랬는지 커피가 과하게 다크로스팅이라서 많이 썼습니다 아이스 아메리카노였는데도ㅠ', 52, 17, NULL, SYSTIMESTAMP);
