INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '피스타치오도넛 맛나더라구요 커피는 그저그랬.. 매장 넓어서 편히앉아 쉴수있더라구요 도넛종류많고 다 맛보고싶었지만 쪼매 비싸 안 싼게 없는터라 암튼  음료는 맛없었... 도넛은 맛있어요', 63, 18, NULL, SYSTIMESTAMP);
