INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '랜디스랑 노티드만 있었는데 뚝딱뚝딱 공사하더니 오잉. 올드페리도넛 생김 멀리 안가서좋긴한데..훔..... 아침일찍가서. 붐빔도없음 도넛도  랜디스랑 노티드 중간의 폭신함.  달달함이. 랜드스랑비슷함 그러나 계산하시는분이 너무 불친해서 다시는 안가고싶음. 도넛 고르는것부터 눈치줌. 바쁜시간도아니고 사람별로없음. 힘들어서. 지쳐서 불친절한건 이해가능한데 이건뮈...', 42, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '원래 도넛을 그리 즐기는 편은 아니었는데 새롭게 눈을 떴달까요! 커피와 도넛의 궁합이 최고네요 :-) 무엇보다도 도넛 빵이 넘 쫄깃하고 크림 풍미가 좋아서 실컷 먹다가 집에까지 포장해서 사들고 왔습니다ㅋㅋ 버터피스타치오랑 코코넛 도넛은 꼭 드세요!!! 새로생긴 매장이라서인지 깨끗 쾌적했고 힙한 인테리어가 사진에 고스란히 담겨서 좋았어요. 전체적인 색감도 예뻤지만 뚱뚱이 곰 캐릭터가 특히 맘에들었구요 ㅋㅋ 도넛먹는 곰 너무 귀여운것 같아요. 굿즈들도 다양하던데 나중에 여유있게 가서 득템해야겠어요🤭 직원분들도 친절하셔서 기분좋게 머물다 왔습니다~ 주 생활권과는 거리가 멀어서 막 자주 방문하진 못할것같지만 종종 일부러라도 들러볼만한 곳이란 생각이 듭니다!', 7, 9, 'GOOD', SYSTIMESTAMP);
