INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올드페리도넛 연남점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '저녁 늦게 테익아웃했는데 도넛이 건조하고 너무 맛없어서 충격적이었어요. 웬만하면 다 상향평준화 되어 있어서 무난할텐데 특히 핑크스프링클 너무나 비추합니다….', 5, 8, 'BAD', SYSTIMESTAMP);
