INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미스터크레페'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '4900원 스몰 해피크레페 먹었는데 사진과는 다르게 토핑이 마시멜로우랑 츄러스같은거 각1개씩 넣어주셨어요. 참고로 같은 종류 라지사이즈는 8,900원이였구요. 크레페는 수제는 아니구 또띠아 데워서 접어주시더라구요 반죽으로 데워서 만드는 얇은 크레페는 아니였어요. 다음에 라지사이즈먹어볼게요!', 123, 22, NULL, SYSTIMESTAMP);
