INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미스터크레페'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '홍대에서 갑자기 찾아들어왔는데 너무 맛있어요 매장이 좁지만 앉을자리도 있고 충분히 여유롭게 쉬다갑니당 사장님이 외국분이신데 한국어 너무 잘하시네용ㅋㅋ', 29, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미스터크레페'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '인스타그램 보고 왔는데 사장님이 웃겨요 외국분이시라 영어로 설명해주시는게 재밌습니다 크레페 시켰는데 양이 엄청 많고 짱달아요 추천추천 이태원바이브입니다 피아노 치면 공짜로 크레페 준다는데 저희는 피아노 못쳐서 내돈내산했습니다 그래도 만족하고 재밌는 시간 보냈어용 추천합니덩', 41, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미스터크레페'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '딸기크레페 먹어봤는데 존맛이에요! 크레페도 바삭하고 재료도 아낌없이 넣어주세요 1000원에 아이스크림 추가되는데 강추합니다!! 그리고 M사이즈로 주문했는데 양이 되게 많아서 배부르네요ㅋㅋㅋ 밥 안 먹고 갔는데도 이 정도니 L사이즈는 얼마나 큰건지 궁금해지는 부분,, 그리고 외국인 사장님이 엄청 친절하고 유쾌하세욯ㅎ  유쾌한 기분으로 맛있게 먹고 갑니다! + 그리고 가게 앞에 앵무새들 짱 귀여워요,,🥰', 78, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미스터크레페'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '오늘이 두 번째 방문이었는데 역시 오길 잘했다는 생각이 듭니다ㅎㅎ 양도 푸짐하고 재료도 많이 넣어주셔서 한끼 식사로 먹기 정말 좋습니다. 홍익대학교 정문과도 가깝고, 가격도 부담 없어서 재학생분들도 오기 좋을 것 같아요👍 사장님도 정말 친절하셔서 앞으로도 자주 방문하려고 합니다.', 92, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미스터크레페'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '딸기크레페 맛았고 저번에 먹었던 다른 크레페도 맛있었습니다!! 속재료에 따라 식사 대용으로도 간식으로도 먹을 수 있어서 좋아요!!', 34, 0, NULL, SYSTIMESTAMP);
