INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미스터크레페'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '진짜 엄청 맛있어요! 사장님들도 친절하시고 피아노와 기타도 칠 수 있어서 좋았어요! 앵무새들도 귀여웠어요 ㅋㅋ 다음에 또 오고싶어여☺️☺️', 31, 6, 'GOOD', SYSTIMESTAMP);
