INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미스터크레페'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '인스타에서 유명한 크레페 맛집!!! 천 원 추가하면 맛도리 아이스크림까지!!! 너무 맛있게 먹고갑니당!! 사장님 너무 친절하세요!! ㅎ', 64, 11, 'GOOD', SYSTIMESTAMP);
