INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '매장 인테리어가 너무 예쁘고 빵도 종류대로 다있고 음료도 커피도 없는게 없어요 다있어서 굳이 다른카페 안 찾고 여기가 친구들 약속잡을 때도 모두의 니즈 충족가능요!!! 테이크아웃하면 할인도 하고 마감세일도해서내가  동네주민이였음 매일 빵사감', 41, 10, 'GOOD', SYSTIMESTAMP);
