INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '날씨가 엄청 더운데 들어오자마자 엄청 시원해서 깜짝놀랐어요!^.^ 내부가 넓직하고 지하에도 자리가 있어서 좋아요! 빵 종류가 다양하고 맛있어보이는게 많구 제가 고른것도 맛있어요^~^ 바닐라라떼랑 천혜향 에이드 먹었는데 캐맛있습니다 ㅎㅎ', 31, 5, 'GOOD', SYSTIMESTAMP);
