INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '우연히 찾은 카페인데 넘 좋았어요 커피도 맛있고 베이글 샌드위치도 진짜 맛있었습니당 먹어본 잠봉뵈르 샌드위치 중 최고에요😚서비스로 주신 블루베리 크림치즈 스콘도 맛있었어욤! 내부도 넓고 조용해서 집중하기 좋아용 사장님이랑 직원분도 친절하시구 덕분에 잘 쉬다 갑니당👍🏻💛', 7, 7, 'GOOD', SYSTIMESTAMP);
