INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '더운 여름엔 수박주스만한게 없죠🍉 여기는 생과일을 써서 그런지 인공적인 시럽맛이 아니라 신선한 수박맛 그자체에욤🥰 에어콘도 시원하고 자리도 많고 빵종류가 많아서 선택장애가 올 것 같지만, 제 최애는 역시 소금빵입니당✨️❣️ 합정역 카페맛집으로 임명합니다!', 39, 5, 'GOOD', SYSTIMESTAMP);
