INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '오랜만에 합정 놀러왔다가 분좋카 같아서 들어왔어요! 인테리어도 잘되어있구, 통창에 비치는 햇살이 최고네요〰 부모님께서 커피입맛이 까다로우신 편인데 커피도 꼬소하니 맛있어요!! 또 올게요!!', 40, 3, 'GOOD', SYSTIMESTAMP);
