INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '지나가다가 처음으로 방문한 곳인데 소금빵 종류도 엄청 다양하고 전부 바삭하고 너무 맛있어요!! 특히 고구마 소금빵 너무 맛있습니다 ㅠㅠ 베이컨 에그 샌드위치도 너무 맛있고 팥빙수도 시원하고 맛있어요!!! 이런 곳을 알게 돼서 너무 좋아요!! 나중에 또 올게요🥰', 52, 16, 'GOOD', SYSTIMESTAMP);
