INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '그냥 지나가다가 예뻐서 들어온 카페 대 성공입니다! 🍀🍀일단 빵이 종류가 너무 많고 맛있어요!! 담에 합정 오실일 있으면 또 방문 할께욤~~🩷', 66, 13, 'GOOD', SYSTIMESTAMP);
