INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '친구들이랑 갈만한 카페를 찾다가 홀린듯 들어왔는데, 좋아하는 카페 폴리의 분점이라니 신기했어요. 메뉴가 같고 구성도 좋아서 디저트 과소비... 빙수도 너무 시원하고 맛있어요:)', 18, 1, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '합정역 가까운 곳에 있는 올라운드커피. 빵 종류 엄청 다양하고, 시식도 넉넉하게 내놨어요(ㅋㅋ). 크루아상 샌드위치, 아몬드 크루아상 멋었는데, 샌드위치 대존맛. 꼭 드셔보세요. 소금빵도 통통~하니 크기 커요. 커피도, 크림커피 맛있었어요. 1층 자리는 예쁘고 캠핑 컨셉 자리도 있고, 지하 자리는 조용합니다. 커피도, 코코넛 크림 라떼 맛있었어요. 또 먹고 싶네요', 2, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '빵종류가 엄청 많은데 가격이 합리적이예요~~ 인테리어도 분위기도 다 좋네요:) 수박쥬스 완전 시원달달하구 옥수수크림 소금빵도 색다른 맛이예요 ♡', 76, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '토요일 아침 합정에 일이 있어 방문하였는데, 유일하게 아침에 오픈한 곳이더라구요! 인테리어가 잘 꾸며져있고 넓어서 좋고, 손님들 몇몇 있었지만 꽤 조용했고 테이크아웃 하러 오시는 분들이 많았어요. 신선한 빵이 계속 나오고 다양한 호주식 커피, 음료 메뉴들이 있었어요. Everything Sandwitch 먹었는데 아침으로 딱이었습니다~ 다음엔 친구랑 브런치 먹으러 오고싶네요!', 46, 8, 'GOOD', SYSTIMESTAMP);
