INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '카페가 되게 분위기 있고 잔잔해서 가족들끼리 시원하게 음료 마시면서 대화할수 있었어요!! 음료도 전체적으로 다 맛있고 서비스로 소금빵 까지 주셨어요 ㅎㅎ 이 가게 엄청 대박날것같아요 빵도 종류가 여러가지여서 다 맛보고 즐길수도 있고 음료도 여러가지여서 진짜 좋았던것 같아요 사장님하고 직원 분들도 다 착하셔서 기분이 좋았어요 재방문할것같아요☺️☺️', 50, 3, 'GOOD', SYSTIMESTAMP);
