INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '합정 온 김에 느낌 좋은 카페 찾다가 여기까지 왔어요...🫶🏻 공간이 넓어서 대화 나누기도, 집중하기도 좋았어요!!! 깔끔하면서도 아늑한 느낌이라 자주 들를 것 같아요...👍🏻👍🏻 음료도 특색있게 맛있었고, 신메뉴 인절미소금빵도 너무 맛있었어요!! 너무 달지도 않고 물리지 않게 먹을 수 있는 맛있여서 좋았어요 다음에 오면 더운 여름이 가기 전에 인절미 빙수도 꼭 먹어보고 싶어요', 2, 2, 'GOOD', SYSTIMESTAMP);
