INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '아이들이 맛있다해서 또 사러왔습니당ㅎㅎㅎ 갓구운 소금빵은 냄새부터가 너무 기분 좋아요~~ 막나오자마자 사서 기분이 더 상큼합니당~', 16, 8, 'GOOD', SYSTIMESTAMP);
