INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '작업 할 게 있어서 방문했는데 빵도 너무 맛있구 커피도 정말정말 맛있어요ㅠ 원두종류도 많아서 원하는대로 고를 수 있는점이 너무 좋았습니당😍 정말 빵 맛집이라고 할 수 있을만큼 너어어무 맛나요..완전 추천..', 4, 3, 'GOOD', SYSTIMESTAMP);
