INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '이름부터 맛없을수가 없는 딸기쨈 피넛버터 초코 스콘이에요. 진짜 한 입 베어물면 미친듯한 버터 풍미에 커피까지 쭉 들어가는 맛. 진짜 너무 맛있어요. 이거 뿐만 아니라 뭐든 디자트가 다 너무 맛있어요. 커피는 말할 필요도  없이  맛있어요', 163, 100, 'GOOD', SYSTIMESTAMP);
