INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '고르곤졸라 소금빵이 정말 맛있어도 갈릭 소금빵도. 소금빵종류 다 괜찮아요. 커피원두도 고를수 있네요. 테이블도 다양하고 간격도 넓어 대화하기 좋아요.', 70, 15, 'GOOD', SYSTIMESTAMP);
