INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '일하는곳이 근처라 자주 이용하는 카페인데 항상 올때마다 맛있은 빵굽는 냄새가 인상적인 곳이에요!! 혼자 앉아있기도 좋고 미팅이나 다른 작업하기에도 좋아요 :) 요즘 카페에서 친절한 직원분들이 잘 없는데 다들 친절하게 응대해주셔서 올때마다 기분좋은 시간이라 다음에도 또 올거에요 다들 추천드려요', 19, 3, 'GOOD', SYSTIMESTAMP);
