INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '오후 7시 이후로는 마감세일을 하는 아주 좋은 베이커리 카페! 타 베이커리 카페 소금빵 보다 훨씬 큰 크기를 자랑하고 종류도 다양해서 만족합니다ㅎㅎ 합정 베이커리 카페 올라운드커피 적극 추천드립니다!', 59, 18, 'GOOD', SYSTIMESTAMP);
