INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '망원동에 산책 나와서 걷다가 합정동까지 와서 휴식하며 간식 보충합니다^^ 손님은 아주 많아도 내가 앉을 자리가 있어서 다행이에요:) 코코넛라떼 맛있어요오', 46, 0, 'GOOD', SYSTIMESTAMP);
