INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '저녁이라 디카페인 마셨는데 산미가 있는편이지만 고소하고 맛있네요! 소금빵도 속은 쫀득하고 맛있어용 ! 배불러서 다른 디저트는 못먹어봤지만 전부 직접 만드신다고 하니 믿고 먹어봐도 될거같아용 직원분들이 친철하셔서 기분좋게 커피한잔 마시고 갑니당 :)', 78, 17, 'GOOD', SYSTIMESTAMP);
