INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '여기 빵 완전 맛있어요. 음료도 맛있고 커피도 엄청 시원하고 양도 괜찮아요. 직원 분들도 친절하고 아래 지하까지 있는데, 엄청 넓고 쾌적해요. 빵 맛집이니까 빵을 꼭 사서 드세요. ❤️❤️❤️', 66, 15, 'GOOD', SYSTIMESTAMP);
