INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '빵을 엄청 좋아하지 않지만, 여기 빵은 정말 맛있어요. 그래서 빵 사먹으러 다시 갈 것 같아요! 그리고, 직원분들도 매우 친절하세요:)', 24, 4, 'GOOD', SYSTIMESTAMP);
