INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '지나가다가 처음보고 들렀던 곳인데 인테리어도 너무 멋지고 무엇보다 빵이 너무 맛있었어요 자몽허니블랙티도 맛있었고 사장님이 소금빵 서비스로도 주셔서 맛있게 먹었습니다! 더 잘 됐으면 좋겠다 싶었던 가게였습니다', 29, 4, 'GOOD', SYSTIMESTAMP);
