INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '합정동에 일보러 나왔다가 메세나폴리스 뒤에 공원 산책하고, 올라운드 커피에 입장했어요^^ 디저트 종류가 많고 호주식 커피가 아주 깊은 맛이 좋아요. 잘 먹을께요', 49, 10, 'GOOD', SYSTIMESTAMP);
