INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '소문난 소금빵 맛집이라 방문했어요. 사진에는 없는 메뉴들이 많이 있는데 옥수수크림소금빵이 모양도 예쁘고 맛도 좋아요. 잘먹었습니다!', 65, 12, 'GOOD', SYSTIMESTAMP);
