INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '처음 와봤는데 빵도 맛있고 커피도 너무 맛있어요. 빵이 너무 다양하고 맛있어서 고르는데 고민이 되고 분위기도 너무 좋습니다. 데이트나 친구들이랑 같이 오기에 너무나도 좋습니다😁😁😁', 43, 2, 'GOOD', SYSTIMESTAMP);
