INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '배민에서 빵맛집 찾다가 발견한곳인데 진짜 합정근처에서 제 1위빵집이고요 맨날 배달로 시키다가 직접와봤는데 사장님 너무 친절하셔서 더 놀랐고 매장도 너무 귀여워요 작진않지만 인테리어 깔끔하고 외관이 귀엽고 조용해서 그냥 댜화하러 오기 좋을 것 같아요 진짜 제발 여기서 돌체프레첼 먹어주세요 제가 프레첼에 환장한사람인데 진짜 여기만 생각나거든요 당연히 꼭 드시고 소금빵 종류 미쳤는데 크기도 큰데 맛있고 바삭해요 제발 드세뇨..', 35, 1, 'GOOD', SYSTIMESTAMP);
