INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '근처에서 갈만한 카페 찾다가 지인들이랑 함께 방문했습니다☺️ 1층에 사람이 꽉 차서 어쩌지,, 당황했는데 1층 말고도 지하에도 좌석이 있어서 바로 이용할 수 있었어요! 같이 주문한 빵들도 촉촉하니 맛있었습니다👍🏻 다음에 또 들를게요☺️💗', 79, 16, 'GOOD', SYSTIMESTAMP);
