INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '위에 승무원 학원 다니면성 몇 번 왔는디 카페 음료랑 베이커리들이 넘넘 마시써용~~~🤍🤍 + 아디다스 자주 입으시는 남직원분이 항상 넘 친절하고 잘생기셔서 그 분 보러 자주 오게 되는 거 같아요🩶 오늘은 꼭!! 인스타나 번호 물어보려고 들렸었는데ㅜㅜ 하필 매장도 마니… 바빠 보이구 손님들도 많았어서 오늘도 물어보지 못했네요🥲🥲 혼자 바보 같이 리뷰글에 혹시라도 봐주셨음 맘에 구구절절 끄적이는데… 평소 영어로 외국인 손님들과 소통하시던 모습들도 반함 포인트였는데 일본어까지 하시는 거 보고 두 번 반해ㅆㅅ서요🫣🫶🏻', 53, 14, NULL, SYSTIMESTAMP);
