INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '저는 건강을 위해서 파인애플 음료 시켰었는데 너무 맛있더라고요. 이것만 밖에 아까워서 소금빵도 하나 시켰는데 버터 향이 쫙 났어요.', 29, 1, 'GOOD', SYSTIMESTAMP);
