INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '아침에 우연히 들어갔는데 갓 구운 빵이 많아서 좋았어요! 커피도 넘 맛있구... 출근길에 빵이랑 커피 사서 회사 들어가면 딱일 듯해가지구 앞으로 자주 방문할 예정ㅎㅎ😋🍞🤍', 29, 0, 'GOOD', SYSTIMESTAMP);
