INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '항상 눈팅만 하다 드디어 들려봄…. 세상에나 프레첼, 소금빵, 베이글 세상 죠아하는 빵은 한데 모였…….. 프레첼이 살짝 너무 단맛이 돌지만 이런 텍스쳐 마포구에서 찾기 쉽지 않아서 만조꾸… 🥨🥨🥨 담에 또 올게유!! 담에는 갈릭과 페퍼로니 베이글 챱챱~도전쓰 🥯🥯🥯', 12, 3, 'GOOD', SYSTIMESTAMP);
