INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '감성있고 트랜디하면서 맛있는 소금빵과 분위기 좋은 노래 틀어주는 곳 찾으시면 오세요!! 너무 예쁘고 음료,빵,쿠키도 다 맛있고 사장님도 친절하세요! 존잘사장님…🥰', 3, 2, 'GOOD', SYSTIMESTAMP);
