INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '카페 어디가다 하면서 길 걷다가 그냥 들어왔어요! 혼자와서 커피 마시기도 편안 분위기고, 여러명 와서 수다떨 테이블도 있네용 :) 빵 종류도 많고고 테이블 간격 넓어서 조어용', 1, 5, 'GOOD', SYSTIMESTAMP);
