INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '추운 날에 방문한거라 매장이 추운건... 그럴 수 있다고 생각했어요! 근데 핫으로 주문했는데 시킨 커피랑 음료 둘다 미지근....해서 좀 의아했어요🥲 음료 따라서 마시라고 주신 컵이.... 커피물? 음료?가 이곳저곳.... 입닿는 부분에도 묻어있어서 쓰지 못했습니다... 맛은 나쁘지 않았지만 편안한 경험은 아니어서 아쉬웠습니다', 93, 25, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '디저트 종류가 엄청 많고, 맛있어 보이는 빵이 넘무 많아서 고민을 많이 했어요! 결국 왕창 쇼핑!! 음료도 진짜 맛있고 토마토쥬스 신선하고 블루베리 쥬스도 맛있네요! 길 걷다가 들어왔는데 자주 와야겠어요💜', 71, 18, 'GOOD', SYSTIMESTAMP);
