INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '합정역에서 5분 정도 거리에 있는 ‘올라운드커피‘ 사진으로 본 것처럼 매장분위기가 아늑하고 좋아요! 특히 빵 종류가 많고 소금빵도 정말 맛있어요ㅎ ㅎ 시식빵도 많아서 맛보고 고를 수 있어서 좋네요! 커피랑 음료도 맛있어요! 다음에도 들리고 싶은 카페입니다✨', 55, 14, 'GOOD', SYSTIMESTAMP);
