INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '연말 기념으로 나왔다가 발견한 가게! 인테리어가 이뻐보여 들어왔는데 너무 만족,, 일단 소금빵 종류가 되게 많고 사이즈가 커서 여러명이서 먹기 좋아요. 저희는 크림브륄레 먹었는데 이마 탁 치게 만드는 맛이었습니다..! 전체적으로 그리 달지도 짜지도 않아서 좋았습니다. 커피도 원두가 여러 종류였고, 저는 겨울한정메뉴인 피넛크림라떼를 주문했는데 크림이 진짜 맛도리입니다,, 살짝 쌉쌀한 커피에 달달하고 고소한 땅콩크림 조합이 굳굳. 분위기도 따뜻하고 아늑하니 얘기하기 좋은 장소인 것 같아요: )', 43, 0, 'GOOD', SYSTIMESTAMP);
