INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '남자친규가 여기 소금빵중독이라서 먹으러갔는데 소금빵 징짜짱짱맛있어용 빵도 크고 종류도 다양합니다 다양한소금빵이 있어서 맛별로 먹어보고 싶습니다~', 17, 6, 'GOOD', SYSTIMESTAMP);
