INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '근처에 지나가다가 소금빵을 판매하시길래 들어왔는데 인테리어도 너무 예쁘고 소금빵 종류도 다양해요! 시식도 해볼수 있어서 맛봤는데 너무 맛있어서 포장해갑니다🙂🙂🙂', 88, 18, 'GOOD', SYSTIMESTAMP);
