INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '맛있는 빵이 정말 많아요! 주말에 수업이있어서 격주 토요일마다 수업전에 꼭 들르는 곳입니다. 같이 수업듣는 분들에게도 추천했는데 와보시고 반하셔서 자주 가게됐다고 하셨어요!!! 빵 종류도 정말 많고 완전 강추추에요… ❤️ 커피도 맛있음!', 88, 17, 'GOOD', SYSTIMESTAMP);
