INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '분위기도 좋고 커피맛도 너무 좋아요 빵종류도 진짜 많네요 👍🏼👍🏼 소금빵 먹었는데 정말 맛있어요 👍🏼👍🏼👍🏼 다음엔 베이글 먹어야겠어요 ㅋㅋㅋ', 29, 3, 'GOOD', SYSTIMESTAMP);
