INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '크리스마스 기념으로 놀러나왔다가 인테리어가 너무 이뻐서 들어왔어요♡♡ 음료도 맛있고, 배불러서 먹진 못했지만 빵 종류도 많았어요!!!', 44, 7, 'GOOD', SYSTIMESTAMP);
