INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '항상 길가다가 여기 한번 와봐야겠다 생각했던곳인데 처음으로 방문하게 되었습니다! 가장 먼저는 베이커리가 너무 많아서 놀랐어요ㅋㅋ 매니저님이 엄청 친절하게 설명해주시고 커피도 맛나게 만들어주셔서 너무 맛있게 먹고 편하고 아늑한 분위기에서 즐겁게 쉬다갑니다:-) 빵도 커피도 최고예요!', 48, 5, 'GOOD', SYSTIMESTAMP);
