INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '지나가다 트리가 크고 예뻐 방문했는데 빵 종류 엄청 많고 매장도 넓어 편히 쉬다갑니다! 크림브릘레 소금빵 강추해요~ >_< 💕', 94, 19, 'GOOD', SYSTIMESTAMP);
