INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '👍 빵 맛집 아침 일찍부터 빵이 나와서 좋아요 빵 종류도 다양하고 맛있어요 가족들 사다 줬는데 맛있다고 해서 빵 다시 사러 왔습니다 👍', 16, 2, 'GOOD', SYSTIMESTAMP);
