INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '와.... 그냥 쨩 공들여진 카페 음료 커피 빵 공간 노래 다 만족 인테리어보는 맛 장난 아니에요 매장도 지하도 있어서 넓구 빵도 시식빵도있어서 먹어봤는데 다 맛나고 음료도 맛나고 합정 카페 핫플료 더 유명해지기전에 뚀 와야겠어요ㅠ', 43, 1, 'GOOD', SYSTIMESTAMP);
