INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '친구랑 합정 놀러와서 근처카페왔는데 베리크로와상 크림이 너무 맛있어요 ! 소금빵도 맛있고 사진을 미쳐 못찍어서 소금빵 꼬다리만 찍었네여 ㅎㅎ', 1, 3, 'GOOD', SYSTIMESTAMP);
