INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '음료가 너무 맛있고 매장이 넓어서 좋아요 입구에 커피 시음할수있도록 되어있는데 아메리카노 미리 마셔볼수도 있고 원두도 선택할수있어서 좋습니다 빵종류도 여러가지고 시식도 할수있어요~~ 친구들끼리 지하에 넓게 앉아서 맛있게 잘 먹었습니다', 5, 0, 'GOOD', SYSTIMESTAMP);
