INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '일단 분위기가 너무 좋아용 그리고 소금빵이 레전드로 겉바속촉입니다 그리고 초코스콘은 브라우니인줄 알았어요 너무 부드러워서 그냥 브라우니로 잘못 시킨줄알았어요 말차라떼도 어거지로 말차를 입에 쑤셔넣는 느낌이 아니라 은은해서 더 좋았습니다', 54, 12, 'GOOD', SYSTIMESTAMP);
