INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '아침에 간단하게 식사하기 좋아요😀 매장도 깔끔하고 일단 빵이 너무너무 맛있어요! 빵 종류도 많아서 자주 애용하게 될 것 같아요❤️', 9, 4, 'GOOD', SYSTIMESTAMP);
