INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '음료 가격대도 적당하고 가성비가 좋은 것 같아요! 소금빵도 맛나게 먹었습니다 합정역 인근이라 접근성이 좋아요. 화장실도 그렇고 전반적으로 매장이 깔끔한 것 같네요', 15, 4, 'GOOD', SYSTIMESTAMP);
