INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '진짜 장마여서 밖에 나가기 싫었는데 소금빵 생각이 아른거려 폭우 뚫고 다녀왔습니다 😋 역시 바질 소금빵이랑 쇼콜라 소금빵은 입호강 시키는데 적절했구요…쪽파 베이글 여자친구가 밥 먹고 먹었는데 안 뺏길려고 제 옆에서 허겁지겁 먹네요..맛있어서 나오는 폭행 아시죠..? 오늘 겁나 맞았네요 ㅎ 빵 하나 때문에 이렇게 행복하다니 제발 앞으로도 이 빵맛 유지해주세용 ㅠ 내일 출근길에 빵 사러 갑니다 🥹물론 퇴근길에도요 ㅎㅎ 빵순이 여자친구가 정말 좋아해서 기분 좋아요! 그리고 썸머블렌드 커피 먹었는데 처음먹어보는 커피맛이라 신기하고 맛있네요 ~! 다음번 갈때는 저 기억해주세요어어🥹', 35, 7, 'GOOD', SYSTIMESTAMP);
