INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '커피가 꽤 진한편!! 고소한 원두여도 많이 쌉쌀한듯요~ 피자빵은 진짜 맛 없던데 ㅜ. 치아바타, 뱅오쇼콜라는 맛있어여! 쵸코 맛있네요👍🏻 공들인 인테리어처럼 보이는데 아직은 뭔가 썰렁 허전하게 느껴졌어요~!! 테이블 간격 넓은 건 참 좋습니당', 52, 18, NULL, SYSTIMESTAMP);
