INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '새로 생긴 곳이라네요~ 매장이 지하도 있다는데,거긴 못가봤지만 1층매장이 이뻐서 대략 인정해요ㅎㅎ 커피도 생과일쥬스도 정성 가득한 맛이예요. 재방문 의사 백퍼예요!', 49, 1, 'GOOD', SYSTIMESTAMP);
