INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '커피폴리 사장님이 내셔서 와봐야지 하다가 들른 곳입니다! 커피 원두는 당연히 맛있고, 매장이 넓고 쾌적하고 테이블도 넓직하고 좋네요!!', 24, 10, 'GOOD', SYSTIMESTAMP);
