INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '오픈한 지 얼마 안돼서 그런지 되게 깔끔하고 분위기도 좋아요😆😆 빵 종류도 많고 커피도 맛있네요 ㅎㅎㅎ 원두도 세가지라 취향에 맞게 마실 수 있어요! 접근성도 좋아서 앞으로 자주 올 거 같아요🤩', 42, 10, 'GOOD', SYSTIMESTAMP);
