INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '햇살이 잘 드는 곳이에요 플랫화이트도 고소하고 커피 내려주는 직원분도 예쁘고 친절했습니다🤭 식물들이 많고 물이 흐르는 소리가 마음에 안정을 주는 것 같네요 매장 분위기도 밝고 쾌적해서 낮에 힐링하러 오기에 좋을 것 같아요!✨', 11, 2, 'GOOD', SYSTIMESTAMP);
