INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '얼마전에 지나다가 한번 방문해야겠다 생각해서 들렸어요 3가지 커피를 맛 볼 수 있고 입맛에 맞는 원두를 선택가능해요 베이커리는 지하에서 직접 굽는 듯 하고, 종류도 다양합니다 베이글, 소금빵류는 시식도 가능하니 먹어보고 선택해도 될 것 같아요', 14, 9, 'GOOD', SYSTIMESTAMP);
