INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올라운드커피'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '사장님도 친절하시고 빵도 진짜 근래 먹었던 것중에 제일 맛있었어요. 걷다가 들어간 곳이라 인테리어만 예쁜줄알았는데 커피도 맛있어서 또 재방문할 예정입니다.^^ 테라스같은 실내정원 자리는 진짜 멍때리기 좋아요. 잘 머물다 가요^^', 30, 8, 'GOOD', SYSTIMESTAMP);
