INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '여기는 방문할 때마다 계산대에 아무도 없어요 계산한다고 말하면 천~천히 와서 계산해주는데..ㅋㅋ 한번도 친절함이라고 느낀 적이 없어요 불청객 온 거마냥 손님 맞이해요 걍 주변 이거밖에 없어서 오는?', 43, 1, 'BAD', SYSTIMESTAMP);
