INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '동네 던킨도넛은 두바이 도넛이 없어서 못 먹어봣는데 홍대점 넉넉하게 잇어서 드디어 먹어봅니다! ㅎㅎ 우왕 카다이프 엄청많이 들어 잇고 맛잇네요!  >ㅂ< 소금우유도 맛잇고.. 근데 0.3초 순삭햇어요ㅠㅠㅜ 잇엇는데 없엇네요 힝구ㅠ', 18, 4, 'GOOD', SYSTIMESTAMP);
