INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '아이스 아메리카노 1잔 주문했는데, 15분 이상 대기했습니다. 알바생한테 물어보니 사과도 없이 누락됐다면서 30초만에 나왔습니다^^ 저희 음료 나오는 곳 앞에서 한참 기다렸는데 못 본 척 알바생들이 무시하다가 결국 나온 말이 누락이네요..^^', 42, 10, 'BAD', SYSTIMESTAMP);
