INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '카카오 후로스터드 2,000원, 소금초코도넛 2,500원 초코칩 🍪 월넛 쿠키 2,900원, 더블 초코칩 쿠키 2,900원,,', 37, 0, NULL, SYSTIMESTAMP);
