INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '글레이즈드가 이렇게 맛없는 거 처음이었어요. 한쪽면만 설탕 코딩 묻어있었고 그마저도 다른 지점보다 적었습니다~ 그래서 둘이 가서 저렇게 먹고 버렸어요 그리고 알바생분들 일하기 싫으신지 폰만 계~~속 보고 들어오던 나가던 인사 절대 안해요!', 3, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '늦은시간 들어가니 도넛이 텅텅 비었지만 좋아하는 도넛은 건졌어요. 디카페인 아메리카노를 같은 가격에 마실 수 있어 너무 좋고 직원분도 친절해서 좋아요~', 85, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '던킨은 커피도 맛나지만 역시 도넛. 스트로베리 필드의 잼꿀맛. 한입 베어물면 안에 가득한 베리액이 도넛과 잘 어울린다. 퍽퍽함이 없이 폭신한 맛을 가진 도넛을 찾는다면 스트로베리필드나 블루베리 필드', 68, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '매장 먹고갈려고 글레이즈와 커피 쿠폰사용하려는데 여사장이 유산지 한 장 주면서 꺼내오라길래 집게는 없냐물으니 집게 주려는것 같길래 제가 됐다하고 유산지로 글레이즈 집어왔음. 근데 쟁반도 준비해 주지않고 유산지로 글레이즈 구겨지게 집은 내 손이 민망해서 매장 이용 안하고 테이크아웃 해달라하고 나와버림. 매장에서 먹는게 싫은건지 기분망쳐서 나옴. 위생환경과 서비스에 대해 교육바람.', 60, 15, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '뱅쇼를 좋아하지만, 던킨의 화이트 뱅쇼는 진짜 배를 끓여서 마시는 맛이어서 마시지 못했지만, 베이글 칩이나 도넛들은 정말 맛있어요!', 44, 1, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '할인가 사용하기위해 갑자기 찾아 들렀네요. 시간이 늦어서 별거 없기도 했지만,  아는맛이기도 하고,넘나 달기도 하고, 홍대라서 그런가 매장도 도넛도 어수선했네요. 갠적으로 프리미엄매장 도넛이 먹고싶었답니다.', 100, 23, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '메뉴: 단짠옥수수꽈배기(2,900원), 멜팅콘 버터필드(2,700원), 아메리카노(3,700원) 여름 신메뉴 2종. 꽈배기는 슴슴했지만, 콘버터필드는 크림이 옥수수향 많이나서 좋았음다', 5, 0, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '아이랑 병원가는길에 들렸는데 정말 알바생땜에 어이가 없어 리뷰남김니다. 도넛이 4개정도 남아 포장해 갈려고 담아달라는것도 아니고 봉투만 달라고 했더니 무슨 기분나쁜 표정과 세상 짜증나고 귀찮은 행동으로 봉투를 줍니다. 어이가 없어서 마스크를 써도 행동에서 표정이 나온다고 어린 알바생 붙들고 말하기 싫어서 나오긴 했는데 홍대에는 외국인들도 많이 오는데 정말 우리나라 사람들이 다들 그런줄 알겠어요 그렇게 일하기 싫으면 무슨 알바를 한다고 진짜 민폐 그자체네요', 8, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '가끔 땡겨서 사먹는데 맛있어요 ㅎㅎ 근데 홍대입구역이라 바빠서 그런지 ,, 집게 위생 관리를 좀 더 신경써 주셨으면 좋겠어요ㅠ 그래도 친절하십니다!', 0, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '집에 가는 길~~ 던킨 123 이벤트를 위해 방문 홍대입구점 좁아서 복잡하지만 접근성이 좋아 가끔 오는 곳~~ 커피&글레이즈드 페어링(3,800원) 그리고 츄이~~~** 날이 갑자기 추워졌는데 따뜻한 커피한잔 좋아요!!', 89, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '새로나온 메뉴인 베리치즈듀얼필드 사봤는데 ㅠㅠ 둘이 따로 노네요 그냥 하나의 도넛츠 두개의 맛 정도. 치즈도 꾸덕한 맛는 아님', 14, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '지금 일하시는 여성분 정말 친절하고 손님을 기분좋게 해주는 훌륭한 분 같습니다. 성품 자체가 곧고 선하신 분 같습니다 친절한 응대 감사합니다. 이 곳의 유일한 단점은 천박한 음악레파토리...', 23, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '안녕하세요^^ 오늘도 SPC의 노예로서 던킨홍대에 와버린 홍대생이에옹...그래두 매번 다른 도넛을 맛보는 재미가 있네요. 포인트 적립하는 재미도 쏠쏠하고요. 요즘은 포인트 적립하는 재미로 사는 것 같아요.~~~^ㅁ^아예 소비를 안한다면 좋지만 저는 커피와 디저트 없이는 못 사는 사람인지라.... 이왕 소비 할 거면  포인트도 쌓아가면서, 할인받고 하면 좋잖아요. 그래서 오늘도 1커피1도넛 도장 찍습니당~~', 39, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '리뉴얼 대기 전에는 조금 더럽고 매장 관리도 잘 안 되는 그런 느낌이 들었었는데 지금은 전혀 달라졌엉. 사장이 바뀌었나 아니면 관리하는 매니저가 바뀌었나? 모르겠지만...... 너무 쾌적해서 좋아 ..나만 알고 싶은. 그런 장소라고 할 수 있지. 난 spc의 노예이기때문에 오기시러도 쿠폰쓰려고 억지로왔는데 생각보다 훨좋네. 내 혼공전용카페로 찜콩해야겠엉.', 71, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '크리스마스 겸 동료들이랑 나눠 먹으려고 이것저것 골라 박스 구성해서 샀는데 가성비가 좋아요! 요즘 빵 하나에 3-4천원이 기본인 시대에.. 부담없이 구매했네요.', 8, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '딸이 커피를 못먹는데 배려해주시고 여사장님 넘 친절하세요~ 퇴근 후 갔는데도 도넛 바로바로 채워주시네요   맛있게 잘먹었습니다  ^^', 3, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '너무 불친절함 그건 그렇다 치고 주문한 메뉴가 맹맛이라 보니 치즈도 빼먹어서 말하니 사과도없이 그냥 슬라이드 치즈 차가운거 껴서 다시 주네요 제값주고 왜 이런식으로 먹어야하는지 최소한의 일도 히기 싫으시면 쉬세요 남의 사업장 돈 받으면서 일하시지 마시고', 14, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '던키&쿠키런 콜라보 상품 예약구매 및 픽업 완료!! 아이패드 보관용으로 사용하려고 구매했네요! 수납공간이 많아서 좋은!! 도넛&커피 12,000원 구매 및 파우치 괜찮쥬? 홍대역 던킨에서 잘 받았습니다!!!!', 30, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '소금우유도넛 위에 글레이즈 있는데 조심해서 들어주시지 콱 집으셔서 그 부분 코팅 다 벗겨지고, 굳이굳이 한 비닐에 인절미츄이랑 같이 넣으려고 욱여넣으셔서 좀 그랬어요 도넛 다 구겨짐;;ㅎㅎ', 61, 17, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '갑자기 비가 내려서 도넛과 따뜻한 커피 마시며 잠깐 쉬어가요 :) 던킨 아메리카노는 제가 좋아하는 아메리카노 중 하나고 글레이즈드 기본 도넛이 제일 맛있어요. 그 다음으로는 카카오 허니딥을 좋아해요', 49, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '매장내 좌석이 있어 앉아서 커피랑 도넛을 먹고 가기엔 좋은 것 같습니다. 매장이 좀 노후가 된건지 관리가 덜 된건지 깔끔, 청결한 느낌은 없어서 그건 좀 아쉽네요ㅜㅜ 도넛은 괜찮았고 커피는 좀 밍숭해서 좀 아쉬웠습니다.', 127, 24, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '친절도 ★★★☆☆ 청결도 ★★★☆☆ 식도락 ★★★★★ 재방문 ★★★☆☆ 좋아하는 도넛과 맛있는 커피 저는 도넛과 커피는 던킨도너츠 도넛과 던킨도너츠 아메리카노가 제일 맛있습니다 원래는 플랫화이트만 먹는데 던킨은 아메리카노', 27, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '오 역대급 불친절 도넛 집으려는데 직원이 비키라고 포장배달 주문건 담으려는지 손님보다 직원이 먼저 집어야하는 곳 그래서 처음엔 새치기하는 일반 손님인줄? 계산하는데 얼굴은 이미 화가나있고 표정 띠껍 박스 툭툭 불친절 리뷰 많네 그사람인듯 문제있음', 117, 25, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '던킨도너츠는 맛있습니다 우연히 홍대점 갔다가 엄청 놀랐습니다 카운터 모니터 화면의 먼지와 포트(물주전자) 에 내려앉은 먼지 또 프런트쪽 한번도 닦지 앉은 듯한 먼지를 방치해놓고 음료가 제조되고 나왔습니다 바닥은 찍찍 끈적끈적해 닦지 않은 채로 있어 얼른 나오고 싶은 매장 상태였습니다. 깨끗한 매장이길!', 23, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '여성 직원분 손님이 도넛 고르는데 비켜세우고 배달포장 먼저 하시더라구요. 매장에서 이런 대우 받을거면 배달 시켜먹는게 낫겠다 라는 생각이 들었지만 날구지 하시나보다 생각했습니당ㅎㅎ', 48, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '궁금한게 있는데 여기는 왜 타 매장보다 음료값을 400원 더 받는건가요? 양이 타 매장보다 많은것도 아니고.. 가까운곳에 다른 던킨매장이 없어서 그냥 결제했지만 좀 그렇더라고요 컵회수보증금 같은건가요? 컵회수바코드도 없고 그런 안내조차 못 받았는데', 50, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '열시반에 문닫는데 왜 도넛은 여덟시 반부터 치우는 건지… 카운터에 뭉터기로 가격표도 다 치우고.. 고르면 담아준다니;; 가격도 모르고 골라야하네요 그리고 알바생 불친절. 포인트는 물어보지도 않고 결제완료. 물론 봉투도 물어보지도 않고 걍 가져가세요~ 하길래 봉투 돈낼테니까 달라고 했어요 과한 친절을 바란것도 아니지만 돈내고 사먹으면서 기분만 나쁘네요', 24, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '커피마시러 들어왔는데 매장 분위기며 청결하지 않은느낌이라 커피pet음료로 샀어요. 빵종류도 적고 매장도 깨끗하지않고 일하는 여자 알바분 2분도 알바느낌이 아니었어요.. 재방문은 없을듯 합니다.', 1, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '일요일 저녁 알바인지 사장님인지 여자 두 분 불친절하고 위생관념 없음 도너츠는 말라서 퍽퍽하고 뜨거운 아메리카노 시켰는데 미지근한 아메리카노 줌 주변에 카페 다 자리없어서 갔는데 왜 자리 많은지 알겠음', 86, 12, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '방금 매장에 들렸는데 마스크를 직원 두분다 안하고 계셔서 “영업 하시는거 맞죠?” 하고 물었더니 “네?ㅡㅡ“ 하고 인상 엄청 찌뿌리면서 맞다고 대놓고 무시하시더라구요 일단 음식을 파는 곳에서 마스크도 안하고 기분 나쁘게 응대하시는것부터 짜증났구요 kt에서 준 생일 쿠폰 쓰러간게 그렇게 기분이 나쁘신건지 모르겠는데 도넛 포장 해주신 봉투도 카운터에 탁 소리 나게 놔두시면서 주시는게 맞는건가요? 던킨에서는 교육을 어떻게 받고 이런 기본도 안되어있는 직원들을 고용한건지 의문이 듭니다 12/4 일요일 오전 9:30분 여직원 2분 이거 보시고 입장 바꿔서 생각해보세요', 89, 18, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '☹️☹️점원의 태도가 좋지 않아 다시는 이 집에 물건을 사러 가지 않을 것입니다.….. 점원이 말을 잘 못해요?손님에게 영수증을 건네줄 때는 한마디도 안 해요… 소비의 체험감이 정말 안 좋고, 이 집 도넛이 맛있다고 생각했는데 점원 때문에, 다시는 오지 않을 거고, 친구들도 못 오게 할 거예요！！', 32, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '얼음에 검은색 조각이 나와서 처음엔 그냥 말씀드리고 얼음 직접 빼고 마셨는데 마시는데 계속 얼음 속에 검은색 정체불명의 이물질이 나오네요 너무 더러워서 못마시겠어요 참고해주세요', 73, 12, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '전철입구 근처라 음료 마시러 들어갔는데 매장이 안락하거나 깔끔하게 정돈되진 않았어요. 의자 등받이끼리 부딪힐 정도로 좁고, 청소가 잘 안되어 의자 위 탁자 위 빵부스러기며 뭔가 끈적해 보인는 흔적까지.. 누굴 만나기엔 꽝인듯요. 그냥 태이크아웃용 매장인듯해 보입니다. 냉방은 빵빵해서 마시는 동안 시원했어요', 119, 26, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'MEETING');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), 'kt vip 초이스로 도넛하고 아메리카노 포인트로 결제 하려고 하는데 500원 추가요금 내라네요 전국매장에서 유일하게 추가요금 하라는 매장입니다 당연히 포인트로 이용하던 매장이 5200원 받고 500원 추가해서 5700원을 받다니 영수증에 소비자중심경영에서 웃음이 터졌습니다. 그리고 단발머리 여점원 응대가 잘못 교육을 받았음에 고객이 vip혜택을 이용에 추가요금을 따졌더니 왜 따지냐고 오히려 못배운티를 내더군요. 그리고 사람 따져가면서 응대합니다 도넛 데워 달라했더니 안되는 거라 하네요 전국매장에서 데워달라는 거 거부ㅋ 그리고 요금 이원화 매장이랍니다 가격을 맘대로 조절하는 곳이라는데 프랜차이즈 가맹점인데 요금 자율화라. 앞으로 잘먹고 잘사세요 500원 더 받으려다가 홍익대 앞 매장처럼 없어질 것 같네요', 6, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '바바리안필드 먹고싶어서 갔는데 없어서 아쉽지만 다른거 먹었습니다. 그런데 나올때 보니까 카운터에 다 꺼내져 있는 빵들 사이에 바바리안필드가 있어서 매우 아쉬웠습니다', 49, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '알바분이 처음인지 타지점대비 포장지(?)도 너무 아끼시고.. (매뉴얼대로인지...) 결제하는데 오래걸리고 서비스도 그저그랬어요', 64, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '지금까지 가봤던 던킨중에 최악입니다,, 음료 두잔과 도넛 4개를 주문했습니다 음료와 함께 도넛을 함께주신다해서 기다렸는데 음료만 주셔서 뭐지 싶었습니다 빵을 함께 주문했는데 빵을 못받았다하니 어리둥절해 하시더군요 그래서 반복해 대략 세번정도 설명 드린 것 같습니다 그제서야 “아..” 하시면서 주시더라고요 실수는 누구나 할 수 있는거니 괜찮습니다만 아..하고 죄송하다는 말도 없이 그냥 주시는데 이게 맞는건가요??…기분이 매우 나쁘네요.. 아이스티에 샷추가해서 먹었는데 아이스티 음료 자체가 너무 밍밍했습니다,,맛도 서비스도 너무 별로예요 리뷰 자체도 잘 안는데 이런 리뷰는 정말 처음입니다 리뷰 적을라고 버려달라했던 영수증까지 다시 받아서 적었습니다..', 15, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '들어갈때와 나갈때 인사 없고 계산할때도 하나더 찍어주셨는데 사과도 없네요! !! 기분 풀리려고 달달한거 사 먹었는데 먹기전보다 기분 더 나빠졌네요 ㅎㅎ 돈 아까워요', 404, 76, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '베이글을 굽고 크림치즈를 발라주셔야하는데 크림치즈를 바르고 구워서 크림치즈가 녹아 흐르고 맛이 눅눅해짐.... 그래도 친절하고 깨끗하긴 함', 15, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '스마트주문 시 10분 예상시간이였고 20분 내내 매장에서 기다리다 직원에게 말하니 이미 준비가 되어있더라구요. 따로 전화가 가질 않는다고.. 근데 전화오네요...', 6, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '종류별로 다 먹어볼 수 있어서 너무 좋았고, 특히 인절미 도너츠 넘나 제 취향 저격이였습니다👏🏻👏🏻👏🏻 다만, 코로나 2단계로 격상해서 못앉아서 슬펐어염.. ㅠ 다음에 또 갈께요!', 18, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '일단 매장들어서자마자 직원분들이 퉁명스럽게 맞아주시고 바닥은 얼마나 안닦은건지 너무 끈적거려서 걸어다니기 불편했어요 도넛넣으시는 진열장문을 너무 세게 열고 닫아서 제가 모 잘못한지 알았습니다 기계적고 퉁명스러운 말투덕에 아침부터 그닥 기분이 좋지않네요 분명 사러갈때만해도 기분이 좋았는데 근처 스타벅스나 베스킨라빈스 파리바게트 들어가면 항상 기분좋게 인사해주시는데 괜히 사러갔나 하는 생각이 들정도였어요 무슨 안좋은일이 있으셨던건지 두분이 사이가 안좋으신건지 아님 오늘만 그러신건지 모르겠지만 오랜만에 방문했는데 좀 그랬네요', 13, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '던킨 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '점장이 4인테이블 하나 잡고 일어나지도 않고 마스크 벗고 대화하고 마스크 벗고 음료 제조중인 바에 마스크 쓰지않고 들어가서 말을하네요 최악', 15, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '언젠가는 꼭 가보고 싶던 곳을 찾아왔어요. 아늑한 공간이지만 많은 사람들이 찾아오는 이유를 알것 같아요. 커피향이 은은하게 퍼져 나가는 이곳에서 누구든 마음 편히 시간을 보낼수 있게 해주셔서 휴일을 보람있게 보내고 왔어요 :) 커피도 역시 맛있게 마시고 왔어요. 멀지 않은 시간에 또 방문하겠습니다!', 52, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '[마포구 보안관 출동 일지] 사건 번호: 2025-09-13 / Case #D-010 사건 개요: 도덕적인 사람이 되고 싶은 커피 현장 기록: 자연스러움이 가장 큰 컨셉, 모든 요소가 개성 넘치는데 결코 과하지 않음, 커피 맛도 그러함 증거물: 푸릇프룻 애플트리(펀치라인에 걸맞는 맛과 품) 특이 사항: 쿠폰에 도장도 허투루 찍어주지 않음 수사 결과: 컨셉을 유지하는 힘은 맛의 일관성', 50, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '벌써 세번째 방문이네요 평일 더운 날인데 좌석이 가득 찼었어요. 에티오피아 타미루 무라고 워시드를 아메리카노로 마셔보았네요. 가격은 조금 있지만 분위기가 특별하고 에어컨 바람이 시원하네요', 48, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '오랜만에 방문한 도규는 내부 좌석 위치가 변경되어있네요~ 전보다 넓어보이는 마법이! 엘피 음악소리 공간 커피 모두 너무 좋았습니다🖤', 83, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '★4.3 요즘은 작은 규모의 카페들이 참 핫하다. 앉는 자리가 몇 없지만 알짜로 운영하는 것 같고 아담한 분위기가 소통의 바이브를 준다. 대형 카페나 기업화된 카페들에서 찾을 수 없는 정서다. 테이블이 없어 노트북 부대가 없는 것이 마음에 든다. 나만의 규범이지만 작업물을 내려놓고 쉬러 가는 분위기도 어딘가에는 있어야 하지 않겠나. 짧게나마 LP 음악을 들으며 커피 한잔 즐기니 하루의 흥이 돋는다. 원두 종류가 많지 않아 선택의 폭이 아쉽다. 특색 있는 원두로 어필하면 좋을 것 같다. Doduk은 도둑으로도 읽히니 그건 그것대로 마음에 든다.', 15, 8, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '커피가 많이 맛있고 . 가게 분위기가 느좋 홍대 1티어 카페로 내성적인 성격도  외향적으로 바꿔주는 마법의 공간. 사장님이 거물임. 상수역 근처 대장 극동방송 대표도 단골인 카페. 쟈철 상수역 이름 뒤에 괄호 열고 (도덕과규범)역입니다 하고 안내방송을 해야 됨', 87, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '커피가 맛있다고 해서 방문했는데, 원두 너무 맛있네요! LP음악이랑 특유의 분위기도 너무 좋았어요. 직원분들도 친절하시고, 커피맛과 분위기도 좋아서 자주 방문하고 싶어요!', 42, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '커피가 맛있다고하여 처음 방문해보았는데 내일의 커피 너무 맛있었습니다.. 엘피로 틀어주시는 음악도 좋고 자주 갈 것 같네요 ㅎㅎ', 83, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '개인적으로 너무 마음에 드는 사람 냄새(?) 나는 카페입니다. 가게 인테리어 부터 일하시는 바리스타 분들도 친절하게 응대해 주시고 스몰토크도 하고 내일의 커피 마시고 너무 마음에 들어서 필터커피까지 한잔 하고 왔네요. 또 들릴게요. 번창하세요~^^', 2, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '리뷰가 좋은 이유가 다 있네요!! 커피맛은 물론.. 사장님? 직원분들이 너무나도 친절하시고 말도 재밌게 걸어주심 편안한 분위기.. 요 근처 살았다면 무조건 단골했을듯 ㅠㅠ 커피는 원두 자체가 산미가 쎄고 꽃향 많이 나서 커피매니아들은 무조건 인정할 맛 아주 아주 즐겁고 행복한 카페였슴니다..💓', 22, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '도덕과 규범에 스며든 목재의 고요함과 레코드 음악의 잔잔한 선율, 그 사이로 퍼지는 커피 향이 참 인상 깊었습니다. 에스프레소부터 필터까지, 한 잔 한 잔에서 흘러나온 향미는 음악과 어우러져 귀와 코를 적시는 경험이었고, 르완다와 에티오피아 커피는 마치 초콜릿이 흐르는 개울과 들꽃 가득한 들판에 선 듯한 여운을 남겼습니다. 따뜻한 시간, 감사합니다.', 12, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '지금의 장소로 이전하기 전부터 방문해야지했는데 이제야 방문했네요. 아늑한 공간도 좋은데 대표님도 참 친절하시네요:) 배치브루 커피 포장해는데 텀블러에 잘 담아주시고 맛도 제 취향입니다. 도 도전하세요 규 규석에 있는 카페, 도덕과 규범', 6, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '커피가 유명한 “도덕과 규범” 요즘 느낌 좋은 카페로 자주 올라오는데 커피만 전문적으로 하는 매장이고 인테리어 특유의 빈티지한 느낌과 lp에서 흘러 나오는 재즈 + 고소한 커피 냄새로 가득한 공간이 참 따듯하다고 느껴졌다,, 커피는 내일의 커피를 주문했는데 매일 원두가 다르고 전 날에 미리 생산한 커피를 다음 날 판매하는 시스템이라고 하셨다,, 오늘은 다크하고 묵직한 맛의 원두라고 설명해주셨고 커피를 마시고 있는데 날씨가 따뜻해서 그런지 사장님께서 슬레이트..?를 올려서 개방감이 더해져서 좋았고 커피도 너무 맛있었다👏', 90, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '맛있는 드립커피가 마시고 싶어서 찾아간 곳 ☕️🤍 직접 자리 내어주시는 사장님 덕분에 기분이 좋았어요! 따뜻하고 아늑한 내부가 인상 깊었습니다☺️', 1, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '홍대 인근 카페 중 제일 커피 맛있는 곳이에요! 매장 규모는 작지만 직접 로스팅도 하고 항상 테이크아웃 손님으로 붐비더라고요. 직원분들도 매번 친절하시고 커피에 진심이 느껴지네요😊', 44, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '이날은 배치브루랑 과테말라 아이스아메리카노(빨대 꽂아있는 사진) 총 2잔 마시고 왔는데요..😉 저는 도규 배치브루(내일의커피)가 너무 맛있고 깔끔하고 제스타일이에요…☕️🤎 가격도 착해..', 22, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '추천을 통해 방문을 했습니다. 추천이라는 단어는 저에게 늘 배신은 하지 않는듯 합니다. 갈 때마다 늘 짜릿하고 새로운 걸 배우는 기분입니다. 아주 작은 카페이지만, 있을 건 다 있는? Lp,cd플레이어를 좋아하는데 가게에 있는게 제 취향이더군요 적립 카드 속 보이는 그림들이 직원분들의 모습이지만 각자의 역할에 모습을 적립카드로 만드신게 인상적이었고요 커피 한 잔 속에 담긴 맛은 기분을 좋게 만들고, 여기를 온게 하나도 후회가 안됩니다. 추울 때 왔지만 따듯할 때 오면 얼마나 아름다울지 기대가 됩니다. 앞으로도 시간 나면 자주 오도록 하겠습니다. 🍀💗✨', 4, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '추천은 많이 받았는데 처음와봤어요 좌석이 많지는 않아요. 바에 3~4명 의자에 2~3명 야외 벤치에 3명까지 앉을 수 있어요 배치브루 에스프레소메뉴 필터커피까지 다양하게 있어요 저는 필터커피를 좋아해서 8,500원으로 비싸지만 필터 시켜봤어요. 몰케 내추럴 폼이 좋았네요. ㅎㅎ 음악도 좋고 특별한 감성이 있는 공간이에요. 메뉴판에 그림 그려진게 참 예쁘더라구요 대부분은 일행과 같이 오시긴 했어요. 사진 찍는 분도 많았어요', 42, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
