INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '서울여행 4박5일동안 드립커피집 투어를 했습니다. 7곳 넘게 돌아다니면서 마지막으로 갔던 카페 집이었는데 공간, 음악, 커피, 사장님 모두 다 맘에 들었던 카페였습니다. 차분한 재즈음악과 눈앞에서 내려지는 커피 단골손님들과의 대화 정말 편안한 공간이었습니다!! 집 앞에 있다면 매일 가고 싶은 카페 👍🏻', 23, 9, 'GOOD', SYSTIMESTAMP);
