INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '상수동 사랑방 예술가들이 많이 오는 카페 사장님도 직원분들도 다들 유명함 그냥 가만히 앉아있어도 재밌는 카페. 커피 당연히 맛남', 86, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '드립커피맛집이에요! 조명조명한 아늑한 매장 분위기도 너무 좋고 친절하고 유머러스한 사장님도 계십니다!:) LP로 음악 틀어주시는 감성도 너무 좋아요~ 커피 잘 마시고 갑니다~', 86, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '커피 맛, 분위기, 인테리어, 음악 뭐 하나 빠지는 것이 없는 최고의 개인카페입니다! 홍대 후문 바로 근처에 위치하여 상수역에서 칼하트 구경하고 오면 좋습니다. 지인들이 모두 최애카페라고 하여 방문했는데, 정말 영화 속 한 장면에 들어갔다 나온 기분이네요. 좌석은 매우 적어서 다닥다닥 앉아야 하지만, 그마저도 답답하지 않고 모두와 동질감을 느끼게 해줍니다. 사장님은 매우 친절하시며 직접 원두 설명을 해주시고, 눈 앞에서 드립 커피를 내리는 과정을 보여주십니다. 배치 커피도 저렴하다고 해서 맛이 떨어지지 않고 오히려 산미를 가볍게 느낄 수 있어 가성비가 정말 좋았습니다. 사실 내성적인 편이라 들어가기가 선뜻 망설여졌지만, 누구에게나 편안하고 아늑하네요. 사실은 저만 알고 싶은 카페입니다.', 59, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '이곳은 치앙마이..?! 느낌이 나는 로컬카페 전부터 궁금했던곳인데 기대 이상으로 좋았어요 내일의커피 3300원에 이런 맛있는 커피를??! 커피도 너무 맛있고 분위기도 차분하고.. 취향에 너무 잘 맞는 곳 이였습니다. 날것의 느낌을 좋아하는분이시라면 분명 좋아하실거에요! 주차는 극동방송국에 하고 갔습니다😉', 89, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '배치브루 넘 맛있어서 드립 마시러 가봤어요! 첫 드립이라 따뜻하게 마셨는데 너무무무 맛있네요 일부러 맘먹고 찾아가야 하는 카페라 배치브루도 한잔 더 마시고 오고싶었지만 상황이 안되어 아쉬웠습니다 ㅜㅜ 두돌 아기랑 같이갔는데 좁은 공간이지만 카인들리한 분위기로 맞이해주셔서 편안히 마시고 왔습니다. 다음엔 일반 아메리카노 마셔보러 또 가볼래요👍🏻👍🏻', 37, 4, 'GOOD', SYSTIMESTAMP);
