INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '- 작은 공간안에 감성과 분위기 가득한 커피 맛집. - 커피 맛은 물론 음악도 너무 좋아요! - 커피에 진심인 사장님의 인스타도 구경해보세요👍🏻 @doduk_kyubum *주차는 인근 주차장 이용 가능 : 홍익대 예문관, 극동방송 등', 8, 8, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '맛있고 친절하다는 소식을 오래전부터 듣고 있어서 멀리서 달려왔습니다! 역시나 사장님은 당연히 맛있고 커피는 친절합니다. 매장에 있으면서 바람소리와 음악소리를 함께 들으니 자체적으로 힐링이 되는 좋은 순간이었습니다!🫡', 45, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '지난번 커피를 마셔보고 맛있어서 또 다시 방문했어요 이렇게 단골이 되어가는게 아닐까 싶네요😀 이번엔 애티오피아 만도예 산미있는 원두로 마셔봤는데 역시나 너무 맛있는걸요ㅜㅜ 직원분도 너무 친절하고 커피도 존맛이라 기분 좋아지고 나가는 찐찐찐 카페입니다', 15, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '도덕과 규범 개성 넘치는 가게 분위기를 즐기느라 바빴다 커피 맛은 역시 대만족!! 디카페인라떼를 마셨는데 정말.. 쫀득하고 꼬소하고 바리스타님들과 하는 소소한 이야기들은 덤^^ 다음에도 상수 근처 오면, 이 아니고 도규만을 위해 상수에 올 것 같다', 46, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '간판이 없지만 웨이팅이 있는 진정한 커피 맛집👍 메뉴는 오직 커피 밖에 없어요! 원두 종류는 세가지로 고소한걸 좋아한다면 과테말라, 산미있는걸 좋아한다면 케냐 혹은 에티오피아를 추천해주셔서 과테말라 한잔, 케냐 한잔 시켜봤어요! 개인적으로 산미있는 커피를 좋아하는데 드립커피가 아닌데도 이렇게 좋은 산미랑 바디감을 가진 커피는 정말 오랜만에 마셔보는거같아요🙂 매장은 작지만 엄청난 크기에 로스터기가 있는거 보면 주인분께서 얼마나 커피에 진심이신지 느껴지는거같아요! 음악도 좋고 분위기도 좋아요 자주 올게요!🎵', 2, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '골목길에 자리한 자그마한 아지트같은 카페. 레트로한 감성의 소품과 철물들이 독특한 분위기를 자아내는 곳으로 항상 사람들로 가득 차는 카페였어요 커피맛집으로 유명하니 취향에 맞는 커피를 주문하면 될 듯👍', 25, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '예전 홍대카페는 작지만 각자의 개성이 강한 카페들이 많았었는데, 어느덧 기업형 카페들이 즐비한 가운데 오랜만에 예전 홍대카페 감성의 카페가 생겼습니다.', 58, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '숨겨진 커피 맛집이라는 소개로 찾아갔어요. 가격은 아메리카노라도 원두에 따라 가격이 다릅니다. 다들 커피 맛있다고 하셨어요. 저는 블랙 라떼 먹었는데, 조금 쓴편 이었습니다.', 63, 11, NULL, SYSTIMESTAMP);
