INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '사장님께서 직접 로스팅한 원두로 커피를 내어주시는데 아주 맛있게 먹었습니다ㅎㅎ 손님분들께 친절히 대화도 걸어주셔서 너무 기분 좋은 서울 나들이를 하고 들어왔어요.. 또 갈게요!!', 47, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도덕과 규범'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '너무 실망스러워서 말이 안 나옵니다,,, 스팀부터 불안했는데 제가 알던 곳이 맞는지 ㅠㅠ 스팀 조금 하다가 망했는지 도중에 스팀봉에서 피처뺐다가 그 우유 다시 스팀한 음료가 제 음료일줄은,,, 😂 앞으로 재방문은 없습니다 ㅠㅠ 맛없는 커피는 하루 기분을 망칩니다 ㅠㅠㅠ', 81, 15, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '미피 비치타올 살겸 음료랑 토스트랑 빙수 먹으러 갔어요~! 미피로 예쁘게 잘 꾸며져 있어서 좋았네요..! 다만 픽업이랑 반납이 좀 불편한 듯 ㅜㅜ 2층인데도 천장이 높아서 계단이 의외로 많네요.. 혹시나 쏟을까봐 조심조심…..', 43, 9, NULL, SYSTIMESTAMP);
