INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '[Declaration of Challenge] Expanding to the Global Market Yoon’s Care is stepping into the global market. We will begin with Southeast Asia. From small home care services, we have grown into a business, received overwhelming support from our customers, and became a corporation. Now, we are ready to go global. We are ready to step into a bigger world.', 62, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '할리스 연트럴파크점 앞에 나무들이 보여서 푸릇푸릇한 뷰도 좋고 매장도 넓고 분위기도 너무 좋아요 팥빙수도 너무 맛있어요 연남오면 또 오려구요 🫘🍨🥄🌿😳❤️👍🏻', 48, 6, 'GOOD', SYSTIMESTAMP);
