INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '연남동 카페중 최고의 뷰라고 생각! 인종도 성별도 나이도 구분없는 핫플중의 핫플이기 때문에 연남동 사는 사람은 오픈런을 노립니다. 책읽고 시간보내기 좋은 연트럴파크뷰 할리스 굳굳😌🧘🏻🎧', 65, 13, 'GOOD', SYSTIMESTAMP);
