INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '헬로우 인디아에서 저녁먹고 김종호 목사님과 미팅 달라진 뉴스킨 보상구조 듣고 소비자도 보너스 빋는 구조 이해 기다려~세상아 내가 왕이로다~ 인스타 mini.5109_freedom', 17, 1, 'GOOD', SYSTIMESTAMP);
