INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '리뉴얼된 할리스. - 3층까지 있으며 화장실은 외부에 있다. - 다양한 좌석과 넓은 공간덕에 공부하는 사람들이 많았다. - 환기가 좀 되면 좋을듯', 29, 9, NULL, SYSTIMESTAMP);
