INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '일요일 오후 4시 정도에 갔는데 1층 2층 3층 만석이었고 3층에 겨우 한자리 잡았다가 커피 들고 올라오다가 2층 창가 좋은자리로 운 좋게 앉게 되었습니다. 직원들도 친절하고 커피도 맛있어요. 여름에는 아아가 맛있고 겨울엔 뜨아가 맛있어요. 커피 맛집 ^^ 휘낭시에도 맛있고 마들렌도 맛있어요. 자주는 아니지만 한달에 한번 정도는 오고 있습니다. 통창가에 앉으면 밖이 뻥 뚫려 있어서 기분도 좋고, 분위기도 좋고, 의자도 크고 폭신하니 아주 대만족입니다요 ^^ 그런데 테이블이 겁나 삐걱거리면서 흔들려요. 팔꿈치라도 잘못 기대면 머피 쏟을 수도 있으니 조심하시구요, 아래에 휴지 깔았는데도 테이블 자체가 흔들리게 만들어졌는지 어쩐지... 고정도 잘 안되더라구요. 그거 빼고는 좋아요.', 41, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '아메리카 가격이 4,500원에서 4,700원으로 인상 되었네요 ^^ 3시 30분에 갔는데 자리가 2층 3층 꽉꽉 다 차 있고, 1층에 딱 한자리 남아있어서 겨우 착석 했습니다. 커피는 여전히 맛있고, 직원분 참 예쁘시고 친절하시네요. 저녁 6시 정도 되니까 손님들이 쏙쏙 빠져서 빈자리 많아지더라구요 ~ 할리스 연남점은 정말 부자될것 같아요 ㅋㅋ 좌석도 편하고, 통창 뷰도 멋있고, 여러모로 다시 오고 싶은 커피집 입니당~ 커피 잘 마셨습니다. 휘낭시에도 너무 맛있었어요.', 58, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '음 조아요 3층까지 있어서 넓구요 커피 양을 잘못 시켜서 어마어마한 양의 라떼가 나왔는데 아주 오래 마실 수 있었어요 적당한 속도로 나오는 편이에요 먼저 자리 잡고 주문하시길 추천드려요 👍 1, 2층 모두 키오스크있고 1층에서 음료 픽업해가면 돼유 ☺️', 18, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '지나다니면서 한번 가봐야지 하다 드디어~ 자정까지 영업하고 통유리창이 있어 뷰가 좋아요. 혼자 공부나 작업하기 좋게 해 놨는데 유일한 단점은 화장실이 깔끔하지 않아요.', 31, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '밤에 갔는데, 손님이 저희 옷에 음료를 다 튀겼는데 수습도 안하는 것에 1차로 짜증이났고, 음료가 잘못나왔는데 자꾸 진상취급을 해서 2차로 짜증이 났습니다. 다신 안갈거 같아요!', 42, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '무더위 여름 주말 다른 개인카페 다 사람 꽉차서 겨우 온 곳. 카페가 3층으로 되어있어서 좌석이 넓어요. 여기까지 못왔으면 열사병 걸렸을듯 어우 시원해라', 45, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '기프티콘을 못 썼는데 당일 이슈가 있었더라고요. 본사지침이래나? 그런거였으면 키오스크에 안내문을 붙여놨다면 더 좋았을거같아요. 그리고 케이크도 주문하고 좀 기다렸다가 제품 받으려고 보니 냉동이라 2시간 후에 해동되면 드실 수 있다며,,, 그걸 나중에 알려주시더라고요. 그것도 좀 당황했습니다,,,,, 이런 부분들은 사전에 주문전에 고객이 알 수 있게 미리 안내를 해주셨음 좋겠네요.', 44, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '자주 오는데 리뷰는 처음 남기네요. 3층 규모고 늦게까지 여는 곳이 많이 없는데 여긴 늦게까지 해서 항상 잘 이용하고 있습니다. 감사합니다', 31, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '연남 할리스 지나다니기만 하다가 왔는데 3층까지 있고 연남동거리를 볼수 있어서 좋네요. 새로운메뉴 유자블로썸오로라도 특이하고 맛나요.', 44, 8, 'GOOD', SYSTIMESTAMP);
