INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '친구모임. 식사후 너무 더워서 생각했던 곳까지 못가고 중간에 들어간 할리스. 근데 가성비 좋은 팥빙수 아이스크림 추가해서 넘 맛나게 먹음. 여름가기전에 또 들를 계획!!', 41, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '할리스가 몇층이나 있고 매장이 되게 넓어서 자리가 많이 있었어요. 자리가 편해서 노트북하기 좋았고 화장실도 따로 있어서 이용하기 편했어요. 화장실은 깔끔해서 좋았어요! 과제하거나 수다떨기 좋은 카페같아요💫', 6, 8, 'GOOD', SYSTIMESTAMP);
