INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '연트럴파크에 생긴지 오래되지 않아서 그런지 매장도 깔끔하고 관리가 잘되어 좋아요. 자리도 트인곳에서 잘보이고 밖을 보며 멍때리기 좋습니다. 뷰맛집도 되고 ㅎㅎㅎ 펫프랜들리 매장이라 일정 구역에선 반려견과 함께 취식가능합니다 ㅎ', 43, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '딸이랑 첫방문했어요. 손님이 많고 정신없이 보였어요^^;; 그래도 애가 버블티 메뉴가 먹고 싶다해서 주문했어요. 주문하고 보니 3층 모두 만석이라 앉을 곳이 없어 급히 주문을 테이크아웃으로 변경해 달라 부탁드렸어요. 아직 제 번호가 호출되기 전이어서요. 근데 검은 마스크 쓰신 분이 말로는 바꿔주신다고 하면서 한숨 한번 쉬고 퉁명스럽게 대답해서 마상입었네요. 그 자리서 머라 하고 싶었지만 아이도 있고 다른 손님들도 계서 영업방해 하고 싶지 않아 참고 나와서 이렇게 여기다 글 남깁니다. 아마 제 앞에도 그런 손님들 조금 보였는데 바쁘고 그런건 이해 하는데 그래도 손님 대하는 태도를 좀 고쳐주심 좋겠네요. 저도 앉을 수 있을 줄 알고 마시고 가려다 그런거니까요. 그 직원 땜에 여기 다시 가고 싶지 않네요ㅠㅠ', 19, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '매장도 넓고 테이블 수도 많아서 좋았어요. 건물이 햇볕 잘 드는 곳에 있어서 그런지 사진이 정말 잘나와요👍 커피도 서비스도 아주 만족이었습니다👏', 20, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '경의선 산책로 걷고 날씨도 좋고 할리스에서 시원한 음료로 땀을 식혔어요. 홍대입구역 주변 인파가 많아서 놀랐어요. 젊은이들의 성지~', 17, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '연남동 돌아다니다가 잠시 쉬려고 방문했어요. 3층인가로 엄청 크고 자리도 편안해서 좋아요. 핑크파인 캐모마일티 먹었는데 진짜 맛있어요. 짱짱 캐모마일 사이에 파인애플이 솔솔나서 달달하고 맛있어요.그날 에어컨이 좀 추웠  매장 향수가 좀 취향이 아니였긴 한데 (다소쌘듯) 스터디하거나 쉬다가기 좋았어요', 10, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '연트럴파크 한가운데에 커다란 성 처럼 있는 할리스~ 커서 좌석이 많아으니까 넘 좋으네요~ 스무디 먹었는데 진하고 새콤달콤 넘 맛있네요~^^', 31, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '케익(딸기생크림,티라미슈)맛있어요. 포크를 다 써서 없다며 케잌 먹으라고 스푼을 주는건 뷁😡 학생들 노트북 켜놓고 죽치고 있어 자리 잡기 힘든거 뷁😡 손님들 문열고 들어오면 엄청 추운 1층 자리도 뷁😡', 81, 18, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '연트럴파크 할리스 엄청 크네요 ㅎ 매장 찍어봤어요 ㅎ 손님도 많지만 좌석도 넓어서 아주 좋아요! 이지쉐이크 쿠폰 있어서 구입했는데 와.. 진짜 깜놀. 초코맛이랑 그레인인데.. 둘다 맛있고 저는 그레인이 고소하고 거 맛있더라고요 ㅎ 할리스.. 진짜 잘 만드네요 ㅎ 아주 맘에 들어요! 진짜 여기저기 할리스 많이 가는데, 박서준과 황정음인가 그 드라마 이후로 계속 쭉 잘 되는 거 같아요! 좋습니다용 ㅎ', 33, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
