INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '더워서 막들어갔는데 북적북적합니다. 역시 연트럴파크! 그래도 3층짜리라 오래 있어도 눈치가 덜 보여요. 공부 하는 사람들 많아요. 와이파이 영수증에 있습니다', 3, 3, 'GOOD', SYSTIMESTAMP);
