INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '주말에 책 읽으러 오기 넘 좋을 것 같은 분위기🩵 책도 다양하게 많구 음료와 디저트도 맛있네요ㅎㅎ 알바생분이 넘 귀여우세요 ,,🫶🏻 추천~~~👍', 29, 8, 'GOOD', SYSTIMESTAMP);
