INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '항상 친절하게 맞아주시고 음료 종류도 많아서 좋아요! 가격이 좋고 맛도 있어서 이 근방 카페중 가장 애용하고 있습니다 저는 카페인을 못 마셔서 커피가 아닌 음료를 자주 마시는 편인데 선택지가 넓어서 좋아요😊 내부에는 10인이 활용할 수 있는 테이블이 있어서 독서모임이나 단체 회의 같은 경우 진행하기도 합니다~', 32, 8, 'GOOD', SYSTIMESTAMP);
