INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '홍대 앞에 갔다가 우연히 지나가다 커피마시러 들렀는데 분위기가 차분하고 아늑하고 너무 좋고 커피와 음료도 맛있네요^^ 또 이 동네오면 오고 싶어요^^', 19, 9, 'GOOD', SYSTIMESTAMP);
