INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '음료 종류가 다양한데 기본적으로 커피부터 달달한 음료까지 신경써서 준비된 느낌이에요. 자색고구마라떼는 뜨끈한 온도로 부드럽게 먹기 좋고 오렌지비앙코도 상큼한 오렌지향이 가미되어 맛있었어요. 크림은 짭짤달콤한 맛이라 소금라떼 좋아하는 분들께 추천드려요.', 43, 1, 'GOOD', SYSTIMESTAMP);
