INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '매달 수요일 혹은 목요일 오후 7시부터 단체석 예약해서 2시간 가량 독서모임 목적을 위해 이용했던 손님입니다. 매달 올때마다 친절히 대해주셔서 감사합니다.', 35, 3, 'GOOD', SYSTIMESTAMP);
