INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '31주년 기념 모든 음료 3.100원 이런 행운이  아인슈페너와 말렌카 슈페너의 크림이 맛있어요 말렌카 가격도 굿~~ 데코도 예뻐요 가성비 최고입니다 커피는 고소한맛 윌리엄으로 커피명이 ㅡ철학자 이름이라고 합니다', 44, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '화장실이 급해 들어왔고 그냥 가기 죄송해서 케이크 만샀는데 목이 마를까봐 차까지 두잔 주셨어요  너무 맛있고 감사해서 음료랑 케이크 하나 더시켜서 먹고갔습니다. 정말 감사합니다!  또올게요♡', 28, 8, 'GOOD', SYSTIMESTAMP);
