INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '언제나 친절하고 따뜻한 분위기. 저는 이곳에서 위로를 받고 갑니다. 좋은 맛과 훌륭한 공간이 나에게 힘을 주고 있습니다. 이 맛이 영원하기를 바라는 기도🙏', 3, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '말렌카와 사라다빵 최고입니다 가성비최고  너무 맛있습니다 아메리카노 복숭아와 포도의 새콤달콤 맛이 난다고 해서 마시니 역시~~ 원두도 좋은것을 사용하신다고 해요', 39, 2, 'GOOD', SYSTIMESTAMP);
