INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '길 가다가 우연히 보았는데 책으로 꾸며놓은 인테리어가 마음에 들어 들어왔어요. 출판사에서 운영하는 북카페라고 하네요 :) 커피도 맛있고 가격도 저렴해요❣️', 48, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '아침마다 여기서 커피를 마시는데, 오늘은 소금빵을 구우셔서 냄새가 좋길래 먹어봤는데 겉바속촉 짱맛이였습니다!! 항상 잘마시고 잘 즐기다 갑니다! 감사합니다!!', 246, 78, 'GOOD', SYSTIMESTAMP);
