INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '근처에 약속있어 거닐다가 북카페가 보여 들어왔어요, 아늑하고 편안히 책볼수있는 자리가 있는것에 너무 감사했고 여러가지 책이 구비되있었네요^^ 조용하게 커피 한잔하고 책 한권 보면서 오랜만에 마음의 여유 즐기다 갑니다. 커피도 맛있네요 :)', 14, 8, 'GOOD', SYSTIMESTAMP);
