INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '하아... 오랜만에 커피나 한잔해 볼까... 있지 있지, 나 오늘 느낌이 되게 좋거든! 분위기에 조금은 취하고 싶다랄까? 이런 날에는 선술집에서의 한잔도 좋지만 그레도 moning에는 커피지! 나를 기다리고 있는 미소녀들에게는 죳또 고멘-! 그치만은 오늘 나... 완전 망가져 버리고 싶은걸...? 크큭... 다들 오늘 같이 밝은 날에는 마.인.드.비.에 와 보는 게 어때? 기분, 좋아져 버릴지도? 크큭....', 12, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '두번째 방문 일요일 지나가다보니  드라마도 촬영하더라구요 오늘은 아메리카노^^ 아인슈페너  크림이 맛있어요 마시기도 편하고 단골  될듯 합니다', 13, 4, 'GOOD', SYSTIMESTAMP);
