INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '커피 맛이 좋아서 팀원들이랑 자주 가는 카페예요. 아메리카노라고 해도 기본이 중요한데! 기본맛이 좋아하서 다른 메뉴들도 다 맛있게 느껴집니다 :)', 35, 10, 'GOOD', SYSTIMESTAMP);
