INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '커피의 고소함이 가득 인테리어도 멋지고 책을 마음껏 읽을수 있고 편안한 공간이 마음에 들어요 커피 추천합니다 커피명도 철학자 이름으로 심리 성격 검사도   무료', 31, 5, 'GOOD', SYSTIMESTAMP);
