INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '직원분들도 너무 친절하시구 음료도 너무 맛있고! 분위기가 좋아서 마음에 들어요~ 책도 있어서 앉아 음료도 마시구 책도 읽으니 좋아요!', 25, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '음료가 맛있어서 자주 가는 곳입니다ㅎㅎ 갈 때마다 친절하게 응대해 주셔서 좋습니다ㅎㅎ 그리고 따뜻한 분위기로 인테리어 되어 있어 갔다 오면 어딘가 힐링 되는 기분도 들어용 쿠키도 넘 맛있어요!', 70, 13, 'GOOD', SYSTIMESTAMP);
