INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마인드 비'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '음료가 전체적으로 맛있고 굉장히 친절한 곳. 학지사의 책 전체를 보는 것만 같은 많은 책을 볼 수 있는 것도 카페의 큰 장점입니다! 최근 여러번 방문해서 다양한 음료를 먹었는데 튀는 것 없이 모든 메뉴가 맛있었어요. 완전 추천...!!', 18, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '여기 분위기 너무 좋아요 디저트39. 믿고 방문하는데 합정점은 찜콩이네요 양화진 데이트코스에넣고 커피와 맛있는 디저트로 마무리하면좋을것같아요 쿠키슈 선택 잘했네요 달콩한 하루 보내고갑니다', 14, 2, 'GOOD', SYSTIMESTAMP);
