INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '콜드브루 1,900원, 다회용 컵까지 남는게 있을까 싶은 가성비와 다이어터한테 좋은 0칼로리 음료들이 많아요! 조용한 분위기로 대화하기 좋고 전체적인 카페 분위기가 화사해서 좋아요! 다시 오고 싶은 카페에요.', 85, 12, 'GOOD', SYSTIMESTAMP);
