INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '시간 정말 많은 분들만 가세요. 점심시간에 밥대신 간건데 음료세개에 조각케익 도지롤 누네띠네 시킨걸 20분동안 안주심 심지어 손님도 우리밖에 없었는데.. 음료도 카테킨아아랑 레몬티 시켰고 시간 걸릴게 뭐가 있나 싶은데 저희가 많이 시켜서 오래걸리는거라고ㅎ 냉동실에 들어있던거 해동하는 시간이라는데 한개 해동이랑 세개 해동이랑 시간이 다른가요..? 아니 일단 해동된게 단하나도 없는것도 당황스럽고 계속 우리탓하는것도 어이없음 20분만에 나온거 보니 도지롤 그냥 얼어있고 카테킨아아는 웬 단맛이 나서 먹다말고 그냥 나왔어요. 문제는 이게 처음이 아니고 저 예전에 점심시간에 갔을때도 아아랑 슈? 같은거 하나 시킨거 삼십분 걸렸었음 그때도 손님은 없었고... 진짜 어쩌려고 장사 이렇게 하세요 걱정될지경임', 42, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '디저트39는 저당 음료가 많아서 종종 이용하는 편이에요! 오늘은 케이크를 먹고 싶어서 왔는데 역시나 너무 맛있네요 특히 치즈 케이크 짱짱!!☺️', 4, 0, 'GOOD', SYSTIMESTAMP);
