INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '학원 바로 근처에 조용하고 넓은 매장이 있어서 자주 오게 될 것 같아요! 시원하고 매장도 쾌적하니 친절하셔서 좋습니당 단골예약❤️', 40, 9, 'GOOD', SYSTIMESTAMP);
