INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '넓고 쾌적해서 혼자 작업하기 좋아요! 디저트 종류도 항상 꽉꽉 채워져있어서 고르기 좋습니다>< 직원분도 빠르고 친절하게 응대해주세요🩷 딸기 요거트 저당라떼가 정말 맛있답니다!', 52, 13, 'GOOD', SYSTIMESTAMP);
