INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '모임이라 일부러예약을 했는데 예약을 안받아서 전화로 얘기하니 안해도 앉을 수있다는 답에 우선 예약을 부탁해서 걸고 갔더니 당일 내부 사정으로 한시간만 이용할수 있다는 충격적인 대응..', 48, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '찾을 땐 안보이지만 지나가다가 보이면 들어올 수 밖에 없는 디저트 39!!!!!! 합정점 디저트 많아요!!!! 커피도 디카페인 변경 했는데 고소해요!!!! 직원 분도 늦은 시간에 왕왕 친절하시구 매장도 쾌적해요!!!!!', 49, 4, 'GOOD', SYSTIMESTAMP);
