INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '넓고 , 쾌적하면서 커피맛도 좋은 디저트39가 있어서 좋은것같아요!! 합정에서 이정도 규모에 가성비까지!!! 친환경잔이라 더 좋은것같아용!! 평일낮에 방문했는데 여유로워서 좋아요!!', 13, 4, 'GOOD', SYSTIMESTAMP);
