INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '역대급으로 불친절한 카페입니다. 베이커리랑 음료 테이크아웃으로 주문했고, 주문 들어간 뒤에 음료도 안만들고 재고정리만 하고 계시길래 키오스크 주문이 제대로 들어간건지 확인하려고 여쭤보니 베이커리는 원래 오래걸린다고 소리치며 말씀하셔서 정말 당황스러웠네요. 혼잣말을 손님 들으라는 식으로 큰소리로 화내면서 얘기하고 "베이커리는 오래 걸린다고 써붙여놔야하나 어휴" 라고 말씀하신거 저 들으라고 하는건가요? 주문한 손님이라고는 저밖에 없는데 아메리카노와 베이커리 구매하고 이렇게 기분 나쁘긴 처음입니다. 다시는 방문할일도 없지만 이렇게 장사하지 마세요.', 22, 2, 'BAD', SYSTIMESTAMP);
