INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '오픈시간 맞춰서 방문했더니 한적하니 좋았어요~ 에어콘 빵빵하게 틀어주셔서 더위 싹 가셨네요 😆 비록 먹고싶었던 메뉴는 없지만 슬림딸기요거트스무디도 만족합니다 🙂 톨사이즈 귀엽습니다! 실용성도 좋아보이니 득템!! 타 39매장은 모르겠으나 합정역점은 음료 하나당 스탬프 하나 찍어주시고 10개 모으면 아아 벤티사이즈 무료득템이니 자주 오시는 분은 직원분께 요청드리면 되요~😆', 41, 8, 'GOOD', SYSTIMESTAMP);
