INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '인테리어가 너무 귀엽고 아늑해서 넘 좋았어요!! 대학생 이후로 간만에 왔는데 추억여행중입니다!! 사장님 선곡이 완전 제 스타일이에요!!😙', 47, 7, 'GOOD', SYSTIMESTAMP);
