INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '더울 때는 디저트39 스무디... 달달한 청포도스무디에 시원한 커피면 좋아요. 조용하고 시원하고 넓고 깨끗하고 좋습니다. ^^', 5, 4, 'GOOD', SYSTIMESTAMP);
