INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '여기 진짜 이름만큼 디저트맛집이에여ㅠㅠㅠㅠㅠ디저트가 다 맛잇고 음료도 하나부터 열까지 다 맛있네요ㅎㅎㅎ디저트킬러라서 맨날 집가는길에 포장하던가 먹고가네요ㅠㅠ너무맛있어요ㅠㅠ', 57, 15, 'GOOD', SYSTIMESTAMP);
