INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '이번에 새로 출시된 제로칼로리 깔라만시 스무디인데 톨사이즈도 있어서 구매해봤네요 컵 크기 깜찍하고 적게드시는 분들께 추천드립니다 오픈한 지 30분 넘어서 방문하니 한적하고 매장도 화장실도 깨끗하고 직원분도 친절하셨어요~🙂', 120, 21, 'GOOD', SYSTIMESTAMP);
