INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '친구들이랑 파티룸 빌려서 놀 때 음료랑 디저트 픽업하려고 들렀어요 종류도 많고 저당음료 제로슈거 음료 많아서 좋습니다 ㅎㅎㅎ 여기 크로칸슈 맛있다고해서 사봤는데 진짜 존맛이네요 여럿이서 먹을 때 선택지가 많아서 좋은 카페!', 25, 7, 'GOOD', SYSTIMESTAMP);
