INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '메뉴가 다양해서 들어갔습니당. 주말이라 그런지 대기가 길었고, 마시고 재활용이 가능한 용기에다 "슬림 딸기 요거트 스무디"랑 "커스터드 그로칸슈"빵이랑 맛있게 먹었습니당^^ 슬림 딸기 요거트 라떼는 벤티 사이즈로 주문하여 저지방 우유로 변경하니 더 맛있네요~~~', 44, 10, NULL, SYSTIMESTAMP);
