INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '제로 아이스티 있어서 먹어봤어요! 그냥 아이스티랑 짱똑같아요!! 존맛~.~ 매장도 깔끔하고 키치한 인테리어가 인상적이에요 잘 먹고 갑니당!', 8, 8, 'GOOD', SYSTIMESTAMP);
