INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '딸이 먹고싶다해서 마포에서 포장하러 검색하고 찾아갔어요 매장 넓고 깔끔하고 맛있어요 밖에 주차해서 마음 급한데 알바 두분 엄청 느긋하게 책보며 만드셔서 조금 놀랐네요 문의시 조금 능숙하게 메뉴설명이라든지 스피드있게 하셨다면  퍼펙트할 매장', 101, 22, NULL, SYSTIMESTAMP);
