INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '생각보다 손님 많아서 놀랐네요 😂 원래 하와이안 코코넛 스무디 먹으려다가 콜라겐슬림 퀸즈베리 스무디로 맘 바꼈어요 상큼한 게 땡겨서요 😄 갈증 싹 사라지면서 상콤한 맛입니다!! 디저트39는 메뉴도 다양하고 음료도 맛있어요 🤤', 36, 1, 'GOOD', SYSTIMESTAMP);
