INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '디저트로 먹을 케익 테이크 아웃 하러 왔어요!! 항상 맛있게 먹어서 자주 옵니당 너무 좋아요오❤️❤️❤️ + 동생 포장해주러 다시 테이크아웃 했습니다! 블루베리치즈케익이 요물이에요ㅠ', 80, 13, 'GOOD', SYSTIMESTAMP);
