INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '합정역 근처에 미팅전에 시간떠서 우연히 들어갔는데 매장도 엄청크고 세련됬네용 디저트메뉴도 엄청 많고 가성비최고 👍🏻👍🏻👍🏻 커피랑 구움과자 시켰는데 맛이 전반적으로 좋았어요 다음에 합정갈때 또 방문할게요 ^^', 2, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '자바칩 프라페 대용량 사이즈 입니다 다른 메뉴에 비해 생각보다 비싸진 않았는데비해 초코맛도 진하고 괜찮았습니다!! 초코라떼 시키는 거보다 자바칩 프라페 주문하는 거 추천드려요~~  (˃‿˂) 주말 낮에 갔는데 매장 한산하고 괜찮네요 ㅋ.ㅋ 10개 모으면 아메리카노 한잔 무료로 주는 스탬프 카드 제공되니 자주 가시는 분들은 만들어 달라고 하심 좋을 거 같아요 (˵ ͡° ͜ʖ ͡°˵)', 3, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '진짜 흑임자라떼에 푹빠져서ㅠㅠ 너무맛있어요!! 여기 합정점은 진짜 인테리어도 깨끗하고 너무 좋네요 카페는 합정오면 여기로와야겠어요!!', 280, 56, 'GOOD', SYSTIMESTAMP);
