INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '자리 넓고 쾌적해서 좋아요 음료도 맛있구 시끄럽지않아서 자주 이용중입니다!! 합정에서 카페 찾으신다면 추천이에용 커피도 음료도 맛있어여', 47, 6, 'GOOD', SYSTIMESTAMP);
