INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '음료 맛있는 게 넘나 많은데 특히 슈크림 시리즈가 맛있네요 안에 바닐라빈도 있어서 고급져 보였고 슈크림라떼 있는 카페 잘 못봤는데 이집은 항시 팔고있어서 좋았습니다~', 118, 23, 'GOOD', SYSTIMESTAMP);
