INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '치즈프로마쥬 바닐라라떼에요 ㅋ 대용량 사이즈 궁금했는데 키오스크 메뉴판에 보니 대용량이 850ml더군요 😆 여기 음료도 맛있고 서비스도 좋아서 자주 들르게 되는 가게에요~ 음료구매하면 잔당 스탬프 한개 찍어주고 열개 모으면 아메리카노 한 잔 서비스로 받을 수 있어요~', 34, 9, 'GOOD', SYSTIMESTAMP);
