INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '요즘 1일 1 디저트39를 방문하며 리뷰를 남기고 있는데 오늘 사장님이 알아봐주시고 쿠키를 주셨습니당! 아까는 너무 알아봐주신게 놀라워서 감사하다는 말씀을 못드렸는데 챙겨주셔서 감사합니다🤍 항상 밝게 맞이해 주시는 직원분과 매장내 감각적인 인테리어 그리고 맛있고 다양한 음료까지! 오늘도 디저트39의 프로틴음료를 마시며 하루를 버텨보겠습니다', 38, 8, 'GOOD', SYSTIMESTAMP);
