INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '당 충전 쇼콜라 케익이랑  아메리카노의 조합은 항상 진리죠^~^ 스트레스 받을때 자주 들러서 먹는 조합인데요~한번 드셔보세요.끝나요♡ 마구 추천누르고 갑니다ㅋㅋ', 89, 18, 'GOOD', SYSTIMESTAMP);
