INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '인테리어도 너무 이쁘고 커피 디카페인 가능해서 좋아요 ㅎㅎ 메뉴도 다양하고 커스터드크로칸도 정말 맛나요👍 매일 먹어도 질리지 않을것 같아요 ㅎㅎ', 17, 9, 'GOOD', SYSTIMESTAMP);
