INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '매장 디스플레이가 넘 예쁘고 디저트도 너무 맛있어요~!! 여러음료를 주문해서 한입씩 먹어봤는데 실패없는 음료맛집이네요~ 아메리카노도 딱 제스타일이에요!', 11, 8, 'GOOD', SYSTIMESTAMP);
