INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '가성비 좋은 디저트39..!! 초코 너무 맛있어여 무엇보다 합정점은 자리도 넓고 테이블이 넉넉해서 좋아여 텀블러 들고오면 할인도 되더라고여 합정 카페 찾으신다면 진짜 추천 ㅜ', 36, 1, 'GOOD', SYSTIMESTAMP);
