INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '직원분들이 친절하시고 음료도 맛있게 만들어주셔서 즐겁게 이야기하다가 가요🩷 매장도 넓고 청결해서 이야기하거나 공부하기도 좋을 것 같아요!!! 다양한 음료가 많아서 골라먹는 재미도 있고 종종 오다가다 들를 것 같아요:) 최고~!!', 13, 0, 'GOOD', SYSTIMESTAMP);
