INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '디저트39 유명해서 자주 먹으러 다니지만,, 특히 크로칸슈 너무 맛있어요 ㅠㅠ💗💗 직원뷴들도 친절하고 합정 디저트39 최고🫶🏻 일단 커피맛도 좋구 일회용 컵 아닌것도 너무 큰 메리트라고 생각합니다 ㅎㅎ💗', 35, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '인테리어가 고급지고 이뻐요~ 걸어가기도 편하고 차로 가기도 편한 위치에 있어 자주 가려고 합니다 사장님도 친절하고 다양한 디저트와 맛있는 음료까지 좋은 시간 보낼 수 있었어요💕', 1, 5, 'GOOD', SYSTIMESTAMP);
