INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '디저트39 도쿄롤이 맛있다고 하길래 궁금해서 방문했는데 매장이 너무 예쁘더라구요!!✨ 저는 오리지널, 녹차 도쿄롤을 시켰는데 엄청 촉촉하고 맛있더라고요 감동적인 맛😭 왜 다들 맛있다고 하는지 알 것 같아요!! 음료와 디저트 종류도 많아서 합정 카페 디저트39 합정역점 자주 방문 할 것 같아요옹🩵🩵', 84, 17, 'GOOD', SYSTIMESTAMP);
