INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '합정역 디저트 종류도 많고 너무 맛있어서 자주 가요~^^ 아이가 화이트 초코 도쿄롤 너무 좋아하고 케익, 크레이프도 맛있어요ㅎㅎ 피곤하고 지칠때 이거만한 치료제가 없더라구요♡♡♡', 33, 10, 'GOOD', SYSTIMESTAMP);
