INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '매번 반갑게 알은척 해주셔서 고마웠었는데, 이번엔 지난번 리뷰까지 기억해주시고, 리뷰 고맙다며 영수증리뷰이벤트용 쿠키까지 챙겨주시다니. 완전 감동이네요. ^^ 수박주스 완전 맛있었어요~~', 126, 21, 'GOOD', SYSTIMESTAMP);
