INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '지난번에 방문했는데 만족스러워서 또 방문했어요 초코 다른 브랜드들보다 훨씬 맛있습니다 ㅋ 양도 많고 자리가 지하에도 있더라고요 방문 추천합니다', 18, 10, 'GOOD', SYSTIMESTAMP);
