INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트39 합정역점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '합정 카페중에 디저트 맛집은  여기가 제일 마음에 들어요 롤종류 많아서 좋고 부드러워요 커피랑 잘 어울려서 오후에 디저트로 딱입니다', 29, 1, 'GOOD', SYSTIMESTAMP);
