INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아우어베이커리 신촌숲길점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '서강대역 근방의 베이커리 카페입니다. 1층에서 빵과 커피를 고른 다음 2층 테이블에 자리 잡았습니다. 건물 층고가 높고 창이 널찍해서 그런지 시원한 인상이 들었어요. 카페와 신촌숲길이 맞닿아 있어 식후에 산보하기도 좋습니다.', 3, 4, 'GOOD', SYSTIMESTAMP);
