INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아우어베이커리 신촌숲길점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '매장도 힙하고 디저트,커피, 음료도 맛있고 직원분들이 친절하고 매장이 2층인데 자리 앉을 테이블이 많지 않아 그 점이 아쉽지만 좋아요. 주차장도 이용 가능한것 같네요 그리고 베이글이 금방 솔드아웃되어서 베이글을 원하면 일찍가서 사서 드세요. 추천합니다.', 99, 22, 'GOOD', SYSTIMESTAMP);
