INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아우어베이커리 신촌숲길점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '팝업을 처음 가봐서 어리둥절 하다가 직원분들께 계속 뭐 여쭈어보고 좀 많이 귀찮게 해드랴서 넘 죄송했는데 ㅜ 직원분들이 친절하게 안내해 주셔서 너무 감사했습니다 ㅜㅜ 음료랑 빵도 넘 맛있었어요 ㅠㅠㅠ 좀 늦게 갔었어서 다른 건 못 봤지만 아무튼 넘 재밌었어요', 104, 23, 'GOOD', SYSTIMESTAMP);
