INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아우어베이커리 신촌숲길점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '라떼가 너무 맛있어요 안갈 수가 없습니다.. 빵은 소세지빵이랑 더티초코가 제 픽입니다. 근데 직원분들이 늘 화가 나 있으세요... 많이 힘드신가.... 싶습니다.. 화이팅!', 61, 12, 'GOOD', SYSTIMESTAMP);
