INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아우어베이커리 신촌숲길점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '까눌레 좋아하는데 라떼랑 먹으니 정말 맛있네요 더티슈도 제 입맛엔 잘 맞았어요 용산 아이파크몰에서 처음 가봤을 때도 빵이 맛있었는데 신촌숲길 점도 맛나네요 담에 또 방문할게요!!☺', 7, 2, 'GOOD', SYSTIMESTAMP);
