INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아우어베이커리 신촌숲길점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '신촌에 상륙한 아우어베이커리! 통창 너머로 보이는 푸릇푸릇한 나무뷰🌳를 볼 수 있는 싱그러운곳! 베이커리 종류도 다양하고 샌드위치와 샐러드도 맛볼 수 있어요!! 아우어베이커리 시그니처 메뉴인 까눌레, 빨미까레, 더티초코 꼭 드셔보시는걸 추천 :)✨', 4, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아우어베이커리 신촌숲길점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '맹그로브 옆에 생긴 경의선 숲길 뷰가 멋진 카페. 큰 통창과 높은 층고로 이루어져 답답하지 않은 분위기에 2층도 있어 여유좌석도 넉넉한 공간! 아침 일찍 열어 모닝빵과 모닝커피 즐기기에도 좋았고 파란 하늘과 푸른 숲 뷰를 보며 힐링할 수 있었어요', 125, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아우어베이커리 신촌숲길점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '오픈 고지한지 몇달만에 갑자기 어제(7월22일) 오픈했어요. 오픈날이라 오후에 가니 빈쟁반이 많았지만 다행이 더티초코는 남아있어서 맛있게 먹었어요. 카야크로와상, 얼그레이까눌레, 옥수수소보로, 크람단팥빵도 맛있게 먹었어요~ㅎ 집앞이라 자주 갈것 같아요~^^', 26, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아우어베이커리 신촌숲길점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '개인적으로 빨미까레 보다 밤페스츄리가 맛있었어요! 커피는 바닐라 더블 먹어봤는데 달달한 커피였어요~ 달콤한 빵 종류를 고른다면 아메리카노가 더 좋을 것 같아요!', 82, 16, 'GOOD', SYSTIMESTAMP);
