INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아우어베이커리 신촌숲길점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '카페 1층은 자리가 별로 없고 2층에 자리가 많습니다. 창밖으로 경의선 숲길을 바라볼수 있어서 좋습니다. 빵에  설탕이랑 초콜릿이 많이 들어가 있어서 그런지 빵은 조금 단편입니다.', 28, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아우어베이커리 신촌숲길점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '제가 제일 젛아하는 앙버터가 없어서 너무 아쉬웠어요. 다른곳은 강아지 동반이 되는거 같은데 여기는 안되나버요...아쉽네요... 앙버터가 들어온다면 다시 올께여...아쉽지만 다음기회에', 65, 18, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아우어베이커리 신촌숲길점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '유명한 빵집이 동네 상륙했다는 소식을 듣고 방문했어요! 이른시간이었는지 더티초코는 없어서 단팥슈크림, 빨미까레,  헤이즐넛퀸아망 구매^^ 시그니처 빨미까레랑 퀸아망은 기대가 컸는지 소소했는데 단팥슈크림이 취향저격이었어요 슈크림과 단팥의 조합이 궁금했는데 묵직하지않고 가벼운 슈크림이라 단팥이랑 잘 어울렸고 빵피도 쫄깃해서 맛있게 먹었습니다.', 26, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아우어베이커리 신촌숲길점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '포장해서 먹어보았어요! 크로아상,아몬드크로아상,더티초코 먹었어요~ 크로아상과 아몬드 크로아상은 겉면이 바삭 보다는 조금 딱딱하게 느껴져서 아쉬웠어요~ 세 가지 중에는 더티초코가 가장 맛있더라구요! 적당히 달고 상짝 바삭하면서 촉촉하고, 초코반죽인지 빵 색깔도 초코색이라 초코맛이 더 진하게 느껴져요!', 27, 10, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아우어베이커리 신촌숲길점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '커피도 맛있고 분위기도 좋아요. 다만 일부 빵이아무런 덮개도 없이 진열되어 있는게 단점이에요. 출입구 바로 앞에 있어 문 여닫을 때 눈에 안 보이는 먼지도 날릴 듯 하고, 오가는 사람들 말 몇마디만 해도 비말이 튈거 생각하면 선뜻 빵을 구입하고 싶지 않는데 부디 개선되었으면 합니다.', 17, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아우어베이커리 신촌숲길점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '드디어 오픈~~  숲길앞에 있어서 전망 좋고. 빵도 맛있고 커피도 맛있지만 의자가 너무 딱딱함  오래 앉아있지는 못할듯ㅠㅠ 그래도 더티초코 땜에 자주 올듯요^^', 6, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아우어베이커리 신촌숲길점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '다른 지점 아우어 베이커리 좋아해서 신촌에도 생겼다길래 방문했어요. 빵 종류는 적당하지만, 좌석 개수는 적어요. 뷰가 좋아요. 그런데 여기 지점은 빵 위에 비닐 안덮여 있네요.. 그리고 직원 분께서 프레첼에 버터 넣어주실 때 계산대에서 바로 제 눈 앞에서 한손으로 넣어주시는것이 좀 당황스러웠습니다. 고객들 안보이게 카운터 뒤에서 넣어서 쟁반에 올려주는 것이 맞지 않나 싶었어요. 다른곳에서는 눈 앞에서 넣어주진 않았어서요ㅜㅡㅜ', 31, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아우어베이커리 신촌숲길점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '빵 종류가 많진 않아요. 근처에 볼일이 있어서 들려보곤합니다. 감자치아바타는 괜찮았는데 콘소보로는 제취향은 아니였어요.겉에는 소보로에 안은 콘과크림치즈? 가 들어있었어요. 뭔가 안어울리는 느낌? 사진은 콘소보로.', 120, 21, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아우어베이커리 신촌숲길점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '언제 오픈하나 했는데 드디어 오픈해서 다녀왔습니다! 역시나 더티초코는 맛있고, 처음 주문해본 올리브 치즈 치아바타 맛있었어용 ㅎㅎ 오븐 1층에 있어서 셀프로 데워 먹을 순 있는데, 너무 구석에 있고 옆은 손님이 앉는 자리라 약간 눈치가 ㅜㅜ 아예 베이커리 근처로 오븐이 옮겨지면 더 좋을 것 가타용 :-) 커피도 무난하구, 2층까지 있고 자리가 넓어서 좋습니다! 다만 화장실은 생기는 걸까용 . . . ? 카페에서 음료 마시면 갈 수밖에 없는디 없다구 하셔서 8ㅅ8 .. 아직 오픈이랑 공사 초기라 그런 걸진 몰라두 ㅜㅜ 얼른 생겼음 좋겠숨당 ..', 57, 17, NULL, SYSTIMESTAMP);
