INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아우어베이커리 신촌숲길점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '플레인까눌레가 시그니처로 표시돼있어 사 봤는데 쫀득한 찹쌀떡 느낌이라 기대와는 조금 다른 맛이었어요. 감태휘낭시에는 감태를 좋아해서그런지 괜찮았어요.', 90, 11, NULL, SYSTIMESTAMP);
