INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아우어베이커리 신촌숲길점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '빵이 전날 것 같음 종이 씹어먹는 느낌임 바삭함이 없음 진짜 전혀 크루와상 맛집이라서 엄청 기대했는데 최악의 아우어임 ㅠㅠ 너무 아쉽다ㅠ', 75, 17, 'BAD', SYSTIMESTAMP);
