INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 서교동사거리점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '점심 먹고 차 마시러 들렸어요 설날인데 차분한 분위기에요 스벅은 북적북적 시끄럽기도 한데 오늘은 한적해요 서교동사거리점은 멋진 그림이 많아서 좋아요❣️ 디카페인 아메리카노랑 밀크티를 마셔요 디카페인 아메리카노는 연한 맛 커피라 맛있어요 밀크티는 달달하고 부드러워요 음악도 차분하고 편하게 쉴 수 있어서 넘 좋아요🥰', 42, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 서교동사거리점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), 'Rozy 파트너님 너무 친절하셔서 감사한 마음에 리뷰 남겨요 ㅎㅎ 제가 기프티콘 결제했는데 당도조절이 안되는 메뉴인줄 모르고 요청했더니 어려운 이유를 안내해주신 다음 우유를 많이 넣으면 덜 달텐데 그렇게 할지까지 물어봐 주시더라고요 보통은 안된다고만 하고 마실 텐데 그짧은 와중에 대안까지 생각해주셔서 감동.. 메뉴 확인도 꼼꼼하게 잘해주셨어요👍🏻 근방 들를때 여기 스벅만 오려고요', 54, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 서교동사거리점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '잠시 이 근처에 일이 있어서 방문했습니다. 평소에 커피를 많이 먹어서 이번에는 커피를 안 먹을려고 해서 주문한 것이 케일 클렌징 음료입니다. 가격은 아이스 아메리카노랑 같고 그냥 무난하게 맛있게 먹을 수 있었습니다!', 11, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 서교동사거리점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '나만 몰랐던 잔액적립 이야기.😂 선물 받은 쿠폰을 금액 때문에 사용 못하다가 오랜만에 약속이 생겨 쓰기로 함. 음료와 케이크 시키고 금액이 남길래 뭘 포장해가나 고민중이었는데 함께한 지인이 남은 금액 적립해 주는데 왜 고민을 하냐고😱 직원분이 60%이상 쓰면 갖고있는 스벅카드에 적립해 준다는.. 작년 10월인가부터 하고 있었다는.. 나만 몰랐던 잔액적립 이슈로 꼰대 확인한 날🤣', 6, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 서교동사거리점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '직원들이 너무 지친것 같아요 바빠서 그런지 웃음기가 없으니깐 화 난것처럼 보이고 물론 화 난거 아닌거 알지만 별로 기분이 좋지않았음 바쁜 일과를 마치고 퇴근시간에가서 그런지 어째든 브랜드집이니 아는 맛임', 36, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 서교동사거리점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '스타벅스 클래식 밀크티 블렌디드 솔직 후기 췌장 크기가 서양인 급이었으면 하루에 5잔 마셨을겁니다 맛있네요 근데 제 기준 클래식 시럽 한번 빼면 딱 적당하게 달달함', 11, 2, 'GOOD', SYSTIMESTAMP);
