INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 서교동사거리점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '회사 근처라서 늘 자주 이용하는 곳이에요. 홍대에 여러 스타벅스가 있는데, 여기가 조용한 편이고 와서 잠깐씩 일하기에도 집중하기 좋아요.', 53, 12, 'GOOD', SYSTIMESTAMP);
