INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 서교동사거리점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '23년 7월 신상인 수박 블렌디드를 먹어봤어요! 수박바 그 잡채입니다! 제가 수박바를 안 먹은지 좀 돼서 확실하진 않지만 초록색 껍질 부분이랑 맛이 똑같아요! 수박바 좋아하시는 분은 좋아하실 거 같아요 ㅎㅎ 생각보다 양이 많아서 다 못 마시고 테이크 아웃해갔어요! 매장은 넓고 안쪽에 푹신한 의자가 많아서 좋아요. 평일 기준 저녁 10시까지 영업합니다.', 17, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 서교동사거리점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '망고리프레셔? 프리퀀시덕에 간만에 다른메뉴 마셔보게되네요~ 색도이쁘고~맛도괜찮아요~미팅많은직딩들은 가끔  마셔주면 좋겠어용♡☕️😉', 12, 6, 'GOOD', SYSTIMESTAMP);
