INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 서교동사거리점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '아메 쿠폰에 추가금 내고 샐러드 먹었어요.. 양도많고 맛있음 ! 스벅은 아메 쿠폰 생길때마다 추가금 내고 다른 메뉴 먹습니다. 커피는 제 입맛에 도저히 안맞아요 ;;;  너무 맛이 없어요; 개인적으로 .', 69, 11, 'BAD', SYSTIMESTAMP);
