INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 서교동사거리점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '얼그레이 티 라떼가 맛있다고 해서 먹으러 왔어요~ 여기에 샷추가 하면 더 맛있다고 하는데 다음에 또 먹으러 오려구여!! 마침 날씨가 갑자기 추워져서 따뜻하게 먹을 수 있게 되었네요~~ 아침으로 소금빵이랑 같이 먹을 예정입니다 :)', 109, 19, 'GOOD', SYSTIMESTAMP);
