INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 서교동사거리점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '매장을 이용하는 연령층이 높아서그런지 예전보다 소란스럽고 부산스러웠어요. 직원이 음료의 주인을 부르는 목소리도 너무 커서 ㅎㄷㄷ 조용했던 스벅이 그립네요~^^', 30, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 서교동사거리점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '스타벅스의 브런치의 기분을 느끼고자 햄앤 루꼴라 올리브 샌드위치와 머쉬룸수프 오로라 캐모마일 어쩌구 음료랑 먹었어요ㅋㄱㅋ 부담없는 맛이라 다 맛있었어욬ㄱ', 47, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 서교동사거리점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '항상 마시는 캐모마일티 진하게 우려줘서 역시 스타벅스가 좋당 ^-^ 홍대근처 돌아다니다가 겨우 자리있는 곳을 찾았는데 조용해서 좋음ㅠㅠ 주말 홍대스벅은 너무 바빠~~', 4, 0, 'GOOD', SYSTIMESTAMP);
