INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 서교동사거리점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '쿠기 맛있습니다. 대신 자몽허니블랙티 자몽맛이 다른 지점에 비해 약한 것 같습니다… 10분? 정도 자나니까 조금씩 쓰다는 느낌..ㅜ', 249, 37, NULL, SYSTIMESTAMP);
