INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '더운여름 딸아이와 시원한 데이트. 토요일 오후 보통 연인들이 데이트로 오는것 같아요. 총 3번 만들어볼수 있고 베이스 맛과 토핑들 다양히 선택가능 우리만의 아이스크림 만들어 먹을수 있어요. 좌식이라 좀 불편한점도 있지만 재미있는 체험이었습니다.', 45, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '이색데이트 하러왔어요 ! 평소에 길가면서 철판아이스크림 해보고싶었는데 직접해보니 더 재밌고 맛있게 먹은거같네요 생각보다 만드는 절차는 복잡하지않지만 힘이 필요하다는걸 하면서 느꼈네요 ㅎㅎ 재료도 많고 맛있고 재밌게 하다 갑니다 또올게요 !! :)', 19, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '아기자기하고 예쁜 분위기와 친절한 설명으로 재미있는 경험이었습니다! 만드는 재미는 물론이고 아이스크림도 맛있었어요! 토핑이나 재료로 제공된 까까들도 다양하고 푸짐했습니다~ 데이트로도 아이와 나들이 경험으로도 좋을것같아요!', 46, 1, 'GOOD', SYSTIMESTAMP);
