INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '생각보다 만들기 어려운데, 엄청 재미있어요! 처음에 어버버했는데, 만드는 방법 알려주셔서 2,3번째는 더 잘 만들 수 있었어요. 아이스크림 맛있고, 토핑도 여러가지 주셔서 꾸미는 재미가 있어요🥰 친구랑 특별한 데이트 하고 싶었는데, 대만족 정말 오길 잘한 거 같아요! 다코야끼도 나중에 꼭 만들러 올거예요!!🙌❤️', 0, 3, 'GOOD', SYSTIMESTAMP);
