INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '홍대 데이트로 너무 좋아요! 철판 아이스크림 만드는 것도 너무 재미있고 카페 분위기도 아기자기하니 좋더라구요 ㅎㅎ 아이스크림 믹스도 세 개나 주시고 기본 토핑들도 다양했어요! 과자 한가득 ㅎㅎ! 사장님도 친절하셔서 정말 즐겁게 놀았습니당! 아이스크림 동그랗게 말기는 생각보다 어려웠지만 재미있어서 실내 데이트로 딱인 거 같아여!', 5, 4, 'GOOD', SYSTIMESTAMP);
