INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '재밌었어요!! 토핑도 다양하고 실패없이 잘 밀었습니다!!! 근데 먹다보면 너무x10000 달아서 느글거려요..... 바로 개쓴 아메리카노 땡기러갔어용 아메리카노 같이 판매하시면 너무 잘팔릴것같습니다👍 담에 또 타꼬야끼 먹으러올게용 !!!!', 79, 11, 'GOOD', SYSTIMESTAMP);
