INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '남자친구랑 이색 데이트를 많이 즐겨가지고 철판 아이스크림 만드는 곳이 홍대에 있다길래 왔어요!!! 여름 한정으로 하는 곳입니다 ㅎㅎ 직원 분들이 너무너무 친절하시고 자리도 아늑해서 재밌게 놀다가 갈 수 있었습니다❤ 철판 아이스크림 처음 만들어 보는데 잘 만들어 볼 수 있게 알려 주셔서 좋았고, 아이가 있으시다면 아이랑 같이 오셔도 참 좋을 것 같아요ㅎㅎㅎ 너무 즐겁게 놀다 갑니다아 홍대 올때마다 들릴 수 있으면 들릴게용👋🏻👋🏻', 89, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '너무너무너무너무너무 재밌고 아이스크림도 예상보다 맛있어서 너무 좋았어요 초코랑 오레오 요거트랑 딸기 강추 합니다!!!! 젤 맛있어요 마지막엔 우유 베이스에 토핑 다 때려넣엇는데 너무 과햇슨 근데도 맛있어서 갠차났어요', 25, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '타코야끼 때도 너무 좋았어서, 여름 시즌 철판 아이스크림도 바로 예약해서 왔어요! 역시나 너무 재미있고 맛있습니다💓👀 엄청 달아서 당 충전 빡 되는 맛이에요! 너무너무 행복한 시간이었습니다🍀', 6, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), 'ㅠㅠ너무너무 재미있어요 아이스크림도 맛있고! 과자는 만들면서 하나씩 계속 빼먹었네용 ㅎㅎ 어느 베이스에 무슨 맛 과자로 포인트를 줄지 정하고 만드는 게 완성도가 좋을 거 같아요! 저흰 초코에 초코 과자, 우유에 커피맛, 바닐라에 딸기 이렇게 분류해놓고 했더니 완전 파는 아이스크림 ㅎㅎ 재밌게 잘 하고 갑니다!', 23, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '남자친구 아니였으면 철판아이스크림 먹으러와서 그냥 아이스크림먹을뻔했어요ㅋㅋㅋ 남자친구 덕분에 겨우 제대로 된거 먹었습니다. 생각보다 만들기가 엄청 어려웠습니다. 그래도 여러 토핑 섞어서 먹으니 맛있었고 재미난 시간 보내다갑니다! 인테리어도 이쁘고 일회용양말이랑 담요 등이 다 준비되어있어서 짧은거 입고 왔어도 신경안쓰였습니다', 31, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '신기해서 처음 방문해봤어요! 만드는 방법도 친절하게 나와있어서 어렵지 않게 만들 수 있었어요😋 연인과 데이트가 있을때 한번 와보시면 재미난 추억이 될 거에요💖', 65, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '아이랑 데이트하러 가기 좋아요~ 만드는 법 설명도 해주시고 앉은 자리에 옆에도 붙어있고 큐알찍으면 만드는 법 나와요. 그래도 요령이 필요하더라고요. 직원분께서 친절하게 설명과 도와주시고해서 아이스크림 말기 성공👍🏻 그다음부터 아이도 계속 성공👍🏻 저는 생각보다 양이 많았어요. 다 못먹었네요. 그래도 즐거웠어요.', 10, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '철판아이스크림 만들기 해보고 싶어서 왔는데 생각보다 어렵지만 그래도 넘 재밌었어요!!! 좋은 추억 만든 거 같아서 쭈아요 다음엔 타코야끼 만들러 올게용😍😍', 2, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '철판아이스크림 만들기 궁금했었는데 은근 말기가 어려운거 같아요 하지만 가이드를 참고하면 굿굿 종류도 많고 토핑도 많아서 먹기에 좋았어요 정말 한달동안 ㅓㄱ을 아이스크림 다 먹은거 같아요 아이스크림 직접 만들면서 먹으니가 좋네요 인테리어도 아기자기해서 좋아요', 6, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '평소 그냥 아이스크림만 사 먹다가 직접 만들어보니 훨씬 색다르고 재미있더라구요! 직원이 기본 재료랑 도구를 준비해 주시고, 설명도 친절하게 해주셔서 어렵지 않았어요. 액체 상태의 아이스크림을 철판 위에 부어서 주걱으로 빠르게 섞고 펴 바른 뒤 돌돌 말아내는 과정이 진짜 신기했어요. 😆 만들 때는 살짝 긴장했는데, 생각보다 잘 말려서 뿌듯했습니다. 맛은 당연히 달콤하고 시원했는데, 제가 직접 만든 거라 그런지 더 맛있게 느껴졌어요. 토핑도 초코, 과일, 쿠키 등 다양하게 선택할 수 있어서 취향껏 즐길 수 있었습니다. 재방문 의사 100!', 82, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '남친이랑 방문했는데 조악어요! 저도 이런 가게 내고싶어요!! 맛을 세가지나 할수 있어서 좋았어요 저는 베이스를 섞는줄 알았는데 3번하는거더라고요! 1) 민초+ 오레오 2) 우유+치즈오뜨+비스코프1개 조합 존맛', 16, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '평소에 길거리에서 철판아이스크림 사먹으면서 너무 맛있고 특이하다 생각했는데 이렇게 직접 철판아이스크림 만들어보는 것도 좋은 경험인것 같아요!!ㅎㅎ처음에는 쉽지 않았지만 갈수록 나아지는 완성품에 뿌듯함도 느끼면서 갑니다ㅎㅎ좋은 추억 만들었어요!!', 8, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '친구랑 같이 왔는데 너무 재밌어요☺☺ 옛날 초등학생때로 돌아간 거 같아요! 다른 테이블 보니 커플로 많이 오시는데, 친구랑 재밌게 놀면서 만들어 먹을 수 있어서 저는 친구랑 오는 거를 더 추천합니다!!! 짱짱👍🏻👍🏻', 26, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '무더운 여름에 어디에서 해볼 수 없는 체험을 해볼 수 있어서 너무 좋은 것 같아요 다같이 도란도란 있지만 각자의 테이블마다 철판과 공간이 있어서 커플끼리 너무 아기자기하게 데이트하기 좋은 것 같아요 ㅎㅎ 생각보다 힘이 많이 들어가서 어려웠지만 생각보다 맛있고 알고리즘에서 뜨던 궁금증도 풀려서 좋았습니다 :)', 51, 12, 'GOOD', SYSTIMESTAMP);
