INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '엄마랑 즐기러 왔는데 인기 많은 이유가 있네용 엄마도 너무 즐거워 하시고 맛도 맛있어요! 이런 체험같은거는 맛은 별루인경우가 많은데 여기는 맛있구 시간도 여유있어 좋아용😍🎀', 35, 1, 'GOOD', SYSTIMESTAMP);
