INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '이거 하고 싶어서 홍대까지 왔는데 철판 아이스크림 생각보다 힘들고 ㅋㅋㅋ 재밌었습니다 !! 사용법도 잘 알려주시고 하다보면 요령도 생겨서 잘 하게 되는 것 같아요 한 번쯤 해보면 좋은 이색 데이트 코스로 추천해요!!!', 49, 2, 'GOOD', SYSTIMESTAMP);
