INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '처음 해본 철판 아이스크림 만들기🍨 재료 고르고 직접 만들어보니까 생각보다 너무 재미있고 돌돌 말리는 모양이 귀여워서 보는 재미도 있었어요! 직접 만들어서 그런지 더 쫀득하고 달콤하게 느껴졌고! 디저트랑 같이 먹으니까 소소하지만 특별한 시간 완성💕 추천하고 싶은 체험이에요👍🏻', 119, 24, 'GOOD', SYSTIMESTAMP);
