INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '겨울에 도란도란에서 타코야끼를 먹고 너무 맛있었는데, 여름에는 철판 아이스크림을 한다고 하셔서 재방문 했습니다! 아이스크림도 너무 맛있구 토핑들 부수면서 만드는 재미가 있습니다!! 직원분들도 너무 친절하셔서 다시 방문하고 싶어요!! 맛있게 먹구 갑니다🩷', 56, 18, 'GOOD', SYSTIMESTAMP);
