INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '재미있게 잘 했습니당 처음 해봐서 처음에는 좀 어려웠는데 가이드 영상보면서 하니 2번째부터 잘 돼서 좋았습니다 직원분도 친절하시고 좋은 경험하고 갑니다', 47, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '내가 만든 철판 아쉬큄~~✨️✨️ 철판 아이스크림 만드는 영상만 주구장창 보다가 직접 만들어보니까 너무 재밌구요 생각보다 잘 안말려서 당황했어요 ㅋㅋㅋㅎㅎㅎㅎ 그래도 너무너무 재밌구 맛도 진짜 철판 아이스크림 사먹었던거보다 더 맛있었어요 🤤 오늘 진짜 더웠는데,, 들어오자마자 시원하고,, 맛있고,, 노래 좋고,, 홍대 오면 담에도 또 올거같아용 강츄츄👍', 76, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '남자친구랑 만드는 걸 좋아해서 철판아이스크림 만드는 곳이 있다길래 와봤어요! 아이스크림도 맛있고 분위기도 아기자기해서 좋습니당 데이트로 추천드려요!', 75, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '도란도란 철판 아이스크림 만들기! 귀엽고 아기자기한 토핑들로 만들어서 너무 재미져요! 점점 갈수록 철판 아이스크림장수 아저씨가 그리워지는 나의 실력이었다..ㅠㅠ 그래도 인테리어도 마음에 들고 그 분위기에 너무 즐거운 추억을 만들고 가요!', 42, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '너무 맛있고 매장도 청결하구 사장님도 너무 좋으세요! 이렇게 만들면서 먹을수도 있고 대화할 수 도있고 꾸미는 아이템도 많이주셔서 꾸미는것도 넘 재밌었어요 이색데이트로도 강추하고 가족들이랑도 많이오세요!😊', 12, 0, 'GOOD', SYSTIMESTAMP);
