INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '철판 아이스크림 진짜 너무너무 만들어보고 싶었는데 체험할 수 있는 곳을 알게돼서 바로 예약했어요!! 평소 철판 아이스크림 만드는 영상을 무척이나 많이 봐서 가장 중요한 요소가 베이스 우유라는 것을 알게 되었는데, 사장님께서 배합을 아주 잘 해 주셔서 초보자들도 손쉽고 깔끔하게 철판 아이스크림을 말 수 있었습니다!!! 기본 우유, 그리고 2가지 베이스 고를수 있고 과일 1개 선택 가능해요. 이외에 데코, 과자들은 충분하게 주셔서 아주 풍성하게 만들 수 있었어요!! 이색 데이트로 왕 추천합니다💛💛', 51, 17, 'GOOD', SYSTIMESTAMP);
