INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '겨울에 타코야키 만들었던 기억이 너무 좋았었는데, 여름엔 철판아이스크림으로 운영하시더라구용! 아이디어가 반짝 빛나는 곳입니다✨️ 타코야끼를 생각보다 잘 만들어서 아이스크림도 잘 만들 수 있을까 기대했는데... 동글동글 마는 게 어렵더라구요..😢 기술이 더 요구되는 듯합니다ㅜㅜ 그래도 만들면서 재밌었어요!! 막트만에 돌돌 말기 성공.....🥹🥹 더운날 색다른 데이트 하고 싶으시면 꼭 도란도란 방문해보세용!💕', 33, 10, 'GOOD', SYSTIMESTAMP);
