INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '우유, 초코, 딸기 세 가지 베이스를 골랐고, 그 위에 토핑도 진짜 다양해서 고르는 재미가 있더라구요. 과일, 젤리, 시리얼, 초콜릿 등등… 취향껏 듬뿍 얹을 수 있어서 만족도 최고✨ 철판 위에서 아이스크림이 만들어지는 과정도 신기했어요!', 84, 15, 'GOOD', SYSTIMESTAMP);
