INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '동생이랑 오랜만에 홍대 데이트 했는데, 이색 카페가 있어서 찾아보니 여기가 나오더라구요! 예약하고 이용했는데 처음 만들어보는거라 어색하지만 그만큼 재밌었어요! 더운날 내가 만든 아이스크림이라니ㅎㅎ 아기자기한걸 좋아하시는 분께 추천드려용~~', 79, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '처음에 철판 아이스크림에 대한 지식이 없어서 많이 망쳤지만 마지막에 사장님이 와서 철판 아이스크림 만들어줬는데 전문가의 솜씨는 다릅니다 망쳤지만 만드는 데 재밌었고 겨울에는 또 다른 거 만 든다고 들었는데 그때 또 재방문해서 재밌게 만들러 갈게요!!', 6, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '철판아이스크림을 직접 해먹을 수 있다는 게 너무 좋은 거 같아요! 베이스 아이스크림을 두개 선택할 수 있고, 기본 밀크 아이스크림까지 해서 총 3번 만들어 먹을 수 있는 게 좋네요. 계속 실패하다가 직원 분의 조언으로 마지막에 예쁘게 말기 성공!', 11, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '양이 되게 많아요 두 명이서 3인분 먹는 느낌 철판아이스크림 맛이랑 토핑을 조합하는 재미+뚝딱뚝딱 만드는 재미 다 있습니다 만족스러워용', 28, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '여친이랑 와서 재밌게 만들다 갑니다! 아이스크림이 이렇게 빨리 만들어진다는 게 놀랍고 신기했어요. 그리고 만들어 먹으니까 더 맛있는 것 같네요 감사합니다~', 12, 7, 'GOOD', SYSTIMESTAMP);
