INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '예약하고 방문했는데 독특한 체험이었어요~~^^ 토핑도 넉넉하고! 아이는 두번째 방문인데 (처음엔 아빠랑 둘이 ㅎㅎ) 한번 해봤다고 곧잘 하네요~~! 재밌고 시원하고~~~ 아이스크림과 토핑이 넉넉해서 배부르네요!', 9, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '더운 여름인데 무엇보다 매장이 청결하고 시원해서 너무 좋았습니다! 매장 이름만큼이나 귀여운 인테리어구요 철판아이스크림 만드는 곳이 거의 없다보니까 이색데이트로 너무 좋았습니다😻👍🏻 토핑 종류도 많고 직원분들도 친절하셔서 다음에 철판 아이스크림 시즌 끝나고 다른걸로 바뀌면 또 오려구요◠‿◠ 시원하고 재밌게 잘 놀다갑니다!! 귀여운 데이트 좋아하면 완전 추천해요~🙈', 25, 5, 'GOOD', SYSTIMESTAMP);
