INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '철판아이스크림 만들어 보고 싶어서 방문했는데 생각보다 어려웠어요. 그래도 너무 재미있구 맛있어서 다음에 또 방문할 것 같숩니다! 겨울에는 타코야끼 만들러 방문할게용', 88, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '여자친구랑 데이트하러 방문했어요. 보기만 했던 철판 아이스크림을 만들어볼 수 있는 체험이 정말 재밌었습니다. 토핑과 베이스맛을 취향에 따라 선택할 수 있어서 더 재밌었던 것 같습니다. 가족이나 연인, 친구분과 이색 데이트에 좋을 것 같아요! 좋은 경험이었습니다!', 15, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '철판 아이스크림 영상 자주 보면서 만들어보고 싶었었는데 오늘 이렇게 만들고 먹어볼 수 있어서 재밌고 좋았어요! 영상에서 영어자막도 나와서 외국인 친구들이랑 놀러와도 좋을 거 같아요 🍬 생각보다 빨리 말기 시작해야 성공하더라고요! 모두들 재밌게 체험하고 가셨으면 좋겠네요 ㅎㅎ', 35, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '종류가 엄청 다양하고 이색데이트 코스로 즐기기 좋은 것 같아요! 생각보다 철판 아이스크림이 잘 안만들어져서 당황했지만 다음에 또 오면 잘 할 수 있을 것 같아요ㅎㅎ', 110, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '철판 아이스크림 만드는 체험은 처음이라 더더 재밌고 즐거웠습니다!ㅎㅎ선택 토핑 외에 주시는 기본 토핑도 다양해서 만드는 재미가 ++!!!! 잘 놀고 갑니당ㅎㅎ', 17, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '남자친구랑 홍대에서 놀 곳 찾아보다가 들른 곳이에요!! 직접 철판아이스크림 만들어볼 수 있는 곳은 여기 밖에 없는거 같아서 특별했고 생각보다도 더 더 맛있고 재밌었어욯ㅎㅎ 겨울에는 타코야끼 만들러올거에요!!❤️', 30, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '철판아이스크림 화려하게 만드시는 분들 보고 저도 해보고 싶어서 찾아보던 중 발견한 도란도란 ! 신기한 경험 하고 가요 ㅎㅎ 그리고 베이스 우유 맛이랑 맛 2개 골라서 각각 만드는 거라 총 3번 할 수 있어요 !! 2가지 맛 섞어서 만드는 줄 알고 조합까지 고민하고 선택했는데..ㅎㅎ 따로 만드는거였어용', 10, 8, NULL, SYSTIMESTAMP);
