INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '이색데이트로 너무너무 재밌었어용 철판아이스크림 만드는 영상 많이봐서 해보고싶었는데 너무 재밌었어용!!!!! 오래된 연인들두 오면 좋을 것 같아요 10년정도 사귄 남친과 웃고 떠들고 갑니당🤣🤣', 69, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '철판 어이스크림 말로만 들어봤지 실제로 만들어보니까 넘 재밌었어요!! 토핑 종류도 다양하고 보기보다 양이 엄청 많았어요!! 아이스크림만 먹어도 배가 부를정도😋 다음에 또 오고싶어요♥️❤️👍 카페 안도 엄청 시원한데 담요도 있어서 굳👍', 400, 85, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '남자친구랑 재밌게 놀다가 갑니다 한번 해보고 싶었던건데 드디어 할 수 있어서 즐거웠어요 겨울에 타코야끼 만들기 체험하러 오겠습니당 좋은 하루 보내고 갑니다! 좋은 일만 가득하시길 바래요❤️❤️', 6, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '아이가 유튜브에서 보고 방문하고 싶어해서 예약후 이용했습니다. 아이스크림을 원하는 토핑과 베이스로 직접 만들어볼수 있어 좋았습니다.', 22, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '항상 사먹어보기만 하던 철판아이스크림을 다양한 토핑과 함께 만들 수 있는 체험을 할 수 있어 정말 좋은 경험이었어요 그리고 생각보다 동그랗게 말아서 컵에 담아내는게 정말어렵다는걸 알았습니다 연인과 함께라면 정말 추천드리는 코스에요 꼭 한번 방문해보세요~~', 35, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '아이스크림 만드는경험은 처음이라 신선하네요 ㅎㅎ 다만 저 같은 똥손은 시간안에 만들기 어렵습니다🫠 다음에 재도전 하러 다시 올게요~', 21, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '밖에서도 먹어보지 않았던 철판 아이스크림을 직접 만들어 먹다니 색다른 경험이었어요! 생각보다 힘이 필요한 작업이어서 그런가 오신 커플 전부 남자분이 말고 계셨지만.. 맛있었어요ㅋㅋㅋㅋ', 56, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '너무 좋았어요! 철판 아이스크림 자체가 처음인데, 맛있었고 만드는 것도 재밌었어요!! 동그랗게 마는 건 어려웠지만...😅 토핑이 다양해서 고르는 재미도 있고 맛있게 원하는 조합 만들어서 먹을 수 있는 것도 좋았어요🫶', 73, 18, 'GOOD', SYSTIMESTAMP);
