INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '홍대 이색데이트를 알아보던 도중 철판아이스크림 만들 수 있는 카페가 있다해서 예약 후 방문했는데 처음이라 서툴어서 저는 실패했지만 여자친구는 성공 해서 엄청 좋아하더라구요 ㅎㅎ 잘 놀다 갑니당', 32, 4, 'GOOD', SYSTIMESTAMP);
