INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '도란도란 핫썸머 메뉴~ 철판아이스크림!! 안갈수 없잖아요ㅎㅎ 날씨도 헉헉!! 아이스크림 먹기 딱 좋은날- 세판이나 만들어 먹을수 있는데, 아무래도 국내최초 철판 아이스크림이라 초보티 팍팍내고 있는데 스윗한 사장님께서 친절하게 설명해 주셔서 완벽한 아이스크림롤 완성했어요~~ 골라먹는 맛, 토핑도 내맘대로~, 만들어먹는 재미까지~~ 친구랑 시간 가는줄 모르고 재밌게 즐기고 왔어요~ 재방문의사 백퍼예요 ㅋㅋ', 27, 10, 'GOOD', SYSTIMESTAMP);
