INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '철판 아이스크림 주문해서 먹어보기만 했는데 실제로 만드니까 정말 재미있고 여자친구랑 추억도 만들어가는 것 같아요!! 만드는 방법도 정말 간단하니까 여름날 이색 데이트 하고 싶으신 분들께 추천합니다', 90, 15, 'GOOD', SYSTIMESTAMP);
