INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '재료가 다양해서 아이가 재미있어하고 맛있어 했어요 양이 많아 넉넉하게 먹을 수 있어 좋았어요! 토핑이 많아 꾸미기 재미있네요!😊', 31, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '여름에 더운데 데이트할 때 실내에서 철판 아이스크림 만들고 시원하게 먹고 대화하면서 즐길 수 있어서 너무 좋았어요 예약할 때 빠르게 하는 것을 추천해요 👍👍 자리가 없을 정도로 유명해서 빨리 잡아야해요 ㅎㅎ', 68, 13, 'GOOD', SYSTIMESTAMP);
