INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '이색데이트를 찾아보다가 철판아이스크림을 직접! 만드는 곳이 있어서 찾자마자 바로 다음날 예약하고 와봤는데 너무 재밌어요!! 평소에 똥손이라 요리하는거 안 좋아하는데 그런거 상관없이 손힘만 조금 있으면 다 가능한 체험이라 신선하고 즐거웠습니다 🫶', 2, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '예약시간보다 20분 정도 일찍 도착했는데 바로 입장 가능했어요~ 대부분 아이 동반 부모님이나 연인들이 오네요^^ 색다른 체험이라 한번 해볼만해요~ 처음 시범 보여주셨는데 알려주신대로 따라하니깐 잘 말리네요~ 즐거운 경함이었습니다:)', 123, 26, 'GOOD', SYSTIMESTAMP);
