INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '도란도란 와서 여자친구랑 처음으로 철판 아이스크림 먹어서 맛있었어요!! 되게 재밌었어요 서로 만드는거 구경하고 1시간이 재밌어서 호닥 지나갔어요!', 49, 0, 'GOOD', SYSTIMESTAMP);
