INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '토핑 넉넉하게 주셔서 엄청 남았어요!ㅎㅎ 옆에는 커피 넣은 철판말이친구인데 색깔이 너무 이상하게 나왔네욬큐ㅠㅠㅠ 색깔은 그래두 진짜 맛있어요.! 꿀조합..우유에 에스프레소랑 롤리폴리, 로투스 조합 진짜 강추합니다..!🤤😋', 32, 0, 'GOOD', SYSTIMESTAMP);
