INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '과자랑 토핑도 다양하고 베이스랑 과자 여러 개 조합해서 만들어먹는게 재밌었어요! 생각보다 어렵지도 않고 만들기 쉬워서 좋았습니당', 7, 6, 'GOOD', SYSTIMESTAMP);
