INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '넘 가고 싶었던 곳인데 직접 해보니까 넘 재밌었어요 철판 아이스크림을 만들어 먹는 곳은 첨이라 토핑도 맘껏해 먹을수있고 만드는 재미도 있어용 ㅎㅎ 베이스도 세개나 주셔서 맘껏 만들어 먹었네용!!❤️', 68, 13, 'GOOD', SYSTIMESTAMP);
