INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '여름에 한번쯤 해보고 싶었던 철판아이스크림 만들기 데이트, 재밌게 하고가요😆 토핑도 다양하고 선택 2개에 기본 우유 베이스까지 있어서 총 3가지 맛으로 다양하게 해먹을수 있어서 좋았습니다ㅎㅎ', 22, 3, 'GOOD', SYSTIMESTAMP);
