INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '다양한 토핑. 메인 맛을 고르고 과자를 더해서 나만의 철판 아이스크림을 만드는데 요거트에 에스프레소를 했더니 세상 맛이 아녔습니다ㅜ여러분은 맛있게ㅜ조합하세요 딴 건 멋.맛있게 만들어 먹었답니다 꿀잼 !!', 9, 10, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '타꼬야끼를 하러 예약 들어왔다가 시기를 놓쳐서 철판 아이스크림으로 도전했는데 옹 이거 재밌어요!!!! 완전추천!! 우유+치즈오뜨+로투스 이렇게 조합해서 컨프러스트 나중에 뿌려먹는게 제일 맛있어요!!! 우유베이스를 제일 추천해요!!!! 더운 여름날에 이색 데이트로 추천!😃🤓👍🤍🍀', 67, 16, 'GOOD', SYSTIMESTAMP);
