INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '여자친구랑 왔는데, 인테리어도 이쁘고 재밌는 시간이었습니다 ㅎㅎ 맛은 기대를 안했는데 솔직히 진짜 맛있었어요 ㅋㅋㅋㅋㅋ 왜 맛있지..? 암튼 재료도 많이 주시고 즐거웠습니다!!', 14, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '철판 아이스크림 만드는 영상을 보고 찾아서 오게된 곳!!! 만드는 법을 쉽게 알게 가이드도 붙어져있고 영상으로도 확인 할 수 있어서 좋았어요~ 토핑도 많고 다양해서 이것저것 시도해보기 좋아요~ 처음이라 그런지 두껍게 돼서 잘 말리지 않아서 아쉬웠어요ㅠ 잘 말고 싶었는데 생각만큼 안된다는게 아쉬울 뿐이었지만 재밌고 좋은 체험하고 가는거 같아요~', 50, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '인테리어 너무 감성적이고 아늑하고 좋아요! 신발 벗고 들어가야 하니까 치마 입으셨으면 담요나 덮을거 챙기세요! 토핑도 다양하고 과자도 정말 다양하게 주셔서 너무 좋아요!! 남친분들은 전완근 자랑하러 오셔도 돼요~(팔근육 엄청 쓰임)', 128, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '철판 아이스크림 만들고 싶었는데 할 수 있는 곳이 있대서 다녀왔어요 직접 해먹으니까 파는 것보다 더 맛있네요🤤 재미있게 잘 체험하다 갑니다!', 112, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '토핑 종류가 많아서 너무 좋았어요! 색다른 데이트하고 싶은 분들한테 추천드려용!! 유튜브 보고 천천히 따라하면 바로 성공하실 수 있습니당(안보고 대충 하다가 2번이나 실패한 사람 나야 나)', 75, 17, NULL, SYSTIMESTAMP);
