INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '신기한 곳이 있어서 방문했는데 철판아이스크림만 보고 기대하고 왔더니 인테리어가 너무 이뻐서 더더 만족스러웠어요! 만드는 것도 재밌고 사진도 완전 많이 건졌어요ㅎㅎㅎ데이트코스로 추천입니당♥️', 3, 2, 'GOOD', SYSTIMESTAMP);
