INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '철판아이스크림을 직접 만드는 체험이 가능한 카페에요 설명도 유튜브로 자세히 나와있고 따로 직접 설명도 해주셔서 어렵지 않게 만들 수 있어서 좋았어요! 타코야키 체험하러 겨울에 또 오고 싶어요', 4, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '인스타 릴스 보고 더운 여름에 데이트하기 딱 좋겠다 싶어서 방문했어요 세 번이나 기회가 있어서 좋았고 매장도 시원하고 재밌었어요!! 그리고 생각보다 배부르기까지 한... 3만원이 아깝지 않은 이색적인 경험이었어요 ㅎㅎ', 15, 8, 'GOOD', SYSTIMESTAMP);
