INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '철판 아이스크림 만드는 거 간단해서 잘 만들 수 있었고, 재료도 다양하게 주셔서 조합하는 재미도 있었어요! 잘 만들고 갑니다 😆', 26, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '색다른 경험을 할 수 있었고 양도 많아서 철판아이스크림을 확실히 체험할 수 있었어요 재밌었고 똑같은 데이트가 지루하신 분들 추천드려요! 생각보다 쉽게 만들 수 있어서 누구나 가기 좋을 거 같아요!', 12, 1, 'GOOD', SYSTIMESTAMP);
