INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '아이가 방학동안 하고싶은 일이 엄마와 데이트&철판아이스크림 먹기여서 찾아보다가 알게되었어요^^ 직접 만들어보는 재미에 푹 빠졌네요~~ 데이트 성공입니다^^', 120, 21, 'GOOD', SYSTIMESTAMP);
