INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '생각만 해봤던 체험이였는데 홍대 드르는 김에 한번 들렀습니다. 만들기가 생각보다 어려웠는데 마지막에 만든 아이스크림은 엄청 잘 말려서 성취감 있었어요!', 21, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '기대 엄청 했는데 기대만큼 재밌었어요! 생각보다 만들기도 쉽고 토핑도 많아서 인스타 스토리 하나 뚝딱이에요 베이스에 너무 많은 토핑을 넣기보다는 적게하고 꾸미는데 많이 해야 더 맛있게 먹을 수 있어요! 왕추천합니당~^^~', 9, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '이색체험이라 재밌고 남자친구가 막상 재밌다고 좋아했어요 ㅋㅋ 타코야끼 할 때 또 올게요 :.ﾟ٩(๑>◊<๑)۶:.｡+ﾟ 번창하세요', 21, 3, 'GOOD', SYSTIMESTAMP);
