INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '아이와 함께 방학 이색경험하러 왔어요. 블로그에서 힘들다고 해서 걱정했는데 생각보다 팔힘이 많이 필요하지는 않았어요. 재밌는 경험하고 갑니다 :)', 28, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '철판아이스크림 만드는 영상만 보다가 직접 만들어보니까 너무 재밌었어요!! 토핑도 다양해서 추가비용 없이 충분히 할 서 있어서 좋았어요 겨울엔 타코야끼 만들러 올게요~', 80, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '너무재밌어요… 타코야끼 만들 때도 왔었는데 여름에는 철판이라 넘좋아요ㅎㅎ 다 좋은데 아이스크림이 너무 느끼해요ㅜㅜ 한 입 넣자마자 느끼하고 맛도 이상해서 마지막엔 거의 남기게 되는거 같아요 체험 자체는 재밌고 시간도 잘 가서 맛만 개선되면 좋겠어요!', 123, 26, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '구성이 되게 알차고 맛있어요!! 그리구 아이스크림 마는거? 되게 재밌고 막 어렵진 않았어요. 직원분께서 친절히 설명해주셔서 좋았으요💕 진짜 분위기도 좋고 자리마다 사진 찍기 좋게 꾸며져있어서 아늑하고 최고엿읍니다.. 다들 여길 꼭 방문해야만.', 8, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '아이와함께 할수있는곳 찾다가 왔는데 넘 넘 좋아요 쉽게 접할수 없는 철판 아이스크림을 직접 만들어서 먹으니 더 맛나네요 아이도 너무 좋아하고 다음에 또 오자고 하네요^^', 109, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '아이랑 방학을 맞아 왔어요~ 아이들이 좋아할 만한 체험입니다! 똥손이라 모양이 예쁘지 않은데, 솜씨 있으신 분들은 잘 만드시는거 같아요! 토핑도 다양하고 3번이나 만들 수 있고 너무너무 만족합니다🩷', 109, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '철판 아이스크림을 만들어 먹을 수 있어서 좋았습니다 :) 만들면서 얘기도 편하게 나눌 수 있고 재료가 많아서 골라먹는 재미가 있었슴니다 !! 다음에 또 방문할 것 같아요 ^_^', 35, 3, 'GOOD', SYSTIMESTAMP);
