INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '아이들과 재미있는 경험 하고 왔습니다. 내부는 좁기는 한데 배려도 잘 해주셔서 아이들과 시원하고 재미있는 체험 잘 했습니다. 또 올게요.', 60, 13, 'GOOD', SYSTIMESTAMP);
