INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '아기자기한 구성이 정말 귀엽네요. 재미도 있고 완성작이 기대한것보다 더 맛있어요~ 우유아이스크림에 오레오 2개랑 비스코프 1개 부셔넣는  조합 완전 추천합니다', 43, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '처음 와봤는데 철판아이스크림 만드는걸 유튜브에서만 보다가 직접 해보게 되니 너무 재밌었어요 심지어 만든 아이스크림이 맛있기까지하니 너무 좋았습니다 과자랑 토핑도 넉넉하게 줘서 많이 남을정도였어요 아직 안해보신분들은 고민 마시고 꼭 한번 와보세요 후회안하실거에요', 106, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '제가 아이스크림을 좋아하는데요, 이렇게 양도 많고 토핑도 많고 직접 만들어 먹을수가 있어서 너무 재미있어요!! 아이스크림 너무 맛있어요', 42, 5, 'GOOD', SYSTIMESTAMP);
