INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '겨울엔 타코야끼 만들어먹는걸로!!!! 여름엔 철판아이스크림 만들어먹는걸로!!!! 사쟝님 아이디어 쵝오자나요👍 만들어 먹는거 너무 재밌어요😆', 56, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '더운여름날 귀엽게 데이트할 수있어서 재밌었어요ㅎㅎ 생각보다 아이스크림을 이쁘게 만들수가없더라구요 그치만 아이스크림 만들면서 웃느라고 즐거운 시간보내다가 갑니다ㅎㅎ', 46, 7, 'GOOD', SYSTIMESTAMP);
