INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '좌식인데 너무 아늑하고 인테리어 진짜 이뻐요. 베이스 선택 2개에 기본제공 우유맛 줘서 총 3번 만들 수 있고, 다 만든후에 뿌리는 토핑도 많이 나오고 베이스에 넣어서 아이스크림으로 만드는 과자도 많이 나와요. 가격값 하는 과자, 토핑 퀄리티로  대만족하는 체험이였어요.', 28, 10, NULL, SYSTIMESTAMP);
