INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '아이생일겸 예약해서 왔는데 아이가 넘 좋아하네요~ 아기자기하고 재료며 너무 귀엽네요~ 처음해보지만 이거저거 섞어보며 만드는 재미가 있네요~~기분좋은 시간보내고 갑니다😄', 32, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '이색데이트로 완전 좋아용 ㅎㅎ 철판 아이스크림이라 젤라또 같이 꾸덕한 식감이라 더 맛있고 넣고 싶은 재료 골라서 넣어 먹을 수 있는 것도 좋은 거 같아용~~ 데이트 코스로 완전 추천함미다💗🫶🏻', 65, 12, 'GOOD', SYSTIMESTAMP);
