INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '어렵지 않구 완전 재밌었어요ㅎㅎㅎ겨울에 타코야키도 꼭 해보고시퍼요 헤헤~~ 재밌게 잘 놀다갑니당!!! 데이트 코스로 츄천해여🫶🏻', 80, 16, 'GOOD', SYSTIMESTAMP);
