INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '여자친구랑 방문했어요! 아기자기한 거 좋아해서 와봤는데 너무 재밌고 직접 만들어수 그런지 더 맛있는 거 같아요! 다음에 타코야끼 할 때도 방문하고 싶어요!', 4, 4, 'GOOD', SYSTIMESTAMP);
