INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '이주 전부터 예약하고 기대하면서 왔는데 기대 한 만큼 철판 아이스크림 만들기 넘 재밌었어용~ 담에 타코야키 체험도 또 하러 오고싶어욤💕', 79, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '정말 리뷰를 각각 남길정도로 재밌어서 후기 남겨요오 ! 예약자 - 친구 슬라임 유튜버라 그런건지 철판 잘하더라고요 … 역시 넌 조리로 가라 .. 근데 시간이 살짝 모잘라요 ㅜㅜ 그래두 진짜 디저트 갔고 어른들이 못하게 하는 음식갖고 놀기라는걸 할 수 있어서 너무 알차구 신났습니다 🤍 10대 여름의 마지막 추억을 만들 수 있게 해주셔서 정말 감사합니다 🫧🤍 친구 -고3 둘이 놀러와도 심심하지 않고 70분 꽉채워서 재미있게 놀았습니다 🐹 각 테이블마다 사진 예쁘게 찍을 수 있도록 인테이러들이 아기자기 해서 너무 예뻐요 오늘 인생사진 많이 남긴것 같아요!! 오늘은 남친 대신에 이제 5년지기 친구와 왔는데 남친이랑 와도 너무 재미있게 놀 수 있을 것 같아요 !! 다음에는 남친과 오겠습니당!!', 49, 5, 'GOOD', SYSTIMESTAMP);
