INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '너무너무 재미있어요~~~!! 베이스 맛은 기본 우유맛에 두가지 더 선택할 수 있는데 세가지 다 맛있었어요! 토핑을 섞어서 오레오처럼 보이지만 사진은 요거트 베이스였습니다! 토핑도 다양하게 주시고 아이스크림 3가지 먹으니까 배도 불러요ㅎㅎ 시원하고 아늑한 곳에서 만드는 재미도 있고 맛도 있어서 데이트 일정으로 완전 추천해요!! 만드는 방법도 어렵지 않아서 부담없고 좋네요!!', 79, 15, 'GOOD', SYSTIMESTAMP);
