INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '우연히 릴스를 보다가 데이트 코스로 추천하길래 남은 자리 바로 예약해서 달려왔어욯ㅋㅎㅋㅎㅋ 무더운 날씨에 데이터하기 어려웠는데 실내에서 즐겁게 추억 쌓고 가용😆😆 아이스크림 베이스 맛도 다양하고 기본으로 제공되는 토핑이 엄청 많아서 선택하기가 어려운!!? 올여름 실내 데이트 장소 저장했어요🐤❣️', 80, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '맛있는 토핑이 잔뜩 있어서 너무 좋아요!! 생각보다 어렵지 않고 재밌습니다!! 다들 특별한 데이트를 원하면 꼭 와봤으면 좋겠어요 ㅎㅎ', 22, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '시험 끝나구 홍대 놀러왔는데 갑자기 비가 와서 급하게 예약했는데 정말 오늘한 것 중 제일 좋았어요!! 사장님이 친절하시구 시간도 순삭입니다😀다들 여기 오세용 근데 길찾기 어려우니까 넉넉히 청천히 오세요 ㅎㅎ', 32, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '아이랑 같이 와서 철판 아이스크림 만들어먹었어요~ 돌돌 마는건 요령이 필요한데 아이가 걍 뿌셔서 그릇에 덜어먹자고 하네요ㅋ 아이가 좋아했고 아이스크림도 맛있게 먹었어요~', 13, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '겨울에는 타코야끼!!  철판아이스크림!! 철판아이스크림을 만들어보고싶었는데, 만들기회가없어서 후라이팬에라도해야하나 생각도했었는데   도란도란 통해서 철판아이스크림 만들고 재밌는 추억만들어서 좋았어여!!  담에또 올게용~!!', 5, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '남자친구랑 사진찍고 와서 아이스크림 만들어 먹는데 이색데이트 코스로 딱 인것 같아요! 나중에 겨울쯤 와서 타꼬야끼도 만들고 싶어용 ㅎㅎ 직원 분들도 친절하십니다!', 10, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '지난번 타꼬야끼때도 왔었지만 분위기가 아기자기하고 귀여운 소품이 많아서 너무 좋아요. 설명도 친절하시고 잘 모르면 QR코드로 영상 보면 되니까 방법도 어렵지 않고 재밌어요.', 22, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '타코야키 핫플 도란도란 여름 특별 아이템은 철판 아아스크림! 소문 듣고 친구랑 놀러갔어요 세가지 베이스에 내맘대로 만드는 아이스크림 세판도 넘 재밌구요 완전 맛있어요! 돌돌돌 말려도 신나고 실패해서 철판에서 부셔먹는 재미도 쏠쏠해요 ㅎㅎ 이거 또 난리날 느낌 ㅋㅋㅋ', 47, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '지인이랑 호기심 반반 만들어서 먹는 철판아이스크림 이라는 주제에 흥미 생겨서 와봤는데 재미도 있고 토핑 다양해서 맛도 다양하게 먹을 수 있어 좋아요 💛💚 예약시간 맞춰 기다림 없이 바로 이용 했습니다 :)', 89, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '인기 많은 도란도란! 친구랑 한달 전에 예약해서 갔어요. 요리도 못하고 손재주가 좋은 편이 아니라 예약하면서도 좀 걱정하긴 했는데 사장님이 친절하게 요리 법을 알려주시고, 벽 바로 옆에 만드는 영상을 볼 수 있는 qr코드도 + 글도 있어서 언제든지 순서를 확인하면서 만들 수 있습니다. 도란도란이라는 이름 답게 인테리어도 감성적이고 따뜻한 느낌이고 정말 도란도란 이야기 하면서 친구들이랑 타코야키 굽기에 좋았어요. 잘하면 잘하는대로, 못하면 못하는대로 재밌는 거는 덤! 갑자기 비가 와서 매장 들어가기 전에 떨면서 들어갔는데, 코타츠는 겨울만 한다는 공지와는 달리 코타츠를 설치해주셔서 정말 감사했습니다. 진짜 만든 타코야키 양만 해도 이미 본전 뽑았습니다 ㅋ 다음에 또 오고 싶어요.', 11, 6, 'GOOD', SYSTIMESTAMP);
