INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '여자친구랑 함께 시간보내기 너무 좋은 곳 같아요. 아이스크림을 같이 만들면서 너무 재밌었어요. 그리고 아이스크림 맛도 원하는 대로 만들 수 있는게 제일 좋아요!!', 65, 15, 'GOOD', SYSTIMESTAMP);
