INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '초등학교 3학년 아이와 와서 철판 아이스크림 만들고 즐거운 시간이었어요~ 시장에서 한 먼 사먹어보고 너무 해보고싶어하던 체험이라 만족도 높아요 ㅎㅎ 아이스크림도 맛있고 토핑도 많아서 배부르게 먹었어요~ 안내도 친절하게 해주십니다', 65, 14, 'GOOD', SYSTIMESTAMP);
