INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '굉장히 신선한 경험이였어요! 데이트 코스로 강추 철판 아이스크림 만드는 과정이 너무 웃겼어요. 타임랩스도 꼭 찍으세요 나중에 보는데 팔 흔드는게 너무 웃겨서 둘이서 터졌네요 ㅋㅋㅋ', 3, 10, 'GOOD', SYSTIMESTAMP);
