INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '처음 와봤는데 친절하게 안내해주셔서 좋았어요! 직접 체험해보는 것도 이색적이고 즐거우아요...♡ 재료도 다양하게 준비되어있어서 맛있게 만들어 먹구 갑니다!! 또 오고 싶어요 ><', 108, 25, NULL, SYSTIMESTAMP);
