INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '부재료도 많고 , 넉넉한 시간에 3번이나 만들어볼 수 있어서 너무 좋았어요 ! 사장님도 너무너무 친절하세요 덕분에 재밌고 달달한 시간 보냈습니다 감사합니다 ! 🙇‍♀️🤍', 39, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '어릴때부터 하고싶었던 철판 아이스크림을 드디어 해봤어요 여자친구가 엄청 좋아해주네요 분위기도 좋고 맛도좋고 좋은 경험이였어요 토핑구성도 알차고 시원해서 여름에 너무 좋았어요', 4, 6, 'GOOD', SYSTIMESTAMP);
