INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '철판 아이스크림을 직접 만들어서 먹을 수 있다니 완전 색다른 데이트였습니다! 재료도 많고 엄청 합리적 가격인 거 같아요 1시간이 눈 떠보니 사라져 있었습니다 ㅋㅋㅋㅋㅋㅋㅋㅋㅋ', 14, 6, 'GOOD', SYSTIMESTAMP);
