INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '여자친구랑 작년에는 타코야끼 만들고 올해에는 철판아이스크림 만들러 또 방문했어요. 생각보다 난이도가 좀 있었어요!! 그래도 재미있고 여자친구가 한번 더 오자고 다음에 더 잘 만들수있다고 하네요 ㅎㅎ', 42, 7, 'GOOD', SYSTIMESTAMP);
