INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '맘자친구랑 실내데이트 뭐할지 찾아보다가 왔는데 시간도 되게 금방가고 ㅋㅋㅋ 평소에 접하지 못할 활동을 해봐서 재미있었어요 첨에는 잘 안말아졌는데 직원분께서 꿀팁 알려주셔서 마지막엔 성공했습니당..!!!!! ㅎㅎㅎ 남자친구도 재밌다해서 담엔 타코야끼 만들러오려구용 ^_^** 재료도 다양하고,, 저는 마지막에 민초베이스로 골랐는데 다른것들보다 덜 달아서 좋았어요 ㅎ 직원분들도 친절하셨습니다!!!', 11, 9, 'GOOD', SYSTIMESTAMP);
