INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '생각보다 토핑이랑 과자를 진짜 많이 주셔서 풍족했어요 ㅎㅎ 철판아이스크림 만들기 너무 재밌고 더운 여름날 실내 데이트로 진짜 추천해요!!🍀🩵', 5, 9, 'GOOD', SYSTIMESTAMP);
