INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '사장님이 친절하게 설명해주시고 재료도 많아서 만드는데 너무 재밌었어요!! 맛도 다양하고 만드는게 너무 신박해서 진짜 좋은 경험이었습니다!', 29, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '친구랑 좋은 추억 남기고 가요~~ 구성도 알차고 재밌었어요 잘 못만드니까 어떻게 만드는지 알려주시고 친절해서 기분좋게 놀다 갑니당~~', 60, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '친절한 설명과 동영상 설명까지 셀프로 기계도 켜보고 아이스크림 만들기 좋은 분위기 아이스크림 지키기 위해 에어컨 빵빵 가정집 리모델링 해서 더욱 아늑해요', 54, 12, 'GOOD', SYSTIMESTAMP);
