INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '색다른 경험이엿어용 ㅋㅋㅋㅋ 무더위에 내가만듬 철판 아슈크림 ㅋㅋㅋ 이색데이트로 좋아용!! 근데 예쁘게 만들기는 쉽지 않아요,,ㅋㅋㅋㅋㅋㅋㅋ', 77, 18, 'GOOD', SYSTIMESTAMP);
