INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '방학시작한 둘째랑 와서 아이스크림 잘만들고갑니다 음악들으며 덩실덩실 춤추고 난리났네요ㅎㅎ 베스킨라빈스보다 더맛있대요~ 감사합니다ㅎㅎ', 14, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '컨셉이 독특하다보니 방문하게 되었습니다. 예약이 어려운 이유가 있네요. 이색데이트로 추천입니다! 여자친구랑 방문하였는데 참 좋아하네요.', 65, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '아이가 꼭 가보고싶다고 해서 방학에 같이왔어요 아이스크림 만드는거 너무 재미있어 좋아하고 생각보다 더 맛있네요 예쁜 공간에서 행복한 시간 보내고 갑니다', 26, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '아이와 함께 예약하고 다녀왔습니다 아기자기한 공간이 좋았고 만드는데도 생각보다 요령이 필요했는데 설명도 잘 되어있고 친절해서 좋았습니다', 14, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '여자친구랑 데이트하러 왔는데 재밌게 잘 놀다 갑니다. 철판 아이스크림을 만들어본다는게 너무 색다르고 특별한 경험이었어요. 데이트 코스로 추천합니다', 10, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '너무너무 재미있어요!!  토핑도 엄청 다양하고 세 가지 맛으로 만들 수 있어서 원없이 체험했어요ㅎㅎ 생각보다 너무 어려워서 돌돌 마는거는 세 번째에 간신히 성공했어요 ㅋㅋㅋㅋ 잘 놀다 갑니당😆', 5, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '아이가 철판아이스크림 좋아해서 직접 만들어 먹으러 봤어요~~주말이라 데이트하시는 분들 많으시네요~ 맛있게 만들고 먹고 갑니다~~', 323, 84, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '겨울에 타코야끼를 너무 맛있게 먹어서 여름메뉴도 기대하며 왔어요! 주말시간이 아깝지 않게 너무 재밌고 맛있었어요😁 사장님이 너무 친절하게 잘 안내해주셔서 어렵지 않았어요ㅎㅎㅎ 꾸미기도 너무 재밌어요! 여름에 한번씩 꼭 오려고요!! 도란도란 짱!!👍👍👍', 27, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '홍대 급 올일이 있어서 검색해보니 철판아이스크림 하더라고요~ 다행이도 예약 바로 하고 담날 방문!! 아이가 너무~~~~좋아했어요 처음엔 둥글게 말지 못 했어요ㅎㅎ 대신  꾸미고 먹으며 즐거워했어요 마지막에는 사장님이 요령을 알려주셔서 아이와 저도 둥글게 말아서 성공!! 조만간 남편과 셋이 와서 또 하게요~~ 홍대 오실 때 꼭 해보세요. 강추합니다 👍', 44, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '기본으로 2가지맛 우유 선택하는데 기본우유도 같이 주시는것도 좋았고 간식을 엄청 많이 주세요 비오는날에 실내데이트로 추천합니당', 89, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '정말 이색적이고 이런 체험 처음이고 재밌었어요!! 아이스크림도 지이이인짜 맛있어요 만드는 재미가 엄청나네요 여자친구랑 재밌게 즐기고 갑니다 ㅎㅎ', 27, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '찰판 이이스크림 만들기 처음 해봣는데 너무 재미있어요! 공간도 아늑하니 두명이서 와서 시원하게 즐기고 가기 좋아요. 양도 많고 맛있네요', 4, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '나름 금손이라 자신했지만 자신을 믿지마세요. 내가 음식할때 느리다? 영혼까지 뽑아서 제일 빨리 말아야합니다. 초코 딸기는 진리👍', 49, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '기본으로 나오는 구성도 좋고 70분 완전 금방가요!!!! 철판 첨에는 좀 어려운데 막판에 진짜 넘 잘나왓어요 이색데이트 대만족🩷', 60, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '철판아이스크림을 원하는 재료 넣어서 민드는게 너무 신선한 체험 같았어요! 평소에 해보지 못했던 일을 해봐서 좋은 경험이였고, 친구들이나 여자친구/남자친구와 함께 방문하면 좋알 것 같아요~!!', 55, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '초5 아이가 엄청 재밌어해요~~아이스크림도 맛있고 토핑 종류도 많네요~~너무 어린애들은 힘들겠지만 초등부터는 괜찮을거 같아요 :)', 16, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '토핑이 다양해서 고르는 재미가 있었고, 3번이나 만들어볼 수 있어서 정말 알찼어요!! 시간도 70분이어서 여유롭게 즐길 수 있었고, 맛도 좋아서 만족스러웠습니다 :)', 37, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '철판아이스크림을 직접 만들어볼수있다는 이색적이고 색다른 경험이에요:) 어려울줄 알았지만 설명도 친절하게 잘해주시고 도와주셔서 잘 만들수 있어서 신나고 재밌어요😆 아이스크림 종류도 다양하고 추가로 넣을수 있는 다양한 재료, 꾸밀수 있는 재료가 충분해서 부족함 없이 먹을수있어용~', 42, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '철판 아이스크림 만들기! 재밌어요! 왜 동글동글하게 안 말아지지 했는데 신경쓰지말고 45도 각도로 계속 밀고 나가면 동글동글 말아져요! 완전 단맛 좋아하는 분들이 좋아할 것 같아요!', 26, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '이색 데이트 장소로 추천!! 직접 재료를 골라서 철판 아이스크림을 만들어 볼 수 있어서 나만의 아이스크림을 만드는 느낌이랄까? 어릴 적 소꿉놀이하던 느낌도 나고 스크래퍼가 쥐어지는 순간.. 여자친구한테 멋있어보이고 싶은 기분이 들었어요.. 멋있는 모습 보여주고 싶으신분들은 연습 조금 해서 가셔요🙂 (사장님이랑 직원분들이 친절히 가르쳐 주셔서 쉽게 체험해 볼 수 있음) 오랜만에 새롭고 재밌는 경험이었어요! 번창하세요~🌸', 16, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '아이 방학을 맞이해서 방문했는데 다른곳에서 해볼 수 없는 특별한 경험이라 너무 재미있게 참여했어요~ 여러가지 토핑에다 본인이 원하는 과일을 넣어서 아이스크림을 만드는 경험은 오래도록 기억에 남을것같아요~^^', 2, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '겨울에 타코야끼 만들러왔었는데 철판아이스크림이라니!! 사장님이 천재이신듯,, 생각보다 구성도 알차고 가게 이름따라 도란도란 얘기하면서 만들었습니다 은근 부수면서 스트레스 풀림.. 오늘은 내가 요리사!', 87, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '외출 시 할 수 있는 것들이 어찌보면 밥 먹고 카페가고 영화보고 다 비슷비슷한데 간편하게 이색 체험 즐길 수 있어 재미있었습니당🥺', 103, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '철판아이스크림을 만들 슈 있다고해서 예약 후 방문했어요! 예약제로 소수인원만 받아서 쾌적하고 조용해서 대화나누기 좋아용!!! 겨울에 타코야끼도 만들러 오고싶어요!', 7, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '처음엔 부모님이랑 온 아이들이 많아서 제가 데이트 장소를 잘못 골랐나 했지만!! 일단 너무 재미있었고 그냥 그 시간에 행복한 방학을 보내러온 가족이 있었을 뿐이고 데이트 하러 오는 곳이 맞았습니다!', 80, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '분위기도 너무 좋고 데이트 코스로 딱이에요. 더운 여름에 시원하게 잘 만들고 먹고 갔어요~~ 토핑 풍부해서 배부르고, 맛은 큰 기대 안했는데 처음 먹어보는 맛에 엄청 맛있습니다~~', 14, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '직접 만들어서 먹으니 존맛탱,, 사장님이 와서 성공하셨냐고 여쭤보셨는데 정말 친절하셨어요 ㅎㅎ 좋은 추억 선물해주셔서 감사합니다!!', 89, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '배이스 하나당 토핑 1~2개가 딱 좋은것같아요! 요아정처럼 토핑많이해봤다가 혈당스파이크제대로맞았네욬ㅌㅋㅎㅋㅎㅎㅋ 그래도 토핑거리 많이주셔서 좋았습니다! 재밌었어요ㅎㅎ', 34, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '친구랑 타코야끼에 이어서 철판 아이스크림 시즌에도 방문했어요! 생각보다 만들기 어려웠지만 재료구성도 알차고 너무 재밌었어요!! 인테리어도 귀엽고 사장님도 친절하셔서 시간 촉박해서 끝에가선 푸파해야하긴하지만 추천합니당', 10, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '홍대에서 머하지 하다가 …여기서 타코야끼 만들기 체험을 한다고 했던 걸 들어서 찾아보니 철판아이스크림을 만들어볼 수 있다고 해서 왔어요!! ‼️토핑종류 완전 다양‼️ ‼️베이스 종류 세가지나 고를 수 잇음‼️ 토핑이 정말 멀 넣어야하지 싶을 정도로 많아서 고르는 재미도 있었고, 만드는데 시간가는 줄도 모르고 너무 재밌게 진행했어요!! 또 오고싶을 것 같아요 재밌는 추억 쌓으러 오세요😍', 14, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '홍대는 역시 핫플🫶 특별하고 이색적인 카페 발견! 인기가 너무 많아 예약해서 친구랑 같이 방문😚 내부는 깔끔하고 소규모이며 대화하기 좋다!! 인테리어가 감각적이고 매우 아기자기하다🥰 음료는 따로 주문해야해서 메론소다 크림소다를 주문~ 기본적인 맛이지만 아이스크림이 투게더맛~🍦 사장님은 친절하시고, 타코야끼 체험도 가격이 착하다! 반죽을 부어서 문어,콘,소세지 등 다양한 토핑을 넣어서 나만의 입맛으로 타코야끼를 만들수있다 ㅇ0ㅇ 굉장히 어려워보였는데 방법대로 하면 동글동글 타코야끼 완성♡ 2번 만들수있어서 양도 많고 남으면 포장도 가능! 진짜 만족하고 가서 재방문 할께용', 16, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '마지막 타임이라서 가게에 저희밖에 없었는데, 그만큼 사장님이 신경 써주셔서 좋았습니다 ! 아이스크림 만들기 난이도는 꽤 있지만 재밌는 경험이었어요 ㅎㅎ 매장 인테리어가 이뻐서 사진이 너무 잘나오는 것도 좋았어요 !', 67, 16, 'GOOD', SYSTIMESTAMP);
