INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '재미잇는 경험이었습니다!! 토핑도 진짜 많아서 오히려 남을 정도였어요! 맛도 있고 재미도 있어요🥰 이색 데이트로 추천합니다!!', 41, 2, 'GOOD', SYSTIMESTAMP);
