INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '과자도 넘 다양하고 맛있어요오!!! 만드는것도 넘 재미있고오오 아이스크림도 넘 맛있어요오!!! 장소도 아늑하구 귀여워서 왕 추천합니다아!!!😀😀😍', 110, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '처음 방문 했는데 설명도 친절히 해주셔서 어려움이 없었고 만드는 방법도 쉬워서 재미있게 즐기고 갑니다!! 겨울에도 타코야끼 만들러 올게용😄😁😁💛💛', 21, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '부산에서 예약하고 왔어요! 친구랑 재밌게 만들고 가는 것 같아용 생각보다 아이스크림 마는 게 쉽진 않았는데 그래도 재미있었어용😊', 42, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '철판아이스크림 한번도 안먹어봐서 궁금했는데 너무 맛있고 재밌었어요😊 토핑도 많이 주시고 양이 많아서 놀랬어요 다음에 또 오고싶어요!!🥰❣️', 15, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '아이가 너무 좋아해서 벌써 세번째 방문합니다 ㅎㅎ 또 오자고 해서 아이 스케쥴에 맞춰 또 예약 ㅎㅎ ㅋㅋㅋ 이러다가 저의 진짜 ㅋ 재능을 발견할지 모르겠습니다 올때  마다 항상 친절히 맞아주셔서 감사합니다 다음달에 또 뵙겠습니다ㅎㅎ', 38, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '타코야끼때도 와봤는데 이번엔 여름버전 철판아이스크림이라고 해서 또 왔어요!! 메장 분위기가 바뀐게 너무 좋네요 ㅎ 이번에도 좋은 추억 남기고갑니다! 이색데이트로 너무 조은거 같아요', 28, 7, 'GOOD', SYSTIMESTAMP);
