INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '한번쯤 만들어보고 싶어서 친구랑 방문했어요!!! 베이스를 최대 3개까지 선택 가능해서 3가지맛 먹을 수 있는게 넘 조앗서요…사장님두 너무 친절하게 알려주셔서 좋았답니다…최고~!!', 37, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '다 큰 성인들끼리도 괜찮을까 걱정했는데 너무 재밌게 잘놀고 잘먹고 갑니다!! 여름에는 와서 시원하고 달달한 데이트 체험해보시길 바래요~ 🍦❄️', 28, 9, 'GOOD', SYSTIMESTAMP);
