INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '컨셉 너무 기엽고 타코야끼 만들기 너무 재밌어요~~ 동글동글 까르보 불닭이랑 같이 먹으니까 천상의 맛 🩵🩵 코타츠도 뜨끈뜨끈하니 너무 기분 좋게 데이트 했습니당 다음에 타코야끼 만들고 싶을 때 또 올래용!!!', 33, 10, 'GOOD', SYSTIMESTAMP);
