INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '홍대 아이스크임만들기 이색카페 방문햣는데 만들어먹는거 너무 재밌어요 세가지 맛인데 두가지 먹아면 배불러요ㅠ한번쯤 방문 해볼만한것같아오💕', 21, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '친구와 홍대에  놀러와서 철판 아이스크림을 만드니 굉장히 신박하기도 했고 좋은 추억을 만들 수 있어서 값진 시간이였습니다. 홍대에 좋은 놀거리 입니다', 88, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '이색데이트 찾아보다가 눈에 띄어 예약 후에 와봤습니다!! 철판아이스크림 만드는곳은 처음보기도 하고 신기했는데 직접 해보니 더 신기하고 재밌었어요!! 토핑재료도 많고 엄청 친절하게 설명해주시고 도와주셔서 처음 해보는건데도 편하고 만족스럽게 잘 즐기고 갑니다!! 도란도란 강추!', 21, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '시원하게 데이트 했어요❤️ 영상으로 본적은 많지만 직접 만들어보긴 처음이에요 ㅎㅎ 과자 종류도 많고 만드는 재미 짱짱👍🏻 바닐라 - 오레오, 오예스,롤리폴리 우유 - 망고,오뜨치즈 초코 - 브라우니, 오뜨초코 이렇게 만들어먹었는데 망고 치즈 생각보다 괜찮은 조합~~~', 48, 2, 'GOOD', SYSTIMESTAMP);
