INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '여자친구랑 더운날 실내데이트 하러 놀러왔어요 베이스를 세개를 주셔서 세번 만들수있고 넣을수잇는 과자토핑도 든든히 주십니다 더운 여름에 와서 철판아이스크림 만들어먹으면서 실내데이트로 딱인것같아요!! 재밌게 놀았습니다~', 29, 0, 'GOOD', SYSTIMESTAMP);
