INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '재밌었습니다. 여자친구랑 데이크로 왔었는데 생각  이상으로 만들기 쉬웠고 내부도 깔끔해서 좋아요 제가 못 찾은 건지 몰라도 중간에 철판을 닦을 만 한한 뭐가 없어서 살짝 아쉬웠습니다', 70, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '재밋어요.^ 매우 힘들긴하지만.. 너무너무 재밌었고 돈값해용 맛있어용 모양은 별루여도… 철판아이스크림 사장님이 얼마나 힘든지 알게되엇어요..ㅎ 재미는 보장가능.ᐟ체력충전해서 오세요들.. 제 남친은 철판아이스크림 만드는 절 보며 원숭이 보듯 쳐다봣어요.. 얜 만드는것보다 제 얼굴보는게 더 재밌었대요.. 하. 일단 재밌으니 강추함니다*^^*', 31, 1, 'GOOD', SYSTIMESTAMP);
