INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '색다른 데이트 재밌었어요! 생각보다 만들기 어려워요ㅋㅋㅋㅋㅋ 말기가 어려운.. 잘만드시는분 대단합니다:)👍 겨울에는 타코야키 만들러 와볼게요~', 45, 10, 'GOOD', SYSTIMESTAMP);
