INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '너무 재밌어용 ㅎㅎ 그리고 아무거나 막 넣어도 꽤나 맛있어요🩷🩷 근데 쫌 말기 어려운데 여러번 시도하다보면 꽤 감 잡혀요 데이트로 완전 추천드립니다!!', 83, 15, 'GOOD', SYSTIMESTAMP);
