INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '여자친구랑 방문했습니다. 이거 재밌네요 손으로 사부작거리는 걸 별로 선호하지 않는데요 오 이거 재밌습니다. 그리고 아이스크림 맛있습니다. 바닐라에 에스프레소 스틱 좋습니다 고급스러운 와일드바디처럼 됩니다.', 122, 21, 'GOOD', SYSTIMESTAMP);
