INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '친구랑 생일 기념 추억 만들러 왔어요:) 직접 처음으로 타코야끼를 만들어 봤는데 어렵지 않았고, 너무 재밌었고 맛도 정말 좋았습니다 ! 재료도 신선하고, 공간도 아기자기 너무 귀여웠습니다. 친구끼리 와도 좋고, 연인끼리 와도 좋을 장소에요! 다음에 기회되면 또 오고 싶네요👍🏻 잘 놀고 잘 먹고 갑니다^^', 10, 2, 'GOOD', SYSTIMESTAMP);
