INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '아이스크림 만드는법이 생각보다 간단하고 서로 으쌰으쌰 만드는게 너무 재밌어요ㅎㅎ 토핑 과하게 넣지 마시고 간단하게만 넣어보세요 재밌었습니다!', 42, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '처음 철판 아스크림 만들어보는건데 첫 시도는 조금 엉망이었지만 하다보니 익숙해져서 늘었슙니자~~ 넘 재밌는 경험이었고 맛있었어요~!~!! 담에 타코야끼로 다시 올게요~!~!', 76, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '😊 : 약 2달 전부터 예약하고 찾아온 집. 타코야끼 직접 만들어 먹을 수 있는 컨셉 넘 재밌고 특별한 경험이에요. 손재주 없는 편인데 생각보다 쉽고 만드는 데 재밌고 맛도 있어요. 이색 데이트로 추천! 코타츠가 있어서 겨울이 제철이긴 함. :)', 93, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '전부터 궁금해서 와본 도란도란! 철판 아이스크림 꽤나 어려웠구요...!!ㅋㅎㅋㅎㅋ 항상 보기엔 쉬워보였는데 역시나 직접하니까 되게 어려웠네요 ㅋㅋㅋㅋ 다음에 오면 더 잘할 각오로...!!!', 19, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '인스타에서 보고 예약해서 왔어요! 타코야끼가 너무 맛있어서 정신없이 먹었네욬ㅋㅋㅋ 직접 만들어서 먹으니까 더 좋았습니다 다음에 또 방문할게요! 번창하십쇼:)', 14, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '분위기도 아늑하고 조영하고 예약하고 오면 딱 좋아요! 아이스크림 만드는 거 어렵지도 않고 맛도 있답니다! 친절해서 너무 좋아요', 30, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '운좋게 예약했어요! 인테리어도 집처럼 너무 아늑하고 타코야끼 꼭 만들어보고싶었는데 체험해볼수있어서 재밌었어요. 유튜브 영상덕분이 생각보다 쉽게 만들었습니당! 너무 맛있었어요 🐙', 43, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '아이스크림을 직접 만들어 먹는 재미가 쏠쏠합니다! 비주얼은 예쁘게 못 만들었지만 맛은 좋아요 ㅎㅎ 데이트 장소로 정말 좋습니다!!', 10, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '기본 우유 베이스 존맛이에요,, 처음엔 잘만들었는데 두번째부턴 실패ㅠ 그리고 많이 치대면 치댈수록 젤라또같아져서 훨씬 맛있어짐,, 과자토핑도 잔뜩 있어서 취향껏 골라먹기 가능! 재방문 각', 98, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '맛도 선택할수 있구 같이 섞는 재료랑 양도 많아서 너무 좋아요💛 저는 개인적으로 민초 너무 맛있었어요!!!!👍🏻 홍대 오면 꼭 예약해서 이용해보세요😆', 83, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '실내데이트로 마땅한 곳 알아보다가 발견한 곳인데 너무 재밌고 시간도 후딱가요!! 항상 예약 꽉차있어서 궁금했는데 인기많은 이유가 있는 것 같습니다ㅎㅎ 겨울에 타코야끼 만들러 또 올게요-!!:)', 46, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '너무너무 재미있고 즐거웠던 타코야끼 만들기 체험 카페 🐙 인기 가득한 곳이라서 주말에 방문하려면 최소 한달 전에는 예약을 해야해요 ⏰⏰ 기다리고 기다린 끝에 드디어 방문!! 기본으로 제공되는 재료들과 맛있는 토핑들 두가지 소스 선택과 추가요금 소스도 선택 가능!! 아늑한 코타츠 속에서의 2시간의 즐거운 타코야키 만들기!! 진짜 너무 재밌고 왕맛있어요 🤤🐧 기다란 꼬치로 콕콕 찔러가면서 돌리는 타코야끼 너무 재밌고 신기한 경험이었어요 💕 만들어지는 알 수는 거의 40알?! 진짜 타코야끼 배 터지게 만들어서 먹다가 올 수 있어요 만들어진거 1,000원만 내면 포장도 가능 🎁💐 커플이 이색 데이트 하기에도 좋고 아이들과 같이 가도 좋을 것 같아요 다음에 또 맛난 타코야끼 만들러 올게요 🐧👍🏻', 65, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '날이 더웠는데 철판아이스크림 만들기 재밌고 맛있었어요 쉽게 생각했는데 잘 안되더라고요 근데 제가 못한 거 였고 여자친구는 잘하더라구요 재밌었습니다!!', 7, 8, 'GOOD', SYSTIMESTAMP);
