INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '만드는 재미 먹는 재미까지! 문어도 너무 야들야들하고 안질겨서 맛있었어요!ㅎㅎ 문어 꼭 꼭 추가하세요~~♡ 배가 안차면 어쩌나 했는데, 너무 배불러서 마지막 6개는 포장!;;; 포장은 8~9개 정도 들어갈것 같아요!ㅎㅎㅎ', 5, 2, 'GOOD', SYSTIMESTAMP);
