INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '데이트히기 좋아요 타코야끼를 함께 만들어 먹는 재미도 있고 예약 하기 어려웠는데 예약해서 오길 잘했네요 음료와 불닭과 타코야끼의 조합이 너무 좋아요 매운소스,갈릭마요 조합 적극 찬성입니다!!! 추운날마다 생각날거 같아요!', 57, 15, 'GOOD', SYSTIMESTAMP);
