INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '타코야끼 만들 수 있는 소중한 경험 주셔서 너무 감사해요!! 이런 체험 너무 좋아하는데 인테리어도 아기자기하고 맛도 있어서 수다 떨다보니 시간 순삭이더라고요 ㅠㅠ 다음에 또 오고 싶어요🥹', 90, 13, 'GOOD', SYSTIMESTAMP);
