INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '저흰 개똥손인가봐요 다른 분들은 다 잘하시던데 저희만 믄제가 있네요… 철판아이스크림 만들기는 재밌었어요 여름에 한번씩 오기 좋을 것 같네요', 33, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '남자친구랑 1주년 기념 데이트 하러 방문했어요! 직접 만들어 먹으니 더 맛있고 재밌었어요😀 겨울시즌엔 타코야끼 만드러 올게요 !', 11, 7, 'GOOD', SYSTIMESTAMP);
