INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '새로운걸 해보고 싶어서 찾아보고 예약했는데 너무 자밌고 맛있었어요! 양도 많고 토핑도 많아서 이것저것 섞어먹는 재미가 있었어요', 48, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '철판 아이스크림을 직접 만들어 볼 수 있다는게 독특하고 특별해요!! 특별한 데이트 코스로 강추드립니다 ~.~ 좋은 추억 쌓고 가요', 27, 5, 'GOOD', SYSTIMESTAMP);
