INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '너무 신기하고 재미있는 데이트였어용 사장님도 친절하세요 중간에 아이스크림이 빨리 굳어서 전완근 운동 열심히 하구왓어용 조아요🫰🏻', 29, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), 'Sns에서 뜰때마다 오고 싶었는데 이번에 예약 성공해서 왔어용 ㅎㅎ 일단 인테리어가 너무 아늑하고 좋아요!! 코타츠 안도 따끗하고 기본 재료들이 이미 충분해서 추가 없이도 알차게 즐길수 있어요! 음료도 저렴하고 사장님이 엄청 친절하셔서 너무 좋았어요~ 양도 꽤 많습니당!! 덕분에 남자친구랑 넘 좋은 추억 쌓구 왔어요 ❤️', 45, 8, 'GOOD', SYSTIMESTAMP);
