INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '종류도 다양하고 생각보다 만들기 쉬워서 재밌어요! 근데 요거트나 민초 하나 할걸 그랬어요,,, 단거 3개 연속으로 먹으니까 물려,,,요,,, 이 리뷰를 보신 분은 꼭 단거단거단거 하지 마세요...! 이미 토핑류도 엄청 달아요!', 33, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '동네 야시장이 열리면 꼭사먹는 철판아이스크림❤ 직접 만들어먹을 수 있다는말에 아이가 얼마나기다렸는지 동그랗게 마는게 쉽진않았지만 재밌는 시간 보내고갑니다❤❤', 40, 1, 'GOOD', SYSTIMESTAMP);
