INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '남자친구랑 와서 해봤는데 재밌었어요!! 첨엔 어려웠는데 남자친구가 곧잘하더라구요,,,, 재미만 있는 것도 아니고 맛있었어요!! 한번쯤 와보는 걸 추천합니다~', 52, 14, 'GOOD', SYSTIMESTAMP);
