INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 1호점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '동생이랑 와서 했는데 너무 재밌었고 사장님도 친절하셔서 설명 잘 듣고 잘 만들었어요! 2판 넘게 나와서 배불러서 포장도 했어요.ㅋㅋㅋ 재밌는 경험이었습니당👍🏻', 121, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로파이'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '네이버 음료 가격표랑 실제 매장에서 결제하는 가격이 달랐어요 5,000원 더 높아서 놀랬어요 그리고 담배 냄새가 너무 심해서 머리가 아팠는데 디퓨저나 탈취제 뿌리면 괜찮을 것 같아요', 13, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로파이'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '이년만에 왔는데 많이 바꼈더라고요. 원래 실내 공간에 바와 디제잉부스가 있었는데 이제 테라스에 개방형 느낌. 노래 좋고 인테리어도 멋있습니다. 근데 칵테일 재료에 가래 같은 걸쭉한 잼인지 뭔지를 쓰는듯 해서 이상했어요', 10, 6, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'TERRACE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로파이'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '홍대 로파이 힙하고 좋습니다. 다만 좀 습해서 중간중간에 물 웅덩이? 가 바닥에 고여있습니자다!! 이것마저 힙하다고 뇌이징 하면 마음이 편하실거에요 아쉬웠던건 전 비흡연자인데 매장 을 아예 오픈하고 영업하시는데 바로 야외석 담배 연기가 다 매장안으로 들어오더라구요ㅠㅠ 헤비스모커 분들이 많이 오셔서 아쉽게도 숨 참기가 힘들어서 금반 나갔어요ㅠ 흡연자분들은 오히려 야외석 좋아하실듯하네요! 홍대 힙한 바 찾으시면 로파이로 고고!', 130, 25, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로파이'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '분위기는 힙한거 좋아하는 사람들만 올만한 그런 감성… 친구들이랑 갈 곳 없어서 그냥 아메리카노 마셨는데 머신이 문제인지 원두가 문제인지 그냥 피시방에서 내려주는 커피같네요. 가격도 싼게 아닌데 여러모로 아쉽습니다.', 20, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로파이'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '사장님이신지 모르겠지만 여자 분 혼자 계셨는데 매장 들어갈 때부터 친절하게 안내해 주시고 처음 간거라 주문 시간이 조금 걸리는데도 불구하고 계속 웃으면서 응대해주셔서 너무 기분좋게 먹고 나왔습니다 분위기가 좋다고 해서 방문한게 큰데 맛도 좋고 사장님 때문이라도 자주 갈 것 같아요❤️', 7, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로파이'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '제 최애인 로파이!! 가게 분위기랑 인테리어 너무 좋고 힙한 분들 많아서 좋아요ㅎㅎㅎ 칵테일 맛있는 편이고 커피도 한 번 먹어봤는데 맛있었어요~ 톰과제리 치즈케이크 진짜 맛있었는데 이제 안들어온대서 아쉽네요 ㅠㅠㅠ 로파이는 사랑입니다 :>', 1, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로파이'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '전에 왔을 땐 맛있었는데 이번엔 쏘쏘... 낮보다 밤에 분위기가 더 좋고 여름되니 창문도 다 열어놓고 에어컨을 틀어놨길래 당황스러웠다.', 12, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '오랜만에 테라로사 들려 보았습니다. 오후 시간이라 그런지 손님이 없네여. 오늘은 비도 오고 해서 라떼와 치즈케이크를 주문했습니다. 바리스타 분 스팀도 아주 잘하고 온도도 너무 뜨겁지 않고 적당하게 잘 만드셨어요. 아주 맛이 좋았습니다. 비오는 날 테라로사에서 라떼 한잔 아주 즐겁습니다', 45, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '피칸파이 맛있음. 근데 다른거 먹어도 됨. 특출날만큼은 아님. 피칸이 고소하고 그렇게 달지 않아서 좋음. 기본적으로 테라로사 매장이기때문에 음료외에도 다양한 커피를 팖. 시향도해볼 수 있는데, 다양한 커피 원두를 팖. 향을 맡아보니까 향긋하고 고소함. 매우 만족스러움. 디자인책같은 것들이 매장에 전시되어있음. 읽어볼수도 있음. 나는 카카오 티를 시켰는데 진짜 초코향이남. 근데 달진않음. 신기함. 잔도 예쁜 잔을 줘서 좋았음. 매장이 넓고 대화하기 좋음. 애초에 건물 자체가 예쁘고 감성적임.', 35, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '너무 배고파서 바로 먹어버려서 사진은 안 찍었지만, 레몬 치즈 케이크 존맛!!! 적당히 상큼하고 입에 술술 넘어가요 💕 담에 또 주문해야지 :) 책도 판매하는 곳이라 그런지 인테리어가 멋졌음!! 공간도 넓고 충전존이 따로 마련되어 있어 대화하는 사람들과 작업하는 사람들 공간 분리되는게 좋더라구요 (테이블은 솔직히 불편했지만) 시디과 전공이면 모를 수 없는 바우하우스... 보자마자 이건 찍어야 해 하고 찍음 ㅋㅋ', 34, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '* 새로생긴 누디트 홍대 1층에 자리한 테라로사 홍대서교점 테라로사의 커피맛은 늘 최고! 커피는 핸드드립으로 마셔야 본연의 맛을 느낄수 있는데, 합리적인 가격으로 늘 오늘의 커피를 내려줌. 파이도 맛있었고 다른 카페들과 달리 층고가 높아서 울림이 적으니 대화하기에 도 그만이다. 누디트 홍대는 청년 1인 가구의 거주공간과 로컬리티를 살린 복합문화공간이라고. 아무튼 건물이 멋지다', 32, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '넓고 시원하고 깨끗하고 ...층고 높고 좌석 많아서 다른 테라로사보다 여유있는 곳, 서관면옥에서 식사하게되면 후식으로 꼭 가게된다. 보장된 산미가득 드립을 만날수 있고 집중해서 앞에사람 이야기를 들을 수 있어 좋다.  조금씩 바뀌는 디저트 라인업도 심쿵 포인트...편하게 이곳만의 원두 구입해서 집에서 드립하는것도 재미있다.', 0, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
