INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '서관면옥 식사 이후에는 거의 테라로사를 찾게 되네요. 사촌 동생과 슬리피 캣을 마시며 간만 대화 삼매경. 주제는 주로 KBL. 요즘은 예전만큼 붐비는 것 같진 않네요. 소음이 다소 심한 편이라 묵직한 주제로 긴밀한 대화를 나누기에는 좀...', 77, 18, NULL, SYSTIMESTAMP);
