INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '우연히 오게된곳.. 한적한 곳에 있어서 좋네요. 빵 종류가 많지 않아 아쉽네요..기본 테라로사에는 좋아라는 빵이 있는데..이곳엔 없지만 넓고 서점같아요', 96, 20, NULL, SYSTIMESTAMP);
