INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '건물부터가 너무 멋지네요. 내부 인테리어는 더욱 멋지구요. 커피도 케잌도 맛나구요. 밖의 푸르름이 뜨거운 이더위를 잊게 만들어 줬어요.좋은 사람들과의 만남♡ 오늘 모든게 완벽했답니다♡', 9, 10, 'GOOD', SYSTIMESTAMP);
