INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '주문이 잘못들어갔는데, 미처 저도 체크를 못했던 부분인데도 매장 직원분들이 너무 친절하게 대응해주셔서 감사했습니다. 🥹💙 커피맛 여전히 좋구요. 특히 카푸치노 너무 맛있어요. 친절한 서비스 및 커피 맛에 또 방문하겠습니다~', 99, 19, 'GOOD', SYSTIMESTAMP);
