INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '숙소옆 테나로사 카베가 있어서 좋네요. 테이크아웃해서 숙소에 와서 한잔 마시고 남은 건 텀블러에 담아서 이동중에 마시니 좋아요. 커피, 인테리어.. 푸드관련 외국책들을 보는 재미가 있어 좋네요.', 41, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '주차되는 커피숍 찾다가 가게되였어요~커피는 맛있었는데 지인이시킨 파프리카쥬스 파프리카향 안난데서 시켰는데 너무 얘기와 다른맛이였어요~그리고 흰셔츠입은 남직원분 한분은 화장실좀 물어봤는데 쳐다도안보시고 불친절한 말투로 응대하셔서 기분이 안좋았네요~인테리어좋고 넓은데 아쉬웠어요', 3, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '커피 맛있는 줄은 알았지만 구움과자도 맛있을 줄이야. 무려 커피 다 마시고 사온 초콜릿도 너무 맛있어서 깜짝 놀랐어요. 홍대점 인테리어나 분위기도 꽤 훌륭해요. 이야기 나누기 좋았습니다.', 78, 12, 'GOOD', SYSTIMESTAMP);
