INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '혼커하기 좋음!! 노트북 2시간 정도 눈치 안보고 작업하기 좋음!! 넓고 쾌적한 공간~!! 스벅같은 편안함~! 서귀포 테라로사 라떼 진짜 맛있었어서 그 맛이 그리워서 40분 버스타고 방문했는뎁…! 여기는 그 맛이 안나서 아쉬웠어요.. 그렇다고 아주 맛없지는 않음..! 까눌레는 맛있음~! 친절함..!', 23, 3, NULL, SYSTIMESTAMP);
