INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '홍대에서 테라로사 커피를 마실 수 있다는 걸 이제서야 알게 된 1인.. 쾌적하고 조용하고 디저트 맛있고 다 좋은데 가격이 살짝 있다는 점^^ 근처 스타벅스 사람 많아서 우연히 발견하고 왔는데 무척 잘 있다가 갔어용', 52, 12, NULL, SYSTIMESTAMP);
