INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '커피 맛이야 검증된 곳이고, 초코 음료도 괜찮네요. 근데 책이 거의 랩핑되어있어 볼 수 있는게 거의 없어요. 책은 오브제가 아니라 읽힐 때 가치있을텐데.. 책 좀 보게해 주세요~~~', 36, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '서교점은 처음가봤는데요~ 라떼가 다른지점보다 연하네요...?😂매장별로 커피맛이 다른거같아 그건 좀 아쉽구요.. 디저트는 다른지점과 동일하게 맛있습니다. 레몬치즈타르트랑 티라미수 피칸타르트 다 맛있구요~ 크로와상은 평범해요😂인테리어는 너무 훌륭합니다👍🏻', 18, 2, NULL, SYSTIMESTAMP);
