INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '오 ~ 망원에 오랜기간동안 공사하던 자리였는데 테라로사가 들어왔네요 ㅎㅎ 신기해라 안에 들어오면 넓고 인테리어가 이쁜거같아요 테라로사만의 분위기가 있는데 한쪽공간에 그분위기가 있고 또 다르게 깔끔한 분위기로 만들었네욤 아메리카노가 기본이 산미있는원두고 라떼가 고소한 원두인데 말하면 바꿔서 라떼에 산미 있는 원두로 변경할 수 있어요 ㅎㅎ 바꾸면 떯은 맛이 올라올 수 있다는데 그래도 맛있었습니다. 케냐 ,온두라스 ,페루 ,에티오피아가, 블렌딩 된 원두인데 색다르고 맛있습니다. 다들 드셔보세요~~ 맛있어요 ㅎㅎ 예전에 강릉에서 가보고 다시와본건데 추천입니다~~~~~', 38, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
