INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '3일동안 출근도장 찍네요 오늘은 원두도 샀어요 외부에서 플리마켓 행사가 있어서 더 복닥거려요 라떼도 맛나네요 11월 한달동안 행사하는게 많네요 쿠폰이 필요하긴 하지만 원두사면 핸드드립 한잔 제공 1+1제공 12시까지 오늘의 커피 주문하면 리필도 된대요', 128, 24, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '이번에는 시간이 없어 아메리카노 한잔 테이크아웃 했지만 다음에는 멋진 담소도 나누고 디저트도 먹어보고 싶어요. 커피도 맛있어요~', 5, 2, NULL, SYSTIMESTAMP);
