INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '새로 생겼다기에 와봤어요. 강릉테라로사는 사람 미어터지는데,여유롭게 커피를 즐길수가 있어서 그점은 좋네요. 혼자 오는분이 많네요. 재방은 글쎄요.... 썰렁한감이 없지않아 있고 개인적으로 광화문점이 최고예요.', 32, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '브라질 드립과 아이스라떼, 레몬치즈 케익, 피칸파이까지 같이 먹었어요~~ 가을느낌 나는 인테리어에 조용한 분위기라 대화 나누기 편안한 곳이에요~ 다음 따뜻한 라떼 먹으러 와야 겠어요^^', 48, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
