INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '주차 한시간 되고 내부는 널찍합니다. 사과비트주스는 바로 착즙해서 주시는데 너무 맛있어서 놀랐고 피칸파이도 재료가 실해서 아주 맛있었습니다', 66, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '테라로사 커피를 워낙 좋아해서 강릉부터 서울까지 웬만한 지점을 다 다녀봤는데 여기도 역시 깔끔해요! 신축건물이라 더 깔끔하고 홍대 번화가에서 좀 떨어져서 조용하구요~ 매장이 개방감 있고 봄 가을엔 밖에서 마셔도 좋을 것 같아요! 커피맛이야 늘 좋아서 나무랄데가 없습니당 담부터 홍대도 자주 방문할게용', 24, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '카푸치노 맛있었구요.넓고 천장도높아서 시야가 시원하고 복잡대지않아 좋습니다 인테리어는so so 홍대 어느 까페에가나 너무 시끄러운데 여긴 사람이 꽉차도 자리 사이가 여유가있어 괜찮네요', 16, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '우왕! 홍대에 테라로사 생겼네용 🥰 라떼도 팔길래 냉큼 사왔어요! 테라로사 커피야 뭐 말 할 것도 없죠! 레몬치케 넘 맛났어요~ 🍰', 75, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '커피 맛있는건 다 아는 사실~ 디져트도 넘 괜찮네요 ^^ 클라이밍 교실(?)과 같이 있어서 공간이 넓고~ 볼거리도 있네요 ^^', 31, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '천장이 높은 곳이라 기본적으로 울림이 있는건 이해가 갑니다. 하지만 벽까지 아무것도 걸리지않은지라 소리가 매우매우 잘 울려서 시끄럽습니다. 소음이 싫은분들 비추천. 그나마 책있는쪽에서 소음을 피할수는 있는데 이쪽은 좌석과 의자가 불편합니다. 평일은 사람이 많지않아 좀 나은데 주말은 정말 소란스럽네요. 카운터에서 일하시는 소리까지 크게 울려 겹칩니다. 디카페인이 맛나서 몇번 갔는데 원두 사와서 집에서 먹으려구요....', 4, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '커피는 늘 무난하게 좋지만 서비스는 약간 불친절 ㅜㅜ 성함은 모르겠고 여자분 (팔에 문신있으신) 여러번 갔는데 갈때마다 불친절해요. 물어봐도 뭔가 보지도 않고 답하시거나 귀찮은 느낌으로 대답을 해서 민망한 느낌.. 저만 그렇게 느끼나 했는데 얼마전엔 같이간 일행도 똑같이 얘기해서 자주가는 곳이지만 남겨봅니다.', 40, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '음 .. 커피는 참 맛있는데 ... 매장이 정말 더러워요 .. 사진은 발로 쓸어서 모아놓은 상태로 찍긴 했지만 원래 소파 ? 쪽 의자, 테이블, 바닥 등에 너부러져 있었어요. 테이블에는 빵가루, 물, 음료 등 눌려서 얼룩진 것도 많구요. 중간 중간 청소가 좀 필요할 것 같네요 ㅠ', 39, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '디저트가 맛있고 자리가 많아요. 테라로사야 믿고 마시니까~ 싱글오리진 컵오브엑셀런스 수상한 원두 드립커피도 마실 수 있었네요. 화장실은 밖으로 나가야 해서 아쉽', 43, 8, 'GOOD', SYSTIMESTAMP);
