INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '테라로사 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '로컬스티치에 머물면서 테라로사에서 커피 마셨어요! 숙소와 붙어있는게 너무 큰 메리트였고 굉장히 넓은 매장과 넉넉한 크기의 테이블이라 다른 업무 보면서 한 잔 하기 너무 좋더라구요 집중도 잘 됐어요!', 3, 2, 'GOOD', SYSTIMESTAMP);
