INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '늘 와보고 싶었던 가게인데 처음 방문했어요. 사실 분위기만 기대하고왔는데 오므라이스가.. 살면서 먹어본 오므라이스 중에 제일 맛있었습니다…… 앞으로는 이 동네 오면 여기만 오고싶어요🥺 푸딩도 너무 맛있었고 많이 달지않은 적당한 밸런스에 너무 좋은 식사 시간 보냈습니다!!', 42, 10, 'GOOD', SYSTIMESTAMP);
