INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '두번에 걸쳐 캐치테이블 대기후 방문했던거라 더더 음식이 맛있었던것 같아요. 기다린만큼 보람있는 맛? 😂 😆  암튼, 맛있는 시간 보내고 와서 다음에도 또 방문하고 싶어요.', 114, 19, 'GOOD', SYSTIMESTAMP);
