INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '부모님이랑 같이 밥먹고 푸딩이랑 파르페 먹었는데 푸딩,,,,, 너무 맛있어서 놀랬어요 제가 먹은 푸딩 중에서 제일 맛있었어요,,,진짜,,,,, 위에 바닐라 아이스크림이랑 바나나 브릴레..?? 무튼 조합이 미쳤어요.. 그리고 파르페가 상큼해서 푸딩이랑 파르페 조합이 너무 좋아서 부모님들도 맛있게 먹었다고 하셔서 뿌듯했어요 🪽🪽', 5, 0, 'GOOD', SYSTIMESTAMP);
