INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '매장은 아늑하니 넘 조았어요☆彡 푸딩은 세계최강맛있었답니다,, 평일에 방문하게 되시면 2층은 이용이 불가하신다는 점 참고 부탁드려용', 42, 5, 'GOOD', SYSTIMESTAMP);
