INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '가보고싶었던 파르페 카페! 🍨 무화과시즌이라 무화과파르페만 있던게 무화과러버라서 솔드아웃되면 어쩌나하구 부랴부랴 달려갔답니다❤️ 다행히 먹을 수 있었구 무화과는 끝물이라 그런지 덜달았지만 밑에 탱x보이 같은 배맛소르베가 정말 맛있었어요🍐 바나나푸딩은 말해머행 찐 일본에서 먹는 푸딩처럼 고소달달하구 바나나위에 브륄레해주신거 신의 한수!!!🍌 가게도 이뻐서 다음에 또 갈집👍🏻', 12, 9, 'GOOD', SYSTIMESTAMP);
