INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '바나나브륄레 푸딩이 진짜 맛있어요 후쿠오카에서 먹었던 푸딩의 맛 ㅠㅠ 말차라떼는 무난했어요~ 개인적으로 달지않은 말차라떼라 좋았어요 좌석이 다양하게 있는 편인데 인기가 많아서 늦게왔음 웨이팅이걸렸을것 같아요 평일 애매한 시간인데도 사람이 많네요', 4, 9, 'GOOD', SYSTIMESTAMP);
