INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '분위기가 아늑하고, 일본카페같아요! 오므라이스가 먹고싶어서 찾아간곳이에요 크림파스타는 면이 약간 두꺼워서 식감이좀있고, 오므라이스는 약간 아쉬웠지만 맛있었어요! 다음에는 카페로 찾아갈게오🧸', 48, 2, NULL, SYSTIMESTAMP);
