INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '좀만 늦게 갔음 웨이팅 있을 편 했어요 비가 오는 날ㅇㄴ데도 불구하고 사람이 많네요! 커피는 고소한 편이고, 메론소다 달콤하니 맛있네용 인테리어가 너무 아기자기 디테일이 살아 있어서 구경할 맛이 나고, 아늑하니 좋네요! 만석 시 카페 이용 제한 시간이 있으니 참고하시길!', 39, 4, 'GOOD', SYSTIMESTAMP);
