INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '합정 안에 있는 작은 도쿄 ㅎㅎ식사와 디저트를 모두 즐길 수 있는 곳 ~! 덕분에 순환율은 좀 느린 편이라 평일에 여유롭게 방문하시는거 추천합니다 ! 주문한 메뉴 다 좋았고 딸기파르페도 진짜 먹어본 파르페 중 가장💥맛있었어요 ㅋㅋㅋ 갬성도 맛도 모두 충실한 곳이라 강추합니다 👍 !', 1, 0, 'GOOD', SYSTIMESTAMP);
