INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '야끼소바가 짭짤한 편인데 그거 먹고 푸딩 먹으니까 단짠 짱이에요 푸딩은 탱탱한 느낌보단 묵직한 질감이고 시럽이 쓰지 않아서 좋아요', 18, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '바질파스타랑 하야시오므라이스는 미쳤습니다 특히나 오므라이스가 정말 맛있어요ㅠㅠ 기존의 케찹소스 오므라이스도 맛있지맘 새로나온 하이라이스소스 올라간 하야시는 더더더더욱 맛좋았습니다... 고오그읍 스러운 맛! 다들 제발 뮥어부세요🍛', 116, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '인상깊었던 메론소다.. ㅎㅎㅎㅎ 이런건 줄 모르고 주문한건데 한참 깔깔됐네요. 식사랑은 어울리지 않는 음료지만 개성있있어요. 나폴리탄은 후추맛 많이 빠진 완벽한 쏘야맛(소세지야채볶음), 첫 맛은 나름 신선했는데 금방 질리긴 했습니다. 오므라이스 부드럽고 좋았습니다만 데리야끼 소스로 볶지 않은 것도 있음 싶었어요.. 끝까지 다 먹기엔 느끼.. 두 메뉴 모두 어른 학생입맛이랄까. 문어가 생생하게 들어있는 타코야끼는 그야말로 맥주를 부르는 맛이더라구요 :-) 기분전환하기 좋은 브런치&디저트 카페라고 생각듭니당, 식사 하러 가진 않을 것 같은데 타코랑 맥쥬는 더 경험해보고싶은 곳!', 44, 8, 'GOOD', SYSTIMESTAMP);
