INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '사람이 많아서 조금 조용한 분위기는 아니였어요! 자리가 많지 않으니 일찍 가시길 추천~ 인테리어 분위디 장난 아니네요ㅠㅜ 신경써서 인테리어하신게 티가 납니다!', 174, 48, 'GOOD', SYSTIMESTAMP);
