INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '파르페만 보고 찾아간 카페인데, 적당한 단 맛 이라서 좋았습니다!! 타코야키 귀여워서 시켰는데 정말 실물은 더 귀여웠고 밑에 양배추가 있어서 오코노미야키 같은 느낌도 있어서 맛있게 잘 먹었습니다~ 혼자 와도 좋은 곳이였습니다 :)', 17, 9, 'GOOD', SYSTIMESTAMP);
