INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '일본감성 합정맛집 수택🤍 주말 오후 1시 기준 30분 정도 웨이팅했어요. 이용시간 제한이 있어서 대기는 은근 금방 빠지는 편이니 순서 다가오면 꼭 근처에 있어야해요. (호출 후 5분 이내 안 오면 순서 넘어감) 푸딩 타코야키 파스타 다 맛있고, 인테리어 아늑하고 아기자기해서 좋아요ㅎㅎ 특히 화장실 비누가 쏘큩..💛 웨이팅이 좀 빡세지만 재방문의사 200%!!', 42, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '합정동의 작은 카페 겸 레스토랑. 나폴리탄, 오므라이스 같은 요리를 맛볼 수 있다. 거창한 일식은 아니지만 일본 분위기가 물씬 난다. 디저트도 훌륭한 곳. 반려견과 가기에도 좋다.', 6, 5, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '키워드 더 못눌러서 아쉬워요  ㅠ ㅠ 음식도 맛있고 디자트도 맛있고 레몬에이드도 맛있고 그냥 다 맛있어요 역시 인기많은곳은 이유가있구나 싶어요 😖 사장님 ,직원분들 다 너무너무 친절하시구 멋쟁이들이에요 ❤️잘먹구갑니다 또 올게요 ! 감사합니다 :)', 21, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '주말 오후에 갔는데 다행히 웨이팅 없었어요! 오므라이스&나폴리탄 파스타 다들 많이 주문하고 시그니처 같아서 시켰는데, 달고 맛있었어요! 푸딩도 진짜 맛있었어요 ◡̈', 97, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '지난날 푸딩먹으러 왔다가  밥도 맛있을것 같아  재방문하였는데 역쉬  맛집이네요..음식.디저트.커피  다 맘에 드는 음식점이예요', 5, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '수택 벌써 n번째 방문이예요… 딸기파르페 다시 나왔다고 해서 서둘러 방문했는데 저번에 먹은 그 맛 그대로 넘 맛있습니당.. 한국에서 파르페 맛있는 곳 여기만큼 없는 것 같아요🥹 또 먹으러 갈래요.. 직원분들도 정말 친절하시구 덕분에 너무 좋은 저녁이였답니다..🤍', 34, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '수택만 3번째 오는데 올 때마다 너무 맛있게 먹어요. 기다리던 딸기파르페를 먹었는데 정말 맛있어서 순식간에 다 먹었어요ㅋㅋ❤🍓', 69, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '바질소바, 나폴리탄, 소르베, 망고파르페 토요일 오픈 15분 전에 도착했는데 여유있게 들어갔습니다. 주문은 계산대에서 해야합니다. 음식 짜지않고 맛있었습니다. 소르베는 자두맛으로 추정되는 새콤달콤한 맛입니다. 파르페는 과자도 있고, 망고랑 구아바? 많이 올려줍니다. 크림+아이스크림 조합 좋네요. 안에도 겹겹이 들어가있는데 바닥부분에 그래놀라?도 있는 것 같아요. 맛있고 든든한 파르페였어요. 식사 후 디저트까지 한곳에서 해결 할 수 있어 좋았습니다.', 279, 32, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '음식이 예쁘게 담겨 나와서 기분이 좋아요⌯''▾''⌯ 음식도 음료도 전부 맛있었어요 분위기가 아늑하고 직원분들이 친절하셔서 즐겁게 있다 갑니다아 또 오고 싶어요!🫶🫶', 10, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '푸딩 맛있어요🍮🤍 아기자기한 공간, 커피 먹으러 들렀는데, , 식사 이용하는 손님도 있고, 합정역 근처 맛집이었음 ! ! ! !', 13, 8, 'GOOD', SYSTIMESTAMP);
