INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '🍮단단하고 부드러운 푸딩 (8천원) 찰랑이는 느낌보단 약간 단단하고 농후한 커스타드맛 아이스크림과 바나나브륄레와의 조합이 굿 디저트메뉴말고도 나폴리탄 같은 간단한 식사 메뉴도 있어 나중에 방문하면 식사+후식 까지 하고싶음 인테리어는 아늑한 우드인테리어 4인테이블이 두개정도 있어서 최대4~5인 정도 방문해도 될듯 한시간 반정도 시간제한이 있음', 0, 5, 'GOOD', SYSTIMESTAMP);
