INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '바나나 브륄레 푸딩 (8,000) 아이스 아메리카노 (4,500) 혼자 카페 와서 먹기 약간 부담스러웠지만 충분히 맛있어서 만족했어요~ 특히 아이스 아메리카노가 기대 안 했는데 맛있었어요… 고소한 맛이 좋아요', 0, 7, 'GOOD', SYSTIMESTAMP);
