INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '올만에 방문한 수택 여전히 맛있네요..💗 맛있는 음료랑 음식 아늑한 인테리어 친절한 사장님까지! 다 맛있고 분위기까지 좋은 곳 요즘 찾기 어려운데 역시 수택이네용🍧💓 나폴리탄 진짜 추천합니다💛 다른 메뉴도 먹으러 또 올거에요💘 (그리고 사장님 넘 귀여워용🍓)', 13, 2, 'GOOD', SYSTIMESTAMP);
