INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '수택 방문만 벌써 3번째 .. 음식도 너무 맛있고 파르페두 맛있어요!! 이번에 바뀐 망고 파르페도 존맛탱 ,, 제 최애는 볼로네제 스파게티입니다 ㅠㅠ 볼로네제 스파게티 꼭 드셔보세용🥺💗💗💗', 38, 8, 'GOOD', SYSTIMESTAMP);
