INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '머리 긴 여자분 알바생인지 아닌지 모르겠는데 알바생이라면 다른 알바생으로 바꾸시고 가족이라면 알바생 쓰는게 나을듯 함 서빙하는게 아니라 걍 던지는 줄 알았어요', 11, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '음식들이 미슐랭급으로 맛있습니다. 사장님도 너무 친절하셔서 기분이 너무 좋았고, 아기자기한 인테리와 분위기 덕분에 수다가 끊기지 않고 편안하게 대화할수 있는 분위기였습니다 강추~', 11, 3, 'GOOD', SYSTIMESTAMP);
