INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '명란크림파스타 13,000 크림소다 진저 하이볼 8,000 타코야끼 4,500 메뉴 다 맛있어서 엄청 만족했어요 식사 메뉴는 3-5시 브레이크 타임 있으니 참고하세요', 1, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '평일 오픈시간에 가서 다행히 웨이팅 없이 바로 들어갔어요! 식사로 나폴리탄 스파게티, 오프라이스, 타코야키5p 먹고 후식으로 바나나브륄레 푸딩, 딸기 파르페,아이스아메리카노 먹었어요. 푸딩먹으러 간거였는데 식사류도 너무 맛있었구요 매장도 인테리어 편안하고 좋았습니다!! 푸딩 묵직하니 솔직히 너무너무 맛있었어요 딸기파르페도 달달하니 맛있었습니다. 기대안했는데 커피도 좋았어요~ 재방문하고싶은 가게입니다', 34, 6, 'GOOD', SYSTIMESTAMP);
