INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '생각보다 웨이팅이 더 심해서 그냥 적어도 1시간 전에 와서 기다리시는 게 나을 거 같아요 주말은 1시에 오픈이어서 잘 보고 가세요! 오무라이스랑 타코야끼 시켜서 친구랑 나눠먹었는데 괜찮은거 같아요 후식은 파르페 먹었어요 달달하니 딸기도 많고 맛있어요!', 29, 0, NULL, SYSTIMESTAMP);
