INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '저번에 친구 만났을 때 여기 왔었는데 월요일인데도 임시휴무여서 헛걸음 했었거든요 오늘은 혼자 재도전했어요 크림브릴레 푸딩 잘 없는데 맛있게 잘 먹었네용^^♡', 76, 13, 'GOOD', SYSTIMESTAMP);
