INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '일본 킷사텐 같은 느낌이에요! (가격은 물론 비싸지만ㅎㅎㅎ..) 소파 좌석은 넓고 아늑해서 좋아요 음식맛은 평타! 친절하셔요!', 8, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '너무 궁금했던 곳인데 드디어! 정말 일본에 있는 식당같은 곳이에요🎀 나폴리탄 스파게티랑 오므라이스 둘다 진짜 맛있었구… 파르페로 마무리하니까 넘 좋았습니다💗 아기자기하니 귀엽고 따뜻한 분위기에요~ 다음에 가면 푸딩도 먹어보고싶어요!', 14, 8, 'GOOD', SYSTIMESTAMP);
