INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '바질우동, 나폴리탄, 오므라이스, 타코야끼, 딸기파르페, 바나나푸딩 싹 다 먹고 왔습니다. 만약 또 가게 되면 나폴리탄이랑 바나나푸딩은 재주문 합니다. 전체적으로 다 맛있습니다.', 39, 9, 'GOOD', SYSTIMESTAMP);
