INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '식사와 디저트 모두 가능한 곳이라 테이블 회전율이 늦다는 말을 듣고 오픈 타임 맞춰서 갔어요. 음식도 맛있는데 바나나 크림브륄레 진짜 맛있어요.', 117, 20, NULL, SYSTIMESTAMP);
