INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '웨이팅이 길다고 해서 걱정했는데 평일에 갔더니 바로 들어갈 수 있었어요! 디저트만 기대하고 갔는데 음식이랑 달달한 음료들도 너무 맛있어서 놀랐어요🥹 내일 또 생각날 맛입니다🍝🍝🍝 그리고 직원들이 친절하십니다👍🏻', 51, 14, 'GOOD', SYSTIMESTAMP);
