INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '커피가 진짜 너무 맛있구요 웨이팅이 길었음에도 불구하고 만족스러운 한끼 했던 것 같습니당 바질우동이랑 오므라이스 진짜 적극 추천합니다 제 이름 석자 걸고 드세오 짱짱 🤪 근데 약간 매장이 추웠음 🥶', 67, 17, NULL, SYSTIMESTAMP);
