INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '푸딩이 너무 먹고싶어서 검색해서 왔는데,, 진짜 짱 부드럽고 너무 맛있어요🫶🏻아이스크림과 촉촉한 푸딩의 조합이 진짜 잘어울리고 커피도 맛있고! 소르베도 짱짱 시원하고 상큼해요💗비와서 갈데 없었는데 너무 쾌적하고 맛있는 카페 발견해서 행복해요🥰🥰🥰파스타도 맛있어보이는데 다음에는 푸드랑 간단하게 맥주도 마시러 또 와야겠어요! 분위기도 넘 좋아욯ㅎㅎ수택 번창하세요,, (나만 알고싶은 카페..🏄🏽‍♀️)', 106, 23, 'GOOD', SYSTIMESTAMP);
