INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '4시 40분쯤 도착해서 5시부터 1시간 웨이팅 했어요! 푸딩이랑 파르페 맛있어요 특히 딸기파르페 딸기 상태도 좋고 달아서 좋았어요!', 1, 10, 'GOOD', SYSTIMESTAMP);
