INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '명란오일 파스타 명란이 많이들어가있어서 만족이요.. 오일파스타를 좋아하는 저라 싹싹 긁어먹었어요 그리고 케일주스?는 건강한맛을 좋아하는 저인지라 다 마셔버렸어요 만족만족이요~! 다음엔 푸딩도 먹어보고싶어요 ㅠㅠㅠ 별5개 드립니다', 46, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '수택'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '합정 갈 일 있으면 항상 들려요👏🏻 일본풍 무드와 인테리어 자체가 멋있습니다. 다른곳에서 쉽게 접할수 없는 메뉴들이 있어서 항상 밥,커피를 같이 즐길수 있어 좋습니다', 30, 9, 'GOOD', SYSTIMESTAMP);
