INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피랩스로스터리 합정점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '합정역 올 때 마다 방문하는 곳입니다~! 1층, 2층 나눠져 있어요~! 혼자 컴 작업 할 때도 편안해요! 원두커피도 직접 판매해서 좋아요~! 조용하면서도 아늑한 분위기로 입니다! 합정역 오면 또 방문할게요~!', 58, 18, 'GOOD', SYSTIMESTAMP);
