INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피랩스로스터리 합정점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '커피 너무 사랑하는 1인이에요. 얼떨결에 들어와 맛본 아이스아메리카노(산미) 에 빠져 3일연속 출석하고 있어요~~ 원두 최고로 좋은거 사용하는것 같아 단골될듯해요😉', 1, 2, 'GOOD', SYSTIMESTAMP);
