INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피랩스로스터리 합정점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '합정역 벚꽃골목 커피숍 2층이 훨씬 더 좋아요☕️ 저녁이라 저는 케모마일 마셨는데 라떼가 다른 곳보다 맛있다고 함께 주문한 친구가 그러네요 스콘도 조각케잌도 괜찮았어요', 24, 3, 'GOOD', SYSTIMESTAMP);
