INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피랩스로스터리 합정점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '녹차라떼 시켜서 2층 전구방으로 들어갔는데 분위기가 좋더라구요. 또 옆 사람이 시킨 케잌도 맛있었습니다. 다만 2층은 일찍 닫아서 아쉽긴 했습니다 :(', 69, 17, NULL, SYSTIMESTAMP);
