INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피랩스로스터리 합정점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '수박주스 시원하고 너무 맛있어요! 다른 곳은 시럽맛만 나는 곳도 있는데 여기는 레알 찐 수박!! 사장님이랑 직원분 너무 친절하시고🥹❤️ 2층도 넓어용!', 29, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피랩스로스터리 합정점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '근처에 볼일이 있어서 왔다가 멀리서 부터 보이는 고급진 카페건물을 보고 추위도 피할겸 왔는데!! 너무 감성적인 곳이더라구요!!♡♡♡ 매장도 넓어서 저리도 널널하고 편히 앉아서 마시고 갔어요!! 커피도 직접 내려주시는데 너무 맛있어요 ㅠㅠㅠ그리고 서비스로 케냐를 조금 주셨는데 진짜 존맛 ㅠㅠㅠ 집이 근처였으면 정말 자주 가고 싶은곳!!', 76, 18, 'GOOD', SYSTIMESTAMP);
