INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피랩스로스터리 합정점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '드립커피가 맛있다고 해서 찾은 카페인데 소문대로 너무 맛있네요. 저는 산미없는 커피를 좋아해 추천 부탁드려서 과테말라로 마셨는데 좋았어요. 친구가 마신 시그니처 커피도(시나몬 들어있는) 맛있대요. 드립커피 좋아하시면 추천합니다.', 4, 8, 'GOOD', SYSTIMESTAMP);
