INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피랩스로스터리 합정점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '직접 로스팅한 드립커피 맛보러 왔어요. 취향 알아가라고 테스트도 한잔 주셨네요. 저는 진한맛이 취향인듯합니다. 뷰도 좋고 합정 거리 사람구경하며 커피한잔하기 좋은곳이네요.', 107, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피랩스로스터리 합정점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), 'The Yemen coffee is very special since it is ancient tradition to grow coffee in Yemen but it''s not widely known for coffee, the coffee was rich and well balanced', 118, 25, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피랩스로스터리 합정점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '핸드드립 시켰는데 원두 상태 따라서 추천해 주셔서 좋았어요 2층까지 있어서 좌석도 넉넉합니다 와서 작업하거나 책 읽기 좋은 듯! 그리고 커피 맛있어요', 6, 3, 'GOOD', SYSTIMESTAMP);
