INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피랩스로스터리 합정점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '주말에 여유롭게 일하러 오는 곳인데 드립 커피도 너무 맛있고 값이 비싸지 않아서 자주 이용하고 있어요! 에티오피아 게이샤 너무 맛있고 그 외에 케냐, 그리고 시즌성 스페셜 원두까지 다 맜있었습니다 ㅎㅎ 핸드드립 좋아하시는 분께 강추!', 81, 14, 'GOOD', SYSTIMESTAMP);
