INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피랩스로스터리 합정점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '직원분들이 친절하게 커피도 추천해주시고 커피 맛도 좋았습니다! 사람들이 많은데 그래도 단체석도 있고 자리도 크게 넉넉히 있어서 친구들이랑 와도 좋을 것 같습니다~', 41, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피랩스로스터리 합정점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '시그니처메뉴인 리조 크레마위에 얹어진 인절미랑 콩가루&크림이 어울려 고소하고 쌉싸름한 커피랑 잘 어울립니다. 2층에는 개인 창가석, 단체석도 있어 시원하고 편안합니다.', 38, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피랩스로스터리 합정점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '텀블러로 핸드드립 커피를 가져와봤습니다. 처음엔 롱블랙을 담아달라고 했는데 370ml 용량에 넉넉하게 담겼습니다. 그래서 핸드드립도 도전해봤죠. 결과는 대성공이었습니다. 사무실에 따로 마련한 작은 컵에 조금씩 소분해서 마시니까 좋더라고요. 신선하고 따뜻한 핸드드립 커피의 첫 느낌을 사무실에서도 느낄 수 있다니. 일회용컵이 꼭 나쁜 건 아니지만 환경을 생각한다는 마음을 얹으니 커피 향이 더욱 좋네요. 오늘도 좋은 품질의 커피에 대만족하고 갑니다.', 29, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피랩스로스터리 합정점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '사람이 엄청 많은 곳. 원래 좋아하는 까페인 커피랩(클럽 빵 근처)과 동일한 분이 운영하시는 곳인진 모르겠지만… 맛은 차이가 있었음 그래도 친절하셨어요.', 88, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피랩스로스터리 합정점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '[기분을 바꾸고 싶을 때 케냐AA] 케냐 원두는 이전에 다른 커피점에서 마셔본 기억이 난다. 시고 가벼웠다. 커피랩스에서도 마셔봤었던 것 같은데, 오늘은 제대로 느껴보고 싶어 찾았다. 직원분은 나에게 원두에 대해 차분하고 친절하게 설명해주셨다. 내리는 방법에 대한 설명도 해주셨고 나는 진하게 원래 원두의 느낌을 살려 내려달라고 부탁드렸다. 직원분의 밝은 웃음과 살가운 응대에 오늘도 연신 감탄하기 바빴다. 커피를 마시는 동안 든 생각은 ''여태 마신 케냐 원두와 본질적으로 다르다''는 것이다. 내 예상보다 더 산뜻하고 톡 쏘는 신맛과 과일향이 났다. 복잡한 생각을 떨치게 했고 입안을 개운하게 바꿔줬다. 정말 생기가 넘치는 음료가 아닌가. 누군가 오후의 나른함을 이겨낼 힘을 얻고 싶다면 케냐 원두를 추천한다.', 87, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피랩스로스터리 합정점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '[좋은 커피의 기준을 새롭게 정의해준 곳] 이곳은 제가 마셨던 커피 중 단연 으뜸의 경험을 주는 곳이었습니다. 저는 모임, 공부 등의 이유로 커피전문점을 찾는 평범한 30대 남성이었습니다만, 여기 커피를 마시고 ''커피가 정말 맛있구나''라는 생각이 들었습니다. 미각만으로 판단해도 이곳의 커피는 온도, 농도, 첫맛과 끝맛이 저에게 가장 이상적인 경험이었습니다. 더불어 이곳은 서비스는 많은 장치가 마련돼 있습니다. 커피를 잔에 가득 주지 않고 넉넉한 공간을 마련해 스스로 기울이는 능동적인 동작을 유도합니다. 원두가 온 곳의 짧은 정보를 제공해 상상력을 자극합니다. 커피를 전달할 때 느긋한 태도와 미소를 통해 받는 사람의 기분을 좋게 합니다. 결론은 커피를 오감을 통해 즐기시는 분이라면 꼭 추천한다는 것입니다.', 74, 18, 'GOOD', SYSTIMESTAMP);
