INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피랩스로스터리 합정점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '여직원 정말 불친절 손님 들어오던 말던 쳐다도 보지 않고 주문받아도 안녕하세요 감사합니다 일절 인사한마디 없이 쌩하니 결제만 합니다 더워서 지나가다 들어왔지만 다시는 안올 곳이에요', 33, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피랩스로스터리 합정점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '남향 카페 햇살이 따스하게 들어와서 굉장히 따뜻했어요 음료 가격도 합정 답지않게 굉장히 저렴 가성비 좋네요 너무 시끄럽지 않아서 대화하기에도 좋았음', 21, 0, 'GOOD', SYSTIMESTAMP);
