INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피랩스로스터리 합정점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '바빠서 커피만 사서 갔는데 야외테라스도 있고 브런치메뉴도 다양해서 다음에 날잡고 와야겠어요! 흡연자분들에게 인기 만점일듯하네요 ㅎ', 23, 5, 'GOOD', SYSTIMESTAMP);
