INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피랩스로스터리 합정점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '여기 이층 테라스 진짜 이뻐요 ㅠㅠㅠㅠㅠㅠㅠㅠㅠ인조 잔디 깔려있고 창이 쫙~ 뚫려있어서 햇빛 받으면서 커피 마시는데 기분 너무 좋아요!!! 헤이즐넛 라떼도 맛있어요!! 굳굳', 51, 15, 'GOOD', SYSTIMESTAMP);
