INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피덕'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '자주가는데 매번 알바생들이 고등학생 양아치 같아요 너무 불친절하고 돈쓰고 기분까지 나쁘게 하는 재능이 있는 것 같네요 저라면 이렇게 직원들 운영하지는 않을 것 같아요 앞으로 여긴 안갈려고요', 105, 26, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피덕'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '매장이 넓고 쾌적하며 내부에 화장실있어 편해요 테이블도 서로 서로 떨어져있어 대화하기 좋았어요 아메리카노 향도 좋았고 헤이즐럿 아메리카노는 좀 달아요.. 의자가 딱딱하고  조금 불편해서 오래 앉아있긴 힘들거 같습니다~', 89, 16, NULL, SYSTIMESTAMP);
