INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피덕'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '1년 넘게 잘이용하고 있었는데, 최근 카운터 근무하시는분 중 나이가 좀 있는 여자분 태도가 좀 문제가 있네요. 본인 기분나쁜것울 고객에게 푸시는거 같네요 . 기분좋게 까페왔다가 기분 나빠질수도 있을거 같아요.', 78, 13, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피덕'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '안에 테이블이 많아서 앉아서 할 거 하기 좋은 장소입니다! 비치된 책들도 종류가 많은데 골라 읽기 좋았어요ㅎㅎㅎ서울에 주차하기 어려운데 주차 공간도 충분해서 좋았어요!!', 13, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PARKING');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피덕'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '커피덕에 아인슈패너를 마시러 자주가는 편인데 사장님이 계실 땐 괜찮은데 알바생들이 이 커피를 만들면 맛이 중구난방이 된다. 특히 오늘은 아인슈패너의 크림이 엉망이었고 양도 모자라 짜증이 좀 났다. 7,500원이나 하는데 이렇게 퀄이 매번 다르면 어쩌자는 건가. 알바들 교육은 좀 잘 시키길.. 휘핑을 치다 말아 플러피한 게 하나도 없었던 그냥 걸쭉한 물이었던 생크림.. 실망.. 커피도 제대로 넣은 거 맞냐?', 54, 14, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피덕'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '중요한 볼 일 이 있어서 온 커피덕 사실 오며 가며 보인 카페였는데 급하게 약속이 생겨서 오게 되었다. 메뉴가 다양했고 내가 주문한건 유자스무디! 요거트가 안들어간 스무디라 좋았고 중독성있는 .. 맛 커피 원두 종류가 다양하고 디저트 종류도 많다. 인테리어도 느낌있고, 수다떨기에도 공부하기에도 좋다. 저녁에 와서 그런지 펍집 같은 느낌이 들기도 한다! 곳곳에 공부를 하는 분들도 보인다. 구석에 전신거울이 있어서 이렇게 전신사진 찍을 수 있지롱 그리고 콘센트가 구석구석 많이 보여서 좋다. 나는 .. 항상 배터리가 부족하기 땜운에^_^.. 여기 케이크 맛있어보인다 ! 담에는 케이크 도전해바야집 ^ㅠ^', 59, 14, 'GOOD', SYSTIMESTAMP);
