INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피덕'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '홍대에 주차 되는 이만한 카페는 더 없는 것 같습니다. 커피도 맛있고 다 좋아요. 헌데 예전과는 다르게 요즘 평일 근무 직원들은 그리 친절하지 않은 것 같아요. 무조건 사근사근할 필요는 또 없지만 말도 약간 쏘아붙이는 식으로 해서 기분이 좋지 않았습니다.', 75, 16, 'BAD', SYSTIMESTAMP);
