INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피덕'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '직접 로스팅하는 커피로 커피맛을 다양하게 즐길 수 있어요ㅎㅎ 그리고 매장 분위기 하나 올리지만 대략적인 느낌 오세요?ㅎㅎㅎ 상상하지마요! 그 이상!ㅋㅋㅋ 직접 보시구요~~~ 메인 카페사진 같이 올려봅니다ㅋㅋㅋ 사장님이 친절하십니다ㅎㅎ', 37, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피덕'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '민초는 뭔가 부족한 맛이었는데 쿠키는 나름 맛있었어요! 매장분들이 친절하세요 ㅎㅎ 평일이 주말보다 사람이 적어서 적당히 조용하니 얘기하기 좋더라구요!', 4, 3, 'GOOD', SYSTIMESTAMP);
