INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피덕'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '친구는 아아 저는 플랫화이트 마셨는데 둘다 고소하니 맛있어요! 커피도 맛있는데 앉아서 공부나 업무하기도 좋은 환경 세팅(콘센트)이어서 좋아요! 홍대입구역과도 가까워서 매우매우 추천합니다~!!', 11, 5, 'GOOD', SYSTIMESTAMP);
