INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피덕'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '번화가에서 드물게 주차공간을 넉넉히 가지고 있는 곳이에요! 주차한다고 말하면 차단기 올려줍니다. 카공족들에게 이정도로 프렌들리한 곳은 정말 드문데 사장님의 배포가 눈에 보여요. 좌석마다 높이도 적당하고 콘센트도 다 구비되어 있어요. 어떤 좌석은 멀티콘센트까지 설치돼있어서 콘센트걱정은 할 필요가 없어욥..! 대단하네요. 그리고 정말 드물게 흡연실도 있습니다. 주차, 카공, 흡연까지 어떻게 봐도 여러모로 대단한 곳입니당..!', 31, 0, 'GOOD', SYSTIMESTAMP);
