INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피덕'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '데이튜하기 좋아용🖤 직원분들도 친절하싲니당💕 카페 거울도 예쁘고 각 인테리어도 깔끔해용 매장두 청결! 책상 넓어서 스터디하기도 꿀입니당 꿀🐽', 22, 3, 'GOOD', SYSTIMESTAMP);
