INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '매장이 정말 깨끗하고 모던해요! 층별로 컨셉이 다르고, 혼자 집중하기도 좋고 조용히 대화 나누기도 좋아요! 말차라떼 러버인데  말차 파우더 베이스라 넘 좋고 컵에 담긴 모양도 진짜 이쁨💚 배경도 너무 이쁜데 비오는 날도 갬성 있어요! 직원분들도 친절하셔서 뷰값+음료맛=느좋 그자체', 47, 1, 'GOOD', SYSTIMESTAMP);
