INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '경의선숲길 산책하다가 큰 카페가 보여 뭔가싶어 호기심이 들었었는데 상호도 호기심 이였더라구요 주차가 넓고 디저트들도 전부 맛있어 보이더라구요 다음에 다른것도 먹으러올게요', 23, 0, 'GOOD', SYSTIMESTAMP);
