INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '위치도 서강대역 바로 앞이고 통창 뷰도 정말 좋네요~~^^ 커피맛도 고급이에요! 조용하게 할일하기 최고입니다! 늘와보고 싶던곳인데 오늘 드뎌와보고 보석 같은곳 발견해서 뿌듯하네요ㅎㅎ', 30, 5, 'GOOD', SYSTIMESTAMP);
