INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '커피랑 밀크티 스콘 다 맛있어요 근데 외부계단을 사용못해요.. ㅜㅜ 엘레베이터는 느린편이고 ㅜㅜ수리중인거같은데 빨리 완료되서 계단이용도 가능했으면 좋겠네요', 72, 16, NULL, SYSTIMESTAMP);
