INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '서강대 신촌쪽 카공카페를 찾으신다면 당장 카페 호기심으로 달려가세요 🙂✨ 카공하기에 아주 딱입니다 자리마다 콘센트도 있어서 너무 편하더라구요 ㅎㅎ 커피 원두도 직접 로스팅하셔서 그런지 커피도 더 맛있어요 ! 제가 마신 산드라피치 음료도 진짜 깔끔하고 맛있더라구요 ! 색도 예쁜데 맛도 있는 음료라니 .. !! 카페 호기심의 신메뉴인 티그레 3종 !! 바삭하고 쿠키같은 식감인데요 단연코 1등은 레몬 가나슈 티그레 입니다 ㅎㅎ 레몬 필링이 듬뿍 들어있어 상큼하고 초코칩 박힌 바짝한 부분이랑 너무 잘어울려요 !! 너무 맛있게 잘 먹고 공부도 잘 되어 집중해서 공부하다가 왔습니다 💖', 70, 11, 'GOOD', SYSTIMESTAMP);
