INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '휘낭시에 맛집이라고 해서 일부러 찾아왔어요ㅎㅎ 평일 낮인데도 벌써 품절된 휘낭시에가 있어서 아쉬웠지만 정말 맛있어요ㅎㅎ 휘낭시에 말고도 다른 디저트도 먹어봤는데 최고🥹🩷 다음에는 친구 데리구 오려구요~!', 25, 5, 'GOOD', SYSTIMESTAMP);
