INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '직원분들도 완전 친절하고 음료랑 빵 다 맛있어요! 휘낭시에는 바삭촉촉하고, 아포카토는 아몬드가 존맛.. 밤슈페너는 밤 맛이 약하긴 한데 그래도 맛 괜찮아요 그리고 뷰랑 인테리어랑 조용함까지..신촌 최고의 카페입니다.', 14, 7, 'GOOD', SYSTIMESTAMP);
