INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '너무 궁금했던 카페였는데 이제야 가봤네요^^ 2~4층까지 매장이 넓고 틀어주는 음악도 작아서 집중하기 좋네요 3층이 특히 더 조용한 것 같아요 바닐라빈 라떼 마셨고, 맛있는 원두 쓰시는것 같아요~ 클래식 휘낭시에는 품절이었는데 다음에 꼭 먹어보려구요~', 28, 2, 'GOOD', SYSTIMESTAMP);
