INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '카페 우연히 방문했다가 단골되서 나갑니다!! 밤슈페너와 산드라피치 시켰는데 음료가 다 고급스러워요 ㅎㅎ 거기에 샤또쇼콜라도 꾸덕하니 최고예요!!', 3, 1, 'GOOD', SYSTIMESTAMP);
