INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '채광이 예쁘게 들어오는 감각적인 공간에, 4층 건물이라 넓고 층마다 좌석도 다양했어요. 대화 나누는 분들, 공부하시는 분들, 책 읽으시는 분들, 어르신부터 학생들까지 누구나 편하게 시간을 보내기 좋은 분위기예요🏞️ ☕️ 과테말라 시그니처 원두로 선택한 아메리카노는 고소하고 깨끗한 맛이 왜 시그니처인지 알겠더라고요. 🍨 아포카토는 미디엄 원두로 마셨는데 부드러운 바닐라 아이스크림을 뚫고 나오는 깊은 원두의 풍미가 최고였어요. 🍑 산드라피치는 달콤하고 시원해서 커피 못 드시는 분들에게 딱입니다. 커피 맛이 확실히 좋아서 디저트와도 찰떡 궁합이에요! 레몬 가나슈와 부드러운 화이트초코 필링이 가득한 티그레의 비주얼이 이뻐서 저도 모르게 담았는데 비주얼만큼 맛있어서 휘낭시에 기프트세트도 하나 데려가요🤍', 40, 7, 'GOOD', SYSTIMESTAMP);
