INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '근처에서 놀다가 디저트맛집 찾아 방문했어요! 층별로 인테리어가 넘 예쁘고, 디저트와 음료도👍👍 티그레가 품절이라 넘 아쉬워서 다음에 또 오려고요ㅎㅎ', 122, 19, 'GOOD', SYSTIMESTAMP);
