INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '서강대역 앞 멋진 카페. 4층에서 보면 전망이 좋네요. 커피맛도 괜찮고 스탭들도 친절한 뷰맛집입니다. 근처에 가면 한번 가보시길.', 48, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '4층까지 건물전체가 카페라 규모가 엄청크네요. 감각적인 인테리어와 존마탱 티라미슈.. 커피도 맛있어요. 경의선숲길 산책하다 들렀는데 다음에도 또 올 듯 합니다. 조용하고 대화하기 좋은 분위기이고 뷰도 예뻐요', 38, 9, 'GOOD', SYSTIMESTAMP);
