INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '신촌사는 지인에게 휘낭시에가 맛있다고 추천받아 선물 구입할겸 잠깐 앉았다 갑니당ㅎㅎ 커피도 휘낭시에도 훌륭하고 카페 안 분위기도 너무 좋네요ㅜㅜ 먼 곳에 사는것만 아니었다면 단골이 되었을텐데 넘 아쉽습니다.. 서강대 학생들 부럽네요ㅎㅎ', 45, 8, 'GOOD', SYSTIMESTAMP);
