INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '카페 분위기 너무 괜찮았어요! 4층전체가 카페라 취향에 따라 편하게 자리 잡을수 있어서 너무 좋더라구요 ㅋㅋㅋㅋ 공부했는데 집중 너무 잘되서 편하게 공부하고 왔어요! 밤슈페너 진짜 맛있더라구요 ㅠ 처음먹어봤눈데 완전 취저 티그레안에 있는 초코 찐하고 빵이 빠삭해서 맛있게 먹고왔어요 ~', 127, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '호기심 : 색다르거나 신기하거나 이상한 일이나 대상에 끌랴 그 정체나 내용을 알거 싶어하는 마음. 카페 이름처럼 매번 길을 지나가다 언젠가 한번쯤 가봐야하지 하고 방문했던곳! 인테리어가 예쁜 곳인지만 알았는데 커피 맛이 일품이었다. 아메리카노 상큼한 원두 추천드려요👍', 37, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '카페 호기심은 디저트 카페로 정말 인정할 만한 맛집이었습니다. 특히 티그레가 아주 훌륭했어요. 인테리어도 세련되고 아늑해서 시간이 가는 줄 모르고 즐겁게 머물렀답니다. 꼭 다시 방문하고 싶어요!', 47, 6, 'GOOD', SYSTIMESTAMP);
