INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '서강대역 2번 출구로 나오면 바로 보이는, 통창이라 낮에도 밤에도 예쁜 카페 방문 ~ 아아부터 다양한 커피 종류들과, non coffee 메뉴들도 많았어요 ! 저처럼 오미자청을 좋아하시는 분들은 산드라 피치 추천드려요 ! ! 그리고 티그레, 휘낭시에, 케이크 등 디저트류도 정말 많답니다. 디저트 뿐만 아니라 커피, 음료도 너무 맛있어서 다음에 또 방문해야겠어요 희희', 50, 7, 'GOOD', SYSTIMESTAMP);
