INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '대형카페에다가 카공하기 딱 좋은 카페 같아요!! 서강대역이랑 가까워서 접근성도 좋았고 무엇보다 치즈케이크가 너무 맛있어요...💛 크림같은치즈케이크 좋아하시는 분들은 꼭 주문하세요...🤤💛', 20, 1, 'GOOD', SYSTIMESTAMP);
