INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '실제로 와보니 생각보다 더 큰 매장!! 내부에 엘레베이터라니 인테리어도 멋있고 직접 로스팅한 원두로 내리는 아메리카노도 고소하고 맛있어요 티그레 신메뉴로 나왔던데 품절이라 못 먹고 바스크 치즈케잌 먹고 갑니다✨ 다음엔 다른 디저트 먹으러 올게요~~~', 27, 1, 'GOOD', SYSTIMESTAMP);
