INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '분위기도 너무 좋고 4층이나 되는 대형카페여서 차분하게 힐링하구 갑니다!!😍 글루텐프리 디저트 맛집이라고 들었는데 바스크 치즈 케이크가 진짜 달달하고 존맛이였어요❤', 60, 16, 'GOOD', SYSTIMESTAMP);
