INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '전에 길가다가 봐뒀었는데 매장도 넓고 자리도 넓어서 좋았습니다. 직원분도 엄청 친절하시고 매장 분위기도 좋고 청결해서 좋았습니다. 매장 음악 선곡도 괜찮고 크기도 적당해서 대화하기도 괜찮고 앉아서 글쓰기도 괜찮네요!', 65, 12, 'GOOD', SYSTIMESTAMP);
