INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '주말에 사람이 많아서 자리먼저 맡고 주문해야해요! 그정도로 이미 소문난 카페ㅎㅎㅎ 디저트 포장도 하나하나 정성스레 해주시고 선물하기 좋을 디저트들도 많더라고용!! 제 원픽은 초코휘낭시에..💛 꼭 드셔보세욤', 12, 8, 'GOOD', SYSTIMESTAMP);
