INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '분위기부터 감성 가득한 카페예요. 커피 맛도 진하고 고소해서, 한 모금 마시자마자 기분이 좋아졌습니다. 디저트도 하나하나 정성스럽게 만들어졌다는 느낌이 들었고, 특히 수제 쿠키는 꼭 드셔보셨으면 해요! 창가 쪽 자리는 햇살이 잘 들어서 여유롭게 책 읽기에도 좋았고, 직원분 모두 친절하셔서 편하게 머물다 왔습니다. 이름처럼, 지나가다 호기심에 들렀다가 단골이 될 것 같아요~', 36, 4, 'GOOD', SYSTIMESTAMP);
