INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '집에서 걸어서 20여분 거리이지만 자주 오게 됩니다. 휘낭시에 맛나구요! 커피는 또 맛있어요!! 요즘은 티그레에 빠졌어요. ^^ 딸기라떼도 맛나고 오미자차도 좋아요 주차장 작지만 2대까지 가능해요.', 51, 13, 'GOOD', SYSTIMESTAMP);
