INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '쾌적하고 친절하고, 맛있어요ㅡ. 엘리베이터 안의 선반 센스! 감동입니다. 커피는 부드러운 산미와 고소한 원두, 디카페인 3종 즁 선택 가능한데 상큼한 커피도 맛있게 먹었어요. 크랙소금빵은 포장했어요.', 24, 10, 'GOOD', SYSTIMESTAMP);
