INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '공간이 이뻣어요~ 커피도 맛있었구요~ 역에서 가까워서 너무 좋아요~ 층마다 엘레베이터 타고 가는데 자리가 많아서 좋았습니다 자주 올거 같아요', 69, 13, 'GOOD', SYSTIMESTAMP);
