INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '매장도 넓고 좌석이 많아서 좋았고 분위기가 미쳤음 ㅠㅠ 인테리어 예뻐서 좋았는데 저녁 되니까 살짝 무드있게 조명 어두워지면서 편안하고 아늑했던 곳 ღ 딸기프레지에 달달하니 짱 맛있고 딸기 듬뿍 들어있음! 커피도 진해서 맛있고 원두 고를 수 있어서 좋았음 또가고싶은 곳🤍', 6, 8, 'GOOD', SYSTIMESTAMP);
