INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '분위기도 맛도 너무 좋아요 말차라떼 정말 고급스러우니 꼭 드셔보세요! 원두도 선택할 수 있어요 서강대역 근처라서 그런지 공부하시는 분들도 많더라고요! 조용하게 집중하면서 디저트와 커피한잔하기 딱입니다 매장도 넓고 엘레베이터도 있어서 편해요 스콘이랑 말차라떼 완전 추천해요💚🤍💚', 31, 9, 'GOOD', SYSTIMESTAMP);
