INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '평소에도 자주가는 신촌베이커리카페 호기심! 오늘은 휘낭시에4종 선물세트와 루이보스 로얄밀크티, 고소한맛 아메리카노를 주문했어요. 임산부라 화장실을 자주가서 디카페인도 줄이려고 하는데 마음놓고 마실 수 있는 루이보스로 밀크티 고를 수 있어 좋았고 남편은 커피 잘 아는데 여기 커피 맛있다고 하더라고요. 커피는 4층에서 직접 로스팅하시고, 베이커리류는 지하1층에서 직접 만드신다고 하더라고요. 크랙소금빵 궁금했는데 제가 간 날은 품절이라 못먹었어요. 빵들도 쌀가루로 만든 글루텐프리 디저트들이 많아서 다이어트 하시는 분들이나 글루텐 알레르기 있으신분들도 편하게 드실 수 있을 거 같아요. 채광 잘되는 통유리창 건물에 4층까지 컨셉마다 다른 인테리어 보는 재미도 있어요. 구경하는재미 맛보는재미까지 있는 카페에요😋👍', 27, 5, 'GOOD', SYSTIMESTAMP);
