INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '요런 신상 카페가 있다니요...💖대형카페라서 카페도 넓고 엘레베이터도 있어서 올라갔다 내려갔다 편하고요! 커피도 넘 맛있고..💖 무엇보다 딸기 디저트가 넘 넘 많아서 행복했다능🍓 그리고 글루텐프리에요!!!!!✨ 이게 젤 제 취향..🤤', 16, 4, 'GOOD', SYSTIMESTAMP);
