INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '독서실만큼 조용하고 차분한 카페에요!! 예쁜 뷰를 보면서 작업할 수 있어서 좋습니다. 자리도 넓고 많아서 카공러들에게는 최고의 장소,,♡ 커피도 맛있고 디저트도 다양해요', 15, 6, 'GOOD', SYSTIMESTAMP);
