INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '보자마자 대박이다하고 먹자마자 더대박이다 했던 바스크치즈케이크 !!!글루텐프리에 제류슈가에요!!!다이어터라면 무조건 대대대강추하고싶은곳 제가 너무 찾던메뉴에요❤️카페는 2,3층이 있어서 자리많고 넓고 창밖도 트여있어서 개방감도 좋고 눈오는날 설경보러 다시갈께요!', 26, 1, 'GOOD', SYSTIMESTAMP);
