INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '매장이 예뻐서 리뷰 보고 방문했는데 너무 예쁘네용 휘낭시에도 맛있고 ~~ 얼그레이 라떼랑 밤슈페너 마샸는데 메뉴도 어디서 잘 보기 어려운 특별한 느낌쓰', 24, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '상큼한 맛의 아메리카노는 산미가 있는 원두로 적당한 산미입니다. 넛츠휘낭시에는 견과류가 설탕조림화되어 단맛이 강한 편입니다. 2~4층까지 통창으로 되어있어 좋습니다.', 7, 5, 'GOOD', SYSTIMESTAMP);
