INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '진짜 조용하고 분위기 좋은 카페를 발견했어요 !!! 4층까지있어서 엘리베이터 이용으로 쉽게 층층마다 분위기를 다르게 즐기다가 왔다구요 아메리카노랑 얼그레이밀크티 티라미슈 주문했구요 음료와 디저트까지 완벽하네요 신촌 조용하고 분위기 좋은 카페를 찾는다면 여기가 딱이예요', 102, 25, 'GOOD', SYSTIMESTAMP);
