INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '딸기밀크티 정말 너무 맛있어서 놀랐어요💕💕 좌석도 너무 편하고 넓어서 카공하기 정말 좋아요!! 오랜 공부하고 왔는데 힐링 되었어요,, 바스크치즈케이크 다이어트용으로 제로슈가라던데 대체당 맛이 나긴했는데 다이어터에게는 감사한 케이크였습니당🥹 아메리카노랑 먹으면 그냥 일반 바스크치즈케이크에요!! 행복한 시간 보냈습니당', 120, 26, 'GOOD', SYSTIMESTAMP);
