INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '신촌에 이렇게 커다란 카페가 있는지 몰랐어요... 분위기도 좋고 커피랑 디저트도 맛있네요! 카공하기도 좋은 것 같아요 다음에 또 방문할 것 같아요🤗♥️', 19, 4, 'GOOD', SYSTIMESTAMP);
