INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '서강대,연대근처에 이렇게 큰 카페가 있다니!! 서강대역,신촌역과 가깝고 통창이라 뷰도 좋아요 1층에서 주문하고 2층에 이쁜 창가자리에서 힐링했습니다 그리고 휘낭시에 진짜 너무 맛있어요😊 넛츠,얼그레이,레몬,기본 맛 먹었는데 친구랑 흡입했습니다! 세트 포장패키지도 너무 예뻐요 남으면 싸갈려고했는데, 카페에서 다 먹었어요ㅋㅋ 그만큼 맛있고, 겉바속촉의 끝판왕입니다 아메리카노, 오미자에이드도 시원하고 맛있어서 휘낭시에랑 잘어울렸어요💜 담에 또 오고싶어요ㅎㅎ 분위기도 좋고 인테리어도 이쁜데 진짜 맛있어요🤗', 70, 14, 'GOOD', SYSTIMESTAMP);
