INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '모던하고 고급진 분위기!! 카페안에 엘베가 있어 놀랐어요😁 그만큼 큰 대형카페였는데 인기많은 핫플이더라구요^^ 디저트, 음료. 모두 맛있었고 특히 제가 커피 잘못 먹으면 그날 밤에도 잠을 잘 못자서 너무 힘든데...ㅠㅠ 여기서 커피 마시고는 아무 지장이 없어서 너무 좋았어요 ^^ 디저트 종류도 맛있어서 그쪽 갈일 있으면 자주 들릴듯해요~!', 89, 16, 'GOOD', SYSTIMESTAMP);
