INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '집 근처에 생긴 카페인데, 4층 건물을 통으로 쓰는 대형카페에요. 바로 앞이 경의선숲길이라 산책 나왔다 들렸는데, 매장 분위기도 좋고 바깥뷰 보며 차마니기에도 좋네요. 매장에서 직접 로스팅을 하고 있어 커피도 맛있는데 디저트도 맛있어요. 여긴 커피 생각날때마다 가고픈 곳!!', 50, 5, 'GOOD', SYSTIMESTAMP);
