INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '커피면 커피, 밀크티면 밀크티, 휘낭시에면 휘낭시에 하나도 빠짐없이 정말 맛있는 맛집이네요! 커피맛도 좋고 빵도 글루텐 프리라 먹어도 속이 편하고 고급스런 포장으로 선물도 할 수 있고, 대형카페라 쉬기도 넘 좋아요!!', 59, 12, 'GOOD', SYSTIMESTAMP);
