INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '산미있는 커피를 좋아하는데 원두를 고를 수 있어서 좋았어요☺ 말차라떼랑 티라미스도 정말 맛있었습니다 대형카페라 좌석이 많았어요 통창이라 뷰가 탁 트였고 인테리어와 분위기가 느낌있고 좋아요 서강대역 바로 앞이고 홍대랑 가까워서 방문하기 좋네요', 11, 8, 'GOOD', SYSTIMESTAMP);
