INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '신촌 근처 카공하거나 재택근무하기 너무 좋은 대형카페입니당!! 분위기도 너무 좋궁 베이커리 메뉴도 가득가득해서 무조건 재방문 의사 백만프로!!💗💗 1. 신촌 근처 카공할 곳 재택근무할 곳 찾으시는 분들 2. 신촌 대형카페 찾으시는 분들 3. 경의선 숲길 인근 카페 찾으시는 분들', 112, 23, 'GOOD', SYSTIMESTAMP);
