INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '서강대역 근처에 대형 카페가 있다고 해서 다녀왔습니당 ㅎㅎ 전체적으로 넓고 쾌적해서 좋았고, 커피 원두 3가지 중에 고를 수 있게 되어 있어 원하는 맛 초이스 가능한 점도 좋더라구요~ 대표로 휘낭시에를 두고 있는데 개인적으로 저희 커플은 시나몬 휘낭시에가 정말 맛있더라구요! 나갈때 포장 하고 싶었는데 늦은 시간이여서 품절이라 다음에 방문 할때는 꼭 사오려구요^^ 공부할 수 있는 공간도 있고 사진 찍을 수 있게 인테리어도 예뻐서 사진 건지기도 좋았습니다 ㅎㅎ 가까운 곳에서 이런 공간의 카페를 이용할 수 있다는 점이 너무 좋습니다! 꼭 추천드려요 ♥︎', 74, 18, 'GOOD', SYSTIMESTAMP);
