INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '신촌 한복판에 엘베가 있는 4층 대형카페라니 층별로 컨셉이 달라서 테이블과 의자도 다르니까 자연스레 분위기도 달라여 커피 원두도 고를수 있고 베이커리류도 맛있어서 강추합니다 로스팅 카페라 원두맛도 신선해서 커피가 맛있있어요 기분전환하며 공부하기도 좋고 대화하기도 좋아 힐링하다 갑니다', 49, 0, 'GOOD', SYSTIMESTAMP);
