INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '서강대역 3분 거리에 있는 4층 대형카페에 갔어요. 실내 인테리어가 이쁘고 스터디 하기 좋은 조용한 카페였어요. 아메리카노 고소한맛으로 주문했는데 향이 고소하고 쓰지않고 신맛도 나는듯하고 휘낭시에랑 먹으니 너무 고소하고 맛있었어요. 미숫가루, 초코 섞인 음료도 아침에 먹으니 든든하게 맛있더라구요. 너츠 휘낭시에 바삭하고 고소하고 정말 맛있었어요. 추천해요❣️꼭 아메리카노랑 같이 드셔보세요👍🏽👍🏽👍🏽👍🏽👍🏽', 40, 9, 'GOOD', SYSTIMESTAMP);
