INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '이번에 처음 가본 카페인데 커피랑 음료가 정말 맛있었어요! 티그레랑 휘낭시에도 같이 먹으니까 궁합도 좋았구요 매장이 깔끔하고 창밖 뷰도 좋아서 다음에도 또 올게요오~~', 47, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '뷰맛집 ㅎㅎ 항상 지나다니다가 가봐야지 가봐야지 하다가 오늘 방문 했는데 디저트 종류도 다양하고 커피도 넘 맛있어용!! ㅎㅎ 티그레 먹고싶었는데 벌써 품절..또르륵 담엔 티그레 먹으러 또 방문 해야 겠어욤', 50, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '매장분위기 넘나 좋구요 쌀가루로 만든 글루텐프리 휘낭시에와 고소한 아메, 오미자 음료까지 넘나 완벽했어요 원두도 취향 따라 고를 수 있고 디저트도 종류가 다양해서 방문할때는 뭘먹을지 미리 생각해 오는게 좋을것 같아요! 왜냐면 다 먹고 싶으니까.....❤️ 사색하기 좋은 건강한 브런치 맛집 휘낭시에 진짜 맛있음..겉은 바삭 속은 쫀득 아주 굿입니다 직원분들 친절은 디폴트, 매장 깨끗하고 커피 맛있고 안가고 모하세요 얼른 가세요', 7, 5, 'GOOD', SYSTIMESTAMP);
