INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '친구랑 예약하고 방문했어요 딸기케익도 맛있고 라떼도 맛있었어요~ 딱 트인 전망보면서 멍 때려도 좋은곳ㅡ노트북 들고 일하기도 좋은곳ㅡ 책 읽기에도 좋은곳^^ 신촌서강대역 부근이면 꼭 방문해보세요~~', 34, 2, 'GOOD', SYSTIMESTAMP);
