INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '신촌에서 집중할 카페 찾고 있었는데 우선 자리가 많아서 좋고 집중이 잘되요! 인테리어도 너무 예쁘고 뷰도 좋고 자주 오고 싶어요^^', 28, 7, 'GOOD', SYSTIMESTAMP);
