INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '밤 슈페너같은 특별한 메뉴도 있고 매장도 완전 넓어서 시간 보내기 정말 좋은 카페입니다! 바스크 치즈케익도 너무 부드럽고 맛있었습니다! 작업, 데이트, 공부 다 잘 어울리네요.', 50, 4, 'GOOD', SYSTIMESTAMP);
