INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '오랜만에 또 방문! 크리스마스선물용으로 휘낭시에4구포장해갖고 갔는데 맛있네요💕 글루텐프리라 걱정없고, 대형카페 인테리어 멋있고, 좋네요😃👍🏻', 32, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '와 여기 진짜 휘낭시에 맛집이에요. 디저트를 당일생산 하신다고 하셨는데 휘낭시에 완전 바삭하고 속은 촉촉해서 끊임없이 들어가는 맛입니다. 저는 앉은 자리에서 쑥휘낭시에랑 너츠휘낭시에 순삭하고 선물용으로 휘낭시에 세트 포장했어요👍 카페 호기심오시면 꼭 휘낭시에 맛보세요. 또한 글루텐프리라 다이어트할 때도 완전 강추😊', 23, 8, 'GOOD', SYSTIMESTAMP);
