INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '4층으로 된 큰 규모의 까페인데 4층에서는 로스터리를 같이 하고 있는 것 같았어요. 적당한 산미가 있는, 풍미있는 아메리카노와 밀크티를 마셨는데 커피도 맛이 있지만 밀크티도 맛이 진해서 좋았어요. 손님들이 꽤 많았는데 거의 휘낭시에 사시는 것 같아서 저도 나중에는 휘낭시에 먹어보고 싶더라고요', 11, 0, 'GOOD', SYSTIMESTAMP);
