INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '커피도 맛있고 카페내부건물이 엄청 넓고 커서 자리선정하기도 넘 좋았어요🥰 특히 휘낭시에세트는 선물용으로 너무 좋을것 같더라구요 !! 글리텐 프리제품이라는데 맛이그냥 시중에파는 휘낭시에맛이랑 똑같아서 먹으면서 놀랐어요 ㅎㅎㅎ 다이어터분들께 선물해줘도 좋을듯,, 💘', 124, 22, 'GOOD', SYSTIMESTAMP);
