INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '공사할때부터 저기는 뭐가 생기려나 되게 궁금했는데 너무 예쁜 카페가 생겼더라구요🥹 그래서 경의선 숲길 산책할 때마다 꼭 방문해보고 싶었어요! 건물을 통으로 쓰니까 넓고 쾌적하고 인테리어도 너무 예뻤어요 ㅎㅎ 쉬폰케이크, 프리미엄 로얄 밀크티 루이보스, 아이스 아메리카노 이렇게 세 가지 주문했는데 다 맛있었어요!  4층에서 직접 로스팅하는 원두라더니 커피도 너무 맛있었고 밀크티도 향긋하고 케이크도 촉촉 폭신 달달하니 맛있었습니다🥰', 18, 1, 'GOOD', SYSTIMESTAMP);
