INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '신촌에 이렇게 예쁘고 깔끔한 대형 카페가 생겨서 너무 좋네요. 사진 순서대로 1층 2층 3층 4층인데 2층 사진이 두장인 이유!! 2층 인테리어가 진짜 너무 예뻐요 사진 맛집입니닷. 근데 커피랑 휘낭시에도 맛있어요. 지하1층을 투명창으로 하기 쉽지 않은데 베이커리를 하는 지하1층을 이렇게 오픈하는건 그만큼 자신 있으시다는 거니깐 더 믿음이 가더라구요. 그리고 직원분들도 다 커피에 진심이셔서 메뉴 설명도 너무 잘해주셨어요. 요즘 글루텐프리가 핫하잖아요 건강하게 맛있는 휘낭시에는 선물포장도 고급스러워서 선물하기 너무 좋을 것 같아요. 8종의 휘낭시에가 있으니 선택의 폭도 다양해서 좋답니다. 분위기 맛집 커피맛집 휘낭시에 맛집 카페 호기심 너무 맘에 들어요!!', 10, 6, 'GOOD', SYSTIMESTAMP);
