INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '커피도 맛있고 디저트도 맛있어서 만족스러웠어요 디저트 종류도 다양한데 다 맛있더라구요 층마다 분위기도 달라서 기호에 맞게 선택해서 가면 좋울 거 같아요', 8, 0, 'GOOD', SYSTIMESTAMP);
