INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '우선 매장이 넓어서 너무 좋아요 ~ 노래가 세련되게 나오네요 ㅋㅋㅋ 인테리어랑 잘 어울려요. 커피도 고소하고 싱싱한 딸기가 있는 케이크도 달달하니 최고입니다 ㅎㅎ 서강대 오가가다 오기 굳 ~', 34, 1, 'GOOD', SYSTIMESTAMP);
