INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '분위기도 너무 좋구 겉바속촉이면서 버터풍미 가득한 달달한 티그레 너무 맛있구요~ 스트로베리밀크티, 아포카토도 맛있는 데 특히 아포카토에 견과류가 들어가 있는 데 조합이 너무 좋아요👍🏻', 4, 0, 'GOOD', SYSTIMESTAMP);
