INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '호기심 카페, 호기심에 오게된 카페인데 입이 수지맞았습니다 특히 휘낭시에랑 커피 맛 뭔가요,, 휘낭시에 맛집 중에 최고임 ㅠㅠ진짜 말이 안 되는 촉촉함과 빠삭함이에요 🥹 신촌에서는 제일 맛있고(장담함) 서울 내에서도 다섯 손가락 안에 드는 휘낭시에 찐. 여기에 브런치로 엄선하여 준비해 주신 닭가슴살 샌드위치랑 디카페인 아메리카노 먹었는데,, 걍 한 번 오면 단골돨 듯. 서강대역이랑 거의 이어져있다시피 가까워서 위치도 좋고 매장 각 층마다 컨셉도 있어서 통창에 은은한 자연광이랑 스터디, 공부하기도 좋고 여유롭게 쉬기도 제격이에요 깔 게 없는 찐맛 + 서비스도 채고👍🏻🌼✨', 21, 5, 'GOOD', SYSTIMESTAMP);
