INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '카페가 예상했던 것보다 너무 예뻐요💙1층 주문하는 곳도 세련됐는데 2,3,4층 각각 느낌이 다 달라요! 아아랑 말차라떼 둘 다 맛있고 원두 선택할 수 있어서 좋아요! 그리고 휘낭시에 중 쑥맛 먼저 먹었는데 꾸덕하고 쫄깃해요! 빵부분은 단데 쑥크림이 달지 않아서 그 조합이 딱이에요!!!🌿👍🏻👍🏻', 97, 23, 'GOOD', SYSTIMESTAMP);
