INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '생딸기 프레지에 보틀 케이크는 쌀가루로 만든 글루텐 프리 케이크라 그런지 좀 더 부드러웠고, 딸기로 달달하니 맛있는 딸기 였어요 커피들은 직접 로스팅한 원두라 그런지 더 고소하고 깔끔한 맛이었어요! 주문할 때 원두도 고를 수 있답니다 ◡̈', 36, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '카페호기심 좋다는 이야기는 많이 들었지만 직접와서 보니 글루텐프리 휘낭시에  너무 맛있고 4층 건물 전체가 다 카페여서 층별로 특색이 있으면서 고급스럽고 편안함이 함께 하는 곳이라 아주 마음에  드네요', 37, 0, 'GOOD', SYSTIMESTAMP);
