INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '깔끔하고 예쁜 카페에 맛있는 디저트까지 있는 곳이에요! 음료도 다 너무 맛있고, 사진도 잘 나와요 ㅎㅎㅎ 신촌 오면 꼭 들러야 하는 분좋카🩷', 39, 4, 'GOOD', SYSTIMESTAMP);
