INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '라떼 마시고, 맛있어서 아메리카노와 에그쉬폰산도 추가 주문했습니다! 공간도 넓고 쾌적한데다 인테리어도 멋져요~ 에그쉬폰산도 촉촉하고 맛있네요~ 무엇보다 목발 사용하는 상태로 방문했는데 자리까지 가져다 주시고 너무 친절하세요 :)', 8, 2, 'GOOD', SYSTIMESTAMP);
