INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '와 카페가 통건물이에요! 인테리어 세련됐고 직원분들도 친절하고 층마다 분위기도 달라서 카공하기도 좋고 이야기나누기도 좋음!! 무엇보다여기 휘낭시에 존맛임!!!!✨👍🏻', 115, 19, 'GOOD', SYSTIMESTAMP);
