INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '오 동네에 이런 카페가 생겼다니 넘 좋아요~ 노트북 작업할 일 많은데 딱이겠어요! 그리고, 디저트 휘낭시에도 쑥휘낭시에 맛봤는데 넘 맛있네용 ㅎㅎ 바스크 치즈케이크도 먹어봐야겠어요', 55, 13, 'GOOD', SYSTIMESTAMP);
