INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '퇴근하자마자 궁금해서 달려간 카페~~ 배고파서 이것저것 시켜먹어봤다! 저녁에 가서그런지 분위기있고 미초, 휘낭 슈페너 그리고 케이크 쉬폰 소금빵 다 너무맛있어서 놀램...진짜 여긴 잘되겠다 싶었다. 직원분들도 너무친절하시고 매장도깨끗하고 왜 사람이많은지 알겠어요. 굳굳 또갈게요~~♡', 85, 14, 'GOOD', SYSTIMESTAMP);
