INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '경의산 숲길 옆에 4층 베이커리 카페라니! 너무 좋고 바깥 구경하면서 힐링 하고갑니다. 커피도 맛있고 밀크티 좋아하시는 분들은 밀크티 추천입니다🎶 쌀로 만든 휘낭시에 첨 먹어봤는데 맛있네요😘', 3, 6, 'GOOD', SYSTIMESTAMP);
