INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '층마다 뷰도 다르고 인테리어 분위기도 달라서 취향에 맞게 선택가능한게 좋아요 4층이 조용하고 음악도 듣고 굿 얼그레이카페라떼 생각보다 마니 달아요 커피맛이 마니 안느껴져서 밀크티느낌 샌드위치 맛도 쏘쏘', 76, 17, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '건강하면서 맛있는 디저트 찾기 어려운데 글루텐프리,슈가프리 디저트인데 일반 디저트랑 차이가 없을 정도로 너무 맛있었어요,,,👍🏻 베이커리랑 디저트 종류도 다양하고 포장 패키지도 예뻐서 구움과자 선물하기도 좋을 것 같은 곳입니다🎁 그리고 대형카페라 층마다 분위기가 달라서 수다 떨기도 좋고 카공하기에도 좋은데, 특히 2층이 넓은 쇼파 자리도 있고 감각적인 전시 공간 느낌이라 분위기가 너무 좋았어요🪨🌌 대형카페라 자리가 넉넉하고 심지어 엘리베이터도 있어서 편해요! 그리고 전체 층 모두 통창으로 탁 트여있어서 밤에 방문했을 때 야경뷰가 좋았고 낮에 오면 햇빛 잘 들어서 예쁠 것 같아요🍀 맛있는데 직원분들도 전부 친절하시고 위치도 좋아서 자주 방문할 것 같습니다🥺', 1, 10, 'GOOD', SYSTIMESTAMP);
