INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '잠깐 시간 때워야 해서 방문했는데 기대 이상으로 만족 했던 곳이에요ㅎㅎ 우선 1~4층 층까지 통창뷰를 즐길 수 있는 게 정말 좋았구요,, 카페 내부도 쾌적했어요. 무엇보다 직원 분들께서 정말정말 친절하셨던 게 되게 인상깊었습니다! 커피도 맛있었구용 가격도 괜찮았습니다~~ 또 가고 싶어요!!', 60, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '서강대역 근처에 이쁜 대형카페가 생겨서 너무 좋아요 경의선숲길, 신촌이랑도 가깝고 넓고 쾌적해서 야외바라보면서 힐링하기도 좋네요 디저트 맛집으로 유명하던데 글루텐프리 휘낭시에 들도 많고, 다양한 샌드위치들도 있어서 브런치먹기 좋은 것 같아요! 집근처에 있어서 더 이용하기 편하네요 4층인데 층층마다 매장 분위기도 다양하고 커피랑 빵을 직접 내려서인지 커피, 음료, 디저트 종류 전부 맛있더라구요!! 다음에는 브런치 먹으러 와야겠어요 휘낭시에 시나몬, 얼그레이, 쑥주문 아메리카노, 오미자 에이드 주문했는데 메뉴가 전부 맛있어요 그래도 쑥 휘낭시에가 가장 맛있더라구요!! 포장도 되서 가끔 포장해서 집에서 먹거나 선물해도 좋을 것 같아요!!', 32, 6, 'GOOD', SYSTIMESTAMP);
