INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '전체 건물이 카페인데요 층마다 인테리어 너무 이쁘구요 음악도 조용하고 3층은 집중하기 좋은 분위기라 공부하러 오기도 좋고 작업하러 혼자 오신 분들도 많더라구요 ㅎㅎ 전 층 통창으로 되어있고 뷰가 좋아서 밖에 보면서 힐링했어요 의자도 너무 편해서 좋았어요 자리도 넓게 떨어져 있어서 완전 마음에 듭니다 커피도 직접 위에서 로스팅 하시더라고요 에스프레소 강추! 너무 맛있어요 그리고 디저트도 글루텐프리에 휘낭시에 완전 쫄깃하고 말차쉬폰케이크도 부드럽고 달지않아 좋아요! 카페도 너무 마음에 들고 커피 마시고 맛있어서 주문 한번 더 해서 2잔씩 마시고 디저트도 2번 먹고 나왔습니다 ㅎㅎㅎ 단골 예약입니다 ㅎㅎ', 90, 13, 'GOOD', SYSTIMESTAMP);
