INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '일단 할말이 너무 많은데여 추천키워드 5개밖에 못고르는게 너무 아쉬워서 더 추가하고 싶은 키워드 적어볼게여 일단 디저트 음료 기본으로 맛있고여 대형카페라 층별로 분위기가 달라요 2층은 친구들이랑 모임용 3층은 작업용 4층은 .. 프라이빗? 4층은 잘 모르겠네요 .^◡^. 그리고 매장 인테리어도 멋지고 힙하고 .. 채광도 잘들어오고 .. 신촌역 서강대역 근처 최고의 카페, 추천합니다.', 26, 4, 'GOOD', SYSTIMESTAMP);
