INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '서강대 근처에 이렇게 거대하고 이쁜 카페가 있을거라고 생각도 못했습니다!😀 우선 카페 디자인이 너무 힙하고 이뻐서 모든 사진이 이쁘게 나올 수 밖에 없구요! 🥹🥹 음식도 이뻐서 음식샷만 잘 찍어도 성공적입니당. 근데 휘낭시에 맛집인가봐요!!! 휘낭시에가 맛까지 너무 좋으니까 오늘 완전 잘온거지 여기!!! 또 자리도 많고 넓은 자리에 혼자 공부 할 수 있는 자리까지!! 서강대 학생들 부럽당!!!😂😂😂', 36, 10, 'GOOD', SYSTIMESTAMP);
