INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '입구에서부터 규모와 통창 인테리어에 놀라고~ 내부 인테리어도 넘넘 고급스럽고 엘리베이터가 있어서 층간 이용도 넘 편리했어요~~ 아메리카노와 초코라떼, 딸기케이크 모두 맛있었어요~!!9살딸과 같이 갔는데 자극적이지 않은 건강하게 맛있는 맛이라 안심하고 즐길수 있었답니다~~3층에 잠깐 있다가 4층으로 이동하여 차마셨는데 층마다 분위기가 달라서 신기했어요~ 다음에 근처오면 또 들러야겠어요♡', 62, 18, 'GOOD', SYSTIMESTAMP);
