INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '신촌 디저트 카페 호기심🤎 경의선숲길뷰로 여유로움을 즐기기에도 좋고 대화하기에도 좋았어요 ㅎㅎ 음악도 잔잔하니 너무 조용하지도 시끄럽지도 않게 딱 좋더라구요🩷 무엇보다 기대됐던 휘낭시에가 완전 기대 이상!!! 할미입맛 사로잡은 쑥 휘낭시에 완전 취저💚 너츠는 품절이라 못 먹은게 넘 아쉬웠다요😭ㅠㅠ 다음에 또와서 꼭 먹을거에요! * 이 글은 업체로부터 식사권만을 제공받아 직접 체험 후 솔직하게 작성한 글입니다.', 0, 3, 'GOOD', SYSTIMESTAMP);
