INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '서울에서 이정도 크기의 대형 카페 찾기힘드랑요 메뉴도 강추입니더 다들 맛있어해요 가족들과 오기좋아요 저희집 애기도 좋아하네요 ~', 75, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '서강대 근처에 이렇게 큰 멋진 대형카페가 생긴게 너무 좋네요! 안에 인테리어도 너무 멋지고 좌석도 많아 좋은데 음로도 맛있고 디저트 종류도 많아서 힐링되더라구요', 16, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '집중하기 좋은 공간 드립 커피가 없는게 아쉽지만 커피는 마실만 하고 휘낭시에가 맛나다 디카페인 커피도 있고 뷰만 맛집 아닌 뷰도 맛집 이른 오전 야외 캠핑 의자에 쏟아지는 볕의 온기가 좋다', 25, 2, 'GOOD', SYSTIMESTAMP);
