INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '매장 층마다 인테리어 테마가 달라서 마움에 드는 층에 앉는 재미가 있어요. 전 에그쉬폰산도랑 오미자에이드 먹었는데 달걀향나는 쉬폰시트에 에그+할라피뇨+씨겨자+바질이 샌드 되어있어서 익숙한 듯 신선한 맛의 샌드위치라고 느껴집니당:)', 8, 5, 'GOOD', SYSTIMESTAMP);
