INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '서강대역 2번 출구 앞이라 접근성 너무좋고 쫀득한 까눌레랑 커피 너~무 맛있어요!! 1층에서 주문하고 엘리베이터를 타고 올라가면 2층,3층,4층공간에서 커피를 마실수 있습니당 (스터디도 가능)ㅎㅎ 통창으로 되어있어서 뷰가 너무 좋아요!ㅎㅎ', 1, 2, 'GOOD', SYSTIMESTAMP);
