INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '음료는 생각보다 그냥 그랬고 디저트는 생각보다 많이 맛있었어요. 매장이 큰데 테이블이 따닥따닥 붙어있지 않아서 굉장히 쾌적하고 좋아요. 1-2인 뿐 아니라 단체 모임하기에도 괜찮은 거 같아요👍🏻', 15, 7, 'GOOD', SYSTIMESTAMP);
