INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '서울에 이렇게 큰 대형카페가 있다라니 너무 좋아요. 주차도 편리하고, 건물 내부에 전용 엘리베이터도 있어서 좋구요. 커피는 로스터리 카페 답게 신선한 맛이 좋았습니다. 바스크치즈케이크는 글루텐 프리라서 부대낌이 적어서 더 맛있었어요. 서강대 주변에서 좋은 카페 하나를 찾은 것 같아서 좋습니다.', 17, 8, 'GOOD', SYSTIMESTAMP);
