INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '커피가 맛있어 자주 방문하고 있어요! 생딸기프레지에 먹어봤는데 딸기는 싱싱한데 케이크 부분은 설탕이 씹히는거 같이 너무 달아서 좀 그랬습니다. 휘낭시에는 맛있어요!', 102, 23, NULL, SYSTIMESTAMP);
