INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '경의선숲길에 있는 큰 카페에요! 휘낭시에도 있고 소금빵도 있고 디저트가 다양하네요:) 무엇보다도 좌석이 다양해서 좋아요! 야외에 캠핑의자에 앉아서 있어도 좋아요!!', 50, 7, 'GOOD', SYSTIMESTAMP);
