INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '제가 글루텐 알레르기가 심한 편이라 글루텐을 조금만 섭취해도 바로 증상이 나타나는데 여기서 먹은 바스크치즈케이크는 정말 맛있고 부드럽더라구요!! 글루텐에 대한 반응도 하나도 없어서 믿고 편하게 먹을 수 있었어요🥹✨ 글루텐프리 디저트집을 가면 맛을 포기하는게 대부분인데 너무 맛있어서 단골집으로 탕탕! 다음번에는 휘낭시에를 잔뜩 포장해갈까 싶어요 💖 글루텐프리 맛집 찾기 어려운 요즘 집 가까운 곳에 맛집을 알게되서 넘넘 행복하고 기뿌네요🥹✨ 매장도 4층까지 있어서 자리 없을 것 같다는 걱정도 하나 안하고 와도 되서 더 맘에 들고 좋아요 ☺️🍀🥹 커피에도 프랄린이 함께 나왔는데 프랄린도 많이 달지 않고 담백하게 맛있었어요! 딸기라떼도 딸기청(?)같은 알맹이가 큼직해서 더 좋았네용💖💖', 287, 95, 'GOOD', SYSTIMESTAMP);
