INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '깔끔하고 모던한 건물부터 다양한 내부 인테리어 공간 다양한 종류의 디저트와 퀄리티 세심한 친절함까지 호텔 라운지 못지 않은 카페! 아메 커피는 종류 초이스 가능 하고 깊고 묵직하니 맛있어요 글루텐프리 휘낭시에도 고급스럽고 포장이 잘 되어서 예약 후 선물로도 추천합니다 :):) 샌드위치 종류도 다양한데 메뉴 하나하나 정성스러워요!! <본 업체에서 제품 및 서비스를 제공받아 직접 체험한 후 작성된 솔직한 리뷰입니다>', 37, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
