INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '신촌 도심에 이렇게 쿨하고 힙한 대형카페가 있다니..! 넓고 시원하고 쾌적한 내부에, 조용히 책읽기도 노트북하기에도, 친구들과 수다떨기에도 너무 좋은 장소였어요…❤️ 경의선 숲길이 쫙 펼쳐지는 도심 뷰로, 이 곳에 카페를 차리신 사장님이 천재적이라는 생각을 했네요 ㅋㅋ 특히 디저트는 글루텐프리로 만들어져 관리하시는 분들이 오기에도 너무 좋을 것 같아요. 밀가루를 사용하지 않았지만 그 어떤 디저트보다 맛있어요. 치즈케이크도 묵직-하니 완전 딱이었음 👍 커피도 디카페인이 있어 좋았고 요즘같은 여름날 시원한 오미자차도 정말 딱이네요❤️ 혼자서도 종종 찾을 것 같은 카페에요!', 23, 7, 'GOOD', SYSTIMESTAMP);
