INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '집근처에 새로생긴 카페로 우연히 왔는데…. 맘에 듭니다! 일단 분위기. 인테리어. 예쁘구요…. 커피잔도 감성있네요. 경의선숲길 매일같이 산책하는데 포인트 적립도 마니해주네요^^ 자주올거같아요~~ 요런카페 조아요~~ 조용해서 더조아요', 6, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '우선 빵맛이 좋아서 샌드위치 엄청 맛있구요. 잠봉햄과 버터의 조합으로 특별한 소스 없이도 단짠을 느꼈습니다. 버터 양이 혜자여서 여기 카야버터샌드 존맛일 거 같아요. 담엔 이걸 먹어보리 .. 미초 스무디는 태어나서 첨 먹어보는데 배도 부르고 조합이 넘 좋아요. 여기 시그니처 음료인듯', 47, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '두 번째 방문한 곳 이번에는 밀크티와  바스크 치즈 케이크로 주문! 밀크티는 부드럽고 깊고 진한 느낌이라 좋았고요 바스크 치즈 케이크는 꾸떡한 느낌의 진한 맛 치즈 케이크 좋아하는 분들은 여기 바스크 치즈 케이크 추천해요! <본 업체에서 제품 및 서비스를 제공받아 직접 체험한 후 작성된 솔직한 리뷰입니다>', 100, 26, 'GOOD', SYSTIMESTAMP);
