INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '경의중앙 서강대역 바로 근처에 위치해 있는 카페 호기심 신촌과 광흥창 그 사이길에서 만날 수 있는 호기심 B1층부터 4층까지 운영이 되고 있는 대형카페 B1층과 4층은 직원분들이 작업 하는 공간 1층은 오더를 하는 공간으로 2층과 3층만 내부에 앉아 즐길 수 있다. 벽면은 모두 통창으로 되어 있어 답답함 없이 편하게 공간을 즐길 수 있다. 한 쪽은 서강대로 가는 다리가 바로 있어서 지나는 사람들과 아이컨택도 하고👀 옆은 초록한 숲 뷰를 즐길 수 있다🌳 학교들이 많은 동네에 오픈을해서인지 각 좌석마다 코드가 준비 된 좌석도 많이 보였다. 그만큼 이미 자리에 앉아 노트북으로 공부나 작업 하는 손님분들👨🏻‍💻 커피도 맛있고, 디저트가 정말 맛있었다고 가성비 갓성비 더 자세한 정보는 최제로 블로그🙇🏻‍♂️🌼', 341, 63, 'GOOD', SYSTIMESTAMP);
