INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '분위기와 인테리어 의자 테이블 모두 좋았지만, 가장 좋았던 것은 브런치 샌드위치와 바치케가 넘넘넘 맛있었네요~ 바치케는 노밀가루 노설탕이라는게 믿기지 않을 정도였어요~ 그리고 에그쉬폰샌드는 진짜 꿀맛이었네요♡ 신촌 샌드위치 맛집, 브런치 맛집 등극입니당ㅎㅎ 또 먹으러 갈게요~ 번창하세용', 26, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '우연히 찾은 카페인데 호기심 의미도 좋고 카공하거나 친구랑 소소하게 이야기 떨기 너무 좋네요 :) 자주 오고싶어요 휘낭시에 취향저격입니다.', 31, 1, 'GOOD', SYSTIMESTAMP);
