INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '커피도 완전 맛있고 빵도 다 맛있어요! 테라스랑 1층은 강아지랑 갈수 있어서 좋고 4층까지 있는데 전층 모두 인테리어 멋집니다 추천추천🤍', 38, 1, 'GOOD', SYSTIMESTAMP);
