INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '글루텐프리 휘낭시에 진짜 너무너무너무 맛있어서 재방문했어요🥹❤️4층규모라 자리도 많고 탁트인 뷰를 신촌에서 느낄수있다니 너무 좋더라구요👍', 73, 15, 'GOOD', SYSTIMESTAMP);
