INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '커피랑 디져트가 너무 맛있어요 휘낭시에 겉바속촉 완전 맛있어요 1층은 주문 2.3.4층이 있는데 인테리어도 너무 멋있고 통창으로 뷰도 너무좋아 사람도 엄청 많아요~ 조용하게 대화하기 너무 좋습니다. 또 방문 찜입니다', 40, 1, 'GOOD', SYSTIMESTAMP);
