INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '매장이 4층까지 있어서 모임으로 오기에도 좋고 공부하러 오기에도 좋은 곳이였오요!! 디저트도 진짜 맛있고ㅠㅠ 커피도 너무너무 맛있어요!! 분위기 좋고 넓은 카페 찾으신다면 추천드릴게요', 7, 1, 'GOOD', SYSTIMESTAMP);
