INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '커피 정말 맛있고,, 뷰가 진짜 좋은 카페에요!! 주말 오전에 가면 정말 평화로움 그 자체ㅠㅠ 디저트도 먹어 봤는데 맛있네요ㅎㅎㅎ', 107, 20, 'GOOD', SYSTIMESTAMP);
