INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '역세권! 서강대역 대형카페가 생기다니!검색해보니깐 직접 로스팅한 원두와 브런치 메뉴, 다양한 디저트까지! 날잡고 오전에 방문해서 여유있게 브런치 먹고 싶었지만 점심먹고 늦게 방문!그르케 휘낭시에가 맛있다고 소문났던데!진짜 다양한 종류의 휘낭시에👀 디저트굿!커피도굿👍🏻 4층 규모로 큰 매장 인테리어! 층층마다 새로워요! 앞으로 자주 방문할 예정🫶🏻', 52, 15, 'GOOD', SYSTIMESTAMP);
