INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '매장도 4층까지 있고 층마다 화장실도 잘 되어 있어서 경의선 숲길 걷다가 쉬고 가기 딱 좋아요^^ 휘낭시에도 넘넘 맛있습니당🩷', 22, 4, 'GOOD', SYSTIMESTAMP);
