INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '신촌에 이런 카페가 있는 줄 몰랐는데 너무 좋았어요 오늘은 친구랑 방문했지만 층마다 분위기가 달라서 공부하러 오기도 좋을거같아요 ! 디저트 음료 다 맛있고 공간도 넓어서 짱 !', 26, 5, 'GOOD', SYSTIMESTAMP);
