INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '새로 오픈한 곳이어서 처음 다녀와 봤습니다. 너무 깔끔하고, 매장이 엄청 깨끗하고 넓어요. 밤에 와서 뷰도 너무 좋고, 친구나 연인과 오붓하게 시간 보내기에도 좋을 것 같아요 ^^! 사진도 잘 나오고, 음료와 빵 모두 맛있었습니다!', 44, 10, 'GOOD', SYSTIMESTAMP);
