INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '여기 진짜 대박인데요… 생길 때부터 언제 생기나 오매불망 기다렸는데 와 보니 너무 너무 만족스럽습니다 피낭시에랑 소금 빵 다 너무 너무 맛있어서 집에 갈 때 소금 빵 추가로 더 사왔어요 ㅠㅠㅠ 진짜대박 조용히 책 보러 가기에도 너무 좋습니다 ㅠㅠㅠ', 39, 5, 'GOOD', SYSTIMESTAMP);
