INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '글루텐프리 휘낭시에들 맛있었고 초코맛은 페레로로쉐맛나요!! 쑥맛도 맛있었어요 너츠맛도 견과류 아낌없이 들어가있고 빠작빠작해서 씹는맛이 좋았어요', 49, 1, 'GOOD', SYSTIMESTAMP);
