INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '육교위로  지나다니는  사람구경  하는재미가있고  우선  디저트가  정말  맛있어요. 그루텐프리휘낭시에는  깔끔한맛이고 쉬폰케이크가  미쳤어요 .  진짜부드럽고  너무  맛있어요  늦게와서  바닐라가아닌  녹차엿거든요??바닐라먹고싶어요 ㅜㅜ일찍와서  바닐라  차지하세요! 혼자온다면  3~4층  앉을거갖고  남친이랑와서  2층에서  계속  사진찍고  놀았어요. 서울대형카페 넘  좋네요!', 103, 24, 'GOOD', SYSTIMESTAMP);
