INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '얼마전 새로 오픈한것 같아 휴일 아침에 브런치 먹을겸 와봤습니다. 샌드위치도 맛있고 커피도 맛있습니다. 분위기도 좋고 휴일 아침에 여유를 즐기기도 좋습니다. 경의선 숲길 지나다니는 사람들 보는 풍경도 좋습니다.  추천해요.', 48, 1, 'GOOD', SYSTIMESTAMP);
