INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '글루텐프리 휘낭시에와 산미가득한 아메리카노 그리고 밀크티, 잠봉뵈르 샌드위치가 매우 맛있었던 카페입니다. 원두 종류는 선택이 가능했는데, 고소한 원두와 산미있는 원두 그리고 디카페인까지 선택할 수 있어 취향에 맞게 이용할 수 있는 점이 좋았습니다. 지하1층~4층까지 이루어진 대형카페답게 굉장히 넓고 쾌적했고, 곳곳에 이용자들의 편리를 위한 포인트들이 눈에 띄어 감동.. 인테리어도 아주 이쁘고 체어나 조명시설도 훌륭했습니다. 역 바로 앞이라 접근성도 좋아 자주 이용할 것 같아요!', 11, 2, 'GOOD', SYSTIMESTAMP);
