INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '경의선숲길 라인에 있는 신상 신촌카페라서 궁금했는데 다리 바로 옆에 있어서 뭔가 뷰가 새로웠어요~! 층마다 인테리어 컨셉이 달랐는데 엄청 힙함 그자체! 혼자오기도 좋고 여럿이 와도 넓어서 편히 쉬다 갈수있고 뷰맛집이였어요~ 대박인건 그냥 아메리카노 마셨는데 제가 좋아하는 계열의 원두라 깜짝놀랐음! 필터시킨거 아닌데 기본이 이맛이라니! 커피맛있어서 또 오고 싶은 곳! 휘낭시에도 종류 진짜 많아서 골라먹기 좋을듯했는데 전 샌드위치 먹은게 반전 ㅎ 근데 넘 맛있었어요!', 81, 18, 'GOOD', SYSTIMESTAMP);
