INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '🧀바스크치즈케이크(8,000원) - 너무 부드러워서 입안에서 맴도는 순간이 진짜 행복했다. 글루텐프리임에도 진짜 촉촉하면서 하나도 퍼석하지 않은 맛이라 다음에 와도 무조건 먹을 것 같은 디저트! 🥖휘낭시에(클래식 2,500원, 쑥, 초코 3,000원) - 하나하나 이렇게 꽉찬 휘낭시에 처음이고 너무 맛있었다. 너무 달지도 않으면서도 기분좋게 맛있었다. 특히 산처럼 솟은 토핑(초코 시리얼, 쑥 크림) 대박이었음!!! 🍵초봄(6,500원) - 녹차를 정말 사랑하는 말차 러버로서 인정하는데 딸기와 말차가 섞인 음료가 잘 있지도 않을 뿐더러 말차 본연의 그 쌉쌀한 맛이 너무 잘 어울림 올해 최고의 말차!!', 6, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
