INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '도심한복판에서 통창뷰를 즐길수있는 완벽한 동네카페! 글루틴 프리/ 노슈가 / 쌀베이킹! 빵에 진심인 곳! 내 최애카페로 등극! 강츄 :)', 1, 10, 'GOOD', SYSTIMESTAMP);
