INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '여기 커피 진짜 맛있어요. 원두 종류 선택 가능한데 상큼 버전 너무 괜찮더라고요.. 인테리어도 예쁜데 2층에 않아 있으면 하늘다리 건너는 사람들이랑 너무 눈이 많이 마주쳐요.. ㅋㅋㅋㅋㅋㅋ 서로 원숭이 쳐다보듯 ㅋㅋㅋㅋㅋㅋ 3층은 스터디하기에 좋은 자리입니다! 콘센트 이용 편하게 할 수 있어요.', 41, 1, 'GOOD', SYSTIMESTAMP);
