INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '수제 베이커리라서 건강하고 맛있는 빵 종류가 많은 신촌 브런치 맛집으로 유명하더라구요~ 그리고 무려 4층 규모의 대형카페다보니 항상 쾌적하고 조용해서 학생들도 카공하러 많이 오는것 같았어요! 커피도 맛있고  샌드위치랑 디저트 다 맛있네욤ㅎㅎ 서울에서 여유롭게 커퓌한잔~할 수 있는 대형카페에요', 25, 0, 'GOOD', SYSTIMESTAMP);
