INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '서강대입구역 코앞이라 좋았던 카페! 매장이 넓고 제 사랑 디저트가 다양하게 준비되어 있어서 너무 좋았어요! 바스크치즈케이크랑 소금빵 강추드리고 고소한 라떼랑 시원달달한 초봄까지✨✨ 분위기, 맛 모두 제대로 즐겼습니다❤️', 39, 1, 'GOOD', SYSTIMESTAMP);
