INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '서강대역 바로앞에 있는 대형카페에요! 인테리어 세련되게 멋지고 디저트가 글루텐프리인데 너무 맛있게 먹었어요🩷 휘낭시에 바삭하니 맛있고 치케는 보슬보슬~~ 선물하기에도 딱 좋을것 같아요:)', 19, 3, 'GOOD', SYSTIMESTAMP);
