INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '사장님께서 추천해주신 라떼도 너무 맛있었고 에이드도 상콤하니 좋았어요 !! 4층까지 있어서 넓고 인테리어도 이쁘더라구요 데이트 하기도 좋고 혼자 책 읽거나 작업하기에도 딱 괜찮은 내부였어요 ~ 🖤 레몬케이크 너무 좋아하는데 호기심카페 레몬 케이크 맛있고 디저트가 글루텐프리라 더 좋았네욤 종종 서울 방문해야하는 일이 많은데 갈때마다 가려구요!!!', 26, 9, 'GOOD', SYSTIMESTAMP);
