INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '2,3,4층 전부 탁트인 통창으로 개방감도 좋고 음료도 맛있고 디저트도 베이커리 전문점 못지않게 맛있어요 ! 직원분들도 친절하시고 층마다 좌석타입이 달라서 인원수와 상황에 맞게 이용하기 좋은 서강대 카페 호기심입니다 !', 19, 5, 'GOOD', SYSTIMESTAMP);
