INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '오자마자 최애 카페가 되어버린 곳❤️ 카페탐방을 좋아해서 카페는 매번 새로운 곳을 방문하는 편인데 여긴 매주 오려구요!! 뷰도 예쁘고 디저트도 존맛이고 음료도 맛있는 카페에요! 바로 맞은편이 뷰가 예뻐서 조용한 곳 와서 카공하거나 모임하기 너무 좋은 곳이에요🤩 그리구 사장님 완전 친절하심🤭 신촌 사는데 웨안와..?🤔 저만 알고 싶지만 오래 잘되었으면 해서 적극 공유중입니당❤️ 다음주에도 또 올게요!!', 32, 5, 'GOOD', SYSTIMESTAMP);
