INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '소금빵이 완전 겉바속촉 제대로인데요?! 샌드위치도 전혀 안느끼하고 아삭아삭 맛난곳이에요. 그리고 지하부터 4층까지 있는데 통창으로 되어있어서 뷰맛집이에요!! 하얀 눈 세상 구경 실컷하고왔어요 :)', 87, 18, 'GOOD', SYSTIMESTAMP);
