INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '진짜.. 어떻게 이런곳이 학교 앞에 생겼는지..! 맨날 여기 오거싶어서 간질간질해요 😭 벌써 두번째 방문에 친구들 지인들 여기저기 공유해서 알려줄만큼 완벽한 곳이에요 오늘은 저녁에 와봤는데 뷰가 너무 좋아서 맘도 좋아지고.. 낼도 또 올겁니당 ㅎㅎ 희망시에도 서비스로 더 주셨는데 이렇게 퍼주시면 어떡하나용ㅠ!! 맛있게 먹었어요 정말 감사합니다:)', 53, 16, 'GOOD', SYSTIMESTAMP);
