INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '카페가 엄청크고 쾌적해서 스터디하기도 좋고 뷰도 너무 멋져요🌈💕 거기에 이렇게 맛있는 글루텐프리 디저트까지 ?..... 럭키비키쟈나', 5, 9, 'GOOD', SYSTIMESTAMP);
