INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '동네에 대형카페가 오픈해서 반갑고 즐겁네요 휘낭시에종류도많고 분위기도좋아서 기분업입니다. 주말이라 가족과 왔는데 사람도이미 많네요', 121, 20, 'GOOD', SYSTIMESTAMP);
