INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '커피랑 디저트 모두 맛있었는데 디저트는 글루텐프리라 더 좋았어요! 카페가 4층까지 있고 좌석도 많았습니당 특히 2층은 인테리어가 잘 되어있어서 감성 사진 남기기 가능할 것 같더라구용 카페가 통창으로 되어있어서 멍때리며 힐링하다 왔네요 다음에는 시험기간에 카공하러 또 방문할 것 같아요! (체험단에 선정되어 체험 후 솔직하게 작성한 후기입니다)', 44, 9, 'GOOD', SYSTIMESTAMP);
