INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '태어나서 먹은 휘낭시에 중 제일 맛있어요 ㅠㅠㅠ 관악구 사는데 휘낭시에 먹으러 호기심카페 또 올거에용,, 직원분들도 친절하시구 분위기도 좋고 음악도 럭셔리하구 ㅠㅠ 무엇보다 음료랑 음식이 맛있으니 서강대 입학하고싶네요 ♥️ 이 매장에서 휘낭시에 4종류를 먹었는데, 그것들이 각각 인생 휘낭시에 1,2,3,4순위에 등극할 정도로 맛있어용♥️', 82, 16, 'GOOD', SYSTIMESTAMP);
