INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '서강대 근처에 큰 카페가 새로 생겼다고 해서 와봤는데, 시킨 메뉴 하나하나 다 맛있었어요! 일단 카페가 4층까지고 통창이라 경의선 숲길공원이 한 눈에 들어오는 것도 좋았고, 창 밖을 보면서 공부할 수 있는 자리가 있어서 답답하지 않게 공부하기 딱 좋겠다 싶었어요 ㅎㅎ 콘센트도 많아서 더 좋아요! 휘낭시에는 쑥 휘낭시에, 황치즈 휘낭시에처럼 독특한 휘낭시에가 많아서 좋았고 미니 레몬 케이크도 상큼하고 진짜 레몬 맛이 나서 맛있었어요 ㅎㅎ 지하 1층 베이커리에서 직접 만드셔서 시판 디저트랑은 비교가 안 되는 맛이었어요~ 커피도 4층 로스터리에서 직접 로스팅하신다더니, 화사한 향이 나면서 새콤하고 은은하게 단 맛이 나는 맛있는 커피였어요! *본 업체에서 제품 또는 서비스를 제공받아 솔직하게 작성된 글입니다.', 95, 20, 'GOOD', SYSTIMESTAMP);
