INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '와 여기 대존맛 ㅠㅠㅠㅠ 호키라떼 먹었는데 넘 꼬소하고 달달하고 증말 맛있어요.. 치케도 크고 진짜 넘 맛있어욥…. 최근 간 카페 중 가장 만족스럽습니다 공간도 크고 예쁘고 사장님 친절하시고 재방문 의사 10000이에욥 💗', 61, 18, 'GOOD', SYSTIMESTAMP);
