INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '모 아이웨어 브랜드 쇼룸이 떠오르는 인테리어입니다. 층별로 다른 컨셉의 인테리어이며 대체로 앉기 편안한 의자입니다. 소금빵도 유수의 베이커리들에 견줄만큼 맛있습니다.', 10, 5, 'GOOD', SYSTIMESTAMP);
