INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '주문한 아메리카노와 말차라떼 모두 너무 맛있었고(특히 말차라떼가 완전 제 스타일💛) 휘낭시에는 포장받아왔는데 봉투랑 패키지, 휘낭시에 비주얼까지 너무 이뻐서 선물이나 답례품으로 하기 좋아보였어요! 냉동실에 하루정도 두고 다음날 해동해서 먹었는데 진짜 맛있었습니당 ㅜㅜ 더 사올 걸 후회했어요.. 매장도 넓고 쾌적하고 뷰도 좋아서 머물다가기 넘 좋았습니당👍', 24, 5, 'GOOD', SYSTIMESTAMP);
