INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '2층 인테리어가 매우 뛰어납니다. 카페에서 흔히 볼 수 없는 쇼파와 의자로 구성되어 있고, 경의선숲길을 통창으로 볼 수 있는 뷰까지! 경의선숲길 걷다가 다양한 베이커리 메뉴들과 커피 한잔하며 쉬기 좋습니다', 21, 5, 'GOOD', SYSTIMESTAMP);
