INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '생긴지 한달도 안되서 그런지 엄청 깨끗해요,, 집 근처에 이런 카페가 생겼다니ㅠ 매번 올 것 같아요 의자도 편하고….❤️ 빵도 파티쉐분이 따로 만드시는 것 같더라구요 지하일층에서 만들어서 빵이 빌때마다 채워주시더라구요!!! 그런 카페 잘 없는데.. 빵 맛집의 이유가 있었습니다 아주 장사가 잘 될 것 같은 느낌이 옵니다..👍', 45, 7, 'GOOD', SYSTIMESTAMP);
