INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '최근에 갔던 카페 중에서 제일 맛있었어요••🫶🏻 얼그레이를 가장 좋아하는데 얼그레이 밀크티가 진짜 진하고 휘낭시에도 쫀득하게 다 맛있었어요 그리고 카라멜이 진짜 미쳤습니당ㅠㅠ 못하는 카페는 가끔 눅눅한데 여긴 완전 쫀득 그 자체라서, 다음에 또 방문해야 겠어요🥹🤍🤍', 16, 9, 'GOOD', SYSTIMESTAMP);
