INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '이렇게 맛있고 좋은데 가격이 진짜 싸서 놀랍다.. 최고의 가심비 가성비 뷰도 너무 좋고 오랜만에 대만족카페를 찾았다 작업하기에도 좋고 친구랑 수다떨기에도 제격인곳 혼자 바치케 먹으러와도 좋을 듯 원두는 고소한 맛이 생각보다 산미가 있지만 바치케 진짜루 맛있음. 다른 샌드위치가 너무 탐나서 다음번에는 샌드위치 먹으러 올 곳!!', 48, 5, 'GOOD', SYSTIMESTAMP);
