INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '분위기도 좋고 빵도 맛있고 공부하기도 좋아서 또 왔습니다! 층 별로 분위기가 나눠져있어서 너무 좋아여 친절하시구,, 또 올께요🍀', 58, 17, 'GOOD', SYSTIMESTAMP);
