INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '어제 오후 경의선 숲길을 막내딸과  함께 걷다 경의선 서강하늘다리를 지나는데 인테리어 멋진 건물이 있어보니 카페였다. 그래서 내일은 그 카페를 가보자 하여 딸과 함께 오게 되었다. 와서 보니 카페 이름도  호기심카페였다. 훈남 직원분도 친절하시고 고소한 아메도 고소 그 자체^^', 45, 2, 'GOOD', SYSTIMESTAMP);
