INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '디카페인 커피도 진하고 좋았어요! 그리고 매장 넓고 인테리어도 예뻐요 ㅎㅎ 치즈케이크는 진짜 노슈가인데도 엄청 맛있게 먹었어요 양도 꽤 많고 깊은 맛 나서 좋았어요!!', 24, 4, 'GOOD', SYSTIMESTAMP);
