INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '분위기도 좋고 내부가 넓어서 너무 좋았어요!! 무엇보다 크래미 와사비 샌드가 너무 너무 맛있습니다ㅠ 이 맛이 또 생각날 것 같아요 재방문 의사 1000%!!', 19, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '분위기 있는 카페에요👍인테리어도 멋지고 휘낭시에나 디저트, 커피 모두 특별한 메뉴가 많아요 에스프레소 다양한 곳이 없는데 메뉴가 많은게 커피도 바부심 있는 카페 같아요👍', 29, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '노슈가 글루텐프리 바스크 치즈 케이크 골랐어요! 맛있었고 커피도 훌륭했습니다 이층은 감각적인 소파 위주로 꾸며져 있고 삼층이 테이블 개수도 다양하고 집중하기 좋습니다 휘낭시에의 종류와 샌드위치 종류가 다양한데 샌드위치 인기가 많아보이더군요. 지금 휘낭시에는 리뷰이벤트도 하네용', 22, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '여기 미쳤는데요..!!! 진짜 대박 ㅜㅜ 넘 예쁘고 다 완벽한 카페를 찾아버렸네요 이대로면 매일매일 친구 데리고 오겠어요 … 대박나세요👍🏻👍🏻 아니.. 가성비가 진짜 말도안되는데 퀄리티가 너무너무 맛있어요 핫플 유명한 맛집보다 더 대박적인데 할인도 엄청 해주시고 ..!', 12, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '완전 넓고 쾌적한 서강대역 카페! 경의선 공원 근처라 산책하다 들르기도 좋을 것 같아요ㅎㅎㅎ 오픈 시간도 8시고 샌드위치도 넘 맛있어서 신촌 브런치 카페로 강추합니다🩷 디카페인 메뉴도 있어서 더 좋아요오오오😆😆👍👍', 49, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '샌드가 넘 맛있어요! 특히 잠봉뵈르 샌드위치 존맛탱ㅎㅎ 가장 먼저 품절되더라구요:) 그래서 다음에 또 방문할 때 크레미 와사비 샌드도 겉바속촉 느낌이고 르꼴라의 향이 훅 퍼져요! 아메리가노랑 먹으니 딱. 내부 분위기도 확 트여서 좋더라구요❤️ 휘낭시에도 촉촉 ㅎㅎ담에 또 방문하려합니당', 5, 1, 'GOOD', SYSTIMESTAMP);
