INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '카페 완전 이쁘고 맛도 너무 맛있어요 그리고 가격이 너무 착해요 1층은 애견동반 가능해서 너무 좋아요 ㅎㅎㅎㅎ ❤️❤️ 카페 주차도 가능하고 4층까지 있어서 진짜 커요 신촌에 이런카페가 새로 생겨서 넘 좋은거 같아요 자주 와야 겠어요', 103, 23, 'GOOD', SYSTIMESTAMP);
