INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '벌써 세번째 방문이에요~!! 직원분들께서 너무너무 친절하셔서 계속해서 오고 싶어지는 곳이에요!! 오늘도 너무너무 잘 먹고 쉬다 갑니당:) 매번 이렇게 휘낭시에랑 케이크 나눠주시면서 저를 살찌우는 카페..☕️ 애정합니당💕', 21, 10, 'GOOD', SYSTIMESTAMP);
