INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '산책하다 생긴지 얼마안된 카페라 들어와서 커피와 디저트시켜 먹어봤는데 커피 너무 맛있어요~~~~커피에 진심인 저희부부 애정하는 카페될듯하네요.', 28, 7, 'GOOD', SYSTIMESTAMP);
