INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '아몬드비엔나 넘 맛있어요~ 휘낭시에랑 레몬케이크도 넘 맛있네요 글루텐프리라서 더 좋아요👍🏻✨ 층별로 분위기도 다르고 인테리어도 달라서 좋네요ㅎㅎ 3층은 공부나 일하기 좋을거같아요', 39, 7, 'GOOD', SYSTIMESTAMP);
