INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '통창으로 확트인시야도 좋고 작업할수있는 전용자리도있어 노트북 하기 좋아요!!!  그리구 2층부터 4층까지 자리도 많은 대형카페에요! 주차공간도 있음!', 16, 5, 'GOOD', SYSTIMESTAMP);
