INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '에쏘 문경☕️ 탄산수와 함께 제공됩니다- 다양한 원두 중 선택이 가능해서 좋습니다. 파삭파삭 버터향이 가득한 소금빵이에요🥐 🐰☕️🐨', 59, 13, 'GOOD', SYSTIMESTAMP);
