INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '새로 오픈해서 가봤는데... 단골될거 같아요. 인테리어도 너무 멋지고  예약하면 20프로 할인도 해주셔서 저렴한가격에  커피랑 샌드위치도 먹고 추가로 커피 한잔씩 더 먹었네요 ㅎㅎ 통창으로 되어있어서 답답해보이지도 않고  친절하셔서  기분 좋게 있다 왔습니다. 그리고 너무 친절하셔서   기억에 남았던거 카페중 하나 인거 같아요.', 48, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '서강대역 바로 앞이고 신촌역 근처여서 접근성도 좋고 실내가 쾌적해서 좋아요! 넓고 감각적인 인테리어가 많고 통창이라 답답한 느낌은 전혀 없어서 집중하기 좋아요! 커피는 고소한 맛이 빵이랑 어울려서 간단하게 할 일 하면서 아침 보내기 정말 좋아용!!', 73, 11, 'GOOD', SYSTIMESTAMP);
