INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '서강대역 앞 카페! 건물이 올라갈 때부터 뭐가 들어설까 호기심 가득히 기다렸는데, 카페이름이 호기심이네! 분위기도 좋고, 뷰도 좋아서 생각정리하기 딱이다. 여기에 앉아 있으면 글도 휘리릭 잘 써질 것 같은 느낌이네. 새로운 아지트 발견!', 28, 5, 'GOOD', SYSTIMESTAMP);
