INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '서강대역 바로앞에 대형카페가 생겼길래 들어와봤어요 통창에 4층까지 있어 탁트이고 청결해서 좋았는데 커피도 맛있구 특히 딸기밀크티 넘 맛있었어요!!💗 잠봉뵈르도 맛있었는데 카라멜 휘낭시에가 진짜 존맛이었습니다👍 사장님도 친절하시고 자주 올거같아요☺️', 85, 17, 'GOOD', SYSTIMESTAMP);
