INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '새로생긴 대형카페로 카공하러 방문했는데 좌석이 깔끔하게 잘 되어있어요! 글루텐프리 제로슈가 케이크도 있길래 함께 시켰습니당 여유롭게 즐기기 좋은거 같아서 추천해요', 7, 8, 'GOOD', SYSTIMESTAMP);
