INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '뷰가 좋아서 노트북으로 작업하기 좋은 카페 4층까지 있는 대형카페임을 감안하더라도 커피랑 디저트 가격이 너뮤 합리적이라 앞으로도 자주 방문할 것 같아요ㅎㅎ 신상 카페라 공간이 너무 깨끗한 점도 매우 마음에 듭니다', 20, 1, 'GOOD', SYSTIMESTAMP);
