INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '버터 풍미가 정말 진하고 겉바속촉 그잡채✨✨ 최애는 초코 휘낭시에예요🍪🍫 샌드위치 종류도 있어서 브런치 먹으러 오기도 좋고, 좌석도 4층까지 있어서 넉넉해요!! 디저트 덕후는 또오겠습니당~', 0, 6, 'GOOD', SYSTIMESTAMP);
