INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '아직 많이 알려지지는 않아서 한가하게 일요일 브런치를 즐기는데 분명 바글바글 해질것 같아요. 뷰 넘 좋고 공간 인테리어 멋지고 층마다 테마도 달라서 누구랑 왔느냐따라 다른곳에 올수 있어요. 잠봉뵈르랑 크래미 에그 먹었는데 전 개인적느로 잠봉이 젤 맛있네요 :) 빵이 정말 겉바속촉이에요. 루꼴라 향 가득. 베이커리 종류가 많지는 않고 휘낭시에만 종류 많아요. 소금빵 11시에 나온다네요. 일단 커피가 맛있고 가격도 좋아요👍', 71, 14, 'GOOD', SYSTIMESTAMP);
