INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '경의선 숲길 뷰가 넘 좋은 카페에요. 사방이 뻥 뚫려서 답답하지 않고 좋은 공간이네요! 휘낭시에 종류도 많아서 하나씩 도장깨기 해야할 거 같아요😋 앞으루 자주 오게 될 듯 합니다!', 33, 1, 'GOOD', SYSTIMESTAMP);
