INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '높은 통창 건물에 새로 생긴 카페라 궁금해서 왔는데 인테리어가 깔끔하고 멋있었어요! 벌써 사람들이 바글바글한거보니 왠지 곧 핫플이 될 느낌??🤣 시원하게 창이 있어서 기분이 좋아요~', 33, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '잠봉뵈르 샌드위치랑 커피 맛있어요👍🏻👍🏻 바깥 뷰도 좋고 층별로 인테리어도 예쁘고 특색있어서 좋았습니다! 😊😊 직원들도 친절해서 자주 방문할 것 같아용~~~!! 번창하세욥!!', 9, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '담소 나누기에도 좋고, 직원분들도 친절하여 맛있는 양질의 음료와 디저트를 즐기고 왔답니다. 일행분들도 아주 만족하여 낮 시간대에 한번 더 오자고 하더라구요? ㅎㅎ 번창하세요~', 3, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '동네네 대형감성카페가 생겨서 좋아요. 커피도 맛있고 오트라떼 디카페인 되어서 좋아요.!! 혼자 노트북 하기에도 좋고 수다떨기도 좋고 추천이요.', 42, 5, 'GOOD', SYSTIMESTAMP);
