INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '서강대역카페 호기심 공간도 넓고 쾌적하고 이뻐요ㅎㅎ 커피도 직접 로스팅해서 맛있고 브런치도 존맛인데 휘낭시에 글루텐프리더라구요ㅎㅎ 많이 달지 않고 맛있어요ㅎ 또 가고싶은 곳ㅎ', 74, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '잔잔한 음악과 함께 각 층마다 다른 인테리어와 창밖으로 보이는 뷰까지. 특히 이날, 갑자기 내린 소나기와 매장 안의 분위기가 더 해져서 ''도심 속 힐링공간''이란 말이 어울리는 곳이었어요~ 공사할 때 부터 궁금했는데 카페이름까지 [호기심]이라니 사장님 센스 최고👍 거기에 특별한 음료도 있어 좋네요~ 포장도, 매장 방문도 자주 이용할 것 같아요.☺️', 12, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '커피도 맛있고 특히 휘낭시에 맛집이에요!!! 층이 여러 개여서 이야기 하기 좋은 곳도 있고 집중하기 좋은 곳도 있는 카페입니당', 65, 14, 'GOOD', SYSTIMESTAMP);
