INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '서강대 인근에 이런 대형카페가 생기다니!! 카공하기 좋은데 분위기도 좋고 뷰도 좋아서 집중이 잘되네여ㅎㅎ 음료랑 디저트도 맛나요 특히 바닐라라떼 강추 다음에 또 오고싳은카페입니당~', 57, 12, 'GOOD', SYSTIMESTAMP);
