INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '오미자에이드는 상큼달콤하고, 날이 많이 더웠는데 리프레쉬되는 음료였어요. 시그니쳐 메뉴인 아몬드 비엔나는, 크림이 달콤하고 부드러워서 첫 모금부터 기분좋게 마셨습니다 :) 바스크치즈케이크는 스테비아를 사용해서 건강하고, 글루텐 프리여서 소화도 잘 되고 좋았어요. 매장이 넓어서 쾌적하고 층마다 개성있어서 취향에 맞게 앉을 수 있어서 좋았어요 :D 자주 오게 될것 같습니다!', 8, 3, 'GOOD', SYSTIMESTAMP);
