INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '신촌 근처에 이런 대형카페가 있다니..!! 몰랐는데 보물 찾은 기분이에요 ㅎㅎ 전체적으로 쾌적하고 인테리어도 넘 이뻐요ㅠㅠ 통창뷰라서 힐링 제대로되고 아아랑 잠봉뵈르도 맛있게 먹었어요 🥰 혼자 오기도 넘 좋고 수다떨러 오기도 좋습니당👍', 264, 29, 'GOOD', SYSTIMESTAMP);
