INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '항상 올때마다 사람이 많은데 왜 그런지 알 것 같은 곳이에요! 커피가 산뜻하고 향이 좋아요. 베이커리류가 정말 맛있어서 혼자 와도 항상 하나는 시키게 돼요. 3층 창가에 공부하기 좋은 자리가 있어서 과제할 때 오기 좋습니다!', 31, 0, 'GOOD', SYSTIMESTAMP);
