INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '경의선숲길 신상 카페인데 뷰 맛집입니다 통창이라서 시원하고 글루텐프리 디저트도 맛있네용 다음에는 샌드위치 먹으러 오고 싶어요ㅎㅎ', 10, 5, 'GOOD', SYSTIMESTAMP);
