INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '매장이 엄청 넓어서 쾌적하게 좋았어요!! 휘낭시에가 겉바속촉이라 너뮤 맛있어용💕 밀크티도 향이 너무 좋았구요 커피는 산미, 고소, 디카페인 고를 수 있어서 좋아용!!', 43, 10, 'GOOD', SYSTIMESTAMP);
