INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '내가 좋아하는 글루텐프리디저트!! 저번에 갔을때 휘낭시에는 다 품절이라 못먹었는데 오늘은 다행이 있어서 먹어봄!!! 얼그레이와 쑥 클래식 빼고. 초코.너티.시나몬맛으로 먹어봄!! 퍽퍽하지도 않고 달달하니 아메리카노와 궁합이 찰떡!!!!', 84, 15, 'GOOD', SYSTIMESTAMP);
