INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '조금 걸어도 맛있는 샌드위치랑 커피 먹으러는 크O크랑 비0소만 갔는데 동네에 깨끗하고 힙하고 샌드위치랑 커피 정말정말 맛있는 카페가 생겨서 너무 좋습니다. 커피도 진짜 신선하고 고소하고 빵도 직접 만들어 그런지 정말 맛나요. 그리고 층마다 컨셉도 다르고 디자인도 이뻐서 이용할 맛 나네요. 직원분들도 진짜 친절해요.', 91, 21, 'GOOD', SYSTIMESTAMP);
