INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '매장 깔끔하고 엘레베이터 있어서 좋아요^^ 다만 오픈한지 얼마안되어서 아직 정체가 있어 보였어요. 음료와 디저트를 다 먹고도 자리에 계속 있는 일부 사람들로 인해 새로운 사람들이 자리를 찾지못하거나 테이블을 쓰지못하는 상황을 보고 안타까웠어요. 저희도 자리가 없어서 1층에 직원분이 의자와 미니테이블을 주셔서 노슈가 글루텐프리 치즈케이크와 음료를 얼른 맛있게 먹고 자리를 나왔어요. 거리가 있는지라 배달에는 아직 안뜨네요^^ 치즈케이크는 치즈맛이 역하게 강한편이 아니고 부드럽고 노슈가라는 강점이 정말 좋았습니다. 제가 체다치즈같은 강한 치즈맛을 못먹고 모짜렐라치즈정도로 먹어서 딱 좋았습니다. 이곳의 치즈케이크가 집에오니 아직 아른거리네요. 번창하세요 :) 🌸', 17, 6, 'GOOD', SYSTIMESTAMP);
