INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '폭염속 마음이 이끄는대로 걷던 날 오아시스같이 눈앞에 나타나준 카페. 1. 친절 2. 휘낭시에 味쳤음 (두개중 하나 포장하려 했으나 앉은자리서 순삭 - 시나몬, 초코 냠냠긋) 3. 집중하기 좋아서 눈깜새 몇시간 지남 덕분에 힐링하고 갑니다.', 26, 2, 'GOOD', SYSTIMESTAMP);
