INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '산책할때  살펴보다가  직접  왔는데   각충마다  분위기가  달라  좋아요  닭가슴살샌드위치  좋아하는데   오늘은  품절 ㅠㅠ  다음에는  조금  더  빨리와서  먹어야할것  같아요 경위선숲길 쪽에   오실분들은  추천추천♡♡', 35, 10, NULL, SYSTIMESTAMP);
