INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 호기심'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '너무 괜찮은 동네키페 탄생. 친절한 사장님과 매우 좋은 커피 맛 층별로 여럿이도 혼자서도 오기 좋은 좌석과 분위기를 주고 있어 오래오래 있어주길 바랍니다😀', 50, 2, 'GOOD', SYSTIMESTAMP);
