INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '완포 코리아'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '주문하고나서 기다리는데 직원분이 먹고 가는거면 먹고가기를 키오스크에서 선택해야된다고 큰 소리로 언잖게 얘기해서 기분이 안 좋네요... 키오스크에서 잘못 선택하기는 했지만 다른 손님들도 있는데 그렇게 큰소리를 치면서 사람 무안하게 만들면 어떡하나요... 홍대에 올때마다 매번 오던 곳인데 이렇게 손님 응대를 하면 누가 다시 올까요... 다음에는 친절하게 해주셨으면 좋겠네요.', 67, 18, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '완포 코리아'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '대만 여행할 때 차 많이 마셨는데, 여기 인테리어며 다양한 차 종류며 마치 대만에 온 기분이 들어요. 예전에 아리산 우롱차랑 과일차 종류도 몇 번 마셨는데 이번엔 신메뉴 레아 우롱차? 마셨어요. 은은한 향이 너무 좋아요.', 12, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '완포 코리아'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '예전에 흑화당이 있던 자리같은데, 오랜만에 지나갔더니 새로운 곳이 생겨 방문해 봤어요. 저는 버블 밀크티를 마셨지만 일반 순차나 과일차도 있어서 다양한 티를 즐기기에 좋은 것 같아요.', 28, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '완포 코리아'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '밀크티 맛있습니다. 대만맛.. 그대로… 그러나… 음료 한 잔 제조에 10분은 걸립니다. 손님 3명 있었고 직원 보이는 사람만 3명이었는데… 10분 넘게 기다렸네요..  시간 여유 많은 분만 가세요. 직원이 중국인인 점 전혀 신경쓰지 않았습니다. 그러나!! 우리말을 암만 못해도 음료 받으려는 손님한테 번호표 확인 위해  “영수증” 이라고 딸랑 한 단어 말합니다. 과연 “주세요” 라는 표현을 모를까요? 안하는거겠죠. 친절한 응대는 커녕.. 직원 유니폼이 흰색이었던 옷 같은데 정말 더럽네요.. 배 부분이 거의 갈색… 아마 찻물이 스며든게 찌들어 그런 것으로 추정.. 그럴거면 유니폼을 갈색으로 하던지.. 하.. 리뷰 귀찮아서 안쓰는데.. 총평=진짜 불친절+느려터짐+더러운 유니폼… 맛은 좋아요.', 35, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '완포 코리아'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '대만의 맛 그자체.... 음료는 너무너무 맛있어요! 사람이 많아서 음료 나오는 데 시간이 좀 걸립니다. 바빠서 그런지 직원분들이 약간 윽박지르는 게 있으시고 친절한 느낌은 아니에요~', 88, 15, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '완포 코리아'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '태도가 매우 나쁩니다. 손님에게 화를 냅니다! !! 10분 기다렸는데, 다 되었는지 물어보면 우리한테 화낼 거예요. 무슨 화를 내고 있습니까? 말을 제대로 못합니까? 이 가게는 무엇을 하고 싶습니까? 정말 형편없습니다!', 97, 24, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '완포 코리아'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '음료는 항상 맛있는데 어떤 직원분이 계속 다른 직원에게 잔소리 하고 있음…. 중국어 알아 듣는 사람이라서 듣기 좀 불편해요🥲🥲', 98, 24, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '완포 코리아'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '직원이 정말 싸가지가 없어요. 바쁘지만 효율적 없으로 일하고 있어요. 메뉴판 중에 제일 간단한 메뉴 주문하고 10분정도 기다리고 왜 계속 기다리는지 궁금해서 받을 수 있는지 물어봤지만 직원은 우리에게 화를 냈어요. 헐 완전 이해할 수 없는 행동이에요. 오래 기다렸는데 미안하기는 말도 없고 고객에게 화를 내는 게 맞나요? 그리고 1층에 떠나고 2층에 올라가서 직원분이 또 안 좋은 소리 하시는 거 들었어요.', 56, 11, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '완포 코리아'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '음료가 맛있습니다. 당도나 얼음도 세세하게 조절가능하고 일반 버블티 파는 곳에서는 못 먹어봤을 타로밀크티나 애옥젤리 같은게 특이해요.', 27, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '완포 코리아'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '밀크티 1티어 맛집이라고 생각해요. 홍대 갈 때마다 종종 들려요. 테이블도 있지만 테이크아웃만 했었구요 아리산 우롱 밀크티가 최애입니다!! 아쉬운 건 대기 손님이 항상 많고, 메뉴 나오는 시간이 꽤나 걸린다는 점입니다.', 5, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '완포 코리아'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '아리산 우롱 밀크티 당도 50%로 하니까 단맛이 하나도 안느껴지는 찐 밀크티 맛으로 먹었어요. 다음엔 당도 100프로로 먹어보는걸로. 전통 동과차는 살짝 달달하면서 구수하고 독특한 맛이라 잘 마셨어요. 애옥젤리 추가해 먹었는데 젤리향은 잘 모르겠고 우무가 쫄깃해지면 이런맛일까 싶은 식감에 다 먹고 나니 배도 좀 차더라구요 ㅎ 재료소진으로 못먹어본 생타로밀크에 동과차 한번 더 마시러 가보고싶네요', 27, 5, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '완포 코리아'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '서울에서 동과차 하는곳 거의없는 편인데 여기선 팝니다. 토핑중에 애옥이라든가 여기서만 파는 토핑있으니 도전해 보세요. 퀄리티 유지 계속 됐으면 좋겠어요', 23, 7, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '완포 코리아'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '평일 2시쯤 왔는데 품절된게 많아서 아쉬웠어용 ㅠ 원래 먹으려던 메뉴 말고 다른 메뉴 먹었는데도 맛있었어요! 다음에 못 먹은 메뉴 마시러 또 오려구요 펄도 따뜻하고 2층 공간도 아늑하고 좋아요', 51, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '완포 코리아'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '흑당 밀크티, 생타로 두유 밀크티 타로가 진득하게 씹히는 밀크티를 먹을 수 있어서 좋았어요! 제조과정에서 대부분의 메뉴에 가루류가 첨가되는 점이 아쉬웠어요', 23, 5, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '완포 코리아'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '홍콩에서 감동하며 마셨던 대만 버블밀크티랑 흡사해요 바로 티를 우려내지는 않지만 차맛도 진하고 버블도 쫀득하고 많이 달지도 않고 체인점이 많아졌음 하는 바람이ㅎㅎ', 31, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '완포 코리아'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '아리산 우롱 밀크티는 맛있어요~ 또 마시고 싶을정도에요. 두유 밀크티는..그냥 두유맛이에요ㅎ 다른맛이 첨가된거 마시는걸 추천합니다!', 13, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '완포 코리아'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '대만사람이 운영하는 밀크티 맛집입니다. 티 종류는 전부 원산지가 대만이라 그런지 밀크티 풍미도 좋아요 ㅎㅎ 밤늦게 가서 타피오카펄은 품절이었지만 화이트펄을 추가해서 먹었는데 정말 맛있었어요 ㅎㅎ 맛있으니 사이즈를 라지로 드시는 거 추천드립니다. 이날은 완포밀크티를 먹었는데 다음에는 다양하게 먹어봐야겠어요!ㅎㅎ😍', 108, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '완포 코리아'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '생타로 버블밀크 슈가 100으로 시켰는데 하나도 안 달아요 하도 먹어서 맛 아는데ㅠ… 설탕 깜빡하신 듯 ㅠ 따흑 바꾸러가기 구찮아서 걍 먹음', 5, 7, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '완포 코리아'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '1 대만사람이 하는 대만밀크티 맛집! 2 키오스크주문 3 밀크티는 4200부터~ 4 완포밀크티+당도100+얼음100이 기본구성입니다 5 얼음0%으로 주문해도☞냉장우유만큼시원하게 온도조절을 잘 해주셨어요 6 테이크아웃만 가능', 30, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '완포 코리아'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '완포 밀크티는 믿고 마십니다. 언제나 맛있음. 동그란 펄이 아니라서 마시다 사래 걸리지 않아 좋아요. 펄이 무슨 중국당면처럼 후루룩', 38, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '완포 코리아'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '여기는~ 레드빈 흑당젤리 밀크티 강추추추~~~~🥹 예전에 비해 젤리 크기가 커졌는지 자꾸 빨대에 껴서 먹기가 힘들었어요 ㅠ 그래도 존맛이니 상관은 없어요', 13, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '완포 코리아'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '생타로버블 옵션보니 우유인절미가 있길래 변경해서 먹었는데 우와 쫀독해서 맛있었어요. 애옥그린티도시켰는데  애옥먹고 싶을 때 여기가서  주문해요.', 51, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '완포 코리아'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '밀크티 당도 100도 생각만큼 달지 않네요 맛이 되게 깔끔해요! 가게안에 들어서니 차향이 확 나서 신기했어요 평일오후인데도 버블이 주문불가여서 추가못했는데 중국인 단골손님처럼 보이는 분들이 중국어로 얘기하니까 남은거 박박긁어서 넣어주시는ㅜ', 89, 15, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '완포 코리아'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '벌써 여기 다닌지도 5년이 넘은거같아요.코로나가 되기 전부터 다녀서... 우롱차가.. 차가 진짜 맛있는 곳입니다.  밀크티도 맛있습니다.  우롱티에 애옥벨리를 토핑해서 먹으면 저의 최애 음료입니다.', 3, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '완포 코리아'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '내부공사한다고 안열었었는데 이제 열었ㄴㅔ요 ㅠ 문연거 보자마자 감격하며 달려들어가(?) 생타로 버블밀크 2잔주문...🥰 여기밖에 파는곳이 없어욤ㅠ', 50, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '완포 코리아'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '대만음료점!! 원래 커피보다 차를 즐겨해서 전통 찻잎 파는 상점처럼 생겨 호기심에 들어가 봤더니 종류도 다양하고 차맛도 텁텁하지않고 공차도 좋아하는데 공차보다 더 차맛에 집중한 느낌이라 너무 좋고 더운날 갈증을 싹 날아가요 여러군데 생겼으면.>.<직원분들도 진짜ㅋㅋ친절하시고 빨때 못꼽고있으니까 꽂아 드릴까요 여쭤보시고 시원하게 해주시더라는👍👍👍', 161, 28, 'GOOD', SYSTIMESTAMP);
