INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '완포 코리아'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '대만 밀크티 가게입니다. 아리산 차, 사계춘 차 등등. 대만에서만 만날 수 있는 차를 맛볼 수 있습니다. 가격대도 괜찮습니다.', 5, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '우연히 버스를 타고 지나가가 좋아하는 ‘사워도우‘ 이름을 건 간판에 꼭 방문해야지하고 주말에 일부러 찾아왔어요. 유럽식 식사빵이고, 버터와 설탕이 들어가지 않아 기대가 커요. 플레인 사워도우 사오려다가 올리브 좋아해서 올리브 사워도우로 가져왔어요. 잘 먹겠습니다', 51, 11, 'GOOD', SYSTIMESTAMP);
