INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '플레인이랑 올리브 사워도우 구입했는데 정말 맛있네요🥹 겉은 질깃하며 씹는맛이 참 좋고 안은 정말 촉촉하네요. 맛있는 빵에 기분이 참 좋아요🤎', 40, 8, 'GOOD', SYSTIMESTAMP);
