INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '동네에서 앗있다는곳은 다 가봐도 제성에 안차더라구요ㅠㅠ 역시 서울인가요ㅎㅎ 한달에한번씩 쟁이러 와야겠어요~~~~ 집가는길에 2개 빼먹었는데 넘나찰지고 맛나요~~', 61, 12, 'GOOD', SYSTIMESTAMP);
