INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '잡곡 통밀 사워도우 통밀 향도 좋고 너무 맛있어요!! 하프사이즈가 없다는 점이 조금 아쉽지만 다음에는 다른 빵도 꼭 먹어볼 예정이에요🥖👍', 83, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '우연하게 건강한 빵을검색하다사워도우빵을 알게 되어 가게되었어요. 조금 일찍 도착한바람에 브레이크타임에 걸려 기다렸다 샀어요. 플레인, 고구마 사워도우빵을 샀는데 저 사진은 고구마사워도우에요. 고구마가 달큰해 시큼한 맛을 중화시켜 더 맛나게 느껴져요. 아들내미는 플레인 먹어보니 시큼하다고  하더니  고구마사워도우 먹어보고 고구마가 달아서 더 맛있대요.ㅋ겉에는 딱딱하고 질기지만 속은 정말 촉촉해요. 씹으면 담백하고 시큼하고 하지만 속은 편해요. 다 먹으면 재구매해야겠어요.', 3, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '매일 품절이어서 사지 못했던 포카치아도 오늘 겟!!!!! 역시나 죽여주는 맛…. 요즘 인기가 더 많아져서 품절이 빠르네용 흑흑.. 냉동 해놨다가 아껴먹어야지', 114, 26, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '사워도우 빵만 판매하는 . 사워도우 마스터가 계시는 사워도우 랩. 브레이크 타임 이후 4시부터 새로나온 빵을 판매하는데 4시에 맞추어 방문하는 손님들이 보였다. 고구마 사워도우는 빵의 신맛과 고구마의 단맛이 조화롭다. 소화걱정이 없는 빵이라는 것만으로도 좋은 선택지가 된다', 64, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '너무 좋아하던 곳이라 자주 갔었는데 저번에 퇴근 이후 방문하니 재료소진이더라구요 ㅜㅜ 알고보니 생활의달인에 잠깐 소개되었다구..🥹 그래서 미리 예약 하고 방문했어요 정말 너무너무 맛있는 사워도우 빵 최애 가게에요', 41, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '저는 이 가게 근처에 사는데요. 그동안은 일부러 다른 길로 다녔어요. 이렇게 맛있을줄 알았거든요 ㅠㅠㅠ 계속 피해 다녔어야 했는데 판도라의 상자를 열었네요 마지막 남은 다양한 재료 들은 거 샀는데 올리브 기름에만 찍어도 진짜 맛이 좋네요. 다음엔 오리지널 떨어지기 전에 가야지 오래오래 여기 있어주세요', 17, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '크렌베리호두 사워도우 너무 맛있어요~~👍 갈때 한꺼번에 많이 사서 소분해서 냉동실에 두고 꺼내먹어요~~ 단백하고 건강한 맛으로 질리지가 않아요~!!', 11, 9, 'GOOD', SYSTIMESTAMP);
