INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '사워도우 속도 편하고 구수하고 넘 맛있어요🥹 집앞에 있으면 정말 자주 가고싶네요*_* 홍대 갈 일 있을 때마다 많이 사서 냉동실에 쟁여둬야겠슴돠!!!', 33, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '달지 않고 건강한 빵이라 식사빵으로 좋아요. 호두사워도우에 호두에 너무 잘아요 좀 더 듬뿍 들어가 있음 더 좋을듯요. 잡곡통밀사워도우는 병아리콩을 비롯해 다양하게 들어가 있어 식사대용으로 먹기에 든든하네요', 24, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '샌드위치 심플한 재료이지만 빵이 맛을 한껏 올려줘요👍 빵이 쫄깃하고 사워도우의 신맛이 매력적이고 부담스럽지 않아 너무 좋습니다!! 다음 방문에는 사워도우 하나 구매해서 집에서 오픈샌드위치 만들어보고싶네요🧡', 23, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '샤워도우에  진심인 사람이예요. 샤워도우 맛보러  김포에서 일부러 찾아갔어요.11시오픈 땡! 매장 앞에서 구수한 빵냄새에 행복했고 집에 와서 먹으니 샤워도우의 시큼한 맛과  구수한 맛이 일품이네요. 올리브샤워도우는 그린 올리브때문에 약간은 짭짤하지만 식사빵이니 좋아요. 갓 구워진거  비닐포장이어서 그런지 살짝 습기가 차서 겉바삭이 없어졌지만 에프나 팬에 구워 먹으면 더 맛있을거같아요~^^', 88, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '사워도우빵이라 일반빵보다 건강할 것 같아서 빵 먹고싶을때마다 구매해서 먹고 있어요~겉은 빠작빠작하고 속은 촉촉합니다. 구수해서 그냥 먹어도 맛있고 냉동실에 넣아놨다가 후라이팬에 구워먹어도 맛있어요! 빵 하나에 8-9천원이여도 크고 묵직해서 비싸다는 생각 안들어요~사장님도 살짝 무뚝뚝하니 친절하시고!! 오래오래 그자리에 있어줬으면 좋겠는 빵집입니다^^ 올리브 사워도우는 올리브가 짭짤해서 조금 아쉽기는 했지만 호두나 잡곡 사워도우 완전 맛있어요👍', 32, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '사워도우만 파는 연구소, 사워도우 랩 고소하고 은은한 산미가 흐르는 맛에 살짝 빠작한 빵 겉면의 식감과 살짝 쫄깃하고 은은하게 촉촉하면서 쫀득한 속면의 식감이 매력적인 조화를 이루는 사워도우! 다양한 종류가 있으며 종류에 따라 적정량의 부재료가 속에 들어가서 빵마다 다양한 매력을 느낄 수 있음 ​ 크랜베리, 새콤달콤 크랜베리와 고소한 호두의 절묘한 조합! 고구마, 달달한 고구마가 곳곳에 포진! ​ 사워도우에 올인한 장인정신이 돋보이는 어나더레벨의 사워도우를 즐길 수 있는 곳 맛있게 잘 먹었습니다😊', 16, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '오래 전부터 가보고 싶었던 곳인데 브레이크 타임 걸려서 못 가다가 오늘 드디어 방문했어요. 오후 늦게 갔더니 호두 통밀 사워도우 딱 하나 남아서 선택의 여지 없이 구입. 8,000원인데 크기가 제법 커요. 마스카포네 치즈 발라 먹으니 느므 맛있네요.', 50, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '사워 사워한 빵을 먹어보고 싶다면 올리브 사워도우를 . 올리브도 빵도 sour 하다. 건강한 빵식사, 소화 잘 되는 빵을 만드는 곳', 18, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '샤워도우에 꽂혀있어서 약속으로 홍대 나간김에 사러갔습니다. 늦은시간에 갔더니 플레인과 크렌베리 두종류만있어서 사왔어요. 약가뉴시큼한 풍미가 좋아요. ^^', 38, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '진짜 사워도우다!!!라고 느낀 플레인 사워도우에요. 지인이 사온거  먹어봤었는데 너무 맛있었어서 처음 직접 와서 구매해요👍🏻👍🏻👍🏻여전히 맛있네요🫶🏻 다른 맛들도 도장깨기할게요!!!', 49, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '지나가다 발견하고 궁금했던 🍞집인데 들렀어요. 빵 종류는 않지 않지만 건강한 발효종 빵집이네요. 잡곡 들어간 빵 하나 업어 옵니다. 소분해서 냉동고 넣고 꼬다리 먼저 아이스크림 발라서 먹어봅니다. 짭조롬하니 맛나네요.', 36, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '멀어서 못갔는데 신촌으로 와주셔서 너무 좋아요! 사워도우 전문인데 그 안에서 은근 라인업이 다양하고요. 겉은 하드한 듯 하면서 속이 찰지고 쫄깃촉촉해요. 개인적으론 좀 더 마른 듯함 느낌도 좋아하긴 하는데, 충분히 맛있습니다. 씹을 수록 올라오는 가벼운 산미와 구수함이 맛있어요. 전메뉴 정복하러 갑니다🥰', 53, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '평일 6시에 가면 품절…헛걸음하다가 다음날 4시경에 가니 몇개 남아있어서 드뎌 구매했습니다!! 통밀,호밀인데 맛있네요! 식사대용으로 계속 먹을 듯 합니다!ㅎ', 40, 7, 'GOOD', SYSTIMESTAMP);
