INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '사워도우 너무 맛있어요!! 담백하고 밋밋한 빵 좋아하는데 계속 손이 가는 맛이에요 양도 많고 여기저기 곁들여 먹기 너무 좋아요', 12, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '통밀빵 퀄리티 진짜 좋아요👍🏻 단면만 봐도 정말 잘 만든 사워도우라는걸 아실수 있을꺼에요!! 여기는 구워드시는것보다, 그냥 바로 먹는게 더 맛나요. 강추강추☺️ 전 사워도우 매니아이지만 맛없는 빵은 못먹는데, 여기는 일주일에 한번은 꼭가서 구매해요. 냉동실에 쟁여두고 먹는답니다💕', 5, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '크랜베리만 먹다가 올리브 처음 먹어보는데 빵이 부들거리고 시큼하면서 맛나요 크랜베리는 고소하고 밀도가 더 높은느낌이구요 여기 빵 제스타일 검암에 이런곳이 있어서 좋아요', 6, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '리뷰는 두번째지만 10번은 더 간거같아요ㅎㅎ 프랑스 밀을 이용한 사워도우... 강남권 직장인이라 비슷한 스타일의 사워도우하는 유명세 있는 곳에서 많이도 먹어봤지만 단연코 최고입니당ㅎㅎㅎ 검암역에서 환승하는데 시간되는날 일부러 내려서 사서가요ㅎㅎㅎㅎ냉동실에 두고 먹을거에요! 사장님 오래오래 맛있는 빵 만들어주세요:)', 85, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '여기 진짜 최애빵집인데 처음으로 리뷰 남기는거 같아요!!!! 담백하고 빵 본연의 맛 그 자체를 좋아하는 편인데 진짜 딱이에요! 좋은 밀에서 느껴지는 그 구수함 !  사워도우랩 진짜 짱입니다! 요즘은 올리브 사워도우에 빠져있는데요 살짝 구워서 먹우면 진짜 짱짱맛입니다. 저녁에 가면 고구마나 올리브는 거의 없어서 담에는 미리 예약해놓고 방문하려구요!!! 크 건강한 빵 오래 만들어주세요!!!', 73, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '체중조절중인 임산부라 건강한 빵 찾다가 구매했는데, 아침대용으로 너무 좋네요:) 저희 엄마랑 동생도 여기 빵 좋아해서 항상 먹어보고 싶었거든요, 검암동 갈때마다 재방문하고싶은 빵집입니다-', 5, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '천연 발효빵이라고 해서 일부러 찾아갔습니다. 가격이 비싸지만, 크기가 커러 식사빵으로 아주 좋아요. 크렌베리 호두 깜빠뉴는 정말 호두의 고소함이 아주 맛있었고, 올리브치아바타와 바게트 앙버터는 특유의 산미가 느껴졌지만 역시 맛있었습니다. 지퍼백에 냉동해두었고, 아침식사로 한조각씩 먹어도 충분할 양입니다. 종종 쟁이러 갈게요.', 34, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '소화가 잘 되고 식사대용으로 좋은 담백한 빵이에요 :) 빵 자르는 기계로 잘라주셔서 먹기도 편해요 ! 한 가지 아쉬운점은 퇴근하고 오후 6시 이후에 가면 대부분 빵이 소진되어있어 아쉽네요ㅜㅜ', 13, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '평소에 하드계열 식사빵 즐겨먹고 집에서도 시도하면서 만들어 먹을정도로 매우 좋아하는데 여기 사워도우랑 치아바타... 정말 맛있고 예술이에요... 남자친구도 하드계열 빵 너무 좋아해서 같이 먹었는데 치아바타 껍질에서부터 감동받았습니다ㅎㅎㅎㅎㅎ 껍질에 생긴 발효 주름부터가 예술이에요ㅎㅎㅎ 사진에 사워도우는 없는데 저희 한입 물고 진짜 눈감고 음미하느라 정신없었어요... 다음날까지 맛있는 빵입니다ㅠㅠ 오픈 초기에 갔을때 빵 없어서 속상하게 돌아섰었는데 드디어 먹어봤네요ㅠㅠ 진짜 또갈게요... 예약걸고 가야지.... 웬만한 서울에 있는 사워도우 빵집보다 맛도 월등하고 가격도 터무니없지 않아요. 검암에 이런빵집이 있다는게 정말 놀라워요👏👏', 72, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '공휴일 저녁7시 조금 넘어서 방문하니 빵이 대부분 품절이었어요 플레인 깜빠뉴랑 올리브 치아바타 플레인 스콘 사왔어요 다음번엔 호두크랜베리랑 흑임자 먹으러 또 방문하려구오', 53, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '얼그레이스콘, 바게트 구매했어요. 이사오고나서 유기농밀, 천연발효, 당일판매, 무첨가 문구 보고 꼭 한번 ㄱㅏ보고싶던곳인데 드디어갔어요! 다른 양념(?) 없이 빵 자체가 맛있는 빵을 좋아하는 단순한데 까다로운 입맛이에요..! 스콘, 깜빠뉴 제일 조아하는데 딱히 소문난곳 가도 별로엿어오..ㅠㅠ 근데 여긴 진짜 맛있네요!!  얼그레이 스콘은 향이 은은하게 나면서 촉촉한 스콘인데 끝맛도 부드럽구요. 원래 퍽퍽 스콘 조아하는데 여긴 촉촉한데도 맛있어요. 빵을 정말 “잘”만들기위해 노력하시는것같아요. 항상 애용하고싶습니다^^ 좋은 빵 만들어주셔서 감사해용 ㅎㅎ 담주 캠핑 갈 때 꼭 사가야겟어요!흑임자깜빠뉴 먹어볼래여! 아침에 커피랑~~~😍', 14, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '건강한 맛 ! 맛있어요 ㅎㅎ 다른 빵들도 먹어보고 싶어요 ~~! 살짝 시큼하긴한데 원래그렇다더라구요 쫄깃하고 맛있네요 빵 보관법도 알려주시고 친절하셔요 ㅎㅎ', 37, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '처음 방문했는데 사워도우 처음이라니까 사장님께서 친절하게 설명해주시고 추천도 해주셨어요!! 처음이라 전부 맛보고 싶어서 세종류 다 구매해봤는데 다 맛있어요ㅠㅠ 왕추천..제발 먹어쥬세요 진짜 담백, 고소, 겉바속촉 장정 다 가지고 있어요!! 식사빵이라 식사하기 힘든분들한테도 너무 좋을거 같아요 ㅎㅎ', 3, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '쟁여놓고 먹으려고 많이 사왔는데 빵 크기도 실하고 너무 맛있어요.. 특히 흑임자는 구수하고 크랜베리!! 스콘은 꾸덕 꾸덕 한게 데워서 우유랑 먹으니 너무 맛있구용… 빵은 냉동실 뒀다가 렌지에 데워먹으니까 더 쫀득촉촉 한게 맛있네요 ^^', 46, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '건강한 빵이 이렇게 맛있다니ㅠㅠ심지어 크기도 커요! 크랜베리 최애 흑임자는 완전 꼬소 통밀은 호두까지 들어서 감동ㅠㅠ빵에서 사장님 정성이 느껴져요!! 자주 갔는데 리뷰는 처음 쓰네요! 보관도 쉬워서 쟁여놓고 떨어지면 바로 갑니다ㅎㅎ스콘도 엄청 맛있어요!!', 33, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '빵이 크다는 생각은 안들어요! 근데 굉장히 무거워서 비싼것 같지는 않아요! 앙버터랑 잠봉뵈르 너무 맛있고 통밀 두종류 샀는데 둘다 너무 맛있어요!', 37, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '저는 이런빵 처음으로먹어본사람 입니다 ㅋ그런데 겉는바삭속은 촉촉 ~진짜  ㅋ제스타일 ㅋ왕버터 진짜버터에 고소함과 팥는 그렇게 달지도 않으면서  정말 맛있게 먹어습니다 거기계신 분들도  엄청진철 하시더라고요  정말 맛있게 잘먹어습니다ㅋ다먹고  ㅋ조금낭아서  사진올릴입니다~', 37, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '검암에도 이런 빵집이 생기다니 좋네요. 겉은 딱딱 고소하고 안에는 부드럽고 고소한 질감좋은 빵!! 스콘도 부드럽고 맛있고요 ㅠ 맛이 뭐랄까 담백한데 고급져요. 맛집이 별로 없는 동네라 뭐 먹고픈거 있으면 청라나 다른 동네 가서 픽업해와야 했는데 빵집은 그럴 필요없을 것 같아요~ 사장님께서 조곤조곤 설명도 잘 해주셔서 좋았습니다.', 2, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '처음가봤는데 시식빵도 주셔서 너무 감사했습니당 겉바속촉...쫀득빵이에요ㅠㅜㅠ 샌드위치 양도 많은데 맛도 좋아요. 통밀은 쫀득쫀득해서 너무 마음에 듭니당 포장지마저 환경친화적....', 11, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '소화가 잘되는 건강한 빵이라니!! 왔다갔다하면서 기웃기웃 쳐다만 보다가 처음 방문했어요~ 맛과 건강 다 잡았어요! 친절하게 설명감사해요 앞으로 자주갈게요^^', 67, 14, 'GOOD', SYSTIMESTAMP);
