INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '플레인 사워도우 껍질이 질기긴 하지만 속이 촉촉하고 쫄깃해요. 중량도 꽤 나가서 이 가격이면 저렴하게 잘 먹을 수 있어요. 그리고 플레인 스콘이 정말 맛있어요.. 스트레이트 티랑 같이 먹으면 행복해요.', 52, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사워도우 랩'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '사워도우 깜빠뉴와 바게뜨 둘다 겉바속촉. 그냥 먹어도 살짝 시큼하면서 쫄깃한 식감이 일품. 올리브발사믹 소스 만들어서 먹다보니 남아있는게 없네요. 원하던 빵집이 드디어 생겨서 너무 좋네요.', 77, 13, 'GOOD', SYSTIMESTAMP);
