INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '요즘 말차가 대세라서 한 번 시켜봤는데, 역시 선택 탁월✨ 녹차라떼는 진하고 부드럽고, 녹차 푸딩도 말차 특유의 쌉싸름함과 달콤함이 조화로웠어요. 인테리어도 한몫해요. 마치 제주도에 온 듯한 분위기 덕분에 힐링되는 느낌 🍃상수에서 감성 가득한 카페 찾는 분들께 추천하고 싶어요.', 20, 7, 'GOOD', SYSTIMESTAMP);
