INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '돌하르방은 비주얼때문에 시켰기도 하고 양갱을 별로 좋아하는 편은 아닌데 의외로 맛있게 먹었네요! 스무디도 상큼하고 맛있었어요~ 초록초록 식물들과 현무암때문에 제주도 느낌도 낭낭해서 사진찍고 놀면서 힐링하기도 좋아요! 잘 먹고 갑니다:)', 47, 3, 'GOOD', SYSTIMESTAMP);
