INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '디저트에 제주도를 담아내다. 카페 입구부터 제주풍으로 뒤덮힌 이곳은 디저트까지 제주도를 담아낸 특색 있는 카페에요. 지하에는 분위기 좋은 공간부터 안에 하나하나 포토존까지 ! (심지어 방탈출도 진행한다네요) 음료는 커피를 마셨고 원두도 선택 가능하니 고르시면 될것 같아요 ㅎㅎ 디저트로 푸딩과 아이스크림을 시켰는데 달달하고 제주 느낌이 강한게 매력적이에요 ㅎㅎ 한번 방문해보시면 후회는 없을것 같아요 :)', 91, 24, 'GOOD', SYSTIMESTAMP);
