INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '갤러리 공간 안에 들어온 듯한 느낌!🍀 이색적이고 분위기있는 공간입니다 ㅎㅎ 생각보다 조용하고 조도가 낮아서 나즈막히 진솔한 친목을 했어요 제주도의 느낌있는 우도땅콩아이스크림, 현무암💕', 15, 3, 'GOOD', SYSTIMESTAMP);
