INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '삼다코지에서 미니방탈출 패키지를 예약해서 짧은 방탈출을 마치고 맛있는 디저트를 먹었어요 🍊 방탈출은 작은 볼륨이지만 그 이후 진행했던 뽑기에서 1등을 뽑아서 너무너무 예쁜 제주바다를 담은 레진 트레이를 득템했네요! 😁😆 커피가격은 좀 있는 편이지만 카페 인테리어도 굉장히 예쁘고 볕이 잘드는 테이블들도 많아서 방문하기에 꽤 괜찮은 제주분위기의 홍대 핫플입니다 🩵', 23, 9, 'GOOD', SYSTIMESTAMP);
