INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '제주도 분위기의 지하와 지상으로 되어있구 내부가 넓어요. 밀크티에서 라벤더맛이 나서 특이한 밀크티네요. 흑임진 양갱도 신박하고 좋아요. 분위기도 좋고 또 올게요.', 92, 21, 'GOOD', SYSTIMESTAMP);
