INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '이름에서 알수있는거처럼 제주도 컨셉의 카페인데 크기에 비해서 좌석이 그렇게 많지는 않아요. 초당옥수수아이스크림이랑 우도땅콩 아이스크림 맛있게 먹었습니다. 사진찍는거 좋아하는 사람이 오면 좋아할거 같아요.', 9, 0, NULL, SYSTIMESTAMP);
