INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '우와~ 어무 이쁜 카페를 발견했네요~♡♡ 크리스마스 분위기를 한껏 살려주는 자연친화적 느낌! 진짜 제주도인줄요~ 메뉴도 그렇지만 분위기가 너무 독특하네요~ 저는 말차라떼 먹었는데 정말 맛있었는데 식을 수록 우유 비릿함이 생기기 시작했던거 같아요~ 그리고 초당크림라떼는 음~ 맛있었는데 강릉에서 드신 분들은 음~ 저와 같은 반응 ㅋㅋㅋ 그런데 와플은 진짜 맛있었어요~ 아이스크림도 너무 쫀득하니 맛나고 와플도 식감이며 맛이며 너무 완벽했어요~ 사진찍으러 가도 될 만큼 이쁜 곳이에요!!', 44, 8, NULL, SYSTIMESTAMP);
