INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '합정역 데이트한다면 꼭 한번 추천하고싶은 연말 분위기 뿜뿜한 이색장소! 삼다코지를 소개합니다. 다른 카페와 다르게 다양하고 이색적인 디저트와 음료! 그리고 맛있는 독특함까지! 자세한게 궁금하시다면 영상을 확인하세요! 많은 맛집 정보가 궁금하신 분들은 네이버에 후니맛블을 검색해보세요! https://m.blog.naver.com/seonghun39', 36, 1, NULL, SYSTIMESTAMP);
