INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '예뻐요 트리 이뿜 포토존 잘해놨어요🎄💛 근데 이제 거울 관리가 안되는 겉에 트리 너무 크고 예뻐요🎄❤️ 근데 이제 뒤가 공사장 뷰인 안에 트리들 보기 좋아요 근데 이제 사진찍긴 사람밭인 주말 3시쯤 갔는데 겨우 앉았고, 못 앉는 사람 꽤 봤어요 음식 특이해요 달고 제 취향엔 안맞았습니다 아포카토 < 저거 포토존 이용비 16,4 나쁘지 않았어요', 2, 10, NULL, SYSTIMESTAMP);
