INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '무료체험도 너무 좋았는데 매장도 너무 이쁘고 제주특색 음료와 디저트가 있어서 더 좋았어요!! 트리도 멋지고 지하공간 진짜 독특했어요~ 직원분들도 친절하고 평일이라 그런지 한산해서 편히 즐기다왔습니다^^', 47, 6, 'GOOD', SYSTIMESTAMP);
