INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '방탈출이 가능한 카페는 처음 봤어요 귀여운 방탈출을 끝내고 아기자기한 제주 테마로 쭉 연결된 음료와 디저트까지 먹으니 근사한 코스를 마친 것 같은 느낌 ㅎㅎ 강추~~', 21, 1, 'GOOD', SYSTIMESTAMP);
