INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '예쁘고 예쁩니다! 늦은 밤이라 사람이 적어서 쾌적하게 잘 앉았고 커피를 못마셔도 마실 수 있는 다양한 음료가 많아서 좋았습니다.', 38, 4, 'GOOD', SYSTIMESTAMP);
