INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '삼다수와 폐 페트병을 재활용 한 비즈들을 가지고 장식을 만들어 보는 좋은 시간을 보낼 수 있었어요. 음료도 맛있네요 비싸지만.... ㅠ', 15, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '인터넷에서 찾아서 방문하게됨  커피 한잔에 5900원  커피 맛있음. 그래서 따뜻한거 마시고 아이스로 한잔 더 시킴  그리고 핸드폰 충전가능한지 물어봄 일하시는 직원분 대답 진짜 기분나쁨 불친절함  여기는 핸드폰 충전안해드려요 이게 끝  말투 자체가 불친절 충전 안해줄수 있죠 근데. 진짜 말투 불친절 이거 뿐만 아니라 기본적인 손님응대 직원들 불친절  커피맛있어서 오늘 처음방문하고 또 오자고 했었는데 다신 안올거임  그리고 자리없어서 돌어 앉아 있었는데 손님이 나가시면서. 저기 앉으라고 친절히 안내해주심 손님이 친절하심', 65, 13, 'BAD', SYSTIMESTAMP);
