INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '엄마랑 휴무에 좋은 데이트 했습니다. 제주도 간 것 같은 기분 좋은 실내 디자인이 좋고 디저트들도 특색있게 맛있었습니다. 부모님과 식사하고 가기 좋아용', 98, 22, 'GOOD', SYSTIMESTAMP);
