INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '곶자왈 크림라떼 맛있어요! 녹담만설도 넘 맛있게 잘 먹어서 추가로 초당 옥수수 푸딩도 주문해서 먹었는데 ㅎㅎ 넘 맛있어요!!👍🏻✨ 오랜만에 정말 맛있는 푸딩을 먹어서 행복한 하루였습니다!☺️', 32, 0, 'GOOD', SYSTIMESTAMP);
