INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '초당옥수수푸딩이 엄청 달달하면서 맛있었어요! 삼다수 물로 만든 커피라는데 약간 쌉싸름한 맛?? 분위기는 전체적으로 너무너무 좋지만 밖에 있는 자리는 웬만하면 비추예요… 나무 근처라서 모기가 엄청 돌아다니더라구용 ㅋㅋㅋㅋㅋ', 72, 12, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '카페어서 처음 체험이라는 것을 한것같아서 너무 좋았습니다. 재활용이 이렇게 깨끗하고 이쁜 제품을 탄생시킬수있다는 것에 다시한번 놀라움을 느끼며 왔습니다^^ 키링은 저희딸이 좋아하네요^^ 감사합니다!!', 18, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '일요일 오후 방문했는데 운이 좋게 있던 한 자리에 앉았습니다! 초당옥수수라떼 그냥저냥 무난했어요. 과자 같은 딱딱하고 오독오독한 콘 알갱이들이 얹어져 있었습니다. 곶자왈 크림라떼(말차) 시킨 일행은 맛있다며 잘 마시더라고요. 귤빛찬란 디저트도 함께 주문했는데 시키길 잘했다 싶을 정도로 만족스러웠어요! 요거트와 아이스크림, 시리얼처럼 버석버석한 식감의 토핑이 잘 어우러져 앉은 자리에서 순삭했습니다 ㅎㅎ 귤맛이 상큼하면서도 과하게 달지 않아 맛있었어요!🍊', 116, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '이 포토존들을 보고... 이건 너---무 잘왔다 싶었어요. 여기 찾은 내 자신 칭찬해💖 ✔️ 애견동반도 가능한 대형카페인데.. 포토존도 잘되어있어!! 데이트로 여기 데려온다? 여자친구 하루종일 기분좋게 만들 수 있음(사진을 잘 찍어준다는 전제) ✔️ 제주감성이라 특별한 제주특성을 잘 살린 귤 메뉴가 많아서 궁금해서라도 먹어보게 됨. ✔️ 숨겨진 지하공간... 무조건 가보세요. 내가 볼 땐 삼다코지는 지하가 찐임.', 20, 4, 'GOOD', SYSTIMESTAMP);
