INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '음료랑 디저트 맛있었습니다. 그런데 자리가 너무너무 불편해요. 대부분의 좌석이 의자보다 테이블이 낮아서 디저트나 음료를 집을 때마다 허리를 숙여야 합니다.', 31, 0, NULL, SYSTIMESTAMP);
