INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '제주도를 옮겨온 느낌이 낭낭한 멋진 카페에요~! 디저트도 특별하고 메뉴들도 다 한번씩 먹어보고 싶어지는 곳입니다👍🏻 홍대쪽을 온다면 방문해보길 추천해요~!', 16, 10, 'GOOD', SYSTIMESTAMP);
