INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '건너건너 아는분이 인테리어 한곳이래서 들렸어여! 넘 멋지더라구요 우도 아포카토는 커피가 너무 좀 써서 다 먹진 못했어여 그래도 분위기는 좋아여~', 70, 18, NULL, SYSTIMESTAMP);
