INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '드디어 와본 삼다코지!! 기대이상으로 디저트가 맛있었어요!! 톡톡 씹히는 식감이 너무 좋았도 맛있었어요!! 뭔가 힐링되는 분위기 잘 즐기다 갑니다!!', 5, 5, 'GOOD', SYSTIMESTAMP);
