INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '가게가 너무 예뻐요~! 포토존도 있어서 카페 와서 소소하게 사진 찍기도 좋을 것 같고, 야외테라스도 있어요. 메뉴도 독특하고, 이번에는 차는 안 시켰지만 이 가게에서만 먹을 수 있는 차가 있는 것 같더라구요! 차 좋아하시면 한 번쯤 와보실만 합니당 화장실도 깨끗해요~!', 58, 11, 'GOOD', SYSTIMESTAMP);
