INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '눈으로도 입으로도 너무 만족스러운 곳입니다! 제주보다 더 제주 스럽구요, 모두 감귤메뉴로 시켜보았는데, 각각의 특색있게 맛있네요! 요즘처럼 덥고 꿉꿉한 날 특히 강추! 합니다!', 35, 3, 'GOOD', SYSTIMESTAMP);
