INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '인테리어가 정말 매력적이고 커피도 맛있어요!! 삼다코지만의 메뉴가 특색있어서 좋고 구경하기에도 쉬기에도 좋은 것 같습니다 ㅎㅎ', 53, 15, 'GOOD', SYSTIMESTAMP);
