INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '와 인테리어 최고! 너무 예쁘고 커피랑 디저트도 너무 맛있어요.💛 다음에 또 올게요 단골이 될 거 같아요.!! 홍대에서 느끼는 제주도 바이브 최고!!!', 27, 6, 'GOOD', SYSTIMESTAMP);
