INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '임영웅 생일카페로 이용한  삼다코지 전철역에서  찾기는  살짝  힘들었어요 기대한만큼  준비해주신  미션들이 재밌네요 찾아가실 별빛님들도  즐건  시간되세요 건행ㄱ 💙 특히 폴라로이드 짱 행복해요!', 31, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '겉치레로 아늑하지 못한 카페 그리고 음료…자리는 많은데 앉고 싶은 곳이 하나 없어서 들어오는 손님마다 헤매느라 바쁨..커피는 진하고 맛있음. 다음엔 제주컨셉 디저트 시도하고싶음.', 23, 10, 'BAD', SYSTIMESTAMP);
