INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '매장도 깨끗하고  일하시는분들도 친절하고 돼지갈비도 부드럽고 맛있어요 ^^ 서비스로 나오는 된장찌개  칼칼그자체  개운하고 맛있습니다  또 들르겠습니다^^', 69, 18, 'GOOD', SYSTIMESTAMP);
