INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '인테리어가 예쁘고 제주도 느낌이 너무 좋았어요 지금은 유채꽃이 있어서 사진찍기 좋았어요 ㅎㅎ 음료 이름이 로맨틱제주 제주햇살스무디🍹 감성적이고 상콤달콤 맛있어요', 16, 2, 'GOOD', SYSTIMESTAMP);
