INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '좌석 너무 불편하고..이상한 냄새도 나요..예쁜 사진 찍고 싶으면 추천! 쉬러 예쁜 카페 가고 싶으면 비추천입니다~직원분들끼리 수다도 너무 떨어서 시끄러워요..', 2, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '제주도로 떠나고 싶지만 현생에 치여 갈 수 없을때!✈️ 조금이나마 위안삼아 제주감성 삼다코지를 찾아왔어요🩵 입구부터 포토존 가득! 이층에 있는 작은 미디어아트까지! 힐링 제대로 하고왔어요🫶🏻🌿 벌써 세번째 방문하는 삼다코지입니다.💖 돌하르방 양갱은 귀엽고 맛있어요🫶🏻 모든 재료에 들어가는 물과 얼음은 제주 삼다수라고 해요!', 80, 17, 'GOOD', SYSTIMESTAMP);
