INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '홍대 속 제주도에 온 기분!! 확실히 아이덴티티가 강한 카페에요! 제주도가 컨셉이라 곳곳에 돌도 있고 전시회 온 것처럼 빔도 있고 각 층마다 분위기가 너무 색달라요! 음료도 맛있었고 물도 삼다수 페트로 비치되어있더라구요 ㅎㅎ 신기했어요!', 5, 1, 'GOOD', SYSTIMESTAMP);
