INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '디저트로는 제주산 팥으로 만든 담백하고 고소한 #돌하르방🗿 양갱 산타 돌하르방인데 넘나 귀엽죠❤️ 고민하다 하나 더 시킨 #우도땅콩아이스크림🍨 제주 한아름 목장에서 방목해 기른 건강한 젖소의 우유로 만든 아이스크림 위에 고소하게 볶아진 우도땅콩이 듬뿍🥜 귀여운건 돌하르방이지만 맛은 우도땅콩아슈크림이 맛있네요🍦 지금보니 고소한 생크림과 제주 성읍에서 재배된 말차로 부드럽게 굳혀낸 푸딩인 녹담만설도 먹어보고 싶네요🍮🍃 크리스마스 트리도 넘 이뻐요🎄❤️', 14, 9, 'GOOD', SYSTIMESTAMP);
