INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '카페 인테리어 너무 이쁘고 분위기도 너무 좋았어요! 뎅유자라떼는 살짝 씁쓸한 유자청이 들어간 크림 라떼였는데 조합이 오묘하고 너무 맛있어서 집에 와서도 계속 생각 나더라구요! 친구는 따뜻한 녹차크림라떼를 시켰는데 텁텁하지 않은 적당히 고소한 맛이었습니다! 비주얼 미친 푸딩까지 냠냠ㅠㅠ 담에 또 방문할게요!!!', 117, 20, 'GOOD', SYSTIMESTAMP);
