INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '제주 컨셉 좋네요~ 제주여행 추억도 솔솔.. 여기저기 포토존도 있고^^ 전 겨울차세트 주문했는데 은은한 차향기 넘 좋았어요~ 직원분도 넘 친절하시고.. 은근 볼일 있어 오늘은 혼자 왔는데 다음엔 친구랑 또 올 예정이네요~', 103, 26, 'GOOD', SYSTIMESTAMP);
