INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '시그니처 음료가 사진찍기 가장 좋았어요 루피가 만든 카페인가 싶을 정도로 루피가 많았습니다 ㅎㅎ 단체로 가기엔 앉을 곳이 마땅치 않아요 단체석은 테이블이 낮아서 허리가 아프지만 한번쯤 와볼만 합니다. 음료는 맛있어요! 가격대비 양은 작지만 잠깐 제주를 느끼기에 좋습니다.', 115, 25, 'GOOD', SYSTIMESTAMP);
