INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '합정에 있는 제주도 분위기 물씬 나는 삼다코지 카페에 다녀왔어요 ! 야외 테이블은 반려동물과 사용가능하며 각 층마다 컨셉이 달라서 흥미로웠어요 음료 가격이 비싸서 아쉬웠지만 색다른 컨셉 음료들이 있었고 제주 삼다수 물도 선물로 드리니 챙겨가세요 ☺️', 63, 12, 'GOOD', SYSTIMESTAMP);
