INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '커피도 맛있고 제주도 분위기로 꾸며져서 너무 예뻐요~! 크리스마스 트리도 꾸며져있어서 연말분위기로 좋고 잔망루피 전시회도 하고 있어서 귀엽네요~.~', 19, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '합정 핫플🩷🩷삼다코지!!! 합정 크리스마스 분위기 즐기기에 넘나 좋았던 카페🎄입니당 게다가 귤귤귤이랑 드립커피가 진짜 맛잇어요,,녹담만설이라는 녹차푸딩도 여기서만 맛볼 수 있는 디저트👏🏻사진도 진짜 잘나오고 홍대대형카페로 강추합니다~~ 다른 음료랑 디저트 맛보러 또 올래요', 15, 5, 'GOOD', SYSTIMESTAMP);
