INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '완전 제주 느낌이고 음료과 디저트가 너무 맛있어요. 돌하르방은 너무 귀엽고 너무 맛있어요. 담백한 양갱의 맛과 하르방의 귀여움에 완전 제주 느낌의 맛을 느낄 수 있어요. 제주 여행도 생각이 나네요 ..', 75, 17, 'GOOD', SYSTIMESTAMP);
