INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '인테리어가 너무 멋있어요! 특히 앞에 트리에서 사진 무조건!! 안에도 사진스팟이 많아서 좋았어요. 음료는 비싼편이지만 한번쯤 방문하기 좋아요.', 41, 1, NULL, SYSTIMESTAMP);
