INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '어느 카페를 갈까 서치하다가 제주도 컨셉 너무 좋고 인테리어가 멋져서 방문했는데, 생각지도 못하게 루피 콜라보 기간에 얻어 걸려서 더 즐겁게 있다 갑니당!! 음료도 맛있어요!!', 4, 7, 'GOOD', SYSTIMESTAMP);
