INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '이런곳이 숨어있었다니 ! 인테리어 넘 멋지고 음료도 찐으로 맛나요 가격이 좀 있지만 저녁에 칵테일 먹으러 가기도 분위기 좋고 낮에도 이뻐요 :)', 42, 8, 'GOOD', SYSTIMESTAMP);
