INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '인테리어가 너무 멋지고 지하는 조금 어두우면서 물소리 들을 수 있구 2층은 밝고 이쁜 트리가 있었어용! 무엇보다 커피 향이 너무너무너무 좋아요 맛있어요!! 잘 데이트 하다가 갑니다:)', 75, 11, 'GOOD', SYSTIMESTAMP);
