INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '매장 너무 예뻐서 놀랐어요 !!! 컨셉 진짜 좋고 힐링하고 갑니다 ㅠㅠㅠㅠㅠ 차도 맛있고 비싸지만 공간값한다는 느낌이 들었습니다 ㅎㅎ또 가고싶네용', 42, 5, 'GOOD', SYSTIMESTAMP);
