INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '합정 홍대 어기 금방 카페들중에 가장 멋드러진 곳 이네요. 제주 모티브로 된 인테리어가 정말 훌륭해요. 인테리어만으로도 좋은데, 핸드드립 커피 맛...바리스타분이 엄청 실력 좋고 친절하셨어요. 디저트류도 독특해서 방문하길 잘했단 생각이 들었답니다. 추천해여!', 15, 8, 'GOOD', SYSTIMESTAMP);
