INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '그냥 지나칠 수 없는 주택개조 큰 건물에 안으로 들어가면 더 멋있는 삼다코지! 꼭 가보세요💚모든 곳이 포토존👍🏻 진짜 제주도 온 것같은 인테리어와 식물들이 많아서 쾌적하고 층마다 테마가 달라요 지하공간은 잊지말고 꼭 가보세요 디저트랑 음료도 제주스러움 가득이라 뭘 먹을지 고민하다가 우도 땅콩아이스크림,귤귤귤,돌하르방 시켰는데 다 맛있어요😉', 18, 3, 'GOOD', SYSTIMESTAMP);
