INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '제주도 컨셉답게 들어가자마자 귤이 한콘테 있었습니다. 겉으로 보기에 매장이 넓어보였는데 생각보다 앉을 수 있는 자리는 별로 없었어요. 그래도 음료랑 디저트가 맛있고 독특했어요. 심지어 이쁘기까지 해서 기분이 좋았습니다! 내부는 좀 어둡고 테라스는 기분 좋게 밝아요.', 7, 4, 'GOOD', SYSTIMESTAMP);
