INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '좌석이 층마다 조금조금씩 나누어져 있어서 골라 앉는 재미가 있습니다. 가격대는 조금 있으나 사진찍기에 좋아서 그 값한다 생각했어요:) 푸딩은 말차맛이 살짝 약해서 아쉬웟어요!', 5, 5, 'GOOD', SYSTIMESTAMP);
