INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '늦은시간이라 검색해서 11시까지 영업인 카페로 들어왔는데,, 10시 라스트주문이래서 주문하니 10시30에 홀마감이라고 나가라고하네요 ㅋㅋ 다먹지도못하고나갔어요 ㅜㅜ', 2, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '완전 제주도 인스타 갬성카페를 그대로 서울에다 옮겨놓은 느낌이었어요.ᐟ.ᐟ  분위기도 제주느낌, 가격도 제주도 카페가격 그대로^_^ 그래도 직원분들 왕 친절 하시고 음료도 맛있고 사진도 잘나와서 만족하고 갑니당◡̈', 37, 10, 'GOOD', SYSTIMESTAMP);
