INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '아이유 생일 이벤트 한다고 해서 방문했는데 특전은 다 소진되어서 못받았지만 그래도 2층에 아이유 사진이 너무 이뻐요!!! 우도 땅콩 아이스크림 먹었는데 땅콩가루 너무 고소하고 맛있네요:) 🥜🍦 서울 속의 작은 제주도 느낌🏝', 51, 15, 'GOOD', SYSTIMESTAMP);
