INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '제주도 느낌이라 검은색 톤과 화강암과 야자수 나무가 멋져요. 의자는 딱딱하고 불편하고 테이블이 몇개 안되요 커피 원두는 두가지 맛이 있고 맛있어요.', 32, 3, 'GOOD', SYSTIMESTAMP);
