INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '제주도가 느껴지는 특색있는 카페에요 워낙 규모가 큰 탓이겠지만 구석구석 세심한 관리가 조금 아쉽다는점 크게 신경써서 만든 공간인만큼 좀더 관리가 잘되었음 좋겠어요', 119, 20, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '제주 컨셉 카페 삼다코지에 우연히 지인따라 방문해봤는데 인테리어도 그렇고 분위기가 완전 제주여행온듯한 느낌이었습니다. 시그니처 로맨틱제주 한잔 마셨는데 붉은색이 딸기? 인줄 알았는데 마셔보니 그런 맛은 아니었고 생각보다 맛있는 에이드였습니다. 날씨가 좋은 날에 채광도 좋고 카페 내부에 포토존도 많아서 다음에 기회되면 다시 방문해봐야겠습니다', 26, 2, 'GOOD', SYSTIMESTAMP);
