INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '제주도 컨셉의 독특한 카페. 힙한 건 좋지만  자리가 좀 심하게 불편합니다. 대부분이 카운터석이고 테이블석은 테이블이 의자 높이보다 낮은지라 도저히 앉아서 뭘 먹고 할 수가 없습니다. 오래 앉아있는 게 싫은 건 이해하는데 이 정도면 그냥 장사를 안 하는 게 맞을 것 같습니다. 메뉴 맛은 나쁘지 않지만 도저히 추천하기 어렵습니다.', 7, 9, 'BAD', SYSTIMESTAMP);
