INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '우선 들어올 때부터 웅장한 느낌이고, 인테리어 너무 예뻐요 ◡̈ 응대해주시는 직원분이 친절하셨고, 우선 디저트 음료가 너어어어무 예뻐서 나온 순간 힐링이었습니다ㅠㅠ 진짜 제주에 온 것 같은 인테리어 디저트 음료였어요! 제주 제품으로 다 만드는 것 같더라구요! 따로 청이나 밀크티나 티백도 팔고 있었어요 잠시나마 제주도를 즐기다 갑니다 ◡̈', 48, 8, 'GOOD', SYSTIMESTAMP);
