INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '매장 인테리어부터 음료,디저트까지 힐링하고 갑니다:) 제주도에 온 것처럼 분위기가 편안하고 캄다운 되는 것 같아 종종 힐링하고 싶을 때 오면 좋을 것 같아요! 더불어 음료랑 디저트는 너무 맛있네요~ 담에 또 올거에요', 25, 8, 'GOOD', SYSTIMESTAMP);
