INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '제주 컨셉에 삼다수로 음료를 만들고 디저트도 제주에서 유명한 우도 땅콩이나 귤 등으로 디저트를 만드는 카페예요~^^ 저는 성산일출이라는 신맛이 덜한 원두로 맛을 낸 아아를 먹었고 같이 간 동생은 카페라떼 먹고 우도 땅콩이 든 아이스크림을 먹었는데 견과류 들어간 디저트 좋아하시는 분들은 한번 먹어보셔도 좋을같아요~^^ 지하에 동굴 느낌의 공간이 있었는데 나올 때 알아서 못 가봐서 아쉽네요~ 담에 방문하면 꼭 가봐야겠어요~^^', 43, 10, 'GOOD', SYSTIMESTAMP);
