INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '삼다수 플래그스토어답게 제주 느낌 가득한 인테리어와 메뉴가 돋보이네여. 귤빛찬란은 건조한 귤이 올라가서 바삭바삭 넘 맛있어서 여름에 또 생각날 것 같아요.', 30, 4, 'GOOD', SYSTIMESTAMP);
