INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '2:45분경 여자알바 교육좀 똑바로 시키시길 아메리카노 주문하니까 원두 고르라고 하길래 어디있는지도 모르겠어서 어디있어요? 물어보니 메뉴판 보고 결정하라길래(이 때 부터 좀 이상) 밑에 메뉴판 보니까 밀크 초콜릿이 어쩌고 쓰여있는데 이건가 싶어서 죄송한데 뭐가 원두냐고 물어보니까 메뉴판 보고 알려달라고(무슨 AI인줄) 그래서 정말 죄송한데 어디있는지좀 알려주실 수 있나요? 여쭤보니 한숨 푹 쉬면서 메뉴판 들고가서 손으로 툭 가리키면서 여기서 선택해 주세요 이러는데 무슨 맛인지 어디 원두 쓴건지 본인이 간단하게 설명도 못할거면 카운터에 왜 서있는지 의문임..보통은 몇가지 종류가 있고 이중에 선택해주세요 할텐데도 끝까지 메뉴판 보고 결정해주세요 이러고 앉아있음 이럴거면 키오스크 갖다 놓으시길;;기분 잡침', 78, 15, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '인테리어 너무 예뻐요! 2층에는 거울 포토존 사진 굿! >.< 디저트도 너무 달지않고 담백하니 딱 좋았습니당. 가격대는 좀 있는편이고 자리는 좀 불편하긴 해요. 좌석수가 그렇게 많은것도 아니구요! 사진이 너무 예쁘게 잘 나와서 만족~', 44, 0, 'GOOD', SYSTIMESTAMP);
