INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '🍊제주느낌 가득한 삼다코지에요. 👍지하,1층,2층까지 좌석이 있어 공간이 쾌적합니다.🌱시그니처메뉴들은...기막히게 맛있다 우와아아아!!!! 이런건 아니지만,눈으로 만족하기 되는 비주얼이에요🥰제가 시킨 메뉴는 녹담만설(녹차 밀크푸딩)과 삼다댕유지차 입니다.🍮 썸녀나 사진찍기 좋아하는 친구와 가는 걸 추천해요!', 124, 25, 'GOOD', SYSTIMESTAMP);
