INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '비오는날도햇빛이 좋은날도 언제든 방문하면 만족할 카페입니다 여기와서 사진찍고 제주도 갔다왔다해도 믿을 것 같아요 ㅋ_ㅋ 제주가 가득 담긴 다른메뉴들도 먹어보고싶어요', 21, 3, 'GOOD', SYSTIMESTAMP);
