INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '주문받아주신 남자직원분이 메뉴설명이랑 추천을 잘해주셔서 맛있게 잘 먹었어요^^! 푸딩 이쁘기만게 아니라 맛도 좋네요 근데 편하게 앉을 수 있는 자리가 하나도 없네요.. 오래앉아있기 힘들어서 메뉴만 먹고 나왔어요ㅠㅠㅠㅠ 의자 넘 아쉽', 35, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '아이유 생일 기념 이벤트 할 때 처음 가봤어요. 매장 인테리어 너무 멋있고 모든 음료에 들어가는 물과 얼음이 삼다수라니 왠지 더 새로운 느낌이네요! 평소에 차를 좋아하는데 차도 맛있고 디저트가 독특해서 좋았습니다.', 47, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '제주도 컨셉이 독특하고. 디저트 메뉴들 비주얼이  신기해요 차도 커피도 맛있네요 공간도 아끼지 않고 인테리어하셔서 볼거리도 많아요', 34, 3, 'GOOD', SYSTIMESTAMP);
