INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '제주 감성잘 드러나고 인테라어도 예뻐요! 특색있는 메뉴들 우린 귤귤귤에이드와 아이스아메리카노 그리고 우도땅콩아이스크림이랑 돌하루방 맛있어요:)', 21, 5, 'GOOD', SYSTIMESTAMP);
