INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '전주에서 서울 놀러왔는데 분위기좋은  카페찾다찾다 이곳을찾게됬어요!제주도 분위기로 고급져서 좋았어요!! 커피도 너무맛있네요!산미도없규😆 잘놀다갑니다!', 37, 0, 'GOOD', SYSTIMESTAMP);
