INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '제주도 컨셉의 카페는 처음 가 봤는데 정말 제주도에 온 느낌이 들 정도로 인테리어나 분위기가 좋았어요~ 대신 4인 좌석이 적고, 테이블과 의자가 낮아 불편한 좌석도 있었어요..! 전체적인 메뉴 가격대는 많이 비싸요..ㅠ 그래도 비주얼과 맛이 정말 만족스러울 만큼 좋았어요~ 직원 분들이 디저트 먹는 방법과 다 먹은 그릇 두는 위치도 잘 알려 주셔서 서비스도 좋았어요! 가격은 비싸지만.. 제주 느낌이 많이 나고 서비스도 만족스러워서 다른 친구하고도 다시 한 번 재방문 하고 싶은 카페였어요~', 8, 10, 'GOOD', SYSTIMESTAMP);
