INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '가게 분위기 감성 정말 완벽하고 잠깐 제주도에 온 기분이에요. 디저트도 너무 예뻐서 사실 맛은 큰 기대를 하지 않았는데 녹담만설 푸딩은 탱글탱글 쫀득쫀득 녹차향도 진하고 정말 맛있었어요! 티세트도 구성이 좋고 맛있습니다. 다음에 꼭 또 오고싶어요!!ㅠㅠ', 9, 10, 'GOOD', SYSTIMESTAMP);
