INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '누군가의 추천을 받고 갔던 삼다코지 진짜 여기가 제주도보다 더 제주도같고 카페 돌아다니면서 와 와 거리면서 다닌건 오랜만인거같아요 시그니처메뉴들이 다 진짜 존맛에 넘 예쁨!!! 다만 문제는 2인 이상이면 좌석이 급격히 애매해짐..... 맥스 4명 아닐까 생각해봅니다. 바 좌석 상관없으면 갠찮을듯!! 4명이서 넘 잘 놀다왔어요 짱', 38, 9, 'GOOD', SYSTIMESTAMP);
