INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '가격대가 있습니다. 제주도 컨셉은 좋은데 특이한 맛이 있는것도 있어요. 전자기기 충전은 안되는 곳입니다.(카운터) 사진찍기는 좋은편이나 다시방문할것같진않아요.카운터 직원이 그리친절하지않았고...앉는곳도 부족', 120, 19, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '여기 밀크티 맛있어요! (달달한거 좋아하시는 분은 비추! 많이 달지 않아요😤) 밀크티랑 차는 맛있었는데 보리와플은 굉장히 별로였어요 🥲 너무 딱딱하고 퍽퍽해요.', 34, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '미리 알고 가시길 자리가 불편해요! 편히 앉아서 얘기하고 앉을 자리가 너무 없어요 ㅋㅋㅋ 근데 제주 컨셉에 맞게 잘 꾸며두셨고 메뉴들도 맛있었어요 우도땅콩아이스크림? 추천!!', 49, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '와... 제주도 온느낌!!  진짜 너무맘에 들어요ㅎㅎ 음료며 디저트도 너무이쁘고 디텔 하나까지 신경쓴 인테리어 취저입니닷!! 제주도 어느카페에 앉아있는 기분이였어요ㅎ 제주도 컨셉 카페들이 몇몇있지만 제가 가본곳 중에 여기가 최고ㅋㅋㅋㅋ 다음에 또 방문하려구요!', 49, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '제주를 그대로 옮겨놓은 것 같은 정말정말 예쁜 인테리어에 놀랐어요!!! 특색있는 메뉴들도 너무 신기했는데 맛도.. 너무너무 맛있었습니다.. 우도땅콩 아포가토랑 귤빛찬란 완전 강추합니다~!! 찾아보니 광동제약에서 삼다수 판매 사업을 하면서 제주와 삼다수를 담은 플래그십 스토어를 오픈한거라고 하던데 오래오래 흥했으면 좋겠습니다! ^_^', 38, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '손잡이가 세상 귀엽습니다‼️ 산미가 전혀 없는 커피를 즐기시는 분들에게는 산미가 좀 느껴질 거 같아요 😂 와플이나 디저트가 기본이상은 하는 거 같아요 맛있어요 ㅎㅎ', 8, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '제주의 컨셉에 맞춰 곳곳에 야자수 나무와 식물등으로 인테리어가 잘 되어있었고, 1층~3층까지 층별로 컨셉이 조금씩 다르게 구성되어 있어 사진찍는 것을 좋아하시는 분들은 좋아할것 같아요 :) 네모난 의자가 많은 편이라, 공부나 일하러 가기보다는 카페에서 쉼을 즐기러 가면 좋을것 같습니다~ 블렌딩 티세트도 구성이 좋아, 천천히 다과랑 같이 먹었습니다. 시그니쳐메뉴인 로맨틱 제주또한 너무달지않아서 적당하게 티맛을 음미하면서 먹을수 있어서 좋았어요!', 15, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '너무 예쁜곳이 많아 사진 고르기가 어려울 정도로 힐링 공간이었어요. 공간에 들어선 순간부터 여기가 서울인지 제주도인지 혼동이 올 정도로 도심 속 제주를 완벽 재현한 곳입니다:) 홍대 다니는 학생분들이 부러울 정도로 또 가고싶은 곳으로 2층 대왕 하루방 포토존은 꼭 들러보세요! 혼자서도 사진 찍을 수 있게 거울이 있어 충분히 즐길 수 있습니다! 덕분에 잠깐이지만 여행 다녀온 것처럼 힐링하고 왔어요~', 43, 6, 'GOOD', SYSTIMESTAMP);
