INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '홍대에서 즐기는 제주ㅎㅎ 특별한 메뉴가 있어 맛 보기 좋았어요 옹기종기 모여서 얘기할만한 테이블들은 없지만 컨셉이 특이해 즐기기 좋아영', 40, 10, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '색다른 음료가 다양해서 두번이나 방문했어요 처음 방문했을 때 영수증이 없어서 리뷰를 한번 밖에 못쓰는게 아쉬울 정도로 음료도 디저트도 너무 맛있어요ㅜㅜ!! 이색적인 음료와 디저트라 도전하기가 망설여졌는데 하나도 빠짐없이 다 맛있더라구요...! 이게 가능한가요! 정말 감탄했습니당 공간도 세련되고 제주도에 온 느낌 물씬나요 인스타에 올렸더니 다들 제주도 갔냐고 물어보네용 ㅎㅎ.. 상수에서 제주도 즐기기 좋습니다 호기심에 한번 갔다가 두번이나 재방문한 공간입니다 추천해요 ☺️', 24, 10, 'GOOD', SYSTIMESTAMP);
