INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '티세트 구성 너무 좋아요 디저트와 티까지 다해서 12,000원!! 그리고 티도 너무 예쁘고 맛있어요 지하1층에서는 핸드드립 커피도 주문할 수 있는데 어디서 주문해서 어디서 먹든 상관 없다하네요 핸드 드립 설명도 엄청 잘해주셨어요! 이번에는 2층에서 먹었는데 나중에는 지하에서도 먹어보고 싶어요 그리고 삼다수 +티 세트도 1500원에 판매하던데 궁금하긴하네여 다음에 먹어보거나 해야겠어요!', 37, 10, 'GOOD', SYSTIMESTAMP);
