INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '컨셉이 확실한곳 제주 느낌의 인테리어와 여러 포토존이 있어 너무 재밌는곳이에요 ㅋㅋ드립커피도 함께 시켰는데 관련업종에서 일하시는분 피셜 굉장히 커피도 잘볶았고 맛있다고 하네요', 40, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '도심 속 제주란 말이 궁금했는데, 진짜 제주를 옮겨놓은듯 했어요. 뷰 맛집 맞네요. 음료도 특색있고, 늦은 시간임에도 계속 손님들이 오더라구요. 홍대 이쁜 까페에서 사진찍기 좋아하는 딸램도 대만족했어요. 근처 가면 또 들르겠습니다.', 111, 25, 'GOOD', SYSTIMESTAMP);
