INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '지하1층 핸드드립바 정말 분위기 있네요! 원두에 대한 설명도 잘 해주시고, 무엇보다 삼다수로 내린 커피라 그런지 커피가 진짜 맛있어요🤍! 바리스타님도 정말 친절하시구, 재방문의사 완전 있어요. 홍대에서 이렇게 맛있는 커피는 오랜만! 커피 좋아하는 친구랑 또 올게요🤭', 38, 9, 'GOOD', SYSTIMESTAMP);
