INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '삼다수에서 만든 도심 속 제주! 제주를 느끼게 해주는 인테리어와 티세트가 정말 매력적입니다 계절별로 티 블렌딩을 다 맛보고 싶어요~ 좌석은 생각보다 많지는 않은 것 같아요!', 19, 3, 'GOOD', SYSTIMESTAMP);
