INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '제주 느낌의 신상 카페✨ 포토스팟 많고, 좌석은 많지 않지만 그래서 오히려 좋은 곳. 독특한 디저트들이 많음. 아인슈페너 느낌의 커피가 먹고 싶어서 시킨 삼다크림라떼는 귤맛이 났음ㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋ 설명 잘 듣고 시키시길!', 60, 16, 'GOOD', SYSTIMESTAMP);
