INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '디저트를 어떻게 먹어야하는지 친절하게 알려주시기도하고 매장 인테리어도 너무 예쁘고 사진 맛집입니다!! 코지 밀크티가 일반 밀크티보다 텁텁한 맛도 없고 너무 맛있어요!! 평일 오후에 갔는데도 사람이 많아서 좌석이 없는점.. 그만큼매장이 예뿌요!♡', 9, 1, 'GOOD', SYSTIMESTAMP);
