INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '제주도 방금 다녀온 느낌!! 현무암, 야자수로 꾸며진 외관부터 제주도 느낌이 물씬나고 내부는 세련된 미래의 제주도랄까? 음료랑 디저트도 수준급이고, 디저트는 아이디어랑 모양새도 이쁘지만 맛이 너무 좋아요. 돌하르방 양갱도 너무 달지않아 커피랑 마시기 딱이고, 녹담만설도 쌉쌀하면서 보들보들한 식감이 최고였어요!! 음료에 사용되는 물과 얼음이 제주 삼다수로 만들어진다고하는데, 음료와 디저트 모두 전체적으로 과하지않은 부드러운 맛이 맘에 들었습니다. 삼다수 컨셉으로 구성된 2층에서 만나는 제주 시청각실?에서는 종일있고 싶었네요ㅎㅎ', 9, 10, 'GOOD', SYSTIMESTAMP);
