INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '메뉴 사진을 보고 삼다수 플래그십스토어, 삼다코지를 방문했습니다. 층마다, 공간마다 독특한 인테리어와 좌석이 인상적이었습니다. 메뉴는 가격대가 있긴 하지만 비주얼과 맛 모두 만족스러웠습니다. 또 방문하고 싶네요:)', 26, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '야자수 좋아하는데 이렇게 서울 한복판에 야자수 카페가 있어 넘 좋아요!🌴 야자수 바라보며 앉을 수 있는데, 제주도에 온 것만 같아요. 그리고 핸드드립 커피는 정문에서 계단 살짝내려 와서 동굴같은 입구로 들어오거나, 옆편에 오픈된 문으로 바로 들어올 수 있어요. 이 공간이 천장과 기둥 인테리어가 반짝반짝 너무 이뻐요💫  인공폭포 흐르는 소리가 asmr처럼 듣기 좋아요', 50, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '생긴지 얼마안되서 정신없고 아직 테이블이나 이런게 정리가 안됫어요 ..... 앉을자리가 많지않음 ㅋㅋ사람은 많아요 인테리어이쁘고 진짜 제주도 느낌 많이나요~ 음료도 신기하고 맛은 보통! 사진많이찍는 여자분들 강추~', 31, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '와 홍대에 제주갬성을 담은 카페가 생겼다고해서 반신반의 하면서 와봤는데 진짜 제주도가 홍대에 있었음 ㅋㅋ 핸드드립커피랑 디자트들 시켜먹었는데 넘나 맛있었다능 ㅎㅎ 근데 직원분들 두분이서 열심히 만드시는데도 손님이 넘 먾아서 그런지 음식이 천천히 나오긴 했지만 기다리는 시간마저도 눈이 즐거운 공간이라 하나도 심심하지 않았다요 ^.3 다음에는 평일에 여유로울 때 와봐야겠더~', 15, 5, 'GOOD', SYSTIMESTAMP);
