INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '제주 컨셉의 인테리어와 디저트메뉴들! 모든 음료 제작에 삼다수 사용! 좌석마다 개성있어서 다음 방문엔 또 다른 자리에 앉아야겠어요! 직원분들도 바쁘신데도 친절😊😊 주문한 메뉴 하나씩 맛보고 눈이 3배나 커져버렸죠!! 진짜 다 맛있었어요😭😭 이 동네 오면 꼭 들르겠어요!!! 🥹😍', 39, 9, 'GOOD', SYSTIMESTAMP);
