INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '음료나 디저트 귀엽기만한게 아니고 맛도 있어요! 층수에 비해 자리가 많은편은 아니라고 느껴지긴했지만, 지하, 외부, 내부 인테리어가 다양해서 어디 앉느냐에 따라 분위기도 달라지는 것 같아요.', 85, 11, 'GOOD', SYSTIMESTAMP);
