INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '감성 맛도리! 땅콩 아이스크림 고소하구 로맨틱  제주의 장미가 좋았어요. 찐한 아메리카노도! 지하도 느낌 있구 포토존도 곳곳에 있어서 프사각 제대로였어요. 곳곳의 돌과 나무가 제주도가 아닌가 착각될정도. 그리고 삼다수를 기본물로 줘서 깔끔해서 좋았습니다.', 42, 6, 'GOOD', SYSTIMESTAMP);
