INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '제주도까지 멀리  안 가도 이 카페에 오니 제주 바이브를 느낄 수 있었습니다. 입구 쪽 공간은 좀 추웠지만 안쪽은 아늑하고 메뉴도 너무 예뻐서 사진 찍기 좋았어요', 7, 7, 'GOOD', SYSTIMESTAMP);
