INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '사진보니 예뻐서 다녀왔는데 정말 이뻤구 특히 지하에 동굴느낌인 곳이 정말 이뻤어요! 귤 아이스크림 디저트도 특이하고 맛있었어요👍🏻', 103, 21, 'GOOD', SYSTIMESTAMP);
