INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '매장 들어가다가 너무 예뻐서 깜놀!!! 와싱턴야자수가 홍대에 있다니! 조화인줄 알았는데 진짜네! 또 한번 깜놀!! 삼다수로 에이드 만들어 주네요^^세번째 깜놀!!!메뉴 네이밍도 사랑스럽고^^Flex한 이 기분 뭐지^^!포토 스팟도 많고 사진도 예쁘게 잘 나옵니다. 길을 걷다가 이상형을 봤을때의 설레임이 느껴지는 곳! 메뉴 하나하나에 정성들인 티가 너무 나네요. 이래도 되나 싶을 정도에요. 단연코 최근 가본 카페중 최고입니다! 좀 있으면 웨이팅 너무 길것 같아 걱정이네요.서두르세요~~: 그래도 다시 오고 싶은 곳입니다.정말 강추!', 98, 21, 'GOOD', SYSTIMESTAMP);
