INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '너무 예쁜 공간에 음료, 디저트들도 너무 맛있었습니다 ! 하나하나 설명들이 제주도에서 만든 건강한 재료들로 신경써서 만들었음이 느껴졌어요 층마다 개별 인테리어들도 감각적이었고, 알고보니 삼다수에서 진행하는 까페여서 더욱 신기했습니다 ㅎㅎ', 99, 20, 'GOOD', SYSTIMESTAMP);
