INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '일단 들어가면서 부터 인테리어가 너무 멋져서 감탄했어요!!!!! 분위기도너무좋고 정말 제주도 온것같은느낌이였어요!! ㅎㅎ 사람이많아서 메뉴나오는데는 시간이좀걸렸지만 메뉴 다성공했네요!! 특히 레몬케이크 비주얼도 귀엽고 맛있었어요.. 우도땅콩아이스크림도 추천!!!!!', 4, 6, 'GOOD', SYSTIMESTAMP);
