INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '너무 분위기 좋은 카페를 만났습니다! 저녁시간이라 디저트와 제주 티를 시켰는데, 티백 손잡이가 나뭇잎으로 되어 있는 디테일까지!! 디저트도 너무 앙증맞고 맛있었습니다 ㅜㅜ!! 다음엔 낮에 방문해서 핸드드립 커피를 꼭 마셔보려구요 :)', 113, 26, 'GOOD', SYSTIMESTAMP);
