INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '디저트 가격은 좀 있지만 너무 예쁘고 맛있어요 !! 인테리어 디자인도 사진찍기 좋은데 몇몇 자리는 좀 불편한 거 같아 오래 앉아 있기는 애매한 거 같아요 글구 낮에 가는 게 더 예쁠 거 같은 장소에요 :)', 5, 4, 'GOOD', SYSTIMESTAMP);
