INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '이런 제주도 컨셉의 카페가 요즘 많아서 인테리어가 예쁘긴 하지만 이젠 그렇게 끌리진 않아요. 맛도 그저 그랬어요. 귤이랑 삼다수 물 제공은 좀 특이했어요.', 73, 17, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '제주도 여행온 느낌이에요 카페인데 미술관 같은 느낌..! 크림라떼는 감귤청(?) 이 들어가서 새콤 달달해요 새로운 맛이었는데 맛있네요 !', 73, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '디저트 너무 맛있어요!! 제주에 온느낌 팡팡납니다. 차도 삼다수라 그런지 물맛이 더 보들보들하고 맛있었습니다👍 특히 카페 인테리어가 제주 컨셉으로 예쁘게 잘되어있어서 다음에 또 친구랑 오려구요ㅎㅎ', 4, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '제주보리와플! 넘 촉촉하고 쫀득하니 또먹고싶은 맛이에요!! 삼다크림라때는 아래 과일청이 애매하게 작은 조각으로 되어있어서 맛이 너무 진해서 좀 별로였어요. 이건 제 친구가 시켰는데 한 입먹고 남기더라구요;; 코지 밀크티도 가격에 바해 양이 터없이 작은데, 밀크티 일반 로열밀크티(ex.스타벅스)보다 스킨 향과 맛이 더 나는 맛이에요.  음료나 디저트 전반적으로 인테리어 값이라 너무 비싸요! 좌석도 불편한 곳이 많고, 동굴같이 생긴 반지하 공간은 너무 어둡고 음악 소리가 커서.. 이여기를 하기에는 적합하진 않고 그냥 사진찍으러가는 곳을 찾으신다면 나쁘지 않습니다~', 24, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '음악, 음료, 디저트, 분위기 모두 완벽 🪨🍊🌴🌿⛰️ 제주도에 있는것 같아 친구들과 좋은시간 보냈어요 제주 삼다수로 제조된 음료도 신기했고 둘러볼것들이 많아 눈도 즐거웠답니다 :)', 43, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '친구가 신상카페라고 가자해서 왔는데 제주도 느낌 디저트에 인테리어에 깔쌈하고 좋았어요! 다만 의자가 넘넘 불편했어요 돌하르방 양갱은 너무 달았고 옆에 말차 푸딩 같은 건 말차맛 찐하고 맛있었어요 아메리카노는 산미 적당히 있는편이었어요', 13, 2, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '음료 디저트, 매장 인테리어 너무 예쁨 접근성도 좋음 하지만 음료나 디저트 모두 취향은 아니었음 다 남김 귤을 무료로 제공하는데 귤맛은 좋았음', 23, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '너무 멋진 곳입니다! 각층마다 포토존이 있어서 사진찍기 좋구요 디저트도 맛있는데 거기에다 이뻐서 너무 좋았습니다! 간만에 멋진 카페 발견해서 좋았습니다 꼭 한번 가보세요^^', 41, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '추운날 저녁 힘들게 찾아간곳,  예상보다 매장이 작았어요~   앉을 자리ㄱㅏ 없어서 걍 나올뻔~  다행히 자리났지만 겨울점퍼 놔둘곳 없고 쇼핑한거, 가방 다 끌어안고 있어야해서 넘 불편했어요. 로맨틱제주   귤귤귤 맛있었어요.', 16, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '광동제약에서 아마 홍보하려고 만든 곳 같아요! 도심속의 제주를 느낄 수 있는곳 같아요 ㅎㅎ 커피도 맛있고 특색있는 디저트와 음료가 한가득 입니다 !!', 16, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '인테리어가 너무 예쁘고 메뉴도 다 맛있어서 좋았어요! 층별로 분위기가 다 달라서 취향에 따라 앉으시면 될 것 같아요~ 직원분들도 친절하시고 맛있는 커피 마시면서 좋은 시간 보냈습니다!!', 19, 6, 'GOOD', SYSTIMESTAMP);
