INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '도심속에서 만난 제주♡ 뭔가 힐링하는 기분이었어요~ 특히, 우도땅콩아포가토 JMT구요 크림라떼가 품절이래서 곶자왈라떼 주문했는데 와 이것도 타카페에서는 없는 새로운 맛이예요~! 제주레몬도 품절이었어서 너무 아쉽지만 담에 다시 방문해서 맛볼게요:)', 35, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '인테리어가 생각보다 너무 좋았습니다. 각 메뉴마다 설명도 제주도 모티브로 설명되어있어서 좋았어요. 녹담만설에 드립커피 추천합니다. 바리스타 분 정말 친절하셨습니다.', 34, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '인테리어는 너무 감각적이고 제주생각나게 합니다. 다만 좌석이 너무 혼란스러워서 손님들이 왔다갔다 하느라 분위기가 어수선한 곳입니다. 개선이 되지 않는다면 1회성으로 그칠만 한 곳.', 30, 6, 'BAD', SYSTIMESTAMP);
