INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '독특한 인테리어가 정말 신선했고 커피&디저트가 정말 맛있었습니다! 특히 땅콩 들어간 아이스크림이 최고에욥!! 삼다수로 내려주는 드립 커피도 최고입니다^^ 또 방문하겠습니다!!', 12, 1, 'GOOD', SYSTIMESTAMP);
