INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '독특한 메뉴들 가득✨ 디저트는 다른데서 못먹어보겠다 싶을정도로 특이해욤 인테리어도 예쁜데 오래 앉아있기엔 좌석이 조금 불편합니당 옹동이 아파요🥲🥲', 16, 4, 'GOOD', SYSTIMESTAMP);
