INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '리뷰 보고 기대했는데 기대치가 높았던건지 넘 평범했어요 푸딩은 푸딩맛... 에이드는 에이드맛 딱 그정도ㅜㅜ 비주얼 예쁘고 사진 찍기는 좋아요 맛은 기대안하시는게ㅎㅎ', 40, 2, NULL, SYSTIMESTAMP);
