INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '예쁘고 친절하시고 다 좋은데 저녁에 가서 그런지 지하1층 문쪽에서 흡연하는 사람들이 있어서 담배냄새가 들어왔습니다ㅠㅠ 이부분 개선되면 더 좋을 것 같습니다!', 57, 12, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '삼다코지'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '딱 제주도를 그대로 옮겨 놓은 것 같아요! 인테리어 하나하나 신경을 많이 쓴 것 같더라구요ㅎㅎ 귤빛찬란이 요거트와 아이스크림, 말린 귤이 어우러져서 정말 맛있어요 요거 먹으러 또 갈 듯!! 완전 강추입니당♡', 38, 3, 'GOOD', SYSTIMESTAMP);
