INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '합정역 근처에 있는 대형베이커리카페 매장앞 3대정도 주차공간있고 지하주차도 가능해여 야외테라스가 있어서 바람솔솔 부는날 커피마시지 좋고 내부공간도 넓고 블랙무드 분위기에 사진 남기기도 좋네여 시그니처 스콘메뉴와 커피도 맛있어서 데이트코스로 혼커장소로도 굿입니다', 126, 26, 'GOOD', SYSTIMESTAMP);
