INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '와 스콘의 풍미와 커피가 맛있었고 느낌있는 음악과도 어우러져서 대화든 작업이든 멍이든 다 좋은 것 같아요 매장도 넓고 쾌적해서 너무 좋았습니다. 아침일찍 1등으로 왔더니 손님이 없길래 맘편히 찍어볼 수 있었네요😁', 39, 8, 'GOOD', SYSTIMESTAMP);
