INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '버터베리, 더티초코, 플레인버터, 콘치즈, 블루베리치즈 스콘과 밀크티, 카페라떼를 주문해서 맛있게 잘먹었어요😊 스콘맛집이네요🤩', 56, 12, 'GOOD', SYSTIMESTAMP);
