INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '커피 맛집인제 스코도 정말 맛있습니다. 저는 오랜만에 말차 라떼 마셨습니다. 겨울에 밀크티! 여름에는 더 밀크티! 밀크티도 정말 맛있습니다. 음료는 커피! 커피는 꼭 뜨겁게 드셔보세고! 커피 안 드시는 분들은 밀크티 강력 추천합니다. 스콘 1개는 필수고 주말 오후에는 일찍 솔드아웃 되니 참고하세요!', 62, 11, 'GOOD', SYSTIMESTAMP);
