INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '우연히 처음 모임하러 왔다가 인테리어와 분위기에 두번오고 커피 맛이 자꾸 생각나서 네번째 옵니다! 커피 너무 맛있어서 베이커리와 함께 먹으면 양이 아쉬울 정도에요~ 꼭 와서 먹고 싶어서 테이크아웃은 안해봤는데 실내가 클래식하면서 절제된 분위기라 뭔가 아늑하고 쾌적함을 줘요~~ 오늘 싱글오리진 도전해봤는데 여기는 이것도 잘하네요!! 오늘은 맘 먹고 영수증리뷰!', 2, 7, 'GOOD', SYSTIMESTAMP);
