INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '❇︎ 라즈베리 로프 케이크 9,800원 ❇︎ 아메리카노 디카페인 5,000원 ❇︎ 카페라떼 5,000원 외국감성나는 카페입니다. 야외테라스가 멋져요. 요즘같은 날씨에 굿굿! 라떼가 맛있어요. 고급진 케이크가 커피랑 잘 어울려요. 창가테이블에서 카공하기 좋아요. 화장실 깨끗해서 너무 좋음! 이솝 핸드워시 스크럽제 진짜 좋음 손만 씻고와도 본전 뽑는 기분(?) 직원분 완전 친절하심ㅋ', 30, 5, 'GOOD', SYSTIMESTAMP);
