INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '합정 빈둥거리며 편히 쉬기 좋은 유럽감성 카페🏠 한 덩어리의 빵과 빈둥거린다라는 뜻을 가진 loaf. 방문한 손님들이 빈둥거리며 편안히 머물 수 있게 노력하는 로아프하우스는 리밀앤밀리의 두 번 째 지점이기도 해요😀 단체인원을 수용할 수 있는 널찍한 공간, 부대끼지 않고 여유롭게 머물 수 있으며 콘센트 자리도 많아서 작업하기에도 정말 좋던 곳💻 창가 너머엔 목련 뷰라 밖을 바라보며 멍때리기에도 괜찮았어요 테라스는 가오픈 기간이 끝나면 오픈할 예정이라고 하니 정식오픈 후 테라스에 앉아 봄날씨를 만끽해도 좋을 듯 합니다', 38, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'TERRACE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PLUG');
