INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '아메리카노는 깔끔하고 고소합니다 끝에 달고나 맛이 살짝 올라오눈데 그게 아주 귣입니당 슈페너도 곡물맛 미숫가루 맛이 납니당 제 취향에는 좋았슺니당 맛있어서 츄천!! 양이 아쉽긴한데 그래도 인테리어도 깔끔해서 좋아요', 118, 24, 'GOOD', SYSTIMESTAMP);
