INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '아는 동생이 추천해서  가봤는데 찾기도 쉽고~ 아빠가 커피 고르기 쉽지않아 어려워 하는데 남자 직원분이 추천을 잘해줘서 아빠가 좋아하셨어요^^ 아인슈페너를 좋아해서 로아프 슈페너 마셔봤는데 고소하고 크림이 맛없으면 느끼한데 깔끔하게 잘 마셨어요~ 근처 오게되면 자주 올듯해요~~', 26, 1, 'GOOD', SYSTIMESTAMP);
