INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '합정역 주변 주차가 가능한 카페 찾다고 왔는데 사람 엄청 많네요! 자리 없어서 주변 다른 카페 돌다가 다시 왔어요ㅠ ㅋㅋㅋ 음료 전반적으로 다 맛있어요 ~ 슈페너도 맛있고 에이드, 유자민트티도 굿굿!! 시원하고 분위기도 좋은데 소리가 많이 울려서 조용한 카페를 찾으신다면 여기는 아닌걸로 ㅎㅎ', 15, 9, NULL, SYSTIMESTAMP);
