INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '인테리어 멋져소 면접보러 왔다가 들어왔는데, 음음 분위기 굳굳입니다 맛도 굳. 스타일리쉬- ;-) 근데 공간 통이라 좀 울려요. 요샌 어디니 그렇지만- 나이드신 분들은 ㅋㅋ 참고!', 18, 7, 'GOOD', SYSTIMESTAMP);
