INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '커피가 너무너무 맛있고, 매장 내외부 인테리어가 너무 제 취향이라 자주 올 것 같아요 ⑉♥ 그리고 직원분이 정말 친절하셔서 기분 좋게 시간 보내다가 갑니다! 합정 오시면 로아프하우스 꼭 들러보세용', 36, 3, 'GOOD', SYSTIMESTAMP);
