INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '새로 생겼는데 괜찮다는 친구 이야기 듣고 방문했어요~ 라떼랑 올리브 살레라는 디저트 주문했고 라떼가 정말 맛있었습니당 재방문 해야겠어요 :)', 104, 25, 'GOOD', SYSTIMESTAMP);
