INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '주변에 산책하다가 가오픈 포스터보고 방문했어요! 매장이 넓고 인테리어가 깔끔해서 좋았어요! 진동벨이 아니라 번호적힌 표지판?을 테이블위에 올려놓으면 가져다주시는데 여기 분위기랑 너무 잘어울려요! 저는 로아프슈페너를 마셨는데 견과류?맛이나요 달달하고 고소해서 좋았습니다 케이크도 맛있어보였는데ㅠㅠ 점심 먹고와서 못먹었어요.. 다음에는 케이크도 먹어보고싶네요', 37, 8, 'GOOD', SYSTIMESTAMP);
