INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '합정에 예쁜 카페가 생겼대서 와봤어요! 원두 세가지 중에 고를 수 있어 좋고, 로아프슈페너는 땅콩버터 맛이 나는 달달한 라떼네요! 널찍하고 탁 트인 느낌의 내부,따뜻한 날엔 테라스에서 커피 마셔도 좋을 것 같아요💗평일 오후에 계셨던 남자직원분도 친절하셔요 :)', 88, 15, 'GOOD', SYSTIMESTAMP);
