INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '새로생긴 카페라서 와봤어요! ㅎㅎ 빵도 너무 맛있을거 같고 커피도 너무 맛있네요 ㅎㅎ 무엇보다 공간이 넓어서 앉을 곳이 많아요 ㅎㅎ 와이파이도 있습니다 ㅎㅎ 콘센트는 많진 않아요! ㅎㅎ 이야기하고 맛난 빵 먹기 더 좋은 커피 맛난 카페! 그리고 인테리어가 너무 예쁘네요 ㅎㅎ 야외테라스도 테이블 넓고 의자도 넓어서 지금 목련이 펴서 밖에서 먹기도 좋을거 같아요 ㅎㅎ', 39, 10, 'GOOD', SYSTIMESTAMP);
