INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '카페 분위기가 엄청 좋아요 모던하고 밖에 보이는 초록잎들이 카페 분위기를 더 살리는 느낌? 커피는 엄청 고소했고 말차라떼도 부드러웠어요 디저트도 죤맛! 여기 가까우면 자주 갈 것 같아요💖', 10, 6, 'GOOD', SYSTIMESTAMP);
