INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '시그니처라고 하셔서 슈페너 먹었는데 맛있습니다. 일찍 오픈하고 좌석 넉넉하고 콘센트도 있고 창도 큼직큼직해서 혼자 책 읽기 좋아요. 커피를 자리로 서브해주십니다.', 89, 16, 'GOOD', SYSTIMESTAMP);
