INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '회사 앞에 새로 생겨서 와봤어요!! 직원분들 너무 친절하고 커피도 너무 맛있어요 합정에서 이정도 가격에 이정도 맛이면 너무너무 훌륭한 것 같아요☺️ 매장도 엄청 넓고 쾌적해서 너무너무 좋아용', 8, 8, 'GOOD', SYSTIMESTAMP);
