INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '로아프 미감 미쳤....😳🤎 간만에 합정역에 제대로 된 카페 등쟝!!!! 이제 퇴근하고 상수나 홍대연남 쪽으로 넘어가지 않아도 되겠어요', 34, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '커피도 맛있고 공간도 좋습니다~ 남사장님? 직원분? 젊은분인데 정말 친절하고 목소리도 좋네요 직접 가져다주셔서 좋은데 쟁반채로 두고 가셔도 좋을 거 같아요 컵에서 물도 많이 떨어지고 코스터도 없는게 조금 아쉽습니다. 디저트는 가격에 비해 좀 아쉽습니다.', 5, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '새롭게 오픈하여 들렸습니다. 점심시간에는 테이트아웃 할인도 해주시거 커피도 고소한맛 산미도 모두 쓰지않고 맛있습니다. 디톡스차도 맛있습니다. 사장님도 친절하십니다. 감사합니다!', 92, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '공간이 넓고 깨끗하고 사진도 넘 잘 나와서 좋았습니다🩷  그리구 창문들이 다 넓고 탁 틔어있어서 바람이 솔솔 불어오는게 아주 행복했습니다 🙊', 12, 8, 'GOOD', SYSTIMESTAMP);
