INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '로아프하우스 커피가 맛있어요. 카페모카랑 아이스 아메 적당한 산미로 맛있었어요. 호두스콘도 고소하고 아메랑 잘 어울리네요. 주차도 편해서 다음에 또 올거에요.', 32, 8, 'GOOD', SYSTIMESTAMP);
