INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '새로생긴 곳이라고 해서 왔는데 테이블 간격도 넓고  층고가 높은게 탁 트여서 좋아요! 라떼는 꼬수운 편이구요..! 배불러서 디저트는 못먹었지만 냄새가 너무 좋습니더ㅠㅠㅠㅠ 담에 꼭 먹으러 올것,,✨✨', 27, 1, 'GOOD', SYSTIMESTAMP);
