INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '우연히 들른 로아프 카페! 외관부터 깔끔하고 세련됐는데 내부 인테리어도 예뻐서 또 오고싶어요~ 자리도 편하고 개인 작업하기도 적합합니다!!', 75, 13, 'GOOD', SYSTIMESTAMP);
