INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로아프하우스'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '오늘 비오는 날 커피를 먹고 싶어서 검색하다가 찾은 카페입니다. 안에 들어와보니 분위기 있는 음악과 깔끔한 인테리어가 어우러져서 작업하기도 좋고 지인들과 함께 커피를 마시기에도 좋은 장소인 것 같습니다. 커피에 대한 질문에도 사장님이 친절하게 답해주시고 커피도 빨리 나왔습니다! 고소한 맛으로 시켰는데 향도 좋고 너무 맛있게 먹었습니다! 만족합니다:)', 20, 7, 'GOOD', SYSTIMESTAMP);
