INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '한국에서 맛보는 싱가폴의 맛… 지금까지 먹은 카야토스트는 전부 가짜라는 걸 꺠닫게 해주는 공간이었습니다. 마냥 달기보단 씹히는 코코넛이 특이하고 잘 어울리네요. 밀크티와 홍차도 달달한 편이라, 달지 않은 걸 원하시면 주문할 때 먼저 말씀드려야 할 거 같아요.', 124, 23, NULL, SYSTIMESTAMP);
