INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '싱가포르 현지를 직접 가본 적은 없지만 이곳에만 와도 현지의 느낌을 물씬 느껴볼 수 있네요. 주말에 방문하는 사람들이 꽤 있어요. 소비쿠폰으로 결제가 됩니다..!', 88, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '싱가폴 디저트들을 맘껏 즐길 수 있어요🤍 개취로 카야번 보단 무조건 토스트!! 카야쨈 좋아하시면 호불호가 나뉠 수 없죠! 여긴 음료가 정말 다양하고 특색있는데 음료들이 다 좋게 말하면 찐한거고 나쁘게 말하면 너무 달거나 짜요(?) 히비스커스가 짠건 또 처음 ㅋㅋㅋ 하지만 너무 맛있게 잘 먹었습니당', 3, 1, 'GOOD', SYSTIMESTAMP);
