INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '싱가폴 카페 디저트 머라이언🇸🇬 카야토스트에 수란을 찍어먹는건 처음이라 진짜 궁금했는데 비리지 않고 짭짤고소달달 존맛탱!!!!! 판단케이크는 코코넛맛 쉬폰케이크 같아서 맛있었어요 카야토스트가 너무 맛있어서 또 시켰다는건 안비밀🤫', 57, 17, 'GOOD', SYSTIMESTAMP);
