INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '홍대에서 느끼는 싱가포르 분위기가 궁금해서 방문했는데 싱가포르 관광객은 없다. 시그니쳐 메뉴인 카야토스트와 반숙계란, 코코넛 판단플레인 케익, 망고실크푸딩 그리고 블랙코피 주문. 일단 커피가 진해서 좋다. 디저트도 하나 같이 맛있는게 싱가포르 수상 부부와 대사의 방문이 납득 된다. 색다른 카페를 찾는다면 추천~', 87, 13, 'GOOD', SYSTIMESTAMP);
