INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '싱가폴 카페를 그대로 옮겨놓은 것 같다. 코코넛커피 추천~ 특색있고 코코넛 액상 대충 넣은게 아니라 찐으로 만든듯! 😍 카야토스트도 일반카페에서 흉내만 낸것과 다르다. 싱가포르도 다녀온사람은 느끼겠지만 진짜 똑같다. 이집은 찐이다.. 👍🏻', 11, 0, 'GOOD', SYSTIMESTAMP);
