INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '싱가포르식 디저트를 취급하는 카페라는 간판만 봐도 지나칠 수 없었다. 드문 컨셉트처럼 제공하는 메뉴도 쉽게 접하지 못하는 것이 많다. 특이한 색을 띈 코코넛크림을 곁들인 판단잎케이크는 촉촉한 질감과 은은하게 올라오는 이국적인 단맛이 기분을 좋게한다. 그리고 마일로 다이노소어. 코코아 같지만 텁텁하지 않은 질감과 적절한 단맛이 좋다. 어린 시절 롯데리아에서 어린이세트와 먹던 그 마일로의 맛을 다시 찾은 것 같다.', 11, 0, 'GOOD', SYSTIMESTAMP);
