INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '오랜만에 왔는데 디저트가 여전히 맛있습니다. 싱가포르 디저트를 다양하게 먹을 수 있는 곳이 정말 없어서 홍대에 온다면 추천하는 카페!', 88, 17, 'GOOD', SYSTIMESTAMP);
