INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '카야토스트 덕후로서 방문함 그..수란이 보시다시피 거의 익었음..여기서 끝남 하..카야토스트 차갑지만 먹을만하고요 밀크티에 코코넛 맛있어요 판단케이크 ☆로. 수란 메뉴는 안 하시는게..', 45, 7, NULL, SYSTIMESTAMP);
