INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '커피도 맛있고 특이한 디저트들 많은데 디저트류 다 맛잇어요 올때마다 새로운거 도장깨기중인데 코코넛트라이플 판단케이크 포멜로빙수 맛잇어요 커피는 콜드브루 따뜻한 버전같아요 향긋함. 다음엔 제일 무난해서 주문 미루고 안먹어왓던 밀크티랑 카야토스트 먹어보게요 다른사람들은 밀크티랑 카야토스트 많이 시켜먹네요', 41, 9, 'GOOD', SYSTIMESTAMP);
