INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), 'TV에서 싱가포르 음료와 음식이 소개되면 늘 이 곳에 방문한다. 방문할 때마다 다양한 메뉴에 도전하는데 재료가 신선하고 싱가포르만의 독특한 개성이 있어 항상 만족한다! 이날은 창밖 뷰를 바라보며 커피를 마실 수 있어 특히 좋았다 :)', 9, 9, 'GOOD', SYSTIMESTAMP);
