INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '✨싱가폴수상방문✨ 강추받은 싱가폴 디저트메뉴 모음집🐻 📍 :   #디저트머라이언 서울 마포구 와우산로27길 75 오복빌딩 #코피-c 싱가폴 코피 중에서도 우유와 함께 엄청 압축된 깊은맛이 느껴지는 코피였습니다! 메인 메뉴인 판단케이크에 맞춰 깊은맛 음료를 선택했습니다☕ #판단케이크 우리나라에서는 정말 생소한 이름인데 엄청 유명한 케이크라고😮 동남아시아에서 나는 판단이라는 식물을 갈아서 만든 케이크입니다! 밀가루 사용이 정말 적은 싱가포르에서 온 케이크입니다🫶🏻', 82, 14, 'GOOD', SYSTIMESTAMP);
