INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '진짜 다 맛있었어요..포멜로빙수에있는 포멜로랑 망고도 신선하고 위에 아이스크림도 진하고 맛있어요 몰튼라바 초코케이크는 달지않고 깊고 진하고 풍부한 케이크맛이에요 꼭! 드셔보세요', 43, 1, 'GOOD', SYSTIMESTAMP);
