INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '싱가포르 현지 디저트라고 해서 어떤 맛일까 했는데 판단케이크 진짜 너무 부드럽고 맛있어요✨ 카야토스트도 잼도 직접 만드신다고했는데 바삭바삭하니 아주 맛도리입니당!! 그리고 망고주스 완전 합격✨', 48, 7, 'GOOD', SYSTIMESTAMP);
