INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '로컬에 온듯한 맛과 융숭한 대접 ㅎㅎ 간장 조절에 유의하세요~ 다시 또 방문하고 싶습니다 카야토스트 외에도 판단케익도 강추합니다 밀가루가 들어가있지 않아 속이 안아파요!', 12, 10, 'GOOD', SYSTIMESTAMP);
