INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '지나가면서 보다 궁금해만 하다가 가봤습니다 코코넛커피랑 판단 케익 먹었는데 짐작한 것보다 더 맛있었어요 분위기는 조용할 줄 알았는데 의외로 시끌벅적했어요', 60, 11, 'GOOD', SYSTIMESTAMP);
