INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '싱가폴 갔을때 먹던 게 생각나서 진짜 찐 싱가폴 분이 하는 곳이라 맛도 굿굿 라디오도 싱가폴 래디오~~라서 진짜 싱가폴온거같아', 21, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '핫을 시켜 따뜻하고 달달한 커피였는데 제입맛엔 적당히 달아서 좋았고 코코넛커피는 이색적이라 좋았습니다:) 겨울에 커피 한잔 하고 나오기 좋은 곳!', 11, 7, 'GOOD', SYSTIMESTAMP);
