INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '친구들이 빙수가 맛있었다며 데려왔어요. 쌀알 같은 자몽맛 젤리와 아이스크림, 망고가 잘 어우러져 맛났어요! 아이스 아메리카노도 시켰는데, 진하고 향이 약간 평소에 먹는 아메리카노랑 달랐어요. 친구들이랑 시간 보내기 좋은 곳이었어요!', 38, 4, 'GOOD', SYSTIMESTAMP);
