INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '판단쉬폰 좋아해서 사먹었어요. 생각보다 크기가 크고 쉬폰은 부드럽고 촉촉합니다 부들초크초크~~~싱가폴에서 먹었던 것보다 더 코코넛 향이 짙네요. 메뉴 이름이 판단코코넛쉬폰이던데, 그래서 그런가. 밀크티는 찐합니다. 한국에서 찾기 힘든 찐한 동아시아쪽 밀크티. !', 20, 10, 'GOOD', SYSTIMESTAMP);
