INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '여러명이 가서 각각 다른메뉴로 맛봤는데 음료는 역시 기본 밀크티가 제일 좋았어요. 디저트는 망고푸딩이 맛있었구요.  너무 달지않은데다 고소하고  부드럽고 입안에서 난리부르스! 푸딩 안좋아하는 제입맛에도 너무 맛있었습니다. 여러분, 이집은 망고푸딩이 최곱니다.', 23, 7, 'GOOD', SYSTIMESTAMP);
