INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '날이 더워져서 자몽쥬스를 시켰는데 독특해요! 분위기도 이색적이고 외국인이 많아서 신기했어요. 창문을 열어서 바람도 불고 좋았어요!', 23, 6, 'GOOD', SYSTIMESTAMP);
