INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '싱가포르의 맛. 진짜 찐 카야토스트는 빵이 얇고 빠싹한게 포인트 그걸 먹으려면 여길 가야 함. 싱가포르서 지내던 추억 몽글몽글. 테타릭도 현지 맛. 오랜만에 생각날때 가기 좋고, 특별한 메뉴를 찾고있다면 추천. 다이노소어 마일로, 코코넛커피, 연두색 빵~판단케이크도 강추츄!', 19, 0, 'GOOD', SYSTIMESTAMP);
