INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '앞으로 홍대에서 디저트를 먹으러 카페를 가야할 일이 있다면 이곳에만 오겠다. 모든 메뉴가 홈메이드라는 사실은 이 작은 싱가포르 디저트 카페의 아주 사소한 장점 중 하나일 뿐이다. 이 곳의 메뉴들은 주문을 마치고도 자리에 가져와 계속 볼 만들 만큼 이색적이다. 맛 또한 훌륭해서 푸딩을 한 입 떠먹고 곧 바로 다른 메뉴를 시켜 먹어야겠다는 생각이 들었다. 주문과 동시에 만들어지는 카야 토스트는 따뜻하고 망고는 신선하고 푸딩은 부드럽고 밀크티는 진했다. 재방문 의사 만프로.', 55, 16, 'GOOD', SYSTIMESTAMP);
