INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '지나갈 때마다 보기만 하고 첫 방문인데 계란+카야토스트에 코코넛커피, 망고 푸딩 들어간 밀크티 먹었는데 디저트도 음료도 너무너무 맛있어요!!! 뭔가 맛에 정성이 느껴져요!!! 다른 메뉴도 궁금해서 조만간 또 방문할 것 같아요!!', 21, 4, 'GOOD', SYSTIMESTAMP);
