INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '특별한 디저트 원하시는 분들께 강추합니다! 땅콩맛은 없어서 흑임자로 먹었는데 겨울철에 먹기 좋은 생강차입니다! 샌드위치도 부드럽고 맛있어요👍 히비스커스는 단맛이 없어서 단거 싫어하시는 분들께 추천합니다👍', 35, 10, 'GOOD', SYSTIMESTAMP);
