INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '카야토스트는 블랙빈소스 넣은 반숙계란에 찍먹하니 진짜 맛있어요. 코코넛커피는 아이스로 먹었는데, 코코넛 밀크의 단 맛이 부드럽고 신선했어요. 단짠의 신세계를 경험했네요.', 9, 4, 'GOOD', SYSTIMESTAMP);
