INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '처음에 싱가폴 친구들이 소개해 줘서 갔었어요. 따뜻한 분위기에서 싱가폴 디저트와 음료를 먹을 수 있는 곳 :) 종종 생각날 거 같아요.', 2, 0, 'GOOD', SYSTIMESTAMP);
