INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '2층에 특색있는 카페라서 들어가기 겁났는데, 막상 들어가니 너무 좋았어요! 밀크티와 디저트류가 정말 맛있어요. 블랙커피도 마셨는데 다음에는 밀크티 마실 것 같아요!', 11, 10, 'GOOD', SYSTIMESTAMP);
