INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '매장이 쾌적하고 좋아요! 카야... 처음 먹어봤는데 맛있더라구요...! 토스트도 맛있었고 티랑 커피 섞인 원앙?도 맛있게 먹었습니다ㅎㅎ', 72, 16, 'GOOD', SYSTIMESTAMP);
