INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '늦게 마감하는 카페 찾다가 길 가다가 그냥 들어갔는데 숨겨진 맛집 이었어요!!! 가격이 좀 비싼것같긴한데 맛있었어요!! 커피 자몽 말차 셋다 맛있었어요 !! 그리고 싱가포르 음식이었나 아마 토스트가 진짜 맛있어요 여기 오신분들 토스트 꼭꼭 드세요 ~!!!!!!', 44, 10, 'GOOD', SYSTIMESTAMP);
