INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '사장님 너무너무 친절하시고 분위기 편해요!! 카야토스트가 진짜 대박이었는데 싱가포르 사장님이 직접 만든 카야로 만드신답니다!! 찐 맛집 떼따레도 완전 제 스타일이었습니다^_^ 단골 예약 확정', 84, 15, 'GOOD', SYSTIMESTAMP);
