INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '항상 갈때마다 너무 친절하세요ㅜ 특히 카야토스트는 여행다니면서 먹었던것보다도 여기가 제일 맛있어요 너무 바삭하고 촉촉해요.. 밀크티도 홍대에서 1등인것같아요>_<', 7, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '싱가폴 여행가서 카야토스트를 너무 맛있게 먹었어서 길 다니다가 카야토스트 파는데 보면 들어가서 하나씩은 사먹어봤어요 한국에 들어 온 야쿤토스트는 현지 맛이 안 나서 아쉬웠는데 여기는 사장님이 싱가폴 분이셔서 그런지 정말 맛있었어요! 잼도 직접 만드셔서 달달하구요! 근데 빵이 좀 늦게 나왔어요... 진동벨이 있으면 어떨까 하는 개인적인 느낌...', 3, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '시간이 걸리는 케이크류라 카페에서 쉽게 접하기 힘든데 제대로 만든 진한 퍼지 케이크예요👍 너무 맛있게 잘 먹었어요~ 코코넛 커피도 너무 맛있었어요! 홍대에 매일같이 오는데도 왜 이제서야 알았는지ㅠㅠ 친구들이랑 자주 올 것 같아요~', 5, 5, 'GOOD', SYSTIMESTAMP);
