INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '연유 밀크코피 5,000원. 오리지날 토스트 3,800원. 식빵 하나를 얇게 잘라 두겹으로 만들고 그 속에 카야 잼이 발라져 잇고 버터 조각이 두어개 들어 잇어요. 빵이 얇아서 바삭바삭 하면서도 밀가루보다는 잼 맛을 더 진하게 느낄수 잇어 아이디어가 좋네요. 버터가 이따금 씹히는 것도 재밋고요. 커피도 맛잇어요.', 71, 17, 'GOOD', SYSTIMESTAMP);
