INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '카야토스트 이렇게 맛있는 집 처음입니다 ㅠㅠ 동남아에서 먹던 카야토스트, 커피, 밀크티의 맛 ...... 홍대 단골 예약이요 !!!!!', 4, 6, 'GOOD', SYSTIMESTAMP);
