INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '싱가포르 사람이 직접 운영하는 디저트 카페. 간단한 차찬텡 급의 다양한 메뉴가 있고, 무엇을 주문하든 중간 이상의 맛을 낸다. 원앙차와 직접 만든다는 카야잼 바른 카야토스트가 최애 메뉴.', 49, 10, 'GOOD', SYSTIMESTAMP);
