INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디저트 머라이언'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '싱가폴카페가 흔한 카페는 아니지만 가끔 커피맛이 생각나는곳입니다. 디저트와커피음료 모두 좋습니다. 친절하고 정성이 느껴지는 맛입니다.', 24, 4, 'GOOD', SYSTIMESTAMP);
