INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '오후에 카페인을 잘 못마셔서 디카페인 라떼 마셨는데, 디카페인도 꼬소하고 맛있어서 좋았어요! 여기 크로와상 맛있었던거 기억하는데 우유크림 크로와상 궁금해서 시켜봤는데 넘 맛있어요. 우유크림이 느끼하지 않고 부드럽고 꽉 차 있어서 (예쁘게 먹진 못했지만) 진짜 맛있었어요🩵', 45, 5, 'GOOD', SYSTIMESTAMP);
