INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '빵이 맛있어서 재방문 했어요. 근처 아구찜 맵고 입맛 별로라 입가싱 하려고 왔는데 진짜 진짜 맛있네요. 여름이라 빙수파르페 개시한듯. 이것도 진짜 맛있어요!!', 26, 0, 'GOOD', SYSTIMESTAMP);
