INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '베이커리류가 다양하고 메뉴 라인업이 좋아요. 크로아상 샌드위치는 주문하면 바로 만들어 주셔서 바삭하고 신선해서 아주 맛있게 먹었습니다:) 매장 테이블 간격도 넓고 손을 씻을 수 있는 세면대가 한 쪽에 있어서 좋았습니다. 자주 올 것 같아요!!', 14, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '조용히 쉬기 좋은 카페를 찾다가 방문했어요 !커피가 정말 맛있어요—산미가 적당하고 풍미가 깊어서 한 모금 마시자마자 기분이 좋아졌어요ㅎㅎ 디저트로 주문한 티라미수는 부드럽고 진한 맛이 일품이었고 빵도 촉촉해서 만족스러웠어요! 직원분들도 정말 친절해요 주문할 때부터 응대가 따뜻해서 좋았습니다! 무엇보다 분위기가 좋아요—조용하고 아늑해서 혼자 책 읽기에도 딱이에요!', 37, 2, 'GOOD', SYSTIMESTAMP);
