INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '오늘 메뉴선택한 나자신 너무 칭찬합니다🫶🏼 플랫화이트 너무 맛있게 먹었는데요 거품이 딱 적당하고 부드러운 것이 숙련된 바리스타의 손맛(?)이었습니다ㅎㅎ 아메리카노는 산미있는 원두로 먹었는데 라이트해서 여름에 딱이었어요 디저트는 두번째 사진에 있는거 세 개다 먹었눈데, 천천히 먹으려다가 너무 맛있어서 정신을 차려보니 없었구요..루꼴라 많이 들어간게 좋아서 잠봉샌드위치로 골랐는데, 빵안에 발려진 홀그레인 머스타드가 들어간 소스가 약간 킥인것 같아요. 과하지 않는데 부드럽게 맛을 감싸주는것이 저한테는 존재감이 확실했어요 다 맛있어서 맛표현이 술술 되는것 같네요 ㅋㅋ 무튼 잘먹었습니다!! 저희집에선 멀어서 아쉽지만 근처갈때마다 갈 것 같아요😚👍🏻👍🏼👍🏽ㅓ', 50, 0, 'GOOD', SYSTIMESTAMP);
