INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '카페에 들어오자마자 기분좋은 빵냄새가 코속으로 훅 ㅎㅎ  들어가자마자 자리잡고 빵사러 갔는데 와.. ❤️다 맛있어 보이고 다 사 먹고 싶어보이는 비쥬얼 ㅠㅠ 크로와상🥐샌드위치에 라뗴☕️ 시켜서 한끼식사 완료!! 분위기가 너무 편안해서 힐링 된 하루 😄', 31, 9, 'GOOD', SYSTIMESTAMP);
