INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '따뜻한 분위기르 카페 >< 엄청 넓진 않지만 와서 이야기 나누기 좋았음!! 빵이 진짜 다양했고, 다 맛있어 보여서 고르기 너무 힘들었음..크로와상인가 골라무금!! 디저트 맛집이라더니 진짜 완전 맛집 인정임. 아메리카노에 맛난빵까지 행복했음^^', 45, 4, 'GOOD', SYSTIMESTAMP);
