INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '감성적인 디저트를 먹으러 찾은 아늑한 카페^^ 편안하게  머무르기 좋았어요.  마들렌은 겉은 살짝 바삭하고 속은 부드럽고 촉촉 그리고 레몬의 상큼함이 깔끔하게 마무리 되는 세련된 맛^^ 음료와 함께 잘 먹었어요.', 28, 3, 'GOOD', SYSTIMESTAMP);
