INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '진열대에서 베이커리 골라 접시에 담는 과정부터 기분이 좋아졌어요. 두툼하게 올라간 크럼블 덕분에 한입 먹을 때마다 바삭한 느낌이 살아 있었네요. 커피랑 같이 조용히 즐기니 여유롭게 쉬어갈 수 있었어요.', 38, 4, 'GOOD', SYSTIMESTAMP);
