INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '야외 테이블에 앉아서 여유롭게 시간을 보냈어요. 라떼 위에 아트가 정성스럽게 그려져 있어서 먼저 눈길이 갔고, 플레이팅이 깔끔한 베이커리랑 샌드위치를 함께 곁들이니 조화가 잘 느껴졌네요. 전체적으로 한 끼로 충분히 만족스러웠어요.', 28, 9, 'GOOD', SYSTIMESTAMP);
