INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '합정 나들이 겸 들렀는데 디저트 색감부터 분위기까지 마음에 들었어요 브런치는 구성도 정갈하고 깔끔하니 부담 없었고요 음료 향도 부드럽고 여운이 남더라고요 가볍게 힐링하고 싶은 날 생각날 것 같아요 :)', 34, 10, 'GOOD', SYSTIMESTAMP);
