INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '크로와상 한 입에 바삭-! 안에 든 꾸덕한 우유크림이 입안 가득 퍼지는 순간 행복이 뭔지 알게 됐어요 합정에서 이런 퀄리티의 베이커리 만나는 거 흔치 않죠 커피까지 진하고 고소하니 완벽 조합✨', 8, 0, 'GOOD', SYSTIMESTAMP);
