INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '크루아상 샌드위치가 푸짐하게 보여서 바로 손이 갔어요. 직접 잘라서 먹으니 바삭한 식감이 더 잘 느껴졌고, 널찍한 테이블 덕분에 여유롭게 즐길 수 있었네요. 담백하면서도 한 끼로 충분히 만족스러웠어요.', 7, 2, 'GOOD', SYSTIMESTAMP);
