INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '굿즈 코너에 에코백이랑 티셔츠가 가지런하게 걸려 있어서 먼저 눈길이 갔어요. 아기자기한 소품 덕분에 전체 분위기가 훨씬 따뜻하게 느껴졌네요. 잔잔한 공간에서 브런치랑 커피로 여유롭게 쉬다 가기 좋았어요.', 54, 12, 'GOOD', SYSTIMESTAMP);
