INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '겹겹이 살아 있는 빵 결을 먼저 느끼게 해줬어요. 크림이 꽉 차 있는 단면이 인상적이라 한참 들여다보게 됐네요. 바삭한 식감에 부드러운 크림이 잘 어울려서 테이블 위 분위기랑도 자연스럽게 어울렸어요. 천천히 즐기기 좋은 디저트였어요.', 80, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '트레이에 음식이 가지런히 담겨 있어서 첫인상부터 깔끔했어요. 크루아상 샌드위치 단면에 신선한 채소가 듬뿍 보여서 더 먹음직스럽게 느껴졌네요. 직접 칼로 썰어 먹는 과정도 소소하게 재미있었고, 한 끼로 충분히 든든했어요.', 18, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '야외 테이블이 깔끔하게 느껴져서 앉아 있으니 한결 여유로웠어요. 라떼 위에 그려진 아트가 정성스럽게 보여서 마시는 순간 기분이 달라지더라고요. 초콜릿과 토핑이 올라간 베이커리 조합이 독특해서 샌드위치랑 같이 새로운 조합을 제대로 즐길 수 있었어요. 디저트와 커피로 한 번에 만족할 수 있었던 시간이에요.', 14, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'TERRACE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '손글씨 쪽지들이 한눈에 들어와서 잠시 멈춰서 읽게 됐어요. 조그만 공간이 전시처럼 꾸며져 있어서 구경하는 재미가 있더라고요. 여유롭게 둘러보며 소품 감상도 하고, 디저트랑 같이 편안히 쉬다 올 수 있었네요.', 121, 22, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '작은 식물 소품들이 눈에 띄어서 공간이 훨씬 아늑하게 느껴졌어요. 여유로운 분위기 덕분에 오래 머물러도 부담 없었고, 자연스럽게 휴식할 수 있었네요. 전체적으로 편안한 느낌이 잘 살아 있었어요.', 16, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '입구 쪽에 굿즈 코너가 따로 마련돼 있어서 구경하는 재미가 있었어요. 머그컵이나 티셔츠 등 소품들이 감성적으로 진열되어 눈길이 가더라고요. 디저트나 커피와 잘 어울릴 것 같아 자연스럽게 매장 분위기에 빠져들게 됐네요. 잔잔한 공간 덕분에 여유롭게 즐기다 왔어요.', 30, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '테이블 간 간격이 넉넉해서 여유롭게 앉을 수 있었어요. 진열된 베이커리들이 골라보는 재미가 있어서 좋았고, 크루아상 샌드위치는 채소랑 햄이 넉넉하게 들어가서 든든하게 먹었네요. 아이스커피 마시면서 오랜만에 천천히 쉴 수 있었어요.', 17, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '겹겹이 결이 살아 있는 크루아상에 속재료가 꽉 들어차서 보기만 해도 풍성했어요. 접시에 담긴 모습이 정갈해서 시작부터 기분이 좋아졌네요. 바삭함과 부드러움이 동시에 느껴져서 끝까지 손이 멈추지 않았어요. 브런치로 한 끼 든든하게 잘 마무리했습니다.', 55, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '샌드위치 단면이 깔끔하게 보여서 보기부터 좋았어요. 신선한 채소랑 햄, 토마토가 겹겹이 들어가 조합이 딱 만족스럽고, 바삭한 빵 식감이 계속 생각나더라고요. 브런치로 간단하게 먹기 좋아서 기분 좋게 마무리했습니다.', 52, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '초콜릿이 듬뿍 올라간 빵에 낯선 토핑 조합이 시선을 잡아끌었어요. 한 입 먹을 때마다 식감이 여러 번 변해서 끝까지 지루하지 않았네요. 커피와 같이 두니 집중해서 즐기게 되는 시간이라 만족스러웠어요.', 42, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '초콜릿이 듬뿍 올라간 베이커리가 시선을 먼저 끌었어요. 위에 뿌려진 토핑과 겹겹이 쌓인 식감이 한 번씩 느껴져서 끝까지 질리지 않았네요. 옆에 나온 음료랑도 잘 어울려서 좀 더 천천히 머물다 가게 됐어요.', 1, 6, 'GOOD', SYSTIMESTAMP);
