INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '원목 테이블 덕분에 편안한 분위기가 잘 느껴졌어요. 샌드위치가 정갈하게 담겨 나와서 처음부터 기분이 좋아졌고, 라떼랑 같이 두니 조합이 자연스럽게 어울리네요. 천천히 식사 마치고 여유롭게 쉬다 갈 수 있었어요.', 40, 4, 'GOOD', SYSTIMESTAMP);
