INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '진열대에 크루아상 샌드위치가 가지런히 놓여 있어서 고르면서 기대감이 들었어요. 신선한 채소랑 선드라이 토마토, 햄 등 속재료 조합이 한눈에 들어와서 선택하는 재미가 있었네요. 버터 풍미가 느껴지는 빵에 식재료가 잘 어우러져서 간단한 브런치로 손색없었어요.', 67, 12, NULL, SYSTIMESTAMP);
