INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '내부 인테리어는 깔끔하면서도 따뜻한 감성이 묻어났습니다. 공간 곳곳에 놓인 소품들이 차분하면서도 아기자기해 앉아 있는 것만으로도 힐링되는 분위기였어요. 친구랑 와도 좋고, 혼자 책 읽으며 머물기에도 편안했습니다.', 18, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '부드러운 라떼 한 잔과 막 구운 빵의 조합은 역시 최고였어요. 라떼는 우유 거품이 촘촘해서 첫 모금부터 부드럽고 고소했는데, 빵과 함께 먹으니 은은한 조화가 느껴져 여유로운 오후를 즐기기에 딱이었습니다.', 19, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
