INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '진열대 앞에서 고르다 보니 종류별로 하나씩 담는 재미가 있었어요. 빵마다 토핑이나 모양이 달라서 먹는 순간마다 느낌이 새로웠네요. 직접 골라서 먹으니 더 만족스러웠고, 전체적으로 깔끔하게 진열돼 있어 선택하기 쉬웠어요.', 11, 8, 'GOOD', SYSTIMESTAMP);
