INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '브런치 구성이 깔끔하게 나와서 보기 좋았어요. 크루아상 결이 살아 있어서 한 입 한 입 부드럽게 즐길 수 있었고, 아이스 커피랑 조합도 잘 어울렸네요. 편안하게 쉬어가기 좋은 곳이라 만족스러웠어요.', 84, 11, 'GOOD', SYSTIMESTAMP);
