INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '벽에 걸린 그림이랑 조명 덕분에 분위기가 한층 더 따뜻하게 느껴졌어요. 나무 의자에 앉으니 오래 머물러도 편안해서 대화에 집중하기 좋았네요. 브런치랑 디저트로 천천히 오후 시간을 보내니까 여유가 제대로 느껴졌어요.', 29, 1, 'GOOD', SYSTIMESTAMP);
