INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '과일 토핑 색감이 화사해서 고르길 잘했다 싶었어요. 나무 테이블에 올리니 전체 분위기가 더 따뜻하게 느껴졌고, 입에 넣으면서 주변을 천천히 둘러보니 한층 여유로워지는 기분이 들었어요. 마시는 내내 편안하게 머물 수 있어서 만족스러웠네요.', 330, 99, 'GOOD', SYSTIMESTAMP);
