INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '분위기도 좋은데 빵도 맛있어요! 크루와상 진짜 좋아하는데 크루와상 종류가 여러가지라 커피랑 조합이 좋은거같아요. 모처럼 맛있는 디저트 먹구가네요 ^^', 38, 7, 'GOOD', SYSTIMESTAMP);
