INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '합정에서 옷 좀 보다 들렀는데 진짜 감성 미쳤어요ㅎㅎ 브런치도 정갈하고 디저트 플레이팅 하나하나 정성 듬뿍~ 음료는 향이 살아있어서 기분 확 풀리더라구요 사진 몇 장 찍어두니 인스타 감성 카페 그 자체예요💗', 49, 6, 'GOOD', SYSTIMESTAMP);
