INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '초콜릿이 넉넉하게 올라간 크루아상이 눈길을 끌었어요. 한쪽엔 부드러운 크림과 고소해 보이는 토핑이 올라가서 먹는 재미가 있었네요. 나무 테이블에 둘러앉아 여유롭게 이야기 나누기 좋은 분위기라 더 편안했어요.', 49, 1, 'GOOD', SYSTIMESTAMP);
