INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '아몬드 슬라이스가 넉넉하게 올라가서 보기만 해도 기분이 좋아졌어요. 검은색 접시에 담겨서 디저트가 더 도드라져 보였고, 겉은 바삭한 느낌이 잘 살아 있었네요. 브런치로 곁들이기 딱 부담 없어서 만족했어요.', 13, 10, 'GOOD', SYSTIMESTAMP);
