INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '진열대에 베이커리 종류가 다양해서 고르면서 즐거웠어요. 내부가 깔끔하게 정돈돼서 여유롭게 머물 수 있었고, 선반 위 커피잔 소품이 은근히 눈에 들어왔네요. 빵이랑 커피 함께 즐기기 좋은 분위기라 만족했어요.', 7, 5, 'GOOD', SYSTIMESTAMP);
