INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '너무 맛있게 먹고 나와서 사진이 이거 하나밖에 없는데 뭐였는지 기억이 안나니까 다음에 한번 더 가서 먹어봐야되겟네요 이 조합이 제일 맛있었습니다!.!', 42, 6, NULL, SYSTIMESTAMP);
