INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '분위기가 아주 좋아 마음에 들어요~ 커피도 고소하니 맛있고 빵 맛집이네요!! 크로와상빵 아주 부드럽고 좋아요 다음에 또 방문할께요', 41, 5, 'GOOD', SYSTIMESTAMP);
