INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '커피랑 베이커리가 넘넘 맛있는 곳 ㅎㅎ 그래서 그런지 사람이 적당히 있었다!! 카페분위기도 차분한것이 혼자와서 시켜놓고 힐링해도 좋을 곳.', 15, 7, 'GOOD', SYSTIMESTAMP);
