INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '간단히 먹고 나올 생각이었는데 바질&선드라이토마토 샌드위치 먹고 생각 바뀜ㅋㅋ 재료가 신선하고 바질 향도 강하지 않아서 부담 없었어요 빵은 바삭한데 속은 촉촉해서 너무 괜찮더라구요~ 커피랑도 잘 어울려서 조용히 힐링하고 왔네요 ^^', 13, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '크로와상 샌드위치에 이렇게 감성이 담길 줄은 몰랐어요ㅋㅋ 바질 향이 은은하게 퍼지고, 선드라이 토마토의 새콤한 맛이 입안을 꽉 채워주는데… 빵 자체도 너무 부드럽고 고소해서 식사 대용으로 전혀 손색 없었어요 한 입 먹고 아 이건 다음에도 또 먹겠구나 싶었달까요 굿굿!', 15, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '테이블에 앉으니 밝은 조명 덕에 노란 샌드위치가 더 눈에 띄었어요. 한 조각 집어먹으면서 독특한 조합에 자연스럽게 집중하게 됐네요. 담백한 플레이팅이 군더더기 없이 깔끔해서 기분 좋게 마무리했어요.', 83, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '친구가 맛있다고해서 데이트 왔는데 맛있어요! 사장님도 친절하시고  빵에 크림이 잔뜩 올라가서 좋아요  조합이 베리굿! 자주올께용!', 33, 2, 'GOOD', SYSTIMESTAMP);
