INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '카페가 인테리어도 너무이쁜데 음료랑 빵두 넘 맛있어요!!ㅎ 너무이뻐서 검색하고 예약하고 왔는데 후회없네용!! 사진찍기도 좋구 여유로운 시간보내기 좋아요', 42, 0, 'GOOD', SYSTIMESTAMP);
