INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '치폴레치킨샌드위치인데 매콤한것이 딱 내스타일ㅎㅎㅎ크로와상 자체가 맛이 좋다~ 달달한 커피랑 같이 먹으니 배가 딱 알맞게 부르다~ 메뉴선택 너무 잘한듯!! 나자신 칭찬해', 37, 9, 'GOOD', SYSTIMESTAMP);
