INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '베이커리류가 하나같이 맛있는곳, 재료를 아끼지않는 느낌이 뿜뿜. 아메에 먹으니 그냥 천상의 맛이였다. 담엔 크로와상샌드위치 먹으러 또 방문해야지. 분위기도 나쁘지않고, 따뜻한느낌인곳이다.', 14, 4, 'GOOD', SYSTIMESTAMP);
