INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '브런치 즐기기 좋은 곳이에요! 아이스커피가 깔끔하고 시원해서 커피가 맛있어요! 브런치 플레이트에 포함된 디저트와 빵이 정말 맛있어요 재료가 신선하고 조화로워요! 직원분들이 친절해요 메뉴 설명도 잘해주시고ㅎㅎ 조명이 은은해서 분위기가 좋아요! 데이트 장소로도 추천하고 싶네요!', 27, 9, 'GOOD', SYSTIMESTAMP);
