INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '카페레터 분위기 진짜 좋아요. 따뜻한 조명에 잔잔한 음악까지 완벽. 라떼도 부드럽고, 베이커리류도 생각보다 맛있어서 놀랐어요. 데이트 장소로 추천해요 😍', 22, 3, 'GOOD', SYSTIMESTAMP);
