INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '베이커리 플레이팅이 깔끔하게 느껴져서 먼저 시선이 갔어요. 겹겹이 살아 있는 디저트 결이 인상적이라 한참 들여다보게 되네요. 나무 테이블에 앉아 있으니 여유롭게 즐길 수 있었어요.', 6, 9, 'GOOD', SYSTIMESTAMP);
