INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '에코백이 깔끔하게 걸려 있어서 한눈에 들어왔어요. 옆에 있는 싱그러운 식물 덕분에 기다리는 동안 공간 분위기가 더 편안하게 느껴졌네요. 디저트랑 커피까지 함께 즐기니 시간 보내기 딱 좋았어요.', 76, 12, 'GOOD', SYSTIMESTAMP);
