INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '창가로 자연광이 넉넉하게 들어와서 앉아 있는 내내 기분이 편안했어요. 큰 화분 옆에 앉으니 조용하고 여유로운 분위기가 더 잘 느껴졌네요. 브런치 메뉴 즐기면서 천천히 쉬기 좋았어요.', 39, 4, 'GOOD', SYSTIMESTAMP);
