INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '분위기 괜찮길래 들어갔는데 디저트가 의외로 정성스러웠어요 브런치 구성도 깔끔하고 플레이팅도 이쁘더라고요 음료는 향 괜찮고 맛 균형 좋아요 감성에 신경 많이 쓴 느낌? 분위기 사진 잘 나옵니다', 41, 5, 'GOOD', SYSTIMESTAMP);
