INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '겹겹이 살아 있는 크루아상 식감에 손이 자꾸 갔어요. 신선한 채소랑 토마토가 어우러져서 한입 먹을 때마다 재료 조합이 잘 느껴졌네요. 브런치로 든든하게 즐기고 나니 기분 좋게 마무리됐어요.', 29, 6, 'GOOD', SYSTIMESTAMP);
