INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '테이블 사이 여유가 있어서 편하게 앉아 있었어요. 원목 가구 덕분에 전체 분위기가 따뜻하게 느껴졌고, 시원한 커피랑 베이커리 조합이 잘 어울렸어요. 조용히 쉬면서 한참 머물다 나왔네요.', 40, 3, 'GOOD', SYSTIMESTAMP);
