INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '트레이 위에 깔끔하게 준비된 빵과 음료 세팅이 보기 좋았어요. 빵 한 입 베어무니 결이 살아 있어서 손 끝에 식감이 진하게 느껴졌고, 아이스커피랑 천천히 곁들이니 한동안 여유롭게 머물렀네요.', 41, 10, 'GOOD', SYSTIMESTAMP);
