INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '크로와상 종류가다양하게 있어서 골라먹을수 있어요 크로와상 같튼 바삭하고 안은 쫄깃 하니 맛있었어요 슈가파우더가 뿌려져서 달콤함이 좋았어요', 48, 9, 'GOOD', SYSTIMESTAMP);
