INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '벽 조명 아래 차분하게 머물 수 있어서 좋았어요. 나무 테이블에 앉아 여유롭게 샌드위치와 커피를 즐겼고, 플레이팅이 정돈돼 있어 한 끼에 더 집중하게 됐어요.', 24, 5, 'GOOD', SYSTIMESTAMP);
