INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '크루아상 안에 햄, 치즈, 채소 등이 넉넉히 들어가 있어 보기만 해도 든든했어요. 트레이랑 커트러리 세팅이 깔끔해서 한결 안정감이 들었고, 혼자 앉아 천천히 여유를 즐기기 좋았네요.', 21, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '요즘 정말 괜찮은 카페 찾기 힘든데, 카페레터는 단번에 마음을 사로잡았어요. 가장 먼저 눈에 띈 건 감각적인 인테리어! 따뜻하면서도 세련된 분위기로, 어디를 찍어도 인스타 감성 가득한 공간이에요. 조명부터 소품 하나하나까지 신경 쓴 게 느껴졌습니다. 그리고 무엇보다 빵이 정말 맛있어요. 겉은 바삭하고 속은 촉촉한 크루아상부터, 달콤한 디저트류까지 퀄리티가 남달라요. 그냥 빵집으로 운영해도 될 만큼 수준 높았어요. 커피도 기대 이상이었어요. 산미와 고소함이 균형 잡힌 원두를 사용했는지, 향이 풍부하고 마시고 나서도 여운이 남더라고요. 커피 맛에 민감한 편인데도 아주 만족했습니다. 분위기 좋고, 빵 맛있고, 커피 맛있는 카페 찾고 있다면 카페레터 강력 추천합니다. 꼭 다시 방문하고 싶은 곳이에요! ☕🥐✨', 43, 4, 'GOOD', SYSTIMESTAMP);
