INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '테이블 간격이 넉넉해서 조용하게 머물기 좋았어요. 샌드위치가 넉넉하게 담겨 있어 한입씩 집어 먹는 재미가 있었고, 아이스 커피랑 곁들이니 시간 보내기에 딱이었네요.', 9, 9, 'GOOD', SYSTIMESTAMP);
