INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '우드 테이블이 깔끔해서 바로 편안한 느낌이 들었어요. 각각 접시에 담긴 빵과 시원한 음료가 보기만 해도 조화로웠네요. 친구랑 나눠 먹으니 대화도 더 자연스럽게 이어졌어요.', 51, 14, 'GOOD', SYSTIMESTAMP);
