INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '지나가다가 너무 예뻐서 들린 카페인데 친절하시고 카페가 깨끗했어요! 커피도 맛있고 공간도 편하고 얘기하기 좋아서 또 들릴 것 같습니다!!!🤍🤍', 12, 4, 'GOOD', SYSTIMESTAMP);
