INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '친구랑 지나가다 우연히 들렀는데 매장이 넓고 엄청 깨끗하네요!! 리본크림빵 너무맛있어요!!!!꼭 먹어야됨💙 티슈마저 감성적인 곳👍🏻👍🏻', 39, 10, 'GOOD', SYSTIMESTAMP);
