INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '최근에 합정에 있는 카페레터를 다녀왔어요. 예전부터 분위기가 좋다고 들어서 기대했는데, 직접 가보니 감성이 물씬 느껴지는 공간이었어요. 우선, 내부 인테리어가 굉장히 따뜻한 느낌이에요. 우드톤 가구와 은은한 조명이 조화를 이뤄서 편안한 분위기를 만들고 있었어요. 직원분들도 너무 친절하시고 커피랑 빵 모두 만족합니다~', 3, 7, 'GOOD', SYSTIMESTAMP);
