INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '커피도 맛있고 베이커리도 뛰어나지만 가장 감동한 건 작은 디테일 감성 넘치는 티슈 섬세한 조명 조용한 좌석 간격… 그냥 앉아있는 것만으로도 위로받는 느낌이었어요', 42, 8, 'GOOD', SYSTIMESTAMP);
