INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '커피 향이 진하게 퍼지는 조용한 공간에서 과제하며 여유로운 오후 보냈어요 좌석 간격 넓고 세면대도 있어 편하게 오래 머무를 수 있었네요^^', 27, 6, 'GOOD', SYSTIMESTAMP);
