INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '크로아상 샌드위치는 주문하자마자 바로 만들어주시는데  바삭함이 살아있어 한입 먹고 감탄했어요 이런 디테일이 계속 오게 만드는 듯해요😋', 50, 8, 'GOOD', SYSTIMESTAMP);
