INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '따뜻하고 아늑한 우드톤의 인테리어가 돋보이는 합정카페 카페레터, 백화점 팝업존에서 맛본 번의 맛과 쉐입이 인상적었는데 가을의 제철과일 무화과의 당도와 페이스트리의 버터향과 바삭한 식감이 조화로와 팝업기간동안 두번이나 찾아간 곳으로 오늘은 본매장에 방문해 팝업에서는 맛보지 않았던 두바이초콜릿번을 맛봤다. 여러겹의 페이스트리 안에 다양한 맛을 조합해서 내어지는 번은 카페레터의 시그니처, 번을 주문하면 커트러리를 같이 내어주셔서 반을 잘라 안을 살펴보는데 카다이프&피스타치오,다크초콜릿이 층층이 쌓여있어 먹기전부터 아주 흥미로웠다. 피스타치오의 고소함이 카다이프와 잘 어울렸고 번의 버터향까지 가미되어 색다른 다크초콜릿을 맛본느낌이었다. 다음에는 많이들 주문하는 핸드드립커피와 다른 번을 맛보러 재방문하고 싶은 맛집', 18, 0, 'GOOD', SYSTIMESTAMP);
