INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '티랑 라떼 시켰는데 라떼 원두맛 진짜 좋아여~~~! 엄청엄청 다양한 소금빵메뉴 있는데 다 못먹어봐서 아쉬워요 ㅠㅠ 앙버터 죤맛', 26, 5, 'GOOD', SYSTIMESTAMP);
