INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '매장 넓고 직원분들 친절하시고 빵이 너무너무너무 맛있어요 ㅠㅠ 무슨무슨 스위스 저 빵 완전 추천 !!!! 커피도 고소해서 좋습니다 최고 !', 92, 21, 'GOOD', SYSTIMESTAMP);
