INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '학교에 있는 게 싫어서 과제하러 나왔는데 분위기 너무 좋아요!!! 노래 선곡도 좋고 배가 안 고파서 디저트는 따로 시키지 않았지만 빵 냄새 미쳤어요😇 다음엔 꼭 디저트도 같이 시킬 겁니다ㅏ🥰', 111, 23, 'GOOD', SYSTIMESTAMP);
