INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '플랫화이트 라떼아트도 예쁘고 맛있어요! 아메리카노는 산미있는 원두로 했는데 제 입맛에 딱! 그리고 크로아상!!!! 카페인데 크로아상 퀄리티 뭐죠?! 맛있는만큼 사람이 많아서 조금 시끄러운것 빼곤 너무 좋아요~~(자리도 하나 있는거 겨우 앉음)', 42, 8, 'GOOD', SYSTIMESTAMP);
