INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '두바이 초콜릿 크로와상이랑 커피랑 맛있어요~^-^ 음악도 좋고 인테리어도 잘 꾸며져있어요 우연히 방문했지만 좋은 카페를 알아서 디저트 좋아하는 친구 데리고 또 방문할 예정이에요', 58, 18, 'GOOD', SYSTIMESTAMP);
