INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '근처 일정이 있어서 우연히 들어갔어요☺️ 공간이 아늑하고 분위기 좋네요👍🏻 구움과자 디저트 종류도 굉장히 다양해요! 아무기대 없었는데 커피도 넘 맛있고 라떼아트까지 디테일하게 그려주시는걸 보니 전문가가 틀립 없는거 같아요ㅋ😆', 13, 6, 'GOOD', SYSTIMESTAMP);
