INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '카페 분위기 너무 너무 좋고 이쁘게 잘 꾸며놨더라고요! 베이커리도 너무 맛있고 아주 힐링하고 갑니다! 다음에 또 와서 힐링하러 오겠습니다', 18, 1, 'GOOD', SYSTIMESTAMP);
