INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '우연찮게 들렀는데 커피도 맛있고 빵도 너무너무 맛있어요! 분위기도 아늑하고, 직원분들도 친절하시고, 기분까지 좋아지는 곳이에요🥰', 42, 5, 'GOOD', SYSTIMESTAMP);
