INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '벌써 몇번째 방문이에요 평일에만 오다가 주말에 오니까 사람들이 정말 많더라구요 다행히 한자리 남아서 바로 앉았어요 오늘도 고메버터 들어간 라우겐을 먹었는데 역시나 맛있습니다💛', 37, 9, 'GOOD', SYSTIMESTAMP);
