INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '웨딩임페리얼 티가 잇는 곳이 많지 않은데 잇어서 너무 좋앗어욤 건너편에서 사진 찍고 한시간동안 텀이 생겨서 남친이랑 갓는데 카페가 너무 이뻐욤 디저트도 이쁘고 리뷰까지 쓰면 구움과자 한개 무료라 해서 레몬 마들렌 하나 받앗어욤🫶🏻완전 럭키비키비나🍀 딸기도 존맛도리!!!', 40, 1, 'GOOD', SYSTIMESTAMP);
