INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '☕️ 메뉴 • 두바이 초콜릿 번 9.4 피스타치오 크림은 슈크림 같이 몽글하고 바삭한 카다이프와 잘 어울려요 ㅎㅎ 초콜릿코팅은 앏아서 과하게 달지 않아 좋아요. 번은 부드럽고 촉촉☺️ • 무화과 크림치즈 번 8.8 속에 크럼블이 깔려 있고 무화과 하나가 통으로 있어요!🍑 크림치즈가 듬뿍 들어있고 무화과 잼과 무화과로 토핑되어 있어 프레쉬하고 너무 맛있어요 ㅎㅎ • 스카치 밀키 커피 6.0 컵 테두리에 둘러져 있는 스카치 캔디는 눅눅하고 별 맛 없어요 ㅜ 위의 크림은 카라멜 맛이 진하고 라떼는 묽은 편이라서 아숩 • 아이스 아메리카노 (원두 러브래터) 5.0 너무 셔서 아쉬워욥😖 🌹 외관 및 내관 • 오후 1시 방문, 웨이팅 ❌ • 콘센트 적음, 노트북 작업 어려움💻 • 넓고 자리 많음, 우드톤, 햇살 굿', 24, 9, NULL, SYSTIMESTAMP);
