INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '회사근처라서 가끔 점심에 디저트 사러오는곳! 종류도 많고 퀄도 좋아서 오래오래 운영하셨으면 좋겠네요. 그 아무것도없는 쫙쫙 찢어먹는 윤기촤르르느 기본빵이 진짜 맛있는데 매장에 없네요ㅜㅜ (빵이름을 몰라서 그빵없냐고 묻지도 못하눈..^^) 번창하세요😁', 43, 7, 'GOOD', SYSTIMESTAMP);
