INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '커피 + 디저트 맛집입니다,,, 지난번에 딸기앤초콜릿번 못먹어서 속상했는데 드디어 먹어봤구 정말 맛있었어요ㅠㅜㅜㅜ (또오길 잘했다는 생각…!) 매장도 넓고 자리도 편해서 카공하기도 좋고 친구들과 대화하러 오기에도 편한 곳이에요! 합정 올 때 마다 들릴 예정입니다🥹💗 사장님 직원분들 너무 친절하셔서 기분 좋게 방문했습니다!!', 62, 17, 'GOOD', SYSTIMESTAMP);
