INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '비싼 카페는 거르는 편인데 여긴 값어치 하더라고요 디저트도 정성 보였고 브런치는 재료 조합 괜찮았어요 음료도 자극 없이 괜찮은 맛이에요 합정에서 이 정도면 꽤 신경 쓴 느낌이에요', 414, 47, 'GOOD', SYSTIMESTAMP);
