INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '카페 외관과 내부 너무 예쁜 분위기에요! 통창으로 햇빛을 보며 커피와 빵 먹기 좋은 카페입니다🤍소금빵, 크로와상, 무화과 ,라우겐,마들렌, 스콘 등 다양한 베이커리류 판매해서 브런치하기도 좋고 식사 후에 디저트에 커피 한 잔 하기에도 좋은 곳이에요👍✨💕', 39, 0, 'GOOD', SYSTIMESTAMP);
