INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '카페 분위기도 넘 좋고 결하트 아트 해주시는 카페라서 좋아요! 아트 덕분에 더 기분 좋은 커피타임이 되었어요🤍 라떼도 엄청 고소하고 디카페인도 맛있어요!', 27, 9, 'GOOD', SYSTIMESTAMP);
