INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '카페 어디가야하나 하며 고민하다 페스츄리 사진 보고 반해서 처음 와봤는데 분위기도 너무 좋고 빵도 너무 맛있어요!!!! 저는 바닐라 크림 리본 페스츄리 먹었는데 크림가득에 페스츄리는 이렇게 바삭하고 고소할 수가 없네요🥹 꼭 다음에 전 종류 빵을 다 먹어보겠습니다!!!!', 35, 9, 'GOOD', SYSTIMESTAMP);
