INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '오트밀크 변경 있어서 좋아요 !! 원두도 선택할 수 있는데 상큼한 원두 시켰는데 라떼랑 넘 잘 어울리고 맛있어요 😋☕️ 라떼 위에 하트도 넘 귀여워요 뭔가 카페랑 잘 어울리는 느낌 !!💌 따뜻하고 아늑한 분위기고 디저트도 완전 맛있어보여요 🥹🩷', 35, 6, 'GOOD', SYSTIMESTAMP);
