INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '돌아다니다 들어왔는데 친절한 직원분의 응대에 라떼맛도 넘 부드럽고 고소하네요. 이럴때 젤 행복하다는...  ^~^ 디저트도 다양하고 매장 컨셉도 우드 앤 화이트로 깔끔하고 예뻐요. 이 근처 오면 또 들려야겠어요', 66, 15, 'GOOD', SYSTIMESTAMP);
