INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '매장도 넓고 라떼도 너무 이쁘고 맛있네요!! 날이 너무 추워서 지나가다 매장도 이뻐보이고 디저트류들 많아보여서 들어왔는데 너무 잘한 선택이네요 최고 ❤️❤️', 90, 11, 'GOOD', SYSTIMESTAMP);
