INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '우연히 걷다가 발견한 카페인데 너무 예뻐서 이끌리듯이 들어갔습니다! 분위기도 너무 좋고 인테리어도 귀여워서 추천해드리고 싶어요! 따뜻한 연말 보내기 좋은 카페 같습니당☺️', 0, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '고소한 라떼와 함께 가을을 맞이하기 좋은 카페🤎 시간이 떠서 책 좀 읽고 다이어리 끄적거릴만한 카페를 찾다가 우연히 들어왔어요! 아늑한 분위기지만, 통창 덕분에 시야가 탁 트여 답답하지 않아서 좋아용 :) 디저트도 먹음직스러워서 다음에 와서 꼭 먹어보려구용🌼', 10, 0, 'GOOD', SYSTIMESTAMP);
