INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '빵 종류가 다양해요! 특히 딸기 초코번 정말 맛있어요 ^.^ 그리구 커피를 시키면 원두도 고를 수 있고 따뜻한 라떼를 시키면 라떼아트도 해 주십니다 😻', 52, 17, 'GOOD', SYSTIMESTAMP);
