INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '합정에 이렇게 통창 원목 인테리어가 있다니! 통창에 따스한 원목 인테리어로 분위기 좋아요. 굿즈들 다양한테 흘림체 글씨도 이쁘고 에코백도 이쁘네요. 무엇보다 원두 맛집, 디저트 맛집이네요! 디카페인 원두도 있고 논커피 기본 커피 다 잘하네요. 시그니처 스카치라떼 맛있고 무엇보다 사진 찍을 맛이 납니다! 패스츄리번 디저트가 시그니처인 만큼 커피랑 잘 어울려요.', 64, 11, 'GOOD', SYSTIMESTAMP);
