INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '예전부터 와보고 싶었는데 오늘 지나가다가 자리가 있어서 바로 들어왔습니다:) 핸드드립도 있고 디저트 종류도 많아서 너무 좋네요-!!!!! 카페도 우드톤이라 편안한 분위기가 나서 좋습니당🫶', 60, 13, 'GOOD', SYSTIMESTAMP);
