INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '많이 걷다보니 배가 출출해서 브런치 먹었는데 속 편하고 좋았어요 디저트는 단맛이 과하지 않아 마음에 들었고 음료도 향이 고와서 기분이 참 좋더라고요 잠시 머물다 가기 좋은 곳이었어요 ☕', 65, 18, 'GOOD', SYSTIMESTAMP);
