INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '스카치밀키커피랑 피넛크림라떼 시켰는데 둘 다 너무 맛있었어요! 두바이초콜릿 디저트는 크림엣서 피스타치오맛 나는데 진짜진짜 또 먹고싶은 맛이라 다음에 또 먹으러 가려구용!!', 114, 26, 'GOOD', SYSTIMESTAMP);
