INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '친구랑 홍대에서 놀다가 우연히 들어오게 됐는데 너무 좋았어요! 커피도 맛있고, 디저트도 다양하고 맛있오요!!! 잘 쉬다 갔어요 :)', 12, 5, 'GOOD', SYSTIMESTAMP);
