INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '오늘은 나를 위한 시간~ 디저트 한 입에 기분 좋아지고 브런치로 배까지 채우고 음료 한 모금 마시며 멍 때리는 이 순간이 너무 좋았어요 아무 생각 없이 천천히 있는 게 이런 카페에서 가능한 듯요 ☕', 30, 9, 'GOOD', SYSTIMESTAMP);
