INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '인테리어와 분위기가 좋아요 사람적은 골목에 있는데, 잠시 힐링하고 갈수있을듯 햐요 굿즈들도 예뻐서 좋을듯해요 디저트랑 커피 종류도 다양해서 자주 이용할듯해요 큰 테이블이 있어서 자리만 비어있으면 다인원도 이용가능할듯여!', 86, 17, 'GOOD', SYSTIMESTAMP);
