INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '매장이 굉장히 아늑하고 편한 분위기예요. 직원분들도 인상이 좋으시고 굉장히 친절하다는 느낌을 많이 받았습니다! 디저트, 커피도 맛있었어요!!', 26, 10, 'GOOD', SYSTIMESTAMP);
