INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '세상에 분위기도 너무 좋은데 여기 디저트가 미쳤어요 너무 맛있네요🥹❤️ 비쥬얼부터가 맛있어보였는데 먹어보니 더 맛있는... 그리고 커피까지 맛있어서ㅠㅠㅠ무조건 단골확정입니다💕 합정역이랑도 가까워서 너무 좋네요 >_< 체고!! 다들 꼭 와보세요!!', 26, 1, 'GOOD', SYSTIMESTAMP);
