INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '커피도 맛있고 플랫화이트도 찐이에여 디카페인라떼임에도 고소하고 맛있어요👍 디저트도 페스츄리 안에 크림이 그득그득해서 맛있오요 !!! 오랜만에 분좋카에서 기분전환 최고에여 !!!', 49, 3, 'GOOD', SYSTIMESTAMP);
