INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '고소한 커피랑 산미 있는 카피 마셨는데, 산미가 강하진 않아서 편하게 마시기 좋았어요. 두바이초콜릿번은 식감이랑 맛이 다 즇아서 추천! 크기도 큼직하고 맛있었습니다! ^^', 97, 20, 'GOOD', SYSTIMESTAMP);
