INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '여기는!~~! 합정역 근처에 있는 카페레터 카페입니다!!! 디저트 맛집!! 수다떨기 아주 좋은 공간 맛집이라고나 할까요!@!! 그리고 무려 두바이초콜릿 번을 팔고 있는 카페이기도 합니다!! 그리고 여기 직원분들이 엄청엄청 친절하세요~~ 두바이 초콜릿이 워낙 유명하고 맛있으니까~ 메뉴 고민을 한참 하다가 다른 메뉴를 골라서 시켜 먹었는데! 가지고 있던 두바이 초콜릿도 나눠주시고~ 짐 놓으라고 의자도 하나 놓아주시고~ㅋㅋㅋ 직원분이 엄청 매력적이고 친절하셔서! 기분 좋다 있다 간 것 같아요! 디저트도 두둠한 초코,바닐라,등 번이 여러개 있어서 다양하게 즐길 수 있어요!! 카페레터! 추천드립니다!! 🥰❤️', 201, 88, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '홍대에서 두바이초콜릿이 들어있는 번과 진한 커피를 마실 수 있는 곳이예요 ~ 커피향도 개인의 취향에 따라 골라 마실 수 있어요 산미맛을 좋아하는 남편은 러브레터 구수하고 진한 커피맛을 좋아하는 저는 그리움.. 취향 확실히 구분되는데 본인이 좋아하는 커피 마시면서 오랫만에 홍대 데이트 했어요 매장 분위기도 깔끔 청결해서 힐링되고 좋았습니다', 47, 9, 'GOOD', SYSTIMESTAMP);
