INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '공간이 너무너무 예쁘고 음료도 맛있어요! 요즘말로 느좋카페 그 자체.. 천천히 마시려고했는데 맛있어서 숨도 안쉬고 마셨답니다,, 디저트도 맛있네용 히히 버터 좋은 거 쓰시는거같아요 담에 또 올것같네요><', 15, 3, 'GOOD', SYSTIMESTAMP);
