INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '지나가다 케이크 포장하러 들른 곳인데 카페가 너무 예뻐요 커피랑 디저트류도 보기에도 좋고 맛도 좋아요 :) 합정 카페로 추천하는 곳입니당 카페 너무 시원해서 천국이에요 노래도 잔잔하고 공간 자체가 힐링이이요', 16, 2, 'GOOD', SYSTIMESTAMP);
