INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페레터 합정'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '카페 찾아보다가 디저트 보고 먹어보고 싶어서 왔는데 커피도 넘 맛있어요!! 디저트는 먹고 싶었던 맛 품절이라 나중에 또 와야할듯 ㅠㅜ', 41, 3, 'GOOD', SYSTIMESTAMP);
