INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피빈 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '금요일 저녁이라 그런지 2층엔 자리가 없고 3층에 자리 여유가 있었다. 디카페인 카페라테, 아이스아메리카노도 좋아요. 자몽쥬스도 시원하니 좋네요.', 49, 7, 'GOOD', SYSTIMESTAMP);
