INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '매장이 넓고 좌석이 편해서 좋아요- 음료도 너무 혜자고 맛있어요! 고양이도 너무 귀여워요~ 식빵 굽는거 구경할 수 있어서 좋아요 ㅎㅎ🍞🧡', 17, 5, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '사장님 남는 게 있으실 지 ㅠㅠ 계속 생각이 들 정도로 가성비 미친 곳이에오 ㅜ 그리구 위스키 엄청 많아요 ... 도장깨기 하러 종종 올 것 같아요 한 잔에 3900원부터 시작 ..', 35, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '고양이 이름이 언니인데 넌 귀여워용~ 사장님도 친절하시고 음료도 디저트도 다 맛있어요 😊 고양이 보고 싶을 때마다 오고 있어요🐱', 10, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '✅️가격 착하고 고양이 너무 귀엽고 분위기 너무 좋은 카페 강추 보드게임도 가능하다. 모든 소파도 푹신하고 위스키도 저렴하게 한잔씩 마실 수 있어 사람들이 한잔씩 즐기면서 가기도 하는.분위기 갬성 카페임 마포에 이런 곳이 존재하다니 행복하다. 자두에이드 3500원 맛은 기억이 나지 않아지만 양과 가격이 나쁘지 않다. 쑥떡라떼 3500원 그냥 그랬던 거 같다 난 쑥이라는 안맞는듯 블루베리치즈케이크 6500원 맛있음 사이즈는 작기는 하지만 푹신한 소파가 만족스러워서 좋다 [리뷰이벤트 한잔 무료]', 16, 6, 'GOOD', SYSTIMESTAMP);
