INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '분위기 좋고 가성비 최고인 카페네요!! 음료랑 디저트 다 맛있고 (특히 바스트치즈케이크 존맛..) 평일이라 조용해서 할 거 하다 가기도 좋았어요 다음에 또 방문할게요👍👍', 25, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '너무 더워서 급하게 네이버로 찾고 온 카페인데 이렇게 귀여운 고양이가 있는줄 몰랐어요 너무너무 귀욥네요 딸기스무디랑 수박주스 시켰는데 둘다 넘 맛있어용 무엇보다 홍대인데 가격이 저렴해서 깜짝 놀랐네유', 1, 7, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '고양이가 있어서 최고임 난 강아지파인데 사실 고양이도 나쁘지 않음 모든 음료가 3,500원이라는 상식파괴 혜자 카페… 수박 주스만 4,500원임 고양이님이랑 또 만나고 싶어서 재방문해야겠음', 47, 0, NULL, SYSTIMESTAMP);
