INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '우연히 검색하다가 들어왔는데!! 넘 잘 왔어요!💛 요즘 메가 팥빙이 유행이라서 여기도 신메뉴 있어서 팥빙 쉐이크 시켜봤어요! 맛은 메가보다 훨~~씬 맛있었어요! 우유가 달달 고소한 느낌!? 팥빙수 좋아하는 사람 추천드려요! 커피도 맛있고 산미 없는 걸로 시켰는데, 고소하니 맛나요! 블루베리 치크케이크 시켰는데 딱 제가 상상한 상큼한 블루베리에 치즈케이크 조합이라 넘 좋았어요! 아아랑 먹으면 짱좋아요!! 여름엔 역시 아아에 치즈케이크💛 덤으로 귀여운 고양이까지💛', 114, 21, 'GOOD', SYSTIMESTAMP);
