INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '근처 카페를 찾아보던 중, 전체적인 가격이 매우 괜찮고 리뷰에 고양이도 있길래 바로 가봤습니다. 매장이 매우 청결하고 인테리어도 되게 멋졌어요. 살짝 레트로 감성? 아늑한 분위기였습니다. 다양한 디저트를 파시는데 맛있더라고요. 놀라웠던 점은 음료는 3500원인 가성비에 불구하고 매우 맛있었어요!! 고양이 이름은 “언니” 인데 특이해서 더 기억에 남을 것 같아요 🐱 언니냥이는 사랑을 많이 받고 자라서 그런지 매우 부드러운 털을 가지고 있더라고요. 자리도 편해서 앉아서 수다 떨기 좋은 카페인 것 같습니다! 사장님도 친절하시고 꼭 재방문 하고 싶은 카페에요 ☺️ 요 근래에 간 카페중 정말 최고입니다 🫶🏼 재방문 의사 100000000프로 🐱', 10, 2, 'GOOD', SYSTIMESTAMP);
