INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '집 근처라 자주 들리는데 올때마다 좋아요 아늑하고 음료 맛있고 가성비좋고 우리 귀여운 꼬앵쥐언니도 볼수있고 행복합니두 더 유명해지면 진짜곤란해져요  하지만 이미 아는사람은 아는 곳이라 ㅋ.ㅋ 암튼 또 잘 놀다가용', 104, 22, 'GOOD', SYSTIMESTAMP);
