INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '친구 따라서 처음 와봤는데 여기 너무 제 취향이네요 흑임자 바스크 치즈 케이크랑 초코 바스크 치즈 케이크 먹엇습니다 :) 흑임자 맛이 먼저 올라와서 엄청 꼬소한데, 바스크 치즈 케이크의 짭쪼름한 맛이 마무리에 느껴집니다! 너무너무 맛있어요… 초코 케이크도 꾸덕꾸덕하니 정말 맛잇어요 ㅎㅎ 최근에 먹은 바스크 치즈 케이크 중에 제일 맛있습니다…! 음료도 다 맛있고 가격도 저렴해서 자주 올 거 같아요 무엇보다 여기 야옹이 있습니다!!💕', 10, 3, 'GOOD', SYSTIMESTAMP);
