INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '홍대 디스코플래닛 카페 다녀왔는데 진짜 숨은 보석 같았어요. 딸기요거트 스무디랑 레몬에이드 둘 다 맛있고 상큼해서 더운 날 딱이었고, 흑임자 바스크 케이크는 진짜 고소함 끝판왕! 디저트 퀄리티가 이렇게 좋은데 음료가 전부 3,500원이라니… 완전 저세상 물가예요. 분위기도 아기자기해서 친구랑 수다 떨기 좋은 공간이었어요. 보드게임도 있어서 대박대박👍🏻', 2, 7, 'GOOD', SYSTIMESTAMP);
