INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '아인슈페너부터 흑임자 바치케,, 진짜 너무 맛있습니다!! 벌써 세번째 방문이네용!!! 아인슈페너에 크림이 진짜 쫀쫀하니 맛있고 흑임자 바치케는 말(해)뭐(해).. 입니다🤍', 14, 2, 'GOOD', SYSTIMESTAMP);
