INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '카페 분위기도 좋고 치즈 케이크 종류도 많습니다. 보드 게임도 있어서 친목도모도 좋고 한쪽에는 양주가 진열 되어 있어서 구역구역마다 분위기가 좋은 카페 입니다. ㅎㅎ', 45, 2, 'GOOD', SYSTIMESTAMP);
