INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '망고스무디가 참 상쾌하고 맛있어요 :) 크림도 얹어져 있는데 조화롭고 분위기가 레트로 감성이라 좋아요 블루베리 바스크치즈케익도 새콤하고 맛있어요 사장님도 친절하시고 좋아요!', 25, 6, 'GOOD', SYSTIMESTAMP);
