INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '바스크드 치즈 캐이크가 꾸덕하고 맛있어보여 방문한 카페예요~ 바스크드 치즈케이크가 플레인,초코, 블루베리, 흑임자로 다양하구요🌟 너무 맛있어보여 선택장애 오는 비쥬얼이예요! 주문한 블루베리 바스크드 치즈 케이크는 부드러운데 엄청 꾸덕하고 치즈 맛이 찐~하게 나고 너무 맛있습니다~ 케이크 위에만 블루베리 콩포트가 있는게 아니라 케이크 안에도 블루베리 맛이 찐하게 나서 케이크 먹는데 기분까지 좋아지네요~ 커피를 부르는 디저트예요! 분위기도 아늑하고 편한 공간입니다👍 자주올거 같아요😏', 45, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '공휴일 최고의 선택!! 카페 분위기도 좋고 자리 간격도 넓어서 쾌적하게 일행이랑 이야기 할 수 있었어요. 직원 분도 친절하셔서 기분 좋았습니다😍😍 초코바치케도 짱 달다가도 끝에 치즈 맛 나서 맛있었어요!!', 25, 7, 'GOOD', SYSTIMESTAMP);
