INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '케이크가 너무 귀엽고 고양이가 짱 맛있습니다 음료 가격도 모두 3500원이라 부담없이 먹기 좋구 노래랑 분위기도 최고에오!!!', 39, 6, 'GOOD', SYSTIMESTAMP);
