INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '분위기가 너무 좋고 음료수도 가성비가…. 바스크 치즈케잌 별로 안좋아하는데 크림치즈맛도 적당히 나고 맛있는거 같아요 다음에도 오고 싶은 카페 입니다!', 37, 0, 'GOOD', SYSTIMESTAMP);
