INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '아름다워서 먹지 못할뻔 했어요 가게 분위기가 좋아서 다시 올 것 같아요 케이크랑 스무디 시켰는데 다음에도 같은 메뉴 시켜야겠어요 너무 달지 않고 상큼하고 맛있어요', 10, 0, 'GOOD', SYSTIMESTAMP);
