INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '흑임자바스크치즈케이크 단면처럼 크림 잔뜩 올라가서 맛있어요 흑임자 좋아하는 분들은 요거 꼭 주문하세요!! 그리고 귀여운 고양이가 있다는 크나큰 장점 ,, 💟', 9, 8, 'GOOD', SYSTIMESTAMP);
