INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '사람 터지는 연휴 카페찾아 서성이다 우연히 들어왔는데 이가격에 이커피 맞아요? ㅠㅠ 너무 맛있는 커피랑 쾌적한 카페 최고다최고 아지트 할게요 그리고 고양이가 귀여워요', 50, 5, 'GOOD', SYSTIMESTAMP);
