INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '제가 원래 초코 디저트를 막 좋아하는 편은 아닌데 지난번에 먹었던 치즈케이크가 너무 맛있었어서 브라우니도 시켜봤는데 너무 맛있어요..ㅜㅜ 위에 올라간 크림이랑 딸기청도 되게 잘어울려요! 커피가 워낙 맛있어서 자주 오게 됩니다 웬만한 메뉴들 다 맛있어요!', 60, 11, 'GOOD', SYSTIMESTAMP);
