INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '우연히 들어왔는데 메뉴도 너무 저렴하고 바치케 진짜 맛있었어요!! 매장도 넓어서 쾌적하구요 위스키 잔당 3900원?에 먹어볼 수 있다는데 다음에는 위스키 마셔보고 싶네요ㅎㅎ', 17, 0, 'GOOD', SYSTIMESTAMP);
