INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '크로플이 촉촉해서 맛있게 먹었습니다. 바닐라& 딸기조합도 너무 맛있게 찍어 먹었어요. 밥 먹고와서 먹는거라 다 먹을 수 있을까했는데 순삭했어요 ㅎㅎ', 130, 22, 'GOOD', SYSTIMESTAMP);
