INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '사무실 근처라 늘 오는 카페입니다!! 출근하지 않아도 친구들이랑 대화하러도 늘 여기로 옵니다! 고양이도 너무 사랑스럽고 커피도 맛있고 대화하기도 너무 편한 최고의 카페에요! 🤍서교동의 자랑 디스코플래닛🤍', 32, 6, 'GOOD', SYSTIMESTAMP);
