INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '지인들과 놀러나온 김에 잠시 들러봤는데 인테리어도 맘에 들고 음악도 좋고…무엇보다 이런 가격에 맛있는 음료랑 디저트를 즐길 수 있다니…너무 좋아요••담에도 꼬옥 오겠습니다!!', 5, 3, 'GOOD', SYSTIMESTAMP);
