INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '이렇게 시켜도 만원이 안넘어요..이게 진짜 구라아니고 사 장 님 이 미쳐써요 기여운 고양이도 있어요 근데 저는 너무 만져서 미움받았으니 여러분은 너무 만지지마시길..', 16, 8, 'GOOD', SYSTIMESTAMP);
