INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '회사 근처 아끼는 카페에요,, 이 분위기에 모든 음료가 3,500원이라니 ㅠㅠ 점심에도 많이 사먹는데 오늘은 퇴근하고 카공하러 왔는데 저녁은 분위기가 더 좋네요! 좋은 카페 운영해주셔서 감사합니다 🥹', 109, 19, 'GOOD', SYSTIMESTAMP);
