INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '친구들 데리고 가면 하나같이 다들 좋다 해요. 팥빙수 쉐이크는 제 최애메뉴구요~ 오늘은 당충전 확실히 하려고 블루베리치케도 같이 주문했어요.', 40, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '아인슈페너 한잔 마시고 감동해서 바로 돼지바 라떼 시키고 돼지바 라떼에 감동해서 팥빙수쉐이크도 시켜버렸습니다... 이가격에 이맛 이 퀄리티라니 거의 공짜라고 생각합니다 고양이도 너무 귀여워요!😚', 65, 18, 'GOOD', SYSTIMESTAMP);
