INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '홍대카페찾다가 내부구성도 좋구 따뜻하구 이쁘고 가격도 혜자(!)인 카페를 찾았어요🥹🥹❤️앞으로 자주 단골되고싶네요! 홍대 몇안되는 홍대찐옛날감성에 귀여운 고양이까지 있네요🤣☺️☺️✨✨음료도 맛있어요!', 86, 12, 'GOOD', SYSTIMESTAMP);
