INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '냥이가 너무 귀여워서 심장아픕니다 ㅋㅋ포동포동 귀요미 ㅋㅋ 전메뉴 음료 동일가 !! 음료맛은 당연 맛있으니 말할것도 없구요 건물옆에 주차도 한대 가능합니다 !', 83, 12, 'GOOD', SYSTIMESTAMP);
