INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '아인슈페너 주문 맛나게 잘 먹었습니다 제가 조아하는 원두도 예가체프 비싸지 않은 가격에 아주 잘 사서 잘 드립학서 마시고 있어요~~^^', 15, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '우준영이 찾고 먹던 자두에이드 !!! 영화 보면서 카페 위치가 서교동이라고 하길래 설마! 했는데 진짜 서교동에 있는 카페였네요 ㅎㅎ 영화에 나오던 자두에이드를 팔아주시다니,, 갬동입니더 음료 너무 맛있어요 고양이도 기여워용 💗💗💗 자두가 달고 진해서 더 맛있었어요,,, 굿굿', 84, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '모든 제조음료가 3천원인데, 맛은 프리미엄입니다~ 바리스타 분께서 직접 운영하시며 로스팅도 직접, 콜드브루도 직접 내리시고, 마스코트인 냥코 한마리가 너무 귀여웠던 카페입니다~ 자주 가게될 것 같아요~~^ㅅ^', 36, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '고양이카페가자~~!!🐈🐈🐈 이러구 언니보러 종종 갔는데 사실 커피도 가격이랑 맛이랑 다 좋아요!! 모든 메뉴 삼천원 실화입니까🫶🏻 좋아하는 원두 맛이 있어도 한번씩 다른 원두가 땡길 때 있잖아요! 여기는 원두도 다양하고 맛있어서 좋아요🤭 테이블도 많아서 여러 인원이 가도 부담이 안되네용😻', 26, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '가격은 전 음료 2,800원에서 3,000원으로 올랐어요. 그래도 착한 가격이에요. 보통의 아메리카노를 마시는 것이 손해인 곳^^ 냥이가 컨디션이 안 좋은지, 안 나오네요. ㅡㅡ;', 15, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '디스코플래닛'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '모든 메뉴2800원인데 메뉴도 다양하네요. 맛도 좋고 양도 적지 않아요. 너무 북적이지 않고 혼자서도 여럿이도 앉아있다 가기 좋은 공간인데 가성비까지 이렇게 좋다니~', 80, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요고 프로즌요거트 홍대점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '너무 습하고 더워서 아이스크림이나 먹을겸 들어왔는데 매장 너무 깨끗하고 사장님도 친절하셔서 너무 기분 좋았습니당 크럼블 쿠폰 덕분에 치즈 크럼블도 무료로 추가할 수 있었어요! 최근 새로 나왔다는 수박 아이스크림도 시식시켜주셨는데 맛도 생김새도 수박 그 자체! 🍉 수박씨처럼 박혀있는 초코 식감이 너무 좋았어요ㅠㅠ💕 제가 주문한건 오레오 츄러스 아이스크림이었는데 가격대비 양도 많고 츄러스도 바로 올려주셔서 냄새가 넘흐 조아요🫶🏻 자주자주 오고싶은 곳이에요 완전😍', 65, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요고 프로즌요거트 홍대점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '지디 팬인 가족 따라서 방문했는데 매장이 무척이나 시원하고 쾌적해서 좋아요 ! 아이스크림도 시원하고 달달 넘 맛있습니다 ! 앞으로도 번창하세뇨😆😆', 27, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요고 프로즌요거트 홍대점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '아이유 생카 즐기러 방문했는데 내부가 엄청 비좁고 사람은 북적북적~~ 자리잡기도 쉽지는 않았네요. 전시도 좁은 공간이지만 나름 빼곡빼곡히 잘 꾸며져있었구요. 무엇보다 디저트집 답게 아이스크림과 쿠키 먹었는데 진짜 맛도리~! 게다가 특전 퀄리티도 엄청좋은데 가격도 착한것 같아 상당히 만족스러웠네요! 사람많아 정신없는 와중에도 럭드까지 재밌게 하구 갔네요~ 정신없지만 즐거웠어요😃', 44, 2, 'GOOD', SYSTIMESTAMP);
