INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요고 프로즌요거트 홍대점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '키위가 상큼하고 아이스크림 양도 많아서 밥 먹고 후식으로 먹기 너무 좋았어요!!! 사장님도 친절하시고 매장 노래도 너무 좋았습니다', 74, 17, 'GOOD', SYSTIMESTAMP);
