INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요고 프로즌요거트 홍대점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '요거트 아이스크림 생각날때 주차도 편하고 반려견도 함께 갈 수 있는 요고프로즌요거트 홍대점 고고고고 수제 요거트를 직접 만드는 곳이라 맛도 좃아요', 105, 19, 'GOOD', SYSTIMESTAMP);
