INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요고 프로즌요거트 홍대점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '트로피칼 요거트아이스크림 먹었어요 !! 골드망고와 그린키위, 블루베리를 선택해서 먹었는데 새콤하니 요거트 맛이 강해서 맛있었어요 💓 현재 아이브 리즈 생카? 하고 있으니 팬분들이 가시면 좋을 것 같아요 (*σ>∀<)σ', 0, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요고 프로즌요거트 홍대점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '집근처에는...다 요아정으로 바뀌고 전에 홍대에서 즐겨먹던 요거트집도 다 폐업하고 사라져서 ...우울해하다가 검색하니 새로운 곳이 생겼다고 이곳추천해서 먹어봤는데 꾸덕하고 든든한 한끼됬어요^-^ 홍대에 놀러 올 때 요거모임친구들과 들릴 것 같아요^-^', 19, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요고 프로즌요거트 홍대점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '밥먹고 입가심용으로 큰 기대없이 사먹었다가 너무 맛있어서 리뷰 남기게 되네요ㅎㅎㅎ 일반 요거트 아이스크림은 단맛이 강해서 몇입 먹고나면 물리는데 여기는 꾸덕하고 뒷맛도 깔끔하고 치즈 비스무리하게 맛도 진해서 순삭했어요ㅋㅋ 사장님도 진짜 왕 친절하심ㅎㅎㅎ 앞으로 홍대 놀러가서 입가심 하고프면 여기 꼭 찾아갈듯 합니당! 친절하신 사장님과 맛있는 디저트덕분에 주말저녁 마무리 잘 하고 가용!♥︎', 86, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요고 프로즌요거트 홍대점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '근처에 볼일도 볼 겸 아이스크림 땡겨서 들어갔는데 메뉴도 다양하고 토핑도 다양하네요~! 배달도 돼서 배달로도 종종 이용할 것 같아요 잘 먹었습니당', 40, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요고 프로즌요거트 홍대점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '좋아하는 아티스트 공연 보기 위해 홍대 들렀다가 잠깐 시간 내서 저녁 먹으러 왔어요^^ 제가 좋아하는 그릭요거트! 맛있게 먹고 갈게요♡', 1, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요고 프로즌요거트 홍대점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '사징님 직원분 다 너무 친절하세요. 아이와 지나다가 아무 정보없이 들어온 매장인데 정말 맛있었어요. 초딩 흡입했습니다. 매장 정말 깨끗하고 깔끔해요. 다음에 아이와의 데이트때 또 방문해야겠어요.', 48, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요고 프로즌요거트 홍대점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '아이스크림이 없어서 그런건지 아니면 원래 그런건지(다음사람한테 아이스크림 없다고하긴함) 아이랑 갔는데 키오스크에 나온 아이스크림양과 너무 다름 ㅠㅠ 컵의 3분의2만 있네요;; 사가지고 나와서 나중에 생각해보니 어이없어서 리뷰남깁니다ㅠㅠ', 21, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요고 프로즌요거트 홍대점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '홍대에 새로 생긴 곳이라 궁금해서 와봤는데 매장 인테리어가 깔끔해서 좋았고 메뉴는 블루베리그릭볼에 여러 토핑을 넣었는데 꾸덕하게 선택하니깐 엄청 엄청 꾸덕해서 좋았어요! 꾸덕한거 좋아하시는 분은 추천 드립니다! 그리고 토핑으로 큐브 치즈를 넣으니 그릭 요거트랑 조합이 괜찮더라고요! 매장도 깔끔하고 맛있어서 잘 먹고 갔습니다 여기 추천드려요!', 4, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요고 프로즌요거트 홍대점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '만원인데 과일 양 엄청 적고, 만드는데 15분 걸리더라구요.. 과일도 일정하게 썰려있던것도 아닌데 왤케 오래 걸렸는지... 다음에는 안갈것 같습니당..', 6, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '컨셉도 너무 예쁘고 처음에는 어색했는데 계속 와서 말걸어주시니까 긴장이 천천히 풀려가면서 재미있게 구경했던 것같아요!! 디저트가 달아서 아아 마시는거 추천드립니당!! 근데 진짜 집사님들 다 너무 잘생기고 착하셨어요ㅠ 다음에도 친구랑 또 방문할게요!!', 114, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '가성비고 괜찮고 음식도 괜찮고 다 괜찮이요다만 비싼거는 비밀 패키지가 비싸요 25만원부터 100만원이고 중간에 40만원이에여 다른거는 다괜찮아요 음식도괜찮고 다좋아여 그날 컨디션이 안좋았긴했는데  집사님 얼굴보아서 젛아요 홍대가 있어서 멀긴 한데요 그래도 좋아요', 9, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '토요일 7시 30분부터 9시 30분까지 2시간 예약하고 2층 인페리스에 다녀왔어요:) 4명이 갔는데 가방 등 짐은 집사님(🐦‍⬛🐸)2분씩 나눠 들어주셨고 안내받은 자리에 앉았어요. 인페리스에는 카이엘, 루시, 케로, 레이, 워커, 렌님으로 총 6분이 근무중이셨고 워커님 빼고는 다 알고 있던 분들이라 편하게 대화했던 것 같아요! 렌님, 루시, 케로님과 사진을 찍었고 새로운 포즈도 도전해본 ㅋㅋㅋㅋ 그리고 루시님이 진짜 자주오셨는데 제가 단기기억상실을 해서 한참을 놀리시던🥹 인페리스 차애 위기에 처한..루시😈 *쿠로님! 베스티아에 안 갔는데도 귀가할 때, 잠시 올라오셨을 때, 외출할 때 모두 말 걸어주시며 세심하게 바뀐부분도 알아주셔서 무척 반가웠던 ㅋㅋㅋㅋ 쿠로님 보러 베스티아에 가야하나봐요…절 내버려두세요😂', 35, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '컨셉이 독특하고 집사체험을 해보고 싶어서 예약후 입장했습니다. 집사분들이 말걸어주시고 재미있는컨셉으로 한번쯤 체험하는것도 좋다고 생각합니다. 다만 점장으로 보이는 분이 시간 추가를 했는지 단호하게 확인하기 때문에 손님입장에서 시간때문에 조급해지는면이 있습니다. 뭔가 민망하고 죄지은 느낌이 들어 좀 그랬습니다. 그점만 보완하면 더 편안하게 즐길수 있을것 같습니다.', 335, 30, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '언제부턴가 홍대에 생긴 화려한 건물에 흥미가 생겨 아 진짜 궁금한데.. 무서운데! 저런곳은 인싸들이 가는건데! 라는 생각에 그동안 고민했지만! 드디어 오늘! 얼굴에 철판깔고 드디어 방문했어요! 이름부터 간지나는 임페리스 로얄로 예약해서 간지나게 2층으로 걸어 올라왔는데! 입장부터 저에게 강한 어그로를 끌어주셔서 감사해요. 이런 박수를 받는건 오랜만이라 저 약간 우쭐해졌어요! 레어몹이 된 기분! 나쁘지 않아요! 이거 재밌을지도!👻 우하하! 정말 감사합니다! 애플워치 오우너 집사님! 이름이 정말 인상적이라 아직까지 기억이 나네요! 이곳에서는 다양한 종족들이 살아가요! 다크엘프도 있고 애플워치족도 있고! 완전 많아요! 아랫층엔 짐승족이 살고있다는 소문이 있어요! 아랫층은 어떤곳일지 궁금해요!', 116, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '예전에 방문했을 때 즐거웠던 기억이 있어서 두 번째로 방문했습니다 ~ ✌️ 내향적인 성격이라 집사님들과의 대화가 조금 어색하긴 했지만 💦 편하게 대해주셔서 덕분에 즐거운 시간을 보냈습니다 🍀 처음 온 친구도 정말 재미있었다고 좋아했어요~ 뿌듯 ✨', 51, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '컨디션이 안좋아서 참고 가니까 그래도 집사님 얼굴 조아서 좋았어요 그리고 디저트도 너무 맛있어요 아쉬운점은 여기 갈때마다 시간 추가가 저는 운이 없는건지 자꾸 예약이 밀려서 안된다고 하더라고요 왜인지 모르겠는데 제가 갈때마다 시간 추가할려고하면 예약이 밀렸다고 하다니 너무 아쉬워요 집사님 얼굴 보아서 좋기도 하고 갖다 오니까 몸살이 도졌긴 하지만 그래도 좋앗어요', 50, 2, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '건물외관이 너무 예뻐서 사진 찍기 좋았고 집사카페 처음이었는데 집사님들도 너무 친절하시고 애프터눈 티세트도 너무 맛있었어요! 사실 사오는거 아닐까 했는데 정말 몇가지빼고는 다 직접 굽는다고 하시더라구요! 감사했습니다ㅎㅎ', 63, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '뒤늦은 후기지만 본가 올라와서 처음 와봤는데 예상보다 싼 가격이라 놀랐습니다..(제가 집사님들에게 인증샷 외에 아무것도 안해서 그런 것도 같습니다..) 근데 진짜 얘기도 잘 들어주곸ㅋㅋㅋ 컨셉 독특하니 너무 좋아서  시간연장도 하고 있었던 거 같아요 ㅎㅎ 너무 즐거웠습니다!', 92, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '인페리스 2시간 예약하고 다녀왔어요:) 오늘은 렌 집사님과 샴페인을 하기로 한 날이라 들뜬 기분으로 집사카페에 들어갔어요 ㅋㅋㅋㅋ 1시간은 친구랑 같이 앉았고 샴페인 할때는 각자 앉았어요! 카이엘님이 휴지꽃도 접어 주셨는데 지금은 어디에 뒀는지 기억이 안나네요.. 오늘은 사진을 한번도 찍어보지 않은 케로, 라무님과 사진을 찍고 궁금랬던 레이집사님 라이브쇼도 들었어요 ㅎㅎ 다른집사님과 다르게 의자에 앉아서 불러주시는 🫣! 이날은 유독 출근한 집사님들이 많아 자리에 많이 와주셨고 대화를 많이 했던 기억이 납니다. 늘 기분좋은 느낌을 주는 인페리스 오늘도 힐링하고 왔어요~ 샴페인 후기는 제 블로그에 따로 올리도록 …! 할게요🫶', 12, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '친구랑 같이 갔었는데 그래도 재미있었어요 ~ 집사님들이 잘해주시고 그렇긴한데요 애프터눈 티세트 1인이 2 ,0000원이고 1인세트가 2,0000원이지만 시간을 추가하면 7,000원이고 시간을 추가하면 두명이 왔을때는저거를 한번더 시켜야합니다. 가성비가 더들긴해요 그리고 2인이 애프터눈 티세트가 3,8000원이고 시간 추가하고 한번 더시키면 가성비가 더들긴해요. 1시간이라는게 아쉽고 그래도 시간이 금방가는거 같아요 1시간이랑 진짜 아쉽고 근데 시간 추가할려고 하면 이미 마감이 되었다고 하는데 제가 운이 없는건지 아쉽기는 하네요 저번도 시간 추가할려는데 마감되었다고 하고 해서 조금 아쉽지만 즐거웠어요. 음식은 맛있어요.', 21, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '루치펠 유일한 여집사님 졸업일이라, 해당 집사님 이미지를 테마로 한 꽃다발을 들고 또 귀가했습니다. 졸업일을 함께하기 위해 진짜 많은 분들이 방문하셔서 북적북적 ㅎㅎ 다리를 좀 다친 상태로 갔는데 집사님들이 엄청 신경 써주셔서 (거의 아장아장 아기 된 느낌ㅋㅋ) 불편함 없이 잘 놀다 왔어요! 오페라 넘버 라이브가 가능한 집사님 노래도 신청해서 들어봤는데 진짜 후회 없습니다!', 47, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '좋아하는 집사님 근무지 인스타에서 확인하고 1,2층 번갈아가며 주마다 가고 있어요. 근무지가 고정인데 파견?으로 바뀔 때가 있더라고요. 집사카페가 처음이고 궁금하시다면 2층 인페리스로 가세요! 직장동료,지인,가족, 저 또한 2층이 훨씬 좋았어요. 2층 집사님들은 바쁘셔도 한번 이상은 와주시는데 1층 집사님들은 근무중인 집사님 반 이상이 안 오실때도 있었어요ㅠ(그냥 카페간줄…) 그래도 1층이 궁금하시다면 쿠로님 있을때 가세요. 자주 와주는데 눈치도 빠르고 재밌어요🤣 기억에 남는 집사님들을 몇자 적어보자면..! 루시님: 예쁘고 기계 같아서 귀여움/케로님: 키가 크고 말 잘 걸어줌/레이님:말이 빠르고 웃김/카이엘님:잘생기고 저음(친구 최애)/렌님:진짜 다정하고 잘생김 행동이 귀여움. 내가 집사카페 가는 이유❤️', 43, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '대기할 때 앞에 정원?도 너무 예쁘게 꾸며져있고 인테리어가 너무 예뻤어요,,, 무한적인 나데나데를 받으러 갔으나 한 집사님이 저를 계속 놀리셔서 이게 맞나? 싶엇지만 재밌었습니다. 다들 컨셉 확실하시고 개성 넘치시고 계속 말 걸어주세요,,, 종을 울리지 않으면 디저트를 절대 꺼내주시지 않으니 참고하시면 좋을 것 같습니닿ㅌㅋ', 0, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '경험하고 싶은 곳이어서 갔다왔어요 리뷰 안 좋길래 걱정했는데 생각보다 집사님들도 친절하시고 노력하시는 게 보여서 좋았습니다! 잘 챙겨주려 노력하시는 게 눈에 보였어요 다만 디저트 퀄리티는 높여야 하는 게 맞는 거 같아요 이만원 치곤 맛이 너무 없어요,,, 맛 없어서 남겼어요,, 재방문 의사 있어요! 방문하시는분들도 한 시간이면 좀 애매해서 두 시간 정도 방문하면 더 좋을 거 같아요! 참고로 체키나 라이브 같은 건 하려면 유료에요!', 52, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '집사카페는 처음인데, 재밌었어요. 딸이 좋아해요. 다음에는 시간 추가 할 수 있게 더 일찍 가야겠어요. 라무집사님 워커집사님 친절하세요. 감사합니다.', 7, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '완전 대박 좋아용 역시 내사랑이들 이번에 남작이 되었다. 너무 좋았어용 내가 빨리 오긴했지만 계속 말 걸어주셔서 감사했습니다 다들 보고싶을거예요', 30, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '집 근처에 집사카페가 많지만 여기가 원픽인 이유는 외관부터 완벽하고 집사님들 캐릭터가 다양해서가 아닐까 싶어요. 당주님 더 많은 캐릭터를 발굴해 주세요♡', 14, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '예전부터 인터넷에 자주 올라오는 집사카페와 메이드카페가 너무 궁금해서 친구와 놀러나온김에 집사카페에 한번 도전해 보았습니다. 제가 생각했던 카페와 달리 입구부터 으리으리해보였습니다. 멋지신 집사분이 나오셔서 안내를 도와주셨고 맛있는 차와 디저트도 시켰습니다. 중간중간 다른 집사님들이 오셔서 말을 거시는데 제가 생각보다 너무 부끄러워해서 말을 잘 못했습니다. 중간에 다른 분이 라이브도 신청하셔서 덕분에 잘 들었습니다. 마지막으로 온김에 사진도 찍자! 해서 고양이집사님과 사진을 찍었습니다. 처음 경험하는거라 어질어질하고 부끄러웠지만 나름 재미나는 경험이였던것 같습니다..! (가격은 아무래도 쪼끔 나가여~)', 71, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '생일인 집사님과 졸업을 앞둔 집사님 보러 다시 귀가했어요~ 덕분에 태어나서 생일카페라는 곳도 처음 가봤네요 ㅋㅋ 제 인생에 재미 +1이 되는 곳입니다!', 5, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '세세하게 다른부분도 알아봐주시고 틈틈히 바쁘신데도 물어봐주시고 센스가 너무 좋으신것 같아용 혼자론 처음가보는데 혼자 생각하는 시간이 너무 좋은 것 같습니당 특히 체키 너무 맘에 들어요!! 지금까지 찍은 체키중에 제일 맘에들엇던 ㅋㅋㅋ 너무 힐링되구 혼자만의 생각을 정리 하기도 딱 좋은 날이엿던 같아요 ! 다음에도 기약 햇으니 그때만은 좀 말을 많이 할려구요 ㅋㅋㅋ🥰 리무님 카프타?님 너무 괜찮앗어용 ㅎㅎㅎ 🤭☺️', 38, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '루시펠은 정말 정말 정말 친절해요! 방학 중에 잠깐이라도 시간이 나면 항상 몇 날이라도 예약하려고 해요. 루시펠에서 항상 너무 즐거운 시간을 보내고, 새로 들어온 집사들을 만나는 것도 좋고, 제가 좋아하는 집사분들을 다시 보는 것도 너무 반가워요. 집사분들은 항상 너무 친절하고, 제가 학교 때문에 오랫동안 못 와도 저를 기억해줘요. 그래서 갑자기 방문했을 때 저를 기억해주는 모습이 항상 감동이고, 루시펠에서의 시간을 잊을 수 없게 만들어줘요. 🌹', 71, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '집사 카폐 와서 좋았는데 음식도 좋았긴한데 음료도 맛있고 잘해도 주시긴하는데 물온 좋긴한데요 집사님들이 다른 손님들에게는 잘 말도 잘걸어주시고 되게 길게 이야기 해주시는데 저는 안그래서 속상했어요 ... 이거 리뷰 쓰다가 어제일 생각나서 눈물 나고 슬프네여 갈때마다 그러니 속상해요.. 물론 다른 2명 집사님은 다음에 말 많이 걸어주긴다고 하긴핬었긴 하는데 슬퍼요', 32, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '입구부터 집사님이 상시대기 타주셔서 아가씨대접 재미나게 받고갑니다!💕 처음가본 장소였는데 아가씨 심심하지 않게 말 많이 걸어주셔서 감사해요😎 라이브 공연도 덕분에 재미나게 관람했어요! 음료도 추천해주셔서 감사합니다!🩷', 47, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '이전 회사에서 연차 사용을 장려하는 홍보하는 업무로 소식지에 특색 카페로 홍보 내용으로 기획하면서 알게 된 곳이에요 부끄러움이 많아서 고민하다가 퇴사 기념으로 방문 했는데 다들 친절 하시고 혼자 가서인지 더 친절하게 챙겨 주시더라구요ㅎㅎ 컨셉은 분명히 있지만 환심이 아니라 진심으로 배려하는 태도와 존중 받는다는 느낌을 받았어요 저는 상담사로 직종 전환 준비 중인데 사람 상대하는걸 어려워 하거든요.. 오늘 한 분 한 분 다가 와주시는 분들 뵈니 프로라는 느낌이 들었어요 단순히 컨셉만으로 대하기에는 난이도가 높은 직업 환경인것 같더라구요 제가 소음에 취약해서 정신이 하나도 없었는데 평일에 가보고 싶네요ㅎㅎ 오늘 받은 배려와 친절 감사했습니다~', 98, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '친구 생일기념으로 이색체험 느낌으로 데리고 갔느데 우선 굉장히 신선한 경험이였어요, 적응 하면 괜찮겟지 하고 온갖 세포를 다 곤두세워 적응하려 몸북둥치는데 공주님 외출시간이라고 해서 적응만 하다가 퇴장함, 다들 컨셉에 맞춰서 열심히 하시는거같아여 여기 오시는분들 보니까 진짜 찐으로 이런 컨셉을 즐기시는분들만 오시는듯 ,,! 방문하시는분들도 심상치 않아요 그리고 제가 방문한날에 뭐 이벤트 하는날이였는데 선택사항이 아니라 필수라 두명 입장료 4만원에 에프터눈세트2인 해서 78000원 태우고 왔는데 솔직히… 제가 세상 테어나 그동안 쓴 모든 소비와 지출중에 제일 아까웠습니다..', 32, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '음식도 맛있고 .. 음료도 맛있고 .. 다 좋았어요 .. 집사님들도 좋았어요 .. 아쉬운게 .. 하나 있는데요 뭐라고 설명하기 어려운데요 .. 집사님들이 다가 오지 않아서 대화를 먼저 안해주셔서 아쉬운거 같아요.. 다른분들 보면 계속 대화 하는데 보였는데 .. 아쉬운거 같습니다. .', 84, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '오글거릴거 같아서 갈까말까 고민하다가 이런경험  언제 해보겠냐 싶어 큰 맘 먹고 가본 집사카폐 루치펠! 처음에 들어가서 몇분간은 부끄럽고 오글거리고 부끄럼은 오로지 내 몫인거 같아 미칠거 같았지만 어느새 적응한 내자신...ㅋㅋㅋ 분위기에 한번, 집사님들의 미모에 한번, 말솜씨에 한번! 계속 힐링되느라 정신 없었지만 결과는 너무나 좋았다 ㅎ 나중엔 집사님들과 수다도 떨고 친구처럼 스스럼이 없었다는! 왠지 계속 갈거 같은 예감이... ♡ㅡvㅡ♡', 62, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '우연히 지나가다가 건물이 너무 아름다워서 분위기 좋은 카페라고 생각했습니다. 알아보니 컨셉이 있는 집사카페였더라고요. 앞에 정원 분위기가 너무 이쁘기도 하고 실내도 궁금해서 예약 후 방문해봤습니다. 컨셉이 있는 만큼 좀 부담스럽다거나 부끄럽기도 했는데요. 이게.. 어느정도 적당히 컨셉이면 모르겠는데 건물 외관부터 그냥 모든 게 컨셉에 잡아먹힌 느낌이라고 해야할까요. 너무 제대로 되어있다보니 오히려 어색해하는 제가 이상한 느낌이었어요. 중간 중간 다가와서 말도 걸어주고 다정하게 대화도 시도하고 그래주니 만족도는 좋았습니다. 사람들 구경하는 재미도 있었고요. 카페에서 나올 때 "아가씨 외출하십니다!" 소리쳐서 이목 끌고 문 열고 내보내주는 게 제일 부담스러웠습니다. 가실 분은 참고하세요..', 61, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '진짜 좋았는데 그때 안좋은일이 있어서 울어버려가지고 집사님들이 달래줘서 감사했었어요 .. 홍대에 좀 무서운 여자애들이 많더라고요 .. 진짜 정원도 이쁘게 꾸며져 있고 진짜 좋았습니다 ~ 디저트가 비싸긴하지만 최고 입니다', 30, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '오늘 다른 아가씨들이 노쇼하시는 바람에 저 혼자 한시간 동안 여러 집사님들을 독차지하는 행운을 얻었네요 ㅎㅎ 넘 즐거웠고 조만간 또 뵈요!!', 47, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '쿠로님 포함해서 모든 집사분들이 돌아가면서 심심하지 않게 스몰토크 걸어주셔서 좋았어요😘💖 다음에도 친구랑 가고 싶어요! 디저트도 맛있고 여러모로 최고예요🫶🎀', 37, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '시간 제한 있는 건 알겠는데 먹고있는데먹고있는데 접시 가져가려는 건 아니지않나요? 두명이나 와서 접시 치워도 되냐는데 먹고있다가 체할뻔. 퇴근인지 뭔진 모르지만 치우려고 드릉드릉해서 어이가 없었어요. 샴페인 정도는 시켜야 옆에서 얘기하는 것 같고. 뭔가 기대했던 방향이랑은 좀 많이 다르네요. 세미 호바느낌? 자꾸 체키나 뭐 더 시키라고 눈치주고 ㅋㅋ 메이드카페가 더 재밌는 것 같습니다.', 43, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '집사분들 모두 친절하게 대해주셨구🥳 처음에는 너무 어색해서 몸둘바를 몰랐지만, 막상 외출 시간되니 섭섭하더라구요🥹🙌 모든 집사분들이 스몰토크 걸어주셔서 감사드렸구!! 폴라로이드 예쁘게 꾸며주신 쿠로님 감사합니다ଘ(੭ˊ꒳​ˋ)੭✧💖🩷', 19, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '두번째 방문, 저택은 외관상으로도 엄청 예쁘고 들어가도 반짝반짝해서 기분좋은 느낌이 들었어요. 1,2층으로 나뉘어져 운영되고 있고 집사님들 마다 소속이 다르고 고정 근무지가 아니기에 원하는 집사님 출근표 확인하고 예약하는게 좋을 것 같아요. 처음 들어가서 자리 안내해주신분이 렌 집사님이였는데 눈이 많이 가고 친절한 말투랑 행동이 좋았어요. 사진 찍었는데 쏠려서 다시 찍자고 했고 엄청 다정하게 잘 찍어주십니다! 너무 아쉬운게 사진에 얼굴이 안담기세요.🥲(4월 중 다시 보러 갈게요ㅎㅎ) 레이 집사님은 자신감이 좋고 결과도 매우 좋아요👍 화장실 갔는데 라이브쇼가 시작되서 무대 뒤쪽에 그냥 서 있었어요. 화장실이 무대 동선이랑 겹치기도 해서 시간이 정해진 곳이니 라이브쇼 하기 전에 미리 안내해주면 좋겠어요.', 43, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '저희 추가비용 결제 안한다고 한 순간부터 테이블을 후다닥 치우시는..ㅠㅠ 아직 이용시간 20분정도 남았었고 먹고있는데 치워도되냐구 다 가져가시더라구요~~ 그래서 휑한 테이블로 십분정도 방치되었습니다😭😭 5분정도 남았는데 다른테이블 퇴장하니까 같이 퇴장시키더라구요 30분쯤부터 계속 추가결제 할거냐고 물어보시고~~ 돈이 좀 아까운 느낌..ㅠㅠ 컨셉도 제가 더 진심인것 같았습니다 재방문 의사 없어요..~~', 49, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '이때 영국 친구랑 같이 같았는데 너무 좋았어요 ~ 진짜 힐링 되고 좋았고 집사님들이랑 재미있게 사진도 찍고 라이브도 보고 재미있었습니다 ~ 집사님들이 다 너무 잘생기셔서 너무 좋았어요 ~', 38, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '다른 집사카페들과 달리, 이곳은 말을 걸지 않으면 먼저 다가오지 않았고, 다섯 번정도 나눴던 대화에서도 중간에 갑자기 자리를 뜨거나 성의 없이 응대해 불쾌했습니다. 두 타임 예약을 했음에도 예약이 누락돼, 첫타임이 끝날 즈음 알게되자 당황하며 태도가 바뀌었습니다. 마치 ''돈을 안 쓴 줄 알고 대충했는데 두타임이나 예약했던 분들이네. 어떡하지'' 라는  인상이 강했습니다. 전반적으로 서비스는 기대 이하였고, 다시 방문하고 싶지 않았습니다. 그런 취급을 받고 2층을 올라가니 그제서야 돈을 쓴 사람들이라는걸 인지한건지 열심히 말을 걸어주시더라고요. 참 다른 의미로 재밌던 경험이었습니다.', 22, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '작년 8월 10일에 가고 어제 오랜만에 갔는데 다들 절 기억해 주시고 너무 좋았어요. 레오 집사님 왜 팔을 다치셔서 사람 마음 아프게 해요…. 다음에 갔을 땐 꼭 다 나으시고 그때 만나요~', 102, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '처음 방문하게 되었는데 재밌는 경험이였어요 집사님들 다 잘생기셨고 친절하셨어요 처음이라 잘 못 적응했지만.. 아쉽게 다음일정때문에 시간 못 채우고가서 아쉬웠어요ㅠ 특히 하쿠님 발레타인님 기억에 남아요 ㅎㅎ 좋은 추억남기고 가요', 17, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '오랜만에 귀가이면서 인페리스 첫 귀가임에도 불구하고 반겨주시고 혼자온 제가 심심하지 않게 집사님들이 돌아가며 자주 찾아오셔서 대화도 많이 하고... 중간에 쿠로님의 멋진 라이브도 듣고... 집사님들 덕분에 힐링에너지 1000%채우고 돌아왔네요 당분간은 업무 스트레스가 쌓여도 덜 힘들것 같아요 오늘 집사님들 전부 너무 감사했습니다', 7, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '두번째 메데 작년도 가고 이번년도도 갈거라고 생각 조차를 못했고.. 대저택이 생기고서 더 냥냥해진 메이드님들.. 잊지못하는 날..~!', 62, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), 'My friends and I really enjoyed our visit. It was a unique experience and every butler was so lovely and kind. Kero was also a great butler and my friends really enjoyed their conversation with him. My friend also was so flattered ☺️to be called “David Beckham”  by the butlers. Thank you gentlemen for a memorable evening. 고생 많이 하셨습니다, 감사합니다 :)', 26, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '생일 기념으로 갔습니다 세상에 잘생긴 사람들이 다 여기있어서 길가에 없나봅니다 사실 후기찾아봐서 인스타 집사님들 피드보고 출근표확인하고 방문하긴 했는데..ㅎ 고양이집사분 사진보다 실물이 너무 잘생기셔서 놀랐습니다 입틀막했습니다 아가씨체험 해볼만 합니다 재밌어요', 4, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '내향인으로서 조오금은 힘들었지만, 전부터 와보고 싶었던 곳이기두 하고 흐름이 끊기지 않게 번갈아가면서 말걸어주셔서 마치 놀이공원에 온 느낌이었어요! 올 봄에 또 올게요! 렌 집사님! 수습끝나고 정규직으로 전환되어있으면 반가울 것 같아요ㅎㅎ', 46, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '진짜 대저택느낌 디저트와 차도 맛있어서 깜놀 정말 아가씨(공주님)된 듯한 느낌이 들어 행복했다 젠틀하신 집사님들덕에 계속 웃고 즐겁게 있었다! 처음이라 낯설었지만 적응하니 또 가보고싶은곳 집사님께서 맛집추천해주셨는데 큽 찐맛집이라 재료소진 ㅋ쿠궁..담에 다시 도전할예정!', 74, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '대저택에 첫귀가 했어요:) 잘생긴 집사님들♥︎ 돌아가면서 소개해 주시고 , 케어해주시는데 너무 행복했습니다. 첫방문이라 최애집사님과 차애 집사님을 정하지못해서 조만간 다시 방문해서 최애 집사님과 차애집사님 꼭 정하겠습니다>ㅅ<', 36, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '이런 카페 처음인데 되게 신기한 경험이었습니다! 도일 집사님 덕에 너무 즐거운 경험이었네요 🥺 정말 집사처럼 예의있게 대해주셔서 아가씨가 된 기분이었어요,,,,,, 오래 기억하고 싶어서 체키라는 것도 찍어봤습니당! 엄청 길고 예쁘게 꾸며주셔서 감동👍 도일집사님 때문에 한 번 더 가려구요. 다음에도 저희 테이블 담당이 되어주세요!', 59, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '아직 정직원이 되시지 못하셨지만 다음에 봤을 때 정직원 집사님으로 봐요! 🤧❤️ 사진보다 실물이 훨씬 잘생겼구 귀여운 집사님-! 다른 집사님들도 친절하시고 끼가 넘치는 분들이니 꼬옥 방문 적극 추천!!✨️✨️', 81, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '딱 4번째 방문!! 드디어 남작 카드로...👀❤️ 한 번쯤 방문하신 분들이라면 한 명 정도 마음에 드는 집사님들이 있으실 거라 생각합니다!... 그러니 또 가실 때는 인스타로 집사님들 출근표 확인하고 가시는 걸 추천드려요~! 가끔 안 오시는 분들이 대타로 오실 때도 있지만 🤧💦 체키나 무대도... 가면 한 번정도는... ㅎㅎ 추천드립니다! 다들 노래나 춤을 굉장히 잘 추고 가까이서 볼 수 있기에 집사님과 가까운 거리에서 눈 맞춤이나 손 정도 잡아주시는 서비스가...! ㅋㅋㅋ', 18, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '친구 생일이라 완벽한 아갓쉬로 만들어주기 위해 방문했습니다˚‧｡♥｡‧˚우선 대저택에 걸맞은 외관 비주얼이 좋았습니다! 예약제라 여유 있게 입장하고(노크 세 번)디저트는 제 생각보다 맛있어서..!좀 놀랐습니다. 차도 개인적으로 괜찮았어요. 종을 울리면 오셔서 도와주시고 정말 색다른 경험이라ㅋㅋㅋ즐거웠어요! 첫 귀가인데 무대도 세 번이나 봐서 황송합니다.춤 노래 다 다른 분으로 구경했는데 다들 수준급이에요ㅋㅋ그리고 쿠로 집사장넴 Queen never cry..★너무 재미있으시고 센스있으세요! + 항마력 걱정 할 필요 없어요 왜냐..~다들 잘생기셨고 편하게 잘 대해주시고 번갈아가면서 테이블 오셔서 이것저것 플러팅 해주셔서ㅋㅋㅋ진짜 아갓쉬 대접 제대로^^..!도일님,하쿠님도 즐거웠어요! 다음에 또 귀가 하러갈게용!', 86, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '오늘 너무 즐거웠고 다음에 또 방문할게요! 앞으로도 집사카페는 여기만 올거같네요 디저트도 너무 맛있고 또 다들 친절하셔서 좋았어요 진짜 추천합니다! 집사님들 오늘 하루 감사하고 다들 잘해주셔서 고맙습니다 꼭 또 올게요! (쿠로집사님 팬됬어요 오늘 즐거웠습니다)', 107, 25, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '두번 째 방문!😘 이번에는 영상으로만 보던 쿠로 님 실물 영접했습니다! ㅋㅋ🤧🫶 새로 오신 라무다? 님도 너무 친절하시고 귀여우셔서 다음 귀가에도 꼭 보고 싶어요!! 2월달만 3번 가는 저에게 잠시.......  🥹 다음에 갈 때는 집사 님들 춤이나 노래? 보러 갈 것 같아요! 다시 가도 기 빨려서 나온 후에 친구랑 왕창 웃고 집에서 꿀잠 잤던 기억이!.... 한 번쯤은 가보시는 걸 적극 추천!!🩷', 22, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '상상이상으로 정말 친절하시고, 분위기도 잘 풀어주셔서 좋았습니다~! 애프터눈티도 맛있었어용!! 특별한날 방문하면 정말 좋은 추억이 될거에요ㅎㅎㅎㅎ 감사했습니다!!🥺✨', 93, 20, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '집사 카페는 처음 가봐서 엄청 긴장했는데 말도 많이 걸어주시고 편하게 대해주셔서 신선하고 재밌는 경험이었습니다...! 다음 달에 또 방문할 생각입니다 👀🩷 루이 님이랑 하울 님 꼬리에 여러 번 닿기도 했지만? 그저 그 상황도 재밌었습니다!! 이번 년도에 방문 많이 할 것 같아서 좀 쑥스럽네요 😅💦 그만큼 색다른 경험과 재밌는 추억을 쌓을 수 있는 곳이라 생각해요 다들 너무 매력적이고 잘생기셨습니다!', 31, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '인페리스는 첫 귀가였는데 잘해주셔서 너무 좋았습니다 집사님들께서 모두 착하시고 재밌습니다 역시 최애 루시님은 사진으로 봐도 실물로 봐도 bb 너무 잘 놀았어요! 감사했어요 조만간 또 갈게요!', 40, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '인페리스는 두번째 귀가였는데 다들 선물 좋아해 주셔서 감사했어요 집사님들 너무 착하시고 음식도 맛있어요 가보고는 싶은데 항마력이 많이 딸리고 부담 될거 같아 하시면 인페리스 추천 드릴게요 인페리스가 크기가 가장 작기도 하고 쉽게 적응 할 수 있게 친근히 다가와 주십니다', 15, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '집사 카페 한번쯤 가보고 싶었는데 말주변이 없어도 집사님들이 친절하셔서 재미있게 즐길 수 있었어요! 😊 운 좋게 공연도 2번이나 보고 같이 간 친구들도 재미있었다고 했어요! 추천~ 👍', 100, 26, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '처음으로 혼자 가봤는데 오히려 많이 챙겨주셔서 좋았습니다 ! 집사분들 다들 개성있으시고 재밌으셔요 ! 처음가서 최애 집사님도 생겨보고 자주 가지 않았던 홍대도 자주 가게 되었어요 ㅎㅎ 나름 가치 있는 활동이라고 생각하고 늘 즐기다가 와요 ! 1시간 보다는 2시간 이상 있는 것 을 추천드립니다 !!', 14, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '첫 귀가 후 ''힐링 명소'' ''영혼의 안식처''라는 타이틀을 붙였습니다 저택에 상주해주시는 모든 집사님들께 감사드리고 있어요 애니메이션이나 매체로만 접했던 집사카페가 한국에도 언젠가 생기기를 염원하곤했었는데 A - Z 까지 이렇게 완벽한 루치펠이라는곳이 상륙하다니 참 기뻤습니다 서민생활을하면서 받아온 상처로 인한 평생의 트라우마가 꽤 심한편이라 창피하긴하지만 정말 솔직히 말하자면 따스함과 다정함에 익숙지않아 살짝 울컥했었어요 최근에 모종의 이유로 짐이많아 손이 부족해 받은것에비해 너무나 약소한 선물을 드리고 와서 아쉬웠는데 다음 귀가시엔 더 제대로 정성 꽉 눌러담은 큰 가치가 느껴지는 소중한 선물을 남길예정이예요 사회에서 한없이 하찮은 저란 존재가 이곳에서만큼은 귀한 존재가되는 마법 마법 주문 감사합니다💙', 130, 21, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '집사님들이 너무너무 멋지고 아름답고 귀엽고 온화해서 제가 너무너무 심쿵했어요 출근이 아니신 울 쿠로님이랑 체키랑 라이브 너무 감사드립니다', 124, 24, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '제가 이런 대접을 받아도 되는 건가 (가격 생각하면 될 것 같기도 하고..) 싶을 정도로 태어나 처음 아가씨가 되어보는 순간이었습니다..🥺👍 사실 여성분들.. (남성분들도) 마음 속 깊은 곳에 웹툰 귀족 영애들의 삶, 디즈니 공주들의 삶, 애니메이션 아가씨들의 삶 한 번 쯤은 꿈꿔본적 있잖아요 ^_^ 어릴적 세바스찬 키우고 싶었던 사람으로서 아가씨라고 불려보니 너무 좋았습니다. 집사 분들도 모두 친절하시고 컨셉에 확실하셔서! 이런 테마카페는 뇌 빼놓고 현실 자각 못하게 만들어버리는 게 중요한데 다들 노력 많이 해주신 것 같아요 ㅎㅅㅎ 제가 낯가려서 잘못 받아친 것 같아 죄송할뿐,, 계속 말 걸어주시고 대화해주셔서 디저트도 입장 25분 만에 첫입 먹을 정도였어요! 마지막 인사 때 이름도 기억해주시고 감사해욧!', 14, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '맛이 기가 막히고 보기만 해도 식욕이 넘치지만 분량이 많지 않아 세련된 편이다. 승재도 싱싱하고 간이 적당하고 불 조절이 잘돼 음식이 빨리 나온다.', 62, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '처음으로 집사카페에갔는데 너무 재밌는 경험이였어요! 집사님들도 너무 잘생기고 친절하고 예의있게대해주셔서 정말 아가씨가된기분이였어요!! 처음에는 적응못했는데 끝날때쯤에는 너무아쉬웠어요ㅜㅜ 다들 얘기도잘해주시고 이쁘다고 계속얘기해주셔서 자신감뿜뿜하고나왔습니다!!', 113, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '안녕하세요 대저택에 계신분중에 레이,시엘, 여자분도 우리를 좋게 밨나봐요 우리도재미있었고 좋았어요 다음에 또 가고싶네요 ㅎㅎ~💗💗', 23, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '세번째 귀가!!! 여전히 집사님들의 외모는 출중하셧답니다! 새로 본 얼굴들도 여러분 계셧는데 진짜 멋잇으셧어요! 그림도 그려주셔서 너무 즐거웠습니다! 늘 1시간 동안이라 다음엔 꼭 재력을 충분히 갖춰서 제대로 파티를 즐겨볼려구요 ㅎㅎㅎ 레이집사님 (새로운 분인데 맘에들어서 간택) 미카집사님은 기억해주셔서 너무 감동이엿어요 8ㅁ8 좀 몇개월 뒤 귀가이지만 꼭 다시 귀가할께요🫠🙇‍♀️🙇‍♀️ 너무 황홀햇습니다🙇‍♀️🙇‍♀️😚😚👑🙏 queen이 되고 싶다면 무조건 여기 루치펠 대저택으로 오시길🫠  (속닥)셀카가 잘나와서 좋더라구요 😚😚', 58, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '기대 반 긴장 반으로 방문한 집사 카페🏆 집사님들이 심심하지않게 말도 걸어주셔서 1시간이 후딱 지나갔네요 :) 다음에 또 방문할게요 +디저트 크림브륄레 맛있었어요!', 21, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '친한동생이랑 2시간귀가 인페리스에는 제리.미카.오니.카이엘.레이 집사님이 계셨다 ㅎㅎㅎ 집사님들이 너무 친절하시고 재밌게 놀아주시고 1시간만귀가하다가 2시간은 처음인데  2시간귀가도 괜찮았다 여유로움을 가질수있고 더 재밌는시간도 가질수있고 장시간귀가도 해볼만하다 저는 재밋어서 체키부자만들었어요 ㅎㅎ', 43, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '1년전에 연남갔다가 여긴 처음오는데 기억하고 알아봐주셔서 놀란...심심하지않게 왔다갔다 계속하면서 대화하고 그래서 재밌었습니다!..', 1, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '첫 귀가였고, 집사님들 매우매우 친절하십니다. 극 내성적인 저는 고개를 푹 숙이고 있어서 집사님들 얼굴은 못봤지만 같이 간 친구 말로는 매우 잘생기셨다더군요. 고개 숙이고만 있던 저에게도 친절히 말 걸어주셨습니답!', 65, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '내부 사진도 찍을수 있으면 찍었을텐데 집사님들 얼굴은 소중하니까..✨ 내부도 엄청 예쁘고 집사님들 모두 예쁘고 잘생기셨습니댜.. 🫶🏻 자주 가지만 항상 다들 엄청 친절하시고 말도 많이 걸어주시고 잘해주셔요!💞 혼자 가셔도 집사님들이 잘 챙겨주시고 여러명이 같이 오셔도 재밌게 놀 수 있으니까 인원수 상관없이 강추드려요! 루치펠 짱👍🏻👍🏻', 16, 10, 'GOOD', SYSTIMESTAMP);
