INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '일단 배고팠는데 귀가한 저희를 위해 준비해주신 디저트가 친절하고 집사님들의 잘생긴 외모가 맛잇어서 괜찮아졋어요 디저트 접시도 집사님들이 들어주셔서 찻잔 들기도 힘든 가려린 저희 손목이 안 나갓음 😁😁😁😁😁', 46, 5, 'GOOD', SYSTIMESTAMP);
