INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '집사분들 너무너무 친절하시고 심심하지 않게 말을 자주 걸어주셔서 혼자 가셔도 부담스럽지 않아요!! 정말 만족스러워서 다음에도 꼭 갈 의향이 있습니다!!', 4, 4, 'GOOD', SYSTIMESTAMP);
