INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '역시 가길 잘한거같습니다 너무 좋았어요 인스타로만 보다가 가게되다니......! 친구랑 갔는데 시간가는줄도모르고 즐겼어요 집사님들도 저희쪽 테이블에 한번씩 다 와주신거같기도하고.. 아니면 아닌거죠!! 하.... 다음에 또 와야겠어요 사진찍을때 레오집사님이랑 찍었는데 너무 기분이 좋아열 이걸로 바로 일기를 꾸며보도록 해보겠습니다...❤️', 2, 10, 'GOOD', SYSTIMESTAMP);
