INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '색다른 경험을 하고싶으면 완전 추천! 추천!😍  친구들이랑 다 같이 가면 더 재미있어요!!😆 낯가리고 말수가 적어도 집사님들이🤵‍♂️🤵‍♀️ 먼저 말 걸어주시고 잘 놀아주세요!✨️ 집사님들이 다 너무 예쁘고 잘생기셨어요!🫢💓', 104, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '20분전에 도착하엿는데요! 먼저 쿠로님 집사분이 나오셔서 안으로 들어와서 기다려주세요 러고 친절하게 알려주셔서 2등으로 기다렷다가 귀가했네요! 처음에 진짜 어색해서 ;; 허리를 꼿꼿하게 새우며 얼떨결에 품위를 지키며 지낸것 같아요 ㅋㅋㅋ 심심하지 않게 여러 집사분이 다녀오는게 엄청 느껴졋어요! 2층에서 내려오셔서 말거신 분도 계셔서 놀랐어요 ㅎㅎ 하지만 좋았어요! 디저트는 기대 안했지만 다 맛있어서 좋았어요! 2층에서 내려오신 집사분 이름을 못들어서 아쉽지만 외모가 진짜 화려한 배우상 느낌이라 와 하며 얘기하는걸 들은것 같아요 ! 영상으로만 보던 집사분들을 봐서 행복했습니다>< 레오집사님 엄청 귀여워용!!', 60, 13, 'GOOD', SYSTIMESTAMP);
