INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '궁금증으로 갔는데 입이 즐거운 곳이였어요 디저트가 하나하나 다 먹기 좋고 맛도 있어요 동생이랑 가서 다른것들도 해봤는데 재미가 있네요 정말 기분낼때 가보세요~', 35, 10, 'GOOD', SYSTIMESTAMP);
