INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '방문은 처음인데 재밌더라고요 위치가 길 가다가 누가봐도 여기가 루치펠이다!! 싶을 만큼 눈에 잘 보였고요 저희 전담 집사님이 아마 닉 집사님이셨던 것 같애요 닉 집사님이 가장 많이 오셔서 말 많이 걸어주시고 으아 근데 되게 다정하셨어요 감사합니다 .. 그 다음에 하쿠 집사님 제로 집사님 순으로 많이 오셨던 것 같아요 운 좋게 라이브 쇼도 봤었는데 춤 진짜 잘 추시더라고요 재밌었어요', 3, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '드디어 루치펠 대저택 방문~! 분위기 넘 좋고 사진 찍기도 넘 좋네욯!안에도 넓고 인테리어가 넘 잘 되어 있습니다!2층에 있는 인페리스 로얄도 방문했습니닿ㅎ넘 뵙고 싶었던 저의 최애 집사님들 미카님,아이작님,카이엘님을 만나고 넘 좋아옇ㅎ! 쿠로님,사토님,즈키님도 만나고 새로운 집사님들 하울님,몰리님,워커님,제리님,오니님까지! 만났습니닿ㅎ최애 집사님들이랑 체키(사진)도 찍고 최애 집사님들에게 선물 전달도 성공!최애 집사님들이랑 대화도 많이 하고ㅎㅎ 다른 집사님들이랑도 대화 많이 하고 장난 치고 넘 즐거웠습니다!  집사님들의 싸인도 받고! 우~왕! 넘 바쁘신데 진짜 넘 감사합니다!ㅠㅠ8월 마지막날을 이렇게 집사님들과 함께 해서 넘 즐거웠습니다! 시간 되면 또 갈께요! 꼭 다시 만나옇ㅎ~!', 42, 4, 'GOOD', SYSTIMESTAMP);
