INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '혼자 홍대 놀러갔다가 생각나서 찾아가 봤는데 친절하고 말도 걸어주셔서 덜 어색 했어요~그런데 집사님이 너무 가까이 오시면 고개를 들면서 눈 마주치면서 이야기 하는데 너무 위에 올려다 봐야 되서 조금 자세가 불편했어요 ㅠㅠ 그거 말곤 잘해주셔서 감사합니다^^😍', 74, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '재미있었어요 !!! 쿠로집사 드디어 영접했습니다 몇번실패 후 드디어 뵌다고 하니 대화 엄청걸어주셨어요 ~ 엄청 잘생기셨네요 ṑṑṑ 연남저택만 있었을때보다 재미있었어요~~', 38, 10, 'GOOD', SYSTIMESTAMP);
