INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '즐거웠던 루치펠 대저택🏰🩶 마치 한시간이 10분처럼 지나간듯한 기분이에요🤤 디저트도 맛있고 집사님들이 정말 스윗하고 친절해요ㅜㅜ 빠른 시일 내에 귀가하겠습니다🫶🏻', 1, 1, 'GOOD', SYSTIMESTAMP);
