INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '분위기도 엄청 좋았고 집사님들 착장도 경성 스럽게 입으셔서 멋졌습니다 진짜 옷도 경성 의복 입고 가니까 경성시대에 있었던거 같습니다🩷💙', 76, 12, 'GOOD', SYSTIMESTAMP);
