INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '루치펠 대저택'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '거기 계시던 집사 분들이 너무 착하시고 정말 아가씨 처럼 대접해 줘서 친구들이랑 재밌게 즐길 수 있었어요! 하지만 생각보다 가격이 무섭더라구요.. ㅜ', 22, 5, NULL, SYSTIMESTAMP);
