INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '베이글 샌드위치 맛집인 것 같습니다! 맛도 좋고 넓고 깔끔해서 매장에서 먹기도 너무 좋은 것 같아요~ 건강을 생각한 메뉴들도 있어서 아침에 간단하고 든든하게 먹기 좋은 것 같습니다! 브런치로 굿! 그리고 무엇보다 직원분들이 너무 친절하시고 기분이 좋아지는 매장입니다 ㅎㅎ', 45, 2, 'GOOD', SYSTIMESTAMP);
