INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '칭구들이랑 브런치로 베이글 샌드위치 먹으러 왔어요 풀드포크, 잠봉뵈르, 카프레제 먹었는데 다 넘 맛있네요.. 게다가 건강한 맛!!! 담에도 아침식사하러 올게요🥰 @브런치 @', 75, 12, 'GOOD', SYSTIMESTAMP);
