INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '베어글스 홍대상수점..! 너무 맛있고 청결하고 화장실 깨끗하고 사장님들 친절하시고 대박이에요...! 저는 점심 먹으러 갔는데 아침식사 겸 브런치로도 아주 딱일듯요..! 그리고 음료가 세상에 너무저렴해요... 엄청 예쁜 컵에 담아주시고 최고입니다! 저 맨날 갈거에요!!!', 71, 15, 'GOOD', SYSTIMESTAMP);
