INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '베어글스 홍대상수점입니다. 지난번에 잠봉뵈르 먹어보고 맛있어서 이번엔 카프레제 먹으려고 방문했어요. 아침식사, 브런치로도 좋은 다양한 종류의 베이글 샌드위치 맛집이에요^^', 9, 8, NULL, SYSTIMESTAMP);
