INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '처음 와보는 카페인데 음료가 다양해서 너무 좋아여 커피를 안 마시는데 논커피 종료도 많고 티를 좋아하는데 딸기 애플티 짱맛있어요 ㅎㅎ 베이글 샌드위치도 많이 파는 거 같아수 브런치 먹으러 오거나 아침식사 대용으로 포장해서 가기 좋은 거 같아오!! 포장 박스도 너무 귀엽고 매장도 넓고 의자 짱 편합니다♥️ 상수 주변에 살거나 직장이 있다면 아침식사 드시러 오시거나 브런치 먹으러 오시길 추천 드려용', 26, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '아침식사나 브런치로 좋을 것 같은 베이글 샌드위치를 팔아요. 빵이랑 고기 종류를 선택해 조합해 먹을 수 있어요. 빵도 맛있고 안 내용물도 실해서 맛있습니다.', 41, 5, NULL, SYSTIMESTAMP);
