INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '오랜만에 남자친구랑 데이트 겸  들렀어요. 잠봉뵈르 베이글 샌드위치를 주문했는데, 진짜 너무 맛있어서 놀랐어요. 쫄깃한 베이글에 짭조름한 잠봉, 고소한 버터 조합이 딱 제 스타일! 가볍지만 든든해서 아침식사로도 좋을것같고! 분위기도 아늑해서 브런치 데이트 장소로도 제격일거같아여! 요즘 베이글 샌드위치 맛집 많은데 여긴 다시 오고 싶을 정도로 인상 깊었어요 🥯💛', 23, 3, 'GOOD', SYSTIMESTAMP);
