INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '후레시한 아침! 베이글샌드위치 너무 맛있어요 ㅠㅠ 닭가슴살 하나랑 다른거 하나랑 시켜서 반반 먹는게 딱! 맛있음 아침 일찍오면 사람도 많지 않아서 주말마다 여유롭고 건강한 아침 잘 먹고 갑니다 번창하세요 히히', 36, 5, 'GOOD', SYSTIMESTAMP);
