INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '매번 배달로 베이글이랑 커피 시켜먹다가 근처에 보여서 들어왔는데 갓 내린커피가 더 맛있어요 ㅠ 원래 메가커피만 먹는데 요즘 여기 커피 맛있어서 여기커피만 시켜먹어요! 베이글샌드위치도 점심대용으로 브런치처럼 먹으면 딱 좋아요!', 39, 2, 'GOOD', SYSTIMESTAMP);
