INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '매장도 깨끗하고! 아침식사로 브런치하기 좋은 베이글 샌드위치 종류들 정말다양해용! 아침이나 점심시간에 간단하게 한끼하기 너무 좋은거 같아용~! 매장도 깔끔하고 사진찍기도 좋은거 같아요 컵도 너무 귀엽네요ㅠㅠㅠㅠㅠ😍', 4, 8, 'GOOD', SYSTIMESTAMP);
