INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '전에도 지나가다 들렸었는데 오늘도 지나가다 급 들어와서 베이글샌드위치 포장해서가요! 커피도 맛있어서 브런치먹기 딱 좋습니다!!', 45, 8, 'GOOD', SYSTIMESTAMP);
