INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '자몽 애플티 : 달달 상큼하면서 자몽에 쌉라름한 맛이 느껴지는 당 충전 음료였어요! 아침식사, 브런치로 먹기 좋은 베이글 샌드위치도 판매중이니 방문해 보셔도 좋을것 같아요^^', 11, 0, 'GOOD', SYSTIMESTAMP);
