INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '혼자 간단하게 샌드위치 먹기위해 또 방문 했어요 :) 좋은가격에 간단하게 먹을 수 있어서 넘 좋은 것 같아용 매장도 유니크하게 곰돌이로 꾸며져있어서 귀여운 ! (특히 사장님이 너무 친절하셔요 ❣️)', 72, 13, 'GOOD', SYSTIMESTAMP);
