INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '밖에서 봤을때 가게가 너무 깔끔하고 분위기가 좋아보여서 들어왔는데 정말 맛있고 기분 좋게 먹고 갑니다!! 치아바타가 정말 부드럽고 맛있어요 들어가는 재료들도 엄청 신선하고 완벽하네요!! 가게 분위기도 좋고 음식도 맛있고 사장님도 너무 친절하셔서 기분 좋게 다녀갑니다 베이글 먹어보러 다시 와야겠어요!', 95, 26, 'GOOD', SYSTIMESTAMP);
