INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '베이글이 크고 맛있어요 선물용으로도 샀는데 다들 맛있다고해서 저희도 또 먹으러 왔어요 아침식사나 브런치로 먹으면 딱일꺼같아요:)', 1, 6, 'GOOD', SYSTIMESTAMP);
