INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '아침에 오는 곳입니다. 매장도 청결하고 친절합니다. 메뉴도 다양하고 베이글, 커피 맛있습니다. 혼자서도 조용히 식사하기 좋습니다.', 24, 3, 'GOOD', SYSTIMESTAMP);
