INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '베이글 시켰는데 따뜻하고 깔끔하게 나와서 좋아요 나중에 아침식사나 브런치로 먹기도 좋겠어요 베이글 샌드위치 종류도 많더라고요 담엔 그걸로 도전해보려고요', 105, 25, 'GOOD', SYSTIMESTAMP);
