INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '휴일 낮에 와이프랑 오랜만에 브런치 데이트로 들렀는데 베이글 샌드위치 진짜 미쳤네요. 겉은 바삭하고 속은 쫀쫀하고 부드러워요.. 입에 베는 맛도, 분위기도 아침식사로 딱 좋았어요. 커피랑 같이 먹으니까 브런치 데이트 느낌 제대로 나더라구요. 데이트 코스로 추천하고 싶을 만큼 만족도 높았고, 재방문 각입니다.', 10, 5, 'GOOD', SYSTIMESTAMP);
