INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '브레이크 타임이 없어서 어중간한 시간에 방문했는데 혼자 먹기에 좋습니다. 베이글은 통밀로 변경 가능하고, 가성비가 아주 좋아요. 반드시 음료를 주문하지 않아도 괜찮습니다. 베이글 샌드위치만 주문했는데 센스있게 리유저블 컵에 물을 챙겨주셔서 기분 좋게 식사했습니다. 매장도 청결하고 친절하시고, 맛있습니다. 재방문 의사 있습니다.', 7, 10, 'GOOD', SYSTIMESTAMP);
