INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '빵땡기는날 점심에 여유롭게 먹을만한곳 너무좋어용 ㅜㅜ 인테리어도 귀엽고 햇살도 잘들어오고 무엇보더 베이글이랑 커피가 너무 맛있고 궁합이좋아요ㅜ 혼자오기도 좋고 점심약속으로 오기도 좋아요!! 베이글 안에 야채나 재료들 너무 풍성하고 신선해요🤭❤️ 회사근처인데 자주올거같아요 맛있게먹고갑니당', 28, 0, 'GOOD', SYSTIMESTAMP);
