INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '처음 방문 했다가 반하고 갑니다!! 인테리어도 너무 이뻐서 사진도 잘 나오고 베이글샌드위치는 너무 맛있어요💖💖 샐러드도 너무 맛있게 먹고 갑니다🍀 자주 방문할거 같아요🧸', 77, 15, 'GOOD', SYSTIMESTAMP);
