INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '베이글 샌드위치와 곰 캐릭터가 반겨주는 카페 베이글과 곰의 영단어인 "베어"에 착안해 베어글스라고 칭하는 것 같다. 지점이 여러 곳이 있는 듯하나 회사 근처 상수역 근처 커피 마실 곳을 찾다가 상수점이 눈에 띄게 되어 테이크아웃으로 커피를 주문했다. 소금 슈페너 오리지널: 5,500원 아인슈페너에 소금을 얹어 크림의 단맛과 소금의 짠맛이 어우러지는 아인슈페너다. 베어글스의 또 다른 장점은 어느 음료수든 일회용 컵이 아닌 리유저블 컵으로 제공한다는 점이다. 컵 제공에 5,500원이면 가성비가 미치지 않았나 싶다. 추후 베이글 샌드위치도 시도해볼 예정이다.', 101, 25, 'GOOD', SYSTIMESTAMP);
