INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '치아바타랑 베이글 좋아해서 따로 서칭해서 왔는데 맛있습니다 교정해서 딱딱한거 못먹는데 빵도 쫀득하니 재방문 해야겠어요.. 다이어트 하시는 분들 한테도 탄단지 맞추기 좋습니다 :) 사장님도 친절하세요 ㅎㅎ', 91, 24, 'GOOD', SYSTIMESTAMP);
