INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '너어무 맛있어요!! 베이글 쫀득하고 터키랑 닭가슴살 샌드위치 시켰는데 저는 닭가슴살, 남친은 터키가 더 맛있대요 ㅎㅎ 그리고 커피 맛집이에용👏😊', 28, 1, 'GOOD', SYSTIMESTAMP);
