INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '브런치 먹기 좋아요! 원래 베이글 샌드위치 먹으러 왔는데 치아바타 샌드위치가 넘 맛있어보여서 시켰는데 역시 너무 맛있어요..🥹✨ 베이글샌드위치도 궁금해서 포장해가려구용 ㅎㅎㅎ 주변에 일 있어서 들리면 혼밥하기 좋은 곳 발견해서 조아요!!', 49, 7, 'GOOD', SYSTIMESTAMP);
