INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '새로생긴 신상카페! 내부 넓고 디자인 깔끔하고 무엇보다 커피맛과 베이글 맛이 훌륭해요! 💐 🍞 🥯 🙏 잠봉베이긍 꼭드세요 버터랑 베이컨 양 무슨일 ㅠㅠㅠ🩷🩷 가격도 저렴한데 커피맛도 고퀄리티에 특히 데이트로 티타임 또는 브런치하러 오면 좋을듯해요!🩷❤️ 분위기도 좋고 여유롭고 ㅎㅎ 사장님도 넘넘 친절하세요!! 앞으로 홍대올때 카페 여기만 들리려구요! ☕️ 번창하세요💞💞 #브런치 #베이글샌드위치 #혼밥 #데이트 #내돈내산', 44, 10, 'GOOD', SYSTIMESTAMP);
