INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '아침에 오는 곳인데 아침으로 혼밥으로도 먹기 좋습니다. 매장도 깨끗하고 친절해요. 커피랑 샌드위치 맛있고 베이클도 쫀득 맛있어요~ 브런치로 커피랑베이클 추천이요~', 36, 7, 'GOOD', SYSTIMESTAMP);
