INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '상수 근처에 간단히 혼밥할 곳을 찾다가 발견!! 브런치로 베이글 샌드위치 하나 냠했음동~~ 집 근처라 좋고 넓어서 혼밥해도 눈치 안 보여요! 일단 맛은 보장되었으니…… 👍🏻👍🏻', 34, 2, 'GOOD', SYSTIMESTAMP);
