INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '요즘 베이글에 빠져서 베이글집이면 무조건 들어오고보는데 여기 넘 괜찮아여!!! 매장 분위기도 혼자 베이글 먹기 넘 편하고 좋고 일단 사장님이 진짜진짜 친절해여ㅎㅎ 크림치즈도 서비스로 받았어요 뭣보다 베이글 진짜 맛있어요! 잠봉뵈르 샌드위치로 시켰는데 느끼한 맛 없이 담백하고 넘 좋아요 잘 시킨 것 같아용 아메리카노는 산미 약간 있는 원두 쓰시는 것 같아요 베이글이랑 잘 어울림~~~~ 초코베이글 궁금해서 시켰는데 베이글 반죽이 쫀득해서 좋아요. 같이 주신 크림치즈 찍먹하니까 더 조아욤. 크림치즈 별로 안 좋아하는 편인데도 잘 먹었어요! 초코베이글 진짜 추천이욤ㅎㅎ', 83, 15, 'GOOD', SYSTIMESTAMP);
