INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '상수역 혼밥하기 좋은 브런치 카페 발견! 🥯☕️ 빵순이들이 진짜 좋아할만한 쫄깃한 베이글 샌드위치에 치아바타 샌드위치까지..! 샌드위치안에 크림치즈가 아낌없이 들어가있어서 진짜 맛있어요! ㅠ🥯🥯 아침에 먹다가 너무 맛있어서 점심에도 먹을려고 베이글 사왔는데 따로 안데워 먹어도 엄청 쫄깃하면서 안에 촉촉하더라구요. 존맛!! 🥯🥯 커피주문하니까 리유저블컵에 주셔서 회사에서 요긴하게 쓰일것 같아요! !☕️ 완전 빵순이들은 꼭 방문해보세요! 👍🏻👍🏻', 23, 8, 'GOOD', SYSTIMESTAMP);
