INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '집 앞이라 계속 가야지 생각해보다가 첫방문 해보았는데 크리스마스 선물로 러스크도 서비스로 주셨습니다 ㅎㅎ 혼자 밥 먹기에 너무 좋고! 분위기도 편안하고 아늑해요 ❤ 사장님도 넘 넘 친절하십니다! 상수주민들 베어글스로 오세용 🐻 재방문 의사 백프로 🫶🏻', 6, 4, 'GOOD', SYSTIMESTAMP);
