INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '합정에 은근히 브런치 베이글맛집이 없는데 동시에 해결!!! 인테리어도 귀엽고 베이글샌드위치로 커피랑 함께 든든히 혼밥하기도 좋은 베어글스 !!! 샌드위치 특히 안에 토핑 엄청나게 많이 넣어줘서 진짜 배부르고 맛있어요!!!!!', 34, 1, 'GOOD', SYSTIMESTAMP);
