INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '벌써 세 번째 방문인데 처음 방문했을 때는 베이글을 못 시켜봐서 이번에 시켜봐요! 베이글 러스크가 정말 맛있고 크림치즈는 전반적으로 꾸덕하고 달달합니다! 초코칩이 들어간 말차 크림치즈도 독특하고, 콘 크림치즈도 플레인도 맛있지만 개인적으로는 넛츠 크림치즈가 제일 맛있는 것 같아요☺️ 매장 내부 쾌적하고 화장실도 엄청 깨끗해서 지칠 때 와서 간식 먹고 체력 충전하고 가기 좋은데, 샐러드도 팔아서 브런치 간편하게 먹고 싶을 때 오기에도 좋을 거 같구요! 무엇보다도 직원분들 모두 친절하셔서 좋습니다✨ 다음에 또 올게요!', 57, 15, 'GOOD', SYSTIMESTAMP);
