INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '5번 넘게 가봤는데 리뷰는 처음 써보네요 커피는 말할것도 없고 베이글도 너무 맛있어요! 사진도 너무 잘 나오는 분의기에요~요즘 날씨가 너무 추워서 테이크아웃하면 뜨거운 커피가 식는데 따뜻하게 포장해주신다고 신경써주시는 모습도 갬동이었어여💕 전 가까워서 포장은 사양했슴다 ^^', 19, 10, 'GOOD', SYSTIMESTAMP);
