INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '선물할 베이글 샌드위치 구매 하려고 들렀습니다! 베이글들이 다 너무 예쁘고 맛있어 보여요 테이블도 넉넉하게 있어서 혼밥 하기도 좋아 보입니다 !!', 19, 10, 'GOOD', SYSTIMESTAMP);
