INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '인테리어가 너무 귀여워서 포장 기다리는데도기분이 좋아졌어요☺️ 샌드위치 만드시는 모습이 보이니까 더 신뢰가는 느낌! 주방도 엄청 깔끔했어요🥹 야채들이 싱싱해서 아삭하니 좋았고, 고기도 엄청 듬뿍 들어있었어요! 무엇보다 베이글이 질기지 않았던게 최고..👍 너무 잘 먹었습니다!', 47, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '잠봉베이글샌드위치 포장해왔는데 넘 맛있어요🙂👍🏻 이 가격에 이 퀄리티라니 만족합니다! 음료컵도 리유저블이라 또 쓸수 있어 좋고 포장지까지도 다 귀여워요 상수에서 샌디치 먹고 싶을 때 종종 들를 것 같아요', 5, 5, 'GOOD', SYSTIMESTAMP);
