INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '화사 근처에 베이글집이 생겨서 눈여겨 보다가 이제야 와봤는데 너무 맛있어요!!! 그릇도 예쁘고 매장도 넓고 깔끔한데 베이글도 너무 맛있어요…!💖 같이 나오는 리유저블컵도 너무 귀여워요!!! 근처에서 간단하지만 맛있는 한 끼 찾는 다면 추천해요!!!', 172, 54, 'GOOD', SYSTIMESTAMP);
