INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '홍대오면 오는 카페에용 리유저블컵에 주시는데 너무 좋구요 일단 커피가 넘나 맛나요 제가 천장만 찍은 이유는 사람이 너무 많아요^^ 아마베이글이너무 맛있어서? 저는 아직 못 먹어봤는데 도전해야겠어요 요기 사장님 진짜 친절!', 59, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '집근처 싱수역에 베이글 맛집이 생겨서 좋아요  ㅎㅎ 매장에서 혼밥하기에도 좋고, 사장님이 친절하셔서 기분좋은  매장이었습니다 ^  동네 단골 될듯 ㅎㅎㅎ', 0, 9, 'GOOD', SYSTIMESTAMP);
