INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '브런치하러 왔어요. 여기 샐러드가 맛있단 얘기 들어서 샌드위치랑 샐러드 먹으러 왔는데 깔끔하고 맛있네요 ! 매장도 크고 깨끗하고 편하게 먹기 좋아요 #브런치 #베이글샌드위치 #혼밥', 54, 14, 'GOOD', SYSTIMESTAMP);
