INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '베이글 샌드위치 먹었는데 진짜 치즈 사르르 녹고 너무 맛있어요🥹🥹💕 혼밥할 곳 찾다가 너무 마싯서 보여서 밤에 홀린듯 들어갔는데 담에는 브런치로 와야겟어요…❤️', 40, 10, 'GOOD', SYSTIMESTAMP);
