INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어글스 홍대상수'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '여의도에서 즐겨먹었던 베어글 이제 상수에서도 만나볼 수 있다니 반가운 마음으로 집에가는 길에 포장했어요! 매장도 넓고 직원분들도 친절하세요!!', 55, 11, 'GOOD', SYSTIMESTAMP);
