INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '인테리어가 재밋고 메뉴가 좋았어요! 매장이 리뉴얼 되고 쾌적하고 좋은데 매장 밖이랑 너무 뚫려있어서 조금 부담스러워졌어요(주말 사람 많을 때는… 예약도 어렵겠지만 못… 못갈 것 같아요)', 11, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '우연히 아는데 당일 예약할수 없어서 다음 날엔 바로 예약했어요!! 직원도 친절하게 소개 해 주셔서 감사합니다! 음료랑 음식 다 맛있다!', 0, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '일러가 멋져서 눈길을 확 사로잡았어요. 저 구름 소다 진짜 달달하니 맛탱구리. 쿠키의 그림들도 따로 떼서 냉장고에 보관했네요. 작품이 말못하게 수작이라 직접 보시길 강추!', 45, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '진짜 예약하기 너무 어려웠음요. 그래서 자리 나자마자 바로 예약했어요 메뉴 다 무난무난하니 맛있었어요. 기회가 된다면 꼭 다시 방문하고 싶어요 ㅠㅠ', 35, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '혹시 몰라 네이버에서 검색해서 내용 이해하구 방문했어요. 역쉬 오메가 너무 좋은 장르!!! 디저트 너무 맛있네요. 첨엔 다들 지정한 음료먹더라구요. 난 몰라요 해서 [메론소다, 고양이 케이크] 주문해서 먹었네요. 이것도 은근 맛있어요. 매장이 워낙 따수워서 차가운 음료 시켜먹어도 찬성!!  키링도 구입했는데 너무 괜찮아서 바로 구입해서 가방에 달구 다녔네요. 이번엔 소원 이루었으니깐 다음 소식에도 달려갈려구요~ 정말 너무나 좋았어요. 너무', 70, 16, 'GOOD', SYSTIMESTAMP);
