INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '안녕하세요  모펀홍대 관계자분들 예쁜콜카 열어주셔서감사합니다. 음식도맛있고..직원분들도 친절하시고.. 좋아하는..작품중 하나인데 예쁘게열어주셔서감사합니다. 또방문할예정입니다..', 101, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '딸기철에 생딸기 안쓰는 딸기 케이크 첨봐요; 단가절감 미쳤음; 케이크는 여전히 크림 하나도 해동 안되가지고 완전 딱딱합니다~ 그나마 다른 콜카중에 맛은 챙겼었는데ㅠ 이제 걍 다른 콜카나 모펀이나 똑같네요;', 6, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '재미있게 봤고 또 보고 있는 작품이라 지나는 길에 우연히 발견해서 홀린 듯이 들어갔어요. 모형제의 예쁜 웨딩 일러스트에 감탄하고 군생활 디피에 빵터졌네요. 즐거운 시간이었습니다. 초코케이크도 달달하니 맛있었어요. 쌉싸름한 커피랑 잘 어울렸습니다.', 114, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '4주애인 단행본구매하고 완전 팬이되어버렸음. 그 작품을 콜라보한 카페인데 어케 안가냐구. 디피도 너무 귀엽고 다른 작품들도 모두 주옥이고~♡ 훈남들한테 둘러쌓여 프렌치토스트를 쓸어버리고~♡ 너무 즐거운 시간이었음. 담달 재방문 예정', 124, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '귀찮아서 안남기려다 쓰기~~ 모카케이크 쿠폰을 주면서 그대로 주세요~ 했는데 털실 케이크가 나옴 > 어차피 먹으려고 했고 가격도 같으니 걍 그러려니하고 가져와서 먹었는데 해동이 덜된건지 안된건지 안에 라즈베리? 암튼 그부분이 완전 셔벗이였음 이럴 줄 알았으면 걍 정정할것을 후회ㅠ', 54, 15, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '가격에 비해 맛이 없어요. 그래도 귤차는 마실만 했습니다. 가격도 슬쩍 인상했던데 그만큼 서비스가 좋았으면 좋겠네요.. 음식 퀄리티는 오를 생각도 안하니 좀... 예약기간내 구매 못하는거면 사람 한명 나와서 예약자만 이용 가능하다 안내 좀 합시다~ 매번 손님들 사고싶은거 다 집어와서 줄 서서 기다리고 나면 카운터에서 안돼요. 예약자만 가능해요. 이게 뭐예요.. 친절하라고 안합니다. 안내 좀 하고 소리 지르지 좀 말아주세요.', 93, 20, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '매장은 너무 예뻐요 너무 예쁜데 커피를 못마시는데 탄산이나 음료수가 있었으면 좋겠어요ㅠㅠ (디저트가 초코케이크, 샌드위치인데 핫초코랑 먹기 좀..) 처음 방문하는거라 직원분께 물어봤는데 친절하셨으면 좋겠어요.. 친구랑 저랑 민망했어요..', 40, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '좋아하는 웹툰인데♡ 모펀에서 콜라보해서 넘 좋았습니다♡ 빌헬름과 라인하르트 보고와서 넘 좋았고♡ 커피와 음식도 넘 맛있었어요♡ 직원분들도 넘 친절하고 좋았습니다♡ 행복한 시간 보내게해주셔서 감사합니당♡♡', 36, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '아포카토와 오믈렛.. 오믈렛은 메뉴판보다 빈약했지만.. 케첩으로 그려준 고양이가 너무 귀여워서 맛있게 잘 먹었습니다! 아포카토도 달고 맛있어요!', 0, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '재미있게 보는 만화 [전  남편의 미친개를 길들였다]의 콜라보 카페 방문. 콜라보에 맞게 메뉴가 구성되어 있어 마음에 드는 음료와 디저트를 골라서 구매하고, 콜라보 MD도 구매가능. 나는 간단히 쿠키를 구매했고, 마스킹테이프 덕후라 마스킹테이프와 에코백에 달 캔뱃지도 구입.', 54, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '루덴정식 퀄리티 좋다는 소리는 들었는데 음료도 그렇고 식음료 퀄리티에 넘 만족했습니다:) 굿즈나 덕질용으로는 대만족인데 식음료 퀄리티까지 좋아하서 넘넘 기분 좋아지는 하루였습니다! 직원 분들도 친절하고 구성도 알차가 많이 버세요🥹❤️❤️', 13, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '너무이쁘고🩷이스랑 루비를 가까이서볼수있어서 너무좋았다ㅎㅎ❤ 카페도 이쁘고 음식도 맛있고 만족ㅎㅎ 직원분들도 친절하고(ฅ’ω’ฅ)♥ㅎㅎ기분좋은 하루였다(๑・ω-)～♥”', 18, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '아들 게임하고 싶다해서 근처 게임기가 있는 가게에 보내고 딸이랑 기다리며 시간 보내고 왔어요^^ 여기 직원분들 하나같이 모두 친절하셔서 입장하면서부터 기분이 참 좋았네요^^ 인테리어가 만화 작품들인지라 구경하는 재미도 있고요. 담소 나누기도 좋았네요^^ 아이스뱅쇼는 처음인데 시원하니 맛있었어요🥰😍', 27, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '남편내편 콜라보를 위해 예약 방문했습니다~ 음식은 솔직히 전혀 기대를 안 하고 갔는데 양은 적지만 맛은 대체로 꽤 있는 편이었어요ㅎㅎ 직원들도 친절하고 음식도 빨리 나와서 편하게 즐기다 갑니다~~', 34, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), 'This was visually beautiful! I loved the display posters and wished they were postcards or photocards, but I’m happy I was able to take photos of them. Seeing Iske look different is so 😍😍😍', 20, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '콜라보 한정 특별메뉴인 육전과 매실차 세트가 맛있어요. 단점은 조금 늦게 나온다는거... 육전도 질기지 않고 맛있고 매실차도 적당히 달달 시원해서 한끼 식사로도 손색없습니다. 저는 금동이에 빠져버려서 미니픽 예약하고 왔습니다.', 12, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '진짜 직원인지 알바인지 성격 대박이고요 펑 뚫린 곳이고 앉아있음 동물원 원숭이가 된 기분입니다^^ 바쁘나 안 바쁘나 성격 대박이고 음식도 너무 느리게 나오고 계산도 오래 걸려요 특전 잘못 주고 확인해달라 하면 표정이 너무 대박입니다^^ 외국인들한테 막 하고 짜증 나는 건 알겠는데 님들 월급 우리 주머니에서 나옵니다', 36, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '모펀 AK플라자점 전미길 콜라보카페 인테리어도 좋았고 음식도 그냥저냥 먹을만 했어요 다만 카페 위치가 뻥 뚫려있어서 내향인분들은 혼자 가는거 비추 저는 재밌었어요', 93, 26, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '여기 홍대 모펀 직원들은 왜이리 불친절하고 사람기분나쁘게 고객이랑 싸우나요? 2시간걸려서 홍대모펀 힘들게 가는데 정말 정떨어지네요 제가 돈쓰고 굿즈구매한 영수증으로 포카를 받는건데 왜 물 묻은손으로 주시면서 교환은 안해주세요? 당연히 교환해주셔야죠 포카도 굿즈고 종이인데. . 그렇게 힘든일이여서 교환 안 하고 고객이랑 왜 기싸움하세요? 왜 사람 면전에 대고 비웃으세요??? 저보고 흥분하지마시고요 손님 ㅋㅋㅋ 이러고 웃으셨잖아요 계속 웃으시던데 제가 그냥웃는거랑 비웃는거 구별을 못할까요? 너무 기분 나쁘고 선 넘셨구요 면전에 대고 처웃는건 어디서 쳐배운건가요 님 부모가 그렇게 가르쳤어요?', 48, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '좋아하는 작품의 콜라보 카페라서 방문 했습니다. 직원분들 다 친절하시고 메뉴도 괜찮았습니다. 다만 포스기가 한대정도 더 있었으면 좋겠네요.', 32, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '셔플 유닛별 특징을 담은 콜라보 메뉴가 다양해서 재미있었어요. 생각보다 무난했던 미트 파이는 시럽을 안 묻히고 먹을 수 있었으면 좋았을 것 같고 아이스크림은 베이스인 바닐라 아이스크림 위에 메론 시럽을 뿌려서 메로나 맛이었어요. 아이스크림 자체는 맛있었습니다. 다만 녹차라떼는 에투제 의리로 마셨어요. 맛없다는 뜻 ㅜ 매장 내에서 판매하는 굿즈랑 전시된 셔플 포스터 구경하니 시간이 엄청 잘 갔습니다.', 57, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '일행 한명을 중간에 만나게되서 잠시 옆에 앉게했는데 3명이 아니라 2명자리 예약했다고 득달같이 쫓아와서 자리 옮기라길래 걍 먹다말고 나왔어요ㅋㅋㅋ 이젠 예약한 사람도 개꼽주네요 아니 사람이 없는거 확인하고 저희 옆에 잠깐 앉게한건데도 그zr을 하는건 좀 아니지않나요?', 48, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '세 번째 방문이었어요. 미트파이는 처음에 갔을 때 스테이크 맛이었나 그랬던 것 같은데 비프칠리? 아무튼 바뀐 맛이 조금 더 취향이었습니다. 에이드 안에 든 젤리는 못 먹었지만 적당히 달고 맛있었어요.', 4, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '모펀 AK점 콜라보 메뉴 육전,오믈렛,방울떡 모두 시켜먹었습니다. 어떻게 다 맛있지ㅠ 다른 메뉴 모두 빠르게 나오는데 육전만 엄청 느리게 나왔던 것 같고 30분 넘게 기다렸어요. 귀야곡 예쁜 사진 정말 많고 아름답니다~근데 조명 때문에 예쁘게 찍을 수 없어서 좀 아쉬웠어요. (무광 액자로 바꿔주시면 안될까요?ㅠ', 21, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '손님들은 매번 업데이트되는 공지사항 확인하게하면서 직원들은 확인안하나봐요? 아니 매번 콜라보때마다 어떨때는 굿즈 갯수 제한하고 어떨때는 안하는데 그거 다 확인하고가면 뭐합니까 카운터에 가져가니 다시 확인해보겠다는 말도 없이 일단 장바구니에서 빼시던데 그건 어디서 배워먹은 싸가지이신지? 그래놓고 제가 갯수제한 못봤다하니 그제서야 확인하시던데ㅋㅋㅋ 아주 가지가지들 하십니다요~ 네 님들은 아주 상전이시고 손님들은 빨리 돈쓰고 나가라이거잖아요 아주 꼴깝이란말이 저절로 나옵니다. 사람도 없는데 비예약자는 주문도 바로 못해~ 사람 아무도 없는데도 예약석에 앉으면 바로 쫓아내~ 아니 사람이 있으면 몰라도 곧 마감에다 아무도 없는데 그러시는건 진짜 웃겨요... 팔아주면 뭐해요 예약안하면 바로 천민되는데', 28, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '콜라보카페들 시간이 지날수록 여러가지로 까다로워지네요. 일행이 오죽했으면 종이 몇장주면서 그러냐고 말할정도. 아니 메뉴도 먹고가는거 인당 2개씩 시키고 쿠폰도 받고 굿즈도 많이 샀는데 따로 계산해서 영수증 하나 더 받는건 못한데요. 그래서 제거 하나 일행거 하나 이렇게 따로 계산했어요. 특전 전체 2세트만큼 담아왔는데도 하도 독자들이 돈잘써줘서 손님으로도 안보이나봐요. 그리고 평일 저녁에 아무도 없거나 한두팀 있는데 예약석에 앉지 못하게 하는건 왜인지 궁금해요. 오픈30분 뒤에 갔고 아예 사람이 없는데 앉지말라고 꼽주시던데 참... 사람이 어떻게 갈때마다 예약시간 맞춰서 가겠나요. 비예약자 취급이 뭐같아서 가기싫어요. 주문 받는것도 사람이 아예 없는데도 비예약자는 굳이굳이 30분뒤에 받는 이유는 뭔지..', 66, 18, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '마지막 타임에 갔어요!! 항상 느끼지만 모펀 음료랑 음식도 맛있고 직원 분들도 친절해요 제가 좋아하는 커플 코스터가 한번에 나와서 진짜 행복했어요🥰 특히 의자가 있어 편하게 쉴수있어서 최고예요.', 17, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '예약 없이 가서 포장 주문했어요. 비예약자는 예약 시간 30분 지나서 주문 가능해서 대기줄에 잠깐 섰는데 포장 자체는 엄청 빠르게 이루어져서 오래 기다리지는 않았습니다. (평일 기준)', 16, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '정말 좋아하는 작품의 컨셉으로 구석구석 알차게 꾸며진 공간이 실재한다는 게 너무 기분 좋았어요. 어디로 눈을 돌려도 재신이랑 녹이랑 금동이(🥰)가 포착되니까요! 각종 굿즈 디피도 정성 들여 예쁘게 해놓으셨더라고요. 처음 가보아서 어리버리 헤매기도 했는데, 직원 분들께서 친절하게 안내해주셔서 감사했습니다.', 13, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '파판14 콜라보 1차기간 메뉴 후기! 햄버거-모스버거 하위호환 복숭아케이크-달아서 그 다음 마시는 음료의 단맛이 사라짐 카레&난-난 1장으로는 카레 다 못 먹어서 햄버거 먹을 때 같이 먹거나 햇반 하나 챙겨오고 싶...◐◐ 행복당근주스-라고 쓰고 오렌지사과주스라고 읽습니다. *텀블러 담아가기 좋은 음료 = 행복당근주스, 명계라떼, 별바다라떼, 블루베리티, 아메리카노, 티타임세트 *텀블러 담을 때 조심해야하는 음료 = 레몬에이드, 창천에이드 (탄산없이 시럽만 달라고 하면 터지지않아요.)', 55, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '애니메이트에 갈 일 있으면 bl 관련 상품이 있나 확인하려 항상 들르는데, 거의 매번 만족스러운 물건들 사서 좋았습니다ㅎㅎ 이번에도 좋았어요😆', 20, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '예약후방문 힘들게예약한보람이있었네요 본인명의로 꼭예약하셔야함 (네이버화면스크롤하고 + 신분증검사 진짜함) 띠부씰때문에 최대한 많이4개시켰는데 배부르네요 지인분꺼까지합쳐서7개정도 원하는띠부씰은안나왔지만 ㅠㅠ 5만원특전도원하는거안나옴ㅜㅜ(랜덤싫어) 콜라보카페치고 괜찮은편이라 맛나게먹었습니다 미트파이 매콤한걸로바꼈는데 맵찔이인데 괜찮았어요 다만 그소스가좀ㅜㅜ 별로라따로주시거나빼줌좋겠는데안되겠죠ㅜㅜ 더가고싶은데 빈자리가안나와요ㅜ 콜라보카페 기간더늘어나거나 테이블이 좀 많았으면좋겠습니다 1시간반동안 맛있게먹고즐겼네요 단점은오픈형카페라 지나가는사람이 쭝얼거리거나 사진찍으면서 쳐다봄ㅜㅜ', 12, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '콜라보카페 마지막날 방문했는데 넘 좋았어요~ 긴죠님 싸인회 못가서 아쉬웠지만 그래도 우연이랑 인섭씨 많이 볼 수 있어서 즐거웠습니다 :)', 2, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '귀야곡 콜카 열린지 한달이 다되어가는데도 우왕좌왕 갈때마다 예약따로 주문따로 받던지 이랬다가 저랬다가 직원들은 고갹한테 예의는 좀 지켜주세요 상전이여', 31, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '미필적 고의에 인한 연애사 콜라보 카페 방문을 위해 예약 후 왔다! 예약이 너무너무너무 힘들었지만.. 좋아하는 작품의 인기가 그만큼 엄청나다는 거겠죠..🥹? 모펀에는 여러차례 방문하였지만, 이번에는 콜라보 메뉴의 음료가 모두 커피류(카페인 포함)라 카페인을 마시지 못하는 나로써는 너무 아쉬운 맘이었다. 음료 구매 특전 코스터를 받으려면 콜라보 메뉴를 주문해야하는데, 나같은 사람은 어떡하라는 것인지.. 직원분께서 함께 아쉬워해주시고 카페임 함량이 적은 메뉴를 추천해주셔서 감사한 마음이 가득했지만, 근본적인 해결이 되어주진 못해서 해당 콜라보 작품 기획측에 대한 아쉬움이 더욱 커졌을 뿐.. 결국 저는 일반 메뉴를 주문하고 코스터는 받지 못했습니다..🥲 다음번엔 해당 부분이 고려가 되었으면 좋겠네요.', 6, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '특전이 없어서 많이 아쉬웠는데 기념으로 와봤는데 친구들하고 이야기도 하고 나름 재밌게 보냈어요! 미트(칠리)파이 시럽이 별로라고 하는 분들 많던데 미트파이는 식사용인데 시럽이 달아서 안 어울리는거라 시럽 많이만 안 묻히면 나쁘지 않아요', 64, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '친구따라서 왔는데 망고스무디가 맛있네요ㅎㅎㅎ 재밌습니다!! 린네? 라는 캐릭터를 좋아하는 친구 덕분에 좋은 경험합니다~*^^*', 25, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '그림도 너무 귀엽고 디저트도 진짜 너무 귀엽고 맛도 너무 너무 맛있어서 만약 다시한다면 또 가고싶을정도로 너무 디저트가 맛있었고 굿즈도 넘나 귀여웠지만 아쉬운점이 있다면 랜덤이 많고 굿즈 종류가 많지가 않아서 그게 조금 아쉬워서 다음에 또 한다면 굿즈종류하고 디저트종류도 더 늘려 주면 너무 좋을것같아요!!!', 34, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '진짜 진행 최악. 이따위로 언제까지 할거에요 나아지는게 있어야하잖아요. 뭐든 느리고 정확하지 않음. 메뉴 누락에 잘못된 메뉴. 한시간반 이용시간중에 한시간을 메뉴기다림', 410, 62, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '항상 이용하구 한...1n번째 이용하는거 같은데 증말 재밌고, 다양한 콜라보를 해서 즐거워용...>_< 제가 파는 장르 다 콜라보해주세용', 3, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '안내/공지가 너무 미흡해요 대기표를 뽑아야하는 날이 있고 안뽑아도 되는 날이 있는데 인원이 몰릴때고 있고 안몰릴 때도 있으니 이해합니다. 하지만 대기 등록이 필요한 날은 등록이 필요하다고 공지가 되어야 사람들이 알고 등록을 하지 않을까요?이걸 알려주는 공지가 그 어디에도 없어요. 그래서 매 타임마다 몇십분씩 헛기다림을 하는 사람이 속출되는데 개선되질 않아요. 그 외에도 예약자 대기자/테이크아웃 대기자/굿즈구매 대기줄 다들 다른 목적으로 줄을 서는데 이것 역시 안내가 없어서 매번 예약자가 테이크아웃 대기 줄에 서서 한참을 기다려요. 앙스타 콜라보 할때마다 오고있지만 이런부분이 너무 아쉬워요ㅠ 개선되면 좋겠습니다', 97, 26, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '역시 오타쿠가 제일 행복합니다 후후 직원분들도 친절했고 음식은 쏘쏘였지만 그래도 비주얼 퀄리티가 좋았어요😆😆 오래오래 앙스타와 함께해주시길', 82, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '직원분들도 친절하시고 예약 확인 및 안내 체계가 철저하고 분업이 잘 되어 있으셔서 대기 거의 없이 신속하게 입장할 수 있었습니다! 디저트 퀄리티도 좋습니다. 재밌었어요. 좋은 추억이 되었습니다.', 12, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '좋아하는 작품 콜라보가 열려서 방문했습니다! 이번 메뉴들은 캐릭터들이랑 너무 찰떡이고 존맛이네요🫶 그리고 굿즈들… 너무 찰떡이니까 다들 얼른 방문하셔요😇 그런데.. 사제기해서 플미로 팔아먹으려는 외국인들은 너무 심하네요; 포토카드 증정 인증도 사진 돌려쓰면서 받아가고 직원분들 고생이 많으십니다ㅠ', 71, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '잘 놀다가용 >< 포스터 번짝반짝 엄청 이뻐요~! 쾌적하고 좋은 분위기에서 놀다갑니당 TV영상은 그냥 유튜브 틀어둬서 그런지 화질이 별루라 아쉬웠을지도.. 직원분들도 다 너무 친절했네요.', 32, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '도수풀 콜라보 카페로 방문했어요!! 캔디소다를 넣은 음료 맛이 매우 궁금했는데 음료랑 아이스크림이 적절히 어울려요. 등신대도 크고 이쁨... 음식 하나당 코스터 1개고 쿠키는 2개당 1개입니다. 트위터 공지에서 못본거같아 작성해요.', 26, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '멜로우티+쿠키 세트 후기 안 좋아서 첫방문 때 안 먹었는데 두번째 방문 때 먹었는데 너무 제 취향이더라고요 다음에 또 먹고싶어요😍', 4, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '정말 좋은 추억 많이 쌓고 왔습니다!! 진짜 영영 잊지 못할 것 같아요ㅠㅠ 햄버거가 특히 정말 맛있었고 나갈 때 가게 왼쪽에서 파는 앙스타 굿즈도 너무 상태 좋았습니다', 210, 99, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '파판에 대해서는 잘 모르지만 친구가 좋아해서 와봤었습니다! 메뉴들이 다양하고 엄청 맛있었어요! 파판 관련된 사진 물품들로 꾸며져 있었는데 엄청 예쁘고 신기했네욥!', 66, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '콜라보 메뉴 테마에 신경써서 정한 느낌이 나요. 메뉴가 전반적으로 달아서 달지 않은 음료 종류도 좀 여러가지 있었으면 좋겠어요', 52, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '모펀 서교점 콜라보 이벤트로 처음 가봤는데 직원분들도 모두 친절하시고 매장 분위기도 참 좋았습니다. 덕분에 즐겁고 소중한 추억 쌓고 왔습니다. 꼭 재방문하려고요!', 27, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '어렵게 취소표를 잡아 다녀왔습니다. 중복이 많다고 해서 걱정했는데 한번에 올클 했네요. 음료도 텀블러에 깔끔하게 담아왔어요. 상시운영 에오르제아 카페가 되는 그날까지 화이팅 입니다.', 50, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '힘들게 예약해서 이용했지만 가게 직원분들도 손님 많아서 힘드신거같아서 안타깝네요 주문하면 음식은 빨리 나옵니다 전시공간 옆에서 예약을 받다보니 전시대에 짐 올리고 예약탭 만지는 손님이 계셨는데 검은옷 입은 남자직원이 갑자기 달려와서 전시공간 탕탕치면서 자기 키 반만한 어린손님한테 짐 빼시라고요!! 여기 올리면 안된다고요!! 소리지르는건 무서웠습니다 예약탭 관리하던 직원도 옆에서 같이 합세해서 짐 빼셔야돼요!! 소리치는게 아니라 탭을 잠깐 받아주시던가 올려둔 짐 치우는걸 도와주셨으면 좋았을것같네요.. 손님은 이미 두손에 예약용 탭 들고있으니 손이 없어서 어쩔줄몰라하시던데...... 무서웠던거 빼면 인증샷 찍기좋습니다 계속 노래도 나오고 영상도 나와요', 44, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '현장예약으로 다녀왔는데 사람이 많아서 음료나오는데 조금 걸려요. 바빠서 그런지 직원분들은 서교점이 좀더 친절하신것 같아요 음료맛은 좋았어요😊', 20, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '음료들이 커피가 진짜 너무너무 맛있어요~ 바리스타 분들 최곱니다 ㅜㅜ 크림라떼 너무 맛나니까 꼭 드셔보시구~ 담에 또 들르면 크림라떼 사먹을 예정입니다 //3//', 5, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '최고품질 사실 콜라보 카페라 기대안하고 먹었는데 생각보다 먹을만 해서 완전...식사 그잡채를 했습니다.. 직원분들다 너무친절하시구 친구랑 좋은 추억 남기고 옵니다!!', 26, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '예전에 즐겁게 힐링한 겜이라 친구들과 다녀왔는데 컨셉과 맞게 음식이 있어 좋았습니다 갈때마다 매번 BL작품만 있어 작품을 몰라 아쉬웠는데 이번처럼 다양한 작품을 콜라보하면 좋을 것 같습니다', 29, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '매번 작품컨셉에 맞춰 진행되는 카페라는 점이 재밋고 음료와 디저트 퀄리티도 나날히 높아지는 것 같아 좋습니다! 굿즈수량도 넉넉하게 해주셔서 너무 만족스러웠어요!', 2, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '제가 간 시간에 계산 했던 직원이 진짜 말투가 불친절하고, 불쾌했어요. 인증 받는데 뭐요? 아니꼬운 말투로 굿즈 사셨나요??그럼 내가 안사고 인증 받는줄아나? 내가 거지도 아니고 뭐야 진짜 말투라도 친절했으면 괜찮았는데 진짜 생각할수록 불쾌하네요. 옆에 있던 직원분은 진짜 친절하셨는데..그 직원은 왜 그러나요?서교점 직원분들은 전부 친절해서 좋은 기억으로 남아있는데 여긴 그 직원 때문에 불쾌한 기억만 나게 됐네요. 리뷰 잘 안쓰는데 내가 진짜 억울하고, 불쾌해서 글 쓴다🤬🤬', 16, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), 'Collaborations pop ups in this cafe is always so pretty decorated. Beverages are tasty and not too expensive. Especially counting that they give gift cards for beverages and posts. Workers are kind and explain everything ☺️', 76, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '직원분들께서 줄 정리도 잘해주시고, 안내사항도 명확하게 말씀해주셔서 혼란없이 기다릴 수 있었습니다. 매장도 매우 깨끗하구요, 음식도 빨리 나오는데다가 맛있었습니다. 매우 만족스럽습니다.', 128, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), 'Beautiful cafe with the Ennead theme where they also give photocards about it!! I loved it and the castella cake was delicious 10/10', 10, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '완전 미띤 🥹🥹🥹 예뻐서 죽겠땅🥹🥹🌝🩷🩷🩷🩷🩷🩷 아~~~~ 오늘만 사는 형제 작가님!!!!  이런 슈퍼작품을 만들어 주셔서 감사합니다!!! 그리고 음식도 너무 맛있어서... 핫도그 겉면에 밀가루 반죽이 바삭바삭하고 설탕과 뿌리는 흰 가루도 아주 특히?. 초콜릿 라떼도 맛있고... 쿠키는 그대로 perfect👌👌👌👌👌', 11, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '청룡의 해에 청룡컨셉의 금선영사라니 아주아주 행복한 경험이었습니다! 알바생이 좀 더 친절하면 더 좋았겠지만..25만원 후회없는 소비였습니다🥰', 17, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '이 가게는 정말 소질이 없습니다. 직원이 예의가 없고, 사전에 의사 소통이 잘 된 상황에 대답이 없습니다. 가게의 규칙도 매우 머리가 없고, 고지식합니다. 정말 추천하지 않습니다!앞으로 연합활동은 정말 이 딱딱한 가게는 추천하지 않겠습니다, 정말 쓰레기입니다!', 40, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '대기없이 예약확인후 바로주문. 인증 이벤트도 설명 친절하게 해주심. 커피가 예상외로 맛있어서 놀랐음(콜라보카페들 음식맛은 정말...😓) 카스테라가 너무 퍽퍽한 식감이라 다른메뉴 드시길...😁', 39, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '매번 콜라보마다 새로운 메뉴가 있어서 좋습니다! 예약하고 가면 편하게 머무르고 갈 수 있어서 너무 좋구요~ 다양한 콜라보 이벤트가 있어서 참여하는 재미가 쏠쏠합니다💖', 35, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '샬다제 모펀 콜라보 다녀왔어요! 너무 늦게 알아서 마지막날 다녀왔네요 ㅎㅎ 예약도 했는데 생각보다 사람이 많이 붐비지는 않았네요~ 편하게 구경하구 인증 굿즈도 받아오구 직원분들께 말 걸기도 편해서 좋았어요~ 망고 요거트 스무디랑 딸기 쉬폰케이크 먹었구요 포도 아이스크림은 안된다고하셔서 못먹었네요ㅠ', 48, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '다음에도 콜라보도 모펀에서 했으면 좋겠다는 생각이 들 정도로 매우 만족스러웠습니다. 음식과 음료도 맛있고 매장도 깔끔해서 좋았습니다!', 104, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '처음 콜라보카페를 갔는데 맛도 괜찮고 좋았어요. 직원분께서도 친절하시고 유쾌하셨어요 다만 방문한 날에 사람이 엄청 많아서 노래소리가 잘 들리지 않아 아쉬웠어요.', 88, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '최고예요! 이집트 정식은 근데 맛있는것과 맛이 요상한게 합쳐있는 묘한 음식이네요 하지만 호루스가 준거니까 참고 먹습니다ㅠ 또 갈거예욧...', 22, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), 'ㅎㅎㅎㅎㅎㅎㅎㅎㅎ아 또 가고싶어요 너무너무 재미있었어요 ㅠ 메뉴도 특별하고 그냥 앉아있는내내음흉한미소만띄우고 맛잇는 키위주스 마시면서 사진찍고^^~~^~ 하... 작가님을 못 뵌 게 한이지만 ㅠㅠㅠㅠ담에또열어주세용❤️❤️❤️', 13, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '메뉴도 빨리 나오고 응대도 친절해서 좋았어요. 다만 음식 먹는데 주변에서 날파리가 5-6마리 정도 날아다녀서 당황했어요. 저희 자리만 그랬을 수 있어서 조심스럽네요. 다른건 다 좋았습니다.', 97, 23, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '드림누이 사려고 들렀는데 딱하나 남아서 부랴부랴 구매했습니다!! 엄청 귀엽고 사길 잘했어요 직원분들도 친절하십니다 또 사러 갈게요!!', 11, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '석류 뱅쇼 음료가 맛있어서 겸사 또 왔는데  허브가 마실때 마다 달라져 맛이 변합니다. 로즈마리 허브가 뱅쇼의 느낌을 지워 맛 없습니다 다른 콜라보 카페 보다 음식이나 음료는 확실히 맛있습니다!!', 46, 3, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '굿즈 다 품절라니 울어여 ㅠㅜ 콜라보카페 중에 모펀음료 다양하고 젤  맛있습니다!!!!!!! 쉿! 다른카페 서운하겠지만 팩트(?) 입니다 🫶🏻', 73, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '그냥 내가 좋아하는 작가님 좋아하는 작품이 너무 좋아서 가는거지 모펀 배째라 장사 제발 개선 안하나요? 구멍가게도 아니고 맨날 메뉴 눈탱이에 맛도 없고 굿즈품절이면 주문자 연락도 안주고 트위터 확인하고 다 직접 찾으러 가야하고ㅋㅋ 아니 배송 안해주면 개별연락이라도 해주는게 당연한거 아닌가? sns에 품절 재입고 트윗보고 찾으러오래ㅋㅋ 비엘러들이 호구지 이래도 평 좋게 써주는거보면', 16, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '오늘이 콜라보 마지막 이라니 너무 아쉬웠어요😥 그래도 포토카드랑 엽서, 코스터, 데코픽 다 모았어요😊 디저트랑 음료 다 먹어봤는데요😄 저는 개인적으로 ''<이유한> 솔티드 카라멜 머핀''이 제일 맛있었어요😋 콜라보 상품도 잔뜩 예약하고 왔는데, 빨리 입고 되서 받아보고 싶네요😚 <팬클럽 회장님 J가 의뢰한 토끼 케이크>도 먹어보고 싶었는데.. 용돈을 너무 많이 쓰는 바람에 못먹어 봐서 아쉬워요😂 생일 렌티큘러 포토카드 이쁘던데, 양도해 주실 분을 찾아봐야겠어요!!', 44, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '어릴 때부터 좋아했던 작가님의 작품이라 더 애정 가득해요. 『샬롯에게는 다섯 명의 제자가 있다』는 진짜 믿고 보는 이야기! 아직 안 읽었다면 꼭 한 번 읽어보세요 :)', 5, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '캐릭터가 좋아서 가는거라 서비스랑 맛 떨어지는건 어느 정도 감안하고 가지만 제발 날파리 해결 좀 해주세요…갈 때마다 보는데 나타나기만 하면 몰라 자꾸 음식에 냅다 앉아서 안그래도 호구잡힌 가격으로 산 디저트 자꾸 버리게 되네요;;오늘도 두 마리 잡고 한 마리 놓치고 갑니다^^ 물론 나름 벌레퇴치램프도 있는거 같지만 그럼에도 몇마리씩 계속 나와서 이정도면 음식 위생도 걱정되니 관리 꼭 부탁드려요…다른 가게에서 왔다기엔 같은 날파리를 서교점에서도 봤고, 5층 다른 음식점 각 1번씩 정도 이용해봤는데 그때는 본 적 없습니다', 32, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '허어어어어 우리 샬롯이 드디어 콜라페 카페를....!!! 이곳저곳이 다 샬롯이고 굿즈들도 전부 이뻐서 정말정말정말 좋았습니다!! 직원분들도 다 친절하셨고 음식도 맛있었어요🥰 모펀 카페 최고!!!!!!', 0, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '처음 예약하고 방문했는데 직원들 완전 불친절 재수없어 포장했으면 바로 나가라고 이런행위도 있다는것 대한민국에서 처음 껵는일  계산해서 카드 잊어버리고 안뽑아가도 아무말없이 다른예약자 주문을 하고 참 어이가없네', 93, 20, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '두번째 방문했어요😘 예약은 3번 했었는데, 첫째날은 못갔어요 ㅠㅠ 돈 쓰면 안되는데.. 디저트도 맛있고, 콜라보 상품도 이뻐서 자꾸 돈을 쓰게 되네요😂 엄마가 통장 내역 확인하고는 이제 그만 좀 쓰라고 잔소리를 하시는데 정말 알바를 해야하나 싶었어요😅 작년부터 웹툰 콜라보 카페에 다니기 시작했는데, 그때부터 돈을 왕창 쓰기 시작했습니다... 그래도 기분은 좋았어요🥰 직원분들 다 정말 친절하게 대해 주셔서 넘 감사했고, 좋았어요☺️ 방문 포토카드 다 모을 때까지 계속 방문할 것 같아요🤣 오늘은 코스터 모으려고 학교 끝나고 혼자 방문했는데, 코스터가 처음 방문했을 때랑 똑같이 다 중복으로 나왔지 뭐예요?😥 그래도 엽서는 다 다른걸로 나왔어요..! 디저트는 다 먹고 왔네요🫠', 32, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '샬롯에게는 다섯명의 제자가 있다 콜라보 카페 열려서 다녀왔어요~ 예약제로 운영해서 쾌적하고 디피도 깔끔하게 되있어서 좋았습니다!', 1, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '#페이백 #samk #푸죠킹 #모펀 #콜라보카페 #모펀페이백후기 ak플라자 방문할 때마다 모펀 카페 꼭 가보고 싶었는데, 오늘 드디어 가봤어요😄 우선 매장이 넓고, 직원분들 다 정말 친절하셔서 좋았어요☺️ 인테리어도 멋지고, 디저트도 정말 맛있더라고요🥰 근데 방문 포토카드는 어떻게 받을 수 있나요..? 받고 싶은데 받는 방법을 몰라서 못받았네요😥 다음에 방문할 땐 꼭 받을거에요!! 아 그리고, 등신대 넘 멋있네요😍', 33, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '첫번째는 예약하고 사정이 생겨서 못갔지만.. 두번째 예약하고 갔을 때 좋았어서 리뷰 남겨요~😘 우선 매장이 넓고, 깨끗해서 좋았어요🥰 직원분들이 다 친절하셨고, 모르는거 물어볼때도 친절하게 답변해주셨어요☺️ 디저트 정말 맛있었고, 콜라보 상품도 넘 예뻐요😍 다음에 또 방문할게요~😉', 79, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '너무 가고 싶었던 샬다제 콜라보 카페!!! 너무 좋았습니다!!!  디저트도 다 맛있고, 직원들도 친절해서 좋았어요, 힐링 제대로 하고 왔습니다! 좀더 있고 싶었는데 옆테이블 두여자의 대화가 처음부터 끝까지 욕이라...더듣고싶지않아서 금세 왔네요^^;;', 426, 58, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '메뉴 불호후기가 많았지만 저는 그래도 무난하게 잘 마셨고 케이크 디저트류 노리시는분들은 되도록이면 낮에 가는게 좋을거같아요~!! 저녁대엔 쿠키밖에없고 품절이라서 그거밖에 못먹고왔네요ㅠㅠ 인테리어도 작게 액자형식으로 잘꾸며져있어서 둘러보는 재미가있었습니다', 72, 11, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '좋아하는 작품의 콜라보 소식에 첫 방문! 나는 카페인을 마시지 못해서, 이번 이벤트의 특별 메뉴가 카페인이 함유된 토피넛 라떼라 너무 아쉬웠다..ㅠ.ㅠ', 62, 11, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '이벤트가 넘 빨리 끝나요 선착순 이벤트로 매일 수량 제한을 두는 탓에 참여하기가 어려워요 그나마도 하나의 이벤트를 참여하면 나머지 이벤트 참여가 안 되어 할 게 없어요', 60, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '다른 콜라보 때 보다 많이 부족했습니다. 모펀은 디저트가 맛있고 친절한 곳으로 기억하고 있었는데 프세카는 혹시 다른 BL웹툰 때 보다 SEGA등에 나눠야 하는 수익이 많아서 그런 건가요? 캐릭터 사용료가 비싸서 그런가요? 너무 이해가 안 갔습니다... 9천원짜리 팬케이크는 흡사 편의점에서 파는 허접하고 자그만 빵 위에 버터조각 하나 올려둔 정도였고, 따끈하게 제대로 구워서 파는 형태가 아닙니다. 그냥 포장지 까서 올려놓은 공산품 수준이예요. 메이플 시럽도 제대로 뿌려져 있지 않데 이걸 9천원에 파시나요? 그냥 코스터 한 장 판매하는 거로 쳐도 더 저렴해야 합니다. 할 말 더 많은데 다음회차 다녀오고 나서 더 리뷰 남기겠습니다 남은 기간동안 분발해 주세요! 지금까지의 모펀 콜라보와 너무 달라 당황스러웠습니다', 7, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '오늘 2번째 이용 했는데 코하네 쿠키도 맛있고 그린애플 모히또랑 크림모카 음료도 맛있었습니다 아쉬운건 특별한 메뉴 추가되는게 없고 콜라보 기간이 짧은 점 이네요', 32, 9, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '좋아하는 웹툰이라서 예약하고 방문했는데 잘 꾸며져있어서 눈이 즐거웠습니다:) 작가님 그림 언제봐도 예뻐요🥹💖 메뉴도 전부 맛있는 편이나, 스튜 세트랑 파르페가 가장 맛있었습니다. 개인적으로 쇼콜라는 별로 맛이 없으니 드시지 마세요;; 콜라보 굿즈도 다 잘나왔는데, 특히 일러스트 색지가 비싼만큼 값어치를 하는 퀄이였어요👍🏻 이벤트로 주는 포토카드도 전종 컴플리트!! (이 맛에 덕질한다) 남미숨 웹툰 좋아하면 콜라보 기간에 한번 쯤 들려보는 것 추천합니다~!', 41, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '카운터 보는 여자 직원 너무 불친절함. 입꼬리를 한쪽만 당겨 웃을거면 차라리 무표정으로 응대하는 게 나아보임. 말투도 비꼬는 말투라 주문하는 게 아니라 언쟁하는 느낌. 오랜만에 홍대 AK몰 놀러갔다가 기분만 잡침. 콜라보 카페때문에 바쁜 건 알겠는데 타임대별로 번호대기표 받아서 제한된 인원만 받아 운영하고, 주방이랑 카운터 둘 다 같이 보는 것도 아니고 본인은 포스기만 띡띡 누르고 있으면서 뭐가 그렇게 기분 나쁜지 의문. 위생모도 안 쓰고 있던데 식품위생법상 그래도 괜찮은건지?', 5, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '오랜만에 관심있는 작품콜라보라서 방문했는데 디저트도 맛있고 좋았습니다❣️ 이번에는 특히 콜라보 메뉴에 에스프레소🥹가 있어서 좋았어요!(카페인이 필요한 나이라..) 상품들이 금방 품절이 되버려서 ㅠㅠ 아쉬웠지만, 예약이 가능해서 좋았습니다☺️', 63, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '일을 정말 답답하게 하심. 예약을 하더라도 15분 지나면 자동취소되게 해야지...예약자리도 극소량이면서. 그리고 작가 사인회도 미리공지하고 선착순 폼작성 아닌 랜덤추첨을 하셔야지 맨날 받는 사람들(사인족)만 끼리끼리 대리싸인 대리예약 아주 가관이에요. 굿즈 5만원 이상 구매하면 현장에서  사인추첨권을 발행하세요. 굿즈는 사지도 않고 옆사람꺼 사진찍어서 방문포카만 받거나 작가싸인만 가로채기 당하는느낌. 굿즈 많이 사는사람에 속하지만 많이사도 혜택은 커녕 손가락이 느려서 사인회는 언감생심. 저같은 늦덕은 돈만쓰라는건지... 돈쓰면서 무임승차족같은 사람들한테 기회박탈당하고 돈쓰면서 기분드러운거 처음이에요. 이런식이면 모펀에 돈쓰기 싫네요. 샀던거도 다 환불받고픔. 여지껏 거진 300만원은 썼구만', 47, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '오늘은 전에 안 먹어본 디저트 먹고 왔어요😆 이번주 일요일이 마지막이라니 아쉽네요😥 토요일이랑 일요일 예약이 꽉 차서 그냥 예약 안하고 낼이나 모레 한 번  더 방문할 예정입니다~😘 바인더랑 색지는 구매했고, 전에 예약 구매한 굿즈 상품도 빨리 받아보고 싶네요😅', 23, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '좋아하는 소설웹툰 콜라보 소식에 큰맘먹고 올라갔어요 ^^ 종료 하루전에 방문해서 쿠키는 구경도 못했지만 꾸며진 일러스트를 큰 사이즈로 보는 것만으로도 너무 좋았어요 ^^ 좋은 콜라보 소식 있으면 또 올라가겠습니다 ㅎ', 4, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '프로세카 1주년 콜라보는 음료에 비해 디저트  종류가 적은 점이 아쉽고 콜라보 기간이 짧아서 특별한 메뉴가 안나올 느낌에 기대감이 떨어 졌습니다', 77, 13, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '다이소보다 못한 퀄리티 굿즈 퀄리티 구려서 사인받았다가 봉변당함 그리고 남의 물건 함부로 만져서 다 흠집남 보상이나 해결책 없이 내가 안고가야함. 이게 말이 되는건지 남의 물건 망가트리면 물어내야하는게 상식아닌가? 내 돈...내 물건...일진들이랑 뭐가 다른건지...ㅋ 돈주고 매우 비싼 쓰레기를 얻고 불친절함과 불쾌함을 사왔음 사인은 작가가 해주는거지 본인들이 해주는게 아닌데 직원들의 말과 태도에서 괴이함을 느낌. 물을께 있어서 직원한테 갔는데 잠시만요하고 카운터 안에 들어갔다 직원 쳐다보면서 기다렸는데도 아무말없이 바로 작가한테 가버려 멀뚱히 세워둠 결국 기다리다 다른 직원 찾아서 해결함. 주객전도를 느낌. 내가 을이되고 싶고 인내심이 부처와 같으며  돈이 넘쳐나 자기 자신에 대해 되돌아보고싶으면 가보시길', 62, 17, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), 'This cafe has the best themed events for korean webtoons. The merch was great and the special desserts and drinks were really fun to try. I''m just a bit sad that some of the merch was already sold out.', 6, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '친구들과 가서 같이 음료와 디저트를 즐겼습니다~ 신기하게 생긴 구조물에 사진을 넣을 수 있는건 좋았습니다 포스트잇으로 벽 한쪽을 예쁘게 꾸밀 수 있어서 즐거웠습니다!', 7, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '다른 곳과 다르게 사인지도 준비 안해주면서 가져간 굿즈들 다 망가뜨리고 발뺌하는 모습을 볼 수 있음 쓰레기에 사인받은 사람됨.피해를봐도 손님이 속으로 삭혀야한다는 식으로 일처리를 함.덕분에 불친절로 기분이 상해서 애정작도 애정이 식어 오히려 분노만 남게 만들어줌. 손님이 디피된거 망가뜨리면 물어내라할꺼면서 내꺼는 왜 안물어내는지 강도인가 혈압약 필수인곳. 작품 이름 볼때마다 이젠 기분나쁜 기억부터 생각나고 돈 생각부터 남. 쓰레기봉투 묶던 그대로 손 안닦고 포토카드 나눠주고 케이크도 맨손으로 집어서 줌.허니브레드 태운건지 썼었음.그리고 항상 형평성 운운하는데 뒤에서 말이 많이 도는데는 이유가 있음.출판사들은 후기들 좀 더 서치하고 본인들이 이벤트를 열었으면 좋겠음.출판사는 작품 명성 떨어지는거 생각 안하는듯', 36, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '여타 콜라보 카페에 비해서는 디자인도, 메뉴도, 굿즈도 부실했지만 프로세카 콜캎 첫 걸음이라는 점에서 앞으로를 기대해야겠습니다', 18, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '요새 부쩍 많아진 애니메이션 게임 만화 캐릭터를 소재로 한 콜라보 카페 중 국내 작품을 소재로 한 곳은 그리 많지 않아요. 그중에서도 홍대의 (예전에는 사당의) 모펀카페는 로맨스 이야기를 다룬 작품을 낭만적인 콜라보 카페로 승화시키는 데 가장 능숙한 곳이라는 인상이 있습니다. 항상 편안한 분위기에, 독특한 콜라보 메뉴의 이름을 곱씹으며 맛있는 메뉴를 즐기고 캐릭터 상품을 이것저것 둘러볼 수 있어요. 상수리 나무 아래 라는 작품은 아마 소설 원작의 웹툰인 것 같은데, 저는 모르는 작품이었습니다. 하지만 콜라보 카페 이벤트를 계기로 좋은 작품을 더 잘 알 수 있는 계기가 된 것 같아요. 한번 기회가 닿는다면 원작도 접하고 싶습니다. 체리에이드 위엔 통조림용 가짜체리 말고 진짜 체리를 부드럽게 절인 것을 올려요', 10, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '렌티로 바닥이라도 닦았나 상태들이 경악스러움 돈받으면 바로 태도 바꾸고 맨날 안된다 공뎀이라고 말하는데  언제까지 공장탓만 할것인가 그렇게 공뎀이 많다면 진작 업체를 바꿨어야하지 않나? 제작 늦어지는 상품일지라도 미리 뽑아 놓은 샘플은 전시할수있는데 그런적이 없는것과 상품 상태들이 심각한거보면  샘플  전혀 안뽑아보고 판다는걸 알 수 있음. 중국산이라 다른곳과달리 기간내 재입고 절대안됨. 작가들도 신분안밝히고와서 서비스 직접느끼고 굿즈랑 메뉴도 돈주고 사봤으면. 항상 대접받고 공짜로 굿즈받아서 모르나 이건 작품 이미지도 실추 시킨다. 타 카페랑 콜라보한 어떤 작가님은 본인 이름과 작품을 걸고하는거라고 적극적으로 후기 모니터링해서 적극적으로 의견내고 개선시키던데...비교가 되는건 당연한일일수밖에 없음.', 8, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '생일구간이 아니라서그런가 사람은 적고 널널했습니다☺️ㅎㅎ 예약석이라고 되어있는좌석이 예약좌석이구그거아니라면 앉아도되는거같았어요(주중기준입니다.) 디저트도 이만하면 꽤 맛있었어요!', 71, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '애니메이트 지나가다 보면 항상 자리가 꽉 차있어서 궁금한 곳이였어요 제가 좋아하는 작가님 콜라보로 행사가 열려서 연차 쓴김에 들렸어요 미리 예약했더니 예약석은 편한곳이라 좋았구요 파르페 생각보다 넘 맛있었어요 ㅎㅎ 포카도 받고 이것저것 많이 챙길수 있어서 즐거웠어요 ㅎㅎ', 24, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '위치도 장소도 접근성도 너무 좋아요. 같은 층에 애니메이트도 있어서 참 좋습니다. 음료는 양이 더 많았으면 좋겠어요. 천천히 머무르면서 먹는 편은 아닌지라 얼음이 있는 음료 양이 갈증을 해소하기에도 아쉽습니다. 그래도 요청시 물을 제공해줘서 좋구요. 얼음을 간 스무디 종류의 메뉴 한가지는 꼭 있으면 좋겠어요.', 43, 1, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '직원분들이 너무 불친철...알바분들은 친절하게 잘 해주시는데 직원은 "안돼요, 이거 아니예요" 이렇게 사람무안하게 만듭니다. 원래 서비스직 이거 교육 있지 않나요??', 0, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), 'AK들릴일 있어서 카페 왔어요! 여러 작가님들이랑 콜라보하는 것 같아서 구경하면서 커피마시기 좋네요! 테이블이 우선 넘 넓어서 커피마시기 좋았어요', 340, 40, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '일본 애니를 좋아하시는 분들이라면 무조건 추천하는 카페입니다. 바로 앞에 피규어 파는 곳도 있습니다. 신선한 경험을 한 카페였습니다', 13, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '앙스타에 관심이 너무 많아서 갔는데 진짜 좋았습니다💗💗 트릭스타 음료 맛은 그냥 귤 오렌즈 섞어서 만든 맛 라빗츠 토끼 케이크는 적당히 달았어요 더블페이스 초코딸기아이스크림은 걍 이름 그대로 맛 그대로 맛있음 에덴 아포카토는 커피 좋아하시는 분들만 추천 드림 ^^ 하지만 다 맛있었음😍 안가면 ㄹㅇ 후회하는 곳임 굿즈도 팔고 너무 좋았음 뮤비도 틀어주고 너무 좋은 곳😆', 10, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), 'I love their collab events! Lots of merch, different food and drinks, and it''s simple to earn free event gifts ^^', 22, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), 'super nice staff. I love their collab events, they have good food and drinks, and they have free gifts and events to earn more free gifts for that collab. The food and drinks are always different for each collab and are delicious. the entire place is also good to take photos, they have different displays and cutouts for every event', 4, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '10년 넘게 좋아한 작품의 콜라보 이벤트가 있다고 해서 가봤습니다. 솔직히 콜라보 메뉴는 실망스러웠지만 그래도 향수를 자극하는 작품의 굿즈들을 살 수 있는 기회가 있다는 것만으로도 기뻐서 즐거운 시간을 보냈습니다.', 71, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '진짜 카페 테마들이 잘 전시 되어 있어서 너무 좋았고 음식들도 맛있었습니다!!글고 직원분들 마다 친절하셔서 더 편안하게 즐길 수 있는 것 같습니다!!', 29, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '예약하고 편하게 이용할 수 있어서 좋았고 항상 콜라보 때마다 특별한 메뉴가 있어서 다음엔 어떤 메뉴일지 궁금해서 또 가고싶기도 해요🥴', 80, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '명장면을 이렇게 크게 볼 수 있는 점도 너무 좋고 틈틈히 야화노래도 나와서 너무 좋았습니다💕 물론 디저트랑 음료도 너무 맛있었구요❤️ 제가 단 걸 자제하고 있어서 덜 달게 부탁드렸는데 따뜻한 물도 주셔서 희석해서 마셨어용😍 넘 친절하셔서 감동😭 굿즈 예약주문할 때도 잘 몰라서 이것저것 물어봤는데 친절히 답변해주시고 넘 감사했습니당💕 다른 콜라보할 때도 갈게요🥰', 30, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '첩돌이로써 행복한 시간이었다는 것에 의의를 둡니다. 윤승호 포카 얻고 나겸이 사진얻어서 행복했어요🥲 다만 갈때마다 생각하지만 조금은 가려진 공간이면 좋겠다는 생각은 이번에도 들었구 오미자 들어간 음료 맛있습니다', 9, 5, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '그냥 하늘이 두쪽이 나더라도 무조건 가셔야 합니다,,,,음료랑 디저트는 기대하지 마시고 그냥 윤승호 전시회 입장료라고 생각하시면 될 것 같습니다,,,,월클 야화첩답게 사람 정말정말 많고 계산하는데도 오래 걸렸습니다. 승호랑 나겸이를 저렇게 크게 볼 수 있다는 것에 감사합니다,,,,', 35, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '앙스타 콜라보 한대서 처음으로 방문했는데 메뉴도 맛있고 직원분들도 친절하시고 매장도 깔끔하고 잘 꾸며져있어서 너무 좋아요ㅠㅠㅜㅠ💕😆', 47, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '홍대 모펀은 처음(사당포함 두번째🤣)인데 생각보다 개방적인 공간이라 놀랐어요!! 근처, 바로 옆에 애니메이트 북새통 등등 굿즈, 만화책 파는 곳들이 있다보니 오가는 사람들도 많아서 앉아 있을 때 조금 부담스러울 수 있어 안쪽에 앉으시면 괜찮을 거 같아요! 위치는 ak플라자 5층 에스컬레이터 올라오면 바로 보여요! 직원분들도 모두 친절하시고 문제가 있음 빠르게 해결해주십니다!! 대형 일러스트 액자들도 있어서 볼거리가 넘쳐요', 52, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '완전 짱이였습니다!! 예약해서 들어가졌다는게 너무 신기하고 긴장되서 주문할때 엄청 버벅거렸는데 직원 분들이 엄청 친절하셔서 안심이였습니다🥺🥺🥺 다음에 또 방문할게요!!', 1, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '평소에도 어공주 웹툰으로 너무 잘 보고있고 스푼작가님 팬이라서 이번에 처음으로 모펀 방문해 본 건데 신기했어요!! 곳곳에 전시되어 있는 그림이나 판넬도 구경하는 재미도 있었고 진짜 너무너무 예뻤어요 작가님께서 그림체 예쁘신 건 알고 있었지만, 콜라보 준비하신다고 더 공들이신게 티가 나요!!! 눈으로 볼때 섬세한 부분들이 카메라로 안 담겨지는 게 좀 아쉬웠어요ㅜㅜㅜ카메라 가져올 걸 후회했답니다. 그리고 혼자 잘 안 다니고 콜라보 카페간 게 처음이라 주문할 때나 굿즈 예약할 때 떨려서 직원분들께 횡설수설하게 말씀드렸는데 친절하게 해주셔서 감사드렸어요~ 그리고 중요한 게 음료도 케이크도 너무너무 맛있었어요!! 약간 아티처럼 공주된 기분이랄까요ㅎㅎ혼자서 이것저것 구경하고 재미있었습니다!!!', 22, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '티파티 세트가 다 나가서 아쉽게 리페차와 루카스와 아티의 초코케이크를 주문 했습니다!! 이것도 맛있네요! 특히 리페차가 굉장히 맛있습니다 히비스와 장미, 레몬 등 정말 ‘마치 꽃이 피어난 것 갔다’ 라는 표현이 절로 나오더라고요!! 너무 좋았습니다', 42, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '진짜 직원들이 불친절하다는 이야기는 많이 들었지만 이렇게 불친절할 줄은 몰랐어요. 일하기 싫은 티 팍팍 내면서 손님들한테 화풀이 하고 왜 거금 들여서까지 직원들 화풀이 상대가 되야하죠? 사장님 직원들 관리 좀 하세요. 자리도 엉성하게 해놓고 손님 탓으로 돌리고 사과도 안하고 진작 와야하는데 왜 지금 왔냐 아니 줄이 있는데 어떻게 미리 오는데요. 새치기할까요? 모펀이 왜 자꾸 이슈가 생기는지 딱 보니 알겠네요. 염색 머리에 주문 위주로 받으시던 여자 직원분. 일하기 싫으시면 하지마세요. 가스라이팅 전문 카페인가 생각했네요;; 여긴 직원이 갑인 카페인가봐요ㅎㅎ 콜라보 아니면 진짜 다신 안가요. 솔직히 콜라보 하더라도 갈 마음 싹 사라짐. 방문하실 분들은 멘탈 챙기고 가세요.', 45, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '작가님께 사인을 받을 수 있어서 영광이었습니다! 오랜만에 가는 모펀이어서 더 좋았던 것 같아요~! 곡물 스무디는 좀 달긴했지만 그래도 먹을만 했던 것 같아요! 등신대 너무 이쁘고 승호랑 나겸이 얼굴이 여기저기 도배되어 있으니까 너무 좋았습니다.', 21, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '예약방문기간에 방문해서 쾌적했는데 카운터 분들이 친절하진 않았고 남자직원분이 계신데 메뉴가 나와서 눈앞에서 기다리는데도 호출을 해주지않아서 불편했어요', 22, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '10월4일 4시타임 예약해서 방문했는데 이시간대에 카운터 포스보시던 여자분이랑 음료제조하던여자한분,남자한분 진짜 최악이었습니다. 테이블 이용 안하고 테이크아웃으로 하고싶어서 테이크아웃으로 요청드렸더니 음료 하나를 갑자기 테이블용으로 주질않나(잘못나온거 사과도안함) 테이블 사용하지도 않았고 서서 테이크아웃 기다리고 있는데 예약 안한사람은 테이블 이용 불가능하다고 대놓고 쳐다보면서 꼽주질않나 음료 잘못나왔을때 진동벨 회수해놓고 테이크아웃으로 음료 나온거 얘기도 안해서 한참기다리게 해놓고 직접 가서 물으니까 그제야 음료나왔다고 가져가라고 하는거까지 최악콜라보. 일 하루이틀 하나요? 예약한 의미가 있는건지도 모르겠네요. 10월4일 4시타임에 있던 직원 세분 일하기 싫으면 하지마세요;', 47, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '디저트 맛 없고... 직원 불친절하고... 카운터에서 예약자 주문 줄 따로 마련해주세요. 예약하고 왔는데 방문테이크아웃 줄에 서있다가 뒤늦게 주문했습니다. 예약제 운영이면 예약자와 비예약자 확실하게 구분하게끔 대기줄을 만들든 해주세요. 이벤트 때문에 가는거지 아니었으면 재방문하고 싶은 마음 전혀 들지 않습니다.', 35, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '모펀 자주 가는데 오늘 직원분 이제껏 온 것 중에서 제일 불친절했어요ㅠ 음료가 맛있어서 가는게 아니라 콜라보하는 작품이 좋아서 가는건데 말투가 너무 진상보듯이 말씀하시네요 무서워서 못물어보겠어요ㅎㅎ 남자직원분은 진짜 친절해요', 66, 13, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '앙스타 콜라보 카페 다녀왔는데,무리를 지어 다니느라 통행로 막는 코스어들 때문에 불편했습니다.카페 측에서 제지도 안 하시던데 어떻게 좀 해 주셔야 할 거 같아요.그리고 카페 직원분께 예약 시간까지 10분 정도 남았으나 미리 예약석에 착석해도 되는지 여쭤보려 했는데 한숨쉬시던데 직원분 피곤하신건 알겠지만 이용하는 입장에선 좀 기분 상했네요.', 105, 26, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '처음에 와보는 모펀콜라보카페! 어공주 굿즈를 재고없는줄알았는데 넉넉히 많이 있어서 다행이에요.직원한테 메뉴과 상품을 인증을 보여드렸더니 랜덤 몇장이 주셨어요. 직원분이 트위터팔로우 하셨냐고 묻고,잊을뻔했어요. 친절히 질문해주셔서 감사해요. 직원들이 왜 불친절하셨는지를 이해가 안되요. 손님들은 얼마나 불편하셨겠지만 직원들은 이해주시길 바랍니다.', 37, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '좋아하는 웹툰이 콜라보해서 다녀왔어요! 너무 예쁘고 행복하고 직원분도 계속 질문드리는것마다 친절하게 답변해주셔서 감사했어요ㅠㅠ 머리하나로 묶으신 분이요!', 17, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '모펀카페직원분들은 친절하셨지만 운영방식이 잘못된것같습니다. 아이가 좋아해서 예약하고왔지만 예약의미가없고 이럴람 왜 날짜 시간선택해서 결제를했는지 일부러 마지막날선택해서 왔는데 굿즈는 이미품절,디저트,쿠키 품절품절. 이럴줄알았으면 오픈하는첫날에갈껄 후회가. 생일선물로맘껏사라며출발하기전말한...현실은 본인이사고픈거못사고 우울해하는 아이보면서- 마음의상처입었습니다. 그래도 아이가 어공주는 좋아할거라하니할말없지만 다음에 또 하신다면 타 다른 굿즈판매하시는거보시고 하셨음합니다.', 49, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '생각보다 너무 개방적인 공간이었지만 그래도 괜찮았어요 레드벨벳 라떼 좀 많이 단 편인데 맛있습니다 휘핑 없이 먹음 괜찮을 것 같아요', 129, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '직원분들이 친절해서 좋았어요~ 사진 찍는데 공간이 협소해서 그런지 사진들이 모여있어서  모여있는 사진들 안 쪽 사진은 찍기가 좀 난감하더라구요~ 작가님과 작가님 사인을 받을 수 있어서 아주 행복했습니다~👍', 11, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '루카스케잌 데코초콜릿이없어 아쉬웠지만 대신에 포카를주셔서 좋았습니다~^^ 케이크가무지달아요ㅜㅜ 다음엔이제키엘도전하겠습니다!ㅎㅎ', 37, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '어피 작가님 콜라보 카페♡♡♡ 이번에 굿즈 종류가 조금 적어서 아쉬웠지만 세 작품 함께 진행해주셔서 더 좋았던 것 같아요*-* 파운드 케이크 특히 맛있었어요!!', 36, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '안내원분이 엄청 친절하십니다. 사인회때문에 방문했는데 시간이 늦춰저서 아쉬웠는데 엄청 잘 대해주시고 질문에 답변해주셔서 초조하지 않고 기다릴 수 있었어요. 다음에 또 방문할 것 같습니다.', 40, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '박지연작가님 작품을 즐기기위해 모펀 방문했습니다 음료랑 디저트 다 맛있었고 무엇보다 좋아하는 그림이랑 굿즈 구경하며 덕친이랑 즐거운 시간 보내서 좋았어요♡♡', 68, 14, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '티 세트 먹으러 이틀 연속으로 방문했는데 직원분 매우 친절하셨습니다 맛도 너무 좋구요 다만 아쉬운 건 굿즈가 전부 품절이었다는 점이 아쉽네요 다음에 재입고 날에 맞춰서 한 번 더 가려구요!', 71, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '수상한 메신저 굿즈로 재희 홀더를 사서 무척 행복합니다. 관심있는 장르의 카페가 열린다면 꼭 다시 재방문 해서 카페를 이용해보고싶습니다.', 6, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '사람이 너무 많음 예약을 해도 일반입장이랑 같이 줄서서 기다려야함. 4시타임이 6시까지인데 아무리 늦어도 이용시간 안에 갔으면  6시 전에는 주문 받아줘야 하는거 아닌가요 대기하다가 결국 6시 돼서 6시엔 주문 ㅇ안 받는다함.', 1, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '블루레몬에이와 아이스티 먹었는데 맛있았어요 초코케익도요 너무 딱딱 하긴 했지만 맛있었고 제가 찾는 제품이 아쉽게도 없어서 예액을 한거 빼고는 다 좋아요 ㅎㅎ', 22, 6, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '12시26분 카운터 보던 머리 내려서 하나로 묶고 남색상의입은 직원분 너무 불친절해요 말투,표정 다요 말을 할 때 화를 내요 소리는 왜 지르나요?  친절하게 말하는법 연습해야할거같네요 모펀에 많이 왔지만 이런 직원은 처음이네요 기분 좋게 왔다가 그 직원 때문에 기분 나빠져서 갑니다', 15, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '굿즈를 파는 곳과 음료를 주문하는 곳이 따로 있었으면, 혼란이 없을텐데~ 음료와 굿즈를 같이 판매하니 소비자 입장에서  혼란스럽네요ㅜㅜ 예약시 카페 이용과 설명이 있으면 좋을 것 같습니다.  그리고 남자 직원분이 불친절하고 융통성이 없어서 기분이 좀 상했네요~ 굿즈는 너무 이뻤네요^^', 242, 87, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '볼지는 모르겠지만 화나서 후기에 남깁니다. 이번에 운영방식 욕 많이 먹고 있는거 아시죠? 위편 진행 중에 달사누 그것도 팝업존이랍시고 비좁은 공간에 굿즈 파는 거, 그거부터 작가님에 대해 예의없다고 생각했는데 가격 대비 현저히 떨어진 굿즈 퀄리티, 대부분 파본인 굿즈들, 불친절한 직원, 콜라보 한두 번 한 것도 아닌데 이상하게 빨리 소진된 굿즈들, 달사누는 심지어 콜라보 기간 절반이나 남았는데 금액당 증정품 소진 등 무리하게 진행할 때부터 알아봤었는데 역시나...ㅎ 소비자는 안중에도 없나보네요. 작가님과 작품에 대한 애정 아니었으면 가지도 않았을 겁니다. 소비자가 소비해주면서 기분 나빠야하는게 맞는건가요? 하나도 제대로 된 게 없습니다. 소비자 없으면 카페 운영도 안된다는거 아셨으면 좋겠네요.', 39, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '모펀 직원분들 왜 작가님 방문하시는 날 친구분한테 말해주시나요? 특히 단발머리에 홍대점 오픈때부터 일하신 여자 매니저님. 친구분이 자꾸 관계자 외 출입금지 들어가시고 그 친구분은 매번 작가님한테 사인받으시네요. 다들 아시던데요. 혜택 받으시는거요. 그리고 굿즈랑 특전들 하자 너무 많아요. 가격이 저렴한 것도 아닌데 확인하고 팔아주셨으면 좋겠습니다. 이번에 위험한편의점 비엘웹툰 콜라보카페 진행하면서 달콤한사기꾼은누구 비엘웹툰 " 팝업 " 진행하셨는데 특전도 적어졌는데 굿즈는 더 비싸지고 심지어 방문포카랑 특전이 동일했는데 품절됐으니 재입고를 안 한다니 작가랑 독자 생각은 처음부터 없었나봅니다. 음식도 맛도 없는데 비싸네요. 그냥 남성향 콜라보 카페 여시거나 예전처럼 리듬게임 사업 진행하시는게 어떠신가요?', 39, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), 'The staff was super friendly. Even though I didn’t know much korean, he took the effort to explain how the themed cafe worked. Super kind.', 18, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '운영방식이 별로입니다. 간 사람들은 대부분 알거에요. 직원들 불친절하고 (알바생들은 친절했습니다) 이번에 파본 많아서 욕 먹었는지 교환 이전보단 잘해주시는 거 같은데 그건 당연히 그래야하는거고 본인이 생색낼 일이 아니에요ㅋㅋㅋ 왜 생색 내면서 교환을 해주는지 잘 모르겠네요? 그리고 흰귀 작가님 콜라보 때 누가봐도 파본인거 교환어렵다고 하더니 이번에는 잘 바꿔주더군요. 구멍까지 난거였는데 대체 왜 그 때는 교환 안된다고 한거죠? 그 직원 분 아직도 계시던데 일처리 기분파로 하니까 기분 나쁘고 소비자가 왜 파본을 감수해야하는지 모르겠습니다. 일처리 똑바로 하세요. 이전까진 후기 쓰는거 넘겼는데 이번에는 유독 심해서 한 마디합니다.', 84, 11, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '언제나 먹으러 가는건 아니지만 음식과 서비스와 일처리 그 무엇 하나 정상적이지는 않은 곳이긴 합니다. 하지만 끊을 수 없다.....', 4, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '콜라보 하는 건 좋은데 준비 좀 제대로 했으면 좋겠어요... 오픈한 지 얼마 안 됐을 땐 메뉴얼이 유동적이라 그럴 수 있다 쳐도 지금은 1년이 넘었는데 운영 방식 면에서 나아진 게 없는 것 같아요. 인기작 콜라보 여러 번 진행하면서 손님 유입도 늘었고 단골도 많은데 왜 매번 상품 수량을 못 맞추나요? 예약하고 방문했는데 굿즈가 없어서 빈손으로 돌아오는 경우가 몇 번째인지 모르겠어요. 지방에 살면 ktx 비용도 만만치 않은데 수령하려면 다시 서울로 가야 하고... 그리고 직원인지 알바인지 모르겠지만 몇몇 분들 너무 불친절해요. 저번에 카페 이용하면서 제가 전달해드린 물건 휙 던지고 인사 무시하셨을 때도 참았는데 이번엔 못 참겠어서 리뷰 남깁니다. 달사누 팝업은... 후기 보고 사람들 의견 좀 참고해주세요.', 28, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '작품을 좋아하는 사람들끼리 모여 굿즈도 구매하고, 컨셉 푸드도 즐기고, 이야기를 나눌 수 있어서 좋지만 운영면에서는 아쉬운점이 많았습니다. 1. 굿즈 품절이 너무 빨라요. 힘들게 찾아갔는데 없는게 더 많네요. 돈 더 벌고싶지않으신가요? 작가님한테도 수익 많이가면 좋지않나요?제겐 돈이있는데,, 예약을하라는데 언제또오냐구요ㅠ 2. 위편 콜라보 카페지만, 한편으론 달사누팝업도 동시진행인데 방문포카가 거의 초반에 동나서 받지도 못하고 재판도 없고 그 종이가 뭐라고 넉넉하게 준비가 안되나요?종이에 원가 절감할 필요가.. 그 한장에 굿즈만원사라하면 살텐데 아예없으니원... 3. 친절하신분은 엄청 친절하신데, 아니신분들은 진짜 아니었어요 일부 직원은 앉아서 핸드폰하고 수다떨고 그런거 첨봐요', 10, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '흰귀 작가님 콜라보 카페도 넘 좋아요^-^!!! 케이크 특히 맛있습니다♡ 기간이 짧은게 아쉬워요ㅠㅠㅠㅠㅜ연장해주세요..콜라보 더더 길게 해주세요!', 23, 5, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '콜라보카페라 해서 가봤는데 생각보다 음료랑 디저트가 맛있어서 좋았어요. 특히 가또 오 소쿌라 초콜렛 맛이 진해서 맛있더라구요!', 0, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '최근 모펀에서의 일로 덕질의 회의감마저드는 요즘 몇년의 방문이후 첫리뷰가 이런 주저리글이라 슬프네요 서비스직의 애로로 이해하려해도 한직원의 지난주의 이유모를 불친절..지나갔습니다..같은직원의 이번주의 무례함..참을수없더군요.메니저님의 그직원도 처음은 그렇지아니했다 라는말씀..당연한거아닌가요 처음 부터 그러면 제정신이아닌거죠 손님이 뭘 모르든 건의를 받아들일수없든 일단 그에대한 설명과 이해를 구해야지 처음부터 사람의심하며 취조식의 질문과 야단치는말투는 어디서도 듣도보도못해 충격이었습니다;;;황당하다 뒤늦게 화가나더군요.직원들은 진상의뒷담화로 끝낼수도있겠지만 이곳은 저처럼 만화동호회회원분들이 지방회원들을위해 대리구매로도 많이옵니다 작품과작가생각해서 오는곳입니다 독점이라 자만하지마시고 초심잃지않기를 바랄뿐입니다.', 129, 19, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '대리화가 모펀콜라보카페 홍대점 방문했습니다 메뉴 맛있고 일러스트와 굿즈들 즐길수있어요 대리화가 만의 이벤트도 참여했는데 즐거웠습니다', 66, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모펀 AK PLAZA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '주문에 실수가 있었는지 메뉴가 잘못 나왔었는데 괜찮다고 말씀드렸는데도 메뉴를 다시 가져다주셔서 감사했습니다. 즐거운 시간 보내다 갑니다.', 32, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '영국인 친구들이 맛있는 케이크 먹고싶대서 홍대에서 검색해서 갔는데 다들 만족해했어요 단호박치즈케잌도 신기한데 맛있었고 다쿠아즈 종류가 엄청 다양해서 또 방문하고 싶어요! 만석이라 2인석에 셋이 낑겨 앉아야했고 사진은 마감때 텅 빈 사진입니다!', 24, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '뭐 브런치처럼 아점을 먹고 나서 간 곳이라 주는 대로 커피는 잘 마셨어요. 연하고 부드러운 맛의 커피 그리고 조그만 접시의 쿠키는 서비스로 식탁마다 다 주는 것이었어요. 뭐라고 하던데 쿠키 이름은 생각나지 않지만 부서짐이 적고 부드러움이 넘쳐나는 그런 맛이었습니다. 다쿠아즈가 사장님 진짜 시그니처인 것 같았어요.  만든 정성이 느껴지는 그런 모양이었습니다. 케이크는 아이들이 워낙 좋아하는 것이라 카페 갈 때마다다 먹어 보고 있고 여기 케익도 맛있습니다. 먹으러 다니면서 느끼는 건데 이런 디저트 카페는 과하지 않은 맛이 사람들을 은은하게 끌어 당기는 것 같습니다. 여기는 다음에 가도 또 갈 곳으로 찍어 놓으랍니다.😘😘😘', 11, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '진짜 아늑하고 원목 테이블 유니크한 분위기가 좋아요☕️ 2인석 4인석 자리도 다양하고 콘센트도 다 있어서 편리했어요💕 ✔️밀크티(6,500원) ✔️오렌지 에이드(6,500원) 주문했는데 서비스 쿠키까지 주시고 사장님 인상 너무 좋으신데 친절하세요👍🏻 직접 앉은 위치까지 갔다주셔서 서비스 좋으세요~☺️ 넓은 편은 아니라 주말에는 만석일 수도 있을 것 같아요‼️ 화장실도 정말 깔끔했어요😃 매장 자체에서 쾌적한 향기도 났고 다음에는 다쿠아즈가 시그니쳐라는데 먹어보려고요! 🥹 배불러서 못먹은게 너무 아쉬웠어요 종류도 정말 많았구요~🙏🏻 홍대 주변 사는 친구한테 추천받아 왔는데 100% 내돈내산으로 후회없는 픽이었어요~☺️ 왜 홍대에서 주민들에게 사랑받는 카페인지 알것같아요🩷', 17, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PLUG');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
