INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '매번 사람이 많아서 운이 좋아야 들어갈 수 있어요ㅎ 근데 그만큼 케익 맛잇고 서비스로 주시는 쿠키도 맛있어요 가게가 쫌만 넓었으면 하는 마음ㅜ.ㅜ♡', 25, 10, NULL, SYSTIMESTAMP);
