INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '딸기우유케이크 맛있었어요. 딸기는 새콤하구 크림에세 정말 맛잇는우유맛나요. 특히 시트가 너무 부드럽구 입에서 녹아여!! 같이주신 사브레쿠키두 하나하나 각각재료맛이 진하구 맛있어요. 감사합니다. 다쿠아즈 포장해가는데 너무 기대됩니당.', 10, 0, 'GOOD', SYSTIMESTAMP);
