INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '다쿠아즈 맛있는 곳이에요. 크림도 느끼함 전혀 없고 꾸덕하긴 한데 입에 넣으면 사악 녹는… 무화과 다쿠아즈 처음 먹어보고 맛있어서 놀랐어요. 딸기프레지에도 크림이랑 시트 부드러워 술술 넘어가요.', 19, 9, 'GOOD', SYSTIMESTAMP);
