INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '망고스무디가 진짜 신선하고 맛있었습니다. 카페 위치 찾는게 조금 힘들었는데 디저트도 다 너무 훌륭하고 손님들이 계속 들어와서 있는동안 계속 만석이었습니다. 분위기도 좋아서 적극 추천합니다!', 26, 7, 'GOOD', SYSTIMESTAMP);
