INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '딸기케이크 최고봉.........🍰 너무 맛있어요!!!! 음료들도 최고!!!! 카페장쌤을 아직 안 간 사람은 있어도, 1번만 간 사람은 없을듯!!!!', 20, 6, 'GOOD', SYSTIMESTAMP);
