INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '딸기케잌으로 유명한 홍대디저트 카페 장쌤입니다. 딸기 프레지에를 먹어봤는데 새콤달콤한 딸기에 부드러운 프레지에 크림이 너무 맛있어요!😋 서비스로 쿠키도 몇개 주셨어요. 다음엔 다른 디저트 먹으러 가야겠어요!', 85, 13, 'GOOD', SYSTIMESTAMP);
