INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '홍대 디저트 카페하면 떠오르는 장쌤. 오랜만에 갔는데도 여전히 굳건히 자리를 지키고 있어서 반갑고 좋았습니다. 시그니처인 밀크티 쇼콜라 케익은 여전히 맛나네용. 다쿠아즈도 유명하긴한데 저는 장쌤은 케익이라고 생각합니닷.', 69, 12, 'GOOD', SYSTIMESTAMP);
