INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '카페 장쌤은 케이크가 찐인데 아쉬운대로 다쿠아즈 사왔어용 다쿠아즈 예전에 먹었을 땐 맛있었는데 이번엔 그냥 그렇네요 .. 말차맛은 진했습니다!', 39, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '홍대에서 젤로 맛있는 딸기케이크 집🍓 여러 곳 가봤지만 카페 장쌤이 최고예요🔥 가게도 아늑하고 인테리어도 따뜻해요 (가게 안에 화장실도 있어요👍 이게 엄청난 장점이라구 생각합니다 ㅋㅋ) 홍대 근처에서 케이크 살일있으면 꼭 이 집으로 옵니다 대표메뉴인 프레지에는 말모말모이고 딸기 초코 생크림도 맛있었어요! 내년 크리스마스엔 초코생크림으로 예약할까 고민중 (내년에도 초코생크림 예약 받아주세요✨)', 13, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '앉는 자리는 별로 없어서 케이크 포장했어요. 미리 프레지에 1호 예약했어요(42000원). 생크림에 바닐라빈이 섞여있어서 너무너무 맛있고 딸기가 풍부해요.', 75, 16, 'GOOD', SYSTIMESTAMP);
