INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '남자분 사장님인지 그냥 직원인지 모르겠지만 너무 불친절한데요; 대기 해야했는데 인사도 아무 안내도 안하셔서 다들 안에서 대기하고 있는데 자리 생겼는데도 테이블 치우시지도 않고 카운터에 서서 대기줄만 빤히 처다보시더니 갑자기 안에서 그렇게 기다리시면 안된다고 ㅋㅋㅋㅋ 어떡하라는건지.. 주문받을때도 아무런 말과 응대가 없음 케이크가 맛있으면 뭐해요 먹기전부터 기분 상하는데 그리고 들어오는 모든 손님들한테 자리없단 말을 한숨섞인 짜증내는 말투로 하심 사장님이시면 손님을 이렇게 대하지는 않겠죠? 케이크 맛있는집은 널렸어요^^ 다신 방문 안 할듯 합니다', 71, 14, 'BAD', SYSTIMESTAMP);
