INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '휴업 후 컴백하셨군요 🥹🥹 오랜만에 맛볼 수 있어 기뻤어요 출산한 친구 선물로 포장해갔는데 덕분에 아주 즐거운 시간이었습니다 🎶', 100, 25, 'GOOD', SYSTIMESTAMP);
