INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '딸기가 먹어도 먹어도 계속 나와요 미니 프리지에라 둘이서 먹기 좋은 사이즈라고 생각했는데 양이 꽤 돼서 2번에 나눠서 먹었어요 크림이 부드럽고 풍미있고 촉촉한 시트와도 잘 어울렸어요', 46, 6, 'GOOD', SYSTIMESTAMP);
