INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '다시 영업을 시작하셔서 너무나 좋습니다. 거기에 제가 사랑하는 슈 메뉴도 생겨서 더 좋아요. 피스타치오무화과슈는 아주 맛있었고 2시에 방문했는데 밤 슈가 소진이라 슬펐습니다. 복숭아케이크도 상큼하니 좋았어요. 웨딩 임페리얼을 주문했는데 항상 어쩜 이렇게 향도 좋게 잘 타시지..그저 감탄뿐입니다. 또다른 사랑인 레몬마들렌 데코가 변해서 말린 레몬조각이 크게 올라가 있어요.', 2, 0, 'GOOD', SYSTIMESTAMP);
