INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '1년넘게 홍대에서 모임이 있으면 카페는 항상 여길 가고있어요. 디저트도 맛있고 홍차커피등 음료도 맛있으면서 깔끔하게 테이블셋팅도 해주세요. 화장실 별도관리하셔서 아주 깔끔하고 좋아요.', 5, 7, 'GOOD', SYSTIMESTAMP);
