INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '피스타치오슈랑 바나나푸딩을 못먹어서 아쉽지만 다쿠아즈도 정말 맛있었어요! 사람이 많은데 운좋게 자리를 잡았네용 커피도 맛있구 디카페인 원두도 맛있는데는 첨이었어용!', 36, 4, 'GOOD', SYSTIMESTAMP);
