INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '예전부터 오고싶었는데 드디어 소원 이뤘어요. 코스터도 예쁘고 케이크와 다쿠아즈 정말 맛있었어요. 홍대 근처 방문하면 또 오고 싶어요~ 진짜루🥹', 7, 9, 'GOOD', SYSTIMESTAMP);
