INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '케익이 맛있어요. 서비스로 주시는 쿠키가 맛있어서 한 통 사왔는데 순식간에 먹어버렸어요.  여러가지 맛이 섞여있는게 있어서 좋습니다', 74, 14, 'GOOD', SYSTIMESTAMP);
