INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '*홍대 부근 최고의 카페* 알만한 사람들이라면 다 아는 디저트 맛집!!!!! 케이크 최고봉!!!!!!! 🍰🍰🍰🧁🧁🧁🥮🥮🎂🎂🎂🍪🍪🍪🍮🍮🍮 1번 와서 조각케이크 등을 먹는다면..... 무조건 당신응 또 오게 될겁니다....... (제 친구들 여기 N년째 단골 ㅎ) 사장님 오래오래 케이쿠 만들어쥬세요......💕 심지어 음료들도 맛있으무ㅜㅜ 내돈내산 홍보입니댜💭', 53, 16, 'GOOD', SYSTIMESTAMP);
