INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '지쳐서 쉬려고 들어간 카페인데, 너무 편하게 잘 쉬었습니다 !! 딸기요거트스무디와 같이 주신 쿠키가 너무 맛있어서 행복핑이 되어버린 사연..⌯''▾''⌯🩷', 126, 26, 'GOOD', SYSTIMESTAMP);
