INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '정말 정말 맛있는 디저트 맛집입니다🍓 사장님 갈 때마다 너무 친절하시고,,, 서비스도 챙겨주셔요ㅠㅠ 미니케이크인데 딸기가 엄청 엄청 들어있고 딸기 완전 달달해요!! 진짜 맛있어요..🤤 생일은 여기서 항상 케이크 사는 것 같아요! 제 지인에게 여태까지 3명한테 장쌤 디저트 선물로 준 적 있는데 하나같이 여기 이름 다 물어봤어요.. 나중에 꼭 가고싶다고 너무 맛있다면서 ㅋㅋㅎㅋㅎ글고 되게 좋은 재료 쓰시는 것 같다고도 했어요 진짜 맛있어요 !! 강추합니당 🩷', 75, 12, 'GOOD', SYSTIMESTAMP);
