INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '딸기프레지에와 다쿠아즈가 맛있대서 놀러왔습니다!! 평일 낮에는 사람이 많지 않고 조용히 대화를 즐길 수 있는 분위기였어요~ 딸기프레지에는 딸기가 듬뿍듬뿍 가득 들어있고 크림이 부드러워서 무난하게 맛있었구요 다쿠아즈는 총 세개(피스타치오베리, 헤이즐넛초코, 딸기) 포장해왔는데 서비스로 앙버터 다쿠아즈를 한개 더 얹어주셨습니당 개인적으로는 헤이즐넛초코가 맛있었어요 다음에 또 오고싶습니다~', 74, 12, 'GOOD', SYSTIMESTAMP);
