INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '홍대에서 제일 좋아하는 디저트 가게입니다. 수 많은 홍대/연남 지역 디저트 가게 중애서 최소 분기별로 한 번씩은 꼭 가서 먹고 포장해서 쟁여놓는 거 같아요. 다쿠아즈랑 프레지에 정멀 좋아합니다.', 41, 0, NULL, SYSTIMESTAMP);
