INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '디저트가 너무 맛있어요!! 피스타치오베리 다쿠아즈 best라서 먹어보자! 하고 먹었다가 너무 맛있어서 또 사먹었어요!! 커피랑도 잘 어울림ㅠ 케이크에 딸기도 너무 신선하고 맛이 있어서 놀랐어요!! 다음에도 다쿠아즈 또 먹을 거예요!!', 36, 4, 'GOOD', SYSTIMESTAMP);
