INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '❣️ [근처에 있다면 들러보길 추천] 오랫동안 홍대에서 버티고 있는 안정적인 디저트 맛집. 그냥 생크림만 쓴 게 아니라 커스터드~바닐라크림을 넣은 딸기프레지에가 대표메뉴로 고소한 맛을 자랑한다. 메뉴에 실패가 없는 홍대디저트 터줏대감으로 근처라면 고민 없이 들를 수 있어서 좋다. 늘 맛있습니다.', 18, 3, 'GOOD', SYSTIMESTAMP);
