INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '운동 끝나고 근처길래 들렀어요. 캬라멜 헤이즐넛 다쿠아즈랑 밀크티쇼콜라 구입했는데,  다쿠아즈는 종류별로 맛보고 싶을 정도로 한 입만에 바로 믿음(?)이 가는 퀄러티. 상대적으로 밀크티 쇼콜라는 제 입맛에 평범했어서 담엔 다른 메뉴로 도전 예정고요. 가게가 입구부터 아기자기 예쁘고, 고객응대도 친절하셔서 소중한 친구 데리고 또 가고 싶어졌어요.', 23, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '제가 지금 이십대 중반인데 고등학생 때부터 종종 왔었던 디저트가게예요. 여전히 맛있고 한결 같이 친절하신 사장님 덕에 정말 오랜만에 왔는데에도 기분 좋게 잘 쉬다가 가요☺️🍓💖', 31, 5, 'GOOD', SYSTIMESTAMP);
