INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '제가 디저트를 상당히 좋아하는 편인데 다쿠아즈는 처음 먹어봤거든요 다쿠아즈라는 녀석이 맛있는 건가요 아니면 여기가 특별히 맛난건가요? 진짜 너무 맛있게 뚝딱 해치웠습니다...,,,, 요즘 인스타그램 유행st 아니고 그냥 뚝심있는 원조 맛집 느낌이에요 꾸준히 방문하게 될듯합니다;;; 심지어 친절하시기까지 ㅠ 강추합니다', 57, 11, 'GOOD', SYSTIMESTAMP);
