INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '지난번에 먹었던 다쿠아즈가 맛있어서 친구 선물용으로 포장했어요 ㅎㅎ 다쿠아즈 3개+쿠키 하나 주문했는데 서비스도 챙겨주셔서 넘 감사했습니다 🫶', 22, 2, 'GOOD', SYSTIMESTAMP);
