INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '다쿠아즈가 특별해요! 딸기케익 맛집이라고 해서 왔는데 크기가 너무 작아서 아쉬웠어요ㅠ 그래서 하나 더 시켰어요..ㅋㅋㅋㅋㅋㅋㅋㅋ 미니케익으로 혼자 먹을 수 있을것 같아요 ㅋㅋㅋ 사장님 진짜 대박 최고 친절 하세요!!!!!', 26, 6, 'GOOD', SYSTIMESTAMP);
