INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '여기저기 리뷰 많이 찾아 보고 방문 했는데 프레지에는 정말 맛있었어요 그런데 아메리카노는 다른 저가형 프랜차이즈와 맛이 다를 게 없었습니다 서비스로 주신 쿠키가 진짜 맛있었어요! 다음에 홍대 가면 방문 할 정도로 맛있었습니다 다쿠아즈 맛집 이라길래 궁금했는데 가격이 안 적혀 있어서 결국 못 샀어요 ㅠㅠ', 41, 6, NULL, SYSTIMESTAMP);
