INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '커피랑 딸기프레지에 케이크랑 캬라멜헤이즐넛 다쿠아즈 주문했어요🍰 커피가 좀 쏟아져서 나와서 당황했지만 디저트는 맛있어요.. 같이 내주신 사브레쿠키도 버터향나서 맛있었어요☺️', 2, 9, 'GOOD', SYSTIMESTAMP);
