INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '단순히 크림으로 가득찬 케이크가 아니어서 맛있습니다. 바닐라빈이 콕콕 박힌 딸기 프레지이가 적당한 가격이라… 무난히 먹기 좋네요. 매장 테이블이 많은 건 아니라 혼자나 둘 정도 방문하기 좋습니다.', 43, 8, 'GOOD', SYSTIMESTAMP);
