INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '홍대에서 디저트 젤 맛있는 집,, 디저트 먹고 싶다? 카페 장쌤 오면 됨 충격,, ‼️ 서빙도 다 해주심 충격,,‼️ 디저트 짱이쁘게 잘라주심 다쿠아즈 너무 이쁘게 잘라주셔서 깔끔하게 먹을 수 있었잔아요... 감동이자나요.. 🥹 다쿠아즈 메뉴 짱 많은데 밤말차 달달구리 밤+씁쓸 녹차 무스 조합 도랏나용 다른 맛들도 빨리 깨고 싶구용,, 다른 디저트도 다 맛있어보임 가격도 합리적임,, 담백한 카페라떼가 디저트 쑥쑥 들어가게 함 아 사랑해요 벌써 또 먹고십다 🩷🩵', 86, 11, 'GOOD', SYSTIMESTAMP);
