INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '카페장쌤 몇년전에 알게된이후로 근처갈때마다 참새방앗간마냥 들리게되는데 언제가도 사장님 너무 친절하시고 맛있는 디저트들 맛이 떨어지는 일이 없어요 사장님 건강하게 오래 가게 부탁드립니다…✨✨ 오늘은 스노우볼이랑 산딸기잼쿠키 포장해왔는데 엳시 존맛…^^!!!', 81, 15, 'GOOD', SYSTIMESTAMP);
