INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '또또간집 오늘도 장쌤 디저트는 맛있다 매번 아메만 마시다가 딸기요거트스무디로 시켜봤는데 진짜 딸기 요플레 먹는 듯한 꾸덕하고 달달한 맛이다 다쿠아즈도 맛있는데 바닐라무스 케이크가 진짜 꾸덕한 바닐라에 바닥은 바삭한게 너무 잘어울린다', 22, 1, 'GOOD', SYSTIMESTAMP);
