INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '딸기프레지에 진짜 최고 맛도리.. 벌써 3번째 먹는데 먹을때마다 맛있어서 행복. 다쿠아즈도 아주 맛있지만 딸기프레지에 진짜 강추!!! 좋은 재료로 잘 만든 디저트라는게 먹으면 느껴져요.', 5, 5, 'GOOD', SYSTIMESTAMP);
