INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '엄청 부드럽고 맛있어서 먹기 시작하자마자 바로 다 먹었네요 ㅎㅎㅎ 크리스마스 당일 오픈시간 맞춰서 구매했구 10분정도 웨이팅 했던거 같습니다:) 사장님이 너무 바빠보여서 다른 디저트류 구매는 못 했만 다음에 재방문해서 도전해보려규요', 0, 4, 'GOOD', SYSTIMESTAMP);
