INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '프레지에 먹고 싶어서 오랜만에갔는데 역시나 다쿠아즈와 케이크는 여전히 맛있고 친절하시네요. 선물로 사간건데 다들 맛있게 먹었어요!', 26, 9, 'GOOD', SYSTIMESTAMP);
