INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '장쌤 is love… 장쌤 ㄴㄴ 장버지(장머니..? 사장님의 성별을 몰라요 죄송해요 일단 제가 갔을 땐 항상 남자 분이 계셨어요) yes yes 나중에 장쌤에서 다쿠아즈 30개 사서 쌓아놓고 먹어보고 싶어요.', 54, 15, NULL, SYSTIMESTAMP);
