INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '일주일에 한 번 정도 홍대에 가야하는데 그냥 지나칠 수 없는 곳 사장님도 너무 친절하시고 모든 종류가 맛있어요. 감동적인 맛입니다😊', 35, 10, 'GOOD', SYSTIMESTAMP);
