INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '샤인머스켓 미니케이크 19,000원 : 홀케이크 찾아보다가 홍대 근처에 유명한곳이길래 방문하게 되었어요🙌🏼 우선 홀케이크는 전화예약 해야하는데,, 전화가 너무 안되서 7번 만에 성공했습니다ㅠㅠ 리뷰들보면 곰돌이초를 서비스로 주시던데 전 케이크와 포크만 받아서 좀 아쉬웠어요🥲 케이크 생크림이 맛있어요~ 마스카포네 치즈와 적절하게 섞여서 가벼운듯 부드러운듯 하네요~ 주먹만한 미니 크기였지만 4인 가족 식후 디저트로 딱 좋았습니다 :) 다만, 생각보다 꽤 많이 달았고 케이크 안에도 슬라이스 된 머스켓이었다면 먹기 더 편했을 것 같아요. 통으로 들어있으니 자꾸 굴러다니려고 해서 불편했어요~ 이래저래 곡절이 조금 있었지만, 좋은 시간보낼 수 있었습니다☺️', 19, 8, NULL, SYSTIMESTAMP);
