INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '너무 맛있어서 케이크 테이크아웃도 시켰는데 덤으로 다쿠아즈도 주셨어요ㅜㅜ 짱 감동쓰.,, 자주 올게요 적게일하구 많이버세요🩷🩷🩷', 54, 11, 'GOOD', SYSTIMESTAMP);
