INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '몇년전에 영접한 다음부터 여기가 인생 다쿠아즈집이고 부모님도 좋아하셔서 근처올일있으면 무조건 박스로 사가고 인터넷주문으로도 몇번 시켜먹었는데요..항상 여자사장님?이 카운터보시다 오늘은 남자분이 카운터에 계셨는데 너무 불친절해서 앞으로는 안갈것같아요. 주문하려고 부르는데 바쁘신거 알지만 저에게 짜증낼 이유는 없는데 너무 짜증을 담아서 대답하시네요. 잘못한것도 없는데 말걸고 잠시만요 바빠서요!이러고 짜증내시는데 아..네 죄송합니다 이말이 나왔어요 ㅎㅎ', 58, 13, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '지금 한 10년 다닌 거 같은데 아직 안질렸어요. 100년 채워볼까 고민 중입니다. 다쿠아즈 퐁신하면서도 재료의 맛이 진해서 너무 좋은 티푸드이고, 각종 과자와 케이크도 사랑입니다. 요즘 물가에 가격도 합리적이에요! 쿠키도 찐하니 맛나니 꼭 드셔보세요 바닐라디아망 특히 추천!!', 24, 0, 'GOOD', SYSTIMESTAMP);
