INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '맛도 맛있는데 사장님이 매우 친절하셨습니다. 서비스 쿠키 뿐만이 아니라 1월 1일에 방문해서 그런가 2024초도 주셨어요! 그리고 화장실 깨끗하고 쾌적합니다. 온수도 잘 나와요.', 32, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '디저트가 이렇게 다양한데 전부 너무 맛있다 사실 장쌤 최애는 쿠키 방문할 때 마다 포장해간다 여유로운 공간도 좋고 사장님도 너무 친절하시다', 50, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '케이크 달지도 않고 느끼하지도 않고 너무너무 맛있어용 ㅜㅜ 그리고 다쿠아즈도 진짜…너무 맛있어요 사장님 너무 친절하시고 서비스도 감사합니당 ㅜ🥹❤️💖', 15, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '매년 놓칠 수 없는 빼빼로데이시즌의 장쌤 빼빼로!! 매해 경쟁이 치열해져서 힘들어요 ㅠㅠㅠ 흑 하지만 포기할 수 없는맛! 내돈내먹용으로 구입했어용 넘 맛있음 ㅠㅠㅜㅜ 내년 빼빼로데이 또 기다려봅니다💜', 30, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '깜빡하고 사진을 못 찍었네요 ㅠ_ㅠ 원래는 뚱빼로 사러 갔던 건데 시즌이 지나서 못 구매했지만 😭 바나나푸딩이랑 초코바나나케이크 구매해와서 남자친구랑 나눠먹었어요! 왜 디저트 맛집이라고 하는지 알 것 같은 꿀맛이었습니당.. 😆 뚱빼로도 서비스로 두 개 챙겨주셔서 맛나게 잘 먹었어요 ㅎㅎ 다음엔 다쿠아즈도 먹으러 가봐야겠어요!', 41, 4, 'GOOD', SYSTIMESTAMP);
