INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '몇 번 갔는데 리뷰는 처음이네요!! 같이 일하는 친구랑 일주일에 두 번 정도 아침 택배를 보내러 가는데 이 카페 좋아한다고 해서 같이 처음 가 보게 됐다가 두어 번 가 보고 이번엔 혼자 갔어용 ㅎ.ㅎ 늘 디저트 더 챙겨 주시려는 사장님... 너무 친절하시구 감사합니다! 😊 매번 라떼 종류 마시다가 24시간 냉침? 이라는 설명을 보고 궁금해서 밀크티 처음 먹어 봤는데 진짜 맛있네요!! 🥹 가끔 대충 만드는 곳들 밀크티 마시면 속이 불편해지는데 너무 맛있어요 ㅠ 얼음컵도 챙겨 주셔서 일하면서 시원하게 당 충전합니다!!! 항상 테이크아웃이라 카페에서 먹어 보지는 못했는데 조용하고 청결한 분위기라 혼커피 하실 분들에게도 좋을 것 같아용 🥹👍🏻', 0, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
