INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '딸기요거트스무디와 섞어디아망!! (요거트스무디 원래 양 저 정도 아니고 먹으면서 와서 조금 줄어든 거임 ㅋㅋ) 스무디는 처음 먹었는데 역시 다 맛있습니당~~~ 대충 만들어서 주스 같이 호로록 나오는 다른 카페들과 다르게 진짜 요거트 마시는 느낌?! 조금 꾸덕함이 살아 있는 스무디라 더 신선한 느낌이었어용 🥹👍🏻 그리고 사실 스무디만 시키고 디저트 구경하다가 쿠키가 너무 맛있어 보여서 ㅋㅋㅋㅋㅋㅋㅋ 추가로 주문해서 시킨 디아망••• 달달하이 계속 손이 가네용 🥹 담엔 꼭 바나나푸딩 먹어 봐야징 그리고 여수 다녀오셨다고 여수에서 사 오신 초코파이를 이렇게... 주시는 사장님이 어디 있어요!!!! 😭😭😭 진짜 감동의 쓰나미 ㅠㅠ 잘 먹을게요 사댱님 늘 감사합니당 💖💖', 112, 19, 'GOOD', SYSTIMESTAMP);
