INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '제가 정말 좋아하는 얼그레이 다쿠아즈 사러 갔어요 얼그레이 말고도 다른 7개 샀어요 여러 개 사서 그런지 고민하던 다른 하나는 사장님께서 서비스로 주셨어요 🥹 잘 먹었습니다 얼그레이는 겉 빵 부분에 얼그레이가, 밤말차랑 제주말차는 겉 빵 부분에 녹차가 들어가있어서 다른 다쿠아즈보다 맛있어요 그래서 요 세 개가 저의 최애입니다 !!! 짱맛 짱맛 배송도 되더라구요 나중에 이용해보려구요 !!', 23, 10, 'GOOD', SYSTIMESTAMP);
