INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '늦은시간가서 매장서 먹진못했지만 친절하게 응대해주셔서 다쿠아즈 포장해와서 먹었는데 너무 맛도 진하고 맛있어요 ㅎㅎ 담엔 매장가서 케이크도 먹어보려구요 ㅎㅎ최고', 76, 17, 'GOOD', SYSTIMESTAMP);
