INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '토요일에 사 욌고 일요일 아침 식사후 가족들과 차르루마시기 위해 준비하다가 제주말차 다쿠아즈가 없어서 놀랐네요 다쿠아즈를 제주말차, 앙버터, 망고치즈, 딸기를 주문했는데 제주말차는 없고 라즈베리같은 저 다쿠아즈가 들어서 황당했습니다 제주말차 다쿠아즈를 못 먹어봤는데 매우 아쉬운데 바꿔 넣은 다쿠아즈는 신맛이 강했지만 달콤한 밀크티랑 먹으니 괜찮았습니다 딸기 디쿠아즈가 맛있었습니다 쿠키도 부드럽고 맛있었습니다 다음에는 포장 주문시 신경써 주시면 좋겠습니다', 89, 11, NULL, SYSTIMESTAMP);
