INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '일하기 전에 자주 들리는카페인데 진짜 디저트 맛집입니당…디저트 종류도 많은데 다 맛있어요ㅠㅠ 특히 제 최애 바나나 푸딩이랑 애플 쿠키 넘 맛있어요!!!! (푸딩도 맛있고 다쿠아즈도 맛있고…다 최고 )가게도 청결하고 사장님도 엄청 친절하십니당✨', 1, 6, 'GOOD', SYSTIMESTAMP);
