INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '다쿠아즈 맛집이라는 소문 듣고 갔는데 정말 다 맛있어요! 주말이라 바쁨에도 신경써주신다는 느낌도 들고 포장주문을 할 때 소요시간 물어보고 보냉 포장도 해주셔서 걱정없이 귀가 후 먹었답니다^^ 산딸기에이드는 인공적인 단 맛없이 딱 과일의 새콤하고 향긋해서 넘 좋았고, 다쿠아즈 안에 과일도 신선하고 개인적으로 바닐라라떼 취저 당했어요^^', 130, 21, 'GOOD', SYSTIMESTAMP);
