INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '아 ㅠㅠ 사진 찍어서 올리고 싶었는데 맛잇어서 먹느라 오늘도 사진을 못 찍었네요 헝 ㅠㅠ 다쿠아즈 진짜 너무 너무 맛잇어요!!!! 특히 5번 이상 간 사람으로서 추천하자면 와인무화과랑 베리앤피스타치오 제일 맛잇어욤!', 1, 0, 'GOOD', SYSTIMESTAMP);
