INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '디저트만 판지 어느덧 10년.. 국내 다쿠아즈 맛집은 카페장쌤이 유일합니다. 항상 맛있는 다쿠아즈 만들어주셔서 감사해요 사장님~~~', 22, 0, 'GOOD', SYSTIMESTAMP);
