INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '홍대 카페 검색해서 왔는데 예쁘고 맛있는 냄새로 가득하고 소파도 푹신하고 사장님도 친절해서 좋았어요! 디저트 너무 많아서 고민됐는데 상큼한 딸기가 먹고 싶어 시켰고요 서비스로 미니 크키도 주셨는데 그것도 맛있어서 포장해 가고 싶었어요! 다음에 또 가고싶음!!', 108, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '멀리서 방문했는데 사장님께서 정말 튼튼하고 안녹게끔 포장해주셔서 밤에 집 도착했을 때까지도 아이스팩이 안녹았더라고요 사장님 정말 친절하시고 케익도 너무너무너무너무 맛있었습니다 유명한 이유가 있는 곳이였어요 포장도 잘해주셔서 감사해요 거리가 멀지만 또 재방문 하고싶은 카페입니다! 다음에 갈때는 안먹어본 메뉴들로 한바가지 사오고싶어요', 66, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '리뷰보고 방문했는데 여기 뭐가 제일 잘나가요? 라는 질문에 저희 다 잘나가는데요? 라는대답... 조각케잌주문하고 커피도 주문하는데 짜증나듯 대답이없어서 포장하는데 너무 화가나더라구요 사장님 조금만 신경써서 손님 대해주세요 언제까지 손님이 많으실까요', 49, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '홍대갈 일 있을때마다 하나씩 사옵니다 너무 맛있어요 ㅠㅠ 사장님이 친절하셔서 서비스도 주시고 ㅠㅠㅠ 갈때마다 갈거에요!!!!!!! 다쿠아즈도 맛있어용', 31, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '정말정말 좋아하는 곳이에요. 친절하시고 종류도 많고 가격도 나쁘지 않은 편! 통에 든 쿠키가 특히 가격이 착해서 종종 사와요. 선물용으로도 너무 좋고 항상 친절하셔서 잘 머물다 옵니다💕', 45, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '디저트맛집 맞네요..!! 📍유명한 딸기 프레지에는 바닐라빈 콕콕 박혀있는 크림이 산뜻하고 딸기도 달아요. 무엇보다 비쥬얼 너무 이뻐요🥰 📍쑥곶감 다쿠아즈는 쑥향이 진하고 곶감도 쫄깃하니 맛있어요! 같이나온 디아망도 사르르 녹고 디저트 다 맛있어요💕 📍포장해온 바나나푸딩도 냉장고에 차갑게해서 먹으니 짱맛이네요😭 카페 분위기도 예쁘고 편안했어요^^', 97, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '오늘도 일개 직원 둘에게 힘이 되는 커피와 디저트... 오늘은 딸기 초콜릿을! 🥹💗 항상 맛있는 디저트랑 커피 내려 주셔서 너무 감사합니다!!😊💖 험난한 홍대에서 장쌤 커피로 버텨요•••', 21, 7, 'GOOD', SYSTIMESTAMP);
