INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '평소 쿠키류 잘 안 먹는데 선물 받은 쿠키가 너무 맛있어서 지인한테 물어 찾아간 곳이었어요. 선물용으로 구입만 했는데, 서비스도 주시고! 카페도 아기자기 예뻐서 다음엔 여유롭게 먹고 가고 싶어요.', 29, 7, NULL, SYSTIMESTAMP);
