INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '가지고오면서 살짝 흔들려서 딸기가 자리이탈했네요 ㅠㅠ 항상 딸기케이크  필요하면 1순위입니다. 늘 바빠서 주문해도된다고할때까지 기다리는데.. 저날은 알바생 혼자있어서 그런지 오래기다렸습니다. ㅠ.. 빤히쳐다보고 자리치우고..친구들이랑 인사하고.. 대기가 저혼자라서 그러셨나봐요', 82, 18, NULL, SYSTIMESTAMP);
