INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '디저트 진짜 맛있고, 싱싱하고 사장님도 왕친절하시다! 푸딩 안먹는데 친구가 사다줘서 한입먹고 여기 또 가서 직접 사옴!!! 다쿠아즈도 너무 달지 않고 종류가 다양해서 넘 좋음!', 20, 6, 'GOOD', SYSTIMESTAMP);
