INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '오랜만에 푸딩이 너무 먹고 싶어서 갔는데 4개 밖에 안남았대서 쓸어왔숨뎌.,., 푸딩 못 산김에 담다가 많아졌는데 여차저차 회사 사람들 나눠주니까 제 몫이 줄어들어버렸네여😢 그래도 다들 맛있다 하셔서 다녀온 보람이 있숨다.,., 디저트 존맛이니 다들 츄라이츄라이~ 푸딩빨 떨어지면 재방문 하겠숨댜~!', 82, 12, NULL, SYSTIMESTAMP);
