INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '우주1등 딸기프레지에~~~~❤️🍓 미니는 혼자서도 쌉가능일 것 같아요. 어쩜 느끼하지도 않고 부드럽고 달달하고 딸기도 얼마나 달고 실하고 많이 가득 들었는지 한입한입 딸기가 씹혀요 ㅠㅠ 너무 맛있어 딸기철 가기전에 1일1장쌤프레지에 먹어줘야하는데 매일 올 수 없는 거리라 아쉽습니다 🤣 다쿠아즈는 말모~~ 쿠키들 밤말차케이크 레몬마들렌~~ 다 존맛이에요. 심지어 커피랑 음료도 맛남. 딸기라떼도 죵맛❤️💜💛', 41, 2, 'GOOD', SYSTIMESTAMP);
