INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '와 진짜 내가 원하는 디져트맛!! 다 맛있다 커피도 케익도 💕 사장님은 왜 말랐는지 이해가 안됨 나만 맛나게 먹고 살쪄서 갑니다', 9, 7, 'GOOD', SYSTIMESTAMP);
