INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '두명이서 왔는데 푸딩 하나당 스푼 두개씩 주시구 밀크티 병 하나 시켰는데 얼음컵 두개 주시는 사장님의 센스에 감동 받았어요 자몽얼그레이푸딩 얼그레이 향이 찐하고 맛있고 우유푸딩도 찐하구 맛있어요 최고', 26, 3, 'GOOD', SYSTIMESTAMP);
