INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '다쿠아즈 도장깨기 하는 중이에요! 지금까지 딸기 / 피스타치오베리 / 카라멜헤이즐넛 / 얼그레이 /  밤말차 먹어봤는데 모두 다 맛있었어료!! 진하고 맛있어요~~!! 홍대 올 일 있으면 꼭 들르는 곳!', 116, 19, 'GOOD', SYSTIMESTAMP);
