INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '딸기케이크가 정말 압권입니다 부모님 생신이신데 케이크를 별로 안 좋아하셔서 고르고 골랐는데 오늘 다 먹어버렸어요 케이크 안에도 슬라이스가 아닌 통딸기가 들어 있어 부모님이 많이 좋아하셨습니다 바닐라빈이 콕콕 박힌 크림도 정말 맛있었습니다 케이크 사고 돈이 안 아까운 건 처음이었습니다', 46, 6, 'GOOD', SYSTIMESTAMP);
