INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '프리지에 케이크 먹고싶어서 카페장쌤가서 커피랑 같이 먹었는데 퐁신하고 적당히 단맛에 딸기가 큼지막하게 들어있어서 정말 맛있게 먹었어요! 모양도 너무 이쁘구 맛있구 사장님 넘 친절하셔서 좋았어요!', 41, 9, 'GOOD', SYSTIMESTAMP);
