INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '장쌤 딸기프레지에 말해무엇! 정말 맛있어요. 아는 맛이 더 무섭습니다. 겨울에 장쌤 딸기프레지에 꼭 먹어야해요. 시즌에 꼭 먹어야할 메뉴!', 35, 6, 'GOOD', SYSTIMESTAMP);
