INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '모든 메뉴 디저트들이 너무 너무 맛있고 사장님이 넘 친절하세요!! 이번에 말차 케이크 먹었는데 맛은 달콤쌉싸름한 찐한 말차와 달달한 밤의 조화가 너무 잘 어울려서 엄청 맛있어요!!!', 9, 6, 'GOOD', SYSTIMESTAMP);
