INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '간간히 가는데 항상 친절하시고 디저트 먹을 때마다 감탄하게 됩니다 딸기 프레지에 특히 맛있어요! 맨날 조각으로 먹다가 저번에 미니로 사봤는데 친구랑 둘이서 순삭했습니다', 15, 3, 'GOOD', SYSTIMESTAMP);
