INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '모든 메뉴가 다 맛있어서 항상 예약해서 구매하고 그랬는데 홍대 와ㅆ다가 생각나서 남자친구 부모님이랑 같이 먹으라고 샀어요! 다들 맛있다고 하셔서 괜히 뿌듯한ㅎㅎㅎ 역시 카페장쌤!!👍🏼 다음에 또 방문하겠습니다ㅎㅎ', 40, 5, 'GOOD', SYSTIMESTAMP);
