INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '딸기 프리지에는 장쌤이 서울에서는 최고 탑 🍓🍰 👍저는 벌써 9년째 이곳을 이용중입니다. 처음에 먹었을때 부터 지금까지 변하지 않은 맛 사랑입니다.', 50, 0, 'GOOD', SYSTIMESTAMP);
