INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '직원분들이 손님 응대에 조금더 신경써주셨으면좋겠어요 손님이 그렇게 줄 서있는데 설거지하고있는거 충격... 파워 i 이신분들은 걍 계속 기다리고있음 ㅠㅠ 홍대갈때마다 사먹는곳인데 처음으로 실망했어요 근데 여전히 맛있긴해요', 27, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '다쿠아즈 진짜 짱맛있어요σ̴̶̷̤ .̫ σ̴̶̷̤ 얼그레이랑 밤말차 바닐라 다쿠아즈 완전 맛있었습니다. 굿굿ㅋ 사장님 왕친절 하셔서 기분 너무 좋았어요. 담에 또 먹으러 갈거에요 짱! (〃⌒▽⌒〃)ゝ', 102, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '가려던 카페가 휴무날이라 우연히 찾게 된 가게인데 그후 벌써 두 번이나 더 방문했어요!!! 맨 처음에 친구 생일로 조각케익 두 조각을 사줬는데 친구 엄마도 만족하셨다길래 부모님 결혼기념일 홀케익도 주문했어요 ㅎㅎ 단호박치즈케익 정성스럽게 맛있는 맛이에요 ! 밀크티 쇼콜라도 얼그레이 은근 진하고 맛있었습니다 밤말차케익?은 통밤이 들어있는데도 생각보다 밤맛이 별로 안 느껴지고 말차 맛만 느껴져서 좀 아쉬웠어요 !~~ 저땐 밤 디저트가 너무 먹고싶었는데 말차 맛만 강한 느낌이더라고요 ㅜ 그렇지만 장쌤으로 추정되는 남자 사장님 갈 때마다 너무 친절하시고, 디저트 종류도 많고 가게도 아기자기해요 🤍 디저트 웬만한 거 다 좋아하는데 다큐아즈를 즐겨먹는 편이 아닙니다 근데 이 집은 맛도리더라고용,, 자주 올게용~!', 95, 24, 'GOOD', SYSTIMESTAMP);
