INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '장쌤 디저트 넘 좋아해서 수업까지 들은 학생이자 손님입니다☺️ 늘 양질의 디저트 만들어 주셔서 빵순이는 행복해요! ㅋㅋ 아, 그리고 가끔 아무 말 없이 서비스 넣어 주셔서... 나중에 확인하는 바람에 인사를 제대로 못 드렸어요🥹 맛있게 잘 먹었습니다~ 고맙습니다! 오래 오래 과자 만들어 주세요🫶🏻', 9, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '넘 멀어서 다쿠아즈 택배로만 주문해 먹다가 근처에 볼일있어서  드디어 매장에 가봤어요 진짜 다 사오고 싶었는데...  다쿠아즈는 맛있는거 알고 있었고 특히 프레지에 이건 홀로 드세요 정말 맛있어요 바나나푸딩도 진짜 최고! 바나나가 엄청 쫀득해요 밀푀유는 품절되어서 아쉬웠어요 멀어도 프레지에 때문에 또 갈거같아요', 18, 3, 'GOOD', SYSTIMESTAMP);
