INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '다쿠아즈가 이제껏 먹어왔던 곳과 다르게 완전 가볍고 퐁신퐁신한 식감이네요. 막 달지도 않고 조화로워서 맛있게 먹었습니다:) 딸기 프레지에는 바닐라 크림이 진짜 깔끔하고 부드럽고,,,여기는 크림이 정말 찐입니다!!! 그리고 딸기가 통으로 진짜 많이 들어가있어서 크림이랑 같이 먹으면 감동 한바가지,,🧡 다음번에는 푸딩이랑 조각케이크 맛보러 가야겠어요~!', 15, 6, 'GOOD', SYSTIMESTAMP);
