INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '카페가 아늑하고 다쿠아즈 맛집 입니다! 다쿠아즈 너무 맛있어요. 딸기요거트스무디도 찐하고 맛있네요. 망고치즈 다쿠아즈 맛있어요.', 62, 11, 'GOOD', SYSTIMESTAMP);
