INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '케익도 너무 맛나고 서비스로 주신 다쿠아즈 미쳤네요. 여기 커피마시러 꼭 다시 갈꺼에오. 사장님도 친절하시고 케익 퀄리티 무엇 이렇게 빵보다 딸기가 많은 케익 처음 입니다', 41, 1, 'GOOD', SYSTIMESTAMP);
