INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '그동안 계속 가보고싶던 곳이에요!!! 커피도맛있고 특히 다쿠아즈 빵(?)부분 진짜 부드럽고 맛있어요 ㅎㅎ 안에 필링도 맛있어요💘 그 중에서 피스타치오베리 다쿠아즈 jmtgr~ 서비스로 주신 쿠키도 짱 마싯음 ㅎㅎ', 48, 7, 'GOOD', SYSTIMESTAMP);
