INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '밥먹으러왓다가 카페검색 햇님 언니가 다쿠아즈 맛집이라 소개햇던 곳이라 와봣어요 막 여기까지 와서 먹어야되! 이런 맛은 아니엿지만 맛없는 것도 아닌 근데 그릇이 조금 사진찍기에도그렇고 보기에도 예쁘진 않네요 ㅋㅋㅋ 멜라민? 그릇 인거같기도 ㅋ 그릇도 중요하구나를 느낀ㅋㅋㅋㅋ', 110, 20, NULL, SYSTIMESTAMP);
