INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '다쿠아즈를 별로 안좋아하는데 리뷰에 다 다쿠아즈 칭찬이여서 한번 먹어봤는데 너무 맛있었어요! 딸기푸딩은 밑에 깔려있는 소스가 살짝 달았고 망고는 딱 적절하게 맛있었습니다! 디아망이랑 카라멜애플쿠키가 진짜 취항저격이였어용 다음에 홍대가면 또 사올겁니당 🥺❤️', 10, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '장사장님께서 반갑게 맞이해주시는 2층카페입니다. 다쿠아즈 종류들이 매우다양해서 고르는데 오래걸렸는데요ㅎ 장난감가게에 어린아이마냥 즐거운과정이었습니다! 주중 1시반 수량은 넉넉했고 복숭아메뉴들은 많이나간상태였습니다. 따로 하나 덤으로챙겨주신 다쿠아즈도 감사히잘먹었습니다! 시식평: 일단, 다쿠아즈를 안좋아하는 사람임을 밝히며.. 먹어본 다쿠아즈중 가장 부드럽고 퐁신한 식감입니다. 많이달지않고 재료본연의 맛들을 정직하게 구현해낸 필링들이 맛있습니다. 복숭아 티라미수는 심플하고 라이트한 편이었고, 체리피스타치오푸딩은 생체리와 푸딩텍스쳐가 산뜻했지만 피스타치오페이스트맛이 조금 헤비한편입니다. 확실히 다른디저트류들보단 다쿠아즈에서 사장님의 철학을 더 엿볼수있는것 같습니다.', 11, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '빈속에 다쿠아즈 먹으러 영하3도를 뚫고 왔는데 너무 맛있어요.. 여태까지 내가 먹어왔던 다쿠아즈는 머란 말이지..🥹 밀크티쇼콜라케이크도 얼그레이가 와장창 들어가있음 걍 끽 먹어야 아는 맛😇🔫', 66, 15, 'GOOD', SYSTIMESTAMP);
