INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '너무너무 맛있어요 여기 케이크랑 푸딩은 매일 먹어도 안질리는 맛 ㅠㅠㅠㅠ 바닐라빈 옴청 많이 들어가있구 크림에서도 바닐라 향 대박이에요!!!! 포장해왔는데 안흔들리게 엄청 꼼꼼하게 해주셔서 감사해요❤️❤️', 59, 12, 'GOOD', SYSTIMESTAMP);
