INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '진짜 최고 기분 울적하고 위로받고 싶을 때 카페장쌤가서 더블바닐라파운드케이크를 드세요 차원이 다른 파운드..그리고 그 위에 크림..글고 항상 넘나 친절하신 사장님.. 홍대카페하면 카페장쌤임 진짜 오래오래 장사해주세요..plz..', 21, 8, 'GOOD', SYSTIMESTAMP);
