INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '커피도 너무 맛있었고 날이 너무 더워서 한잔 더 마시려했는데 리필도 된다하셔서 (유료) 너무 좋았습니다 케이크 미니가 생각보다 작아서 조금 놀랐지만 안에 체리 양 듬뿍들어간거보고 좋았어요! 이미 유명한 곳이지만 추천❤️❤️', 30, 7, 'GOOD', SYSTIMESTAMP);
