INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '바닐라빈 크림라떼 크림 지인짜 맛있어요… 🤤 캐러멜밀푀유는 먹다 보면 감성은 없어지지만 맛은 있습니다 근데 어어엄청 달아요 ㅎㅎ 저는 단거 좋아해서 좋았어요!! 다쿠아즈가 진짜 맛있구 왜 다쿠아즈 맛집으로 소문난 건지 알 것 같아요… 왕맛있네요 🤤 넘 맛있어서 나갈 때 두 개 더 포장했어요 서비스로 주신 과자도 맛나게 먹었습니다!! 주말이아 테이블이 엄청 꽉 차서 조용한 분위기에서 대화하긴 쬐금 어려워용! 하지만 음료 디저트가 너무 맛있어서 재방문 의사 100%입니당… 👍', 22, 5, 'GOOD', SYSTIMESTAMP);
