INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '진짜 퇴근하고나서 더블바닐라파운드 사서 집가면 하루 피로가 다 풀려요♡ 다른 것도 다 너무 맛있어서 매번 행복한 고민이 되는 최애가게><', 44, 10, 'GOOD', SYSTIMESTAMP);
