INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '첫 방문이였는데 여러가지 디저트 종류가 많고 커피나 음료 종류도 맛있었어요 특히 다쿠아즈가 너무너무 맛있어서 꼭 하나씩 드셔보시는거 추천하고, 사장님이 서비스를 많이 주셔서 넘넘 감동했어요 😭❤️ +) 안에 내부도 생각보다 넓고 분위기가 좋아서 작을까봐 걱정하시는 분들, 맛있는 디저트 드시고 싶으신 분들 있다면 추천합니다~! 😆👍', 108, 19, 'GOOD', SYSTIMESTAMP);
