INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '맛있고 친절하시고 짱짱 서비스 쿠키도 넘 맛있고 커피도 맛있어용 디저트는 뭐 말할것도 없죠!!! 얼마전 다른 카페에서 너~무 디저트가 달아서 정말 극강의 단맛으로..놀란 혀를 달래러 디저트 찐맛집을 다시 찾았답니다. 결과는 대만족~~ 다만 녹차덕후로써 녹차''만'' 들어간 디저트가 다시 부활했으면 하는 바람이 있습니다..ㅎㅎ', 3, 3, 'GOOD', SYSTIMESTAMP);
