INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '너무 친절해서 감동받은 집입니다! 잠깐 포스기 오류 때문에 대기하고 있었는데 서비스로 쿠키를 챙겨주시더라구요?! 감동 받았습니다 🤍', 41, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '쑥곶감다쿠아즈 특이하고 맛있었어요 복슝아우유는 좀... ㅎㅎ 디저트도 많고 좋아요! 매장 내뷰 자리는 다소 협소하고 주차공간이 없는건 알고 가셔요', 47, 10, 'GOOD', SYSTIMESTAMP);
