INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '디저트 진짜 맛있어요... 더블바닐라파운드 꼭 드셔보세요... 레몬요거트케이크도 제발 드셔주세요... 피칸파이... 견과류 싫어하는 저도 맛있게 먹었습니다.... 다쿠아즈 말해 뭐해요.. 무조건 고입니다... 그냥 다 맛있으니 다 드세요.... 밀크티도 맛있구요.. 근데 디저트 계속 먹는데는 역시 아.아.가 짱...(개인 취향입니다) 그리고 우유 푸딩 사와서 먹었는데... 푸딩마저 맛있어요....💛 사장님 수원점도 내주세요....🥺', 9, 6, 'GOOD', SYSTIMESTAMP);
