INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '다쿠아즈 맛집으로 알고 있었는데 케이크랑 쿠키류도 많더라구요~ 복숭아티라미수 맛있었어요 이 계절에만 먹을 수 있는 특별한 디저트네요🧡 기본으로 주시는 쿠키와 커피맛도 훌륭합니다!', 75, 12, 'GOOD', SYSTIMESTAMP);
