INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '사장님 오래해주세요. 이미 자주갔지만 갈때마다 도른맛...스노우볼,산딸기잼쿠키는 말할것도 없이 부드럽고 적당히 꾸덕하고..진짜 최고. 이번이 복숭아요거트. 카시스치즈.피스타치오쉭세.카야코코넛 다쿠아즈 리뉴얼된거 먹어봤는데 존맛 개ㅐㅐ존맛 정말 친절하시구 항상 맛난다쿠아즈 감사합니다♡♡', 101, 21, 'GOOD', SYSTIMESTAMP);
