INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '케이크가 먹고싶어서 왔는데 종류가 다양해서 좋았어요! 케이크뿐만 아니라 두툼한 다쿠아즈 그 외 디저트도 엄청 많아요!! 그리고 사장님께서 엄청 친절하셔서 좋았어요~~', 11, 10, 'GOOD', SYSTIMESTAMP);
