INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '진짜 장쌤 애정애정합니다ㅜㅜ 디저트는 말모말모 너무 맛있구요 사장님도 너무 친절하세요.. 단점이라면 탐나는 메뉴가 많아서 제 통장이 위험하달까요?ㅎㅎ 진짜 갈때마다 만만족합니다👐 매번 서비스 쿠키나 초콜릿 너무너무 감사합니다ㅠㅠ♡', 115, 22, 'GOOD', SYSTIMESTAMP);
