INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '갈때마다 너무친절하셔서 기분이좋아서 리뷰남겨요다쿠아즈사면 서비스로 한개 더 주시기도 하고 생각지못한 서비스에 하루가 기분이좋네요^^ 맛도 맛있고 프레지에도 맛있구 다른 쿠키들도 다 너무맛있어요 감사합니다👍❤', 1, 0, 'GOOD', SYSTIMESTAMP);
