INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '특별한 메뉴들도 많고, 맛있어요! 맛있어 보이는것들 주문하다보면 금액이ㅠㅠ 갈 때 마다 친절하셔서 좋아요!! 언제나 감사합니다~!', 113, 19, 'GOOD', SYSTIMESTAMP);
