INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '다쿠아즈 비롯 디저트들의 재료 맛이 살아있고 맛있다라고 느껴지고 개인적으론 단 편이에요😎(좋은 의미) 맛 없었던 메뉴 없었던 디저트의 장인😙👍🏻👍🏻👍🏻👍🏻👍🏻 그리고 인스타보면 사장님 남매분이 친절하고 마인드가 좋다는 생각이 들어요! 가게내부도 뭔가 아늑한 느낌🤔💕 세 번째 방문💛🧡❤', 28, 5, 'GOOD', SYSTIMESTAMP);
