INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '장쌤때문에 유명해진 이곳이 알바때문에 기분 나빠서 영수증리뷰 쓰게되네요. 진열되있는 다쿠아즈 종류에 대해 질문에 아주 무관심과 짜증이 손님을 다시는 가고싶지 않은곳으로 만듭니다. 빼빼로데이나 특별한 이벤트때 줄서서 살때도 이렇게 불친절 하지 않았는데 오늘 최악을 경험하고 맛있는 디저트 먹으러 갔다 기분만 상하고 왔네요. 장쌤이 일군 일터를 알바때문에 망치지 않으시길.', 38, 8, 'BAD', SYSTIMESTAMP);
