INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '다쿠아즈 먹을수록 생각나는 맛이에요. 특이 카야코코넛 진짜 맛있어요!!! 카페에서 먹으니 다쿠아즈 잘라주시고.. 먹기 참 좋았어요. 바닐라 무스도 괜찮았습니다. 커피가 약간 써서 단 디저트랑 먹기 좋았네요. 서비스로 주신 쿠키는 맛은 있는데 달아서 좀 아쉬웠어용 ㅠ 그래도 전체적으로 만족입니다 ㅎ', 5, 0, 'GOOD', SYSTIMESTAMP);
