INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '미니프레지에 눈물나게 맛있어요 ㅠㅠ 자주 먹고 싶은데 시간맞춰 가기가 쉽지 않네요. 딸기도 신선하고 달콤하고 크림이랑 시트랑 너무 부드럽고 맛있어요. 1인1케이크 완전 가능~ 😆👍🏻', 1, 2, 'GOOD', SYSTIMESTAMP);
