INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '사장님 진짜 매우 최고 친절하시고 딸기 프리지에랑 바스크치즈케이크 너러어어ㅓㅓ무 맛있어요 사장님 대성하세요 하지만 유명해지진 마세요… 나만 알고시퍼요…😊😊😊', 48, 4, 'GOOD', SYSTIMESTAMP);
