INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '일전에 다쿠아즈, 쿠키 먹고 여긴 찐이다 하던 와중에 딸기제철에 딸기프레지에 판매 정보를 접하고 ㄱㄱ 먹어보고 싶었던 다쿠아즈와 함께 구입🤗 주말동안 먹어야지😚 뿌듯허다...💞', 42, 9, 'GOOD', SYSTIMESTAMP);
