INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '미니프레지에 딸기 미니케이크를 구입했는데 정말 맛있었어여 딸기는 달콤하고 생크림은 느끼하지않고 달지않고 빵은 촉촉하고 친구생일이라 산건데 내가 다먹음.', 78, 14, 'GOOD', SYSTIMESTAMP);
