INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '인스타로만 보다가 갔는데 다쿠아즈 넘 맛있어요 순삭했어요  또 먹꼬 싶어요 포장해 가는데 친절 응대 또한 좋았어요 왜 그렇게 다쿠아즈 했나 했더니진심 넘 맛있어요 다른맛도 먹어봐야겠어요', 81, 15, 'GOOD', SYSTIMESTAMP);
