INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '우연히 인스타에서 발견하게된 다쿠아즈 맛집입니다. 다쿠아즈빼빼로 먹어보고싶어서 간건데 품절이고.. ㅠ 나오는데 시간 얼마나 걸리는 지 알 수 없다하여 3시간정도 기다렸지만.. 결국 먹어보지 못했네요. 그냥 다쿠아즈는 카야코코넛이 진짜 맛있었네요. 래밍턴.. 먹어볼수 있겠죠?', 78, 14, NULL, SYSTIMESTAMP);
