INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '연말이라 손님 엄청 많고 바쁜데도 사장님 넘나 친절하신것.. 멀리서 굳이 사러 갔는데 찾는거 없으니까 비슷한 메뉴 서비스로 넣어주셔서 감동했어용😭 부자되세요 사장님', 26, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '푸딩 부드럽고 과일이 정말 신선해서 좋았어요! 다쿠아즈도 적당히 달고, 부드럽구 가격도 이정도면 나쁘진 않은 것 같구요 음료 시키까 미니쿠키 주셔서 좋았어요! 다쿠아즈가 조금만 더 쫀득하면 좋을 것 같은데.. 원래 이런건지는 잘 모르겠어요ㅎㅎ 무튼 디저트는 정말 맛있게 잘 먹었습니다~', 71, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '버터 쿠키가 맛있어요. 빼빼로를 버터쿠키로 만드시는데 그 식감이 기분 좋아 작년에 이어 올해도 사먹었어요. 코팅된 초콜렛도 맛있구요! 치즈쿠키 빼빼로가 전 가장 맘에 들었어요. 사장님도 친절하시고 좋습니다. 주력 메뉴인 다쿠아즈도 맛있습니다.', 73, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '서울에서 제일 좋아하는 디저트 카페^^ 오래전 단골인데 한동안 방문 못하다가 오랜만에 갔는데 여전히 사장님도 친절하시고 디저트들도 여전해서 반갑고 좋았어요 다쿠아즈 맛집으로 유명해졌지만 저는 카페장쌤 케이크가 젤 좋아요ㅎㅎㅎ 홍대에서 오래오래 영업해주셨으면 좋겠어요 ~~ 건강하세요', 5, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '여수에서 인스타보고 2년 전에 처음 가고 완전 반해서 남친 데려가고 친구들 데려가고 오늘 다시 남친이랑 같이 갘ㅅ다왔어요 ㅋㅋㅋ 5번 갔네여 홍대만 가면 저한텐 필수코스에요 밤말차케이크 너무 맛있어요 복숭아 티라미수도요 밀크티도 그렇게 단 편은 아니라 좋았습니당 너무 친절하세요 타지살아소 가는 횟수가 적지만 홍대갈 때마다 무조건 들리겠습니당>_<', 16, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '테이크아웃 했는데 보냉포장은 가격 추가 됩니다.  미리 알았다면 챙겨 갔을텐데 그나마 가까운 거리라 그냥 들고 왔어요. 좀 녹아서 냉장고에 뒀다 먹었습니다. 매장에서 많이들 드시고 계시더라고요. 담엔 보냉제를 챙겨가거나 매장에서 먹어야겠어요~', 41, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '왕왕 친절하시고  디저트류가 다 맛있어요 사실 디저트류에 집중되는 카페들은 커피가 실망스러울 때가 많은데 커피도 맛있어용!!!', 3, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 장쌤'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '다쿠아즈 너무 맛있어요 카페도 정말 조용하고 생각보다 넓고 ,, 좋았어요 오늘은 남자분 계셨는데 너무 친절하시고 차분하셨어요 !!! 다쿠아즈는 진짜 너무 맛있어요 ㅠㅠ 늦게 갔는데 다행히 남아 있어서 살 수 있었어요 다음엔 일찍 가서 더 많은 종류 다양하게 사고 싶어요 많이 달지도 않고 퐁신 퐁신 존맛입니다 근처 갈 일 있으면 꼭 들리고 싶어요 ! 강추 ㅜㅜ', 64, 17, 'GOOD', SYSTIMESTAMP);
