INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '수박화채(딸기우유 선택)+ 멜론추가8,000원 허니그래놀라요거트 아이스크림+초코쉘추가 2,000원 4명이서 먹었어요~ 진짜 맛있게 먹었습니다. 먹다 허니그래는 먹다가 요거트 아이스크림 추가했어용 진짜 맛있게 디저트 먹고 이야기하기도 좋아서 편하게 있다갑니다 추천해요!!', 117, 24, 'GOOD', SYSTIMESTAMP);
