INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '과일들이 진짜 엄청 맛있어요! 이런 방법으로 먹는 화채는 처음인것같아요 ㅋㅋㅋㅋ 가격 대비 양도 만족스럽고 새로생긴 매장인지 엄청 깨끗해요!', 40, 10, 'GOOD', SYSTIMESTAMP);
