INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '처음 와봤는데 와.. 정말 달콤하고 맛있어요 과일들이 싱싱해서 더 맛있는거 같아요 게다가 딸기우유가 달콤하고 맛있고 과일의 달콤한 맛까지 더해져서 더 달고 맛있어요 매장도 넓어서 여럿이 오기에도 좋아요', 11, 1, 'GOOD', SYSTIMESTAMP);
