INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '시원하게 먹고싶어서 왔는데 단거 좋아하시면 여기 추천드립니다 ! + 리뷰 쓸 때 사진도 같이 올려야 컵과일 주시는데 사진이 없어서 못올렸어요 ㅠㅠ 그래도 사장님께서 컵과일 주셨는데 성격 좋으신 사장님 감사합니다🤍 번창하세요 !🍀✨', 43, 2, 'GOOD', SYSTIMESTAMP);
