INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '수박 좋아하는데 집에서 수박 먹기가 번거롭고 귀찮아서 잘 못사먹거든요 근데 수박 화채로 먹으니까 너무 좋은거예요 과일들 다 싱싱하고 좋았어요 오미자가 있길래 신기해서 선택해봤고 다음에는 딸기우유로 먹어볼래요 복숭아 화채에다 먹어야겠어요 흐흐 💕', 83, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '후식으로 화채 먹고싶어서 왔는데 과일도 싱싱하고 양도 꽤 많구 넘 맛있네용 ~~ 🍉🫧 살살 얼어있는 딸기우유가 신의 한 수 .. 🍓✨ 과일 위에 뿌려먹으니 더위가 싸악 ~ 💨 직원분도 너무 친절하셨어요 !!', 35, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '달화채 홍대점은 분홍빛의 샤방한 느낌의 카페에요. 달화채랑 달빙수 그리고 카페음료까지 준비되어 있어요. 달화채에서 먹은 멜론달화채랑 골든프렌즈요거트빙수는 맛이 정말 맛있답니다! 과일의 종류와 양이 많고 특재 딸기우유 베이스와 오미자 베리스 중에 선택할 수 있어서 더욱 좋더라구요! 홍대입구에 오시면 달화채에서 더운 여름에 생각나는 빙수랑 화채 드셔보세요! 추천드려요', 24, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '메뉴판에 홍시 빙수 이미지가 없어서 수박 화채랑 정말 고민했는데 후회 없는 선택이었습니다🥵 친구랑 둘이 홍시를 너무 좋아해서 사실 걱정은 없었는데 그것보다도 더 큰 이상으로 만족했어요 >  ̫<  홍시가 너무 달아요! 모양도 너무 예쁘고 진짜 사르르 녹습니다... ... 사장님도 너무 친절하시고 매장도 너무 쾌적해요! 후덥지근한 날씨에 기분 좋게 피서 했습니다 ♡ 다음에 와선 화채 꼭 먹어볼게요! 다들 홍시빙수 꼭 드셔보세요😖💗💗', 19, 4, 'GOOD', SYSTIMESTAMP);
