INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '딸아이가 미리 알아놨다고 해서 따라 와봤는데 과일도 다 너무 싱싱하고 딸기우유 베이스가 정말 맛있더라구요~~ 다음에는 토핑 추가해서 먹어봐야겠어요^^ 매장이 핑크핑크해서 사진도 잘 나와서 좋았어요', 16, 8, 'GOOD', SYSTIMESTAMP);
