INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '화채 너무너무 좋아요 💗 슬러시로 나와서 더 맘에 들어요 파핑보바 더 추가할걸 후회ㅠ + 매장 진짜 넓고 깨끗 쾌적합니다 ㅋㅋㅋ 해장타임으로도 좋을 듯💗', 83, 13, 'GOOD', SYSTIMESTAMP);
