INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '딱 화채 생각났는데 홍대에 새로생겼더라고용 딸기우유, 오미자 중에 베이스 고를 수 있구요 딸기우유는 살얼음처럼 얼려나와서 아주 시원달달해여~~', 34, 6, NULL, SYSTIMESTAMP);
