INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '매장도 아기자기하게 예쁘고 과일주스, 과일빙수 여러가지 있었는데 혼자 와서 요거트아이스크림 먹어봤어요ㅎㅎ 너무 친절하시고 디저트도 맛있어요~ 빙수가 궁금했는데 못먹어서ㅠ 다음번에 친구랑 과일빙수 먹으러 한번 더 오려구요 ㅎㅎ', 20, 3, 'GOOD', SYSTIMESTAMP);
