INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '역시 겨울에는 딸기빙수 ෆ 일단 과일 너무 신선해요 진짜,, 딸기 미쳤더요,,🍓 연유랑 딸기퓨레도 따로 챙겨주셔서 입맛에 맞게 넣어먹을 수 있어서 너~무 좋았어요 🥹🤍 사장님 센스 무엇ㅠ 맛있어서 빙수 하나 더 먹을까 고민하다가 다른 메뉴도 궁금해져서 바~~로 수박주스도 시켰습니다 🍉! 저 최근에 치앙마이다녀와서 땡모반에 미쳐있었는데.. 치앙마이 갈 필요가 없었네요..ㅋㅋ 수박주스도 너무 만족해서 화채까지 사서 돌아갑니다 😎✨✨ 매장도 넓고 콘센트자리도 많고 좌석간 간격도 넓어서 공부하러 와도 좋을거 같아요! 픽업/포장할 수 있게 근처 사시는 분들 징짜 너무 부럽읍니다••', 127, 22, 'GOOD', SYSTIMESTAMP);
