INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '화채 먹어본지 너무 오래되었는데 새로 오픈했다고 떠서 가봤어요! 과일 넘 상태좋구 상큼하고 약간 건강식으로도 좋을 거 같아요 강추입니다ㅋㅋ', 42, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '여기 사장님 너무 친절합니다. 화채도 깔끔하고 맛있어요. 샤베트 느낌이라서 빙수 먹는 느낌이에요. 과일도 신선하고 양이 많아요. 혼자 사는 분도 주문해서 먹으면 좋을 것 같아요.', 323, 34, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '집앞에 새로 생긴건 알고있었는데 그간 계속 가야지 하다가 날도 너무 더워서 이번에 딸기빙수 포장해서 왔슘다! 매장 너무 깔끔하고 넓고 시원해서 공부하러갈때 자주 갈것같아요!!!! 딸기빙수 진짜 맛있어요ㅠㅠㅠㅠ🍓🍓 베이스가 달닫ㄹ하고 소스도 맛있어서 잘 먹었습니당~', 23, 10, 'GOOD', SYSTIMESTAMP);
