INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '화채만 먹어야 하는 게 아니구 과일주스도 있어용 종류도 다양하고 넘 맛있어요 과일 좋아하시는 분은 좋아하실 것 같아요 다음번엔 친구랑 같이 와서 화채도 먹고 싶어요!! 일하고 계신 분 친절하셔서 좋앗어요🥰🥰', 97, 25, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '원래도 딸기빙수 너무 좋아하는데 먹어본 딸기빙수 top3안에 드네용🍓 너무 맛있어요 우유빙수인데 우유맛 엄청 진하고 달아요! 그리구 딸기 진짜 달구 많이들어가고 맛있어요🍓💗 내일 또 생각날 것 같은 맛입니당 무조건 또또또올게요!! 카페도 핑크색이라 완전 이뻐서 취저에용>_<', 1, 10, 'GOOD', SYSTIMESTAMP);
