INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '아이랑 같이 먹기 좋아요!!!!!! +흥 사실 남자친구랑 왓는데 얘는 너무 애가 좋긴 한데 절 너무 서운하게 해요 그치만 마니 좋아해…', 12, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '아 화채 나오면 사진찍어야지 해놓고 나오자 미자 허겁지겁 먹는 바람에 화채사진을 못찍었네요 ㅜㅜ 진짜 너무너무 맛있었어요!! 과일도 다 너무나 신선했고 양도 많았는데 순식간에 없어질만큼 맛있었어여 겨울이고 새로생긴 곳이라 아직 이 맛집을 모르시는 분들이 많아서 편하게 먹었지만 더워지기 시작하면 줄서야 될거같아서 저는 여름이 후 오기전에 열심히 오려구욬ㅋㅋㅋ 너무 맛있어서 군고구마랑 화채 추가로 야무지게 포장해갔어용!!!잘먹었습니다❤️🍓🍉🍌🍋‍🟩🍊', 56, 18, 'GOOD', SYSTIMESTAMP);
