INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '친구랑 망치빙 포장했다가 매장이 이쁘고 시원해서 매장에서 먹어도되냐고 여쭤봤는데 친절히 허락해주셔서 감삼둥 너무 맛있게잘머거써용 아이스크림 어디꺼에오...?? 마시멜로맛나용ㅎ헤헤', 8, 1, NULL, SYSTIMESTAMP);
