INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '배달로 시켜먹었다가 너무너무 맛있어서 매장으로 방문..사장님 엄청 친절하시고 과일 너무 신선하고 맛있어요!! 역대 먹어본 화채중  1등 입니다!👏🏻', 39, 7, 'GOOD', SYSTIMESTAMP);
