INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '핑크컬러 인테리어로 귀여운 카페예요~! 딸기달화채에 딸기우유 토핑해서 먹어봤는데~ 넘넘 맛있어요! 다시 오고싶은 또가는집ㅎㅎ 분위기도 좋구, 화채도 맛이 굳굳👍👍', 48, 5, 'GOOD', SYSTIMESTAMP);
