INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '집 앞에 생겨서 기다리고 기다리다 방문했습니다~~ 양세형님이 보내주신 화환이 앞에 있어서 신기했네용 ㅎㅎ 딸기화채 맛있게 먹겠습니다~~😁', 1, 3, NULL, SYSTIMESTAMP);
