INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '너무 친절하셨어요ㅜㅜ빙수도 맛있었어여 첨에 조금 비싼것같다고 생각했는데 그만큼 맛있어요!!!처음 놔봤는데 홍대 오면 또 올거같아여😻', 6, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '매장이 넓고 쾌적해서 너무 좋습니다! 핑크톤이라 매장도 너무 예뻐요 오늘 아샷추 사먹으려고 왔던건데 다음에 와서 빙수도 먹어보고 싶을정도로 매장도 잘 되어있습니다 다음에 또 올게요💗', 44, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '우연히 지나가다 들어왔는데 카페가 넓고 분위기가 좋아요!! 아아 맛있어서 우와 했네요 +.+ 사장님도 친절 하셔서 기분이 좋았어요! 화채랑 요거트도 팔던데 다음엔 그것도 먹어봐야 할 것 같아요!!', 7, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달화채 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '매장이 엄청 넓고 이뻐요.! 화사한 느낌.!!✨ 직원분도 엄청 친절하셔서 그냥 바로 들어오게 됩니다ㅋㅋㅋ 엄청 유명하던거라 궁금했는데 동네에 딱 생겨서 밤에 달달한 거 땡길 때 자주 오겠네요.. 지갑 털릴 듯💳 일단 추천합니당.!!', 17, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '연남동 북적이는 거리를 벗어나 한적한 분위기 속에 위치해 있는 감각적인 공간을 가진 카페 브라운하우스 치열한 연남동 카페 시장에서 오랜 시간 운영을 이어오며 꾸준한 사랑을 받고 있는 브라운하우스 해외 유명한 디자인 가구들로 공간을 채워두어, 카페가 아닌 가구 쇼룸에 들어온듯한 기분을 주는 곳 멋진 가구 소품들을 가진 카페들이 많아지는 요즘이지만, 아직까진 나에게 첫번째라고 할 수 있을정도로 멋지다라고 생각이든다. 여럿이서 담소를 나누기에도 혼자서 노트북이나 책을 가져와 여유로운 시간을 보내도 좋은 곳이며 3층은 카페 공간과 함께 작은 소품샵도 운영을 하고 있으니 함께 즐기시면 좋을거 같다. 더 자세한 정보는 최제로 블로그🙇🏻‍♂️🌼', 85, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '너무 아늑하고 좋은카페에요!!🥺🩷 진짜 저만 알고싶운 카페 .. 2층으로 되어있고 2층에는 소품샵도 있어요! 연남이랑 더 가깝구 디저트도 다양한 편입니당 저녁이라서 디카페인 아인슈페너 시켰는데 크림 뭐에영? ㅁㅊ네요 맛있다는뜻💝😤', 3, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '분위기 맛집✨️ 디저트 맛집🤩 연남동 차분한 카페 찾는다면 브라운하우스 추천해요! ☕️ 건물부터 눈길이 가는 외관인데, 내부는 더 감성 가득하달까요! 2, 3층이 카페인데, 3층은 작업실(?)로 사용하시는 공간이 같이 있는 것 같더라구요. 디저트도 꽤 있어서 행복한 고민 끝에 단호박 치즈 케이크🍰 먹었는데, 단호박 좋아하시면 딱 좋아하실 맛! 꾸덕하니 커피랑 조합이 아주 굿이었습니다😋 근처에서 카페 어디갈지 고민할 때 가면 좋을 것 같아요!! 재방문 의사 완전 있습니다~😉', 12, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '인테리어도 너무 이쁘고 깔끔해요! 조용해서 대화하기도 너무 좋았어요 ㅎㅎ 예쁜 소품 파는 곳도 있어서 볼거리도 많고 아기자기해서 보기만해도 즐겁고 행복했습니다✨ 그리고 무엇보다 단호박 치즈케이크 진짜 너무너무 맛있어요!!!!! 단호박 좋아하시면 무조건 드시길 추천합니다💛 커피도 콜드브루도 좋았고 시그니처인 브라운커피가 크림도 쫀쫀해서 너무 맛있었어요! 사장님도 정말 친절하셔서 오랜만에 온 연남동에서 마음까지 따뜻해지고 돌아가는 기분이에요😻', 90, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
