INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '주말 홍대.사람에 치여 지쳐갈 때쯤 1팀 정도 웨이팅 후 들어간 브라운하우스 직원분이 친절하신게 인상깊었고 산미있는 원두도 입맛에 맞았고 단호박치즈케이크가 정말 맛있었다 다양한 굿즈 및 책도 판매하고 계셨고 친구 사진을 예쁘게 찍어줄 수 있어서 행복했다 통창으로 들어오는 햇볕이 따스한 연남동 어느 카페.', 63, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '절대 비추드립니다. 노트북 2시간 제한이라는 문구를 보고 음료와 더불어 추가로 케이크를 주문했습니다. 약 3시간 15분 정도 되었을 때 노트북은 2시간 이용 제한이 있다고 말씀해주셔서 아르바이트생 분께 여쭤보니 [음료]기준이라고 말씀하시네요 상식적으로 메뉴판에 제대로 써두셨으면 케이크를 굳이 주문 안하고 나가던지 음료를 주문했을텐데 응대가 매우 아쉽습니다. 입장은 충분히 이해가 가지만 제 돈 주고 주말에 기분이 매우 잡치네요; 다른 분들은 방문하실 때 참고하시면 좋겠습니다. ps 혹시 사장님께서 억울하신 부분이 있으시면 언제든지 말씀 부탁드립니다. 직접 대면해서 말씀드리려다 리뷰로 전달드립니다.', 5, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '대화하기 참 좋은 조용하고 깔끔한 인테리어에 카페! 항상 가고싶던 카페였는데 나른한 주말 오후 시간을 이용해 다녀왔습니다! 커피도 너무 맛있고, 특히 시그니처 디저트인 단호박 치즈케이크 필수입니다!', 41, 2, 'GOOD', SYSTIMESTAMP);
