INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '브라운하우스는 안 예쁜 곳이 없어요! 음료와 케이크도 맛있지만 인테리어 맛집이에요 편안한 색감에 햇살도 따스하고💓 자주 찾게 되는 건 이유가 있지요!!', 31, 2, 'GOOD', SYSTIMESTAMP);
