INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '따뜻한 라떼는 처음 주문했는데 맛있었어요. 음.. 여기 알바분은 가끔 갈 때마다 한번도 웃지 않으시고 표정없이 응대 하시는데, 기분이 안 좋으신건지 왜인지 모르겠으나 기대하고 온 카페인데 기분이 별로네요.', 48, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '언제와도 좋은 브라운 하우스. 작업하기에 정말 좋은 카페라서 회의할 때 자주 와요. 층도 2개라서 자리도 많고 무엇보다 브라운하우스의 단호박치즈케이크는 정말 감동의 맛..ㅠㅠ 조만간 먹으러 다시 가야겠어요.', 42, 4, 'GOOD', SYSTIMESTAMP);
