INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '#단호박치즈케이크 단호박에 치즈가 곁들여진 듯한 맛과 후반에 느껴지는 깊은 단 맛 - 단호박과 유사하면서도 좀 더 꾸덕한 질감 #디카페인콜드브루 곁들이기 좋은 고소한 콜드브루 p.s. 혼자 있거나 또는 조용한 대화하기 좋은 공간(2, 3층)', 28, 9, 'GOOD', SYSTIMESTAMP);
