INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '분위기도 좋고, 디저트도 맛나고 따뜻한 커피도 괜찮았어요. 아이스 라떼는 우유맛보다는(얼음이 많은것 같지는 않았는데 ) 물맛이 더 났다랄까요? 우유가 저지방일까하는 의문이 들었어요. 원두는 맛났었는데 아쉬웠구요. 그리고 요즘같은 시대에 충전 서비스가 안된다는 곳은 처음 보구요 콘센트도 찾아보기 힘들었구요. 알아서 하라는식의 서비스 참 난감하고 아무리 맛나도 지인분은 다시 안올꺼라고 돈쓰고 기분 나쁘다고 하셨어요. 본인들도 충전 할텐데 약간의 배려만 있었어도 충분했을꺼 같아서 아쉽네요. 늦은시간까지 계속 손님들이 찾아는 오시던데 아쉬웠습니다.', 23, 5, 'BAD', SYSTIMESTAMP);
