INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '재방문 했어요! 지난 번에는 2층에 있었는데 3층도 조용하고 아늑하니 작업하기 좋았어요. 매장은 2층, 3층으로 구분되어 있고 화장실은 두 층 모두 있어요. 깨끗합니다! 인테리어가 정말 예쁘고 가구 보는? 재미가 있어요. 저 아메리카노 안 좋아하는데 여기꺼는 맛있어서 먹어요. (아몬드 트리?였나) 단호박 바치케도 정말 맛있고요... 분위기가 정말 좋아요 노래도 카페랑 잘 어울려요! 평일 금요일 2시쯤에 갔는데 자리 넉넉했어요. 3층에 콘센트는 벽쪽에 있는 자리에 두 개 있습니다. 2층은 콘센트가 있었는지 기억이 잘 안 나네요.. 다음에 또 올 것 같아요.', 27, 9, 'GOOD', SYSTIMESTAMP);
