INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '작업하기는 3층이 대화하기는 2층이 좋은듯 합니다 통창에 은은한 조명 북유럽같아 좋아요 잘 작업하고 갑니다 좀 접근성이 좋지 않지만 재방문의사 있어요 가격대도 있어요ㅎㅎ', 31, 5, 'GOOD', SYSTIMESTAMP);
