INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '2,3층으로 이루어진 카페에오. 커피도 너무 맛있고 작업하기 좋은 책상들도 많아요.🙂 일하러 오기도 떠들러 오기도 좋은거같아요.', 33, 4, 'GOOD', SYSTIMESTAMP);
