INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '아늑하고 따뜻한 분위기라 좋고 연희동으로 넘어가는 연남동 끝쪽에 위치해서 시끄럽거나 붐비지 않아 더욱 좋아요 🤍 혼카페나 작업하러 오시는 분들도 많고 공부하기도 좋을 듯 싶어요 단호박 치즈케이크 크기는 아담했지만 구수하고 맛나네용 👍🏻 숨겨져 잇지만 2층이 더 아늑해서 좋아요 !', 72, 13, 'GOOD', SYSTIMESTAMP);
