INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '인테리어가 너무 멋져서 찜해놨던곳 라떼 쫀쫀한 우유거품 짱~ 직원분들 다들 친절하신데다 분위기진 공간에서 편안하게 대화나누기 좋았어요 저녁에 방문했는데 낮에는 또다른 느낌일거 같아 다음엔 밝을때 한번 가보고 싶네요 ^^', 71, 14, 'GOOD', SYSTIMESTAMP);
