INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '연남 핫플레이스들에서 약간 거리가 있지만 그래서 고요하게 저녁을 보낼 수 있었다. 아는 사람들끼리 찾아오는 비밀 아지트 같은 느낌이랄까. 나중에는 혼자 낮에 가보고 싶다. 밤의 느낌도 좋았지만 낮의 햇살도 예쁠 거 같아서. 예전에 살던 동네, 살던 곳 옆에 이런 멋진 카페가 생기다니 격세지감도 느껴지고, 여러 감정이 오갔던 곳. 그리고 조명들이 다 너무 예뻤다.  낮에만 방문해본 사람들은 꼭 조명이 켜진 저녁에도 방문해보길 추천.', 3, 10, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '[연남동 아인슈페너 짱 맛있는 카페🫶🤍] 커피 디카페인 선택도 가능하고 일단 아인슈페너 크림이 진짜 맛있어요❤️ 2층,3층이 카페고 화장실 각 층에 남녀공용으로 있습니당. 주차자리는 딱히 없어서 골목에 알아서 대셔야할것같아용. 의자도 편하고 공간이 좀 편안한 분위기여서 오래 편하게 대화하기도 너무 좋아요👍', 12, 8, 'GOOD', SYSTIMESTAMP);
