INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '데이트겸 연남동 놀러갔었어요! 공간이 2층으로 되어있어서 좌석이 많았는데 그래도 사람들이 많아서 꽉 차있더라고요 그래도 조용한 공간이여서 편하게 있을 수 있었어용ㅎ 단호박치즈케이크는 처음 먹어봤는데 엄청 달지 않고 조합이 좋더라고요 👍 차분한 곳 찾는다면 여기 추천이용🫶', 26, 5, 'GOOD', SYSTIMESTAMP);
