INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '카페 내부 분위기가 너무 좋았고, 카페와 알맞는 음악까지 나와서 대화를 나누거나 간단한 작업하기에 좋은 카페입니다! 치즈케이크도 꾸덕하고 맛있었습니다!! 카페전문 유튜브 유리소리TV', 74, 15, 'GOOD', SYSTIMESTAMP);
