INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '인테리어도, 커피,디저트 모두 다 맛있고 멋져요! 지난 번 방문에도 느꼈는데,, 공부하는 사람들이 있어서 괜히 눈치보이더라고요 카페는 수다떠는 곳 아닌가요,,', 6, 2, NULL, SYSTIMESTAMP);
