INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '연남동 카페 찾아보다가 우연히 들어온 곳인데 2,3층에 위치해 테이블도 적당히 거리감 있게 배치해서 이야기 하기도 좋고, 작업하기에도 적합한 공간이라 좋았어요. 아메리카노 시켰는데 원두도 두종류로 취향에 맞게 골라서 먹을 수 있고, 단호박 케이크도 촉촉하고 부드러워 꿀조합이었어요 ! 굿즈도 판매하고 있어서 구경하는 재미 쏠쏠', 36, 10, 'GOOD', SYSTIMESTAMP);
