INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '2, 3층 이용할 수 있는 카페 내부가 깔끔하고 인테리어도 예쁘게 꾸며놓아서 곳곳에서 사진 찍기 좋았습니다. 단호박치케 궁금했는데 역시 맛있네요. 간만에 무척 마음에 드는 카페를 찾은 것 같아 너무 좋은 시간이었습니다🥰', 32, 5, 'GOOD', SYSTIMESTAMP);
