INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '분위기 너무 좋아요. 조용하고 팔로산토 향이 진하게 나서 더 제가 좋게 느꼈나봐요. 묵직하고 고소한 원두로 블랜딩한 아몬드 트리도 잘 먹고가요.', 20, 5, NULL, SYSTIMESTAMP);
