INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '인스타 보고 방문 했어요 내부가 생각 한 것 만큼 예쁘진 않았어요 음료 맛은 평범해요 이 가격에 맛에 인테리어까지 음..굳이? 두번은 안올 것 같아요 조용한거 좋아하시는 분이나 혼자 카페 갈때는 좋을 것 같네요 사진 찍는거 좋아하시는 분들은 안가는게 좋을듯 ..눈치보임 매장 자체가 조용한 분위기', 130, 19, 'BAD', SYSTIMESTAMP);
