INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '음료가 맛도라지고 가구와 인테리어에 눈돌아가는 카페입니다. 층수도 있고 좌석도 다양해서 좋습니다. 소리 울리고 왁자지껄한 느낌도 없고, bgm도 적당히 리드미컬한걸로 틀어주셔서 담소 나누기 아주 좋습니다. 아늑하고 잔잔한 분위기👍🏻', 1, 0, 'GOOD', SYSTIMESTAMP);
