INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '연남동 신상카페 찾다가 발견한 카페입니다..! 분위기도 너무 좋고 2,3층으로 되어 있어서 좌석도 많답니다! 베스트 메뉴인 단호박 치즈케이크 너무 맛있어요😋', 37, 1, 'GOOD', SYSTIMESTAMP);
