INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '분위기 좋고 친절하세요 커피맛도 맛나요 종종 연남오면 시끄러움 피해서 들릴거 같아요 다만 과한 힙쟁이셀피좀 자제시켜 줬으면ㅜ 계속 셀카찍는 찰칵찰칵 소리 엄청 거슬리더라구요', 2, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '바치케가 갑자기 먹고싶어져서 즉흥적으로 찾아간 곳인데 너무 좋았어요! 치즈케이크 맛있어요😚 아메리카노도 맛있었습니다🤎 가게가 넓진 않지만 2층에도 자리가 있고 사람이 붐비지 않아서 여유롭게 있다가 왔네요 (평일 낮 기준!)', 29, 7, 'GOOD', SYSTIMESTAMP);
