INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '분위기 너무 좋고 친절해요. 커피도 맛있어요 향긋향긋. 사람이 많아서 겨우 앉았어요. 분위기 좋아용. 그런데 간판이 눈에 띄지 않아요ㅜ 해당건물 2층입니다!', 19, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '디저트 보단 커피가 맛있네요 아인슈 깔끔한맛이구요 카페 인테리어도 미니멀하면서 모던한 느낌 전체적으로 시끄럽지 않아 좋았습니다.', 75, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '연남동 숨은,, 이라고 하기엔 너무 유명한 분좋카예요! 직원분도 너무 친절하시고, 눈 돌아가는 가구들이 매력적인 곳이에요. 음료 맛도 맛있고, 화장실도 쾌적합니다. 전체적으로 따뜻하고 차분한 분위기라 만석이더라도 어수선하지 않은 것 같아요.', 10, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '날이 풀려서 기분전환을 하러 나왔어요! 연남에서 집중할 수 있는 카페에 가고 싶어서 찾아보다가 발견한 브라운 하우스 카페 인테리어가 마음에 들어서 기대를 하고 도착했는데 생각보다 훨씬 더 깔끔하고 세련된 분위기였어요 . 특히 분위기에 맞추어서 매장에 틀어지는 노래가 기분을 좋게 만들어주네요 💛 2,3층 으로 구성돼있는 이 공간은 무엇보다 앉을 수 있는 좌석이 넉넉해서 좋은 것 같아요. 혼자서 집중할 시간이 필요할 때 찾아와도 좋을 것 같고 친구와 대화를 나누러 와도 좋을 것 같네요 :) 또 오겠습니다 ^ㅁ^', 33, 2, 'GOOD', SYSTIMESTAMP);
