INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '그냥 평범한 카페인줄 알고 들어갔으나 사장님이 특별히 친절했고, 따뜻한 분위기의 카페였다. 따뜻한 아메리카노 맛있고, 브라운커피를 먹어야 한다. 그러나 단호박 치즈케잌은 단호박 향 싫어하면 비추 그러나 싫어해도 맛은 평균 이상 입니다. (난 단호박 싫어하나 맛있었다)', 11, 4, 'GOOD', SYSTIMESTAMP);
