INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '인테리어도 너무 멋지고 조용한 분위기라 커피마시기도 너무 좋아요!! 커피랑 디저트맛도 대박입니다!! 버터바는 무조건 드세요!!', 81, 15, 'GOOD', SYSTIMESTAMP);
