INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '커피랑 디저트 둘 다 맛있고 좋았어요. 치즈케이크도 맛있는데 다음엔 단호박 치즈케이크 먹어보려고요 여하튼 분위기 좋은 카페라 추천합니다!', 54, 14, 'GOOD', SYSTIMESTAMP);
