INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '시그니처 커피가 정말 맛있고 단케도 단호박 맛이 많이 느껴져서 너무 만족스러웠어요. 매장도 카운터층이랑 그 위층이 다른 느낌으로 모두 예뻐서 또 방문하고 싶은 곳이었어요!', 16, 9, 'GOOD', SYSTIMESTAMP);
