INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '너무 친절해서 기분좋게 먹었어요! 3명이서 방문했는데 자리도 적극적으로 만들어주셨어요 인테리어도 너무 맘에 들고 커피 진짜 맛있어요!!!! 치즈케이크랑 버터바는 엄지척👍🏻', 26, 2, 'GOOD', SYSTIMESTAMP);
