INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '좌석이 많아서 사함들이 많이 찾음에도 불구하고 웨이팅 없이 앉을 수 있음 커피 무난함 클래식 버터바는 너무 달음 단호박 치즈 케이크는 깔끔하고 많이 달지도 않고 먹기 좋음 다만 단호박 향이 강해서 단호박 안좋아하는 사람은 호불호가 갈릴 수도 있음 재방문의사는 딱히 없음? 그렇지만 주변 카페에 자리가 없다면 다시 갈 생각은 있음', 52, 13, NULL, SYSTIMESTAMP);
