INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '골목에 있는지라 주말 늦은 시간에도 3팀 밖에 없었고 테이블 간 거리가 멀어서 말소리가 안 들리고 넓직해서 좋았음 메뉴가 별로 없지만 맛있고 인테리어, 조명이 아늑해서 사진 잘 나옴 : )', 10, 8, 'GOOD', SYSTIMESTAMP);
