INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '사장님도 친절하시고, 커피도 맛있고 다 좋지만.. 브라운 하우스는 공간이 정말 완벽해요 .. 가구나 조명 그리고 굿즈까지 하나 하나 다 세심함이 느껴지고, 2층까지 넉넉하게 사용할 수 있어서 좋았어요! 케이크를 못먹어본 게 아쉬워서 또 방문 예정입니다 : )', 42, 5, 'GOOD', SYSTIMESTAMP);
