INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '깔끔하고 모던한 인테리어와 모든 가구들과 탁자 의자 등 카페 이름에 걸맞네요ㅎ 커피는 정말 맛있었고 무엇보다 자리가 너무 편해서 좋았습니다. 브라우니는 조금만 더 촉촉하게 해도 괜찮을거 같아요', 36, 8, 'GOOD', SYSTIMESTAMP);
