INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '브라운하우스 연남'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '분위기 좋아요! 2층까지 생겨서 엄청 크고 넓은데 단점은 계산대쪽 앞 테이블이 너무 다닥다닥 붙어있어 불편하고 불안했어요  ㅠ 커피맛 좋긴한데 데 아메리카노 너무 비쌌습니다,, ㅠㅠㅠㅠ', 50, 9, NULL, SYSTIMESTAMP);
