INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '인스타에서보고 먹어보고싳어서 돚오전 흠..줄섯으면 후회햇을가같은..? 맛은잇는데 두번은 안올거같아용..ㅎㅎ 사진용...ㅎㅎㅎㅎ디저트 ...ㅎㅎㅎ 웨이팅 없이 먹을수잇어서 좋앗어용', 0, 0, NULL, SYSTIMESTAMP);
