INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '비싼값 합니다 ㅎㅎ 과일이 다 달고 맛있어요🍓🍊🍋🍇 커피도 쏘쏘 근데 생각보다 크레이프랑 크림이 좀 느끼하네용 매장은 엄청 협소해서 포장도 많이들 하는거 같더라고요! 포장하러 또 가볼라구요~~', 23, 9, NULL, SYSTIMESTAMP);
