INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '1.5플로어에 다녀왔다 가게가 정말 작고 수줍은 듯 위치해서 처음엔 그냥 지나쳤다. 아마 네비가 없었으면 못찾을뻔했다. 그런데도 다섯 개밖에 없는 자리는 다 차지되어있고 일부러 찾아온것같은 외국인 한 팀은 대기자에 명단을 올렸다 나는 혼자 간거라 포장해서 나왔다 너무나 탐스럽게 생긴 후르츠롤을 들고 흐믓하게 연남동 골목을 걷는다', 64, 16, NULL, SYSTIMESTAMP);
