INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '가성비 좋고 신선한 과일을 써서 맛있어요!! 연남공 올 때마다 생각나서 이번에 또 왔어요!!  맛있세 먹은 마카롱이 화이트데이 시즌이라 없어서 아쉬웠어요~ㅠㅠ 다음에 오면 다시 먹을거에요!!', 49, 2, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '친한 동생이랑 릴스 보고 처음 방문했는데, 음료랑 디저트도 너무 맛있고, 사장님이 친절해서 좋았어요😮😮💛 공간이 조금 협소하지만 불편하거나 신경 쓰이는 부분은 없었습니다! 오히려 아늑하고 아기자기한 귀여운 공간이었어요:) 저희는 후루츠 크레이프 보고 갔었는데, 저녁쯤에 가서 그런지 솔드아웃 됐더라고요ㅜ 아쉬운 마음에 딸기로 먹었는데 이것도 넘넘 맛있었어요༼;´༎ຶ ۝ ༎ຶ༽ 다음엔 일찍 방문해서 꼬옥 후루츠 크레이프 먹을거예요..🥲🥲 번창하세요~!', 13, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '웨이팅 안 하구 원하는 거 겟했네요 저희가 들어온 뒤로 손님들이 우루루 오더라구요 진짜아 롤 크네요 앞으로도 애용할게요ㅜㅜㅜ!!!', 18, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '기대하고 갔었는데.... 비쥬얼에만 치중된 베이커리였어요. 망고는 숙성되지않아 너무 딱딱했고, 후르츠롤의  과일도 조화롭다고는 생각이 안들더군요 더군다나 생크림이.. 식물성 생크림이 섞인 맛이더라구요', 117, 26, 'BAD', SYSTIMESTAMP);
