INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '홍대 딸기 케이크 검색해서 왔는데 대박 롤케이크 존맛이에요 오리지널이랑 피스타치오 샀는데 둘 다 맛있음 다음번엔 매장에서 먹으려구요!!', 7, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '오픈런해서 먹었던 일쩜오플로어✨ 사람이 많고 유명한 데에는 이유가 있다는데 여기 디저트 맛집 인정합니다 과일도 엄청 듬뿍 들어있는데 한국인이 좋아하는 너무 달지 않은 맛 그잡채 포장하시는 손님 분들도 많은 걸로 보아 매장이 만석일 때 집만 가까우시다면 포장해서 드시는 것도 좋을 것 같아욥 🍓🥝후르츠롤 존맛 강츄🍊🍍', 32, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '드디어 먹어보았습니다. 무게가 상당했는데, 막상 먹어보니 1인1케잌으로 가볍게 하나씩을 먹을 수 있네요! 구입한 것 중 딸기초코가 크림 비중이 좀더 있게 느껴졌어요. 집에서 너무 멀지 않으면 자주 사먹을텐데 아쉬워요', 9, 0, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '매장이 말 그대로 1.5층에 있어요...! 사장님 친절하시고, 커피랑 디저트 다 맛있어요,,,ㅠㅠ 산미 없는 편이라 더 좋았어요~ 후르츠롤 보고 일부로 온건데 과일도 많고 맛있어요!! 다만 잘라먹기 힘들었습니다,,ㅠㅠ 접시가 조금 더 컸으면 좋겠어요! 잘라먹기에 접시가 좀 작았어요,,ㅠㅠ 과일도 맛있고 다 좋았습니다~ 매장은 좁아요!', 45, 1, 'GOOD', SYSTIMESTAMP);
