INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '신기한 디저트 였어요!🤔 식감이? 포크로 잘라낼때 질감이? 약간 크레이프 케이크를 먹는거 같으면서도 다른 그런...? 과일도 많이 들어있고 맛있었어요😋 생각보다 커서 둘이 먹으면 딱 되는 느낌...? 사진을 뒤쪽에서 찍어서 과일이 안보이는데 눕히고  먹어야해서 눕히면 과일이 여러가지 크게 박혀있어용😉 초코라떼랑 먹었는데 디저트가 그렇게 많이 달지 않아서 조합이 꽤 괜찮았습니다😆 매장은 좀 협소한 편이라 매장에서 먹으려면 대기 있을수도....? 화장실도 깨끗하고 굿굿👍👍👍 다음에 또 가보고 싶어용~', 34, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '이렇게 옆으로 들면 안됩니다!!ㅠㅠ 그래도 진짜 맛있었어용!!! 후르츠맛 먹어보고팠눈뎅 이거는 걍 오픈런해여합니당!!! 담에오픈런 각!!!👍🏻', 32, 1, NULL, SYSTIMESTAMP);
