INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '보기에도 좋은 떡이 맛도 좋다는 우리나라 속담처럼 보기에도 예쁜 크레이프롤이 먹으면 너무 맛있다구요~~! 다른 맛 맛보러 조만간 출동하려고요! 사장님인지 직원분인지 주문 받으시던 분 전문가포스 뿜뿜 너무 멋져요😍😍😍', 110, 20, 'GOOD', SYSTIMESTAMP);
