INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '미쳐땅….👍🏻 가격이 비싸서 처음에는 흠칫, 머뭇 거릴 수 있으나 크기도 안에 들어가는 과일양과 퀄 그리고 맛까지 느끼다보면 일반적인 조각 케이크나 큰 홀케이크 보다 훠어어어얼씬 훌륭합니다♥️🫨👍🏻 한조각 실물이 사진보다 진짜 커요! 과일이 다양해서 먹을때마다 음음 소리가 절로 나옵니다!! 진짜 또가야지…보물을 발견한 이 기분? 옆집으로 이사가고 싶은 심정입니다요 ㅠㅠ 휴 당분간 케이크 선물은 이집에서만 해야지. 사장님 아프지 마시고 오래오래 이 맛있는 케이크 플리즈 입니다🙏🏻😌🙏🏻', 49, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '라떼도 맛있고 디저트 매우 만족합니다 녹차도 먹고싶었지만 저녁으로 고기를 먹어야하기에 참았어요 홍대갈일 생기면 담에 녹차 포장해 올려고요! 마카롱도 가격대비 괜찮은 편인듯해요! 평일임에도 손님 계속 와서 시간 못맞추면 웨이팅 있을수도 있어요:)', 58, 12, 'GOOD', SYSTIMESTAMP);
