INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '디저트가 비싸긴한데 그만큼 양이 엄청 많기는 해요..! 그리고 맛도 있어서 좋습니다 ㅎㅎ 매장은 협소한편이고 분위기가 아늑해서 좋습니다 !', 6, 6, 'GOOD', SYSTIMESTAMP);
