INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '생각했던 것보다 롤이 엄청 커서 놀랐어요! 후르츠롤 포장해와서 먹었어요 메론, 귤, 용과, 망고, 딸기, 샤인머스켓이 한가득 들어갔어요!!! 재방문의사 100%', 66, 11, 'GOOD', SYSTIMESTAMP);
