INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '궁금했던 곳 드디어 방문해봤어요 먹어보고 싶었던 롤 두가지하고 조개롱 샀는데 품절이 되있어서 더 구입하지 못해서 아쉬웠습니다 맛있어요 재방문 의사있습니다', 29, 2, 'GOOD', SYSTIMESTAMP);
