INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '후르츠롤크레이프/아아/페퍼민트레몬 주문했습니다 사진보자마자 디저트너무 맛있을것같아서 방문했습니다 너무 맛있네요,,,,👍🏻 또오고 싶어요 좌석은 4~5테이블정도로 협소한 편입니당', 30, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '과일이 통으로 가득가득 들어있어 너무 좋았고 맛도 엄청 단맛은 아니라 물리는게 덜했어요 다만 크림이 과일에 비해 좀 부족해서 퍽퍽하게 느껴지더라구요 과일을 크림에 찍어먹는 느낌이랄까요 바쁜 와중에도 사장님이신지 직원분이신지 엄청 친절하세요~', 51, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '대왕 후루츠 롤크레이프🍈 과일이 듬뿍이라 과일 먹고 싶을때 롤크레이프 사먹을래요~~ 크림이 느끼하지 않아서 커피나 우유 없어도 술술 들어가요.. 두명이서 하나 나눠먹으니 식후 디저트로 좋아요! 다른 맛도 궁금해서 또 갈게요😽', 31, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '1) 망고샤인 먹었습니다 처음에 망고 먹고 너무 셔서 뱉었습니다 썩은줄 알았습니다,, 샤인도 그저그런맛 빵과 크림은 무난하네요 과일빼고 골라먹었습니다 2) 헤이즐넛슈패너 위에 가루 비쥬얼 충격에 헤즐넛향이랑 슈패너 크림, 커피랑 따로 놀아서 먹기 힘들었습니다🤮 광고 사진 조심하세요.', 12, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '케이크 가격이 왜그래 하지만 양과 비주얼을 보면 인정할만한 가격 적당히 단 맛에 가득 찬 과일들이 들어있음 크레이프가 쌓여져있어서 취향저격임 커피랑 딱 먹으면 적당함', 41, 9, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '유튜브에서 보고 폭력적인 비쥬얼에 감탄을 금치 못했는데 맛은 비쥬얼을 따라가지 못한... 과일의 당도는 좋았으나 크림이 먹을수록 입안이 기름기로 코팅되고 느끼해서 간신히 먹었어요. 아아와 함께먹으니 크림이 입안에서 녹지못하고 막을 만들어서 갈수록 먹기가 힘들더라구요ㅠㅠ 마카롱을 못먹어봐서 궁금하긴합니다. 직원분들은 정말정말 친절하셨어요👍', 10, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '생크림롤에 생크림이 식물성이긴한데 과일이 많고 과즙터져서 느끼함 잡아준 케이크는 평범하고 롤이 더 특색있는듯 매장안 4~5팀만 가능해서 먹고가려면 타이밍 잘 맞추시길', 26, 1, NULL, SYSTIMESTAMP);
