INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '후르츠롤크레이프 너무 맛있어요 부모님이랑 오빠가 단거 안좋아하는데 이케이크는 맛있게 먹었어요 단거 안좋아하시는 부모님 생일케이크로 딱이에요', 7, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '와 여기 크레이프케이크 진짜 대박이에요ㅠㅠㅠㅠ 가격만 봤을 땐 넘 비싸다고 생각했는데 크기보니까... 와우 ㅋㅋㅋㅋㅋㅋㅋ 복숭아 크레이프케이크 시켰는데 복숭아도 정말 많이 들어있고 진짜 맛있어요ㅠㅠㅠㅠㅠㅠ 담에는 다른거 먹어볼거예요 기본 케이크도 크기 진짜 크고 위에 과일 듬뿍 올려져있어요. 하ㅏㅏ 둘이서 크레이프케이크 하나 다 못 먹었는데 남긴 거 생각나는 맛입니당.. 꼭 다시 방문할거예요ㅠㅠ', 101, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
