INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '두번째 방문만에 드디어 자리가 있어서 먹어 볼 수 있게 되었습니다 매장에는 그렇게 편하지는 않은 조그만 두 테이블과 매장 밖에 조그많게 두 테이블까지해서 총 4테이블 정도로 매우 협소해서 운이 좋아야 자리를 겟할수 있더라구요... 마카롱과 케익 그리고 인스타에서 핫한 롤케익까지 파는데 다양한 종류의 롤케익이 있었고 말차딸기롤케익으로 먹어봤는데 말차와 딸기를 좋아하시는 분이라면 추천합니다! 딸기도 진짜 낭낭하게 들어있고 크림도 꾸덕하니 맛있었어요! 커피도 요즘 인스타감성으로 쪼매난컵에 감질나게 주시는게 아니라 긴 컵에 기본 투샷으로 샷추가안하고 진하게 마실수 있어서 좋았습니다 자리만 있다면 연남 들렸을때 꼭 재방문하고싶은 카페입니다!!', 48, 3, NULL, SYSTIMESTAMP);
