INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '후르츠롤크레이프로 입덕한 일쩜오플로어. 딸기치즈롤크레이프랑 초코딸기롤크레이프도 먹어봤는데 다 맛있어요. 크레이프 안에 들어있는 과일도 정말 싱싱하고 크림도 부담스럽지 않아서 좋습니다!', 11, 3, 'GOOD', SYSTIMESTAMP);
