INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '생각보다 과일이 다채롭고 많아서 좋앗어용 매장은 정말 작으니 포장해서 드시는걸 추천ㅠㅠ 시끄러운거 싫어하시는 분들은 매장식사는 비추천입니당ㅎㅎ', 47, 3, NULL, SYSTIMESTAMP);
