INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '정식 명칭은 기억ㅇㅣ 안나는데 여기 마카롱도 진짜 맛있고 크레이프도 진짜 맛있어요!! 커피는 산미가 없는 고소한 원두이고 전체적으로 양도 많고 너무 달지않고 맛있어요! 매장은 테이블이 2개/테라스에2개 있는데 포장도 추천! 크레이프는 생각보다 엄청 커서 놀랐어요! 연남동 방문 시 꼭 드셔보시길..!!강추!', 84, 13, 'GOOD', SYSTIMESTAMP);
