INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '주말에 방문했더니 웨이팅이 있더라구요 ! 가게가 협소해서 수용인원이 많은 편이 아니라 3-40분 기다렸던 거 같아요 포장하시는 분들도 많았음 ! 크레이프케이크는 접시가 작아서 잘라먹기 좀 불편했아요ㅜ 그리고 살짝 의문인게 마카롱 같은 건 비닐포장이 되어있으니까 상자포장시 추가금액이 발생할 수 있다고 생각하는데 케이크는 왜 발생하는 건지 좀.. 모르겠더라구요..? 100원인가 밖에 안 해서 상관은 없긴한데 그럼 손으로 들고 가라는 건가 싶어서 허허', 62, 16, NULL, SYSTIMESTAMP);
