INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '크레이프케이크 한 번 꼭 먹어보고 싶어서 방문했어요. 매장엔 테이블 2개 있고 협소해서 테이크아웃 위주더라구요. 크레이프케이크 한 번쯤 먹어볼만 한 것 같아요. 크림이랑 딸기가 맛있었어요!! 매장에서 먹으면 1인 1음료 주문이에요. 아메리카노 산미가 없어서 맛있었어요.', 129, 21, 'GOOD', SYSTIMESTAMP);
