INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '케이크를 생과일로 만드니 너무 맛있습니다. 커피도 브랜드 커피보다 훨씬 맛있어요. 다만, 연남동 대부분의 가게가 그렇듯 공간이 넓지 않아서 자리가 없을 수 있어요~', 37, 1, 'GOOD', SYSTIMESTAMP);
