INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '예전부터 가보고 싶은 곳이라서 드디어 마음 먹고 갔는데 일단 테이블이 실내에 4개 야외에 2개 있는데 가게 자체가 작아서 먹고 가기는 그렇고 항상 테이크아웃으로 가져가야할 거 같더라구요ㅠ 그래도 마카롱이랑 빵은 맛있었어요!!! 솔직히 빵 보고 간건데 빵은 너무 달았고...마카롱이 더 맛있었어요ㅎㅎ..', 16, 3, 'GOOD', SYSTIMESTAMP);
