INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '우선은 출입구 옆에 취식이 가능한 좌석이 2자리가 있긴 합니다만.. 서로 간격이 너무 딱 붙어있기도 하고 매장을 오가시는 손님들과 아이컨택을 계속 하게 될 수 있으니 웬만하면 포장해 가시는 것을 추천합니다. 화려한 뚱카롱과 롤 크레이프 케이크를 판매하는 곳이에요. 미니 케이크도 판매하시는데 이 날 라인업에 없어서 구매하지 못했네요. 롤 크레이프는 비주얼은 화려하나 한 번 먹은 것으로 만족합니다. 가끔 뚱카롱이 생각나면 방문하여 포장해갈 것 같습니다.', 22, 0, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '제가 방문할수있는날은 오픈하지않아 어렵게 겨우 날짜가 맞아서 맛본~ 크림이 느끼하지않고 크레이프가 평범하지않은 진짜 맛집이에요 재방문 의사 100%', 96, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '양평에서 쉬는 날 피해서 온다고 벼르고 벼러서왔어요 !!! 그래도 사장님의 배려로 잘. 사서 가요 ~~ 역시 사딤하고 쪽같은 비쥬얼이라 넘 안심 하고 가요 ^^ 두시간 비를 뚫고 온 보람이있습니다', 116, 20, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '마지막 하나 남은 후르츠롤크레이프케이크 포장해서 먹었어요. 과일 신선도와 당도가 끝내주네요. 무슨 케이크 안에 귤이 들었냐고 했는데 아주 탱글탱글하면서 달콤한 과즙에 바로 여물었습니다. 다른 메뉴들도 너무 궁금하네요!', 4, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '크레이프롤 너무 맛있어요!! 과일이 한가득 ㅠㅠㅠ 안에 먹고 갈 곳은 없지만 너무 맛있어보여서 한개 포장해서 먹었어요 ❣️ 다음에 기회되면 다른 맛도 먹고싶어여 ㅎㅎ', 3, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '여기 디저트 진짜 너무너무너무 맛있어요. 경기도 사는데도 시간 내서 오는 디저트 샵 ㅜㅜ 뚱카롱도 맛있는데 이번에 새로 나온 롤크레이프가 진짜 대박이에요 흑흑 ㅜㅜ 매장이 협소해서 사람이 많으면 좀 대기해야 하지만 그런건 전혀 문제가 되지 않는 맛이에요. 좋은 재료를 쓰시는 게 느껴져요. 다음에 또 올게요❤️', 31, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '매장에서 먹고 오려고 했는데 자리가 없어서 아쉽지만 그래도 딸기치즈 롤크레이프가 있어서 포장해왔습니다! 포장해와서 먹는데도 존맛ㅠ 너무 맛있게 잘 먹었습니다!', 21, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '인스타보면서 너무 가보고싶었던곳이었는데 겨울가기전에 먹을 수 있어서 다행이에요😂 테이크아웃전문매장이라 안이 좁은게 아쉽긴하지만 크레이프도 쫀득하고 딸기도 맛있었어요!', 72, 14, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '모든 종류의 크레이프를 하나씩 다 먹어봤는데 개인적으론 말차가 젤 맛있는거 같네요! 그렇다고 다른 종류가 맛이 없다는건 아니고 네종류 모두 맛있습니다! 딸기를 좋아한다면 고민하지말고 드셔보시길~~!', 28, 3, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '생크림이 많아서 느끼할지 알았는데 전혀 그렇지 않네요. 팬케이크시트라 헤비하지도 않고 안물려요. 하나 다 먹기 힘들것 같았는데 금방 다 먹었어요. 다음엔 먹방처럼 하나씩 사서 다 먹어보려고요! 매장이 협소해서 테이크아웃만 가능해요. 참고하세요.', 0, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '정말 맛있어요. 포장도 해오고 싶은 맛! 매장에 두 테이블 밖에 없어서 웨이팅 하면 늦에 연락이 올 수도 있어요..ㅠㅠ 다행히 저는 금방 전화가 와서 앉아서 먹었지만, 다들 너무 매장이 좁으니 포장해가시더라구요!', 51, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '사장님~ 딸기치즈롤크레이프 정말 맛있게 잘 먹었습니당 🤠🍓🍰 처음 가봤는데 한정수량이고 인기가 많아 입이 딱 벌어지는 비주얼만 믿고 매장에서 먹을거 하나랑 포장까지 한꺼번에 두 개 구매했어요!!! 포장한거는 냉장고에 보관 후 이틀 뒤에 먹었는데 딸기는 여전히 달달하구 크레이프도 눅눅한 느낌없이 오히려 매장에서 먹었을 때보다 더 맛있어진 느낌이었어요 ! 시간이 지나도 맛있는 케이크 또 먹으러 갈게요♥️ 게다가 마카롱도 정말 다양했는데 궁금했던 마카롱도 먹을거에요 ㅎㅎㅎ', 87, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '진짜진짜 과일도 신선하고 맛있어요 ㅠㅠ 늦게가서 딸기치즈는 못먹고 후르츠 먹었는데 진짜 만족했어요 과일이 신선한게 느껴졌습니다', 118, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '과일이 정말 듬뿍 들은 크레페 롤케익이여서 좋았어요 크림도 맛있고 과일과 조합이 좋아요~ 근데 눅눅한 크레이프 식감은 좀 아쉬웠어요 취향차이일 것 같긴 해요 그리고 믹스베리 히비스커스(?)도 시켰는데 너무 시고 애매한 맛이라 제 입맛엔 많이 별로였습니다 저는 후르츠롤크레이프보다 딸기치즈롤크레이프를 더 추천해용 테이크아웃전문가게라 먹을 수 있는 공간이 매우 협소하므로 일반적인 카페를 생각하신다면 비추고 잠깐 먹고 갈 수 있는 정도의 시간만 필요한 거라면 괜찮을 것 같아요', 37, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '디쟌은 이뿐데 생크림이랑 빵 다 너무너무너무 달아요.. 한입먹고 당황... 이렇게 달아도 되나요... 건강을 해치는 맛인데요 이건.. 이렇게까지 안달아도 될거같아요..!', 28, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '이렇게까지 인기가 많은 곳인지 몰랐어요. 12시 45분쯤 도착해서 첫번째로 들어갔는데, 이후로 점점 웨이팅이 늘어나더니 카페에 들어간 이후에 계단 밑까지 쭉 늘어선 줄을 보고 일찍 가길 잘했다 생각했어요!! 크레이프롤 치즈맛과 딸기가 너무 잘 어울려요. 산미없는 아메리카노 좋아요! 개인적으로 마카롱은 버터필링이 좀 느끼해서 아쉬웠어요.', 36, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '인스타로만 보다가 드디어 사본 일쩜오플로어! 딸기마카롱에 딸기가 싱싱달달해서 맛있어요. 마카롱 가격은 조금 있지만 보장되는 맛인것 같아요! 근데 꼬끄가 쫀득하진 않았어요(냉동안하고 먹긴했어욤)', 13, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '여러개를 샀어요! 다 먹어보진 못했지만 무난하게 먹을만해요~ 과일이 들어가있어 빨리 먹어야해요! 매장은 협소해서 포장위주로만 될 것 같아요~(테이블 2개)', 15, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '휴 일쩜오플로워 마카롱은 말해뭐해요! 쫀득하고 너무 달지 않은 필링에 계절과일 듬뿍! 근데 케이크는 빵 시트가 너무 퐁신하지 않고 으깨지는 그런 느낌이라아쉽네요 ㅜㅜ 여기 사장님 너무 친절하고 품절될까바 예약해서 갔는데 또 가고싶은곳이에요^^', 46, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '노키즈존이라는 차별이 아무렇지 않게 만연하고 있는 사회에서 꼬마 손님에게 친절하고 상냥하신 사장님! 꼬마 손님을 대하시는 모습을 보면서 제가 다 기분이 좋았습니다. 맛도 훌륭하지만, 사장님의 그런 마인드에 감동받고 왔습니다. 6주년이라고 붙어있던데 오랫동안 잘 되는 가게는 역시 이유가 있다고 생각합니다. 네이버 영수증 리뷰 처음으로 씁니다. 리뷰 쓸 생각없이 습관적으로 받아온 영수증인데 받아오길 정말 잘했다는 생각이 듭니다. 꼭 다시 방문하겠습니다!', 40, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '롤케익 마카롱 넘이뻐요 여심저격 ㅎㅎㅎ 포장도 이뻐서 선뮬용으로 좋을것 같아요 딸기크레이프 맛은 우리가 아는맛? ^^보통이예요', 71, 11, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '일쩜오에 드디어 체리포레누아 등쟝!!!!!!! 체리왕창 시트촉촉 초코짱맛bb 여전히 디저트는 짱짱맛있고 갈때마다 항상 친절하게 인사해주셔서 너뮤 죠아요!!', 69, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '조개롱보다는 뚱카롱이 맛있고 전체적으로 꼬끄가 별로에요ㅠㅠ 딱딱한거, 숙성기간 지나서 너무 무른 것... 네개 샀는데 쫀득한거 하나도 없었음 비싼데 아쉬움, 필링 가득하고 비쥬얼은 예쁨!', 41, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '여태 먹은 마카롱 중 여기가 제일 맛있어요 마카롱이 너무 달아서 하나 이상은 먹기가 힘든데 일쩜오플로어 마카롱은 계속 먹을수 있을 정도오 적당히 달아서 너무 좋고 맛나요!!! 그리고 너무 친절하세용🙂', 18, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '소문듣고 벼르다 찾아갔는데 생각보다 맛이 평범해서 놀랐네요... 가격도 너무 비싸고.. 마카롱 크기 자체는 크지만 맛은 보통. 마케팅 효과인듯', 37, 2, 'BAD', SYSTIMESTAMP);
