INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '일쩜오플로어'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '아기자기한 집에 마카롱이 예쁘고 뚱카롱치고 크림이 느끼하거나 많이 달지 않은 편. 과일마카롱이 매우 맛있음. 가격 값 하는 마카롱 맛집. 재방문 의사 ⭐⭐⭐⭐⭐', 44, 9, 'GOOD', SYSTIMESTAMP);
