INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '디자인도 너무너무 귀여운데 고를 수 있는 종류도 많았고 가격도 합리적이라서 구매했어요🩷 실물을 사진이 담지 못하네요 ㅜㅇㅜ 진짜 귀엽고 예뻐요!! 금손 사장님..🥹💛', 23, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '갑작스럽게 주문드렸는데ㅠㅠ 여태까지 제작한 케이크 중에 제일 예뻐요!! 다음에도 홍대에서 축하 할 일 있으면 여기서 하려고요!! 사장님도 너무 칼답에 친절하시고 맛도 초코맛 있어서 너무 좋았어요💓💓', 29, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '까먹고 있던 친구생일을 급하게 챙기게 되었어요! 아무리 급하게 챙겨도 그냥 평범한 케이크로 주기 싫어 여기저기 인스타를 뒤져보다가 너무 귀염 뽀짝해서 이건 사야해!! 하고 급하게 레터링 케이크 당일제작이 가능한지 여쭤봤답니다ㅠㅠ 카톡으로 문의를 드렸는데 빠르게 답장을 주셔서 바로 매장으로 날아갔어요ㅎㅎ 방문하니 그자리에서 바로 레터링해서 주셨습니다ㅎㅎ 다음달에도 친구생일  챙기러 재방문할꺼에요!', 50, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '이틀 전에 예약했는데도 예약이 가능해서 좋았어요!! 디자인도 디테일하게 변경 요청드렸는데, 원하는 모양으로 너무 예쁘게 잘 그려주셔서 만족스러워요🫶🏻 예상했던거 보다도 훨씬훨씬 더 예쁘게 나와서 다음에도 또 이용할 것 같아요✨ 특히 캐릭터 너무 예쁘게 잘 그려주셔서 진짜 귀여워요ㅠㅠㅠ❣️', 31, 2, 'GOOD', SYSTIMESTAMP);
