INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '친구 케이크 선물용으로 주문했어요 !! 친절하시고 너무 귀여워요 …… ( ¯ ¨̯ ¯̥̥ ) 다음에 또 주문할 일 있으면 하려구욧', 44, 1, 'GOOD', SYSTIMESTAMP);
