INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '요즘 케이크가 너무 비싸서 ㅠㅠ 고민중이었는데 이렇게 귀엽구 !!! 가격도 적당한 케이크 집이 있다니 감동 그 잡채였습니다 .. 다음에도 또 이용할게요 .. 💗💗', 8, 3, 'GOOD', SYSTIMESTAMP);
