INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '급하게 연락드렸는데도 불구하고 너무 친절하게 응대해주시고 준비해주셔서 감사했습니다!! 케이크도 너무너무 귀엽고 맛있어요~ 다음에 또 오겠습니다🥹💖', 0, 2, 'GOOD', SYSTIMESTAMP);
