INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '주문제작케이크는 맛없다?의 인식을 깨준 대존맛 홍대 크림온케이크! 그 이후로는 특별한 일이 있을때마다 주문하는 케이크 맛집이에요ㅠㅠ 응대도 빠르시고 원하는 디자인을 찰떡같이 캐치하시고 매번 만족스럽게 만들어주시는 사장님❤︎ 디자인도 예쁘지만 케이크 먹는 사람마다 다 맛있다며 놀랠정도로 맛있는 주문제작 케이크 맛집이에용 ㅠㅠㅠ 제일 친한 친구 브라이덜샤워 할때도 믿고 주문할 정도면 말다했죠 뭐,,혹시나 고민하시는분들이 계시다면 꼭 한번 주문해보세요! 이런 맛집은 사라지면 안되니까 사장님 건강하셔야해요?🩷', 113, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '매장이 아기자기하고 넘 예뻐요 !! 사장님도 친절하시고 친구랑 10주년 기념 케이크를 주문 제작하였는데 근처 케이크 집들에 비해 가성비도 좋고 맛있을 거 같아요 😝 귀여운 초들도 많이 구비되어 있는 크림온케이크 추천함니당 🫶🏻', 51, 11, 'GOOD', SYSTIMESTAMP);
