INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '도시락케이크집 중에 제일 그림도 잘 그려주시고 가격도 좋아서 6번 이상 주문할 정도로 만족스러워요!!! 이번에도 아빠가 좋아하실 것 같아요!!', 42, 2, 'GOOD', SYSTIMESTAMP);
