INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '진짜 케이크가 너무 예쁘고 가성비가 좋아요 ㅠㅠ 그리고 사장님이 진짜 친절하시구 답장도 엄청 빠르세요 가게가 작구 아기자기하고 청결하게 운영되는 것 같아요 친구 생일축하하면서 알게됐는데 너무너무 좋은 가게인것같아요 앞으로도 많이 이용할것같아요 가성비 짱짱!!!', 36, 3, 'GOOD', SYSTIMESTAMP);
