INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '크림온케이크 리뷰 보고 예약했어요! 친구 퇴사 기념으로 주문 했는데 너무 귀엽고 가성비도 좋아서 특별한 날에 준비하면 너무 좋을 것 같아요!!🫶 저 말고도 거의 10팀 정도 있던데,,, 인기 있는 곳이라는게 실감이 납니다!❤️', 8, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '사장님께서 전역 케이크인거 아시고 초록색 박스, 리본 포장을 예쁘게 해주셨어요!!🥹💚💚 사장님 진짜 센스있으셔서 너무너무 감동 받았습니다ㅠㅠ 완전 친절하시고, 케이크 진짜 맛있어요!!ㅎㅎ 홍대에서 케이크 픽업 할 일이 생기면 무조건 재방문 할 예정이랍니다~!~~! 세심한 사장님 번창하세요오ㅎㅎ🤍', 62, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '전날 예약했는데 당일예약도 된다고 하더라구요! 기본 디자인도 너무 귀엽고 사장님 금손이신 거 같아요~ 친구가 너무 좋아할 거 같아서 두군거려요🥰 가성비 최고입니다!!', 39, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '케이크 너무 예뻐용! 선물할건데 딱 제가 원하는대로 만들어쥬셨어요 ㅋㅋㅋ가게도 너무 예뻐용 ㅋㅋ주변 가게랑 비교해도 가격이 가장 합리적인데다 솜씨도 너무 좋으셔서 잘 선택한거같아용', 54, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '당일 레터링케이크 클라스... 말잇못.. 실화인가요?? 여러분 당일케이크인데 이렇게 이쁠수가잇냐구요ㅠㅠㅠㅠㅠㅠ 크림온케이크 강추합니당 ❤️🩷❤️🩷❤️🩷❤️🩷 참고로 오늘 아침 접수해 점심에 받았습니다. 사장님 복받으세요 ㅠㅠㅠ 감사합니다!!', 42, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '도시락 케이크는 처음이라 어떻게 해야할지 잘 모르는데 고정 디자인도 있고 심지어 너무 귀엽거 너무 예쁘게 잘 해주셔서 너무 만족합니다ㅎㅎㅎ', 130, 26, 'GOOD', SYSTIMESTAMP);
