INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '여긴 늘 디자인이 예쁘고 주문했던대로 나와요! 사장님이 금손이신 것 같아요 중요한 날에는 늘 믿고 방문합니다 !! 맛도 정말 맛있어요 근방 최애 도시락케이크 집입니다!', 20, 7, 'GOOD', SYSTIMESTAMP);
