INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '케익 너무 기여워용!!! 친구가 푸우 환장하는데 너무 기엽다고 하네용🎈🧸 케익도 너무 마싯고, 친절하게 요청사항 잘 들어줘서 좋음🩵  다음에 또 주문할듯!!! 그리고 사장님 좀 예쁨ㅋㅋㅋㅋㅋㅋㅋㅋ👍', 2, 10, 'GOOD', SYSTIMESTAMP);
