INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '케이크 귀엽고 예쁘고 사랑스럽고 다 했네요!!ㅎㅎ 친구가 케이크 받고 너무 행복해했어요!! 귀여워서 못 먹겠대요ㅎㅎ 퇴근길+폭우+강풍+교통 혼잡으로 픽업하겠다고 말씀 드린 시간보다 30분이나 늦었는데 천사같은 사장님께서 이해해주셔서 정말 감사했어요!! 케이크도 예쁘고 맛있는데 사장님까지 친절하시고.. 덕분에 행복하게 친구 생일을 축하해줄 수 있었어요! 다시 한 번 감사합니다♥', 34, 8, 'GOOD', SYSTIMESTAMP);
