INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '케이크 주문할 때 애용하는 곳이에요!! 벌써 3번째 주문인데 케이크가 진짜 맛있고 귀여운데 당일 주문도 가능해서 넘 좋아요!! 다음에 또 주문할게요🥰🥰', 34, 8, 'GOOD', SYSTIMESTAMP);
