INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '귀염뽀짝한 초들이 한가득이네요🍰☀️🌈 가자마자픽업준비해주실때 넘 귀여워서 찍었네욤 케이크는 먹느라 사진이…없네요 담번에는 케이크사진도 함께리뷰로 올릴게용!!!!! 넘맛있고 레터링케이크중에 젤 맛있었어요!!😝😍 재주문하러올게요🙂🙂', 50, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '지인소개로 알게되서 구매했어요🙂 피규어만 선택하고 알아서 디자인 요청드렸는데 너무예뻐요 시나모롤에 빠진 아들 .. 선물도 시나모롤, 케이크도 시나모롤로 다 맞춰서 파티해줬더니 너무 좋아하네요', 13, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '재방문 의사 없습니다 주변에 케이크집 많으니 다른 곳 이용할게요 세시간 픽업 시간 늦을 것 같아서 여쭤봤는데 답장은 안될 것 같다고 하시더군요 .. (이후 정 어려우면 해준다고하긴함) 제가 뭐 당일에 디자인을 바꿔달라, 픽업을 안하겠다는 것도 아니였는데요.. 냉장고 보관 세시간 해주는 게 어렵다시네요.. 그래서 그냥 왔다갔다 정 시간에 맞춰 픽업해왔습니다 이용자분들는 참고하세요', 15, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '기존에 집 근처에서 이용하던 도시락 케이크 업체가 월, 화 휴무라 홍대에 방문하는 김에 근처에 괜찮은 곳이 있나 찾아 보다 알게 된 크림온케이크 ◡̈⋆* 앞으로 도시락 케이크 예약은 무조건 여기입니다 ..! 일단 당일 예약이 가능하다는 점이 가장 큰 강점이고, 지난 고정 디자인도 주문이 가능하다는 점이 두 번째로 큰 강점인 것 같아요 제가 원했던 디자인이 11월 고정 디자인이라 당연히 주문이 안될 거라고 생각했는데 되는 데다가 따로 신경쓰지 않아도 잘 어울리는 색으로 문구를 적어주셔서 진짜 너무 너무 만족스러웠어요 ! 케이크 안먹는 남자친구가 한 입 먹자마자 너무 맛있다고 연거푸 먹었을 정도로 느끼하지 않고 깔끔한 맛이에요 덕분에 프로포즈 성공했습니다 번창하세요 🥹❤️', 36, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '처음 방문인데 사장님께서 친절하게 잘 설명해주시고 제가 급하게 부탁드렸는데 빠르게 작업해 주셨어요 그리고 케익이 이쁘고 정말 맛있어요!!! 다른 친구들 생일 때 또 갈게요 😀', 32, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '생일 축하 케이크 주문했어요 주문 케이크가 일반 케이크보다 가격대가 있다보니까 조금 고민되었는데 너무 예쁘게 만들어주셨을 뿐더러 세세하게 주문하지도 않았는데 알아서 캐릭터에 맞게 색 조합을 잘 해주셨어요 감사합니다', 15, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '보라색 컨셉으로 생일 스냅 촬영을 해서 보라색 케이크가 필요했는데 너무너무 예쁜 케이크를 원하는 색상에 디자인으로 만들어주셔서 정말 만족스러웠어요!💟 이전에도 지인에게 줄 생일케이크 주문했을 때 잘 해주셔서 또 갔던건데 주문케이크는 계속 이곳으로 갈 것 같아요ㅎㅎ', 47, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '각각 예약일 2주전 두번 주문넣었는데 한개는 주문 누락으로 못받았어요.. 중요한날 필요해서 미리 상담진행하고 찾으러갔는데 정말 황당하고 허무해요... 당장 다시 만들기엔 시간이 오래 걸리고 대처방안이 없는게 아쉽더라구요 다음날 받은 티아라케이크는 위에 장식이 30분만에 가지고오는동안 다 떨어져서 안예쁘네요ㅠ', 15, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '전날 예약했는데 바로 받아주셨어요! 고정디자인이 있어서 그건 가능하다고 하시더라구요 다행히 2월 디자인이 예뻐서 그걸로 결정해서 진행했습니다 모임용으로 가져간건데 다들 너무 만족하면서 먹었어요 ! 감사합니다 도시락케이크 화이트 주문했는데 크림치즈 맛이 강해서 치즈케이크 같은 느낌이 드는 케이크였어요', 68, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '디자인이 너무 귀여워요! 깜짝선물로 넘좋아요! 급하게 예약했는데도 추가 요청사항도 들어주시고, 픽업 시간도 조정해주셔서 감사했어여~', 1, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '크림온케이크'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '레터링 케이크 주문했는데 사장님이 마음대로 디자인이랑 색깔 바꿔놓으셨어요. 칙칙해보일까봐 호의로 그러셨다는데 그러면 레터링 케이크 왜 하나요…?? 처음에 너무 당당하셔서 그냥 나왔다가 생각할수록 어이없어서 다시 돌아가서 말씀드렸습니다. 소비자가 원하지도 않았고 애초에 레터링 케이크의 취지와 벗어나는데 호의는 아닌듯 싶네요. 당시에 그냥 핑계거리로 들렸지만 뒤에 일정이 있는 관계로 급하게 가야해서 나왔습니다. 다음부터는 주의해주세요.', 14, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '동생이 좋아하는 쿠리노키제빵! >_< 합정 온 김에 사 가려고 들렀어요. 쿠리노키제빵은 다양한 종류의 일본빵을 팔고 있는데 멜론빵, 말차빵, 쿠마빵, 야키소바빵 등 먹음직스러운 빵들이 많아서 고민이 정말 많이 되더라고요! ㅠㅠ ㅎㅎㅎ 직원분께 잘나가는 빵도 추천받았는데 친절하셔서 좋았습니다. 사실 한국어를 잘하셔서 한국분인줄 알았는데 일본분이시더라고요! >_< 이번엔 주말 오후에 방문했는데 빵이 많이 나가서 다음엔 조금 더 일찍 방문할 예정입니다! ㅎㅎ', 33, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '꼬마소금빵 2,000원 빵 오 쇼콜라 4,000원 말차 소라빵 2,600원 유자단팥빵 2,000원 오렌지쇼콜라(소) 2,500원 이전부터 궁금했던 쿠리노키제빵!!! 소금빵은 바게트 맛이 나면서 묵직한 느낌이예요! 특히 신기하고 맛있었던건 유자단팥빵!🥰 안에 앙금이 있는데 유자맛이예요! 상큼하니 적당히 달달하고 빵이 쫀득하니 넘 맛있어요! 담에 다른 단팥빵도 먹어보고 싶어요!😆 친절하고 매장 깔끔해요! 매장에서 취식도 가능해서 쪼아용!👍', 1, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '총 6가지의 빵을 샀어요 야키소바빵 초코빵 카레빵 명랑감자오니기리 새우카츠버거 아몬드크로아상 포장 내돈내산 리뷰 https://m.blog.naver.com/mar_quito/223934784075', 14, 7, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '일본빵으로 유명한 쿠리노키 드디어 방문했네요 야키소바빵도 맛있고 명란바게트도 맛있고 진짜 모든빵이 다 중박 이상 하는 거 같아요 다음에 또 방문하고 싶어요', 10, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '일본에서 먹던 야끼소바빵이 그리워서 방문했는데, 역시 일본인 사장님이 만드셔서 그런지 그 맛 그대로입니다! 전혀 불지 않은 야끼소바빵이라니,,, 이걸 찾아 그동안 얼마나 국내 빵집을 헤매고 다녔는지 몰라요 ㅠㅠ 한입 먹는 순간 일본에 다시 간 것 같은 기분이 느껴졌습니다 ㅠ 말차소라빵은 안에 말차크림이 한가득 들어차 있는데 아주 부드러우면서 진한 말차맛이 입안 가득 느껴져서 넘 행복했어요.. 명란감자 오니기리빵은 감자가 메인이라 그런지 식사 대용으로 먹어도 괜찮을 정도로 포만감이 있었어요. 안에 명란이 가득한데 짜지 않아서 참 신기했습니다. 카레빵, 메론빵 등등 먹어보고 싶은 빵들이 정-말 많았는데 다음 약속 이슈로 못 먹어봐서 넘 아쉬워요 ㅠ 담에 이 빵집 때문에 합정 다시 와야겠다 생각했습니다!', 2, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '이름대로 일본 스타일의 빵을 판매하는 매장입니다. 일단 가격대가 적당해서 좋았네요. 빵은 밀도있게 단단한 편이어서, 개인적으로는 만족했습니다. 특히 식빵이 샌드해먹기 좋은 밀도였어요. 다른 빵들도 기대해봅니다.', 2, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '일본식 베이커리 중 가장 먼저 떠오르는 곳이다 빵속의 어묵참치 깻잎이 들어있는 치쿠와 빵, 빵속의 야끼소바가 들어있는 야끼소바빵. 빵속의 왜 식사, 밥반찬같은게 들어있나 싶지만 빵과 어울리고 간도 잘 맞다.', 1, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '구매한 대부분의 빵들은 다 평균 이상 맛이었습니다! 야키소비빵은 안에 내용물이 조금 부족해 아쉽긴 했어요...ㅠㅠ 근데 지금보니 봉투값을 받았네요..... 현장에서 그냥 담아주셨던 걸로 기억하는데.. 다음엔 물아봐주셨으면 좋겠습니다', 29, 10, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '오사카에서 먹었던 야키소바빵이 그리워 찾다가 방문하였는데 정말 다양한 빵이 있어 여기가 일본인가 순간 착각이...ㅋ 근데 비쥬얼에 비해ㅡ맛은 인상적이지는 않더라고요 재방문은 안할듯', 20, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '지나가다 궁금해서 들렸어요~ 건강한 맛이에여!! 먹어도 속이 편할거 같은 빵!!! 다음엔 메론빵과 독특한 메뉴를 먹어보겠어여~~~~~', 66, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '빵 종류 다양하고 맛있어요! 이 정도 퀄리티와 맛에 이 가격이면 저는 가성비도 매우 좋다 라고 여겨졌어요 그렇기때문에 점내에서  커피랑 빵 먹고 그냥 가기에는 테이크아웃을 안 할 수 없는 비주얼과 맛입니다 :) 매장 깔끔하고 화장실까지 깨끗하게 정돈되어 있어서 무조건 여러 번 가고 싶은 곳입니다 :) 선물용 박스가 준비되어있다면 빵선물도 하고 싶어서 다음에 여쭤봐야갰네요', 9, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '종종 들려서 단품 빵만 사다가 단팥식빵을 샀는데, 너무 맛있었어요🥹 완젼 취향저격 당해서 행복한 맛이었습니다 가격이 저렴한 만큼 가성비가 좋은 가게이지만… 딘팥러버는 가격을 올리고 단팥 더 가득한 식빵조합도 먹고 싶어지더라구요 밤을 넣거나 하는 ㅎㅎ 그래도 넘 귀엽고 맛있어요', 54, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '맛있어보이는 빵이 너무 많아서 고르기 너무 힘들었어요.. 선택한 빵 모두 맛있구ㅠ 가격도 너무 좋아요ㅠㅠ이 가격에 이렇게 맛있는 빵이라니.. 매일 먹고싶어요 뱅오쇼콜라도 맛있구 차조기?빵은 어묵 들어있는데 색달라서 좋았구 다른것도 다 맛있어요. 다음번에 가면 안먹어본 빵 다 사먹어보려구요. 매장에서 커피랑 음료도 팔아서 빵 산 다음 바로 같이 먹을 수 있어서 좋아요. 완벽해요 진짜🥰🥰', 30, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '쿠리노키의 일본식 빵 좋아해서 가끔 갔는데 갓 구워진 소금빵 쟁반 위에 파리가 가득가득(한 두마리가 아니었어요) 하더라구요.... 비닐 하나 안 덮여있는데... 입맛 떨어져서 비닐 포장된것만 몇개 사서 나왔어요. 신경 좀 써주세요 ㅠㅠ', 2, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '메론빵을 좋아해서 검색하다 떠서 방문해 봤어요! 빵 종류가 진짜 다양해서 다 먹어보고 싶었어요ㅠ 기본 메론빵부터 초코칩, 말차맛이 있고 귀여운 얼굴의 빵이 있어서 안 살 수가 없었어요 ᵒ̴̶̷̥́ ·̫ ᵒ̴̶̷̣̥̀ 가격도 저렴해서 너무 좋아요~~', 16, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '빵종류가 어마무시하게 많았고 가격도 굉장히 합리적이네요! 나름 빵순이라 생각해서 아는 빵이 많다 생각했는데 오니기리빵등 첨 보는 빵이 많았네요!!', 46, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '직원분들이 너무 친절하시고 올리브 치아바타, 바게트 너무 맛있어요! 특히 올리브 치아바타는 다른 곳에 비해 올리브가 많이 들어가 았어서 더 맛있고 좋아요 ㅎㅎ', 1, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '명란 오니기리는 처음 먹어보는맛인데 식사 대용으로 괜찮을듯 소금빵은 별로 유자단팥 개인적으로 호! 유자맛 흰앙금?이라 안물렸어요 쿠마빵은 그냥 다 아는 슈크림빵맛 근처 가면 또 가볼 의향은 있어요', 90, 17, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '일본식 베이커리 쿠리노키제빵 영수증은 홍대베이커리로 나오네요 타마고샌드랑 야끼소바빵 blt샌드랑 멜론빵 등을 샀는데 가격도 적당하고 맛도 괜찮았어요', 72, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '야끼소바빵이 먹고 싶을 때마다 갑니다. 메론빵도 맛있고요. 소금빵이 작아서 가볍게 먹기 좋습니다. 타마고샌드나 치킨칠리버거는 아침에 먹으면 든든합니다.', 33, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '아기자기하고 다양한 일본빵이 가득한곳 홍대 아오이 토리와 비슷해요~~ 근처가면 종종 들러오는 빵집 요즘 빵값 너무 비싸지요 하지만 여기는  그래도 합당한 가격에 다양한 맛을 볼수 있어 좋아요 메론빵 그렇게  좋아하지않는데 여기가면 꼭 하나는 사먹게 되는곳 ㅎㅎㅎ 커피 마실 공간도 있고 깔끔하고 귀여운빵들 구경해도 기분좋아지는 곳입니다', 39, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '맛있고 종류도 다양한 망원동 일본빵집 쿠리노키🤍 지난 달에 와보고 너무 맛있어서 재방문했어요~ 버거류, 에그마요, 메론빵, 소라빵 다 맛있어요ㅎㅎ 집 근처였으면 정말 자주 갔을듯🥹 + 푸딩은 바닐라맛보다는 계란맛이 많이 나서 개인적으로 아쉬웠어요', 27, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '디저트 성지 망원동에서 감히 원탑이라 말해봅니다🥹 세상에 너무 맛있어요...! 종류도 다양하고 맛있고 가격도 엄청 저렴해서 놀랐어요. 특히 야끼소바빵이랑 메론빵은 찾아보기 힘든데 감동🤍 역시 일본빵집!! 재방문의사 200%', 34, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '여긴 단팥식빵 진짜 맛있어요. 자주갑니다. 그런데 오늘먹은 데리야끼 치킨버거 왜이렇게 짜요? 깜짝 놀랬어요!! ㅠㅠ 지난번에 맛있게 먹어서 또 재구매한건데 오늘 소스가 덜 섞인건지 ㅠㅠ 너무 짜서.. 다 못먹었어요ㅜㅜ...', 11, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '두번째방문에는 밤 단팥빵, 말차메론빵, 카레빵을 먹어봤다. 일본 베이커리하면 떠오르는 야끼소바 빵, 메론빵, 카레빵을 볼 수 있어서 좋아하는 곳이다. 카레빵이 느끼하지 않고 부드러운 빵이 카레와 잘 어울려서 너무 맛있다. 추천메뉴는 단연 카레빵', 51, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '여긴 합정이나 망원가면 무조건 가줘야해요. 단팥식빵이 최곱미다! 무조건 드세요!! 마감전시간이라 그런지 서비스 빵 받았는데 이것도 너무 맛있어요!', 21, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '新しく見つけた日本のパン屋さん♡ とりあえずベーコンエピがあることにテンションアップ！ 色々お惣菜パンも豊富で、全部美味しそうだったー！ また行きたいパン屋さん！ ホンデの青い鳥よりも私はクリノキ派かも！ 또 가고 싶은 일본 빵집♡ 홍대에 있는 일본빵집 아오이토리 보다 저는 쿠리노키가 좋을 것 같아요😋', 77, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '빵 종류도 다양하고 아기자기한 느낌이라서 간단한 간식이나 아점용으로 괜찮은 것 같아요!! 단팥빵 종류도 많고 크림류도 많아서 다음엔 더 쓸어오려고요!! 자세한 후기는 블로그를 참고해주세요! https://m.blog.naver.com/purpura1126', 47, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '우리학교 출판사 근처에 있는 빵 맛집이라고 친구가 추천해서, 밤 8시 지난 시간에 갔더니 빵이 얼마 남지 않았네요. 포장해 와서 따끈한 차와 함께 친구들과 담소 나누며 잘 먹었어요. 초코넛 스콘과 허니크림치즈 먹었는데, 별로 달지 않고 깔끔하게 맛있어요. 소금빵도 맛있다는데 품절이어서, 다음엔 소금빵과 다른 빵도 맛보고 싶어요.', 20, 8, 'GOOD', SYSTIMESTAMP);
