INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '야끼소바빵 소금빵 타마고샌드 구매했는데여 타마고샌드는 진짜 계란박에 안들어있어서 조금 아쉽네여ㅜㅜ 아삭한 양파같은 식감이있으면 더 좋을거같아요!', 20, 8, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '쿠리노키제빵'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '일본분이 운영하는 로컬빵집입니다 이집에 시그니처인 소금빵과 아메리카노가 정말 잘 어울리는 조합입니다 근처에 오시면 꼭 들려주세요', 34, 3, 'GOOD', SYSTIMESTAMP);
