INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오버트 합정'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '생각보다 자리는 협소하고 화장실 예민하다면 비추 커피맛있고 특히 에그타르트가 생각보다 맛있어서 놀랐어요 크로와상이랑 뺑오도 굽는거 같은데 파이지까지 전부 만드는지는 모르겠지만 베이커리류도 추천합니다', 12, 1, 'GOOD', SYSTIMESTAMP);
