INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오버트 합정'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '기대한만큼은 예쁘진않았지만 친구랑 수다떨고 휴식하는 편안한 카페였습니다. 커피음료 종류가 꽤 맛있었어요. 디저트가 예쁘고 맛있어보였는데 식사 후라서 패스 ㅠㅠ 가게 한쪽에서는 공부 하는 사람도 있어서 집중하기도 좋아보이는 곳이었습니다', 118, 25, NULL, SYSTIMESTAMP);
