INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오버트 합정'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '커피 원두를 고를 수 있어서 좋구요✨ 커피가 맛있습니다🙂 리필도 되니 더- 좋아요💖 게다가 베이커리는 기대하지 않았는데 맛있어서 깜짝 놀랬습니다😮 주차가 안 되는 것이 아쉽지만, 커피와 디저트가 맛있어서 만족했던 카페에요!', 34, 9, 'GOOD', SYSTIMESTAMP);
