INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오버트 합정'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '로얄밀크티,바닐라라떼 제가시킨 로얄밀크티는 우유맛도,티맛도 좀 약한편이라 좀 아쉬웠어요. 친구가 커피 종류가 맛있다니 담에 오면 커피류로 도전해보려구요ㅎㅎ', 12, 4, NULL, SYSTIMESTAMP);
