INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오버트 합정'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '여기 갈때마다 알바생이 일하기 귀찮은건지… 틱틱거린다고 해야하나 옷가게 구경할때 눈치주는 점원말투에요. 매번 처음 갔을때 남자 알바생은 친절했던것 같은데', 79, 12, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오버트 합정'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '크림라떼 바닐라 시켰는데 너무 맛있어요! 아메리카노를 무료로 리필 가등한다고해서 아이스로 타크 받았어요 시간이 없어시 다 먹을수없었는데 맛났당 그리고 제가 일본사람이라서 말을 잘 못하는데 직원님들이 친절하게 천천히 설명해주셨어요,감사합니다~~', 68, 11, 'GOOD', SYSTIMESTAMP);
