INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오버트 합정'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '크림에 이끌려 찾아온 이 곳 크림카푸치노라니😘 크림이 2번 들어가는데 아래는 부드러운 크림 위에는 케이크 생크림! 되게 꾸덕해요 모카랑 플레인 있는데 모카 선택했는데 넘 맛있더라고요 크림라떼도 존맛🥹 근데 대박인게 아메리카노 무료 리필이 된답니다아 너무 신기했어요 디카페인으로 시켰는데 사실 제 스타일은 아니었지만 커피 좋아하시는 분,오래 공부하시는 분들한테 딱일듯해요', 12, 6, 'GOOD', SYSTIMESTAMP);
