INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오버트 합정'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '🏷️ 뷔릴레라떼, 크림모카라떼, 크로아상 플레이트🏷️ 친구가 여기 뷔릴레라떼 궁금하다고 해서 먹으러 왔는데 달달하고 부드럽고 맛있었어요! 근데 크로와상은 너무 달아서 조금 물려요 아메리카노랑 먹으면 괜찮을 듯', 34, 5, 'GOOD', SYSTIMESTAMP);
