INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오버트 합정'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '분위기 좋은 카페발견~ 베를린을 가보진않았지만 베를린 감성을 담은 카페 (뭐래니~~~~) 커피 맛있고 디저트도 괜찮으니 성공적. 이 집 잘 하네. 여기 좋아요. #합정카페 #오버트합정 #드래곤스카이 #드래곤스카이의싱글라이프', 33, 3, 'GOOD', SYSTIMESTAMP);
