INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오버트 합정'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '뺑오쇼콜라와 라떼 주문 바닐라 아이스크림과 생크림, 바나나 조각을 곁들인 패스츄리 빵이 나쁘지는 않았지만 시그니처는 아닌듯... 좌석이 애매하게 불편해서 재방문할지는 모르겠다 🥲', 1, 9, NULL, SYSTIMESTAMP);
