INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오버트 합정'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '예전에 와보고 뺑오쇼콜라 플레이트가 넘 생각나서 또 왔는데 역시 맛있어요 ㅎㅎ 로얄밀크티는 찻잎가루가 넘 많아서 아쉬웠어요 ( ᵒ̴̶̷̥́ _ᵒ̴̶̷̣̥̀ )', 4, 0, NULL, SYSTIMESTAMP);
