INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오버트 합정'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '세상에.. 이렇게 기분 좋게 방문한 카페는 정말 정말 오랜만이었어요. 메뉴 설명도 친절히 해주시고 음료는 말모.. 너무 맛있었구요, 아메리카노 리필까지 서비스에 감동 받구 갑니닷 끝날 시간 다 되어서 나눔해주신 빵도 맛있었어용 뺑오쇼콜라 추천합니다!! 굿즈도 예뻐서 담에 오면 살 것 같아요🤩', 37, 4, 'GOOD', SYSTIMESTAMP);
