INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오버트 합정'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '시그니처도 마시고싶고 아아도 마시고 싶어서 둘이서 시그니처 두잔, 아메리카노 한잔 주문했어요 음료 픽업하러가니 세잔다 아메리카노로 리필 가능하시다고 하셔서ㅎㅎㅎ 주문시에 말씀해주셨으면 두잔만 주문했을텐데!!! 다음번엔 기억했다가 두잔만 주문할게욥! 테이블이 아주 많이 흔들거려서 앉기전에 다 흔들어보고 제일 고정되어있는곳에 앉을게욥!!', 45, 4, NULL, SYSTIMESTAMP);
