INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오버트 합정'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '공간이 정말 이쁘고 소품들도 감성적이에요! 푸릇푸릇한 공간이 보여서 감각적이고 인테리어 색감도 독특하고 이뻐요! 사진찍기에도 좋지만 음료도 맛있고 디저트도 독특하고 맛있어요 😍 홍대합정핫플이네요 💗', 47, 2, 'GOOD', SYSTIMESTAMP);
