INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '월페이퍼 서교'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '핫초코가 많이 달지 않고 부드러워서 정말 맛있었어요 👍🏻 고급진 핫초코 맛 라떼 러버가 인정한 스팀입니다 ~ 다음 번엔 따뜻한 라떼 먹으러 와야겠어요 연말이어서 크리스마스 분위기 물씬 풍기네요 햇살 잘 드는 창가 아래서 작업하기도 좋고 친구들이랑 수다떨기도 좋은 카페를 발견했네요', 21, 1, 'GOOD', SYSTIMESTAMP);
