INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '월페이퍼 서교'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '최근부터 저녁10시까지 영업해서 처음으로 밤에 와봤는데 낮이랑은 완전 다른 분위기네요! 적당히 어둡고 노래 크기도 적당해서 책읽거나 작업하기 너무 좋을 것 같아용 저녁에도 자주 오려구요 !', 11, 7, 'GOOD', SYSTIMESTAMP);
