INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '월페이퍼 서교'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '나만 알고 싶은데 다들 알아줬으면 하는 카페 1등 의자도 편하고 콘센트도 많아서 작업하러 오기 좋아서 젤 많이 오는 곳..🤫 그리고 일단 음료가 전체적으로 다 존맛임', 33, 4, 'GOOD', SYSTIMESTAMP);
