INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '오늘 방문해서 콜드브루 라떼와 다른음료를 주문했지만 콜드브루는 이상한맛이어서 물어보니 불친절하게 다시해준다는말만 하고 다시해줘서 마셔보니 그냥맹물이어서 어이없어서 그냥 나왔지요 수박쥬스도 별로고 방문자리뷰보고 더운날 갔는데 정말 큰실망입니다 직원들이 불친절하고 맛이 없습니다', 47, 4, 'BAD', SYSTIMESTAMP);
