INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '커피 맛있다길래 찾아왔는데 주문 받아주는 직원분이 그냥 일하기 싫어하는거 티 팍팍내면서 귀찮아하는 표정이고 내가 이럴려고 주말에 여기까지 왔나 싶네요.. 콜드브루는 맛있었는데 초코라떼는 돈주고 사먹기 아까울 정도로물넣은것 마냥 밍밍한 맛이었습니다.', 32, 4, NULL, SYSTIMESTAMP);
