INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '홍대 공영주차장 6번 바로앞 테라스 자리가 넓어서 낮에 커피 마시기 조아여! 사장님이 주문받으시는데 음료 나올때 조금 시간이걸려여^^;;;', 100, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PARKING');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'TERRACE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '두번째 방문한건데 올쩍마다 안경낀 나이좀있는 여직원분 말투부터 정말 너무 불친절합니다~ 열심히 옆에서 일하는 젊은 아르바이트남자분은 참친절하신데.. 손님이 바로 앞에앉아있는 냉장고를 뿌실정도로 쾅쾅닫고 진짜  행동하나하나 넘 불쾌감을 주네요.. 다른데 가야죠.. 머..', 13, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '미숫가루 맛있어요. 망고패션 후르츠도 맛있구요 다만 밤시간가면 매장앞에 오토바이가 늘 10대이상 있는데 입구도 막혀있을때도 있고 흡연구역도 넘 드럽게 사용해요. 그리고 알바분 혼자 넘 고생하는듯.그래서 4점', 20, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '드롭탑 홍대점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '친절하고 자색고구마라떼와 뚱카롱들 맛있네요. 필링이2배 들어갔다고 하더니 촉촉하고 부드러운 달콤함에 반함! 궁금한 거 물어보니 친절히 얘기해주심.', 118, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
