INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '장점: 밸런스가 엄청 좋은 케이크였어요! 단거 잘 못먹는데, 많이 안달고 안에 피스타치오 크림 도 너무 맛있고, 산딸기가 엄청 많고 신선하고 맛있었어요! 단점: 근데 보냉백 필수입니다..ㅠ그냥 무조건 사야돼요..ㅠ16도에 약하게 비오는 날씨였는데, 생크림이 많이 녹아내렸어요. 손에 우산들고 걷느라 평소보다 더 흔들렸겠지만, 산딸기가 몇개는 맥없이 후두두 떨어지더라구요..그게 아쉬웠습니다..예쁜사진 많이 건지고 싶었는데 그러질 못했어요ㅜㅠ 다른분들은 꼭 보냉팩 추가하세요!!', 20, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '여기 케이크가 그렇게 맛있다고 친구들이 추천해줘서 엄마생신날 케이크 예약했습니다. 저는 한번도 안먹어봐서 걱정을 많이 했었지만, 세상에 그 걱정을 다 날려버리는 케이크였습니다. 일단 모양이 너무 이뻤고, 맛은 제가 먹어본 케이크중 완전 최고였어요. (๑˃؂˂๑) 생크림이 진짜 어떻게 이런 맛이? 나지 할정도로 느끼하지도 않고, 깔끔한 맛이예요! 가족들이 모두 맛있다고 칭찬해준건 처음이였습니다. ヾ(*''∀`*)ﾉ♡ 담에도 기회가 된다면 또 주문하고 싶어요!', 47, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '친구들이랑 우연히 갔다가 케익이 너무 맛있어서 생일케익 주문했는데 너무 예뻐서 눈이 즐겁고 너~~무 맛있어서 입도 즐거웠어요! 최고에요!', 68, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '괜히 호텔케이크 비싸고 맛없는거 살필요없어요ㅠㅠ 저는 맨날 슬릿가서 제 모든친구에게 슬릿케이크맥여요... 가격도 적당한데 가격보다 맛도좋고 예쁘고... 가져갈때마다 있는자리에서 바로 싹 다 먹어치워서 냉장고에 들어간적이 없어요... 맨날 다이어트가 실패해요 슬릿때문에ㅠ 흑흑... 저 리뷰쓰는거 정말 싫어해서 다른곳 리뷰 쓴적도없고 이벤트도 절대참여안하는편인데 슬릿은 해요. 맛.있.으.니.까.', 48, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '네번째 슬릿 홀 케이크! 올해에는 첫 슬릿 홀 케이크! 이번 크리스마스 피스타치오 딸기케이크가 너무 맛있었어서 다른 모임친구들 먹여주겠다고 또 픽업했네요. 친구들 기다리며 홀에서 밤 바스크 치즈케이크랑 체리코코 먹었는데, 밤바스크 꾸덕진하니 보니밤 잔뜩들어있어서 맛있었구요, 체리코코는 꾸덕한 초콜릿에 달콤한 즙 가득한 체리가 박혀있어서 게눈감추듯 먹었네요... 그리고 숙소도착해서 먹은 로제케이크는... 정말 감동 그자체. 크림에 딸기맛 가득가득 상콤하고 살짝 짭짤고소한 피스타치오가 너무 조화롭게 맛있습니다... 저 리뷰같은거 귀찮아서 절대안쓰는사람인데 슬릿은 써요. 맛있으니까...☆', 2, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '12월에 벌써 두번째 슬릿 홀케이크 주문이네요! 친구들에게 꼭 꼭 꼭 먹여보고 싶어서 두근두근하며 주문했는데, 다들 먹으면서 이렇게 맛있어도 되냐고 10분만에 먹어치웠어요. 다들 여기 케이크 어디꺼냐고 물어봐서 알려줬구요 ^~^ 제가 슬릿 영업자입니다! 크림까지 딸기향 가득에, 딸기도 새콤달콤하니 맛있고, 시트에 피스타치오 가득... 쫀득달콤 환상적인 맛이었어요... 포장지에 딸기향이 잔뜩 배여서 안에 얼굴묻고 킁킁맡았습니다... (+로 제가 픽업을 1시로잡았는데 약속이 6시로 미뤄진거예요... 혹시 5시로 변경해서 픽업해도 되냐 여쭤봤는데 친절하게 응대해주시고 기다려주셔서 너무너무 감사했어요. 슬릿최고!)', 61, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '제가 딸기케이크를 사실 별로 안좋아해요. 가격만 비싸고 맛이없는경우가 많아서 그냥 사진용 케이크라고 늘 생각해왔거든요. 근데 슬릿에서 처음 딸기케이크먹고 너무 맛있어서 충격받았어요. 그 이후로 기념일때마다 슬릿에서 홀케이크를 주문해서 먹습니다. 다른 화려한 케이크들 예쁘기만하고 맛은 없는경우가 많은데, 슬릿은 예쁘면서 또 진짜 맛도 좋아서... 다이어트중인데도 못참고 반판 먹어버렸네요ㅠ... 후회없는 증량이었어요.', 31, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '홍대에서 전시회 보고 생과일 조각케이크 사진 보구 달려왔어요!! 복숭아 요거트 케이크 완전 맛나용! 히비스커스 베리랑 아메리카노도 맛있어요~! 카페 분위기도 좋구용 다들 데이트 코스로 추천합니다❕', 37, 9, 'GOOD', SYSTIMESTAMP);
