INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '혼자 늦은시간 방문했다가 체리코코에 아메리카노 마셨어요 역시나 맛도 음악도 최고 😘🫶🏻 가오픈날 우연히 들러 맛 보고 몇년째 단골이되어 꾸준히 다니는 카페에요 꾸준히 신메뉴 만들어주셔서 감사해요 오래오래봬요오💗 딸기철 기다리겠습니다', 42, 10, 'GOOD', SYSTIMESTAMP);
