INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '디저트 너무 맛있었어요 9천원이 아깝지 않았다구요 커피도 마셔본 곳중에 진짜 제일 베스트 특유의 뒷맛이 남지도 않았고 넘 꼬소했어요 🖤', 23, 3, 'GOOD', SYSTIMESTAMP);
