INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '홍대가면 무조건 맨날 가는 카페 슬릿이에용 ㅎㅎ🧡 여긴 일단 디저트 맛집에다가 감성맛집 ㅜㅜㅜㅜㅜㅜ 이번에 시즌케익으로 나온 메론케이크 강추에요! 그리구 크리스마스때는 무조건 딸기케이크 사셔야돼요ㅠㅠㅠㅠㅠ🩷🌹 거기다 주인분들도 엄청 친절하시구 깔끔 깨끗해요!!', 0, 5, 'GOOD', SYSTIMESTAMP);
