INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '무더위에 신메뉴 맛보러 다녀왔어요🫶🏻 시원한 참외에이드는 참외맛이 가득했고 망고케이크 멜론케이크는 달달한과육 담백한생크림에 촉촉한시트가 다 잘 어울려서 맛있었어요 :) 아 매장에 화분도 많아져서 더 멋있어졌어요 이번 여름도 시원한 커피마시러 자주갈게요🖤', 28, 5, 'GOOD', SYSTIMESTAMP);
