INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '독특한 모양의 케이크가 매력적인 카페에요❤️ 보기도 좋은게 맛도 좋다고 안에 딸기가 가득 담겨있어 상큼 달달하니 맛있었어요. 음료는 아메리카노는 무난한 맛이였지만 티가 참 괜찮았어요! 다음번에 방문해도 저는 티 종류를 먹게되지 않을까싶어요ㅎㅎ 내부는 창가석 빼고는 조금은 어둡고 좁은 편이지만 바로 앉을 수 있는 1-2자리 정도는 비어 있답니다. 착석후 자리 이동은 안되니 참고하세요 ;)', 69, 17, 'GOOD', SYSTIMESTAMP);
