INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '케이크들 맛있음. 여름메뉴로 참외...슬러시? 같은거 마셨는데 달달구리 느낌으로 맛있었음. 좌석이 적어 약간의 운빨도 필요함.', 59, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '🍓딸기케이크가 먹어본 케이크 중에 제일 맛있어요 특히 너무이뻐요!!  위에 햐얀딸기가 이뻐요  크림이 느끼 할수있지만 유자크림으로 새콤하면서 밑에 건조된 딸기도 케이크랑 잘 어울려요🍰', 27, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '다른 가게 리뷰 남기러 왔다가 답글 달린 거 우연히 보고 어이가 없어져서 기존 리뷰 싹 지우고 적습니다. 저는 "다른 곳으로 오해하거나 1인 1음료 안내를 무료로 착각"한 적 없구요, 도리어 음료 무료라는 안내에 모든 음료 해당이냐고 두 번이나 물어봤었습니다. 지난 번 결제 내역 확인해보니까 음료+케잌 가격으로 돼있긴 하지만 저는 분명 음료를 ''선택''해야 된다는 안내가 아니라 ''무료''라는 말을 들었었거든요. 아님 굳이 케이크 가격이랑 맞먹는 음료를 주문할 필요가 없어서요. 신뢰가 각별하신 건 알겠지만 무작정 고객을 매도하는 대신 직원분이 말 실수를 했을 가능성도 염두에 두셔야 하는 거 아닌가요? 뭐... 가게에 악감정이 있는 것도 아니고 여기까지 하겠습니다. 어차피 다신 갈 일 없을 테니까요^^', 7, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '전부터 너무 궁금했는데 딸기시즌에 방문하네요! 디저트도 이쁘고 맛있고 공간도 세련되고 차분하니 좋아요! 여름에 멜론케이크 먹으러 다시 오고싶어요', 47, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '와....여기 카페 케이크 맛집이에요!!! 디저트를 좋아하는 1인으로서 진짜 케이크 맛있는거 보장합니다아아. 우리 동네에도 있었으면 좋겠어요😭 무화과케이크는 무화과가 혜자로 들어있어요. 씨가 오도독 씹히면서 무화과즙이 나오면서 케이크시트에 스며들면서 와.....😍 메론🍈케이크는 메론이 달아요! 그래서 케이크를 한입 입에 넣으면 메론즙이 시트에 스며들면서 메론맛빵 맛 나면서 녹아요! 초코테린느는 꾸우우덕꾸우우덕해요! 카카오가 많이 들어간 느낌이에용🥹 아이스아메리카노 고소햇어요! 산미를 좋아하시면 여쭈어보시면 될 것 같구요 남친은 밀크티 시켰는데 향이 참 좋았어요🥰 카페분위기는 먼가 시크해요! 블랙&화이트 그리고 심플하게 꾸며놓으셨는데 오히려 깔끔라고 시크하고 엣지있어보여용👍', 23, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
