INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '처음 가봤는데 매장 자리도 꽤 많고 인테리어도 깔끔하고 분위기 너무 좋아요! 케이크가 너무 맛있어 보여서 방문한 건데 기대한 것 이상으로 맛있었습니다 ჱ̒ ｰ̀֊ｰ́ ) 앞으로 케이크는 여기서 먹어야겠어요! 무화과 케이크 최고예용 ( ⸍ɞ̴̶̷ ·̫ ɞ̴̶̷⸌ ) 아 블루베리루이보스 마셨는데 이것도 맛있었어여💜', 42, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '아이들과 연극 보러 갔다가 디저트 먹을 만한 작지 않은 카페 찾아보고 들렀어요. 세상 힙한 인테리어에 사장님?들도 힙하고 멋지고 친절하셨어요. 라떼2, 미숫가루, 초코라떼, 산딸기 피스타치오 케이크 주문했는데 음료 다 맛있었고요. 초코라떼에 부드러운 생크림이 올라가 있어서 아이 둘 다 서로 초코라떼 먹겠다고 ㅎㅎ 케이크 취향이 조금은 까다로운 편인데 정말 맛있었어요. 가격대가 저렴하진 않으나 가격 이상 만족스러웠어요. 꾸덕하고 달달한 초코테린느까지 서비스로 주셔서 감동ㅠㅜ 담에 홍대 갈 일 있음 재방문할래요.', 30, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '태어나서 먹은 디저트들 중 원탑입니다... 초당옥수수바스크가 진짜 겉에 뿌려진 소보로? 같은거랑 곁들여먹으면 진짜 맛있어요... 말로 다 표현할 수 없는 조화로운 맛 ,,, 여태 서울 다니면서 어딜 다닌건지ㅠㅠ 이제야왜안건지 후회가 ...!!! 지인추천으로 왔는데 디저트 찐맛집입니다 ㅎㅎ 테린느는 찌인한 춰퀄렛 그 자체고 , 커피도 다크하고 산미없는게 완전 제 츼저 ㅎㅎ 좌석이 매대 안쪽에 따로 있어서 편안하고 여유로운 시간 보낼수잇슘당', 2, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '매장에서 핸드드립이랑 산딸기피스타치오 케이크 먹고 너무 맛있어서 다른 디저트류들도 포장해갔어요 모든 메뉴들이 흔히 맛볼 수 없는 조합인데 여러가지맛들이 다 조화롭게 어울려서 좋았어요! 부드럽고 촉촉하고 느끼하지않아서 또 갈 예정입니다!', 14, 3, 'GOOD', SYSTIMESTAMP);
