INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '피스타치오생딸기 케이크 와 넘 맛있다 치즈케이크도 맛있는데 피생케이크가 쪼금 더 맛있었음...커피도 진하고 괜찮구 무엇보다도 고급스러운 분위기의 카페인듯 하당 ㅎㅎㅎ', 39, 8, 'GOOD', SYSTIMESTAMP);
