INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '매장에 좌석이 은근 많아요! 날만 좀 덜 더웠으면 야외석에 앉아도 좋을 것 같아요 커피도 맛있고 피스타치오케이크도 맛있었습니당', 69, 13, 'GOOD', SYSTIMESTAMP);
