INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '설화로즈 케이크를 먹어보았어요~ 맛있는데 설향딸기는 위에 데코로만 조금 있어서 아쉬웠어요~ 커피는 아메리카노를 마셨는데 맛있었어요!', 117, 20, 'GOOD', SYSTIMESTAMP);
