INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '차분한 분위기의 카페 블랙&화이트 인테리어가 넘 예쁘다. 화장실조차도... 커피도 굿굿 특히 딸기 케이크가 살살 녹아서 넘 맛있었다.', 59, 13, 'GOOD', SYSTIMESTAMP);
