INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '딸기케이크 진짜 맛있어요!! 크림이 진짜 보드랍고 맛있네여ㅠㅠ 바닐라라떼 달달하게 당충전하기 좋아요! 인테리어 좋고 의자도 다른 갬성카페에 비해선 편한 편입니당! 다만 탁자가 무릎근처라 ㅎㅎ 조금 불편하긴 하네염 그래도 좋았어요!!', 48, 2, 'GOOD', SYSTIMESTAMP);
