INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '슬릿 홍대'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '고소하고 깔끔한 커피와 디저트 맛집!!! 🥰커피가 맛나면 디저트가 아쉬운 곳이 많은데 여기는 진짜 빠지는것이 없어요 ㅜㅜ 딸기 쇼트케이크 진짜 신선하고 최고이니 다들 꼭 맛 보시길!!❤️', 113, 20, 'GOOD', SYSTIMESTAMP);
