INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '레드플랜트 합정본점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '블루리본 있어서 궁금했는데 확실히 커피 맛이 달라요! 내부에 창문도 많아서 답답하지 않고 잠시나마 혼자서 힐링하기 좋은 곳이었어요. 2-4명이서 방문해서 담소나누기에도 좋아보여요. 합정역에서 가까운 점도 좋고~ 다음에 또 방문할게욤!', 25, 4, 'GOOD', SYSTIMESTAMP);
