INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '레드플랜트 합정본점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '오랜만이 아닌것 같지만 굉장히 오랜만에 좋아하는 원두로 시켜서 마셨어요ㅎㅎ 혐요일이지만 공휴일이라 행복함!! 그리고 시음해주신 언니를 또 만난덕도 있구요ㅋㅋㅋㅋㅋㅋ 또 놀러가겟어요! 후헤헿🩵', 5, 3, 'GOOD', SYSTIMESTAMP);
