INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '레드플랜트 합정본점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '2025 코리아커피로스팅챔피언십(KCRC)2위 류정헌 로스터의 카페 넘사벽 로링 로스터로 볶는 스페셜티 관대하게 무료 시음 커피부터 온두라스, 과테말라 싱글 게이샤 에스프레소까지 있네 시네소mvp hydra머신과 sp2+로버s+e80gbw+ek43 그라인더라니 ㅎㄷㄷ 단맛 임팩트에 복합적인 꽃과 과일 신미에 매끄럽고 부드러운 텍스처까지 대단하다 캐나다 명품 NAIM 스피커에 트리며 2층 뷰가 놀랍네 안캅 데미따세에 듀라렉스 유리잔이며 친절하고 국산 에토라 나무트레이로 테이블까지 서빙 와 걍 합정역 코너자리 카페인지 알았는데 국대 로스터리였네 많이 놀랐다!!', 52, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '레드플랜트 합정본점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '저번주에 세텍 카페&베이커리페어에서 대표님과 예쁜 팀장님?이 맛보여주신 커피 맛에 반해서 드립백 사와서 오늘 내려먹었어요~ 한모금 마시자마자 얼른 리뷰쓰러 달려왔습니다ㅠㅠ 솔직히 페어때 맛 본 커피들이 너무 소름돋아서 드립백은 좀 아쉬울수도 있겠다 생각하고 마셨는데, 어느 카페 드립커피와 비교해도 지지않을만큼 맛있었어요!! 무려 드립백인데ㅠㅠ 감동ㅠㅠ 커피를 사랑하고 직업을 애정하시는 두분의 열정과 커피의 행복 느끼러 매장으로 꼭 다시 방문할께요♡ (애견동반이라니 너무 감사합니다 :) 가방안에 잘 데리고 갈께요!)', 1, 8, 'GOOD', SYSTIMESTAMP);
