INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '레드플랜트 합정본점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '친절한 커피 전문가 사장님이 운영하시는 카페. 공간도 넓고 커피가 맛있어요! 출근시간에는 할인 이벤트도 하셔서 아침에 자주 가는데 오늘은 프리미엄 원두로 업그레이드 서비스까지 해주셔서 하루의 시작이 행복해졌네요. 감사합니다☀️', 81, 13, 'GOOD', SYSTIMESTAMP);
