INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '레드플랜트 합정본점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '테이블에서 주문하는 큐알코드 설명이 있어서 테이블로 바로 갔더니 큐알코드는 카운터에만 있는거였음.. 결국 다시 가서 사진찍고 주문함. 테이블마다 붙여주던지 사진 거기서 찍고 가라고 써주던지 했음 좋겠음..', 121, 26, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '레드플랜트 합정본점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '이전 후 정말 오랜만에 들렀습니다. 사장님, 초심을 잃으신것 같습니다. 제가 아는 레드플랜트의 열정넘치는 그 커피가 아니었습니다. 레드플랜트의 그 간판이 아니었음 차라리 납득했을 그런 맛이었습니다. 평타정도의 맛이었음 저도 적당히 넘어갔을텐데 친구데려온게 미안할 정도의 분노의 맛을 보여주시더군요. 이 리뷰를 남기기 위해 까먹었던 영수증도 다시 받아왔고 바보같은 앱도 깔도 인증도 했습니다. 네이버 리뷰는 오늘 처음 남겨봅니다. 부끄러워해주세요, 사장님.', 18, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '레드플랜트 합정본점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '비싸지만 커피는 맛있음 (원두 선택 가능) 디저트도 맛있음 (스콘이랑 까눌레bb) (치즈케이크도 맛있어보임ㅎ.ㅎ) 사장님, 직원분들 모두 친절하고 좋아요. 인테리어 이쁘고 깔끔. 2층에 좌석도 많음.', 24, 5, 'GOOD', SYSTIMESTAMP);
