INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '레드플랜트 합정본점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '맛있어요 남자친구랑 합정가면 늘 여기 커피 마시자고 꼬셔요 ㅎㅎ. 다만 얼음양이 많아서? 시간 흐르면 밍밍해져요 좀더 진하거나 얼음양 조절해주시면 좋을 것 같아요 그럼 또 찾아갈게요!!', 49, 5, 'GOOD', SYSTIMESTAMP);
