INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '레드플랜트 합정본점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '넓고 분위기 좋아 편하게 커피 마시기 좋은 카페 커피 맛은 좋은데 디저트 스콘은 비주얼 만큼 맛은 좀 별로였고, 화이트,블랙 머그컵 심플하니 예쁜데 손잡이가 없어 뜨거운 음료 마시기가 많이 불편했음', 36, 1, 'BAD', SYSTIMESTAMP);
