INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '레드플랜트 합정본점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '#합정역 #바닐라라떼 여기 바닐라라떼가 정말 맛있어요! 원두가 좋아서 그런가 커피류는 정말 다 맛있어요. 그런데 스콘은 포크가 안 들어갈 정도로 너무 딱딱해서 별 하나 뺏어요...', 25, 6, 'GOOD', SYSTIMESTAMP);
