INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '[마포 빵투어 후기 2탄] 소금빵 4pc 10.0 소금빵 러스크 4,000원 더블유오앤에서 저렴하게 소금빵을 맛볼 수 있어요 !!🥐🥐', 47, 5, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '저녁에 날씨도 풀려서 야외 앉았는데 조용하고~ 너무 좋더라구요ㅎㅎ 물론 커피는 말할것도 없이 맛있고, 적당한 산미에 적당히 달달한느낌도 있고ㅎㅎ 두번째 방문이지만 이쪽오면 언제나 오고싶은곳이네요.', 14, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'TERRACE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '엄청난 인테리어….!!!! 1층도 완전 짱이다 생각했는데 지하로 내려오니 무슨 동굴처럼 되어있었습니당 소금빵도 종류가 엄청 많고 커피 원두도 다양해욤 다음엔 남자친구랑 와야겠어요 희희😃', 13, 10, 'GOOD', SYSTIMESTAMP);
