INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '소금빵 먹고싶어서 왔는데 생각보다 종류가 넘 많아서 행복했습니더 :) 공간도 넓고 분위기도 쾌적해요! 소금빵 먹고싶을 때 또 오려구요 >.<', 15, 4, 'GOOD', SYSTIMESTAMP);
