INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '분위기가 정말 좋고 규모가 커요!!! 빵과 케이크도 처음 보는 메뉴가 많아서 고민되더라구용🥹💗 핸드드립 커피도 있어서 자주 올 것 같아요❣️', 47, 0, 'GOOD', SYSTIMESTAMP);
