INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '친구랑 급 홍대나들이왔다가 늦게까지하는카페가있어서 왔는데 카페분위기도 너무좋고, 핸드드립도있고  케잌도 안달고 맛있어요~~ 너무맛있게먹고 힐링하다가요~😊👍', 122, 19, 'GOOD', SYSTIMESTAMP);
