INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '카페 인테리어 분위기가 너무 좋아요. 늦은시간까지 하구요 커피가 맛있아요 좋은향이 나고 노래소리와 장르가 너무 좋아요.. 👍 👍 최고', 6, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '유명한 소금빵 카페 맛집이어서 방문 했어요 카페 인테리어도 멋지고 에어컨도 빵빵하고 친절해서 좋아요! 지하 좌석들도 넓고 편해서 자주 방문 하기 좋은거 같아요!!', 4, 2, 'GOOD', SYSTIMESTAMP);
