INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '간단리뷰 - 대형 베이커리 카페로 자리가 많음 / 다양한 빵 음료 및 핸드 드립 커피 있음 / 매일 오전11~새벽2시 운영 해서 늦은 시간 가기에 좋네요 / 층마다 차별화된 인테리어 숲속, 모던바, 캠핑, 야외 특징이에요 / 영수증 리뷰 작성시 소금빵1개 무료 제공 / 베이커리는 전문점 느낌 정도의 맛은 아니고, 커피랑 먹기에 무난 했어요. / 지하층에 푹신한 의자 덕분에 오래 앉아서 이야기 나누기 좋아요 / 인테리어가 잘 꾸며져 있어서 다양한 곳에서 사진 찍기 좋은듯했어요', 42, 7, 'GOOD', SYSTIMESTAMP);
