INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '소금빵 맛집이어서 그런거 빵도 맛있고 커피도 맛있어요!! 카페도 넓고 분위기도 좋아요~~ 개인적으로 지하가 더 취향저격이라 추천합니다~!!', 44, 3, 'GOOD', SYSTIMESTAMP);
