INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '카페 분위기도 좋고 직원분들도 친절하십니다. 소금빵 맛집답게 소금빵 종류도 많아서 선택하기 좋습니다! 지하에도 좌석 많아서 좋네요!', 22, 2, 'GOOD', SYSTIMESTAMP);
