INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '솔직히 말해서, 인테리어 하나만큼은 정말 압도적이에요. 외관부터 눈에 확 들어오고, 내부는 샹들리에에 대리석 바닥, 통창 구조까지… 약간 유럽 명품 매장 같은 느낌이라 사진 찍는 재미가 엄청나요. 진짜 포토존 좋아하시는 분들에겐 천국일 거예요.', 32, 2, 'GOOD', SYSTIMESTAMP);
