INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '☕️ 아늑한 분위기와 맛있는 커피가 정말 좋았어요! 친절한 직원분들 덕분에 기분 좋은 시간이었습니다 :) 다음에 또 방문하고 싶어요!', 39, 5, 'GOOD', SYSTIMESTAMP);
