INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '서울여행와서 어디카페갈까 찾다가 소금빵도 맛있어보이고 인테리어도 예뻐서 와봤는데 역시나 다를까 후회가 전혀 되지않게 ~ 포토스팟이 많아요!', 29, 7, 'GOOD', SYSTIMESTAMP);
