INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '분위기가 평소에 넘 좋아하는 분위기라 와봤는데 기대했던대로 넘 예뻐용ㅜ 원래 소금빵 처돌이인데 여러 가지 맛 소금빵 먹을 수 있어서 행복햇어요 😍 굿굿 오늘은 지하에서 있었는데 다음엔 1층에도 앉아서 다른 컨셉도 즐겨보고 싶어요 굿 😋', 39, 4, 'GOOD', SYSTIMESTAMP);
