INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '소금빵이 맛있다는 소문을 듣고 포장하러 왔습니다! 당일생산 당일폐기, 수익일부는 유기동물을 위해 사용되기까지! 빵도 맛있고 내부 분위기도 좋아서 나중에 데이트하러 올게요!', 38, 5, 'GOOD', SYSTIMESTAMP);
