INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '홍대 카페 검색해서 왔는데 분위기도 좋고 빵 종류도 꽤 많아요!! 접근성 괜찮은 편이구 특별한 메뉴도 많아서 다음에 또 오고 싶네용 ㅎㅎ 추천합니다', 9, 8, 'GOOD', SYSTIMESTAMP);
