INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '원래 자주 왔는데 오랜만에 홍대와서 또 온 카페.. 다른곳 가고싶어도 못간다!!! 인테리어가 너무 이뻐서 ㅜㅜ 디저트없음 카페 안가는사람으로써 완전 추천이요 남자친구는 소파 편하다고 잘왔대용ㅋㅋㅋㅋㅋ❣️', 5, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '서울 한복판에 이렇게 넓은 카페가 있다니! 지하 동굴분위기와 지상 높은층고 캠핑장분위기 둘다 멋졌습니다💕 금귤이 들어간 선셋크러쉬와 말차코코넛콜드브루 마셨는데 금귤이 엄청 새콤하고 강렬하더라구요! 코코넛과 말차크림과 말차크림이 조화롭게 잘 어우러져서 추천입니닷😃 빅토리아케이크는 딸기잼이 엄청 달달해서 당충전 팍 되더라구요. 다 맛있게 먹고 가요!', 2, 10, 'GOOD', SYSTIMESTAMP);
