INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '분위기가 너무 다양해서 좋고 소금빵 너무 맛있어요!!! 사장님도 너무 착하시고 포토도 따로 찍을 수 있어서 데이트 할 때 좋은 거 같아요! 다음에 또 올게여🙂', 87, 16, 'GOOD', SYSTIMESTAMP);
