INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '음료도 마싯고 분위기도 좋아요. 시원하고 넓어서 마음 편하게 잘 쉬다 갑니다! 층별로 분위기가 다른 것도 좋고, 소금빵 종류도 많아요', 2, 9, 'GOOD', SYSTIMESTAMP);
