INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '맛있는 커피랑 분위기 그윽한 카페 어디 없을까... 검색하다 찾은곳~^^ 처음엔 넓은 카페 치고 자리가 적다..했더니, 대반전~!!! 지하에 바 형태의 분위기 죽이는 곳이 있었다~ 와우~!!! 신나서 사진 찍느라 두리번 거리며 누볐다 2층 캠핑컨셉 자리에만 눌러 앉아 있었으면, 엄청 후회할뻔~~ 숲과 동굴이 공존하는 공간~🌲🏞 쫄깃한 소금빵이 딸기랑 크림을 넘치도록 품었네~ 달달한 말차코코넛라떼랑 잘어울리는 초코바나나케이크~ 🍵🥥🍫🍌🍰 거품 풍부한 쌉싸름한 카푸치노~☕️ 음료랑 소금빵, 케이크 디저트도 훌륭하다~~👍 리뷰이벤트로 따뜻하게 데워준 소금빵을 받았는데, 얘가 또 너무나도 맛난거다~♡ 저녁에는 한층 더 분위기가 멋있을꺼 같다~🍷🍸🍹 밤까지 있을수 없는 것이 너무나 아쉬웠다..🥲', 53, 11, 'GOOD', SYSTIMESTAMP);
