INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '화창하고 뜨거운 여름 햇빛을 받다 들어오니 마치 동굴 속에 온 듯 황홀하네요✨ 음료도 맛있고 음악과 분위기 모두 적당하고 느좋이에요..👉🏻👈🏻 넘나예쁨,,😍', 36, 7, 'GOOD', SYSTIMESTAMP);
