INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '처음와봤는데 카페 인테리어 분위기가 너무 조아요. 사진찍고 친구들이랑 놀기 딱 좋은 분위기인거같아영 담에 또 와서 놀려구용🥹🥹 그리고 직원분들이 너무 친절하세요. 대박나세여 직원분들🥰', 122, 23, 'GOOD', SYSTIMESTAMP);
