INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '사진 찍기 너무 좋고 분위기가 좋고 자리가 편해요 홍대갈때 분위기 좋은카페라고 추천하고 싶어요!! 홍대갈때 마다 방문할게요 카페 어디갈지 고민하시는 분들은 여기로 오세요', 23, 8, 'GOOD', SYSTIMESTAMP);
