INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '커피 원래 안 마시는데, 시그니처라해서 크림라떼 시켜봤어요 커피 다 마실 때까지 위에 크림도 충분했어요 😆 오잉? 너무 맛있잖아? 아메리카노도 진짜 맛있어요 카페 분위기 넘 좋아서 맛은 좀 감안해야겠다했는데, 맛도 있었습니다! 매장도 넓고 좌석 사이 공간이 넓어서 부담스럽지 않아요 친구끼리도, 연인끼리도 많이 오는 것 같습니당 앞으로 홍대 오면 여기에서 모이는 걸로  🥰', 36, 8, 'GOOD', SYSTIMESTAMP);
