INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '홍대에 주차되는카페가 귀한데 여기는 주차도 가능하고 카페도 너무 넓고 예쁘고 좋네요.. 우연히 발견한 곳인데 앞으로 단골될거같아용 ㅎㅎ', 59, 16, 'GOOD', SYSTIMESTAMP);
