INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '직원이 좀 불친절 했어요. 표정이랑 말투가 너무 불친절함이 묻어나와서 친구들이랑 왔는데 기분이 별로 안 좋았네요 그래도 말차 라떼는 평타칩니다.', 54, 14, 'BAD', SYSTIMESTAMP);
