INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '커피도 맛이 좋고 소금빵도 맛있었어요~ 초코소금빵도 단짠이 느껴지고 빵 자체도 부들부들 맛있더라구용 주말에 가니 10대 학생들이 엄청나게 많더라구요 ㅋㅋㅋㅋ', 77, 11, 'GOOD', SYSTIMESTAMP);
