INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '업무하러 왔는데 ㅎㅎ 집중해서 하기 좋아요 =) 소금빵에 윤기가 ㅎㅎㅎ 너무 맛나보이고 종류도 다양해서.다음에 또 올 것 같아요 🫶🏻🙊', 28, 3, 'GOOD', SYSTIMESTAMP);
