INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '늦게까지하는 카페면서 분위기도 인테리어도 독특하고 좋아요 밤에 왔는데 디카페인도 있어서 부담이 없네요 디카페인 커피 맛이 괜찮아요!(다른 카페 디카페인 커피...맛없아사 실망 많이 했는데 여기 괜찮네요) 주차는 와서 연락하면 주차장 문 열어주셔요!', 39, 5, 'GOOD', SYSTIMESTAMP);
