INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '집에서 그리 멀지 않은 심야 카페 처음 와봤는데 분위기랑 너무 좋았어요 심야에는 밝은 카페보다 어두운 카페를 선호하는데 지하1층은 어두워서 더 만족스럽습니다 음료랑 빵도 맛있고 감사해요', 19, 4, 'GOOD', SYSTIMESTAMP);
