INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '매장도 넓고 맛있는 디저트도 많아서 너무 좋았어요~!! 인테리어도 너무 예쁘고 지하랑 지상의 느낌이 달라서 더 좋았던 것 같아요! 특히 지하에 물 떨어지는 인테리어가 대박..🥹🥹 디저트랑 음료수도 잘 먹구가용👍👍', 14, 3, 'GOOD', SYSTIMESTAMP);
