INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '동생이랑 놀러왔는데 넘 좋네요~ 빵 냄새도 좋고, 커피도 맛있어요!! 항상 홍대오면 카페 찾아다녔는데,, 유목민 생활 끝입니다! 강츄🩷', 107, 25, 'GOOD', SYSTIMESTAMP);
