INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '매장 내부가 엄청 커요 1층과 지하 분위기가 완전 달라서 취향대로 가기도 좋고 사진도 잘 나와서 친구들과 인생샷 건지러 가기 좋을거같아요', 25, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '디저트도 빵도 다양하니 너무 맛있고 사진맛집입니다ㅠㅠ 세상 너무너무 이쁘고 알흠다와요ㅠㅠ 대화하기도좋아요 지하는 아늑하고 지상은 보드러운 느낌', 11, 6, 'GOOD', SYSTIMESTAMP);
