INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '실내로 입장하는 순간까지도 일케 분위기있는 곳인지 몰랐어욤 문을 열고 들어가면 카운터와 각종 빵이 있고, 그 기준으로 위층은 캠핑 컨셉?, 아래에는 바 컨셉?이에요 급하게 서치해서 찾아온곳인데 커피도 맛나서 완전 대.만.족 그 자체☺️👍', 67, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '빵 너무 맛있고 인테리어랑 포토존 너무 예뻐요..! 지하가 있는 줄 몰라서 1층에만 있었는데 지하도 보니까 어둡게 예쁘고 1층은 조명도 이쁘고 좋았어용', 4, 0, 'GOOD', SYSTIMESTAMP);
