INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '매장 크고 좋네용 소금빵도 맛있어요! 사진찍기 좋을것 같아요! 근데 넓은만큼 사람이 더 많아서 앉을자리 잘 타이밍 맞춰서 가야해요 ㅠㅠ 그래도 추천드려요!! 🌼', 49, 3, NULL, SYSTIMESTAMP);
