INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '1층에서는 빵 고를 수 있고 테이블은 2층이랑 지하로 이루어져있는데 중간 계단에도 앉을 수 있게 자리가 마련되어있어서 특이하고 예뻤어요 소금빵은 완전 파쟉하니 버터향이 잔뜩나서 너무 맛있고 케이크는 생크림이 느끼하지않아서 더 맛있게 먹었습니다 커피랑 딸기라떼는 더 말할거없이 깔끔하고 적당히 달달한게 빵들이랑 잘 어울렸어요', 34, 6, 'GOOD', SYSTIMESTAMP);
