INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '소금빵 프레즐 메뉴가 다양하고 먹어본건 다 맛있었어요 초록초록하고 캠핑갬성나는 위층이랑 어둡고 차분한 지하랑 분위기가 완전 다르구 낮에와도 밤에와도 좋을것 같아요 지하에서는 라이브도 하는지 무대도 있던데 다음에 저녁에 와보고싶네요 잘먹고 잘쉬다 갑니다!', 6, 8, 'GOOD', SYSTIMESTAMP);
