INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더블유오앤'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '그냥 주변 카페찾다가 아인슈페너가 맛있어보여서 왔는데 매장이 이렇게 이쁜줄 몰랐어여 그냥 들어왂는데 대만족입니다🥺🥺 직원분도 모르는게 있어서 물어봤는데 친절하게 대답까지 해주셔서 너무 감사했숩니다🥰 다음에 또 홍대오면 친구 데려올정도로 매장도 넓고 넘 예뻐요!! 또 오겠습니다❤️', 25, 7, 'GOOD', SYSTIMESTAMP);
