INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '더피 발바닥 모양 소다맛 아이스크림? 도 있어서 너무 귀여웠어요!!! 아이스크림도 종류 다양하고, 일단 진짜 쫀득하고 직접 수제인게 보여서 추천해요!! :):):)', 18, 6, 'GOOD', SYSTIMESTAMP);
