INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '홍대 돌아다니다가 맛있는 젤라또 집이 있다고 해서 갔는데 가게도 아기자기 귀엽고 젤라또 맛도 다양해요! 냥바닥 토핑도 너무 귀엽고 콘 디테일까지 너무 귀여워요🥹💖 양도 많고 비싼 편도 아니라서 좋아요 사장님도 엄청 친절하셔서 좋았습니당 맛있게 잘 먹었습니다☺️', 42, 6, 'GOOD', SYSTIMESTAMP);
