INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '길 지나가다 무심코 보고는 다시 돌아서 들어간 가게💕 젤라또 정말 맛있고 귀요미 발바닥으로 뽀인트 줘서 맛도 기분도 업업 됬어요ㅋㅋ 사장님 친절함 최고👏', 32, 3, 'GOOD', SYSTIMESTAMP);
