INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '아이와 홍대데이트 나왔다가 젤라또 가게 검색해서 온 곳! 리뷰에 고양이발바닥 토핑에 끌려서 왔는데용ㅎ 가게가 아담하니 귀엽네요. 다행히 앉을 자리가 있어서 편하게 맛있게 먹고 갑니다~', 27, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '카레 먹구 후식~ 젤라또~! 사진 넘 이쁘게 잘 찍힘❤️ 남친이 고른 리조는 제 스탈 아니었어요 쌀 씹혀서 이질적…? 제가 고른 딸기랑 핑크 솔트는 맛났어요 히히 사장님 친절하셨어요❤️ 스티커 주셔서 감사합니다~~~', 39, 2, NULL, SYSTIMESTAMP);
