INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '젤라또 좋아해서 먹으러 갔는데 너무너무 귀엽구 고른 거 다 완전 맛있었어요❣️ 맛집 많은 길목에 있어서 근처에서 밥 먹고 젤라또 먹고 맥주로 마무리하면 홍대데이트코스로 갓벽! 거울존 귀여워서 인증샷 찍어줘야 되구용ㅋㅋㅋ 테라스도 아기자기하고 넘 예뻐요😍 젤라또 팥빙수도 있어서 담엔 빙수도 먹어보려구요! 그리구 사장님 진짜 최고루 친절하심~~ 마포구 토박인데 진심 홍대디저트 카페 중에 여기보다 친절한 곳 못 봤어요👍🏻❤️ 재방문 의사 200%🫶🏻', 40, 4, 'GOOD', SYSTIMESTAMP);
