INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '매장 입구부터 내부까지 아늑하고 귀여운 인테리어와 싱싱한 과일이 진짜 많이 들어간 느낌이라 찐과일맛을 느낄 수 있는 젤라또였어요!! 사장님도 엄청 친절하시구 냥발또도 귀여운데 넘 맛있어서 추가 강추!! 홍대 젤라또 맛집 발견한 기분이라 앞으로 자주 먹으러 올게용 !', 44, 1, 'GOOD', SYSTIMESTAMP);
