INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '젤라또 먹고 싶어서 길찾아왔오요~~~ 리조 젤라또가 없는 줄 알고 깜짝 놀랐는데 있더라구요 ㅎㅎ 최고!! 홍대에 젤라또 먹으러 오면 또 올 것 같아요!! 맛있 어요 💗💗', 36, 7, 'GOOD', SYSTIMESTAMP);
