INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '사장님이 진짜진짜 친절하시고 맛보기 스푼도 주셔서 맛 고를 수 있었어요!! 사장님이 더 신나게 젤라또 퍼주셨어욬ㅋㅋㅋㅋ (리뷰 쓴다니까 완잔 귀야운 고양이 발바닥 아이스캔디도 챙겨주셨다는 꿀팁..소곤소곤)♥️', 33, 4, 'GOOD', SYSTIMESTAMP);
