INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '홍대에서 정말 맛있는 젤라또 발견했네요‼️ 친절한 사장님이 자꾸만 맛보기 스푼으로 맛보기 권하시는데 맛볼 수록 다 맛있어 선택하기 점점 어려워지는 🤭 새로운 맛으로 그때그때 리필을 하는 방식이라 방금 만든 라즈베리를 추천해주셔서 먹었는데 라즈베리씨가 그대로 씹히는 찐수제젤라또맛 이네욥👍🏻 과일이 많이 들어가서 찐과일맛에 입에 남는 텀텀함이 1도 없는 찐젤라또😘 리조젤라또도 씹히는 식감이 지금까지 먹은 리조 중 역대급이라 꼭 드셔보셨음 좋겠네욥 거기에 아기자기한 냥발또마저 찐한 우유에 딸기씨까지 느껴지는 딸기맛의 정성 가득든 토핑입니다❤️ 과일맛 젤라또는 강아지도 같이 즐길 수 있다고 하니 댕댕이랑 맛난 젤라또 즐기러 방문해 보세요', 56, 12, 'GOOD', SYSTIMESTAMP);
