INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '이탈리안들도 찾는 젤라또 집이예요 제가 머무르는 20분정도 동안 이탈리안이 두팀이나 왔어요! 젤라또가 너무 달지않고 과일향이 잘 살아있어서 디저트로 딱입니다. 특히 사장님께서 너무 친절하시고 컵가득 넘치게 담아주시는데 진짜 인심도 최고! 홍대갈 때마다 갈꺼라구요!', 102, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '컵 두가지맛으로 시켰는데 콘도 꽂아주시고, 서비스 한스푼까지 주셨어요ㅎㅎ 연유랑 딸기맛나는 귀여운 고양이 발바닥까지!! 홍시맛이랑 라즈베리 시컀는데 둘다 맛있었지만 홍시맛이 레전드였습니다..😭💖💖💖 꼭 드셔보세요', 65, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '아이스크림 맛있구 좋아요! 네이버 리뷰하면 젤라또 위에 발바닥 토핑을 무료로 올려주세요! 밖에 의자밖도 귀엽고 컨셉 넘 귀엽고 좋아요!₍˄·͈༝·͈˄₎❤︎', 86, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '목적없이 더워서 들어온 집인데 맛있는 게 이쁘기까지 해요~~ 저 냥이 발~ 너무 이쁘죠? 냥발은 우유랑 딸기로 만들었대요~ 세 손꾸락만 끼는 장갑도 챙겨 주시니까 손으로 잡고 먹으면 되는데.. 아까워요~ 이 이쁜 걸 먹으려니~~~ 과일 맛은 그때그때 제철과일로 교체된대요~ 홍대오면 다른 맛 먹으러 계속계속 와야 할 집이에요~~~ 강추~!!!!!!', 10, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '고양이 발바닥 모양 사탕? 인줄알았는데 더 맛있는 우유아이스크림 이였어용!!!! 제 옆에있는 사람은 사장님이 재밌어요 래요 맛보기 스푼 배라같은 곳이랑은 비교할수없는 무한 맛보기스푼 이래요 ㅋㅋㅋㅋㅋ 일단 저는 패션후르츠가 맛있고요 (엄청 셔서 눈질끈감은) 그거랑 다크초코가 진짜 어울릴듯 친구는 오레오랑 딸기  딸기가 더 멋있었대요 담에가면 식사전 패션후르츠 후식은 다크초코', 38, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '신촌에서 젤라또 가게 찾다가 홍대까지 걸어왔지만 더위가 싹 물러가는 맛이었어요🥰🥰 사장님도 너무너무 친절하시고 5천원에 이렇게 잔뜩 담아주시면 남는 게 있으신가요🥹 셋이 갔는데 셋 다 넘치도록 담아주시고 서비스 스푼까지~! 감사합니다 또 오겠습니다~~~!~!!🤩🤩', 20, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '다크초콜릿이 하나도 안달고 완전 맛있어요 라즈베리도 완전 쌍콤하고, 딸기도 너무 맛있어요!! 냥발아스크림은 우유 베이스에 딸기 맛이라서 완전 존맛탱이에오!! 무조건 다시 올 예정입니다!! >_< 사장님도 완전 친절하시고, 재밌으셔서 바로 인스타 팔로우 했습니다😚 여기 홍대 왔다가 안드시고가면 레알 후회해용!!! 다음에 토마토 먹으러 또 오겠습니당 🙇‍♀️🙇‍♀️', 4, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '과일이 그대로 다 씹혀서 좋아요, 위에 꽂아주시는 귀여운 미니콘에 모든 맛 올려버리기~ 한스푼씩 맛보기 주시는 것도 귀엽고 좋네요 ㅎㅎㅎ', 43, 9, 'GOOD', SYSTIMESTAMP);
