INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '늦은 시간 방문했는데도 너무 친절하게 맞아주셔서 좋았어요!!기대했던 라즈베리가 다 나가서 아쉬웠는데 박박 긁어서 주샸어용 덕분에 넘 맛있게 잘 먹었습니당!!먹어보라고 파인애플도 주셨는데 진짜 쵝오이십니다!!!담에 또 올게요~!~!!사장님이 맛있구 아이스크림이 재밌어용!', 28, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '여기 젤라또 진짜 맛있어요!!! 딸기맛안에 씹히는것도 맛있고 초코맛 최고임!!♡ 사장님 너무 친절해요~ ^^ 담에 또 방문할께요!!!', 13, 1, 'GOOD', SYSTIMESTAMP);
