INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '과일맛은 모두 쌍콤하고 초코는 엄청 진하고 대박이에요 특히 다크초코랑 라즈베리 꼭꼭 드세오!!!‘ 초코 좋아하시면 무조건 다크초코 상큼한 거 좋아하면 무조건 라즈베리!! 식후땡으로 최고입니다👍👍👍👍 수제 젤라또니까 그냥 아이스크림보다 아이들한테 좋을 것 같아용', 101, 23, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '홍대 젤라또가 맛있는 젤루떼리아아라또💕 고소하고 담백하고 상큼한 젤라또가 가득한 곳이에요 ㅎㅎ 저는 패션후르츠, 자몽, 리조(쌀), 로투스 이렇게 2가지맛을 2개 먹었어요 ㅎㅎ 그 위에 토핑은 냥발을 추가했는데 우유를 얼린 느낌으로 완전 부드럽고 맛있어용 ㅎㅎ 여러가지 맛의 젤라또를 먹을 수 있어서 좋았고 다 맛있었어요! ㅎㅎ 다른 맛도 엄청 궁금하네요~~😝😝', 60, 15, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '홍대에서 젤라또가 생각난다면 추천하는 곳이에요. 일단 고양이 가득한 인테리어가 너무 귀엽고, 냥발또 아이스크림도 토핑으로 얹을 수 있는데요. 여기만의 시그니처 느낌인데, 비주얼도 귀엽고 맛있으니 꼭 올려서 사진 백장 찍으세요!! ㅋㅋㅋ 개인적으로 추천하는 맛은 키위랑 로투스쿠키!!! 둘 다 진짜 키위랑 로투스 그 잡채로 너무 맛 재현을 기깔나게 하셔서 다음에도 또 먹을 것 같아요. 망고, 오레오도 호불호 없을 것 같고, 누구나 좋아할 맛이에요. 이제 날씨 따뜻해지면 야외 테이블에서 젤라또 드세요. 기분 최고!!!', 24, 3, 'GOOD', SYSTIMESTAMP);
