INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '매장이 정말 아기자기 하고 예뻐요. 그래서 여자 사장님인줄 알았는데, 남자 사장님이신건 반전 ㅎㅎ 어떤 젤라또를 고를지 몰라하니 맛도 보게 해주시고, 젤라또도 가득 담아주시고 젤라또 종류에 따른 토핑도 귀엽게 올려주세요. 고양이 발 모양의 냥발또는꼭꼭 추가하세요. 넘 귀엽고 맛있어요. 소품들이 예뻐서 이것저것 사진도 가득 찍었네요', 97, 22, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '친구가 전에 젤라또 너무 맛있게 먹었다고 추천해서 같이와봤는데 진짜 건강한 맛이고 맛있었어요!ㅎㅎㅎ 신메뉴 개발도 많이하시는지 별빛청하맛도 있더라구요ㅎㅎ 저희가 막 궁금해하니까 맛볼수있게 조금씩 더 주신 것도 감사했어요 강아지도 먹을 수 있는 젤라또라고 하셔서 반려동물이랑 같이먹어도 좋을 것 같네요^^ 잘먹고갑니당:)', 9, 4, 'GOOD', SYSTIMESTAMP);
