INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '로투스맛, 리조맛 먹었고 네이버 영수증 리뷰로 냥발도 받았어요!!! 아이스크림이 귀엽고 냥발이 귀여워요... 로투스맛이 취향이어서 한번 더 올 것 같아요♡', 25, 10, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '젤라또 종류도 많고 야외좌석에서 시원하게 먹기 좋네요 ㅋㅋㅋ 상큼파는 패션후르츠 꼭 드세용 상큼하고 찐해서 맛있어요 ㅎㅎㅎ 젤리발바닥올려주신거 넘 상큼달달해서 좋았어요 젤라또먹고싶으면 꼭 가게 될 것같아요 사장님도 친절하시고 젤라또맛 쏘굿🫶🫶', 50, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '홍대 수많은 아이스크림이 있지만 맛은 물론 이렇게 귀여움 과다인 젤라또맛집이 있네요💗 리얼 과일이 들어가 과육이 씹히고 진한 우유맛과 상큼한 딸기맛으로 왜 모두 추가해서 먹는지 알겠던 냥발또 ! 꼭 추가해서 드세요! 사장님이 맛개발도 하시고 동물사랑하는게 잔뜩 느껴졌던 공간이랍니다. 점심 먹고 딱 디저트 후식으로 데이트코스로 강추드려요 :)', 79, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '저녁먹고 아이스크림 땡겨서 먹었는데 너무 상큼하니 맛있었어요! 망고랑 라즈베리맛 해서 먹었는데 진짜 과일 먹는 것 같아요 꼭 냥발이랑 같이해서 드셔보세요! 🐾', 3, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '고양이 인테리어가 가득한 젤라또 집이 있어서 방문해봤어요! 메뉴는 체리, 딸기, 쌀, 망고, 오레오, 다크 초콜릿 등등 다양한 메뉴가 있고 특별하게 막걸리, 맥주 맛 젤라또가 있더라구요! 실제 막걸리, 맥주로 만든다고 하시더라구요 먹어보니까 진짜 술 맛이나요 ㅋㅋ 근데 술의 쓴맛은 없고 주종에 맞는 향과 맛이 달달하게 나는게 진짜 시원하게 먹었습니다 다른 맛들도 맛있게 먹었고 쌀과 오레오는 젤라또 안에 쌀과 오레오가 씹혀서 재밋게 먹었습니다', 23, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '📌냥발또 젤라또는 꼭!!! 드세요 토핑으로 추가할 수 있는데 젤라또랑도 조금 식감이 다른 아이에요 우유+딸기맛인데 굉장히 부드럽고 사르륵 녹는다는 게 이런 말인가 싶을 정도에요! 일단 그리고 엄청나게 귀엽습니다 ㅎㅎㅎ 📌언제나 사랑받는 고정메뉴들도 많지만 몇 가지는 계속해서 새로운 맛으로 만드신데요 매번 가서 다른 맛들 먹어보고 싶어질 정도 ㅠ 특히 이 날 먹은 맛 중 다크초코와 라즈베리 맛은 왕 추천!!!! 합니다 💖 다크초코는 꾸덕하면서 굉장히 고급진 초코맛이 나구요 라즈베리는 상큼한 거 좋아하는 분들은 맛있다고 하실 호불호 없을 맛..!! 📌2가지 컵으로 주문할 때 맛보기 스푼까지 해주셔서 넘 조아요 ㅎㅎ 그리고 사장님도 너무 친절하셔서 친절+맛 두 가지 다 잡은 곳입니다!', 49, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '홍대젤라또 맛집 ! 비쥬얼 너무 귀엽구 예뻐요 🥺 달달하고 부드러운 젤라또 밥먹고 간식으로 먹기 넘 좋았어요 테이크아웃해서 경의선숲길 걸으면서 먹으니까 좋더라구요 홍대데이트 코스로 추천합니다 💛', 12, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '리뷰뇌물을 너무 많이 받아버려서 안 쓸 수가 없는 리뷰🤣ㅋㅋㅋㅋ전에 한 번 방문했던 곳인데 서비스로 한 스푼 올려주신 황치즈가 너ㅓㅓㅓㅓ무 맛있어서 재방문한 곳!!! 원래 황치즈 별로 안 좋아하는데 여기 황치즈젤라또는 넘 맛있음!!! 이거 먹으러 왔다니까 핑크젤리도 황치즈 맛으로 넣어주신 센스🫶🏻과일샤베트류도 별로 안 좋아하는데 서비스로 넣어주신 라즈베리도 맛있다ㅠㅠ저거 먹으러 또 가야될듯,,,,❣️', 18, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '사장님 완전 친절하셔서 기분 좋았어요😁 홍대에 과일과 우유로 수제로 직접 만들어서 반려동물도 먹을 수 있는 건강한 디저트 젤라또 맛집이 있다고 해서 방문했어요:) 가게 내부 곳곳에 아기자기한 소품도 많았고 냥발또 토핑도 추가해서 먹어봤는데요. 아이스크림 컵은 기본으로 2가지맛을 고를 수 있는데 사장님께서 맛보기로 다른 맛도 한스푼 주셨는데 그 마저도 너무 맛있어서 ㅎㅎ 리조 쌀맛은 쌀알이 씹히는데 생각이상으로 맛있었고 인위적이지않고 딱 본연의 재료맛이 나고 부드러운 녹는 식감에 많이 달지않아서 좋았어요!', 48, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '건강한 맛! 젤라떼리아아라또💕 홍대데이트하며 오기 좋은곳이예요~ 인테리어도 너무 귀엽고 아기자기 해요 🐱 고양이 좋아하는 딸이랑 데이트하다 들렀는데 가게 곳곳에 귀여운 고양이들이 있어서 아주 좋아하네요 👍   아이스크림 2가지 맛 고를 수 있어서 딸은 다크초코와 오레오 맛!  저는 바나나우유와 소금우유 골랐어요~ 바나나우유맛은 바나나 직접 갈아서 만드신거같아요 🍌 바나나향같은 첨가물이 들어가지 않아 건강한맛^^  너무달지 않아서 좋고 소금우유 맛도 적당히 짭짤하고 고소한 우유맛이 좋았어요 👍 딸은 초코 사랑이라서 오레오 와 다크초코에 푹 빠졌어요 ❤️   냥발또(발바닥토핑)는 우유와 딸기를 얼리신 거래요~! 센스있게 손으로 잡아서 먹을 수있게 손가락에 끼우는 비닐장갑도 주셨어요 🐾 홍대아이스크림추천 👍', 3, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '고양이발바닥 모양도 맛있고 아이스크림도 맛있어요 밥맛 아이스크림은 처음 먹어봤는데 쌀처럼 씹히는 게 있어서 먹는 재미가 있었던 것 같아요 다음에 또 오고 싶습니다 ㅋㅎㅋㅎㅋㅎ', 57, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '5천원에 이정도 양이면...밥 안먹고 와야할거 같아요. 젤라또라서 칼로리 걱정도 덜 되고 재료도 풍부하게 쓰셔서 씹히는게 엄청 많아요..!사장님도 너무 친절하십니당😃', 99, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '홍대 이렇게 맛있는 젤라또 집이 있을 줄은 몰랐어요 홍대입구역이랑 정말 가까우니까 들려 보시는 거 정말 추천 드려요 젤라또가 정말 생 과일을 쓰셨는지 너무 싱싱하고 맛있었어요 색깔도 너무 다양하고 예뻤고 아삭아삭한 샤베트 식감이었어요 ✨ 또 이렇게 맛보기로 한 스푼씩 더 꼽아 주시는 센스도 있으시고 네이버 영수증 리뷰 하면 이 고양이 발바닥까지 주셔요 그런데 이게 단돈 5500 원이라니 2가지 맛을 정말 저렴한 가격에 즐길 수 있는 것 같아요 저는 베라보다 차라리 이거 사먹을 것 같아요 완전 강력 추천 드립니다☺️❤️', 11, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '홍대 젤라또 맛집이구요, 우유와 과일을 재료로 만든 건강한 디저트에요. 컵으로 두가지 종류 맛 젤라또 골랐는데 사장님이 더 맛볼수있도록 다른 젤라또도 조금씩 얹어주시더라구요. 그렇게 해서 민트초코 먹었는데 정말 맛있게 먹었어요ㅋㅋ인심도 좋구요, 남자 사장님인데 인테리어가 아기자기 귀여웠어요. 홍대건강한 디저트 집으로 추천드려요!', 41, 2, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '식사 후 디저트로 젤라또가 땡겨서 방문했는데요! 메뉴도 다양하고 너무 맛있게 먹었습니다 :) 매장 인테리어도 너무 귀엽구요! 맛은 코코넛, 쌀(리조), 패션후르츠, 로투스 먹었는데요! 모두 맛있었어요😋 특히 상콤했던 패션후르츠..👍🏻 친구랑 둘 다 원픽으러 꼽았어요ㅎㅎ 냥발또 토핑으로 올려먹었는데 너무 귀엽고 맛있고 둘 다 하는>< 낮에 오면 냥이 세마리도 볼 수 있다고 하니 담에는 낮에 방문해봐야겠어요!', 26, 0, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '이른 저녁먹고 디저트로 홍대젤라또 맛집 아이스크림 사먹었는데요~ 오오오 너무 귀엽지않나요? 많이 달지도 않고 넘 맛나요^^ 직원분도 너무 친절하시고 좋았어요^^ 재방문의사 200% 강추해요~~~~', 50, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '먹으면 행복해지는 맛. 진짜 최고임. 사장님 짱 친절하시다. 홍대 다니면서 한 번도 맛보지 않은 사람은 보았지만 한 번만 맛본 사람은 보지 못했다. 중독성 레전드.', 57, 17, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '건강한 재료로 이렇게 맛있을 수 있나요...?? 데코 너무 깜띡하구용.... 리조 진짜 너무 맛나요. 쌀알 가득해서 밥 안먹어도돼요?? ㅋㅋㅋ 헿 즐거운 한입 한입 이었습니당.', 47, 0, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '젤라또 너무너무 귀여워요 ㅎㅎㅎ 아기자기해서 사진찍기에도 좋은데 달달상큼하니 넘 맛있었어요. 맛이 다양해서 좋은데 그중에서도 황치즈랑 코코넛 추천이에요! 가게안도 귀엽게 잘 꾸며져있고 먹고갈 수 있는 공간도 있어요. 사장님도 너무 친절하고 유쾌하셔서 더 좋았습니다 ㅎㅎ', 34, 10, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '홍대젤라또 젤라떼리아아라또에 다녀왔어요. 젤라또 종류가 많은데 전부 다 맛있어보여서 고르기가 힘들었어요. 맛보기로 한가지맛 더 주고 귀여운 고양이 발바닥 아이스크림까지! 가게도 귀여워서 홍대데이트하기 좋아요. 홍대아이스크림 찾는다면 추천해요.', 74, 11, NULL, SYSTIMESTAMP);
