INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '젤라또가 먹고 싶었는데, 집근처에 홍대 젤라또 가게 아라또가 있어서 다녀왔네요! 리조 너무 좋아하는데, 쫀득하게 씹히는 쌀알이 들어있어 제 취저였어요. 진짜 달달 꼬소하면서 식감도 굿! 라즈베리도 시원상콤해서 좋았고 맛보기 얼그레이도 맛있었네요! 소금우유도 먹고 싶었는데 이번엔 패스해서 담에 먹어볼 생각입니당!', 48, 8, NULL, SYSTIMESTAMP);
