INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '매장이 너무너무 귀여운 젤라또집이에요! 젤라또도 가득가득 담아주시고 냥발토핑이 넘 귀엽고 맛있어요 . . 재료 본연에 맛에 충실해서 좋았어요~ 다크초코와 오레오, 로투스와 쌀으로 먹었는데 다 넘 맛있었습니다 ! 친절하신 사장님 ^^ 감사합니다 담에 또 들를게요', 18, 4, NULL, SYSTIMESTAMP);
