INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '사장님이 친절하고, 젤라또가 양이 엄청 많아요!! 그리고 너무 맛있습니다ㅜ 쌀맛 왤케 맛있어요?? 진짜 다음에 또 올겁니다. 길냥이들도 다녀가는 존맛 젤라또ㅜ', 99, 21, NULL, SYSTIMESTAMP);
