INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '사장님도 친절하시고 젤라또도 너무 맛있습니다!!! 손가락 비닐장갑도 주셔서 편하게 맛있게 먹었습니다 내부 인테리어도 귀엽고 깔끔해서 좋았습니다 홍대 젤라또 맛집 찾으시는 분들에게 추천드립니다!! 재방문 의사 200% 강추합니다👍👍👍👍👍', 22, 3, NULL, SYSTIMESTAMP);
