INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '홍대에서 젤라또 찾기 쉽지 않은데 이곳은 맛난 젤라또를 여러 라인업에 걸쳐서 판매하고 계시더라구요:) 사장님이 양껏 주시고 토핑도 알차게 꽂아주서서 맛있게 잘 먹었습니다!', 102, 23, NULL, SYSTIMESTAMP);
