INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '가성비 좋은 젤라또집. 주문한 메뉴 외에 오레오 쿠키랑 새로운 맛이 담긴 젤라또 수저를 담아주시고, 사장님도 정말 친절하십니다.', 47, 9, NULL, SYSTIMESTAMP);
