INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '⭐️⭐️⭐️⭐️⭐️ 냥이발바닥 모양 슈크림빵 맛있어요. 다음엔 젤라또를 먹으러 가야겠어요. 친절한 남자분이 인상적이었어요 *^^* __________________ [참고] 본인의 리뷰기준 : 1. 맛, 친절, 청결 세가지 중 한 가지라도 부족하다 느끼면 그냥 리뷰 안 올림. (왜냐하면 그날 그순간만 그랬을 수도 있으니까) 2. 맛집 찾아 다니는걸 좋아하는 아재로서 조미료 범벅이거나 건강만 추구하는 맛은 그닥 안 좋아하는 입맛이 기준인 리뷰여요', 20, 6, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '젤라또를 좋아해서 여행 가면 하나씩 먹는 젤라또 홍대에 귀여운 비주얼의 젤라또 가게가 있길래 방문했어요 맛도 정말 다양하고 특이하게 매화수/별빛청하 맛도 있더라고요 신기했어요 맛도 진하고 맛에따라 식감도 다르고 부드러운 젤라또였어요 귀여운 냥젤리 아이스크림도 얹어주는데 너무 귀엽죠 외관에도 내부에도 고양이 인테리어들이 가득한데 홍대데이트하면서 방문하기 너무 좋을것같아요 :)', 82, 18, 'GOOD', SYSTIMESTAMP);
