INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '너무 귀여운 가게에용😍 셤기간에 당충전하려고 들렸는데 스트레스날리구 갑니다 ..🥰 리뷰이벤트하시면 발바닥아이스크림 주시니까 꼭받아가세용>.<', 89, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '사장님도 친절하시고 수제 젤라또라 더욱 맛있어요!! 귀여운 토핑들도 잔뜩❤️ 다른 젤라또랑 같은 가격이라면 저는 여기 젤라떼리아아라또 갈꺼예요! 해장용으로도 딱✌️', 26, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '가게 너무 귀여워요🥹 고냥이랑 아이스크림 투성이예여🫢 (근데 가게 마스코트는 강아지인 건 함정) 사장님 너무 친절하고 유쾌하시구 젤라또 정말 맛있었어요…! 쌀맛이랑 황치즈맛 먹었는데 정말루 최고👍 마지막엔 섞여서 그냥 같이 먹었는데 의외로 섞인 맛도 오묘하니 맛있어서 오히려 조아..! 이제 곧 여름이라 홍대 올 때마다 자주 들리게 될 것 같아요 ㅎㅎ 잘 먹구 갑니닷', 77, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '여기만큼 양 많이주고 친절하시고 꾸덕한 젤라또 처음입니다… 홍대서 이상하고 비싸기만한 디저트 드시지 마시고 여기서 젤라또 강추에요', 74, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '사장님이 친절하다는 후기가많은데 진짜였어요ㅋㅋ 엄청 친절은 물론 유쾌하시기까지☺️👍🏻🧡 젤라도 시식 엄청 많이 주셔서 사장님 거덜나면 어쩌지 걱정될 정도에요 ㅋㅋ 그래도 덕분에 입맛에 맞는 젤라또 고를 수 있어서 좋았어용!! ㅋㅋ ✔️에스프레소 : ☕️삼각커피우유 맛 ✔️딸기🍓:딸기 그 자체 ✔️토마토:고급진 토마토맛🍅 ✔️라즈베리:나 라즈베리다!외치는 맛 ✔️고구마🍠:내 원픽❤️🧡💛 고구마 사랑해.. ✔️메론🍈:메로나보다 백배 맛있음', 33, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '입에 아이스크림 묻은 강아지 그려진 간판이 귀여워서 들어와봤는데 젤라또가 넘 맛있어서 다음에 홍대 놀러오면 또 먹으러 와야겠어요!! 가게도 아기자기해서 귀엽고 이번에 쌀맛이랑 오레오맛 골랐는데 다음에는 맥주맛도 먹어볼 거예요 🤩🤩', 38, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '남자칭구랑 아이스크림 먹으러 왔어요 평소에도 젤라또 너무 좋아하는데 여기 젤라또 진짜 맛있어요 ,, 🥹🥹 너무 맛있게 먹구 갑니당', 38, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '젤라또 아이스크림은 오랜만에 먹어도 역시 맛있네요🤤 특히 쌀맛이랑 다크초코가 쫀득하니 맛있더라구요!! 사장님도 친절하시고 잘 먹고 쉬고 갑니다아', 26, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '아이스크림 가게애서 다른 아이스크림 가게로 바뀜 그래도 맛있는 아이스크림 가게네요 과일맛 추천!  과육이 엄청 많이 들어있고 다크 쵸콜렛도 엄청 진하니 맛있네요', 50, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '젤라또 덕후인데 매번 가던 젤라또 집이 없어져서 우연히 들렸는데 사장님도 친절하시고 너무 맛있어요!!! 젤라또가 쫀득쫀득 상큼 상큼해요💖 그리고 젤라또 양도 많이 주시네요 넘 만족스러워요 자꾸 생각나는 맛이여서 앞으로 자주 갈거 같아요! 번창하세요 사장님', 12, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '사장님이 유쾌하시고 친절하셨어요. 젤라또 맛 선택을 잘못했지만(두가지맛 다 신 걸로 고름) 맛있게 잘 먹었습니다! 인테리어도 소품도 아기자기 귀여워요 :)', 22, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '사장님 엄청 유쾌 친절하셔요><!!! 맛보기 계속 많이 주시고ㅎㅎㅎㅎ 젤라또 시원달콤쫀쫀!!! 마지막에 리뷰이벤트로 올려주신 발바닥도 넘 맛있다는❤️', 50, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '매장도 넘넘 귀엽구 젤라또 종류가 다양해서 좋았어요😊😊 과일젤라또는 진짜 과일을 갈아서 먹는 맛이여서 신기했고 쫀득한 오레오 젤라또는 오레오도 올려주셔서 디저트 간식으로 최고였습니다💖', 65, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '홍대젤라또 젤라떼리아아라또 건강한 맛인 젤라또는 처음인데 맛닜게 먹었어요! 인테리어도 너무 귀엽고 발바닥모양도 너무 귀여워용!!', 3, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '너무나 귀여운 콘 고양이가 가게 앞에 녹아내리고 있는 가게. 과일 젤라또, 과자 젤라또, 쌀 젤라또 뺄 것 하나 없이 맛있고 패션푸르츠는 정말 여름에 생각날 것 같은 맛이에요. 라즈레리 젤라또랑 키위 젤라또도 완전 맛있었어요.', 14, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '기가 막힙니다 아주 뽀짝하고 맛있어요😙😙 아직 맥주맛을 모르는 아가는 더 커서 맥주맛을 도전할게요 사장님도 기가 막힙니다 아주 친절하세요😵 매장도 세심하게 이ㅆ을거 다 있어요 불편한게 하나도 없어요 매장도 너무 뽀짝해요😳', 19, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '귀엽고 맛있고 다하는 젤라또집 발견했어요! 젤라또 맛도 다양한데 기본 컵 주문 시 두 가지 맛 선택할 수 있어서 좋고 주문한 맛 모두 맛있어서 더 좋았습니당❤️ 귀여운 캐릭터로 귀여움도 더해주고 젤라또 맛도 진하고 훌륭합니다🥰 사장님도 친절하세요💕', 37, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '홍대젤라또 맛있는 집👍🏻 우연히 지나가다 들렸는데 사장님도 친절하시고 일단 기본적으로 젤라또가 다 너무 맛있어서 좋았어요😍 맛보기도 가능해서 모험하거나 고민할 필요가 없음! 그런데 다 맛있어서 맛 선택하는데 고민되실 수는 있을거 같아용ㅋㅋㅋ 아무튼 홍대젤라또 맛집이라고 장담합니다 꼭 한 번 가보세요 여러분!!!', 12, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '형형색색 다채로운 맛의 젤라또를 맛볼 수 있는 곳! 종류가 굉장히 많아서 결정장애가 오지만 ㅎㅎㅎ 맛보기가 가능해서 덕분에 수월하게 맛을 골랐어요! 과자맛 젤라또는 실제 과자 토핑도 해주셔서 모양도 넘 이뻐여 ㅠㅠㅠ', 46, 1, NULL, SYSTIMESTAMP);
