INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '일단 귀여워요. 네. 사장님도 귀여워요. 아이스크림은 더 귀여워요. 맛은 더더 귀여워요. 장마 끝나고 무더위가 찾아오면 시원하게 먹고 싶을 맛.. 비가 와도 생각나는 맛.. 존맛이다 이 집 젤라또 진짜로다가', 8, 5, 'GOOD', SYSTIMESTAMP);
