INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '홍대에서 젤라또 맛집 찾았습니다용 !! 맛 종류도 10가지가 넘게 있고 사장님도 정말 너무 유쾌하셔서 넘넘 행복해지는 곳이에용 ㅎㅎㅎ 신선한 재료로 만드시는 게 느껴지는 맛이었어요 ! 근처 오시면 꼭 들러보세용 >0< 저는 곧 또 가렵니다..!', 89, 17, 'GOOD', SYSTIMESTAMP);
