INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '이러한 무더위 속에서 맛있고 시원하게 먹을 수 있는 젤라또예요! 상큼하고, 부드러운 젤라또 먹고 싶은 분들이라면 추천이요~😀😀😀', 5, 1, 'GOOD', SYSTIMESTAMP);
