INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '사장님 넘 친절하시고 젤라또도 맛있어요! 리쪼 진짜 진하고 패션후루츠도 톡톡 튀는게 짱맛 두가지 맛 다 모두 추천드려요💓💓 홍대오면 또 올게요✌️✌️✌️', 4, 0, 'GOOD', SYSTIMESTAMP);
