INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '홍대 젤라또 맛집 인정입니다~! 맛도 다양해서 고르는 재미가 있어요. 패션후르츠 너무 상큼하고 맛있고 다크초코도 달달해서 맛있게 잘 먹었어요. 가게 앞에 시바 인형이랑 흘러내리는 고양이 모형 너무 귀여워서 사진 잔뜩 찍고왔어요~~!! 다음에 또 와서 다른 맛들도 다 먹어보려구요~~♡', 9, 5, 'GOOD', SYSTIMESTAMP);
