INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '젤라또가 먹고싶어서 검색하다가 근처에 있어서 왔는데 고양이에 진심인 인테리어에 한번 반하고 맛에 한번 더 반하고 갑니다🤭 다음에도 다른 맛 보러 올게요!!!! 사장님도 짱 친절하시고 프렌드리 하십니다👍🏻 아지트 될 듯♥️', 1, 3, 'GOOD', SYSTIMESTAMP);
