INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '젤라떼리아아라또'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '아닛... 진짜 너무 귀여운것 아닌가요 ㅠ 사장님도 너무 친절하시고!! 아슈크림도 달달하고 맛나유...특히나 여기는 딸기가 찐입니당! 추', 65, 15, 'GOOD', SYSTIMESTAMP);
