INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '진짜 카페 이름대러 작업 하시는 분 많앗어요 혼카페러 많아서 옴청 시끄러운 분위기는 아니에여 담에오면 다쿠아즈 먹어봐야겠어요 ㅣㅜㅜ 먹고시픔', 47, 0, NULL, SYSTIMESTAMP);
