INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '이름처럼 정말 작업하기 좋은 공간입니다. 다들 작업하다보니 회전율이 좋지는 않지만…😇 혼자 와서 집중하기도, 둘이 와서 이야기 나누며 작업이나 대화하기도 좋아요.👩🏻‍💻', 44, 1, 'GOOD', SYSTIMESTAMP);
