INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '작업하러 많이 가는 곳인데 디저트도 미쳤어요... 크림이 많이 안달아서 다쿠아즈?랑 잘어울리는거 같아요🥹 다른 맛도 기대돼요 진짜...', 60, 11, 'GOOD', SYSTIMESTAMP);
