INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '친절한 직원분과 커피가 맛있는 작업실01 일단 응대해주시는 직원분이 친절해서 좋았고, 감성있는 내부인테리어는 혼자 와서 사진찍기에도 좋았음 커피는 01라떼 시켰는데, 산미있는 에스프레소와 라떼가 적절하게 잘 어울린다 생각이 듦 아쉬운 점은 내부가 넓지 않아 수용 가능한 인원이 많지 않다는것', 60, 18, 'GOOD', SYSTIMESTAMP);
