INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '항상 느끼는거지만 여긴 흔치않게 직원분이 매번 친절하세요🩷 분위기도 은근 힙하고 따뜻하고..음료도 커피도좋구! 너무좋아요💕💕저같은 혼카페하는 사람에게 안성맞춤인 분위기좋은 카페 ㅎㅎ 저만 알았으면 좋겠어요 선의로 쓰는 리뷰 !', 9, 4, 'GOOD', SYSTIMESTAMP);
