INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '늘 사람이 많아 못 갔는데 혼자 가니 처음으로 1인석이 있어 기쁘게 방문했습니다. 직원분 목소리가 너무 차분하고 좋으셔서 주문할 때부터 기분이 좋았고, 노래와 분위기가 책을 읽기 정말 좋은 카페였습니다 😊 크림브륄레 라떼는 맛있었으나 제 입맛에는 너무 달아 다음엔 다른 음료로 도전해보고싶습니다!', 20, 3, 'GOOD', SYSTIMESTAMP);
