INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '메인 홍대 거리에서 살짝 골목으로 들어오면 있는 카페. 눈이 그치고 뚝 떨어진 온도에 피신하듯이 들어왔는데 따뜻하고 아늑한 분위기가 아주 좋네요. 작업실이라는 이름답게 개인 작업이나 스터디하는 학생들이 많아서 아주 조용하진 않아요 적당히 활기가 넘치는 공간입니다', 23, 8, 'GOOD', SYSTIMESTAMP);
