INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '홍대에서 일정 마치고 주변 카페에서 카공하려고 하다가 우연히 발견한 카페에요🩷 늘 북적북적 사람도 많은 홍대라 제가 원하는 분위기의 카페가 있을까 싶었는데 “작업실”이라는 이름 하나 보고 여기다 싶었어요 ㅎㅎ 잔잔한 노래와 다들 한껏 무언가에 집중하는 모습 그리고 그 풍경을 완성해주는 멋진 카페 인테리어까지..!🥹 갔을 때 창가자리가 하나 남아있어서 운좋게 바로 앉을 수 있었어요! 아인슈페너도 너무 맛있게 먹었답니다 시나몬 가루 많이 뿌려주셔서 행복했던..👍🏻 좋은 공간에서 잘 집중하다 가요🥰', 16, 1, 'GOOD', SYSTIMESTAMP);
