INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '작업하기에도 좋고, 조용히 도란도란 얘기하기에도 좋은 홍대 카페예요 작업실01 특유의 아늑한 분위기 덕분에 종종 찾게 됩니다 ♥ 홍대 카페 중에서 재방문하는, 정말 몇 안 되는 카페예요!', 129, 21, 'GOOD', SYSTIMESTAMP);
