INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '카페 이름대로 작업하기 좋고, 책도 많아서 커피 하나 시키고 독서하기도 적절한 곳이네요. 데이트로나 혼자나 상관없이 편히 와서 쉬다 가고 싶은 곳이에요.', 30, 10, 'GOOD', SYSTIMESTAMP);
