INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '홍대에서 놀다가 커피 한잔 마실겸 책을 읽으려고 찾아간 카페입니당:) 첫 방문인데 인테리어와 분위기도 너무 좋았고 음료랑 디저트도 맛있었어요! 혼자 오신 분들을 위한 1인 좌석도 있어서 노트북으로 할 일을 하거나 독서를 하기에도 좋았습니다~책도 있어서 빌려 읽을 수도 있고요. 무엇보다 사장님이 너무 친절하셨어요 (사장님이 너무 미인이셨어요🫢) 홍대 올 때마다 들르고 싶은 카페네요,, 제 최애 카페가 될 예정입니다:)', 128, 26, 'GOOD', SYSTIMESTAMP);
