INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '평점 높아서 간건데 인테리어도 좋고 조용해서 좋았어요. 가게가 작아 주말2시간 이상은 피해달라고 했어요. 여기 시그니처 메뉴는 안먹었는데 커피맛은 근냥 그래요. 가성비는 좋음 그러나 라떼는 그냥그럼', 24, 1, NULL, SYSTIMESTAMP);
