INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '공간이 차분하니 혼자오기 좋습니다. 아따 향 냄새 기가막힌다👍 1인석이 잘되어 있어서 작업하시는 분들에게 이미 잘 알려진 곳 같드래요. 사람이 많네요 물론 큰 자리도 있어서 담소 나누실 수도 있습니다. 인기쟁이 카페라 작업하실 분들은 빨리와서 자리 선점 하셔야 할듯', 3, 8, 'GOOD', SYSTIMESTAMP);
