INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '크림 브륄레 라떼가 시그니처여서 마셔봤는데 정말 달았어요! 그래도 맛있었습니다😋 공간이 좁은 건 아쉬웠는데 그래도 좋은 시간이었습니다!', 5, 5, NULL, SYSTIMESTAMP);
