INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '다쿠아즈 레몬 4,500원 실라떼 6,500원 크림브륄레라떼 7,000원 인테리어가 독특하고 예쁜 카페! 주말 운좋게 한자리 남아있어서 대기없이 들어갈 수 있었어요! 크림브륄레라떼 크림이 너무 부드럽고 실라떼는 고소하니 맛있었어요! 친절하고 좋은 카페였습니당~!', 28, 5, 'GOOD', SYSTIMESTAMP);
