INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '홍대 카공 카페 찾는다면 작업실01 강추예요! 분위기도 아늑하고 전반적으로 조용해서 집중하기 너무 좋고 인테리어 하나하나 취향저격이에요 ♥', 66, 17, 'GOOD', SYSTIMESTAMP);
