INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '제가 홍대에서 가장 아끼는 카페!! 인데 갈 때마다 자리가 없어서 못 갔다가 오랜만에 또 갔어요 ㅎㅎ 자격증 시험기간이라 공부도 하고 좋아하는 시집도 읽고~~ 일기도 쓰고 :) 작업하기 좋은 공간이에요 나만 알고 싶지만 이미 유명할 대로 유명해져버린 공간..✨', 8, 6, 'GOOD', SYSTIMESTAMP);
