INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '공간이 아기자기하고 예뻐요. 테이블 간격이 좁긴 하지만 분위기가 좋고, 음료가 맛있어서 또 갈 것 같아요. 아인쑥페너 존맛 강추', 13, 10, 'GOOD', SYSTIMESTAMP);
