INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '복잡한 홍대거리 속 한적한 골목에 위치해있습니다 찾기 어렵지는 않았지만 눈에 띄지는 않았습니다 혼자 앉을 수 있는 자리가 따로 있어서 혼자와도 좋을 것 같습니다 물론 저도 혼자 갔지만요😆 따듯한 조명과 시끄럽지 않은 음악으로 가게 분위기가 너무 좋았습니다 커피나 라떼를 먹을까 했지만 배고파서 밀크티 크림 라떼를 먹었는데 크림이 굉장히 부드럽고 달아서 빠르게 먹었네요 사진은 못 찍었습니다ㅎ 분위기가 너무 좋아서 다시 방문하고 싶은 장소입니다', 128, 19, 'GOOD', SYSTIMESTAMP);
