INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '말차라떼 덜달게 해달라고 말씀드려서 해주셨는데, 위에 크림이 달아서 남겼습니다. 초코 다쿠아즈맛있습니다. 홍대에서 연남동 스러운 카페가 있어서 신기했습니다.', 73, 15, NULL, SYSTIMESTAMP);
