INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '작업하거나 책보기 좋아요  근데 조명이어두워서 책볼땐 눈이 좀....  노래가 볼륨이 커요 가사없는 노래거나 볼륨이 좀 작으면 좋겠어요~  아 그리고 와아파이가 한글인데, 구형노트북은  영어만 인식해서 와이파이 못잡음요 ㅋㅋ', 52, 17, 'BAD', SYSTIMESTAMP);
