INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '대화하기도 좋지만, 카페 이름만큼 작업하기 정말 좋은 카페☕️ 콘센트도 여기저기 정말 많고 와서 그냥 책 읽는 분들도 많았어요.', 191, 53, 'GOOD', SYSTIMESTAMP);
