INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '노트북 하는 사람들이 많은 카페:) 저는 먼저 혼자가서 노트북 좀 하다가 남자친구도 와서 같이 커피 마셨는데 혼자가서도 누군가랑 같이가도 좋은 카페인거같아요!', 23, 5, 'GOOD', SYSTIMESTAMP);
