INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '엄청 조용하고 각자 일하거나 책 읽는 분위기. 이어폰 끼신 분들도 많았음. 구석에서 조용히 대화했는데 저녁에는 불 꺼지고 사람 점점 없어져서 오히려 좋았음..! 근데 음료 가격 좀 비쌈(7000) 홍대라 어쩔 수 없겠지,,', 43, 8, NULL, SYSTIMESTAMP);
