INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '분위기가 너무 좋은 곳! 홍대 메인 길이나 연남동쪽 카페들은 사람이 정말 많아서 시끄러운데 이곳은 조용한 분위기에 아주 예쁜 조명, 인테리어가 마음에 들었어요! 게다가 다쿠아즈가 정말 맛있습니다ㅠㅠㅠㅠ안 먹으면 범죄에요,,!♥️', 75, 16, 'GOOD', SYSTIMESTAMP);
