INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '평점 엄청 높길래 가봤는데 커피랑 음료 기대 이상으로 맛있었습니당 번화가랑 가까운데 되게 조용한 뒷골목에 있고 테이블이 많진 않아요. 근데 사람 진짜 많았어요. 혼자 가기 좋은 카페인 듯', 123, 25, 'GOOD', SYSTIMESTAMP);
