INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '북카페처럼 정숙하고, 따뜻한 인테리어가 맘에 들었습니다. 그래서 그런지 과제나 팀플하시는 분들이 많았습니다. 사장님 혼자 하시는거라 메뉴 나오는데 시간은 좀 걸렸지만, 디저트 살살 녹아용🎶 친구나 연인이랑 이야기 하기 좋은 예쁜 카페!', 35, 3, 'GOOD', SYSTIMESTAMP);
