INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '진짜 제가 지금까지 찾던 최고의 카페예요… 앞으로 홍대 갈 일 있을 때마다 올거예여ㅠ 창가 1인석 자리에서 조용히 책 읽고 공부하기 너무 좋습니당… 씰 라떼짱', 27, 7, 'GOOD', SYSTIMESTAMP);
