INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '시그니처인 실라떼 추천해주셔서 먹어봤는데 기대이상으로 너무 맛있었어요 !! 😭 다른 모카라떼랑은 다른 느낌 .. 위에 올라가는 크림도 맛있고 같이 시킨 크림브륄레도 맛있었습니다 !', 16, 6, 'GOOD', SYSTIMESTAMP);
