INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '작업하기 좋은 분위라고 홍보하길래 왔더니 딱히 일반 카페랑 다르지 않은 경험 함. 처음 들어섰을 땐 다들 조용히 작업하고 있었지만, 그냥 수다 떨러 들어온 팀이 시끄럽게 굴어도 아무런 제지도 없음. 이어폰도 없이 애기들 소리지르고 떼쓰는 영상 보면서 귀엽다고 큰 소리로 깔깔대는데 진짜 최소한 이어폰 껴 달라던가 목소리 좀 낮춰달라고 한 마디는 해줄 줄 알았음. 스터디카페 아니니까 그정도 수준을 기대한 건 아니고 작업 회의하느라 대화하는 팀이었다면 이해하겠는데, 컨셉과 홍보한 내용에 맞는 최소한의 기대를 충족 못함.', 124, 19, 'BAD', SYSTIMESTAMP);
