INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '저번에 갔을땐 닫았어서 방문 못해서 다시 찾아갔는데 생각보다 넓었고 음료도 맛있었어요!! 크리스마스 분위기나게 트리도 있어서 좋았습니다😍🎄', 33, 5, 'GOOD', SYSTIMESTAMP);
