INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '커플이나 친구끼리 가도 좋을 것 같아요~! 대화하기 편하고 무엇보다 디저트가 진짜 너무너무너무너무너무너무너무 맛있어요‼️💕 특히 크림브뤨레 라떼를 처음 먹어보는데 저는 단거 좋아해서 조금 떠 먹고 섞어 먹었어요🤭❣️ 진짜 꿀맛 그리고 마시기 전에 어떻게 먹어야 맛있는지 단 거 싫어하시는 분들도 부담없이 마실 수 있게 자세히 알려주셔서 좋았던 것 같아요~!! 대화 하기에 부담 스럽지 않아서 분위기도 나쁘지 않았던 것 같습니다 ㅎㅎ', 84, 13, 'GOOD', SYSTIMESTAMP);
