INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '홍대에서 가장 괜찮은 작업 공간이에요! 네이밍 그대로 작업실! 혼자와서 맥주도 한잔하고 커피도 한잔하면서 놉북 작업하기 넘 좋아요. 창업준비하는 분들 삼삼오오 와서 작업해도 되고, 둘이와서 수다떨기도 좋아요. 가구 구성이 다양해서 목적에 맞게 앉을 수 있어요ㅎㅎㅎ홍대에 번잡스러움이 전혀 느껴지지 않고 은은한 음악때문에 다른 분 대화소리가 잘 안들려요^^ 다시 올것같아요. 곧 멤버십도 한다고하니 멤버십도 ㄱㅇㄷ', 73, 12, 'GOOD', SYSTIMESTAMP);
