INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '퇴근하고 조용히 앉아 책한권 꺼내들고 누구에게도 방해받지않으면서 편하고 여유롭게 맥주한잔 할 수 있는 공간. 하루를 개운하게 마무리하기 딱 좋아요 :)', 24, 1, 'GOOD', SYSTIMESTAMP);
