INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '좌석마다 콘센트있어서 노트북 사용하는 분들 강추입니다!!! 조용하게 일하기도 좋고 언더락에 위스키까지 마실수 있네요 저한텐 최고의 플레이스!!! 자주 찾아뵐게요', 43, 7, 'GOOD', SYSTIMESTAMP);
