INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '이런곳이 생겨서 너무 좋습니다. 조용히 집중 할수있고, 매장도 너무 쾌적하네요 다음엔 술한잔 하면서 작업해봐야겠어요~ 사장님도 친절하시고 좋네요~ !', 53, 13, 'GOOD', SYSTIMESTAMP);
