INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작업실01'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '조용히 작업하기에는 최고에요 일반카페는 소음도 있고 눈치도 좀 보이는데 컨셉이 작업용 카페라 일반카페보다 편히 집중할 수 있었네요', 66, 13, 'GOOD', SYSTIMESTAMP);
