INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시타커피로스터스'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '콩고물크림커피 처음 먹어보는 맛인데 좋았어요. 흑임자랑 비슷하면서도 달라요. 당도도 적당했습니다. 드립도 훌륭합니다. 공간도 예쁘고 친절하셔서 기분좋게 머물다 갑니다.', 29, 3, 'GOOD', SYSTIMESTAMP);
