INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시타커피로스터스'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '올때마다 더 좋아지는 곳. 첨엔 혼자 책읽으러 왔다가 너무 좋아서 동료들 데리고 수다떨러도 왔었어요 올때마다 추천해주신 커피도, 잘 어울리는 디저트도 너무 맛있었고. 사장님 두분 성격이 넘 좋으셔서 기분이 좋아져요. 오늘은 친구 기다릴겸와서 이미 카페인을 마신터라 티를 주문했는데 커피만큼 티도 너무 맛있어요 오래오래 장사해주셨으면 좋겠어요!', 22, 9, 'GOOD', SYSTIMESTAMP);
