INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시타커피로스터스'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '한 달 내내 시그니처 게이트 도어 컬러가 탈바꿈하는 걸 오가는 길에 봐가며 커피맛이 궁금했는데 드디어 오늘 들려봄… 소프트 오프닝이라 오전엔 한적.. 드 디 어 서교동에.. 머물다 가고 싶은 카페 하나 더 추가요.. 추적추적 비가 내리길래 우연히 원두를 잘 이해하시고, 추출까지 완벽한 댄디한 영맨 사장님과 소쿨 매력 직원분이 계셨.. 이 골목에 이만한 찐 커피를 아는 카페라니.. 왠걸… 넘 반갑고 오래오래 잘되시면 좋겠…! 커피 스몰 토크가 가능한 아늑한 소공간 잘 마시고 갑니다아앙 ☕️', 36, 3, 'GOOD', SYSTIMESTAMP);
