INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시타커피로스터스'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '친구 추천으로 다녀온 카페인데, 분위기 너무 좋고 드립커피 향도 좋고 깔끔해서 넘 맛있었어요!! 사장님이 주문 받을때부터 웃는 얼굴로 반겨주시고, 원두 설명도 친절하게 해주셔서 참 좋았습니다:D 아🤭 피칸정과도 적당히 달고 고소해서 넘 맛있었어요~ 케이크류도 다음에 방문해서 꼭 먹어보려구요^^', 112, 22, 'GOOD', SYSTIMESTAMP);
