INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시타커피로스터스'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '게이샤커피 넘 맛있어요..! 바닐라빈라떼 시럽은 직접 만드신다고 합니다. 다들 꼭 드셔보세요!! 어떤 커피를 주문해야 할지 올 때마다 항상 망설이게 되네요😋', 84, 13, 'GOOD', SYSTIMESTAMP);
