INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시타커피로스터스'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '시그니처 커피 추천해주셨는데 그 중에 콩고물 커피 먹었어용!! 다른 크림커피처럼 과하게 달지도 않고 진짜 좋은 재료로 만든게 느껴져요 !! 넘 맛있어여...🤤🤤 그리고 서비스가 너무 친절해여... 기분좋아지는.. 🫠😚 담에 또 와야겠음!!!!!!', 3, 6, 'GOOD', SYSTIMESTAMP);
