INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시타커피로스터스'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '제가 좋아하던 커피 원두를 직접 볶으시던 사장님이 직접 카페를 창업했다고 하셔서 방문했어요. 역시 커피맛이 역시네요. 너무 친절하시고 더욱더 번창하세요!!!', 36, 6, 'GOOD', SYSTIMESTAMP);
