INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페카운티 홍대점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '24시간 영업이라 시간 생각 안 하고 오기 좋아요. 조각케이크 가격이 5000원 미만에 감동받고 갑니다. 초코무스케이크 맛있네요.', 46, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페카운티 홍대점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '홍대입구역, 합정역, 망원역에서 접근성 좋게 이용 할 수 있는 카페입니다. 커피, 음료, 디저트가 정말 다양하기때문에 취향따라 골라 먹는 재미를 기대 할 수 있겠으며 서교동 동네 평균 가격을 생각 했을 때 정말 합리적인 가격대에 메뉴가 운영중이기때문에 이 또한 매장을 이용하는데 도움이 되겠습니다. 건물 뒷편에 4대 정도 주차가 가능했으며 공영주차장도 가깝기 때문에 주차 걱정없이 내방이 가능했습니다. 그리고 매장도 넓고 단체석도 마련이 되어 있어 여럿이서 방문을 하더라도 불편함없는 이용이 가능하겠습니다. 합리적인 가격 덕분에 맛보고 싶었던 커피, 음료, 디저트 모두 맛봤으며 앞으로 자주 들릴 것 같습니다. 감사합니다:)', 20, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페카운티 홍대점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '⭐️⭐️매장 정말 넓고 쾌적 그 자체예요! 굽네볼케이노 통밀 닭가슴살 샌드위치랑 콘에그&불고기 통밀 샌드위치 주문했는데 신선한 야채와 두툼하고 살짝 매콤한 닭가슴살이 건강한 한 끼를 챙겨주는 느낌이였고, 치킨이 먹고 싶지만 못 먹는 다이어터를 위한 메뉴!! (정말 뚱뚱한 샌드위치라 입이 찢어지는 것은 주의!) 콘에그&불고기 통밀 샌드위치는 적절하게 양념된 불고기와 신선한 야채와 맛도리 조합 콘에그였어요! 정말 최고 메뉴👍👍 또 통밀로 바꿔서 먹으니 더 건강한 한 끼를 먹는 것 같았어요. 강추‼️‼️', 116, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페카운티 홍대점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '넓고 커피 맛있고 디저트 많고 가격도 합리적 게다가 연중무휴 새벽에 유일하게 홍대입구에서 맘편히 갈 수 있는곳! 짱!!!! 다만..새벽이라 그런지 모기가 좀 있음..킹받음 긴바지 입고 가시길 추천', 24, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페카운티 홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '생딸기라떼 양도 많고 맛있고 아샷추도 찐으로 맛나요! 콘에그샌드위치 푸짐하게 너무 맛있게 잘먹고 갑니다 담엔 또 다른거 먹으러 올게요 ~', 41, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페카운티 홍대점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '다음날 아침에 먹을 샌드위치를 미리 사려고 방문한 카페카운티..! 샌드위치를 포함한 디저트랑 음료종류가 진짜 엄청 많아서 놀랐어요 그래서 파이랑 마카롱도 하나 더 샀답니다 히히..달달허이 맛있었어요! 가장 중요한 샌드위치가 다음날에도 빵이 촉촉하고 바질향도 듬뿍나는게 너무 신선하니 좋았어요..! 다음에 또 사먹으려구요 ㅎㅁㅎ', 78, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페카운티 홍대점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '편안하게 언제든지 방문하기 좋은 서교동 24시 카페, 카페카운티 홍대점 📌특징: 24시간 내내 운영하는 카페로 밤에 출출하거나 달달한 디저트가 당길때 방문하거나 배달시키기 좋은 곳. 스콘 종류가 굉장히 많았고 샌드위치 종류도 제법 있는 편. 📌후기: 샌드위치와 아메를 세트로 주문하면 조금 더 저렴한 가격으로 먹을 수 있고, 카페카운티의 샌드위치는 한 끼 식사로는 조금 부족할 수도 있는 양. 맛은 무난한 편이고 500원 추가하면 다른 맛의 샌드위치를 반반으로 고를 수 있음.', 30, 10, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페카운티 홍대점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '친구네 동네갔다가 여기가 딸기라떼가 맛있다고 극찬해서 저녁겸햐서 샌드위치랑 딸기라떼 포장했는데 종류도 정말 다양하고 매장에서 먹기도 편한곳이라 근처살면 저구갈것같아요 커피도 맛있는데 디저트 종류도 너무 다양해서 점심으로 먹기도 건강하고 딸기라떼는 정말 과하게 달지않아 짱맛있음 샌드위치도 통밀이라 굳귣 조만간 또 포장해갈듯요', 83, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페카운티 홍대점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '카운티에 처음 방문했는데 카운터에 계시는분이 친철하셨고 깨끗한 매장 이었어요. 커피는 운전할때 많이 마셔서 흑임자라떼 추천해 주셔서 먹어 봤는데 타 카페와 달리 재료를 아끼지 않는듯한 걸죽하게 흑임자 맛이었어요. 통블루라떼도 먹어봤는데 맨날 갈려져 있는거 먹다가 통으로 먹으니 톡톡 터지는게 재미있었어요ㅋ 맛은 단연v 수제로 만든 샌드위치도 이 가격에 맛있게 잘먹었습니다. 다음에 또 들릴께요~', 72, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페카운티 홍대점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '새로 생긴곳이라 바로가봤습니다. 종류가 많아서 뭘 고를지 고민입니다. 평타이상 예상한맛이지만 고르는 재미가 있네요 ㅎㅎ.. 메뉴 전부 하나씩 먹으러 가려구요 !', 62, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페카운티 홍대점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '24시간 영업하신다던데 이른아침에 방문해도 맛있는 커피 먹을수 있어서 더 조아요 실내도 환하고 예뻐요 샌드위치도 종류도 많고 라떼종류도 맛날거 같아요 디카페인도 친구가 맛있다고 했어요 사장님 번창하세요~^^', 111, 20, 'GOOD', SYSTIMESTAMP);
