INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'NUHOOD'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '분위기가 차분하고 조용해서 꼭 노트북 작업이 아니어도 각종 글 쓰기, 멘탈 힐링(?), 플래너 등 정리하기 좋은 곳 .ᐟ 👍🤭 무엇보다 후르츠콕이 기대 이상으로 너무 맛있었어요 진짜ㅜㅜ한잔 더 시켜 마시고 싶은 욕망을 겨우 참았습니다,,,🌟🥲 물론 다음에는 진짜로 두잔을 마실 수도 있어요🤭🤭 게다가 사장님도 연예인 닮으시고 친절하셔서 감동 한잔 이빠이 받고 여기에 제대로 반해서 단골 될 것 같습니다😇🥰', 5, 4, 'GOOD', SYSTIMESTAMP);
