INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'NUHOOD'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '요즘 핫한 카페라고 해서 방문해보았습니다. 내부가 상당히 어두운데 이런 곳에서 작업하는 거 좋아하시는 분들은 놋북작업도 좋을 듯. 커피 맛있습니다', 11, 10, 'GOOD', SYSTIMESTAMP);
