INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'NUHOOD'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '분위기 넘 좋고 노트북 하기도 편한 카페. 커피도 괜찮고 화장실도 깨끗하고 사장님도 친절하셔서 넘 좋았어요 담에 또 방문할게요~~', 59, 17, 'GOOD', SYSTIMESTAMP);
