INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'NUHOOD'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '저녁에 조명으로 분위기 아늑하고 좋아요✨🕯️ 맥주, 와인, 커피, 디저트, 안주 다 있어서 술 좋아하는 사람과 커피 좋아하는 사람 같이 가면 둘 다 만족도 백퍼입니다ㅎㅎ 바넛푸딩은 바나나푸딩이랑 비슷한데 떡이 들어가 있어서 독특하고 맛있었어요. 츄러스도 크림+시나몬 같이 나와서 안주로도 추천입니다. ☺️', 117, 25, 'GOOD', SYSTIMESTAMP);
