INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'NUHOOD'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '장난감 같은 에그타르트 😆 에타 전문점 처럼 맛있지는 않았지만 뭐랄까, 귀여운 맛이랄까? ㅎㅎ 라떼도 맛있공 밀크티도 맛있네용💕', 8, 6, 'GOOD', SYSTIMESTAMP);
