INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'NUHOOD'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '동네 돌아다니다가 느낌 좋아서 방문했는데 음료도 맛있고 분위기 좋아서 이번이 3회차 입니다. 저번에 먹은 후르츠 콕 맛있고 친구가 먹은 고구마 라떼도 너무너무 맛있어서 겨울 완전 강추입니다!! 바넛 푸딩도 진하고 같이 잘먹었습니다!! 오늘은 프라하케익이랑 커피 먹었는데 따뜻하고 맛있어서 단골 될거같아요..... 저녁 늦게 왔는데 너무 친절하시구 카페 분위기도 너무 좋아서 오래 앉아 있다 갑니다......쵝오👍', 22, 4, 'GOOD', SYSTIMESTAMP);
