INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'NUHOOD'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '넓고 분위기가 조용해 작업하기 좋아요! 연필이랑 종이가 구비되어 있어서 편안하게 낙서하는 것도 누후드만의 갬성..✨ 음료도 맛있었지만 서비스로 주신 작은 쿠키가 진짜 맛있어서 친구랑 감탄하면서 먹었습니다:) 다음에는 디저트 먹으러 가려구요❕', 5, 2, 'GOOD', SYSTIMESTAMP);
