INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'NUHOOD'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '지나가면서 공사할 때부터 오고 싶었던 카페입니다! 제도에 안나와서 의아했는데 드디어…! 오픈 했다고 해서  왔습니다 사장님도 친절하시고 전 메뉴 넘 맛있습니다. 곡센스와 작업러 분들을 위한 1책상 1콘센트까지 완벽한 카페입니다😭😭 홍대 올 때 마다 오겠습니다!', 6, 8, 'GOOD', SYSTIMESTAMP);
