INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'NUHOOD'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '요즘 집중 할 일이 있거나 조용히 커피를 마시고 싶을때 힐링차 방문해요! 내부 인테리어가 아늑하고 편안합니다 예뻐서 대충 사진 찍어도 멋진 사진이 나와용 ㅎㅎ 사장님도 굉장히 친절하세요! 커피를 직접 가져와주시는데 그릇을 놓을때도 세팅을 신경써주시는 섬세함이 있으십니다 주변에 좋은 카페가 있어서 행복해요🍀🍀', 20, 6, 'GOOD', SYSTIMESTAMP);
