INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'NUHOOD'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '여긴 정말 조아요.. 너무나도... 분위기도 인스타 감성 분위기 좋은 카페.. 심지어 커피도 맛있어서 회사랑 거리가 좀 있는데 늘 여기서 시켜먹어요.. 출근 하는 날마다 왔는데 잊고 있다가 이제서야 리뷰 쓰네요.. 돈 많이 버세요 사장님', 88, 15, 'GOOD', SYSTIMESTAMP);
