INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'NUHOOD'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '생긴지 얼마 안된 카페인데 분위기도 좋고 음료도 맛있어요! 여유로운 분위기에 잔잔한 음악과 함께 집중하기 좋아요. 사장님 친절하시고 제로콜라음료가 메뉴에 없는데 손수 준비해주서서 완전 감동했습니다! 다음에 또 올게요:)', 7, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'NUHOOD'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '느려도 너~~~무 느려요. 맛은 있는데 한번 주문하면 기본 15-20분 걸립니다. 이렇게 느릴거면 진동벨을 쓰세요. 사장님이 테이블마다 음료까지 가져다주니 누가 주문했는지 헷갈려하시고.. 올때마다 오래걸려서 맛있는데도 늘 오기가 주저됩니다.', 8, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'NUHOOD'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '공간도 조용해서 좋고 무엇보다 사장님이 엄청 친절하세요!! 서비스로 주신 쿠키와 차 잘 마셨습니다...🍋🍪 다음에 또 올게요 :))', 78, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'NUHOOD'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '친구랑 합정역에서 1차로 맛집 푸파하고 2차로 카페 푸파했네요 🤣 합정역에서 분위기 있는, 음악 좋은 카페 찾는다면 무조건 추천 합니다💓 맛있는 커피, 달달한 디저트는 베이스로 깔려 있어요 재방문 의사 무조건 있음', 6, 1, 'GOOD', SYSTIMESTAMP);
