INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'NUHOOD'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '서비스로 쿠키도주셨는데 못찍고 냅다먹었습니다 고구마라떼 짱맛있어요! 고구마 러버인데 찐고구마가 들어있어서 인공적인맛이아니라 넘 좋았고 책읽기도 너무 좋네요 또올거에요💛', 20, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'NUHOOD'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '두번째 방문입니다 라떼 샷추가해서 먹었는데 아주 좋아요 시그니쳐 디져트인 푸딩도 진한 커피와 잘어울립니다. 밤에오니 분위기가 더 좋아요👍', 5, 6, 'GOOD', SYSTIMESTAMP);
