INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '다시 오픈해서 너무 좋아요! 직원분도 친절하시고 베이글도 맛있습니다 ㅎㅎ ! 이벤트 가격이라 저렴하게 먹어서 완전 만족해요...😍 또 방문할게요~!', 3, 8, 'GOOD', SYSTIMESTAMP);
