INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '홍대 24시간 영업하는 카페입니다. 9시 반부터는 무인이에요. 공간도 꽤 넓고 콘센트도 잘 되어있어 작업하기 아주 좋습니다. 카페에서 각종 베이글이랑 디저트를 많이 팔아서 출출할때 사먹기도 좋아요. 라떼(6.5)를 마셨는데 콜드브루 라떼더라고요. 개인적으로 콜드브루 좋아해서 더 맛있게 먹었습니다. 홍대에서 밤 늦게 들릴만한 카페로 추천드려요!!', 45, 3, 'GOOD', SYSTIMESTAMP);
