INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '3주년(?)행사라 소금빵 1500원 부담없는가격에 즐기기 너무좋았어요 🥐💛 저는 대파크림치즈소금빵이 제일 맛있었네요 인당3개까지 음료주문시에만 할인된가격으로 구매가능하니 참고하세용', 38, 7, 'GOOD', SYSTIMESTAMP);
