INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '가끔 디저트는 포장 주문해서 먹던 곳이라, 더위 식힐 겸 잠시 들러 음료만 마시고 왔습니다. 매장 분위기도 나쁘지 않고, 맛있게 먹고 나오는데 여자 매니저 분?으로 보이는 분이 다 마신 컵 반납 안내하는 말투가 매우 차갑고 불친절하시더군요; 요즘 더운 날씨에 업무가 바빠 경황이 없더라도 조금 더 고객을 배려해 주시면 어떨까 하는 마음에 리뷰 남깁니다.', 33, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '커피 맛있어서 마음에 들어요. 디저트 종류도 많고 샌드위치도 있어서 간단한 브런치 먹을 수 있었어요. 위치때문인지 조용하고 여유로운 분위기도 좋았구요. 참, 여기 24시간 운영한다니 밤에 카페가 필요할때를 위해 기억해 두려고요 ㅎㅎ', 50, 0, 'GOOD', SYSTIMESTAMP);
