INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '컨셉이 웃김. 무인카페라는데 직원이 여러분 있었고 쇼케이스에서 베이커리류랑 음료가져가면 세팅을 해줌.. 그냥 인건비 아끼시려는거 같은데 그래도 무인카페는 아닌듯…ㅎ', 15, 2, NULL, SYSTIMESTAMP);
