INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '음료도 맛있고 뭐 예 그런데 그것보다 전화해보고 10:30부터 무인매장운영이라고해서 부랴부랴 일부러 여기로 가서 10시에 도착했습니다 그런데10시부터 디저트 대부분 안 되고 커피도 미리 포장된 것만 된다고 하더라구요 그럼 전화할 때 말해주실 수 있는거 아닌가 싶었습니다 10:30부터 사람이 없다고 해도 10시부터로 무인운영으로 수정하던가 하세용 괜히 방문했나싶엇습니다', 3, 7, NULL, SYSTIMESTAMP);
