INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '아침에 커피 사러 갔는데 샷을 반도 안 뽑고 주시네요.. 포터필터가 원샷짜리가 없어서 그런거라면 물양을 조절하셨을거 같은데 제가 보기엔 원두양은 투샷 같아 보였어요. 샷을 한 7초? 정도 추출도중에 눌러서 멈추고 그것만 담아주시는데 양으로는 반샷 정도 되어보였네요. 테이크아웃은 반값이라 반만 주시는건가요..?😂 샷 양이 너무 적어서 커피맛이 어떤지 느낄수가 없었어요 다른 직원분이 계실때 다시 방문해보겠지만 아니면 원래 그렇게 추출해주시는건지 진짜 궁금해서 씁니다 저도 카페를 했었고 이 동네 카페 운영 빡센거 잘 알기에 혹시 알바분이 잘못하신거라면 안타까운마음이라 그냥 지나가지 못하고 남깁니다..', 41, 8, 'BAD', SYSTIMESTAMP);
