INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '분위기 너무 좋고 대화하기 편했어요. 다른곳은 너무 시끄러워서… 주문할때 키오스크 이용은 좀 불편한편이고 베이글과 크로와상 소금빵 맛집인듯요.', 1, 0, 'GOOD', SYSTIMESTAMP);
