INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '카페라떼랑 아메리카노 시켰는데 맛있어요 고소하고 시원하고 좋네요✨내부도 넓찍하고 사진이 잘 나와서 좋았어요 보니까 빵도 팔더라구요 다음엔 디저트와 함께 먹고싶어요. 디저트도 퀄리티 좋아보여요', 39, 7, 'GOOD', SYSTIMESTAMP);
