INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '베이글이 싸길래 8개 구매했어요~베이글은 싸고 맛있어요~리뷰에 친절하다고 많이 얘기하시는데 사장님인지 직원분이신지 남자분..썩  친절한 느낌은 아니었어요. 저한테만 쌔하신건가유? 그래도 베이글이 싸고 맛있어서 자주 갈 것 같습니당~', 44, 1, 'GOOD', SYSTIMESTAMP);
