INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '우선 알바가 매우매우매우 친절 ㅠㅠ 냅킨이랑 물티슈 완벽 구비돼있고 매장이 넓은데도 관리가 잘되어 청결함 카페는 2층이라 넓구 편하고, 수다떨기 좋은 카페. 여럿이 가서 조별과제하기도 좋고 친구랑 밥먹고 들리기도 좋음 그리고 리얼그린이 맛있다', 35, 0, 'GOOD', SYSTIMESTAMP);
