INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '너티크림라떼 강추.. 크림이 부드럽고 커피가 진하니 맛있어요. 휘낭시에와 소금빵 좋아해서 시켜봤는데 베이커리도 맛있어요 테이블과 의자도 많고 분위기 좋아서 대화 나누기도 편했어요 커피랑 베이커리 맛있어서 홍대 가면 또 갈 의사 있어요.', 45, 0, 'GOOD', SYSTIMESTAMP);
