INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '날이 너무 더워서 걷던 도중 있던 카페라서 뭣도 모르고 들어갔는데 너무 예쁘고 커피맛도 좋네요ㅋㅋㅋㅋ 카페 사진 찍고 싶었는데 사람이 많아서 나중에 먹고싶은 음려 사진 찍어둔거 올립니다 ㅋㅋㅋ !!! 다음에는 저거 먹으러 꼭 가야할 것 같아요', 73, 16, 'GOOD', SYSTIMESTAMP);
