INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '매장도 청결하고 친절함까지 있어 주문할 때 부담이 없어서 좋았습니다~ 커피종류도 다양해서 원하는 맛을 골라서 먹었는데 진짜 맛이 좋았어요~~다시 생각나는 커피맛 또 올께요^^', 0, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '매장도 넓고 분위기 너무 좋았어요! 특히 테라스에 마시는 커피맛 최고👍 커피회사에서 운영하는 곳이라 그런지 커피맛도 깊고 너무 제가 좋아하는st였다는 .. 지나가다 자주 갈것 같아요', 16, 10, 'GOOD', SYSTIMESTAMP);
