INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '카페 분위기도 너무 좋고 오토 베이글도 너무 맛있네요. 특히 플레인 스콘이 커피와 진짜 잘 어울리더라구요. 제 입맛에 딱 맞았어요. 분위기도 괜찮아서 친구랑 얘기하면서 시간 잘 녹였습니다 ㅋㅋ', 65, 17, 'GOOD', SYSTIMESTAMP);
