INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '매장에서 예쁘고 아기자기하게 포장되있는 상품을 봤어용 ~~~~ ㅎ 너무 예뻐서 정말 에 ㅜ ? 이거 담으려구 그랬다고 ? 싶었지만서도 괜히 기분은 좋드라구요 ㅎ 솔직히 요즘 입으로만 즐기는게 아니라 눈으로도 즐기잖아요 ~~ ㅎ', 460, 70, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '베이글 귀신인데 이렇게 맛있어도 되는거야 나 살찔 준비됬어 매일 보자 이글아~여름 내내 먹으러 와야지:) 신랑도 맛있다고 한입씩 뺏어먹는데 이래서 부족했나 ㅋㅋ 또가야징', 15, 0, 'GOOD', SYSTIMESTAMP);
