INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '에소프레소 맛이 깔끔함. 여기 원두 좋은 거 쓰는듯 모카향이 진하고 산미 없어서 딱 내 취향 에소프레소 가격은 좀 있는 편이지만 분위기가 괜찮아서 추천함 가게도 넓고 대화하기도 집중하기도 좋음! 선곡센스가 그냥 미쳤음', 45, 8, 'GOOD', SYSTIMESTAMP);
