INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '베이글과 크림치즈가 맛있습니다. 근데 직원이 멍청하고 불친절해요 23.04.19 수요일 낮 12시 근무하셨던 여자직원분 빵포장 당시 밀봉하지말아달라는  요청사항을 옆에 포장하는 남직원한테 말씀을 안했더라구요 ? 저는 해주겠거니하고 다른데 보고있었는데 ㅡㅡ 물론 아주 사소한 것이긴 하지만 그래서 받아갈때 밀봉이 되어있어 엇 ! 이거 밀봉하지 말아주세요 하면서 제가 밀봉된걸 풀면서 결제하면서 말씀드렸는데 전달이 안됬나바요라고 했더니 주문받은 그 여자분이 ''아 네'' 대답이 끝이었습니다. 심지어 포장기다리는 손님이 한명 ... 바쁘면 말도안해요 .. 한가한데 별것도 아닌 요청도 안들어주면서 본인이 잘못한줄도 모르는 사람이 무슨 서비스직을 하는지 모르겠네요. 그렇세 뻔뻔하실거면 다른일 찾아보세요', 42, 5, 'BAD', SYSTIMESTAMP);
