INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '베이커리 카페. 마들렌이 맛있어요. >_< 카야코코넛 마들렌 존맛이예요. 위에 카야쨈이 올라가는데 빵이랑 같이먹으면 달달 구리한게 굿굿. 날풀리면 루프탑에서 커피마시기 하면 너무 좋을꺼같아요', 123, 25, 'GOOD', SYSTIMESTAMP);
