INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '화이트롤케이크 겉면은 쫀득한 막으로 싸여있고  안에는 부드러운 빵과 크림이  가득있어 맛있습니다. 위에 장식된 새콤달콤한 건레몬칩과 레몬크림&허브가 케이크의 맛을 배가시킵니다.', 79, 15, 'GOOD', SYSTIMESTAMP);
