INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '퍼스트커피랩 홍대점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '4월 17일 오후 4시 45분경 6명이 테이블에 앉아 있는 것을 보고 깜짝 놀랐습니다. 가족 같아 보이진 않아서 그런데 방역 수칙 위반 아닌가요? 그리고 예전 주차장 자리를 확장 한거 같은데 그렇다면 문제가 있겠네요. 사진은 문제시 될까봐 다 블러 했고요. 다시는 이런일 없기를 바랍니다. 제가 오해한거라면 글 지우겠습니다.', 38, 2, 'BAD', SYSTIMESTAMP);
