INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멜로우'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '망빙하면 멜로우가 생각하서 홍대에 놀러온 김에 왔는데 오픈한지 얼마 안되서 들어가서 그런지 거의 웨이팅 없이 들어왔어요 먹자마자 우유얼음에 망고가 살살 녹아가지구ㅠㅠㅠ 얼마나 맛잇던지… 이맛에 자꾸 홍대 놀러오면 꼭 들리네요🥰', 32, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멜로우'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '친구랑 빙수를 찾아온 멜로우!! 수박빙수🍉를 먹었는데 진짜 맛있습니다ㅜㅜ 멜론빙수🍈도 담에 남자친구랑 먹을거에요! 특히 만들어 주시는 직원분들께서 엄청 신경써서 만드시는게 보여서 더 좋았습니다! 감사하게 잘 먹었어용🫶', 34, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멜로우'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '지나가다가 메뉴판 현수막을 보고 우연히 가게된 곳이에요:) 골목에 있는 반지하층의 카페다보니 아무래도 사람들 눈에 쉽게 띄지는 않는 것 같아요! 조용하게 앉아서 먹을 수 있고 다양한 연예인등 생일 카페를 하는지 싸인도 많았어요:) 커피도 괜찮았고 빙수는 애플망고로 바꿔서 먹었는데 그날 망고는 그렇게 달지 않았지만..ㅠ 사람 북적이는 길에서 벗어나 조금 쉴수 있는 공간이 되었어요!', 75, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멜로우'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '멜로우가 다시 딸기제철로 바뀌었다는 소식을 알았지만 늦게 와버렸는데요ㅠㅠㅠ 역시나 딸기위주로 시켯더니만 맛잇게 먹엇던 기억이 다시 나는거에여!! 왜 다들 안 드시나요?? 완전 추천합니다 여기 빙수 환상이에요 크레이프는 옵션입니다아 후훗', 16, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멜로우'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '홍대에서 친구들이랑 들리기 좋은 크로플 맛집으로 완전 추천해요.. 🫶🫶 리뷰 원래 잘 안쓰는데, 여기는 진짜 써야할 것 같네여.. 딸기생크림크로플 하나 시켰는데 존맛탱.. 브라운치즈 크로플도 추가로 시켰어요 ㅜㅜ 친구도 맛있다고 다음에 또 오자구 그러더라구여 ㅜㅜ 정말 만족했어용!! 맛은 물론 비주얼도 완벽해서 사진 찍기 딱 좋고, 인테리어도 아기자기하고 귀여워서 분위기가 정말 좋아요. 다음엔 남자친구랑 방문할게요~!! 예쁘고 맛있는 크로플 찾으신다면 여기 꼭 가보세용!!😘🫶', 123, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멜로우'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '인테리어도 너무 예쁘고 분위기도 좋았어요!! 친구랑 맛있는거 잔뜩 먹고 싶을 때 꼭 다시 먹으러 올려구요❤️ 사장님도 너무 친절하셔서 리뷰 잘 안쓰는데 꼭 쓰고싶은 카페였어요 :) 덕분에 맛있게 먹구 좋은 시간 만들고 가요 체고❤️❤️', 27, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멜로우'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '여자친구와 딸기빙수 검색해서 간 멜로우 카페! 딸기 진짜 엄청 많이 넣어줘서 놀랬어요 ㅎㅎ 당도도 좋은 딸기 쓰시는거 같아요! 재방문의사 완전 있어요! 딸기 빙수 드시고싶으시면 완전 추천합니다.', 10, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멜로우'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '저번에 수박빙수 시즌에도 와서 먹었었는데 여긴 과일이 엄청 싱싱하고 맛있네요ㅠㅠ 케익도 처음 먹어봤는데 치즈맛 너무 찐하고 다른 케익 가게랑 비교가 안되요ㅠㅠ ❤️❤️', 32, 6, 'GOOD', SYSTIMESTAMP);
