INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멜로우'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '빙수 넘 맛있고 케이크도 진짜 괜찮라요! 가게 공간도 아늑하고 테이블 자리도 3-4인 이렇게 있어서 친구들이랑 모임하기 좋아요!', 33, 1, 'GOOD', SYSTIMESTAMP);
