INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멜로우'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '저녁시간쯤에 합정역 주변에 있는 멜로우 카페에 다녀왔는데,이 시간에도 손님들이 많았어요!! 그리고 망고빙수🥭와 수박주스🍉를 시켜서 먹어봤습니당~!! 생망고가 들어간 망고빙수는 달달하고 고급스러운 맛이였고,아이스크림위에 귀여운 곰돌이 쿠키가 서있는거 너무 귀여워요 ㅠㅠ 수박주스도 시원하고 달달구리 했고 너무 맛있어용~~👍🏻👍🏻', 27, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멜로우'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '원래 가려던 카페에는 빙수가 없어서 갑자기 들어왔는데 빙수도 너무 알차고 맛있었습니다! 생망고 인 것 깉고 빙수 얼음이랑 부드럽게 너무 잘 어울렸어요🥭', 414, 99, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멜로우'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '저녁 먹고 남자친구랑 방문했어요! 생각보다 안쪽이 넓어서 3인석에 앉았는데 아늑하고 좋았습니다. 망고가 생망고라고 해서 일부러 찾아왔는데 비쥬얼도 좋고 가성비도 괜찮은 것 같아요! 망고맛이 진하고 잘 익어서 부드러웠어요 약간 자랑이신지 망고를 쭉 늘어놓으셨더라고요 ㅋㅋㅋㅋ 장식인 줄 알았는데 생망고라서 놀랐어요 연예인도 많이 왔다 가신 것 같더라고요', 74, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멜로우'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '요즘 날씨가 너무 더워서 빙수 맛집 찾아보다가 샤인머스켓 빙수가 있길래 들어왔어요!!😚 친구랑 같이 왔는데 카페 분위기가 넘 좋았구 빙수 나오자마자 짱 귀여워서 사진 겁나 찍었다는 ㅋㅋ!! 샤인머스켓 빙수 궁금했는데 양도 많고 기대한 만큼 맛있었어요:) 숨은 빙수맛집 발견한 기분..!!', 5, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멜로우'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '이번여름 망고빙수를 꼭한번 먹고싶었는데 넘 비싸서 벼르다가 먹어봤어요 망고빙수 첫경험이라 객관적인 평가는 모르겠고 냉동망고가 아닌 생망고를 썰어 그대로 올려주셔서 맛있게 먹었습니다~  근데 왠지모를 snl에 나온 인스타카페느낌이.. 나가주세요🙏 는 농담이고 진짜 인스타 느낌 카페에요 😂 골목 안쪽에 위치한 아담한 카페입니다. 계속 한팀 이상씩은 웨이팅을 하고 있어요', 11, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멜로우'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '딸기빙수가 재료소진이여서 다른 수박빙수를 먹었어요! 요새 날씨가 더워서 땀이 쑥 들어가는 느낌이 날 정도로 당도도 높고 시원해서 맛있게 먹었습니당ㅎㅎ 완전 빙수맛집이에여!! 딸기빙수 들어가면 또 망고빙수도 하신다고해서 메뉴도 올려봣어여~', 22, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멜로우'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '너무 더워서 찾아간 멜로우 카페! 수박빙수 먹고 더위를 날렸어요 ㅎㅎ 매장도 쾌적하고 빙수 맛집이에요!! 얼음도 수박얼음으로 되어있어서 끝까지 맛있었어요 ㅎㅎ', 9, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멜로우'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '직원분들 서비스 개선이 필요할 것 같아요. 남자직원분 빙수 서빙하시다가 아이스크림이랑 과일이 트레이로 떨어지고 고객 옷에도 묻었으면 사과하고 새로 해드리겠다고 멘트하시는게 맞지 않을까요? 사과한마디없이 물컵을 피하려다가 그랬다고 혼잣말로만 해명하시는건 이해가 안되네요. 실수하실수 있죠, 그런데 저희랑 부딪혀서 떨어트린것도 아니고 직원분 스스로 서빙하다가 떨어트리신거니 당연히 새로 해주실줄 알고 저희는 트레이에 떨어진 토핑을 정리하고 있었는데 그 모습을 보고 그냥 먹는줄 알았는지 티슈만 가져다주셨죠? 다른 여자직원분한테 상황 알리는 모습도 다 보고 들었는데 여자직원분조차 그냥 슥 보시더니 아무런 조치도 안 취하신 것도 봤습니다. 괜찮아보인다고 마음대로 판단하시고 고객봐가면서 응대하시는건 아닌것같아요.', 114, 25, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멜로우'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '망고빙수🍋🍧 맛있다는 소문을 듣고 왔는데, 역시 양도 많고 기대한것만큼 너무 맛있었어요^^(위에 올려진 귀여운 곰돌이 쿠키도 포인트~♡)  그리고 🍨아이스크림과 치즈가 올려진 크로폴, 초코케익도 아아🧋랑 너무 잘 어울려서 즐거운 시간 보내고 왔어요.', 103, 22, 'GOOD', SYSTIMESTAMP);
