INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멜로우'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '음료와 커피맛이 좋아요. 인테리어도 좋구 분위기가 멋져요. 대로변하고 좀 떨어져 있어서 사람들이 없어 조용히 지인들하고 이야기 나누기 좋아요.', 42, 8, 'GOOD', SYSTIMESTAMP);
