INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '하이타운서울'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '프로미스나인 박지원 생일카페에 다녀왔습니다. 매장은 좁은 편이었지만 다른 생일카페들과 다르게 특별한 음료 메뉴가 있어서 좋았습니다. #프로미스나인 #fromis_9 #fromis9 #박지원', 44, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '하이타운서울'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '여기 관리자님 친절 그 잡채👍🏽👍🏽👍🏽👍🏽👍🏽 생카 아니더라도 관리자님 친절함 덕에 나중에 일반카페로라도 꼭 가고픈 곳이에요👍🏽', 17, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '하이타운서울'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '운아기 생일 기념으로 다녀왔어요 >< 카페 너무 예쁘고 음료도 맛있었어요☺️ 날씨가 많이 춥지 않아서 다행이었던...😆😆주최자님도 카페사장님도 다 너무 친절하셨고 카페 분위기 최공👍👍 운학아 생일 축하했어🩷🩷🩷', 42, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '하이타운서울'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '운학이 생일이어서 왔는데 운학이랑 너무 잘 어울리는 공간이었어요 사람이 너무 많아서 조금 힘들긴 했는데 기다린만큼 보람이 있는 공간이었어요 😀 청포도 아이스티도 맛있었습니다', 27, 2, 'GOOD', SYSTIMESTAMP);
