INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '하이타운서울'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '테이블이 많지 않아서 🥺 내부에서 시간 보내기가 어려워서 넘 아쉬웠어요 그치만 외부까지 너무너무 예쁘게 꾸며져 있어서 사진도 많이 찍고 가장 좋았던 카페입니다 (*´-`)', 85, 15, 'GOOD', SYSTIMESTAMP);
