INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '하이타운서울'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '숨은그림 찾는 듯한 장소지만 그래서 더 특별했습니다. 이벤트로 찾은 곳이지만 칵테일 맛이 맛있어서 넘 맘에 들었습니다. 또 가고 싶어요 😚', 5, 1, 'GOOD', SYSTIMESTAMP);
