INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '하이타운서울'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '매장이 많이 작긴 하지만 소품, 인테리어가 아기자기하고 너무 예뻐요 오늘 두번째로 방문했는데 직원분들 변함없이 친절하셔서 기분 좋았습니다! 그리고 커피랑 칵테일도 맛있어요 대관 이벤트 없어서 여유로울때 방문하시면 좋을 것 같아요~', 26, 0, 'GOOD', SYSTIMESTAMP);
