INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '하이타운서울'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '호비 좋아해서 홉월드 기념으로 갔는데 들어가자마자 주문 하라 그러고 무조건 1인 1 메뉴 특전도 호비 사진은 하나뿐이고 홉월드 글씨만 잔뜩 줘서 실망하고 옴 안보다 밖이 더 나음 가격이 저렴하지도 않고 이쁜 호비 사진도 많은데 아쉬워여', 34, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '하이타운서울'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '걷던 중에 키치한 분위기가 맘에 들어서 들어왔는데 커피 맛 무슨 일이에요 ㅠㅠㅠㅠㅠ 달달하고 고소해서 실패 없는 맛이에요 바닐라라떼나 토피넛 라떼 좋아하시는 분들께 강추합니다! 😘💕 화장실도 내부에 깔끔하게 되어 있고 테이블도 아기자기 귀여워용 💦💦홍대에서 사람 너무 많은 건 싫지만 맛있고 귀여운 카페 찾는 분들 바로 이 집입니다!!!! 그리고 이건 비밀인데 사장님이 멋있고 커피가 친절해요 💜💖❤️💕❤️', 23, 5, 'GOOD', SYSTIMESTAMP);
