INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바나프레소 합정역점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '전자레인지에 넣는 척 하더니 그냥 줌 크림 실화냐… 그리고 제가 뭐 잘못했나요 표정 너무 불친절해요, 인상 쓰고 있는게 마스크를 뚫고 나오네요', 48, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바나프레소 합정역점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '나갈려고 테이크 아웃잔에 담아달라했더니 남자알바가 빨대 어쩌구 하길래 빨대 빼달라는줄알고 뺐는네 자기 말귀 못알아먹어서 화가났는지 정말 큰소리로 “빨.대.빼.서.넣.어.주.시.겠.어.요!?” 라면서 개짜증냄ㅠ 말 하나하나 짜증난다듯이 강조하면서 말함ㅋㅋㅠㅠ 주변에 있는 손님들 그 큰소리에 다 쳐다봐서 진짜 무안함.....나도 열받아서 컵홀더 드리냐고 물어볼때 화답으로다가 똑같이 짜증내면서 네!!ㅡㅡ라고 대답해줬어요ㅎㅎ 마스크 쓰고 웅얼거리는 본인이나 말똑바로하시던가요 지 말 못알아먹었다고 손님한테 짜증을 내다니ㅠㅠㅠㅠㅠㅠ말만 존대하고 말투에 분노에 차있음ㅠㅠㅠ진짜 싸가지 대단하세요~^^ 서비스업 하기싫으면 딴 데가서 알바하세요', 15, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바나프레소 합정역점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '직원들끼리 계속 떠들고 (직원들만떠듬)주문 밀려있는데 떠들면서 음료계속 밀립니다. 저도 카페일 안해본거아닌데 진짜 8/25일 오후 두시반에 이용했을때 계셨던 남성,여성직원분 매장안에서 둘만 떠들고계시네요 픽업존에 반납한 컵, 음식물 계속 그대로 두고 떠드시는데 그건아닙니다.', 18, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바나프레소 합정역점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '시그니쳐원두로 내린 아이스아메리카노 맛있어요! 2200원에 가격도 할인해줘서 더 좋아요! 해링턴건물에 주차하시면 1시간 무료입니다!', 31, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PARKING');
