INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바나프레소 합정역점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '매장 안에 들어가서 주문했더니 10분 정도를 기다려도 가게 안에서 메뉴를 만드는 사람도 없고, 제 앞에 이미 주문이 3~4개가 밀려 있는 상태에서 더 기다릴 수 없어서 주문만 하고 받지도 못하고 바로 이동하였습니다. 돈만 날렸네요. 최소한 화장실을 다녀오겠다 이런 문구 적힌 말이라도 있었으면 포기하고 다른 곳으로 이동했을 텐데 계속 하염없이 기다리는 게 화가 났습니다. 원래도 너무 좋아하던 매장이었기에 실망입니다.', 89, 14, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바나프레소 합정역점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '약속까지 시간이 남아 들렸는데 매장이 그리 넓지는 않치만 머물러 가기 좋았어요 다만 앉아있으면 번호판(?)이 안보여서 번호 부르는지 집중해야해요', 24, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바나프레소 합정역점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '주말 저녁타임 방문 너무너무 불쾌했네요. 테이블은 너무 끈적여서 직접 닦았고(한두타임 안닦은게 아님) 알바생이 화장실 물어보면 대답하는 것부터 주차 지원된다고 엄연히 적혀있는데 물어보니 “안돼요” ”무슨말하시는거에요“ 이러는데…대답하는 태도가 무슨 못물어볼거 물어본것처럼 인상쓰면서 대답하는데..너무 불쾌했습니다. 결국은 카운터 앞에 적혀있다고 하니, ”차 번호요“ 이러는데..참 너무 하네요. 주인분 보시면 알바 교육을 다시하거나, 채용 다시 한 번 고려해 보세요. 거의 근 몇년간 만난 알바생들중 최악으로 불친절하고 일하기 싫어하는게 눈에 보이네요.', 41, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바나프레소 합정역점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '직원분들이 정말 친절하십니다. 1.25일 토요일 오후 3시 20-30분경에 제가 음료를 크게 쏟아서 테이블 전체에 음료 쏟고 난리가 아녔는데요 바쁜 타임에 직원분들 귀찮으실법도 한데 귀찮거나 불쾌하신 기색 하나 없이 치워주시고 대응해주셔서 정말 감사했습니다. 점장님 혹시 보시면 당시 근무하던 직원분들께 포상이나 따뜻한 말 한마디 부탁드립니다...너무 민망했었는데 직원분들 손님 대응이 훌륭해서 그나마 살았습니다 바나프레소 최고...자주 이용하고 다음엔 안 쏟겠습니다...', 97, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바나프레소 합정역점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '핫치킨부리또 4400 아이스 제로슈가 복숭아아이스티 3500원 다른 프렌차이즈에 비해 음료가 양이 많아서 진짜 가성비 좋은 것 같아요d=(´▽｀)=b', 40, 7, 'GOOD', SYSTIMESTAMP);
