INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바나프레소 합정역점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '키오스크 주문할 때, 적립을 하게되면 주문번호 종이가 따로 안나와서 주문번호를 알 수 없네요. 그래서 다들 본인 음료인지 모르고 빨리 안찾아가는 것 같은데 직원분이 신경질적으로 번호 외치셔서 조금 당황스러웠어요. 시스템에 문제가 있어 보여요.', 38, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바나프레소 합정역점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '대로에 일요일 아침 8시 전에 오픈한 카페가 여기뿐인듯.  넘 반가웠다는.. 아이스아메리카노 좀 더 비싸게 받아도되는데 미안할 정도로 싸네요 잘 마셨어요', 101, 25, 'GOOD', SYSTIMESTAMP);
