INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바나프레소 합정역점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '이건.. 가성비를 뛰어넘어서 좀 과하다 싶을 정도로 양을 너무 많이 줘서 부담이 됩니다.. ^^.. 체감상 아아 1L 받은 느낌', 44, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바나프레소 합정역점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '바나프레소에서 복숭아아이스티는 처음시켜먹었는데 복숭아가 밑에 깔려있어서 마실때 복숭아랑 같이 맛을 느낄수있습니다. 복숭아 좋아하시는 분들은 좋아하실거같아용', 39, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바나프레소 합정역점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '바나프레소 ~ 오늘의 음료 피스타치오라떼 할인중 이라 생크림 500원 추가해도  3300원!에 득템~ 과트로치즈빠니니는 양이 적어요 금방 사라지네요 ㅋ.ㅋ 그래도 맛있었어요', 7, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바나프레소 합정역점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '이제 안가려구요... 일중이라 못달려갔는데 진짜 레시피대로 안만들고 뭔가 빼먹으신거같아요 먼저시켰는데 늦게 받아서 정말 짜증났는데 뭔가 빠졋는지 단맛은 아예안나고 그냥 엄청써요 ㅡㅡ 살다살다 쑥보다 쓴건 처음봐요 그냥 어이가없네요 환불받을까하다가 그냥 리뷰쓰고 안가려구요', 25, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '워낙 아이스크림을 좋아해서 이번에 예약하고 이용해봤어요!(예약은 필수입니다!!) 색다른 경험이라 즐거웠는데 맛도 있었어요!! 처음엔 어려울 수 있지만 금방 요령이 생겨 수월할거에요 ㅎㅎ 재밌었어요 재방문 의사 있습니다!!', 44, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '이색 데이트로 넘 좋아요!! 색다른체험이라 넘 재밌고 아이스크림 맛은 기대 안했는데 완전 맛도리였어요! 재료들이 다 깔끔하고 구성이 알찼어요 가성비 괜찮은거같아요!! 레트로풍 분위기 넘 귀엽고 깔끔해서 좋았어요 다음에 또 오고싶어요🤗', 9, 10, 'GOOD', SYSTIMESTAMP);
