INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '철판 아이스크림 누가 더 잘 만드나 내기했는데 졌답니다 암튼 설명도 친절하게 잘 해주시고 어렵지 않아요 재료들도 엄청 많아서 조합 생각하는 재미가 쏠쏠희~ 다들 많이 오세요~ 아니예요 사람 많으면 제가 담에 또 못 오니까 오지 마세요~ 아닝에료 그래듀 오세요', 82, 14, NULL, SYSTIMESTAMP);
