INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '어렸을 때 영상으로만 봐와가지고 정말 하고 싶었는데 기회가 없어 하지 못한 아쉬움을 여기서 다 풀고 가네요 !! 너무너무 재미있고 아이스크림도 그만큼 맛있어요 ㅎㅎ 과자 종류도 많이 주시고 데이트 하기 너무 좋아요 👍👍', 27, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '홍대데이트코스로 추천하는 철판아이스크림 만들기 ! Sns에서 보고 궁금해서 예약 후 방문했는데 생각보다 더 재밌고 알찬 시간이었어요 !! 시간 꽉 채워서 아이스크림도 만들어보고 여러 토핑도 주셔서 꾸미는 재미도 있었어요 데이트코스로 추천합니당 !', 6, 3, 'GOOD', SYSTIMESTAMP);
