INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '처음 만들어본 철판 아이스크림, 재밌고 맛있어요! 철판 아이스크림 키트를 처음 사용해봤는데, 생각보다 만드는 과정이 너무 재미있었어요! 오레오랑 생딸기, 우유 아이스크림 베이스로 조합했는데, 비주얼도 예쁘고 맛도 기대 이상이었어요🍓🍪 처음이라 그런지 철판이 충분히 차갑지 않아서 아이스크림이 살짝 퍼지긴 했지만, 그래도 긁어가면서 만드는 재미가 쏠쏠했어요. 특히 아이들 있는 집이나 친구들이랑 같이 하면 정말 좋은 홈카페 아이템인 것 같아요.', 62, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '철판아이스크림 만들고 싶어서 예약했는데 생각보다 어려웠지만 직접 만들수 있어서 재밌었고 기본토핑도 많이 주셔서 여러가지 만들수 있어서 좋구 맛있었어요👍🏻 이색데이트로 추천합니다☺️', 1, 9, 'GOOD', SYSTIMESTAMP);
