INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '남친이랑 이색 데이트로 왔는데 넘 재밌어요 ㅋㅎㅋㅎ 생각보다 아이스크림이 빨리 굳으니까 빠르게 하는 게 좋은거가타요 애인이나 친구랑 오면 좋은 추억 만들 수 잇습니다🥰', 17, 10, 'GOOD', SYSTIMESTAMP);
