INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '철판아이스크림 만들어 본 건 처음인데 어렵네요🤣 그래도 특별한 경험하고 갑니당 맛은 기복 우유맛과 2가지 선택 가능한데 딸기, 요거트 선택해서 상큼달달하니 좋았어요 토핑도 다양하고 꾸미는 재미도 있네요👍', 19, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '철판아이스크림 만들기 생각보다 어려워서 예쁘게 만들지는 못했지만 너무 맛있었어용! 재료도 다양하고 토핑도 많아서 뭘 넣을지 고민하게 돼용 ㅋㅋㅋㅋ 저희는 초코 베이스에 딸기를 넣어서 먹었는데 넘 맛있었어용 매장도 깔끔하고 좋아용🥰🥰❤️❤️', 87, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '홍대에 철판아이스크림 카페가 있다해서 날도 덥고 하니 만들어보자! 해서 왔는데 넘 재밌고 신기해요!!! 토핑도 다양하구 공간도 레트로 할머니댁 컨셉…?이라 정감있어요☺️✨', 13, 0, 'GOOD', SYSTIMESTAMP);
