INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '아이스크림은 3번 만들 수 있고 좌식이라 약간 불편하긴 한데 토핑이 엄청 다양하고 혈당 지대로 올릴 수 있어요 이색 데이트 장소로 짱짱! 많이 달달해서 말차나 요거트 추천해요!🫶🫶🥵', 34, 5, 'GOOD', SYSTIMESTAMP);
