INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '여름이 가기 전에 꼭 철판아이스크림 만들기 해보고 싶었는데 직접 해보니까 너무 재밌었어요!! ㅎㅎ 아이스크림 배터지게 먹구 갑니다 .. 🤤👍🏻🩷', 61, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '기본 구성은 요런식으로 ..! 남자친구랑 이색 데이트 느낌으로 방문해봤는데 생각보다 넘 어려워서 당황쓰 ㅋ 돌돌돌 말리는 걸 예상했지만 현실은 손으로 말고 있음 ㅋㅋ 가격은 좀 비싼 것 같지만 체험하는 과정이 재밌어요 한 번쯤 해볼만 함 추천드려요', 47, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '너무너무 재밌고 맛있어요!!! 인스타에서 핫한 이색데이트집도 가봤는데... 돈아까운적 많았거든요 ㅠㅠ..여기는 최고입니다.. 겨울엔 타코야끼 한다고 하니까! 여름겨울로 방문하기!!', 92, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '직접 만들어볼 수 있는게 너무 재밌어요 ㅋㅋㅋ 만들기 은근 힘든데 하면 할수록 잘 만들어지더라구요 맛도 있고 좋은 경험이였어요 이색적인 데이트인정! 1호점 예약잡기 힘들어서 포기했는데 2호점 생겨서 바로 예약 했습니다!!!', 27, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '여름방학이라 아이랑 철판아이스크림 만들기 체험해보고 싶어서 예약했어요. 처음엔 조금 어려웠는데 세번이나 만들 기회가 있어서 계속 시도하다보니 잘 말려지더라구요. 토핑도 다양하게 많이 주셔서 먹다보니 배불렀어요 ~', 63, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '재밌었습니다! 철판아이스크림 처음 만들어보는데 되게 이색적인 체험이었어요✨ 시간도 넉넉해서 편하게 만들었습니다 잘 놀다가여~!', 73, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '맛은 3가지이고 2가지는 고를수있어요! 매뉴얼을 주시는데 되게 간단하고 이해하기 좋습니다! 아이스크림 첨 만들어보는데 넘 재미있고 무엇보다 맛있어요♡♡ 담에 또 올래요~', 37, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '홍대는 정말 놀거리 먹거리 가득이지만 직접 만든 아이스크림 가게에 들려보세요 기대 이상으로 재밌고 맛있어요 만들고 먹고 하려면 이용시간 70분이 빠르게 갑니다 토핑도 넉넉하고 레트로한 감성의 인테리어도 마음편하게 해주세요 추천해요', 1, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '처음 해봤는데 설명도 잘해주시고 영상도 있어서 보고 만드니까 쉽게 할수있었어요 만드는 재미도있고 맛난 아이스크림도 먹고 즐거운 경험이였어요', 12, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '남자친구랑 데이트로 도란도란 2호점에 철판 아이스크림 만들러 방문했어요!! 바로 입장했고 매뉴 주문 후 사장님이 친절하게 설명해주세요!! 둘이 이야기 하면서 재미있게 만들기 너무 좋고 밖에서 할 수 없는 경험이다보니 너무 재미있어요!! 별로 어렵지도 않고 이쁘게 펴서 말리는 것이 쾌감있구 너무 재미있어요! 토핑도 다양하게 한가득 주시고 베이스도 3개나 있어서 넉넉하게 만들고 먹고 갑니다! 다음에 또 오고 싶어요!!🧡🧡', 12, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '색다른 체험을 할 수 있는 곳이어서 좋았구 직접 철판 아이스크림을 해먹을 수 있는 곳이어서 좋았습니다! 본인 하기 나름대로 여러가지 다양한 맛을 먹을 수 있다는 것도 장점이에요! 재밌습니다!', 25, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '너모 재밌어요~! 유튜브에서만 보는데 직접 만들어먹는건 처음이에요. 철판아이스크림 신기하고 해보니 재밌어요. 이색데이트로 추천해요!', 29, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '여기는 선예약을 해야하고, 제한시간은 1시간 10분 정도? 되는데 생각보다 짧았던 거 같아욤 그래도 맛 두 가지 골랐는데 세 종류를 만들 수 있어서 좋았어욤 또 토핑도 다양하게 주셔서 겨울에는 타코야끼 할 예정입니다🤎🤎', 17, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '철판 위에서 아이스크림을 직접 만들어 먹는 경험이 생각보다 훨씬 재밌었다. 재료를 고르고 섞고, 눈앞에서 바로 얼려지는 과정을 보니 신기하고 뭔가 장난감 가지고 노는 기분이었다. 달콤한 맛에 보는 재미까지 더해져 시간 가는 줄 모르고 즐겼다.', 15, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '이색데이트 하고 싶을 때 추천합니다-!! 재미있게 꾸나랑 놀다왔서요ㅋㅋㅋㅋ 저희는 1000일이 넘어서 안 가본 곳이 없는데 색다른 데이트였습니다! 철판아이스크림 사장님이 되고싶다면 한 번쯤 예약하고 방문해보세용~!', 303, 82, 'GOOD', SYSTIMESTAMP);
