INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '홍대 도란도란 2호점에서 철판 아이스크림 만들기 체험을 하고 왔어요! 직접 재료를 올려서 철판 위에서 아이스크림을 만들어보는 과정이 신기하고 재밌었어요. 평소에 먹기만 했던 아이스크림을 제가 직접 만들 수 있어서 색다른 경험이었고, 완성된 아이스크림도 맛있고 달달했습니다 🍨✨ 친구들이랑 같이 하면 더 즐겁고, 아이들이랑 와도 좋아할 것 같아요. 홍대에서 특별한 체험을 원하신다면 추천합니다!', 21, 0, 'GOOD', SYSTIMESTAMP);
