INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '요즘 유투브에서 핫한 철판아이스크림 직접 만들어보려고 왔어요ㅎㅎ2호점까지 생겨서 겨우 주말에 예약했는데 어린이가 좋아하는걸보니 저도 즐겁네요 :)', 32, 9, 'GOOD', SYSTIMESTAMP);
