INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '남자친구랑 같이 왔는데 너무 재미있었어요!ㅋㅋㄱㅋㅋ 둘 다 손재주가 없어서 쫌 망했는데ㅠㅋㅋㅋ 엄청 웃으면서 좋은 시간 보냈어요! 양도 많아서 엄청 배불러요ㅎㅎ 감사합니당!!🥰🥰', 60, 15, 'GOOD', SYSTIMESTAMP);
