INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '내맘대로 만드는 철판아이스크림 이색데이트였어요. 이색데이트라 재밌기도 하고 시원해서 좋아요. 맛은 … 조합에따라 너무나 다를 수 있다는점!!!', 35, 5, NULL, SYSTIMESTAMP);
