INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '철판 아이스크림 만드는건 너무 재밌는데 먹느라 조금 힘들었어요ㅋㅋㅋㅋㅋㅋㅋㅋㅋ 우유를 기본으로 주시기 때문에 고르는 맛 중 한개는 요거트로 상큼함을 챙기시는거 추천드려요 다 달콤한 맛으로 했더니 조금 느끼해서 집 가서 불닭 깠어요', 2, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '와보고 싶었던 ㅜㅜ곳이였는데  너무너무 행복하네여! 너무 맛있고 행복해용..! 진짜 또 예약잡고 올수있으면 올라구요ㅠㅠ! 빈자리 예약으로 왔는데 너무너무 행복해요! >.< 잘먹고 데이트행복하게 하구갑니다!', 24, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '철판아이스크림 만들어보고 싶어서 방문했는데 생각보다 더 특별한 경험이었습니다🤩 만드는 것도 재밌고, 맛도 있어서 추천드립니다!', 47, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '아이가 철판아이스크림을 좋아해서 방문했습니다 멀리서 온 보람이 있어요 집에서 하는 철판과는 차원이 다릅니다ㅎㅎ 세 판 만들 수 있는데 첫 판은 실패했지만 두번째 판부터는 스킬을 익혀서 잘하더라고요 가격도 착해서 다음에 또 오려고요', 96, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '철판아이스크림을 직접 만들어볼 수 있다니 너무 이색적이고 토핑도 많아서 정말 재밌게 만들 수 있었습니다!! 무엇보다 너무 맛있어요 !! 다음에 또 방문할게요🖤', 14, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '일단 음식 부수면서 만드는게 너어무 스트레스 풀리고 재밌어요ㅠㅠ!!!! 맛은 솔직히 기대 안했는데 너어무 맛있고 중간중간 씹히는 과자가 킥입니다! 너무 잘게 부수지말고 건더기 좀 남겨서 얼리시면 더 맛있을거에요!!!💓💓💓', 89, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '아이랑 방문했어요~세번정도 만들 수 있는데 모양만들기는 쉽지않치만 ~ 토핑을 넣고싶은만큼 넣어 만들어먹는 재미가 있었고 ,일단 토핑종류가 많았어요 베이스는 다양했지만 우린 딸기맛 요거트,우유맛로 했는데 넘나 맛있었어요~~다음에 방문할땐 좀더 예쁜모양 도전~~😍', 3, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '겨울엔 타코야끼만들었었는데 여름에 철판아이스크림으로 한다해서 왔는데 완전 만족했어요 :) 어렸을때 마냥 해보고싶었던 철판아이스크림이였는데 오늘 처음해보니까 시간도 잘가고 정말 재밌었어요 남자친구랑 왔는데 남자친구도 좋아하고 같이 떠들면서 먹었어용 타코야끼 재오픈 하기전에 한번 더 올게용', 15, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '똥손 두명이 고분분투 하면서 만들었습니다ㅋㅋㅋ마지막에 감을잡은...다른분들은 망했다고 먹지 마시도 다시 녹여서 시도해보십셔ㅋㅋㅋ🥹재밋었어요', 50, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '처음에는 서툴러서 대패삼겹 아이스크림 만들다가 마지막에 성공했어요!! 해내는 기분이 너무 좋네요😊 사장님이랑 직원분 친절하시고 토핑도 다양해서 즐겁게 잘 놀다갑니다!', 94, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '남자친구랑 특별한 데이트를 하고 싶어서 찾아보다가 우연히 알게 되었어요! 직접 만들 수 있어서 너무 재밌었어용 그리고 맛있네요 추천합니당', 1, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '요즘 같이 더운 날 남자친구랑 이색 데이트 하고싶은데 어디 가야할지 모르겠다 싶을 때 오면 무조건 성공하는 데이트 장소인 것 같아요🙂💛 철판 아이스크림 안에 넣을 수 있는 토핑 과자 종류도 다양해서 여러가지 맛의 아이스크림을 만들어 먹을 수 있어 만족스러웠어요!!! 남자친구가 이런 활동적인 데이트를 좋아하는데 너무 재밌고 기억에 남을 데이트 라고 하네요 ㅎㅎ 다들 홍대에서 남자친구랑 이색 데이트 하고싶다 하시면 도란도란 철판 아이스크림 꼭 방문하세요!!! 매우 강추!!', 19, 0, 'GOOD', SYSTIMESTAMP);
