INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '이색데이트인것가타요 아이스크림 마는게 조금 어려웠지만 한번 할 때마다 실력이 늘어용ㅋㅋ 겨울에는 타코야끼 만들으러 올게요✌️🤍', 49, 9, NULL, SYSTIMESTAMP);
