INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '철판 아이스크림을 직접 만들어볼 수 있다는게 너무 신박하소 재밌었어요!! 넣을 수 있는 요소도 많고 간식 겸 먹을 수 있는 과자들도 있어서 넘 좋았어요 ㅎㅎ 친구랑 같이 갔는데, 데이트로 오는 것도 정말 좋을것 같아요!!', 37, 5, 'GOOD', SYSTIMESTAMP);
