INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '아이가 엄청 재밌어 해요~ 직접 만든 아이스크림이라 더 맛잇다고도 하구요 ㅎㅎ 다음에도 또 방문할게요~ 친절한 설명도 감사합니다!!', 79, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '홍대에 철판 아이스크림을 직접 만들어 먹을 수 있는 곳이 있다고 해서 왔습니다! 아이스크림 만들기가 어려우면 어떡하나 걱정했는데, 전혀 그렇지 않았고 오히려 가게 이름처럼 도란도란 얘기 나누며 철판 아이스크림을 만드니까 시간이 너무 금방 가서 아쉬울 정도였습니다 ㅠ 베이스도 다양하고 토핑도 여러가지라 나만의 아이스크림을 만드는 재미도 쏠쏠했습니다 ㅎㅎ 무엇보다 더운 여름에 실내에서 시원한 아이스크림 만들어 먹을 수 있어서 좋았습니다 👍🏻', 36, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '인스타 보고 네이버로 예약하고 방문했어요~ 시원한 아이스크림을 마음껏 먹을 수 있고 재료도 충분히 주셔서 마음껏 만들어볼 수 있고 옆에 설명과 영상도 있어 만들기도 좋았어요~', 50, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '이색 데이트로 좋았어요!! 생각보다 어렵네요ㅠ 그래도 기회 3번 있어서 배부를 때까지 만들어 먹었어요ㅋㅋㅋㅋ 즐거운 시간 보냈습니다🫶', 17, 2, 'GOOD', SYSTIMESTAMP);
