INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '철판아이스크림 장인이 되다! 남자친구랑 방문했습니다 토핑도 엄청 다양하고 아이스크림 양도 생각보다 넘넘 많아서 맛있고 즐겁게 시간 잘 보내다 가요!', 64, 11, 'GOOD', SYSTIMESTAMP);
