INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '베이스와 과일도 직접 고를 수 있었고 나머지 토핑들도 다양해서 좋았어요 철판 아이스크림을 직접 만들어보고 먹을 수도 있어서 재밌고 좋았어요!', 16, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '인테리어도 정말 독특하고 서비스도 정말 좋았어요. 토핑도 많고 종류도 다양해서 만들 수 있는 아이스크림이 많아서 즐거웠네요. 다음에도 또 방문하고 싶어요~^^', 17, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '야외에서 파는거 볼 때 마다 항상 만들어 보고 싶었는데 재료도 다양하고 엄청 재밌었습니다! 겨울에 타코야키도 만들어보러 오고 싶네요', 70, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '홍대에 놀러온 김에 친구랑 재밌는 추억 쌓았습니다! 둘다 철판아이스크림은 처음이었는데, 사장님이 친절히 알려주시고 설명서도 쉽게 써있어서 쉽게 만들었어요ㅎㅎ 토핑도 다양해서 다양한 맛으로 즐길 수 있었어요! 인테리어도 할머니댁이 생각나서 덕분에 즐거웠습니다😆 번창하세요!', 8, 6, 'GOOD', SYSTIMESTAMP);
