INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '이색데이트로 너무 좋은 곳 같아요!!💕 철판아이스크림 만들 수 있는 데가 없는데, 여름에 딱 맞게 아이스크림 만들고 맛있게 먹을 수 있어서 좋았어요 ㅣㅎㅎ 또 직원분들이 넘 친절하게 안내 잘 해주셨습니다! 색다른 데이트 하고 싶은 분들 추천해요😊🥰', 41, 1, 'GOOD', SYSTIMESTAMP);
