INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '33..살먹고.. 홍대란곳에 나와봤네요.. 배우자와 함..께.. 좋언 시간 보냈읍니다. 아이스께끼를 만드는 거라는데 손이 떨려 쉽지 않네요.. 그래도 즐거웠읍니다..✨️', 33, 1, NULL, SYSTIMESTAMP);
