INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '철판 아이스크림을 만들어 먹을 수 있다고 해서 재밌어 보여 방문했는데 너무 좋았네요! 재료가 좋아서 그런지 제가 만들었는데도 너무 맛있었네요! 데이트 코스로 강추합니다!', 1, 1, 'GOOD', SYSTIMESTAMP);
