INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '영상으로만 보다가 실제로 해보니 재밌어요! 친구랑 둘이 추억만들기좋아요 ㅎㅎ 생각보다 양도 많고 토핑 종류도 많았어요! 다음에 또 올게요 ~', 90, 15, 'GOOD', SYSTIMESTAMP);
