INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '아이가 많이 즐거워 하였습니다. 활동하기에 장소도 편안하고, 활동방법에 대한 안내도 친절했습니다. 무엇보다 재료가 다양해 즐거운 체험할 수 있었어요. 이색테이트장소로도 추천해요~', 33, 0, 'GOOD', SYSTIMESTAMP);
