INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도란도란 2호점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '요즘 핫한 철판 아이스크림 체험하러 왔는데 너무 친절하게 안내해주셔서 맛있게 잘 먹고 갔습니다~ 홍대 한복판에 있어서 접근성도 좋네용', 45, 5, 'GOOD', SYSTIMESTAMP);
