INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '꿀토마토주스: 진심 진짜 너무너므 맛있었던 주스. 홍대 나들이는 이걸 먹음으로써 다 이뤘다고 생각했을 정도로 토마토의 맛있는 맛과 적당한 달기가 정말 좋았던 음료! 블루베리치즈조각케이크: 케이크 자체는 생각보다 달지 않아서 좋으나 치즈의 쿰큼힌 향이 있어 개인적으로 별로.. 레몬 스퀘어 케이크: 대형마트에서 파는 냉동 케이크 맛 맛이 없지는 않았음. 아이스 시나몬블랑: 크림과 시나몬향이 좋았고 맛있었음 플레인스콘: 지금까지 서울에서 먹었던 스콘 중 가장 맛있었던 플레인스콘! 따뜻하게 데워줘서 더 맛있었던 거 같음.', 59, 11, 'GOOD', SYSTIMESTAMP);
