INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '여기 너무 좋아요~~! 동네라 종종 가는데 빵도 엄청 다양하고 맛있고 커피도 맛있고 직원분들도 친절하세요 ㅎㅎㅎ 연희동에서 카페 찾으시면 강추합니다 ☺️🍀 공부하러 가기도 좋고 친구랑 가기도 좋아요!!', 23, 9, 'GOOD', SYSTIMESTAMP);
