INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '도심안에 있는 주택을 개조한 카페에요. 1층~2층으로 되어 있어요. 주문하면 자리까지 직접 가져다 주십니다. 좌석은 많은 편이나 창가자리는 일찍 가거나 운이 좋으면 앉을 수 있어요. 제가 갔을 땐 그 외의 자리는 넉넉한 편이었어요. 커피는 맛있는 편이었습니다.', 17, 7, 'GOOD', SYSTIMESTAMP);
