INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '홍대 경의선 숲길 산책하다 맛있는 커피집 찾기가 너무 힘들었는데 연희동에서 보던 간판보고 들어간곳인데 역시 커피맛집이다. 아이스라떼맛있고 2층이있는줄 모르고 불편한 1층자리를 전전하다 갈때 여자화장실 찾다 2층이 있음을 알게됐다는~^^ 연희동가면 분위기있는 본점두 방문추천^^', 5, 1, 'GOOD', SYSTIMESTAMP);
