INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '비내리는 날, 친구랑 쇼핑 후 들어오게 된 카페! 사람들이 많았어도 앉은자리 겨우 있어 커피 얼른 주문하고 수다 와다다 떨고 ㅎ 동교 원두는 진하고 고소하고, 친구가 시킨 바닐라라떼도 고소 달콤했어요~~', 49, 1, 'GOOD', SYSTIMESTAMP);
