INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '운동끝나고 언니동생이랑 커피한잔🫶 쓴커피를 잘 못마시는데 색깔은 엄청 진해보였는데 너무 부드럽고 맛있었어요👍 여기서 커피 드셔본분이 집에가서도 커피맛이 기억나서 한잔더 마시고 싶으셨대용 자주올께요!! 감자 고로캐 따듯하게 데워주시고 커팅도 해주시고 센스 짱짱입니당💕', 41, 5, 'GOOD', SYSTIMESTAMP);
