INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '로덴드론 연희 3호점 카페입니다. 연희동에 주차 공간 있는 카페 찾기 힘든데, 여기는 가능합니다. 다만 동네 특성상 도로가 비좁으니 도보 이용을 권장합니다.', 77, 15, NULL, SYSTIMESTAMP);
