INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '지하철타기전에 들르기좋은, 뭔가 내겐 정말 편안한 느낌이 드는 그런 카페예요^^ 친구도 편안하게 생각하는~ 그런 카페♡ 1.2층으로 되어있어서 2층에서 여유롭게 작업하기도 좋고, 이야기나누기도 좋은 그런 카페에서 좋은시간 보내다왔어요^^', 81, 14, 'GOOD', SYSTIMESTAMP);
