INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '단팥빵은 견과류 씹히면서 안에 팥이👍🏻 까눌레는 겉바속쫀이 아니고 겉쫀속쫀이라 좀 아쉬웠지만 맛있었어요🥤 디저트 종류도 다양하고 매장 넓어요 다음 방문때는 케이크 먹어보려구요🧁🍰 사장님 서비스 감사합니다🍀🌷', 40, 0, NULL, SYSTIMESTAMP);
