INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '치즈바스크랑 아메리가노 맛있게 먹었어요. 옆에 빵공장에는 조각이 없어서 다른 빵사고 카베와서 보자마자 조각 케이크 보여서 커피랑 같이 먹었어요~', 37, 10, 'GOOD', SYSTIMESTAMP);
