INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '길 가다가 그냥 들어온 카페인데 기대 이상으로 너무 맛있어요!! 특히 까눌레 맛있게 하는 집 희귀한데 여기는 맛있어서 놀랐습니다ㅠㅠㅠ 그리고 겨울시즌이라 딸기 케이크 있어서 좋네요~ 커피도 고소하니 좋아요! 잘 먹고 갑니다.', 33, 10, 'GOOD', SYSTIMESTAMP);
