INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '시나몬 좋아해서 시나몬블랑 시켰는데 맛있었어요. 카페인 못 먹는데 모든음료 디카페인으로 바꿀 수 있어서 좋았습니가. 무화과철에 무화과 케이크는 정말 꿀맛이었구요~~가방 놓으라고 의자 하나 더 놔주는 센스까지 아주 맘에 쏙 든 카페였어요~~^^', 126, 21, 'GOOD', SYSTIMESTAMP);
