INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '인테리어가 멋진 카페입니다. 주문은 1층에서 하고 음료 받아서 2층 올라가실 수 있어요! 아메리카노는 고소한 원두, 산미 있는 원두 두 가지 중에 고를 수 있어요', 30, 3, 'GOOD', SYSTIMESTAMP);
