INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '로덴드론 최애 음료는 크림말차❤️ 말차 좋아하는 사람은 꼭꼭 가서 드셔보세요!! 계절마다 새로운 메뉴도 많이 나오고 베이커리 종류도 많아서 갈때마다 뭐먹을지 고민되는 곳이에요 매장도 2층까지 있어 좋아요', 33, 8, 'GOOD', SYSTIMESTAMP);
