INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '친구 기다려야해서 근처 이쁜카페 보여서 방문했어요ㅎㅎ 매장이 넓고 좌석도 많고 보기좋게 빵이 진열되어있어요 직원분들도 굉장히 친절하세요:) 커피는 엘사바도르 핸드드립먹었는데 마일드 하고 단맛도 있어서 정말 맛있어요👍🏻👍🏻 소금빵은 커피에 어울린다고 맛보시라 주셨어요 굳굳!!', 18, 7, 'GOOD', SYSTIMESTAMP);
