INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '디저트 종류 빵 종류 다양하구 직원분들이 항상 친절하세요. 매장도 깨끗하고 밝아요! 아메리카노 원두 선택도 가능해서 넘 좋아요', 39, 8, 'GOOD', SYSTIMESTAMP);
