INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '레몬티 아메리카노 초코스콘 다 맛있었어요 초코스콘은 데워달라고 해서 아메리카노랑 먹으면 녹진한 초코랑 아메리카노의 조화가 최고에요 직원분들이 다 넘 침절하셔서 더 좋았구 재방문할거에용 참 1인1메뉴 주문시 2000원에 아메리카노 리필해먹을수 있으니 여러음료 드시고 싶으신분들 이용해보세요 ㅎㅎ', 124, 20, 'GOOD', SYSTIMESTAMP);
