INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '아침에 방문했더니 조용하고 집주할 수 있는 공간이였어서 좋았어요. 예쁘고 맛있어보이는 다양한 디저트가 있고 원두도 다양해서 드립커피 좋아하시는 분들도 좋을 듯 해요 😍😍', 111, 23, 'GOOD', SYSTIMESTAMP);
