INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '빵 사진 찍느라 음료 사진을 못찍었네요 복숭아케익, 체리치즈케익 안달고 맛있었어요 특히 직원분 너무너무 친절하셔서 정말 좋았습니다! 재방문의사 있어요', 14, 8, 'GOOD', SYSTIMESTAMP);
