INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '카페, 기분탓일수도 있지만 진짜 예전에 비해 친절 하지가 않음.(특히 말투) 진짜 예전에는 엄청엄청 친절해서 자주 갔는데 요즘은 사람도 많고 바빠서 그런지 그냥 그럼…그래도 물론 일부 직원들은 친절함. *디저트는 맛있음', 35, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '작년에 오픈했을 때 잘될까 했는데 지나갈 때마다 손님이 점점 많아져서 가봤는데 커피도 맛있고 굉장히 친절합니다~ 왜 잘되는지 알 것 같아요 근데 낮 시간에는 여기 손님도 많은데 직원 한분 계시던데요 혼자 메뉴 다 빼시던데 좀 안쓰러워보였어요! 바쁜데도 친절하시고.. 손님 많은데 직원 좀 더 뽑으세여~~', 2, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '여기 홍대 인근에서 보기 드물정도로 친절합니다. 맛은 맛 없는쪽과 맛있는 쪽으로 나누자면 맛있는 쪽입니다. 가격은 to go해가면 만족스러워서 매일 to go 해갑니다. 좋은 커피숍은 좀 오래 가면 좋겠네요.', 36, 5, 'GOOD', SYSTIMESTAMP);
