INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '서울 놀러갔다가 들렸는데 커피맛, 분위기좋고, 깔끔했습니다 커피 마시는데 직원들 응대와 친절함에 너무 기분 좋았네요 또 들릴께요^^', 101, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '원래 바닐라라떼를 좋아하는편이 아닌데 주변에서 바닐라라떼 맛집이라고 소문나서 속는셈치고가봤습니다. 다른 카페랑 달리 엄청 달지 않아서 남기지않고 잘마셨네요ㅎㅎ 친구가 마시던 아메리카노도 잠깐 맛봤는데 커피맛이 제취향이라 그걸로 마실걸 그랬어요 커피말고도 빵도 같이 팔던데 배가 불러서 빵은 다음에 올때 한번 먹어봐야겠네요. 자주 들릴것같습니다.', 68, 13, 'GOOD', SYSTIMESTAMP);
