INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '로덴드론 동교 2호점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '와~수제티라미수 넘 맛있어요!! 청포도주스도 신선하고 커피맛도 고소하면서 분위기도 좋네요~ 무엇보다 여기 직원분들 참 친절해요^^', 24, 3, 'GOOD', SYSTIMESTAMP);
