INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공룡빵공장'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '무화과깜빠뉴 빵속이 매우 부드럽고,고소하고 맛있네요 말린 무화과도 덕당히 들어있고.같이 있던 올리브유 찍어먹으니 더 고소고소ㅎ', 46, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공룡빵공장'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '안녕하세요. 사랑합니다 적힌 딸기하트 케이크인데요. 저녁5시50분경 구입한 케이크인데 선물받으신 분이 곰팡이가 있다고 사진을 보내주셨어요 8시이후라 퇴근하셔서 교환도 안되고.. 우선 내일 연락드릴건데, 미리 글 올려둡니다. 당일 생산 아니었나요.. 은사님 스승의날 선물인데 어떡할까싶네요. 너무 난감해졌어요. 아침에 연락드리겠습니다.', 52, 17, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공룡빵공장'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '🥨아몬드크림치즈 - 5,000원 샌드위치 사먹으려고 갔다가 아몬드크림치즈 사먹었어요! 왕크고 왕맛있어욤! 🌟빵사서 같이 운영하시는 카페에서 먹을수있다고 하셔서 앉아서 먹었어요! (걸어서 1분이내) ☕️카페 카페 분위기도 좋고 2층이 조용하니 좋아요! 잔잔한 재즈 틀어줌. 직원분도 넘넘 친절하십니다!! - 빵사서 카페가면 음료 1,500원 할인 (빵가게 사장님께서 음료 마실 예정인지 여쭤보심, 특정 음료만 되는건지는 모르겠음) - 카페에도 빵/케이크 있습니다! 카페 네이버 메뉴판에 음료만 있길래 빵 없는줄 알았음! 빵집이랑 카페랑 같이 하셔서 그런지 빠네스프 세트 등등 메뉴가 많음', 58, 12, 'GOOD', SYSTIMESTAMP);
