INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '동네 숨은 보석입니다. 아늑하게 작업하기 너무 좋았어요. 티아메리카노는 처음 먹어봤는데 다른 곳에서는 먹을 수 없는 아메리카노라 더욱 특별했고 호두과자도 너무 맛있었습니다☺️ 동네 주민분들께 사랑방 같은 인기있는 카페더라구요!!👍', 36, 9, 'GOOD', SYSTIMESTAMP);
