INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '티 아메리카노 맛집이에요 ◡̈ 호두과자도 따끈따끈하게 맛나게 먹었습니다 ㆅ 인테리어도 이쁘고 분위기도 좋아서 덕분에 다이어리 정리하며 여유로운 시간 보냈네요 담에 재방문 예정입니다 !', 42, 9, 'GOOD', SYSTIMESTAMP);
