INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '다들 호두과자 테이블에 하나씩 올려져있길래 저도 시켜봤는데 개맛있네요 ㅎ 왜 다들 시켰는지 알겠습니다 티 아메리카노도 맛있어요. 아메리카노에 달달한 향 나니 넘 맛있었어요.', 30, 5, 'GOOD', SYSTIMESTAMP);
