INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '직지만 실내가 심플하고 깨끗합니다. 수박주스는 냉동이 아닌 생과일을 써서 과즙이 살아 있는 느낌 좋았구요 뜨끈하게 갓 구워 나온 호두 과자는 정말 넘사벽이었습니다. 바삭바삭하고 호두도 듬뿍..최고...', 61, 12, 'GOOD', SYSTIMESTAMP);
