INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '너무 편안하고 느낌 좋은 카페입니당 커피 메뉴에 티백을 넣어주는 티커피와 라떼가 있었는데 이색적이고 좋더라구요 ㅎㅎ 호두과자도 주문했는데 바로 만들어주셔서 따뜻하구 맛있엇어용…! 스피커도 좋은거 두셔서 음악 듣기가 너무 좋았습니당', 76, 16, 'GOOD', SYSTIMESTAMP);
