INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '홍대입구 사람 많아서 싫은데 여기는 조용한 골목에 있어서 조용하게 대화하기 좋은 작은 카페입니당 호두과자 너무 맛있었어요. 바닐라라떼도 진하고 맛있어요. ㅎㅎㅎ 다음에는 말렌카 케이크 먹어 보고 싶어요✌🏻☺️', 96, 23, 'GOOD', SYSTIMESTAMP);
