INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '사장님 너무 친절하셨어요! 호두과자도 너무 맛있었어요! 수박주스는 한창 철이라 그런지 달달하구 맛있었어요! 커피에 티백도 함께 들어가서 더 새로운 맛이었다는💕 좋은시간보내고 갑니다!', 27, 1, 'GOOD', SYSTIMESTAMP);
