INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '왕호두가 들어간 바삭 호두과자가 맛있습니다~ 티아메리카노는 향긋하고 커피랑 잘 어울려요! 가게가 아늑하고 조용해서 대화하기 최적의 장소네요. 요즘 시끌벅적 카페보다는 골목길 소규모 카페가 더 매력적으로 느껴집니다. 번창하세요!', 66, 17, 'GOOD', SYSTIMESTAMP);
