INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '꿀케이크와 티아메리카노의 조합 최고에요🤭❤️❤️ 호두과자도 따뜻하고 바삭하고 촉촉한게 맛있습니다~~!! 홍대입구역 2번출구역쪽이라 접근성이 좋아서 오기 편해요!!', 82, 13, 'GOOD', SYSTIMESTAMP);
