INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '혼자 시간을 보내고 싶어서 방문하게 되었습니다. 너무 시끌벅적한 곳 말고 적당히 조용한 곳 가고 싶었는데 아이테르가 딱 그런 곳 같아요. 거기에다가 이 카페만의 특별한 메뉴, 티 아메리카노도 너무 맛있었고, 점심시간 전이라 배부르지 않게 디저트를 먹고 싶었는데 가격도 부담 없는 호두과자가 디저트로 있어서 정말 마음에 들어요👍🏻 음료도 저렴한 편이고 조용히 시간을 보낼 수 있어 나만의 아지트 삼고 싶은 곳입니다!🩷', 32, 8, 'GOOD', SYSTIMESTAMP);
