INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '티아메리카노 파는곳 여기만봐서 궁금해서 왔는데 너무 맛있어요!! 티러버에게 최고입니당 회사근처인데 자주올거같아요~~~ 호두과자도 한번더 구워서 주셔서 따뜻하고 쫀쫀하니 같이먹기 딱입니당', 9, 8, 'GOOD', SYSTIMESTAMP);
