INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '홍대입구역카페 아이테르에서 티아메리카노와 생강차 그리고 호두과자 뿌수고 왔어요. 아늑하고 아기자기한 공간에서 편하게 쉴수 있는 곳으로 홍대카페 아이테르 추천합니다. 호두과자를 직접 구워주시는데 완죤 맛있어요. 다음에 또 가야지~ 홍대맛집으로 강추해요', 28, 0, 'GOOD', SYSTIMESTAMP);
