INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '추운 겨울날 호두과자 간식이 먹고 싶다면, 홍대 아이테르 강추 드립니다! 시그니처 티 아메리카노도 일반 아메라카노랑 다르게 풍미 가득해서 좋았어요. 큰 창이 있어 인생샷 건지기도 좋고, 날 풀리면 테라스 앉아서 먹어야겠네요ㅎㅎ 자리마다 콘센트도 있고 작업 하기 좋습니다!', 6, 3, 'GOOD', SYSTIMESTAMP);
