INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '홍대 카페 알아보다가 발견한 곳인데 번화가 쪽이 아닌 뒤쪽 골목에 위치해, 번잡한 카페가 싫어 우연히 들어가게 된곳이에요. 조용하니 혼카페 가는걸 즐기신다면 추천드립니다. 저만 알고 싶은 곳이지만 사장님과 알바분이 너무 친절해서 알려드리고 싶어 리뷰 적습니다☺️ 티 아메리카노, 호두과자 추천드려요! 번창하세요🍀', 32, 5, 'GOOD', SYSTIMESTAMP);
