INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '아이테르에서 시그니처티를 마셨는데 달거나 자극적이지 않고 맛있었습니다. 내부는 넓고 포근하고 아늑했습니다. 사장님과 직원 분께서도 친절하셔서 감사했습니다~^^ 참고로 호두과자도 정말 맛있었습니다~! ㅎㅎ', 1, 10, 'GOOD', SYSTIMESTAMP);
