INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '호두과자 주문하면 즉석에서 직접 구워주세요 ㅎㅎ 바삭하고 팥도 많고 호두도 크고 맛있어요 겨울에 딱 맞는 간식이에요 페머민트 넣은 아메리카노도 커피에서 페퍼민트 향이 확 퍼지는게 훨씬 깔끔한 커피 맛이에요 딥바닐라라떼는 시럽이랑 꿀이 들어가는데 너무 맛있네요', 242, 30, 'GOOD', SYSTIMESTAMP);
