INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '티 아메리카노 라는 특별한 메뉴가 있어서 너무 신선했어요 ㅎㅎ 저는 블랙피치 맛으로 선택했는데 한 입 마시면 끝에 느껴지는 은은한 복숭아 향이 치고 올라와서 즐겁게 먹었습니다~👍🏻 밀크티라떼도 먹어봤는데 달달하면서 위에 뿌려잔 시나몬 가루가 같이 어울려져서 더욱 향긋하게 즐길 수 있었어요😍 사장님도 너무 친절하시고 낮에 커피 즐기러 오기 딱이예요🤍', 127, 24, 'GOOD', SYSTIMESTAMP);
