INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '연남동 카페 아이테르 시그니쳐음료 티아메리카노 드셔보세요ㅋㅋ 아샷추뒤를 이을 묘한매력의  음료랍니다. 호두과자도 주문과 동시에 즉석에서 구워주시는데 호두과자맛집인듯해요ㅋㅋ 잘 쉬다갑니당😁', 32, 1, 'GOOD', SYSTIMESTAMP);
