INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '커피, 디저트 모두 너무 맛있는 카페!🫢 티 아메리카노가 시그니쳐라고 했는데 생각 이상으로 너무 맛있게 먹어서 다음에도 또 먹으러 오고 싶어요 ㅎㅎ 티 아메리카노는 3가지 티 중에 선택할 수 있는데 얼그레이 왕 추천입니다! 호두과자는 반죽부터 맛있어요😭❤ 겉바속촉이면서 안에 팥 앙금이랑 호두가 같이 씹히는 식감이 넘 좋았습니다!!', 27, 0, 'GOOD', SYSTIMESTAMP);
