INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '홍대에 위치한 아늑한 카페였어요! 멀리서부터 호두과자 판넬이 보여서 발길을 사로잡았는데 음료랑 같이 시켜먹으니 정말 좋네용ㅎㅎ달달한 호두과자에 시그니처 음료 티아메리카노와의 조합이 좋았어요! 특히 티아메리카노는 다른 집에서 먹어본 적 없는 아이테르만의 특색있는 맛이라 추천해요! 사장님도 친절하시구 맛있는 음료가 있는 곳이라 다음에 또 재방문하고 싶어지는 곳이에요🧡', 20, 3, 'GOOD', SYSTIMESTAMP);
