INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '매장인테리어가 감성잇고 예뻐서 대화하기도 넘 좋고 집중하기도 좋을것같네요 전체적으로 커피들이 넘 맛있는데 특히 티 아메리카노가 독특해서 좋았어요 커피향이랑 티 향이 잘 어우러져서 새로운 음료를 마시는느낌이였습니다 ㅎㅎ 호두과자도 새로 나온메뉴라고 해서 먹오밨는데 직접만드시나봐요 바삭하고 쫄깃하고 달달하니 맛잇엇어요 !', 31, 10, 'GOOD', SYSTIMESTAMP);
