INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '티 아메리카노는 처음 마셔보는데 시그니처 메뉴답게 너무 맛있더라구요! 즉석으로 구워주신 알 큰 호두과자도 겉바속촉 맛있어서 티 아메리카노랑 잘 어울렸어요~ 작업하기 좋은 여유로운 홍대 카페 추천!', 76, 11, 'GOOD', SYSTIMESTAMP);
