INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '티아메리카노가 있는 홍대 카페에요! 향긋한 티랑 커피가 너무 잘 어울리네요 왕큰 호두가 들어간 호두과자도 존맛ㅠㅠ 카페 분위기가 좋아서 조용히 잘 머물다갑니다 맛있게 잘먹었어요 🫶', 56, 14, 'GOOD', SYSTIMESTAMP);
