INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '점심 먹고 커피마시러 들렀는데 시그니처 음료인 티 아메리카노 독특하고 좋네요 티 좋아하시는 분들은 입맛에 딱 맞을 것 같아요! 디저트 저희는 코코아 맛으로 선택해서 먹었는데 맛있네요 ㅎㅎ 커피는 연한 편이에요!', 30, 0, 'GOOD', SYSTIMESTAMP);
