INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '홍대입구역에서 5분거리였던  호주스타일 인테리어의 아늑한 카페였어요 티아메리카노가 신기해서 시켜봤는데 페퍼민트향도 나고 상쾌하면서 맛있더라고요 커피향이랑 페퍼민트향이 잘 어울렸어요 화이트 아메리카노도 고소하니 맛있었습니다 꿀케이크는 완존 꾸덕하고 달달하니 맛있었어요 재방문의사⭐️⭐️⭐️⭐️⭐️ 다음에는 바닐라티라떼 도전~!!', 27, 7, 'GOOD', SYSTIMESTAMP);
