INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '홍대입구역에서 도보6분거리라 접근성 넘 조아용 !!시그니처 메뉴인 티 아메리카노(얼그레이) 바닐라 티라떼 (블랙피치) 너무맛있어요 ㅎㅎㅎ 티랑 커피의 조합이라니 신선하면서 티의 향과 조합이 조화롭게 어울려서 말렌카 케이크랑 맛나게 먹었습니다🙂카페 분위기도 너뮤좋고 오늘날이 좋아서 야외 들창자리에서 먹었는데 분위기 미쳤어요 👍🏻👍🏻', 36, 6, 'GOOD', SYSTIMESTAMP);
