INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '말렌카 호두 케이크 처음 먹어봤는데 막 달지도않고 딱 맛있어요:) 티아메리카노도 남자친구가 엄청 만족해했습니다. 바닐라 얼그레이티라떼도 시그니처라 하셨는데 맛있었어요! 사장님도 친절하시고 자주 방문하겠습니다', 24, 7, 'GOOD', SYSTIMESTAMP);
