INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '혼자 조용하게 시간보내고 싶어서 와보았는데 너무 제 취향이었어요!!🧡 완전 코지한 분위기에 노래 선곡도 카페 분위기랑 너무 잘 어울리더라구요~ 사장님은 엄청 친절하시고 음료랑 디저트 둘다 너무 맛있습니당 티 아메리카노는 처음이었는데 상큼한 티 맛과 고소한 커피 맛이 잘 어울렸어요!! 말렌카 꿀 케이크도 달달하니 커피랑 아주 찰떡입니당ㅎㅎ 혼자 와서 작업하기 좋고 친구나 연인끼리와서 대화하기도 너무 좋아보여요ㅎ', 18, 6, 'GOOD', SYSTIMESTAMP);
