INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '호두과자가 디저트로 있어서 이색적이면서 너무 맛있어요!! 안에 팥이 듬뿍 들어가있는데 적당히 달고 겉은 바삭해서 너무 맛있어요😊 티 아메리카노도 적당한 커피향과 티가 적절하게 잘 어울려져서 너무 맛있어요! 사장님도 친절하고 위치도 좋아서 너무 맘에들어요!!', 47, 4, 'GOOD', SYSTIMESTAMP);
