INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '따듯한 감성의 카페 아이테르! 커피맛도 좋고 잔잔한 분위기가 참 좋았어요 주문하면 바로 만들어주시는 호두과자가 뜨끈뜨끈하니 정말 맛았어요😊👍👍', 11, 8, 'GOOD', SYSTIMESTAMP);
