INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '바닐라 티 라떼(블랙피치)는 처음인데 너무 맛있었고 계피가루 향이 넘 좋았어여~ 그리고 호두과자 맛집!! 겉이 바삭해서 더 맛있었고 내부가 아늑하고 사장님께서 친절해서 좋았어여 ㅎㅎ', 52, 15, 'GOOD', SYSTIMESTAMP);
