INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '말렌카 쿨 케이크 정말 맛있게 잘 먹었습니다!! 제가 빵을 진짜 싫어하는데 약간 시루떡?? 떡보단 더 맛있어요!! 식감도 더 퐁실퐁실하고 맛있게 먹었네요! 여기에 있는 티 아메리카노도 꼭 드셔보세요!!! 얼그레이 먹었는데 얼그레이 아메리카노 아이디어 진짜 좋으신거같아요!! 사장님 도 엄렁 친절하시고 밝게 인사해도 해주시고!! 무엇보다!!  남자사장님 너무 잘생겼어요… 조용하게 노래 들으면서 공부하기도 좋고 행복했던 시간 보내고 갑니다!', 23, 9, 'GOOD', SYSTIMESTAMP);
