INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '향긋한 커피향 뒤로 은은하게 느껴지는 티의 향이 새로우면서도 빠져들 것 같은 중독이 있는 티(tea)아메리카노를 즐길 수 있어서 좋았습니다. 쫀득한 식감에 꿀 향이 느껴지는 말렌카 꿀 케이크도 good!!', 67, 13, 'GOOD', SYSTIMESTAMP);
