INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '티가 들어가 향긋한 아메리카노를 마실 수 있는 홍대입구역 카페! 호주식 심플한 인테리어로 시간보내기 좋았어요:) 저는 티 아메리카노 페퍼민트를 마셨는데 첫맛은 고소하다 뒤에 화사한 맛이 퍼지는데 진짜 새로운 경험이었으며 말렌카 케이크는 달달하면서 촉촉하니 맛있었어요.ㅎㅎ 개인적으로 분위기도, 음료 맛도, 가격도 좋아 근처오면 또 들려봐야겠어요!', 14, 0, 'GOOD', SYSTIMESTAMP);
