INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '티아메리카노 처음 마셔보는데 괜찮네요!? 페퍼민트로 먹어봤는데 다음엔 얼그레이티아메리카노로 도오저언! 말렌카 케이크는 말해뭐해.. 진짜 개존맛탱 ㅜㅜ 제 최애.. 진짜 안드셔본 분들 제발 말렌카 드셔주세요.. 개인적으로 호두가 젤 맛남! 홍대에서 분위기도 좋고 음악들도 차분해서 노트북 하기도 좋은 곳 찾으신다면 여기가 딱 일 듯!', 87, 15, 'GOOD', SYSTIMESTAMP);
