INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '티아메리카노,바닐라얼그레이라떼,호두말렌카꿀케이크 주문했는데요! 티아메리카노는 페퍼민트로 택했구요, 첨엔 생소했는데 한입먹어보니 너무 깔끔하고 향긋한게 딱 제 스타일이더라구요!! ‘민트파🌿’이신분들은 완전 강추입니다!!!!인테리어두 이쁘고 분위기도 좋아서 홍대나 연남동 방문하실 계획있으시면 아이테르에서 여유를 즐겨보세요🪵💚', 18, 9, 'GOOD', SYSTIMESTAMP);
