INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '좋은 제품 쓰셔서 커피도 디저트도 다 너무 맛있어요 ✨ 사장님께서 맛에 진심이시더라고요 :) 단거 별로 안좋아하는데 많이 달지 않아서 제 입맛에 딱이에오ㅎㅎ 홍대 오면 자주 올 것 같아요', 13, 4, 'GOOD', SYSTIMESTAMP);
