INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '티 아메라카노 얼그레이로 마셨는데 너무 맛있어요!! 말렌카 꿀 케이크 디저트도 쫀쫀 달달하니 취향저격입니다😍 주변 인스타 인기 카페보다 좋은것같아요 추천해요', 6, 6, 'GOOD', SYSTIMESTAMP);
