INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '홍대에 힐링하러 왔다가 분위기 좋은 카페 발견🩵 코지한 분위기에 힐링 그자체🍀 홍대에 이런 카페 있는지 이제 알았다니!! 사장님 두분 친절하시고 하나하나 신경써주셔서 좋았어요!🥰 그리고 티아메리카노가 시그니처인 카페인데 티랑 커피의 조합이 오묘해요! 그냥 아메리카노가 아닌 특별한 커피 드시로 오고 싶으시다면 홍대 아이테르 추천✌️데이트 하러 오기도 좋은 카페! 디저트도 특이한 메뉴로 추천드립니다! 초코말렌카꿀케이크 꾸덕하고 초코맛 찐하니 꼭 드셔보세요!🤍 도심속에 편안하게 힐링하러 오기 좋은 카페!', 63, 14, 'GOOD', SYSTIMESTAMP);
