INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '일단 인테리어가 넘 예뻐요 ,,, 그리고 티 아메리카노 처음 마셔봤는데 !! 너무 신기한 맛 .. 너무 맘에 쏙 드는 거 있죠 .. ♥ 저는 페퍼민트로 마셨습니다 ㅎ 끝맛이 시원해서 넘 좋았어요 그리구 캐모마일 사과는 달달하구 시원하구 애플시나몬느낌?? 맛 좋았어요 ! 말렌카 시나몬 맛 먹었는데 빵 아스크림 같은 느낌 ?! 시나몬 향이 넘 좋아요 !!  전체적으로 다 맘에 드네욤 ㅎㅎ', 38, 4, 'GOOD', SYSTIMESTAMP);
