INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '경의선 숲길을 거닐다가 분위기 좋아보이는 카페를 발견해서 들어왔어요~ 페퍼민트 향이 나는 티아메리카노를 먹었는데 상쾌한 맛이 에스프레소와 잘 어울러져 만족스러웠습니다🥰 다음번에는 말렌카 꿀케이크 막으러 방문하려구요ㅎㅎ 가볍게 책 읽기도 좋고 날씨좋은 날에 방문하기 좋은 아이테르 강추💕', 62, 12, 'GOOD', SYSTIMESTAMP);
