INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '특별한 커피(티 아메리카노, 호두과자)가 있었는데 맛이 매우 훌륭했습니다🫢 사장님이 매우 친절해서 기분좋게 마실 수 있었습니다😄', 57, 15, 'GOOD', SYSTIMESTAMP);
