INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '홍대입구역 예쁜카페 아이테르!! 아늑하고 예쁜 인테리어부터 커피 디저트 맛까지 너모 좋았어요 유럽감성 느껴지는 분위기가 힐링이구 저는 티아메리카노 주문했는데 안 그래도 맛있는 커피에서 티의 향긋함이 느껴지니까 색달라서 좋았어요 마시고 나서도 자꾸 생각나는 맛있는 커피였어용 생과일주스도 테이크아웃해왔는데 신선한 과일을 바로 갈아주셔서 완전 맛있더라구요 편하게 혼카페 하기도 좋구 친구들끼리 대화 나누기도 좋은 분위기좋은 홍대 연남동 카페로 추천해요 사장님도 친절하시구 자주 재방문 하고싶은 곳입니당!!', 16, 0, 'GOOD', SYSTIMESTAMP);
