INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '홍대에서 지나가다가 외부가 완내스라서 들어갔는데 내부 마저 감성낭낭한거 뭔가요 🥹 거기에다가 음료랑 디저트 주문할때 뭔지 모르는 것도 친절하게 하나하나 알려주시고 완전 감동 그자체였어요 🫢🖤 그 뿐만 아니라 음료랑 디저트가 완전 맛나고  처음 먹어본 디저트인데 식감도 특이해서 더더 먹는데 재미가 있었어요! 다음엔 날이 더 좋으면 분위기 있게 밖에 테라스 같은 곳에서 음료 마시면서 여유롭게 시간 보내러 올게요 🥹🖤', 23, 0, 'GOOD', SYSTIMESTAMP);
