INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '티아메리카노 향이 너무 좋아요ㅠㅠ 돌체라떼도 달달하고 고소하니 넘 맛있네요ㅎㅎ 겨울이니깐 호두과자도 시켜서 먹었는데 따뜻하게 구워져서 나오고 안에 통호두가 들어가있어요!ㅎㅎ 완전 맛있게 먹었습니다🫶', 18, 5, 'GOOD', SYSTIMESTAMP);
