INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '여기 말렌카호두진짜 맛있어요... 그리고 캐모마일 애플티 무조건 시키세요.. 애플맛이 달달하게 넘 맛있구요 티아메리카노 캐모마일맛도 지인짜 맛납니다!! 여긴 찐 맛집이에요', 89, 16, 'GOOD', SYSTIMESTAMP);
