INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '회사 근처 있는 카페인데, 티아메리카노 특이하니 아침에 먹기 좋았어요😀 강아지가 있어서 양해부탁드리고 야외테라스 앉았는데 햇살이 이쁜 카페입니다!! 사장님 친절하시고 담에 장군이 델꼬 또 올께용🐕', 20, 1, 'GOOD', SYSTIMESTAMP);
