INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '멋지고 러프한 우드 인테리어🤎 동교동카페 아이테르 ✔️ 티 아메리카노 (얼그레이) ✔️ 말렌카 꿀 케이크 (호두) 음료 양이 많고 톨,벤티,벌크 세가지 사이즈로 나눠져 있어서 좋아요. 사진은 톨 사이즈인데도 양이 무척 넉넉하죠? ㅎㅎ 티 아메리카노는 홍차와 커피를 블렌딩한 음료인데, 향이 독특하고 가벼워서 좋았어요! 들창은 열린 모습이 더 멋있어요! 외국 노천 카페 같아요 🙂 사장님도 친절하시고, 개인작업, 독서 등을 하기 좋은 분위기입니다. 환하고 조용해요!', 68, 16, 'GOOD', SYSTIMESTAMP);
