INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '바닐라라떼도 너무 맛있고 스팀 진짜 잘내리신거 같아여 사장님이 라떼에 진심이신듯 합니다ㅎㅎ 시그니처인 캐모마일 사과티도 너무 달지않고 적당해서 맛있었어요ㅎ.ㅎ', 14, 2, 'GOOD', SYSTIMESTAMP);
