INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '홍대 너무 예쁜 카페 발견!!! 여긴 티아메리카노가 시그니처인데 진짜 색다른 맛인데 입안이 깔끔하고 넘 맛있다!! 대용량 텀블러에 넣고 죙일 마시고 싶은맛~ 디저트도 넘넘 맛있넹^^', 26, 3, 'GOOD', SYSTIMESTAMP);
