INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '매장이 굉장히 아기자기 예쁘고 티 아메리카노가 넘 맛있었어요 🫶🏻 티의 향이 잘 나는 아메리카노라 특이하면서도 계속 땡기는 맛이더라구요 말렌카 케이크도 녹진하고 달달해서 아메리카노와 먹기 딱 좋았답니다 매장이 조용하고 예뻐서 자주 오게될 것 같아요 ☺️', 46, 0, 'GOOD', SYSTIMESTAMP);
