INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '커피메뉴에 티가 포함된게 여기 시그니처에요~~ 커피마시면서 티 맛도 나니 좋네용! 딱 깔끔하고 아담한 느낌의 개인카페라서 여유롭게 커피한잔 하기 딱입니다! 정신없는 연남동에서 이런 바이브 넘 귀히고 좋아용😌', 18, 7, 'GOOD', SYSTIMESTAMP);
