INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '티와 아메리카노의 조합이라뇽~~  이런 아이디어는 어떻게 생각하셨는지! 기존 아메리카노와는 다르게 더 깔끔한 느낌이에요 ㅎㅎ 그래서 달달한 디저트와도 넘 잘 어울리구용~~ 잘 먹고 갑니다!', 19, 7, 'GOOD', SYSTIMESTAMP);
