INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '홍대에서 찾기 어려운 카페입니다! 가격도 엄청저렴한데 맛도 있고, 디저트도 너무 맛있어요 ㅋㅋ 카공하고싶은분들에게도 추천입니다!! 홍대오시면 꼭 가보세요~!', 2, 7, 'GOOD', SYSTIMESTAMP);
