INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '연남동에서 먹은 음료 중에 제일 맛있어요 😀 커피 좋아하는 친구 따라서 방문했어요! 티 아메리카노가 맛있다고 들었는데, 저는 커피를 못 먹어서 바닐라 얼그레이 라떼 시켜보았는데요. 얼그레이향에 바닐라 라떼가 너무 부드럽고 맛있었어요 🧡 커피 잘하는 카페 가면 다른 메뉴는 구색만 갖추는 경우가 많아서, 크게 기대 안했는데 감동이에요.. 🥹 커피/음료 잘하는 연남동 카페 찾으시면 꼭 추천이요!', 108, 25, 'GOOD', SYSTIMESTAMP);
