INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '홍대 티아메리카노 맛집 아이테르에요. 카페 분위기 차분하고 깔끔해서 좋아요. 시그니처 메뉴인 티아메리카노 블랙피치는 복숭아 맛이 살짝 가미되어 진한 아메리카노와 잘 어울리네요. 허니바닐라라떼도 베스트 메뉴인데요. 달콤하고 부드러운 향이 좋아요. 데이트 장소로 딱이에요.', 16, 9, 'GOOD', SYSTIMESTAMP);
