INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '선선한 날씨에 찾은 홍대입구역에서 가까운 아이테르 카페!! 들창이 열려있어서 시원한 바람을 맞으며 커피를 마실 수 있어서 좋았어요!! 시그니처메뉴인 티아메리카노랑 수박쥬스 먹어봤는데 티아메리카노는 우리가 블랙피치를 골라서인지 아샷추가 생각났어요!! 수박쥬스도 달달하고 시원해서 맛있었고 말렌카꿀케이크도 독특하고 맛있었어요!!', 2, 10, 'GOOD', SYSTIMESTAMP);
