INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '커피전문점이여서 그런지 커피가 아주 맛있네요! 가격도 가성비 있는데 저렴한 맛이 아닌 깊이가 있습니다!! 그리고 케이크도 너무 맛있어요! 말렌카케이크라는데 너무 맛있네요!!! 분위기도 좋고, 사장님도 친절하세요!👍🏻💕무엇보다 사장님께서 너무 잘생기셔서 놀랐습니다..!배우이신줄알았어요! 또 놀러가겠습니다!', 6, 0, 'GOOD', SYSTIMESTAMP);
