INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '티 아메리카노는 처음인데 시그니처 메뉴인 만큼 정말 맛있네요! 얼그레이로 시켰는데 다음엔 페퍼민트로 먹어보려구요 ㅎㅎ 말렌카 꿀 케이크도 꾸덕달달 맛있어서 아메리카노랑 먹기 딱이에요 🍰🤍', 67, 16, 'GOOD', SYSTIMESTAMP);
