INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '너무나도 향긋한 티아메리카노가 너무 맛있어서 인상적이에요! 말렌카꿀케이크도 달콤하고 부드러워서 먹는내내 기분이 좋았던 카페인 것 같아요!!', 11, 0, 'GOOD', SYSTIMESTAMP);
