INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '말렌카 꿀케이크 호두맛 진짜 이거 찐이에여 3접시도 먹을 수 잇어욯ㅎㅎ 티아메리카노도 티향이 가득나서 특이하고 끝맛이 깔끔해요. 케이크랑 조합이 좋아요!', 71, 12, 'GOOD', SYSTIMESTAMP);
