INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '친구랑 홍대갔다가 분위기 넘 이뻐보이는 카페 발견해서 들렀는데 디저트도 맛있고 음료도 맛있어서 좋았습니다~~~ ㅎㅎ 또 방문 할게용~', 5, 4, 'GOOD', SYSTIMESTAMP);
