INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '티아메리카노가 맛있고, 수박주스가 맛있고, 말렌카가 맛있고 가게가 조용하고, 음악이 차분하고, 접근성이 좋은 카페. 인근에서 식사 후에 방문 추천드립니다.', 1, 0, 'GOOD', SYSTIMESTAMP);
