INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '친구랑 같이 방문했는데 차분하고 조용한 분위기라 둘이서 대화하기 좋았어요! 내부 공간도 깔끔하고 대화에 집중할 수 있었습니다. 그리고 통창이 예뻐요~!', 34, 10, 'GOOD', SYSTIMESTAMP);
