INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '이정도 크기에 수박쥬스가 5천원이라니!! 넘 저렴하고 가성비 좋은것 같아요! 그리구 수박씨를 다 제거 해주셔서 마시기 너무 편해요 ㅜㅜ 짱짱 (๑•̀ㅂ•́)و✧', 51, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '공간이 작고 테이블 몇 개에 아기자기한 디저트를 갖춘 집이다. 커피와 디저트의 맛운 그럭저럭. 근처에 너무 예쁜 카페가 많아 눈에 띄기엔 힘들지 싶다', 68, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이테르'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '아메리카노 테이크아웃 1500원(매장 2000원) 진짜 감사한 가격입니다 덕분에 수액 잘 충전하고 다녀요! 그렇다고 맛 없는 것도 아니에요 쓴맛 텁텁한맛 담배냄새 안 나고 적당한 산미 있습니다 약간 연한 것 같긴 해요 전 연한 거 좋아해서 완전 만족합니닷 주로 오후 3시 이후에 가는데 그쯤엔 사람이 많이 없다가 4시 이후엔 두세 테이블씩 사람들 앉아 있는 것 같앗습니다 조용할 때 가서 작업하기 조아요~', 19, 1, 'GOOD', SYSTIMESTAMP);
