INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '위드커피'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '영어 단어 중에 가장 좋은 단어가 WITH...라지요. 함께, 같이의 의미가 있는 위드. 2층 발코니에 큰 화분들이 시선을 끄는대로 들어와 봅니다. 깜끔하고 쾌적한 느낌의 테이블. 눈길가는 케익과 음료들.. 아~~ 오늘도 다이어트는 물건너갔구나...하면서도 치즈케익과 아이스아메리카노를 주문합니다. 기다리는 동안 두리번 거리며 인테리어를 살펴봅니다. 아직 정신연령이 낮은 탓에 아기자기한 소품들에 Hi~ 인사를 합니다. 2층으로 올라가는 계단. 다리에 문제가 있어 몇번을 망설이다 올라갔습니다. 2층은 커피를 마시며 대화할 수 있는 공간과 데블릿이나 노트북을 사용할 수 있는 공간이 따로 분리되어있어 잠시 학업이나 일을 처리할 때 옆 테이블과의 대화로 불편함을 줄여줍니다. 폰번호 입력하면 포인트도..', 86, 13, 'GOOD', SYSTIMESTAMP);
