INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '위드커피'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '얼그레이 케이크가 맛있어요. 치즈케이크도 맛있는데 얼그레이 케이크가 제 입엔 덜 잘고 맛있더라고요. 티 종류도 꽤 많고 늦은 시간에 방문했는데도 마실 게 많아서 좋았습니다. 넓고요.', 64, 18, 'GOOD', SYSTIMESTAMP);
