INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '위드커피'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '홍대 아기자기한 커피숍입니다.무엇보다 좌석이 많아 언제가도 자리가 있고. 대화나누기가 너무 좋은곳 입니다. 직원분들도 너무 친절하게 응대해주시구요 ㅎㅎ', 13, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '위드커피'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '홍대입구 8번역 출구 커피숍중에서는 여기가 가장 쾌적 한 거 같습니다. 최근에 로커피가 새로 생겨서 그곳이 핫 하기는 하지만 그래도 2층까지 있고. 따로 흡연실도 설치 되어 있어서 대화나누기 좋은거 같습니다', 71, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '위드커피'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '가끔 나가는데요~ 지금 계시는 직원분 (얼굴 하얀)이 정말 친절하셔서 리뷰남겨요. 히비스커스 티를 뜨겁게 시켰는데 그만 잔 채로 잡았지 뭐예요. 근데, 뜨겁다며 웃어주시더라고요! 다른 손님 대하는 태도도 한결 같이 깍듯하고 친절해서, 모르긴 몰라도 손님들 모두 기분이 좋아졌을 거예요 :) 사장님은 이런 직원에게 뭐라도 더 챙겨주셔도 좋을 것 같아요. 아시겠지만, 이런 직원분이 매출을 올려주잖아요. 홍대에 커피집이야 많죠. 맛도 비슷하구요. 중에 한 곳만 간다면 여기 이 집만 갈 것 같아요. 다녀오면 기분이 좋아지니까요. (직원분이 2층에 올라 오셔서 테이블 닦고 빈컵들 들고 가시는데 한번도 핸드폰을 안 하시더라구요.)', 77, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '위드커피'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '요즘 자주 방문중인 커피숍입니다. 2층까지 있어서 자리도 넉넉하고. 커피도 맛 좋고. 직원분들도 친절 해서 한번 가고 나서는 두번.세번 방문중인 곳입니다. 근처에 커피숍도 많지 않아서 자연스럽게 가게되었지만 기대 이상만족이라 앞으로도 자주 방문 드릴 생각입니다', 59, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '위드커피'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '모임이 있어서 방문했는데 홍대에 있는 것치고 사람이 심하게 붐비지는 않아서 좋았어요! 화장실도 1층 2층 둘 다 있어서 편합니다', 32, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'MEETING');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '위드커피'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '일단 드럽게 불친절해요! 사람이 많아서인지.. 주문할때부터 불친절하고 사람이 그렇게 많지도않은데 앉은자리 바로옆에서 막 걸레질하고 불편하게 합니다. 1시간넘어가니까 바로.. 아무리 주말이라지만 아메리카노 5천원하면서 1시간앉는것도 눈치봐야되나 싶네요 두명이서왔는데.. 역에서 가까운게 아니라면 굳이 갈필요가없어요 커피도 일단 맛이없구요', 32, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '위드커피'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '아침에 남자친구 기다리며 급하게 화상미팅할 곳이 필요해서 주차가능한 카페를 찾고있었는데 매장앞에 주차 공간이 있어서 너무 좋았어요🙂 홍대근처에 주차가 가능한 곳을 찾기가 힘들거든요 테라스도 채광도 좋고 콘센트 좌석도 많고 너무 좋은 곳 알아낸 것 같아요! 사장님 두분은 젊은 부부이신 것 같은데 너무 친절하시구 커피도 크림치즈 프레즐 맛있었어요! 남자친구랑 자주 올게요🩵', 32, 7, 'GOOD', SYSTIMESTAMP);
