INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '위드커피'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '오랜만에 홍대 근처방문 창가에 예쁘게 피어있는 꽃화분에 끌려 들어감 시원한 커피 맛도 괜찮고 1층2층  넓고 깔끔한느낌의 까페', 46, 3, 'GOOD', SYSTIMESTAMP);
