INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '위드커피'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '더많은 사진과 자세한 후기는 블로그로 와주세여:) https://m.blog.naver.com/smilefaceu/223070438745', 27, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '위드커피'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '카페에서 공부하려고 2층 올라와서 4명이 앉을 수 있는 테이블에 2명이 앉았습니다. 2개로 연결되어 있는 테이블에 의자 8개가 둘러싸여 있었고요. 벽 쪽에 다른 의자들도 놓여있었습니다. 당연히 단체손님이 왔다 간 줄 알아서 나머지 의자 4개를 벽쪽에 치워 놓고 공부하고 있던 도중 카페 사장님이라는 분이 사람 8명 앉는 자리에 젊은 사람들이 그러면 안된다고, 뭐 저희 때문에 사람들 다 나간다고 뭐라 하시고 가시더라고요. 테이블 위에 4인 이상 앉아달라고 펫말이라도 명시되있었으면 안 앉았겠죠. 다짜고짜 오셔서 그런식으로 말하셔서 기분이 매우 불쾌했습니다. 다음부터 뭐라도 명시하는 말이라도 테이블에 올려 놨으면 합니다.', 63, 14, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '위드커피'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '아무생각 없이 근처에서 그나마 오래하길래 들어갔는데 매장도 예쁘고 직원분들도 친절했어요 벽에 붙어있는 안내문 읽고 힘내서 돌아왔네요 번창하세요 사장님~!!', 17, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '비가 억수로 내렸어요.  우두둑 소리가 들리는 카페..식물이 많아서 숲속에 와 있는듯. 사람들이 별로 없을 거라 생각했는데 생각보다 많았어요. 맛있는 음식과 커피..즐거운 대화를 나누고 왔어요. 좋은 사람들과 쾌적한 카페에서 수다를 즐기며....행복한 시간이었어요.', 74, 13, 'GOOD', SYSTIMESTAMP);
