INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '오랜만에 왔는데 합정 오면 꼭 들리는 곳이예요! 라떼 아트도 예쁘고, 파운드 케이크도 부드럽고 맛나요 ㅎㅎ 분위기도 좋고 여러 느낌의 테이블들이 있어서 지하, 2층까지 있어서 대화 하기도, 혼자 집중하기도 좋습니다 :) 노래 사운드도 웅장하고 😂 음료는 말해 뭐합니까 ㅎㅎ 그린 플로우 커피 너무 맛있어요!! 추천합니다 👍🏻 오늘은 식사하고 왔는데 다음에는 브런치도 먹으러 와야겠어요!!', 20, 4, 'GOOD', SYSTIMESTAMP);
