INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '#합정맛집 🙂 합정역에서 나와 조금 걸어서 만나는 새로운 세계- 식물원에 들어가는 것 같은 기분과 1, 2, 지하까지 공간이 크고 넉넉합니다. 🍍 파인애플 에이드 상큼달콤하고, 음식들도 맛있네요.  서비스 친절하고 만족합니다.', 38, 9, 'GOOD', SYSTIMESTAMP);
