INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '합정 주말 브런치 맛집! 주말 오전에 워크인 했는데요~ 자리도 널널하고 분위기가 너무 좋았습니당! 특히 부라타 프로슈 샌드위치가 맛있습니다! 강추 그리고 어반플랜트 특유의 향이 너어어무 좋습니다! 주말 오전 데이트 코스로 추천드립니당', 4, 3, 'GOOD', SYSTIMESTAMP);
