INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '도심 속 식물원에 온 느낌입니다 지하 1층부터 지상 2층까지 있으며 넓은 공간이라 모임으로나 개인으로 와도 너무 좋네요 커피와 음식 모두 제공하고 브런치까지 !! 여름에 시원하고 이색적인 카페 인 것 같아요 직원들의 대응이 빠르고 친절해요 🥰 #합정맛집 #합정카페', 32, 3, 'GOOD', SYSTIMESTAMP);
