INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '초록초록 식물이 많아서 그런지, 공기가 싱그럽고 상쾌한 느낌이 들어요 ! 그리고 들어오자마자, 메뉴시킬때 등등 직원분들 인사와 서비스가 매우 좋습니다 ! 음료맛도 좋은데 서비스때문에 기분이 더욱 좋아지는 것 같아요^.^ 어딜가든 밝은 인사는 밝은 기운까지 주니까요~ 어머니가 만족하셔서 곧 다시올것같아요! 다음엔 음식도 같이 먹으며 시간 보내러올게요~!', 72, 18, 'GOOD', SYSTIMESTAMP);
