INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '합정 브런치 약속은 항상 합정맛집 어반플랜트로 오는데요~! 오늘은 제가 좀 일찍도착해서 아이스아메리카노랑 홈메이드티라미수 먹으며 친구를 기다려요~! 공간에 은은하게 퍼져있는 풀 냄새도 좋고, 테이블과 의자도 탄탄해서 너무 좋아요. 여기 자주 왔지만 홈메이드티라미수는 처음 먹어봤는데 폭신하고 촉촉해서 아이스아메리카노랑 너무 잘어울리구 맛있어요~!!! 친구오면 샌드위치도 먹어보려고요~!#합정맛집', 38, 1, 'GOOD', SYSTIMESTAMP);
