INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '깻잎 파스타랑 치킨 샌드위치랑 아메리카노 같이 먹었는데 너무 맛있어요!! 인테리어도 식물이 많은 초록초록한 감성에 넓고 쾌적해서 대화하기도 좋고 음식도 너무 맛있습니다 ㅎㅎㅎ #합정맛집 #합정데이트', 5, 7, 'GOOD', SYSTIMESTAMP);
