INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '얼마전에 와보고 넘 좋아서 또 왔어요. 식물이 이렇게 많은 카페라니!!! 음료도 맛있고 친절해요. 함께 온 사람들 모두 만족이요!! 합정맛집이에요!! 근처 오시는 분들 꼭 들러보세요~~', 104, 20, 'GOOD', SYSTIMESTAMP);
