INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '공간 가득 초록 식물이 놓여 있어서 들어서는 순간부터 싱그러움이 느껴졌어요. 원목으로 꾸며진 인테리어와 작은 화분들이 주는 따뜻한 분위기 덕분에 마치 작은 정원에 앉아 있는 듯한 기분이었어요. 자연광이 들어오는 자리에서는 식물들이 만들어내는 그림자가 예쁘게 드리워져 더 포근했답니다! 가게 한쪽에는 신선한 채소와 과일, 식재료들이 진열되어 있어서 단순히 카페라기보다 작은 마켓에 온 것 같은 재미도 있었어요. 공간 곳곳에 세심하게 배치된 식물들과 내추럴한 소품들이 편안함을 주어서 오랜 시간 머물고 싶어지는 장소였습니다!! #합정맛집', 0, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '합정 맛집이라고 일행이 강추해서 왔는데 후회없는 선택이었어요. 일단 매장이 식물 가득해서 너무 멋지고 음식도 건강한 메뉴가 가득하더라구요. 다이어트 중인데 부담없이 맛있게 잘 먹었어요. 다음에 브런치랑 식물 좋아하는 친구랑 또 올거예요!!!', 23, 1, 'GOOD', SYSTIMESTAMP);
