INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '여기 친구랑 찾아서왓는데 너무 내부가 이쁘고 직원분들이 친절하세요! 솔직히 카페가 너무 이뻐서 맛있을까 생각도 했는데 커피랑 같이 먹은 샌드위치, 파스타 둘다 맛있었어요!! 다음에 또 오겠다하는 곳입니다👍👍 안에 내부도 진쩌 시원해용 #합정맛집 #합정카페', 20, 4, 'GOOD', SYSTIMESTAMP);
