INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '#합정맛집 합정 어반플랜트, 식물 인테리어가 많아서 눈도 편하고 분위기도 좋았어요. 테이블 간 간격 넓어서 조용히 얘기하기 괜찮고, 좌석도 편했어요. 음료 마셨는데 맛 괜찮았고, 직원분들도 응대 깔끔하고 전체적으로 관리가 잘 되어 있다는 느낌이 들었어요. 카페 자체가 깔끔하고 쾌적해서 다시 올 의향 있어요. 🤍🍀', 12, 4, 'GOOD', SYSTIMESTAMP);
