INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '합정맛집에 이런 곳이 있었다니?! 실내인데 야외에 온 느낌이랄까요. 파스타와 함께 차도 마실 수 있어 데이트하기 좋아요❤️ 비오는 날, 바람 선선한 날, 햇살 좋은 날, 분위기 전환하고 싶을 때 혼자 또 오고 싶네요.', 20, 2, 'GOOD', SYSTIMESTAMP);
