INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '도심안에 이런 식물가득한 장소가 있다는게 힐링이에요. 부라타 프로슈 샌드위치도 넘 맛나요.  가끔 식물들로. 분위기로 힐링하러 와야겠어요.', 76, 18, 'GOOD', SYSTIMESTAMP);
