INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '명칭그대로 정체성이 plant인 인테리어여서 독특하고 컨셉츄얼해서 마음에 든 공간이였어요 브런치카페로 알고갔는데 브런치>>카페의 비중인거같은게 들어가자마자 단체인사 하시더라구요ㅎ.ㅎ 분위기좋은공간에서 맛있게먹고왔어요', 44, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '크림파스타 먹었는데 깔끔담백하고 살짝 매콤해서 딱 좋았어요 바게트도 너무 딱딱하지않아서 소스랑 같이먹기에 부드러웠어요 ! 합정맛집입니다 식물이 많아서 향도 좋고 , 특히 파인애플에이드 강추입니다 🍍🍍', 115, 21, 'GOOD', SYSTIMESTAMP);
