INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '우연히 합정카페찾다가 왔는데 너무너무 좋은곳 발견했어요! 입구부터 식물원,화원 느낌물씬나고 식물들이 있어서 그런가 공기도 너무좋은것 같아여! 커피도 맛있구 샌드위치도 진짜 너무너무 맛있었어용 요기요기 합정맛집입니다><', 61, 16, 'GOOD', SYSTIMESTAMP);
