INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '음식 너무 맛있고 실내 인테리어가 너무 힐링이었어요,,,,,💓 잠깐 쉬다가는 도심속 정원느낌,,, 다음에 또 방문할게요!! 합정맛집,, 인정,,,,', 298, 43, 'GOOD', SYSTIMESTAMP);
