INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '입구부터 향 너무 좋아요🩷 가볍게 브런치도 즐길수있고 음료 종류도 많아 좋았습니다😍!! 올때마다 힐링받고 가요🫶 #합정카페 #합정맛집', 8, 2, 'GOOD', SYSTIMESTAMP);
