INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '전에 한번 왔다가 너무 좋았던 기억에 특별한 날 한 번 더 찾아온 ✨합정맛집✨이에요! 매장도 엄청 커서 제일 좋아하는 자리 찾아서 앉을 수도 있고 대화하기도 좋아서 애정하는 곳입니다 ㅎㅎㅎ', 177, 61, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '친구랑 방문했어요 예쁘다고 합정맛집으로 유명해서 방문했는데 인테리어는 물론 음료 브런치까지 완전 맛집에 분위기 짱짱입니다! 직원분들도 친절하세요!', 64, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '말차 티라미수 먹으러 친구랑 같이 방문한 카페인데 인테리어도 음료도 디저트도 다 근사한 맛집이었어요🥹🩷 식물 많은 카페를 정말 좋아하는데 입구부터 딱 온실같은 분위기가 느껴져서 정말 좋았어요! 2층인데다 매장 자체가 넓고 야외 테라스에도 자리를 마련해놓으셨더라구요 날 좀 선선해지면 야외에 앉는 것도 좋을 것 같아요😍 말차를 좋아해서 음료랑 디저트를 다 말차로 시켰는데 말차 맛이 정말 진하고 크림도 맛있었어요ㅎㅎ 다음에는 브런치 식사도 먹으러 오고 싶어요🤤🩷 #합정맛집', 124, 24, 'GOOD', SYSTIMESTAMP);
