INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '너어어무 맛있어용 !! 합정맛집 인정 👍🏻👍🏻인원수까지 체크해주시면서 세심하게 메뉴 내어주시구,, 짱! 카페인줄만 알았는데 양식까지 넘 잘하는 카페예요 🤍 데이트장소로도 좋을듯!!!', 37, 6, 'GOOD', SYSTIMESTAMP);
