INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '한국에서 느낄 수 없는 정원이 있는 느낌이 좋은 카페였습니다. 브런치도 맛있었어요 다음에 기회되면 또 오고 싶네요! 합정맛집입니다', 62, 17, 'GOOD', SYSTIMESTAMP);
