INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '합정 맛집으로 유명해서 와보고 싶었는데 분위기도 좋고 식물들이 가득해서 들어올 때부터 자연의 향이 좋아요! 음식도 맛있고 흘러나오는 음악도 좋아요!', 58, 16, 'GOOD', SYSTIMESTAMP);
