INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '식물을 좋아하시는 분에게 강추입니다. 음료도 맛있고 활기차고 자연자연한 부분이 좋아요☺️ 지하철에서도 가까워서 합정에 오실 일 있으시면 강추드립니다~! #합정맛집', 23, 8, 'GOOD', SYSTIMESTAMP);
