INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '합정 맛집입니다 부모님 모시고 재방문 했어요~! 샌드위치는 부라타가 젤 맛있는 것 같아요 ㅎㅎ 향도 푸릇하니 시원하고 시간 보내기 좋았네요 #합정맛집', 33, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '완죤강츄해요오~~저희 아지트에욧 양도 푸짐하고 맛있어요! 공기정화 식물이 있어서 공기가 상쾌해요~~ #합정맛집 #어반플랜트 #말차티라미수 #피톤치드', 40, 8, 'GOOD', SYSTIMESTAMP);
