INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '어반플랜트는 공간이 참 예뻐요ㅎㅎ 힐링하는 기분이 많이 듭니닷 ㅎㅎ  음료도 진짜 너무 맛있어요! 커피도 맛있고 에이드도 입에 안 맞으면 청이나 에이드를 더 추가해주신다고 하더라구요! 직원분들도 올 때마다 항상 친절하셔서 더 기분이 좋은 것 같아요ㅎㅎ 합정맛집으로 브런치도 유명하던데 조만간 브런치 먹으러 한번 더 와야겠어요! 감사합미다 :)🌿🌱🌳🍀💚', 32, 0, 'GOOD', SYSTIMESTAMP);
