INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '#합정맛집 점심시간에 새로운 곳 오고 싶어서 검색해서 왔어요. 들어서자마자 입구부터 꽃집향기 향긋하고, 사방에 가득한 식물들에 기분이 너무 좋아졌습니다. 음료 종류도 많고 푸드 종류도 많아요! 양도 푸짐해서 넉넉하게 아주 잘 먹었어요!', 114, 23, 'GOOD', SYSTIMESTAMP);
