INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '아아랑 아라 티라미수 주문햇어요 커피맛이 고소하고 넘 맛있어요! 푸른숲속 정원 느낌이고 분위기 너무 좋아요! 재방문 의사있어요!😀', 89, 17, 'GOOD', SYSTIMESTAMP);
