INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '오전 10시반에 문 연 곳을 찾다 우연히 알게 된 훌륭한 브런치 카페입니다.  골목에 있고 간판이 크지 않아 찾기는 약간 어려웠지만 들어가는 입구 부터 코에 훅 들어오는 싱싱한 식물냄새부터 사람을 사로잡는 매력적인 장소입니다.  친절하고 목소리 좋은 직원분들과 맛있고 푸짐한 음식들이 좋은 선택했다 했네요.  각종 식물들 가득한 인테리어와 군데 군데 외국인 손님들이 마치 발리같은 어디 휴양지에 와 있나 싶게 만드는 곳입니다. 맛있게 즐겁게 행복한 시간 보내다 왔습니다.  그리고 예쁜 화분까지 서비스 받으니 누구든 데려가고 싶은 그런 장소입니다.', 26, 6, 'GOOD', SYSTIMESTAMP);
