INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '남편과 시원한 곳에서 브런치를 먹고 싶어 방문했습니다. 식물들이 많아서 쾌적하고 시원한 공기 덕분에 식사내내 기분이 좋았고 메뉴도 선택의 폭이 넓어서 고르는 재미가 있었네요! 커플로 온다면 메뉴 2개 음료 1개 추천입니다 ㅎㅎ 한강선셋 티에이드가 특히 맛나네용^^', 16, 8, 'GOOD', SYSTIMESTAMP);
