INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '두번째 방문입니다! 카페가 인테리어가 너무 이뻐서 기억에 남아 재방문 했어요 식물이 많아서 힐링되고 분위기가 너무 좋아요 커피도 맛있고 다음엔 파스타 먹으러 와야겠어요~😊 #합정맛집#합정카페#어반플랜트합정', 50, 1, 'GOOD', SYSTIMESTAMP);
