INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '시그니처 음료 한강선셋 티~~~ 맛좋고 추천합니다 카페 인테리어 만족도 상타치에 브런치도 맛있어 보이네요 다음에 밥먹으로 올게요!:) #어반플랜트 #합정맛집', 77, 17, 'GOOD', SYSTIMESTAMP);
