INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '지인들과 분위기좋은 식당을 찾다가 발견해서 왔어요! 숲속에서 맛있는 양식을 먹으니까 기분이 좋더라구요! 합정에 오신다면 꼭 여기 들리세요! 직원분들도 친절해서 대접받는 느낌이에요 합정 맛집! 어반플랜트!', 31, 4, 'GOOD', SYSTIMESTAMP);
