INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '친구랑 점심 먹고 들른 카페인데, 실내가 푸릇푸릇해서 교외 나온 것 같네요. 말차 티라미수도 맛있고요, 편하게 수다 떨기 좋았습니다. 강추  합정맛집!!', 9, 5, 'GOOD', SYSTIMESTAMP);
