INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '지나가다가 멋진 곳이 있어서 지나치지 못하고 들어와 버렸습니다. 합정 맛집 핫플레이스로 원래 이름은 알고있었어요. 입구 들어올때부터 꽃향기가 엄청 좋아요.  친구들이랑 처음 봤는데 들어오자마자 아지트로 삼겠다고 결심했습니다. 내부에도 식물이 가득하고 디저트도 근사하고 커피향도 매우 좋아요. 다음에 5번 더 오고 싶어요. 2층도 있습니다.', 24, 0, 'GOOD', SYSTIMESTAMP);
