INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '친구들 만나러 합정맛집 어반플랜트를 왔는데 너무 좋네요. 음식이 맛있어요. 아메리카노도 맛있었구요. 데이트 장소로도 좋을것 같아요~~', 76, 18, 'GOOD', SYSTIMESTAMP);
