INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '바질깻잎 파스타 향이 너무 좋고 맛있어요! 샐러드랑 샌드위치도 다 맛있어서 싹다 비워서 먹고 갑니다! 식물이 가득해서 정원에서 밥 먹는 것 같아서 싱그러웠습니다🌱#합정맛집', 46, 4, 'GOOD', SYSTIMESTAMP);
