INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '식물과 커피가 좋아서 찾아왔어요. 인테리어가 너무 이쁘고 집에서 기르지 못하는 희귀식물들을 실컷 볼수있어 너무 좋아요. 행복한 시간 보내고 갑니다.^^ #합정맛집', 98, 23, 'GOOD', SYSTIMESTAMP);
