INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '제가 정말 좋아하는 분위기인데 이렇게 좋은 장소가 있는줄 몰랐네요. 주변에 나무가 가득하고 쉬러 오기 좋은 공간입니다. [합정맛집]', 42, 0, 'GOOD', SYSTIMESTAMP);
