INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '메뉴 종류가 많지 않지만 파스타 샐러드 모두 넘 맛있어요. 합정역에서 가깝고 입구 들어서는 순간 숲에 온 것 같은 기분에   녹색식물 덕에 힐링이 됩니다. 차분하게 대화하면서 식사나 음료 마시기 좋은  것 같아요. 일요일 1시30분에 왔는데 김치라구볼로제네 재료소진으로 못먹었지만ㅠ 크리미 로제 파스타도 넘 맛있었어요. 다음에 일찍 다시 오기로~!', 77, 14, 'GOOD', SYSTIMESTAMP);
