INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '지하랑 2층까지 있어서 좌석이 많아서 좋습니당 식물로 가득찬 공간이라서 햇살 내리쨀 때 넘 예뻐요 사진 찍기 좋아요ㅎㅎ 음료도 파인애플에이드랑 메이플커피 마셨는데 둘다 괜찮았습니다~~!데이트하기에도 좋은거같아요!!새로 발견한 합정맛집입니다!!👍', 52, 16, 'GOOD', SYSTIMESTAMP);
