INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '첫방문인데 각종 식물들과 인테리어에 너무 기분전환&힐링하고 갑니다. 음료랑 샌드위치도 맛있게 먹느라 사진찍는 걸 잊었네요. 다음에 다른 브런치 메뉴 먹어보러 재방문 하고 싶어요~~ 합정 맛집입니다!', 17, 2, 'GOOD', SYSTIMESTAMP);
