INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '브런치를 먹으면서 이런 식물들을 볼수있는곳이 없는데 어반플랜트는 맛도 너무 맛있고 뷰도 좋고 풀내음도 좋고 맛과멋 둘다 가져갈수있는 브런치 맛집이에요!! 합정브런치 찾으신다면 합정맛집 어반플랜트 추천합니다!', 66, 18, 'GOOD', SYSTIMESTAMP);
