INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '들어올때부터  우와~~ 하면서  왔는데 음식까지 완벽해요.   페스토맛집~~~ 싹싹  긁어먹게되네요.  조만간  또  모임하고  먹으러  와야겠어요 .#합정맛집', 85, 13, NULL, SYSTIMESTAMP);
