INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '가고싶은 곳으로 저장해뒀는데 드디어 와보네요🥹 내부, 테라스 모두 식물로 가득 채워져서 자연 그 자체🌿 날도 풀려서 테라스에 앉아있는 것만으로도 힐링이에요! 여름엔 좀 더울 수도 있겠지만.. 천장으로 들어오는 빛이 너무 좋았어요✨ 브런치 맛집, 합정 맛집으로 유명해서 파스타나 샌드위치를 먹어보고 싶었는데 점심 먹고 카페로 온 거라 간단하게☕️🍰 티라미수가 진짜 촉촉해요!! 느끼하거나 달지 않고 딱 좋아서.. 진짜로 이정도 티라미수는 제 기준 세손가락안에 듭니다👍🏻👍🏻👍🏻 아인슈페너, 플랫화이트 둘다 맛있어용 아인슈페너 크림은 되직한 편이고 시나몬 가루가 올라가요! 느끼하거나 겉돌지 않아서 좋았어요 하지만 티라미수와의 조합으로는 역시 플랫화이트가 더.. ㅎㅎ 아이스인데도 밍밍하지 않아요🧊 담엔 꼭 브런치 먹으러!!', 34, 1, 'GOOD', SYSTIMESTAMP);
