INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '합정 너무너뮤 예쁜 플랜트카페!!! 인테리어 진짜 이쁘고 카페 메뉴들도 나무나무 좋다!! 라떼 맛있고, 티라미수도 너뮤 맛있는데 식물 가득한 인테리어가 진짜 대박적!!! 연인이랑, 가족이랑, 친구 누구와도 방문해도 힐링되는 공간!! 합정 맛집으로 강추합니다 !!', 0, 5, 'GOOD', SYSTIMESTAMP);
