INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '오늘 처음 방문 했습니다. 오렌지 부라타 샐러드 비쥬얼과 맛 모두 상큼 했고 기분 좋았습니다! 그리고 음료도 신선하고 분위기도 정원 같은 쾌적함과 아늑함이 좋네요! 합정맛집으로 완전 추천합니다! #합정맛집', 24, 10, 'GOOD', SYSTIMESTAMP);
