INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '두번째 방문 나주에서 칭구가 와서 식사후 한참 걸어서 왔지만 입구부터 좋은 내음이 ~~ 생자몽 쥬스 맛있네요 음악도 좋고 직원들도 엄청 친절하시네요 재방문의사 있어용^^', 12, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '식물이 많아서 숲 속에 있는 기분이예요. 음식도 맛있고  커피 향이 너무 좋아서 기분 좋게 있다가 갑니다. 무엇보다 직원분들이 너무 친절해요. 두 번째 방문인데 역시 합정 맛집입니다!!', 165, 82, 'GOOD', SYSTIMESTAMP);
