INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '친구들이랑 여행 계획짜려고 모였어요! 인테리어도 너무 예쁘고 향기도 좋고 너무 잘 있다 갑니다:) 다음에 또 올게요!#합정맛집', 4, 5, 'GOOD', SYSTIMESTAMP);
