INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '#합정맛집 어반플랜트! 공간도 너무 예뻐서 여름에 인생샷 찍으러 오기 참 좋은 카페!!이자 맛집이에여 ㅎㅎ 친구들이란 스터디 할 때 와서 음료랑 브런치 시키기도 좋고 티라미수가 진짜 맛있어요..ㅜㅜ 데이트 하기도 넘 좋을 것 같아요 화장실도 깔끔하고 직원분들도 완전 친절하세요 ㅎㅎ 근방에 넘어갈 저녁 먹기 좋은 술집도 많아서 위치도 완전 좋습니다! ㅎㅎ 😍😍 1n번째 방문이에요 ㅎㅎ', 37, 5, 'GOOD', SYSTIMESTAMP);
