INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '마차 디저트를 좋아해서 검색하다가 인테리어가 특이해서 한 번 들어와봤는데 합정역이랑 가까워서 이동도 편하고 디저트랑 라떼도 정말 맛있었어요ㅎㅎ 합정 맛집으로 추천합니당🥰', 32, 2, 'GOOD', SYSTIMESTAMP);
