INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '좌석이 정말 많고 분위기가 정말 좋아요 연인끼리 오면 아주 좋을거같아요 !! 조용히 대화할수있는 곳도 있고 조금 떠들수있는 공간도 있고 지하도 있고 단체석도 있어서 이용하기 편한거 같습니다 인테리어가 정말 예뻐용 ㅎㅎ 합정역 맛집입니당 !', 65, 16, 'GOOD', SYSTIMESTAMP);
