INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '식물원에 온 것마냥 초록초록하고 분위기도 좋고 무엇보다 그렇게 시끄럽지않고 조용해서 혼자 오기도 좋아요 재방문의사있습니다 #합정맛집', 51, 12, 'GOOD', SYSTIMESTAMP);
