INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '합정에서 카페 하면 바로 떠오르는 곳 어반플랜트 자연의 냄새에 묻혀 커피와 차를 마시며 함께 시간을 보내는 이 시간은 참 특별한 공간이기에 그렇지 않을까? #합정맛집', 14, 0, 'GOOD', SYSTIMESTAMP);
