INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '홍대-합정 안에서 분위기 좋은 카페 3위 안에는 무조건 들어갑니다. 처음에 외국인 친구 서울 탐방 시켜줄 때 데려왔다가, 두번째 방문 때는 혼자 왔어요. 연인/지인 만남 자리로 추천합니다 작업하러 오시는 분들은 지하에서 콘센트 사용하시면 되어요. 보통 카페 지하는 냄새가 꿉꿉해서 잘 안 들어가는데 여긴 식물이 하도 많아서 향기로워요ㅎㅎ [장점] - 바닐라 라떼 기준 음료 사이즈가 스타벅스 벤티 사이즈와 맞먹음 - 공간이 넓어서 자리 고르기 좋음 - 식사와 음료를 한번애 해결 가능 - 스태프가 친절함', 41, 4, 'GOOD', SYSTIMESTAMP);
