INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '급하게 찾아서 방문한 어반플랜트😌 많은 식물이 저를 반겨주어 기분이 좋아요🩷 음식도 맛있고 분위기 아주 nice 집과 멀지만 재방문 의사있어용 #합정맛집 #어반플랜트 합정', 130, 21, 'GOOD', SYSTIMESTAMP);
