INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '어반플랜트 합정 분위기좋아요. 저번에는 친구랑 낮에 방문했었는데 그때 분위기랑 다른 색다른 느낌이 나는 주말저녁 플랜트입니다. 케잌이 수제이라 단맛이 은은하고 맛있어요. 입구부터 식물의 피톤치드 향이 진짜진짜 좋아요!! 강추입니다!', 40, 6, 'GOOD', SYSTIMESTAMP);
