INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '아이스바닐라라떼랑 티라미수 먹었어요. 티라미수가 컵에 담겨져서 나와서 안 흘리고 먹을 수 있고 매장 컨셉이 식물이 많아서 뭔가 자연속에서 커피 마시는 느낌이었습니다. 복층이고 넓어서 일행과 오랜시간 이야기 하기 좋아요.', 38, 6, 'GOOD', SYSTIMESTAMP);
