INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '#합정맛집 #걸스데이 들어가자마자 넘 예뻐서 반했습니당🪴💐🌷🍋🍊🍓 식물 과일 뷰도 예쁘고 엄청 맛있다구 핫플이라고 소문나서 재방문하는 지인들 따라 왔습니당🍒 근데 웨이팅도 없구 매장이 넓어서 바로 입장이라 햅삐🌸 소중한 사람들이랑 추억 쌓아서 좋아용❣️', 33, 10, 'GOOD', SYSTIMESTAMP);
