INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '미팅할 때나 혼자 작업할 때 종종 오는 까페입니다. 식물이 한가득 있어서 도시에서 벗어나고 싶을 때 찾아요. 식물 좋아하시는 분, 특색 있는 공간에 관심 있는 분들에게 추천해서 실패한 적이 없는 곳입니다. #합정 #합정맛집 #합정까페 #식물 #식물까페 #어반플랜트', 51, 14, 'GOOD', SYSTIMESTAMP);
