INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '오랜만에 나들이인데 풀들이 한가득인 공간에서 맛있는 브런치 너무너무 좋았습니다 :) 어반플랜트 합정은 처음 방문해보는데 남친이랑도 데이트 와봐야겠어요!! 합정맛집입니당!! 좋은 시간 보내다 갑니다 🥰', 65, 11, 'GOOD', SYSTIMESTAMP);
