INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '어빈플랜트에 처음 방문했는데 식물 인테리어가 아니라 진짜 정글에 온 것 같았어요! 저는 어쩌다보니 비오는 날 아침에 커피 마시러 왔는데 더 좋았습니다ㅎㅎ 초록 가득한 생기를 얻어가는 느낌이고 직원분들도 정말 친절하셨어요 💛 자연과 브라질 음악 좋아하시는 분들 서울에서 좋은 에너지 얻고 가세요 🌞🌴 #합정카페 #합정맛집', 59, 13, 'GOOD', SYSTIMESTAMP);
