INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '합정에서 식물원을 느끼고 싶은 카페에 오고 싶다면 여기에요!!!합정에 오면 자주 오게 되는 합정맛집카페에요!! 근교갈 필요없이 도심 속 자연자연~', 103, 20, 'GOOD', SYSTIMESTAMP);
