INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '가족끼리 담소 나누러 들렀다가 로제와인 마시며 좋은 시간 보냈어요~~ 여러번 방문 했는데 메뉴가 종종 바뀌는 데 다 맛이 좋네요^^ 누굴 데려와도 기분 좋은 만남 가능합니다. 합정 맛집 추천합니다~', 33, 3, 'GOOD', SYSTIMESTAMP);
