INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '합정역에서 살짝 떨어져 있지만 가격으로 보상받는 느낌?! 날씨가 추워서 내부는 추운편 이었고, 직원들이 매우 친절해요! 지인과 연인과, 가족과 오는거 추천!! 지하 자리도 있고, 2층도 , 야외도~ 넓고 쾌적하고 좋아요! 식사 후 다른카페 가려다가 자리만 옮겨 더 즐기다가 갔어요^^ 또 오고 싶은 브런치카페네요~~^^ 메뉴는 크림파스타, 토마토파스타, 치킨 샌드위치 먹었고, 파스타 소스가 비슷한 맛 나는게 있고, 둘이 섞어 로제맛으로 먹어보기도 했어요! 굿굿!! 논 커피는 파인애플주스, 파인애플 에이드 먹었어요. 주스 강추!!! 비타500같이 넣어먹으면  색감쨍해지고 맛도 굿!!! #합정#합정역브런치카페#합정역맛집#합정어반플랜트', 273, 95, 'GOOD', SYSTIMESTAMP);
