INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '친구들과 지나가다가 우연히 초록초록한 느낌에 끌려 방뭉했습니다! 반갑게 인사해주시고 다양한 식물들로 꾸며져있어서 힐링할 서 있었습니다:) 커피도 맛있고 장소가 커서 친구들과 편하게 이야기 나눌 수 있어 좋았습니다..! #합정맛집', 18, 8, 'GOOD', SYSTIMESTAMP);
