INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '매장 내부에 다양한 식물들이 있어서 향도 좋고 분위기도 너무 좋았어요~ 거기다가 직원분들이 다 친절하시고 텐션도 좋아서 대접받는 느낌을 받았답니당😛 합정오시면 꼭 들르시면 좋을 것 같아요💗 합정맛집', 75, 15, 'GOOD', SYSTIMESTAMP);
