INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '커피도 맛있고 샌드위치 샐러드도 가격대비 만족도가 높아요 인테리어는 완전 힐링되는 분위기라 초록초록한 분위기에서 스트레스 다 날라가네요~ 합정에서 데이트 친구랑 모든 목적에 부합하는 곳으로 추천합니다~', 0, 5, 'GOOD', SYSTIMESTAMP);
