INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '와 매장이 너무 멋져요 제가 식물을 키우고 있어서 기대하고 갔는데 분위기도 멋지고 직원들도 친절하고 자리도 넓직해서 만족스럽네요 아직 음식이 안 나와서 맛 리뷰는 못 쓰지만 분위기만으로도 가볼만 하다고 생각해요~!', 43, 9, 'GOOD', SYSTIMESTAMP);
