INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '몇 년째 다니고 있는데 얼마 전 메뉴가 약간 바뀌었어요. 오믈렛이 사라진 건 슬프지만 그래도 여전히 정말 맛있고 무엇보다 분위기가 좋음! 식물이 많은데도 벌레 관리가 잘되고 직원분들도 친절하심. 깻잎 파스타 추천합니다.', 60, 11, 'GOOD', SYSTIMESTAMP);
