INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '왜 이제 왔을까요…진짜 너무 맛있고 너무 친절하고 모든게 다 완벽합니다.. 인기 많은곳은 역시 이유가 있네요! 조만간 또 오겠습니다!!!!', 108, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '입구에 들어서면서 상쾌한 식물향으로 기분이 업되어어요^^라테와 자몽주스와 부라타샌드위치를 주문했는데 너무 귀엽운 라테아트가 나왔어요~음료도 조았지만 샌드위치 맛이 넘넘 좋아요~~~입맛없다하고 남깁없이 싹싹 다 먹었네여', 31, 10, 'GOOD', SYSTIMESTAMP);
