INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '초록 기운 얻고싶어 왔는데 완전 초록초록에 분위기 넘 좋아요! 2층 1층 지하까지 각 컨셉이 달라서 데이트로 강추~ 음식도 넘 맛나네여 !!! 꾸덕 크림파스타 먹구싶어서 시켰는데 살짝 매콤도 하고 ㅎㅎ 강추추~ 사장님 완전 매너굿 넘 친절ㅎㅏ시고 먹고나니 식물까지 🍀 집가서 잘 키우께용 진짜 합정맛집인정👍🏻', 24, 3, 'GOOD', SYSTIMESTAMP);
