INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '데이트 장소로 너무 좋고 직원 분들도 친절하시고 좋았어요! 대기가 많아서 바쁘셨음에도 불구하고 다 챙겨주시려 노력해주셔서 정말 감사했습니다! 힘드셨을텐데 밝게 끝까지 챙겨주셔서 덕분에 좋은 시간과 하루 보내고 갑니다🥰🌸', 28, 1, 'GOOD', SYSTIMESTAMP);
