INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '주말인데도 대기 없이 바로 들어갔어요! 직원분들이 친절하시고 테이블도 바로바로 치워주시고 음식도 빨리 나와요! 전부 맛있었고 빵도 쫄깃해요! 채소가 엄청 신선합니당!! 자연에사 밥먹는 기분이라 나들이 나온 것 같고 기분 좋네용😀 합정 맛집 발견!!', 9, 5, 'GOOD', SYSTIMESTAMP);
