INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '식물이 가득한 공간이라 분위기부터 너무 힐링됐어요. 깻잎파스타는 향긋하면서도 깔끔해서 생각보다 훨씬 맛있었고, 면도 알맞게 삶아져서 식감도 좋았습니다. 직원분들도 친절해서 기분 좋게 식사하고 왔어요. 합정에서 꼭 다시 오고 싶은 곳이에요! 🌿✨', 84, 17, 'GOOD', SYSTIMESTAMP);
