INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '늘 찾는 합정 맛집 식당이예용! 몇년 가봐도 메뉴 늘 바뀌고 항상 맛있고 친구들이랑 와도 대화 하기 좋고 ㅎㅎ 분위기 너무 좋아요!', 37, 10, 'GOOD', SYSTIMESTAMP);
