INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '커피도 맛있고 분위기 너무 좋은 합정 맛집이에요♥♥♥여기 들어오면 냄새 자체가 완전 식물원 냄새가 나서 힐링이에요! 합정 올 때마다 오고 싶은 카페...식물 덕후한테는 완전 추천입니다:)', 38, 8, 'GOOD', SYSTIMESTAMP);
