INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '합정 오면 꼭 오는 식물 카페에요! N번째 방문인데 특히 식물들이 많아서 여름에 방문하면 청량하고 시원한 느낌이 좋네요. 특유의 카페 분위기와 향이 좋아요! #합정맛집 #합정카페 #식물카페', 105, 19, 'GOOD', SYSTIMESTAMP);
