INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '합정오면 항상 들려보게 되는 까페예요! 자연 속에 들어온 느낌이 들도록 조성된 식물들 덕분에 힐링도 하고 맛있는 음료 마시며 수다떨 수 있는 곳입니다! 합정맛집 까페로 친구와 또는 연인과 함께 오시는 거 추천드려요👍', 49, 8, 'GOOD', SYSTIMESTAMP);
