INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '음식 퀄리티가 진짜 좋아요 ! 깻잎파스타도 향이 은은하게 맛있고, 토마토파스타는 일반 파스타에서 업그레이드 버전인거 같아요 :) 샌드위치도 크고 같이 나오는 감자튀김 샐러드까지 👍👍 식당도 넓고 ~~ 비오니 후두두둑 빗방울까지 분위기가 좋네요 ❤️', 4, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '분위기 너무 좋고 예뻐요~~!! 매장 향도 너무 좋고 기분 좋아지는 곳이에여 ㅎㅎ 합정에서 유명하다고해서 왔는데 합정 맛집 핫플 맞네요!!!', 84, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '틀림없이 합정맛집! 입니다~~~~지인분 맛집 추천으로 왔는데!!너무 의외로 아늑하고 스파게티 너무 맛있어서!!! 식후 커피도 여기서 마시기로 함요!!! 다음번 가족하고도 또 다시 와야지 싶네요. 아들도 좋아할것 같아요', 25, 0, 'GOOD', SYSTIMESTAMP);
