INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '음식도 맛있고 인테리어도 푸릇푸릇하니 너무 이쁩니당!!!눈이 정화되는 느낌이에요 ㅎㅎ다음에 또 방문할게요!합정맛집으로 추천드립니다👍🏻', 92, 23, 'GOOD', SYSTIMESTAMP);
