INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '지나가다가 발견해서 들어왔는데..! 너무 이뻐요!!! 카페가! 식물이 많아서 온실에 들어온기분! 넓어서 아늑하거 저희끼리 있을수있게 공간들이 많이 분리되있어서 너무좋았어요!! 커피도 맛있어요! 합정맛집이에요 밥을먹고와서 다음엔 브런치 먹어볼께요~~', 39, 10, 'GOOD', SYSTIMESTAMP);
