INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '합정, 홍대 쪽에 나오면 들르는 곳이에요. 식물 좋아하는 분들은 여기 엄청 좋아할 거예요 ㅋ 인테리어 멋지고 커피도 무난하게 마실만해요 지인들 데리고 오면 좋은데 데려와줘서 고맙다고 할거예요 합정맛집', 31, 10, 'GOOD', SYSTIMESTAMP);
