INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '근처 애견병원 욌다가  강뒤데리고 브런치카페 찾아 왔는데 와~~~~ㅎㅎ 식물인테리어기 코끝을 찌르며 신선한 냄새로 맞아주는 어반플랜트 합정~^^♡♡♡ 블로그 리뷰와 사진이  좋아보여 방문했는데 역쉬 ~~ 기대를 져버리지않네요 ㅎㅎ #합정맛집 음식도 맛나고.분위기도 좋고 우리강쥐 입장도 가능하고 ㅎㅎ 저는 재방문의사 200프로 입니다용 ㅎㅎ', 10, 0, 'GOOD', SYSTIMESTAMP);
