INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '숲속에  들어온듯  상쾌하고  멋진 공간입니다 인테리어도  예쁘고  직원분들도 친절하시고  커피도  맛있네요 공간도  여유롭고 복잡하지않아  여유롭게 쉬다갑니다', 30, 7, 'GOOD', SYSTIMESTAMP);
