INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '가끔 브런치를 먹으러 오는 곳인데 오늘은 산책길에 차 마시러 들렀어요. 숲속에 온 듯 청량한 느낌이 늘 기분 좋게 하는 곳입니다. 커피도 맛있습니다. ^^ 합정맛집', 77, 15, 'GOOD', SYSTIMESTAMP);
