INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '커피도 맛있는데 무엇보다 붕위기가 넘 좋아용 ㅠㅠ 식물들이 많은 카페인데 느좋 그자체!! 합정 맛집으로 추천합니당 #합정맛집 #커피맛딥 #느좋', 15, 2, 'GOOD', SYSTIMESTAMP);
