INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '합정에서 커피 마시려고 미리 검색해보고 왔는데 식물을 좋아해서 그런가 인테리어가 너무 이쁘고 도심속이 아닌 것 같은 느낌이 좋았어요~! 2층 테라스는 날이 좋아그런가 식물들 사이로 채광이 너무 좋은데 분위기가 너무 좋네요 다음엔 점심 먹으러 와봐야 겠어요😊 #합정 #합정역맛집 #합정어반플랜트 #합정카페', 2, 2, 'GOOD', SYSTIMESTAMP);
