INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '매장 밖에서부터 장미향에 끌려 들어왔어요 ! 저녁 메뉴 고민이로 길에서 방황 중이었는데 즉흥적으로 들어온 곳에서 너무 만족스러운 식사를 했습니다 😋 매장 분위기가 잔잔하니 푸른 제주도에서 즐기고 있는 느낌도 들고 가끔 힐링하고 싶을 때 오면 좋은 카페예요 !☺️🌳 다음에 또 방문하러 올게요 ! #합정맛집', 1, 4, 'GOOD', SYSTIMESTAMP);
