INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '뷰 미쳤쭁 이전엔 커피만 마시러 왔었는데 파스타도 맛있꼬 식물도 많아서 기관지가 좋아지는 느낌 ㅋㅎㅎ 시간이 일찍이었는데도 손님분들이 꽤나 계셨어요~! 다음에도 피크 시간대 피해서 잘 와야징 #합정맛집', 3, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '합정 맛집 찾다가 알게 된 곳이예요! 카페이면서 다이너인데 메뉴가 엄청 다양해서 식사랑 디저트, 커피까지 다 해결할 수 있어서 좋았어요. 도심 한가운데 실내 식물원 느낌이라 기분전환하기 좋을 것 같아요! 합정 맛집 찾는 분들 한번씩 방문해보세요.', 50, 0, 'GOOD', SYSTIMESTAMP);
