INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '#합정역 맛집 근처 가게에서 식사하다가 손님분들이 이 가게 너무 괜찮다고 언급하셔서 찾아왔어요! 식물을 좋아하는데 입구부터 신선하고 향긋한 냄새가 나서 너무 좋았고 내부도 식물로 가득차서 좋았어요 리뷰보고 말차라떼랑 티라미수 시켰는데 둘 다 너무 만족스러웠습니다. 전 주변에 커플분들이 많아서 약간 힘들었지만 힐링하고 싶을 때 방문하면 너무 좋을 것 같아요', 12, 9, 'GOOD', SYSTIMESTAMP);
