INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '예쁘게 생긴 인테리어와 친절하신 직원분이 계십니다. 서울에서 보기힘든 인테리어라도 생각합니다. 내부 식물관리도 뛰어나게 잘 되어있어요. 즐거운시간 보내며 식물 향을 맡으니 매우 즐거운 시간이었습니다. 합정 맛집중에 최고입니다.', 49, 10, 'GOOD', SYSTIMESTAMP);
