INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '합정동 대형 카페를 검색하다가 초록초록한 분위기에 끌려 찾아간 곳인데, 입구부터 라일락 향기가 가득 퍼져 기분이 참 좋았어요. 생각보다 넓은 공간 곳곳에 식물들이 가득해 어디에 앉아도 분위기가 좋았어요. 커피도 맛있었고, “다음에 또 오자!” 하며 사진도 많이 찍고 수다도 한참 떨다 왔어요.', 24, 1, 'GOOD', SYSTIMESTAMP);
