INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '합정역에 일이 있어 갔다가 역근처 맛집 검색을 하고 간 곳인데 가성비 좋아요.합정역에 커피집은 많은데 브런치 하기 좋은 편안한 곳은 딱히 없는데 어반플랜트 여러모로 괜찮았어요. 특히 친절하고 인사도 크게 해주셔서 좋았어요. 한남점도 있다니 그 곳에 가봐야겠어요~', 99, 24, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '인테리어, 분위기 진짜 너무 예뻐요.! 낮에도 예쁘지만 밤에는 더 분위기 있어서 데이트할 때 좋을 것 같아요🫢 깻잎페스토 파스타 시그니처 같은데 진짜 맛도리구 부라타 프로슈토 샌드위치도 진짜 맛잇어요..💗💗', 148, 30, 'GOOD', SYSTIMESTAMP);
