INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '배고파서   들어가  봤더니 이게   모지??   맨  처음에는  아마존인줄ㅋ  알고보니 식당  좋아서  식사  했더니   강아지 🐶 가   꼬리를  살랑살랑 흔들고  있음   반려동물  대리고  오기  딱  좋음  날씨   좋을때  오면  따봉👍   오늘도 맛집  오기 성공!!🥰 합정 맛집 ♡♡', 16, 8, 'GOOD', SYSTIMESTAMP);
