INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '식물 애호가라면 꼭 들러야 할 공간! 합정에서 우연히 들른 어반플랜트, 분위기부터 감성 가득한 공간이에요. 매장 안은 식물로 가득 차 있고, 상태도 정말 건강하고 잘 관리되어 있었어요. 잎이 반짝이고 힘이 넘쳐서 보기만 해도 기분이 좋아집니다. 조명, 화분, 작은 가드닝 소품들도 다양해서 구경하는 재미도 쏠쏠했습니다. 합정 맛집 놀러 갔다가 힐링하고 돌아왔어요. 또 방문할게요!', 46, 1, 'GOOD', SYSTIMESTAMP);
