INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '지나가다가 들어왔는데 들어오자마자 너무 향기로운 식물향때문에 힐링이였습니다ㅠㅠ 커피도 맛있도 분위기도ㅠ너무 좋아서 또오고싶어요! #합정맛집', 30, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '비오는날 왔는데 풀냄새도 좋고 분위기도 겁나 좋아요 직원분들도 친절하셔서 기분좋게 왔다 갑니다! 다음에도 꼭 방문할게요 #합정맛집#합정카페', 20, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '브런치 먹으러 왔는데 메뉴가 다양하고 이색적이어서 넘 좋았어요 재료들도 모두 신선했고 분위기도 편안하니 데이트로도 좋았습니다 넘 넘 추천드려용🧡합정맛집🧡', 34, 8, 'GOOD', SYSTIMESTAMP);
