INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '검색해서 예뻐서 찾아왔는데 파릇파릇 공기도좋고 샐러드 파스타 모두 넘넘 맛있어요 엄마가 너무 좋아하심요^^ 담에 또 올게요!^^ #합정맛집', 18, 9, 'GOOD', SYSTIMESTAMP);
