INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '근처 미쉐린 라멘집에서 먹구 후식커피 마시러 온 곳~! 식물원, 온실같은 느낌에 따뜻하고 포근하고 인테리어가 돋보적인 곳ㅎㅎ보사노바 재즈가 흐르는 곳, 브런치집이지만 밥먹고 온 관계로 생과일쥬스랑 플렛화이트 맛나게 마시구 갑니다!^^', 27, 2, 'GOOD', SYSTIMESTAMP);
