INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '몇년전에 욌다가 생각이 나서 다시 왔는데 전보다 더 좋아진 것 같아요! 오늘은 강아지도 같이 왔는데 돌아다니지만 않으면 같이 있어도 된다고 하네요! 참고로 강아지는 15키로 중대형견 입니다. 평일 낮이지만 사람도 많고 분위기도 좋아서 데이트, 업무, 공부하기 좋은 것 같아요! #합정맛집 #합정카페 #반려동물동반', 20, 8, 'GOOD', SYSTIMESTAMP);
