INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '시그니처인 메뉴 그린플로우 시켜봤는데 딱 기분 좋은 달달함과 말차의 쌉싸름함이 조화로워서 맛있어요!! 비주얼도 비주얼인데 식사메뉴도 팔고 카페 메뉴도 팔아서 데이트 장소로 좋은 느낌 그리고 확실히 식물이 많아서 향기가 너무 좋아요!!! 곳곳에 나무가 있어서 수목원에서 힐링하는 느낌이에요 다들 시그니처 메뉴인 그린플로우 꼭 드세요 부드럽고 달콤쌉싸름한게 넘 맛있어요ㅜ', 12, 10, 'GOOD', SYSTIMESTAMP);
