INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '몸살기운에 너무 쳐져있었는데 큰소리의 인사와 분위기에 굉장히 기분전환이 잘 되었어요. 물론 메뉴도 너무 맛있었습니다 너무 잘먹고 갑니다😄 #합정맛집', 446, 94, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '세번째 방문입니다! 식물카페라 힐링되는것같아요! 티라미수 케익도 맛있고, 평일에 한적하니 여유롭게 즐기다 가는것같네용! 식물이 파릇파릇하니 기분좋아지네용! #합정역맛집', 26, 5, 'GOOD', SYSTIMESTAMP);
