INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '너무 맛있게 먹고갑니다~~ 깻잎 파스타, 어반 치킨 센드위치 주문해보았는데 음식도 빨리 나왔고 맛도 좋았고 분위기도 초록초록해서 눈과 마음도 힐링하면서 갑니다~~!! 다음에 지인들이랑 또 방문하러 올게요 ~~>.< #합정맛집', 48, 8, 'GOOD', SYSTIMESTAMP);
