INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '동생의 추천으로왔는데 분위도 넘 좋고 야외테라스에서 식물과함께 있으니 힐링되고 좋았어요. 커피맛 좋구 여럿이 모임장소로도 강추합니다. #합정맛집#합정핫플#어반플랜트', 0, 4, 'GOOD', SYSTIMESTAMP);
