INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '동생들과 함께 분위기 좋은 #합정 맛집 어반플랜트에서 즐거운 티타임 가지고 갑니다~^^ 음료도 맛있고 올때마다 넘 넘 좋아요~^^b', 12, 0, 'GOOD', SYSTIMESTAMP);
