INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '카페 이름이 예뻐서 처음 와봤는데 외관에서 분위기에 놀라고 들어가자마자 향기에 놀랐어요! 서울에 이런 곳이 있다니,, >(< 엄마 아빠도 데리고 올려구요! ㅎㅎ 직원들도 너무 친절해서 기분이 내내 좋았어요 또올게요~ #합정맛집 #합정역맛집 #합정카페 #분위기좋은', 10, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '들어갈때부터 기분좋은 향기가 나요 날씨 좋은 날 오니까 식물원 나들이 온 기분 🌿 공간도 넓고 어딜 가도 포토존.. 합정 맛집으로 추천합니다', 61, 17, 'GOOD', SYSTIMESTAMP);
