INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '어반플랜트 늘 와보고 싶었는데 지인이랑 오랜만에 만나는 자리에서 좋은 분위기에서 이야기도 하기 너무 좋아요! 맛있게 잘 먹었습니다💕 #합정맛집 #홍대맛집 #어반플랜트', 7, 6, 'GOOD', SYSTIMESTAMP);
