INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '합정역 저녁 식사 하러 왔다가 우연히 친구들하고 들렸는데 들어오자마자 꽃이랑 식물향기가 잔뜩나서 너무 좋았어용💚식물원 온 기분이랄까요 ! 직원분들도 너무 친절하시구 친구들하고 너무 좋은 시간 보내고 갑니당😊🌷🍀', 27, 9, 'GOOD', SYSTIMESTAMP);
