INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '늦은 점심으로 오랜만에 쉬는날에 가족들이랑 왔는데 너무 좋네요 ㅎㅎㅎ 파스타도 샐러드도 커피도 너무 맛있어요 식집사분들 오시면 너무 행복하실만큼의 식물 너무 이쁘네요 #합정맛집', 23, 4, 'GOOD', SYSTIMESTAMP);
