INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '캐나다에서 온 친척과 함께 왔어요. 21개월 아기도 함께할 수 있었네요. 분위기 참 좋고, 음식도 맛있고, 식물로 가득해서 마음이 안정되었어요. 합정 맛집이네요!', 72, 13, 'GOOD', SYSTIMESTAMP);
