INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '들어오는데 풀향이 확 나는 힐링 카페입니다!! 커피랑 티라미수 너무 맛있고요ㅎㅎ 여기 브런치도 파는데 담에 꼭 먹어보려고요 :) 합정 맛집 카페로 추천입니다', 28, 10, 'GOOD', SYSTIMESTAMP);
