INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '합정 분위기 좋은 카페 찾다가 발견했어요 플랜테리어 관심많아서 찾아왔는데 플랜테리어를 넘어서 식물원같아요 풀이랑 나무향이 들어갈때부터 느껴집니다 식물 분위기 좋아하시면 진짜진짜진짜 강추입니다~~!! 분위기만으로도 계속 방문하고싶은곳! #합정맛집', 363, 32, 'GOOD', SYSTIMESTAMP);
