INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '합정 맛집으로 완전 추천이에요! 식물로 가득찬 향 속에서 여유롭게 대화하고 식사하기 좋아요! 두번째 방문인데 종종 오고싶은 곳이에요 🍀🌿', 109, 19, 'GOOD', SYSTIMESTAMP);
