INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '음료도 맛있고 분위기가 너무 좋아요 특히 은은하게 나는 향긋한 꽃내음이 매력있어요 보통 이런 감성카페는 음료 퀄리티가 별로거나 불친절할 수 있는게 이곳은 음료도 맛있고 서비스도 좋아서 만족스럽게 시간을 보냈어요', 38, 5, 'GOOD', SYSTIMESTAMP);
