INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '여기 분위기도 좋고 메뉴들도 다양하고 맛있어요 진짜 합정 맛집이에요!!치킨 파스타랑 부라타 프로슈 먹었는데 추천해요!! 좋아하는 사람들과 좋은 시간 보내고 갑니당🥰', 80, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '너무너무 예쁜 카페…! 입구에서부터 꽃향기가 엄청 나요!!  식물원인지 카페인지..🍀 음식도 맛있고 커피도 괜찮아요ㅠ 사진찍기도 너무 좋아요 합정맛집으로 추천드려용', 25, 7, 'GOOD', SYSTIMESTAMP);
