INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '합정에 오면 꼭 들려야하는 카페! 시그니처 메뉴랑 티라미수 먹었는데 너무 맛있어요 식물이 많아서 공기가 깨끗한 곳에서 좋은 시간 보냈어요 재방문 의사 100% 합정맛집', 59, 12, 'GOOD', SYSTIMESTAMP);
