INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '분위기도 너무 좋고 음료도 너무 맛있어요! 친구랑 대화하기도 너무좋고 공부하기도 좋아요 다음에도 또 들리겠습니당!❤️ #합정맛집', 38, 6, 'GOOD', SYSTIMESTAMP);
