INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '네이버 지도로 카페를 검색한 곳들 중에 식물이 많은 사진을 보고 오게 되었는데 정말 매장 안에 들어오면 더 많고 건물이 많은 밖을 걷다 들어와서 그런지 정말 다른 곳에 온 듯해서 기분전환에 너무 좋은 것 같아요! 오늘은 이런 곳이 있는줄 모르고 밥을 먹고 음료를 마시러 왔지만 다음엔 식사하러도 오고 싶어요:) #합정맛집 #합정느좋', 84, 18, 'GOOD', SYSTIMESTAMP);
