INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '숲속에와있는것같은 초록초록한 식물카페 약간 빈티지한느낌과 잘어울리는 곳이네요 직원분들도 웃는얼굴로 친절히 대해주시고 움식도맛있네요', 1, 4, 'GOOD', SYSTIMESTAMP);
