INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '풍성한 식물 인테리어가 특별한 합정 맛집! 카프레제 샐러드는 신선한 야채와 상큼한 소스 때문에 항상 맛있게 먹는 메뉴예요. 깻잎 새우 파스타도 고소하니 특별한 맛입니다. 비오는 날, 향긋한 식물냄새 덕분에 좋은 시간 보내고 갑니다.', 21, 3, 'GOOD', SYSTIMESTAMP);
