INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '전에 친구랑 왔다가 오늘은 남편이랑! 올때마다 너무 좋은곳! 마음도 차분해지고, 식물친구들이 많아서 공기도 좋고~~ 🥰 합정 올때마다 방문 할게요!! #합정맛집 #데이트코스 #데이트 #인생맛집', 47, 2, 'GOOD', SYSTIMESTAMP);
