INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '일요일 오전 산책 겸 나들이 겸으로 방문했어요 분위기도 차분하고 알바분들도 친절하고 활기차셔서 들어오면서부터 기분 좋았네요ㅎㅎ 음식 음료 뭐 하나 빠지는거 없이 만족스럽습니다 그린플로우 대표 음료라서 주문했는데 대만족 자주 오고 싶어요 여기 오고 싶어서 연차쓸듯 히히', 21, 6, 'GOOD', SYSTIMESTAMP);
