INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '일요일 12시 기준 바로 입장할 수 있었어요~ 정말 식물이 가득한 공간이라 힐링이 되는거같아요! 파스타도 맛있습니다. 자리도 꽤 많고 넓어서 단체모임하기 좋을 거 같아요.', 74, 18, 'GOOD', SYSTIMESTAMP);
