INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '느좋카페,,, 솔직히 식물 많아서 벌레가 많지는 않을까 싶었는데 그런 것도 없고 쾌적해요! 테이블이 넓어서 공부하거나 뭐 먹기도 넘 좋습니당', 17, 5, 'GOOD', SYSTIMESTAMP);
