INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반플랜트 합정'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '음식도 맛있고 음료도 맛있어요😆 식물이 가득해서 봄 분위기 나고 좋네요🍀 합정맛집 추천드려요!! 분위기도 좋ㄱㅎ 자리도 많아서 이야기하러 오기 좋을거 같아요. 데이트도 좋고 친구들이랑 와도 좋을듯!!👍', 105, 26, 'GOOD', SYSTIMESTAMP);
