INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '록집'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '시그니처 록라떼 크림이 너무 맛있었어용~ 한 입 먹으면 "나야, 바질." 하고 은은하게 바질맛이 나서 너무 좋았어요!! 사장님도 친절하시고 인테리어도 정말 록집이라는 이름에 걸맞게 완전 락스타의 아지트 느낌이 들었어용 ㅎㅎ 상수역에서도 가깝고 닌텐도 wii도 가볍게 즐길 수 있어서 추억이 새록새록 피어나네용~^^', 116, 20, 'GOOD', SYSTIMESTAMP);
