INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '록집'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '어떻게 카페가 락스타??? 지나가면서 우연히 보게된, ㅋ ㅏ페.  이거는 절대로 들어가야한다.  시작은 혼자 사이키쿠스오 기분 느끼면서 커피젤리 움냠냠 먹으면서 커스터드파이를 먹다가 , 친구를 불렀습니다. 바아로 칵테일 시켰습니다. 엄청난 카페일줄만 알있는데 , 어째서 칵ㅌ ㅔ일조차 맛있단 말임..?? 자주가던 바에서 마시던 그맛,, 그냥 말이안돼요.인테리어도 사장님 하나하나 애정담아 멋드러지게 꾸며놓은게 넘무 느꺄집니다. 그리고 소파가 세개나 있어요!!!!!!!! 편한소파세개나ㅜㅜ 감격스럽습니다,,, 사장님,, 어디있다 이제야 나타나신 것...? 록집은 유명한 어쩌고임. 개큰감동,,, 그 자리 그대로 뿌리박고 오래 계셔요,,, (사장님 엔푸피 라 하셨는데, 혼자 바테이블 앉아도 즐거웟숨다,,)', 53, 11, 'GOOD', SYSTIMESTAMP);
