INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '록집'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '애플파이가 진짜 너무 너무 너무 맛있어요 . . . . . . 새벽이 되면 생각나는 맛이에요 꼭 데워서 드셔야합니다. 사장님과 알바분 모두 친절하십니다 인테리어도 이뻐용', 41, 6, 'GOOD', SYSTIMESTAMP);
