INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '록집'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '밤에 가기 좋은 카페를 발견했어요! 카페음료도, 술도 있어서 좋았습니다! 반지하라 밴드 합주실 분위기도 나고 둘이서 이야기 하기 좋은 공간이에요👍', 38, 4, NULL, SYSTIMESTAMP);
