INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '포크가 미리 세팅돼 있어 여럿이서 케이크 쉽게 나눠 먹을 수 있었어요. 음료마다 얼음이 넉넉하게 들어가서 한 입 마실 때마다 시원함이 바로 느껴졌고, 강렬한 민트 색감의 케이크가 대화 주제로 자연스럽게 이어졌네요. 전체적으로 단정하고 정돈된 느낌이 인상 깊었어요.', 20, 7, 'GOOD', SYSTIMESTAMP);
