INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '음료를 각자 고르니 취향대로 나눌 수 있어서 좋았어요. 민트오레오 치즈케이크가 선명한 색감 덕분에 시선이 먼저 가더라구요. 트레이랑 식기, 포크까지 정돈돼 있어 나눠 먹을 때 불편함 없었고 차분한 분위기에서 여유롭게 티타임 마무리할 수 있었습니다.', 17, 0, 'GOOD', SYSTIMESTAMP);
