INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '트레이 위에 케이크와 음료가 가지런히 놓여 시작부터 정돈된 느낌이 들었어요. 민트 케이크 단면이 깔끔하게 나뉘어 보기 좋았고, 조용한 분위기에서 여유롭게 쉴 수 있었네요. 진한 아이스 음료랑 디저트 조합도 만족스러웠어요.', 42, 4, 'GOOD', SYSTIMESTAMP);
