INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '트레이랑 식기가 정돈돼 있어서 시작부터 깔끔하게 느껴졌어요. 민트라떼랑 케이크 색감이 확실히 눈에 띄어서 한층 산뜻하게 다가왔고, 음료랑 디저트 조합이 자연스럽게 잘 어울려서 만족스럽게 즐길 수 있었네요.', 10, 6, 'GOOD', SYSTIMESTAMP);
