INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '트레이 위에 포크와 컵이 가지런하게 준비돼 있어서 시작부터 기분이 편안했어요. 민트색 케이크와 시원한 아이스 음료가 나란히 있으니 대화 나누며 천천히 즐기기에 딱 좋았습니다. 각 메뉴마다 개성 있는 색감이 조화로워서 여유롭게 쉬어가기 좋은 시간이었어요.', 22, 5, 'GOOD', SYSTIMESTAMP);
