INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '친구랑 나눠 먹으니 케이크 한 조각도 훨씬 재밌게 느껴졌어요. 민트색이 선명하게 보여서 상큼한 기분이 들었고, 음료랑 디저트 조합도 잘 맞았네요. 포크랑 식기 세팅이 깔끔하게 준비돼 있어 먹는 내내 편했어요. 트레이에 정돈된 모습까지 신경 쓴 느낌이라 전체적으로 만족스러웠습니다.', 39, 2, 'GOOD', SYSTIMESTAMP);
