INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '음료 준비된 모습이 한눈에 정돈되어 보여서 시작부터 마음이 편해졌어요. 얼음이 넉넉히 담겨 색감도 산뜻하게 느껴졌고, 한 모금 마시니 차가운 감각이 바로 전해졌네요. 테이블 세팅이 군더더기 없이 깔끔해서 전체적으로 기분 좋게 즐길 수 있었습니다.', 74, 13, 'GOOD', SYSTIMESTAMP);
