INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '테이블에 앉아 여유 있게 대화 나누기 좋았어요. 밝은 조명 아래 민트 케이크 플레이팅이 인상적이라 눈길이 갔고, 음료 조합 덕분에 입맛도 산뜻하게 전환됐습니다. 독특한 민트 디저트가 자연스럽게 대화거리가 되어 만족스러운 시간이었습니다.', 62, 13, 'GOOD', SYSTIMESTAMP);
