INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '각자 취향대로 음료 골라서 대화 시작이 자연스럽게 이어졌어요. 민트 케이크를 넉넉한 포크로 나눠 먹으니 다 같이 즐기기 편했고, 테이블 위에 시원한 얼음 음료가 놓여 있어서 분위기가 한층 상쾌하게 느껴졌네요. 세팅도 깔끔해서 전체적으로 만족스러운 시간이었어요.', 18, 9, 'GOOD', SYSTIMESTAMP);
