INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '원목 트레이에 케이크랑 음료가 정돈돼 있으니 시작부터 기분이 좋았어요. 민트초코퍼지 케이크 단면이 선명해서 한 입씩 나눠 먹기 좋았고, 민트라떼 밑부분에 층이 나뉘어 있어서 조합이 자연스럽게 어울렸어요. 전체적으로 군더더기 없이 깔끔하게 즐길 수 있는 구성이었네요.', 31, 10, 'GOOD', SYSTIMESTAMP);
