INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '민트 케이크 단면이 여러 겹으로 나뉘어 보여 한 입씩 떼어 먹는 재미가 있었어요. 시원한 민트 음료랑 같이 곁들이니 조화가 잘 느껴지더라고요. 포크와 식기가 깔끔하게 준비돼 있어서 전체적으로 단정한 느낌이 들었고, 자리에서 천천히 여유롭게 즐길 수 있었습니다.', 55, 15, 'GOOD', SYSTIMESTAMP);
