INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '민트 디저트마다 비주얼이 달라서 고르는 재미가 있었어요. 오레오 토핑이 올라가 식감이 한 번 더 느껴져서 좋았고, 여러 조각 나눠 먹으니 더 풍성하게 즐길 수 있었네요. 트레이에 깔끔하게 플레이팅된 덕분에 끝까지 기분 좋게 마무리했습니다.', 256, 75, 'GOOD', SYSTIMESTAMP);
