INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '테이블에 세팅된 음료랑 디저트가 정돈되어 보기도 편했어요. 민트색 케이크 위에 오레오가 올려져 있어서 시각적으로 재미있었고, 진한 아이스 음료랑 궁합도 만족스러웠습니다. 색감 덕분에 평소와는 다른 디저트 타임이 된 것 같아요.', 78, 15, 'GOOD', SYSTIMESTAMP);
