INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '두 가지 케이크가 각자 개성이 느껴져서 골라 먹는 재미가 있었어요. 민트 음료 위 토핑이 한 입마다 바삭해서 포크를 자주 들게 되네요. 트레이에 디저트와 음료가 정돈되어 있어 시작부터 편안하게 느껴졌고, 세련된 인테리어와도 잘 어울려서 전체적으로 만족스러웠어요.', 59, 14, 'GOOD', SYSTIMESTAMP);
