INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '트레이 위에 음료랑 케이크가 차분하게 정돈돼 있어서 시작부터 단정했어요. 각자 원하는 음료를 고를 수 있어 취향대로 즐기기 좋았고, 민트 케이크 특유의 청량한 색감이 눈에 잘 들어왔어요. 포크가 넉넉히 준비돼 있어 친구랑 한 조각씩 나눠 먹으니 디저트 시간이 더 편했네요.', 39, 1, 'GOOD', SYSTIMESTAMP);
