INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '원목 트레이에 케이크와 음료가 단정하게 놓여 시작부터 안정감이 느껴졌어요. 얼음이 넉넉하게 담긴 아이스 음료를 한 모금 마시니 바로 상쾌해졌고, 민트 케이크의 단면 색감도 눈길을 끌었네요. 간단하게 디저트 즐기며 기분 전환하기 좋았습니다.', 8, 10, 'GOOD', SYSTIMESTAMP);
