INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '민트 컬러랑 오레오 조합이 확실히 눈에 띄었어요. 트레이 위에 음료랑 케이크가 정돈돼 있으니 시작부터 깔끔하게 느껴졌고, 차가운 음료 덕분에 한결 시원하게 쉴 수 있었네요. 전체적으로 기분 좋게 머무를 수 있는 곳이었어요.', 31, 7, 'GOOD', SYSTIMESTAMP);
