INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '트레이 위에 음료랑 케이크가 깔끔하게 세팅돼서 시작부터 눈길이 갔어요. 민트 음료 특유의 초록빛이 진하게 대비돼서 테이블이 한층 산뜻해 보였고, 케이크 단면에 초코와 민트가 확실히 나뉘어서 시각적으로도 재미있었네요. 조용한 분위기에서 편하게 대화할 수 있어 만족스러웠어요.', 4, 3, 'GOOD', SYSTIMESTAMP);
