INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '민트오레오 치즈케이크 비주얼이 인상적이라 한눈에 들어왔어요. 아이스 음료랑 같이 곁들이니 조화가 잘 느껴졌고, 포크로 나눠 먹으니 대화도 자연스럽게 이어졌네요. 테이블 위 소품이 정돈돼 있어서 전체적으로 단정한 분위기였어요.', 121, 26, 'GOOD', SYSTIMESTAMP);
