INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '얼음이 잔뜩 들어간 음료로 시작하니 바로 시원함이 느껴지더라구요. 초콜릿 케이크 단면이 또렷하게 보여서 한 입씩 나눠 먹기에 좋았어요. 테이블 위 소품들이 정돈돼 있어서 전체적으로 정갈한 분위기로 즐길 수 있었네요. 깔끔하게 마무리되는 디저트 시간이었습니다.', 39, 7, 'GOOD', SYSTIMESTAMP);
