INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '케이크를 나눠 먹으면서 민트 색이 확실히 눈에 띄었어요. 얼음이 가득한 음료 덕분에 바로 시원함이 느껴졌고, 트레이도 정돈돼 있어서 전체적으로 깔끔한 인상이었습니다. 친구들이랑 담소 나누며 여유롭게 마무리하기에 딱 좋았네요.', 75, 16, 'GOOD', SYSTIMESTAMP);
