INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '민트 컬러가 확실히 눈에 띄어서 음료랑 디저트가 한눈에 들어왔어요. 간단하게 플레이팅돼 있어서 시작부터 부담 없이 즐길 수 있었고, 케이크 한입 하고 천천히 대화 나누니 시간 가는 줄 몰랐네요. 오래 앉아 있어도 분위기가 편안해서 또 들르고 싶어요.', 51, 11, 'GOOD', SYSTIMESTAMP);
