INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '메뉴 고르는 재미가 쏠쏠해서 친구들이랑 한참 얘기했어요. 민트 케이크 색감이 확실히 눈에 띄어서 자연스럽게 시선이 갔고, 음료도 각자 취향대로 골라 나눠 마시니 조합이 괜찮았네요. 테이블 세팅이 밝아서 전체적으로 분위기도 더 산뜻하게 느껴졌어요.', 19, 8, 'GOOD', SYSTIMESTAMP);
