INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '테이블에 앉아서 음료를 천천히 섞으니 색이 달라지는 모습이 눈에 들어왔어요. 얼음이 녹아갈 때 나는 소리 덕분에 한참 여유롭게 머물게 되더라구요. 민트랑 초코가 어우러진 조합이 한 모금씩 마실 때마다 색다르게 느껴졌어요.', 4, 3, 'GOOD', SYSTIMESTAMP);
