INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '얼음이 가득한 음료가 손에 닿자마자 바로 시원함이 느껴졌어요. 민트 케이크 한 조각이 독특하게 보여서 친구랑 나눠 먹기 좋았고, 트레이와 식기가 간결하게 세팅돼 있어서 전체적으로 깔끔하게 마무리됐네요. 소소하게 즐기기에 딱 좋았어요.', 84, 14, 'GOOD', SYSTIMESTAMP);
