INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '트레이 위에 음료와 케이크가 가지런히 놓여 있어서 세팅부터 정돈된 느낌이었어요. 민트초코 퍼지 케이크는 층마다 색감이 뚜렷해서 보는 재미도 있었고, 음료랑 같이 먹으니 달콤함이 잘 어우러졌네요. 잔에 그려진 캐릭터 덕분에 자연스럽게 대화가 이어졌고, 전체적으로 깔끔하게 마무리할 수 있었어요.', 125, 26, 'GOOD', SYSTIMESTAMP);
