INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '트레이 위에 컵, 포크, 냅킨까지 하나하나 정돈된 느낌이 눈에 들어왔어요. 민트초코 케이크와 음료 색감이 보기만 해도 확실히 독특하게 다가왔고, 여럿이 한 입씩 나눠 먹으니 메뉴 조합이 자연스럽게 어우러졌어요. 매장 인테리어랑 잘 어울려서 전체적으로 만족스러운 시간이었네요.', 87, 18, 'GOOD', SYSTIMESTAMP);
