INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '자리 잡고 앉아서 메뉴를 천천히 둘러보다가 민트오레오 치즈케이크랑 아이스 음료로 골랐어요. 케이크 단면이 깔끔하게 잘려 있어서 한 입씩 먹기 좋았고, 민트 컬러가 시원하게 느껴졌습니다. 조용한 분위기 덕분에 오랜만에 여유롭게 대화하며 머물다 나왔어요.', 20, 10, 'GOOD', SYSTIMESTAMP);
