INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '케이크 단면이 깔끔하게 잘려 있어서 한 입씩 먹기 편했어요. 민트색 음료랑 케이크가 테이블 위에서 확실히 눈길을 끌더라구요. 아이스 음료 덕분에 마실 때마다 시원함이 느껴져서 휴식 시간에 잘 어울렸어요. 트레이와 포크 세팅이 정돈돼 있어서 전체적으로 기분 좋게 즐겼네요.', 15, 10, 'GOOD', SYSTIMESTAMP);
