INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '민트라떼 색감이 유독 선명하게 층이 나눠져 있어서 테이블 위가 한층 정돈돼 보였어요. 여유롭게 직접 음료를 저어가며 마시니, 조용히 머물며 쉬어가기 좋았습니다. 간결하게 정돈된 세팅 덕분에 군더더기 없이 음미할 수 있었어요.', 36, 3, 'GOOD', SYSTIMESTAMP);
