INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '음료랑 케이크, 디저트까지 메뉴 구성이 다양해서 고르는 재미가 있었어요. 민트 색감이 선명해서 테이블 위가 한눈에 시원하게 느껴졌고, 포크랑 빨대, 개별 포장까지 깔끔하게 준비돼 있어 위생적으로 느껴졌네요. 여럿이서 나눠 먹으면서 자연스럽게 대화도 이어졌어요.', 18, 10, 'GOOD', SYSTIMESTAMP);
