INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '트레이 위에 민트초코 케이크와 민트라떼가 가지런하게 놓여 시작부터 정돈된 느낌이 좋았어요. 아이스 민트라떼는 청량하게 어울렸고, 케이크 한입 먹으니 달콤함이 입안에 퍼졌어요. 조용히 혼자 머무르며 기분까지 산뜻하게 환기되는 시간이었네요.', 40, 8, 'GOOD', SYSTIMESTAMP);
