INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '여럿이서 각자 음료를 고르며 자연스럽게 대화가 이어졌어요. 민트색 케이크가 테이블에 놓이니 분위기가 한층 산뜻해졌고, 포크랑 냅킨도 넉넉하게 준비되어 있어 불편함 없이 즐길 수 있었네요. 마무리까지 서로 도우며 자리를 깨끗하게 정리할 수 있었습니다.', 21, 2, 'GOOD', SYSTIMESTAMP);
