INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '민트라떼 색감이 선명해서 테이블 위가 산뜻하게 느껴졌어요. 준비된 냅킨과 빨대도 깔끔하게 세팅돼 있어 첫인상부터 기분이 좋았습니다. 혼자 한 잔 천천히 즐기며 조용히 머물다 가기에 딱 어울렸네요.', 1, 3, 'GOOD', SYSTIMESTAMP);
