INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '음료 세 가지랑 민트색 케이크를 나눠 먹으니 고르는 재미가 있었어요. 각 메뉴마다 색이 달라서 테이블 위가 한층 생동감 있게 느껴졌고, 포크와 냅킨이 넉넉하게 준비되어 있어 편하게 즐길 수 있었네요. 차분한 분위기에서 여유롭게 머무르기 좋아요.', 63, 18, 'GOOD', SYSTIMESTAMP);
