INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '음료랑 케이크 색이 선명하게 대비돼서 테이블 위가 한눈에 시원하게 느껴졌어요. 오레오 토핑이 얹힌 케이크는 부드럽게 잘라 먹을 때마다 식감이 살아 있었고, 필요한 것만 올려둔 테이블 구성 덕분에 대화에 더 자연스럽게 집중하게 됐네요. 공간 자체도 단정해서 한참 머물러도 편하게 느껴졌어요.', 14, 9, 'GOOD', SYSTIMESTAMP);
