INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '민트초코 좋아하는 분들이라면 눈이 번쩍 뜨일 조합이에요. 민트오레오치즈케이크가 달콤하면서도 치즈의 부드러움이 잘 어울려서 계속 손이 가더라구요. 음료들도 향이 깔끔하고 시원해서 디저트랑 궁합이 딱 맞았어요 😋', 4, 0, 'GOOD', SYSTIMESTAMP);
