INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '트레이에 디저트랑 음료가 깔끔하게 놓여 있어서 처음부터 기분이 산뜻했어요. 민트 색감이 또렷하게 보여서 테이블 위가 한층 상쾌해진 느낌이었죠. 내부 분위기랑 잘 어울려서 친구랑 대화도 더 자연스럽게 이어졌어요. 먹으면서 민트 덕분에 특별하게 여유를 즐길 수 있었네요.', 34, 1, 'GOOD', SYSTIMESTAMP);
