INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '트레이 위에 음료와 포크, 냅킨까지 깔끔하게 세팅되어 시작부터 기분이 편했어요. 민트색 케이크에 오레오 토핑이 올라가 있어 단번에 시선이 가더라구요. 음료와 디저트 함께 나누며 대화도 천천히 이어졌고, 전체적으로 여유로운 분위기를 느낄 수 있었습니다.', 18, 6, 'GOOD', SYSTIMESTAMP);
