INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '트레이에 음료와 케이크가 가지런히 준비되어 있어서 시작부터 기분이 산뜻했어요. 각기 다른 색감의 아이스 음료가 시선을 끌었고, 민트 케이크의 독특한 색 덕분에 고르는 재미가 있었네요. 여럿이서 나눠 먹으니 각자 취향에 맞게 즐길 수 있었고, 전체적으로 만족스럽게 마무리됐어요.', 29, 9, 'GOOD', SYSTIMESTAMP);
