INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '여러 명이 취향별로 민트 음료를 골라보는 재미가 있었어요. 트레이에 컵과 포크, 냅킨까지 가지런히 준비돼 있어서 처음부터 편하게 대화가 이어졌고, 민트 케이크와 음료를 나눠 먹으니 조합이 색다르게 느껴졌네요. 전체적으로 세련된 분위기 덕분에 편하게 즐길 수 있었습니다.', 34, 4, 'GOOD', SYSTIMESTAMP);
