INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '둘이 앉아서 민트 케이크를 넉넉하게 나눠 먹으니 한 조각도 든든하게 느껴졌어요. 오레오 토핑이 올라가서 식감에 포인트가 있었고, 아이스 음료 덕분에 상쾌하게 즐길 수 있었죠. 테이블 위에 포크랑 컵이 가지런히 놓여 있어서 안정감 있게 시작할 수 있었고, 내부 분위기도 감각적으로 느껴졌어요.', 11, 4, 'GOOD', SYSTIMESTAMP);
