INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '얼음 가득한 아이스 음료 한 모금에 더위가 싹 가시더라구요. 밝은 민트색 케이크가 시선을 확 잡아줘서 자연스럽게 손이 갔어요. 트레이에 정돈된 세팅 덕분에 더 깔끔하게 느껴졌고, 친구랑 나눠 먹으면서 편하게 이야기 나눌 수 있었네요.', 56, 13, 'GOOD', SYSTIMESTAMP);
