INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '트레이에 케이크랑 음료가 정돈돼 있어서 바로 먹기 편했어요. 민트색 케이크가 확 눈에 띄어서 고르는 재미가 있었고, 음료도 여러 잔이라 같이 온 사람들과 나눠먹기 딱 좋았네요. 디저트랑 음료 조합이 알차서 만족스럽게 즐겼어요.', 33, 4, 'GOOD', SYSTIMESTAMP);
