INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '트레이 위에 음료와 케이크가 정돈돼 있어 한눈에 보기 좋았어요. 아이스 음료 두 잔과 민트 케이크가 나란히 놓여서 자연스럽게 나눠먹기 편했네요. 전체적으로 세팅이 깔끔해서 대화하며 오래 머물기 괜찮았어요.', 0, 0, 'GOOD', SYSTIMESTAMP);
