INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '트레이에 케이크와 음료가 깔끔하게 놓여 있어서 보기부터 기분이 좋아졌어요. 민트초코퍼지는 오레오 토핑이 올라가 있어 나눠먹으면서 비교하는 재미가 있었고, 민트라떼 같은 음료들과 같이 곁들이니 조합이 잘 맞았네요. 공간도 아늑해서 편하게 쉬다 올 수 있었어요.', 15, 3, 'GOOD', SYSTIMESTAMP);
