INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '민트라떼가 색감부터 시원하게 느껴져서 한 모금 마실 때마다 갈증이 풀렸어요. 케이크 위 파란 크림이 정돈돼 보여서 더 예쁘게 느껴졌고, 포크며 컵까지 깔끔하게 세팅돼 있어 편하게 쉴 수 있었네요. 친구랑 앉아 여유롭게 대화 나누기에 좋았어요.', 46, 2, 'GOOD', SYSTIMESTAMP);
