INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '아이스 음료가 시원하게 느껴져서 한 모금마다 갈증이 바로 풀리더라구요. 민트 색 케이크가 독특하게 보여서 테이블이 한층 산뜻해진 느낌이에요. 전체적으로 플레이팅이 정돈되어 있어서, 여유롭게 이야기 나누기 참 좋았어요.', 106, 25, 'GOOD', SYSTIMESTAMP);
