INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '헐 민초덕후라면 여긴 무조건 좋아하실 듯요. 민트우유는 진짜 부드럽고 상큼해서 한입 마시면 기분까지 시원해져요. 달콤한 디저트랑 같이 먹으니까 조합이 딱 잘 맞더라구요. 분위기도 편안해서 데이트 자리로 오기에도 괜찮았어요 🤗', 41, 4, 'GOOD', SYSTIMESTAMP);
