INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '민트초코 좋아하신다면 민트오레오치즈케이크 한번 드셔보세요. 부드러운 치즈랑 상큼한 민트 향이 입안에서 조화롭게 어울리고, 오레오가 씹히는 식감까지 있어서 계속 손이 가더라구요. 공간 분위기도 편안하고 직원분들 응대도 따뜻해서 기분 좋게 머물렀습니다 🙂', 51, 12, 'GOOD', SYSTIMESTAMP);
