INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '민트아메리카노 특유의 시원한 향이 입안에 퍼지니까 기분이 싹 풀리더라구요. 달달함보다는 깔끔한 뒷맛이 남아서 더 매력 있었어요. 분위기도 차분해서 데이트하기 좋은 느낌이었고, 스태프분들도 은근히 따뜻하게 응대해 주셔서 편했네요 🤗', 13, 5, 'GOOD', SYSTIMESTAMP);
