INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '민트카페라떼가 달콤하면서도 깔끔하게 떨어지는 맛이 있어서 입안이 시원하게 정리되는 느낌이에요. 케이크도 크림이 부드럽고 층층이 식감이 살아 있어서 한입 먹을 때마다 은근히 설레더라고요. 전체적으로 디저트카페 분위기가 차분하고 편안해서 더 즐거웠습니다 🙂', 98, 22, 'GOOD', SYSTIMESTAMP);
