INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '민트 디저트가 다양해서 골라먹는 재미가 있었어요. 각각 컬러가 선명해서 테이블이 한층 화사해 보였고, 부드러운 케이크부터 바삭한 초콜릿까지 식감이 달라서 비교하는 즐거움이 있었습니다. 플레이팅도 깔끔하게 준비되어서 기분 좋게 나눠 먹고 왔네요.', 6, 0, 'GOOD', SYSTIMESTAMP);
