INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '민트초코퍼지 케이크 한입 먹으니까 꾸덕한 초콜릿 사이로 민트 향이 확 퍼져서 기분이 상쾌하더라구요. 같이 시킨 음료도 시원하고 부드러워서 케이크랑 궁합이 잘 맞았어요. 공간 분위기도 차분해서 디저트카페 느낌 물씬 났습니다 😋', 74, 12, 'GOOD', SYSTIMESTAMP);
