INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '주문한 아이스 음료가 보기만 해도 시원해서 손이 먼저 갔어요. 민트 디저트는 색감이 독특하고 오레오 토핑이 눈에 띄어서 구경하는 재미가 있네요. 여유롭게 나눠 먹으면서 편하게 이야기할 수 있어 기분 전환 제대로 했어요.', 4, 10, 'GOOD', SYSTIMESTAMP);
