INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '한입 먹자마자 민트향이 확 퍼지는데 오레오 크런치랑 같이 씹히는 게 너무 맛있더라구요. 달콤하면서도 상큼한 조합이 진짜 기분 좋아요. 커피랑 곁들이니까 밸런스도 딱 맞아서 디저트카페 찾는 분들 취향 제대로 저격일 듯 🙂', 3, 9, 'GOOD', SYSTIMESTAMP);
