INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '민트 색감이 먼저 시선을 끌었고, 케이크 단면도 깔끔하게 나눠져 보기 좋았어요. 포크와 냅킨이 정돈돼 있어 나눠 먹기 편했습니다. 민트와 초코, 오레오의 조합이 색다르게 느껴져서 디저트 시간에 소소한 재미가 더해졌네요.', 18, 5, NULL, SYSTIMESTAMP);
