INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '민트덕후라면 그냥 못 지나칠 곳이에요. 민트초코퍼지 케이크가 달콤하면서도 상큼한 민트향이 확 퍼져서 입안이 개운해졌어요. 같이 나온 음료도 컬러부터 시원한 느낌이라 보는 재미까지 있었네요 😋', 87, 17, 'GOOD', SYSTIMESTAMP);
