INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '트레이에 케이크와 음료가 정돈돼 있어서 시작부터 보기 좋았어요. 민트 케이크와 진한 초코 케이크가 딱 대비돼서 고르는 재미가 있었고, 음료 색감이 선명해서 분위기도 더 산뜻하게 느껴졌습니다. 포크랑 냅킨이 넉넉하게 준비돼서 여유 있게 나눠 먹기에 괜찮았어요.', 44, 10, NULL, SYSTIMESTAMP);
