INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '트레이 위에 각자 쓸 포크까지 준비되어 있어 편하게 케이크를 나눠 먹었어요. 음료 색감이 다양해서 테이블이 한층 산뜻하게 느껴졌고, 세련된 분위기 덕분에 대화에 집중하기 좋았네요. 마무리까지 기분 좋게 즐기고 나올 수 있었습니다.', 65, 17, 'GOOD', SYSTIMESTAMP);
