INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '여러 명이 모여 각자 원하는 음료랑 케이크를 골라보니 고르는 재미가 있더라구요. 트레이에 식기랑 포크가 한 번에 준비되어 편하게 나눠 먹기 좋았어요. 음료마다 색감이 달라서 테이블이 더 밝아진 느낌이 들었고, 자연스럽게 대화도 이어져서 만족스럽게 마무리했네요.', 69, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '음료랑 케이크가 트레이 위에 깔끔하게 세팅되어 있어 한눈에 보기 좋았어요. 민트초코 케이크 단면이 또렷하게 보여서 고르기 쉽게 느껴졌고, 음료와 케이크를 같이 먹으니 조합도 잘 어울려 여유롭게 즐기기 좋았습니다.', 34, 6, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '트레이 위에 케이크와 음료가 가지런히 놓여 첫 인상이 정돈됐어요. 민트색 디저트가 확실히 눈에 띄어서 테이블이 산뜻하게 느껴졌고, 민트 음료와 케이크 조합도 다양해서 고르는 재미가 있었네요. 전체적으로 공간 분위기랑 디저트가 잘 어울려서 여유롭게 즐기기 좋았습니다.', 27, 4, 'GOOD', SYSTIMESTAMP);
