INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '친구들이랑 포크 챙겨서 케이크 나눠 먹으니 대화도 자연스럽게 풀렸어요. 서로 다른 음료 고르다 보니 취향도 새로 알게 되고, 민트 케이크 비주얼 덕에 테이블 위 분위기가 더 밝아졌네요. 전체적으로 세팅이 깔끔해서 편하게 머물다 왔어요.', 87, 15, 'GOOD', SYSTIMESTAMP);
