INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '트레이에 메뉴가 가지런히 준비되어 처음부터 기분이 좋아졌어요. 민트 케이크의 선명한 색감이 확실히 눈에 띄었고, 얼음 가득한 음료 덕분에 시원하게 즐겼네요. 세련된 분위기에서 편하게 쉬다 올 수 있어 만족스럽게 마무리했습니다.', 278, 64, 'GOOD', SYSTIMESTAMP);
