INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '민트 초코 케이크랑 음료, 바크까지 선택지가 다양해서 고르는 재미가 있었어요. 각자 원하는 디저트 골라 담으니 테이블 위가 한층 산뜻해졌네요. 비주얼이 확실히 돋보여서 눈길이 갔고, 디저트랑 음료 한 번씩 곁들이며 여유롭게 쉬다 왔어요.', 100, 26, 'GOOD', SYSTIMESTAMP);
