INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '식기 세팅이 깔끔하게 준비되어 있어 바로 먹기 편했어요. 민트 케이크는 색감이 선명해서 눈에 잘 띄었고, 음료랑 같이 먹으니 조합이 잘 어울렸네요. 잔잔한 분위기에서 대화 나누기에도 괜찮아서 전체적으로 만족스러웠어요.', 13, 5, 'GOOD', SYSTIMESTAMP);
