INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '테이블에 앉아 메뉴를 살펴보니 민트 색감이 먼저 눈에 들어왔어요. 음료와 케이크 색상이 또렷하게 대비되어 시각적으로도 만족스러웠고, 각각 천천히 맛보며 조용히 대화 나누기에 딱이었습니다. 전체적으로 여유로운 분위기 덕분에 편안하게 시간 보내고 왔어요.', 27, 7, 'GOOD', SYSTIMESTAMP);
