INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '플레이팅이 처음부터 깔끔해서 기분이 좋아졌어요. 민트라떼는 시원함이 바로 느껴져서 한 입 마실 때마다 개운했네요. 케이크 한 조각이랑 같이 먹으니 진한 조화가 잘 어울렸고, 전체적으로 쾌적한 분위기 덕분에 편하게 머물 수 있었습니다.', 16, 7, 'GOOD', SYSTIMESTAMP);
