INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '트레이 위에 케이크와 음료가 단정하게 준비되어 첫인상부터 정돈된 느낌이었어요. 케이크 단면마다 초코와 민트가 균형 있게 겹쳐 보여 한 조각씩 나눠 먹는 재미가 있었습니다. 음료 얼음 덕분에 시원함이 오래가서 편하게 시간 보내기 좋았네요.', 80, 18, 'GOOD', SYSTIMESTAMP);
