INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '트레이 위에 메뉴들이 깔끔하게 정돈돼 있어 시작부터 마음이 편했어요. 오레오 토핑이 듬뿍 올라간 민트 케이크 비주얼이 확실히 눈에 들어왔고, 얼음 잔뜩 든 음료랑 같이 있으니 더 시원하게 즐길 수 있었네요. 세련된 인테리어 분위기랑 잘 어울려서 전체적으로 만족스러웠어요.', 27, 3, 'GOOD', SYSTIMESTAMP);
