INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '트레이 위에 메뉴가 가지런히 준비되어 시작부터 정돈된 느낌이 들었어요. 민트색 케이크와 음료가 조화롭게 어우러져서 시각적으로 신선했네요. 차분한 분위기에서 여유롭게 디저트와 음료를 즐기며 편하게 머물 수 있었습니다.', 53, 13, 'GOOD', SYSTIMESTAMP);
