INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '민트오레오 치즈케이크랑 민트초코퍼지 케이크 각각 나눠 먹으면서 비교하는 재미가 있네요. 음료 색감이 선명해서 시선이 먼저 갔고, 트레이에 정돈된 세팅 덕분에 전체적으로 깔끔하게 느껴졌어요. 여럿이서 조용히 앉아 민트디저트 조합을 즐기기 좋은 곳이에요.', 43, 3, 'GOOD', SYSTIMESTAMP);
