INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '테이블 위에 올려진 민트색 케이크와 오레오 토핑이 눈에 잘 띄었어요. 투명하게 층이 보이는 민트 음료와 함께 조합을 즐기니 색감도 분위기도 만족스러웠습니다. 전체적으로 구성도 알차고 테이블 정돈도 마음에 들었습니다.', 29, 1, 'GOOD', SYSTIMESTAMP);
