INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '여럿이서 음료를 골라 주문하니 얼음이 넉넉하게 들어가서 한 잔씩 시원하게 즐겼어요. 포크와 식기도 미리 세팅되어 있어서 각자 편하게 나눠 먹기에 불편함이 없었습니다. 밝은 색의 민트 케이크를 함께 나누며 취향껏 선택한 음료로 여유로운 시간을 보냈네요.', 47, 5, 'GOOD', SYSTIMESTAMP);
