INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '혼자 앉아 케이크 단면을 천천히 보며 먹으니 조용히 쉬기 좋았어요. 아이스 음료 한 모금 덕분에 마무리가 상쾌하게 느껴졌고, 전체적으로 테이블이 깔끔하게 세팅되어 집중해서 편하게 머물렀네요.', 25, 7, 'GOOD', SYSTIMESTAMP);
