INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '트레이에 올려진 민트 케이크와 아이스 민트라떼가 잘 어울렸어요. 케이크 단면이 깔끔하게 보여서 한 입 베어무는 맛이 좋았고, 음료는 얼음이 넉넉하게 들어있어 끝까지 시원하게 즐겼습니다. 여유롭게 대화 나누며 조합의 매력을 제대로 느낄 수 있었어요.', 26, 3, 'GOOD', SYSTIMESTAMP);
