INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '케이크마다 색감이 또렷해서 보기만 해도 구분이 쉬웠어요. 위에 토핑까지 정성스럽게 올려져 있어 플레이팅이 신경 쓴 느낌이 들었습니다. 조용한 분위기에서 서로 취향 이야기하며 여유롭게 디저트를 골라 먹기 좋았네요.', 24, 2, 'GOOD', SYSTIMESTAMP);
