INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '얼음 가득한 음료 덕분에 마시는 내내 시원함이 확 느껴졌어요. 트레이에 식기랑 케이크가 정돈돼 있어서 시작부터 깔끔한 기분이 들었고, 민트색 케이크는 색감부터 눈길이 갔네요. 여유롭게 나눠 먹으면서 편하게 이야기 나누기 좋은 시간이었어요.', 20, 8, 'GOOD', SYSTIMESTAMP);
