INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '오레오가 큼직하게 올려진 민트 케이크가 시선을 끌었어요. 얼음이 가득 들어간 시원한 음료 덕분에 입안도 깔끔하게 정리됐네요. 트레이에 깔끔하게 차려져 있어서 조용히 앉아 쉬며 여유를 즐기기 좋았어요.', 73, 17, 'GOOD', SYSTIMESTAMP);
