INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '아이스커피와 케이크 각각의 조화가 눈에 띄었어요. 깔끔하게 준비된 트레이와 식기로 단정한 느낌이 더해져서 편하게 즐길 수 있었네요. 민트초코 조합이라 그런지 평소와는 다르게 기억에 남는 시간이었어요.', 27, 10, 'GOOD', SYSTIMESTAMP);
