INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '가게 들어서서 직접 셀프 세팅하니 준비 과정이 깔끔하게 느껴졌어요. 민트 음료 첫 모금이 시원하게 다가와서 한입에 기분이 바뀌더라구요. 민트 케이크의 화사한 색감이 테이블 위를 더 산뜻하게 만들어줘서 여유 있게 즐길 수 있었어요.', 38, 7, 'GOOD', SYSTIMESTAMP);
