INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '트레이가 깔끔하게 정돈되어 있어서 시작부터 기분이 좋았어요. 민트빛 케이크가 시선을 사로잡았고, 여러 가지 아이스 음료와 함께 조합을 다양하게 즐길 수 있었네요. 식기와 포크도 깨끗하게 준비돼 편하게 먹을 수 있었습니다. 편안하게 쉬어가기 좋은 공간이었어요.', 85, 11, 'GOOD', SYSTIMESTAMP);
