INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '민트 색 케이크랑 음료가 한눈에 들어오더라구요. 여러 메뉴를 같이 맛보니 골라 먹는 재미가 있었어요. 포크와 빨대 등 식기도 잘 준비되어 있어서 편하게 즐길 수 있었습니다. 함께 나눠 먹으면서 대화도 자연스럽게 이어졌고, 전체적으로 만족스러운 시간이었네요.', 18, 6, 'GOOD', SYSTIMESTAMP);
