INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '유리잔에 담긴 민트라떼가 시원하게 보여서 첫인상부터 눈길이 갔어요. 테이블 위 정돈된 세팅 덕분에 공간이 더 깔끔하게 느껴졌고, 직접 마시니 은은하게 상쾌함이 퍼졌던 기억이 남아요. 세련된 분위기에서 여유롭게 시간을 보낼 수 있었네요.', 23, 2, 'GOOD', SYSTIMESTAMP);
