INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '민트 컬러 케이크와 음료가 깔끔하게 세팅되어 한눈에 들어왔어요. 사이좋게 한 조각씩 나누며 대화 나누기 좋은 분위기라 여유롭게 즐길 수 있었네요. 테이블 위 정돈된 느낌 덕분에 자리에서 편안히 머물렀어요.', 34, 2, 'GOOD', SYSTIMESTAMP);
