INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '처음 접한 민트 디저트 색감이 확실히 눈에 들어왔어요. 각각의 케이크가 또렷하게 구분돼서 고르는 재미가 있었고, 음료는 얼음이 가득해 시원하게 즐기기 좋았네요. 트레이와 식기가 깔끔하게 세팅되어 있어 전체적으로 만족스러웠어요.', 40, 2, 'GOOD', SYSTIMESTAMP);
