INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '민트 음료랑 민트 디저트 조합이 테이블 위에 올려져 있으니 분위기부터 시원하게 느껴졌어요. 케이크, 마카롱을 번갈아 먹으면서 각각 다른 식감도 바로 느껴져서 좋았습니다. 전체적으로 깔끔하게 즐기기 좋은 구성이라 산뜻하게 마무리할 수 있었어요.', 11, 10, 'GOOD', SYSTIMESTAMP);
