INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '초코 드리즐이 유리잔에 진하게 남아서 비주얼부터 눈에 띄었어요. 시원한 얼음이 가득 들어 있어 한 모금씩 마실 때 상쾌함이 잘 느껴졌고, 나무 테이블 덕분에 전체 분위기가 더 편안하게 느껴졌네요. 앉아서 천천히 음료 즐기며 쉬기 좋았어요.', 15, 10, 'GOOD', SYSTIMESTAMP);
