INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '내부 전체가 민트색으로 꾸며져서 들어서자마자 특별한 분위기가 느껴졌어요. 창가 자리에 앉으니 바깥 풍경도 편하게 볼 수 있어 시간 보내기에 좋았습니다. 다양한 민트 디저트를 고르는 재미가 쏠쏠했네요.', 8, 0, 'GOOD', SYSTIMESTAMP);
