INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '민트 색감이 눈에 띄어서 메뉴가 더 특별하게 느껴졌어요. 케이크랑 음료 조합이 독특하게 어울려서 한입 먹을 때마다 새로운 느낌이었네요. 잔잔한 분위기라 데이트나 조용한 시간 보내기 괜찮았어요.', 17, 5, 'GOOD', SYSTIMESTAMP);
