INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '통창 옆에 앉으니 밖 풍경 보며 여유 있게 얘기 나누기 좋았어요. 전체적으로 민트색 인테리어가 산뜻해서 기분이 한층 가벼워졌네요. 민트초코 음료랑 케이크를 골라보는 재미도 있어서, 친구랑 오랜만에 다양한 조합을 즐겼어요.', 25, 10, 'GOOD', SYSTIMESTAMP);
