INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '얼음이 가득한 음료를 먼저 마시니 입안이 시원해졌어요. 진한 민트색 디저트 조합이 테이블 분위기를 한층 산뜻하게 만들어줬네요. 간단히 한 입씩 나눠 먹으며 대화가 자연스럽게 이어졌고, 브랜드 로고가 들어간 소품도 깔끔하게 느껴졌어요.', 77, 12, 'GOOD', SYSTIMESTAMP);
