INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '진열대 앞에서 뭐 고를지 한참 고민하게 되더라고요. 민트초코퍼지 케이크랑 다른 민트 디저트들이 확실히 눈에 띄었어요. 한 입 먹으니 입안에 시원함만 남아서 만족스러웠어요. 여러 메뉴 비교해보는 재미도 있어서 민트덕후라면 꼭 들러볼 만해요.', 12, 0, 'GOOD', SYSTIMESTAMP);
