INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '친구랑 처음 들렀는데 테이블이 깨끗해서 앉는 순간부터 기분이 좋았어요. 귀여운 곰 그림이 그려진 컵이 인상적이었고, 시원한 음료 덕분에 대화도 한층 더 편하게 이어졌네요. 다음엔 민트 메뉴도 꼭 먹어보고 싶어요.', 60, 15, 'GOOD', SYSTIMESTAMP);
