INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '입구부터 민트 컬러가 통일감 있게 꾸며져 한눈에 들어왔어요. 브랜드만의 산뜻한 분위기가 확실히 느껴져서 디저트에 대한 기대도 자연스럽게 생겼네요. 공간에서부터 기분이 한층 밝아져서 기분 좋은 마무리가 됐어요.', 31, 5, 'GOOD', SYSTIMESTAMP);
