INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '민트색 케이크가 상큼해서 음료랑 잘 어울렸어요. 트레이에 식기랑 냅킨이 정돈돼 있어 시작부터 깔끔하게 느껴졌고, 친구랑 나란히 앉아 이야기 나누며 천천히 즐길 수 있었네요.', 30, 0, 'GOOD', SYSTIMESTAMP);
