INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '민트빛이 또렷한 음료가 시선 먼저 끌었어요. 얼음 가득한 잔을 서로 건네며 나누다 보니 대화가 자연스럽게 이어졌네요. 다양한 메뉴가 준비돼 있어 고르는 즐거움이 확실히 느껴졌어요.', 114, 21, 'GOOD', SYSTIMESTAMP);
