INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '각자 다른 민트 음료를 고르면서 자연스럽게 대화가 시작됐어요. 음료 색감이 확실히 달라서 테이블 위가 한층 더 산뜻하게 느껴졌고, 테이블 정돈이 잘 돼 있어 여유롭게 마실 수 있었네요.', 42, 2, 'GOOD', SYSTIMESTAMP);
