INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '여러 메뉴 주문해보니 각자 색다른 매력이 느껴졌어요. 민트오레오 치즈케이크는 부드럽고, 민트라떼는 시원해서 각각 따로 즐기기 좋았네요. 취향따라 케이크 혹은 음료 중 선택해도 만족할 듯하고 직원분이 밝게 응대해줘 재방문 의사도 생겼어요.', 66, 14, 'GOOD', SYSTIMESTAMP);
