INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '민트덕후라면 환장할 곳 맞네요. 민트오레오 치즈케이크는 부드럽게 녹으면서도 달콤쌉싸름한 조합이 신의 한 수였어요. 음료도 시원하고 깔끔해서 같이 먹으니 더 좋았어요 😋', 109, 21, 'GOOD', SYSTIMESTAMP);
