INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '케이크 플레이팅이 깔끔해서 사진부터 찍게 됐어요. 민트초코퍼지와 오레오 치즈케이크 단면을 비교하니 색감이 확 달라 보였습니다. 먹을수록 단맛과 상쾌함이 달라서 재미있었고, 민트라떼랑 같이 먹으니 조합이 더 잘 어울렸어요.', 1, 4, 'GOOD', SYSTIMESTAMP);
