INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '포장해서 집에 와서 케이크랑 민트라떼를 천천히 즐겼어요. 케이크는 집에서도 부드럽고, 민트와 초콜릿 조화가 확실히 도드라졌습니다. 남은 조각도 맛이 그대로라 끝까지 신선하게 먹을 수 있었네요.', 0, 2, 'GOOD', SYSTIMESTAMP);
