INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '케이크 고르기 전에 직원분이 메뉴 설명을 친절하게 해줘서 쉽게 선택했어요. 민트초코퍼지는 부드럽고, 민트오레오 치즈케이크는 진한 풍미가 느껴져서 각각 다른 매력이 있었네요. 남은 케이크는 포장해 집에서 다시 먹으니 식감이 그대로라 또 한 번 만족했습니다.', 39, 5, 'GOOD', SYSTIMESTAMP);
