INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '민트초코퍼지 케이크는 달콤함이 먼저 느껴지고, 부드럽게 넘어가서 만족스러웠어요. 민트오레오 치즈케이크는 민트향이 은은하게 남아 오레오와 잘 어울렸어요. 여운이 길지 않고 깔끔하게 마무리되는 맛이라, 마지막까지 기분이 편했네요.', 51, 18, 'GOOD', SYSTIMESTAMP);
