INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '감각적인 인테리어 덕분에 들어서자마자 시선이 머물렀어요. 민트오레오 치즈케이크랑 민트라떼 사진부터 여러 장 찍게 되더라구요. 직원분들도 친절하게 안내해줘서 편하게 주문할 수 있었고 디저트카페로서 다음에도 꼭 다시 방문하고 싶어요.', 55, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
