INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '메뉴 이름 모르고 고른 케이크였는데, 직원분이 설명해주셔서 빠르게 이해했어요. 첫 입엔 의외로 초콜릿과 민트가 잘 어울려서 재미있었고, 먹는 동안 디저트 단면이 달라지는 게 신선하게 느껴졌어요. 결국 부드러운 케이크 쪽이 내 취향이라는 걸 알게 됐네요.', 13, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '메뉴를 받자마자 색감이 눈에 들어왔어요. 케이크 한 입 먹을 때마다 단맛과 민트향 조화가 다르게 느껴져서 재밌었고, 음료와 디저트 각각 부드러운 질감이어서 비교하며 먹는 재미가 있었습니다. 직원분이 친절하게 안내해줘서 전체적으로 만족스러웠어요.', 47, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '내부가 아늑해서 앉자마자 편하게 느껴졌어요. 민트라떼는 깔끔하고, 케이크는 각각 다른 매력이 있어서 비교해 먹는 재미가 있었네요. 조용하게 머무르며 디저트 즐기기에 딱 좋아서 쉬어가기 좋았어요.', 45, 7, 'GOOD', SYSTIMESTAMP);
