INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '케이크 단면을 먼저 보고 두 가지를 나란히 비교해봤어요. 민트초코퍼지는 부드럽고 달콤해서 입안에 기분 좋게 퍼졌고, 민트오레오 치즈케이크는 상쾌함과 진한 치즈 맛이 어울려서 확실히 색다르더라구요. 민트라떼랑 같이 먹으니 맛이 더 깔끔하게 어우러져 마지막까지 기분 좋게 마무리했어요.', 107, 22, 'GOOD', SYSTIMESTAMP);
