INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '주문부터 빠르게 진행되어 기다림 없이 좋았어요. 케이크 플레이팅이 예뻐서 사진 먼저 찍게 되더라구요. 조용한 분위기 덕분에 혼자서도 여유롭게 머물렀고, 디저트 먹고 나니 기분이 한결 산뜻해졌어요.', 48, 6, 'GOOD', SYSTIMESTAMP);
