INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '테이블에 메뉴를 펼쳐두고 서로 한 입씩 나눠먹으니 각자 취향이 딱 보이더라구요. 민트초코퍼지 케이크는 진한 맛이 인상적이었고, 민트오레오 치즈케이크는 산뜻해서 선호가 갈렸어요. 결국 다들 자신이 고른 메뉴에 만족해하는 분위기라 즐거웠어요.', 41, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '메뉴 선택이 고민될 만큼 종류가 다양해서 한참을 망설였어요. 민트오레오 치즈케이크와 민트라떼를 함께 고른 조합이 기대 이상으로 잘 어울렸습니다. 디저트 먹으며 편안하게 시간을 보내다 보니 여유가 느껴졌네요.', 36, 4, 'GOOD', SYSTIMESTAMP);
