INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '민트색 디저트가 한눈에 들어와서 고르는 재미가 있었어요. 투명한 잔에 담긴 시원한 음료랑 자연스럽게 어울려서 조화롭게 즐겼고, 전체적으로 플레이팅이 정돈돼 있어서 만족스러웠네요.', 59, 17, 'GOOD', SYSTIMESTAMP);
