INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '굿즈 종류가 정말 많아서 하나씩 구경하는 재미가 쏠쏠했어요. 전체적으로 공간이 아기자기하게 꾸며져 있어서 머무는 동안 기분이 좋아졌고, 민트덕후라면 꼭 한 번 들러볼 만한 곳이에요.', 83, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '민트 음료 색감이 보기만 해도 상큼하게 느껴졌어요. 포장된 디저트 모양도 독특해서 하나씩 고르는 재미가 있었습니다. 트레이 위에서 차분하게 즐기니 단순히 쉬어가는 느낌이 들어서 좋았어요.', 24, 6, 'GOOD', SYSTIMESTAMP);
