INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '테이블 세팅이 정돈돼 있어서 바로 기분이 좋아졌어요. 민트와 초콜릿이 눈에 확 들어와서 메뉴 고를 때부터 기대됐네요. 케이크랑 음료 조합이 잘 어울려서 자연스럽게 오래 머물렀어요.', 18, 0, 'GOOD', SYSTIMESTAMP);
