INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '비주얼부터 시선을 사로잡는 디저트라 기대감이 생겼어요. 민트와 초코가 어우러진 조합이 먹는 내내 기분을 상쾌하게 해줬네요. 달콤함이 계속 이어져서 전체적으로 만족스러운 시간이었어요.', 38, 3, 'GOOD', SYSTIMESTAMP);
