INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '진열대 가득한 디저트 중 고르는 재미가 있었어요. 밝은 민트색이 눈에 띄어서 기분이 산뜻해졌네요. 민트와 초코가 어우러진 케이크를 연인과 나눠 먹으니 더 즐거웠던 시간이었어요.', 26, 3, 'GOOD', SYSTIMESTAMP);
