INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '디저트랑 음료가 예쁘게 플레이팅되어서 기분부터 좋아졌어요. 민트라떼는 우유랑 민트가 부드럽게 어울렸고, 민트오레오 치즈케이크랑 민트초코퍼지 케이크는 각자 개성이 확실하더라구요. 저는 오레오 들어간 치즈케이크 조합이 더 잘 맞았던 것 같아요.', 70, 11, 'GOOD', SYSTIMESTAMP);
