INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '민트디저트랑 일반 베이커리 둘 다 맛봤는데 확실히 분위기가 달랐어요. 민트오레오 치즈케이크에 커피 조합이 입에 잘 맞아서 끝까지 만족스럽게 먹었습니다. 취향 따라 골라 먹는 재미에 다음에 또 방문하고 싶어져요.', 128, 26, 'GOOD', SYSTIMESTAMP);
