INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '진동벨 손에 쥐고 기다리면서 내부 분위기 한 번 더 살펴봤어요. 민트초코퍼지 케이크 딱 받아들자마자 향이 먼저 느껴졌고, 첫입에 온도감도 괜찮았네요. 남은 조각은 포장해가니 집에서도 여유롭게 즐길 수 있었어요.', 123, 22, 'GOOD', SYSTIMESTAMP);
