INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '여러 가지 민트음료와 케이크를 차례로 맛봤어요. 민트와 초콜릿이 섞인 케이크는 달콤하면서도 상쾌함이 느껴졌고, 케이크마다 풍미가 달라서 고르는 재미가 있었네요. 한 번 더 방문해서 다른 조합도 먹어보고 싶어요.', 2, 3, 'GOOD', SYSTIMESTAMP);
