INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '민트음료 종류가 다양해서 고르기부터 재밌었어요. 직원분이 친절하게 각 메뉴 특징도 설명해줘서 고르는 데 도움이 됐습니다. 민트오레오 치즈케이크와 민트라떼 조합이 새로웠고, 다음엔 다른 메뉴도 꼭 도전해보고 싶어요.', 18, 4, 'GOOD', SYSTIMESTAMP);
