INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '케이크랑 음료 모두 색감이 또렷해서 눈길이 먼저 갔어요. 테이크아웃으로 포장 받는데 포장도 깔끔해서 들고 다니기 편했습니다. 친구들도 민트 덕후라며 관심 보여서, 민트 초코 좋아하는 분들께 추천하고 싶어요.', 16, 9, 'GOOD', SYSTIMESTAMP);
