INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '주문이 복잡하지 않아 금방 받을 수 있었어요. 민트오레오 치즈케이크를 한입 먹으니 진한 민트향이 바로 느껴졌고, 직원분이 짧게 메뉴 설명해줘서 처음 선택했는데 만족스러웠네요. 식사 후에도 입안이 산뜻하게 남아 기분 좋게 나왔어요.', 28, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '케이크 설명이 자세하게 적혀 있어서 메뉴 고르면서 한참 고민했어요. 처음엔 익숙한 걸로 가려다 민트오레오 치즈케이크에 눈이 가서 도전해봤죠. 한 입씩 번갈아 먹으니 확실히 맛 차이가 느껴져서 비교하는 재미가 있었어요. 남은 조각은 포장해가니 집에서도 한 번 더 즐길 수 있더라고요.', 43, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '진열대에서 민트초코퍼지와 민트오레오 치즈케이크를 골라 바로 메뉴 설명도 읽어봤어요. 민트라떼까지 주문해서 케이크랑 같이 조합하다 보니 각자 다른 맛이 느껴졌어요. 민트초코퍼지는 진한 초코가 먼저 와닿고, 오레오는 치즈랑 부드럽게 어울렸네요. 메뉴 구성이 다양해서 다음에도 또 와보고 싶어졌어요.', 3, 1, 'GOOD', SYSTIMESTAMP);
