INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '민트초코퍼지랑 민트오레오 치즈케이크를 같이 주문해서 비교해 봤어요. 두 케이크 모두 민트맛이 다르게 느껴져서 번갈아 먹는 재미가 있었고, 남은 건 포장해서 집에서도 또 즐겼습니다. 여러 가지 민트 디저트 고르며 데이트 장소로도 활용하기 괜찮겠더라고요.', 14, 6, 'GOOD', SYSTIMESTAMP);
