INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '민트초코퍼지 케이크를 처음 먹어봤는데 진한 맛이 확 느껴졌어요. 직원분의 추천으로 민트오레오 치즈케이크도 골랐는데 확실히 다른 매력이 있더라고요. 데이트 장소로도 조용하고 아늑해서 다음에 또 오고 싶은 곳이에요.', 34, 9, 'GOOD', SYSTIMESTAMP);
