INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '주문할 때 민트 디저트 종류가 다양해서 고민이 됐어요. 직접 받아보니 케이크마다 색감이나 크기가 조금씩 다른 게 한눈에 들어왔고, 민트초코퍼지랑 오레오 치즈케이크 각각 풍미가 확실히 느껴졌어요. 민트 좋아하는 분들한테는 메뉴 선택하는 재미가 있을 듯해요.', 122, 23, 'GOOD', SYSTIMESTAMP);
