INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '민트초코퍼지 케이크랑 민트오레오 치즈케이크가 확실히 비주얼이 달랐어요. 테이블 위에 디저트와 음료가 가지런하게 놓여 있어서 먹기 전부터 기분이 좋았습니다. 민트라떼와 각 케이크를 조합해서 먹으니 맛이 다르게 느껴져서 골라 먹는 재미가 있었고, 다음엔 민트덕후 친구랑 같이 와도 좋겠다는 생각이 들었어요.', 2, 10, 'GOOD', SYSTIMESTAMP);
