INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '민트초코퍼지 케이크랑 민트라떼를 골랐는데 직원분이 민트오레오 치즈케이크도 추천해줘서 같이 주문했어요. 직접 맛보니 각각 달라서 고르는 재미가 있었고, 디저트카페답게 조합이 잘 어울렸네요. 민트덕후라면 다시 와도 메뉴 골라보는 재미가 충분할 것 같아요.', 94, 22, 'GOOD', SYSTIMESTAMP);
