INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '메뉴판부터 민트 조합이 예쁘게 나열돼 있어서 고르는 재미가 있었어요. 민트초코퍼지 케이크랑 민트오레오 치즈케이크 각각 골라보니, 서로 다른 민트 맛이 바로 느껴졌고 민트라떼까지 곁들여서 민트 메뉴에 제대로 집중해볼 수 있었네요. 짧은 시간에도 다양한 민트 조합을 비교하며 즐기기에 딱 좋았습니다.', 17, 2, 'GOOD', SYSTIMESTAMP);
