INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '메뉴 주문할 때 직원분이 친절하게 설명해줘서 선택이 쉬웠어요. 민트라떼랑 케이크 세 가지를 나눠 먹으니 각자 취향에 맞는 맛을 찾아서 즐거웠고, 음료와 디저트 모두 가격 대비 만족도가 높다고 느꼈어요.', 13, 0, 'GOOD', SYSTIMESTAMP);
