INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '민트라떼는 입 안에 민트 향이 은은하게 남아서 음료부터 기분이 달라지더라고요. 퍼지 케이크는 달콤한 맛이 진하게 느껴지고, 오레오 치즈케이크는 상쾌함이 한 번에 확 다가왔어요. 민트덕후라면 메뉴 골라 먹는 재미 확실히 느껴질 거라 생각해요.', 57, 12, 'GOOD', SYSTIMESTAMP);
