INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '민트라떼, 민트초코퍼지 케이크, 민트오레오 치즈케이크 모두 직접 주문해서 먹어봤어요. 각 메뉴마다 민트 향이 다르게 느껴져서 비교해보는 재미가 있었고, 개인적으로는 진한 초콜릿과 민트 조합이 확실한 퍼지 케이크가 제일 입에 잘 맞더라고요. 여러 메뉴 천천히 맛보며 오래 머물기 좋아 만족스러웠습니다.', 2, 4, 'GOOD', SYSTIMESTAMP);
