INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '민트라떼랑 민트아메리카노 둘 다 마셔봤는데 느낌이 꽤 달라서 고르는 재미가 있었어요. 민트초코퍼지 케이크랑 오레오 치즈케이크 조합도 각각 매력적이라 비교해보며 먹는 재미가 쏠쏠했습니다. 굿즈 진열장도 한 번씩 둘러보게 돼서 기다리는 시간도 지루하지 않았어요.', 21, 2, 'GOOD', SYSTIMESTAMP);
