INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '민트 음료 여러 가지를 마셔보니 각자 향과 단맛, 식감이 조금씩 다르더라고요. 특히 민트라떼는 부드러움이 잘 살아 있고, 다른 메뉴들은 청량한 민트맛이 더 두드러졌어요. 직접 고른 민트초코퍼지 케이크는 진한 초코와 시원한 민트가 확실하게 구분돼서 더 인상 깊었습니다.', 14, 7, 'GOOD', SYSTIMESTAMP);
