INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '주문이 간단해서 시작부터 편했어요. 음료랑 케이크가 빠르게 나와 기다림이 거의 없었습니다. 민트라떼는 부드럽게 넘어가고, 케이크 둘 다 민트맛이 분명하게 살아있어 좋았어요. 양이 딱 맞아 배부르게 잘 먹고 나왔고, 다음에 또 방문할 생각이 들었습니다.', 13, 10, 'GOOD', SYSTIMESTAMP);
