INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '와, 민트 토피넛을 마셔봤는데 이건 실화냐? 부드러운 크림과 진한 민트의 조화라니! 감동의 물결 특히 민트케이크, 꾸덕한 맛에 홀린 듯 다시 찾게 될 거에요 민트만 사랑하는 줄 알았는데, 이렇게까지 섬세하게 조화로울 줄이야. 💚', 4, 6, 'GOOD', SYSTIMESTAMP);
