INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '민트 디저트 여러 가지 주문해서 비교해봤어요. 민트오레오 치즈케이크는 민트, 오레오, 치즈가 진짜 잘 어울렸고, 입 안에 깔끔한 단맛이 남아서 마지막까지 부담 없었네요. 다음엔 어떤 민트음료에 도전할지 고민하게 되는 곳이에요.', 42, 1, 'GOOD', SYSTIMESTAMP);
