INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '처음에는 민트오레오 치즈케이크부터 맛봤어요. 한입 먹는 순간 상쾌한 향이 먼저 느껴져서 기분이 달라졌고, 민트맛이 진하게 퍼져서 입안이 시원했네요. 민트덕후라면 여러 메뉴 비교해보려고 또 올 것 같아요.', 21, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '직접 고른 민트 디저트를 커플끼리 비교해보니 각자 취향 차이가 확실히 느껴졌어요. 민트초코퍼지 케이크와 민트오레오 치즈케이크를 함께 나눠먹으니 조합이 다양해서 만족스러웠고, 아늑한 분위기 덕분에 대화도 자연스럽게 이어졌네요.', 123, 19, 'GOOD', SYSTIMESTAMP);
