INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '케이크 두 가지를 나눠 먹으니 서로 다른 민트의 매력이 확실하게 느껴졌어요. 민트음료와 곁들이니 디저트 조합에 한 번 더 손이 갔네요. 특별한 날 새로운 음료와 케이크로 다시 즐길 생각이 들어요.', 3, 4, 'GOOD', SYSTIMESTAMP);
