INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '직원이 메뉴에 대해 꼼꼼하게 설명해줘서 주문이 수월했어요. 추천받은 케이크와 민트라떼를 골랐는데, 두 메뉴가 각자 다른 매력을 보여줬어요. 마무리까지 기분 좋은 경험이라 만족스럽네요.', 18, 3, 'GOOD', SYSTIMESTAMP);
