INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '오, 민트라떼가 이렇게 깔끔할 수 있구나 싶었어요. 민트의 향이 느껴지면서도 과하지 않아요. 인테리어도 예쁘고, 기분 전환 제대로 했죠.', 35, 7, 'GOOD', SYSTIMESTAMP);
