INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '민트 아메리카노 주문했는데, 이거 실화냐? 민트향과 커피의 어우러짐이 이렇게 맛있을 줄이야! 민트케이크도 부드럽고 달콤해요. 민트 덕후 강추!', 53, 13, 'GOOD', SYSTIMESTAMP);
