INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '민트하임은 민트의 천국이네요 민트 아메리카노 한입에 신선한 민트향이 퍼지는게 정말 대박이에요😊 민트 초코라떼와 민트케이크 조합은 찐 민초단이라면 반드시 방문해야 하는 곳!', 73, 13, 'GOOD', SYSTIMESTAMP);
