INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '주문할 때 직원분이 메뉴 하나하나 설명해주는 게 인상적이었어요. 결제할 때 번거로움 없이 금방 끝나서 편했습니다. 민트초코 좋아하는 분들은 다시 찾고 싶을 곳 같아요.', 11, 10, 'GOOD', SYSTIMESTAMP);
