INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '여러 종류의 민트음료를 친구랑 나눠 마셔봤어요. 같은 민트라떼도 서로 다르게 느끼는 모습이 신기했네요. 취향에 따라 고르는 재미가 있었고, 새로운 조합을 직접 경험해볼 수 있어 좋았어요.', 96, 22, 'GOOD', SYSTIMESTAMP);
