INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '메뉴판에서 민트초코퍼지 케이크 보고 바로 주문했어요. 케이크 단면이 촉촉해서 한입 베어물 때 식감이 깔끔하게 느껴졌네요. 남은 조각은 천천히 아껴 먹으니 달콤함이 오래가는 느낌이라 좋았어요.', 72, 11, 'GOOD', SYSTIMESTAMP);
