INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '다양한 민트 음료를 주문해서 하나씩 비교해봤어요. 각각 민트 향이 다르게 느껴져서 선택하는 재미가 있었습니다. 민트를 좋아하는 입장에선 고르는 순간부터 만족감이 확실하게 느껴졌어요.', 30, 2, 'GOOD', SYSTIMESTAMP);
