INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '메뉴 고르기 쉽게 되어 있어서 고민 없이 주문했어요. 직원분이 친절하게 안내해주셔서 처음 방문인데도 편하게 느껴졌고, 케이크 포장도 깔끔해서 테이크아웃하기에 딱 좋았습니다.', 88, 14, 'GOOD', SYSTIMESTAMP);
