INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '민트 좋아하는 친구랑 같이 가보았는데 생각보다 메뉴가 다양해서 좋았어요. 민트초코퍼지 케이크랑 음료 주문했는데 꾸덕한 초코 위에 민트가 적절하게 어우러져 있었어요. 민트덕후들에게 강추하고 싶은 곳이에요. ㅋㅋ', 41, 4, 'GOOD', SYSTIMESTAMP);
