INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '오! 민트에 진심인 서교동 카페에요~ 이름은? 민트하임! 민트 카페라테, 민트 밀크티, 민트 오레오 치즈케이크를 주문했는데! 역시나 깔끔한 끝맛이 독특해요! 민트에 진심이라면, 꼭 와보세요! 그런데 원두도 맛있어요 😊 참! 라온 굿즈, 하츠네미쿠 굿즈도 있으니 참고하세요 😉', 40, 2, 'GOOD', SYSTIMESTAMP);
