INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '민트초코라떼 처음 마셔봤는데 정말 맛있어요 민트와 초콜릿이 잘 어우러져서 달달하면서도 상큼한 느낌이 좋네요 사장님도 친절하시고 음료도 예쁘게 나와서 만족했어요', 43, 7, 'GOOD', SYSTIMESTAMP);
