INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '민초단으로서 예전부터 가보고 싶었던 서교동 카페 민트하임!! 입구부터 민트색 낭낭해서 너무나 설레였어요~~ 귀여운 캐릭터들이 반겨주고 너무나 귀엽게 꾸며져 있었어요~~ 민트초코퍼지 케이크~  위에 진득한 초콜렛이 덮여 있고 진한 민트크림과 부드러운 초코시트가 만나 너무나 맛있는 민트초코퍼지 케이크 였어요~ 민트다크마카롱도 3.000원인데 크기도 크고 두꺼웠어요!! 약간 바스러지는 꼬끄게 진한 다크초코가 아주 잘어울려요~ 한번에 크게 한입 먹으니 완전 맛있고 강한 민트초코 맛이 느껴져서 좋았어요! 그리고 이날 베스트 매력쟁이!! 민트아메리카노!! 산미있는 아메리카노를 좋아하는 저한테 완전 취향저격이였던 맛이였어요!! 역시나 민트에 진심인 사장님!! 최고에요~ 또 먹으러 갈겁니다!!!', 5, 1, 'GOOD', SYSTIMESTAMP);
