INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '민트색 러버 반민초파 인간이 방문한 민트하임 후기 일단 너무 좋아하는 민트색으로 꾸며진 카페라 너무 예쁘고 귀여운 굿즈들이 많아서 좋았어요. 반민초파로써 두려웠지만 민초파들을 이해하게 된 계기였습니다. 민트초코퍼지 쫀득하고 부드러워서 맛있게 먹었어요. 민트카페라떼도 일반 라떼보다 텁텁하지 않아서 좋았습니다.', 24, 0, 'GOOD', SYSTIMESTAMP);
