INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '언제 와도 기분이 좋아지는 민초단의 성지 같은 곳 민트하임!! 저번엔 민트오레오케이크를 먹었는데 이번엔 민트초코퍼지와 민트아메리카노에 도전해 봤어요 코끝에서 후 혀끝에서 화 하는 강렬한 맛에 이게 디저트지 싶네요 ദ്ദി*ㅁ*✧', 20, 8, 'GOOD', SYSTIMESTAMP);
