INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '민트하임 말그대로 민트 그자체인곳이에요 페인트도 민트색어디서 구하셨는지 배경도 민트민트 케이크 음료메뉴까지 민트로 가득하답니다!! 민트색 굿즈들고 함께팔구있구요 민트를 좋아하시는분들이라면 합정놀러오시는분들한테는 추천드립니다!! 커피랑 케이크 잘먹구 갑니다!!', 82, 15, 'GOOD', SYSTIMESTAMP);
