INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '민트초코 도오전 하고픈 분들 부담없이 커먼 맛있는 민초 치즈케이크, 샌드, 롤케익 이쁜 아이들이 많아요 굿즈구경까지!!넘 좋앗', 37, 2, 'GOOD', SYSTIMESTAMP);
