INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '민초단 극락가는 디저트와 음료만 파는 카페가 있다니,,,왜 이제 알았을까 싶네요!!! 현재 팝업도 하고있어서 구경거리도 많고 민트디저트가 다양해서 민초단끼리 오면 넘 좋을 거같아요 시원한 민트아메리카노도 거부감도 없고 무난하게 마실 수 있어서 추천합니다!!!', 407, 52, 'GOOD', SYSTIMESTAMP);
