INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '인테리어는 민트색과 파스텔톤 색감들로 아기자기하게 꾸며져 있어서 완전 여심저격스러운 분위기였어욤! 저와 집사 일행은 초코라떼, 민트 오레오 라떼, 밀크티를 주문했어욤 시럽이 밑에 가라앉아 있기 때문에 잘 섞어드셔야 해욤 민트 오레오라떼는 달달한 맛과 오레오 가루의 바삭함이 잘 어울렸어욤 민초가 생소한 저도 생각보다 맛있어서 더 뺏어 먹었네욤 흐흐흐 초코라떼는 초코시럽의 무작정 단 맛보다는 부드러운 느낌이 강해서 인위적인 느낌 없어 좋았어욤 밀크티도 얼그레이 향이 은은하게 나서 좋았어욤 민트 누텔라 케이크는 시트사이에 크림이 꾸덕하게 발려있어 정말 부드러워욤 크림 자체도 민트향이 느껴지고 약간의 초코향이 같이 느껴집니당 적당히 달달해서 그런지 이것도 순삭했어욤', 49, 8, 'GOOD', SYSTIMESTAMP);
