INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '민트컨셉에 진심인 사장님ㅋㅋㅋ이셔서 너무 독특하고 이색카페에요!! 남자친구가 민트를 좋아하고, 저는 반민초단이었는데 민트초코라떼가 너무 맛있어서 반하기 시작한 것 같아요,,😻 민트로만 유명한줄 알고 갔는데 귀여운 팝업스토어도 하고 있더라구요!! ㅎㅎ 서교 이색데이트로 딱이에용!!', 100, 23, 'GOOD', SYSTIMESTAMP);
