INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '특별한 민트초코 메뉴가 가득한 민초단 성지카페예요!!🥹💛민트 아메리카노 생각보다 은은한 단맛과 민트향이 커피랑 잘어울려서 너무 놀랐지뭐에요,,,민트우유도 괜찮고 디저트도 꾸덕하니 넘 맛도리였어요!', 47, 9, 'GOOD', SYSTIMESTAMP);
