INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '저도 민트 넘 좋아하는데 정말 기분 좋게 잘 먹었습니다!! 민트 아메리카노 시원하구 넘 맛나용 ㅋㅋㅋㅋ 같이 간 친구가 감기가 걸려서 요 근래 목이 답답했는데 민트 맛 덕에 시원해져서 넘 좋다구 했습니다 ㅎㅎ 민트초코 케이크도 달다구리 넘 맛나고 절대 반민초가 될 수 없는 맛이에요ㅠㅠㅠㅠ 특별하고 재밌는 방문이었습니다 다음에 또 갈게요!!💗', 87, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '홍대 이색카페 민트하임 방문했어요!! 민초단으로서 민초 컨셉의 카페가 있다니 너무 반가웠어요ㅋㅋ 입구부터 민트색이고 내부도 민트민트 하게 꾸며 놨네요~~♥️ 민트담은 음료와 디저트들이 그득하네요~ 감기 걸렸는데 민트덕분에 코가 뻥 뚫리는 기분이에요☺️  귀여운 굿즈들도 굉장히 많아서 구경하는 재미도 있고, 특별한 디저트 맛볼 수 있어서 좋아요! 홍대 카페 민트하임 추천이에요🌱', 30, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '가정집을 개조한 듯한 마당에 포도가 주렁주렁 달린 곳이 에요 ~^^ 합정에 이런곳이? 하면서 들어갔어요 ~ 귀여운 굿즈들도 있어서 구경하는 재미도 있었어요 ~  민트초코퍼즈케이크는 쫀득하면서도  민트향이 퍼지면서, 진한 초콜릿의 달콤함까지 민초단분들 박수칠 것 같아요^^단맛이 너무 강하지 않으면서 민트의 상쾌함이 있어서 부담스럽지 않게 즐길  수 있어요 민트판초콜릿은 오레오 쏙쏙 박혀있어서 맛이 없을 수 없어요 ㅋㅋㅋ  포장도  예뻐서 선물해도 괜찮겠어요. 반민초단분들은 초콜릿으로 먼저 민초단 입문을 시도해보시면 좋을것 같아요 ~ 청량한 민트 디저트가 가득한 민트하임에 서 눈가 입이 즐거운 시간이었습니다 *본 리뷰는 업체로부터 식사권을 제공받아 체험 후 솔직하게 작성하였습니다.', 40, 1, 'GOOD', SYSTIMESTAMP);
