INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '민초단이라면 꼭 오세요👽 아니어도 오세요 민초는 맛있으니까요😍 카페도 예쁘고 민초 디저트 천국이에요 사장님도 친절하시고 소품샵도 있어서 구경하기 조아요', 18, 2, 'GOOD', SYSTIMESTAMP);
