INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '민트를 너무너무 좋아하는 저로서는 천국이지만 반민초단분들도 즐길 수 있는 메뉴가 많은 민트하임이에용! 민트퍼지케익이 꾸덕꾸덕 맛있고 민트밀크티도 향이 너무 좋더라구용🥳🥳 일단 공간이 너무 예뻐서 앉아있기가 너무 신나고, 각종 귀여운 굿즈들도 판매하니 한번 꼭 들려보세용🥳🥳', 42, 4, 'GOOD', SYSTIMESTAMP);
