INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '토요일 오후 2시에 운 좋게 웨이팅 없이 방문했어요! 건물 외관부터 민트색으로 잔뜩 칠해져 있어서 찾기에도 수월했어요~ 내부에 스티커를 팔고 있었는데 팝업 중인 것 같더라구요! ㅎㅎ 메뉴판에 하트가 있는데 하트가 많을수록 민트 세기가 더 크다고 알려 주셨어요! 원래 약간 반민초단이었는데 카페 디저트가 넘 맛있어서 민초단이 되었습니다...💚 자주 방문하게 될 거 같아요!', 71, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '홍대이색카페 찾다가 민초단인 여친 강력추천으로 이끌려왔어요!  반민초단인 저는 살짝 쫄았지만 반민초메뉴도있어서 좋았어요ㅋㅋㅋ 민트나라온것처럼 민트민트하네요ㅎㅎ 초코케이크가 촉촉하고 부드럽고 찐한맛이라 반민초로 가시는분들은 강추해요👍 다른분들 리뷰보니까 민트아아는 반민초도 먹을만하다는데 담에 홍대올때 도전해보려구요😆 예쁜 이색카페 찾으시는 민초단 반민초단 모두에게 추천합니다!', 22, 5, 'GOOD', SYSTIMESTAMP);
