INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '와진짜 민트 너무싱기해요 처음와봣는데 민트메뉴진짜많아서너무신기했어요 ㅎㅎ 민트아아는 너무신기해서 한번쯤도전해보면 좋을거같아요🩵🩵🤭🤭👀👍🏻👍🏻👍🏻 메뉴 내부 인테리어도 너무민트색으로 되어있어서 좋더라구요~!! 다음에친구들데리고올게요 ㅎㅎㅎ', 102, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '민트초코를 사랑하는 모든 분들을 위한 특별한 카페를 소개해 드리려고 합니다. 바로 서교동에 위치한 ‘민트하임’이라는 곳인데요, 민트초코 디저트부터 음료까지 다양한 메뉴를 즐길 수 있는 민트 천국이라고 할 수 있어요. 민트하임은 홍대입구역에서 매우 가까워 접근성이 좋습니다. 홍대입구역 8번 출구로 나와 잔다리로6길을 따라 10분정도 걸어가면 쉽게 찾을 수 있습니다. 민트하임은 단순한 카페를 넘어 민트초코를 사랑하는 사람들의 커뮤니티 공간이라고 할 수 있습니다. 만약 당신이 민트초코를 좋아한다면, 민트하임에서 잊지 못할 특별한 경험을 할 수 있을 것입니다.', 63, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '민트에 정말 진심인 곳이에요! 메뉴도 정말 다양하고 개인적으로 민트오레오라떼 취향저격이었어요ㅎㅎ 민초 좋아하는 분들은 꼭 와봐야하는 곳.!', 36, 1, 'GOOD', SYSTIMESTAMP);
