INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '민트 민트 온세상이 민트인 민트카페입니다!🩵🩵🩵🩵🩵🩵 민트 좋아하시는 분들에게는 천국인 곳이네용! 구경할것도 많고 즐기기 좋았어용🩵', 21, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '외관에서부터 강렬한 민트색이 눈에 띄는 곳이에요! 민초단이여서 홍대쪽에 이런 민트 컨셉의 카페가 알았다면 진작에 왔을 것 같은데 늦게 알아서 지금부터라도 열심히 단골이 되어볼까합니다. 민크 향이 은은하게 나는 음료들과 꾸덕 맛있는 케이크까지 디저트 맛집이에요~ 일단! 민트초코 좋아하시는 분들은 서교동 카페 민트하임 꼭~ 오시는 걸 추천드립니다!! 🌱', 16, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '직원분 친절하시구요! 민초단이라면 꼭 와야할 카페!  민트초코 롤 케이크 넘 부드럽고 맛있구요 ~ 민트아메리카노 , 민트카페라떼 넘 특색있고 맛있었어요~ 카페 내부 분위기도 좋아서 만족스러웠어요 😃', 44, 3, 'GOOD', SYSTIMESTAMP);
