INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '민초단 모이세욧!! 음료랑 디저트에 은은하게 민트 추가를 할 수 있는 시대가 왔습니다 논민트 음료 디저트도 있지만 민트가 강하지 않아서 호불호 크게 안 갈릴 것 같아요 ㅎㅎ 지금은 귀여운 팝업도 같이 진행 중이라 소소한 볼거리도 있어요', 6, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '민트로 된 집이라는 이름답게 민트민트하게 해줍니다 갔던 기간이 보컬로이드 하츠네 미쿠 콜라보 기간이라 사람이 많아서 앉아있진 못하고😢 금방 나왔어요 민트 좋아하면 가볼만한 곳입니다', 21, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '귀여운 민트 카페! 이런 곳이 있는 줄 몰랐어요 ㅋᩚㅋᩚ 스티커랑 키링도 팔아서 구경하는 재미도 있는 곳! 아 그리고 생각보다 민트가 맛있는 음식이었더라고요??! 다음에 찐으로 민트 좋아하는 친구 끌고 다시 올 생각 입니다 >__<', 35, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '민트초코가 강하게 땡기던 날 홀리듯 찾은 이 곳 마침 콜라보 이벤트도 있어서 한정 메뉴도 먹어 볼수 있었다. 시원한 색과 은은한 단맛! 흔치 않은 컨셉으로 오랫동안 마니아들의 발길을 잡은 민트하임 앞으로도 계속 민트민트한 디저트들을 만들어 주길~', 35, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '꺅!  너무 귀엽잖아...민트 전문 베이커리카페. 온통 민트와 초코로 가득...캐릭터 굿즈들도 종류 다양하고 민트초코 주제로 여러가지 조각케잌도 진열장에 있다.  버터링쿠키사이에 필링 두툼한 샌드쿠키 6종 종류별로 샀고 민트판초코 한통하고 민초케잌 한조각 포장했다. 이처넌짜리 쿠키샌드 두개나 덤으로 넣어주심.  마카롱스러운 두터운 필링이 화~~~하고 민트맛 나서 더 좋았음.', 15, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '민트와 초코의 궁합은 찬성! 까페 자체가 민트민트한 컨셉이 확실한 곳이에요ㅋ특히 케이크는 꾸덕한 초코와 민트향이 적절히 어울려서 넘나 맛있었어요ㅋ (모든테이블이 요 케이꾸 주문했다는건 안비밀ㅋㅋ) 음료도 민트베이스가 있어서 호불호 갈리겠다 싶었지만 네버ㅋㅋ화한 치약맛의 민트가 아니고 기분좋게 민트향과 맛이나서 민트애호가가 아닌 나에게는 더 특별한 디져트였어요! 케이크에 가려져 잊을뻔한 대왕마카롱, 개인적으로 추천해요! 쫀득한 꼬끄가 진짜 맛있어요bbb', 34, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '한정 콜라보 메뉴를 노리러 갔는데 정작 먹고 프던 메뉴는 품절??? 어쩔수 없지 차선책 민트 밀크티! 파우더를 섞어 쭈~욱 의외로 민트맛은 약하고 초코맛이 강하다', 40, 7, NULL, SYSTIMESTAMP);
