INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '전에 방문하고 반해서 찜 해둔 곳 그ㅎ래서 강한 것을 도전했는데 나 생각보다 넘 강한것운 잘 못 먹는 군 하면서 재미있고 민트 컬러가 정말 아름담고 귀여운 것이 넘넘 힐링 되는 카페', 78, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '저 민트초코 별로 좋아하지 않는데 여기 있는 #민트오레오치즈케이크 #민트다크마카롱 먹어나서 맛있어요~~~ 민트초코 좋아하시는분들도 여기 가시면 좋아할거예요~ 분위기 다양한 디저트 서비스 다 좋아요~ 좀 더 강한 민트맛도 먹어보고 싶어요 🙏🏼🙏🏼🙏🏼', 11, 4, 'GOOD', SYSTIMESTAMP);
