INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '민트초코같은거 좋아해서 왔는데 넘 만족해용👍 가격도 생각보다 저렴했고 맛있었어요😋 분위기도 괜찮고 매장도 깨끗했어요!! 홍대오면 한번씩 들릴거 같아용😊💕', 119, 19, 'GOOD', SYSTIMESTAMP);
