INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '미쿠 콜라보로 방문했는데... 맛이... 별로입니다. 아이스크림에 츄러스로 추정되는 게 있는데 진짜 근본없는 맛이에요. 민초 아이스크림도 그냥저냥...', 33, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '민초파들을 위한 카페!! 사실 민초파vs반민초파 논란이 커지기 전에도 민트초코를 사랑하는 카페인 민트하임!! 민트초코를 기반한 다양한 메뉴들이 많아서 민초파라면 꼭 가보기를 추천하는 카페입니다 :)', 30, 0, 'GOOD', SYSTIMESTAMP);
