INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '큰딸과 큰아들이 방문해서 구경하고온 카페입니다. 사람이 엄청 많아 대기가 1시간 가까이 있었다고 해요. 외국에 유명한 캐릭터라고 하는데 귀엽네요. 민트 제품들이 다 맛있었다고해요.', 52, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '음식이 맛있고 맛없고 를 떠나서 2명이서 하던데 바쁜건 이해하겠지만 손님이 와서 자리를 잡았으면 주문을 받고나서 기다리던가 해야되는데 자리만 잡고 30분 넘게 기다리는동안 주문 안받음 하도 답답해서 내가 주문안받냐고 하니까 그제서야 받음 운영시스템 이면 몰라도 그것도 아니면서 먼저온사람이 뒷사람 보다 빨리 나오는건 이해 안됨  많은걸 시킨것도 아니고 음료랑 케이크 하고 쿠키만 한건데 뒷사람은 여러개 주문했는데 뒷사람이 먼저 나옴 제일 짜증났던게 마카롱 시키지도 않았는데 이게 나와서 멋대로 포함시켜서 결제하더니 직원실수라고 하고선 사과 한마디도없음  그냥 마카롱도 달라하니깐 안주고 말없이 3500원 결제함 뭐냐 그러니까 품절 이라함  3500원은 나머지 쿠키값 다신 안감  최악이었음', 0, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '친구 따라 갔는데 민트 디저트 다 맛있어요! 누텔라 케이크 서비스로 주셨네요🍰 여름한정으로 나오는 민트아이스크림도 맛있고 민트초코송이도 포장해왔어요🍫', 68, 18, 'GOOD', SYSTIMESTAMP);
