INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '오래전부터 와보고 싶었던 곳이었는데 드디어 방문했습니다ㅜㅜㅜ 매장에서 먹은 음료 두개랑 케익 두개가 마음에 들어서 싹싹 다 먹고서 포장도 두개 하구 나왔어요! 그리구 메뉴 고르는데 궁금해서 뭐 하나 여쭤봤는데요 사장님이 조근조근하게 친절히 설명해주셔서 기분 좋았어요ㅎㅎ 다음에 또 오고 싶어요.. 특히 제일 맛있었던 건 민트우유였습니다ㅠㅠ!! 홍대 올 때 마다 가서 한 메뉴씩 도장깨기 하고 싶어요!! 포장해서 온 판초콜릿이랑 프레첼도 너무 맛있어요!! 민트최고!', 7, 4, 'GOOD', SYSTIMESTAMP);
