INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '민트초코를 좋아하는 사람에게는 꼭 방문하면 좋을 곳중 하나입니다:) 민초아닌 바닐라 마카롱도 있었는데 그것도 달달해서 맛있었습니다~', 21, 10, 'GOOD', SYSTIMESTAMP);
