INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '대한민국 민트카페의 성지 민트하임!! 예전부터 오고싶었는데 드디어 왔어요~~ 평일저녁 늦은시간에는 웨이팅없이 들어왔고 종류도 넉넉하게있어서 좋았어요! 민트아메리카노는 향을 맡았을땐 일반 아메리카노였는데 한입마시면 민트맛이 스윽 느껴지구요!! 루이보스티는 향도좋고 맛있었어요💙 디저트로는 민트2단계인 민트오레오치즈케이크랑 민트4단계인 민트초코칩케이크 먹었는데 후자가 더 입맛에 맞고 맛있었어요!💪💪 전자는 민트랑 치즈가 애매하게 섞인느낌이였어용 오늘 롤케이크는 없어서 아쉬웠어요🥺', 14, 7, 'GOOD', SYSTIMESTAMP);
