INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '민트의 성지는 바로 민트하임! 민트 디저트 먹고 싶을 때마다 생각나요 ㅠㅠㅠ 민트 카페라떼랑 민트초코 퍼지 케이크 진짜 맛있어용!!', 61, 15, 'GOOD', SYSTIMESTAMP);
