INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '민트 좋아해서 처음 왔는데 사장님이 정말 친절하시고 한 명한명 챙겨주셔서 너무 감사했습니다. 케이크 고르는데 케이크의 맛과 특성을 고려해 추천해주셨어요. 그리고 원래 제가 골랐던 케이크도 서비스로 주셨습니다. 감사해요!!! 케이크도 너무 맛있고 음료수도 너무 맛있어요 행복한 시간보내고 갑니다♡', 76, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '민초단에겐 가끔씩 꼭 와줘야하는 성지 같은 곳... 진짜 민초 수혈하러 홍대 갈 때마다 꼭 다녀와요....❤ 사랑입니다 사랑💞💙💞💙 민초 오레오라떼 먹으면서 민트맛을 조금 더 강하게, 오레오맛을 조금 더 약하게 해달라구 말씀드려서 먹는데 그 화한 민트맛을 잊을 수가 없습니다 정말루❤❤❤❤ 제가 카페매니저가 직업일 때에도 다른 카페는 다 안 갔지만 여긴 계속 왔었어요💙💙💙', 54, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '☆ 성지순례 왔습니다 ☆ 이곳을 이제서야 방문하다니, 후회되고 개탄스러운 심정이 밀려오는 동시에 제 게으름을 반성할 따름입니다. 시식으로 속죄합니다 - 우선 <민트 아메리카노>로 입가심을 하였는데, 둘의 궁합이 좋더라구요. <민트 마틸다>는 오리지널 민트의 풍미가 느껴지는 부드러운 크림 케이크였습니다. 톡 쏘면서 상쾌한 민트 본연의 식감이 그대로 전달되어서 만족스러웠습니다. <민트초코 케이크>는 살짝 느끼하고 진한 초콜릿 맛이 상쾌한 민트향보다 더 진하게 남습니다만 민트랑 초코의 배율 맞추기가 쉽지 않은 것을 감안하면 환상적인 조합입니다. <민트송이>는 민트맛이 진하게 나는 초콜릿과 바스락거리는 과자가 중독성 있네요. - 이외에도 다양한 민트 디저트가 있어서 보는 것만으로도 행복했습니다', 4, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '민초단이 좋아하는 초코 맛보단 민트단에게 추천하는 카페에요! 민트한 향이 엄청 강해서 좋아요!!민트 덕후로서 너무 좋아하는 곳이에요! 판매하는 음료나 케이크 값은 괜찮은데 마카롱이나 초콜렛 칩, 초코송이 등은 비싼 편이여서 아쉬워요😭 그래도 민트하면 민트하임이니만큼 홍대 갈때마다 들리는 것 같아요:)', 31, 3, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '강경민트파의 눈높이에게는 부족하고, 일반 이용인들애게는 강한 민트카페. 여러 손님을 수용하려면 민트의 높이를 낮출 수밖에 없었겠지만, 오히려 이도저도 아닌 애매한 중간이 된 거 같아 조금 아쉬웠습니다. 진짜 민트파를 위한 카페 같았는데 ㅠㅠ', 114, 24, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '민트의, 민트에 의한, 민트를 위한 독립카페. 민초(초코)가 아닌 민트를 중심으로 돌아갑니다. 이탈리아의 명물인 민트우유를 마셔볼 수 있습니다. 근데 가격은 스톡홀름입니다.', 4, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '민트하임'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '민트의 끝판왕 민트의 천국 민트 좋아하시면 꼭 가세요! 그런데 매장은 생각보다 협소해요 그래서 옆 테이블이랑 너무 가깝고 의자가 불편하기는 했어요 그래도 민트가 너무 먹고 싶었어서 기분 좋게 먹고 왔어용', 81, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크예스플리즈'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '요즘 태닝키티 최애인데 너무 기여워요!! 재주문인데 항상 디자인 만족에 맛도 최고에요. 매번 친절하게 해주시고 초도 이쁜게 너무 많아서 좋아요~~', 8, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크예스플리즈'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '홍대 근처 도시락케이크 찾고 찾고 찾다가 고심 끝에 정한 곳이 바로 여기 케이크예스플리즈! 요즘 도시락케이크 디자인이 다 거기서 거기인데, 특히 이 귀여운 토끼 캐릭터 디자인이 있어서 요기서 주문했다! 픽업하러 갈 때 귀여운 초도 한가득 있어서 하나 골랐는데, 너무 많아서 하나 고르는 게 힘들었답니다..☺️☺️ 케이크도 맛있어서 꿀떡꿀떡 마시듯 먹었습니다 ෆ 홍대 합정 근처에서 케이크 찾으시면 츄천드려용 🎀👍', 50, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크예스플리즈'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '케이크 너무너무 기엽게 잘 만들어주셨어요!! 제가 생각한 디자인 그대로 제작되서 너무 기뻐요! 요청사항도 잘 들어주시고 다음에 또 주문할게요', 108, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크예스플리즈'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '사실 처음에 견적 듣고 생각보다 높은 가격에 살짝 놀랐지만 돈값 무조건 합니다… 미니 케이크 사이즈로 했는데 생각보다 꽤 커서 더 좋았고 이런 케이크들 자주 주문 제작 해봤는데 모양은 예뻐도 맛은 개차반은 곳 엄청 많아서 별 기대 안 하고 먹었다가 눈 커짐… 흑흑 다음에 또 올게요 ㅜ 덕분에 좋은 시간 보냈습니다 ~!', 6, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크예스플리즈'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '케이크 너무 이뻐요 사장님..🩷 이쁜 합정주변 케이크 집 찾다가 주문했는데 너무 마음에 듭니댜!! 한입케이크라 많이 남아돌지 않아서 좋고 디자인도 정말 이쁘지않나용..? 남자친구 생일이라 준비했는데 너무 마음에 들고 남자친구도 좋아했어요! 입짧고 디저트를 좋아하지않는 남자친구들에게 선물하기 딱..❤️ 매장도 너무 이쁘고 사장님도 너무 친절하셨습니다! 다음에 또 케이크 주문할게요 사장님 감사합니다..🩷🩷🩷', 36, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크예스플리즈'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '케이크 완성물 자체는 나쁘지 않았는데 1시 픽업 말했던 걸 2시부터 된다고 하셔서 2시로 했더니 픽업시간 5분 전에 30분 늦어진다고 말씀하시질 않나…. 뭐 따로 보상 해주시는 것도 없고 100일 기념 데이트인데 길바닥에서 30분 버리기만 했네요. 늦을 것 같으면 차라리 그냥 일찍 연락을 주시면 좋을 것 같아요.', 121, 26, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크예스플리즈'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '급하게 당일레 케잌 사러갓는데 디자인이 너무 귀엽고 특히 그냥 레터링이 아니라 입체적으로 해주셔서 너무너무 귀여웠어요. 그리고 크림이 레알 존맛탱인.... 진짜 먹고 너무 놀랫잖아요 솔직히 그정도로 맛있을줄 몰랐어요..', 41, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크예스플리즈'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '레터링케이크 여러번 해봤는데, 케이크는 예쁘나 타 업체에 비해 비싸요. 그리고 사장님 너무 안 친절하십니다.. 응대 능력이 떨어지시는 것 같아요. 기분좋은 선물 하고 싶어서 방문한 곳인데, 주문할때도 케이크 찾을때도 기분이 상했어요😂 레터링 주문제작하는 곳은 많은데요.. 굳이 재방문 계획 없어요ㅠ', 81, 13, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크예스플리즈'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '버터크림이 아닌 크림치즈라서 맛있어요 🤩 도시락 케이크치고 좀 비싼 거 같은데 예약 없이 레터링 케이크 구매 가능해서 좋습니당', 19, 8, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크예스플리즈'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '인스타그램 사진에 케이크들이 너무 예뻐서 두개 주문 했습니다ㅎㅎㅎ 찾아와서 케이크들 보니 역시 원하는대로 이쁘게 만들어주셨어요 친구들이 너무 좋아하네요 주문 상담부터 방문때 직원분들도 친절해서 필요할때 또 주문해야겠습니다. 보기좋은케이크가 맛도 좋더라구요!!', 55, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크예스플리즈'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '진짜 엥간해서 리뷰 안 쓰는데 여기 ㄹㅇ 찐임. 수많은 레터링 케이크 해봤지만 여기만큼 정갈하게 이쁘고 트렌디한 곳이 없음. 케이크 맛까지 완벽하게 맛있음!!ㅠㅠ💙 대부분 예쁘면 맛이 부족하거나, 맛있으면 디자인이 덜 한데, 여기는 두개 다 완벽!💕 내용물 혜자임 재료를 안 아낌!! 그래서 맨날 케예플만 찾게 됨요! 벌써 다섯번째인데 매번 오백퍼 만족!!👍 사장님이랑 직원들 다 너무 친절하고!! 지나가는 사람들 다 매장 너무 예쁘다고 하고 지나가더라,, 여기 진짜 갓벽! 나만 알고싶어서 애껴두다가 이제야 리뷰씀,,ㅋㅋ 제발 오래도록 해주세요💙', 33, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크예스플리즈'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '🍓2번째 이용 후기🍓 일단 항상 예쁜 케이크 디자인을 연구해주시는 사장님께 정말 감사드려요. 워크인으로도 매번 이렇게 예쁜 케이크를 살 수 있다는게 참 감사합니다. 귀엽고 이쁜데 맛도 장난아닙니다. 옹골찬 케이크.. 원래 먹어보고 맛있으면 하나만 계속 사먹는 성격이여서 앞으로 모든 케이크는 여기서만 살 것 같습니다. 항상 감사합니다❤️', 25, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크예스플리즈'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '친구가 표현을 이렇게 잘 하는지 처음 알았어요 그렇게 하오를 좋아하다니💙 매우 기쁘고 넘 예뿌게 만들어주셔서 감사하고 친구 픽이 데뷔해서 친구가 행복해해서 좋네요  ◡̈ 앞으로도 여긴 내 픽💙', 58, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크예스플리즈'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '4,29일날 케익하우스짱 방문했습니다 초코케익 제일 작은거 사고 생크림꽈배기랑 피자빵 이렇게 샀는데 38500원이 결제된걸 이제 알았아요.. 서비스를너무 많이 주셔서 확인도안하고 인사하고 나왔는데 .. 뭐죠 ㅠ', 26, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크예스플리즈'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '친구 생일로 포토케이크 구매했어요 🩵 너무 맘에 들어하고 사장님도 왕친절 ㅠㅠ 사진도 잘 나온거 확인도 해주시고!!! 다음 케이크도 무조건 여기서 구매하려구요 감사합니다 🙇🏻‍♀️🫶🥹', 18, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크예스플리즈'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '아빠 생신 케이크로 특별하게 하고싶어서 주문했는데 원하는 디자인데로 똑같이 만들어주셨어요!!! 안에 오레오 들어있고 겉에는 크림치즈인데 너무 맛있어서 다음에 또 주문할려구여!! 너무 만족합니당!!', 35, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크예스플리즈'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '급히 케이크 살 일이 있어서 문의했더니 당일케이크 준비되어 있다고 안내받고 픽업완료!! 귀염뽀짝한 디자인에 맛은 물론이고 퀄리티가 너무 좋았어요 완전 만족 만족 >.< 친절한 사장님 덕분에 즐겁게 파티했어용💕', 80, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크예스플리즈'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '크기 정말정말 작습니다 손크기 아니고 손바닥 크기만해요 제가 사본 도시락 케이크중에 크기 대비 가격 젤 비싸요..  케이크 지름이 15cm도 안되는데 당일 케이크 가격은 28000원 이에요ㅎㅎㅎ..(맨아래칸)', 48, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크예스플리즈'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '센스있고 맛있는 웨딩 레터링 케이크 덕분에 친구가 아주 좋아했어요 ㅎㅎ 감사합니다 :) 합정 레터링 케이크로 주변에 추천해야겠어오 ㅎㅎ', 15, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크예스플리즈'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '도시락케이크인데 거의 3만원대. 저렴하지 않는 가격이나 이전에 했던곳은 휴무여서 그래도 예약하고 픽업하러 갔는데 손님을 보고도 무시. 픽업할수 있는 공간이고 따로 안에서 먹거나 할수 없는데 왜 왔는지 찾아가시는건지 묻지도 않음. 노래도 너무 크게 틀어놓는게 말시키말라는 암묵적 표시 같음. 맛이 어떻고를 떠나서 서비스가 너무 불친절함', 13, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크예스플리즈'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '케이크하면 무조건 케예플이쥬🎂 주변 지인들 생일때마다 특별한케이크 선물해주는데 만족도 100%에요!! 항상 맛있는 케이크 만들어주셔서 감사합니다🙏🏻💕', 17, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크예스플리즈'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '먼저 케익 외형은 주문한 대로 잘 제작해주셨으나 주문 접수 때부터 글에서도 느껴지는 불친절함이 있었는데 픽업시에도 다르지 않아 불쾌했습니다. 맛과 서비스로는 지불한 비용과 기다린 한 달이란 시간이 아깝단 생각이 들었습니다.', 25, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크예스플리즈'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '케이크 잘안먹는데 특별한날이라서 주문해서 먹어본건데 그냥 프랜차이에서 사먹던 케이크맛이랑 너무다르고 심각하게 맛있어서 지금까지도 케이크 계속 주문해먹고있어요ㅠㅠㅠ빵 안좋아하는 취향까지 바꿀만한 맛이예요 최고예요!', 28, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크예스플리즈'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '픽업하러 갔는데 가게 외관부터 인테리어까지 눈에 확 들어와서 이뻤어요! 사실 요새 케익샵 많아서 디자인은 다들 잘하셔서 맛이 중요한데 여긴 ㄹㅇ맛이 좋아욥... 저 갔을때 다른 손님들 있었는데도 친절하게 해주셔서 좋았어여', 27, 0, 'GOOD', SYSTIMESTAMP);
