INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크예스플리즈'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '제가 웬만하면 리뷰 잘 안올리는데 여기는 진짜 맛있어서 감동먹고 올려요 케이크가 너무 앙증맞고 귀엽고 예뻐요! 보통 이런 주문제작 케이크집 맛 없는 곳 많은데 여긴 진짜 크림치즈 맛이여서 너무 맛있었어요! 다음에 또 주문할꺼예요.(진지해요)', 68, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크예스플리즈'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '처음으로 케이크 주문해서 먹어봤는데 진짜 너무 맛있어서 그자리에서 흡입했어요!! 크림치즈도 별로 좋아하지않는데 여기 케이크는 다르더라구요 앞으로 케이크는 무조건 여기서만 주문하려구요^.^ 글구 사장님 너무 친절하세용 자주올게요❤️', 73, 12, 'GOOD', SYSTIMESTAMP);
