INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크예스플리즈'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '벌써 세번째 주문이에요! 사장님도 친절하고 케이크 와인이랑 먹으면 진짜 맛있어요 솔직히 이런케이크 별로 안좋아하는데 여긴 맛있고 이뻐서 재주문하게되네요 또 이벤트있으면 주문할께요', 61, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크예스플리즈'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '주문사항 상세하게 답변해주시고 디자인 화려하고 귀여웠어요ㅎㅎ 초도 귀여운거 많아서 고르는데 한참 골랐네용 하루 주문량 정해져있어서 사장님 엄청 바쁘시던데 급한분들은 주문 미리 하셔야할듯!', 37, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크예스플리즈'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '여자친구 생일케이크 픽업을 갔는데 , 남성 직원분께서 실수로 떨어지려는 케이크 옆면을 손으로 붙잡았고 저희가 봤음에도 불구하고 아무런 사과도 없이 여자 직원에게 넘겨 찌그러진 케이크 옆면을 다시 덧칠하셨습니다 코로나 시국에 그냥 손에 닿은걸 포장해서 주시네요 집에 도착해 케이크를 확인해보니 덧칠한 케이크조차도 옆으로 뭉게져서 제 모양을 내지 못했습니다 이후 저희가 카톡으로 연락을 드렸더니 그제서야 사과를 하셨고 여차저차 사과를 받았지만 특별한 날에 44000원 내고 남이 만진 케이크를 받고서 기분만 상했네요 감사합니다', 116, 23, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크예스플리즈'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '여자친구 생일 케잌 주문했는데 까다로운 주문ㅇ었는데도 친절하게 응대해주셔러 너무 감사합니다 :) 예쁜데 맛도 너무 맛나서 감탄하면서 먹었네요~ 또 주문할께요 🙂', 33, 0, 'GOOD', SYSTIMESTAMP);
