INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정카페 웨하로스터스'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '아아랑 쿠키나 레몬파운드 세트 먹었어요. 세트로 팔아서 조금 더 싸게 먹을 수 있었어요. 레몬파운드 케이크는 부드럽고 제스트가 위에 올려져 있어 상큼하게 먹었구요. 아메도 원두를 고소, 산미, 디카페인으로 선택할 수 있어 좋았어요.', 2, 4, 'GOOD', SYSTIMESTAMP);
