INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정카페 웨하로스터스'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '아이스아메리카노(5,500), 웨하라떼 디카페인(7,800) 시켰어요!!! 커피 양이 진짜 많아서 좋았어요 ㅎㅎ 테이블 간격도 괜찮고 트인 창문이라 안 갑갑하고 굿 무엇보다 개귀여운 따랑이가 있어요 너무 사랑스러워요……. 수다 떨기 좋고 좌석들도 꽤나 편해서 만족스럽습니다! 커피도 달달하니 맛있었어요 디카페인 있어서 굿 👍🏼 키오스크 셀프주문입니다!', 69, 17, 'GOOD', SYSTIMESTAMP);
