INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정카페 웨하로스터스'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '사장님이 커피에 진심인듯한 카페입니다. 귀여운 댕댕이 보러왔다 커피 맛에 반하고 갑니다(너무 맛있어서 원두도 구매해버렸구요) 베이킹도 직접 하시는 듯 해서 다음 방문에는 베이커리도 맛보고싶네요. 합정의 조금 조용한 쪽에 위치하고있어 여유롭게 쉬어갈 수 있어서 좋네요.', 37, 2, 'GOOD', SYSTIMESTAMP);
