INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정카페 웨하로스터스'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '만족스러운 베이커리가 정말 인상적이었어요. 레몬파운드케잌의 상큼한 맛이 참 좋았고, 커피와 함께 먹으니 더욱 맛있게 느껴졌어요.', 44, 6, 'GOOD', SYSTIMESTAMP);
