INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정카페 웨하로스터스'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '웨스티가 꿈의 강아지라 이수역 웨하로스터스에 열번가까이 갔어요ㅠㅠ 갈 때마다 멈머가 없어서 섭섭했는데 웨하라떼 진심 심각하게 맛있어서 행복했어요.. 또간집 인터뷰하면 여길 말해야하나 고민할만큼 라떼 맛집이에요 ㅎㅡㅎ 웨스티 너무 보고싶어서 합정까지 찾아왔는데 이수보다 넓고 깨끗하고 드디어 만났어요!!! 웨스티 좋아하시면, 라떼에 진심이라면, 편안하고 넓고 조용한 카페 찾으신다면, 합정에서 약속 있다면, 완전 추천입니다 :)', 126, 26, 'GOOD', SYSTIMESTAMP);
