INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정카페 웨하로스터스'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '너무 만족스러웠어요. 같이 간 친구가 추천해준 아이스 아메리카노 한 잔으로 알게 된 곳인데 정말 맛있게 마셨어요. 가게도 깔끔하고 조용해서 좋았어요.', 19, 2, 'GOOD', SYSTIMESTAMP);
