INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '이런 크레페를 먹어보고싶었는데 찾아보다가 인생크레페를 발견해서 방문했어요! 어떤걸 먹어야할지 너무 고민되더라구요ㅎㅎ 젤라또,생크림,딸기는 꼭 들어간걸로 먹어보고싶어서 고민이 많았지만 잘 골라서 예쁜 크레페를 맛나게 먹을 수 있었어요ㅎㅎ 목이 말라서 석류오미자아이스티랑 맛있게 먹었어요!ㅎㅎ', 88, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '✏️ 한줄평 - 신선한 생과일로 즉석에서 만드는 고퀄리티 크레페 🏠 공간 - 아담한 매장이지만 깔끔한 분위기. 크레페 만드는 모습을 바로 볼수 있는 오픈형 주방. 내부에서 먹을 수 있는 테이블도 있습니다 🥣 음식 - 떨기 젤라또: 주문과 동시에 크레페 부터 만들고 딸기와 바나나를 커팅해서 넣습니다. 거기에 젤라또 넣고, 싸면 끝. 생과일이라 식감이나 신선함 좋고, 젤라또도 퀄리티 좋아요. 겉에 바삭한 식감까지 가격은 좀 있지만 재료와 맛이좋으니 인정! 🙏 서비스 - 너무 친절하시고, 매장도 깨끗해요~', 4, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '수플레 먹으려다 웨이팅 있어서 지나다가 본 크레페집이 아른거려서 급 계획 체인지로 발걸음돌려서 방문해서 먹었는데 오우얏 맛도리였습미당ㅎㅎ 치즈케잌 한덩이 추가하길 잘한거가태여 맷도뤼~~~ 또 먹으러 가고파요 ㅎㅎ', 26, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '크레페 정말 좋아하는데 반죽에 메밀..?이 들어가서 그런지 쫀득 바삭 맛있었어요 토핑도 보이는 곳만 뭉쳐서 넣어주시는 게 아닌 안쪽까지 골고루 넣어주셔서 좋았습니다', 69, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '친구가 데려와준 크레페 가게!! 가보고 싶었는데 들리고 온 후기.. 정말.. 정말 너무 맛있었어요 .. 무엇보다 제 마음대로 재료를 고를 수 있는 점이 너무나 좋았습니다 🥹❤️ 그리고 제가 바나나 알러지랑 더불어서 과일을 안 좋아하다 보니 빼주실수 있는지 여쭤봤는데 흔쾌히 빼주셔서 매우 감사했습니다... 그런데도 이렇게 맛있다니 반칙 아닌가요... 다음에 또 방문하겠습니다.. 지나가다 지나가다 혼자서 먹기도 좋은 것 같아오 !!', 65, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '사장님인지 짧은 단발 직원분. 굉장히 불친절하십니다. 기다리던 손님 입장에서 되게 무서웠어요. 안에있던 사람들이 다 눈치를 볼 정도로. 근데 크레페는 잘 만드십니다. 두번은 안 갈듯요', 36, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '홍대 핫한곳인지 사람꽉찼어요. 아이들은 좋아하는데 크레페가격이 만만치 않네요. 1인1메뉴 필수 아메리카노는 맛없어요.음료 주문하실분 다른 음료주문하세요. 컵에서 유자향이 나요.ㅠ', 30, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '진짜 구라안치고 인생크레페 ㅎㅋㅎㅋ 왤케.. 맛있어요 진짜..? 진짜 리뷰안달고 저만알고싶은 크레페예요.. 나오는 노래도 힙하고 알바언니도 힙하신데 과한 친절없이 그냥 휘리릭 슉 만들어주시는데 되게 디저트 맛집 고인물 같은.. 그런 맛이예요.. 하 또먹고싶다.. 장사 잘되셔서 오래계셔줬으면 좋겠는데 나만먹고싶어요 ㅠ', 25, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '홍대에서 정말 유명하다고 해서 찾아간 크레페 맛집❤️❣️ 딱 하나 남아있는 크레페 재료였다는데 다른건 다 솔드아웃이라서 딸기크레페를 먹었습니다! 딸기와 딸기 젤라또를 골라서 먹었어요. 아이스아메리카노는 터치커피여서 커피맛이 쓰지 않았고, 크레페가 엄청 바삭바삭해서 먹는내내 입이 즐거웠어요❤️ 찾아가서 먹을만한 크레페였던거 같아요😍 다음에 또 홍대가면 꼭 다시 먹어보려고요✌️👍', 28, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '홍대 갔다 찜해놓은 곳 아들이랑 갔는데, 역시 넘 맛있네요. 빠삭하고.. 내용도 고를수 있고 암튼 맛나요. 담에  재방문하고 싶다네요.', 14, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '정말 최악… 사장님 대응이 정말 별로였어요 손님있는데 욕설쓰시고 다시는 안 갈 것 같아요!!!!!! 여러분 가지 마세요~~~~', 29, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '크레페를 처음 먹어보는데 인생크레페에서 처음 먹어보고 푹 빠졌어요 가격도 착하고 애기입맛인 저한테 딱이였어요~ 다음에는 다른 메뉴로 먹어보려구요^^ 잘 먹었습니다! 또 올게요!', 39, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '되게 맛있다고 해서 기대하고 갔는데 기대 이하였어요... 맛이 없는 건 아니지만 다른 크레페랑 맛이 비슷했고 가격도 좀 있는 편이라 가성비 있다고 느껴지진 않았습니다.... 매장도 넓은 편 아니구 음식도 늦게 나왔어영... 그래도 우유에 빠진 초코젤라또? 이 아이스크림은 다른 곳에 비해 독보적으로 맛있었던 거 같아요!! 🍦', 32, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '크레페 먹을땐 멀어도 맨날 여기만 와용… 진짜 맛있고 먹기도 편합니닷 크레페가 바삭바삭한데 또 쫀득해서 차가운과일이랑 너무 잘맞아요 🤤 항상 번창하셨으면 좋겠습니당', 16, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '지난 겨울에 우연히 방문했다가 웨이팅을 거의 40분을 하면서 먹었던 기억이 있습니다. 오늘 지나가다가 우연히 또 이 앞을 지나게 되었고, 오늘은 웨이팅이 없어서 얼마 안기다리고 바로 받았습니다. 가격은 뭐 신경 안쓰지만, 음료 부분은 필히 개선해주시는게 좋을거 같습니다. 음료 한잔 가격에 컵사이즈 작은거? 얼음 갯수 적은거? 그렇다고 칩니다. 하지만 인간적으로 물 양을 왜이렇게 안넣으시나요? 저번에도 그렇고, 이번에도 그렇고, 음료 딱 받아서 마셔보면, 너무 달고, 너무 씁니다. 물을 아끼려고 그러나 하는 생각이 들 정도로 심각합니다. 이 부분은 개선해주시길 바랍니다. 너무 꽉 채워서 표면장력으로 간신히 버티는 정도는 아니여도, 적당히는 넣어주시는게 좋알거 같네요.', 7, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '도우도 바삭하고 아이스크림도 쫀득하니 맛있어요!!개인취향대로 커스텀할 수 있어 좋았습니다! 매장도 꽤 넓어서 먹고 갈수있어 좋았어요~홍대한복판에서 먹으면서 가기 좀 그랬는데🥹 잘 먹고 갑니다!!', 123, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '크레페 구성을 맘대로 다양하게 정할 수 있어 좋았어요! 매장이 깨끗하고 시원해서 친구 가족 애인과 시간보내기 좋아요♡ 너무 달지 않아서 단 걸 잘 못 드시는 사람들도 맛있게 먹고 갈 수 있습니다! 담에두 또 오고 싶어요', 45, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '크레페처돌이인데 맛있우요!! 아이스크림 종류도 많고 만드시는곳도 옆에서 보이는데 정성가득입니다💕 매장도 넓어서 요즘같은 날씨에 앉아서 먹기 좋습니다!!', 19, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '몇 번째 오는 건지 셀 수 없을 정도로 왔던 것 같아요... 진짜 올 때마다 너무 맛있게 먹고 갑니다🥹 누텔라+딸기+바나나+젤라또 조합이 진짜 찐이에요. 진짜 맨날 먹고 싶은 맛( ´•̥-•̥` )', 25, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '크레페집 많이 없어서 검색해 보고 방문했어요~ 이거저거 추가하면 간단한 디저트로 생각하기엔 가격이 좀 올라가긴 하는데 크기가 커서 배불렀어요. 맛있게 잘 먹었습니다😋', 80, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '홍대에 여기 크레페가 맛있다고 해서 방문해봤는데 역시 유명한 이유가 있었네요| 젤라또크레페 먹어봤는데 다음번에는 생크림도 먹어봐야지요 너무 맛납니당!!', 43, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '맛있다는 소문듣고 아이랑 와봤는데 크레페중 최고의 맛집이네요~~^^바삭바삭 아이스크림도 맛있어요~~홍대올때마다 들릴것같아요~~잘먹었습니다^^', 7, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '가게 이름처럼 인생 크레페네요 ! 크레페 좋아해서 다른 가게도 많이 다녔는데 여기는 바삭함이 제일 살아있어요 젤라또랑 아이스크림 등 옵션이 많은데 저는 기본 누텔라생크림바나나딸기로 먹었는데도 맛있게 먹었어요 집 가까우면 매일 먹고 싶은 맛이에요 😍', 94, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '홍대에서 유명한 크레페집이래서 다녀왔어요🩷 앉아서 크레페를 먹을 수 있는 좌석도 있답니다! 하지만 바로 옆에서 사장님분들께서 만들고 계셔서 꽤나 덥고 습해요ㅠㅠ... 가격은 저렴하다고 생각되지는 않지만, 꽤나 맛있던! 저희는 젤라또 바나나 딸기 크레페를 먹었는데, 요거트 젤라또랑 꼬옥 같이 드셔보셨으면 좋겠어요..🫧 너무 맛있더라구요.. 단거를 잘 못 먹는 커플인데, 남자친구가 정말 잘 먹었어요😋🌹', 49, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '먹어본 프레페 중에 제일 맛있었어요💗 주문하자마자 만들어서 더 따끈따끈하게 먹을 수 있습니당 누텔라🤎생크림🤍생딸기🍓바나나🍌맛 없을 수 없는 조합이에요 ( ˶˙ᵕ˙˶ ) 맛있어서 자주 가는 곳이에요!', 15, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '크레페가 살짝 바삭바삭한 게 진짜 맛잇어요😋 날씨 더워서 시원한 복숭아 아이스크림으로 골랐는데 생각보다 훨씬 맛있어서 담에도 이걸로 시켜먹을 것 같아요!!!', 48, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '지나가다가 맛있는 냄새가 나서 참새가 방앗간 들리듯 자연스레 들어왔네용 ㅎㅎ 대기는 좀 걸렸지만 그만큼 정성이 들어가서 진짜 맛있어요!!!!!', 63, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '인스타에서 보고 먹어보고싶어서 방문했는데 식후 디저트로 너무 좋은 거 같아요 !! 맛있어서 다 먹느라 사진을 못 찍은건 안비밀...ㅎ.. 다음에 또 올게요 !!', 22, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '예전에 왔을 때보다 많이 빈약해짐. 일단은 바나나 양도 그렇고, 아메리카노 시켰는데 컵 주변에 이물질 있는 거 마시는 중반에 알아서 찝찝함. 일 하시는 분들 너무 시끄러움.(이건 가게가 작아서 좀 갈리는데) 앉아서 드시는 거 아니면 그냥 아메리카노는 시키지 마세요.... 돈 아까운데 맛 없는 거 먹으면서 살 찌는 기분 오래 앉아 있을 거 아니면 비추. 화장실도 고장났다고 함. 홍대에 어중이 떠중이 많아서 그런지 예전보다는 별로임.', 40, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PARKING');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '크레페에 들어가는 재료를 하나하나 골라담을 수 있어요. 특히 딸기재료같은경우 냉동딸기가 아닌 돈을 조금 더 추가하여 생딸기를 쓸 수 있단점이 매우 좋았습니다. 전체적인 식감은 바삭보다는 부드럽습니다. 누텔라를 좀 더 추가하면 꾸덕한 식감도 기대할 수 있을거에요', 14, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '가게이름 그대로 제 인생크레페 입니다. 오래 기다렸다 먹었던지라 맛만 없어봐라 콱 이런 마음이었는데 한 입 먹고 봄눈 녹듯 노여움이 사라졌어요. 왜 1인 1크레페하고 있었는지 알겠더라고요. 다음에는 각자 하나씩 주문할거에요.', 124, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '키오스크 주문 후에도 20-30분 기다려서 먹었어요! 크레페 부드럽고 뉴텔라 생크림도 적당히 들어간게 맛있네요~ 바나나 딸기도 얇은 슬라이스로 들어간게 좋아요 인생크레페라고 할만함 👍', 2, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '젤라또 크레페 시켜서 스푼 요청했는데 없다고 하시면서 이유를 길게 설명?하셨어요 작게 말하셔서 잘 못알아들었는데 대충 나눠먹지 말라고 하신 거 같아요 둘이서 두개 주문했는데?ㅋ🫠 기분 나빴고 덕분에 앞니 시리게, 불편하게 먹었습니다🤢 크레페 양 적어졌고 맛도 달라졌어요', 16, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '크레페 하나에 5분정도 걸려서 대기를 이십분 정도? 했는데요 진짜 한입 먹고 너무 맛있다고 얼마든지 기다릴수 있다고 생각했어요 ㅠㅠ 크레페가 어쩜 이렇게 바삭바삭 맛있나요 ㅠㅠ 홍대 가면 필수로 들려야 합니다,,,! 다만 사장님 혼자 만드시니까 여유있게 기다리실 분들만 가기로 해요!', 120, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '사람 많아서 대기가 좀 있어요 누텔라 딸바 생크림에 요거트 젤라또 추가인데 딸기랑 젤라또가 상큼해서 덜 질려요 근데 바쁘셔서 깜박 하셨는지 친구 젤라또를 초코로 시켰는데 바닐라로 주셨어요🥹', 11, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '가격싸고, 양도 적당하고 다 좋은데, 조금 오래 걸립니다ㅎㅎ 아이스티는 양대비 가격이 비싼 편인데 물이라도 좀 꽉 채워주시는게 좋을거 같아요ㅋㅋ받고나서 엥 이게 뭐야? 라는 말이 자동아로 나왔습니다', 92, 25, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '진짜 인생크레페입니다!! 우연히 들어갔는데 진짜 오랜만에 맛있는 크레페먹었네요!! 😍운이 좋았네여!! 한분이서 하셔서 대기시간이 있는데 마침 대기자가 몇없어서 맛보고 갔습니다!! 내부도 청결하고 깔끔하고 담에 홍대가면 꼭 또 가봐야겠어요💕', 43, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '그럭저럭 먹을만함 1.사장님들이 초짜이신지 손이 느리심 (정말....) 2.재료가 푸짐하게 들어가진않음 3.종류가 적어 아쉬움 굳이 또 먹진않겠지만 근처지나가다 사람없으면 먹을거같기도', 94, 25, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '바삭하니 맛있어요 한국인 스타일 크레페 ㅎㅎ 전 눅눅한거 안좋아하는데 바삭해서 좋았어요 근데 먹다보면 밑에 부분에 습기차서 밑에부분은 말랑해져요 바삭 말랑 둘다 느껴볼수있어요 딸기도 너무 시렵지도 않았고 맛났어요😊 제가 시간이 없어서 후딱 먹고간게 아쉽네요 좀 맛을 음미하면서 먹고 싶었는데 아무튼 잘먹었습니다.~', 32, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '크레페 불모지인 한국에 내려온 한줄기의 빛 .. 일본에서 여러번 먹어봤지만 정말 일본 안 가도 될 정도의 맛입니다. 반죽은 시간이 꽤 많이 지나서 먹었는데도 콰삭! 하고 씹힐 정도로 바삭함이 오래 유지되었고 두께가 얇아서 반죽 맛 보다는 속재료의 맛이 눈에 많이 띄었어요! (반죽이 맛이 없다는 뜻이 아님 진짜 눈 튀어나올 정도로 맛있음 •••) 속재료가 가득 가득 들어있는데도 생크림의 느끼한 맛이 전혀 없고, 하나를 다 먹을때까지 질리지 않는 크레페는 처음이었습니다. 참새가 방앗간 못 지나치는 것처럼 지나갈때마다 들를 것 같아서 큰일이에요 .. 포장해서 가져오는 바람에 사진이 예쁘지 않아 속상하지만 인생 크레페 모르는 사람이 없길 바라며 글 남겨봅니다 .. 🥲 인생 크레페를 모르는 것은 인생에 큰 손실이에요', 44, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '부드러운 아이스크림, 상큼한 딸기, 달달한 초코 거기다 치즈 케이크 한 조각 까지! 순식간에 당충전 완료! 하루 스트레스를 잊게 만든다~', 49, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '살면서 먹어본 크레페 중에 제일 맛있었음. 크레페가 바삭해서 눅눅하지 않고 젤라또 선택지가 다양함. 날짜나 시간대 안 맞아서 가야지  맘 먹곤 3달 정도 못 갔는데 대만족', 29, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '사장님이 진짜 친절하세요.  손님들이 올때마다 대기시간 설명해 주시고 정말 친절하세요. 너무 맛있어요. 재방문하겠습니다. 사업번창하세요.', 56, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '크레페 1개 만드는데 5분 정도 걸려서 웨이팅이 조금 있었어요😢 사장님이 주문 전에 안내해주세요♡!! 요기 크레페는 처음 먹어보는데 기다린 보람이 있는...✨️', 126, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '개인이 재료 선정도 할 수 있어서 좋았고 크레페가 너무 딱딱하지않고 적당히 바삭한느낌이라 맛있었어요 ㅎㅎ 요거트젤라또, 생딸기 바나나, 뉴텔라 들어간 크레페였는데 괜찮더라구요 ㅎㅎ 다른하나는 망고젤라또 크레페 였는데 엄청 얇게 초코가 발려있는데 좀 새로운 맛 느낌?? 신선했어요 ㅎㅎ 매장도 깔끔해서 괜찮아요 😊 크레페를 겨울에 밖에서 먹으면 딱딱한 느낌이 강해서 안사먹곤 했는데 매장에서 먹을 수 있는 장점을 갖고 있어요 ㅎㅎ 달콤한거 땡기실때 괜찮을 것 같아요', 54, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '맛없을 수 없는 베이직한 조합, 생각한 맛 그대로였습니다. 나쁘지 않았어요. 하지만 냉동딸기는 비추천해드립니다. 냉동딸기중에 약간 맛이 이상한게 있었어요. 생딸기로 추가한 친구는 잘 먹었습니다', 50, 10, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '화가 나신 것 같이 대하셔서 당황스러웠어요,,,들어가기만 했는데,,,그래도 맛은 있어서 굿 ㅎㅋㅋ 젤라또는 굳이 안 먹어도 될 것 같아용', 47, 0, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '하나 만드는데 10분 걸리는듯.. 2~30분 걸릴 수 있다더니 대기 한시간 했네요(과장아님) 동대문 크레페할아버지 막 생각나고 휴 알바라도 뽑으심이 ㅜ 손님시간은 어쩌라고', 81, 13, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '30분 기다려서 먹을만해요! 파르페 정말 맛있고 깔끔하게 먹을 수 있어서 좋아요:) 반죽이 떨어지면 잠시 품절인 것 같으니 빨리 가서 먹는 걸 추천! 생크림을 안 넣어 먹었는데 살짝 후회돼서 다음엔 생크림도 넣으려구요😋 기본 누텔라는 맛이 별로 안 느껴지니 추가를 추천합니다😉', 78, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '맛있지만 누텔라를 추가해도 맛이 안 나네요ㅠㅠ 과일은 바나나보단 딸기만 넣는 게 더 맛있는 것 같아용 다음엔 최고의 조합을 도전해보기로..!😊', 12, 0, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '요거트가 왤케 상콤하지 했는데 청포도맛이어서 그랬어요 ㅋㅋㅋㅋㅋ 크레페에서 생크림은 뺐어요 그래도 굿. 생크림누텔라 다 넣은 친구는 너무 달아서 먹기 힘들대용', 32, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '인생크레페'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '크레페 파는곳 거의 못봤는데 우연히 지나가다가 먹어봤어요 빠삭빠삭하고 요거트아이스크림 찐이고 정말 맛있었어요 제발 없어지지마세요 ㅜㅜ', 23, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '대충유원지'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '매장 인테리어가 잘 꾸며져 있었고, 음료들이 맛있었습니다! 테이블마다 차이가 있을텐데, 제가 앉았던 곳은 사알짝 불편하였긴 하였습니다! 데이트 하다가 살짝 방문해 보기 좋은 카페였습니다! 개인적인 평점 [3.3/5]', 17, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '대충유원지'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '여기 원두 종류 4가지 중에 고를 수 있고(하나는 디캎) 사장님이 친절하게 설명도 다 해주시고 커피도 맛있고 치즈케이크도 진짜 맛있었고 인테리어도 예쁘고 카페 넘 좋았어용:)', 44, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '대충유원지'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '인테리어도 예쁘고 분위기 좋은 홍대입구역 근처 카페! 원두를 독특하게 표현했더라고요ㅎㅎ 실물도 놓여있는 센스ㅋㅋㅋ의자가 편하진 않지만 대화하기 좋은 분위기이고 커피가 진짜 맛있습니다ㅎㅎ특히 라떼 너무 제 스타일이였어요!♡ 필터커피는 원두가 따로 있으니 참고하세용~', 21, 6, 'GOOD', SYSTIMESTAMP);
