INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '대충유원지'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '테이크아웃에 텀블러까지 하면 합리적인 가격! 원두의 카데고리를 보니 건축 디자이너가 만든 카페가 아닐까 하는 생걱이..! 비오는날에 오면 더 좋을거 같은', 40, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '대충유원지'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '정말 간만에 맛있는 커피를 마셨습니다 원래 리뷰 같은거 안쓰고 지나가는데 바디감 묵직하고 입안 가득 향 느껴지는 커피를 좋아하시는 분 이라면 꼭 콘크리트 원두로 변경해서 에소프레소 메뉴 즐겨보세요 :) 은은하게 달달한 크림브륄레와 함께 먹으면 중화되서 더 좋았던 경험이었습니다!', 37, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '대충유원지'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '커피 한 잔 마시면서 독서나 글쓰거나 작업하기 참 좋은 곳! 나만 알고 싶은 카페! 통창으로 보이는 바깥도 좋고 내부 인테리어도 멋지다', 79, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
