INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '대충유원지'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '연남동에서 쉽게 만나볼 수 있는 푸하하하프렌즈의 공간. 다양한 원두뿐만 아니라 싱글몰트 위스키까지 즐길 수 있고 티라미수 디저트도 매우 맛있다. 뭐니뭐니 해도 공간을 꾸리는 스탭들의 친절한 응대와 배려가 돋보이는 공간 ☺️', 74, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '대충유원지'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '독자적인 블렌드원두로 커피를 내리시네요. 가장 라이트로스팅 된 철근이라는 블렌드를 마셨습니다. 가벼운바디감에 비교적 화사한 향이 특징적이었습니다. 이 블렌드의 에스프레소에는 설탕을 안넣는것이 더 밸런스가 좋아보였습니다.', 39, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '대충유원지'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '대충유원지 밖에서볼때 이름알아보기가 어려웠는데 분위기가좋아서 검색해서 갔네요.. ㅎㅎ의자 불편하고 겨울이라 겉옷둘곳이없어서 넘불편했네요', 25, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '대충유원지'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '인왕산 대충유원지 가보고 넘 매력있었어서 연남동도 가보았습니다. 크림라떼는 숟가락으로 크림을 떠먹으면서 라떼와 함께 마셔보고 1/3정도 남았을때 밑에 가라앉아있는 시럽을 섞어서 먹으라고 하셨어요. 그렇게 먹으니 한잔의 커피를 세가지맛으로 즐길수 있었습니다.', 50, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '대충유원지'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '커피 자체가 맛있어요! 저는 산미 있는걸 안좋아해서 콘크리트 원두가 잘 맞았고, 친구는 플라스틱 원두를 골랐는데 산미가 강하더라구요..! 플랫화이트도 맛있었어요. 티라미슈도 맛있고 카페 전체적으로 분위기 있거 조용해서 집중하거나 소곤소곤 얘기하기 좋았어요🫶', 53, 11, 'GOOD', SYSTIMESTAMP);
