INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '대충유원지'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '오늘은 티라미슈 말고 크림브릘레 시켜봤는데, 여기는 맛없는 디저트가 없군요!! 이제 버터곶감말이만 먹어보면 되는데 기대중이예요:) 마포구에 집중하기 좋고 커피가 맛있는 카페🤎', 30, 4, 'GOOD', SYSTIMESTAMP);
