INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '대충유원지'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '일단 매장 분위기가 너무 좋아 구경하는 재미가 있어 좋아요 :-) 커피원두도 스틸, 콘크리트, 플라스틱 등 선택할 수 있어 좋은 것 같아요. 맛도 물론 좋구요 ^^ 믿고 가는 커피 맛집입니당 -😘', 39, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'INDUSTRIAL');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '대충유원지'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '★3.7 모든 종류의 커피를 두 번씩은 마셔본 것 같다. 맛에서 차이를 느끼기 힘들고 전반적으로 무겁고 단조롭다. 향미가 많이 닫혀있다. 내리는 사람에 따라 커피 맛도 조금씩 달라진다. 각 커피들에서 약간의 뉘앙스 차이 정도만 느껴진다. 로스팅이 오래된 것 같지는 않은데 대체적으로 모든 원두의 로스팅이 심히 강배전 돼있는 느낌이다. 진작 안 갈 수도 있었지만 ‘왜 하나같이 단조로울까’ 고민하다 보니까 계속 가게 됐다. 분위기와 음악, 서비스 등은 반전으로 만족스러워서 갈 수 있었던 것 같다. 또 가서 재차 맛을 확인해 보고 싶으나 단골로 오해할 것 같아 당분간은 못 갈 것 같다.', 36, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '대충유원지'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '원두의 네이밍을 재밌게 해놓으셔서 고르는 재미가 있네요! 쾌적하고 내부가 길쭉한 느낌이라 개방감도 있습니다^^ 사장님의 커피내리시는 멋진 모습을 보려면 바자리가 좋은거 같아요~  그리고 디카페인 커피마져도 특별하고 향이 정말 좋아요! 또 방문하려고 합니다 👍🏻', 16, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '대충유원지'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '전부터 너무 가보고싶었는데 드디어 ㅠㅠ 아메리카노도 원두를 3개 중에 선택할 수 있는게 신기했어요 콘트리트 원두로 마셨는데 적당히 묵직하니 좋았고 필터커피는 디카페인도 되서 마셨는데 산미도 없고 딱이었어요~ 곶감말이는 딱 나왔을 때는 차가워서 좋았는데 금방 녹아서? 조금 아쉬웠어요 ㅠㅠ 거봉녹차는 신기하고 재미있었어요 ㅋㅋㅋ', 34, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '대충유원지'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '여기에 있으면 시간을 잊고 분위기 자체를 즐길 수 있어 좋아요. 원두 고를 수 있어 좋은데 대체적으로 산미가 강한편이에요. 콘크리트랑 플라스틱 시켰습니다! 곶감말이도 맛있지만 역시 첫입이 가장 맛있네용!', 47, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '대충유원지'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '깔끔하면서 아담한 분위기 아메리카노(철근)을 주문 은은한 산미와 끝맛이 달콤하면서 부드러운 적당해 진한 커피맛에 대만족 다른 종류의 커피도 마셔보고 싶어서 다시 들릴 나만의 장소', 30, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '대충유원지'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '내부가 좁으면서 넓어요(?) 사람은 많지만 자리가 빽빽하게 배치되어 있지는 않아서 조용히 대화하기 좋은 곳입니다! 인테리어가 특이하면서 잘 되어있기 때문에 사진도 잘 나와요! 음료는 특이한 것도 많았는데 친절하게 설명해주셨고, 커피가 유명하던데 커피를 마시지 않아서 차를 주문했습니다. 맛있었어요~ 단점을 찾자면 화장실이 외부에 남녀공용으로 있습니다ㅠ', 42, 8, NULL, SYSTIMESTAMP);
