INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '대충유원지'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '라떼가 맛있는 대충유원지. 그냥 대충대충의 대충인줄 알았는데 알고보니 <클 대+충성 충>의 의미였네요 ㅋㅋ 매장에 걸려있는 커다란 태극기 액자도 인상적이었습니당. 🫡🇰🇷', 19, 7, 'GOOD', SYSTIMESTAMP);
