INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '대충유원지'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '사진엔 없지만 아메리카노도 마셨어요. 진짜 인테리어 넘 내 스탈이고 분위기 넘 내 스탈이에여 대충유원지 … > 대충 좋단 뜻이에여 🥺✨💐', 20, 0, 'GOOD', SYSTIMESTAMP);
