INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '대충유원지'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '커피가 맛있네요. 직원분이 설명 잘해주셔서 잘 골라마셨습니다. 다음엔 다른 종류도 먹어봐야겠어요. 와인도 파는 거 같던데 밤에 와도 좋을듯', 71, 13, 'GOOD', SYSTIMESTAMP);
