INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '대충유원지'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '갈 때마다 커피 설명도 잘 해주시고 직원분들이 메뉴에 대한 고민을 한다는 게 느껴져요 그만큼 음료들도 다양하게 맛있구요🥰 맛도 있고 친절하고 인테리어도 예뻐서 또 가게 됩니다:)', 98, 19, 'GOOD', SYSTIMESTAMP);
