INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '대충유원지'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '자리가 좀 불편하다는 리뷰가 있었는데 그런 느낌은 못 받았어요 ㅎㅎ 우드 갬성에 자리 간격도 넓어서 편하고 아이스라떼 고소하고 맛있어요.', 13, 1, 'GOOD', SYSTIMESTAMP);
