INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '대충유원지'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '더운 날씨에 잠깐 들러 커피 한 잔. 가격대가 있는 편, 아주 진한지는 모르겠습니다. 휴일 오후의 여유를 멍하게 보내기엔 좋아보입니다.', 9, 1, NULL, SYSTIMESTAMP);
