INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '대충유원지'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '쿠키 직접 만드신다고 들었는데 굉장히 맛있게 먹었습니다! 직원 분들도 친절하시고 커피도 무척 맛있었어요! (특히 엘리오) 연남동 가면 또 가고 싶은 까페입니다! 추천!', 21, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '대충유원지'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '커피가 너무 맛있구요 (카페라떼 짱) 직원분 너무 친절 합니다 :) 친구가 샷 두개 들어가는 라떼에 하나만 넣는걸 깜빡 말 못했는데 우유도 더 갖다주시고 서비스에 감동 받았습니다 - 분위기도 좋고 커피맛도 좋고 위치도 연남동이라 자주 갈 듯 싶어요 :-)', 23, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '대충유원지'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '서촌점도 가봤는데 분위기는 비슷한 거 같네요 막~ 친절하다 느낄 정도는 아니었는데 그렇다고 뭐 불친절하지도 않은... 직원분들이 그냥 각자 본인 일 하시는 느낌... 의자가 편하진 않아요! 커피 맛도 나쁘지 않았어요~', 41, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '대충유원지'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '라떼도 아메리카노도 맛있어요! 라떼 고소하니 너무너무 맛있었고 아메리카노도 바디감 좋고 적당한 산미 있어서 좋았어요! (원두 ‘철근’으로 먹었어요)', 1, 5, 'GOOD', SYSTIMESTAMP);
