INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 동교동삼거리점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '6시대 일하는 쌍꺼풀한 알바는 서비스 정신 교육이 필요하네. 커피가 x맛없어서 버리고  따뜻한물좀 달라는데  띠겁게 아래위로 훝어보는 눈 뭐니? 커피먹던컵에 헹구지도 않고 컵에 물을 주면 커피맛이지 물맛이니? 자주오는데, 알바들마다 서비스교육받은 애들이 별로없는듯. 테이블한번 닦는걸 본적이 없고 닦아달라고해도 귀찮아하고...이걸보는 사장님은 알바들 제대로 교육시켜야 매출이 오를듯요.', 41, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 동교동삼거리점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '알바생 하나없이 중년여성분 혼자 바쁘신건 알겠는데 너무 불친절해요. 이 넓은매장에 그렇게 손이 부족하면 알바생을 더 쓰든지.. 진짜 최악이네요.', 20, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 동교동삼거리점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '주차장 있긴한데 주차 후 가파른 언덕길 내려와야하고 큰 매장에 직원 혼자 계셔서 그런지 바쁜건 알겠는데 주차 물어보는데도 손님한테 오만상 찌푸리시네요.. 언덕부터 짜증났는데 이런 불친절한 곳 첨보네.. 기분좋게 아이랑 왔다가 기분잡치네. 직원이 뭔 죄겠습니까? 사람 좀 더 쓰세요.', 98, 26, 'BAD', SYSTIMESTAMP);
