INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 동교동삼거리점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '홍대에 위치하고 있으면서도 신촌 느낌 나기두 하고, 주변 다른 대형프랜차이즈 카페들과 비교해서 한산하기에 집중해서 작업하기두 좋습니다 😉', 21, 6, 'GOOD', SYSTIMESTAMP);
