INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 동교동삼거리점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '베리쿠키 아박은 기존 아박이 넘사벽이라 아쉬움 밤양갱 쉐이크 고소해서 취향저격 (바밤바 녹인맛) 스초생은 너무 꾸덕달달이라 먹기 힘들었음', 28, 4, NULL, SYSTIMESTAMP);
