INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 동교동삼거리점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '아이 생일이라 쇼콜라 케이크 사러 왔다. 스트로베리 케이크 기프트콘을 선물받아서 그걸로 샀는데 금액이 천원이 남았다. 키오스크에서 결제하니 남은 천원이 사라졌다. 직원에서 물어보니 취소하고 다시 결제해주세서 남은 돈에 조금 보태어 생일 숫자 초를 샀다. 친절하게 빨리 처리해주셔서 감사했어요.', 96, 19, 'GOOD', SYSTIMESTAMP);
