INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 동교동삼거리점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '저녁 먹고 가볍게 대화하러 들렀는데 매장이 넓어서 기다리지 않고 바로 자리잡았습니다. 다양한 방문객들이 문의하는 가운데서도 직원분이 친절하셔서 잘 안내 받고 차 잘 마시고 갑니다.', 16, 3, 'GOOD', SYSTIMESTAMP);
