INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 동교동삼거리점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '모임 시간까지 시간이 남아 추위를 피해 방문했습니다. 스타벅스는 자리가 없기도 했고, 우주패스 쓸 수 있어서 방문했어요. 사람이 많긴했지만 혼자 있기에 개별 좌석이 많았습니다. 커피도 빨리 나왔어요.', 2, 0, 'GOOD', SYSTIMESTAMP);
