INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 동교동삼거리점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '매번 갈 때마다 느끼는데 매장 진짜 넓고 좋아요. 근데 화장실이 좀...ㅜㅜ 밖으로 나가서 슈퍼마켓 가로질러가야하는데 그다지 청결하지도 않음...', 33, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 동교동삼거리점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '주말 오후3시쯤 갔는데 체크무늬 옷입은 직원분 너무 불친절 하셨어요. 못마땅한 표정과 말투때문에 혼나는 기분이 들었어요. 다음엔 다른지점 이용하려구요..;;;;', 48, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 동교동삼거리점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '공부하기가 좋네요 화장실은 실내를 가로질러야하지만 그렇게 불편하진 않구요. 좌석간 자리도 넓고 콘센트도 넉넉하고 하서 편안하네요', 11, 7, 'GOOD', SYSTIMESTAMP);
