INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 동교동삼거리점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '작업하기는 좋습니다. 공간도 넓고 음식은 투썸이니까 당근 기본은 합니다. 다만 평일 오후 알바생 몇 번씩이나 불친절하네요. 곱슬머리 여성분은 저번에 되게 친절하셨는데 그 분 제외하고는 여자 두 분 뭐 물어봐도 잘 안들리게 대답하고 알바 맞으신지,,', 28, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 동교동삼거리점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '여기 알바가 진상입니다. 요청한 물건 그대로 주면 되는데 점장에게 전화할 때 말을 더 추가해서 일관성 없이 어떻게든 빠져나갈 구실이나 만듬. 고객을 대하는 자세부터 영 별로... 서비스업 욕먹이지 마세요.', 10, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 동교동삼거리점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '자리도 편하고 디저트도 맛있어요~~!! 근데 문이 손님들 들어올 때마다 어디에 걸려서 자동으로 안 닫히는 건지 계속 닫으러 가야하고 종종 추웠습니다 ㅠㅠㅠ', 34, 1, NULL, SYSTIMESTAMP);
