INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 동교동삼거리점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '처음 와 본 투썸플레이스 동교동삼거리점. 매년 이맘태쯤 판매하는 시그니처뱅쇼 올해도 처음 맛보는데 계피가 들어간 와인에 달달함과 쌉쌀한 조화가 잘 어울리는게 맛있어요. 추천합니다.', 24, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 동교동삼거리점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '매장이 꽤 넓은데 좌석이 정말 알차게 들어찬 느낌! 투썸 아이스박스는 언제나 실망시키지 않네요. 개인적으로는 꽝꽝 얼었을 때 더 맛있는 거 같아요 :)', 62, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 동교동삼거리점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '직원들이 시끄럽게 떠드는곳  무슨 손님들보다 시끄럽냐.... 수다떨지말고 조용히 일좀해라. 추운날씨 출입문 2시간씩 열어놓고 손님내쫒는 특히한 투썸아  직원 교육좀....', 37, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 동교동삼거리점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '매장 넓고 친절해요~ 환기를 문 열어놓고 시켜서 안심되네요! 산미가 살짝 느껴지는 아로마노트 아메리카노 맛있어요. 아이스는 500원 더 내면 젤 큰 사이즈 주는 이벤트도 해요. 굳이에요', 57, 18, 'GOOD', SYSTIMESTAMP);
