INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '홍대디저트카페 꾸울과자점 후기 남겨용!! 치즈케익, 휘낭시에, 스콘까지! 베이커리 카테고리도 다양하고 카테고리별로 맛도 엄청 다양하답니담 맛도 종류만큼 훌륭하고!! 선물포장까지 있어서 자주 이용한답니다!', 34, 8, 'GOOD', SYSTIMESTAMP);
