INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '에그타르트 겉은 쫌 두껍고 빠쟙?한편이어서 쪼금 아쉽소, 속은 엄청 부드럽고 많이 달진 않아요. 필링 맛은 좋았어요!! 물이 흐르니까 길빵같은건 조심하세용 발로나 초코칩 휘낭시에는 바닥면에도 초코 코팅이 있고 안쪽에도 뭔가 속재료가 들어있어요. 겉이 바삭할 줄알았는데 끈적꾸덕한 휘낭시에라서 재구매는 놉 얼그레이 파운드는 퍽퍽하면서도 촉촉해서 맛있었어요! 위에 아이싱이 달달하고 맛도 진하니 맛있네용', 29, 10, NULL, SYSTIMESTAMP);
