INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '입구부터 맛있는 빵 쿠키 냄새가..ㅎㅎ ㅜㅜ 기분이 저아져요.. 선물용으로 골랐는데 포장도 꼼꼼히 잘해주시고 휘낭시에랑 르뱅쿠키, 파운드 케이크가 알차고 너무 맛있어보였습니다!! 선물용으로 하기 정말 좋아요! 추천합니당⭐️⭐️✨🤍', 128, 22, 'GOOD', SYSTIMESTAMP);
