INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '예약해야 디저트 남아있을 거 같아서 했는데 너무 늦게가지만 않으면 대부분 남아있긴합니다! 사실 상자 포장 원하진 않았는데 이미 해주셔서 700원 더 냈구요 원하지 않으시는 분들은 요청사항에 적어야 할 거 같아요 필수로 안써있어서 ㅠ 그 외에 커피랑 소금빵이 진짜 맛있고 나머지는 그냥 맛있습니다 테이크아웃 전문이어서 그런지 가격이 좋아서 만족합니다 근데 카라멜 무화과 스콘은 카라멜에 탄맛이 나서 아쉬웠습니다', 13, 4, 'GOOD', SYSTIMESTAMP);
