INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '평소에 휘낭시에 정말정말 좋아하는데 여기 꺼가 제일 맛있어요!!! 전이 친구가 사다준 거 먹어봤는데 너무 맛있어서 오늘은 직접 방문했어요ㅎㅎㅎ 그리고 동생 피셜 말차 르뱅 쿠키도 말차맛 진짜 진하고 너무너무 맛있다고 하더라고요🤍 #홍대디저트카페 #휘낭시에', 35, 9, 'GOOD', SYSTIMESTAMP);
