INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '발렌타인데이 선물세트 구매했는데 정성이 가득 담겨서 너무 이뻐요 :) 파운드들도 너무 맛있어보이고 특별한 날 사랑하는 사람들에게 선물하기 너무 좋아요😆', 24, 2, 'GOOD', SYSTIMESTAMP);
