INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '종류가 정말 다양해서 너무 좋아요!!! 휘낭시에랑 쿠키 파운드 종류별로 여러가지맛이 있어서 고르는 재미가있고 모두 다 맛있어요💛', 107, 23, 'GOOD', SYSTIMESTAMP);
