INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '저만의 리얼 또또간집입니다.. 너무 맛있어서 며칠전에 갔다가 오늘 또 다녀왔어요.. 전 심지어 집에서 한 시간 거리라구요.. 근데 이 거리에서 또 갈 정도면 얼마나 맛잇는건지.. 홍익대 학생들 너무 부럽습니당.. 케이크도 다른 데처럼 터무니없이 비싸지도 않고ㅠ 개맛도리에(크림이링 먹으면 술술 넘어감요) 저는 제 짝꿍이랑 미니딸기케이크 앉은자리에서 한 판 다 먹었습니다. 무화과 크림치즈 저번애 하나 사갔다가 가족들이 더 먹갰다고 싸워서 오늘 또 사갑니다.. 그리고 소금빵은 앙버터 소금빵으로 드시길 리얼 맛도리🩷💜💙🩵💛💚 안양에는 왜 이런 곳이 더 생기지 않는지 의문 가득입니다..?🥲 ㅎㅎ 사장님 번창하세요!!! 전 또 올거에요🤗😍', 16, 4, 'GOOD', SYSTIMESTAMP);
