INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '기념일때마다 들리게 되는 꾸울❤️ 포장도 이쁘고 구성도 알차고 무엇보다 디저트가 너무 맛있어요ㅋㅋㅋㅋ 그래서 집앞 나만알고싶은 디저트맛집❤️❤️ 아니 솔직히 더 알려져야 함!!! 지~~~~난번 크리스마스 케이크는 이벤트로 먹었었고 지~난번 빼빼로데이때는 빼빼로데이 구성으로 먹었었고 이번에는 발렌타인데이❤️ 내가 누군가한테 주는거라 이걸 직접 먹을 순 없고 가끔 들려서 직접 사먹었는데 갈때마다 예약했다고 하나씩 주셔서 얼마나 감사한지❤️ 누군가도 나한테 꾸울패키지 선물해줬으면 좋겠다❤️', 37, 10, 'GOOD', SYSTIMESTAMP);
