INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '발렌타인 기념으로 찾아보다가 예약하게 되었는데 빵들도 넘 귀여워서 선물받은 사람이 무척 좋아했어요!! 맛도 있고 가격 대비 구성도 다양해서 좋은 선물이 되었어요💗 저도 먹어보고 싶어서 꼭 다시 방문할게요!! 요청사항도 수용해주시고 넘 친절하세요', 12, 6, 'GOOD', SYSTIMESTAMP);
