INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '후기가 너무 좋아서 방문했는데 들어서는 순간부터 냄새가 미쳐….❤️ 다행히 딸기케이크도 있었구 자리도 2개 있는데 한 자리 비어 있었어요 ㅎㅎ 쿠키도 휘낭시에도 케이크도 너무 맛있어요 ㅠㅠㅠ 빵순이 행복해요❤️❤️❤️', 38, 3, 'GOOD', SYSTIMESTAMP);
