INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '리얼 또또또간집 ㅁ한 달도 안됐는데 3번째 방문입니다. 멀리서도 찾아오게 만드는 맛집.. 잉버터 소금삥 제가 강추해드링거 잊지읺으셧죠? 앙버터 소금빵을 무조건 드셔야 해요. 진찌리구요.. 특히 므화과 크림치즈어쩌구 휘낭시에가 저희집 인기휘낭시에인데.. 여러분 제발 드셔보세요.. 홍익대 올 걸 그랬어요 꾸울괴자점 출석체크하러..🫠', 89, 18, 'GOOD', SYSTIMESTAMP);
