INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '와...... 30년 넘게 살면서 먹은 쿠키. 파운드 케잌 중 원탑이에요~~~ 개인 과자 전문점이 아니라 호텔 베이커리 급인데요!?? 와........👍🏻 진짜 돈 안아까워요~ 크기 작다고 하시는 분들 있는데 그래 크기는 좀 작아요 근데 맛이 👍🏻👍🏻👍🏻👍🏻 꼭 사서 드셔보세요! 파운드케잌 다 촉촉하고 맛있고 쿠키도 맛잇고 휘낭시에 맛잇어요!!', 4, 3, 'GOOD', SYSTIMESTAMP);
