INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '급하게 예약하고 갔는데 너 ~~ 무 맛있어요.. 촉촉하고 선물하기에도 넘 좋구요. 서비스로 주신 휘낭시에도 너무 맛있어서 다음에 꼭 다시 방문하려구요! 선물용 구움과자 찾으시면 꾸울과자점 꼭 방문해보세요. 최고!', 5, 10, 'GOOD', SYSTIMESTAMP);
