INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '3년 전에 알게 돼서 계속 사먹고 있어요! 친구, 동료들한테 선물하려고 몇번이나 재구매한 디저트 찐맛집❤️ 집이랑 멀지만 꾸울 파운드케익 사려구 주기적으로 들러요! 😍모든 파운드케익이 다 맛있구 특히 선물용으로 너무 좋습니당!!👍👍👍', 33, 6, 'GOOD', SYSTIMESTAMP);
