INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '저번에 먹어보고 두번째 방문이에요! 매장 들어가자마자 일단 구움과자 냄새가 너무 좋아서 많은 종류 중에서 고르기가 힘들었어요ㅎㅎ 집만 가까웠으면 자주 왔을 것 같아서 아쉬워요ㅠㅠㅠㅠ', 5, 2, 'GOOD', SYSTIMESTAMP);
