INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '앙버터 소금빵 너무 맛있어요!! 소금빵은 바삭하고 버터 풍미가 좋아요;) 다른 디저트들도 맛있고 홍대 기숙사 근처라 접근성도 좋아요!', 17, 4, 'GOOD', SYSTIMESTAMP);
