INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '홍대생으로서 당당하게말합니다. 여기 디저트가 최고예요. 앉아먹는 자리는 몇 개 없지만 전 당 땡길때마다 르벵쿠키를 사가요. 최고예요. 다른 메뉴도 다 맛있고 실패한 적 없어요. 진심입니다.', 68, 17, 'GOOD', SYSTIMESTAMP);
