INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '디저트 종류가 엄청 다양해서 좋아요! 주로 휘낭시에, 버터바, 파운드 케이크 사먹는데 다 맛있습니다 ㅎㅎ 선물하기에도 구성이 좋습니다~~!', 106, 25, 'GOOD', SYSTIMESTAMP);
