INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '퀵 배송과 택배 배송이 같이 있어서 복잡했을텐데 잘 맞춰주셔서 감사합니다. 수령일 맞춰서 퀵 도착할 수 있었고 카카오 퀵으로 해주셔서 퀵 이동경로도 확인할 수 있어서 좋았습니다. 메뉴 구성도 알차고 직원들도 만족도가 높아요.', 11, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '선물용으로 주문했는데 깔끔하게 개별포장되어, 받으신 분이 맛있다고 아주 만족해 하셨어요. 덕분에 좋은 선물드린 것 같아 뿌듯했답니다. 번창하세요!', 12, 8, 'GOOD', SYSTIMESTAMP);
