INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '선물용 구움과자가 필요해서 급하게 찾아갔는데 종류도 다양하고 선물포장도 깔끔하게 되어서 굉장히 만족했습니다. 특히 직원분들이 너무너무 친절하셔서 기억에 남네요. 덕분에 잘 선물했습니다.', 9, 3, 'GOOD', SYSTIMESTAMP);
