INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '진짜 진짜 너무너무 애정하는 가게입니다….😭❤️❤️ 휘낭시에,쿠키,파운드 케이크 너무 맛있어요… 얼그레이랑 단호박 파운드 진짜 맛있고 황치즈 쿠키도 진짜 맛있어요 일주일에 한 번은 꼭 옵니다…', 45, 4, 'GOOD', SYSTIMESTAMP);
