INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '꾸울과자점♡ 홍대 들렸다가 발견한 작은 디저트가게예용! 쿠키랑 파운드, 휘낭시에가 너무 귀엽고 맛있어보여서 테이크아웃고 갑니당! 다음에도 또 방문할게요!', 49, 10, 'GOOD', SYSTIMESTAMP);
