INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '오랜만에 들렀는데 화사하고 깔끔한 분위기가 변함이 없네요. 고구마파운드, 마늘소금빵, 르뱅쿠키, 군고구마휘낭시에, 아몬드크로칸트휘낭시에 구매했습니다. 다 괜찮았는데 마늘소금빵이 특히 맛있었어요!', 41, 4, 'GOOD', SYSTIMESTAMP);
