INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '들어가자마자 빵냄새 가득~ 행복했어요ㅠ 참지 못하고 쿠키랑 휘낭시에랑 파운드케이크 사버렸습니다 . . 저번엔 갓나온 소금빵 사먹었는데 존맛 ㅜ 길빵 해버렸어요 소금빵 12시 40-50분 사이에 나와요 ㅎㅎ', 22, 6, 'GOOD', SYSTIMESTAMP);
