INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '학교 앞에서 달달하게 커피랑 디저트 먹을때 자주 방문했는데, 집에두 사가니 맛있다고 해서 한가득 쟁여갑니다. 맛있여여~~~ 감사합니당', 48, 1, 'GOOD', SYSTIMESTAMP);
