INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '동생 공연 축하하려고 선물 고민하다 네이버 리뷰에서 맛있다는 글 보고 세트 주문해서 픽업했습니다. 구성도 딱 적당히 알차게 다양했고 박스 포장 요청해서 겉모양도 예뻤어요. 들어갔을 때 버터 냄새도 너무 좋았습니다. 제가 맛 보려고 산 게 아니라 먹어보지는 못해서 다음에는 먹으러 방문할게요.', 51, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '디저트 종류도 다양하고 맛있어서 가끔 포장했었는데, 이번에는 답례품 구매했어요! 포장도 예쁘게 해주시고 받으시는 분들께서 엄청 맛있다고 좋아하셨어요~~!', 50, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '선물용으로 너무 깔끔하고 좋습니다! 엄청 맛있어서 선물 사러 갈 때마다 제 것도 꼭 같이 사서 먹습니다 ㅎㅎ 너무 맛있어요 💕', 33, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '답례로 선물 준비한건데 맛은 나쁘지 않았어요 전체적으로 평균? 한번정도 먹을정도 였습니다 미리 전날 예약하고 찾으러 간거였는데 방문 후에 포장하면서 누락될뻔 해서 그러부분은 좀 아쉬웠습니다.', 50, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '홍대생인데 4년동안 저 뿐만 아니라 주변 동기들도 주기적으로 찾는 맛집입니다...🤍 휘낭시에랑 쿠키, 파운드케이크가 진짜 맛있어요!! 커피고 싸고 맛있어서 자주 사마십니다', 45, 0, 'GOOD', SYSTIMESTAMP);
