INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '모든 스콘과 빵, 쿠키들이 정말 맛있어요! 측히 유자파운드와 초코소금빵이 정말정말 달고 부드럽고 맛있습니다! 직원분들도 너무 친절하셔서 자주 오게 돼요~', 12, 7, 'GOOD', SYSTIMESTAMP);
