INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '간단리뷰 - 파운드 종류가 다양하고, 휘낭시에, 쿠기 등 있네요 / 단품 보다는 세트로 선물포장에 특화 되어 있는 매장 인듯 했어요. / 더블바닐라파운드: 포장해 와서 반 잘라보니 안에 바닐라빈 보이고 달달하고 맛나긴 했어요 가격대비 크기가 약간 작은 느낌 이구요.', 2, 10, NULL, SYSTIMESTAMP);
