INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '친구 전시선물로 주려고 휘낭시에 6구 포장했습니다. 막상 가보니 맛있어보이는것이 너무 많아서 더샀네용 무화과카라멜스콘이 정말 자지러지게 맛있었습니다💕', 33, 2, 'GOOD', SYSTIMESTAMP);
