INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '홍대생이라면 모를수가 없는 디저트 맛집!! 여기 파운드는 어디서도 먹어보지 못한 꿀맛이고, 휘낭시에 쿠키 모두 맛있어요!! 이쁘게 포장도 가능해서 선물용으로도 강추입니다 ㅎㅎ 오래오래 장사해주세요 ❤️', 14, 10, 'GOOD', SYSTIMESTAMP);
