INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '친구 생일이라 케익 대용으로 구매했는데 더운날씨에 멀리 이동해도 녹지않아서 너무 좋았어요! 맛도 다양하게 있어서 취향대로 골라담을 수 있다는 장점이 있습니다! 살짝 아쉬웠던 점은 유산지에 쌓여있다보니 케익판에서 계속 미끄러져서 선물로 건네줄때 한쪽으로 쏠려있을 수 있어요..🥲 그래도 그것빼곤 선물용으로 좋았습니다!', 19, 7, NULL, SYSTIMESTAMP);
