INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '오전에 비즈니스 미팅이 있는데, 아침 시간에 문을 연 곳이 많지 않아서 찾다가 오게됐어요. 쿠키랑 파운드케이크, 휘낭시에 종류가 많고 다 먹음직스럽게 생겼더라고요! 700원 내면 선물박스에 포장도 해주셔서 좋았습니다 :)', 46, 7, 'GOOD', SYSTIMESTAMP);
