INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '홍대생 방앗간입니다,,🫶 종류도 다양하고 특히 고구마 휘낭시에랑 황치즈 쿠키 너무너므 맛있어요❤️‍🔥❤️‍🔥 파운드 케익도 예뻐서 선물하기도 조아요 오래오래 맛있는 디저트 많이 만들어주셧슴합니당!', 21, 7, 'GOOD', SYSTIMESTAMP);
