INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '매장이 너무 예뻐요!! 디저트도 왕 많고 예쁘게 진열되어 있어요!! 어무니께서 좋아하는 빵 잘 사서 갑니당!! 사장님께서 너무 친절하시고 빵도 너무 맛있어요!!!! 최고 !!!! 👾💜', 50, 10, 'GOOD', SYSTIMESTAMP);
