INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '너무 매일 가서 매일 리뷰를 쓰게 되는데 아침마다 들러서 커피를 사는게 출근의 유일한 낙이예요 친절하신 사장님과 직원들 덕분에 맛있는 과자랑 속시원한 커피를 수혈받고 있어요', 80, 14, 'GOOD', SYSTIMESTAMP);
