INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '여기 정말 깔끔하고 좋았고 쿠키만 샀는데 벨기에 🇧🇪 산인지 이탈리아 산인지 초콜렛이 정말 깊고 진한맛을 내더군요! 추천드려요!!! 아 그리고 ''견과류''가 들어가있어서 만약 알레르기 있으신분들은 비추!!!!', 3, 10, NULL, SYSTIMESTAMP);
