INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '일 때문에 여기서 수십만원 넘게 구매한 사람입니다.진짜 다들 너무 만족하시고 먹은이들 중 남긴 사람이 없었습니다.저도 궁금해서 하나 사 먹어 봤는데 말도 안되게 맛있더군요.초코 휘낭쉬에 의 초코도 아주 풍미가 좋고 휘낭시에는 까눌레 저리갈 정도로 겉바속촉의 미학에 충실했습니다.격이 다른 맛이더군요.지금 제 맛집지도에 저장해 뒀습니다.나중에 데이트든 개인적인 선물이든 애용할듯 합니다.격이다른 디저트 맛집으로 추천 합니다!(사장님도 되게 친절하셨어요!!감동이었습니다!감사했어요!)', 96, 22, 'GOOD', SYSTIMESTAMP);
