INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '딸기케이크가 먹고 싶어서 들렀어요! 테이블은 두 개 있었는데 평일에 와서 한적하기도 했고 혼자 와서 괜찮았어요 케이크랑 밀크티 먹었는데 다른 디저트들도 맛있어 보여서 다음에는 다른 디저트 포장하러 와야겠어요', 111, 23, 'GOOD', SYSTIMESTAMP);
