INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '늦은 시간에 방문했는데 손님들이 계속 들어오더라구요 찐 디저트 맛딥! 파운드는 조금 가격대 나가는 편인데 휘낭시에나 쿠키 이런 것들은 다른곳보다 상대적으로 가성비있는 느낌?! 🍪 🥠 🍪 🥠 🍪 여러개 먹은 것 중에서 휘낭시에는 일단 아래 순서로 맛있었어용 1. 아몬드 휘낭시에 2. 초코 휘낭시에 3. 무화과 휘낭시에 마늘소금빵 첨 먹어봤는데 저는 원래 크림빵을 안 좋아하는 편이지만 이건 괜찮았어요! 두 입정도 아메리카노랑 먹으니까 딱이었습니다 다음엔 파운드 먹어볼래요!!! 흑임자 등등 맛이 다양해서 궁금해요 🍞🥐🥖🫓🥨🥯🥞🧇🍪🍩🎂🍰🍮', 9, 1, 'GOOD', SYSTIMESTAMP);
