INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '여기 르뱅쿠키 진짜 모두 다 드셔보셔야 해요ㅠㅠㅠㅠㅠㅠ 집가면 맨날 생각나서 학교 올때마다 꼭 들려서 사가지고 갈 정도로 진짜 여기가 젤 맛있어요!!!!', 85, 16, 'GOOD', SYSTIMESTAMP);
