INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '맛있는 스콘과 쿠키 피낭시에 팔아서 너무 너무 맛있어요 ❤️❤️커피도 너무 맛있구요 종류가 다양해서 골라먹는 재미가 있네요💜💜 추천합니다 사장님도 너무 예쁘시고 친절하세요 대박 나세요👍🏻👍🏻', 36, 2, 'GOOD', SYSTIMESTAMP);
