INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '작년에 다른분께 선물받은 휘낭시에,파운드 맛을 잊지 못하고 다시 찾아왔습니다 홍대입구에서 거리가 좀 있어서 많이 걸어야하지만 재재방문 의사 있습니다! 구움과자 좋아하시는 분들께 추천드려요.', 40, 1, 'GOOD', SYSTIMESTAMP);
