INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '휘낭시에 맛집이에요 무화과, 아몬드, 플레인, 초코칩 다 맛있어요 제 취향은 고구마랑 베이컨 같이 사서 단짠으로 먹는건디 아몬드가 젤 인기많을 거 같아요 원래 아몬드 입에도 대지더 않는데 이 집 아몬드휘낭시에는 진짜 맛있어요 아몬드 조아하심 강추 진짜 바짝한 겉면이 너무 중독적이에요', 39, 4, 'GOOD', SYSTIMESTAMP);
