INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '우연히 지나가다가 들렸는데 디저트 종류도 다양하고 가격도 나쁘지 않아 좋고 무엇보다 르뱅쿠키 좋아하는데 여기가 진짜 먹어본 곳들 중에 가장 맛있어요ㅠㅠㅠㅠㅠㅠ 다들 여기 르뱅 쿠키 드셔보세요 꼭!!', 44, 7, 'GOOD', SYSTIMESTAMP);
