INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '매번 올 때마다 맛있는 빵 냄새가 나서 너무 좋아요 구움과자 진짜 여기가 제일 맛있습니다 휘낭시에믄 여기 처음으로 먹고 다른 곳을 못 먹어요 ㅜㅜ 다들 꼭 드셔보세용!!', 90, 14, 'GOOD', SYSTIMESTAMP);
