INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '홍대생이라면 모두 다 아는! 대표디저트가게 꾸울🧡 미니 파운드케이크, 휘낭시에, 르뱅쿠키, 소금빵, 스콘을 팔아요. 모든 메뉴가 다 평균 이상의 맛을 보장하기때문에 아무거나 골라도 다 맛있어요👍 황치즈쿠키같은 독특한 메뉴도 추천해요 여기 황치즈 먹어보고 벨X쿠키꺼 황치즈 먹어봤는데 꾸울이 진짜 맛있는거구나 체감했어요 글구 여기 의외로 커피☕️가 정말 맛있습니다! 한번 사먹어본 이후로는 학교 안 카페 안가고 여기로 와용. 아아 3000원인데 양도 많아요! 가격대는 대략 미니 파운드 - 4000, 르뱅쿠키 - 3800, 휘낭시에 - 2800, 소금빵 - 4000 정도고, 처음에는 비싸다고 느꼈는데, 이 근방 카페들 다녀보면 꾸울이 하한선이더라구요? 포장도 정성스럽게 해주시니 선물용으로도 추천해요🧡', 26, 3, 'GOOD', SYSTIMESTAMP);
