INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '휘낭시에 맛집. 빠자쟉한 휘낭시에 좋아하면 무조건 추천 기본도 버터향이 찐하게 나니 맛있고 아몬드가 진짜 맛있음 달달하고 고소한 조화가 미친.. 체다베이컨도 단짠의 조화가 좋음 소금빵도 맛있으니 추천드림', 28, 3, 'GOOD', SYSTIMESTAMP);
