INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '항상 구움과자만 구매하다가 음료 행사하길래 처음으로 음료도 구매해봤어요! 토피넛라떼가 고소하고 맛있네요ㅎㅎ 오랜만에 방문했는데 역시 뷰도 좋아요~', 76, 14, 'GOOD', SYSTIMESTAMP);
