INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '넘 귀염뽀작한 가게였어요! 시간이 없어서 이것저것 담아서 포장해왔는데요, 정말 맛있었습니다. 소금빵에 앙버터추가해서 가져와서먹었는데요, 그것도 짱맛있었어요.쿠키도 넘 맛있어요. 조만간 다시 방문해야겠습니다. 안먹어본게 아직많네요', 7, 3, 'GOOD', SYSTIMESTAMP);
