INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '냠냠!! 소금빵 앙버터 꼭 드세요!! 전 밖에빵이 있어서 얼마나 바삭할까햇는데 완전 바삭바삭..두개사올껄..ㅠㅠ 옆에있던 초코 소금빵도 사올껄 후회했어요..ㅋㅋㅋ 다른 쿠키보다 휘낭시에도 존맛!!! 음료는 왜또 맛있는지..달달구리에 달달구리먹는데도 맛있어요!!!', 57, 15, 'GOOD', SYSTIMESTAMP);
