INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), 'Great selection of gourmet bread.These are definitely not the regula bread you would get at other coffee shops.The Bread is amazing! Plus, kindy staff!!!', 100, 20, 'GOOD', SYSTIMESTAMP);
