INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '빵들 다 너무 맛있습니다..  가끔씩 달달한거 생각나면 어느새 제 발이 꾸울을 향해 걸어가서 제과점 앞이더라구요… 르뱅쿠키도 쫀듯쫀듯하니 맛있고.. 아 르뱅쿠키 기본으로 시작하시고 다른 맛 드시는거 추천드려요 베이스부터 차근차근 쌓은 후 이것저것 먹다보면 순정으로 돌아오게 되더라고요!! 암튼 다 맛있어요..그냥 드셔보셔유', 2, 5, 'GOOD', SYSTIMESTAMP);
