INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '위시리스트로 저장해놨다가 드디어 들렸어용 ! 아기자기하구 좋아하는 메뉴 많아서 왔는데 절제하는라 힘들었어용 ㅜㅜ 또 와서 오늘 안 산 메뉴 또 사러 올게요 〰️🤍', 31, 7, 'GOOD', SYSTIMESTAMP);
