INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '초코소금빵이랑 마늘소금빵 미쳤어요 초코소금빵 재구매하러가서 마늘소금빵도 홀린듯이 구매했는데 마늘소금빵 최근에 먹은 빵 중에 제일 맛있었어요', 1, 1, 'GOOD', SYSTIMESTAMP);
