INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '아몬드 휘낭시에는 그냥 먹는게 맛있구 초코휘낭시에 얼려먹으면 진짜 맛있어요 ㅠ 쫀득 꾸덕 미침 .. 냉동실에 쟁여두려했는데 늦게가서인지 두개밖에 없었네요 흑흑', 31, 1, 'GOOD', SYSTIMESTAMP);
