INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '꾸울 과자점~~ 학교 기숙사에서 나오자마자 있는 가게여서 위치가 너무 좋아요!! 선배들이 여기가 진짜 맛있다고 추천하셔서 가 봤는데 기대 이상으로 맛있었어요!!! 😍 사장님도 친절하시고~ 용돈 여기서 다 쓸 것 가태요 ㅜ 😇😋♥️', 102, 23, 'GOOD', SYSTIMESTAMP);
