INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '정말 홍대생들의 당 응급처치는 여기가 책임진다… 베이커리류 쿠키류 모두다 맛있어요… 찐한 맛이 나요… 아주 좋습니다 중독되었습니다… 굿 굿 굿', 2, 6, 'GOOD', SYSTIMESTAMP);
