INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '교수님 뵈러 가는데 선물용으로 구매했어요. 종류가 다양하고 가격대가 부담스럽지 않아서 좋습니다. 포장이 귀엽네요. 포인트 제도도 만족스럽습니다!', 27, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '오늘은 테이크아웃으로 했어요! 종류도 다양하고 맛있어 보이는거 많았는데 그 와중에 골라 담느라 혼났어요 냄새도 너무 맛있는 냄새가 솔솔 나요 ㅎㅎ 다른 사람들도 나눠주려고 함께 구매했어요', 19, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '단순히 마늘맛 소금빵인줄 알았는데 소금빵안에 크림치즈가 많이 들어있어서 부드럽게 넘어가는 빵이에요. 바닐라파운드케잌도 안에 바닐라 크림이 들어있어서 자주 먹을것 같아요!', 1, 9, 'GOOD', SYSTIMESTAMP);
