INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '학교근처여서 자주 오는 디저트가게에요! 맛있고 매장도 예뻐서 좋아용 테이블은 두개 있는데 좁아서 그냥 테이크아웃으로 가져가기 좋은곳이에요~!! 휘낭시에가 맛있어요😍', 49, 2, 'GOOD', SYSTIMESTAMP);
