INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '소금빵 너무 맛있어요 ㅠ 엄마가 좋아해요!! 신메뉴 토피넛라떼에 샷추가해서 먹어봤는데 달달하니 맛있어욤 샷추가 안하면 너무 달거같아서 단거 안좋아하는분들은 비추 ..!', 27, 1, 'GOOD', SYSTIMESTAMP);
