INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '초코발로나파운드랑 오레오쿠키 먹었는데 맛있었어요! 파운드는 보들보들하고 위쪽에 카라멜 같은 게 뭐가 들어있는데 그게 맛있었어용 / 쿠키는 제가 딱딱한 쿠키를 좋아하는 편인데 괜찮았습니당 부드럽고 쫀쫀하고 오레오가 속에도 박혀있어요', 12, 7, 'GOOD', SYSTIMESTAMP);
