INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '너무 맛있어요... 브라우니 사다가 집에 있는 아이스크림 올려서 먹었는데 너무 맛있어요.. 학교 바로 앞이라 맨날 사먿어요 리뷰이벤트 3000포인트 너무 혜자 아닌가요 ㅠㅠ 선물하기도 너무 좋아요', 2, 7, 'GOOD', SYSTIMESTAMP);
