INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '홍대 제2기숙사 바로 옆 다양한 미니 파운드 케이크와 쿠키, 소금빵등을 파는 작은 디저트집이에요. 전반적으로 파운드케이크가 맛있어요(맛이 진해요). 쿠키는 초코, 말차중에 말차쿠키가 더 취향이였어요. 말차맛이 진하구 마카다미아가 씹혀서 맛있어요🥰 가게에 앙버터 소금빵이라는 특별한 메뉴가 있는데 그것도 추천해요!', 68, 13, 'GOOD', SYSTIMESTAMP);
