INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '꾸울과자점 일단 올라 갈때부터 설렙니다.. 가자마자 반겨주는 르뱅쿠키들과 휘낭시에랑 스콘 그리고 파운드케이크까지.. 제 최애는 아몬드 휘낭시에 이고 나머지는 맨날 바꿔가며 먹는 것같아요.. 학교앞이라 지나가는데참새가 방앗간을 어떻게 지나챠요ㅠㅠ', 46, 1, 'GOOD', SYSTIMESTAMP);
