INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '빵돌이 인생 32년.. 휘낭시에 한입 먹어보고 정착 결심한 꾸울과자점... 그동안 소홀했는데 오랜만에 재재방문하고 아몬드휘낭시에 한입 베어무는 순간 스스로에게 실망하고 말았읍니다.. 그동안 왜 소홀했을까.. 왜 어제는 오지 못했을까.. 왜 지난주에는 오지 못했을까.... 반성합니다..', 37, 9, 'GOOD', SYSTIMESTAMP);
