INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '홍대생은 빵 다 여기서 먹는다 !!!! 휘낭시에 너무 맛있어요 저만 먹게 아무도 먹지 마세요.!!!!! 존맛탱구리 ㅠㅠ 소금빵도 진짜 너무 존맛 ㅠㅠ', 63, 13, 'GOOD', SYSTIMESTAMP);
