INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '적적했던 하루를 달콤하게 마무리 지어주는 곳 일하느라 지친 심신을 달래주는 곳이에요 구움과자 맛집..!!!! 나만 알고 싶지만 유명해지길 바라는 마음이 공존하는 디저트집이에요🫶🏻 오늘두 맛나게 잘 먹었습니다', 98, 21, 'GOOD', SYSTIMESTAMP);
