INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '매장에서 포장한 거라서 4구 포장 사진은 없지만 파운드가 너무 예뻐요 ㅠㅠ 4개 구매하면 상자에 예쁘게 포장해주시고 이미 유명하지만 더 유명해졌으면 좋겠어용 ㅎㅎ 다음에 또 오고 싶어요!!', 70, 11, 'GOOD', SYSTIMESTAMP);
