INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '존맛😭😭 잠깐 친구 기다리다가 근처에 있어서 들렀는데 미쳤어요. 휘낭시에 존맛… 파운드도 맛있어요. 미쳤나봐요ㅋㅋㅋㅋㅋㅋㅋ밥먹으러 갈건데 세개나 순삭했어요ㅋㅋㅋㅋ소금빵이 유명한거같은데 없어서 못샀어요. 담에 소금빵 사러 와야겠어요 🤦🏻', 31, 6, 'GOOD', SYSTIMESTAMP);
