INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '꾸울과자점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '이곳 빵은 다 맛있지만 이전에 먹었던 바스크치즈케익이 너무 맛있었어서 생일 맞은 기념으로 쿠폰도 주시더라구요. 그래서 홀케익으로 주문했었는데 정말 만족스러웠어요. 케익이 진짜 치즈가 가득한게 느껴질 정도로 크리미하면서 꾸덕한 식감도 정말 좋구요. 맛도 정말 맛있습니다ㅠㅠ 커피랑 먹으면 순식간에 사라져버려요. 가족들이랑 정말 순식간에 다 해치웠었네요. 이 정도 퀄리티의 홀케익을 할인까지 받아서 살 수 있었다는 점이 너무너무 만족스럽고 앞으로도 자주 이용하겠습니다. 여기 온다면 꼭 치즈케익 드셔보셨으면 좋겠구 생일되면 쿠폰주시니 홀케익으로도 드셔보시면 정말 좋을거 같아요. 푹푹 입안에 한가득 넣어 먹을수록 더 맛있거든요... 사장님 장사 꼭 오래오래해주세요❤️‍🔥', 29, 1, 'GOOD', SYSTIMESTAMP);
