INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '원래 투썸오면 항상 먹는 메뉴가 있는데 품절인지 없어서 새로운 메뉴인 애플망고프라페 시켜봤어요! 여름에 먹기 너무 시원하고 생각보다 달지않아서 더 좋았어요! 홍대점이라 그런지 창으로 사람들이 걸어다니는 모습도 볼 수 있어서 야외뷰도 좋았습니다:)', 16, 7, NULL, SYSTIMESTAMP);
