INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '일요일 1시경에 갔는데 남자2 여자1 있는데 안경낀 남자 웅얼웅얼 마스크 껴서 하나도 안들림; 그리고 진동벨 주면서 준비되면 불러준다면서 여자알바는 음식 다 준비해놓고 진동벨 울리게 하지도않음 그럴거면 진동벨 왜주는거임?ㅋㅋㅋㅋ', 19, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '카페라떼 디카페인 5700원 오트음료 변경 600 너무 맛있어서 놀랬다. 자리도 많고 4층에 화장실도 있다. 잘 쉬었다. 외국인들이 많이 온다.', 44, 2, 'GOOD', SYSTIMESTAMP);
