INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '빙수 메뉴가 키오스크에 없어서 직접 주문하려고 하는데 묻는말에 대답도 안하고 띠꺼운 표정으로 알바생 너무 불친절해서 기분이 나쁨 손님이 많은 주말 시간대도 아니고 월요일 평일 자리도 널널한데 점장 또는 사장님 교육 제대로 시켜야할듯 합니다. 알바들 무표정에 띠꺼운 태도가 불친절 끝판왕 돈쓰고 기분 더럽이네요 다시는 재방문 의사 없음', 36, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '여기 직원들 왤케 화가나있음? 너무 불친절해서 나한테 시비거는 줄 알았네 명찰에 캡틴이라 써있는데 캡틴이 왜 이럼? 음료 만든 남 알바생은 음료 나왔다는 말도 안함 그아무도 인사 안함 깊티로 주문 하려고 불렀는데 나한테 말을 왜걸어? 딱 이표정으로 쳐다봄', 77, 14, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '생각보다 너무 많이 더웠어요. 근처에 투썸보이자마자 들어 간 곳인데 사람도 엄청 많았고 직원분들도 친절하시고 좀 편히 쉬다 갔어요.', 28, 0, 'GOOD', SYSTIMESTAMP);
