INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '저녁때나 주말엔 안 가시는걸 추천.... 인산인해+밖엔 (버스킹 도 아닌 무슨 야애니 코스프레 한것 같은 호빗뚱녀들이 한 겨울에 헐벗고 걸그룹 댄스 커버 하는데 실력이 진짜 형편 없던.... 일본 지하 아이돌 이나 초등학생, 중학생 장기자랑 수준도 안되 보이던 안무 X 율동 O 하며 뒤뚱거림 ㅠ.ㅠ 진심 용기가 대단....) 공연(?) 음악 으로 굉장히 씨끄럽고 게다가 이건 무슨 영화 촬영장 수준의 라이트 를 쏴서 창가에 앉으면 눈이 아플 정도.... 최악은 계산 받는 직원이 너무 불친절 함.... (다른 직원분들, 특히 남자 직원분들은 굉장히 친절하심)', 5, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '대형 프랜차이즈점이라 편하고 좋아요. 영업시간이 새벽 12시 50분까지라 무엇보다 늦게까지 있을 수 있어서 친구들과 함께 하기 좋아요!!', 48, 1, 'GOOD', SYSTIMESTAMP);
