INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '로투스 아이스박스 맛도리입니다. 평소에 스초생이랑 아이스박스만 먹었는데 로투스도 맛있네여. 아아는 블랙원두로 시켜서 먹으십쇼 산미가 없어서 고소한맛 좋아하시는 분들은 커피향 맘에 드실것같네요. 매장도 4층까지 2개 층으로 되어있고 에어컨도 빵빵해서 시원합니다. 여름 대피 코스로 추천드려여. 라스고🔥', 46, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '3년 정도 꾸준히 이용했는데 한결같이 불친절하고 처음 본 외국인 스텝이 제일 친절하세요. 새음료 줄 때 가장자리 좀 깨끗하게 주세요 … 누가 먹다가 준 것 같아요.', 25, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '홍대 중심가에 있고 매장이 2,3,4 층으로 나름 넓어서 쾌적하게 이용하기 좋아요 근데 주말에는 자리 없습니다 ㅎㅎ 복숭아 케이크 맛없어요 비추합니다', 10, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '주말에 방문했는데 사람이 많았어요 창문이 커서 개방감 있어요 사람 많으면 공기가 답답한데 창문열어놔서 환기도 되서 답답하지도 않아요~ 신메뉴 블루베리 요거트케익 너무 맛있어요! 저렴한 가격은 아니지만 안에 블루베리 시럽?이랑 밑엔 그래놀라같아요 2층부터 4층까지 있고 시간도 길게 오픈해서 늦은시간오기도 좋을거같아요', 35, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '월요일 오전 여자직원 진짜ㅠㅋㅋ 키오스크에 메뉴가 준비중이라 메뉴없냐고 물어봤는데 일하기싫고 귀찮은 표정으로 행동하더라구요 ㅋㅋ', 37, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '매장이 4층까지 있어서 꽤 넓어요. 홍대라 뷰가 좋다면 좋다고도 할 수 있을 것 같네요. 버스킹 하면 보일 듯. 의자도 나름 푹신한 축에 속하는 것 같습니다. 그리고 투썸은 역시 떠먹는~ 시리즈가 맛있어요. 떠먹는 딸기 우유 생크림 케이크 맛있게 먹었습니다. 딸기 러버라 딸기 음료까지 먹었는데 맛있었어요. 쿠폰을 2개 중복으로 적용 못 하는 게 좀 아쉽긴 한데 그래도 맛있게 잘 먹고 잘 쉬다 갑니다~', 42, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '투썸 홍대걷고싶은거리점은 매장이 3개 층이여서 좋았어요! 3개 층 모두 사람 많고 거의 만석인데, 중간중간에 좌석이 있었어요! 사람이 많아서 메뉴 주문할 때 줄 서서 주문했어요🫢 여기 창가 자리가 홍대거리뷰여서 좋아요ㅎㅎ', 36, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '조별 모임으로 방문했는데 층이 많아서 오래 머무르기 좋고 노래소리가 크지 않아서 대화하기 좋습니다! 화장실은 맨 윗층에만 있어요!!', 77, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'MEETING');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '사람이 너무 많고 복잡합니다. 조용하게 커피한잔하며 쉬는 곳이 절대 못돼요. 주문도 오래 기다려야하고 컵과 포크도 없다고 매장안에서 1회용 물품에 종이컵으로 마셨습니다. 건물이 오래되어 화장실도 지저분한데 남녀 하나씩이라 많이 기다리고 계단도 너무 좁고 경사가 심해요. 의자도 오래되었구요. ㅠ 투썸 디저트가 맛있어서 간건데 홍대 투썸은 다시는 가지 않을거예요.', 30, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '투썸은 역시 케익이다! 방문한 홍대걷고싶은거리점은 층이 많지만(4층), 층마다 면적이 좁은 곳이었다. 지역이 워낙 유동인구가 많은 곳이라 좌석 찾기 힘든데, 엘베가 없어서 계단 오르락내리락;; 계단이 높아서 조금 힘들다. 화장실이 4층에 있어서 한번 가려면;;', 14, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '케이크가 차갑지 않고 따뜻해서 너무 맛이 없었습니다. 회전율이 빨라서 그런가 싶었는데 그럼 차라리 냉동이 되어있지 않아 싶었어요. 케이크는 살짝 차가워야 맛있는데 너무 아쉬웠습니다.', 41, 8, 'BAD', SYSTIMESTAMP);
