INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '홍대에서 넓은 카페찾다가 들어온 투썸인데 주말이라 사람 많아서 4층에 겨우 자리 잡았어요😂 커피는 디카페인변경으로 달달한 메뉴로 시켰습니다 4층 창가에 앉았는데 위에서 내려다보며 홍대 구경하니까 좋아요', 38, 9, 'GOOD', SYSTIMESTAMP);
