INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '2,3,4층 다 투썸인데 연말에 금요일이라서 그런지 사람들 엄청 많았어요~~ 계단의 통로가 좁아 주문한 음식을 들고 갈땐 사람들이 비켜주지 않으면 올라가기 힘들었네요. 손님들도 많은데 주문 받으시는 분도 친절하셨어요.', 123, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '집근처 방문할려다 들어가는길에 홍대걷고싶은거리점에서 케익 구입했는데 케익상태가 ㅠㅠ 딸기가 저정도면 판매 안해야되는거 아닌가요? 분명 냉장고에 있는 케익 상태는 완전 좋았었는데… 확인 후 구입했었야했는데… 생일날 케익보고 화가 났어요. 사진보다 더 형편없었어요.ㅠㅠ 최근에 다른지점에서 구입한 케익과 비교하니 할말이없네요!!! 최악의 생일케익 이였지만… 빵은 왜 맛있는거죠?🤣', 15, 7, 'BAD', SYSTIMESTAMP);
