INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '사람이 많아서 그런가 너무 정신없었어요.. 음료도 하나 안된다고 취소했다가 하나 다른거 바꾸고 주문햤는데 그전에 된다던 메뉴 앞에서 시켜서 재고 떨어졌다고 그래서 2번이나 취소되었답니다..', 50, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '너무 시끄러워요~ 화장실 4층이에요 다리아파 참아요~~ 자리 순삭 눈치게임 해야해요 2층에서 거리 버스킹 하며 젊음을구경하기 좋아요', 40, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '카피 맛있어요 근데 언젠가부터 도를아십니까같은 사람들이 많은 자리를 차지하고 있고 주문도 안한 사람들이 좋은 자리는 다 차지하고있는 사람들도 많고 매장 관리를 하시는 게 좋지 않을까 싶어요', 119, 22, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '커피와 아이스크림이 정말 맛있었고 분위기도 좋았습니다!할로윈 장식도 이쁘게 되어있어서 좋았어요! 하지만 고객응대가 별로에요.. 주문 할 때 표정부터 안 좋고 그닥 입니다 다른 고객분들께도 그러던데 평일 오후 일 하시는 분이요😢 조금만 더 친절히 대해주셨으면 좋겠어요', 15, 3, 'GOOD', SYSTIMESTAMP);
