INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '저녁9시쯤 주문하려고 서있는데 세명이나 직원인지 알바생이 있는데 아무도 안 쳐다보고 주문받으러도 안오고 기분이 상하네요 그리고 따뜻한 아메리카노랑 아이스박스 시켰는데 주문 받을때부터 주문받는 사람이 자꾸 아이스아메리카노라해서 마지막까지 따뜻한거라 얘기했는데 결국은 아이스나와서 다시 달라고 했네요 직원들이 친절하기를 바라지는 않지만 적어도 주문 받는건 잘해야 하는거 아닌가요?기분좋게 왔다가 기분만 상하네요 그리고 아이스는 다회용잔 나오고 따뜻한 아메리카노는 일회용잔에 나오네요 먼저 일회용잔에 음료나오는데 괜찮으시냐고 물어봐야하는거 아닌가요? 별로에요', 76, 15, 'BAD', SYSTIMESTAMP);
