INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '4층까지 매장이 있는데 크기가 생각보다 넓지는 않아요!! 그리고 화장실이4층에 있는데 영수증에 화장실비밀번호 적혀있어서 주문안하시면 화장실 사용못해요!!', 43, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '홍대에서 걷다가 너무 더워서 들어갔는데, 직원분도 친절하시고 시원해서 좋았어요~ 그냥 대충 상큼한 거 먹고 싶어서 시켰는데 ⭐️🍑‘복숭아 에이드’🍑⭐️ 이거 존맛이니깐, 어느지점이든 투썸가실 때 다들 한번 꼬옥 먹어보세요~!', 16, 1, 'GOOD', SYSTIMESTAMP);
