INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '매장이 크고 넓습니다 역시 메인 거리이 있어서 유동인구도 많네요 좌석들이 편해서 좋습니다 그리고 홍대에서 프렌차이즈커피샵중에서 제일 영업시간이 긴거 같아서 자주이용하려고합니다', 32, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '넓은 매장. 청소 상태는 별로 안 좋고 카페 소파는 일부 너무 낡아서 너덜너덜함. 음료는 그냥저냥 먹을만. 넓은 데 찾으면 가고 아니면 별로.', 2, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '지인 만나러 가는 길에 빈 손으로 가기 좀 그래서 주변을 둘러보니 투썸과 할리스가 나란히 있었어요. 둘 중 어느 곳으로 가야할까 고민하다가 아무래도 케이크는 투썸이 더 맛있을 것 같아 갔는데요. 근데 직원분이 불친절하셔서 조금 기분이 상했네요. 할리스 갈껄. 케이크는 참 이뻤는데, 다시는 방문하지 않을 것 같아요.', 31, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '1.테이블 너무 더러웠어요. 2.금요일 낮에 카운터에 계신 여직원분이 다른 직원분이랑 사진찍고 놀고계시면서 주문 안받으시길래 주문해도되냐고 물어봤더니 정색하시면서 대답도안하시고 쳐다보셨어요. 카드 꽂아달라는 안내도 없으시고.. 3.커피 두개시켰는데 디카페인하고 일반 아메리카노 시켰는데 어떤게 디카페인인지도 안내가없으셔서 물어봐야만 대답해주시네요.^^ 친절함 조금만 더 갖춰주시길', 17, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '투썸 케익 맛있음 음료는 그냥 그렇지만 케익 먹으러와도 될정도 홍대 한가운데에 있어서 그런지 사람이 너무많아여 ㅜ 잘못하면 자리 없을뻔', 50, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '진짜 최악입니다. 홍대라서 사람 많고 정신없는거 잘 알고 있습니다. 근데 본인이 기분이 안좋은걸 왜 손님한테 화풀이를 하는지 도대체가 이해가 안가네요. 일단 키 별로 안크신 여자 알바분 주문 전 부터 표정 썩어있었어요. 제 카드가 꽂아서 결제가 안돼서 긁어서 결제하는 방식만 된다고 좋게 말씀드렸는데 제 말 무시하고 “꽂으세요.” 이 한마디만 하고, 결국 안되니까 자기가 카드 확 가져가서 카운터 단말기에 또 꽂아서 결제를 하시더라구요? 그리고 (당연히)안되니까 절 확 째려보고는 결국 긁어서 결제하시더라구요. 그리고 음료를 받았는데 음료가 진짜 너어~무 시고 맛이 이상해서 몇 모금 마시고 도저히 못먹겠어서 결국 못마셨어요.. 요거트 쉐이크 투썸 갈때마자 항상 먹는 음료라서 무슨 맛인지 아주 잘아는데 이건 아녜요', 28, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '목요일 저녁타임에 머리에 인형 삔 꽂고 있던 여자 알바생분 너무 불친절하셔서 조금 당황스러웠어요. ㅠㅠ 주문 받으실 때랑, 매장 이용 중에 저한테 말 거셨을때 모두 조금 부드러운 말투를 써주셨으면 좋지 않았을까 싶네요~ 예전에 자주 왔었는데 앞으로는 방문하지 않을 것 같아요!', 27, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '생긴지 얼마 안되서 그런지 매장이 깨끗하고 직원분이 친절하세요! 밖이 시끄러워서 공부하기엔 적절하지 않은 위치지만.. 잠깐 들러 사먹기엔 좋음! 앉아서 편하게 버스킹 관람 가능해여', 24, 3, NULL, SYSTIMESTAMP);
