INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '3-4층되는 커피숍인데 워낙 걷고싶은(사람많이다니는)거리에 있어서 그런지, 관광객+내국인 모두 많아서 좌석확보가 관건. 머그잔들고 길거리에서 커피마실판. 손님이 워낙 많아 주문하는곳이 조금 복잡해도 직원분들이 친절하고 빠름빠름빠름', 6, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '홍대거리 걷다가 들어왔어요 사람 많은 곳이라 자리잡기 힘들어요.. 화장실은 주문하면 영수증 하단에 있는 화장실 비밀번호 보고 이용할 수 있어요~ 투썸은 역시 디저트짱입니다', 8, 4, 'GOOD', SYSTIMESTAMP);
