INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '토요일이라 그런지 사람이 엄청 많았다. 빈자리 찾기가 쉽지않았다. 4층까지 있어서 여유롭게티타임가짐. 화장실이 4층에있는데 칸이 2칸이라 좀 비좁다는 생각이들었다', 13, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '아이스유자레몬티를 주문했는데 한입 먹기 유자껍데기랑 시럽이 한뭉텅이로 올라와서 놀랬어요 섞었더니 빨대가 반으로 휘어지고.. 흠.. 별로에용 ㅋㅋㅋㅋ 섞어서 주시면 좋았을 텐데', 108, 22, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '음료도 맛있고 직원분들 친절하세요. 케이크 사러갔는데 사고싶었던 건 홍대+크리스마스 시즌이라 금방 팔렸는지 없어서 못 샀네요. 대신 다른 케이크 사갔는데 맛있어요.🙂', 29, 8, 'GOOD', SYSTIMESTAMP);
