INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '홍대 투썸플레이스 홍대 공연거리에 있어서 저녁엔 볼것도 많을듯 신촌에만 있는건지 신촌커피라는게 있어서 시켜봄 딸기 케이크는 맛있음', 83, 14, 'GOOD', SYSTIMESTAMP);
