INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '정말 폭풍감동의 현장처럼 카페에 익숙치 않은 나 자신을 편안하게 느끼게 해주는 육각형 헥사곤 카페라는 생각이 드네요, 제가 선택한 그린티 라떼 레귤러핫은 정말이나마 만족스러웠답니다. 다시한번이곳에 들려 나의 추억을 정립하고 싶어질만큼 이곳은 우 나 핫하고모시깽이하고 정말 홍대의 거리가 잘 보이는 만족스러운 투썸이었습니다. 많은 사람들에게 와이파이와 화장실이 제공되는"투썸플레이스 걷고싶은 거리점" 한번 가보시길 추천할정도입니다. 홍대에서의 분주함과 인간력을 느끼며 좋은 하루되시길 바라겠습니다.  :)', 67, 12, 'GOOD', SYSTIMESTAMP);
