INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '4월22 15:21 결재.  너무 너무 불친절해요.  주문 받을때부터 표정이 화가났네요.. 말도 못걸겠어요 뭐좀 물어봤는데 표정이 무섭네요  조각케익 포장했는데 포크도없고 박스찢어서 먹고있습니다.', 39, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '매장은 좁은 편이지만 2~4층이라 작은 느낌은 마니 안듬. 음료 한정 메뉴 같은데 생각보다 맛있음. 4층에서 내려다보는 풍경이 홍대 버스킹존이라 멍 때리며 사람 구경하기 좋음', 42, 0, NULL, SYSTIMESTAMP);
