INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '체인점이라 음료는 맛있었지만 직원분이 대응이 좀 별로였어요. 음료 주문 중에 화장실이 너무 급해서 급하다고 말씀드리니 영수증에 기재 되어있다고만 말하시고 절대 비번 안알려주시고..하...음료구매를 안하는 것도 아니고 융통성이 좀 없다고 느껴졌어요', 43, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대걷고싶은거리점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '바쁜건 알겠는데 아메리카노 한잔 17:47분에 주문함—>너무 안나오길래 사람 많아서 바쁜가보디 함—>나보다 한참 늦게 주문한 사람이 음료 받아옴—> 가서 물어봄 누가 가져간거 같다는 말만함(심지어 진동벨도 안울림)—> 18:16에 받음아이스 아메리카노 한잔 받는데 30분 걸림 먼저 말 안했으면 1시간도 기다렸을뻔', 14, 4, 'BAD', SYSTIMESTAMP);
