INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '매장 내부가 정말 깔끔하고 세련되게 관리되어 있어서 들어서는 순간 기분이 좋아졌습니다. 무엇보다 말차라떼가 진짜 맛집이에요! 진한 말차 맛과 부드러운 우유의 조화가 완벽해서 단숨에 다 마셔버렸네요ㅎㅎ', 11, 8, 'GOOD', SYSTIMESTAMP);
