INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '아메리카노랑 말차크레이프 둘 다 맛있고, 카페 공간이 감성적이라 앉아만 있어도 기분 좋아요 ☕🍵 직원분도 친절해서 편하게 머물 수 있었고, 전체적으로 아늑한 분위기 덕분에 힐링 되는 느낌이었어요✨', 6, 5, 'GOOD', SYSTIMESTAMP);
