INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '1층 핑크문을 열고 들어가면 통창의 빛을 받으며 지하로 내려가는 계단이 나와요 공간이 재밌어요 커피 맛있어요 수제스콘.쿠키 포장했어요 담엔 브런치와 파르페 먹어 봐야겠어요 직원분 친절해요 재방문할거에요', 22, 5, 'GOOD', SYSTIMESTAMP);
