INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '여기 카페 찐 맛집이에요 .. ㅠ 음료도 맛있는데 우유크림도넛이 짱맛입니당 ! 식물성 크림 쓰는 곳은 싫어하는데 여긴 동물성 생크림 사용하시는 것 같아요! 고급스럽고 느끼하지도 않아서 계속 먹을 수 있을것 같아요 .. 👍🏻', 28, 8, 'GOOD', SYSTIMESTAMP);
