INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '저 완전 녹차홀릭인데 파르페 비쥬얼 완전 최고예요~비쥬얼만큼이나 맛도 최고예요😍 스트로베리 밀크티도 신선하네요~ 너무 맛있게 잘 먹고 왔어요~ 매장도 깔끔하고 친절하게 서비스해주셔서 기분 좋았어요☺️', 13, 2, 'GOOD', SYSTIMESTAMP);
