INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '와 처음보는 바나나티라미수라니 딸기만 먹어본저는 이 달달함에 녹아효! 너무 맛있어요 파르페맛집인건지 여기저기 전부 파르페 트시더라고요! 저는 아메리카노랑 먹고 왔는데 커피도 디저트도 넘 맛있음', 90, 11, 'GOOD', SYSTIMESTAMP);
