INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '너무 더워서 아아 마시러 들어갔는데 분위기 아늑하고 좋네요 커피 너무 맛있어요 🩷 여기 메뉴도 다양하고 달달구리는 왜키 많은가요? 😍😍😍😍😍😍😍😍 담엔 아이와 함께 오려구요 💕', 10, 8, 'GOOD', SYSTIMESTAMP);
