INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '커피 수혈 필요해서 아아 시켰는데 아니 오늘따라 내가 이상한건지 그냥 여기가 맛집인건지 커피 맛이 너무 좋더라구요 진짜 아아수혈 필요할때마다 오고싶은 맛이였고 넘 더워서 수박스무디도 시켰는데 와 완벽. 이말 한마디로 정의합니다.', 24, 4, 'GOOD', SYSTIMESTAMP);
