INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '달달한 콜드브루 카라멜라떼는 처음인데 와,,, 이거 제 최애 메뉴 될 것 같아요🥹 너무너무 제 취향이고 맨날먹어도 안질릴 맛!! 넘 짜릿해요 ㅎㅎ 직원분도 항상 친절하셔서 넘 좋았습니다~~', 128, 21, 'GOOD', SYSTIMESTAMP);
