INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '친구랑 홍대에서 놀다가 날도 덥고 목도 말라서 우연히 지나가다 들린곳인데 내부가 너무 깔끔하고 사진찍기에도 인테리어가 정말 예쁘더라구용❤️ 무엇보다도 상하목장 아이스크림 너무 맛있었어요! 재방문의사 200프로입니당😃', 14, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '여기 매장은 넓고 좋은데 저는 포장으로 아메리카노를 샀거든요 ! 완전 가성비있게 구매할 수 있어서 너무 좋아요 그리고 커피 맛도 너무 좋아서 유일하게 아침마다 가는 곳이랄까요.. ㅎㅎ', 77, 16, 'GOOD', SYSTIMESTAMP);
