INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '애플뱅쇼 따뜻하게 마시니깐 진하니 넘넘 맛있네요~^^💙 가게 분위기도 아늑(?)따뜻(?)한 분위기여서 사진찍기에도 이뻤고 이번엔 혼자 여유롭게 있었는데..다음엔 친구랑 가서 수다 떨려고요ㅎㅎㅎㅎ', 14, 4, 'GOOD', SYSTIMESTAMP);
