INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '가게도 예쁘고 메뉴도 다양해서 고르는데 한참 걸렸네용샌드위치랑 빠네 스프까지 가격도 착하고 아침에 여유롭게 브런치먹기 좋았어요 종종 아침에 들러서 있는 메뉴 다 먹으려구용', 36, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '홍대에서 넓은 대형 카페 찾으신다면? 여기 카페그랑주 가보시는걸 추천드립니다. 지하1층에 있는 홍대 카페:  카페그랑주 파르페 맛집이라고 하는데, 저희 커플은 여자친구의 픽: 초콜릿케익을 먹었는데 초콜릿케익도 여자친구의 입맛에 합격ㅎㅎ (여친님의 입에 맞으면 당연히 합격 그자체입니다) 다음번은~~~ 파르페도 먹으러 가볼 생각입니다.', 42, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '커피한잔하면서 남은번역작업하기위해서 슬쩍 카페그랑주에 다녀왔는데!! 대박😆 넓고 시원하고 쾌적해서 너무너무 좋았는데,,, 여기에 아아한잔하면서 열심히 번역일까지 해서 마무리할수있어서 좋았어요!! 다음에는 친구들이랑 방문할게요❤', 24, 5, 'GOOD', SYSTIMESTAMP);
