INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '저녁을 먹고 당 떨어지는 것 같아서 후식으로 디저트 먹으려고 방문했습니다! 아메리카노랑 레몬버터로 바로 충전 완료했어요 다음에도 당 떨어지고 단 게 먹고 싶으면 또 방문해서 먹으러 올게요 ㅎㅎ', 22, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '꺄악!!!! 파르페는 일본에서만 먹는 줄로 알았는데 한국 그것두 그리 멀지않은 홍대에 이런 파르페가 있을줄이야😍 비줠부터 걍 사랑이죠? 맛은 더 사랑입니다^^* 조금은 달거란 제 예상을 완전히 깨고 정말 순수한 우유생크림과 딸기가 가득 채워져있구요 중간중간 과하지않게 치즈큐브랑 콘프레이크가 살짝씩 식감과 맛을 끌어올려주면서  맨위에는 리얼딸기로 만든 딸기젤라또와 맨밑에는 수줍게 살짝 깔린 딸기시럽 글구 초코과자2개가 이 파르페의 아름다운 구성입니다  빵은 없지만 무슨 떠먹는 케잌같이 부드럽고 실키하고 상큼하고 딸기의 과일 단맛이 극대화된 조합으로 진짜 넘 맛있어요💓 점심시간이라 살짝 배고프길래 브런치메뉴로 토마토스튜도 주문했는데 이것도 기대이상 맛있어서 놀랐어요 앞으로 한국에서 파르페명가는 그랑주입니다!!!', 4, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '아이가 파르페 먹어보고싶다고해서 방문해본곳이예요. 파르페가 양도 많고 아이가 너무 맛있어했어요~ 저는 따뜻한 뱅쇼 먹었는데 .. 그동안 마신 뱅쇼중에 탑이예요~!! 바나나 티라미수도 추천해요~ 직원분도 친절하시고 아들과의 홍대나들이의 추억하나 더 쌓았네요. 단, 화장실 쪽 자리는 주말이라서 그런지 ..불쾌한 냄새가.. 다른자리에 앉긴했지만 입구와가까운 자리가 냄새가심하니 좀 그렇더라고요  방향제라도 놓으면 좋겠더라고요~ ㅎㅎ', 48, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '인테리어 분위기가 좋아보여서 날씨도 덥고 해서 우연하게 들어갔음 예상대로 아늑했음. 수박을 좋아해서 수박스무디주문했는데 맛이 깔끔하고 수박맛 그대로라서 많이 놀람. 주문하길 잘한 것 같음.', 25, 7, NULL, SYSTIMESTAMP);
