INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '파르페랑 타코치킨 치아바타 너무 맛있어요🥹 치아바타 속이 알차서 든든히 먹었습니다🥰!! 파르페도 딸기 완전 많구 시리얼도 있어서 순삭했네요🤭🤭 매장 넓고 대화하기 좋구, 테이블 마다 조명도 있어서 사진, 셀카도 잘 나오네요 ㅎㅎ 좋은 시간 보내다 갑니당~🥰 잘먹었습니당', 2, 9, 'GOOD', SYSTIMESTAMP);
