INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '이제껏 먹어본 뱅쇼중에 단연 제일 맛있었어요! 아이리쉬커피까지 준비되어있고 알콜이 들어간 믹솔리지 음료종류도 다양해서 선택하는 재미가 있었어요! 특별한 분위기에서 즐기기 딱 좋았어요!', 36, 9, NULL, SYSTIMESTAMP);
