INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '생딸기파르페가 너무 맛있어요,,,🥹🍓 카페 분위기도 넘 아늑하고 편안한 의자 소파들이 많아서 좋았어요! 데스크 테이블도 있어서 공부 잠깐하기에도 좋을 것 같아요 빵도 엄청 잘 나오고 위생적으로도 깔끔해서 좋았어요 케이크도 종류 정말 많고 음료도 다양하게 있어서 다 먹어보고싶어요ㅜㅜㅜ 딸기파르페랑 딸기 크로와상 먹었는데 둘 다 짱 맛있어요.. 또 가고싶어졌어요', 13, 8, 'GOOD', SYSTIMESTAMP);
