INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '아침에 뭔가 가볍게 먹고 싶어서 카페 갈겸 들렸어요 아침에 가볍게 과일샐러드 즐길 수 있어서 너무 좋은 거 같아요 ! 과일도 싱싱하고 일단 너무 맛있다는게 팩트에요 ! 덕분에 달달하고 맛있는 과일을 먹을 수 있어서 너무 만족해요 ㅎㅎ', 3, 6, NULL, SYSTIMESTAMP);
