INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '🍦파르페먹고싶었는데 8시반 파르페마감으로 못먹어아쉬움 ☕️디저트 괜찮았고 홍대대형카페느낌으로 얘기나누기좋아요 🍰친절해요 🫚주차불가', 9, 9, NULL, SYSTIMESTAMP);
