INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '로즈 봄베이 레드넥타, 제임슨 블랙아이스티 하이볼 엄청 맛있습니당 아늑한 분위기도 좋고 인테리어도 예뻐서 여유롭게 친구랑 대화하면서 잘 마셨어요 좌석도 편해서 좋았어요 만족하고 갑니당!!', 73, 15, 'GOOD', SYSTIMESTAMP);
