INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '딸기파르페랑 딸기아이스크림 먹었는데 딸기 시지않고 달았어요! 상하목장 아이스크림이 있어서 딸기도 상하목장인가 싶었는데 딸기아이스크림은 상하목장이 아니더라구용! 자리도 넓고 매장도 커서 잘 놀다 갔습니다~', 17, 1, NULL, SYSTIMESTAMP);
