INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '커피가 굉장히 고소해서 맛있습니다! 파르페는 워낙 유명해서 그런지 그냥 맛있구요 빠네스프 같은경우엔 처음에 갑자기 비린맛이 나길래 놀래서 매니저님께 문의드렸더니 바로 새걸로 바꿔주시더라구요 조리기구를 오늘 새거로 바꿔서 직원분들 사용이 서툴러서 그랬다고 매니저님께서 직접해주셨는데 정말 맛있었습니다! 혹여나 진상처럼 보일수 있는 문의에도 불구하고 너무 친절하게 대처해주신 매니저님 덕분에 기분좋게 수다떨다갑니다!🥰🥰', 22, 4, 'GOOD', SYSTIMESTAMP);
