INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '친구 따라 방문했는데 베이컨토마토샌드위치가 너무 맛있었어요 ㅎㅎ 재료도 맛도 깔끔하고 딱 제가 좋아하는 스타일이라 바로 하나 포장했네요👍🩷 다음에 또 먹으러 올게요~!! 굿굿', 4, 3, NULL, SYSTIMESTAMP);
