INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '여럿이서 방문했는데 대형테이블이 있어서 단체모임하기 좋아요. 커피도 맛있었고, 베이커리 종류도 꽤 있어서 간단하게 식사하기도 좋을 것 같습니다. 같이 간 지인이 음료를 살짝 쏟았는데 친절하게 응대해주셔서 감사했어요 :)', 65, 14, 'GOOD', SYSTIMESTAMP);
