INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'MEETING');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '일단 공간이 넓고 날이 춥거나 더워도 한층 아래 있는 매장이라 여건이 좀 낫다는게 장점 근데 화장실 근처 단체석은 화장실냄새가 좀 많이남 (화장실 자체는 깨끗한편인데 하수구문제인듯) 디저트도 여러가지 있어서 편하게 가기 좋은카페', 63, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '카페가 힙해서  들어갔어요. 베이커리 종류가 다양해요 ~ 생딸기파르페도 같이 시켰는데 생크림과 딸기가 엄청 듬뿍들어있고 새콤하면서 달콤 양이 많아서 좋아요. 또먹으러 방문할께요^^', 11, 2, 'GOOD', SYSTIMESTAMP);
