INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '매장도 넓어서 모임하기에도 너무 좋고 매장도 청결하고 쾌적했어요 생딸기파르페가 유명하다고해서 왔는데 와 진짜 생딸기를 아낌없이 올려주시는데 진짜 맛있고 최고에요👍', 81, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '친구생일이라 ~~오며가며 눈여겨봤던 카페그랑주 들어가는 입구부터 이뽀이뽀 ~~~ 집에 가져갈 케잌이지만 축하도 해주고 미니컵케잌은 하나 클리어 다음번엔 디저트도 먹으러갈께요', 25, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '크로크무슈가 무난하게 막있는 맛이되 갠적으로는 크레페가 품절이어서 아쉬웠지만 러블리 스트로베리 안에 있는 견과류들이나 건포도 오레오 등과 요거트가 꽉꽉 채워지면서 딸기와 딸기 아이스크림과 함께 조화로운 거 같네요 루프탑은 가게  밖에 나가야 갈 수 있다는 게 조금 아쉬웠고요. 가게에서 잘 먹었습니다.', 34, 4, NULL, SYSTIMESTAMP);
