INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '다른 곳보다 티라미수의 씁쓸한 커피 맛이 더 잘 나네요 빙수는 밑으로 파 먹을수록 더 달달해요 두 번째 방문인데 갈 때마다 사람이 붐비는 것 같아요 🥺👍', 42, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '메뉴가 엄청 늦게 나오고 먼저 나온 음료부터 가져가려고 했더니 안 된다고 하시더라고요. 사장인지 직원인지 모르겠으나 친절하지도 않고, 화장실도 수리 중이라 5층까지 올라가야해서 엄청 불편합니다', 2, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '테이블은 파르페 잔해로 끈적끈적하고, 가장 기본적인 쓰레기통도 없습니다. 베이커리 테이블 바로 옆에 손님 테이블은 왜 두시는건가요...? 이런 카페는 난생 처음입니다.', 20, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '굿즈샵 돌다 주변에 있는 카페 찾아들어갔는데 너무 넓어서 엥 했음 진짜 엄청 넓음 인스타사진용처럼 생겼는데 좌석들도 나름 편함 디저트들이 저렇게 덮개 하나 없이 있어서 위생적으로 별로 안 좋아보였고 저 쪼만한 파르페가 무려 9000원인게 좀 아쉬웠음 홍대인걸 감안해도 진짜 비쌈.. 맛없었으면 화날 뻔 그리고 화장실에 의자가 너무 예쁨 딱 봐도 사진 찍으라고 만들어 놓은듯한ㅋㅋㅋ', 39, 2, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '친구랑 딸기 파르페 먹고 싶어서 왔어요! 중간에 요거트인지 찐득해서 저는 좀 별로였어요 그냔 한번 먹어볼만한 맛..? 다른 디저트나 음료도 맛있어보여서 다음에 또 방문할 의사는 있습니다! 매장 크고 넓어서 대화하기 좋았고 화장실도 굉장히 깔끔했어요!', 87, 16, NULL, SYSTIMESTAMP);
