INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '파르페 아이스크림 맛있어요! 딸기도 신선했고 안 쪽에는 견과류랑 크렌베리가 엄〰️〰️〰️〰️청 많아요❕ 빵 종류도 다양한 편이에요🥖', 19, 10, 'GOOD', SYSTIMESTAMP);
