INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '파르페 먹고 싶어서 우연히 들어갔는데 너무 좋았어요~매장도넓고 사람이 많지 않아서 대화 하기 좋았어요. 재료도 아끼지 않고 팍팍쓴게 느껴지더라구요 ㅎ다음에 또 갈거에요', 32, 3, 'GOOD', SYSTIMESTAMP);
