INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '빨미까레 너무 맛있었어요 ㅎㅎ 정작 빨미까레 사진이 없네요.. 포장으로 2개 사고 나왔는데 초콜릿+아래까지 달달함으로 코팅되어 맛있었습니다.', 61, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '딸기 파르페와 아메리카노를 주문했습니다. (13,900원/5,000원) 매장은 공간이 넓습니다. 주문은 키오스크로 합니다. 화장실은 입구쪽에 있으며 깔끔합니다. 딸기 파르페는 딸기도 은근 들어있고 달달한 파르페입니다. 하얀 크림은 우유맛과 밤과 같은 고소한 맛도 나서 찐득합니다. 한명당 하나씩 주문해도 적당할듯합니다. 아메리카노는 적당했습니다. 다음에도 파르페가 떠오른다면 방문할 거같습니다.', 43, 2, NULL, SYSTIMESTAMP);
