INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '일하는 분이 친절하셔서 좋아요. 여름 디저트를 잘 하는 집이라 여름에는 특히 붐비지만, 겨울에도 방문해서 디저트와 음료를 먹기에 좋아요.', 23, 7, 'GOOD', SYSTIMESTAMP);
