INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '너무 기대했는지..!! 제 기대보다는 별로.. 맨위 다먹고 두번째 층 들어가니까 좀 느끼했어요. 이럴줄 알았으면 작은거먹을껄 실망', 0, 8, 'BAD', SYSTIMESTAMP);
