INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '와 홍대에 이렇게 이쁘고 넓고 괜찮은 카페 있는지 첨 알았어요 너무좋아요 진짜 ... 저만알고 싶을정도에요ㅠㅠ 적극추천합니다!! 음식도 넘 맛있고 분위기 짱 좋습니당', 42, 9, 'GOOD', SYSTIMESTAMP);
