INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '생딸기 파르페 최고네요! 생딸기 가득하게 많고 코푸레이크, 치즈, 생크림, 싱싱한 생딸기가 어우러져 맛있어요~ 그리고 앙버터 크로와상도 역시나 무염버터와 수제 팥앙금이 건강하게 맛나서 최고인 듯요~ 가게 인테리어도 뭔가 반전이 있어서 멋져요 ㅎ 홍대 카페, 카페그랑주 좋네요! 특히 생딸기 파르페는 정말 예뻐서 인스타그램 감성인 듯요 👍', 10, 7, 'GOOD', SYSTIMESTAMP);
