INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '참치 오믈렛 크로와상 진짜 너무 맛있어요❤️❤️ 많이 자극적이지 않고 크리미하면서 짭쪼롬해 아아랑 브런치로 딱 좋아요👍🏻 파르페 맛집 답게 아주 달달구리해서 당충전도 제대로 할수 있어요! 크렌베리+브라우니+아이스크림 조합 미쳤!!! 존맛입니당', 14, 9, 'GOOD', SYSTIMESTAMP);
