INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '분위기 좋은 디저트 갬성카페 였어요! 좌석도 넓직 넓직하고 소파도 푹신푹신하니 요즘 신생카페의 딱딱한 의자가 아니라 편리함을 더 위한 카페여서 더 좋은 공간이지 않나 싶었습니다 홍대카페여서인지 곳곳의 공간들이 예술적으로 보였어요 ㅎ 게다가 음료와 디저트 브런치 종류까지 어쩌면 올인원 카페! 여기서 모든것을 해결 할 수 있어 나갈 수 없는 매력의 공간이지 싶어요~ 크로와상 , 에그타르트 , 도넛 등의 빵류 점심과 저녁 한끼로 충분한 브런치류 풍부한 메뉴들과 넓은 실내 그리고 화장실까지 있는 곳! 와이파이 + 콘센트 보유 등 카페로 출근하고 싶은 갬성입니다! 소정의 서비스를 지원받아 작성한 리뷰 입니다!', 38, 9, 'GOOD', SYSTIMESTAMP);
