INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '매장이 엄청 넓고 맛있는 브런치와 함께 파르페도 맛볼 수 있는 곳입니다!! 매장이 엄청 넓어서 대화하기도 좋고, 빈티지스럽게 인테리어가 잘 된 모습이 굿!! 👍 요즘 파르페 파는 곳이 많이 없는데 카페그랑주에선 예쁘고 맛난 파르페를 먹어볼 수 있어용 강추입니다용😍🫶💝 소정의 서비스를 지원받아 작성한 리뷰입니다.', 25, 7, 'GOOD', SYSTIMESTAMP);
