INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '커피도 고소해서 완전 좋았고, 토마토 모짜렐라 치아바타 샌드위치도 너무 맛있어요ㅎㅎ 파르페는진짜 오랜만에 먹었는데 이거 하나로도 든든하고ㅋㅋ 기분좋아집니다ㅎㅎ 매장도 넓고 시원 그리고 곳곳에 그림도 많아서 여름 피서는 여기로 와야겠어요ㅎㅎ 브런치메뉴도 알차고 소의자도 편해서 앉아있기 좋더라구요! 아 그리고 여기 사장님 잘샐겼어요!! (나만알기 아쉬우니까ㅋㅋ 좋은 정보는 널리 알리기...ㅎㅎ) 소정의 서비스를 지원받아 작성한 리뷰입니다', 20, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '그랑주의 시그니처메뉴 파르페랑 샌드위치 브런치로 즐겼는데 너무 만족하며 먹었어요 파르페는 평소에 잘 접하질 않았는데 그랑주 파르페 먹고 완전히 반해버렸네요.. 속재료가 너무 알차고 조화롭고 무조건 추천입니다 사람많은 홍대에서 아늑하게 즐길 수 있고 다양한 베이커리가 많아서 안 갈 이유가 없는 듯한 느낌.. 재방문 할래요 하트', 29, 2, 'GOOD', SYSTIMESTAMP);
