INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '음료는 괜찮은데 진짜 케이크 ….. 이런 맛없는 케이크 진짜 오랜만이에요 우와 진짜 못먹겠더라구요 6명 다 일심동체로 안먹었어요……', 41, 5, 'BAD', SYSTIMESTAMP);
