INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '가격은 좀 비싸구..☆ 카페디자인이나 의자는 푹신해서 좋아요! 파르페 사진으로 맛있어보여서 시켰는데 견과류만 잔뜩있어서..목맥혔어여..ㅋㅋㅋㅋㅋ', 13, 6, NULL, SYSTIMESTAMP);
