INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '생딸기파르페가 너무 맛있쪄요 폴인스윗 파르페도 맛있고요❤ 음료뿐만 아니라 빵과 도넛도 많이 있어요 아침마다 직접 굽는다고 하네요~ 인테리어도 이쁘고 화장실이 정말 깨끗했어요 좌석도 넉넉해서 좋아요^^', 7, 10, 'GOOD', SYSTIMESTAMP);
