INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '홍대에 이런 카페가 있었더니 너무 쾌적하고 좋습니다 쉬어가기 좋은 카페네요 ^^ 파르페도 너무나 달콤하고 특히 타코 치킨 베이글 맛있어서 재방문 의사 있습니다 ㅎㅎ 소정의 서비스를 지원받아 작성한 리뷰입니다.', 50, 0, 'GOOD', SYSTIMESTAMP);
