INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '🩷🩷🌸소녀들에게 알립니다🌸🩷🩷 빵🥐과 케이크🍰가 맛있어요 매우매우🥰 그러나 케이크🧁의 맛🍴과 직원🙎🏻‍♂️🙎🏻‍♀️의 친절함이 반비례합니다😊 기분좋게😍 와서 돈💸내고 불친절함과 주문📋 까먹어서 몇번 찾아가야🤸🏻‍♀️ 케이크🎂를 주는 경험을 바란다면 여기로! 🩷🩷', 30, 6, 'BAD', SYSTIMESTAMP);
