INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '디저트 너무 과하게 달지 않고 딱 맛있어요! 카페도 넓고 예뻐서 대화하기도 좋아요! 특히 화장실이 너무 예뻐서 놀랐습니당 ..ㅋㅋㅋㅋ', 42, 9, 'GOOD', SYSTIMESTAMP);
