INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '분위기 좋은 홍대 카페 입니다. 브런치 메뉴도 훌륭해요! 특히 크로와상 오믈렛 샌드위치 추천드려요 치즈, 토마토, 로메인상추의 콜라보입니다 속에 달걀 오믈렛이 들어 있었는데요 일반 오믈렛이 아니고 참치가 들어 있어서 담백하고 든든하더라구요. 일반 크로와상 샌드위치인줄 알았는데 속이 꽉차서 든든하게 먹었습니다!', 41, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '생딸기 파르페가 맛있다고 해서 주문!위에 올라간 샤베트 정말 맛이 고급지고 맛있어요 직접 만든는 베이커리도 맛보고 싶었는데 배불러서 못먹은게 한 입니다 또 방문할겁니다 직접 굽는 기계도 매장에 있고 신뢰가요 소정의서비스를 지원받아 작성한 리뷰입니다', 66, 17, 'GOOD', SYSTIMESTAMP);
