INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '카페그랑주 외관이 예뻐서 궁금했는데 ㅎㅎ 내부도 넓고 미술작품들이 많았어요~👍 친구들과 오기 좋은 홍대카페 였습니다❗️ 빵과 케이쿠, 파르페 같은 특별한 디저트를 맛볼 수 있는 점도 좋았어요 ☺️', 24, 1, 'GOOD', SYSTIMESTAMP);
