INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '브런치겸 눈앞에 보이길래 갔는데 성공적입니더 커피 빵 다 맛있는데 남자친구가 생초코라떼 먹고 너무맛있다고 좋아했어요 ㅎㅋㅋ😋🫶', 23, 9, 'GOOD', SYSTIMESTAMP);
