INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '이야기하기 좋고, 화장실이 청결해서 좋았어요 커피 맛은 괜찮아요 다만 직원분들은 정말 일하기 싫으신가봐요 테이블에 음식물이 그대로 있길래, 카운터가서 남자직원분한테 테이블좀 뭐로 닦아야 할 것 같아요 라고 말했더니 물티슈를 주시네요ㅋㅋㅋㅋㅋㅋㅋㅋㅋ 카페 많이 다녀봤지만 전 손님의 음식물을 직접 치우라고 하는 카페는 처음이에요 물통이 비어서 물 달라니까 대답도 안하고 통화하면서 세상 귀찮은 듯 주셨어요 파르페가 대표 메뉴여서 그런지 크로아상은 너무 눅눅했어요', 57, 15, 'BAD', SYSTIMESTAMP);
