INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '카페인테리어도 이쁘고 , 심지어 이렇게 넓은 곳이 연남동에 있었다뇨 ㅎㅎㅎ 거기다가 파르페파늠곳은처음인데 비주얼대박이에오 ㅎㅎㅎㅎ 외국인도 진짜 많고,, 숨은 인기 연남동카페였어요🫶🏻', 29, 1, 'GOOD', SYSTIMESTAMP);
