INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '새콤달콤한 딸기 파르페를 맛볼수 있는곳! 상콤한 아이스크림에 생크림, 견과류와 과자까지 다양한 맛을 한컵안에 담아서 너무 달달한게 디저트로 딱입니당ㅎㅎ 친구들이랑 오기 좋아요!❣️', 27, 3, 'GOOD', SYSTIMESTAMP);
