INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '싱싱한 딸기가 끝까지 가득 들어간 파르페 맛집이에요 케이크랑 베이커리도 다양해서 고르기도 힘들었어요ㅎ 다른 곳에서는 볼 수 없는 예쁜 메뉴들이 있는 카페!! 데이트로 무조건 추천이에요', 58, 14, 'GOOD', SYSTIMESTAMP);
