INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '카페 그랑주 카페 안도 굉장히 넓고, 조용해서 카공하기 좋아요! 디저트도 너무 맛있고 음료도 맛있어요. 가게 인테리어도 분위기 있어요', 32, 9, NULL, SYSTIMESTAMP);
