INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '진짜 오랫만에 퀄리티가 너무 좋은 파르페를 만나서 기분이 좋았습니다👍 딸기도 신신하궁 위에 딸기아이스크림 진짜 상큼하고 약간샤베트같은 느낌이 취향저격이였습니다. 가격이 좀 있어서 자주는 못오겠지만ㅠㅠㅜ 그래도 파르페먹고싶으면 제일먼저 떠오를거같은 가게👍', 11, 8, 'GOOD', SYSTIMESTAMP);
