INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '파르페 먹고 팟는데 솔드아웃으로 못먹고 토마토쥬스오ㅏ 커피와 티라미슈 주문해서 먹었는데~ 티라미슈는 촉촉하니 맛났지만.. 커피도 아쉽고.. 토마토쥬스는 딱봐도 토마토 양이너무 적어서 맹맹하고 묽었어요 ㅠㅠ 디저트만 굿! 다른 음료는 아쉬웠네요 ㅠㅠ', 17, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
