INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '파르페가 너무 맛있었어요. 특히 맨 위에 올라가는 딸기 샤베트가 너무 새콤달콤상큼해서 아직도 생각나네요. 라즈베리 화이트 초콜릿 케이크도 먹었는데 이건 그냥 사진용으로 딱 좋은 것같아요. 너무 예쁜데 맛은 조금 과했어요. 진한 버터크림에 진한 화이트 초코, 진한 라즈베리 잼, 진한 오레오 시트까지. 좀 느끼했어요. 분위기도 너무 좋고 가게가 예뻐서 다음에도 파르페 먹으러 와야겠어요.', 13, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '홍대 카페 외관으로 봤을 때보다 훨씬 넓어서(홍대에서 가봤던 카페중에 규모가 큰 카페크에 속하는 듯) 여럿모임하기 좋을 것 같아요👍🏻 공간도 멋지고 빵도 아름답고 맛있네요🥐🥯 노래 선곡도 20년대팝송이라 취저였어요!', 28, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'MEETING');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '비추) 같이 간 친구가 자주 가는 카페인데 파르페가 유명하다고 하더라고요. 파르페가 늘 재료 소진이라 못 먹었다길래 평일 점심에 방문했어요. 가격은 딸기 파르페 13900원, 러블리 초코 8000 비주얼은 훌륭한데 맛이 없어요.. 굳이 사먹으러 올 곳이 아닌 거 같아요. 딸기는 냉동을 쓰는데 맛이 없어서 먹는 내내 셔서 눈이 찌푸려졌어요. 너무 신 맛이더라고요- 요즘은 생딸기나 맛있는 딸기로 판매하는 카페도 많은데...너무 놀랐네요🫠 초코는 아이스크림은 맛있으나 안에가 별로 맛이 없어요ㅠ 체리?같은 게 계속 씹히는데 어울리지도 않고 실망했습니다. 둘 다 거의 안 먹고 버렸어요...🥹 유일하게 마음에 든 것이 화장실ㅋㅋ과 인테리어ㅎ 흠 두 번은 안 갈 거 같군요...', 112, 20, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '파르페를 먹어보았어요~딸기는 이 시간에는 품절이라 없었고, 작은 사이즈의 파르페도 있더라구요~ 커피가격은 다른 음료에 비해 저렴해보였어요~', 114, 20, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '평일 저녁시간에 일하는 남자알바 너무 불친절 귀찮은티 팍팍내면서 손님한테 싸우자는건지...가오는 왤케부리는지 주문들어간거 봐도 서서 폰만 보고있음;;; 귀찮으면 일을 하지말던가 돈내고 기분만 잡쳤네요 교육좀 다시 시키던가 안쓰면 좋겠네요 사장님만 손해일건데ㅠㅠ 정말 좋은 가게인데 사장님 손해보시는게 안타까워서 글씁니다 ㅠㅠ', 3, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '인생 최악의 커피, 분쇄후 다듬지도 않고 템핑, 에스프레소 엉망으로 추출, 스팀완드 딲을때 스팀 크린 안함. 따뜻한 물 한잔 달라고 했더니 제공 안한다고 거절, 다신 방문 할것 같지않음', 129, 20, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '웬만해서 리뷰 작성 안 하는 스타일인데 꼭 해야겠다 싶어 작성합니다 파르페로 유명하다고 하여 방문해 본 카페인데 직원분이신지 사장님이신지 기본적인 인사도 안 하시고 좀 불친절하시더라고요 아니나 다를까 후기 찾아보니 불친절하시다는 말씀들이 참 많구요~ 먹다가 도중에 나왔어요 그만큼 재방문하고 싶지 않은 카페네요', 36, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '나올때 번호 알리는거 개선해야할 것 같아요. 전혀 안들리고 직원들도 하나하나 불러주는거 되게 귀찮아보이더라구요.. 그리고 직원 분들 조금 불친절함을 느꼈습니다ㅠ', 35, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '딸기파르페맛집🍓 홍대 부근 파르페맛집으로 유명한 곳이라 방문해봤어요!!😆신선한 딸기가 올라가서 그런지 파르페가 너무 맛있었고 매일 아침 구워내시는 베이커리가 너무 맛있어 보였던 카페에요ㅠㅠ 식사를 하고 온 상태라 너무 배불렀는데 파르페가 진짜 쑥쑥 들어가더라고요🫠다음에 방문하면 꼭 베이커리도 먹어보고 싶어요!!매장 또한 넓고 쾌적한 상태였고 인터레이더 너무 예뻤어요:) 체험단에 선정되어 업체로부터 이용권을 제공받아 직접 시식해 본 후 작성한 후기글입니다', 49, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '카페가 지하라 밖에서 안보여서 몰랐는데 엄청 크고 쇼파의자여서 앉아있기 편해요! 독특한 논카페인음료 많고 디저트류가 살짝 가격대있지만 맛있어요', 109, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '베이커리류는 아침마다 직접 굽는다하시더라고요!ㅎㅎ 케이크도 커피도 맛있었고 파르페 딸기가 신선해서 오랜만에 먹었는데 굿초이스란 생각 들었습니당!!!!! 다음엔 브런치 먹으러 갈래요ㅎㅎ 같이간 친구도 만족했던 카페라 재방문 의사 100프로에요. 그리고 마지막 사진ㅠ 화장실인데 너무 깨끗해서 맘에 쏙 들어요. 저처럼 화장실 예민하신 분들께 강추ㅎㅎ 소정의 서비스를 지원받아 작성한 리뷰입니다.', 2, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
