INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '진짜...생크림 맛 보고 아무맛도 안나고 식감도 뭉쳐있어서 저게 생크림인지도 몰랐어요. 치즈케이크는 한 두개 조각 봤나....? 하 이걸...그 돈 주고 전 다시는 안 사먹어요...정말....', 35, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '별로에요. 커피 두 잔이랑 크로크무슈, 햄치즈에그베이글을 시켰는데 베이글 안에 있는 햄에서 이상한 냄새가 났어요. 구리구리하고 쉰 냄새가 나서 여쭤보았는데, 그냥 확인만 한다고 하시고 아무런 조치가 없으셨어요. 돈 너무 아깝네요. 위생에 좀 신경 써 주세요.', 24, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '직원분인지 알바분인지 모르겠지만 탈색머리 남자분이 마스크를 안쓰시고 일하시더라고요 마스크 착용해주세요 먹을거 파시는데 좀 그렇더라구요.. 패션후르츠 에이드는 많이 달지도 않고 맛있어요! 초코라떼는 하나도 안섞여있었다고는 하지만 맛있네요 매장은 넓고 따듯해서 좋아요', 37, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '방문해서 좋지 않았던 곳은 아예 리뷰를 남기지 않으려 하는 편인데요. 이 카페에 방문했던 하루는 너무 좋지 않은 기억으로 남아 몇 자 적어보려 합니다. 매장이 지하에 있고 빵 매대는 사진처럼 오픈되어 있습니다. 딸기 크루아상을 집게로 집었더니 옆으로 수많은 날파리들이 후두두둑 떨어지더군요. 요즘 세상에 이런 곳이 있다니.. 카페 위생에 큰 충격을 먹었습니다. 파르페도 사진에는 예쁘게 나올지 모르겠으나 시리얼은 눅눅하고 생크림의 맛 또한 부드럽지 못하며 뭉쳐있었습니다. 두 번 다시 방문하지 않을 생각이며 이 카페를 방문하시려 하는 분들에게 참고가 되었으면 좋겠습니다.', 59, 18, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '매일 아침마다 빵 만드느라 힘들어보이는데 항상 웃으면서 인사해주세요~ 커피는 솔직히 맛 없지만, 직원분이 친절해서 일할 때마다 방문합니다.', 40, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '☆ 달달함 속에 빠져 허우적대고 싶다면 ☆ <폴인스윗> 파르페를 먹어 봅시다. 롤리폴리, 아몬드빼빼로, 달고나, 마카롱, 고구마, 크랜베리, 사과, 초콜릿, 카라멜시럽, 황도 ..... 가 여러분을 넘쳐 흐르는 달달함의 세계로 인도합니다. 파르페가 담긴 컵으로 서로 건배를 한 후, 위에 있는 아이스크림과 과자부터 시작해서 컵을 싹싹 비워 나가며 "스윗함"을 만끽하는 순간이 정말 꿈만 같았습니다만 5분 후 파르페 컵이 바닥을 드러내고 말았습니다. 컵 안에는 파르페 대신 아쉬움과 여운이 남았겠지요. - 매장이 반지하에 있고 작은 전시회관 같은 분위기가 납니다. 파르페 말고도 고를 수 있는 음료랑 빵이 꽤 되기 때문에 먹고 가기 좋습니다. 좌석도 편합니다.', 19, 5, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '벌써 4번째 오는 곳이에요 진심 크루아상이랑 패션후르츠 에이드가 존맛이에요 올 때마다 먹는 중인데 오늘 아이라 생카 하더라구요 ㅎㅎ ㅎ 번창하세요', 48, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '스윗롱파르페? 먹었는데 사과, 고구마, 시리얼 들어있어요 중간에 초코시럽때문에 밑에 망고랑 사과+초코가 진짜 맛이 이상해요! 맨밑에는 꿀에 시리얼인데 너무 달아요 초코가 파르페를 망치는 것 같습니다 그리고 진동벨이 비싸도 진동벨 쓰는게 나을 것 같아요 직원분들은 번호 맞게 안오는 손님때문에 고생, 손님은 번호 신경쓰느라 대화에 집중 못해서 고생인 것 같습니다..', 34, 2, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '라떼 커피가 2샷이라고 나와있는데도 불구하고 커피향우유네요 ㅠㅠ 우유들어가있는건 다 흐려요. 커피도 흐리고 맛없고 차도 밍밍.전반적인 컨셉이 밍밍한맛인가봐요', 0, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '카페 분위기는 좋지만 서비스가 엉망이라 씁니다. 저 말고도 이미 혹평이 많네요. 화장실은 두 칸 다 변기가 막혀서 아예 사용 불가능하고, 메뉴 보고 주문 했는데도 종업원이 그 메뉴가 있는지도 몰라 다른 메뉴로 다시 주문했네요. 두 명이 같이 카운터에서 주문 했는데도, 음료는 엄청 오래 걸려서 하나만 나왔지만 오히려 다행이었어요. 이렇게 맛없고 비싼 메뉴를 두개 샀다면 정말 짜증났을 거에요. 음료는 다 남겼어요.', 43, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '☆ 분위기/맛 최고 ☆ 빈티지풍의 갤러리 같은 인테리어의 카페입니다. 등받이가 기울여진 푹신푹신한 좌석에 앉아서 콜드브루 한 잔 들이키니까 정말 천국에 온 것 같은 느낌이 납니다. 천국에서 구름으로 만든 소파 위에 드러눕는 기분은 이런 기분이겠지요. 카페 내부에 중간중간 눈요기거리가 꽤 있습니다. 늦은 시간대에 와서 파르페는 못 먹고 가서 아쉽습니다. 다음에 방문할 때는 파르페를 먹고야 말겠습니다.', 17, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '주말 바쁜 시간에 직원들에게 친절함 절대 바라지 않습니다. 앉을 자리가 난방기 바로 아래라서 강도좀 약하게 해달라고 얘기하려고 말 꺼내는 순간 남자직원이 말 끊고 눈 번뜩이며 ”에어컨 켜 드릴게요“ 라는 말 듣는순간 제가 뭐 잘못했나 싶었습니다. 친절 서비스 안 바랍니다.  직원 교육 똑바로 하셨으면 좋겠네요.', 32, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '불친절 알바화난듯 키오스크인줄모르고불렀는데 무응답 무서울정도 아인슈페너 맛도없음 내고향 부산전포단길이 훨 맛남 슬픔ㅠㅠ애들은 파르페 하나시켜줬는데 조금 먹다안먹음 근데 음악은 좋음ㅠ', 16, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '알바 일하기 진짜싫은듯 파르페시켰는데 20분걸리니까 작은거시키라고하네 인상너무쓰면서 얘기하는데 간신히참았어요 같이간사람 아니였으면..휴 먹고가는데 플라스틱컵에주던데..', 43, 2, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '애플석류 에이드 진짜 별로고 최악. 자몽 히비스커스 티에이드는 이도더도 아닌 물맛 바닐라라떼는 그나마 평타침 양이 너무 많음 양은 많지만 커피빼곤 다 별로😵‍💫', 76, 14, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '커피랑 케익 3종류 먹었는데 진짜 심각,,특히 티라미스는 맛없기 쉽지않은데 여긴 그걸해냄 일행 모두가 한입먹고 포크내려놓음 ㅠ 커피조차.. 리뷰보니까 파르페는 맛있다던데 다른메뉴도 신경좀 쓰셔야할듯🫠', 49, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '반 지하로 된 구조는 특이한 곳. 특별한 메뉴로 상하목장 아이스크림으로 만든 파르페가 있었지만 품절로 아쉽지만 걍.. 여타 음료로 대체. 친절이나 여타 서비스 면에서는 그닥 권하고 싶지 않은 곳.', 110, 22, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '딸기 하나만 시켰는데 초코도 같이 주더라구요. 그래서 저희 거 맞냐고 물었는데도 맞으니 가져가라고 했습니다. 그래서 가져가 안 먹고 자리에 놔뒀더니 남자 직원이 와서는 “딸기만 시키셨죠? 그런데 왜 초코도 가져가셨어요?”이러면서 잘잘못부터 따지더군요? 마치 저희가 훔쳐간 것처럼요. 그래놓고 테이블로 가져갔으니 결제를 하라는 겁니다. 뭐 저희가 가져간 건 맞으니 결제를 마쳤습니다. 이번 사태야 주문 확인도 안 하고 가져가라고 한 직원이나 가져온 저희나 둘 다 잘못이있다고 보아 저희 쪽에서 먼저 사과를 건넸습니다. 그런데 직원은 자기 잘못은 없다는 식으로 기분 나쁘다며 대꾸도 않고 카드만 툭 주고 돌아섰습니다. 아무리 바쁘더라도 이건 아니죠. 제품이 맛있으면 뭐합니까, 직원 상태가 엉망인데. 다신 안 옵니다.', 70, 13, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '빈티지 느낌의 인테리어에 문화를 접목한 느낌이라 쉬어가면서 커피한잔하기 딱 좋은 것 같아요. 매장도 넓고 청결해서 기분좋게 잘 이용했어요.', 44, 3, 'GOOD', SYSTIMESTAMP);
