INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '파르페 먹으러 갔는데 아이스크림 마감이라 아쉬웠는데 리뷰 보니까 잘한 것 같기도~진심 불친절해서 짜증났어요 주문도 안 받고 계속 전화하고 안내도 없고 에이드랑 커피만 된다고 뻥치고 키오스크에서 주문했는데 주문서 나온 거 보고도 계속 딴짓하자가 겁나 늦게 나옴 음료는 그럭저럭 양 적당했음', 17, 10, 'BAD', SYSTIMESTAMP);
