INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '파르페에 왠 고구마... 상큼한 과일은 어디갔누? 초코아이스크림인지 알았는데 초코 시럽이넹 파르페 맛없네용ㅡㅡ 매장시설은 쇼파가 오래되서 가죽이 벗겨져있고 데이블도 깨끗하지 않아요.불친절합니다.', 9, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '솔직히 이렇게 맛 없는 음료가 이 가격이라는게 화가 났네요. 다 마시지 않고 나왔구요, 파르페 너무 먹고 싶어한 딸이이가 실망 많이 하고 왔네요.', 45, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '직원분이 카운터에 서있으니까 카드 결제면 키오스크로 가라고 하셨는데 키오스크 가니까 디저트가 안나와있어서 다시 카운터로 가서 결제하려는데 오셔서 다른 직원분이 또 카드결제냐고 물어보셔서 디저트 시킨다고 말하니까 아 ~ 이러시네요 진짜 기분 안좋고 불친절해요,, 불 친 절', 28, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '키오스크에 쇼케이스 메뉴가 없길래 옆에 안내문에 카드&현금 결제, 쇼케이스 메뉴는 카운터에서도 주문 가능하다해서 카운터로 갔더니 직원이 카드결제냐고 기계로 하시라고 남자친구랑 이부분에서 기분이 상했는데 일단 쇼케이스 메뉴 주문도 있다고 말하고 주문 후 결제. 커틀러리 청결도가 사진에 잘 보이는지 모르겠지만 나이프나 포크 다 별로입니다. 세척 후 따로 확인이나 닦지는 않는거 같아요. 물자국이 다 있어요. 바꾸려고 카운터 갔는데 아까 그직원이 가져가서는 보는 앞에서 막 확인해보고 아무 말도 없이 새로 바꿔주기만 하네요. 평점 좋아서 방문했는데 재방문 의사는 절대 없네요 이제.', 26, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '홍대갈때마다 지나만 갔었는데 드디어 오늘 직접 가봤네요. 밖에서 볼때는 작아보이는 지하였는데 왠걸 들어가보면 꽤 넓은 매장에 놀랐어요. 디저트들도 맛있고', 23, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '딸기 파르페 먹으러 왔다가 매진되서 대신 시킨 그린티 파르페는 개인적으로 별로.. 안에 들어있는게 오레오가 아니라 흑임자 같음.... 속이 너무 느글거림... 흑임자와.. 곡류? 미숫가루? 같은 맛이 나는 층도 있었음... 뭘까... 대체...', 5, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '12시50분쯤 있으셨던 알바분 정말 너무 불친절하세요 말투가 충전기 어디있는지 여쭈어봤는데 정말 너무 불친절하게 대답을 하셔서 다시 여쭈어보기도 좀 그랬어요 그리고 테이블도 너무 더러웠구 빵 맛도 그 돈 주고 사먹을 맛은 정말 너무 아닌듯해요', 72, 12, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '음료가 이미지와 너무달라요 솔직히 맛도 없습니다 그리고 파르페광고를 매장밖부터 잔뜩해놔서 기대하고 들어갔는데 안하네요? 그럼 광고를 안하는게 맞지않나요. 케익도 가격에 비해 걍 그래요. 매장은 예쁘고 그림그릴수 있게 해놓은건 좋습니다. 매장인테리어말곤 응대도 그렇고 좋은기억이 없네요', 10, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '친구가 전부터 가보고 싶었다고 해서 들렀는데 이날 공휴일이라 그런지 사람이 엄청 많아서 음료 나오기까지 50분 정도 걸림. 심지어 파르페 주문해서 그런가 우리보다 나중에 주문한 사람들 음료가 먼저 나갔는데 카페 편의를 위한 거라 해도 좀 어이없었음.. 한 분은 포스, 두 분은 음료 담당이었는데 매장이 큰데도 공휴일에 직원 세 명이라니 당연히 딜레이 될 수밖에. 그럼에도 착실하게 기다리고 드디어 주문한 파르페가 나옴. 비쥬얼은 밖에 광고하던 그 휘황찬란한 모습이었음. 근데 가격 대비 별거 없음.. 11900원짜리 생딸기파르페는 딸기, 생크림, 시리얼을 번갈아 쌓은 게 다임 거기에 치즈 몇톨 숨어있는 거. 차라리 7500따리 러블리 스트로베리가 나음. 구성으로 보나 가격으로 보나. 딸기도 밍밍함.', 19, 1, 'BAD', SYSTIMESTAMP);
