INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '매장이 넓어서 좋고 콘센트도 곳곳에 있어서 좋아요. 근데 사장님이랑 직원이 회의같은걸 하느라 아메리카노 시켰는데 되게 오래 걸렸어요.', 23, 1, 'BAD', SYSTIMESTAMP);
