INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '사악한 가격의 파르페지만 기분내며 먹기 좋은것같아요 뱅쇼는 오래걸리긴했지만...주문하고20분걸렸어요 너무 맛있어서 마음이 녹았어요 여러 뱅쇼먹어봣지만 여기가 제일 맛있었어요 지하층임에도 밝은분위기였고 곳곳에 그림과 책 액자, 그리고 좌석이 정말 많았어요 다음에 갈일이있다면 출출할때 방문해 베이커리도 먹어보고싶네요! 화장실이 뭔가 특이하면서 멋졌엉ㅅ', 15, 5, 'GOOD', SYSTIMESTAMP);
