INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '아이스크림과 토핑들은 맛있었지만 그 아래는 별로 먹고싶은 맛은 아니었어요.. 안에 커피얼음 같은 것도 있는데 너어어무 써요 ㅠㅠ', 8, 8, 'BAD', SYSTIMESTAMP);
