INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '와 ㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋ 아무리 이벤트매장이라고는 하지만 너무한 거 아닌가요? 아아 한 잔 받는데 45분 걸렸어요 ㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋ 나머지 알바분들은 다른 메뉴 만드시고 카페 한 분이 하시는데 혼자 유니폼 안 입으신거보니 사장님이거나 매니저시겠죠 머리도 안 묶으신건 둘째치고 머리 만진 손으로 영수증 뽑고 커피 템퍼 누르는 부분 털고 진짜 별로에요 다신 가고 싶지 않아요', 19, 0, 'BAD', SYSTIMESTAMP);
