INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '아이스크림은 맛있었는데 직원분들이 너무 느리시고 나오는데는 20분넘게 걸린 것 같고 주문은 받으실 노력도 안 하시고 주문은 계속 쌓여가고있는데 느릿느릿 전화하시면서 숟가락 준비하시고 ㅜ 그래도 카페는 이뻤고 아이스크림도 맛있었습니다', 39, 0, 'BAD', SYSTIMESTAMP);
