INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '아이스아메리카노 40분째 안나오고있어요 손님이 많은것도아니고 손이 그냥 너무 진짜 느려요.. 커피를 내릴생각이없어요 손님 받겟다는건지말겠다는건지', 60, 16, 'BAD', SYSTIMESTAMP);
