INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '뱅쇼 주문했는데 나오는데까지 30분 걸렸어요. 카페에서 음료 이렇게까지 늦게 나온적은 처음이네요. 테이블이 적은 안쪽에 앉았는데 너무 추웠어요. 재방문은 안할 것 같아요.', 36, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'TERRACE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '러블린지아닌지 모르겠는 초코와 그린티 시켰습니다. 받는데 총 1시간 넘어갈때쯤 사장님께 문의했고 사장님께서는 주문이 밀려있다는걸 보여주시면서 15분 더 기다리라고 하시던데...그 느리시고 제때 나가게 못하실거면 주문 자체를 받지마세요. 그리고 대기 번호좀 체계적으로 전산해주시겠어요? 순서대로나가는건지 빨리나가는것부터 나가는건지 헷갈릴정도로 왔다갔다하고.. 애초에 1시간 넘게 걸린다고 주문시에 말씀해주시던가요. 1시간 이상 기다린 사람으로서 제 1시간을 쏟을만큼의 가치 모르겠고요 그 시간이 조금이라도 아까워서 취소도못하겠고 뭐 어쩌란건지..', 47, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '크루와상은 진짜 맛있고 파르페도 아이스크림이아니라 요거트랑 이런것들이 있어서 다양한 식감 즐길 수 있어서 좋아요:) 커피는 탄맛이 많이 나니까 그런맛 싫어하시는 분들은 유의하세욤', 35, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '직원분 참 불친절하네요! 직원분인지 사장님인지는 모르겠지만요..... 그렇게 일하기 싫으면 왜 나와서 일하고 있나요? 매장안은 음악소리랑 사람들 목소리 때문에 카운터에서 거리가 멀면 직원 목소리 안려요! 진동벨도 없고!! 음료 나왔는데 우리가 못 들은데 기분 나쁜건지 음료 나왔다고 소리 지르고 가지러 갔더니 팩 돌아서고! 그렇게 기분 나쁜티 팍팍 내더라구요!! 처음 들어왔을때부터 주문할때도 당연히 나갈때도 사람들한테 어떠한 인사없고 뭘 물어봐도 퉁명스럽고... 다시는 안갑니다. 분위기가 어떻든 맛이 어떻든 기분 안좋다 나쁘다 광고하듯 있는 직원이 있는 곳에 돈 쓰고 싶지 않네요', 43, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '다른곳보다 커피원두가 맛있거나 커피가격이 싸거나 하진않지만 분위기 때문에 홍대 놀러오는사람들한텐 괜찮을꺼같아요, 다만 홍대 직장인 같은 바쁜 사람에겐 비추 하고싶은곳이네요. 아쉬운것들 얘기해도 개선은 안될꺼같아서 말하기 싫구요, 1점이 아닌 2점은 일하시는분들 몇분 빼고 친절하셔서 아쉬운마음이나마 2점으로 찍었습니다.', 30, 9, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '인테리어가 이쁘고 맛있고 넓어서 좋아요. 근데 샤랄라한 인테리어인데 벽이 너무.. 벽지 뜯은 듯한 벽이라 아쉬웠어요. 디저트는 안 먹고 음료만 먹었는데 맛있었어요.', 34, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '매장에 손님 많을때 주문한 것도 아니였는데 크로크무슈와 딸기 밀크티 두개 받기까지 40분 넘게 걸렸네요. 같이 온 친구는 한시간 걸려서 받았고요. 식당에서도 이정도 걸려서 나오지 않는데 카페에서 이렇게 오래기다린적 첨이라 당황스럽네요. 오래걸린것도 그렇지만 기본적인 손님응대 서비스가 안되어있는게 제일 기분 상했어요. 늦게나와서 죄송하다는 말씀 한번 없으시고 뭐가 문제인지 인식하지 못하시는 것 같아 오히려 저희가 이상하게 민감한건가 생각까지 들더라구요. 음료는 맛있었지만 다시 오고싶지도 추천하고 싶지도 않네요.', 29, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '화장실이 포토존인거같아요 화장실진짜 예뻐여 딸기라떼 맛있구 그림그리면서 시간떼우기도 좋아용! 근데 프라페는 입맛에 안맞는거같아용ㅜㅜ', 70, 11, NULL, SYSTIMESTAMP);
