INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '요기 커피 너무 맛있어요~~ 산미도 딱 적당하고 넘 맛있네요♡♡ 재방문 의사 200프로입니다~~^^ 다음에는 파르페랑 케이크 먹어보려구요 제친구가 여기 단골인데 맛있다고 해서요~~!', 84, 18, 'GOOD', SYSTIMESTAMP);
