INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '아이스크림딸기라떼 맛있어요!! 케이크도 생크림이랑 초코맛이 진하네요 조용한 느낌은 아니고 사람이 많아서 약간 활발한? 분위기였어요~!', 41, 3, NULL, SYSTIMESTAMP);
