INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페그랑주'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '이벤트 때문에 다녀왔어요. 주문을 무인기로 받아서인지 알바생이 친절한지 안친절한지는 모르겠고... (음료 나왔을 때도 그냥 벨 울리고 픽업대에서 가져갔기 때문에 마주치지도 않았습니다) 음료 맛은 그냥 보통이었어요. 케이크느 빵도 팔던데 비주얼은 맛있어보였지만 가격이 무서워서 못 먹어봤습니다. 전체적으로 넓고... 그냥 무난해요', 75, 12, NULL, SYSTIMESTAMP);
