INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '정말 맛있었어요 특히 수제 푸딩 계란 맛이 진해서 더 좋았어요 푸딩 데코도 너무 귀여워요 메론소다도 처음에 그냥 먹을 때도 맛있지만 아이스크림이 녹으면서 서로 섞이면서 조금씩 맛이 변해가는데 그것도 정말 맛있었어요', 34, 3, 'GOOD', SYSTIMESTAMP);
