INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '아이와 홍대데이트중 가보고싶다해서 와본곳!! 딸기.초코푸딩과 함께 오기 좋은곳 같아요~ 아이스크림올라간음료는 혼자먹기 많은양이지만 하나시키면 싸우기에 두개를..그래도 좋아하니..뭐 ㅋ 예쁘고 달달구리 푸딩이 있어~ 다음에 또 와보려 합니다:)', 26, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '홍대에 아이와 놀러와서 꼭 가고싶은 모코모코 카페에 왔어요:) 자리가 없었지만 대기명단에 이름 올리고 잠깐 주변 소품샵 구경하고 있었더니 바로 연락주셔서 왔습니다:) 입구부터 예쁜 버터옐로우색 외벽과 아기자기하게 꾸며진 실내까지♡ 소다도 커피도 넘 맛있고 푸딩은 넘 예뻐서 먹기 아까울 정도에요. 근데 숟가락을 한번 들기 시작하니 맛있어서 멈출 수가 없었어요♡', 4, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '푸딩 좋아하는 아이와 마을버스 타고 온 모코모코😍 기대한 만큼 맛도 모양도 예술인 홍대 푸딩 카페맛집이네요! 다양한 음료도 있어서 또 오려고요~^^', 1, 3, 'GOOD', SYSTIMESTAMP);
