INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '푸딩이 너무 귀엽고 맛있어요! 매장도 너무 귀여워서 방문하는 재미가 있습니다,,🤍🫧🥹 푸딩 완전 꾸덕하고 맛있어요~! 메론소다가 찐인 것 같으니 꼭 메론소다로 드세요,, 저희는 못 먹었어요,,', 7, 1, 'GOOD', SYSTIMESTAMP);
