INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '푸딩은 말할 필요도 없이 당연히 너무 맛있었고, 밀크티도 직접 만드는거라 그런지 진짜 맛있었어요😍 커피도 탄 맛이 아니라 살짝 산미 있는 깔끔한 맛이라 완전 제 취향이예요~ 한번 다녀오면 계속 생각나는 곳이예요~ 이번에도 완전 잘 먹고 왔어요❤️', 58, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '체리소다는 상큼달달하고 위에 올려진 아이스크림이 부드러워서 함께 먹으니 너무 맛있었어요. 커스터드푸딩도 입안에서 살살 녹으며 고소하고 달달해 만족스러웠습니다! 디저트 두가지 모두 분위기와 잘 어울려 기분 좋게 즐길 수 있었어요😊✨', 75, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '멜론은 익숙한 메로나 맛인데 더 고급진 느낌~ 블루 소다는 멜론보다 더 깔끔해요~ㅎㅎ 부드럽게 달달한 맛을 원하시는 분은 멜론을 깔끔 시원한 맛을 좋아하는 분은 블루 추천~~😆 커스터드 푸딩은 일본에서 먹었던 그 맛입니당!! 너무 달지도 않고 너무 탱탱하지도 않고 딱 부드러운 식감에 고소하면서 향긋한 바닐라 향 진짜 진짜 맛있어요~💕 커스터드가 이정도면 다른 푸딩도 다 맛있을거 같아서 앞으로 도장깨기 해보려고해요~🤩', 41, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '친구들이랑 홍대 놀러 나왓는데 지나가다가 음료가 너무 귀여워서 들어왓어요! 디저트로 시킨 푸딩도 너무 기여워용 근데 비주얼뿐만 아니라 맛도 너무 맛있어서 친구들이랑 오랜만에 즐거운 시간 보내다가 가용!', 44, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '아이랑 지난번 홍대에 왔다가도 사람이 꽉차서 다음에 오자라고 했는데,,,,, 오늘은 다행히 2자리가 있어서 아이둘만 앉아서 푸딩이와 소다를 주문했네요. 사진 찍어도 이쁘고 이 귀요미를 어찌 먹었을지 ㅎㅎ 소다수위에 가득한 아이스크림위에 토핑이들도 넘 정성스럽네요 :) 공간이 조금만 더 여유있어도 좋겠지만, 드디어 푸딩디저트 맛집을 갔다고 만족해하는 아이둘!!', 53, 14, 'GOOD', SYSTIMESTAMP);
