INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '처음 와봤는데 너무 아늑하고 인테리어 전반적인 가게 분위기 모두 너무 좋았어요! 홍대 오면 꼭 또 다시 들릴 것 같아요!! 에겐녀 수치 200프로 상승', 46, 9, 'GOOD', SYSTIMESTAMP);
