INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '홍대에서 우연히 들른 푸딩 카페였는데, 분위기도 좋고 푸딩이 완존 귀여웠어요!! 커스터드랑 초코 푸딩 먹었는데, 쫀쫀하고 막 너무 달지 않아 더 좋았어요. 조용하게 쉬기에도 좋고, 친구랑 수다도 좋은것 같아욤 디저트 좋아하신다면 꼭 한번 가보셨으면 해요!', 71, 15, 'GOOD', SYSTIMESTAMP);
