INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '비주얼이 귀엽고 알록달록하고 생딸기맛이 가득했습니다! 딸기청을 직접 담궈서 만든 거라 인공 딸기맛이 아니라 진짜 생딸기맛이라서 너무 맛있었어요 소다도 상큼달달하고 위에 올라간 아이스크림까지 다 맛있었습니다!', 46, 8, 'GOOD', SYSTIMESTAMP);
