INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '푸딩이   생각하던   일반   푸딩과   다르게   맛있아요 ㅎㅎ  아이와 아이친구와   데이트  왔는데   푸딩이  참  특별하네요 ㅎㅎ 홍대,푸딩,까페중    단연  쵝옥 ~~~~~ ♡♡♡♡', 2, 4, 'GOOD', SYSTIMESTAMP);
