INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '아메리카노는 산미가 느껴지면서 깔끔해서 정말 맛있었어요! 멜론소다도 맛있었답니다.그리고 뭐니 뭐니 해도 푸딩 전문점답게 여기 푸딩이 진짜 최고예요! 초코푸딩이랑 커스터드푸딩 둘 다 먹어봤는데, 하나같이 부드럽고 정말 맛있었어요.', 9, 4, 'GOOD', SYSTIMESTAMP);
