INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '홍대에 오시면 여기 카페 한 번 들려보세용! 푸딩도 맛있고 메론소다도 맛있어용 ㅎㅎ 1500원 빼고 음료수만 마실 수 있으니까 너무 좋았어요!!', 44, 7, 'GOOD', SYSTIMESTAMP);
