INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '키오스크 이용해서 결제가 가능해서 너무 편리했습니다 홍대에 이런 푸딩 맛집이 있다니 재방문 의사 있습니다 꼭 카페에 방문해보세요!', 21, 8, 'GOOD', SYSTIMESTAMP);
