INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '친구 소개로 홍대카페 모코모코에 왔는데 푸딩 너무 맛있고 메론소다 평소에 좋아하는데 정말 신세계였습니다. 여느 메론소다랑은 달랐어요! 아!! 그리고 위에 올라간 아이스크림 진짜 맛납니다..👍', 20, 8, 'GOOD', SYSTIMESTAMP);
