INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '딸기푸딩은 달콤한 맛이 강한 딸기맛이예요 직접 담군 딸기청으로 만드셔서 진짜 꾸덕한 푸딩이예요 커스터드 푸딩 계란 비린내 하나도 없고 고소하고 맛있어요 카라멜시럽도 달콤하고 생크림도 맛있어요 멜론소다 먹어 본 소다중 제일 맛있습니다.', 1, 0, 'GOOD', SYSTIMESTAMP);
