INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '홍대에 가보고 싶었던 카페, 모코모코 드디어 방문해봤어요!! 오타쿠 투어하면서 들리기 참 좋은 카페랍니다💓 내부 좌석이 매우 협소해서 눈치 게임 필수에요!! 푸딩이 너무 귀엽고 맛있어보였는데, 기대를 저버리지 않았답니다..🌹 티들도 너무 맛있어요! 좌석이 있다면 방문 추천드립니다😉💓', 80, 11, 'GOOD', SYSTIMESTAMP);
