INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '가게가 너무 귀염뽀작 한거 아닌가효 딸기푸딩 완전 생딸기맛이 나더라고요 딸기 케이크 같기도하고 넌무 맛있었어요 디자인만 귀운거 아닐까 생각했는데 ~ㅋㅋ 커스터드 푸딩도 일본 킷사텐에서 먹었던 맛이랑 똑같음!! 여기 꼭 방문해보시길', 63, 13, 'GOOD', SYSTIMESTAMP);
