INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '홍대에 놀러왔다가 방문했어용 사장님이 친절하시고 ㅎㅎ 푸딩,음료가 다 맛있어요 가게가 아기자기합니당!! 카페 갈일 있으면 또 들릴게용', 15, 8, 'GOOD', SYSTIMESTAMP);
