INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '아이 친구네랑 아이들이랑 같이 방문했어요 😍 음료 비주얼👍 사진각😍 블루소다는 아이스크림을 올렸고 체라소다는 빼서 주문했었는데 아이스크림이 없으면 깔끔한 맛 아이스크림이 있으면 좀 더 풍성한 맛이라 아이스크림 올리는거 추천드려용 푸딩은 다 맛있었는데 저희 아이들은 초코러버들이라 초코가 제일이었대요 ㅋㅋ 잘먹고 왔어요 ㅎㅎ', 69, 16, 'GOOD', SYSTIMESTAMP);
