INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '멜론소다 블루소다 커스터드푸딩이 추천 조합이라서 시켜봤는데 영롱한 비주얼✨에 사진찍기를 멈출 수 없었네요,,,ㅎㅎ 소다는 엄청 달까봐 걱정했는게 과하게 달지 않고 소다랑 아이스크림리 잘 어울렸어용~~ 푸딩은 넘 귀여워서 먹기 아까웠는데 눈 딱 감고 먹어보니 그냥 녹더라구요,,, 비쥬얼 맛 다 갖춘 맛집 인정합니댱!!', 98, 22, 'GOOD', SYSTIMESTAMP);
