INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '🍈메론소다와 커스타드 푸딩😽💕 ☝️메론소다는 아이스크림까지 올라가면 차갑게 유지되기 때문에 얼음은 안넣는게 좋을것 같아용! 나중에 가면 얼음이 녹아서 맹맹해지는게 쬐끔 아쉬웠습니다... 그래도 너무 마쉿었어요🤤🩷 ✌️제가 커스타드 푸딩을 참 조아하는데 개인적으로 위에 올라간 생크림이 그렇게 푸딩이랑 잘 어울리는것 같지는 않았어요 (비주얼이 귀여운것과는 별개로 아쉽)', 42, 8, NULL, SYSTIMESTAMP);
