INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '푸딩 좋아하는 친구랑 오랜만에 왔어요! 밀크티도 딸기푸딩도 직접 만든 딸기청으로 만든다고 하셨는데 그래서 그런지 딸기맛이 정말 산뜻하고 맛있었어요!! 밀크티랑 딸기 조합은 처음 봐서 먹어봤는데 맛있더라구요!! 체리소다는 시큼한 맛은 아니고 진한 체리 맛이에요 체리과육도 들어있어요! 귀엽기도하고 맛까지 너무 맛있는 곳이에요!!', 117, 21, 'GOOD', SYSTIMESTAMP);
