INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '처음와보는 곳이라 일단 예뻐서 시켰는데 소다 정말 맛있었어요♡매장에서 소다만 드시는 분들도 계셨는데 왜인지 알 것 같음~ㅋㅋ근데 푸딩도 진짜 맛있습니다~진짜 푸딩의 정석 같은 맛이라고나 할까용ㅋㅋ부드럽고 고소하고 달콤해요~특히 계란냄새 제가 예민한데 안나서 좋았어요~매장도 시원하고 넘 잘 쉬고 수다떨고 갑니다', 44, 9, 'GOOD', SYSTIMESTAMP);
