INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '홍대 지나다니다가 항상 사람이 많아서 못왔다가 드디어 왔어요!! 평소에 소다 좋아해서 체리소다. 메론소다 주문했어요. 푸딩 맛집이라고 하던데 다음에는 푸딩도 먹고싶어요!! 소다 맛집 카페입니다!!', 82, 11, 'GOOD', SYSTIMESTAMP);
