INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '제 생일 기념으로 놀러왓어요 ㅎㅎ 전부터 매장에서 먹고싶었는데 드디어 좌석에서 먹네요~ 제가 젤라틴 푸딩 식감을 싫어하는데 여기 푸딩은 젤라틴 들어갔어도 전혀 그 식감 안나서 너무 좋았어용!!', 85, 16, 'GOOD', SYSTIMESTAMP);
