INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '홍대 지나가다 많이 본 카페인데 이번 소다가 먹고싶어서 처음으로 가봤어요!! 블루소다랑 체리소다 두개 사서 먹는데 같이 간 친구가 원도어라구 사장님이 우유푸딩 서비스로 주셔서 맛있게 먹었습니다! 매장도 아늑하고 분위기가 귀여워서 좋았어요 다음에 꼭 재방문 하고싶습니다!', 34, 7, 'GOOD', SYSTIMESTAMP);
