INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '홍대 올 때마다 커다란 푸딩 간판 보고 꼭 와보고 싶었는데 드디어 와봤네요😋🍮 탱글하고 달콤한 푸딩과 맛있는 커피가 너무너무 마음에 들었어요~ 다음에 친구들이 카페 가자고 하면 무조건 모코모코로 오겠습니다 ㅎㅎ 아 푸딩 너무 맛있어용🤍 시럽이랑 푹 떠서 먹으니까 진짜 너무 달콤하고 맛나용 히힛🤤', 92, 21, 'GOOD', SYSTIMESTAMP);
