INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '멜론소다 완전 최고!! 아는맛이라 더 맛있는거 같아요 >< 메로나 고급버전 같은맛이랄까요! 커스터드푸딩은 넘 부드럽고 계란 비린내 하나도 안나요~고소한맛이 느껴져서 진짜 맛있었습니다 소다 위에는 아이스크림, 푸딩 위에는 생크림이 올라가는데 둘 다 우유맛이 진해서 넘 맛있었어요 또 먹고 싶어요~', 71, 11, 'GOOD', SYSTIMESTAMP);
