INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '홍대에 놀러와서 쉴 카페를 찾다가 푸딩이 맛있다길래 왔어요 안이 너무 아늑하게 꾸며져있어서 대충 찍어도 예쁘게 나오고 음료들도 다 너무 맛있어요 저는 초코푸딩이 부드럽고 고소해서 제일 좋았지만 다른 간식들도 너무 맛있으니까 꼭 다 먹어보세요!!', 22, 3, 'GOOD', SYSTIMESTAMP);
