INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '밀크티 수제라고하는데 진짜 진하고 맛있네요🙄 아이스로 시켜도 귀여운 머그 잔에 담아주셨어요 ㅎ 얼음 없이도 시원했답니다. 커스터드푸딩 입에서 살살 녹습니다ㅋㅋㅋ 밀크티가 약간 쌉쌀한 맛이 있고 커스터드도 과하게 단 맛이 아니라 같이 먹어도 맛있었네요😚', 462, 69, 'GOOD', SYSTIMESTAMP);
