INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '여기 푸딩 정말 코퀄… 세상 너무 맛났어요💗 커스터드는 제가 일본 카페에서 먹은 맛이랑 똑같았고!! 초코는 완전 진하고 꾸덕한 초코라서… 딱 내스타일🥰 역시 푸딩 전문점이라 그런지 뭔가 다르더라고요.. 엄청 맛있었어요 정말 :) 🫶', 89, 12, 'GOOD', SYSTIMESTAMP);
