INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '홍대에서 푸딩이 있는 카페를 찾아서 검색해보니 너무나도 귀여운 푸딩이 있더라고요! 자리도 다양하게 있고, 빈티지하면서 발랄한 느낌의 인테리어가 너무 좋았습니다! 밖에서부터 귀여운 느낌이 팡팡 느껴져서 찾기도 좋았습니다🥰❣️', 31, 5, 'GOOD', SYSTIMESTAMP);
