INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '대충 찍어도 너무 잘 나올 정도로 인테리어가 예뻤어요! 친구와 함께 방문했는데 매장도 조용해서 대화 나누기도 참 좋았습니당 푸딩은 진짜 부드럽고, 느끼하지 않아서 무한히 먹을 수 있을 정도의 맛이었어요☺️ 홍대 놀러오신다면 푸딩 먹으러 모코모코 카페 와봐도 좋을 것 같아요!!', 17, 1, 'GOOD', SYSTIMESTAMP);
