INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '✨ 홍대에서 찾은 디저트 천국 ✨ 홍대 거리를 걷다가 우연히 들어간 이 카페, 진짜 보물 찾은 기분이에요. 분위기는 감성 그 자체인데, 결정적으로 푸딩이 정말 미쳤어요. 부드럽고 쫀쫀한 식감에 달지 않으면서도 깊은 맛이 느껴져서 단숨에 다 먹어버렸네요. 커피랑도 찰떡이라 한참을 앉아서 여유롭게 즐길 수 있었어요. 홍대에서 이런 퀄리티의 디저트를 만나게 될 줄이야… 또 가고 싶은 카페 1순위로 저장 완료!', 85, 12, 'GOOD', SYSTIMESTAMP);
