INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '중학생 딸랑구가 홍대에 맛난 푸딩이 있다해서 왔는데~ 넘넘 맛있어요 특히 말차가 ^^ 포장해서 대전갑니다ㅎㅎㅎㅎ 커피기계가 고장나서 음료 하나가 하나인데 다음에는 꼭 맛보고 싶네요~~~~~', 130, 21, NULL, SYSTIMESTAMP);
