INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '예전에 길가다가 발견하고 꼭 가보고 싶다고 생각했는데 홍대에서 가장 맛있고 예쁜 카페같아요… 🥰🥰 특히 초코푸딩이 정말 맛있었어요 다음에 또 오고싶습니다', 106, 24, 'GOOD', SYSTIMESTAMP);
