INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '안녕하세용~ 이번에 굠쏘중 쏘가 푸딩이 너무 먹고싶어 찾아보다 모코모코를 알았답니다 ( 완전 반대편에서 열심히 걸어왔어요ㅜ) 메뉴 밀크티,체리모카라떼,커스터드푸딩2개 밀크티(HOT) : 엄청 달단하다보단 딱 적당히 단맛 체리모카라떼(ICE) : 완전 처음 먹어보는 커피에 체리가 씹히는맛? 커스터드푸딩 :  입에서 녹으면서 달달한 푸딩이 너무 맛있고 위에 체리까지 먹으면 하나순삭되요 굠❤️쏘의팁✅️ ✔️네이버리뷰시 캡슐뽑기 ✔️안에가 아담해서 최대 4명정도가 딱 좋아요 ✔️사진 찍기 좋은곳은 창가쪽이 이뻤어요', 33, 8, 'GOOD', SYSTIMESTAMP);
