INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '지난 번에 방문하고 좋았어서 또 들렸어요💕 매장 내부가 무척이나 귀엽고 아기자기해서 귀여운 사진 찍기 좋아요 지난번엔 커스터드 푸딩 먹었는데 이번에는 말차 푸딩 시켰는데 말차 푸딩 진짜 맛있네요 달콤 쌉싸름🥺🩷🩷 여태껏 먹은 말차푸딩 중에 제일 맛있었어요🥹🩷🩷 재방문 의사 있습니다!‘', 18, 7, 'GOOD', SYSTIMESTAMP);
