INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '지나가다 홀린듯이 들어왔어요. 홍대에 이렇게 귀엽고 맛있는 푸딩카페가 있을 줄이야! 매장도 귀엽고 판매하는 메뉴도 넘 귀엽고 맛나요.💕', 67, 11, 'GOOD', SYSTIMESTAMP);
