INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '홍대를 걸어다니다가 카페에 들어가고 싶어서 무작정 찾던 중 인테리어가 예뻐서 우연하게 들어왔는데 푸딩도 너무 귀엽고 맛있어서 좋은 추억을 간직할 수 있게 되었습니다!!💖', 33, 6, 'GOOD', SYSTIMESTAMP);
