INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '딸기 푸딩은 직접 담군 딸기청으로 만드신다고하셨는데 그래서 그런지 정말 생딸기 맛이 강하고 너무 맛있었습니당~~진짜 존맛!! 블루 소다는 위에 올라간 아이스크림이 진짜 대박!! 이때까지 먹은 블루소다중에 여기가 최고입니당!!', 3, 2, 'GOOD', SYSTIMESTAMP);
