INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '분위기가 아기자기하고 샬랄라헤요 푸딩은 주문하자마자 바로 생크림 코디 하시느라 좀 오래 걸리는데 그민큼 세심하고 예쁘게 잘 만들어주세요 매장 안에 소품들이 파스텔톤에 아지가지하고 예쁘고 푸딩도 맛있습니다', 40, 7, 'GOOD', SYSTIMESTAMP);
