INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '모코모코에 또 왔어요😆 애플시나몬티는 시나몬향이 진하게 퍼지면서 달달한맛이라서 맛있어요!!! 블루소다는 익숙한 소다맛인데 위에 올라간 아이스크림이 맛있어서 섞어먹어도 맛있었어요!!!ㅎㅎ 딸기푸딩은 생딸기 그자체입니다,, 과하게 달지않은 기분좋은 달달함ㅎㅎ 주문한메뉴가 다 맛있었어서 다음엔 다른메뉴도 먹어보고싶어요❤', 32, 2, 'GOOD', SYSTIMESTAMP);
