INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '밀크티를 수제로 만드신다고 하더니 정말 진하고 맛있네요~~ 달달한 딸기청으로 만든 딸기우유에 루이보스티의 부드러운 맛이 잘 어울려요 ㅎㅎ 커스터드푸딩이 대표메뉴인데 일본에서 먹은 푸딩이랑 정말 비슷! 제 입맛엔 더 맛있는 것 같은 ㅎㅎ', 3, 3, NULL, SYSTIMESTAMP);
