INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '초코푸딩이랑 커스터드푸딩, 딸기푸딩을 주문했어요 푸딩마다 재료 맛이 잘 살아있고 식감도 각각 재료에 잘 어울리는 식감이라 공들여 만든 디저트란게 느껴졌어요 입에 넣으면 0.1초만에 없어지는 이 달달함.. ㅎㅎ 매장도 아기자기하고 비지엠도 귀엽고 완전 힐링공간이에요 !!', 45, 7, 'GOOD', SYSTIMESTAMP);
