INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '아이와 홍대 나들이!! 커스터드 푸딩이 너무 맛있고 귀여워요^^ 밀크티도 진하고 맛있어요! 소다에 올려진 아이스크림도 너무 맛있어요! 홍대 나들이시 모코모코 카페 강추👍', 24, 9, 'GOOD', SYSTIMESTAMP);
