INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '친구랑 홍대 나들이 와서 카페 들렀어요! 매장 분위기도 너무 귀엽고 아기자기해서 참 좋았던...🥺🥺 서비스로 받은 푸딩은 말뭐 가챠도 대성공해서 너무 좋은 추억이었어요!! 나중에 또 들릴거에요😆💕', 55, 11, 'GOOD', SYSTIMESTAMP);
