INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '저번에 홍대 왔을 때도 지나가다 보고 너무 먹고 싶었는데, 이번에는 시간이 돼서 한 번 와봤어요! 친구랑 둘이 와서 초코푸딩이랑 우유푸딩 시키고 선물용으로 커스터드 푸딩도 포장해갔어요! 포장해가면 조그만 병에 담긴 푸딩을 주시더라구요? 너무 귀엽고 맛도 좋아요 진짜 지금까지 먹어본 푸딩 탑3 안에 드는 맛..🥹 소다는 안 먹어봤는데 다음에 방문하면 꼭 먹어보려구요~', 19, 5, 'GOOD', SYSTIMESTAMP);
