INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '홍대에 푸딩맛집이 있다고해서 방문했어요! 푸딩이 너무너무 귀여운데 예쁜 모양을 뛰어넘는 맛이었네요! 소다도 푸딩도 너무 맛있었어요 인테리어 소품부터 비지엠까지 매장에 있는 모든 것 하나하나 신경쓰신게 느껴지는 정성 가득한 공간이였어요', 76, 11, 'GOOD', SYSTIMESTAMP);
