INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '홍대 걷다가 귀여운 카페 찾아서 들어갔는데 너무 좋았어요🫰🏻🫰🏻 메론소다 맛있고 푸딩이 너무 귀엽습니다 .. ♥ 예전에 방문했을 때 커스터트 푸딩 먹었던 것 같은데 커스터드푸딩도 맛있었구 이번에 초코푸딩도 넘 맛있었어요 최고예요🫶', 473, 95, 'GOOD', SYSTIMESTAMP);
