INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '🌀🌀🌀너무 귀여운 홍대 카페🌀🌀🌀 카페 인테리어도 너무 아기자기하고 이쁘고 푸딩 비주얼이 🩷진짜 긔여워요🩷심지어 맛있음 사진찍기도 좋고 데이트하기도 너무 좋아요!!!! +직원분들 너무 친절하시구 카페 분위기도 좋아용!!!!!', 265, 92, 'GOOD', SYSTIMESTAMP);
