INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '홍대에 있는 일본감성카페 다녀왔어용 멜론소다💚🍈랑 블루소다💙🥂 시킬 때 아이스크림을 얹어주시는 줄 알았는데 따로 주시더라고요!! 아이스크림이 음료에 섞이는게 싫었는데 사장님 센스 너무 좋앗어용🫶🏻 그리고 커스타드 푸딩도 시켰는데 타 지점과 다르게 푸딩이 단단해서 좋앗어요 타 지점은 흐물흐물해서 먹기 힘들고 흘리기만 했는데 여기는 텍스쳐가 떠먹기 좋고 시럽도 메이플맛이라 넘 조앗음.. 체리도 아낌없이 꽂아주셔요🍒 적립카드(?) 새로 만들구 도장을 3개 찍어주시는데 5개 찍어주셔서 너무.. 행복끄', 2, 8, 'GOOD', SYSTIMESTAMP);
