INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '홍대 푸딩을 검색해서 가장 먼저 뜨길래 왔는데 푸딩과 음료가 정말 맛있었습니다!! 매장도 아늑하고 사장님도 친절해서 편하게 있다가 가기 좋은 카페인것 같습니다🍮🍮', 15, 8, 'GOOD', SYSTIMESTAMP);
