INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '귀여운 소품도 아기자기하게 많이 있어서 좋고 푸딩도 맛있는 홍대 카페입니다! 푸딩도 넘 귀여워요 (친구가 준 인형이랑 한 컷!)', 48, 6, 'GOOD', SYSTIMESTAMP);
