INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '말차 푸딩을 시켰는데 너무 귀엽고 맛있어서 이 카페가 홍대에만 있어서 아쉽긴합니다!! 그래도너무너무 맛있고 인테리어도 맘에들어서 홍대에 왔을때 다시 방문하고 싶습니다', 40, 4, 'GOOD', SYSTIMESTAMP);
