INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '체리모카라떼는 초코맛이 강한 달다구리 음료에요. 체리맛도 꽤 강해서 달콤하고 진한 맛 좋아하는 분들 추천해요! 블루소다는 좀 더 산뜻한 달달한 맛이에요 위에 올라간 아이스크림까지 너무너무 맛있었어요. 푸딩은 초코로 시켰는데 쫀득하면서 진한 초코맛이 나요. 발로나 커버춰를 쓰신다고하는데 그래서 그런지 초코맛이 진하면서도 과하게 달지 않은 묵직한 맛이라 정말 맛있었어요.', 18, 2, 'GOOD', SYSTIMESTAMP);
