INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '홍대 갔다가 알게되었는데 커스터드푸딩은 정말 정석그대로의맛이였어요 !! 귀엽게 생겼음에도 맛은 풍미가 깊었어요^^ 전 아메리카노랑 같이 먹었는데 아아도 퀄리티 굿👍👍 꼭 가보세요 여친님들이 좋아하실 듯💕', 78, 17, 'GOOD', SYSTIMESTAMP);
