INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '소문 듣고 친구랑 왔어요~블루소다 아이스크림 빼고 주문하면 6000원인데 추가하면 7500원..깔끔하게 먹고싶어서 빼고 주문했는데 청량한 색감처럼 시원하고 달콤하네요 커스커드푸딩은 너무 묽지도 단단하지도 않은 부드럽고 먹기 좋은 식감이예요 향긋한 바닐라빈향과 달콤한 카라멜시럽까지 너무 맛있어요ㅎㅎ', 93, 21, 'GOOD', SYSTIMESTAMP);
