INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '카페 너무 아기자기하고 귀여워요! 음료랑 푸딩도 너무 귀엽고 다른 데보다 훨씬 맛있어요! 홍대에서 가본 카페 중에 제일 친절한 것 같아요!', 12, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '친구랑 홍대 놀러왔다가 방문했어요! 항상 가던 카페말고 다른 곳 가고 싶어서 알아본 카페입니다. 매장 내부는 크지 않아요 2명이서 오는걸 추천하고 4명까지 방문하는 걸 추천합니다. 작아도 인테리어는 아기자기하니 귀엽습니다♡ 푸딩 너무 귀엽고 너무 맛있어요. 하나하나 수작업으로 발바닥이랑 눈코 그려주셔요. 홍대오면 또 방문 하고싶어요.', 110, 20, 'GOOD', SYSTIMESTAMP);
