INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '인테리어뿐만 아니라 식기까지 다 너무 귀여워요🥰 하나하나 섬세하게 신경 쓰신게 느껴지는 카페에요! 밀크티는 수제라고 해서 기대하면서 시켜봤는데 수제라서 그런지 맛이 진짜 진하고 맛있어요! 홍콩에서 먹었던 밀크티랑 비슷하게 진하고 맛있어서 놀랬어요! 커스터드 푸딩도 식감이랑 맛이 다 조화롭고 너무 맛있어요❤️', 34, 10, 'GOOD', SYSTIMESTAMP);
