INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '홍대 디저트카페를 찾아다니다 빙수가게 가려다가 귀여운 푸딩이 발을 잡아서 그냥 여기 들어왔어요! 딸기가 품절이라 말차먹었는데 과하게 달지 않고 맛있었습니다🐻곰돌이 얼굴이랑 발바닥이 너무 귀여워욯ㅎ', 18, 1, 'GOOD', SYSTIMESTAMP);
