INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '홍대 놀러왔는데 귀여운 푸딩 간판에 끌려서 들어왔어요 너무 귀여운 푸딩과 맛있는 소다 🫧🤍✨ 여름 그자체입니담 ㅎㅎㅎ 귀여운 카페 좋아하신다면 모코모코로~🐻💛', 118, 22, 'GOOD', SYSTIMESTAMP);
