INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '홍대와서 데이트할 카페 찾다가 푸딩 먹으러 왔어요! 운좋게 웨이팅 없이 입장해서 맛있게 먹고 갑니다:) 직원분들도 친절하고 푸딩은 귀엽고 맛있어요 블루소다도 너무 예뻐서 기분좋게 먹었어요❤️', 48, 2, 'GOOD', SYSTIMESTAMP);
