INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '커스터드푸딩 멜론소다 애플시나몬주문 커스터드푸딩 귀엽고 생크림은 우유맛이 진합니다 멜론소다의 아이스크림도 우유맛이 진하고 멜론시럽맛이 좋고 애플시나몬은 많이 달달하니 씁쓸한 차를 생각한다면 다른 차종류로 주문하세요', 29, 5, NULL, SYSTIMESTAMP);
