INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '홍대에 있는 감성 카페에서 푸딩 먹었는데 진짜 최고였어요! 부드럽고 달콤한 커스터드 푸딩, 입에서 사르르 녹아요. 분위기도 좋아서 홍대 데이트나 혼카페로 추천해요 🍮💕', 14, 5, 'GOOD', SYSTIMESTAMP);
