INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '일단 매장이 너무너무 귀엽고 메뉴가 아기자기하니 너무 예쁘게 꾸며주시는데 받으면 기분이 너무 좋아요ㅠ 전 푸딩 시켰는데 풍미좋은 초코맛이라(약간상하목장초코아이스크림맛?) 완전 취향입니다! 좌석이 많지않으니 혼자나 친구랑 둘이 올때 오시면 좋은 공간인거같아요~!', 39, 0, NULL, SYSTIMESTAMP);
