INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '홍대에 친구랑 놀러와서 왔어요 저는 카라멜 푸딩이랑 체리 소다 시키고 친구는 말차 푸딩이랑 얼그레이 라떼 시켰는데 다 맛있어요 카페 인테리어도 귀엽고 곰돌이에 진심이신 것 같아요 그래서 너무 좋음…💕', 11, 2, NULL, SYSTIMESTAMP);
