INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '홍대 푸딩 디저트 카페 맛 집이라고 찾아간 곳이예요~ 딸램이가 친구랑 방문해보고 같이 가보고 싶다고해서 왔는데 효도받는 느낌이네요 ㅎ 다음에 체리소다를 먹어봐야겠어요~', 113, 20, NULL, SYSTIMESTAMP);
