INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '홍대 여기저기를 둘러다니다가 외관만봐도 귀여운 무언가가 많이 있을 것 같은 카페를 발견해서 들어왔어요. 2인이서 같이 커스타드 푸딩이랑 말차푸딩, 블루소다 세가지를 주문했는데 생각보다 빨리 나와서 좋았습니다! 또한 푸딩 위에 곰돌이가 올려져 있어서 좀 더 특별하게 먹은 것 같기도 하네요// 다음번에 온다면 또 가고 싶은 곳이예요🩷', 32, 7, 'GOOD', SYSTIMESTAMP);
