INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '가게 너뮤너뮤귀여워요!!!!!! 아이스크림도 맛있고 위에 올라가있는 스프링클이나 쿠키 너무커여움😻 홍대 오면 다시 와보고 싶어요!', 5, 6, NULL, SYSTIMESTAMP);
