INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '또 모코모코에 왔어요😆 푸딩은 초코 커스터드 말차로 주문했는데,,, 하나하나 다 맛있었어요!!! 과하게 달지않고 딱 기분좋게 달달한맛 , 식감도 부드럽고 초코늣 초코 말차는 말차로 맛의 개성이 뚜렷해서 질리지않았어요ㅎㅎ 커스터드도 진짜 맛있었는데,, 위에 올라간 생크림도 동물성인지 느끼하지않고  맛있어요!! 소다는 체리 멜론으로 주문했는데 아이스크림이랑 섞은 맛도 의외로 괜찮더라구요🤭 단, 깔끔한맛을 좋아하시는분들은 아이스크림을 빼면 6000원이에요!! 다음에도 맛있는달달한충전하러 올까봐요❤', 9, 4, 'GOOD', SYSTIMESTAMP);
