INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '이거 먹으려고 신촌에서 홍대까지 걸어왔어용... ㅎ.ㅎ 푸딩 너무 맛있고 귀엽구 ㅜ.ㅜ... 카페 분위기도 너무 좋아요!! ㅠㅠ 인테리어 진짜 아기자기하고 넘 귀여워요 잘 찾아온 것 같아요', 33, 4, 'GOOD', SYSTIMESTAMP);
