INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '지나가다가 카페 분위기와 디저트가 귀여워서 들아왔는데 들어온게 행운 일 정도로 좋았어요 ! 매장 내 분위기도 귀엽고 포근한 느낌이 들었어요! 푸딩이랑 소다 주문하였는데 생긴거는 물론 맛도 좋아서 다음에 홍대 놀러오면 또 올 예정이에요 😋', 21, 0, 'GOOD', SYSTIMESTAMP);
