INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '홍대에 있는 푸딩카페 보다가 귀엽고 인테리어도 제 스타일이라 방문했어요!! 푸딩이 부드럽고 달콤해요!! 게다가 귀엽게 있어서 너무 좋았어요!! 메론소다도 맛있고 아이스크림도 부드럽고 좋아용~❤️❤️ 매장도 귀여워서 사진 찍기 좋아요!', 12, 1, 'GOOD', SYSTIMESTAMP);
