INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '말차,딸기,커스터드 푸딩 포장했는데 포장은 커여운 푸딩용기에 포장해주시고 가나디모양은 아니어도 안쪽에 생크림도 올라가있어요🤍 저는 말친놈이어서 말차가 젤 맛있었고 커스터드도 존맛이었어용 딸기도 상큼하고  귯〰️  담에는 매장에서도 먹어보고싶어요😚', 33, 1, 'GOOD', SYSTIMESTAMP);
