INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '이색 디저트 카페를 찾다가 우연히 발견한 모코모코! 이름부터 귀여운데요😊 내부도 아늑하고 푸딩은 말해 뭐해요! 사랑스러운 곰돌이 푸딩 귀여운 곰돌이 스푼으로 맛있게 먹고 갑니다:) 특히, 딸기 추천드려요 ㅎㅎㅎ', 6, 2, 'GOOD', SYSTIMESTAMP);
