INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '큰애가 푸딩 먹고 싶다해서 검색해 찾아간 곳이예요. 여기 전부터 지나다니며 보던 곳인데 드디어 방문했어요🍒 딸들과 애들 아빠랑 홍대 나들이 왔다가 들었네요^^ 점심으로 닭갈비 먹고 나서 바로 왔는데 딱 좋네요💕 매운거 먹고 달달한게 들어가니 기분 좋아졌거든요^^ 특히나 큰딸은 본인이 원한 곳 와서 신났네요~ 막둥인 귀엽고 깜찍한 푸딩 사진 찍느라 바빴구요^^ 저도 마찬가지😅❤️ 남편은 아메리카노 시키고, 딸기 밀크티는 처음인데 요것도 맛있더군요^^ 담에 또 들를게요🎶', 8, 6, 'GOOD', SYSTIMESTAMP);
