INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '홍대 놀러왔다가 아이와 지나가다가 너무 예쁜카페를 보고 들어왔어요. 푸딩 제대로 시켜먹은건 처음인데 정말 맛있어요. 엄청 친절하시고요. 아이들과 오면 더 좋은 곳인거 같아요.', 26, 9, 'GOOD', SYSTIMESTAMP);
