INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '넘 예뿌고 아기자기해요 ㅜㅜ!!💕💕💕 홍대 카페 치니까 제일 먼저 뜨길래 방문했는데 넘 만족스러워용😆🎀🎀 푸딩은 커스터드 푸딩이 더 맛있었고 블루소다는 아이스크림 먹느라 힘들어서 담에 오면 아이스크림은 빼고 주문할것같아요💕💕💕 추천합니당💗', 67, 16, 'GOOD', SYSTIMESTAMP);
