INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '동생이랑 홍대에서 방탈출하고 근처를 지나는데 저번에 1시간 웨이팅 뚫고 먹었던 맛있는 푸딩카페라고 하길래 지나가는 길에 운 좋게 카페 입장 했습니다! 금방 자리 찼구요! 말차&우유푸딩에 메론&블루 소다 시켰습니다! 실내가 작아도 쾌적하고 인테리어가 너무 제 마음에 쏙 들었어요ㅠㅠㅠ 푸딩도 쫀쫀하고 귀엽고 소다도 일본여행의 추억을 불러 일으켰습니당🍮', 60, 12, 'GOOD', SYSTIMESTAMP);
