INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '메론소다에서 아이스크림을 빼니 6,000원!!!!시원하고 달달하면서 탄산도 톡톡 터져서 정말 맛있게 잘 마셨어용😊 커스터드 푸딩은 말해 뭐해요~ 입에서 살살 녹는 부드러움에 완전 감탄!!! 매장도 아기자기하게 꾸며져 있어서 눈도 즐겁고 분위기 자체가 기분 좋아지는 공간이었답니당❤️다음엔 다른 푸딩들도 맛보러 올께용 : )', 42, 6, 'GOOD', SYSTIMESTAMP);
