INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '동생이 푸딩 먹고싶어해서 찾아보고 방문했는데, 푸딩도 맛있고 음료도 제대로여서 감동했어요 🥹 주말에 사람 많으니까 꼭 미리 연락하고 방문하시는거 추천이요! 홍대에서 귀여운 푸딩 디저트 카페 찾으시면 강추입니다👍🏻', 20, 6, 'GOOD', SYSTIMESTAMP);
