INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '오늘 my girlfriend의 boyfriend의 birthday 사건으로 ✨️홍대✨️에서 생일카페 돌다가 겨우 밥먹구 진짜 카페 들어왔네요 깜찍한 인테리어에 달콤한 푸딩 어떻게 지나침...', 11, 3, 'GOOD', SYSTIMESTAMP);
