INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '직장 근처라 지나갈때 마다 궁금했는데 드디어 주말에 친구랑 카페 찾다가 발견한 푸딩집! 인테리어부터 메뉴하나하나 너무 귀엽고 전부 제취향이에요 짱맛있음!!! 자주 올 것 같아요 4월에 갑자기 추운날 넘 따뜻하고 귀여운 카페를 찾아서 행복해요🥹🫶🧸🍅 다들 푸딩 드세요🍮 말차푸딩 짱맛있어요 ☘️', 73, 13, 'GOOD', SYSTIMESTAMP);
