INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '너무 예뻐요! 분위기도 예쁘고 음식도 맛있어요^~^ 푸딩 진짜 맛있구요 음료 양도 많앗어요! 인테리어도 완전 짱짱이에오 소품들이 하나같이 너무 귀여웟어요! 완전 힐링', 43, 2, 'GOOD', SYSTIMESTAMP);
