INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '두번째 방문했어요! 아이들이 너무 좋아해서 또 갔답니다ㅎㅎ  초코푸딩은 딸 최애에요 이빨썪을까봐 단거 많이 못먹게하는데 하나도 안단데 달콤하고 맛있어요 인테리어도 너무이뻐서 사진도 잘 나와요', 47, 9, 'GOOD', SYSTIMESTAMP);
