INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '홍대에서 가장 유명한 카페이길래 방문했는데 다행히 예약없이 바로 들어왔어용 푸딩이 유명해서 커스타드 푸딩이랑 초코 푸딩 하나씩 시켰는데 달달하고 꾸덕해서 엄청 맛있었어요!!🍮', 70, 15, 'GOOD', SYSTIMESTAMP);
