INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '수학여행으로 서울 놀러와서 홍대 푸딩 카페 모코모코 우연히 찾아서 왔는데 귀여울뿐만 아니라 달달하고 촉촉해서 넘 맛있어용 ( ᵕ̤ ‧̫̮ ᵕ̤ ) 카페 내부도 귀엽게 꾸며져 있답니당', 88, 12, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '친구가 밀크티랑 소다가 맛있다고 추천해줘서 방문했어요. 수제 밀크티라 그런지 생딸기 맛이 진짜 많이 나고 루이보스티는 풍미가 넘 좋더라구요~ 멜론 소다 음료도 위에 올라간 아이스크림이랑 잘어울려서 맛있었어요. 음료들을 하나같이 다 만족이라 푸딩은 어떨지 넘 궁금해져서 조만간 푸딩먹으러 다시 가보려구요. ^^', 30, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '모코모코! 매번 지나가기만 했었는데 오늘은 드디어 용기내어서 방문해보았습니다..✨ 앉아서 먹을 시간이 없어서 맛별로 하나씩 포장했어요! 사장님두 넘 친절하시구 푸딩도 말해모해.. 진짜 완전 맛있습니다🥺〰️❗️ 집에 가자마자 가족들끼리 하나씩 까먹어보았는데요, 정말 정말 맛있습니다.. 전메뉴 전부 추천 드립니땨..〰️ 다음엔 꼬옥.. 앉아서 먹고 갈테야..', 28, 3, 'GOOD', SYSTIMESTAMP);
