INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '모코모코에서 멜론소다와 커스터드 푸딩을 먹었는데 정말 만족스러웠어요! 멜론소다는 상큼하고 달달한 맛이 기분 좋게 퍼지면서, 위에 올라간 아이스크림까지 조합이 최고였어요. 커스터드 푸딩은 일본에서 먹었던 그 맛 그대로라 감동했어요. 부드럽고 진한 맛에 식감도 촉촉해서 정말 맛있게 먹었어요ㅎ', 65, 13, 'GOOD', SYSTIMESTAMP);
