INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '체리히비스커스는 신맛은 거의 없고 체리 과육이 들어있어 달달하고 은은한 맛이에요! 이런 종류의 차는 처음 먹어보는데 너무 맛있었어요 초코푸딩 발바닥 너무 귀엽지 않나요 발로나 커버춰가 들어간다고 써있는데 그래서 그런지 초코 맛이 정말 녹진~하고 진~하더라고요. 그런데 너무 달지도 않아서 부담 없고, 쫀득하고 꾸덕한 식감이 되게 고급진 맛이 나요', 8, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '전부터 너무 가고싶었던 카페에요~ 메뉴가 다 아기자기한데 저흰 소다랑 푸딩시켰답니다~ 멜론소다는 아이스크림없이해서 6000원, 블루소다는아이스크림 올려서 7500원이었어요~ 음료만 깔끔하게 드시고 싶을땐 빼고 주문하는게 좋을 거 같은데 예쁜 비쥬얼을 원하시면 아이스크림 포함 추천!❤️ 위에 올라가는 아이스크림도 맛있어요👍 커스터드푸딩은 당연 맛있고 딸기푸딩이 기대 이상으로 정말 맛있었어요~', 22, 2, 'GOOD', SYSTIMESTAMP);
