INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '홍대 모코모코 귀여운푸딩 검색해서 찾아갔어요 아이가 대구푸딩가게를 간데서 가까운데를가자고 검색해서 갔는데 분위기도 좋고 너무 예쁘네요 #홍대 #푸딩까페 #홍대푸딩까페', 18, 8, 'GOOD', SYSTIMESTAMP);
