INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '체리소다의 숙성 된 블랙체리 맛이 좋았어요 귀여운 비주얼에 맛은 고퀄리티였어요👍 아메리카노도 커피 전문점 못지 않은 퀄리티였고 전문점답게 말차푸딩, 커스터드푸딩 둘다 너무 맛있게 먹었어요! 말차는 살짝 쌉사름하면서도 말차 향이 확 퍼져요! 커스터드푸딩은 뷰드럽고 향긋한 바닐라향에 과하지 않은 달콤함이 잘 어울려요', 29, 6, 'GOOD', SYSTIMESTAMP);
