INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '친구랑 홍대 왔다가 방문했네요! 푸딩 좋아해서 찾아봤는데 이런 카페가 있다는게 너무 좋네요!! 푸딩과 음료 둘 다 너무 맛있었습니다♡', 20, 2, 'GOOD', SYSTIMESTAMP);
