INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '홍대에서 저녁먹고 지나가다가 귀여운 인테리어랑 디저트 보고 들어왔는데 사진이랑 똑같이 귀여워요>< 어제부터 푸딩이 먹고싶었는데 푸딩이 너무 달지도 않고 부드러웠고 카라멜 시럽도 맛있고 메론소다도 아이스크림이랑 잘 어울리고 달달시원했습니다🍈🍦🥤 홍대 귀여운 디저트 카페로 추천해요👍', 86, 17, 'GOOD', SYSTIMESTAMP);
