INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '홍대에서 너무너무 귀여운 카페를 발견해서 가보았는데 직원분도 친절하시고 푸딩이랑 음료가 너무 맛있고 분위기가 귀여워서 즐겁게 보내고 왔어요❤', 49, 6, 'GOOD', SYSTIMESTAMP);
