INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '장소가이쁘고아기자기하고 유튜브보고한번와보고싶었는데 맛있어요 아이가좋아하고 자리가몇자리없어서 오래기다렸는데 기다렸다고서비스주셔서감사합니다 푸딩이맛있네요^^♡', 73, 11, 'GOOD', SYSTIMESTAMP);
