INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '말차 덕후라면 무조건 좋아할 찐~한 말차푸딩! 한입 먹어보면,일본에서 먹어봤던 그 진한 말차 아이스크림이 바로 떠오르는 맛이에요. 말차 좋아하시는 분들한테 강추! 꼭 한 번 드셔보세요~ 그리고 블루소다는 뭐랄까, 보기만 해도 벌써 여름 분위기가 확 느껴지는 예쁜 비주얼! 시원한 파란 블루소다 위에 쏙 올라가 있는 소프트 아이스크림은 진짜 비주얼부터  여름이 확 느껴져요.', 43, 2, 'GOOD', SYSTIMESTAMP);
