INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '오랜만의 홍대 방문! 늘 포장만하던 모코모코 카페에 처음 앉아서 먹어봤다! 매장도 너무 아기자기하고 푸딩은 너무 맛있었다. 근처에 올일 있으면 자주 들리게될것 같다.', 129, 22, NULL, SYSTIMESTAMP);
