INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '홍대 푸딩 카페, 모코모코 🩷 자주 오는 푸딩 맛집입니다! 주인장 언니분이 지극정성으로 푸딩 직접 만드는 곳인데 정말정말 맛있어요 달달한 거 좋아하시는 분은 커스타드 푸딩, 담백한 카카오 맛을 좋아하시는 분은 초코 푸딩 추천드려요 👍', 5, 5, 'GOOD', SYSTIMESTAMP);
