INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '유명해서 한번쯤 와보고 싶었는데 홍대 방문한 김에 홍대 지점 친구와 매장 방문 했어요! 인테리어도 아기자기하니 넘 이쁘고 디저트가 정말 맛있어요 푸딩 좋아하는데 정말 넘 귀엽구 맛있었어요 ><💕💕 소다는 아이스크림 추가 필수!🍦🍦🍦', 4, 0, 'GOOD', SYSTIMESTAMP);
