INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '친구랑 홍대 놀러왔다가 알게 된 카페예요! 푸딩 진짜진짜 너무 귀여워서 심장이 다쳤어요... 곰돌이 진짜 너무 큐티하고 푸딩 완전 맛있어요 징짜ㅠ 말차푸딩 씁쓸한 맛인데 초코시럽도 먼저 추가하는거 추천해주셔서 너무 좋았어요! 담에 다시 오겠습니다!', 33, 7, 'GOOD', SYSTIMESTAMP);
