INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '모코모코에 또 왔어요😆 이번엔 커스터드푸딩과 얼그레이티따뜻한걸로 주문했는데,,와 푸딩은 기대했지만 기대보다 더 맛있었어요!!! 일본에서 먹은것보다 더 맛있었어요ㅎㅎㅎ그리고 귀여운머그잔에 담겨나온 티도 향긋하고 맛있어요!!! 푸딩과 잘 어울려서 추천하고가며 다음에도 먹으러올게요❤', 61, 12, 'GOOD', SYSTIMESTAMP);
