INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '외관이 너무 귀여워서 친구랑 즉흥으로 방문했어요 카페인 줄이고 있어서 논커피로 시켰는데 생각보다 음료도 맛나고 커스타트 푸딩도 탱글하고 적당히 달달한게 너무 맛나게 잘 먹었어요~~!!', 114, 26, 'GOOD', SYSTIMESTAMP);
