INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '친구랑 홍대 놀러 와서 어디 카페 갈지 고민하다가 푸딩이 맛있다는 모코모코에 왔어요 🤭 푸딩 너무 맛있고 멜론 소다도 맛있어염...🥹🥹 아기자기한 인테리어까지 완벽,,,👍', 40, 1, 'GOOD', SYSTIMESTAMP);
