INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '올 때마다 눈과 입과 심장이 해피해지는 디저트 샵! 지난번 커스터드 푸딩에 못지않게 딸기 푸딩도 완전 맛있다! 아이스크림도 반드시! 추가해서 먹어야하는 곳!', 35, 1, 'GOOD', SYSTIMESTAMP);
