INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '진짜너무너무너무 귀여운 카페! 푸딩간판 보고 홀린듯이 들어왔는데 절대 후회없음! 홍대 올때마다 방문할것같아요 귀엽기만 한게 아님 푸딩음료도 다 맛있어요', 20, 3, 'GOOD', SYSTIMESTAMP);
