INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '아이와 홍대 구경왔다가 검색해서 왔어요~~~지나가다 사람이 많길래 들렀는데 푸딩도 맛있고 커피도 맛있어요!!!홍대 푸딩카페 들러보세요~~', 47, 9, 'GOOD', SYSTIMESTAMP);
