INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '디저트가 명성답게 정말 맛있어요! 항상 사람이 많아서 방문하기 어려웠는데, 저녁에 가보니 다행히 대기 없이 바로 앉을 수 있었어요😄 직원분들도 친절하고 분위기도 좋아서 기분 좋게 즐기고 왔어요~♡♡', 15, 7, 'GOOD', SYSTIMESTAMP);
