INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '인테리어도 너무 아기자기하고 귀엽고 이쁩니다!!! 여기 푸딩 좋아해서 많이 먹어봤는데 초코푸딩도 제티맛이 아니라 엄청 깊은 맛이 느껴지는 비싼 초코맛이 느껴지고 그전에 먹었던 딸기푸딩도 인위적인 약맛딸기가 아니라 정말 생딸기를 쓰는듯한 맛이었어요 정말 푸딩맛하나는 강추합니다!😆', 34, 7, 'GOOD', SYSTIMESTAMP);
