INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '원래 가려던곳이 있었는데 예약없이가서 자리가 없다고해서ㅜㅜ 아이와 홍대역쪽으로 걸어가다 너무 예뻐서 들어왔어요. 아이가 푸딩을 좋아하는데 정말 최고로 맛있데요 메뉴들이 다 예쁘고 예뻐서 더 맛있게 느껴지는거같아요. 홍대에 카페가 우연히 맛있고 예쁜 카페를 찾게되서 운이 좋은거같아요^^', 7, 0, 'GOOD', SYSTIMESTAMP);
