INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '홍대에서 카페찾다가 가게외부에 푸딩메뉴가 있는걸보고 웨이팅대기 쪼금하고 들어왔습니다! 커스터드푸딩이 진짜 뷰드럽구 맛나요! 인테리어랑 식기도 너무 귀여운거같아요☺️', 29, 2, 'GOOD', SYSTIMESTAMP);
