INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '꽤 예전에 홍대 왔을때 발견했던 푸딩 카페인데 오래간만에 와도 아직 영업중이길래 방문. 우유푸딩은 딱 깔끔하고 시원한 우유맛이고 커스터드 푸딩은 그야말로 기대한대로 고소하고 진한 맛이 나는 푸딩입니다. 맛있어요.', 16, 1, 'GOOD', SYSTIMESTAMP);
