INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '홍대 푸딩맛집 카페!!🍮 포장해주시는 푸딩용기도 귀엽지만 매장에서 먹으면 더 귀엽게 해주십니당!!😆 사장님이 정말 친절하구 소다도 맛있고 푸딩 맛은 말해뭐해,, 딸기맛 찐하게 나는 딸기푸딩 추천합니당🍓🍮', 7, 5, 'GOOD', SYSTIMESTAMP);
