INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '멜론소다 처음 마셔보는데 카페 분위기랑 잘어울리는거같아서 시켜봤어요! 아이스크림 유무도 선택할 수 있고 음료도 너무 맛있어요,,💓 사장님이랑 직원분도 넘 친절하셔서 기분좋게 마셨습니다💕', 48, 8, 'GOOD', SYSTIMESTAMP);
