INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '말차 푸딩 말차가 찐하고 맛있었어요 푸딩이 너무 달지도 않고 무엇보다 귀여워서 너무 좋았어요 웨이팅이 길긴 했지만 기다릴 가치가 있었어요 🤭☺️', 7, 4, 'GOOD', SYSTIMESTAMP);
