INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '딸기푸딩, 초코푸딩, 메론소다 주문해서 먹어봤어요! 딸기는 생딸기맛이 엄청 좋고, 초코도 꾸덕뚜덕한 진한 초코맛이었어요 ^^ 매장 분위기도 메뉴 구성도 뭔가 동화속에 있는 거 같은 기분이라 너무 좋은 시간이었습니다!', 48, 8, 'GOOD', SYSTIMESTAMP);
