INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '문 앞에 붙어 있는 안내대로 대기 명단 작성했어요! 😊 평일이라 그런지 약 10분 만에 바로 전화가 왔답니다. 멜론소다랑 체리소다를 주문했는데, 스푼까지 색깔 맞춰줘서 정말 세심하더라고요. 체리소다는 과육이 씹힐정도로 듬뿍 들어 있었고, 멜론소다는 익숙한 메론 맛이라 호불호 없이 누구나 즐길 수 있는 실패 없는 맛이었어요.', 68, 17, 'GOOD', SYSTIMESTAMP);
