INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '예쁜 음료 디저트 싼 가격으로 너무 맛있게 먹었어요 사장님도 넘 친절하세요🥺🥺 분위기도 넘 좋고 메론소다 진짜 미틴 비주얼… 또 올게요!', 4, 0, 'GOOD', SYSTIMESTAMP);
