INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '처음 방문해서 뭘 몰랐기에 무난한 초코 푸딩을 먹었습니다. 초콜릿 맛이 진하고 부드러워서 한 숟갈씩 사르르 녹는 느낌이 좋았습니다. 너무 달지도 않아서 끝까지 맛있게 먹었어요. 가게 분위기도 아담하고 깔끔해서 푸딩 좋아하는 분들 홍대에 오시면 한 번쯤 가볼 만한 곳인거 같습니다', 47, 8, 'GOOD', SYSTIMESTAMP);
