INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '엄마랑 함께 홍대 놀러와서 지나가다가 예쁜 카페가 있어서 방문해봤는데 딸기푸딩이 엄청 부드럽고 딸기향이 확 올라와서 좋았어용 메론소다도 넘 예쁘고 달달해서 맛있어요!', 12, 7, 'GOOD', SYSTIMESTAMP);
