INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '매번 지나가다가 항상 사람들이 많아서 못갔는데 저녁시간대쯤 들렸더니 다행히 자리가있었어요! 아기자기한 인테리어에 분위기가 귀여워요~! 말차푸딩과 커스터드푸딩이랑 멜론소다 같이먹었는데 넘넘맛있어서 감동함서먹음. 특히 말차푸딩은 진짜 진한맛이라 넘좋아요! 홍대올때마다 들려볼거에요!!', 50, 10, 'GOOD', SYSTIMESTAMP);
