INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '홍대 놀러와서 푸딩 먹고 싶어서 모코모코 왔어요! 커스타드 푸딩 달달해서 맛있고 카페 인테리어가 아기자기해서 너무 귀여워요〰️🩵', 29, 1, 'GOOD', SYSTIMESTAMP);
