INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '친구 추천으루 홍대에 푸딩집 왔는뎅 ㄱ왔는데 아기자기하구 너무 귀엽고 맛있어요 ㅎㅎ 곰돌이 숟가락이 젤 맘에 든다능 조용한 카페라서… 감성잡기 구웃 ㅎㅎ', 49, 6, 'GOOD', SYSTIMESTAMP);
