INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '홍대에서 제일 귀여운 푸딩카페! 예에전에 푸딩 한번 잘못먹고 음 내취향은 아니라고 생각했는데...그냥 그집 푸딩만 취향이 아니었다..여기 커스터드는 진짜 맛있음ㅜㅠ 나의 푸딩세계를 다시 넓혀준 곳! 소다류도 사진찍기에도 맛도 좋아서 정말 추천! 다만 오픈시간대가 아니거나 늦게오면 자리가 없음ㅜㅠㅠ 포장도 가능한데 그러면 귀여운 곰돌이를 못보는 슬픈 사실...', 71, 16, 'GOOD', SYSTIMESTAMP);
