INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '홍대 놀러올 때마다 눈독들이던 카페인데 늘 사람이 많아서 오늘 드디어 첫 방문! 곰돌이 푸딩 너무 귀엽고 맛있음!! :P 종류별로 푸딩 다 먹어보고 싶음!', 48, 0, 'GOOD', SYSTIMESTAMP);
