INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '오랜만에 친구랑 둘이 홍대에 왔는데 길가다 본 푸딩 사진에 나도 모르게 입장했습니다 ㅋㅋ 사랑스러운 푸딩 한입 사르르 녹아버리는 기분.. 카페 인테리어도 너무 사랑스럽고 귀엽습니다.. 아기자기하게 카페에서 푸딩한입 하고 싶다면 추천 하겠습니다..👍', 57, 13, 'GOOD', SYSTIMESTAMP);
