INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '사장님이 마싯고 디저트가 친절해요,,🩷 디저트가 너무 먹기도 아깝게 귀여워요ㅠㅠㅠ 심지어 맛있어요🧸 나중에 푸딩 땡길때 여기 홍대 카페 이용할 것 같아요!! 재방문 100퍼센트.', 18, 8, 'GOOD', SYSTIMESTAMP);
