INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '홍대에서 제일 귀여운 카페를 찾으신다면 바로 이곳입니다!! 특히 푸딩은 꼭 시키세요 너무 귀엽습니다ㅠㅠ❤️🥰 아늑하고 넘넘 예뻤어용💕', 0, 1, NULL, SYSTIMESTAMP);
