INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '꿈뜰이 모임하다가 친구들과 우연히  왔습니다! 음식들 너무 너무 귀엽고 직원 분도 정말 친절하고 밝은 분이세요! 직원 분 타로 봐 드렸는데 좋아해주셔서 귀여우셨습니다🥰 커스터드 푸딩 추천!!🍮 홍대 맛집 카페', 31, 3, NULL, SYSTIMESTAMP);
