INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '푸딩맛집으로 유명한 가게인데 음료도 너무 맛있어요!!! 아메리카노도 맛이 깔끔하고 밀크티를 직접 만드신다고 하더라구요 그래서 그런지 진짜 진하고 맛있어요 커스터드푸딩 우유푸딩이 전혀 다른식감과 맛이 나는데 커스터드는 부드럽고 고급스러운맛이나요 우유는 산뜻하고 살짝 탱글한식감이에요 ㅎㅎ 메뉴가 다 과하지않고 적당한 당도에 풍미도 깊고 너무 맛있어요', 33, 6, 'GOOD', SYSTIMESTAMP);
