INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '평일 낮시간인데도 인기 매장 답게 만석이었어요! 카운터에서 대기 명단 작성하면 전화 주시는데, 15분정도 기다렸습니다. 매장이 작지만 회전률이 빠른듯해요. 마침 근처에 피규어샵이나 소품 가게가 많아 구경하다보면 금방입니다ㅎ 앉고싶었던 창가자리 안내 받아서 좋았어요🥰 블루소다랑 커스터드푸딩 주문했는데, 모양도 예쁘고 맛도 좋았어요!', 68, 16, NULL, SYSTIMESTAMP);
