INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '홍대에서 예쁜 카페 찾다가 귀여운 푸딩을 판매하는 모코모코를 보고 친구들이랑 바로 갔어요! 대기 3분 만에 들어가서 운이 좋았습니다 ㅎㅎ 메뉴도 빠르게 나오고 너무 맛있어요!! 다음에 친구들이랑 또 방문하겠습니다🐻🍮🍎', 0, 0, 'GOOD', SYSTIMESTAMP);
