INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '친구랑 돌아다니다가 아기자기한 곳 발견해서 들어간곳 ㅎㅎㅎ 블루소다 딸기푸당 커스터드 푸딩 주문 블루소다 맛은 뽕따 아이스크림 맛  위에 아이스크림은 우유맛이 진하고 맛있음~ 딸기푸딩은 직접담군 딸기청으로 만들어서 그런지 인공적인 맛이 안나고 생딸기 맛이 느껴져서  맛있음 >_< 커스타드 푸딩은 은은하게 바닐라향이 나면서 살살녹는 부드러운 식감과 당도가 딱 맞아서 너무 맛있게 잘먹음!!!!', 95, 19, 'GOOD', SYSTIMESTAMP);
