INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '오랜만에 이색카페 찾아서 들렸네요.말차 푸딩 처음 먹어봤는데 일본에서 말차가 유명한만큼 특유의 맛을 느낄 수 있었어요. 원래 달달한커피만 즐기다보니 디저트 생각하지 못했는데 힐링하고 갑니다. 종종 이용할께요.', 34, 7, 'GOOD', SYSTIMESTAMP);
