INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '또 모코모코에 방문했어요😆 대표메뉴인 메론소다와 커스터드푸딩주문했는데,,대표메뉴답게 비주얼뿐만아니라 호불호갈리지않을거같은 달다구리한맛!!! 음료퀄리티도 좋고 아이스크림은 맛있고 푸딩은 식감, 당도, 비주얼 3박자완벽해요ㅎㅎ이정도퀄리티면 다른푸딩도 맛있을거같아서 모든맛 도장깨기하고싶네요❤', 16, 10, 'GOOD', SYSTIMESTAMP);
