INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '홍대 카페 홍대 푸딩 맛집!!🍒 인터리어도 정말 귀엽고, 평화로운 모동숲?같은 브금이 흘러나와서 좋아요!!💗 시그니처인 커스터드 푸딩도 부드럽고 맛있어요!! 다음엔 다른메뉴 도전하려구요!💕', 129, 21, 'GOOD', SYSTIMESTAMP);
