INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '홍대 길거리에서 걸어다니다가 너무 귀여운 카페가 보여서 방문했어요! 푸딩도 음료도 너무 달지 않아서 달달한 디저트를 잘 못먹는 편인데도 맛있게 먹을 수 있었어요! 홍대에 놀러가신다면 꼭 들러보시길 추천합니당😋', 1, 3, 'GOOD', SYSTIMESTAMP);
