INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '우유푸딩,커스타드,딸기푸딩 딸기는 진짜 딸기우유 맛 👍 저는 여기서는 딸기가 제일 맛있었어🫶 메론소다는 지인이 먹었고, 전 밀크티 마셨는데 꽃잔도 이쁘고 달달하이 잘먹었습니다🙂', 53, 11, 'GOOD', SYSTIMESTAMP);
