INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '푸딩 너무 귀엽고 맛있어요💗💗 가격대비 너무 실합니다.. 가게 인테리어랑 소품도 너무 아기자기하니 맘편하게 쉴 수 있었어요 다만 테이블이 몇 없어서 여차하면 웨이팅 하셔야 될 수도 있다는 점!', 27, 10, 'GOOD', SYSTIMESTAMP);
