INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '홍대에서 푸딩으로 유명한 카페라고 해서 방문했어요 ! 😚 저녁 방문했을 때 만석이라서 오래 기다려야 하나 했는데 금방 자리가 빠져서 10분 이내로 들어왔습니다 💗 들었던 대로 푸딩 진짜 귀엽고 인스타 사진 찍기 최적의 공간이에요 ! 🫶🏻', 16, 9, 'GOOD', SYSTIMESTAMP);
