INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '홍대에서 데이트하다가 우연히 들어갔는데 우유푸딩도 맛있고 카페 인테리어도 아기자기 해서 좋은거같아용.. 데이트 목적이나 귀여운거 좋아하시거나 하시면 추천드립니당!', 76, 15, 'GOOD', SYSTIMESTAMP);
