INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '홍대에 위치해 있는 카페, 모코모코에 왔어요. 푸딩 위에 올라가 있는 곰이 너무 귀여웠어요!!! 매장도 아기자기하게 꾸며져 있어서 사진이 잘 나오는거 같아요. 노래도 흘러나오는데 귀여운 분위기의 노래라 매장이랑 잘 어울렸던 거 같아요.', 37, 9, 'GOOD', SYSTIMESTAMP);
