INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '모코모코 홍대 카페는 푸딩이 정말 맛있어요 :) 생크림이 올라갔는데 푸딩이랑 잘 어울려요ㅎㅎ 매장도 귀엽고 분위기도 아기자기하고 좋아요 히히', 124, 25, 'GOOD', SYSTIMESTAMP);
