INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '친구랑 지나가다가 귀여운 푸딩 모형 보고 들어갔는데 내부도 너무 아기자기하고 귀여워요 😭❤️❤️ 홍대에서 카페 많이 가봤는데 이렇게 포근하고 귀여운 곳은 처음입니다 !! 푸딩도 너무너무 귀엽고 맛있어요 ! 컵이랑 인테리어, 모든 것이 귀엽고 따뜻한 공간입니다 !! 완전 강추 ⭐️⭐️⭐️⭐️⭐️', 13, 4, 'GOOD', SYSTIMESTAMP);
