INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '홍대 모코모코 말차 푸딩~~. 친구가 가고 싶다고 해서 왔는데, 맛있게 잘 먹었어요. 가게 인테리어도 아기자기하고 너무 좋네요. 밀크티 품절이라 못 먹은 건 아쉽...! 담에 또 올게요!', 45, 2, 'GOOD', SYSTIMESTAMP);
