INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '홍대 근처에 놀러갔다 귀염뽀짝한 인테리어에 반해 방문했어요:) 딸기 좋아하는 아들이 딸기푸딩먹어보더니 맛있다고 엄지척하네요 너무 예뻐서 사진 한참찍고 먹은건 안 비밀ㅎㅎ 공간은 작지만 너무 귀여워서 또 방문하고싶어요!', 95, 24, 'GOOD', SYSTIMESTAMP);
