INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '홍대에 있는 푸딩 카페 지인이 추천해줘서 왔는데 카페 분위기 넘 느좋이에여 ㅠㅠ ( ^-^)ノ∠※。.:*:・''°☆ 사장님도 친절해엽 (*≧∀≦*)', 24, 10, 'GOOD', SYSTIMESTAMP);
