INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '홍대에서 오랜만에 맛있는 푸딩을 먹을 수 있는 카페여서 좋았습니다. 저흰 남자 셋 여자 하나 로 왔지만 아무래도 여긴 여성분들, 커플분들이 오기 좋은 장소입니다. 물론 남성분들끼리 와도 즐기실 수 있습니다😃 가격도 적당하고 맛있었어요.', 24, 6, 'GOOD', SYSTIMESTAMP);
