INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '홍대 혼자 놀러 다니고 있는데 들어오기 전부터 귀여워 보이는 카페가 있어서 지나가다 들렀습니다. 푸딩 종류도 적지 않고 맛도 있고 무엇보다 엄청 귀여워요 귀엽고 조용한 분위기에서 편안하게 디저트 맛보고 싶은 분들이 오시면 좋을 것 같습니다!', 52, 14, 'GOOD', SYSTIMESTAMP);
