INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '마포에 갈일 생기면 꼭 들리는 디저트집 모코모코♡ 가게이름만큼이나 메뉴도 사랑스러워요 저는 메론소다 주문했는데 메론맛 커스티드식감이 부드러우니 제 입맛에 아주 딱이에용 🍈 은 사랑입니다♡♡', 0, 0, 'GOOD', SYSTIMESTAMP);
