INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '초코 말차 맛이 진하고 만힝 달지않아서 먹기 딱좋아요!! 식감은 쪽득 녹진한편이라서 좋고 위에 올라간 생크림이랑도 완벽 조합!! 애플 시나몬티는 따뜻하게 먹으면 더 맛있을꺼같아여~', 48, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '홍대에서 제일 귀여운 푸딩카페에용 돌아다니다가 간판부터 푸딩모양이어서 넘 귀여워서 들어갔는데 귀여운만큼 맛도 넘 맛있고 가게 인테리어도 좋아용 포근포근한 분위기에서 맛있는 푸딩을 먹을 수 있는 카페에용 인기도 많은지 사람도 거의 가게 안에 꽉 찼어용 데이트 장소로 추천해용', 39, 3, 'GOOD', SYSTIMESTAMP);
