INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '카페가 너무 예뻐서 외부에서 내부까지 구석구석 아기자기하게 잘 꾸며져 있어서 어디를 찍어도 포토존이더라고요~ 밀크티 컵이 너무 귀여워요! 딸기루이보스밀크티랑 얼그레이밀크티 모두 맛있고 밀크티 직접 다 만드셔서 그런지 향이 진하고 너무 좋아요. 대표메뉴인 커스터드 푸딩도 먹어봤는데 사진보다 실물이 훨씬 예뻐요. 대표메뉴답게 정말 맛있어요!! 눈이랑 입이 즐거운 시간이었습니다^^', 31, 8, 'GOOD', SYSTIMESTAMP);
