INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '우유푸딩은 찐~~한 우유맛에 과하지 않은 단맛이 느껴져요! 특유의 우유 비린내도 없고 너무 맛있었어요ㅎㅎ 초코도 맛이 굉장히 진한데 과하게 달지 않아 좋았어요 위에 올라간 곰돌이는 생크림인데 푸딩과 너무 잘 어울려요 너무 귀여워서 먹기 아까웠지만 맛있게 먹었습니당~~', 16, 9, 'GOOD', SYSTIMESTAMP);
