INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '홍대에 있는 푸딩 맛집 카페라고 해서 찾아오게 되었는데요!! 와 정말 눈도 즐겁고 입도 즐겁고 너무 기분좋고 맛있게 먹고왔네요!! 하나하나 전부 눈에 담으려고 얼마나 노력햇는지..다들 꼭 드셔보세요 너무 밋있어요 ㅠㅠ', 50, 9, 'GOOD', SYSTIMESTAMP);
