INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '너무 예뻐서 완전 반했어요🩵 인테리어 너무 예쁘고 분위기도 좋아서 사진이 정말 잘나와요 :) 친구랑 사진 엄청 찍었어요 히히☺️ 비주얼도 제 취향저격한 디저트랑 음료는 놀랍게도 맛도 좋더라고요?! ㅎㅎ 어느것 하나 빠지는 게 없이 완벽했던 모코모코😍 반했어요ㅎㅎ 또 갈게요 :)', 38, 4, 'GOOD', SYSTIMESTAMP);
