INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '푸딩 좋아하는 만3세랑 왔어요. 홍대 유명 푸딩집이라 웨이팅 있을까봐 오픈런해서  다행히 바로 입장했습니다. 푸딩위의 크림데코가 너무 귀엽고 까페도 아기자기~ 달콤하고 맛있어요♡', 26, 2, 'GOOD', SYSTIMESTAMP);
