INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '푸딩을 좋아해서 홍대에 온 김에 먹을만한 카페 찾아보다가 음식 사진이 귀여워서 바로 왔어요! 푸딩은 물론 음료수 위에 아이스크림도 맛있어서 만족했습니다!', 92, 24, 'GOOD', SYSTIMESTAMP);
