INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '홍대 놀러왔는데 귀여운 푸딩카페가 있어서 왔어요!! 그냥 귀여워보여서 온건데 먹어본 푸딩중에 젤 맛있어서 놀랐어요!! 귀여워용 너무', 17, 7, 'GOOD', SYSTIMESTAMP);
