INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '홍대에 푸딩집을 검색했는데 바로 앞에 나와있고 너무 푸딩이 귀여워서 홀린듯이 들어왔어요🥹🥹 카페 분위기도 좋고 아기자기한 소품이 많아서 너무 좋았습니다! 다음에도 또 방문할게요♥️♥️', 48, 8, 'GOOD', SYSTIMESTAMP);
