INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '홍대 푸딩맛집이라는 소문을 듣고 찾았습니다. 아기자기한 인테리어 덕분에 눈도 즐거웠고 디저트도 맛있었습니다. 연인 친구와 가볍게 들리기 좋은 곳이라 추천합니다!', 8, 1, 'GOOD', SYSTIMESTAMP);
