INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '푸딩이 너무 부드럽고 맛있어요 ㅠㅠ 위에 귀엽게 올라간 강아지 크림도 부드럽고 우유맛이 찐해서 엄청 맛있고 푸딩과 잘 어울려요 분위기도 너무 따뜻 포근한 분위기라서 친구들과 와서 푸딩 먹으며 얘기하기 좋아요!!', 42, 10, 'GOOD', SYSTIMESTAMP);
