INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '‼️여기 홍대 푸딩 맛집입니다 꼭 오세요..!‼️ 푸딩러버인 제가 먹고 정말 반한 카페입니다😍😍 푸딩이 너무 귀엽고 맛있습니당 사장님도 넘 친절하시고 카페 분위기도 짱 조아요!! 재방문 의사 100%입니다~~', 20, 7, 'GOOD', SYSTIMESTAMP);
