INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '홍대 푸딩 카페 데이트하다가 푸딩간판보고 들어오게 되었는데, 푸딩이 부드럽고 맛있었어요. 디피도 너무 이쁘고 사진도 잘나와서 데이트 장소 추천합니다', 0, 0, 'GOOD', SYSTIMESTAMP);
