INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '친구들이랑  푸딩 먹으려고 찾아왔는데 푸딩이랑 소다 너무 맛있고 인테리어도 너무 귀여워요!! 친구들이랑 왔는데 다 푸딩 너무 귀엽다고 먹기 아까워했어요🥹🥹  홍대 최애 카페 됐어요🩷', 12, 10, 'GOOD', SYSTIMESTAMP);
