INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '5번째 재방문인데 올때마다 푸딩이 너무 맛있어요 ! 항상 우유푸딩만 먹다가 말차푸딩 도전해봤는데 진쨔 맛있어요 인테리어도 너무 귀엽고 좋아요 홍대에서 푸딩파는 카페중에 제 기준 1위 .. 🩷', 12, 2, 'GOOD', SYSTIMESTAMP);
