INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '홍대에서 푸딩맛집 찾다가 들어온 곳인데 너무 아늑하고 푸딩도 너무 맛있었어요!! 소품들도 너무 귀엽고 카페 분위기도 너무 좋아서 다음에 또 올 것 같아용', 84, 18, 'GOOD', SYSTIMESTAMP);
