INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '홍대 돌아다니다가 정말 귀여운 카페가 있어서 들어왓더니 아니 귀여운 푸딩을 팔고있었어요!!!그리고 메론소다도너무귀여워요!! 푸딩이랑 소다 둘다 귀여운것 뿐만 아니라 너무너무 맛있습니다!!🧸오랜만에 귀여운 공간에서 귀여운 디저트 먹으니 행복했습니다!', 29, 5, 'GOOD', SYSTIMESTAMP);
