INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '인테리어가 너무 예쁘고 푸딩이 진하고 맛있어요! 홍대 푸딩 먹을 수 있는 카페 찾으신다면 오시는 거 추천해요! 메론소다도 달달하니 맛있고, 아이스크림이 맛있습니다. 사진도 잘 나와요!', 10, 9, 'GOOD', SYSTIMESTAMP);
