INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '홍대 푸딩 카페◠ ̫◠ 푸딩도 너무너무귀엽고 커피도 맛있어요. 대기 있을까봐 걱정했는데 바로 들어갈 수 있어서 더 좋았습니다. ˘͈ᵕ˘͈👍💕 인테리어도 너무 귀여웠어요.', 83, 15, 'GOOD', SYSTIMESTAMP);
