INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '홍대에 친구랑 놀러 오면서 카페에 들렸어요! 다른 곳보다 가격이 싼데 맛도 더 좋아요 무엇보다 가게가 너무너무 이뻤어요! 홍대에 올때 들렸던 카페중에 제일 이쁜 것 같아요!~~^^ 여기서 커스타드 푸딩을 시켰는데 너무 귀여워요 올라간 하얀크림(?)이 달고 맛있어요 홍대에 오면 또 여기 들릴 것 같아요!', 101, 25, 'GOOD', SYSTIMESTAMP);
