INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '카페 간판에 붙어있는 푸딩에 홀려 들어갔던 카페에요. 커스터드푸딩이랑 블루 소다를 마시고 왔는데 개인적으로 푸딩이 너무너무 맛있네요🍮 다음에 또 오고 싶을 정도였어요. 즐겁게 있다 갑니다.', 32, 0, 'GOOD', SYSTIMESTAMP);
