INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '말차푸딩이 유명하다고 해서 방문했어요! 말차 디저트는 너무 연하거나 쓴맛만 나는 경우가 많던데 진한 말차맛에 은은한 쌉쌀한맛과 단맛이 적당하고 조화롭게 이루어지면서 고급스러운 맛이 났어요🤩', 28, 10, 'GOOD', SYSTIMESTAMP);
