INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '홍대에서 가장 귀여운 푸딩 카페 모코모코 🥺 푸딩 위에 곰돌이 올라가 있는 게 너무 마스코트고 귀여워요 ㅠㅠ 테이크아웃해서 가는데 담엔 직접 와서 먹고 싶어요 (〃´𓎟`〃)', 31, 5, 'GOOD', SYSTIMESTAMP);
