INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '전에 홍대오면서 한번 들린 곳인데 그때는 달달한 게 안 땡겨서 쿠키차만 마시고 갔었어요 🥹 근데 집가면서 푸딩이랑 소다가 너무 아른아른 .. 결국 언니랑 같이 방문했답니다!! 이브라서 사람이 많을까봐 걱정했는데 딱 2자리만 남아서 럭키비키 ..🍀 저는 커스타드 푸딩과 블루소다를 주문했는데 너무 귀엽고 사랑스러운 비주얼과 맛 ,,,, 홍대 오시면 꼭 들려야 할 카페 ..💛🩷', 17, 2, 'GOOD', SYSTIMESTAMP);
