INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '친구가 추천해준 홍대 푸딩 맛집이라 왔는데 타이밍이 좋아서 대기 없이 바로 앉을수있었어요! 푸딩들 다 탱글하고 부드러워서 좋았고 우유 초코 커스타드 먹었는데 개인적으로는  커스타드가 제일 맛있었어요❤️ 인테리어도 아기자기하고 귀여운 카페라 친구랑 오기 좋아요!', 278, 80, 'GOOD', SYSTIMESTAMP);
