INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '홍대 오랜만에 왔는데 근처에 예쁜 카페가 있어서 들어갔어요! 근데 메뉴를 시켰는데 진짜 예쁜 푸딩이 나와서 놀랐어요! 이런 푸딩 처음 먹어보는데 맛도 졸도라구요! 꼭 와보시길 추천해요🙏🏻', 157, 86, 'GOOD', SYSTIMESTAMP);
