INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '친구가 여기 푸딩이 맛있다고해서 홍대왔다가 방문했어요 카페가 넘 아기자기하게 인테리어가 귀여워용 푸딩이 진짜 너므 귀여움 ㅎㅎ 귀여운거 좋아하시면 진짜 좋아할듯용 커피도 푸딩도 너무 맛있어요', 41, 2, 'GOOD', SYSTIMESTAMP);
