INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '홍대에서 너무 귀여워서 다시 돌아오게 만든 푸딩 카페! 역까지 걸어갔다가 귀여운 푸딩 디자인이 자꾸 생각나서 푸딩먹으러 돌아왔어용ㅋㅋㅋㅋ 푸딩 진짜 맛있고 밀크티가 미미!!!!! 밀크티 진짜 좋아하는데 제대로된 맛이었습니다~♡ 다음에 또 푸딩이랑 밀크티 먹으러 올게용♡ 사진은 오늘 돌아다니며 샀던 키링들과 함께 ㅋㅋ', 40, 0, 'GOOD', SYSTIMESTAMP);
