INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '홍대에 귀여운 푸딩 카페 모코모코🍀 푸딩이 넘 귀엽고 맛있어용 카페 안에서 잔잔하고 귀여운(?) 음악도 나오고 사장님이 친절하세요ꯁ', 73, 16, 'GOOD', SYSTIMESTAMP);
