INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '최근에 홍대에 자주왔는데, 저녁이나 술 먹기 이전에 들릴 카페를 찾아보다가 모코모코라는 푸딩맛집으로 알아보고 왔어요 ! 제 바부 이슈로 아이스크림 없이 멜론소다만 마셨지만 너무 맛있었고 , 딸기 푸딩 시키면서 딸기인척 하는 다른 푸딩들과 같으면 어떡하지 했는데 . 진짜 최근에 먹은 딸기로 만든 간식중에 제일 맛있어요. 딸기 과육맛 ㅎㅎ 딸기 좋아하는 분들 추천드려용🍓', 24, 1, 'GOOD', SYSTIMESTAMP);
