INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '지나가다가 인테리어가 너무 예뻐서 와보고 싶었는데 늘 사람이 많았어서 기회가 없다가 오늘 럭키하게 방문할 수 있었습니다. 밖에서 보던 것 보다 안에 들어오니 인테리어가 너무 예뻤어요! 커스터드 푸딩 시켰는데 크림위에 발바닥 너무 귀여워서 귀여워를 계속 외쳤습니다. 맛도 부드럽고 달콤하고 맛있었습니다. 다음에 기회되면 또 오고 싶네요!', 42, 6, 'GOOD', SYSTIMESTAMP);
