INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '우연히 찾은 홍대 푸딩집인데 인테리어도 아기자기 귀엽고 푸딩도 귀여운데 완전 맛있어요 ! 커스타드는 일본꺼처럼 맛있는데 딸기푸딩 진짜 기대이상입니다 !! 상큼하고 예쁘고 맛있어요 진짜 저 믿고 꼭 드셔보세요👍🏻 요런 귀여운 카페 좋아하는데 넘 좋아요..🩷💕 다음에는 소다 뿌시러 올려구요..! 진짜 그 정도..!💝', 43, 8, 'GOOD', SYSTIMESTAMP);
