INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '우리 아아가 너무 좋아하는 곳~ 우연히 가다 들른 모코모코에서 블루소다와 커스터드 푸딩을 먹고 반해서 또 오게 되는 곳!!! 이번엔 멜론소다 도전!!! 애니메이션 속에 들어 온 듯한 인테리어와 음악은 힐링입니다 🩵🩵🩵', 93, 20, 'GOOD', SYSTIMESTAMP);
