INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '홍대 카페를 찾아보다가 후기가 좋은 푸딩 카페를 발견했어요!! 모코모코는 한국어로 복슬복슬이라는 뜻이라던데 딱 가게 분위기랑 알맞은 가게 이름인것 같아요. 그리고 푸딩이 너무 맛있어요... 입에서 녹아요...', 46, 2, 'GOOD', SYSTIMESTAMP);
