INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '홍대 놀러온 김에 귀엽고 맛있는 카페를 찾아보다가 발견한 푸딩 맛집이에요!! 넘 아기자기하고 귀여워서 먹기가 아까웠어요 >.< 앞으로도 오래오채 장사해주세요 꼬옥 다시 올게요!! 💖', 35, 9, 'GOOD', SYSTIMESTAMP);
