INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '오랜만에 홍대 데이트 하다가!넘넘 이뻐보여서 거는길 멈추본 들어간 카페!!❤️진짜 푸딩이 완전 시요미하궁!가격도 생각보다 괜찮더라구용!!완전 기요미 소품으로 아기자기하게 꾸며두시궁!좌석에 곰돌이가 밖을 보고 있는것듀 아주아주 기요미 해요ㅜㅠ진짜 지구 뿌셔ㅠㅠ 진짜 이런 사랑스럽구 기요미한 카페는 온 세상 사람들이 다 알아야할 정도에용!!음료도 맛있궁 푸딩이 진짜 뽀잉뽀잉하구 위에 크림도 아주 기요미햐서ㅜㅠ행벅해료ㅜㅠ진짜 사랑스러운 카페 담에두 방문 할 예정이에용ㅜㅠ❤️❤️', 15, 5, 'GOOD', SYSTIMESTAMP);
