INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '원래 말차 안 먹는데 모코모코 말차는 맛있어요 쓴 맛만 나는 말차가 아니고 차의 향이 강하고 적당히 쌉쌀한 맛이 나는 엄청 진한 맛이라서 맛있어요💚 커스터드는 당연히 맛있었고 함께 주문했던 커피랑 멜론소다도 퀄리티가 좋았어요👍🏻', 1, 10, 'GOOD', SYSTIMESTAMP);
