INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '매장이 귀엽고 아늑해요 푸딩 그림도 많고 군데군데 꾸며져있어서 구경하기 좋아요 홍대라 사람이 많아서 방문하지 못했는데 이 시간대에서는 사람이 없어서 구경하고 놀기 좋았어여 홍대에 예쁜 카페! 푸딩 좋아하시는 분들은 추천합니당', 74, 12, 'GOOD', SYSTIMESTAMP);
