INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '홍대 푸딩 카페 왔어요!!! 지나가다가 많이 봤는데 늘 사람이 많아서 못 들어갔는데 너무 맛있어오 인테리어도 궈엽고 무엇보다도 제가 먹어본 밀크티 중에서 제일 맛있어요 싸구려 밀크티가 아니라 진짜 향 잘 느껴지는 밀크티에요 딸기 루이보스 밀크티ㅠㅠㅠ정말 맛있습니다 딴 건 몰라도 이건 꼭 드셔보세요🥰🥰', 5, 6, 'GOOD', SYSTIMESTAMP);
