INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '디저트랑 음료 다 너무 맛있고 귀여워요!! 너무 귀여워서 먹기 아까웠어요ㅠㅠㅠ 인테리어도 알록달록 아기자기하니 너무 예쁘고 분위기도 짱이에요!!! 배경 음악도 너무 좋아서 맛있게 먹고 잘 떠들다가 왔어요~ 최고의 카페 입니당:)', 33, 7, 'GOOD', SYSTIMESTAMP);
