INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '인스타 보고 홍대까지 찾아왔는데 예상 외로 푸딩이 너무너무 귀여워요 😍😍 푸딩 맛마다 숟가락 색깔도 맞춰서 주시는 디테일도 너무 좋았어요 카페 분위기도 딱 제 스타일이라서 더 좋았습니다 😋🍀✌🏻', 32, 7, 'GOOD', SYSTIMESTAMP);
