INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '아이랑 홍대에 왔는데 정말 귀여운 카페에서 로망의 메뉴를 판매하네요. 푸딩이라니 정말 사랑스러워요~~디저트도 커스터드 푸딩 캐러멜과 어우러진 맛이 너무 좋았어요~~모양은 말할것도 없이 정말 귀엽구요^^ 오늘 데이트 성공적이네요^^', 36, 8, 'GOOD', SYSTIMESTAMP);
