INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '혼자 홍대 놀러온김에 전부터 가보고 싶었던 모코모코에 방문해봤습니다✨️ 귀여운 푸딩과 소다 메뉴를 먹어보고싶었어서 각각 근본적인 맛으로 골라서 주문해봤습니다! 달달하고 부드럽고 맛있는 아이스크림과 메론소다의 조합은 충분한 당충전이 되어 기분이 좋았습니다🤭🍈 그리고 비주얼이 말이 안 되게 귀여운 커스터드 푸딩... 이거 하나보고 홍대온다해도 아쉽지 않을거 같습니다🥹💖 너무 귀여워서 보자마자 스트레스가 풀리더라구요! 맛은 무난무난하니 좋습니다👍✨️ 귀여운 비주얼에 다음엔 친구와 재방문하고싶다고 생각이 들었습니다!🫶 홍대 디저트 카페  찾고 계신다면 추천드립니다🥰💕', 58, 12, 'GOOD', SYSTIMESTAMP);
