INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '친구랑 놀러 다니면 푸딩집은 꼭 찾아서 가는데 사장님 여기 타지 배달도 되는 건가요. 주기적으로 안 먹으면 현기증 나서 못 살 거 같은데.. 그 정도로 맛있고 초코도 진해서 너무 좋습니당 친구는 커스터드 푸딩 먹었는데 이거 그냥 사랑입니다. 사장님 이 한 마디만 하겠습니다. 푸딩 장사 계속 해주세요♥ 여러분 홍대 푸딩 카페는 어디다? 모코모코다. 그럼 전 이만~♥', 76, 14, 'GOOD', SYSTIMESTAMP);
