INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '친구와 함께 찾아본 온 홍대 카페인데 먹기 전부터 너무 귀엽고 메론소다 생각 이상으로 너무 맛있어요...!̤̻ 푸딩도 너무 귀엽고 다음에 또 오고 싶은 카페에요🥹🫶🏻', 47, 0, 'GOOD', SYSTIMESTAMP);
