INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '<홍대, 푸딩, 카페> 딸기 푸딩을 시켜서 먹었는데 진짜.. 딸기가 진짜 맛있었어요...! 그리고 친구들이 시킨 초코 말차 커스터드 3개 도 맛있었어요...! 진짜 홍대와서 여기 온게 다행인거 같아요..!', 33, 1, 'GOOD', SYSTIMESTAMP);
