INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '홍대 놀러왔다가 너무 좋은 카페를 발견해서 기분이 좋아요!!! 푸딩 원래 돈주고 안사먹는 사람인데 여긴 초코푸딩이 진짜 맛도리입니닿ㅎㅎ 분위기도 미쳤고 혼자 오기도 괜찮은 것 같아용🩷', 61, 17, 'GOOD', SYSTIMESTAMP);
