INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '홍대를 지나가다가 너무 귀여운 푸딩이 보여 방문한 카페! 블루소다랑 메론소다는 너무 달지 않아서 좋았고 커스터드 푸딩은 내가 먹어본 푸딩 중에 가장 맛있었던 곳😆❤️ 크림도 귀여운 곰돌이 모양으로 올려주셔서 비주얼도 맛도 넘 좋은 곳❣️', 20, 5, 'GOOD', SYSTIMESTAMP);
