INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '오랜만에 홍대 놀러와서 아기자기한 카페 찾고 있었는데 도로변에 잘 보여서 들어오게되었어요🥹 체리소다 넘 맛있게 먹어서 다음에 올땐 우유푸딩도 시켜보고싶네요😋😋', 4, 1, 'GOOD', SYSTIMESTAMP);
