INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '홍대 들렸다가 푸딩카페 보이길래 방문 해봤어요~~ 들어서자마자 너무 아기자기하고 예쁜 카페 분위기에 놀랐어요! 소품샵 느낌 완전 귀여워요♡♡ 푸딩도 종류 다양하고 귀엽고 맛있어서 강추!! 홍대 오시면 꼭 들를만한 카페입니다👍🏻👍🏻', 107, 26, 'GOOD', SYSTIMESTAMP);
