INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '딸아이 미술학원 전시회를 홍대쪽에서 하게되어 전시회 구경하고 바로근처에 푸딩 카페를 발견하여 방문하게 되었습니다. 매장이 아기자기하고 조용합니다. 우유 푸딩과 초코 푸딩 둘다 맛있었어요. 추천 합니다.', 26, 0, 'GOOD', SYSTIMESTAMP);
