INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '홍대에 그냥 정처없이 돌아다니다가 느낌 좋은 간판이랑 포스터 붙여져 있는 카페가 있길래 무작정 들어갔었는데 웨이팅이 좀 있더라구요 30분? 정도 기다렸는데 근처에 소품샵이나 볼거리가 많아서 크게 문제는 안 됐어요 우유 푸딩이 깔끔하니 맛있었어요 좀 텁텁한 느낌 나는 푸딩들이 많아서 크게 기대 안 했는데 너무 맛있었어요 ㅎㅎ 소다류 음료도 잘 안 마시는데 아이스크림이랑 잘 어울려서 너무 좋았어요 👀 분위기가 너무 좋아서 담에 친구들이랑 올 일 있으면 또 오고 싶어욤', 29, 7, 'GOOD', SYSTIMESTAMP);
