INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '너무 맛있습니다 우선 커스터드 푸딩은 살짝 고소한데 카라멜 시럽같은 저 아래 깔려있는게 달달해서 맛있고 초코푸딩은 무스같은 느낌이라 좋아요 .ᐟ .ᐟ 그리고 메론소다는 소다만 먹으면 진짜진짜 맛있고 아이스크림 살짝 녹인 상태로 먹으면 적당히 부드럽고 달달해서 좋아요  대신 너무 많이 녹이면 메론맛이 너무 없어지니까 주의하세요! 총 5테이블에 바 테이블 1개 4자리 있고 생각보다 빠르게 자리가 나와요! 다시 올 의향 1000000000000% 있습니다 매우 만족 ‎𐔌ᵔ ܸ>⩊< ͡ 𐦯ᡣ𐭩‎', 8, 0, 'GOOD', SYSTIMESTAMP);
