INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '친구 생일이라 홍대 푸딩 카페로 유명한 모코모코 왔어요! 인테리어가 진짜 너무 귀엽고 예뻐서 특별한 날에 오기 너무 좋더라구요 ㅠㅠ 캐모마일티도 마녔는데 차 향도 너무 좋구 맛있었어요 다음에는 푸딩 먹으러 재방문할거예요 ♡♡ 사진은 너무 귀여운 인테리어~', 41, 3, 'GOOD', SYSTIMESTAMP);
