INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '홍대 갈때마다 이 카페 가보고 싶었는데 평일이라 그런지 빈자리가 있어서 들어왔습니다ㅎㅎ 푸딩이랑 밀크티 시켰는데 둘다 너무 귀여워요..☺️ 말차맛이라 너무 달지 않아서 맛있었습니다!', 128, 25, 'GOOD', SYSTIMESTAMP);
