INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '모코모코 카페는 인테리어부터 눈이~~ 확~~가요 인테리어도 아기자기 너무 이쁘고 무엇보다 디저트가 너무 귀여워요😍 푸딩이 몽실몽실 귀엽고 부드럽고 맛나네요 푸딩도 소다도 존맛이에요', 30, 2, 'GOOD', SYSTIMESTAMP);
