INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '홍대에 놀러온 기념으로 들린 카페! 외관부터 너무 귀여운 카페입니다. 곳곳에 푸딩이 장식되어 있어서 너무 귀여워요 달달 시원한 메론소다를 즐길수 있다니 너무 좋아요', 10, 8, 'GOOD', SYSTIMESTAMP);
