INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '점심먹고 디저트 먹으러 갈 곳을 찾다가 외관에서부터 귀여움이 뿜뿜 끌려서 들어왔어요 ㅎㅎ 귀염뽀짝한 푸딩메뉴와 소다먹었는데 비주얼도 좋고 맛도 좋고 사진을 안찍을 수 없네요 다음에 또 올게요', 44, 7, 'GOOD', SYSTIMESTAMP);
