INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '서울 홍대 푸딩 맛집 입니다 가게가 너무 아기자기 하고 이뻐요 포장만 하다가 먹고 가봤는데 먹고가면 이런 귀여운 데코가 올라온답니다❤️❤️ 이런 이쁜 카페를 찾아서 너무 기분이 좋네요 빨리 쿠폰 다 모으고 싶어요 히힣', 78, 17, 'GOOD', SYSTIMESTAMP);
