INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '홍대에 놀러왔다가 푸딩이 먹고싶어서 점찍어둔 가게에 방문해봤어요~ 푸딩에 올라간 곰모양 크림이 정말정말 귀여웠어요. 초코는 달긴한데 딱 생각했던 단 맛이라 커피랑 잘 어울렸습니다 ^_^ 가게에 자리가 많진 않지만 다음에도 귀여운 카페에 가고싶으면 찾아올 것 같습니다 💕', 25, 3, 'GOOD', SYSTIMESTAMP);
