INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '홍대 푸딩 맛집이라고 해서 밥 먹고 왔어요!! 카페 인테리어가 너무 아기자기하구🥹 푸딩이 너무 달지도 밍밍하지도 않고 딱 좋아요👍👍 또 올 예정이에요 히히', 51, 18, 'GOOD', SYSTIMESTAMP);
