INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '홍대에 볼 일이 있어서 왔다가 편하게 앉아있을 곳 찾다가 발견한 카페였어요. 바깥에서 본 푸딩들 이미지가 귀여워서 끌리듯 들어갔습니다. 매장 내 테이블 수가 적어서 살짝 대기했지만 오래는 안 기다렸고, 나오는 것도 꽤 빠르게 나왔습니다. 푸딩 정말 맛있습니다. 말차랑 커스터드 시켰는데 개인적 취향으론 말차가 더 취향이었습니다만 둘 다 맛있었네요ㅎㅎ 다음에도 또 올 것 같아요.', 55, 11, 'GOOD', SYSTIMESTAMP);
