INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '리뷰는 처음 쓰지만 정말 좋아하는 홍대 푸딩 카페 첫방문때는 테이크아웃을 하지 않아도 병푸딩이었는데 이제 매장 푸딩은 곰인형이 되어서 귀여워요', 73, 14, NULL, SYSTIMESTAMP);
