INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '항상 만석이라 못간 홍대 카페였는데 오늘 사람이 없어서 들어갔어요 카페 너무 아기자기하고 이쁘고 블루소다도 맛있어요 우유푸딩 ㄹㅈㄷ 맛있어요 😁😁😁😁', 36, 6, 'GOOD', SYSTIMESTAMP);
