INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '푸딩 맛집으로 유명한 모코모코 다녀왔어용 초코푸딩은 진짜 찌~~인한 초코였는데 너무 제스타일이였어요 발로나초콜릿으로 만든 시럽이라 그런지 쫀득함도 좋더라구요 우유 푸딩도 비린맛 없고 위에 올라간 크림마저도 맛있네요', 11, 9, 'GOOD', SYSTIMESTAMP);
