INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모코모코'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '부드러운 푸딩이 맛있는곳!! 입에 넣자마자 사르르 녹는데요 이렇게 제대로 된 푸딩은 먹어본적이 없는것 같아요 그래고 메론소다도 시원하고 맛있는데요 디저트로 이만한거 없어요', 16, 7, 'GOOD', SYSTIMESTAMP);
