INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '몰리스피크닉'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '윤두준 생카로 다녀왔는데 공간도 넓고 쾌적하고 좋습니다! 사장님도 친절하시고 밀크티랑 초코라떼도 맛있습니다~!! 버터쿠키도 먹었는데 부드럽고 맛있었습니다! 그리고 구석구석 이쁘게 꾸며놔서 힐링하고왔습니다~♡', 39, 0, 'GOOD', SYSTIMESTAMP);
