INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '몰리스피크닉'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '아이유 생카로 다녀왔어요. 가게 생각보다 넓고 쾌적했구요. 전시 컨셉도 너무 좋고 볼거리가 풍부해서 좋았어요ㅎ 디저트 세트 마카롱, 쿠키 왤케 귀여운지ㅠ 먹기 아까울 정도였네요~ 럭드도 하고 싶었으나 빠른 마감 이슈로 해보지 못해 아쉽긴하지만...🥹 생카중 거의 탑티어급 전시였어요👍', 40, 3, 'GOOD', SYSTIMESTAMP);
