INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '몰리스피크닉'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '이벤트 카페 다녀왔어요~ 카페 내부가 넓어서 한 쪽은 전시회처럼 꾸며져 있었는데 다양한 사진들을 볼 수 있어서 좋았습니다! 음료랑 디져트도 기대보다 훨씬 맛있어서 좋았어요!!', 5, 8, 'GOOD', SYSTIMESTAMP);
