INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '몰리스피크닉'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '이벤트 때문에 방문한 카페라 음료나 디저트 맛은 그다지 생각하지 않았는데 커피, 밀크티, 초코라떼 다 맛있어서 다음엔 그냥 가보고 싶어요. 내부 인테리어도 예뻐서 좋았습니다.', 50, 4, 'GOOD', SYSTIMESTAMP);
