INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '와플대학 홍대캠퍼스'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '홍대에 오면 꼭 들리는 와플대학! 이전을 해서 미쏘 매장 안쪽에 들어와야 있더라고요 언제나 맛있는 와플대학이지만 전과달리 왜 반죽 안데워주시는거죠.. 갓데운 따뜻한 와플 먹고싶어서 오는건데 이번엔 좀 아쉽네요ㅜㅜ', 20, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '와플대학 홍대캠퍼스'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '개인적으로 아이스크림와플은 아이스크림이 좀 단단해야 덜 느끼하고 먹기 편한데 아이스크림이 이렇게 녹아서 나온 지점은 처음이에요 입에서 물자마자 아이스크림이 녹아서 뚝뚝 떨어지고 먹는 내내 너무 불편했어요', 1, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '와플대학 홍대캠퍼스'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '주문기게가 아마 고장나서 영수증 안 나왔는데 직원에게 와이파이 비번 물었더니 영수증으로 보라고 했다고ㅋㅋ영수증 안 나왔다고 했도 계속 불친절하게 영수증 보라고 하시네…말투와 표정이 되게 mean하고 심지어 눈을 희번덕거리기까지 했어요🙄 너무 기분 나빠서 너무 무서워서 다시 여기로 안 올거에요 ㅎㅎ(2025년 8월15일 오후5시-7시 사이 여자직원)', 73, 11, 'BAD', SYSTIMESTAMP);
