INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '와플대학 홍대캠퍼스'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '직원이 너무 불친절해요 매니저인비 직원인지 모르겠는데 윽박지르고 짜증내고;; 와플 먹으러와서 기분만 나빠져서 나갔어요 바쁜 건 알겠는데 왜 손님한테 짜증이신지 모르겠네요 다신 이용 안 할 것 같아요', 125, 22, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '와플대학 홍대캠퍼스'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '8월 14일 저녁에 방문했는데 매장 진짜 더럽고 직원도 불친절했어요. 들어가자마자 보이는 바닥에 냅킨 군데군데 떨어져 있었고 빈 테이블 위엔 아이스크림 자국 + 쓰다 남은 냅킨 있더라고요. 직원한테 테이블 좀 닦아달라고 요청했는데 자기네 지금 바쁘니까 물티슈 가져다가 알아서 닦으라고 해서 당황스러웠네요; 요청 당시 뒤에서 와플 먹고 있는 다른 직원도 있던데.. 손님한테 테이블 닦기 시키는 매장 첨봐요. 서비스 + 위생 별로여서 재방문 의사 없습니다.', 13, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '와플대학 홍대캠퍼스'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '커피사고 왔는데도 안나옵니다 . 주토피아 나무늘보 보는거 같아요 메뉴 레시피도 모르는거 같고 크림 잘못바르고 뭐지뭐지 하고있네요.. ㅋ 진짜 이렇게 늦게나오는거 첨봤어요 , 한국인데 미국에 온거 같네요.', 114, 25, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '합정동 커피 맛집으로 유명한 커피폴리에 다녀왔어요. 굉장히 다양한 소금빵이 있었고 여기는 무슨 아지트처럼 손님이 굉장히 많은 특별한 카페였습니다. 분위기가 자유롭고 힙해서 한 번쯤 가볼만한 합정역 근처 카페에요', 13, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '소금빵 종류가 미쳤어요 홍대 합정 베이커리 통틀어서 소금빵 종류 제일 많고 크기도 커요!!! 아무생각 없이 들어간곳인데 소금빵맛집을 찾을줄이야 ㅠㅠ 합정역에서 10초면 걸어올 위치인데 이렇게 맛있는 곳이 숨어있었다니!! 에그베이컨소금빵은 식사대용으로도 충분히 포만감이 느껴지고 무엇보다도 크렘뷔렐레가 대박.. 소금빵이 너무 커서 세개 담으니 휘낭시에 배는 남아있지 않았지만 다음번엔 휘낭시에 털러올거에요!!!! 합정 베이커리나 서교동카페 찾는다면 꼭 커피폴리 가보세요!!!', 31, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '분위기도 좋고 커피맛이 좋아요. 플랫화이트가 우유가 플랫하게 들어가서 진한 커피맛을 즐길 수 있어 좋고 소금빵, 특히 갈릭치즈소금빵과 잘어울려요. 커피맛도 좋지만 달달한 디저트도 맛있어요. 특히 소금빵 맛집이라 음료와 함께 먹으면 단짠 조합이 좋아요.', 86, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '케일 파인애플 주스는 상큼하면서 프레쉬해서 아침이나 점심과 잘 어울리는 주스였어요. 고구마 소금빵은 겉은 바삭 쫄깃하고 속은 촉촉하면서 적당하고 부드러운 고구마 앙금이매력적인 음료였어요 피넛 버터 초코칩 쿠키는 바삭 부드러운 땅콩 쿠키에 초코가 콕콕 박혀서 당충전에 완벽한 쿠키였어요! 딥초코 휘낭시에 는 겉은 바삭 속은 촉촉 쫀득한 리얼 초코 휘낭시에 였어요.', 87, 17, 'GOOD', SYSTIMESTAMP);
