INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '합정역 카페로 검색해서 소금빵이 유명하다는 커피폴리 방문했습니다. 듣던대로 소금빵 천국이었구요, 베이지 소금빵 아쥬 고소하고, 크림브륄레 소금빵의 크림은 예술이었습니다. 돌체라떼, 아프리칸 루이보스 티 맛있게 잘마셨어요. 내부도 인테리어가 이쁘고 아기자기한 소품들도 많아서 좋았어요.😊👍☕️🥖', 42, 10, 'GOOD', SYSTIMESTAMP);
