INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '합정에서 분위기 좋은 카페를 찾다가 카페폴리에 다녀왔어요! 내부가 아늑하고 편안했어요. 커피 맛도 진하면서 밸런스가 좋아 만족스러웠습니다. 디저트도 깔끔하게 준비되어 있어서 함께 즐기기 좋았어요. 홍대, 합정에 오면 또 들르고 싶은 카페예요! 💛', 65, 12, 'GOOD', SYSTIMESTAMP);
