INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '카페가 생각보다 크고 분위기 좋아요. 원두, 커피, 음료 메뉴 등등 베이커리 종류 다양해서 좋아요. 호주식 디저트, 커피를 제대로 즐길 수 있어서 누구랑 오든 좋은 시간 보낼 수 있을 거 같아요. 메뉴 하나하나 비주얼 다 예쁨!! 커피는 디카페인으로 했는데 향긋하고 깔끔해요. 레밍턴 케이크도 많이 안달고 맛있어요! 다음에 또 오고싶어요.', 19, 8, 'GOOD', SYSTIMESTAMP);
