INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '호주식 커피 맛보고 싶었는데 정말 진하고 맛있었어요.♡ 분위기도 아늑하니 좋구요!  갈릭크림치즈 소금빵과 고구마 소금빵 적당히 달달하고 버터리하고 고소해서 막 들어가요 ㅎㅎ 합정역에서 친구만나 좋은 시간 보냈어요 ㅎㅎ 또오고싶어요!!!♡', 12, 6, 'GOOD', SYSTIMESTAMP);
