INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '원두가 여러종류 있어서 좋구 통창에 채광이 드는데 너무 느좋.. 합정에 이런데있는거 첨 알았는데 너무 좋아요 ㅎㅎ 데이트하기도 과제하기도 딱이라 또 올것같아요! 케이크 강츄,,,, 촉촉하니 너무 맛납니다!', 18, 10, 'GOOD', SYSTIMESTAMP);
