INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '이미 알만한 사람들은 다 아는 카페폴리.. 오랫만에 갔더니 메뉴가 더 많아진 느낌이었어요. 특별한 맛들이 많은데 다 많있고 베이글도 쫀쫀하고 맛있고 레몬딜 크림치즈 너무 상큼하고 맛있더라고요. 샌드위치도 진짜 맛있어요. 1,2층이라 자리는 은근 있는 편입니다.', 13, 0, 'GOOD', SYSTIMESTAMP);
