INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '유서 깊은 플랫화이트 맛집이에요 !! 원두 종류도 많고 이제는 베이커리 종류도 다양해서 고르는 즐거움이 있어요 !! 언제나 맛있는 커피에 차분한 분위기까지 좋아요 !!', 4, 8, 'GOOD', SYSTIMESTAMP);
