INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '복층으로 되어있고 음악이 흐르는 공간! 사장님도 친절하고 카페 분위기도 좋고 커피와 소금빵이 맛있어요~ 영수증 리뷰이벤트도 넘 좋아요~', 4, 3, 'GOOD', SYSTIMESTAMP);
