INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '커피맛집찾다가  발견한곳 💙카페폴리💚  외관부터 감성충만카페💜빵종류도 다양하고 커피도 직접 로스팅 믿고먹는카페🥰  소금빵 플랫화이트    베라자몽 주문 베라자몽 씹히는아삭한자몽  달지않고 건강한맛😍소금빵도 사장님께서 정성껏 데워주시는 센스😂😂플랫화이트 는 진하고고소한맛  진짜의커피맛😂💜 완전 힐링 되네요ㆍ합정역2번출구  도보3분거리  딱   좋은것같아요ㆍ 커피를 좋아하시는분들은  꼭 오실것같아요ㆍ사장님두 친절하세요ㆍ1증2층 되어있어서 좋으네요ㆍ2층은 뷰가 더좋아요🥰🥰🥰', 50, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '합정역 인근 골목으로 들어오면 유리벽으로 되어있는 카페입니다. 직접 로스팅도하시고 빵도 구우시는 곳이라그런지 배달주문도 많은것 같아요. 토요일 1시경 방문했는데 자리는 충분했고 2층까지있어요! 음악소리가 큰편이라서 저는 1층에 앉았어요. 커피는 직접 로스팅하셔서 그런지 흔하지않은 약간의 신맛이었는데 특별하게 먹기 좋았어요! 에스프레소가 우유를 타고내려오는 디테일이 사진찍기딱입니다ㅋ', 19, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '커피 마시러 갔다가 그냥 생각없이 추가한 샌드위치가 너무 맛있어서 기절. 바질치킨? 뭐 그런거였는데 빵 쪼온득하고 속 푸짐하고 소스도 맛있고.. 이건 무조건 또 먹으러 가려고요. 그리고 두유변경 디카페인변경 다 가능해서 너무너무 좋아요!!!! 두유라떼 너무 맛나게 잘 해주심.', 86, 11, 'GOOD', SYSTIMESTAMP);
