INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '베이커리종류가 엄~청 다양하고 커피도 맛있어요! 원두도 4가지중에 선택하는 거여서 더욱 다양하게 즐길 수 있었습니당👍🏻 합정 카페로 추천드려요!', 94, 26, 'GOOD', SYSTIMESTAMP);
