INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '전에 샌드위치 너무 맛있어서 또먹음. 푸짐하고 바질소스? 가 아주 맛있어요. 디카페인 커피도 맛있어요. 소금빵은 파사삭 스타일.', 16, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '커피도 맛있고 빵도 맛있고 종류많아서 빵순이 천국!! 배달도 많더라구요.. 빵자체가 맛있는 베이커리 카페!! 레밍턴 케이크랑 플랫화이트 강추합니다♥️ 호주식이라구 하는데 실제로 외국인 손님 많더라구요! 완전 강츄', 9, 0, 'GOOD', SYSTIMESTAMP);
