INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '주말 아침에 방문했어요!! 커피도 맛있고 디저트류 종류도 많아서 아침먹으러 오기도 좋은 거 같아요^^사장님도 친절하시고 분위기도 좋아서 자주 올 것 같네요:)!!', 47, 9, 'GOOD', SYSTIMESTAMP);
