INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '근처 약속 전에 너무 배가 고파서 들어온 합정동 카페 갓 구운 빵들이 엄청 많았고 소금빵으로 유명한 집이더라구요 그래서 베이글이랑 소금빵 담아서 아침먹고, 커피도 너무 맛있어서 거래처분들 커피 사들고 갔어요 다들 여기 카페 자주 간다고 베이글 꼭 먹어보라고 추천도 받은 카페맛집! 아침일찍열어서 아침사들고 출근하는 분들도 많으시더라구요 합정역 근처 약속 있을때 머무르기 좋더라구요 2층까지 있어서 작업하기도 너무 좋았습니다', 32, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
