INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '수박, 망고 스무디 둘 다 진짜 과일 맛 그대로라 상큼하게 잘 넘어감. 아몬드 크로와상은 겉은 바삭, 안은 촉촉해서 식감 좋았고, 고소한 맛도 괜찮았음. 카스테라 소금빵은 달달하면서 부드러워서 커피 없이도 먹기 좋았고. 전체적으로 양도 괜찮고 분위기도 조용해서 편하게 먹고 나옴. 혼자 와도 좋고, 사람 많지 않을 때 오면 더 좋아 보여요!!', 53, 18, 'GOOD', SYSTIMESTAMP);
