INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '단골된지 1년 됐는데 여긴 진짜 우리나라에서 가장 맛있는 커피와 소금빵을 판매합니다 (진심 개쩜) 사장님 항상 친절하시고 맛있는 음료도 추천 많이해주시고 빵도 서비스로 자주 주시고 ㅋㅋㅋ 항상 감사합니다 ㅠㅠㅠ 오늘도 소금빵 서비스 너무 감사합니다 ❤️❤️', 6, 7, 'GOOD', SYSTIMESTAMP);
