INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '조용한 오후, 분위기 좋은 로컬 카페에서 잠시 여유를 즐겼어요. 고풍스러운 의자와 따스한 조명이 어우러진 공간은 마치 시간이 천천히 흐르는 듯한 느낌을 줍니다. 전체적으로 조용히 이야기 나누기 좋은 분위기, 정성스러운 음료와 디저트가 만족스러웠습니다.', 23, 10, 'GOOD', SYSTIMESTAMP);
