INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '커피부터 베이커리류까지 전부 맛있는 카페인데다가 노래랑 분위기까지 넘 좋은 곳이라 추천드려요!! 플랫화이트 커피 완전 고소하고 같이 먹은 앙버터 소금빵이랑 레밍턴케이크도 커피랑 잘 어울려서 사촌언니랑 맛나게 먹고 갑니다♡', 4, 10, 'GOOD', SYSTIMESTAMP);
