INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '올때마다 기분 좋아지는 곳이예요. 맛있는 베이글과 소금빵은 물론, 크루아상과 레밍턴케이크까지. 늘 만족하고 갑니다. 근처에 들러서 포장하고 가며 리뷰 남깁니다. 꼭 한번 들러보세요.', 28, 3, 'GOOD', SYSTIMESTAMP);
