INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '플랫화이트가 맛있는 합정카페네요 겉바속촉 소금빵도 맛있구요 스콘에 베이글 브라우니 샌드위치까지 베이커리가 다양해서 넘 좋네요 1~2층 단독 건물에 분위기 맛집이라 데이트 모임 하기도 좋아요 커피 베이커리 맛집에 여름 메뉴 수박주스도 넘 맛난 합정카페 단골 될것같아요ㅎ', 6, 9, 'GOOD', SYSTIMESTAMP);
