INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '디카페인 커피도 있고 맛나요 ^^ 소금빵 맛집 ~~~♡♡ 감태랑 크림브륄레 소금빵도 있어 다양한 빵을 맛나게 맛볼 수 있어요 ~채광도 좋구요 ♡😚추천!!! 그리고 합정역과 가까워요 *', 21, 10, 'GOOD', SYSTIMESTAMP);
