INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '분위기가 너무 좋아보여서 들렸는데 오기잘한것 같아요! 커피도 달달하고 맛있고 에이드도 짱입니당! 소금빵도 종류가 어찌나 다양한지 다 먹고 싶을 정도예요~~ 합정에 이쁜카페 찾으면 강추드립니다💕💕', 21, 2, 'GOOD', SYSTIMESTAMP);
