INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '홍대놀러왔다가 우연히발견한곳. . . 코코넛크림커피 맛있네. . 애플파이도 맛있어!! 달달한게 땡기는날엔 커피폴리와야게씀!! 맛있게 잘먹고갑니당~또올게용 ㅋ.ㅋ 분위기는 약간 자유분방한 앤틱? 스타일이라고해야하나. . 빈티지한 느낌의 카페입니당 ^^ #홍대카페#합정카페맛집#홍대가볼만한곳#합정가볼만한곳#합정커피폴리#커피폴리#디저트맛집#홍대빵맛있는곳#합정빵맛있는곳#합정코코넛크림커피', 19, 8, 'GOOD', SYSTIMESTAMP);
