INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '오늘 날이 즇아서 사진이 더욱 잘 나왔는데 2층에 넓은 좌석이 편했고 들어가자마자 다양한 소금빵이 너무 맛있어 보였어요! 원두도 다양해서 원하는 향이나 맛을 이야기하면 추천해주고 좋아요. 아이스크림라떼랑 피넛크림라떼릉 추천받았는데 헤이즐넛향과 부드러운 바닐라아이스크림이 잘 어울려서 완전 좋았어요! 강추!', 75, 14, 'GOOD', SYSTIMESTAMP);
