INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '음료 두잔씩 마시고 쿠키에 휘낭시에까지 2차 식사 했어요 ㅎㅎ 음료가 많이 달지 않은것도 좋았고 개인적으로 디카페인이 있어서 좋았습니다. 베이커리 종류도 다양하고 바틀포장된 음료도 있어서 테이크아웃하기에도 좋네요.', 61, 11, 'GOOD', SYSTIMESTAMP);
