INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '합정역 근처에 외국 분위기 물씬나는 감성 카페 ☕️ 테라스가 있어 선선한 날 오기 너무 좋고 내부 좌석도 많고 창가 자리도 있어요 :) 커피폴리 시그니처 메뉴답게 플랫화이트랑 호주 디저트 레밍턴이 맛도리였어요! 소금빵이 빠쟉하고 베이커리 종류가 다양한데 진짜 다 맛있어보여서 왕창 담음 😋 원두도 판매하시는데 커피가 진짜 향이 좋고 맛나요 커피 꼭 드셔보세용 샌드위치, 잼, 주스, 크림치즈 등도 판매하니 베이커리 겸 카페 느낌이라 합정/망원 사시는 분들은 꼭 방문해보세용 강추!!', 91, 20, 'GOOD', SYSTIMESTAMP);
