INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '라떼 커핑향이 정말 좋네요~ 분위도 좋고 커피와 빵 모두 맛있어서 즐거운 시간 이였습니다. 합정역에 놀러오면 다시 오고싶은 카페입니다. 음악 선곡도 넘 좋아서 커피마시면서 편안하게 쉬기 좋은 곳입니다~^^', 19, 8, 'GOOD', SYSTIMESTAMP);
