INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '지나가다가 들린 카페 케일 파인애플쥬스 6,500원 수박쥬스 6,500원 케일 파인애플쥬스가 진짜 맛있어서 집에 400리터정도 사두고싶음 뭔가 해독쥬스 색인데 맛은 날 미치게 만들었음', 37, 0, 'GOOD', SYSTIMESTAMP);
