INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '합정역의 감도 높은 카페를 찾는 분들께 추천⬇️🔥 . 노트북 작업하려고 들른 곳인데 메뉴도 다양하고 무엇보다 쌉쌀한 커피 맛이 너무너무 매력적입니다! 공원 앞이라 풍경도 초록초록하네용ㅎㅎ 음향도 너무 좋아용(대화하기도 편한 정도!) 혼자든 친구들이랑이든 다시 오고 싶은 곳입니다 짱 추천!!', 35, 1, 'GOOD', SYSTIMESTAMP);
