INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '출근 때 오느라 맨날 테이크 아웃이지만 매번 활기찬 직원들에 폭룡적인 베이커리 비쥬얼에 놀라고 간답니다ㅠㅠ 디저트도 디저트인데 커피 정말 잘 하니까 들러보세용~ 참고로 테이크 아윳은 천원 할인!!', 59, 17, 'GOOD', SYSTIMESTAMP);
