INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '트레이 닦지도 않고 다른사람이 흘린 커피 그대로, 빵가루 그대로 거기에 일하는 여자분 불친절함은 덤 친절이라도 했으면 넘어갔을텐데 바쁘지도 않은시간 손님한테 음료나갈때 트레이 한번 닦고 나가는게 그렇게 어렵나요? 기본이 안되있는 불친절한 안경쓴 여자분 덕분에 기분만 나빴네요 직원교육 시키시길.', 9, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '와 명란 소금빵 아침에 사먹고 미쳤다 (positive) 했습니다 봄햇살에 잘 어울리는 소금빵 잘 먹었습니다 매장 분위기도 좋고 소금빵 종류 다양해서 다음엔 고구마 소금빵 먹어보러 올게요', 31, 6, 'GOOD', SYSTIMESTAMP);
