INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '베이글 종류도 짱 많고 스콘, 파이도 있어서 행복한 고민 가득… ♡ ⁼³₌₃ 당근라페 샌드위치는 처음인데 진짜진짜 맛도리..ㅜㅜ', 106, 24, 'GOOD', SYSTIMESTAMP);
