INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '녹차쿠키만 보고 왔는데 다른 종류들도 많고 맛있어보이더라구요?! 테라스와 2층까지 좌석이 있어서 넓었어요 ! 쿠키는 약간 오래된 맛이 나서 아쉬웠는데 다음에 다시 먹어봐야겠어요ㅜ 다른 메뉴와함께 커피는 맛있게 잘마셨고 엔틱한느낌이 있어요 화장실도 내부에 있어서 좋더라구요ㅎㅎ 담에 다시 방문해보기🙂🙂', 37, 7, 'GOOD', SYSTIMESTAMP);
