INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '처음 방문했는데 너무 맛있어서 또 오려고요. 특히 앙버터 소금빵 미쳤어요. 집 앞이면 매일 와서 사먹고 싶을 정도입니다. 커피, 디저트 다 잘하는 곳 찾기 쉽지 않은데 둘 다 진심으로 맛있어요. 합정 카페는 카페 폴리!! 🩶🩶', 17, 0, 'GOOD', SYSTIMESTAMP);
