INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '합정왔다가 맛있는빵 먹고싶어서 들렸는데 좐맛이에요,,, 먹고싶은빵 너무많아서 렉걸리듯 멍때리다가 고민끝에 맛없없 크림브륄레 소금빵으로 골랐는데 안에 크림이 터져나와요ㅠㅠㅜㅠ진짜미친맛임.. 여기 또올꺼에요', 44, 6, 'GOOD', SYSTIMESTAMP);
