INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '코코넛 크림 라떼 시켰는데 달달하니 맛있어요!! 빵 종류가 많아서 빵순이인 저한테는 행복을 주는곳 ㅎㅎㅎㅎ 햇살이 잘 들어오는 창가에 앉아서 이야기하기에 너무 좋습니다!', 15, 1, 'GOOD', SYSTIMESTAMP);
