INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '지인 추천으로 방문하게 되었는데 좋네요. 감사 선물드리고자  드립백 구매했는데 포장까지 해주시고 만족합니다. 커피 맛있다고 하니 기대됩니다!', 4, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '카페가 엄청 크고 넓어요:) 2층 분위기 너무 좋고 아늑한 분위기라 노트북이나 공부하시는분들도 많구 대화하기에도 좋아요 플랫화이트 커피 추천😋', 7, 4, 'GOOD', SYSTIMESTAMP);
