INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '호주식 디저트 레밍턴을 만날수 잇는곳 시크한듯 하지만 알고보면 넘 친절하고 인심좋은 사장님 ㅎㅎ 인테리어도 참 멋지고 통창에 햇살받으며 힐링하기 좋은 곳이애요', 7, 8, 'GOOD', SYSTIMESTAMP);
