INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '자주 오는 동네 카페입니다! 디저트 종류가 다양한데 가격도 저렴해요. 커피 맛도 진짜 좋습니다.. 아메리카노도 맛있지만 플랫화이트도 좋아하는 메뉴에요! 합정 근방 카페 중에 가장 좋아하는 곳입니다☕️🤎', 9, 4, 'GOOD', SYSTIMESTAMP);
