INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '좋은 음악과 편안한 공간. 늦은 시간에 방문해 커피가 조금 부담스러웠는데 생과일 주스 종류가 많아서 좋았어요. 케일 파인애플 주스 상큼하고 맛있어요!', 3, 5, 'GOOD', SYSTIMESTAMP);
