INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '인테리어부터 조용한 대화를 나눌수 있는 공간까지.  합정오면 꼭 들리고 싶은 곳입니다. 사장님들께서도 친절하셔서! 이곳에 오면 후회없이 시간 보낼 수 있다는 믿음이!! 잘 마시고 갑니다!!', 18, 9, 'GOOD', SYSTIMESTAMP);
