INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '직장동료들과 함께 나눠먹기위해 검색 후 방문했어요 . 사진은 먹고나서 찍어섴ㅋㅋㅋㅋ빵 바닥난거 사진 .. 사람들이 어디서 사왔냐고 커피와 빵 다 너무 맛있다시네요 ,, 🤍🫧또오고싶어서 저장해놨어요 > = < 흥하셍ㅎ !', 13, 7, 'GOOD', SYSTIMESTAMP);
