INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '시즈널 원두를 이용했고 설명대로 딸기맛이 느껴지는 산미있는 원두였어요. 개인적으로 산미원두도 잘 마셔서 좋았습니다. 창가 자리에 노트북 이용 가능한 자리가 따로 있어 노트북이용하기에도 좋을 것 같아요', 35, 6, 'GOOD', SYSTIMESTAMP);
