INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '플랫화이트가 맛있다고 해서 방문해봤어요. 플랫화이트 맛있어요. 베이글도 데워주셨는데 겉바속촉이라 좋아요. 다만 머리 탈색하신 여자 직원분 너무 불친절하셔서 친구나 저나 둘 다 기분 나쁘고 어이 없었어요.', 39, 5, 'BAD', SYSTIMESTAMP);
