INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '커피도 맛있는데 소금빵이랑 베이글 찐맛집! 배달도 엄청 많더라고요. 주문많아서 정신없는데 직원분들 모두 친절~ 재방문하고싶은곳이에요. 🥯🥖🥪', 34, 1, 'GOOD', SYSTIMESTAMP);
