INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '커피폴리 좋아해서 자주 이용하는데요! 디저트는 늘 맛있는데, 커피는 만들어주시는 분에 따라 맛의 편차가 큽니다 ㅠㅠ 안경쓴 남자분이 만들어주시는 커피는 고소하고 부드러워서 믿고 마시는데, 다른 분들이 만들어주신 커피는 탄 맛 쓴 맛이 심해서 한 잔을 다 못마실 정도예요.. 함께 가는 일행도 갈 때마다 똑같이 느낀다고 합니다. 컴플레인이 달갑지는 않으시겠지만, 이 부분만 개선되면 더할 나위 없이 좋겠다는 바람을 담아 리뷰 적었습니다!', 34, 2, 'BAD', SYSTIMESTAMP);
