INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '배달로 많이 시켜 먹던 카페인데 고구마 소금빵 메뉴가 있어서 정말 많이 들러요..!! 일반 소금빵도 맛있고 음료도 맛있습니다,,(특히 트로피칼 어쩌구 스무디최애)직접 들르면 카페 분위기도 좋아유', 38, 5, 'GOOD', SYSTIMESTAMP);
