INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '사장님이 친절하시고 아침 8시에 방문했더니 빵을 굽고 있어서 갓구운 빵을 뜨끈하게 먹을 수 있어서 좋았어요 테라스에 애견도 가능해서 산책올겸 브런치 조앗습니다👍', 9, 0, 'GOOD', SYSTIMESTAMP);
