INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '근처 살때 못해도 일주일은 1-2번씩 오던 카페인데 커피랑 스콘류가 너무 맛있어요! 종종 합정 올 일 있을때마다 커피 캔바틀로도 구입해서 가고 있어요. 못온 새에 베이커리류가 많이 늘어서 더 좋네요 💗', 52, 14, 'GOOD', SYSTIMESTAMP);
