INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '커피맛집 이여서 자주 들르는 곳이예요. 최애는 카페 라떼. 디저트도 다양하게 있어서 골라 먹는 재미도 있어요. 2층에 테이블 모양도 다양하고 채광이 좋아서 자주 들러서 일하기도 한답니다. 추천해요!', 10, 7, 'GOOD', SYSTIMESTAMP);
