INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '교회가기전에  커피한잔 !! 항상 맛나고 인테리어 감성이 완전 제취향이예요 매번 시즌 마다 바뀌는 컵 홀더도 완전 센스짱이어요 !!', 34, 5, 'GOOD', SYSTIMESTAMP);
