INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '우연하게 들어온 카페인데 분위기도 좋고 커피도 다양하고 베이커리도 다양하고 맛도 너무 좋아요!! 좋아하는 사람들이랑 또 오고 싶은 카페입니자ㅜ 분위기도 너무 좋아요ㅠㅠ', 41, 0, 'GOOD', SYSTIMESTAMP);
