INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '대처가 너무 별로임. 왼쪽의 멜버른 디저트라는 빵을 주문했는데 상한 상태였습니다. 먹는데 너무 발효?된 술 맛이 심해서 혹시 몰라 여쭤보니 상한게 맞았습니다. 당연히 전액 환불은 받았으나 대처가 그 뿐이라 한 입을 크게 먹었는데 그 이후 배탈 나면 어떻게 하냐 라는 질문에 그제서야 그럼 연락달라고 하더라고요. 보통 먼저 이 얘기를 해주셔야하지 않나요? 기분도 너무 찝찝하고 더 있고 싶지 않아 카페에서 나오는데 확인해보니 저 디저트 아직 안 치우고 그대로 판매중이네요. 오늘 날씨가 더운 여름이면 어느정도 이해가 갈 수는 있어도 3월 초의 날씨에 이렇다면 언제 만든지도 의심이 가네요.', 389, 68, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '지인이 맛있다고 해서 찾아갔어요 저녁시간이라 거기서 마시진 못했고 캔포장이 되서 집으로 가져올 수 있네요 (굿) 오! 원래 라떼 잘 안 마시는데 라떼 찐~하고 맛있네요 근데 추워서 아이스는 아직 무리였습니다...ヽ(；▽；)ノ', 46, 7, 'GOOD', SYSTIMESTAMP);
