INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '여자친구와 함께 합정역 근처 카페 커피폴리에 왔는데요, 분위기도 좋고 사진찍기에도 너무 좋더라구요! 소금빵, 뺑오쇼콜라 특히 넘 맛있었어요😍', 19, 9, 'GOOD', SYSTIMESTAMP);
