INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '배달해보려고 추가해둔곳인데 근처 올일이 있어 매장 들렸습니다 ㅎㅎ 빵종류도 엄청 많구 커피 ,음료종류도 다양해요 !! 호주를 너무 좋아하는데 호주식이라니 다른 커피랑 빵들도 먹아보러 또 오겠습니다 .', 73, 16, 'GOOD', SYSTIMESTAMP);
