INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '항상 들르는 저의 합정동 방앗간. 커피 신맛이 없고 너무 맛있어요. 디저트도 다양하게 있고 2층에 자리도 많어서 자주 이용해요! 추천합니다. :)', 52, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '합정역 근처 베이커리 카페 찾다가 빵 종류가 많고 분위기도 좋아보여서 방문했어요 빵 종류도 맛있고 커피도 맛있네요~ 마침 저희가 방문한 날 눈까지 내려서 카페에서 흘러나오는 음악과 어우러져 분위기가 너무 좋았어요 주차도 가능하니 참고하세용', 82, 17, 'GOOD', SYSTIMESTAMP);
