INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '넘. 맛잇고 깔끔해영 디카페인 코코넛 강추에영 음악도 좋고 빵도 맛잇어영 친절한 사장님 감사합니다 홍대 커피 맛집 인정 입니당 적게 일하고 마니 버세영', 0, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '깊고 고소한 커피~~ 빵도 맛있고요 ^^ 분위기도 아늑해서 시간 가는줄 몰랐네요 ㅎㅎ 합정역 2번 출구 5분 거리에 있어서 찾아가기도 좋아요', 24, 4, 'GOOD', SYSTIMESTAMP);
