INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '가게가 아기자기하게 이쁘구 심지어 베이커리 가격 진짜 좋아요!대부분이 4500원대! 심지어 맛있어요ㅋㅋㅋ 이 근처 올때마다 가고싶습니다ㅋㅋㅋ 주말에 힐링하러 책보거나 공부할때 짱좋음', 88, 13, 'GOOD', SYSTIMESTAMP);
