INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '여러번 갔는데 커피는 맛있어요. 근데 정문 앞에 항상 꽁초가 널려 있는데 냄새 맡으며 안밟으려 피해서 들어가기 고역이네요. 왜 전혀 청소를 안하는지...가뜩이나 내부나 건물도 낡았는데 깔끔하게 관리하면 더 좋을거 같습니다', 44, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '책상에 먼지가 많고 전반적으로 위생 관리가 안된다고 느껴져서 별로였습니다.. 그리고 전반적인 메뉴들 금액이 비싼편이라 누가 비용 지불해주지 않는 이상 방문하지 않을 예정입니다.', 37, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '공부하러 와봤는데 1층은 1-2인이 사용하기 좋고 조용하고 콘센트가 있어 공부나 작업하기 딱이였고, 2층은 여러명이 와서 이용하기 좋게 공간분리가 잘되어 있어서 좋아용!👍🏻 커피랑 디저트도 맛있어서 또올 예정입니다~', 10, 1, 'GOOD', SYSTIMESTAMP);
