INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '커피를 좋아하는 대표가 운영하는 호주식카페. 아침에 2층에서 맛있는 모닝라떼와 잔잔한 좋은음악 듣기에 좋은 커피공간입니다 :) 하루 필요한 만큼만 정해진 시간에 커피를 직접 볶아 스몰배치한다고 합니다. 좋은 커피 맛을 즐길수 있어요!', 84, 11, 'GOOD', SYSTIMESTAMP);
