INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '빵이 너무 맛있어요💕 커피도 깔끔해서 넘 만족스럽습니다 ㅎㅎ 2층은 자리도 넓고 쾌적해서 수다떨기에도 좋고 혼자 작업하러 오기도 좋을 거 같아요 ㅎㅎ 강추드립니당☺️', 3, 8, 'GOOD', SYSTIMESTAMP);
