INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '풍부한 커피향과 안락한 분위기가 매력적인 카페입니다. 친구랑 작은 디저트 하나 시켜 수다떨기 좋은 장소. 들어오자마자 느껴지는 특유의 냄새가 좋아요 ㅎㅎ', 74, 17, 'GOOD', SYSTIMESTAMP);
