INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '아침 식사로 샌드위치 먹었는데 정말 너무 맛있었어요! 커피도 물론 맛있습니다! 가끔 가던 곳이라 오랜만에 가려고 카카오지도에서 찾았는데 없어져서 사라진 줄 알았어요ㅠㅠ 오래오래 있었으면 하는 곳입니다💛', 43, 3, 'GOOD', SYSTIMESTAMP);
