INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '오늘 커피를 두잔 마시게 되어 디카페인으로 마셨는데 매장에서 머그컵이 아닌, 일회용컵으로 쥐서 당황. 친구들 만나서 식사후 지나가다 들어갔는데 일욜 저녁시간이라 조용해서 좋았으나 매장이 뭔가 정리가 안되고 깔끔한 느낌이 안들어요 디저트는 버터프레첼은 생각보다 맛있었는데 블루베리크림치즈는 그닥..', 32, 5, NULL, SYSTIMESTAMP);
