INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '점심먹으러 방문했어요! 가게 앞에 바로 주차가능해서 편했고 커피에 진심인 커피폴리네요☕️ 빵도 직접 구우시는건지 다양하고 맛있어요 2층에 넓직한 공간까지 있어 혼자와도 좋을 것 같아요!', 49, 9, 'GOOD', SYSTIMESTAMP);
