INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '분위기도 좋고 빵도 커피도 다 맛있어요! 빵 먹을 생각은 없었는데 보니깐 너무 맛있어 보여서 먹었는데 절대 후회 안함요! 커피도 너무 맛있고 여기가 분위기 맛집이여서 혼자와도 같이 와도 시간 보내기 너무좋아요:)', 104, 26, 'GOOD', SYSTIMESTAMP);
