INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '차분한 분위기에 좋은 음향시스템에서 흘러나오는 잔잔한 음악이 함께하는, 반듯함 보다는 앤틱 한 편안함이 공존하는 카페 입니다. 주말오전 여유를 느끼고 싶다면 폴리카페 2층 창가자리 추천합니다. 소금빵과 맛있는 라떼 조합 추천.', 39, 8, 'GOOD', SYSTIMESTAMP);
