INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '가끔 친구만나러 합정에 가는데 처음 들어가본 집인데 포인트 적립 안하고 계산했다가 나가는길에 적립했어요…. 여기만 갈라구요… 카푸치노에 시나몬이랑 초코파우더 추가가능하냐 여쭤봤는데 해주셨어요…. 커피가 너무 맛있어요… 전 더운여름에 카푸치노 너무 좋더라구요', 119, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '매장은 이쁘고 디져트도 좋은데 커피는 쏘쏘 원두선택으로 고소한걸했는데 강배전으로 볶아서 그런지 고소함보다는 쓴맛이 더 강했음 참! 얼음컵 달라고 하니 얼음이 든 물이니 따라 마시라는 대응은 쫌 아닌것 같아요 정말 40대 후반 여성이 얼음물 달라고 하는건 이유가 있는데 얼음담긴 컵 주면서 응대를 그리 하는건 멀까요? 돈아끼려고 아이스안사고 뜨아 산걸로 오해하셨을까요? 기븐이 별루더라구요', 2, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '애용하는 카페인데, 사장님이 아닌 직원분들에 따라서는 요즘따라 커피 맛 편차가 좀 많이 나는 것 같습니다 ㅜ 재료듬뿍 음료 다 좋은데 커피맛 차이가 아쉬워서 리뷰 남깁니다..', 30, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '우연히 친구랑 찾아왔는데 너무 좋았던 카페,,ㅎㅎ 커피도 맛있고 빵도 맛있어서 또 오고싶은 곳입니다!! 완전 추천해요〰️〰️〰️〰️〰️〰️', 2, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '샌드위치와 커피가 너무 맛있고 제대로예요! 샌드위치가 특히... 재료가 썬드라이 토마토하며 치즈와 살라미(?)와 루꼴라 모두 너무너무 실하고 맛있는 재료로 가득한데 가격이 왜 이렇게 저렴하죠? 크로와상 빵 자체는 평범했지만, 전체적인 조합이 말도 안 되게 좋습니다. 서울 시내에 이보다 재료 충실한데 더 저렴하고 맛있는 집은 못 찾을 것 같네요. 커피도 굉장히 진하고 고소한 플랫 화이트가 최고였습니다. 연휴 마지막날 일정 사이에 시간이 좀 떠서 방문했는데, 이렇게 분위기 있고 맛있는 집을 발견하게 되어 명절 선물같네요 ㅎㅎㅎ', 1, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '홈베이킹하는 사람이라 디저트카페 투어다니는데… 세상에 이렇게 반죽이 떡진 스콘을 판매…하는 곳은 처음이에요….. 제가 산것만 이런걸라나요…', 73, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '원두랑 라떼 맛집으로 생각되어 몇년동안 꾸준히 찾은 카페입니다 지인들에게 맛있는 카페라 소개해주고싶은 마음에 항상 약속장소가 되는 곳이기도 하구요 회사 근처라 요즘은 더 자주 오고 있는데 항상 정신없고 바쁜거 같은 직원분들 모습을 보며 그에 맞는 맛을 보장해주는거 같단 생각도 듭니다 2층 특유의 몽글몽글한 카페의 분위기도 좋고 베이커리의 점점 진화된 맛을 느낄 수 있어서 더 애착이 가는 카페입니다 물론 커피맛좋은건 기본값이구요', 46, 2, 'GOOD', SYSTIMESTAMP);
