INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '입구부터 베이글향이 가득! 아침 일찍 열어서 좋구, 노래랑 분위기도 잘 어울리고 아늑하고 집중하기 좋아요!! 주차자리까지 완벽..! 다음에 또 오겠습니댱💛', 48, 10, 'GOOD', SYSTIMESTAMP);
