INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '합정에서 공부할만한 카페 찾다가 늦게까지 하고 디저트도 맛있어보여서 방문했어요~ 디카페인커피인데도 커피맛이 진하고 꼬소해서 맛있어요 리틀포레스트 라떼는 좀 더 가벼운 맛이었습니다! 조명을 잘 쓰셔서 공부하기에 좋아요', 40, 5, 'GOOD', SYSTIMESTAMP);
