INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '서교동 호주식 커피 전문 커피폴리 ● 언제든 열려있는 합정 카페 합정역 도보 2분 평일 07:00~23:00, 주말 09:00~22:00 ● 다양성과 개성이 뛰어난 곳 스몰배치(소량 다품종) 로스팅으로 매주 바뀌는 원두 라인업 (다양성 추구) 커피 메뉴 외에도 생과일주스 라인업 탄탄 ● Since 2015 오픈 10년차 호주식 커피의 정석 플랫화이트의 교과서를 느낄 수 있는 곳 ● 제과/제빵 탄탄한 베이커리 라인업​ 베이커리 전문 인력만 3인 상주하는 만큼 탄탄한 내공을 경험 가능함 ● 호주 감성이 인테리어 네추럴 우드 인테리어 자연광이 뛰어난 곳 자세한 내용은 블로그 리뷰를 참고바랍니다!', 33, 5, NULL, SYSTIMESTAMP);
