INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '차이티라테도 맘에 들고 샌드위치도 아랫부분이 소스 때문에 눅눅했던 것 말고는 맛있었는데 여자 화장실 위생은 좀 아쉬웠습니다. 세면대가 거의 막힌것 같아요,,', 12, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '빵 여러 종류를 샀는데 명란빵이 맛있었습니다. 다만 카운터 보시는 여성분은 뭔가 언짢아 보이시네요;; 그리고 서울페이도 된다고 적혀있는데 실제론 사용 불가한 매장이이었어요…', 180, 57, 'BAD', SYSTIMESTAMP);
