INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '최애 카페라 집이랑 멀어도 주말에 자주 옵니다! 분위기 굿 디저트 메뉴도 다양해요 바나나브레드가 진짜 넘 달지 않고 계속 들어가는 맛 🥹🫶', 13, 9, 'GOOD', SYSTIMESTAMP);
