INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '자리도 많아서 바로 착석 가능했고 작업 하시는 분들도 많거 조용해서 대화하기 너무 좋았어요! 코지한 느낌입니다:) 또 올 것 같아요', 25, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '1. 음료, 커피, 빵은 모두 맛이 준수. 특히 아몬드 들어간 빵 매우 맛남 2. 창가쪽만 노트북 충전이 가능토록 되어 있어 조금 아쉬움(일반석 충전 코드 미제공) 3. 고소한 빵 냄새와 시원한 바람 그리고 좋은 음악이 고객을 반겨주어 좋음 4. 주차 공간 부족한 편 5. 사장님과 남자 직원들은 매우 친절하고 상냥하여 기분이 좋았는데, 여자 직원은 정말 매우 쌀쌀 맞고 말투도 기분이 나빴고 응대 태도도 매우 형편없었다(몸에 타투 있었음). 내가 이상한가 싶었는데 수 차례 방문 할 때 마다 저 여직원의 소위 4가G없는 태도로 전부 쏙 마음에 들고 자주 들리고 싶은 이 카페 폴리에 긍정적인 평가가 바닥을 치게 만드니 큰 하나의 오점이랄까. 여기는 여직원에게 고객응대 교육좀 제대로 해야 될듯하다(사장 따님임?)', 59, 13, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '홈페이지에 23시 영업 종료이지만, 2층 22시 30분, 1층은 22시 50분 마감함. 시간 다르게 영업할 거면 홈페이지 수정 바람. 그리고 음료 하나 주문 후에 빵 고르고 메뉴판 보고 있는 중인데 5초도 안 돼서 1인 1음료 주문해야 한다고 압박 넣음. 마음의 안정을 가졌으면 좋겠음. 22시 30분 되자마자 손님 다 나가라는 듯이 대화가 안 될 정도로 음악 크게 틀어 놓음. 주변에서 소음공해로 신고할까 봐 걱정됨.', 48, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '오랜만에 마시러 온 커피폴리! 위층으로 올라가면 뭔가 말 못할 아늑함이 느껴지는 곳이어서 커피마시기에 너무 좋은 곳 같아요! 롱블랙도 모처럼 맛있게 마셨답니다b', 50, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '음료가 맛있어서 흡입했는데 ..  모두 빈잔일때 사진을 찍었네요 ㅋㅋ  여기 원두랑 커피맛 좋아요 !! 주차는 조금 어려울수 있지만 3대정도는 될것같아요 대화하기 좋습니다 !! 자주 오는 집이에요', 441, 35, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PARKING');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '제가 사장이라면 평일 아침 시간 여직원 자릅니다. 불만스러운 표정으로 손님 응대할 거면 서비스 업종 말고 다른 일 알아보세요. 갈 때마다 태도가 거슬렀는데, 여태까지 쌓은 스탬프 포기하고서라도 앞으로 더이상 방문하지 않을 겁니다.', 49, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '커피폴리. 24년5월29일 14시 방문. 파운드케이크 구매. 30분 뒤에 먹음. 한입 먹자마자 곰팡이 우글우글한 것을 발견. 카페에 전화했더니 사장으로 추정되는 분이 받았고, 본인은 다른 곳에 있으니 카페에 직접가서 물어보라함. 직접갔더니 직원이 곰팡이 맞다고 인정. 환불해주겠고, 다른 빵을 무료로 가지고 가라함. 빵의 위생이 문제인 상황에서 빵 준다하는 대처에 충격. 함께 있던 지인이 구매하고 내가 먹은 거라 환불도 나에겐 의미없음. 빵 안받겠다고 하니 ‘그럼 뭘 원하세요?‘ 함. 원하는것 없고, 곰팡이 난 것 문제 있다고 하니까 전화번호 남기래서 남겼고, 7일이 지난 지금까지 아무말도 없음. 전화번호는 왜 남기라한건지? 위생에 신경을 아예 안 쓰는것 같아, 공익의 목적으로 알려야할 필요성을 느껴서 씁니다', 12, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '분위기가 특이해요. 신기한 주스 메뉴들이 많아요. 꿀토마토는 진마 꿀토마토구요, 코코피치는 얼음+복숭아+코코팜 그 맛입니다 ㅎ 매장이 바빠서 그런지 비교적 청결한 느낌은 약했어요.', 56, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '여름에 먹기 좋은 시원한 쥬스 종류가 많아서 좋아요! 신선하구 맛있습니다! 그리구 대중교통 이용하기 편하게 캔으로 포장도 가능해서 더욱 좋습니다! 자주 올거 같아요! 감사합니다!', 115, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '음식을 취급하는 곳 인데 청결에 문제가 많습니다. 천장에 실링팬은 먼지가 눌러 붙은 정도고, 주방 산풍기나 주변 인테리어 소품도 쌓인 먼지 한가득, 카운터도 위생에 문제가 많은게 보일 정도 입니다. 직원분들은 무례함을 느낄정도는 아니였지만 불친절 합니다. 위생, 청결은 하루빨리 개선이 필요합니다.', 47, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '인생 플랫화이트. 밝고 화사하고 산미있는 원두는 아이스로 연하게 내려 마시면 더 선명하게 그 맛과 향을 느낄 수 있다. 하지만 커피폴리에서는 따뜻하고 무거운 바디감의 플랫화이트로 꽃동산이 떠오르는 감각을 선보인다. 너무 맛있음', 18, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '합정의 조용한 골목에 위치한 커피폴리! 커피가 맛있어요☕️ 매장 앞 3-4대정도 주차공간이 있어서 더 좋아요! 원두를 구매하시거나 다양한 드립백을 구경하고 구매하실 수도 있어요🤎', 101, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PARKING');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '편안하고 코지한 분위기의 까페입니다. 노트북 사용하기도 편하고 음악도 신나고 2층까지 좌석이 많아 여유롭습니다. 손님들에 대한 배려가 곳곳에서 보입니다.', 23, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '되게 힙함+조잡함+인스타 스러운 동네 카페예요 분위기가 신기해요 커피가 맛있어요 내부에 화장실있지만 자주 막히나봐요 근처 공중화장실 이용하라고 안내해줍니다 아늑한 미국집같아요', 15, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '민폐끼치는 사람은 오지마라~ 이런 느낌의 카페인 느낌이었어용~ 벽에 써 놓은 글들이 별로였어요. 말이 아다르고 어다른데 물론 이상한 손님은 안오는게 좋겠졍.. 맛있는 커피를 예쁜 잔에 마시고 싶은 고객 입장에서는 플라스틱 느낌의 검정잔도 별로였고 차와 함께 나오는 물잔도 별로였고 (사용감이 너무 많음) 일단 2층의 빈 테이블들이 안 닦여져 있어서 더 별로~ 청소를 신경쓰셔야할 듯~ 고객들이 잔을 가지고 내려가면 테이블은 안 닦는 듯... 고객 지적 전에 카페 먼저.. 둘러보셔야 할듯? : )', 16, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '폴리커피는 중타이상으로 늘 먹는데 이 날은 그냥 그랬음. 원두 설명을 보고 기대해버린 탓일까…? 포스 앞에 있는 화병이 예뻐서 찰칵', 44, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '커피가 맛있어서 가끔 이용하지만 직원들은 항상 불친절합니다. 특히 머리 묶은 남자직원은 퉁명스럽기도하고 뭘 물어봐도 잘들리지 않는 소리로 툭 던집니다. 아침에 기분 잡칠정도로요. 한번은 알바생이 빨대를 잘 꼽지 못하자 대표가 제 바로 앞에서 맨손으로 빨대끝을 손으로 누른후 쑥 집어 넣고 “이렇게 하면 되잖아!”하고 비위생적인 교육(?)을 하는 것을 보고 허걱했네요. 뭐라고 따졌어야 하는데 그냥 가지고 나왔지만 대표가 위생관념은 없어 보입니다. 1층 매장 보시면 에어컨이나 이런 곳에 먼지가 수북한데 컨셉인지 그대로 놔두더라고요.  리뷰에 불친절하다는 이야기가 많은데도 별로 신경 안쓰나봅니다. 커피 맛만큼 친절과 위생에 신경써주면 좋겠어요.', 1, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '베이커리가 종류가 더 생긴 느낌은 기분탓지 모르겠지만 간식거리 많아서 좋아요 화장실이 좀 아쉽지만 나머지 다좋아요 편히 이용하기 좋은데 교회 끝나는 시간이랑 겹치면 가끔 많이 시끄러워요', 23, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '직원인지 사장인지 문신으로 인하여 위협감을 느끼게하는 남자분이 너무 불친절 했습니다. 음료의 맛보다 직원분 응대때문에 아무것도 기억에 남는게 없네요. 들어가서 1부터 10까지 다 불친절했구요. 마감 안내까지 고객으로써 너무 불편했네요. 두번다신 재방문 하고 싶지 않습니다. 비추천합니다.', 23, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '매장 선곡 차분하니 넘 좋고 혼자 노트북하시는분들 많아서 조용해요. 커피도 부드럽고 맛이 좋네요. 매장 앞에 4대정도? 주차도 가능해요.', 89, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PARKING');
