INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '따뜻한 아메리카노를 주문했는데 한잔만 잘못나온건줄알고 그냥달라했는데 저 종이컵 누가봐도 따뜻한 아메라카노 담아주는거 아니였는지...? 캐리어에 받아서 먹기전까지 저 종이컵안에 아이스아메리카노가 들어있을거라고 생각도못했어요 정말 황당...', 17, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '제가 좋아하는 합정 카페입니다. 맛도 있고 감성도 좋아서 합정가면 가끔가요. 근데 갈때마다 사잠님이 조금 불편했어요. 주문 잘 못 받으시고 다시 만들어 주시긴 하셨지만 그 과정에서 분위기를 굉장히 불편하게 하셨고요, 오늘은 깨진 컵에 커피가 서빙돼서 제가 모르고 1/4정도 마신것 같아요. 늦게 확인하고 사장님께 말씀드리러 갔는데 다짜고짜 손님이 유리를 먹은 건 아니라고 확인해 주시고선 커피 다시 만들어주신다고 하시곤 그냥 한잔 내어주셨네요. 물론, 제가 유리를 먹진 않았을 것 같습니다. 그럼에도 괜찮은지 물어보고 사과해야 하는 게 먼저 아닐까요? 유리에 다치진 않더라도 새어나온 커피가 옷에 묻어 불편했거든요. 다시 내어준 커피는 마실 기분이 아니어서 그냥 반납했습니다. 앞으로는 괜찮은지 물어봐주세요.', 70, 11, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '5년째 다니는 커피폴리 항상 최고!! 언제나 열정돠 에너지가 넘치는 맛있는 커피집 입니다. 쌀쌀한 요즘 서교동 모카가 간절하네요.', 38, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '직원들 대부분 친절한데 음료 받으러가면 진동벨 받을때 한손으로 툭 받고 눈은 딴데보고 다른얘기 하고있음 한두번이아님 머리 염색한 중년남성 사장님인거같은데 신경좀 쓰셨음 좋겠어요', 19, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '매장이 이쁘고 커피가 맛있어요 원두는 4종류 고를 수 있었고 내 입맛에 맞는 취향을 물어보면 원두나 맛에 대해 잘 설명해주셔서 좋아요 베이커리류도 종류가 많더라구요 이번에는 커피만 먹어봤지만 다음에 또 방문한다면 베이커리도 먹어보고 싶은 카페에요', 47, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '*카페모카 HOT 5,500 달달하고 커피 맛난다고 함 *HOT 아메리카노 디카페 4,500 디카페라고 트레이에 써준거 넘나 기엽ㅋ *HOT 아메리카노 케냐 4,500 고소하면서 깔끔한 맛! 커피 종류가 다양하고 설명이 상세해서 다양한 맛의 커피를 기호에 따라 즐길 수 있어서 좋은 곳! 밀크티랑 샌드위치 등 디저트도 팔아서 아지트로 삼아도 될만한 곳!! *히비스커스 티 리프레셔 6,500 너무 상큼하면서 엘더베리가 들어가서 플로럴한 꽃향이 그윽하게 퍼지는 특별한 티! 일반 히비스커스랑 달라서 비싼 값을 하는 너낌! 선택 너무 만족! *분위기 테라스도 있고 2층으로 되어서 다양한 분위기를 즐길 수 있는 홍대 힙카페!  재방문 의사 200%', 438, 99, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'TERRACE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
