INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '근처 지나가다가 참새 방앗간 지나가지 못함. 이번 원두는 쏘쏘한 느낌,, 그래도 중타 이상은 늘 친다. 폴리 앞에 있던 삼색이도 한컷~', 26, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '밤늦게 갔는데 늦게 까지 해서 좋고 디저트가 겹겹히 막 쌓아져있음! 하나남은 인절미 스모어 겟하고 수박주스 먹었는데 맛있었음 책상과 분위기는 옛날 서점 느낌‘', 33, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '호주식 플랫화이트나 카푸치노 마시고 싶어서 급 검색했어요 ㅎㅎㅎ  매장 넓고 좌석도 많고 메뉴도 다양하고 커피두 깔끔하네요 베이커리류도 다양해서 여러가지로 아주 만족한 커피타임이었습니다 맛은 주문한 거 전부다 평균정도로 괜찮았어요^^*', 30, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '매장에 자리가 은근 있고 대화하긴 좋을것 같아요. 카페라떼는 그냥그냥 먹을만했습니다! 노트북은 쓰는곳 자리 제한되어있고( 1층은 모르겠고 2층은  딱 창가자리 4~5석 정도요)  콘센트 안쓰는 아이패드사용도 노트북사용 취급해서 작업용으로는 별로일것 같네요?? 화장실 남녀 따로고 카페 내부라 괜찮았습니다', 87, 14, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PLUG');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '카페도 넓고 커피도 디저트도 맛있고 약속 장소로정말 좋아요! 저는 매번 폴리에서 약속 잡는데 지인들도 다 재방문합니다! 다만 배달 주문 밀렸을 땐 메뉴가  좀 늦게 나오는 것 같더라구요! 그래도 합정역 카페는 여기가 제일 좋아요👍🏻', 88, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'MEETING');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '아메리카노 마시고 가려고 주문하고 앉아있었습니다. 5분뒤에 테이크아웃컵에 음료가 나왔길래 내꺼아니구나하고 다시 기다렸습니다. 10분..15분이 지나도 안나와서 물어보니 제음료라고 하시더라구요. 진동벨을 줬는데 울리지 않았고 그럼 제 음료인지 어떻게 확인을하고 가져가나요? 손님이 가서 “이 음료 제음료인가요?” 라고 물어봐야 하는건지.. 이상한 시스템인것 같습니다.', 16, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '맛있다! 뭔가 먹고 아 이게 커피에서 나는 플럼향인가 생각했는데 설명보니 없었음.. 커알못인듯 ㅠ 아침에가면 다들 바쁘셔서 공장처럼 그러면서도 프랑스 레스토랑처럼 움직이는 느낌인데 (라따뚜이에서 본 프랑스 레스토랑 주방 ㅋㅋ) 그게 뭔가 나에게 활기를 준다. 다음엔 프라우드메리도 먹어봐야지 넘 궁금!!', 50, 9, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '이번 원두는 파푸아뉴기니, 서비스 음료는 투 에티오피안. 투 에티오피안 진짜 너무 맛있어서 메뉴 바뀌기 전에 또 가야지 싶었다.', 14, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '궁금한게 위클리원두는 언제바뀌는건가요? 제 기억엔 한 삼일전에 갔는데 또 바뀌어있어서… 맛있어서 또 먹고싶었는데.. 아쉽지만 사장님의 열정을 응원합니다. 이게 시즌메뉴의 매력이지…. (그치만 투 에티오피안 너무 맛있었는데 ㅠ)', 81, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '맛있는 커피 마시면서 동물의 숲 하고왔어욤 ㅎㅎ 홍대 주차되는 카페 찾아서 왔는데.. 베이커리 종류도 많아서 참기 힘들었어욤🥹 그리고 커피 지인짜 맛있어용', 45, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PARKING');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '강추👍 두유라떼, 오트라떼 찐맛.. 오트라떼(6,000), 케일파인쥬스(6,500) 오트라떼가 정말 고소한게 맛있어요. 다음에는 바닐라시럽을 추가해서 먹어보려구룐! 그리고 케일파인쥬스는 맛이 진해요. 다른 매장들은 물양이 더 많아서 가벼운 맛이 나는데, 여기는 진해서 디톡스하기 딱 좋아요!', 22, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '원두를 사면 아메리카노 한잔이 공짜! 근데 그 커피 맛이 너무 좋았다. 스페셜티원두도 많고 싱글원두는 좀 한 노트가 강하게 느껴지는 경우가 많아서 핸드드립할때도 보통 블렌딩원두를 많이 사는 편인데 이번엔 온두라스가 궁금해서 구매해봤다. 근데 밸런스가 너무 좋아서 ! 여기 또와서 이것저것 다 먹어봐야지 !', 81, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '합정 커피 찐맛집, 오전부터 카페인에 쩔어있어 디카페인으로 주문했는데 것도 나쁘지 않았음. 뱅쇼도 괜찮았다고 함. 레트로 빈티지 무정리 인테리어라 편함 ㅋ 요기 디저트도 맛있을 듯. 점심을 과하게 먹어 사진만 찍었는데 갓 나온 스콘 냄새가 예술이었음.', 19, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '여기 스콘 진짜 맛있어요..❤️ 촉촉한 스콘은 처음이라 남김없이 다 먹었네요🥹 카푸치노도 존맛입니다ㅜㅜ 부드러운 커피 오랜만에 먹어서 노곤하니 좋더라구요!', 65, 16, 'GOOD', SYSTIMESTAMP);
