INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '종종 재택하게 될 때 배달이나 포장해서 쟁여두고 마십니다. 기본 아메리카노도 맛있고 라떼류도 달지 않고 부드럽고 맛있음 에이드 차 종류도 굳 아아는 트리플샷이라 약하게 드실 분은 얼음이나 물 조금 섞어 드세용', 8, 5, NULL, SYSTIMESTAMP);
