INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '진짜 애정하는 곳 ✨ 친구 만날때 약속 장소로 꼭 정하는 곳이에요 커피도 맛있고 도란도란 얘기 나누기 좋아요 나만 아는 줄 알았는데 이제 다들 아는 곳,,,,🤦🏻‍♀️', 75, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '사진을 안찍었네… 어쩌다 갔는데 음료 맛 인테리어 친절 좌석의 편안함 화장실 청결도 소음의 정도 음악 모두 평균이상을 한 굉장히.. 흔하게 느껴질 수 있지만 드문 카페. 1층은 베이킹을 계속해서 조금 혼란스럽지만 2층은 여유롭게 느껴졌다. 물과 담요같은 편리를 위한 배려도 느껴지고 … 원두도 맛있을거같다', 40, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '전에 크림커피 마셔봤는데 기억에 남아서 재방문 해봤어요 제쥬주스 시켰는데 달고 맛있어요 진짜 당근이랑 사과 갈아서 그런지 씹히는게 미세하게 있어서 더 좋았습니다', 86, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '맛있는 빵냄새가 가득하고 로스팅하는 원두냄새가 가득한곳 커피도 디저트도 실망없는 카페애오!! 디카페인원두로 라떼도 너무 꼬숩고 맛나요', 23, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '기대 많이 하고 가서 생각보단 별로였어용 시그니쳐 메뉴가 카푸치노 베이스인데 폼은 플랫화이트 수준이더라구요 글고 매장이 그닥 청결하진 못해요 많이 시끄럽고요 제가 기대를 많이 해서 그럴까요? 아무리 바리에이션 커피라 해도 샷이 너무 워터리 해요 기본 1샷 넣는 곳인가 싶더군요', 43, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '내가 유일하게 아는 커피 맛집.  매번 다른 메뉴를 돌아가면서 먹는다. 단커피 싫어어는 편이지만 기꺼이 막어본다. 사장님의 손맛을 110프로 믿기때문에~', 39, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '머리 염색하신 분 마스크도 안 쓰시고 에미넴 노래 따라 부르시고 카드 만졌던 손으로 빵 만지셔서 좀 그렇네요... 커피 내리시는 분은 친절해요.', 30, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '지난번 플랫화이트 너무 맛있게 마셔서 다시 갔는데 이번엔 그때 그 맛이 아니다. 너무나도 평범한 맛이었다. 지난번 주문한 게 그게 아니었나 헷갈릴 정도로 완전 다른 맛이었다.', 1, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '일찍 여는 카페 찾다가 아홉시에 열길래 와봤는데요. 아침이라 저밖에 없었어요. 근데 빵도 다 있구 들어가면서부터 냄새가 너무 좋았어요. 커피도 빵도 맛있고 분위기가 좋아서 혼자 힐링했습니다♡', 36, 10, 'GOOD', SYSTIMESTAMP);
