INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '정말 자주 가는 카페 폴리😆 2023년 첫카페도 폴리였네요~>< 좌석도 꽤 많고 디저트도 많아서 넘 좋아요!! 음료도 맛있는것 같아용(엄지척👍)', 36, 1, 'GOOD', SYSTIMESTAMP);
