INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '홍대에 있는 수많은 카페 중에서 몇 없는, 제가 대학생 때부터 꾸준히 방문하는 곳이에요. 1층과 2층까지 가게 내부가 넓고 프라이빗하게 이야기할 수 있는 공간도 있습니다. 방문할 때 마다 이곳의 커피를 꼭 구매해서 가는데요. 디저트는 전부 다 맛있고 특히 과일과 채소가 들어간 주스를 마시면 속이 풀리는 느낌이 들어요~😊 사장님께서 카페의 본질에 맞는 운영을 하고 계세요. 카공하다가, 대화를 나누고 있는 다른 손님에게 눈치 주거나 컴플레인을^^; 건다면 서로 민망한 상황이 될 수 있으니 이용시 참고하세요~ㅎㅎ 사장님, 항상 같은 자리에 있어주셔서 감사드립니다. 오늘의 음료도 맛있었어요 😁 ❤️ ❤️', 106, 20, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '매장 앞 주차도 가능하구, 메이플피칸파이 먹었는데 진짜 디저트 너~~~~무 맛있었어요!! 다음에 다른 디저트 먹으러 또 갈거에요!!!! 커피 맛있는것도 기본이에요!!!!', 44, 3, 'GOOD', SYSTIMESTAMP);
