INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '커피가 맛있네요. 테라스 자리와 실내 자리가 많지만 간격이 여유있어 좋습니다. 카페앞 주차자리가 4-5대 정도 가능해서 이것도 큰 장점이네요. 베이커리류도 직접 굽고 있던데 다음에 먹어봐야 겠어요.', 65, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PARKING');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'TERRACE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '리뷰 처음 써보네요. 커피도 맛있고 스콘도 맛있는 집입니다. 근데 직원이 너무 케바케에요. 좋으신 분들도 많지만 평일 오전 여자 직원분들 너무 매너가 없으신 것 같아요. 친절한것까지는 바라지도 않습니다. 그리고 손님 많은데도 불구하고 카운터 옆에서 손톱깎으시던데 식품 취급하시는곳에서 그건 진짜 아닌 것 같은데 안그러셨음 합니다.', 78, 14, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '커피가 맛있어서 항상 배달로만 시켜먹다 오늘 직접가서 사봤는데 서비스와 대하는 태도가 불쾌했습니다. 캔보틀을 직접 구매자가 갖고오고 비닐만 띡주고서 직접 셀프로 하는거라면 안내라도 제대로 적어놓길 바랍니다 앞으로 다시갈일은 없겠네요', 87, 16, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '배달로 주로 시켜먹다가 매장 가서 스콘이랑 크럼블파이 사와서 먹었습니다. 매장은 배달기사님들이랑 주문받고 베이커리 굽는 분들이 많아서 1층은 좀 복잡했어요', 6, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '매장 내부에 항상 흐르는 냉랭함과 불친절의 기운. 특히 카운터 주문 자주 받는 두 여성분의 차갑고 안일한 대응은 그 끝을 달린다. 사실 불친절의 선봉장은 이 곳 사장님이다. 그래서 다들 보고 배우는 게 아닐까..? 벽에 붙어있는 칼럼글이나 유의사항 등을 보면 커피 혹은 매장에 대한 자부심이 넘쳐 나는데 서비스 정신의 안일함을 덮을 만큼의 커피퀄리티는 아니다. 그릇에 담긴 딸기, 음식들 앞에서 자주 마스크를 내리고 말하는 사장님의 모습은 프로답지 못하고 보는 이에게 찝찝함을 남긴다. 이 건물 공간 고유의 운치가 좋아 다녔는데 인재로 인해 혼탁해져 참으로 안타깝다. 사람이 결국 공간을 망친다.', 41, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '음료 맛집 이근처 약속있음 무조건 여기로 옴 근데 오늘 유난히 내부에 벌레가 너무 많았음 11월인데 날파리에 모기가 너무 날라다녀서 음료 마시면서 계속 물리고 잡는다고 박수(?)침 커피는 언제나 맛있지만 벌레는 없었음 좋겠음', 89, 17, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '카페 분위기좋고 조용해서 좋았어요! 비오는날에 딱이었습니다:) 디저트종류도 여러가지 있었는데 담엔 한번 먹어보고싶어요! 캔보틀은 내일 마셔보려고샀습니다😇', 97, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '커피 맛있고 좋은 건 알고 있지만 새로 바뀐 잔 뚜껑을 제대로 닫아주셨으면 좋았을 것 같아요.. 테이크아웃해서 가져오는데 뚜껑이 덜 닫혀있는 것도 모르고 사무실에서 꽤 흘렸어요ㅜㅜ.... 사람많고 주문 밀린 건 알지만....', 37, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '역시 평점이 높은데는 다 이유가 있던 거였어요! 커피도 맛있고, 인테리어도 예쁘고 직원분들도 엄청 친절하세요!! 스콘도 너무 맛있어보여서 포장해왔는데 대만족이에요!! 또가려구요 ㅎㅎ', 49, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '최악. 담배핀 손으로 손도 안닦고 커피내리는거 방금 눈으로 확인했고 남자사장님 마스크고 안쓰고 트레이는 커피가루로 더럽고..위생 최악임. 다시는 근처도 안갈거임', 95, 24, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '아이스라떼 에티오피아 상큼하고 맛있어요ㅠㅠ 라즈베리페스츄리 바삭달콤🤭 가게도 이쁘고 노래선곡도 너무 좋고 비오는날 우연히 왔는데 대만족💯', 37, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '프로페셔널하여 커피에 자부심 강한 곳! 맛과 서비스, 분위기 모두 완벽한 곳! 하루라도 안 마시면 갈증나는 곳! 최고입니다! ❤️', 72, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), 'Small Batch Roasting을 하는 몇 안되는 Light Medium Roasting Coffee 전문점입니다. 산미가 있고 가볍게 과일향이 있는 원두를 좋아하신다면 적극 추천드립니다. 플랫화이트, Wet 카푸치노 추천드려요. 원두를 1-4번 중에서 선택해서 주문할 수 있어요.', 85, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '커피 : 별 4.5 개 가격 : 별 4개 음악 : 별 3.5 개 뷰 : 별 3.5 개 분위기 : 별 4개 친절도 : 별 5 개 항상 산뜻한 커피와 활기찬 분위기가 있는 커피숍', 118, 21, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '보통입니다... 인테리어 엔틴하고 예쁜데 플렛화이트 가격이 네이버랑 다르네요 (200원파이) 그닥 기분이 좋지는 않습니다. 사람 많아서 시끌시끌 편안한 느낌은 없어오.', 39, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '#합정카페 #홍대카페 #플랫화이트 커피에 집중하는 카페에요 :D 어떤 메뉴를 고르든 다 좋았어요 !! 2층으로 되어 있어서 공간도 넓었습니다 :)', 49, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '1층은 쾌적하지만 2층은 청소 상태가 그다지 좋지 않아 먼지가 곳곳에 쌓여있습니다. 또한 화장실 곰팡이가 ‘여기가 과연 영업장이 맞는가’ 하고 의구심이 들 정도로 위생 상태가 좋지 않습니다. 커피 맛은 훌륭합니다만 업장의 전반적 위생상태가 거슬려 재방문을 망설이게 합니다.', 0, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피폴리'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '플랫화이트 그리고 라떼 마셨는데 평범했어요. 브라우니는 생각보다 맛 없어서 아쉬웠고 재방문은 하지 않을래요ㅜㅜ 조금 아쉽네요!', 7, 5, 'BAD', SYSTIMESTAMP);
