INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바나프레소 홍대입구역사거리점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '이번엔 어떤 메뉴를 먹을까하다가 청귤이 들어간 유자의 맛은 비타민처럼 상큼하네요!! 어니언베이글까지 야무지게 잘 먹었습니다 그리고 걷다가 지칠때쯤 종종 들리는데 잘 머무르다 가요~', 37, 6, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바나프레소 홍대입구역사거리점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '주말인데 이렇게 한산하다니~ 팝업스토어 자주 하는 곳에서 조금만 걸어오면 됩니다. 덕후 여러분들 모여서 쉬다가 가기 좋아요~ 테이블 크기가 작지만 자리 꽤 있어서 쾌적합니다.', 104, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'MEETING');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바나프레소 홍대입구역사거리점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '음료 맛있어요!!! 직원분이랑 사장님 다 친절하시구 좋아요 홍입에서 간단하게 작업할 수 있는 곳 찾고 있었는데 엄청 만족스러웠습니다 ㅎㅎ', 34, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바나프레소 홍대입구역사거리점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '가게 알록달록 이뻐요❤️ 컵에 오늘의 운세적혀있는것도 은근 읽는재미가 쏠쏠하네요 이번엔 딸기요거트로 마셔봤는데 딸기맛이 강해서 좋았고 많이 달지않아서 맛있었습니다 메뉴가 많아서 그날그날 고르는 재미가 있을것같아요 직원분들도 친절하셨고 인테리어도 이쁘구 내일은 다른음료 먹으러방문해볼게요 !', 321, 47, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바나프레소 홍대입구역사거리점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '가게가 이뻐요 평소 메가, 컴포즈만 다녔는데 바나프레소도 생각보다 맛있네요 얼그레이 밀크티가 꽤 진해서 맛있었어요😊 가격대는 유사한 점포들과 비슷한수준이고 메뉴가 꽤 다양하더라구요 종종 방문해보겠습니당', 42, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바나프레소 홍대입구역사거리점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '홍대입구역 근처에서 카공하려구 찾다가 분홍색에 이끌려서 들어가게 됐는데요!ㅎㅎ 가게 내부도 쾌적하고 깔끔해서 카공하기 좋은 분위기고, 무엇보다 음료량이 진짜 많아요!! 이 가격이면 다른 브랜드 톨 사이즈도 못 사먹는 가격인데 너무 만족했어요☺️👍🏻같이간 친구들도 다 음료 마시고 배부르다고ㅠㅋㅋㅋ 저녁 못 먹을뻔 했어요.. 3시간동안 먹어도 먹어도 줄지 않던 음료들.. 덕분에 가성비 카페인 거 몸소 배웠습니닼ㅋㅋ', 13, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바나프레소 홍대입구역사거리점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '평소에 궁금했는데 주변에 바나프레소가 없어서 홍대 온김에 왔습니다! 프랜차이즈에 그렇게 고가의 가격이아닌데 커피맛도 음료퀄리티도 상당히 좋아서 만족스러워요!😊', 107, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바나프레소 홍대입구역사거리점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '커피 유튜버 안스타님의 평이 괜찮아서 방문했어여! 1800원 극강의 가성비를 자랑하는 아아!! 맛 괜찮고 저는 포장했지만 내부 자리도 넓어서 홍대에서 가볍게 시간 보내실 분들께 추천이요~!', 4, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '바나프레소 홍대입구역사거리점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '맘스터치옆에 있어서 탄산 못먹는 아이가 좋아하는 라떼를 주문하기 좋네요. 맘스터치 햄버거와 치킨 시키고 기다리는동안 라떼도 사러가기 편해서 좋네요', 38, 4, 'GOOD', SYSTIMESTAMP);
