INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '협찬 | 홍대입구에서 탕종빵으로 유명한 빵나무 방문했어요🍞 시식 빵부터 맛있어서 기대했는데, 마늘바게트·소금빵 등 촉촉하고 쫄깃해 깜짝 놀랐어요👍 생활의 달인 명판이 괜히 있는 게 아니더라구요! 화학첨가제 없이 만들어 속 편하고 종류도 다양해 골라먹는 재미가 있었고, 직원분들 친절해서 기분 좋게 머물다 왔어요😊 포장도 가능하지만 따뜻한 인테리어 덕에 앉아서 여유롭게 먹기 딱 좋은 곳이라 홍대 빵집 찾으신다면 추천드려요', 48, 1, 'GOOD', SYSTIMESTAMP);
