INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '생활에 달인에도 나올만큼 유명한 탕종빵집!!! 건강빵을 좋아하지만 소화력이 좋지 못하기 때문에 들렸는데요. 앉아서 먹을 수 있는 편안한 자석도 있어서 빵이랑 음료 시켜서 먹고 가면 아주 딱일거 같더라고요 저는 식사겸 먹기 좋은 호밀깜빠뉴랑 무화과초코호밀깜빠뉴를 먹었답니다~ 아아 한입 마시면서 빵을 먹으니 환상의 궁합이랄까요 👍 호밀깜빠뉴도 그냥 먹어도 맛있고 크림치즈를 발라 먹어도 맛있더라고요👌 무화과초코호밀깜빠뉴는 고소하고 적당히 달달해서 죄책감을 없이 먹을 수 있는 맛있어요 겉은 바삭하지만 안은 탕종빵 맛집답게 속이 부드럽고 쫀득쫀득한 식감이 너무 좋았습니다 😀', 7, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '생활의 달인에 나온 빵집이라 전부터 궁금해하다가 드디어 방문했어요! 화학첨가제가 들어가지 않아서 속이 편한 빵이고 종류가 정말 다양했어요! 탕종빵집이다보니 깜빠뉴와 바게트 식빵 소금빵이 가장 잘 나가는 메뉴들이더라고요! 저는 연유바게트, 소금빵, 하트후레즈 주문했어요. 진짜 다 맛있어서 너무 놀랐어요!ㅎㅎ 소금빵은 왜 베스트인지 한 입 드셔보시면 알게되실거에요💓 구움과자 선물 세트나 케이크도 선물하기 너무 좋아보이더라고요ㅎㅎ 무엇보다 비주얼 너무 예쁘고 사장님께서 맛에 진심이셔서 재료를 정말 아낌없이 넣으시는게 느껴지더라고요!! 사장님과 직원분 너무 친절하셔서 너무 기분 좋게 머무를 수 있었어요! 포장도 가능하지만 따뜻한 인테리어 속 차분하게 책을 읽기도 좋고 친구들과 대화 나누기에도 좋은 공간이에요', 30, 1, 'GOOD', SYSTIMESTAMP);
