INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '소금빵, 밤식빵 포장했어요!! 다다음날 에프에 구워서 먹었는데 넘 맛있었어요!! 소금빵 버터향 넘 좋고, 부드러웠어요!! 밤식빵도 안에 밤이 한가득 들어있어서 넘 맛있게 잘 먹었습니다!! 사장님 진짜 진짜 친절하셨어요!! 담에 또 방문하고 싶어요!!', 26, 0, 'GOOD', SYSTIMESTAMP);
