INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '홍대입구에서 탕종빵으로 유명한 빵나무 먹어봤네요 확실히 보통 빵집하곤 맛이 다르네요 반죽이 달라서 그런지 훨씬 쫄깃거려요 요기는 다들 드셔보셨으면 좋겠네요 진짜 맛있어요', 46, 5, 'GOOD', SYSTIMESTAMP);
