INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '마롱바게트 유명해서 먹어봤는데 크림이랑 밤 조합이 너무 맛있고 안쪽빵도 촉촉해서 좋았어요!!! 홍대거리랑 떨어져있는데도 손님들 계속 꾸준히 들어오더라구요! 그리고 무엇보다 직원분이 너무너무너무 친절하셔서 기분좋게 먹고 나왔습니다 ㅎㅎ', 0, 8, 'GOOD', SYSTIMESTAMP);
