INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '요즘 홍대에서 유명하다는 베이커리 빵나무에 들렀어요. 시식용 빵이 맛있어서 내부 벽에 생활의 달인 명판이 두 개나 붙어있는 것을 보니 역쉬~👍 하는 하는  말이 절로 나오네요. 기분이 좋아지고 싶으면 들르면 좋은 빵집인 것 같아요~🥰', 11, 2, 'GOOD', SYSTIMESTAMP);
