INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '홍대 오랜만에 와서 빵집 투어했는데요! 달인의 빵집이라고 해서 방문했어요~! 단팥빵/깜빠뉴/마늘빵/식빵 등 종류가 다양했고 매장 안에서 빵 먹고갈 수 있는 공간이 있어서 좋았어요ㅎㅎ 저는 연유 바게트, 마롱 바게트, 강낭콩배기, 소보루 이렇게 먹었는데 특히 마롱바게트랑 강낭콩배기 달달하니 맛있엇어요~', 77, 13, 'GOOD', SYSTIMESTAMP);
