INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '커피와 빵도 맛있었는데 빵 서비스까지 주셔서 든든하게 먹고 나왔습니다!!! 너무 친절하시고 분위기도 좋아요 홍대 조용한 카페로 강추', 103, 21, 'GOOD', SYSTIMESTAMP);
