INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '생활의 달인에도 나온 서울 마포 홍대베이커리 연남동빵집 빵나무 빵 가격이 합리적이며, 다양한 종류의 빵이 있다. 포근하고 아늑한 느낌의 인테리어 수제로 만들고 재료에도 상당한 신경을 쓰신게 느껴진다. 파티쉐님이 나오셔서 무슨일인가 했더니 케이크를 주문받으시는중 너무 맛있는 케이크를 먹어보고 사러오셨다는 분~ 그이야기를 들으니 나도 구입하고 싶은데 주문을 하면 산책하고 오시는동안 만들어두신다고 한다 다음에는 꼭 주문해봐야지', 84, 11, 'GOOD', SYSTIMESTAMP);
