INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '빵나무는 빵 퀄리티도 높고 가격도 합리적이라 정말 만족스러운 곳이었어요. 특히 밤 티라미수의 묵직하고 달달한 매력은 다른 베이커리에서 찾기 힘든 맛이라 추천드려요. 테이크아웃해서 인근 연트럴파크에서 맛있는 빵과 커피를 즐겨 보시는 것도 좋을듯 합니다. 여러분도 시간이 되신다면 꼭 들러보세요!', 34, 7, 'GOOD', SYSTIMESTAMP);
