INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '사장님이 너무 친절하시고 가게 분위기도 푸근해서 제 취향 저격입니다 :) 건강 생각하는데 호밀빵 종류도 많고 음료도 진짜 종류가 많아서 골라먹기 좋았어요🤍', 57, 14, 'GOOD', SYSTIMESTAMP);
