INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '베이컨 베이글 샌드위치  - 탄단지를 아주 골고루 잘 갖추어서 포만감도 적당히 있어 한 끼 식사로 손색없었다. 솔직히 내가 골랐지만 메뉴 정말 잘 골랐다 생각했었다. 밤 티라미수 - 부드러운 밤 크림과 빵 시트가 아주 조화롭게 잘 어우러졌고, 비주얼부터 맛까지 너무 조화로웠어서 마음에 들었다. 강낭콩베기 - 특히 강낭콩이 빵 안에 송송 박혀 있어 씹을수록 고소한 맛이 입안에 퍼졌고, 빵 자체가 아주 쫀득쫀득하다보니 말랑한 빵의 식감과 아주 잘 어우러졌다.너', 100, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '빵 종류가 다양하고 먹음직스러워요. 향수를 불러일으키는 곳이에요. 무화과초코깜바뉴가 맛있었고, 식사대용으로는 에그버거를 추천드려요!', 60, 15, 'GOOD', SYSTIMESTAMP);
