INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '요즘 맨날 먹는 점심빵 소개합니다🥐 #빵나무 비오는날일수록 뭔가 빵이 그립더라구요? 오늘은 홍대의 식빵맛집 다녀왔습니다! 한번 방문할때 2~3일치 사오는데, 브런치 메뉴랑 연유빵에주로 먹었어요...! 단짠 조화맞추기🫧 씨앗식빵도 정말 맛있는 편이니 도시락러들은 이반주 샌드위치 어떠신가요? 😘오늘 먹은 메뉴? 브런치에그 4000원 연유크림바게트 4500원 연유토스트 1500원 카페라떼 4500원 😘 빵나무 서울 마포구 월드컵북로4길 30 102호 #홍대맛집 #홍대카페 #홍대빵집 # 홍대핫플 #홍대식빵 #홍대예쁜카페 #식빵맛집 #홍대놀거리 #카페투어 #빵지순례 #브런치', 11, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '이근처에서 빵먹고 싶을땐 빵나무, 바케트의 담백 고소한  부드러운 식감까지, 신상 크림치즈 브라우니는 달콤한 치즈에 살짝씩 씹히는 짭잘한 치즈의 맛이 너무 잘 어울리는 느낌이네요. 맛나요. 아메와 딱', 12, 3, 'GOOD', SYSTIMESTAMP);
