INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '''개인 빵집이 맞나'' 싶을 정도로 다양한 빵, 디저트에 압도당하는 느낌을 받았어요 판매하는 상품 비주얼과 진열상태만 봐도 실력있고 깔끔하신 분이라는 느낌이 드는! 매장도 테이블이 많고 깨끗해요 퀄리티 높은 수제빵들을 맛 볼 수 있고, 특히 발효빵 종류가 정말 맛있더라구요 디저트들도 너무 달지 않고 고급스러운 맛이 나서 좋아요😊 홍대입구역과 가까우니 꼭 방문해보세요', 26, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '친절해요. 빵 뭐먹지 고르는데 마침 시식거리가 있어서 먹어보고 골랐어요. 우유만도 팔아서 빵엔 우유지 하며 시켰습니다. 인테리어보다가 카메라를 보았고 그렇게 제빵사님과 스몰토크도 하고 좋았어요. 단거 좋아하면 슈크림빵 추천드립니다.', 88, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '홍대에서 제일 자주 가는 빵집이에요❤️ 지나가다가 구경하는데 타르트가 너무 이뻐서 구매해봤어욤 브라질넛 캬라멜이랑 헤이즐넛 쇼콜라 타르트에요! 브라질널 캬라멜은 이름처럼 캬라멜 향이 찐하고 위에 소보루 크럼블이 올라가 있어요!! 브라질넛이 잔뜩 들어가있어서 너무 고소하고 캬라멜이 달달해서 잘 어울려요🫶🏻 중간중간 소보루 크럼블도 포인트구 식감이 무엇보가 너뮤 좋아요🥺 커피랑 우유 같이 먹으면 최고의 디저트일것 같아요❤️ 헤이즐널 쇼콜라도 헤이즐향이랑 초코 향이 잘 어우러져요!! 그리고 비주얼부터가 빤짝거려서 너무 이쁘더라고요ㅠ 집들이나 선물로도 좋을것 같아요! 헤이즐넛이 듬뿍 들어가 있어 먹을때 끝까지 식감이 좋고 고소 달달해서 맛있었어료👍🏻 타르트지 자체가 버터향 가득한 고소한 맛이여서 기본부터 토핑까지 완벽✨', 64, 14, 'GOOD', SYSTIMESTAMP);
