INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '당일 생산되는 신선한 빵을 맛볼 수 있는 홍대 베이커리 맛집입니다! 빵 종류도 많고 맛있는 빵이 많아서 홍대 빵집으로 추천드립니다. 밤식빵, 오믈렛, 에그버거 포장해서 집와서 먹었는데 아주 맛있어요~!', 39, 2, 'GOOD', SYSTIMESTAMP);
