INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '크림치즈브라우니에 치즈가 통째로 들어서 치즈맛이 진하게 나요 달지않고 부드럽고 느끼하지않고 맛있어요 바게트가 진짜 고소하고 깊은 빵맛이 나요 진짜 맛있어요', 17, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '생치즈 같이 생겨서 사봤어요! 쌀로 만든 치즈케이크라는데 엄청 꾸덕하고 중간중간 릴 치즈가 씹혀서 식감도 너무 좋았어요❤️ 커피랑도 잘 맞구 와인 안주로 완전 잘 맞을것 같네용… 너무 맛있어서 그 자리에서 다 먹어 버렸어요🥺 꾸덕하면서도 촉촉하고 단단한 식감이 완전 취향 저격이네요! 치즈향이 엄청 찐한데 꼬릿한 치즈와 크림치즈 중간 정도에 짭잘하면서 달달해서 물리지 않고 계속 먹을 수 있었어요ㅠㅠ 너무 단 디저트 잘 못드시면 완전 추천해여👍🏻 중간중간 릴 치즈가 씹혀서 은은하게 치즈향도 계속 남아요 쌀로 만들어서 그런지 식감도 다른 치즈 케이크랑은 다르더라고요!! 종종 사먹을것 같아요 맛도 다른 치즈케이크보다 독특하고 맛있어서 보시면 한번 드셔보세요🍀', 41, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '홍대입구&동교동&연남동에서 유명한 "생활의 달인"에도 출연된 "빵나무"♥️♥️😋 이곳은 냉동생지나 냉동빵을 취급하지 않고 100% 수제빵을 선보이는 베이커리 맛집!!! 1. 탕종 80%들어간 우유 식빵을 비롯한 50%, 30%의 다양한빵 2. 냉동생지나 냉동빵을 취급하지 않고 100% 수제빵 3. 첨가물 free 4. 천연호밀발효종(르방) 무화과초코호밀깜빠뉴는 천연 호밀종을 이용해 쫄깃한 식감이 특징이고, 꿀과 감자반숙 숙성 발효를 거쳐 노릇하게 구운 담백하고 쫄깃한 깜빠뉴💖💖 호두브라우니는 촉촉~하면서 브라우니의 꾸덕한 식감이 살아있고 호두가 박혀있어서 너무 맛나요~😋😋', 108, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '생활에 달인에 탕종빵 전문점으로 나온 베이커리 맛집이에요! 내부는 작지만 먹을 수 있는 공간이 있으며 매일매일 빵을 굽는다고 합니다. 다양한 종류의 빵이 있어서 취향껏 고를 수 있어요! 어니언빵 추천👍', 46, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '블루리본 받은 생활의 달인 홍대 빵맛집 여기 깜빠뉴 진짜 겁나 맛있어요... 남은것도 에프에 구워서 버터랑 먹었는데 천상의맛... 여기는 주변 주민분들께서 자주오시더라고요 숨겨진 홍대 빵맛집같아요 일반 빵도 맛난데 요새 유명한 밤티라미수랑 마시멜로케이크도 있어서 담에 꼭 먹어보려고요... 진심 재야의 고수 같으세요..... 여긴 찐입니다 빵순이라면 여기꼭 와보세요', 0, 9, 'GOOD', SYSTIMESTAMP);
