INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '밀크티향이 좋아요 부드럽고 맛있어요. 탕종빵이 유명하다해서 이집의 시그니쳐 강남콩베기 먹어봤는데 콩이 달달해서 거부감이 없네요 빵도 쫄깃쫄깃 담백하고 맛있어요', 34, 1, 'GOOD', SYSTIMESTAMP);
