INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '홍대베이커리 빵나무! 다양한 빵이 있는 홍대 빵집입니다. 종류가 정말 다양하고 전부 맛있어보여요. 건강하면서도 맛있는 빵이라 더욱 좋아요~', 80, 16, 'GOOD', SYSTIMESTAMP);
