INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '몸에 좋은 탕종빵과 다양한 식빵이 있어요! 크림치즈 베이글을 먹었는데, 베이글과 크림치즈의 환상적인 조화네요! 빵이 촉촉하고 치즈는 부드러워요👍 워낙 다양한 종류의 베이커리들이 있고 맛있어서 데일리 또는 선물로도 좋을 듯 해요😃', 32, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '디저트 별로 안좋아하는데 여기 디저트들은 항상 맛있게 다먹어요ㅠㅠ  너무 달지도 않고 식감도 엄청 다양해요!! 편의점에서 파는거 먹었을땐 너무 달아서 별로라 기대없이 먹었는데 일단 밤이 어ㅓㅓㅓㅁ청 많아요🌰 어딜 퍼먹너도 밤이 한가득이라 너무 좋앗어요 크림도 짱부드럽고 항가득 퍼먹어도 느끼하지두 않았어요ㅠㅠ 한입 먹을때마다 햄복했슴니다💕 그리고 즁간즁간에 초콜릿칩? 같은게 계속 씹혀서 진짜 맛있규 크런티 가루 중간중간 있어서 눅눅하지도 않은게 진짜 킥이에요.😋😋😋 흑백요리사 티라미수 먹고싶으묜 편의점 말구 여기로 달려오는게 진짜 밤티라미수 즐길 수 있어요👍 이 티라미수는… 생존입니다❤️', 31, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '빵이 참 맛있어요. 빈속에 먹었는데도 느끼하지 않고 반죽이 엄청 부드럽고 고소하니 사람이 많은 이유가 있네요. 밤식빵 안에 밤도 가득 들어있고 강낭콩베기도 정말 고소하고 맛있으니 추천!!', 31, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '생활의 달인이 만드는 빵이라서 엄청 기대하고 갔어요 빵순이 입장에서는 전국 빵맛집 다 가잖아요 ㅎ 종류도 다양하고! 건강빵도 있고 디저트류도 엄청 많네요. 시식빵도 있어서 먹어보고 살 수 있어서 굿!! 👍 이번에 먹어보니 맛있어서 단골 예정입니다 ㅎ', 47, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '베이커리 카페입니다. 아늑한 공간이고 빵이 맛있습니다. 테이블도 몇개 있어 음료시켜서 빵을 먹고갈수 있습니다. 아침부터 외국인 관광객들도 다녀가네요.', 23, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '사장님도 항상 웃으면서 맞아주시는데 너무너무좋아요!! 기운없으면 걱정해주시고, 밝게오면 제 덕분에 가게가 밝아지는것 같다고 말씀해주시고ㅎㅎ 올때마다 마음이 포근해요♡ 빵덕에 저도 베이커리 운영해봤는데, 항상 빵도 맛있어요! 확실히 달인이 만드셔서 그런지, 너무달지도않고, 다른곳엔 없는 색다른 빵도 있구요!  재료도 좋음..!! 빵나무 오면 지친삶에 힐링되 느낌이에요!♡ 항상감사해요 사장님~ 새해 복 많이 받으시고 건강하세요♡', 85, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '마롱바게트, 강낭콩배기, 피칸파이 먹었는데 역시 탕종빵이라 촉촉하고 쫄깃하니 빵이 다 맛있어요. 피칸파이도 고소하고 달지않아 최고. 그치만 빵나무에서 마롱바게트랑 강낭콩배기가 특히 맛있으니까 꼭 사세요.', 2, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '홍대베이커리 빵맛집 빵나무 ෆ!!! 빵 종류가 진짜 엄청 많아서 좋았어용ㅎㅎ 가성비도 좋은데 맛도 미쳐씀 ... 현지인 맛집 너낌 생활의달인에 나올만큼 인증된 곳입니당🫶🏻', 4, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '11시 30분쯤 방문했는데 빵들 전체적으로 부족하지않게 다 나와 있었당ㅎㅎ 빵집 갈때마다 고민하는게 언제가야 모든 빵들이 구워져있는 시간대에 방문할수있을까 이런건데ㅋㅋㅋㅋㅋㅋ 진짜 새벽부터 구우시는듯ㅠㅠㅜ 역시 제과제빵 명인쯤 되려면 미라클 모닝은 필수인가요... 베이글 샌드위치 먹고 몇가지는 포장했는데 먹는내내 너무 맛있는 빵굽는 고소한 냄새가 나서ㅋㅋㅋㅋㅋㅋㅋ음... 행복했다 그리고 직원분들도 넘 친절하고 편하게 있다 갈수있는 공간이었음 짱! 담에 또와야지', 27, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '생활의 달인에 나온 빵집이라고 해서 다녀왔는데 이유가 있었네요! 빵도 부드럽고 천연발효종을 사용해서인지 소화도 잘되는거 같았어요 마늘바게뜨는 꼭 드셔보셔요! 찐추👍 자주방문할께요😋', 10, 3, 'GOOD', SYSTIMESTAMP);
