INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '홍대 빵집 빵나무 방문했어요. 생활의 달인에도 나오신 유명한 빵집이더라구요. 손님들도 많았어요. 빵 포장해서 먹었는데 저렴하고 너무 맛있네요. 건강하고 고소한 편이었고 빵종류가 다양해서 좋았어요. 다음에 홍대가면 또 들리고 싶은 홍대베이커리였어요~', 0, 3, 'GOOD', SYSTIMESTAMP);
