INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '매장 인테리어나 분위기, 사장님의 친절함, 그리고 커피와 빵의 맛과 퀄리티까지 모두 훌륭했던 홍대 베이커리 카페 빵나무 ❣ 탕종빵 전문점은 남다른가봐요.. 빵의 쫄깃함이 정말 남다릅니다 ㅠ.ㅠ 맛있게 잘 먹었습니다~! 나중에 빵지순례하러 또 올게요 😆✨❤️', 39, 4, 'GOOD', SYSTIMESTAMP);
