INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '진~짜 오랜만에 왔더니 인테리어가 바뀐것같네용 그래도 빵은 여전히 맛있고 사장님?도 친절하게 맞이해주셔서 기분좋게 맛있게 잘 먹었습니다!!!', 14, 7, 'GOOD', SYSTIMESTAMP);
