INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '요즘 유튜브에서 유행하는 스노우 코코를 해외직구도 아니고 홍대에서 이가격에 먹을 수 있는 게 너무 좋았어요❤️ 겉에 코코넛 가루도 너무 마싯구 안에 브라우니가 진짜 미쳤어요😋 겉에 마시멜로도 사장님이 직접 만드신거라 그런지 별로 달지도 않고 완전 퐁실퐁실해요ㅠㅠ 가격도 너무 착하고 크기도 크고 나중에 친구들 데리고 또 가려구옹 🫢🫶🏻🫶🏻', 20, 1, 'GOOD', SYSTIMESTAMP);
