INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '여기 진짜 짱.,♡ 우울할때 여기로 빵사러가야돼요.. 크리스마스의 울쩍한 기분을 날려준 곳..♡ 사장님! 새해 복 많이 받으세요~!!', 3, 7, 'GOOD', SYSTIMESTAMP);
