INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '지나가기만 하다가 맘먹고 들어왔는데 진작 와볼걸 그랬네요. 빵종류도 많고 맛도 있어요. 밀크티 맛이 좋네요. 빵먹으러 와야겠어요.', 69, 15, 'GOOD', SYSTIMESTAMP);
