INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '빵 종류가 다양한데 하나같이 다 맛있어요. 역시 블루리본 빵집 답네요. 먹었을 때 속도 편안하고 좋았어요. 다른 빵들도 하나씩 먹어보러 가려구요!!', 27, 7, 'GOOD', SYSTIMESTAMP);
