INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '마시멜로 빵이라고 하시길래 그냥 생김새만 마시멜로 처럼 생긴 케이크인줄 알았는데 겉에는 코코넛을 잘게 갈아서 눈꽃처럼 뿌려져 있고 브라우니 케이크 위에 진짜 마시멜로가 덮여있더라구요 너무 쫀득하고 코코넛이랑도 잘 어우러져 맛있었습니다 너무 달지도 않아 커피에 곁들이기 너무 좋은 디저트메뉴 같네요!!', 56, 16, 'GOOD', SYSTIMESTAMP);
