INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '생활에 달인에 내온 탕종빵의 달인 식빵의 달인 집인 빵나무 방문했습니다 홍대에는 아직까지도 빵순이인 제가 못가본 맛난 빵집이 많군요 이쪽 골목은 평소에 잘 다니지 않은 곳이였는데 이쪽도 자주 와야겠어요 ㅠㅠ 빵이 너무 맛있어요', 31, 3, 'GOOD', SYSTIMESTAMP);
