INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '소보루 크림빵, 베이컨베이글샌드위치, 슈크림빵 이렇게 3개 먹었는데 진짜 다 맛있어요.. 특이 베이컨베이글샌드위치 대박입니다.. 소스도 너무 맛있고요 사과도 너무 잘 어울리더라구요.. 양도 많아서 식사대용으로 강추드리고요.. 소보루 생크림빵이랑 슈크림빵도 너무 맛있었어요.. 생활의달인에도 나오셨다던데 정말 잘 되었으면 좋겠어요!!', 2, 9, 'GOOD', SYSTIMESTAMP);
