INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '요즘 유행하는 빵부터 빵나무만의 시구니처 빵들과 옛날 빵들이 다양하게 많아서 빵순이는 완전 눈 돌아갔어요-! 매장 내부도 깨끗해서 먹고 가도 좋겠더라구요~ 시식빵도 있어서 먹어보고 골랐는데 바로 호두 브라우니 픽해서 먹었습니당 ㅎㅎ 다른 메뉴들도 너무 맛있게 잘 먹었어용-! 갓나온빵들 최고!!', 39, 10, 'GOOD', SYSTIMESTAMP);
