INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '달지많고 슴슴한데 자꾸 손이가는 장인의 맛이랄까? 우연히 들어갔다가 샘플 먹어보고왕창 집에 사갔는데 티라미수, 연유크림바게트 다 달지 않고커피랑 먹기 딱이었어요! 생각 없이 먹다 오늘 산거 다 먹어서 저녁을 못 먹을 정도였다는건 안 비밀!', 27, 3, 'GOOD', SYSTIMESTAMP);
