INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '탕종빵으로 생활의 달인까지 나온집이라해소 궁금했는데 역시나 식빵종류 넘넘 맛있오요 ㅠㅠ 시식빵까지 있어서 먹어보고 구매할수있다는점. 직원분들 사장님까지 너무 친근하고 친절하시다는점. 빵도 그만큼맛있다는점!!!! 너무너무 맛있게 잘먹었어용!!', 18, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '리뷰 보고 맛있을것 같았는데 역시나 맛있었어요. 감동하여 리뷰를 안 쓸 수 없었음 ㅠㅁ ㅠ 쫄깃쫀득 신선한 빵~ 앞으로도 많이 팔아주세요 💓', 12, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '동생 생일을 축하하고자 숙소 근처 베이커리를 들려서 망고케이크를 샀습니다. 서프라이즈 준비한다고 다 사진도 찍고 했는데 확인해보니 포장하시다가 케이크도 완전 푹 파이에 찍으셨고 맛은 유제품이 발효되어 상한맛이 났습니다. 저도 사장님 입장을 아는 입장이라 리뷰를 남기고 싶지 않았는데 케이크 맛에 대해 가게를 다시 방문했을 때 나이 있으신 여자직원분께서 저희 앞에서 사장님께 전화를 걸어 저희 바로 앞에서 진상 취급을 하듯이 저희에 대해서 대화를 하셨고 사과도 없으신 채 반말도 하셨습니다. 베이커리에서 일해봤어서 저도 알지만 당일생산이냐고 여쭤봤을 때 바로 답해주지 않으셨고 생크림과 위에 토핑 과일 상태는 당일 생산이라고 하기에는 너무 말라비틀어져있었습니다. 환불도 완전 무시하면서 해주셔서 기분이 좋진 않았네요', 41, 10, 'BAD', SYSTIMESTAMP);
