INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '빵종류가 엄청 많습니다! 다 너무 맛있어보여서 고르는데 너무 힘들었어요 ㅠㅠ 카페음료들도 있어서 음료랑 빵이랑 같이 시켜먹기 젛을 것 같아요 ㅎㅎ 매장 안에 좌석도 꽤 있어서 먹고가기 좋습니다!', 73, 17, 'GOOD', SYSTIMESTAMP);
