INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '빵 종류도 많고 맛있어요! 사장님도 친절하셔서 기분이 좋아지는 공간입니다!! 먹고 갈 공간도 충분히 여유가 있으니 최고..👍🏻', 130, 20, 'GOOD', SYSTIMESTAMP);
