INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '소금빵 오 그냥 평타인데?했는데 먹다보니 쫄깃함 그자체! 강낭콩베기가 의외로 되게 맛있었다 쫄깃한 빵에 달달한 강낭콩이 가득들어있는데 조화가 참 좋다', 25, 8, 'GOOD', SYSTIMESTAMP);
