INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '빵나무!!! 역시 유명한 빵집이라고 해서 왔는데 너무 맛있어요 ㅠ 홍대 근처에 올 일 있으면 꼭 가야겠어요!! 맛꿀마!!! 꼭 한 번 와보세요!!', 26, 2, 'GOOD', SYSTIMESTAMP);
