INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '빵맛은 기본! 친절함에 한번 더 기부니업~~되는 홍대빵맛집! 카페음료페어링으로 빵데이트 가능~~ 홍대 베이커리카페로 시식빵까지 있는 내공가득 빵맛집였으요~~😘', 53, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '먹을 빵이 필요해서 근처에 있는 곳 검색해서 간 곳인데 종류도 이것저것 많고 좋습니다. 특히 사온 깡파뉴는 감자반죽 이용한 것이라 그런지 속질이 쫄깃한 그런 느낌으로 아주 맛있게 잘 먹었어요! 재방문해서 다른 종류들도 먹어보고 싶습니다.', 3, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '집에어자마자 먹어봤는데 방맛 미쳤음 이렇게 맛있다니;;; 블루리본 빵명장의 가게라더니 진짜 맛있어서 광광 우러요 에그버거는 고기 대신 계란들어있어서 다이어트에도 좋고 드레싱 미쳐버린 대존맛', 74, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '홍대 식빵 맛집 진짜 왜 빵지순례 필수코스인지 이제야 알겠어요... 식빵 최강달인 진짜 맞습니다 제가 여태 먹었던 식빵은 전부 가짜고 여기는 진짜 찢어지는 결부터가 차원이.다른... 식빵이 미친 빵집이에요... 다른 빵들도 퀄리티도 높은 편이고 다른 메뉴들도 무조건 도전해야하는 곳이에요... 꼭 다음에 가서 다른 빵들 사오려고요 아니 근데 가시면 무조건 식빵. 잊지마세요', 13, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '속도 편하고 맛잇고 건강빵집이네요^^ 직원언니도 유쾌하고 친절해서 넘 좋았습니다 이 어려운 시기에 시식빵까지 넉넉한 인심 감동감동♡', 49, 8, 'GOOD', SYSTIMESTAMP);
