INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '동네 빵 맛집이에요!!! 특히 베이글 샌드위치랑 탕종빵, 깜빠뉴 등등 식사빵이 맛있어요~~ 늦게가면 빵 없어서 오전에 가서 맛있는거 쟁이시길!', 42, 2, 'GOOD', SYSTIMESTAMP);
