INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '항상 오전에가다가 오후에 계신 아주머니 때문에 안가고 싶어지네요. 전화를 계속하셔서 뭐하시나 했더니 본인이 잘 못 들으시는걸 누차 확인하느라...뒤에 손님들 기다려도 나 몰라라 하시는 모습ㅠ 참 안타까웠습니다 빵나무 너무 맛있고 오전에 항상 계신 사장님 너무 친절해서 갔었는데 선물할 빵 천원 이천원이나 박스값 정확하게 받아내시는 모습에 몇 년동안 첨 보는 아주머니가 참 성공하시겠구나 생각하고 왔네요^^ 인상 그만쓰셔요ㅠ 무서웠어요 저기 아주머니ㅠ 저도 사업체 몇 개 운영하는데 천원 이천원에 돈이 아니라 민심 다 잃어요. 연남동에 밝고 성실하게 일하시는 빵집 많습니다 비록 전 앞으로 안가겠지만, 빵은 맛있어요 아주머니 ㅠ', 15, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '빵 종류가 많아요! 매장에서 바로바로 구워지는 빵이라 확실히 촉촉하고 고소해요. 바질페스토 좋아한다면 토마토포카치아 추천하고요! 딸기찹쌀떡도 쫀득쫀득한게 너무 맛있었어요. 무엇보다도 사장님이 친절하셔서 기분좋게 매장에서 좋은 시간 보낼 수 있었어요', 2, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '일단 사장님께서 친절하시고 빵도 너무 맛있고 가격도 착해서 다음에 또 오고싶은 맛집이였어요. 마침고른 도넛이 신상 딸기도넛이였는데 안에 딸기가 가득해서 감동이였습니다. 딸기모찌도 카푸치노랑 아메리카노도 정말 맛있었어요.', 118, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '홍대에 유명한 베이커리가 있다고 해서 방문했어요ㅎㅎ 커피도 고소하니 맛있고 빵도 다 맛있었습니다! 엄청 달거나 느끼하지도 않아서 물리지도 않네요ㅎㅎ 매장도 조용하니 좋았어요. 앉아있다보니 소금빵이나 깜빠뉴, 바게트 위주로 포장 손님이 많이 오시더라구요!! 저도 다음에 그거 먹으러 또 오려구요^^', 15, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '홍대에서 약속이 있어 홍대 빵집이라는 빵나무 다녀왔어요 저흰 먹고 왔는데 동네 빵맛집인지 배달 주문이 끊이지 않았고 픽업 손님도 계속 계셨어요 시식빵도 있고 빵 종류도 다양해서 취향에 맞는 빵을 먹기 좋을 것 같아요 ㅎㅎ 블루베리 타르트와 소금빵 먹었는데 소금빵 추천이요🥰', 3, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '생활에달인에 나온 집 답게 빵이 넘 맛있었었어요! 시식도 할 수 있어 직접 골라 먹어볼수있답니다! 에그버거 흑임자생크림팥빵 추천해용~!! 연남동 가면 꼭 가보세용!', 35, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '리뷰는 다섯 번째인데, 10년 넘게 단골이에요 중학생 때 처음 와보고 나날이 발전하는 사장님과 직원분의 제빵 기술에 감탄하고 있습니다 ㅎㅎ 물가 상승률에 비해 빵 가격은 거의 오르지 않아 사장님이 걱정되기도 하는데.. 그만큼 소비자들이 더 자주 가면 되겠죠? ☺️ 맛과 실력에 비해 언제나 겸손하시고 SNS에 많이 올라오는 여타 디저트 가게와는 다르게 넘나 만족스럽습니다 ㅎㅎ 다음에 또 올게요!', 61, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '우연히 지나가다가 지인이 한번 구경 가자고 해서 들어 간 곳인데 막상 땡기는게 없어 가려던 중 식빵 달인이라고 되어 있어서 식빵을 하나 구매 했어요 크기는 일반 크기 만하고 .. 탕종 식빵이라고 하기에 기대 했는데 .. 생각만큼 쫄깃하지 않아서 조금 실망했어요 맛도 크게 다른 맛집에 비해 좋다라는 생각은 안 들었구요 아무래도 워낙 빵지순례 많이 다니다 보니 제 기준이 높아 진 것도 있는 거 같습니다. 그리고 빵을 그냥 일반 위생 봉투에 담아서 진열해 놓은 것도 저는 조금 보기 안 좋았어요 하지만 한가지 품목은 너무 맘에 드는게 있어서 다음에 그걸 구매하러 한번 더 방문 할 거 같아요', 59, 15, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '확실히 뭔가 다른 빵집👍 블루리본이 왜 달렸는지 알것같은 훌륭한 맛과 품질 그러나 그에 비하면 너무 저렴한게 아닌가 싶은 가격ㅠㅠ 🧡 + 수제팥으로 만든 단팥빵은 시판앙금이랑 비교도 안되게 맛있어요 너무 달지 않아서 다른곳이랑 차별화가 되네요 👍그리고 깜빠뉴의 쫀득함이 진짜..ㅠㅠ 어디서도 못먹어요 너무너무×10 맛있었어요! 명인은 뭔가 다르네요.. 🤤 저는 또 조만간 들릴예정이에요 ㅎㅎ', 121, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '치아바타 갓 나온때에 운좋게 갔어요! 와 세상 쫄깃 부드러워서 놀랐어요.. 조카들도 잘 먹고 엄청 좋아하더라구요ㅎ 카스테라도 맛있는지 얼굴을 파뭍히고ㅋㅋㅋ 연유 바게트는 한정으로 판매하셔서 전에 갔을때 없어가지고 이번엔 가서 나오는 시간에 예약후 사왔어요 언니가 전에 시식했다가 사고 싶었는데 이번에 사오니 행복해 했습니당 행복을 주는 빵집이네요🥰', 34, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '서울 살면서 이런 곳을 몰랐다니!!!! 진짜 믿고 먹는 생활의 달인이에요 ㅋㅋㅋㅋㅋ 가격도 그렇게 비싸지않고 빵이 다 촉촉하고 재료가 아낌없이 들어간게 느껴져서 좋았어요!!', 15, 9, 'GOOD', SYSTIMESTAMP);
