INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '건강하고 맛있는빵 찾기힘든데 빵나무 넘 맛있어요!!!! 가격도 비싸지않고 넘 좋아요 시식해보고 엘리게이터 넘 맛있어서 바로 샀어요😝 사람이 많은 이유가 있네요! 다음에 또 올거에요🥰', 27, 9, 'GOOD', SYSTIMESTAMP);
