INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '생활의달인 파티쉐가 있는 빵집 답게 너무 맛나네요!👍🏻👍🏻 모든 메뉴 다 먹어보고싶어요🥹 딸기 크림 크라상 타르트는 마치 크루아상 위에 탕후루가 올라간듯한 식감 좋은 타르트였고, 베이글 샌드위치는 햄,치즈,양배추에 사과가 들어가서 너무 맛있었어요ㅎㅎ 크림이 한가득 들어간 적당히 달달해서 좋았던 생크림앙금빵이 신의 한수👍🏻 밀크티와 히비스커스도 딱 좋아하는 맛이어서 만족🫶🏻친절함은 덤인 기분 좋은 곳이에요!', 43, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '마포구 동교동 홍대권 베이커리, 빵나무 생활의 달인 탕종빵과 식빵 달인이 운영하는 소금빵, 앙금빵 등의 다양한 빵이 있는 맛집 흑임자생크림앙금빵과 생크림앙금빵,  쫄깃쫄깃한 빵피 안에 적당히 달달한 수제팥과 생크림, 흑임자 생크림이 들어있는 구성 마카다미아,  마카다미아, 크랜베리 등이 듬뿍 든 바삭바삭한 쿠키 같은 식감의 타르트 마롱바게트,  밤과 커스터드 크림이 들어있는 많이 질기지 않고 쫄깃쫄깃한 식감의 바게트 소금빵, 적당히 짭짤하고 기름진 쫄깃쫄깃한 식감의 담백한 소금빵 가성비 괜찮고 다양한 종류의 빵이 많아 홍대근처 간다면 방문해 볼 만한 곳 맛있게 잘 먹었습니다.😄', 1, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '홍대 왔다가 이 빵집 안가면 손해임 이 근처 직장인들의 간식 성지♡♡ . 저렴하고 건강하고 맛있기까지한 빵, 음료 종류 몹시 다양하고 시식도 할 수 있다 현금으로 8천원 이상 결제하면 수제잼도 주시는데 그게 미쳤어 너무 맛있단말야 ㅋㅋ 샌드위치랑 베이글샌드도 있는데 점심 못드신 분들 여기서 식사하시더라구 나두 포장해와서 저녁 대용으로 먹었는데 내용물이 알차서 영양구성도 좋구 포만감도 있구 좋았어 암튼 나의 베이커리 또간집 등극👍', 48, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '생각나면 내 돈 주고 사먹을 곳. 다른 메뉴는 모르겠는데 시식을 먹어보고 사먹게 된 호두 브라우니(￦4,500)는 어디서 먹어본 듯 친숙하면서도 적당히 달고 고소하고 다 했다. 동네의 오래된 빵집 느낌을 주는 곳. 나무 위주의 디자인으로 아늑한 느낌을 주고 일하시는 분도 친절했다.', 29, 9, 'GOOD', SYSTIMESTAMP);
