INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '저녁 쯤 도착해서 품절 된 빵이 많아서 아쉬웠어요ㅠㅠ 이야기 된다고 하니 다음부턴 꼭 예약하고 가야 될 것 같습니다! 구매 빵 중에 쌀 호두 브라우니가 진짜 존맛탱ㅋㅋㅋㅋ 달달한 빵 좋아 하신 분들에게 추천 드리고 유명한 흑임자 생크림 팥빵도 역시나 맛있었습니다! 마롱바게뜨 구매 하러 다음에 또 방문 해야 될 거 같아요ㅋㅋㅋ', 29, 5, 'GOOD', SYSTIMESTAMP);
