INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '아침으로 아이스 아메리카노랑 소금빵 먹었는데 소금빵 미쳤어요!!! 탕종빵 전문점이라서 빵도 쫄깃하고 소화도 잘 돼서 또 가고싶은 빵집입니다.', 24, 4, 'GOOD', SYSTIMESTAMP);
