INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '빵전문점답게 다른 베이커리랑은 다르게 무조건 달고 그런 맛이 아닌 진짜 은은하게 단맛(?)이 났어요. 여기 픽업 포장 주문도 많고 아주머니들도 많이 오시는걸 보니 검증된 맛집 너낌ㅎㅎㅎ 서비스로 콩빵(?) 주셨는데 콩 싫어하는데 진짜 밤빵 먹는것처럼 맛있었어요.', 10, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '딸기모찌 꼭 드셔보세요.. 완전 맛도리에요 ㅠㅠ 차차버거도 패티가 치아바타인거같은데 쫄깃하고 식감 미쳤구요 빵순이에게 너무 행복한 시간이었습니다 또 올래요', 13, 7, 'GOOD', SYSTIMESTAMP);
