INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '마감시간 임박하게 방문했는데 시식빵과 사장님의 친절한 설명으로 영업당해버려서 초코빵 하나 사야지했다가 다른걸 많이 사왔어요(초코빵 원래 없음)🤣오늘부로 빵나무는 소금빵 맛집 종결입니다. 버터가 아래에 몰려서 밑에 식감이 바삭하고 버터향이 풍부해요! 소금빵은 워낙 유명해서 마감전에 품절되는데 제가 남아있는날 방문한 거랬어요 ㅎㅎ 그리고 저 납작한것도 엄청 달고 맛있어요! 달인 식빵으로 유명하다는 식빵은 평범하게 맛있는 맛이었어요! 또 생각날때 방문하겠습니다!', 20, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '빵들이 다 맛있습니다. 오믈렛은 내용물이 풍성하고 올리브스틱은 큰 그린올리브가 통으로 5개나 들어가 고소하고 쌀호두브라우니는 고소달콤합니다.', 76, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '서교동 동교동에 11년째 살면서 온갖 빵집을 다 다니지만 결국 정답은 빵나무! 서교동 동교동 합정동 연남동 다~~~해도 거의 모든 빵이 가장 맛있는 빵나무!', 42, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '눈오는 날… 급하게 찾아 들어간 가게였습니다. 사실 크게 기대를 하지 않았는데… 생각 이상으로 너무 좋은 공간이었습니다. 빵은 맛있고, 친절하시며 공간은 깔끔하고… 잠깐 눈을 피해 들어갔지만 여러모로 좋은 시간을 보내고 나올 수 있었습니다. 자주 들를게요.', 31, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '홍대 인근 유명한 빵집인에요.  생활의달인 나오셨데요, 나올만해요 빵이 맛있어요 .10년 이상 한곳에서 운영한 빵집이에요. 홍대에서 빵 맛집 찾으신다면 여길로 오세요!  빵들 소화도 잘 되고 또한 식사 대용으로 먹을만한 빵들도 있어요. 안 내부도 아늑하고 언제든지 손님 반기는 분위기에요.', 11, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '소금빵과 식빵 맛집~^^ 출근 길이나 오후 간식으로 가끔씩 자주 가는데 소금빵이 조금 커졋다ㅎㅎ 금일 혼자 삼실서 바쁠 예정이니 아점으로 크로와상과 소금빵 후딱 헤치움ㅋ 맛.나.다.ㅎ', 80, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '간단히 소금빵만 사오려다가 다 맛있어보여서 충동구매 해버린 홍대 빵집 빵나무! 생활의달인에도 나왔다길래 믿고 구매했습니다 빵들이 다 쫄깃하하고 맛있메요 특히 레몬파운드가 너무 달지 않아서 딱 제 취향이었습니당 ㅎㅎ', 129, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '탕종빵, 식빵 생활의 달인으로 나온 곳인데 홍대 로컬맛집이예요 빵 고르는 동안 평일 한적한 낮시간에도 빵 많이 사가시더라구요! 솔직히 크림은 빵 전문이고 건강한 느낌으로 맛없을까 걱정했는데.... 웬만한 크림빵 전문보다 더 맛있었어요 막 달기만하고 아무 맛도 안나는 밍밍한 맛 아니고 적당히 단맛에 풍미있는 우유 생크림 느낌! 5개 구매했는데 실패한 빵 하나없이 하나만 담아온게 후회스러워요 다음에 무조건 재방문입니다', 18, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '입구에서 너무 맛있는 빵 냄새가 나서 홀리듯 들어간 곳이예요~ 블루리본도 받고 생달에도 출연한 곳이더라구요! 정말 장인이 만드신 느낌이예요 빵 종류가 많고 가격도 합리적이라 앞으로 종종 들를게요', 64, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '탕종빵, 식빵이 유명하다고 해서 왔어요! 근데 왠걸 디저트류부터 케이크까지 종류가 넘넘 다양하잖아요..🫶🏻 블루리본 달만합니댜!!! 거기다가 주변 빵집대비 가격도 넘 착해서 잔뜩사도 부담이 덜한것도 큰 장점이에요☺️☺️', 8, 10, 'GOOD', SYSTIMESTAMP);
