INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '홍대 베이커리 맛집 빵나무...♡ 베이커리 명장이 만들어 그런가 더더욱 맛나고 쫄깃해서 잘먹었어요~~ 특히 요즘 모든 음식이 다 넘 자극적이기 마련인데 여기 빵은 먹고 나서 속 더부룩한 게 없어서 참 좋네요!! 특히 베이글 샌드위치 진짜 맛있습니다... 샌드위치 좋아하시는 분들께 완전 추천드려요 ㅎㅎ 수제잼은 진짜 엄마가 집에서 푹 끓인 그런 맛이라 달달하니 빵이랑 곁들여먹기 정말 좋았어요 ㅎㅎ', 39, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '아는사람만 아는 동네맛집이에요 생활의달인 나오셨데요, 나올만해요 빵이 맛있어요 홍대갔다가 집에오는길에 빵사오는집이에요 인테리어도 옛날 미팅하던 빵집(?)처럼 생겨서 귀여워요 홍대에서 빵 맛집 찾으신다면 여길로 오세요! 깜빠뉴 강추구요 식빵 진짜 보들보들 맛있어요 소화도 잘 되요 어르신들도 편히 드실 수 있어요 양과자선물세트도 판매하니까 선물하실일 있으시면 추천합니다. 맛있어요!!', 0, 8, 'GOOD', SYSTIMESTAMP);
