INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '빵들이 넘 맛있어보여서 못고르다가 최애 빵들로 구매하고 먹고 갔는데 완전 맛있고 가볍고 든든하게 잘 먹었어요:) 호밀깜바뉴에 바닐라 애플잼 사서 발라먹었는데 잼이 내 마음까지 발라벌인건 안비밀', 19, 6, 'GOOD', SYSTIMESTAMP);
