INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '동교동 데이트갔다가 만난 인생빵집🫶🏻 탕종빵으로 유명하던데 쫀득한 식감이 매력적인 식빵과 버터의 풍미가 완벽한 소금빵, 고소한 크림이 가득한 흑임자 생크림팥빵! 이렇게 크림이 많으면 느끼할만도한데 꼬숩 그 자체 🖤 동교동 베이커리는 무조건 빵나무로~🍞', 41, 4, 'GOOD', SYSTIMESTAMP);
