INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '우리는 마살라차이 4000원과 히비스커스 4000원, 게랑드 소금빵 2800원과 마롱 바게트 5000원을 주문했다. 잘라주신 빵이 마롱바게트고, 오른쪽 작은 빵이 게랑드 소금빵이다. 게랑드 소금빵은 게랑드 소금을 사용한 소금빵이다. 버터 풍미가 진하게 느껴지고, 소금이 별로 짜지 않아 소금이 얹어진 부분을 먹어야지만 짠맛이 미세하게 느껴졌다. 마롱 바게트란 커스타드 크림과 큼직한 밤 조각이 가득 들어간 빵이다. 바게트 윗면은 일반 바게트 식감인데, 빵 속과 빵 아랫면은 말랑하다. 달달한 고급진 맛의 커스타드 크림과 밤이 잘 어울린다. 소스가 넘 맛있는데 전체적으로 빵에 골고루 발라져 있어서 좋았다.', 70, 17, 'GOOD', SYSTIMESTAMP);
