INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '연남동에서 가장 퀄리티 넘치는데 가성비 넘치는 빵집이에요! 빵 비주얼 하나하나 완벽해서 고르는 것도 힘들었는데 매장고 조용하고 너무 편안하게 일요일 잘 보내다 가요!!!!! 빵이 부드럽고 먹기도 아까운 비주얼인데 맛있어서 다 먹어버렸어요🐷', 46, 4, 'GOOD', SYSTIMESTAMP);
