INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '동교동 베이커리 맛집이에요!👍 빵 엄청 좋아해서 여기저기에서 많이 먹어봤는 데 빵나무는 매우매우 근본있는 맛이에요. 빵의 달인께서 만든 빵은 역시 달라요👍👍 베이글 특히 쫀득하고 완전 맛있습니다. 다음엔 식빵이랑 크로와상도 꼭  먹으러 올거에요😄', 0, 7, 'GOOD', SYSTIMESTAMP);
