INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '홍대 빵나무 깜빠뉴 맛집이예요!!! 쫄깃하고 고소한게 건강빵 매력을 제대로 느낄 수 있습니다ㅎㅎ소금빵은 특히 제 인생 소금빵으로 등극했습니다ㅠㅠ뒷부분은 바삭하고 안은 촉촉하고 담에가면 남은거 다 사오려구요!', 37, 8, 'GOOD', SYSTIMESTAMP);
