INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '✔연유크림바게트 4200 연유크림 부드럽고 바삭한 바게트랑 잘 어울려요 ✔깜빠뉴 5000 소화도 잘되는 깜빠뉴, 생활의달인 탕종빵 달인이 하는 맛집 인정 고소하고 부드럽고 쫀득하고 빵 잘하는집! ✔도쿄만쥬 2000 감자맛도 나는 것 같고 풍미가득한 흰앙금이 들어간 빵', 8, 2, 'GOOD', SYSTIMESTAMP);
