INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '대박𖤐 빵생빵사로 빵 정말 주식처럼 먹는데 탕종빵만 먹게 될것같아요 맛있고 식감이 쫄깃+부드러운데 감동의 맛이네요 :) 포장 기분좋게 가족들이랑 먹는데 두번 감동이고 더운날씨에 아바라 한잔도 했는데 맛있어서 깜놀했어요 홍대입구역 1번출구에서 신호등 건너 골목길 우회전하니까 바로 나와서 위치도 기억하기 좋을 것 같아요 본가에서 버스 한방위치라 애용할게요 번창하세용!!', 56, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '홍대 숨은 빵맛집 ! 소금빵, 생크림빵 최고네요 진짜🙊💗 기본적으로 빵피가 쫄깃하고 맛있어요. 동네빵집 느낌인데 없는 메뉴가 없구 가격도 착한 편! 탕종빵맛집답게 속 편하구 좋은 재료 쓰는 느낌이 들더라구요. 여긴 홍대 갈 때마다 갈꺼 같아요... 아 그리고 남자 직원분 진짜 친절하시구 빵 추천 잘 해줘요!!!', 16, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '가게를 들어가자마자 빵 냄새가 확! 나더라구요 빵 종류도 굉장히 다양하고 다 너무 맛있게 생겨서 고르는데 한참 걸렸어요ㅠㅠ 사장님도 너무 친절하셔서 기분 좋게 다녀왔던 곳!! 빵도 맛있었어요!! 카페전문 유튜브 유리소리TV', 308, 80, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '맛있는 빵이 가득하고 주변에서 선물도 많이 주는 곳이여서 어디인가 하다가 이번에 방문해보게 되었어요~ 너무 쫀득하고 맛있는 빵들을 먹어보고 탕종빵이라는걸 알게되었네요! 동네주민분들도 많이들 오시던데 조용히 커피한잔하면서 빵먹기에 너무 좋아요! 빵을 밥먹는것만큼 사가버렸네요 ㅎㅎ 잘 먹고 갑니다!!!', 38, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '좀 일찍 가서인지 모든 메뉴가 나와있진 않았지만 ㅎㅎㅎ 너무 맛있게 먹었어요 티 메뉴도 다양하고, 무엇보다 빵들이 속이 편안하고 느끼하지 않아서 좋았어요! 쌀로 만든 호두 브라우니랑 마롱바게트 짱 추천', 98, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '빵이 너무 맛있어요ㅠㅠ 방송에도 많이 나온 맛집이라더니 왜 유명한지 잘 알겠는 맛입니다. 달달구리한거 좋아하시면 흑임자생크림팥빵이랑 마롱바게트 추천드리구요, 짭잘한 빵 좋아하시면 소금빵이랑 올리브스틱빵 추천드려요! 밤식빵은 디저트로도 좋고 식사대용빵으로도 좋은데다가 안에 밤이 진짜 가득 들어서 너무 맛있으니까 꼭꼭 드셔주세요ㅠㅠ 믹스커피나 우유랑 먹으면 최고의 조합입니다! 이상 맛잘알의 빵 후기였습니당😘😘', 127, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '동교동 베이커리 카페 빵나무는 생활의달인이 만드는 빵으로 정말 맛있었요 ㅎㅎㅎ 종류도 엄청 많아서 고르는 재미가 쏠쏠 ㅎㅎ 동네 주민들이 포장 주문을 많이 하더라구요!! 식빵 먹으러 다음에 또 방문하려구요 ㅎㅎ', 36, 3, 'GOOD', SYSTIMESTAMP);
