INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '빵 가격은 저렴한데 맛은 넘 좋네여 🥹🥹  소금빵은 안에 버터향이 가득하구 겉은 살짝 바삭한데 속은 넘모 쫄깃하고 맛잇써요! 마롱바게트 크림단팥빵 연유크림바게트도 넘맛잇어요!! ㅋㅋㅋ시식빵도 잇고 정감 가는 동네 빵집인데 빵 종류들은 요즘 유행하는 빵들도 다 잇고 넘 좋네요 😻😻❤️❤️', 38, 7, 'GOOD', SYSTIMESTAMP);
