INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '홍대에서 유명한 빵집이라 방문했는데 소금빵 진짜 대박이에요! 너무맛있고 올리브빵도 맛있고 에이드도 최고💜 너무 맛있어서 포장도해가요😄', 90, 17, 'GOOD', SYSTIMESTAMP);
