INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '소금빵이랑 카스테라, 밤식빵 너무 맛있어요!! 카스테라는 넘 부드럽고 소금빵이랑 밤식빵은 쫄깃하고 담백한게 너무 맛있어요 다른 빵들도 너무 맛있을거 같아요 빵순이라 매일 들릴거 같아요~!', 13, 9, 'GOOD', SYSTIMESTAMP);
