INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '정말 맛있는 빵들이 있어요... 진짜 날 잡고 모든메뉴 하나씩 다 먹어봐야하는집...!! 식빵달인 땅콩빵달인 명패도 있으시더라구요!!! 다들 알았으면 좋겠어서 리뷰 남깁니다!!!', 481, 32, 'GOOD', SYSTIMESTAMP);
