INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '동교동 베이커리 카페 빵나루!! 바게트빵, 체리페스트리빵 먹었는데 맛있었어요!! 추천!! 매장도 깨끗하고 빵순이들에게 딱인 곳이에요. 동교동 데이트 하시면서 베이커리 카페 찾는 분들 가보세요~', 237, 79, 'GOOD', SYSTIMESTAMP);
