INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '빵 종류 진짜 많아요! 그리고 생활에 달인에 나온 달인 빵집이라 빵이 진짜 맛있었고 음료는 가성비 대박이에용! 홍대에서 4천원 아메리카노라니🤍🤍 대박나세요🤍', 47, 10, 'GOOD', SYSTIMESTAMP);
