INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '동교동 베이커리 생활의 달인 빵집이에요! 주말에 먹을 빵 사러 왔다가 커피 한잔 시켜서 빵 먹고 있는데 맛있네요! 아침 일찍부터 빵 만드시는거 같은데 맛이 궁금해서 종류별로 담았어요! 소금빵, 슈크림빵, 밤식빵, 연유크림바게뜨, 강낭콩베기 이렇게 골랐는데 빵 맛있네요! 소금빵은 밑은 바삭 위는 버터풍미 가득 좋았어요. 콩 좋아해서 강낭콩배기 골랐는데 요것도 콩의 단맛과 함께 먹기 좋았어요. 빵 가격도 마음에 들어요!', 21, 0, 'GOOD', SYSTIMESTAMP);
