INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '식빵 최강 달인의 빵집 빵나무! 홍대 빵집으로 유명한 베이커리 카페 빵나무. 커피 양도 많고 디저트도 맛있고 가성비까지 굿입니다! ^^ 동교동 베이커리 찾으신다면 빵나무 강추합니다! 👍', 47, 10, 'GOOD', SYSTIMESTAMP);
