INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '빵들이 하나하나 다 맛깔나보여요ㅋㅋ!! 동네빵집인듯 요즘빵집인듯 다양한 메뉴들이 있는데 빵 자체를 잘하는 집이구나 싶더라구요! 깜파뉴랑 포카치아도 존맛...🤍', 125, 24, 'GOOD', SYSTIMESTAMP);
