INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '흑임자생크림팥빵 대박! 생크림이 흑임자x100 그 자체...! 할미입맛 취향 저격입니다 ㅠㅠㅜㅜ 빵이 쫀뜩하고 말랑해요 ㅜㅜ 동교동 베이커리 맛집으로 왕추천입니다!!!', 35, 1, 'GOOD', SYSTIMESTAMP);
