INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '매장에서 먹었어요, 빵집이라 기대안했는데 밀크티가 특히나 맛있어서 놀랐습니다! 향긋함이 완전 고급진 ㅎㅎ 그리고 빵은 정말 부드럽고 맛있었는데, 슈크림빵은 크림이 달콤하니 좋고, 소금빵은 바닥 부분과 겉부분이 바삭하고 속은 쫀득! 마늘 바게트는 달콤한 마늘 소스가 부족함 없이 있어 가격대비 만족도가 높네요 ㅎㅎ', 39, 6, 'GOOD', SYSTIMESTAMP);
