INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '디저트 먹으러 방문했는데 빵맛집인듯 한 분위기. 빵종류도많고 디저트도 다양합니다. 내부에 인테리어도 깔끔하고 먹고가기에도 딱 좋네요! 블루베리타르트는 블루베리향이 진짜 진하고 맛있어요! 티라미수페스츄리? 이것도 위에 찐한 티라미슈에 파삭한 페스츄리조합이 넘 맛나네요! 빵들도 맛이 진하고넘맛있는데 에이드마저도 엄청 진한맛ㅋㅋㅋ 너무 마음에드는 디저트집을 발견했습니다', 29, 3, 'GOOD', SYSTIMESTAMP);
