INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '오옹 역시 홍대 베이커리 맛집답게 빵 종류가 꽤나 다양했어요 타르트 종류도 과일이 가득 올라가 있어서 맛있어보였어요 딸기타르트 먹어봤는데 달달하고 타르트부분은 묵직하니 맛있더라구용 글고 마늘바게트가 찐맛이었어요 추천!', 71, 11, 'GOOD', SYSTIMESTAMP);
