INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '아침에  소금빵 주문했는데요 뜨거운김이 안식었을까 하여 사장님이 이렇게 포장해주셨어요~ 맛있게 먹으라는 사장님배려에 감동 했어요~~~♡♡♡ 사무실도착하자마자 먹었는데 따뜻하니 너무 맛있게 먹었어요~', 91, 20, 'GOOD', SYSTIMESTAMP);
