INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '마누카꿀카스테라, 강낭콩배기빵, 흑임자크림팥빵, 소금빵, 엘리게이터, 밀크티 다 맛있네요~ 엘리게이터 맛집이라더니 정말 많이 달지도 너무 바스러지지도 않고 딱 담백하니 맛있어요. 흑임자팥크림빵도 진짜 너무 너무 고소하고 맛있어요ㅠ 탕종식빵은 서비스로 주셔서 먹어봤는데 엄청 쫄깃담백하니 너무 맛있어서 집에 가는길에 또 사가려고합니다!!!', 13, 10, 'GOOD', SYSTIMESTAMP);
