INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '깜바뉴 5000원 처음 먹어보는 식감의 깜바뉴에요 신기해요! 식감은 겉은 질긴데 안은 촉촉하면서도 쫄깃하고 무슨 알갱이가 씹히는데 아마도 감자로 추측이 되어요! 새콤? 시큼? 하기도 해요! 호불호가 있을 빵 같은데 저는 호에요! 맛있어요!', 18, 8, 'GOOD', SYSTIMESTAMP);
