INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '빵 종류도 많고 다 너무 맛있어보여서 고르는데 힘들었네요ㅎㅎ 사장님도 친절하시고 기능장에 생활의 달인이라 더 믿고 사먹었습니닷 빵맛집이에용', 118, 20, 'GOOD', SYSTIMESTAMP);
