INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '매장입구부터 엔티크하고 맛집 느낌이 가득해요 이미 홍대입구에서는 빵 맛집으로 유명한 곳이에요😆 빵 종류가 매우 다양했는데 기본 바게트 종류부터 시작해서 유명한 마늘 바게트와 아이들이 좋아할 애플파이, 슈크림빵, 또 요즘 아주 핫한 소금빵, 흑임자 생크림 팥빵까지! 빵 종류가 정말 다양했어요🤤 식사대용으로 든든하게 먹을 수 있는 에그버거와 선물용으로 좋을 것 같은 구움과자류까지! 종류가 다양한게 너무 좋았어요😆 저는 유명한 밤식빵과 토마토 포카치아를 먹어봤습니다! 탕종식빵답게 식빵류가 정말 맛있었어요', 16, 5, 'GOOD', SYSTIMESTAMP);
