INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '인생 빵집인거같아요.. 타르트 밑에서 보들보들해서 잘 자를수 있고 너무 맛있어요 음료도 맛있구요! 가게분위기도 너무 예뻐요ㅜㅠ 빵나무가 이름인 이유는.. 역시 나무에서 빵이 열리는거겠죠 넘 맛있어영..🫢', 26, 9, 'GOOD', SYSTIMESTAMP);
