INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '아는 사람은 다 아는! 이미 너무 유명한 빵맛집입니다 저도 n번째 방문인데요 여전히 맛있더라구요 소금빵이랑 연유바게트 바삭하니 다음에 가도 또 구매할것 같아요~~', 40, 1, 'GOOD', SYSTIMESTAMP);
