INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '연남동 빵나무 유명하죠! 최근에 알게되어 방문 해봤는데 혼빵 하며 먹기도 좋고 종류도 다양해요. 시식가능한 빵도 있어서 먹어보고 구입 할 수도 있고요 옛날 빵집 같은 감성이에요. 탕종빵!???이라고 하는데 빵맛모르는 1인은 그냥 다맛있게 먹었어요 ◡̎', 23, 10, 'GOOD', SYSTIMESTAMP);
