INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '탕종빵은 처음먹어봤는데 확실히 일반빵들보다 훨씬 쫄깃쫄깃하고 맛있었어요~~!!🥹 빵종류가 엄청 많아서 뭘먹어야할지 엄청 고민하다가 깜빠뉴와 딸기타르트, 소보루빵을 포장해와서 먹는데 맛있어서 몇개 더 사올걸~ 하는 생각이 드는 맛이었습니다👍🏻 매장 분위기도 조용하고 아늑해서 빵과 커피한잔을 하며 대화하기에도 좋아보였어요~! 생활의 달인에 나왔다고 해서 찾아간 빵맛집인데 바로 납득 되는 빵맛들 ㅎㅎ 맛있게 잘 먹었습니다~~☺️', 32, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '빵종류도 많고 우선 빵이 진짜 담백해요ㅜㅜ 입에 감겨요ㅠㅠ!! 마늘빵도 촉촉하고 2번째 사진 브런치뭐시기 빵인데ㅜㅜ 이거강추!! 진짜ㅠㅠㅠ', 122, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '요즘 직접 만드는 집 찾기도 어려운데 하나하나 손수 만드시는 베이커리에요~ 생활의 달인, 블루리본 등 맛집 인증이 되어있는집이라 친구가 완전 맛있다고 추천까지 해줘서 가봤는데 완전 동네 빵집 넘버원이라고 보심 되요👍👍 빵 종류도 많구요~ 제가 오후 1시쯤 갔는데, 빵 제일 많을 시간이라고 하니 꿀팁 받아가세요😆 시식빵도 있어요!! 매장 자리도 넓어서 친구랑 먹으면서 수다 떨기 딱 좋은집! 커피랑 티도 좋은거 쓰시더라구요 너무 맛있었어요~ 선물 세트도 판매하고 있어서 이번 설날선물도 샀네요🤗 맛난빵 만들어주셔서 감사합니다🥰🥰', 9, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
