INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '탕종빵의 쫀득한 식감을 알아버렸어요!! 너무맛잇어요 그리고 소금빵 밑부분이 바삭하고 안은 촉촉하고 한입베어물면 고소한 버터랑 쫀득한 식감이 너무맛잇어서 순삭이에요 거리 멀어도 종종 들리려구요😆', 39, 3, 'GOOD', SYSTIMESTAMP);
