INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '오늘 젤라또 먹으려했는데 부재중이라 안계셔서 빵나무에 와서 하트후레즈 2개랑 고규 1개를 샀는데 하트후레즈가 조금  딱딱한것 같아서 4천원 블루베리 타르트를 고를걸 약간 아쉽습니다ㅠ 마들렌이나 타르트가 더 괜찮을것 같습니다', 45, 7, NULL, SYSTIMESTAMP);
