INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '1. 빵이 너무맛있다. 엘리게이터랑 도쿄만주...줜맛 근데 스톨렌이 제일맛있음 진짜 이건 꼭사야해요 2. 사장님 너무친절하십니다! 3. 빵 가성비 미침... 이퀄리티에 이가격?? 꼭방문하세요 4. 생활의달인분이 하시는곳! 5. 홍대에서가까움! 포장해서 가기도 좋음!! 담주에 또 올지도...??', 41, 9, 'GOOD', SYSTIMESTAMP);
