INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '여러 손님들이 고르는데 시간이 걸리니 상당히 불친절하게 “계산하실거예요?” 라고 돌아가며 물었습니다. 왜 저렇게 싸가지 없냐며 빵을 안 사고 나간 손님도 있었습니다. 직원분이 바쁘시면 “고르시면 말씀해주세요”라고 표현해도 이해할텐데요. 지난번에는 이 분이 아니었고 친절했는데…. 기분 나빠서 다시 가진 않을것 같아요.', 13, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '먹고싶은 빵이 한가득이라 고르는게 어려웠어요ㅠㅠ 탕종식빵은 무조건! 꼭! 사야해요ㅎㅎ 가격도 정말 합리적이고 엘리게이터도 오랜만에 만났는데 맛있었어요! 또또 갈게요❤️', 14, 2, 'GOOD', SYSTIMESTAMP);
