INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '맛있어요 엘리게이터는 먹어본거중에 가장 맛있었어요 안 딱딱해서 좋았습니다 생크림빵은 생크림이 약간 느끼했는데 나머지빵들은 다 맛있었어요 늦게가도 빵 종류 많았어요', 115, 24, 'GOOD', SYSTIMESTAMP);
