INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '홍대베이커리 생활의달인 마포빵집 빵나무 총평 역시 생활의 달인에 나올만한 빵 맛집 인정! 신기방기 & 예쁜 빵들 많음 생크림 덕후라면 꼭 방문하여 드셔보세요! 기회가 된다면 재방문 의사 200% 지인에게 추천하고 싶은 홍대 베이커리 빵집 ​', 2, 3, 'GOOD', SYSTIMESTAMP);
