INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '여기 빵은 진짜 다른 것 같습니다! 특히탕종식빵은 삼일을 두고 먹어도 하나도 한푸석거리고 쫄깃함이 유지되는게 대박이에요…! 빵도 미리 원하는거 주문도 가능하고 종류도 은근 다양해서 동네에 이런 빵집 최고입니다 ㅠㅠ', 30, 9, 'GOOD', SYSTIMESTAMP);
