INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '깔끔한 외관의 빵집이 있길래 들어가서 구경하다가 시식해본 호두 브라우니가 너무 맛있어서 바로 구입했어요! 달달하고 촉촉하니 안에 씹히는 호두가 아주 고소하고 좋았습니다!', 11, 3, 'GOOD', SYSTIMESTAMP);
