INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '갓나온소굼빵 진짜 겁나맛있어요 제가먹어본집중에 소금빵 젤맛있어요ㅠ 기름진거 버터맛 좋아하시는분들은 꼭가보시길  버터즙 쫙 나오는 저 꼬다리만 모아먹고싶어요 엉엉', 40, 6, 'GOOD', SYSTIMESTAMP);
