INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '회사 다닐때 자주 사먹던 곳인데 오랜만에 방문했어요 양추절임 들어간 소세지빵을 좋아했는데 그건 안보이네요 그 소세지빵이랑 생크림팥빵 맛있어요.', 0, 2, 'GOOD', SYSTIMESTAMP);
