INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '밥먹고 당연히 찻집이죠 ㅎㅎ 끌리듯 들어간 찻집인데 빵이 맛나나봐요. 있는동안에 구매해서 가시는 분들이 많더라구요. 커피도 빵도 맛나고 친구랑 편안히 애기했네요', 25, 2, 'GOOD', SYSTIMESTAMP);
