INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '식사대용으로 먹기 좋은 탕종식빵 바게트부터 소금빵 깜빠뉴 밤식빵 앙금빵 마늘빵 크로와상 페스츄리 달콤한 타르트까지 다양해요 생활의 달인이 만든 탕종식빵을 먹어보고 싶었는데 아쉽게 매진이라 밤식빵으로 먹고 왔어요', 30, 9, 'GOOD', SYSTIMESTAMP);
