INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '우와우와!! 생활의달인에 나오신 빵명장님이 하시는곳이네요~~탕종빵이래요.. 겉이 바삭하면서 속은 부드럽게 쫄깃!! 딱 제가 좋아하는 스퇄~ 소금빵이랑 식빵 강추합니다.. 무한흡입 주의^^', 98, 24, 'GOOD', SYSTIMESTAMP);
