INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '에그브런치 원래 개별로 봉지에 담아주셨던거 같은데 오늘은 두개 겹쳐서 봉지에 담아주셨네요 소금빵은 당연히 그럴수 있는데 기름 잔뜩묻은걸 겹쳐서 주시면… 직장사람들 나눠주려고 산건데 더럽게 포장해주셔서 결국 제가 먹었어요 ㅜㅜ 빵은 여전히 맛있지만 가격도 오르고 주인아주머니분이 아니셔서 그런지 친절하지도 않고.. 실망 마니했습니다', 13, 5, 'BAD', SYSTIMESTAMP);
