INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '내사랑 흑임자크림빵 먹으러 왔어요. 빵도 부드럽고 크림맛은 말해뭐해요.. 그냥 단팥크림빵도 맛있지만 여기 흑임자크림빵은 좀 짱이에요..', 40, 8, 'GOOD', SYSTIMESTAMP);
