INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '지나가다 고양이가 생선냄새 못참고 지나가다 이끌리듯 들어간 빵집.. 다이어트중이라 눈물로 마카다미아파이 하나 먹었는데 맛이 기가막히네요? 노티드랑 같이 먹었는데 맛이 진해서 도넛담에 먹길 잘함', 36, 9, 'GOOD', SYSTIMESTAMP);
