INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '사진을 못찍 ㅠㅠㅠ 너무 맛있어요 여긴 모든빵이 맛있는듯 .... 그리고 직원분 친절하셔서 좋아용 가격만 더 올라가지 않았으면...', 46, 9, NULL, SYSTIMESTAMP);
