INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '하ㅠㅠ진짜 하나하나 맛없는거 없이 다 넘나 맛있어요😭😭😭😭제 인생빵집입니다ㅠㅠ친구들한테도 널리널리 알려야겠어요❤️❤️담ㅇㅔ 재방문하면 다른종류 빵도 털어올거예요~헿', 5, 1, 'GOOD', SYSTIMESTAMP);
