INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '🍞 탕종빵 (6.0) 🥐 소금빵 (개당 2.5) 🥯 비스킷소보루 (1.8) 🧈 고규 (2.2) 💗 하트후레즈 (2.3) 2013.06.24 생활의 달인 386회 탕종빵의 달인으로 나온 바로 그 베이커리 맛집🍞 탕종빵 : 탕종제빵 방식으로 만든 식빵. 끓는 물로 반죽을 하고 반죽기계에 꾸준히 열을 가해 숙성시켜 반죽하므로 일반식빵보다 촉촉하고 쫄깃하며 소화흡수가 잘되는 탕종빵이예요 그냥먹어도 맛있고 토스트해서 크림치즈 발라먹어도, 샌드위치해먹어도 맛도리 🍞💛 소금빵 : 소금빵을 너무 좋아해서 어떤 빵집을 가든 소금빵은 다 사막어보는데 그냥먹어도 에프에 돌려먹어도 무난하게 맛 괜찮은 소금빵이였어요 🥐', 9, 3, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '만델(2,200) 아몬드가 가득 올라가있은 타르트. 가격대비 매우 만족. 타르트중에서는 만델이 제일 괜찮아요. 강낭콩베기(2,400) 강낭콩이 안쪽에는 없고 거의 외각쪽으로 다닥다닥 붙어 있음. 빵이 쫄깃한 식감이다', 41, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '여기 처음에 갔을 때 여자사장님도 엄청 친절하시고 아침 8시 전부터 나오셔서 빵을 굽는 남자 사장님도 정말 대단하다고 생각했음 빵도 맛있고 커피도 맛있는데 아침에 일하는 여자 알바생분이 좀 문제인듯 커피 머신기 돌리면서 뭐라고 말씀 하시는데 안들려서 되물었더니 소리지르듯이 답하는 태도(머신기 시끄러운데 그렇게 주문을 받았어야 했나?) 그리고 아침에 커피사면 연유식빵을 주는데 빵이 나왔어야할 시간에 안나왔으면 미리 말을 해주던지 커피를 주시면서도 아무말없길래 연유식빵은 없는거냐 그러니까 죄송하다는 말도 없었음. 같은돈 주고 다르게 먹어야하나? 나중에 다시 갔을 때 챙겨주긴 했지만 이러한 태도의 문제가 너무 큼 [이제 안감]같이 간적 없는 직장동료랑 나중에 이야기 했는데 똑같이 느꼈음', 44, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '정말 자주 애용하는 빵집입니다. 탕종빵이라고 생활에 달인에도 나오시고 유명한 빵집인줄은 알고 있었는데 정말 맛있어요! 다음에 또 방문할게요!', 52, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '재방문했어요 ㅎㅎ 전에는 식빵을 안샀어가지고 ㅎㅎ 유명한 탕종식빵과 함께 슈와 슈크림빵 구매했습니다. 아직 안먹어봤지만 맛있을 것 같아용 ㅎㅎ 화학첨가물이 일절 안들어갔다고 하니 안심하고 먹을 수 있을 것 같아요👍🏻', 74, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '라즈베리캐슈넛(2,500) 라즈베리의 단맛을 좋아하면 좋아할듯. 내 입맛에는 넘 달았다 밤식빵(4,800) 달달한 밤이 그래도 꽤 들어있으며, 안에 카스테라가루?가 엄청 들어있어서 빵 자체가 좀 단편이다 수제앙금빵(2,400) 팥이 달지 않은편. 빵피 쫄깃하다', 49, 6, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '네이버에 맛집이라뜨고 티비에도 나온거 같고 기대하고 갔는데 직원인지 주인인지 상당히 불친절 뭐만 물어보면 노려보듯 눈땡그랗게 쳐다보고 말을 못알아듣고 네? 이런식, 나한테만 그런거 아니고 지켜봤는데 모든 사람한테 다 그랬음. 그리고 1월부터 가격인상이면 가격표를 미리 교체하고 장사를 해야되는거 아닌가? 다 고르고 계산할때도 말 안해주고 영수증 보고 왜 가격 다르냐 물으니 그제야 1월부터 올랐는데 자기도 몰랐데. 그러고 보니 알바생이었나봄 현금계산하면 뭐 슈인가 준다고 써있는데 슈만드는 날만 준데 ㅋㅋㅋㅋㅋ 그럼그렇다고 써 놓든가. 사람 민망하게 일부러 현금계산했는데 안주길래 물어봤더니 오늘은 안준데ㅋㅋㅋㅋㅋ 참 여러가지로 불쾌했고 다시는 안갈거임', 4, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '빵나무 소금빵 진짜 맛있어서 반했어요... 에그버거도 맛있고 사장님 정말 맛있게 잘 만드시는 것 같아요... 🖤🤍 다음에 또 방문할게요!!', 115, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '블로그 체험단이 와서 15,000원정도의 무료 빵을 받고 써주는 댓글 들… 사장이 댓글 잘 부탁한다며 몇개 더 얹어주는  빵을 받으며 좋아라는 모습을 보며 같이간 일행과 함께 쓴 웃음을 지었던 일이 생각나네요.. 그저 흔한 동네 작은 빵집일뿐. 별거 없고 다른 빵집에 비해 같은 메뉴도 오히려 재료는 부실하고 가격은 비싼듯.', 40, 1, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '빵종류도 너무 많고 깔끔하고 친절하셔서 좋았어요! 매장 내부에 자리도 있어서 안에서 조용히 대화 나누며 빵 음료 즐기기도 좋은 것 같아요! 맛도 맛있어요! 특히 올리브스틱 최고 ㅎㅎ 집근처니깐 자주 갈게요~', 41, 1, 'GOOD', SYSTIMESTAMP);
