INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '집 근처에 있었으면 하는 빵집이에요. 빵 종류도 다양하고 특히 밤식빵에 밤의 양이 많고 프랜차이즈 밤처럼 사각지지 않아서 좋아요. 매장도 넓고 밀크티도 달달하니 맛있더라고요.', 4, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '빵의 퀄리티에 비해 가격이 너무 착해요🥹 탕종빵이 이런 맛이었구나,, 역시 명장은 다릅니다!!! 포카치아는 완전 요리고요,, 소금빵과 포카치아도 빵 본연의 맛이 참 좋았어요~! 와인 안주로도 추천!!!😆', 24, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '이곳은 한국의 미슐랭인 블루리본서베이 2021에수록된 블루리본 서베이pick빵집이라 더욱 더 기대가 됩니다. 매장 내부는 베이커리 카페답게 테이블이 넉넉하게 있으며, 안쪽으로는 조용히 편하게 쉬었다 갈 수 있는 공간이 마련되어 있습니다. 먼저 흑임자 생크림 앙금빵은 빵을 반으로 가르면 고소한 냄새가 풍기는 흑임자 생크림이 가득 들어 있으며, 탕종법으로 만든 빵이라서 극강의 쫄깃함을 느낄 수 있었습니다. 그다음 마늘바게트빵은 부드럽고, 촉촉하면서, 갈릭향의 풍미까지 더해져 맛있습니다. 그다음 크림치즈딸기타르트는 봄과 어울리는 신선한 제철딸기와 생크림, 잼이 올려져 있으며 아래는 촉촉한 타르트빵 달달함보단 상큼한 맛에 가까웠고, 크기도 커서 타르트만 먹어도 배가 부르더라구요.', 10, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
