INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '빵들이 쫄깃쫄깃 다 맛있어요!! 인공적인 느낌이 하나도 없이 재료 본연의 매력을 하나하나 살린 빵들이라 물리지 않고 먹었네용:) 특히 밤식빵이 좋았어요! 생활의 달인에 나오셨다는데 달인 인정입니다(๑>؂< ๑)۶', 74, 11, 'GOOD', SYSTIMESTAMP);
