INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '빵순이는 빵나무가 너무 좋아~ ^^ 맛난 빵이 있는곳을 지나칠수 없지... 생활의 달인에 나온건 안비밀 ㅎㅎ 친구랑 맛난 빵이랑 커피랑 수다랑', 110, 19, 'GOOD', SYSTIMESTAMP);
