INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '타르트부터 소금빵, 케이크 등 다양한 디저트가 있고 오시면 딸기치즈크림 타르트 꼭 드세요!! 조용하고 따뜻한 분위기 카페찾으시는 분들께 추천요!', 33, 2, 'GOOD', SYSTIMESTAMP);
