INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '직원분께 추천 받은 빵 위주로 구매했는데 다 맛있었어요. 특히 탕종식빵은 정말 촉촉하고 부드러웠습니다. 소금빵도 추천하는 메뉴예요. 직원분 응대도 친절하고 매장 인테리어도 멋있었어요. 다음에 또 방문할게요.', 276, 81, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '소금빵 강추 입니다 ! 요 근래 먹어 본 소금빵 중에 젤 맛있었어요…..（＾ν＾） 소금빵 맛이 다 비슷비슷 하다고 생각했는데, 여기 소금빵은 빵 자체가 쫄깃해서 더 맛있습니다….다음에 가면 또 소금빵 구매하려고요.', 53, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '진짜진짜진짜 너무 맛있어여!!😭😭 먹고 맛있어서 집가서 또 먹으려고 더 샀어여.. 탕종빵으로 유명한 곳이라 해서 다른건 솔직히 기대 안했는데 줜맛ㅜㅜ 빵피가 걍 믜칀럼이에여.. 집근처가 아니라 아쉬울 따름..  근처 들릴 때마다 포장해가려구여🥺 소금빵 꼭꼭 드셔보세여들..', 27, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '탕종 밤식빵은 사장님의 강력 추천해주셨는데, 그냥 먹어도 부들부들 쫄깃쫄깃 최고...🍞 밤식빵 답게 밤도 큼지막하게 많이 들어있었어요🌰 생활의 달인 “탕종빵의 달인”, “식빵 최강달인” 상장에 걸맞은 맛-🏆 생과일이 올라간 크로와상 타르트도 빼놓을 수 없죠❤️ 파삭- 바스라지는 타르트지에, 과즙 팡팡터지는 딸기&샤인머스켓 조합이 대박이었어요ㅠㅠㅜㅜㅜ🍓🍇', 38, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '탕종식빵은 처음인데 진짜 촉촉탱글부드러워서  맛있더라구요!!! 배불러서 다른 것들은 못먹고 시식으로 나온 거 먹었는데 연유크림바게트, 단호박치아바타, 호두브라우니, 마늘바게트도 너무 맛있었어요♥️', 50, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '사장딸 인듯 한 애기 엄청 시끄럽다. 처음에 어른이 고함지르는줄 알았다. 잠깐 앉아서 요깃거리 하려다가 체하는 기분이었다. 근처도 지나가고싶지 않을만큼 재수없다. 손님 주문 받아가며 애 놀아줘야하는 알바생 불쌍함', 15, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '*평일 오전 근무 여자 직원 너무 퉁명스럽고 불친절합니다* 재촉한적도 불편한 이야기를 나누지도 않았는데 오전에 종종 커피사러 가면 세상 귀찮은 표정으로 틱틱거리네요 틱틱거리느라 내 말도 못알아들어서 여러번 말해야하는.. 한 3번정도 참다가 리뷰 남깁니다 저희 부모님까지 좋아하는 너무 맛있는 빵집인데 오전 근무자때문에 빵도 먹기 싫어져요.. 오전 근무자를 재교육하거나 캐셔를 따로 두셔야 할 것 같습니다 .......', 89, 12, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '사장님이 너무 친절하시고 빵이 진짜 미쳤어요 ㅠㅠ 저 엄청 멀리 사는데 홍대 올때마다 들릴것같아요 .. 오늘 하루 행복하게 만들어주셔서 감사합니다', 39, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '저장해둔 곳이라 기대하고 갔는데 솔직히 들어가자마자 기분이 상했네요. 아무 손님이 없었는데도 제가 들어오든 말든 사장님이 직원분께 개인적인 이야기를 하시느라 절 보시고도 대화만; 투명인간 된 기분이었어요 눈치보면서 주문해도되냐고 물었네요 직원분은 친절한거같았는데 사장님은 제가 주문하는 와중에도 나가시면서 본인 하실말, 당부 같은거 계속 하시느라 직원분은 제 빵을 담다 대답하다 담다 그래서 기분이 완전 나쁘게 나왔는데 집와서 빵 먹어보니 너무 내취향이라 더 화나여. 다신 안가야지 하고 더 살거 덜 사서 나오고 그랬는데 먹고나니 또 가게 생김 종류별로 다 맛있고 특히 엘리게이터.. 그래 빵집이 빵맛있으면 됐지 친절은 에휴 하고 합리화하면서도 너무 번창은 안하셨음 하는 이중적인 맘이 드네여', 31, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '여기 크림 치즈 딸기 타르트 잔짜 대박 맛있어요 🥺💕 딸기가 씨지않고 달달하고 타르트 부분이랑 잘 어울려서 너~무 맛있었어요! 여기 식빵 맛집이라고 유명하다고 하니까 담에 가면 식빵이랑 다른 타르트도 먹어보고 싶어요😚', 123, 22, 'GOOD', SYSTIMESTAMP);
