INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '생활의 달인에 나온 유명한 탕종식빵 사러갔는데 매진 됐길래 흑임자 생크림 팥빵이랑 딸기 타르트 사왔어요. 크림빵은 크림 한가득이고 타르트도 엄청 부드럽습니다!!딸기쨈 서비스로 주셨어요ㅎㅎ너무 맛있습니다!!!!', 50, 8, 'GOOD', SYSTIMESTAMP);
