INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '빵은 쫄깃! 크림은 느끼하지 않고 너무 부드러워서 맛있습니다. 일산에서 일부러 찾아가서 구매하고 있습니다. 너무 맛있습니다~^^', 77, 15, 'GOOD', SYSTIMESTAMP);
