INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '맛있는 빵들이 한가득!! 무화과크로와상타르트 -무화과가 말그대로 넘치도록 올려진 무화과 크루와상! 이 메뉴는 진짜 꼭 드셔보셔야해요 무화과가 이렇게 많이 올려진 빵은 처음인데 다다익선이라고 많으면 많을수록 좋다는 것을 느낄 수 있어요 크루와상 안쪽에도 무롸과가 숨어 있어서 최소 두개는 들어있는게 분명해요!! (*´◒`*) 흑임자생크림팥빵 -흑임자크림빵도 안에 크림이 드음~뿍 들어있어서 사장님이 재료를 아끼지 않는다는 것을 느꼈어요!! 흑임자 좋아하는 할매입맛들은 무조건 좋아하는 맛~🖤 마늘바게트-마늘바게트는 크기부터 합격!!🥖 길쭉한 바게트 사이사이 촉촉하고 녹진한 마늘속이 있어서 겉바속촉으로 식사대용으로도 좋을 것 같았어요🧄', 112, 22, 'GOOD', SYSTIMESTAMP);
