INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '홍대 지하철역에서도 가깝고, 깔끔하고 여사장님이 친절하셨어요! 무엇보다 빵 네가지 골라왔는데 다 맛있고 먹고나서도 속이 편안했어요! 재료들을 아끼지 않으시는게 느껴졌어요!', 48, 3, 'GOOD', SYSTIMESTAMP);
