INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '허 너무 맛있는 빵나무 탕종빵으로 식감좋고 소화잘되는❤️ 강낭콩빵은 어디에도 안파는거 같아요 너무 맛있어서 포장도 한가득 했네요', 168, 29, 'GOOD', SYSTIMESTAMP);
