INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '티라미슈 딸기케익 너무 맛잇엇어용 !!! 바닐라 라떼도 달달해서 당뇨병 걸릴뻔~~~~ 너무 조용하고 아늑해서 대화하기도 좋았어요 :) 강추합니당', 46, 0, 'GOOD', SYSTIMESTAMP);
