INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '아니 이 가격에 이런 맛이.. 가성비 갑이네요-! 매번 올 때마다 느끼는 건데, 먹고 나서 속이 너무 편해서 좋습니다 ㅜㅜ 사장님께 여쭤보니, 화학첨가제도 안 넣고 대부분의 재료를 유기농으로 만든다고 하네요.. 코로나라서 자주 못 오는 게 아쉽지만.. 배달시켜서라도 자주 먹을게요! 매번 잘먹고 가요~~', 50, 5, 'GOOD', SYSTIMESTAMP);
