INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '사장님에서 몇년만에 팥빙수 개시를 하셨다고 합니다! 기대를 하며 한입 먹어봤는데 역시나.. 믿고 먹는 빵나무입니당.. 설*이나 파스** 빙수는 너무 달아서 다 먹지도 못했는데, 여기는 팥을 사장님이 직접 정성껏 끓이셔서 그런지.. 인위적인 단맛이 안 나서 싹싹 비워먹었습니다 ㅋㅋㅋ 위에 올려진 떡 같은 건 흑당모찌라고 하는데, 역시나 사장님떼서 직접 만드셨다고 하네요! 강추합니다~~', 55, 13, 'GOOD', SYSTIMESTAMP);
