INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '밀가루 먹는다고 죄책감 가지지 않아도 되는 빵이라서 좋아요오 속도 편하고 맛도 좋아서 너무 만족스럽습니다! 친절하신 사장님과 친절한 직원분들 덕분에 기분 좋게 다녀갑니다 ㅎㅎ', 36, 0, 'GOOD', SYSTIMESTAMP);
