INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '빵이 하나같이 쫄깃하고 맛있어요 인공적이지않고 건강한 단맛에 먹고나면 속이 편해서 더 좋아요 가격도 부담없어서 자주 사묵어야겠어요😆😆', 57, 13, 'GOOD', SYSTIMESTAMP);
