INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '근처 갈 때마다 들르는 빵집! 뭐가 특별히 가미된 것보다는 빵 본연의 맛를 즐기기 좋은 곳이에요~ 단호박치아바타 너무너무 맛나네요. 탕종식빵은 말해 뭐해요^^', 0, 9, 'GOOD', SYSTIMESTAMP);
