INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '매장도 넓고, 사장님과 직원분이 너무 친절하세요! 빵에 대해 여쭤봤는데 친절하게 말씀도 해주시고 추천도 해주셨어요~ 내부는 조용해서 좋고 빵 종류 엄청 많아요 그리고 결정적으로 와안전 맛있습니다 회사가 근처라 매일 출근도장 찍을예정', 49, 0, 'GOOD', SYSTIMESTAMP);
