INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '빵순이라 너무만족스러운곳이에요! 빵이 일반빵들과 다르게 고급진맛이랄까요? 부드럽고 쫄깃하고. .그리구 아주머니두분다 너무친절해서 기억에남아요 감사합니다^^!', 0, 5, 'GOOD', SYSTIMESTAMP);
