INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '생활의 달인에 나온 빵집이라 궁금해서 다녀왔는데 빵들이 하나같이 다 맛있네요^^ 홍대에 있어 가깝고 앞으로도 자주 가야겠어요!', 333, 99, 'GOOD', SYSTIMESTAMP);
