INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '동교동 골목길 달인 빵집. 동네주민들의 단골빵집이예요. 탕종빵집. 식빵은 완판. 디저트도 묵직하고 커피는 아아가 더 맛있어요. 꽃향기와 부드러운 산미가 어울려 조화롭네요. 화장실도 깨끗! 강추', 2, 3, 'GOOD', SYSTIMESTAMP);
