INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '빵 진짜 맛있어요!! 사장님도 친절하시고 갓구운 빵들이 속속 나오는 모습도 넘 반가웠어요^^ 맛있는 빵 많이 계속 만들어주세요~~', 35, 1, 'GOOD', SYSTIMESTAMP);
