INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '빵나무 베이커리 진짜오랜만이에요! 내부공사로 한동안 시간이 안맞아서 찾아가질 못했네요~^^ 내부 깔끔하게 카페처럼 바뀌었네요^^', 104, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '빵나무'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '달인의 빵집으로 유명한 홍대 [빵나무] 늦게 가서 빵 종류는 많이 없어서 아쉽. “탕종빵” 으로 유명 (끓는 물로 반죽, 반죽기계에도 열을 계속 가하고 숙성시키는 방법, 부드럽고 소화도 잘된다 함)', 43, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '분위기 있는 작은 카페입니다. 다양한 인디 음악 사인 앨범도 놓여있었고, 홍대 학생의 조그마한 공예품도 판매하고 있었습니다. 오늘은 디카페인 아메리카노를 시켰는데, 다음에는 케이크도 먹어보고 싶습니다.', 17, 3, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '길가다가 생크림케이크가 먹고 싶어서 갔는데 진짜진짜 맛있었어요!!! 복숭아케이크인데 복숭아도 말랑달달하고 케이크시트도 촉촉해서 슉슉 들어가요!! 무엇보다 생크림이 안 느끼해서 한숨에 다 먹었네요 😋 음료 안 시켰는데도 친절히 얼음물 주셔서 감사했어요 !!!', 94, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '커피랑 케이크 + 매장 인테리어 모두 정성가득이에용 분위기 너무 좋고 케익도 맛있어서 먹는다고 사진은 깜빡 ㅎ 필터커피인가 싶을정도로 아메리카노 맛있고 사장님 넘 친절하세요 일상속 힐링공간,,, 감사합니다 또올게요 ㅎ', 11, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '리뷰는 처음이지만 두번째 방문해요! 지나가다 우연히 발견한 케이크맛집인데 무화과 케이크가 있길래 냉큼 갔다가 너~~~~무맛있어서 홍대오면 들르는 디저트카페가 됐어요! 진짜 케이크가 입에서 사르르 녹는데 깔끔하게 똑 떨어지는 달달함에 재료 본연의 맛과 향이 살아있는 케이크 맛집입니다👍 진짜 무화과 완전 싱싱한데 너무 맛있어요..진짜 맛있어.. 무화과철 끝나기 전에 또 와서 무화과 케이크 먹어야겠어요.. 매장이 작아서 혼카 하기도 편하고 분위기도 너무 좋아요 말차케이크도 먹어봤는데 개인적으로 근본없이 꾸.덕 하기만해서 포크 안들어가고 케이크 빵시트는 다 사라졌는데 입에서 맴도는 초코케이크 별로 안좋아하는데 여기는 초코가 진짜 입에서 살~살 사르르녹으면서 입에서 크림하고 빵시트랑 섞여서 넘어가는게 최고..넘맛있다', 21, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '전에 영업일을 확인 못하고 갔다가 못 먹고 추천받고 넘어갔다가 혼자 영업중인지 제대로 잘 확인하고 왔습니다 가면서 레몬을 꼭 먹어야지 하면서 갔는데 다 나가서 기다렸다가 구매했습니다! 사장님이 기다려주셔서 감사하다고 서비스 주셨어욤🥹 기다리면 받을 수 있어서 다행이라고 생각했었는데🥲🫶🏻🫶🏻 크림이랑 빵 둘 다 너무너무 부드러웠고 레몬 케이크 위에 저 갈색?이 뭔진 모르겠지만 엄청 맛있었어요🤤 샤인 머스킷도 케이크에 많이 들어있어서 좋았구 다음엔 음료도 같이 사서 먹어보고 싶어요👍🏻👍🏻', 15, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '부드러운 앤티크 감성의 케이크 카페 🤍 홍대에서 드문, 잔잔한 곳이라 더 눈길이 갔어요 ✔️ 무화과 초코 케이크와 아메리카노 탄탄하고 살짝 꾸덕한 (브라우니 느낌의) 코코아 시트 속에 무화과가 듬뿍! 담백하고 고소한 유크림도 듬뿍! 들었어요. 높이가 꽤 높고, 크림의 당도는 생각보다 세지 않아서 보기보다 깔끔하고 은은하게 달아요. 무화과는 플레인 시트나 얼그레이와 어울린다고 생각했는데, 초코와의 조합도 정말 매력있네요 🤎', 8, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
