INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '오늘 친구와 함께 다녀왔어요! 원래 전혀 생각이 없었는데 케이크와 음료 그리고 친절한 서비스에 감동해 영수증 부탁드리고 리뷰를 쓰게 됐습니다. 케이크가 먹고 싶어 찾다가 우연히 방문한 곳인데 인테리어가 너무 예뻤으며 사장님께서도 친절히 안내해주셔서 머무르는 내내 기분이 좋았습니다. 음료도 맛있었고 케이크는 정말 계속 생각나는 맛이네요🥺🩷 번창하셨으면 좋겠습니다!', 42, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '손동운생일카페로 방문하게 됐는데 너무 맛있는 케이크를 먹게 됐네요~ 제주말차쉬폰 넘 과하지 않게 맛있는 말차크림이고 얼그레이레몬은 넘넘 상큼한 게 맛있어요~♡ 다른 시그니처 케익맛도 넘 궁금해요~', 4, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '케이크 맛있어요~ 안 달고 깔끔합니다!! 근데 BGM이 넘 커서 대화를 크게 해야 해요.. 대화하기 어려워서 다른 카페로 결국 옮겼습니다ㅠ 혹시 사장님 이 글을 보신다면.. 소리 좀 줄여주셔도 될 것 같아요. 그리고 세이브더칠드런 기부하시던데 거기 대전 관평초 선생님 죽이는 데에 일조한 곳이라 기부 안 하셨음 좋겠어요~ 모르실까봐 남겨요.', 79, 14, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '회사 기념일에 자주 예약하는 가게에요. 합정에서 제일 맛있는 케이크집! 아주 소중한 공간❤️ 사장님이 정말 친절하세요. 앞으로도 쭉 방문 하고싶은 곳입니다.', 67, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '딸기 생크림 케이크, 쑥 베리 롤케이크 구매 딸기케이크는 시트도 크림도 묵직한 느낌이었구 쑥베리롤케이크가 상콤함이 적절하게 더해져서 훨씬 맛있었당 취향저격🫶🏻 아! 케이크에 쓰인 딸기 자체가 맛있더라', 120, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '친구 생일이라 케이크 사러 갔어요! 예약을 안 해서 못살까봐 걱정했는데 다행히 홀케이크가 남아있어서 살 수 있었어요. 모양도 예쁘고 맛있어서 친구도 저도 너무 만족했습니다! 제 생일에도 또 가고 싶어요 😍', 47, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '너무 맛있어요.. 특히 밀크티.. 밀크티 덕후로써 여긴 진짜 인정입니다.. 적당히 달고 적당한 쌉싸름한 맛.. 진짜 여기 밀크티 또 생각나요.. 커피도 고소하니 맛있었어요!!!! 케이크들은 말해뭐해 셋다 너무 맛있어요.. 진짜 느끼할 법도 한데 하나도 안 느끼해요 특히 말차 쇼콜라는 제 원픽 조만간 다시 먹으러 갈 예정 이예요 ㅎㅎ', 3, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '재방문입니다!! 딸기 생크림 케이크 너무 맛있었어요! 갔는데 품절이라 아쉬웠습니다 ㅠㅠ 하지만 다른것들도 다 맛있고, 케익이 너무 이뻐요🥰 인테리어도 너무 이쁩니다.자리가 3개밖에 없지만, 다행히 맨날 마지막 자리 앉을 수 있었네요. 또 갈겁니다!! 클쓰마쓰 케익 예약 마감이라 아쉬워요~~', 36, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '근처에서 밥 먹고 디저트로 케이크가 먹고 싶어서 열심히 찾아봤습니다 ! 자리가 많지는 않아서 주말엔 기다려야 할 수도 있을 것 같아요 매장 인테리어가 너무 아기자기하고 귀여웠습니당 … 그리고 젤 중요한 케이크 !!!!!!!! 얼그레이 레몬 케이크 진짜 너무 맛있었어요 ….. 혼자 가서 케이크 하나만 먹기가 아쉬워서 무화과 케이크 포장해왔습니다 ! 한시간 반 동안 지하철 타고 왔는데 완전 멀쩡했구 쿠키는 서비스로 주셨어요 🥹 홀케이크도 있던데 나중에 홀케이크도 사먹고싶어요 ㅜㅜㅜㅜㅜㅜ 근처에 살았으면 정말 자주 가고 싶은 케이크집입니당 ..', 80, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '늘 케이크만 포장해서 가다 처음으로 매장에서 차와 같이 먹으니 좋습니다. 웨딩 임페리얼이란 홍차가 초콜릿과 캐러멜향이 은은하게 나면서 부드럽고 맛있습니다. 커피맛도 좋습니다.', 89, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '믿고 먹는 나타샤 케이크💛💛 복숭아 케이크 들고 멀리 가니까 더운 날씨 녹지 말라고 초코코팅 해주셨어요🙈❣️ 케이크 하나도 안무너지고 너어무 맛있게 먹었어요!!!!!💕💕 그래서 무화과 케이크로 재주문~~🙋‍♀️ 케이크는 나와 나타샤🧁', 29, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '사장님이 정말 친절하세요. 인스타로 예약하면 가격이랑  예약가능한 케이크 목록 안내해주십니다. 너무 귀엽고 맛있는 케이크라서 직원들이 아주 좋아해요 생일때마다 주문하기로 했답니다^.^', 69, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '방탈 시간 남아서 왔는데요 오 음료 자몽이 특히 맛있었어요 부쉬 드 노엘 케이크는 퍼피레드 게임에서나 보던건데 드디어 먹어보네요??ㅠㅠ 다른 케이크도 맛있다는 리뷰 보니 또 가고싶어요 그리고 직원분 친절하십니다:) 케이크 맛집이러 들었어요', 11, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '지인이 오랜단골이라 항상 극찬하던 나와나타샤 가족들과 홍대 나들이를 간 김에 들렀는데 너무너무너무 만족하고 행복한 감상을 받고 가 잘 남기지도 않던 리뷰까지 남깁니다 시그니처인 얼그레이 레몬 케이크는 못 먹었지만 말차갸또와 부쉬 드 노엘은 타가게에서 먹던 맛과는 비교할 수 없을만큼 너무 맛있었고 포장해간 무화과 케이크와 천도복숭아 다쿠와즈는 8월 생일인 둘째와 셋째가 엄마와 함께 너무 맛있게 먹었다고 합니다❣️ 게다가 서비스로 구움과자까지 챙겨주시고 진짜 너무 행복했고 감사했던 방문과 소비였습니다 진짜 정말로 사장님께서 너무나도 친절하시고 귀여우세요🥺💕 구구절절한 리뷰를 남길정도로 행복하고 뿌듯한 소비였습니다❤️‍🔥 언제까지나 번창하시고 꼭 오래오래 뵀으면 좋겠어요 담주에 또 갈게욧❗️❗️❗️', 67, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '진짜 많은 케이크 맛집을 찾아다녔는데 이곳은 찐입니다!! 소금캐러멜케이크 먹자마자 눈 똥그래져서 얼그레이레몬케이크도 포장해 나왔습니다🤤 케이크 맛집 찾으신다면 고민없이 강추입니다!! 음료도 찐맛집인건 안비밀 사장님 친절왕인것도 암비밀!!', 128, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '생크림 좋아하는 저를 위해 친구가 특별히 주문 제작 해준 케이크ㅎㅎ 사장님 너무 친절하시고 상냥하십니다. 까다로운 요구사항 다 들어주셔서 감사합니다ㅎ 파는 케이크도 맛있어요ㅎㅎ 근데 제 케이크가 더 맛있네요ㅋㅋ 생크림은 동물성 생크림으로 느끼하지도 넘 달지도 않고 고소하니 정말 맛있습니다!!', 35, 10, 'GOOD', SYSTIMESTAMP);
