INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '사장님이 친절하시고 커피랑 케이크 둘 다 잘 먹었습니다!! 아메리카노가 특히 맛있었어요 오랜만에 맛있는 아메리카노를 먹어서 기분이 좋네요😍', 24, 4, 'GOOD', SYSTIMESTAMP);
