INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '말차쇼콜라, 딸기생크림, 레몬바 포장해서 먹었어요. 밀차쇼콜라는 쫀득하고 찐해서 맛있었고 딸기생크림도 크림이 느끼하지 않아서 잘 먹었어요. 마음에 들어서 동생 생일케이크 예약해서 먹었습니다.', 31, 2, 'GOOD', SYSTIMESTAMP);
