INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '근처에 마땅한 케이크집이 없는데 나와 나타샤가 있어서 좋아요! 저번에 홀케이크 샀었는데 홀케이크가 다 나가서 조각으로 여러개 샀어요!', 62, 12, 'GOOD', SYSTIMESTAMP);
