INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '급하게 케이크가 필요해서 갔어요. 인테리어 완전 여성여성하니 예쁘고 사장님도 엄청 친절합니다. 케이크 선물했는데 넘 좋아하더라구요.', 5, 1, 'GOOD', SYSTIMESTAMP);
