INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '엄청 고민하다가 딸기케익 샀는데 가족들이 맛있다고 좋아해서 뿌듯! 담번엔 얼그레이 레몬 홀케익에 사보려구요! 조각케익도 궁금!!', 67, 17, 'GOOD', SYSTIMESTAMP);
