INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '진짜 친절하세요ㅠㅠㅠㅠ그리고 너무너무 맛있어요! 케잌이 진짜 뭘 먹어도 맛있고, 음료도 넘 맛있어요! 매장이 작긴한데 엄청 포근하고 좋아요!!', 6, 8, 'GOOD', SYSTIMESTAMP);
