INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '그냥 지나가다가 급 땡겨서 포장한거라 리뷰할 생각없이 사진 안찍고 먹다가 맛있어서 살아있는(?) 부분만 확대해서 찍었습니다.. 무화과 생크림 먹었는데 아주 고급스런 단맛이 나고 무화과가 아주 싱싱하네요. 크림도 일반 생크림이 아니고 뭔가 맛있는걸 넣어서 섞으신거 같은데 뭔진 모르겠네영. 담엔 여러 종류 더 먹어보겠습니당.', 5, 9, 'GOOD', SYSTIMESTAMP);
