INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '케이크 맛집입니다❤️❤️ 케이크 종류도 다양하고 차도 너무 맛있어요!! 테이블이 약 3개 정도 있는 아담한 카페이긴 하지만 도란 도란 이야기하기 좋습니다🥰', 113, 24, 'GOOD', SYSTIMESTAMP);
