INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '사진이 없어 아쉽지만 케익이 정말 맛있었어요! 분명히 밑에는 꾸덕한 초코였는대 진짜 안달고 맛있었습니다! 오죽했으면 예랑이가 단거 안먹고 케익도 안먹는대 괜찮다고 할 정도 였어요! 그 근처가면 또 갈겁니다! 강추!', 45, 9, 'GOOD', SYSTIMESTAMP);
