INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '얼그레이 레몬케잌 정말로진짜로 맛있고 레몬의 상쾌함이 잘 느껴졌어요!!안에 자리가 많은건아닌데 그만큼 대화에 집중할수있었습니다 티는 웨딩임페리얼 시켰는데 향이 정말좋았어요!', 27, 8, 'GOOD', SYSTIMESTAMP);
