INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '케이크 하나하나 너무 맛있고 ,, 좋은 재료로 만드신게 느껴져서 너무 좋았어요 ㅠㅠ 사장님도 너무 친절하시고 제 최애 카페입니다 !!!! 오래오래 롱런하세요 😻', 30, 1, 'GOOD', SYSTIMESTAMP);
