INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '급하게 케이크 필요해서 들어갔는데 진짜 친절하시고 선물받은 친구도 맛있다고 하네요,, 홍대 들르면 또 가고싶을정도로 친절하심 감사드립니다아', 23, 3, 'GOOD', SYSTIMESTAMP);
