INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '친절하십니당!! 그리고 디저트 진짜 너무 맛있어여,,,, 또 먹으러 갈거예요!! 얼그레이레몬케잌도 맛있고 저거 파운드도 사과절임이 있고 시나몬 향나요! 시나몬이랑 사과 조합 아시죠?! 진짜 맛있습니다,,,자리가 별로 없는 게 아쉬워요,,,! 사장님 잘 되셔서 더 확장하면 좋겠네용!! 음료도 진짜 맛있었어요!! 히비스커스펀치에이드도 맛있고 밀크티도 맛있숩니당 (조금 더 진해도 맛있을 것 같아요!)', 86, 11, 'GOOD', SYSTIMESTAMP);
