INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '실망시키지 않는 케이크 쇼트브레드쿠키는 버터가 많이 들어간듯 햇다 서비스로 받은 히비스커스 쇼트브래드쿠키 는 신맛이 강한편이라 집에서 초콜릿과 같이 먹엇ㅆ더니 밸런스가 맞았어', 73, 12, 'GOOD', SYSTIMESTAMP);
