INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '완전 맛있어요 이틀 연속 방문했습니다 하하 생크림이 달지 않아서 물리지 않고 먹을 수 있어요 절대 후회 안함 무화과 생크림 추천해요', 7, 7, 'GOOD', SYSTIMESTAMP);
