INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '부쉬드노엘은 초콜릿 부분이 엄청진해서 크림과 밸런스가 딱 좋아 분위기도 좋고 1인1음료가 아니란 점도 좋아 탁자만 조금 더 높아져라...제발..', 124, 25, 'GOOD', SYSTIMESTAMP);
