INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '케이크가 정말 맛있다. 2022.4.19 가게도 깨끗하고 분위기도 좋다. 협소해서 많이 들어올순 없음 탁자가 너무 낮아 불편한게 아쉽다', 30, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '우연히 지나가다가 새로 생긴곳인가 하고 안을 봤는데 케이크가 장난아닌거에요~ 여기는 가야한다 생각했고 몇일뒤에 방문했습니다 케이크 다 맛있어보여서 고르는데 한참 걸렸네여 ㅋㅋ 부쉬드노엘로 골랐고 겉에 초코는 진하고 꾸덕?에 안에 크림은 안느끼해서 조화로웠어요! 촥촥한 초코 케이키 스탈? 차도 케이크랑 잘 어울렸답니다 사장님이 친절하셨고 또 방문하려구요>\\<', 19, 4, 'GOOD', SYSTIMESTAMP);
