INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '쇼콜라밀크티래서 밀크티에 초콜릿향 살짝 나는 정도일 줄 알았는데 홍차향이나는 핫초코였어요. 저는 그래서 더 좋았습니다 추운 날씨에 어울리고요. 레몬케익도 새콤하고 맛있어요', 25, 10, 'GOOD', SYSTIMESTAMP);
