INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '설탕맛 심한 밀크티말고 진짜 차에 우유부은 밀크티를 좋아하는데 동네카페에서 이런 밀크티를 만날 수 있어 정말 놀랍고 좋았어요. 시럽을 따로주셔서 당도는 알아서 조절할 수 있고 양과 질에 비해 가격도 부담없는편입니다. 케익도 다 맛있고 공간도 깨끗하고 분위기도 좋았습니다.', 29, 6, 'GOOD', SYSTIMESTAMP);
