INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '엄마와 오랜만에 연극본 후 근처에서 식사하고 지나가다 우연히 발견한 카페♡ 인테리어 아기자기하구 평일저녁이라 가게안은 조용하고 메뉴들 가격도 착하네요ㅎㅎ 울동네 왜 이런곳 없죠😭 다쿠아즈 두종류 맛보았는데 엄마도 저도 취향저격🥰 담에 또 올꾸예요💕 담엔 케이크도 먹어봐야지🍰', 12, 4, 'GOOD', SYSTIMESTAMP);
