INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '커피 가격 저렴하구욘 케이크도 저렴하고 맛있어요 대신 그만큼 작아서 아쉬워요 긔까 다들 1인 2케이크하면 좋을거 같아요 저는 곧 공연봐야해서 1개만 먹은게 넘나 아쉬워요ㅠ', 84, 16, NULL, SYSTIMESTAMP);
