INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '나와 나타샤'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '커피값이 아주 저렴하네요 아이스아메리카노가 2,000원인데 연하긴하지만 가볍게 마시기 좋습니다 그리고 여자들이 좋아할만한 예쁘고 디저트들 가득,, 여자둘이서왔다면 케에크는 당연히 두개 주문했을꺼에여 ㅠㅠ', 46, 2, NULL, SYSTIMESTAMP);
