INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '홍대 테라스카페 찾다가 발견한 조블라! 유럽갬성으로 완전 분좋카 감성입니당ㅎㅎㅎ 카페도 예쁜데 커피랑 디저트까지 맛있어서 가는길에 포장해서 갔어요 ㅎㅎㅎ 가을시즌이라 밤치즈케이크 먹었는데 너무너무 맛있어오!! 분위기도 예뻐서 홍대 데이트 코스로도 추천!! 사장님 너무 예쁘고 친절하세요 ㅠㅠㅠ 번창하세요!!', 87, 15, 'GOOD', SYSTIMESTAMP);
