INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '디저트 진짜 넘 맛있어요 두 번 먹으세요 세 번 먹으세요 꼭 가보세요 말차 치즈 케이크는 말차맛이 굉장히 깊어요 말차에 그대로 흠뻑 빠져듭니다 곰들렌 귀엽죠 제 니플러 인형 자랑하려는건아니공..키키', 21, 4, 'GOOD', SYSTIMESTAMP);
