INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '바스크치즈케이크 맛집이라고 해서 방문했는데 역시나 소문 그대로 너무 맛있었습니다 라떼아트도 너무 귀엽고 고소하니 너무 맛있었습니다! 다음에 또 방문할게요~!', 57, 13, 'GOOD', SYSTIMESTAMP);
