INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '커피도 맛있고 분위기도 유럽 같았던 곳! 진짜 여행 온 거 아닐까 하는 느낌이라 좋았고, 정신없지 않아서 마음에 쏙 들었네여🥹🫶 홍대쪽 갈만한 카페 없어서 고민이었는데 마음에 드는 카페 찾은 것 같아서 기쁩니당ㅎㅎ', 43, 5, 'GOOD', SYSTIMESTAMP);
