INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '홍대에 이런 보석같은 카페가 있다니..! 유럽감성 인테리어에 맛있는 디저트들까지 너무 최고였어요 !🫶 저는 디저트 포장으로 방문했었는데요, 포장지에도 리본으로 이쁘게 포장되서 기분이 넘 좋았어요 담에 홍대에서 디저트선물할때 지인선물용으로도 좋을것같아서 마음속으로 찜했습니다 ㅎㅎ  특히 꾸덕한 바치케랑 파삭한 에그타르트 완전 추천 ! 넘 맛있어용 ! 담엔 매장이용도 해보려구요 💛', 50, 1, 'GOOD', SYSTIMESTAMP);
