INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '너무 예쁜 카페 .. 🫧 여름이 잘 어울리는 곳이었어요 유럽감성 낭낭한 빈티지 카페였습니다 🫶🏼 신상카페인지 빈티지 감성이지만 엄청 깔끔하고 예뻤어요 ! 저는 밤 바스크 치즈 케이크 & 곰들렌을 구매했는데 밤 맛 가득한 꾸덕한 치즈 케이크였어요. 밤 가득 넣어서 식감이 훨씬 좋은 치즈 케이크였어요 🌰 곰들렌은 딱 선물용으로 좋은 귀여운 마들렌이에요 🐻 촉촉하고 폭신한 식감에 반했습니다 🫶🏼 넘 맛있구 다음에는 카페 내부 분위기 즐기면서 데이트 기고 싶은 곳이었어요 🤍', 51, 11, 'GOOD', SYSTIMESTAMP);
