INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '테이크아웃 해서 집에서 먹었습니다! 카페 인테리어가 너무 예뻐서 다음에 방문하면 꼭 카페에서 먹고 가고 싶어요 !! 디저트는 곰들렌이랑 에그타르트 시켰는데 제가 근래 먹은 에그타르트 중에 제일 맛있었네요:) 음료는 피스타치오 크림라떼로 주문해봤는데 크림이 너무 맛나용', 10, 10, 'GOOD', SYSTIMESTAMP);
