INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '유럽갬성이라 느좋 분위기에 음료는 모카크림라떼 주문했는데 초코 풍미가 그득그득한데다 여태 먹어본 크림라떼 중에 이렇게 진할 수 있나 싶을정도로 크림 자체가 묵직하면서 꼬수워요 ••ㅎ 혼자 와서 사색 즐기기도 좋을 거 같아요 :)', 17, 8, 'GOOD', SYSTIMESTAMP);
