INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '#협찬 너무 예뻐요 ㅠㅠ 홍대역 시끌벅적하고 어딜가도 사람 많은데 이렇게 숨어있는 보물을 발견하다니 행복🩷 카페 야외 테라스랑 내부 다 너무너무 빈티지하고 예뻐요 감성 굿, 느좋카페😍 사진도 너무 잘나오고 분위기 진짜 한적하고 아늑하고 너무너무 마음에 들어요 ❤️ 디저트는 또 얼마나 맛있게요~!? 에그타르트 촉촉, 말차 치즈케이크도 진짜 부드럽고, 쿠키도 넘 맛있어요✨ 진짜 유럽 한낮의 평화로운 한 장면 연출되는 이미지예요! 홍대역 근처 카페 찾으시면 여기 홍대 데이트로 강추!!', 61, 14, 'GOOD', SYSTIMESTAMP);
