INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '홍대에 이런 카페가 있었다니,, 이제야 발견한 나 반성해 🫠 알고보니 자주 오던 최애 술집 바로 옆이었다 … 일단 들어오자마자 예쁜 테라스에 1차 놀람, 그리고 실내도 아늑하고 예뻐 2차 놀람. 방문했을 때 디저트는 쿠키종류가 가장 많았고, 곰모양 귀여운 마들렌 곰들렌이랑 에그타르트, 바치케 3가지 맛(기본, 말차, 밤) 있었다! 얼그레이 밀크티 다른 곳이랑 다르게 굉장히 향긋하고 적당한 당도라 너무 달지 않을까 걱정하며 시켰던게 무색하게 인생 밀크티일정도 .. ෆ 밤 바치케도 커다란 밤이 진짜 장난없다 🫢 홍대 분좋카? 당장 출동 💨💨💨', 21, 5, 'GOOD', SYSTIMESTAMP);
