INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '쿤데라 책과 어울리는 무드라고 추천떠서 호다닥 와본 조블라~~~ 카페 웨이팅 있을뻔 했지만! (3인이상 4석은 공석이었음) 다행히 테라스에 앉아있으니 다 드신 분이 비켜주심 ^^ * 곰돌 궁금했는데 다 나가서 담엔 먹어보기루! 원랜 안되는건데 에그타르트 감사합니다ㅠㅠㅠ 다음에는 시그니처 먹어보겠음~~ 기분전환제대루~~ 주말엔 2시간 이라고 써있어요~', 50, 5, NULL, SYSTIMESTAMP);
