INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '홍대골목에 이런 곳이 숨겨져있다니 놀라울따름!! 꽤 여유로운 테라스 공간도, 빈티지 유럽감성 가득한 실내와 짱맛구움과자도 모두 마음에 들었던 홍대데이트맛집이에요 특히 부드러운 생크림같은 크림라떼 안느끼하고 너무 맛있어오!!! 홍대데이트코스나 대화하기좋은 카페, 디저트맛집으로 홍대 조블라 추천드려요!!', 16, 0, 'GOOD', SYSTIMESTAMP);
