INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '전부터 말차케이크 먹어보고 싶었는데 와 이루어져서 기뻐요 좀 달긴 해도 맛있어요❤️ 원래 아아 마시려고 했는데 피스타치오 흔하지가 않아서 한번 마셔보려고 주문했는데 역시 맛있어요~~가끔은 당 충전해도 될 만큼... 옆에서 크림라떼도 맛있다고 하네요 ㅎㅎㅎ 인테리어도 예쁘고 시원해요!!!🤣 또 리뷰 남기면 곰돌이 주셨는데 귀엽고 맛있어요!', 17, 1, 'GOOD', SYSTIMESTAMP);
