INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '동생이랑 경의선 숲길에서 벚꽃 구경 하다가 방문하게 되었어요. 지도에서 찾아보는데 카페 인테리어가 너무 예쁘더라구요. 그래서 방문하게 되었는데! 훨씬 분위기가 좋았어요.👍 음악도 카페랑 너무 잘어울리구요!👀 뿐만 아니라 이날 마셨던 음료들도 다 너무 맛있었습니다. 초코 라떼는 제티 같이 진한 코코아 맛이었고 청포도 에이드는 포도 청이 가득 들어가 진했어요. :) 분위기 좋은 곳에서 맛난 음료 마시고 갑니당🤎', 63, 12, 'GOOD', SYSTIMESTAMP);
