INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '인테리어 짱 예뻐서 사진 찍으면 잘 나와요. 분위기 정말 좋음!!! 커피도 맛있지만 디저트 최고!! 바스크치즈케이크 말차 먹었는데 꾸덕 촉촉 맛있어요.', 44, 7, 'GOOD', SYSTIMESTAMP);
