INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '홍대입구역 8번출구 근처에 위치한 골목 안 예쁜 카페 조블라! 예전부터 가보고 싶었는데 이번에 친구랑 가봤어요. 크림라떼가 시그니처 같아서 크림라떼랑 곰들렌 먹었는데 크림라떼도 달달하니 맛있고 곰들렌은 우선 너무 귀여워서 먹기가 아까울 정도에요💕 곰들렌도 촉촉하고 맛있습니다. 테라스도 있어서 날씨 좋을 때가면 야외석에 앉고 싶어요. 카페 분위기도 유럽감성 물씬 풍기고 아늑하고 너무 예쁩니다.', 36, 8, 'GOOD', SYSTIMESTAMP);
