INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '말차 스모어 쿠키가 너무 맛있어서 재방문 했어요! 네이버로 포장 예약하고 찾으러 갔는데 바로 받을 수 있어서 좋았어요 친절하시고 매장 분위기도 좋고 무엇보다 말차쿠기가 맛있습니다!!', 77, 18, 'GOOD', SYSTIMESTAMP);
