INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '지나가다 우연히 들린 카페였는데, 인테리어부터 너무 예쁘고 라떼도 달지 않아 딱 제 취향이었어요! 또 오고 싶게 만드는 그런 곳이었어요💕', 63, 12, 'GOOD', SYSTIMESTAMP);
