INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '눈, 코, 입까지 있어서 귀여운 비주얼 자랑하는 곰들렌은 부드러우면서도 정말 고소해요! 조블라의 시그니처로 완전 인정 인정! 에그타르트는 촉촉하고 포슬포슬한 식감으로 계란의 담백함과 고소함까지 즐길 수 있오요! ​ 초코칩 스콘은 초코칩 가득 박혀 있어 어느 부분을 먹어도 초코맛 푸짐하게 느낄 수 있어요! 달달러버들에게 인기 만점일 듯한 초코칩 스콘! 플레인 스콘은 고소하면서도 바삭한 스콘 위에 설탕을 올려 살짝 구워내 달달함 추가! 딸기잼과 스콘 조합은 언제나 사랑🧡 초코 월넛 쿠키, 레몬 얼그레이 쿠키는 사이즈에 놀라고, 바삭하면서도 꾸덕꾸덕해서 맛 도리 그 자체! 로투스 스모어 쿠키는 데웠더니 녹아내린 비주얼에…. 아메리카노와 함께 먹으면.. 찰떡 조합…!', 3, 3, 'GOOD', SYSTIMESTAMP);
