INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '저번에 우연히 들렸다가 에그타르트가 너무 맛있어서 재방문했어요!! 에그타르트 페스츄리같은 그 파이지?? 인데 제가 딱 찾아다니던 에그타르트라 행복..🥹🥹 분위기도 대화하기 좋고 시끄럽지 않아요! 노래도 귣', 5, 7, 'GOOD', SYSTIMESTAMP);
