INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '와 인테리어 너무예쁜 카페발견!! 친구만나러 홍대나왔다가 진짜예쁜 카페에서 차랑 디저트먹었는데 디저트도 존맛이예요 ㅜㅜ 군데군데 포토스팟이있어서 사진찍기도좋아요 :) 홍대카페로 완전 추천이요:)', 45, 4, 'GOOD', SYSTIMESTAMP);
