INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '홍대에 숨겨진 진짜 맛있는 카페! 치즈케이크 꾸덕하게 찐한 맛이 진짜 최고에요!!! 쿠키는 르뱅쿠키 느낌으로 꾸덕한데 이것도 진짜 너무 너무 너무 맛있구요! 바삭한 스콘도 진짜 최고! 요기 밤티라미슈랑 에그타르트 유명한 곳인데 제가 갔을 때는 품절이라 못 먹어봤거든요!! 그러니까 조블라 가면 진짜 꼭 드셔보세요!! 연말이라 예쁘게 꾸며진 공간도 너무 예뻐서 시간 보내기도 좋을 것 같아요 ❤️❤️', 118, 24, 'GOOD', SYSTIMESTAMP);
