INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '포장해서 먹게되었는데 치즈케이크 진짜 너무맛있어요 ㅠㅠ!! 그리고 쿠키는 오레오 최곱니당!!!! 홍대에있어서 접근성도 좋은것 같아요', 6, 8, 'GOOD', SYSTIMESTAMP);
