INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '홍대 분위기 좋은 카페 찾아보다가 조블라에 다녀왔어요! ㅎㅎ예쁜 트리도 있어서 크리스마스 분위기도 좋구 아늑한 감성카페에용 ㅎㅎㅎ 수제 디저트도 맛있고 곰들렌도 넘 귀요미🐻!!특히 바치케가 부드럽고 촉촉해서 진짜 맛있더라구요 ㅎㅎ홍대 디저트 맛집 조블라 추천합니다🎄💛', 21, 3, 'GOOD', SYSTIMESTAMP);
