INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '꺄 매장자체도 너무 크리스마스 분위기 낭낭해서 예뻤는데 바스크 치즈 케이크가 너무 맛있었습니다!!!! 너무 맛있어서 친구 선물로 포장도 해갔는데 역시나 맛있다구 하네요 ㅎㅎㅎ 특히 에그타르트도 맛있엇어요!! 만족만족~', 57, 14, 'GOOD', SYSTIMESTAMP);
