INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '아 밤치케 너무 맛있어서 울뻔했어요. 완전 클스마스 분위기에 내부도 너무 예쁘고 얼죽아인데 아메리카노 핫으로 주문 실수해서🥲 속상했는데 얼음컵 제공 해주셔서 식혀먹었습니다! 감사해요🤍', 21, 5, NULL, SYSTIMESTAMP);
