INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '홍대 디저트 카페 추천이에요! 크리스마스 시즌에 맞춰서 카페도 너무 이쁘게 꾸며져있고 쿠키들도 진짜 너무 두툼하고  맛있네요!! 완전 강추!!!!!', 31, 10, 'GOOD', SYSTIMESTAMP);
