INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '저번에 왔다가 너무 맛있어서 재방문했어요!! 치즈케이크 별로 안 좋아하는 남자친구도 밤치즈케이크 맛있게 먹었어요ㅎㅎ 크리스마스 장식도 너무 예쁩니다!💛🩵 사진 많이 많이 찍으세요', 106, 19, 'GOOD', SYSTIMESTAMP);
