INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '케이크 맛집 찾다가 오게된 카페입니다. 홍대에 숨겨진 케이크 맛집!!! 인테리어 완전 앤틱하고, 이뻐요~ 치즈케이크 너무 맛있구요. 시크니쳐 라떼 완전 달달구리합니다😛 또 재방문 하고 싶을정도의 케이크 맛입니다~ 또 올거에요~😋', 20, 6, 'GOOD', SYSTIMESTAMP);
