INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '에그타르트가 진짜 맛있어요. 인테리어도 이뻐서 감성사진 잘 나오고 사람많은 주말에 갔는데도 불구하고 생각보다 자리가 많아서 앉을 수 있었어요.', 1, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '홍대디저트카페 조블라 ෆ 쿠키 먹고싶어서 방문했어용!! ㅋㅋㅋ 진짜 폭신부드러운 쿠키.. 넘 맛있음 ㅠㅠㅠ 달달해서 당충전 제대로 되는 거 같아요!! ♡ ♡', 24, 6, 'GOOD', SYSTIMESTAMP);
