INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '크리스마스 분위기가 가득한 곳입니닷! 구석구석 열심히 꾸미신 것이 느껴져서 좋았어용! 음악도 넘 크지 않아서 대화하기 좋아요.', 2, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '사장님 여기 진짜 3시에 가도 막 에그타르트 하나만 남고 그랬는데ㅠㅠ 혹시나 해서 5개를 일단 주문을 해봤어여 근데 3개나 남아있던거죠 ㅠㅠㅠ그래서 바아로 3개 후다닥 예약구매 갈겼어요 ㅠㅠ 급한 제 마음이 보였을랑가 모르겠는데 암튼 에그타르트 먹을 수 있어서 너무 좋았습니더 ㅠㅠㅠㅠ 행-복😍', 56, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '실내외에 좌석이 꽤 많았어요. 바스크치즈케익과 커피 시켜먹었는데 맛이 괜찮았네요. 쿠키 에그타르트 등 디저트 선택의 폭이 다양해서 취향것 먹을 수 있어요. 매장 내외로 이쁘게 잘 꾸며져 있어 데이트로도 좋을거 같아요.', 48, 2, 'GOOD', SYSTIMESTAMP);
