INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '여자친구의 추천으로 같이 오게 되었습니다! 치즈케이크가 그렇게 맛있다고 하던데 진짜더라구요... 음료도 뭐 말모입니다.. 다음에 또 재방문 하려구요! 🫡', 8, 7, 'GOOD', SYSTIMESTAMP);
