INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '홍대에 초등아이 데리고 놀러가면 항상 들리는 곳이에요! 넘 번잡스럽거나 시끄럽지 않고 테라스공간이 있어서 아이들이 답답해하지 않아서 너무 좋습니다! 게다가 커피와 음료들 모두 맛있어요~~~~👍', 83, 14, 'GOOD', SYSTIMESTAMP);
