INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '치즈케이크 러버들 조블라 오세요 ,,, 저는 말차 좋아해서 말차 치즈케이크 시켰는데 너무 부드럽고 맛있어요 ㅠㅠ 순삭입니다 디저트 종류도 많아서 올 때마다 행복한 고민이에요🥹 분위기도 너무 좋아서 가까우면 맨날 오고 싶어요 엉엉', 12, 3, 'GOOD', SYSTIMESTAMP);
