INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '연남동 데이트 가는 길에 갈만한 예쁜 까페 찾다가 발견한 홍대 디저트 맛집 ‘조블라’.. 사람많은 홍대 거리 어귀에 위치해서 조용하고 안에 인테리어도 넘 예뻐서 좋았어요. 커피랑 디저트도 맛나서 편안하게 좋은 시간 보내다 갑니당 ♥️ 재방문의사 200%', 13, 4, 'GOOD', SYSTIMESTAMP);
