INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '우연히 들른 커피숍입니다. 예쁘고 아기자기한 인테리어가 인상깊었고, 커피도 맛있고, 음악도 조용한 팝송이라,, 연인과 대화하기 좋네요.', 48, 8, 'GOOD', SYSTIMESTAMP);
