INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '우연히 방문했다가 분위기가 너무 좋아 또 오게됐는데 크림라떼 정말 너무 맛있어요 ,, 저번에 먹은 갓나온 곰들렌도 너무 맛있게 먹었습니다 올 때마다 다른거 도전해보고 싶어요 잔잔해서 혼자서도 여럿이서도 오기 좋아요 ! 단골 되기 딱 좋은 집이네요😝', 23, 5, 'GOOD', SYSTIMESTAMP);
