INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '바스크 치즈케이크가 너무 꾸덕하고 맛있고 카페에 사람이 적당히 있어서 기다리지 않고 들어왔고 분위기가 아주 아늑하고 사진도 잘 나와서 연인 친구와 데이트 하기 너무 좋아요🥰', 16, 2, 'GOOD', SYSTIMESTAMP);
