INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '크림라떼라 너무 달까봐 걱정했는데 적당하고 맛있어요! 커피는 산미도, 탄맛도 걱정 없는 누구나 즐길 수 있는 맛! 분위기가 좋아요..🤍', 8, 1, 'GOOD', SYSTIMESTAMP);
