INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '대표메뉴인 크림 라떼와 바스크 치즈케익 시켰습니다. 크림 라떼는 위에 크림이 뚜툼하니 지인짜 맛있고 바스크 치즈케이크.. 요물이에요.. 아 이 조합이면 걍 쿠폰 쓰러 스벅갈까ㅠ 했는데 절대 ㄴㄴ.. 바스크치즈케익 스벅갖다댈수없습니다 꾸덕한듯크리미한듯유연한듯 풍미가 스근~하게 풍기는데 질리는 것 없이 술술 들어와요 바스크치즈케익의마법사.. 둘 다 크리미한데 물리지않는 매직.. 크림의 축복이 끊이지않습니다 커피와 케익 한 입 하시면 ‘여길 발견하다니 난 정말 운이 좋다🍀’ 라고 생각하실 거예요 강추', 77, 16, 'GOOD', SYSTIMESTAMP);
