INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '시그니처 세종류 시켜봤는데 크림이 너무 맛있었어요! 특히 흑임자 크림 고소하고 피스타치오 크림 달콤하네요. 그리고 밤 디저트도 있어서 좋았어요~! 무엇보다 테라스 컨셉의 인테리어라서 해외 관광지 놀러온 것 같네요~~!', 47, 7, 'GOOD', SYSTIMESTAMP);
