INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '크림라떼랑 치즈케이크 플레인 시켰는데 둘다 맛있어요! 인테리어도 너무 이쁘고 밖에 야외 테이블이 진짜 이뻐서 나중에 선선해지면 야외에 앉아보고싶네요', 29, 8, 'GOOD', SYSTIMESTAMP);
