INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '홍대입구역에서 점심을 먹고 우연히 찾은 카페 ''조블라'' 작고 아담한 공간이었지만 인테리어도 괜찮고 차맛도 좋아요. 야외도 사진 찍기 좋아요.', 32, 7, 'GOOD', SYSTIMESTAMP);
