INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '유럽감성 뿜뿜한 홍대에 있는 조블라 카페에 방문했어요 ! 홍대에 있는곳인데 커피,음료,디저트 정말 가격이 착한 곳이에요 🥹👍🏻✨ 가성비도 좋은데 맛도 놓치지 않은 조블라 !! 노래도 잔잔하게 틀어주셔서 수다에 집중 할 수 있어 좋았던 공간이에요 ♥️ 에그타르트는 주문하면 따뜻하게 데워주시는거 같더라구요 !!! 그래서 정말 촉촉하게 먹었어요 ㅠㅠ👍🏻 홍대 놀러오시면 꼭 조블라 방문해보세요 !', 74, 18, 'GOOD', SYSTIMESTAMP);
