INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '주택을 개조해서 만든 카페인데 테라스가ㅜ있어서 너무 좋더라고요. 애견동반가능하더라고요. 커피랑 치즈케이크 맛집입니다. 담에 또 방문할게요~~~^^', 13, 2, 'GOOD', SYSTIMESTAMP);
