INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '바스크 치즈케이크가 먹고 싶어서 왔는데 일반 플레인과 말차도 있어서 골라 먹는 재미가 있을 거 같아요!! 너무 맛있습니다 ㅎㅎ 다음엔 말차를 먹어보려구요 ㅎㅎ 좋은 카페 알아냈습니다 :)', 44, 4, 'GOOD', SYSTIMESTAMP);
