INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '쿠키가 엄청 맛있어요! 인테리어도 아기자기하고, 골목길에 숨어있는 곳이라 찾아오는 재미가 있네용ㅎㅎ 아메리카노도 딱 적당히 꼬소하니 맛나요옹! 추천합니당', 27, 3, 'GOOD', SYSTIMESTAMP);
