INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '바스크 치즈 케이크 초코 스콘 둘 다 너무 맛있었어요 특히 바스크 치즈 케이크는 정말 정말 부드럽고 촉촉했어요.👍🏼조블라에서 직접 정성스럽게 만든 디저트라 그런지 더 특별했습니다❣️유럽 감성에 따뜻한 분위기가. 넘좋구요날씨 따뜻해지면 야외 테라스에서도 커피 한잔 하고 싶네요', 325, 31, 'GOOD', SYSTIMESTAMP);
