INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '실내도 너무 예쁘고 안에 자리도 많아요. 너무 덥거나 춥지 않으면 테라스에도 자리가 있어서 좋을 것 같아요. 아메리카노도 산미 적어서 맛있고 피스타치오 라떼가 너무 맛있어요!', 97, 26, 'GOOD', SYSTIMESTAMP);
