INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '아늑한 카페를 찾고싶어서 왔는데 너무 좋아요! 디저트랑 음료도 가격대가 높지 않고 적당해서 오기 좋은 것 같아요! 추천드려요😽', 27, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '홍대카페 조블라 다녀왔어요 정말 너무 분위기 좋은곳! 아니 무슴 동화같은 분위기더라구요 ㅎㅎ 너무 예뻤어요 분위기도 분위기지만 디저트도 너무 맛있어요 치즈쿠키 먹었는ㄷㅔ 따뜻하니 완전 제 스타일!! 크림라떼 는 너무 부드럽구 고소해서 맛있었어요 곰들렌은 너무 귀여운거 아닌가요??><홍대 걷고 싶은거리근처에 있는데 골목사이로 들어가서 찾을 수 있어요!', 3, 10, 'GOOD', SYSTIMESTAMP);
