INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '우선 이렇게 홍대 마당 옆 구석에 이렇게 멋있는 카페가 있는 줄 몰랐어요 ... 우선 바스크 치즈케이크 랑 에그타르트 진짜 맛있어요.. ㅜㅜ 그리고 인테리어 밖에 테라스 분위기랑 노래 선곡까지 다 마음에 들고요, 커피도 맛있습니다 !! 유명해졌으면 좋겠는데 조용한 분위기가 좋아서... 안유명...해졌으면 좋겠기도(ㅠㅠ) 해요... 구석구석 놓치지 않고 다 꾸며두셔서 사진 엄청 찍었어요 ㅎㅎ 그리고 직원분도 친절하셔서 잘 먹고 갑니다 ~ 👍👍 또 올거예요 !', 80, 15, 'GOOD', SYSTIMESTAMP);
