INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '예전부터 예뻐서 가려고 저장해둔 조블라 드디어 와봤어요!! 입구부터 너무 이뻐서 사진 잔뜩 찍었어요ㅎㅎ 내부도 너무 이쁘고 옛날 팝송을 틀어두셔서 감성 미쳐요.. 디저트도 맛있고 생크림 스콘에 딸기잼이 너무 맛있었어요🥹 다음엔 쿠키 먹어보려구요', 40, 6, 'GOOD', SYSTIMESTAMP);
