INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '카페분위기도 너무 좋고 카페에 흘러나오는 노래도 너무 좋아요!!! 인테리어도 너무 감성적이고 커피랑 쿠키가 너무 잘 어울리게 맛잇어요 홍대길거리 중간에 이런 분위기 카페가 있다는게 대박입니다!!!👍🏻👍🏻👍🏻', 125, 25, 'GOOD', SYSTIMESTAMP);
