INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '분위기 좋은 카페💕 커피도 맛있고 귀여운 곰돌이 곰들렌 너무 귀여워🙂 테라스도 있어서 앉고 싶었는데 역시 인기가 많아서 사람들이 다 앉아서 아쉽! 다음에 도전해야징!🤣', 76, 14, 'GOOD', SYSTIMESTAMP);
