INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '구움과자 검색해서 들어온 카페인데 분위기 넘 아늑하고 좋네요 !! 약간 유럽 여행 온 것 같은 느낌입니당…😊✈️ 곰마들렌도 너무 귀여워요!!🐻❤️🥰', 27, 1, 'GOOD', SYSTIMESTAMP);
