INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '맨날 연남쪽 카페만 가다가 홍대쪽 카페 찾아서 와봤는데 너무 마음에 들었어요~!🩷 인테리어도 너무 예쁘고 매장도 크고 깨끗해요!! 그리고 무엇보다 바스크치즈케이크가 진짜 맛있습니다🤤 다음에는 말차맛으로 먹어보려고요!!', 31, 1, 'GOOD', SYSTIMESTAMP);
