INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '인테리어도 너무 예쁘고 디저트랑 커피도 너무 맛있어요🥹🥹 사장님도 넘 친절하셔서 또 오고 싶어요 ㅎㅎ 날 좋은 날 밖에서 먹으면 최고입니당🤭🤭☁️🩵 추천해요 !!! 🩵🧸🎀', 16, 8, 'GOOD', SYSTIMESTAMP);
