INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '언니랑 근처에서 밥먹고 분위기 좋은 카페를 찾다가 발견한 조블라 인데요! 밖에 있는 테라스부터 마치 프랑스같은 유럽의 집에 온 느낌이 물씬 풍겼습니다. 🥰🥰 내부도 정말 디테일 소품 하나하나 넘 이뻐서 계속 사진을 찍게 되는 분위기였습니다! 바스크 케이크 맛집이라해서 주문했는데 정말 진한 치즈 맛이 인상적이었습니다 💕💕 데이트 코스로 친구랑 가기 좋은 카페로 추천드려요!', 29, 1, 'GOOD', SYSTIMESTAMP);
