INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '가게가 넘 예쁘고 음료도 너무 맛있어요! 피스타치오 라떼와 모카크림라떼 주문했어요! 야외 테라스도 넓고 감성 있어서 추천해요♡', 23, 8, 'GOOD', SYSTIMESTAMP);
