INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '홍대에서 디저트 맛집에 조용하고 예쁜카페 찾으신다면 여기에요! 곰돌이 마들렌 너무 귀엽구 음료도 맛있어요! 테라스도 있어서 날 풀리면 테라스에 앉고싶어요 ㅎㅎ😆 인테리어 곳곳이 사진찍기 좋고 케이크 종류도 많고 초도 있어서 기념일에 오기에도 좋은 거 같아요 :)', 32, 1, 'GOOD', SYSTIMESTAMP);
