INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '분위기 너무 좋아요🫶 음료도 예쁘고 카페도 예뻐서 사진 찍기에도 너무 좋고 조용해서 친구랑 이야기하거나 책 보기에도 너무너무 좋습니다! 테라스가 있어서 요즘 날씨에 앉아 있기 너무 좋았어요💓 다음에 또 올거에요🙆‍♀️🙆‍♀️', 19, 4, 'GOOD', SYSTIMESTAMP);
