INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '테라스가 너무 예뻐서 야외에 앉고 싶었는데 비가 와서 ㅠㅠ 아쉽지만 다음에 방문하게 된다면 꼭!! 테라스에서 사진 찍어보고 싶습니다 커피두 넘 맛있어요 ㅎㅎ', 3, 7, 'GOOD', SYSTIMESTAMP);
