INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '우연히 방문한 카페인데. 넘 맛있구 인테리어 넘예뻐요. 따뜻해지면 테라스에서 디저트 먹으러 와야겠어요. 여기 바스크치즈케이크 꾸덕하규 넘 맛있어요. 오레오스모어쿠키도 촉촉하구 … 최고.. 오래오래 계세요.🎀', 82, 11, 'GOOD', SYSTIMESTAMP);
