INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '홍대카페 다녀왔어요 조용히 책읽고 싶어서 갔는데 플레이리스트도 좋구 사람들 다 조용조용 카페 즐기는것 같아서 좋네용! 인테리어가 멋져서 커피 의심했는데 흑임자 커피도 맛나게 먹었어요!', 304, 89, 'GOOD', SYSTIMESTAMP);
