INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '일단 여긴 디저트 맛집이에요 홍대 오면 꼭!!! 들리셔야 합니다. 전 바스크 치즈 케이크를 너무 좋아하는데 여기만큼 맛있는 곳 못봤어요... 존맛탱 ㅠㅠ 다른 디저트들도 너무 맛있을 것 같아서 재방문하려고 합니다 애견동반도 가능하다고 하니 댕댕이들 많이 와주세요..🥹❤️ 분위기도 좋고 커피도 디저트도 대짱존맛입니다...', 34, 4, 'GOOD', SYSTIMESTAMP);
