INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '치즈케이크 처돌이인데 꾸덕하고 너무 맛있어요 !! 아메리카노랑 같이 먹으면 딱 🥹 분위기도 너무 좋아서 눈도 즐겁고 입도 즐거워요 ㅠㅠ 또 방문하겠습니다 ♥', 15, 0, 'GOOD', SYSTIMESTAMP);
