INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '음료에 크림이 많이 달지 않아서 좋았고 부드럽고 모카크림라떼라는 음료에 맞게 모카맛이 잘 났어요 커피 잘 못 마시는데 너무 맛있었어요 친구들도 같이 갔는데 모두 맛있다구 하고 연남 , 홍대 디저트 카페 맛집이여서 또 올 거 같아요 인테리어도 너무 예뻐여 😻😻', 66, 14, 'GOOD', SYSTIMESTAMP);
