INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '밀크티도 너무 맛있고 특히 바스트 치즈 케이크가 너무너무 맛있었어요!! 곰돌이 마들렌도 있고 날씨 좋은 날에는 야외 테라스에서 앉아 있어도 좋을 것 같아요 번화가가 아니라서 조용하고 분위기도 좋아요 친구들이나 연인과 담소 나누기 좋은 공간 같아요 😙', 18, 0, 'GOOD', SYSTIMESTAMP);
