INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '카페 분위기가 너무 좋아요! 음료는 기본적인 티 시켰는데 디저트도 너무 맛나 보여요. 조명, 음악, 인테리어 너무 맘에 듭니당 :)', 8, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '우와 골목 안에 이런 아늑한 카페가 있었네요🥺 바스크 치즈케이크랑 아이스아메리카노 시켰는데 둘다 맛있어요!! 바스크 치즈가 꾸덕하니 커피랑 잘 어울리네요 ㅎㅎ 요즘 날 따뜻해져서 테라스도 오픈했던데 다음엔 테라스로 앉아보려고요 ! 여유로운 주말 잘 보내구 가요~', 50, 3, 'GOOD', SYSTIMESTAMP);
