INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '음료가 맛있고 곰들렌이 너무너무 귀여워용 크림라떼 먹어보고싶었는데 날이 추워서 따뜻한 음료로 시켰어요 둘 다 너무 맛있네요 인테리어도 너무 멋져서 대화 나누기 참 좋았어요^^♡ 아직 연말 분위기가 나는게 넘 포근해서 좋아요~', 27, 10, 'GOOD', SYSTIMESTAMP);
