INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '아늑하고 좋은 분위기에서 한잔하는 커피는 언제나 기분 좋은 것 같아요 ㅎㅎ 크림라떼 부드럽고 맛있어요 ~! 햇살 좋은 날 가면 더 좋을 것 같은 카페에요~', 109, 24, 'GOOD', SYSTIMESTAMP);
