INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '커피랑 음료 너무너무 맛있고 카페가 정말정말 예뻐요..🥹💖💖 한국 속 유럽같아요... 완전 취향저격!!! 사장님도 친절하십니다!! 힐링 플레이스 등극...😆🙌💚🍀', 4, 0, 'GOOD', SYSTIMESTAMP);
