INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '바스크치즈케이크 맛집 알아보다가 방문한 홍대 카페인데 인테리어 너어무 예쁘고 조명 좋아서 셀카 잘나와요!!! 여기서 사진 한 오백장 찍은듯,, 인스타 피드 올리고 싶으신 분들께 추천하고 싶은 갬성카페!', 75, 18, 'GOOD', SYSTIMESTAMP);
