INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '스콘이 진짜 맛있었고 차도 커피도 맛있었습니다 ~ 노래나 분위기도 취향이고 인테리어도 괜찮았어요 가게가 외진 곳에 있어서 처음 와보는데 재방문 의사 만땅입니다 :)', 44, 3, 'GOOD', SYSTIMESTAMP);
