INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '홍대 분좋카 ~ 분위기 좋은 카페 조블라 추천해요 🧡🧡 카페 플레이리스트 너무 좋고 🎶 커피도 맛있는데 바스크 치즈케이크랑 스콘도 정말 너무 맛있어요 !! 부드럽고 바삭한 고소한 스콘 추천 😋💛 완전 재방문 할 거예요 !! 🤎', 17, 2, 'GOOD', SYSTIMESTAMP);
