INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '반려동물과의 방문이라 혹시 실내가 안되진않을까 걱정했는데 반려동물도 실내입장 너무 당연하게 들어오게해주시고 음료도 너무 맛있고 스콘마저 진짜 왕맛이에요ㅠㅠㅠ 사장님도 너무 친절하시고 반려동물 물 요청드렸는데 종이컵 잘라드리냐고도 물어봐주시고 짱짱입니다ㅠㅠㅠ', 102, 25, 'GOOD', SYSTIMESTAMP);
