INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '연말 같지 않은 연말이라 크리스마스 느낌 물씬 나는 곳을 찾아왔는데 딱 제격이에요🫶🏻 분위기 좋은 곳에서 캐롤 듣는데 힐링되네요! 카페도 너무 예쁘지만 커피도, 오레오스모어쿠키도, 에그타르트도 너무 맛있어서 만족하고 갑니다 :) 평일에 온 거 아니었으면 웨이팅 필수였을 거 같은 곳이에요🥰', 30, 9, 'GOOD', SYSTIMESTAMP);
