INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '돌아다니다 근처 카페 찾느라 우연히 들어갔는데 밖에 테라스 너무 이쁘게 잘 꾸며 놓으셨더라구요🎄🎅🏻🤍 언니는 크림라떼 저는 아메리카노 마셨는데 둘다 너어무 맛잇었습니다! 추천추천🤍', 19, 2, 'GOOD', SYSTIMESTAMP);
