INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '우연히 들어갔는데 커피가 달달한 디저트랑 먹기 딱좋아요!! 스모어 쿠키 시켰더니 따뜻하게 데워주세요~ 매장 분위기 따뜻하고 넘 좋네요 ㅎㅎㅎ 추천합니댜>_<', 9, 8, 'GOOD', SYSTIMESTAMP);
