INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '홍대 골목에 이렇게 귀엽고 아늑한 카페가 숨어있었네요!! 크리스마스 분위기 물씬 나서 사진찍기도 좋고 디저트도 다 너무 맛있어요💓 평일 저녁이었는데 딱 한자리 남아서 운 좋게 기다리지 않고 앉았어요!', 24, 0, 'GOOD', SYSTIMESTAMP);
