INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '홍대에서 우연히 들어갔다가 재방문한 곳인데 늦은 저녁에 갔더니 손님이 많더라구요 역시 한번가면 계속 생각나는 곳이에요 인테리어도 좋고 음료도 맛있고 디저트도 맛있었던듯! 또 방문할게요!', 24, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '홍대카페 플래인스콘과 에그타르트가 맛있는 애견동반 카페 조블라에  딸이랑 방문해서 맛있는 스콘과 에그타르트를 포장해왔어요. 남편도 아들도 이 집 진짜 맛집이라고 칭찬해요. 홍대에서 데이트하시거나 맛있는 스콘 맛집 찾으시면 따뜻하고 보고는 홍대 카페 조블라 추천해요.', 61, 15, 'GOOD', SYSTIMESTAMP);
