INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '들어오는 길 부터 크리스마스로 꾸며져있어서 너무 좋았어요 ㅠㅠ 포토존도 있고, 내부가 나름? 넓어서 좋습니다~! 주말에 방문했는데 만석이라 한팀 기다리고 바로 들어가써요👍🏻 음료도 예쁘고 맛있습니다 ❤️ 홍대입구역이랑 가까워서 추운 겨울 대피하러 들어오기도 딱이에여 🥶🥶☃️', 57, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '인테리어가 너무 귀엽고 커피가 맛있어용 !! 조용하고 아늑해서 편하게 있다 가기 좋았어요🥰 선곡 센스도 대박이에욤ㅎㅎㅎ 다음에 또 올게용>_<', 129, 21, 'GOOD', SYSTIMESTAMP);
