INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '동기 언니들이 인테리어도 넘 이쁘고 커피도 진짜 맛있다고 추천해서 방문해써요!! 수업 듣다가 졸렵구 당떨어졌는데 크림라떼 먹으니까 기운이 확나더라구요 ㅋㅋㅋㅋ 쿠키랑 휘낭시에도 사왔는데 휘낭시에는 같은 빠직하면서 속은 부드러운게 맛있더라구요( 츄러스 맛입니당 참고로☺️ ) 쿠키는 두툼하니 맛있어 보여서 골랐구 집 가서 먹으려구유 ㅋㅋㅋㅋ 암튠 오늘은 남은 수업이 있어서 포장해왔는뎅 담에는 매장에서 먹어보고싶네용 ㅎㅎ 야외가 진짜 잘 꾸며져 있어서 크리스마스에 오고싶어요!! 다음에 또 오겠슴돠 냠냠굿~😋💕', 14, 6, 'GOOD', SYSTIMESTAMP);
