INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '구움과자 디저트류가 굉장히 많더라구요 포장해서 거의 모든 종류 먹어봤는데, 다 굉장히 맛있었어요 특히, 에그타르트는 엄청 부드럽고 커스터드에서 계란맛이 살아있어서 굉장히 고소하면서 달달한 맛이었어요 초코스콘은 겉은 바삭하고 안은 촉촉하고 부드러운 식감이었는데, 겉에 뿌려는 초코가 달기만 한게 아니고 되게 부드러운 초코맛이라 더 맛있었어요 크림라떼는 시그니처 메뉴라고 해서 주문해봤는데, 요것도 달면서도 라떼 특유의 고소한 맛이 살아 있어서 맛있더라구요 경의선 숲길 산책갈때 포장해서 들고가기 딱인 것 같아요', 11, 2, 'GOOD', SYSTIMESTAMP);
