INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '오랜만에 홍대 들렀다가 처음보는 카페가 있어서 방문해봤어요! 분위기가 그냥 유럽 그자체,,,뭔가 스페인 느낌이 나는 카페였어요!! 시그니처 크림 라떼랑 디저트를 테이크아웃해서 먹었는데 다 너무 맛있더라구요!! 다음에 시간되면 안에서도 먹고 싶어요!! 맛+분위기까지 만족스러운 홍대 디저트 맛집 카페로 추천〰️✨', 10, 2, 'GOOD', SYSTIMESTAMP);
