INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '홍대 디저트 맛집, 크림커피 맛집인 조블라❤️ 여기 감성 너무 좋아여 벽돌인테리어 완전 이쁘고 내부도 아늑하고 유럽느낌 뿜뿜인데,,사장님도 친절쓰!! 그리고 무엇보다 디저트가 존맛탱이에용 ㅠㅠㅠ 바치케랑 휘낭시에 ㅠㅠ 💟💟 바치케 말차맛이랑 밤맛도 궁금하네요 나중에 또 가야겠서용!!!', 88, 11, 'GOOD', SYSTIMESTAMP);
