INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '시그니처인 크림 라떼 너무 달지 않고 맛있었어요💛 휘낭시에 먹으러 왔다가 에그 타르트에 반하고 가는,, 쿠키랑 치즈케이크, 구움 과자류도 많았구 카페도 유럽 느낌의  앤틱하고 아늑하고 데이트 하기 조아요☕️☕️', 18, 4, 'GOOD', SYSTIMESTAMP);
