INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '주변에서 공연보고 카페 찾다가 예뻐서 와봤는데요!! 내부도 아늑한 느낌으로 너무 예뻐요!! 늦은 시간까지 하셔서 좋았어요 사장님도 너무 친절하십니다♡', 20, 2, NULL, SYSTIMESTAMP);
