INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '완전 가을분위기라 지금 방문하기 딱! 좋은 카페입니당! 시그니처인 크림라떼를 크림부터 차근차근 마시면 본연의 맛을 잘 즐길 수 있어요! 사람들도 많이 찾구 감성있는 분위기를 느끼기 좋은 곳이에요🤭 특히! 테라스자리가 넘 매력있어요👍', 12, 6, 'GOOD', SYSTIMESTAMP);
