INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '조블라 인테리어 크림라떼 맛집...🥰 넘 맛있어요 진짜ㅠㅠ 커피부터 일단 맛있는데 시그니처 크림에 올라가있는 바삭바삭한 비스킷?까지 조합 완벽합니다 그리고 얼그레이 밀크티도 넘 맛있어서 한잔 더시킬뻔했지 뭐에요? 디저트도 넘 다양하구 자리도 넉넉하구 분위기도 좋았어요!', 80, 12, 'GOOD', SYSTIMESTAMP);
