INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '홍대 사람 많은 속 여유롭게 즐길 수 있는 한적한 공간이에요 특히 저녁 조명이 너무 아늑하고 예뻐요 :) 무엇보다 크림 커피를 시켰는데 고소하고 달달해서 진짜 너무 맛있어요 ㅠㅠ(´▽`ʃƪ)♡ 다음에도 커피 먹으러 또 방문할 것 같아용-`♥´-', 56, 15, 'GOOD', SYSTIMESTAMP);
