INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '홍대에 인기있는 카페 중 하나인데 역시나 주말에 사람들로 꽉 차있네요~~ 크림라떼와 휘낭시에 에그타르트 스콘 구움과자류들을 포장해서 연트럴파크 가서 먹었어요~~! 크림라떼 위에 크림 엄청 부드럽고 적당히 달달해요! ㅎㅎㅎ 에그타르트 스콘 휘낭시에 다 맛있는데 전 에그타르트 원픽! ㅎㅎ 타르트지 위에 계란이 완전 부드럽고 입안에서 녹아요💛 카페 내부도 감각적이고 대화나누기 좋아서 홍대카페로 추천드려용❤️', 54, 18, 'GOOD', SYSTIMESTAMP);
