INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '왜이리 카페가 예쁘죠,,, 제 갬성에 딱 맞는 곳은 꼭 숨어있더라구요,,, 남편이랑 같이 밖에서 구경하다가 쉴 겸 카페 왔는데 사진 맛집 !! 인테리어도 우드톤, 따뜻하고 사진도 잘나와용 ! 시그니처 크림라떼랑 아이스 아메리카노, 플레인 스콘 시켰답니다 따뜻한 날이면 밖에 앉아도 좋을 것 같아용,,, 커피는 탄맛이 좀 있어용 ! 크림라떼는 달달하니 좋네용 잔잔한 노래 들으며 남편이랑 좋은 시간 보내고 갑니당 눈호강 + 디저트랑 커피 맛있어용 👍🏻', 124, 24, 'GOOD', SYSTIMESTAMP);
