INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '주변에 일이 있는데 갑자기 비가 오길래 들어간 곳인데 분위기도 좋고 직원 분께서 친절하게 응대해주셔서 좋았어요. 카페에 혼자여서 그랬을 수도 있지만 제가 잠깐씩 자리에서 일어나서 뭐 찾으면 바로 반응해주시고 좋더라구요:)', 15, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '진짜 홍대 바치케 1등 맛집이에요.. 🤍 친구랑 바치케 어디가 맛잇나 보다가 여기로 와봤는데 가격도 저렴한데 크기는 손바닥 만해서 놀랐어요 !! 양도 짱 많고 맛도 진짜 맛있어서 좋았어요 ☺️ 초코라테랑 고구마라테 시켰는데 둘다 맛이 찐해서 음료도 짱짱 존맛탱이니깐 다들 바치케 먹구 싶을때 조블라로 가세욤 🥺', 18, 9, 'GOOD', SYSTIMESTAMP);
