INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '크림 라떼가 진짜 맛있아요.. 오늘 처음 방문했는데 너무 맛있어서 다음에 홍대오면 여기만 올래여ㅜㅠ 스콘도 버터향 나면서 넘나 맛도리인것.. 👍🏻💛 인테리어두 잘 해두셔서 매장이 넘 이뻐요!', 40, 1, 'GOOD', SYSTIMESTAMP);
