INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '커피 한 모금 먹자마자 맛있어서 개안했어요 시그니처라 시켜봤는데 크림이랑 커피 맛 조합이 훌륭.. 합니다 애인은 패션후르츠 에이드 마셨는데 역시 맛있다고 했음 ! 골목 사이에 있어서 여긴가 ? 하고 들여다봤을 때 가게 외관부터 크리스마스 가게처럼 꾸며져 있어서 너무 예뻤어요', 27, 9, 'GOOD', SYSTIMESTAMP);
