INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '바로 앞에 야외엔 예쁘게 트리 장식이 되어있었어요 시그니처 크림라떼는 달달한 향이 나서 추운 날에 몸 녹이기 좋았던 것 같아요 생각보다 자리도 넓고 넉넉해요 골목 안에 숨겨진 감성 카페 인정합니당☺️', 126, 19, 'GOOD', SYSTIMESTAMP);
