INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '홍대에 크리스마스 분위기 카페 찾아서 왔는데 커피 맛집이었어요!!🎄❤️ 인테리어도 분위기 너무 좋고 음악도 넘 좋아요. 구움과자 종류도 많아서 디저트 먹으러 또 올 거에용🩷🩷', 66, 14, 'GOOD', SYSTIMESTAMP);
