INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '커피가 너무 맛있어요!❤️ 츄로스 휘낭시에도 쫀똑하니 시나몬향이랑 달달하니 맛있구, 에그타르트는 입에서 살살 녹습니다..🤤🤤 맛있는 디저트와 함께 사장님도 너무나 친절해서 더 행복해지는 시간이었습니다 :) 담에 다른 디저트 먹으러 또 올게요 ❤️❤️❤️', 30, 8, 'GOOD', SYSTIMESTAMP);
