INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '분위기가 넘 좋아요 !!! 트리두 이쁘고 매장도 아늑해서 최고 … 🩷 바스크 치즈 케이크랑 크림라떼 먹었는데 젤 마시써요 꼭 드세용 🤩🤩🤩', 14, 3, 'GOOD', SYSTIMESTAMP);
