INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '분위기 너무 좋아요 ❤️❤️ 스모어 에그타르트 완전 맛있구 음료도 맛있습니다 😊 홍대입구역 인근에 위치해서 거리도 좋아요 ☺️', 10, 4, 'GOOD', SYSTIMESTAMP);
