INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '이번이 두번째 방문인데 처음 와서스콘먹고 오랜만에 맛있는 스콘을 찾아서 너무 좋아서 친구와 두번째 방문하네요 가게 분위기가 좋고 지금12월이라 크리스마스 장식 해놓으셔서 사진찍기 좋아요 여기오면 꼭 스콘은 사서 먹어 보세요 초코월넛쿠키,소금초코휘낭시에 플래인스콘,피스타치오크림라떼,초코라떼 먹었어요 피스타치오 크림라떼도 너무 맛있어요 저번에는 초코스콘 먹었는데 오늘은 품절이더라고요 오늘은 플래인 먹는데 플래인도 맛있네요 홍대오면 친구들한테 소개시켜주고 싶은맛이에요', 52, 12, 'GOOD', SYSTIMESTAMP);
