INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '우드톤 인테리어 좋아해서 찾아보고 들어왔는데 너무 예쁘고 황치즈 쿠키 정말 맛있어요오 안에 마카다미아 왕창 들어있어요!! 휘낭시에도 겉바속촉 커피랑 궁합이 좋아요 분위기도 좋고 월요일 낮에오니까 웨이팅도 없구 공간도 넓어서 너무 좋아용♥', 85, 11, 'GOOD', SYSTIMESTAMP);
