INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '이런 곳이 있는 줄 몰랐어요! 골목 안에 있어서 그런거같은데 분위기도 좋고 인테리어가 잘 되어있어서 구경거리도 은근 있어요! 야외에도 테이블이 있어서 날씨 좋을 때 방문해도 좋을 것 같아요! 기념일이라 간단하게 곰돌이케이크 주문 했는데 넘넘 귀엽고 음료들 디저트들도 다양해서 자주 방문 할거같아요!', 1, 5, 'GOOD', SYSTIMESTAMP);
