INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '홍대입구역 근처 디저트 포장하기 좋은 카페예요. 매장 분위기도 넘 좋고 야외석 분위기도 짱좋아요. 디저트가 넘나 맛나보여서 커피는 기대 안했는데 커피도 맛있고요! 에그타르트 맛있으니까 꼭 먹어야해요. 휘낭시에랑 스모어쿠키도 굿굿!!', 44, 6, 'GOOD', SYSTIMESTAMP);
