INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '조용한 카페 좋아하는데 홍대역에서 이렇게 가까운곳에 이쁘고 조용한 카페가 있었다니 ..! 왜 여태 몰랐을까요 테라스자리도 너무 이쁘고 소품 하나하나 감성이 넘쳐요~!~! 혼자 책 읽기 좋은 곳 같아요', 0, 1, 'GOOD', SYSTIMESTAMP);
