INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '개인적으로 홍대에 오면 정신이 없어서 힘들 때가 있는데 카페가 살짝 안쪽에 있어서 조용하고 갑자기 다른 곳에 온 느낌이 드는 공간입니다. 사장님도 엄청 착하시고 가게 자체가 예쁘고 조용하고 공간이 잘 되어 있어서 어떤 만남에 오든 부담 없이 올 수 있어서 좋습니다. 디저트도 다양하고 다 맛있고 음료도 맛있어서 추천드립니다.', 62, 14, 'GOOD', SYSTIMESTAMP);
