INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '크리스마스 시즌때 방문해서 그런지 엄청 예쁘고 아늑해서 좋았어요! 카페라떼도 고소해서 제 취향저격😍 크리스마스로 꾸민 야외 공간도 예뻐요👍🏻', 16, 8, 'GOOD', SYSTIMESTAMP);
