INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '매장 분위기, 커피, 케이크 맛까지 완벽했던 곳✨ 맨날 술먹기 위해 갔던 골목사이 이런곳이 있었다며 놀라고, 음료 맛과 커피맛에 또한번 놀랐어욯ㅎ 밤 바스크치즈케이크와 피스타치오 크림라떼 먹었는데 둘다 다른 카페에선 느끼지 못하는 맛이었어욯ㅎㅎ😚🧡 홍대에서 카페 갈땐 여기로 달려갈 것 같아요!!🙂💛', 55, 15, 'GOOD', SYSTIMESTAMP);
