INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '일단 지하철 역이랑 가까워서 추운 날에도 찾아오기 좋아요! 카페 밖이랑 안에 있는 크리스마스 인테리어가 정말 귀엽고 예뻐요 :) 초코휘낭시에랑 아이스 라떼 둘 다 맛있어요..!!!', 29, 9, 'GOOD', SYSTIMESTAMP);
