INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '전체적으로 인테리어가 빈티지한 유럽풍으로 부드러운 분위기여서 좋았어요 여기저기 예쁘게 꾸며져있어서 포토존도 많고 디저트 포장하기에도 좋았네요😊 저는 플레인스콘이랑 크림라떼 추천!!', 22, 4, 'GOOD', SYSTIMESTAMP);
