INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '힙 거리 홍대 속 이쁜 카페!! 카페 기본메뉴 아아랑 조블리 시그니처 크림라떼, 바스크치즈케이크 시켜 먹었어용 크림라떼의 크림이 일반적인 달달하기만 한 크림이 아니라 뭔가 담백(?) 고소(?) 두유 느낌나는 맛이에요! 크림라떼 강추!!!!', 0, 8, 'GOOD', SYSTIMESTAMP);
