INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '카페 분위기도 되게 좋고 디저트도 엄청 맛있어요! 무엇보다 동반자랑 조용히 얘기 할 수 있는 자리도 있어서 너무 좋은 거 같아요! 재방문 의사 있습니당~', 1, 1, 'GOOD', SYSTIMESTAMP);
