INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '홍대에도 이렇게 따뜻한 느낌의 카페가 있네요. 포장해 왔는데, 다음에는 안에서 먹고 가야겠어요. 포장 기다리면서 실내 인테리어가 예뻐서 사진 찍기 좋더라구요. 아우, 감성있어요! 샤인머스켓케이크 안에는 부드럽고, 샤인머스캣이 안보이는 안쪽까지 다 들어있고 맛이 미쳤어요! 생크림케이크 부드러움과달달함이 커피랑 먹기 너무 좋아요. 사장님이 냉장고에 넣었다가 먹으라고 알려주셨는데 먹어보니 이유를 알겠어요. 크림이 살아있음! 포장 커피는 사이즈도 커서 마음에 드네요.', 50, 1, 'GOOD', SYSTIMESTAMP);
