INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '홍대에 이렇게 아늑한 카페가 있었다니!! 우연히 검색해서 왔는데 야외 테이블도 있고 내부인테리어도 아늑해서 좋아요! 정신없고 시끄러운 분위기가 아니라서 맘에들어요~! 커피도 맛있습니다 :)', 17, 2, 'GOOD', SYSTIMESTAMP);
