INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '조블라 테라스 공간이 넘넘 예뻐요~! 직원분도 친절하시고 케이크도 부드러워요! 스콘이랑 구움과자 종류도 있는데 배가 불러서 많이 못먹은게 아쉽습니다~ 인테리어도 유럽풍이라 아늑하고 다음에 또 오고싶어요~', 82, 18, 'GOOD', SYSTIMESTAMP);
