INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '카페가 너무 예뻐요 ! 사진찍기 좋아요 *.* 안은 아늑해서 대화하기 너무 좋아요 (╹-╹｡) * 쿠키종류도 다양하고 음료도 맛있어요 🤍', 15, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '홍대 감성카페는 여기로.. 디저트도 맛있고 좌석도 많아요 감각적인 인테리어 덕에 포토스팟도 많아요 젊은 여성분들이 정말 좋아하실 분위기에요☺️ 골목에 숨겨져 있지만 다들 찾아오는 이유가 있어요', 104, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '여기 남자친구랑 한번 방문하고 혼자 오늘 와서 총 두번째 방문인데 인테리어가 너무 예뻐서 사진도 잘나오고 디저트도 너무 귀여워요 다음에 홍대올때 또 방문할게요💓💓💓', 71, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '북적북적한 홍대 골목 사이에 다른세상이 숨겨져있네용^^ 너무 멋진 유럽정원에 온듯한 고풍스럽고 멋스러운 분위기입니다. 들어서자마자 보이는 야외테라스가 보기만해도 힐링이고 인테리어와 소품 하나하나 정성이 느껴져서 완전 기분전환돼요~ 사진스팟 많고 인생샷도 바로 건졌어요^^ 내부공간도 유럽의 고급 레스토랑 느낌이고 차분하면서도 너무예뻐요~커피도 맛있고 음료도 맛있고 에그타르트도 부드럽고 맛있어요^^ 디저트 종류도 다양하고 가격도 합리적이어서 더더더 좋네요^^ 잔잔한 음악선곡도 분위기를 더합니다. 집근처에 이렇게 아름다운곳이 있는지 몰랐어요ㅠ 이제부터 홍대 카페는 무조건 여기^^', 14, 7, 'GOOD', SYSTIMESTAMP);
