INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '남친이랑 한여름 밤에 맥주 한잔🩵 지금 여기가 유럽인지 집앞인지 오랜만에 달달한 시간 보냅니당 다음엔 와인 마시러 올 예정 🩵 커피맛집이라 종종오는데, 날이 선선해서 야외 자리에서 맥주 한잔 먹는데 여행온것 같아요 사장님 노래 선곡 너무 좋아요 😍🥰', 46, 0, 'GOOD', SYSTIMESTAMP);
