INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '카페가 아기자기 이쁘고 도란도란 수다 떨기 좋은 분위기여서 너무 좋았어요! 커피도 맛있고 디저트도 달달해서 너무 맛있고 즐거운 데이트했습니당💓', 44, 3, 'GOOD', SYSTIMESTAMP);
