INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '너무 친절하셔서 좋았고, 음료와 디저트도 맛있게 먹었습니다 특별히 빈티지한 분위기로 음악과 인테리어가 너무 좋았어요 날씨가 좋을때는 실외 테라스에서 시간 보내기도 너무 좋을 것 같네요 번창하세요~~👍👍', 25, 7, 'GOOD', SYSTIMESTAMP);
