INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '피스타치오 크림라떼 너무 맛이써요ㅠㅠ 완전 라떼 맛집입니당💚 스모어 쿠키랑 휘낭시에도 너무 맛있네요 그리고 홍대인데도 분위기가 너무 여유롭고 조아요 카페에서 나오는 노래랑 인테리어가 잘 어울려서 여유 즐기기 조은 것 같아요 다음에도 또 오깄습니당', 48, 1, 'GOOD', SYSTIMESTAMP);
