INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '홍대에 위치한 유럽느낌의 디저트카페. 사진찍기도 좋고 디저트가 맛있어 포장해오기도 해요~🥹 늦게 갔더니 품절돼서 많이 겟하지 못한게 아쉬워요🤣', 50, 4, 'GOOD', SYSTIMESTAMP);
