INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '사장님 혼자서 하시는 거 같은데 친절하시구 매장이 아늑하고, 대화하기도 좋아요~!! 시그니처 메뉴인 크림라떼는 꼭 드셔보세용! 친구가 먹어봤는데 크림이 너무 맛있대용><><', 69, 13, 'GOOD', SYSTIMESTAMP);
