INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '겨울에 찾아왔는데 크리스마스 분위기 뿜뿜입니다. 여기 분위기도 좋고 이야기 나누기도 좋아용 시그니처 크림라떼 추천드립니다~•~•', 16, 6, 'GOOD', SYSTIMESTAMP);
