INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '인테리어가 정말 멋있어서 사진찍기 좋아요. 저녁에 왔는데 완전 분위기 맛집이네요! 모카크림라떼 테이크아웃으로 주문했는데 완전 맛있었어요!! 다음에 홍대 또 방문하면 테이크아웃 말고 매장에서 마시고 싶을 정도로 카페 분위기가 좋았어요 :)', 89, 11, 'GOOD', SYSTIMESTAMP);
