INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '홍대 골목 안쪽에 숨어있던 찐 디저트 맛집이에요✨️ 야외석부터 내부 인테리어까지 넘 아기자기하고 유럽감성 낭낭,, 디저트 종류도 많고 넘 귀여워요 💖 이번에는 일정이 있어서 포장했는데, 포장도 깔끔하게 해주시고 귀여운 도시락 케이스에 담아주세요!! 안에 인테리어도 너무 이뻤어서 다음번엔 홀 이용해보려 합니다 😊😊 밤 바스크 치즈케이크: 달달한 밤이 통으로 세네개 들어가 있어요!! 반죽에 밤이 많이 들어가 있는지, 밤 없이 케이크부분만 먹어도 달달고소한 밤향이 가득합니다 😍 에그타르트: 담백한 계란향이 은은히 퍼지면서 과하게 달지 않아 맛나요!! 추천!', 19, 4, 'GOOD', SYSTIMESTAMP);
