INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '분위기가 좋고 인테리어가 멋져요! 빈티지한 감성 좋아하시면 맘에 들거같아요 😊 커피랑 스콘 주문했는데 둘 다 맛있었어요 날이 좋아서 야외자리에 앉았는데 인테리어가 예뻐서 실내에 앉아도 좋을거같아요 !', 120, 20, 'GOOD', SYSTIMESTAMP);
