INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '빈티지하면서 아늑한 가게 인테리어는 물론❣️ 포장한 디저트들도 다 너무 맛있어요. 딱 적당히 달콤하고 각 네이밍의 맛들이 살아(?)있어서 혀가 즐거워지는 맛이에요 전 포장했지만 다음엔 매장에서 먹고싶어요', 43, 1, 'GOOD', SYSTIMESTAMP);
