INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '카페 분위기 너무 예뻐요!! 오두막에 놀러온 느낌이라 음료 마시기 전부터 기분이 정말 좋아져요! 음료랑 디져트도 넘 맛있어요!!', 130, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '커피와 아이스티 다 너무 맛있었어요!! 에그타르트도 겉에는 빠삭하고 안에는 흐물달달해서 좋았어요 공간이 아늑하고 따뜻한 분위기라 겨울에 잘 어울려요! 사람이 많아 사진은 못찍었지만 트리로 크리스마스 분위기로도 잘 꾸며둔 공간이라 분위기 좋아서 좋네요🎄☕️', 121, 23, 'GOOD', SYSTIMESTAMP);
