INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '커피도 맛있고 인테리어도 멋진곳이에요! 갠적으로 에그타르트가 진짜 맛있었어요! 여기 크림라떼가 유명하길래 흑임자크림라떼 주문했는데 텁텁하지않고 깔끔하게 맛있습니다!! 매장내부도 너무 작지않고 테이블도 꽤있어서 데이트코스로도 너무 좋은것같아요!!', 27, 4, 'GOOD', SYSTIMESTAMP);
