INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '홍대에 작은 골목에 너무 귀엽고 따뜻한 카페가 있어서 놀랐어요 나만 아는 특별한 카페같아서 더 좋네요 겨울에도 여름에도 방문 하기 좋은 예쁜 카페네용🤍', 42, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '언니랑 같이 홍대 첫나들이라서 카페 리뷰 좋은 곳 찾아왔는데 진짜 기대 이상! 크리스마스 분위기도 너무 예쁘고 세상 설레는 중입니다..❤️', 38, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '쿠키가 많이 안달아서 넘 좋아요ㅠㅠ 그리고 곰탱이 빵 넘 졸기탱 . . 나중에 오면 곰탱빵 먹어볼래여 오늘은 스모어 쿠키가 더 땡겨서 쩔 수 없이 . . 🐻🍪🧁 분위기두 차분해서 넘 좋고 조용히 이야기 할 수 있어서 넘 좋습니동 🤭 아챰 여기 거울 맛집입니더 -!-!', 27, 4, 'GOOD', SYSTIMESTAMP);
