INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '홍대입구 카페 네이버에 입력해서 찾아보았는데 생각지도 못한 곳에 너무 예쁜 카페가 있어서 놀랐오요~ 인테리어도 너무 예쁘고 디저트류도 예쁘게 진열되어있었는데 모형인줄 알았어요 ㅎㅎ 카페에서 대화하다보면 내 이야기가 옆 사람에게 들리지 않을까 눈치보게될 때도 있는데 노래소리도 적당히 커서 그럴걱정 없어서 좋은 것 같아요!! 오늘 날씨가 흐려서 기분전환이 필요했는데 기분전환하고 갑니다~', 1, 4, 'GOOD', SYSTIMESTAMP);
