INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '모카크림라떼, 흑임자크림라떼, 바스크치즈케이크 플레인 주문했어요❣️ 가게 인테리어도 예쁘고 테라스가 너무 사진 맛집 bb 에그타르트, 스콘, 마들렌 등 구움과자도 있어요! 크림라떼 커피도 고소하고 위에 쫀쫀 크림도 진해서 디저트랑 잘 어울리고 맛있어요! 엔틱 우드톤이라 대화 나누기도 넘 좋은 곳❣️', 97, 23, 'GOOD', SYSTIMESTAMP);
