INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '홍대입구역의 명소 ''조블라''에 드디어 와봤네요! 예쁜 인테리어 덕분에 사진이 잘 나오기로 유명한 곳이죠! 실제로 와보니 아기자기한 분위기가 제 맘에 쏙 들어요. 시원한 아이스 아메리카노와 함께 플레인 스콘, 치즈 머랭 쿠키, 초코 월넛을 주문했는데요. 맛있는 디저트와 함께 아메리카노를 마시니 한 주의 피로가 싹 풀리며 힐링되는 기분입니다!', 112, 19, 'GOOD', SYSTIMESTAMP);
