INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '유럽감성 인테리어 완전 취향저격이에요!! 햇살 맛집입니다! 햇살 들어올때 테라스자리너무 예뻐요✨✨ 흑임자크림라떼랑 피스타치오크림라떼도 엄청 맛있고 사장님이 직접 만든 디저트도 👍🏻👍🏻👍🏻 곰들렌, 소금초코휘낭시에 갓 구웠을때 진짜 바삭하고 여태 먹은 마들렌휘낭시에 중에 제일 맛있었어요!! 다음에는 시그니처 크림라떼랑 바스크치즈케이크 먹으러 올게요🧡', 22, 0, 'GOOD', SYSTIMESTAMP);
