INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '분위기 좋고 깔끔해요! 날씨 좋은 날에 야외석 앉으니 딱 좋아요 패션후루츠에이드도 상큼하고 맛있어요! 커피도 산미 없이 깔끔해요', 75, 12, 'GOOD', SYSTIMESTAMP);
