INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '홍대근처 예쁜카페, 디저트 맛집 찾다가 발견한 "조블라"카페! 분위기도 넘 좋구~커피도 맛나요🤗 친구가 행복한 시간 보내고 왔네요~ 아! 밤치즈케이크 완전 맛나요😍', 19, 2, 'GOOD', SYSTIMESTAMP);
