INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '네이버 예약이 되서 너무 좋아요! 분위기도 좋고 날 선선할 때 테라스에서 마시면 너무 좋을 것 같아요. 커피도 맛있고 직원분들도 친절하셔서 너무 편안하고 좋은 시간 보내고 갑니다.', 49, 4, 'GOOD', SYSTIMESTAMP);
