INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '이런 곳에 카페가 있다고? 생각하면서 왔는데 길 끝에 정말 아늑하고 우드감성이 가득한 카페가 있어서 너무 귀엽고 예뻐서 놀랐어요 소품들도 아기자기하고 너무 예쁘고 테라스도 좋아요 밤 치즈케이크와 음료도 맛있네요 🫶🏻', 77, 11, 'GOOD', SYSTIMESTAMP);
