INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '지나가다가 유럽풍에 크리스마스 느낌 뿜뿜해서 홀린듯이 들어왓어요!! 근데 분위기이며 스콘 맛도 넘 맛나요ㅠㅠ 여기 트리도 해놔서 사진찍기에도 짱이에요🫶🫶👍👍', 0, 7, 'GOOD', SYSTIMESTAMP);
