INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '카페 분위기가 좋고 사장님이 친절하십니다 디저트도 다양하고 케이크와 촛불등 판매 하는것들이 많아서 자주 방문하게 될 것 같아요! 내부도 멋있게 꾸며져있어 사진찍기 좋습니다', 87, 11, 'GOOD', SYSTIMESTAMP);
