INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '가격도 저렴하고 음료도 맛있어요 인테리어도 잘 꾸며져있어 사진 찍기도 좋았습니다 무엇보다 사장님께서 너무 탁하셔서 너무 좋았습니다 ..><', 53, 12, 'GOOD', SYSTIMESTAMP);
