INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '카페 분위기 너무 좋고, 크림라떼 완죤 맛있어요! 사진 다 잘나와요ㅠㅠ 내가 조블라를 발견하다니! 장하다 나자신! 주문한 메뉴는 자리로 갖다주시고 여기 베이커리 너무 맛있어요! 츄러스 휘낭시에 짱맛!', 56, 18, 'GOOD', SYSTIMESTAMP);
