INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '일단 들어오기 전부터 분위기에 반했고.. 음료도 너무 맛있어요ㅠㅠ 시그니처 크림라떼는 꼭 드세요!! 에그타르트도 제스타일ㅠㅠ 요즘 크리스마스 분위기 나는 곳 찾아가는데 여기도 넘 예뻤어요!!ㅎㅎㅎ', 56, 12, 'GOOD', SYSTIMESTAMP);
