INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '홍대이지만 홍대의 힙함이 아닌 연남의 조용한 카페 느낌이어서 색다른 느낌이에요. 브라운 계열의 톤으로 마춘 카페라서 차분하고 고요한 느낌이 들고, 예쁜만큼 디저트도 귀엽고 맛있어 보이고,, 눈에 보기 좋은 것이 먹기도 좋다고 맛있었습니당 🩷', 5, 9, 'GOOD', SYSTIMESTAMP);
