INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '모카크림라떼 추천! 크림라떼에 은은한 초코향이 더해져서 완전 맛있어요 🍫❤️ 쿠키랑 휘낭시에도 샀는데 완전 맛있고 포장도 정성스럽게 잘 해주셔서 감동 ㅠㅠ 직원분들도 넘 친절하셔요 🥰😍🫶🏻', 38, 8, 'GOOD', SYSTIMESTAMP);
