INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '카페분위기도 좋고 편안합니다! 시그니처 크림커피도 맛있구 케잌도 정말 맛있어요:) 무엇보다 늦게까지 영업하는 카페는 많이 없는데 오후 11시까지 운영해서 편안하게 대화하고 커피도 마실 수 있었습니당', 49, 7, 'GOOD', SYSTIMESTAMP);
