INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '음료도 다양하고 특별한 메뉴가 많아서 마음에 들어용!! 티종류도 다른카페랑 다른 종류들이 있어서 먹어봤는데 정말 맛있어용! 친구 생일이라 당일에 보틀케이크 예약했는데 너무 귀엽게 만들어주셨어요ㅠㅠㅠ귀여움만 있는게 아니라 케이크 진짜 맛있어요!!!', 126, 20, 'GOOD', SYSTIMESTAMP);
