INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '야외테라스가 이쁜 홍대입구근처 카페 조블라 드디어방문!!!! 디저트도 너무 맛있어요 늦게가면 솔드아웃주의 커피 테이크아웃 했는데 진짜 산미 최고 따봉버튼 누르고가요', 2, 9, 'GOOD', SYSTIMESTAMP);
