INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '인스타에서 보고 너무 와보고싶었던 조블라 드뎌 방문...🤎 커피도 넘 맛있지만 바치케가 미쳤어요...;;; 먹어 본 바치케 중 젤 맛있었어요!!! 매장 이쁜 건 말모~~~ 중간중간 사진 스팟이 얼마나 많은 지! 인생샷 건지기 완전 가넝이에요🫶🏻 늦은 오후 방문했더니 다른 디저트들은 솔드아웃 된 게 많아서 사오지 못한 게 한이에요 ㅠㅠㅠ조만간 또 가야겠어요~!!!', 58, 14, 'GOOD', SYSTIMESTAMP);
