INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '여기 테라스가 예쁘다고 해서 갔는데 진짜 유럽풍이라서 넘 좋았어요 카페 안에도 되게 아늑하고 포근한 느낌이라서 친구랑 수다 떨기도 좋더라구요 시그니처메뉴가 크림라떼라고 해서 그거 먹어봤는데 크림 진짜 맛있었어요 디저트는 치즈케이크로 먹어봤는데 완전 부드럽고 치즈향이 엄청 고급스럽더라구요 디저트 퀄리티 진짜 좋아서 넘 만족 ㅎㅎ 날씨 좋으면 무조건 테라스에 앉아보세요 사진 진짜 잘나옴 ㅠㅠ', 7, 0, 'GOOD', SYSTIMESTAMP);
