INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '시끄럽지도 않고 조용해서 좋았어요! 인테리어도 넘 이쁘고 디저트도 맛있네요...🖤 오늘은 혼자 왔는데 다음엔 친구랑와서 이쁜사진 많이 찍고싶네요!!', 12, 10, 'GOOD', SYSTIMESTAMP);
