INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '여기 음료 완전 맛있어요!! 날씨가 좋아서 야외테이블 있는 분위기 좋은 카페 찾고있었는데 입구부터 완전 앤틱한 분위기에 반하고, 가게 인테리어, 조명, 노래 모두 잘 어울리는 곳이에요!! 특히 크림라떼에 올라가있는 크림이 진짜 쫀쫀하니 고소해서 엄청 맛있습니당 ◡̈', 79, 18, 'GOOD', SYSTIMESTAMP);
