INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '분위기 맛집이라 듣고 갔는데 인테리어도 아늑하고 예쁘고 커피,디저트,음료들까지 진짜 다 맛있어서 대만족이였어여^^ 같이 방문했던 지인도 셀카 잘나왔다고 좋아하더라구여ㅎ 조만간 친구들과 재방문 예정이에여~♡', 75, 12, 'GOOD', SYSTIMESTAMP);
