INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '아기자기하고 분위기가 너무 좋았어요! 사장님도 친절하시고 음료도 맛있어서 친구랑 시간 보내다 가기 좋았습니다💕 음악 선곡도 어쩜 그렇게 제 취향으로만 하시는지 디저트와 커피 음악 선곡 모두 완벽해요👏', 153, 81, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '점심쯤만 되면 무척 날씨가 덥더라고요. 홍대 입구역 근처에 약속있어서 갔다가 조블라 다녀왔어요~  리뷰로 유럽풍 분위기의 카페라고 후기를 봐서 가봤는데 인테리어가 역시~  유럽에 와있는 것 같고 느낌있더라고요 ㅋㅋ 맛있는 쿠키랑 디저트도 많이 있길래 고심하다가 쿠키 포장해봤어요 커피도 산미있게 맛있고~  혹시 홍대지나가다 들릴일있으시면 추천합니다~!', 34, 4, 'GOOD', SYSTIMESTAMP);
