INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '유럽풍의 인테리어가 정말 이뻐요!!! 디저트들도 종류가 많고 하나 같이 맛있었어요😋휘낭시에랑 스콘 추천해요ㅎㅎㅎ 그리고 시그니처인 크림라떼도 강츄입니당👍👍', 121, 26, 'GOOD', SYSTIMESTAMP);
