INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '아늑한 공간과 맛난 디저트가 있는 곳에요~ 홍대에 이런 곳이 있었어요 와~ ㅎ 바스크 치즈케이크 정말 부드럽고 입에서 살살 녹아요 😄 바스크 치즈케이크 이곳의 디저트 시그니처 인 듯요~ 음료도 부드럽고 심하게 달지 않아서 좋아요 ㅎ 그리고 레터링 되는 케이크도 판매되고 있어서 좋네요~', 35, 7, 'GOOD', SYSTIMESTAMP);
