INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '홍대입구역 근처에 진짜 예쁜 카페 발견 분위기가 좋아서 들어갔는데 디저트가 맛있어서 홀딱 반한 카페라는!! 사장님도 친절하시고 안에도 자리가 예뻐서 사진 찍고 이야기 나누기도 좋아요', 55, 15, 'GOOD', SYSTIMESTAMP);
