INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '음료 받자마자 벌컥벌컥 마셔버려서 사진을 못찍었어요 ㅜ,ㅜ 커피 고소하니 맛있고 머랭쿠키 꼭 꼭 드셔보세요!! 그리고 가게 내부 진짜 예쁘고 완전 취향저격이에요👍 날씨 선선할땐 밖에 테라스 앉아도 좋을거같고 인테리어가 예뻐서 다른 손님들도 사진 엄청 많이 찍더라구요! 사장님도 너무 친절하시고 좋아요! 케이크 주문했는데 제가 원하는것보다 더더더 잘만들어주셔서 진짜 행복한 날 보냈어요 감사합니다!!! 자주 올게요오 🙆🏻‍♀️💛 디저트 진짜 다 맛있어요 다 드셔보세요 !!!!!!!!', 88, 14, 'GOOD', SYSTIMESTAMP);
