INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '친구들과 홍대 왔다가 들린 카페입니다. 이제 추워져서 못앉겠지만 야외 자리도 있고 좋네요. 내부는 넓지는 않습니다. 커피랑 디저트 모두 맛이 무난하니 괜찮은거 같습니다.', 19, 7, NULL, SYSTIMESTAMP);
