INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '홍대 골목 안에 있는 예쁜 테라스 카페에요. 안과 밖 인테리어가 모두 영화 속에 들어온 듯 예쁩니다. 사진 속 음료들은 아이스 아메리카노와 아이스 크림라떼입니다. 아메리카노는 산미 없이 고소한데 쓴 맛이 전혀 느껴지지 않았어요. 크림라떼는 씨리얼 토핑과 함께 적당히 달콤한 크림이 올라가요. 개인적으로 커피우유 맛이 나서 맛있게 먹었습니다.', 35, 1, 'GOOD', SYSTIMESTAMP);
