INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '우연히 검색하다 들렀는데 숨은 예쁜 카페를 찾았네요! 내부는 따뜻한 분위기이고, 저는 여름 감기에 걸려서 야외에 앉았지만 차양막이 있어 그렇게 덥지 않았어요 아이스 음료 마시며 앉아 있으니 유럽 감성 뿜뿜합니다 :) 요즘 휘낭시에에 꽂혔는데 츄러스 휘낭시에 겉바속촉 너무 맛있어요! 인테리어도 신경 많이 쓰신 것 같아요 + 저희 밖에 앉았다고 어닝 더 내려주시고 너무 친절하세요 ㅎㅎ 덕분에 데이트 잘하고 갑니다❤️', 28, 0, 'GOOD', SYSTIMESTAMP);
