INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '조블랑 카페 홍대와서 친구랑 둘이 이야기하기 너무 편하고 좋네요! 특히 트레이에 손잡이가 있어서 실수할 일 없이 편하게 옮길 수 있어서 좋았어요!', 65, 18, 'GOOD', SYSTIMESTAMP);
