INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '사장님이 너무 친절하시고 크림커피 짱맛있어요 추천추천 ㅎ 인테리어도 우드톤의 편안하고 깔끔한 무드로 잘꾸며져 있었어요! 친구들끼리 수다떨러 오기 너무 좋아보여용 ㅎㅎㅎㅎ 디저트류들도 선물하기 넘 좋을 것 같아요! 화장실 깔끔한 것두 너무너무 맘에듭니당', 107, 25, 'GOOD', SYSTIMESTAMP);
