INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '분위기 아늑해서 넘 좋은 감성카페예요❤️ 맛있어 보이는 디저트가 넘 많아서 결정장애 온 게 힘들었지만 ㅠ 구움과자, 케이크 다맛있어여ㅠ🫶🏻🥹 포토스팟도 많은 카페라 또 가려구용!!', 12, 4, 'GOOD', SYSTIMESTAMP);
