INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '지난 번 방문은 주말이었어서 만석으로 못 들어왔는데, 평일 저녁에 오니 자리가 있었어요. 날이 추워져서 따뜻한 차 한잔이랑 아이스아메리카노 주문했는데, 깔끔하고 좋았어요! 디저트 종류도 많은데, 다음번에 먹으러 오겠습니다😊', 37, 10, 'GOOD', SYSTIMESTAMP);
