INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '바스크치즈케이크 맛있대서 와봤어요ㅎㅎ 후기대로 맛있고 음료도 예쁘고 맛나요! 특히 외부 인테리어 엄청 마음에 들어요!!!! 홍대오시는 분들 한번씩 오셔도 좋을듯해용', 81, 11, 'GOOD', SYSTIMESTAMP);
