INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '홍대에 이렇게 예쁜 테라스카페가 있는지 몰랐어요!! 아기자기한 소품들도 너무 예쁘고 사장님도 친절하시고 음료랑 디저트 너무 맛있고...🥹🫶🏻 뭐 하나 부족함이 없는 곳입니당...', 50, 10, 'GOOD', SYSTIMESTAMP);
