INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '바스크치즈케이크 맛집 소문을 듣고 방문했어요 크리스마스분위기로 카페도 이쁘게 꾸며있어 사진 찍기 좋네요 케이크도 예상대로 넘 맛나서 데이트 잘 했어요 !!', 17, 2, 'GOOD', SYSTIMESTAMP);
