INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '곰들렌 보고 바로 와본 카페에용🐻💛 인테리어가 너무 예쁘고 테라스도 넘 조아요!!! 음료도 곰들렌도 쿠키도 넘 맛있게 먹었습니당ㅎㅎ 곰들렌 먹으로 또 올게용ㅎㅎ 번창하세용💕', 4, 6, 'GOOD', SYSTIMESTAMP);
