INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '골목에 이럴게 좋은곳이 있는줄 몰랐어요! 분위기도 너무 좋고 목재 인테리어와 소품들이 클래식한 분위기를 내고 잘 어울려요! 특히 아기자기한 소품들이 너무 예뻤어용', 13, 9, 'GOOD', SYSTIMESTAMP);
