INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '근처에서 카페 찾다가 들어갔는데 너무 예뻤어요! 아기자기하고 메뉴도 다양하고 디저트 종류도 많아서 취향 저격!! 담에 홍대올 일 있으면 또 와야겠어요💖', 25, 8, 'GOOD', SYSTIMESTAMP);
