INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '처음 들어오자마자 우와~너무 예쁘다!!!!😍😘 사진 찍는거?찍히는거? 좋아하는 사람들이 오면 사진 백만장 찍을수 있을거같아요 사진도 예쁘게 잘나오고 엄청 큰 규모는 아니지만 야외분위기랑 공간이 사진찍기좋게 예뻐요^^ 여긴 어두울때와도 참 예쁠것 같아요!!! 커피는 디카페인이 없어서 아쉬웠지만 디저트도 맛나보이고 아기자기하기도하고 친절하셨어요 😜 대화하기도 좋았고 뭔가 힐링되기도했구 잘 머무르다 갑니다🙏', 107, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '오랜만에 친구랑 홍대에서 만나는데 언니가 최근에 다녀왔던 카페라고 추천해줘서 오게 됐어요! 너무 번잡하지 않아서 얘기하기 좋구 디저트도 맛있네용', 21, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '빈티지 유럽풍 제대로 컨셉 예쁜 공간이네용 홍대입구역 근처카페라 접근성 대박이고 골목쪽에 있어서 시크릿한 너낌? 디저트도 한가득 있어서 골고루 먹어봤는데 다 맛났어용! 테라스도 넘 예뿌게 꾸며놓으심😍 사진 엄청찍엇어유 👍👍', 1, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '크림라떼 먹었는데 달콤쌉싸름해요 피스타치오크림라떼도 달고 맛있어요 크리스마스 분위기가 물씬 나고 음악도 좋아서 연말 분위기 내기 좋은 카페인 것 같아요', 39, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '강아지랑 구경하다가 예쁜 외관에 이끌리듯 들어와 봤는데 동반되서 너무 좋아요 :) 날도 좋아서 외부에 앉았는데 음악도 좋고 편안한 분위기라 적극추천해요 -!', 0, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
