INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '홍대 왔다가 분위기 좋은 카페 발견해서 기분 좋아요! 사장님 넘 친절하셔서 더 좋았어요! 콜드브루 맛있어서 두잔..마심.. 디저트류 왜 다 맛나는거죠! 나가는길에 쿠키 더 구매해서 갑니당 집에가서 뇸뇸할거에요:D 곳곳에 인테리어 포인트 구경하는것도 쏠쏠! 저녁엔 와인도 하신다니..다음에 꼭 와인 맛볼거에용:)', 20, 5, 'GOOD', SYSTIMESTAMP);
