INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '홍대에서 분위기 좋고 맛있는 카페 찾다가 우연히 들어왔는데 생각했던 것보다 훨씬 아늑하고 따뜻한 분위기라서 들어갈 때부터 기분 좋았어요! 그리고 스모어쿠키가 진짜 짱맛 😵‍💫 나중에 방문할 때에는 다른 스모어쿠키도 먹어 보고 싶어요~~ 🫰🫰🫰', 61, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '인테리어가ㅜ미쳤어요! 유럽 빈티지풍에 ~ 포토존도 있고! 사장님도 넘나 친절하시궁 ㅎㅎ왜 디저트포장맛집이라고 하는지 알겠돈,, 초코휘낭시에 강추입니당', 10, 10, 'GOOD', SYSTIMESTAMP);
