INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '메뉴도 다양하고 음료도 맛있어요~ 인테리어도 아기자기 귀엽고 아늑합니다 !! 날씨 선선해지면 바깥 테이블에 앉아도 좋을거같아요 !!', 32, 2, 'GOOD', SYSTIMESTAMP);
