INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '주변이 한적한데 사람은 항상 북적이더라구요!  패션후르츠 에이드 상큼하고 너무 맛있어요!  시그니처 크림라떼는 기본 카페라떼처럼 고소한 라떼 위에 달달한 크림이 듬뿍 올라가있어서 너무 맛나요!!!  치즈케이크도 꾸덕하니 맛있어요! 다음에 또 올게용', 23, 8, 'GOOD', SYSTIMESTAMP);
