INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '홍대놀러와서 어디가지 찾다가 왔어요!! ㅋㅋ 음료도 맛있고 인테리어 깔끔하고 화장실도 내부에 있어서 더 좋아요! 가격도 합리적이라 잘 찾아온것같아요ㅋㅋ', 68, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '음료랑 디저트가 정말 맛있는데 분위기까지 좋아요..💗 홍대 중심가에 있는데 카페가 정말 조용하고 유럽 감성이에요! 단골 카페각입니다✨', 65, 16, 'GOOD', SYSTIMESTAMP);
