INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '우와... 골목 속에 숨어 있어서 찾는 재미도 있고 분위기도 너무 좋아요!! 놀이공원 테마파크 느낌도 엄청 나요!! 날씨 좋을 때 밖에 앉아서 디저트랑 음료 먹으면 진짜 행복할 듯... 사실 안에서 먹고 있는데도 너무 행복해요! 인테리어 & 카페 외관 다 너무 예뻐요.. 🦭', 43, 6, 'GOOD', SYSTIMESTAMP);
