INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '외관이 예뻐서 들어왔던 카페였어요..! 더워서 테라스에 못 앉았지만 테라스가 너무 예쁘네요,,, 디저트 종류도 많고 커피도 맛있었어요 산미 없는 커피 좋아하신다면 추천 드립니다~!', 71, 12, 'GOOD', SYSTIMESTAMP);
