INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '초코 스모어가 먹고싶어서 갔는데 품절이라 조금 아쉬웠지만 🥲 인테리어도 예쁘고 공간도 넓어서 다음에 친구랑 재방문해보고싶어요! 서비스로 주신 곰들렌 넘맛있구요,, 쿠키도 지금 먹고있는데 존맛탱구리입니다,,  사장님도 친절하시구!! 담에 다시갈게요옿ㅎ', 32, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '제대로 유럽 감성 카페였다구요.. 🤍 홍대카페에 이런 곳이 생겨서 넘 조아요 휘낭시에랑 바스크치즈케이크 쟌맛이니 꼬옥 커피랑 다들 먹어주세요 그리고 날씨 좋은 날은 테라스에서 즐겨주시길🫶 (#협찬 업체로부터 이용권을 제공받았습니다🌼)', 18, 5, 'GOOD', SYSTIMESTAMP);
