INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '사장님 너무 친절하시구 인테리어가 이뻐요!! 날씨 선선해지면 밖에 테라스 자리도 좋을 것 같아요~ 커피도 산미없이 고소한 맛이고, 베이커리는 솔드아웃이 많아서 아쉬워요ㅜㅜ!!', 41, 10, NULL, SYSTIMESTAMP);
