INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '사진찍을 시간도 없이 순삭해서 사진이 별로없지만 그중 크림라떼 시그니처는 진짜 제가 가본 카페들중 최고입니다 수제나 음료스페셜한거 좋아하시는분들 무조건 추천!', 76, 17, 'GOOD', SYSTIMESTAMP);
