INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '내부가 깔끔해서 좋아요! 바스크 치즈케이크를 다양한 종류로 판다는 말에 홀린듯이 이끌려 왔고 커피도 케이크도 맛있네요😍 홍대 올 때 자주 들를 것 같아요😄', 129, 22, 'GOOD', SYSTIMESTAMP);
