INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '저번에 방문하고 디저트가 맛있어서 또 왔어요! 쿠키랑 피낭시에 맛집에 크로플까지 진짜 취향저격이에요..🩵비오는 날 와도 어닝이 쳐져있어서 테라스에서 운치있게 먹을 수 있어서 너무 좋았어요  다음에 또 방문할게용☺️', 48, 6, 'GOOD', SYSTIMESTAMP);
