INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '네이버 지도 목록에 있는 거 보고 카페 방문 했는데 제가 생각한 대로 분위기도 빈티지스럽고 아기자기해서 이뻐요. 직원 분도 친절하시고 ..디저트도 귀여워요. 홍대에 이런 카페가 있는 줄은 몰랐네요.', 6, 1, 'GOOD', SYSTIMESTAMP);
