INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '네이버 보고 찾아왔는데 오길 넘 잘한거같아용😊 디저트 호불호없이 다 맛있구 말차라떼 좋아하는데 여기꺼 짱맛…💓 사장님도 엄청 친절하셔요!!! 카페 안의 분위기도 좋은데 테라스에서 사진 잘 나와요😉😉', 5, 3, 'GOOD', SYSTIMESTAMP);
