INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '새로 오픈했길래 바로 방문했습니다 ! 골목 안쪽에 테라스를 갖추고 있는 아늑한 카페라 뭔가 더 신비로운 느낌이예요 🏡 엔틱하고 포근한 인테리어가 예쁘고 주택을 리모델링 한건지 구조가 특이하고 룸이 있어 좋아요 🚪 한 가지 아쉬운 점은 소리가 울리는 편이라 사람들이 큰 소리로 떠들면 많이 시끄럽다는 거 .. 🗣️ 사람 없을 땐 편안히 즐길 수 있는 카페예요 ✨ 유명해지지마 .. 나만 갈거야 .. 🫠', 14, 6, NULL, SYSTIMESTAMP);
