INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '홍대에 이런 곳이 있었다니...🥹🥹 분위기가 너무 예쁘고 사진도 잘 나와요ㅠㅠㅠ 음료도 맛있고.. 새로 생겼던데 자주 오겠습니다...🥹🥹♥️♥️♥️♥️♥️♥️♥️♥️', 58, 16, 'GOOD', SYSTIMESTAMP);
