INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '초코라떼랑 쿠키 먹었는데 맛있었어요! 분위기도 좋고 밖에 테라스도 있고 얘기하기도 좋고 혼자 업무하기도 좋고 종종 들릴 것 같아요ㅎㅎ', 45, 8, 'GOOD', SYSTIMESTAMP);
