INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '들어오는 순간부터 외국에 들어온 듯한 기분을 주는 카페에요!! 디저트 종류도 많고 커피도 맛있어서 다음에 또 오고 싶어요🖤 홍대 카페 찾으시는 분들에게 완전 추천-!✨', 3, 8, 'GOOD', SYSTIMESTAMP);
