INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '귀여운 곰 만들레도 팔고 가게가 작지만 너무 예뻐요!ㅎ우연히 발견한 곳이지만 마음에 쏙 들었어요 소품들도 그렇고 음료도 맛있고 다들 들렸다가세용~~', 5, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '홍대에 새로 오픈한 카페라고 해서 와봤는데 내/외부 인테리어 완죤 이뻐요 ㅎㅎ 특히 외부 자리는 포토존 그 자체!! 요즘처럼 날씨 좋은 날에 자연 조명까지 있어서 완전 인생사진 건질 수 있음!! 그리고 디저트 종류가 엄청 많으니 고르는 재미도 있었습니당 ㅎㅎ 홍대 카페로 추천해욤 크림라떼도 쫜쫜하니 맛남', 18, 0, 'GOOD', SYSTIMESTAMP);
