INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '인테리어가 예뻐서 홍대에 이런장소가 있나 놀랬고, 들어와보니 평화로운 분위기와 맛있는 디저트가 너무 좋았어요 다음에도 방문하고싶네요!', 67, 17, 'GOOD', SYSTIMESTAMP);
