INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '우아 크림 맛이 진짜진짜 너무 맛있어요!!!!!!!!꼭꼭 다시 와서 다른메뉴도 먹어볼거에용👍👍👍 다른 디저트도 정말 맛있어여🥰', 22, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '말차라떼가 쓰지 않고 달달해요. 피스타치오 크림라떼는 다시 먹고 싶을 정도로 정말 맛있었어요. 다시 올 의향이 있습니다!!. 분위기도 좋았고 인테리어가 깔끔하게 잘 되어 있었습니다.', 56, 17, 'GOOD', SYSTIMESTAMP);
