INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '✔️ 홍대 골목길 유럽감성 신상카페🍪☕️ 골목끝에 마치 마법공간처럼 유럽느낌 물씬나는 카페가 나타나 순간이동한 느낌이었어요🥹 외부 테라스만큼 가게내부도 인테리어가 예뻐요. 쿠키랑 스콘이랑 이것저것 시켜서 먹어봤는데 스콘이 진짜 맛있어요! 질깃하고 눅눅한 스콘 싫어하는데 겉빠속촉에 생크림스콘은 위에 소금이 올라가서 짭쪼롬하고 초코칩은 안에 가득 들어서 꼬독꼬독하고 위에 드리즐되어있어서 좋았어요. 커피랑 말차라떼도 맛있고 생분해빨때 사용하셔서 좋아요:) 당일케이크도 예약받으시고 디저트 종류도 다양해서 못 먹어본 음료랑 디저트 먹으로 또 갈거에요🐻', 21, 2, 'GOOD', SYSTIMESTAMP);
