INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '카페 분위기가 좋아서 예약하고 들어왔는데, 되게 아기자기하고 음료도 맛있어요!!🫶🏻 홍대쪽에 이런 카페가 있을 줄은 몰랐는데 백퍼센트 만족입니당~~~🩷', 23, 0, 'GOOD', SYSTIMESTAMP);
