INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '저도 홍대카페 여럿 다녀봤지만, 야외테라스 구비되어있는 건 정말 처음 봤어요 👏👏 빈티지 유럽 인테리어와 소품들이 눈에 띄는 공간에, 디저트 종류도 너무 다양하고 다 맛있어 보이더라구여👍💕 무려 모두 수제디저트 라고 하시더라구요❤️❤️ 시그니처 크림라떼와 아메리카노도 맛있구 연남주문제작케이크로 유명한 곳 답게, 다양한 주문제작케이크도 있었답니다 😋💕 나중에 홍대바스크치즈케이크가 생각나면 또 오고 싶은 조블라에요😍😍', 52, 15, 'GOOD', SYSTIMESTAMP);
