INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '홍대에 약속이 있어서 근처 카페를 찾다가 오게 됐어요!! 인테리어도 너무 아기자기 예쁘고, 무엇보다 음료가 너무 맛있었어요!! 피스타치오 라떼 크림이 아주 냠냠했습니다:) 다음에도 홍대 올 일 있으면 또 올 것 같아요!!💓', 64, 13, 'GOOD', SYSTIMESTAMP);
