INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '홍대에 이렇게 분위기 좋은 곳이 있는지 처음 알았어요❣️❣️분위기 완전 지중해 스타일이고 음료도 다 맛있는데다가 레터링 케이크 맛집이라더니 베이커리 종류도 다 맛있게 먹었네요ㅎㅎ다음에 또 오겠습니다', 13, 9, 'GOOD', SYSTIMESTAMP);
