INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '여기 별 다섯개도 부족할정도로 유럽 감성의 이쁜 카페예요🥰 사장님도 친절하시고 디저트들도 하나같이 다 맛있어요🥰야외 테라스도 넓고 이뻐서 날씨 좋은날에 먹음 좋을것같아요🙏  홍대 이쁜카페 알아가서 좋네요👍', 77, 16, 'GOOD', SYSTIMESTAMP);
