INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '인테리어도 너무예쁘고 무엇보다 나오는 노래들이 너무 좋아요 ㅠㅠㅠ 분위기짱 치즈케이크도 너무맛있고 즐겁고 편안하게있다가 갑니다💗', 40, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '인테리어도 예쁘고 깔끔해서 사진찍기 되게 좋아요. 분위기가 아늑해서 친구랑 도란도란 수다떨기도 좋고 서울 한복판에 있지만 시골 마당있는 집에서 잠깐 쉬다가는 기분도 들어요. 다음에 날씨가 좋다면 밖에서 마셔보고 싶을 정도로 다 잘 꾸며 놓으셨어요. 사장님도 엄청 친절하시고 디저트도 맛있습니다. 아포가토 고소하니 엄청 맛있어요! 자리도 많고 잠시 쉬다가기 좋은 곳 같습니다🥰🥰', 27, 3, 'GOOD', SYSTIMESTAMP);
