INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '눈으로 보고 맛으로 먹는 카페☕️☕️ 커피도 향긋하고 디저트도 달달해요!(그렇다고 설탕 퍼부은 단맛은 절대 아님!) 홍대 골목 사이에 이런 곳이 있었다니...👀 직원분들도 친절하시고 보물 같은 곳입니다.✨ 인테리어, 익스테리어 둘다 예뻐서 사진 남기기도 좋으니📸 연인, 친구들과 예쁜 감성카페 찾으시는 분들 강츄츄츄💕', 9, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '친절하고 고급스러운느낌?? 있었어요 손님이 나가면 사장님이 테이블을 닦아서 깨끗하게 하고있었어용 물이 있으면 더 좋았고 와이파이는 영수증에 써있어요', 20, 7, 'GOOD', SYSTIMESTAMP);
