INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '홍대에 이렇게 조용하고 감성적인 디저트 카페가 있는지 몰랐어요 !!! 늦게가면 디저트 품절 많으니 일찍 방문을 추천두림다 다음엔 이른시간에 가서 얼그레이레몬 쿠키 꼭 먹겠어요 .. 😋', 70, 14, 'GOOD', SYSTIMESTAMP);
