INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '인터넷에서 디저트 맛집으로 유명하다고 해서 왔는데 인테리어도 이쁘고 음료도 맛있었어요!바스크 치즈케이크 플레인 맛이 제일 맛있는거 같아요 많이 파세요🤩🤩', 36, 1, 'GOOD', SYSTIMESTAMP);
