INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '프라이빗룸이 따로 있어서 예약하고 갔는데 대화 나누기 너무 좋았어요! 건물 외관부터 내부 인테리어까지 하나하나 신경쓰신게 느껴질 정도로 너무 예뻐요♥ 디저트류부터 음료부터 다 맛있습니당! 다음에 또 오고 싶어요', 22, 1, 'GOOD', SYSTIMESTAMP);
