INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '인테리어가 너무 예뻐요❤️ 유럽감성 인테리어라서 사진도 예쁘게 나오고 사장님도 진짜 친절하세여 ㅎㅎ 디저트 종류가 많아서 고르는 재미도 있구 또 얼마나 맛있게요~~? 다음에 또 재방문 의사 100% 입니당ㅎㅎ', 22, 6, 'GOOD', SYSTIMESTAMP);
