INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '분위기 넘 좋고, 커피도 맛있어요:) 베이커리도 바로 만드시는거 같아서 있는 내내 맛있는 빵 냄새도 즐길수 있었습니다ㅎㅎ 앞으로 홍대서 커피 마실때 자주 올 거 같아요! P.S. 화장실도 엄청 깨끗해요', 36, 2, 'GOOD', SYSTIMESTAMP);
