INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '일단 들어설 때부터 유럽 느낌의 인테리어라서 기분이 좋았어요ㅎㅎ 따뜻한 우드 느낌 인테리어라서 여성분들이 좋아할만한 인테리어예요. 밖에 테라스도 있어서 좀 더 선선한 날씨에 오면 더 좋을 거 같아요! 음료도 맛있었고 우드 트레이도 예뻤어요🤗', 470, 85, 'GOOD', SYSTIMESTAMP);
