INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '아기자기하고 귀여운 카페에요! 예쁜 정원에서 커피 먹는 기분이에요 ㅎㅎ 츄러스 휘낭시에도 맛있고 크림라떼도 진짜 맛있어요~ 또 오고 싶은 곳이에요 💕', 161, 70, 'GOOD', SYSTIMESTAMP);
