INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '째즈 음악이 가득한, 테라스 공간에서 잠시동안 유럽에 온 것 같은 기분을 느꼈어요..! 숨은 나만의 비밀공간 찾은 느낌!! 여름에 💕 자주 올것 같아요 😍 절대 아무곳에서 판매하지 않는 *피넛버터밀크 스타우트* 발견해서 너무 신났어용 진득한 흑맥주에 피넛향과 초콜릿향이 가득해서 정말 좋아하는 맥주인데 !! 파는곳이 많지 않아서 이렇게 가끔씩 먹으면 ㅠㅠ 감동 😭😭😭🥹 낮술! 혼술! 편안하게 즐길 공간 생겼어요 😍😍 😍😍😍😍😍', 0, 0, 'GOOD', SYSTIMESTAMP);
