INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '홍대입구역 근처에 신상카페가생겼다길래 바로가보기😋 디저트고르는데에만 한참걸렸네여..전부다 맛나보여서;;; 어렵게고른 메뉴들, 맛은 말해뭐해👍🏻👍🏻👍🏻 저희가 간날 야외테라스(?)를 예쁘신 사장님이 직접 정성껏 꾸미고계셨는데 완성이안됐는데도 불구하고 넘예뻐보였어여 완성된모습 넘나궁금🥺🥺 기대하고 조만간 다시 방문할게여~! #단골집추가', 35, 3, 'GOOD', SYSTIMESTAMP);
