INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '진짜 맛있네요...💕 타르트 바삭하구, 쿠키 진하구, 밀크티 진짜 진하구 맛있어요 !! 심지어 가격도착하고, 위치도 좋음!! 믿고 방문해보세요~!', 93, 23, 'GOOD', SYSTIMESTAMP);
