INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '홍대 안에 숨어있는 이쁜 공간입니다! 바깥에 있는 테라스가 너무 이뻐서 날씨가 조금만 시원했으면 테라스에 앉아있는것도 좋은 선택같습니다. 이쁜 벽돌들로 꾸며져 있는 실외 실내 인테리어 모두 마음에 드네요 :)', 40, 9, 'GOOD', SYSTIMESTAMP);
