INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '아기자기한 유럽감성을 느낄 수 있는 카페 조블라. 홍대입구 근처에 있어 접근성이 좋지만 생각보다 골목 안에 숨겨져있기 때문에 알고 찾아오지 않는 이상 우연히 방문하기는 힘들 것 같아요 조블라는 쿠키, 스콘 종류를 맛볼 수 있는 디저트카페로 널찍한 매장과 매력적인 테라스 자리가 있는 곳이에요 전 크림모카라떼를 시켰는데 당땡길 때 먹기 딱 괜찮은 커피였고 귀여운 곰돌이 빵도 귀여웠어요🐻 사장님도 친절하셔서 더 번창하셨으면 좋겠어요!', 34, 2, 'GOOD', SYSTIMESTAMP);
