INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '홍대입구역 근처에 진짜 예쁜 카페가 생겼네요! 카페가 넓고 유럽 정원 분위기라 너무 좋아요. 잔잔한 음악 맛있는 커피와 디저트! 홍대에 오면 꼭 와야할 곳 리스트업!', 47, 1, 'GOOD', SYSTIMESTAMP);
