INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '몇일전에 카페에서 커피랑 디저트 넘 맛있게먹어서,,레터링케이크도 하신다길래 주문했는데 이쁭건 물론이고 리얼 핵존맛이에용 !!! 딱 제가 원하는색감에~~ 사장님센스 짱입니다 ㅠ 케익 묶어주는 저 리본까지 넘 예뻤어요오오 담에 생파할때 도시락말고 큰 케이크 주문하로 올게욤 ♥️', 24, 2, 'GOOD', SYSTIMESTAMP);
