INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '바스크치즈케잌 맛집…🫶🏻 제가 한 바스크녀인데 인정합니다.. 네이버 카페 검색해서 들어왔는데 이런 맛집을 ㅠㅠ 사장님도 너무 친절해요🥰❤️', 28, 10, 'GOOD', SYSTIMESTAMP);
