INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '우연히 들린 카페인데 분위기, 인테리어 너무 좋고 사장님이 친절하셔서 기분 좋게 머물다 갑니다. 소품 하나하나 신경 쓰신 게 눈에 보이고, 곳곳에 사진 스팟도 많아서 사진 찍기 좋을 것 같아요. 쿠키는 완전 꾸덕한 스타일은 아니고 적당히 촉촉 묵직한 스타일입니다. 스모어 쿠키는 기본적으로 데워지지 않고 나오는데, 데워달라 요청 드리고 먹으면 더 맛있을 것 같아요.', 26, 2, 'GOOD', SYSTIMESTAMP);
