INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '홍대 골목에 이렇게 예쁜 카페가 있다니 신기해요🤩 매장도 너무 예쁘고, 디저트와 커피도 맛있어요! 화장실도 안에 있답니다.. 최고..😳🖤', 3, 9, 'GOOD', SYSTIMESTAMP);
