INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '홍대속 유럽 감성 신상 카페! 실내도 너무 예쁜데, 야외 자리가 너무 예뻐서 어디 앉을까 고민했어요! 남편이랑 오랜만에 데이트였는데 :) 숨은 카페 찾아낸 기분이라, 너무 좋은 시간 보내다가 왔어요! 저 귀어운 머링쿠키가 어찌나 맛있던지, 크림라떼 맛집 인정! 다음번에 와서 먹어볼 메뉴맛도 기대중💕 5월부터는 와인도 판매한다는데, 디저트+ 샴페인 마시러 꼭 다시 올꺼얏', 31, 6, 'GOOD', SYSTIMESTAMP);
