INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '머랭쿠키는 순삭..친구들 나눠주기도 너무좋아요. 한참을 마시고 놀다가 포장도 해왔는데 너무좋아요. 흑임자와 초코크림음료는진짜맛있었어요. 어제 포장해온 스콘과 휘낭시에 먹는데 오늘도 너무맛있어요. 매장에서 찍음사진은 똥손인 저도 너무 만족스럽게 잘 나왔네요^^ 맛도좋고 사진도 잘 나오는 카페예요^^또 가야겠어요♡', 11, 2, 'GOOD', SYSTIMESTAMP);
