INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), 'JOVULAR : 행복에겨운, 사랑이넘치는 뜻 답게 홍대입구역에서 접근성도 좋은데 유럽느낌의 정원과 우드톤의 아기자기한 감성이 사랑이 넘치는 곳', 52, 12, 'GOOD', SYSTIMESTAMP);
