INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '완전 유럽 그 자체 한국이라곤 전혀 느껴지지않는 곳 유럽 빈티지 감성 가득함 포토존 많구요 홍대오면 한번은 꼭 방문해야하는 곳입니당 커피랑 디저트도 맛있어요ㅎㅎ', 370, 29, 'GOOD', SYSTIMESTAMP);
