INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '조블라 홍대점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '비가 와서 갑자기 들어온 곳이지만 시그니처 크림라떼가 진짜 맛있었어요 !!🤤 크림은 쫀득 그자체.... 홍대 오면 또 올것같어요', 31, 5, 'GOOD', SYSTIMESTAMP);
