INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크 밀쿠'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '보통 레터링 케이크 집 당일 예약도 안되고 한데 여기는 ✨️당일 케이크✨️가 있어서 예약 없이 살 수 있고 레터링도 바로 써주셔서 넘 좋아요❤️ 디자인도 너무 예뻐서 돈이 하나도 안아깝습니다 ㅎㅎ', 17, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크 밀쿠'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '오랫만에,,? 홍대당일케이크 구매하러왔습니당!!! 여전히 존맛초코케이크 밀쿠🍰🤍 (케이크가 먹고싶어서 파티를 하는 1인,,🐷) 위에 올라간 초콜릿조차도 맛도리네용!!?👍😆 역쉬,,홍대당일케이크는 밀쿠잖아용!!!! 오래오래 홍대케이크집해주세요!!🙏🙏 저는 계속올꺼니까요오어어어🫶', 41, 4, 'GOOD', SYSTIMESTAMP);
