INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크 밀쿠'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '급하게 케이크 필요해서 방문했는데 당일 레터링 케이크 중에 젤루 이쁜거 같아요 진짜루🩵 너무너무 대만족🍀 다다 귀여워서 고르는데 어려었을 정도,,, 레터링 삐뚤하고 엉성하게 써주는 데도 잇는데 밀쿠는 진짜 글씨체 넘귀💖 그리고 엄청 빨리 서주시고 사장님 쏘 친절,,, 담에 필요할때 또 방문할고에요ꔛ', 9, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크 밀쿠'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '당일케이크가 급하게 필요했는데 높은 퀄리티에 당일 레터링까지 가능하다고 와서 오게 되었습니다! 멀어도 충분히 올만큼 가치있다고 생각해요🥰 17시 정도에 왔는데 마지막 남은 케이크였습니다! 인기가 좋아서 빨리빨리 나가는 것 같으니 필요하신 분은 빨리 방문하시는게 좋을 거 같아요~ 사장님 응대도 완전 친절하시고 퀄리티도 너무너무 좋습니다 ㅎㅎ 생일 케이크 급하게 필요하신 분 완전 추천드려요~ ♡ 덕분에 아빠생일 잘챙긴 효녀 됐어요🥺❤️', 12, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크 밀쿠'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '예약 없이 구매할 수 있어서 좋아요! 도시락 케이크 레터링도 바로 해주시고 초도 이쁜 거 많아요 ㅎㅎㅎ 사장님도 너무 친절하시네요 다음에는 예약하구 올게용😁', 6, 10, 'GOOD', SYSTIMESTAMP);
