INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크 밀쿠'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '연남 밀쿠케이크에서 너무너무 귀여운 도시락 케이크 픽업했어요 🐶🎀🩷 사장님 너무 친절하시고 비주얼 최고예요 ㅜㅜㅜ 덕분에 특별한 기념일이 될 것 같아요 💗', 43, 10, 'GOOD', SYSTIMESTAMP);
