INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크 밀쿠'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '케이크도 너무 귀엽고 매장도 청결하고 친절하세요!😍 당일케이크가 있어서 너무 좋은 것 같아요! 다음에 또 이용할게요 감사합니다!', 4, 1, 'GOOD', SYSTIMESTAMP);
