INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크 밀쿠'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '저번에 맞춘 케이크가 너무 만족스러워서 또 방문했어요 ㅎㅎ 케이크도 너무 이쁘고 무엇보다도 맛나요!! 항상 친절한 응대 감사드려요 ☺️', 51, 14, 'GOOD', SYSTIMESTAMP);
