INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크 밀쿠'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '당장 내일 필요해서 급히 당일 제작 가능한 곳 찾아보다가 왔습니다! 문구도 이쁘게 작성해주셔서 기분이 좋네요~~!! 급히 필요하신 분들 오시면 좋을 것 같아요! 감사합니다~~', 49, 4, 'GOOD', SYSTIMESTAMP);
