INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크 밀쿠'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '엄마 생신 케이크 급하게 찾아서 왔는데 마지막 당일케이크 겟겟! 보통 당일케이크는 간단한 디자인이 대부분인데 당일케이크 퀄이 주문제작 케이크만큼 좋은 것 같아요! 담에는 주문제작으로 다시 올게요~~', 31, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크 밀쿠'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '내일이 기념일이라서 케익을 빨리 마련해야했는데 근처에 당일케익 퀄리티좋은 집을 발견했네요!!!! 다음에는 제작주문도해봐야겠어요♥️♥️ 초 종류도 다양해서 좋아용>_<', 30, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크 밀쿠'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '너무 친절하세요 당일에 사러 갔는데 추천 문구도 알려주시고 웃으면서 상냥히 대해주셨습니다 보냉백도 재활용할 수 있는 멋진 보냉팩이네요 좋아요 아직 안 먹어봤지만 맛있을 거 같아여', 50, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크 밀쿠'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '친구 생릴선물로 당일케이크 사허 왔어요! 당일인데도 디자인이 너무 귀여워서 만족중🎶 문구도 바로 원하는 대로 써주시고 넘넘 예뻐용!!', 74, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크 밀쿠'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '케이크를 미리 준비 못했는데, 당일 케이크가 가능하다고 해서 방문했습니다:) 당일 케이크들이 너무 예쁘서 만족스러운 기념일 케이크 셀렉이었습니다!💓', 58, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크 밀쿠'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '예약 없이 방문했는데도 주문제작 케이크처럼 받을 수 있는 부분이 넘 좋은 거 같아요ㅠㅠㅠㅠㅠㅠㅠ🫶 그자리에서 바로 레터링 작성해주시고(1~2분 소요), 아주 친절하셨습니다❗️❗️😍', 39, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크 밀쿠'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '당일케이크 구매했습니다! 레터링도 빠르게 작성해주시고,사장님이 친절하세요^^ 다른곳도 방문했었는데, 여기가 제일 귀여워서 바로 구매했어요! 먹어본 도시락 케이크중에 가장맛있었어요💕다음에도 방문할 생각입니다~', 4, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크 밀쿠'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '많은 사람들에게 알려주고 싶어서 리뷰를 씁니다! 사진 로딩이 안되어서 그냥 올립니다! 홍대~ 연남동 레터링케이크 당일케이크 친구들이랑 여러번 구매 해본 결과 여기가 원탑인 것 같습니다. 강아지 캐릭터 올라가있는 케이크 너무너무 귀여웠고 사장님 너무 친절하시고 귀여우셨습니다!', 60, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크 밀쿠'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), 'n번째 재방문입니당!!!! 사장님 케이크가 너무 뽀짝하구!맛있어서 자꾸 찾게됩니다!!!🍒마침 귤푸린이 남아있어서 다행이예요!😆케이크랑 글씨체가 너무 귀여워요!!!!!🩷', 28, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크 밀쿠'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), 'N번째 재방문 입니당😍 갈때마다 사장님도 너무 친절하시고 케이크가 진짜 너무너무 귀여워요..❣️ 고를때 엄청 고민하게됩니다…🩷 당일케이크로 자주 구매했는데 정말 맛있고 예쁜 레터링 덕에 항상 기분좋은 날 보냈어요!🩵 특별한 날 케이크하고 싶을때 추천드려요❣️ 산리오 캐릭터들도 너무 귀엽습니당❤️ 주변 케이크 집 중에 예쁜 초 종류도 많고 좋아용 🎂🕯️', 7, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크 밀쿠'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '주문제작 하려고 하다가 시간이 촉박해서 당일로 왔는데 당일케이크조차 디자인이 너무 귀엽고 레터링도 너무 귀여워서 맘에 듭니다!! 오길 잘했어요ㅠㅠ 예쁜 케이크 감사합니다🫶🏻🩷', 5, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크 밀쿠'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '당일케이크 인스타에 공지 올린지 1시간 만에 거의 다 팔렸지만 다 너무 예뻐서 남아있는 케이쿠도 너무너 예뻤습니당 🩵❤️🩵❤️ 케이쿠밀쿠에서 다음엔 커스텀으로 해봐야겠어용 ㅎㅎ', 28, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크 밀쿠'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '당일케이크 찾아보다가 디자인이 너무예뻐서 오게됐는데 사장님도 너무 친절하시고 케이크도 너무 이뻐서 진짜 만족입니다ㅠㅠ 사장님 추운데 감기조심하시구 건강하세요ㅠㅠ 진짜 너무이뻐요 최고!!!!!!!!', 45, 9, 'GOOD', SYSTIMESTAMP);
