INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크 밀쿠'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '당일 케이크 구하기 어려웠는데 1분 만에 작성할 수 있어서 너무 좋았어요!! 내부는 깨끗하고 엄청 청결해요! 그리고 무엇보다 설명도 잘해주시고 친절하신 사장님 최고 🤍', 22, 4, 'GOOD', SYSTIMESTAMP);
