INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크 밀쿠'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '두번째방문입니당!저번에는 도시락이었는데 이번에는 당일케이크에 옥지가 있어서 냅다 구매했습니다!!!😃남자친구 생일에 아주 맛있게 잘 먹었어요!!!🫶ㅋㅋ핵맛도리!숟가락으로 퍼먹었어요!!!!!!👍ㅋㅋㅋ케이크 상자도 너무 귀여웠는데!🩷열었더니!더 귀여운!!옥지가있어서!만족스러웠습니다!!!!!ㅋㅋ다음에도 또 방문할꺼예용!!!!사장님!💝', 12, 3, 'GOOD', SYSTIMESTAMP);
