INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크 밀쿠'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '당일케이크 구매했습니당! 이벤트하고계셔서! 초도 받았는데!불자마자 먹어버려서!처음찍은사진만 올립니다,,😓 사장님께서 매우 친절하시고!먹기전에 꺼내두라고하셨는데!덕분에 아주 맛나게 잘 먹었습니다!😋 친구들이랑 여행기념으로 구매했는데!칭찬 받았어요!!!!!캐릭터도 너무 귀엽고!맛도리 였습니다!!!❤️다음에도 또 올게요오~~', 118, 22, 'GOOD', SYSTIMESTAMP);
