INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크 밀쿠'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '주문제작 맡길 시간이 없어서 급히 검색해서 들어왔는데 사장님 너무 친절하시고 당일 도시락 케이크 디자인 너무 예뻐요 ❤️❤️센스 짱이세요 덕분에 친구 생일 잘 축하해 줄 것 같아요 다음에 또 방문하겠습니다 👍😄', 44, 3, 'GOOD', SYSTIMESTAMP);
