INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크 밀쿠'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '당일케이크 이렇게 예쁜 곳 처음 보는 것 같아요 💗💗 실물 깡패입니다!  급하게 골라야 했는데 귀여운 케이크 꽤 남아있어서 잘 골랐습니다 감사합니다!!!', 72, 15, 'GOOD', SYSTIMESTAMP);
