INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크 밀쿠'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '여자친구 생일케이크를 사러 케이크밀꾸 당일케이크를 주문해보았습니다! 예쁜 케이크에 센스있는 문구까지 정말 감사합니다! 많이들 방문하세요~', 34, 5, 'GOOD', SYSTIMESTAMP);
