INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크 밀쿠'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '친구 생일인데 케이크를 못 맞춰서 급하게 당일케이크 구매하러 방문했어요. 너무귀여운 입체케이크 있어서 바로 구매…!!! 친구도 너무 귀엽다고 좋아했아요. 맛도 겉에 크림치즈? 엄청 맛있어요 다음에는 주문제작 케이크도 구매해보려구요!!! 사장님 대박나세요!', 23, 4, 'GOOD', SYSTIMESTAMP);
