INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크 밀쿠'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '친구 생일기념 이쁜 케이크 서프라이즈 해주고 싶어서 1시에 맞춰서 왔는데 1픽은 아니였지만 2픽였던 너무너무 기여운 노랭이 대꼬 와서 만족스러워요! 가격대는 초큼 있는 편인데 실물 보니까 너무 이해가 가는 퀄리티에요! 사장님도 너무 친절하시고 기념일에 또 올것 같아요!', 19, 2, 'GOOD', SYSTIMESTAMP);
