INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크 밀쿠'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '친구들이랑 숙소잡고 노는날 급하게 예쁜케이크 사고싶어서 찾아보다가 여기서 당일케이크 구매했어요! 사장님 너무 친절하시고 케이크도 맛있었어요!🤭💚', 24, 0, 'GOOD', SYSTIMESTAMP);
