INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크 밀쿠'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '갑작스럽게 서프라이즈로 준비한건데 만족했어요! 해리포터 케이크도 예쁘고 사장님은 쏘쓰윗친절,,🥹 생일인 친구도 만족해서 넘 기뻤습니다. 가나슈로먹었는데 초코 꾸덕 그 잡채!! 맛있었습니다. 재주문 할거같아요 ㅎㅎ', 7, 1, 'GOOD', SYSTIMESTAMP);
