INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크 밀쿠'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '급하게 주문 케이크가 필요했는데 인스타보고 당일 케이크가 가능하다해서 바로 달려왔는데 퀄리티랑 문구도 자리에서 바로 써주셔서 너무 좋아요.ᐟ.ᐟ.ᐟ🫶🏻🫶🏻다음엔 주문케이크로 주문하고싶네용🤍', 89, 15, 'GOOD', SYSTIMESTAMP);
