INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크 밀쿠'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '친구 생일선물로 케이크가 필요해서 갔는데 귀여운 디자인이 많고 친절했어요~ 당일케이크 디자인이 여러개라 급하게 케이크 필요할 때 강추입니다! 색감이 너무 예뻐요😍', 10, 8, 'GOOD', SYSTIMESTAMP);
