INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이크 밀쿠'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '당일에 케이크가 필요해서 당일케이크 구매했습니다@@@ 디자인이 예쁘고 귀여운거 같아요 :) 오레오생크림이 부드러웠습니다~~~ 당일구매케이크인데 너무 만족스러웠습니다 선물한 보람이 있었어요 엄청 좋아해요 ㅠㅡㅠ 감사합니다', 27, 0, 'GOOD', SYSTIMESTAMP);
