INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '아이가 당고를 진짜 좋아하는데 직접 구워주는 곳이 계셔서 바로 주문해보았어요! 보는 맛도 있는 곳! 당고 3가지 맛과 말차라떼 구매했는데 너무 잘어울리고 맛있었습니다! 일본에서 먹은 것 만큼 맛있어요!', 18, 1, 'GOOD', SYSTIMESTAMP);
