INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '주말이라 옆매장까지 줄서서 기다림 사장님 혼자 하셔서 기다릴 수 밖에없음 홍대에서 당고하면 우마이 당고 !! 골목에 위치해 있고 차도 들락날락해서 한줄로 기다려서 받야함 진짜 일본 온 느낌 낭낭 노래도 일본 노래로 나옴 당일 아침부터 떡을 직접 찌심ㅠ🥺👍🏼', 45, 4, 'GOOD', SYSTIMESTAMP);
