INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '일본에서 당고 먹고 반해서 찾아왔습니당 ㅎㅎ 그런데 …. 세상에나 너무너무 맛있어요🥹 직원분도 친절하시고 제가 좋아하는 노래도 나와서 행복해요💗 현대백화점 팝업스토어도 하셨던데 앞으로 더 유명해졌으면 좋겠습니당!!!!!!!', 11, 4, 'GOOD', SYSTIMESTAMP);
