INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '길 가다가 발견한 곳인데 간판이랑 포장용기 너무 귀여워요!!!! 앞에서 직접 굽고 계셔서 보는 맛도 있고 매운맛이랑 기본맛인 간장에 인절미 가루 있는 거 먹어봤는데 간장에 인절미 넘 맛이써요 ㅎㅎ', 13, 9, 'GOOD', SYSTIMESTAMP);
