INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '일본여행에서 먹었던 당고가 그리워서 먹으러왔는데 대만족입니다!! 간장맛이 짭조름하니 너무 맛있어요!! 다음에 또 와야겠어요💕💕', 47, 7, 'GOOD', SYSTIMESTAMP);
