INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '쫄깃한 식감에 달콤한 소스가 잘 어울려서 정말 맛있게 먹었어요. 한입 크기라 먹기도 편하고, 은은한 단맛이라 질리지 않네요. 따뜻하게 먹으니 더 부드럽고 고소해서 디저트로 딱이었습니다. 분위기도 아기자기하고 직원분도 친절해서 기분 좋게 즐기고 왔습니다. 추천합니다!', 1, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '우마이당고! 일본에서 당고를 먹고 오랜만에 당고가 생각나 더운 여름날에도 들렸어요!! 당고 종류가 생각보다 많아서 1차로 놀라고, 가격도 합리적인 편이라 2차로 놀랐고, 직접 굽는 모습을 볼 수 있어서 3차로 놀랐네요ㅎㅎ 바로 구워서 그런지 쫀득함은 말모구요ㅠㅠㅠ넘 맛있어서 당충전 제대로 했습니다~~담엔 다른 맛도 먹어보고파요! 2꼬치에 5900원이구요! 최대한 당일섭취를 권장한다고 하네요!(당일섭취추천!)', 19, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '인스타에서 보고 궁금했던 곳‼️ 드디어 영접했어요! 친구들이 먹을 때는 배불러서 못먹어봤는데 남자친구랑 와서 오픈하자마자 바로 주문번호 1번으로 먹었는데 ㅠㅠ 진짜 너모 쫀득하고 맛있더라구요 🥺🤎👍 콩고물도 많이 주시고, 굽기도 세심하게 체크하시구, 날이 더운데 불 앞에 계시느라 짜증나실 법도 한데 너무 친절하게 응대해주신 것도 기분이 좋더라구요. 아무래도 받기까지 조금 시간이 걸리긴 해도 그 시간만큼 즐거웠어요. 처음이라 기본맛을 먹었는데 다음에는 다른 맛도 먹어보고 싶어요 ! 💕 연남동 구경하실 때 여기도 꼭 오세요! 사람이 많아 오픈런 필수인거같아요ㅜ', 74, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '길가다가 당고집 발견해서 신나는 맘에 바로 먹었습니다!! 연남동 한복판에 당고라니!! 맛도 엄청 다양하고 포장도 깔끔해서 하나씩 들고 연남동 걸어다니기 딱 좋아요! 😋 바로바로 구워주셔서 쫄깃하고 단짠단짠 완전 맛있어요!', 86, 12, 'GOOD', SYSTIMESTAMP);
