INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '꼭 홍대가면 가 보고싶었던 곳 중에 한 곳이였는데!! 밥 먹고 바로 옆에 당고집이라서 더 특별하네요 한국에서 당고라니..!! 그것도 여러가지 다양한 당고들이 직접 앞에서 구워 주시는데 굿👍', 491, 73, 'GOOD', SYSTIMESTAMP);
