INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '예전부터 너무 먹고싶었는데 드디어 방문했습니다!! 당고가 너무 쫄깃하고 달콤하고.. 일본가서 먹었던 맛과 유사해서 덕분에 추억여행했어요ㅎㅎ 맛있게 잘 먹었습니다~!!', 49, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '지나갈때마다 사람많아서 먹어보고싶었는데 !!!!! 분위기도 좋고 종류도 많아서 골라먹기 좋은 거 같아요^_^ 이번엔 시그니처 먹어봤는데 다음엔 다른 종류도 먹어보려구요!!!!', 23, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '유명해지기 전에 먹어봤었는데 그 이후로 인스타에 많이 뜨더라구요 ㅎㅎㅎ 오늘 다시 왔는데 역시 진짜 맛있어요 일본에서 당고 먹었을 땐 실망했는데 여기 당고는.. 만화 보면서 상상했던 그 당고맛이에요 정말 최고....ㅠㅠ', 15, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '아이가 당고 먹고 싶어해서 찾아서 왔어요~ 예전에 지나가며 봤을 때는 줄이 엄청 서있었는데 오늘은 문닫을때즈음 가서 그런지 줄 없이 바로 주문 가능했어요. 쫄깃하고 너무 맛있어요~~👍🏻', 15, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '부산에서 서울까지 이거 먹을려고 왔어요. 당고 완전 좋아해요! 일본에서 먹던 맛과 똑같애요~! 부산에도 있으면 좋겠어요! 잘 먹었어요!', 7, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '딸이 맛있다고 해서 함께 먹어봤어요. 로투스와 미타라시를 먹어봤는데 쫀득한 식감에 달달한 맛이 좋았어요. 소문만끔 맛있는 디저트네요.', 12, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '오픈 주방으로 앞에서 바로바로 만들어 주셔서 믿고먹을 수 있었고 토핑종류도 많아서 선택도 할 수 있고 보이는것보다 더 맛있었습니다.', 37, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '후기가 너무 좋아서 와봤는데 쫀득하고 맛있습니다. !! 일본 세븐일레븐 당고 좋아하셨으면 너무 좋아할것 같은 달달한 맛 당고맛이에요. 길거리 지나갈때 달달한거 땡기시면 하나씩 먹기 좋습니다.. 자주 올 거 같아요😳😳', 31, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '대기가 엄청 길어서 궁금해서 왔던 당고집이에요 평소 당고가 너무 달아서 취향이 아니였는데 여긴 매운맛도 있고 다양한 메뉴가 있어서 좋았어요! 사장님도 친절하셔서 더 좋았던 당고집이에요 추천합니당', 24, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '일본에서 먹던 당고랑 똑같은 맛이에요!!! 연남에서 당고를 먹을 수 있어서 행복합니다 ㅎㅎㅎ 잠깐 일본여행 다녀온 느낌이에요 💕', 112, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '오로지 이 당고 세가지맛을 먹기위해 홍대에 왔습니다. 먼길 올만하네요!! 가치있는 맛입니다. 그리고 김당고는 정말 일본 현지에서 먹던 당고보다도 맛있고 특별합니다ㅜ 강추에요. 홍대에 이거하나만 먹으러와도 될만큼이니 꼭 가세요! 앞으로 올때마다 가려고요~', 75, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '일본에서만 먹어봤던 당고! 여긴 특별한 당고가 있길래 지나가다가 먹어봤어요!! 특히 구운김 당고가 궁금해서 먹었는데 한국인 입맛 저격ㅠㅠ  맛도리이에요ㅎㅎ 맛디저트입니당ㅎㅎ', 30, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '일본에서 먹었던 당고 생각나서 들렸어요! 당고 종류도 다양하고 신기한 것도 있더라고요!(로투스..ㅋㅋㅋㅋ) 근데 맛있을 것 같아유 친구랑 와서 세개 주문!🐷', 107, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '날 더운데 불 앞에서 떡 구우시는 사장님 멋지십니다! 적게 일하고 많이 버세요 당고 일본에서 먹었을 땐 우엑이었는데 여긴 진짜 맛도리예요 일본 안 가도 됨🤭 아침에 손수 쩌내신다고 하샸는데 그래서 그른가 더 최고예여 우헤헤 맛있당', 14, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '겉은 쫀득쫀득~ 속은 말랑말랑~ 한입 베어 물었을 때 달콤한 간장 베이스의 미타라시 소스가 입안 가득 퍼지는데, 진짜 일본 전통의 그 맛을 꽤 잘 재현했더라고요', 25, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '진짜 너무너무 맛있어요 떡은 쫀득쫀득하면서 부드럽고 소스도 너무 대존맛이여서 걍 한입 컷 했어요!! 집에 와서 또 생각나는 맛이에요 앞으로 이거 먹으러 홍대 갈 것 같아요❤️', 47, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '당고는 처음 먹어보는데 너무너무 기대되고 실내가 없긴 하지만 앉아서 먹을만한 메뉴가 아니라서 야외만 있어도 충분한 것 같습니다! 인테리어도 근사하구 왕 기대되어요 ><', 32, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '일본에서 먹던 바로 그맛! 전 김맛 먹었는데 어리지널에 뿌려주는 인절미 가루 넘 맛있어보이더라고요🤤 김맛도 고소하니 맛있습니다!! 엄청 따끈 쫀득하고 이 소스가 킥이네요...🦶예전부터 오고싶어서 저장해놨는데 줄 길어서 못오다가 12시에 오니까 여유있게 바로 먹었습니다!', 25, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '당고 먹어보고 싶어서 방문했는데 당고 계속 구워서 만들고 계셨어요! 따끈따끈 해서 너무 맛있게 먹었습니다 여러가지 맛 먹어보고 싶어서 세가지 맛으로 주문했는데 너무 잘한거 같아요! 다음에는 못 먹어본 다른 맛 먹어 보고 싶네요', 277, 98, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '당고를 너무나도 죠아하는 나머지 인스타 보다가 찾아왔는뎅 여기는 광고할만하다고 느꼈어여 너무 맛있고 일본 현지에서 먹던 당고랑 똑같에여! 다음에 또 올께여 사장님!! 짱짱!', 9, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '일본 가서도 못 먹얶던 당고를 홍대에서 ㅠㅠㅠ 가게가 없어서 얼마나 헤맸는데 여기 생겨서 너무 좋아요 캐릭터도 귀엽고 맛있어요', 35, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '원래 당고를 좋아해서 일본에서도 많이 먹었는데 홍대에 이런 곳이 생겨서 너무 좋아요 ㅎㅎ 토요일에 금방 먹을수 있었고 지나가다 한번씩 들리는 거 추천드립니당', 8, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '동생한테 추천받아서 먹어보러 왔어요 ㅎㅎ 김당고 먹었는데 맛있어요 💗 담엔 그냥 일반 당고 먹으러 오려고요~~ 홍대 오시면 한번 먹어보세요 강추드립니다 👍✨✨ 혼자 오는것보단 둘이상 오는걸 추천드립니다ㅎㅎ 그럼 500원 저렴하게 먹을 수 있음', 2, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '일본에서 먹었는데 기대했던 맛이 아니라서 한번먹고 친구 다줬습니다. 일본여행가면  안사먹었는데.. 언니가 지나가는 길에 먹고싶다고 해서 보게되었어요. 떡을 당일생산하고 초당옥수수에 이끌여 주문하게 되었네요. 초당옥수수사려고했는데 이미품절이여서..  그건 포기하고 노리/키라이를 시켰습니다. 노리는 김을 바삭하게 구워서 그런지 멸치볶음 맛이납니다. 키라이(매운맛)  양념치킨 맛이예요. 언니가 너무 맛있다고 하네요. 떡을 좋아하시는분들 추천합니다.  떡이 쫀득하고 치즈같이 쭉 늘어납니다. 목적은 초당옥수수 였는데 30개 한정이라  못먹었네요.', 18, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '직원분도 너무 친절하시고 당고도 가성비 메뉴로 저렴히 먹을 수 있어서 너무 좋았습니다😚👍  당고 종류도 많고 주문 후 조리해주셔서 따뜻하고 쫀득한 상태로 먹을 수 있었습니다💕', 34, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '한국에서 당고를 먹을 수 있다니 너무 좋아요!! 웨이팅도 얼마 없고 음식도 넘 맛있습니다:) 커플세트 시키면 나눠먹기 좋아요!!!!', 90, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '친구가 먹어보고 추천해줘서 와봤어요. 가끔 품절 될때도 있다고 해서 전화하고 왔습니당 맛도 종류별로 시켜 먹어봤는데 넘 맛있어요 >< 재밌는 이벤트도 하니까 츄라이, 츄라이 🍡 🍡 냠', 30, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '연남 올 때 마다 먹는 당고에요 !!! 일본 자주 가는데 일본에서 꼭 당고 먹고 오거등요 ,, 근데 여기 찐이에욧 ~~ 무족건 드셔보시길 🍡🍡🍡', 98, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '오랜만에 방문한 한국에서 제가 제일 좋아하는 당고집이에요! 진짜 떡이 크고 쫀득하고 겉에는 토치로 구워서 살짝 바삭한게 좋아요 ㅎㅎ 그리고 소스도 가득해서 맛있어요! 노리당고를 제일 좋아하는데 오늘은 기본으로 미타라시 커플 세트로 먹었어요 ㅎㅎ 오랜만에 먹어도 맛있네요!!ㅎㅎ 사장님 계속계속 번창해주세요오오!!', 32, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '저번에 와서 기본 맛 먹고 반해서 또 왔는데 고민하다가 여러 종류를 주만해버렸네용 ㅎㅎ 너무 감동적인 맛이였습니다☆ 일본에서 먹은것보다 입맛에 잘맞아요!! 종종 간식으로 사러 와야겠어요>-<', 60, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '연남동 놀러왔다가 당고 맛난집 있대서 지나가다 테이크아웃했어요 너무 맛있네요 교토에서 먹었던 당고가 오랜만에 생각났어요 생각보다 따끈따끈하네요 전 기본 콩고물 묻힌거 먹었는데 잘먹었습니다 맛나요', 122, 26, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '오리지널 당고로 먹었는데 밤꿀맛 소스가 쫀득한 찹쌀에 곁들여지고 고소한 콩가루가 킥이 되서 너무 맛있었어요! 분위기도 너무 좋아요~꼭 한 번 와보시길 추천드립니다!', 88, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '당고가 너무 먹고싶었는데, 홍대에서 먹을 수 있어서 너무 좋아요!! 처음 방문해봤는데 가게도 너무 귀여워요!! 날이 덥기도하고 길거리에서 먹는게 불편하다고 생각했는데, 포장도 되어서 좋아요!!', 9, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '연남 주민으로써 집 옆에 이런 단골 집이 있어서 너무 행복해요. 생각 말 때마다 자주 오고 있어요. 앞으로도 번창 해 주세요. 저는 앞으로도 많이 먹어야 하니까요.👍', 74, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '연남동 오면 항상 먹는 디저트 중에 하나에여‘!!! 당고 넘 좋아하는데  넘 맛있어용!!!! 일본에서 먹은 당고랑 젤 비슷해서 좋아용!!!❤️❤️ + 이벤트도 진행 중이여서 더 재밌어용!!!!', 120, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '기본당고 이외에도 다양한 토핑이 올라간 당고가 많이 있었어요! 주문하면 앞에서 바로 구워주시는데 만들어지는거 보는 재미가 있었네요ㅎㅎ 당고 귀엽고 맛있었어요!', 27, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '떡이 커서 한끼로도 먹은적이 있다는ㅋㅋㅋ 기다림은 좀 감수해야하지만 평일 점심엔 괜찮아요! 초당이 시즌 한정으로 나왔네용🥰 가성비맛집입니다!', 78, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '홍대 올 때마다 꼭꼭 들려서 먹는 곳이에요!! ( •᷄⌓•᷅ ) ꖶዞ¿? 저희 동네에는 없는건지…ㅠㅠㅠㅠㅠㅠ 진짜 동네에 있었으면 하루에 기본 5개씩은 먹었을거에요ㅠㅠ 그정도로 너무너무 좋아하는 우마이 당고!! 강력추천합니다👍❣️❣️', 0, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '친구가 연남동에 유명한 당고맛집이 있다고해서 왔어요 아즈키당고랑 미타라시당고 시켰어오 너무 맛있어요!  연남동 올때 꼭들려보세요 아이들과함께 놀러오신분들도 같이잘먹더라구요!', 11, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '직접 구워주시는 당고가 일본에 온 느낌,,,,새로운 흑임자 메뉴도 있고 매운당고같은 신기한 메뉴도 있어서 다음에도 먹어볼려구요 사장님도 친절하시고 번창하세요✨✨', 57, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '맨날 짱구에 나오는 당고만 보다가 인스타에서 당고 카페가 있다는 말 듣고 방문했어요! 떡을 정말 좋아하는데 콩고물에 묻히면 얼마나 더 맛있게요,, 무엇보다 인테리어두 너무 귀여워서 만족스러웠어요❤️', 12, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '넘 먹어보고 싶었는데 드디어 먹게 됐어요!!! 넘 맛있어서 우마이당고에 있는 맛 다 먹어 보려구요ㅠㅠㅠ 연남 올 때마다 무조건 먹을 거예요!!!', 27, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '즐겨찾기해놨다가 먹으러 왔는데 재료를 아낌없이 넣어주세요👍🏻 노리당고는 김과 당고로 맛없을 수 없는 조합이고 갈릭바게트와 당고의 조합은 신선해서 재밌어요! 사장님도 친절하시던데 앞으로도 잘 되셔서 오래도록 장사해주셨으면 좋겠어요.', 59, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '두번째 방문한 당고 맛집!!! 생각날 만큼 너무 맛있고 지나가다 사먹기 딱 입니다 가성비 메뉴도 있어서 아주 좋고 바로 구워 주셔서 더욱더 맛있고 좋습니당 무조건 1인1당고 추천!! 둘이서 하나는 부족함돠…', 20, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '당고 진짜 좋아하는데 홍대근처와서 지나가다가 사람들 많길래 먹어봤는데 진짜맛있네요!! 종류도 너무 신기했어요! 일본에서도 못 본 느낌의 당고..🩷 맛있네용!', 42, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '떡을 즉석에서 바로 구워주시고 진짜 쫀득쫀득 너무 맛있어요,,,, 당고 원래 안좋아하는데 떡 자체가 너무 맛있어서  연남 올때마다 옵니다!! 꼭 드셔보세용~~', 20, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '소스가 진짜 감칠맛 미쳤네요 ㅠㅠ 떡이라서 그런지 배 안채워질 줄 알았는데 은근 배부르네요 ㅎㅎ 떡도 부드럽고 쫀득했어요. 미타라시 당고도 맛있어요 꼭 드셔보시길 ..ㅠ', 14, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '홍대오면 항상 먹어봐야지 하다가 줄이 길어서 못먹었는데 드디어 먹어봤어요!! 비쥬얼도 맛도 완전 일본 그 자체라서 너무너무 만족하고 먹었습니다!!', 21, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '떡이 완전 쫜득해요! 당일 생산해서 그런지 부드럽고 쫀득한 맛이 일품이네요😍 로투스로 먹었지만 많이 달지 않고 적당한 당이 당충전하기 아주딱이었어요! 담에 또 방문하겄습니당😉', 50, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '히힝 길 가는 길에 있길래 들렸는데 일본당고는 넘 짜고 달지만 여기는 뭔가 한국식으로 변형된 맛 ㅎㅎ 맛있게 잘 먹었습니다 ~~!🫧☁️🩵', 2, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '주문하면 바로 구워줘서 시간이 걸리긴 하지만 너무 좋아요! 평일 6시에 왔는데 웨이팅도 거의 없었어요! 더 빨리 오면 더 빨리 먹을 수 있을듯! 미리 구워서 양념 발라놓는게 아니라서 더 좋고 가게도 깔끔하고 맛도 여러 가지라 너무 좋아요! 세트 구성도 알차요!!', 12, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '연남동에 이색적인 당고집이 있아서 지나가다 하나씩 사먹기 너무 좋아요 맛도 다양하고 바로 앞에서 구워주시니까 구경하기도 좋습니다!! 완전 컨셉에 충실하게 신나는 일본 노래도 나오더라구요 연남 데이트 할때 또 올께요!!', 29, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '앉아서 먹을곳은 없지만!! 당고 맛집이라고 해서 찾아왔어요, 떡을 손수 쪄내신다니까 더 맛있을 것 같아요🥹 게다가 현백 팝업까지 하신다고•• 커피와 다른 음료들도 함께 저렴한 가격에 판매하고 있으니까 먹으면서 목 멕힐 일도 없어요!!!! 카페가면 6-7천원씩 하는 메론소다가 3500..!!!! 맛있게 먹구 다음에 또 올게요😉', 97, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '전에 지나가면서 먹어보고싶었는데 평일이라 한적해서 웨이팅 없이 바로 먹어보게 되었어요! 매장 깔끔하고 엄청 청결해요~일본 분위기 물씬!', 46, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '친한친구가 추천해서 왔어요!! 😊 건물도 이쁘구 분위기가 좋더라구요 ㅎㅎ 테이크 아웃이라 돌아다니면서 먹을수있어서 좋았어요 맛있기도하고.. 매운거라고해서 많이 매울줄알았는데 분식집 떡꼬치 느낌?! 이어서 좋았어요 ㅎㅎ 또 오겠습니다', 4, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '너무 와보고 싶엇던 우마이 당고!.!🤎 미타라시, 노리당고 두개 다 너무 맛잇오요 즉석에서 바로 구워주셔서 뜨근하게 즐길수잇어서 좋앗어요 >.<', 42, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '당고가 너무 먹고싶어서 찾아왔는데, 정말 쫀득하구- 말랑말랑하구- 맛이가 아주 좋아요- 합정쪽으로 놀러오면 꼭 다시 올거여요- 츄베르으으읍-!', 53, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '냄새도 군침돌고 먹기 전부터 너무너무 기대했어요 직접 불로 해주셔서 더 맛있던 거 같아욥 ㅎㅎ 으앙 쫀득쫀득 맛있어요 🤩🤤🤤🤤', 9, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '일본에서도 놔뒀던거 살짝 데워서 주던데 여긴 처음부터 구워서 주시네요 !!!! 일본에서 먹던맛 생각나서 왔는데 일봉에서 먹던맛이랑 똑같아요 !!', 56, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '일본에서만 먹던 당고를 홍대에서 볼 줄 몰랐어요ㅎㅎ 즉석으로 구워주는 당고는 처음인데 콩고물도 뿌려주고 신선하네요 다음에 또 들릴게요! 너무 쫀득따듯하고 맛있어요! 콩고물 별미입니다👍', 128, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '진짜 너무너무 와보고 싶었던 곳이에요 ㅠㅠㅠ 드디어 영접✨당고 진짜 너무 좋아하는데 잘 먹겠습니다.ᐟ 4개 드시고 싶으신 분들 커플3개 세트에 하나 추가하는 게 가격 더 싸니까 참고하세용🫶', 38, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '항상 줄이 길어서 못먹었는데 더운 날 한낮...  처음으로 줄이 없어 바로 주문했어요~ 친절하시고 설명도 잘해주셔서 감사했어요~''! 떡도 바로 구워주셔서 너무 좋았습니당♡', 43, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '3개 포장 주문했는데 3개맛이 뒤섞이지 않게 PP나 시트지 같은 거라도 덮이면 좋겠습니다ㅠ 뭐가 뭔 맛인지 너무 속상.. 팥은 호두가 토핑되어 갠취로는 별로였고, 기본 당고가 제일 맛있었습니다. 다음에 먹을 때는 기본만 먹을래요.', 110, 22, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '그동안 당고를 썩 맛있게 먹었던 기억이 없어서 크게 기대안했는데 진짜 대박맛있어서 깜짝놀람;;초당옥수수맛 6월에만 판매한다는데 진심 6월 안으로 꼭 먹어야함개미친맛', 25, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '미타라시 당고 달달하고 너무 맛있어요! 주문과 동시에 구워서 주시니까 퀄리티가 아주 좋습니다ㅎㅎ 한국에 당고 전문점이 많지 않은데 연남동에서 찾네용ㅜㅜ 그저 빛...⭐️', 20, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '우..우마이..!!! 진짜 닉값해요 너무 맛있어요 ㅠ 세상에 무슨일이야… 집 앞에 있었으면 사장님 옆에 세워두고 계속 먹었을 거 같아요. 달짝지근한 간장설탕 베이스 양념에 콩고물 조합 + 군침 도는 불향🔥 + 쫀득한 떡꼬치 = 극락열차 직행이요!', 0, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '비오는 날 더욱 운치있는 이 곳 , 안에서 먹을 공간이 없는 건 아쉽지만 이거대로 낭만적입니다. 아이가 가보고 싶다고 해서 나왔는데  생각보다 떡 크기에 놀라고, 너무 기대되는 맛입니다', 81, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '테이크 아웃 식당이라 따로 앉아서 먹을 장소는 없지만 길거리 음식 같은게 좋았어요. 주문 즉시 바로 구워주시는데 겉은 바삭하고 적당히 뜨거워서 바로 먹을 수 있었어요. 기본인 미타라시당고 먹었는데 달달한 간장 양념에 고소한 인절미 가루가 맛있어요. 주의할 점은 콩가루가 목에 걸릴 수 있으니 조심조심.', 37, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '당고 종류 되게 많아요 !!! 당고 진짜 좋아하는데 한국에도 당고 맛집 생겨서 좋습니다 ㅠㅜㅜ 홍대 오면 꼭 먹으러 올거에요 🥺', 38, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '연남동 우마이 당고 ! 한국에서 당고 사먹기 진짜 쉽지 않은데 연남동에 생겨서 너무 좋아요 ㅠ 다들 꼭 한번 씩 드셔보시길 !', 62, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '점심 먹고 나와서 걷다가 사람들이 모여있길래 눈길을 돌려봤는데 당고집이더라고요!? 이건 무조건 먹어야 해!! 하고 이끌리듯 왔는데 진짜진짜 대만족이에요..🥺 후회 없으니까 꼭 오세요!!! ❤️', 19, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '지나가면서 항상 궁금했었는데 이번에 드디어 갈릭바게트 먹어봤어용 갈릭바게트 가루 넘 맛있어용 다음에 다른 맛도 하나씩 다 먹어보고 싶어요 🫧🧡', 50, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '당고가 쫀득하고 따뜻하고 맛있습니다 지나가다 들렀어요 직화로 토치로 해서 겉에 구워주셔서 바삭하고 맛있어요 미타라시당고 기본 주문하면 콩가루도 같이 주시는데 엄청 맛있네요 추천드려요', 35, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '너무 맛있어서 홍대 올때마다 방문하는 곳입니다!! 비록 리뷰는 처음 써보지만 여기가 맛있다는건 확신할수있어요!! 직접 떡 구워주셔서 완전 맛도리!!', 7, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '근처에서 점심을 먹다가 우연히 발견했어요!✨ 예전부터 당고가 먹어보고싶었는데!!!🍡 테이크아웃을 전문으로 하는곳이지만 오히려 그게 더 매력있는 것 같아요~🍃🍀 첫시도(?)라 젤 기본맛으로 먹어봤는데 맛있어요!!!👍 담에 연남오게되면 또 먹어보려구요~☺️', 50, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '지나가는길에 줄랄라비~~~~ 서있는거 보고 기다렸다 먹었어요. 주문줄은 금방 줄고 받을때까지는 조금 시간이 걸렸고 세트는 할인되서 좋아요. 일본에서 먹던 맛 기대해봅니다! 리뷰이벤트도 있어요! 👍', 23, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '막내 동생이 홍대 가자고 노래 불러 들렸는데 당고를 먹어볼 수 있다니 - ! 🫧 엄청 더운 날 달달하게 당고로 당충전하기💗🍀 맛도 굿!!', 50, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '여기는 연남동 디저트 맛집 우마이당고^^돌아다니다가 생각 나서 또 왔음 근데 왠걸 한정메뉴가 있었네 근데 품절 ㅠㅠ 다음에 와서 꼭 먹어 봐야지!', 45, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '당고가 쫜득한게 맛있고 사장님도 되게 친절하세요! 한정메뉴가 있길래 먹고싶었는데 아쉽게 품절 ㅠㅠ 다음엔 한정메뉴 도전! 연남동 디저트로 강츄!', 89, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '주문하자마자 구워주셔서 따뜻하게 먹을 수 있지만 더운 날에는 조금 힘드실 수도 있어요!! 떡도 엄청 쫀득하고 콩고물 잔뜩 뿌려주십니다..😍', 18, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '당고를 바로 구워주시는데 냄새가 미쳤어욥,, 골목에 줄 서 있는게 보이신다면 바로 그 집입니다. 한번씩 드셔보시길 추천드려요!', 98, 26, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '연남동 데이트 필수 맛집인데 아직도 안 오신 분들 있으면 꼭 들러보세요!! 🍡 다른 당고집보다 훨씬 쫀득하고 부드럽고 쭉쭉 늘어나는게 당고를 먹는 건지 치즈를 먹는 건지 헷갈릴 정도;;👍 기본이랑 갈릭맛 시켰는데 천재같은 맛있어서 다음에 다른 맛들도 먹어보려구요!! 저 멀리 강동에서 왔는데 이제 우마이당고를 알아버린 이상 여긴 이제 제 나와바리입니다ㅠㅠ💚💚💚💚', 1, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '당고는 우마이당고에서 처음 접해보는데 완전 쫀득하고, 주문하면 바로 앞에서 구워주셔서 더 맛있는 것 같아요!! 나중에 또 오겠습니다! 우마이!!!', 22, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '여기가 맛집이라길래! 움움 데이트하러 온 김에 먹어봤어요~! 일본에서 기대하고 먹었던 당고는 별로.. 였는데 여기 당고는 진짜 한국인 입맛에 맞춰서 그런지 너무 맛있었어요🥹.. 헤헤 다음에 또 오겠습니다❤️', 27, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '일본감성 제대로❤️ 따로 앉아서 먹을순 없지만 이 나름대로 분위기있고 좋았습니당 당고 종류도 많도 음료도 있어서 더 좋았어요~!', 118, 24, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '우연히 만난 당고!!! 너무 먹어보고싶었는데 진짜 맛나용!!!!! 쫀득한 떡에 달콤한 조청 찍어먹는 느낌인데 진짜 맛있어용ㅋㅋㅋㅋㅋ!!!!', 10, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '저번달에 일본에가서 먹은 당고가 생각나서 사먹어봤는데 달달하구 맛있어요!! 데워서 주시는 게 아니라 바로 구워서 주시니까 따끈따끈하고 너무 맛있어용', 3, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '겉은 탱글하게 안쪽은 쫀득하게 씹히면서 부드럽게 넘어가는 식감이 너무 맛있네요 간장의 짭짤함같으면서 단맛이 좀 더 극대화되게 해주는 짠맛이라 너무 좋았습니다 딱 과일에 소금을 더하면 느껴지는 단맛의 느낌이었던것같아요 맛있게 잘먹었습니당ㅎㅎ', 7, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '당고 진짜 좋아하는데 한입 먹자마자 우마이 소리 나와요 떡도 직접 뽑으시는 것 같은데 쫄깃쫄깃하고 연남 오면 꼭 드셔보시길 추천!', 41, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '일본에서 먹던 당고가 생각나서 홍대 놀러온김에 들렸어요~~ 오리지널부터 이색당고까지!! 일본에서 맛본 그맛이라 순간 일본에 여행온줄 착각할거같아요~~~ 종종당고 생각날때 들려야겠어요! 우마이당고 당고맛집으로 인정!', 33, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '당고 먹어보고 싶었는데 지나가다가 자만추했습니다! 주문 즉시 구워주셔서 따끈따끈하고 맛있어요. 일본에서 먹어본 적은 없어서 비교가 어렵지만 충분히 맛있습니다!! 한 번 씩 지나가다가 드셔보세용', 64, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '종류가 다양해서 배만 안불렀음 하나씩 먹어봤을 것같네요 가게 이름처럼 우마이! 맛있습니다!! 일본에서 먹었을 때는 별로였는데 어찌 한국에서 먹는 게 더 맛있네요 ㅋㅋㅋㅋ 다음에 또 올 일이 있다면 지나가면서 먹을게용!🤭❤️', 80, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '길가다가 봤는데 일단 지나치다가 분위기가 진짜 일본같고 취향이라 끌리듯 멈춰섰던 것 같아요! 메뉴도 당고라서 주문해봤는데 가격도 합리적이고 가게에 계신 분들도 친절하셔서 마주침부터 주문, 갈때까지 기분 좋게 갈 수 있었던 것 같습니다! 다음에 홍대오면 다시 와볼 정도로 일본 감성을 홍대에서 느끼고 싶다면 여기가 진짜 좋은 것 같아요', 18, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '길가다가 줄 서 있는 사람들 많아서 멈쳤어요 대기 중인디 완전 기대 중! 우마이 당고 먹어봤다고 지인들한테 자랑할거에오!!.ᐟ.ᐟ 대기 최소 15분은 해야합니댜,,,😊', 34, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '당고를 주문과 동시에 구워주셔서 좋아요. 기다리면서 가게에서 나오는 일본 노래를 듣는데 인테리어도 그렇고 세미 일본여행같아서 재밌어요~', 37, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '당고 좋아하는 1인으로 완전 기대해서 왔어요. 눈으로 먼저 먹고 있어요. 맛은 기대이상이예요~~ 여기 올 일 있으면 꼭 들려서 먹을거예요. 콩고물한것도 안한것도 둘 다 맛있어요', 0, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '당고가 너무 맛있어요!! 일본에서는 기본 당고만 먹어봤는데 종류도 다양해서 맛있게 잘 먹었습니다 :) 연남동 오시는 분들은 꼭 드셔보세요!!', 41, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '저번엔 사람 많아서 못먹었는데 오늘은 적당해서 먹을 수 있었어요! 콩가루까지 뿌려져있고 점원분 너무 친절한데다가 너무 쫀득하고 맛있어요!', 53, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '당고집 지나가다가 궁금해서 시켜봤는데 키라이 당고라니 너무 신기하잖아요 바로 하나사서 친구랑 먹어볼게요ㅋㅋㅋㅋㅋㅋ 맛도 다양하고 가격도 괜찮아서 연남 올때마다 새로운 맛 도전해보고싶네요', 40, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '유명해서 당고 먹으러 평일에 와서 대기 없이 받을 수 있는 것도 너무 좋고 쫀득한 당고도 너무 맛있어요!! 사장님 친절하시고 이벤트 하는 것도 재밌어요', 11, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '줄서서먹는 당고 저도 드디어먹어봤습니다! 여기완전 일본이예요 ㅎㅎㅎㅎㅎ 오사카에서 맛있게 먹었던 당고랑 똑같고 더 맛있네요 ㅎㅎ 비주얼도 완젼 귀여워용ㅎㅎ', 46, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '지나갈때마다 너무 먹고싶었는데 먹게되어서 너무 좋아요!! 당고 먹기 어려운데 홍대에 딱 있어서 너무 행복합니다.. 자주 갈 예정이에요!', 23, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '밥 먹고 나오는 길에 당고집이 보여서 사먹었는데 바로 떡 구워서 만들어주셔서 좋았어요! 따끈한 당고는 처음인데 맛있어요! 미타라시 당고 꼭 드셔보세요 강추입니다!!', 2, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '당고 일본에서만 먹을수 있다고 생각했는데 연남동에서도 먹을수있는게 신기해요 키오스크로 주문하고 당고 만드는법 바로 볼수있어서 재미있었어요', 31, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '당고 처음 먹어봤는데 너무 따끈하구 쫄깃하구 맛있어용 ㅠㅠ 생각보다 빨리 나오고 맛도 다양해서 다음엔 다른 맛도 먹어보려구오~~', 462, 49, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '인스타에서 왕왕 유명한 당고집!! 넘 궁금해서 와봤는데 넘넘 맛있어요!! 쫄깃쫄깃 달콤한 당고맛최고! 맨날 짱구보면서 궁금했던거 소원성취했네용!! 다음에도 또 오겠습니당><', 37, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '홍대 나들이 왔다가 방문했습니다!!! 가게 지붕에 달린 풍경도 예쁘니 산책하다 눈에 자꾸만 들어와서 냉큼 사먹었어요 부담되지 않는 맛이라 간식으로 먹기 딱이네요 쫄깃쫄깃 당고 맛있게 잘 먹었습니다~', 54, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '달달한 게 땡겨서 들렀는데, 기대 이상으로 맛있었어요! 겉은 쫀득하고 속은 부드러운 당고가 진짜 매력적이에요. 특히 간장소스 당고는 짭짤하면서도 은근히 감칠맛이 돌아서 계속 손이 가더라고요.', 1, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '연남동 놀거리 찾아보다가 당고집이 있다는 사실에 바로 달려왔습니당 ㅎㅎ 로투스 당고나 한국인 입맛에 맞게끔 구운 김 당고 등 일본에서 맛볼 수 없는 메뉴들까지 있어서 너무 좋은 것 같아용 !! 당고넘넘넘 좋아하는데 일반 당고보다 더 떡이 쫀쫀하고 늘어나구요 !!!맛도 넘 맛있어서 담에 연남오면 또올게요 ♡', 48, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '당고 너무 좋아하는데 가까운 곳에 현지 맛과 똑같은 당고를 맛볼 수 있는 가게가 생겨서 넘 좋네요!! 기본맛들 다 너무 맛있어요! 다음은 새로운 맛도 도전해볼게요:)', 48, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '우마이당고 홍대점 리뷰 🍡 일본에서만 먹던 당고를 한국에서 먹어볼 수 있다니!! 웨이팅중인데 너무 맛있을거 같아 기대중이에요 ㅎㅎㅎ 저희가 시킨 메뉴는! 흑임자 당고! 7월 한정 메뉴래요!🫧', 78, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '항상 휴일에는 사람이 많아서 기다리는 시간이 좀 걸리지만 맛있어서 끊을 수 없어용 ㅜㅜ 갓구운 당고맛 너무너무 맛있구 연남올때마다 꼭 들리는 곳이에용♥️', 18, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '지나가다가 발견하고 저번부터 먹어보고 싶었는데 오늘 도전해봤어요!!! 너무 너무 바삭쫀득 맛있어요 주문 받자마자 바로 직접 구워주시고 토치질 해주셔서 그런지 따끈하고 맛있네용👍', 13, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '당고를 엄청 좋아하는 나와 친구🩷 무려 연남에 우마이당고가 생겼다고 추천받아서 방문! 사람은 많고 대기는 있지만, 음식은 빨리 나온다! 주문했는데 영수증이 안나와서 번호 헷깔려서 그 점은 아쉬웠어요~🥲 직원들은 친절하고 바빠서 이해합니다~ 카라이 당고는 매콤하니 맛있었고,  노리당고 기본소스에 김이 붙어 감칠맛이 나서 맛있었다~😋 떡이 쫀뜩쫀뜩해서 식감도 너무 좋고 양도 적당해요(가격대비) 먹고갈수있는 야외 인테리어도 일본풍이 나서 마음에 들었고, 귀여워요! 연남 당고 맛집 맞아요~ 재방문 할께요', 6, 1, 'GOOD', SYSTIMESTAMP);
