INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '길거리에 오랜만에 보는 당고 🍡 지나가다가 보이길래 바로 주문!! 감성 넘치고 귀여운 포장 디자인에 주시더라구용 맛도 너무 있었어여 가격도 괜찮고 강추추', 12, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '사장님께서 너무 친절하시고 당고가 너무 예쁩니다 T^T 여러가지 맛이 있고 포장도 친절하고 예쁘게 해주십니다! 지나가시다가 들려보시는거 추천드려요! 당고도 금방 나옵니다!', 56, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '매장이 작아서 잘 찾으셔야 해요. 주문하면 그때부터 당고 굽기 시작해서 시간은 조금 걸리지만 따뜻하고 쫄깃한 당고를 먹을 수 있습니다ㅎㅎ 기본 미타라시 당고부터 다른 곳에선 보지 못한 다양한 맛이 있어서 취향껏 골라먹을 수 있어 좋아요~ 다만 노리당고는 김에서 탄내가 좀 나고 소스가 제 취향은 아니었습니다... 떡은 쫄깃쫄깃해서 너무 맛있었어요.', 34, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '2번째 방문인데 올때마다 여긴 꼭 빼놓고 싶지 않고 코스에 필수로 넣어야 하는 맛집이에요~ 당고를 즉석에서 구워서 주시는데 쫀득하고 불맛나요~~!!🤤🥹 감사합니다~ 또 찾아 뵙겠습니다♡!', 2, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '지나가다가 우연히 보고 호기심에 먹어봤는데 당고 식감이 쫄깃하고 소스도 달짝지근하면서 인절미가루랑 잘어울리네요 ㅎㅎ 넘 맛잇게 먹어서 다음에도 재방문 할거에요!!', 49, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '당고 딘짜 좋아하는데 일본 못 가는 저한테는 진짜 최고의 곳이에요ㅜ 맛도 맛잇고 떡도 완전 쫄깃ㅜㅜ 우리 동네에도 있었르명 좋겟다ㅜ', 3, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '일본다녀온이후로 아른거리는 당고맛집이란맛집은 다찾아다니는거같은데요... 당일떡부터 아주 일본기억 새록새록하게하는곳이에요 추천드립미다', 19, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), 'This place is so delicious, I like ordering dango from here it is amazing', 37, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '떡이 단 1도 전혀 쫄깃하지 않아요 구워주시는 분은 되게 친절하세요 소스는 엄청 맛있네요 또 사먹는다면 소스맛땜에 사먹을 듯 합니다 떡이 쫄깃했다면 더 좋았을 거 같네용', 23, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '연남동 길가에 있는 당고집! 가게가 작아서 테이크아웃만 가능해요. 지나가다 사람들이 엄청나게 줄 서있길래 궁금해서 홀린듯 사먹어봤는데 넘 쫄깃하니 맛있네요🙂 가격은 좀 사악한듯 ㅠ 기본맛으로 먹었는데 로투스 가루 올라간거도 맛있을거 같아요~~', 32, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '너무 맛있어요... 불로 지져주세요... 짭짤할줄알앗는데 달아서 더 좋아용 근데 그렇게 단 건 또 아니고 그냥 모르겟어요 너무 맛잇어요', 10, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '떡이 말랑말랑하고 하나하나 구워주셔서, 불향도 은은하게 느껴집니다! 소스가 맛있고 떡이랑 잘 어울려용!! 직접 만든다는 말이 있어서 더 믿음직스럽네요! 다음에 또 방문하고싶은 집이에요!!', 70, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '맛있어서 순삭했어요/// 사진이 이것밖에 없어서 이거라도 올려봐요!! 맛있고 사장님도 친절하셔요! 뽑기이벤트?도 있어서 했는데 꼴등 없고 최소 일본간식 주셔요😋 강력추천!!!!!!!!!', 48, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '연남에 새로 생겼다는 당고집, 우마이당고💞 주문 즉시 앞에서 구워주셔서 구경도 할 수 있구 맛도 다양해서 골라먹는 즐거움까지 있는 우마이✨ 기본당고도 김당고도 짭잘하니 입에 촥 붙는 맛이에요! 진짜 우마이네영👏🏻👏🏻👏🏻', 25, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '또 또 온 우마이당고🍡🍡 여전히 사장님은 친절하시구 당고도 엄청 맛있어여ㅠㅠㅠ 이번엔 노리당고 먹었는데 노리당고도 맛있었숩니당!! 다음에 또 올게영', 9, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '동글동글 귀엽고 맛있어욤 🍡💞 메뉴가 더 다양해졌으면 좋겟어요 ㅎㅎ 친절하시고 노래도 그렇고 가게 분위기도 잠시나마 일본 여행 기분를 낼수있어서 좋았숩니당 👍🏻👍🏻', 20, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '일본에서 먹었던 당고 생각나서 들러봤는데 생각보다 웨이팅도 적고 방금 막 나와서 엄청 따뜻하구 맛있어요❤️ 생각보다 덜 짜서 더 맛있어용', 62, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '겉바속쫀이에요! 당고 좋아해서 찾아왔는데 배부른 상태에서 먹었는데도 너무 맛있어요! 사람들 많았는데도 빨리나오고 좋아요! 팥은 너무 안달고 쫀득쫀득 맛있어요~', 17, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '서울 당고는 여기로 정착했어요! 근데 길가면서 먹을거면 콩고물은 비추천.. 폰, 옷, 신발, 바닥 등 난리납니다.. 근데 있어야 더 맛있긴 합니다.. 그래서 전 그냥 흙 맞은척하고 먹어요', 57, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '항상 사람이 많아서 언젠가는 먹지않을까 생각했는데 그날이 오늘이네요 힘든 날에 먹고싶었던 당고 먹어서 기분 좋아졌어요! 주문 들어오자마자 바로 맛있게 구어주십니다👍 달달고소쫀득 맛있어요👍 콩가루까지 달아서 진짜 어어어엄~청 매우 달아요👍', 43, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '주문 즉시 손수 쪄낸 직접 꾸워주시는 당고🍡 너무 맛있어용 3개해서 나눠먹는게 최고:) 로투스/아즈키(팥)/미타라시(기본) 최고😍', 7, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '디저트로 근처 당고집에 들렀습니다. 가게는 작지만 아기자기하고 일본 느낌이 나는 분위기라, 들어서는 순간 여행 온 기분이었어요.', 30, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '떡순이 둘이 방문했습니다! 인스타에서 볼때마다 궁금했는데 드디어 와봤네용 ㅎㅎ 떡도 쫀득하고 메뉴도 은근 다양햐서 좋아요 일본놀러가서 먹었던 당고가 생각나네용ㅎㅎ 그리우신 분들은 꼭 방문해서 드셔보세욥〰️〰️', 18, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '당고 처음 먹어보는데 진짜 맛있어요.... 떡이 완전 쪼오오올깃 치즈처럼 쭉쭉 늘어나는데 부드러워요 소스도 달콤하고 콩가루도 고소해서 넘 맛있게 먹어써요', 11, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '평소 당고좋아하는데 맛있게 파는 곳 이 없어서 너무 아쉬웠는데 여기는 진짜 이미 생긴거부터가 맛있어보이고 맛도 역시 맛있어요! 진짜 또 오고싶어요 🫶🏻 꼭 한번씩 다들 드셔봤으면 좋겠습니당', 66, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '홍대 ‘우마이당고’🍡 남자친구랑 홍대 올때마다 먹고가는 당고집이에요! 진짜 노리가 진짜 미첫어요!! 달달하고 찹잘한 맛이 증말 이건 바빠도 하나는 먹고가요!!!! 보이시면 꼭 한번 방문해보시면 실망하지 않아요!!', 2, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '홍대 갈 때마다 들리는 곳이예요!! 당고를 파는 곳이 없어서 너무 소중한 곳입니다~저의 또또또간집고요 카라이 당고 꼭 드세요💖🥹💖💞', 7, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '일본에서 먹었던 당고맛!!! 너무그리웠는데 이렇게 맛볼수있어서 너무좋았습니다 ㅠㅠ 노리당고 강추강추! 다음에 또먹으러올께요!!', 45, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '일본에서 당고먹고 너무 먹고싶어서 찾아왔는데 그 맛 그대로예요 ㅎㅎ 연남동 놀러와서 사먹기 딱 좋습니다 가격도 적당하고 강추입니당!', 12, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '길 가다가 사람들이 줄 서있길래 방문! 당고맛 종류가 꽤 돼서 골라먹는 재미가 있을듯 합니다 저는 김맛을 먹었는데 막나온건 엄청 뜨거웠습니다ㅋㅋ 소스가 잘 배서 맛있었어요', 11, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '직접 구워주는 당고에 토핑과 함께 얌냠 먹으면 얼마나 맛있게요 ㅠㅠㅠ 일본여행가서 당고 못 먹고 온게 너무 슬펐는데 여기서 먹고 너무 행복해졌어요 6월 한정메뉴 옥수수맛 꼭 드셔요크으', 36, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '친구가 맛있는 당고집이 있다고 해서 함께 방문했어요!! 6월 한정 메뉴라는 초당옥수수 당고 먹어봤는데, 맛있었습니다🥹 다들 드셔보시길!!', 14, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '미타라시 당고 3,500원 사실...저 당고 처음 먹어보그등용... 근데 소스와 저저 콩가루 조합 미쳐떠여!! 리뷰이벤트로 따순 아메리카노까지..❤ 당고 쫀득쫀득 이런 집이 있다니!!!! 가격도 착하고 따순 녹차까지! 친절하고 분위기 미쳤어용!!! 주문하자마자 구워주셔서 넘 좋아용! 토치까지 정성 담으시니 맛없없이쥬?!?!!! 당고 최공!🥰🍡', 65, 17, 'GOOD', SYSTIMESTAMP);
