INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '사자마자 화로에 올려줘요! 바로 나오는게 아니여서 따끈하게 먹을 수 있었어요 날씨 좋은날 길떡(?)하기 조아요 완전 쫀~득한 구운가래떡에 당고소스까지 맛있더요ㅠㅠㅠ🩷🩷', 25, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '당고 처음먹어보는데 정말맛있어요!! 지나가다가 일본느낌에 퐁당 쫀득 달콤 한번빠져보시겠습니까😆😆😆😆😆 경기도 안조은데 가볍게 일본여행하세용~~❤️ 데이트땨 또오료규요! 맛잇어용😁😁', 35, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '인스타에 뜨고 너무 와 보고 싶었는데 드디어 왔네요!!! 사장님도 친절하시고 직접 구운 당고 먹을 수 있어서 너무 좋아요 :) 자주 올게요!!!🍀🥹💖', 33, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '지나가다가 우연히 발견했는데 사람이 끊임없더라고요! 일본에서 먹어봤던 당고가 생각나서 먹어봤는데 제대로 하시는 곳 같아요ㅎㅎ 맛있게 잘먹었습니다~ 다음에는 다른 맛도 도전해볼께요!', 35, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '드디어 와봤다 우마이 당고! 당고 진짜 좋아하는데! 진짜 매장도 깔끔하고 너무 먹음직스러워보여요! 포장용이라 당장은 못먹지만! 그래도 헤헤 잘먹겠습니다!', 36, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '자리에서 바로 구워주시고 떡을 당일 아침부터 매시간 쪄내신다고 해서 더 먹고 싶게 되어 방문했는데 기대했던대로 너무 너무 맛있았아요!̆̈!̆̈ 다음에 또 방문하겠급니당!!', 21, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '지나가는 길에 발견한 우마이 당고 평일 낮인데도 사람들이 많았고 직원분은 너무 친절하셨고 일본 느낌나는 가게에 후우링도 달려 바람 불때마다 청량한 소리가 들려서 좋았고 계속 일본곡 틀어주셔서 마치 일본에 온것만 같았어요:)', 7, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '당고를 먹고 싶어서 방문했습니다~~!! 세트메뉴도 다양하고 주문하자마자 즉석으로 조리해주셔서 맛있게 먹을 수 있습니당!! 당고 드시고 싶으시면 방문이에요!!', 0, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '저번주에 처음 사먹고 이번주에 와어 미타라시당고 벌크에 흑임자당고도 사갑니다 너무 쫄깃하고 맛나요!!! 오래오래 장사해주세요😁😆💜', 0, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '당고!!!! 일본여행때 많이먹구 우리나라에서도 먹고싶어서 홍대찾아왔어용!!! 미타라시 당고 카라이 당고 노리 당고 강추ㅠㅠㅠ!!!맛집이에용', 66, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '일본에서 당고 먹구 한국에서도 먹고 싶어서 찾다가 방문했는데 쫀득하고 너무 맛있어요 ㅜㅜ 일본 안가도 되겠어요..^^ 앞으로 당고 먹고 싶을땨 자주 방문 할 것 같아요~~~🍡🍡🍡', 86, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '인생 당고 드디어 찾았어요...🥹🍡 바로 옆쪽 골목에서 먹고 너무 맛있어서 가게로 쓰레기 버리러 가는 김에 사장님한테 쌍따봉 날려드리려고 했는데 안쪽에 계신지 안보이셔서 아쉬웠어요 진짜 너무너무 최고로 맛있었어요 한달에 한번은 연남동 가는데 갈때마다 당고 먹으러 갈거예요🤍', 31, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '당고가 먹고 싶어서 찾다가 방문했는데 주문하는 즉시 만들어주셔서 따끈따끈하고 맛있어요!!!! 외관도 예쁘고 포장도 엄청 깔끔합니다 ㅎㅎㅎ', 118, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '지나가다가 딸랑거리는 소리에 봤는데 당고집이더라구요! 냄새도 고소해서 기다리는데 군침이 ..🤩 쫀득하고 엄청 맛있어요!! 연남동 가시면 꼭 가보세용!', 6, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '당고 맛도리!! 쫀득쫀득 좋네용 카라이는 떡꼬치느낌나구! 노리는 짭조름하니 맛있어요 ㅎㅎ 지나가다가 들려서 냠냠하면서 돌아다니기 좋네용 ㅎㅎ 굽는데 한 3분? 정도 걸리는거같아요', 460, 87, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '지나가다가 항상 먹어보고싶었는데 드디어 먹어봐요!! 남자친구도 엄청 맛있게 먹어서 다음에 또 올려규요 ㅎㅎ 떡이 쫀득쫀득하고 맛있어용☺️❤️', 1, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '떡순이 절대 못 지나지츄~~~ 3개 세트 8900원 할인가 넘 좋아요!! 직화로 구워주는 쫀득한 당고 최고ㅜㅜ 무조건 3개 세트로♡♡♡ 홍대 지나갈때 필수로 들려야하는 우마이당고 밥 먹기 전에 일요일 5시쯤 지나가니 줄이 넘 긴거에요 밥먹는 동안 내내 당고 생각하다가 왔어요 ㅋㅋㅋ 6시30분에 운좋게 대기 5번 정도 기다리다가 받았어요!!!', 118, 24, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '저번에 먹고 너무 맛있어서 다시 방문했어요! 당고집 중에 가장 맛있는 것 같아요 한 번 먹으면 계속 생각나는 맛 추천합니다! 재미있는 이벤트도 있더라구요🤭', 117, 24, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '당고를 저렴한 가격에 먹을 수 있어서 너무 좋아요 ㅠㅠ 가게도 일본풍으로 귀엽고 좋아요! 연남 올 때마다 자주 사먹을 것 같아요!', 26, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '솔직히, "그냥 당고겠지~" 하고 기대 안 했는데, 한 입 먹는 순간 바로 생각 바뀜. 겉은 살짝 구워져서 은은한 불향 나고, 안은 쫀득쫀득 부드럽게 넘어가는데 달콤 짭짤한 소스가 진짜 핵심임. 단맛이 막 끈적한 게 아니라 깔끔하게 퍼지는 느낌? 크기도 딱 적당해서 "아 하나만 더 먹을까..." 하는 마음 자동으로 들고, 녹차나 커피랑 같이 먹으면 입 안이 진짜 깔끔해져서 기분 좋아짐. 요약하면, "심플한데 미친 듯이 손 가는 맛." 가벼운 간식 찾고 있으면 무조건 추천. 별거 아닌 것 같은데 먹다 보면 은근 계속 생각나는 그런 간식임.', 29, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '연남동 산책하다가 우연히 발견한 일본풍 당고 맛집, 우마이당고! 겉보기엔 작고 소박한 가게지만, 지나가는 사람들 손마다 당고가 하나씩 들려있더라고요. 안 먹고 지나갈 수 없었어요.', 0, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '인스타에서 보고 맛있어보여서 가야지하며 생각해놨던 곳인데 홍대에 자주 못갔고  겨울이어서 춥다보니 봄에 찾아가야지 하던  가게였어요. 워낙에 맛있게 보여서 당고 먹어본 적 있지만 그닥 선호하지 않고 예전에 먹어본 당고는 작고 맛이 애매해서 먹고 실망했는데  우마이당고는 떡이 토실토실? 하고 부드럽게 녹아버려서 입안에  붙지 않고 넘어가면서 맛도 달콤하니 간장 베이스랑  너무 맛있어서 엄지척 하는 🍡  당고^^ 라서 홍대 오시면 한번 드셔보길 추천 해요. 지도 보고도 홍대에서  길 헤매는  저도 무작정 길따라 가다보면  있겠지 하고;;  와서  먹어본 당고 맛집, 따뜻한 봄에 당고 드시러 오면  최고일 듯이네요 ^^', 17, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '매장에 사람도 많고 당고가 먹고 싶어서 방문했습니다! 미타라시 당고 주문했고 간장소스가 정말 맛있어요!! 떡도 쫀득하고 모찌처럼 잘 늘어났어요🍡 일본노래도 나와서 분위기가 좋아요👍', 7, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '우마이당고 진짜 맛있네요~ 처음 지나갈땐 줄 길던데, 다음에 마침 아무도 없길래 사먹었어요. 바로 대기 생기네요ㅋㅋ 소스도 적당히 단짠이라 맛있고, 떡도 부드럽고 최고에요❤️', 23, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '당고 너무 귀엽고 먹고 싶은 종류들이 많아요 일본에서 먹었을 때보다 선택할 수 있는 폭이 많아서 친구가 오자고 말하자마자 바로 고고 햇어요', 14, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '일본 여행 가서도 못먹어본 당고를 한국에서 먹어볼 수 있어서 너무 좋었어요. 일본에서 당고를 못 먹어봐서 비교는 불가능 하지만.. 맛있었습니다!!', 14, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '아이가 티비에서 보고 먹어보고싶어 했는데, 연남동 놀러왔다가 발견해서 엄청 반가웠어요~ 아기지기 인테리어가 너무 이쁘고, 일본 감성도 나고 좋아요~ 특히 창문 사이로 실제 당고 굽고 계시는 모습도 인상적이었어요. 엄청 정성들여 만들고 계시더라구요. 더운데 좋은 음식 만들어 셔서 너무 감사합니다. 일단 가장 기본 맛으로 도전했는데 엄청 맛있어요. 담에 또 올게요~~', 51, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '지나가다 우연히 봤는데 교토에서 먹었던 당고 생각나서 바로 사먹었어요~!! 옆에 도리이도 너무 귀여워서 예쁘게 사진찍고 당충전하기 최고예요~ 맛도 교토에서 먹었던 딱 그맛인데 콩가루 뿌려져서 전 더 취향이었어요~ 😍', 29, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '저는 당고에 진심이라 교토 여행 가서도 몇 시간을 걸어 100년 넘은 당고집을 찾아 가기도 했는데요 이런 맛을 한국에서 즐길 수 있다니 굉장히 기쁩니다! 떡도 그 자리에서 익혀주셔서 매우 쫄깃합니다! 녹차도 제공되는데 문구도 다정하고 응대도 친절하셔서 기분 좋은 하루 보낼 것 같아요~ 감사합니다 오래오래 잘 되길 바랍니다!', 13, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '일본에서 먹고난 뒤 그리워하다가 당고맛집있다하서 홍대까지 달려왔슴당 친구랑 둘이 순위 정했어요 1위 기본 미타라시 (+콩고물) 2위 아즈키 3위 카라이(떡꼬치 진화된맞) 4위 노리 하지만 다 종류별로 꼭 먹어보는거 추천👍', 3, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '당고 맛있다고 유명해서 인천에서 왔어요!!!! 먹어보니 일본 여행 때 먹은 당고가 생각나네요…당고 먹으러 일본 가고 싶으신 분들…비행기표 아껴서 여기 오세요🍡', 97, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '미로길에 위치한 우마이당고입니다. 일본간식인 당고를 판매하고 있습니다. 키오스크로 주문을하면 당고를 굽고 토치를 한후 소스를 올려주십니다. 여러종류의 당고가 있으니 취향따라 골라먹기 좋습니다. 호기심에 먹어보았는데 길에서 간식으로 먹기 괜찮습니다.', 13, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '미타라시 당고가 너무 먹고싶어서 찾아보다가 오게되었어요!! 사장님도 너무 친절하시고 커플세트로 먹으니까 할인도 되어서 너무너무 좋아요 ㅎㅎ 너무너무 맛있게 잘먹어서 홍대 올때마다 들릴거같아요😻😻', 19, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '카라이당고 시켜서 먹었는데 너무 맛있어요! 일본에서 먹은 것보다 더 맛있고 노래도 완전 취향저격이에요! 가게 분위기도 너무 좋아요!', 18, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '흑임자 당고가 있었으면 좋겠다고 생각하던 중에 마침 7월 한정메뉴로 팔고 있었다..! 직접 정성껏 구워주셔서 쫄깃하고 맛나다😁👍', 29, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '저는 노리 김 맛이 젤 맛있어요! 저희 집 근처에도 있었음 좋겠습니다 🤤 다른 당고보다 확실히 신경써서 만드신게 티가 납니다.. 일본에 온 것 같은 분위기도 분위기지만 사실... 진짜 당고자체가 쫀득쫀득하고 소스가 완벽합니다.. 너무 달지도 짜지도 않는 완벽 비율의 단짠맛이랄까 ... 홍대올때마다 꼭 가서 먹고 옵니당.. 사장님들과 직원분들도 꼼꼼히 만들어주시고 친절하세요! 여기 당고 먹어보면 다른거 못먹을걸요 ㅎㅎ 본토의 맛 한번 아니고 두번 드셔보세요 ... 찐이양 ..', 128, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '일본에서 먹었던 당고 맛을 찾아서 한국 당고매장 찾아서 많이 가봤지만 여기만큼 찐만족하는 당고집은 없었어요🍡🤍 당고에 진심인 우마이당고!!! 맛있어요!!!  ♡･ᴗ･♡ 이거먹으러 서울까지 갑니당!.. 미타라시 당고가 메인이니 꼭 드셔보시고 개인적으로 팥당고도 맛있었어요!! 팥이 그림보다 많아서 깜짝놀랐어요 (너무 맛있음..!) (+ 우마이당고 캐릭터도 너무 귀여워서 저번에도 이번에도 포장하며 받아온 종이가방들 집에 모아두는중...🌈💝)', 1, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '수제당고 유명해서 먹으러왔어요. 뜨뜻하고 바삭 쫀득한데 일본에서 먹었던 당고 느낌은 아니고 맛있게 잘 구운 떡같아요..! 커피나 차랑 먹으면 맛있을거같아요 콩가루 많이 떨어지니 조심 !!', 62, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '떡이 엄청 부드러워요! 피자치즈같이 쭈욱 늘어나는 말캉한 떡이에요 쪼오오오오온득해요 직접 만든 떡이라 그런지 식감이 부드럽고 맛있고 콩고물도 고소하고 너무 맛있어요 달달하고 부드러워서 혼자서 두개 먹을 수 있을 것 같아요🥹 쫄깃한 떡 구이 생각한다면 아쉬울 수 있어요,, 부드러운 사르르한 떡을 생각한다면 먹어보길 추천해요👍🏻 ⚠️ 입에 들러 붙는거 안 좋아하면 당고와 안 맞을 수 있어요', 21, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '전에 방문했을때 맛있어서 기억에 남았었는데 오늘 남자친구하고 지나가다가 보아서 오랜만에 먹어봤어요! 맛있고 사장님도 친절하셔요!', 49, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '당고는 먹어본적이 없어서 생소했는데 너무너무 맛있어보이고 사진도 이쁘게 잘 나왔어요!  지나가다 한번씩 츄라이 해보는것도 나쁘지 않을거같아요!', 11, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '달달한 간장소스랑 김이 잘 어우러져서 너무 맛있어요👍👍금방 구워져서 나와서 그런지 떡도 쫄깃하고 따듯하고 맛있네용 다른 메뉴도 많던데 다음에는 다른맛도 꼭 먹어봐야겠어요🥹', 20, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '사람들 완전 바글거려요! 3개 세트 가성비 괜찮았구 당고 맛있어요!! 기본, 매운맛, 로투스 먹어봤는데 다 맛나구 담엔 다른 맛 먹어볼게용', 76, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '보기드문 일본식 당고집이라 신기했어요! 당고 종류가 6개라 올때마다 하나씩 시도해보는 재미가 있을거 같아요 시그니처인 미타라시 당고 시켰는데 떡이 쫄깃하고 소스랑 콩고물이 잘어울려요 포토존도 있어서 데이트 때 들르기 좋아요~', 35, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '일본에서 너무 맛있게 먹었던 당고, 한국에서도 가끔씩 생각났었는데 이렇게 집근처 연남동에 딱!! 앞으로도 오고가며 자주 찾을것 같습니다😊', 2, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '당고 진짜 좋아하는데 쫀득쫀득하고 맛있는거 같아요!! 기본에 콩고물 들어있는게 제일 베스트인거 같습니다!! 너무 맛있게 먹고 갑니당🩷', 82, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '연남동길에서 당고가게를 만나서 엄청 반가웠어요 !! 당고 종류가 굉장히 많고, 특히 기본 미타라시 당고에 콩가루 조합이 소스만 먹어도 정말 맛있었어요 !! 🍡🍡', 43, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '연남동에 당고집이 생겨서 와봤어요! 미타라시 당고 먹어봤는데 일본에서 먹은거랑 맛이 비슷하고 떡이 따뜻해서 좋아요~~인절미가루도 뿌려줘서 두배로 맛있어요~!', 28, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '우마이!!!!!!~ 정말 이름처럼 너무 맛있는 곳이에요 일본여행 다녀오고 당고가 너무 그리웠는데ㅠㅠ 홍대에 우마이가 있는 덕분에 행복해요💗💗', 48, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '저번에 노리 당고, 갈릭바게트 당고, 로투스 당고 이렇게 3개 먹었는데 너무 맛있어서 오늘은 미타라시 당고랑 노리 당고 먹으러 왔습니다! 여전히 맛있고 인기가 많네요~ 다음에도 또 먹으러 와야지', 21, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '닌텐도 스위치가 받고 싶어서 음식이 나오지도 않았는데 급하게 올려봅니다 안먹어봐도 맛있겠쥬!!!♡♡♡  지금 군침 흘리고 있습니다 충성!!!', 17, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '우마이 당고 !! 처음 먹어봐요!!! 떡이 쫄깃해요 애니매이션에서 보던거 !!! 신기했어요 바로 구워줘서 따뜻해!!!! 달디달디단 떡꼬치느낌이에용😗', 33, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '주문하면 떡을 굽기 시작해서 시간은 조금 걸리지만 그만큼 맛있습니다ㅎㅎ 맛도 다양하고 다른 당고 가게에선 보기 어려운 맛들이 있어요~ 들고 다니면서 먹기도 적당하고 아니면 가게 옆에 서서 먹고 가도 돼요~', 25, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '외관이 너무 귀여워서 걸어가다가 돌아보게 되는 곳인것 같아요! 루토스 당고도 너무 맛있고 좋았어요 👍✨️✨️ 직원분도 친절하시고 너무 좋아요!', 89, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '연남동 맛골목 디저트 가게 같은데 줄이 잔뜩 서있어서 궁금함에 봤더니 당고네요! 마침 식사후라 하나 입가심으로 먹었어요. 바로 구워줘서 더 맛날거 같아요 :)', 20, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '당고는 당연히 맛있엇고 갓구워주셔서 그런지 따근따끈해서 더 맛있었어요!! 사장님도 넘 친절하셔서 연남올때마다 방문할 것 같아요🫰🫰🫰', 10, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '당고도 맛있고 분위기도 너무 좋아서 이색적인 경험을 해보기에 너무 좋았어요!💖 친구나 연인이랑 같이 들러보는 것도 좋을 것 같습니당!', 9, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '이제 10번째 오는건데 늘 맛있고 하나하나 정성스럽게 당고를 만들어주셔서 더운날에도 찾게 되는것 같아요. 사장님도 친절하시고 정말 맛있어요. 한번 꼭 드셨으면 좋겠어요!!', 379, 88, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '미로 길 구경하다가 너무 맛있어 보여서 주문했습니다. 음식 기다리면서 많은 분들이 주문하시는 거 보니 맛집인 것 같아요. 당일 아침 만든 떡이라 그런지 쫀득쫀득 맛있습니다👍', 31, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '원래 영수증도 안뽑았는데 넘 맛있어서 자발적 리뷰를 써봅니다.;;; 팀원분들이랑 근처에서 포케먹고 한번 사먹어봤는데 진 짜 맛있어요 -_-;; 당고를 원래 싫어하시면 어쩔수없지만 달달고소키리모찌떡 좋아하시면 무조건 추천임 ㅠ 저 기본맛... 콩고물+꿀에 쭈욱 늘어나는 따뜻한 당고 진짜 짱맛이에여ㅠㅠ 입에서 떡이 녹아요ㅜ 막 머리아프게 달지도 않았고 딱 그냥 너무 맛있는 맛!! 따뜻해서 더 맛있는듯요 콩고물 흐르는거 좀 조심해야하지만 진짜 맛있게먹었어요 ㅠㅠ (커플세트 가격도 착함! 다만 떡 굽는시간 좀 기달려야함) 그리고 의외의 수확>> 아아가 1900원인데 진짜 맛있습니다..!!! 저희회사 근처 3~5000원에 파는 카페들만큼 맛있어요 다같이 커피괜찮다며 완전감탄. 완전 행복한 점심 후식이었습니당! 추천', 33, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '일본 전통 간식인 당고 전문점이 연남동에?!?? 당일 새벽부터 찌기에 쫄듯쫀득한 우마이당고 🍡 일본에서 맛본 소스와 정말 비슷해서 놀랐어요! 우마이당고로 일본 대리만족 ㅎㅎ 연남동에서 밥먹고 디저트로 너무 좋았어요 일본 분위기 그대로 느낄 수 있는 인테리어뿐 아니라 사장님까지 친절하셨던 ,, 연남동 간식 우마이당고 추천합니다~~! 😻', 14, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '당고 너무 좋아하는데 종류도 많고 바로 사서 바로 먹을수 있는점이 너무 좋구 사장님이 친절하십니당 맛은 말해뭐해 최고구요 길가다가 출출할때 들려서 한번 먹어보세욤 더운날 먹는 당고 쥰맛탱구립니당', 57, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '사장님 진짜 친절하시고 당고도 일본에서 먹던맛 똑같아요! 불에 직접 구워주시는데 구경하고 있으면 시간 잘가요 일본 당고 좋아하시면 꼭 가보세요 맛있어요~', 28, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '오리지널 당고가 진짜 맛있고 그 다음 로투스 추천... 이거 먹으러 인천에서 서울까지 왔어요 🥲🥲🥲 사장님도 친절하시고 가성비도 좋습니다...', 14, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '일본에서 당고 먹고 아쉬웠던 적이있는데, 여기선 떡도 엄청 쫄깃하고 맛있었어요 시간은 좀 걸린 편이지만 충분히 기다릴만한 줄!', 28, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '전에도 한번 먹어봤는데 너무 맛있어서 다른 친구랑 또 왔어요!!! 다른 가봤던 당고집들은 이렇게 철판에 바로 구워주시진 않았는데 주문 직후 바로 구워주셔서 너무 맛있습니다! 지금은 여름에 먹지만 겨울에 먹으면 최고일 듯..', 77, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '미타라시 커플 세트 5,900원 여기 당고 진짜 왤케 맛있어용!!! 쫀득쫀득 미쳐써여!!🥰 1인 1당고는 기본이예용! 친절하시구 토치로 구워주셔서 불향까지 나용! 꺄 당고먹으러 또 갈거예용!🍡', 5, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '기다리구 먹은 당고 ㅠㅠ 너무너무너무 맛나요 🤎🤎 연남오시면 꼭 드시고 가시길 추천합니당 ✨ 귀여운 인증샷도 찍어보세요 ~!~!', 12, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '자주 들리는 곳인데 오늘 처음으로 리뷰 쓰네요 여기 정말 맛있습니다 사람들 주사 한데 오늘은 줄이 많이 없어서 한 번에 먹을 수 있었습니다. 또 들릴께요.🩵', 19, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '일본에서 당고를 너무 맛있게 먹어서 그리웠던 참에 홍대에도 있다고 하여 왔습니다! 너무 쫀득하고 맛있고 콩고물이랑 같이 먹으면 너무 잘어울려요 ㅎㅎ 커피도 저렴해요', 12, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '여자친구랑 지나가다가 들렀는데 아니 세상에 오사카에서 먹던 당고는 당고도 아니였어요 너무맛있어서 나중에 또 오려구요 잘먹고갑니당😛', 82, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '완전 맛도리 당고!! 종류도 다양하고 바로바로 구워주셔서 출출할 때 간식으로 먹기 완전 딱~~~ 입니다 연남 당고 맛집 찾는다면 완전 강추강추!! 🤍🩵😉', 48, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '주문하면 바로 직접구워주시고 매장앞에서있으면 일본와있는기분! 일본에서먹은것보다 마시쯤.. 커피도 산미별로없는 한국인이좋아할맛이네용!!!!', 0, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '길거리 다니다 노랫소리에 끌려서 왔는데 너무 귀여운 당고집 발견!!!! 컨셉이 너무 귀여워요🥹 오랜만에 쫀득당고 맛있게 먹고 갑니당!', 73, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '두번째 방문이네요 !! 일본에서 당고 먹고 한국에서 계속 찾고 있었는데 연남동 핫플로 떠오르는 것 같아 좋아요 ㅎㅎ 🌼 꼭 가보세요 추천 👍🏻👍🏻', 79, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '당고 처음 먹어보는데 진짜 너무 맛있어요!!!!!! 엄청 쫄깃쫄깃하고 쭈욱 늘어나요! 줄 많은 거 인정! 다음에 또 먹고 싶어요', 65, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '일본에서 먹었던 당고가 생각이 나서 먹었는데 맛있었어요! 소스도 달콤하고 짭조름해서 맛있고 떡도 부드럽고 쫄깃했습니다☺️ 한쪽에 녹차가 따뜻하게 있어서 기다리면서 마실 수 있어서 좋았습니다❤️', 48, 0, 'GOOD', SYSTIMESTAMP);
