INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '트위터에서 마싯다구 해서 와봤어요 !!! 일본에서 먹은 당고랑 비슷해요!! 가격도 저렴하구 굿 메뉴도 꽤 많아요!!! 세트메뉴도 있어서 둘이서 오면 더 이득일 듯 ,,,', 76, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '손님이 많아요!! 주말에는 좀 많이 기다려야하지만 기다려서 먹어도 후회 없는곳 입니다!! 메뉴 거를것 없이 다 맛있습니다!!!', 222, 30, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '일본당고가 너무 먹고싶어서 현지맛 찾아서 왔어요~~ 종류도 많고 일본당고만큼 너무 맛있어요~💛 당고 먹고싶을땐 우마이당고 올께요~', 11, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '10년만에 먹어본 당고! 여친도 이게 당고지~라고 감탄했습니다ㅎㅎ 짭짤달달하고 굽자마자 먹으니까 쫀득해서 더 맛났습니다! 다만 콩가루 날리니까 바람을 등지고 드셔야해요~', 54, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '저번에 먹고 너무 맛있어거 오늘 다시 재방문했어요!! 여긴 당고 맛집입니다~~ 당고 좋아하시는 분들은 꼭 한번 오시면 좋을 거 같아요☺️', 35, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '따듯해서 일본에서 먹었던 것보다 더 맛있어요 ㅠ 일본 가고싶을때마다 와서 한번씩 먹고 뇌에 힘줘야겠어요 가성비 일본여행 댕이득ㅠㅠ', 46, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '미타라시, 간장에 인절미가루를 주는데 떡은 다 아는맛, 쫀득 보다는 당고 특유의 진짜 꿀떡꿀떡 넘어간다 할때 그 부드러운 식감이고 간장소스가 짭짤 달콤한데다 인절미가루가 달달 고소해서 궁합이 아주 잘 맞아요! 이색디저트로 딱! 주의) 당고 다 먹고 종이를 접으면 맨 아래 미세한 구멍으로 남아있던 소스가 흘러나올 수 있음', 37, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '당고집이 있어서 홀린듯 들어왔어요 기본당고뿐만아니라 다양한 당고가 있어서 골라먹는재미도 있어요! 가격도 저렴해서 맛있게 먹고갑니다!', 83, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '따끈쫄깃 진짜 맛잇어요~ 근데 더 맛있게 먹으려면 ❗️꼭 당고가 식고나서 드세요❗️ 뜨거울때 먹으면 미타라시 당도 특유의 맛이 잘 안느꺄져요 꼭 식고 드세요!!', 407, 68, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '홍대 지나가다 들린 당고집인데 당고란 간식을 처음 먹어보는 것 같아요 맛도 다양하고 맛있네용 다음에 서울와도 꼭 들릴 가게입니다😀', 41, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '일본은 못가지만 당고는 먹어보고자 방문했는데 친절하셔서 일단 만족합니다^^ 3개 포장했는데 맛있을 거 같아요. 얼른 맛보고 싶네요!!', 44, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '서울권 당고 중에선 여기가 최고인 거 같아요 여기서 한번 먹고 잊을 수 없어서 홍대 올 때마다 힘듦을 참고 걸어오는 사람...♡ 다들 꼭 드셔보세요', 103, 25, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '그 자리에서 바로 토치로 구워주셔서 따뜻하게 바로 먹을 수 있어서 좋아요  맛있어요!! 그리고 J-POP좋아하는 사람으로써 노래 들으면서 대기할 수 있어서 좋았습니다 😆', 11, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '연남쪽에 새로 생긴 당고맛집이래서 길가는 길에 먹어봤는데 맛있어요😍 근처에서 밥 먹고 역으로 나가면서 들고 먹기 딱 좋은 사이즈에요!', 250, 41, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '나만 알던 맛집인데 너무 유명해져서 줄서서 주문하고 기다려서 받다니ㅠㅠㅠ 더 유명해지지마.. 아냐 사라지면 안돼.. 유명 안해졌으면 좋겠는데.. 엄.. 주문 후 10팀이 앞에 계셨는데 계속 준비하시고 계셔서 5분 안에 저의 당고 받았습니다!!', 32, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '한국에서 흔히 먹을 수 없는 당고라 너무 소중하고 맛있어요 ㅎㅎ 그래서 지방 사는데 꼭 서울 올때마다 먹습니다!!! 계속 장사해 주세요 ㅎㅎ', 104, 20, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '우마이 당고'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '사람들이 우르르 당고 주문하고 드시고 계시길래 궁금해서 먹어보았어요! 15분정도 대기했습니당 기대한만큼 맛있었어요 일본 당고 넘 좋아하는데 자주 올게요 :) ㅌ', 1, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소림커피'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '이번 싱글 오리진 에티오피아 내추럴도 진짜 맛있어요. 샌드위치도 진열대에 빵 있으면 무조건 시켜야 합니다. 소림커피 최고 👍 👍', 9, 1, 'GOOD', SYSTIMESTAMP);
