INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소림커피'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '두번째 소림커피 추억하러 왔어요~~ 샌드위치는 여전히 맛있고 디카페인 아메는 구수해요~ 멜버른 아이스커피는 커피는 진하고 달달구리 맛있어요~', 49, 3, 'GOOD', SYSTIMESTAMP);
