INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소림커피'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '새로 출시한 썸머 블렌드 과일향 가득해서 맛있어요. 원두도 판매하고 있어서 원두도 사왔어요. 소림커피와 함께 여름에도 즐거운 커피생활 ☕️ ❤️', 93, 25, 'GOOD', SYSTIMESTAMP);
