INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소림커피'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '평일에 소림커피를 갈 수 없는 저는 토요일이 소림커피를 갈 수 있는 유일한 날입니다. 매장에서 직접 만드시는 빵이랑 샌드위치도 맛있지만 직접 로스팅한 커피가 진짜 맛있어요. 이렇게 맛있는데 가격까지 저렴해서 너무 감사한 마음으로 먹고 있습니다. 곧 개업 5주년인데 오래오래 해주셨으면 좋겠습니다.', 43, 6, 'GOOD', SYSTIMESTAMP);
