INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소림커피'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '몇안되는 인생라떼중 한곳입니다!  날씨가 더워져서 아이스만 먹어봤는데..  뜨라도 꼭 마셔보고 싶네요! 근처 프랜차이즈 커피맛에 질렸었는데.. 약간 걸어도 소림들려서 커피마시고 충전후 출근하고 있어요 🤗', 17, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소림커피'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '서울 올 일 있으면 모든 일정을 소림 커피 위주로 짭니다 몇시 쯤엔 일을 마쳐야 소림 문닫기 전에 세잎할 수 있어!! 이런 식이예여 소림의 찐~~~~한 아이스라떼는 제 영혼을 치유해주는 마법의 음료거든요 철마다 바뀌는 디저트를 먹는 것도 큰 재미인데 겨울철이라 역시 딸기케이크가 있네요!! 미친 맛 ㅠㅠ 풍성한 마스카포네치즈와 생크림, 얇은 시트 속에 콕콕콕 박힌 딸기 한입 먹고 아이스라떼 흡입하니 여기가 천국😍 달지 않고 상큼하고 부드러워염🥹ㅡ 소림 단골 우리 언니는 자꾸 4번 아메리카노와 디저트 같이 먹으라고 강요하지만 전 아이스라떼와의 조합이 더 좋아여.. 언제 다시 올지 알 수 없어 발걸음이 떨어지질 않네요ㅠㅠ 영원하라 소림👍', 20, 0, 'GOOD', SYSTIMESTAMP);
