INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소림커피'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '라떼가 땡기면 소림으로~~~ 원두도 여러 종류 디저트 샌드위치 다 맛있어요~~ 오픈도 일찍 해서 출근길  직장인들의 참새 방앗간 같은곳', 77, 12, 'GOOD', SYSTIMESTAMP);
