INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소림커피'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '회사 근처라 진짜 자주 가는데 커피 너무 고소하고 (특히 라떼!) 맛있어요 진짜 한입씩 다들 먹여주고 싶다😮‍💨😮‍💨😮‍💨게다가 나오는 베이커리도 전부 맛도리인데 알고보니까 제가 주말마다 집에서 자주 배달시켜먹던 근처 커피폴리의 버터프레첼이 여기서 왔전(?)거라고 하더라고요..? (아닐 수도 있음 지금은 안 팜용) 아뭍턴!! 진짜 🥨프레첼🥨 좋아하시는 분들 다들 한번 먹어주세요.. 제발요~~~~~💛💗💛💗', 1, 2, 'GOOD', SYSTIMESTAMP);
