INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소림커피'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '무뚝뚝하셔서 좀 당황스러웠지만, 아이스 라떼 마시면서 걍 다 잊었습니다. 흑단목 원두 선택해서 쓴 맛이 심할까 걱정했는데, 오우~ 진짜루 다크초콜릿 맛이 나요~~ 너무 맛있네요. 근처 여러 카페 가봤는데 여기가 찐입니다.', 36, 4, 'GOOD', SYSTIMESTAMP);
