INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소림커피'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '직접 로스팅한 원두로 만드는 커피가 맛있어요. 빵 종류는 많지 않지만 다 맛있습니다. 다양한 싱글오리진으로 필터 커피도 먹을 수 있어요.', 70, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소림커피'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '대구러..요즘 핫한 성수동 근처에 출장이 있어 상경했지만 소림커피 마시러 홍대까지 갔습니다 제게는 서울 최고 카페는 소림커피니까요😊 커피는 당연 최고고 갈때마다 오늘은 어떤 디저트가 있을까 설레는 재미가 있어요 오늘은 애플시나몬크림치즈스콘 발견!! 시나몬향은 은은하고 크림치즈는 풍성해서 찐한 커피와 잘 어우러졌어요', 48, 2, 'GOOD', SYSTIMESTAMP);
