INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소림커피'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '서울 올 때면 꼭 들르는 소림커피. 카페라테가 정말 꼬숩고, 드립백도 맛있어요 드립백 중 흑단목은 신맛 없이 다크다크해서 누구나 좋아할 맛! 오늘은 무화과크림치즈휘낭시에 없어서 아쉬웠는데 러스크앙버터와 카푸치노스콘도 정말 특별한 맛이네요! 디저트가 독창적이예요👍👍 버터프레첼도 딱딱함은 덜하고 고소함은 더해서 제 기준 버터프레첼 최고맛집입니다 소림세권 거주자 및 직장인 부러워요', 77, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
