INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소림커피'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '소림커피는...정말 너무 애정하는 곳인데 드디어 후기를 남김. 이곳 커피는 정말 찐임. 지인 소개로 알게된 곳인데 집이랑도 거리가 있고 위치도 편리하진 않지만 그래도 이곳 커피만한데가 없어서 늘 찾아가게됨 ㅠㅠ 아무 메뉴나 먹어도 맛있고 베이커리류도 훌륭함. 그냥 사장님 오래오래 변치말고 계셔주길 바랄뿐....', 16, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소림커피'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '소림커피 안와본 사람 없게 해주세요ㅠㅠ 꼬숩고 부드러운 카페라떼, 진하고 향기로운 아이스카페라떼, 무화과 호두 크림치즈가 풍부하게 들어있는데 기름진 느낌이 1도 없는 무화과 호두 크림치즈 피낭시에 계산할 때마다 놀라운 갓성비! 매장 앞에 작은 숲(?)이 있어서 소림커피인가봐요 항상 느끼는 거지만 대형 카페는 작은 규모 로스터리 카페의 풍미와 수제 디저트의 퀄을 절대 흉내낼 수 없는 거 같아요 오늘도 너무 잘마셨습니다!', 79, 14, 'GOOD', SYSTIMESTAMP);
