INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소림커피'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '원두를 사면 커피 한잔 무료에요 이런 서비스 음료 시스템 너무 좋아요 휘낭시에도 아주 클래식한데 기본을 다 잡았어요 매장이 아주 깨끗하고 정갈해요 저는 이런게 좋아요 원두도 So Good~', 82, 12, 'GOOD', SYSTIMESTAMP);
