INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소림커피'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '커피 정말 찐탱맛집 소림 👍 집앞이라 종종 가요 제 남자친구가 커피에 정말 진심인데 왠만한 카페 안다녀 본곳 없는데 여기는 정말 커피가 정말 맛있다고 너무 좋아해요 정말 맛있어여 소림은 커피에 진심이에요 👍🥰🫶🏻', 4, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소림커피'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '한 번 먹어보고 맛에 반해서 여러 번 방문 중인데요!저는 올 때마다 토마토 바질 치아바타 샌드위치랑 멜버른 아이스 커피를 꼭 마셔요! 최애 메뉴랍니다🥰 다른 커피랑 빵도 먹어봤는데 라떼 종류랑 초코 스콘, 얼그레이 마들렌, 무화과 휘낭시에 맛있었어요!! 커피랑 빵 맛집이에요!☺️사장님도 너무 친절하셔요👍소림커피 최고입니다ㅠㅠ 더 번창하세요🙏🏻', 79, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소림커피'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '원두 오백그램 23000원 말이 되나 ?! 근데 150그램 살때만 시음음료있다는걸 계산하고나서 깨달았다 쬐끔 아쉬웠지만 가격이 너무 합리적이여서(나에게 합리적이고 사장님한텐 안 합리적) 바랄 수 없었다. 나중에 베이커리류도 먹어봐야지.', 81, 16, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소림커피'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '나는 머신커피는 주로 타격감을 원해서 먹는데 소림커피의 커피는 그게 알맞지 않은 것 같다. 첫 맛은 조금 밍숭맹숭하게 느껴지는데 뒤에 남는 향이 장난이 아니다. 고급진 느낌이 느껴지는 느낌… 드립커피도 좋아하지만 주로 혀 끝에 남는 향미가… 산미가 셀수록 식초먹으면 혀끝이 약간 아픈것처럼 뾰족하게 돌아서 주로 고소한 류의 블렌딩원두를 내려먹는편인데, 이 커피는 향이 혀 뒤.. 목구멍 앞쪽에서 부드럽게 퍼지는 느낌이다. 그리고 이번에 사고나서 알았는데 150그램은 12천원 500그램은 23천원이었다 !!! 12천원도 싼데.. 나중엔 500그램씩사서 먹어야겠다', 54, 15, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소림커피'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '아이스카페라떼 정말 맛있고 블랙카푸치노 같은 특별한 메뉴가 있어요.  비쥬얼 최고네요.  베이커리류도 다양한데 특히 무화과 크림치즈 휘낭시에는 커피맛을 해치지 않으면서 존재감 쩌는 디저트예요. 결정적으로.. 영수증 리뷰 쓴다고 영수증 보고 가격에 놀랐습니다. 가성비 너무 심하게 좋은 거 아닌가요..', 102, 21, 'GOOD', SYSTIMESTAMP);
