INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소림커피'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '밤 식빵이 맛있다는 추천을 받아서 사먹어봤어요. 밥 알갱이가 큼직큼직하게 들어있고 너무 달지도 않아서 좋아요. 간식으로 우유와 함께 먹으니까 더 조화롭고 부드럽게 먹을 수 있어요! 밤 식빵 강추합니다!!', 42, 6, 'GOOD', SYSTIMESTAMP);
