INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소림커피'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '소림사처럼 연출하려는 것 때문인지 나무에 가려 간판이 잘 안 보일 수 있어요. 두번 방문했는데, 처음 온 사람보다는 이 근처로 출근하는 사람들이 루틴처럼 커피 테이크아웃하는 분들이 대부분이었어요.', 38, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소림커피'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '여길 오기위해 출근하신분 백퍼 공감이네요 너무 맛있어요 샌드위치도 맛나고 커피도 넘 맛나네요 맛난건 3잔 ㅋㅋㅋ 치아바타샌드위치 7,000 코코넛크림커피 5,000 바크콜 5,000', 42, 7, 'GOOD', SYSTIMESTAMP);
