INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소림커피'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '회사다니면서 가장 좋았던건 소림이 바로 앞에 있어서였는데... 음료도 맛있고 디저트도 짱이었어여 ㅠㅠㅠ 퇴사로 거길 못가는게 넘 아쉽네요 ㅠㅠ 번창하세요!!!', 28, 7, 'GOOD', SYSTIMESTAMP);
