INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소림커피'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '드디어 크림치즈베리스콘을 먹게되네요! 크림치즈가 가득해서 너무 맛있었어요 디저트 날짜가 정해져있지 않아서 매일 기웃기웃하는게 힘들어요 ㅋ', 35, 10, 'GOOD', SYSTIMESTAMP);
