INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소림커피'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '소림커피는 서교동 최애 커피집! 커피랑 베이커리류 다 맛난데, 샌드위치까지 맛있어서 내 지갑을 탈탈 털어가는 곳 🥲 사랑해 소림,,,', 64, 13, 'GOOD', SYSTIMESTAMP);
