INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소림커피'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '소림커피 없으면 출근하기가 싫을 거예요 🤭 서교동 최고 커피!! 브루잉 커피, 플랫화이트 강추해요. 관계자 아니구요? 소림커피에 지분 없습니다.. 지분 있고 싶네요 ㅎ', 79, 17, 'GOOD', SYSTIMESTAMP);
