INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소림커피'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '소림의 고수처럼 숨어 있어서 소림인가요? 홍대 골목의 숨겨진 베이커리 카페 :) 빵맛집 공간맛집 커피맛집. 콜드브루는 좀 많이 써요...', 2, 2, NULL, SYSTIMESTAMP);
