INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소림커피'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '작지만 굉장하 매력적인 카페였어요 . 오랜 시간 머물 수 있는 분위기는 아니지만 커피도 맛있고 방도 꽤 괜찮았습니다. 베이커리의 경우 요일별로 메뉴가 변경되니 원하시는 거 맛보려면 확인하고 가시는 게 좋아요. 분위기도 좋고 음악 선곡도 마음에 들었고 사장님들도 참 친절하셨습니다. 홍대 부근 치고 가격도 나이스한 편이었어요. 블랙 카푸치노는 은은하게 달면서 고소했고 러스크 바는 달달 쫀득 합니다. 재방문 의사 엄청 많아요', 73, 18, 'GOOD', SYSTIMESTAMP);
