INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 동교삼거리점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '감자빵 3,500원 데워나오는데 너무 맛있어요 디카페인 카페라떼 3,900원 할메가커피 스무디 2,900원 가격 대비 가성비가 좋아서 커피한잔 잠시하고 전자기기 충전도 가능해서 좋았습니다. 매장은 엄청 좁지만 나름 테이블 수가 많아요.', 127, 19, 'GOOD', SYSTIMESTAMP);
