INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 동교삼거리점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '프로맛박사 리뷰올립니다! 서울 전체 메가커피를 가보고 있는중입니다~ 키오스크에 제로 사이다 변경이 없어서 그냥 주문하고 사장님께 말씀드렸어요! 제로 사이다 변경이 가능한 음료를 저는 많이 가봐서 알고있는데 모르시는분은 검색해보시고 교체해서 드세요!', 40, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 동교삼거리점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '메가커피 동교삼거리점 테이블 작은거 10개있고 알바가 매번 엄청 바쁩니다. 그래도 음료는 빨리 나와요 . 2번출구랑 가까운데 연남쪽으로 들어가야해요.', 31, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 동교삼거리점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '매장이 좀 협소함ㅠㅠㅋㅋㅋ 알바분들 친절하시구 쾌적함 :) 바쁘신거 같은데 두분만 계셔서 힘내라 해주고 싶음ㅜ 저녁 연습전에 잘 쉬다 갑네다ㅎㅎ', 39, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 동교삼거리점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '가성비 좋아요. 맛 좋아요. 키오스크 카드 꼽으면 안되고 갈때마다 긁으라고 뜨네요. 처음부터 긁어달라고 뜨면 좋을텐데... 씨제이 적립도 번호 입력하면 안되더라구요. 저만 그런가 하고 다른이 하는거 봤는데 그분도 안됐었어요 확인 한번 해주세요', 48, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 동교삼거리점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '여긴 직원 한명은 음료 정량 못맞춥니다. 직원 두명이 벽에 기대어 얘기하고 있어서 키오스크 주문하고 얼음 적게 넣어달라고 했는데 한명은 얘기하느라 제 말을 못들은건지... 그냥 컵에 한가득 얼음 담고 우유 붓더니 옆에 다른 직원이 얘길해주니까 그제야 집게로 얼음 몇개 꺼내고 커피부어서 주네요.. 근데 보통 얼음을 적게 넣으면 음료양이 준다던데 안줄어든 것 보니 처음 만든대로 받았으면 넘쳐서 커피는 다 들어가지도 않았을 듯. 전에도 주문할때마다 이런식이라서 한동안 다른 지점 가다가 오늘 급한대로 갔는데, 그 직원보고 아 잘못왔구나 생각했는데 역시나인것 같네요~ 원래 그런 매장인가...', 31, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 동교삼거리점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '체리콕 맛난다고 해서 먹었는데.. 좀 아쉬운게 콜라 김이 다 빠졌어요. 만드는 거 봤는데 이미 사용했던 거 남은 거 넣더라고요. 어쩔 수 없지만 좀 아쉽..ㅎ 그래도 전 여기 단골이에요~ 엄청 자주가요. 늘 라떼나 아아를 마시는데.. 새로운 메뉴도 좀 먹어봐야겠네요. 사업 번창하세요!', 4, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 동교삼거리점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '매주 2회는 오는 단골입니다. 원래 더 자주 갔었지만 ㅎㅎ 여튼 늘 맛있고요. 가성비 좋아요. 알바생들이 힘들어보이지만 열심히 하네요... 감사해요! 수고하세요!', 0, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 동교삼거리점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '학원 쉬는시간에 잠깐 다녀왔는데 시크하신 알바생 분... 매장 깔끔하고 좋았습니다 ㅠㅠ 사람 많아서 앉을 자리는 조금 선착순으로 후다닥 차지해야 하긴 하지만 그래도 자주 들르는 곳이에요!', 8, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 동교삼거리점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '유난히 더운날이라 그런지 시원한 음료를 시키려고 대기하는 사람들이 많았어요~ 위치성도 좋고 사람들 대기가 많아서 맛집 같은 너낌?🙂 음료 나오는데 까지 10분 정도 걸렸네요~ 여 직원분 두분이서 많이 바빠 보이던데 한분은 굉장히 친절하시고, 다른 한분은 짜증섞인 말로 틱틱거리는 목소리로 말씀하시길래 인상이 깊었네요. 명찰에 적힌 네임이 민정? 문정? 인지 그분은 좀...;;;  메가커피 어느지점이든 레시피는 같은데 손님 응대를 이렇게 하는 지점은 굳이 재방문 안하죠~', 215, 66, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 동교삼거리점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '청송 애플 선셋 티플레저와 청송 애플파이 프라페를 주문했는데 두 메뉴 모두 맛있네요!! 상큼한 맛이 강하지 않고 달달한 맛도 나서 좋았어요', 87, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 동교삼거리점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '12시쯤 방문했는데 직원 두 분이 일하고 계셨어요. 따아 크로크무슈시켰는데 나오기까지 30분 기다렸어요. 앞에 단체 오더가 있어서 그런가보다했는데... 9잔 이더라구요?ㅋㅋㅋㅋ이 속도는  한국인은  속에서 천불이 나는 속도입니다. 제 앞에 오더하신 남자분은 직원분께 자기꺼 언제나오냐고 확인하더니 옆에서 계속 쌍욕하시곸ㅋㅋㅋㅋㅋ 결론적으로 메뉴를 받았는데 아메는 먼저 뽑아놨는지 다 식어있고 크로크무슈는 제대로 안 데우겼는지 차가워서 집에가서 다시 데워 먹어야.....ㅋㅋㅋㅋㅋㅋㅋ 다신안가요...', 47, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 동교삼거리점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '음냐 커피만 먹다가 과일음료 시켜봤는데 증말 맛없는 만드는 과정을 봤는데 재료를 너무 아끼는듯 얼음만 잔뜩 >< 다신 안먹어..3,900원도 아까움', 43, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 동교삼거리점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '홍대입구라 평일낮에도 다른지역보다 주문이 2배이상은 많은데, 일하시는분은 1분이셔서 그분은 숨돌릴틈도 없어보이심. 화장실은 아애 못갈것같고, 자리비우면 큰일날것 같은 바쁨바쁨 음료나오는 곳에 주변정리할 여유조차 없음. 손님들이 다 먹고 놔둔 빈 음료컵들과 주문해서 나오는 새로운 음료들과 나란히 서 있어서 당황스러움. 음료는 맛있었고 직원은 상냥했음.', 71, 16, NULL, SYSTIMESTAMP);
