INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 동교삼거리점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '꿀아메리카노 2700원 공부 전에 늘 커피 마시는데 오늘은 꿀아메리카노 땡겨서.. 완전 맛있는데 다요트 땜에 자주 못 먹어요 ㅠㅠ 맛나요!! 꿀!', 6, 10, 'GOOD', SYSTIMESTAMP);
