INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 동교삼거리점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '평일 오전 알바생 교육 좀 시키셔야할듯해요. 바빠서 그런거라면 사장님이 알바생 한명을 더 넣어주셔야할거같아요. 손도 느리신거같고요. 계속 늘어지는 피곤한 목소리로 서비스업할거면 다른 직종 찾으셔아할듯합니다. 계속 웃고 친절해야한다는게 아니라 알바생 눈치가 보여요', 19, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 동교삼거리점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '매니저로 보이시는분 말투가 너무 불친절해요 다신 가고 싶지 않습니다 손님한테 좀 예쁘게좀 말하면 안되나요.. 그건 그렇다치고 손님이 옆에 있는데 예쁜 알바생 너무 적나라하게 혼내는게 마음이 안쓰러웠습니다..ㅠ', 32, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 동교삼거리점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '물없이 얼음가득 부탁드렸는데 뚜껑 때문에 더 못 준다고 하셨어요. 회사에 얼음이 있길래 더 넣었는데 들어가네요. 카페 알바 해보면 가득 넣는 것 정도는 해줄 수 있을 텐데 조금 아쉽네요.', 38, 6, NULL, SYSTIMESTAMP);
