INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 동교삼거리점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '탈색 머리하신 알바분 요청사항 너무 안 지켜주시네요 매번 커피 샷도 컵 바깥으로 흘러 넘치구요 그 시간대 알바분들 메가오더 알림도 눌렀다 안 눌렀다 하도 잘못 누르시는 것도 여러번이구요 저가형 커피숍에 대단한 서비스를 바라는 건 아닌데 기본적인 상품 퀄리티가 타 지점에 비해 너무 떨어지네요 기본만이라도 지켜졌으면 합니다', 15, 7, NULL, SYSTIMESTAMP);
