INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 동교삼거리점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '아침에 계신 앞머리 있고 살집 있으신분 cs엉망이네요 손님이랑 싸우자는 건지 뭔지 커피 직원분한테 많은걸 바라는 건 아니지만 일하기 싫은건 알겠는데 티좀 내지 마세요', 69, 15, 'BAD', SYSTIMESTAMP);
