INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 동교삼거리점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), 'ㅎ.. 포터필터에 잔뜩 낀 커피 때를 봐버렸다.. 그걸 대충 슥삭 하고 커피를 새로담아서 내린다고..? 더러워요.. 맛있었던것도 맛 없어지겠어요..', 41, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '아사이볼은 꼭 올루올루에서 먹는걸루..💜 내가 그동안 먹은 아사이볼은 아사이볼이 아니었구나 싶을만큼 퀄리티, 맛, 재료 신선도 모두 완벽해요💛 ✔️베이스 맛이 다양해서 좋아요(복숭아, 망고 등) ✔️라이트, 스위트, 시그니처로 선택할 수 있는 폭이 넓어요! ✔️생과일 신선도가 남달라요👍 무른거 하나 없고, 그렇다고 덜익은 것도 없이 너무 잘 익은 과일들이에요🍑🍌🍓 ✔️사장님이 너무 예쁘고 친절하세요..🫶🏻💜💜 친구가 아사이볼 먹고 싶다고 해서 다음에 꼭 여기로 데려오려구요 ㅋㅋ 약속했답니당🤗 다들 진짜 꼭 드셔보세요~!!!! 강추!!', 67, 13, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '홍대입구역 올루올루에서 아사이볼 먹었어요! 토핑이 엄~~~청 많이 올라가요! 망고, 바나나칩, 초코볼, 그래놀라까지 토핑이 진짜 알차고 비주얼부터 만족!!!. 베이스도 너무 다 먹고 싶었는데, 맛보기 가능하고 반반메뉴도 가능합니다! 베이스가 다 너무 상큼해서, 빙수 땡기는 날 빙수말고 여기 올 것 같아요!🥰 홍대입구역에서 가깝고 맛있어서 재방문의사 있습니다 ㅎㅎ👍👍👍', 11, 6, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '아사이볼의 아사히가 뭐죠?🤷‍♂️ 아사이베리에요🙏 더워서 1층에 있는 공차가려다가 아사이볼이라는 이름에 이끌려 방문하게 되었어요 ㅋㅋ 아사이 시그니처로 주문하고 피타야베이스를 추가했는데, 아주 상큼한게 맘에 쏙 이었습니다.👍 그리고 리뷰쓰면 1000원 페이백 와우 늘 쓰던거니까 꽁돈 받는 기분~👏👏 날도 더운데 잠깐 들러서 에어컨 만끽하고 입에 시원한거 넣고 아주 좋아요! ㅋㅋㅋ (15분에 들어왔는데 주문하고 3분만에 나와서 리뷰를 적는 지금 40분 되기 전에 나가는 미래가 그려짐) 재방문 의사 있습니다~', 27, 6, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '이번에 홍대에 새로운 아사이볼 가게가 생겼다고 해서 방문했어요! 아사이 시그니처로 주문했는데 아사이베이스랑 과일 전부 신선하고 맛있어서 너무 행복했답니다 .. 😋💝 다이어트 하시는 분들도 홍대 오신다면 추천드리고 싶어요!😍 그리고 사장님이 대빵 친절하시고 아름다우십니다 💗', 50, 3, NULL, SYSTIMESTAMP);
