INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '아사이볼 처음 먹어봤는데 진짜 너무 맛있어요!! 과일이 정말 싱싱하고, 시럽 없이도 달콤해서 건강한 디저트 느낌이에요🍓🥝 빙수 대신 이런 거 먹으러 데이트 오는 거 강추합니다! 그리고 꼭 드셔야 하는 거 하나 더! 치아씨드 푸딩!!', 69, 14, 'GOOD', SYSTIMESTAMP);
