INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '홍대 맛집입니다요 홍대에서 이렇게 건강한 디저트를 먹을 수 있는 게 넘 좋아요! 카페 안도 시원하고 테이블 사이도 넓어서 편합니당', 72, 17, NULL, SYSTIMESTAMP);
