INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '아사이볼을 워낙 좋아하는데 홍대 지나가다가 들렸어요. 피타야 베이스랑 반반 했는데 너무 맛있어요. 다른 지점은 자리가 별로 없어서 불편했는데 홍대점은 자리도 넓어요.', 17, 7, NULL, SYSTIMESTAMP);
