INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '넘 상큼하고 맛있는 아사이볼 칼로리 높은 음식 고기, 피자, 치킨, 파스타... 헤비한 음식 먹고 후식으로 딱이에요 신선하고 맛있어요', 4, 5, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '지나가다가 생긴 거 보고 와야지 하다가 드디어 와봤어요 나만의 볼로 내 맘대로 담고 싶은거 담을 수 있어서 좋아요 아사이볼 땡길 때 자주 올 것 같아요! 땅콩버터가 진짜 맛있네용 ㅎㅎ 베이스 반반 선택 가능했는데 피타야베이스도 상큼하고 맛있어요!! 먹다보니 용과맛이 나서 뭐지 했는데 피타야가 용과네여 ㅎ,, 그린베이스도 궁금해서 담엔 그린베이스로 먹어보고싶어용 케일맛이 얼마나 날지 궁금해요ㅎㅎ', 82, 14, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '매 번 배달만 시켜서 먹다가 오늘 잠깐 시간나서 매장 방문해사 먹어봤는데 예상치 못하게 너무 좋은 뷰와 함께 그리고 친절한 직원분의 응대에 무기력한 월요일 아침 힐링 받고 갑니다❤️ 오래오래 번창하세요🫶🏻', 46, 9, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '아사이볼 진짜 좋아하는데! 홍대에 찐 아사이볼을 맛볼 수 있는 곳을 발견해서 넘 기뻐여!!!! 건강한 간식에~ 맛도 있고🤤 제 최애 간식입니당 이것저것 토핑 골라 먹을 수도 있고 시그니처 / 스위트 나눠져있어서 선택장애도 고르기 쉬워용 히히 넘 맛있어서 또올래용', 65, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '그린베이스는 녹차가 아니라 케일 들어간거래요😆 나만의 볼로 피타야 베이스에 그린베이스 반반했는데 피타야는 상큼하고 그린은 시원해서 맛있어요 (기본 아사이 베이스는 새콤한 맛이 더 있는 거 같아요) + 토핑은 코코넛 청크에 생블루베리 위트박스 추가함', 83, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), 'I’ve been craving an acai bowl and I’m so happy to find this place here in hongdae. It tastes just like how I imagined it to be :) yummy and healthy!', 7, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '배고픈데 뭐 먹을까 고민하다 아사이볼 전문점이있길래 방문했어요. 그린라이트에 아사이베이스 반 해서 먹었는데 맛있어요! 그린은 상큼하고 아사이는 상큼달달해서 조합좋았습니다. 맛있게 잘 먹었어요!', 16, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '애정하는 아사이볼 맛집 올루올루 ❤️ 홍대점 두번째 방문인데 역시나 최고 ㅠㅠㅠㅠ 아사이 스위트 (반반 망고 베이스 선택 강추합니다) 조합 믿고 먹어요 !!', 68, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '베이스도 토핑도 넘 신선한 게 느껴지고 많이 주십니다!! 특히 베이스가 진하고 넘 신선해욥!! 제 기준 현백 아사이볼보다 맛있는 것 같습니당! 베이스 반반으로 피타야 추가했는데 아사이가 깔끔한 것 같아서 담번엔 아사이 단독 베이스 먹으려구요!! 그냥 메뉴는 냉동딸기 가격이고, 생딸기는 별도 1500원 추가입니당! 막상 딸기를 받아보니 아주 쪼꼬만 아이였지만 생딸기를 좋아해서 추가했습니다! *네이버 리뷰 이벤트!!', 88, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), 'The acai bowl tastes really good.It has a healthy flavor that I like. I recommend the one with greek yogurt. It’s really delicious.🥰', 12, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '애정하는 올루올루 🫶🏻 더 가까운 곳에 생겨서 기분이 좋습니다 ㅎㅎ 아사이 스위트 언제나 행복한 조합 !! 포장주문했는데 매장이 깔끔해서 먹고 가기에도 좋아요 !', 4, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '직원분이 친절하게 설명해주시고 아사이볼 시원해서 맛있네요:) 토핑도 꽤 많이 들어가있어요! 아쉬운건 매장에서 먹는데도 플라스틱통에 담겨져 나와요 그래서 가성비 좋으니까 한번쯤 드셔도 좋을 것 같습니당', 24, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '맛있따!!!! 발리에서 먹던맛 그대로 입니다 ㅎㅎㅎ 아사이볼이 너무 땡겨서 홍대까지 왔는데 후회없는 선택이였어요~ 좌석도 많고 회전율도 좋고 너무 좋아요!', 23, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '광화문점 갔다가 너무 맛있어서 또 가고 싶었는데 홍대에도 생겨서 좋네요 !! 베이스 종류 많아서 좋아요 !! 토핑 종류도 다양하고 매장 깔끔해서 잘 먹고 갑니당~', 50, 6, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '일단 맛이 좋구요! 베이스를 반반으로 나눠서 먹을 수 있어서 좋아요! 저는 아사이 베이스와 피타야 베이스로 먹었는데 친구가 먹는 그린 먹어보니 그린도 상큼하고 맛있어요! 홍대 오시면 시원하게 한 번 먹는 것도 좋을 것 같아요!🍓', 47, 6, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '아사이볼 진짜 좋아했는데 오크베x 입점때 가보고 너무 실망햇거든요.. 근데 여기가 진짜네요 토핑도 많고 선택지도 다양하고 ㅠㅠ 프루타볼 같음 ㅠㅠㅠ 너무맛있어요 사장님 번창하시길', 55, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '아사이볼 좋아하는데 베이스 옵션이 다양한 곳은 처음이라 신기하네용! 복숭아 스무디 땡겼는데 아사이볼먹으면서 같이 먹을 수 있다니 대박! 날도 더운데 빙수 대신 먹기 딱 좋습니당ㅎㅎ', 25, 6, NULL, SYSTIMESTAMP);
