INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '상큼하면서도 진한 아사이베리 맛이 입안 가득 퍼지고, 위에 올라간 과일이랑 그라놀라가 같이 어우러지니까 씹는 맛도 좋고 포만감도 있더라구요. 건강하면서도 디저트처럼 달콤해서 부담 없이 즐길 수 있었어요. 더운 날에 먹으니까 시원하고 상쾌해서 기분까지 좋아졌습니다. 또 먹고 싶어요! 🥄✨', 55, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '친구끼리도 혼자도 너무 좋은 올루올루 홍대점! 저는 아사이시그니처로 주문했는데 아사이베이스 그래놀라 땅콩버터 바나나 코코넛칩 꿀 딸기 가득 너무 맛있는 조합이에요!!! 한 끼로 딱이고 든든해요! 맛있게 잘 먹고 다녀갑니다  :)', 39, 2, 'GOOD', SYSTIMESTAMP);
