INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '늘 오고싶었던 올루올루 홍대에 생겨서 좋아요! 포장해갔는데 커스텀 되는거 반반되는거 너무 좋고, 더운날씨에 상큼하고 시원하게 먹을 수 있어서 넘 좋아요🥰', 0, 4, NULL, SYSTIMESTAMP);
