INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '확실히 주말에는 사람이 더 많네요! 외국인도 많은 것보니 한국 맛집으로 제대로 소문난 것 같아요🤪✨ 커스텀도 맛있지만 나만의 볼을 만들수 있다는게 정말 최고의 장점 같아요!!!!!!!!!!!!!!!!! 마시써 ㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠ', 2, 4, NULL, SYSTIMESTAMP);
