INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '항상 믿고 가는…. 너무 맛있고 자꾸 생각나서 되게 자주 오게 돼요ㅜㅜㅜㅜ 가성비가 너무너무 좋은 요거트 아이스크림집!!! 다른 곳은 못가겠어요ㅎㅎㅎㅎ', 51, 16, 'GOOD', SYSTIMESTAMP);
