INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), 'This place is delicious 😭💖 the chia seed pudding here is especially good, and the fresh fruit is very yummy. This is my second time coming, and I''ve really loved my bowl both times.  I''ve tried the acai and the pitaya before and both are really delicious ~ I think it''s my favorite acai bowl I''ve had in Korea 💕', 46, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '아사이와 복숭아베이스로 했는데 더운날 시원하니 딱이에요 다이어트중인데 죄책감 덜면서 먹기 딱입니다 ㅋㅋㅋㅋ 위트빅스 필수로 넣어드세용', 79, 18, 'GOOD', SYSTIMESTAMP);
