INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '과일 토핑 제가 직접 골라서 먹을 수 있어요. 아사이베리가 시원하고 맛있어요. 양이 적을까 했는데 기본 사이즈로 먹어도 배가불러요.', 13, 4, 'GOOD', SYSTIMESTAMP);
