INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '배달로만 시켜먹다가 홍대 온김에 먹고 가려고 들렀어요. 이번 여름은 빙수보다 아사이볼을 더 자주 먹고 있어요. 먹고나면 든든하고 건강한 맛이라 기분도 좋습니다~~ 매장도 깔끔하고 테이블도 여러 개라서 좋네요. 바테이블에서 창밖 구경하면서 먹고 갑니다ㅎㅎ', 4, 7, 'GOOD', SYSTIMESTAMP);
