INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '더운날 시원한 디저트를 찾아 헤매다가 들어왔습니다 시원한 아사이볼과 요거트 아이스크림 짱이에요 생과일 맛이 진하게 느껴지고 토핑도 듬뿍 올라가서 더 좋았습니다 잘 먹고 갑니다~', 44, 7, 'GOOD', SYSTIMESTAMP);
