INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '벌써 몇번째왔는지 모르겠어요….ㅎㅎㅎ 맛있고 가성비가 너무 좋아서 요거트 아이스크림 먹는다 하면 여기만 오게돼요!!! 생과일 너무 싱싱하구 맛있어요ㅜㅜㅜㅜ', 58, 15, 'GOOD', SYSTIMESTAMP);
