INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '#헬시푸드 #스무디맛집 #후식맛집 #홍대디저트 엄마와 함께 맛있게 잘먹었어요~ 언니도 친절하고 디저트로 딱이예요 종종 들릴게요~!💯', 8, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '폭염에 시원한거먹고싶었는데 새로생긴 아사이볼집에왔어용 토핑이 엄청 다양해서 이것저것 추가해서 먹기좋은거같아용!! 저는 과일을 별로안좋아해서 좋아하는거 위주로 와르르 먹었는데 너무너무맛도리였네용 😍😍😍🩷초코쉘 처음먹어보는데 진짜달콤하구맛있어용!  자주올거같아용💖🥰 홍대맛집 발견했네용 ~ 분위기도 시원하구 좋아용!!!', 40, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '매장도 시원하고 재료가 신선해서 잘 먹구 갑니당😭👍 아사이볼 진짜 상큼 달달 그 자체였어요! 💜 건강하게 달달함 땡길 때 딱이에욧', 44, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '요거트아이스크림 라이트로 했는데 토핑도 고소해서 맛있어요! 메뉴들이 다 맛있어보여서 엄청 고민하면서 고른거였는데 넘 맛있어서 담번에 오면 다른 맛들도 다 골라보고 싶어요', 27, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '너무 상큼하고 맛있어요! 건강한 간식 먹고 싶으면 여기로.. 아사이볼 정말 좋아하는데 신선한 과일들이랑 먹으니까 넘맛있어요🥹🥹', 47, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '아사이볼 파는 곳이 흔하지 않은데 홍대에 있어서 넘 반갑네요 ... ㅎㅎ 분위기좋고 조용해서 혼자왔는데도 괜찮았고 홍대에 이런 아사이볼 맛집이 있어서 좋아요 🩷', 16, 5, 'GOOD', SYSTIMESTAMP);
