INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '올루올루 홍대점 아사이볼 너무 맛있고 토핑 선택할 수 있어서 원하는 맛으로 만들 수 있어서 좋아요💞🥹 매장 쾌적하고 직원분들 너무 친절하셔서 좋은 시간 보내고 갑니다!!', 28, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '예약없이 방문했는데 바로 이용가능했고, 넓진 않았지만 충분히 쾌적한 공간이었어요! 토핑이랑 베이스랑 거의 1:1 비율인거같아용 토핑 좋아하시는 분들은 좋아하실 것 같습니당 >_< 맛있게 먹구 가용❤️', 77, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '아사이 스위트 조합이 다 달달한 토핑이라 처음 드시는 분들도 좋아할 것 같아요 ! 아사이 베이스부터 과일까지 다 신선하고 맛있습니당', 12, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '아사이볼이 진짜 맛있어요! 양도 많고 가성비 최고에요!!!!!!!! 2층이라 분위기도 너무 좋아요🥹 홍대에서 아사이 맛집 찾아서 자주 올것 같아요!!!', 89, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '맛있어요 베이스 두가지 고를 수 있어서 좋고 원래 코코넛 청크같은걸 별로 안 좋아하는데 슬라이스처럼 조금 커서 식감이 있는덕에 먹기 좋았어요. 제일 작은 사이즈로 배를 채우기는 어렵지만 허기를 달래줄 정도는 되는 것 같아요.', 21, 4, NULL, SYSTIMESTAMP);
