INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '아사이 피타야 시그니처 베이스와 토핑이 너무 조화롭고 듬뿍 들어있어서 너무 만족스러웠습니다!  다른메뉴도 너무 궁금해져서  곧 또 방문할 예정입니다 아사이볼 생각날때마다 올 것 같아요!', 20, 6, 'GOOD', SYSTIMESTAMP);
