INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '이전에 한 번 방문했었다가 날이 더워지면서 시원한게 생각나서 다시 방문했어요! 똑같은 토핑은 2번 추가가 안되길래 혹시나 싶어 요청드렸더니 흔쾌하게 가능하다고 말씀해주셨어요~ 직원분들도 너무 친절하시구 매장도 트여있는 편이라 쾌적해요! 테이블이 조금 적긴 하지만 배달만 하는 매장들만 보다가 먹고 갈 수 있는 곳이 있어서 좋아요! 더운날 시원하고 맛있게 먹고 갑니다!', 5, 6, 'GOOD', SYSTIMESTAMP);
