INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '아사이볼 베이스 종류도 다양하고 반반으로 선택가능해요. 토핑도 다 건강해서 건강하게 한끼 먹거나 간식으로 먹기에도 좋아서 자주 올것 같습니다', 196, 63, NULL, SYSTIMESTAMP);
