INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '홍대 데이트중에 아사이볼 간판이 보여 먹으러 들어왔어요! 요즘 건강하고 프레쉬한 음식의 대명사처럼 떠오르는 아사이볼이라 기대 많이 하고 왔는데 진짜 너무 맛있더라구요. 오후 햇빛도 뜨거운데 망고베이스로 시원하게 먹으니 너무 기분 좋았습니다. 다음엔 요거트 먹으러 와볼게요ㅎㅎㅎㅎ', 129, 26, 'GOOD', SYSTIMESTAMP);
