INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '새로 오픈한지 얼마안된곳이라  매정에  방문해봤어요! 배달해서 먹어도 맛있엇는데 매장에서는  바로 받아서 먹을 수 있어서 좋아요! 앞으로  자주 올것 같아요!! 키오스크에서  아사이볼 선택하고  토핑 옵션추가 기능이  바로 밑에  있었으면 좋겠어요:)', 89, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '아사이볼 너무너무 좋아하지만 먹을 데가 많지 않아 슬퍼하던 도중 발견한 올루올루💜 맛도 넘 맛있고 토핑도 다양하고 사장님이 친절해요!! 홍대에서 디저트나 아사이볼 가게 찾고 계시다면 추천!', 30, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '아사이볼 좋아하는데 홍대에 생겼다해서 방문했어요 넘 맛있고 예쁘고 s사이즈인데도 양이 많아요🤍 아사이볼 뿐만 어니라 그릭요거트랑 치아씨드도 가득해요 감동🥹', 42, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '그릭요거트 추가가 1500원이던데 한스푼 정도 넣어주시나봐요ㅠ..ㅠ 아사이 시그니처 먹었는데 이돈이면 차라리 오크베리를 갈것 같아요.. 특별히 맛있지는 않고 그냥 아사이볼 맛이에요. 내부 자리가 넉넉하진 않습니다.', 46, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '매장두 아늑하고 무엇보다 넘 침절하셔요~~🥰 토핑도 듬뿍 담아주시고 진짜 맛있는데 건강한 느낌 ㅎㅎ 아사이볼 먹고싶을때마다 자주 올래요 💜', 38, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '맛있어요! 아시아볼 파는 곳이 많이 없어서 지도에서 열심히 검색했는데, 가게도 아기자기하고 종류도 되게 많아요 👍🏻👍🏻 시그니처 추천합니다. 상큼상큼해요!!!', 53, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '빙수만큼시원한데 건강한맛이고 천천히먹어도 물로 녹는일없어서 여름에딱이에요 식사대용도 가능 디저트로도 가능이구요 빙수의 단맛아닌 상큼하고 깔끔한맛 무조건추천요', 121, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '홍대에 새로 생긴 아사이 집! 맛있어요! 신선해요🤤 분위기도 좋고 가볍게 먹고갈 수 있는 맞집인 거 같아요ㅎㅎ 재방문 꼭 하겠습니다 !!', 14, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '가볍게 저녁 먹고 싶은데 홍대에 아사이볼 전문점이 생겼다고 해서 와봤어요. 과일도 신선하고 시원해서 여름에 입맛 없을때 건강하게 한 끼 먹기 좋은 것 같아요!', 30, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '지나가다가 너무 더워서 왔었는데 하와이 생각 나는 맛이네요~!! 종류도 다양하니 미리 고민하고 오세요~!! 잘먹었습니다~~^^', 85, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '드디어 홍대에 좋고 맛있는 아사이 카페 찾았음! 아사이 카페들 대부분 강남, 압구정있는데 거기 까지 가는게 너귀찮아서 이제 홍대쪽에있어서 너무 행복함 ㅠㅠ 여러 아사이볼들도 있고 직접 원하는 아사이볼도 만들수있음! 💜 카페 조금 작은편이지만 스태프분들 친절하고 분위기 좋습니다! 자주 오겠습니다! 올루올루 고고씽! 💜', 2, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '인테리어도 멋지고 주문도 빠르게 할 수 있어서 좋았습니다. 지금까지 먹은 아사이 중에서 여기가 탑이에요!! 너무 맛있어요 ㅎㅎ', 38, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '어제 처음 먹어보고 너무너무 맛있어서 오늘은 동생이랑 엄마랑 같이 와서 먹었어요! 오늘까지 가오픈이여서 다양하게 저렴하게 골라서 먹을수 있어서 너무 좋고 엄마랑 동생 둘다 베이스 자체도 많이 안달아서 위에 같이 먹는 토핑과 잘 어울린다고 했어요! 홍대 또 들릴 일이 있으면 또 올라고요^^', 48, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '요거트 아이스크림에 토핑 추가해서 먹었어요 밀크파우더가 진짜 맛있어요 치즈케익 큐브도 추천합니다 원하는 토핑만 얹어먹을 수 있는게 좋네요', 9, 4, 'GOOD', SYSTIMESTAMP);
