INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '맛은 말할 것도 없이 너무 좋구요ㅠ!! 진짜 너무너무너무 맛있어요ㅠㅠ 메뉴 구성이 정말 알찬 것 같습니다😍 아사이볼 처음 먹어보는 친구와 함께 왔는데 좋은 추억 남기고 가요 자주 올게요 번창하세요🤍🤍!!', 38, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '아사이볼!! 토핑도 아낌없이 주시고 리얼 복숭아 리얼 아사이베리를 갈아줘요!! 토핑이 많아서 다 흘리고 있어요 ㅎㅎ 번창하세요', 27, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '처음 들어가자마자 웃으면서 인사해주셔서 기분 좋았어요! 한가득 담아주셔서 토핑이 위태롭게올라가 있었네요ㅋㅋ 아사이볼 처음인데 맛있고 매장 분위기도 깔끔하고 좋았어요!', 41, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '아사이볼에 빠져있기도 하고 집 근처에 있어서 꼭 방문해보고 싶었던 곳이었는데 너무 맛있어요 땅콩버터랑 너무 잘 어울리고 저는 과일은 빼고 먹었는데 과일이랑 같이 먹으면 맛있을 거 같아요 ! ㅎㅎ', 16, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '올루올루… 맨날 광화문에서 일하다가 배달로만 시켜먹었는데 저희 집 옆에 생겨서 너무 좋아요! 여자친구랑 홍대 데이트중에 있어서 신나라 들어갔는데 역시 제 최애 아사이볼 올루올루인거같아유… 음식사진은 허겁지겁먹느라…  오래오래 장사해주세요! 뷰도 압권이네요 ㅎㅎ', 33, 1, 'GOOD', SYSTIMESTAMP);
