INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '베이스 맛을 못골라서 고민하고 있었는데 직원분이 너무 친절하신 덕에, 베이스를 한 입씩 맛볼 수 있었어요💟😍 감사합니다! 그리구 보통 아사이볼 먹으면 가격에 비해 양이 적은 경우도 많은데, 여기 올루올루는 토핑이 다양할 뿐만 아니라 양도 많아서 엄청 배부르더라구요 ㅎㅎ 베이스도 아사이만 있는게 아니라 여러종류가 있어서 골라먹는 재미도 있어요!🫶🏻', 38, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '아사이볼 넘 좋아하는데 매장이 흔하지 않아서 먹기 쉽지 않았는데 자주 오는 곳에 생겨서 넘 좋아요 🥺 다른데서 먹었을 때보다 가격대비 양도 많고 넘 맛있어요 ✨✨ 오래해주세요 🫶🏻🫶🏻', 38, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '아사이볼을 즇아해서 친구랑 방문했어요! 앞에서 뚝딱뚝딱 만들어주시는데 너무너무 좋았습니다. 매장도 깔끔하고 잔잔한분위기라 맘에들었어요. 맛있게 먹고갑니다 :)', 89, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '금요일 점심, 사람많은 홍대거리 점심먹고 후식으로 뭐를 먹을까 두리번 거리던중 2층에.야자수와 테라스가 있는걸 발견 아사이볼 전문 매장이지만 점심을 먹고와서 스무디로 선택 이미지가 제일.화려한 피넛버터 스무디 선택 혼자 테라스에 앉아 쪽쪽 빨아먹으니 스무디가 참 꼬쏘하이 쳐 쮝이네요 날씨까지 딱 좋아 금상천화네요 모든게 조화로워 낮잠자기전에 스윽 남겨봅니다', 7, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'TERRACE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '제가 아사이볼을 좋아해서 최근에 도장깨기(?)하고 있는데 올루올루는 맛을 반반으로도 할수 있고 토핑도 많이 주셔서 맛도 좋고 기분도 좋네요 ^^ 홍대에 살지는 않지만 가오픈 기간 끝나고도 자주 와야겠어요 ㅎㅎ', 21, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '맛있는 아사이볼 파는 곳 찾기 쉽지 않았는데 여기 너무 맛있어요!!! 베이스랑 토핑이 다양해서 취향대로 골라 먹을 수 있는 점이 좋고 맛있습니다😋😋', 126, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '요즘 아사이볼에 빠져서 자주 사먹고 그랬는데 그동안 먹었던 아사이볼중에 여기가 1등! 양많고 조합해서 먹을수 있어서 너무 좋았다 다음에 또 방문예정ㅎㅎ', 74, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '아사이 볼 원래 좋아해서 자주 먹고 찾아다니는 중인데 ㅎㅎ 여기 건강하면서도 맛있어요! 토핑이 다양해서 원하시는거 골라서 드실 수 있어요 🥣🥣🥣💜', 118, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '라이즈가 먹었다고 해서 궁금했는데요. 진짜 맛있군요,,, 양도 실하고 빨리 나와서 한국인에게 딱이에요. 제대로 된 아사이볼 처음 사먹어봤는데 완전 만족스럽습니다! 다음에 또 먹으러 올게요', 25, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '인테리어도 예쁘고 분위기가 차분해서 너무 좋았어요 먹어본 아사이볼 중에 제일 맛있어서 홍대 올 때마다 들릴 것 같아요 홍대맛집입니당', 73, 11, 'GOOD', SYSTIMESTAMP);
