INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '여름에 하루종일 밖에서 돌아다니느라 넘 지치고 힘들었는데 올루올루 아사이볼 먹고 완전 기운 차렸어요 !! 매장도 쾌적하고 시원해서 좋네요~~~', 8, 7, 'GOOD', SYSTIMESTAMP);
