INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '홍대점 매장은 두번째 방문! 배달이랑 광화문점 방문까지 치면 n번째 방문입니다! 서울에 아사이볼 맛집 다 뒤졌는데, 제기준 여기가 1등입니다. 간만에 홍대 지나가다가 못참고 또 들려버림ㅋ', 9, 0, 'GOOD', SYSTIMESTAMP);
