INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '몇년만에 온 홍대인데 장소도 너무 좋고 맛도 좋고 뷰도 좋고 사장님도 친절히시고 최고네요🍓🍓🍓🩷요즘 기분이 안좋앗는데 기분 좋게 있다 갑니다,, 감사합니다📝', 82, 15, 'GOOD', SYSTIMESTAMP);
