INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '아사이볼 좋아하는데 매장이 별로 없어서 아쉬웠는데 가까운 홍대에 생겨서 좋아요 ㅎㅎ 아사이베이스 당연히 맛있고 그린베이스랑 파타야베이스도 넘 상큼하고 맛있었어요', 28, 0, 'GOOD', SYSTIMESTAMP);
