INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '아사이볼이 너무 먹고싶었는데 홍대에는 없나 찾아보다가 발견하고 와봤어요. 더운 여름에 너무 딱인 간식이네요. 맛있게 잘 먹고 갑니다~!', 114, 25, 'GOOD', SYSTIMESTAMP);
