INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '분위기도 엄청 좋고, 무엇보다 아사이볼 가게 중에 제일 종류가 많은 것 같아요! 밤 9시 즈음 갔는데 사람도 많은 거 보니 확실한 맛집인 것 같습니다', 494, 67, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '요즘 아사이볼에 꽂혔는데 접근성 편한 홍대에 생겨서 좋아요 아사이스위트 먹었는데 상큼달달하니 맛있고 매장에서 먹고 갈 수도 있어서 편해용👍', 130, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '가오픈 기간 덕에 반값으로 먹게 된 아사이볼!! 토핑을 원하는 만큼 다양하게 넣을 수 있는 덕분에 욕망 그득한 아사이볼이 나왔어요. 아사이 베이스는 상콤한 소르베 제질이고 그렇게 단 편은 아니여서 단 토핑을 별도로 추가 안 하시면 건강하게 먹을 수 있을 것 같아요. 사이즈는 미디움으로 시켰는데 사실 혼자 간식용으로 드실 예정이면 스몰도 충분할 것 같아요! 양이 푸짐합니다.', 42, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '귀여운 쇼타로가 맛있다고 강추해서 와봤는데 너무 맛있었어용~~ 막 자극적이지 않고 건강한 디저트맛이랍니당 직원분들도 친절하셨어여!!', 36, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '올루올루 광화문점만 다니다가 홍대에 새로 생겼다길래 냉큼 와봤슴다 매장도 넓고 홍대 메인거리가 통창으로 다 보여서 너무 좋았어요!!♡ 아사이볼은 말모말모 존맛탱♡', 86, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '아사이볼 처음 먹어보는데 합리적인 가격에 알차고 맛있게 잘 먹었습니다~!! 여름에 홍대에서 놀다가 더우면 한 번쯤 먹고 갈만 해요 ☺️', 251, 61, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '길 찾기 되게 편해요 ~! 인터넷에 뜬거 보고 바로 왔는데 배달도 되나봐요 !! 직원분 친절하세요~! 아이스크림은 살짝 물같아서 아쉬웠어요!!', 25, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '아사이볼 좋아해서 많이먹는뎅 올루올루 생겼대서 바로 와봤는데 단골예정임니당⭐️ 직원분 너무 친절하시구~~~ 지금 가오픈기간이라 50퍼이벤트중이여서 가격도 넘착해용ㅎㅎㅎ 마이따', 43, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '아사이볼도 시원하고 맛있고 토핑들도 신선하고 양이 넉넉해요! 사장님도 너무너무 친절하시고 가게 분위기도 깨끗하고 아늑해서 너무 맛있게 먹고 왔습니다!', 12, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '직장이 광화문 근처라 광화문점은 되게 자주 갔었는데, 홍대점 오픈하셨다고 해서 친구랑 홍대 놀러온 김에 생각나서 들렀어요! 홍대점 직원분들도 너무 친절하시고 역시나 맛있어용 ~~', 34, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '광화문점 자주갔었는데 홍대점생겼다길래 방문했습니당 여전히 너무맛있어용❤️❤️❤️ 홍대점만있는 복숭아랑 망고맛 너무좋습니다 ㅎ히히👍', 13, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '올루올루 홍대점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '근처 학원 다니는데 시원하고 맛잇어요!!! 베이스를 반반 고를 수 있고 사장님 친절하셔서 기분도 좋앗고,, 6월인데 딸기가 달고 신선해요. 자주 갈 것 같아요 ㅎㅎ', 29, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 꼬모'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '트리플에스의 박쌤 박소현 생일 축하해! 트리플에스 아기 고양이 김나경 생일 축하해! 네, 소현과 나경의 생일 축하를 위해 방문했습니다. 다른 아이돌 기념일도 보이는 걸 보니 여기는 생일 축하 전문카페인 것 같네요. 멤버를 테마로 한 메뉴도 제공되어 특별한 기분을 제공하는 것은 물론, 멤버들이 기뻐할 사진들도 가득 꾸몄습니다! 만약 아이돌 카페 생축을 하고 싶다면 여기처럼 멤버에 맞는 메뉴도 만들어주고 기념품도 주는 여기가 좋을 것 같아요! 주의! - 주차 공간과 내부가 협소하니 여기 올 때 대중교통을 타고 가벼운 차림으로 오세요. 가방 보관함이 없어요ㅠㅠ 가격 - 홍대의 비싼 물가를 감안하면 적절한 가격입니다.', 76, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 꼬모'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '닭 한마리에 소주 10병 넘게 먹을수 있을꺼같아요 너무 맛있어요 두부김치삼겹두 맛있어요 제육볶음 고기 다먹고 셀프 주먹밥에 소스 비벼먹었는데 너무 맛있어요 고기 다먹구 볶음밥으로 먹어두 맛있을꺼같다는 생각합니다 사장님혼자 요리하시는데 너무 친철하시구 손님 안받으실려구 했는데 받아주셔서 너무 감사합니다 자주는 못오더라두 가끔 갈께용ㅎㅎ 맛있게 잘 먹었습니당❤❤', 77, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 꼬모'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '아무리 아이돌 이벤트 전용카페지만 이렇게 퀄떨어지는곳은 처음봄.. 머신으로 뽑는 커피달라니까 안돼.. 콜드브루 5500원씩받으면서 맛은진짜 역대급노맛.. 시판용 따라파는건 아니죠?ㅋ  500원줘도 안사먹을 싸구려쿠키 3500.. 진짜 이딴식으로 장사할꺼면 접으세요 팬들이 축하한다고 멀리멀리서 찾아와주니까 장사가 당연한줄아나요? 매장 퀄이 좋으면 말도안해요ㅋㅋㅋ 홍대바닥에서 이런정도의 낮은퀄카페는 본적이 없어요ㅋ 화가나고 돈이아깝습니다 여기가실시간에 제발 다른이벤트카페 가시길', 124, 20, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 꼬모'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '좌석이 전혀없음. 메뉴가 너무 적음. 그 적은 메뉴 중에서 핫음료는 아메리카노밖에 없음.....(스팀밀크 기계가 품절됐나요..?ㅎㅎ) 품절됐다고 답변하시는데 가려진메뉴 빼고도 샷내려서 만드는 에스프레소커피류가 하나도 없는게... 당황스러운 이유랍니다..ㅎㅎ! 평균가격 5000원에 물타서 주고, 우유타서 주고, 음료수 따라주고.. 이런메뉴밖에 없음..', 7, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 꼬모'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '카페 이벤트 때문에 갔는데 아이스티 먹고 이게 뭔가 싶었어요 ㅎㅎ ㅠㅜ 진짜 맛이 없고 이걸 4500원 주고 먹어야 한다는 게 놀라움 다 버렸어요 😢😢', 316, 88, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 꼬모'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '공간은 협소하지만 종업원분이 친절하게 응대해주시고, 아기자기하게 전시가 돼있어 기분 좋게 이용할수 있었어요. 이벤트하기 적합한 장소 같고요. 다음 번에 이런 이벤트할때 또 방문하려고요😀👍.', 43, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 꼬모'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '2월 14일 엔시티 재현 생일이어서 카페꼬모에서 생카열었는데 천국이었어요..!! 처음간 저 즈니한테 카페 내부 정말 잘 꾸며져있고 도재정으로 되어있는거 너무 눈호강하고 왔어요🤍🤍', 41, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '먼로'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '합정 예쁜 카페 찾다가 괜찮은 서교동 카페 발견해서 방문해 봤는데 넘 만족스러웠어요😍 벚꽃길에 위치해 있어서 벚꽃시즌에 가면 벚꽃 뷰 장난 아닐 듯!!! 분위기도 힙하고 커피랑 디저트도 다 맛있어요♡ 특히 크로플 짱맛!!! 사장님도 친절하셔서 재방문 의사 200%입니당👍', 45, 9, 'GOOD', SYSTIMESTAMP);
