INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '먼로'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '크로플(디저트)너무 맛있구~ 커피는 카페라떼 시켰는데 👍🏻👍🏻좋아요 굿굿 요거트도 넘 맛있네욤 카페가 너무 이쁘고 화장실도 깨끗 의자와 테이블 높이가 적당하고 편해서 오래있기도좋아여 공부하러와도 괜춘할듯 의자가 아주 이뻐요 3층에 투명한 창이 있어서 바깥보기도 너무 좋고 힐링돼요 ❤️❤️👍🏻👍🏻', 18, 5, 'GOOD', SYSTIMESTAMP);
