INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '먼로'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '크로플 맛집입니다! 달달하니 겉바속촉~!! 너무 맛있었어요 유자에이드도 진하고 청을 사장님께서 직접 담구시나요? 먹어본 유자에이드중 최고였습니다 카페도 조용하고 분위기있네요 ^^ 아이돌행사가 있을때 왔으면 더 좋았을텐데 아쉽네요 ㅠㅠ 다음에 행사있을때 한번 들려보려구용 ^^💕', 81, 12, 'GOOD', SYSTIMESTAMP);
