INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '먼로'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '이벤트 카페 하기에 구조가 아쉬워요...전시공간은 적고 테이블이 너무 많음. 벽이 덕지덕지 지저분해서 포스터 붙여놔도 이쁘지도 않고...음료는 무난했습니다', 34, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '먼로'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '그냥 카페 방문하러 갔는데 아이돌분 생일카페였어요~! 생일카페로 운영될때는 메뉴가 좀 다르니까 생일카페 목적이 아니신분은 평일에 가세요! 에어컨 바람 짱짱 나오니 편해요 ㅎㅎ', 148, 40, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 창천점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '올 여름 참 맛있게 먹고다닌♡ 팥밍 젤라또 파르페를 신촌에서도 맛봤어요~^^ 역시 맛있네요! 👍  입니당♡ 사계절 계속했음 좋겠어요~ㅎㅎ', 70, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 창천점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '헛개리카노 도전해봤는데 니맛도 내맛도 아닌.. 그 어딘가..😅 굳이 다시 마시진 않을거같아요 치즈품은감자빵은 데워먹으니 넘 맛있어요👍🏻', 20, 10, 'BAD', SYSTIMESTAMP);
