INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 창천점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '메가리카노 포장했어요. 사이즈 진짜 커요. 하나 먹으면 하루치 카페인 다 채운 느낌이에요. 직원분들이 많아서 주문하면 빨리 빨리 나와요.', 37, 5, 'GOOD', SYSTIMESTAMP);
