INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 창천점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '날 좋은 가을날 산책할 때마다 메가커피는 우리 칭구,, 산책 필수템이에용ㅋㅋㅋ 쿠폰 사용 편하고 적립도 잘 되고 커피양도 많아서 너무 잘 마시고 있습니다! 메가커피 최고 ♥', 112, 20, 'GOOD', SYSTIMESTAMP);
