INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 창천점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '12/8 4시 반쯤 아이스티랑 마늘 크로크무슈 주문했었습니다. 앞에 주문 많이 밀렸으니 늦게 나오는건 그렇다 쳐도요, 앞 주문 중에 베이커리 메뉴가 하나도 없었던 것 같은데 알바 두분이서 크로크무슈 서로 미루다가 마지막 차례인 제 아이스티 만들 때 되어서야 넣어서 대기시간 몇십분 더 늘리는게 맞나요? 마늘 크로크무슈 재고 소진되어서 일반으로 바꿔드리냐 물어보실 때도 사과 한마디 없으시고 100원 차이라도 차액이 생긴다면 차액 환불해드리냐 물어봐야 하는 것 아닌가요? 저도 서비스직 오래 해봤는데 다시는 가고 싶지 않은 응대네용', 18, 8, 'BAD', SYSTIMESTAMP);
