INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 창천점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '라떼보다 카푸치노가 조으닼ㅋㅋㅋㅋㅋㅋ 우유 거품과 시나몬가루의 조합ㅋㅋㅋㅋ 아메리카노도 좋지만 약간 든든할라면 요론 아이들이 좋움요💕', 19, 8, 'GOOD', SYSTIMESTAMP);
