INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 창천점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '늘 배달로 주문하다가 다른 곳 픽업 주문하면서 같이 픽업 주문했어요! 점심시간 피해서 주문하면 빨리 받을 수 있어요ㅎㅎㅎ (여러분의 시간은 소중하니까요) 늘 직원분들도 친절하시고 커피도 맛있숩니다 가성비 말모🫢', 46, 4, 'GOOD', SYSTIMESTAMP);
