INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 창천점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '동교동 삼거리에 주막보리밥에서 점심식사를 하고 옆에 있는 메가MGC커피 창천점에서 커피타임을 마카롱을 시켜준 미숙언니 짱♥ 수다도 떨면서 즐거운시간을 갖었다.', 22, 8, 'GOOD', SYSTIMESTAMP);
