INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 창천점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '대흥동부터 경의선숲길 걷다가 창천동까지. 그 끝의 메가커피 들러서 한잔 구입에서 목축임. 저녁 즈음이라 한가해보이는 매장이었음.', 16, 10, NULL, SYSTIMESTAMP);
