INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 창천점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '남직원이 휴대폰 만진 손으로 음료 만들고 먹고 가는 건데도 매장용 잔이 아닌 일회용잔에 제공해줍니다 퇴식구에 매장용잔 엄청 쌓여있고 안 치우네요', 18, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 창천점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '금요일 오후 2시쯤 방문했는데 남자분 두분계시는데 유니폼도 아닌거같았고 앞치마도 안한거같았고 손님이 들어가있는줄알았어요 왜 용모단정을 중요시하는지알겠더라는..', 26, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 창천점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '음료 반납하는 선반 정리가 하나도 되어 있지 않고 다 차 있는 상태였고, 그 상태에서 손님들이 컵을 아슬아슬하게 반납하더라고요. 그리고 제가 아래층 선반에 컵 반납하려고 하니 위에 쌓여있던 컵이 떨어지면서 얼굴과 모자, 옷과 신발까지 모두 젖었습니다. 알바생은 저한테 ’괜찮으시냐, 죄송하다, 닦을거 드리냐‘ 이중 ”단 한마디 말도“ 안 하고 멀뚱멀뚱 보고만 있더군요. 덕분에 온몸에 초코인지 뭔지 냄새나는 음료 다 얹고 나왔네요. 교육을 못 받은 건지 알바 그런식으로 하지 마세요, 토요일 오후 5시쯤 근무하는 알바생들. 다신 안 갑니다.', 45, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 창천점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '지인이 체리콕 맛있다고 해서 먹었는데 닥터 페퍼 맛인데, 제게는 너무 달아서 포장해와서 탄산수 더 섞어서 3잔으로 만드니 그 때서야 제 취향에 맞았습니다. 근데, 확실한 건 당 너무 떨어졌을 때에는 그냥 흡수하시면 될 것 같아요. ㅎㅎ', 44, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 창천점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '티라미수 라떼 위에서 부터 먹는데 부드럽고 좋네요. 음료도 즐기고 싶고 티라미수도 가성비 있게 증기고 싶을 때 괜찮을 것 같아요. 그래도 케이크가 땡기면 그냥 티라미수를 드시는게 나아요 ㅎㅎ', 8, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 창천점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '네이버에 22시까지라고 해서 갔는데 음료 주문하고 음료 나오니까 마감 21시라고.. 그럼 음료주문하거나 만들기전에 말씀해주셨으면 더 좋았을텐데.. 그 마저도 20:30분부터 암묵적인 퇴장요구.. 노래 엄청 크게 틀고 노래 부르시던 직원분들.. 알바인지 사장님인지 모르겠지만 카페에 사람이 없던것도 아니고.. 거의 클럽인줄 알았어요.', 75, 13, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 창천점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '커피 받을때 조금 흘려서 죄송하다고,닦으려고 했는데 남자직원분이 제발 제발 아무것도 하지말고 제발 가만히 놔두라고 하셔서 당황했네요 불친절함', 20, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 창천점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '불친절해요 사람이 많은 것도 아니고 키오스크가 안되서 계속 소리울리는데도 본체만체하네요 그렇게 고객 내비둘거면 키오스크를 멀쩡하게 두던지 아니면 고객확인하고 주문을 받아주기가 그게 어렵나요 아니면 음료만 만드는 직원이었던걸까요? 매장밖이랑 안쪽 둘 다 안됐었어요', 3, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 창천점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '올 때마다 핫도그는 무조건 추가 필수!! 콜드브루디카페인 3300원 개꿀띠 양 많고 쵝오👍 메가커피 내줘서 감사해요 사장님 너무 좋아요 행복해여💓 또 올게여💕', 16, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 창천점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '오늘은 잉글리쉬 머핀을 먹었어요! 원래 없었는데 오늘부터 된다고 하네요??? 계란이 폭신폭신 치즈가 잘 녹아져 있어 맛있어여!!! 베이글도 새롭게 업데이트 되었더라구요 다음엔 이거 먹어야쥐~~~~~', 44, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 창천점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '메가커피는 커피 포장만 해봤었는데 매장이 넓어서 너무 좋아요! 테이블도 넓고 자리가 편해서 책 읽으러 오기 좋아요~ 핫도그 처음 시켜봤는데 너무 맛있어요~ 무엇보다 커피맛이 고소하고 신선하네요! 앞으로 자주 올게요🥰', 110, 26, 'GOOD', SYSTIMESTAMP);
