INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 창천점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '평소에 크기가 커서 눈에 보이면 사먹는 곳인데 창천점에서는 일부직원의 태도에 기분이 좋진 않았네요. 일단 처음에 주문메뉴 잘못 입력한 부분에 대해 양해구하며 다시 해주신 부분에 대해서는 충분히 이해합니다. 주문받으면서 미안하다고 하셨고 나오면 자리로 갖다주신다고 하셔서 친절하구나 생각했구요. 주문+나중상황에 대해서는 사진 참고 부탁드립니다. 해당 상황에 대하여 호출한 직원에게 가서 해당 상황을 알렸지만 업무처리한 직원이 휴식시간을 들어가며 아무런 말을 못 들어 본인이 계속 호출한 것이라며 미안하다고 하더라구요. 호출직원도 인수인계받은게 없으니 충분히 그럴 수 있다고 이해는 합니다. 앞으로는 휴식시간을 들어가게 되면 본인이 할 업무에 대해선 단순업무라도 인수인계가 필요하다고 봅니다.', 105, 22, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 창천점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '다들 조용히 공부하거나 노트북작업 하시는데 노래 크기도 너무 크고 과하게 시끄러워요... 정말.. 친구가 듣더니 감주온거냐면서 랩이랑 힙합음악 바꿔가면서 트시는데 노래 소리를 낮춰주시던지 일반 가요를 틀어주시던지 잔잔한거 틀어놔도 괜찮을거같아요', 40, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 창천점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '새로 오픈했다고 해서 가봤는데 알바생 불친절 실화?ㅋㅋ 계산하는데도 실수하고 넘 불친절하네요ㅡㅡ 실수는 할 수 있지만 불친절은 뭐죠…', 2, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '컴포즈커피 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '새로나온 음료 3개를 시켜먹었는데 유자스타카토가 제일 맛있었습니다. 동교점 크다고해서 컴포즈 매장중에 큰편인데 2층 3층 올라갈스록 좁아지는 구조라 그렇게 커보이지는 않아요. 매장이 큰데 키오스크가 하나뿐이라 좀 당황했어요. 직원분들 모두 친절하셔서 음료 맛있게 잘 먹고 갑니다.', 72, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '컴포즈커피 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '8시40분쯤 주문하고 화장실을 이용하였습니다. 마감시간에 대한 안내는 따로 없었고 화장실이용중에 5분전부터 청소해야한다고 사장으로 보이시는 중년 여성분이 화장실 이용중인데 눈치와 핀잔을 계속 주시면서 다른손님이 화장실을 못쓴다고 갑자기 고함치시면서 매장밖으로 내쫓았습니다 이런 쓰레기같은 곳은 가지마시기 바랍니다', 85, 11, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '컴포즈커피 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '초코칩도 1도 없어요ㅠ 민트초코오레오프라페 시켰는데 이게 원래 맞나요??? 초코는 위에 뿌린 초코드리즐뿐인거죠..? 매점바이매점인듯..', 46, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '컴포즈커피 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '당충전 기절이야~더블초코라떼 포장 3500 가격 좋고, 맛도 찐한 초코 넘달 ㅠ 잠 확 깸! 휘핑크림 섞어먹는 건 안좋아하고, 따로 조금 먹고싶어서 휘핑크림 조금 함. 맛있는데 담엔 휘핑 없이 호로록 먹어보려고요! 컴포즈 가성비 최공 가격 오르지마~~', 90, 12, 'GOOD', SYSTIMESTAMP);
