INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '컴포즈커피 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '매장은 엄청 넓어요. 지하도있고 2층도있고. 근데 아인슈페너를 마셨는데 원래 이렇게 한약방냄새같은게 나는게 아닐것같은데… 뭔가 가루든 크림이든 잘못보관해서 다른것과 냄새가 섞인것같아요ㅜ', 1, 8, NULL, SYSTIMESTAMP);
