INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '컴포즈커피 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '허브티를 시켰는데 티백을 뜨거운 물에 따로 우려서 부어주는게 아니고 그냥 얼음물에 넣고 바로 주네요. 2500원짜리 허브향 날까말까한 얼음물 샀네요.', 35, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '컴포즈커피 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '컴포즈 초코라떼를 엄청 좋아해서 생초코라떼 먹었는데 ,, 기대보단 별로에용 ㅠ 초코라떼는 약간 밍밍하고 생초코는 딱딱해서 음료 다마시고 따고 퍼먹어야하는 ... 그냥 원래 마시던 거 마셔야징', 32, 1, NULL, SYSTIMESTAMP);
