INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '컴포즈커피 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '포크..ㅜㅜ 과일포크인가요? 케익 먹기엔 역부족 ㅡㅡ..;; 자허블도 티백도 없고 싱겁습니다. 4800원이면 싼것도 아닌데. 신경좀 써주세여!', 35, 1, 'BAD', SYSTIMESTAMP);
