INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '컴포즈커피 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '아메리카노 시키자마자 과장 안 보태고 10초만에 나오길래 처음에는 의식 못하고 마셨다가 맛 보고 미리 뽑아놓은 오래된 샷 쓰는구나 알았습니다... 다른 지점 애용하다가 여기 와봤는데 아무래도 오래된 샷이다보니 맛도 엄청 다르고요... 텁텁한 맛, 냄새, 오래된 산미맛이 나서 기분 안 좋네요 ㅠ 미리 뽑아놓은샷 쓰지 말아주세요.. 같은 돈내고 누구는 새거먹고 누구는 이상한거 먹고는 좀 이상하지 않나요...', 70, 11, 'BAD', SYSTIMESTAMP);
