INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '컴포즈커피 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '신맛 싫고 쓴맛나는 커피 좋아하는데, 그 어디 중간쯤이에요. 가격대비 나쁘지 않고 양이 많네요. 건물 안에 화장실 있는 거 마음에 듭니다.', 30, 3, 'GOOD', SYSTIMESTAMP);
