INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '컴포즈커피 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '매장에서 마신다고 하니 매장이용이라고 3,000원이 더계산되더라구요 ㅁㄱ커피는 매장이용이든 테이크아웃이든 가격이 같은데 여기는 아니여서 실짝 당황했네요', 4, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '컴포즈커피 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '출근길에 여러번 사먹었었는데 항상 같은 요청사항(음료달게,얼음적게)으로 주문했습니다. 뚜껑부분까지 오는게 정상인데 어느날 갑자기 이런식으로 반 좀 넘게만 오는 양으로 주시더라구요? 그래서 앞머리있고 검정단발 여자직원분한테 이거 음료 내꺼맞냐, 다 따라진거맞냐 양이 왜이러냐 물어보니 얼음적게해달라해서 적게넣구 정량대로 넣었다하시더라구요?? 여기지점에서만 10번넘게 동일한요청으로 녹차라떼만 사먹었는데 한번도 양을 이렇게 준적이 없거든여? 진짜 4-5모금 먹으니까 사라지는양ㅎ너무 어이없어서 본사사이트에도 민원걸었는데 몇개월동안 답도없고,, 직원분 대처도 큰브랜드랑 비교하면 진짜 최악의서비스 본사도 답없는 최악의서비스', 28, 1, 'BAD', SYSTIMESTAMP);
