INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '컴포즈커피 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '층이 많은데 층마다 테이블 수는 많지 않아서 집중하기 좋아 보였어요. 공부하는 분이 많더라고요. 다들 이어폰 끼고 있어서 대화하기도 괜찮았어요.', 74, 17, 'GOOD', SYSTIMESTAMP);
