INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '컴포즈커피 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '층은 높으나 각 층마다 좌석이 많은편은 아니에요! 그래도 무더위에 커피마시면서 잘 쉬고 가요~ 다만 아쉬운건 저는 주말 낮에 방문했었는데 여자 직원분들이 불친절해서 유독 기억에 남는 카페예요', 48, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '컴포즈커피 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '전체적으로 별로 입니다. 매장도 지저분하고 고객 리즈도 맞추지 못하는 곳이여서 추천하지 않습니다. 알바생이 너무 불친절하고 귀찮은티 팍팍내서 기분이 좋지 않았네요… 서비스직인 만큼 적당히 융통성 있고 유도리가 있으면 좋았을텐데 아쉽네요.', 28, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '컴포즈커피 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '가성비짱 이예요. 깊은맛은 아니지만 브랜드커피 맛 이라 나쁘지 않구요~ 1층은 주문하고 윗층으로 올라가면 얘기나누기도 좋고 책읽기도 좋은거 같아요~', 73, 12, 'GOOD', SYSTIMESTAMP);
