INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '컴포즈커피 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '원래도 컴포즈 넘 좋아하는 곳인데 이렇게 홍대에 3층짜리 건물이 있어서 좋네요👍 자리가없어서 아쉬울때도 있지만 나름 매장도 깔끔해서 좋아요', 17, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '컴포즈커피 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '출근길 아침마다 들르는 곳인데, 정말 친절하고 정성스러우셔서 다른 카페는 잘 안가게 되는 것 같아요! 많이 바쁘실텐데도 빠르게 제조해주시고요 :) 맛도 좋습니다 ㅎㅎ', 33, 10, 'GOOD', SYSTIMESTAMP);
