INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '예전에 저장해놓은 카페였는데 우연히 방문하게 되었어요. 사장님께서 정말 친절하시고 커피에 대한 지식이 깊어보이셨어요. 주문한 것도 정말 맛있었고 단골분들이 많으시더라구요. 이런 곳을 알게되어 기쁘네요!! 사장님 번창하세요 :)', 11, 3, 'GOOD', SYSTIMESTAMP);
