INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '단골 언니가 좋아하는 카페! 따라와서 마신 커피 향이 너무 좋아요 향 다 맡아보고 원두 고르고, 그것도 어려워서 취향 플레이버 말하니까 사장님이 친절하게 추천해주셔서 마시고 있어요 사실 드립은 아이스로 하면 향 떨어진다고도 하는데 전혀 그런 것 없이 향긋하고 맛있는 커피 먹고 있고, 생체리가 들어간 파이는 체리와 크림치즈의 조합이 이렇게 좋구나를 새롭게 알려준 것 같아요 내부 색감도 정말 감각 있다는 것과 카페에 사장님이 애정 넘치시는 게 느껴지더라구요 데려와 준 언니 최고🥰', 74, 16, 'GOOD', SYSTIMESTAMP);
