INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '리뷰가 좋아서 왔는데 리뷰를 안 쓸 수 없을 정도로 카페 분위기도 너무 좋고 커피, 디저트도 맛있고 무엇보다 사장님이 정말 친절+세심하시고 카페에 진심이신 것 같아요. 번 나올 때쯤 또 올게요! 서비스로 주신 귤꽃차?도 너무 잘 마셨습니다:)', 18, 3, 'GOOD', SYSTIMESTAMP);
