INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '예전에 롱블랙을 추천해주셔서 복숭아 타르트 결제해놓고 롱블랙은 테이크아웃으로 마셨었는데, 사장님께서 원두에 대한 철학이 있으셔서 그런지 커피도 디저트도 너무 맛있었어요 ! 그래서 다음에 홍대에 오면 아메리카노를 마셔봐야겠다 생각하고 왔어요. 산미 있는 아메리카노를 별로 좋아하지 않는데, 약간 느껴지는 산미가 아메리카노 맛을 더 풍부하게 만들어줘서 산미에 대한 거부감이 하나도 안들고 맛있네요 ☺️', 50, 2, 'GOOD', SYSTIMESTAMP);
