INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '느좋 카페. 커피 경험을 공유할 수 있는 멋진 공간이네요. 원두 큐레이션이 취향저격이고 공간도 우드톤에 창이 많아서 좋아요✨ 슈퍼리치 추천합니다', 66, 18, 'GOOD', SYSTIMESTAMP);
