INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), 'ㅎㅎ오랜만에 온 토커바웃~~~~ 통창이라 밖이 잘보여서 넘 아늑하니 좋아요~ 저녁이라 디카페인 커피 마셧는데 디카페인이 이렇게 맛잇다니~~ 후훗 분위기최고~~ 단골친구 피셜로 칵테일도 넘 맛잇다고해서 엄청고민햇으나 나즁에 날잡고 마시는걸루..!!! 사장님 직업의식 넘 멋잇어여~~ 화이팅!!', 114, 19, 'GOOD', SYSTIMESTAMP);
