INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '이번 ☀️여름☀️ 위클리 디저트~ 청무화과 크림치즈 타르트 나왔습니다👏👏👏 처음 딸기,블루베리,복숭아... 등등 나오는 타르트마다 뿌시고 있지만! 이번 청무화과... 사람들에게 생소 할 수도 있겠지만! 타르트로 만드니깐 이런 맛이 나올줄이야🤤🤤 타르트 안에 들어가 있는⭐️ 수제 무화과청 ⭐️이게 이번 디저트에 킥입니다 꼭 음미 해보시길 그리고! 카페에 오시면 커피 입문자들을 위한 ☕️필터커피 라인업이 줄비했으니 향을 맡아보시고 취향에 맞게 디저트랑 어울리는 커피나 시그니처랑 같이 즐기면 좋을 거 같습니다 안 먹으면 그냥 인생손해....... 여기저기 디저트 꼭 먹어보는 저로서는 단연컨데 토커바웃 디저트는 1등입니다 제발 드셔보세요!!!', 36, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '매력적인 원두의 향과 그 향을 선명하게 느낄 수 있는 커피, 차분하고 무드있는 분위기, 재치있고 센스 넘치시는 친절한 사장님 여태 커피를 즐겨 마셔본 적 없지만 토커바웃 사장님의 커피를 우연히 마셔본 뒤 커피의 매력이 이런 건가 싶은 느낌에 계속 발길이 이끌리는 곳 여러 종류의 커피와 디저트 그리고 음료들을 훌륭한 퀄리티로 경험하고 즐길 수 있어서 너무 좋았습니다.', 43, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '이 카페에 오신다면 무조건 바 자리에 앉는 것을 추천 드립니다!!! 커피를 잘 모르고 즐기지 않는 저도 커피에 굉장한 흥미를 느끼게 되었어요… 이렇게 다양한 블렌딩의 커피가 있다니! 코도 즐겁고 입도 즐거운 경험이었습니다ㅎㅎ 사장님께서 커피 내리시는 퍼포먼스도 구경하는 재미가 있어요! 사장님이 정말 친절하시고 말솜씨도 재밌으시거등요~~ 그동안 왜 안 왔는지 후회가 됩니다.. 앞으로는 더 자주 올게요! 논커피 메뉴도 다 좋으니 커피 안 드시는 분들도 놀러오세요~~', 97, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '디저트다 다 맛있어 보여서 두 개나 시켰습니다🥰 타르트는 그 특유의 바삭한 식감이 살아있어서 좋았고 블루베리가 달았어요! 시나몬번은 계피환장인간에게 딱입니다. 골고루 시나몬이 섞여있어서 향이 진짜 좋아요:) 커피는 시그니처인 너티크림라떼를 시켰는데 꼭... 드셔보십셔 여기는 커피가 찐입니다;; 꼬수워서 술술 들어가고 달달한 커피 좋아하시면 딱 맞아요❤️ 공간도 적당히 조도 낮고 따수워서 재방문 의사 짱많✨️', 40, 1, 'GOOD', SYSTIMESTAMP);
