INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '2층에 있는 매장인데도 다들 잘 찾아서 오시는것 같아요. 케잌 커피 둘다 맛있고 사람들 대화소리로 잔잔한 분위기입니다. 오시면 좋아하실것 같아요', 86, 11, 'GOOD', SYSTIMESTAMP);
