INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '저는 토커바웃 케이크 집에서 즐깁니다 ㅎ ㅡ ㅎ❣️ 홀케이크 예약하면 케이크 각각 포장도 해주셔서 냉동실에 넣어두고 토커바웃 케이크 매일 수혈하고 있어요🫶🏻 고르곤졸라치즈케이크 때문에 근처로 이사가야하나 했는데 홀케이크 포장도 되니 너무 좋습니다❤️ 토커바웃 케이크 좋아하시는 분들 홀케이크로 집에서 즐기셔요 하루하루가 행복해여🙆🏻‍♀️💕', 88, 17, 'GOOD', SYSTIMESTAMP);
