INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '믿고 가는 토커바웃입니다…! 커피도 맛있고 피나콜라다도 처음 시켜보는데 너무 맛있었네요! 근처 오실 일 있으면 꼭 들러보세요!', 8, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '저번에 맛있어서 또 왔어요! 사진은 못 찍어서 재탕이지만..ㅎ 한입 먹어보면 재료 본연의 맛이 조화로워서 정성이 많이 들어간게 바로 느껴졌어요! 그리고 저번보다 더 맛있어진거 같아요!! 얼그레이자몽케이크 얼그레이 잎차를 엄청 오랜 시간 냉침하셨다는데 이건 못 참지.. 돈쭐내드릴게요! 잘 먹었습니다!', 12, 9, 'GOOD', SYSTIMESTAMP);
