INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '다들 아메리카노말고 필터커피 드세요 제발 다양한 원두 향 맡고 직접 고를 수 있어요 원두향 그대로 맛나게 내려주신다구요🥹 쑥향 가득한 모스라떼도 부드럽고 적당히 달달해요 흔한 녹차라떼말고 쑥라떼 추천이요👏🏻👏🏻 디저트는 필수. 거짓말아니고 다 맛있어요 블루베리타르트는 그냥 블루베리 그 자체 수량한정이니 있으면 무조건 드세요', 41, 8, 'GOOD', SYSTIMESTAMP);
