INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '필터커피 처음 먹어봤는데 맛있어요! 사장님도 매우 친절하십니다ㅎㅎ 특히 럼 베이스인 원두로 따뜻한 커피를 먹으니 살짝 꼬냑 같기도 하고 술 같기도 하고? ㅎㅎ 되게 신기하고 맛있네요. 사장님이 커피에 진심이신게 보여요. 홍대 근처 온 김에 들려서 커피한잔 하기 좋습니다!', 12, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '정말 우연히 찾아 들어간 카페 겸 칵테일바입니다. 커피를 지독하게 사랑하는 커피오타쿠 사장님의 원두 설명을 듣는 것 만으로도 너무 재미있어요. 커피도 너무 맛있습니다. 자주가려구요 ㅠㅠ최고', 56, 16, 'GOOD', SYSTIMESTAMP);
