INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '남자친구 첫 휴가 때 우연히 들른 카페인데 사장님도 친절하시고 여유로운 공간이 마음에 들었어요 그리고 얼그레이 아이스티가 맛있어요 굿,,,', 254, 64, 'GOOD', SYSTIMESTAMP);
