INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '이번에도 위클리 스페셜이 나왔다... 신비복숭아🤤 복숭아 처돌이인 저로서는 도저히 참지 못했습니다..! 딸기 타르트 블루베리 타르트 안먹어본 디저트가 없을 정도로 디저트를 다 먹어봤지만 이번 타르트가 디저트부분🍰 1위 챔피언을 등극 했습니다👏👏👏 복숭아가 숙성도 잘돼서 당도가... 오늘은 복숭아 힘으로 버티겠습니다ㅠㅠ 토커바웃 최고', 22, 4, 'GOOD', SYSTIMESTAMP);
