INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '여기 필터 커피 한번 마시고 빠져버린 1인!!! 여기 필터 커피 진짜 향 풍부하고 그냥 맛있어요!! 사장님 친절한 건 말해 뭐해~~✌️ 요즘 같이 금방 사라지는 가게들 많은데 여긴 계~~~속 쭉~~~ 열었으면 좋겠는 카페 중 한 곳🥹 여기 디저트도 짱맛!!!!', 62, 15, 'GOOD', SYSTIMESTAMP);
