INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '역시 필터커피 첫 모금의 임팩트는 여기만한곳이 없는거 같아요 그리고 크림 커피에 크림이 도대체 어떻게 만드신건지 궁금할정도로..👍👍 다른 곳 크림이랑 다른데 이게 사장님의 비법이시겠죠..? 늘 잘 먹고 있습니다 감사합니당🙂‍↕️🙂‍↕️', 99, 23, 'GOOD', SYSTIMESTAMP);
