INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '커알못이었는데 커피에서 이렇게 새롭고 다양한 향이 있을 수 있다는 걸 알았다 🤓 필터커피는 엄청 고급스러운 차 같은 느낌 ☕️ 커피에 진심인 사장님과 적당히 어스름한 조명과 편한 좌석이 맘에든다 !', 34, 9, 'GOOD', SYSTIMESTAMP);
