INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '사장님이 친절해요! 핸드드립에 이 정도로 진심인 분은 처음 봐요 ㅋㅋ 원두 향도 느껴볼 수 있고 시즌에 어울리는 맛도 잘 추천해 주셔서 편하게 먹을 수 있었습니다! 커피들 중에 쓴맛보다는 신맛에 더 집중한 느낌이 났습니다. 커피 드실 때 신맛 좋아하시는 분들께 추천드립니다', 22, 0, 'GOOD', SYSTIMESTAMP);
