INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '필터커피 조아하시면 무조건입니다,,, 원두 종류도 많은데 다 시향해볼 수 있어용. 사장님 넘 친절하시고 재밌으세요😝 다음에 웰치스맛 커피 마시러 올게요🍇', 40, 0, 'GOOD', SYSTIMESTAMP);
