INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '맛있는 핸드드립 + 사장님의 친절 + 파릇파릇한 통창뷰 = 언제 와도 좋은 곳이예요🩷 원두도 친절하게 하나씩 시향할 수 있게 해주시는데 원두 라인업도 다양하고 새로운 원두도 자주 들여오셔서(?) 도장깨기 하는 즐거움이 있어요!!! 중국 운남성에서 나오는 아이스티, 복숭아 향 나는 원두 진짜 여름하고 잘 어울리는 시원하고 상큼향긋한 원두예요🩷 추천추천>_<', 76, 13, 'GOOD', SYSTIMESTAMP);
