INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '드립커피 주문 시 로스팅 원두 5가지 직접 향 맡아서 고를 수 있어서 좋았어요 레몬파운드도 상큼달달하고 맛있어요 잔잔한 분위기라서 이야기하기 좋았어요 다음에도 또 방문할게요 커피 이외에 칵테일도 팔아서 혼술하는 사람도 많았어요', 28, 8, 'GOOD', SYSTIMESTAMP);
