INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '아묻따 강추❤️💜🩵 인스타에만 맨날 태그하다가 네이버리뷰는 첨써봐용 ;) 그동안 사장님이 내려주시는 커피부터 디저트네 취해있느라.. 이제야 끄적끄적 😉 필터커피 사랑하신다면 여기는 무조건! 커피 안다는 사람치고 사장님 내려주시는 커피에 안빠진 사람 없음 😏 제 인생 나만알고싶은카페 1위!!🙌❤️ 웬만한 메뉴 다 먹어봤는데 진심 다..맛있어요! 사장님의 진심이 느껴지는 메뉴들!! 하.. 그리고 사모님이 직접 베이킹 하시는 베이커리는..하.. 말모말모💜 찐이에요 진짜! 시즌?! 마다 바뀌기도 해서 디저트 업뎃은 인스타 확인해보세영!👍', 15, 10, 'GOOD', SYSTIMESTAMP);
