INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '장소가 아늑하고 논알콜 피나콜라다가 맛있었어요!! 아 그리고 제가 LG트윈스를 좋아하는데 사장님도 같은팀 팬이셔서 반가웠습니다 ㅎㅎ 다음에 또 올게요!!', 18, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '매번 디저트 먹으러 갈 때마다 너무 맛있어서 홀케이크도 처음으로 예약해봤네요😋😋 1호 사이즈인데 케이크 내부에도 생블루베리도 꽉꽉 차있고 크림도 너무 맛있어요 가족들도 다들 맛있게 만족하면서 먹었어요~~~', 4, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '토크어바웃은 사랑방같아요 보통 제 기준에는 자꾸 생각나고 음료랑 커피도 맛있고 분위기가 편하고 사장님이 친절한 곳이 오래동안 카페 하시겠다라고 생각이 나는 곳들인데 토크어바웃 카페가 그런 곳이에요 ! 사장님이 전직이 믹솔로지스트셔서 직접 개발한 음료들도 많고 진짜 다 맛있답니다 ...! 디저트도 직접 만드시는걸로 알고 있는데 정말 다 맛있어어요 ㅠㅠㅠㅠㅠ 나중에 케이크를 조각이 아닌 통으로 주문할까 합니다 그리고 여기는 사장님이 진짜 통통 튀셔서 사람 기분 좋게 해주시고 친절하셔요 모두 꼭 와보시길 정말 강추 드립니다 ❤️', 4, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '아메리카노 테이크아웃해서 먹고 . . . 맛있어서 또 들러서 다른 메뉴도 먹어봤는데 밀크티랑 라벤더라떼 둘 다 존맛입니다 향이 확실하고 커피랑도 잘 어울려요 그리고 사장님이 너무 친절하십니다 기분 좋아지는 공간🎵', 9, 10, 'GOOD', SYSTIMESTAMP);
