INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '리뷰를 이벤트하려고 참여하는게 아니라.. 그냥 쓰고싶어서 쓰는건 처음이에요.. 커피 시향부터 티 시향까지 너무 친절하게 재밌게 해주셔서 즐거운 시간이었습니다 :)❤️ 제가 마신 커피는 강릉에서 온 커피인데 향이 아주 강렬하고 상큼하고 향긋해요💕 너무 맛있어서 주말에 또 오려구요!!😋 베이커리류는 아내분께서 직접 만드신다는데, 다이어트때문에 참았지만.. 주말은 치팅데이니까 당근케이크 먹으러 올게요!', 32, 7, 'GOOD', SYSTIMESTAMP);
