INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '저번에 친구랑 오고 좋아서 또 왔어요 사장님이 음료에 진심이시고 직접 만드시는 디저트로 매주 바껴서 강추요 시끄러운 매장도 아니고 항상 여유롭게 대화해야할 때 옵니다 굿굿 강추요', 11, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '커피는 산미가 강한 에티오피아 원두를 사용하시는것 같고 너티크림라떼도 땅콩향이 강하게 나는 것 같았습니다. 일하시는 분들이 친절하셔서 좋았습니다.', 1, 1, NULL, SYSTIMESTAMP);
