INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '바람도 선선하게 불고 커피를 못 마셔서 논 커피 추천해주셨는데 얼그레이 아이스티랑 치즈케이크 너무 궁합이 좋아요ㅠㅠ 다들 치즈케이크 꼭 드샤보셨으면 좋겠어요 사장님도 너무너무 친절합니다 🥰🌸 우연히 방문한 카페인데 만족하고 갑니당', 20, 8, 'GOOD', SYSTIMESTAMP);
