INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '너티크림라떼, 샤케라토, 콜드브루 라벤더라떼, 얼그레이 아이스티 모두모두 너무 맛있어요!! 한적한 시간에 방문했는데 가족끼리 즐겁게 수다떨수있었네요! 사장님도 정말 친절하시고, 매장 인테리어도 너무 멋있어용!!', 3, 9, 'GOOD', SYSTIMESTAMP);
