INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '친구가 커피좋아하는 저에게 여러번 가자고 이야기했는데... 이제서야 왔네요~ 주인 아저씨 완전 프렌들리해서 마음까지 편하게 해주시네요.ㅎ 먼저 커피향으로 자신이 원하는 커피를 찾도록 도와주시는데... 신기하게 코로 자극한 커피를 입으로 먹는 유희가 좋네요. 정성스럽게 내려주시는 커피와 설명이 양념처럼 베어서 먹는 내내 행복했습니다. 유리잔원액과 커피 한잔 주셔서 시작과 마감을 원액으로 하고 마지막에는 얼음 두덩이로 아이스도 즐길수 있게 도와주셨어요. 다음에는 아이스 먹어봐야할듯. 더욱 선명한 맛이~ 고풍스러워요.와우~~~^^ 그리고 주인아저씨 서비스로 후식도 주셨어요♡♡♡ 감쏴합니다.^^~', 0, 9, 'GOOD', SYSTIMESTAMP);
