INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '일단, 커피가 맛있습니다. 디저트를 먹지 않아도 커피만으로도 충분한 곳이에요. 그런데, 디저트도 맛있습니다. 사진이 대체 왜 없는지 모르겠는데 쫀쫀한 비엔나 커피에 시나몬롤 먹으면 너-무 행복하구요💖 시즈널 케이크나 디저트도 맛있어요. 하지만 디저트 품절돼도 실망하지 마세요. 여긴 진짜 커피만 드셔도 또 충분해요. 커피 잘 못 드세요? 다른 음료도 맛있어요. 친철하고 유쾌한 사장님이 커피와 손님들에게 보여주시는 애정이 진짜라서 힐링이 됩니다. 홍대에서 은근히 이렇게 나만의 아지트 같은 느낌의 카페를 찾기가 어려운데 친절한 사장님, 맛있는 커피와 디저트, 여유로운 영업 시간, 깨끗한 매장, 쾌적한 화장실. 빠지는 게 없은데 안가실 이유가 있나요...?', 120, 20, 'GOOD', SYSTIMESTAMP);
