INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '매번 올때마다 디저트가 달라서 너무 좋아요 재료도 아낌없이 쓰시고 이 케이크는 얼그레이 자몽 케이크인데 그냥 자몽 자체도 과즙이 팡팡 너무 맛있는데 얼그레이 시트 이거랑 은은 & 쌉싸름 & 상큼 달콤 조화가 너무 좋아요! 다른데서 못 먹어본 고퀄 디저트랑 커피.. 저만 먹을게요 유명해지지 말아주세요 🤣', 41, 7, 'GOOD', SYSTIMESTAMP);
