INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '커피 맛집이라는 소문 듣고 찾아왔습니당 인테리어가 너무 따뜻하고 커피가 너무 맛있어용!!! 필터커피 원두도 직접 시향해보고 고를수 있고, 추천해주신 운남원두 진짜 처음 먹어보는 맛이에요 넘 꼬숩,,✨🤍 콜드브루 라벤더 라떼도 향긋한 얼그레이 느낌이 나서 넘 맛있어용 디저트도 넘 단거 안좋아하는데 레몬딜티라미수도 세상 상큼하네여 !!! 자주 올래용,,,💖', 61, 16, 'GOOD', SYSTIMESTAMP);
