INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '토커바웃의 가장 큰 매력은… T자형의 바에요. 말 그대로 자연스럽게 대화하며 맛있는 차를 즐길 수 있는 홍대 최애 카페입니다. 커피뿐만 아니라 칵태일 제조도 잘 하시고 시나몬 번, 망고케이크, 호박타르트… 처와 곁들여 먹으면 천국이 따로 없답니아 음악 선곡도 잘 하시고 통창을 통해 보이는 거리 풍경도 일품이에요 혼자 와서도 충분히 분위기 즐길 수 있는 곳이에요.', 89, 13, 'GOOD', SYSTIMESTAMP);
