INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '2번째 방문인데, 사장님 너무 친절하시고 재밌으셔요ㅎㅎ 커피도 너무 맛있고, 비엔나커피 크림이 진짜 맛있어요!! 디저트도 자주 바뀌어서 매번 와도 다른 카페 오는 것처럼 익숙한듯 새로운 느낌을 느낄 수 있을 것 같아요! 점심에 와도 좋구 저녁에 와도 좋을 것 같구, 데이트로 자주 올 것 같아용🥰☺️', 25, 5, 'GOOD', SYSTIMESTAMP);
