INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '토커바웃은 항상 정직한 맛이 장점인것같습니다 메뉴 이름에 들어간 재료의 맛이 정확히 다 느껴져서 재미있어요!! 제 아지트입니다… 사장님의 애정이 담겨 더 즐거운 곳이에요☺️', 38, 1, 'GOOD', SYSTIMESTAMP);
