INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '항상 방문할때마다 맛있게 잘 먹고 있습니다 사진을 깜박해서 전에 마신 음료로 대체하기로~~~ 방문할때 마다 어떤 필터커피 먹을지 설레이는 카페 ㅎㅎ 다음에 또 방문할게요!!', 9, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '사장님께서 너무 친절하시고 커피도 맛있어요 드립커피 선택하기 전 시향 가능해서 좋았어요 ❤️👍🏻 분위기도 좋고 커피맛도 좋은 나만 알고싶은 소중한 카페 🌸', 57, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '오늘도 위클리 스페셜과🍰 함께 돌아온 토커바웃입니다~항상 느끼지만 여기 디저트는 너무 맛있네요🤤 크림이 너무 달지도 않고... 느끼하지도 않은... 남녀노소 누구나 좋아 할 만한 디저트입니다! 커피는 이제 말하는게 입이 아플 정도로 항상 맛있습니다☕️ 홍대나 연남 주변에 오실 일이 있으시면 토커바웃 한번 오셔서 느껴 보시는것도 좋습니다👍', 37, 10, 'GOOD', SYSTIMESTAMP);
