INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '인테리어도 예쁘고 사장님이 너무너무 친절하고 음료까지 맛있기까지 어려운데 여긴 그걸 해냅니다…👍👍👍👍👍 친구 추천 받고 왔는데 너무 맛있어요 ㅎㅎ', 50, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '사장님 왕친절 음료도 맛있고 커피도 신선한거 쓰는 것 같아요 원두에서 나는 커피향이 그대로 살아있는 커피는 오랜만이네요!! 피콜로맛집입니당 ㅎㅎ', 87, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '어느 날 걷다가 무작정 들어온 곳인데 커피 종류도 다양하고 원두에 따라 고를 수 있어서 너무 좋았어요!! 사장님도 너무 친절하시고 친근하시고! 그 중 필터 커피가 너무 향도 진하고 진짜 맛있어요!!! 단골 될랍니다~~~!😊 #토커바웃커피브루어스 #토커바웃커피 #필터커피 #핸드드립', 46, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '콜드브루 라벤더 라떼가 너무 맛있어요ㅠㅠㅠ 어디서 먹어도 콜드브루 맛있던적이없는데 여태 먹은 콜드브루중에 제일 맛있어요🫢🫢🫢 케이크는 매번 올때마다 먹는데 항상 너무 맛있습니다.. 그냥 케이크 먹으로만 와도 성공이예요🙈💓 사진도 너무 잘나와서 날씨 따듯해지면 프사 바꿀겸 또오려구용🌸🫶🏻🥹', 34, 0, 'GOOD', SYSTIMESTAMP);
