INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '음료 너무 특색 있고 맛있어요~! 사장님 입담이 너무 재미나답니다~~! 대화하기 좋은 분위기예요. 마지막 카피바라 인형 사장님이랑 너무 닮았어용^^', 55, 14, NULL, SYSTIMESTAMP);
