INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '사장님이 친절하십니다. 다양한 종류의 원두를 음향할수 있으며 이를 토대로 맛있는 커피를 즐길수 있습니다. 잔을 주시는 방식 테이크 아웃 방식이 매력적인 부분입니다.', 9, 8, NULL, SYSTIMESTAMP);
