INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '사장님의 응대가 너무 좋아서 N년 째 가고 있어요 ㅎㅎ 매번 기억해주시고 갈때마다 맛있는 음료와 디저트가 있어서 다 먹어보고 싶게 만들어요~~ 특히 사모님이 직접 만드시는 디저트가 취향저격~!!! 이번에 새로 나온 아이리쉬 커피도 먹어봤는데 요즘같이 추운날 정말 잘 어울리는 것 같아요. 최고최고~~~!!!!!', 27, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '홍대 최애 카페여용,, 언제 가도 사장님 너무 친절하시구 사모님이 만드셨다는 시나몬번은 따끈 달콤하니 천국의 맛이에욘 ♥♥♥♥ 필터커피가 정말 맛있고 다양하니까 커피 좋아하시는 분들은 꼭 경험해보세요! 근데 필터 말고 그냥 아메리카노도 다른 카페랑은 다르답니다… 너어무 맛있어요 사장님 꼭 오래 영업해주시길 ꒰՞⸝⸝•̀𖥦•́꒱و ̖́- ♥', 48, 3, 'GOOD', SYSTIMESTAMP);
