INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '맛보느라 맛있어서 또먹느라 먹으면서 또주문하느라 리뷰쓸사진하나 없어서 빈잔들만 찍어올려버린 너무 맛있고 사장님 바이브도 너무 좋으시고, esfp최고 🤣ㅋㅋㅋ', 85, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '커피맛집,, 디저트맛집,, 나만의 아지트 발견🥹🥹 사장님이 달콤하고, 커피/디저트가 친절한 곳🙊 커피에 문외한임에도 불구하고  커피는 다르다는게 느껴져요 커피에 진심이신 분들이 오신다면 더 감동일듯!!! 디저트는 말모.. 모든 조각케이크들이 너무 맛있지만 >>고르곤졸라치즈케이크<< 원픽추천입니다👍👍 어디서도 먹어보지 못한 풍미깊은 치케🥲💕 처음엔 동네 카페 오는 가벼운 마음으로 찾았는데 n회차 방문 예약입니다,,~~~ 저 계속 오고싶어요~~ 번창하세요 사장님~~~♡♡', 88, 18, 'GOOD', SYSTIMESTAMP);
