INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '커피랑 디저트 그리고 칵테일 ! 다 특별하고 너무 맛있어요. 디저트 메뉴가 종종 바뀌는게 매력적이에요. 당근케이크 맛잇었는데 앞으로 뭐 만들어 주실지 기대가 돼요! 사장님께서 너무 유쾌하시고 귀엽게 서비스 해 주셔서 방문할때마다 웃고 힐링하고 가요. 멀리 있지만 아지트로 삼고 싶은 곳, 좋아하는 사람들 대려가고 싶은곳 이에요! 오래오래 커피 내려주세요 💗💗', 20, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '너무 맛있어서 허겁지겁 먹었네요.. ㅎㅎ 항상 올때마다 사장님이 친절하셔서 너무 기분좋아지는 카페에용 사장님이 차도 서비스로 줬는데 맛나용😁', 94, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '차 향도 다 맡아볼 수 있게 해주셔서 제일 향좋은걸로 골랐습니다>< 커피도 평소 먹던 맛과 색다른 맛으로 넘  맛있어요ㅠㅠ❤️❤️ 디저트도 하나하나 다 입에서 살살 녹네욥! 또 올게요!!!!', 19, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '유쾌하고 친절하신 사장님에 혼자 멍때리며 횡단보도 멍~ 핸폰도 하고 작업하기도 좋은 거 같아요 분위기가 넘 좋아서 저녁 술한잔 하기도 좋을 듯. 필터커피 8천~만원정도인거 같고 아메 맛도 좋아요 단골손님 많은 사랑방', 7, 10, 'GOOD', SYSTIMESTAMP);
