INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '시그니처 커피인 너티라테는 너무 고소하고 달달해서 넘 맛있었구 모스라테는 쑥 맛이 진하고 향긋했어요 ㅎㅎ 그리고 티랑 블루베리 케잌도 넘 맛있게 잘 먹었습니다:)', 200, 39, 'GOOD', SYSTIMESTAMP);
