INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '혼카페 하러 왔다가 힐링 만땅 하고 갑니다 🫧💗 인테리어도 너무 예쁘고, 좌석도 생각보다 많고 편안하고, 재즈나 팝 위주의 음악이 나오는데 완전 취향 저격 당했답니다 .. 🫠 너티크림라떼가 시그니처라 마시고는 싶은데 너무 달까봐 걱정되어 사장님께 여쭤봤는데, 많이 달지 않다고 하셔서 믿고 주문했어요. 컵 입구에 묻어있는 설탕과 크림, 커피가 아주 조화로워 고소하고 맛있습니다 .. 🫶🏻 너무 맛있어서 순삭될 것 같아 아껴먹었어요. 사실 술을 마시고 싶었는데 저녁 약속이 있어 아쉬운대로 커피를 마신건데, 다음엔 꼭 바에 앉아 술을 마시러 오겠습니다 😎 사장님 정말 친절하시고, 뷰도 좋아서 멍때리기도 좋아요 ㅎㅎ', 16, 1, 'GOOD', SYSTIMESTAMP);
