INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '오늘은 위클리 스페셜 디저트로 딸기 초코 케이크🍰가 나왔다는 소문을 듣고 찾아왔지만 역시나 믿고 먹을 수 있는 퀄리티 입니다 저번 위클리는 블루베리 케이크 였지만 못 먹어서 너무 아쉽습니다ㅠㅠ🥲 항상 이렇게 직접 좋은 재료들만 선정해서 건강한 디저트를 만드시는 모습을 보면 저도 제과제빵을 배워보고 사람들에서 먹는 즐거움을 전달하고 싶다는 생각이 듭니다!👍 한번 방문해서 디저트랑 어울리는 음료를 추천받고 함께 즐겨보세요!', 112, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '남편이 발마사지 받는거 기다리는동안 커피나 한잔 할랬는데 같은 건물이 마침 카페가 잇어서 들어간거였는데 존맛집일줄이야..😍 보물섬 발견한 기분 ㅎㅎ 필터커피 주문하니 원두통 싹다 열어서 직접 향맡아보고 원두 고르게 해주시는거 너무 좋구요, 원두 고르고나니 어디어디 사장님의 무슨 원두인데 어떤장점이 있다, 다음에 지역여행가시면 들려보셔라ㅡ이런 멘트까지ㅋ 커피맛이 일단 너무 끝내줬구요, 중간에 얼음 녹으니 두알정도 더 넣어주시고ㅎ 처음부터 끝까지 맛있고 일정한 커피맛을 느낄수 있도록 계속 신경써주시더라구요. 이런 세심함 너무 좋아요👍 콤파냐도 추가주문했는데 얘도 끝장나는맛ㅋㅋ 아 부산이 아닌게 너무 슬픔ㅠㅠ', 47, 10, 'GOOD', SYSTIMESTAMP);
