INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '늘 유쾌하고 긍정적인 사장님과 예쁘고 맛있는 음료들, 그리고 어마무시한 커피 라인업이 늘 있는 분위기좋은 카페 겸 바인 토커바웃! 오늘도 행복해진 기분 잔뜩 느끼고 갑니다 :D', 59, 17, 'GOOD', SYSTIMESTAMP);
