INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '비엔나커피 파는 곳 별로 없어서 시켜봤는데 넘 맛있어요 크림 왕 쫀!쫀! 사장님도 너무너무 친절하시구.. 친절하시다는 리뷰 보고 왔지만 생각보다 더 더ㅓ 친절하셔서 기분이 좋아요💕 카페 분위기도 좋구.. 주말 홍대 사람 너무 많아서 지치는데 힐링하고 갑니다😚 다들 카페갈거면 여기로 오세요 다른데 사람 너무많고 시끄러움', 32, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '토커바웃에서만 즐길 수 있는 오리지널 샤케라또와 토커바웃만의 주말만 나오는 시나몬번 다른 곳에서 맛보지 못한 쫀득한 반죽 그 어느보다 시나몬번이 압도적으로 맛있고 카페 이름 답게 스몰 토크를 즐길 수 있습니다 혼자 오셔도 괜찮고 친구나 연인을 데려오면 사장님의 퍼포먼스도 구경 할 수 있고 사장님 세심한 배려와 디테일을 하나씩 찾아보는 재미도 있습니다 필터커피도 다양한 원두를 향을 맡고 고를 수 있기 때문에 커피의 진심인 분들도 오시는 걸 추천드립니다 밤 낮 관계없이 칵테일도 마실 수 있습니다.', 54, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '친구랑 같이 왔는데 사장님도 너무 친절하시구.. 가게 분위기도 넘 좋아서 또 방문할 것 같습니다! 그리고 조금씩 내주신 차도 넘 맛있어요🥹 또 방문하겠습니다!', 394, 44, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '남자친구랑 꼭 와보고싶어서 또 왔어요! 2층의 통유리도 너뮤 멋잇고 라떼랑 피나콜라다 너뮤 맛잇네요 ㅠㅠ ㅠㅠ파인애플맛뒤에 올라오는 코코넛맛.. 피넛라떼의.크림도 너뮤맛잇습니다 ........진짜 좋아요 홍대와서 안오면 후회할듯요', 36, 5, 'GOOD', SYSTIMESTAMP);
