INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '오트라떼 마셨는데 커피도 맛있고 무엇보다 채광이 잘 들어서 창밖풍경이 너무 예뻐요💛 메뉴 다양하던데 다음에는 다른 메뉴도 시도해보려고요 잘 쉬었다 갑니당!', 0, 2, 'GOOD', SYSTIMESTAMP);
