INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '친구랑 한 번 와보고 커피가 넘 맛있고 분위기가 넘 좋았어서 혼자 재방문했어욤! 제가 디카페인 주문하려고하니 사장님께서 신메뉴 판매 고민 중이라고 하시며 ⭐️디카페인콜드브루라떼⭐️를 알려주셔서 맛보았는데 이거 왜 안파시는지....? 저 이거 마시러 또 와야하니까 제발 팔아주시길ㅠ 디카페인에 커피향 많이 나고 깔끔한 라떼 찾기 진짜 힘든데(유럽에서도 못찾음;) 드디어 찾아서 넘 행복쓰,, 라떼러버 친구 데리고 또 올것!ㅋ', 62, 17, 'GOOD', SYSTIMESTAMP);
