INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '근처 핸드드립 커피 찾다가 우연히 보고 오게 되었는데 넘 잘한일 같아요ㅎㅎ 사장님 친절하시구 커피 얘기도 편하게 많이 물어보고 이야기 나눌수 있어서 재밌었어요! 플랫화이트도 맛있었구 코스타리카 필터커피도 추가로 추문했는데 은은하니 좋습니다👍 바 자리에 앉아서 사장님이랑 얘기하면서 필터커피 내리는 거 구경했는데 이게 은근 힐링타임이에요ㅋㅋ 커피 마시면서 사장님이랑 스몰톡 하고싶으신 분 강추할게용- 전 mbti I 인데도 편했어요ㅋㅋㅋ 2층에서 보이는 뷰도 말모말모-! 너티크림라떼가 맛있다는 리뷰가 많던데 담에 마셔봐야겠어요ㅎㅎ 또 올게용 :)', 40, 7, 'GOOD', SYSTIMESTAMP);
