INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '커피랑 디저트가 너무 맛있어요!! 분위기도 너무 좋고 인테리어 하나하나 신경쓰신게 보여요 :) 무엇보다 사장님이 너무 친절하셔서 강추합니당!! 또올게요😊', 50, 1, 'GOOD', SYSTIMESTAMP);
