INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '사장님 커피 전문가! 아내분은 디저트 전문가! 슈톨렌 난리나ㅠㅠㅠ 커피 금방 다마시고 친구랑 얘기하며 있었는데 친절하게 티까지 챙겨주십니다🥺🥺👍🏻🩵✨ 넘 친절하세요 연남가면 또 갈거에욥!!!', 4, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '근처 볼일이 있어 급하게 찾아 처음 가본곳. 입구에 맞이해주는 포스터부터 매장 내부 아늑한 분위기와 창문 밖으로 보이는 거리뷰가 마음에 들었습니다. 마침 주말에만 나온다는 좋아하는 시나몬빵과 제일 어울리는 필터커피로 추천해주신 멕시코 원두의 조합이 정말 잘 어우러졌어요. 빵도 너무 맛있고, 커피도 정말 감미로워서 시간만 더 있었으면 계속 음미하고 싶었는데 쫒기듯 나와서 아쉬웠습니다. 다음번 근처 가게되면 꼭 다시 가려고요. 사장님 친절함에 한번 더 웃을 수 있는 토커바웃 추천합니다.', 75, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '칵테일 너무 맛있어용 🍸🍹🍸🍹처음나왔을때 예쁜색이어서 깜짝 놀았어요! 🥰사진에는 없지만 시나몬번도 너무 맛있고 칵테일이랑 위스키랑도 잘 어울리는 디저트였어요! 저만 알고 싶은 칵테일바💕혼자오기도 좋아보여서 나중에 혼자 방문예정입니당 사장님도 너무 친절하셔서 기분좋은 시간 보내고 왔습니다💚', 45, 3, 'GOOD', SYSTIMESTAMP);
