INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '분위기도 좋고 사장님도 친절하시고 무엇보다 커피가 엄청 맛있어요,,,!!!! 바 자리 앉았더니 계속 설명해주시고 보여주셔서 완전 빠져들어서 커피만드는거 구경했어요 필터커피는 몇번 안 마셔봤는데 왜 마시는지 그 매력을 알것같아요', 39, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '연휴에 오픈한 카페찾다가 분위기가 좋아보여서 온건데 웬걸., 제대로 찾았네요 커피나 음료 종류가 다채롭게 구성되어있는것도 좋고, 핸드드립 커피를 내려주시는데 커피뿐만아니라 모든 음료를 제조하실때 엄청 정성스럽게 만드시는걸 바로앞에서 볼수있어서 재밌기도하고 맛도 그만큼 좋습니다!! 사장님 너무 나이스하셔서 되게 기분좋게 시간보낼수있었어요😆 단골이 되고싶어지는 될거같은 카페에요~~ 완전추천합니다👍🏻👍🏻👍🏻👍🏻👍🏻', 49, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '우연히 방문한 곳에서 보물을 찾은 느낌입니다~ 커피를 잘 모르지만 사장님과 커피토크 넘 재밌었고 유익했어요! 나만 알고 싶은 카페…지만 잘 됐으면 좋겠어요ㅎㅎㅎ 다음에 또 올게요!', 84, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '특별한 커피가 있다고해서 찾아가봤습니다. 바테이블에 앉으니 원두향도 맡게해주시고 테이스팅도 정말 다양하게 즐길 수 있게 해주셔서 너무 좋았습니다. 너티크림라떼는 과장없이 이제껏 마신 너티중에 가장 좋았습니다. 이외에도 여러 다른원두, 차향도 시향할 수 있었구요 사장님께서 재미있게 이야기도 많이 해주셔서 커피, 음료를 즐기는 다양한 경험을 할 수 있었습니다. 다음엔 차를 꼭 마셔보고싶네요. 커피와 음료 즐기시는 분들은 꼭 가보셨으면 좋겠습니다👍', 44, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '친절하고 야물딱지게 일하시는 사장님 덕분에 기분 좋은 곳이에요- 비엔나 커피 마셨는데 맛있엇습니다- 통창이라 바깥 보는 재미도 있고 인테리어도 감각적이에요! 담에 또 가고싶은곳 :)', 73, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '홍대로 가게 옮기시고 나서 처음 가게됐는데 인테리어 너무 예쁘고, 커피 맛이야 뭐.. 말이 필요없는 아는맛 이어서 ㅎㅎ너티크림라떼와 럼베럴? 이라는 럼 향이 나는 추천 필터커피를 시켰어요~~사장님께서 바텐더 출신 바리스타 셔서 늘 커피에 진심이시고, 이 카페에 가장 좋은게 필터커피를 추천받거나 직접 향 맡고 고를수 있는게 사장님 만의 인간적인 방법이신거 같아요~ 먹을때마다 감탄이 나오는 너티크림라떼도 다른곳에서는 따라할 수 없는 독보적인 맛이에요~~ 시그니처인 바스크치즈케잌과 시나몬빵?도 너무 맛있고 최고에요!! 다음에 또 놀러갈께요!', 63, 17, 'GOOD', SYSTIMESTAMP);
