INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '일산에서 영업하실때 많이 다녔다가 홍대입구쪽으로 재오픈 하셔서 다녀왔어요. 친절한 사장님 여전하시네요~^-^* 커피도 맛있게 내려주시고 다양한 커피 경험을하게 해주세요~! 한번 가면 2-3시간 사장님이랑 수다떨다 오는 것 같아요ㅋㅋ #홍대입구역카페 찾으신다면 꼭 한번 방문해보세용. 디저트도 엄청 맛있어요!🙂🙂', 20, 9, 'GOOD', SYSTIMESTAMP);
