INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '홍대입구 주변 가볼만한 분위기 좋은 카페☕️ 즉흥으로 방문한 카페인데 차분한 분위기, 친절하신 사장님, 아늑한 카페 인테리어, 맛있는 커피&디저트,,,! 모두 만족스러웠던 곳이에요💗 아아랑 디저트를 시켰는데 세상에 여기 디저트 맛집이었나요..? 바스크치즈케이크(딸기 밀크티맛)랑 시나몬 번 진짜 너무 맛있어요ㅠㅠ 원래 왤컴 드링크로 주셨었다고 했던 차를 한모금씩 맛볼 수 있도록 해주셔서 감사합니다! 홍대입구역 주변에 가신다면 이 카페는 꼬옥 방문해보세요〰️🤍', 60, 13, 'GOOD', SYSTIMESTAMP);
