INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '처음 방문했는데 사장님 덕분에 시간 가는지 모르고 있다 온 거 같아요. 정말 친절하시고 먼저 물어볼 수 있는 편안한 분위기를 만들어주셔서 감사했습니다. 카페 이름처럼 이야기 나누기 좋은 카페였어요. 사장님과 이야기 나누고 싶어 오시는 분들도 계실 거 같아요☺️  필터커피를 주문했는데 취향에 맞게 선택할 수 있도록 원두 소개부터 해주시고 커피도 말할 거 없이 정말 최고였습니다🥺', 13, 8, 'GOOD', SYSTIMESTAMP);
