INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '우연히 처음 방문한 카페인데, 앞으로로 단골이 되고싶은 곳이에요:) 사장님께서 커피와 디저트에 진심이신게 느껴지고, 그만큼 맛도 너무 좋네요! 과하지않은 인테리어에 편안한 분위기라서 친구, 연인과 함께 방문하면 너무 좋을거같네요 앞으로 자주 방뮨하고싶은데 너무 유명해져서 웨이팅하고 사끌시끌해질까봐 걱정? 되지만 잘되었으면 하는 곳이네요! 너무 잘 머무다가갑니다, 앞으로도 계속 계셔주세요◡̈♥', 63, 15, 'GOOD', SYSTIMESTAMP);
