INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '토커바웃 빌리옹 사장님 커피는 언제나 맛있어요👍🏼 일산에 계시다가 홍대로 이전 하셨는데 사장님 커피 먹고싶어서 총총총 들렀다 갑니당 ㅎㅎㅎ 커피도, 인테리어도 여윽시 ㅎㅎ 제가 좋아하는 유자보스🫶🏻 잘마시고 가용!!!', 40, 10, 'GOOD', SYSTIMESTAMP);
