INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '대화에서 이전하고 9개월동안 기다린 시간이 아깝지않은 순간이였습니다. 커피를 잘 몰라도 사장님의 친절한 설명과 섬세한 솜씨가 오늘도 내일도 즐겁게 지내는 원동력이 되는 순간이였네요!', 0, 0, 'GOOD', SYSTIMESTAMP);
