INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '커피: 럼배럴 체리밤 Luxardo 체리와 럼배럴 필터커피의 페어링 세트입니다. 체리의 달큰한 맛이 커피를 쭉 땡기고, 럼배럴의 향을 즐기던 중에 머릿 속에서 체리 맛이 아른거릴 때 쯤 체리를 한입 또 베어물며 마시는 커피입니다. 정신을 차릴 때 쯤 비어있는 커피잔이 아쉽습니다.', 34, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '사장님이 유쾌하고 커피랑 모히또가 맛있어요 원래 이쪽 골목에 다니던 가게들이 오늘 다 휴무여서 리뷰 괜찮은 곳 찾아온건데 깔끔하고 좋아요 여름이 끝나기 전 또 와보고 싶어요!', 77, 12, 'GOOD', SYSTIMESTAMP);
