INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '내부가 넓고 아늑하고 차분히 커피마시기 좋은 분위기입니다. 혼자 조용히 와도, 친구와 수다를 떨어도 불편하지 않을 묘한 편안함이 있는 카페에요. 사장님의 친절함과 엄청난 커피솜씨까지 있으니 홍대입구쪽 일있음 카페는 무조건 여기로 오렵니다.', 2, 6, 'GOOD', SYSTIMESTAMP);
