INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '대체 불가한 카페. 4년만에 최애 카페 리스트 리뉴얼 되었습니다. 커알못이시든 커잘알이시든(저는 커알못입니다만) 방문하시게 되면 에스프레소 머신으로 내리는 커피보다는 드립을 꼭 드셔보세요. 지불한 돈, 지불한 시간, 그 이상을 경험할 수 있는 곳입니다. 조만간, 정말 조만간 엄청 뜰 것 같습니다. 매수 시작~', 7, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '커피와 디저트 페어링이 좋은 곳이에요(물론 따로 먹어도 최고구요!) 홍대입구역과 가까운데 신기하게 차분한 분위기에요ㅎㅎㅎ 대표님의 커피 큐레이션👍🏻 바스크치즈케이크, 구움과자👍🏻👍🏻 활기차고 따듯한 환대가 매력적이에요🤗 정식오픈하시면 칵테일도 준비하신다니 기대됩니다!!', 22, 8, 'GOOD', SYSTIMESTAMP);
