INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '커피도 맛있고, 디저트도 맛있습니다! 항상 잘마시고 잘먹고 갑니다~ 사장님과 이야기 나누는것도 너무 재밋어요ㅎㅎ 이전하시면 꼭 놀러갈께요~ 번창하세요!', 16, 8, 'GOOD', SYSTIMESTAMP);
