INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '여기 넘넘 사랑해용~~~~ 평생 사장님 따라다니고싶음!!! 비엔나 크림최고임.. 두종류 질감으로 생크림 따로 만드는 곳도 첨봣고 겁나 맛잇음.. 디저트 말할것도 없고 갈때마다 밀크티 포장해서 옵니다 ㅋㅋ', 38, 0, 'GOOD', SYSTIMESTAMP);
