INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '쓰고 카페인 충전을 위해 먹는 커피가 아니라 취향을 알아가게 되는 신기한 공간🌈 한잔 한잔 정성스럽게 내어주셔서 감사해요 (๑･◡･)', 49, 5, 'GOOD', SYSTIMESTAMP);
