INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '오늘도 웰컴티에 스트로베리 밀크티도 맛보게 해주셨는데 밀크티 특유의 텁텁함도 없고 입안이 개운한데 깔끔하게 달아서 바로 구매했어요! 커피도 역시 말해 뭐해,, 너무 맛있어요🥹 콜롬비아 디카페인 마셨는데 다른곳에서는 디카페인 드립 맛있다고 느꼈던 적 거의 없었는데 역시 토커바웃 너무 맛있었어요ㅜㅜㅜㅜ 케이크는 시즌 한정 메뉴라 미리 예약하고 가서 먹었어요! 크림이 푸딩처럼 탱글탱글한 식감에 신비복숭아가 제철이라 향도 달달함도 폭발❤️ 커피랑 케이크의 조합 최고였어요ㅠㅠㅠ', 42, 4, 'GOOD', SYSTIMESTAMP);
