INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '지인의 소개로 방문한 곳. 처음 방문했음에도 사장님과 이야기를 나누다 보니 어느덧 몇년간 왔던 곳 같은 느낌을 느낄 수 있습니다. 그동안 즐겨왔던 스페셜티 원두들도 맛있었지만 특별한 커피를 즐기고 싶을때 방문하면 반드시 만족할 수 있을것 같아요. 바텐더 출신의 사장님이시라 주류에 대한 지식과 경험도 많으셔서 대화가 아주 통통 튄답니다~~ 서비스에 대한 많은 이야기들을 함께 나눌 수 있어서 너무나 좋았습니다~~ 자주 올것 같아요^^ 성룡씨 좋은 곳 알려줘서 고마워요!!', 39, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '단골 카페에서 추천받은 일산 커피 맛집이에요!! 매장 분위기도 밝고 깔끔한편이에요! 원두 종류도 다양하고 커피가 정말 맛있어요ㅠㅠㅠ 사장님도 너무 친절하시고 커피에 대해서 많이 알려주셔서 원데이클래스를 듣는 기분이었어요!ㅎㅎㅎ 케이크랑 커피도 너무 잘 어울려서 행복한 시간 보내고 왔어요ㅎㅎ', 75, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '추천받아서 마시러왓다가 너무너무 만족합니다❤️❤️❤️원데이 클래스 온줄 알앗어요 사장님 너무 유쾌하시고 정말 편하게 이야기 하다가왔는데 중요한건 커피가!!!!맛있습니다!!!!!!!! 자주 올게요 사장님 대박나세여!!!!!', 72, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '추천해주신 게이샤 원두로 필터커피 먹었는데 깔끔하고 너무 맛있었어요! 수제밀크티도 메뉴판엔 없지만 주문 받아서 만들어주시는데 강추입니다.. 천연베리홍차로 냉침해서 만들어주셔서 미리 주문해야해요! 베리향이나면서 적당히 달아요!!!! 너무맛있어요..커피도 음료도ㅠ', 9, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '커피맛집으로 방문했는데 알고보니 사장님 토크맛집ㅋㅋㅋㅋ근데 밀크티도 맛도리~~~! 밀크티에서 천연딸기향이 난다구하셨는데 맛보니까 바로 알겠고ㅋㅋㅋ 진쨔 향긋하고 맛있어옹 인생밀크티등극! 이 카페는 여러번 방문해서 다양하게 드셔보셔야함당! 아 그리고 밀크티는 온니 예약주문으로만 판매하시니까 미리 예약하구 가세여!!! 꼭이여 젭알!!!', 49, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '제 최애 카페입니다ᄒᄒ 사장님 친절하시고 유쾌하셔서 길 때마다 기뷴이 좋아요! 커피 맛은 말할 것도 없이 너무 맛있음! 여러분 너티 크림 라테 미쳤어요 크림이 진하고 달콤하고 커피랑 같이 한 모금 먹으면 여기가 천국~~😚 사장님의 커피. 차 내공도 엄청나신 것 같아요 그렇다고 부담스럽지 않고 유쾌하게 쉽게 커피에 대해 이야기해 주시고 좋았습니다 향긋한 웰컴티도 주시는데 감동~ 더 더 유명해져서 많이 찾아오셨으면 좋겠어요 한편으론 넘 유명해져서 내가 못 먹는 거 아닌가 싶은 생각도 들지만 맛있는 집은 돈쭐 나야합니둥!👍 그리고 치즈케이크 꼭 드셔보세요!  치즈케이크 꾸덕꾸덕한 거만 먹어봤는데 치즈가 주룩 크림처럼 부드러운 케이크는 처음입니다! 아껴먹고 싶은 케이쿠입니당!', 47, 9, 'GOOD', SYSTIMESTAMP);
