INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '두 번째 방문! 이번에는 여유롭게 마시고 갈려고 했지만 댕댕이 끌고 와서 테이크아웃 했어요 저번에 마시고 너무 맛있어서 아른아른하더라고요ㅎㅎ 한적한 주택가에 보석 같은 카페입니다✨ 사장님 밝은 에너지에 친절하시고 재밌으셨어요 유자 보스? 요 메뉴가 인기가 많더라고요 다음에 꼭 먹어보는 걸로~', 3, 9, 'GOOD', SYSTIMESTAMP);
