INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '커피 맛있어요!!! 복숭아 향과 맛이 진짜로 나는 필터커피를 첨 먹어봤어요~!!! 너티크림라떼도 맛있고 사장님 진짜 커피에 진심... 그리고 웃기셔요ㅋㅋ‎𐨛 ‎𐨛 ‎𐨛 ‎𐨛 즐거운 대화와 맛있는 커피가 고프시다면 강추..', 50, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '처음와봤어요! 너티크림라떼 진짜 맛있습니다~~ 사장님께서 응대도 기분좋게 잘해주시고요, 웰컴티도 주시고, 재미있으세요ㅋㅋㅋ 다음에 또 찾아오겠습니다~', 45, 5, 'GOOD', SYSTIMESTAMP);
