INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '항상 밝은 분위기에 모든 메뉴가 특별하고 맛있는 카페. 카페인 못먹는 저에게 한잔의 빛같은 곳..디카페인도 넘 맛있고..오트밀도 있어서 넘 좋아요. 치즈케익은 또 얼마나 맛있게요.. 공장형 디저트가 아니라 모두 직접 만드셔서 흔한 맛이 아니라 너무 맛나요 ^^', 17, 9, 'GOOD', SYSTIMESTAMP);
