INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '봄 기운이 느껴지는 토요일 오후에 토커바웃에 갔어요~ 오늘도 반갑게 내주신 웰컴티~  드시던 차라며 나눠주신 향긋 달달한 녹차~ 그리고 추천해주신 커피..저는 커피에 대해서는 잘 모르지만 좋았어요^^ 오늘 아주 예쁜 오렌지색 티셔츠와 비니가 멋져서 사장님 뒷모습 찍어왔어요 집에 오면서 지난번에 사 와서 맛있게 먹었던 치즈케이크 또 사왔네요 이게 요즘 완판 행진중이라는!! 강추합니다!!', 13, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '지나가다가 한번 들러보고 싶었는데 타이밍 안 맞아서 이제야 와봤어요ㅎ 강아지들 때문에 안에 들어가지 못하고 테이크아웃했는데 기다리는 동안 향긋한 웰컴 티를 주셔서 기분도 좋았습니다! 커피는 말할 것도 없이 진하고 부드러워서 눈이 번쩍 뜨이는맛👀 커알못이지만 이건 진짜 맛있는 커피다!라고 느꼈네요 다음에는 매장에서 여유롭게 마셔보고 싶어요ㅎㅎ 그리고 사장님 정말 친절하십니다👍🏻👍🏻', 25, 7, 'GOOD', SYSTIMESTAMP);
