INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '토커바웃커피 덕분에 제 커피취향을 알게 되었고 어떻게 하면 집에서도 커피를 맛있게 내려 마실 수 있을까 고민하다가 조르륵커피클럽 프로그램에 참여하게 되었어요.  너무나 맛난 원두도 맛보고 다양한 방법으로 커피를 내리는 마법을 배웠어요. 정말 친구들도 데리고 가고 싶은 곳이예요. 토커바웃커피는 정말 사랑입니다.', 13, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '지금까지 이런 카페는 없었다. 💥충격💥 !!우리학교앞으로 납치하고싶은 카페 실존!! 단 걸 별로 안 좋아하는데도 인조적이지 않고 적당히 편하게 즐길 수 있는 단맛 위주라서 저도 편하게 먹을 수 있었어요!! 쑥라떼는 그냥먹엇을때보다 우유랑 섞어먹어서 더 적당히 달구 맛있어지더라구요 정말 존맛입니다 ㄹㅇ 밥도둑ㄷㄷ.. 초면의 오타쿠 손님을 멋진 입담으로 잘 받아두셨구 퐁당쇼콜라는 겉바속촉 진심 미.쳤.습.니.다. 디저트를 가르자마자 갈라져나오는 진하고 풍미오지는 쇼콜라들이 진심 입에서 완전 녹구.. 엄청 달지도 않은 주제에 계속 손이 가서 ㄹㅇ 진짜 존맛.이었습니다 쑥라떼랑 같이 먹으니까 살짝 느끼한가 싶었는데 조금 느린 템포로 먹으니까 딱 좋고 맛있엇어요 ㄹㅇ 최고의카페입니다 번창하세요. ❤️❤️', 7, 4, 'GOOD', SYSTIMESTAMP);
