INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '오늘도 늦은 시간에 달콤한 유자보스 한잔으로 마지막 시간까지 일도 즐겁게 입도 즐겁게^^ 정리하는 타이밍이셨는데 기꺼이 시간 더 내서 음료 내주셨어요.', 79, 18, 'GOOD', SYSTIMESTAMP);
