INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '참새가 방앗간 그냥 지나가지 못하듯 발길이 절로 옮겨지는 곳이에요. 추운 토요일. 퇴근길 따뜻하려고 따뜻한 유자보스 받아들고 퇴근했어요. 적당히 달게 따뜻하게 지하철에서 여유롭게 마시면서 잘 퇴근했습니다^^', 32, 7, 'GOOD', SYSTIMESTAMP);
