INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '이번엔 라즈베리 밀크티를 주문했어요. 바쁜 고3 조카가 밀크티를 좋아해서 선물했답니다 대화를 통해 추천 메뉴 새로운 것을 접해서 좋아요', 62, 16, 'GOOD', SYSTIMESTAMP);
