INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '일 하러 가면 꼭 들리는 참새입니다. 오늘은 모스라떼 먹어뵜어요! 기분 졸은 얼음동동 웰컴티까지. 나올 즈음 보니 가족 5분이 저처럼 출근하셨더라고요. 일부러 찾아가볼만한 까페에요~!', 3, 4, 'GOOD', SYSTIMESTAMP);
