INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '커피를 잘 모르지만 토커바웃커피 사장님이 내려주신 드립커피에 반해 35분-40분을 운전해서 마시러 갑니다.  커피에 진심이시고 hospitality 에 진심이신 사장님께 감동하고 그 맛에 또 감동합니다. 그동안 드립커피만 마시다가 넛티크림라떼 처음 마셨는데 너무 맛있어서 기절하는 줄 알았어요. 레몬파운드랑 휘낭시에도 너무 맛있었어요.  집에서도 토커바웃커피 마시고 싶어서 원두도 구입했답니다.  커피를 사랑하시는분들 꼭 가보세요', 22, 2, 'GOOD', SYSTIMESTAMP);
