INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '요즘 핫한 디저트라는 바스크치즈케이크 안에서 치즈가 흘러내려 생크림처럼 부드러워요 와인 마시면서 먹었어요 아이들도 어른들도 모두 좋아할 맛이에요~♡', 69, 16, 'GOOD', SYSTIMESTAMP);
