INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '지인 추전으로 우연히 가게되어 큰 기대는 하지 않았던 카페였지만 계산을 마치고 가게를 나가는 시점에 만족감만이 남게되었다 기다리는 동안 마신 차는 메뉴로 만들어도 될 정도로 더 마시고 싶게 만드는 차였고 초코밀크는 다른 카페들에서 마셨을 때는 제티가 바탕이 되어있다는 인상을 주었던 것과는 달리 첫맛은 초코가 강하게 하여 입안의 달콤함이 퍼지게 해주었고 중간맛은 우유 맛이 주가 되게하여 입안을 헹구는 효과를 줌과 동시에 고소한 맛을 느끼게 해주었다. 끝맛은 다시 초코맛이 주가 되었지만 첫맛보다는 연하여 너무 달콤한 맛이 끝맛일 때는 보통 생기기 마련인 약간 씁쓸한 맛이 전혀 나지 않았으며 오히려 깔끔하게 달콤한 맛으로 한 모금의 마무리를 장식하는 효과를 주었다.', 87, 15, 'GOOD', SYSTIMESTAMP);
