INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '커피만 맛있는줄 알았는데 디저트도 찐맛집 입니다. 즐거운 대화로 이끌어 주시는 유쾌한 주인분 덕분에 더 좋은 분위기예요. 벌써 단골된듯해요. 강추.', 31, 5, 'GOOD', SYSTIMESTAMP);
