INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '시그니쳐 메뉴인 너티크림라떼 강추. 가볍게 곁들일 수 있는 디저트 메뉴들도 맛있고 내가 직접 고른 원두로 내려주는 핸드드립 커피도 맛있다. 성저공원앞 골목안에 있어서 지나치기 쉽지만, 애써 찾아가는 보람이 있다. 커피에 관심있는 사람이라면 누구나 talk about coffee 를 할수있는 곳', 19, 4, 'GOOD', SYSTIMESTAMP);
