INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '무알콜하이볼이 정말 맛있는 카페입니다~ 오늘 포장해와서 치킨이랑 맛있게 먹었어요~ 진짜~~~대박 사장님 진심이 느껴져요 감동입니다~~~^^', 57, 11, 'GOOD', SYSTIMESTAMP);
