INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '친절하고 유쾌하신 사장님과  웰컴티가. 반갑고 기분좋게 한다 오늘은 추운날씨에도  아이스카페라떼로 속을 달래보네요 오늘은 새로 내리신 콜드블루와 밀크티를 시음해보았다 굿굿이었어요 어제가 1주년 이셨는데 축하드리고 맛난커피계속 내려주세요', 76, 11, 'GOOD', SYSTIMESTAMP);
