INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '엄마가 한 번 가보시고 같이 가보자 해서 왔는데 분위기도 그렇고 너무 좋았어요! 이런 분위기의 카페는 처음 와 보았는데 너무 재미있었어요! 커피로 과학 실험을 하는 느낌이었습니다ㅎㅎㅎ 커피 마시면 머리 아파서 안 마시는데 토커바웃 사장님의 커피는 너무 맛있었습니다ㅎㅎㅎ 가게 이름대로 사장님과 토커바웃 할 수 있는 곳이예요!  진짜 너무 만족스럽고 단골되고 싶은 카페입니다!!', 336, 69, 'GOOD', SYSTIMESTAMP);
