INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '너티크림 주문했습니다^^ 부드럽구 고소하구~~증말 맛났어요^^ 성저공원 바로 옆이라 산책하구 커피고파 바로 달려왔네요^^ 커피지식인 사장님도 정말 친절하시네요^^ 굿굿♡', 37, 8, 'GOOD', SYSTIMESTAMP);
