INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '커피가 너무 맛있어요 크림라떼 마시러 여기저기 다 다녀봤는데 토커바웃 너티크림라떼는 진짜 !! 맛있어요  커피에 진심이신 사장님 덕분에 맛있는 커피 마시고 갑니다 고맙습니다', 37, 7, 'GOOD', SYSTIMESTAMP);
