INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '너츠크림라떼 너무 맛있어요! 최근에 마셔본 크림커피중에서 제일 맛있어요. 드립도 맛있고 가격도 착하고 사장님도 친절하시고 섬세하세요 ㅎㅎ 너츠크림라떼 강추입니다!', 58, 13, 'GOOD', SYSTIMESTAMP);
