INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '따뜻한 분위기에 맛있는 커피. 골목길 안에 숨은 보석같은 곳! 처음에 리뷰보고 찾아갔었는데 너무 맛있어서 종종 찾아가요. 서비스와 맛 모두 훌륭합니다!!', 88, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '피나콜라다 완전 맛있어요!! 커피보단 음료를 더 좋아하시는 분들은 꼭 한번 드셔보셔요!! 인위적이지 않고 자연스러운 파인애플맛이라 존맛이에요^^', 71, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '너무 많이 알려지지 않았으면 좋겠네요. 오늘 손님 너무 많이 오니까 사장님이 당황하시네요 ㅋㅋㅋㅋㅋㅋ 여유있게 기다리고 즐기다 가실 수 있는 분들에게 최고의 카페입니다.', 21, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '사장님 왕 친절 ㅎㅎㅎ 가볍게 방문했다가 친구가 되어 버린 기분이에용 사모님이 만드시는 디저트들도 다 맛있고 커피가 일산에서 느끼기 어려운 스페셜티커피 제대로 먹어보고 갑니다 ㅎㅎ 사장님 넘 재밌으세여 ^^', 2, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '한적한 곳에 혜성처럼 나타난 까페입니다. 언제나 밝은 에너지로 웰컴티로 환영을 해주시는데 환대받는 경험이 편안하고 유쾌합니다. 커피도 맛있고 음료도 맛있어요. 사장님께서 무대를 펼쳐놓으시고 티나 커피를 내리는 모든 과정을 여과없이 보여주십니다. 혹시! 맛있는 커피는 당연히 기본이고, 밝은 에너지와 즐겁고 적절한 대화도 원하신다며 언제나 충전하러 가세요! 참. 커피에 대해서 전문가셔서 커피에 대한 이야기 나누셔도 좋으실 것 같아요. 저는 커피 문외한이지만 무엇이든지 새로운 것에 호기심이 있으신 분도 좋겠네요~!', 47, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '매장을 보는 순간 너무 예뻐서 들어가고 싶은 마음이 들어요! 들어서면 사장님이 하나하나 애정들여 고르신 소품이 곳곳에 있습니다. 커피와 차는 사람마다 취향에 맞게 고르게 도와주시고 정성들여 내려주세요. 귀한 대접 받는 느낌입니다ㅎ 커피도 맛있어요~', 225, 70, 'GOOD', SYSTIMESTAMP);
