INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '진짜 맛있어요. 밍밍한 커피, 향없는 쓴 커피, 물잔뜩 섞은 커피나 마시다 여기 커피 마시니 진짜 속이 뻥 뚫리는 느낌! 필터커피도 예술이네요. 필터주문하면 보통 밍밍하게 내린 커피 마셨었는데. 사장님이 진짜 필터 잘 내리세요. 1부터 100까지 맛을 다 뽑아낸 커피입니다. 어디서 맛보기 힘든 커피에요.', 87, 12, 'GOOD', SYSTIMESTAMP);
