INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '우연히 발견한 까페. 아파트 아닌 주택가에서 가능할까 싶은 비싼 가격의 드립이나 완전 색다른 맛의 커피. 원두 시향도 가능. 안 사장님이 매일 구우신다는 베이커리도 수준급', 26, 5, 'GOOD', SYSTIMESTAMP);
