INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '열정 가득하신 사장님의 철학이 돋보이는 커피 즐겁게 마셨고 배웠습니다! 최근 필터 커피에 빠져서 여기저기 마시러 다녔는데 완전 정착했어요ㅎㅎ 제대로된 필터커피 드시고싶으시면 묻지도 따지지도 말고 토커바웃으로 향하세요❗️❗️❗️❗️❗️❗️⭐️', 81, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '매번 갈때마다 기분 좋아지는 곳이예요! 사장님 마인드도 너무 좋으시고 카페에 기본인 커피 자체가 너무 맛있어서 믿고 지인들에게 추천하는 곳이예요! 오늘도 친구 데리고 갔는데 친절하게 설명도해주시고 커피도 맛있게 내려주셔서 엄~~~청 만족했어요!! 친구도 자기 단골될꺼같다고 ㅜㅠ 진짜 오래오래하셨으면 좋겠어요! 사장님 즐겁게 일하시고 많이 버시길 ㅋㅋ  (커피사진은 왜 안찍었지?? ;;스티커로 대체 ㅋㅋ)', 99, 24, 'GOOD', SYSTIMESTAMP);
