INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '너티크림라떼는 말모말모말모~~~~😍❤ 사모님이 구워주신 쿠키에 너티크림찍어먹으면 당충전 100000000% 호랑이 기운이 솟아납니다💪🏼 오늘도 카페인충전 당충전 행복충전 잘하고 갑니다🙌🏻❤️', 68, 17, 'GOOD', SYSTIMESTAMP);
