INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '오늘 드뎌 가보았네요 너티크림라테 너무맛있어요 사장님 마인드가 커피에 애정이 듬뿍듬뿍~ 정성을 다해 내려주시네요~ 웰컴티도 존중받는 느낌입니다', 22, 1, 'GOOD', SYSTIMESTAMP);
