INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '네이버 지도 검색하다가 얻어걸린 𝘫𝘰𝘵 𝘮𝘢𝘵 카페 ....  단골 됨. 커피가 너~무 맛있어요. 커피 좋아하지만, 잘 모르니 이렇게 밖에 표현이 안되네요. 가장 큰 장점은 다양한 원두의 향을 맡아보고 고를 수 있는 것! 커피를 마시기 전 따라 주시는 티의 종류도 매번 바뀌는데 따뜻하고 맛있어요.  많은 카페를 다녀봤지만 바 테이블에 앉아 사장님과 얘기하며 좋은 시간을 보낼 수 있는 곳은 처음이었어요. 음악 얘기를 하기도 하고, 커피 얘기도 하고! 햇빛 좋은 날에는 밖 벤치에 앉아 있었는데 너무 따뜻하고 좋았어요. 쿠키들도 정말 매력있어요. 먹으면 먹을수록 더 먹고 싶은 맛. 크림 추가하면 더 맛나요. 티 종류도(최애 = 피치우롱) 에쏘도 샤케라또도 추천X100! 경험만이 답.🤍', 18, 8, 'GOOD', SYSTIMESTAMP);
