INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '커피랑 쿠키 너무 맛있어요. 너티크림라떼는 먹어본 것 중에 제일 진하고 고소해요. 만드는 모습도 다 보여주셔서 얼마나 정성스럽게 만드는지 보실 수 있어요. 웰컴티로 오렌지홍차도 주셨는데 이것도 너무 맛있네요. 매우 친절하셔서 한참 수다도 떨고왔네요:)', 126, 24, 'GOOD', SYSTIMESTAMP);
