INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '커피보단 음료를 좋아하는데요. 어제 먹어본 피나콜라다가 넘 맛있어서 또 왔어요ㅎㅎ 달달하고 감미로운 시지않은 파인애플맛이에요 학생들이나 커피를 못드시는분들께 강추해요!! 진짜 맛있어요😊 가게 인테리어도 이뻐요!', 9, 0, 'GOOD', SYSTIMESTAMP);
