INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '나만알고싶은카페이면서, 널리널리 소문도 났으면 좋겠는 카페♡ 소중하게 정성으로 내려주신커피 마음까지 행복해지는 마법이 있네요! 사장님 넘 유쾌하고 친절하세요!!!! 덕분에 행복한 티타임이였습니다🥰🥰', 487, 46, 'GOOD', SYSTIMESTAMP);
