INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '집근처에 아주 맘에드는 카페를 발견한거 같아서 기분이 좋네요! 사장님이 이 일을 너무 좋아하시는게 느껴져서 저도 긍정적인 힘을 받게되더라고요!! 너티크림라떼도 굉장히 진득하고 좋았어요! 추천받은 커피도 맛있게 잘마셨습니다', 41, 3, 'GOOD', SYSTIMESTAMP);
