INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '정말 맛있는 커피 찾다가 새로 생긴 곳 같아서 방문했어요. 맛있는 라떼 찾으신다면 여기예요! 향도 좋고 고소한데 맛있는 커피예요! 사장님 성격 너무 쾌활하시고 커피에 진심이신분 같애요! 주시는 음료에 설명이 곁들여지니 음미하고 대접받는 느낌이예요. 자주 올께요:)', 67, 17, 'GOOD', SYSTIMESTAMP);
