INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '분위기에 끌려 들어갔는데, 커피가 정말 맛있어요. 직접구우신 쿠키랑 같이 먹으면 기분이 좋아지더라구요. 웰컴티 주시는건 외국여행가서 호텔에서 대접받는 기분이에요^^', 8, 3, 'GOOD', SYSTIMESTAMP);
