INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '정말 재밌게 커피를 즐길수 있는 곳이에요~! 처음 방문했는데 즐거운 시간 보내다 갑니다 :) 커피도 정말 맛있어서 자주 방문할것 같아요!', 9, 5, 'GOOD', SYSTIMESTAMP);
