INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '키워드를 최대 5개까지 밖에 선택할 수 없어서 마음만큼 더 체크를 못했습니다. 시간 가는 줄 모르고 커피를 즐길 수 있는 곳입니다.', 27, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '커피가 너무 맛있어요. 필터커피 여러곳에서 마셔봤지만 진짜 커피 맛을 있는대로 다 뽑아내신 것 같아요. 좋은 원두로 마진 적게 맛있는 커피 대접한다고 하시더니 진짜 사장님 마인드 제대로이시네요. 편안한 대화와 손님들끼리도 스스럼 없이 어울릴수 있는 분위기가 너무 좋아요.', 44, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '강아지와 함께 방문하였는데 사장님이 넘 친절하시고 행복해보이셨어요! 매장이 아담&아늑해서 햇빛이 잘 들어옵니다. 웰컴티와 커피 모두 맛있는 커피에 진심인 사장님이 계신곳입니다. 또 뵙겠습니다~', 80, 14, 'GOOD', SYSTIMESTAMP);
