INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '사장님께서 친근하게 다가와주셔서 너무 좋았어요! 주문하기 전 커피 향 먼저 맡게 해주셨는데 새로운 경험이었던 것 같아요~!~! 테이블에 앉아서 사장님이랑 이런저런 대화 나누면서 커피를 마시니 더 좋았던 것 같아요 그리고 웰컴티로 따뜻한 히비스커스티를 주셨는데 맛있었어요 매일 달라진다구 하던데 다음에 또 방문해서 다른 티도 먹어보고 싶어요❗️그리고 너트크림 진짜 너무 맛있어요❗️❗️❗️❗️❗️', 29, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '가게에 들어가면 사장님이 작고 우아한 잔에 웰컴티를 담아 주세요. 직접 우린 동백자몽차로 목을 축이고나면 이제 핸드드립으로 마실 원두를 고릅니다. 사장님이 직접 셀렉해서 구입한 로스터리 샵 원두 종류만 열가지가 넘어요. 하나하나 향을 맡으며 설명을 듣고 고심 끝에 원두를 고릅니다. 그리고 신중하게 내린 맛있는 커피를 마십니다.', 18, 6, 'GOOD', SYSTIMESTAMP);
