INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '진짜…. 나만 알고싶은 카페인데 사장님의 행복을 위해 리뷰를..⭐️ 여기 진짜 커피에 진심인곳… 맛있는커피 먹고싶으면 무조건 가는 곳!', 67, 18, 'GOOD', SYSTIMESTAMP);
