INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '사장님 진짜 너무 친절하세요 👍 분위기도 매장에 나오는 음악도 커피랑 잘 어울려요 커피도 취향저격이구요 쿠키와 스콘👍 한보따리 포장해 왔네요 히비스커스음료는 홀짝홀짝 리프레쉬 되는 느낌이었어요😊 자주 방문해야겠어요', 43, 10, 'GOOD', SYSTIMESTAMP);
