INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '토커바웃커피 브루어스'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '칵테일처럼 영롱한 신메뉴 추천이요! 히비스커스와 청량함의 조화는 어디서도 먹어보지못한 맛이였어요🥰 커피도 맛롱! 커피에 관심이 많은데, 드립 내려주실 때 친절하게 설명해주셔서 흥미롭게 들었습니다:))', 11, 4, 'GOOD', SYSTIMESTAMP);
