INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페요아정 홍대점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '역시 홍대는 핫플🥰🥰 요아정이 있다! 친구랑 배불리 저녁을 다먹고 마지막 후식으로 아이스크림으로 결정😋😋🍦 연남점은 포장말고도 좌석이 있어서  매장에서 먹고갈수있다!. 👍👍 웨이팅은 없었고, 요거트아이스크림2인,초코쉘,바나나,꿀,그래놀라로 조합해서 주문!!! 시원하고 달당구리하고 맛도리💞💞 깔끔하게 다 먹고 나왔당♡ 직원분도 친절했고 대화하기도 좋았다~ 역시 요아정 믿고 먹는다♡', 14, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페요아정 홍대점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '요아정 평소에는 비싸서 잘 안먹지만 친구 만나서 오랜만에 먹어보았어요😎딸기랑 골드키위 신선했구요 초코쉘이랑 벌꿀집은 필수조합인 거 같아요😻', 44, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페요아정 홍대점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '첫번째 사진) 내가 주문한 요아정 두번째 사진) 이 점포의 나같은 또다른 사례 세번째 사진) 이 점포의 다른 요아정 네번째 사진) 다른 점포의 요아정 벌꿀집이 4,500원인데 내가 2번째로 시켜보았는데 연희점과 달리 이 점포는 저렇게 먹을 가치도 없을 만큼 500원사이즈에 통일되지 않은 사이즈를 배달시킴. 그리고 이런 사례에 대한 환불이나 미안함따윈 없이 정량이라 말함. 내가 여기 처음 시켜보았다면 그냥 양아치네하고 넘겼겠지만 연희점에서 시켰을 때는 벌꿀집 바 형태로 나왔고 같은 금액에 벌꿀집이 먹기 힘들 정도로 많이 주었는데 여기는 서비스인줄 알았네요.. 내돈주고 먹는건데. 다른 분들은 운 나쁜 한 사람이 되지 않기를..', 21, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페요아정 홍대점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '포장 전문점이라 매장이 엄~~~~~~~~~청 작아요 그 작은 매장에 6-7명의 직원분들이 일을 하고 계신데 문 바로 앞에 냉장고가 있어서 배달 기사님들이 직접 꺼내 가시더라고요 통로도 2명 2팀도 못 들어갈 정도로 좁은데 냉장고까지 입구쪽에 있어서 기사님들 들어오시기도 힘들어보였습니다. 배달로는 시켜먹을만 할 거 같지만 포장은 좀 힘들 거 같아요 매장에서 먹을 수도 없고 근처에 먹을만한 곳도 없어서 땡볕에 돌아다니면서 먹기 힘들더라구요 🥹', 45, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페요아정 홍대점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '요거트 아이스크림을 직접 만드시는지 문앞에 우유가 엄청 많습니다 믿음이 가네요 맛 자체가 인위적이면서 강하지않고 은은하면서 깔끔합니다 벌집꿀을 처음 먹어보는데 아이스크림이랑 같이 먹으니 입안에서 녹으면서 달달해집니다 그레놀라도 고소하고 토핑도 내맘대로 조합해서 먹을 수 있고 좋네요', 74, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페요아정 홍대점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '배달 주문이 너무 많아서 매장 가서 주문하고 기다리기까지 대기 시간이 너무 너무 길어요.. 그리고 정신없어서 계속 계산 실수나고 다음에는 그냥 배달로 먹어야겠어요. 오프라인으로 구매하는건 여간 힘든게 아니네요 ㅜㅜ', 26, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페요아정 홍대점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '가는 길에 달달한 게 먹고파서 슥 들어갔는데.. 서비스로 오레오오즈토핑도 주시고 정말 친절하셔서 너무너무 기분이 좋아진 밤이었어요! 양도 넉넉하게 많고 정말 맛있었습니다(◍•ڡ•◍) 감사해요𖦹𖦹', 6, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페요아정 홍대점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '고기 먹고 와서 늦은 시간에 먹을 수 있는 아이스크림 가게 찾다가 발견했는데 역시 요아정 맛있어요!!! 사장님도 너무 친절하셨어요 막차땜에 급하게 먹느라 사진이 없지만 양도 많았고 서비스도 감사합니다🙇‍♀️ 다음에 근처 가게 되면 또 포장하러 갈게요!!! 번창하세요!!', 71, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페요아정 홍대점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '항상 배달로 시켜먹다가 근처에서 일보고 찾아갔는데 먹고 싶었던 초코쉘 품절. 문제는 직원의 태도. 첨에 초코쉘 없냐고 물어봤을때 대답을 안 해서 또 물어보니 그제서야 코도 안 보일만큼 모자 푹 뒤집어쓰고 빨리 주문하라는 식으로 짜증을 냄. 거기엔 나밖에 없었음. 직원 무서워서 못 가는 집. 사장님, 직원 관리가 필요해보입니다…', 1, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페라래'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '저도 생카로 방문했는데 왠지 생카 전문 카페 같아요ㅋㅋ그래서 가성비가 좋거나 이렇진 않지만 인테리어도 이쁘고 주인 분도 되게 친절하셨어요!', 68, 17, NULL, SYSTIMESTAMP);
