INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페라래'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), 'BTS  지민 생일카페 방문했습니다 아담해서 좋아요 여러가지 음료가 있었으면 하는 아쉬움 음료외엔 먹을수 있는게 없어서 아쉬웠어요', 73, 13, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페라래'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '홍대 골목 아담한 카페입니다 생일카페로 방문했는데 조금 비싼것 같았어요 아메리카노에 쿠키 하나 (매우 얇은 쿠키) 만원이 넘네요 ㅎㅎㅎ', 26, 8, 'BAD', SYSTIMESTAMP);
