INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페라래'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '지나가다 간판이 너무 이뻐 와봤는데 가수분 생일행사가 있더라구요?!! 카페가 너무 아기자기 이쁘고 노래도 좋아서, 커피마시며 앉아있다가 노래 따라부르다보니 저도 팬클럽 된 것 같아요 ㅎㅎ 카페 인테리어 너무 상큼하고 깔끔하고 이쁜 배경도 많아서 담엔 남친이랑 사진 찍으러 와야겠어요 ㅎㅎ', 40, 8, 'GOOD', SYSTIMESTAMP);
