INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페라래'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '자몽에이드 3천원에 너무 저렴하고 맛나요. 카페가 화이트하고 아기자기한 소품과 인테리어에 휴양지 느낌나 힐링가고 갑니다. 네이버리뷰로 받은 크로플도 짱~ 싸장님 음악취향도 굿👍', 45, 9, 'GOOD', SYSTIMESTAMP);
