INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페라래'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '홍대 지나가는 길에 귀여운 그림이 있길래 들어와봤어요~ 새로생겨서 깔끔한것도 있지만 인테리어가 밝고 예뻐요. 아기자기한 소품들까지 정말 취향저격!! 커피도 너무 맛있고 크로플도 짱!!!!!! 너무 잘 쉬다 갑니다 다음에 또 올게요^^ 번창하세요!!', 83, 11, 'GOOD', SYSTIMESTAMP);
