INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페라래'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '일하다가  들어간 새로 생긴  = 카페라래 = 오~~ 들어가자 마자 분위기 깔끔하고 아기자기 넘 예뻐예뻐♡ 다른 카페들이랑 분위기도 다르고 사장님 친절하시구요~ 아몬드라떼는 완전 달콤하고  고소해서 또 생각나요', 47, 10, 'GOOD', SYSTIMESTAMP);
