INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페라래'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '카페가 너무이뻐요!!! 커피도 맛있구 사장님 너무 친절하셔서 좋았어용!!! 화장실도 너무 깨끗하고 좋은향기가 나서 있는동안 힐링하고 왔습니다~', 70, 11, 'GOOD', SYSTIMESTAMP);
