INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오스카 커피부스'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), 'cgv 근처에 이렇게 조용하고 쉬기 좋은 카페가 있었다니…🥺 덕분에 돌아다니느라 빨렸던 기를 충전하고 갑니다☺️ 고를 수 있는 원두도 3가지나 되고, 화장실이 분리되어 있어서 좋았어요 인스타 감성 낭낭해서 의자들이 불편한게 단점이지만…😅 공간 자체가 예뻐서 잠깐 쉬기에는 괜찮았어요! 단호박 푸딩은 처음 먹어봤는데 무스 느낌에 적당히 달달해서 커피랑 먹기 딱이에요ㅎㅎ 꾸덕한 걸 좋아하지 않는 편이라 제 입맛에 잘 맞았어요 커피 자체도 맛있어서 다음에 방문하면 시그니처 커피도 먹어볼려구요~', 31, 10, 'GOOD', SYSTIMESTAMP);
