INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오스카 커피부스'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '오랜만에 홍대에서 깔끔하고 커피와 디저트 맛있는 집 발견함 매장은 홍대에 널린 인스타 갬성보다는 진짜 찐 갬성처럼 일단 들어가자마자 합격 단호박 푸딩 메뉴만 보고 왔는데 커피도 전문적으로 하고 있어서 또 합격 2층이라 카페에 채광도 좋았고 군데군데 자리도 잘 마련되어있어서 기다림 없이 바로 앉을 수 있었지만 자리들이 등받이 없는 자리라 오래 있을 순 없을거 같음 여기 가면 꼭 단호박푸딩을 먹는걸 추천함 크리미한 재질에 단호박 향과 은은한 단맛이 어울러져서 그냥 한접시 바로 순삭했음 이런 갬성 카페 나만 알고싶당', 75, 12, 'GOOD', SYSTIMESTAMP);
