INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오스카 커피부스'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '오늘은 말차라떼 마시려고 했는데 홀린듯이 단호박푸딩을 시켜서 어쩔 수 없이 아메리카노와 먹었습니당 🦦 스트레스가 녹는 맛이여요 🤤', 44, 9, 'GOOD', SYSTIMESTAMP);
