INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오스카 커피부스'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '최근 푸딩에 빠져있는데, 오스카 커피부스의 단호박 푸딩은 생각보다 실험적이라고 느껴지는 디저트였어요🤭 시그니처인 서울 바나나 라떼도 얼음이 적고 바나나 밀크와 커피의 조화가 좋았구요🫶 CGV 예매 했다가 시간이 비어서 들어갔는데 접근성도 좋았고 공간 자체가 트렌디 하고 아늑해서 빗소리 들으며 여유롭게 시간 보내기 좋았습니다', 33, 2, 'GOOD', SYSTIMESTAMP);
