INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오스카 커피부스'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '오랜만에 홍대에 온 김에 들른 카페. 국내 다양한 로스터리의 필터커피를 한자리에서 즐길 수 있어서 커피 마니아라면 꼭 들러볼 만한 곳이에요. 각 원두마다 추천 영화가 함께 적혀 있어, 커피 한 잔과 영화 한 편의 여운을 함께 떠올릴 수 있는 감성적인 요소도 인상적이었어요. 사랑과 영혼은 아직 못본 영화라 밤에 한 번 오늘 마셨던 커피를 마셔보며 찾아봐야겠어요', 51, 14, 'GOOD', SYSTIMESTAMP);
