INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오스카 커피부스'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '인테리어 진짜 이쁘고 곳곳에 디테일이 가득해서 센스있어요 디저트 덕훈데 케이크 너무 맛있어서 감탄했고 치마입은거 보시고 담요까지 챙겨주시는 친절함에 두번 감동받았습니당 치즈케이크 꼭 드세용!!🥺🩷', 34, 6, 'GOOD', SYSTIMESTAMP);
