INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오스카 커피부스'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '한적한 분좋카! 시그니처 피스타치오라떼 맛남! 위에는 고소한 피스타치오 크림+아래는 부라보맛 피스타치오 라떼맛! 근데 여기에 샷 추가해서 먹으면 뭔가 더 맛날 것 같은 느낌!!!', 13, 10, 'GOOD', SYSTIMESTAMP);
