INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오스카 커피부스'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '[오스카 커피부스] 🪄 피스타치오! / 필터커피(페루 타바코나스) ⭐️ 일본에 온듯한 조용한 카페 카페에 딱 들어가면 나는 풀향과 고요함이 매력적💚 예쁜 잔에 담겨 나오는 필터커피의 깔끔함이 좋더라구요~ 피스타치오는 꼭 추천하는 커피인데 달달한 피스타치오 아이스크림 녹인듯한 크림의 쫀득함이 정말 맛있어요!🍦☕️', 18, 7, 'GOOD', SYSTIMESTAMP);
