INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오스카 커피부스'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '1. 너무 더워서 들어간 집 2. 내부는 시원한데, 좌석이 진짜 불편했다. 3. 음료는 나쁘지 않았는데 좌석이 넘 불편했다. 4. 어차피 이렇게 써도 이달의 리뷰어 안줄꺼 알고 있음', 1, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오스카 커피부스'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '따뜻한 볕들 때 오면 정말 조용하고 아늑해요 원두 종류가 많아서 선택의 폭이 넓은게 장점이고, 디저트도 항상 마쉿답니다! 사장님들도 정말 친절하셔서 근처 오면 먼저 생각나요 제 최애 카페 콜마인이 사라진 이후로 떠돌이처럼 다녔는데,, 마음 붙일 카페 하나 생겨서 기뿝니다 🤤', 27, 3, 'GOOD', SYSTIMESTAMP);
