INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오스카 커피부스'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '화요일 12시쯤 방문해서 바나나푸딩과 피스타치오를 주문해서 먹었는데 맛있었습니다 우드톤 내부가 진짜 겨울이랑 찰떡인거 같았습니다 밖에 추운데 안엔 너무 아늑하고 따뜻해서 좋았습니다 그리고 곳곳에 콘센트가 많아 카공하기도 좋습니다!! 재방문의사 무조건 있습니다~!!', 86, 17, 'GOOD', SYSTIMESTAMP);
