INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오스카 커피부스'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '너무 맛있어요..🤍 카페만 이쁜게 아니라 커피도 맛있고 디저트도 맛있고...! 친구랑 와서 대화하기도 좋고 혼자와서 작업하기도 좋을 것 같아서 근처에 살면 맨날 오고싶어요~', 45, 10, 'GOOD', SYSTIMESTAMP);
