INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오스카 커피부스'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '눈앞에 가로수가 있어 너무나 분위기 좋은 곳입니다 그냥 편안해여 전에도 잠시 머무르다 갔는데 계절이 가을로 바뀌니 더욱 좋네요 필터커피가 궁금해서 시켜봤는데 호주에서 사오신 장비로 내려주십니다 르완다 원두로 골랐고 커피내리는 모습도 구경하고 좋았습니다. 나무테이블 적당한 조명 잘 쉬고 갑니다', 10, 3, 'GOOD', SYSTIMESTAMP);
