INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오스카 커피부스'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '연말분위기 낭낭해진 오스카에서 오붓한 시간 보내고 가세요~~ 수다떨기 좋은 인테리어와 맛있는 커피와 케잌까쥐 ㅎㅎ 신메뉴 딸기케익 맛있어요🫶🏻😆', 50, 5, 'GOOD', SYSTIMESTAMP);
