INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오스카 커피부스'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '너무 이쁜 카페..🩷 사장님 두분 다 너무 친절하시고 공간이 너무 좋아요 커피도 맛있고 디저트도 너무 맛있습니다 또올게요!!!', 12, 7, 'GOOD', SYSTIMESTAMP);
