INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오스카 커피부스'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '친구랑 왔다가 너무 좋아서 남자친구 데리고 또 방문!🤍 오늘도 커피 너무 맛있어요 핸드드립 종류가 여러가지라 다 먹어보려면 부지런히 와야해요', 77, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오스카 커피부스'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '5월 말에 카페를 다니며 사진찍는걸 좋아하는 언니의 추천으로 어떤분과 처음 데이트(?)겸 ㅋㅋㅋ 방문하고 앉은 자리에서 혼자 케냐 뚱구리, 화이트 두잔 마시고, 두번째 방문에는 케이크들과 전에 맛있게 마신 화이트 한잔 그리고 같이간 친구는 아아 그리고 오늘 방문은 혼자였는데요 항상 오픈 시간대에 맞춰 가서 고요함 속에 사람들이 하나 둘 자리를 잡는걸 보다 어느새 가득 찰 때면 일어나곤 하는데요 너무나도 귀여운 두분이 주문 받고 커피를 내어 주시는걸 보면 뭔가 기분이 좋아져요 창가에 앉아서 적당히 들어오는 햇빛에 책읽기 좋고, 적당한 조도가 있는 테이블에서 잠시 머물럿다 가는것도 좋네요 오늘도 너무 좋아 글 남겨 봅니다 (여긴 나만 알고싶다)', 8, 10, 'GOOD', SYSTIMESTAMP);
