INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오스카 커피부스'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '디저트도 커피도 너무나 맛있는 곳💓 홍대에 오면 꼭 다녀와요 특히 시그니쳐 피스타치오라떼는 또 먹고싶어요ㅠㅠ 시즌한정 딸기케이크도 추천!!', 20, 5, 'GOOD', SYSTIMESTAMP);
