INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오스카 커피부스'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '영화 좋아하는 사장님이 만드신 곳인가!! 영화관련된 책 많아서 분위기 만끽! 뷰도 좋고 분위기도 좋고 음료도 맛있어서 한참 시간 보내고 나왔답니다. 시그니처 피스타치오! 고소하니 맛이 좋아요!! 망고 스파클링도 매력적으로 달콤하고 맛나서 신이 나네요 ♥', 54, 17, 'GOOD', SYSTIMESTAMP);
