INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오스카 커피부스'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), 'I was torn between "hot" and "iced" because the weather kept telling me I should order iced coffee. So, I ordered iced coffee, but I am the person who orders hot coffee even if it''s 30 degrees Celsius... 🥲✨ They served me both hot and iced ones, which was a very generous gesture. Luckily, I tried both. 차가운거 뜨거운거 둘다 맛있었어요 감사합니다', 44, 1, 'GOOD', SYSTIMESTAMP);
