INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오스카 커피부스'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '오랜만에 홍대에 왔는데 저번에 왔던 카페가 생각나서 또 들렸습니다💛 이번에 디저트 신상이 또 나왔더라구요! 저번에 단호박푸딩이 너무 맛있어서 시켰는데 옥수수치즈케이크라니,,,,진짜 너무 맛있었습니다 치즈케이크랑 옥수수가 어울릴까 했는데 담백하고 오히려 너무 잘어울려서 반했어요,,!🫢 처음 먹어보는 디저트 맛이라서 더 색다르고 이거 먹으러 또 올 것 같아요,,,! 여러분 다들 꼬옥 드셔보세요!!!🌱🌱 여기 진짜 사진, 분위기, 디저트 그리고 커피까지 맛집이에요,,,! 여러분 홍대오면 여기 오세요 친구 연인 그리고 소개팅,,,까지 완벽합니다!👍🏻', 28, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오스카 커피부스'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '홍대 신상카페 <오스카 커피부스> 내부 인테리어가 인테리어 하우스처럼 독특힌 구조를 가지고 있습니다. 밝은 우드톤에 독특한 테이블과 체어 구조가 사진을 찍으면 잘나옵니다. 음료와 디저트도 수준급으로 맛있어서 만족합니다. 홍대 신상카페이면서 sns핫플로 성장할 것 같은 카페입니다.', 41, 10, 'GOOD', SYSTIMESTAMP);
