INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오스카 커피부스'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '홍대입구역 근처 새롭게 오픈을 한 카페 오스카 5월1일부터 3일까지 가오픈 기간으로 운영이 되고 있어서 19:00까지만 단축 운영이 된다고 한다. ( 그 이후로는 22:00 ) 밝은 원목으로 꾸며진 공간 시원하게 뚫린 창으로 들어오는 햇살 멋진 뷰는 아니지만 초록한 풍경 보며 멍 때리기 너무 좋았던 공간 시간이 얼마 없어서 커피만 먹고 나왔는데, 다음에는 디저트도 같이 즐기고 오고 싶은 곳 🍰 더 자세한 정보는 최제로 블로그🙇🏻‍♂️🌼', 49, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오스카 커피부스'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '아이스크림라떼 여름에 마시기 좋습니다! 달달씁쓸시원해요! 아이스크림도 약간 우유아이스크림 느낌이라 좋았어요 피스타치오 라떼 신메뉴라고 추천해주셔서 마셔봤는데 맛있습니다! 단 거 못먹는 친구한테는 조금 달다고 하니 참고하세요! 디저트 종류도 생각보다 다양하고 감성 챙기기 좋은 창가 자리도 있습니다!', 94, 21, 'GOOD', SYSTIMESTAMP);
