INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오스카 커피부스'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '분위기 있는 커피 맛집! 가장 인상 깊었던 건 인테리어와 맛입니다 브랜딩이 잘 되어있다는 느낌을 받았어요 ㆅ 차분하고 분위기 있는 곳을 좋아하는 분이라면 호불호 없이 좋아할 것만 같은 카페입니다! 여기 시그니처 메뉴가 특히나 맛있어서 커피에 진심이신 분들께도 추천 드려요! 사장님도 친절하시고 공간을 즐기기도 좋아서 근처 갈 일 생기면 재방문할 예정입니다 ›  ᴗ  ‹⋆', 0, 0, 'GOOD', SYSTIMESTAMP);
