INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오스카 커피부스'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '홍대 분위기 있는 카페 찾으신다면 오스카 카페 진짜 꼭 가보세요! 분위기 + 향 + 음료 + 디저트 +커피 빠지는 거 하나 없이 모두 만족스러운 카페 입니다! 특히 단호박 푸딩이 있는데 정말,,, 너무 맛있어요! 다른 카페와 차별화 된 디저트가 있어서 디저트 러버들이 찾게될 카페랄까,,,🤎 창도 넓게 있어서 답답하지 않고 무엇보다 카페 분위기가 정말 아늑하면서 모던해서 들어가자마자 우와,, 좋다! 라는 감탄사가 나왔습니다:) 커피를 못 먹는 사람도 먹을 수 있는 에이드가 있는데 이게 진짜 엄청 달지도 않고 맛있어서 너무 좋았습니다! 소개팅도 좋고 친구 만남도 좋으니~! 아! 사진도 잘나와요,,,👍🏻👍🏻👍🏻친절하고 예쁘시고 잘생긴 사장님들이 계시니 꼭 방문해보시길 추천 드립니다🤍', 39, 10, 'GOOD', SYSTIMESTAMP);
