INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오스카 커피부스'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '홍대 커피가 맛있는 플라타너스 뷰 카페🍀 햇살 좋은 5월에 오픈한 오스카커피부스는 마하 건축사무소에서 공간을 설계한 곳으로 밝은 분위기의 우드 톤 인테리어를 엿볼 수 있는 곳. 2인석과 공용테이블로 이루어진 공간, 플라타너스 뷰가 돋보이는 창가 뷰는 최고의 명당으로 홍대 길거리를 관망할 수 있어 창 밖 구경하기에 좋고, 무엇보다 커피가 맛있어서 만족스러웠어요 아이스크림을 활용한 커피부터 필터커피 등 다양한 종류의 커피와 특색있는 케이크까지 커피를 좋아하는 사람들이라면 만족하지 않을 수 없는 카페입니다👍', 49, 4, 'GOOD', SYSTIMESTAMP);
