INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오스카 커피부스'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '쉬는날 연남동 산책하러가는 길에 들렸어요! 사장님도 친절 하시고 공간이 햇살도 잘 들고 이뻐서 잘 쉬다 가요 ㅎㅎ 담에 또 방문하겠습니다!', 16, 8, 'GOOD', SYSTIMESTAMP);
