INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오스카 커피부스'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '홍대에서 좀 조용히 대화할 곳 찾다가 발견했어용 디저트 밀가루 없이 직접 만드신다는데 단호박케이크 넘 맛있;; 원래 성수동에 단호박 케이크 먹으러 갔는데 이제 여기 올라고요;;', 43, 2, 'GOOD', SYSTIMESTAMP);
