INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오스카 커피부스'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '출근길 횡단보도 근처에 공사하길래 계속 눈여겨 보던 카페에요! 카페여서 직장동료들과 오픈 날 맞춰서 약속잡고 방문 했습니다! 블렌딩원두도 있고, 아이스크림 메뉴가 있어서 여름에 다시 방문하고 싶어요~ 그리고 초코 아이스크림 너무 맛있어보여서 꼭 먹어보려고 합니다! 인테리어가 너무 예쁘고 나무기둥 피해서 만든 테이블과 의자도 너무 감성 있었습니다~❤️', 130, 24, 'GOOD', SYSTIMESTAMP);
