INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오스카 커피부스'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '커피랑 디저트 넘 맛있어요! 같이 간 지인이 커피를 실수로 쏟았는데😭 친절하게 대해주셔서 감사했습니다😅😄!! 또 방문할게요!!', 40, 6, 'GOOD', SYSTIMESTAMP);
