INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오스카 커피부스'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '*ㄹㅇ내돈내산 후기* 홍대 간다? 오스카 커피부스 “필수 코스”라고 생각합니다. <디저트 처돌이>인 저의 입맛을 아주 사로잡았으며, 커피부스인 만큼 커피는 두말할 것도 없습니다. 이마 빡빡 치게 만드는 곳입니다 정말로;; 오스카 만의 깔끔한 필터 커피 꼭🙏🏻 디저트는 그냥 종류별로 도장깨기 하시길 바랍니다. 세상에, 이런 푸딩이 존재하나? 싶은 오사카만의 푸딩. 먹교수로서 왜 이제야 알게 된 건지 반성하게 되는 맛.. ✨단호박 푸딩✨제발 드셔보세요ㅠㅠ 아 울음나와 케이크인가? 푸딩인가? 촉촉 카스테라인가? 등등 정말 처음 먹어보는 색다른 맛인데 존맛ㅠ 근데 여기서 더 충격적인 것,💓글루텐 프리💓란다. 이게 말이되나? 아이스크림도 꼭 드세요 +ㄹㅇ사진 맛집 아 할말 넘 많은데 글자수 부족 이슈로 이만;;', 47, 3, 'GOOD', SYSTIMESTAMP);
