INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '오스카 커피부스'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '공간도 이쁘고 커피랑 디저트도 엄청 맛있었어요 사람이 좀 있었는데도 소리가 울리지 않아서 전혀 시끄럽지 않고 잘 쉬었다 갔네요!', 44, 8, 'GOOD', SYSTIMESTAMP);
