INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '최애의 생일 카페가 열려서 방문했어요. 카운터에서 주문 받아주신 카페 사장님이 정말 친절하셔서 기분 좋게 다녀올 수 있었어요. 디저트도 맛있었고 특히 아메리카노가 산미 없는 커피라서 너무 최고였어요. 이벤트가 열리지 않는 날에도 꼭 다시 재방문하고 싶네요. 좋은 카페에서 행복한 추억 만들고 갑니다. 사장님 번창하시길..🫶', 3, 3, 'GOOD', SYSTIMESTAMP);
