INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '친구 생일겸 오랜만에 홍대 갔는데 비가 너무 오더라구요. 하늘에 빵꾸난줄 알았어요,, 진짜 밖에서 그냥 예뻐보이는 카페 들어갔어요. 원래 카페에서 커피 마시는데 음료를 시켰는데,, 진짜 너무 맛있는거에요??? 직접 청을 만드신다고 하시더라구요! 바질 토마토 에이드 강추.. 아망추도 존맛... 사장님 레시피 무엇인가요,,, 넘넘 맛있어요!!! 홍대생일카페나 아이돌 생일카페로 유명한 곳이더군요! 연남동카페로 단골 될 것 같아요♥️ 그리고 사장님이 너무나 최고 우주 친절함에..감동ㅠ 찐 내돈내산 후기입니다...🤓', 86, 18, 'GOOD', SYSTIMESTAMP);
