INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '우와ㅜㅜ 여기 카페 너무 귀엽고 예뻐요,,, 오렌지커피 진짜 진짜 맛있어요,,,!!! 테디베어 케익도 먹기에 아까울정도로 귀여운데 ㅜㅜ 넘 맛잇어요!! 최고!!!!', 2, 5, 'GOOD', SYSTIMESTAMP);
