INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '너무 분위기가 좋아요.. 💛 취향 저격이네요.. 힐링이 되는것 같아용 ~!~!~! 아망추도 너무 맛있고 디저트는 달달하니 너무 맛있어요 ❗️❗️ 홍대에 이런 귀여운 카페가 있었다니 !!! 다음에 또와야겠어용 🥰', 6, 4, 'GOOD', SYSTIMESTAMP);
