INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '먼저 이렇게 친절하신 사장님을 뵌 적이 없어요… 진짜 친절하세요 🥹🥹 테디 쇼콜라 케이크 귀엽고 맛있고.. 바질 토마토 에이드도 상큼달달해서 너무 좋았어요! 아아도 고소한 편이라 디저트랑 궁합좋아요..! 생일 이벤트 카페로도 유명해서 그런지 카페에 볼거리가 많더라구요! 굿즈같은것들..!! 안에 있던 숍인숍 악세서리 브랜드도 너무 이뻤어요! 잘 쉬다 갑니다 ❣️', 122, 21, 'GOOD', SYSTIMESTAMP);
