INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '홍대입구에 조용하고 아늑한 카페 발견! 감성인간 감성충전할 수 있는 취향저격 인테리어와 귀여운 곰돌이 케이크&아망추! 예쁜 카페에서 맛있는 케이크와 음료 먹으면서 평온하게 휴일 마무리하니 기분이 좋아요. 다음에 홍대오면 또 들를게요~ 무료대관도 가능하다고 한다.', 17, 9, 'GOOD', SYSTIMESTAMP);
