INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '오늘 서온 생일 카페 때문에 갔는데 생일카페이벤트 방문하러 간곳중에 제일 별로 였습니다... 일단 너무 매장이 좁아서 앉는 테이블도 별로 없고 구성도 아쉬웠습니다... 그리고 스탬프 투어이벤트라고 해놓고 굿즈를 사도록 강요하는거라면 굳이 왜하는지 이해가 되질 않았습니다... 전체적으로 어설프다는 느낌과 돈아깝다라는 생각이 공존했네요...', 36, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '창가 좌석에 앉았는데 분위기 너무 조용하고 좋아요~☺️ 사장님도 친절하시고 붐비는 연남동에 조용한 카페 발견해서 좋았어요! ✨✨ 또 방문하려구요!! 🫧', 43, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '귀여운 곰돌이 디저트가 있는 카페에 방문했어요! 디저트 실제로 보니 너무 귀엽.. 발바닥 디테일까지 미쳤음 카페 채광도 너무 좋고 ! 사진도 잘 나오고 굿👍', 127, 21, 'GOOD', SYSTIMESTAMP);
