INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '250307)"홍대생일카페" "아이돌생일카페" "배우생일카페" "카페무료대관" "홍대생카" "아이돌생카" "무료대관" "곰돌이케이크" 로 유명하고 입소문이 자자한 "홍대입구역 3번출구 근처의 역세권 대형카페" "스튜디오앱트" 에 첫방문을 하게 되어서 아주 영광스럽고 행복한 나날이었습니다!^-^/♡♡♡♡♡♡♡ "홍대입구역 3번출구 근처의 역세권 대형카페" 이며! 아기자기하고 분위기도 핫하고 역시 홍대입구역 최고의 대형카페 입니다!^-^/♡♡♡♡♡♡♡ 무료대관이 가능한 카페이며 아이돌이나 배우님들 생일카페로도 아주 최고로 좋습니다! 그리고 판매하고 있는 모든 메뉴들도 전부 다 맛있고! 디저트 종류가 무척 다양하게 있습니다! 재방문을 하게 된다면! "브라운치즈 크로플" 메뉴도 먹어보고 싶더라구요! 스튜디오앱트추천', 49, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '친구가 분위기 좋은카페 데리고 가주겠다고해서 따라왔는데통유리라 시원한느낌에 아기자기한 인스타감성이라 넘 좋았어요 거기다 테디케이크인 곰돌이디저트가 진짜 맛도리..!! 음료도 보기에도 이쁘고 맛도있어서 또올거같아요ㅎㅎ', 31, 2, 'GOOD', SYSTIMESTAMP);
