INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '새벽부터 멀리서 날아왔지만 마냥 행복했던 카페 ࣪˖ ִֶָ𐀔 냥덕이와 원빈이 천국이라 정신를 못채림^^ 생카 기획하신분 미감이 미쳤어요.... 사장님 친절하시고 내가 못까고 있는 갸챠 캡슐도 까주심 원빈아 생일 축하한다아아ㅏㅏㅏㅏㅏ', 54, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '연남동에 이렇게 귀엽고 예쁜 카페가 있는지 몰랐어요 ㅎㅎ! 곰돌이 케이크도 넘 귀엽구 음료도 맛나고 대화하기 좋아요! 평소엔 생일카페도 운영하는곳이라 많이 오실텐데 추천드립니당!', 35, 2, 'GOOD', SYSTIMESTAMP);
