INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '내부 인테리어가 멋있었던 스튜디오앱트 햇빛이 잘 들어서 어디서 찍어도 인생샷을 건질수 있어서 좋음 음료와 디저트도 너무 맛있어서 더 놀랏음', 59, 12, 'GOOD', SYSTIMESTAMP);
