INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '직장동료들과 1차로 치맥하고 가볍게 차한잔할 곳 찿다가 경의선 철로길 옆골목에서 발견한 예쁜 공간 저녁이라 커피대신 무얄콜 진저비어로 동료의 커피도 맛봤는데 커피맛도 좋았다. 조용한 카페에 우루루 들어갔는데 친절하게 응대하주시고 서비스로 아이스크림도 주셔서 내내 즐거웠다. 스타생일모임을 하는 카페같았다. 테디베어 미니 케이크도 인상적이었다. 이뻐서 차마 못먹을듯 홍대에서 모임있을때 또 가고싶다.', 6, 8, 'GOOD', SYSTIMESTAMP);
