INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '우연히 블로그 보다가 알게된 스튜디오앱트 🤍 곰돌이에 환장하는 저여서 더 마음이갔는데 실제로 보니 더 귀엽더라구요ㅠㅠㅠ 초코 좋아하시는분은 무조건 좋아하실것같아용!! :) 🐻🐻🐻 카페 분위기도 좋구 !! ☕️ 무엇보다 사장님이 너무 친절하셔서 더 더 좋았던것같아요 💙💙💙', 38, 2, 'GOOD', SYSTIMESTAMP);
