INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '하아아 너무 기야운 곰돌이케이크가 있는 곳 🤎 연트럴카페 여기로 가세용 채광도예쁘고 커피도 맛있고 곰돌이케키도 넘나 소즁하니까여 !!!!! 아이돌 생일파티도 할수있는곳인가봐용 분위기 쵝오 연남카페🤎🤎🤎', 35, 9, 'GOOD', SYSTIMESTAMP);
