INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '쇼콜라 테디 케이크 너무 귀엽고 맛있어요 💓 아메리카노랑 같이 먹으면 조합 최고예요!! 아메리카노도 맛집이네요 👍 완전 달고 부드럽고 당충전 돼요! 얼그레이 케익도 부드럽고 층층마다 크림이 많아서 좋아요~ 분위기도 깔끔하고 아기자기하면서 힙해서 생일카페로 많이 대관하시는 것 같더라구요! ㅎㅎ', 76, 12, 'GOOD', SYSTIMESTAMP);
