INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '맛,위치,서비스, 인테리어 뭐 하나 빠지지않고 완벽한곳! 인생카페 찾았어요 곰돌이 케이크 진짜 너무 귀엽고 쫀득하니 안달고 맛있어요 바질토마토에이드도 꼭 드셔보세요... 미친거같아요 단골 등극이요 또 갈거에요!!!! 악세서리도 판매하고 계시고 귀여운 공주세트도 있어서 사진찍기 딱 이였어요. 추천추천이요!', 18, 0, 'GOOD', SYSTIMESTAMP);
