INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '들어가자마자 와- 예쁘다 감탄했어요 채광도 좋고 인테리어도 블링블링해요🩷 시그니처 곰골이 케이크는 꼭 드셔보세요 귀엽고 맛있고 사진찍기 좋고ㅎㅎㅎㅎ 곳곳이 포토존이고 직접만드신 쥬얼리까지 판매하셔서 눈이 즐거워요:) 다음에 또 오고 싶은 카페 !!!😍', 43, 1, 'GOOD', SYSTIMESTAMP);
