INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '음료와 디저트 종류가 다양하고 바질토마토에이드 이색적이고 맛있었어요♥ 곰돌이 모양의 테디 케이크는 너무 귀여워서 심쿵! 먹기 미안한 비쥬얼이지만 맛있어서 어쩔 수 없어요ㅋㅋㅋ 분위기도 좋고 예쁜 소품들로 잘 꾸며져 있어요✨ 사장님이 직접 만드시는 쥬얼리 구경하는 재미도 쏠쏠한 카페입니당', 92, 24, 'GOOD', SYSTIMESTAMP);
