INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '근처에 용무가 있었는데 1시간 정도 시간이 비어서 이용하게 되었습니다. 깔끔한 인테리어만큼 깔끔 친절 하셨던 사장님의 응대에 기분좋게 쉬었다 갑니다~ ^ㅡ^', 24, 2, 'GOOD', SYSTIMESTAMP);
