INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '💟❤️확실히 아이돌 생일 대관까지 하는 카페다보니 인테리어랑 소품들이 다 감각적이에요!!💟❤️ 저도 공주기놀이 잘 하다 갑니당ㅎㅎㅎㅎㅎ 사장님 짱 친절하세요!!😁 홍대 인테리어이쁘고 사진찍기 좋은 카페 추천😊💜', 66, 13, 'GOOD', SYSTIMESTAMP);
