INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '사장님 너무 친절하시고, 베이글 식어도 촉촉하고 부드러워요., 찐 베이클 맛집에 크림은 꼭 토마토바질 드세요,, 소금 커피도 최고임♥️', 15, 0, 'GOOD', SYSTIMESTAMP);
