INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '최근 연남동에서 간 카페중 최고였어요>< 인테리어도 너무 예뻣는데 디저트랑 음료 너무 귀엽구 맛나요ㅜㅜㅜ ㅎㅎ 곰돌이 실화인가요 케이크 엄청 다양한데 이 곰돌이 케이크는 꼭 시키세요. 꾸덕초코가 완전 레전드입니다. 바질토마토 에이드도 색다른데 청량감 최고여서 요즘같이 더울때 완전 추천이요!!!  같이 팔고 있는 악세서리들도 너무 예뼈서 한참 구경했어요 친구들이랑 나중에 같이 다시 오꼐요 사장님  ❤️❤️', 66, 18, 'GOOD', SYSTIMESTAMP);
