INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '매장 분위기 힙하고 쾌적해요. 통창이라 낮에 햇살드는 것도 너무 예쁘고 더우면 커튼쳐서 빛을 가릴 수도 있답미장. ㅎㅎ 수제청에이드도 너무 맛있고 당근케이크랑 서비스로 주신 과자와 아이스크림도 잘 먹었어요~! 화장실도 청결해서 뭐하나 불편한 점 없이 잘 즐기다갑니당. ^^', 28, 0, 'GOOD', SYSTIMESTAMP);
