INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '우선 들어가자마자 인테리어도 너무 예쁘고, 통창이라 햇볕도 잘 들어서 햇살맛집이네요❤️🫢 사진을 위한 소품들도 있으니 셀카도 왕창 찍었어요! 음료도 사장님께서 직접 청을 담그셔서 진짜 맛있더라구요😂 디저트중에서도 곰돌이모양 케익이 진짜 귀여워요🐻 맛도 진하고 맛있답니다! 평소에 사진찍는 것 좋아하는데 여기는 감성사진도 찍기 좋은 곳이에요! 재방문하고싶은 카페입니다!💜', 18, 8, 'GOOD', SYSTIMESTAMP);
