INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '음료랑 케이크 맛은 말할것도 없고 공간이 너무 예뻐요 음료 마시자마자 시원하고 당근 콕콕 박혀서 진짜 맛있엉요!! 홍입 입구에서 그렇게 멀지도않고 2층이라 밖에 풍경 구경하면서 여유롭게 있기 너무 젛아요! 테디 케이크도 궁금한데 다음에 먹어버려구요!', 0, 6, 'GOOD', SYSTIMESTAMP);
