INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '분위기도 좋고 너무 예쁜 카페예요ㅠㅠ 연남에 항상 사람 많은 정신없는 카페만 가다가 이렇게 이쁘고 조용한 카페를 발견해서 너무너무 좋아요..🥹 음료도 넘 맛있고 쇼콜라 테디 케이크가 진짜 최고 ..🫶 친구랑 왔는데 애인이랑 데이트할 때 오기도 너무너무 좋을 것 같아요!! 연남에 카페 찐맛집 발견…🥺', 26, 7, 'GOOD', SYSTIMESTAMP);
