INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '커피, 곰돌이 무스케익, 서비스로 주신 아이스크림 모두 정말 맛있어요. 비 오는 날이라 기분이 안 좋았는데 좋은 곳에 오게돼서 다행이에요😆 무스케익 꼭 드셔보세요! JMT', 18, 10, 'GOOD', SYSTIMESTAMP);
