INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '인테리어가 너무 예쁘네요 ㅎㅎ 좌석마다 다 매력있어서 어디 앉을지 고민했어요 ㅎㅎㅎ 커피도 너무 맛있고 쇼콜라 테디 케이크 먹었는데 넘나 귀여움😆', 105, 25, 'GOOD', SYSTIMESTAMP);
