INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '요즘 자주 가는 연남동 카페 스튜디오앱트~ 새로운 디저트 메뉴 베이글에 푹 빠졌어요~🥰 카페도 너무 예뻐서 자주 가지만 음료랑 디저트가 정말 맛있어서 자주 가요~~ 인스타로 보셨거나 가보신분은 아시겠지만 음료 디저트 비주얼도 미쳤고요~ 한동안 크로플에 빠졌다 테디에 빠졌다 이번엔 베이글에 퐁당~~😆 크림치즈도 미쳤어요~다 맛있지만 전 바질페스도 크림치즈 강추요~ 베이글도 어쩜 이리 부드럽고 쫄깃한가요~~이렇게 안 질기고 부드러우면서 쫄깃한 베이글은 처음 먹어봐요~~~👍 커피랑 함께 오늘도 행복했어요~~ 언제나 친절한 사장님은 오늘도 최고~ 언제가도 기분 좋은 카페예요~~😄', 9, 4, 'GOOD', SYSTIMESTAMP);
