INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '분위기 있는데 디저트 맛있는 감성 카페 찾아보다가 왔어요 오렌지커피가 있길래 궁금해서 시켜봤는데 진짜 제 취향 ㅜㅜ 커피의 고소한 맛이랑 오렌지의 상큼 달달한 맛이 너무 잘 어울려서 조합 최고! 그리고 치즈케이크가 완전 맛이 찐해서 커피랑 너무 잘 어울렸어요~ 인테리어도 넘 예쁘고 분위기 좋아서 홍대 오면 또 방문할 것 같아용 친구랑 수다 떨기 딱 좋아요!', 45, 9, 'GOOD', SYSTIMESTAMP);
