INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '사진으로 보는 것보다 실제가 뷰가 더 좋아요!! 내부 인테리어 사진은 많이 못 봤는데, 생각했던 것보다 훨씬 예쁘고 깔끔합니당☺️ 디저트 음료 세팅도 엄청 신경써서 하신 티가 나고, 맛도 너무 맛있어요!!! 예쁘기만 한줄 알았더니, 맛도 너무 좋아용~~ 사장님이 스콘 서비스도 주셨어요💖 +영국인 친구도 인정한 치즈케이크 꼭 드셔보세용!', 106, 25, 'GOOD', SYSTIMESTAMP);
