INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '테디베어 케이크라니..완전 취향저격...💕 인테리어도 정말 예쁘고 쥬얼리까지 같이 판매한다는게 정말 매력적이네요! 공주놀이 할 수 있는 소품도 마련되어 있던게 귀여웠습니다ㅋㅋ 음료도 맛있고 사장님도 친절하세요!', 26, 7, 'GOOD', SYSTIMESTAMP);
