INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '카페메뉴가 다양해서 좋어요 솔트크림커피 대박이네요 ㅎㅎㅎ 주얼리도 판매하고있는데 너무 이뻐요💯💯 카페 분위기도 대박이고 대관까지 하고있어서 다음에 또 이용할께요 디저트 너무 맛있었어용', 46, 5, 'GOOD', SYSTIMESTAMP);
