INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '사장님 인테리어 감각이 남 다르신 것 같아요!! 매장이 너무 힙하고 예뻐요! 디저트나 음료 모두 예쁘고 맛도 좋아요!! 연남동 분위기 좋은 카페로 스튜디오앱트 추천합니당', 14, 6, 'GOOD', SYSTIMESTAMP);
