INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '🩷 솔트 크림 라떼 ; 크림에서 가벼운 엑설런트 아이스크림 맛이 나는게 진짜 크림 맛집에다가 호록 마시면 커피향이 사알짝 향긋하게 올라와서 너무 좋아요! 솔트라고 해서 커피가 짜면 엥스러운데 크림에 적당한 핑크솔트 정도여서 만족! 🩵 바질 토마토 에이드 ; 아이스크림 토마토마 맛이랑 비슷한데 더 깔끔 상큼한 맛입니다! 토마토 좋아하면 무족건이야- 🤍 베리베리크로플 ; 크로플은 바삭 + 아이스크림은 달짝지근 + 베리류들은 상콤해서 조합이 너무 만족스럽고 그냥 뭐 맛잇죠!! 🍀 마음에 들었던 가위와 집게. 매번 안잘리는 나이프 쓰다가 간편한 도구 쓰니까 진짜 행복- 인테리어 맛집이라 다녀오면 방 인테리어도 바꾸고싶어져요,,💚', 26, 2, 'GOOD', SYSTIMESTAMP);
