INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '사장님이 진짜 친절하시고 밝으세요ㅎㅎ 인테리어도 깔끔하고 청결하고 플레이팅도 굿!! 음료도 아주 맛있었습니다~ 재방문할 이유가 있는 카페에요!', 101, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '매장도 넓고 인테리어 엄청 이뻐요 😍 음료도 디저트도 엄청 정성스럽게 만들어주시고 섬세함이 느껴져요👍👍 사장님도 엄청 친절하시고 데이트하러오셔도 좋을꺼같아요 사진 많이 건져가요!!! 찍는곳마다 너무이뻐용 😍😍', 16, 9, 'GOOD', SYSTIMESTAMP);
