INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '귀여운 곰돌이케이크, (너무 귀여워서 기절 ㅎㅎ) 맛있고 예쁜 음료들이 있는 연남동 카페 스튜디오앱트 다녀왔오용 쥬얼리(귀걸이,팔찌,목걸이)도 판매하시고 카페대관(아이돌생일카페)도 진행하세요! 카페 내부 넓고 통창이라 뷰보는 맛도 좋네요✨ 신메뉴(오렌지비앙코)🍊먹으러 또 가야겠어요~~', 123, 23, 'GOOD', SYSTIMESTAMP);
