INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '브라운 치즈 크로플이랑 말차 라떼를 주문했는데... 크로플 완전 맛있었고 라떼도 맛있었지만 두 메뉴 조합은 어울리지않았다....ㅎㅎ...ㅎㅎ 그래고 둘다 맛있으니 한번 더 방문 할 예정!♡ 쥬얼리숍으로 카페 대관도 하는 곳이며 매장 안에서는 쥬얼리 모두 껴보는 게 가능하다🥰', 2, 7, 'GOOD', SYSTIMESTAMP);
