INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '들어가자마자 색감있는 의자들이 너무 예뻐서 눈이 휘둥그레해졌어요~~ 분위기도 좋고 인테리어가 너무 예쁜데다가 음료도 정말 최고...👍 공주놀이 아이템도 카페에 비치되어 있어서 친구들과 착용하고 사진찍으면서 한참을 놀았네요ㅎㅎㅎ 사장님 너무 친절하시고 깨끗한 카페, 다음에 또 오고 싶은 곳입니다💕', 82, 13, 'GOOD', SYSTIMESTAMP);
