INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '7명이서 앉고 마실 수 있는 카페 찾다가 우연히 찾아서 들어가봤는데 친절하게 책상이랑 의자 붙여주신다고 해서 넘 좋았습니다🤍 그리고 서비스로 아이스크림도 주셔서 너무 감동..ㅠ 음료도 너무 맛있어요 진짜 이렇게 착하신 사장님은 처음입니다,,💓 진짜 장사 잘되셨으면 좋겠어요ㅜㅜ! 분위기도 너무 좋고 음악도 제 취향입니다!! 인테리어도 깔끔하고 귀여워서 맘에 듭니다🫶🏻 그리고 노을 풍경도 넘 예뻐요,, 저녁 지는 시간에 가면 창문에 노을 지는게 보이는데 넘 예뻐요🍀 나중에 또 올게요>< (+저 진짜 이런 리뷰 안쓰는데 너무 착하시고 감동받아서 리뷰 씁니다!^3^)', 22, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '여자분들이 너무좋아할것같은 예쁘고 아기자기한카페!! 테이블이 인스타갬성이고 소품들고 사진찍기도 좋은 곳!! 아이스쿠림 크로플 너무 맛있고 달달해서 강추메뉴!', 85, 11, 'GOOD', SYSTIMESTAMP);
