INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '자발적으로 리뷰 쓰고싶게 하는 맛과 친절이네요🙏🏻 저희는 윗층 스튜디오 대관하면서 카페를 우연히 알게 되어 먹었는데 얼그레이 바닐라 라떼에 진짜 놀랐어요 흔하지 않는데 호불호 없을 그런 맛..! 모두들 연남동 카페 가면 꼭 먹어야할 맛집입니다 사장님이 흔쾌히 빌려주신 소품들로 제 브라이덜 샤워 사진도 이쁘게 찍었어요 저희 일행 다 연남 가게 되면 꼭 재방문 할게요 감사합니다 🤍', 223, 73, 'GOOD', SYSTIMESTAMP);
