INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '연남동 예쁜 카페 발견! 이런 카페를 왜 이제야 찾았나 싶었는데 오픈한지 며칠밖에 안됐다고 하네요~^^ 카페 인테리어가 너무 예뻐요. 요즘 유행인 미드센츄리 감성 가득 카페~ 구석구석 너무 예뻐서 어디를 찍어도 사진 정말예쁘게 나오고요! 이쁘기만한게 아니라 여기가 크로플맛집이었어요!!! 크로플 종류는~ 상콤달콤한 믹스베리가 듬뿍 올라간 베리베리크로플이랑 단짠의 정석 브라운치즈 크로플, 그리고 다 아는 맛이라 더 끌리는 초코아이스림크로플~세 종류예요~♡ 고민하다 주문한 초코아이스크림 크로플엔 오레오 가루도 뿌려져 있어서 달달달~~♡♡ 너무 맛있었어요~ 재방문각이네요! 오픈이벤트로 매장 이용시 귀걸이 증정 이벤트도 하고 있어요! 맛있게 먹고 귀걸이 선물까지 받아서 너무 기분 좋네요! 또 갈께요~^^', 38, 0, 'GOOD', SYSTIMESTAMP);
