INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '넘 맛있고~ 넘 예뻐^^ 평일오후에 돌아다니다 까페 새로 생겼나보네 하고 들어왔는데 😍😍😍 우왓 넘 맛있어~~브라운치즈크로플 헐 이렇게 브라운치즈 듬뿍에 크림은 넘나 맛있어~~알고보니 쥬얼리까페 ㅋ 먹고나니 보임. 예쁜귀걸이도 많음. ㅋㅋ 귀걸이도 겟!! 재방문각~ 담엔 베리베리크로플 먹어봐야징~ㅋ 사장님도 너무 친절하심~~', 30, 9, 'GOOD', SYSTIMESTAMP);
