INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '사장님도 친절하시고 가게도 이쁘고 깔끔함 홍대에서 이정도면 되게 좋았음 크로플은 좀 비싸지만 음료는 가격 착함 재방문 의사 있음😉', 16, 7, 'GOOD', SYSTIMESTAMP);
