INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '자몽에이드 ㅋ 맛있어요~~. 메뉴사진이랑 똑같아요^^ 보기만해도 시원한데 맛은 더 좋음 😍👍 두번째 방문~ 오늘은 혼자왔는데 음악도 좋고, 음료도 맛있고, 시원하고 ㅋ 힐링!! 좋아요', 18, 8, 'GOOD', SYSTIMESTAMP);
