INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스튜디오앱트 STUDIOAPT'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '사장님도 친절하시고 에스쁘아 팝업 위에 있어서 그냥 갔던 카페인데 생각보다 커피도 너무 맛있고 분위기도 좋아요!! 그리고 크로플 존맛이니까 제발 드세요', 29, 7, 'GOOD', SYSTIMESTAMP);
