INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더웨이브라운지 후카바'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '제 최애 시샤바예요! 사장님이 정말 친절하시고, 시샤 체크도 정말 자주 해주세요. 쿠폰 제도가 있어서 다 채우면 시샤 하나가 무룐데 벌써 두번이나 무료로 받았어요😅', 42, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더웨이브라운지 후카바'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '오랜만에 후카 하고싶어서 찾아봤는데 너무 카페처럼 아늑하고 좋은 곳을 발견했어요🙏🏽 사장님도 넘 침절하시고 음악도 좋고 깔끔해서 넘 만족이에용 🍀 다음에 또 올꺼에요!!!💕', 7, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더웨이브라운지 후카바'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '후카바 여러군데 많이 다녀봤는데 요새 제일 좋아요 일주일에 두 번 이상은 가는것같아요! 후카 맛 다양하구 음료도 맛있어욤 후카도 관리 잘해주셔서 마지막까지 맛있어요 강추함돠', 42, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더웨이브라운지 후카바'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '매장은 좀 작지만 아늑해요. 마테차는 쓴 녹차, 잎차 맛이에요. 후카 숯과 찻물을 자주 갈아주셔서 좋았어요. 화장실도 깨끗합니다. 추천!', 125, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더웨이브라운지 후카바'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '후카 피우시는 분들은 이미 아실 겁니다. 서울에서 찐 시샤 맛집 더웨이브 ❤️ 시끄럽지 않고 편안한 분위기에 온전히 후카를 즐기실 수 있어요. 일주일에 두세번 이상 매일 갑니다. 믿고 가시면 됩니다 !', 26, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더웨이브라운지 후카바'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '후카바 첫 방문인데 사장님께서 친절하게 잘 알려주시고 분위기도 좋은 것 같아요! 소중한 사람과 함께 대화하면서 즐기기 좋은 장소 같습니당', 35, 5, 'GOOD', SYSTIMESTAMP);
