INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더웨이브라운지 후카바'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '매장이 너무 깔끔하고 다른 후카바랑 다르게 밝은 카페 느낌나서 좋아요 :) 아는 사람이 저밖에 없어서 오히려 아쉬운 정도에요. 칵테일 몽키숄더 하이볼 맛있어요!!!', 40, 0, 'GOOD', SYSTIMESTAMP);
