INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더웨이브라운지 후카바'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '시샤 하고 싶을때마다 오는 곳인데 항상 좋아요. 숯도 정말 자주 갈아주시고 친절해서 단골될 것 같아요 ㅎㅎ 장소도 역과 가까워서 추천하는 곳입니다.', 17, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더웨이브라운지 후카바'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '처음으로 하러 왔는데 분위기도 좋고 노래도 잔잔해서 좋았어요!! 사장님도 친절하시고 자세하게 설명해주셔서 좋습니다! 친구랑 서울와서 노는데 좋은 경험하고 갑니다!', 27, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더웨이브라운지 후카바'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '혼자서 후카 하면서 독서하러 왔어요😷 보통 후카바는 밤에 운영하고 어두운데 밝아서 너무 좋았습니다 노래도 취향이구 자리도 아늑하고,,🩷 숯도 자주 갈아주세요 혼자만의 시간 갖고싶을때 또 올것같아요 잘 즐기다 가요~', 5, 3, 'GOOD', SYSTIMESTAMP);
