INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더웨이브라운지 후카바'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '후카바 처음 이용해보는 거렸는데 사장님께서 설명도 친절하게 해주셔서 즐겁게 경험해봤어요! 체험하면서 커피 마시고 대화 나눠서 친구랑 편하게 놀았어요', 40, 1, 'GOOD', SYSTIMESTAMP);
