INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더웨이브라운지 후카바'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '분위기 너무 좋고 가게가 깔끔해요.☺️ 후카 여러곳에서 해봤는데 가본 후카바 중 가장 좋습니다.👍 사진 찍기도 좋고 모임하기도 좋은 곳!', 3, 2, 'GOOD', SYSTIMESTAMP);
