INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더웨이브라운지 후카바'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '🎯후카바는 처음인데 👶저는 초보라 ''연한 체리&로즈베리'' 후카와 ''자몽에이드''를🧋 주문했어요🎍 🥤자몽에이드가 먼저 나와서 작고 아담하지만 갬성있는 공간이라 자몽에이드로 어떻게 찍어도📸 사진이 잘나오더라구요🫧 ❣️호스 봉으로 들이마실때 통안에 물방울과 연기가 올라오면서 흡입이 되어지고 뱉어낼때 자욱한 연기에🌬 뭔가 갬성돋는 모드가 되는것 같았어요 😆 💫그리고 호스에 바람을 불면 통안에 있는 연기가 빠져나가는 방식이에요😲 향수를 뿌린듯 제가 있는 공간에 체리와 로즈베리가💐 은은하게 향을 내어서 향이 너무좋고 힐링도 되더라구요🌿', 32, 4, 'GOOD', SYSTIMESTAMP);
