INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더웨이브라운지 후카바'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '후카 처음이라 잘 모른다하니 친절히 설명해주시고 너무 재밌었어요! 일반 카페 음료도 있어서 부담없이 즐기기 좋은 공간인 것 같아요😊 인테리어도 감각적이어서 취향저격이었어요! 데이트 코스로도 좋은 것 같아요💕', 46, 7, 'GOOD', SYSTIMESTAMP);
