INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더웨이브라운지 후카바'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '밝은 분위기에서 후카를 즐길 수 있어서 좋았습니다. 마우스피스도 인당 1씩 주셔서 위생에 있어 안심이 되었습니다. 화장실은 남녀공용으로 온수가 나오고 이솝 비누를 쓰시는 것 같았으며 사용하는데 무리가 없었습니다. 리뷰 이벤트로 주시는 콜라도 얼음과 함께 잔을 주셔서 좋았습니다.', 95, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더웨이브라운지 후카바'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '후카도 경험할수있고 필터커피 존맛임. 커피도 맛있는데 가게가 작은데도 편안하고 완전 아지트같아요. 빈백석 너무 좋아❤️ 혼자 가기도 좋고 친구들이랑 가기도 좋고 연인이랑 각도 좋네요. 커피랑 술 다 있으니 취향대로 먹을수있고 복숭아 아이스크림 맛있다고 들어서 다음에 먹어보려고요. 이번엔 커피만 마셨는데 다음엔 하이볼 먹어볼거예요!! 후카도 해봤는데 재밌었어유 ㅎㅎㅎㅎ 연기로 노는것도 꿀잼 ㅋㅋ', 33, 10, 'GOOD', SYSTIMESTAMP);
