INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더웨이브라운지 후카바'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '자주가는 최애 시샤바 더웨이브 ❤️ 시샤 맛도 좋고 밝은 분위기에서 즐길 수 있어 햄복쓰 🔥 숯도 잘 체크해주시고 아늑해서 만족스러워요 !', 79, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더웨이브라운지 후카바'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '*고요하고 집중하기 좋은 환경* 더웨이브라운지 후카바는 고요하고 집중하기에 좋아서 공부하기에 이상적입니다! 또, 자리에 충전기를 꽂을 수 있는 콘센트도 있어서 태블릿 가지고 오셔서 물담배 즐기시면서 공부하시기에 최고의 카페입니다.', 34, 2, 'GOOD', SYSTIMESTAMP);
