INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더웨이브라운지 후카바'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '후카바라는 곳을 처음 와보는데 넘 신기하고 좋네요 후카하는 곳은 다 어두침침한 굴 같은 곳에서 한다는데 여기는 채광도 좋고 사장님도 넘 친절하시고 음료도 맛있습니다❤️ 후카를 처음 해보는데 사장님께서 넘 친절하게 설명해주셨어요', 24, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더웨이브라운지 후카바'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '매장이 청결하고 사장님이 친절하세요 커피 맛도 좋은데 시샤초보인 저에게 친절하게 설명해주시고 중간중간 계속 체크해주셔서 즐겁게 할 수 있었습니다 아! 화장실도 깔끔하고 매장안에 있어서 너무 좋았어요', 25, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더웨이브라운지 후카바'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '좋아용! 아이스크림도 맛있었어요 직원분 설명도 차근차근 해주셨고 짱 친절하셨어요 물담 처음인데 색다른 경험이었슴다! 근데 많이 피면 안 되겠어요 다음날 죽었습니더... 😵 조용한 분위기 좋아하시는 분들께 추천드려요!', 48, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더웨이브라운지 후카바'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '홍대에서 칵테일, 하이볼과 함께 후카를 하고 싶은 바를 찾으신다면! 더웨이브라운지 후카바로 가세요! 복숭아 아이스크림이 맛있었어요~~', 89, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더웨이브라운지 후카바'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '친구랑 같이 후카바 이용했어요 초보자도 쉽게 후카를 할 수 있네요 후카가 진하고 퀄리티도 좋네요 커피 한잔 여유롭게 하면서 후카하고 왔어요~!!', 50, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더웨이브라운지 후카바'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '좌석이 편해서 편하게 시샤를 할수 있었고 친구들과 대화하기도 좋았습니다 호기심에 첨 가본곳인데도 사장님이 친절하셔서 전혀 어색하지 않았고 편하게 즐기고 왔습니다', 22, 7, 'GOOD', SYSTIMESTAMP);
