INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더웨이브라운지 후카바'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '후카 처음 해보는데 너무 재미있었어요~ 후카가 진하고 퀄리티가 좋네요 술을 잘 못먹어서 커피 시켰어요 커피 먹으면서 후카할 수 있네요', 42, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더웨이브라운지 후카바'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '제가 좋아하는 맛의 커피! 이런 커피맛때문에 다시찾을수 밖에 없네요. 사장님도 친절 하시고 벌써부터 사람들이 많이 찾아오는거 같아요. 저녁에 가면 후카랑 다양한 칵테일도 마시러 다시 와야겠어요 . 애정하는 홍대 아지트가 될꺼 같아요!', 49, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더웨이브라운지 후카바'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '분위기 진짜 좋구 음료도 맛있어요! 후카도 맛있고 친구나 데이트 등 만나기 너무좋은 장소예요ㅜㅜ 사장님 진짜진짜 친절하세용 너무 아늑하고 좋아요 너무 좋은데 말로 표현할수가 없네요.. 재방문의사 3000%입니다❤️❤️', 125, 21, 'GOOD', SYSTIMESTAMP);
