INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더웨이브라운지 후카바'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '*최상의 시샤(물담배) 경험* 이곳은 시샤 관리는 정말 뛰어납니다. 다른 곳에서는 경험할 수 없는 일관된 맛과 품질을 유지해주는데, 이는 사장님이 주기적으로 나오셔서 직접 관리해주시기 때문이에요. 물담배 고인물로서 처음 맛을 계속 유지해 주시는 사장님의 정성은 정말 대단하십니다.', 25, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더웨이브라운지 후카바'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '*편안한 분위기와 탁월한 서비스* 더웨이브라운지 후카바는 훌륭한 내부 분위기와, 친절한 사장님 덕분에 항상 편안하게 머무를 수 있어요. 혼자 공부하러 자주 방문함에도 항상 반갑게 맞아 주십니다. 사장님의 고객을 소중히 여기는 마음이 느껴지는 곳입니다.', 48, 8, 'GOOD', SYSTIMESTAMP);
