INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더웨이브라운지 후카바'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '*완벽한 조합: 커피, 술, 그리고 시샤 “낮과 밤, 모든 시간대에 완벽한 라운지”* 낮에는 맛 좋은 커피와 함께 공부하거나 지인과의 대화를 즐길 수 있는 완벽한 장소입니다. 밤이 되면, 맛있는 칵테일과 함께 편안한 시간을 보낼 수 있어요. 커피와 칵테일 모두 최상급이며, 물담배와의 조합도 훌륭해 어떤 시간에 방문해도 만족스러운 경험을 할 수 있습니다.', 37, 8, 'GOOD', SYSTIMESTAMP);
