INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '동료가 제일 좋아하는 곳이라고 해서 모임장소로 선택했어요. 분위기가 좋고 쾌적해서 입장할 때부터 좋았는데, 무엇보다 맛있어서 더 자주 방문하고 싶은 곳 입니다. 쾌적하고 맛있은 곳 찾는다면 추천입니다. 😋', 30, 4, 'GOOD', SYSTIMESTAMP);
