INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '저번에 한번 와봤는데 너무 맛있고 분위기가 좋아서 두번째 방문했어요! 폴브라운 커피도 진짜 맛있고 음식은 역시 레전드..👍 진짜 찐 해외 브런치 느낌이라 외국인들도 항상 많은 것 같아요. 사장님도 영어 너무 잘하데이트 장소로도 넘 추천이요🥹 요즘 브런치 먹고싶었는데 여기부터 생각나서 바로 달려왔어요. 다음에 또 방문할게요🫶', 31, 8, 'GOOD', SYSTIMESTAMP);
