INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '커피와 브런치가 모두 만족스러운 가게를 찾았어요! 브런치는 심플한데 소스랑 밸런스가 좋아서 정말 맛있게 먹었어요! 뻔하고 보기만 그럴듯한 브런치플레이트 아니고 알차고 맛납니다~ 다른 메뉴들도 하나씩 맛보러 와야겠어요ㅎㅎ', 102, 19, 'GOOD', SYSTIMESTAMP);
