INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '건강하고 맛있는 샌드위치를 먹었습니다. 눈으로 즐긴 다음 입으로 향했을 때 입안에서 느껴지는 그 맛은 아름다웠다고 말할 수 있겠습니다. 시각과 미각의 조화가 일품입니다. 선곡도 좋아서 귀까지 즐겁습니다. 스피커가 엄청 좋아보였어요.', 36, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '지인 만나러 왔다가 시간이 남아 식사 차 우연히 들렀는데 음식도 맛있고 분위기도 정말 좋네요. 한적한 곳임에도 웨이팅이 있어 기대하고 기다렸는데 기다린 보람이 있습니다. 외국 분들도 정말 많이 오시네요.', 42, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'MEETING');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '커피만 맛있는 줄 알았는데 브런치 메뉴도 맛있어요. 비건 메뉴도 있고 신선하고 알차요. 양도 보기보다 푸짐해서 배부르네요. 카페도 예쁘고 사진도 잘 나와요 음악 좋고 뭐 하나 빠지는 게 없네요. 다음 모임하러 또 오겠습니다', 27, 3, 'GOOD', SYSTIMESTAMP);
