INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '근처에 일정이 있어서 왔다가 우연히 들러서 브런치했는데 분위기 합격, 메뉴도 합격, 맛두 합격이에요! 라떼도 꼬숩고 브런치메뉴도 너무 맛있어요 ㅋㅋㅋ 저희 동네에도 있으면 좋겠어요ㅠㅠ!!!', 7, 7, 'GOOD', SYSTIMESTAMP);
