INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '호주식 브런치라고 해서 궁금해 방문했어요 전반적으로 특색 있고 건강한 맛이 인상적이었습니다 “팔라펠 플레이트”는 제 입맛엔 타코처럼 느껴졌고 “가든 스페셜”은 에그 스크램블에 한국에서 보기 힘든 재료들이 독특했어요 호주식 브런치라 그런지 외국인 손님들도 많이 보였고 브런치뿐 아니라 커피도 진심인 느낌이었어요 커피 맛도 좋았습니다', 5, 1, 'GOOD', SYSTIMESTAMP);
