INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '회사와 가까운데 지인이 추천해줘서 방문했어요! 매장도 아늑하고 자리도 붙여주셔서 편하고 맛있게 먹었는데 다음에 여유롭게 방문해서 커피랑 마셔도 좋겠어요~:)', 92, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '아침에 와서 건강하게 먹기 좋아요 음악을 들으며 여유롭게 시작하기 좋은 것 같아요 요리도 간과 메인 재료별 조금씩 다르게 들어가는 구성이 좋네요 맛있게 잘 먹었습니다.', 98, 21, 'GOOD', SYSTIMESTAMP);
