INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '친구들이랑 브런치 하러 방문했어요 아기자기한 소품들과 창가에서 들어오는 채광 푸릇푸릇한 식물들 덕분에 따뜻하고 감성있는 분위기 좋았고 커피 훌륭하고 브런치로 먹을 메뉴도 다양하고 맛있었습니다 좋은시간 보내고 갑니다🫠😊', 31, 4, 'GOOD', SYSTIMESTAMP);
