INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '가든브런치랑 풀드포크 다 너무 맛있어요. 이 맛은 여기서 밖에 못 먹는 것 같음,, 게다가 커피가 너무 맛있어서 더 맛있게 먹을 수 있어요. 커피 좋아하시면 꼭 커피랑 드시길,,주기적으로 와줘야 하는 집👍', 155, 75, 'GOOD', SYSTIMESTAMP);
