INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '지나가다 항상 와보고 싶었던 곳인데 드디어 와보네요! 브런치부터 디저트까지 모두 맛있었어요!! 아이스크림 쫀득한게 정말 너무 맛있어용👍', 61, 12, 'GOOD', SYSTIMESTAMP);
