INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '카페 구석구석 사장님의 센스가 돋보이는 곳입니다. 음식도 맛있고 건강한 느낌이에요. 커피는 당연히 훌륭합니나. 자주 오고 싶어지는 장소네요 :)', 5, 6, 'GOOD', SYSTIMESTAMP);
