INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '어쩌다 우연히 동네에서 발견했는데 너무너무 맛있는 커피집을 찾았어요~  언제 생겼대요~??  발견 이후론 거의 매일 출근하면서 사갖고 가네요~ 아침에 고소한 라떼는 저의 최애가 되었네요~  완전 커피맛집 이네요!  주말에 보니 브런치 맛집 인거 같은데 조만간 브런치로 방문 할께요~', 1, 9, 'GOOD', SYSTIMESTAMP);
