INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '플레이트가 나오기 전에 먼저 오렌지 주스와 코코넛 샤워가 먼저 나왔어요. 음료는 둘 다 자극적이지 않고 딱 알맞은 당도로 음식과 잘 어울렸습니다. 파머스 플레이트와 가든 브런치를 주문했는데 간이 잘 된 연어와 베이컨이 곁들어진 파머스 플레이트와 특별한 소스 맛이 느껴지는 가든 브런치 두 개를 같이 시키기를 잘 한 것 같아요. 10시가 되니 사람이 꽉 차서 일찍 방문하길 잘 한 것 같아요. 다음에 재방문 의사 완전 충만합니다~~~♥️', 127, 22, 'GOOD', SYSTIMESTAMP);
