INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '오늘도 정말 맛있게 먹고 갑니다! 😊🙂‍↕️🙂‍↕️ 커피도 맛있고, 논카페인 음료도 많아서, 아침에 즐기기 너무 좋아요! 👍 평일 아침에 방문하니 그 특유의 분위기가 너무나도 좋네요! 🤗', 74, 18, 'GOOD', SYSTIMESTAMP);
