INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '햇살이 비치는 아침 가게 분위기에 반하고 갑니다.  롱블랙 산미있는 커피 맛있고, 가든 에그스도 간이 적당하니 맛있어요. 외국 분들 비건 메뉴 드시러 많이 오시는 것 같아요. 뉴질랜드 안가봤지만 뉴질랜드를 느낍니다. 아 여행가고 싶다-', 3, 2, 'GOOD', SYSTIMESTAMP);
