INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '커피도 꼬숩고 찐해서 음료 자체도 맛이 있었고 음식도 깔끔하고 처음 먹어보는 메뉴였는데 거부감없이 싹싹 비워먹었어요! 특히 아보카도가 부드럽고 양배추 샐러드가 깔끔해서 좋았습니다! 그리고 튀김도 처음 먹어보는 맛임데 바삳바삭하고 소스마다 조금씩 맛이 달라서 너무 맛있게 먹었습니다!', 44, 0, 'GOOD', SYSTIMESTAMP);
