INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '좋은 추억이 있어 오랜만에 다시 방문한 아날로그가든. 역시 분위기,맛,친절함 모두 최고였다👍🏻 재방문 의사 10000% 행복해지는 음식과 공간 즐길 수 있어서 너무 행복해요 감사합니다🫶🏻', 17, 6, 'GOOD', SYSTIMESTAMP);
