INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '흉내낸 맛 아니고 진짜 맛 아 너무 맛있어요 밸런스도 훌륭해요 쿠스쿠스 입에서 안 흩어지고 쫀쫀하고 페퍼론치노랑 후추가 느끼한 맛을 잡아줘요 연어랑 아보카도 신선하고 소스랑 양파랑 잘 맞아요 음악도 넘 포근하고 주말 나른한 분위기 다들 친절하시고 😌 힐링하고갑니다🌿💚', 39, 4, 'GOOD', SYSTIMESTAMP);
