INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '비주얼 좋고 특히 커피가 맛있어요 ~~~ 로스터링도 하는지 기계도 있더라구요 ~~ 주말방문 했는데 저 빼고 다 외국인 ㅎㅎㅎ  한국서 외국온 느낌도 좋네요 ㅎㅎㅎ', 48, 2, 'GOOD', SYSTIMESTAMP);
