INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '길가다 분위기가 좋아보여서 들어왔어요 아메리카노랑 팔라펠 플레이트 먹었는데 남녀 둘이서 브런치로 먹기 딱 좋은 양이에요 팔라펠 볼 처음 먹어봤는데 너무 맛있었어요 원두 로스팅도 직접 하셔서 그런지 커피 맛도 너무 좋아요 홍대 오시면 브런치 드실때 꼭 들려보세요😆', 26, 0, 'GOOD', SYSTIMESTAMP);
