INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '홍대입구사거리 지역에서 보기 드물게 아침 8️⃣시 문을 여는 브런치식당. 호주🇦🇺스타일.. 맛있음❕️ 일찍 일어나 배고픈 분들, 특히 아침 먹을 곳 써치해 찾아온 외국인여행객들 눈에 많이 띔. 🔹️ 입장해서 자리잡은 후 카운터로 가 주문하면서 결제💳 먼저. 업장은 좁은 편. 둘이 앉을 수 있는 테이블이 10개쯤 오밀조밀. 테이블 자체 크기도 아담해 연인들👩‍❤️‍👨에게 최적. 🔹️ ''파머스 플레이트'', 호밀빵 위에 베이컨,연어,아보카도,수란,트러플,야채가 올리브오일과 치즈에 살포시 버무려져 먹음직🍴 롱블랙커피☕️는 매력적 베리향 산미🍇', 80, 16, 'GOOD', SYSTIMESTAMP);
