INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '매장도 너무 예쁘고 직원분들도 정말 친절 하셨어요. 그리고 무엇보다 브런치 메뉴들이 너무너무 맛있습니다. 오늘 첫방문인데 또 오고 싶어요!', 8, 7, 'GOOD', SYSTIMESTAMP);
