INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '오랜만에 홍대 예쁜 카페 와서 비건 음식과 아아 먹으며 작업하니 대학(원)생 때로 돌아간 느낌이네요 ㅎㅎ 음식 맛도 너무 좋아서 추천합니다~!!👍👍', 127, 22, 'GOOD', SYSTIMESTAMP);
