INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '그동안 커피만 먹으러 왔었는데 처음으로 식사메뉴를 시켜봤오요. 신선한 재료, 건강하고 맛있는 식사였어요~ 맛있게 잘 먹고 즐겁게 쉬고 갑니다^^', 43, 10, 'GOOD', SYSTIMESTAMP);
