INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '이거 먹으려고 홍대왔는데 만족스러웠습니다😉 특별한 브런치를 맛볼 수 있는 곳이었네요 인테리어도 이쁘고 중간 중간 식물들이 분위기를 더 편안하게 만들어주는것 같아요', 34, 6, 'GOOD', SYSTIMESTAMP);
