INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '3번째 방문입니다. 올때마다 느끼지만 커피가 정말 향이 좋고 맛이 풍부해요~ 아날로그가든땜에 홍대 계속 옵니다~ 그리고 에그스가든! 진짜진짜 맛있어요~ 홍대오면 무조건 아날로그가든 올거에요! 오늘은 남편과 함께 왔는데 남편 연한커피만 먹는데 여긴 진한데도 맛있어서 좋다고 칭찬을 계속 하고 있어요~ 같이 오길 잘했네요^^', 54, 14, 'GOOD', SYSTIMESTAMP);
