INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '저희가 오더한 파머스플레이트와 쿠스쿠스볼  정말 맛나요!! 플랫화이트도 구웃 입니다!!^^ 외국인들도 엄청 많이 오네요~^^  사장님  국위선양 멋집니다!!', 91, 22, 'GOOD', SYSTIMESTAMP);
