INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '유명해서 꼭 한번오고싶었는데  드드어 왔어여   쿠스쿠스 사랑해요  건강하고 좋아요  분위기도  음악도 ~ 좋아요  건강식 특별식 먹고싶으면  아나로그!!!!', 16, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '가끔 커피만 테이크아웃해왔던 곳인데 남편과 오랜만에 느긋하게 브런치했어요~ 커피도 맛있고 눈과 입이 즐거운 시간이였습니다🥰 혼자도, 둘도 좋을것같아요:-)', 2, 2, 'GOOD', SYSTIMESTAMP);
