INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '오늘같이 날이 넘 좋은날엔 예쁜 브런치 먹어줘야죠 호주식브런치라는데 가고싶네요 저 호주 못가봤는데요🥺 회사 들어가기엔 날이 넘 예뻐서 장미향따라 땡땡이중💕', 45, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '신선하고 건강한 재료들로 구성되어있는 브런치카페입니당!! 저번에 왔을땐 식사류가 마감되어서 못먹었는데 오늘은 성공!! 식당 분위기도 우드톤으로 따뜻하고 음식도 맛잇어용!!', 171, 29, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '원래 다른 곳 가려다가 웨이팅이 너무 길어서 가볍게 브런치 먹으러 온 곳이에요 웨이팅 쪼끔 있었지만 빠르게 입장했어요 푸릇푸릇한 인테리어에 브런치 비주얼 넘 잘 어울려요🪴 리뷰에서 본 대로 정말 외국인분들이 많으세요 합정에 작은 외국이랄까! 에그스에 햄 추가했는데 소스가 부분으로 있어서 빵 한 개로 여러 가지 맛 즐길 수 있어서 좋았고 안 느끼하고 깔끔해요! 한 끼 잘 먹고 갑니당♥', 2, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '너무 예쁘고 사랑스러운 곳이에요..🍀 올때마다 만족하구 갑니다 음식도 음식인데 실내 분위기가 너무 따뜻하고 평호ㅓ로워요 트러프레소는 하나의 요리를 먹는 기분이니 꼭 한번 시켜보시길!!!', 43, 0, 'GOOD', SYSTIMESTAMP);
