INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '자주 애용하는 곳입니다. 요즘 외국인이 너무 많은데 외국 감성나요. 가격이 조금 있지만 분위기 맛이 다 하는 곳이에요.재료 좋은게 느껴져요.', 27, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '유학하는 딸 만나러 서울상경. 네이버검색에서 발견한 홍대역근처 브런지카페 아날로그가든 실내인테리어 등 감성 듬뿝 친절히 응대해주시는 스탭분듫 건강한 블랙퍼스트 브런치 가든에그스와 커피한잔의 여유로운식사 웰빙의 감성.굿..재방문 200% 딸과함께 즐거운 모닝타임보냈어요', 40, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '카페가 너무 예뻐요 다음에 시간이 되면 와서 브런치도 먹고싶어요 머신이랑 그라인더도 좋은거 쓰시고 매장이 깔끔하게 유지되어있어요 👍', 43, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '오랜만에 브런치 먹고싶어서 이곳저곳 검색하다가 분위기가 좋아보여서 왔습니다 후기 읽고 왔는데 역시나.. 너무 맛있어서 행복했습니다ㅠ 일단 브런치하면 비싸고 양도 적다는 인식이 있는데 여기는 양도 많고 가격도 적당하고 딱이에요 팔라펠 플레이트 존맛탱이니까 꼭 드세요 또띠아 추가해서 또 드세여.. 진짜 집에 싸가고 싶을 정도ㅠㅠㅠㅠㅠㅠㅠ 담에 또 올께요', 27, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), 'Good brunch menu with fresh ingredients. there''s a bit of waiting but the good coffee was definitely worth the time.', 31, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '맛있게 잘먹었습니다~ 늘 많은 사람이 줄서 있어서 궁금했는데 건강한 맛이예요! 신기한 재료가 많아서 즐겁게 먹었습니다. 인테리어도 멋집니다', 41, 6, 'GOOD', SYSTIMESTAMP);
