INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '에그가 들어간 메뉴가 많아서 좋아요 ㅎㅎ 커피도 맛있어요 위치도 접근하기 편해요 창이 커서 밖에 구경하면서 식사할 수 있어요 🥰🥰🤍🤍🤍🍽️🥞☕️', 40, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '작고 아늑한 가게에요! 식사 메뉴와 카페 메뉴가 함께있고 비건 메뉴가 있어서 논비건 친구와 가볍게 오기 좋을것 같습니다. 식물들이 곳곳에 있어서 너무 예뻐요!! 카페 안에 창이 크게 뚫려있는데 거리 구경하며 시간 보내기 좋습니다~🥰', 57, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '주변네 볼 일 있어 잠깐 왔다가 블루리본 뱃지가 5개 있는 것을 보고 무작정 점심 먹으러 들어왔어요! 커피도 너무 맛있고, 플레이트도 정말 맛있었습니다! 또 오고 싶어용!', 60, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '블루리본이 걸려있어서 즉흥적으로 들어온 카페예요! 라떼는 진해서 괜찮았고, 코코넛 샤워는 처음 먹어보는 커피 맛이라 색달라서 흥미로워요! 무엇보다도 여기 인테리어가 예뻐서 머무는 동안 기분도 좋았어요!', 92, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '여기 진짜 무조건 오세요,,, 매번 지나갈때마다 궁금했던 곳인데 진짜 기절이에요 ~!!~ 너무 맛있고 분윅 너무 좋고 행복한 곳입니다..💓', 30, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '항상 손님이 많아서 궁금했는데 자리가 남아있길래 즉흥적으로 들러봤어요 큰 창으로 보이는 동교동 풍경도 너무 좋고 호주식 브런치 맛도 아주 좋았습니다 뜻밖의 힐링하고 가요', 87, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '평생 먹은 브런치 집 중 가장 커피가 맛있는 곳!! 마시기 전에 향부터 미쳤네요.. 이 정도 향이 살아있는 아메리카노는 처음 마셔봐요... 거의 드립 수준의 다양한 노트가 살아있네요. 감탄하면서 마심!!! 브런치는 한국식보다는 파리나 뉴욕에서 먹는 맛이에요. 한국식 특유의 매콤한 맛은 거의 없고 쿠스쿠스나 팔라펠을 활용해서 이국적인 맛이 나는 편입니다! 양도 충분히 많아요♡ 다음에 또 올거에요!!!', 40, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '2번째 방문이고 9시반에 입장했는데도 사람 많아서 기다릴뻔 했는데 다행히 한자리 있어서 앉았어요! 다른곳 브런치랑은 차원이 다르구요 정말 맛있어요! 정말정말 맛있어요! 친구 데려왔는데 친구도 칭찬 엄창 했구요. 게다가 커피맛도 정말 좋고 특히 쿠키 엄청나게 맛있습니다! 가까이 살면 매일 올텐데 너무 아쉬워요 홍대 올때마다 방문 예정입니다!! 아날로그 가든 완전 짱이에요!^^', 43, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '파머스플레이트와 포르게타 주문했는데 둘다 맛있었어요. 튻니 뽀르게타는 어떤 맛일지 상상이 안됐었는데 결론적으로 잘 고른 메뉴네요. 시그니처 커피도 달달새서 음식과 안어울릴카ㅈ걱정했는데 잘 어울렸어요. 전반적으로 양이 돔 적은 점 빼고는 만족스런 식사였네요. 또 올 의사 있습니다^^', 118, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '얘기만 듣다가 처음 방문했는데 듣던데로 맛있네요. 이국적인데 향이 깔끔하고 섬세해요. 가든스페셜(+빵/베이컨 추가)과 코코넛샤워 먹었습니다. 먹는 양이 적은 편이면 두명도 충분합니다. 추천드립니다.', 50, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '대만 친구가 먼저 방문해서 왔는데 너무 분위기 좋고 다시 1번 더 오고 싶어요!! 블루 리본도 많은데 홍대에서 남겨두고싶은 찐 맛집입니다!!', 64, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '커피도 너무 맛있고 은은한 음악에..쏟아지는 햇살..! 브런치 카페로서 완벽합니다! 주말 아침 힐링하고 갑니다~^^ 외국인분들도 아침 일찍부터 많이 오시네요!', 3, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '연어 들어간 파머스플레이트, 기본 가든 플레이트 둘다 넘   고급지네요 롱블랙 커피도 첫맛이 오! 커피 맛있다! 로 연결되는 맛~ 특히 옷걸이 따로 있는거랑 물 정수기가 짱  신선했어요 외국인들도 많이 오는데 사장님 영어가 짱!', 41, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '음식은 매콤한 향신료가 들어간 메뉴가 많아 좋았어요! 야채도 싱싱하고 플레이팅도 근사합니다. 맛도 물론 좋구요! 무엇보다 커피가 정말 끝내줍니다. 한자리에서 오래 하셨으니 시간이 맛을 증명하는것 같습니다. 자주 올께요^^', 47, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '원래 음식 사진을 잘 안 찍는 편인데 비주얼부터 아름다웠습니다. 그런데 양념의 아주 은근한 맛과 전체 재료 조합의 맛이 더욱 더 아름다웠습니다ㅜㅜ. 예술처럼 느꼈던 음식 감사합니다! 새로운 최애 맛집이 생겼습니다..', 3, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '워낙 유명해서 따로 설명도 필요 없는 곳이죠. 메뉴 나오면 좀 배고플거같은데..? 했다가도 다 먹고나면 포만감이 좋아요🌿🥑 가든 브런치 먹었는데 메뉴 중에 제일 맛있는 것 같아요. 완전 제 스타일~ 푸짐하고 맛있는 건강한 식사!', 36, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '인테리어도 너무예쁘고 ~ 오픈주방이라 청결함도 믿을 수 있고 창밖에 햇살이랑 분위기도 너무 좋아요❤️ 무조건 또 오고싶은 분위기! 애견동반도 되서 정말 좋습니다', 20, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '예전부터 가고싶었는데 드디어 왔어요. 분위기는 물론이고 너무 맛있네요. 이것저것 먹고 싶어서 세개나 시켰는데 여러개 시키길 잘했어요 진짜 맛있어용', 109, 23, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '왜 떠나기 전에 이런 멋진 곳을 알게 되었는지🥲!!  맛은 이미 너무 완벽한데 눈으로도 먹는 기분이라서 스스로에게 대접하는 느낌이에요. 요즘 식단관리해서 포케나 샐러드 자주 시켜먹었는데 가격에 맞지 않는 맛과 양때문에 화났거덩요.. 저는 진짜 근처면 매일 여기 올 것 같아요 담에 또 올게요 진짜......💌💝', 43, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '여기 커피부터 먼저 나왔는데 컵 디자인에 우선 반했고 커피 맛에 또 맛있다 했어요 :)) 요새 진짜 건강한 음식을 먹고 싶어서 찾아보다가 점심 맞춰서 친구들이랑 왔는데 여기는 손님 반이상이 외국언니오빠들이에요. 식재료의 원물 그대로 보이면서 깨끗하고 맛도 깔끔하게 좋아서 혼자서도 자주 올 것 같아요!! 진짜 킹 맛 ㅜㅜ 넘 좋음 ㅜㅜ쿠스쿠스 맛도리이고 아 킥!! 할라피뇨가 들어간 소스가 있는 거 같은데 느끼할 수 있는 맛이 확 전환되면서 벨런스가 좋습니다 :)) 또 올게요💗', 15, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '홍대 브런치 가게 찾다가 들어왔는데 호주식 브런치라고 하네요 ! 기분이 좋아지는 예쁜 공간에서 커피도 맛있고 브런치도 맛있게 먹고 갑니다 !💗', 122, 24, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '가끔 시간날때 와서 브런치랑 커피먹는곳인데 식사메뉴도 독특하고 맛있구, 제가 좋아하는 느낌의 카페에요! 음악들으며 맛난거먹구 멍때리기 좋습니다💚', 22, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '일요일 아침 8시에 와서 먹었는데, 와,,,, 너무너무 맛있어서 싹 다 먹었네요. 셋이서 각자 쿠스쿠스 하나씩 시켰는데 다들 그릇을 싹 비웠습니다! 감사합니다 ^^', 1, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '특별한 커피 메뉴가 있어서 도전해봤는데 이곳에서만 맛볼수 있는 특별하고 맛있는 맛이네요 트러프레소 엄청맛있고 처음먹어보는맛이라 추천이에요 브런치도 다양하고 건강한 메뉴로 구성되어 좋아요 블루리본 다섯개 있어서 들어왔는데 탁월한 선택이엇어요 ㅎㅎ', 5, 1, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '연남동에서 제일 좋아하는 브런치 카페에요! 처음 왔던 게 5년 전이었던 것 같은데 맛도, 분위기도 여전히 너무 좋아요. 화창한 주말 시드니 어느 카페에 있는 듯한 감성!', 23, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '커피 정말 맛있었어요! 특히 분위기가 너무 좋아서 혼자 조용히 시간을 보내기에도, 친구랑 놀기에도 좋은 것 같아요. 인테리어도 아늑하고 조명도 따뜻해서 편안했어요! 다음에 또 올게요.', 117, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '친구 추천으로 처음 와봤는데 밖에서 지나갈때 보던거보다 안에 분위기도 너무 좋고 음식은 너무 깔끔하고 사랑스럽고 다 맛있 어요. 팔라펠 존마탱~~~~!!! 또올께요.', 19, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '겉은 바삭, 속은 촉촉한 팔라펠이 정말 맛있었어요! 병아리콩 알갱이 살아있고 소스 세 가지랑 곁들여 먹으니 계속 새로운 맛이 느껴져서 질리지 않았고요. 신선한 샐러드랑 또띠아까지 곁들여 든든하게 한 끼 했습니다. 플레이팅도 예뻐서 사진 찍기 좋았고, 분위기도 밝고 쾌적해서 만족스러웠어요.', 60, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '처음 매장에 딱 들어섰을때 마치 태국에 있는 리조트에 있는 느낌이 들었어요 ㅎㅎ 기대 한가득 안고 시키 브런치는 기대치를 한참 초과해 너무 행복한 아침 식사였습니다! 얼그레이향이 가득한 클래식 밀크티와 진한 맛이 인상깊은 카페라떼까지! 너무 맛있게 잘 먹고 갑니다, 감사합니다!', 138, 47, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '서교동 이사가기전에 마지막으로 방문했네요! 직원분들도 친절하게 설명해주시고, 인테리어 분위기도 마음에 들어요! 디저트 맛있습니다 :)', 129, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '아침에 일찍 여는 곳 찾기가 어려운데 , 늘 아침에도 사람 많은 아날로그 가든 !! 🐶강아지랑도 갈 수 있어서 좋았어요. 나오는 음악도 참 좋고, 커피만 마시러 왔다가 오늘은 브런치 먹었는데 역시나 감동이네요!🥹', 44, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '목표는 가든스페셜이었지만 팔라펠볼이 그새 떨어졌다네요. 결국 브런치로 변경! 후회없는 선택이었습니다 다음에는 조금 더 일찍와서 스페셜에 도전해야겠네요', 51, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '다양한 메뉴가 많았는데 그 중에서 쿠스쿠스 보울 먹었습니다 ㅎㅎ 맛도 있있구 먹은 후 적당한 포만감이고 깔끔해서 좋았습니다. 다음에 재방문해서 다른 것도 먹어보려구요.', 37, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '커피가 맛있어요! 롱블랙 종류 두가지 고를 수 있는데 저는 산미있는거 골랐어요. 첫맛은 진하고 맛있는데 끝맛은 또 부드러웠어요ㅎ', 60, 18, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '엄마랑 이 동네 산책하다가 심상치 않은 맛집의 기운이 느껴져서 계획하지 않았던 브런치를 먹게 되었습니다. 기대 이상으로 예쁜 음식과 신선한 음료 메뉴들이 보기에만 좋은 게 아니라 정성이 담긴 맛이 느껴졌어요! 저는 다음에 다시 와도 베리베리 루이보스 오트밀크티와 타히니포그를 시킬 것 같아요! 먹어보지 못한 메뉴들도 또 방문해서 시도해보고 싶습니다. 엄마랑 기억에 남을 데이트를 하게 해주셔서 감사해요 :)', 93, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '가끔 즐거우면서도 쉬고 싶은 점심 때 자주 가는 곳인데 오늘에서야 리뷰를 올리네요 바쁘게 왔다가 쉼을 안고 가는 곳입니다 좋아요!', 45, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '밖에서는 가게가 작은 듯 보였는데, 안에 들어오니까 분위기 너무 좋고 특히 직원분들이 너무 친절하셔서 정말 좋았어요. 커피도 맛있구, 외국까페도 많이 가봣는데 외국 느낌이랑 거의 똑같아서 해외온 것 같았어요 ! 커피만 마셨는데 다음에는 음식도 먹어볼게요 :)', 30, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '햇살이 큰 창을 통해 매장 안으로 들어오는 것, 따뜻한 음악이 흐르는 것을 느끼다 보면 놓여지는 음식이 참 좋네요:) 브런치는 신선한 야채와 함께 고소하고 건강한 메뉴들이 있어 더 좋구요! 외국인 분들도 많았고 여러모로 여유가 있는 시간이었어요☺️', 468, 82, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '주말 브런치 먹으려 왔는데 분위기도 아늑하고 가든스폐셜 주문했는데 넘 맛나네요. 커피도 굿이고요. 직원분들도 친절하시고 좋아요', 53, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '여기서만 맛 볼 수 있는 브런치라서 너무 특색있고 맛있게 먹었어요 ㅠㅠ!!! 진짜 새로운 맛이면서도 낯설진 않아서 맛있게 잘 먹었습니다 ㅎㅎ 인테리어도 너무 잘 해두시고 직원분도 친절하셔서 편하고 맛있게 잘 먹고 갑니다 ㅎㅎ!', 38, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '홍대입구역 1번 출구 인근에 위치한 브런치 카페로, 블루리본도 붙어있어요. 비건 메뉴를 포함한 다양한 브런치메뉴와 디저트가 많습니다 ! 내부는 아늑하고 햇빛이 잘 들어와 편안한 분위기입니다. 반려견 동반도 가능해요! 커피는 시그니처 메뉴로 2가지 시켰는데, 트러플 들어간 커피를 추천드립니다! 👍🏻', 5, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '외국인 친구와 가기 좋은 브런치 맛집! 각 메뉴에 들어가는 모든 재료가 메뉴판에 다 적혀 있어서 식재료 알러지가 다양하고 개인 선호도에 특히 민감한 외국인들에게 정말 좋은 곳인것 같아요. 가든 스페셜을 주문했는데 신선한 재료를 과하지 않게 요리했기 때문에 건강한 맛이 물씬 느껴지고요. 다양한 재료를 밸런스 좋게 구성해서 독특한 조화가 느껴지더라구요. ​그러나 아쉽게도 양이 많지는 않았어요. 홍대 근처에서 따뜻하고 정감있는 로컬 채식 브런치 경험하고 싶은 분들께 강추해요.', 48, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '작은 가게인데 좌석이 오밀조밀 가득 있어요. 주말 아침이었는데 만석이고 줄을 섰더라고요. 외국인 손님도 많았어요. 브런치메뉴들 재료가 신선해서 좋았고 대체로 매콤한 맛이 들어 있었어요. 라테가 맛있더라고요. 추천해요!', 29, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '서교동의 귀한 브런치 카페에요 ㅎㅎ 커피도 맛있고 음식도 맛있어요 채광이 좋아서 여유롭게 시간 보내기 딱 좋습니다 🤍 팔라펠이 가장 맛있어요', 80, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), 'n년째 방문중입니다 분위기도 너무 좋고 친절하시고 음식은 맛있는데 다른곳에선 먹을 수 없는 맛이라 더 좋아요! 오래오래 영업해주시기를..!', 23, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '시그니처 커피 중 더티 차이 커피가 처음 마셔보는 데도 취향과 잘 맞았어요 ㅎㅎ 내부 공간도 아늑해서 겨울에 와서 시간 보내기 좋은 것 같아요 : ) 음식도 맛있어 보이는데 다음에 식사 안 했을 때 와서 먹어보고 싶네요', 15, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '입맛이 까다로운 편인데,(특히 집에서 만들기 쉬운 메뉴로만 구성된 브런치는 싫어하는 편) 맛이 굉장히 고급져요. 가든에그스에 아티초크 추가했는데 모든 재료가 다 조화롭고 맛있어요 ㅠ 예쁘기도하고 분명히 다른 메뉴도 다 맛있을 것 같아요.', 73, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '눈오는 날 브런치 먹으러 방문했는데 분위기도 좋고 음식. 커피 모두 맛있어요 브런치 비주얼이 예뻐요~ 가든에그스에 아보카도 추가해서 먹었어요', 30, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '카페는 작고 아늑해요. 하지만 창으로 햇살도 잘 들고 따뜻한 느낌 가득하네요^^ 흘러나오는 음악도 좋고 커피 맛이나 브런치 맛도 좋습니다. 브런치 메뉴는 아주 강렬하고 자극적인 맛이 아닌 집에서 만든것 처럼 담백하고 깔끔해요.', 10, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '일찍 문연곳을 찾다가 들어간곳.8시반 갔는데 오픈되있엇니 좋았고 커피볶는기계있는걸로 봐서 당근 커피맛집인줄알았네요. 작지만 푸근한 분위기였네요', 71, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '처음 2019년에 방문했었는데 추억의 맛을 다시 만나려고 해 재방문했습니다. 건물은 달라도 맛은 달라지지 않았어요! 옛날처럼 신선하고 건강한 맛인데 완벽한 브런치 옵션이에요! 트러플맛 정말 신기하고 여러 가지 메뉴랑 잘 맞아요. 분위기가 훈훈하고 주변이 조용한 편이에요.', 76, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '너무 맛있어서 또 오고 싶은 아날로그가든🍀🩵 카페라떼랑 브런치메뉴도 넘 넘 맛있오요•• 인테리어도 포근하고 전메뉴 다 먹어보고 시품 🍀❄️🍀❄️', 10, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '먹은 브런치중에 최고입니다 ㅎㅎ 정말 맛있습니다 강추드립니다. 커피도 맛있으니 꼭 같이 드셔주세요~~!! 🙏😍😍 잘 먹고 갑니다', 18, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '일단 인테리어가 반은 먹고가는 실패가 없을듯한 인테리어와.. 역시 실망시키지 않는 맛나는 음료가 있는 좋은 장소인듯 합니다. 홍대 오실일 있으시면 여기서 커피한잔, 어떠신가요?', 10, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '음식 맛있고, 커피 맛있고, 코지합니다! 달걀이나 채소들이 신선해서 좋네요. 호주에 살아본적이 없어서 호주식 블랙퍼스트에 관한 언급을 할순 없지만(음식은 맛있음) 플랫화이트는 방문해서 마셔봤던 그 맛이었어요ㅎ 그리고 작은 소품들이 매우 인상적이고 따뜻한 느낌의 우드톤 인테리어라 그런걸까요 부드럽고 아늑해요. 거기에 묘하게 익숙한 느낌이 드는 분위기의 레스토랑이예요.', 13, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
