INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '토요일 아침에 친구랑 같이 방문했어요! 갬성 낭낭합니다!! 인테리어 예쁘고 혼밥 하시는 분들도 많으시네요! 저는 특히나 빵이 쫀득하고 맛있었어요!! 맛있게 먹고 갑니다🥹', 120, 26, 'GOOD', SYSTIMESTAMP);
