INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '팔라펠이 너무 바삭하고 고소하고 맛있었어요🫶 쉽게 찾아보기 어려운 코지하고 따뜻한 바이브 햇빛도 잘 드는 오후에 커피 한 잔 하기도 좋아요', 491, 46, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '건강한 메뉴인데 맛까지 있으니 너무 좋아요! 외국인 손님도 많고 맛집인가봐요! 음식도 맛있게 잘 먹고 갑니다! 폴브라운커피 너무 제스타일.. 다음엔 데이트하러 올게요!', 93, 25, 'GOOD', SYSTIMESTAMP);
