INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '친구랑 같이 브런치 먹으러 왔는데 직원분들도 너무 친절하시구 특히 팔라펠 너무너무 맛있어요. 랩에 싸먹으니 신선하고 맛있었습니다. 가게는 조금 좁지만 쾌적하고 인테리어도 너무 감각있고 좋아요. 또 오겠습니다☺️', 39, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '커피가 정말 맛있어요. 호주식커피에 브런치인데 딱 먹던맛이에요. 카푸치노시켰는데, 향긋한 충미에 우유의 달달함이 느껴져서 오랜만에 기분좋은 카푸치노 한잔이었습니다. 디카페인 아이스아메리카노도 마셨는데 디카페인이지만 맛있었어요-!', 82, 11, 'GOOD', SYSTIMESTAMP);
