INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '햇살맛집🥰 커피맛집🥰 음악맛집🥰 일찍 오픈해쥬셔서 좋네요 시그니처 커피도 맛있어요 뿜뿜 하루를 시작할 수 있게 해주는 곳입니다', 50, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '색다르고 예쁜 브런치. 둘 다 맛있어요! 늘 브런치 먹으러 사람들 가득해요. 특히 외국인에게 소문난 맛집🐥 다음에 다른 메뉴들도 먹어보고 싶네요 - 쿠스쿠스 보울 15,900 - 피쉬 아웃오브 워터 16,900', 94, 23, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '비건이라해서 맛없을거란..생각은 노우.. 이쁜데 음식 넘넘 맛있어용! 소스도 자극적이지 않아서 잘먹었습미다:) 같이 시킨 코코넛 스무디도 달지않아서 좋았어용', 88, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '홍대 아날로그가든. 오래된 인켈 스피커에서 나오는 아날로그 음악에 시간이 멈춘듯합니다. 차가운 도시에서 찾기 힘든 따뜻한 공간이네요. 커피도 근처 스페셜티 카페 못지 않아요!', 68, 14, 'GOOD', SYSTIMESTAMP);
