INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '친구끼리 아침 일찍 방문했습니다 분위기, 음악 , 커피 뭐 하나 부족한게 없네요ㅎ 특히나 추천 메뉴인 폴 브라운은 특유의 너티함과 적절한 당도 때문에 굉장히 만족스럽게 마셨습니다', 1, 6, 'GOOD', SYSTIMESTAMP);
