INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '대체휴일이라 황금같은 시간을 어디서 보낼까 하다가 찾아낸 아날로그가든! 너무 맛있고 비주얼도 좋아서 만족하고 갑니당 ㅎㅎ 특히 코코넛음료가 정말 맛있어용!', 36, 0, 'GOOD', SYSTIMESTAMP);
