INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '직원분들이 친절하십니다 항상 손님으로 만석이고 외국인 비율이 많아요! 커피도 맛있어서 테이크아웃 많이 했는데 브런치 너무 맛있네요 또 방문의사 있습니다', 24, 0, 'GOOD', SYSTIMESTAMP);
