INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '동네에 있어 자주 가는 곳입니다 시드니 브런치를 위주로 하는데 호주하면 떠오르는 플랫화이트가 맛있습니다 그리고 처음보는 특이한 잔에 담아주는데 재밌습니다 매번 플랫화이트가 맛있어서 오는데 다음엔 브런치도 먹으러 와야겠습니다', 359, 31, 'GOOD', SYSTIMESTAMP);
