INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '너무 맛있고 분위기도 너무 좋아서 재방문 했어요!!! 커피가 진짜 너어무 맛있어요 ㅠㅠ 롱블랙 강추합니다 ㅠㅠ 음식도 맛있고 부담없어요!!', 10, 8, 'GOOD', SYSTIMESTAMP);
