INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '피쉬 아웃오브 워터와 가든에그스를 시켰는데요, 재료가 신선하고 주말 오후 채광이 너무 예뻐서 기분 좋게 잘 먹었어요ㅎㅎㅎ🍀 특리 피쉬오브워터의 연어와 아보카도가 너무 신선해서 좋았어용ㅎㅎ 피클도 달달하고 리프레쉬되는 맛!!ㅎㅎ 또 오고 싶어요~!', 121, 23, 'GOOD', SYSTIMESTAMP);
