INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '플레이트하나하나 손수 만드신 정성스러운 맛이엿어요  너무 잘 먹었습니다 다 맛있는데 특히 팔라펠 플레이트를 제일 맛있게 먹었네요!! 감사합니다ㅎㅎㅎ', 35, 0, 'GOOD', SYSTIMESTAMP);
