INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '생일을 맞아 와이프와 방문했습니다. 브런치식당이지만, 생일에 방문하기에 부족함없는 퀄리티의 음식을 맛볼 수 있었고, 코코넛밀크에 에스프레소가 가미된 ‘코코넛샤워’도 정말 특별한 맛이었어요. 유명한 ‘트러플에소’와 다른 플레이트들을 먹으러 다시 방문하겠습니다~ 라고 적었는데 너무 궁금하여 바로 주문하여 마셔보았습니다ㅎㅎ 특별하고 특이한 중독성 있는 맛이에요~ 미각과 후각을 동시에 자극하는 맛!! 다들 꼭 마셔보세요~ 맛있는 음식 감사합니다:)', 44, 10, 'GOOD', SYSTIMESTAMP);
