INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '애견동반이 가능한 유명항 서교동 브런치까페입니다. 커피로만 유명한줄 알았는데 브런치가 진짜 맛있어요. 유명해서 살짝 웨이팅 있을때도 있지만 금방 자리 나옵니다.', 15, 5, 'GOOD', SYSTIMESTAMP);
