INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '일요일 아침에 여유있게 건강하고 맛있는 브런치를 먹을 수 있는 공간! 쿠스쿠스 맛이 궁금했는데 아날로그가든에서 먹어볼 수 있었어요. 평소에 자주 못먹는 메뉴가 많고 비건 메뉴도 다양해서 좋아요!', 35, 0, 'GOOD', SYSTIMESTAMP);
