INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '토요일 아침 오픈하자마자 와서 가든 에그스 (아침 브런치 메뉴) 먹었습니다 너무 맛있어서 휘둥그레 하면서 먹었네요 ^^ 쿠스쿠스 사이드 추가 강력 추천 드립니다. 오래오래 번창해주세요!', 105, 21, 'GOOD', SYSTIMESTAMP);
