INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '친구겸 배우자겸 의형제겸 동료겸… 아무튼 친한 사람과 점심 먹으러 왔어요🥹 너무 맛있고, 음악과 인테리어가 취향이에요😊😊😊 다음에 또 방문할게요 맛있는 음식 감사합니다!', 14, 3, 'GOOD', SYSTIMESTAMP);
