INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '호주식 플랫화이트가 라이트한 동시에 진해서 너무 맛있었고, 트러프레소는 달달한 크림이랑 트러플 오일이 올라가있는데 처음 맛보는 조합이라 신선했어요! 외국인 분들도 많이 오시고 분위기도 넘 좋았습니다.', 20, 9, 'GOOD', SYSTIMESTAMP);
