INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '독특한 시그니처메뉴와 이국적인 분위기가 끝내줘요 더티 차이 는 정말 차이고 밀크티는 진하고 트러프레소는 진짜트러플향이 강하고 독특해요!', 22, 3, NULL, SYSTIMESTAMP);
