INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '정말 오랜만에 왔네요. 혼자였던 제가 아이를 낳고 그 아이의 만4살 생일 전날에 가족과 함께 말이에요. 커피가 맛있고, 팔라펠 플레이트가 맛있어요,여전히. 표고가 장소를 기억하는 듯해요. 행복하네요.', 9, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '목재와 음악, 창으로 들어오는 햇살에 마음이 편안해지는 곳. 맛있는 에그 요리와 커피까지 곁들이면 최고. 오래오래 있어주세요🙏🐰☺️', 106, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '오랜만에 방문하는데, 너무 맛있어요!! 🥰😋 토요일 아침에 방문했는데, 외국인들도 엄청 많아요! 분위기가 정말 좋네요. 쿠스쿠스 보울은 상큼하고 가벼우면서, 풍부한 맛이 너무 좋았어요!! 😍 커피와 밀크티도 너무 맛있고, 너무 행복한 브런치 경험이였어요.', 46, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '남자친구랑 가끔 방문하는데 너무 너무 맛있어요 ㅜㅜ 다른 곳하고 좀 차별되게?? 맛있어요🤤 폴드포르게타?? 제가 시킨 메뉴들 너무 맛있어요 그리고 무엇보다 커피가 넘 맛있어요 👍👍🩵 가게 분위기도 넘 좋고 바깥 풍겨도 좋아요~', 96, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '오랜만에 와도 참 좋아요. 브런치 맛집, 팔라펠, 에그 요리 유명하고 유럽분들도 엄청 많이 오시는데 갠적으로 마포구에서 만나기 어려운 평범하지만 특별한 시그니처 디저트와 음료가 좋아서 옵니다. 유럽 백반집 같은 느낌, 사장님도 직원분들도 힙하신데, 무엇보다 박리다매가 아닌 정말 한 접시 한 접시, 코지한 공간에서 먹는 일상 브런치로 최고에요.', 14, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '에그스에 아보카도 추가해서 먹었어요! 헤비하지 않은데 든든하게 잘 먹었습니다 ㅎㅎㅎ!! 오렌지쥬스도 완전 상큼하고 맛있습니다.. 분위기도 좋아요… ㅎㅎ', 25, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '브럽치먹으러 남자친구랑 왔는데 에그스에 아보카도 추가 해서 먹으니까 너무 맛있어요 ! 커피도 산미 맛 너무 좋습니다! 인테리어에 왕큰 스피커가 한몫했네요 ㅎㅎㅎ 더운 여름에 쉬다가기 참 좋은곳 인것같아요!!', 25, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '여러번 왔는데 처음 리뷰 작성! 블루리본 연속~ 외국인들 많아요. 맛집 인증입니다. 브런치도 좋았고 음료도 좋았고 테이크 아웃도 굿입니다', 21, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '인테리어가 예쁘고 깔끔해요. 빵이 부드럽고 맛있고 재료들도 신선하고 맛도 독특하고 맛있어요. 가든 브런치에는 빵,계란,햄,방울토마토,아보카도가 나오는데 신기하고 맛있어요! 가든 브런치+비니나드유스무디 추천해요 다음에도 오고싶어요!', 7, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '브런치 먹으러 왔습니다! 대문부터 블루리본이 가득해서 기대가 되었는데 역시 맛있었어요💘 가든스페셜로 먹었는데 팔라펠이 특히 맛있었어서 다음에는 팔라펠 메뉴를 먹어볼까 합니다', 33, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '커피도 맛있고 분위기도 좋아요~ 드디어 와봤습니다! 맨날 사람이 많아서 못왔는데...🥲 외국에 온것같고 분위기가 좋아요♥ 최고!', 98, 19, 'GOOD', SYSTIMESTAMP);
