INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '신선하고 맛있어요!!! 트러플 오일향 은은하게 나고 팔라펠도 바삭바삭. 소스가 조화로워요. 은근 든든하고 넘 맛있어요 ❤️ 커피도 아주 맛있어요!🩷', 74, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '브런치 식당을 찾고 있었는데 우연히 지나치다 발견한 숨은 맛집이에요! 카페 내부는 테이블이 많진 않지만 평일 오전이라 그런지 바로 앉을 수 있었어요. 전체적으로 우드베이스에 소품 하나하나 신경쓰신 느낌이 들어서 좋았습니다. (플리도 인디 어쿠스틱이라 👍👍) 음식은 가든 에그스에 아보카도 추가했는데 제가 아는 그맛이라 너무너무 반갑고 정말 맛있었습니다!! 호밀빵도 적당히 구워서 나오는데 가장자리가 바삭하고 안은 부드러워서 좋았어요! 커피대신 얼그레이 티를 시켰는데 잘 어우러져서 너무 맛있게 잘 먹었습니다! 다른 메뉴들도 궁금해서 다음에 또 올거같아요! ☺️', 30, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '친구 단골 카페라고 해서 따라왔어요. 트러프레소 정말 독특하고 맛있어요. 블랙페퍼는 커피를 음식의 반열에 등극 시킨 신의 한수라 생각해요. 더울 때는 코코넛 샤워 시원하게 추천해요. 디저트로 시킨 아이스크림 시나몬도 넘 맛있어요. 대신 녹기 전에 스피디하게 빨리 맛있게 드셔야 해요.', 44, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '혼자만의 여유롭고 특별한 시간을 가지러 방문한 곳 중 하나입니다. 음식들이 보기에도 예쁘고 맛도 좋더라구요. 팔라펠 볼은 처음 먹어봤는데 독특한 식감이 참 좋았고, 전체적으로 조화가 좋았습니다. 고기러버로서 토핑 중 올라간 햄이 특히 맘에 들었습니다. 재방문 하고 싶네요!', 85, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '브런치로 너무 유명한 곳이라 아침 일찍 오픈런했어요😌 팔라페 랩 안에 오독오독 씹히는 것도 너무 맛있고 바나나두유 스무디까지 아침으로 드시면 점심 스킵해도 될 정도로 든든합니다....🤍', 5, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '메뉴가 다양하면서도 각각의 메뉴의 구성이 너무 좋았습니다. 신선한 채소와 함께 영양소의 균형도 브런치로 먹기 정말 좋았습니다. 그리고 특히 플레이팅이 아주 좋아서 먹기 전에 사진 찍기도 매우 좋았습니다. 음료도 매우 시원했고 식전에 음료수부터 주셔서 정말 맛있게 먹었습니다. 매장도 너무 혼잡하지 않고 아늑하며 세련된 분위기에서 더욱 맛있는 식사가 되었습니다. 잘 먹었습니다!', 49, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '오늘 비도 오고 기운 빠지는 일이 있어서 기분 전환겸 나한테 좋은 음식을 선물해줘야지하고 평소 눈여겨보았던 이곳에서 식사를 했다. 혼자라 식사 가능한지 여쭤보았더니 흔쾌히 된다고 얘기해주신 친절한 사장님, 비오는 날 따듯한 조명과 인테리어, 마음을 녹여주는 재즈, 음식과 커피 맛까지... 최고였다..! 비올 때 재즈 들으면서 창 밖 바라보는데 아, 이건 리뷰를 꼭 남겨야겠다 싶어서 자발적으로 작성하는 리뷰이다. 흥하세요 아날로그가든!! (아, 제가 주문한 메뉴는 파머스 플레이트외 따듯한 롱블랙이에요 ㅎㅎ)', 3, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '저의 올타임 페이보릿 브런치 집입니다 팔라펠 랩 너무 맛있어요! 재료 하나하나 정성 들이신 티가 물씬 나는 음식이라 먹을 때마다 기분 좋아요~~', 168, 76, 'GOOD', SYSTIMESTAMP);
