INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '건강하고 맛있는 한 끼 먹고 싶을 때 주로 가는 곳이에요 재료도 매번 신선하고 오랜만에 가도 맛의 편차가 없어서 좋아요 밀크티도 추천', 61, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '매장 들어갔을 때부터 맛잇는 냄새에 치이고 조명과 비쥬얼에도 치인상태로 메뉴 나올때까지만 기다렷어요ㅠㅠ 기대만큼 넘 신선하고 맛잇어요ㅠㅠㅠ재방문의사 가득🫶🏻입니다!', 49, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '늘 지나가다 눈여겨 봤는데 디뎌 왔네여^^ 너무너무 친절하시고, 분위기도 좋고, 맛도 환상적입니다. 왜 손님이 많은지 알겠네요. 재방문200%', 27, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '댕댕이 동반해서 방문할 수 있는 아날로그가든!!! 브런치맛집이라 댕댕이랑 브런치 먹으러 방문해도 좋을 것 같아요!!! 커피도 맛있어요👍', 102, 19, 'GOOD', SYSTIMESTAMP);
