INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '남친 매장 놀러갔다가 브런치카페 찾아서 우연히 왔는데 분위기도 브런치도 너무 좋았어요❤️ 매장도 넓고 빈티지 분위기 낭낭 반려동물도 가능하다니 다음에는 또 오려구요 완전 추천이요👍', 16, 9, 'GOOD', SYSTIMESTAMP);
