INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '핸드폰 고치러 왔다가 들렀어요. 나름 외국인들 핫플레이스? ~~ 그래서 분위기도 음식도 음악도 더 이국적이네요. 앞에 바다만 있으면 휴양지일듯..(도로지만^^) 맛은 아날로그가 추구한데로 건강한 느끼믈 주는 야채위주예요. 제가 먹은 쿠스쿠스 는 살짝 매운맛이 있는데 빵이랑 같이 먹으니 괜찮네요. 또 근처 지나갈일 있음 조용히 차한잔 해봐야겠어요~', 74, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '지나가다 들린 곳인데... 와 정말 인생 브런치집... 음식이 건강하니 맛도 있어서 너무 행복했어요. 홍대쪽 올 때마다 들릴 듯...👍', 45, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '등원 후 데이트에 최적화 된 공간 맛 분위기🩵🤍 육아를 더욱 더 힘차게 할 수 있는 에너지 퓔업!!😇 자기야, 우리 가족 행복하게 살자😘', 126, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '출근할 때 보면 항상 자리가 차 있어서 궁금했는데 드디어 가봤습니다 가든스페셜, 코코넛샤워 두 가지 시켰는데 둘 다 너무 맛있었습니다😊 코코넛샤워는 고소하면서 달달하니 쭈욱 쭉 들어가더라고요 다 맛보고 싶었기에 가든 스페셜로 시켰는데 혼자 먹기엔 양이 많은 것 같습니다 (1.5인분 느낌) 오픈샌드위치에 들어있는 햄이 정말 맛있고 쿠스쿠스가 뭔가 했는데 색다르게 맛있었어요:) 진짜 배불렀는데 맛있어서 다 비웠습니다 다음에 다른 메뉴도 먹어봐야겠어요🫨', 44, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '한버 오고싶던 곳인데 대기없이 바로 들어와서 좋았어요! 음식은 예상처럼 맛있고 커피는 예상보다 훨씬 맛있어서 놀랐어요 커피 마시러도 종종 와야겠어요:)', 83, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '지나가다 우연히 가게 외관이 예뻐서 검색하니 호주식브런치를 먹을 수 있는곳이더라구요... 롱블랙 테크아웃 했는데 커피 제스타일입니다~ 맛있어요.. 다음에 브런치도 먹으러 가야겠습니다.', 36, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '팔라펠 영국에서 먹고 오랜만에 먹었는데 다시 영국이 떠오르는 맛이었어요 ,,! 물론 이집트 음식이긴하지만 ,, ㅎㅎ 살짝 매콤한 킥이 있는게 한국적인 매운 맛과는 다른 느낌을 잘 살리신 것 같아서 계속 생각날 것 같아요 🫶🏻 다른 메뉴도 다 도전해보고 싶네요 🤤 왕왕 추천합니다 ,,!', 3, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '너무너무 예쁘고 아늑하고 재즈 음악도 좋아요…🩷공간에서 느껴지는 몽글몽글함이 딱 제 취향입니다. 바나나스무디 시켰는데 음료도 딱 맛있고, 이제부터 여기는 제 아지트입니다. 💭', 55, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '걷다가 우연히 들렀는데 신선한 맛에 반해서 자주 오게 될 것 같아요! 커피도 정말 맛있습니다. 여유로운 낮에 브런치 먹기에 정말 좋네요 ~', 26, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '가벼운 점심으로 할만한 메뉴 찾다가 들렀어요 팔라펠은 해외에서 자주 먹어보던 거라 무난하게 잘 먹었는데 처음 들어갔을 때 좀 텁텁히고 불쾌한 냄새가 났네요 주방쪽 청소가 잘 안된듯요. 그리고 가게 내부는 생각보다 좁았고 좀 너저분했어요. 그런 부분이 좀 아쉬웠습니다', 36, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '원래도 자주 사먹는데 커피도 맛있고 항상 친절하셔요! 아기유치원셔틀이 여기 앞에서 내려서 종종 선생님들도 사드리는데 다 커피 맛있다고 하시더라구요 :)', 60, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '쿠스쿠스볼하고 롱블랙 주문했습니다. 쿠스쿠스볼은 살짝 매콤했는데 오히려 질리지 않고 끝까지 맛있게 먹을 수 있었고 채소들이 신선해서 좋았습니다. 롱블랙도 산미 있는 원두로 시켰는데 너무 잘 어울렸습니다. 가게 분위기도 포근하고 혼밥하기에도 좋습니다.', 69, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '화창한 날 창가에 앉아서 먹었는데 호주에 있는것 같은 느낌을 받았어요!! 음식도 너무 맛있고 사장님도 친절하셔서 기분좋게 있다가 갔습니다 ㅎㅎㅎ', 21, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '옛날부터 꾸준히 오던 커피맛집이라 브런치두 종종 시켜먹었는데 오늘 시킨 풀드 포르케타두 엄청 맛있더라구요 :) 커피는 늘 콜드브루 마시는데 여기만큼 맛있는 콜드브루 못 찾았어요', 49, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '양 많습니다 저 돼진데 남겼어요 너무 아까움 코코넛 커피 한입먹자마자 베트남이네요 브런치가 삼삼하지 않고 한국인에게 딱 알맞은 맛이었어요', 48, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '시간이 애매해서 간단하게 먹을 수 있는 걸 찾다 방문한 곳! 혼자 식사도 가능해서 좋았습니다 매장 분위기가 이국적이라서 여행 온 기분 들었어용', 65, 11, 'GOOD', SYSTIMESTAMP);
