INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '가격대가 있지만 다른 곳에서 먹을 수 없는 맛이라 만족하면서 먹었습니다! 분위기도 너무 좋아요! 양이 작은가 싶었는데 먹어보나까 적당했어요', 11, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '분위기는 너무 좋은데 음식은 향신료가 강한느낌이에요! 가든 스페셜 시켰는데 가격대는 좀 있고 제가 햄을…안좋아하는데 깍둑썰기로ㅠㅠㅠ 저랑 취향 반대이신분들이 좋아하실것같아요!', 10, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '브런치로 가볍게 먹기 좋은 곳이에요. 가든 에그스에 아보카도를 추가했는데, 잘 선택한 것 같아요. 적절하게 간이 베어있어서 너무 뻑뻑하지 않아요. 식감 자체가 부드럽고 플레이팅도 예쁘게 되어 있어서 눈으로도 입으로도 먹기 좋아요. 팔라펠 랩은 양배추가 많이 들어있어서 신선하게 먹을 수 있어요. 팔라펠은.. 생각보다 퍽퍽하고 간이 약해서 먹으면서 좀 힘들었어요. 소스가 적어서 그런것인지, 야채 특성 때문인지 서로 뭉침?이 적다보니 한입 먹을 때마다 후두두두 흘리면서 먹게 되서 불편하기는 합니다. ㅜ 매장은 큰 편은 아니지만 그래도 아늑하고 우디한 인테리어 덕분에 포근한 느낌도 들어서 편안한 식사가 가능합니다!', 44, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '가끔씩 커피만 마시다가 브런치맛있게 먹는 손님들 보며 오늘은 메뉴를 주문했는데 정말 맛있네요.브런치 맛집찾기 은근힘든데 맛있어서 싹싹먹었어요. 단점은 가격이 싸진않은것같아요😢 그래도 맛있고 친절하고 가게도 매력적이라 재방문할것같아요🙌', 35, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '늘 오고 싶었던 곳인데 드뎌 와봤다 오늘따라 사람이 많아서 조금 정신없지만 음식과 커피 모두 맛있어서 다른날 또와서 아늑하게 있고싶은곳이다', 43, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '넘 맛있어서 놀랐어요 ㅎㅎ 가든 브런치와 풀드포르케타 주문했는데 다음에 다른 메뉴들도 다 먹어보고 싶어요. 원래는 다른 메뉴 먹어보고팠는데 메뉴 이름을 헷갈렸는데도 맛났어요 ㅋ 특별한 날 데이트하기 좋네요', 3, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '음식먹다가 밑에 깔려있던 머리카락 나왔어요. 평점이 왜 높지?? 기본적으로 가게에서 일하는 사장 포함 모든 직원이 머리카락 다 나풀거리며 비위생적으로 음식을 만들고 계시네요. 차라리 머리카락이 빨리라도 발견됬으면 이런 음식 안먹었을텐데.. 그런데 더 어이없는건 주인 태도네요. 이미 비위 확상해서 이집에서 음식 더 먹고싶은 마음 전혀없지만 그래도 순서가 아직 접시에 음식이 남은상태에서 머리카락이 나왔으면 형식적으로라도 음식 다시해다드릴까요? 라든지 뭐 그에대한 적절한 대처를 하셔야지, "죄송합니다" 하고는 바로  쿠키하나 던져주고가네요. 정말 어이없네요. 쿠키먹고 닥치라고요? 그 비위생적인 식당에서 만든 음식을 내가 왜 더먹습니까? 그 쿠키 그대로 놓고 그냥  바로 나왔습니다. 모든것은 태도가 문제입니다!', 30, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '인테리어가 감성적이고, 외국인들이 많아서 우리나라 같지가 않아요! 그리고 다양한 나라의 음식들이 브런치로 준비되어 있어서 처음 접해보는 음식들 맛볼수 있어 좋아용', 88, 12, 'GOOD', SYSTIMESTAMP);
