INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '음식이 프레쉬하고 팔라펠이 맛있어요! 의외로(?) 커피도 맛집 ㅎㅎ 코코넛샤워인가 커피만 먹으러 와도 좋을 것 같아요. 인기 많음!', 15, 6, 'GOOD', SYSTIMESTAMP);
