INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고더티차이최고 양이 좀 적은 편, 맛은 무난한 브런치입니다~', 20, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '예쁘고 맛있는 브런치 카페 홍대 합정쪽에 오픈을 일찍 하는곳이 없는데 여기는 일찍 열어서 참 좋앗어요! 그런데 메뉴판에 설명이 텍스트만 가득해서 메뉴 검색을 해도 뭔가 그림이 잘 나오질 않아 주문하기 너무 힘들엇던것 같아요 ㅠㅠ 메뉴 혼돈으로 잘못 주문해버렷습니다(?) 팔라펠 플레이트는 원하던게 아니엿는데 이게 나와버렷어요 ㅋㅋㅋㅋ 메뉴판에 그림좀 넣어주세요 또 가고싶어요 🥺❤️', 338, 67, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '우와 진짜 너무 맛있어요!!! 😋😋😋 가격이 살짝 부담될수도 있다고 생각할수도 있는데, 이렇게 맛있는 쿠스쿠스는 진짜 오랜만이에요!! 👍👍 쿠스쿠스 샐러드에 빵 추가 해서 찍어먹는데, 정말 대박이에요!! 🥹😭😭😭😭 진짜 브런치 맛집인지 외국인들도 계속 들어와요.😋 대박인건 웜톤 베이스의 디자인인데, 스피커부터 실내 디자인이 대박이에요!! 👍👍👍', 14, 0, 'GOOD', SYSTIMESTAMP);
