INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '너무 맛있어서 처음에 메뉴 세개 시켰다가 다 먹고 두 개 더 시켰어요 진짜 한 입 먹자마자 반해버렸 ,,, 거의 10만원 가까이 쓴 것 같은디 전혀 후회없습니다 너무 맛있습니다! 인생 브런치 가게예요.. 오래오래 롱런해주세요 사장님', 55, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '비단 살롱 ㅡ 홍대 아날로그가든 브런치 맛집 지나가다가 사람 없는 틈을 타서 급 ~ 이렇게 먹지 않으면 늘 대기 모드라서 ^^ #아날로그가든 #브런치 #맛집 #홍대 #비단', 16, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '밖에서도 분위기가 좋았는데 안에도 분위기가 좋네요. 일반 브런치와는 다른느낌의 요리같은 브런치였습니다!-! 외국인이 많아서 정말 외국나온 분위기 물씬~ 가격은 비싸지만 브런치카페보다는 레스토랑에 가깝게 맛있고 배부르게 먹었습니다. 독특한 향신료향? 호불호 갈릴듯도 한데 저는 이색적이고 맛있고 좋았어요 ㅎㅎ', 48, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '운동끝나고 다음일정 사이에 시간이 남아 뭘먹을까하다가 브런치카페를 찾아오게 됫는데, 조용하고 혼자먹기도 너무 편한 공간이에요~ 가볍게 배 채우기 좋았어요! 다음엔 남자친구와 같이 올 예정입니다 :>', 24, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
