INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '여기는 아침에 브런치 먹으러 오면 너무 좋을꺼 같아요!! 제가 컴퓨터로 집중해서 일했어야 했던 날이라 이 카페를 골랐는데, 식사만 하러 오시는 분들이 많아서 그런지 매우 조용했고 집중하기 딱 좋았어요 커피도, 식사도 여기서 다 해결가능❤️ 인테리어도 너무 멋지고 다음에 또 가려구요!', 10, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '예전에 연남동에 살때 종종 갔는데 아주 오랜만에 들렸는데도 맛은 여전히 좋아요,,! 평일 한적한 시간에 들리면 아날로그 가든의 분위기를 더 잘 느낄 수 있을 것 같아요~✨✨🤩 팔라펠랩 맛도리!', 79, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '주말에 브런치 먹으러 갔습니다. 1시 정도에 갔고 따로 대기는 없었어요. 인테리어가 예뻐요. 매장 자체가 크진 않아요. 맛도 괜찮습니다.', 9, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '플레이트 팔라펠랩 커피등 먹었습니다. 좋았던점은 남향통창에 쏟아지는 햇살과 나무위주 인테리어, 음악등이 편안한 분위기를 줍니다. 음식은 개인적으로 쿠스쿠스등을 좋아해 나쁘지 않았지만 가격대비 구성이나 양이 흡족하진 않습니다. 화장실 밖에 있습니다. 주차공간 없습니다. 전반적으로 여자들끼리 적당히 분위기 좋게 대화나누기 좋은 브런치 카페는 될수 있을것 같습니다. 음식 위주로 방문하시기엔 부족할수 있습니다. 결정적으로 (2022.12.11기준) 음식 앞접시를 요청했는데 앞접시가 찻잔이네요. 당황해서 아메리카노 찻잔과 뒤집어서 확인까지 해봤습니다. ㅎㅎ 누군가에겐 신경쓰지 않고 지나갈 일일수도 있겠습니다만 제겐 그순간이 이 브런치 카페의 정체성이 박혀버린 순간이었습니다. (음식 위주는 아니구나)', 31, 1, NULL, SYSTIMESTAMP);
