INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '깔끔하고 좋은분위기였는데  옆에손님들이,, 사진찍고 돌아다니고 플레쉬터트리고 바닥에눕고 의자등받이 위에앉고,, 안말리시더라구요 ㅠ', 110, 26, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '이른 시간 식사할 곳을 찾다가 우연히 들어갔어요. 단일메뉴였는데 맛있었어요.  첫방문인데 그리 붐비는 것 같지도 않은데 추천하는 차 이름이 낯설어 설명 부탁했더니 퉁명스레 얼버무려서 그냥 커피 마셨네요. 가든에그스는 맛은 괜찮은데 가격대비 양이 너무 작더라는..  햄 추가까지 했는데 햄도 추가된게 맞는지 다시 한번 보게 되더라는..', 85, 18, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '브런치 진짜 맛있고 분위기 좋아요 💘 가든브런치 먹었는데 모자람 1도 없이 전부 다 맛있어요 양도 아침으로 먹기에 딱 좋았어요 🍽 창밖으로 보이는 풍경이 별거 없어두 그냥 힐링이에요 ~~ 월욜 점심 12시에 갔더니 웨이팅이 있었지만 5분만에 자리났어요 회전율 빠른편 !! 코코넛샤워 마셨는데 커피맛도 색다르고 맛있어서 다른 음료도 마시러 가보고싶어요 .. ❤️‍🔥❣️❤️', 41, 5, 'GOOD', SYSTIMESTAMP);
