INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '가든에그스와 폴브라운! 서교동에서 즐길 수 있는 아침 기회는 흔치 않은데 여기 아날로그 가든은 아침부터 분주합니다.☺️ 재료 준비상으로 모닝은 한가지 메뉴만 가능한데 아무것도 추가하지 않은 가든 에그스는 뚜렷한 개성이 있는 브런치 메뉴! 사실 착한 가격대에 속하는 편이라고 할 수 있어죠.ㅎㅎ 깔끔하고 건강한 플레이팅에 담백하면서 살짝🥗 매콤한 맛이 부담없이 즐기기 좋은 브런치메뉴! 계란과 치즈도 아낌없이 들어가고 향긋한 허브와 통후추가 계속 입맛을 돋아주어서 만족스러운 식사🍳 대표 시그니처 폴 브라운은 밑에 우유를 섞지 않고 그대로 마시는 라떼같은 느낌의 커피였는데 첫 맛을 달달하고, 끝맛은 커피의 쌉싸름한 맛에 두 가지 풍미를 느낄 수 있는 매력적인 메뉴! 잘 먹고 갑니다! 또 올게요~', 97, 19, 'GOOD', SYSTIMESTAMP);
