INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '팔레펠 랩은 처음 접했는데 신선하고 고소하고 맛있어요! 인테리어도 멋지고 직원분들도 친절하시고 주말 모닝 브런치 먹으러 가면 너무 좋아요', 89, 11, 'GOOD', SYSTIMESTAMP);
