INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '주문받는 머리 묶으신분이 사장님인가요? 서비스하실 때 말투 주의하셔야 할거 같아요 ~세요 ~하세요 하면서 고객에게 눈치 줍니다. 예민해보이심.. 인스타그램 사장 느낌', 27, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '팔라펠 등등 특별한 음식을 맛볼 수 있는 곳! 그렇지만 가격대비 양이 적어요 푸ㅠㅠㅠ 저날 먹은 풀드포르게타도 넘나 훌륭한 맛이었지만.. 먹고 배가 부르진 않았답니다', 19, 8, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '불친절합니다. 메뉴판을 제자리에 꽂아라, 일행 오면 들어와라.. 말투라도 친절했다면 기분나쁘진 않았겠죠. 일정 상 그냥 사먹긴 했는데 내 돈쓰고 기분나쁘긴 간만이네요. 기분 좋게 브런치하시려면 비추입니다.', 27, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '티라떼 매니아인데 독특하고 맛있네요 위어얹어진 크림은 꾸덕한 크림맛이랄까..다른종류의 크림맛도 있었으면.. 좀더 덜끈적거린 생크림맛도 소망해봅니다^^', 56, 15, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '메뉴가 특별하고 좋아요 주문하고 한 40분되도록 안 나와서 보니까 제가 주문한 걸 다른분한테 주셨더라구요...그래도 나중에 사과하시고 서비스 주셨습니다 ㅜ', 67, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '무슨 음식을 선택하시든 팔라펠 볼은 추가 해주세요. 양은 좀 적은 편이라 많이 먹지 않는 사람 기준에도 살짝 아쉬운 정도입니다. 커피보단 밀크티 맛집.', 72, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '코코넛 샤워 주문했는데, 직원분이 음료제조 도중에 엎으셔서 기다린거 그러려니 하구요. 먹으면서 지름 2cm는 족히 될법한 얼음 덩어리들 씹은것도 이번만 그랬으니 그러려니 하구요. 그런데 코코넛밀크 재료 넣으실때보니 알루미늄캔 그대로 오픈한채로 랩씌워서 보관하시는건 정말 이해되지않네요. 유해물질 때문에 가정에서도 개봉직후 별도 용기에 보관하는데. 오다가다 가끔 먹는데 이번에 처음 리뷰 써보네요. 다음부턴 아메리카노만 먹어야겠어요.', 13, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '맘이 편안해지는 곳이었어요 ^^ 두부(강아지) 보고싶었는데 ㅠ ㅠ 아프다고 해서 못봤어요ㅠ 언능 나았음 좋겠어요 다음에 또 가게 되면 봐야징', 29, 6, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '몇년전부터 잊을만하면 오던 곳이예요. 오랜만에 방문했는데 여전히 좋네요. 여기 브런치 정말 맛있어요. 화장실이 밖인 점만빼면 전부 다 만족스러원 곳이예요.', 52, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '랩에 고수가 들어있네요 ㅠ.. 메뉴판에 안 적혀있던 거 같은데 ㅠㅠ 포크로 고수 골라내면서 먹었습니다 ㅋㅋㅋㅋㅋ 그거 외엔 잘 먹었어요', 11, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '커피도 맛있고 분위기도 좋고 합정의 보물💖 합정 올 때면 무조건 여기 와요. 커피 원두가 두 가지라 산미 있는 거, 부드러운 거 둘 중 하나 고를 수 있는 게 참 좋아요 브런치도 맛있어요!!!', 38, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '분위기가 활발하고 자유롭고 반려견동반이 됩니다. 음식맛도 좋습니다. 여러 향료가 들어가 다른 곳과 차별화 되네요. 아쉬운건 양이예요. 그래도 플레이트 하나 12000원 가량인데, 밥 반공기 정도뿐의 배부름이라... 물과 식기도 셀프이던데 그러면 이 가격에 양을 좀더 늘려야 좋을 것 같아요.', 29, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '음식자체는 흔하지 않은 브런치였어요.독특한 향신료와 음료도 만족스러웠으나 처음 자리 배정되고 메뉴판도 주시지 않고 앞쪽에서 주문해달라는 말도 전달받지 못했습니다. 자리도 없다며 단호하게 문을 닫으셨죠.. 저희가 무슨 잘못한 줄 알았네요; 거기에 식기류 물 모두 셀프까지. 가격은 사실 저렴하지 않은데요 가격에 못미치는 서비스였네요.', 13, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '위치 접근성이 좋다. 테이크아웃 할인이 된다. 분위기가 좋다.라떼에서 진한맛이 약간 부족하다. 사람들이 몰리니 직원들끼리 손발이 안 맞는 느낌??', 50, 5, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'TERRACE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '분위기도 좋고 햇살 있을 때 가면 좋아요 가든브런치 맛있습니다! 직원 분들 친절하십니다. 아쉬운 점은 키 들고 밖에 나가야 공용 화장실이 있는데 좀 오래됐어요.', 21, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '커피도맛있고 가든브런치도 넘 맛있었어요.재방문하고싶을정도로 맛은 있어요. 다만 차도에 위치에 있는게 좀 아쉬웠어요. 문열어 놓으신데다가 바람부니까 먼지가 엄청들어와서 음식먹을때 당황스러웠네요.', 22, 8, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '원래가려던 브런치집이 닫혀서 우연찮게 찾은 집인데 맛도 신선했고 가격도 착하고 새로운음식 맛있게먹었습니다. 좌석이 많지는 않았고 둘이 오붓하게 먹기엔 좀 불편한 자리인거 빼고는 음식은 너무 좋습니다.', 48, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '분위기가 엄청 예쁜 카페는 아니지만 괜찮았고 잉크블랙이라는 민트초코 시그니처 음료 먹었는데. 이게 맛있었어요 다른 카페 민트초코랑은 다른 맛이었는데, 엄청 달지도 않고 좀 더 민트맛이 시원하게 나는 그런 맛이었어요 잉크블랙이 생각나서 종종 들를거 같아요', 213, 42, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아날로그가든'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '밀크티를 정말 좋아하는데 밀크티가 정말 맛있어요 그리고 분위기가 나쁘지 않습니다 제가 갔을때는 사람이 없어서 좋았어요 사람이 많을때는 어떨지 모르겠네요 레이식당 가는 길에 있으니 두 곳을 한꺼번에 가는 것도 좋을거 같아요', 37, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '케이클링'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '당일에 네이버예약했어요! 그냥 가벼운 기념?으로 케이크는 하고싶은데 그렇다고 큰거는 필요없고(오직 사진용ㅎㅎ) 가격 너무 만족해요! 문구 문의를 해보니, 한글 10글자/ 영어 20글자 라고 합니다- 우유크림? 맛있게 먹었습니다~ 친절히 대응해주셔서 감사합니당♡', 88, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사계의숲'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '이름이 참 예쁘지요? 네이버 검색해서 가고 싶은 카페로 저장해 놓은 곳이었습니다. 홍대입구역 7번 네이버지도 따라 조금 걸어오면 쉽게 찾을 수 있는 신상카페입니다. 바치케 전문이라니....다이어트 중인데 잘 못 왔군...싶으먼서도 귀엽고 예쁜 장식들에 정신이 팔려 나도 모르게 바치케를 주문... 계속 두리번거리며 홀을 둘러봅니다 내가 좋아하는 일본애니 중 하나인 토토로..달력도 손님이 없으므로 막 넘겨보기도 합니다. 눈으로만 보세요...라고 써 있는 장식을 세상 불쌍한 표정으로 한번만 만져보게 해 주세요..해보고... 시력이 나쁜탓에 뭔 떼어진 스티커를...했더니 "오늘의 운세. 행운이 와르르~~" 갑자기 미소지어지며 기분이 좋아집니다. 이건 폰케이스에 넣었습니다. 부드러운 바치케와 커피로 잘 쉬었다갑니다', 11, 10, 'GOOD', SYSTIMESTAMP);
