INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사계의숲'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '카페가 너무너무 귀여워요 ~~ 🤍🤍🪽 사진 찍을 곳도 나름 많고 직원분들도 친절하셨어요 ♥ 디저트는 종류가 별로 없는 것 같아용 치케 꾸덕하고 맛있었어요 🤍 웨이팅 처음에는 없는 줄 알았는데 나중에 나가려고 보니까 꽤 있는 것 같아요 ..! 매장 시원하고 좋았습니다 ~ ♡', 17, 1, 'GOOD', SYSTIMESTAMP);
