INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사계의숲'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '공간이 너무 아늑하고 편안해서 좋아요. 창가 좌석에서 혼자 작업하기 좋습니다👍 사계라떼랑 바닐라라떼 마셔봤는데 둘 다 되게 맛있습니다☕️ 자주 들릴 것 같아요~', 14, 8, 'GOOD', SYSTIMESTAMP);
