INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사계의숲'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '세가지 메뉴를 먹어봤는데 다 맛있네요! 진한 초코라떼 맛이라 좋았고 바치케도 홍대에서 탑급이에요ㅎㅎ 파르페는 귀엽고 딸기 좋아하시면 추천드려요~ 귀여운 소품도 많아서 친구랑 오기 좋은 카페에요 잘 마시고 갑니다 사장님😋', 42, 5, 'GOOD', SYSTIMESTAMP);
