INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사계의숲'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '초코타르트는 꾸덕하고 부드러운 생초콜렛을 먹는 느낌이었고 바치케는 특별히 다른점은 없었습니다. 덕후들을 위한 공간이라 플레이리스트가 일본노래 위주로 나오고 한켠에는 피규어나 아크릴스탠드 등 꾸며져있는 공간도 있었습니다. 거대한 초록인형을 마주보고 오른쪽에 두번째 자리는 에어컨 순환기가 돌아가서 조명이 깜박거리게 보여 눈이 아팠습니다. 음료도 전반적으로 괜찮고 디저트도 괜찮았습니다. 바테이블에 콘센트가 있는 좌석도 있어서 공부하시거나 일하시는분들도 계셨습니다. 메인거리랑은 좀 떨어져 있어서 조금 걸어야하지만 그만큼 사람이 많지 않아 바로 앉을 수 있었습니다.', 5, 9, 'GOOD', SYSTIMESTAMP);
