INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사계의숲'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '두 번째로 방문한 홍대 사계의 숲! 다른 음료들도 다 맛있지만, 저는 특히 아이스 바닐라 라떼가 좋았어요! 깔끔하면서도 바닐라 풍미가 가득해서 정말 "너무너무" 맛있었습니다. 사장님께서 매장에서 직접 만드시는 치즈 바스크 케이크도 겉바속촉 너무 맛있었어요. 카페 곳곳에 놓인 귀여운 피규어들과 아기자기한 소품들을 구경하는 재미도 쏠쏠하고, 예쁜 포토존도 마련되어 있어서 사진 찍기에도 좋았어요. 스탭분들의 센스가 곳곳에서 느껴지는 공간이었습니다. 홍대에서 분위기 좋고 맛있는 카페를 찾으신다면 사계의 숲 추천합니당!', 38, 4, 'GOOD', SYSTIMESTAMP);
