INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사계의숲'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '너무 더워서 찾은 곳인데 직원분도 너무 친절하시고 인테리어도 귀여워서 좋앗더요 디저트 수제로 만드시는 거 같은데 담에 방문하면 꼭 디저트도 같이 먹을거임', 2, 1, 'GOOD', SYSTIMESTAMP);
