INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사계의숲'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '오늘 커피를 많이 먹어서 달달한게 땡겨서 초코라떼로 주문했는데..  제티맛나고 별로인 카페 많아서 걱정했는데 여기는 진하고 고급진 맛이 나요 🍫 피규어 한바가지 있어서 님의 최애를 찾아보세요. 수준이라 오늘은 혼자 왔지만 담에 친구들이랑 와서 오타쿠 진.대 예정입니다 ㅎㅎ 우연히 지나가다 간판이 귀여워서 들어왔는데 내부도 깔끔하고 음료랑 케익도 맛있어서 자주 올것같아요! 오늘의 운세로 길가다 최애 만남이 나와서 열심히 돌아다녀볼 예정입니다 🍀', 69, 12, 'GOOD', SYSTIMESTAMP);
