INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사계의숲'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '신상카페라서 와봤는데 머야 어기,,너무 기여워요,,🤍🤍매장인테리어도 귀업고 커피도 아주 맛있습니당!! 스피커 좋은거 쓰시는지 음악도 너무 좋아요 홍대오면 자주 오게 될 것 같아요🧸🤍', 43, 0, 'GOOD', SYSTIMESTAMP);
