INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사계의숲'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '사계라떼 무조건 드세요!!!!!!!! 카페라떼 마시려다 추천해주셔서 시그니처 마셔봤는데 진짜 너무 맛있어요,, 인테리어도 예쁘고 치즈케이크도 👍🏻', 95, 20, 'GOOD', SYSTIMESTAMP);
