INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사계의숲'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '카페가 가오픈이었지만 매장 분위기도 정돈되어 있고 인테리어가 너무 예뿌고 음악이 진짜 좋았어요..! 스피커가 엄청 많아서 그런지 음악 듣기가 너무 좋았습니다 그리고 인테리어도 오타쿠 친화적이라서 혼자 갔는데도 구경하고 사진찍고 넘 즐거벘어요,,! 다음에 친구들 많이 데리고 가서 놀아도 재밌을 것 같아요. 우유 못 마시는데 오트밀크 변경도 가능하고 직원분들이 메뉴 설명도 친절하게 해주심! 굿굿댜 시그니쳐 메뉴들도 종류가 많던데 다음엔 또 다른 시그니쳐 메뉴들 먹어보고 싶네용 번창하세요!!', 61, 17, 'GOOD', SYSTIMESTAMP);
