INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사계의숲'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '일단 커피가 맛있어요 좋은 원두쓰신다고 느껴집니다 치즈케이크도 맛있습니당 ㅎㅎ 원래 후기 잘 안남기는데 홍대에서 간만에 쾌적한 카페를 찾아서 남겨봅미다 ㅎㅎ 화장실도 매장안에 있어요👍🏻', 67, 18, 'GOOD', SYSTIMESTAMP);
