INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사계의숲'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '가오픈 기간에 다녀왔어요🥰 시그니처 커피인 사계라떼 마셨는데 인생라떼 발견🥹 보통 라떼와는 다른 꾸덕함이 있어서 카페라떼 좋아하시는 분은 좋아 하실 것 같아요☕️ 바치케도 너무 맛있습니당 커피 드신다면 함께 꼭 드셔주세요', 54, 13, 'GOOD', SYSTIMESTAMP);
