INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사계의숲'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '시그니처메뉴 사계라떼 너무 맛있어요💚 다른곳에서 먹어볼 수 없는 맛!! 치즈케이크랑 조합이 최고입니다 👍 인테리어도 너무 예뻐요~~! 홍대 커피 맛집 사계의 숲 단골 예약입니다💚🌲 더 번창하세요~~~! 🙏', 26, 2, 'GOOD', SYSTIMESTAMP);
