INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사계의숲'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '사장님 중 한 분이 블로그 이웃이라서 소식듣고 가오픈 기간(~4월30일까진 6시까지) 들렀어요. 포토존 인형 피규어 콜렉션에 눈이 휘둥그레~~ 가구와 인테리어도 멋져요. 그리고 플레이리스트 아주 좋아요. 제이팝과 밴드 좋아하시는 분들은 귀호강하실 거에요. 이날 들은 플리 ♬ 글렌체크 - addicted 7co - unmellow 스테이시 오리코 - stuck 이고도 - 우리 같은 사람들 스킵잭 - heartplant kiii kiii - i do me 오피셜히게단디즘 - tattoo 인디밴드 공연장과도 가까워요 - 생기스튜디오, 스페이스한강, 구름아래소극장,  AOR, 클럽빵, 우주정거장, 언플러그드서교 찬 걸 못 마셔서 말차라떼. 디저트 개시전이라 서비스로 주신 크래커와 크림치즈도 고맙습니다', 24, 6, 'GOOD', SYSTIMESTAMP);
