INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사계의숲'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '지나가다 우연히 들어왔는데 내부는 빈티지하고 아기자기한 소품들로 가득해서 구경하는 재미가 쏠쏠했고, 시그니처 커피도 맛있고 초코타르트는 황홀 🥺', 44, 0, 'GOOD', SYSTIMESTAMP);
