INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '사계의숲'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '사장님도 친절하시고 음료도 너무 맛있어요 !! 인테리어도 제 취향 🫶🏻🫶🏻 아기자기한 소품샵 온 기분이네용 노래선곡도 좋아요 자주 올 것 같아용 ㅎㅎ', 47, 10, 'GOOD', SYSTIMESTAMP);
