INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 홀리데이'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '정신이 없다 보니 늦은 리뷰를 남기네요. 얼마 전 소중한 장르 속 애정 어린 캐릭터의 생일파티에 참여했는데 카페에 꾸며진 장식들도 멋지고(주최자분들이 전 날 열심히 꾸미셨더라고요. 고생하셨습니다) 음료와 디저트들도 맛나고(마카롱도 에이드도 커피도 빠지는 것 없이 맛이 좋았습니다) 함께 참여한 분들도 반갑게 맞아주시니 분위가 너무 포근하더라고요. 카페 마감 전 게임으로 획득한 등신대를 비가 내리던 날 어떻게 가져가야 하나 걱정했는데 카페 사장님의 도움으로 안전하게 포장할 수 있어서 집까지 잘 올 수 있었습니다. ^^//♡ 근사한 하루를 보냈어요~ 감사합니다.', 40, 3, 'GOOD', SYSTIMESTAMP);
