INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 홀리데이'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '공간이 넓은 편은 아니었지만 깔끔하고 예뻤어요! 아기자기하게 꾸며진 카페에서 넘넘 행복한 시간 보냈네요🫶 사랑하는 나은언니 생일 축하해!💚', 56, 17, 'GOOD', SYSTIMESTAMP);
