INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 홀리데이'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '뭔 펜카페인가봐요? 좋아하는 아티스트 생일잔치해주던 곳 같은? 규모는 엄청작고 음료나 쿠키도 한정적이네요 뭔 세트라고 해서 시켰더니 엽서같은 크기에 사진같은거 주네요 애들 홀려서 한판에 천원주고 뽑기하는데 진심 말리고싶네요 그돈으로 차라리 원하는걸 사지... 쩝 카페를 관리 하시던가 시스템을 좀 바꾸던가 개선이 필요할듯해요', 34, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 홀리데이'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '생일 카페 방문하려고 찾아갔었어요! 내부가 너무 사랑스럽게 꾸며져 있어서 그런지 들어와서 보기만 해도 기분이 좋더라구요 ㅎㅎ 깨끗하고 시원해서 친구랑 기분 좋게 갔다 왔습니다~~', 4, 10, 'GOOD', SYSTIMESTAMP);
