INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 홀리데이'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '쟈니 루키즈 카페 다녀왔어요~ 매장 안이 꽤 넓어서 좋아요 사장님도 친절하시구 음료도 넘 맛있었어요 핑크레몬에이드 콜드브루 둘다 맛있습니다', 45, 1, 'GOOD', SYSTIMESTAMP);
