INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '귀여운푸딩이 탱글탱글 쫀득쫀득해요 비싼듯했는데 먹어보니 비싼이유가 있네요 천겹빵과 카이막은 진짜 잘어울려요 카이막은 먹을수록 먹고싶은 매력이 있어요 카페는 크지 않지만 루프탑에서 경의숲길바라보며 앉아있기 좋아요', 69, 11, 'GOOD', SYSTIMESTAMP);
