INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '여기 카이막 좋아해서 자주 와요! 다른 곳보다 카이막이 더 꾸덕하고 쫀득한 느낌 너무 좋아요 늘 ㅎㅎ 근데 오늘은 바게트빵이 좀 오래 됐는지 푸석푸석하고 딱딱했어요!! 빵 좀 신경써주세요🥹 멜론 소다는 언제 먹어도 맛있으니까 패스구요 ㅎㅎ 그래도 여기 분위기가 되게 아기자기해서 친구랑 이야기하기 딱 좋은곳이에요! 오늘은 좀 실망했지만 그래도 들릴게요 종종', 82, 14, NULL, SYSTIMESTAMP);
