INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '가게가 아기자기한데 3층까지 있습니다. 잠깐 쉬려고 들렸는데 카이막에 귀여운 고양이 푸딩도 있었습니다. 오늘은 목 축이려고 차만 마셨지만, 다음엔 다른 메뉴들도 도전해보고 싶습니다.', 124, 26, 'GOOD', SYSTIMESTAMP);
