INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '생딸기 카이막 모찌 4,500원 모찌가 먹고싶어서 방문했어용! 매장이용은 음료 주문이 필수라고 하셨어용! 저는 밖이 너무 추워서ㅜㅜ 양해구하고 급하게 1층에서 한입컷했습니당!🥹 달달구리 딸기 모찌 맛있어용~! 위에 자리도 깔끔하고 좋을 것 같아요!😀', 81, 11, 'GOOD', SYSTIMESTAMP);
