INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '혼자와서 포장으로 4잔 주문했는데, 커피캐리어 없이 4잔 주는…황당해서 담아줄 캐리어 없냐니까 그제서야 비닐봉투 주는^^ 다른카페에 사람이 많아서 간건데 다시는 안갈듯…심지어 커피맛도 그냥 그냥…', 28, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '괜찮은 카페였어요! 가격이 저렴하다는 아니지만 분위기도 괜찮은 편이고 대화나누기 좋았어요! 화장실 깨끗하고 만족합니다!!! 카이막 천겹 세트??? 그냥 괜찮은 맛🤔 엄청 특출나게 맛있다는 모르겠고 맛있었어요 ㅋㅋ😉하하', 36, 7, 'GOOD', SYSTIMESTAMP);
