INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '음? 카이막두바이초콜릿 시켰는데 그냥 두바이 초콜릿 주셨네요 그리고 두바이찹쌀떡도 그냥 냉동식품 먹은 두바이 초콜릿도 카다이프 눅눅하고 맛없어요', 30, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '부산에서 강원도로 여행에서 서울을 경유해서 여행했는데 거기서 찿은 예쁜 커피숍 여기는 두바이 초코렛메뉴도 있었고  이쁘게 탱글탱글하게  빚어진 고양이모양의 젤리 디저트도 있었다. 초코젤리와 딸기젤리를 주문했는데 베리시럽을 뿌려먹는 딸기젤리가 더 맛있었던것같다 특히 3층발코니에서 먹기를 추천함. 음료도 맛있었고 디저트도 맛있게 먹었고 예쁜 카페에서 추억도 쌓아감', 40, 2, 'GOOD', SYSTIMESTAMP);
