INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '소금빵을 사고 나니 커피가 너무 먹고 파서 바로 길 건너에 있는 커피집을 갔는데 산미 가득 맛난 아아를 먹게되었어요~ 앞에 공원에서 먹으니 꿀 맛입니다!', 16, 4, 'GOOD', SYSTIMESTAMP);
