INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '문을 열고 들어서면 맡게 되는 엄청난 악취.(카이막 때문에 나는건가 싶었으나 1,2층의 화장실 냄새임. 여기서 일하는 직원이나 2층에서 그 역한 냄새 속 먹는 사람이나 비위가 대단함. 카페의 향이라고 할 수 없음.) 음료와 카이막은 괜찮았으나 역한 냄새, 2,3층에 직원이 한 번도 올라가지 않기에 여기저기 흘려있는 빵가루, 불친절한 직원을 생각하면 절대 갈 이유가 없다고 봄. 평소 리뷰 작성 안 함. 난 3층 루프탑을 이용했고 처음엔 정말 카이막 만드는 냄새인가보다 생각했기에 들어간 거임. 아직도 속이 역한 느낌임. 매장 청결에 관심이 필요함', 11, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '홍대 카이막 맛집 미크플로에 다녀왔습니다~ 사실 같은 카페를 이렇게 많이 가본곳도 없는데 이곳은 바게트, 카이막 세트가 너무 맛나 계속 생각나 계속 가게되는 곳입니다. 이번에도 변함없이 바삭바삭한 바게트 위에 꿀첨가한 카이막 올려서 먹으니 넘넘 맛나고 카이막라떼는 그냥 사랑이네요! 너무 맛있었어요~', 57, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '진짜 최악이네요 롤카이막이라고 이름 붙이고 업체 이미지도 그렇게 등록해놓고 막상 키오스크로 주문하고 야외에서 받은거라 종이봉투에 포장해줘서 내용물을 못 봤다가 나중에 꺼내보니 롤은 커녕 아이스크림마냥 퍼서 담아줬네요 카이막 파는 곳 많은데 굳이 미트플로에 간건 “롤카이막”이라고 했으니 간겁니다 이정도면 허위광고 아닌가요', 21, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '두바이 초콜릿 궁금해서 들려봤는데 두바이초콜릿은 품절이고 , 두바이카이막 초콜릿은 있어요! 가격이 7500원이지만 퀄리티 좋아보이고 1층에서 키오스크로 주문할 수 있어서 편해요~', 57, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '두바이 초콜릿🍫 내용물이 알차서 가격이 아깝지 않았습니다! 카다이프와 피스타치오 스프레드가 많이 들어있어서 정말 맛있게 먹었습니다🐷', 49, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '갑자기 비가 너무 많이 내리던 주말, 연트럴파크 근처의 카페로 피신하듯 들어갔었는데 생각보다 좋아서 만족스러웠어요. 내부가 전반적으로 예쁘고 구름 캐릭터도 귀엽고 3층 루프탑 공간에서 빗소리 듣는 것도 좋았어요. 주문은 아메리카노(4500원), 카이막단품(8000원)으로 해봤는데 아메리카노는 적당히 진한 맛이었고 카이막은 크림치즈+그릭요거트 같은 느낌으로 쫀득쫀득하고 고소한 맛이더라구요. 사실 요게 빵이랑 같이 꿀에 찍어 먹는 게 보통인 것 같았는데 저희는 너무 배가 불러서 도저히 양 많은 디저트는 먹기 힘들 것 같고해서 카이막을 아이스크림처럼 먹었어요..ㅋㅋ 아이스크림 한스쿱에 8천원은 좀 세다 싶지만 유니크한 메뉴라고 생각하니 나쁘지 않았습니다~', 125, 23, 'GOOD', SYSTIMESTAMP);
