INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '두바이 초콜릿 🍫 연남동 카페에서 팔길래 사봤어요 아이가 먹고싶다해서 구매했는데 작은 초콜릿 하나 가격이 후덜덜하네요 아이가 맛있다고 하는데 다음엔 안먹어도 될 것 같다고 😅 직원분은 그리 친절하진 않은 것 같아요', 25, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '푸딩 왕짱 귀엽고ㅠㅠ 기대 이상으로 진짜 맛있어서 놀랐어요😳🫢 우유 맛이 녹진하니 카이막도 맛있을거 같네요 요즘 카페 생각하면 가격도 괜찮은 편, 커피도 구수함! 루프탑 전망도 좋고 에어컨도 있어서 완전 좋았슴당 다만 계단이 좀 살벌 ㅋㅋ 근데 1층에 에어컨 청소 하셔야•• 냄새가 너무 나요 더럽고', 32, 9, 'GOOD', SYSTIMESTAMP);
