INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '카이막이 진짜 맛있네요. 소금빵에 먹었는데 진한우유맛이 담백하니 빵에 발라먹기 딱 좋아요. 3층은 통창이라 홍대거리가 다 보이고 저녁노을 보면서 있기 좋아요', 34, 8, 'GOOD', SYSTIMESTAMP);
