INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '푸딩과 음료는 아주 맛잇엇어요 하지만 소금빵은 별로엿어요 이걸 소금빵이라 하면 무덤에 있는 소금빵의 조상님이 격노하면서 일어나실것 같아요 먹으면 먹을수록 화가 나여 푸딩만 드세요', 50, 2, 'BAD', SYSTIMESTAMP);
