INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '카이막을 판매해는 미크플로입니다.🥛 지나가다가 우연찮게 카이막을 파는 거 보고 호기심에 방문했습니다. 백종원의 스프푸2에서 보면서 먹어보고 싶다고 생각했는데 이걸 이렇게 먹게 되었네요.🤣 카이막 단품으로도 주문 가능하고 세트로 해서 소금빵이나 베이글을 포함해서 주문도 가능합니다. 처음 먹어보는 카이막인데 소금빵에 발라먹으니 신기한 맛이었습니다. 치즈보다는 우유에 가까운 맛이 났고 비쥬얼로는 아이스크림에 가까운데 꾸덕하더라구요.🤩 다 좋았지만 소금빵의 경우에는 좀 빨리 식었다고 해야하나, 그게ㅜ좀 아쉬었네요😂', 72, 16, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '드디어 카이막 영접했답니당~ 자태가 너무도 아름답져^^ 무슨맛일지 두근두근~ 3층까지 통으로 되어있는 건물도 너무 예뻐용👍 카이막 소금빵세트를 시켰어요 소금빵안에도 버터가 가득 녹아있어 풍미가 대박이에여 달콤한 꿀을 살랑살랑~~ 난 돼지니까 많이 발라 먹을거에요 와구와구~~ 아 이게 천상의 맛인가요? 진짜 부드럽고 은은한 우유맛에 반해버렸어요 이래서 카이막 카이막 하나봐여🤭 소금빵 하나를 순삭해버렸어여😄 또 오고 싶은맛! 카이막 죠아여😋', 9, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '푸딩 댕댕하고 맛있어여. 카이막라떼도 맛있구여 ! 카이막 모찌도 맛있어여 ( 전에 먹고 포장까지 )  오늘은 배불러서 패스 ~', 3, 10, NULL, SYSTIMESTAMP);
