INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '두바이초콜릿(7500원) 먹었어요. 난생 처음 먹은 거라 기대를 했는데 크기가 너무 작아서 1차 충격ㅋㅋ 겉 초콜릿은 되게 맛있었는데 안에서 피스타치오 맛이 거의 안 났어요ㅠ 카다이프의 바삭바삭한 식감으로 인해 먹는데 소리는 와그작와그작 나는데 막상 피스타치오 맛이 안 나니까 그냥 바삭바삭한 초콜릿 먹는 느낌… 피스타치오 함량을 늘리셔야 할 것 같아요.', 11, 8, 'BAD', SYSTIMESTAMP);
