INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '연남동 길을 걷다가 귀여운 고양이 모양의 푸딩이 살랑거리는 모습을 보고 매장으로 들어왔습니다. 푸딩은 아이들 주려고 포장하고, 매장에서 그래놀라 카이막 호떡과 얼음 동동 시원한 밀크티와 아메리카노 마시며 좋은 시간 보냈습니다.', 14, 3, NULL, SYSTIMESTAMP);
