INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '초코펜 이벤트로 푸딩에 얼굴 그려주기 대성공😉 초코푸딩에 라떼, 아메리카노해서 먹었는데 궁합 괜찮네요. 푸딩은 꽤 커서 친구와 나눠먹기에 딱 적당했어요! 움직이는 거 넘 귀엽고ㅋㅋㅋ 어린이들도 참 좋아할 거 같네요(실제로 옆에서 애기가 꺅꺅 좋아함ㅋㅋ)🫧', 3, 7, 'GOOD', SYSTIMESTAMP);
