INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '우유푸딩이 궁금했는데 솔드아웃이라 초코푸딩으로 시켰어요 오모나~ 맛있지 뭐예요 콩포트처럼 사이드 주시는거 얹어먹으니 더 맛있네요 커피도 생각보다 괜찮았어요 초딩 자녀와 갔는데 좋아하네요 모찌도 맛있어요 근처가면 또 방문의사 있어요', 25, 6, NULL, SYSTIMESTAMP);
