INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '릴스에서만 보던 토끼우유푸딩을 드디어 먹어보네욤! 골목 들어갈 필요없고 큰길에 위치하기 때문에 찾아오시는데 어려울 일 없는 위치였습니당 우유푸딩이랑 망고잼 같이 먹으면 달달한 망고 우유 아이스크림 맛도 나요 맛있어용 리치에이드는 말해뭐해 넘 달달 시원..😍 루프탑 이용하진 않았지만 바깥공기 맡기 좋은 공간이더라구요!', 86, 18, 'GOOD', SYSTIMESTAMP);
