INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '커피도 푸딩도 너무너무 맛있어요! 다음에 올 땐 카이막도 먹어보고 싶어요~!! 귀여운 고양이 푸딩이랑 행복한 시간 보내고 갑니다!', 40, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '저번에 너무 맛나게 먹었던 카이막이 생각나서 오랜만에 연남동 온 김에 재방문한 미크플로~ 카이막 라떼와 세트를 시켰고 정말 맛있게 즐겼습니다. 달달한 카이막 라떼도 유니크하면서 너무 맛있고 겉바속촉한 바게트에 꿀에 적신 카이막을 발라먹으면 정말 환상적인 맛을 다시 한 번 느낄 수 있었어요~', 24, 1, 'GOOD', SYSTIMESTAMP);
