INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '우연히 지나가다가 들어왔는데!! 푸딩!!! 푸딩 너무 귀엽고 미쳤어요....!!!!! 세상에..눈도 입도 너무 즐거운 푸딩이었습니다ㅋㅋㅋ', 41, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '천상의 맛이라는 카이막 .. 무슨맛인지 모르겠어요 ㅋㅋㅋㅋ 꾸덕하고 안 단 연유같은맛 .. 만천원 .. 너무 비싸지만 한번쯤 먹어볼만 했고 다시 먹지는 않을 것 같아요', 17, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '연남동 오면 들리게되는 미크플로... 그리고 계속 생각나는 그 카이막 세트! 오늘도 카이막 세트 시켜서 맛나게 먹었답니다. 카이막, 꿀 조합은 말해뭐해고 바게트빵이 너무 제 취향이고 맛나요! 이런 빵에 꿀이막 발라먹으면 그냥 끝난거죠ㅎㅎ 미크플로 너무 좋습니닷! ༼๑0⊖0๑༽❤', 101, 24, 'GOOD', SYSTIMESTAMP);
