INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '지나가다가 인스타에서 유명한 고양이 푸딩이 있어서 방문… 완전 찐한 밀크 푸딩이어서 좋은 거 같아요 그리고 3층 루프탑까지 있어서 자리가 은근 많았어요 친구랑 또 방문 하고 싶은 곳 입니다', 101, 26, 'GOOD', SYSTIMESTAMP);
