INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '카이막 한번도 못 먹어봐서 늘 궁금했었는데 드디어 먹어봤습니다~!! 카이막세트 소금빵으로 선택하고 아아랑 파인애플 스무디 마셨어요😁☺️ 카이막은 양이 엥??이게뭐지?ㅋ이렇게 조금 나온다고?싶었는데ㅋㅋ 소금빵에 발라먹고 남아서 카이막만 따로 먹었어요~!! 흠 엄청엄청 궁금했었고 기대했는데 첫입은 엥??이게 무슨맛이지?였어요ㅋ 그래서 꿀 왕창 뿌렸는데 그래도 이게 무슨맛이지?ㅋ 말로 설명하기 힘든데 전 솔직히 무슨맛인지 잘 모르겠더라구요ㅋ 매장은 아기자기해요ㅋㅋ 3층 루프탑도있고', 99, 24, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '예전부터 먹고 싶었는데 드디어 먹는데 너무 맛있어서 행복합니다! 담에 또 먹으러 오겠습니다!!!❤️🥲☺️😵‍💫😵‍💫🚂☺️😵‍💫👍🏻👍🏻👍🏻👍🏻', 27, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '카이막 먹어보러 들린 미크플로! 카이막 첨먹어봤는데 요거 크게 달지도 않고 상당히 맛있네요~ 꿀 발라서 바게트 빵과 먹으면 진짜 극락~ 너무 맛있어요! 그리고 카이막 라떼 요건 베스트 음료답게 맛 진짜 좋아요~ 카이막 첫인상을 너무 좋게 만들어준 집입니다. 모찌는 다른 집에서 컷당해서 못먹어서 아쉬움을 달래기위해 시켜봤네요ㅎ 요 근래 간 카페중에서 가장 맘에들었어요! 잘먹었습니다~', 30, 0, 'GOOD', SYSTIMESTAMP);
