INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '소금빵+카이막 11,000원 백종원 아저씨가 맛있다고 너무 호들갑을 떤건지…. 그냥 꾸덕한 생크림이던데.. 드실거면 빵은 바게트로 하세요 6조각은 나오더라구요 맛에비해 너무 비쌈 ㅠ', 7, 8, 'BAD', SYSTIMESTAMP);
