INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '블루베리 카이막 요거트 스무디는 사랑이에요💜 스무디 헤비해서 잘 안 찾고, 특히 블루베리 스무디는 인위적인 맛 나는 경우 많아서 거의 안 사 먹는데... 미크플로 거는 갈 때마다 먹는 편이에요ㅎㅎ 최고👍', 5, 9, 'GOOD', SYSTIMESTAMP);
