INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '용산 아이파크몰 팝업 스토어로 이용했어요. 카이막이란걸 처음 먹어보는데요. 우유향 강한 스프레드 같더라구요. 그래서 고소함 + 우유향이 너무 좋아요. 그리고 카이막 크림 모찌도 카이막 특유의 우유향이 가득해서 진짜 맛나요.', 8, 0, 'GOOD', SYSTIMESTAMP);
