INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '처음 먹어보는 카이막이어서 어떻게 먹는지 모르고 그냥 베이글에 발라 먹었는데 옆에 꿀이 있어 카이막 위에 뿌리니까 카이막의 맛이 한층 더 맛있고 꾸덕했던 카이막이 조금 부드러워지고 달달해져 먹기 좋았어요 그리고 파인애플 스무디 최고', 1, 8, 'GOOD', SYSTIMESTAMP);
