INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '마감 직전에 가서 푸딩은 없었지만 4개세트 괜찮다고 하더라구용! 예.. 인테리어도 아주 귀엽고~ 푸딩 너무 귀엽고 보지는 못했지만...담기회에', 12, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '카이막 처음 먹어봤는데, 이렇게 맛있는거였다니…!! 완전 반했습니다 진심 또 먹고싶어요 🥰 진한 우유풍미에 부드거운 그릭요거트 식감인데 찐으로 맛있음ㅇㅇ 그냥 먹어도 담백하니 맛있고 꿀시럽 뿌려먹으면 달콤해서 완전 꿀맛이네요!! 바게트빵 자체도 맛있어서 카이막 발라먹으면 계속 먹게되는 중독성이 있어요 😋 겉바속촉 바게트빵에 카이막 조합은 사랑입니다 👍 비싸지만 또 사먹고싶은 맛…🤣 카이막라떼는 조금 달콤하고 부드러운 라떼느낌인데, 씁쓸한 커피 잘 못드시는 분들도 먹기 좋은거 같습니다. 메론소다에 바닐라 아이스크림이 넘 잘어울려요💚 카이막 모찌는 달콤담백한 크림떡맛이었어요. 사실 카이막맛은 잘 모르겠고 맛있난 크림떡 스타일입니다. 쫀득한 떡 속에 부드러운 크림은 말해뭐해죠 😆', 2, 9, 'GOOD', SYSTIMESTAMP);
