INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '우리나라에서 먹어보기 힘든 카이막을 터키 직수입으로 먹어볼 수 있는 곳! 천상의 맛 카이막 너무 궁금했는데 우유지방맛이 옴청 진하게 나는 크림+버터 느낌이었음!! 빵에 발라먹으면 맛있고 카이막라떼는 좀 더 고소한 맛이 나는것 같은데 카이막 본연의 맛이 궁금하다면 라떼보다는 카이막세트로 추천!', 9, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '카이막 투어 중입니다 ~ ~ 연남 미크플로 카이막 직수입(?) 하는 곳이라길래 달려와쑴니당 베이글은 단 맛이 같이 난다구 해서...? 바게트로 먹었는데 바게트가 뭐랄까 넘 바삭해서 잘 부서지더라고용 아쉬웠지만 카이막은 정말 맛있네여. . .', 32, 2, 'GOOD', SYSTIMESTAMP);
