INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '연남동 들렀다가 카이막 모찌 특이해서 구매해봤어요! 맛있고 귀여운 카이막모찌,, 연남동 갈때마다 간식으로 하나씩 사먹을거에용💕', 41, 2, 'GOOD', SYSTIMESTAMP);
