INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '카이막 전문점. 카이막 라떼 6500원 카이막 세트 10000원 총 16500원 터키의 카이막 먹는 영상을 보고... 홍대근처에서 찾다가 발견한 곳. 진짜 신선 그 자제. 넘 맛나요. 맨날 가고 싶긴 한데.. 가격이 후덜덜..ㅎㅎ 그래도 가끔 가서 먹을 만 합니다. 맛있어서요 ㅎ', 35, 2, 'GOOD', SYSTIMESTAMP);
