INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '카이막 처음 먹어봤는데 고소하고 맛있어요 크림치즈같은데 크림치즈보다는 좀 담백하다고하나... 근데 넘길때 뭔가 끈적이는 그런 느낌이 있음 베이글에 발라먹으니까 딱 잘어울려서 좋았음 카이막라떼는 생크림넣은거 같은 무거운 느낌의 라떼였음', 37, 1, 'GOOD', SYSTIMESTAMP);
