INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '카이막 올라가는 음료 마셔봤는데 괜찮아서 카이막도 추가로 구매했어요🥛 음료 위에 올라가는 카이막은 많이 묽고 밀크폼같은 느낌이었습니다. 따로 구매한 카이막은 담백하고 고소한 버터같았어요!', 45, 9, 'GOOD', SYSTIMESTAMP);
