INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '맛ㅇㅣㅆ어요 구웃! 미크플로 생기기전에 홍콩아이스크림(?) 이였던거 있을 적에도 왔었는데 금방 인테리어가 슉 바뀌었네요 ! 내부완전 깔꼼 귀염 st하고 ,,튀르키예사람은 아니라 찐 카이막 맛이 무엇인진 몰라도 빵과 카이막 꿀 조합이 정말 잘 어울려요. 직원분들도 친절하시고 내부가 일단 너무깔끔하고 아 왠지 카이막 팔것 같아. 하는 느낌의 공간 ㅋㅋ귀엽고 몽글몽글한 곳이에요. 화장실도 다깔끔~ 1층엔 바테이블의 의자가 있고,2층과 루프탑3층에 공간이 여유롭게 있었어요.  자주 갈 것 같아요 ! 짱마싯어', 262, 32, 'GOOD', SYSTIMESTAMP);
