INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '카이막 너무 좋아하는데 손에 꼽는 맛집이었습니다. 특히 카이막라떼 위에 크림 너무 취향저격이었어요..❤️❤️ 연남 갈때 또 재방문하겠습니다👍 카이막 입문하기 딱 좋은곳😎😎', 96, 25, 'GOOD', SYSTIMESTAMP);
