INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '인테리어 취향저격쩌러요ㅠㅠ 민트랑 옐로우라니 도랏다ㅜㅜㅜㅜ 카이막이 먼지 궁금해서 가봣어요! 대표 캐릭터 욀케기엽나여ㅠㅠ행복해지는 공간이었어욬ㅋㅋ 카이막은 크림우유치즈너낌!? 꿀이랑 같이 머그면 진짜 환상~ 카이막라떼는 생각보다 달고 꾸덕하네욬ㅋㅋㅋ 그냥 커피랑 먹어야 마싯을거같아요 카이막은!  여튼 너모 예쁜 인테리어에 특이한 카이막까지 져아여', 4, 0, 'GOOD', SYSTIMESTAMP);
