INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '한번도 먹어본적 없던 카이막 도전..!✨️ 연남동에 카이막 가게가 생겼다길래 달려가봤어요! 카이막세트에 빵은 바게트와 베이글 둘 중 선택할 수 있었는데 저는 바게트빵 선택했구요 꿀이랑 같이주는데 카이막크림에 꿀을 뿌려먹으면 달달~하고 안뿌려먹으면 밍밍하지만 고소한 우유맛이 나서 맛있었어요! 하지만 뿌려드세요 ㅎㅎ 다음에 또 가서 베이글도 함께 먹어보고 싶어요! 상큼한 레몬에이드와 같이 먹으니 조합도 좋았고 친구는 밀크티 마셨는데 밀크티가 되게 찐하다고 하더라구용 참고하세욥❗️', 35, 2, 'GOOD', SYSTIMESTAMP);
