INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '튀르키예에서 1일1카이막 해본 사람으로서... 당연히 맛은 똑같을 수가 없다고 생각했었지만 그래도 너무 다르네요ㅠㅠ 깊은 맛도 전혀 없고,, 꿀도 소나무꿀 맞나요..? 묽고.. 일반 밥숟가락만큼 한입 퍼먹지 않는 한 카이막 특유의 맛이 전혀 안 나요ㅎ.. 튀르키예에서 직접 공수했다고 해서 기대 좀 했었는데 실망만 가득 안고 가요ㅠ', 32, 7, 'BAD', SYSTIMESTAMP);
