INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '어머니랑 같이 왔습니다!! 하도 주변에서 카이막~ 노래를 불러대길래 왔는데... 제 단골 디저트집이 됐어용 ㅋㅋㅋㅋㅋ 진짜 짱 맛있어용!! 요거트 들어간 라떼는 다 맛있구 초코라떼도 맛있어용! 꾸덕하고 진합니다 ㅎㅎ 채광 잘 들 때 3층에서 인스타 갬성 사진 찍기 좋습니다 ㅎㅎ', 41, 8, 'GOOD', SYSTIMESTAMP);
