INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '다른곳이랑은 차원이다른 카이막에요! 풍미도 최고고 쫀득해서 더 맛있는거같아요 음료도 맛있어요! 카이막라떼나 카이막요거트는 시그니처 맞네요 ㅎ 재방문 무조건합니다!', 3, 1, 'GOOD', SYSTIMESTAMP);
