INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미크플로 연트럴파크점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '천상의 맛이라던 카이막 맛 봄~~ 크림치즈보다 부드럽고 아이스크림처럼 입에서 바로 녹아내려 맛을 느낄순 없음.. 그래선지 꿀과 조합을 이루는듯~ 좌우간 특별한 식감을 맛 봄', 14, 10, 'GOOD', SYSTIMESTAMP);
