INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더베이크 홍대피규어프레소FP점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '하이큐 콜라보 카페 열려서 왔어요! 음료도 생각보다 괜찮고 무엇보다 카페라 넓고 쾌적하네요. 기대 이상이어서 만족하고 갑니다!', 85, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더베이크 홍대피규어프레소FP점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '가성비 좋은 빵과 음료를 편안하게 즐길 수 있어서 좋아요. 특히 이쁘고 귀여운 피규어, 인형, 가챠, 쿠지를 함께 즐길 우 있어서 아주 좋아요', 46, 2, 'GOOD', SYSTIMESTAMP);
