INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더베이크 홍대피규어프레소FP점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '피규어 샵이랑 카페랑 재밌게 연결되어있어서 구경도 하기 좋은 곳입니다! 음료랑 여러 굿즈들이 많아서 좋은 곳이라 추천드립니다😃', 38, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더베이크 홍대피규어프레소FP점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '카페인데 굿즈들도 많아서 구경하기 너무 좋았고 굿즈 가격대도 다른데에 비해 괜찮은 가격대였습니다 다다다 굿즈 구하기 쉽지 않은데 캔뱃지랑 랜덤카드 등으로 여러가지 구입하고 커피 마시면서 가챠구경도 할수있어서 너무 좋았습니다❤️❤️❤️❤️❤️❤️❤️❤️❤️❤️❤️', 17, 5, 'GOOD', SYSTIMESTAMP);
