INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더베이크 홍대피규어프레소FP점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '오타쿠에게 천국입니다. 너무 친절하시고 매장 내에 볼 것도 많아요. 추천! 아래에 굿즈샵 있어서 애들은 구경하고 부모님은 쉬셔도 될 듯!', 2, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더베이크 홍대피규어프레소FP점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '더베이크 홍대피규어프레소점 처음 왔어요. 피규어들이 엄청 많아서 구경하기 좋아요. 별의별 캐릭터가 다 있던데 아이가 찾던 소닉은 안보이네요.', 26, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 이유'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '백현이 생카 방문했어요 💜 자리랑 공간이 꽤 널널해서 백현이 사진이 많아서 좋았어요 !! 250506 백현아 생일 축하해 🐶💞', 64, 16, NULL, SYSTIMESTAMP);
