INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 이유'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '성훈이 생일🥳겸 방문한 생카 카페 이유에용🫶 카페가 입구가 되게 예뻐서 입장할때부터 내부가 기대됐어용 ( σ̴̶̷̤ .̫ σ̴̶̷̤ )♡ 역시나.. 성훈이 사진들로 가득 찬 예쁜 액자들이 특히나 많더라구용! 벽에는 성훈이 사진들이 가득해서 활동별 스타일링이 다시금 생각나더라구요ㅋㅋ🤭🤭 추억회상하기 딱 조았어용 ₍ᐢɞ̴̶̷.̮ɞ̴̶̷ᐢ₎👍 또 사진들로 성훈이 이름 새겨주신 센스에 감탄.. 중간에 하트는 가을이인것도 넘 귀여워용ㅠ💓 특전은 디저트 특전으로 주문드렸구 마카롱 종류가 다양해서 좋았어용😽💕 럭드는 총 다섯번 했는데 제가 카페이유에 온 이유.. 4등 상품인 성훈이 아기 때 띠부씰이 넘넘 귀여워서에용🥹🥹 다행히도 4등이 나와줘서 득템했답니당👏👏 넘 만족스럽게 생카 잘 즐기다 왔어용💗', 23, 2, 'GOOD', SYSTIMESTAMP);
