INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 이유'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '이유카페 넘 예쁘네요! 💕 6월 해찬 생일 기념 이벤트가 있었는데, 우연히 들렀다가 저도 팬fan 될 것 같아요! 패키지 구성도 넘 좋네요! 자주 이런거 하는 것 같은데, 종종 들러봐야 겠어요 😊', 2, 8, NULL, SYSTIMESTAMP);
