INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 이유'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '생카…라는 곳을 처음 가봤는데 신기하네요 약간 위치는 조금 구석진 곳에 있는데 앉을 곳도 꽤 있고 괜찮아요! 뚱카롱도 있고 밀크티 맛있어보이는데 집에서 케이크랑 먹으려고 콜드브루 샀어요 ㅎㅎ 조금 연한 편이라 연한 커피 좋아하시는 분들 좋아할듯!', 83, 15, 'GOOD', SYSTIMESTAMP);
