INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 이유'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '몬스타엑스 민혁이의 생일이라길래 딸아이와 방문했습니다. 처음 가보는 생카였는데 그 유명한 그림이 있어서 사진과 그림을 한참 감상하고왔어요. 처음 경험해서 그런지 너무 멋지고 재미있었습니다♡♡', 46, 8, 'GOOD', SYSTIMESTAMP);
