INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 이유'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '솔직히 어이도 없네요 ㅋㅋㅋ 인스탁스 선착 준다길래 7시에 가서 11시까지 기다렸는데 누가 새치기해서 받지도 못했구요 알고보니까 인스틱스 카메라가 아니라 딸랑 사진한장이였네요 진짜 ㅋㅋㅋ 담에는 제대로 공지해주셧음좋겟네요 ㅋㅋ선착특전보시면 아시겠지만 인스탁스 미니폴라로이드를 누가 사진으로 알겠냐구요 ㅋㅋㅋ', 27, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 이유'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '창균이 생카하러 다녀왔습니다! 아메리카노 좋았고 마카롱도 맛있었습니다! 다양한 창균이 사진으로 구성되어있어서 좋았어요💜 창균이 생일 축하하고 생카열어주신 몬베베 선배님 감사합니다!!', 26, 7, 'GOOD', SYSTIMESTAMP);
