INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 이유'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '생카만 아니어도 안갔을 곳 왜 사람들이 없었는지 알겠네요 포카 성의도 없을 뿐더러 밀크티에 찻잎이 걸러지지도 않은 채로 팔다니.. ㅋㅋ 맛도 이상해서 한입먹고 바로 버렸어요 저처럼 멀리서 오신 분들은 헛걸음하지 마시길', 38, 9, 'BAD', SYSTIMESTAMP);
