INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '2~4층으로 이루어진 카페라 넓어서 좋아요. 카공하기에도, 잠깐 쉬기에도 좋습니다. 4층 같은 경우는 흡연 장소가 있어서 담배 냄새가 안으로 약간 흘러들어오더라고요, 이런거 싫으신 분들은 3층 이용하시는거 추천합니다', 21, 7, NULL, SYSTIMESTAMP);
