INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '염색하신 남자 알바생분 너무 불친절해서 기분 좋게 왔다가 기분이 안 좋아졌어요.. 따로 서비스 교육을 하시는게 좋을 것 같아요', 37, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '와! 캐모마일 이렇게 팔아서 남는 게 있어요?? 제가 가봤던 카페들의 거의 반값에 팔고 있네요! 와 진짜 이렇게 저렴한 캐모마일 처음 봤어요!', 49, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '저는 3/2일 남자 직원의 태도에 만족하지 않다. 그는 고객에게 회를 내고 친절하지 않은 태도를 보였다. 외국인인기때문에 한국어 들을때 천찬히 말해주셔야 더 잘 이해할수있다. 하지만 제가 다시 물어볼때 그는 제 얼굴에 대고 소리를 질렸다. 그는 “밝기” 또는 “화면” 같은 단어만 사용했고 문장을 완전히 말하지 않아서 그의 의도를 이해할수없다. 부드럽게 다시 질문했고 “최송합니다,잘 이해하지 못했습니다”라고 말했지만 그는 더욱 불친절한 태도를 보이며 고객을 무시했다. 단순히 작은 커피 한잔때문에 지금 이런 글을 쓰고있다는 사실만 봐도, 제가 그직원에게 얼마나 무시당하고 고객으로서 존중받지 못했는지 알수있다. 솔직히 그는 왜 이곳에서 일하고 있는지 이해할수없다.', 44, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '수박쥬스 먹는데 퀄리티가 어 뭐지 싶을정도로 다른매장에 비해 떨어집니다 . 수박 쥬스 시키자 마자 바로 나왔는데 미리 만들어 놓은거 같아요 .', 41, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '간단히 샌드위치에 음료를 하고 싶어서 오전 1시까지 한다는 카페를 찾아 들어왔는데 음식류(샌드위치, 베이글, 스프 등)는 전부 마감을 하셨는지 sold out으로 되어있고 매장 이용으로 선택했는데 어째서인지 일회용 컵에 나오고... 여러모로 기대했던 바는 아니라 좀... 별로였네요. +...1시까지라고 적혀있었는데 12시부터 마감송 반복해서 틀면서 나가기를 종용하네요.......', 55, 13, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '매장에서 먹는데도 종이컵에 주네요. 메가보다 커피가격대가 비싼 편이나 사람이 없고 조용해서 좋았어요. 매장이 되게 넓고, 층마다 계단 타기 귀찮지만 괜찮았어요.', 1, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '모든 층에서 하수구 냄새가 심하게 나요. 키오스크에는 매장 안에서 1회용/테이크아웃 잔 사용 금지라고 한글, 영어 등으로 적어놨는데 테이크아웃 잔으로 줌(?). 무엇보다 냄새가 진짜 너무 심함.', 62, 15, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '골든볼 용과 스무디 주문했는데 이미지와 좀 다르긴 하지만 나쁘지 않았어요. 층이 높고 자리도 넉넉해서 여유롭게 있다 가기 좋아요 : )', 89, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '딸기치즈케익할리치노(6,300원) 치즈케이크 스무디 맛인데, 스타벅스 딸기딜라이트 요거트 블렌디드보다 1000배는 더 맛있어용!', 31, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '평일 낮 12시쯤 갔는데 알바분 2명 불친절함.매장이 바쁘면 그러려니 하는데 텅텅 비었는데도 다 귀찮다는 식으로 대응하고 빨대가 안 보여 물어보니 뒤에 사이드 테이블 같은 곳에 있었는데 그런 당연한걸 왜 묻냐는 식으로 답 해서 황당했음. 그리고 매장에서 먹는건데 리뷰 보니 여기는 항상 다 일회용 종이컵에 주는듯. 이런 할리스 매장은 처음인데 굳이 2번 방문하진 않을듯', 1, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '매장에서 먹는건데 일회용품으로 나왔어요. 주말이라 바빠서 그런건지~ 창가석 바로앞은 홍대 공연하는 곳이 잘보여서 눈이 심심하지 않았어요.', 11, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '카페모카에 들어간 우유를 저지방 우유로 바꿨는데 커피 나오기전에 직원이 "아 저지방 우유 였어요"했는데 다른직원분이 "괜찮아 그냥 나가~~" 이러는 말을 들었는데 뭐지 했네요~~~~~~~~~ 픽업대 앞에 서있어서 정확히 들었네여~~~~ 똑바로 일하세요~~~~', 21, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '승환아 너에게 줄 편지를 쓴 곳이란다. 하루에 하나씩 읽어 보라던 그 편지는 잘 읽고 있니,, 애플 망고 치즈빙수가 개나 맛있어 너는 보리밥에 강된장 같은 빙수를 먹지만 그래도 홍대에서 나 프랜차이즈가 제일 조용한 거 같아서 왔더니 너무 쾌적하네. 다음에 또 보자', 35, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '키오스크가 1대뿐이라 주문 줄이 깁니다. 할리스앱에서 오더도 안되더라구요. (근처 다른 매장은 되는걸로 봐서는 어플문제는 아닌것 같아요) hot,ice 아메리카노에 조각케이크 주문했는데 매장에서 먹고가는건데 일회용종이컵에 주시고 심지어 아이스음료도 종이컵에 주셔서 좀 당황스러웠습니다. 음료주시면서 어떠한 사정 얘기도 없었고요. 얼음이 녹으면서 종이컵도 눅눅.. 커피는 신맛없이 고소했고 케이크도 맛있었습니다.', 75, 15, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '직원분 일하기 많이 싫으신듯 너무 귀찮아하고 말투도 너무 싸가지 없어요 하기싫으면 집에서 쉬시는게… 낫지않을까요? 기분좋게 카페왓다 망치고갑니다 계속 일하실거라면 서비스교육 받길바랍니다', 7, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '주말에 사람 개많아염.. 계단이 헬파티임 ˃̣̣̣̣̣̣︿˂̣̣̣̣̣̣ 화장실은 한칸 ˃̣̣̣̣̣̣︿˂̣̣̣̣̣̣ 지옥 ˃̣̣̣̣̣̣︿˂̣̣̣̣̣̣', 62, 16, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '매장도 넓고 늦게까지 영업해서 좋습니다~😁 외국인 손님분들도 많이 계셨어요😊 분위기도 너무너무 좋고요 확실히 동네 할리스하고 다른 것 같아요~ 직원분들도 너무 친절하셨는데 아쉬운 건 아이스초코 휘핑크림 맛있어보여서 키오스크로 주문했는데 픽업하러 가니 음료에 휘핑크림이 안올라가있어서 직원분께 문의드렸는데 오늘 소진되었다 하더라구요😌 이미 음료가 나온 상황이고 미리 말씀해주시면 좋았을텐데 응대 태도가 조금 아쉬웠습니다..‼️ 그래도 바쁜 와중에 맛있게 타주셔서 잘 먹었어요~☺️ 4층은 공부하시는 분도 많으시더라고요~😄', 118, 19, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), 'kt vvip쿠폰 이용 하러 갔는데 직원이 커피를 내릴수 없어 이용 할수 없다 하면서 쿠폰은 다운로드 해버려 이용못할 쿠폰을 이번달에 버리게 된 ㅠㅠ 난감했어요 늦은시간에 혼자 일하느라 바쁘고 힘들어 보여 더이상 말 못하고 다른 음료 시켜 테이크아웃하여 나왔어요 매장에서 인원충원을 더 해주셔야 매장이미지를 나쁘지 않게 유지 할 서 있을거 같아요 그리고 원래 쿠폰은 금액에 맞게 다른걸로 이용할 수 있다 알고 있는데 제휴할인이용법에 대해 더 인지하셔야 할 것 도 같습니다', 15, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '콜드브루할리치노가 항상 전 여기꺼가 젤 맛있드라구용 항상 여기오면 창가에앉아서 충전하면서 밖에 보면서 마시구 폰하면시간뚝딱가는데 누구 기다릴때 있기좋은것같고 시간보내기좋은 분위기카페입니당', 28, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '버스킹 거리 바로앞에 있어서 접근성이 아주 좋은 프랜차이즈 카페..그 이상 그 이하도 아닌.. 프랜차이즈니 맛은 뭐 평범하구요.. 대신 사람많아서 공부하고 작업하실분들에겐 비추인곳.. 고냥 앉아서 친구 기다리기 좋은느낌 아니면 목말라서 잠깐 친구랑 들어와서 수다떨기 좋은..', 436, 37, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '저는 감귤차 시켰는데 영수증을 안 뽑아서 친구 영수증으로 해요; 음료 너무 대충 주시는 것 같네요~ 알바 여자 세 명 이였는데 자기들끼리 씨끄럽게 떠들지 않나, 차를 마시는 건지~ 물을 마시는 건지~ 모를만큼 심각할 정도로 너무 맹맹하네요; 왠만하면 먹겠는데 이건 좀 아닌 것 같네요!! ㅎㅎ', 16, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '소프트잠봉뵈르 샌드위치... 제품설명에 나오는 트러플오일맛은 안느껴지고 양배추피클도 엄청 조금들어있어요. 마지막엔 커다란 버터만ㅠㅠ샌드위치 좀더 맛있음 좋겠어요', 8, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '불친절함 기프티콘 결제라 키오스크에서 못하고 계산대에서 기다리는데 바빠보이길래 바쁜거 끝나면 주문받아주겠지하고 한참 기다렸는데 일하시는분3분 중 아무도 응대를 안해주길래 저 기프티콘 결젠데 키오스크에서 가능한가요?라고 물어보니깐 그제서야 지금 주문도와준다고 계산대로옴 참고로 토요일 오후 3시 시간대였습니다', 62, 18, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '여자 직원 두분 계셨는데 주문 받으시는 분 표정도 귀찮ටㅏ 죽겠는 표정이고 옆에 분은 핸드폰만 보고 계시더라구요. 주문 잘못 받으시고 죄송하다는 말도 없이 추가 결제 하셔야돼요. 이러시고 그냥 주시더라고요. 그때부터 기분 상한 상태였는데 제 영수증 가져가시고 안 주셔서 화장실 비밀번호 찾으러 다시 내려갔다 왔네요. 기본적인 서비스 교육부터 받으셔야 할듯... 주문하기 미안할 정도로 귀찮아하시는거 티내지마시구요. 오늘 7월 18일 월요일 오후 2시쯤 계시던 여자 직원 두 분이요!', 15, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '알바생 서비스 최악이요^^ 금요일 12시반쯤 갔는데 사람이 많거나 바쁘지도 않았어요. 상냥한건 바라지도 않아요 적어도 주문받고 결제할때 손님을 응대할때 꼭 필요한 과정이 있지 않나요? 카페 알바해보신 분들이라면 아실거에요. 기계처럼이라도 해야되는 말들이 있는걸. 레드 멤버십이라 커피 사이즈 업그레이드 가능한데 적립이나 멤버십 물어보지도 않고 결제하더니 말도없이 그냥 음료 만들러 가길래 제가 얘기하니까 그제서야 번호 눌러달라하네요^^ 메뉴 한개 시킨것도 아닌데 크라운 적립 제대로 되긴했는지도 모르겠어요. 커피 사이즈 업그레이드는 당연히 못 받았구요. 평소에 할리스 좋아해서 자주가는데 모든 카페 통틀어서 여기만큼 손님응대 대충하는 곳은 처음 봤어요.', 69, 11, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '갈때마다 느끼는데 진짜 왜이렇게 불친절한건지 서비스태도가 아주 0점임... 할리스커피맛을 좋아해서 가는거였지만 그런거 아닌 분들은 굳이 여기가지말고 근처에 다른커피점 가는걸 추천', 44, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '센트플로우 커피 로스터리'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '커피 맛을 결정하는 데는 여러가지가 있겠지만 크게 신경을 쓰지 않았던 것 중 하나가 카페의 분위기였다. 하지만 센트플로우 커피 로스터리는 분위기 까지도 정말 향긋(?) 했다 약간 어두운 실내 그리고 짙은 우드색으로 세련미를 더한 카페 내부 공간은 앉아 있는 것 만으로도 아늑함을 느끼기 충분하다. 그리고 창 밖으로 들어오는 햇살과 조용한 골목의 풍경들.... 센트플로우 커피는 에스프레소류와 필터커피류가 있다 필터 커피 라인업이 상당히 다양하며 특히 컵노트가 정말 자세히 적혀 있다 나는 로스팅 전 원두의 맛 까지 적혀 있는 컵노트는 처음 본 것 같다 ^^ 그리고 커피를 가져다 주며 맛에 대해 자세히 설명 해주시는 사장님의 친절함~! 홍대 근처에서 필터커피를 좋아 한다면 필수 방문 카페가 아닐까 싶다~', 39, 10, 'GOOD', SYSTIMESTAMP);
