INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '센트플로우 커피 로스터리'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '마포 동네 카페 탐방기-내돈내먹 8월 20일에 홍대입구쪽에 오픈한 신상카페. 2주밖에 지나지 않았지만 벌써 손님들이 많네요. 하리오드리퍼, 호시자키제빙기부터 직접 로스팅하는 머신까지 커피 전문점이라면 갖출 기계들이 즐비하고 멋스러운 인테리어는 금요일밤 무드와 가장 잘 어울리는 분위기입니다. 싱글오리진 라인업도 7가지, 에스프레소는 더블까지 준비되어 있고, 필살기라고 볼 수 있는 티라미슈는 정성 가득+적절한 맛으로 소문나기 좋은 메뉴네요.', 62, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '센트플로우 커피 로스터리'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '에스프레소만 메뉴에 있어도 감사한데 싱글(3천 원)/더블(3500 원)이 둘 다 있다니 3종의 블렌드 중 산미있는 것은 에티오피아 워시드(아르베고나+게뎁)2종을 섞었다 스팀LP머신+로버s+코니s그라인더 조합도 감동인데 무려 zm그라인더로 분쇄 앉자마자 인포카드와 냉수 한 잔의 서비스 이태리의 클럽하우스 데미따세는 소서까지 나온다 설탕을 넣기 전부터 본연의 단맛에 꽃과 과일 향이 아찔하다 프랑스 라빠르쉐 유기농 설탕이 들어 가니 브라질산이 아닌 캘리포니아 오렌지 주스 같다 로보비 저울에 푸쉬탬퍼와 오토콤브로 이븐하고 균일한 추출 과정이 빛을 발한다 명품 호시자키 제빙기며 알파 드리퍼로 추출하는 게이샤 브루잉커피까지 거를 타선이 없다 분쇄 시향도 가능하고 모든 의자는 허리까지 편안하다 세상 놀랄 커피맛집일세', 31, 7, 'GOOD', SYSTIMESTAMP);
