INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '센트플로우 커피 로스터리'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '분위기 좋은 로스터리 카페~ 이 주변에 차분한 분위기 카페가 별로없는데...생겨서 좋아요. 오늘은 드립으로 과테말라 비하 베라파스 리브레 셀렉션과 에티오피아 벤치마지 게샤로 드립으로 시켰는데 마실때 온도가 너~~무 적당해서 엄청 좋았습니다.^^ 또 들릴게요~사장님^^', 87, 17, 'GOOD', SYSTIMESTAMP);
