INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '센트플로우 커피 로스터리'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '리뷰잘 안쓰는데.. 우연히 들러 커피 마시고 놀랬어요 정말 맛있고 차별화된 깊은 맛이 나요 오픈한지 얼마되지 않아 깨끗하고 사장님이 하나하나 커피와 디저트에 대해 친절히 설명해 주세요 실력자인듯.. 레몬 솔베는 얼음과젤리로 어뜨케 장미를 만드는지 신기해요 디저트도 굿입니다 눈도 입도 즐거워요 드랍커피는 집으로 모셔왔어요 사장님 대박나세요!!', 24, 10, 'GOOD', SYSTIMESTAMP);
