INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '센트플로우 커피 로스터리'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '지인들과 함께 방문하여 여러가지 주문했습니다 커피가 맛있으며 음료도 다른곳에서는 맛보기 힘든 차별화된  맛입니다 특히 레몬소르베의 상큼한 맛에 모두 반했으며 바닐라라떼는 제가 먹어본것중에 최고였습니다 고급원두에 시럽을 좋은것을 쓰시는듯 합니다~^^ 넓은 테이블이 있어서 여러 사람이 편하게 앉을 수 있는점도 좋았습니다 사진이 잘 나오는 조명도 마음에 들었습니다 편안한 분위기로  사장님의 디테일한 감각이 느껴지는곳입니다', 17, 10, 'GOOD', SYSTIMESTAMP);
