INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '센트플로우 커피 로스터리'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '최근에 먹은 드립커피중에 제일 맛있었습니다 인테리어도 취향이고 티라미수도 너무 안달고 입에서 살살 녹아요,,, 사장님도 너무 친절해서 주변에 알리고싶어요 여자친구 워홀 합격해서 여권 제출한 날인데 마무리도 특별하게 된것같아서 기억에 남을것 같아요 😢', 41, 3, 'GOOD', SYSTIMESTAMP);
