INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '센트플로우 커피 로스터리'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '✨우연히 걷다 들어왔는데 분위기가 너무 좋아요!! 들어가자마자 커피에 진심인 분위기를 느낄 수 있었습니다 ㅋㅋㅋㅋㅋ 덕분에 천천히 오래 즐기다가 갑니다! 자주 오고 싶은데 가오픈기간이라 아쉬워요🥹🥹🥹', 66, 13, 'GOOD', SYSTIMESTAMP);
