INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '센트플로우 커피 로스터리'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '지나다니며 인테리어 공사 할때부터 지켜봤는데요, 내부가 너무 예뻐서 오픈 날까지 기다리다가 다녀왔습니다! 재택근무 했는데 카페 분위기도 너무 좋고 노래 선곡도 완벽합니다..,집중하기에 정말 좋았어요. 커피도 맛있고 조용해서 대화 나누기도 좋았습니다. 꼭꼭 와보세요 홍대에 레전드 카페가 생겨버림..,🌟', 0, 8, 'GOOD', SYSTIMESTAMP);
