INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '센트플로우 커피 로스터리'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '필터커피를 주문했는데 대표님께서 원두별 특징을 하나하나 설명해주셔서 제 취향에 맞는 커피를 고를 수 있었습니다. 덕분에 선택하는 과정 자체가 즐겁고, 실제로 마셨을 때 설명해주신 맛의 차이가 느껴져서 더 특별하게 다가왔습니다. 공간도 차분하고 아늑해서 커피에 집중하기 좋았고, 세심한 서비스 덕분에 만족스러운 시간을 보낼 수 있었습니다. 커피에 진심이 느껴지는 곳이라 홍대 올 때 마다 방문하고 싶네요!', 6, 7, 'GOOD', SYSTIMESTAMP);
