INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '센트플로우 커피 로스터리'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '새로 생긴 곳 같아서 들어와봤어요! 공간이 너무 좋고 잔잔한 음악이 나와서 집중하면서 작업하기도 좋고 대화하기도 좋아요! 커피도 원두 종류별로 고를 수 있고 음료 맛도 좋아요, 다음에 또 올게요😌', 60, 18, 'GOOD', SYSTIMESTAMP);
