INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '센트플로우 커피 로스터리'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '커피를 직접 볶으시는데 커피는 물론이고 논커피도 다 너무 맛있어요 좌석도 편하고 친절하셔서 너무 좋았습니다 또 방문 하고 싶어요', 2, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '센트플로우 커피 로스터리'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '오랜만에 보물같은 카페를 찾은 것 같아요. 차분하고 운치있는 골목 속 멋진 외관과 인테리어부터 마음에 들었는데, 메뉴 구성과 옵션이 굉장히 전문적이고 세분화되어있어 커피 정말 좋아하시는 분들 꼭 한 번 방문하시라고 추천해드리고 싶어요✨ 에스프레소부터 필터 커피, 논커피 메뉴까지 알차게 구성되어있고 디저트 종류도 구비되어 있어 많은 분들이 만족하실 것 같아요. 커피 맛은 더할 나위 없이 훌륭했고요! 무엇보다 정말정말 친절하십니다🌝 메뉴 하나하나 다 도장깨기 하고 싶어요! 앞으로도 자주 찾게 될 것 같은 공간입니다🕊️', 65, 15, 'GOOD', SYSTIMESTAMP);
