INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '센트플로우 커피 로스터리'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '보리크림라떼 맛있네요. 일단 라떼에 우유얼음 넣어주시는 것부터 감동이고 고소한 보리맛과 향도 좋습니다. 홍대쪽에 생각보다 찐커피맛집 많이 없는데 하나 찾고 갑니다 :)', 17, 0, 'GOOD', SYSTIMESTAMP);
