INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '센트플로우 커피 로스터리'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '새로 생겨서 와봤는데 커피도 맛있고 분위기랑 인테리어 모두 다 너무 좋네요. 사장님도 친절하세요. 데이트 하기 좋을 것 같네요!', 34, 5, 'GOOD', SYSTIMESTAMP);
