INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '센트플로우 커피 로스터리'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '친구들과 우연히 발견한 로스터리 카페🪴 다양한 원두와 깔끔한 추출로 다양한 맛을 즐길 수 있는 카페였습니다!! 친구들과 맛있는 커피 마시고 고즈넉한 분위기에 취하다 돌아갑니다🙇‍♂️', 15, 9, 'GOOD', SYSTIMESTAMP);
