INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '센트플로우 커피 로스터리'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '인테리어가 깔끔하고 좌석 간격이 넓어서 편하게 이야기하기 좋았어요. 커피는 산미가 부드럽고 디저트도 직접 만드신 것 같아 퀄리티가 높았습니다.', 122, 24, 'GOOD', SYSTIMESTAMP);
