INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '센트플로우 커피 로스터리'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '집앞에 새로 생긴 센트플로우~ 산미있는 아메리카노도 맛있고 처음 먹어보는 페이보리 라떼도 너무 맛있어요!! 편하게 커피 마실수 있는 분위기도 너무 좋아요! 자주 이용하겠습니다👍', 5, 5, 'GOOD', SYSTIMESTAMP);
