INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어피스오브'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '북카페인줄 알고 들어갔는데  환경을 생각하는 제로웨이스트 카페더라구요. 테이크아웃 하는 손님들이 많았고 커피맛있었어요. 직원분도 친절하시구요.', 10, 6, NULL, SYSTIMESTAMP);
