INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어피스오브'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '환경을 생각하는 카페에서 환경 독서모임을 해서 의미있었습니다! 특히 홍대에서 10명이상 20명 미만 공간 대여 찾으신다면 이만한 공간 없지 않을까해요. 도란도란 얘기하기 최적의 장소라고 생각합니다. 프로젝트 사용도 되고요! 또 텀블러 내면 커피 값이 천 원 할인이라 굉장히 파격적(?)이더라고요,', 6, 0, 'GOOD', SYSTIMESTAMP);
