INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어피스오브'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '음료 너무 시원하고 새콤해서 맛있어요!! 커피두 존맛이구!! 사장님 너무 친절하심 ㅠㅠ 한입마시구 바보같이 샤베트 녹이다가 음료를 엎었는데 감사하게두 한잔 슬쩍 더 만들어주시구 넘 감사했어요!!!!ㅠ💕💕', 52, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어피스오브'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '어피스오브는 단순히 맛있는 음료를 넘어서 지구와 건강을 위한 작은 실천을 경험할 수 있는 공간입니다. 귀리 우유로 만든 음료의 특별한 맛을 즐기며, 환경에 긍정적인 영향을 미치고 싶다면 꼭 한 번 방문해보세요.', 64, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어피스오브'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '카페라떼가 별표길래 먹었는데,꼬쑵 살짝 묵직느낌! 오트밀을쓰시나봐요~ 분위기를 보니 제로웨스트 환경보호를 보여주는 카페였어요👍🏻', 28, 3, NULL, SYSTIMESTAMP);
