INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어피스오브'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '지나가다 우연히 들렀는데 폐자재 활용한 인테리어가 인상적이었어요~! 노트북 작업하기도 좋고 책 읽기도 좋아요~! 커피도 맛있고 유리빨대에 텀블러 할인은 1000원! 자주 올 것 같네요😁😃', 111, 22, 'GOOD', SYSTIMESTAMP);
