INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어피스오브'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '비건 메뉴에 재생지로 만든 굿즈를 전시 및 판매하는 곳. 커피가 맛있고 모든 라떼는 우유 대신 오트밀크로 제조돼서 라떼파에겐 반가운 카페예요. 식물이 많고 조용해서 집중 잘 되는데 화장실이 깨끗하기까지, 추천합니다.', 2, 4, 'GOOD', SYSTIMESTAMP);
