INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어피스오브'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '비가 오는 날 우연히 들린 카페인데, 실내 장식이 예뻐요! 업사이클링, 친환경 제품도 많고 커피는 오트밀우유로 주는데 맛있어요!-! 조용히 일하거나 책 읽기도 좋은 것 같으니 홍대에 오면 한 번씩 들러보시면 좋을 것 같아요~', 49, 10, 'GOOD', SYSTIMESTAMP);
