INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어피스오브'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '커피도 맛있고 카페만의 아이덴티티와 추구하는 가치가 보이는것 같아서 더 좋았습니다! 라떼는 오트밀크 쓰시는것 같은데 더 맛있었어요 🙌', 16, 5, 'GOOD', SYSTIMESTAMP);
