INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어피스오브'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '따뜻한 분위기의 업사이클링 제품들로 이루어진 카페. 음료 가격이 분위기에 비해 합리적이에요. 다만 양도 적어요 ..^^ 차분한 분위기로 조용히 이용하기 좋아요.', 78, 14, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어피스오브'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '안경쓴 남자분이 커피에 진심인게 느껴졌습니다. 그리고 화장실에 있는 휴지가 우유팩으로 만든 휴지였고, 행주나 테이블 등 가구 및 소품도 재활용을 한 것들이 많았습니다. 환경을 생각하지 않고 마구 뜯어쓴 휴지들에게 미안해지고 일회용품 사용을 줄여야겠다는 다짐을 하게 되는 카페였습니다. 또 갈게요!', 52, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어피스오브'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '딸이 커피 맛집이라고 해서 같이 왔는데 비건메뉴들과 재활용관련 제품과 제로웨이스트 제품들이 많은것 같아 착한소비를 하는 곳이네요 커피도 맛있고 기분도 좋아지는 곳^^', 76, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어피스오브'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '그레이프랩의 오프라인 매장이자 어피스오브 카페. 지속가능한 삶을 위한 노력들이 곳곳에 보여지는 곳에서 가치로운 시간을 보내다 갑니다~ 특색있는 공간에서 특별한 시간과 생각을 담아가세요 ^^', 9, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어피스오브'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '지속가능성을 우선시하면서도 맛과 디자인 모든 요소에서 너무 만족스러웠습니다🥹❤️ 공간도 층고 높고 넓어서 오래있기 좋습니다! 직원분도 친절하세요👍', 45, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어피스오브'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '지나가다 들어가 본 카페인데 재활용품을 사용한 다양한 물품이 있어서 카페말고도 이것저것 구경할 수 있는 곳이라 눈도 즐거웠어요. 특히 북스탠드를 무료로 사용해볼 수 있어서 좋았어요!', 35, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어피스오브'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '제가 가본 카페 중에서 분위기도 커피맛도 최고예요 리사이클링 굿즈들이 많은데 북스탠드도 써볼 수 있어요! 태블릿 올려놨는데 흔들리지도 않고 튼튼해서 정말 뽐뿌오는...', 98, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어피스오브'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '우연히 방문했는데 카페 전체가 업사이클링으로 인테리어 되어 있고 제작하신 업사이클링 제품도 판매하고 있었어요☺️ 평소 환경문제에 관심이 많고 관련 업계에 종사하고 있는만큼 멋진 장소를 발견해 기쁩니다 특히 대여해 주시는 종이 스탠드가 편리하고 디자인적으로도 훌륭해 구매까지 고려하게 됐습니다 덕분에 업무도 잘마쳤어요! 다음에도 꼭 방문하겠습니다💚💚', 39, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어피스오브'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '작업할일 있을때 자주자주 들려요. 공간이 쾌적하고 홍대 중심부 상권과 거리가 있어서 조용히 집중하기 좋습니다. 친환경 디자인브랜드의 쇼룸이기도 한데, 그래서인지 가게의 인테리어가 진짜 예뻐용. 여기에 6.7번은 넘게 들렸는데 그때마다 직원분들이 언제나 친절하셨습니다.', 45, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어피스오브'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '공간이 특유의 부드러움과 따뜻함을 갖고 있네요. 혼자 들린 것이 아까울 정도입니다. 특별한 책 스탠드도 샀어요! 발달장애를 가진 아티스트 분들이 참여하여 만든 작품인데요, 잘 써보겠습니다 😍☺️ 또 오고 싶은 곳이예요 💗🌱', 16, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어피스오브'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '친환경 카페라 음료 주문 시 빨대를 주지 않는데 취지가 너무 좋았어요. 플랜테리어도 마음에 들고 조용히 작업할 수 있는 공간도 있어서 복잡한 홍대 근처에서 오래 머무르기 좋을 것 같아요! 물론 편하게 대화해도 됩니다. 일하시는 분도 엄청 상냥하고 친절하게 맞아주셔서 즐겁게 머물다 갑니다 :)', 29, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어피스오브'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '이 동네에 살기 잘했다 싶은 마음이 드는 큰 이유들 가운데 하나인, 정말정말 좋아하는 공간입니다. 항상 일부러 혼자 힐링하러 조용히 찾아옵니다. 소리에 민감하고 공간의 분위기에 민감한 제게 이 곳만의 리듬을 제공해 주는 안정적인 공간!!! 완전추천이용 감사합니다', 27, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어피스오브'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '학교 근처에 이런 카페가 있는 줄 몰랐네요. 업사이클링 제품을 판매하는 쇼룸이 있어 커피 주문 후 기다리는 동안 구경하는 재미도 있었습니다. 층고가 높아 시원시원하고 많은 가구가 재활용 나무 자재로 되어 있어 독특하면서 아늑해 좋았습니다. 혼자 와서 차분히 생각 정리하기 좋아요!', 4, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'INDUSTRIAL');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어피스오브'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '비건 디저트 맛있어요! 너무 단거보다 조금 달달한게 좋은데 코코넛버터스콘이 딱!! 좋은 단맛과 겉 바삭 속은 포슬포슬슬한 식감이었어요 ㅎㅎ 홍대에서 조금 걸어야 있는 카페이데 이렇게 멋진 인테리어와 조용한 곳이라니~ 다음에 다른 디저트 먹으러 또 오고 싶어요 :)', 19, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어피스오브'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '이동네에서 보기 드문 조용하고 따뜻한 분위기의 카페에요 ☕️🤎 콘센트도 넉넉하고 잔잔한 음악이 나와 책읽거나 작업하기 딱 좋아요 ㅎㅎ 그레이프랩 제품들(북스탠드, 업사이클 다이어리 등) 이 진열되어있고 2층은 사무실 공간으로 사용되고 있습니다 커피리브레 원두를 사용하는 곳이라 커피맛도 좋은데 머신이 잠시 수리중이라 티를 주문하였어요 비건 디저트도 있고 텀블러 할인도 되더라구요 :)', 45, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PLUG');
