INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어피스오브'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '공간이 너무 예뻐요! 통창도 좋고 안에 업사이클링 제품들 구경하는 것도 재밌어요💕 특히 뒤에 카공하기 너무 좋을 것 같은 곳이 있어서 나중에 노트북 갖고 재방문하고 싶어요~', 7, 8, 'GOOD', SYSTIMESTAMP);
