INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어피스오브'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '주변에 쓰는 분이 계셔서 뽐뿌오다기 직접 보고 구매하고 싶어서 방문했어요. 공간도 방문해서 보니 만든 의미도 함께 볼 수 있어서 좋았습니다. 물론 커피도 맛있었어요. 텀블러 사용하면 천원 할인도 되니 꼭 텀블러 지참하시면 좋을 것 같습니다😊', 48, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'INDUSTRIAL');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어피스오브'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '분위기가 좋아요~! 디자인 스튜디오도 운영하시면서 카페도 함께 있는것 같네요. 구경할 거리도 많습니다! 좋은 의미의 제품들도 많아서 제품 레퍼런스 공부하는데 도움도 되네요! 물론 커피도 너무 맛있어요! 자주 방문하게 될것 같습니다! 🥰', 39, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'INDUSTRIAL');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어피스오브'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '업사이클링과 중고를 발굴한 제품들로 구성된 카페로 인테리어가 너무 멋집니다. 비건애프터눈티 행사가 있어 처음 와봤는데 너무 예쁘고 맛있었어요', 80, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어피스오브'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '카페 분위기가 너무 좋아요 ㅎㅎ식물이랑 목재 느낌 테이블이라서 마음이 안정되는 느낌이고 인테리어도 좋아요! 통창이라 햇빛도 잘 들고 앉아서 과제하기도 좋고~', 1, 8, 'GOOD', SYSTIMESTAMP);
