INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도트블랭킷 연남점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '오늘 저녁으로 정말 신선한 재료로 만든 맛있는 파스타와 샐러드를 먹었어요!  매콤한 맛 덕분에 느끼함 없이 계속 먹게 되더라구요.  음식 맛만큼이나 인테리어도 너무 예뻐서  사진 찍는 재미도 있었어요. 예쁜 곳에서 맛있는 음식 먹으니 기분 전환 제대로 됐어요!  다음에 또 방문해서 다른 메뉴도 먹어보고 싶어요.', 46, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도트블랭킷 연남점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '삼청점 브런치 유명한데 연남점에도 오픈했네요 플레이팅이 예쁘게 나와요 ㅎㅎ 다만 음식 양은 살짝 적은 편입니다 경의선숲길 공원뷰 보면서 먹을 수 있어 좋아요~', 33, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'TERRACE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도트블랭킷 연남점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '뷰맛집에 브런치도 훌륭하네요! 편안한 분위기 속에 귀여움이 느껴졌어요! 브런치 메뉴도 맛은 물론 양많고 푸짐하네요! 연트럴파크 브런치카페로 추천해요!', 111, 26, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도트블랭킷 연남점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '안국부터 자주 가던 식당이었는데 연남점에 새로 생긴 것 같아사 와봤어요! 인테리어가 안국점이랑 다르게 너무 예쁘고 뷰도 푸릇푸릇해서 너무 맘에 들었어요 !! 여기서는 신메뉴로 먹어봤는데 징짜 완전 제 스타일,,, 와인 안주로도 어울리고 에이드랑 같이 먹어도 너무 맛있더라구요 연남점도 자주 와야겠어요ㅎㅎㅎ', 8, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도트블랭킷 연남점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '푸릇푸릇 예쁜 뷰에 브런치는 산뜻하게 하루를 시작하기 제격이에요 .ᐟ ꒰۪  ɞ̴̶̷ ·̫ ɞ̴̶̷⋆꒱ 음식도 너무 맛있어요 추천합니다👍🏻💗', 9, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도트블랭킷 연남점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '도트블랭킷이 연남에? 자몽에이드 6. 애플티 에이드 6. 아보카도 파스타 샐러드 15.5 콰카몰리 쉬림프 블랭킷 14. 가격 착하고 친절하고 맛있음 초록 풍경 힐링이다', 95, 20, 'GOOD', SYSTIMESTAMP);
