INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도트블랭킷 연남점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '너무 맛있어서 주말에 먹고 또 왔어요 신선한 재료랑 매콤한 새우가 넘 잘어울려요 샐러드 파스타 좋아해서 종종 먹는데 여기는 진짜 최고네요! 분위기도 좋고 혼밥하기에도 편한곳이라서 파스타 땡길때 종종 올 것 같네요ㅎㅎ', 125, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도트블랭킷 연남점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '네이버 지도로 홍대입구역 근처 브런치 카페 검색하다가, 도트블랭킷 메뉴 구성 보고 방문했습니다. 워낙 아보카도를 좋아하는 본인과 크림 파스타를 좋아하는 남자친구라, 쏙 드는 메뉴 구성이었습니다만! 남자친구가 먹는 내내 이렇게 맛있는 버섯크림파스타 처음 먹는다고 극찬했습니다🥹 버섯을 별로 안 좋아하는 편인데도 이건 역대급이라며(ㅋㅋ) 다음에 정식 오픈하게 되면 또 방문할 것 같습니다🫶 +) 사이드 메뉴에 치아바타 2조각 메뉴가 있으면 더 좋을 것 같아요! 치아바타 말고 바게트도 좋고! 양념 안 된 담백한 빵이면 뭐든요! (크림과 토핑 양이 너무 알차더라구요!)', 13, 1, 'GOOD', SYSTIMESTAMP);
