INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도트블랭킷 연남점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '연남동 걷다가 귀여워 보이는 카페가 있어서 들어왔는데 가오픈한 카페더라구요 ><🫧 카페에 귀여운 굿즈 상품들도 많고 커피와 음료 넘 넘 맛있어요 🤍 창가석에서 앉아 멍때리고 있으면 넘 힐링될 것 같아요 🤍', 22, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도트블랭킷 연남점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '밥먹고 커피 한잔 하려구 왔는데 맛있는 메뉴가 많은 브런치 집이었어요!!! 친구 말로는 음식 다 맛있다구 하는데 다음에는 브런치 먹으러 오구싶어요🥹 커피도 너무 맛이었구(디카페인돼요) 창문도 많고 다 열려있는데도 매장이 시원해서 조앗어요!!! 재방문 의사완전잇어요💕💕💕', 21, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도트블랭킷 연남점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '안국동에 가본적 있는 매장이 홍대에도 있길래 신기해서 들어가봤어요 새로 오픈한 곳이라 그런지 깔끔하고 안국에 있는 매장이랑은 분위기가 달라서 새로웠어요✨ 일부러 안국점에 없는 새로운 메뉴들만 시켰는데 다 완전 만족이었습니다😊2층이어도 창문이 커서 그런지 큰 조명없이 자연광으로도 충분히 밝고 분위기 있더라구요 연남점은 저녁 늦게까지 한다고 해서 다음에는 저녁에 와볼려구요🤔😊', 86, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도트블랭킷 연남점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '서울 오자마자 방문했어요!! 블랭킷 처음 먹어봤는데 너무 맛있게 먹었고, 파스타가 진짜 맛있습니다. 다음에도 홍대 방문하면 재방문할거에요 🙂 홍대 근처 브런치 맛집 찾으신다면 방문해보세요!!', 0, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도트블랭킷 연남점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '파스타랑 알배추 샐러드 다 맛있었어요 통창 뷰도 예뻐요~ 아직 생긴지 얼마 안돼서 그런지 접객이 좀 미흡한 점 빼곤 다 만족했습니다', 109, 20, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도트블랭킷 연남점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '도트블랭킷 워낙 좋아해서 안국점, 삼청점 즐겨 갔었고 집에서 더 가까운 연남에 생겼다길래 가봤습니다. 숲길 큰 길에 있어서 찾기 쉬웠고 뷰도 좋네요. 음식도 아는 맛이지만 맛있고요. 다만 브런치 메뉴에 사이드 감자튀김은 양 보고 굳이 시키지 말걸 후회했네요. 오픈하자마자 사람들이 몰려서 키친이 바빴던 건지 어떤지 모르겠지만 샐러드도 이전에 맛본 다른 지점보다 양이 적은 느낌이 있었습니다.', 92, 20, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도트블랭킷 연남점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '삼청동에 있는 곳도 가봤는데 맛있어서 연남점도 와봤어요😊 매장이 예쁘고 창가에 앉으니 뷰도 좋네요! 아보카도 샐러드 너무 맛있어요~~', 41, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도트블랭킷 연남점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '존맛… 창가 뷰가 진짜 예뻐요 굿 ~~~ 오픈샌드위치도 아보카도 새우 토핑 듬뿍 올라가져있어요…. 브런치 맛 없고 비싸기만 할 때도 많은데 도트블랭킷 ㄹㅇ 맛있음', 1, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도트블랭킷 연남점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '저번에 한번 왔었는데 그땐 스파게티 먹구 이번엔 안먹고 티만 마셨는데요. 솔직한후기입니다.  뷰는 진짜 정말 좋아요👍 이것때문에 오고싶을정도로! 외국같아요. 근데 여름엔 너무더워서 죽을것같아서 갔었는데 다시나왔어요 ㅋㅋ이점 아셨으면 좋겠어요. 스파게티 음식은 제일맛있어보이는걸로 주문했는데 종류는 부족해보였고 가격은 많이 비쌌어요. 맛은 솔직히 제취향은아니었고..창가자리의 의자가 매우 빈약했어요. 끌고가면 잘못하면 넘어질뻔할정도? 그외엔 좋았어요 직원분들도 친절하셨고 음악도 너무좋았어요💕', 20, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도트블랭킷 연남점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '재료도 신선하고 브런치 너무 맛있네용 가격도 너무 괜찮아요 에이드 두개 시켰는데 둘다 시원하고 맛있는데 자몽에이드가 진짜 너무너무너무 맛있움😋👍👍👍', 24, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도트블랭킷 연남점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '브런치카페를 와본 적이 처음인데 너무 맛있게 잘 만들어주시고 친절하게 대해주셔서 너무 좋았어요ㅠㅠ❤️❤️ 서비스도 감사합니다!! 다음에 또 올게요 신메뉴 알리오올리오파스타 너무 맛있고 새우가 진짜 탱글탱글하고 맛있습니다요…. 눈물나는 맛…..😭😭😭❤️💋', 66, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도트블랭킷 연남점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '이렇게 이쁘고 맛있는 브런치가게 본 적 있나요? 전 없어요ㅠ 샐러드 재료도 너무 신선하고 파스타도 관자 미쳐요ㅠ너무 맛있었어요💗다음에 또 올게요!☺️', 12, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도트블랭킷 연남점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '음식이 깔끔하고 신선하니 너무 맛있네요~ 지인이랑 차음 방문한 곳인데 앞으로도 자주 찾을 것 같아요! 연남동 놀러오신다면 강추합니다~~', 54, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도트블랭킷 연남점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '가려던 카페가 리뉴얼 중이라 앞에 있는 곳중에 아무대나 들어왔는데 카페 분위기 너무 좋아여🤍🤍 음료도 맛있고 인테리어도 맘에 들어요👍🏻', 115, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도트블랭킷 연남점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '예약시간보다 좀 일찍 갔는데 바로 준비되서 이용할 수 있었어요. 음식은 너무 맛있었는데 공간이 약간 울림이 있어서 시끄럽게 느껴지기는해요. 그래도 음식이 너무 맛있어서 또 방문하게될 듯 싶습니다', 26, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도트블랭킷 연남점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '파스타 빼고 새로운 메뉴들이 많았는데 다 독특하게 맛있었어요!! 어쩌다 들어온 곳인데 너무 만족하고 갑니다 ㅠㅠ 매장 내부도 깔끔하고 넓어서 데이트하기에도 친구들이랑 가기에도 좋아요 !!✨', 108, 25, 'GOOD', SYSTIMESTAMP);
