INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도트블랭킷 연남점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '이번에 오니 신메뉴가 생겼네요~ 관자 알리오올리오 파스타랑 레몬에이드 상큼하게 점심먹고 갑니다~ 분위기도 너무 귀엽고 음식도 맛있어요~!', 145, 68, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '도트블랭킷 연남점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '분위기 너무 좋고 뷰도 완전 힐링이에요🌿 브런치도 맛있고, 창밖 풍경 덕분에 시간 가는 줄 몰랐어요.사진도 예쁘게 잘 나와서 데이트나 친구랑 오기 딱이에요!다음에 또 오고 싶은 카페에요ㅠㅠ', 31, 2, 'GOOD', SYSTIMESTAMP);
