INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '수험생인데 집에서 공부하기 지겨워서 홍대로 마실 나온 김에 좋은 카페로 오고싶어서 찾아왔어요! 여기 분위기도 너무 좋고 책도 읽을 수 있어서 시험 끝나고도 오고 싶네요ㅠㅠ 좋은 분위기라 공무 집중도 잘돼서 시험보기 전에도 몇 번 더 올 것 같아요 피치보스티도 달달하니 맛있숩니다 ㅎㅎ', 13, 9, 'GOOD', SYSTIMESTAMP);
