INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '오랜만에 렉터스라운지! 쌉싸름한 다크초코인 ''당신의 평안'' 날이 선선하져서 뜨겁게 마시며 평안해졌어요! 건축관련된 책이 많아서 뒤적여보기도 했어요 ㅎㅎ 이런저런 책도 많아서 다음에는 책읽으러 올게요! 말차크림휘낭시에... 맛있다는... 담에 또 먹으러 올게오!', 19, 8, 'GOOD', SYSTIMESTAMP);
