INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '근처 사는데 이렇게 분위기 좋고 작업하기 좋은 카페가 있다는 걸 처음알았어요.. 음료(당신의 평안) 너무 맛있네요 자주올 것 같아요 엄청넓고 콘센트석도 많고 분위기가 최고에요 음악도 좋고 힐링됩니다.^^', 40, 10, 'GOOD', SYSTIMESTAMP);
