INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '동네에서 우연히 발견한 카페인데 분위기가 정말 좋아요. 조용한 음악 덕분에 집중하기 좋았고, 창가 자리에서 보는 햇살이 예술이었어요. 라떼는 고소하고 부드러워서 한 잔 더 마시고 싶을 정도! 주말에 책 읽으러 다시 오고 싶은 곳입니다. 📚✨ #서울북카페 #홍대카페 #커피맛집', 128, 21, 'GOOD', SYSTIMESTAMP);
