INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '노트북으로 작업하기에 완전 좋은 곳이에요. 작업하거나 그룹으로 프로젝트하는 것도 추천해요. 공간도 다양하고 의자도 편해서 오래 있어도 괜찮았고, 커피도 맛있어서 작업하러 가기 딱 좋아요. #서울북카페 #홍대카페 #작업하기좋은카페 #책읽기좋은카페 #커피맛집 #디저트맛집', 9, 8, 'GOOD', SYSTIMESTAMP);
