INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '조용하고 집중하기 좋은 분위기의 카페라 공부하기에 적합했습니다. 콘센트와 와이파이가 잘 갖춰져 있어 노트북 사용도 편리했고, 테이블 간 간격이 넓어 방해받지 않고 공부할 수 있었습니다. 음료도 깔끔하고 사장님도 친절해 장시간 머물며 공부하기에 만족스러웠습니다. #홍대카페 #서울북카페', 6, 8, 'GOOD', SYSTIMESTAMP);
