INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '홍대에서 여유롭게 책 읽기 너무 좋은 카페예요! 차분하고 음악까지 넘 좋아서 책 읽고 사유하기에 딱 좋아요. 공간도 조금씩 느낌이 달라서 그때그때 선택하는 재미가 있어요. 음료메뉴들도 넘 맛있어서 행복한 시간 보냈습니다~ #홍대카페#책읽기좋은카페#커피맛집', 24, 5, 'GOOD', SYSTIMESTAMP);
