INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '조용해서 작업하기 너무 즇구요 작은 테이블도 많아서 혼자 작업하고 싶을 때 부담없이 오기 좋아요!! 아마 더 번창하실 것 같아요 #서울북카페 #홍대카페 #작업하기좋은카페 #책읽기 좋은카페 #커피맛집 #디저트맛집', 48, 0, 'GOOD', SYSTIMESTAMP);
