INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '조용히 책 읽거나 작업하기에 분위기 완벽 ! 이미 책 좋아하는 사람들 사이에서는 유명한 곳인가봐요 커피도 맛있고 디저트도 다양해서 편하게 쉬다가 갈 수 있었어요 사장님도 친절하시고 분위기 너무 좋아요', 28, 1, 'GOOD', SYSTIMESTAMP);
