INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '서울북카페 찾다가 왔는데 홍대에 이렇게 카공하기 분위기 좋은 곳이 있는 줄 몰랐어요. 음악도 잔잔하고 좌석도 진짜 다양하고 많고 콘센트도 잘되어있고 에어콘도 시원하게 잘 틀어져있어서 맘 편히 할 일하고 갑니당. 진짜 집 근처에 이런 곳이 있었다면 넘나 좋았을 것 같아요 ㅠㅠ 다음에도 또 작업하러 올게요 ㅎ.ㅎ', 8, 7, 'GOOD', SYSTIMESTAMP);
