INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '홍대에서 혼자 작업하기 어려운 카페 찾기 어려웠는데 여기는 제격이예요! 조용하고 좌석마다 콘센트도있고 다들 집중하는 분위기에 좋았어요 커피도 맛있고 잠봉뵈르도 맛있고 책읽기 정말 좋았어요', 365, 67, 'GOOD', SYSTIMESTAMP);
