INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '#서울북카페 #작업하기좋은카페 작업하기 좋은 대형공간 찾고 있었는데 서울 한복판에 이런 공간이 있어서 너무 좋아욥! 아늑하고 편안한 분위기예요 직원분들도 다들 친절하십니다 다음에는 책들고 오려구요 추천합니다 ☺️💛', 18, 0, 'GOOD', SYSTIMESTAMP);
