INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '약속 시간까지 시간이 떠서 방문한 서울 북카페! 수많은 홍대 카페 중에 꼭 와보고싶었던 카페였는데 분위기 미쳤어요ㅠㅠ 작업하기에도 좋고 차분하게 책 읽기에도 너무 좋은 곳입니다! 다음에는 노트북 들고 방문해야겠어요~', 3, 5, 'GOOD', SYSTIMESTAMP);
