INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '간만에 쉬는 날 아침부터 비오고 꿀꿀해지려고 하는 날이었는데, 커피 마시고 책이나 읽자하구 북카페 검색하다가 우연히 근처 카페를 처음?! 와봤습니다. 왜 이런 좋은 곳이 코앞에 있는 줄 이제 알았을까요😵‍💫 진한 라떼와 책 한 잔에 마음이 잔잔해지고 일상의 행복을 다시 느낍니다🍀 인테리어/익스테리어 모두 너무 감각적이구 특히 비 오는 날 오면 좋을 것 같네요. 비치된 책들도 많아서 빈 손으로 오셔도 좋을 것 같습니당. 또 와야지. #책읽기좋은카페 #홍대북카페 #커피맛집', 82, 17, 'GOOD', SYSTIMESTAMP);
