INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '홍대카페 어디가지 하다가 렉터스라운지 홍대에 처음 와보았는데요!! 매장이 지하 1층서부터 2층까지 있고 매우 넓었습니다! 그리고 작업하기 좋은 카페로 노트북 작업 하는 분들이 대부분이었어요 ㅎㅎ 저도 노트북 작업하러 왔는데 편안하게 할 수 있었습니당', 14, 9, 'GOOD', SYSTIMESTAMP);
