INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '처음와봣는데 지금까지 머거봣던 잠봉뵈르 중에 최고로 맛잇어요ㅠ 겉바속촉 ... 그리구 비건 브라우니도 짱꾸덕하고 맛나요!! 분위기도 조용조용해서 책읽기두 좋고 대화나누기도 좋아요 ㅎㅎ #서울북카페 #홍대카페 #작업하기 좋은 카페 #책읽기 좋은 카페 #커피맛집 #디저트 맛집', 90, 11, 'GOOD', SYSTIMESTAMP);
