INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '조용히 책을 읽거나 생각을 정리하기에 딱 좋은 분위기의 카페입니다 벽면을 가득 채운 서가와 따뜻한 조명이 아늑함을 더해주고, 의자와 테이블 배치도 여유로워 오래 머물러도 편안했습니다 책을 읽으며 시간을 보내기에 최적의 공간이었고, 음료와 디저트 또한 특별합니다.', 35, 7, 'GOOD', SYSTIMESTAMP);
