INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '노트북으로 작업하기 좋은 차분한 분위기의 카페예요. 햇살 들어오는 자리에서 글도 쓰고 책도 읽기 딱 좋습니다. 음료와 디저트 모두 깔끔해서 오래 머물기 편했어요. #서울북카페 #홍대카페 #작업하기 좋은 카페 #책 읽기 좋은 카페 #커피맛집 #디저트 맛집', 38, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
