INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '늦게까지 하는 카페여서 찾아왔는데 지하1층, 1층, 2층 나눠져있고 매장이 넓어요 그리고 작업하거나 공부하기 좋게 1인 좌석이 많고 좌석별 콘센트가 있는 곳도 있네요 책장에 책들도 있어서 책을 읽어봐도 좋을거 같고 아예 책을 가져와서 잔잔한 노래랑 함께 읽어도 좋은거같아요 #홍대카페 #작업하기좋은카페 #책읽기좋은카페 #커피맛집 #디저트맛집', 103, 22, 'GOOD', SYSTIMESTAMP);
