INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '갑자기 미팅할자리가 필요해서 온건데 너무 괜찮아요 진짜 분위기도 분위기인데 미팅관련 이야기 할수있어서 너무 좋았던거같습니다 #작업하기 좋은 카페', 9, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'MEETING');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '분위기가 정말 대박이에요. 비 오는 날 카페 가는 걸 좋아해서 오픈런했는데, 다행히 사람도 많지 않아 좋은 자리에 앉을 수 있었어요. 덕분에 오붓하게 전체 인테리어를 구경하기 좋았답니다. 전시도 관람할 수 있고, 꽂혀 있는 책을 읽을 수도 있어서 정말 좋았어요. 노트북을 가져오시는 분들은 2층 자리를 추천드려요. 아주 조용하고 집중이 잘 되는 분위기예요 😌😌', 8, 10, 'GOOD', SYSTIMESTAMP);
