INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '지하 1층부터 2층까지… 작아 보였지만 알고 보니 대형 카페… 창가 자리 넘 좋죠! 다들 공부하시느라 엄청 조용해요.^^ 혼자와서 멍때리기도 넘 좋습니다.  ~~ 무엇보다도 음악이 최고입니다. ! 오늘도 힐링하고 갑니다. ^^ 감사합니다. #서울북카페 #홍대카페 #작업하기 좋은 카페 #책 읽기 좋은 카페 #노트북하기 좋은 카페#커피맛집 #디저트맛집', 50, 4, 'GOOD', SYSTIMESTAMP);
