INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '홍대에서 이만큼 작업하기 좋은 카페 찾기 어려운데 여기는 공간도 넓고 분위기도 좋아서 작업이 너무 잘됩니다. 작업뿐만 아니라 연인끼리 오셔도 데이트 코스로 너무 좋을 것 같네요. 매주 홍대카페는 여기로 오는데 커피도 맛있고 좋습니다.!', 47, 0, 'GOOD', SYSTIMESTAMP);
