INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '수업 중간에 시간이 떠서 들렀습니다! 공간도 넓고 쾌적하고, 혼자 작업하기 너무 좋아요 디자인과 학생으로서 너무 최적..🫰🏻💞케이크는 처음 시켜봤는데 생각보다 크기가 커서 놀랐답니다!! 다들 클래식 치즈 케이크 드셔보세요 ㅎㅎ 맛나네요. 다음에 또 시간 뜨면 방문하려구용 ㅎㅎ #서울북카페 #홍대카페', 116, 21, 'GOOD', SYSTIMESTAMP);
