INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '매주 주말 조카학원픽업 때문에 홍대에 오는데 오로지 나를위한 힐링시간👍👍👍👍 커피가 일단 고소하고 맛있고 책도 읽으면서 여유를 찾을수 있는 서울북카페 진짜 조용히 책읽기 좋은 카페. 힐링되는카페추천🙏🙏', 117, 24, 'GOOD', SYSTIMESTAMP);
