INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '독서모임하러 정말 자주 오는 카페! 오늘은 레몬블랙티 시켰는데 달달하니 맛있네요 ㅎㅎ 분위기가 좋아서 공부하거나 작업하러 오기 정말 좋은 카페인 것 같아요~~! 또 방문 하겠습니다 :)', 21, 4, 'GOOD', SYSTIMESTAMP);
