INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '홍대 특유의 번잡함에서 벗어나 조용히 집중하고 싶을 때 최적의 장소예요. 혼자 가도 부담 없고, 공부 모임이나 프리랜서 작업하기에도 딱 좋습니다.😍 #서울북카페 #홍대카페', 44, 9, 'GOOD', SYSTIMESTAMP);
