INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '분위기좋고 집중하면서 작업하기 좋아요😊 딴짓앙하고 열심히 할 일 했네요 ㅎㅎ 음료도 완전 맛있어요(히비스커스 아이스 추천) 다음에 또 올 것 같아요🥰 #작업하기좋은카페 #느좋카페 #노트북하기좋은카페', 39, 7, 'GOOD', SYSTIMESTAMP);
