INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '여자친구랑 데이트 하러 왔는데 정말 분위기가 좋아서 좋았습니다 그리고 맨위에는 모니터가 있어서 노트북 활용하기가 너무 좋아서 개인적으로도 방문 하고 싶습니다!! 렉터스  라운지 오세요!!', 90, 17, 'GOOD', SYSTIMESTAMP);
