INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '분위기 맛집🥰12시까지 매장이용가능해서 집중 필요할 때 자주와요~분위기도 좋고 선곡도 좋아서 엄청 집중 잘 되는 기분이에여~! 책 읽기도 좋고 작업하기도 좋아요~❤️자주 오는 카페에요👍', 1, 10, 'GOOD', SYSTIMESTAMP);
