INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '노트북 가지고 작업하거나 책 읽기에 너무 좋은 까페에요! 공간도 구획별로 분위기가 달라서 가볍게 작업할때랑 집중해서 작업할 때에 따라서 좌석을 고를 수 있는 점이 너무 좋아요😀😀 주문 공간이랑 좌석공간도 아예 분리돼 있어서 편하게 작업할 수 있고 콘센트도 좌석마다 다 배치돼있어요 요즘 오래 앉아있으면 눈치주는 까페가 많은데🥹 여기는 책도 비치되어 있고 오히려 오래 앉아 있는 분위기라 작업이 필요할 때 자주 방문하게 될 것 같아요!', 120, 21, 'GOOD', SYSTIMESTAMP);
