INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '찰스엔터님 유투브 보고 근처 볼일있다가 처음 와봤는데 조용하고 너무 좋아요! 제가 대학다닐때 있었으면 더 좋았을걸 ~~ 책 종류도 다양하고 집중할 수 있어서 혼자만의 시간 필요하신 분들 적극 추천입니다 ☺️', 62, 13, 'GOOD', SYSTIMESTAMP);
