INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '홍대카페 검색 중 작업하기 좋은 카페를 발견해서 당장 다녀 왔어요😀 디카페인도 있어서 넘 좋구 완전 커피맛집이예요 신선한게 느껴져요!😍', 25, 8, 'GOOD', SYSTIMESTAMP);
