INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '처음 방문해보는데 모던한 분위기가 너무 좋네요 다들 공부나 할 일 하러 오셔서 굉장히 조용하고 노래도 은은하게 깔리는 브금이라 오히려 집중이 잘 돼요 좌석도 편하고 2층에는 개인 좌석도 있어 혼자 오기에도 너무 좋을것 같습니다. #홍대카페 #홍대공부카페', 42, 0, 'GOOD', SYSTIMESTAMP);
