INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '홍대에서 조용히 작업하기 좋은 카페로 추천합니다! 집중이 잘 되서 벌써 N번째 방문하고 있어요. 디저트와 시그니처 음료인 당신의 평안도 꼭 먹어보세요:)', 37, 5, NULL, SYSTIMESTAMP);
