INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '친구와 함께 와도 좋고, 혼자도 넘좋은 장소입니다 ! 콘센트가 곳곳에 마련되어 있어 작업하기에도 편리하고, 평일에는 비교적 한산해 책 읽기에도 정말 좋아요 📚 잔잔한 분위기 덕분에 여유롭게 시간을 보낼 수 있어요 🍃 #서울북카페 #홍대카페 #작업하기좋은카페', 28, 10, 'GOOD', SYSTIMESTAMP);
