INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '홍대에서 조용하게 노트북하기 좋은 카페는 렉터스라운지가 최고인 것 같아요! 매장도 넓고 좌석도 많이 있고 분위기도 차분해서 집중하기 좋아요 #서울북카페 #홍대카페 #작업하기좋은카페 #책읽기좋은카페 #노트북하기좋은카페', 54, 16, 'GOOD', SYSTIMESTAMP);
