INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '음료랑 디저트가 맛있어요 특히 잠봉뵈르가 맛있습니다 또 작업하기에 분위기가 좋고 조용합니다 다양한 형태의 좌석이 있는것도 좋은것 같아요 인근에서 작업하기에늠 가장 좋은 곳인것 같아요', 19, 5, 'GOOD', SYSTIMESTAMP);
