INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '홍대에 이렇게 넓으면서 공부하기 좋은 카페가 있는 줄 몰랐어요 !! 책상도 커서 혼자서 태블릿이나 노트북 가지고 공부하기도 좋고 ! 시끄럽지 않고 잔잔한 노래가 나와서 공부 집중도 잘 됩니다 !! 그리도 잠봉뵈르가 진짜 맛있네요 ㅋㅋㅋ 🩵 점심 먹고 왔는데도 불구하고 맛있게 느꺼져요', 30, 0, 'GOOD', SYSTIMESTAMP);
