INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '가끔 홍대에 오면 무조건 들리는 카페에요! 스틱프레즐 진짜 맛있어요 🥹🥹 담백한 빵 좋아하는데 책 읽거나 작업하면서 먹기 딱! 포션 궁금해서 다 추가해서 시켜먹어봤는데 (종류당 1000원) ㅋㅋㅋ 저는 크림치즈가 찰떡 💕 친구들에게 서울북카페로 항상 추천하는 곳이에요! 또 올게요🫶🏻', 69, 13, 'GOOD', SYSTIMESTAMP);
