INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '집중하기 좋은 홍대 대형 카페 홍대 어디를 돌아다녀도 이만한 카페를 찾기 힘듬 개별 좌석이 많아서 카공 하기도 탁월함. #홍대카페 #커피맛집', 25, 5, 'GOOD', SYSTIMESTAMP);
