INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '홍대에 있는 카페인데도 조용하고 책 읽거나 작업하기가 너무 좋아요🩷 휘낭시에 디저트도 맛있어용🤤 공간도 넓어서 자리 잡기도 쉬웠어요! 음악도 가사가 없는 음악이 나와서 이어폰 계속 안 꽂고 있어도 되고 너무 편함니당..', 30, 3, 'GOOD', SYSTIMESTAMP);
