INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '조용하고 자리 많고 공간이 특이해서 모임, 작업 등 있을때마다 오면 좋을 것 같아요. 근처에서 일하는데 이런곳이 있는줄 몰랐네요... 굳굳.. 퇴근하고 잔업하고 싶을 때 여기 또 올려구요 #커피맛집 #작업하기좋은카페', 38, 10, 'GOOD', SYSTIMESTAMP);
