INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '혼자도 여럿도 좋은 룸도 많고 1인공간도 많아 작업히기 좋읔 카페네요. 1,2,3층 공간공간이 멋쪄요. 커피도 디저트도 맛있는 읽을책도 먾은 멋진 갤러리 북카페 좋아요.', 90, 13, 'GOOD', SYSTIMESTAMP);
