INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '예전에 방문했었는데 독특한 구조 덕분에 기억에 남았어요. 날이 좀 더 풀리면 테라스에서 먹어도 좋을 것 같아요! 커피 맛있고 메뉴도 다양합니다. 실내 공간 넓은데 사람들이 계셔서 많이 못찍었어요 🥹🥹', 30, 6, 'GOOD', SYSTIMESTAMP);
