INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '공간이 다양하게 구성되어 있어서 필요에 따라 이용하기 좋은 장소입니다. 집중해서 몰입하고 싶을 때, 중간중간 편안하게 휴식하고 싶을 때 한 장소에서 이 모두를 만족시키긴 어려운 법이지만 렉터스라운지는 그걸 해냅니다 ㅎㅎ 그리고 시그니쳐 영감 음료를 두 종류 시켜봤는데 둘다 맛있어요~:) #서울북카페 #홍대카페 #작업하기좋은카페 #책읽기좋은카페 #노트북하기좋은카페', 68, 16, 'GOOD', SYSTIMESTAMP);
