INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '우연히 들렀는데, 작업하기 참 좋은 공간이네요. 홍대 정문에서 그리 멀지 않은 곳에 위치하여 있어요. 커피맛도 좋고, 디저트 사진을 못찍었는데 쇼콜라 케이크 맛있어요 :)', 45, 0, 'GOOD', SYSTIMESTAMP);
