INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '조용하고 인테리어가 너무 좋아서 홍대 올때마다 들려요. 집중하기도 좋고 혼자오기에도 좋아서 가까웠으면 진짜 자주 왔을 것 같아요. 또 앞에 모니터랑 연결할 수 있는데 노트북 가져오면 진짜 좋을 것 같아요. 음료 가격도 적당한 것 같습니다!!', 8, 7, 'GOOD', SYSTIMESTAMP);
