INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '지난번에 공부하러 왔다가 너무 괜찮다 싶어서 오늘도 공부하러 왔는데 일단 카페 분위기가 차분해서 공부하기 정말 좋아요 또 좌석도 다양해서 고르는 맛도 있는 것 같고 점원 분들도 친절하세요! 앞으로도 종종 공부하러 오겠습니다 말차 휘낭시에 맛있어요..짱😋', 27, 0, 'GOOD', SYSTIMESTAMP);
