INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '커피가 진짜 맛있어요 분위기도 너무 좋아서 자주 오고싶어요. 책 읽으며 카공하기도 좋고 친구들이랑 이야기 하기도 딱 좋은 안성맞춤 카페입니다 !! 추천드려요', 65, 18, 'GOOD', SYSTIMESTAMP);
