INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '홍대에서 디저트 카페를 검색하니 늦게까지 영업한다길래 와 봤는데 좋은 가게를 찾은 것 같아요 작업이나 독서 하기에도 좋을 것 같아요', 348, 71, 'GOOD', SYSTIMESTAMP);
