INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '혼카공하기에 딱인 넓고 쾌적한 공간..😊 카공할 때는 항상 프랜차이즈 위주로 갔었는데 자주 올 카페가 생겨서 참 좋습니다.. 음악도 재즈풍 음악이 들리는데 여기 분위기와 너무 잘어울려욧!! ㅎㅎ 좌석도 참 다양하니 호불호없이 좋은 공간인듯 합니다추천드려요!! ❤️ 책읽기 좋은 카페고, 북카페로써 책도 많이 비치되어 있어서 혼자 놀기에 딱이예요 ㅎㅎ😍', 8, 3, 'GOOD', SYSTIMESTAMP);
