INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '홍대에 있는 정말 매력적인 카페에요. 혼자만의 시간이 조금 필요해서 노트랑 필기구를 들고 왔는데요. 일하시는 분들이 많아서 조용하고 차분한 분위기에요. 책 읽기 좋을 것 같아요. 저는 혼자 글쓰면서 시간을 보냈는데 두 시간이 훌쩍 지났네요. 곧 다시 방문할 것 같아요^^', 32, 1, 'GOOD', SYSTIMESTAMP);
