INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '매장이 3층까지 있고 자리도 많아용 24시간 하는 홍대 카페 근처에 잘 없는데 분위기도 좋고 가격도 합리적이에요 독서모임하시는 분들도 있네요! 책 읽기 좋은 서울북카페에요 추천ㅎㅎ', 11, 0, 'GOOD', SYSTIMESTAMP);
