INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '평일 오후 2시쯤 방문했고 자리 널널했어요. 혼자 조용히 와서 노트북 작업하기 좋아요! 콘센트 거의 자리마다 있어서 부담없이 쓰기 좋아요 :) 레몬블랙티 마셨는데 엄청 상큼해서 담백한 레몬에이드? 같은 느낌이에요! 자주 와서 작업할거같아요~!', 17, 10, 'GOOD', SYSTIMESTAMP);
