INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '혼자 작업을 해야해서 왔는데, 진짜 작업하기 좋은 카페입니다. 독서모임도 있고, 책들도 많아서 책읽으로 오셔도 좋을 것 같습니다.', 17, 1, 'GOOD', SYSTIMESTAMP);
