INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '홍대 카페중에 제일 작업하기 좋은 카페에요🫶🫶 조용하고 혼자 앉을 수 있는 자리도 많아서 매번 빡작업하다가 갑니다👍 인테리어 쵝오..', 1, 10, 'GOOD', SYSTIMESTAMP);
