INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '홍대에서 조용한 카페 찾기 쉽지 않은데 카페 분위기부터 음악, 향까지 너무 맘에 드는 카페를 찾아서 행복해요 ㅠㅠ시험기간에 공부하러, 책 보러 자주 올 것 같아요 🥰 #작업하기좋은카페 #서울북카페', 7, 8, 'GOOD', SYSTIMESTAMP);
