INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '공간 자체가 여름을 보여주는 것 같은 카페였습니다. 🍀 카페에서 작업하시는 분들도 많은 것 같고, 다양한 사람들이 함께하는 공간이었어요! ☺️ 곳곳에 숨은 자리들이 아늑하고 매력있는 카페였습니다. 💝💖💘 #서울북카페 #홍대카페 #작업하기좋은카페 #책읽기좋은카페 #노트북하기좋은카페', 35, 6, 'GOOD', SYSTIMESTAMP);
