INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '집중해서 공부나 작업하기 좋은 카페인거 같아요! 롱블랙이 유명한 것 같아 먹어봤는데 커피 맛도 너무 좋습니다😊 조용한 공간이 필요할 때, 집중이 필요할 때 또 오고 싶습니다!!', 42, 10, 'GOOD', SYSTIMESTAMP);
