INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '노트북 작업하기 진짜 좋은 곳이에요. 의자도 편하고 자리도 다양해서 오래 있어도 편하고요. 커피도 맛있어서 작업하러 가기 딱이에요.', 83, 13, 'GOOD', SYSTIMESTAMP);
