INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '홍대카페 중 제일 카공하기 좋은 거 같아요 자리마다 콘센트도 있는 센스 짱 ㅠㅠ 저는 카공을 목적으로 왔지만 편한 좌석들도 있어서 친구들과 수다떨러 와도 너무 좋을 거 같아요 커피도 너무 맛있고 완내스 카공 카페 찾은 거 같아서 기분이 넘 좋아요 ♡', 288, 29, 'GOOD', SYSTIMESTAMP);
