INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '친구 소개로 같이 홍대 카페 왔다가 분위기도 좋고 공부하기에도 너무 좋안 공간 같아요 자리도 많고 콘센트도 많이 있어 작업하기에도 책읽기에도 좋은 카페인 것 같아 자주 방문 할 것 같습니다.', 49, 7, 'GOOD', SYSTIMESTAMP);
