INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '책 읽기 좋은 카페 찾으면서 홍대 주변 돌아다니다가 들어왔습니다. 내부에 공간도 여기저기 많아서 골라앉는 재미가 있어요. 혼자와서 작업하기 좋은 카페예요!', 26, 6, 'GOOD', SYSTIMESTAMP);
