INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '홍대에 이런 공간이 생기다닛!!!❤️ 분위기 너무 좋고 책도 있고 혼자만의 시간 즐기기에도 딱이겠어요👍 집은 일산이라 멤버쉽은 못하지만 홍대 나올때 시간 뜨면 또 와야겠러요 굳 #서울북카페 #홍대카페 #작업하기좋은카페 #책읽기좋은카페 #노트북하기좋은카페', 25, 0, 'GOOD', SYSTIMESTAMP);
