INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '홍대입구에 이렇게 조용하고 집중하기 좋은 카페가 있다니 넘 좋아요👍 공간도 넓고 앞쪽에는 푸룻푸룻한 뷰를 보면서 편하게 작업할 수 있어서 좋았어요!! 고급스러운 초코 좋아하신다면 일상의 평안 음료 추천드립니다', 60, 13, 'GOOD', SYSTIMESTAMP);
