INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '창작자를 위해주시는 마음이 진실로 느껴지는 카페예요 작업하기도 정말 좋구요 이런 카페를 만난 건 행운이에요.. 음료도 흔한 양산형(?) 카페 음료가 아닌 고안하고 고심하여 정성껏 만들어주신 느낌이 듭니다 운영해주셔서 감사합니다 사장님 가시는 길 모든 길에 행운 가득하세요 🍀', 26, 7, 'GOOD', SYSTIMESTAMP);
