INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '홍대에서 카공하기 좋은 카페를 검색해서 오게 되었어요. 매장도 깔끔하고 분위기도 좋고 무엇보다 직원분들 친절하시고 매장에 잔잔히 흐르는 음악이 작업도 대화도 공부도 그 무엇이라도 편안하게 집중하게 만들어주네요. 자주 지나다닌 길인데 이런 곳이 있는줄 몰랐어요. 다음에도 집중이 필요할때 다시 방문하려고 해요.', 10, 7, 'GOOD', SYSTIMESTAMP);
