INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '서울에서 분위기도 좋고 집중하기 좋은 북카페 찾기 은근 힘든데 .. 여기가 그런 곳인 것 같아요! 책읽기, 작업하기 모두 안성맞춤인 카페입니다 👍 커피맛도 좋아서 다음에 또 방문할게요 !.!', 25, 10, 'GOOD', SYSTIMESTAMP);
