INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '공부하기에도 좋고 적당히 조용해서 너무 좋았습니다 좌석도 편안하니 작업하기좋네요 무엇보다 분위기가 좋아요 홍대카페에 중에 최고', 85, 15, 'GOOD', SYSTIMESTAMP);
