INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '혼자 근처 홍대맛집 갔다가 찰스엔터님 영상보고왔다는 후기보고 바로 달려왔어요!! 분위기가 너무 좋고 조용해서 책읽기 너무 좋은 거 같습니다. 조용함과 차분한 공간을 원하신다면 완전 추천드려요!', 29, 9, 'GOOD', SYSTIMESTAMP);
