INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '친구 소개로 왔어요 :) 책 읽기도 좋고, 차분히 얘기 하러와도 좋을것같네요 🥨 나만 알고 싶긴하지만. . . 롱런을 위해 후기 올립니당 ! 다음에도 올게용 🤍🤍 #홍대카페 #커피맛집 #디저트맛집', 117, 26, 'GOOD', SYSTIMESTAMP);
