INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '홍대카페 중에 가장 조용하고 공부하기 좋습니다! 분위기도 좋아서 데이트하러 오기도 좋을 것 같습니다 책 읽기 좋은 카페라 책 한 권 들고오셔도 좋을 것 같아요', 40, 3, 'GOOD', SYSTIMESTAMP);
