INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '분위기가 좋아서 작업하기 오기 좋을것 같아 자주 방문할 것 같아요. 매장도 넓어서 친구들, 연인과 함께 오기 좋고 커피맛집입니다👍👍', 19, 3, 'GOOD', SYSTIMESTAMP);
