INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '이렇게 작업친화적인ㅎㅎ 공간은 처음이에요:) 조명, 인테리어, 가구, 음악 전부 창작활동 하기에 맞춤이라 ''창조적인 사람들을 위한 영감의 공간''이라는 소개글 그대로를 실현한 카페네요~ 홍대 온 김에 작업공간이 필요해서 와봤는데 이 공간을 오려고 홍대를 찾게될 것 같아요b', 30, 6, 'GOOD', SYSTIMESTAMP);
