INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '두 번째 방문이에요... ♡ 홍대 약속 있어서 왔다가 조용히 책 읽고 할 일 할만한 곳이 없을까 생각하다가 저번에 좋았던 기억이 와서 다시 왔습니다 ㅎㅎ 치즈케이크는 저번에도 먹고 맛있ㅇ서 또 시켰고 피치 티 너무너무 맛있어요 다음에는 초코케이크 먹어볼래요!', 109, 19, 'GOOD', SYSTIMESTAMP);
