INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '연남에서 업무 볼 공간이 필요했는데 렉터스라운지 홍대가 딱이네요! 노래도 잔잔하고 콘센트와 책상도 넉넉해서 너무 좋아요:) 자주 애용할 예정입니다✌️💕 당신의 평안을 주는 카카오음료도 추천합니다!!', 36, 3, 'GOOD', SYSTIMESTAMP);
