INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '홍대에서 사람많이 없고 급히 작업할수 있는 공간 검색하다 발견해서 방문했습니다! 골목에 생각지도 못한 곳이 있었네요 ㅎㅎ 좌석마자 콘센트도 구비되어있어서 맘편히 자유롭게 작업할수 있는 환경이 조성되어있어서 만족합니다!', 80, 17, 'GOOD', SYSTIMESTAMP);
