INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '카페 분위기가 너무 좋고 조용해서 집중하기에 딱 좋아요! 공간도 넓고 분위기가 여유로워서 쾌적하게 일할 수 있었어요. 음악도 너무 크지 않아서 방해되지 않고 전체적으로 편안한 분위기에서 일하기 좋은 장소였습니당', 47, 0, 'GOOD', SYSTIMESTAMP);
