INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '홍대카페 중 작업하기 좋은 카페로 최고입니다. 카페 그이상의 공간으로 언제든 편하게 와서 쉬기 좋은 공간입니다. 읽기 편안한 책들이 많아 시간을 보내기도 훌륭합니다.', 3, 0, 'GOOD', SYSTIMESTAMP);
