INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '어두운 조명과 조용한 분위기가 인상적인 스터디 카페입니다. 각 자리마다 스탠드 조명이 있어 집중하기 좋고, 좌석 간 간격도 넓어 쾌적했어요. 오렌지 자몽 에이드와 아이스라떼 모두 맛있고 비주얼도 좋아요. 혼자 공부하거나 조용히 책 읽고 싶은 분들에게 추천합니다!!!', 36, 9, 'GOOD', SYSTIMESTAMP);
