INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '홍대에서 카공하기 제일 좋은 (북)카페에요 시그니처 음료(논알콜)이 3개가 있는데 저는 그 중에서 당신의 평안이 제일 맛있더라구요...🫶🏻 깊은 코코아맛! 당도도 0~200까지 조절 가능한데 50은 살짝 쌉싸름하고 100은 약간 달아서 그 사이로 가능한지 여쭤봤더니 만들어주심 ㅠㅠ 직원분들 올 때마다 모두 친절하셔요', 58, 17, 'GOOD', SYSTIMESTAMP);
