INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '홍대 한복판에서 찾기 힘든 조용하고 집중하기 좋은 작업실 카페예요 노트북하기도 편하고 좌석이 다양해서 소파에서 일행이랑 조용히 대화할 수도 있어요 커피맛있어요', 11, 0, 'GOOD', SYSTIMESTAMP);
