INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '두번째 방문한 렉터스 라운지 공간이 예쁜데 널찍하고 음악도 적당한 볼륨으로 잔잔하게 나와서 집중하기 참 좋다 콘센트 있는 자리도 많아서 노트북 들고 작업하거나 공부하러 어디가지 할 때 생각나는 곳 건물 하나를 다 쓰고 3개의 층이 있는만큼 자리가 아주 많아서 붐빌 때도 자리 걱정 하지 않아도 된다 무엇보다 커피가 진하고 맛있어서 좋아하는데 특히 롱블랙은 아주 진하니 아메리카노의 깔끔함이 좋은데 더 강력한 풍미를 원한다면 주문해보시길 ! 저번에 시켰던 시그니처 음료도 맛있었다', 54, 16, 'GOOD', SYSTIMESTAMP);
