INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '공부하러 자주 왔던 곳인데, 오랜만에 친구랑 방문했어요! 구석구석 아늑한 좌석이 많아서 편히 쉬다가기 좋아요🥰 에어컨도 빵빵해서 시원하게 잘 머물다갑니다💙', 32, 3, 'GOOD', SYSTIMESTAMP);
