INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '카페 순례자 또 등장💨 오늘은 홍대 렉터스라운지 다녀왔어요! 입구부터 깔끔-하고 힙한 분위기! 공간 넓고 조용해서 노트북 펼치기도 딱 좋았어요💻 (혼자 집중하고 싶은 날 완전 추천!) 뱅쇼 – 와 이거 진심 몸 녹는 맛…! 과일 향 가득하고 시나몬 향 솔솔 올라오는 게, 잔도 예쁘고 따뜻하게 내어줘서 한 모금 마시자마자 “아… 살 거 같다” 나옴ㅋㅋ 무엇보다 직원분들 친절해서 기분 좋게 나왔어요🥹 조용하고 쾌적해서 다음엔 공부하러 또 올 듯! (콘센트 많은 것도 완전 굿굿) 홍대에서 분위기+맛+여유 세 박자 다 잡고 싶다면 무조건 렉터스라운지 추천! 📍 재방문의사 1000%', 14, 6, 'GOOD', SYSTIMESTAMP);
