INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '카페 넘 쾌적하고 작업하기 딱 좋아요~~ 2번째 방문인데 여전히 좋네요 ㅎㅎ 혼자 오기에도 좋고 조용히 대화하기도 좋은거 같아요 추천드립니당', 71, 13, 'GOOD', SYSTIMESTAMP);
