INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '홍대 근처 카페들은 다 너무 시끄러워서 작업하기 쉽지 않았는데 여기는 조용하고 좌석도 편해서 좋아요. 메뉴명들도 재치있어서 더 맛있게 느꼈졌습니다. 담에 또 올게요! #서울북카페 #홍대카페 #작업하기좋은카페', 40, 4, 'GOOD', SYSTIMESTAMP);
