INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '조용해서 작업하기 좋은 카페인 것 같아요. 내부도 깔끔하고 넓어서 자주 오게 됩니다. 책도 많아서 책 읽기 좋은 카페인 듯 합니다.', 49, 1, 'GOOD', SYSTIMESTAMP);
