INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '차분하고 분위기 좋아요 :) 주차가 조금 불편허긴 했지만 들어오자마자 그런 불편함은 충분히 감수 될 정도로 좋아서 만족합니다 만족합니다 음악도 잔잔하고 아늑해서 편하게 쉬는 숨은 공간이니 홍대 오심 들려보세요', 46, 2, 'GOOD', SYSTIMESTAMP);
