INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '오랜만에 다시 오는 홍대에 와서 식사를 하고 다음 일정까지 시간이 조금 남아서 노트북 작업을 하기 위해 찾은 카페. 입구에서 바라본 느낌은 정돈이 잘 되어 집중하기 좋겠다 싶어 들어왔는데, 인테리어가 깔끔하게 잘 되어 있고 커피의 맛과 작업환경이 너무 좋아서 무더운 날씨에도 불구하고 마음이 평안해져서 좋았습니다. #서울북카페#홍대카페#작업하기 좋은카페#책읽 기좋은카페#노트북하기좋은카페', 26, 9, 'GOOD', SYSTIMESTAMP);
