INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '1. 주택을 리모델링해서 홍대카페 중 친숙한 분위가 좋습니다. 2. 커피가 원하는 바디감이 좋네요 (롤블랙) 커피맛집 3. 방으로 된 곳이 조금 더움감이 있는데 가만히 있으면 시원해욧!', 70, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '리뷰로 봤을 때 인테리어가 워낙 이뻐서 사람들이 많지 않을까 싶었는데, 조용한 골목에 위치해있고 한적해요! 안에 분위기도 조용하고 테이블에 콘센트도 있어서,  노트북 작업하기 딱이에여😊', 26, 0, 'GOOD', SYSTIMESTAMP);
