INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '잠봉뵈르 저번에 먹었는데 너무 맛있어서 오늘도 먹음요. 진짜 너무너무 맛있엉ㅜㅠ올리브빵이랑 잡곡빵 둘다 맛있는데 올리브가 좀 더 내취향. 그리고 인테리어는 말할것도 없음.작업하기 최고의 공간❤️', 18, 10, 'GOOD', SYSTIMESTAMP);
