INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '홍대 렉터스라운지에 다녀왔는데, 노트북 작업하기에 정말 좋은 카페에요😇😇. 다양한 공간이 있고 의자도 편안해서 오래 있어도 부담 없습니다. 커피도 맛있어서 작업하실 분들께 추천드릴게용 !! #홍대카페 #서울북카페', 21, 7, 'GOOD', SYSTIMESTAMP);
