INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '항상 들러서 천천히 커피 즐기고 가요! 공감도 좋고 맛있는 커피도 많아요! 일하고 집중하기도 좋은 공간이어서 자주 오고있습니다.', 86, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '오래 운영하는 카페를 찾던중 우연히 발견한 보물과도 같은 곳입니다! 번잡한 홍대속에 이런 고요함이 있을 줄 상상도 못했어요 디저트와 같이 즐길 다양한 책들이 마음을 편안하게 해줍니다', 130, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '작업하는 사람들을 위한 최고의 공간. 어둡고 아늑한 분위기를 좋아하시는 분들께 딱입니다. 지하부터 2층까지 다양한 좌석들을 골라 앉는 재미가 있네요. 시끌벅적한 홍대에서 오롯이 집중할 장소를 찾으신다면 바로 이곳. 또 방문하겠습니다.', 9, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '노트북 작업하기 너무 좋은곳입니다! 1인석도 잘되어있어서 혼자 작업하기도 괜찮고 넓은 좌석도 있어서 모임하기도 좋을거 같습니다. 자주오려고요 #작업하기 좋은 카페 #커피맛집', 46, 4, 'GOOD', SYSTIMESTAMP);
