INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '넷플연가 모임에 참여하러 방문했습니다 긍정과 활기라는 음료를 마셨는데 달콤하고 고소한 블랙돌체라떼로 적당한 카페인과 달달함이 있어서 좋았습니다. 이 모임은 참 신비롭더라고요. 음료의 온도가 적당해서 즐기기 좋았습니다.', 46, 5, 'GOOD', SYSTIMESTAMP);
