INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '홍대 놀러왔다가 근처 카페 검색해서 들어왔는데 분위기도 너무 좋고 커피도 맛있어요!!  우리동네에도 이런카페 있었으면ㅠ 다음에 홍대 올 일 있으면 꼭 또 오고싶네요~~', 28, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '오랜만에 작업하려고 왔는데 여전히 차분한 음악과 조명이 작업하기 참 좋습니다, 종종 야간작업 할때 찾기 딱이고 아메리카노가 구수+약간산미 포함해서 적당히 다크하니 참 맛있어요! 산미끼 있는 커피 싫어하는데 이건 적당해서 맛있어요 오늘도 작업하시는 프리랜서님들 화잇팅….', 125, 25, 'GOOD', SYSTIMESTAMP);
