INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '조용하면서도 감성적인 분위기의 북카페라 책 읽기와 대화 모두에 완벽했습니다. 홍대 번화가 속 숨은 휴식처 같아요. 감사합니다☺☺👍🏻 #서울북카페 #홍대카페', 21, 10, 'GOOD', SYSTIMESTAMP);
