INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '진짜 분위기도 너무 좋고 커피도 맛있어요. 잠 깨려고 커피에 샷추가 한번할지 두번할지 고민하다 한번만 했는데도 엄청 진하고 좋아요. 강추합니당 #홍대카페 #커피맛집', 16, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '24시간 작업할 수 있는 카페 찾다가 분위기도 좋길래 왔습니다. 늦게까지 카공하기 좋은 곳입니다. 앞으로 자주 올 것 같아요~~', 34, 9, 'GOOD', SYSTIMESTAMP);
