INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '처음 방문했는데 완전 느좋 카페네요!! 맛있어서 먹다가 사진 찍었어효 ㅋㅋ 🥰 분위기 너무 좋고 공간도 넓어서 작업하러 오기 너무 좋아요!! 사장님도 친절하시고 시원하고 화장실도 넓고.. 공간 자체에 신경을 많이 쓰신 느낌이라 단골 될 것 같아용🥹🤍🤍', 96, 24, 'GOOD', SYSTIMESTAMP);
