INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '근처에 일정이 있어서 잠시 책 읽을 카페를 찾아가 리뷰보고 알게 되었어요. 노트북 가지고 작업하기도 좋고 책읽기도 좋고 단체 스터디하기도 좋은 적당히 넓은 공간이에요. 차분하게 머물다 가기 좋은 공간입니다. 커피도 맛있고 홍대에 이런 곳이 있어서 좋네요', 36, 3, 'GOOD', SYSTIMESTAMP);
