INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '오랜만에 홍대왔다가 시간이 떠서 잠시 작업할 공간을 찾다 알게되서 우연히 와봤는데요. 공간 하나하나가 너무 다른느낌으로 잘되어있어서 혼자 일을 할때나 친구를 만날때 언제든지 오고 싶은 카페에요! 번잡한 홍대에서 잠시 여유를 누리고 싶고 맛있는 커피가 생각날땐 앞으로 여기로 올거에요😀', 5, 4, 'GOOD', SYSTIMESTAMP);
