INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '홍대에 있는 조용한 북카페, 노트북 작업하기 딱 좋아요. 책 읽기 좋은 분위기라 혼자 집중하기에 최적의 공간. 서울에서 이런 감성 작업카페 찾기 힘들어요, 재방문 각!', 57, 13, 'GOOD', SYSTIMESTAMP);
