INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '분위기가 너무 좋은 카페같아요! 책읽기 좋고, 작업하기 좋은 카페네요. 앞으로 일하거나 공부할 때는 여기와서 할거 같아요~ 너무 추천합니다 ! 다들 와서 힐링하고 가세요~~👍', 35, 10, 'GOOD', SYSTIMESTAMP);
