INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '조용하게 쉬고 싶어서 카페를 찾던중 제가 찾는 그 느낌이랑 딱! 맞는 카페를 발견했어요! 여기 한적하게 책 읽기 좋고 야외공간 테라스도 캠핑느낌으로 분위기 즐기기 너무 좋아요!!!! 2층은 진짜 작업이나 업무하기 좋을듯해서 다음에 또 노트북 들고오게요!', 70, 14, 'GOOD', SYSTIMESTAMP);
