INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '홍대에서 북카페로 강추해요! 매장이 되게 넓고 유니크해서 더 좋은 거 같아요 여기서 노트북으로 작업하기도 공부하기도 좋은 카페인 거 같아요! 그리고 책도 있어서 편하게 있기 좋네요 강추〰️⭐️', 20, 6, 'GOOD', SYSTIMESTAMP);
