INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '혼자 조용히 머무르며 책 읽거나 노트북 작업하기 좋은 북카페였어요! 콘센트가 곳곳에 있어 작업 환경이 잘 갖춰져 있고, 서가에는 다양한 책이 구비되어 있어 혼자만의 회고 시간 갖기에도 안성맞춤인 공간입니다. 베이글+솔티버터도 맛있습니다:)', 41, 7, 'GOOD', SYSTIMESTAMP);
