INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '인테리어, 창밖뷰, 음악, 커피맛, 담요랑 책까지 매력적이고 만족스러운 공간입니다! 공간과 서비스에 대한 사장님의 고민과 정성이 보여서 더 애정이 가는 카페였습니다! 창밖 조경이 예쁜데 맑은 날 와서 창가자리에 앉았더니 채광에 마음이 편안해지네요☺️ 노트북 작업하기 좋은 카페, 혼자 사색하기 좋은 카페, 책 읽기 좋은 카페, 조용하고 느긋하게 시간 보낼 수 있는 카페 찾는다면 추천합니다!! 좋은 공간 발견해서 좋네요. 오래 운영해주셨으면 좋겠습니다!', 12, 9, 'GOOD', SYSTIMESTAMP);
