INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '요즘 북카페를 찾아다니는 사람입니다. 여지껏 다녀본 북카페 중 가장 다용도에 감성 넘치는 인테리어 같아요. 편안한 작업공간도 재공해 주시고요! 여기서 그림 많이 그릴 것 같습니다 :)', 31, 6, 'GOOD', SYSTIMESTAMP);
