INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '공부를 위해 조용한 카페를 찾고있었는데 웬걸.. 핫플레이스를 발견하고 말았습니다 분위기면 분위기 공간이면 공간 아니 근데 커피 맛까지 이렇게 훌륭하면 다른 카페 어떻게 가요 🤣🤣🤣 차분하게 책읽고 싶거나 작업할 일이 있다면 이곳을 강력 추천합니다 따봉 육천 삼백개 드립니다😄', 1, 1, 'GOOD', SYSTIMESTAMP);
