INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '제가 갔던 북카페 중 최고입니다. 여기 인테리어 진짜 따뜻한데 세련됐습니다.. 완전 만족 앞으로 무조건 다시 올 예정이고 여기 단골 될 거 같습니다!! 강추!! #서울북카페 #홍대카페 #작업하기좋은카페', 10, 8, 'GOOD', SYSTIMESTAMP);
