INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '업무가 많아서 항상 조용하고 분위기 좋은 카페를 찾곤 했는데 공간도 넓고 분위기도 좋고 노래도 좋고 감성도 좋고 이런 느좋 카페 저만 알고 싶은데 제가 특별히 공유합니다;;; 공익을 위해서;;;; 여기 정말 좋아요 첨 왔는데 반해버렸어요 😵‍💫😵‍💫🩷🩷🩷 담에 또 올 것입니다…. 사장님 돈 많이 버세요', 5, 8, 'GOOD', SYSTIMESTAMP);
