INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '퇴근하고 작업하러 왔는데 음악도 잔잔하니 집중 최고입니다🫶 칵테일류도 있어서 저녁에 오시는 분들도 취향껏 즐기기에 좋은 곳인 것 같아요 또 올게요🥰', 26, 7, 'GOOD', SYSTIMESTAMP);
