INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '책+ 커피+ 공간  이 참 조화롭습니다 책을 가져와도 좋고 그냥 와도 도서관처럼 책이 많아서 좋아요 무엇보다 조명이 밝아서 글쓰고 책읽는 등의 작업학 딱입니다 ! 앞으로 자주 올게요 :) 롱블랙과 통밀 베이글 맛있어요', 75, 14, 'GOOD', SYSTIMESTAMP);
