INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '노트북으로 작업하기 좋아요 특히 2인 작업실이 좋아보였는데 혼지와서 넘 아쉽... 다음에 친구랑 같이오면 포근한 분위기에서 작업 가능할 것 같아요. 잔잔한 재즈음악이랑 의견을 나누고 계시는 다른 분들의 에너지가 잘 조화되는 느낌. 개인적으로 좋아하는 분위기에요', 17, 0, 'GOOD', SYSTIMESTAMP);
