INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '음료가 맛있고 분위기가 좋아요!! 자리가 많습니다 커플끼리 와서 이야기 하거나 공부하는것도 좋아요 저희는 왁자지껄보다는 분위기를 즐기러 왔어요', 8, 1, 'GOOD', SYSTIMESTAMP);
