INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '#서울북카페 #홍대카페 #책읽기 좋은 카페 지인들과 독서 모임 하려고 왔는데 책읽고 대화나눌 수 있는 파티션 룸도 있네요! 분위기도 넘 좋습니다 👍😊', 32, 7, 'GOOD', SYSTIMESTAMP);
