INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '공부하기에 정말 좋은 카페입니다. 공간이 넓고 공간마다 분위기가 달라요. 독서실 느낌인 곳, 스터디룸 같은 곳 라운지?같은 곳 등등 다양한 공간들로 이루어져 있어서 본인이 선호하는 분위기의 공간에 앉으시면 됩니다. 그리고 잠봉뵈르가 너무 맛있어요💕💕 적당히 가득 들어있는 버터와 잠봉, 느끼함을 싹 잡아주는 후추, 쫄깃한 빵까지..❤️ 공부하다가 출출하시면 꼭 드세요.', 42, 3, 'GOOD', SYSTIMESTAMP);
