INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '차분하고 인테리어가 너무 예뻐요 조용하고 자리도 잘 되어있어서 작업하러오기 좋은것같아요 다음에 책읽으러오고싶어요 혼자 앉는 자리 뷰가 좋아서 한적하게 시간보내기 좋을것같아요', 18, 1, 'GOOD', SYSTIMESTAMP);
