INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '환경이 정말 좋습니다! 우연히 들어갔는데 뜻밖의 서프라이즈를 얻었습니다! 친구들과 자주 오겠습니다! 인테리어는 어두운 색상으로 조용한 느낌을 주며 분위기감이 정말 좋습니다. 하루 종일 공부하러 와도 지루하지 않아요. 정원에 가서 앉아 있을 수도 있으니까요.', 9, 0, 'GOOD', SYSTIMESTAMP);
