INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '검색으로 노트북 하기 좋은 카페 찾아서 왔는데 너무 좋네요!!잔잔한 음악에 집중도 잘 돼고 다양한 공간이 있어서 기분에 따라 자리 골라서 앉을 수 있을 것 같아요!화장실도 깨끗해서 더더욱 만족입니다!!', 107, 19, 'GOOD', SYSTIMESTAMP);
