INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '카공하기 좋은 분위기예요!! 인테리어도 이쁘고 2층까지 있어서 자리도 많고 좋아요 무엇보다 화장실도 엄청 깨끗합니다👍👍 앞으로 여기에서 계속 카공하러 올 거같아요😍', 448, 31, 'GOOD', SYSTIMESTAMP);
