INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '노트북으로 할일이 있어 카페를 찾다가 디저트가 맛있다고해서 왔는데...샌드위치도 맛있고 커피도 맛있어서 너무 좋았어요. 혼공하기에도 좋은 카페인거같아요~', 18, 9, 'GOOD', SYSTIMESTAMP);
