INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '각 층, 구역마다 다른 분위기때문에 다양하게 즐길 수 있고, 여러 사람들과 스터디나 세션 같기에도 좋아보여요! 노래도 차분하고 콘센트도 많아서 오래 작업하기 최적의 장소입니다! 음료 종류도 다양하고 맛도 괜찮아서 꼭 작업하러 오지 않아도 오기 좋은 것 같아요ㅎㅎ 번잡스러운 홍대 거리에서 이렇게 잔잔하고 힐링되는 대형전시카페가 있다니 최고👍', 39, 10, 'GOOD', SYSTIMESTAMP);
