INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '커피 정말 깔끔하고 맛있습니다! 카페 내부가 굉장히 차분해서 공부하시는 분들도 꽤 많아요 노래도 잔잔하고 여름엔 시원해서 딱인것같아욤👍', 118, 19, 'GOOD', SYSTIMESTAMP);
