INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '집중해서 작업을 해야하는 곳을 찾고있었는데, 마침 리뷰가 꽤 괜찮고 비교적 가까워 찾아오게 되었습니다. 내부 인테리어가 정말 아름다웠고 작업에 집중할 수 있는 환경이어서 정말 마음에 들었어요. 음료와 디저트 또한 과하지 않은 맛이라 작업 중간중간 먹기 너무 좋았어요. 다음에 또 방문할 것 같아요!!', 15, 10, 'GOOD', SYSTIMESTAMP);
