INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '저는 당신의 평안 맛 당도 없이 시켜봣는데 충격적인 맛이지만 넘 건강한 맛이예요!! 공부하기에 분위기도 좋구 편안하네요!ㅎㅎ 칭구랑 방문했는데 좋은데 찾은거같아여!!ㅎㅎ 담에 또 오려구얌', 84, 14, 'GOOD', SYSTIMESTAMP);
