INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '분위기 너무 좋고 음료도 맛있어요!! 저번에도 여러번 방문했었는데 매번 올때마다 깨끗하구 좋아요!! #서울북카페 #홍대카페 #작업하기 좋은 카페 #책 읽기 좋은 카페 #커피맛집 #디저트 맛집', 16, 5, 'GOOD', SYSTIMESTAMP);
