INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '책 읽기 좋은 카페 검색해서 방문했는데 생각보다 더더 만족스러웠어요 ㅠㅠ 층도 여러개도 콘센트도 많고 분위기도 차분하고 딱 책 읽고 작업하기 좋은 곳이어서 강추입니당 베이글도 맛있어요 강추!!', 35, 8, 'GOOD', SYSTIMESTAMP);
