INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '책읽고 작업하기 너무 좋은 카페에요. 겉으로 보기보다 안쪽에 공간이 많고 여러명이서 앉을 수 있는 테이블도 마련되어있습니다. 심심할때 언제든 꺼내읽을 수 있는 책도 많이 마련되어있고 무엇보다 밤 12시까지 영업해서 저녁 늦은시간 시간 보내기 좋은 곳입니다.', 82, 18, NULL, SYSTIMESTAMP);
