INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '이 카페에만 존재하는 메뉴들로 마셔봤는데 역시 너무 맛있습니다! 치즈케이크도 너무 맛있고요! 라이노 돌릴때 여기 와서 차분하게 작업하면 좋아요!', 11, 8, 'GOOD', SYSTIMESTAMP);
