INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '왜 이제야 알았지 싶은 홍대 카공하기 좋은 카페 정말 넓고 콘센트 다 있고 집중하기 좋아요.. 뭔가 독서모임 영화모임 사람들이랑 와서 영감의 대화 나누기 좋은 공간 또와야지', 39, 0, 'GOOD', SYSTIMESTAMP);
