INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '밥먹고 작업하기 좋은 카페를 검색하다가 우연히 들렀는데 너무 좋은곳이에요 ㅎㅎ 콘센트가 구비되어있는 좌석이 많아서 노트북 작업하기에도 좋고 책읽기에도 좋은것같아요! 2-3시간정도 간단히 작업하기 좋은 홍대카페로 추천합니다 ㅎㅎ 다음에 또 방문할게요 :)', 35, 2, 'GOOD', SYSTIMESTAMP);
