INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '총 3개 층으로 되어있어서 갤러리 구경도 하고 분위기가 좋아서 도란도란 얘기하다 갔어요 막 시끄럽거나 수다스럽지 않아서 좋았고 종종 올 것 같아요 ㅎㅎ', 3, 10, 'GOOD', SYSTIMESTAMP);
