INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '주택 개조 카페라 여러 층이라 공간도 넓고 작업 공간이 많아요! 무엇보다 모니터도 사용할 수 있고 메모지와 펜도 있어서 책읽고 일하기 넘넘넘 좋았어요!📚 층마다 컨셉 다른 것도 좋네요 :)', 22, 3, 'GOOD', SYSTIMESTAMP);
