INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '조도가 낮고, 공간도 넓어서 집중해서 작업해야할 때 자주 올 것 같아요! 게다가 음료도 특이한 메뉴들이 많아서 골라 마시는 재미까지💜', 15, 7, NULL, SYSTIMESTAMP);
