INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '전 거리가 먼데도 여기오려고 지하철 30분 이상 탑니다! 디저트 도장깨기 중인데 여태 먹어본 초코케이크, 치즈케이크, 잠봉뵈르, 베이글 다 맛있었어요…🤎분위기 좋은건 당연하고 디저트까지 좐맛', 10, 2, 'GOOD', SYSTIMESTAMP);
