INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '공부하러 왔는데 카페 분위기, 인테리어, 음악, 전경 모두 다 너무 좋네요. 이 공간에 있다는 것만으로 편안해지네요:) 앞으로도 혼자 작업할거 있을때 자주 오고싶어요-! 레몬블랙티 시켰는데 향긋하고 맛있네요 커피도 맛있을것 같아서 다음엔 커피 시키려구요:) 혼자 카공하거나 작업하시는 분들 추천입니다!', 14, 9, 'GOOD', SYSTIMESTAMP);
