INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '첫방문인데 잘 꾸며져있고 생각보다 잘되어있어서 놀랐어요 긍정과 활기 라떼 디카페인으로 시켰는데 진짜 맛있어뇨 당도랑 얼음도 조절할 수 있어 조아요! 공부하고 작업하기 좋은 카페에요! 나중에 공부하러 또 올것 같아요', 35, 9, 'GOOD', SYSTIMESTAMP);
