INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '밤늦게까지 하는 카페를 찾고 있었는데 3층까지 있는 대형카페고 다인원으로 와도 좋을 것 같은 큰 테이블이 있어서 또 방문할 것 같습니다! 조용한 공간도 있어 공부하기에도 좋을 것 같아요 ㅎㅎ 무엇보다 시그니처 음료가 너무 맛있었어요😍💗 #서울북카페 #홍대카페 #작업하기좋은카페 #책읽기좋은카페 #노트북하기좋은카페', 177, 67, 'GOOD', SYSTIMESTAMP);
