INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '똥손이라서 사진에 안나타나는데 실제보면 카페 더 예쁘고 공부나 책읽거나 작업하기 좋아요! 매장도 넓어서 자기 걱정할 필요 없을듯요 다음에도 이용할 것 같아요', 35, 10, 'GOOD', SYSTIMESTAMP);
