INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '단독 건물로 이뤄져 있으며 각 층마다 컨셉이 있었어요 작업자의 방, 창작자의 방, 소통의 방까지 자유롭게 선택해서 즐길 수 있는 장소가 마련되어 있어 색다르면서 재미있었어요 커피도 원두가 깔끔해서 잠봉뵈르 샌드위치하고 찰떡 궁합으로 맛있었어요 날 좋은 날 방문해서 좋은 에너지 얻고 가는 기분이네요!!', 26, 8, 'GOOD', SYSTIMESTAMP);
