INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '렉터스라운지 홍대는 깔끔하고 넓은 공간이 인상적이에요. 편한 책상과 의자가 잘 갖춰져 있어 장시간 앉아 있어도 부담이 없고, 조용해서 작업에 집중하기 정말 좋은 공간입니다. 음료도 맛있어서 재방문 의사 있어요!', 41, 10, 'GOOD', SYSTIMESTAMP);
