INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '조용히 혼자 할게 있어서 왔는데 집중하기 좋아요!! 잔잔한 음악도 나오고 노트북 하는분들도 많아요~~!! 종종 이용할듯해요:)', 11, 7, 'GOOD', SYSTIMESTAMP);
