INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '오랜만에 다시 방문한 곳인데 이전에는 아메리카노를 먹어서 오늘은 시그니처 메뉴를 시켜봤는데 맛있더라구요!! 당도, 얼음 조절 같이 세세하게 변경헐 수 있어서 좋았고 음료 이름이랑 카드가 같이 오니까 나름 기분 전환되고 혼자와도 같이 와도 괜찮은 좌석 구조이구, 이것저것 작업하기 좋은 카페같아요!! ㅎㅎ 야외 좌석도 있어서 날씨좋은 날에는 밖에서 수다떨어도 좋을 분위기예요! 오늘은 업무하러 왔지만 다음엔 수다떨러 오겠습니당 :)', 333, 69, 'GOOD', SYSTIMESTAMP);
