INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '홍대입구역 근처 분좋카. 인테리어 멋지고 작업하기 좋은 공간 추천☕️🤎 커피 : 롱블랙 맛있고 분위기 : 노래가 조용하면서도 편하게 대화하기도 좋네요 방문목적 : 일하시는 분들이 많아보이는데, 디저트 먹고 딩굴딩굴하는 분들도 있어요', 37, 6, 'GOOD', SYSTIMESTAMP);
