INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '작업하기도 좋고 분위기가 좋네용 잠봉뵈르가 맛잇어요 치즈랑 햄만 들어갓는데 맛이있구 좋아요 따로 분리된 다인석이 있어서 다같이 와서 회의하거나 해도 좋을것 같아요', 22, 2, 'GOOD', SYSTIMESTAMP);
