INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '메뉴 이름들도 따듯하고 힘되네요! 작업할 때마다 오는 곳인데, 공간도 지하부터 지상 2층까지 넉넉하고 콘센트도 넉넉합니다 책도 엄청 많아서 읽고 싶은 책 골라서 읽기 좋아요 빈손으로 와도 좋은 곳!', 24, 10, 'GOOD', SYSTIMESTAMP);
