INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '분위기도 너무 좋고 마음이 평안해지는 공간이에요. 작업하기에 공간이 잘 되어있고 조용해서 작업자분들 추천드립니다. 그리고 너무 친절하셔유🩷🩷🩷', 30, 4, 'GOOD', SYSTIMESTAMP);
