INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '전부터 홍대에서 공부할 때면 꼬옥 오는 곳입니다! 좌석도 넓고 공부하기 딱 좋은 분위기에요😊 커피도 음식도 맛있고 집중도 잘 되어서 멀리서도 오고싶은 곳이에요🫧', 1, 7, 'GOOD', SYSTIMESTAMP);
