INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '모임으로 우연히 알게되어 첫 방문했습니다. 공간이 이렇게 크고 넓을지 몰랐는데 혼자 혹은 지인들과 스터디나 작업하러 오기 좋은 공간 같아요. 음료도 나쁘지 않구요! 컨셉도 독특해서 정말 맘에 들어요!', 49, 7, 'GOOD', SYSTIMESTAMP);
