INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '조용하고 편안한 공간이었어요! 이야가 나누기 좋은 곳도 물론 있었습니다☺️ 과제나 공부하러 오기 좋은 것 같아요~!! 영업 시간도 길고!', 57, 14, 'GOOD', SYSTIMESTAMP);
