INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '작업하기에 최적화된 조용하고 쾌적한 분위기의 카페입니다. 좌석 간 간격이 넉넉하고, 노트북 사용하기에도 전혀 불편함이 없어요. 조도와 음악 볼륨도 집중하기 딱 좋은 수준이라 시간 가는 줄 모르고 머물게 됩니다. 음료도 전체적으로 맛이 깔끔하고 밸런스가 잘 맞아, 한 잔 마시고 나면 다른 메뉴도 궁금해지는 곳이에요. 기분 좋게 작업을 시작할 수 있었어요. 다음에도 꼭 다시 오고 싶은, 재방문 의사 100%인 카페입니다.', 46, 5, 'GOOD', SYSTIMESTAMP);
