INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '친구들과 회의를 가지고자 방문한 렉터스라운지 홍대! 아무래도 목적이 회의이다 보니 카페를 고르는데도 신중한 편인데, 렉터스라운지는 북카페이다 보니 너무 완벽한 선택이었어요 😍👍 분위기도 차분하고 조용해서 이야기하기도 편하면서도 집중이 잘되어서 또 재방문할 의사 100%입니다!', 46, 8, 'GOOD', SYSTIMESTAMP);
