INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '동료들과 잠깐 이야기하러 왔는데 분위기, 커피맛 정말 맛있네요~~ 무엇보다 혼자 와서 공부하기 좋은 카페네요. 자주 책보러 와야겠네요~ 그리고 사장님이 친절하셔유😃', 37, 5, 'GOOD', SYSTIMESTAMP);
