INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '우연히 들렀는데 조용히 집중하기 좋았어요. 비치된 책을 읽을 수도 있어서 좋아요. #서울북카페 #흥대카페 #작업하기 좋은 카페 #책 읽기 좋은 카페 #노트북하기 좋은 카페', 45, 0, 'GOOD', SYSTIMESTAMP);
