INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '카페에 들어서는 순간부터 따뜻하고 감각적인 분위기가 인상 깊었어요. 조용하면서도 세련된 인테리어 덕분에 자연스럽게 마음이 편안해졌고, 앉자마자 이곳이 단골이 될 것 같다는 생각이 들었습니다. 시그니처 메뉴인 ‘긍정’과 ‘활기’를 주문했는데, 이름만큼이나 긍정적인 에너지가 느껴지는 맛이었어요. ‘긍정’은 부드럽고 진한 풍미가 일품이었고, ‘활기’는 산뜻하면서도 깊은 여운을 남기는 향이 인상적이었습니다. 커피를 마시는 내내 정성이 느껴졌고, 공간과 어우러져 더욱 특별한 경험이 되었어요. 좋은 커피와 좋은 분위기가 만나 정말 만족스러운 시간을 보냈고, 다음에도 꼭 다시 방문하고 싶은 곳입니다.', 32, 10, 'GOOD', SYSTIMESTAMP);
