INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '잠봉뵈르 샌드위치 꼭 드세요! 올리브빵+햄+버터+후추 조합으로 엄청 맛있어요! 커피도 맛있고요👍 혼자 공부하러 오거나 일하러오거나 책읽으러오거나(책없이 오셔도! 책들도 비치되어 있음!) 여럿이 회의하러오거나.. 그냥 다 뭐든 하기 좋은 공간이에요! 사진은 못찍었지만 2층에는 모니터 있는 테이블까지 있더라고요! 인테리어, 디테일 센스도 한 몫 합니다👍👍👍 오래있어도 눈치 안보일것 같구요!', 49, 9, 'GOOD', SYSTIMESTAMP);
