INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '저번에 책 읽으러 왔다가 분위기기 너무 좋아서 이번에 재방문했어요 :) 역시나 분위기가 너무 차분하고 따뜻해서 덕분에 잘 작업하다가 가요! 커피도 정말 맛있고, 잠봉뵈르(올리브)가 진짜 최고로 맛있어요! 태어나서 먹어본 잠봉뵈르 중 제일 맛있었어요🥹', 23, 10, 'GOOD', SYSTIMESTAMP);
