INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '몇 달 전에 발견한 카페인데, 공부하기 정말 좋아요! 총 3층으로 구성돼 있고, 야외 테라스는 데이트하기 좋고 나무진 작업공간으로 정말 좋아요. 컴퓨터도 있고 1인용 좌석, 단체석도 있어요. 공부할 때마다 찾아요 ㅎㅎ', 82, 17, 'GOOD', SYSTIMESTAMP);
