INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '커피 마시러 겁색하다가 우연히 발견하고 왔는데 특별한 메뉴도 있고 단독주택을 개조해셔 그런지 넓고 테라스 있는 야외도 이쁘네요^^ 전 긍정과 활기란 커피 메뉴 있어서 마셨는데 달달하면서 맛있네요.', 124, 20, NULL, SYSTIMESTAMP);
