INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '공간이 넓고 조용해서 작업하기가 좋아요 그리고 음료랑 음식이 맛있어요 홍대 인근 카페 여러군데 가봤지만 이만한곳이 없는것같아요!', 72, 18, 'GOOD', SYSTIMESTAMP);
