INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '만족스러운 카페!작업하기 너무 좋은 것 같아요 또 올 생각입니다. 홍대에 이런 곳이 숨어 있는 줄을 몰랐네요. 너무 조용하고 인테리어도 이쁘고 마음에 들어요', 40, 0, 'GOOD', SYSTIMESTAMP);
