INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '벌써 4-5번째 방문이에요! 거의 아지트가 된 렉터스 라운지... 조용하고 커피 맛있고 작업하기도 좋아요! 노래도 좋고 홍대 노트북 카페로는 여기가 최고 같아요! 담에도 또 올게용 여기 루이보스티 맛있어요 #서울북카페 #홍대카페 #작업하기좋은카페', 22, 3, 'GOOD', SYSTIMESTAMP);
