INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '홍대 근처에서 일 보고 작업할 것이 있어서 왔는데, 여기 너무 좋네요... 집중하기도 좋고 인테리어가 짱이에요! 그냥 검색해서 노트북 할 만한 곳으로 온 건데 힐링하고 갈 것 같아요 ㅎㅎ', 128, 24, 'GOOD', SYSTIMESTAMP);
