INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '연휴 끝나가는 중에 작업하러 들렀습니다! 매장이 세 개 층으로 이루어져있고, 검정색 톤 인테리어의 차분한 분위기예요. 마당도 있는데 너무 예쁘게 꾸며져 있었습키다. 아메리카노에 통밀베이글 주문했는데 커피도 맛있지만 베이글 따뜻하게 먹으니 넘 맛있었습니다~ 작업 혹은 조용하게 대화하실 분들에게 추천드립니다!', 43, 10, 'GOOD', SYSTIMESTAMP);
