INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '롱블랙 처음 마셔봤는데, 적당히 진하고 맛있는 것 같고 아메리카노보다 조금 더 부드러운 것 같아요. 공간도 다양하게 있고 취향에 따라 선택해서 작업하기 좋은 것 같습니다.', 34, 0, 'GOOD', SYSTIMESTAMP);
