INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '커피가 진하고 맛있어요. 예전에도 방문했었는데 지인에게도 소개하고 싶어서 왔습니다. 오늘은 커피만 마셨지만 잠봉뵈르도 맛있습니다.', 36, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '홍대 근처에서 독서모임이 있어서 장소를 물색하던 중 발견한 카페예요. 단독주택을 개조해서 만든 곳이라 큰 대문과 마당이 예쁘고 실내 공간은 블랙 톤의 인테리어가 세련된 분위기였어요. 카페 공부나 노트북 작업 하시는 분들도 많았고 모임 하면서 도란도란 이야기 나누기에도 좋았어요. 😍', 28, 3, 'GOOD', SYSTIMESTAMP);
