INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '다니는 네일샵이 홍대다보니 겸사겸사 작업할 카페를 찾던 중 발견했어요! 제가 딱 좋아하는 분위기의 적당한 차분함과 적당한 채광이 매력적으로 느껴졌어요. 번화가와는 조금 떨어져 인근도 조용한 분위기에요. 다음 방문에는 독서할 책 가져와서 다른 자리에 앉아볼까 해요! 완전 추천하는 카페입니다!', 27, 2, 'GOOD', SYSTIMESTAMP);
