INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '노트북하기 좋은 카페로, 다양하고 편안한 공간 구성이 인상적이에요! 편한 의자 덕분에 오래 앉아 있어도 부담이 없고, 맛있는 커피까지 더해져 작업공간으로 강력 추천합니다.', 121, 26, 'GOOD', SYSTIMESTAMP);
