INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '독서모임하러 매주 들르는 곳 !! 분위기도 너무 좋고 커피도 맛있어요 ☺️ 노래도 시끄럽지 않고 은은한 음악이라 집중도 더 잘되는 것 같아요~', 45, 6, 'GOOD', SYSTIMESTAMP);
