INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '공부하기 너무 좋은 카페입니다!! 자리마다 콘센트도 많고 컴퓨터 있는 책상도 있어요 다들 공부하러 오는 분위기라 조용하고 집중하기 좋습니다👍👍 시험기간마다 올거 같아요', 53, 13, 'GOOD', SYSTIMESTAMP);
