INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '북카페를 찾다가 이곳에 오게되었는데요, 조용하고 분위기도 작업하기에 집중이 아주 잘돼서 작업 후다닥 끝냈네요👍다음에 또 올게요! 홍대쪽에서 작업하거나 책 읽을 때 완전 추천합니다!✌️', 20, 6, 'GOOD', SYSTIMESTAMP);
