INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '홍대에 작업하기 좋은 카페 찾다가 발경했는데 인테리어와 분위기 모두 너무 만족스럽습니다! 스터디카페와는 다른 분위기를 찾으면서 집중할수있는공간 찾으신다면 모두 만족할만한 카페입니다!!', 23, 7, 'GOOD', SYSTIMESTAMP);
