INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '근처 팝업스토어에 놀러왔다가 작업할 곳을 찾고 있었는데 작업하기 좋은 카페가 있다기에 방문했습니다! 노래도 제가 작업할 때 듣는 노래에, 다들 같은 목적을 가지고 온 사람들만 모여 있어서 그런지 너무 소란스럽지 않고 적당한 백색소음으로 집중도 잘되는거 같아요', 5, 8, 'GOOD', SYSTIMESTAMP);
