INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '시험기간이라 과제도 많고 강의 들을 것도 많아서 왔는데 공부하기 좋은 공간 같아요 다음에도 올게요 #서울북카페 #홍대카페 #작업하기 좋은 카페 #책 읽기 좋운 카페 # 노트북하기 좋은 카페', 30, 10, 'GOOD', SYSTIMESTAMP);
