INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '커피가 맛있고, 조용해서 이야기 나누기 좋아요! 입구에 작품이 걸려있어서 창작을 위한 공간임을 알수있었어요 트레이와 조명 등 여러 소품들은 컬러풀하고 인테리어도 이뻐서 눈도 즐거워져요 #서울북카페 #홍대카페 #작업하기좋은카페 #책읽기좋은카페 #노트북하기좋은카페', 78, 15, 'GOOD', SYSTIMESTAMP);
