INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '분위기가 좋고 매장이 3층으로 이루어져 있으며 특이합니다! 생각보다 신선한 분위기라 신기했고 커피와 디저트 모두 맛있었습니다!!', 17, 7, 'GOOD', SYSTIMESTAMP);
