INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '시끄러운 홍대에서 ‘조용한 카페’를 검색했다. 과연 있을까…? 했지만 근처 100m 안에 있다는 결과에 발걸음을 옮겼다. 도착해보니 도서관과 카페 그 사이 어디쯤 존재하는 균형점을 참 잘 잡았다는 생각이 드는 곳이다. 전체적인 분위기 덕분인지 수다쟁이들 또한 볼륨을 적당히 줄이게 만든다. 그래서 책과 음악에 집중하기 참 좋다. 홍대시험 기간만 피하면 온전히 공간을 누릴 수 있을 듯 하다.', 35, 9, 'GOOD', SYSTIMESTAMP);
