INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '분위기도 차분하고 고요해서 좋아요🖤 조명도 은은하면서 따듯한 느낌이고, 업무 및 독서를 하면서 집중하기에도 참 좋네요! 나중에 또 방문하겠습니다~ :)', 59, 18, 'GOOD', SYSTIMESTAMP);
