INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '검색해서 후기가 좋길래 와봤어요! 후기처럼 분위기도 좋고 넓어서 여유롭게 책도 읽고 작업하기도 좋네요! 주말에는 사람이 많을거 같아서 평일에 오면 더 좋을거 같네요! 라떼도 맛있어요 👍🏻', 2, 2, 'GOOD', SYSTIMESTAMP);
