INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '독서를 시작한 친구와 같이 온 렉터스! 독서하는 사람들, 함께 프로젝트를 진행하는 듯한 사람들, 혼자 무언가에 집중하는 사람들이 모인 곳이라고 생각 듭니다. 커피도 맛있구요. 친구와 책 읽으며 조용함을 즐긴 시간도 잠깐 수다떠는 시간들도 다 즐거워 지는 곳입니다.', 44, 0, 'GOOD', SYSTIMESTAMP);
