INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '혼자 카페 이용하려고 홍대 근처에서 찾다가 방문했습니다! 콘센트도 잘 되어있고 혼자 카페 방문하기 좋은 카페인거같아요 다음에 또 올게요~', 25, 2, 'GOOD', SYSTIMESTAMP);
