INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '잠봉뵈르가 일단 진짜 너무 맛있어요!! 잡곡 올리브 둘다 너무 맛있네요! 커피도 고소하고 다크다크하고 시그니처 음료들도 다 각자 개성있고 맛있어요~ 내부 화장실도 깔끔하고 관리가 잘 되어있어서 이용하기 편하고 카페도 넓고 쾌적합니다 노트북 이용도 할수있게 테이블마다 콘센트가 배치되어 있어 편하게 일하다가 갈수 있어서 좋아요!! 벌써 세번째 방문입니다!', 63, 12, 'GOOD', SYSTIMESTAMP);
