INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '홍대에 이런 곳이 있는 줄 몰랐어요…! 음악도 가사 없는 편안한 음악들만 나오고, 공간도 되게 다양하고 감각적이에요. 제가 오늘 앉은 자리에는 옆에 너무 예쁜 그림이 있어서 기분 좋게 글 쓸 수 있었네요! 오늘 제가 마신 음료 ‘당신의 영감’도 정말 맛있었어요! 당도 조절도 가능하고 카카오 향도 진하네요 ㅎㅎ', 116, 22, 'GOOD', SYSTIMESTAMP);
