INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '올 때마다 너무 좋아서 벌써 세번째 방문이에요! 홍대올 일 있으면 카페는 꼭 렉터스라운지로 와요 커피도 맛있고 빵도 맛있습니당 #서울북카페 #홍대카페 #작업하기 좋은 카페 #책 읽기 좋은 카페 #노트북하기 좋은 카페', 70, 14, 'GOOD', SYSTIMESTAMP);
