INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '오늘하루 향이이끄는대로 행동했다. 좋은사람의 향, 좋은장소의 향 향으로 다른사람을 이끄는 사람이되고싶다. 렉터스라운지. 이끌림.', 22, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '분위기가 너무 좋고 올 때마다 쾌적해서 너무 좋아요! 직원분도 친절하시고 화장실도 깨끗합니다 조용하고 좋은 음악이 나와요 테이블마다 콘센트가 있어서 작업하기 좋고 다양한 책이 있어서 힐링하고 갑니다.. 🙂‍↕️ #서울북카페 #작업하기좋은카페', 39, 3, 'GOOD', SYSTIMESTAMP);
