INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '카페가 생각보다 엄청 커요 ㄷㄷㄷ 리뷰보고 왔는데 분위기 미쳤네요 ㅜㅠ 평일 오후인데도 실내는 애매한 자리만 남아 있어서 밖에 앉았는데 완전 힐링됩니다 ㅜㅜ 무엇보다 음료맛이 진짜 미쳤어요 또와야지 ㅜㅜ', 51, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '직원분들도 친절하시고 커피도 맛있어요:) 분위기가 좋아서 친구랑 와도 편하고, 잔잔한 느낌이라 혼자 작업하러 오기에도 참 괜찮을 것 같아요', 47, 5, 'GOOD', SYSTIMESTAMP);
