INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '저만 알던 공간에 이제 사람이 넘치는군요. 정말 집중하기 좋습니다. 여기서만 매일 100문제 넘게 풀고 갈 수 있습니다. 이제 여기 아니면 갈 곳이 없습니다. 많이들 이용하세요.', 88, 12, 'GOOD', SYSTIMESTAMP);
