INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '근처에 약속이 있었어서 끝낸 후에 급한 과제를 쳐낼 카페를 찾느라 ''홍대 카공 카페'' 로 검색을 하다가 발견한 곳입니다. 음료 하나 시켜두고 별 기대 안 하고 급하게 왔었는데 카페 내부 분위기도 너무 좋고 직원분들도 친절하셨어요. 차분하게 집중할 수 있는 공간이라서 과제나 작업할 게 있는 분들께 추천드려요.', 1, 7, 'GOOD', SYSTIMESTAMP);
