INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '카페가 조용하고 분위기가 좋아요! 친구랑 처음 와보는데 음료도 맛있고 무엇보다 분위기가 진짜 좋아요~~ 다음에 또 오고 싶은 정도예요!! 자주 이용할 것 같아요!', 52, 15, 'GOOD', SYSTIMESTAMP);
