INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '사색하거나 글쓰기 좋아요. 잔잔한 음악이 흘러나오면서 음료마시면 집중 잘되고 책읽기도 좋아요. 혼자서 와도 좋고 여럿이 와도 좋아요. 무엇보다 늦게 퇴근하고나서도 자정까지 운영하니까 그때까지 책읽을 수 있어서 좋네요~ 앞으로 자주 올 예정이예요.', 42, 9, 'GOOD', SYSTIMESTAMP);
