INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '친구와 약속 가기 전 잠시 들렀는데요, 카페 외부부터 너무 예쁘더라고요. 커피 이름이 긍정과 활력이라 주문해봤는데, 너무 부드럽고 맛있었어요. 달기 조정이 되니까 입맛에 맞게 주문할 수 있네요', 89, 18, 'GOOD', SYSTIMESTAMP);
