INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '치아바타 잠봉뵈르가 특히 맛있어요!! 홍대에서 가장 카공하기 좋은 카페가 아닐까싶습니자 ㅎㅎ 노래도 조용하고, 쾌적해서 집중이 잘 돼요!!! 또 이용할 것 같습니다:) #서울북카페 #홍대카페 #작업하기 좋은 카페 #책 읽기 좋은 카페 #노트북하기 좋은 카페', 22, 7, 'GOOD', SYSTIMESTAMP);
