INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '홍대에서 집중하기 좋고,개인작업하기 좋은 카페를 찾긴 쉽지 않아서 이 카페를 찾은 게 참 반갑다. 북카페라는 타이틀에 걸맞는 공간과 분위기를 제공한다. 앞으로 재택근무나 독서가 카페방문 목적이라면 이 카페를 선택 할 것 같다. 참고로 잠봉뵈르 치아바타랑 롱블랙도 괜찮다.', 64, 11, 'GOOD', SYSTIMESTAMP);
