INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '작업하기 좋은 카페 시험기간에 왜 몰랐지 커피도 맛있고 책이 많아서 좋아요 집근처에 있어서 너무 좋습니다 집중도 잘되고 인테리어도 느좋..❤️‍🔥🍀', 35, 7, 'GOOD', SYSTIMESTAMP);
