INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '분위기 너무 좋네요 다음에도 공부하러 오려구요 사장님도 너무 친절하시고 ㅎㅎ 노래도 굉장히 집중이 잘되더라구요. 창가에 앉고 싶었는데 아쉽긴 하더라구요 저는 층올라갈때 있던 쇼파에 앉았는데 ㅋㅋ 거긴 진찌 그냥 독립공간 같아서 좋았습니다 다음에 오면 무조건 창가에 앉을거에요 ㅎㅎ', 42, 9, 'GOOD', SYSTIMESTAMP);
