INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '작업 공간이 필요해서 처음 방문해보았는데 분위기가 너무 좋아서 깜짝 놀랐어요! 이 카페 특유의 잔잔한 분위기가 작업 효율을 올려준달까요,, 다들 방문해보세요', 90, 15, 'GOOD', SYSTIMESTAMP);
