INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '음료가 맛있고 넓고 콘센트가 많아서 카공하기에도 너무 좋은 홍대 대형카페! 홍대 중심에서 살짝 벗어난 조용한 골목 안에 자리한 이 디저트 카페 안은 햇살이 잘 드는 통창 덕분에 분위기가 환하고, 좌석 간 간격도 널찍해서 답답하지 않아요! 무엇보다도 각 자리마다 콘센트가 마련되어 있어 노트북 작업이나 아이패드 필기에도 완벽하게 적합한 곳이여서 너무 좋았어요!', 107, 23, 'GOOD', SYSTIMESTAMP);
