INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '전에는 사람 별로 없었는데 오늘은 진짜 너무 많아서 못 앉을 뻔 했어요 ㄷㄷ!! 여기 분위기 홍대에서 최강이고 흘러나오는 음악또한 재즈라 분위기있게 카공하기 좋은 것 같아요. 넓고 쾌적해서 좋아요:)', 7, 1, 'GOOD', SYSTIMESTAMP);
