INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '구옥 리모델링 카페입니다. 다들 작업, 공부하는 분위기라서 집중하기 좋아요. 자리 아주 많아서, 토요일피크시간만 아니면 헛걸름할일은 없는것같아요 추천합니다. 저도 자주 가려구요', 94, 26, 'GOOD', SYSTIMESTAMP);
