INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '이번달에 처음 와 본 후 반해서 요즘 일주일에 한 두번씩 오는 것 같네요~ 분위기가 너무 좋아요. 실내는 감성 촉촉해지는 곳이라 진짜 영감 솟는 곳이에요. 집중하기 좋은 분위기와 음악도 재즈가 흘러서 편안해요. 책도 꽤 많은 편이에요. 경제 자기계발서 등 ㅎㅎ 이런 카페가 생긴 걸 이제야 알았네요. #서울북카페#홍대카페#작업하기좋은카페#책읽기좋은카페', 36, 6, 'GOOD', SYSTIMESTAMP);
