INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '저번주에 왔는데 이번주에도 또왔습니다… 주변 지인 모두에게 영업하는 중ㅋㅋㅋ ㅡㅠ 너무 좋아요 특히 요즘 날씨가 좋아서 더 자주오게되네요', 128, 24, 'GOOD', SYSTIMESTAMP);
