INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '카페 분위기도 좋고, 독서모임 하러 왔는데 매장이 넓고 단체석도 준비되어 있어서 좋았습니다. 커피두 맛있네요 항상 애용하고 있습니다👍👍', 16, 8, 'GOOD', SYSTIMESTAMP);
