INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '내부 공간 곳곳에 자리가 있어서 원하는 자리 골라앉기 좋아요. 정원 보이는 자리 폴딩 도어 오픈되어 있고, 정원에도 자리가 있어서 날 좋을때  오기 딱이에요. 노트북 하기 좋아요. #서울북카페 #홍대카페 #작업 하기 좋은 카페 #책 읽기 좋은 카페 #노트북하기 좋은 카페', 9, 3, 'GOOD', SYSTIMESTAMP);
