INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '햇빛 단풍 바람 새 지저귀는 소리와 함께 잔잔한 음악 즐기면서 휴식을 취하기 좋아요 노트북 작업하기도 편하고 책 보기도 좋고요 공간이 엄청 넓어요', 16, 3, 'GOOD', SYSTIMESTAMP);
