INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '차분한 분위기에서 분위기 있는 매장 음악을 들으면서 하던 업무를 마무리 할 수 있었습니다. 음악이 시끄럽지 않고 템포도 빠르지 않아서 이야기하거나 업무할때 방해받지 않아요 커피도 맛있었고 시그니쳐 메뉴도 맛있어요. 평소 단골카페 없이 그냥 길가다 나오는 조용한 카페 좋아하는데 다음에 또 방문하고 싶어지는 곳 입니다', 58, 15, 'GOOD', SYSTIMESTAMP);
