INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '학교 근처라 왔어요! 분위기 너무 좋고 음악도 어울리네요 컴퓨터 작업하기 좋아요 ㅎ  공간이 전부 감각적이고 책들도 스테디 인것들로 책읽기도 좋더라구영 근처에 시간 비면 자주 올 것 같아요:)', 47, 8, 'GOOD', SYSTIMESTAMP);
