INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '야외석 좀 보세요… 분위기 미쳤죠 ㅠㅠㅠㅠ 책 잘 읽고 가요!! 책을 안가져와도 책이 준비되어 있으니까 그냥 와도 되요!! 커피도 쓴맛 적어서 맛있구 치아바타 잠봉샌드위치도 맛있어요!! 따뜻할때가 더 맛있으니 방문시 다들 참고하셔요 ㅎㅎㅎ', 22, 6, 'GOOD', SYSTIMESTAMP);
