INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '카공하기 좋은 카페 검색해서 왔는데, 요즘 카페에서 공부하는게 눈치 보이는데 여기는 주로 오시는 분들이 모두 공부 아니면 독서나 비지니스모임 같은 걸 하고 계신 것 같아서 눈치 없이 카공 하기 너무 좋았어요!!! 평소에 카페 갈 때 전기도둑이 되기 싫어 노트북 풀충전 하고 다니는데, 여기는 아예 충전하기 편하도록 멀티선이 되게 많았어요!😍 자리공간도 넓고 분위기도 깔끔하고 너무 좋아서 공부나 모임이나 데이트 하시기 넘 좋은 카페로 추천합니다!! 무엇보다 커피가 저렴하고 맛있어요🫶', 49, 5, 'GOOD', SYSTIMESTAMP);
