INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '카페 분위기가 너무 좋아요! 선곡도 좋구🩷 그리구 잠봉뵈르 치아바타가 진짜.... 진짜 너무 맛있어요 ㅜㅜㅜㅜ 치즈케이크도 맛있습니당 #서울북카페 #홍대카페 #작업하기좋은카페', 67, 18, 'GOOD', SYSTIMESTAMP);
