INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '장소가 아늑하고 공부하기에 좋아요! 분위기가 따뜻해요. 잠봉뵈르가 바삭하고 맛있어요 ㅎㅎ 야외도 잘 보이고 날씨 따뜻할 때 밖에서 잠봉뵈르 먹으면 좋을 거 같아요! #서울북카페 #홍대카페 #작업하기좋은카페 #책읽기좋은카페 #노트북하기좋은카페', 13, 0, 'GOOD', SYSTIMESTAMP);
