INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '잠봉뵈르 치아바타가 진짜 맛있고 공간이 하나하나 너무 이뻐요! 카공하기 너무 좋은 카페같아요~! #서울북카페 #홍대카페 #작업하기 좋은 카페 #책 읽기 좋은 카페 #노트북하기 좋은 카페', 22, 2, 'GOOD', SYSTIMESTAMP);
