INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '홍대 근처에서 여기만큼 조용하고 집중하기 좋은 카페가 없어요 ㅎㅎㅎ 노트북 하기 좋은 카페라고 해서 갔는데 비트감 강한 음악 틀어놓는 곳도 종종 있는데 여긴 진짜 인테리어, 음악 모든 것이 집중하기 딱 좋은 공간! 편하게 노트북 할 수 있어서 완전 좋아요,,,,💛 아,, 커피도 진짜 훌륭합니다!!!! 완전 부드러움..', 1, 3, 'GOOD', SYSTIMESTAMP);
