INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '홍대라서 이렇게 조용한 카페 보기 힘든데 너무 좋네요. 음악도 잔잔하고 사람들도 작업하러 오시는 분들이라서 서로 배려하고 집중해서 시간 보낼 수 있습니다. 꾸준히 이용중입니다.', 47, 6, 'GOOD', SYSTIMESTAMP);
