INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '공간이 넓고, 콘센트와 조명도 많아서 작업하기 좋아요! 분위기도 많이 시끄럽지 않고 조용한 분위기입니다. 야외좌석도 있어서 날 좋은 날에는 밖에서 마셔도 좋을 것 같아요!', 16, 0, 'GOOD', SYSTIMESTAMP);
