INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '주택같은공간인데 안은 미드센츄리스타일 조명과 데이블로 2층까지 있고 야외 정원공간에 캠핑의자로 다양하게 구성되어있어요 주문은 지하에서 받아 공간이 분리되서 커피마시는공간은 조용해요', 50, 5, 'GOOD', SYSTIMESTAMP);
