INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '카페가 엄청 넓고 좋아요 1인석 2인석 4인석 다양하게 있고 분위기가 다양해요! 책읽기도 좋고 노트북하기도 좋아요 야외 분위기도 너무 이쁘고 좋네요 추천!!', 4, 6, 'GOOD', SYSTIMESTAMP);
