INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '홍대 근처에서 여기만큼 조용하고 집중하기 좋은 카페가 없습니다!!! 노트북 하기 좋은 카페라고 해서왔어요 여긴 진짜 인테리어, 음악 모든 것 이 집중하기 딱 좋은 공간! 편하게 노트북 할 수 있어서 완전 좋숩니다', 80, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '공간이 주는 아늑함이 느껴진다 조용하지만 숨이 막히는 기분은 아니다. 그렇다고 말을 안해야 되는 느낌도 아니고 적당하다. 사장님 또한 커피에 대한 관심이 많이 느껴진다. 전에 일하던 곳 점장님이 생각날 정도로 커피에 진심인게 느껴진다. 커피 또한 좋은 원두라는것이 느껴지고 사장님이 굉장히 친절하다는 것이 느껴진다. 비가 오는 날 와서 야외를 사용 못했지만 나중에 한 번더 와보고 싶다.', 11, 4, 'GOOD', SYSTIMESTAMP);
