INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '홍대 넓은 카페 찾다가 왔는데 분위기 독특하고 좋아요 공부하는 분들이 많지만 구역마다 분위기 달라서 담소 나누기에도 부담 없어서 좋네요 당분간 홍대 자주 와야하는데 또 올 거 같아요~', 21, 1, 'GOOD', SYSTIMESTAMP);
