INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '여기처음와보는데..단골될거같아용.. 뷰랑 분위기랑 ,,,청결함,,기타 등등 부족한게 하나도 없네용 주변사람 전부 데려오고싶은 곳입니당💛💛', 96, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '집중이 잘 되는 카페는 오랜만이라 너무 기분이 좋아요! 차분한 음악이랑 집중하게 만드는 조명이 있어서 집중을 못하는 편인데도 오래 집중할 수 있어서 좋았습니다 다음에는 친구랑 와서 같이 공부하고 싶어요🫶🏻 긍정과 활기라는 돌체라떼 먹었는데 추천드립니다 맛있어요 🤤', 74, 16, 'GOOD', SYSTIMESTAMP);
