INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '유동 인구가 많아 시끄럽고 정신 없는 홍대에서 조용한 카페를 찾을 수 있어 정말 좋았습니다🫶🏻 차분하고 편안한 분위기로, 자주 오고 싶다는 생각이 드네요!', 41, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '치아바타 잡봉뵈르 맛있게 먹었어요~ 작업하는 분이라면 도심 속 여유도 느끼면서 새로운 자극도 받을 수 있을듯.. 구비된 책도 잘 읽고 갈께요~', 31, 0, 'GOOD', SYSTIMESTAMP);
