INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '카공하고 싶어서 홍대입구 근처에 있는 렉터스라운지 방문하게 됐는데 리뷰에 있는대로 매장 완전 청결하고 좌석도 많아서 공부하기도 좋습니다!', 73, 14, 'GOOD', SYSTIMESTAMP);
