INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '야외 자리랑 테라스 너무 좋고 책도 있어서 힐링하기 좋아요..🫶🏻 음료도 맛있고 분위기 미쳤네여 작업하시는 분들도 많아서 카공하기도 좋을듯합니당~!!', 1, 6, 'GOOD', SYSTIMESTAMP);
