INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '레몬블랙티 맛있어요~!😊 야외 테라스가 있고 분위기가 너무 좋은 곳입니다. 1층에서는 개인작품 전시도 하고 볼거리도 있고 감각적인 곳이에요 ㅎㅎ', 10, 6, 'GOOD', SYSTIMESTAMP);
