INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '카공하기 너무 좋아서 자주와요! 분위기도 좋고 커피 맛도 좋습니다. 노트북 작업하기에도 좋은 공간이에요. 가끔 만석일 때도 있숩니다', 23, 0, 'GOOD', SYSTIMESTAMP);
