INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '친구가 추천하여 함께 카공을 위해 방문했는데 확실히 작업을 위해 만들어진 카페인 만큼 분위기가 너무 좋았습니다! 커피도 맛있었어요~', 64, 11, 'GOOD', SYSTIMESTAMP);
