INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '처음 방문해서 아메리카노하고 베이글 시켰는데 베이글 너무 맛있어서 다음에 또 먹을거 같아요 🥹🥹 채광없는 공간하고 채광 잘드는 공간이 나뉘어져 있어서 원하는 공간에서 작업할 수 있다는 점이 너무 만족스러웠습니다!! 자주 올 것 같아요🍀🫧', 12, 10, 'GOOD', SYSTIMESTAMP);
