INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '비오는 날 조용하게 들릴 카페를 찾다 방문하게 됐습니다. 뷰도 좋고 분위기가 차분해서 작업하기 너무 좋아보여요. 롱블랙 진하고 좋네요! 터를 잡고 싶을 만큼 만족스럽습니다. 또 방문할게요. #서울북카페 #홍대카페 #작업하기 좋은카페', 14, 4, 'GOOD', SYSTIMESTAMP);
