INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '와ㅏㅏㅏㅏ 분위기가 까맣고 고졀스 해요. 음료는 진하고 깊은 풍미가 느껴지고, 앤틱한 분위기의 식기가 어우러져요. 음악도 아름답고 동료 세 분과 즐거운 시간 보냈습니다!!!', 26, 1, 'GOOD', SYSTIMESTAMP);
