INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '카페 분위기가 진짜 좋아용... 안에 큰 나무 테이블 있는 곳에서 공부했는데 노트북으로 작업하기도 좋구 집중하기에도 좋았어여! 글구 잠봉뵈르가 진짜 맛있어요', 12, 9, 'GOOD', SYSTIMESTAMP);
