INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '건축을 배우시는분들은 렉터스의 명성을 익히 들어보셨을겁니다. 창작자들의 장비는 여타 일반카페에 있는 테이블에서는 작업하기 어렵다고 보여집니다. 하지만 이곳은 넓은 테이블, 내부공간의 분위기 그리고 필수요소라고 할 수있는 넉넉한 콘센트까지, 작업자들에게는 최고의 공간이라고 할 수 있겠습니다', 26, 9, 'GOOD', SYSTIMESTAMP);
