INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '홍대에 일정있어서 왔는데, 분위기도 너무 좋아요. 일단 넓어서 좋고, 커피도 좋고 일하기도 좋아요.! 요 동네오면 또 들릴꺼같아요.', 403, 92, 'GOOD', SYSTIMESTAMP);
