INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '카공하기 너무 좋은거같아요! 자리도 되게 다양하게 많고 공부에 집중하기 좋은 느낌의 좌석이라 스터디카페 같아요 음료도 맛이씁니당', 29, 1, 'GOOD', SYSTIMESTAMP);
