INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '친구가 추천해서 따라왔는데 카공하기 너무 좋아요! 조용하고 책상이랑 의자도 너무 편하고 아바라,치즈케이크 다 맛있어요! 화장실도 짱 넓고 깨끗하고 예뻐서 깜짝 놀랐어요! 다음에 또 올게요~', 19, 4, 'GOOD', SYSTIMESTAMP);
