INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '정말 좋은 카페입니다. 음료가 맛있어요. 원래 커피를 잘 남기는데 다 먹어버렸습니다. 무엇보다 화장실이 넓어서 좋네요. 문 열자마자 너무 넓은 화장실에 깜짝 놀랐습니다. 공부하기 진짜 좋은 카페에요!!!', 32, 9, 'GOOD', SYSTIMESTAMP);
