INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '어제 방문하고 바로 또 오늘 방문합니다! 3개의 층까지 좌석도 다양하고 인테리어랑 정원까지 너무 분위기가 좋습니다. 맛있는 커피랑 분위기있게 즐기기 너무 좋아요!', 10, 2, 'GOOD', SYSTIMESTAMP);
