INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '중요한 시험을 앞두고 공부데이트를 위해 방문했어요...! 카페 분위기부터 스터디하는 분들과 개인작업하는 분들이 많다보니 아주 차분하고 조용했구요, 사진은 못찍었지만 1인 좌석들도 여럿있었습니다ㅎㅎ 가격대가 다소 있는만큼 넉넉히 편히 머무르다 갈 수 있었어요🌝👍🏻 이미 아아는 타카페에서 마시고 와서 카페모카와 시그니쳐 음료를 먹었는데, 감성적 문구랑 이름때문에 더 특별하게 먹을 수 있었던 것 같아요ㅎㅎㅎ 내부에 진열된 책들도 무척 다양하고 읽을만한 책들이 많아서 담번엔 책읽으러도 와보려구요!!! 참고로 저희 커플은 주말(일욜) 낮에 방문했는데 거의 만석이었습니다ㅋㅋㅋㅋ 다들 넘나부지런한것....', 6, 8, 'GOOD', SYSTIMESTAMP);
