INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '#서울북카페 #홍대카페 #작업하기 좋은 카페 #책 읽기 좋은 카페 #노트북하기 좋은 카페 인테리어 넘 좋구 공간 넓어서 작업하기 짱 조아요 홍대에 이런 곳이 있다니', 38, 7, 'GOOD', SYSTIMESTAMP);
