INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '분위기 좋고 업무에 집중하기 좋아서 왔어요! 1층에서 전시회도 열리고 있어서 카페온김에 구경하기도 좋았습니다. 너무 조용해서 친구랑 아예 얘기못하면 어쩌나 걱정했는데 소소하게 얘기나눠도 괜찮은 분위기입니다☺️ 다음에 또 올게요!', 29, 0, 'GOOD', SYSTIMESTAMP);
