INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '혼자 갔는데 차분하고 조용한 분위기라 할 일하거나 다이어리 쓰기 좋았어요. 수다떠시는 분들도 있고 테이블이 많은데도 인기가 많아 못앉으시는 분들도 꽤 있었어요. 조용히 대화 혹은 작업할 카페 찾으시는 분들에게 추천합니다. 라떼도 맛있었어요!', 20, 6, 'GOOD', SYSTIMESTAMP);
