INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '홍대에 이런 곳이 있다니 정말 멋져요. 개인 일 하기에도, 친구를 만나기에도, 책 읽기에도 다 너무 좋습니다 보물 같은 곳 운영해주셔서 감사해요 또 올게요!!', 9, 10, 'GOOD', SYSTIMESTAMP);
