INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '저번에 처음 방문하고 이번이 두 번째 방문이에요. 사람이 많은데도 시끄럽지 않고, 다들 자기 할 일을 열심히 하는 느낌이라 분위기도 좋아요. 거기다 커피도 케이크도 맛있네요! 추천!', 64, 14, 'GOOD', SYSTIMESTAMP);
