INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '#작업하기 좋은 카페 시험 준비 중에 너무 좋은 장소를 찾았어요. 입구부터 작업하는 사람들을 환영하더라고요. 눈치 보지 않고 집중할 수 있었어요. 커피도 맛있고요. 층마다 다른 분위기와 콘센트와 조명도 참 좋았고요. 무엇보다 영업시간이 참 좋네요!', 4, 9, 'GOOD', SYSTIMESTAMP);
