INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '카페에서 작업할 때 주변소음 및 히트곡 메들리로 노캔을 끼는데, 여기는 다들 조용하고 집중하시고 카페 노래도 집중잘되는 음악으로 틀어주셔서서 노캔없이 보냈네요 ㅎㅎ 자주 들릴게용', 10, 6, 'GOOD', SYSTIMESTAMP);
