INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '북카페 검색해서 산책 겸 찾아왔는데 너무 힐링했네요🤍 마당에 피어있는 목련까지 너무 완벽했습니다🌸 독서에 집중할 수 있고 일상 속 영감을 받을 수 있는 훌륭한 장소입니다🌱힐링이 필요하시다면 꼭 방문해보세요🙃', 33, 8, 'GOOD', SYSTIMESTAMP);
