INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '홍대에 이런 카페가 있는지 처음 알았네요 !! 작업+카공에 진짜 너무 최적화 된 카페에요 홍대카공은 무조건 여기입니다 🙄 매장도 되게 신기하고 분위기도 짱이에영', 109, 26, 'GOOD', SYSTIMESTAMP);
