INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '학교 과제 때문에 방문했는데 조용하고 노래도 잔잔하고 과제나 작업하기 딱 좋은 것 같아요 지하 1층과 1층으로 나뉘어있는데 넓고 쾌적합니다 화장실도 엄청 넓고 깨끗해서 자주 올 거 같아요!!', 19, 2, 'GOOD', SYSTIMESTAMP);
