INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '#서울북카페 #홍대카페 #작업하기좋은카페 #책읽기좋은카페 #노트북하기좋은카페 혼자 두번째 방문이에요 매장도 3층으로 넓고 노트북 이용하기에도 엄청 편해요 3층에는 모니터도 사용 가능해서 편하게 이용하면 좋을거같아요! 노래소리도 방해되지않고 적당해요', 39, 4, 'GOOD', SYSTIMESTAMP);
