INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '조용하고 분위기 좋은 공간에서 작업하기 딱 좋은 북카페였어요. 음료랑 디저트도 맛있고 테라스 자리까지 있어서 다음에도 꼭 다시 방문하고 싶어요! 홍대 조용한 카페 추천합니다 :)', 40, 3, 'GOOD', SYSTIMESTAMP);
