INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '홍대 근처 북카페를 검색해서 한번 오고 싶은 곳이었는데 와보니 기대이상으로 너무 좋아요. 밤12시 있을 수 있고 분위기나 놓여있는 책도 기대이상입니다. 매일 저녁 출근하고 싶단 생각이 들정도로. 음료도 맛있습니다. 늦게까지 여는 북카페 찾는 분들께 강추해요.', 7, 10, 'GOOD', SYSTIMESTAMP);
