INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '근처에 일정이 있어서 남는 시간에 책이나 볼까 하고 들렸는데 정말 맘에드는 카페를 찾아서 좋아요ෆ 분위기도 좋고 공간도 여러곳이라 작업하기에도 책 읽기에도 좋고 친구와 함께 와도 좋을 거 같습니다!', 15, 1, 'GOOD', SYSTIMESTAMP);
