INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '근처에 왔다가 작업하기에 좋은 것 같아서 와봤는데, 공간도 음악도 모두 마음에 들어요. 잔잔하게 깔리는 음악도, 편의를 위해 제공되는 여러 용품들(멀티탭, 담요 등)도, 그리고 무엇보다 맛있는 커피와 술이 마음에 듭니다. 롱블랙, 순리대로(칵테일), 비스코티 비건쿠키 셋다 맛있고, 기본으로 주신 과자도 맛있어요! 자주 올 것 같아요. 이런 공간이 있는 것만으로도 참 감사합니다ㅎㅎ', 2, 4, 'GOOD', SYSTIMESTAMP);
