INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '홍대에 이런 카페가 있을 줄 몰랐는데 공부랑 작업하기에 너무 좋아요!̆̈ 1,2층은 데이트하기 좋고 3층은 작업하기에 딱인 것 같습니다. 자주 올게요!̆̈', 38, 7, 'GOOD', SYSTIMESTAMP);
