INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '남친이랑 갈만한 북카페를 찾던 중 여기가 생각내서 다시 와봤어요. 책장에 책도 부담없이 꺼내읽기 좋고 작업하기 좋고. 다른 카페보다 어수선하지 않아서 이용하기 좋았어요. 덕분에 책 한 권 완독!', 6, 8, 'GOOD', SYSTIMESTAMP);
