INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '꼭 와보고 싶었던 렉터스라운지 드디어 와보네요 ㅎㅎㅎ 평일 오후에도 사람이 꽤 있었는데 자리 있어서 대기는 없었습니다. 긍정과 활기 먹고 기운 내서 할일 했어요^-T 맛잇어용 추천추천', 30, 2, 'GOOD', SYSTIMESTAMP);
