INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '정신없는 홍대에서 카공하고 싶어서 찾아보고 왔는데 생각보다 느좋 카페여서 만족하고 갑니다! 공간도 생각보다 많이 넓고 콘센트도 좌석마다 있어서 노트북 작업하기도 좋습니다. #서울북카페 #홍대카페 #작업하기좋은카페 #책읽기좋은카페 #노트북하기좋은카페', 56, 18, 'GOOD', SYSTIMESTAMP);
