INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '🫶작업하기도 좋고, 책 읽기도 좋고, 노트북 하기도 좋은 홍대카페. 베이글도 맛있고, 커피도 맛있는 서울 북 카페 렉터스라운지!🫶 아주아주 만족스러운 카페였어요!!', 5, 7, 'GOOD', SYSTIMESTAMP);
