INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '조용하고 분위기 좋은 공간에서 여유롭게 커피 한 잔 즐기기 딱 좋은 곳. 커피 맛도 깔끔하고 인테리어도 너무 고급스럽게  되어 있어 만족스러웠어요.', 6, 3, 'GOOD', SYSTIMESTAMP);
