INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '며칠전에 친구랑 늦은밤에 방문했었는데, 너무 좋았던 기억에 오늘은 낮에 어머니와 방문했습니다! 마침 날씨도 좋아서 새소리도 들리고 바람도 선선하게 불어서 좋은 시간 보냈습니다✨', 0, 4, NULL, SYSTIMESTAMP);
