INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '유튜브에서 보고 왔는데 상상 이상 좋았어요 콘센트도 많고 좌석도 많아서 카공하기 진짜 좋아요!! 한번씩 꼭 들러보시길 바랍니다..🫶🏻 #작업하기 좋은 카페 #노트북하기 좋은 카페 #책 읽기 좋은 카페', 5, 10, 'GOOD', SYSTIMESTAMP);
