INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '시험기간에 공부하려고 찾다가 왔는데 홍대에서 카공하기 좋은 카페 1티언거같아요 2층은 작업공간처럼 집중 할 수 있게 돼있고 1층과 야외에는 쉬러온 분들을 위한 자리도 엄청 많아요 자주올거같습니다리...ㅎㅎ #홍대카페 #카공하기좋은카페', 14, 9, 'GOOD', SYSTIMESTAMP);
