INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '예술가의 공유오피스 같으면서도 여유와 감성을 놓치지 않은 블랙톤의 조용하고, 깔끔한 카페! :-) 작업하기엔 너무 시끄러운 홍대에서 열심히 찾아 온 보람이 있네요! 다음에 또 작업하러, 데이트하러 올 것 같아요! 🖤 Pick point ✔️합리적인 가격대의 디저트 ✔️ 1층은 작업 및 데이트, 2층은 작업공간으로 추천 ✔️ 데이트코스로 B1 갤러리 구경 > 1층 소파자리에서 오붓한 데이트 추천! ✔️ 혼자 작업, 노트북, 책 읽기 좋은 카페로 추천!', 30, 1, 'GOOD', SYSTIMESTAMP);
