INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '노트북 할 만한 곳을 검색하다 방문했는데 음악도 가사가 없으니 집중하기도 좋고 인테리어도 차분해서 느낌이 좋네요. 긍정과 활기는 돌체라떼인데 맛이 진하고 부드럽습니다. #작업하기좋은카페 #노트북하기좋은카페 #책읽기좋은카페', 61, 12, 'GOOD', SYSTIMESTAMP);
