INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '두번째 방문입니다. 상수에 들린김에 홍대쪽까지 이동해서 다시 왔어요. 컨셉도 독특하고 편안한 느낌의 카페입니다. 다음에 홍대 근처에 올일 있으면 다시 들를 예정입니다.', 102, 23, 'GOOD', SYSTIMESTAMP);
