INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '음료 맛있고 음악 차분하고 조용해요! 카공하기에 딱입니다,,, 너무 조용해서 부담스럽거나 그렇지 않고 적당해서 또 방문하고 싶은 공간입니다! 홍대 카공 카페로 짱짱추천,,', 26, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '홍대에 이런 곳이 있는지 처음알게 되었어요. 전시장도 운영하면서 카페도 있는 곳이라니..내부는 증말 책읽거나 작업하다가기 너무 좋은 환경이에요. 모니터도 있어서 깜놀했네요. 공간도 엄청 넓은데 활용성도 높고 그렇다고 커피나 음료, 디저트 맛이 없는 것도 아니어서 왜 사람이 많은지 알게됐네요. 나중에 혼자와서 작업할거리 조용히 하다 가봐야겠어요!', 5, 6, 'GOOD', SYSTIMESTAMP);
