INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '분위기도 좋고 다들 공부하는 분위기라 작업하고 스터디하기 아주 좋은 카페에요 음료 맛도 좋고 여기저기 세심한 배려, 그리고 신간 책들도 가득해서 좋습니다 🤩😍', 309, 51, 'GOOD', SYSTIMESTAMP);
