INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '디카페인, 오트밀 옵션있고 커피맛은 평범해요~ 공간이 넓고 화장실도 깨끗해요! 예술과 관련된 다양한 책들이 많이있어서 읽을 수 있어서 좋아요: )', 60, 11, 'GOOD', SYSTIMESTAMP);
