INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '정말 예쁜 곳이에요!!! 앞으로도 자주 올 예정❤️ 수다는 정원을 추천합니당 하지만 거기도 넘 조음 멤버십도 있다던데 궁금해요‼️', 22, 8, 'GOOD', SYSTIMESTAMP);
