INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '2층에는 큰 공간과 작은 공간이 분리되어 있어요 작은공간을 이용하였는데, 집중하기 더 좋았어요 3층에는 큰 공간으로 이루어져 있어요 컴퓨터를 이용할 수 있는 공간도 있고, 프린트기기가 있네요! 커피 주문은 지하1층에서 할 수 있는데, 갤러리 공간도 있어요. 1층 입구로 들어와서 지하1층으로 가는 길을 못 찾아서 헤맸어요 ㅎㅎ 작은 공간에 숨겨진 계단이 있어요 너무 좋았습니다😁 #작업하기 좋은 카페 #노트북하기 좋은 카페 #책 읽기 좋은 카페', 11, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '매장 전체적인 분위기나 규모, 그리고 집중하기에도 너무 좋고 주문한 커피와 디저트까지 센치하고 너무 좋아서 삼첩밥상을 먹은느낌이에요!!', 49, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '치즈케이크 모야모야 너무 꾸덕하고 맛있쟈나~~ 라떼도 고소하고 아메리카노도 산미 적당하니 향이 진해요. 제가 홍대 오면 꼭 오는 카페! 작업하기 좋은 카페라서 와서 책도 읽고 시간 가는 줄 모르고 눈치 안보고 있어도 좋은 곳이랍니다. 노트북하기 좋은 카페니깐 와서 작업도 하고 책 읽기 좋은 카페에요~ 읽을 만한 책 많으니깐 책 없는데 시간 떼워야 할 때 강추!!', 44, 2, 'GOOD', SYSTIMESTAMP);
