INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '우연히 이쁜 카페에 홀린듯이 들어왔는데 분위기가 너무 예쁘고 편안한 이 공간이 쉬기에 너무 좋았어요! 시그니처 음료 중 2잔을 골라 주문했는데 긍정과 활기, 새로운 상상이라는 이름이 너무 독특하고 매력적으로 느껴졌어요! 맛도 물론 너무 맛있었고 치즈케이크도 담백하고 맛있어서 너무 좋았습니당!!! 편안하고 예쁜 이 공간에 잠시 머물렀다 가는 것이 너무 좋았고, 다음에 그림 작업하러 와도 너무 좋을 것 같았어요!! ☺️☺️', 11, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '완전 단골카페가 됐어요! 일단 인테리어와 구조가 너무 신기하고 좋습니다. 조명 하나하나 신경쓰신게 보이고, 나오는 가사 없는 음악도 반복 안되고 좋아요! 메뉴 이름 중 “긍정과 활기”가 있는데, 이름만큼 너무 맛있고 저에게 특별한 음료가 됐습니다. 잠봉뵈르도 진짜 맛있으니 꼭 들려보세요!🥹🥹😸', 35, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '근처에서 차분하게 이야기나눌 공간을 찾다가 와봤는데 마음에 드네요:) 작업하거나 공부하러 오시면 아주 좋을 것 같고, 적당히 얘기나누기도 좋아요. 공간이 다양해서 여러용도로 방문할 수 있겠네요. 음료이름이 특별해서 고르는 재미도 있는데, 맛도 잘 어울리고 좋아요. 선택할 수 있는 옵션도 많아서 여러 취향이 함께할 수 있을 것 같은 공간이네요 :))', 19, 6, 'GOOD', SYSTIMESTAMP);
