INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '홍대 조용하고 작업하기 좋은 카페 렉터스 라운지! 혼자 책을 읽거나 공부, 작업하기도 좋고, 편하게 회의하거나 모임하기도 좋은 곳이에요 편안하고 차분한 공간에서 혼자 힐링하는 시간 보내고 갑니다💕 라떼도 너무 맛있고, 비스코티도 고소해서 커피랑 잘 어울려요', 42, 4, 'GOOD', SYSTIMESTAMP);
