INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '매장도 넓고 공간도 하나하나 이뻐요! 카공하는 사람들도 있고 자유로운 분위기입니당 책도 많아서 놀다가 책읽고 쉬러 오기도 좋을것같아요~ 노래도 잔잔하니 좋아용', 4, 0, 'GOOD', SYSTIMESTAMP);
