INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '지나가면서 한 번쯤 와보고 싶었는데 친구 기다리면서 드디어 방문했어요:) 커피가 진해서 좋고 잠봉 샌드위치도 맛있어요! 후추가 완전 킥😋 책 읽고 조용히 대화하는 분위기라 아늑하고 좋아요 #작업하기 좋은 카페 #노트북하기 좋은 카페 #책 읽기 좋은 카페', 96, 25, 'GOOD', SYSTIMESTAMP);
