INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), 'N번째 방문입니다.. 언제나처럼 긍정과 활기라는 메뉴 너무 맛있고 분위기도 완벽합니다!! 친구랑 와서 수다떨기에도, 할일 하기에도 좋습니다 더 자주 올게요!!🤎', 44, 6, 'GOOD', SYSTIMESTAMP);
