INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '오고 싶은 곳으로 저장해놨다가 드디어 와봤는데 너무 좋아서 앞으로도 자주 올 것 같아요!! 무엇보다 분위기가 너무 좋고 조용해서 작업공간으로 추천해요 커피도 맛있어요💛💛 #작업하기 좋은 카페 #노트북하기 좋은 카페 #책 읽기 좋은 카페', 32, 9, 'GOOD', SYSTIMESTAMP);
