INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '조용하고 차분한 분위기의 카페예요~ 공부하러 온 사람들이 많고 공간 공간이 나뉘어져서 프라이빗 한 느낌이 있네용~ 알코올 음료도 있어요.😊', 81, 18, 'GOOD', SYSTIMESTAMP);
