INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '조용히 책 읽을 수 있는 카페를 찾다가 우연히 왔는데 너무 밝지도 어둡지도 않은 조명에 진짜 작업 하시는 분들만 있어서 소란스럽지 않고 책읽기 딱 좋은 카페인 것 같아요. 다음에 또 방문해서 여유있게 책 읽기 좋은 곳입니다🖤', 52, 16, 'GOOD', SYSTIMESTAMP);
