INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '카공하러 왔는데 자리도 많고 콘센트 넉넉하고 조용해서 집중하기 너무 좋았어요 친구들한테도 추천했는데 저도 자주 올것같아요! 치아바타 잠봉뵈르 맛도 좋습니다!', 113, 21, 'GOOD', SYSTIMESTAMP);
