INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '오늘 처음 와봤는데 분위기가 너무 좋아서 공유 오피스인줄 알았어요. 집중하기에 최고네요. 위에 올라가보니 작업자들끼리 모여서 작업도 가능하던데 다음에는 친구와 함께 오겠습니다!', 94, 20, 'GOOD', SYSTIMESTAMP);
