INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '<렉터스 라운지> 홍대에 이렇게 좋은 공간이 있는지 몰랐어요! 주택을 통으로 사용하고 있어서 넓은 크기에다가 작업하기 좋은 환경의 북카페입니다! 책읽기에도 작업하기에도 공간이 잘 구성되어 있어서 잘 있다 갑니다~ 초코케이크두 맛있고 긍정과 활기도 달달하니 집중할때 마시기 좋네용! 작업할거 있을 때 또 방문하겠습니다😊🧡', 50, 7, 'GOOD', SYSTIMESTAMP);
