INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '친구랑 공부하러 왔는데요, 인테리어도 잘되어 있고 분위기가 좋아 집중해서 공부할 수 있었습니다!! 음료는 긍정과 활기를 마셨는데 진하고 달달하니 정말 맛있습니다♡ 강력 추천해요👍 #작업하기 좋은 카페', 22, 3, 'GOOD', SYSTIMESTAMP);
