INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '집중할수있는 공간과 음악 그리고 인테리어가 너무 맘에 들어요! 존마다 분위기가 다른것도 좋고 책 읽기에도 딱 좋으서 무조건 또 올거에요!! #작업하기좋은카페 #노트북하기좋은카페 #책읽기좋은카페', 28, 2, 'GOOD', SYSTIMESTAMP);
