INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '친구랑 두번째 방문했어요! 일주일 전에 처음 방문했었는데 각자 할 일 하기에 너무 좋을 분위기라 친구는 노트북, 저는 책 갖고 굳이 또 방문했습니다~! 커피도 입맛에 맞고 좋았어요~~ 근데 오늘은 처음 방문 했을 때의 분위기와 다르게 좀 소란스러운 손님들이 많았던 것 같아서 일반 카페와 다를게 없는 분위기였어요,,~~ 그래서 쪼꼼 집중하기에 아쉬웠네요..🥹 그래도 카페 자체는 좋아서! 앞으로 자주 찾아올 것 같아요👍🏻', 76, 12, NULL, SYSTIMESTAMP);
