INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '홍대오면 맨날맨날 오는 카페입니다. 대학생 과제하기도 좋고 카페 내부가 굉장히 넓고 다양한 분위기의 탁자와 공간이 있어서 너무 좋아요. 일하고 공부하기 좋은 카페입니다.', 22, 6, 'GOOD', SYSTIMESTAMP);
