INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '친구랑 서류 작업 할 게 있어서 홍대에 콘센트가 있고 좌석이 넓고 영업시간이 빠듯하지 않은 카페를 이곳저곳 찾다가 렉터스를 봤어요 :) 분위기도 많이 시끄럽지 않고 작업하기에는 정말 좋았어요 야외 흡연실도 따로 있어서 쾌적하고 특히 예체능 창작러분들 오시기 좋을 것 같아요', 2, 1, 'GOOD', SYSTIMESTAMP);
