INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), 'B1층부터 2층까지 좌석도 정말 다양하고 영감을 받는 공간인 것 같아요!! 당신의 평안 먹었는데 찐한 코코아 맛 🤎 분위기와 감성에 사로잡혔어요 단골 찜 🧡 #책읽기좋은카페 #작업하기좋은카페 #노트북하기좋은카페', 35, 1, 'GOOD', SYSTIMESTAMP);
