INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '친구 추천으로 오게됐는데 과제하러 오기 딱 좋아요ㅠㅠ 매장도 넓구 좌석도 다양하게있어서 공부하다가 기분전환하러 오기도 좋을거같아용 ㅎㅎ', 54, 18, 'GOOD', SYSTIMESTAMP);
