INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '차분한 분위기로 공부와 작업하는데 집중이 잘되었고 랙터스라운지만의 카페라떼 긍정과 활기도 맛있어요 게다다 힙한감성으로 주변지인에게 추천해주고 싶은 카페입니다 #작업하기 좋은 카페 #노트북하기 좋은 카페 #책 읽기 좋은 카페', 73, 18, 'GOOD', SYSTIMESTAMP);
