INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '카공할 겸 점심 먹으러 들렸는데 잠봉뵈르도 너무 맛있고, 잔잔하게 공부하기 좋은 공간이에요!! 홍대에서 카공 스팟 찾기 쉽지 않은데, 대부분의 좌석에 콘센트도 있고, 분위기도 너무 좋아서 종종 올 것 같아요 ㅎㅎ 홍대에서 카공할 곳 찾으신다면 추천 💙', 76, 16, 'GOOD', SYSTIMESTAMP);
