INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '홍대에서 카공하기 좋은 카페 찾고 있었는데 전에 가던 곳보다 더 넓고 집중하기도 좋아서 앞으로는 여기만 올 것 같아요. 그리고 진짜 커피가 대박 맛있음.. 잠봉뵈르도 정말 기대 이상이었어요 ㅠㅠ', 17, 6, 'GOOD', SYSTIMESTAMP);
