INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '단순히 음료마시면서 쉬러 찾아온 장소였는데 3층까지 있는 아늑하고 넓은 장소였어요. 음료 이름들도 되게 특이하고 영감 메세지 카드도 있어서 소소한 재미도 있었어요! 무려 6장의 카드를 모아오면 영감 음료도 무료로 준다고 하네요. 3층은 아예 개발을 하기에 쾌적한 장소처럼 멀티 플러그도 구비돼있고 이것저것 창작자들이 찾기에 좋은 장소인것 같아요ㅎㅎ 다음에도 찾아올 계획이에요.', 50, 0, 'GOOD', SYSTIMESTAMP);
