INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '작업에 집중할 수 있도록 해주는 편안한 인테리어와 의자,테이블에 신경 쓰신게 보이고 무엇보다 스테디,베스트셀러 책들이 아주 다양하게 있다는 점.... 독서까지 음료 한잔으로 할수 있다는게 최고에요 :)', 46, 9, 'GOOD', SYSTIMESTAMP);
