INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '카페 자체가 커서 다양한 공간이 있어 좋았어요!! 공간자체도 작업 공부하기 넘 좋은 카페!! 책도 있고 혼자 노트북하러 작업하러 오기 좋은곳!! 음료도 맛있었어요 :) 혼자 작업하러 오신분 수다떨러 오신분 모두 많았습미당', 39, 1, 'GOOD', SYSTIMESTAMP);
