INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '홍대 오면 자주 찾는 곳입니다. 일단 매장이 크고 청결해요, 커피도 너무 맛있구요. 무엇보다 환경이 무언가에 집중하기 너무 좋습니다. 홍대에서 작업할 게 생기면 첫번째로 떠오르는 곳입니다!', 62, 14, 'GOOD', SYSTIMESTAMP);
