INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '예전부터 한번 꼭 와보고싶었는데 우연히 오늘 와보고 너무 마음에 들어서 자주 와야겠다고 생각했습니다..! 작업하기 너무 좋은 차분한 분위기고요 여러사람들이 독서하거나 작업하시는 모습들도 많이 볼 수있어서 자극받을 수 있는 공간이예요..! 완전 추천합니다😉', 32, 7, 'GOOD', SYSTIMESTAMP);
