INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '이제 와본걸 후회할 정도로 너무 좋은 공간이네요❣️ 굳이 스카 방문하거나 카공할 카페를 찾을 필요 없이 렉터스로 정착하면 될것 같아요 어딜 앉아도 작업하기 편하고 집중이 잘 되도록 공간이 구성되어 있고, 커피 디저트 모두 맛있고 퀄리티 좋았습니다 앞으로 자주 찾을 곳으로 찜!', 18, 2, 'GOOD', SYSTIMESTAMP);
