INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '홍대에서 작업하기 좋은 카페를 찾고 있었는데 여기 정말 좋았어요! 노트북작업 하기에 너무 좋았고 노트북이 아니더라도 정말 공부하고 자기개발하기에 너무 좋은 카페였습니다:) 치즈케이크 꾸덕하니 맛있고 커피도 얼음양이나 샷조절이 가능해서 취향것 마셨습니다 다음에 또 홍대에 작업할 일이 생기면 이용할 것 같아요! 또 주문하는곳 옆에 갤러리가 있었는데 건축에 대한 것을 많이 볼 수 있어서 좋았습니다', 26, 8, 'GOOD', SYSTIMESTAMP);
