INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '노트북 카페로 전부터 와보려고 찜해놨던 곳인데 은은하게 흘러나오는 노래도 좋고 채광 강한 곳과 조도 낮은 곳 공간이 다양해서 좋아요 집중이 잘 되는 카페! 또 오려구요 #작업하기 좋은 카페 #노트북하기 좋은 카페', 9, 1, 'GOOD', SYSTIMESTAMP);
