INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '차분하고 아늑하고 따뜻하고 처음 방문했는데 공간이 참 만족스러워서 분명 재방문할거같아요 ㅎㅎ 여럿이서 와도 좋을만큼 크고 넓은 공간도 있고 조명 음악 다 감각적이에요! 홍대에서 이렇게 맘편히 작업하고 책읽을 수 있는 카페가 있다니 감사한 마음입니다!!! 🤎', 2, 4, 'GOOD', SYSTIMESTAMP);
