INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '인테리어가 감각적이고, 음료의 네이밍 센스도 감성있어요. 잔잔한 재즈풍 노래와 넓고 다양한 공간이 집중하기에 좋게 잘 구성되어 있어요. 음료도 시그니처 메뉴 맛있고 좋아요! 재방문 의사 200%인 곳이에요! 특히 작업공간으로는 최적의 장소!', 35, 7, 'GOOD', SYSTIMESTAMP);
