INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '렉터스라운지 깔끔하고 좋은 분위기였고 직원들도 모두 친절하셔서 잘 이용하였습니다! 음료도 맛있고 깨끗해서 이용하기 좋았습니다!', 40, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '홍대 작업용 카페 검색해서 발견한 곳인데 정말 넓고 콘센트도 많고 작업용으로 딱이에요 책상도 넓고요 몇몇 책상은 의자가 시디즈네요 ㅋㅋ 컨셉 자체부터 작업용이니 눈치 안 보고 집중할 수 있는 거 같아요! 아메리카노 5500원이라 커피값 자체로만 보면 비싼 편이지만 가성비가 아주 좋다고 생각합니다. 식사 안 하고 와서 잠봉뵈르 시켰는데 후추랑 허브 잔뜩 뿌려져서 맛있어요ㅎㅎ', 26, 3, 'GOOD', SYSTIMESTAMP);
