INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '작업하기 딱 좋은 홍대 분좋카 추천합니다...🫶 잔잔한 재즈음악이 틀어져있고 다들 조용조용 대화하거나 각자 작업하는 분위기에요 1층,2층 구조라 좌석도 널널한데다가 콘센트 자리도 꽤 많아서 노트북 작업하기도 좋아요🔥', 83, 13, 'GOOD', SYSTIMESTAMP);
