INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '따듯한 아메리카노와 아이스 라떼는 고소하였습니다. 커피 향이 너무 좋았어요. 분위기 있는 카페이고, 작업하시는 분들이 많아서 작가들에게 사랑받는 카페로 느껴졌습니다. 저 역시 블로그 작업을 하며 시간을 보냈는데 집중이 잘 되었어요. 대화 나누는 사람들도 많아요! 다음에 또 오고 싶은 카페입니다.', 23, 10, 'GOOD', SYSTIMESTAMP);
