INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '집중하여 작업할 곳이 필요했는데 그렇다고 스터디카페로 가기엔 노트북타자소리가 신경쓰이고 다른 카페들은 너무 시끄럽고... 그럴때 렉터스 라운지가 아주 딱입니다! 공간도  넓고 음료랑 음식도 고퀄입니다! 강추해요><', 2, 4, 'GOOD', SYSTIMESTAMP);
