INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '조용하고 아늑한 공간 내에서 집중해서 작업 잘 끝내고 갑니다 :) 무아지경 음료도 맛있어요 :D #서울북카페 #홍대카페 #작업하기 좋은 카페 #책 읽기 좋은 카퍽 #노트북하기 좋은 카페', 41, 6, 'GOOD', SYSTIMESTAMP);
