INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '외관이 멋져서 알고는 있었지만 몇 번 지나만 가다가 오늘 첫 이용! 분위기도 괜찮고 매장도 넓고 구역마다 분리 공간이 있어서 목적에 맞게 활용하기 좋은 곳 ! 일하기도 집중 잘 되고 베이글+커피 맛있음!!', 9, 0, 'GOOD', SYSTIMESTAMP);
