INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '분위기 너무 좋고 카페 예뻐요! 조용해서 책 읽기 좋은데, 스터디 카페만큼은 아니라서 편하고 안락해요ㅎㅎ 커피도 맛있습니다! 카페가 크고 운영시간도 길어서 자주 올 거 같아요😊 #작업하기 좋은 카페 #노트북하기 좋은 카페 #책 읽기 좋은 카페', 62, 12, 'GOOD', SYSTIMESTAMP);
