INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '메뉴명 하나까지도 정말 고민을 많이 하셨구나 생각이 들어요! 저랑 여자친구는 ''순리대로''라는 이름의 칵테일과 ''무아지경''이라은 칵테일을 마셨는데 이름도 맛도 재밌습니다😄 책을 읽기도, 공부를 하기도,  대화를 하기도, 일을 하기도 좋은 아지트같은 정말 특별한 장소입니다! 자주 올게요!!', 31, 1, 'GOOD', SYSTIMESTAMP);
