INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '노트북하기 좋은 카페에요! 나이스합니다. 전반적으로 공부하기 좋아요. 더 일찍 올 걸 후회스럽. 그리고 남성직원분이 개인적으로 쪼오금 무섭긴 한데 그것만 빼면 괜찮습니다.^^', 6, 9, NULL, SYSTIMESTAMP);
