INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '책 읽기 좋고, 일기 쓰거나 노트북 작업하기 좋은 공간이에요. 조용하고 차분한 분위기에 다들 집중해서 작업하고 있어서 몰입도 잘되고, 쇼콜라케이크가 너무 맛있었어요.... 홍대에 이런 노트북 하기 좋은 카페가 생각보다 없는데 렉터스로 자주 오게 될 것 같아요', 66, 16, 'GOOD', SYSTIMESTAMP);
