INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '분위기가 차분해서 집중하기 좋은 공간이었어요. 콘센트도 이곳저곳에 있어 노트북 작업이 용이했습니다. 그렇다고 너무 조용한 분위기는 아니어서 친구와 조용히 대화나누는 정도는 괜찮았어요! #작업하기좋은카페 #노트북하기좋은카페', 14, 5, 'GOOD', SYSTIMESTAMP);
