INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '루이보스 티 마시면서 책 읽었는데, 적당히 햇살 들어오고 음악이 좋아서 집중이 잘 됐어요 ! 노트북 작업 하시는 분들도 많아서 공부나 일 목적으로 리프레쉬하기 적합한 공간인 것 같습니다 ㅎㅎ', 19, 4, 'GOOD', SYSTIMESTAMP);
