INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '매장이 넓고 분위기도 편안해요 ㅎㅎㅎ 작업카페 찾고있었는데 앞으로 애용하려고요! 커피랑 케이크도 넘 맛있습니다… 넘 맛있어서 나오자마자 허겁지겁 먹느라 사진이 좀.. 이미 먹어버렸네요ㅜ ㅋㅋㅋㅋㅋ 케이크가 은근 큽니다!! 작업하시는 분들도 많아서 조용하고 좋습니다!!', 50, 9, 'GOOD', SYSTIMESTAMP);
