INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '3번째 방문! ㅎㅎ 자리마다 다른 특색이 있어서 분위기가 다양한데 오늘은 창가석에 앉아 이전 두 번 방문 때와는 또다른 이 곳의 매력을 느낌! 제일 좋은점은 집중이 잘 된다는 점!', 34, 4, 'GOOD', SYSTIMESTAMP);
