INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '북카페 찾아서 왔는데 좌석도 많고 조용한 분위기라 집중이 잘되네요 어두운 공간도 있고 밝은 공간도 있어서 취향에 따라 고르면 될 거 같아요! 돌체라떼 좋아하는데 여기 돌체 맛있어요 고소하고 달달해서 흑임자라떼 느낌도 나고 생각날거 같은 맛이에용', 77, 18, 'GOOD', SYSTIMESTAMP);
