INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '창작하거나 일하기 너무 좋은 공간이에요!! 심지어 모니터도 있답니다..🙃 노래도 잔잔하고 의자도 편해요 ㅎㅎ 다같이 작업 필요하거나 책 읽고싶을 때 자주 오고싶숩니다 ><', 46, 3, 'GOOD', SYSTIMESTAMP);
