INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '노트북 작업이 필요해서 괜찮은 카페를 찾다고 우연히 오게되었습니다. 그런데 층별로 작업공간도 나뉘어 있고 무엇보다 콘센트도 넉넉해서 작업하기 아주 좋았습니다. 그리고 커피자체도 맛습니다👍🏻👍🏻 #작업하기좋은카페 #노트북하기좋은카페 #책읽기좋은카페', 6, 2, 'GOOD', SYSTIMESTAMP);
