INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '분위기가 좋아요 진열된 책도 제 취향이라 책 읽으러 와도 될것 같습니다 노트북 하는 사람도 있고 얘기하는 사람도 있고 음악까지 잔잔하고 편안한 분위기입니다 조만간 재방문 하려구요 번창하세요!', 121, 20, 'GOOD', SYSTIMESTAMP);
