INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '늦게까지 하는 홍대부근 넓은 카페를 찾다가 오게됐어요! 조용해서 웃고떠드는 분위기는 아니지만 일행들이랑 조곤조곤 대화나누기 좋았습니다 작업하러 오신들이 많아서 저도 작업할거 가지고 다시 오고싶은 장소입니다!', 23, 4, 'GOOD', SYSTIMESTAMP);
