INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '작업하기 좋습니다. 조용하고 노래도 크지 않아여. 콘센트도 많고 담도 준비되어 있어요! 편안하게 온전히 집중할 수 있는 공간이 생겨 좋습니다🙂', 52, 11, 'GOOD', SYSTIMESTAMP);
