INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '멋진 카페예요 조용히 작업 및 공부하기 정말 좋아요. 들어와서 놀랄정도로 인테리어 잘 해놓았고 조용해요 ! 앞으로 단골 예약이예요 😊😊', 29, 9, 'GOOD', SYSTIMESTAMP);
