INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '날씨가 좋은 날엔 항상 큰 통창을 열어주셔서 요즘에 부쩍 자주 찾는 가게입니다. 다들 공부나 작업 중이셔서 집중해야 할 일이 있을 때 와요ㅎㅎ 추천합니당', 59, 15, 'GOOD', SYSTIMESTAMP);
