INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '오늘도 선택한 렉터스 라운지! 모두 각자의 할 일을 열심히 하고 있어서 왠지 집중이 더 잘 되는 기분!! 오트라테도 굿! ☕🥛', 5, 10, 'GOOD', SYSTIMESTAMP);
