INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '자리도 많고 소파자리,혼자 작업할만한 자리가 있어서 친구랑 오는것도 좋고 작업할려고 오는것도 좋을것같아요! 전체적으로 조용한 분위기라 집중도 잘될것같습니다!!', 12, 4, 'GOOD', SYSTIMESTAMP);
