INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '친구가 오자고 해서 처음 와봤는데 층마다 분위기가 다양해요! 구조가 다른 카페랑은 느낌이 달라서  놀랐어요 노래도 작업하기 좋았습니다', 42, 0, NULL, SYSTIMESTAMP);
