INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '집 근처에 있다면 매일 와서 작업하고 싶은 카페입니다.  아쉽네요.. 커피도 맛있고 공간을 보는 재미도 있고 집중해서 혼자 작업하거나 회의하거나 독서하거나 어떤 경우든 다 적합한 카페입니다!', 75, 15, 'GOOD', SYSTIMESTAMP);
