INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '북카페라서 집중하기에도 좋고, 토론하기에도 좋은 공간이 있어요. 이 건물 구조가 독특해서 보는 재미가 있었습니다! 또한 기다리는 동안 후지산 액자 구경하는 재미도 쏠쏠했어요 ㅎㅎ 24시간 운영하니 오랫동안 분위기 좋고 말할 수 있는 공간에서 있고 싶은 분들께 추천합니다!', 105, 25, NULL, SYSTIMESTAMP);
