INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '노트북 작업할 일이 있어 적당한 곳을 찾다 왔습니다! 집중하는 분위기라기보다 좀 더 편안하고 감성넘치는 곳이네요. 2층으로 이동하는 계단이 다락방 느낌이 나서 좋네요ㅎ 당신의 평안이라는 카카오 음료도 진하니 맛있어요! 자주 올거 같네요~', 59, 11, NULL, SYSTIMESTAMP);
