INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '공간배치나 음악이 책읽기에 정말 좋아요! 음료도 당도 옵션 다양하게 선택할 수 있어서 마음에 듭니다❣️ 다음엔 글을 쓸 수 있는 노트북이나 종이와 펜을 챙겨서 재방문해야겠어요', 27, 4, NULL, SYSTIMESTAMP);
