INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '작업하기에도 좋고 공간도 넓어서 답답하지도 않고 좋았어요! 저는 와서 다이어리도 정리하고 책도 읽었는데 힐링하다가 가요! 커피도 맛있고 사장님도 친절하셔서 다음에도 홍대 올 때 와야겠어요 :)', 101, 23, 'GOOD', SYSTIMESTAMP);
