INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '커피 맛있고 분위기 좋아서 집중하기 너무 좋아요. 맨날 여기올게요 공부하러 ㅋㅋ 노트북이나 패드 필기 소리도 뭐라 신경 안써서 좋은 거 같아요 대화도 가능!', 81, 11, 'GOOD', SYSTIMESTAMP);
