INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '홍대 근처에 차분하고 아늑하고 집중 잘되는 카페에요. 작업하기 좋아서 자주 방문할 거 같아요. 카페라떼랑 커피, 치즈케이크도 너무 맛있어요. 책도 많아서 여러 책을 읽을 수 있어서 좋네요.', 60, 17, 'GOOD', SYSTIMESTAMP);
