INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '이렇게 마음에 드는 공간은 오랜만이에요,, 너무 조용하지 않고 조명도 할 일에 집중하기 좋은? 산만하지 않은 느낌이라 책 한 권 완독하고 갑니다… 덕분에 너무 기분 좋은 하루가 되었어요! 커피도 케이크도 맛있어서 더 만족스럽습니다,,', 42, 9, 'GOOD', SYSTIMESTAMP);
