INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '정말 작업자를 위한 공간이라는게 잘 느껴지는 곳이에요 어두운 분위기 공간부터 통창 뷰가 예쁜 공간, 스몰토크를 위한 쇼파좌석, 단체석까지 다양한 테이블들이 있어서 너무 좋아요! 음악도 잔잔하고 전체적으로 조용한 분위기라 작업하기 정말정말 좋습니다!!', 7, 10, 'GOOD', SYSTIMESTAMP);
