INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '조용히 작업할 공간이 필요해서 방문한 카페!! 작업에 최적화 되어있습니다. 조용한 재즈가 흘러나오고 대부분 작업하는 분들이세요^^ 전망좋은 1층은 라운지로 꾸며져있고 카운터는 지하에 있더라구요~ 공간구성에 진심인 카페라고 느껴졌어요!! 차분하고 조용하게 사색할 수 있는 카페 찾으신다면 강추합니다!!', 74, 13, 'GOOD', SYSTIMESTAMP);
