INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '혼자 책을 읽기에도, 작업을 하기에도 너무나 좋은 공간이에요! 우연찮게 들렸는데 마음에 드는 곳이라 다음에 꼭 다시 들리려고 리뷰 적습니다ㅎㅎ 책 좋아하시는데 깜박하고 놓고 왔다면, 카페 내의 책을 읽을 수도 있어 더욱 좋습니다🫶', 38, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
