INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '라떼아트가 예술이에요 기분이 좋아지는 커피향과 감성적이지만 불편하지 않은 ㅎㅎ 아늑한 공간, 넉넉한 운영 시간으로 언제든 방문하고 싶은 공간이에요 3층까지 있는데 편한 소파좌석, 오피스 좌석, 일반 카페석 등 다양하게 준비되어 있고 차분한 조명과 음악에 조예가 깊으신것 같은 섬세한 선곡까지 작업을 위한 최고의 공간이라 성인 adhd도 집중 빡될것 같아요ㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋ', 31, 6, 'GOOD', SYSTIMESTAMP);
