INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '작업하거나 혼자만의 시간을 가지기 가장 좋은 카페인거같아요!!! 나만알고싶지만 문은 닫지않기를 바래 더 잘되면 좋겠는 그런 감정 강강강추츄추추', 2, 2, 'GOOD', SYSTIMESTAMP);
