INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '집중 하고 싶은 사람에게 최적의 공간 입니다. 차분한 분위기에 적당한 조도, 작은 재즈 노래소리. 오늘 해야 할일 다 끝내고 갑니다•••', 55, 11, 'GOOD', SYSTIMESTAMP);
