INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '처음 방문해본 카페! 들어오는 출입구는 2군데! 지하와, 1층 조금은 복잡한 미로와 같은 공간이지만 공간에 앉아있자니 기분만큼은 복잡하지않고 차분하다 적당한 음악과 대화소리는 백색소음인냥 나만의 세계에 집중하게 해준다 앞으로 자주 애용할 카페가 될것같다!', 7, 6, 'GOOD', SYSTIMESTAMP);
