INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '홍대올때마다 들르는곳인데 창가자리는 오픈런해야 하는거같아요 한강 작가 소설 많아서 책읽기도 좋고 커피가 다양해서 좋아요. 나만 알고시픈곳…👍 #책 읽기 좋은 카페', 8, 6, NULL, SYSTIMESTAMP);
