INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '공부하기 좋은 카페 찾다가 알게 되었어요 작업러 공부러들이 많았구 그냥 소소하게 대화하러 오신 분들도 계셔서 너무 조용하거나 시끄러운 곳에서 공부 못하는 저에게 제격이었습니다 ;) 작업이나 가벼운 독서 하러 오기도 좋을 것 같아요', 26, 10, 'GOOD', SYSTIMESTAMP);
