INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '너무 분위기가 좋아요...! 매장이 매우 넓고, 콘센트 있는 좌석도 많아서 공부하기 좋습니다👍무엇보다 음료수가 정말 맛있어요 ❤️ 완전 분좋카입니다. 책도 많아서 나중에 책읽으러도 오고 싶어요~', 44, 10, 'GOOD', SYSTIMESTAMP);
