INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '어느새 단골이 되어버렸네요..! 일주일에 3-4번은 공부하러 오는 것 같습니다! 집에서 집중못하는 사람들은 여기서 공부하시면 10시간도 앉아있으실 수 있을겁니다. 무엇보다 의자가 또 편해요..!', 32, 1, 'GOOD', SYSTIMESTAMP);
