INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '연 후 에 공부하려고 방문 했어요! 분위기 너무 좋고..!! 모니터가 있어서 인강 볼때도 너무 편하고 노래도 좋아서 연휴 내내 올듯요! 진짜 강추강추! #작업하기 좋은 카페', 26, 7, 'GOOD', SYSTIMESTAMP);
