INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '친구 소개로 가볍게 카공하러 들렀는데 인테리어 하나하나부터 공간 활용까지 너무 완벽하고 제 스타일이었습니다🥹 무엇보다 커피랑 잠봉뵈르가 너무 맛있어서 또 먹으러 와야겠어요!! 최근 가본 카페 중 최고입니다💗', 49, 10, 'GOOD', SYSTIMESTAMP);
