INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '홍대 근처 카페 렉터스라운지 방문했어요! 주택을 개조한 카페라 지하부터 야외공간까지 이용가능하고, 분위기도 조용하고 멋있더라구요!! 음료 이름도 특별하고 맛있어요~~👍🏻 공간이 여러개 나뉘어 있어서 맘에드는 곳에서 커피한잔 즐길 수 있고, 전시도 볼 수 있어서 좋은 공간 같아요☺️ 렉터스라운지 홍대 추천이요👍🏻', 36, 8, 'GOOD', SYSTIMESTAMP);
