INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '잠시 공부하면서 시간 보내기 위해 들렀어요! 다른 손님들도 뭔가 열심히 하고계시는 분위기라 자연스럽게 저도 집중하게되었어요.  포근한 분위기와 인테리어 덕분에 편하게 시간 보내다 갑니다☺️', 78, 13, 'GOOD', SYSTIMESTAMP);
