INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '다들 책 읽고 공부하는 분위기입니다~ 저는 친구랑 넷플 같이 보고 얘기하려고 방문한 거라 구석진 곳에 앉았는데 좌석도 다양하고 공간도 다양하고.. 좋아요! 나중에 책 읽으러 다시 오고 싶어요^^☕️', 3, 0, 'GOOD', SYSTIMESTAMP);
