INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '조용하고 아늑하고~~~ 홍대커피맛집!! 홍대 조용한 카페 찾으시면 강추에요. 눈치 안 보고 작업하거나 책 읽기 좋은 북카페랍니다. 자리마다 콘센트 다 있어서 노트북 들고 작업할 장소 찾으러 안 다녀도 돼요~~ 1,2층 다 카페인데 각 장소마다 다 매력이 넘치고!! 지인들한테도 엄청 추천한답니다. 날씨 좋을 땐 테라스에서 커피 한잔하기에도 좋고! 약속 기다리면서 차 한잔 하며 여기 있는 책보면서 기다리는 제 아지트^^', 20, 8, 'GOOD', SYSTIMESTAMP);
