INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '작업할 일 있어서 왔다가 너무너무 갤러리같고 이쁘고 커피 맛있는 카페를 발견.. 일단 분위가 너무 취향이고 작업실 같은데 멋지고.. 진짜 맘에 쏙,, 잠봉뵈르 진짜 너무 맛있어요ㅠㅠㅠ💜', 21, 8, 'GOOD', SYSTIMESTAMP);
