INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '아늑한 분위기와 집중이 잘 되는 공간인 것 같습니다. 대화하기에도 편하고 자기 할 일 하는데도 편하고, 음료, 음식 또한 맛있어서 다시 방문하고 싶은 곳입니다!🌿', 130, 21, 'GOOD', SYSTIMESTAMP);
