INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '두번째 방문입니다. 대형카페이면서 분위기 좋고 깔끔하기 쉽지 않은데 다 갖췄고요 집중도 잘되어서 작업할일이 있거나 중요한 일이 있으면 꼭 오는 것 같아요! 노래도 좋고 메뉴판에도 힘이되는 카피들이 쓰여있습니당 새로운 상상을 마시며.. 좋운 아이디어가 나오길', 0, 8, 'GOOD', SYSTIMESTAMP);
