INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '매장이 넓고 집중하기 좋은 분위기예요. 3층에는 보조모니터 있는 좌석도 있어요. 작업하기 좋은 카페인데 완전 북카페는 아니라서 친구랑 대화도 가능해서 좋아요!', 23, 9, 'GOOD', SYSTIMESTAMP);
