INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '첫 번째 방문하고서 마음에 들어 두 번째 방문했습니다! 여전히 작업하기에 여유롭고, 편안한 분위기에다 커피랑 치아바타 잠봉뵈르 샌드위치는 너모 맛있어여ㅎㅎㅎ 세 번째, 네 번째 또 방문할께욤 대성하세요😊', 14, 2, 'GOOD', SYSTIMESTAMP);
