INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '책 읽기도 좋고 넓고 층고도 높고 조용하고 가사 없는 음악 나오고 빵도 맛있고 진짜 우연히 들렸는데 무척 만족스럽습니다 추천해요 다음에도 올 예정', 124, 24, 'GOOD', SYSTIMESTAMP);
