INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '근처 도서관만 가다가 집중하기 좋은 카페가 있다고 해서 한 번 와봤는데, 집중하기 너무 좋고 음악도 아주 좋아요! 주말에 커피 한 잔 시켜서 생각 정리도 하고 이것저것 할 일도 하면 마음이 이주 따뜻해지는 공간입니다! 자주 찾을 것 같아요', 106, 23, 'GOOD', SYSTIMESTAMP);
