INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '약속 전에 비는 틈에 시간도 보낼 겸 작업도 하고자 방문했습니다 몰입하기 좋은 분위기에 노래도 잔잔하고 적당히 두런두런한 소리 덕분에 집중하기 좋아요 직원분도 친절하시고 무엇보다 음료랑 빵도 넘 맛있네요!', 9, 8, 'GOOD', SYSTIMESTAMP);
