INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '늦은 시간에 방문했는데 카페 넓고 정숙한 분위기여서 생각 정리나 독서 작업하기 너무 좋더라고요. 카운터가 지하층에 있는데 내려가는 계단이 위험하게 느껴졌거든요. 다 먹고 갔다주러 가야하는건 좀 불편했어요. 식기구 정리하는게 층마다 있으면 더 편할 것 같아요. 디저트가 다양한 카페를 선호하지만 분위기나 공간만으로 충분히 만족스러웠어요. 커피도 좋았고 늦게까지 운영하는 영업시간도 좋아서 자주 방문하려고요. ㅎㅎ', 103, 23, 'GOOD', SYSTIMESTAMP);
