INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '공부하거나 작업하기 좋은 카페에요. 공간도 여러 공간으로 나뉘어져있어서 좋고 조명때문에 아늑한 분위기라 집중하기 좋았어요 음료도 덜 달게 설정가능해서 👍👍', 40, 4, 'GOOD', SYSTIMESTAMP);
