INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '좌석도 다양하고 공간이 넓고 작업하기에 너무 좋아요. 주말보다 평일이 좀 더 조용하고 주말에는 조금 더 활기찬 분위기인 것 같아요!', 10, 2, 'GOOD', SYSTIMESTAMP);
