INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '노트북 작업차 들렸는데 뷰가 너무 좋네요~ 작업공간도 있고, 이야기 나눌만한 공간도 있어서 어떤 목적이든 시간 보내기 좋을 거 같아요. 커피도 굿!!', 15, 10, 'GOOD', SYSTIMESTAMP);
