INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '읽고 싶은책도 가득하고 홍대에서 가본 북카페중에 가장 좋았어요! 커피맛도 good!! 홍대올때마다 들르는곳 #작업하기좋은카페#책 읽기 좋은 카페', 11, 7, 'GOOD', SYSTIMESTAMP);
