INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '근처에서 점심먹고 책보고 컴퓨터 작업할 만한 카페를 찾아보고 있었는데, 추천글을 보고 방문하게 됐습니다. 분위기도 조용한데, 음악도 마음에 들고 책읽기 좋아서 더 마음에 듭니다. 커피도 맛있어서 더 좋았어요. 또 근처 올일 있다면 방문해야겠어요.', 21, 8, 'GOOD', SYSTIMESTAMP);
