INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '홍대입구에서 이런 조용하고 예쁜 카페를 오게되다니 ! 음료도 이름이 ‘긍정과활기‘ 디카페인으로 변경해서 시켜보았는데 풍미가 좋고 토요일 오후 기분좋게 책읽으며 마시기에 너무 훌륭하네요 구조가 복잡한만큼 곳곳에 편안한 장소들이 숨어있는 작업/ 독서하기 좋은 힐링카페입니다 비지엠도 딱 제스타일이에요 ❤️ 홍대입구역에서 걸어오는 길도 멀지 않은데 요즘처럼 날씨좋을땐 한번 꼭 와보세요 강추 !!!', 26, 9, 'GOOD', SYSTIMESTAMP);
