INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '고풍스런 주택을 개조한 이색 카페. 조용하고 한적한 시간을 보낼 수 있는 곳. 커피가 정말 맛있어요. 재즈 음악을 즐기며 조곤조곤 대화하며 힐링하는 시간... 굿!!', 46, 10, 'GOOD', SYSTIMESTAMP);
