INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '벌써 세 번째...커피도 맛있고 잠봉뵈르랑 베이글이 정말 맛있어요 빵도 다 데워주셔서 더 마싯음 ㅠ 공부하기에 이만한 카페가 없고 흡연구역도 있어서 개편함 글고 운영시간도 길어서 그냥 시험기간 망부석행이에요 🥲❤️', 24, 8, 'GOOD', SYSTIMESTAMP);
