INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '홍대 조용한 카페 렉터스라운지 공간 하나하나 전시를 보는 듯하고 조용한 분위기라 좋았어요. 홍대 작업카페로도 좋고 혼카페 하기에도 좋은 공간이였음! 거기다 아메리카노도 엄청 맛있더라고요. 진한 커피 맛 ! 시그니처 메뉴로는 긍정과 활기 돌체라떼 추천드려요. 진짜 진한 우유 풍미에 달달한 연유 + 모카커피 맛이라 당충전 제대로 됩니다!! 케이크 드실 거라면 초코케이크로.. 쇼콜라케이크 거의 초콜릿 먹는 것처럼 꾸덕하고 진했어요. 전체적으로 커피와 디저트, 조용한 카페 분위기까지 모두 만족했어요 굿굿 👍', 22, 9, 'GOOD', SYSTIMESTAMP);
