INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '분위기 미쳤는데요.. 여기서 작업하면 자동으로 영감이 샘솟을 것 같아요🥹 들어오는 입구부터 심상치 않았는데, B1부터 2층까지 모두 몰입하기 좋은 환경입니다! 책도 많고~ 문화예술의 대학로 홍대를 대표하는 카공 카페로 임명합니다! 땅땅👍', 28, 3, 'GOOD', SYSTIMESTAMP);
