INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '분위기가 너무 좋고 작업하는 사람들에게 최고의 공간일 것 같아요! 듀얼모니터도 있고 일단 공간이 다양하고 큼직큼직해서 너무 좋았어요! 다음엔 노트북 들고와서 작업해야겠어요!!!', 20, 6, 'GOOD', SYSTIMESTAMP);
