INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '섬세한 설명이 달려 있는 특색 있는 메뉴가 인상적이었어요 :) 다양한 좌석이 있는 편안한 공간에 맛있는 커피까지 잘 마시고 갑니다.', 10, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '노트북으로 작업할 수 있는 공간을 찾던 중 렉터스라운지를 오게 되었는데 커피가 맛있고 자리도 많아서 좋아요! 특히 잔잔히 나오는 재즈가 집중력에 매우 도움이 돼서 자주 올 거 같습니다', 11, 3, 'GOOD', SYSTIMESTAMP);
