INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '홍대에서 가장 편하게 공부할 수 있는 카페같아요 집중할수있는 방도 따로있고, 분위기도 좋아서 자꾸 이끌려서 오는 곳입니당 인테리어 너무맘에들어요🥹❤️🥹❤️ #분좋카', 38, 0, 'GOOD', SYSTIMESTAMP);
