INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '노트북 작업할 일이 있어서 찾아왔는데 음악이 좋아서 집중하기 딱이었어요!! 공간이 다양한데다가 음료도 맛있습니당 다음엔 책 읽으러 와도 좋을 것 같아요☺️', 37, 2, 'GOOD', SYSTIMESTAMP);
