INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '주말엔 조용한 카페가 없어서 북카페릉 검색해서 찾았어요 정말 지금까지 가 본 카페 중 가장 공부하기좋은 분위기이고 사용은 안했지만 컴퓨터가 있답니다.. 노트북이랑 연결해서 큰 화면으로 보시는 분도 계셨어요 이 모든게 음료 한잔만 시키면 누릴 수 있다는게 너무 좋은 궇 같아요 다음번에 또 방문하려고 리뷰 작성합니다', 117, 26, 'GOOD', SYSTIMESTAMP);
