INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '오늘도 들렀다갑니다!! 렉터스최고에용~! 집중잘되고 다들 열심히 하는분들 여기 모인거같에서 분위기좋아요 드디어 영감카드 다 모아갑니당 ☺️👍🏻 매일 오고싶은곳!!', 12, 10, 'GOOD', SYSTIMESTAMP);
