INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '늦게까지하는 카페 찾다가 발견해서 들어왔는데 1층,2층으로 공간이 넓고 와서 독서하기에도 좋고 이야기하기에도 좋은 그런 공간인 것 같습니다! 다음에 또 방문할게요.', 19, 5, 'GOOD', SYSTIMESTAMP);
