INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '조용한 분위기에 수다떨기 좋아요!! 연유라떼=긍정과 활기 음료명도 지금 저에게 딱 필요한 시기인데!! 맛있는 커피에 의미있는 내용에 더욱 맛있게 느껴져요. 다시 한 번 마음을 다잡아 보세요. 반드시 잘 될거예요.😀', 45, 10, 'GOOD', SYSTIMESTAMP);
