INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '조용한 카페 찾다가 대학 후배와 간 곳인데 책이 정말 많더라고요. 혼자 와도 커피 시켜 놓고 책 읽기에도 좋은 카페고 층마다 특색있게 꾸며놨는데 커피 맛도 좋은데 쇼콜라 케이크도 꾸덕하니 당 충전하기 좋더라고요. 카페 인테리어도 마음에 들고 커피, 디저트까지 아주 만족스러운 카페입니다.', 120, 21, 'GOOD', SYSTIMESTAMP);
