INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '작업하기 위해 방문했는데, 공간 인테리어도 예쁘고 편안한 분위기여서 집중이 잘 됐습니다 너무 맘에 들어서 또 오려구요!!! 당신의 평안이라는 메뉴 당도 조절이 가능한 점이 엄청 좋았어요 ㅎㅎ 당도 0으로 마셨는데 쌉싸름하고 맛있었습니다', 16, 7, 'GOOD', SYSTIMESTAMP);
