INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '블로그를 통해서 알게되었고 방문했습니다. 사장님의 따뜻한 말투에서 마음이 포근했습니다. 그리고 각자 자기의 일을 하고 있으니 저도 제 것을 하면 되겟다라는 분위기입니다. 어때요? 좋죠?😉', 0, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '매장이 2층까지 있고 작업, 공부 공간이 넓습니다! 이야기하기에도 좋아서 친구와 오시거나 공부, 작업하러 혼자 오셔도 좋을것 같아요 강추!! 그리고 커피도 맛있어요ㅎ', 48, 4, 'GOOD', SYSTIMESTAMP);
