INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '조용하고 음악이 굉장히 좋아요 긍정과 활기 커피 진짜 맛도리입니다!!! 강추 디카페인 변경도 가능하니 매우 좋아용 담에 또 와야지~!~!~!~!!', 31, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '늦은 시간에 앉아서 쉴 곳 찾다가 발견했는데 분위기가 넘 좋고 메뉴도 맛있어용 시그니처 음료가 커피부터 칵테일까지 다양해서 다음에 또 와보고싶어요 ㅎㅎ 이번엔 혼자서 왔지만 이름대로 여러명이서 작업하기에도 적합합니다!!', 1, 0, 'GOOD', SYSTIMESTAMP);
