INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '일부러 찾아와봤는데 이것저것 작업하기 딱 좋았어요! 다들 집중하는 분위기라 더 집중도 잘되고 그렇다고 너무 조용하기만 한 것도 아니라 좋았습니다!! 커피 종류 다 있고 티 종류도 다양해서 넘 좋았습니다 다음에도 무조건 또 와야할 곳!! #작업하기좋은카페 #노트북하기좋은카페 #책읽기좋은카페', 32, 10, 'GOOD', SYSTIMESTAMP);
