INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '목말라서 나오자마자 먹고 사진찍는거 생각나서 찍었어요 와서 책읽거나 작업하기 좋고 자리도 많고 전체적으로 차분한 분위기여서 좋은거 같아요!!!!! 담에도 책읽으로 올려고요 그리고 좋은점은 늦게까지 한다는게 장점인거 같아요', 30, 1, 'GOOD', SYSTIMESTAMP);
