INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '이런곳을 왜 이제 알았을까요 정말 작업하기 최적화된 곳이에요 들어오면 마치 건축가의 작업실에 놀러온 기분이네요 #작업하기 좋은 카페 #노트북하기 좋은 카페 #책 읽기 좋은 카페', 7, 3, 'GOOD', SYSTIMESTAMP);
