INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '글쓰기 너무 좋은 공간이네요. 오늘 처음왔는데 반했습니다!! 멤버십에도 가입하고 싶네요^^ 좋은 공간에서 영감받고 글 잘 쓰고 갑니다🧡🧡 저만 알고 싶은 공간이예요 강추!!', 34, 1, 'GOOD', SYSTIMESTAMP);
