INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '처음 방문해봤는데 단순 카페가 아닌 책읽기도 좋고 작업하기도 좋고 다이어리 끄적거리기도 좋은 라운지형  카페였어요. 수다 떠는 분들도 계셨지만 분위기가 분위기인 만큼 시끄럽진 않았구요~ 음악도 잔잔하니 몰두하기 좋았습니다. 아이스 라떼 주문했는데 고소하니 맛있었어요!!! 재방문 의사 완전 있어요 :)', 34, 7, 'GOOD', SYSTIMESTAMP);
