INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '공간이 독특하게 인테리어가 잘 되어있고, 잠봉베르가 너무 맛나요~! 카공하기에 최적인 카페입니다:)🥹🫶🫶#작업하기 좋은 카페 #노트북하기 좋은 카페 #책 읽기 좋은 카페', 62, 13, 'GOOD', SYSTIMESTAMP);
