INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '홍대에 카페 어디가지? 하다가 오게 된 곳인데.. 진짜 느좋 카페 인정 또 오고 싶다는 생각이 들어요 감성 하나 하나 너무 좋고 분위기도 좋고 다들 조용해서 작업하기 최고인 것 같아요 특히나 책들이 정말 많은데 읽고싶었던 책들이 많이 보여서 행복하네요 진심에서 우러나는 후기입니다 꼭 다들 와보세요!!', 37, 4, 'GOOD', SYSTIMESTAMP);
