INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '약속시간 전에 책 읽을수 있는 조용하고 고즈넉한 분위기의 북카페를 찾아왔는데 , 매장도 3 층까지 넓고 집중해서 작업하거나 , 책 읽고싶을때 좋아요 😊 커피이름이 긍정과 활기 달달하고 너무 맛있어요 👍🏻 다음에 다른 커피들도 마시러 , 더 길게 있을때 또 방문 하고싶어요 ~ ☺️', 33, 9, 'GOOD', SYSTIMESTAMP);
