INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '렉터스라운지 홍대'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '이번주만 벌써 두번째 방문이에요. 분위기 너무 좋고 자리도 은근 많아서 책읽기도 이야기하기도 정말 좋은 것 같아요! 자주 오고 싶어요~', 56, 12, 'GOOD', SYSTIMESTAMP);
