INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '써니데이 인 잔다리'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '차가운 포케에 디여 다이어터임에도 포케는 거들떠도 안봤는데.. 써니데이 포케는 포케에 대한 생각을 바꿔 줬다! 포케원래 차가운 재료들로 구성되어 제공 된다는 그 예전 어느 포케집과는 차원이 다른 풍요로움에 진짜 넘나 만족스럽게 냠냠 💗 밥과 치킨에 온기가 있어 목 넘김이 부드러웠고 껍질이 있었어도 닭누린내가 나지 않아 너무 맛있었다 다이어터 뿐 아니라 클린식이 필요한 현대인에게 꼭 꼭 추천해봅니다 :) ✅모든재료가 신선하고 ✅넓고 쾌적하고 에어컨 빵빵빵!! ✅달콤청량깔끔한 레몬청에이드 찐맛탱구리리', 126, 19, 'GOOD', SYSTIMESTAMP);
