INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '써니데이 인 잔다리'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '넓고 쾌적하고 편안한분위기 독서모임했어요 스터디카페같은 조요한분위기 커피는 맛있구 말차라떼 아이스크림 얹어서 달콤하고 홍시라떼 엄청달콤ㅎㅎ 기분좋은시간이였어요', 37, 4, 'GOOD', SYSTIMESTAMP);
