INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '써니데이 인 잔다리'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '매장도 정~~~말 넓고, 인테리어가 깔끔해서 좋았습니다! 그릭요거트도 과일이 듬뿍 올라가서 상큼합니당 시그니쳐 음료인 것 같은 써니데이 크림라떼는 크림이 듬뿍 올라가져 있어서 너무 맛있게 먹었습니다 :)', 66, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '써니데이 인 잔다리'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '작업하기좋은 조용하고 넓은 카페입니다 포케랑 요거트 메뉴도 있어 식사할수도 있습니다 주말에 가니 한적하고 조용해 여유를 느낄수 있어 좋네요. 아이스티에 샷추가해서 아샷추 주문해봤어요 포케랑 아메 주문하면 아메리카노 할인 많이 되니 참고하시고 콘센트가 있어 편했습니다', 8, 8, 'GOOD', SYSTIMESTAMP);
