INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '써니데이 인 잔다리'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '작업할 일 있거나 집중하고 싶을 땐 여기를 꼭 오게 되요. 푸드메뉴도 다양해서 식사하고 커피먹고 완전 다 가능!! 넓은데 아늑해서 너무 좋습니다 ㅎ', 100, 24, 'GOOD', SYSTIMESTAMP);
