INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '써니데이 인 잔다리'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '포케 먹고 맛있어서 샐러드베이글세트까지 또 먹으러 왔어요! 식단관리 때문에 샐러드나 포케 자주 먹는데 여긴 카페에서 파는거라 샐러드먹고 커피까지 먹기 좋아요💚 다음에 또 올게요 신선함 유지해주세용🌿', 18, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '써니데이 인 잔다리'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '분위기 좋고 넓고 깨끗해용 젤 좋았던게 음식이 너무 맛있습니다.. 이 연어베이글이 댑악🙈 포케도 야채 많고 조화로워서 맛있었어용~!~ 음식이 맛있으니까 가끔 생각날 것 같아서 또 오려구욤😋', 257, 46, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '써니데이 인 잔다리'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '콘센트 넉넉하고 작업하기 좋은 카페 주말엔 자리가 더 많게 느껴지는듯 넓고 식사메뉴 있고 와이파이 빨라서 넘 좋은데 커피는 좀 맛이 없움', 2, 8, 'BAD', SYSTIMESTAMP);
