INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '써니데이 인 잔다리'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '매장이 넓어서 눈치보지 않고 집중하기 좋고 쿠키가 맛있어요 ㅋㅋㅋ 부실해보이는 이미지랑 다르게 많이 안달고 쫀득하니 좋더라고요 ㅎㅎ 카야 토스트는 빵이 좀 개선되면 더 좋겠네욥 샌드위치 종류도 많던데 다음에 먹어봐야겠어요', 9, 7, 'GOOD', SYSTIMESTAMP);
