INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '써니데이 인 잔다리'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '합정 망원 산책하다 발견한 써니데이즈잔다리 늦은 점심 플레인베이글 요거트 쵸코그린아스크림 푸짐하게 주문한 우리💕 가볍게(?) 식사 타임 후 따아 주문 했어요~ 사진 없지만 커피도 맛나고 넓은 좌석으로 스터디 하기에도 너무 좋은 분좋카 딱이네요~ 잘 먹고 좋은 시간 보냈어요:)', 31, 1, 'GOOD', SYSTIMESTAMP);
