INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '써니데이 인 잔다리'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '내 최애 커피숍 중 하나 사장님 직원분들 너무 친절하고 너무 좋아욤 이번에 나온 샌드위치도 진짜 대박적 이 샌드위치 딘짜 꼭 먹어봐야함 !!!!대박적인 맛', 13, 10, 'GOOD', SYSTIMESTAMP);
