INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '써니데이 인 잔다리'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '자주오는 곳인데 계속 방문하게 될만큼 분위기 최고에요! 커피맛도 진하고 좋아요 ;) 지인에게 추천하고 싶은 곳입니다. 또 올게요!', 31, 5, 'GOOD', SYSTIMESTAMP);
