INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '써니데이 인 잔다리'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '보통 카페에 가면 작업이나 독서 보다는 대화하는 걸 좋아하는데, 가끔 일이 생겨 급한 작업을 해야할 때 가기 정말 좋은 곳. 대화 보다는 작업, 공부, 업무를 보는 사람들에게 최적화 되어 있는 것 같다..!', 2, 9, 'GOOD', SYSTIMESTAMP);
