INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '써니데이 인 잔다리'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '커피 마시면서 책읽기 좋은 카페입니다. 넓고 쾌적해서 서교동 올때마다 들르는 분위기 맛집입니다! 커피 맛도 좋고 음악도 좋습니다~ 주말보다 평일이 방문하기 더 좋습니다!', 19, 2, 'GOOD', SYSTIMESTAMP);
