INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '써니데이 인 잔다리'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '넓은 매장과 테이블. 고소하고 시원한 커피. 그 사이로 서로가 펼쳐놓은 네모난 랩탑에선 많은 일들이 벌어지고 있었다. 세상을 바라보는 시야가 직사각형으로 규정된 이유는 무얼까. 내 눈을 가리고있는 안경만큼은 직사각의 저주에서 벗어나고 싶었다. 잠깐 살다 가는 인간이라는 저주에선 벗어날 수 없었지만 세상이 만들어놓은 공간에서 내가 만든 것 하나 없이 누군가의 작품들로 하루를 살아가는 것 만큼은 저주가 아니라 복이었을까. 커피 한 잔 음미하며 직사각에 몰두할 때 파생되는 모든 결과물은 반도체 위에 기록되어 전파를 타고 어디론가 사라져버리듯 공유되는 세상. 분명히 이 커피의 원두도 우유도 내가 앞으로도 볼 일 없을 어딘가의 누군가가 만들어냈을 것이란 생각. 직사각의 세상에서만 가능한 일이 아니었을까', 8, 6, NULL, SYSTIMESTAMP);
