INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '써니데이 인 잔다리'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '카페가 정말 넓고, 노트북 하기 좋게 돼있어요. 창도 커서 답답하지도 않구요. 홍대 합정 쪽에서 여기만큼 작업하기 좋은 곳은 없는 것 같네요.', 4, 8, 'GOOD', SYSTIMESTAMP);
