INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '써니데이 인 잔다리'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '두바이초콜릿, 아메리카노 주문. 근처 식당 웨이팅 걸고 우연히 방문했는데 내부가 생각보다 넓고 쾌적해서 좋았습니다. 두바이 초코 맛났어요!! 물론 가격 생각하면 다시 먹을 정도인지는 모르겠지만… 맛있었습니다. 잘쉬고 갑니다!', 73, 13, 'GOOD', SYSTIMESTAMP);
