INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '써니데이 인 잔다리'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '카공족에겐 좋습니다 그런데 콜드브루를 시켰는데 콜드브루인지 보리차인지 모를 너무 연한 커피가 나와서 당황했습니다. 작업하거나 책읽으실 분들에겐 추천입니다. 조용한 음악이 나오기 때문에 차분하고 편안한 분위기입니다. 화장실 남여분리인 것도 좋아요', 17, 6, NULL, SYSTIMESTAMP);
