INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '써니데이 인 잔다리'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '매장 자체가 시원시원하게 넓고 큼직해서 굉장히 쾌적했습니다. 높은 층고로 음악소리가 뭉개지지않고 퍼지다보니 공간이 주는 힐링감도 좋았고 커피가격도 4.5천원으로 준수한 가격대에 앉아서 공부하거나 작업하기 좋은 데스크공간도 있어 이른시간부터 다들 작업하러 오시는거같은데 좋더라구요. 주변에 들르신다면 방문해보세요', 64, 15, 'GOOD', SYSTIMESTAMP);
