INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '써니데이 인 잔다리'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '오랜만에 갔는데 벽 인테리어가 시계로 바뀌어서 더 무드있어졌더라구요ㅎㅎ! 갈 때마다 항상 새로운 메뉴를 시키는데 뭘 먹어도 맛있어서 항상 기분이 좋아집니다. 카공하기 너무 좋은 카페라서 집이랑 좀 멀어도 시간 나면 가게 됩니다🥰', 44, 7, 'GOOD', SYSTIMESTAMP);
