INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '써니데이 인 잔다리'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '혼자 와서 기분 좋게 작업하다 맛있는 샌드위치랑 커피 먹으며 기분 전환하고 가는 곳이에요! 크래미샌드위치랑 커피 조합이 최고입니다🥰', 73, 15, 'GOOD', SYSTIMESTAMP);
