INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '써니데이 인 잔다리'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '근처에 볼일있어서 왔다가 우연히 들렀어요..! 분위기도 좋고 작업하기 너무 좋을거 같은 카페예요😊 매장도 넓고 쾌적해요~~~ 커피도 맛있어요', 47, 9, 'GOOD', SYSTIMESTAMP);
