INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '써니데이 인 잔다리'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '직원 언니가 빵이랑 크림 용기에 아기자기한 그림들을 그려두시는게 너무 귀여워요! 오늘은 무슨 그림 있을까 기대하면서 가는 재미가 있답니다🥹🥹 그리고 카페가 햇살 좋은 날에 가면 너무 예뻐요! 통창이라 카페 내부가 엄청 화사해지는데 감성이 미쳤습니다. 사람 없는 날은 카공하기에도 너무 좋아요. 자리도 많고 무엇보다 책상이 넓은게 정말 편해요!! 음료는 아직 2 종류만 마셔봤지만....☺️☺️ 크림라떼 진짜 왕맛있습니다. 그리고 우유빵이 진짜 완전 맛있으니 꼭 드셔주세요!!', 46, 1, 'GOOD', SYSTIMESTAMP);
