INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '써니데이 인 잔다리'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '잔잔한 분위기 노래 선곡도 좋고 콘센트도 많아서 작업.공부 하기 좋은 거 같아요 차분히 대화하기도 좋은 듯 합니다! 샌드위치 구매시 아메리카노 할인되는 것도 너무 좋은 거 같아요!!', 8, 4, 'GOOD', SYSTIMESTAMP);
