INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '합정에서 테이크아웃 매장일때 부터 이용했는데 이후에는 백화점 팝업으로 이용하다가 카페에는 처음와요! 음악이고 매장 인테리어고 분위기고 너무 예쁩니다! 맛도 변함없이 고급지고 맛나용 옛날에 있었던 딸기우유맛 츄이쿠키도 생각나요 최고최고 자주오겠읍니다 번창하세용', 74, 17, 'GOOD', SYSTIMESTAMP);
