INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '무화과 푸딩이 나왔다는데 안 먹어볼수 없잖아요,,🤩 치즈케잌은 예상가능한 맛이지만 무화과가 가득 들어서 달고 맛있었어요!! 멀어서 자주는 못가지만 갈때마다 맛과 분위기 그대로여서 넘 좋은 코코로카라💖', 100, 19, 'GOOD', SYSTIMESTAMP);
