INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '너무 궁금했던 코코로카라 본점 방문했어요! 매장 이용시 1인1음료 필수라 아아주문했는데 무난하게 마시기 좋았어요. 그릭모모 추천을 넘 많이 받아서 요걸로 골랐는데, 크림치즈의 부드러운 매력에 환장하시는 분들 드셔보시는 것 추천! 크림치즈 특유의 부드러움이 매우 잘 살아있고 물복이 너무 맛있게 들어있어서 복숭아 원없이 먹은 느낌이에요 ㅎㅎ 사실 전 브레드푸딩이 생소한 편이라 엄~청난 맛이다!! 까진 못느꼈지만 혼자서 완.푸 가볍게 했어용 마카다미아 브리틀 포장해서 친언니 선물했는데 당충전에 제격이라고 맛있어하더군요! 담에 다른 메뉴도 도전해볼 의향있어요 ㅎㅎ', 66, 12, 'GOOD', SYSTIMESTAMP);
