INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '퇴근하고 정처없이 떠돌다가 갑자기 단게 땡겨서 찾아 본 카페 굉장히 특이하고 맛있어보이는 메뉴를 보고 홀린 듯 도착한 이곳…!!! 진짜 너무 예쁜 매장과 디저트들에 감탄하고 포장해서 나왔습니다👍🏻 다음엔 여자친구와 방문해서 맛있고 좋은시간 보낼려구요!!', 21, 10, 'GOOD', SYSTIMESTAMP);
