INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '더현대에서 처음 먹었을때 너무 맛있어서, 이번엔 매장 방문했습니다.ᐟ 매장도 넓고, 주택으로 되어있어서 앤틱한 느낌이 들어서 너무 이뻤어요.✨ 디저트랑 음료도 너무 맛있고, 잘 어울려요.ᐟ 커피 못마시는데 논커피로 되어있는 음료도 많아서 좋았어요~ 담에 다른 푸딩 먹으러 또 오려구요🩷🤍', 90, 12, 'GOOD', SYSTIMESTAMP);
