INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '진짜 코코로 카라 사랑해서 기절할꺼같아요 한달에 무조건 2-3번? 많으면 5번도 오는 제가 죽기전에 먹고싶은 디저트 1위랍니다,, 널리널리 알려져서 사장님 돈 많이 벌어서 더더더ㅓ덛 맛있는거 많이 내주셨으면 좋겠어요 코코로카라 사랑해요💗🩵', 13, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '진짜 맛있어요... 호불호 갈린다길래 메뉴 하나 시켰는데 너무 맛있어서 바로 하나 더 시킴. 진짜 꾸덕해서 케이크보다 더 맛있더라고요ㅜㅠ 오길 잘 했다고 느꼈습니다. 미쯔말차가 유명한거 같은데 전 시즌 메뉴인 무화과치즈케익이 더 좋았고 친구는 미쯔말차가 더 좋대요!', 3, 8, 'GOOD', SYSTIMESTAMP);
