INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '단독주택st의 매장이라 좌석이 넓어요! 그리고 시즌마다 푸딩이 바뀌는데 정말 맛있습니다. 그리고 디카페인변경에 추가금이 안붙어서 너무 좋아요', 107, 19, 'GOOD', SYSTIMESTAMP);
