INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '언제나 맛있는 브레드푸딩입니다 ㅠㅠ🫶 커피도 맛있어요! 올 때마다 무슨 맛 먹을지 고르는 재미가 있어요. 시즌 메뉴들도 특별해서 좋습니다.', 9, 7, 'GOOD', SYSTIMESTAMP);
