INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '항상 포장으로 선물했어서 매장에서 먹는 건 처음이네요! 2층에 좌석도 넓게 많아서 편하게 잘 쉬고 잘 먹고 갑미댱~ 마카다미아 푸딩 매번 가을쯤 잘 먹고있어요 ㅎ꙼̈ㅎ꙼̈ 짱맛탱구링~~🤎😋', 66, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '친구가 맛있다고 추천해준 푸딩집🍮에 방문했습니다! 푸딩인줄 알았는데 푸딩 케이크라니!!! 분위기도 넘 좋고 매장 디자인 자체도 넘 귀여워서 마음에 쏙 들었습니닷!! 친구가 가장 맛나다고 추천해준 미쯔말차!! 진~한 초콜릿과 녹차향이 가득해서 맘에 쏘~옥 들었습니닷!!🔥', 25, 10, 'GOOD', SYSTIMESTAMP);
