INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '푸딩의 성지로 유명한 코코로카라 예전엔 푸딩 하나 사도 감격이었는데 종류가 와바박 늘어서 너무 행복했습니다 시즌메뉴는 꼭 드셔보십시오ㅠㅠ감동이니까요', 29, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '저번주에 방문했는데 다른맛도 먹고싶어서 또 왔어요! 커피는 약간 산미가있고 푸딩은 다 맛있는 거 같아요! 또 와서 다른맛도 먹어보려고요! 사진도 잘나와서 사진도 다른 옷으로 찍으러 또 왔어요! 매장도 시원합니다!', 78, 18, 'GOOD', SYSTIMESTAMP);
