INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '무화과랑 복숭아 시즌 끝나기전에 후다닥 다녀왔어요 웨이팅없이 방문했고 푸딩맛은 말해줘헤요~!! 직원분도 너무 친절하셨고 종류도 많았어요!! 다들 여기오면 꼭 방문해보세요!!', 65, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '이거먹으러 홍대 찾아외도 될정도로 맛있어요! 엄청 달지는 않고 꾸덕하니 깊이감있고 쫀득하니 촉촉한게 식감이 좋아요 꽉꽉 담겨있고 복숭아도 엄청 많이 들어있어요 예쁘고 맛있고 다하는 카페에요 ㅎㅎ 디카페인도 있어서 저멱에도 부담없구요 2층 올라갈 때 조심해야하는거 말고는 괜찮아요 2층에 화장실 있어요!', 23, 2, 'GOOD', SYSTIMESTAMP);
