INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '같이 갔던 일행이 또 먹고싶다고해서 이틀연속 방문! 미쯔말차 최고예용 계속 생각나는맛.. 집에 포장해가서 얼려먹었는데 존맛! 레몬딜버터 맛도 너무 특별하고 복숭아도 굿입니다', 7, 3, 'GOOD', SYSTIMESTAMP);
