INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '최애 코코로카라 초당옥수수 아웃되기전에 왔는데 안먹었으면 큰일날뻔 ㅋ 진짜 너무 맛나요…. 앞으로 더더더 맛있는 맛 만들어주세요…..', 29, 2, 'GOOD', SYSTIMESTAMP);
