INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '브레드 푸딩 성지 코코로카라!! 근처 올 일이 있어 드디어 방문해봤어요! 황치즈를 좋아해서 치즈팝을 주문할까하다가 시즌 메뉴 초당 옥수수로 픽!🌽 콘 크런치를 함께 주시는데 초당옥수수의 아삭함 + 콘크런치의 바삭함 + 크림의 부드러움 + 빵의 치덕함 + 카라멜 소스? 스러운 소스의 식감까지 너무 조화로웠어요! 그냥 푸딩만 먹기엔 달게 느껴질 수 있는데 아니 여기 커피 맛집이네요?? 아메리카노와의 조화가 굳!! 사실 푸딩만 하나 먹고 가고싶었는데 매장 이용시 1음료 필수라 시킨 아메리카노가 맛이 있어서 좋았습니다☺️ 꼬소함 + 달달함 + 약간의 솔티함 + 초당옥수수 상큼함이 더해져서 하나 순삭 했어요오,,, 생각만큼 느끼하지 않고 디저트로 딱이라 추천합니당!!', 42, 4, 'GOOD', SYSTIMESTAMP);
