INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), 'N번째오는 진짜 좋아하는 곳 때되면 메뉴 바꾸셔서 질리지도 않고 오게되는곳 인테리어도 아기자기 귀여워서 커피한잔이랑 푸딩 먹고가기 딱 좋아요 직원분들 너무 친절하시고 제 제일 애정메뉴는 마카다미아 브리틀!!!', 55, 18, 'GOOD', SYSTIMESTAMP);
