INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '레몬딜버터 푸딩, 디카페인 아이스 아메리카노 주문했습니다! 친구는 달다고 했는데 저는 맛있게 잘 먹었어요 ㅎㅎ 빵이랑 크림이 같이 들어있는 푸딩입니다🧁 가게 인테리어도 외국느낌나고 분위기 좋았어요!', 36, 1, 'GOOD', SYSTIMESTAMP);
