INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '친구가 너무너므 맛있다고 추천해줘서 방문했어요!! 소문대로 너무너무 맛있어서 다음에 또 오고 싶습니다 😭 시즌메뉴가 곧 있으면 없어진다니.. 넘 아쉬워요 !!!', 23, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '애정하는 코코로카라...🥹 브레드푸딩 세상에서 제일 맛있는 곳! 올 때마다 다른 맛 먹고있는데 이번 치즈팝도 단짠단짠 너무 맛있어요ㅠㅠ 우리집 앞이었으면 1일1푸 했을텐데.. 아쉬운 맘입니당,,🥰', 15, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '푸딩으로 유명하다고해서 왔는데 미쯔말차가 제취향이 아니라 별로였는지 아니면 푸딩 자체가 제취향이랑 안맞는지 확인하기위해 믿고먹는 초코종류를 하나더 먹어봐야겠네요 진한 말차의 맛도 약하고 전형적인 푸딩특유의 부드러움도 없으며 초코가 쿠엔크아이스크림에 들어있는 종류의 초코가 들어가 있어서 아쉽네요 리뷰로 주는 러스크를 먹고나서 티케이크나 마들렌 맛집일수도 있겠다는 생각을 했는데 두바이초콜렛 티케이크를 먹어보고 확신으로 바뀌었습니다 여기 초콜렛 완급조절 잘하네요 찐한 초코맛에 적당한 단맛, 고소함 듬뿍넣은  피스타치오 크림과 바삭한 식감의 카다이프 면이 조화를 이룹니다 푸딩은 과연 어떨지 다시한번 도전해봐야겠어요', 24, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '시즌 메뉴 무화과가 달다고 해서 찾아왔습니다. 그런데 얼그레이 마들렌이 너무 맛있게 생겨서 같이 데려와부렸습니다. 맛있게 잘먹을게요!', 71, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '홍대에 유명한 카페가 있어서 찾아왔어요! 카페 밖에 포토존이 있고 매장 안에서도 아무데서나 찍어도 사진이 잘나와요! 직원분들 완전 친절하세요! 그릭모모도 복숭아 좋아해서 이걸로 골랐는데 완전 부드러워요! 한번 오셔서 드셔보세요!!', 35, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '너무 와보고 싶었던 코코로카라 드디어 다녀왔어요~! 주택형이라 분위기도 너무 아늑하고 시즌인 그릭모모랑 레몬딜버터 푸딩 구매했는데 푸딩도 맛있을 것 같아요 🥹', 24, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '코코로카라 넘 좋아해서 오랜만에 왔어용 무화과를 못사서 아쉽지만 .. 담에 다시 오겠슴다 친절하시고 넘 조아여 ㅎㅎㅎ 가게도 넘 예뿜 ㅠ', 38, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '애정하는 코코로카라! 엄청 꾸덕한 푸딩인데 맛이 찌인하고 묵직해서 무엇을 골라도 너무 맛있어요!!  커피맛도 호불호 없는 맛이라서 푸딩이랑 같이 먹기에도 좋아요~', 32, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '래몬 딜버터 시켰는데 살짝 콤콤하고 탄산감?이랑 과일발효되면 느껴지는 그런 맛이 났어요..🥹 앞으론 먹는것만 먹는걸루.... !', 45, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '그릭모모 시즌 끝이라 들렀어요! 마음같아선 더 사고싶었는데 ㅜ.ㅜ 귀찮아도 또와서 사는게 더 맛있겠더라구용 항상 맛있는 디저트 만들어주셔서 감사합니다 ㅎㅎ', 12, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '🍰디저트, 빵들의 성지! 연남동에 방문하셨다면 여긴 꼭 들리셔야죠 :) 브레드푸딩과 티케이크가 맛도리 늘 백화점 팝업과 빵택배로만 접하다가 매장 방문은 처음이었는데 후기로 봤던 것 보다 훨씬 더 인테리어가 예쁘고 동화속에 온듯한 비주얼이었어요🩷👑 신메뉴 🍑그릭모모 브레드푸딩 영접 ~ 산미 없는 그릭과 파삭하게 씹히는 요거트 볼 토핑이 아주 맛있고 신비 복숭아로 만들어 달달하니 과일 별로 안좋아하는 분들도 맛있게 드실 맛 ! 두바이초코 티케익도 도전해봤는데, 왜 티케이크 이제야 먹은거죠 저..? 쫀쫀한 휘낭시에랑 부드러운 마들렌 그 사이의 식감으로 그냥 맛있다밖에🙊 두바이 디저트 아직 안드셔보셨다면 덜 부담스러운 코코로카라에서 티케이크로 도전해보세용 :)', 27, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
