INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '두바이초콜릿티케이크 대합격합니다. 너무 달지 않고 되게 꾸덕하고 진한 맛이에요! 반 자를 때부터 카다이프?의 바작 거리는 소리가 합격이었는데 (한 입 더 먹고옴) 과하게 달지 않으니까 쉬지않고 들어가네요ㅋㅋㅋ 리치 캐모마일 티 따뜻한것도 맛있어요! 향이 아주 좋습니다 캐모마일은 티백인데 안에 아주 작은 미니미 과일같은것도 넣어주셔서 보기에도 예뻐요. 루이보스티는 캐러멜 향이 확 납니다:) 디저트랑 같이 마시기 딱 좋아요!', 30, 1, 'GOOD', SYSTIMESTAMP);
