INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '무슨 말이 필요한가요… 브레드 푸딩을 좋아한다면 그냥 오셔도 됩니다. 고민은 무슨 맛을 먹을까하는 고민뿐… 근데 뭘 먹어도 진짜 맛도리보장해요…', 70, 11, 'GOOD', SYSTIMESTAMP);
