INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '몇년전부터 우연히 알게되어 찾아온 코코로카라.. 홍대에 올일이 거의 없어서 몇년만에 왔는데 홍대 올때마다 꼭 들리는 맛집입니다 다들 들려서 제발 한번만 먹어보세요 디저트 싫어하는데 이집건 너무맛있어요 ㅠㅠㅠ❤️❤️❤️❤️', 27, 8, 'GOOD', SYSTIMESTAMP);
