INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '푸딩 맛집으로 유명해서 전부터 와보고 싶었는데 근처 올 일 있어서 바로 달려왔습니다~ 매장에서 커피랑 밤말차케이크 먼저 먹어봤는데 케이크 말차 진한맛 너무 맛있고 커피도 맛있어요! 일반 아메 말고 디카페인 아아는 약간 산미가 있는편이네요! 푸딩 종류가 많아서 뭐 사갈지 넘 고민되는데 평일 오후 2시기준 재고 넉넉해서 좋네요 :)', 85, 13, 'GOOD', SYSTIMESTAMP);
