INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '예전부터 너무 와보고 싶었던 곳인데 드디어 방문했네요.! 바나나 먹고싶었는데 시즌 메뉴라 그리모모 주문했어요. 너무 상큼하고 많이 달지 않아서 맛있어요. 디카페인 아메리카노도 맛있네요. 말도 안돼는 날씨에 걸어올만한 카페입니다.!', 10, 6, 'GOOD', SYSTIMESTAMP);
