INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '말차미쯔가 제일 유명한것 같아서 주문했어요~ 약간 씁쓸하면서 초코맛도 나서 맛있네요 엄청나게 단맛은 아니에요!! 가게도 넘 이뻐요 선선해지면 야외테이블에 앉아서 먹으면 좋을것같아요🥰', 14, 2, 'GOOD', SYSTIMESTAMP);
