INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '또또또또간집 코코로카라! 시즌메뉴가 있어서 매번 뭘 먹을지 고민하게 돼요 무화과랑 복숭아 고민하다가 복숭아 먹었는데 역시 맛있어요!! 얼그레이 티케이크도 진짜 꾸덕하고 얼그레이 향 제대로라서 진짜 맛있고, 디카페인 아아고 맛있어요', 32, 10, 'GOOD', SYSTIMESTAMP);
