INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '오랜만에 방문한 코코로카라! 매장 분위기 포근하니 너무 좋고 들어가자마자 퍼지는 달큰한 향기가 아주 기분좋게 해주네요ㅎㅎ 오랜만에 방문해서 많이 변했는데 맛은 더 맛있어졌어요! 시즌 메뉴도 생겨서 다른 시즌 메뉴 정복하러 또 오겠습니다~', 15, 3, 'GOOD', SYSTIMESTAMP);
