INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '분위기가 아기자기하고 빈티지해서 소꿉놀이 하는 동화속에 들어온 것 같아요 시그니처 푸딩인 바나나오레오 먹었어요 꾸덕꾸덕하고 달달해서 무조건 음료랑 같이 먹어야 할 것 같아요', 47, 2, 'GOOD', SYSTIMESTAMP);
