INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '푸딩으로 유명한 코코로카라 방문했어요!!! 좋아하는 유튜버들도 많이 먹고 워낙 맛있다고 해서 궁금했는데 드디어 먹네요🥹🥹 미쯔말차맛 마지막 남은 거 사서 너무 좋아요ㅎㅎ', 25, 2, NULL, SYSTIMESTAMP);
