INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '배만 안불렀어도 진짜 다 먹을텐데요.. 브레드푸딩 너무 맛있고 부드러워요! 미쯔말차여서 말차맛 초코맛 다 나서 좋았고 밤말차는 말차맛이 더 진한데다 밤의 고소달달함도 좋았어요!', 69, 11, NULL, SYSTIMESTAMP);
