INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '예전부터 고민만 하다 드디어 방문했는데 너무 맛있어요ㅠㅠ 두바이 푸딩은 아쉽게 시즌이 아니라고 하셔서 못 먹었지만 대신 두바이 티케이크를 먹었어요! 달달하니 당 충전 제대로 하고 갑니다... 바나나오레오 푸딩도 진짜 맛있었는데 다음 일정 때문에 다 못 먹고 간 게 아쉽네요ㅠㅠㅜ 무화과 시즌 끝나기 전에 다시 와서 꼭 무화과 푸딩도 먹어볼게요!!!', 48, 10, NULL, SYSTIMESTAMP);
