INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '이미 너무 유명해진 코코로카라! 몇 년 전부터 푸딩 먹고 싶으면 방문 하던 곳이네요 망고 새로 나와 먹고 싶어 방문했습니다. 여전히 매장 너무 이쁘고 귀엽네 ㅎㅎ 달달 망고에 부드러운 크림이 합쳐져 너무너무 맛있어요ㅠ 또 먹으로 갈거예요!', 19, 7, NULL, SYSTIMESTAMP);
