INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '여기 푸딩은 주기적으로 생각나요!! 제 최애는 말차입니다😍😍 이번에 2층 처음 가봤는데 자리 정말 넓고 좋네요ㅎㅎ 또 올 거예요!!', 105, 23, NULL, SYSTIMESTAMP);
