INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '제철푸딩 맛집  평소 말차푸딩이 최애인데 무화과철을 맞아 무화과로 ~~ 당도최고 맛도 넘 좋고 주택을 개조해 만든 인테리어도 넘넘 맘에 든다.', 53, 17, NULL, SYSTIMESTAMP);
