INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '내부가 너무 귀엽구 푸딩 종류도 많아서 너무 좋아요!! 패키징도 너무 제 스타일이고 맨날 와보고 싶었는데 드디어 방문 완료 !! 직원분도 너무 친절하셔요 💘', 19, 9, NULL, SYSTIMESTAMP);
