INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '거의 20번 넘게 방문 한 코코로😽 군데 항상 포장 해서 매장에서는 처음 먹어봐용ㅎㅎ 티팟이 너무 귀여워용!! 초당 옥수수 푸딩이 작년보다 훨씬 초!당! 맛이 잘 느껴지고 적절한 단짠의 조화가 최고입니당🌽💛 마카다미아 다시 나왔더라구요ㅠㅠ🤎 진짜 기다렸어여ㅠ 레몬딜 푸딩도 상큼해서 여름에 생각나는 맛🍋🍃', 28, 6, NULL, SYSTIMESTAMP);
