INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '여기 처음 오는 바나나 푸딩 무화과 푸딩 가게인데 너무 느낌도 좋고 맛있을 거 같아요. 포장도 해서 자리도 넓고 엄청 좋아요 ㅎㅎ', 94, 19, NULL, SYSTIMESTAMP);
