INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '어제 더현대 가서 먹어보고 넘 맛있어서 오늘 바로 와봤어요!! 개인적으로 레몬딜버터 진짜 강추합니다!!! 그리고 생각보다 양도 많아서 좋았어요ㅎㅎ', 14, 9, NULL, SYSTIMESTAMP);
