INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '친구랑 연남동 놀러와서 코코로카라 브레드푸딩 먹고 싶어서 들렸어요! 레몬딜버터는 처음 먹어보는데 상큼한 레몬 치즈케이크? 느낌이었어요. 맛있네요. 같이 시킨 화이트 리치도 안에 화이트 펄과 리치 캐모마일의 조화가 잘어우러져 맛있었어요!', 14, 9, 'GOOD', SYSTIMESTAMP);
