INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '용산에서 말차맛 먹고 넘 맛있어서 다른 맛도 먹어보려고 연남 오는 김에 왔어요!! 여전히 너무 맛있고 친절하셔서 좋아요 🥹💞💞', 18, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '코코로카라 꼭 한번 먹어보고 싶어서 방문! 여름 시즌이라 초당옥수수맛으로 선택☺ 푸딩 섞인 케이크같아요/ 퍼묵 케잌 느낌~!! 아메리카노 고소해서 푸딩이랑 조합이 어울려요~~ 옥수수 토핑 뿌려먹으니까 오도독 씹어서 식감 좋고 맛도 최고입니다 추천해용~~', 39, 1, 'GOOD', SYSTIMESTAMP);
