INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '💰바나나오레오푸딩(7,300원) 아메리카노(4,500원) 카페가 너무 예뻐요~!! 아기자기하게 인테리어 잘해놓으셨더라구용😚 바나나오레오푸딩 먹었는데, 많이 달지 않고 진짜 맛있더라구요!! 아아랑도 잘어울려요👍 다른 맛 푸딩도 먹어보고 싶네요 ㅎㅅㅎ', 3, 6, 'GOOD', SYSTIMESTAMP);
