INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '평소에도 코코로카라 바나나푸딩빵을 좋아해서 가봤습니다. 오레오 바나나푸딩도 맛있었어요! 인테리어도 이쁩니다. 카페가 디저트도 만큼 이쁜만큼 사람들도 많네요 ㅎㅎ', 130, 23, 'GOOD', SYSTIMESTAMP);
