INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '예전에 들려서 사갔던  코코로카라 푸딩 맛을 못 잊어서 서울 여행오면서 비 오는 날에도 들렸습니다☔️🌧 시즌 푸딩인 그릭 모모가 엄청 기대됩니다. 코코로카라니까 당연히 맛있겠죵ㅎㅎㅎ 보냉포장도 있어서 여름에도 걱정 없이 포장해갑니당', 9, 2, 'GOOD', SYSTIMESTAMP);
