INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '망고푸딩 나왔길래 당장 달려갔다옴🥭 진한 망고맛 푸딩에 새콤한 패션후르츠 한방울 첨가된 맛ㅎㅎ 찐과일맛이라 너무 맛있구 안에도 망고 많이 들어가서 넘 좋아요ㅠㅠ 치즈케이크랑 코코넛젤리도 넘 잘 어울립니당… 요거트 좋아하시면 얼망고! 싫으면 아프지망고 강추!! 레몬 블루베리는 상큼할 줄 알았는데 생각보다 달달한 편이네요! 레몬의 새콤한 맛을 기대했어서 제 취향은 아니었지만 그래도 맛있었어용><', 15, 2, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '매번 팝업스토어에서 구매하고 먹다가 본점에 처음으로 방문했는데 너무 예뿌고 아늑해요🥺🩷 저 맛별로 다 먹어봤는데 말복 좋아하는 저는 역시나 그릭모모가 젤로 맛있어요🍑💕🫧 오래오래 해주세용ㅎㅎ', 2, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '친구가 넘넘 좋아하는 집이라 왕추천 받아서 왔는데...!! 좋아하는 이유를 넘 알겠어요☺️ 인테리어도 근사하고, 직원 분들이 왕 친절하십니다🌷 물론 디저트 맛있는 건 두말하면 잔소리입니다🤭 푸딩 종류가 많아서 한참 고민하다가 결국 메뉴 월드컵 해서 겨우 하나로 추렸어요🥹 시그니처 메뉴 중 하나인 바나나 오레오로 결정!!! 쿠앤크 느낌보다는 초코쿠키!! 브라우니!! 요런 느낌이라 바나나 푸딩 크림이랑 넘 잘 어울려요🤤 1층에도 자리가 몇 좌석 있고, 2층으로 올라오면 두 세개 방에 4인/6인 테이블도 있어요!! 1층 자리가 다 찼더라도 2층으로 얼른 올라오세요😉 계단 턱이 살짝 높은 편이라, 음료 주문하면 직원 분들이 내어주실 때 조심하시라고 안내해주셔요. 왕 친절〰️ 다음에는 또 다른 맛 먹으러 올게요🌷', 42, 1, 'GOOD', SYSTIMESTAMP);
