INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '가끔 팝업이나 인스타로만 보던 코코로카라 본점 처음 방문해봐요... >< 전 종류 보고 느긋하게 고를 수 있는 것도 너무 좋고 다들 엄청 친절하셔요ㅜㅜ 오늘은 포장해가지만 담엔 먹고가고 싶을 정도로 분위기도 좋습니당 ㅎㅎ 믿고먹는 코코로 브레드퓨딩 ... !!!', 8, 7, 'GOOD', SYSTIMESTAMP);
