INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '무화과 치즈케이크 푸딩을 먹었어요!! 부드러운 치즈 풍미에 달콤한 무화과가 어우러져 정말 맛있었고, 주택을 개조한 듯한 빈티지한 공간 덕분에 분위기까지 완벽했어요~😋💕', 10, 0, 'GOOD', SYSTIMESTAMP);
