INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '코코로카라는 빵순이의 홍대 방앗간입니당🥰 남자친구랑 처음 같이 왔는데 남자친구도 꼭 조아하면 좋게또요! 오늘은 남친 덕분에 빵력자랑대회 와서 그릭 모모 새로나온맛 5프로 할인받아 삿어요>,< 기대돼요💕', 81, 16, 'GOOD', SYSTIMESTAMP);
