INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '언제 먹어도 맛있는 코코로카라! 전메뉴가 다 맛있구요 지점마다 차이도 없이 다~맛있습니다 남자친구기 그릭모모 좋아해서 매번 시즌맞춰 챙겨먹고 있어요~', 43, 6, NULL, SYSTIMESTAMP);
