INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '애정하는 코코로카라..✨매장에서는 처음 먹어봤는데 아메리카노 너무 맛있었어요 ㅎㅎ 디카페인으로 바꿀 수 있어서 더 좋았답니당 두바이 초콜릿 푸딩은 처음 먹어보는데 가격이 좀,, 비싸긴 하지만 너어어무 맛있었어요! 원물맛 너무 고소하고 카다이프도 가득 들어있고 초코랑 피스타치오 뭐 하나 강하지 않고 조화가 최고였답니당 ㅎㅎ 역시 믿고먹는 코코로카라💚 아 그리고 혼자 2층으로 올라가려고 트레이 들고 나가려는데 예쁘신 직원분이 문도 열어주셨어요,, 감동🥹', 24, 10, 'GOOD', SYSTIMESTAMP);
