INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '여자친구와 홍대 데이트로 다녀왔어요 두바이초콜릿푸딩이랑 레몬유자 마들렌 시켰어요 두바이초콜릿푸딩은 가격은 다른 푸딩보다 비싸지만 충분히 매력적인 맛이니 추천이에요! 원래는 푸딩 2가지 맛을 먹고 싶었는데 1인 1음료 주문이 필수라서 푸딩은 하나만 먹게 되었네요 밀크티랑 바닐라라떼도 디저트랑 잘 어울렸어요 네이버 영수증 리뷰 이벤트도 진행중이에요!', 49, 10, 'GOOD', SYSTIMESTAMP);
