INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '발로나 초코 푸딩 먹었는데 초코 엄청 진하고 꾸덕하고 맛있었습니다! 초코칩도 사이사이 씹히고 좋았는데 금방 질리긴 해요..ㅎㅎ', 35, 8, 'GOOD', SYSTIMESTAMP);
