INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '메뉴 하나씩 뽀개러 오는 재미가 있는 코코로카라 시즌메뉴 무화과과 새로 나왔더라구요 냉동 후 먹을 거라 다른 걸 사긴 했지만 시즌 신메뉴라 담엔 꼭 먹어보려구요 어떤 걸 먹어도 맛이 보장되어있는 코코로카라입니다💕', 36, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '저번에 황치즈 푸딩 먹고 맛있어서 또 왔는데 시즌제 허걱 ㄷㄷ 이번달에는 할지말지 모른다고 하시네요...ㅠ 찾으시는분은 용산점에 있다고 하니 한 번 가보세요! 저희는 아쉬운 마음에 말차랑 마카다미아로 했습니다. 역시나 얘들도 맛있네요 ㅎㅎ 분위기도 감성도 좋은 데이트 명소 코코로카라~!', 66, 12, 'GOOD', SYSTIMESTAMP);
