INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '정말 맛있고 밸런스가 정말 좋아요! 초당옥수수가 아삭아삭하니 너무 맛있고 적당히 달아서 기분이 좋아요 식감도 너무 좋습니다 여름의 맛이네요!', 24, 2, 'GOOD', SYSTIMESTAMP);
