INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '무화과 디저트와 피스타치오 조합이 너무 맛있어요! 중간마다 카다이프? 같은 것도 씹이는게 조화가 좋구, 카페 분위기도 좋아요 다른 디저트들도 또 먹으러 올려구요ㅎㅎ🥹🥹❤️❤️', 10, 7, 'GOOD', SYSTIMESTAMP);
