INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '저의 완전 또또또간집인데여ㅎㅎ 오랜만에 방문해도 너무 맛난 푸딩들이 반겨줘 기분 좋고 좋은 시간 보내고 갑니다ㅎㅎ 가게 내부 인테리어도 너무 예뻐요!', 5, 4, 'GOOD', SYSTIMESTAMP);
