INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '항상 궁금했던 곳이였는데 빈티지한 분위기의 가게 인테리어가 무척 취향이었어요. 어딜 찍어도 사진이 예쁘게 나와서 행복한💛 푸딩과 티케이크 등 디저트 종류도 다양한데 보기에도 예쁘고 달달하니 디저트의 정석 느낌. 커피는 아메리카노 주문했는데 적당히 산미 있고 고소하니 커피마저 제 취향이었어요.. 다음에는 친구들도 데리고 또 올거에요 무조건!!🥹', 0, 7, 'GOOD', SYSTIMESTAMP);
