INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '맛있어요.^^ 홍대 디저트 맛집이에요. 여기 그릭모모 좋아하는데 판매하고 있어서 사러왔어요. 코코로카라 홍대오시면 한번 먹어러 가보세요.👍💕', 44, 0, 'GOOD', SYSTIMESTAMP);
