INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '바나나푸딩이 제 최애픽인데ㅠㅠ 저녁이 방문하니까 확실히 다 솔드아웃이더라구요ㅜ 역시 푸딩원조집다워용ㅠ 그래도 덕분에 시즌메뉴인 애플청포도 먹었는데 이거도 존맛이었습니다ㅜ 다음엔 낮에와서 한 열개 쟁여가야겠어요', 3, 6, 'GOOD', SYSTIMESTAMP);
