INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '예전부터 봐왔던 코코로카라를 매장처음와봤습니다 ㅎㅎ듣던대로 인테리어 너무예쁘고요 이분위기 너무좋네요~~~티케이크 두바이 궁금해사 사봤구오 미쯔말차는 예전에도 먹어봐서 ! 믿먹이에요 ㅎㅎㅎ🤭💞', 73, 12, 'GOOD', SYSTIMESTAMP);
