INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '코코로카라는 다양한 맛의 브레드 푸딩과 구움과자를 팔고있는 곳인데요! 모든 메뉴들이 특색있고 맛있었습니다 매장은 단독주택을 개조한 아늑한 분위기이고 사진도 잘 나옵니다:) 또 매장과 화장실도 깨끗하고 직원분들도 다 친절하셔서 머물기 좋았습니다! 디저트 별로 안좋아하는 친구도 좋아했어서 추천합니다!', 40, 4, 'GOOD', SYSTIMESTAMP);
