INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '옛날부터 유명한 건 알고 있었는데 홍대 근처 올 일이 없어서 맨날 지켜보기만 햇던 케이크 푸딩.... 제 최애 해쭈와 박명수님도 모두 칭찬햇던 그맛! 세 가지 메뉴 기쁘게 골라갑니당! 분위기도 넘 조와요ㅠㅠ', 9, 7, 'GOOD', SYSTIMESTAMP);
