INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '떠먹는 푸딩이 궁금해서 방문했는데 종류가 엄청 많더라고요!! 고민끝에 미쯔말차 골랐는데 진한말차 크림에 달달한 초코가 잘 어울려서 맛있네요 크림이 하나도 안 느끼해요ㅎㅎ 다른맛들도 먹어보고 싶어요~', 130, 19, 'GOOD', SYSTIMESTAMP);
