INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '처음 와본 곳인데  손님 진짜  많네요~ (사실 유명한줄 모르고 와서^^) 첨 먹어보는 푸딩케이크 진짜 맛있구^^ 너무 달지 않아서 또 생각나는 맛이예요~ 손님 많은 이유 알겠더라구요^^ 아기자기한 인테리어  분위기도 좋고 아늑한 공간도 마음에 들어요^^ 좋은곳 알게되서 기분도 좋네요^^ 같이 온 딸아이도 바나나오레오 맛있게 잘먹었습니다^^', 354, 50, 'GOOD', SYSTIMESTAMP);
