INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '코코로 카라!!뉴욕에서 먹었던 메그놀리아 바나나푸딩이랑 또 다른 매력이네요! 홍대에서 이정도 맛이 날줄이야 이젠 비행기값아껴서 전철타고 여기 와야 겟어요🍌✈️', 70, 17, 'GOOD', SYSTIMESTAMP);
