INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), 'N번째 재방문 중인 연남동 카페 코코로카라! 푸딩이 가장 유명하지만 티케이크도 진짜 맛있고 다른 구움과자들도 다 맛도리니까 꼭 다양하게 드셔보세요! 항상 시즌 메뉴 도전하는데 늘 성공하는 그런 맛집👍 추천합니다!!!', 23, 3, 'GOOD', SYSTIMESTAMP);
