INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '재재재재재재방문한 곳이에요 크림류 안좋아하는 편인데 여긴 정말 너무 맛있어요ㅠㅠ! 원픽 바나나였다가 그릭딸기로 바꼈다가 그릭모모로 바꼈다가 애플청포도로 바꼈다가 그냥 바닐라웨이퍼 베이스는 다 제취향... 너무 맛있어요ㅠㅠㅠ', 15, 8, 'GOOD', SYSTIMESTAMP);
