INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '코코로카라 초코푸딩은 최고..🤎 촉촉꾸덕에 씹히는 초코칩 최고입니다 두바이도 맛있고 얼그레이 마들렌도 진짜 최고.. 연남동에서 디저트 찾는다면 코코로카라 느끼하지 않지만 당충전 제대루!!! 매장도 넓어서 자리가 넉넉해요! 다른 맛도 궁금한데 초코 포기할 수 없다 ㅠㅠ 다음엔 푸딩 두개 먹겠어요..!!', 2, 7, 'GOOD', SYSTIMESTAMP);
