INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '데이트로 방문 했어요! 포장으로 햤지만 매장 분위기 너무 좋고 꼭 와보고싶었던 곳이라 방문했는데 직원분들 다 친절히셔서 기분좋게 구매했습니다!', 69, 11, 'GOOD', SYSTIMESTAMP);
