INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '지방사람인데 서울 왔다가 포장할만한 디저트로 추천받아 방문했습니다! 오후에 갔는데 푸딩들 재고 아직 많이 남아있었고, 비주얼이 너무 맛있어보였어요... 티케이크랑 푸딩 유명한 건 알았지만 마들렌도 넘 이쁘고 맛나보이네용 다음엔 매장에서 친구랑 먹으러 오려고 합니다!', 114, 22, 'GOOD', SYSTIMESTAMP);
