INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '고민 한참하게 만드는 라인업.. 마들렌, 푸딩 종류별로 다 맛있어보인다 레몬딜버터 푸딩 구웃—🍋 이런 디저트는 처음이다! 반면 초당옥수수는 개인적으로 좀 아쉬웠다. 🌽🥲스위트콘 퍼먹 느낌이 강해서,, 다음에 말차 푸딩이랑 등등 다른 푸딩들 먹으러 또 와야지~ 그나저나 카페라떼 갸씀;; 탄원두로 내린듯한 맛이었어요ㅠ', 13, 3, NULL, SYSTIMESTAMP);
