INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '코코로카라 몇년 전부터 알고 이전 매장 방문도 했었고 택배도 시켜먹을 정도로 좋아하는데 오랜만에 서울 온 김에 방문했어요! 특별한 메뉴도 더 많아졌고 코코로카라 푸딩은 다 말모뭘모입니다 짱 맛... ෆ', 83, 12, 'GOOD', SYSTIMESTAMP);
