INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '맛있는 디저트 먹고싶어서 왔어요. 인테리어에 세심하게 신경쓰신게 보여요. 카페 분위기 상콤하니좋아요. 디저트는 물론이고 커피랑 밀크티도 맛나네요. 역시 날좋은날엔 카페에서 보내야되는것같아요. ^^', 21, 7, 'GOOD', SYSTIMESTAMP);
