INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '더워서 점심시간에 잠시 갔는제 인테리어도 너무 예쁘고 음료도 맛있어서 힐링 제대로 했어요! 그리구 남자 직원분 2층가는데 도와주시구 너무너무 친절하셔서 여러모로 카페에 대한 기억이 너무 좋아요 번창하세요✨🫶', 24, 10, 'GOOD', SYSTIMESTAMP);
