INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '친구가 놀러와서 당장 여기부터 데려왔어요!! 포장포함 벌써 세번째 방문입니다😍 너무너무 맛있어요.. 두바이초콜릿은 매일 먹고싶은 맛입미다.', 39, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '그릭 딸기 먹었어요~ 푸딩이라고 생각해서 주문했는데 안에 치즈크림이랑 빵이 들어 있어서 보통 푸딩을 생각하시고 드시면 조금 놀라울 것 같아요 ㅎㅎ 그래도 안에 큰 딸기도 들어 있고 맛있게 냠냠 먹었습니다. 매장 내부가 넘 아기자기해서 2층에 올라가 실 것을 추천해요~친구랑 커플이랑 오는 것을 추천합니다^^', 47, 3, 'GOOD', SYSTIMESTAMP);
