INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '코코로카라 오랜만에 오는데 시즌메뉴도 있고 맛도 많고 결정장애ㅜㅜ 근데 진짜 다맛있어서 아는맛이라 더무서운,, 푸딩은 역시나 안에 내용물도 많고 맛있어요ㅜㅜ 달달한 푸딩케이크,,입에서 살살녹고 또이용할게요 직원분도 친절하고 기분좋아지는 곳이예요👏🏻', 1, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '말차 푸딩 먹어보고싶어서 인스타에서 보고 방문했는데 친절하게 대해주셔서 감사해ㅛ어여 담에 또 오겠습니다 너무 너무 맛있을거같아요!!!!', 11, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '두바이 초콜릿이 먹고 싶어서 다시 왔어요 오늘은 화이트 리치 에이드를 먹었는데 향이 너무 좋고 제 스타일이었어요 다음에 또 올게요 😊😊', 28, 6, 'GOOD', SYSTIMESTAMP);
