INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '유튜버 해쭈님이 여기 갔다온걸 보고 나서 넘 먹고싶어서 방문했어요~ 어떤게 맛있을지 몰라서 제일 많이 팔리는 푸딩 중 하나인 미쯔녹차를 주문했답니다~ 일반적으로 생각하는 푸딩과는 다르게 꾸덕 쫀득 맛있는 푸딩이에요 커피랑 넘 잘어울리네요😀😀', 24, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '커피도 맛있고 무엇보다 푸딩 종류도 많고... 하나하나 다 맛있어요 ㅠㅠ 다음에 또 올거 같아요 카페 내부 인테리어도 너무 예쁩니댜 🩷🩷', 10, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '홍대 오면 꼭 오는 코코로카라 🍀🤍 날씨도 너무 좋은 날에 맛있는 거 먹으니까 너무 행복해요 ꒰ᐡ⸝ɞ̴̶̷ ·̮ ɞ̴̶̷⸝ᐡ꒱ !!!', 36, 7, 'GOOD', SYSTIMESTAMP);
