INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '택배로 받아보던 코코로카라! 매장 방문해서 포장했어요 다양한 푸딩들이 있고 직원들 모두 친절하셔서 빠르게 포장할 수 있었습니다🙂', 92, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '연남동 3번 출구 쪽이 아니라 옆 골목으로 들어가야 있는 위치라 주변 조용하고 주택 개조해서 만든 곳이라 아늑한 분위기였습니다! N번째 먹는 푸딩은 여전히 맛있었고 토요일이라 가장 바쁜 날이라 정신없으실텐데 직원분들도 친절하시고 또 방문 예정입니다💕', 53, 18, 'GOOD', SYSTIMESTAMP);
