INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '매장은 처음 와보는데 데이트하기 좋을 것 같아요! 직원 분이 친절하세요. 티케이크 완전 꾸덕해서 다른 맛도 먹어보고싶어요ㅠㅠㅠ 말차맛이 강하진 않고 밤맛이랑 잘 어울어지는 맛입니다', 220, 80, 'GOOD', SYSTIMESTAMP);
