INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '모든 메뉴가 맛있어서 도장깨기 중이에요💟 미쯔말차는 언제 먹어도 너무너무 맛있었요! 특히 블랙쿠키여서 더 맛있습니댜.. 다들 코코로카라하세요💓', 39, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '✔캐셔 직원의 불친절: 지난번 혼자 방문했을 때도 그렇구.. 너무 세상불만 가득한 표정으로 응대하시는게 불쾌했어요ㅠ 남자친구도 나오면서 왜저러냐구. 많은 사람이 사랑하며 찾는 만큼 더 친절하게 응대해야하지 않나하는 아쉬움이 컸급니다 ️✔️연남동 고퀄리티 디저트카페: 신메뉴 밤말차티케이크도 예상한대로 담백+달달 맛있는 맛이에요. 말차푸딩은 열번정도 먹은듯한 나의 페이보릿. 바나나오레오는 재구매하진 않을 듯하고 오리지널 바나나가 훨 입맛에 맞았어요. 디저트 잘하는 집 코코로!', 27, 5, 'GOOD', SYSTIMESTAMP);
