INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '오늘 너무너무 쿠키가 먹고싶은데 저는 와구와구 들어가있는 쿠키보다 담백하고 간단한 쿠키를 좋아해서 지인한테 물어보고 맛있다고 하여 방문 하였어요 매장은 이용안했고 포장했는데 분위기는 아기자기하고 귀여웠어요 쿠키도 너무너무 원하는거였어서 맛있게 잘 먹었습니다 감사합니다!', 21, 5, 'GOOD', SYSTIMESTAMP);
