INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '주변지나갈일오면 꼭들리게되는 코코로카라^~~칭구들이랑 약속잡기도좋은 넓은 2층두있고 혼자서도 오기좋아서 넘조아용 맛은이제 말모말모 홍대에서 최고카페입니당🌸💕', 4, 4, 'GOOD', SYSTIMESTAMP);
