INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '폭신폭신한 느낌이 맛있어요! 커피두 맛나고 인테리어도 좋아서 잘 머물다 갑니당 ㅎㅎㅎ 얼먹이 맛있다는데 얼먹 해보고싶오요!!❤️', 22, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '코코로카라 더현대에서만 먹어보고 홍대 본점 처음 방문인데 가게 아기자기하고 분위기 너무 좋아요>< 코코로카라 푸딩 역시나 맛있고 마들렌 러스크도 대박 맛있어요….👍👍', 32, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '몇번 온 건지 셀 수가 없어요ㅠㅠㅠ 이번 시즌 메뉴도 뿌시러 왔습니다!! 자리도 꽤 많고 인테리어가 진짜 취적.. 사진은 1층 모습인다 2층에 테이블 많아요!', 129, 20, 'GOOD', SYSTIMESTAMP);
