INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '맛있어요 콜라보한다고 서비스로 받은 초콜릿됴 뿌려먹었는데 짱 맛있습니다. 저는 타로랑 말차 시켰는데 성공적이네요. 벌써 2번째 방문 ☺️', 304, 51, 'GOOD', SYSTIMESTAMP);
