INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '친구들이랑 2차로 방문했습니다! 푸딩도 너무 맛있고 귀여운 인테리어와 소품들이 가득해요ㅎㅎㅎ 시즈널메뉴가 다양해서 너무 좋아용❣️', 87, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '드디어 코코로카라 다녀왓어요! 첫방문이라 바나나랑 딸기피스타치오겟!! 존맛 ㅎ 다음에 다른 맛 먹으러 뜌 올게요! 가게도 크고 뷴위기도 너무 좋아용!!0', 34, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '연남 빵투어의 마지막으로 코코로카라를 방문했어요. 여기저기서 추천도 받고 제 최애 유튜버 뽀니님의 최애 카페여서 너무 궁금했는데 기대 그 이상의 맛집이네요💕 저는 그릭딸기를 먹었는데 요거트의 상큼함과 딸기가 적절하게 어우러져서 순식간에 먹었어요. 이미 빵만 n차 식사 중인데..ㅎㅎ 매장도 너무 아늑해서 즐겁게 먹고 갑니다!', 84, 17, 'GOOD', SYSTIMESTAMP);
