INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '2020년부터 꾸준히 사랑하고 있는 코코로카라예요!! 거의 모든 맛 다 먹어봤는데 정말,,.다 맛있어요ㅠㅠ 티케이크도 쫀득꾸덕 짱이에요!!', 83, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '연남동 살 땐 자주 왔었는데 ㅋㅋㅋ 진짜 디저트 맛집 리스트에 꼭 있어야 되는 코코로카라👍🏻 오늘 처음 먹어보는 딸기 피스타치오, 밤말차티케이크 도전! 딸기 피스타치오는 처음 먹어보는 맛있는 맛! 계속 손이 가는 맛이었다 밤말차는 많이 달지 않고 밤이랑 잘 어울렸다👍🏻 코코로카라 사장님의 도전 정신! 최고! 연남동 오면 무조건 코코로카라☺️', 17, 5, 'GOOD', SYSTIMESTAMP);
