INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '유명한 코코로 카라 이미 유명하지만 들어오니 먹음직스러운 푸딩이 가득합니다 첫 브래드 푸딩이라 더욱 기대되어요 직원분들도 친절하세요 '' ∇ ''', 6, 2, 'GOOD', SYSTIMESTAMP);
