INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '수년 전부터 늘 애정하는 코코로카라.✨ 물가가 올라 그른가 비싼감이 없지않지만 맛은 끝내줍니당ㅎㅎ 사실 지난 여름 옥수수맛 먹었을때 실망했어서 한동안 안먹다가,, 내가 젤 좋아하는 맛으로 골랐고 좋아하는 재료가 들어있어서 한통 한자리에서 댜 비울 수 있어요!! 매장 내부도 아늑해서 머무르기도 좋아보였음ㅎㅎ 더현대에서도 종종 구매하는데 어디든 맛은 좋아 또 먹고싶네용ㅣ', 42, 1, 'GOOD', SYSTIMESTAMP);
