INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '방문은 여러번했는데 리뷰는 처음 남겨요! 여기 매번 시즌메뉴 새로 나오는데 나올때마다 방문 꼭하는 곳이에요❤️‍🔥 바나나푸딩으로 알게 됐는데 다른 메뉴들 너무 맛있어요,, 미쯔말차, 마카다미아, 그릭딸기 등 최애가 너무 많아서 행복합니다 겨울에는 꼭 슈톨렌 먹으러 방문해야되요❤️‍🔥👊', 19, 0, 'GOOD', SYSTIMESTAMP);
