INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '초당옥수수에 계절이 돌아와서 찾아왔습니다! 되게 이쁘게 만들어주셨고, 직원분도 굉장히 착하셨어요! 내년 여름에 또 방문하겠습니다 ㅎㅎ', 94, 25, 'GOOD', SYSTIMESTAMP);
