INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '지금까지 먹은 두바이 메뉴 중에 진짜 제일 맛있어요 카페도 2층까지 있고 자리가 서로 떨어져 있어서 공간도 넉넉해요 음료도 넘 맛있습니다 또 오고싶어요 ㅠㅠ', 5, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '푸딩은 엄청 맛난거는 아니지만 친구가 가보고싶대서 또 와본곳 세명이서 푸딩을 각 한개씩 3개 매장에서 먹겠다고 시켰는데 1인1음료 안하면 매장에서 못먹는데서 음료까지 시켜야한곳 융통성 없어서 다신 안갈듯', 37, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '디저트 이름은 푸딩인데 흔히 생각하는 탱글한 푸딩 보다는 케이크와 더 비슷한 질감입니다. 엄청 맛있어요. 카페도 감성적인 분위기라 데이트하기 좋네요.', 15, 2, 'GOOD', SYSTIMESTAMP);
