INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '꾸덕한 떠먹케하면 전 여기가 1티어라고 생각해요✨✨ 오랜만에 먹어서 그런지 게 눈 감추듯이 흡입했어요! 신메뉴도 좋지만 근본 오브 근본이 최고죠?!', 45, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '푸딩을 사서 집에 까지 오는 거리는 30분 남진 포장안에 너은 아이스팩 이 녹기도 전에 도착했음개봉을 하고 맛을봣는데 바나나 가 상해서 맛이 토할거같음..매장에 문의 할려고 연락 할려니 영수증에 있는 번호..매장 번호가 존재하지 않는 없는 번호 인터넷으로 물어볼라니 매장 영업시간이 아니라고 나옴 카톡에 문의를 하니 답변을 읽지를 않음 반품이 아니더라도 연락처가 정상적으로 존재를 하지않는 까페..음식점 이 있다니 사업자등록증에 연락처가 바뀌면 수정을 해놔야지불법영업도 아닌데 연락처가 없는 번호라 나오면 소비자는 어쩌란 건지', 7, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '가정집을 개조해서 만들어서 그런지 아늑하고 귀염귀염한 인테리어가 너무 좋네요 푸딩도 먹고 싶은 맛은 품절이라서 아쉬웠지만 푸짐하니 맛있어요💜', 38, 7, 'GOOD', SYSTIMESTAMP);
