INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '홍대오면 항상 방문합니다. 다른 메뉴도 맛있지만 역시 시그니처인 바나나는 꼭 포함해서 구매하는것 같아요!!! 오늘도 잘 먹었습니다~', 44, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '첫번째 방문 때는 말차 마들렌을 먹었는데 그것도 엄청 맛있게 먹었어요🍵 그리고 친구들은 푸딩을 먹었는데 진짜 맛있게 먹더라고요 그래서 계속 생각나서 오늘 스트로베리 초콜릿을🍓🍫먹었는데 진짜 맛있어요 춪헌합니다~!!!!!', 15, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '홍대 근처 가면 이제 자동으로 생각나는 이곳 망고 신메뉴가 너무 궁금해서 달려왔어요 예상대로 망고 맛 낭낭하니 맛있어요 앞으로 100번은 더 올게요~', 5, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '그 유명한 코코로카라 드디어 와봤네요! 입에서 살살 녹는 푸딩에 진짜 반했어요! 시즌메뉴도 정말 맛있어요! 택배 이용 가능한것도 너무 좋아요! 무조건 재방문 각', 85, 18, 'GOOD', SYSTIMESTAMP);
