INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '역시 코코로카라는 티케이크 맛집임ㅠㅠ 두바이는 안에 까작한 카다이프 식감이 너무 좋고 마카다미아도 토피랑 캬라멜 들어가서 달달해요! 꾸덕꾸덕한 식감 좋아하시면 무조건 추천!! 피넛 봉봉은 아몬드 봉봉에 피넛버터 들어간 맛인데 전 이게 더 취향이에요ㅎㅎ 초코볼도 맛있고 고소한 피넛버터 들어가서 단짠단짠 그 자체🥜 딸기 오레오는 딸기가 은근 많이 들어있고 당도도 생각보다 많이 안 달아서 좋았어요! 오레오 좋아하면 다들 좋아할 맛입니다ㅎㅎ', 30, 7, 'GOOD', SYSTIMESTAMP);
