INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '친구 추천으로 와 본 곳인데 정말 맛있어용! 메뉴가 너무 다양해서 고민하다가 애플 청포도 푸딩으로 골랐는데 성공적이었습니다ㅎㅎ 2층 뷰도 너무 예뻐서 좋았어요!!', 59, 14, 'GOOD', SYSTIMESTAMP);
