INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '제 홍대 최애 카페입니다💗 여기 푸딩들 자꾸 생각나서 맨날 일부러 홍대까지 찾아와서 먹어요 언제 먹어도 맛있는 곳ㅜㅜ 친구들한테도 홍대 갈거면 여기 꼭 들르라고 추천하고 다녀요!! 분위기도 좋고 인테리어도 예뻐서 사진도 잘 나오는 것 같아요 코코로카라 사랑햌', 51, 17, 'GOOD', SYSTIMESTAMP);
