INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코코로카라'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '코코로카라 처음 방문했을 때 먹었던 메뉴인데 다시 먹어도 넘 맛있네요💕 바나나랑 오레오가 잘 어울어지고 완전 제 취향이에요🥰🖤', 23, 9, 'GOOD', SYSTIMESTAMP);
