INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '오랜만에 에스프레소를 마셨는데,  밸런스가 정말 좋았어요. 실내는 춥지도 덥지도 않아 머물기 편했고, 소음도 크지않아서 조용히 있기 좋았어요. 외국인 손님들도 종종 보였는데 누구에게나 열려 있는 공간이라는 느낌이 들었어요. 혼자 와도, 친구나 가족과 함께 와도 편안하게 즐길 수 있는 감성 카페입니다.^^ 책읽고 작업하기도 최적화입니다♡', 25, 4, 'GOOD', SYSTIMESTAMP);
