INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '지나다가 인테리어가 넘 이뻐서 들어왔는데 파니니랑 스프가 있어서 같이 주문했는데 넘 맛나요. 커피도 맛나도 사장님도 넘 친절하세요^^ 따끈한 파니니는 한끼로 충분하고 스프도 적당한 양이라 세트메뉴가 딱👍', 28, 7, 'GOOD', SYSTIMESTAMP);
