INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '비오는 날 방문했어요. 주차도 가능하고 분위기가 너무너무 좋은 카페입니다. 맛있는 커피와 휘낭시에는 덤이구요. 자주 올 것 같은 동네카페에요!!', 47, 4, 'GOOD', SYSTIMESTAMP);
