INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '인테리어도 우드 톤으로 아늑하고 시그니처 메뉴가 여러 종류가 있어서 다 먹어보고 싶더라구요! 점심에는 일부 할인도 하고 있어서 다음에는 다른거 마시러 와야겠어요🙂', 15, 10, 'GOOD', SYSTIMESTAMP);
