INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '크림커피 궁금해서 들어왔다가 아아마셨는데 산미있는원두 좋아하시는 분들은 좋아하실거같아요! 사진도 진짜 잘나오고 아늑해서 너무 좋아요!', 68, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '지나가다 우연히 왔는데 진짜 커피가 너무 맛있어요.... 각자 다 다른 메뉴 시켰는데 전부 다 맛있었어요 앞으로 홍대 근처 오면 카페는 그냥 여기 오면 될 거 같아요 최고였어요', 75, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '들어가기 전부터 외관이 예뻐서 기대했는데 분위기도 좋고 메뉴도 다양해서 한참 고민하고 골랐어요🙈 사장님도 친절하시고 맛은 뭐 말이 필요 없네요~ 재방문 각!', 24, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '회사 근처 이쁘고 조용한 카페를 발견했어요. 인테리어두 이쁘고 음료도 맛있네요 ㅎㅎ 앞으로 점심시간에 자주 올것같아요 ~ 잘 쉬다가겠습니다 :)', 35, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '말차초콜릿, 딸기크림 시켰는데 크림이 엄청부드럽고 맛있어요 초코브라우니는 아이스크림이랑 잘 어울립니다 지나가며 보고 항상 와보고 싶던 카페였는데 내부 인테리어가 예쁘고 깔끔+생각보다 넓어서 앉아있기도 좋았어요', 25, 4, 'GOOD', SYSTIMESTAMP);
