INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '우연히 지나가다가 매장이 너무 이뻐서 남편과 처음으로 방문해 봤습니다. 전체적인 분위기가 너무 제 취향이고 편안하고 이쁩니다~! 사진 찍기 좋아요. 디저트류랑 시그니처 음료들도 당도가 적당해서 기분 좋게 맛있고 모카 헤이즐럿 크럼블의 경우는 식감도 좋고 고소하니 맛있네요. 모양도 참 이쁩니다. 🥰😋', 28, 4, 'GOOD', SYSTIMESTAMP);
