INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '급하게 찾은 카페였는데 분위기도 따뜻하고 아늑한 느낌이라 좋았어요! 바스크 치즈케이크가 부드러우면서 쫀득하고 위에 올라간 바닐라 아이스크림과도 아주 잘 어울렸고, 바닐라 크림커피는 많이 달까봐 걱정했는데 딱 좋은 단맛에 적당히 섞어먹으니 위에 크림이 부드럽게 넘어오는게 아주 좋았어요! 아메리카노도 딱 제가 생각한 맛이었고 아주 만족스러운 카페였습니다! 화장실도 실내에 있고 아주 깨끗해요!', 5, 9, 'GOOD', SYSTIMESTAMP);
