INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '합정에 들를 일이 있어서 일을 본 후 시간이 조금 떠서 카페를 찾게 되었습니다 근처에서 가장 평점이 높아보이고 인테리어도 좋아보이는 곳이 카페리프인 것 같아 방문했습니다 실제로 오니 더 이쁘고 커피도 너무 맛있습니다 고소한 원두는 강배전 좋아하시는 분들은 너무 좋아하실 것 같아요', 40, 0, 'GOOD', SYSTIMESTAMP);
