INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '브런치 시간에 와서 머쉬룸 파니니와 커피 맛있게 먹었어요 :) 조용하고 분위기 좋아요! 다음엔 다른 디저트들도 먹어보고싶어요!! ㅎㅎ', 4, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '크리스마스날이라 만석이라 걱정했지만 마침 한자리 비어있어서 바로 들어올 수 있었어요! 소금커피 좋아해서 소금커피 검색해서 온 곳이였는데 너무 맛있어요 ㅎㅎ 카페공간도 인테리어도 너무 아늑하고 편해서 좋고 무엇보다 화장실이 안에있어서 너무 좋아요 ㅎㅎ 매장도 엄청 깔끔하고 화장실도 깔끔하니 여자분들 좋아할거같은 카페입니다! 디저트들도 꽤 맛있어보이고 다음에 또 방문 할 거 같아요 ㅎㅎ', 35, 8, 'GOOD', SYSTIMESTAMP);
