INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '매장 분위기가 너무 아늑하구 디저트 종류도 다양합니다 🩷 음악도 잔잔하게 깔려서 집중하기에도 좋고, 도란도란 대화하기에도 너무 좋은 홍대 서교동 카페입니다 ☺️ 커피 원두도 선택할 수 있어요 !', 50, 4, 'GOOD', SYSTIMESTAMP);
