INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '지나가다가 우연히 발견해 들어온 곳인데, 우선 밖에서 보고도 어??! 할정도로 외관도 그렇고 내부도 인테리어가 너무 멋져요!🫶🏻저휘는 허니솔트커피랑, 아메리카노! 그리고 디저트는 필수인지라 ㅋㅋ 바스크치주케이크랑 모카헤이줄넛크럼블 먹었는데🤩 너무너무너무 맛있는🩷🫶🏻✨ 여유롭게 대화하기 좋고, 이모저모 전체적으로 대만족 한 곳이에요. 또 올게요✨', 47, 7, 'GOOD', SYSTIMESTAMP);
