INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '카페란 카페는 모두 찾아다니는 사람으로써 여기는 찐입니다..🤍 분위기 진짜 무쳤어요.. 집 앞에 있는 카페인데 왜 이제서야 왔을까 후회돼요. 홍대 올 일 있으면 꼭 추천합니다ㅠㅠ!!! 자주 올게요 사장님', 42, 0, 'GOOD', SYSTIMESTAMP);
