INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '조용히 작업할 곳을 찾다가 들어왓는데, 티 너무 맛있어요! 크리스마스 분위기도 잔뜩 나구, 알바생분도 친절해서 좋은 시간 보내고 갑니다😊', 16, 7, 'GOOD', SYSTIMESTAMP);
