INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '홍대 미팅 오면서 인테리어가 마음에 들어서 오게되었어요~~~~^^ 조용하고 깔끔하고 짙은우드스타일을 갠적으로 좋아하는 저라 예쁜카페였고 원두도 3가지종류라서 원하는걸 픽 할 수있어서 좋았습니다~~😉😉 담번에도 온다면 여기로와서 일하면 집중도 잘 될것같아요^^👍', 38, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'INDUSTRIAL');
