INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '사장님 커피랑 디저트 진짜진짜맛있어요! 모카 헤이즐넛 크럼블? 정말 덕분에 행복해지는 순간이였어요! 추천받고 왔는데 멀어서 자주는 못오지만 많이많이 소문낼게요!🙃', 6, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '시그니처 메뉴들 다 먹어보았는데 커피보다는 논커피 좋아하는 저에게는 샷 한번만 들어간 시그니처 커피 그중에 말차초코가 넘 맛있어요! 샷 하나라 부담도 없고 맛은 더더욱 좋아요! 술술 들어가서 금방 다 마시게된답니다 🥹 매번 테이크아웃해갔는데 다음에는 아늑한 내부 즐기면서 마시고싶어요!', 36, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '우연히 지나가다가 분위기가 예뻐서 들어왔는데, 음료도 맛있고 디저트도 굿굿👍👍 특히 허니솔트 라떼 최고에요! 분위도 좋고 집근처 동네라서 자주 올것 같아요👍', 41, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
