INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '카페 치케 먹었는데 짱 맛이고 음료도 다 맛있었어요! 그리고 분위기가 너무 좋아요😆 악보 인테리어도 그렇고 거울 테두리도 피아노 건반같이 되어있어 감성 넘쳐요! 그래서 사진 막 찍어도 예쁘게 나와 기분 좋았어요🥰', 74, 12, 'GOOD', SYSTIMESTAMP);
