INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '세번째 방문입니다 초코말차가 정말 맛있다고 했는데 초코말차가 또 생각나서 왔어요. 여러분들도 또 와서 초코말차를 꼭 드길 바랍니다. 구리고 휘낭시에도 맛있는 솔직히 그냥 여기 시그니처는 전부 맛있으니까 와서 드셔보시길 바랍니다. 영수증 리뷰이벤트도 정말 좋은 이벤트만 하니 꼭 참여해보세요.090', 50, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '매장이 전체적으로 우드톤이어서 고급져요! 시그니처 커피 2개를 시켰는데 둘 다 넘 맛있어요👍 사장님이 넘 친절하셔서 오래 있어도 편한하게 있을 수 있었어요^^ 홍대 올때마다 방문하려구요😆', 8, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '제가 정말 좋아하는 가게 입니다. 아니나 다를까 또 말차초코인데 여러분들 제가 이렇게 말한다면 역시 말차초코를 먹어야하지 않을까요 꼭 와서 말차초코를 드시길 바랍니다.', 44, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '분위기가 너무 좋아요🥰 저녁 여덟시 좀 전에 오니까 웨이팅 전혀 없고 이야가 하기 딱 좋은 느낌! ʕ•͡-•ʔ 곰돌ㄹ이 트리 짱 귀여움', 45, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '카페 인테리어도 너무 예쁘고 분위기도 좋아요! 녹차라떼는 크림이 저어엉말 맛있고 레몬에이드도 상큼하니 좋았습니다. 치즈케이크 꼭 드세요~~~ 케이크도 아이스크림도 정말 최고💓... 연남 놀러올 때 또 와서 다른 메뉴도 먹어볼 예정입니다!!', 125, 22, 'GOOD', SYSTIMESTAMP);
