INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '시그니처 메뉴 도장깨기중...!! 오늘은 말차초콜릿 먹었는데, 커피맛 안나는 커피 음료는 이거다!! 말차크림 텁텁해서 별로 안좋아하는데 이건 하나도 그런맛 없고 너무 부드럽네요ㅎㅎ 초코라떼 같은 맛인데 너무 달지 않고 깔끔한 고급진 단맛이에요! 여전히 분위기 편안하고 좋아요 :)', 42, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '연남동 데이트하다 분위기 좋은 카페 보여서 들어왔는데 인테리어도 예쁜데 커피, 디저트 다 맛있어요! 바닐라크림 강추😁😁따봉 드립니다', 15, 5, 'GOOD', SYSTIMESTAMP);
