INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '사장님이 친절하시고 무엇보다 디저트랑 시그니처 커피가 진찌 맛있어요!!!!🥹연남동 놀러와서 우연히 들렀는데 분위기 맛집 음료 맛집 디저트 맛집이에요🥳❤️🩵데이트하시는 분들 완전 추천이영😘', 104, 24, 'GOOD', SYSTIMESTAMP);
