INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '커피가 넘 맛있어요 원두를 선택할수있어서 좋고, 내부인테리어도 감각적이라 사진도 잘나와요!  화장실도 넘깨끗하고 주차장도있어서 편했어요♡', 118, 19, 'GOOD', SYSTIMESTAMP);
