INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '지나가는길에 카페가 너무 예뻐서 가봤어요!! 인테리어 분위기가 너무 너무 좋았어요. 커피도 맛있고, 디저트도 너무 맛있었어요!! 오픈한지 하루밖에 안되어서 운좋게 바로 앉을 수 있었지만 다음에 올때는 웨이팅이 있을것같다는 생각이 듭니다ㅎㅎ 최고예요!!👍😘', 5, 6, 'GOOD', SYSTIMESTAMP);
