INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '새로 오픈해서 방문했는데 깔끔한 인테리어 좋네요. 무엇보다 커피가 제 취향입니다. 로스팅이 강한 프렌치 스타일이 아녀서 저는 좋아요. 디카페인이 보통 풍미가 떨어지는 경향이 있는데 풍미와 향이 괜찮아서 재방문할 것 같아요. 시그니처 라테 3종류도 부드럽고 좋네요', 33, 1, 'GOOD', SYSTIMESTAMP);
