INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '디카페인도 있어서 좋아요 ~ 바닐라 음료 고급스럽게 단맛이고 거품도 쫀쫀해서 맛있어요 유리컵에 주시는 것도 마음에 듭니다 휘낭시에도 겉바속촉으로 데워서 주시는데 커피랑 같이 먹으면 하루의 피로가 풀려요 ~~ 좌석도 프랜차이즈 다닥다닥 아니고 적당히 간격이 있어서 편히 얘기하기 좋습니다 ^^', 36, 0, 'GOOD', SYSTIMESTAMP);
