INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '말차초코가 정말정말 맛있습니다. 시그니처라면 사실 다 맛있는데, 와서 꼭 드시길 바랍니다. 사진만봐도 지금 말차초코가 3개입니다 말차초코가 맛있다는게 느껴지시죠. 꼭 말차초코를 드시길 바랍니다.', 59, 15, 'GOOD', SYSTIMESTAMP);
