INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '카페 인테리어가 너무 멋진데 커피도 맛있어요~~ 테이크 아웃으로 가지고 나가려했는데 매장에 오래있지못해 너무 아쉬웠어요~~~ 다음엔 허니솔트 꼭 먹어보고싶어요~~ 그리고 벽에 포스터 너무 힙해요~~~^^', 38, 10, 'GOOD', SYSTIMESTAMP);
