INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '새로 생긴 곳이라서 기대 없이 도전했는데 진짜 맛있어요! 점심시간에는 테이크아웃 할인도 있으니까 가격도 나쁘지 않은 것 같습니다.', 1, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '인테리어가 멋져 보여서 우연히 들어온 카페인데 시킨 메뉴 모두 진짜 너무너무너무 맛있어요 집이 멀어서 너무 속상할 정도로요 ㅠㅠ 강남에도 매장 만들어 주세욧🙄🙄🙄❤️', 51, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '음료 왜이렇게 맛있어요….????!!!!????!!!!!! 인테리어도 너무 예쁘고 ㅠㅠㅠㅠ 직원분도 친절하시고 대대대대대대만족입니다', 47, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '카페가 생긴지 얼마 안되서 그런지 인테리어 매장등등 엄청 깔끔합니다 ㅋ 커피도 맛있고 사진 찍기 좋아요 연인이랑 오면 좋을꺼같아요!!참고로 사장님이 미인이에요~ 번창하세요', 16, 7, 'GOOD', SYSTIMESTAMP);
