INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '원두를 선택할 수 있어서 좋아요 산미 있는 원두를 선택했는데 끝맛이 꺌끔하고 오렌지향이 나는 느낌이 너무 좋네요 바닐라 크림 커피는 밸런스 있는 원두를 선택했는데 부드럽고 맛있네용 카페 내부 인테리어 및 분위기도 좋아서 마음에 듭니다~', 25, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '이번에 새로 오픈한 카페라고 하는데, 저만 알고싶을 정도로 카페가 너무너무 예뻐요 ... 정말 커피도 다른 곳에 안 파는 시그니처 메뉴여서 너무 맛있고 단골 해야겠단 생각이 🤍🤍 듭니다', 40, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '친구들이랑 근처 소품샵 들렀다가 카페 왔는데 분위기도 좋고 얘기나누고 좋네요 커피 원두 종류도 3가지여서 입맛 따라서 고르기 좋은 것 같아요. 다음에 또 올게요!', 17, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '커피향이 너무좋아요 ! 휘낭시에는 너무 달지않고 적당히 달달하니 너무맛있어요~ 그리고 뭔가 카페 분위기가 갬성이 너무좋네요 ㅎㅎ 조명 음악 인테리어의 조화도 좋습니다 다음에 또 방문할게요~~~', 71, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '사장님 친절하고 커피가 진짜 맛있어요. 가게 분위기도 좋고 인테리어에 신경쓴게 보입니다. 우유 못먹는 사람도 먹을수있는 대체 음료도 구비되어있어요. 추천합니다.', 38, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '인테리어가 독보적으로 좋았어요. 멍때리고 있어도 분위기가 너무 좋아서 시간도 너무 잘 감. 단 커피 잘 안먹는데도 여기 시그니처 커피는 여자친구랑 같이 바닐라크림 허니솔트 두가지 먹었는데 감탄하면서 먹었네요. 굿굿', 13, 8, 'GOOD', SYSTIMESTAMP);
