INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '홍대 신상 카페 인테리어도 예쁜데 시그니쳐 바닐라크림커피랑 휘낭시에, 디저트도 찐하고 너무너무 맛있네요ㅠㅠㅠㅠ 다음에 스카치밀크 꼭 마시러 올게요!!', 1, 9, 'GOOD', SYSTIMESTAMP);
