INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페리프 서교점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '앞손님이 너무 맛있다고 하면서 나가시길래 사장님한테 뭐냐고 물어봐서 먹어봤는데 진짜 맛있었어요...!!! 다들 로얄바나나 드세요 백번 드세요!!! 달달하고 부드럽고 고소하고 다함!!! 못참고 빵도 추가로 시켰는데 가성비 진짜 좋아요ㅎㅎ 스벅이랑 가격 비슷한거 같은데 여긴 사장님이 빵도 만드시는듯?? 조만간 쿠폰도 만드신다는데 빨리 주세요.... 자주 갈게요.....', 21, 5, 'GOOD', SYSTIMESTAMP);
