INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라포레스타'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '정말이지 익을 것 같은 더운 여름날이다 경의선숲길을 헤메다 발견했다 들어가자마자 자리부터 차지하고 메뉴 선택을 고민해본다 아이스카페모카 주문 주변 풍경이 괜찮다 사람이 많기는 한데 다들 공부중이라 시끄럽지 않아서 좋았다 커피도 맛있고 공간도 괜찮고 소개하고 싶은 곳이다 다음에 오게되면 다른메뉴도 먹어봐야겠다', 13, 8, 'GOOD', SYSTIMESTAMP);
