INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라포레스타'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '드립커피가 맛있고 공간도 넓은 게 좋았어요. 배가 불러서 디저트 못 먹은 게 조금 아쉽네요 ㅎㅎ 깔끔하고 마음에 들어서 다음에 또 방문하고 싶어요 ㅎㅎ', 32, 7, 'GOOD', SYSTIMESTAMP);
