INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라포레스타'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '근처에서 일했을 때 자주 왔던 카페 오랜만에 방문했는데 주말이라 그런지 사람이 댕많다 평일에 오면 조용해서 좋았는데 살짝 아쉽,,, 반지하라 조용하고 시원하다 음료도 맛남', 30, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라포레스타'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '점심먹고 철길공원 산책하고 자주 들리는 곳입니다 일단 커피맛이 좋아서가 첫번째고 창가에 앉아서 철길공원 바라보며 차한잔 하는 맛, 사장님의 친절함.. 짧은 시간이지만 기분좋게 머물다 갈수있는 장소입니다', 49, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라포레스타'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '저녁 6시정도에 들어와서 거의 마감 직전까지 친구랑 수다 떨고 놀았는데 좌석도 쏘 널널하고 정말 아늑하니 편안한 분위기였어요 ㅎㅎ 제가 예전에 보조배터리를 대여했던 곳이었던 걸로 기억하거든요 그때나 지금이나 사장님도 정말 친절하셨고 무엇보다 디저트랑 커피가 너모 맛있었어요👍👍❤️❤️', 14, 4, 'GOOD', SYSTIMESTAMP);
