INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라포레스타'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '분위기도 좋고 직원분들도 친절하시고 케이크도 맛있었어요! 홍차 아이스로 시켰는데 얼음을 따로 주시고 원하는 만큼 따라마실수도 있어서 좋았습니다!', 107, 20, 'GOOD', SYSTIMESTAMP);
