INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라포레스타'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '🎀 헤브니 추천메뉴는 - 얼그레이 로얄 등 tea 종류🍵 (쉽게 진해지니 오래 기다렸다 마시지 말기! (심장이 벌렁❤️‍🩹) 뜨거운 물은 리필요청 가능😇) 🍜 La Foresta 📍 서울 마포구 신촌로6길 23 지층 - 매일 오픈(12pm~10:20pm) - 주말에는 사람 많지만 홍대 근처치고는 그나마 자리가 있음😘 - 평일에는 혼자 가서 작업하기 좋은 조용하고 분위기 좋은 카페 ☕️ #홍대카페추천 #홍대골목카페 #마포카페추천 #헤브니라이프 #헤브니가다녀간곳', 9, 4, 'GOOD', SYSTIMESTAMP);
