INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라포레스타'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '평일에 방문하면 젠틀하신 중년남성분이 반겨주신다 미소를 띄며 안내해주셔서 내 입가에도 미소가 돌았다 커피는 고소한 맛, 산미 있는 맛 두가지 고를 수 있고 맛있는 편이다! 혼자와도 둘이와도 다같이와도 전혀 부담없는 곳이다! 자주 들를거같다👍🏻', 48, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라포레스타'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '카페라떼 주문 반지하에 있는 조용한 카페인데, 매장이 넓은 거에 비해 사람이 그렇게 많진 않고 카공하기 좋은 분위기였다. 재즈가 흘러나오고 푹신한 원목 가구들이 좋았음... 카페 리뷰는 잘 안 남기는 편인데, 사장님께서 너무 친절하셔서 잘 되라고 남김♡', 118, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라포레스타'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '사장님이 너무 친절하시게 대해주셔서 저까지 기분이 좋았어요!̆̈  게다가 크림 넛라떼 너무 맛있네요. 커피가 너무 맛있어서 또 오고 싶어요!̆̈ 남자(여자)친구랑 같이 오기에 분위기도 좋고, 홍대에서 이만한 카페 찾기 쉽지않은것 같아요!̆̈ 재방문 의사 무조건 있습니다:)', 10, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라포레스타'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '반지하에 있는 카페. 어른 사장님께서 친절히 메뉴 제안해주심. 단체석도 있으나 조용히 작업하기에도 좋은 곳. 경의선 숲길 바로 앞 이라 지나다 들르기도 좋다. 주말 오후엔 들어서자마자 자리부터 잡고 주문하자.', 119, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라포레스타'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '갑자기 비가 와서 들어가게 됐는데 .. 왠걸 오레오 빙수 찐 맛집 .. 담에도 들릴게요 🍧 조용해서 작업 하는 분들이 꽤 있었어요', 11, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라포레스타'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '경의선 숲길 걷다가 우연히 들어간 카페. 밖에서 보는것보다 매장도 넓고 좌석간 간격도 넓어서 대화나누기도 좋아요 커피맛도 고소하니 너무 맛있고 음악도 좋고~ 사장님들도 친절하세요 혼자와도 좋을 맘 편한 카페 발견해서 좋네요:)', 23, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라포레스타'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '아늑하고 따뜻한 라떼 같은 장소 🤍 항상 어딜가나 처음가면 커피 맛을 알기 위해서 라떼를 시켜요! 바리스타분의 커피 기본기와 아트 그리고 원두 풍미까지 넘 좋았어요 말차라떼 위 크림 .. 😍사장님과 바리스타 두 분 모두 너무 친절하셔서 더 자주 올거 같아요! 다음엔 초코라떼 먹으려구요 ㅎㅎㅎ 초코라떼에 초코가 고디바꺼 쓰시더라구오 :) 음악은 잔잔히 클래식 나와서 비오는 날 더 운치있었어요 넘 좋은 시간 잘 보냈습니당 자주자주 방문할게요 ☕️🐻🤍', 127, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라포레스타'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '카페 분위기도 좋고 쾌적해서 너무 좋았어요 저녁 시간대 방문 한 거라 가볍게 마실 수 있는 음료를 찾고 있었는데 친철하게 티 종류로 추천 해주셔서 궁금해서 시켜봤는데 티백이 아닌 티 포트에 나와서 깜짝 놀랐습니다..☺️ 티 맛도 정말 최고였습니당 !!', 31, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라포레스타'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '너무 더워서 달달한 밀크티가 먹고 싶어서 지나가다 테이크아웃했어요. 사장님 친절하셨지만 가격이 쪼금 비싼 것 같구, 밀크티가 맛있긴해도 연해서 4점!', 50, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라포레스타'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '조용하게 작업하기 좋은 카페! 화장실도 공간도 깨끗하고 넓음. 원두는 두종류인데 둘다 쏘쏘. 디저트류도 쏘쏘. 특별히 맛있는 집은 아니어도 지인이나 혼자서 무난하게 오기 좋은 곳!', 75, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라포레스타'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '밖에선 나름 괜찮아보여서 들어갔는데요 둘이서 디저트 세개 음료 두잔 주문 하고나서 괜찮다는데도 자꾸 너무 많이 시킨거 아니냐고 계~속 계~속 물어보셔서 민망하네요. 그리고 제 음료 준비 다된걸 픽업대?에서 빨대잡고 젓고 계시던데 뭐하시는건가요? 제 입이 닿는 부분인데 불쾌하네요.', 32, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라포레스타'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '처음에 밖에서 보니까 카운터에 연세가 조금 있으신 분이 마스크를 안쓰고 앉아서 뭘 드시고 계셔서 들어갈까 말까 고민하다가 들어갔는데 분위기도 좋고 직원분들 친절하셔서 좋았습니다. 음료도 나쁘지 않았습니다. 카페로서의 느낌은 좋았습니다만 인테리어에 비해 업무 숙련도를 조금 끌어올리셔야 할 필요가 있을것 같아요', 9, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '원래 친구하고 오고 싶었지만 시광대리인 콜라보가 24일이라서 제가 혼자왔습니당...친구하고 못와서 아쉽지만 전메뉴 중에서 2개는 친구 주려고 포장했는데 친구가 만족스러워했습니당!!사장님이 되게 친절하셨고 전시된 것도 보면서 감탄만 했습니당..!!아침 일찍 혼자야서 그런것도있겠지만 공간이 넓고 깔끔해서 그 분위기를 좀더 느낄수 있었습니당..!!거기에 더불어 분위기에 맞는 음악덕에 더 좋았습니당..:33쓰고 싶은게 많지만 설명을 어떻게해야할지 몰라 이만 적겠습니다..!!', 32, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '정말 최고의 콜라보 카페예요ㅠㅠ 이번주가 마지막이라 너무 아쉽고 연장해 주셨으면 좋겠는 마음이에요,,, 재방문을 해도 해도 질리지 않고 좋아요 음식도 맛있고, 포토존도 잘 꾸며져 있어서 정말 좋았어요!!!', 83, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '첫 투니크 카페 방문이었는데요~!! 시광대리인 콜라보라고 해서 참을 수 없어 다녀왔습니다ㅏ 공간은 생각보다 넓고 쾌적했어요~ 근데 약간 아쉬운점은 식기가 랑 음식 청결이 그렇게 좋지않았다는 점..? 그리고 직원분들도 친절하다는 평을 많이 봤는데 저는 잘 모르겠더라구요ㅠ 그래도 안에 되게 잘 꾸며져서 구경하고 즐기는데에는 매우 만족스러워요!!', 16, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '8/7 (목) 투니크 x 시광대리인 콜라보 카페 다녀왔습니다!😄 시광대리인 오랜팬으로서 너무 너무 값지고 감동적인 경험이었고 애니메이션 내용이나 캐릭터 컨셉 정말 꼼꼼히 잘 반영해서 내부 인테리어 꾸며졌다고 생각해요. 특히 사진 인화실과 영도편 빌런 트리오 인테리어 룸이 정말 시광대리인 컨셉에 잘 맞게 다양한 소품들로 꾸며져 있었습니다! 들어가는 순간 하룰라라 가기 가능...😇 음식이랑 음료도 정말 맛있는데다 예쁘기까지해서 눈과 입 모두가 즐거웠습니다 그밖에도 포스트잇으로 방문후기 적어놓고가는 게시판이나 MD굿즈 파는 굿즈존, 헤이포카 뽑을 수 있는 포카 기계와 시광 네컷사진 찍을 수 있게 따로 마련해놓은 옥상 야외공간까지...🥹 이토록 다양한 체험을 즐길 수 있게 만들어주셔서 정말 감사드립니다🫶❤️❤️❤️❤️❤️', 84, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '다른 곳에서 진행하는 콜라보카페들도 많이 가봤지만, DP정말 잘해두셨어요. 주말에 이용인원대비 직원이 부족해서 힘들텐데도 서비스를 잘 해주십니다. 이용자들이 최대한 서비스를 받을 수 있게 안내를 잘 해주셔요.', 1, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '포토존이 진짜 잘 되어있었어요. 특히 사진관 현상실은 영상에서 튀어나온 줄...! 콜라보 카페라 음식 맛은 크게 기대 안하고 갔는데 케이크나 음료도 괜찮았어요. 뭣보다 한국에 들어올거라고 생각 못하고 있었는데 해주셔서 정말 감사합니다.😭 나중에도 또 하게 되면 좋겠네요~', 34, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '투니크 홍대점 첫방문♡ 웹툰 레가스랑 콜라보하고있어요! 카페 너무 예쁘게 잘꾸며 놓고 메뉴도 너무 예쁘고 맛나요😚 산뜻하게 전시되어 있어서 포토존도 너무 예쁘고 굿즈도 많이 팔고 자주 방문해야 겠어요🥰', 78, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '컨셉을 잘 살려서 독특하고 좋았어요! 근데 일하는 알바분들 너무너무 불친절해요 굿즈 구매하려고 물어보는데 그렇게 틱틱대면서 말할필요 있을까요? 자리에 가만히 앉아서 손가락 하나 까딱안하고 돈 편하게 번다 싶네요 편하게 일해서 부럽더라구요', 101, 21, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '시광 콜라보 카페 다녀왔어요🖤🤍 포토존 너무 잘 꾸며져있고 퀄리티 미쳤어요ㅠㅠ 콜라보 메뉴도 다양해서 좋았는데 루광이링 청샤오시 메뉴가 하필 품절이라 못먹은게 너무 아쉬웠네요….. 품절메뉴는 미리 sns에 공지해주시면 좋을 것 같아요ㅠㅠ', 15, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '웹툰 속 세상에 쏙 들어온 느낌. 둘의 기숙사를 몰래 탐방하는 기분이었어요. 이번 음료중 라떼는 맛도 좋았습니다. 마늘빵은 개인적으로 좋아하는 메뉴라 맛있게 먹었습니다. 내일도 재방문할 예정입니다. 마지막날까지 알차게~^^', 83, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '원룸조교님 콜라보 카페 두번째 방문이었습니다! 평일에 방문하면 여유롭게 구경할 수 있어서 너무 좋더라고요 직원분들도 여전히 친절하셔서 궁금한 거 물어보기도 편했습니다!', 2, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '콜라보카페 답게 이쁘게 꾸며져있어서 구경하는 재미가 있어요! 직원분들도 친절하시고 방문하기 좋아요! 에어컨도 빵빵...여름에 최고예요!', 26, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '아 처음 와봤는데, 넘 행복했습니다. 인테리어가 너무 비명 지를만큼 좋았구요. 제가 갔을 때는 1층 에어컨 고장이라 좀 더웠지만 또 갈 생각입니다. 음식도 금방 나오고 직원분도 친절하시고 그냥 너무 좋았습니다', 38, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '아름다운 그들의 사랑과 그들의 원룸을 훔쳐보고 왔습니다. 오래 사랑하시고 오래 행복하시고 오래 남친 덕질하시길… 유운이와 진형이 그리고 많은 원룸 조교 등장 친구들을 만나게 해주신 지붕님께 무한한 사랑과 지갑을 바치며 이만 줄이겠습니다…❣️', 81, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '칼과 꽃 이벤트 카페. 음료가 맛있고 콜라보카페라 관련 굿즈와 식음료가 구비되어 있어 다양하게 골라 먹을수 있습니다. 저는 권희량의 블랙커런트 에이드 주문. 상콤하고 시원해서 갈증날때 마시면 좋아요~', 16, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '굿즈도 그렇고 완전 메이저는 아닌지 시광대리인 장르 콜라보카페 소식을 듣고 찾아가 즐기고 왔습니다 안에 꾸며놓으신 인테리어나 메뉴도 나쁘지 않았어요 그런데 예약 시간이 돼도 직원분 안내가 없었고, 결국 다른 방문객분께서 여쭤봐서 하나둘 들어가기 시작했습니다. 그래도 직원분들 들아와도 된다는 말씀은 단 하나도 없었습니다 그리고 인화사진 뽑는 기계나 네컷 사진 위치에 대한 안내도 매장 내에 없고, 심지어 인화사진은 바코드를 찍어서 뽑아야하는데, 사용 방법에 대한 안내가 없어 아쉬웠습니다. 예약 상품과 일반 상품 수령 방법, 음식과 굿즈 계산 위치도 다른데 그에 대한 안내도 부족합니다. 트위터 공지만으로 다 알기 힘들고, 매장에서 안내를 해주셔야할것 같습니다 그리고 직원분들도 친절하지는 않으셨습니다', 7, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '저 둘 정분 났어요~ㅎㅎㅎ 여기저기에 귀욥게 디피된 액자들과 소품들. 일단 팥든 음료맛이 썩 괜찮아요. 찹쌀떡도 맛있었구요. 벚꽃케이크도 괜찮았는데 약과는 느므 딱딱해요. 약과가 딱딱하기 쉽지 않은데 말이쥬. 그래도 지금까지 콜라보메뉴보다는 나은듯해요', 67, 11, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '직원분들은 친절했고 공간 구성도 좋았지만 전시물 사진 찍을 공간이 카운터 바로 옆이라 비좁았습니다. 에어컨을 피해 2층 실외에 앉았는데 맞은편 건물이 공사중이라 그런지 의자와 식탁에 먼지가 뽀얗더라고요. 상시 청소가 어려웠던 거라면, 차라리 주의 표시라도 해주는 게 더 좋았을 것 같습니다.', 22, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '19년지기 친구 했으니깐 19년만 연애해. 이런 문구 너무 좋다.. 메뉴 구성도 알차고 음료도 소프트하게 크림크림하고 딸기케이크도 든든하구.. 매장 여기저기 않찍을레야 않찍을수 없구. 너무 좋았어요. 하늘하늘 색이라서 분위기도 밝고.. 좋음요.. 외부는 공사때문에 시끄러웠지만 . 그래도 구경 하는 동안 기분도 좋았어요.. 다음엔 또 어떤 분위기로 바뀔지 궁금하네요.. 2번째 방문이랍니다~ 달마다 오는 느낌 너무 좋아요~', 103, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '우리나라에도! 드디어 시광 콜라보카페를 한다는 마음에 냅다 시광칭구들 모아 갔습니다. 음료들, 디저트 맛있있었어요! 친구들이랑 같이가서 도장을 4개 찍었는데! 두개만 더 모으면 띠부씰 얻을수 있어서! 과감히 질렀습니다. 랜덤이라고 하더라고요... 또오륵..😢 그래서 점원 분께 ''제발 샤오시 있는 세트로 뽑아주세요🙏'' 하며 받았는데~ 샤오시가 뙇!!!! 감사합니다🙇‍♀️ 하며 저보다 더 시광 찐 팬인 친구에게 선물해 주었습니다! 아쉬운점 - 통창인데 차양막이 없어 공간이 더웠어요. - 촬영스팟이 적은거 같아요. - 타 장르 물품도 한 장소에서 판매해서 시광콜라보카페 기분이 안났어요. 메뉴만 콜라보인 느낌... - 증정 물품에 대한 안내부족. 그냥 구경만 해도 직원분이 눈치를.. 대응도 불친절 하셨어요.', 20, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '직원분들이 친절하시고 일처리 하시는게 완전 고수느낌이에요 만원당 특전이 있는지 몰랐는데 구매하는 금액 확인하시곤, 하나만 추가하시면 좋을것같다고 해주셔서 너무 좋았어요. 이벤트 참여도 한분한분에게 꼼꼼히 설명해주셔서 좋았습니다 ~ 콜라보 카페는 투니크 ㅠㅠ!!', 25, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '맞춘 메뉴와 디피가 이쁘게 꾸며져 있어요! 곶감 색다르고 맛있었어요. 매실이 적어서 조금 아쉬워요. 세트메뉴 음료양 동일하게 부탁드려요....ㅠ 직원분들 친절하시고 즐거운 시간이였습니다! 😍', 30, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '전시 해놓은 거 보는 재미가 있었습니다! 2층에는 노래 틀어주면 좋을 것 같아요 너무 적막이고 대화하기에도 다들 눈치 보이시는 느낌이었음 다른 분들은 어떤지 모르겠는데 직원 한 분이 불친절하셨어요.. 투니크 홍대점 첫 방문이었는데 다시 가고 싶은 마음은 딱히 없네요..ㅜ', 16, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '색다르고 재밌어요! 직원분들 넘나 친절하시고 안내랑 설명도 잘 해주셔요! 샌드위치 맛났어요! 잘 꾸며져있어서 구경하는 재미 👍', 82, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '기다린거 만큼 기쁨이 100배. 입장하시면 왼쪽 벽면쪽으로 응원메시지 문구 쓰는 곳도 있구. 벽 전체가 계속 사진찍게 만들어놔서 진짜 주문도 하기전에 사진을 미친듯이.. 2층도 올라가보세요. BL좋아하시는 분들은 진열장에 있는 물건들 보면 기분이 좋아져요. 점심도 거르고 와서 먹었는데 맛있구. 음료도 깔끔해서 너무 맛있어요. 좀만 더 사먹으면 먹을수 있을꺼 같은데 삼각김밥 먹어서 배가 부르네요.여러분 천장도 보세요. 의외로 깔끔하게 가랜다를 달아놔서 저거 사고 싶네요. 다시 1층 내려오시면 죽이는관계 사진 인화하는 곳도 있어요. 가격도 저렴해서 차라리 여기서 인화하는거 추천! 근데 많은 사진은 없으니깐 요령껏. ㅋㅋ. 입장 스티커 잊지 마시구. 잘 놀다 갑니다.', 24, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '원룸조교님 콜라보카페 다녀왔습니다앙❤️ 처음엔 마냥 개그 만화인줄 알았는데ㅠ 우지녕 서사가 너무 내 맘을 아프게 해ㅠㅠㅠㅠㅠ 찌통이야.. 멋진 콜리보카페 열어주셔서 고맙슨,,🫶🏻 이 소녀는 너무 우유니와 우진형, 많은 아이들과 너무/..  즐거웠습니다 또 열어주쎄용~❤️❤️', 86, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '두번째 방문이며 첫번째 방문때도 만족했으며 오눌도 매우 만족했다 주위 싸인이나 장식해둔 굿즈를 보니 더 좋았다 직원들도 친절했으며 매장도 아늑하고 청결했다 굿즈도 콜라보 굿즈뿐만이 아닌 콜라보했던 굿즈나 다른굿즈들도 살수있어서 매우 좋았다', 121, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '정말 애정하는 하절기 콜카 다녀올 수 있어서 너무 행복해요🍀🍀디피 연출되어있는 것도 너무 좋고 색감도 너무 청량미🍃 낭낭하고 예뻐서 좋았어요!! 기억에 남는 좋은 추억만들고 갑니다❤️❤️❤️ #하절기 #하절기카페 #절구 #밍구르 #이로밀 #북극여우 #투니크', 22, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '메뉴가 독특하네요. 동행분께서 약과 메뉴도 맛보여주셨는데 무척 달고 딱딱했어요. 원래 콜라보 메뉴는 큰 기대는 안하는 편이 맞을듯요. 그래도 디피가 예뻐서 재방문 하렵니다.', 27, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '이번 콜라보 메뉴들은 너무 맛있었어요~! 작품 분위기랑 제일 잘 어울리는 메뉴라서 좋았습니다! 그런데… 음료 디저트들이 다 너무 달아서ㅠㅠ 커피메뉴(시럽같은게 안섞인) 제발 부탁드려요…', 49, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '생각보다 역에서 가까워서 금방 찾았어요 콜라보 카페 중 맛은 상위입니다. 주문할때 별로라고 생각했던 토마토도 맛있어서 너무 잘 먹었어요', 37, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '조금 늦게 도착했는데도 알바생분들이 너무 친절하게 안내해주셔서 감동..🥹 시설도 깔끔하고 이쁘게 잘 되어있어서 눈호강 잘 하고 왔네요. 음료도 이쁜데 맛있기까지! 저 장미가 식용인줄은 몰랐네요 친구가 주워먹길래 기겁하다가 식용이란걸 듣고 같이 주워먹었어요 ㅎㅎ 장미까지 맛있는 투니크...굿', 26, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '직원분들도 너무 친절하셨고 매장안도 생각했던 것보다 넓고 깨끗했어요. 혼자가서 조용히 분위기 즐기다 오는것도 좋을것 같아요. 다음에 또 오고싶네요:>', 8, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '일단 작품 디피가 끝장나요. 너무 예쁨. 작품 1도 모르고 갔다가 단행본 주문했다능요. 아크릴 살까말까하다가 온라인 주문해야지~했다가 놓침요 ㅠㅠ 메뉴가 야화첩때랑 겹치는거같아서 살짝 실망했는데 뭐 그래도 케이크는 맛있었어요. 메뉴의 실망감을 디피가 다 눌러버렸으니 된걸루요.', 62, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '이번에 메리마블링 카페 꼭 와보고 싶던 곳 이였는데  인테리어나 굿즈도 너무 마음에 들고 좋았고 사진 찍기에도 너무 좋았습니다 우렁강도 메리마블링 팬이였는데 사진 열심히 찍고 왔어요 카페 메뉴도 케이크는 둘다 먹었는데 너무 맛있었고 음료도 맛있었습니다 쿠키는 품절이여서 황치즈만 먹어봤는데 너무 예뻐서 먹기 아까웠어요.... 2층에 인생네컷도 잘 찍고 인테리어도 너무 좋았습니다', 14, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '세번째 방문, 언제 와도 사람이 많네욯ㅎㅎ 돈 좀 써서 5만원 특전 받아 봤어요. 생각했던 것 보다 너무 이쁘고 기분이 좋네요 스탬프도 다 찍어서 띠부실 받았는데 너무 이뻐요 내일도 오겠습니다! 교환해주시는 분들도 한분한분 너무 친절하세요😊', 36, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '첫 시간에 혼자 처음 가는거라서 걱정 많이 했는데 직원분들도 친절하시고 생각보다 눈치도 많이 안 보였어요! 굿즈도 다 너무 귀여웠고, 디저트도 맛있었습니다 :) 굿즈존 바로 뒤에 꾸며진 공간이 있는데 아늑하지만 작품의 포인트들을 다 담아둬서 즐겁게 즐기다 갑니다~~', 26, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '오늘로 이틀차인데 갈때마다 할게 생겨서 새롭네요 ㅎㅎ 펭키 작가님 독자분들도 금손이신듯, 편지 쓰는 공간? 같은게 있었는데 독자분들이 그리신 아이들이 넘 멋졌음 무엇보다 굿즈 교환할때 다들 너무 친절하고 착하시고하셔서 힐링이 됐네요 이렇게 오프라인으로 만나니까 내적 친밀감 UP! 다음에 갔을때도 만났으면 하는 마음이ㅎㅎ 너무 만족수로운 하루였습니당 :)', 76, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '💙투니크 다른점은 이용해봤어도 홍대점은 처음이어서 기대됐었는데 입구부터 너무 예뻐서 더 기대되었고, 내부도 컨셉에 너무 잘맞게 이쁘게 되어있어 진짜 내가 웹툰 속에 들어와있는것만 같았어요!-! 굿즈들도 너무 예뻐서 다 충동구매해버렸어요ㅠ심지어 메뉴들도 맛있어서 너무 행복한 기회였어요😍컨셉에 잘맞는 예쁜 카페 만들어주신 @Toonique7  투니크 직원분들과 그림체부터 너무 취향이라 열심히 챙겨 봤던 좋은 작품 만들어주신 @iiPengkii 펭키작가님한테도 감사드려요💕다음 콜라보도 기대하며 응원할게요!-! #우렁강도 #울강 #메리마블링 #메블링 #펭키 #학산 #투니크💙', 42, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '칼과 꽃 좋아해서 보러갔는데 너무너무 만족했어요 디피도 예뻤고 일러는 말뭐 그냥 너무 좋았어요 또 방문 하려구요! 찹쌀떡 맛있어요 ㅋㅋ', 63, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '멋진 공간이었어요. 작품 속 데이의 전시회를 고스란히 옮긴 듯한 인테리어가 인상적이었습니다. 파니니랑 국화차도 어울리는 조합이라 맛있게 먹었어요.', 9, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '처음 가봐서 이벤트 어떻게 참여하는지 이것저것 많이 물어봤는데 친절하게 대응해주셔서 감사합니다. 음료도 정말 맛있었어요..!!', 37, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '작품과 잘 어울리는 콜라보 메뉴와 잘 꾸며진 매장, 귀여운 굿즈들 보는 재미가 있었어요. 눈과 입이 즐거운 콜라보 카페였습니다. 🌞🏡', 37, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), 'Love decorations and the decorations totally depict the comic 😍 able to make it in time for the last day of the cafe collaboration for 푸른 뭍 아래로 Friendly and nice staff too. Thank you for the nice experience 🥰!', 11, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '매번 새로운 콜카가 오픈할 때마다 찾게 되는 매력이 있는 곳이에요! 특별한 테마와 함께하는 경험 자체가 정말 재미있고, 커피와 특별 메뉴 음료들은 항상 기대 이상으로 맛있었어요.', 18, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '예약물품 픽업갔더니 예약자만 이용가능하세요~ 그날 당일에 트위터공지에 오늘부터 예약물건 정상적으로 수령가능합니다 라고 올려놓고 정작가면 예약자만 이용가능한 날이라 불가능합니다 ㅋㅋ 제가 카페 이용하겠다는것도 아니고 그저 예약물품 주시는게 그리 어려웠나요 심지어 사람 한명도 없었는데요 시간 겨우내서 갔는데 그정도 융통성도 발휘못하나요?', 49, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '굿즈 n만원어치 사고 물건확인하던중에 한개 빼먹었길래 추가로 구매하였는데 영수증 따로라고 1만원 특전 안주시네요 특전 챙기려고 현장구매하는거 아시면서.... 융통성을 조금 발휘하시면 좋지 않을까요?🤭 이건 제잘못이라 어쩔수없는데 새로산 굿즈에 같이 나온 1만원 엽서도 중복이라 기분이 좋지 않네요😟 천원 단위 절삭은 그렇다쳐도 엽서라도 중복 안되게 챙겨주시면 안되나요? 음식은 항상 느끼는거지만  음료가 밍밍해요 케이크는 나쁘지않았어요 아그리고 굿즈 구매할때 가격/품목 맞는지 확인하시지도 않고 바로 결제 받으하더라고요 뭔가 가격이 안맞는것 같다 싶을때 확인했었어야하는데;;; 그리고 제 카드 싸인을 왜 본인이 마음대로 하시는건가요?', 128, 23, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), 'I always enjoy visiting this toonique hongik branch 😄 the staff are friendly, the decorations are beautiful, and I really enjoyed experiencing “ Our Sunny Days” My adventures here always brighten up my day ☀️☀️ ☀️☀️ #해뜨는집 #해뜨집 #콜라보카페 #정석찬 #봄툰 #투니크', 13, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '두 번째 방문입니다. 첫 방문 때 못 먹었던 크레이프 케이크를 시켰는데 연유가 뿌려져서 그런지 엄청 달달한 편이었어요. 그래도 언럭키 휘범이 음료가 달달함을 어느 정도는 잡아줘서 좋았습니다. 전시 공간은 작중 컨셉 구현을 잘해줘서 눈이 참 즐거워요.', 78, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '제가 즐겨 읽는 해 뜨는 집 콜라보! 매장도 아담하고 직원도 친절해서 즐겁게 구경했어요. 아 해 뜨는 집 비예약 기간어 다시  한 번 더 가볼까 고민됩니다.', 43, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '음료도 디저트도 너무 맛있었어요♡♡ 음료는 잘 저어 드셔야 달달하고 시원한 음료를 드실 수 있어요♡♡ 케이크가 진짜 너무 맛있었어요♡♡ 마카롱도 쿠키도♡♡ 야화첩 콜카 다녀와서 지금 기분 너무 좋아요🫶 직원분들도 넘 친절하고!! 암튼 기분좋은 주말이 된 거 같아 행복합니다♡', 15, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), 'This is the second time I’ve visited               두니크 홍대점 and they really know how to decorate and let their visitors experience the world of these characters!', 16, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '진짜 변덕님 최고ㅜㅠ제 마음이 부자되는 느낌인데 그만큼 변덕님 주머니도 든든해지시겠죠 작가님 몸 항시 건강하시고 우리 나겸이 승호 현대물 많이 그려주세용 사랑합니다', 44, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '야화첩X투니크 콜카 후기🐾 변덕작가님의 야화첩 콜카 알림이 뜨자마자 예약대기하고 성공해서 다녀왔습니다! 카페 입구부터  승호와 나겸이를 보자마자 심장이 두근 거렸어용🥲❤️ 직원분들이 친절하게 입장 도와주셨습니다! 들어가자마자 메뉴 먼저 주문하고 (코스터 중복 하나도 없어서 넘 기뻤어용!) 메뉴 사진 찍고 하나하나 다 구경했습니다 ㅎ 진짜 주막처럼 꾸며놔서 나겸이의 망나니 생활이 기억나서 웃겼고 액자 구경할 땐 눈물이 울컥 했어요 ㅋㅋ ㅠ 혼자 가서 우물쭈물 댈 줄 알았는데 혼자서도 재밌게 즐기고 왔어용 궁금한 것도 잘 설명해주시고 인사도 잘 해주셔서 직원분들도 정말 짱짱이였어요! 인생네컷도찍고 진짜 너무 행복한 하루였습니다 ㅎㅎ 투니크에게도 변덕 작가님에게도 넘 감사합니다! 승호야 나겸아 결혼 축하해💕', 24, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '와플보단 크레이프가 맛있었어요. 콜라보카페라 디저트 퀄리티 기대 안했는데 맛있었어요. 음료도 다 괜찮아요. 가격도 괜찮은 것 같아요. 굿즈 품절은 아쉬워요. ㅜ 구경하는 재미가 있어서 좋았어요.', 48, 7, 'GOOD', SYSTIMESTAMP);
