INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '예약자 확인하는건 좋은데 폰주인 본인에게 해달라고 하지 왜 지들 맘대로 폰에 손대나요? 괭장히 불쾌합니다 직원이든 알바든 교육좀 똑바로 시키세요', 3, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '좋아하는 작품과의 콜라보 소식에 예약 하고 다녀왔어요. 투니크는 항상 작품 속 공간을 잘 구현해 주어서 좋습니다. 재미있는 콜라보 메뉴와 공간을 구경하다 보면 시간이 금방 가요.', 43, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '혼자가서 테이크아웃해서 갖고 갔어요. 직원분들도 친절하세요. 콜라보카페라 음식 퀄리티 기대안했는데 맛있어서 놀랐어요. 포도 스파클링은 웰치스 느낌나요. 크레이프는 달달하니 맛있었어요. 디피도 예뻐요!', 20, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), 'Was so excited to visit the Painter of the Night collaboration cafe and it did not disappoint! I love everything about it! Would love to visit it soon again 🥹', 40, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '좋아하는 작품 콜라보카페라서 방문했는데 인테리어가 너무 재밋고 좋았어요!! 팬이 많은 작품이라 함께 즐기는 팬들이 많은 건 너무 좋은데… 확실히 외국인 업자들로 보이는 사람들이 섞여서 특전들 받아가는 게 너무 싫었어요🙂‍↔️ 직원분들도 바쁜 와중에도 나름 거르려고 노력하시는 게 보여서.. 많이 응원함돠🥹', 2, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '좋아하는 작품 콜라보가 열려서 방문했습니다! 예약이 너무 어려워서 방문해서 대기 등록하고 겨우 입장했어요.. 1시간 넘게 기다렸는데 착석 불가 테이크 아웃만 가능하다고 해서 둘러보고만 호다닥 나왔습니다. 디피 너무 예쁘고.. 여유롭게 둘러보고 싶었는데 조금 아쉬웠어요(훌쩍)', 18, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '네번째 방문! 보리 작가님 좋아해서 자주 왔습니다. 이렇게 콜라보 카페 많이 오는 건 처음인 거 같아요~ 메뉴도 다른 콜라보와 비교해서도 제 취향이라 더 좋았어요! 굿즈도 짱귀😍', 367, 85, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '비가오는 날이지만 안내도 빠르고 입장도 바로바로 진행되었습니다. 오늘은 소나무에이드마셨어요. 예상한 그맛 솔의 noon맛 음료였어요. 치즈케이크 생각보다 진하고 맛도 좋았어요.  같은타임 방문객분들하고 중복 포카랑 티코스터 교환도 잘 하고왔어요.  기간이 더 길었더라면 좋았을걸 했어요.', 39, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '짱 귀여움. 친절하심. 2층도 구경가능. 콜라보카페 첨 가봤는데 디피가 예뻐요. 신경 많으쓰신 것 같아서 좋았어요. 앞으로 2-3번 더 갈 것 같아요!', 9, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '좋아하는 작품이라 콜라보 카페 소식 듣자마자 예약, 방문 했어요. 공간도 작품 속 배경을 그대로 옮긴 것처럼 꾸며져 있어서 여러모로 즐겁게 머물다 왔습니다.', 64, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '3명 예약하고 비예약 대기하시는 분들 더운 거 같아서 전 혼자 왔고 3명으로 예약했으니 같이 들어가도 되냐 하니 안된다네요^^ 내가 예약했는데 말이죠ㅋㅋㅋㅋㅋㅋㅋㅋ 합정점은 셔벗 포장해 주길래 여기도 가능하냐 했더니 안된다 하네요 같은 사장 지점만 다른데 홍대점 안되면 합정점 가능하고 합정점 안되면 홍대점 가능?????? 뭔 ㅋㅋㅋㅋㅋㅋ 제발 통일 좀 하고 직원분들 교육 좀 다시 하세요 안 준걸 안 줬다 하지 준걸 안 줬다 하겠습니까??? 투니크 사장과 직원들 때문에 변덕 작가님만 피해 보는 거 같아 너무 마음 아프네요 제가 말로도 했지만 적당히 하세요 작품과 작가님 보고 방문하고 즐기는 거지 투니크 때문에 가는 거 아닙니다 덕녀 호구로 보지 마세요^^', 21, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '타르트 과일이 올라가서 특이해요 !!!! 달다가도 새콤하 신거같은데 달아요 !! ㅎㅎㅎ 좀 퍽퍽하다 싶을때 음료 마시면 완전 최고 👍🏻👍🏻', 69, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), 'Wow… Just incredible attention to details: from dessert styling with shovel until blood stains with detergent on the floor. Movie posters are so cool that I want to take them home! 😅 Cherry cola is unexpectedly awesome.', 71, 11, 'GOOD', SYSTIMESTAMP);
