INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), 'Decoration for pop up is so nice 😊 Also all beverages are tasty. Donuts plating is really interesting and matched the story.', 17, 4, 'GOOD', SYSTIMESTAMP);
