INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '3명 예약하고 비예약 대기하시는 분들 더운 거 같아서 전 혼자 왔고 3명으로 예약했으니 같이 들어가도 되냐 하니 안된다네요^^ 내가 예약했는데 말이죠ㅋㅋㅋㅋㅋㅋㅋㅋ 합정점은 셔벗 포장해 주길래 여기도 가능하냐 했더니 안된다 하네요 같은 사장 지점만 다른데 홍대점 안되면 합정점 가능하고 합정점 안되면 홍대점 가능?????? 뭔 ㅋㅋㅋㅋㅋㅋ 제발 통일 좀 하고 직원분들 교육 좀 다시 하세요 안 준걸 안 줬다 하지 준걸 안 줬다 하겠습니까??? 투니크 사장과 직원들 때문에 변덕 작가님만 피해 보는 거 같아 너무 마음 아프네요 제가 말로도 했지만 적당히 하세요 작품과 작가님 보고 방문하고 즐기는 거지 투니크 때문에 가는 거 아닙니다 덕녀 호구로 보지 마세요^^', 6, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '오늘이 마지막 방문 ㅠㅠ 우연히 자리가 생겨서 급하게 예약하고 왔어요! 11시 59분에 겨우 했다는..ㅋㅋ ㅠ 동생이랑 왔는데 쪽팔림을 감수하고 메뉴까지 알차게 먹고 갑니다! 매번 갈때마다 새롭고 좋았어요 ㅠ친절하게 맞아주셔서 감사드려요! 동형 흥해라! 박노덕 작가님 그리고 직원여러분..이렇게 좋은 카페 열어주셔서 정말 감사드려요 ! 다음에 콜라보할 카페도 기대할게요!', 117, 24, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '못갈 뻔 했는데 늦게나마 도착해서 1층만 구경했는데도 정말 좋았어요 !! 늦어서 다 못본게 아쉬웠어요 크레이프도 장미 무슨 음료도 맛있었어요 근데 크레이프가 엄청엄청 달았는데 장미음료랑 같이 마시니까 좀 나았어요 근데 장미음료도 안섞고 시럽이 가라앉아있어서 제대로 안섞이면 왕 달더라구요 잘 섞어야해요 컵 둘레에도 설탕이 쭉 발라져서 까딱하면 당 폭발 ... 또 방문해서 2층도 구경하고 포토부스도 이용하고싶어요 !!', 8, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '넘 모 재 밋 당,, 🤭🤭🤭 내생애 최고의 행운 콜라보 카페가 열린다는걸 보고... 왕복 7시간을 운전해서 왔어용 🫠... 너무 예쁘게 꾸며놓으셔서 구경할 맛 나더라구요 >.< 자주 가지 못해서 너무 아쉽지만.. 다다음주 한 번 더 방문할 예정입니당 🥹 흑흑 서울 사람들 시기질투되,,, 😢', 23, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), 'I visited with my friend. It was really new experience for her but we both really enjoyed ☺️ Shoveling dessert is awesome 😂', 21, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '좋아하는 작품 콜라보 카페 마지막 날이라서 방문했어요~! 마지막날까지 예약이 꽉차서 테이크아웃해서 갔지만 예쁘게 잘 꾸며주시고 운영해주셔서 감사합니다!', 2, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '야화첩 첫날이라 실수도 있었는데 직원분의 빠른대처로 기분이 좋아졌습니다 다른직원분도 그 직원분 같았으면 졸을텐데...그분말곤...거의 대부분이 불친절합니다 단기알바든 장기알바든 근로시간은 꼭 준수해서 지켜주셨으면 합니다 그런 직원들 때문에 친절한 직원분도 같이 욕먹는겁니다 거기다 투니크욕은 배가 되고여', 5, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '와 진짜..많이 온당.. ㅠㅠ 벌써 이번주 일요일이 마지막이라니 ㅠㅠ 이번주 일요일에 가고 싶은데 예약을 못해서 대기를 좀 해야할 것 같네용 ㅠㅠ 아무튼 벌써 세번째 방문! 정말 좋았어요 ㅠㅠ 방문포카 진짜 예쁘더라구요!! ㅠㅠ 갔다오고 지하철에서 리뷰쓰는게 벌써 일상이 되어버림 ㅠㅠ 카페 너무 친근하고 유리 선우가 너무 이뻐여 ㅠㅠ 앞으로도 좋은 작품 많이 많이 콜라보 해주세요!!😍😍', 38, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '6월2일 마감했던 직원 근무태도가 개그지같았음 예약하고 늦게가서 예얔금 3000원 못받는거 감안하고 혹시나 해서 쿠폰이나 쿠키 못사면 굿즈라도 사야지하고 35분쯤 갓으나 둘다 포스마감했다고 아무것도 못함 9시 마감이고 포카만 8시50분이지 그전엔 마감하면 안되는거 아닌가요?', 44, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '오랜만에 방문했어요~~ 캐릭터가 넘 귀여워요😍 ''일기예보적 연애'' 라는 웹툰을 보지 않아서 잘 모르겠지만, 드라마도 있는 것 같더라고요!! 카페에서 좋은 노래가 흘러나왔는데, 드라마 ost 같았습니다😊 노래 진짜 좋았어요🥰 디저트도 맛있었고 즐거운 시간 보내고 왔네요 ㅎㅎㅎ', 96, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '직원 교육 똑바로 하셨으면 좋겠습니다. 본인들이 판매 후 마그네틱 제거 제대로 하지 않았으면서 일행이 퇴장시 도난경보음이 울리니 "훔쳐?"라고 큰 소리로 대화하며 무안을 줘서 지켜보는 입장에서 정말 민망했습니다. 작은 돈도 아니고 십수만원을 쓰고 이런 대접 받는 것을 지켜보니 정말 불쾌했네요. 작품 컨셉에 맞게 예쁘게 꾸며놓고 굿즈로 수익창출만 하면 끝인가요? 이 카페에 찾아오는 사람들은 작품에 대한 애정으로 먼 곳에서 시간을 내어 찾아오는 고객들입니다. 설령 의심이 들었다 할지라도 차분히 영수증을 요구하고 조용히 확인 절차를 거치면 안 됐던 걸까요? 마치 도둑 취급을 하는 것 처럼 느껴질 정도로 직원들의 대응이 정말 실망스러웠습니다. 좋은 추억마저도 망쳐버린 것 같아 불쾌합니다.', 72, 16, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '너사대 동형 너무 재미있게 봤는데 콜라보 카페까지 가게 됐어요. 콜라보 메뉴 맛있고 굿즈랑 혜택 다양해서 좋았어요! 직원분들도 친절하셨고 카페 인테리어도 잘 구성된 거 같았어요. 사정상 한 번만 방문한 게 아쉬울 정도예요ㅠㅠ 그래도 잘 구경하고 좋은 시간 보내고 온 거 같아서 정말 만족합니다:)', 79, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '아주 예전에 비밀사이 콜라보할 때 와보고 오랜만에 갔었는데 디저트도 예뻐서 굿즈랑 찍는 맛이있었네요ㅎㅎ 굿즈들 가격이 좀 나가는데.. 아크릴류들이 양면접합이 아닌게 좀 슬펐어요..🥲 태서 귀 흰배경 누락도 그렇고... 다음부턴 굿즈 퀄리티에 더 신경 써주시면 좋을 것 같아요.', 21, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '콜라보때문에 온지 벌써 몇번째이지만 이번 콜라보음식은 또 특별한 맛이에요!! 엘더플라워 에이드는 대체 무슨 맛일까 궁금했는데 잔잔하고 맛있어요!!! 추천합니당', 58, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '2층에 인생네컷 용지부족인지 고장인지 사진다찍고 안나와서 문의드렸고  고치는데 오래걸릴꺼같으면 말좀해주시면 1층에서 기다렸을텐데 2-30분 그앞에서 계속기다렸구요... 그거에대해서 사과한마디없고 고쳤다고해서 다시 촬영하고 또 용지안나옴 ㅠ 카운터가서 환불요청시에도 제대로된사과도없고 ㅠㅠ 콜카만아니였으면 안갔을듯한 서비스입니다~', 70, 13, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '잘 다녀왔습니다. 본인이 원하는 하에 실제 디져트나 음료 대신 쿠폰을 주는 것이 마음에 듭니다. 간혹 이벤트성을 위해 사버리고는 길가에 아무렇게나 버리는 것을 종종 봐왔기에 이런 시스템이 있는 것이 좋다고 생각합니다. 직원 분들은 바쁜 와중에도 친절하고 잘 처리해줍니다. 나중에는 삼삼한 맛의 음료나 디저트가 나왔음 좋겠네요.', 40, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '이번으로 두번째 방문! 여전히 청결하고 음식도 빨리나와서 좋았어요! 굿즈 너무 많이 사서 포카 벌써 다모움…ㅋㅋㅋ큐ㅠㅠㅠ 다음에 또 방문하겠습니다! 감사했습니다~직원분들', 19, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '방문중 불쾌한 경험하여 리뷰 작성합니다. 11시에 방문 및 구매 후 6시쯤 재방문하여 양해 구하고 전시존만 사진 촬영 하고 나왔는데요, 도난방지기 알림이 울려 굿즈와 영수증 내역 확인 시켜 드렸습니다. 여기까진 충분히 이해 하고 바로 협조드렸습니다. 그러나 주방에서 직원분들끼리 들으라는듯 ‘훔쳐?’ 등의 도둑 취급하는 말을 하신 것은 상식적으로 이해가 가지 않네요. 사실상 직원분의 과실로 택이 제거 되지 않은건데, 왜 제가 불쾌하고 무례한 말을 들었어야 했는지 궁금합니다. 작품을 사랑하는 마음으로 찾아갔다가 불쾌한 응대로 작품에 대한 애정마저 변색되지 않도록 주의 부탁드립니다. 저와 같이 불쾌한 경험 겪으시는 분이 발생하지 않도록 공익 차원에서 해당 글을 작성하며, 트위터에 작성하려다 우선 후기란에 올립니다', 60, 16, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '좋아하는 작품 콜라보 카페가 있어서 방문했습니다~! 이번에도 작품에 알맞은 인테리어랑 메뉴가 너무 좋았어요! 특히 커피 메뉴를 콜라보 메뉴에 넣어주셔서 너무 만족스랍습니다!', 22, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '갈 때마다 직원들 친절하셔서 너무 좋았는데.. 방문하시는 분들 중.. 자식이랑 남편 데려와 서너자리 차지 하고 앉아 계셔서, 예약했음에도 자리 잡기가 힘들었습니다. 콜라보 시작한 주는 예약자만 입장 가능한 거라 오버 부킹은 아닐 듯 한데..... 아무튼 즐기시는 건 좋은데 방문하시는 분은 음지 장르라는 인식과 (꾸금 콜라보 카페에 미취학 아동 데려오는 건 좀 그렇잖아요..) 예약 좌석 관리 부탁드립니다.....', 22, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '오랜만에 방문했어요~😘 밤 라떼랑 소나무 에이드 메뉴가 넘 궁금해서 먹어봤습니다! 밤 라떼는 바*바 맛이 났고, 소나무 에이드는 솔*눈 맛이 났어요😁 동생은 캔디 스무디 먹었는데, 몽글몽글해서 넘 이쁘더라구요🥰 밤 라떼에 다람쥐(?) 아트도 귀여웠어요😍 ''스윗스팟'' 콜라보 운영 내일이 마지막이던데, 다음 콜라보도 기대되네요😊', 93, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '달콤한남자, 영원한 계약 콜라보카페로 방문했어요! 1.6일자로 타로카드 입고됐어요. 다들 가보세요~ 웹툰 두개여서 어떻게 배치했을까 했는데 특징 딱 잡아서 넘 좋게 배치했더라구여ㅠㅠ', 18, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '예약하고 갔는데 비예약자에게 심지어 업자에게 좋은 자리를 양보해야 한다는 게 솔직히 이해가 안가고 불쾌했다. 계산대에 있는 여성 직원분이 표정부터 말투까지 굉장히 불친절했다.', 20, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '너무너무 컨셉에 맞는 콜라보카페였구요 굿즈들이랑 카페 디저트메뉴가 좋았어요! 특히 전시존이 bbbb 재방문할거고 그때는 다른메뉴먹어보려구요.', 43, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '좋아하는 작가님의 작품으로 콜라보 카페 이벤트를 진행한다고 해서 방문! 방문할 때마다 느끼는 거지만, 음식 맛을 포함하여 아쉬운 점이 참 많은 곳. 다음에는 좀 더 발전한 공간이 되어있기를 바라는 마음입니다.', 11, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '전시도 굿즈도 다 좋은데 음식이 너무 맛이 없습니다. 이번 콜라보 메뉴인 와플와 아인슈패너 뱅쇼를 주문했는데, 와플은 해동을 제대로 안 했는지 칼도 잘 안 들어가는 밀가루 덩어리에 한 입 먹고 쓰레기통행, 아인슈패너는 아인슈패너가 어떤 음료인지 제대로 모르는 사람이 만든 것 같네요. 우유를 살짝 탄 아메리카노 위에 휘핑크림만 올려놓은 걸 누가 아인슈패너라고 합니까?? 코스트코 음식을 가져다 팔아도 이거보단 나을 것 같네요, 필히 개선하세요. 진짜 끔찍합니다. 그나마 괜찮은 뱅쇼랑 쿠키만 디립다 주뮨해서 굿즈 받아갑니다.', 71, 11, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '사전 예약을 했고 모든 것이 좋았지만 마지막에 위층에서 사진을 찍으려고 줄을 서서 예약한 시간을 5분 초과했습니다. 아래층으로 내려왔을 때, 2만4천원 가치의 포장된 음식이 시간 초과로 직원에 의해 버려진 것을 발견했습니다. 직원에게 물어봐도 만족스러운 답변을 받지 못했고 사과도 없었습니다. 논쟁 끝에 음식을 다시 만들어 주긴 했지만 다음 번에는 가지 않을 것입니다.', 4, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '투니크에서 제공해주시는 음료나 푸드는 콜라보 카페인 걸 감안해서 전문성이나 특별하게 뛰어난 맛을 기대하지 않습니다만... 이번엔 좀 당황스러웠어요. 아인슈페너는 거의 아무맛도 나지 않고, 뱅쇼는 포도쥬스를 데워서 식힌 느낌이었어요. 제일 심각한 건 와플이었는데 절반은 칼로 썰기도 힘든 정도로 딱딱해서 씹는데도 고생을 좀 했습니다. ㅜㅡ 뛰어난 맛까지는 바라지 않으니 기본은 해주셨으면 하는 바램입니다. 포토존은 항상 작품을 이해하고 꾸며주시고, 주문을 받으실 때나 판매시에도 친절하게 대응해주셔서 항상 기대하며 방문하고 있습니다. 그저 오래오래 자리에 있어줬으면 하는 바램입니다.', 49, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), 'I really like toonique collaboration cafe. The dessert are also really good.', 28, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '역시 음식은 언제나 별로입니다 이번에 와플은 특히 딴딴해서 포크가 안박히고 썰리지 않아서 당황했습니다 하지만 음식을 먹으러 가는건 아니니… 굿즈존이 이번에는 꽤나 마음에 들게 만들어졌습니다.', 11, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '너무 좋아하는 웹툰 콜라보였어요~ 이번 콜라보도 투니크는 완벽하네요💜 덕분에 갓작을 즐겁게 즐길 수 있었습니다😇 직원분들도 항상 친절하시고 매장도 깨끗 메뉴도 너무 맛있었어요! 콜라보카페 마감전에 레몬타르트 ㅠㅠ 얼른 다시 들어왔으면 좋겠습니다🥹 #디파인더릴레이션십 #DTR #콜라보카페 #플로나 #차다 #봄툰 #투니크', 46, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '디저트도 맛있고 카페자체도 깨끗하고 좋아요~! 직원분들도 매번 친절해서 항상 즐겁게 갈 수 있어서 좋습니다❣️ 예쁜 콜라보 카페 열어주셔서 감사합니다!', 124, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '좋아하는 작가님과의 콜라보라 들어가기 전부터 설레고 들어간 후론 너무 좋았습니다. 다만 음료와 md를 구매하고 이벤트를 참여 한 후 자리에 앉아 음료를 마시던중 직원분들이 하는 얘기를 들었습니다. "내 애가 저러면 난 저꼴 못 봐" 등에 말들이 오갔습니다. 그 자리에서 미성년자로 보이는 사람은 저 밖에 없었고, 제가 md를 구매 후 그 대화가 오간 것이 우연이라기엔 뭔가 이상했습니다. 선정적인 md가 있던것도, 미성년자에 출입이 제한 되었던것도 아니였습니다. 정당하게 예약하고 간 자리에서 저런 소리를 들으니 매우 불쾌했습니다. 좋아하는 작가님에 굿즈와 그림과 캐릭터를 보러간 것이고, 무례를 범하지도 않았습니다. 직원분들께 "감사합니다" 하며 md를 받은 제가 너무 한심하게 느껴지네요...', 44, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '주말 토 일 17일 18일 3시에 방문했는데, 직원분들이 너무 친절하십니다. 정말 친절하셨어요. 덕분에 재밌고 편하게 놀다 왔습니다.', 90, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '음식은 솔직히 그럭저럭입니다....케이크 완전 달아요 음료는 그냥 평범한 맛. 포토존은 엄청 잘꾸며두었더라고요 눈호강하고 갑니다 ~', 33, 1, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '두번째 방문이에요! 시간이 좀 지나서 후기를 남기는데 콜라보카페 세심하게 준비해주시고 카페에서도 친절하게 대해주셔서 행복한 기억과 감정이 여전히 남아있어요. 좋은 추억 만들 수 있게 콜라보카페 열어주셔서 정말 감사합니다🥰 메뉴를 쿠폰으로 대체해서 받을 수 있다는 점과 일반 카페 메뉴로 변경해서 주문할 수 있다는 것도 너무 좋았어요!', 29, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '감 스무디 진짜 정말 맛있었더라구여...예쁘게 꾸며서... 사진 많이 찍었어요...근데 쿠키 다 품절되어서 슬퍼여 ㅠㅠ 100점 만점 99.9점', 17, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '시킨 메뉴 전부 너무 맛있었고 직원분들도 정말 친절하셨어요 :) 내부 전시가 잘 되어있어서 사진 찍기도 좋았고 1,2층 다 너무 예뻐서 구경하기도 좋았어요! 콜라보 카페 첫 방문이었는데 좋은 기억만 가득 남겨주셔서 감사해요. 콜라보가 아니더라도 나중에 다시 방문하고 싶을 정도로 좋았어요 !', 127, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '진짜 이런시스템으로 운영하실거면 장사하지마세오 메뉴도 쓰레기메뉴....덕후들이 호갱으로 보이죠?? 증정품 수량도 늘 야박하게뽑아서 .... 그깟종이 원가 얼마나 한다고....장사마인드 진짜.... 게다가 굿즈 품질도 최악 워터글리픽 워터 새고 아크릴이랑 키링 인쇄부분 코팅 1도 안하고 공기노출시켜놔서 좀만쓰다보면  다벗겨지고... 이게 28000원이라고? ㅋㅋㅋㅋㅋ 진짜 호구로 아네 우리도 눈달렸습니다', 37, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '예쁘게 잘 꾸며놨어요!!! 근데 마지막 타임 디저트랑 커피는 정말 최악이네요... 열심히 티켓팅하고 주말에 시간내서 왔고, 좋아하는 작가님 콜라보카페라 기대하고 왔는데 아무리 굿즈를 준다고 해도 그렇지... 좀 심하네요. 콜라보카페 여러군데 가봤는데 맛은 없어도 먹을 수는 있는 정도 였는데... 붕어빵이 꺼내놓은지 오래됬는지 말라 비틀어져서 버석버석한걸 8000원주고 사먹고 커피는 맹맹하니 커피가 스쳐지나간 맛... 아무리 마감시간대여도 그렇지 메뉴 점검 중간중간 한번씩 해주시고 팔아주세요~ 오전에 왔었을때랑 마지막타임 왔을때랑 맛차이 너무 심하네요.', 39, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '오늘 처음방문했는데 생각보다 너무 잘꾸며져 있어서 놀랐어요!!  직원분도 너무친절하셔서 처음가서 긴장한게 사라졌습니다!! 또 방문할께요♡♡', 27, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '콜라보 카페 중에 가장 좋은 것 같아요❣️ 독채로 있는 카페라서 구경하기 너무 좋구요 매장도 항상 깨끗해서 좋습니다! 메뉴들도 맛있고 좋았어요! 🌊 ‎⁦‪#너를찾는파도‬⁩ ⁦‪#너찾파‬⁩ ⁦‪#콜라보카페‬⁩ ⁦‪#청연‬⁩ ⁦‪#투니크‬⁩', 42, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '그저 천국 그 자체... 인테리어도 잘 해놓으셨고 무엇보다 굿즈를 너무 잘 뽑았어요.. 스콘은 맛이 좀 아쉬웠지만 잼이 맛있었습니다 메뉴는 말해뭐해요 콜라보 카페는 우리 애들 보러 가는거죠  뭐...', 72, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '스윗스팟 콜라보카페 너무 멋지고 행복했어요💙 스윗스팟 드씨 주연 성우님들 안내멘트도 들을수 있어서 더 특별하고 환상적이었습니다^_^ 윤건영 남원우 영원히 사랑해!!!!! 🥹🥹🫶🏻🫶🏻🫶🏻', 121, 22, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '역시나 투니크... 운영방식 점점 이상해짐. 첫날 예약자도 굿즈 못삼 비예약자들이 앞타임에 다쓸어가서 품절인게 말이되나? 그럴거면 예약을 안받는게 어떠신가요?', 9, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '작년부터 방문했었는데 디저트 퀄리티가 더 좋아진 것 같습니다. 상큼한 음료들은 디저트랑 잘 어울렸고, 언제나 예쁘게 꾸며지는 메뉴들은 보는 즐거움도 더해집니다. 또 작품을 그대로 옮겨온 듯이 정성껏 디피된 카페를 보면 독자로서는 정말 행복하고, 직원분들도 늘 친절하셔서 항상 감사드립니다. 다만 콜라보 기간이 길지 않은데도 쿠폰을 그 기간 내에만 촉박하게 사용해야 하는것과 이건 개인적인 의견으로 제가 가는때에는 디저트가 단 메뉴만 있던게 조금은 아쉽습니다. 이건 여담이지만 직원 한 분은 포카 인증시 약간은 융통성을 보여주시길 바라는 마음입니다. 딱 봐도 대신해 주는 건데 얼굴을 비추고 일행임을 알렸음에도 굳이 사람을 다시 불러서 본인이 보여주라는 식은 자주 방문하면서 적지않은 돈쓰고 참 신선한 경험이었습니다.', 17, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '#겨울지나벚꽃 #겨지벚카페 #콜라보카페 #밤우 #투니크 ''겨울 지나 벚꽃'' 콜라보 첫날이라 학교 끝나자마자 바로 왔습니다😘 게다가 오늘 해봄이 생일이라서 꼭 오고 싶었고, 학교가 4시 10분에 끝나서 5시 타임에 예약하고 왔네요☺️ 여태 나왔던 케이크 중에 이번 케이크가 젤 맛있었어요🥰 음료도 맛있었고, 동생이 엄청 좋아했어요😄 포토카드도 구매하고 왔는데요!! 이번엔 세트로 없고, 랜덤만 있더라구요😭 그래서 15개 구매했고, 다행히 10장 다 모았네요😁 포토카드 정말 예쁘게 잘 나온 것 같아요😍 다른 MD도 다 구매하고 싶었는데, 최근에 용돈을 너무 많이 써서 포토카드 밖에 구매하지 못했네요😂 열심히 용돈 모아서 다음에 또 방문할 때 다른 MD도 구매할 거예요😚 해봄아, 생일 축하해🎉', 83, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '#겨울지나벚꽃 #겨지벚카페 #콜라보카페 #밤우 #투니크 오늘 ''겨울 지나 벚꽃'' 콜라보 진행 마지막날이라 ''로즈 체리 케이크'' 먹으러 왔어요😊 로즈 체리 케이크 정말 맛있었는데, 더이상 못 먹으니까.. 마지막으로 먹으러 방문했습니다😂 아쉽지만, 그래도 맛있게 잘 먹고 왔어요🥰 원하는 포토카드를 얻기 위해 오늘도 랜덤 포토카드 10개 구매해서 바로 뜯어봤는데요!! 운이 좋게도 원하는 게 3장이나 나왔습니다😆 5만원당 SET 1종 증정되는 것도 원하는대로 ''겨울 SET''가 나왔습니다😄 그래서 기분이 엄청 좋았어요😁 오늘이 마지막이라 아쉽지만 그래도 좋았네요☺️', 14, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '#겨울지나벚꽃 #겨지벚카페 #콜라보카페 #밤우 #투니크 갈 때마다 힐링하고 오는 듯한 기분이 들어요☺️ 맛있는 디저트도 먹고, 이쁜 MD도 구매하고, 눈호강(?)도 하고요🥰 우리 해봄이랑 태성이 넘나 귀엽고 이쁘고 잘생겼고 그냥 다 좋네요❤️ 직원분들 다 정말 친절하시고 작은 질문 하나에도 친절하게 답변해주셔서 좋았어요😄 다음 콜라보 작품으로 무얼 하실지 모르겠지만, 벌써부터 기대되네요😊', 23, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '#겨울지나벚꽃 #겨지벚카페 #콜라보카페 #밤우 #투니크 겨울 지나 벚꽃 넘 재밌게 봤는데, 이렇게 콜라보 카페로 진행해 주셔서 정말정말 좋아요🥰 이번 디저트도 역시 넘 맛있고, MD도 하나같이 다 예쁘고 귀여워요😍 오늘 1주차 프린팅박스 코드 마지막날이라 가서 뽑고 왔어요❤️ 줄이 길었지만, 기다린 보람이 있네요☺️ 2주차 때도 꼭 뽑을게요~😘', 48, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '#애인셔틀 #애인셔틀카페 #콜라보카페 #임애주 #투니크 안녕하세요! 저는 비밀사이 때부터 ''투니크''라는 카페를 알게되어 방문했습니다. 비밀사이 콜라보가 끝난 뒤에 노리즌 콜라보가 시작되서 디저트를 먹으러 갔었는데요. 이번에도 역시 디저트를 먹으러 왔는데, MD들이 넘 예뻐서 돈을 왕창 쓰고 왔네요😂 그래도 MD가 귀엽고, 예쁘고, 사랑스러워서 후회는 없습니다😄 디저트는 빔사 때부터 와서 웹툰 바뀔 때마다 먹었는데요! 정말 다 맛있는 것 같아요☺️ 직원분들 다 정말 친절하시고 좋아요🥰 언젠가는 제가 원하는 웹툰도 콜라보 진행해 주셨으면 좋겠어요🙏 그때까지 자주 방문하도록 하겠습니다😘 (3월 이후로는 개학하니까 많이 못올수도 있겠네요😭 그래도 가끔이라도 방문할게요😁)', 54, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '항상 어떻게 꾸며놓으셨을까 기대하면서 가게 됩니다😏 분명 같은 공간인데도 침실이 되기도 하고 방송실이 되기도 하고 야영지가 되기도 하는 마법 같은 곳이에요🥰 굿즈도 다양하면서 예뻐요', 31, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '너무 좋았어요! 음료도 생각보다 맛있었어요! 디피존도 멋있구요. 쿠키는 너무 먹기 아까워서 아직 안먹어 봤지만 맛있어 보여요! 굿즈도 많았고 눈도 즐거웠습니다~', 7, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '#애인셔틀 #애인셔틀카페 #콜라보카페 #임애주 #투니크 안녕하세요~ ''애인셔틀 콜라보 카페'' 5번째 방문입니다😊 케이크는 품절되서 못 먹었고, 카스테라만 먹고왔어요😂 그래도 맛있었습니다🥰 다 먹고나서 이벤트 포토카드 받아왔는데요!! 엄마랑 동생이랑 같이 가서 9장 받았고요, 9장이 다 다른게 나온건 처음이네요😄 MD도 다 이쁘고, 귀엽고 좋네용😍 (MD는 전에 왔을 때 구매한 겁니다😘) 다음 콜라보는 ''겨울 지나 벚꽃'' 이던데, 벌써부터 기대되요😆', 85, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '그냥 갈때마다 최악이란말밖에....2호점을 낸다니 .... 마테 양 점점 줄어드는거 판매할때는 스티커로 가려서 일부러 두께 가림...교묘함 장사 그렇게 하지마세요 엄청남나보네', 24, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '#노리즌 #노리즌카페 #콜라보카페 #솔티 #북큐브 #투니크 노리즌 콜라보 카페 2번째 방문입니당😘 일단 직원분들이 정말 친절하세요😊 바나나 케이크는 처음 먹어보는데, 넘 맛있었어요🥰 MD도 구매하고 왔어용😁 이번엔 스탬프 모으면 띠부띠부씰도 주는데요. 6개 다 채우고, 또 받아 왔네요😄 내일 또 방문 예정이랍니다~😉', 13, 5, 'GOOD', SYSTIMESTAMP);
