INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '의자불편함 직원들이 너무 바빠서 그런지 주방은 특히 정신이 없어보이고 친절한 느낌은 아님 의영이 감 스무디 진짜 너무너무너무 달기만해서 다 버렸어요', 44, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '#애인셔틀 #애인셔틀카페 #콜라보카페 #임애주 #투니크 갈때마다 엄마랑 동생이랑 같이 방문했었는데, 오늘은 혼자 방문했어요😁 방문 때마다 디저트를 많이 주문해서 코스터는 벌써 다 모았고요😆 방문 이벤트 포토카드는 오늘 한 장 못 모은 것도 운 좋게 나와서 다 모았어요🥰 (8번째 포토카드 받기가 참 어려웠네요😂 한 번도 안 나오다가 오늘 드디어 받았어요🥳) 스탬프도 3장이나 모아서 띠부띠부씰 3개나 받았어요😘 다음엔 어떤 콜라보가 진행될지 기대되네요!! 언젠가 한 번은 꼭 제가 원하는 웹툰과 콜라보 해주시길 바래봅니다🙏', 20, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '#애인셔틀 #애인셔틀카페 #콜라보카페 #임애주 #투니크 ''애인셔틀 콜라보 카페'' 첫째날🥳 오픈 첫날에 오는 건 처음인 것 같아요~ 이번 디저트도 역시 맛있네요☺️ MD도 다 넘 예뻤어요😍 다 구매하고 싶었지만, 용돈이 넉넉하지 않아서 다 구매하진 못했네요😂 그래도 다음에 또 방문할 거니까 조금씩 다 모으면 되겠죠?😅 이번 콜라보 웹툰도 최고네요👍 이렇게 콜라보 카페를 진행해 주셔서 감사드립니다🙇‍♀️', 10, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '너를찾는파도 콜라보 카페 다녀왔습니다. 너무 예쁘게 꾸며놓으셔서 카페 전체가 포토존이고 방울이 놀이방에서는 그 귀여움에 정신을 못차렸습니다.', 68, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '디저트도 맛있고, 무엇보다 매장이 청결하고 직원분들이 친절해서 좋았습니다❣️ 웹툰에 나온 장면들이 구현된 게 너무 귀엽고 반가웠어요🥹 #범을길들이는요령 #범요령카페 #콜라보카페 #콤 #봄툰 #투니크', 34, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '#애인셔틀 #애인셔틀카페 #콜라보카페 #임애주 #투니크 애인셔틀 콜라보 카페 3번째 방문입니다~😘 오늘은 시간이 없어서 많이 못 먹었네요😥 그래도 맛있었습니다🥰 이벤트 포토카드를 아직 다 모으지 못해서 또 방문 예정이랍니다~😚 다음 콜라보 때는 부디 제가 좋아하는 웹툰으로 콜라보가 진행되면 좋겠네요😄', 8, 4, NULL, SYSTIMESTAMP);
