INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '비밀사이 콜라보 카페 이후 오랜만에 방문했습니다🎉 콜라보 하는 웹툰이 바뀌어서 디저트도 바꼈는데, 바뀐 디저트도 정말 맛있었습니다😊 오랜만에 갔으니 MD도 구매하고 왔어요😉 ''노리즌''이라는 웹툰은 제목만 알고 아직 보지는 않았지만, 그래도 좋았어요😄 다음에 재방문 예정입니다❤', 0, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '혼자가도 좋아요~ 물론 주문한 양이 혼자 먹기엔 많았지만❣️ 갈 때마다 기분 좋게 머물 수 있어서 좋아요 #범을길들이는요령 #범요령카페 #콜라보카페 #콤 #봄툰 #투니크', 36, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '#노리즌 #노리즌카페 #콜라보카페 #솔티 #북큐브 #투니크 오늘 또 왔어요~!! 세트 메뉴 다 먹어봤는데요. 저는 개인적으로 체리콕 에이드랑 쿠키 앤 크림 케이크가 젤 맛있었어요😋 MD를 다 구매하지 못하여 아쉽긴 하지만, 이벤트 포토카드는 다 모았네요😉 스탬프도 3장 다 모아서 띠부띠부씰도 3개나 얻었네용~😆 월요일, 금요일, 오늘 토요일 이렇게 3번 방문했어요😁 다음 웹툰 콜라보 할 때도 방문 예정 입니다~😘', 45, 7, 'GOOD', SYSTIMESTAMP);
