INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '웹툰 좋아해서 왔어요! 코라보 이벤트 메뉴 상품들 다 좋아요~ 푸드 맛있고 굿즈들은 다 소장가치 1000% 👍 넘 이뻐요 방울이 놀이방 볼수있어서 행복했어요😍', 1, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '1. 스탭분들이 뭔가를 누락하셔서 여러번 카운터에 말씀드리게 되었는데 조금 더 신경써주셨으면 좋겠습니다 (특전 종이라든지 메뉴가덜나온다든지) 2. 방문포카 수령하는 걸 구매줄 외에 따로 마련해주셔도 좋을듯 합니다. 구매줄뒤에서 기다려 받는데 너무 오래걸려요 3. 디저트류가 다 단데 전반적으로 음료도 다 달아서..아직 두 작품밖에 안다녀온 입장이지만 음료중에 달지않은 음료도 하나 껴주셨으면 좋겠습니다', 37, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '진짜 너무 하세요 ㅡㅡ 3000원 예약금 차감 못했으면 당일은 해주셔야하는거 아닌가요? 맨날 하는일 까먹으세여?? 그럼 물어라도 보셨어야죠 1시~8시까지 있었는데 그걸 말 못ㅗ하세요? 포카인증은 사람잘보고 말하면서 왜 예약은 잘 모르고 안해주세요???당일 갔는데 차감안된다는건 또 첨보네 진짜 웃겨요 일 참 잘하시고 기분 더럽네요', 29, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '평일이라 그런지 걱정했던것보다 사람이 많지 않았다. 내 입맛에 밀크쉐이크는 좀 달게 느껴졌지만 그냥.. 내가 이 공간에 있다는 것 만으로 행복해졌다..♥︎', 28, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '벌써 네번째 방문입니다😚😚 오늘은 일러스트 색지 세트를 사왔어요😆 다온이 넘 이뻐요😍😍 이렇게 사랑스러운데!! 성현이, 재민이, 수현이가 어떻게 안좋아 할 수가 있겠습니까😊 결말이 좀 그렇긴 했지만.. 외전을 기대해 보겠습니다😉 드라마도 빨리 나왔으면 좋겠네요🙏 ''비밀사이'' 정말 사랑해요❤❤❤', 64, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '매번 다른 컨셉의 공간활용이 좋아요! 다만 예약금이 다른카페에 비해 비싼데 당일취소가 안되는점. 메뉴쿠폰을 해당콜라보기간에만 쓸 수 있다는 점 (다른 콜라보 카페보다 기간이 짧은데 타 카페는 쿠폰기한을 더 길게 발급해 줌) 스탬프는 왜 합산이 안되는지.. 딱히 안될 이유가 없다고 생각하는데 아무튼 이런 단점이 개선되면 좋겠어요... 물론 메뉴의 맛도..☆', 65, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), 'Nice cafe and staff! It was well decorated and got to take tons of cute photos. The food and drinks were delicious!', 46, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '친구랑 처음으로 가봤는데 너무 좋았어요. 분위기도 좋고 디저트와 음료는 맛있었어요. 제가 좋아하는 웹툰 이벤트 때 왔으니 너무너무 좋아요. 다음에는 또 올게요 ~', 29, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '정말...덕후들 마음 바로 아시고 대박적인 인테리어와 소품들였어요ㅠㅠㅠ N차 방문이어질 것 같습니다!!음식도 맛있고 음료는 이뻐서 어떻게 먹어야 할지 의문이 들정도ㅠㅠㅠ', 39, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '오늘 세번째 방문합니다😘 오랜만에 갔더니 새로운 MD가 있길래 바로 get 했습니다😎 진짜 너무 행복했어요🥰 리뷰 올릴 때마다 적는 것 같지만.. 직원분들 다 친절하시고, 디저트도 정말 다 맛있습니다☺️ 방문 안해보신 분 계시다면 한번쯤 방문해 보셔도 좋을 것 같아요😄 내년 1월 1일까지 운영합니다! 기간 얼마 안남았으니 얼른 예약하세요😉 (※광고 아닙니다!) #비밀사이 #비밀사이카페 #맥퀸스튜디오 #카카오웹툰 #오디오웹툰 #투니크', 13, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '솔직히 누가 여기 디저트먹으러 오겠냐만은 그래도 패스츄리맛은 좀 선넘었음...크림도 주고 아이스크림도 주는 이유 : 빵이 진짜 퍽퍽함.... 크림+아이스크림으로 녹여먹어도 힘듦 진짜 음료는 그래도 괜찮던데..', 37, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '#겨울지나벚꽃 #겨지벚카페 #콜라보카페 #밤우 #투니크 금요일마다 학교가 끝나면 집이 아닌 투니크로 하교합니다~☺️ 일주일동안 학교에 가면서 지쳐있던 마음을 투니크에 와서 맛있는 디저트를 먹고, 이쁜 해봄이와 태성이를 보며 힐링하고 집에 돌아갑니다😄 오늘도 MD 10만원어치 사왔습니다😅 뭔가 아까워서 개봉은 안하고 있지만, 개봉하지 않은 채로 잘 간직하도록 하겠습니다😁 3/26 일요일에 ''겨울지나벚꽃'' 콜라보 카페가 종료된다니 아쉽네요😥 특히 ''로즈 체리 케이크'' 정말 맛있었는데, 이제 못먹게 되니 많이 아쉬울 따름입니다😭', 44, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '아 근데 일이 너무 ㅜㅜㅜㅜ 체계적이지가 못해요 계산기를 하나 더 장만하셔서 효율을 높이심이.....매번 굿즈 따로 음식따로 기다리기힘들', 45, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '2번째 방문입니다~~ 직원분들 정말 다 넘 친절하시고 좋아요☺️ 지난번에 먹어보지 못한 디저트를 주문해서 먹어봤는데요! 정말정말 맛있었습니다🥰 엄마랑 동생이랑 같이 갔는데, 동생이 다음에 또 오고 싶다네요😆', 32, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '웹툰 잘 보고있고, 콜라보소식에 이번에 서울상경하여 방문했습니다. 규모가 생각보다 작아서 아쉬웠지만 작은 규모에도 꽉꽉 알차게 채워져있어서 좋았구요. 등신대도 다 멋있고 ㅠ ㅠ 좋았습니다~ 아이들을 데리고가서 아이들 입맛대로 메뉴를 시켰더니 다 성현픽이었네요. 아이스크림위에 솜사탕 맛있다고 애들 눈이 휘둥그레졌었어요 ㅎㅎ 색지는 살 생각없었는데 실물을 보니 안살수가 없더라구요. ㅠ ㅠ 이뿌긴 이쁩니다~~ ㅎㅎㅎ', 6, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '#너를찾는파도 #너찾파 #콜라보카페 #청연 #투니크 콜라보카페 첨인데 투니크 넘 덕후취향 잘알이고 스텝분 바쁜데도 넘 친절하셔서 좋았어요👍🏻💕', 16, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '오늘 드디어 기다리고 기다렸던 비밀사이X투니크 콜라보 카페에 방문했어요🎉🎉🎉 일단 직원분들 모두 누구 하나 빠짐없이 다 친절하시고 넘 좋으세요😄 디저트도 맛있고, 저는 재민이 음료 먹었는데요. 처음 먹어보는 맛이라 새로웠고 정말 맛있었어요❤❤❤ 다음에 재방문 할 예정입니다😘', 39, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '첫방문인데 음료도 디저트도 맛있고 좋았습니다~! 무엇보다 매장이 깨끗하고 밝아서 앉아있기 좋았구요❣️ 직원분도 너무 친절했어요😍 #겨울지나벚꽃 #겨지벚카페 #콜라보카페 #밤우 #투니크', 37, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '인사 안받아주는 직원 한결같고 손님앞에서 한숨쉼 포카 주는게 힘들면 이벤트 하지마시길 안에 있다가 손님이 와서 카운터 앞에 기다려도 안나오고 불러야 겨우 나옴 손님오면 바로 대응해야하는 직원이 보통 있지않나 카운터 좁아서 손님많으면 한참 기다려야하는데 제 때 와도 내 차례 때 예약시간 지나면 예약금 차감 안해주고 돈 날려야하는 말도안되는 구조 현장에서 문의하면 거진 온라인 cs문의하라함 지인들 말로는 한참뒤에 기계적인 답변온다함 2층은 관리가 안되고있는건지 본인들도 계단 위험한거 알아서 잘 안가는지 화장실은 물이 넘쳐서 바닥이 흥건한게 몇일동안 계속 그랬고 악취남 요즘은 고쳤는지 이전 타임 손님이 음료를 바닥에 흘렸는지 타임이 바뀌어서 들어갔는데 바닥을 안닦아놔서 끈끈하게 신발 바닥이 다 달라붙음', 6, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '콜라보 작품마다 인테리어, 소품 하나하나까지 세심하게 신경을 써주셔서 작품 팬으로서 방문할때마다 너무 행복한 시간을 보내고 옵니다..!ㅠㅠ 그리고 친절하게 응대해주셔서 더 즐겁게 있다가 왔습니다><b', 21, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '오늘 인기 많은 웹툰 덕분에 전 맛있고 달콤한 디저트를 먹어 봤어요. 분위기도 너무 좋고 지원이 너무 친철하니까 너무 좋았어요', 402, 99, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '직원분들이 정말 친절하시고 디저트도 맛있었어요♡그리고 안을 너무 잘 꾸미셔서 어디에서나 사진찍고 싶은 생각이 들었어요.그날 너무 재미있게 있다 갔습니당', 38, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '콜라보 디저트도 생각보다 맛있고 무엇보다 내부가 너무너무 예뻤어요... 특히 성현재민수현 웹툰에 나온 장소들 재현해놓은게 완전 과몰입 유도 대박.. 🥲 최고의 콜라보카페!! 다른웹툰도 다 투니크에서 했음 좋겠어요 흑', 56, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '매장도 깨끗하고 직원분들 바쁜 와중에도 무척 친절하셔서 갈때마다 기분이 좋았어요~! 이번 콜라보 기간에 처음 가봤는데 매장도 항상 깨끗하고 안내도 꼼꼼하게 해주시고 특전도 매번 잘 챙겨주셨어요. 바빠서 미처 체크 못한 부분이 있을때도 다시 가서 여쭤보면 잘 기억하고 처리해주셔요. 좋아하는 작품 콜라보 많이 하면 좋겠어요!', 71, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '5번째 방문이에요🎉🎉🎉 오늘이 운영 마지막 날이라서 넘 아쉬워요😭 5번 방문했는데, 포토카드 이벤트 참여하는 법을 오늘에서야 알게되서 더 아쉬웠습니다 ㅠㅠ 포토카드 받고, 교환도 해서 겨우 8장 모았는데요..! 2장을 구하지 못한게 매우 아쉽기만 합니다🥺 오늘이 마지막 날이라서 포토카드 구할 방법이 없다는게 너무 슬퍼요😢', 72, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '핫케이크가 퍽퍽하지 않고 부드러워서 맛있게 먹었어요~ 음료도 맛있어요! 작품을 좋아하는 팬으로서 차고 넘치게 만족할 예쁜 구성의 공간들 너무 좋았습니다=D', 85, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '카페보다는 협업작가님작품전시회을 보러가거여서 만족했습니다. 1, 2층을 알차게 꾸며서 좋았어요. 음료는..ㅎㅎ 뱅쇼는 딱 뱅쇼맛이었고요. 초코라떼?는 마시멜로우가 너무 딱딱했어요. 레드벨벳케이크는 처음엔 잉? 하는 맛이지만 먹다보면 익숙해집니다.', 48, 5, NULL, SYSTIMESTAMP);
