INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '어쩜 이렇게 공들여서 인테리어를 꾸며놓으셨는지... 감동이에요. 다음에 다른 작품과 콜라보를 한대도 가고 싶은 맛과 정성입니다. 번창하세요!', 45, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '인테리어가 너무 이쁘고 아기자기해서 보는 것만으로도 힐링되어요..디저트도 정말맛있고 굿즈도 아름답고.. 평일오전에 사람도없어서 너무좋았어요💕', 9, 6, 'GOOD', SYSTIMESTAMP);
