INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '좋아하는 웹툰이라서 가봤는데 너무 깔끔하고 직원분들도 친절하게 잘 대해주셔서 좋았습니다 💓내부 곳곳을 살펴보는 재미가 있었습니다!!', 55, 16, 'GOOD', SYSTIMESTAMP);
