INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '비밀사이 콜라보 카페로 처음 투니크 방문 했는데 일단 직원분들이 다 너무 친절하세요 메뉴도 다 맛있고 너무 좋은 시간 보내고 갑니다', 29, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '직원분이 너무 친절하고 설명도 잘해주시고💚 젊은이가 아니라 잘 모르고 그냥 가고싶다는 맘만으로 갔는데 이벤트? 그런것도 잘 알려주셔서 이것저것 많이 받아왔어요 사장님 이런 직원분 계시니 흐뭇하시겠어요😍', 48, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '들어가자마자 자리 맡고 메뉴 주문 및 굿즈 계산을 같이 하는데요 메뉴 주문하는 데만 30분 넘게 줄서서 기다렸어요 개선이 필요할 것 같습니다 직원분들은 친절했는데 많은 인원을 감당하기 힘들어 보였습니다 그 외에 깔끔하고 전시도 잘 되어있어서 즐거운 시간 보내다 왔습니다!', 65, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '비밀사이 콜라보여서 해당 콜라보 메뉴들만 먹어봤지만 웬만큼 다 보통 이상은 합니다! 맛있다는 소리입니다. 아 레드벨벳 빼고요. 레드벨벳케이크 말고는 저는 음료도 디저트도 다 괜찮았어요. 요즘 이만큼도 못하는 카페가 너무 많아서....', 28, 2, 'GOOD', SYSTIMESTAMP);
