INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '직원분들도 다 너무 친절하시고 인테리어도 너무 예쁘구 굿즈들과 덤으로 주시는 상품들까지도 너무 예뻐서 진짜 행복했습니당 …🥹💗💗🍀', 31, 10, 'GOOD', SYSTIMESTAMP);
