INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '행사가 다양합니다 좌석도 많고 구석구석 잘 꾸며졌습니다 잘 모르는 곳이지만 그림들이 예뻐서 보기 좋습니다   다만 행사상품 받는 조건을 복잡하게 해둬서 계산줄이 너무 길어서   불편했습니다   깔끔하게 정리해서 잘 보이는 곳에 게시 해뒀으면 좋았을 듯 합니다', 44, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '지방에서 처음 방문했는데 너무 친절하게 가르쳐주시고 응대해주셔서 넘넘 감사합니다~맘같아선 매일 가고프지만 ㅠ 좋은추억 가지고 갑니다^^', 48, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '다양한 콜라보 제품 만나볼 수 있어서 좋았어요! 다만 계산대가 하나라서 계산이 조금 느린게 단점인것같아요ㅠㅠ 그래도 직원분들은 친절하시고 좋았어요!', 40, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '직원분도 친절하시고 인테리어도 좋아서 만족감 MAX입니다 좋아하는 장르가 투니크 카페랑 콜라보를 한다면, 한번 꼭 들러보세요 최고입니다~~👍👍👍', 14, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '직원분들 친절하시고 너무 오픈되어 있는 위치가 아니라서 오히려 편하게 사진찍고 구경할 수 있어서 좋았어요. 프박머신도 있어서 바로 출력할 수 있는 점도 편리하구요', 24, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '몇몇 직원이 너무 불친절 직원마다 말하는게 다 다름 화장실은 관리가 잘 안되는 것 같고 테이블도 늘 얼룩져 있음 프박도 투니크가 잘 못올려놓고 여백 잘라내라는 말도안되는 소리를 하고 있음 체계가 하나도 없는 듯', 14, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투니크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '나의 마녀 콜라보 카페를 갔다 왔습니다! 마침 당일에 하는 사인회에도 당첨이 되서 너무 좋았네요ㅎㅎ인생작이 콜라보 카페도 하고 굿즈도 많이 나와서 좋네요! 인테리어도 좋고! 직원 분들도 친절해요ㅎㅎ', 23, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스트레인지프룻'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '#추다혜차지스 다혜님 대단하십니다 존경합네다 좀 더 맘껏 뛰놀고 애들(그니까 저 포함 관객들요)더 날뛸수 있는 공간이 필요해요 ㅋ 천정 터질까봐 뛸수가 없더라고요 이 특별하고 독보적인 팀이 더 많은 기회를 얻고 글로벌하게 더더 초대받아 댕기시길 기원합니다 스트레인지프룻 20주년 자축잔치 마지막날 이었네요 다혜님이 축원한대로 잘 노는 우리 모두의 차지 앞으로의 20년도 스트레인지 프룻의 차지 되도록 기원합니다!', 35, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스트레인지프룻'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '어제 간만에 들른 스트레인지프룻 너무 기억에 남고 맛있는 맥주 먹고 좋은 공연 봐서 즐거웠습니다. 오칠, the do do do’s, 팻햄스터 & 캉뉴 좋은 팀 알아갑니다. 스트레인지프룻 20주년 너무 축하하고 앞으로도 계속 있어주세요.', 29, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스트레인지프룻'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '#데디오레디오 도 간만에 뵐겸 가본 #스트레인지프룻 20주년 감축드립니다! 생일잔치로 전설을 써버리시는 묘한과일, 출연진이 후덜덜한데 저의 마이너 취향에 데됴레됴와 리셋터즈까지 맞춰주셔서 즐거웠네요 아하하!', 33, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스트레인지프룻'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '스트레인지 프룻 17주년 공연 다녀왔어요. 아기자기한 공간 덕분에 윤트 공연 너무 즐겁게 즐기고 왔어요. 진토닉 마셨는데 쏘쏘했습니다🧃', 38, 3, 'GOOD', SYSTIMESTAMP);
