INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '초코 바나나 수플레 팬케이크 진짜 맛있어요. 비릿맛도 안나고 퐁신퐁신하고 달콤하고❤️ 지친 마음이 사르르 녹아요! 에비타마고도 계란샐러드가 가득 들어있어서 한끼로 먹기에 딱 좋아요! 도쿄 바닐라도 달콤하고, 아메리카노도 적당히 고소 +산뜻해요. 통창으로 홍대거리를 보는 재미도 있어요!', 117, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '홍대에서 예쁜 디저트 카페 찾다가 방문했어요. 블랙펄 밀크티(6,800원)는 진하고 부드러운 홍차 베이스에 쫄깃한 펄이 들어 있어서 디저트랑 함께 먹기 딱 좋았어요. 에비타마고(14,000원)는 폭신한 계란과 새우가 가득 들어 있어서 부드럽고 담백한 맛이 인상적이었고, 반가워 딸기 수플레(19,000원)는 진짜 푹신푹신하고 달달한 딸기 향이 확 퍼져서 기분까지 좋아지더라고요. 가격대는 조금 있는 편이지만 플레이팅부터 맛, 분위기까지 다 만족스러웠던 곳이에요.', 9, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '홍대입구에 2층까지 있는 대형카페가 있다니 단체석도 있고 통창에 햇살까지 들어와서 좋더라고요 수플레가 이렇게 다양하디니 저는 초코러버라 초코로 선택했는데 엄청부드럽고 초코아이스크림이랑 같이 먹으니까 하루 너무 행복하더라고요 💓 종류별로 수플레 깨기 도전해야겠어요', 31, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '젊어지고 싶은 저희 커플은 홍대 브런치 맛집 라헬의 부엌을 다녀왔어요. 수플레로 굉장히 유명해서 저희 커플은 만나면서 수플레의 ㅅ도 먹어보지 못했기때문에 너무 기대됐습니다! 달달이를 엄청 좋아하는 저에게 달잘이 폭격당하는 중인 남자친구도 너무 맛있다며 5분 컷 했어요ㅋㅋㅋㅋㅋㅋ 말캉말캉 너무 맛있었던 크림뷔릴레 너무 추천추천합니다🥹💓 치킨커리샌드위치도 단짠의 짠을 맡아주었어요ㅋㅋㅋ둘의 궁합 최고!!!👍👍', 70, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '아이데리고 홍대왔다가 그냥 들어갔는데, 수플레팬케이크가 생각보다 맛있었어요~ 사과주스도 찐사과라 맛있고, 딸 먹으라고 주문한 딸기파르페도 괜찮네요~ 수플레맛있어서 하나더 주문했어요~~ 바빠서 그런지 여자직원분이 좀 친절하진 않으셨지만, 팬케이크는 맛있네요^^;;', 54, 12, NULL, SYSTIMESTAMP);
