INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '수많은 수플레 메뉴중 메론생크림은 안먹어본 메뉴여서 신기해서 골랐는데, 메로나의 그 아는 맛이지만 그래도 맛있었네요 ㅋㅋ 싱싱달달한 메론도 좋았구요! 에비타마고메뉴의 에그마요(또는 에그사라다 ㅋㅋ)가 완전 제입에 딱!ㅋㅋ 맛있게 먹고갑니다 ㅋ', 52, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '오늘의 대만족 방문!! 일단 폭염이라서 너무 더워서 들어왔는데 찐으로 잘 들어왔네요!! 매장이 밖에서 볼 때마다 크고 쾌적하고 찐으로 시원해요. 그리고 메뉴에 수플레가 있어서 시켰는데 완전 부드럽고 촉촉하고 퐁신하고 다하네요!! 종류가 많으니 취향따라서 먹으면 될듯해요~ 기본 수플레가 맛나서요!! 그리고 체리에이드 강추요! 제가 체리에이드 진짜 좋아해사 메뉴 있는곳은 다 먹어보는데 여기는 찐입니다! 오늘 잘 쉬고 잘 먹고 갑니다 :)', 25, 6, 'GOOD', SYSTIMESTAMP);
