INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '딸기 수플레와 도쿄바닐라 함께 먹으니 핵꾸르맛 엄청 부드럽고 수플레빵과 생크림이랑 아이스크림이랑 딸기까지 한입에 앙 물면 구름위로 올라갑니다', 36, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '복숭아수플레 퐁신퐁신한 수플레3장 백도, 황도, 생크림, 아이스크림 복숭아의 향기와 적당한 달달함 그리고 상큼함~ 수플레와 아주 잘어울려요💕 ICE아메리카노 상큼한 산미가 살짝 있고 묵직한 바디감이 느껴져요 수플레와 완벽한 조합!! 빛과소금 거품이 쫀쫀해요~~ 빛과소금 아인슈페너는 크림에 소금이 섞여있어 짭쪼롬해요~ 수플레, 커피, 분위기 모두 완벽했던 라헬의부엌 홍대점👍👍👍', 99, 21, 'GOOD', SYSTIMESTAMP);
