INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '친구랑 근처에 밥 먹으러 왔다가 방문했어요!ㅎㅎ 분위기도 좋고 대화하기도 좋네요@@ 또 수플레 종류가 엄청 많았어요 가을 시즌때 무화과랑 밤 수플레 먹으러 오고 싶네요 🥰 맛있게 먹고 재밌게 놀다가요👍👍 추가로 제가 먹었던 수플레중 가장 최고입니다..😍', 315, 71, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
