INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '전에도 맛있게 먹었던 기억이 있는데 갑자기 생각나서 지나는 길에 들어왔어요 평일 오전이라 웨이팅 없이 바로 들어왔구요 여전히 매장도 쾌적하고 퐁신 퐁신 수플레 물론 맛있었어요 직원분들도 친절하시고 시원하고 ㅎㅎ 잘 머물다 갑니다', 12, 3, 'GOOD', SYSTIMESTAMP);
