INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '일요일 오전, 여유롭게 브런치를 즐기고 싶어 라헬의 부엌 홍대점에 다녀왔어요. 🥰 일찍 방문해서 그런지 매장도 쾌적하고 한적해서 분위기까지 완벽했습니다. 주문한 브런치 메뉴는 비주얼부터 압도적! 맛, 분위기, 서비스 모두 만족스러운 곳이라 일요일 아침 브런치 장소로 강력 추천하고 싶어요. 친구랑 또 오고 싶어요! 💛', 29, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '수플레 팬케이크 먹고 싶어서 방문했어요 벚꽃 수플레 비주얼 이쁩니다🌸 달달하니 맛도 있었구 같이 주신 아이스크림도 연유맛 나면서.. 진짜 맛있었어요! 밥을 먹고 나서 배부른 상태로 그냥 천천히 먹자 하구서 간 건데 맛있어서 금방 먹었어요😅 매장이 분홍으로 꾸며진 곳이 많구 귀여운 소품들도 있어서 아기자기합니다💕 2층까지 있어서 자리도 많이 있었어요!', 42, 4, 'GOOD', SYSTIMESTAMP);
