INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '완전 맛있는 홍대 수플레 !! 여긴 워낙 유명해서~ 또 오고 또 오고 싶은 곳 입니다 ㅎㅎ 외국인들도 여행지로 오는 곳인데 사장님 직원분들 모두 친절하세요^^ 딸기 수플레 + 아아 환상의조합 !!!', 113, 25, 'GOOD', SYSTIMESTAMP);
