INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '라헬의 부엌 수플레 진짜맛있어요~~  부드러운 수플레와 멜론의 향이 너무 잘 어울리고 맛있어요. 계절에 어울리는 과일과 음료 잘 선택한 것 같아요. 너무 맛있게 먹고왔어요:)', 53, 17, 'GOOD', SYSTIMESTAMP);
