INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '브런치 먹으러 왔는데 구성이 정말 알차요!! 다음에 다른 메뉴도 먹어보러 오고싶어요!!!! 매장도 깨끗하고 넓고 청결해서 기분이 좋아요~~❤️', 56, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '퐁신퐁신 수플레는 언제나 사랑이죠,,,🫶🏻수플레 굽기도 좋고, 크림도 맛있었어요>< 커피맛도 좋네요!! 매장은 쾌적하고 깨끗해서 혼자 시간 보내기도, 친구랑와서 수다 떨기도 넘 좋을 듯 합니당ㅎㅎ 크림이 넘나 맛도리~~~~!!🤍', 14, 0, 'GOOD', SYSTIMESTAMP);
