INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '친구들이랑 수플레 먹으러 왔는데 너무 맛있었어요😋수플레랑 휘핑크림, 아이스크림의 조화가 좋았습니다! 밥도 안먹고 와서 에비타마고 브런치도 시켰는데 에그마요와 빵, 새우가 전부 맛있었어요! 다음에도 또 먹고 싶어요 ㅎㅎ', 26, 2, 'GOOD', SYSTIMESTAMP);
