INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '가게가 귀욤귀욤하고요 널찍하고 환한 느낌의 인테리어입니다! 수플레가 과연 퐁신퐁신 비주얼이 미챴네요..♡ᩚ 🥞 잘 먹겠습니다 🫶🏻', 80, 12, 'GOOD', SYSTIMESTAMP);
