INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '무화과 수플레 팬케이크와 망고 음료들을 시켜서 같이 먹어봤는데 맛있었습니다! 지난번엔 딸기를 먹었던 거 같은데 무화과도 정말 떫지 않고 맛있었어요👍', 20, 6, 'GOOD', SYSTIMESTAMP);
