INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '이거 받구 화 안풀리는 사람이 있을까?🥹 #라헬의부엌홍대점 @라헬의부엌 홍대에서 기분 전환이 필요할 때 무조건 달려가는 곳! 들어가자마자 예쁜 분위기에 심쿵하고, 디저트 비주얼에 또 심쿵✨ 오늘은 달콤멜론수플레랑 딸기파르페 시켰어용🍈🍓🍰 퐁실퐁실 부드러운 수플레랑 상큼달콤한 파르페 먹으니까 스트레스가 싹~ 풀리는 기분이었답니다😋 이렇게라도 쌓인 스트레스 풀어야해... 하는 분들에게 강추! 진짜 시킨 메뉴 나온거 보자마자 어느정도 해피해지는곳이니 취향맞다면 함 들려보시길...🤍 😘오늘 먹은 메뉴? 달콤멜론수플레 18000원 딸기파르페 12900원', 31, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '예쁜 카페가기... 네이버 검색해서 이름이 마음에 들어 방문한 카페입니다. 들어서서는 작은 카페구나...했는데 (혼자가는 작은카페는 부담스러워서....) 2층으로 올라가니 흡족하게 넓은 카페입니다 카페 전체가 아기자기하고 약간 진한(?) 파스텔톤이라 동화나라 인듯 합니다. 주위 테이블을 보니 20대 초반인 듯 여학생(?)들이 예쁜 메뉴들을 앞에도고 사진찍기에 여념없습니다. 카페 분위기도 메뉴도 사진찍고 싶게 만드는 곳입니다. 집에서 샐러드 먹게 되지 않아 주문했는데 치즈는 아낌없이...소스는 과하지도 부족하지도 않은 행복한 샐러드를 맛보고 갑니다. 나가려다 무심코 본 티슈에 적힌 문구를 보고 한장 더 찍습니다.', 9, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '서울 여행와서 검색 후 들렸는데 대~만족이요!!!💖💖 커피도 고소하니 맛나구 녹차 수플레 감탄하면서 먹었어요 ㅎㅎ 퐁실퐁실 잘 먹고 갑니닷!! 수플레가 커피랑 너무 잘 어울려요', 47, 9, 'GOOD', SYSTIMESTAMP);
