INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '라헬의 부엌 지점 중 단연 최고! 과일도 아낌없이 주시고 수플레 맛은 말모~~ 참고로 여기서 인생샷도 건졌어요 맛과 인생샷 모두 놓치고 싶지 않다면 이곳은 탁월한 선택✨', 28, 0, 'GOOD', SYSTIMESTAMP);
