INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '브런치를 좋아해서 여러군데 다녀봤는데 유독 여기 수플레랑 아인슈페너가 정말 맛있네요! 수박주스도 너무 달고 맛있어서 행복한 브런치 식사를 할 수 있었어요! 개인적으로 수플레에 잘 맞게 단맛이나 짠맛 등등의 밸런스를 잘 맞춰서 메뉴를 구성하신게 보여서 맛있었습니다. 다음에 또 방문할께요!', 4, 1, 'GOOD', SYSTIMESTAMP);
