INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '분위기도 너무 예쁘고 친구들끼리 사진찍으러 가면 좋을 것 같더라구요💗 브런치같은 것도 판매하시는데 수플레가 진짜 미쳤어용 엄청 몽글몽글해서🫶🫶💛', 44, 3, 'GOOD', SYSTIMESTAMP);
