INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '수플레 팬케이크 좋아해서 자주 먹으러다니는데 여기 팬케이크 고소하고 부드럽고 너무 맛있어요! 몽글몽글 식감이 너무 좋고 계란 비린내 안나서 좋았습니다. 운좋게 웨이팅없이 들어갔는데 인테리어도 예뻐서 다음에 또 오고싶어요!', 6, 4, 'GOOD', SYSTIMESTAMP);
