INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '처음 와봤는데… 미쳤어요!!! 😭💕 수플레 디저트가 진짜 입안에서 사르르 녹아요. 달콤하면서도 부담스럽지 않고, 한 입 먹자마자 “와… 이 집 뭐야?” 소리가 절로 나왔습니다ㅎㅎ 커피도 디저트랑 너무 잘 어울리고, 부드러워서 깔끔하게 마무리되는 느낌! 오늘 좋은 선생님들과 함께 방문해서 그런지 더 특별한 시간이었어요. 다음엔 다른 메뉴도 꼭 도전해볼 거예용!!💗💗', 28, 8, 'GOOD', SYSTIMESTAMP);
