INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '요즘 인스타에서 핫하다는 수플레 케이크 가게에 다녀왔어요! 가게에 들어서자마자 은은한 디저트 향과 따뜻한 조명이 분위기를 제대로 살려줬어요. 내부는 아담하지만 아기자기하게 꾸며져 있어서 사진 찍기에도 정말 좋더라고요. 수플레 케이크는 제가 ‘말랑말랑’한 디저트를 좋아해서 기대했는데, 진짜 입안에서 사르르 녹는 느낌이었어요.', 125, 23, 'GOOD', SYSTIMESTAMP);
