INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '상큼한 음료랑 상큼한 팬케이크 너무 맛있게 잘 먹었어요 🤭🩷 팬케이크 먹고 싶었는데 엄청 퐁신하고 존맛탱 ••• ! 더워서 상큼한 거 먹고 싶었는데 딱 제격인 것 같아요 🤓 맛있게 잘 먹구 갑니다 ! 🩷❤️🔥', 15, 0, 'GOOD', SYSTIMESTAMP);
