INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '딸기 수플레랑 아메리카노랑 먹었는데 환상입니다ㅎㅎ 연남점도 가봤었는데, 1층과 2층으로 되어 있어 홍대점이 훨씬 넓고 얘기하기도 좋아요. 요즘 같이 날씨 좋을 때 폴딩 도어 다 열고 카페에 앉아 있으니, 루프탑 느낌도 나고 분위기 좋네요! 여유로운 분위기에서 맛있는 수플레 드시고 싶은 분들께 추천합니다!!', 1, 8, 'GOOD', SYSTIMESTAMP);
