INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '멜론 수플레 팬케이크 진짜 맛있게 먹었어요! 부드러운 수플레에 신선한 생과일이 듬뿍 올라가 있고, 바닐라 아이스크림까지 함께 나와서 조합이 정말 좋더라고요. 멜론 수플레는 처음 시켜봤는데 기대 이상으로 맛있었어요. 가격대는 꽤 있지만 그만큼의 가치가 있는 디저트라 항상  만족스러워요. 다만 한 가지 아쉬운 점은 수플레 위에 올려진 멜론 생크림에서 살짝 인위적인 멜론 향이 느껴졌다는 점이에요. 좀 더 담백한 생크림이었으면 더 좋았을 것 같아요!.! 그래도 완전 만족했습니다 😋', 30, 6, 'GOOD', SYSTIMESTAMP);
