INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '음식도 너무 예쁘게 잘 나오고 알찬 구성으로 맛있게 잘 먹었어요 수플레 기대하고 왔는데 치킨 커리 샌드위치도 반해버렸습니다 건강한 호밀빵과 아보카도, 치킨 커리의 조합이 최고에요 달달하고 부드러운 초코코 수플레도 엄지척입니다:)', 68, 17, 'GOOD', SYSTIMESTAMP);
