INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '달콤메론 수플레 한 입 먹는 순간 입 안에서 녹아내리는 느낌이 정말 환상적이에요 메론의 달콤함이 부드러운 수플레와 만나니까 마치 구름 위를 걷는 기분! 겉은 살짝 바삭하고 속은 촉촉폭신한 식감이 너무 매력적이어요.', 1, 2, 'GOOD', SYSTIMESTAMP);
