INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '수플레케이크 맛있었던 기억이 나서 이번에는 망고빙수 먹으러 방문했어요 ~ 망고빙수 중에 가성비 제일 좋은 것 같아요 👍 중간중간 뿌려진 시럽이 너무 맛있었어요 수플레도 맛있는데 빙수 먹으러 와도 좋을 것 같아요 ❤️', 95, 23, 'GOOD', SYSTIMESTAMP);
