INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '정말 나오는 음식마다 너무 이쁘고 아보카도며 야채들은 완전 싱싱하고 제대로 익어서 정말 맛있고 예쁜 샌드위치 많이 먹었어요! 수플레는 너무너무 부드러운데다가 달달함의 정도가 적당해서 퍼펙트이븐 드립니다. 굉장히 맛있는 한끼 행복한 한끼 잘 먹었습니다🥰', 105, 24, 'GOOD', SYSTIMESTAMP);
