INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '말차맛이랑 흑당맛 수플레 먹어봤어요. 말차는 은은하게 쌉싸름하고 부드러웠고, 흑당은 진하고 달달해서 디저트 느낌 제대로였어요. 둘 다 식감이 폭신해서 먹는 재미도 있었고요. 가게 분위기도 괜찮고 직원도 친절했어요. 다음에 또 올게요~~~ ♡', 117, 24, 'GOOD', SYSTIMESTAMP);
