INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '사진 보고 홀딱 반해서 찾아온 집! 수플레 넘나 맛나요. 메뉴도 다양해서 어떤거 먹을지 고민했는데 담엔 다른거도 먹어봐야겠어요 ^^', 136, 28, NULL, SYSTIMESTAMP);
