INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '음식이 너무너무 맛있고 둘이 와서 수플레 브런치 푸파 했습니당 생각보다 양이 많고 맛있어서 좋았어요👍🩷 분위기 좋고 이야기 하기도 적당히 가게가 넓어서 추천합니다 다음에 또 방문하겠습니다😊', 39, 4, 'GOOD', SYSTIMESTAMP);
