INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '인테리어가 너무 아기자기하고 예뻐서 음식 나오기 전에 구경하는 재미로도 시간이 쏠쏠합니다! 수플레가 주력 메뉴이니까 하나는 꼭 시켜 먹으면 좋을 것 같아요 외국인 분들도 많으신 인기 플레이스입니다ㅎㅎ', 41, 8, 'GOOD', SYSTIMESTAMP);
