INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '수플레 종류가 많고 부드러워서 맛있었습니다! 복숭아 수플레 주문했는데 복숭아도 달고 맛있었는데 양이 적어서 아쉬웠습니다ㅠㅠ 다음에 다른 수플레도 먹어보고 싶어요!!', 83, 14, NULL, SYSTIMESTAMP);
