INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '예쁜 인테리어가 눈에 띄어서 들어오게되었어요! 깔끔한 매장에 메뉴도 다양해서 좋았습니다. 홍대 수플레맛집으로 소문난곳이라 기대했는데 정말 폭신폭신하고 부드러워서 맛있게먹었습니다. 음식비쥬얼도 예뻐서 함께 방문한 아이가 너무 좋아했습니다.', 43, 2, 'GOOD', SYSTIMESTAMP);
