INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '수플레가 너무 퐁신퐁신해서 맛있어요◡̈ 처음 갔을 때 기억이 너무 좋았어서 또 방문했는데 강아지는 없네요…🥹 기염둥강쥐 또 보고싶네용 수플레는 말이 필요 없어요… 진자 짱맛있음 음료도 맛있어용', 16, 10, 'GOOD', SYSTIMESTAMP);
