INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '평일 점심시간쯤 방문했는데 대기없이 바로 이용가능했어요. 친절하고 매장이 예뻐서 딸아이가 좋아했어요. 제 커피도 맛있고 딸도 딸기라떼 맛있대요. 수플레는 말해모합니까~~~ 딸 생일데이트로 픽한곳인데 굿초이스라 기분 좋게 다녀왔어요.', 126, 26, 'GOOD', SYSTIMESTAMP);
