INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '딸기 파르페를 판다고 해서 와봤는데 상상대로 맛있네요~ 홍대 근처 오실거면 꼭 와보세요!! 후회하지 않습니다. 인테리어도 정말 이쁘고 커플들도 많아서 데이트하기도 좋아보이네요~~ 👍👍', 17, 10, 'GOOD', SYSTIMESTAMP);
