INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '따스한 조명과 창가 좌석엔 햇살 한가득 분위기 였구요 핑크핑크한 여성스러운 분위기의 브런치가게 라헬의 부엌은 정말 매력적인 공간이었습니다. ​ ​ ​ 인스타 사진찍기에도 안성맞춤인 예쁜 분위기 맛집입니다. 홍대 브런치 맛집중에 제일 분위기가 좋고 단체석도 준비되어 있어 단체모임 하기에도 좋아보였습니다.', 32, 5, 'GOOD', SYSTIMESTAMP);
