INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '맛있어요! 두번째 방문인데 수플레 맛있는건 알았지만 브런치도 이렇게 맛있을줄 몰랐어요! 진짜 브런치 강추요!!! 저 비이컨 토마토 빵이 너무 맛있고 잘 먹었어요!!!', 30, 6, 'GOOD', SYSTIMESTAMP);
