INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '당 떨어질 때마다 생각나는 홍대 수플레 맛집...♡ 계절별로 제철 과일 메뉴도 많아요! 지금은 복숭아철이라 복숭아 수플레를 먹어봤는데, 너무... 달달하고... 최고입니다...♡', 8, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '🎂  가 너무 푹신하구 부드러워요ㅠ 음료는 커피나 상큼한건 좋은데 음료 자체 개성강한걸 피하구 케이크랑 잘 어울리는걸 고르는걸 추천드려요! 꿀과 아이스크림 모두 적당히 달고 좋은데 딸기는 상큼하니 참고하면 좋아요! 모두 즐거운 디저트 타임 보내쎄용~!!', 115, 24, 'GOOD', SYSTIMESTAMP);
