INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '맛있었어요! 사실 밥과 가격이 비슷해서 이정도 냈으면 맛있어야 되는건 맞다고 생각하지만, 그래도 수플레 종류가 많아서 다른 메뉴도 너무 먹어 보고 싶어요! 수플레 먹어봤는데 다른 맛도 먹어 보고 싶은 분들에게 추천드리고 사람이 많아서 자리 없을 줄 알았는데 생각보다 자리 바로 납니다! 직원분들도 바쁜 와중에 나름 친절하셔서 좋아요', 105, 25, 'GOOD', SYSTIMESTAMP);
