INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '라헬의 부엌은 수플레를 맛볼 수 있는 브런치 맛집이예요!! 수플레가 완전 폭신폭신 탱글탱글해서 부드러운 솜사탕을 먹는 느낌입니당ㅎㅎ그리고 치킨커리샌드위치는 건강한 맛 그 자체! 인테리어도 사진찍고 놀기 좋아요~', 7, 10, 'GOOD', SYSTIMESTAMP);
