INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '수플레 팬케익과 브런치 메뉴가 있는 카페 2층 통창뷰라 개방감 좋고 테이블도 많아요 수플레는 15분 정도 기다려야 하고 아메리카노는 같이 마시기 부담없어요 딸기수플레(19,900) 쉬림프아보카도오픈샌드위치(19,000) 아메리카노(5,200)', 25, 8, 'GOOD', SYSTIMESTAMP);
