INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '수플레 맛집으로 알려진 라헬의 부엌에서 브런치 먹고 왔어용 :) 수플레 맛집인 건 이미 유명하지만 여기 브런치도 진짜 맛있어요 💕 타마고샌드 드셔보세요 요즘 식단관리한다구 시저샐러드도 주문했는데 상큼+시저드레싱 조합으로 맛있게 먹었어용 친구가 말렌카케이크 좋아해서 같이 주문했는데 저는 처음먹어봤는데 이런 맛이군여..? 초코맛 추천! 2층 자리도 많고 쾌적해서 좋았어요 :)', 21, 8, 'GOOD', SYSTIMESTAMP);
