INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '카페분위기가 너무 이뻐요! 소담소담한 핑크와 화이트톤이 진짜 카페라는 느낌이 확들더라구요 2층까지 있어서 엄청 넓어요! 그리고 브런치도 시켜먹었는데 재료도 싱싱하고 이거 넘 맛나더라구요 ㅠㅠㅠ최고 그리고 귀여운 콩이도 있어요! 너무 귀여워요 ㅠㅠ순하고 착한거 같았어요! 만지고싶었지만... 열심히 참았다...', 46, 3, 'GOOD', SYSTIMESTAMP);
