INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '전에 친구랑 왔다가 너무 좋아서 또 왔어요! 그땐 초코수플레 없었는데 이번에 생겼더라구요!! 자리도 많아서 회전도 잘돼요! 초코 수플레 맛있어요!!!', 38, 2, 'GOOD', SYSTIMESTAMP);
