INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '수플레가 맛있다고 해서 검색해보고 방문 했어요. 오후 5시반쯤 이였는데 1,2층 사람 꽉차있었어요! 아메리카노는 나쁘지 않았고 딸기라떼는 달달해서 괜찮았다고 하네요! 수플레는 가격대가 조금 있지만 지금까지 먹어본 것 중에 가장 부드럽고 맛있었던 것 같아요! 아쉬운점은 주변 대화소리가 컸는데 매장 노래까지 큰편이라 조금 소란스럽게 느껴지긴 했어요.', 76, 18, NULL, SYSTIMESTAMP);
