INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '매장이 넓고 분위기가 좋아요! 그리고 전시된 소품들도 예뻐서 사진 찍기 좋았었요 ㅎㅎ 그리고 사장님이 친절하시고 디저트도 너무 맛있어요! 잘 놀다 갑니다!', 42, 2, 'GOOD', SYSTIMESTAMP);
