INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '비주얼 왜 이렇게 예뻐요!🍓 딸기 수플레 3개나 나와서, 다른곳보다 훨씬 저렴한 느낌이에요! 부드러운 크림이랑, 아이스크림까지 나와서 구성도 좋고, 부드럽고 맛있었어요☺ 레몬 케익은 친구가 먹고파해서 시켜봤는데 생각보다 훨씬 좋았어요!! 라떼가 원두맛이 강한데, 그래서 디저트랑 잘어울렸답니다. 손님이 많아서 식후 시간엔 웨이팅이 있을 수 있겠어요!', 14, 4, 'GOOD', SYSTIMESTAMP);
