INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '수플레 종류가 정말정말 많았어요!! 엄청 퐁신하고 갓 만들어진 따끈한 수플레를 먹어볼 수 있었어요''!! 음료도 종류가 엄청 다양해서 좋았어요-!! 여름에 오기도 딱이에요😆', 50, 10, 'GOOD', SYSTIMESTAMP);
