INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '수플레 팬케이크 종류도 많고 넘 맛있어요!! 먹고싶을때 찾아올것같아요! 시즌별로 과일 팬케이크도 팔아서 시즌맞춰오면 좋을것같아요~', 95, 19, 'GOOD', SYSTIMESTAMP);
