INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '망고 수플레 팬케이크 먹었는데 진짜 미쳤어요. 폭신폭신한 팬케이크에 달달한 망고랑 크림 조합이 조아요 입에서 살살 녹고 하나도 안 느끼해서 순식간에 다 먹었어요. 또 먹고 싶다…', 12, 4, 'GOOD', SYSTIMESTAMP);
