INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '수플레 종류가 너무 많아서 고민이었는데 겨울이라 딸기 수플레 선택! 너무 맛있고 딸기도 달달하더라구요ㅎㅎㅎ브런치 플레이트 구성도 알차고 재료 하나하나 질이 좋아서 계속 생각나는 맛이에요💭 홍대 수플레 맛집, 홍대 브런치 맛집 찾으신다면 강추입니다‼️', 51, 12, 'GOOD', SYSTIMESTAMP);
