INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '폭신한 팬케이크 위에 바삭하게 캐러멜라이징된 토핑, 진한 바닐라 크림과 바나나의 조화가 환상적이에요. 달콤하고 부드러운 디저트 한 접시에 아이스 커피 한 잔이면 완벽한 브런치!', 14, 4, 'GOOD', SYSTIMESTAMP);
