INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '당연코 가장 유명한 수플레 팬케이크 맛집❤ 워낙 유명해서 고향 친구들도 알고있는 맛집이었는데요! 퐁실통실한 수플레 케이크가 넘나 부드럽고 맛있어서 왜 유명한지 알것 같던 수플레 팬케이크 맛집입니다 부들 촉촉한 식감 드셔본 사람은 아실꺼에요🥰 음료 메뉴도 커피 논커피 쥬스 에이드 티 시그니처 메뉴가있어 어떤걸 먹어야할지 고민,, 시그니처 밀크티와 딸기라떼를 주문해 먹었는데 시그니처 메뉴가 최고에요ㅎㅎㅎㅎ 딸기라떼🍓 딸기 듬뿍 꼭 드셔보세요 다양하고 수플레 케이크 말고도 브런치 메뉴, 말렌카 케이크, 빙수, 파르페도 있어서 취향껏 드실 수 있어요! 귀여운 인테리어는 덤ㅎㅎ 2층도 카페여서 테이블 좌석도 많아서 평일 오후 방문이었는데 자리는 여유있었습니다', 56, 15, 'GOOD', SYSTIMESTAMP);
