INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '회사 동료 추천으로 와봤는데 와 정말 너무 맛있어요~! 주말엔 웨이팅한다고 해서 10시반 되기전에 얼른 왔는데 직원분께서 들어와있어도 된다고 하셔서 자리 잡고 10시반 되자마자 주문했습니다~! 근데 여기는 진짜 시간 되기도 전에 사람들이 들어오네요 팬케이크 너무 맛있어요 진짜 입에서 걍 녹아버립니다 그동안 많이 먹어봤는데 여기처럼 이렇게 녹는곳은 처음이에요! 아아도 제 입맛에 잘 맞아요^^ 일찍 온 보람이 있네요!!', 108, 25, 'GOOD', SYSTIMESTAMP);
