INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '친구랑 연남동 브런치 먹으러 방문했는데 분위기도 너무 좋고 맛나게 먹었어요.💓💓 베이컨써니사이드업이랑 수플레 비주얼도 좋고 맛있어서 완전 힐링했습니다. ㅎㅎㅎ', 16, 3, 'GOOD', SYSTIMESTAMP);
