INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '녹차에 반한너를 시켜서 먹었는데 처음봤을때 비주얼이 미쳤어요..진짜 맛있어보이고 첫입먹어봤는데 진짜 급나 맛있어요 근대 단점이 먹다보니까 살짝 느끼하고 물린달까??근대 정말 만족하면서 먹었어요!후식아이스크림도 정말맛있었어요! 다음에 꼭 또 올것같아용😍', 45, 4, 'GOOD', SYSTIMESTAMP);
