INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '흑당 수플레랑 티파티 홍차 먹었는데, 둘 다 비주얼도 너무 예쁘고 맛있었어요. 수플레는 퐁신한 팬케이크 세장에 크림, 흑당소스 가득 올라가서 흑당버블티향기가 가득했는데, 여기 펄까지 더해져서 흑당 밀크티 좋아하는 사람으로써 환상적이었어요. 수플레 자체도 퐁신퐁신 너무 맛있는데, 차가운 소프트아이스크림과 조화도 정말 좋더라구요. 티파티 홍차도 너무 예쁜 티팟과 잔에 나와서 보기에도 너무 예뻤는데, 포근하고 차분하면서 깔끔한 향이 너무 좋았어요. 수플레와도 정말 잘어울려서 맛있게 먹었습니다. 다른 맛들도 전부 먹으러 가고싶어요.', 30, 4, NULL, SYSTIMESTAMP);
