INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '수플레 느끼하거나 많이 달디 않고 너무 맛있어요~! 과일, 크림 많이 줘서 좋아요. ☺️ 매장도 예쁘게 잘 꾸며져 있고 포토존도 있네요. 2층으로 되어있어서 자리도 넉넉한 편입니다.', 54, 15, 'GOOD', SYSTIMESTAMP);
