INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '수플레 먹고 싶어서 왔다가 파르페까지 시켰어요.. -.,- 매장 2층까지 있어서 좋고 핑크핑크한 분위기네요 좋아용 가성비 굿.', 60, 17, 'GOOD', SYSTIMESTAMP);
