INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '정말 라헬의부엌💛 인테리어 넘 귀여워용 여성분들 엄청많아용 ㅎㅎ 반려동반해주셔서 맛있게 잘먹고왔습니당 ㅎㅎ 크림수플레ㅜ미쳤어요!! 사진보니 군침나오네용 ㅎㅎ 무조건 재방문합니다💖', 49, 7, 'GOOD', SYSTIMESTAMP);
