INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '수플레가 너무너무 부드러워서 놀랐어요! 이렇게 맛있는 수플레는 처음이에요 수플레와 아이스크림 조화가 미쳤네요 인테리어랑 분위기도 너무 예쁘고 잘 놀다가요', 11, 7, 'GOOD', SYSTIMESTAMP);
