INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), 'ㅠㅠ 8시 라스트오더인데 조금 늦을까봐 전화로 주문 가능 한지 여쭤봤더니 해주시더라구요 감사합니다ㅏ 먹고싶엇던 거게엿어요 여기 아이스크림도 맛나요', 2, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '딸기 수플레 팬케이크 맛집🍓🍰 퐁신퐁신한 수플레맛집~~답게 부드러움 맛이 일품이네요!👍 상큼한 딸기와 수플레의 조화는 딸기철에만 즐길 수 있으니 꼭 드셔보세요! 매장도 넓고 조용하고 인테리어가 너무 예쁩니당ㅎㅎ 브런치 즐기시는 분들도 많고 혼밥 하시는 분도 많아요~~ ☕️', 9, 3, 'GOOD', SYSTIMESTAMP);
