INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '맛은 그냥 수플레 맛있는 맛이에요. 근데 테이블 배치나 분위기가 이렇게 정신없는 카페는 처음봐요.. 맛은 괜찮은데 매장 어수선함에 충격받아서 다신 안올것 같아요..', 22, 0, 'BAD', SYSTIMESTAMP);
