INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '비싼 가격에 주춤했지만 먹어보니까 오길 잘했다고 생각했어요 ㅎㅎ 수플레가 엄청 폭신하고 에이드랑 쉐이크도 정말 좋았어요 인스타에 올릴 사진도 엄청 건지고 갑니다 ㅎㅎ', 97, 21, 'GOOD', SYSTIMESTAMP);
