INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '수플레 먹고싶으면 무조건 오는 라헬의 부엌! 친구들도 다 아는 제 맛집이에요+_+ 오늘도 와본 적 없다는 친구 데리고 왔어요!! 과일 수플레도 과일 시즌 오프라 가끔 먹고싶은 메뉴를 못먹을 때도 있지만 그럼 다른 과일 수플레를 먹음 되니까~ 눈으로 보기에도 예쁘고 맛도 좋아요!!', 11, 7, 'GOOD', SYSTIMESTAMP);
