INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '이번이 이용 두 번째인데 처음 갔을 때도 직원 응대가 기분 좋은 편은 아니었지만 두 번째도 진짜 별로였습니다. 따로 결제를 하려고 주문하는데 말 끊고 친구도 같이 동시에 메뉴 주문하시라고 뭔가 귀찮다는 듯이 말씀하시는데 결국 커피 연하게 주문한 것도 누락하셨어요. 결제가 따로가 가능 한데 굳이 메뉴 다 듣지도 않고 말 끊고 안내하는 건 응대가 미숙하다고 볼 수밖에 없었습니다. 한 사람 메뉴 말하는 건 다 받고 다른 분까지 주문 동시에 받고 결제 따로 하겠습니다 란 생각은 못하셨는지? 처음 갔을 때도 메뉴 구성인 시럽을  빼먹고 주셔서 먹다가 뭔가 이상해서 시럽 받으러 갔는데 두 번째 때도 나이프 또 안 챙겨주셔서 가지러 갔었네요. 사과의 말은 일절 없구요 뭐 하나씩 빼고 주는 게 이집만의 특징인가봅니다', 30, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '수플레팬케잌 넘 마싯어서  발견한 후로 n번째  이용하고잇어요 ㅎㅎㅎ    팬케잌 여러메뉴 먹아봤는데  다 마싯거 해서 추천 합니다   데이트 코스로도 추천해요   분위기도 넘 이뻐서 사진찍기도 좋습니다', 20, 7, 'GOOD', SYSTIMESTAMP);
