INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '너무 맛잇어요… 수플레 전문점이라서 그런가 매번 똑같은 수플레만 파는게 아니라 다양하게 있어서 넘 조아요 밤 수플레 시켰는데 기본 크림 수플레에 꿀에 절인 밤이 나오는데 존맛탱이에요 파르페도 넘 이쁘구 맛잇어요… 담엔 밀크티 먹어보려구요', 92, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '수플레가 엄청 퐁신하고 같이 있는 초코드레싱이랑 같이 뿌려먹으면 엄청 맛있어요. 분위기도 좋고 가게 내부도 깔끔해서 친구랑 오든 데이트하기도 아주 좋아요.', 6, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '가게 안이 2층으로 되어있고, 인테리어가 귀여워요 2층은 통창이었는데 창가 자리에 앉아 좋았어요 수플레 먹고 싶어서 왔는데 좋았어요! 🤤👍', 30, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '팬케이크 종류가 생각나면 들리는 곳이에요. 맛도 있고 매장도 깔끔해서 좋아합니다 ㅎㅎ 홍대 근처 팬케이크 맛집 하면 라헬의 부엌만 찾게 되네요!', 10, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '수플레 맛집답게 수플레 종류가 엄청 다양하네요~ 반가워딸기는 딸기도 신선한데 빵이 너무 부드러워서 입안에서 살살 녹네요~ 생크림 안좋아하는 1인인데 여기 크림은 느끼함 1도 없고 빵이랑 푹푹 찍어 먹어면 완전 달콤하니 맛있어요~ 에비타마고는 바삭한 빵안에 부드러운 계란마요와 쉬림프, 홀그레인 소스 조합이 잘 어울려요👍 분위기도 좋고 포토존 따로이 있어서 사진 찍기에도 좋네요~', 18, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '한 번쯤 와 보고 싶던 라헬의 부엌을 드디어 와 보게 됐어요 맛도 좋고 친구와 수다 나누기에도 완전 적합한 장소 넘 좋아요!!', 446, 36, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '동생이랑 방문했는데 딱 마침 자리가 나서 바로입장했어요 ! 더운 날씨에 빙수 먹고싶었는데 수플레 보자마자 수플레 시켰어요 🤤🤤🤤 메론/복숭아 시즌일때 다들 꼭 드셔보세요! 🍈🍑', 83, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '홍대입구역 근처 사랑스러운 공간 ‘라헬의부엌’ 방문했어요!! 분홍분홍 포인트가 돋보이고, 크리스마스 시즌이라 연말 분위기 물씬나게 꾸며 두셔서 분위기가 넘 좋아요☺️ 딸기시즌이라 딸기모찌 수플레 시켜봤는데 비주얼도 맛도 넘 훌륭하네요👍🏻♥️ 라헬의부엌 홍대점에서 맛있는 디저트도 즐기고 연말데이트도 하면 딱일거 같아요!! 라헬의부엌 홍대점 추천이에요!!! 👏🏻😊', 22, 9, 'GOOD', SYSTIMESTAMP);
