INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '디저트 너무 맛있어요ㅠㅠㅠ 수플레는 입에 들어가자마자 녹구 아이스크림도 딸기도 최고.. ㅠㅠ 대구에서 왔는데 또 생각날것 같아요퓨ㅠ', 28, 4, 'GOOD', SYSTIMESTAMP);
