INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '홍대에서 즐기는 브런치, 디저트, 커피 모두 맛있는집이에여!!!😍 쉬림프아보카도랑 말렌카 월넛 케이크 너무 맛있어요!! 라헬의부엌 또 수플레는 워낙에 유명하구요~ 분위기도 계절따라 변해서 언제가도 좋구,, 혼브런치 혼카페 즐기러 오는 단골도 엄청 많은 이유가 있어요❤', 18, 1, 'GOOD', SYSTIMESTAMP);
