INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '친구가 오고 싶다고 해서 왓어요!!! 아이스크림이 진짜 우유 같고 수플레 미쳣어요ㅠㅠㅠㅠ 너무 맛잇습니다 홍대오면 또 오겟습니다!!!', 25, 7, 'GOOD', SYSTIMESTAMP);
