INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '진짜 홍대 디저트 카페 맛집이네요! 수플레도 넘 맛있고 커피도 진하니 진짜 맛있더라구요. 다음에는 브런치 먹으러 가보고 싶어요', 13, 4, 'GOOD', SYSTIMESTAMP);
