INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '일주일 째 라헬의 식탁 수플레가 너무 땡겨서 먹으러 나왔는데 일요일에 인프피가 밖으로 나온것이 후회하지 않는 맛 라모닝이랑 반가워 딸기 시켰어요 고기질과 단맛의 조화를 위해', 83, 15, 'GOOD', SYSTIMESTAMP);
