INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '예전부터 알던 라헬의 부엌. 팬케이크 맛집. 겨우 자리잡음ㅋㅋㅋ 널널한건 2층. 화장실도 2층에 있는데 화장실 향기 좋아요. .주문한건  딸기 망고 크림브릴레인데 . 크림브릴레가 제일맛있음 딸기말고 이거드세요 모두가 인정. 제철이고 이뻐보이는 건 딸기긴한데 크림덮힌 크림브릴뤠가 제일 맛있어요 딸기말고 이거이거 모두 이거먹어요.. 특히 바나나 존맛. 시원하게 1 인 1 케이크로 케이크먹으러와서 7 만원 쓰고 감ㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋ . 괜찮아요 난 도ㅐ지니까', 19, 2, 'GOOD', SYSTIMESTAMP);
