INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '조금 비싸지만 맛있고 예뻐요! 다만 케이크가 포크로 잘 안 썰리는데 나이프가 없어서 마구마구 분해시켜 먹었어요 ㅋㅋㅋㅋ 나름 재밌었습니다!!', 25, 7, 'GOOD', SYSTIMESTAMP);
