INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '올때마다 사람이 많아서 가지못했는데 좀 일찍 오니까 자리가 먾아서 드디억 먹고 갑니다~~ ㅎㅎ 빙수랑 수플레 넘 맛잇어요!!!', 86, 13, 'GOOD', SYSTIMESTAMP);
