INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '사람이 많은 이유가 있었네요! 겨울철이라 딸기가 눈에 들어왔는데 성공입니다. 다른 메뉴도 맛있을 거 같아요! 계절별로 메뉴가 바뀐다고해서 더욱 기대가 됩니다. 베이컨서니는 매콤한 느낌이 들었어요!! 다음에 또 와야겠네요 ^ 0^ 인테리어도 너무 잘 되어있고 이층으로 구성 되어있습니다.', 318, 86, 'GOOD', SYSTIMESTAMP);
