INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '수플레맛집 라헬의 부엌 홍대점 다녀왔습니다. 공간도 넓고 예쁜데다, 대표메뉴인 수플레의 종류도 다양하고 브런치메뉴도 있어서 달달한 수플레와 두가지 매력을 느낄수있어서 좋았어요! 인기가 많은 곳이니 꼭한번 방문해보세요😗', 31, 2, 'GOOD', SYSTIMESTAMP);
