INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '홍대에서 유명한 수플레 팬케이크 드디어 먹었습니다!! 계란 향기가 뿜뿜 나고 산뜻한 생크림과 딸기와의 조화도 엄청 나네요 특히 기대 안 했던 커피가 너무너무 고소하고 맛있어서 수플레 팬케이크 드시는 분들은 커피 꼭 시켜 드시길 바랍니다!!! 다음에 또 올게요 맛있게 잘 먹었습니다~~', 1, 2, 'GOOD', SYSTIMESTAMP);
