INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '반가워 딸기랑 딸기 친구 딸기, 말렌카 케이크 코코아 맛으로 주문했는데 당보충 제대로 하고 왔습니당 딸기도 완전 싱싱하고 상큼한데 수플레 케이크도 퐁신하고 부드러우면서 계란 잡내가 하나도 안나서 넘 맛있게 먹었어욤 크림도 동물성이라 우유향이 나면서 담백했고 메이플 시럽까지 뿌려 먹으면 달다구리 그 잡채에욤 말렌카 케이크는 초코향이 은은하게 나는데 여기에 꿀의 풍미까지 더해져서 완전 꾸덕하고 달달해욤 생크림까지 더해지니 부드러움도 더 잘 느껴졌고 딸기라떼도 상큼부드럽고 너무 맛있었어욤 딸기 과육이 씹히는데 너무 달지도 않고 우유의 담백하고 부드러운 맛 위주라 부담스럽지 않아 좋았습니당 인테리어도 너무 예쁘고 크리스마스 분위기도 물씬나서 데이트 코스로 완전 딱입니당', 2, 3, 'GOOD', SYSTIMESTAMP);
