INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '인생 첫 수플레!!!! 인데 너무 맛있었어요 ㅠ.ㅠ 체리 수플레랑 초코바나나 수플레, 티파티 티 주문했어요 너무 부드럽고 크림, 아이스크림, 과일이랑 같이 먹으니까 조합 최고!! 차도 찻잔에 나와서 좋고 수플레랑 잘 어울렸습니다 매장이 넓은데도 손님이 가득한 이유를 알았습니다... 또 먹으러 올게요❤️', 67, 14, 'GOOD', SYSTIMESTAMP);
