INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '수플레 케이크랑 샐러드 모두 맛있었던 라헬의 부엌! 수플레 비주얼이 너무 귀여워서 외국인 관광객들도 엄청 많더라구요. 추천합니다 ❤️', 22, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '어차피 묻힐까 싶어 안 쓰려다가 너무 화나서 리뷰 씁니다. 웨이팅이 있으면 기다리는게 맞는거고 인원이 몇명이든 엄연히 돈내고 음료 사먹는 ”손님“입니다. 짐이 많아 4인석에 앉아 있으니,웨이팅 때문에 2인석에 앉아달라는 말을 결제하고 들은 저로서는 좀 당황스러웠습니다. 애초에 카운터에서 웨이팅이 있을 경우에는 2인석 이용을 부탁드린다는 멘트라고 해줬으면 알겠다고 했을텐데 전혀 배려심이 없다는게 느껴지네요. 디저트 안 시키면 한시간 제한도 웃기지만 음료도 컵 잔에 잔뜩 묻혀서 내어주고 케이크에 올라가는 딸기도 책상 위에서 준비하는게 아니라 보는 앞에서 물건 주고 받듯이 딸기를 올리더라구요. 제딴에는 돈주고 음료사고 카페 이용하려고 왔는데 돌아가면서 눈치주고 일행 언제오냐고 물어보니 기분 진짜 최악입니다.', 65, 18, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '수플레 부들부들해서 너무 맛있고 특히 아이스크림과 체리가 맛있어요. 카페 분위기도 따뜻하고 겨울느낌 가득,,버블밀크티도 먹었는데 맛있었습니다🩷', 12, 10, 'GOOD', SYSTIMESTAMP);
