INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '라헬의 부엌 홍대점 홍대 단골들은 무조건 한번이상 방문해본 가게일것 같아요 저는 친구들이랑 카페에서 디저트 먹을 겸 솜깅 사진 찍으러 가는데 오늘은 갔다가 크리스마스 장식 너무 예뻐서 사진 오천장 찍었어요ㅠㅠ 그리고 무슨 크리스마스 신메뉴라고해서 딸기모찌수플레가 나왔는데 .ᐟ .ᐟ 이거 진짜 쫀득하고 너무 맛있었어요ㅠㅠ 미친놈임 꼭드세요 저는 일반보다 이게 더 특색있고 좋았던듯 게다가 수플레가 너무 달지않고 딱 적당했어서 좋았어요 홍대 나들이 카페로 추천드려요', 22, 8, 'GOOD', SYSTIMESTAMP);
