INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '[서울 ] [마포구] 와우산로, 홍대앞 카페, 동교동에서 경의선숲길 걷다. 서교동 서강대입구까지 잘 걷다 return . 잠시 다리 휴식 제공차 방문, 마눌과 따님 좋아 하시니 good. coffee잘 안드시는 wife도 내 커피에 행복해할정도로 달달 구리 맛. 젊은이들 많으시네, carbo, sugar 많은 차림, ^아 메리 카 no^ 가 포함되어야 깨운해질 맛 ㅎ 어르신들 입맛에는 많이 달달할듯, 잡숫고 많이 walk 하셔야 fat 축적 피하실수 , stress가 엄습할 땐 많이 relax%해 줄수 ... 참고하샴, but 입가심 커피 꼬~옥 필요할듯, 25년도 가화만샤셩임당 ~', 24, 3, 'GOOD', SYSTIMESTAMP);
