INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '딸기수플레 너무 맛있어요ㅠ 아이스크림, 생크림, 딸기 올려서 먹으면 꿀맛이에요! 레몬케이크도 하나 먹었는데 오! 레몬 맛 진하고 너무 맛있었어요. 카페 분위기도 예뻐서 데이트로도 좋을 것 같아요', 10, 1, 'GOOD', SYSTIMESTAMP);
