INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '기분 좋은 크리스마스 마을이에요. 지나가다가 저기 한 번 꼭 가봐야지 했던 곳인데 드디어 와보네요. 크리스마스 시즌 메뉴인 모찌 딸기 수플레 먹었는데 딸기도 많고 부드럽고 달콤한 기분 좋은 디저트네요! 라떼도 맛있어요~', 49, 6, 'GOOD', SYSTIMESTAMP);
