INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '전반적으로 라헬의부엌 홍대점은 맛있는 음식뿐만 아니라 아늑한 분위기까지 갖춘 곳이었어요. 브런치 메뉴도 신선하고 푸짐해서 든든하게 즐길 수 있었고, 디저트인 팬케이크는 정말 인생 팬케이크라고 할 수 있을 정도로 만족스러웠습니다.', 106, 25, 'GOOD', SYSTIMESTAMP);
