INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '홍대 수플레 맛집 라헬의부엌 홍대점! 여기 수플레 가격대가 있긴 하지만 맛있습니다 ㅎㅎ 퐁신부들 브런치도 넘 맛있게 잘 먹었어요~! 인테리어 예쁘고 사장님 친절하셔서 남녀노소 많이 오더라구요 ㅎㅎ 추천합니다! 다만 이 때 12월이라 그런지 딸기가 단편은 아니었는데 이제 제철이니 괜찮지 않을까 싶어요~', 38, 10, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '홍대 근처에 수플레 맛집 귀엽고 아기자기한 카페 라헬의부엌에서 맛있게 먹은 딸기 스풀레에요 1.2층이라 공간 넉넉하게 있었지만 만석이라서 자리 찾기가 쉽지 않을만큼 인기가 좋은 곳인가봐요 외국인도 많이 찾아오는 디저트 카페인가 봐요 수플레 풍신하고 맛있게 먹었어요 🥰', 1, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '라헬의부엌이 유명한 이유를 알겠음 수플레가 유명한 곳이라 무화과로 주문했는데 막 달지않아서 좋아요. 그리고 빵도 부드럽고 크림이랑 아이스크림 모두 좋은걸 써서 그런지 우유맛 많이나는 찐한 맛이 아주 좋아요! 생각보다 브런치가 엄청 맛있었는데 치킨커리?처음 먹어보는 조합인데도 신선하고 너무 맛있어서 깜짝 놀랐네요. 다먹으니 양도 꽤 많은듯 배부르고 음료도 맛나요~~', 8, 7, 'GOOD', SYSTIMESTAMP);
