INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '맛은 애초부터 기대 안했지만, 정말 최악. 아아는 얼음양도 엄청 부족하고 맛은 … 아우.. 게다가 너무너무 시끄러움. 말소리도 안들림. 괜히갔음. 돈아까워 ㅠㅠ', 6, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '수플레 팬케이크 맛집 라헬의 부엌 🥞 딸기 수플레를 주문했는데 따뜻하고 폭신폭신해서 부드럽게 넘어가고 커피랑 잘 어울렸어요. 2층까지 있는데 매장이 넓고 편하게 쉬기 좋네요 😊', 79, 11, 'GOOD', SYSTIMESTAMP);
