INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '수플레 케이크 완전 퐁신퐁신하고 생크림도 너무 맛있어요 계절메뉴로 딸기 나왔다고 해서 주문했는데 초코바나나도 눈에 아른거려서 결국 둘다 먹기로ㅎㅎ 둘이 먹기 많았지만 배터지게 먹었습니다-!! 좌석도 넓고 외국인 손님이 많이 오더라구요 홍대디저트카페로 추천합니다~! *본 리뷰는 업체에서 이용권을 제공 받아 작성되었습니다.', 35, 7, 'GOOD', SYSTIMESTAMP);
