INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '수플레 비싸긴 한데 맛있어요 근데 가게 자체가 환기가 잘되는 느낌은 아닌...? 그리고 인기 많은 곳이라 음식 나오는데 좀 걸려요', 81, 12, NULL, SYSTIMESTAMP);
