INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '🥑쉬림프아보카도는 바케트빵과 🍅토마토 위에 🥑아보카도와 새우가 얹어 🔥불맛나는 통통한 🍤새우가 입맛을 자극시키면서 쉬림프의 통통,불맛,짭짤함과 바케트가 잘 조화를 이뤄서 맛있고, 🥬싱싱한 야채로 이루어진 샐러드까지 더해져 한끼 💪건강한 식단의 묘미를 체험할수 있었어요🤠 🍗치킨커리샌드위치는 🥖바게트에 오일과 🥑아보카도, 잘게썰어진 치킨거리를 바게트에 올려 먹으니 다양하고 😋건강한 식감에 샐러드까지 아주 베리굿‼️ 🍇청포도에이드의 청량함과 새콤달콤함에 ☕️카페따레의 달달함으로 입안을 정리해주면서 뱃속 든든하게 채워주었더니 🍁가을날씨에 맛있는 식사까지 할수 있어 기부니가 짱조아😍', 64, 18, 'GOOD', SYSTIMESTAMP);
