INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '수플레가 진짜 맛있었고 가격이 좀 비쌌지만  꽤나 괜찮았습니다. 근데 혼자 가니까 굉장히 눈치를 주더군요. 분명히 바닐라 라떼를 시키고 지인 기다리는데, 한 잔만 시키는 거에 대해서 굉장히 물어보고,, 지인이 언제 오는지까지 계속 캐물었습니다! 그 부분이 굉장히 아쉬웠고 실망스럽습니다. 1명이든 2명이든 고객입니다. 아쉬웠지만 맛있게 먹고 갑니다.', 29, 9, 'BAD', SYSTIMESTAMP);
