INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '수플레 팬케이크는 처음이었는데 대박 맛있네요 부들부들해서 입에서 금방 없어져요 둘이서 순삭함!! 직원분도 엄청 친절하셔서 기분 좋았어요 화장실 청소 중이시던데 위생에 신경쓰는 것 같아 믿음이 갔어요', 4, 2, 'GOOD', SYSTIMESTAMP);
