INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라헬의부엌 홍대점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '평일인데 만석이였고 주문후 20-30분 후 디저트가 나왔습니다. 바쁘신데 친절하게 응대하시는 남자 직원분이 기억에 남네요! 수플레도 최근에 먹은 수플레중에서 이치방이였습니다❤️', 52, 14, 'GOOD', SYSTIMESTAMP);
