INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '튜토리얼'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '신기한 디저트가 있어서 가봤는데, 자이언티님 아버님께서 운영하시는 카페네요! 통창으로 햇살이 들어오고,  아늑하게 머무를수 있어요. ⭐️아이스크림라떼, 초록에이드, 구겨진종이케이크 모두모두 추천합니다. 특히 구겨진종이케이크는 초코펜으로 직접 꾸밀수 있어 재미있기도하고, 맛도 있어요! 귀여운강아지도 있지만, 눈으로만 예뻐해주세요❤️', 87, 12, 'GOOD', SYSTIMESTAMP);
