INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '튜토리얼'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '전참시에서 보고 꼭 한 번 가봐야지 했던 카페!💓 평소에 자이언티 가수님 팬이라 유심히 봤는데, 가보니까 더 좋았어요! 사장님의 감각적인 취향이 담긴 공간을 많이 볼 수 있었고, 귀여운 강아지 토리가 있어서 힐링 했답니다! ▪︎구겨진종이케이크 초코펜으로 직접 드로잉해서 즐기는 케이크 🎂 은근 그리기 어려워서 단순하게 그리는게 더 예쁘게 나오는듯해요! 생일이나 기념일에 가서 직접 레터링케이크 만들기도 좋을 것 같더라고요! 브라우니와 크림으로 이루어진 케이크라 달달해서 맛있었어요. ▪︎말차라떼 진한 말차맛에 부드러운 크림이 더해진 말차라떼🍵 상위버전 인절미 말차라떼도 있답니다!', 225, 47, 'GOOD', SYSTIMESTAMP);
