INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '튜토리얼'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '카페 분위기도 좋고 음료도 정말 맛있었습니다. 말차라떼 크림도 쫀쫀하니 맛있게 먹었습니다. 말차맛도 진해서 더 맛있게 먹었습니다. 그리고 카페라떼도 정말 맛있게 먹었습니다. 라떼가 고소하면서 진해서 더 맛있게 느껴졌습니다. 분위기도 좋아서 더 맛있는 커피였습니다', 40, 8, 'GOOD', SYSTIMESTAMP);
