INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '튜토리얼'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '분위기가 너무 좋다고 생각했는데 사장님 패션센스가 좀 남다른거에요 “오! 좀 힙하시다!” 했는데 자이언티 아버님이셨어요 어쩐지 진짜 패션센스가 남다르시더라구요! 전체적으로 화이트톤이라서 사진도 정말 잘나오고 음료도 맛있었지만 강쥐도 넘 순딩하고(그러나 만지면 안됨) 구겨진 종이케이크도 주문했는데 그림은 비록 망했지만 진짜 찐한 브라우니케이크여서 당충전 완전 쭉쭉 됐어요😆🔥', 20, 6, 'GOOD', SYSTIMESTAMP);
