INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '튜토리얼'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '상수역 느낌좋은카페 튜토리얼 🫶 감성 가득이라 내부 인테리어도 공간마다 넘 이쁘구요 토리라떼 고소하니 커피맛집이에요👍구겨진 종이 케이크 내맘대로 이쁘게 케이크 꾸미기 가능해요💜💜 넘 귀여워버렷 커피 디저트 분위기까지 모두 갖춘 상수역 분위기 좋은 카페 튜토리얼 추천드려요 ✨️', 51, 15, 'GOOD', SYSTIMESTAMP);
