INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '튜토리얼'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '오랜만에 너무너무 맘에 드는 카페를 발견했어요!! 인태리어도 넘 예쁘고 사진 다 잘나와요. 케이크 귀여울뿐만 아니라 브라우니 쫀득하고 맛있어요. 멍뭉이도 멋있고 귀여워요 ㅎㅎㅎㅎ ㅜㅜ또 갈게요!!', 61, 11, 'GOOD', SYSTIMESTAMP);
