INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '튜토리얼'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '직접 그림 그릴 수 있는 케이크가 너무 귀여워요 ㅎㅎㅎ 초코펜으로 하니까 은근 어려운데요?! 카페 분위기도 넘넘 좋았습니다~~', 0, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '튜토리얼'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '상수 온 김에 들렀는데 자이언티 아버지가 하는 곳이라니..!! ㅋㅋㅋㅋㅋㅋㅋ 인테리어가 참 깔끔합니다. 또 구겨진 종이케이크는 진짜 기발한거 같아요!!!!! 기발하기만 하고 별 맛 없을 줄 알았는데 안에가 초코 브라우니처럼 되어 있어서 더 좋았습니다🫶🏻 그리고 강쥐가 있는데 와줄 듯 말 듯 하다가 결국 안오더라구요🥹🥹 카페에 가면 루틴한 이야기나 진부하고 따분한 이야기만 하고 오는 경우도 있는데 구겨진 종이케이크로 재밌게 보내고 갑니다^____^👍', 42, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '튜토리얼'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '구겨진 종이 케이크 너무 귀여워요! 사장님도 너무 재밌으시고 친절해요! 아인슈페너 말차라떼도 맛있어용! 음대생 또 갈게요! 기억해주세용><', 114, 22, 'GOOD', SYSTIMESTAMP);
