INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '튜토리얼'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '자이언티 아버지 그리고 토리가 있는 카페 공간 및 카페 사진이 잘나와여 그리고 종이케이크에 예쁘게 초코시럽으로 그림기까지 좋아용', 47, 10, NULL, SYSTIMESTAMP);
