INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '튜토리얼'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '케이크에 직접 그림을 그릴 수 있는 상수 카페! 자이언티 아버지가 운영하신다는 카페인 걸 리뷰 쓰다가 알게 되었네요 ..! 왠지 힙 하시더라 ☺︎ 처음에 어디지 하고 헤매다가 토요일 2시쯤 방문했는데 사람이 많지 않았고 아늑해서 대화하기 좋아요 귀여운 강아지도 있는데 중간중간 손님들한테 인사만 하고 자리에 가서 쉬더라고요 똥손이라 빵빵이 그림을 그렸지만 망쳤습니다 ..! 그래도 그리는 재미가 있고 아아 산미도 없어 데이트 또는 힐링하러 올만 합니다', 19, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
