INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '튜토리얼'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '화이트톤이 깔끔한 카페입니다. 자연채광 느끼기 너무 좋았어요. 안에 큰 강아지가 목줄 안하고 있으니 강아지 무서우신분들은 오시면 안되요! 커피는 고소한 맛이 부드럽고 맛있습니다. 여기만의 시그니처가 흰 케이크(안은 초코) 인데 직접 초코펜으로 그릴 수 있어요. 다만 냉동케이크고 맛은 그닥입니다. 채광 즐기며 커피 즐기기는 너무 좋아요.', 31, 5, 'GOOD', SYSTIMESTAMP);
