INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '튜토리얼'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '그림그리기 좋아하는 아이와 둘이 방문해서 행복한 시간 보내고 왔어요~ 커피도 맛있고 딸기라떼도 맛있고 케이크도 맛있어요 ㅎㅎ 너무 힙하고 mz스러우면 저는 좀 힘든데 적당히 세련되고 편안한 분위기라 아주 좋았습니다 새로운 카페 다니는걸 좋아하는데 여긴 재방문 할꺼 같아요~', 76, 17, 'GOOD', SYSTIMESTAMP);
