INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '튜토리얼'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '강아지 카페 요즘 인기 많은 건 알겠지만 이 친구가 편하게 쉴 수 있는 방석이나 공간이 딱히 없어보이네요.. 바닥에 닿는 부분 팔꿈치도 까져있구 딱딱한 바닥이라 걱정되어요ㅜ 창 밖만 보고 있는데 좀 안쓰럽더라구요.. 음악 볼륨도 좀 많이 큰 것 같아 이런 부분 개선되면 훨씬 더 좋을 것 같아요!ㅎㅎ', 90, 18, NULL, SYSTIMESTAMP);
