INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '튜토리얼'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '찾아가는 길이 좀 어려웠어요 그래도 재밌게 놀 수 있어서 좋고, 카페 내부에 개가 있어요! 장모견이 아니라 완전 단모?견이에요', 312, 93, NULL, SYSTIMESTAMP);
