INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '튜토리얼'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '케이크에 직접 그림을 그릴 수 있어서 너무 귀여워요! 자이언티 아버님이 운영하시는 카페라고 알고 있는데 사장님 너무 재미있으시고 친절하세요 ㅎㅎ', 33, 10, 'GOOD', SYSTIMESTAMP);
