INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '튜토리얼'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '친절하고 깨끗해서 좋아요. 음악 선곡도 탁월! 역시 자이언트님의 아버님 가게답습니다. 직원분들도 훈남들이시고 친절하세요^^  커피도 맛나요^^  벽면들을 장식한 생활예술인들의 그림들도 까페와 더불어 멋지네요🥰👍👏👏', 111, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '튜토리얼'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '자이언티아버지가 운영하는 카페에여~~~노랑에이드와 말차라떼, 구겨진 종이 케이크시켰어여~~케이크는 작지만 직접 꾸밀수있어서 좋아여~~', 98, 24, 'GOOD', SYSTIMESTAMP);
