INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '튜토리얼'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '까까머리에 염색하고 팔에 타투한 알바생보아라! 저번주에 울애들이 갔는데 너 진짜 개 불친절 하고 웨이팅하는  우리애들 앞에서 담배도 오지게 피고 주방으로 들어갔다는데! 너 손은 씻고 음식만드니? 그리고 뭐? 주문하는 울애들한테 뭐라했다며? 웨이팅하는 손님 면전에 대고 담배연기 내뿜는데 울애들이 순진하고 착하니 그나마 지들끼리 궁시렁한걸갖고 또 뭐라했다며?너 그딴식으로 남의 업장(가수 자이언티까지 싫어짐)에서 알바하는거 아니다! 더럽고 치사한꼴 보기싫음 알바  때려치던지!  부모님앞에 부끄러운  아들이 되지 않기를  바래요~~아드님♡', 27, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '튜토리얼'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '디저트는 특색있고 좋아요! 근데 카페 앞에서 알바생이 담배피시는건가요 ㅜㅜ 오픈형 카페인데 앞에서 지속적으로 피셔서 안으로 담배냄새가 들어와요.. ㅜㅜ', 24, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '튜토리얼'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '생각보다 매장이 넓고 쾌적해서 놀랐어요 그동안 갈까말까 망설였었는데 진작 와볼걸 하는 생각이 드네요! 일단 입구에서 해먹이가 반겨주는데 시크하고 귀엽고 너무너무너무 좋아요💕 일단 해먹이한테 별 다섯 개 드립니다. 인테리어가 좋으면 음료나 디저트가 맛없는 경우가 많은데 여기는 메뉴도 맛있고 인테리어도 괜찮고 사장님도 친절하셔서 너무 좋아요!! 그리고 구겨진 종이케이크에 직접 그려보라고 초코시럽 주시는데 이게 너무 재밌네요! 다음에도 또 가려고요ㅎㅎ', 44, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '튜토리얼'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '일단 분위기로 별점 4점은 그냥 먹고 들어갑니다.. 처음엔 너무 하~얘서 당황스러웠는데ㅎㅎ깔끔하고 편하게 있기 너무 좋았어요. 강아지도 귀엽고 모두 친절하십니다! 상수동 카페거리 가시면 들러보세용', 46, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '튜토리얼'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '분위기 좋아요 ㅎㅎ 공간도 나름 분리 잘되어있구요~ 대신 음료는 그냥저냥 먹을만하긴 했는데 와 ~ 맛있다 이런 건 아니었어용 ㅠㅠㅋㅋ', 18, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '추석세트로 주변에 선물하기 너무좋은거같아요 케익도 정말 맛있습니다👍 괜히 5성급호텔 파티쉐의 베이커리가 아닌가봐요 아기자기한 케익이라 부담도 없어요❤️ 분위기와 카페 향이 좋아서 아늑했어서 종종 이용할거같아요 선물하기 좋은것들이 많아요', 6, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '솔티드카라멜휘낭시에랑 당근케잌,밤휘낭시에까지 너무 맛있어서 또먹고 싶어요 종종 들러 디저트먹는데 역시 맛있는곳이라 방앗간처럼 디저트 땡길때 꼭 들러야 합니다용 오늘도 냠냠 하고 가요', 5, 7, 'GOOD', SYSTIMESTAMP);
