INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '이벤트로 망고쉬폰 무료 시식을 했는데 쉬폰이 촉촉하고 폭식해서 맛있어요!! 쉬폰 사이에 망고퓨레가 잘어울려서 맛있었어요☺️ 커피는 제돈제산인데 산미있는 원두를 좋아하지만 원두는 한가지였어요! 고소한 원두였는데 커피도 맛있었습니다☺️☺️ 다른 구움과자랑 미니케이크 먹으러 또 방문할 것 같아요.', 41, 9, 'GOOD', SYSTIMESTAMP);
