INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '연남동에 있는 카페 처음 방문했는데 분위기도 좋고 인테리어도 좋고 케이크도 맛있네요!! 평일 낮에 방문했는데 시끄럽지도 않고 대화하기 딱 좋았어요ㅎㅎ 달달한거 땡겨서 초코케이크 먹었는데 담엔 귀여운 당근케이크 먹어보고 싶네요!!ㅎㅎ', 49, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
