INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '밥도 두둑히 먹고 차곡 문닫을까봐 헐레벌떡 뛰어왔네요!!!! 동료들과 홍대 투어하고 디저트 먹어야지!! 디저트는 차곡이지~❤️ 서로의 입맛이 달라 취향적인것들 하나씩 담아 동료들이랑 조금씩 나눠먹고 아메리카노와 같이 먹으니 행복감이 몇배인지~ 오늘 스트레스 받은거 싹 다 날라갔어용 에그타르트는 속안이 겉바속촉!!! 두바이초콜릿은 말해 뭐해 그냥 잡숴봐요~ 제 입맛도 한 까다로움 하는데 치즈케이크랑 당근케이크는 커피랑 같이 먹으면 넘넘 맛있어요!! 고소하다고 해야할까? 사장님~ 디저트 정말잘해요 강추에요 이집 존맛탱이에요 ~ 집에가서 또 먹고싶어서 포장도 해가지고 갔네요^.~', 5, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '케이크가 넘 맛있는 차곡파티세리에요 음악 인테리어 분위기 넘 좋아 데이트하기도 좋고 혼자 힐링하기도 좋은 카페에요~  번잡한 홍대 중심가와 다른 분위기 좋은 카페에 디저트까지 맛있어 넘 좋은데요  글루프리 케잌이라 부담 없이 먹을수 있구요 촉촉한 티라미슈도 넘 맛나요~ 피곤한 오후 진한 아메리카노에 티라미슈 드시길 강력추천드려요ㅎ', 28, 9, 'GOOD', SYSTIMESTAMP);
