INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '연남동 어쩌다 한번 가는데 갈때마다 방문하게되는 좋아하는 디저트 집입니다 처음엔 빙수랑 쇼트쿠키만 먹었다가 옆테이블 시킨거 보고 맛있어보여서 초코케이크랑 에그타르트 추가주문해서 먹었는데 추가 안했으면 후회할뻔했어요 초코케이크는 크림도 엄청꾸덕하고 시트도 꾸덕하지만 입에 넣으면 사르르녹아요 크림이랑시트가 조화롭습니다 같이 먹었던 친구는 케이크 별로 안좋아하는데 인생케이크래요 지난번에 먹었던 아이스크림이랑 래밍턴 케이크도 맛있는거 보니 모든 디저트가 다 맛있는거 같아요 단골고객은 적립도 10프로로 변경되어서 너모 좋아요♥', 5, 10, 'GOOD', SYSTIMESTAMP);
