INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '유럽 골목카페같이 예쁜 연남동 디저트 카페네요 수제초콜릿도 있고 케이크도 찐득 쫀득하니 진한 커피랑 잘 어울립니다 홍대역 에서 가깝기도하고 길가에 있어서 쇼핑하다 쉬기 좋네요 내부 공간도 이쁘고 화장실도 있고 친절하심', 46, 8, 'GOOD', SYSTIMESTAMP);
