INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '우연히 딸이랑 홍대갔다 방문했는데 수제케이크라 달지 않아 너무 좋았고 커피도 산미없이 고소하고 맛있었어요~ 호텔 파디쉐가 만든다고 하셔서 좋았는데 수제초콜릿이나 케익 선물하기 넘 좋을것 같아요~', 12, 1, 'GOOD', SYSTIMESTAMP);
