INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '여러분 여기 수제 케이크 맛집이라고 해서 방문해보았는데 미쳤어요 ! 다들 꼬옥 와보셔야해요 🙃🫶🏻 인생 치즈케이크를 만났어요 ! 밑에는 타르트지에 크림 가득에 크럼블 조합 .. 💗 고급스러운데 맛있어요 ! 수박 주스는 생과일 주스라 진짜 여름에 시원하게 먹기 딱이에요 ! 커피도 고소하니 디저트랑 찰떡이에요 !! 홍대 연남 연희 카페 고민중이시라면 차곡파티세리 추천드려요 🎉', 38, 4, 'GOOD', SYSTIMESTAMP);
