INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '매장 이전 후, 첫 방문이에요! 토끼가 올라가서 더 귀여운 얼그레이 쉬폰 케이크🤎 얼그레이 정말 진하고 초코와 조합이...🤎 부들부들한 쉬폰의 식감이 너무 좋아요~! 티라미수도 젤라틴이 안 들어가서 크리미한 크림의 질감이 최고입니당ㅠㅠ 음료도 너무 맛있어요ㅠㅠ 초코라떼 완전 찐초코!!🍫😍', 9, 4, 'GOOD', SYSTIMESTAMP);
