INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '디저트 너무 맛있고 음료도 맛있어요..아메리카노 산미없이 고소하고 부드럽고요! 딱 한국인이 좋아할 맛입니다~~ 근데 진짜 찐은 3가지 초콜릿 리얼 핫초코? 이거…아이스로 먹었는데 개미친 도른맛!!! 완전 고오오오급스러운 초코 맛👍🏻', 15, 2, 'GOOD', SYSTIMESTAMP);
