INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '커피가 산미가 없어 좋고, 케익류, 작은 베이커리, 등 디저트류가 다양해서 좋고, 무엇보다 알바생이 잘생겨서 좋아요😍 주방에 계신 직원분들도 너무 친절하시고 분위기, 노래, 온도, 화장실, 다 너무 좋습니다!!!', 12, 10, 'GOOD', SYSTIMESTAMP);
