INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '처음 방문했는데, 너무 맛있어서 놀랐어요..!! 치즈 케이크 진짜 맛있어요.. 위에 크림이랑 크럼블 같이 먹는 조화가 짱입니다.. !!! 그리고 커피도 산미 없고 완전 부드러워서 맛있었어요!! 치즈 케이크 완전 추천 드려용!!!!', 68, 16, 'GOOD', SYSTIMESTAMP);
