INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '홍대카페 검색하다가 케이크가 넘 맛있어보여서 방문했습니다. 당근케이크도 쫀득한게 정말 맛있구요, 에그타르트랑 사브레도 맛있었습니다. 오늘 커피를 많이 마셔서 디카페인 아아를 시켰는데, 맛도 진하고 양도 적지않아서 좋았습니다. 매장도 깔끔하고 좋아요:)', 92, 21, 'GOOD', SYSTIMESTAMP);
