INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '연남 확신의 디저트 맛집..💗 카페도 너무 쾌적하고 넓고 커피, 티라미수 다 넘넘 맛있어요. 여러분 아이스크림 라떼 꼭 시켜보시길..🥺 아이스크림 너무 꼬수운 우유 맛입니다. 디저트 성지순례 할 가치가 있는 파티세리🫶', 31, 1, 'GOOD', SYSTIMESTAMP);
