INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '호박팥차와 아이스티 그리고 초코케이크 먹었습니다! 차는 고소하고 정말 따뜻했어요. 아이스티도 적당히 달달해서 좋았구요. 케이크는 당충전하기 딱이었습니다 ㅎㅎ 배 안 불렀으면 다른 디저트도 먹어볼걸...하는 생각도 했습니다 다음에 또 방문해서 다른 메뉴들도 먹어볼게욧◜◡◝', 20, 6, 'GOOD', SYSTIMESTAMP);
