INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '찾아본 집 아니고 역에 가다가 망고 아이스크림이 보여서 갈까말까... 하다가 들어간 집인데 이날 홍대에서 놀며 먹었던 것들 중 제일 맛있었어요!! 꼭 드셔보세요ㅠㅠ 망고가 이렇게 맛있는 과일이라는 걸 다시 한번 느꼈습니다. 안 먹었으면 후회했을 맛이에요. 홍대 가시는 분들 꼭 드셔보시길 바라요!! 다음에 갈 때까지 망고 아이스크림이 있었으면 좋겠네요ㅜ', 52, 13, 'GOOD', SYSTIMESTAMP);
