INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '연남 카페 원탑이에요 🔥 제가 연남 카페 엄청 많이 다녀봤는데,, 가격도 넘 착한데, 디저트 맛이며 커피 맛이 진짜 너무 좋아요 ❤️ 특히 요 치즈케이크 요물입니다 ‼️ 또 방문할 예정입니다❤️', 33, 7, 'GOOD', SYSTIMESTAMP);
