INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '가게가 아기자기하고 사람이 많이 없어서 좋아요!! 초코 음료가 엄청 초코초코해서 진해요 생각보다 디저트 종류는 많이 없었어요! 까만초코케이크는 엄청 맛있었습니다 강추', 47, 0, 'GOOD', SYSTIMESTAMP);
