INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '분.조.카 제가 정말 좋아하는 카페인데요../// 얼그레이 향이 은은하게 퍼지는 케이크가 너무 마음에 들어요 토끼는 아까워서 어떻게 건드리죠🥺 아아랑 먹으니까 정말정말 어울려요////', 14, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '혼자서 한 번, 친구랑 한 번 갔는데 두번 다 만족이요!!! 디저트 넘 고급져요, 특히 생망고 아이스크림은 진짜 냉동망고 아니고 생망고라 더 맛있고, 끝까지 망고가 나타나요...! 게다가 언니들도 다 친절☺️ 돈 있고 날씬하면 자주 가고싶은 곳이에요', 11, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '기념일이나 선물할때마다 꾸준하게 주문하던 디저트맛집인데 서교동에서 동교동으로 이전하고 처음방문했어요. 전체적인 인테리어가 감각적이고 더 아늑해져서 사장님이 확장하시면서 더 신경쓰신게 느껴지더라구요! 마카롱,케이크,초콜렛 등 디저트종류가 여전히 다양하게 있어서 지인과 입맛에 맞게 여러가지 주문할 수 있어 좋았습니다^_^!! 주문한 달달한 망고쉬폰, 래밍턴과 아메리카노가 부담없이 즐기기 좋았어요. 사장님의 디저트에 대한 자부심도 느껴졌고, 서비스도 친절해서 기분 좋은 시간을 보냈습니다. 홍대에서 디저트에 진심인 카페를 찾는다 면 ''차곡파티세리'' 추천이요!🍰☕️☕️', 71, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '아무리 글루텐 프리라지만… 좀 너무한 맛…. 그냥 진짜 케익이 맛없습니다…크림은 괜찮은데 빵이 너무 맛없어서 크림부분만 먹고 다 남겼네요. 빵이 너무 뻑뻑합니다. 수분을 뺏긴 갸또 식감에 맛은 어설픈 초코 백설기(식감말고 맛만)같습니다… 가격이 비싸지 않았다면 리뷰 안남겼을텐데 싼 가격은 또 아니라…. 진짜 밀가루를 못먹는데 케익은 좀 먹고싶다 하시는 분들도 재고해보셔야하는 맛입니다', 30, 3, 'BAD', SYSTIMESTAMP);
