INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '걸어가다 5성급 호텔 출신 파티쉐님이 하시는 카페라고 해서 방문! 바닐라 크럼블 아이스크림 달지 않고 바삭한 크럼블과 아이스크림이 정말 잘 어울려서 놀랐습니다! 인테리어도 좋고 한적하게 힐링하기에 딱 좋은 곳입니다 ;)', 17, 0, 'GOOD', SYSTIMESTAMP);
