INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '치즈케이크 주문했는데 진짜... 맛 없어요 정말 진짜 5성급 호텔...? 이런 느낌 돈 날리는 맛.... 진짜 치즈가 아니라 밀가루 맛이 납니다 하...', 58, 13, 'BAD', SYSTIMESTAMP);
