INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '신메뉴로 나온 마카다미아 휘낭시에, 초코 휘낭시에 둘 다 먹어보니 딱딱하거나 찐덕하지 않고 담백해서 넘넘맛있더라구요,,,🥹🥹💓 초코처돌이로 초코휘낭시에 원픽입니다!!!!', 13, 9, 'GOOD', SYSTIMESTAMP);
