INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '홍대입구역 근처 5성급 호텔 출신 파티쉐님이 운영하시는 카페 차곡파티세리 완전 추천이욥😍👍 공간 자체도 세련되면서 빈티지함이 물씬 느껴지고 무엇보다 디저트!!! 진짜 너무 맛있어요 까만케이크로 골랐는데 진한 발로나 초코의 맛이 제대로 느껴지고 꾸덕 달달해서 힐링됩니당🤩😊 포카치아도 쫀득하고 퐁신해서 식사대용으로 먹기 좋아요 ㅎㅎ 디저트는 세트 구성으로도 살수있는데 완전 고급스러운 선물로 딱입니다🥹 직원분들도 너뮤 친절하시고 분위기도 좋아서 재방문 의사 완전 있어요😄', 70, 11, 'GOOD', SYSTIMESTAMP);
