INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '리얼초코랑 당근케이크 먹어봤습니다. 당근케이크는 꾸덕하고 견과류 때문에 식감도 있어서 맛있는데 저는 시나몬을 좋아해서 시나몬이 들어갔으면 더 취향이었을 것 같아요.  리얼초코는 너무 진하면 말하라 하셨는데 저는 진한걸 좋아해서 딱 좋았습니다. 가게 바로 앞이 대로라 차 다녀서 문 열어두면 좀 소란스럽긴 해요. 그래도 매장은 깔끔해서 좋습니다.', 46, 8, NULL, SYSTIMESTAMP);
