INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '친구랑 동교동에 원데이클래스 듣고 주변 카페 찾다가 차곡파티세리에 왔는데 분위기가 편안해서 거의 3시간째 카페에 있네요ㅋㅋ :) 케이크는 수제라 그런지 진짜 부드럽고 맛있어요...❤️ 아메리카노랑 찰떡입니다🙊 다음에 또 방문할게요!!', 47, 3, 'GOOD', SYSTIMESTAMP);
