INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '인테리어가 진짜 이쁘고 길 찾기도 쉬워요~ 인테리어가 이뻐서 사진찍기 너무 이쁜곳 케익디저트도 너무 맛있고 사장님도 쏘스윗 친절해요 커피랑 달달구리 초콜렛과 케익 디저트 먹기 딱 좋아요 그리고 무엇보다 조용해서 힐링하가 딱 좋아요 !! 재방문 있습니다', 3, 2, 'GOOD', SYSTIMESTAMP);
