INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '차곡파티세리에서 이렇게 맛있는 디저트와 커피도 즐겼습니다 😋 사장님께서 너무 친절하게 말씀해주셔서 너무 좋은 인상이 남았어요. 다음에 동교동 오면 사장님 그릇 차곡차곡 쌓으실 수 있게 들르겠슴돠 👍', 6, 3, 'GOOD', SYSTIMESTAMP);
