INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '역시 믿고 먹는 차곡❤️ 달콤하고 부드러운 얼그레이쉬폰 케이크랑 따뜻한 홍차 & 커피 조합👍👍 이사한 차곡 처음 이용하는데 매장이 정말 이쁘고 따뜻하고 편안합니다!! 매장안에 깔끔한 화장실도 있어요! 사장님들이 친절하시고 디저트 퀄리티가 좋아서 선물용으로도 강추👍', 41, 9, 'GOOD', SYSTIMESTAMP);
