INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '연남동 주말에 자리이용가능한 차곡파티세리 디저트 카페 너무 좋아요!! 쉬폰 케이크, 초코 케이크를 먹었는데 다른 카페들과 다르게 직접 다 만드는거 같더라구요. 특히 레밍턴 케이크는 흔히 볼 수 없는 디저트라 신기하고 맛있었어요. 커피도 디저트랑 잘 어울려서 맛이 좋더라구요. 주말이었는데 자리도 넓어서 자주 방문하겠습니다!!', 9, 1, 'GOOD', SYSTIMESTAMP);
