INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '가게에 단 내음이 은은하게 번져 좋아요. 디저트가 특별한 게 많아서 보는 눈이 즐거워요ㅁ 계신 분들 모두 친절하시고 예뻐요 :) 잘 쉬다가 갑니다☺️', 35, 1, 'GOOD', SYSTIMESTAMP);
