INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '친구 만나기 전 시간이 비어서 들렀는데 케이크도 일품이고 아이스크림 라떼도 더위 식히기에 넘 좋고 맛있어요~! 기회 되면 다음에 또 와서 먹고싶어용 ㅠㅠ 멀리 살아서 아쉬워요 아무튼 잘 먹었습니다~!', 44, 2, 'GOOD', SYSTIMESTAMP);
