INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '가게도 넓고 인테리어가 고풍스럽고 앤티크해서 처음 들어설때부터 너무 좋았어요! 인파도 많고 인기도 많은 이유를 알겠더라구요. 유명파티셰님께서 직접 만드시는 수제 케이크와 디저트류 가득한데 너무 맛있고 달지도 않고 건강하면서 단아하고 귀엽고 깔끔해요. 연남동 홍대오면 추천하고 싶은 카페에요👍🏻', 32, 1, 'GOOD', SYSTIMESTAMP);
