INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '와 맛있어요. 케이크가 느끼함 없이 쫀득해요. 글루텐프리라 부담없고~ 아이스티 완전 시원하고 청량. 물 한 잔 부탁드렸는데 예쁜 머그잔에 주셔서 감동☺️ 화장실은 안에 있고 깨끗해요.', 110, 22, 'GOOD', SYSTIMESTAMP);
