INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '편안한 분위기, 사장님도 친절하시고 디저트가 맛있어요!! 저 발로나 초코만 찾아 먹는 사람인데 마침 케이크가 발로나라니!! 맛있게 잘 먹었어요 바나바잎차도 있어서 혈당 걱정 없이 행복한 티타임 가졌습니다💕 루비케이크도 맛있게 보여서 담엔 이거 먹으려고요ㅠㅠ!! 내부도 쾌적해서 좋았고 화장실도 가게 내에 있어서 편리했어요!', 79, 14, 'GOOD', SYSTIMESTAMP);
