INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '근처에 새로 생겨서 방문했는데, 처음 본 귀여운 디저트들이 가득했어요❤️ 겉바속촉 최고! 다른 곳에서 확장이전한 곳이라 그런지 매니저님도 전문가스러우셨어요! 연남동에 오면 꼭 와보세요!!', 9, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '매장에서 먹고나서  맛있게 먹어서 나올때 케이크 포장해서왔는데 집에와서 넘 맛있게먹었어요 얼그레이쉬폰 구매했는데 케이크도 달지않고 크림과의 조화도 넘 좋았어요 매장분위기랑 인테리어도 넘 이뻐서 좋았고 친절하게 응대해주셔서  좋았어요', 28, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '항상 갈때마다 예쁘게 포장해주셔서 케이크 살 때마다 기분이 너무 좋습니다 -! 💖💖 얼그레이케이크 좋아해서 남자친구랑 기념일마다 사먹고 부모님이랑도 자주 사먹는데 다들 정말 좋아합니다 -! 크기도 적당하고 특히 빵이 촉촉하구 크림도 인위적인 맛 안나서 넘 좋아요 !!! 그리구 레밍턴 케이크도 맛별로 먹어봤는데 징짜 맛있습니다 -! 이전하고 처음 가봤는데 커져서 다음에 커피 먹으러 갈게요 🧚🏻‍♀️😋😋', 53, 12, 'GOOD', SYSTIMESTAMP);
