INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '얼그레이 쉬폰, 바나나잎차, 아아메. 얼그레이 쉬폰 엄청맛있네요~~! 케이크 안좋아하는 남편도 순식간에 해치웠어요ㅋㅋㅋㅋ 느끼함도 없고 맛있어서 다른디저트들도 궁금하네요. 가게 이전한 후에 넓어지고 인테리어도 이뻐져서 데이트하기에 좋아요', 52, 16, 'GOOD', SYSTIMESTAMP);
