INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '5성급 호텔 출신 파티쉐님이 만들어주시는 수제디저트집이라 케이크가 적당히 달달해서 너무 좋아여!! 아아도 산미없는 고소한 맛이라 디저트에 곁들이기 아주 딱 좋구요!!👍👍', 395, 80, 'GOOD', SYSTIMESTAMP);
