INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '지금껏 먹은 생크림케이크 중 탑 3  안에 들어요! 친구 생일 케이크하러 와서 망고쉬폰케이크 먹었는데 정말 맛있었어요! 망고도 진짜 좋은 걸 쓰시는데 망고스프레드도 찐하고 빵도 촉촉하고 크림도 부드러웠어요..하나도 안 느끼하더라고요..연남 케이크 탑 맛집이라고 자부합니다, 강추요!', 49, 6, 'GOOD', SYSTIMESTAMP);
