INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '친구가 추천해줘서 방문한 곳! 두바이초콜릿, 세가지 초콜렛 핫초코, 애플망도 레밍턴 케이크 주문했어요. 카페 분위기가 너무 좋고 음악 선곡도 마음에 들어서 다음에는 매장에서 먹고싶어요 ㅎㅎ 재방문 의사 만땅!', 16, 5, 'GOOD', SYSTIMESTAMP);
