INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '차곡파티세리를 처음 방문해보았는데 직원분도 친절하시고 확실히 수제 초콜릿의 향기와 풍미가 더해져서 나가고 싶은 생각이 안드네요ㅎㅎ 손님들이 좋아할 만한 초콜릿 맛들이 각양각색으로 배치되어있더라고요! 다양한 맛과 취미를 느낄 수 있어서 좋운 것 같아요!! 선물용 초콜릿을 사러 왔는데 제 마음도 같이 선물받아서 기분 좋아져요!! 오늘 하루도 차곡파티세리와 함께 마무리 해보는 게 어떻세요? 마음도 좋아집니다^^', 12, 4, 'GOOD', SYSTIMESTAMP);
