INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '디저트 다 팔렸을까봐 밥먹고 막 뛰어왔어요..ㅎ 아 옆구리야ㅠ 근데 먹고싶던 디저트들이 남아있어서 얼마나 행복했는지 모르고요.. 한 입 입에 넣자마자 삘스라잌헤븐이에요..💫 이런 저 어떤가요 돼지런스럽나요?', 29, 1, 'GOOD', SYSTIMESTAMP);
