INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '두바이 초콜릿 팔길래 방문한건데 구매한 목록중에 라즈베리 봉봉이 제일 맛있었어요.. 한국인 최고의 칭찬 달지 않고 고급스러워요 요새 단거 못 먹겠어서 그 좋아하던 메가커피 가서 음료 시키면 먹다가 남기거든요 ㅋㅋㅋㅋ 라즈베리봉봉이 진짜 그동안 먹어본 것 중에 제일 맛있어요ㅎㅎ 기분좋게 씁쓰름한 맛이 술 많이 써서 켁 하는 맛도 아니고 부드럽게 넘어가다가 라즈베리맛이 앞에서 씁쓰름한 느낌 없애주고 샥 지나가요 담에 또 사먹으러 갈게요', 24, 3, 'GOOD', SYSTIMESTAMP);
