INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '케이크 예약해서 왔습니다! 매장에서 먹는다고 말씀드려놔서 먹고 갔어요 미니케이크 사이즈는 손바닥만해서 둘이 먹기 너무 좋네요 ㅎㅎㅎ 얼그레이 케이크인데 초코 크림이 잘 어우러져서 넘 맛있습니다!!!', 11, 9, 'GOOD', SYSTIMESTAMP);
