INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '두바이초콜릿 찾아서 카페 왔는데 다른 메뉴도 넘 맛있어요! 두바이초콜릿은 다크초콜릿에다가 바삭하고 견과류 맛도 나면서 너무 맛있어요!! 아이스크림에서 연유 맛 나요 ~ 매장은 조금 작아서 테이크아웃 손님이 많은 것 같았습니다', 27, 2, 'GOOD', SYSTIMESTAMP);
