INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '항상 올때마다 맛있게 먹구가여~ 사장님 매번 웃는 모습으로 맞이해주셔서 감사해요~늘 맛있는 디저트 먹구가용🥰🥰🥰🥰 사장님 오늘은 어디가셨어여~ ㅎㅎ 보고싶어여 행복하세여~', 109, 25, 'GOOD', SYSTIMESTAMP);
