INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '두바이초콜릿 먹고싶어서 근처에서 샀는데 너무 맛이 달랐어요..ㅠㅠ 새끼손가락 길이와 같은 크기에 5천원주고 샀는데 피스타치오맛 하나도 안나고 초콜릿 단맛만 나요.. 심지어 안에는 카다이프도 아니고 대체로 다른 게 들어간 것 같은데ㅠㅠ 여러모로 좀 실망했습니다.. 다음엔 그냥 술들어간 봉봉 초콜릿 먹으러 갈게요😢', 41, 9, 'BAD', SYSTIMESTAMP);
