INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '오늘 케이크 급히 주문 했는데도 만들어 주셔서 감사해용 ^^ 서비스로 주신 초코바 완전 맛있었어용 “오리 초“도 감사합니다^^ 넘넘 맛나요', 44, 3, 'GOOD', SYSTIMESTAMP);
