INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '두바이 초콜릿 먹으러 왔는데 진짜 존맛탱!! 후… 앞으로 두바이 초콜릿 먹고 싶을 때 여기 와야겠어요. 특히 두바이 시가렛 쿠키가 진짜 찐… 친구랑 호들갑 떨면서 먹는 중인데 번창하세용ෆ', 93, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '선물용 초콜릿으로 이쁘고 맛있어보여서 예약하게 되었습니다. 독특하고 이쁜 포장땨문에 이끌렸고, 두바이 초콜릿이 맛있다고 해서 기대되네요 ㅎㅎ 여친한테 선물로 추천드려요~', 45, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '먹기 전에 찍지못하고 거의 먹은 상태에 찍은 상태입니다~ 무더위에 오래 돌아다니다보니까 더워서 그만...ㅜㅜ 여기 유명한데, 디저트 먹어본 적이 있어가지고~ 그 맛에 반해서 여기 카페를 찾아서 들어오게 됐는데, 처음 앉아서 먹게 되니 좋습니다❤️ 두바이초콜렛도 첨 먹어봤는데 예상외로 맛있어서 놀랬네요~ 다른 곳 두바이보다 더 낫더라요....(생소한 맛...) 여기 강추천합니다👏👏👏👏', 23, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '근처 카페 찾아보다 근방에 리뷰제일 좋은데로 방문했어요 ㅎ 매장이 엄청 넓진 않지만 아늑하고 다른 리뷰해주신분 말씀대로 들어오자마자 맛있는 냄새가 한가득.. 초코브라우니바랑 아메리카노를 먹어봤는데 이조합.. 너무 좋고  맛은 말해뭐해 ..ㅋ 와서 드셔보셔야 함돠. 쵝옹~', 135, 95, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '디저트를 좋아하지 않는 제가 너무 맛있게 먹었던터라 가격이 인상 되었어도 개의치 않았어요. 제한이 없대서 완전맛있다고 다들 기대하라고 모임에 사갈거라고 떵떵거려놨는데 당분간 제한이 없다하셨지만 9개를 구매한다고 하니 주방안으로 들어갔다 나오셔서는 대뜸 1인 4개 제한이라셔서 당황스러웠어요. ^^; .. 아이스팩과 초코렛을 보냉봉투에 담아 주시지 않는것도 그 전에는 초콜렛을 박스에 담아주셔서 그러려니 했는데 오늘은 보냉봉투에 감싸진 얼음과 초콜릿 4개를 떨렁 이렇게 주시니 제가 아는 보냉 포장이라는 말이 좀 무색합니다. 길 가다보니 녹아서 제가 보냉봉투안에 우겨넣었네요. 맛은 있습니다. 초콜렛도 다른곳과 다르게 싼맛이 아니구요. 그런데 방문 할 수록 아쉬움이 남네요.', 32, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '내 사랑 차곡..❤️ 길 걷다 우연히 발견한 보석같은 디저트 가게에요❤️ 생일 케이크 주문해서 실패한 적 없고 커피도 진짜 맛있어요..🥹 최근엔 두바이초콜렛에 반해서 자주 먹고있어요 여기저기 먹어봤는데 차곡 두바이초콜렛이 제일 진득하고 피스타치오 맛도 강해요..! 멀리 이사가면서 자주 못가게되어 속상한데 제겐 택배가 있으니까요 후후 차곡파티세리 꼭 더 번창하시길 진심으로 응원해요🫶🏽', 450, 67, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '디저트로 유명한집인것같아 방문했어요. 두바이 초콜릿 줄서야만 살수있는데 줄안서고 예약 가능해서 예약후 토요일 저녁 다 되서 갔는데도 그냥 구매도 가능하더라구요. 그런데 분명 전화랑 문자로 예약했을때 1인 2개라고 하셨는데 바로 앞에분이 3개 구매하시길래 다시 물어보니 재고 있으면 4개까지도 구매가 가능하다고 하네요. 그걸 왜 말씀을 안해주셨는지?ㅎㅎ;; 진작 말씀해주셨으면 혼자와도 되는건데.. 하튼 총 6개 샀는데 다른 후기에 안에 카다이프가 적다는말이 있던데 확실히 적더라구요. 저만 그런게 아니고 같이 먹어본 언니한테도 물어보니 언니도 이말하셨구요. 아무래도 수급 문제 때문에 구하기 어려워서 그런거겠죠? 이해가능한 부분입니다. 많았으면 더 비쌌겠죠. 근데 초콜릿맛에 묻혀 맛있는진 모르겠네요...', 23, 7, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '다양한 디저트들도 많고 요즘 그 유명하다는 두바이 초콜렛이 있는 곳이에요!! 인스타 디엠으로 예약이 가능하니 꼭 미리 예약하구 방문하쎄요! 늦게 가면 없어요오 🥲', 46, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '케이크 진짜 맛있어요!!! 많이 안 달고 맛나요 ㅎㅎ 친구가 가자고 해서 왔는데 앞으로 단골 될 것 같아요 혈당 조절하는 바나바잎차가 있어서 좋아요 ㅎㅎ', 67, 14, 'GOOD', SYSTIMESTAMP);
