INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '도시락 케이크 사이즈에 맛은 훨씬 좋은 얼그레이 쉬폰 케이크예요🫶 둘이 먹으면 적당한 사이즈라 너무 좋았어요. 두바이 초콜릿도 먹어보러 또 와야겠어요!', 24, 7, 'GOOD', SYSTIMESTAMP);
