INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '두바이 초콜릿, 라즈베리, 흑임자, 데낄라 먹어봤어요 너무 맛있어서 몇시간 만에 또 방문 했습니다. 평점이 높은 이유가 있는거 같아요. 두바이 초콜릿 안에 진짜 피스타치오도 조각으로 크게 들어있고 단짠단짠 맛있었습니다. 품절인 초콜릿이있어 아쉬웠어요', 7, 5, 'GOOD', SYSTIMESTAMP);
