INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '와우! 간만에 다 맛있는 디저트집을 발견했어요~ 아이가 케익 사오라그래서 급하게 들른 건데 다 맛있었어요! 다음번엔 초콜릿도 먹어볼거에요', 46, 6, 'GOOD', SYSTIMESTAMP);
