INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '두바이 초콜릿이 궁금해서 다녀왔습니다 비싸지만 궁금해서 먹어봤는데 호기심정도의 가격입니다 다른디저트가 맛있다고 친구의 추천입니다 다음에 먹으로 오겠습니다', 2, 3, NULL, SYSTIMESTAMP);
