INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '망고 쉬폰 케이크 14,000원 저녁 7시에 갔는데 얼그레이 케이크가 없어서(굽고 있다고 했어요ㅠㅠ) 대신 망고 케이크 포장해서 갔어요! 크림도 쉬폰도 너무 부드러워서 들고 가는데 무너져버렸네요 ㅠㅠㅠ 포장하실 분 조심하시길…! 정말 부드럽고 망고도 안에 가득 있어서 너무 맛있었습니다🧡 친구들도 너무 맛있었는지 4명에서 순식간에 다 먹었어요 ㅎㅎㅎ 사이즈는 1호보다 조금 작은 사이즈였던 거 같애요!! 부담스럽지 않은 홀케이크 찾으시는 분에게 추천!!!🫶 다음에도 소모임이 있을 때 사갈 거에요!!!', 9, 4, 'GOOD', SYSTIMESTAMP);
