INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '두바이초콜릿 광공 여자친구 따라 와서 먹었는데 디저트가 너무 맛있어요! 두바이초콜릿 풍미가..살아있습니다. 아이스크림도 맛있었어요 초딩입맛 저격!', 7, 1, 'GOOD', SYSTIMESTAMP);
