INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '카페에 들어오자 마자 버터냄새 가득한게 이 집은 맛집이다라는 느낌이 강력하게 납니다. 초콜렛 단품도 있고 적당한 사이즈의 케이크도있어서 기념일 선물용으로 넘 좋네요. 발로나초코케이크 꾸덕하고 넘 맛나요ㅜㅜ', 103, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '어머니 생신케이크사러 와서 데이트까지❤️ 공간이 아늑하고 커피랑 케이크 전부 맛있어요! 솔티드카라멜아이스크림 꼭드세요!! 강추👍 얼그레이향 가득한 케이크..너무 좋아요..♥︎ 위에 초코크림도 잘어울리고 최고입니다!!👍👍', 49, 5, 'GOOD', SYSTIMESTAMP);
