INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '계속 와봐야지 했다가 주변에 들릴 일이 있어서 와봤어요. 먹고 가기에도 분위기 아늑하고 선물용으로 좋아보이는 초코 디저트들이 많아요🎶', 48, 6, NULL, SYSTIMESTAMP);
