INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '글쌔요. 특별하다는 느낌은 못 받았어요. 포장이 잘 되어 있는 건 좋은데 뜯다가 짜증났어요. 뜯기 편하게 하는 것도 서비스의 일종이 아닌가 싶네요. 두바이초콜릿에 들어가는 재료 가격 형성대는 알고 있는데 들어가는 원재료에 비해 가격이 사악하다 생각이 드네요.', 36, 8, 'BAD', SYSTIMESTAMP);
