INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '들어오자마자 디저트 냄새가 마음을 사로잡았어요 디저트 달고 고급지고 맛있어요!! 주류 메뉴도 있는데 나중에 주류와도 함께하고싶어요🥺', 10, 7, 'GOOD', SYSTIMESTAMP);
