INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '발렌타인 기념으로 남자친구 선물해줬어요. 데킬라봉봉은 첨이라 신기해서 예약 후 픽업했네요. 사장님께서 넘 친절하시고 서비스도 주셔서 잘 먹었습니다. 술이 많이 들어있네요ㅎㅎ 첨에는 쓴데 끝맛이 초콜릿이 어우러지면서 매력있어요!!! 모양도 이쁘고 이벤트 대성공입니다~ 덕분에 감사해요!', 83, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '카페 이름에 파티세리는 역시 아무나 붙일 수 있는게 아닌가봅니다… 치즈케익 하나를 먹었을 뿐인데 이게 디저트지!!! 소리가 절로 나오게 되는 것 같습니다.. 여기서 다른 디저트박스 사서 선물하면 딱 좋을 것 같은데 벌써부터 선물 돌릴 일 없는지 고민하게되네요.. 최고입니당', 33, 0, 'GOOD', SYSTIMESTAMP);
