INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '매장은 조금 작지만 디저트랑 음료가 넘 마싯구 바나나잎차가 첨 마셔보는데 맛있어요! 무엇보다 사장님이 넘넘 친절하셔서 넘 조아요!!!!', 3, 4, 'GOOD', SYSTIMESTAMP);
