INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '서교동 가면 포장해서라도 꼭 먹어야하는 하얀쉬폰🤍 홍대케이크맛집은 아마도.. 차곡파티세리가 원탑이지 않을까 싶네요ㅎㅎ 다음엔 녹차쉬폰주문하고 갈게요!!', 16, 5, 'GOOD', SYSTIMESTAMP);
