INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '늘 차타고 지나가면서 궁금해 했었는데 드디어 와봤네요! 케이크 전문점이라 그런지 케이크 종류가 많아요. 정갈하게 담아주셔서 기분이 좋았어요. 디저트는 많이 달지 않고, 식감이 좋습니다:) 연말 케이크 이곳에서 픽하셔도 좋을 것 같아요!', 0, 2, 'GOOD', SYSTIMESTAMP);
