INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '원래 다른 카페 찾아 가는 길에 눈을 확 사로잡아 들어가게 된 카페예요. 테이블 5개의 작은 카페인데 밖에 디저트 사진이 너무 맛있어 보이더라고요. 실제로 들어가서 보니 메뉴 하나하나도 다 정성스럽고 예쁘게 생겼고 맛도 예상대로 맛있었습니다!! 그리고 드물게 레밍턴을 팔고 있어서 좋았아요. 코코넛가루를 시판보다 더 가신 건지 너무 부드럽더라고요. 살살 녹는~ 음료는 아메리카노 시켰는데 양이 너무 많아요ㅋㅋㅋㅋ 디저트랑 같이 해서 다 마시니까 한 끼 식사한 것 같네요. 우연히 좋은 가게 발견해서 기분이 좋아요. 다음에는 친구도 데려와야겠어요~', 111, 24, 'GOOD', SYSTIMESTAMP);
