INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '플레인소프트아이스크림도 부드럽고 맛있지만 개인적으로 솔티드카라멜맛이 WIN!!!!!! 단짠단짠맛이 극강으로 입안에 쫘-악, 위에뿌려주신 토핑이 아작아작 씹혀식감까지 미쳤어요..😭 오분도 안되서 싸-악 클리어😎 비싸도 맛있으면 또먹는데 역시차곡은 가심비맛집 사랑입니당🤍🤎🤍🤎🤍🤎 신메뉴 초코스콘도 안에 찐초코커버춰가 들어있어서 고급진맛!!!👍🏻👍🏻', 119, 22, 'GOOD', SYSTIMESTAMP);
