INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '🍋신메뉴로 레몬레밍턴이 나왔다고해서 먹어보니 역시나 새콤상콤한게 너무 맛있고 코코넛이랑도 잘 어울려서 입안에서 그냥 녹아요ㅎㅎㅎㅎ 얼그레이를 선호하지 않지만 여기껀 거부감없이 한접시 뚝딱비운답니다!🤎🍰🍵', 62, 15, 'GOOD', SYSTIMESTAMP);
