INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '회사에 답례품으로 쿠키를 나눠드리고자 단체 주문했는데, 늦은 시간임에도 사장님께서 친절하고 빠르게 상담해 주셔서 좋았어요. 거기에 포장도 꼼꼼하게, 부서진 것 하나 없이 제시간에 잘 배송되어서 완전 만족했습니다! 사실 맛보고 구매한 것이 아닌지라 맛있을지 걱정했는데, 우려는 잠시.. 다들 맛있다고 하셔서 좋았습니다. 궁금해서 저도 하나 먹어봤는데 바삭하고 맛있었습니다.😄 덕분에 최고의 선물이 되었어요. 고맙습니다. 서비스로 주신 꼬끄도 잘 먹겠습니다!', 21, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '커피 잘 마셨습니다 기대 이상으로 넘 맛있었어요:) 매장에 베이커리 냄새 진짜 대박이에요🤩 다음에 꼭 베이커리 먹으러 가려구요!', 28, 10, 'GOOD', SYSTIMESTAMP);
