INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '갑자기 땡겨서 들어가서 포장해왔는데 진짜 완전 맛있었어요!! 포장도 깔끔하게 잘해주시고 사장님도 친절하셔서 기분좋게 집와서 디저트 먹었어요 ㅎㅎ', 37, 0, 'GOOD', SYSTIMESTAMP);
