INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '수제초콜렛과 수제디저트가 가득한 차곡파티세리 인스타로 아는사람들은 다아는 디저트맛집이죠ㅋㅋ 퀄리티 대비 가격이 정말 좋네요 앞으로 서교동 오면 이곳만 갈것같음! 당근케이크에 아메리카노 추천합니다 봉봉초콜렛도 대존맛', 52, 15, 'GOOD', SYSTIMESTAMP);
