INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '수제케익이랑 수제디저트가 유명하다고 해서 가봤어요! 수제케익이라 그런지 티라미수가 엄청 부드럽고 텁텁하지 않아서 넘 맛있어요!! 다음엔 빼빼로 구경할 겸 당근케익 먹으러 들릴게요~~', 38, 8, 'GOOD', SYSTIMESTAMP);
