INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '친구생일날 얼그레이시폰으로 주문했는데, 얼그레이 향이 진하고 시트도 말랑말랑 부드러웠어요ㅎㅎ 너무맛있게 잘 먹었네요ㅎ 재구매의사👌', 24, 1, 'GOOD', SYSTIMESTAMP);
