INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차곡파티세리 연남점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '단호박스콘+빼빼로+아망드 한 세트로 3가지 디저트를 먹을 수 있는 간식상자 사봤습니다 :) 단호박스콘은 찐~~한 단호박이 너무 좋아요 😍 아망드도 저번에 먹어보니 오독오독 달콤달콤 아몬드랑 초콜렛 조합이 좋아요!! 사브레도 들어있는데 이건 집에가서 아껴 먹을래요🤭 사장님이 친절해서 기분이 좋아지네요 ㅎㅎ', 89, 15, 'GOOD', SYSTIMESTAMP);
