INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스테레오포닉사운드'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '지나가면서 늘 궁금했는데 저녁엔 생각보다 문을 일찍 닫아서 낮에 가보게 되었어요. 커피 진짜 맛있었고 매장은 온통 감각적입니다ㅎㅎ (디자인 회사에서 만드신것 같아요) 제 취향에 딱맞아서 좋았네요 :)', 0, 9, 'GOOD', SYSTIMESTAMP);
