INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스테레오포닉사운드'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '저녁 타임 펍 오픈한다고 sns에서 확인해서 다녀왔습니다. 생맥주도 맛있고 라면팝콘도 맛있고 디제잉 하시는 분들 노래도 너무너무 좋았어요ㅎㅎㅎ자주 애용할게요!!', 17, 2, 'GOOD', SYSTIMESTAMP);
