INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이니드케이크 홍대점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '목적성 확실한 방문. 즐겁고 알차게 즐기고 갔습니다. 젤리소다가 진짜 눈으로 즐기기에도 좋고 먹기에도 좋았습니다. 복숭아? 컨셉 확실 최고의 맛.', 48, 2, 'GOOD', SYSTIMESTAMP);
