INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '브런치카페를 찾다가 분위기가 예뻐서 방문했습니다! 주말 1시쯤 방문하니 대기가 5분 정도 있었고, 1층 카페는 자리가 널널했어요! 브런치 플래터와 프렌치 토스트를 주문했는데 둘 다 맛있었습니다😋', 69, 11, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '입구부터 이국적인 감성이 물씬 풍기는데, 내부는 조명이 은은하고 테이블 간 간격도 넓어서 여유롭게 식사할 수 있었어요. 벽면은 미니멀하면서도 아트워크로 포인트를 줘서, 마치 작은 갤러리에 온 듯한 느낌을 주더라구요. 데이트 장소로도, 친구들과의 모임 장소로도 딱일 것 같아요. 저는 파스타와 와인을 중심으로 주문했어요. 봉골레 파스타: 조개가 신선하고 국물 맛이 깔끔해서 술술 들어갔습니다. 트러플 크림 리조또: 풍미가 진하고, 크리미하면서도 질리지 않아 만족스러웠어요. 음식과 잘 어울리고 가격대도 합리적이어서 가볍게 즐기기 좋았습니다.', 50, 0, 'GOOD', SYSTIMESTAMP);
