INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '리조또가 너무 맛잇데서 남자칭구랑 왓어용 대박 진짜너무맛있고 커피한잔이랑 먹으면 유럽 감성 지대루~ 이탈리아 온줄 알앗어옹 가게분위기가 너무 이뽀요ㅠㅠㅠ', 3, 9, 'GOOD', SYSTIMESTAMP);
