INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '분위기 너무 좋고 음식도 깔끔해서 만족했어요! 카페가 2층 건물인데, 층고도 높고 공간이 꽤 넓어요. 햇살 잘 들어오는 창가 자리 앉았는데 너무 여유롭고 좋았어요. 인테리어도 세련되고 조용해서 데이트나 혼카페로도 추천해요 홍대에서 조용하고 예쁜 브런치 카페 찾으신다면 알 누오보 추천드려요! 재방문 의사 100%입니다 💯.', 67, 18, 'GOOD', SYSTIMESTAMP);
