INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '뇨끼 맛집이에요~! 숟가락으로 후욱 부셔지고 넘넘 부드럽고 쫜득해요.. 소스도 퍼먹으니 넘 따뜩하고 좋네요. 라구파스타도 토마토향이 물씬나고 면이 아주아주 두꺼워서 포만감 제대로예요!', 19, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '1층엔 카페고 2층엔 브런치를 먹을 수 있어요! 공간이 넓고 분위기도 좋아서 특별한 날에 방문해도 너무 좋을것 같아요🥳 음식도 간이 너무 세지 않아서 정말 잘 먹었어요 다음에는 1층 카페 들러보려구요🤭🩷', 57, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '샐러드부터 파스타 스테이크 디저트까지 맛있게 먹었습니다 커피도 맛있고요 넓고 쾌적한 공간과 친절한 직원들까지 만족스러운 식사였습니다', 33, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '너무 맛있고...분위기가 너무 좋네요,,,😚 힐링하고 싶은 곳...데이트하기 좋은곳🫶🫶 사장님도 너무 친절하시고,,sweet,,,💚💚', 14, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '알리오올리오랑 토스트 주문했는데, 둘 다 정말 만족스러웠어요! 알리오올리오는 마늘 향이 풍부하고 면도 적당히 알덴테로 잘 삶아져 있어서 입에 착 붙는 맛이었어요. 매콤한 맛도 적당히 있어서 느끼하지 않고 좋았습니다. 토스트는 겉은 바삭하고 속은 부드러워서 파스타랑 찰떡궁합이었어요. 버터 향도 은은해서 한 조각도 남김없이 먹었네요', 10, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '1층에서 작업 하기 좋은 공간 :) 아아 아라를 홀짝 홀짝~~ 여유있게 늦은 시간까지 운영해서 노트북으로 일하기 좋고 대화하기 좋은 홍대 느좋카 ㅎㅎ 귯굿', 105, 24, 'GOOD', SYSTIMESTAMP);
