INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '브런치 먹으러 갔었어요! 저는 뇨끼가 제일 맛있었고, 다른 메뉴들 모두 다 맛있었어요. 아메리카노가 맛있었고, 브런치 메뉴 주문하면 메뉴 하나당 음료 하나 3000원 할인됩니다! 공간도 너무 이쁘고 데이트로 와도 좋을 것 같아요~', 51, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '홍대 브런치,디너 맛집 찾다가 방문 했어요 🗣️ 공간도 넓고, 테이블 간격도 꽤 있는 편이라 편안하게 식사 할 수 있었던 것 같아요 ㅎㅎ 가게 내부도 되게 깔끔하고 오픈형 키친이라 다 들여다 볼 수 있어서 슬쩍 보니 내부도 엄청 청결한 것 같더라구요! 완전 오픈형 주방인 이유가 있는 곳 ,, 🪽 서버님도 친절하게 이것저것 설명 해주시고, 가져다 주시는 음식들도 깔끔하고 좋았어용 제가 주문한 라구 파스타는 면 식감이 되게 특이해서 신선했던 ㅎㅎ 다른 맛있어보이는 파스타들도 많아서 조만간 친구들이랑 도장깨기 하러 또 방문할 것 같아요 ㅎㅎ🍷', 22, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '1층은 카페, 2층은 식당이에요. 2층에서 샌드위치 먹었는데 맛있었어요. 벽면이 유리라서 답답하지 않고 자리도 좁지 않아 편안하게 점심을 해결했어요! 다른 메뉴로 재방문 하고 싶은 곳입니다.', 22, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '브런치로 딱 좋은 거 같아요 직원분들도 너무 친절하셔서 다음에 다시 오고 싶네요 특히 에그네베딕트가 고소하고 아주 맛있습니다. 재방문 의사 있습니다. 뇨끼도 참 맛있어요', 35, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '네이버에서 홍대근처 브런치집 찾아보다가 아침부터 연 데가 별로 없어서 방문했는데, 알고보니까 유명한 맛집이더라구요! 공간도 엄청 넓고 음식도 너무 맛있어서 같이 온 동료들도 다 만족하고 갑니다. 다음에 근처 올 일 있으면 또 올 거 같아요~', 87, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '회사 동료분들과 모임이 있어서 방문하게 되었는데 단체테이블을 포함해 자리가 많아서 모임이나 데이트 장소로 너무 좋은것 같습니다, 음식들도 5가지 정도 먹었는데 모두 맛있고 조화롭게 잘 먹었습니다! 재방문의사 가득이에요><', 8, 0, 'GOOD', SYSTIMESTAMP);
