INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '여러가지 다양한 메뉴를 즐길 수 있고 무엇보다 분위기와 인테리어가 너무 예뻐서 모임 장소로 제격인거 같아요❤️ 2층에서 식사 즐기고 1층 내려가서 디저트 즐겼어요.! 여러군데 돌아다니지 않고 한 곳에서 해결할 수 있어서 좋았습니다!!', 103, 22, 'GOOD', SYSTIMESTAMP);
