INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '깔끔하고 넓고 쾌적한 공간! 노트북 들고 작업하기에도 수다 타임 갖기에도 딱 좋네요 2층에서 브런치 먹고 1층에서 디저트 먹는 것도 좋고, 커피도 맛나서 굿굿👍🏻👍🏻', 2, 9, 'GOOD', SYSTIMESTAMP);
