INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '인테리어 깔끔하고 탁 트인 느낌이라 좋았어요. 프리타타나 에그인헬, 후무스 같은 흔치 않느 메뉴들이 있어 좋았고 모두 맛있었어요. 뇨끼가 정말 좋았고, 기본 물도 레몬물로 주시는 것도 좋았습니다. 티켓투에서 연방하고 밥까지 해결하기 너무 좋아요!', 98, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '항상 시저샐러드+뚝배기 파스타+판체타 버섯 크림 리조또를 시켜 먹는데 넘 착한 가격의 신메뉴가 생겨서 다음날 또 방문해서 먹어봤어요. 우와~ 이 가격에 이 음식이 가능한 건가요? 정말 분위기 좋은 곳에서 넘 맛있는 파스타를 실컷 먹을 수 있어서 넘 행복해요. 감사합니다.😍🤤 알 누오보는 사랑입니다.🥰', 13, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), 'pm9:00 주문 마감 pm 9:30 영업 종료 인듯 케익이 너무 달지 않아 먹기 좋았음. 1층 카페 2층 브런치 식당 층별 구분 이용.', 55, 12, 'GOOD', SYSTIMESTAMP);
