INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '인테리어가 예쁘고 커피맛이 너무 좋아요! 1층은 카페 2층은 브런치카페인데, 1층카페에서는 테이크아웃하면 커피 1천원 할인해줘요!', 10, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '매장이 넓고 예뻐요!! 아침에 스프 빵 세트 있는거 보고 메뉴만 보고 왔는데 정말 이뻐서 깜짝 놀랐네요ㅎㅎ lp판도 있고 갬성이 너무 좋아요😊 그리고 정말 친절하셨어요!! 물 다 마시면 계속 오셔서 채워주셨습니다ㅎㅎ 일찍가서 저밖에 없었는데 계속 신경써주셨습니다ㅎㅎ 분위기도 너무 좋아서 다른거 안하고 노래만 들으면서 멍때리고 경치랑 디자인 구경하며 힐링했습니다ㅎㅎ 다음에 또 오고싶어요!! 다음에 브런치 스페셜 세트 시켜보고 싶네요😆 추천합니다!!👍', 49, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
