INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '오므라이스 먹고 얼마 안지나서...가볍게 주문. 뇨끼는 정말 맛있으므로 꼭 시켜야 하고...양 적은거 주문하려고 채끝등심으로..ㅎㅎ 고기 굽기 아주 잘되어서 입에서 부드럽게 씹히는 맛이 좋네요. 커피도 괜찮습니다.', 49, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
