INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '오늘 너무 더워서 무작정 들린 카페였는데 내부 시원하고 음료도 너무 맛있어서 기분이 좋아졌어요! 직원분도 친절하셔서 감사했습니다 ㅎㅎ', 62, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '건물이 전체적으로 깨끗하고, 통으로 써서 그런지 내부도 엄청 넓고 청결합니다. 1층 카페, 2층 브런치, 3층 방탈출 카페로 이뤄져 있어 데이트 코스 짜기에 최고👍🏻 브런치 카페 진짜 넓고, 고급스러워서 기념일이나 모임 가지기도 좋고, 사진 찍기에도 너무 좋아요! 파스타랑 리조또 너무 맛있었고, 양도 많아서 성인 남자 기준 부족함 없이 먹을 수 있습니다. 그리고 양배추 피클 진짜 맛있고 새콤해서 느끼함 없이 먹을 수 있어요. 방탈출 카페는 인테리어 진짜 이쁘고, 낙후되거나 노후된 장비 1도 없고, 쾌적합니다! 테마 몰입도도 최고! 방탈출 이용하면 주류 제외하고 음식이나 음료 할인이 된다고 하니 방탈출하고 밥 먹기 딱입니다! 홍대에 이런 넓고 쾌적한 공간이 있을 줄 생각도 못했네요. 재방문 무조건 각!', 19, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
