INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '홍대는 무조건 여기에요! 브런치먹으러 왔다가 분위기에 치여서 낮술했습니다! 와인 추천해주셨는데 진짜 취향저격했어요🩷🩷🩷 뇨끼가 맛있는 집이 잘 없는데 여기 풍미도 좋고 감자맛 낭낭하고 밀가루 향 없어서 진짜 맛있어요❤️ 분위기 좋은 곳 찾으시면 여깁니다 ✌🏻', 17, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '밥먹고 지나가다가 인테리어가 예뻐보여서 방문했어요. 라떼 - 라이즈 (고소) / 아메리카노 - 밸런스 (산미) 원두로 골랐어요. 커피 맛있었어요! 공간이 넓고 이야기하기 좋아요. 브런치 공간은 2층으로 나뉘어져있어요.', 34, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '알누오보 이쪽으로 처음 와보는데 건물 자체가 신식이라서 너무 깔끔하고 예쁘네요!! 일단 판체타 버섯크림 리조또가 정말 최고에요!! 크림이 깊은 맛이 느껴지고, 현미밥으로 리조또를 해서 특이하더라구요~ 또, 위에 견과류가 올라가서 고서함을 더 해줬어요!! 다른 메뉴인 아라비아따도 적당히 매콤하고 소스도 그냥 토마토소스가 아닌 느낌,,❤️ 직원 분들도 너무 친절하시고, 물잔이 비면 계속 따라주셨어요!! 너무 잘먹었습니다~ 다음에 또 방문하고 싶네용', 32, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '여기도 후기가 정말 끝장이라 기대 만땅 하고 방문했는데 기대가 크면 실망이 따른다라는 고정관념을 깨부실정도로 정말 맛있었던 브런치카페였어요 지하랑 3층은 방탈출카페고 1층은 일반 카페 2층은 브런치카페. 하루종일 안에서 데이트하며 시간보내기 좋은 장소예요!', 65, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '근처에 미팅이 있어서 잠시 저녁먹을 겸 미팅 준비할 겸 방문했어요. 이탈리안식 오믈렛 시켰는데 맛있더라고요! 브런치를 저녁시간까지 먹을 수 있어서 좋았고, 커피도 리뷰 작성하면 무료 이벤트하더라고요. 종업원 분들도 너무나 친절하셔서 혼자 방문했지만 마음 편하게 저녁 먹으며 일 볼 수 있어서 좋았어요.', 118, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'MEETING');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '홍대 분위기 좋은 브런치 카페 알 누오보💕 홍대 데이트코스로 너무 좋은게 3층에 방탈출카페가 있어 서 방탈출하고 분위기 좋은 식당에서 식사하기에 넘 좋은 곳 이에요✨ 뚝배기 파스타 팬네면이라 더 맛있고 국물이 매콤하니 정말 맛있어요👍🏻 비스코소스여서 더 특별한 맛이었던 로제 파스타도 완전 추천해여🫶🏻 * 이 글은 제품만을 제공받아 솔직하게 작성한 글입니다.', 85, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '엄마랑 데이트로 홍대 브런치카페 방문했는데 인테리어도 너무 예쁘고 깔끔 그 자체였어요! 재료도 신선하구 맛있더라구요! 직원분들도 엄청 친절하세여,,ㅎ 단체석들도 있어서 친구들이랑도 단체모임하기 너무 좋을 것 같아용 같은 건물에 방탈출도 있어서 홍대 데이트 코스로 완전 추천,,👍🏻', 38, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '특이하게 1층 카페 2층 식당입니다 ! 때마침 브런치 카페 찾고 있었는데, 숨겨진 맛집 느낌 뿜뿜이라 데이트 장소로 골랐어요. 휴무일에 홍대 갔는데도 웨이팅 없이 사람 많지 않아서 너무 좋았습니다. 직원분들 서비스도 너무 친절해요. 물 매번 리필해주십니다 :) 분위기도 아늑해서 데이트 장소로 완전 강추합니다👍 아라비아따는 매운 토마토파스타로 매운거 좋아하시면 추천 ! 뇨끼는 버섯튀김이랑 스프, 뇨끼 양이 넉넉해서 좋았어요. 뇨끼랑 버섯 좋아하시는 분들에게 무조건 추천 ! 특히 뇨끼 찐꾸덕꾸덕 그잡채...💛 판체타 버섯크림 리조또는 견과류랑 쌀알이 씹혀서 포만감이 높습니다. 고소해요 !! 덕분에 행복한 시간 보냈네요. 음식, 서비스, 매장 인테리어가 마음에 들어서 다음에 또 찾아올 듯 합니다 😄', 117, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '뇨끼랑 아라비아따 파스타 꼭 드세요!!!! 진짜 인생 뇨끼예요>< 너무너무 맛있어요! 여기는 홍대 갈 때마다 이제 무조건 먹으러 갑니다!', 12, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '브런치 카페 찾다가 우연히 들어왔는데 넘 맛있게 먹고 갑니다 🌝 가격도 합리적이고 브런치 세트 런치 타임에 시키면 아아도 주니깐 더 좋아요 👍🏻', 111, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '브런치 먹으러 왔다가 제가 먹으려고 했던 메뉴가 특정 시간에만 가능해서 우연치 않게 파스타 먹었어요! 맛도 좋구 가격도 좋아요!! 홍대에 시끄러운 곳 밖에 없는데 여긴 조용해서 넘 좋아요ㅠ', 34, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '브런치 맛집이라 해서 별생각없이 왔는데 2시반까지라 의도치 않은 식사타임을 가졌어요 ㅋㅋㅋㅋ 아니 근데 진짜 뇨끼 ㅁㅊ놈이네요 존맛….. 쫄깃한 스타일은 아니고 감자 식감? 근데 마지막에 약간의 쫀득함은 있는? 뇨끼 잘알은 아닌데 요끼 다시 먹으러 또 올 것 같아요🥺❣️', 90, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '2번째 방뮨입니다 ^^ 좀 더 특별한 곳을 원하신다면 이곳을 한번 와보세요 공간이 아주 놃고 특별합니다 음식은 독툭하고 풍뷰한맛이며 직원분의 친절합니다 덕분에 좋은시간 맞이하고 갑니다 ^%', 6, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '오픈시간에 가면 브런치만 주문 가능합니다 양이 좀 적어서 좀더 기다렸다가 런치 주문하시는걸 추천^^ 직원분들 친절하고 매장 예쁘고 깔끔해요 재방문의사 있습니다', 113, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '방탈출 카페 이용 후 알 누오보에서 식사 !! 1층은 카페 2층은 식사 이용 가능합니다 리조또 정말 맛있는데 가격은 2만원밖에안합니다 뚝배기 파스타도 되게 이색적이고 맛있었어요 데이트 코스로 추천드립니다', 18, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '친구 추천으로 왔는데 자리도 넓고 커피도 맛있어요 ! 홍대생인데 왜 이제 왔을까요 … 이 카페를 몰랐던 게 아쉬울 정도로 너무 좋네요 !! ☕️💗🌱', 35, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '뚝바기파스타 포르치니 크림뇨끼 프리타타 오믈렛 음식이 전체적으로 다 맛있고 특히 뇨끼 처음먹어보는데 정말 인상적이었습니다~ 토요일 11시경 부모님 모시고 식사했는데 대화하기도 좋고 인테리어가 마음에 들었네요. 식기나 테이블 의자 등 소품에 신경을 많이 쓴 것 같았어요. 특히 직원분들이 너무 친절시고 요청안해도 물, 물티슈, 테이블 정리 등 신경써주셔서 기분좋게 식사하고 갑니다~', 257, 70, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '대한민국 최고의 쇼콜라라떼 맛집🍫 초코라떼가 다 똑같지라고 생각했는데... 여기서 먹은 이후에는 다 제티처럼 느껴져요..😂 그만큼 대존맛', 31, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '홍대브런치맛집 알누오보! 같은 건물에 방탈출카페도 있어서 한 건물 안에서 놀거리, 밥, 카페 모두 해결할 수 있다는 점이 너무 좋아요 ㅎㅎ 매장도 쾌적하고 음식이 다 너무 맛있어서 좋았음! 개인적으로 크림 들어간 메뉴들이 젤 맛있었어요 👍👍', 21, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '저번에 먹은 아라비아따가 너무 맛있었어서 두 번째 방문했어요! 이번에 먹은 판체타 크림 리조또도 대박이네요 .. 매장 분위기도 좋고 맛도 넘 좋았어요 여기 커피도 맛있어요 !!!', 53, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '알 누오보 1층에서 음료 마시면서 일행을 기다렸다가 2층으로 올라가서 식사를 했는데요. 음식 하나하나 정말 맛있어요. 그 중에서도 시저샐러드+판체타 버섯크림리조또+뚝배기 파스타 이 조합 정말 환상적이에요. 매일매일 생각나는 맛!👍', 43, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '가족식사. 뇨끼 참 맛있어서 항상 시키게 되는 기본 메뉴. 부드러운 식감에 소스도 맛있죠. 후무스 샐러드 처음 시켜봤는데...이거 참 맛있네요. 다만 고수향외에 추가 향신료도 냄새가 있어서 익숙치 않으신분들은 주의 필요. 저는 매우 맛있게 먹었네요. 항상 만족스럽던 곳인데..오늘은 아들까지 같이와서 더더욱 즐거운 자리였습니다.', 9, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '모든 음식이 맛있었지만 특히 뇨끼가 참 맛났네요! 직원분이 메뉴 설명도 잘해주시고 친절하셨어요. 물도 바로바로 채워주시고요. 다시 가고 싶은 곳이예요.', 26, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '매장이 넓고 예뻐요,, 방탈출하고 브런치랑 카페까지 홍대 실내데이트로 딱이었던 알 누오보 다음 번에도 재방문 예정입니다 리조또가 진짜 제 스타일이었습니다', 74, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '정말 친절하시고 응대도 잘해주셔서 넘 짱이에요 방탈출 한 김에 건상한 식사하려고 왔는데 여기 오길 정말 잘한거같아요! 음식이 다 맛있고 특히 뇨끼 미쳤음 ㅜㅠ', 35, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '앤쵸비 파스타랑 뚝배기 파스타 먹었는데 둘 다 너무 맛있었어요!! 뚝배기 파스타 국물 끝까지 먹게되는 그런 맛입니다...후기 보니 뇨끼 맛있다는 얘기가 많아서 다음에는 뇨끼 먹으러 오려구요! 가게도 넓고 점원분들도 친절하셔서 좋았습니당~!', 64, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '벌써 몇번째 방문인지.. 알게 된 후 부터 친구 데리고 정말 자주 오고 있어요. 오늘은 간단하게 토스트에 스프! 분위기도 좋고 가격도 좋지만 맛도 정말 좋아요~ 👍', 4, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '지인들과 홍대에서 연말 모임 중 주변 라멘 집 찾다가 우연히 발견한 카페였는데 겉모습에서 깔끔하고 넓어보여 방문하게 되었습니다. 내부 분위기는 연말에 딱 맞는 트리와 포근한 조명으로 되어 있고 단체석 자리도 중앙에 마련되어 있어 연말 모임할때 강추 드리는 카페입니다. 디저트랑 커피도 지인 모두 만족하여 다음에 홍대에 약속이 생기면 재방문 의사가 있네요. ㅎㅎ', 30, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'MEETING');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '대화하기 좋고 탁 트인 뷰라 좋은데 가격도 생각보다 저렴하네요! (아메리카노 4500원) 직원분들도 친절하시고, 매장도 깔끔합니다. 위층에 있는 티켓투이스케이프 이용시 10% 할인쿠폰 제공되니 방탈출하시는 분들은 알누오보 이용 추천드려요~', 37, 5, 'GOOD', SYSTIMESTAMP);
