INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '두번째 방문 역시나 맛있어요. 궁금해서 먹어본 바질 크림파스타 새우도 많고 향도 좋고 맛은 누구나 좋아하는 녹진크림 ! 맛있게 잘 먹었습니다:)', 68, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '2층은 시끌벅쩍 해보이는데 1층 카페는 여유롭고 좋아요!! 혼자 노트북 들고와서 작업할 수 있는 공간도 있구요 홍대에 드문 사이즈의 대형카페인거 같아요 스몰라떼는 우유 양이 부담스럽지않고 딱 좋아요', 74, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '조용해서 집중하기 좋은 대형 카페 디저트도 음료도 다 맛있어서 완전 만족🍀 1층 카페, 2층 브런치로 공간이 분리되어 있어 조용한 카페를 원하시는 분들도 만족 가능🍀', 4, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '네이버 검색으로 갔는데 정말 보석같은 곳을 발견한 느낌이에요!!!! 맛있는 건 당연하고, 널찍한 테이블에 편안한 분위기, 직원분들의 서빙 모두 홍대에서 찾기 어려울 정도의 퀄리티에요!!!!!! 너무 좋아서 1주일에 2번이나 갔어요 😍 최고입니다 👍👍👍', 317, 71, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '티켓투이스케이프 방탈출테마파크 예약시간 보다 일찍 도착해서 1층 카페에서 먼저 아몬드아인슈페너를 마셨는데 진짜 넘 맛있었어요. 위에 있는 크림을 먼저 따로 먹어도 맛있더라고요. 방탈출 예약시간 15분 전엔 3층으로 올라갔는데 다른 세상에 온 것 같이 넘 이뻐서 사진도 많이 찍었네요. 방탈출게임 신나게 하고 티켓 가지고 2층 레스토랑 갔는데 10% 할인도 해줘서 넘 좋더라고요. 음식도 하나하나 다 맛있어요. 한 건물 안에 제가 좋아하는 모든 것이 다 있어서 좋아요. 친구들과 카페에서 모여서-> 방탈출 게임하고-> 티켓가지고 10%할인 된 가격으로 식사하는 코스 추천합니다!', 8, 1, 'GOOD', SYSTIMESTAMP);
