INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '저번주에 브런치카페에서 먹어보고 맛있어서 카페도 이용해보고싶어서 왔는데 아몬드 아인슈페너 너무 맛있어요😍😍😍😍😍 크리스마스 분위기 물씬 나네요 여전히 친절하시고 시설도 너무 깔끔합니다 여기 왕추천이요!!!', 32, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '땡땡샵 오면 꼭 방문하는곳. 1층은 카페, 2층은 레스토랑입니다. 저번에 뇨끼가 너무 맛있어서 뇨끼는 이번에도 주문~ 저는 베이컨 뭐시기 파스타! 베이컨이 두툼하니 아주 좋네요. 맛있게 잘 먹고 나왔습니다. 매장 내부도 산뜻하고 화장실도 청결도가 좋아서 내외적으로 아주 만족스럽네요.', 8, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '홍대맛집 답게 분위기도 고급스럽고 인테리어도 너무 마음에 듭니다!:) 대표메뉴인 판체타버섯크림리조또는 다양한 곡물과 견과류가 들어가서 고소하고 담백했고 식감이 좋았어요^^ 토마토를 베이스로 한 뚝배기 파스타에 해산물 가득 들어있어서 정말 맛있게 먹었어요:) 지중해 스타일이 가미된 이탈리안 브런치 메뉴가 돋보였고 가격도 합리적이네요^^ 브런치를 먹은 후 1층에는 커피숍이 있어서 1층에서 커피랑 단호박바스트케익도 먹었는데 멀리 가지 않아도분위기 좋은 카페에서 음료와 디저트 먹기에도 좋은 곳 같아요:) 오래 머물며 좋은 시간 보냈어요^^ 너무 만족스러워서 다음에 또 올게요!', 62, 13, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '카페 음료도 맛있다고 하지만 브런치 메뉴로도 괜찮은 곳이에요!! 개인적으로 뚝배기 파스타 먹었는데 홍대 파스타 맛집을 발견한 느낌이에요ㅎㅎ 개인적으로 직원분들 서비스가 엄청 좋으셔서 대접받는 기분이 들었고 매장도 넓어 좋았어요!! 홍대 가볼만한 곳 찾으신다면 여기로 오세요!!', 14, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '홍대 분위기 좋은 파스타, 뇨끼 맛집! 비건 메뉴도 있고 브런치 메뉴들도 하나 같이 넘 맛나요 ㅎㅎ 우드 인테리어 중심의 넓고 깔끔한 공간에서 편안하게 즐길 수 있어서 너무너무 좋은 홍대 데이트 맛집이에요❤ 인테리어가 넘 잘 되어있어서 구경하는 재미도 있구 분위기도 짱짱 좋아요😘😘 포르치니 크림 수제뇨끼는 버섯 풍미 넘 좋고 뚝배기 파스타의 매콤한 토마토 베이스랑도 궁합이 좋아요! 후무스 오븐야채 샐러드도 후무스 부드러움에 구운 야채의 달달하고 좋은 식감이 잘 어우려져 피타브레드랑 조합 짱짱!!! 완전 강추하는 브런치 메뉴에요😘❤ 와인 주류 메뉴도 많아서 간단하게 저녁 먹으며 와인 마시고 싶을 때 데이트하고 싶을 때 강추😍', 44, 3, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '홍대 역대급 인생 맛집....!!! 분위기도 좋고, 리조또, 샥슈카 완전 맛있습니다. 내부 인테리어도 예뻐요💛❤️💛❤️ 음식 넘 맛있어서 이탈리아에 와있는 느낌🍝 가격도 가성비 좋고 음식도 맛있고 분위기까지 정말 좋네요! 판테차 버섯크림 리조또 부드럽고 곡물, 견과류가 들어가있어서 식감도 좋아서 추천해요~ 샥슈카는 매콤한 토마토소스에 야채와 계란으로 된 요리라 빵과도 잘 어울려요.', 38, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '지나가다가 너무 예뻐서 들어왔는데 커피도 너무 맛있고 공간도 분위기도 멋져서 분좋카 좋아하시는 분들이라면 꼭 추천드립니다♡♡♡', 110, 24, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '친구 생일겸 송년회로 다녀왔어요!!! 기대없이 갔다가 완전 반하고 왔어요 층고가 높아 답답하지 않고 매장이 밝고 유니크해요 특히 직원들의 과한 친절과 응대에 기분이 절로 좋아지더라구요👍👍음식이 맛있어도 불친절하면 다시는 안가죠!!! 그리고 전 인생뇨끼를 만났습니다👍🫶🫶🫶 지금까지 먹어본 뇨끼중에 탑이네요 두껍고 쫄깃쫄깃 너무 맛있어요! 다른 음식들도 너무 맛있더라구요! 나만 알고 싶은 식당이지만 홍대 오시는분들 두번 세번 오세요^^(참고로 관계자 아닙니다 ㅋㅋㅋ) 전 돌아오는 주말에 또 가보려고 합니다😀 1층 카페를 이용 못해봐서 겸사겸사요!! 덕분에 친구들과 좋은 모임했네요^^ 다시한번 직원분들 친절에 감동했습니다🙏', 122, 25, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '홍대에 이렇게 넓고 깨끗한 카페가 있는 줄 몰랐어요! 제 입맛엔 커피가 연하긴 한데 고소하고 부담없는 맛이에요! 다음에 노트북 가지고도 오려구요 콘센트도 다 마련 돼 있어요!', 38, 9, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PLUG');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '추웠던 날 홍대에서 카페 찾다가 가까운 곳에 그냥 들어갔는데요. 완전 분위기 좋고 대박이었습니다. 2층은 식사, 1층은 카페 공간이었습니다. 직원분 친절하시고, 매장 분위기가 너무 좋았어요. 깔끔했구요. 창가 노트북석이 있어서 코드 사용까지 가능했습니다. 나중에 또 방문할까 하고 있어요!', 89, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '판체다 버섯크림 리조또 대존맛이에요!!! 고소한 견과류와 리조또에 톡톡 터지는 곡물 식감이 일품인데 여기에 베이컨과 함께 먹으면 맛이 없을 수가 없어요ㅠ', 45, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '요기 새로 오픈한 곳이라고해서 바로 방문했는데 홍대 브런치 카페로 바로 인증 도장 5개 드리구 갑네당 일단 포르치니 버섯 크림뇨끼는 크림소스가 고소하니 미쳤는데 무엇보다 뇨끼가 완전 쫀득하니 식감이 미쳤어요.. 심지어 같이 주문한 새우앤쵸비 파스타는 감칠맛이 대박이였고 새우도 토실토실해서 저 바닥까지 싹싹 긁어먹엇자나여.. 대박스', 28, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '뇨끼와 뚝배기파스타가 일품이에요🤍 양이 많아서 2명이서 2개 시켰는데도 배부르네용 분위기도 좋고 넓직해서 데이트나 모임장소로 딱! 나만 알고싶은 분위기갑 맛집이에용', 100, 22, 'GOOD', SYSTIMESTAMP);
