INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '2층에서 브런치 먹고 1층 내려와서 디저트에 커피 마시고 갑니다! 오픈한지 얼마 안되어서 정말 깨끗하고 인테리어가 너무 예뻐요~~ 음식 진짜 너무너무 맛있었습니다! 1,2층 직원분들 다 친절하셔서 감동!! 음악도 고급스럽고 정말 오랫동안 잘 먹고 잘 놀다 가요~~ 또 방문 할게요!!', 25, 4, 'GOOD', SYSTIMESTAMP);
