INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '카페가 크고 깔끔해요! 혼자 공부하거나 작업하기도 너무 좋고 단체석도 있어서 모임 가지기도 좋습니다 ◡̈ 저는 자주 올 것 같아요!', 43, 6, 'GOOD', SYSTIMESTAMP);
