INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '가게가 크고 매장 친구가 높아서 데이트하기 좋은 거 같아요! 일층은 카페고 한적해서 작업공간으로 추천 드립니다! 근처 사시는 분들 부럽네요', 30, 0, 'GOOD', SYSTIMESTAMP);
