INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '인테리어가 진짜진짜 멋있어서 음식맛이 별루여도 그러려니 해야지 싶었는데 음식도 개존맛이에요... 지금까지 먹은 뇨끼랑 뚝배기파스타 중 여기가 최고...', 21, 0, 'GOOD', SYSTIMESTAMP);
