INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '홍대에서 이런 분위기의 대형카페에서 합리적인 가격대로 식사를 할 수 있어서 너무 좋았던 곳❤️ 숨겨진 기념일&데이트 장소입니다!! 일단 1층카페, 2층 레스토랑으로 건물 한채로 운영이 되고 있어요. 건물도 너무 예쁘고, 약간 갤러리 온느낌? 고급스러웠어요. 인테리어에 비해 가격은 비싸지 않고, 일반 레스토랑 가격 정도 받더라고요. 음식도 맛있고 분위기도 좋고 무엇보다 직원분들 서비스가 좋았습니다👍 식사 중, 후로 필요한게 있는지, 음식맛, 알러지 등등 세심하게 챙겨주셔서 기억에 남는곳!! 곧 재방문 예정입니당', 28, 3, 'GOOD', SYSTIMESTAMP);
