INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '여기 음료랑 디저트도 맛있고 이벤트도 많아서 좋아요ㅎㅎ 방탈출하면 10% 할인에 리뷰 작성하면 크로플 주는 이벤트도 하니까 많이 방문해보세요 :)', 2, 3, 'GOOD', SYSTIMESTAMP);
