INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '근처에 놀러왔다가 동생이랑 친척동생이랑 점심 먹으러 왔는데 너무 맛있었어요! 뇨끼 진짜 쫀득쫀득하고 재료가 신선해서 다른 메뉴들도 다 맛있네요ㅎㅎ 부라타치즈샐러드도 꼭 먹어보세요~!~!', 19, 1, 'GOOD', SYSTIMESTAMP);
