INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '진짜 맛있어요! 방탈출 하구 내려와서 밥먹구 내려가서 커피마시구 다할수있어욬ㅋㅋㅋ 건물 짱크고 깨끗하고! 다피료없고 진짜 음식이 넘맛 ㅜㅜ 완전 반했어요 담에 방탈출할때 또 올듯!! 굳굳', 6, 3, 'GOOD', SYSTIMESTAMP);
