INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '너무 추워서 지나가다 우연히 마주친 곳에서 너무 만족!! 앤쵸비파스타…감칠맛 아직도 혀에 맴도네요👍 인테리어도 멋지고 곳곳에 크리스마스 무드가 툭툭 1층 카페에 트리는 너무 예뻤어요♥️ 직원분들은 또 어찌나 친절하신지:) ㅣ 담에또 와서 밥두 먹고 작업도 하고 싶은곳 등록!', 63, 18, 'GOOD', SYSTIMESTAMP);
