INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '후기 잘 안남기는데 너무 만족스러워서 후기남겨요 ㅎㅎ 분위기 너무 좋고 뇨끼 정말정말 맛있고 새로 생긴 치즈플래터도 와인이랑 잘 어울렸습니다. 콜키지 2만원도 너무 좋았구요. 다음에 또 방문할게요! ㅎㅎ', 21, 5, 'GOOD', SYSTIMESTAMP);
