INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '몇번 왔는데 품격있고 대화하기 넘 좋아여 ^^*~ 맛은 당연하구요 ~ 분위기가 세련되고 다양한 메뉴와 깔끔한 내부가 인상적이네요', 46, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '예쁜 카페 입니다 이른점심으로 찾아갔어요 오픈런성공인듯합니다 마음껏 돌아다니며 사진찍구 음식나오기시작 수제뇨끼너무맛있어요 뇨끼두께 엄청두꺼워요 그래두 부드러움은 이루 말할수없어요 리조또는 또 어떠냐면요 밥알일까요?입안에서 톡톡터져요 우리끼리 보리다..밥을튀긴걸까? 머리맞대구 생각해봐두 알수없음 물어보기루....듣고보니 딱!!그거였어요 안알랴줌(직접 드셔보셔야해요) 커피맛은 묵직하면서 부드럽게 목넘김이 있는.... 커피는필수예요 트리도있어요 화려하지않으면서 풍성하지않아두 예쁩니다 오늘두 카페투어 성공입니다', 61, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '맛, 인테리어, 분위기 모든 게 완벽했던 곳. 오랜만에 연남동에 약속 모임이 있어 왔다가 새로 오픈 했 다기에 방문 한 곳! 외관부터가 크고 깔끔해서 바로 들어왔습니다 인원이 꽤나 많아서 여러 가지 시켜봤는데 하나하나 퀄리티가 상당했어요 특히나 ‘비스큐 리조토’라는 메뉴는 한입 먹고 깜짝 놀랐 네요! 다른 메뉴들도 너무나도 만족했습니다. 아직 오픈한지 얼마 안 된 매장이라 주말 저녁에 방문한 데도 한산했습니다. 직원들도 굉장히 친절하셔서 만족 시 러운 식사가 되었네요. 재방문 의사 100%입니다 :)', 83, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '친절한 직원, 예쁜 인테리어, 맛있는 커피, 디저트, 식사. 그러나 불합리한 주차 정책. 2층 식사시 2시간 3000원+추가요금 x / 1층 카페 이용시 2시간 3000원+추가 30분 당 3000원으로 듣고 2층 식사 후 1층 카페 이용(음료2잔 디저트 3개). 그러나 주차요금 계산 시 식당 이용 후 카페를 이용하였으므로 카페 정책에 따라 추가 주차요금 18000원을 내야한다고 함. 카페이용을 오래했으니 추가요금을 내는 것까진 납득가능하나, 그렇다면 카페 이용은 별 건으로 계산하는 게 맞지 않은지? 아무튼 2층 1층 같은 사업장으로 봐서 무조건 18000원을 내라고 함.  같은 사업장이라면 2시간 이후 요금은 식당 정책에 따라 안 받는 게 맞는 것 같은데. 결국 돈 내고 왔지만 제대로 고지하길 바람.', 25, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PARKING');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '인생후무스샐러드입니다... 구운야채도 기절하게 맛있고 시즈닝도 진짜 좋아요. 뇨끼는 버섯향이 진짜 진하고 고급스러운 맛입니다. 펜네도 매콤하니 궁합이 좋아요, 특히 해산물 퀄이... 인테리어도 넓고 화사하고 정말 친절하세요!! 자주 올래요ㅠㅠ', 26, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '직원분 너무 친절하셔서 입장부터 기분이 좋았어욤 요리하시는 주방이 탁트여있어서 잘 보이고 청결함이 느껴져서 안심하고 방문할수 있을것 같아용', 71, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '음식이 많고 맛있어요~ 뇨끼랑 뚝배기파스타랑 먹으니까 안느끼하고 깔쌈하게 맛있으니 이렇게 먹는것도 추천합니다! 홍대에서 분위기있고 먹기 편하고 넓은곳이 있으니 최고네요~ 사진도 잘나와서 더 좋습니다 강추', 79, 18, 'GOOD', SYSTIMESTAMP);
