INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '인테리어 너무 예쁘고 서비스 퀄리티도 정말 좋았습니다! 분위기 좋고 음식도 맛있어서 가족모임, 데이트장소, 소개팅장소로 진짜 좋을 것 같아여🫶', 28, 7, 'GOOD', SYSTIMESTAMP);
