INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '오랜만에 홍대에 방문했다가 너무 예쁜 카페를 알게되서 정말 좋아요 맛있는 바스크 케이크랑 버터바도팔고 음료도 맛있습니다 분위기 정말 좋아요!', 49, 8, 'GOOD', SYSTIMESTAMP);
