INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '재방문 의사 500%입니다. 건물도 아름답고 내부 인테리어도 예쁘고 무엇보다 음식이 정성 가득하고 맛있습니다 :) 직원분들도 친절해서 머무르는 동안 좋은 시간 보내고 가요!', 302, 100, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '후무스 오븐야채샐러드와 비스큐 파스타 시켰습니다. 샐러드는 한끼 식사 대용으로 먹기에도 충분했고 후무스와 구운야채가 조화로워 맛있었습니다. 파스타는 비스큐 소스의 감칠맛이 너무 좋았고 간도 적절해서 맛있게 먹었습니다. 대형 카페라 브런치 장소도 넓어 대화하기 좋고 직원도 친절해 기분이 좋았습니다. 추천합니다.', 81, 15, 'GOOD', SYSTIMESTAMP);
