INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '티켓투이스케이프 갔다 방문했는데 디저트 커피 모두 맛있고 방탈출 이용시 주차도 가능한게 너무 좋아요. 다음엔 브런치 먹으러 방문할게요 : )', 67, 11, 'GOOD', SYSTIMESTAMP);
