INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '홍대 브런치 카페 알누오보 😍 1층은 카페 2층은 이탈리안 레스토랑.. 식사하고 음료까지 마실 수 있어서 좋아요! 분위기도 정말 좋고 호텔 음식보다 더 맛있게 먹었어요 👍', 30, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '넓고 편한데다 인테리어도 멋져요. 창가자리에는 콘센트가 모두 매립되어있어서 편해요. 홍대 바로 앞에 있고 뷰가 좋아서 집중하기도 좋네요!', 15, 8, 'GOOD', SYSTIMESTAMP);
