INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '일주일에 한번씩 지금 갔는데 질리지않고 맛있어요♡:)강추 테이블넓어서 좋고 시그니처 메뉴 궁금해서 시그니처 위주로주문했는데 왜인지알것같아요:) 뚝배기파스타 약간 얼큰하면서 시원한맛이에요 양은사실 많은건 아니지만 맛이 진짜맛있어요', 88, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '급하게 찾아서 들어온 곳이었는데 분위기도 좋고 넓고 쾌적하고 직원분들도 너무 친절하셔서 좋았습니다 ! 그리구 무엇보다 음식이 정말 맛있었어요 또 오고싶은 곳입니다 강추예요!!💕', 56, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '음식이 너무 깔끔하게 나오고 맛있어요! 인테리어가 이뻐서 찾게 되었는데 데이트코스로 완전 만족했고 남자친구랑 감탄했어요 음식도 맛있었는데 후식도 만족해서 다음에 또 오려고 합니다. 나중에 커피 마시러 올때도 좋을 것 같아요!👍🏼', 23, 5, 'GOOD', SYSTIMESTAMP);
