INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '분위기도 좋고 자리 간격도 넓고, 천장도 높아서 쾌적해요! 커피와 디저트도 모두 맛있어요 화장실도 깨끗해요~ 좋아서 멀리서 또 왔어용 다음에도 또 올게요!', 15, 10, 'GOOD', SYSTIMESTAMP);
