INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '학생 시절 바로 옆에 위치한 건물에 알라또레라는 레스토랑을 알게되었습니다. 그 이후로 기념일을 포함해 종종 방문하면서 애착을 쌓아왔는데 정작 졸업하고 바쁘게 보내던 사이 없어지면서 아쉬움이 컸습니다. 알누오보로 돌아오기 까지의 2-3년간 와이프와 알라또레에 대한 그리움을 얼마나 이야기 했는지 모릅니다. 어찌나 자주 검색했봤었는지, 알누오보로 돌아온다는 걸 채용사이트 게시물 보고 미리 알 정도였어요. 음식은 물론이고 모든게 여전히 좋았습니다. 계속 소중한 곳으로 남아있기를 바랄 뿐이네요!', 12, 2, 'GOOD', SYSTIMESTAMP);
