INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '방탈출하고 밥먹고 이제 커피마시러 왔오요! 카페 분위기 너무 좋고 커피도 맛있어요!! 찐 커피집! 글구 디저트도 있어서 딱좋아요!! ! 너무맛있어요!! 담에도 방탈출이랑 묶어서 오면 조을듯 해요! 마싯댜아아아', 271, 37, 'GOOD', SYSTIMESTAMP);
