INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '일하는 직장근처에 새로생겨서 가봤는데 넓고 새건물이라서 쾌적하고 음식도 너무맛있어요 커피도랑 케익도궁금해서 다먹어봤는데 다좋았어요 :)♡종종 점심에 가볼려고요', 74, 18, 'GOOD', SYSTIMESTAMP);
