INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '알 누오보'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '최근 홍대에 오픈한 카페 우연히 가보게 되어 자주 애용중 👍 1층은 커피랑 디저트 중심 2층은 파스타 샐러드 같은 브런치카페 분위기가 정말좋고 공간도넓고 직원분들 다 친절하구 갠적으로 제일 좋았던 부분은 주차힘든 홍대에서 주차장이 있음 :) 데이트로 파스타에 와인한잔하러 올 예정 !!!', 14, 3, 'GOOD', SYSTIMESTAMP);
