INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '뮤즈 시노님'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '세븐틴 민규 생일카페로 방문했었어요. 매장 컨셉이 좋았습니다. 직원분들도 컨셉에 맞게 커스튬하고 계셔서 더 흥이 났어요. 매실 에이드 맛있습니다!', 76, 11, NULL, SYSTIMESTAMP);
