INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '뮤즈 시노님'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '카페 직원분도 너무 친절하시구 구석구석 너무 귀여워서 앉아서 먹고 가고 싶었는데 자리가 없어서ㅜㅋㅋㅋ 너무 아쉬웠어요 ㅠ 인기퍽팔', 19, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '뮤즈 시노님'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '갈때마다 너무 친절하신 뮤즈시노님 카페! 아기를 위해 따로 우유를 주실정도로 따듯한 곳이에요 이전에 배너 영광생카때도 너무 좋았는데 배너 혜성 생카일때도 아기자기한 공간이라 감상하기도 좋았어요 인생사진까지 찍을 수 있는 뮤즈시노님 카페 좋아요😄 https://naranara88.tistory.com/m/2031', 59, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '뮤즈 시노님'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '블루베리 소다는 처음 먹어보는데 굉장히 맛있었고 위에 올라간 레몬 샤베트도 맛있었어요! 사장님도 친절하셔서 다음에 또 갈거예요💜', 19, 8, 'GOOD', SYSTIMESTAMP);
