INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '뮤즈 시노님'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '역이랑도 가깝고 매장이 아기자기 귀여워서 사진찍기가 넘 죠아요ㅎㅎ 제가 입맛이 좀 까다로운 편인데 여긴 음료랑 베이커리도 직접 만들어서 진짜 기분좋게 먹고 왔어요🥰 직원분들도 친절하시고 볕도 잘 들어서 끝까지 좋은 텐션으로 있다 힐링하고 왔네여 💓 p.s. 화장실에 고영희 사진 꼭 보고 오기 ㅋ', 110, 25, 'GOOD', SYSTIMESTAMP);
