INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '뮤즈 시노님'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '딱 들어왔을때 파스텔톤으로 예쁘게 인테리어되어 있고 매장이 너무 청결해서 좋았어요🥹 맥북으로 셀카도 찍을 수 있게 세팅되어있답니다 !! 매장 내 화장실도 청결합니다..♡ 아이스티랑 크림소다 시켰는데 사실 크림소다는 맛을 기대하고 먹는 음료는 아니라구 생각했는데 넘 맛나서 놀랐어요!! 아이스티도 복숭아맛인데 사실 립* 생각했거든요,,(모두가 아는 그 맛) 근데 립*이랑 전혀 다른데 완전 맛있는 아이스티였어요!! ♡ 서비스로 주신 쿠키도 완전 맛나고 진심 왕친절 그자체십니다 크림소다 살짝 흘렸는데 후다닥 물티슈 가져다주셨어요 감동..', 28, 4, 'GOOD', SYSTIMESTAMP);
