INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '뮤즈 시노님'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '처음보는 가게 가보는 걸 좋아하는데 걷다가 새로 생긴 것 같아 방문했어요! 오픈한지 얼마 안되신 것 같았는데 내부 색감이 예쁘고 포토존이랑 좌석이 구분되어 있어서 사진 찍기 좋았습니다 :D 시즌메뉴(?)인듯한 토마토바질에이드도 너무 예쁘고 맛있었어요🥺 친구랑 떠들다가 좀 오래 앉아있었더니 곧 판매예정이라 연습해보고 있다며 푸딩도 주셨어요,,🍮 정식판매 시작하시면 가서 또 먹을거예요 ~~ 논커피 메뉴들이 많고 오트밀크 옵션도 있어서 자주 갈 것 같아요!', 18, 8, 'GOOD', SYSTIMESTAMP);
