INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '뮤즈 시노님'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '홍대 놀러갔다가 마감 한시간 남기고 찾아갔는데도 너무 친절하시고 음료가 넘 맛있었어용 ◡̈ ෆ  매장도 너무 예쁨데 서비스로 주신 쿠키도 너무 맛있었습니다 강추‼️', 39, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '뮤즈 시노님'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '궁금했던 카페인데 와보니 더 더 좋네요! 음료가 커피 위주가 아닌게 새로웠고 고민하다 저는 이달의 음료인 청귤하이볼을 마셨는데 넘넘 맛있었습니다🥹 청을 직접 담그신대요 역시~~ 친구는 메론소다 마셨는데 그것도 맛있다네요~~ 녹차치즈케이크도 넘 촉촉하고 쿠키도 맛있습니다 귀여운 포토존도 있으니 귀여운 인테리어도 구경하고 사진도 마니마니 찍어가세요 ~~~', 55, 13, 'GOOD', SYSTIMESTAMP);
