INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '뮤즈 시노님'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '청귤에이드 정말 달기만한 시럽이 아니라 직접 담그셨어서 그런지 너무 맛있었어요 ! 그리고 얼그레이도 직접 우리셔서 완전 깔끔하고 하이볼타먹고싶은(?) 맛이였ㄴ어요 ㅋㅌㅌㅌㅌ😏 카페의 전체적인 톤이 블루옐로우로 귀엽고 대화도 하기 좋은 담에 또 가구싶네용 😘😘', 50, 1, 'GOOD', SYSTIMESTAMP);
