INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '뮤즈 시노님'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '그냥 들어갔는데 홍대 디저트카페 중에 이렇게 인심좋은곳 처음이에여 베이커리 직접만드신다고 하시고 푸딩이랑 쿠키까지 아주그냥 엄청나여 ㅠㅠ사장님 ….열일해주세요… 아 글고 어디서 찍어도 사진이 너무 잘 나와서,,,포토이즘 갈필요가 엄서요 ヾ(๑╹◡╹)ﾉ“', 11, 8, 'GOOD', SYSTIMESTAMP);
