INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '뮤즈 시노님'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '오랜만에 홍대 갔다가 넘나 귀여운 카페를 발견했어용 !! 하늘하늘한 분위기에 사진찍기도 너무 좋구 음료도 진짜 맛있었습니당 ㅠㅠㅠ 피치하이볼과 밀크티 존맛 꼭꼭 드세요 !!!!', 88, 14, 'GOOD', SYSTIMESTAMP);
