INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '우리나라에 이런 곳이 있다고요..?.? 해리포터 컨셉 카페인데 들어간 순간 제가 호그와트에 있는 기분이어서 있는 내내 행복했어요💗 직접 옷이랑 목도리도 입어볼 수 있고 해리포터 브금들이 나와서 신비했어요✨ 기억이 넘 좋아서 다시 오고 싶어요~!!', 9, 0, 'GOOD', SYSTIMESTAMP);
