INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '음료가격이나 디저트가격이 조금 나가기는 하지만 사실 분위기에 놀라고 멋진 카페 마치 해리포터 영화속에 들어온것 같아 더욱 맘에 드는 것 아이들과 홍대 갈일 있다면 가서 잠시 분위기를 즐기는 것도 좋은 선택이 될듯합니다 저희는 대 만족 사진 백만 번 찍고 왔어요', 26, 4, 'GOOD', SYSTIMESTAMP);
