INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '아이기 갑자기 해리포터 카페 가고 싶다고 해서 검색했더니 정말 있었네요. 홍대에 규모도 엄청 크로 건물도 예쁘고 인테리어도 잘 되어 있어요. 음료들도 아이들이 좋아할만헌것들 시그니처 음료 좋아했어요 음료 시키고 약간 거미 장난감이랑 캔디들 많이 얻어서 아이들이 정말 좋아했어요. 네컷 사진도 찍고 평일에 와서 여유롭게 놀다 가서 좋았어요 해리포터 덕후들 추천할만합니다', 9, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '진짜 해리포터 테마 카페 중에 1등이지 않을까 진짜 너무 만족했어요:) 다만 음료 퀄리티나 카페트, 의류 세척을 안해서 살짝 냄새가 나는 건 아쉽지만 해리포터 러버라면 꼭 와보세요!! 완전 추천입니다:)👍🏻💕', 125, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '아이랑 홍대 올때마다 가게 되는 킹스크로스943 드레곤레그(칠면조)랑 꾀병스무디를 너무 좋아하네요. 해리포터 기숙사 의상 입고 사진도 찍을 수 있고 지하부터 4층까지 포토존도 많아요. 오랜만에 왔더니 내부 인테리어도 좀더 편안하게 바뀌었네요^^', 32, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '해리포터 덕후인 아이가 가고싶다고 해서 왔는데 메뉴들 넘 취향저격이고 층마다 넘 이뻐서 사진도 많이 찍고갑니다!!! 디저트 케이크 넘 맛있어요^^', 42, 7, 'GOOD', SYSTIMESTAMP);
