INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '초등학생들이 좋아해요 디저트 특별하고 분위기 좋아요 해리포터 좋아하는 아이들이 아주 만족해 했어요 식사보다는 디저트 하기 좋은 곳이예요', 49, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '아이가 해리포터를 좋아해서 너무 가보고 싶어 했던 곳입니다. 사진 스팟이 많아 지하에서 4층까지 이곳저곳 보고 사진 찍는 재미가있네요. 어맛 그리고 층마다 잘보면 숨겨져있는 장치가 있어요. 너무 신기하고 재밌습니다. 여유롭게 구경하고 색다른 음료도 마시니 아이와 함께 즐거운 추억이 될듯 합니다.', 62, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '부근에 볼 일이 있어서 왔다가 방문해보었어요! 칠면조가 맛있다는 추천을 받고 왔는데 제가 간날은 리뉴얼중이라 음료만 가능하다고 해서 아쉬웠어요~ㅜ 그래도 지하부터 4층까지 다 구경해보고 사진도 찍고, 너무 즐거웠어요! 아이가 꾀병스무디 너무 좋아하네요! 음료 가성비는 안좋지만 인테리어가 멋져서 좋았어요!', 37, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '컨셉이 확실한 볼 거 많은 곳이예요. 시그니처 음료  메뉴 시켜봤어요. 맛은 쏘쏘해요. 층별로 좌석 다양하고, 사진 잘 나와요.', 16, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '아이들과 연휴로인해 홍대에 놀러왔다가 마법사분위기의ㅡ카페가 있는것을 알고 들렀는데 층도 지하1층부터 4층까지 엄청 큰 카페엿고 지하1층에 늑대인간이랑 용같은걸 둘째가 무서워할정도로 리얼하네요 ㅎㅎㅎ  정말 추천합니다.', 28, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '기회가 될때 아이와 함께 꼭 와야지~  했던 곳 입니다. 지하 1층부터 지상 4층까지 곳곳이 포토죤이고 비싸긴 하지만 메뉴가 특별해서 좋네요^^ 아이와 함께 사진 찍고 수다떨기 괜찮아요. 그리고 좌석 넓은 곳도 많아서 여러명이 와도 좋을듯하네요~ 아이가 헤리포터에 대해 알았다면 더 좋아 했을텐데...ㅠ 그러지 못해 아쉽네요.', 50, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '해리포터컨셉 카페가 있다고 들었는데 아이와 홍대 나들이한 김에 방문해 봤어요! 생각보다그리 멀지 않았고 가는길 날씨가 많이 더웠지만 카페내부가 엄청 넓고 시원했습니다!^^ 음악과 인테리어와 장식들이 컨셉에 딱맞았고 놀이동산에 온 듯한 기분으로 입장하고 사진찍으며 놀았어요! 매뉴들도 독특해서 주문하는 재미도 있었고 해리포터케이크는 기념일에 한번 포장해가고 싶네요!^^ 기억에 남는건 엘리베이터 타고 내릴때 쾌감이 좋습니다 ㅎ 진짜 놀이동산 같아요~ 메뉴들 가격대가 좀 있는데 이런 컨셉카페들은 입장료있는 곳들이 있는데 그런거생각하면 그냥 적당하다 할 수 있겠어요! 아이나 친구들과 홍대가시면 한번쯤은 가볼만 합니다!', 21, 10, 'GOOD', SYSTIMESTAMP);
