INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '홍대에 놀러온김에 해리포터 컨셉이라하여 방문했어요 아이는 꾀병 스무디에 반해서 오고싶어했고 음식도맛있고 특별하고 신기해서 올만한거같앙아이가 좋아해요 ㅎㅎㅎ', 49, 0, 'GOOD', SYSTIMESTAMP);
