INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '해리포터에 나오는 마법세계 컨셉으로 꾸며진 카페예요. 아이랑 기념삼아 와보는 것도 좋을 것 같아요~ 다른카페에서는 없는 특별한 메뉴들도 이목을 끄는 곳이라 아이도 좋아하네요.', 47, 1, 'GOOD', SYSTIMESTAMP);
