INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '난타공연 보고 티켓가져가서 20프로 할인도 받았네요^^ 대기가 좀 있긴 했는데, 내부는 좌석 여유있고 괜찮았답니다. 특별히 왕 맛난건 없지만 층마다 사진도 찍고 이쁜 메뉴들 먹으면서 잘 쉬다 나왔어요~', 77, 16, 'GOOD', SYSTIMESTAMP);
