INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '아이와 함께 홍대 꼭 오면 들러보세요 사진찍기도 좋고 드레곤레그도 추천합니다 맛도 있고 아이가 좋아하네요 젤리와함께하는 꿈의 음료수가 있어서 더 좋아해요 ㅎㅎ', 66, 16, 'GOOD', SYSTIMESTAMP);
