INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '아이가 해리포터책을 좋아해서 홍대나온김에 들려봤는데 너무 신기해하네요^^ 박물관에 온 것 같아요 층마다 컨셉이 다르게 되있어서 둘러보는 재미가 있어요', 39, 7, 'GOOD', SYSTIMESTAMP);
