INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '처음 와본곳인데 너무 마음에 들어요 아이들이 엄청 좋아해요 또 오고싶어요 해리포터 팬입니다 캬~~내가 더 좋아 했지요 분위기 맛집 테마도 다 달라서 좋아요', 20, 9, 'GOOD', SYSTIMESTAMP);
