INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '책을 읽고 해리포터를 너무 좋아하는 아이와 함께 왔어요 으스스한 입장부터 설레였구요 외국인 관광객이 대부분이라 해외 펍에 와있는 기분도 듭니다 ㅎ 음료는 시크니처보다 딸기 에이드가 제일 맛있어요', 13, 1, 'GOOD', SYSTIMESTAMP);
