INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '해리포터 좋아하는 아이들과 함께 방문했어요 포토존 많아서 사진도 많이 찍고 아이들이 행복한 시간 보냈네요 특별한 음료도 너무 좋아했네요', 6, 5, 'GOOD', SYSTIMESTAMP);
