INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '아이들과 홍대 나들이 나왔다가 갑자기 왔는데 아이들이 넘 좋아하네요~~ 음료도 특이하고 인테리어도 특이하고 여기서만 경험할 수 있는곳이여서 음료가 쫌 비싸지만 색다른 분위기를 즐기고 싶다면 추천합니다.', 44, 9, 'GOOD', SYSTIMESTAMP);
