INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '층별로 테마가 있어서 너무 재밌는 곳이에요! 4층에서는 옷입구 사진찍을수도 있어요 ㅋㅋㅋ 미니 유니버셜 스튜디오 초코케이크도 꾸덕하고 맛있네요! 한번쯤 방문해보는거 추천합니당☺️', 17, 3, 'GOOD', SYSTIMESTAMP);
