INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '해덕들은 꼭 방문해보시길 추천드려요 인테리어를 정말 잘해놓으셔서 해덕인 저는 너무 만족스러웠어요! 음료는 좀 많이 비싸긴 한데 인테리어값으로 보고 기분 좋게 먹었습니다 ㅎㅎ', 14, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '아이와 함께 왔어요 해리포터 마법주문책도 사는 아이라 역시나 엄청 좋아했어요~~ 대기없이 들어와서 더 좋았구요 시그니처 음료들 다 맛있네요! 첫째랑만 왔는데 둘째도 데리고 와야겠어요! 해리포터덕후들에게 추천합니다 ㅋㅋ', 1, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '홍대 카페 킹크로스는 해리포터 컨셉 낭낭한 카페! 아이 및 연인과 데이트하기도 좋은 곳. 입장료 포함된 음료가격이라 좀 비싼감이 있지만 들어가면 하나도 아깝지않는 곳이다👍👍👍 층마다 장치있는것도 재미있고 분위기도 노래도 컨셉에 잘 맞음!!!! 후회없는 홍대 카페였음. 홍대 데이트로 추천 🫶❤️', 1, 7, 'GOOD', SYSTIMESTAMP);
