INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '해리포터 좋아하는 딸이 가자고 해서 왔어요~ 이런 곳이 있어서 행운이래요 ㅎㅎ 해리포터 분위기를 느낄 수 있어서 좋네요. 디테일이 좀더 살아있으면 좋을거같아요', 7, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '아이들이 해리포터 좋아해서 방학이라 한번 와봤어요~ 층마다 다른 분위기로 꾸며져 있어서 사진 찍기 좋았어요~ 음식 메뉴가 재미있고 귀여워요~ 맛도 있어서 즐겁게 맛있게 즐기다 갑니다^^', 11, 0, 'GOOD', SYSTIMESTAMP);
