INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '해리포터 좋아하면 진짜 꼭꼭 가보세요!!! 인테리어도 멋지고 사진어디서 막찍어도 예뻐요 ㅠㅠ 솔직히 음식은 기대안하고 갓는데 이런 공룡고기비주얼도 처음이고 심지어 맛있엇어요 ㅋㅋㅋ 버터맥주는 흑맥주에 아인슈페너 크림올린맛나용 ㅎㅎㅎ 멘드레이크 케이크 못먹은게 아쉬워서 담에 또올라구요 ㅠㅠㅠ', 24, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '아이와 방문 했는데 너무 좋아 합니다. 해리포터 호그와트 분워기 라고 좋아합니다. 이이들이 좋아하는 특별한 음료가 있네요. 거미스무디  꾀병스무디  아이가 좋아합니다. 아이를 위한 카페  좋아요', 422, 50, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '아이들이 좋아할만한 요소들이 많아요 음료 케잌 메뉴들이 특이해서 너무 신나하네요 맛도 좋아요 지하에서 4층까지 사진찍을 스팟들도 많아 지루하지 않고 주말 오전에 오니 여유롭고 너무 좋아요', 26, 1, 'GOOD', SYSTIMESTAMP);
