INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '#홍대카페 #킹스크로스  #해리포터카페 #신기한카페 #볼거리먹거리 친구랑 홍대 왔다가 해리포터 카페있다고 해서 왔는데 지하1층부터 4층까지 볼거리가 많음~ 다음엔 신랑이랑 와서 놀아야겠다 재방문의사 완전 또 있음~', 39, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '해리포터 덕후로서 합정에 이런데 있는지도 몰랐눈데 남자친구가 찾아봐서 같이 오게 됐어요~ 4층짜리 건물이고 지하도 있어서 생각보다 엄청 크고 각 층마다 해리포터 세트장처럼 꾸며서 진짜 좋아요 ㅎㅎ 사진찍기도 넘 좋아요 ㅎㅎㅎ 추천입니다아👍🏻👍🏻👍🏻👍🏻👍🏻', 89, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '해리포터 좋아하는 친구랑 같이 다녀왔는데 덕후들이 오기에 진짜 너무 잘 꾸며진 것 같아요. 사진도 잘 나오고 분위기도 영화 속 그대로 재연되어 있습니다. 추천 드려요. 그리고 꾀병 스무디 뽕따 맛인데맛있는 뽕따 맛으로 맛있어요.!!!!추천!', 28, 0, 'GOOD', SYSTIMESTAMP);
