INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '해포덕이라면 반드시 방문해야 하는 곳입니다! 인테리어를 너무 잘해놓으셔서 구경할 거리도 많고 마술공연도 해주셔서 시간 맞으면 정말 시간 순삭할만한 곳이에요. 음료랑 디저트도 컨셉 충만해서 과몰입하기 정말 좋아요🤗', 39, 9, 'GOOD', SYSTIMESTAMP);
