INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '입구부터 해리포터 세트장처럼 분위기가 너무 좋았어요. 음료도 케잌도 다른까페에서 볼수없는 특별한 메뉴에요. 아이들이 너무 좋아하네요^^', 116, 24, 'GOOD', SYSTIMESTAMP);
