INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '두번째 방문인데 버터맥주 엄청 맛있어요! 칠면조 다리도 엄청 부드럽고 양이 많아서 애들도 맛있게 먹었어요 사진도 잘 나오고 구경할게 많아서 좋아요', 15, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '아이가 해리포터를 너무 좋아하는데 홍대에 해리포터 테마의 카페가 있다고 해서~ 빙문했어요!! 주말에는 사람이 많다고 이야기들어서 오전에 방문했어요! 해리포터 테마로 이야기가 있는 카페라 너무 재미있고 좋아요!!! 아이가 너무 좋아하네요!!굿!!!!!!!!!굿!!!!!!!!!! 거리가 가까우면 지주오고 싶어요!! 만족 입니다~~~~~!!!^^', 3, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '아이 생일을 맞이해서 943킹스크로스 카페를 방문했어요 큰 기대는 안하고 가서 그런지 오히려 더 즐겁게 놀다 왔네요~ 음식이 비싸다는 후기가 있어서 각오는 했는데 비싸긴 하더라구요 ㅋ 시그니처 음료 한잔이 11800원..ㅋ 단걸 싫어한다면 시그니처는 비추해요 저흰 다 잘먹긴 했어요 ㅋ 그래도 지하부터 4층까지 돌아다니며 사진도 많이 찍고 마술공연도 보고 재밌는 시간 보내다 왔어요~ 해리포터를 좋아한다면 한번쯤 방문해 보면 좋을 거 같아요!', 22, 9, NULL, SYSTIMESTAMP);
