INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '인테리어가 진짜 독특하고 재밌어요. 해리포터 좋아하는 아이 엄청 즐거워합니다. 디저트와 음료들 디테일이 좋네요. 재방문의사있어요', 47, 1, 'GOOD', SYSTIMESTAMP);
