INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '컨셉 확실하고, 볼거리가 많음. 평일에는 넓고 한적하게 이용하기 좋음. 음식이랑 음료도 맛있음. 한번쯤 방문해서 경험해볼 만한 곳', 19, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '층마다 너무 잘꾸며놓아 구경하는 재미 사진찍는 재미가 쏠쏠했어요!! 기대하지않았던 드래곤레그는 정말 맛있었구요~ 드래곤 레그 먹으러 다시 와야겠어요^^', 87, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '평일 예약없이 왔는데 바로 들어올 수 있었어요 분위기도 좋고 찾아왔는데 오길 잘했어요 아이들이 좋아하네요 잘 먹고 맛있게 잘 지내고 갑니다', 408, 47, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '해리포터를 좋아하는 아이와 방문했어요!!  인테리어 너무 멋지고 주말에는 마술공연도 해서 아이와 방문하기 최고입니다. 음료수 디테일도 최고에요👍👍', 51, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '해리포터좀 봤다 하면 한번쯤 방문하기 좋을거같아요!!! 칠면조다리도 먹기는 힘들지만 꽤 맛있고 특이한 음료도 많고, 카페가 보는 재미가 있어요!', 35, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '첫째 아이가 해리포터 책을 읽고 해리포터 관련 검색을 하다가 발견 곳이예요~ 여기는 꼬옥 가봐야 한대서 방문 했어요. 모든 층이 해리포터 테마로 꾸며져 있어 구경하는 재미도 있고, 음료나 음식도 특색 있고 맛도 괜찮아요~ 토요일 오후 3시쯤 왔는데 생각보다 붐비지 않아서 자리 잡기도 수월했어요~ 시원하고 여유 있게 쉬다 갑니다!! 😆', 19, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '유명한 카페라 지인 추천으로 왔는데 색다르고 한 번쯤 와볼만한 곳이네요. 음료나 디저트 가격대가 좀 있지만 전반적으로 다 맛있어요.', 75, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '서울 여행 왔다가 방문했어요. 음료가 다소 비싸지만 입장해서 구경해보니 납득가는 가격이에요. 음료는 좀 달고 양이 많아서 아이들이 끝까지 못마셨지만 버터맥주는 위에 올려주는 은은한 단맛의 크림 덕분에 너무 맛있게 마셨어요! 해리의 생일케이크는 달지 않고 부드러워서 너무 맛있네요. 해리 포 터 덕후 가족이라 너무 즐거운 시간 보냈습니다^^ 겁 많은 12살 둘째는 코너 돌때 다른 손님만 마주쳐도 깜짝...ㅋㅋㅋ 재밌어요!', 68, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '일행과 저 둘다 해리포터를 좋아하고 잘 꾸민 것 같아 왔어요 밖에 엄청 큰 빗자루와 나머지 빗자루들이 있는데 포토존인듯 왼쪽의 입구로 가면 안에 장식용 계단이 보이고 줄서있더라구요 메인들은 리뉴얼예정이라 안됐고 술도 없었어요 시그니처세트는 왼쪽아래 케이크만 된대요ㅠㅠ 나가면 사람 인식 용이 있고 엘베와 지하층이 있어요 지하는 사람들 없었어요 층마다 테마별로 꾸며놨고 자리가 없어 원하는 곳에 못앉다가 나중에 옮겨앉았네요 다 예뻐요 꾀병스무디(소다) 위자드쇼콜라(초코) 흑마법사의 모자(초코케이크) 주문했는데 다 별로였어요 여긴 테마만 즐기는걸로.. 3층에서 어떤 분이 여기저기 마술 보여주다 시간되니 공연하시더라구요 4층은 침대컨셉이래도 누워있는 사람은 주의주면 좋을듯해요 보기 안좋았네요', 40, 4, NULL, SYSTIMESTAMP);
