INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '마법사카페 신기해서 아이들이랑 왔어요 거미스무디 신기해서 시켜보고 치즈케이크도 맛있네요^^ 직원분 친절하세요~ 잘 쉬다갑니다♡♡', 31, 2, 'GOOD', SYSTIMESTAMP);
