INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '음료도 독특하고 공간도 독특해서 와볼만 한 것 같아요. 특별한 느낌이 나서 좋네요. 해리포터 좋아하는 사람들에겐 넘 즐거운 곳입니다.', 39, 6, 'GOOD', SYSTIMESTAMP);
