INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '인테리어도 다 너무 이쁘고 매층마다 컨셉이 다 달라서 사진 찍을 곳도 너무 많아요!!! 디저트도 다 너무 맛있어요!! 해리포터 좋아하신다면 꼭 와보세요! 강추!!! 🥰🥰🥰🥰🥰', 20, 1, 'GOOD', SYSTIMESTAMP);
