INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '친구들이랑 오늘 처음 왔는데 매장 분위기랑 인테리어가 좋고 시진 찍고 수다떨기 너무 좋았어요 음료가 맜있었어요 다음에 또 방문할게요', 38, 4, 'GOOD', SYSTIMESTAMP);
