INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '해리포터팬이라면 강추요!! ^^ 인증샷 찍기도 좋고, 인테리어도 신기해요 ^^ 시그니처 메뉴인 칠면조다리가 들어있는 세트도 독특하고 맛있습니다 ^^', 84, 16, 'GOOD', SYSTIMESTAMP);
