INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '아이들이 좋아해서 또 왔어요~ 오늘도 사람이 많긴했지만 바로 앉을 수 있어서 다행이였어요~아이들이 좋아해서 다음에 또 올것 같아요~~', 8, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '아이가 요즘 해리포터를 좋아하는데 홍대에 해리포토 카페가 있다고 해서 찾아왔어요! 음료 맛없다고 리뷰가 많았는데 전 너무 맛있네요 ^^', 17, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '아이와 갈만한 곳 네이버 검색으로 찾아서 가봤어요. 해리포터 영화 본 큰 아이는 엄청 좋아합니다. 잘 모르는 둘째는 시큰둥. 입장료 값이 퍼함되서 그런건지 음료 등 좀 비싼편이구요. 아이들도 1메뉴 시캬야한대서 추가한 프랜치후라이가 맛있었어요. 초코케익은 별로라 남겼네요. 재미삼아 한번쯤 가볼만 합니다.', 12, 0, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '커피 진짜 ㄱㅐ맛없네... 이렇게 밍밍하고 맛없는 커피 진짜 오랫만에 먹어본다 케이크가 오지게 단데 커피가 밍밍하니 그야말로 최악... 어차피 사진찍으러 온거긴 하지만 오실 분들은 절대 커피 시키지 마시길', 77, 13, 'BAD', SYSTIMESTAMP);
