INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '정보없이 갔다가 생각보다 별다른 것이 없다고 생각했는데 아니었어요….! 알고 가야 재밌는 곳!!! 조카가 진짜 좋아했슴당 ㅋㅋㅋㅋㅋㅋ', 10, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '해리포터 덕후라면 꼭 와야하는 카페~^^ 신나게 사진 찍고 감자튀김이랑 케이크 먹다보니 시간이 금방 가네요. 인테리어가 넘 예뻐요. 사진도 잘 나오고 알바하시는 분들도 친절하셔요.  또 오고 싶어요♡', 77, 16, 'GOOD', SYSTIMESTAMP);
