INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '해리포터를 좋아하는 사람이라면 꼭 한번 와보세요! 재미있는 메뉴도 많고 영화 안에 들어와 있는 기분이예요. 아이가 아주 좋아해서 뿌듯합니다!', 10, 0, NULL, SYSTIMESTAMP);
