INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '두번째  방문  입니다 진심을 다해  컨셉에  맞춘  음힏  구성들  감동  적이네요 음식은  생각보다  맛있습니다 양이  많아서  4인이  먹기  좋아요!1층부터 4층까지  둘러보고  사진찍고  시간  금방  간답니다 안이  어두워서  좀  사진  찍을때는 아쉽네요 즐거운 데이트 였습니다!!', 74, 17, 'GOOD', SYSTIMESTAMP);
