INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '친구랑 우연히 들렀는데 둘 다 해리포터 좋아해서 너무 즐겁게 잘 즐기다가 왔어요 인테리어부터 음악까지 진짜 영화 속에 있는 것 같은 기분을 느낄 수 있고 디저트도 너무 귀엽고 맛있었습니당 4층에서 호그와트 교복도 입어볼 수 있어서 아이들과 함께 오면 좋을 것 같아요!', 28, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '아이가 너무 오고싶어했던 곳이예요! 해덕이(해리포터덕후) 친구들하고 와서 신났어요~ 정말 제대로 꾸며놓으셨네요~ 음료도 맛있고 아이들 취저네요!! 완전 대만족입니다!', 15, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '지난 번에 와보고 넘 분위기 좋구 맛있어서 또 왔어요 🩷 역시 기대를 져버리지 않는 최강 비쥬얼 오늘도 즐거운 경험을 먹고 갑니다 😍', 5, 7, 'GOOD', SYSTIMESTAMP);
