INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '해리포터 좋아하는 아이면 꼭 와봐야 하는 카페!!! 인테리어가 아주 멋져요!! 입장 하면 눈이 쉴틈 없어요!!! 해리포터 음악소리에 영화의 한장면에 들어와 있는 것 같아요!!', 2, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '해리포터에 푹 빠져있는 아이와 함께 방문했어요~~ 매장 여기저기 너무 잘 꾸며놔서 구경하는 재미가 있어요~ 쾌적하고 공간도 넓고~~ 너무너무 좋았어요😆😆🥰🤩', 27, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '체험할 수 있는 공간이 엄청 다양하고 많고, 층수도 지하 1층까지 총 4층이나 있어서 해리포터 덕후들에게는 어마어마하게 좋아요! 외국인들도 한국여행때 필수코스로 많이 오는것 같더라구요 한 번쯤은 와보셔도 돈이 아깝지 않습니다', 81, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '해리포터 카페라고 듣고 해리포터 덕후 아들 데리고 찾아갔는데.. 해리포터는 전혀 없고 그냥 마법사카페네요 ㅠㅠ  bgm 해리포터 음악과 비슷하다가 달라지는게 표절인것 같았어요. 해리포터 관련 글이나 인물은 하나도 못봤구요^^;; 괴물 그림들은 많아요. ㅎㅎㅎ 그리고 목요일 3시쯤갔는데 카운터 남자분이 너무너무 불친절해서 입장부터 기분이 상했어요. 메뉴에 대해 물어봐도 알아서 찾아보라는 식.. 다신 안갈것 같아요.', 34, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '가격이 비싸 보이지만 입장료라고 생각하면 납득이 되고 기대보다 음료 메뉴가 아주 맛있어요. 대기자가 많아 오래 기다려야 했지만(재료 소진도;;) 해리포터 좋아하는 아이가 있다면 가 볼만 한 장소입니다!', 5, 9, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '메뉴가 독특하고 귀여워요. 곳곳에 포토존과 구경거리가 있어 재밌었고 층마다 테마가 있어서 좋았어요! 4층 기숙사는 좌석 테마로 침대라 특이해서 좋았습니당', 4, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '음료는 비싸지만 아이들이랑 하나씩 구경하는 재미가 있어요. 외국인분들도 가족 단위로 많이 오시네요. 자리도 편하고 넓어서 쉬다가기도 좋은 거 같아요~', 43, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '실내 장식이 정말 아름답게 느껴지네요. 세련된 디자인과 조화로운 색감이 눈에 띄는 것 같아요. 전체적인 분위기가 편안하고 아늑한 느낌을 주네요. 섬세한 디테일과 개성이 돋보이는 공간 같아요. 이런 멋진 인테리어는 보기만 해도 기분이 좋아지네요.', 33, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '아이와 홍대나들이 왔다가 요즘 핫플이라고 그래서 한번 방문해 보았는데 아이들고ㅏ 함께오기 딱 좋네요. 아이들이 조금 무서워 하긴 했는데 재미있어하고 곳곳을 살피며 즐거워했습니다!!', 22, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '해리포터 덕후는 꼭 방문하길 추천합니다. 컨셉이 다했어요. 멋진 공간에서 사진도 많이 찍고 해리포터를 맘껏 즐길 수 있었어요. 음료는 비싼편이지만 입장료 포함된 금액으로 생각하면 무난합니다. 아이가 매우 좋아하네요.', 15, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '서울여행 계획중, 해리포터 좋아하는 큰아들때문에 이 카페를 중심으로 계획을 짰습니다 주말이라 웨이팅이 길까봐 걱정했지만, 시간대 잘맞춰오면 붐비지않고 여유있게 구경하며 즐길수있어요. 블로그글들에 음료가 많이 달다고했는데 제 입맛에는 크게 달지않았습니다^^ 이색적이고 아이들이 흥미로워해서 뿌듯한 하루네요. 참, 직원분들이 너무 친절하십니다❤️', 40, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '아이들과 동생이랑 같이 홍대 나들이로 들렀어요~ 특별한 분위기에 아이들이 좋아하는 해리포터를 그대로 즐길수 있네요~ 여기서만 느낄수 있는 음식도 짱입니다! :)', 78, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '지난번에 지나쳤는데 아이가 가보고 싶다해서 왔어여 제가 해리포터 덕후라 아이에게 해리포터 보여주며 주입 시킨 보람이 있네요^ 일부러 일본 등에 여행가서 찾아가기도 하는데 생각하면 음료도 그렇게 비싸진 않아요. 놀이동산에서 사먹는 비싼 음료라고 생각하심 됩니당 ㅋ 유니버셜에서 사먹었던 버터맥주? 보다 맛나요… 멘드레이크 케이크는 배불러서 포장해 갑니다', 16, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '최근 해리포터 영화를 보면서 해리포터에 관심이 많은 아이들을 위해 방문해보았는데요 인테리어가 멋지고, 거미스무디, 꾀병스무디도 맛있게 잘 먹었습니다', 370, 61, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '해리포터 컨셉에 완전 진심인 카페입니다~ 해리포터 덕후라면 무조건 와봐야해요! 음료도 맛있고 곳곳 포토존과 이벤트가 재밌습니다ㅎㅎ', 45, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '인테리어랑 분위기 미쳤어요!! 진짜 해리포터 영화와 드라마 안에 들어온 기분이에요.!! 음료와 메뉴도 넘 특색 있고 신기하네요 ~~', 11, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '실망이었어요 아이들이 다시.가서 꾀병스무디를 먹고싶다하여 방학을 이용해 방문했어요 이전에는 음료와 커피가 맛있어서 비싸도 만족스러웠는데 이번에는.가격은.더.비싸지고 맛은 더 저렴해졌네요. . 음료마시러 간건데 돈 아까웠어요 드래곤레그는 아이들이 재밌어하고 초반엔잘먹었지만 소스도그렇고 모든데 마트서 사먹는맛이예요', 27, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '너무 멋진곳입니다. 가족 나들이에 너무 적합한 곳이에요. 무엇보다 직원들이 친절해서 좋습니다~^^ 음료도 맛있고 추억을 남기기에 아주 맘에 듭니다. 번창하세요~^^', 47, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '해리포터 좋아해서 찾아보고왔어요!✨메뉴도 너무 다 예쁜데 맛있고 분위기도 좋았어요ㅎㅎ한참 잘 놀고있는데 한 마술사분께서 테이블에서 카드마술도 보여주시고 너무 신기하고 좋았어요👍👍무엇보다 잘생기셨답니다😊이런 이벤트 너무 좋아요! 담번에 또 방문할게요ㅎㅎㅎ', 31, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '아이들이 해리포터를 많이 좋아해서 찾아간 곳! 평일에 가니 사람이 하나도 없어서 편안하게 쉬면서 밥도 먹고 낮잠도 잠깐 자다가~ 사진 왕창 찍고 돌아옴~ 아이들이 좋아하니 그걸로 됬음! 하지만 내 개인적으로는 세트메뉴 음식은 괜찮았는데 음료는 정말 별로....', 81, 14, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '아이들과 방문했는데 해리포터 컨셉 넘 좋네요ㅎㅎ 포토스팟도 많고 음료도 디저트도 전부 맛있어요! 아이들도 굉장히 좋아해서 다음에 또 방문하려고요 만족합니다!!', 124, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '해리포터 좋아하는 아이라 일부러 찾아와보았습니다^^ 멋진 인테리어에 아이들이 재미있게 구경하였습니다. 특이한 음료메뉴에 즐거워했어요^^ 구석구석 숨겨진 곳을 찾는 재미가 있어요!  아이와 함께 홍대나들이 온다면 추천합니다!', 61, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '5월 5일 어린이날 기념으로 색다른 걸 찾다가 오게 되었어요~!! 아이뿐만 아니라 어른들도 같이 오기 좋아서 가족카페로 추천입니다~~ 칠면조 정말 맛있어요~^^', 73, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '한국에 이런곳이 있다니! 이미 외국인들한테 소문이 났는지 외국인 손님들이 많았어요~! 자리도 많아서 주문하고 나서는 대기도 없답니다! 예전에 왔을때랑 달라져서 더 놀랐어요 맨드레이크 케이크는 ㅋㅋ 최고귀여움 ㅠㅠㅠ', 47, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '아이랑 집근처 갈곳없나 검색하다 발견하곤 바로 고고!! 애가 드레곤레그가 넘나 기대된다고 ㅋㅋㅋ 기대없이 먹었는데 넘 맛있다며 다리째 들고 다 뜯었다는ㅋ 구석구석 해리포터의 디테일이 살아있어요^^ 해리포터 컨셉이라 박물관처럼 생각하고 오심 안되요ㅋ 해리포터 실생활 공간서 쉬다오는 느낌ㅎㅎ 암튼 디저트 넘넘 이쁘고 일본서 못먹고온 버터맥주도 먹어서 그저 대만족합니다^^', 100, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '아이가 해리포터 좋아해서 방문했어요. 사진 찍기 좋고 시그니처 메뉴도 괜찮네요. 해리포터 분위기 물씬 나고 층별로 잘 꾸며놨어요.', 63, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '해리포터 덕후인 아이를 위해 방문했어요 카페라 큰 기대는 안했는데 여기저기 세심한 인테리어가 인상적이네요 음료와 디저트가 특별해서 너무 재밌게먹었어요 조금 어두컴컴한 분위기라 더 운치있습니다😊', 39, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '아이가 해리포터 좋아해서 들렀는데 정말 좋아했어요 음료도 맛있고 분위기도 너무 좋네요 다음에 평일에 한가할 때 한번 더 들리고 싶어요~^^', 128, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '음료는 거미스무디랑 위자드쇼콜라 시켰는데 거미스무디는 오레오맛인데 위자드쇼콜라에 비해 엄청 달았어요! 위자드쇼콜라도 달달한 초코맛으로 단 편입니다~ 해리포터 좋아해서 가봤는데 잘 꾸며져있어서  좋았고 자리도 많아서 앉을 자리는 있었어요! 점심보다는 저녁즈음에 가니깐 좀 한적해서 여유롭게 즐겼습니다!', 40, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '저는 우와 할정도이리었는데 아이는 해리포터를 좋아해서인지 한국에서가본곳중 최고라고 내년에도오고싶대요 의외로 드레곤레드가 안짜고부드럽고, 음료는 너무달더라구요 물은 무료로주셨어요', 34, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '해리포터 좋아하는 아이가 엄청 좋아했어요 ㅎ 여기저기 다니면서 해리포터에 대한 지식을 술술술… 볼 거리가 많아서 카페라기보단 테마 체험관 느낌이었고 그에 비하면 가격이 저렴하다고 느꼈어요 재밌게 놀았습니당', 66, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '아이가 해리포터를 보기 시작해서 왔는데 너무 좋아했어요!!!! 특히 마술사가 와서 마법도 보여주고 즐거워했어요  음료도 맛있도 재방문하고 싶네요', 427, 89, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '아이랑 지난주  도쿄 해리포터 스튜디오를 다녀오고 한국에도 이런곳이 있단곳을 알고 찾아왔어요~ 음료가 비싼편이지만 젤리며 초코머랭쿠키며 독특하고 어두컴컴한 분위기나 음악이 해리포터 스튜디오 까페보다 멋집니다ㅎㅎ 단 구경거리는 아니고 까페 자리들이 층마다 분위기가 다르니 보는 재미가 있네요. 가챠하고 일본 캐릭터상품도 많고 여기가 한국인지 일본인지 잠시 헷갈렸네요ㅎㅎ', 89, 14, 'GOOD', SYSTIMESTAMP);
