INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '해리포터 덕후로써 아주 좋은방문입니다 ^^ 오늘 집에가서 해리포터 정주행 다시 합니다 너무너무 좋아요 ㅎㅎㅎㅎ 특이한 음식도 있고 다음에 또 올게요 ~~^^', 50, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '과일치즈플레이트 맛있네요 생각보다 잘 나와서 놀랐어요ㅋㅋ 그리고 소다스무디 뽕따맛인데 젤리도 있고 해서아이들이 좋아해요 카페가 해리포터 테마라서 기본적으로 영화 보고 책 보고 온 애들이 환장 합니다ㅋㅋ 서울이라 사람이 적은 편은 아니지만 매장이 커서 어떻게든 자리가 나는 편이에요 화장실은 그리 좋진 않았어요 화장실 변기커버가 부서져있더라구요;; 그거 빼곤 다 좋아요~!', 3, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '아이가 해리포터를좋아해서 왔어요 입구부터 포토존이 잘되어있고 음료나 디저트도 독특한게 많아서 아이가 좋아해요 아쉬운점은 4층 해리포터 마법사옷입고 사진찍는포토존에 어린이용도 있으면 좋겠고 목도리가 지저분했습니다 해리포터컨셉이라그런지 음료 디저트가 비싼편이고 비싼편에비해 맛이 뛰어나진않은거같아요 해리포터 좋아해서 아이는 만족했습니다', 3, 7, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '홍대 필수 카페♡!!  해덕들이 좋아합니다. 4층은  침대테이블,  침대를 4층에 굳이 올린 이유는 마법사들이 한 듯한 느낌. 느낌아니까~ (기숙사) 3층(연회장) 은 볼드모트분위기인데  긴 테이블이 있어서 회식해도될듯 ,  2층(마법사카페)은 따듯했어요  히터가 요기서 빵빵 1층은 웨이팅이 있었어도 즐겁게 기다리게 해준 용이랑 찰칵찰칵~!    칠면조 맛있었어요.  버터비어는  달고달고달고단 거품키스가능 ㅋㅋㅋ', 82, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '친구랑 서울 여행 중에 방문했습니다👍🏻 저녁 시간대라 바로 입장 가능했고 해리포터 인테리어 실제로 보니까 더 멋졌어요! 음료도 특색있었고 맨드레이크 케이크 짱 귀여웠음..🥰 다음에 또 방문하고 싶을 정도로 재밌게 즐기고 갈 수 있었습니다🫶🏻', 111, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '생각보다 너무 멋있게 꾸며져 있어서 놀랐고 신났어요! 진짜 해리포터 속의 이야기에 들어온 기분이 들어서 좋았습니다!! 음료도 맛있고 데코도 너무 좋기는 했는데 다 단 음료여서  마시기 힘들더라고요...ㅎ 단 음료 좋아하시면 더 즐겁게 오랜시간 즐길 수 있을 것 같아요!!', 49, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '아이가 정말 좋아했어요!! 그런데 층마다 좀 덥고, 주문받는 남자직원이 좀 불친절 했습니다. 진동벨도 잘못줘서 하도 오래걸리길래 내려가니 음료와 케익은 이미 한참전에 나와있었고 진동벨을 잘못주고는 사과도 없네요.', 28, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '홍대 해리포터 카페 분위기 최고! 소품 하나하나 다 디테일 있고 음료나 케이크도 독특해요👍🏻아이도 너무 좋아하고 해리포터 좋아하는 사람이라면 꼭 들러보세요^^', 0, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '아이가 헤리포터  영화를 좋아해서 방문했어요. 운좋게 바로 입장했어요. 아이가 신기해하고 한참 놀다왔네요^^ 이색데이트하기 좋은장소입니다~', 28, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '날씨 좋은 주말 해리포터 좋아하는 아이들과 함께 방문했어요. 드레곤플레이트세트를 주문했는데 배가 고픈 때라 부족할듯 싶었으나 먹다보니 완전 배부른? 양이었어요. 음료도 맛좋고 지하부터 4층까지 구경하느라 두시간이 훌쩍 넘어 나왔네요. 주말 마술쇼 까지 알차게 놀다 가요~ #홍대카페', 122, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '아이가 해리포터를 아주 좋아해서 전부터 방문하고 싶었는데 방학을 맞아 방문했어요. 영화처럼 잘 꾸며 놓아서 사진 찍기 좋아요 :)', 29, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '몇년전부터 오고싶었던곳! 되게 아늑하고 좋아용 버터맥주도 맛있고(갠적으로 초딩입맛이라 조금 더 달면 좋을거같아여ㅎㅎㅎ🤍) 대기는 있었는데 금방금방 빠져서 10분도 안기다린거같아용 담에는 디저트 먹으러 와보려구요@.@ 집가서 해리포터 봐야겠네영ㅎㅎㅎ🧙‍♂️', 29, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '해리포터 좋아하는 아이들이랑 함께 방문했어요! 인테리어가 잘 되어있어서 재미있었는데 지하 1층은 지금 공사중이라 넘 아쉬웠어요!', 15, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '해리포터 덕후라먼 한번쯤 방문해보시길 추천합니다. 4층까지 있는데 층별로 테마도 다르고, 음악도 해리포터 관련으로 계속 나와서 분위기 좋아요!', 50, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '아이들과 주말에 홍대 나왔다가 해리포터 테마카페가 있다고 해서 방문했어요! 해리포터가 사는 호그와트에 들어온 것 같아 좋네요~재미있게 놀고 갑니다♡ 버터맥주 넘 맛있어요!', 4, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '친구가 해리포터를 엄청좋아해서 홍대에 해리포터 컨셉 카페가있다해서 갔어요 매장도 넓고 곳곳에 해리포터 관련해서 잘 꾸며져 있었어요 옷도 입어볼 수 있었고 포토존도 많았어요 음료는 입장료포함해서 그런지 만원초반이였어요 ㄷㄷ 저 스무디위에 있는 초콜릿모자 엄청 안녹아요 돌멩이인줄 알았어요 암튼 음료는 맛있었어요', 51, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '어린이날 해리포터 팝업에 맞춰서 함께 이용했어요 긴 기다림이였지만 아이가 해리포터를 좋아해서 다행인 하루였어요 버터맥주 마시고 기분 업된 아이', 17, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '음료 쿼리티는 좋은 편. 디저트는 품절되서 못 먹음. 해리포터 좋아하는 아이들을 위해서는 기볼만한 곳 분위기는 해리 포터 세트장 느낌같은? 그러나 별 이유 앖이 너무 오래 기다려야했다. 안에 자리도 많은데 왜 그럴까? 저작권 때문이겠지만 어쨌든 sns만큼의 장소는 아닌듯. 내 입장에서는 기다린 시간이 아깝다. 애들도 해리 포터와 다르다고 뭐라한다.', 22, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '킹스크로스카페방문했어요 외국인도 많고 붐볐지만 특색있는 경험입니다. 메인메뉴 칠면조 랑 감튀도 맛있어요 굿굿 해리포터 덕후들도 많아요 친절하네요', 34, 4, 'GOOD', SYSTIMESTAMP);
