INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '해리포터 느낌 물씬 나는 곳으로 음료는 좀 비싸지만 구경하는 재미가 있어요~~ 스*타벅스에서도 케이크 팔긴하는데 여기가  좀 더 리얼리틱하고 맨드레이크 케잌도 있어서 재밌어요~~~ 데이트하기 좋아요~', 37, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '일단 옷입고 사진찍을 수 있는 포토존도 있고 멋있게 꾸민 것이 많아서 좋았어요! 음식도 너무 해리포터스러워서 해덕은 울고갑니당 ㅜㅜ 근데 포스터에 퀴즈 있는거 같은데 그냥 컨셉인지 아님 진짜 퀴즈인지 궁금해요~~ 맞춰볼려고 했는데 다 찾지 못해서 맞출 수가 없었음... 가오픈때보다 인테리어도 더 멋있어졌네요~~', 20, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '아이가 해리포터를 너무좋아해서 홍대나들이를 이 카페를위해 계획했어요 역시나 아이가너무 좋아해요 층별로 테마도 너무 디테일하고 음료도 너무나 먹기아깝게 만들어놨습니다 또 생각나는 인생카페가될거같네용 해리포터를 좋아하는 아이라면 꼭방문추천드립니다 !!!', 26, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '아이가 해리포터를 좋아해서 왔습니다. 가격이 쌘편이었는데 인테리어가 잘꾸며져있어서 깜짝놀라고 돌아갑니다. 해리포터 덕후라면 추천할만합니다!', 17, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '해리포터를 좋아하는 아이들을 위해 방학 마지막날 방문해보았어요~ 처음에 아이가 샘플인줄 알고 나온 음료를 만졌는데 너무 감사하게 다시 만들어주셨네요 친절함에 감사합니당 ㅠㅠ 사진 찍을곳도 많고 음료도 아이들이 너무 좋아해요~ 다시 오고 싶은 곳입니다~!!!! 추천이요!!', 68, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '해리포터 덕후라면 완젼 반할곳입니다 왜 여길 이제 왔을까요 꺄 꺄 꺄 👀👀👀 음료도 맛있고 잼나요 다시 와야겠어요 아이는 몇번을 층마다 다니며 보고 또 보고 합니다', 8, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '위자드 쇼콜라 Hot&Ice/ 음료 가격은 쎄지만 인테리어를 보고나면 입장료도 포함되는건가 라는걸 생각하게 되고 꽤 만족을 했습니다ㅎ 쇼콜라 Hot는 메뉴엔 토핑모자가 없어서 안주는줄 알았는데 주셔서 좋았어요~토핑모자는 머랭인 것 같았는데 나쁘지않았고 귀여워서 좋았어요~ 양도 굉장히 많아요~ 저야 원래 잘 못마셔서 남기지만, 일행은 원래 빨리 마시는데도 양이 많아서인지 천천히 다 마시더라구요ㅎ 일행이 마신 Ice에 들어가는 초코칩이 맛있었다고 해요~ 테마가 좋아서 한 번쯤은 즐기러 오는 것도 좋아요~ 주문할때 영수증에 국적이 나오는데 이것도 꽤 독특해서 재밌었어요~ㅎ', 6, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '해리포터 시리즈 영화를 많이보구 좋아하게된 아이와 함께 이곳을 찾았는데 처음엔 아이가 어두워서 조금 멈짓했다가 바로 즐겁게 구경했어요 무서운것을 싫어하는 친구는 한번 생각해보시면 될 것같고 좋아하는 친구들은 이것저것 영화이야기 하며 즐길 수 있습니다~!', 129, 21, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '해리포터를 좋아하는 아이와 함께 방문했어요~~ 이런 까페는 가격만 비싸고 맛없는곳 많은데 디저트는 모양도 예쁘고 아이가 정말맛있게 먹었습니다! 직원분들도 매우 친절하고 프렌치프라이도 맛있었어요~!', 11, 7, 'GOOD', SYSTIMESTAMP);
