INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '해피포터를 좋아하는 아이들에게는 최고의 장소에요 가격대는 홍대 입지와 컨셉 값이라 생각하면 되구요 주말 낮인데도 자리가 많아 바로앉았습니다 추천해요', 64, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '아이들이 해리포터좋아해서 홍대까지와봤네요 분위기 너무좋고 칠면조고기 특별한메뉴까지있어서 너무 좋네요 인생네컷도찍고 해리포터옷도 입어봤어요^-^', 116, 21, 'GOOD', SYSTIMESTAMP);
