INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '아이들이 해리포터에 빠져서 방문하게 되었어요 아쉽게도 맨드레이크케이크는 품절이었지만 거미스무디.꾀병스무디는 주문할수 있었어요ㅎㅎㅎ 해리포터 좋아하면 한번쯤 방문하기 좋은곳 같아요~~', 34, 4, 'GOOD', SYSTIMESTAMP);
