INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '해리포터 덕후라면 강추하는 테마 카페로 초5  딸아이가 너무 좋아했던 장소 해리포터 갬성을 느낄 수 있어 행복했음^^ #홍대카페 #해리포터 #943킹스크로스', 122, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '943킹크로스 헤리포터 컨셉에 맞게 층마다 테마가 다양하다. 쇼콜라 그린티 거미스무디 꾀병스무디 달콤하고 스무디의 마법이 들어가 맛있네요~ 아이들과 주말 나들이 마지막 코스 끝내주네요~^^', 9, 8, NULL, SYSTIMESTAMP);
