INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '아이들과 방학중에 오기 좋아요 메뉴금액은 저렴하지는않지만 재미와 추억을 남기기에 좋은가격인듯요 주차는 근처 민영주차장 또는 대중교통이용하세요 칠면조 다리들고사진찍고 뜯어먹는재미가있어요 빵도부드럽고맛있고 음료는 달달그자체네요 다 달아요 ㅋ 어른들은 일반음료나 커피드심이~~~ 분위기.매장음악 다 좋습니다', 89, 15, 'GOOD', SYSTIMESTAMP);
