INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '해리포터 덕후 초딩들이랑 다녀왔어요~ 인테리어에 애들이 홀딱 반하고 넘 좋아해요 단 거 좋아해서 음료도 맛있다네요ㅋㅋ 버터맥주도 전 괜찮았어요!', 47, 2, NULL, SYSTIMESTAMP);
