INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '해리포터컨셉이라고해서 아이들과 왔는데 너무좋아요 4층까지구경할거도많고 자리도많아서사람이많아도 복잡하지않네요 음료는컨셉이있어재미있는맛이에요', 18, 10, 'GOOD', SYSTIMESTAMP);
