INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '궁금해서 아이들이랑 왔는데 가운이랑 목도리도 있어서 사진도 찍을 수 있고 ㅎ 메뉴도 해리포터 스토리 맞춰서 만들어 주셔서 재밌네요 ! 일요일 12시 정도 까지는 웨이팅 없고 좋은 거 같아요 ㅎㅎ 음료가 어마무시하게 맛있진 않지만 (좀 달아요) 버터 맥주가 맛있어요!!', 18, 0, NULL, SYSTIMESTAMP);
