INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '내부인테리어에 비해 가격이 쫌 비싸서 처음엔 아쉬웠지만, 마술사가 있어서 재밌었어요!! 컨셉에 맞게 음악과 마술이 잘 어우러져서 친구와 재밌게 구경했습니당!! 마술사가 찾아오면 놀라지마시고 모두들 마술 구경하고가세요!!!!!!', 14, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '해리포터 분위기 카페라고해서 아이들과 함께 방문했어요 아이들이 너무 좋아하네요^^ 저희는 4층 기숙사 층에서 드레곤 레그를 먹었는데 부드럽고 맛있는 만족스러운 식사였습니다. ~!', 70, 14, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '아이가 해리포터를 너무 좋아해서 홍대 나들이 나온김에 와봤어요. 인테리어도 진짜 멋지고 엘레베이터도 꼭 한번 타보세요! 마법학교 입학한 느낌 음료는 괜찮은데 일회용컵에 주셔서 그게 좀 아쉬웠어요. 해리포터 느낌에 컵이면 더 좋지않았을까 저만의 생각ㅋ 여튼 홍대 한복판에서 이런 느낌을 받을 수 있단게 재미있어요. 재방문의사.있어요!', 89, 14, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '극한의 컨셉충 카페… 홍대 카페가 슬슬 지겨워지던 차에 이런 곳 발견해서 좋네요ㅎㅎㅎ 앉아서 지내고 있다 보면 어디선가 마술사 님이 나타나 묘기를 보여주십니다ㅋㅋㅋㅋ 메뉴도 특이하고 재밌었어요!!', 53, 17, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '컨셉 확실합니다ㅎㅎㅎ 어린이들 좋아해서 가족단위로 오는 사람들이 제법 있어요 2회차 방문인데 아마 아이가 원하면 또 올듯합니다 해리포터 분위기 느끼기에 괜찮은 특색있는곳. 디저트나 음식은 금액대가 좀 있어요', 33, 3, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '해리포터 좋아하는 딸. 마호도코로 들렀다 킹스크로스까지 풀코스까지 대만족 하네요~ 가격은 좀 비싸지만 볼거리가 많고 깔끔해요~포토존이 많아 사진찍기도 좋네요~', 89, 13, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '해리포터 카페 가보고싶었는데 색다른 카페였어요 매장은 엄청 넓고 해리포터 분위기도 나면서 옷도 입어볼 수 있게 되어있어요! 구경거리는 생각보단 많이 없어서 아쉬웠어요 사진 찍을 공간도 많고 재미있으니 한번 가보는건 추천 드려요!!', 19, 2, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '해리포터 소설속에 들어온것 같아요~ 매장 전체 컨셉, 음료, 배경음악 등 모든것이 공을 많이 들인것 같아서 멀리서 찾아온 보람이 있네요🙂', 116, 21, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '층별로 각각의 테마로 나누어진 것이 가장 맘에 들었어요! 특히 4층인 기숙사는 기숙사 의상을 입곺사진울 찍을 수 있는 장소도 마련되어 있고 예쁜 인테리어 소품들도 많아서 가장 맘에 들었어요! 다만 가격이 너무 비싸요 ㅠㅠ', 2, 3, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '초등학교 3.5학년 남매 데리고 왔는데 무척 흥미있어 하네요. 층마다 다른 컨셉에 음악도 나오고 정말 영화 속 해리포터 장면 안으로 온 것 같아요.^^', 17, 3, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '#해리포터카페 #홍대나들이 #홍대 핫플 해리포터 좋아하는 아이들과 방문했어요~~~ 입구부터 아이들 시선강탈하고 시그니처 음료도 재미있어요. 드래곤 플레이트 칠면조 고기를 아이가 맛있게 잘 먹었습니다. 사진도 많이 찍고 특별한 카페 데이트 원하시면 방문해 보셔도 좋을 것 같아요 :)', 6, 8, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '이번이 두번 째 방문인데 아이가 매우 좋아하네요. 층마다 멋진 테마로 꾸며진 인테리어를 보고 있자니 마치 호그와트 마법 학교에 와 있는 기분이 들었어요. 사진도 예쁘게 잘 찍히더라구요.👍 베스트 세트로 시킨 드래곤 플레이트 메뉴와 음료도 양도 많고 맛있었어요. 내내 번창하시고, 새해 복 많이 받으세요.👍😊', 36, 8, 'GOOD', SYSTIMESTAMP);
