INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '아이가 해리포터에 푹 빠져있어서 찾아서 왔어요  분위기가 완전 해리포터네요 ㅎㅎ 구석구석 재미있는 소품들이 있고 사진찍기 좋네요  음료도 특색있고 맛도 좋아요  만족합니다', 20, 7, 'GOOD', SYSTIMESTAMP);
