INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '해리포터 좋아해서 처음으로 여기와봤는데 진짜 너무 재밌었어요!🥹💕✨️✨️ 디저트나 음식도 신기한게 많고 층마다 각 테마가 달라서 너무 신기했어요! 그리고 층마다 이스터에그처럼 숨겨져있는 이벤트도 너무 재밌게했습니다!😆💕💕', 480, 39, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '드디어 벼르고 벼르다 왔어요. 가격은 좀 있지만 특별한날 먹기 좋은 것 같아요. 아이가 해리포터를 좋아해서 와봤는데 좋아해서 기분 좋네요.^^', 40, 9, NULL, SYSTIMESTAMP);
