INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '해리포터를 좋아하는 아이들과 함께왔어요! 음료가 다 맛있고 분위기도 좋아요ㅎㅎ 해리포터 좋아하면 아이들과 오시면 좋을거에요 추천합니다 :)', 29, 8, 'GOOD', SYSTIMESTAMP);
