INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '리뷰는 딸아이가적었어요  맞춤법이안맞을지도 ㅋㅋ 너무너무대밌었어용 음식도 밋있고 볼구경 거리도 많았어요 ㅎㅎ 가족이나 친구들이랑 같이가기추추추추천 이에영 영수증 이벤하면 젤리빈도주고 ㅎㅎ해리포터좋아하시는분은 많이오세요!!조금만한재미있는 재미요소가 라주~~~~~많고많아용 여러분도와서 재밌는거랑 맛있는거 드시고요 ㅎㅎ많이구경해 보세용 리뷰는여기까지          여기는 짱짱 추천 맛집ㅎㅎ', 74, 15, 'GOOD', SYSTIMESTAMP);
