INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '홍대 놀러왔다가 들렀어요~ 역시 소문대로 너무 신기하고 이뿌네요~^^ 아이와 유니버셜스튜디오 갔을때가 생각납니다♡ 메뉴가 특별하고 양도 많고 맛있어요^^', 2, 1, 'GOOD', SYSTIMESTAMP);
