INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '컨셉이 너무 신기하고 재미있어요 ㅋㅋ 음료도 맛있고 매장 구경하는 재미가 있어요 위지드버터, 거미스무디 구매했습니다. 위지드버터는 카라멜 맛이 강했고 거미스무디는 쿠키분태가 많아서 좋았어요', 100, 26, 'GOOD', SYSTIMESTAMP);
