INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '도심속의 호그와트네요,,, 인테리어 소품들도 디테일하고,, 테마카페로 즐겁게 가서 즐기면서 놀수 있어 좋아요,, 처음 먹어보는 칠면조 요리도 좋았고요 분위기가 너무 좋아서 사진찍고, 구경하는 재미가 있어요~!!', 53, 17, 'GOOD', SYSTIMESTAMP);
