INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '해리포터를 좋아하지는 않지만! 층층마다 다양한 포토존들도 있고 구경할것도 많았어요~ 가격이좀 비싸지만 메뉴도 특별하고 감성도 듸집니다👍🏻', 10, 0, 'GOOD', SYSTIMESTAMP);
