INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '홍대 매일 지나다니면서 있는줄도 몰랐다가 여행 온 친구가 가고 싶다고 해서 토요일 12:30쯤 방문했어요 저희가 입장할 때는 웨이팅 없었고 나올 때는 웨이팅 있었어요! 앉아서 수다떨고 있으니 마술사 분이 오셔서 카트 마술 보여주셨는데 너무 재밌었어요🤗 해리포터 덕후나 서울 여행 오시는 분들에게 추천합니다', 50, 4, 'GOOD', SYSTIMESTAMP);
