INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '아이들과 함께한 서울여행중 단연최고로 뽑히는곳이었어요 4층에 자리가 없어서 아쉬웠지만 볼거리도많고 음료도 독특해서 어디영화속 탐험한 기분이었습니다 동심의 세계로돌아갔던 좋은 추억이됐네요', 15, 0, 'GOOD', SYSTIMESTAMP);
