INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '사진도 잘나오고 곳곳에 해리포터 느낌 물씬 나게하는 소품들이 많았어요☺️ 음료도 달달하니 맛있었어요~ 음식은 조금씩 비싼감이 없지않아 있었지만 양도 많았고 맛있었어요😊 정말 영화속에 들어온 기분이었어요^^', 35, 2, 'GOOD', SYSTIMESTAMP);
