INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '해리포터 좋아하는 아이와 함께 즐거운 추억 남기려고 방문했습니다~ 각층마다 컨셉이 달라서 둘러보는 재미도 있고, 시그니처 음료도 맛있네요~^^ 다만 가격은 있으니 한번 온거로 만족할듯 합니다ㅋ', 28, 7, 'GOOD', SYSTIMESTAMP);
