INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '해리포터 덕후 아이들과 함께 홍대 방문했다가 들려보았어요 ㅏ단독 건물에 해리 포터로 꽉찬 인테리어가 너무 너무 멋집니다. 해리포터 더쿠라면 꼭 1번 와 보시길 추천 드려요.', 69, 13, 'GOOD', SYSTIMESTAMP);
