INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '음료도 되게 독특하고 용도 윰직여서 깜짝놀랐어요 ㅎㅎ 너무 잘 꾸며져있어서 놀이공원 온 느낌이고 너무 색달라서 좋았습니다!!💗💗', 47, 10, 'GOOD', SYSTIMESTAMP);
