INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '아이가 해리포터 시리즈에 빠져서 찾아왔어요 실내가 놀이동산 온 것처럼 잘 꾸며져 있어서 재미있어요 음료와 디저트도 재미있고 맛도 좋아요^^ 주말의 즐거운 나들이가 되었어요~~', 37, 5, 'GOOD', SYSTIMESTAMP);
