INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '아이 시험보고 홀가분한 마음으로 평소 좋아하던 카페왔어요. 시간이 안맞아어 계속 못 왔는데 오늘은 너무 복잡하지도 않고 좋네요. 고기 맛집이라며 아이들 맛있게 먹었어요.', 39, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '입장료+카페 라고 생각하면 비싼 가격은 아닌 거 같고 만족해요! 아이가 너무 좋아했어요 :) 사람 많지만 테이블 간격이나 매장 자체가 넓어서 붐비는 걸로 힘들진 않았어요. 사진 제법 느낌 있게 잘 나와요!', 18, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '오~칠면조가 너무 맛있어요. 다음에도 칠면조 먹으러 또오자고 하네요~ 음료는 대체적으로 달달하니~ 비오는날 분위기까지 너무 좋으네요.~ 구석구석 테마가 있는 해리포터카페 추천해요. 아이랑 해리포터 이야기 한참할 수 있어요^^', 96, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '오랜만에 가족이 나들이 왔는데, 여기 검색하니까 나와서 왔는데, 생각보다 크고 잘 해 놓은 거 같애요 아이가 조금 더 어렸으면 더 재미있을 것 같애요 한번쯤은 오셔서 경험 해도 좋을 곳입니다🙂', 20, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '구경할 것두 많고 보는 재미 먹는 재미 다 있어요♡ 음식두 맛있구 양 많고 음료도 좋았어요!!! 기대 이상!!! 담에도 꼭 또 올라구요. ☺👍🏻', 39, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '동생이랑 30분 안되게 웨이팅하고 들어갔어요! 지하1층 이용했는데 어둡고 아늑해서 좋았던ㅋㅋ 멘드레이크 머핀이 맛있네요! 위자드버터는 단짠? 느낌에 머랭쿠키가 맛있어요 여러 층 다니면서 보는 재미도 있고 좋았습니다~~', 5, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '아이는 아직 해리포터를 몰라서 마법사 카페 라고 하고 함께 왔어요. 해리포터를 모르는 아이지만 무척 좋아했습니다. 내부 인테리어도 정말 잘 되어 있고 시그니처 메뉴들도 특색있고 맛있어요😋 아이들도 어른들도 모두 좋아할 만한 곳인 것 같습니다👍', 89, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '완전 테마파크같아요. 해리포터 컨셉에 진짜 진심임. 곳곳에 포토존 많아서 사진찍기 좋고 4층까지 있어서 자리도 많았어요. 음료가 비싸지만 카페 인테리어와 분위기를 보면 완전 돈값합니다.', 36, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '인테리어가 해리포터 영화와 똑같아서 해리포터 속에 와 있는 듯 해요! 처음으로 독특한 컨셉의 카페에 와봤는데 좋은 추억으로 남을 것 같습니다', 15, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '#해리포터 카페 #아이와 함께 가족들과 홍대 나들이 추워서 소문으로만 듣던 해리포터 카페에 왔어요.주말 낮이지만 생각보다는 대기가 길지 않았어요.처음이라 시그니처 음식과 음료를 주문했고 좀 비싼듯하지만 입장료 포함이라고 생각하면 합리적인듯...ㅋ사진 찍기 좋고 칠면조 고기는 부드럽고 좋네요.', 9, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '해리포터 좋아하는 아이와 함께 방문했어요 호그와트에 와있는듯한 착각을 일으키가에 충분! 음료 비싼건 방문비용이라 생각할게요^^', 77, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '해리포터를 좋아하는 아이와 함께 방문했습니다. 각 층마다 컨셉이 있고 디테일하게 너무 잘 꾸며져 있어서 카페가 아닌 테마파크에 온 기분이에요. 주말이었지만 생각보다 붐비지 않았습니다.', 48, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '해리포터를 좋아하는 아이랑 다녀왔어요 생각했던것보다 규모도크고 신기한 메뉴가 많아서 즐거웠어요 다행이 대기없이 바로 들어갈수있어서 편하게 있다왔어요!', 36, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '세트메뉴 브런치로 가서 먹었는데 너무 맛있었어요~칠면조는 첨인데 훈제오리?그런 느낌! 살이 엄청 많고 빵에도 올려먹으니 샌드위치처럼 굿!커피도 맛있었구 위자드쇼콜라는 하루 당충전 그냥 완료됨 ㅋㅋ 호프안주로 즐기기에도 좋은 세트메뉴 추천! 포토존도많고 넓은 자리도 있어 모임에도 적당한곳~', 27, 0, 'GOOD', SYSTIMESTAMP);
