INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '저랑 제 친구가 해리포터를 엄청 좋아하는데 너무 즐거웠어요 짱 신기하고 디테일해서 또 오고싶어요!! 음료수랑 케이크도 맛있었어요 너무 특이하고!! 또 오겠습니다 너무 즐거웠어요!!!!!❤️❤️ 강추합니다!!😊', 30, 4, 'GOOD', SYSTIMESTAMP);
