INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '해리포터를 좋아하는 사람한텐 더없이 재밌고 즐거운곳, 메뉴도 독특하고 층별로 다르게 꾸며놓은 인테리어도 재밌는곳,. 직접 의상을 입고 사진도 찍을수 있어서 너무 재밋어', 54, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '해리포터팬인 아이가 정말 좋아했어요!! 음료/음식값에 입장료 포함이고 생각보다 맛있었어요ㅎㅎ 토요일 점심에 대기없이 바로 입장했고요 여러층에 자리가 있어 넉넉했어요. 아이가 다음에 또 오고 싶다네요😍', 65, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '공간이 정말 멋져요!! 해리포터 좋아하시면 방문시에 좋은 추억 가져가실 수 있을 것 같습니당 지나가다 들렀는데 분위기부터가 행복했어요..!! 잘 놀다갑니당!!', 56, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '아이가 해리포터 덕후라서 찾아왔어요. 건물전체가 컨셉되어있고 메뉴 주문후 입장하는거라 대기시간 있었는데 들어오니 자리는 제법있었어요. 그래도 맘에드는 자리 잡고 디저트 즐기며 여기저기 포토존 찾기재밌네요^^', 35, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '외국인분들도 많이오는 핫플이에요 메뉴에 입장금액도 포함이라 가격이좀 있는편 무조건 주문 하고 입장가능합니다 (자리있는지 업는지 미리 확인 불가) 해리포터 안봤어요 애기들이 좋아할거 같아요 거미는 먹는거 아님 ㅋㅋㅋ', 64, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '해리포터 분위기를 정말 잘 재현했습니다. 친구한테 사진 보냈는데 전시회인둘 알았네요ㅋㅋㅋㅋ 음료도 맛있고 가격이 조금 있는데 입장료라고 생각하고 먹었습니다.해리포터 팬이나 특별한 분위기 찾으시면 추천합니다.', 88, 11, 'GOOD', SYSTIMESTAMP);
