INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '해리포터 좋아하면 꼭 가보는거 추천~!! 영화에 나왔던 소품이나 장면을 볼 수 있어서 좋아요 층마다 분위기가 다르고 해리포터 노래가 계속 나와서 흥얼거리면서 친구들과 영화이야기를 많이 했어요ㅎㅎ 영화에서 봤던 케이크도 직접 먹어봤는데 영화에서도 이런 맛이였겠지?! 생각하며 맛있게 먹었어요~ 음료에 올라간 저 초코모자 너무 귀여운데 딱딱해서 조심히 먹으세요 맛은 딱 생각했던 그린티라떼랑 초코라떼에요~ 9와 4분의 3 승강장은 왜 없나하고 아쉬웠지만 다른 즐거움이 있어서 행복한 날이었어요🩷🩷🩷', 27, 7, 'GOOD', SYSTIMESTAMP);
