INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '우연히 지나가다 보고 아이가 좋아할것같아 찾아 방문 했습니다~ 해리포토룰 좋아하시는 분들은 너무나 맘에 드실듯요~  아이가 좋아할만한 음료도 케이크도 잇어서 보는재미 먹는재미가 쏠쏠하네요~  양이많아서 다 먹지못하고 많이 남겨서 너무 아까운디 포장이 안되서 좀 아쉽네요 ㅠ 담엔 다른메뉴 도전하러 오겠습니댜^^', 78, 15, NULL, SYSTIMESTAMP);
