INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '이런 곳을 이제 알았다니!!!이제 막 해리포터에 빠진 아이와 함께 왔더니 너무 좋아요~^^ 주말 이른 아침에 왔더니 붐비지 않고 사진도 많이 찍어 갑니다~', 29, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '이색적인 테마가 있는 홍대카페예요 해리포터를 좋아하는 아이와 함께 방문했어요 음료도 진하고 맛있었고 신비롭고 아늑한 분위기에 사진찍기도 좋았어요 직원분들도 친절해서 더욱 만족했습니다 아이는 친구와 같이 또 방문하고 싶어했어요', 8, 9, 'GOOD', SYSTIMESTAMP);
