INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '이색적인 카페예요ㅎㅎㅎ 팝업도 아니고 건물이 전부~~ 컨셉 확실하고 아이들이 즐거워해서 돈안아까웠어요 ㅋㅋㅋ 해리포터 좋아하는 사람들은 한번쯤 와볼만한곳이어서 추천합니당!!', 98, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '사진으로만보다 실제로와보니 놀이동산에온 기분이 들어요 음료도 귀엽고 맛도 있어요 커플이나 어린자녀를 둔가족 분들께 방문추천 해요😄', 14, 5, 'GOOD', SYSTIMESTAMP);
