INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '아이가 너무 좋아하네요..ㅎㅎ 해리포터를 보진 않았지만 워낙 들은게 많아서 모르는데 알것같은 느낌적인 느낌?!ㅎ 그냥 모르고 봐도 신기하고 특이하고 재밌어요..^^ 음료가 맛있어서 더 좋네요~~ㅋㅋㅋ', 35, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '해리포터 덕후라 여행 계획 짤때 무조건 넣은곳이에요 웨이팅이 있긴 했지만 20분 이내였고, 생각보다 음료랑 케이크도 맛있었어요!! 사진찍기도 좋고 넘 맘에 들어요!! 담에 서울 오면 또 들를거에요 :)', 22, 4, 'GOOD', SYSTIMESTAMP);
