INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '해리포터를 좋아하는 아이들에게는 최고의 장소에요! 음료도 맛있고 음식도 맛나고 재미있어요^^ 평일이라 조용하고 아늑하게 너무 좋은 시간을 보냈답니다', 37, 10, 'GOOD', SYSTIMESTAMP);
