INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '공간마다 재밌는 요소가 있어 아이데리고 즐거운 시간 보냈습니다아~ 흘러나오는 노래와 영화를 봤다면 반가운 인테리어들이 즐거워요. ^^', 4, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '아이들이 해리포터를 너무 좋아해서 꼭 한번 와야지 했는데 ~ 오길 잘 한 것 같아요! 4층까지 있어서 자리도 많고 음료메뉴도 다양하고 볼거리가 많아서 사진 찍기 너무 좋았어요! 음식도 맛있어서 나오자마자 먹어버렸네요 ^^', 25, 2, 'GOOD', SYSTIMESTAMP);
