INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '이런걸..해리포터 카페라고 하는건 좀 아닌거같아요 전날 대기 엄청 하길래 궁금해서 다음날 오픈런 했어요. 다행히 대기는 없어서 바로 들어올 수 있었지만 진짜 내부와 음료는 실망 그 자체입니다 광고 엄청 때렸나보네요.. 음료도 그냥 평범하고 맨드레이크 케이크도 그냥...ㅋㅋㅋㅋㅋㅋ.....ㅋㅋㅋㅋㅋㅋ웃겨서 웃음만 나옵니다 그냥 경험했다 생각하고 가려고요...^^;;;;;', 37, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '해리포터 좋아하는 친구따라서 왔어요~ 입장료 포함이라 가격이 사악하지만 특별한 장소인것 같아요:) 잘꾸며놓은 것 같아 외국인들도 많아요~', 7, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '해리포터 덕후… 재밌게 즐기다 갑니당🧙‍♀️국내에서 이렇게 해리포터를 즐길 수 있는 공간이 있다니 너무 감격스럽습니다. 디저트도 귀여운 거 투성이고ㅠㅠ 돈만 많다면 다 먹어보고 싶네요…❣️구경할 거리도 너무 많구 해덕이라면 무조건 무조건 추천입니다. 평일에 와서 자리가 널널했어요👍 안에 포토존도 많고 망토 입고 인생네컷 찍을 수 있는 공간도 있어요🥺 서울에 살면 여긴 주기적으로 올 듯해요ㅠㅜㅠ 담에 여행 오면 또 올게요. 혼자서 너무 힐링하고 갑니다!!!! 그리핀도르 파이팅~~🧹', 32, 1, 'GOOD', SYSTIMESTAMP);
