INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '해리포터 덕후 아이들 위해 방문했어요 음료도 특이하면서 맛있어요 아이들과 특별한 추억 쌓기에 최적인듯~!! 즐겁게 놀다갑니다~~', 33, 7, 'GOOD', SYSTIMESTAMP);
