INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '매장의 컨셉이 정말 독특하고 음식도 진짜 맛있어요. 특히 칠면조 고기가 신기하네요.인테리어도 멋있고 매장도 넓어서 쾌적했어요. 매뉴도 종류가 다양하고 신기해서 다음에 또 올것같아요^^ 저희 아이가 해리포터를 좋아하는데 여기 오니 정말 좋아 하더라고요ㅋ 정말 맛있었고 좋았습니다. 여긴 무조건 추천이에요. 다음에 또 올게요! 최고~', 56, 18, 'GOOD', SYSTIMESTAMP);
