INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '아이가 해리포터에 빠지면서 오게됐어요 평일에 와서 그런지 붐비지않고 공간이 여유있어 좋았어요 음식은 사실 많이기대안했었는데 상당히 맛있게먹었어요 보기에만 예쁠줄.알았는데 고기도 맛있고 거미스무디도 많이 달지않고 맛있었습니다~', 114, 24, 'GOOD', SYSTIMESTAMP);
