INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '홍대입구역 근처 이색카페 943킹스크로스 카페 방문했어요!! 해리포터를 컨셉으로 지하 일층부터 사층까지 으리으리하게 꾸며놨어요~ 영화를 처음 봤을때 감동을 실제로 보고 느낄 수 있는 곳이에요🥹 음료나 디저트 마법학교에 나올것 같은 재미나고 개성있는 비주얼이에요👏🏻 보는 것만으로도 만족스러워요😆 마술공연까지 진행한다고 하니 아이, 친구, 연인과 함께 오기 좋은 공간 같아요👍🏻 홍대 943킹스크로스카페 추천이에요♥️', 18, 7, 'GOOD', SYSTIMESTAMP);
