INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '주말에 마술쇼도 하고 포토존도 다양해서 좋아요 4층은 옷도 있어서 입어보고 사진찍을수 있어 좋고 특이한 음료 메뉴가 있어 재미있어요', 24, 4, 'GOOD', SYSTIMESTAMP);
