INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '해리포터 인테리어 너무 멋집니다. 아이가 해리포터 좋아해서 방문했고, 너무 좋아했습니다.음료도 찐해서 맛있고,, 완전 호그와트학교 컨셉이라 만족도 최고입니다☆', 186, 47, 'GOOD', SYSTIMESTAMP);
