INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '해리포터 덕후라면 좋아할 카페. 음료도 독특하고 노래도 해리포토영화 음악과 인테리어도 해리포터 영화속 기숙사와 연회장느낌이라 좋았습니다.', 34, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '칠면조다리너무맛있고  ㅋ 너무멋있게잘꾸며놔서 좋았어요ㅎ 아이가 해리포터책을다읽고와서구경해서  더재미있었네요ㅎ위저드버터너무맛나요!!꺄', 54, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '해리포터 진짜 좋아해서 예전부터 오고싶었는데ㅠ 음식들 역시 기대를 저버리지 않고ㅠ 인테리어도 4층까지 있는데 호그와트에 와있는거 같아요ㅋㅋㅋ 직원분들 바쁘신데도 친절하고 영어도 하시더라구뇨? 엄청난 능력자들… 사람 많아서 연회장에 있었는데 너무 편하고 좋았습니다!!! 인스타에 사진 왕창 올릴라구요!!', 27, 3, 'GOOD', SYSTIMESTAMP);
