INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '해리포터를 배경으로 너무 멋지게 꾸며져있어서 볼거리가 많아요 음료수도 다맛있구 해리포터좋아하시면 꼭들러보면좋을것같은 카페네요~강추입니다', 78, 18, 'GOOD', SYSTIMESTAMP);
