INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '드래곤 플레이트 궁금해서 시켰어요. 고기가 엄청 크고 배불러욬ㅋㅋ 맛있더라구요. 마치 호그와트 급식 먹는 느낌??? 파인애플 있는 게 좋았어용ㅎㅎ 음료도 위자드 녹차 맛있어요.💚 연말 데이트로 딱입니다~!!', 0, 7, 'GOOD', SYSTIMESTAMP);
