INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '해리포터 컨셉이라 호기심에 방문했는데 매장도 넓고 층마다 인테리어가 달라서 사진 찍기 좋아요! 막찍어도 사진이 예쁘게 나오네요!', 128, 20, 'GOOD', SYSTIMESTAMP);
