INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '지방에서 놀러온 친정식구들과 함께 놀러왔는데 어른부터 아이까지 모두 즐거워하네요. 해리포터를 제대로 안 본 사람들도 추억 남기기 좋고,  특별한 음료랑 디저트 사먹는 재미가 있어요', 22, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '해리포터를 엄청 좋아하는 조카와 방문했어요 평일에 방문해서 제일 인기자리라는 기숙사층 침대자리에 앉아 먹었어요 꾀병스무디 11,800원 아메리카노 10,000원 맨드레이크 14,000원 젤리빈         3,000원 주문했어요 꾀병스무디는 조카가 먹고싶다고해서 시켰는데 젤리가득 비주얼 굿 뽕따녹인 맛_그렇지만 너무달아 거의 못마심 조카는 젤리가득이라 완전 신나함 생각보다 커피가 너무 맛있어서 비쌌지만 만족 기숙사 옷 걸치고 사진찍기도 가능 조카가 너무 신나해서 진짜 추운 날에 칼바람이였지만 같이한 시간 너무 소중했어요', 40, 0, 'GOOD', SYSTIMESTAMP);
