INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '해리포터 영화 속에 들어온 것 같아요~ 인테리어 정말 멋져요!!! 해리포터 정말 좋아하는 아이들에게 최고의 추억이 될 듯 하네요~ 음료도 맛나요!!', 35, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '들어오자마자 해리포터 분위기 짜잔이에요! 식음료는 다소 비싼 감은 있지만 친구들이 해리포터 좋아해서 다들 좋아했어요! 음료는 굉장히 달아요. 한 입에 혈당 풀충전되는 맛이에요', 4, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '요즘 핫한 헤리포터 카페 아이랑 방문하기 너무 좋아요^^ 특색있는 음료랑 사진 찍기 좋은 핫플 입니다^^ 층마다 테마가 틀려서 구경하기 좋아요^^ 5.6층 개방을 안해서 조금 아쉬웠답니다~~~', 14, 8, 'GOOD', SYSTIMESTAMP);
