INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '독특해요 해리포터 좋아하신다면 꼭이요 나름 코너코너 새심하게 꾸며놓았어요 메뉴들도 다른곳에 없는메뉴하 너무 기분전환되고 좋았어요', 36, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '주말 나들이로 왔는데 정말 멋지네요~ 아이들뿐만 아니라 저희부부도 눈이 희둥그레지고 음식도 너무 맛있고 볼거리가 한가득이네요~ 해리포터를 좋아하는 분들에게 진짜 강추입니다~~!!ㅎ', 38, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '#영수증리뷰#젤리빈증정#review event#jelly bean present 해리포터덕후 딸이랑왔는데 음료도맛있고 분위기기 너무 홀릭이네요~ 담에또올께요', 91, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '해리포터 덕후는 웁니다..인테리어가 진짜 해리포터 세상에 온거같아요..ㅠ 구경거리도 많고 사진찍을거리도 많으니 꼭 꼭 오세요! 특히 B1~4층마다 인테리어컨셉이 다 다르고 볼거리 많은게 너무 좋았어요ㅠ 침대에 앉아서 먹으면서 해리포터bgm까지 나오니까 진짜 기숙사에서 먹는 것 같았어요ㅋㅋㅋ 자리에서 마술쇼까지...ㅠㅠ 재밌게 놀았습니당 다음에 또 올게요🍀❤️', 47, 8, 'GOOD', SYSTIMESTAMP);
