INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '서울여행와서 독톡한 곳이 없을까 찾다가 온 곳이에요. 포토존이 많고 컨셉에 충실하게 비주얼이 예쁜 음료와 케이크들이 있어서  좋았어요.', 1, 7, 'GOOD', SYSTIMESTAMP);
