INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '검색하는데  많이 떠서 신기해서 와봤어용 가격대가 좀 있긴한데 한번쯤은 와볼만한것같아용 볼거리도많고 자리도 6층까지 있는데 널찍합니다', 36, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '한 번 쯤 방문해봄직한 곳이에요! 음료 주문해야 입장 가능이고 지하1층~4층까지 다른 컨셉이어서 둘러보는것도 좋아용 위자드 쇼콜라는 빠삐코 맛이에요', 88, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '아이가 전부터 오고 싶다고 했던 곳인데 이제야 방문하네요 눈도 즐겁고 입도 즐거운 시그니처 매뉴!! 일요일 오후엔 마술공연이 있다는걸 모르고 왔는데, 운이 좋았네요~ ^^ 아이와 기분 좋은 데이트 잘 하고 갑니다.', 24, 3, 'GOOD', SYSTIMESTAMP);
