INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '오사카 해리포터 테마파크 온 느낌이예요😆 건물도 크고 편안하게 쉬다 가도 좋아요 곳곳에 사진찍을곳 많아 좋고 배경음악도 웅장해서 가격대비 깨알 시간보내기 좋습니다👍 버터맥주와 음료는 쏘쏘하지만 입장비 포함한다하면🤔 강추합니다', 74, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '어린이날 웨이팅은 한시간 반 걸렸지만! 아이들이 너무 좋아해서 ㅎ 다행이네요 그리구 음료수도 너무 이쁘게.나와요 웨이팅 없는 날 꼭 한번들 오세요!', 42, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '해리포터 영화의 장면들이 떠올라요~ 모자모양의 머랭쿠키도 멋졌고 먹기 아까웠어요ㅠ 층마다 분위기가 달라서 보는 재미가있습니다!!', 39, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '평택에서 여기볼려고 기차타고 버스타고 왔네요 너무 만족합니다. 인생 살면서 죽기전 한번은 와야할곳이네요  10시반 오픈때왔는데 금방 사람들 몰려오네요', 28, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '장점: 인상적인 인테리어와 해리포터를 연상시키는 메뉴들 단점: 너무 단 음료, 정리되지않는 반납테이블 테마파크처럼 잘 조성되어있는데 재방문할 생각이 안드는게 아쉬워요', 6, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '아이랑 둘이 갔는데 일단 애들이 많아요. 아무래도 컨셉이 해리포터다 보니까 가족 단위로 많이 찾아오시더라고요. 메뉴는 그냥 정해져 있는데 조금 느끼하기는 합니다. 음료는 너무 너무 달아요. 그냥 분위기 보고 사진 찍고 놀다 오기 좋아요. 한 번 정도는 가볼 만 합니다. 메뉴가 막 생각나는 그런 맛은 아니에요. 그렇지만 데이트 코스나 아이와 가기에는 정말 좋은 장소예요.', 50, 9, 'GOOD', SYSTIMESTAMP);
