INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '서울 여행 온 시골쥐들ㅎ 해리포터 좋아하는 아이들을 위해 함께 방문~~ 시그니처 음료와 음식은 필수 !!!! 주말 방문이였는데 웨이팅도 많이 길지 않아서 좋았던 곳', 36, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '해리포터에 관심있는 아이들과 같이 왓어요 꾀병 스무디는 아이들이 좋아할만한 메뉴에요 케잌도 맛잇고 해리포터 망토입고 사진도 찍고 좋네요 다음 재방문의사있습니다', 11, 6, 'GOOD', SYSTIMESTAMP);
