INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '타지에 거주 중인데, 해리포터 좋아하는 친구랑 943킹스크로스에 함께 오고 싶어서 벼르고 벼르다 드디어 오늘 방문했어요. 그만큼 기대치가 높았는데 건물 외관부터 만족감 943퍼센트였어요! 건물로 들어서는 순간 마법세계로 잠시 들어온 것 같은 기분이 들었습니다. 해리포터ost와 신비한동물사전ost가 흘러나오는 것도 좋아요. 사실 컨셉이 너무 훌륭해서 음료까지 기대하진 않았는데 주문한 위자드쇼콜라아이스도 맛있습니다. 기숙사 테이블에 앉아서 음료 마시다 보면 호그와트 교수님들 만날 것 같은 기분이에요ㅋㅋㅋ 또 방문하고 싶어요!', 22, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '아이가 해리포터를 좋아해서 방문했는데 분위기가 너무 좋네요. 층별로 다양한 컵셉이 있어 좋고 특색있는 음식메뉴와 음료,케익이 있어 아이들과 함께 오기 좋습니다. 주말에는 마술쇼까지해서 최고네욧👍 해리포터 덕후들은 꼭 와보면 좋을 것 같습니다.😍', 46, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '분위기 음침하니 해리포터 영화 같아요 아이들이 좋아하고 어른도 좋아요 인테리어가 정말 맘에 들어요 사진으로 꼭 남기고 싶은 곳이에요', 7, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '아이가 해리포터 너무 좋아해서 찜해두고 있다가 드디어 왔어요. ㅎ 분위기 너무 좋고 소품들도 멋져서 신나게 구경했어요. 홍대 오면 또 올게요! 😊', 40, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '해리포터 좋아하는 사람이라면 꼭 추천이요 애들이 좋아할 달달한 특별메뉴도 있고 어른을 위한 버터맥주도 있어요 진짜 맥주 맛 좋아요! 사진도 잘나옵니닷', 48, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '해리포터 좋아하는 아이와 여름방학에 오고 또 오고 싶다고 해서 겨울방학에 왔습니다!! 인테리어도 소소하게 바뀌고 내부도 더 깔끔해지고 좋네요!! 음식도 비싼것같지만 식사 및 관람료라고 생각하니 좋은 추억도 쌓을수있고 좋아요^^', 21, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '되게 독특한 분위기에요 어둡구요 각 층마다 컨셉이 다 달라요 어디서 먹어야 하나 고민 많이 했어요 ㅋㅋㅋ 음식을 먹으러가는것 보다는 ..... 독특한 카페 찾으시면 방문하길 추천이요 버터맥주는 맛있었어요 저희가 간날은 한국인보다는 외국인이 90퍼 였어요', 39, 5, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '엄청 크고 컨셉이 확실한 카페였어요 음료랑 베이커리류가 비싼편이지만 공간을 즐길만한 규모라 입장료가 포함되어 있다고 생각하면 납득이 가는 수준 외국인이 무척 많았고 한번쯤 가볼만한곳이지만 두번은 안갈거같아여 ㅋㅋㅋ', 123, 25, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '해리포터 컨셉으로 꾸며놓은 카페라고해서 와봤는데 층마다 컨셉도 다 다르고 소품들도 아기자기하게 잘 꾸며놨더라고요!ㅎㅎ 구경하고 사진찍기 좋았어요~ 음료랑 디저트도 컨셉에 맞춰져 있더라고요ㅎㅎ 위자드 그린티는 말차프라프치노에 쿠키분태가 올라가 있는 음료였는데 쿠키가 생각보다 많이 올라가 있어서 씹는맛이 있더라고요! 디저트도 괜찮아서 해리포터 좋아하시는 분들은 오시면 좋아하실거 같은 카페였어요😊', 82, 15, 'GOOD', SYSTIMESTAMP);
