INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '해리포터소설 속에 들어와 있는 것같았어요. 외국인손님들도 꽤나 있었고, 층마다 컨셉이 달라서 구경하는 재미도 있어요. 음료는 엄청 달달해서 당충전은 150%됐어요!', 26, 8, 'GOOD', SYSTIMESTAMP);
