INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '아이가 해리포터에 빠져서 오늘 홍대 해리포터 카페에 다녀왔어요~ 사진 찍을 수 있는 곳도 많고 마법주문도 직접 외워보면서 여유롭게 즐기고 왔습니다 ^^다음에 또 오고 싶어요^^', 76, 17, 'GOOD', SYSTIMESTAMP);
