INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '해리포터에 빠진 아이들과 나들이 왔어요. 아이들이 너무 너무 좋아하네요.. 카페 곳곳이 포토 스팟이고, 음료도 너무 독특하고 멋있게 나와서 좋아요', 37, 4, 'GOOD', SYSTIMESTAMP);
