INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '아이들과 재밌는 경험이었어요 예약없이 30분정도 기다렸으나 실내에서 기다려 춥지않았고, 구경하며 있어서 금방차례가 온듯해요 음료가 다 달아서 어른들은 달다...했지만 음료 컨셉이 귀엽고 아이들도 재밋어햇어요 ㅎㅎㅎ', 83, 15, 'GOOD', SYSTIMESTAMP);
