INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '아이와 예전부터 와보고 싶었는데 오늘 드디어 방문했어요ㅎ 인테리어도 멋있고 음료도 넘 맛있어요ㅎ 해리포터속에 와있는듯해요 다음에는 와서 음식들도 먹어보려구요ㅎ', 25, 1, 'GOOD', SYSTIMESTAMP);
