INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '아이가 해리포터를 너무 좋아해서 방학에 마음 먹고 왔는데 너무 만족하고 갑니다 갑니다~직원분들도 친절하시고 음료도 너무 맛잇어요~', 78, 13, 'GOOD', SYSTIMESTAMP);
