INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '근처 카카오프렌즈에서 해리포터 콜라보 제품고르고 바로 달려왔어요~~ 아이들과 포션 3종 먹으면서 행복한 시간 보내고 있습니다. 2번째 방문인데 인테리어가 또 바뀌어서 바뀐 혼테일보고 놀라기도 하고 색다르네요. 층별 다양한 느낌 잘 즐기고 갑니다', 50, 0, 'GOOD', SYSTIMESTAMP);
