INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '아이들이랑 같이 왔는데 너무 좋아하네요 가운 입고 빗자루 들고 사진 찍으니 너무 즐거워해요 시간 가는줄 모르고 사진 열심히 찍고 즐기다 갑니다^^', 32, 3, 'GOOD', SYSTIMESTAMP);
