INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '신기한메뉴도 많고 볼것도 많아서 너무 좋았어요!! 메뉴가 가격대가 있지만 너무 잘해놔서 만족이였어요! 다음번에 또 오고싶어요! 사진도 잘나오고 인생네컷은 꼭 찍으세요!!!!엄청 잘나와요😆', 15, 4, 'GOOD', SYSTIMESTAMP);
