INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '홍대에 이색데이트 코스로 해리포터를 좋아하는 사람이라면 한번쯤 와보기 정말 좋을 거 같아요! 인테리어도 해리포터 느낌이 물씬 나고 소품도 다양하고기숙사 로브도 입어볼 수 있어요 메뉴들도 개성있고 거미스무디랑 버터맥주를 먹었는데 버터맥주는 흑맥주+달달한 크림 조합입니다 그리고 버터맥주 위에 휘핑크림은 절대 섞어 먹지마세요 그냥 먹는 게 더 맛있어요👍', 26, 8, 'GOOD', SYSTIMESTAMP);
