INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '나름 분위기는 잘 꾸며놓은거같아요! 잼민이 아들은 너무 좋아합니다. 하지만 군데군데 의자가 낡아서 삐꺽거리고 쿠션이 없어서 엉덩이가 빠지는 의자들이있어요. 재미있는 요소라고 생각했습니다ㅋㅋㅋ', 5, 7, NULL, SYSTIMESTAMP);
