INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '아이와 함께 주말 나들이로 해리포터 카페로 유명한 943 킹스로드카페를 찾았어요. 음료도 맛있고 8살아이도 즐거워하고 4층 침대모양 좌석은 아이들과 다리뻗고 앉아 쉴수 있어 너무 좋아요. 주말엔 마술쇼도 볼수있어 아이와 함께 데이트로는 최고네요👍👍', 43, 4, 'GOOD', SYSTIMESTAMP);
