INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '해리포터 인테리어 분위기에 음악이랑 음료까지 전부 마음에 들어요!!ㅎㅎ 층별로 둘러보고 사진 찍는 재미가 쏠쏠합니당~ 다음에도 또 오고싶어요!', 22, 0, 'GOOD', SYSTIMESTAMP);
