INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '부산에서 명절연휴로 검색하고 찾아왔어요 분위기 케이크 음료 다 너무 좋았어요 지인들한테 추천해야겠어요😍 초6아들이 너무 좋아합니다', 0, 4, 'GOOD', SYSTIMESTAMP);
