INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '예비 중1 아들내미랑 초등 졸업 서울 여행 메인 스케쥴이었습니다. 해리포터 대백과 책까지 들고 방문했네요.~~~^^  음식~~도 맛나고 ~~  음료도 아이들을 사로잡네요~~  달콤한 크림 맥주도 훌룡합니다.', 82, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '아이가 요즘 해리포터에 푹~~빠져있어서 찾아보니 이런 이색카페가 있더라구요~~ 카페 앞에 빗자루를보더니 아이는 엄청 설레어하며 벅차하더라고요 ㅎㅎ그렇게나 좋을까~ 컨셉에 맞는 음료도 여러 소품들도 엄청납니다👍', 95, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '해리포터에 대해서 잘 모르는 저도 마법의 세계같은 이 카페에 빠져들었어요! 케이크와 음료수도 달달하니 넘 맛있고 중간중간 포토스팟도 있어 사진 남기기도 너무 좋아요. 잘 즐기다 갈게요~', 129, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '아이들과 함께 왔어요!! 해리포터 영화 덕후 라면 무조건  와야해요. 아이가 진심 좋아합니다. 인테리어 뿐만 아니라 영화속  세세한 소품들까지 있어서 즐길거리 잔뜩이예요. 포토존 많네요.', 25, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '포토존이 마련되어있어서 즐거운 시간 보냈습니다. 층마다 볼거리가 많아서 해리포터 좋아하시는 분들 꼭 와보셨으면 좋겠습니다. 재방문 의사 있습니다!', 20, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '해리포터 덕후라면 가봐야 할 카페에요! 4층까지 있어서 볼 거리도 많아요! 입장권(?)까지 포함된 가격이라 음료나 메뉴들 가격이 좀 센 편이긴 한데 볼 거리가 많고 사진 찍을 곳도 많아서 괜찮습니다! 4층에 해리포터 옷도 입을 수 있고 사진 찍는 기계도 있는데 필름 카메라 같은 형식으로 잘 나옵니다ㅎㅎ! 해리포터 옷 입고 찍으면 좋아요! 음료는 시그니처 같아 보이는 위자드그린티, 위자드쇼콜라, 위자드버터로 시켰습니다. 비주얼은 다 해리포터스럽고 이뻤어요! 위자드그린티는 단 말차음료인데 묵직하고 생각보다 맛있었어요! 위에 초콜릿으로 된 모자 토핑과 초코크런치들도 있어서 더 좋았어요! 위자드버터는 버터스카치 캔디 맛입니다! 해리포터를 좋아하시면 이색적인 카페로 943 킹스크로스 카페 한 번 가보시길 추천드려요☺️', 34, 3, 'GOOD', SYSTIMESTAMP);
