INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '가보고 싶었던 해리포터카페! 잘 꾸며져 있네요. 아늑하고 분위기 있어요. 음료도 예쁘고 층마다 구경하는 재미도 쏠쏠합니다. 평일인데 사람도 많네요.', 19, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '아이생일이어서 방문했어요~ 주말이어서 마술쇼도 보고 해리포터 덕후인 딸이 너무 행복해했어요~ 멀리서 방문했는데 온가족이 즐거운 시간이었어서 너무 만족해요~', 49, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '분위기 맛집이에요. 주말에 외국인분들도 많고 대기도 많네요. 음료도 맛은 없지만, 컨셉 하나는 확실해서, sns에 올리기 좋네요.', 73, 12, 'GOOD', SYSTIMESTAMP);
