INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '신기한 메뉴들이 많아요! 영화속 공간에 온 기분이들어서 너무신나고 재밋네요!! 층별로 컨셉도 확실하고 재밋어용 Very excited 😊 🤗 🤪', 64, 12, 'GOOD', SYSTIMESTAMP);
