INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '아이가 해리포터 너무 좋아해서 와봤는데 아주 좋아하고 음료도 귀엽고 직원분들도 친절하세요ㅎㅎ 토요일 오후에 와서 대기는 좀 했지만 와볼만해요!', 9, 2, 'GOOD', SYSTIMESTAMP);
