INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '여기 디테일 짱이에요.. 해리포터 덕후면 꼭 와볼만함 메뉴들이 가격대가 있긴한데 신기한 데코도 있고 그래서 돈이 전혀 안아까웠음 칠면조 다리도 유니버셜꺼보다 큼 그리고 주차도 괜찮은게 근처에 주차하면 싸게해준다면서 두시간 금액만 주고 새벽2시까지 놀다가라는 아조씨가 주차장을 운영하심 여기 주차하면 바로 앞이라서 여기저기 돌아다니면서 구경하기 좋고 카페 네이버리뷰쓰면 젤리빈이나 초콜렛줘요ㅋㅋ뜯어보니까 왕귀욤🥸', 11, 8, 'GOOD', SYSTIMESTAMP);
