INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '아이가 해리포터광팬이라 인천에서 와봤어요 주차가 아쉽지만 아이가 너무 좋아했어서 뿌듯해요 좌석이 협소해 주말에는 자리잡기 힘들겠어요 비싼가격같지만 또 그렇지도 않네요 잘놀다 가요', 40, 6, NULL, SYSTIMESTAMP);
