INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '아이와 함께 가볼만한곳 찾다가 발견한 곳이에요~ 아이와도 연인과도 가족과도 함께오기 좋은곳 이네요~ 컨셉도 독특하고, 사진 찍기도 좋네요~ 지하부터 4층까지 자리도 넓습니다. 다만 인기있는 자리는 사람 많을땐 없을거 같아요~ 베스트 메뉴 주문했는데, 칠면조 왕크네요~ ㅎㅎ 잔뼈가 많아 조심히 먹어야하고, 뼈가 크네요~ 같이 나온 파인애플은 안익은거라 아삭하고, 시고,  아쉬웠어요~  ㅜㅜ 음료는 둘다 맛있었어요!!^^ .', 39, 3, 'GOOD', SYSTIMESTAMP);
