INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '사람은 많았는데 내부가 예쁘게 잘 꾸며져있어서 좋았어요! 음료 값이 비싸긴한데 입장료 포함이라서 한 번쯤은 오기 좋은 카페인 것 같아요✨', 5, 3, 'GOOD', SYSTIMESTAMP);
