INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '해리포터에 뒤늦게 빠진 아들데리고 왔는데 제가 신이났어요 해리포터의 깨알같은 디테일 다살려주고 음식도 기대안했는데 보기에도 이쁜데 맛도 좋아요♡그리고 너무 친절하세요 담에 또올게요', 103, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '해리포터 좋아하는데 안가볼수가 없죠🤩 지하1층부터 4층까지만 오픈되어있고 5층,6층은 출입이 불가해요.. 우린 머글이니까요🥲 칠면조다리는 필수로 시키셔야해요😉 묵직하면서 오리고기 맛이 나고 쫄깃하고 양 많아요😚 이번에 맨드레이크 케이크 새로 나왔다해서 주문했는데 너무 귀여워요😘 초코컵케이크에 맨드레이크 쿠키 꽂아져있는데 완전 고퀄리티,, 음료도 음식도 컨셉이 완벽한 이곳 추천드려요🫶 외국인 방문객들도 많고 층마다 컨셉도 달라서 구경하는 재미가 있어요🥰 포토존도 있고 굿즈에 눈돌아가는거 겨우 참았어요🤭 건물 밖에 큰 빗자루에서도 사진찍는거 잊지말기🧙‍♀️', 10, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
