INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '아이와 홍대 데이트 왔는데 이색 카페가 있다고 해서 와봤어요^^ 배가 고파 음식과 음료를 같이 주문했는데~ 비주얼만 좋은 줄 알았는데 맛도 상당히 좋습니다 아이와 싹싹 다 비우고 왔네요^^ 음료도 아이들이 좋아할 맛으로 저렴한 맛이 아니에요 사진 찍을 곳도 많아서 이쁘게 아들과 사진도 많이 찍고 음식도 음료도 아주 맛나게 먹고 갑니다 다음에 홍대에 들리면 또 방문할 것 같아요^^', 1, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
