INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '아이가 해리포터를 좋아해서 두번째 방문입니다. 새롭게 괴물모형이 설치되어있네요 지하는 무섭다고 안들어가고 4층부터 시작해서 옷입고 사진찍고 재미있게 놀다갑니다. 인테리어비용이라 그런지 음료는 금액이 좀 나갑니다. 입장료 포함이라 생각해야할듯요.', 102, 19, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '홍대에 있는 해리포터카페에요! 위자드그린티를 주문했는데 맛있었어요! 입장료까지 포함되어있는 가격이라 음료가 11,800원으로 비싸지만 구석구석 구경하고 사진찍을 곳이 많아서 좋았어요👍🏻', 8, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '943 킹스크로스'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '해리포터를 좋아하시고 홍대입구에서 이색카페를 찾으신다면 해리포터 컨셉의 943 킹스크로스는 꼭 와보셔야 한다고 생각해요! 음료뿐만 아니라 메뉴들도 너무 맛있어서 한번쯤은 무조껀 방문해야한다고 생각하는 카페랍니다!!!! 다양한 컨셉의 해리포터 카페를 구경하면서 즐거운 시간 꼭 보내보세요~!', 18, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '여기 까페 분위기 깡패! 여기 디저트 환상의 맛!! 달콤한 맛 좋아하시면 지지 초코 무스 추천합니다~ 달아요 음청 달아요 ㅎㅎ 유명한 바다라떼는 그냥 먹어도 맛있는 솜사탕이 음료랑 녹여먹으니 더 맛나네요~~ 지지머그타르트, 초코라즈베리 번트는 많이 달지않고 먹기 좋습니다. 라벤더라떼는 생각보다 양이 적은 편인데 라벤더 향이 은은하게 풍겨 감미롭네요~ 복숭아라떼는 마시는 순간 복숭아 맛과 향이 입안에 풍깁니다. 카페의 디저트는 뛰어난 맛보다 귀여운 디자인에 혹하게 되네요 ㅎㅎㅎ 굿즈샵 구경하는 재미도 솔솔~~ 토요일 주말 오후 4시쯤 방문했는데 약 10분 기다리고 들어왔어요~ 지브리 분위기만으로도 기분 좋아지는 카페!!', 33, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '지브리를 좋아하는 1인으로 전부터 가보고 싶었는데 이제야 왔네요 입구부터 이쁘고 힐링 그 자체네요 굿즈숍이 있어서 눈 돌아가는데 디저트는 또 왤케 이쁘고 난리인지...!!! 굿즈쇼핑도 하고 맛난 디저트도 먹으니 너무 좋아요 지브리음악이 계속 나오니까 그것도 너무 좋고~ 지브리 좋아하는 분이면 무조건 오세요', 23, 5, 'GOOD', SYSTIMESTAMP);
