INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '세 번째 방문이에요!!! 지브리 수혈 필요할 때 찾게되는 곳 …💖 메뉴도 다양해서 올 때마다 다른 메뉴 먹어보는 재미도 쏠쏠해요👍🏻', 186, 58, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '딸과 람께 연남동 데이트 나왔다가 찾아보고 들어욌어요 디저트가 너무 맛있어요 딸이 말차라떼 좋아하는데. 말차맛이 진해서 만족해하네요 들어오는 입구부터 분위기가 완전 내스타일이네요 창가에 앉았는데 마당에 초록뷰가 좋습니다', 44, 3, 'GOOD', SYSTIMESTAMP);
