INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '드디어 오게 되었어요! 인테리어 너무너무 이쁘고 계속해서 흐르는 키키ost 때문에 눈물 찔끔 했어요!! 숨겨진 디테일이 너무 좋은 카페에요! 키키 팬이면 진짜 100번 추천해요!!', 31, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), 'We really enjoyed the unique Ghibli-themed menu items and gift shop at Koriko Cafe! The atmosphere is super cute as well. Great for any fans of Studio Ghibli, Kiki’s Delivery Service, or cute cafes.', 11, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '친구하고 여행하면서 꼭 가고싶던 곳 중 하나였는데 무사히 먹을 수 있어서 좋았습니당! 너무 맛있고 인테리어가 기절할 만큼 예뻐요ㅠㅠ 안 그래도 마녀배달부 키키 좋아하는데 다음에 또 오고싶네여...♡ 최고의 선택이었습니다ㅠ!!', 7, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '지나가다 우연히 들어왔는데 마녀배달부키키 컨셉 카페더라구요. 시그니쳐 메뉴가 뭘까 궁금해서 시켜봤는데 시간이 지날수록 눈코입이 사라져가서 슬픔 😢 아기자기하고 이색적인 장소라 지브리 좋아하는 친구나 데이트할때 오면 좋을거 같아요. 마녀배달부키키 다시 봐야지...', 37, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '아이랑 주말마다 이쁜카페 찾아다니는걸 좋아해서 오늘은 코리코카페 방문했어요~정말 입구부터 너무 아늑하고 따뜻한 느낌~아이도 신났어요~오늘 크림브뤌레랑 지지머그체리타르트,아메리카노에 지지샷아이스 추가했는데 너무 귀엽고 진짜 맛있었어요~^^오늘 이쁜카페 최고였어요.성공적!', 25, 1, 'GOOD', SYSTIMESTAMP);
