INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '진심으로 지지 머그 타르트 드셔야 합니다. 너무 맛있고 귀여워요. 아메리카노에 지지샷 아이스도 꼭 추가해 보세요. 킹왕짱 귀엽습니다. 기분이 꿀꿀할 때나 새로운 경험을 하고 싶을 때 놀러 오기 좋아요. 음악도 지브리 ost만 틀어주고, 테마파크에 온 것 같아요. 행복하게 있다 갑니다.', 27, 0, 'GOOD', SYSTIMESTAMP);
