INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '분위기가 좋으면서 편안하고 디저트와 커피는 너무 맛있고 1,000원 추가시 지지 모양 얼음을 올려주셔서 너무 귀여워요!! 심지어 소품들도 너무 많아서 구경하기 딱이고 선물하기 아주 좋아요!! 한국 전용 한정판도 있으니 모두 와서 구경해보세요~♡♡', 50, 10, 'GOOD', SYSTIMESTAMP);
