INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '코리코카페! 전부터 가고 싶었는데 드디어 친구와 방문했어요😍 굿즈샵도 예쁘고 다양하게 세팅되어있고 디저트들도 다 너무 먹기 아까울 정도로 예뻐요🥹 자두타르트? 특히 추천드려요! 풍경도 아름답고 흔치 않아 좋아요🩷 또 올게요!', 32, 0, 'GOOD', SYSTIMESTAMP);
