INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '마녀배달부 키키 정말 좋아하는데 굿즈들이 놓여져 있어서 너무 좋았어요 타르트도 너무 맛있는데 자두맛 궁금했는데 없어서 너무 아쉬웠어요 ㅠㅠ 솜사탕 라때도 무슨맛일지 궁금했는데 달달한 라떼라 맛있어요! 매장도 넓고 빨리 빨리 나와서 좋았어요!', 6, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '코리코 카페 전부터 쭉 오고 싶었는데, 이번에 기회가 되서 왔습니다 !! 정말 인테리어가 마음에 들어서 10시간씩 있고 싶지만... 시간이 없어서 30분도 못 있다 갑니다... 다음에 꼭 다시 오고 싶어요 !!', 61, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '입구부터 너무 지브리스럽고 예쁩니당! 마녀배달부키키 속으로 들어온거 같아요오! 아기자기하고 영화 그 특유의 느낌이 느껴지는 곳이에용ㅎㅎ 어느 구도에서 찍든 사진이 다 잘나오는..👍🏻 음료랑 컵모양의 케이크도 너무 카와이해요!! 일요일인데 일찍 와서 그런지 웨이팅도 없어서 너무 기분 좋게 있다갑니다!ㅎㅎ', 37, 3, 'GOOD', SYSTIMESTAMP);
