INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '진짜..안왔으면 후회할뻔.. 홍대를..1년만에 왔는데..진짜너무너무좋았어요.. 와..ㅠㅠ̑̈ 진짜..음료도괜찮고 사실디저트 값할거같고 맛은별로일까 걱정했거든여?? 근데..솔찍히..다른카페들도 이쁘지맛 맛있는데 별루없자나여 근데.. 여긴 시킨거후회1도안할맛이에요 값은좀 있지만.좋아요 추천해요', 5, 1, 'GOOD', SYSTIMESTAMP);
