INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '주말인데 웨이팅없이 바로 방문!! 운이 좋구만🩷 이쁜데 비싼 지브리 굿즈도 많아서 구경하는 재미도 있고, 구옥을 개조한 카페라 고즈넉하고 빈티지한 분위기도 좋습니다🩷 디저트 솔직히 맛은 그냥 그런데 비쥬얼이 너무 귀여워서 주문을 안할 수가 없었음ㅎㅎ 지브리 좋아하는 분들이라면 무조건 만족할만한 카페입니다!!', 110, 24, 'GOOD', SYSTIMESTAMP);
