INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '가게 입구부터 엄청 예쁘고 내부도 귀여웠어요!! 컨셉 뿐만 아니라 커피랑 디저트도 맛있어서 지브리 좋아하신다면 추천드립니다☕️', 11, 6, 'GOOD', SYSTIMESTAMP);
