INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '인스타보고 꼭 와보고 싶었던 카페! 너무 이뻐 어쩌지ㅜㅜ 찾아오길 너무잘함! 꼭오세요!❤️❤️❤️❤️❤️❤️ (타르트는 좀달아서 필링좀 먹다가 우유에 마구 부셔서 섞어먹음 짱맛일듯😍마침 모양도 컵이라서😆)', 115, 19, 'GOOD', SYSTIMESTAMP);
