INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '너무 귀엽고 예쁜 카페입니다..!🐈‍⬛🎀 그리고 마녀 배달부 키키의 OST가 계속 나오는데 분위기가 너무 좋습니다✨ 곳곳의 인테리어와 굿즈샵도 구경하는 재미가 있어요 음료는 여느 카페들처럼 맛있는 음료였습니다!🍵🥛 케이크도 음식도 종류가 많던데 배불러서 먹어보지 못한게 아쉬웠어요...🥺', 89, 12, 'GOOD', SYSTIMESTAMP);
