INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '직원분이 너~~~무 친절하셔서 리뷰 남겨요!! 지브리 덕후라 코리코 가끔 자주 가는데 온라인 판매를 놓쳐서 오프라인으로 사러왔어요🥲 탈색머리에 굿즈샵 계산담당하시는 직원분 목소리도 나긋하시고 친절하세요 정말러,,. 마음이 따뜻해지는곳이에요 자주갈게영,,!!!', 1, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '평소와는 색다른 분위기의 카페에 가고싶어서 방문했는데 마녀배달부 키키테마라 아기자기한 인테리어가 예쁘고 먹기 아까울정도로 예쁜 디저트와 음료가 결정장애를 부릅니다. 디저트도 음료도 모두 맛있었어요.', 47, 9, 'GOOD', SYSTIMESTAMP);
