INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '마녀배달부 키키 영화랑 캐릭터 좋아하는데 이 카페 완전 천국같았어용ㅜㅜ💕🐈‍⬛ 디저트들도 디테일하고 생각보다 맛있어요!! 잘 놀다 갑니당', 50, 3, 'GOOD', SYSTIMESTAMP);
