INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '일단 외관이 너무 예뻐요~ 직원분들도 친절하시고 디저트가 예쁘기만한게아니라 맛도 있어요. 초코시트가 사르르 녹는게 식감이 너무좋고 레몬셔벗도 상큼한데 너무달지도 않고 쫀득하니 진짜 맛있게 먹었어요! 지지 얼음도 넘귀엽 ㅎㅎ♡ 담에 또올것같아요', 119, 26, 'GOOD', SYSTIMESTAMP);
