INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '아이가 오고싶다해서 왔는데 제가 시킨 메뉴는 맛이 없네요 다신 안올 것 같습니다. 맛이고 뭐고 알바생이 과하게 불친절하네요 서비스 교육은 꼭 필요하네요 영수증  리뷰 안하고 싶었는데 불쾌해서 남깁니다', 9, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '지브리 감성을 가득 담은 카페예요. 분위기가 아늑하고 편안해서 오래 머물고 싶었고, 디저트가 예쁘게 나와 눈과 입이 모두 즐거웠습니다. 커피 맛도 깔끔하고 풍미가 좋아 만족스러웠고, 직원분들도 친절해서 기분 좋게 다녀왔습니다. ☕🍰✨', 9, 4, 'GOOD', SYSTIMESTAMP);
