INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '우선 분위기가 넘넘 좋고 커피도 맛있어요 고르곤졸라 더치 팬케이크도 시켰는데 진한 고르곤졸라놔 부드럽고 쫄깃한 계란도우가 넘 잘어울려요. 디저트도 진짜 맛있네요 강추합니다', 109, 21, 'GOOD', SYSTIMESTAMP);
