INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '디저트 종류가 많고, 커피가 맛있었어요 인테리어도 귀엽고 조그만 지브리샵이 있어서 소품샵도 구경할 수 있어요!! 주말 2시 반쯤에 왔는데 웨이팅 없었고 자리도 꽤 남아있었어요 지브리 덕후 추천 ❤️', 84, 18, 'GOOD', SYSTIMESTAMP);
