INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '나무 예쁘고 마침 지브리 영화 속으로 온 것 같아요😭💕💕💕 맛있는 음료 한 잔 마시면서, 지브리 ost 듣고 바쁜 일상에서 잠시 휴식을 취하기 딱 입니다!! 매일 매일 오고 싶네요~ This place feels straight out of a Ghibli movie😭💕💕💕 Everything from the food & drinks to the decorations feels so cozy and whimsical, and they play Ghibli osts all the time! The perfect place to come if you need a break from life~✨️ (I don''t want to leave😭😭😭)', 37, 1, 'GOOD', SYSTIMESTAMP);
