INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '디저트가 너무 맛있었어요. 배지테리언 메뉴도 있었는데 그것도 너무 좋았어요. 시간이 많았다면 한 곳에 시간을 오래 보내면서 즐길 수 있었을 텐데 디저트와 음료가 너무 맛있어서 빠르게 돌아보고 말았네요ㅋㅋ 좋아하는 사람들과 시간을 보낼 수 있어서 행복했어요.', 24, 3, 'GOOD', SYSTIMESTAMP);
