INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '지브리좋아하늣 딸과 조카데리고 방문했어요. 귀염뽀짝 디저트도 맛나고 미트파이도 맛납니다. 지브리소품 쇼핑은 덤이네요. 찾아오는 길이 조금 헤메인거빼고는 좋아요. 근처 공영주차하시고 잘 찾아오시길요~', 13, 10, 'GOOD', SYSTIMESTAMP);
