INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '여러번 오다가 새로운 메뉴가 있어서 시켜봤는데 너무 맛있었어요 머그 타르트 사실 고구마랑 초코바나나 먹으려고 했었지만 예상 외로 시트러스가 엄청 달고 상큼하고 맛있었어요 타르트 안에는 케이크 같은 느낌인데 층이 여러개 있고 다양한 맛이나서 좋았어요!', 0, 10, 'GOOD', SYSTIMESTAMP);
