INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '목요일 낮에 왔는데 대기 없이 바로 들어올 수 있었고 한적했어요. 분위기도 너무 좋고 특히 노래가 마녀배달부 키키 OST가 계속 나와 더 몰입되고 좋았습니다. 라벤더라테를 마셔봤는데 달달구리 하고 크림브륄레 팬케이크도 달달하고 퐁신퐁신 해서 너무 맛있게 먹었어요!!', 121, 20, 'GOOD', SYSTIMESTAMP);
