INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '가게 곳곳이 너무 예쁘고 디테일들이 진짜 영화속에 들어온거 같아요. 디저트도 이쁜데 맛도 참 좋네요. 기념품도 팔아서 기분좋게 먹고 하나 득템해가기 좋아요. 비오는날에도 이쁩니다.', 99, 26, 'GOOD', SYSTIMESTAMP);
