INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '예전부터 너무 오고 싶었던 곳이었는데 진짜 상상 이상으로 너~무 귀엽고 맛있어요 ㅠㅠ 더치 팬케이크 모닝 적극 추천이요!! 팬케이크+샐러드가 섞인 브런치 느낌?? 마녀 배달부 키키 위주인 지브리 샵도 있고 지브리 좋아하시면 무조건 오셔야 해요... 눈 돌아갑니다 또 오고 싶어요!! 😍😍', 13, 9, 'GOOD', SYSTIMESTAMP);
