INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '코리코카페 첫 방문!100일 기념으로 어디 카페를 갈까 찾아보다가 지브리 감성 카페라고 해서 바로 방문했어요!와서 뭐 먹을지 고민하다 라벤더라떼라는 것을 처음봐서 시켜 먹어봤는데 진짜 너무 맛있습니다!정말 라벤더 맛🤭섞기전보다 섞은 후 먹는게 더 맛있더라구요!카페도 시원하고 너무 좋았습니다!다음에도 재방문할거같아요🫶🏻', 52, 16, 'GOOD', SYSTIMESTAMP);
