INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '서울 여행겸 와서 아늑한 시간 보내다 갑니다! 디저트들도 맛있고 매장 직원분들도 친절하셔서 기분이 너무 좋았어요! 다음에도 기회가된다면 꼭오고싶어요! 더치베이비 부드러운맛이 잊혀지지 않을것 같아요!✨', 21, 8, 'GOOD', SYSTIMESTAMP);
