INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '브런치 메뉴 꼭 먹어 보고 싶었던 코리코 카페! 미트파이 세트랑 더치베이비 모닝 먹었어요. 예쁘고 카페 분위기랑 잘 어울려서 기분 좋은 시간이었어요! 다음엔 디저트 먹어 보러 올게요~', 1, 2, 'GOOD', SYSTIMESTAMP);
