INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '너무너무 예쁘고 행복하고 맛있고 좋아요!! 세상에서 제일 귀여운 카페...🥹 직원분들 옷차림이 귀얍고 다들 친절하세요. 음료 맛만으로도 재방문 왕창할것같아요!!', 71, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '여자친구랑 들러본 코리코카페! 전부터 오고 싶었는데 막상 오니까 넘넘 분위기 좋고 좋아요ㅎㅎ 지지인형은 제가 인형뽑기에서 뽑아서 여자친구 선물로 줬던건데 이렇게 쓰이니 기분 좋네요. 다 좋은데 아인슈페너가 넘 좋았어요 히히 짱~~ 담에 또 올게요!', 23, 8, 'GOOD', SYSTIMESTAMP);
