INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '웨이팅 있을까 걱정했는데 일요일 11시 반에 바로 입장했어요!! 폭염이라 그런 걸지도... 채광이 좋아서 사진도 예쁘게 나오고 음식도 퀄 좋으면서 맛있어요!', 50, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '야외도 이쁘고 매장안에서 흘러나오는 음악들이 감성을 자극해요 일본에 있는 듯한? 사람 없을 때 오면 힐링 그 자체일 듯 합니다.', 44, 3, 'GOOD', SYSTIMESTAMP);
