INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '분위기가 아기자기하고 케이크는 신기한 모양이에요! 멀지만 찾아온 보람이 있담니다! 여기까지 소품가게도 엄청 있어서 천천히 오기 좋아요 그리고 카페가 똭 있는데 너무너무 이쁘고 동화속 같아요 오길 잘했어요!', 16, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '아기자기하고 너무나 이쁜 인테리어에 지브리 감성까지 행복해지기 딱 좋은 카페입니다. 가격이 조금 있는 편이지만 다인원으로 오면 괜찮은 편인 듯 싶어요. 브런치 메뉴들 다 맛있고 무엇보다 평일 오후에 방문하니 사람이 없어서 여유롭게 둘러보고 사진 찍고 편하게 수다 떨다가 왔어요 :) 평일에 서울 가면 무조건 다시 갈 겁니다..🥹✨', 42, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '분위기 최강 너무 귀여워요 귀여워수 힐링 그 자체!!! 음료도 지지 추가해서 너무 귀엽게 마셨습니다 다이어트 아니였음 디저트도 꼭 먹엇을거에요 ㅠㅠ 귀욥', 61, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '일본 친구가 지브리를 사랑하는 저와 함께 꼭 같이 가고싶어한 곳입니다. 진짜 지브리 애니메에서 바로 나온 것 같은 비주얼이에요. 특별한 메뉴가 있어서 좋았고 지브리 굿즈샵도 있어서 너무 좋았습니다.', 32, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '주말 오후 대기 없이 바로 입장 했구요 가장 좋아하는 지브리 캐릭터인 키키와 지지로 가득한 카페여서 너무 행복하구 음료와 케이크도 괜찮네요 굿즈들 구경도 하고 좋은 시간 보냈습니다 :D', 26, 0, 'GOOD', SYSTIMESTAMP);
