INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '지브리 너무 좋아하는데 남자친구가 검색해서 찾아봐주고 방문했어요. 음료 디저트 다 너무 맛있고 인테리어와 BGM이 진짜 애니안으로 들어온것 같아서 행복했어요^^ 굿즈도 많고 스템프 이벤트도 진행중이니 꼭 다시 방문해야겠어요!', 4, 4, 'GOOD', SYSTIMESTAMP);
