INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '마녀배달부 키키를 좋아해서 늘 오고싶었던 코리코카페에 드디어 왔습니다~ 🌿 초입부터 초록초록한 무드가 너무 좋았고, 특별한 메뉴까지 있어서 기분좋게 즐겼어요~ 💗', 49, 6, 'GOOD', SYSTIMESTAMP);
