INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '귀여운 인테리어랑 넘 맛있는 브런치 🍳 일본에서 갔던 지브리 카페보다 더 지브리 카페 같아요! 🫶 분위기도 너무 귀엽고 차광 조은 날에 다녀오면 기억에 더 오래 남을 것 같아요~~ 홍대에 요런 보물같은 곳이 잇엇다니 자주 올게영!(밀크티 진짜 달달하구 미쳤어요🩷🩷🩷)', 22, 10, 'GOOD', SYSTIMESTAMP);
