INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '매장이 너무 예쁘고 지브리 세상 속에 들어온것 같아서 좋았어요! 친구랑 같이 갔는데 자두가 철이라 그런지 자두 번트 케이크도 맛있고 음료수도 복숭아 요거트 맛 나서 맛있었습니다!!', 24, 1, 'GOOD', SYSTIMESTAMP);
