INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '여자친구가 예전부터 서울에 놀러가몉 가고싶어하던 카페에 오늘왔는데 일단 대문에서부터 너무이쁘고 귀여워서 사진엄청찍었고 1층에 소품샵도 있어서 정말 좋은거 같아요 직원분들도 친절하시고 추천드려요', 51, 11, 'GOOD', SYSTIMESTAMP);
