INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '키키 테마 너무 귀여워요! 지브리 bgm이 계속 흘러나와 좋구요! 밀크티 맛있어요! 쿠키 낱개 구매 가능하게 되면 더 좋을 것 같아요!', 35, 3, 'GOOD', SYSTIMESTAMP);
