INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '마녀배달부 키키~🎀 요런 컨셉의 카페는 그냥 지나칠수 없지 지브리 팬으로서~~~ 음료와 디저트류도 만화속에서 튀어나온듯한 모양과 구성으로 되어있네 솜사탕구름 퐁실 바다라떼와 키키의 친구 지지 모양으로 얼린 지지샷아이스 추가한 아이스아메리카노까지~ 지지머그타르트도 너무 사랑스럽고 예쁘당~♡ 바나나피칸캬라멜 더치베이비팬케이크는 맛나게 오븐에서 구워나오느라 약20분정도 소요된다고~~ 마법 빗자루 타고 파란 바다위~ 하늘물 들은 하늘색 구름 위를 날으는 마녀 배달부 키키~♡ 부풀부풀 팬케이크위에 바나나, 피칸, 아이스크림이 가득 담겼다 머그컵에 담긴 딸기타르트는 사랑스러운 맛~♡ 지지샷아이스는 귀여워서 천천히 녹기를~ 만화 속 공간에 아이처럼 들뜬 행복감으로 잠시 머물렀다~', 25, 6, 'GOOD', SYSTIMESTAMP);
