INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '지브리 영화 덕후인데 왜 이제야 방문했을까 싶은🥲 입구와 외관부터 영화 속 장면 같아서 동심이 마구마구 생겨요 내부 인테리어도 아기자기한 키키 캐릭터들로 가득하고, 채광 좋은 테라스도 최고입니다 카페 바로 앞에 엄청 큰 목련 나무가 있는데 아쉽게도 제가 방문했을 때는 목련이 거의 떨어진 ㅠ.ㅠ 조금만 더 빨리 올걸..!! 벚꽃 시즌에만 먹을 수 있는 체리블라썸라떼와 벚꽃번트 주문했는데 먹기 아까울 정도로 너무 예쁜 🌸 달달 상큼한 체리 디저트 존맛탱입니다 🍒 다 먹고 굿즈샵도 구경했는데 텅장되실 수 있으니 조심하세요 🥲', 102, 20, 'GOOD', SYSTIMESTAMP);
