INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '디저트도 맛있고 분위기 좋고 지브리감성 가득한 카페에요 장소도 넓고 아늑한 분위기가 너무 좋습니다! 지지 얼음이 너무 귀여웠어요ㅠㅠ', 33, 10, 'GOOD', SYSTIMESTAMP);
