INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '지지 케이크도 너무 귀엽고 디저트 종류, 브런치도 먹을 수 있어서 좋아요! 지점이 두 곳 밖에 없어서 서울 놀러온 김에 왔는데 역시나 기대 이상이고 담에 또 오고 싶어요!!', 95, 20, 'GOOD', SYSTIMESTAMP);
