INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '쉬는날 혼자 힐링하러 왔는데🌿 귀엽고 아기자기하고, 평일엔 한적해서 더 좋아요!! 읍 ...홍대 자주 오면서 왜 이제알았지...😵‍💫 버터스카치라떼 먹었는데 크림도 달달하니 넘넘 맛있었어요!!! 재방문의사 🌟X100입니당 힐링하다 가용💖💖날씨 따뜻해지면 또 놀러갈게요 🤭', 13, 8, 'GOOD', SYSTIMESTAMP);
