INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '키키를 좋아해서 왔는데 웨이팅없이 바로 들어가서 좋았어요 그리고 인테리어가 매우 감각적이라서 너무 예뻤어요 키키랑 지지 귀여워요', 25, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '우선, 인테리어가 입구에서 부터 예뻐요!😄 1층 굿즈샵도 귀어운게 많아서 구경하는 것도 재미있었어요:) 2층도 예쁘고 화장실도 깔끔해서 좋았어요!!! 다만!!! 디카페인 아메리카노는 정말 최악이었어요!!! 😭 먹기전부터 색이 연해서 왜이러지 했는데, 먹으니 그냥 물이었어요 연한커피를 시킨게 아니라 디카페인을 시킨건데 디카페인 추가요금까지 내고 6000원 결제 했는데 이건 진짜 돈이 아까웠어요 친구랑 저랑 이건 그냥 물은데..?  얼굴 붉히기 싫어서 말안했어요 개선이 필요합니다!!', 89, 14, 'BAD', SYSTIMESTAMP);
