INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '웨이팅이 길까봐 걱정했는데 카페 안쪽 공간이 꽤 넓어서 좋았어요 하지만 대부분 2인석이라 3인 이상의 경우 조금 애매할 수 있을 것 같아요', 1, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '홍대입구역에서 꽤 걸어야했지만 오는 길에 소품샵이 많아서 구경하며 오기 괜찮은 것 같아요!! 아이 손님보다는 어린 손님들이 많았고 대기없어서 좋았어요~~ 디저트 가격은 사악하지만 한번 와 보기에 괜찮은듯해요! 매장 앞에 서 계신 직원분은 들어오자마 보이는 얼굴인데 표정이 좋지 않고 친절하지 않으셔서 조금은 웃어주셨으면 좋겠어요~~', 18, 5, 'GOOD', SYSTIMESTAMP);
