INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '가격대가 좀 있지만 그만큼 너무너무 예쁘고 분위기있고 사진도 잘나와요 맘먹고 서울나들이 오실 분들이라면 꼭 한 번씩 들러보시는 거 추천드립니다!! 특히 라벤더라떼가 정말 달고 부드럽고 맛있어요 🥰🥰 디저트는 컵 모양으로 생긴 시트러스타르트를 골랐는데 지지쿠키가 일단 너무 귀여웠고 딱딱할 거라는 예상과 다르게 시트가 정말 촉촉하고 포슬포슬했어요 타르트 안에는 오렌지크림, 자몽크림같은 게 있는데 특히 자몽 컬러가 킥이더라고요 눈으로 한 번 입으로 한 번 먹으니 안 그래도 맛있던 디저트가 더 맛있어졌습니다😋', 20, 9, 'GOOD', SYSTIMESTAMP);
