INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '바깥 풍경이나 외관을 보면 겨울이라 휑하고 뭔가 잘못 왔나? 영업을 안하나? 하실 수 있습니다 그런데 막상 들어가면 놀랍니다! 😲🤗 그렇습니다 익스테리어 마저도 이걸 위해 거의 연출한거나 다름 없을 법한 내부,, 지브리 좋아하는 분들은 꼭 오세요 토토로, 마녀배달부 키키 굿즈들이 참 많았습니다 특히나 지지 굿즈들이 상당히 많이 보이더라구요☺️ 탐나서 꼭 사고픈 것들이 이곳저곳에 널려 있었습니다🥺 굿즈뿐 이겠습니까 내부 인테리어부터 구조, 소품들까지 다 지브리 덕후들은 기절할 법한 퀄리티였습니다🙂‍↕️👍 카페인데 메인이 뭐겠습니까 커피와 디저트죠 딸기밀크티와 아인슈패너 주문했습니다 디저트 비주얼만 봐도 아까울정도로 이쁜데 부드럽고 맛있기까지 아인슈패너도 진짜 위에 적당히 맛있게 달고 아래 커피는 고소~😋', 16, 8, 'GOOD', SYSTIMESTAMP);
