INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '들어올 때부터 지브리 느낌+ 노래까지 지브리 감성이 느껴지는 카페였어요. 디저트랑 음료도 다양하고 카페 안에 기념품샵도 같이 있어서 구경하기도 좋아요.', 19, 3, 'GOOD', SYSTIMESTAMP);
