INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '이 카페에서 만화 자주 읽습니다! 분의기도 좋고 디저트도 항상 맛있습니다. 친구들이랑 사랑스러운 카페 가고 싶기이나 데이트 카페 찾고 있으면 여기서 추천합니다!', 38, 3, 'GOOD', SYSTIMESTAMP);
