INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '웨이팅 있을까봐 걱정했는데 다행히 바로 들어갔어요! 전부터 가보고싶었던 곳인데 드디어 와봤어요ㅎㅎ 외관부터 애니메이션에서 나온 것처럼 잘 꾸며놨어요! 작게 굿즈존도 있고 디저트도 너무 귀엽고 맛있었어요ㅎㅎ 지브리 좋아한다면 꼭 가봐야 하는 곳이에요!', 25, 5, 'GOOD', SYSTIMESTAMP);
