INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '지브리 카페에 들어서는 순간, 마치 지브리 애니메이션 속 세계로 들어온 듯한 느낌을 받았습니다. 토토로 인형들과 손그림 스케치, 따뜻한 조명까지 모든 것이 아늑하고 감성적이에요. 미야자키 하야오 감독의 감성이 그대로 살아 숨 쉬는 공간입니다. 저는 하울의 베이컨 & 에그 브런치와 하쿠 말차 라떼를 주문했는데, 플레이팅도 예쁘고 맛도 좋았어요. 특히 고양이버스 치즈케이크와 검댕이 쿠키는 꼭 드셔보시길 추천드려요. 귀엽고 맛있어서 사진 찍기에도 딱입니다! 직원분들도 매우 친절하고, 지브리에 대한 애정을 가지고 있는 것이 느껴졌어요. 조용하게 흐르는 지브리 OST 피아노 버전도 분위기를 더욱 따뜻하게 만들어줍니다.', 6, 7, 'GOOD', SYSTIMESTAMP);
