INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '너무귀엽고 예쁜 곳이에요,, 직원분들도 짱 친절하시고 분위기는 말모ㅠㅇㅠ..... 제주점이랑 연남점이 분위기가 다른것같아서 연남 방문해봤는데 정말 좋아요,, 과일이 들어간 브런치는 시즌메뉴같아서 아쉽게 못먹었지만 또오고싶어요🥰', 40, 10, 'GOOD', SYSTIMESTAMP);
