INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '너무 와보고 싶었던 카페인데, 주말은 사람이 많을것같아 평일에 혼자 방문해봤어요! 여유롭게 구경하고 사진도 찍고 고르곤졸라피자랑 음료마시고 갑니다 너무 힐링되고 좋아요 크히 😭💛', 12, 2, 'GOOD', SYSTIMESTAMP);
