INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '예전에 막 오픈했을 때 웨이팅 엄청 기다려서 왔었는데 오랜만에 평일 오전에 왔더니 웨이팅 없고 넘 쾌적하고 좋았습니다!!! 외국에서 놀러온 친구가 꼭 와보고 싶다고ㅋㅋ 잘 데려온 것 같습니다~~ 최고!', 36, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '진짜 항상 오고싶엇는데 멀어서 못왔는데 기회가 되서 이번에 왔는데 진짜 너무 분위기가 좋고 디저트도 너무 맛있어요 연남오면 진짜 꼭한번 와보세용 지브리 좋아하는사람 추천 완전 눈 돌아가요 ღ', 68, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '아기자기하고 카페가 너무 귀염뽀짝해용😍 서울여행와서 연남동카페 알아보다가 발견한곳인데 커피도 맛있고 디져트도 너무귀엽고 꿀맛탱❣️ 직원분도 너무 친절하게 응대해주셔서 기분좋았어용❣️', 18, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '친수랑 예약 없이 왔는데 웨이팅도 없었고 너무 예뻐서 사진찍기도 좋아요! 원색 컬러의 옷 입고 오면 최고 😆 레몬번틀 먹었는데 추천합니다!!!! 직원분께서도 친절하셔서 음식 받기 전부터 기분이 좋았어요 ㅎㅎ ᰔ', 10, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '입구로 들어서자마자 키키가 있던 빵가게에 온것 같아서 기붐이 좋아졌어요🐈‍⬛🧹 카페 분위기도 아늑하고 지지 얼음도 귀엽고 지브리 상품도 잔뜩 구경해서 너무 좋았어요🤩❣️', 6, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '지브리 감성 못 잃어요~ 맛있고 예쁘고 귀여운거 가득이네요. 👍🏻💕 더치베이비 팬케이크 쫀득 달콤. 또 올만한 맛인데다 밀크티 맛집, 아인슈페너도 좋았어요.', 4, 0, 'GOOD', SYSTIMESTAMP);
