INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '지브리 느낌이 충만할줄 알았는데 카페 내부 분위기 자체는 평범합니다. 음료 잔 접시나 굿즈 파는 곳 정도만 지브리 느낌이 나는 정도.. 음료랑 디저트는 맛있습니다. 잘 먹고 갑니다~', 22, 9, 'GOOD', SYSTIMESTAMP);
