INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '너무너무너무예뻐요!!!! 1층에 지브리 굿즈를 파는 곳도 있어요! 직원분도 친절하십니다! 여름이라 푸릇푸릇해서 더 예뻐요😍 해가 밝을 때 오는게 예쁠것 같아요✨️', 73, 15, 'GOOD', SYSTIMESTAMP);
