INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '서하마 런닝 마치고 찾은 연남동 코리코. 똑똑...여기가 그유명한 지브리 카페 맞지요?! 지지 아이스아메리카노랑  레몬번트케잌 넘 맛있어요.  지브리 소품코너에서 고양이버스 보고 지름신올뻔!', 35, 9, 'GOOD', SYSTIMESTAMP);
