INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '입구부터 너무 지브리느낌이 나요! 마녀배달부키키 속 으로 들어온거 같거든요~!! 어느 구도에서 찌든 사진이 다 잘 나옵니ㅡㅏ직원도 친절합니다. 친절하지만, 직원한테 3번이나 반복해서 말했는데 이해 못 하길래 포기 했어요~! ^^ 에휴', 27, 2, NULL, SYSTIMESTAMP);
