INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '음식뿐만 아니라 카페도 너무 예쁘고 직원분들도 친절하셔서 또 왔습니다!! 연남동 오신분들은 코리코 카페 한번씩 오시는거 추천합니다👍', 13, 0, 'GOOD', SYSTIMESTAMP);
