INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '지브리 애니 중에서도 마녀배달부 키키 특히 좋아하는데 키키 집에 놀러온 기분이였어요!!! 디저트도 맛있고!! 인테리어도 정말 너무 너무 예쁘고ㅠㅠㅠㅠ 다음에는 2층에서 시간 보내고 싶어요! 1층도 예쁘지만 2층이 특히 더 예쁘더라구요', 51, 15, 'GOOD', SYSTIMESTAMP);
