INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '방문해보고 싶은곳으로 찜해놓고 이번 여행에 방문했어요^^ 팬케이크와 음료 모두 정말 맛있고 제가 키키팬이라 행복한 시간을 보냈습니다♡', 47, 10, 'GOOD', SYSTIMESTAMP);
