INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '공간이 예쁘고 귀여워요 지브리 좋아하신다면 한번쯤 방문하기 좋은 곳입니다! 내부도 깨끗하고 넓어서 좋았어요 메뉴들도 맛있어 보입니다~~ 안쪽에 소품샵도 있어서 구경하기 좋아요', 7, 3, 'GOOD', SYSTIMESTAMP);
