INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '저번에 방문하고 이어서 방문했는데, 너무 예쁘고 좋아요~~~~ 생일 기념 케이크 샀는데, 너무 기대되네요~~~~ 다음에 또 올게요!!', 65, 11, 'GOOD', SYSTIMESTAMP);
