INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '가게에서 나오는 지브리의 음악과 인테리어가 너무 좋았고 전체적으로 아기자기한 느낌과 아메리카노에 추가하면 나오는 지지의 얼음도 다 귀여워서 행복..기zㅓㄹ..☺️ 벚꽃 슈크림 라떼도 부드럽고 달달한 게 아주 맛있었습니다', 83, 18, 'GOOD', SYSTIMESTAMP);
