INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '여자친구와 함께 방문했구요 내부도 너무 이쁘고 굿즈들도 함께 구경할 수 있어서 너무 좋은 것 같습니다. 지브리팬으로써 눈이 돌아갈 수 밖에 없는 카페인 것 같아요', 33, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '새로운 벚꽃 메뉴를 먹어보려고 왔어요. 안타깝게도 케이크가 매진되어서 (오후에 왔어요) 벚꽃 크림 라떼와 초콜릿 케이크를 샀어요. 둘 다 너무 맛있어서 창가에서 먹고 기블리 음악을 들으면서 너무 편안해요 ☺️ 100% 다시 방문할게요! 🌸💖', 80, 17, 'GOOD', SYSTIMESTAMP);
