INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '분위기 너무 좋고 안에 스토어가 있어서 다양한 지브리 상품들을 볼 수 있어서 좋았어요!!!또 인테리어도 이쁘고 사진 완전 잘나와서 다들 한번씩 오시는거 강추합니당!!', 93, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '💜날씨 좋은 날에 방문했어요💜 다시 방문해도 너무 좋았어요! 특히 시즌 메뉴를 먹을 수 있어서 행복합니다😆! 🌸벚꽃 시즌 메뉴 완전 추천드려요🌸 파이도 정말 애니메이션에서 튀어나온 비쥬얼에 감탄하며 열심히 사진을 담아보았어요💕🐈‍⬛', 55, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '제일 좋아하는 애니메이션인 키키 보러 왔어요!! 다양한 캐릭터 용품이 많고 케이크도 예쁜게 많아서 다시 한 번 방문하고 싶은 곳이에요! 운좋게 예약없이 올 수 있어서 행복해요!', 13, 7, 'GOOD', SYSTIMESTAMP);
