INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '코리코카페… 드디어 왔숩니다… 안에 굿즈샵도 있어서 지브리 굿즈도 구매할 수 있고 디저트도 귀엽고 뽀짝해서 안 먹을 수가 없었어요… 🥹 다음에 또 오고 싶습미다', 22, 7, 'GOOD', SYSTIMESTAMP);
