INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '일단 전체적으로 너무 지브리같아서 좋고 제가 좋아하는 배달 마녀부 키키를 바탕으로 하니 진짜 너무 예뻐요>< ♡⁺◟(●˙▾˙●)◞⁺♡', 27, 3, 'GOOD', SYSTIMESTAMP);
