INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '외관부터 너무 예쁘게 잘 꾸며져있어서 들어올 때부터 기분이 넘 좋았어요! 일요일 4시 정도에 방문했는데 사람은 많았지만 대기 없이 바로 입장할 수 있었어용 카페 내부도 그렇고 디저트도 그렇고 마녀배달부 키키 그자체.. 예쁘기만 한 게 아니구 디저트도랑 음료 너무너무 맛있었어요! 안에 소품샵도 있으니 꼭 구경해보시길.. 또 오고 싶은 카페에요🩷🩷', 26, 5, 'GOOD', SYSTIMESTAMP);
