INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '내부가 너무 이쁘게 잘 되어있어요! 음식도 맛있었고 지브리 캐릭터가 상징인 귀여운 디저트들도 많아서 다음에 오게 되면 다른 메뉴로 먹어보고싶네요ㅎㅎ 음악도 지브리 음악이 나와서 동심으로 돌아간 느낌이고 좋았어요 내부에 지브리 관련 굿즈들 판매하는데, 구경해보는 것도 추천해요! 보기만해도 기분이 좋아지더라고요', 52, 11, 'GOOD', SYSTIMESTAMP);
