INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '지브리 카페 있다고 해서 왔는데 너무 만족스러워요~ 토요일 2시에 웨이팅 없이 바로 입장했습니다! 카페 옆에 지브리관련 샵도 있어서 구경할수있어서 너무 좋아요 카페 너무 아기자기하고 귀여워요~', 42, 1, 'GOOD', SYSTIMESTAMP);
