INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '기대한 대로 너무 예쁘고 귀엽고 맛있고 엄청 힐링했어요 🩵 평일 낮에 방문했는데 여유롭게 머무를 수 있어서 너무 좋았습니다 ㅜㅜ 키키 좋아하시면 꼭 오세용 😸🍋🍋', 32, 0, 'GOOD', SYSTIMESTAMP);
