INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '동화 속 카페 같아요~~ 아기자기한 소품샵도 한 공간에 있어서 메뉴 주문하고 구경하기 좋습니다! 소품들 가격이 저렴하더라고요!! 1~2층 구조라 앉을 자리도 넉넉해요. 또 방문하겠습니다~!', 35, 10, 'GOOD', SYSTIMESTAMP);
