INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '키키 카페가 생겼다고 해서 방문했습니다 매장안에는 키키샵이 따로 있어요! 메뉴들도 컨셉에 맞게 키키 메뉴들이 많아서 넘 귀여웠어요!! 메뉴들도 맛있더라구요!! 야외 테이블이 있었지만 아직은 추워서 안에서 먹었습니다 마당에는 목련나무가 있어서 봄에 꽃피면 야외 테이블에서 먹으면 넘 좋을거 같아요!!!! 마녀배달부 키키의 팬이라면 무조건 방문 추천입니다!!!!🎀🐈‍⬛', 29, 8, 'GOOD', SYSTIMESTAMP);
