INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '친구가 코스 짜줘서 따라 왔는데 ㅜ 카페가 너무 귀엽고 예뻐요! 지브리 작품 중에서 마녀배달부 키키를 제일 좋아하는데 키키 테마의 카페라서 너무 좋았습니다 ❤️ 안 쪽에 MD 매장에도 귀여운 인형과 소품들이 많아서 너무 즐겁게 구경할 수 있었어요! 왕 귀여운 지지 인형도 득템…🫶🫶 다음에 또 찾아오고 싶을 정도예요 ㅜ 퐁당 오 쇼콜라 먹었는데 너무 부드럽고 맛있었어요! 버터 스카치도 맛있었고, 지지 아이스도 시켰는데 귀엽네요! 너무나도 만족스러운 곳이었습니다 ㅎㅎ ❤️❤️', 11, 4, 'GOOD', SYSTIMESTAMP);
