INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '일본 지인과 방문했어요! 대기 시간이 조금은 길었지만, 소품들도 귀엽고 인테리어도 이뻐서 대기시간이 지루하지 않았어요! 음료도 맛있고, 케잌도 맛있었습니당', 40, 5, 'GOOD', SYSTIMESTAMP);
