INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '외국에서 온 친척이랑 같이 가보니 엄청 좋아하더라고요! 메뉴 가격대는 좀 세지만 지브리 감성 느껴보고 싶은 분들에게는 강추드려요👍', 42, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '원더풀입니다 커피도 맛있구,케잌도 맛있네요.목련나무도 때마침 목련꽇이 활짝 피어있어 좋았구,,햇살도 좋구,일본서 온 동생과 조카가 아주 대만족했습니다', 41, 8, 'GOOD', SYSTIMESTAMP);
