INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '지브리좋아해서 기대했던 카페인네 기대이상입니다! 생각보다 넓고 곳곳에 너무 아기자기하게 예쁘게 꾸먀져있어요ㅠㅠ지브리 좋아하시는 분들 후회없을 겁키자ㅠㅠ', 292, 92, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '너무너무 와보고 싶었던 코리코 카페에 드디어 방문했네요💖 귀여운 지지 인형도 사고 금액 추가하여 지지 얼음도 야무지게 올려주었어요!! 다음 일정이 있어 디저트를 먹거나 오래 머물지는 못해 아쉽지만 재방문을 기약해야겠네요ㅎㅎ🥰', 29, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '고구마타르트가 진짜 너무 맛있어요🥺🩷 초코바나나 아니면 고구마 먹어야지 했는데 초코바나나  품절된게 다행.. 품절 안됐으면 이 맛있는 고구마타르트를 먹지 못했을거니까🥲 다들꼭드셔보세요 아니 드시지마세요 저만알고싶음....진짜맛있어요 고구마타르트최고🍠 말차라떼 아이스 변경 500원은 슬프지만.. 맛있으니까..', 91, 26, 'GOOD', SYSTIMESTAMP);
