INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '마녀 배달부 키키를 너무 좋아해서 평소에도 오고 싶었던 카페예요,, 인테리어, 음료 그리고 디저트가 다 정말 예쁘고 사랑스러웠어요🥹 눈도 즐겁고 입도 즐겁고ㅜ 다음에 또 방문할 것 같아요!!❤️🧹', 33, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '지나가던 길에 외관에 홀려서 들어왔더니 보이는 곳 마다 지브리 배경에 내부까지 너무나도 이뻤어요🥲 팬케이크도 빵 자체로 달달하고 샐러드에 드레싱 소스의 상큼한 맛도 느껴져서 너무너무 맛있게 먹었어요ㅠㅠ 다음에 또 오고싶을정도로 눈도 입도 즐거웠던 곳이에요!!', 46, 6, 'GOOD', SYSTIMESTAMP);
