INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '3번째 방문입니다 근처 올 때마다 꼭 빠지지 않고 오는 디저트 맛집입니다 에그타르트랑 팬케이크 진짜 맛있어요 짱짱 오늘은 번트케이크 먹으러 왔어요 다들 꼭 오세요 안 오면 후회해여', 12, 7, 'GOOD', SYSTIMESTAMP);
