INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '토요일 오후, 아이와 연남 데이트 했네요~ 키키를 좋아하는 아이라 데이트하기 너무 좋았습니다. 디저트와 음료 모두 맛있었고 인테리어도 귀엽고 예쁘네요~ 마녀배달부 애니 속으로 들어온 느낌이에요~~^^', 14, 0, 'GOOD', SYSTIMESTAMP);
