INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '키키의 베이커리를 생각나게 하는 이쁜 카페입니다. 원래는 웨이팅이 좀 있다는데 제가 갔던 날 날씨가 별로라서 그랬는지 저는 그냥 들어갔어요. 아이스커피에 지지얼음 올리고 딸기 타르트 먹었는데 딸기 타르트가 대박입니다. 생크림과 딸기의 조화도 좋고 타르트지도 바삭해요. 무엇보다 저 고양이 쿠키 ㅜㅠ 맛있어서 하나 포장했는데 집에 와 보니 쿠키가 부서졌더라고요 흑. 포장하실거면 2개 포장하시는 게 좋을 것 같아요 하나만 포장하니까 타르트가 안에서 고정이 되지 않아서 그런 사태가 벌어진 듯요.', 40, 8, NULL, SYSTIMESTAMP);
