INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '전부터 꼭 와보고 싶었던 코리코카페 입니다 진짜 지브리 마을에 들어온 기분ㅎㅎ 아늑하고 인테리어가 제 스타일이에요 혼자 와도 즐길 수 있는 카페에요 직원분들도 친절하시고 기분 좋게 즐기다 갑니다 ㅎㅎ', 70, 17, 'GOOD', SYSTIMESTAMP);
