INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '오랜만에 리뷰 작성 ㄱㄱ 코리코 카페에는 지브리 애니매이션 관련 아기자기하고 예뿐 상품들이 있었다ㅏ 뱃지를 택하고 한번 오픈을 해보니 짱 귀여 운 뱃지가 있었당!!:) 사람두 많아서 인기있는듯 요기 추천>~<', 53, 14, 'GOOD', SYSTIMESTAMP);
