INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '오늘 코리코 카페☕️ 다녀왔는데 인테리어 진짜 아기자기하고 예뻤어요! 🥰 미트파이🥧 먹었는데 생각보다 든든하고 맛있어서 놀랐음!  그리고 더치베이비🥞랑 머그 타르트🍮도 완전 짱귀엽고 맛있었어요! 😋 다음에 또 가야지!', 3, 9, 'GOOD', SYSTIMESTAMP);
