INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '번트케익이 생각보다 뻑뻑하지 않고 크림도 진해서 맛있어요! 커피는 고소한 맛이 강해서 산미있는걸 잘 못드시는 분들께 너무 좋을거 같아요😊 카페 분위기가 오밀조일 너무 귀여워서 너무 잘 온거 같아요!!!ㅎㅎㅎ', 104, 25, 'GOOD', SYSTIMESTAMP);
