INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '부산 시골쥐들이 서울 놀러와서 처음 온 카페입니다!! 친구가 인스타를 보고 찾았는데 인스타 사진보다 실물이 훨씬 훨씬 너무 많이 이쁘고 귀엽고 바나나 초코 쿠키 머그컵도 너무너무 맛있어요!!!! 딸기 초코 라떼는 인공적인 딸기맛이 조금 나서 남겼지만 사진은 정말 예쁘게 나온답니다!', 4, 5, NULL, SYSTIMESTAMP);
