INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '지브리 좋아하는 사람이면 무조건 들러야 하는 곳ㅠㅜㅜㅜ 디저트도 너무 귀엽게 해놔서 안 좋아해도 무조건 먹어줘야함 지브리 노래 나와서 좋고 밖에 앉으면 정말 날씨 좋으면 힐링 그 자체ㅜㅜㅠ', 86, 17, 'GOOD', SYSTIMESTAMP);
