INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '분위기가 따뜻하고 포근합니다.디저트도 예쁘고 맛 있습니다. 꼬마배달부 키키 좋아하는 사람이면 애니메이션 장면이 많이 생각 날 정도로 좋은 인테리어 입니다.', 0, 3, 'GOOD', SYSTIMESTAMP);
