INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '지브리 그 자체같은 주택카페에 지브리굿즈샵도 있고 키키같은 귀여운 디저트도 많고 심지어 맛도 있고 올때마다 너무 예쁘고 기분 좋은 카페💝', 43, 3, 'GOOD', SYSTIMESTAMP);
