INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '인테리어 외에는 특별하지 않았던.. 그리고 전체적으러 직원들 말투가 불친절 디저트 한개밖에 안먹어봣지만 내가 먹은건 디저트 생김새에만 집중하느라 그런지 무맛…', 58, 13, 'BAD', SYSTIMESTAMP);
