INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '인테리어 너무 예쁘고 천원 추가하면 주는 지지 고양이 얼음이 너무 귀여워요. 지브리 굿즈도 다양하게 팔아서 음료 기다리며 구경하는 재미도 있어요! 가시면 꼭 아아 시키셔서 고양이 얼음 추가하시길…!! 커피도 생각보다 맛있었어요!', 7, 9, 'GOOD', SYSTIMESTAMP);
