INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '완전 맛있고 분위기가 좋아요! 사장님도 짱짱 친절하시고 예쁜 물건들도 많이 팔아서 너무 좋은 카페인 것 같아여❤️ 번창하세여 사장님❤️❤️❤️❤️❤️', 80, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '골목에 이런 카페가 있다는게 너무 신기하고 외관부터 이쁘더라구요!! 들어오자마자 눈에 띄는 디저트들이 한가득에 굿즈 구경도 할 수 있고 지브리 덕후로써 너무 행복합니다😍', 13, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '4월 벚꽃 시즌을 위해 출시된 코리코카페 연남점의 벚꽃 세트 먹으러 친구랑 놀러왔어요🌸🍰💓 체리 블라썸 번트 케이크, 벚꽃 라떼, 벚꽃 슈크림 라떼 주문해서 먹었어요. 벚꽃 모양 초콜릿이 올라간 달달한 슈크림 라떼, 딸기 다이스와 핑크색 초콜릿 조각들로 토핑해서 벚꽃나무를 그려넣은 벚꽃 라떼는 정말 달달하고 맛있었고, 푹신한 카스테라 위에 크림이 올라간 번트 케이크는 음료에 비해 생각보다 덜 달아서 달달한 음료랑 같이 먹기 딱 좋았어요. 음료와 디저트의 비주얼도 끝내주고 달달한 맛도 즐기고 코리코 카페만의 독특한 지브리 컨셉 인테리어와 음악도 즐기면서 힐링 제대로 하고왔어요☺️ 4월에 벚꽃이 피고 만개할 때쯤 찾아와서 봄 벚꽃 시즌의 분위기를 만끽해보기 정말 좋은 것 같아요🌸💗', 66, 15, 'GOOD', SYSTIMESTAMP);
