INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '예약 없이 갔는데 굿즈샵 조금 둘러보다보니 들어갈 수 있었어요! 물론 예약없이 들어가시려면 웨이팅 팀이 다 들어가고 나서 입장할 수 있더라구요! 아인슈페너랑 말차&팥 어쩌구는 맛있었구 아메리카노 위에 지지 추가한거 너무 귀엽더라구요....', 43, 1, 'GOOD', SYSTIMESTAMP);
