INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '여자친구랑 첫 연남 데이트인데 좋아하는 키키 캐릭터가 잔뜩이라 바로 눈에 들어왔던 카페예요 내부 인테리어부터 디저트 음료까지 너무나 좋고 지브리 갬성 뿜뿜하네요🫶🏻🥰', 32, 2, 'GOOD', SYSTIMESTAMP);
