INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '여자친구 그리고 친구들과 방문했는데 알고보니 제주에 있었던 곳과 같은 체인점이라는 것을 알았고 특히 굿즈샵이 인상적이었습니다.', 27, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '인테리어가 너무 예쁘고 귀엽고 쿠폰도 뭔가 특별하고 귀여울 거 같아서 받았어요 히히 다음에 또 와야죠!! 메뉴도 예쁘고 맛있어요👏👏', 23, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '입구부터 너무 귀여운 카페 ㅜㅜ 지브리 좋아하시는 분들이라면 추천드려요!! 인테리어 너무 뽀짝하고 어디선가 키키가 나올것만 같은 동화같은 분위기입니다 ㅎㅎㅎ 디저트도 다 너무 예쁘고 음료도 예뻐요 ㅠㅠ 지지 아이스샷은 꼭 추가하기..!! 컨셉 확실하고 예쁜 카페로 추천해요 ㅎㅎㅎ', 74, 15, 'GOOD', SYSTIMESTAMP);
