INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '안녕하세요!! 오늘은 어제 가려다가 실패 했던 지브리 컨셉 카페에 다녀왔습니당! ㅎㅎㅎ 이 카페는 역시 너어어어어어어무 귀엽고 소품들도 하나 하나 다 사고 싶을 만큼 귀엽습니다! 귀여워 하는걸 좋아하시는 분들이라면 다들 이 카페에 꼭 와보시는걸 추천 드려요~!! 그럼 이만 뿅! •~• (* 이 카페는 오후 6시 30분이 라스트 오더 인거 다들 참고해 주세요! )', 33, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '지브리 느낌 엄청나서 너무 좋았어요! 친구와 데이트하기도 너무좋고 연인이랑 와도 엄청 좋을 것 같아요 금요일 점심쯤에가서 사람은 얼마없었고 주말에는 인기 많을것같은...😢', 40, 8, 'GOOD', SYSTIMESTAMP);
