INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '지브리 좋아하신다면 꼭 방문하세요😻 굿즈들도 다양하구 메뉴도 키키 분위기에 맞게 모두 아기자기해요! 대부분 귀여우면 맛이 아쉬운데 여기는 맛도 만족이었답니다:)', 8, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '마녀배다부키키가 제 인생영화인데 그래서 부산에서 서울까지 올라와서 구경했어요 !! 영화처럼 키키가 일하는 빵집과 비슷해서 너무 좋았어요 ㅎㅎ 다음에 또 놀러올게요 ~!', 9, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '라벤더라떼가 기억이 남아서 다시 오고 싶었던 곳이에요!! 평일에 가니까 사람도 없고 좋아요!! 인테리어가 구석구석 넘 예뻐요ㅠㅠ', 42, 3, 'GOOD', SYSTIMESTAMP);
