INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), 'ㅈㄴ별로임 불친절하고 메뉴 얼마나 남았는지 확인도 안하고 주문부터 받음 계속 웨이팅 타령만 하고 음료도 성의 없어요 가격대비 너무 적음', 43, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '지브리 세계속으로 들어온듯한 인테리어와 분위기가 너무 좋아요💕 컨셉에 충실하고 디저트까지 맛있어서 두번째 방문입니다 어느 계절에 와도 항상 만족스러운것 같아요!', 24, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '날씨도 좋고 카페와 디저트는 예쁘고...간만에 맘에 쏙 드는 카페 다녀갑니다. 자몽 들어간 디저트가 아메리카노와 잘 어울리네요.. 딸아이 데리고 다시 꼭 와야겠어요.', 25, 3, 'GOOD', SYSTIMESTAMP);
