INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '지브리를 좋아해서 온 건데, 디저트가 기대 이상으로 맛있었어요! 카페의 모든 공간들이 너무 예뻐서 한 곳 한 곳 다 즐기고 싶었습니다. 다음에 또 오려구요!', 6, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '커피도 맛잇고 레몬 케이크는 아메리카노와 아주 찰떡입니다~~! 매장에 지브리 노래도 나오는데 놀이동산 같고 힐링 하고가요! 직원분도 친절하셔서 좋습니다 다들 연남 오시면 코리코 카페로 오세요❤️ 저두 또 오려구요 ㅎㅎ', 5, 3, 'GOOD', SYSTIMESTAMP);
