INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '우왕~~매장 인테리어도 예쁘고 음료도 귀엽네요 :) 매장이 동화같고 사진도 예쁘게 나와서 외국인분들도 많은데 특히 오늘은 일본분들 많네요 아이스크림 얹어 나오는 음료드실거면 숟가락 챙겨오세요 숟가락이 없대요ㅋㅋㅋ', 25, 4, 'GOOD', SYSTIMESTAMP);
