INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '디저트들이 귀엽고 예뻐서 사진 찍기 좋고 신기한 음료도 있어서 좋았어요!! 나중에 다시 와서 다른 디저트도 먹어보고 싶어요. ㅎㅎ 매장 한 쪽에 굿즈 판매하는 곳이 있는데 거기에도 귀엽고 사고 싶은 것들이 많았어요!! 내부도 잘 꾸며져 있고 건물도 예뻐요. ㅎㅎ', 35, 1, 'GOOD', SYSTIMESTAMP);
