INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '케이크가 너무 귀여워요 ㅎㅎ 안에 굿즈도 팔아서 구경하느라 시간 가는 줄 모르겠어요 ㅋㅋㅋㅋㅋ 딸기히비스커스티 시켰는데 산뜻 상큼하니 넘 마싯었어요 🍓🍓 음악도 좋고 가게도 커서 분위기 넘 좋습니다 🧡🧡 많이 파세요 사장님~', 40, 7, 'GOOD', SYSTIMESTAMP);
