INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '친구랑 카페를 찾아보다가 지브리랑 고양이를 좋아해서 코리코카페에 와보게 되었어요! 디저트랑 음료 너무 맛있었구 인테리어가 아기자기하고 이뻤어요 ❣️ 지지 너무 귀여워요!! 쿠폰에 귀여운 발도장이랑 날짜 찍어주셔서 언제 방문했는지 기억할 수 있어서 좋은것 같아요 다음에 또 방문하고 싶어요 😘', 30, 5, 'GOOD', SYSTIMESTAMP);
