INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '인스타 보고 방문했는데 인테리어 넘 예쁘고 지브리 노래 틀어줘서 분위기 넘 좋아요 라벤더라떼는 처음 봐서 시켜봤는데 아무래도 티로 쓰이는 거여서 밀크티랑 비슷한 느낌이 나더라구요 진짜 맛있었어요 좀 늦게 가서 디저트는 품절된 것이 많아 패스했는데 담에 또 방문하면 디저트도 먹어봐야겠어요..!', 59, 13, 'GOOD', SYSTIMESTAMP);
