INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '키키 좋아하는 분들이라면 맘에 들어하실 카페입니다✨🐈‍⬛ 인테리어도 예쁘고 독특한 메뉴도 많아서 메뉴고르는 재미도 있으니 꼭 와보세요!🎀', 23, 9, 'GOOD', SYSTIMESTAMP);
