INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '지브리를 좋아하신다면 굿즈구경겸 오기 좋습니다! 날씨도 요즘 플려서 야외에서 즐기기도 좋네요. 음악도 지브리 음악이라 데이트 오기 좋아요!', 21, 7, 'GOOD', SYSTIMESTAMP);
