INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '마녀배달부 키키 좋아하는 사람이였으면은 꼭 와야되는 곳 :) 음료 음식들이 다 예쁘고 분위기도 좋아요 영화속에 들어가는 느낌…♡', 10, 7, 'GOOD', SYSTIMESTAMP);
