INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '지브리 컨셉카페를 가자는 말에 왔는데 입구부터 컨셉이 뚜렷하고, 분위기도 좋았습니다. 커피랑 디저트도 생각보다 맛있어서 좋았습니다만 사진찍기 좋은 타르트는 2시30쯤이면 모두 품절이니 일찍 가시는걸 추천드립니다.', 2, 5, 'GOOD', SYSTIMESTAMP);
