INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '지브리 공식 마녀배달부 키키 카페 또 가고 싶어요ㅠㅠㅠ디저트도 맛있고 눈호강까지 최고네요 지지 쿠션, 접시 저그 다 사왔어요 텅장 됨 ㅠㅠ', 57, 14, 'GOOD', SYSTIMESTAMP);
