INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '여자친구가 지브리 마녀배달부 키키를 제일 좋아해서 테마 카페 방문 겸 갔다왔는데 되게 인테리어가 좋네요. 데이트하기 정말 좋아보입니다. 여자친구가 지브리 감성 좋아하면 꼭 데려와보세요 ㅎㅎ', 28, 8, 'GOOD', SYSTIMESTAMP);
