INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '입구부터 분위기 완전 미쳤고여ㅠㅠㅠㅠㅠ 들어가자마자 진짜 구경거리 한가득이햐.... 텅빈 내지갑..커피도 넘 마싯구 디저트도 넘 귀엽구 먹기 아까웠어여 담에 돈 넉넉히 준비해서 다 살꺼야...ㅋㅋㅋㅋㅋㅋㅋ', 42, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '사실 모양이 예뻐서 그렇게 기대를하진 않았는데, 미트 파이가 충격적으로 엄청 맛있었어요ㅋㅋㅋㅋ 위에 패스트리가 빠삭 달달하니 너무 좋았습니다. 다음에 다른거 먹어 보러 다시 올 것 같아요.ㅎㅎ', 43, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '전부터 너무너무 와보고싶었던 카페 드디어 방문😭❤️❤️ 사진으로 영상으로 본것보다 훨씬 귀엽구 좋아요 ㅠㅠㅠㅠ 지브리좋아하는 커플은 웁니다😭❤️', 8, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '한번쯤 꼭 와보고 싶었던 코리코 카페에 드디어! 카페 어디서 사진을 찍어도 너무 예쁘고! 디저트 하나하나 넘 귀여워서.. 욕심껏 전부 시켜서 사진으로 남기고 싶었던... 혈당 조심해야하는 어른이라 참았다 진짜 "동심으로 돌아간 기분이었다" - Sij', 130, 22, 'GOOD', SYSTIMESTAMP);
