INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '소품들도 너무 귀엽고 퀄리티도 진짜 좋아요! 디저트도 많이 달지 않으면서 맛있어요 분위기가 애니메이션 속으로 들어온것 같아 진짜 좋아요!', 76, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '마녀배달부 키키 컨셉 카페라고 해서 들려봤어요~! 음료랑 디저트 전부 너무 맛있었어요🥺 라벤더라떼 진짜 존맛탱...💜 매장도 넓고 좋아요! 딱 하나 단점이 있다면, 노래가 몇 곡만 반복재생 되더라고요...? 그게 좀 힘들었어요ㅋㅋㅋㅋㅋ큐ㅠㅠㅠ', 23, 7, 'GOOD', SYSTIMESTAMP);
