INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '진짜 여기는 미첬어요 진짜 아이스아메리카노에 지지 아이스 꼭 추가하세요 진짜 너무 귀여워요ㅠㅠ 그리구 팬케이크도 진짜 맛있구 팬케잌 시키면 키키 포토카드도 주니까 꼭 시키세요🖤', 28, 7, 'GOOD', SYSTIMESTAMP);
