INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '마녀배달부 키키 영화보고 너무너무 가고싶어서 찾아왔는데 안에 지브리 굿즈도 너무 예쁘고ㅠㅠㅠ 디저트도 너무 귀엽고 맛있었어요! 음료도 같이 시켜서 먹었는데 친구들 모두 다 만족한 카페였습니다~~ 감사합니다💕', 40, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '제주점만 가봤었는데 연남점은 또 느낌이 다르네요ㅎㅎ 근처에 살면 더 자주 올텐데 아쉬워요ㅜㅜ 그래도 평일 낮에 방문하니 사람도 많지 않고 좋았어요! 디저트는 너무 예뻐서 먹기 아쉽지만 키키ost를 들으며 먹으면 너무너무 맛있어서 두번 세번 먹고 싶어집니당.. 다음에 또 올게요오~~', 1, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '지브리 좋아하는 사람은 완전 추천이에요! 키키 테마 음료랑 케이크도 너무 예쁘고 안에서 굿즈들도 많고 넘 예뻐요! 사진 찍을 곳 많고 사람도 많아요..! 기대 안하고 퐁당 쇼콜라도 진짜 맛있어요🔥🔥🔥', 47, 2, 'GOOD', SYSTIMESTAMP);
