INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '아침 일찍 방문했는데, 겨울느낌 가득한 카페도 너무너무 이쁘고 지브리 느낌에 맞게 노래 선곡도 너무 잘 되어있어서 들을때마다 자연스럽게 기분이 좋아지는 것 같았어요! 디저트랑 커피도 모양만 이쁜 게 아니라 맛까지 너무너무 좋아서 가족끼리 오기도 좋을 것 같구, 인테리어랑 테이블 배치, 중간중간 놓여진 소품까지도 지브리 세계관 속에 들어온것 같아서 굉장히 만족스러웠습니다♡♡', 12, 7, 'GOOD', SYSTIMESTAMP);
