INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '지브리컨셉에 인테리어도 아기자기하고 너무 귀여워요😁😁 지브리 덕후라면 무조건 방문 ㄱㄱ 마지막 손님으로 입장했는데 주말 5시쯤엔 웨이팅 마감하더라구요 주말에 방문하실려면 서둘러야할거 같아요', 112, 23, 'GOOD', SYSTIMESTAMP);
