INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '동생이랑 서울에 놀러와서 꼭 와보고싶었던 코리코카페에 왔는데, 분위기가 너무 예쁘고 좋아요😍 지브리른 좋아하는 팬이라면 누구나 좋아할 것 같아요! 직원분들도 친절하시고 만족합니다.', 6, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '친구랑 방문했는데 입장하는 입구부터 너무 예쁘고 기분 좋았어요🥺🫶 매장 내부도 아기자기하게 잘 꾸며져 있는데 넓고, 시원한 장소에서 노래도 지브리 노래들이 나와서 즐거웠습니다!', 1, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '디저트와 음료가 예뻐요!  예쁜데 맛있어요! 지지샷 얼음도 예쁘고, 타르트와 딸기번트케이크도 너무 예뻐요ㅎㅎ 동화속에 있는 기분이에요ㅎㅎ 크리스마스 트리보며 맛있는 디저트먹으니 좋아요ㅎ 또 오고싶어요ㅎㅎ', 30, 1, 'GOOD', SYSTIMESTAMP);
