INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '친구추천으로 왔는데 좋아요 굿즈샵이 옆에있어 음료 기다리면서 구경했는데 굿즈들도 너무 귀여웠어요 디저트는 딸기 타르트랑 퐁당 쇼콜라먹었는데 둘다 귀엽고 넘 맛있었어요 안에 소품들도 전시되있어서 좋았어요 음료는 2층에서 먹었는데  아늑해서 좋았어요', 25, 3, 'GOOD', SYSTIMESTAMP);
