INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '그냥 귀여워서 기분이 너무 좋아지는 카페예요,, 구경할 거리도 너무 많고 지갑 탕진할 거리도 너무 많아서 그냥 행복했습니다… 직원분들도 너무 친절하시고 인테리어도 너무너무 맘에 들어요💕', 28, 7, 'GOOD', SYSTIMESTAMP);
