INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '정말 지브리 감성 낭낭한 너무 귀여운 까페에용! 디저트와 음료 둘다 너무 귀엽구 맛있네용! 카페 이곳저곳에 포토존도 많아 사진 찍기에도 좋구 까페 직원분들도 너무 친절하세요 ㅎㅎ 데이트로도 친구들과 함께 오기로도 너무 좋은 까페네요 ㅎㅎ', 38, 1, 'GOOD', SYSTIMESTAMP);
