INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '정말 딱 지브리 풍경 속에 들어온 듯한 느낌이고, 후식도 좋지만 식사 메뉴도 궁금해요 다른 굿즈도 다양하지만 지지 굿즈가 정말 많아요!😆', 11, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '저랑 아이가 지브리좋아해서 소품도구경하고 디저트와음료도 마시러왔어요 아기자기해서 너무 이쁘고 지브리노래도 나오네요!! 잘즐기다갑니다', 82, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '메누도 너무 맛있고 귀여웠어요! 미트파이와 아이스초코를 시켰는데 모두 깔끔하고 플레이팅도 예뻐서 즐거웠습니다. 지브리컨셉 카페라 정말 신기하고 좋은 경험이었네요~', 15, 8, 'GOOD', SYSTIMESTAMP);
