INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '카페 ㄹㅇ 너무 예쁘고 타르트는 예쁘기만 하고 맛 없을 줄 알았는데 맛도 너무 좋아용ㅠㅠ 눈와서 분위기도 미쳤어요 다음 방문때는 딸기타르트 먹어봐야지~~💝🖤💝🖤', 63, 18, 'GOOD', SYSTIMESTAMP);
