INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '사촌이랑 찾아보고 왔는데 들어가능 입구부터 너무 긔엽고 굿즈샵도 따로 있어서 구경도 하고 너무 좋은거같아요!! 직원 분들도 다 착하시고 음료랑 커피도 맛있는거같아요! 이렇게 컨셉을 가지고 카페를 운영하는 곳들은 다 커피나 음료 맛이 아쉬웠는데 코리코는 다르구나 라고 생각 들었습니다 ㅎㅎ 좋은 시간 보내고 가요 ><', 52, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '오픈했을때부터 오고싶었는데 웨이팅 무서워서 이제야 왔네용ㅠ 디저트 별로 기대안했는데(예뻐서) 너무너무 맛있어요!! 말차라떼도 엄청 진하고 베이커리는 예쁘고 맛있어서 너무 힐링이고 행복한 연말 좋은데서 시간 보내고 갑니당! 키키 최고!', 31, 3, 'GOOD', SYSTIMESTAMP);
