INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '진짜~~~와보고싶었는데 분위기도 괜찮았구 귀여운 소품들이 많이 팔고 있어서 구경하는 맛도 있었습니다~지인들 친구들과 맛있게 먹고 갑니다ㅎㅎ 번창하세요~~❤️❤️', 1, 8, 'GOOD', SYSTIMESTAMP);
