INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '외관부터 몽글몽글 그 자체에요ㅠㅠ인테리어도 귀욤뽀짝하고 음료도 맛있습니다ㅠㅠ소품샵도 안쪽에 있어서 화병 하나 구매했습니당!!사진도 잘나오고 꼭 한번쯤 방문해보세요~~', 3, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '지브리를 진짜 진짜 좋아해서 인스타도 팔로우해서 항상 눈으로만 보고있었는데...이번에 기회가 와서 첫 서울나들이에 첫 지브리카페..이러면 안올수가없죠ㅜ.ㅜ 일찍이 오다보니 오픈런을 했지만 그냥 들어온순간 와 이건 지브리 좋아하면 꼭 와야되요 너무 좋아요!! 음료도 상큼 딸기초코는 동생이 너무 맛있게 먹어서 기부니가 좋아요ㅜ.ㅜ 서울은 오기힘들어서 맘먹고 와야하는곳이지만 카페가 계속 있다면 저는 무조건 또 올것이여요!', 7, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '너무 귀여워용💛💛 진짜 지브리 만화 속 집에 온 느낌!! 디저트 커피도 귀엽네요ㅎㅎ 대화하기도 아늑한 느낌이고 좋아요~~ 시간제한응 아쉬운데 사람 없으면 딱히 뭐라 안하는듯해용', 49, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '남자친구랑 오랜만에 데이트하러 나왔는데 날씨도 너무 좋고 케이크도 맛있고 커피도 머무 맛있었어요!! 말차팥 번트케이크 먹었는데 너무달지 않고 적당히 달고 아메리카노랑 잘어울였어요 너무귀엽고 꿈에그리던 동심의 나라에 온거 같아서 정말 좋았습니다🫶🥺💗', 32, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
