INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '인스타에서 여러번 떴는데 최근에야 방문하게 됬어요. 금요일 오후에 방문했는데 붐비지 않고 매장이 너무 귀여워요 :) 다만 아쉽게도 오후에 오면 디저트 선택지가 거의 없어서… 다음엔 좀 일찍 와서 이쁜 디저트 맛보고 싶어요 ☺️', 25, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '어린 시절 보던 동심이 가득한 지브리를 실제로 눈으로 볼 수 있어서 행복한 시간을 보낼 수 있었어요 ! ! 찾아오는 길 근처에 소품샵이 많아서 구경하며 오느라 시간 가는 줄 모르고 왔어요 ~ 💖 데이트하러 한 번씩 꼭 오면 좋을 것 같아요 ~ 추천합니다 ⭐️', 15, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '전에도 여러번 혼자 왓엇는데 외국인분들도 진짜 마니오시고 지브리를 좋아하는 사람들이라면 누구나 만족할거에요! 디저트들도 이쁘고 맛잇어요😋', 102, 24, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '너무 귀여워요…키키에 나오는 카페의 동선을 완벽하기 카피한 건 아니여서 아쉬울뻔 했지만 메뉴들과 그래도 곳곳에 소품들이 아쉬움을 잘 달래줘요 ㅎㅎ 키키 미니케이크는 생일 때 주문해서 먹으려고 눈독들이고 있어요!! 너무 예쁘서 기분이 좋네요 ㅎㅎ', 24, 3, 'GOOD', SYSTIMESTAMP);
