INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '지브리 좋아 인간이 앉아있기에 너무 좋은 분위기입니다... 음료랑 디저트도 너무 귀엽고 맛있어요! 날 좋을 때 다시 한번 오고싶네요.', 1, 2, 'GOOD', SYSTIMESTAMP);
