INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '친구가 추천해줘서 방문했는데 너무 귀여워서 제대로 취향저격한 카페예요!! 디저트도 너무 예쁘고 기념품샵도 있어서 추천해요❤️❤️', 19, 2, 'GOOD', SYSTIMESTAMP);
