INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '지지는 마법에 걸려서 떠나고 키키는 배달갔나봐요 대신, 귀엽구 친절한 직원분들이 있는 곳 !! 데이트 장소로 딱 이에요 ㅎㅎ 옛날에 코리코 카페가 잇엇슨.. 초코 딸기 팬케이크를 머것슨.. 촉촉하고 달콤해서 꿈에서도 머것슨.. 행복햇슨.. 그런데 녹아버린 지지가 나를 쫓아왓슨!! 그래서 머거버렷슨.. 얼음은 맛이 없엇슨.. 그치만 귀여웠슨!!', 20, 2, 'GOOD', SYSTIMESTAMP);
