INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '날씨 좋은 날에 왔더니 햇빛이 들어오면서 엄청 화사하고 정말 분위기가 좋아요👍🏻💕 가격은 좀 있지만 귀여운 디저트들도 많고 굿즈도 있어서 구경하기 좋습니다!', 67, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '스튜디오지브리에서 라이센스 허가 받은 카페에요~주된 테마가 <마녀배달부 키키>라서 카페 전체가 영화 분위기이고 공식 굿즈들도 많이 팔아서 지브리 팬들은 한 번쯤 와볼만 해요. 아메리카노, 레몬번트케이크 주문했는데 맛은 무난했네요~음료 가격은 살짝 비싼 편, 디저트류는 꽤 비싸게 느껴졌어요. 음료와 디저트 메뉴 다 다양해서 선택권이 넓어요~ 1~2층까지 좌석이 꽤 많은 편이지만 외국인 관광객이 많아서 평일이어도 꽤 복작복작하네요. 테이블에는 1시간 30분으로 이용 시간 제한 있다고 적혀있었는데 웨이팅이 없어서 그런지 딱히 신경 안 쓰더라구요. 직원 분들 다 친절하셨고 화장실도 남녀 분리되어 있어 좋았습니다.', 17, 7, 'GOOD', SYSTIMESTAMP);
