INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '오래전부터 방문하고 싶었던 곳인데 친구들과 드디어 방문!!! 내가 마치 애니메이션 속에 들어와 있는 착각을 하게 만드는 장소😆 아기자기함 그자체에요 디저트도 음료도 그냥 팬시 그자체. 앞으로 자주 올거 같아요. 데이트 장소로도 친목장소로도 강추입니다!!!!', 104, 21, 'GOOD', SYSTIMESTAMP);
