INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '인스타에서 보고 찾아왔는데 감성 있고 메뉴도 맛있어요. 대기는 좀 있지만 그럴만한 가치가 있는 카페인거 같아요. 다음에 기회가 되면 또 방문하고 싶어요.', 83, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '직원분들 안내가 너무 친절하고 생각보다 더 귀엽고 사랑스러운 분위기에요!! 메뉴도 많고 시그니처 메뉴가 많고 디져트가 달지 않아서 좋았아여!!', 0, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '제가 제일 좋아하는 애니메이션과 책인 마녀배달부 키키테마여서 혼자서라도 방문했어요. 혼자여도 분위기가 너무 좋아서 행복한 시간 보내고 갑니다! 음료와 디저트도 맛있어요. 무엇보다 예쁜 게 커요', 32, 1, 'GOOD', SYSTIMESTAMP);
