INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '지브리 감성 카페라서 지브리 좋아하시거나 귀여운거 좋아하시는 분들이 특히 좋아하실 것 같아요 내부도 인테리어가 너무 잘 꾸며져있어서 사진 찍기도 좋고 친구들과 와서 구경하기도 좋아요🫶', 53, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '마녀배달부 키키가 곳곳에 있어서 찾는 재미가 있는 카페 입니다 딸기쿠키머그타르트는 품절이어서 못 먹었지만 다음에 와서 꼭 먹어보고 싶어요! 화장실도 깔끔해요 데이트로 추천합니다 :)', 84, 17, 'GOOD', SYSTIMESTAMP);
