INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '오랜만에 가족과 함께 나들이 나왔다가 전부터 가고싶던 까페라 방문했는데 생각보다 대기 시간이 오래 걸리지 않아서 좋았어요. 디저트도 맛있고 분위기도 너무 좋아요', 25, 5, 'GOOD', SYSTIMESTAMP);
