INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '짱이예유 너무 이쁘구,,사람이 많긴해두 많은 이유가 있어요 맛있구 예쁘구 그냥 다 핮니다 너무 조아연🙈🩷🥺너무너무 따숩고 따스하구 이쁘고 다하는집 굿즈들도 너무 기여어', 37, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '지브리만화 좋아하는 초딩딸래미들과 홍대 마실나왔는데 여기 왔더니 너무 좋아하네요^_^ 너무 예뻐서 먹기 아까운 딸기타르트 강추!! 맛있어요', 50, 8, 'GOOD', SYSTIMESTAMP);
