INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '카페가 정말 예뻐요 마녀 배달부 키키를 좋아하시는 분들이라면 당연히 좋아하실 것 같아요. 1층에는 소품샵과 주문하는 곳, 자리가 마련되어 있고 2층에 자리랑 화장실이 마련되어 있어요. 크리스마스에 방문해서 그런지 대기가 매우 길었습니다,,ㅎㅎ 딸기 밀크티? 진짜 맛있어요 (친구꺼 뺏어먹음) 밀크티류가 꽤 맛있더라고요!? 아메리카노도 괜찮았어요~ 케이크는 친구들이 생일이라고 해줬는데 넘 감동이고 귀여웠습니다... 초코무스 케이크 같고 맛있었어요ㅎㅎ', 36, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
