INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '이전부터 가보고 싶었던 연남동 카페 코리코카페에 방문했어요. 웨이팅 있을 수 있다고 했는데 토요일 2시쯤 방문했는데 웨이팅 없이 원하는 곳에 앉을 수 있었어요. 마녀 배달부 키키 굿즈들 보는 재미도 있고 일본여행 갔을때 봤던 굿즈들도 있어서 반가웠어요. 음료랑 쿠키컵타르트도 맛있었어요.', 2, 3, 'GOOD', SYSTIMESTAMP);
