INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '지브리 좋아해서 꼭 와보고 싶었는데 직접 와보니 인테리어랑 음식 둘 다 너무 이뻐요! 음료랑 디저트 두개 다 너무 맛있게 잘 먹었습니다😀😀 다음에도 또 오고 싶어요👍👍', 48, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '아이생일 기념 아이가 너무 오고싶다고해서 방문했어요 너무 아기자기 이쁘고 케이크도 맛나요!! 주차가 안되서 주차장 찾아 아빠는 못들어오고있지만 담에 또오고싶데여!!', 41, 8, NULL, SYSTIMESTAMP);
