INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '아이들이 오고 싶어해서 일부러 방학한 평일에 왔어요 홍대입구쪽에서 걸어오기는 멀어서 택시타고 오니 금방이였구요 네이버지도로 위치 찾아서 오니 딱 이쁜 까페가 있어요!! 직원분들도 너무 친절하시고 아이들이 오자마자 우아아아 하고 좋아해요 사진찍기 좋은 장소가 너무 많아요!!사람이 없어서 눈치 안 보고 구경하고 아이들 로망이 가득한 곳이에요~~!! 진짜 추운날 바람을 뚫고 온 바람이 있어요!!', 18, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '사촌동생들과 서울 투어 중 너무나도 좋아하는 지브리 감성의 카페가 있어서 꼭 가보자 하고 방문했습니다! 분위기도 너무 좋고 디저트부터 인테리어까지 너무 예뻐서 행복한 시간 보냈습니다!', 121, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), 'I usually come to this location as they always have great selection 4 🍹 or 🍨 + 🛍  for Ghilbi stuff. My friends and I came the day after  설날 & we were greeted by this short/thick rude gal working the front. We had a mixture of all different ethnicities, including Korean & all of us were offended by her unprofessional behavior. Snapped at us and seemed pissed @ the 🌎. Need better training on staff.', 2, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '지브리 팬이라 전부터 꼭 한 번 방문해보고 싶었는데 드디어 왔어요! 곳곳에 지브리 캐릭터와 소품들이 가득해 영화 속에 들어온 듯한 기분을 느낄 수 있어요. 특히 카페 이름처럼 ''배달의 키키와 관련된 소품들이 많이 눈에 띄었고, 공간 자체가 따뜻하고 아늑한 느낌이에요!', 90, 15, 'GOOD', SYSTIMESTAMP);
