INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '가게 인테리어도 너무너무너무 귀엽구 특히 가게 안에 있는 지브리샵이 있어서 볼 거리가 더욱더 풍성하고 좋아요! 초코바나나 케이크 맛있어요!💕', 30, 8, 'GOOD', SYSTIMESTAMP);
