INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '분위기도 좋고 디저트도 맛있었어요! 주말에는 사람 많다고 해서 일부러 평일에 왔네요~ 날씨도 좋고 창으로 들어오는 햇살이랑 인테리어가 너무 잘 어울리네요 다음에 또 오고 싶어요!', 18, 2, 'GOOD', SYSTIMESTAMP);
