INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '항상 오려고 벼르고있다가 이제야 기회가 되서 왔는데 이시간대에는 사람이 아직 많지 않아서 좋았어요!! 딸기 지지타르트머그랑 화이트초콜릿모카 먹었는데 너무 달지 않아서 맛있게 싹비웠습니당😍 분위기가 너무 좋고 1층 옆에는 굿즈샵도 있어서 기다리는동안 둘러보기 좋았어요! 다음에 이 근처에 올 일이 있으면 또 들릴 것 같아요ㅠㅠ 입구부터 너무 예뻐서 사진찍기 좋습니다! 사진 찍는거 좋아하시는 사람들은 오면 너무 좋을 것 같아요 지금은 연말이기도 해서 트리도 있고 시즌메뉴도 있어서 연말 기분 제대로 내고 가는 것 같아요!!🥰', 88, 14, 'GOOD', SYSTIMESTAMP);
