INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '주말이라 드물게 웨이팅이 잡혔어요 ㅠ 4시쯤 도착했는데 앞에 8팀이 있어서 쫌 걸렸구요 레몬케이크는 상큼하고 파운드케이크도 포근한게 좋았어요!! 너무 배고파서 팬케이크는 피자로 8등분해서 호다닥 먹어치워버렸어요 ㅋㅋㅋㅋ 다음엔 다른 메뉴도 먹어보고싶네요 :3', 56, 12, 'GOOD', SYSTIMESTAMP);
