INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '너무 아기자기 귀여워요 지브리 노래도 흘러나오고 지브리 덕후로써 방문 좋습니다.제주에서는 지나가다가 보기만 해서 아쉬웠는데 서울로 이번에 오게되서좋아요 지브리랑 키키 좋아하시는 분들은 와보세요 아기자기해요!', 49, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '눈이 많이 오는 날이었는데 갈까 말까 고민하다가 결국 왔습니다 너무 예쁘고 메뉴도 맛있었어요 키키에 들어와 있는 거 같았어요 꼭꼭 오셔용', 32, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '아이가 지브리 만화를 좋아해서 방학이라 평일 일찍 방문했어요~ 일본식 빈티지와 유럽풍이 섞인 감성있는 인테리어와 채광도 훌륭해서 연남동 주변의 사진 스튜디오보다 더 멋진 것 같아요. 디저트들도 귀엽고 퀄리티도 있고, 가격도 괜찮아요! 지브리 팬이 아니더라도 방문하기 좋은 곳이에요^^', 5, 2, 'GOOD', SYSTIMESTAMP);
