INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '인테리어도 너무 예쁘고 귀여운 캐릭터들이 많은 카페에요 ! 케이크도 맛있구 음료도 진짜 맛있습니다ㅏ! 안에 엠디 구매하는 곳도 있는데, 엄청 귀여운 엠디들이 많았어요! 다음에 다시 온다면 꼭 사가겠습니다 😎', 44, 3, 'GOOD', SYSTIMESTAMP);
