INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '지브리 정말 좋아하는데 지브리풍 카페여서 들어오자마자 기분이 너무 좋았어요!! 지지 얼음도 추가했는데 너무 귀여워요 카페 안에 굿즈들도 있어서 구경하는 재미도 있네요 한번쯤 꼭 와볼만한 장소인거같아요🫰', 42, 8, 'GOOD', SYSTIMESTAMP);
