INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '정말 와보고 싶었던 코리코카페 주말 3시쯤 방문하니 웨이팅없이 바로 입장했어요! 내부가 마녀배달부 키키 느낌 물씬 나 지브리 세상에 놀러 온 느낌이라 데이트나 친구들끼리 방문해도 너무 좋을 공간이에요!! 생각보다 디저트도 맛있고, 특히 커피 고소하니 맛있어요~', 97, 19, 'GOOD', SYSTIMESTAMP);
