INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '밥 먹고 근처 카페로 온 건데 오길 잘 한 거 같아요 ! 지브리 느낌 낭낭하구 무엇보다 꾸며 놓으신게 너무 귀엽네요꒰ ⸝⸝ɞ̴̶̷ ·̮ ɞ̴̶̷⸝⸝꒱ 관련 소품들도 팔고 계셔서 구경하기도 좋습니다ㅏ💖', 43, 6, 'GOOD', SYSTIMESTAMP);
