INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '동화마을속에 있는것 같은, 지브리 키키컨셉카페에요~ 매장이 너무 예쁘고, 곳곳에 장식들과 소품들도 깨알귀요미♡ 한쪽에는 굿즈들도 판매하고, 비쥬얼 끝판왕음료들과 귀여운 디저트는 종류들도 많아요~ 아아 위에 지지얼음마져 귀여움ㅋㅋ 커피,오로라에이드 맛있구요~ 초코지지머그타르트도 맛나요♡ 너무 귀여워서 먹기 아까웠음ㅠㅠ 제주 송당동화마을 코리코카페를 작게 옮겨놓은 느낌! 그래서 더 귀여운거같아요~ 요즘같은 날씨에는 테라스좌석도 너무좋지요^^ 공간이 주는 힐링감 최고!!', 16, 9, 'GOOD', SYSTIMESTAMP);
