INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '제가 진짜 지브리에 환장하는 사람인데용... 입장부터 지지 인형이 반겨주고!! 여기저기 마녀배달부 키키와 관련된 것들로 장식되어있어서 카페 구경하는 재미도 있고 케이크도 너무너무 맛있었어요ㅠㅜㅜㅜㅜ 카페 안에 작은 소품샵 같은 곳도 있는데 거기서 이것저것 구경도 하고 진짜 너무 좋았습니당☺️', 34, 3, 'GOOD', SYSTIMESTAMP);
