INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '친구랑 왔는데 사진도 잘 나오고 너무 예뻐요!! 인테리어 대박이에요.. 진짜 동화 속 들어온 듯 마음이 몽글몽글해져요 조금 늦게 왔는데도 직원분이 친절하게 안내해주셨어요!! 음료랑 디저트도 너무 예쁘고 맛도 있어요 진짜 재방문 무조건 할 거에요🥹', 8, 4, 'GOOD', SYSTIMESTAMP);
