INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '(내가) 또간집, 지브리 덕후 취향 저격 📍코리코 카페 이번에는 크림브륄레 팬케이크를 먹어봤는데, 달달하면서도 정말 맛있었어요! 게다가 작은 포스터까지 같이 주셔서 너무 좋았어요🥹 건물 외관과 내부 모두 귀엽고 이번에는 크리스마스 분위기로 가득하더라고요 심지어 진동벨조차도 귀여워서 하나하나 찾아 구경하는 재미있더라고요 지브리 덕후라면 꼭 한 번 들러보세요! :)', 30, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '처음와본 코리코카페! 지지 아이스에 아메리카노 먹었는데 정말 맛있어요! 디자인만 이쁜줄 알았는데 커피도 고소하고 맛있네요😊 다음엔 조금더 일찍와서 품절된 디저트들도 먹고싶어요 ㅠㅠ', 16, 6, 'GOOD', SYSTIMESTAMP);
