INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '아ㅠㅠ 지브리 좋아하는사람한텐 천국이에요.. 진짜 다음에 또올거에요.. 음료도 너무 맛있고 그냥 좋아요ㅠㅠ❤️ 피규어도 질러버렷ㄷr..✨', 55, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '지브리 좋아하는 친구와 왔는데 제가더 재밌게 놀고가요~ 카페도 예쁘고 음료도 맛있네요 지브리 팬들은 물론이고 아니어도 꼭한번 오세요!', 16, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '키키 덕후 심장 남아나질 않는 인테리어에 음식들도 하나같이 다 넘 맛있어서 집앞에 ㅇ있으면 맨날 오고 싶은 정도의 카페에요ㅠㅠㅠ 백년만년 유지되기를❤︎', 0, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '두번째 방문인데 아메리카노 위에 지지 얼음❤️ 너무 귀요워요ㅎㅎ 커피도 맛있고 디저트는 더더욱! 직원분들도 친절하시고 달달한 향이 가득해요', 119, 24, 'GOOD', SYSTIMESTAMP);
