INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '아담하면서 신비하네요 타르트와 번트케이크 맛나네요~ 옆에 소품가게도 다양한 종류로 가득하구요~ 1층도 좋지만 2층이 햇살로 인해 포근함이 가득하네요~', 107, 24, 'GOOD', SYSTIMESTAMP);
