INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '인테리어가 아늑하고 너무 예뻐요🎄마녀배달부 키키가 너무 귀엽네요 📮❤️ 디저트도 너무 귀엽고 음료도 맛있어요 ~ 지브리 좋아하시면 꼭 한번 와보세요 !! 🥰', 84, 14, 'GOOD', SYSTIMESTAMP);
