INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '지브리 좋아해서 데이트로 왔는데 역시 오길 잘했습니다!!! 직원분들 다 엄청 친절하시고 볼거리 먹을거리 매우 만족이에요🥰 아기자기하고 엄청 귀여워서 담에 또 오고 싶어요♡', 116, 20, 'GOOD', SYSTIMESTAMP);
