INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '마녀배달부 키키 팬이라면 꼭 방문하셔야 되는 카페입니다! 카페 내부에서 키키 ost도 계속 나오고 인테리어도, 디저트도 다 너무 너무 귀여워요ㅎㅎ', 17, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '여기왔을때 마당부터 내부까지 마녀배달부 키키랑 하울의 움직이는 성을 포함해서 여러 일본 애니메이션 속으로 들어와있는 기분이라서 진짜 너무 행복했어요 디저트도 진짜 맛있었고 분위기도 평화롭고 아늑한데 넓어서 편하게 있을 수 있었어요..☺️ 직원분들도 너무 친절하셔서 행복함 2배였습니다 완전 강추에요🥰!', 26, 5, 'GOOD', SYSTIMESTAMP);
