INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '키키 좋아해서 오게 되었어요! 주말엔 손님이 많을거같아서 평일에 왔는데 괜찮네요~ 음료랑 디저트도 맛있고 굿즈샵도 너무 예쁘네요~ 다음에 또 올께요~', 84, 15, 'GOOD', SYSTIMESTAMP);
