INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '연인과 함께 방문했는데 지브리 애니메이션 좋아하는 분들이라면 정말 만족할 것 같아요~ 사진도 너무 이쁘게 나오고 아기자기한 소품들이 정말 예뻤습니다! 데이트 코스로 정말 좋았습니다 :)', 50, 1, 'GOOD', SYSTIMESTAMP);
