INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '지브리 중 가장 좋아하는 마녀배달부키키❤️ 배경으로 한 코리코카페 완전 취향저격 지브리 카페 입니다❣️ 크리스마스리스 컵케이크도 진한 말차크림과 초코파운드가 어우러져서 넘넘 맛있어요💚', 75, 18, 'GOOD', SYSTIMESTAMP);
