INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '지브리 애니메이션 너무너무 좋아하는데 할로윈 맞아서 왔어요~ 할로윈 오로라 메뉴 맛있고 컵케이크가 너무 귀여워요! 정말 키키에 나온 빵집에 온 것 같은 분위기예요 판매하고 있는 굿즈들도 하나같이 너무 귀엽습니다', 40, 4, 'GOOD', SYSTIMESTAMP);
