INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '처음 와보는 곳인데 입구부터 지브리 세상에 들어온 것 처럼 너무 예뻐요🫶🏻✨🦄 외관이 너무 예쁘고 초콜릿 팬케이크랑 얼그레이 너무 맛있어용!!😚 따뜻한 차 시켜서 주전자에 워머 끼워주신 배려 너무 좋아요,,, 다음에 또 오고 싶어요~', 26, 8, 'GOOD', SYSTIMESTAMP);
