INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '커피 맛있고 디저트랑 인테리어가 너무 귀여워요. 1층에서 지브리 소품도 팔고 있어요. 많이 혼잡하지 않고 햇볕이 잘 들어서 좋아요', 2, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '코리코카페 연남점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '동화속에 들어온 느낌 아기자기하게 꾸며져 있어서 너무 예뻐요 특히 디저트는 완전 귀엽고 예뻐서 못 먹겠어요 사진 백만장 찍을 각오하고 가야하는 카페입니다', 90, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '지나가다가 외관이 눈에들어와서 온 무슈랑 방문해보니 여기 케이크 전문점임ㅜㅜ 진짜 지금까지 먹은 망고 케이크 중 1등 임  무슈랑 망고케이크 먹어보면 다른 망고케이크 만족못할거임 ㅜ 찐디저트 맛집 발견해서 기분좋음 ^^ 통창이라 답답하지 않고  예쁘신 사장님의 말투와 친절은 덤인곳♡♡ 비오고 눈오늘날 뷰맛집일거같다♡♡', 16, 4, 'GOOD', SYSTIMESTAMP);
