INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '진짜 거짓말아니라 먹어본 케이크 중에 제일 맛있어요ㅠㅠ❤️망고 당도 최고+너무 달지않은 진짜 맛있는 바닐라크림+촉촉한빵시트..그냥 최고에여..레터링 글씨도 너무 예쁜거 보이죠❣다음에 케이크 살일있으면 무조건 여기서 할거에요 이런 케이크 만들어주셔서 감사합니다 사장님', 42, 9, 'GOOD', SYSTIMESTAMP);
