INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '지난 모임때 망고케이크 접한 이후로 다른 케이크도 궁금해서 오늘은 매장방문했어요! 오후시간대에 케이크가 많이 나가서 아쉬웠지만 사장님 너무 친절하시고, 케이크 맛있게 먹고갑니다 키키', 0, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '급하게 당일 3시간 전 연락드려서 주문했어요~ 미니사이즈 주문했고, 4인이 딱 한조각씩 디저트로 맛있게 먹을 수 있었습니다. 미니서이즈라 해도 망고가 엄청 올라가서 묵직했구요, 저 망고크림이 너무너무너무 맛있어요~ 살짝 달달하게 입에서 녹아버리는데 부모님도 너무 맛있다고 다 드실 정도였습니다. 담에 친구 생일 때도 주문하려 해요!!', 5, 9, 'GOOD', SYSTIMESTAMP);
