INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), 'For my birthday I ordered by my self The mango was really fresh also the atmosphere was good Thank you^^', 8, 2, 'GOOD', SYSTIMESTAMP);
