INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '보기에도 예쁜 케이크가 맛도 최고입니다! 케이크 속 샤인머스켓이 파도파도 계속 나와요🍇 정성 가득한 케이크와 레터링부터, 친절하신 안내와 꼼꼼한 포장까지! 친구 생일을 위해 준비했는데, 덕분에 기분 좋게 픽업하고 즐거운 생일 파티까지 이어질 수 있었습니다. 감사합니다!', 12, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '와 여기 미쳤어요 오랜만에 홍대와서 맛있는 빙수가 먹고싶어 찾다가 리뷰가 넘 맛있어보여서 한 번 와봤어요 망고빙수가 22,000원, 케이크들은 8~9000원대로 금액이 있긴 하지만 돈 내고 먹을만한 곳이에요 평일이라 사람이 많진 않은데 주말이면 웨이팅이 길 듯 해요 망고빙수 얼음이 우유얼음이라 더 맛있는 듯 해요 초코케이크는 바나나가 통으로 들어가서 더 색다르고 맛나요!!치즈케이크도 맛있는데 전 초코가 더 맛있는 느낌이에요 망고빙수는 필수에요 여기는 커피는 약간의 산미가 있어요!! 추천해주고 싶은 곳이에요 ㅎㅎ', 43, 4, 'GOOD', SYSTIMESTAMP);
