INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '오늘 세번째 망고 케이크 포장해 갑니다 🥭🥭 다음에는 복숭아로 주문할 예정인데 기대되네요ㅎㅎ 너무 깔끔하고, 느끼하지 않고 제일 좋아하는 망고케잌입니당', 66, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '엄마생일이라 케이크를 샀습니다. 이제 망고가 다 들어가버리는추세라서 걱정이 많았는데요. 이렇게 보기도 좋고 맛도 좋은 케이크를 찾아서 너무 기쁩니다. 돌아가는길이 1시간 좀 넘게 걸린다고 하니 얼음팩도 넉넉하게 넣어주셨습니다. 직원분이 매우 친절하셔서 들고가는내내 기분이 좋았습니다.', 68, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '돔 형태라 이쁘긴한데 ㅜㅜㅜ 밖에 보이는 사각망고는 포 떠서 붙인 망고이고 안에도 망고보다 크림이 한가득. 바닐라빈 맛 가득한 바닐라케잌이란 생각이 드네요. 다른 망고케이크(스트로베리 32 등)들의 망고 가득한 모습을 보다가 실망스럽습니다. 후기가 좋던데 아쉽네요.', 15, 7, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '망고케이크가 너무 먹고싶은데 이제 시즌 끝물이라 열심히 서치해서 예약했어요! 생망고가 가득 들어있고 펄까지 올라가서 비쥬얼이 훌륭해서 넘 좋아요! 다음 시즌 케이크도 먹으러 올게요', 63, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '망고가 너무 먹고싶은데 요즘 안 팔아서 찾아보다 발견하고 예약하고 찾았어요! 망고가 많이 올라가서 너무 이쁘고 가득 들어있고 사장님 무척 친절하세요!! 케이크 종류도 많아서 조각케이크도 맛있어보이네요! 잘 먹을게요:)', 16, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '디저트 러버는 친구와 카페를 갈 때면 항상 디저트 먼저 확인하는 습관이 있답니다. 사장님이 매장에서 직접 케이크를 만드시고, 판매하는 만큼 디저트 퀄리티가 좋았어요! 매장도 오픈한지 얼마 안돼서 깨끗하고, 테이블 간격이 적당해서 다른 테이블과 대화 소리가 서로 들리지 않아 좋더라고요. 요즘 주문 제작 케이크가 참 많고, 기념일마다 꼭 챙기는 필수품이잖아요! 무슈랑은 다른 곳과 다르게 제철 과일로 커스텀 케이크 제작 해주시더라고요. 이번에 친구 결혼 선물로 티아라까지 얹은 케이크를 부탁드렸는데.. 퀄리티 보세요.. 친구가 너무 맛있어서 놀라더라고요! 홀케이크가 부담스러우신 분들은 매장에서 조각 케이크 먼저 접해보시는 거 추천드려용!', 29, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '조카 생일케이크로 주문했습니다. 전날 급하게 예약했음에도 흔쾌히 접수해주시고, 예쁘고 맛있게 만들어주셨어요. 덕분에 생일파티도 즐겁게 하고, 모두 맛있게 나누어 먹었습니다☺️ 청포도와 요거트크림이 아주 넉넉하게 들어있어요. 개인적으로는 과일이 많은건 정말 좋았는데, 크림도 지인짜 많아서 시트와 크림의 밸런스가 조금 아쉬웠어요🥹 시트 비중이 조금 더 있었으면 좋았을 것 같습니다. 그래도 크림과 과일이 모두 신선하고, 부드러워서 가족들 모두 정말 맛있게 먹었습니다😋 네이버 예약 후에도 자세한 내용을 따로 안내해주시고, 당일 픽업할 때도 친절하게 안내해주시고, 이동시간에 따라 보냉재 함께 넣어주셔서 아주아주 좋았습니다. 정말 감사해요! 홀케이크 뿐만 아니라 조각케이크도 먹으러 가볼래요🙌🏻', 87, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '직원분이 엄청 엄청 친절하세요!! 케이크 확인도 시켜주시고 짱... 입니다. 케이크도 너무 예쁘고 정갈해요 ㅠㅠㅠㅠ 모임 케이크로 가져가는데 다들 엄청 기대중입니다,,, 홍대 근처라 더 좋아오 접근성 짱!!!', 4, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '친구 생일케이크로 예약했는데 실물이 더더더 청순하고 예뻐요..ㅠㅠ🤍다음 생일에는 또 망고케이크로 주문해서 먹어보려구요 사장님도 정말 친절하세요 또 올게요 감사합니다🥰', 122, 26, 'GOOD', SYSTIMESTAMP);
