INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '무슈랑 케이크로 기념일 케이크 진짜 만족스럽게 진행했습니다. 비주얼도 고급지고 너무나도 맛있게 잘 먹었습니다. 한번 방문하고 맛있어서 처음 도전하는 망고로 시켰는데 호텔 케이크보다 퀄리티 좋음ㅋㅋㅋㅋ', 85, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '얼그레이 무화과 너무 맛있고, 외관도 이뻤어요! 기념일에 너무너무 만족스러웠네요. 사장님도 친절하셔서 담에 또 구매하러가려구용 ☺️', 7, 2, 'GOOD', SYSTIMESTAMP);
