INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '내돈내산 망고빙수 먹어봤는데 비싼만큼 맛있었어요. 커피도 맛있었어요. 근데 빙수 양 좀 줄이고 가격 좀 낮춰도 괜찮을 거 같네요…', 16, 9, NULL, SYSTIMESTAMP);
