INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '지인 선물로 케이크 주문 예약했어요!🥭 주문한 케이크 너무 맛있어 보여요🤤 사장님도 친절하시고, 매장도 감각적이라 더 있다 가고 싶네요 ㅎㅎ 더운 날 픽업하러 왔다가 잘 쉬다 갑니다〰️ 케이크 맛있으면 제가 먹으러 올게요 ㅎㅎ', 37, 1, 'GOOD', SYSTIMESTAMP);
