INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '망고 생과일 우유빙수   꼭 꼭  먹어보세요.정말 강추천하고  싶어요. 망고 하나 다 들어가  있고  맛도  너무  좋아요.오죽하면 짝이랑 "빙수싸움"ㅋㅋㅋ커플 데이트 하기 좋은  카페^^', 17, 5, 'GOOD', SYSTIMESTAMP);
