INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '케이크 기대 이상으로 예쁘고 먹음직스럽게 생겼어요!! 복숭아 케이크 자체도 흔하지 않고 맛있어서 친구 생일 기념으로 샀는데 시키길 잘한 것 같아요. 🎂🎂❤️❤️', 22, 2, 'GOOD', SYSTIMESTAMP);
