INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '진짜 달지 않은 케이크 맛집을 찾기가 진짜 힘들었는데 여기는 진짜 생과일들을 올려주시고 매일매일 케이크를 만드신다고 하네요. 너무 맛있어서 기념일 홀케이크도 바로 선결제 했습니다! 생크림도 달고 과일도 달면 과일맛이 뭍히기 마련인데 여기는 벨런스를 딱 잘 잡아서 과일의 본연의 단맛을 방해하지 않아서 너무나도 좋아요!!! 맛도리였습니다ㅠㅠ', 105, 25, 'GOOD', SYSTIMESTAMP);
