INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '요즘 망고 케이크에 꽂힌 친구를 위해 생일케이크 주문했습니다 진주 장식까지 완벽✨👏👏👏 친절히 설명해주시고 안내해주셔서 좋았어요 :) 다음에 다른 케이크도 먹어보고 싶네요', 39, 8, 'GOOD', SYSTIMESTAMP);
