INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '급하게 예약한건데 너무너무 잘 먹었습니다 1호인데도 엄청 묵직했던😳 선물 받은 친구도 너무 맛있다고 먹어본 케익 중 최고라고 할 정도였습니다 망고도 많고 감사합니다', 39, 10, 'GOOD', SYSTIMESTAMP);
