INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '과일 케이크 찾다가 검색한 곳인데 케이크가 너무 예뻐서 바로 예약했습니다! 복숭아랑 고민하다가 망고가 유명한듯해서 망고했는데 너무 이쁘고 싱싱해보여요 다음엔 다른 과일 케이크도 맛볼겸 재방문 의사 너무나 있습니당!', 65, 18, 'GOOD', SYSTIMESTAMP);
