INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '남자친구 생일로 케이크 예약했어요! 너무 예쁘고 고급져서 생일케이크로 완벽했어요👍🙌 매장도 넓고 좋아서 데이트하기에도 좋은것같아요😚다음에도 이용할게요🫶', 25, 9, 'GOOD', SYSTIMESTAMP);
