INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '비주얼부터 완벽한 망고 케이크였어요. 생망고가 정성스럽게 올라가 있어서 기념일 케이크로 딱이에요. 망고 자체도 달고 신선했고, 생크림도 부드럽고 깔끔해서 과일이랑 잘 어울렸어요. 안에도 망고 과육이 큼직하게 들어 있어서 만족도 높았습니다. 재구매 의사 있어요!', 10, 6, 'GOOD', SYSTIMESTAMP);
