INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '친구 생일이어서 주문했는데 너무너무 기엽구 생각보다 사이즈도 커서 만족스러워요!! 친구가 망고케이크에 미친 자인데 친구가 너무너무 좋아할 것 같아서 신나요!!!', 108, 19, 'GOOD', SYSTIMESTAMP);
