INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '기념일이라서 케이크 픽업 예약했는데 너무 예쁘구 좋어요...! 망고가 한가득이라 마음이 풍족해지네오 ㅎㅎ 카페 너무 예뻐서 다음에 와서 먹구 가려고요', 42, 6, 'GOOD', SYSTIMESTAMP);
