INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '기념일이라 예쁜 케이크를 주문하고 싶었는데 찾다보니 이렇게 예쁜 복숭아 케이크가!!! ❤️ 복숭아도 아낌없이 올라가 있고 너무 맛있어요ㅠㅠ🥰', 33, 0, 'GOOD', SYSTIMESTAMP);
