INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '크림이 달지도 않고 질리지도 않는 케이크입니다 포장도 꼼꼼히 해 주시고 박스를 여는데 망고 냄새가 확 풍기는것이 입맛이 확 돌았어요 다음번엔 다른 케이크로 맛보고 싶네요', 25, 1, 'GOOD', SYSTIMESTAMP);
