INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '무슈랑에서 주문한 생일 케이크 정말 최고였어요! 🍰 과일도 생크림도 너무 신선해서 한 입 먹자마자 감탄했어요. 과일의 달콤함과 촉촉한 케이크, 부드러운 생크림 조화가 완벽했어요. 특히 위에 올라간 과일이 아낌없이 듬뿍 올라가 있어서 보는 순간부터 기분이 좋아졌습니다. 레터링도 너무 예쁘게 해주셔서 선물하는 사람도, 받는 사람도 모두 만족했어요. 디테일까지 세심하게 신경 써주신 게 느껴졌고, 서비스도 친절해서 감사했습니다. 무슈랑 덕분에 특별한 날을 더 특별하게 보낼 수 있었어요. 재방문 100% 확신하고, 다음에도 꼭 여기서 케이크 주문할 거예요! 💕 좋은 케이크 만들어주셔서 정말 감사합니다!', 130, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '기념일 케이크가 급하게 필요했는데 사장님께서 예약 당일 제작해주셨어요 진짜 비쥬얼 합격 호텔에서 파는 케이크같아요 크림도 슈크림같은데 많이 달지않아서 부모님도 맛있게 잘 드셨어요! 그리고 딸기 이렇게 많이 들어간거 실화인가요 딸기도 진짜 실하고 너무 맛있었어요 덕분에 가족들과 행복한 시간 보냈습니다. 앞으로 기념일 케이크는 무조건 무슈랑입니다. 다음엔 커피랑 조각케이크도 먹으러 갈께요.', 63, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '케이크 너무 예쁘고 귀여워여🫶🏻 과일도 신선하구 매장도 쾌적합니다~~! 조각 망고케이크 때려 뿌셨읍니다.. 증말 맛도리에여...', 66, 17, 'GOOD', SYSTIMESTAMP);
