INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '어머님 생신이라 급하게 생일 케이크 알아보던 중 과일도 많이 올라가고 크림도 맛있다고 해서 예약하게 되었습니다. 후기만큼 크림도 너무 맛있고 망고도 맛있어서 어머님도 너무 만족해 하셨고 무엇보다 레터링이나 데코까지 너무 완벽하게 해주셔서ㅠㅠ 생신 잘 마무리 했습니다 감사합니다🩵🎀', 4, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '홍대 케이크 맛집이에요 ! 홀케이크도 예약 가능해서 케이크 필요할 때 주문 해야겠어요 과일 케이크에는 과일이 통으로 들어가요 😍', 23, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '여저친구 생일이어서 케익 찾아보다가 이곳 망고케익이 후기가 좋아서 예약해서 구매했어요!! 맛은 너무 좋았고 케익도 너무 이쁘고 망고를 아낌없이 넣어주셔서 너무 만족스러웠어요!! 홍대 올때 한번씩 방문해야겠어요!!', 11, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '복숭아 미니로 예약해서 구매했습니다 기념일에 필요했던거라 요청드린 문구도 예쁘게 잘 써주시고 맛있었어요 다음 기념일에는 다른 케익으로 구매 해보려고합니다 ㅎㅎ', 102, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '아내 생일이라 처음으로 케잌을 구매해봤습니다. 케잌 비주얼도 이쁘고 맛도 제가 원했던 담백하면서 적당하게 단 맛이었습니다. 다음에 딸 생일에도 다른 케잌 구매를 위해 방문할까 합니다.', 45, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '홍대에서 카페 가려고 찾다가, 오늘 오픈했다길래 가보니 롯데호텔파티쉐..? 취미가 아닌 생업으로 만들던 케이크.. 첫 입에 “아, 이건 진짜다” 싶었어요. 초코 생크림은 부드러우면서도 깊은 맛이 있고, 제 기준  너무 달지 않아서 정말 깔끔하게 넘어가요. 무엇보다 안에 들어간 바나나가 포인트인데, 눅눅하거나 물러있지 않고 진짜 신선하고 향이 살아 있어서 초코와 조화가 너무 좋았어요. 케이크 전체가 무겁지 않으면서도 만족감이 꽉 차 있고, 뭔가 호텔 디저트 느낌 그대로를 조금 더 편하게 즐기는 기분이었어요. 저는 개인적으로 레몬을 정말 좋아하는데, 다음엔 꼭 레몬머랭케이크도 도전해보고싶어요! 아메리카노랑 조합이 정말루 좋았습니다!!! 만족하고 갑니다!', 51, 12, 'GOOD', SYSTIMESTAMP);
