INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '케이크가 너무 맛있어요! 완전 맛집!! 요즘 카페 케이크 맛집 많지만 이집은 유난합니다!! 커피도 케이크랑 먹기에 딱 잘어울리는 맛이에요. 깔끔하고 향이 진해요~ 햇살 맛집이라 사진도 너무 이쁘게 잘나오네요~🥰', 28, 10, 'GOOD', SYSTIMESTAMP);
