INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '케이크 맛집 햇살 맛집 분위기 맛집! 친구들이랑 오랜만에 홍대에서 만났는데 새로생긴 카페가 있다해서 가봤는데 일단 분위기가 너무 귀엽고 햇살맛집이라 찍는 사진마다 분위기가 너무 좋아서, 아주 만족이었어요 케이크를 좋아해서 친구들이랑 종류별로 주문해서 먹었는데 뭐하나 빠지지않고 맛잇더라구요 저는 딸기랑 망고가 원픽......♡ 커피도 제가 딱 좋아하는 구수함이라서 케이크랑 커피가 아주 찰떡이엇어요 아가들이랑 같이가서 아가들은 딸기라떼 먹엇는데 너무 맛잇다고 잘먹더라구요😀 차분하고 햇살좋은 곳에서 커피한잔 여유갖기 너무 좋은거같아요 다음에 또 올게요! 저히 네명갔는데 다 케이크포장해온건 안비밀😆', 43, 10, 'GOOD', SYSTIMESTAMP);
