INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '예약시간보다 조금일찍갔지만 바로 받을 수 있어서 감사했습니다 ~ 그리고 가까운 편이지만 ~ 아이스팩도 주셔서 좋았어요 ~ 덕분에 멋진 기념일 보내겠네요 ^^', 40, 3, 'GOOD', SYSTIMESTAMP);
