INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '친구 생일이라 예약하고 픽업 했습니다🥳 날이 너무 더워서 보냉백이랑 아이스팩 추가로 구매하고 기다리는데 사장님 너무 친절하셔서 더위가 싹 가셨네요~~ 케이크도 너무 맛있구 담에 홍대갈 일 있음 또 주문하려구여!! 망고 무조건 맛있구 크림도 안느끼해서 순삭했네요😋', 29, 9, 'GOOD', SYSTIMESTAMP);
