INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '케익이 너무맛있어서 N번째방문이에요 냉동이 아니라 생과일도 너무 좋은데 크림 까지 맛있어요 초코바나나케익도 많이 달지않아서 매번 생크림케익과 고민합니다 디저트 땡기는날 또 방문예정이에요!', 30, 8, 'GOOD', SYSTIMESTAMP);
