INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '망고 케이크가 먹고 싶어서 검색 하던 중 알게 된 무슈랑! 다친 상태로 외출이 어려워서 DM 으로 배달로 가능한지 문의 드렸는데, 친절히 방법도 알려 주셔서 편하게 먹을 수 있었습니다😍 느끼하지 않고 망고도 달달하니 최고의 맛 무슈랑💛', 11, 10, 'GOOD', SYSTIMESTAMP);
