INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '친구 생일케이크로 당일 주문하여 방문하였음에도 너무 이쁜 케이크를 준비해주셔서 감동이였습니다ㅠㅠㅠ 너무 이쁘고 다른 디저트들도 너무 맛있어보여서 또 방문할게요!!', 33, 10, 'GOOD', SYSTIMESTAMP);
