INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '지나가다가 너무 예뻐서 들어왔는데 여기 진짜 인생 맛집⭐️⭐️⭐️⭐️⭐️ 디저트도 다 너무 맛있어보여서 잔뜩시켜서 먹었는데 다 너무 맛있어서 깜짝놀랐어요! 분위기도 너무 예쁘고 사진도 다 잘 나와서 대만족! 오랜만에 찐디저트 맛집 찾은 것 같아서 너무 좋아요 케이크 생각나서 다음에 홍대 올때도 또 방문 할 것 같아요!', 12, 6, 'GOOD', SYSTIMESTAMP);
