INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '케이크 비쥬얼이 너무 예술적이라 기분이 좋네요 친절하시고 매장 분위기도 좋구요 익일 주문예약 가능해서 편리해요 기념일 케이크 하기에 좋은 선택인 것 같습니당', 35, 6, 'GOOD', SYSTIMESTAMP);
