INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '와이프가 가게 앞을 오가며 마음에 드는지 꼭 케잌 사오라 하기에 들렀습니다. 일단 케잌 사이즈가 큽니다. 토핑된 과일도 좋고 시트지도 두툼하니 먹음직 합니다. 가격만 보면 비싸다 싶은데 비주얼과 맛을 보면 충분히 가치 합니다. 사장님이 섬세하신지 포장후 상태 확인도 시켜 주십니다. 맛있게 잘 먹겠습니다. ㅎ', 98, 20, 'GOOD', SYSTIMESTAMP);
