INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '케이크 디자인 너무 이뻐요! 신선한 망고에 맛있는 크림까지😋 100일 기념일을 더 빛나게해준 케이크였어요! 만족도 최상입니다⭐️⭐️⭐️⭐️⭐️', 97, 21, 'GOOD', SYSTIMESTAMP);
