INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '친구 베샤때 쓸 케이크 준비했는데 망고러버에게 찰떡인 너무 이쁜 바닐라진주망고케이크!! 맛도좋고 다음에 또 특별한 날 준비하고 싶은 케이크에여🧡👍🏻', 48, 8, 'GOOD', SYSTIMESTAMP);
