INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '급하게 케이크가 필요해서 당일 2시간 전에 예약했는데 예쁘게 준비해주셨어요! 1호 사이즈인데 생각보다 꽤 크고, 망고도 완전 빠방하게 올려져 있어서 군침 나와요 츄르릅! 다음에 또 방문 할게요!', 50, 6, 'GOOD', SYSTIMESTAMP);
