INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '사장님이 맛있고 음식이 잘생겼어요...행복합니다. 케이크 왠일이에요 너무 맛있어요 생일 서비스도 주시고 행복해요 적게 일하시구 많이 버세요❤️❤️❤️❤️❤️', 34, 10, 'GOOD', SYSTIMESTAMP);
