INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '커피는 속쓰려 인간인데 아 여기 커피 쪽쪽 들어가요 굿··· 그리구 유자티는 쓴 맛 제로 달달해서 진짜 최고··· 레몬 머랭 케이크는 비린내 없고 보들촉촉새콤달큰해서 커피랑 궁합이 최고라내요 꼭 꼭 드셔보시구 저두 또 올게요 흐앙 ヽ(；▽；)ノ❤️‍🔥 서비스로 주신 개업 떡이랑 휘낭시에도 넘 마싯게 먹었어요 사장님 대박나세요 ( ’@‘ ) b', 5, 8, 'GOOD', SYSTIMESTAMP);
