INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '홍대 망고케이크 맛집으로 처음 생겼다길래 후다닥 친구들 생일 케이크 픽업하러 왔어요❤️ 사진이랑 똑같이 생겼구 맛도 너뮤 기대되요 앞으로 홍대 올일 오면 여기서만 픽업하께요❤️', 8, 5, 'GOOD', SYSTIMESTAMP);
