INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '키위랑 망고 둘다 좋아하는데 너무 예쁘고 알찬 케잌이에요 가게도 큰길가에 있어서 찾기 쉽습니다 직원분들도 친절해요 많이 달지 않고 맛있습니다', 41, 8, 'GOOD', SYSTIMESTAMP);
