INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '전화로 당일 예약 문의하고 3,4시간 후 찾으러 갔는데 친절하게 응대해주시고 케이크도 너무 맛있었어요! 레터링도 예쁘게 해주셨습니당♡ 더운 날 1시간이 넘는 거리를 이동했던터라 케이크가 녹아서 커팅할때 케이크가 좀 무너지긴 했었지만, 그거 감안해도 맛있는 맛! 진짜 맛있어서 반했어용... 무너지니까 오히려 과일이 와르르 떨어지는데 과일 엄청 많구나 확실하게 느껴져요 ㅋㅋㅋ 사장님께서 얼음팩도 챙겨주시고 나중에 홍대에서 카페갈 일 있으면 여기가서 다른 조각케이크도 먹어보려고요.', 45, 2, 'GOOD', SYSTIMESTAMP);
