INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '케이크가 예쁜데 맛도 좋고… 진짜 담백하고 과일 먹고싶으면 와야겠다 할정도로 과일도 가득이네요! 초코바나나도 꾸덕 그잡채… 케잌 맛집 인정~~ 사장님이 맛있고 케잌이 잘 생겼어요~~~', 12, 4, 'GOOD', SYSTIMESTAMP);
