INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '케이크 예약되는 곳 찾다가 너무너무 맛있어보여서 주문했는데 인생케이크 됐어요…🩷 호텔 케이크 뺨치는 맛이라 먹는 내내 감탄했어요ㅠㅠ 케이크 주인(생일자)와 함께 방문했는데 사장님께서 생일축하도 해주셔서 감동이었어요! 재방문 의사 가득합니다아🫧🩵', 27, 8, 'GOOD', SYSTIMESTAMP);
