INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '집 주변에 케익 맛집이 없어서 슬펐는데 바로 앞에 생겨서 너무 좋아요 .. 다른 후기들이 너무 좋아서 들어왔는데 사장님도 너무 친절하시고 매장도 깨끗하고 분위기가 좋아요! 케익에 과일도 왕창 들어가 있어서 선물받는 친구가 너무 좋아할 거 같습니다.', 23, 5, 'GOOD', SYSTIMESTAMP);
