INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '예약할 때 시간을 잘못 선택했는데 전화로 문의 드리니 친절하게 응대해주셨어요 예약한 시간보다 조금 일찍 갔는데 케이크가 준비 되어 있었어요 매장 분위기가 좋아요!', 135, 45, 'GOOD', SYSTIMESTAMP);
