INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '홍대 근처 망고케이크 검색해서 찾은 무슈랑 !  급해서 전날 네이버 예약했는데 픽업 가능했어요~ 망고도 듬뿍 올려주셔서 맛있게 먹었습니다 가성비 최고에요 추천합니다! 🤍', 23, 8, 'GOOD', SYSTIMESTAMP);
