INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '예약하고 방문했습니다! 조금 일찍 도착했는데도 친절하게 응대해주시고 바로 픽업 가능했습니다! 케이크 실물도 너무 예쁘고 다른 케잌도 너무 맛있어보여서 또 방문할것 같습니다:)', 13, 6, 'GOOD', SYSTIMESTAMP);
