INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '친구랑 밥 먹고 돌아다니다가 진열된 케이크가 맛있어 보여서 들어온 카페에요! 케이크가 높고 과일이 엄청 신선해보여서 더 맛있는 것 같아요ㅎㅎ 분위기도 깔끔하고 좋아요 👍', 77, 16, 'GOOD', SYSTIMESTAMP);
