INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '친구 생일이라 케이크 예약했는데 너무 만족해용~!! 케이크 실물 너무 예쁘고 아직 먹어보진 못했지만… 맛있을 것 같아용!! 카페에서 먹은 커피랑 에이드도 짱맛입니다 👍🏻👍🏻', 42, 7, 'GOOD', SYSTIMESTAMP);
