INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '케이크 주문해서 수령하였는데, 실제로 보니 너무 예뻐서 만족했습니다 :) 맛도 너무 맛있고 주문 잘 한 것 같아 좋았습니다 :)', 15, 4, 'GOOD', SYSTIMESTAMP);
