INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '과일케이크라고 해서 일반적으로 먹는 케이크 정도 생각했는데 시중 케이크보다 과일 3~5배는 많은거 같아요 엄청 막 달고 자극적이거나 인위적이지 않아서 아기도 어른도 잘먹었어요 모임이나 기념일 생일때 과일 케이크 사러 또 오겠습니다', 47, 6, 'GOOD', SYSTIMESTAMP);
