INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '망고 케이크가 먹고 싶어서 급하게 예약했는데 응대도 너무 잘해주시고 케이크도 너무 이쁘게 준비해주셔서 행복한 파티됬습니다 !! 감사합니다 :) 💖', 70, 11, 'GOOD', SYSTIMESTAMP);
