INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '기념일로 케이크 예약했습니다~! 워낙 평이 좋아서 바로 예약했어여!! 너무 예쁘게 준비해주시고 해서 기념일 잘 보낼 수 있었어요! 감사합니다!', 49, 0, 'GOOD', SYSTIMESTAMP);
