INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '망고케이크. 초코체맄0아크. 레몬케이크 먹었는데  빵도 촉촉 생크림맛이  다  조금씩 달라요.  그냥 생므림에 과일만 바꾼게 아닌듯...초코 체리도 맛이 초코맛이 안나는 곳이 많은데 여긴 확실히 나서 좋아요. 빵순이라 케이크도 많이 먹는데   근래 먹은 케이크 중 젤 맛나네요.', 25, 5, 'GOOD', SYSTIMESTAMP);
