INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '매장에서 차 마시고 블루베리케이크 포장해서 먹었어오 케이크전문점이라 그런지 크림도 부드럽고 시트마다 콕콕박힌 블루베리도 무르지않고 신선해서 좋았습미당😋 귀여운 생일파티용품도 다양하게 있던데 친구생일때 케이크주문이랑 같이 구매하러 재방문하겠습니당', 114, 19, 'GOOD', SYSTIMESTAMP);
