INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '케익도 맛있고.. 가격도 적당하다고 생각해요! 정말 과일이 많이 들어가서그런지 가격이 아깝지않아요! 워낙 회사에서 자주 사먹어서 그런지, 이번에 처음으로 예약해서 집으로 가져가려고 포장했는데 안에 과일이 많고 크림은 부드러운데, 고정되는게 없이 움직이다보니까 이동한지 10분만에 이렇게 되더라구요 도보로 그냥 들고가는데 이렇게 되면..음... 띠지라도 둘러주셔야되는거 아닌가싶어요 ㅠ 그부분이 조금 아쉬웠어요,,! 그리고 멜론이 아직 철이 되기 막 직전이라그런지, 생과일은 하나도안달구 크림은 달달하니 오히려 크림이랑 따로놀아서 전에 먹었던 망고나  청포도로 할걸 좀 싶었어욥..! 멜론덕후라 기대했는데 ㅠㅠ 이 두개빼곤 아쉬운거 없어요! 다음엔 다른맛으로 찾아갈게용~~!', 47, 8, NULL, SYSTIMESTAMP);
