INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무슈랑'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '카페 전체적인 분위기도 좋고, 사장님 메뉴 설명 다 해주시고 짱 친절하세요!!! 그리고 케이크 짱맛있음... 🥲 집 근처였으면 무조건 제 생일케이크는 무슈랑에서 샀을거에요 제발 카페 오래 해주세요 사장님!!!!🥹 홍대 갈 때마다 무슈랑만 갈거니까요', 50, 3, 'GOOD', SYSTIMESTAMP);
