INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '매장도 넓고 시원해요 통창뷰라 뷰도 좋고 쾌적해서 좋습니다 커피도 맛있어요 요새 수플레 팬케이크 맛있는 곳 찾기 힘들었는데 복숭아도 통째로 올라가있고 너무 맛있어요 밥 대신 먹어도 배부를 것 같아요!!👍👍', 11, 4, 'GOOD', SYSTIMESTAMP);
