INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '파르페 좋아하는데 파는 곳이 많이 없어 찾아보다가 오게 되었어요~ 과일도 다 신선하구 처음 비주얼을 보면 생각보다 커서 놀랄 수 있는데 너무 맛있습니다! 볼이 흘러내릴 듯한 달달함이에요 디저트 특성상 느끼할 수 있는데 복숭아가 잘 잡아줘서 크게 물리지 않고 먹을 수 있는 거 같아요 사람도 평일인데 꽤 있고 인테리어도 감성있고 예뻐서 좋아요 복숭아에는 씨 없이 크림이 있어서 썰어 먹기에도 크게 불편함은 없습니다! 겨울에는 딸기 메뉴라던데 기대중입니다 파르페 파는 곳이 많이 없어서 그동안 슬펐는데 이런 곳을 찾을 수 있게 되어 너무 좋습니다🫶🏻', 23, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '홍대 디저트 맛집 중 단연 최고예요! 복숭아밭 수플레 팬케이크는 푹신한 수플레 위에 달콤한 복숭아와 모찌, 크림, 하겐다즈 아이스크림이 어우러져 입안에서 진짜 ‘사르르’ 녹아요. 과일도 정말 신선하고 무게감 있어 식사 대용으로도 손색 없습니다. 카페 내부는 감성적인 인테리어와 넓은 공간, 창가 자리는 포토존 그 자체! 평일 낮 방문했는데도 사람이 많더라구요. 다음엔 딸기 파르페도 꼭 먹으러 가고 싶어요.', 74, 11, 'GOOD', SYSTIMESTAMP);
