INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '딸기시즌때만 오다가 복숭아 시즌엔 처음 와보는데 과일 상태도 좋고 맛도 좋아요 시간이 좀 걸리긴하는데 그거 참고도 또 오게되는 맛 인정합니닼ㅋ 다음에도 또 올게요 번창하세요', 43, 2, 'GOOD', SYSTIMESTAMP);
