INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '작년에 복숭아밭 수플레 팬케이크 먹고 반해서 자주 오고 있어요! 올해 타이밍을 못 맞춰서 복숭아 시즌 끝날까 봐 네이버 톡톡으로 문의 드려서 찾아왔는데 여전히 너무 맛있어요…🥰 다음에 또 올게요!!', 31, 7, 'GOOD', SYSTIMESTAMP);
