INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '홍대 근처에 수플레 맛집 찾다가 베리블리스 한번 와봤어요!! 인테리어도 이쁘고 분위기도 진짜 좋아요😁😁 수플레도 진짜 맛있고 복숭아도 달아서 맛있었어요!! 매장 자체가 엄청 넓었어서 널널하게 앉을수 있었어요. 직원분들도 친절하셨고 정말 맛있게 먹고가요😄😄', 6, 6, 'GOOD', SYSTIMESTAMP);
