INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '복숭아는 흐물거리지 않고 탄탄한 느낌의 물복이였고 상태가 신선하고 시원해서 맛있습니다. 그리고 복숭아 밑 층에는 아이스크림 위에 잘게 부서진 시리얼 같은 게 올라가 있었는데, 이게 바삭거리고 고소해서 복숭아 항이 맴도는 중인 입 안에 변화를 주어서 이 부분이 마음에 들었습니다. 양도 꽤 많아서 모자르다거나 하지 않았어요. 다음번에 다시 와서 다른 파르페 메뉴들도 맛볼 의향이 있습니다.', 112, 22, 'GOOD', SYSTIMESTAMP);
