INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '감성 가득한 인테리어와 함께 모찌수플레의 부드러운 맛에 완전 반했어요. 복숭아 디저트가 정말 상큼하고 맛있어서 복숭아 러버라면 무조건 좋아할 곳! 홍대 오면 꼭 들러야 할 힐링 카페, 베리블리스 강력 추천해요 🍑💕', 44, 4, 'GOOD', SYSTIMESTAMP);
