INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '정말… 정말 정말 정말 좋았어요 이렇게 맛있는 수플레를 먹을 수 있어서 행복했어요 물복 딱복 골고루 주시고 크림도 맛나고 저는 로얄 밀크티 먹었는데 친구가 먹은 망고 음료도 정말 정말 맛있었어요 직원분들도 하나같이 다들 친절하시고 상냥하시고 3층으로 되어있는데 공간이 아이코닉하게 분리되어 있어서 좋았네요 꼭 다시 가고 싶어요', 67, 11, 'GOOD', SYSTIMESTAMP);
