INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '어디갈까 고민하다가 맛있어보여서 방문했어요!! 복숭아 철이라서 그런지 복숭아가 너무 달고 부드러워서 맛있었어요ㅠㅠ 모찌수플레도 처음 먹어보는데 너무 맛있었고 하겐다즈 아이스크림 써서 너무 좋았어요!!! 맛있게 먹었습니다😻 말차음료 엄청 맛있어요', 128, 22, 'GOOD', SYSTIMESTAMP);
