INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '모찌 수플레가 너무 궁금해서 왔는데 너무 맛있고 예뻐요~~~ 복숭아 한개가 통째로 똭~~~ 올라가 있어서 수플레가 쓰러지는 바람에 사진을 많이 못 찍어서 아쉬워요 ㅠㅠ', 49, 4, 'BAD', SYSTIMESTAMP);
