INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '친구들이랑 디저트 먹으러 왔는데, 정말 다 맛있어 보여서 고르기 어려웠어요! 고민 끝에 복숭아밭 수플레 먹었는데 진짜 달콤하고 맛있어서 다음에 다른 것도 먹어보고 싶어요! 짱 추천입니다 (매장도 1~2층으로 넓고 시원해요!)', 85, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '커피랑 망고 에이드 잘 먹었습니다 ♥ 커피는 아주 약간 산미가 있는 것 같고, 커피 원두 자체가 맛있어요! 망고에이드는 왕창 달달에 코코넛도 들어가 있습니당', 2, 10, 'GOOD', SYSTIMESTAMP);
