INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '친구랑 둘이 왔는데 다 먹어보고싶은거 겨우 참아서 이정도..ㅋㅋ 물복에 완전 달고 맛잇는걸루 골라서 쓰시나봐요 담에 오면 메론버전도 먹어보고싶고 겨울에 와서 딸기버전도 먹고싶어용 직원분들 너무 다들 친절하시고 카페는 구조가 특이하고 시원하게 냉방도 잘 돌려주시는데 좌석도 많네용 굳굳 조아용', 47, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '수플레가 진짜 맛있었어요! 복숭아 수플레 먹었는데 잘려있는 건 딱복같았고 통 복숭아는 물복이에요! 안에 커스터드 크림도 들어있었고 수플레 자체가 퐁실퐁실해서 진짜 맛있었어요 아이스크림도 너무 맛있었습니다❤️❤️', 3, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '푸딩 진짜 맛있어요..!!! 푸딩만 따로 팔았으면 좋겠네요 합리적인 가격에..🥹복숭아 라떼도 복숭아 자체가 달달하게 씹혀서 맛있었어용 먹기는 좀 불편하지만🥲예쁘고 기분좋은 신기한 경험이었어요 ㅎㅎ', 0, 5, 'GOOD', SYSTIMESTAMP);
