INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '무화과가 신선하고 달아요!! 수플레의 폭신함과 잘 어울립니다. 하겐다즈 아이스크림을 써서 아이스크림을 활용한 메뉴 꼭 추천 드립니다! 1,2층으로 되어있어서 카페 자리도 넉넉합니다!', 13, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '매장이 1층 2층으로 나뉘어져 있고 다른 분위기라 좋아요. 스무디 엄청 새콤하고 수박 주스는 생과일 100% 느낌으로 달달하고 시원했어요. 수플레는 복숭아항 멜론 올려져 있는데 복숭아 너무 맛있어요. 그리고 역시 하겐다즈 짱👍👍👍', 52, 15, NULL, SYSTIMESTAMP);
