INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '카페 넘 아늑하고 좋네용 .. 넓은 편인데 소리도 안 울려서 더 좋아요 카페 넘 예쁨 과일도 맛있어요 .ᐟ.ᐟ 모찌 수플레에 모찌가 킥입니다 ㅎ 예쁘고 맛있는 디저트 였습니당..', 57, 17, 'GOOD', SYSTIMESTAMP);
