INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '더운 여름 복숭아 킬러인데 너무 맛있어요 ㅠㅠ 복숭아 좋아해서 지나가다가 홀리듯 들어왔는데 파르페 존맛ㅋㅋ 자리도 2층까지 있는데 쾌적하고 좋았어요! 더워서 야외는 못가지만 ‎𐨛𐌅𐨛𐌅𐨛𐌅𐨛𐌅ࠅヲ‎𐨛𐌅𐨛𐌅𐨛𐌅𐨛𐌅ࠅヲ 복숭아 좋아하시는 분들은 꼭 오세요!!', 76, 17, 'GOOD', SYSTIMESTAMP);
