INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '맛잇읍니다... 남자친구랑 왓는데 복숭아 최고 수플레 진짜 퐁실퐁실하고 담콤하고 최고입니더 야호! 2층 완전 하얘서 너무 깔끔하고 너무 친절하시고 첫끼로 먹어도 맛도리', 102, 24, 'GOOD', SYSTIMESTAMP);
