INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '친구 추천으로 홍대 여행을 와서 베리블리스에 처음 방문하게 되었는데요!! 조금 부담되는 가격에 망설였지만 가격만큼의 훌륭한 서비스를 받았다고 생각합니다!! 위에 올려져있는 커스타드 푸딩이 너무 맛있었고, 특히 수플레를 먹을 때마다 입에서 살살 녹는 느낌이 너무 좋았어요! 원래도 팬케이크를 좋아해서 팬케이크 종류라면 안 가리고 다 먹었는데 베리블리스 수플레 팬케이크도 너무 맛있었던 것 같아요🥹 그리고 청포도 에이드에 탄산 추가 되있는 거 너무 감다살 메뉴 선정이라 좋았습니다😍 수플레를 먹다보면 점점 물릴 때가 있는 데 그때마다 탄산으로 충전해주면 정말 끝없이 먹게 됩니다😘 근래 먹었던 디저트 중에 비주얼도 그렇고 맛도 그렇고 오래 기억에 남을 법한 디저트 가게 럈던 것 같습니다! 앞으로도 더욱 번창하세요!🍀🍀', 19, 9, 'GOOD', SYSTIMESTAMP);
