INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '카페 공간도 2,3층까지 있어서 넓고 쾌적하고 좋았어요! 음료도 맛있구 복숭아 치즈 케이크도 너무 맛있었어욤 …🍑 노래 선곡도 좋고 카페도 조용하니 친구랑 수다 떨기도 좋았어요!!!!!!', 66, 14, 'GOOD', SYSTIMESTAMP);
