INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '비주얼이 미쳤어영 모찌는 모르겠고 수플레랑 복숭아는 맛있었어요 매장이 시원해서 좋아요 세명이상 가면 좌석앉기가 어려워요 두명까지만 괜찮음!', 40, 0, 'GOOD', SYSTIMESTAMP);
