INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '음료에 진짜 과일이 들어가서 더 풍미있고 맛있어요~! 음료 안에 곤약..?도 들어가 있는 거 같은데 음료랑 너무너무 잘 어울리고 더 맛있게 느껴졌어요!! 그리고 넓어서 완전 쾌적하답니당', 24, 1, 'GOOD', SYSTIMESTAMP);
