INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '복자 모찌 수플레 주문 후 20분 정도 걸린다고 해서 기다리는 동안 함께 주문한 커피를 먼저 마시면서 기다린 보람이 있는 모양과 맛이었고, 수플레 양이 2명이 먹기 좋았어요.', 33, 7, 'GOOD', SYSTIMESTAMP);
