INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '아메리카노는 깔끔하고 자두에이드는 자두향이 넘 좋아요! 복숭아밭 수플레는 입안에서 사르르 녹는 식감에 달콤한 복숭아 향이 가득해요! 가게 인테리어도 너무 예쁘고 감성 가득해서 사진 찍기 좋고, 기분까지 좋아져요. 맛, 분위기, 감성까지 완벽한 분좋카..꼭 다시 오고 싶어요! 💛', 41, 6, 'GOOD', SYSTIMESTAMP);
