INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '카페가 화이트 인테리어라 진짜 깔끔하고 좋아요!! 직원분들도 친절하시고 2층까지 있어서 자리가 넉넉하구 예약없이 바로 입장했어용 요새 복숭아 철이라서 그런지 복숭아 관련 메뉴들이 정말 많아서 추천합니당 아이스티 위에도 황도를 올려주시는데 정말 달콤하고 맛있었어요 ㅎㅎㅎ 다음에도 수플레 먹으러 오겠습니다!!', 71, 15, 'GOOD', SYSTIMESTAMP);
