INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '부모님,동생과 서울와서 음료마실 카페를 찾다가 발견한 곳 인데,분위기도 밝고 대화하며 시간보내기 좋은것이에요!! 친절한 직원분의 안내가 기억에 남는 곳이에요~', 31, 1, 'GOOD', SYSTIMESTAMP);
