INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '홍대카페 베리블리스에 다녀왔습니당..!! 외부부터 딸기가 가득하니 넘모 귀여웠어용..!! 1,2층 큰 카페여서 쾌적한 환경과 깔끔하고 사진이 잘 나오는 인테리어에 노래선곡도 좋아요..!! 친구와 함께, 연인과 함께 데이트 하러 오기 너무 좋은 분위기라서 맘에 쏙 들었죠ㅎㅎ 딸기가 달달하니 음료가 너무 맛있고 신선하니 좋았어요..!! 접근성도 좋은 위치에 있어서 홍대 놀러 왔다가 예쁜 사진두 얻고 좋은 추억도 쌓고 가기 좋아요..!! 담에 또 재방문하고 싶네요..!!', 124, 21, 'GOOD', SYSTIMESTAMP);
