INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '와 너무 맛있어요~ 너무 보들보들하고 제철 과일을 이용해서 넘 입이 즐거워요!! 푸딩도 넘 부들부들하고 달콤해서 행복해요 ㅜㅜ', 8, 5, 'GOOD', SYSTIMESTAMP);
