INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '분위기가 넘 좋아요!!!! 공간도 넓어서 대화하기 좋습니다   딸기 수플레 너무너무 맛있어요ㅠㅠㅠ 딸기가 엄청 많아서 특히 더 좋은 거 같습니다!!!!!!  복숭아 아이스티 위에 복숭아 올려주는 곳 처음이에요.....❤️❤️ 대기 없이 바로 들어가서 안힘들어요 ㅋㅋㅋㅋ  수플레도 완전 뽕실뽕실  받을 때부터 맛있어 보였어요.... 최곱니다 다시 올 거 같은 카페에요!', 37, 6, 'GOOD', SYSTIMESTAMP);
