INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '처음 한 입 먹자마자 식감이 진짜 부드럽고 촉촉해서 놀랐어요. 달지 않으면서도 계란향이 은은하게 나서 부담 없이 먹기 좋았고요. 생크림이랑 같이 먹으니까 조합도 훨씬 부드럽고 고급스러웠어요. 재방문 의사 있습니다. 친구들이랑 또 오고 싶어요', 28, 9, 'GOOD', SYSTIMESTAMP);
