INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '수플레 너무 부드럽고 퐁신퐁신해요! 스무디도 시원하고 맛있어서 여름에 마시기 너무 좋아요🥰 매장도 크고 시원해서 친구랑 수다떨기도 너무 좋아요! 다음에도 또 방문하겠습니다❤️', 56, 15, 'GOOD', SYSTIMESTAMP);
