INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '연인이랑 특별한 날에 딱 맞는 데이트 맛집 발견했어요~ 베리블리스는 분위기부터 로맨틱해서 마음에 쏙 들더라구요! 복자 모찌 수플레 팬케이크 시켰는데 이게 또 프리미엄과일로 만들어져서 그런지 너무 맛있었어요 :) 인테리어도 깔끔하고 넓어서 여유롭게 데이트 즐기기 좋았어요^^ 조만간 다시 갈 거예요!', 24, 2, 'GOOD', SYSTIMESTAMP);
