INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '하겐다즈 초코라떼 시켰는데 음료에 아이스크림도 올라가고 수플레도 너무 이쁘고 맛있어요 얼그레이도 쓰거나 너무 달지도 않고 적당한 밸런스라 맛있어요!', 79, 17, 'GOOD', SYSTIMESTAMP);
