INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '친구들이랑 홍대에서 대박 맛집 찾았어요! 베리블리스라는 곳인데 수플레팬케이크 진짜 미쳤어요 ㅋㅋ 복숭아밭 수플레 팬케이크 먹었는데 비주얼도 핵미남이고 맛도 최고였어요~ 사진 찍기에도 딱이라 인스타에 올리기 좋은 곳이에요 분위기도 아늑하고 세련돼서 친구들끼리 가성비 좋은 카페 찾는다면 강추드립니다 :)', 23, 3, 'GOOD', SYSTIMESTAMP);
