INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '가족끼리 주말 나들이 갔다가 들렀어요 2층 구조로 넓고 아이들 데리고 가기에도 좋아요 신선한 과일 디저트에 애들이 너무 좋아하더라구요~ 한정 메뉴도 있어서 색다른 맛을 즐길 수 있었어요 다음엔 또 가족끼리 가보려구요 ^^', 75, 18, 'GOOD', SYSTIMESTAMP);
