INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '친구랑 처음 서울와서 첫번째 일정이었는데 너무 만족스러웠어요! 프라페도 너무 맛있었고 틀어주시는 노래도 너무 취향이어서 기분좋게 친구랑 대화나누다 왔습니다☺️ 기회가 된다면 다시 오고싶어요😎😍', 35, 3, 'GOOD', SYSTIMESTAMP);
