INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '베리블리스 완전 우리 아지트 돼버렸어요~ 인테리어도 너무 깔끔하고 분위기도 짱! 2층 구조라 공간도 넓어서 사람 많아도 쾌적했어요 친구들끼리 수다 떨기에도 좋고 과일 전문가가 직접 선택한 디저트라 그런지 뭐든 맛있네요^^ 포장해가서 집에서도 먹을 예정이라니까요~', 49, 5, 'GOOD', SYSTIMESTAMP);
