INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '홍대 카페 찾다가 수플레가 너무 맛잇어보여서 오게 되었는데 진짜 후회없어요 ㅠㅡㅠ 아이스티 너무너무 맛잇엇고 수플레가 진짜 부드럽고 퐁신퐁신해서 먹는 내내 미소가 지어지더라구요 ㅎㅎ 강추!!', 3, 0, 'GOOD', SYSTIMESTAMP);
