INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '와 여기 진짜 미쳤어요! 친구들이랑 홍대 다니다가 발견한 곳인데, 분위기 완전 인스타 감성 터짐ㅎㅎ 푸딩 모찌 수플레 팬케이크 먹었는데, 하겐다즈 아이스크림이랑 조합이 JMT였어요! 직원들도 엄청 친절해서 기분 좋게 즐기다 왔네요~ 다음에 또 오고 싶어요!', 53, 12, 'GOOD', SYSTIMESTAMP);
