INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '오늘 친구들이랑 홍대 핫플이라는 베리블리스에 갔어요~ 인테리어 진짜 예쁘고 레전드였어요! 푸딩 모찌 수플레 팬케이크랑 하겐다즈 복숭아 라떼 완전 JMT! ㅋㅋ 직원분들도 엄청 친절하고, SNS에 올리기 딱 좋은 곳이었어요 주차는 안 되지만, 그거 빼곤 대박 만족! 또 갈 거예요~', 24, 10, 'GOOD', SYSTIMESTAMP);
