INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '수플레케익 꼬오오오옥 드세요🍓🍓🍓🍓🍓 딸기도 가득이고 수플레팬케이크 정말 폭신하고 맛있더라고요 가운데 아이스크림도 하 스쿱 툭 올려져 있는데 정말 맛있어오!!!!!!!! 초코라떼에도 하겐다즈 아이스크림이 들어가서 초코향도 강하고 좋네요', 15, 4, 'GOOD', SYSTIMESTAMP);
