INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '가족 모임으로 방문했는데 정말 좋았어요 넓은 공간 덕분에 아이들이 뛰어놀기에도 부담이 없고, 부모님도 좋아하셨어요 주차가 안 되는 게 조금 아쉬웠지만, 계절과일로 만든 음료들이 다 맛있어서 괜찮았던 것 같아요~ 아이들이 복숭아 요거트 스무디를 특히 좋아했어요', 16, 8, 'GOOD', SYSTIMESTAMP);
