INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '베리블리스, 완전 SNS 감성! 친구들이랑 갔는데 푸딩 모찌 수플레 팬케이크가 대박 맛있어서 놀랐어요 ㅎㅎ 하겐다즈 아이스크림 덕분에 고급디저트 제대로 느꼈어요 공간도 넓고 분위기 너무 좋았어요 여기 진짜 레전드, 친구들이랑 자주 가고 싶어요~', 18, 10, 'GOOD', SYSTIMESTAMP);
