INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '아이들과 함께 베리블리스에 갔었는데요, 온가족이 즐길 수 있는 디저트 카페였어요 아이들이 요거트스무디 너무 맛있다고 좋아하더라고요 :) 가게도 크고 편안해서 가족끼리 오랜 시간 머물기 괜찮았어요 직원들도 친절해서 가족 모두 즐거운 시간을 보냈답니다~', 14, 10, 'GOOD', SYSTIMESTAMP);
