INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '친구랑 같이 베리블리스 다녀왔는데, 이게 바로 찐맛집이구나 싶었어요 복숭아 파르페 진짜 상큼하더라고요 가성비도 좋고, 무엇보다 수플레팬케이크가 너무 부드러워서 감동했어요 ㅎㅎ 이런 곳이 홍대에 있어서 너무 좋아요!', 83, 16, 'GOOD', SYSTIMESTAMP);
