INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '여기 완전 레전드 핫플이네요! 친구들이랑 홍대 놀러 갔다가 우연히 발견했는데, 분위기 완전 미쳤어요 과일소믈리에가 직접 선별한 과일이라 그런지 신선도 장난 아니었어요 그리고 포장도 가능해서 집에 가져가서 먹었답니다~ 사진도 잘 나오고 진짜 추천해요!', 7, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '골드망고 파르페가 진짜 레전드! 친구들이랑 가성비도 챙기고 사진도 찍고 대박 만족했어요~ ㅋㅋ 아기자기한 테이블 덕분에 사진도 예쁘게 나오고 다음에 또 갈 계획이에요! 홍대디저트 찾는다면 여긴 꼭 가봐야 해요!', 13, 5, 'GOOD', SYSTIMESTAMP);
