INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '월요일 점심에 친구 따라 들른 카페예요. 2층으로 되어 있어 자리 넉넉하고 조용하게 머물기 좋았어요. 딸기 수플레 많이 달지 않아서 부담 없이 먹었어요. 아이스 라떼는 깔끔하게 마시기 괜찮았어요. 전체적으로 편하게 쉬어가기 좋은 곳이에요.', 19, 6, 'GOOD', SYSTIMESTAMP);
