INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '홍대 핫플 베리블리스 다녀왔어요~ 복숭아밭 수플레 팬케이크 진짜 최고였어요 친구들이랑 갔는데 분위기랑 인테리어까지 완전 예뻤어요^^ 주차는 좀 힘들지만, 이 정도 맛이면 뭐 다 용서되죠! 인스타 올리기 좋은 느낌적인 느낌~ ㅋㅋ', 127, 23, 'GOOD', SYSTIMESTAMP);
