INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '혼자 힐링하면서 놀겸 근처 방문했다가 전에 인스타로 보고 너무 맛있어보여서 지도에 저장해뒀다가 방문했어요! 매장분위기도 너무 좋고 2층 창가자리에 앉았는데 자리로 가져다주시고 결제 할때도 정말 친절하게 응대해주셨습니다🙂 평소에 푸딩이랑 메론을 정말 좋아하는데 두가지가 다들어간 파르페를 먹을수 있어 정말 좋았습니당😆 페르페에 올라간 푸딩도 맛있었고 메론은 적당히 달았어요🙂 제 입맛에는 너무 맛있었고 혼자 오기에도 너무 좋았지만 다음에는 지인이랑 같이 모찌 수플레먹으러 재방문 해야겠어요!!😆', 18, 7, 'GOOD', SYSTIMESTAMP);
