INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '데이트 하러 베리블리스 갔는데 정말 둘이 가기 좋은 곳이었어요 마포에 있는 깔끔하고 넓은 공간 덕분에 편안하게 대화 나눌 수 있었답니다 복숭아 요거트 스무디 마셨는데, 신선한 과일의 향기와 부드러운 맛이 로맨틱한 분위기에 딱이었네요~ 기념일에 다시 가고 싶어요 :)', 17, 0, 'GOOD', SYSTIMESTAMP);
