INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '오랜만에 먹고싶어서 부들부들 촉촉한 곳으로 찾아서 왔어여 근데 아아메가 생각보다 제 스타일이어서 기분 조앗구 수플레듀 맛나고 과일이 짱맛잇앗아어 ~~~ 또 올라구요 쾌적하그 조아여', 49, 8, 'GOOD', SYSTIMESTAMP);
