INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '진짜 맛있어요  완전 퐁신퐁신하고 크림도 진짜 부드럽고 전체적으로 조화가 너무 좋아요 완전 그릇까지 싹싹 먹었어요 인간 청소기가 되었습니다 베리블리스님 합격입니다', 81, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '인스타 보고 저장해뒀다가 드디어 가봤어요. 수플레 팬케이크 위에 생딸기가 잔뜩 올라가 있어서 먹기 전에 사진부터 찍었어요. 내부가 넓어서 북적이지 않고 조용히 대화하기 좋아요. 다음엔 커플 친구 추천해주려구요!', 45, 2, 'GOOD', SYSTIMESTAMP);
