INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '베리블리스에서 복자 에이드 먹었는데 진짜 맛있어요~ 여기는 진짜 인테리어도 깔끔하고 넓어서 친구들이랑 가성비 좋은 데이트하기 딱이에요ㅋㅋㅋ 요즘 계절과일 음료가 대세라서 그런지, 이 카페가 핫한 이유가 있네요^^', 42, 1, 'GOOD', SYSTIMESTAMP);
