INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '친구들이랑 베리블리스 다녀왔어요~ 부모님 모시고 갔는데, 넓은 공간 덕분에 온가족이 편하게 즐길 수 있었어요~ 아이들도 좋아할 만한 메뉴가 많아서 가족끼리 가기 정말 좋아요 계절과일 음료 시리즈도 신선하고 맛있었어요^^', 67, 11, 'GOOD', SYSTIMESTAMP);
