INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '복자스무디 맛있어요 더운 여름에 최공 !!! 방문때마다 수플레 먹었는데 이날은 시간 이슈로 수플ㄹ레 포기해지만 파르페 가격이 수플리 급이라 놀라떠욤', 39, 0, 'GOOD', SYSTIMESTAMP);
