INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), 'SNS에서 보고 친구들이랑 가봤는데 JMT 인정ㅋㅋ 베리블리스 수플레팬케이크가 이렇게 맛있을 줄이야~ 복숭아밭 수플레 팬케이크 시켰는데, 과일 상태가 진짜 최고더라구요 홍대 맛집 찾는다면 무조건 여깁니다!👏', 37, 9, 'GOOD', SYSTIMESTAMP);
