INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '주변 카페를 찾아보다가 알게됐어요!! 오랜만에 만난 친구들과 함께 왔는데 친절하시고 가게도 쾌적하고 디저트도 맛있고 예뻐요!! 연인 친구 가족 모든 사람들과 방문하기 좋을 것 같습니다', 15, 2, 'GOOD', SYSTIMESTAMP);
