INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '홍대 데이트로 베리블리스 가봤는데, 완전 로맨틱하고 둘이 가기 좋은 카페였어요~ 분위기가 조용하고 프라이빗해서 여유롭게 얘기 나누기 좋았어요 과일소믈리에가 선택한 과일 디저트가 정말 맛있더라구요 다음에 또 가고 싶네요!', 331, 29, 'GOOD', SYSTIMESTAMP);
