INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '점심시간에 잠깐 들러서 음료 한 잔 했는데, 생각보다 무난하고 깔끔해요 프리미엄재료를 사용한다고 해서 기대했는데 확실히 맛이 좋더라구요 복숭아 디저트로 오후가 상쾌하게 시작됐어요 서비스도 나쁘지 않았어요', 62, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '와, 베리블리스 진짜 찐맛집임! 친구랑 골드망고 파르페 먹었는데 레전드였어요 ㅎㅎ 여기 인테리어도 아기자기하고 사진 찍기 진짜 좋음 가성비도 짱짱하고 요즘 홍대디저트 중에 여기가 제일 핫한 듯! 주차는 안 되니까 대중교통 추천~', 78, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '전날 회식하고 동료들과 여유롭게 커피 한잔 하러 갔어요 베리블리스는 인테리어가 깔끔하고 편안해서 점심시간에 딱이더라구요~ 주차는 좀 아쉽지만, 친절한 서비스로 만족했어요 디저트는 무난하게 고급디저트 느낌이라 괜찮았어요~', 15, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '종종 생각나서 들르는 곳이에요! 오늘은 평일 점심이라 자리가 널널한데 햇살이 들어서 너무 예쁘네요 과일 수플레 너무 맛있어서 시즌바뀔때마다 돌아가면서 시켜먹고있어요! 딸기랑 무화과 먹어봤는데 오늘은 망고수플레를 시켰어요. 망고 환장하는 두명이서 벌써 침흘리고있어요..🤤🤤 그리고 망고 통째로 올라간 망고스무디도 종종 먹었는데 시킬때마다 눈도 입도 너무 즐겁네요,,🥭🥭 추천합니다🤓', 16, 6, 'GOOD', SYSTIMESTAMP);
