INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '8시쯤 방문해서 1층엔 자리가 많았어요! 30분 정도 걸린다고 했는데 10~15분안에 나왔습니당 디저트 너무너무 맛있고 골 드망고에이드 강추합니다!!!', 17, 1, 'GOOD', SYSTIMESTAMP);
