INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '베리블리스에서 만난 복숭아 요거트 스무디 마셨는데, 로맨틱한 분위기에서 함께하니 더 특별하더라구요~ 넓은 공간 덕분에 조용하고 프라이빗한 데이트를 즐길 수 있었어요 특별한 날 방문하기 좋은 선택이었어요!', 31, 5, 'GOOD', SYSTIMESTAMP);
