INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '와, 여기 진짜 대박이에요! 친구들이랑 홍대 갈 때마다 자주 가는 곳인데요, 베리블리스 수플레팬케이크 진짜 미쳤어요 분위기도 너무 아늑해서 인스타 감성 제대로 느껴져요 복숭아밭 수플레 팬케이크도 비주얼 끝장나요 다음에도 꼭 다시 오고 싶어요 :)', 50, 1, 'GOOD', SYSTIMESTAMP);
