INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '와 여기 진짜 인생맛집이에요! 친구들이랑 홍대 갔다가 우연히 들렀는데, 푸딩 모찌 수플레 팬케이크가 핵맛이라 깜짝 놀랐어요~ 인스타에 올리기도 딱 좋고, 인테리어도 예뿌더라구요ㅎㅎ 하겐다즈 아이스크림이랑 먹으니까 완전 찋맛집 인정^^', 13, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '매장도 깨끗하고 디저트도 이쁘고 맛도 있어요. 푸딩파르페 강추! 솔직히 너무 이뻐서 어떻게 먹나했는데 한입먹자 돌변한 눈빛으로 마구마구 퍼먹어서 처참해졌어요. 진짜 맛도리(๑´ސު｀๑)', 43, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '데이트하기 좋은 분위기의 카페를 찾다가 베리블리스에 갔어요 :) 인테리어가 예뻐서 특별한 날 기념하기 딱이더라구요~ 푸딩 모찌 수플레 팬케이크와 함께 하겐다즈 아이스크림이 있어서 더욱 고급스러웠어요! 데이트 마무리하기에 완벽한 장소였어요~ 다음에 또 오고 싶네요!', 29, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '수플레팬케이크 마싯어욤 복숭아가 너무 말랑하고 달아요 복숭아 안에 커스터드 크림?같은게 들어 있는데 너무 마싯어요ㅜㅜ 다음에 또 방문하고 싶어요🤗🍰🍰', 20, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '너무맛있고매장이청결하고넓어서좋아요~ 음료위아이스크림도하겐다즈라서좋고 직원분들도친절히응대해주셔서좋아요 인테리어도멋스러워서보는즐거움이 있어요', 3, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '홍대 디저트 카페 맛집 베리블리스 다녀온 후기입니다! 말차랑 딸기 조합이 이렇게 잘 어울릴 줄 몰랐어요. 입안에서 고소함과 상큼함이 번갈아 퍼지면서 넘넘 존맛탱이었어요 ,,, 말차 딸기 러버들 무조건 먹어야할 디저트 맛집 추천', 46, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '말차파르페도 너무 맛있고 수플레 케이크도 정말 맛있어요!! 망고 스무디도 생망고로 만든 것 같아 진짜 맛있어요~!! 인테리어도 너무 좋구 자리도 많아요 카페 분위기가 러블리해서 데이트 장소로도 너무 좋은 것 같아요', 42, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '카페투어 중 마지막 코스로 갔는데 분위기가 딱이었어요. 딸기 모찌 수플레 팬케이크는 쫀득하면서 폭신해서 신기했고, 비주얼이 진짜 대박이에요. 내부가 넓어서 북적이지 않고 조용히 대화하기 좋아요. 딸기덕후라면 무조건 강추드립니다!!', 19, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '야외에서 먹었는데 날씨도 좋고 바람도 선선해서 너무 좋았어요. 디저트도 전체적으로 다 맛있었고, 수플레가 너무 푹신푹신하고 부드러워서 다음에도 먹고 싶었어요..!!  파르페도 맛있었지만 사진 찍을 때부터 기울어져 있더니 결국 추락했지만 그래도 맛있게 먹었습니다..!ㅎㅎ', 104, 20, 'GOOD', SYSTIMESTAMP);
