INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '베리블리스에서 복자 스무디 완전 내 스타일! 친구들이랑 베리블리스 다녀왔는데 계절과일을 이렇게 맛있게 만들 수 있다니 ㅎㅎ 주변에 주차 공간은 없지만 마포니까 대중교통으로 해결 가능~ 가격도 가성비 좋고, 핫플레이스로 추천합니다ㅋ', 85, 14, 'GOOD', SYSTIMESTAMP);
