INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '너무 만족했어요 혼자 노는걸 좋아해서 노는도중 목말라서 근처 이쁜 디저트 카페를 찾았는데 거리도 가깝고 특별한메뉴가 있어서 첫방문 해봤는데요! 음료는 제가 좋아하는 음료종류가 없어서 블리스 아이스티 시켰는데 맛이 좀 약한거랑 양이 좀 적은거 빼면 나름 만족했어요 ㅎ 얼음도 작고 둥글둥글한게 귀엽 ㅎㅎ 더치베이비 딸기는 인스타 사진 그대로 나왔고 음료 줄때 더치에 뿌려먹는 시럽을 주시는데 전 좀 더 주셧으면 했어요 ㅠㅠ 그치만 일어나기 귀찮아서 그냥 먹었다는.... 양도 되게 많아서 다 먹지도 못했어요 ㅠㅠ 먹을수 있는 공간은 1층 2층 있는데 2층이 훨 좋아요 2층계단으로 올라가면 중간에서 아늑하게 드실수 있고 높은곳은 날씨 좋은날 햇볕이 좋아요 ㅎㅎ 가격대비 좀 비쌌지만 맛도 좋고 분위기도 좋고 나름 굿굿', 43, 0, 'GOOD', SYSTIMESTAMP);
