INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '친구들이랑 단체로 갔다 왔는데 대박이었어요! 푸딩 파르페 먹었는데 비주얼도 맛도 레전드급 홍대에서 파르페맛집 찾는다면 여기가 최고예요 ㅋㅋ 공간도 넓고 단체석 있어서 편하게 수다 떨고 왔네요 베리블리스 강추!', 24, 6, 'GOOD', SYSTIMESTAMP);
