INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '연인이랑 데이트하러 갔는데, 분위기 너무 좋았어요 2층 구조 덕분에 아늑하고 예쁜 인테리어가 인상적이었답니다~ 디저트도 신선해서 둘 다 만족했어요! 기념일에 또 오기 좋을 것 같아요 :)', 23, 4, 'GOOD', SYSTIMESTAMP);
