INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '매장이 2층까지 있어서 쾌적하게 이용할 수 있어요! 수플레도 너무 부드럽고 맛있네요 :) 과일이랑 같이 먹으니까 넘 잘 어울리는 거 같아요 🍈', 44, 9, 'GOOD', SYSTIMESTAMP);
