INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '말차 좋아해서 기대 많이 하고 갔는데 너무너무 맛있게 먹었습니다 ㅠㅠ 제 기준 홍대 말차 디저트 Top 3 아니 서울 TOP3 안에 들어갈 또또또 간집이에요,, 씁쓸한 맛에 딸기가 쏙 올라와서 입안에서 춤추고 오늘 하루 꿀꿀했는데 덕분에 기분 전환 까지 완료했습니다 !!! 재방문의사 너무너무 있어요', 70, 12, 'GOOD', SYSTIMESTAMP);
