INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '회사 근처에서 점심시간에 들렀는데, 베리블리스 깔끔하네요 과일소믈리에가 고른 신선한 디저트라 그런지 맛도 좋고, 전 메뉴 포장 가능해서 일 끝나고 집에 가져가기도 괜찮네요 주차는 안 되지만, 가성비는 만족스러워요', 37, 1, 'GOOD', SYSTIMESTAMP);
