INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '예전부터 가고 싶었던 곳인데 오늘 친구와 다녀왔어요.매장이 넓고 깔끔해서 오래 앉아있기 편하구요,무엇보다 음료하고 수플레 팬케이크가 너무 맛있어요.여기 방문하시는 분들 팬케이크 꼭꼭 드셔보세요.하겐다즈 딸기도 딸기가 진짜 잘 씹혀서 정말정말 맛있었어요 직원분들도 정말 친절하시구 2층은 창이 트여있어서 전망도 괜찮아욤 덕분에 좋은 시간 보내고 갑니다.감사합니다', 1, 5, 'GOOD', SYSTIMESTAMP);
