INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '너무너무너무 맛있어요 여기 딸기밭케이크가 정말 맛있구 파르페도 너무너무 맛있었어요!! 음료수는 하겐다즈 바닐라 먹었는데 정말 맛있었어요 다음에도 또 올거에요!!', 8, 7, 'GOOD', SYSTIMESTAMP);
