INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '가족과 함께 베리블리스 다녀왔는데, 부모님도 아이들도 좋아했어요! 공간이 넓어서 온가족이 함께 가기 좋고, 과일 디저트가 정말 신선하더라고요 아이들이 먹기에도 안전하고 맛있다며 엄청 좋아했어요^^ 다음에 또 오고 싶어요~', 57, 17, 'GOOD', SYSTIMESTAMP);
