INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '점심시간에 동료들이랑 홍대 쪽 갔다가 들렀어요 베리블리스는 깔끔하고 세련된 분위기가 참 괜찮네요 복숭아밭 수플레 팬케이크 시켰는데, 과일이 정말 프리미엄급이더라고요 서비스도 나쁘지 않았고 여유롭게 즐기기에 딱 좋은 곳인 것 같아요', 21, 3, 'GOOD', SYSTIMESTAMP);
