INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '홍대입구역이랑 가까운 카페입니다. 수플레 케이크가 맛있다고 해서 찾아왔는데, 케이크 종류가 다양하고 맛있어요! 음료도 맛있어서 추천합니다', 15, 3, 'GOOD', SYSTIMESTAMP);
