INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '서울 홍대 놀러왔다가 카페 찾아보는데 딸기수플레 엄청 맛있어보여서 왔어요!! 아이스크림도 맛있구 수플레도 따뜻하게 갓 나와서 맛있어용! 담에 남친이랑 와야겠어요!!', 65, 11, 'GOOD', SYSTIMESTAMP);
