INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '평일 일찍 방문해서 여유롭게 즐겼어요! 매장이 스튜디오처럼 진짜 예쁘고 채광이 좋아서 사진이 잘 나오네요!! 여기에 수플레 비주얼도 맛도 미쳤어요!! 폭신한 식감에 딸기도 싱싱하고 달달하니 맛있어요. 여기에 하겐다즈 아이스크림이 올라간 말차라떼랑 딸기 쥬스인 오롯이 딸기도 완벽했어요! 홍대에 이런 대형 카페 찾기 힘든데 자주 와야겠어요', 45, 0, 'GOOD', SYSTIMESTAMP);
