INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '연인이랑 특별한 날을 보내고 싶다면 여기 추천해요! 베리블리스의 분위기 정말 로맨틱해요~ 파르페도 맛있고 테이블 간격이 넓어서 프라이빗하게 데이트하기 딱 좋더라구요 예쁜 인테리어 덕분에 사진도 예쁘게 나왔어요 ^^', 68, 18, 'GOOD', SYSTIMESTAMP);
