INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '온가족이 베리블리스에서 즐거운 시간을 보냈어요~ 공간이 넓어서 애들 데리고 가기에도 좋고, 파르페 종류가 다양해서 모두의 취향을 맞출 수 있었어요 주차가 좀 아쉬웠지만 가족끼리 오붓하게 디저트를 즐길 수 있어서 좋았답니다 :)', 46, 6, NULL, SYSTIMESTAMP);
