INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '레전드 상황 발생해버렸습니다.. 역대급 수플레와 스무디가 등장해버렸어요ㅠㅠ 수플레 한 입 먹고 감탄을 금치 못 했는데 스무디를 마시고 나선 정신을 잃을 뻔 했습니다(너무 맛있어서) 여기 와서 복자 스무디 안 드시면 진짜 인생 절반 손해보시는 거라는 거 명심하셨으면 좋겠습니다!', 8, 3, 'GOOD', SYSTIMESTAMP);
