INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '딸리 모찌 수플레 케이크와 샤인머스켓 에이드 정말 맛있었어요! 부드럽고 촉촉한 수플레도 맛있는데 쫀득한 모찌까지 너무 잘어울렸어요. 샤인머스켓에이드는 너무 달지않고 딱 깔끔하게 상큼한 맛이라 좋았어요. 매장도 넓고 인테리어도 이뻐서 다음에도 또 방문하고 싶어요!', 378, 27, 'GOOD', SYSTIMESTAMP);
