INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '인스타 보다가 너무 맛있어보여서 방문했어요🥺 주말에는 사람이 너무 많아서 못 갔는데, 이번에는 평일이라 바로 입장 할 수 있었어요! 푸딩 모찌 수플레가 품절이어서 복숭아+자두로 주문했는데 너무 맛있어요😭😭 한라봉에이드도 완전 상큼해서 제취향.. 다음에 또 방문할게요🤍', 36, 0, NULL, SYSTIMESTAMP);
