INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '딸기의 제철이 언제 였지~?? 내 기억으로는 노지 딸기는 5~6월이었던것 같은데.. 요즘은 겨울이 딸기 제철~🍓 호텔, 뷔페, 베이커리, 카페.. 온통 딸기로 만든 디저트들의 축제다~ 베리블리스~~🍓🥞 딸기디저트 맛집으로 소문 듣고 찾아왔다 딸기모찌수플레팬케이크를 주문~♡ 쫄깃몰캉 모찌가 얇게 덮혀 나오는데 모찌 이불 위에는 쫀득한 하겐다즈아이스크림과 딸기가 올려져 있고, 모찌 이불 속에는 생크림과 흔들흔들 찰랑거리는 부드러운 수플레팬케이크가 숨어있다 입에서 느낄수있는 다양한 식감들의 폭발이다 딸기는 상콤달콤하고, 모찌는 말캉쫄깃하고, 생크림과 수플레는 부드럽고 촉촉하고, 하겐다즈는 쫀득꾸덕하고,,, 시럽은 달콤하게 혀를 감싸며 녹아들고~~ 그냥 뭐 마구 정신이없다~~ㅎ "자리부터 정하고 주문하세요~"', 6, 2, 'GOOD', SYSTIMESTAMP);
