INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '매장이 넓고 쾌적합니당 1층은 데이트하기 좋고 2층은 여러명이 사용하기 좋더라구요 매장내부도 예쁜데 디저트도 너무 마싯서요 ❤️❤️ 사장님도 친절하세용', 24, 8, 'GOOD', SYSTIMESTAMP);
