INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '가족끼리 행복한 시간을 보낼 수 있는 곳이었어요 넓은 공간 덕분에 애들 데리고 와도 괜찮았고, 아이들이 복숭아 요거트 스무디를 엄청 좋아했어요 재료 덕분인지 정말 신선한 맛이었어요 다음 가족 모임에도 또 가고 싶네요^^', 7, 5, 'GOOD', SYSTIMESTAMP);
