INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '공간이 넓어서 너무 좋고 노래도 틀어져있어서 공간 자체가 주는 느낌이 좋더라구요!! 사실 모찌 수플레 케이크 사진에 홀려서 들어왔는데 너무너무 이쁘고 맛있어요!!!!🎂🍓음료도 맛있어서 여긴 데이트하러 또 올 것 같아요!!!💖', 34, 0, 'GOOD', SYSTIMESTAMP);
