INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '딸이랑   딸기그림에 이끌려 들어온카페 ♡♡ 2층까지 테이블있고 (3층은화장실) 음료가 너무맛나용 특히 망고♡♡ 그리고 카운터직원분께서도 너무친절하셔요!^^ 담에 홍대올때 또오려고요ㅎㅎ', 19, 4, 'GOOD', SYSTIMESTAMP);
