INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '연인이랑 데이트하기 좋은 곳 찾는다면 베리블리스 추천드려요 :) 분위기 진짜 로맨틱하고요, 말차망고 파르페가 제일 맛있었어요~ 테이블 간격이 넓어서 프라이빗한 느낌도 좋았고, 예쁜 인테리어 덕분에 데이트 내내 기분 좋았어요!', 5, 3, 'GOOD', SYSTIMESTAMP);
