INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '간만에 만난 친구들이랑 베리블리스 다녀왔어요! 인스타에서 보던 그대로 산뜻한 인테리어가 대박이더라구요~ 팬케이크랑 에이드 시켜서 먹었는데 과일이 아주 신선하고 맛있어서 놀랐어요! 홍대 가면 꼭 다시 갈 듯!', 48, 3, 'GOOD', SYSTIMESTAMP);
