INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '지인과 밥먹고 카페를 찾던중에 우연이 들어오게되었는데, 수플레 너무 맛있어요!! 딸기먀 따로먹었을때도 너무 달고 같이먹어도 맛있고 맛도리입니다👍 자리도 많고, 자리도 넓어서 너무 좋았습니다💕 다음에 낮에도 한번 와보고싶어요~', 55, 16, 'GOOD', SYSTIMESTAMP);
