INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '여기는 진짜 JMT ㅋㅋㅋ 친구들이랑 SNS에서 보고 바로 와봤는데, 대박 이었어요 복숭아 파르페는 완전 프리미엄재료로 만든 느낌이라 맛있었어요~ 분위기도 깔끔해서 인생샷 찍기 딱이네요 다음에 또 올 거예요!', 12, 5, 'GOOD', SYSTIMESTAMP);
