INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '주말에 연인과 함께 베리블리스에 다녀왔어요 :) 아기자기한 인테리어가 둘이 가서 이야기 나누기 딱 좋더라구요~ 골드망고 파르페와 푸딩 파르페 시켰는데, 과일이 정말 신선하고 맛있었어요! 데이트 맛집으로 강력 추천합니다 특별한 날 방문하기 좋은 곳이에요~❤', 38, 10, 'GOOD', SYSTIMESTAMP);
