INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '홍대에서 케이크맛집이라고해서 들렸어요~ 입장하자마자 맛있는케이크에 눈이 휘둥그레해졌어요 냄새도 좋은냄새고 직원분도 친절하게 응대해주시고 너무 좋았습니다. 딸기라떼 위에올라가는 아이스크림도 하겐다즈로 만들어주시고 딸기전문점 같아서 좋았습니다~😋 완전 딸기파티!! 카페분위기도 너무좋고 다음에 홍대오면 또 방문하겠습니다~~😊😍🥳', 34, 0, 'GOOD', SYSTIMESTAMP);
