INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '데이트 코스로 완전 추천하는 베리블리스! 인테리어가 고급스럽고 로맨틱한 무드가 가득해서 특별한 날 가기 딱 좋았어요! 과일을 듬뿍 올린 팬케이크는 정말 맛있고 비주얼도 예술이네요^^ 데이트 할 때 가는 거 추천 ㅎㅎ', 81, 11, 'GOOD', SYSTIMESTAMP);
