INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '수플레 비주얼에 홀려서 찾아왔던 곳인데 수플레 맛있었어요😎 초코를 좋아해서 초코베리 수플레로 시켰는데 초코 아이스크림이 위에 올라가고, 수플레 안에 초코 크림도 별도로 들어가 있어요! 초코맛 좋아하시는 분들이라면 맛있게 드실 거 같아요~ 수플레 자체가 막 부드러운 느낌은 아니지만 전체적으로 조화롭게 맛있어용 달달합니다👍🏻 매장도 쾌적하고 직원분들도 친절하셔용 다만 디저트가 나오는 시간은 조금 걸리는 편입니다 참고하시면 좋을 거 같아요~!', 23, 0, 'GOOD', SYSTIMESTAMP);
