INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '인스타 보고 너무 맛있고 예쁠것 같아서 왔는데 디저트도 예쁘고 너무 맛있고 사장님이 정말 친절하세요! 다음엔 다른 디저트도 먹어보고 싶어요! 같이 온 친구도 아주 맘에들어 했습니다! 추천합니다!', 72, 17, 'GOOD', SYSTIMESTAMP);
