INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '회사에서 점심시간에 잠깐 들렀어요 단체석도 있어서 회식하기 딱 좋겠더라고요 베리블리스의 푸딩 파르페, 정말 무난했어요 인테리어도 깨끗하고 깔끔해서 마음에 들었네요 주차는 불편하지만 분위기는 꽤 괜찮네요', 90, 13, 'GOOD', SYSTIMESTAMP);
