INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '항상 인스타 수플레 맛집, 감성카페 보고 방문했다가 매장도 좁고 웨이팅은 기본이고,,, 생각보다 수플레가 덜 퐁신하고 비린내 나는 경험도 있었는데 여긴 진짜,,, 일본에서 유명한 수플레 맛집보다 여기가 더 맛있어요 ㅠㅠ + 매장도 엄청 넓은 나름 홍대에서 대형카페여서 너무너무 좋습니다 !!', 6, 2, 'GOOD', SYSTIMESTAMP);
