INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), 'ㅋㅋㅋ 친구들이랑 홍대에서 핫플 찾다가 베리블리스 갔는데 개맛있어요! 과일 디저트가 이렇게 맛있을 줄은 몰랐네요 포장 가능해서 남은 건 집에 와서도 먹었답니다~ 무선 인터넷도 잘 돼서 자리 잡고 수다 떨기 딱이었어요 ^^', 42, 2, 'GOOD', SYSTIMESTAMP);
