INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '베리블리스 말차메뉴 전부 주문해서 먹어봤어요  ◡̈ 쌉싸름 말차와 새콤달콤 딸기 조합은 말뭐.. 모찌도 쫀득하니 말차크림도 진해서 맛있게 잘 먹었습니다! 파르페 잼이 너무 맛있어서 깜짝 놀랐어요✧ʕ̢̣̣̣̣̩̩̩̩·͡˔·ོɁ̡̣̣̣̣̩̩̩̩✧ 생딸기 자체가 맛있어서 어떤 메뉴를 시켜도 맛있을 것 같아요!! 분위기도 좋고 야외 날씨 좋으니까 최고네용 잘 먹고 갑니다˃̵͈̑ᴗ˂̵͈̑!!', 9, 2, 'GOOD', SYSTIMESTAMP);
