INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '딸기는 메뉴에 아낌없이 올라갔고, 아이스크림이 하겐다즈라 맛이 없을수가 없었습니다! 너무 달기만한 맛은 아니여서 커피나 차랑 마시면  잘 들어가용~ 딸기 철이 조금 지나서 딸기맛이 살짝 아쉬웠지만 그건 어쩔 수 없으니ㅠ 철에 맞춰서 다시 와보고 싶네여', 76, 12, 'GOOD', SYSTIMESTAMP);
