INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '음료수 맛있고 양도 많아요 !! 수플레도 너무 예쁘고 맛있어서 다음에 또 방문할게요 😘 사장님도 너무 친절하셔서 좋았습니다 강추 !!!!! 수플레가 진짜 진짜 맛있어요 !!', 12, 10, 'GOOD', SYSTIMESTAMP);
