INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '여기 수플레 진짜 찐이에요! 친구들이랑 갔는데 다들 감탄하더라고요! 팬케이크도 부드러워서 최고 ㅎㅎ 과일이 신선해서 그런지 달달하면서도 상큼한 맛이 입안을 가득 채워요 요즘 인기 많은 이유가 있었네요! 다음에 또 갈 예정~!', 38, 4, 'GOOD', SYSTIMESTAMP);
