INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '수플레 팬케이크 좋아하는 친구가 추천해줘서 갔어요. 딸기+말차 조합은 평소에 안 먹어봤는데 은근 잘 어울리더라구요? 우선 소문처럼 수플레 진짜 완벽 그 자체였고, 계절메뉴, 커피들 종류도 엄청 다양하고 매장이 넓어서 찐 만족하면서 먹었습니다 ㅠㅠ 소문내기 싫은데 소문 좀 더 나야겠죠..?', 47, 1, 'GOOD', SYSTIMESTAMP);
