INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '인스타에 많이 떠서 웨이팅 있을까 걱정했는데 평일 오후라 바로 들어갔어요. 수플레 팬케이크가 입에서 사르르 녹고 과일도 엄청 달아서 놀랐어요. 비주얼도 비주얼인데 진짜 ‘맛집’임.', 36, 9, 'GOOD', SYSTIMESTAMP);
