INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '와, 여기 진짜 찐 디저트 맛집이에요! 친구랑 서교동 근처 놀러 갔다가 베리블리스에 들렀는데, 수플레 팬케이크 비주얼이 미쳤어요 ㅎㅎ 과일이 진짜 싱싱하고 팬케이크도 정말 폭신폭신~ SNS에 사진 올리니 친구들 반응도 장난 아니네요! 다음에 또 가고 싶어요 :)', 124, 22, 'GOOD', SYSTIMESTAMP);
