INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '2층 매장으로 올라가서 먹을 수 있는 게 진짜 좋은 것 같아요.. 밖에서 잘 보이지도 않고 공간도 넓어서 정말 좋았습니다!! 수플레는 진짜 수플레의 정석.. 퐁신하고 따듯하고 맛나요 딸기두 맛나고… 무화과 나오면 또 올게용~', 5, 10, 'GOOD', SYSTIMESTAMP);
