INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '여기 완전 대박! 인스타 감성 제대로~ 복자 에이드 먹었는데 진짜 상큼하고 맛있어요 ㅎㅎ 친구들이랑 또 가고 싶어요 마포 핫플 인정!', 30, 8, 'GOOD', SYSTIMESTAMP);
