INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '친구들하고 홍대 베리블리스 다녀왔는데 특히 수플레 맛이 미쳤어요! JMT 그 자체.. 산뜻한 과일과 같이 먹으니까 진짜 맛있더라구요! 내부도 널찍해서 대화하기 편하고, 인스타 감성 뿜뿜하는 인테리어도 대박이에요ㅎㅎ 사진 찍기에도 최적의 장소라 재밌게 놀다 왔어요 ㅎㅎ', 37, 9, 'GOOD', SYSTIMESTAMP);
