INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '베리블리스 완전 데이트 장소로 추천해요! 분위기가 산뜻하고 인테리어 덕분에 고급스러운 느낌이 가득하더라구요~ 우리는 파르페랑 팬케이크 먹었는데, 달콤한 과일과 함께해서 분위기마저 달달해짐! 둘이서 조용히 이야기 나누기에도 딱 좋은 곳이에요~ 꼭 와보세요!', 67, 14, 'GOOD', SYSTIMESTAMP);
