INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '딸기 디저트 덕후라면 주목할 홍대 디저트 맛집 ! 인스타에서 딸기 수플레 팬케이크 본 뒤로 계속 생각나서 결국 주말에 친구랑 다녀왔어요. 수플레가 말도 안 되게 폭신하고 딸기도 엄청 신선하더라구요. 딸기 덕후들 또간집,,,', 20, 3, 'GOOD', SYSTIMESTAMP);
