INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '홍대에서 친구들이랑 놀다가 베리블리스 들렀는데, 여기 찐 디저트 맛집이더라구요! 수플레랑 파르페 진짜 JMT... 과일이 너무 신선해서 놀랐어요~ 인테리어도 예쁘고 사진 찍기 딱 좋았답니다 다음엔 팬케이크도 꼭 먹어보겠음ㅎㅎ', 44, 3, 'GOOD', SYSTIMESTAMP);
