INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '말차파르페가 유명하다고 해서 일부러 찾아간 홍대 베리블리스 말차베리 파르페는 쌉싸름한 말차랑 상큼한 딸기가 진짜 조합 최고였고 수플레도 퐁신 퐁신 그자체,, 왜 홍대에서 유명한 디저트 맛집인지 보여주는 나만의 홍대 또간집이다', 74, 11, 'GOOD', SYSTIMESTAMP);
