INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '처음 방문해봤는데 너무 만족스럽습니다!! 빵 위에 올라가있던 크림과 딸기 아이스크림도 정말 조합이 잘 어울리고 같이 시켰던 아이스 아메리카노와도 잘 맞았습니다! 팬케이크도 주문을 하면 만들어주시는 식으로 하기 때문에 갓나온 따뜻한 팬케이크를 맛보실 수 있습니다!! 친구랑 같이 왔는데 친구도 너무 만족스러워 하네요!! 다음에 또 방문하겠습니다~❤️❤️', 85, 11, 'GOOD', SYSTIMESTAMP);
