INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '처음으로 서울 여행 와서 수플레 먹기로 했는데 여기가 유명하다고 해서 선택했어요! 푸딩 모찌 수플레는 부드러워서 맛있었고 복숭아랑 자두의 조합이 잘 어울려서 좋았어요 다음에 오면 메론 맛으로 먹어보고 싶어요 감사합니다!', 42, 1, 'GOOD', SYSTIMESTAMP);
