INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '딸기밭팬케이크🍓 진심 최고에요ㅠㅠ 주문하고 기다리는 시간은 좀 힘들었지만 기다린 시간이 전혀 안 아까웠어요 그런데 뭐가 문제였는지 이 날 주문한 커피가 다 안되서 다른 음료를 마셨는데 카페인이 넘 고팠던 터라 아쉬웠네요😹 워낙 핫플이라 좌석도 좁고 주문후 대기도 길었지만 그래도 넘 맛있어서 재방문 할 생각입니다아🎶', 7, 10, 'GOOD', SYSTIMESTAMP);
