INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '디저트 진짜 JMT... 친구들이랑 서교동에서 놀다가 들렀는데 인생 디저트집 발견! 수플레도 넘 폭신하고, 팬케이크랑 에이드도 맛있어요 🙂 사진 찍기 딱 좋은 분위기라서 사진도 엄청 찍음 ㅋㅋㅋㅋ', 31, 8, 'GOOD', SYSTIMESTAMP);
