INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '친구가 딸기를 좋아해서 가본곳이에요 딸기수플레, 밀크티, 하겐다즈초코라떼? 먹었는데 일단 수플레 정말 퐁실퐁실하고 맛있더라구요(근데 수플레는 나오는데 2-30분 걸린거같아요. 주문이 밀려서요) 좌석간에 간격이 엄청 좁고 2층까지 있는데 정말 딱 사람이 지나다닐 수 있는 최소한의 공간 빼고 엄청 다닥다닥 붙어있어서 불편해요 그래도 수플레와 함께 음료 잘 먹고 나왔습니다 사람이 그렇게 많은데 직원분들 전부 친절하셔서 기분 좋았습니다 :)', 3, 2, NULL, SYSTIMESTAMP);
