INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '모찌 수플레 팬케이크 먹었는데, 계란맛이 진해서 매우 맛있었습니다!! 수플레도 부들부들하니 두툼했고, 위에 얇은 피가 모찌였는데 같이 먹으니 맛있었습니당! 딸기 맛집답게 딸기 요거트 스무디도 찐딸기가 들어있어서 과즙이 넘치고 맛있었습니당ㅎㅎ 추천드려요~', 70, 15, 'GOOD', SYSTIMESTAMP);
