INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '베리블리스 분위기가 너무 좋아서 시간을 잊고 즐길 수 있었네요 ㅎㅎ 특히 팬케이크는 부드럽고 달콤해서 분위기를 더욱 특별하게 만들어줬어요! 커피도 커플끼리 나눠마시기 딱 좋았어요ㅎㅎㅎ', 79, 15, 'GOOD', SYSTIMESTAMP);
