INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '친구들이랑 같이 가서 베리블리스에서 과일 파르페랑 팬케이크 먹었는데 이거 찐맛집이네요~ 과일이 정말 신선해서 맛이 아주 굿! 사진 찍기에도 완전 예쁘고, 분위기도 세련돼서 친구들이랑 수다 떨기 딱이에요 주차는 좀 불편했지만 그래도 또 갈 거예요! ㅎㅎ', 54, 17, 'GOOD', SYSTIMESTAMP);
