INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '서교동 핫플 인정입니다! 친구들이랑 수플레랑 에이드 시켜서 나눠 먹었는데, 수플레는 진짜 폭신폭신..! 과일도 다 퀄리티가 좋더라구용! 가성비도 좋아서 자주 갈 것 같네요~', 11, 5, 'GOOD', SYSTIMESTAMP);
