INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '<주문메뉴> 딸기모찌 수플레 팬케이크 24,000원 초코베리 수플레 팬케이크 23,000원 제주 한라봉 스무디 7,500원 블리스멜로 6,900원 총 61,400원 엥?다 사고보니 비싸네^^; 진짜 물가 너무 올랐네요 그래도 디저트 포기못해~~~~ 달달이 좋아하시고 하나만 선택해야 한다면 초코베리 수플레 팬케이크 추천!! 딸기모찌는 2% 부족한 느낌...ㅎㅎ 카페 내부 자리는 2층이 전체적으로 예쁘고 테라스 자리 요즘날씨에 최고👍👍👍', 17, 3, 'GOOD', SYSTIMESTAMP);
