INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '카페 넓고 커피랑 케이크 맛있어서 저번에 방문하고 또 방문했어요!! 홍대에 프랜차이즈 카페빼고 넓은 카페 잘 없는데 여기 추천합니다😚', 53, 17, 'GOOD', SYSTIMESTAMP);
