INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '여친이랑 함께 베리블리스 다녀왔어요! 느좋 분위기에 감성적인 공간이라 둘이 가기 너무 좋네요~ 수플레의 폭신함과 과일의 달콤함이 잘 어울려서 기념일에 오기에도 딱이에요! :)', 31, 1, 'GOOD', SYSTIMESTAMP);
