INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '오랜만에 대학 친구랑 수다 떨면서 단 거 땡겨서 찾아간 홍대 카페예요. 말차베리 파르페는 쌉싸름한 말차와 상큼한 딸기 조화가 너무 잘 맞았어요. 인테리어랑 조명도 감성 충만해서 사진도 정말 잘 나와요.', 28, 10, 'GOOD', SYSTIMESTAMP);
