INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '베리블리스 디저트 진짜 대박이에요! 인스타에도 당장 올리고 싶은 비주얼 ㅋㅋ 수플레랑 팬케이크 먹었는데 과일 진짜 신선하고 맛있었어요~ 디저트 맛집으로 강추!', 69, 16, 'GOOD', SYSTIMESTAMP);
