INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '지난 주말에 베리블리스에서 데이트했는데, 진짜 즐거운 시간 보냈어요~ 팬케이크랑 에이드 조합이 참 좋더라구요! 인테리어가 깔끔하고 세련돼서 분위기가 좋았어요~ 제철 과일로 만든 디저트라 신선 그 자체~!', 72, 14, 'GOOD', SYSTIMESTAMP);
