INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '아침부터 친구랑 가서 팬케이크랑 에이드 먹고 왔는데 대박 맛있었어요~ 분위기도 세련되고 인테리어도 예뻐서 사진 찍기 딱 좋은 곳! 과일이 상큼해서 디저트 더 맛있게 느껴졌어요 여기 완전 추천합니다 :)', 3, 4, 'GOOD', SYSTIMESTAMP);
