INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '산뜻한 기분 내고 싶어서 딸기 디저트 생각나서 방문했어요. 딸기 디저트는 말할 것도 없고, 봄 느낌 살린 음료까지 완벽했습니다. 다음엔 오픈런 해서 창가자리에서 여유롭게 커피 마시러 가야겠어요!!', 29, 7, 'GOOD', SYSTIMESTAMP);
