INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '두번째 방문인데 여전히 맛있어요ㅎㅎ 과일들도 신선하고 디저트만 맛있는 게 아니라 음료도 다 맛있습니다! 매장 디자인도 신경쓴 게 느껴지고 서비스도 친절하셔서 복합적으로 좋은 느낌을 주는 가게같아요.', 34, 0, 'GOOD', SYSTIMESTAMP);
