INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '진짜 하겐다즈가 올라가있는 음료랑 디저트라 퀄리티 높아서 좋았어요. 딸기도 달아서 음료랑 같이 먹어도 새콤하지 않아요. 매장이 넓어서 예약 없이 이용해도 될 것 같습니다.', 33, 3, 'GOOD', SYSTIMESTAMP);
