INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '사람이 많을 때 와서 조금 시끄러웠어요. 친구들끼리 수다떠는 데는 문제 없었습니다. 딸기 에이드는 안에 젤리도 있어요. 코코넛 젤리인 듯. 케이크는 빵이 위주인 레몬 프로마쥬 케이크인데 레몬 향이 은은하게 나서 맛있고 단단한 브라우니 식감입니다. 덜 물리는 맛이라 무난하게 맛있습니다', 0, 3, 'GOOD', SYSTIMESTAMP);
