INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '친구랑 같이 베리블리스 갔는데 찐 디저트 맛집~! ㅋㅋ 수플레랑 에이드 너무 맛있고 특히 분위기가 진짜 최고였어요 :) 핫플 인정! 과일이랑 디저트 조합이 미쳤어요ㅎ 다음에는 다른 메뉴도 도전 해보려고요~', 4, 3, 'GOOD', SYSTIMESTAMP);
