INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '가게에 딸기 모양 장식들이 가득 있어서 너무 귀여워요🍓🍓  딸기 수플레를 시켰는데 맛있는 딸기를 잔뜩 올려주셔서 넘 좋았어용 가게도 깔끔해서 친구와 방문하기 정말 좋아요!!🍓🍓', 26, 10, 'GOOD', SYSTIMESTAMP);
