INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '남자친구랑 둘이서 처음 가봤는데요, 와.. 분위기가 일단 넘 좋았어요! 밝은 톤에 깔끔한 느낌이라 너무 좋고, 수플레 맛도 진짜 환상적이에요! 과일의 신선함이 다른 데랑 달라요~ 커피랑 함께 먹으니 또 다른 매력이 있더라구요~ 다음번엔 다른 디저트도 도전해볼 생각!', 123, 22, 'GOOD', SYSTIMESTAMP);
