INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '데이트로 이보다 더 좋은 곳이 있을까요? 베리블리스는 정말 분위기 맛집이었어요! 조용하고 프라이빗한 느낌이라 둘이 가기 딱 좋더라구요! 수플레는 물론이고 커피 한 잔 하면서도 여유롭게 즐길 수 있었어요ㅎ 다음번에도 방문 예정~', 43, 10, 'GOOD', SYSTIMESTAMP);
