INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '친구들이랑 홍대 베리블리스 갔는데 진짜 가성비 미쳤어요 ㅋㅋㅋ 수플레랑 팬케이크 JMT~ 과일 진짜 신선하고 예뻐서 사진 찍기 딱 좋았어요! 다음에 또 놀러 가고 싶어요ㅎㅎㅎ', 72, 15, 'GOOD', SYSTIMESTAMP);
