INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '달달한 디저트가 생각나서 학교 끝나고 방문했던 홍대 베리블리스...! 직접 만든 계절별 디저트들로 가득가득 했습니다! 매장도 1,2 층으로 넓은 대형 카페라 웨이팅 걱정 없고 맛있는 수플레는 입에서 스르르 녹는것이.,,, 행복 그자체네요 ㅎㅎ 이미 근처에서 밥 든든히 먹고 와도 디저트 배는 역시 따로 있나봐요 !! 데이트 하기에도 딱 좋고 북적거리지 않아서 수다 떨기 좋은 그런 홍대 디저트 맛집 :)', 48, 10, 'GOOD', SYSTIMESTAMP);
