INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '오며가며 한번 꼭 와보고 싶었어요 ! 보통 수플레 케이크는 손이 많이 가서 좀 비싸던데 베리블리스는 가격도 나름 합리적이구요 넘 부드럽고 맛있어요 촉촉하고 부드러운 팬케이크, 또 먹으러 올 의사 만땅이에요 추천 !', 10, 8, 'GOOD', SYSTIMESTAMP);
