INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '데이트하러 베리블리스 갔는데, 분위기 정말 최고였어요! 특유의 밝은 인테리어 덕분에 공간이 환하고 로맨틱하더라구요! 수플레랑 커피 시켜서 먹었는데, 디저트의 비주얼이 너무 예뻐서 사진 찍는 재미도 있었어요 ㅎㅎ 조용하고 프라이빗한 시간 보내기에 딱 좋았어요~♡', 39, 1, 'GOOD', SYSTIMESTAMP);
