INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '시험 끝나고 친구들이랑 디저트 파티하러 간 곳이에요. 딸기크림라떼는 퓨레가 진하게 들어가서 디저트처럼 풍부한 맛이여서 혼자 찐 감동,,, 혼자 힐링하러 오기에도, 데이트로 오기에도 완벽한 곳이에요.', 4, 5, 'GOOD', SYSTIMESTAMP);
