INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '데이트 장소로 베리블리스만큼 좋은 곳이 또 있을까요? 예쁜 인테리어 덕분에 분위기 최고였어요! 수플레를 먹으면서 둘이 오붓하게 얘기 나누기에도 딱입니다ㅎㅎ 다음 기념일에 또 와야겠어요~', 8, 5, 'GOOD', SYSTIMESTAMP);
