INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '장소 저장해두었다가 드디어 방문했어요! 수플레 팬케익 진심 너무 사랑해서 집에서도 만들어보고, 맛있는 맛집들 찾아 다니는데 여기 ㄹㅇ 사장님이 수플레 장인이에요 식감이 구름 씹는 듯한 기분 입에서 그냥 사라져버려요 맛은 있어도 수플레에 진심인 가게 찾기도 힘든데 여긴 레알 찐입니다,,, 조만간 또 갈거에요 ~! 오래오래 잘 되셨음 좋겠습니다', 46, 9, 'GOOD', SYSTIMESTAMP);
