INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '비주얼이 너무 예뻐서 기대하고 왔는데 기대했던 이미지랑 똑같았어요! 맛도 좋았고 카페 분위기도 좋아서 다음에 다시 올 것 같습니다. 공간이 넓어서 자리도 많이 있어 대기없이 편하게 들어왔습니다!', 81, 16, 'GOOD', SYSTIMESTAMP);
