INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '오랜만에 수플레가 먹고싶어서 왔어요!! 딸기 양도 많고 수플레도 맛있게 잘 먹었습니다 :) 제 여자친구도 매우 좋아했습니다 ~ 다음에 홍대오면 다시 방문하겠습니다 ! 😀😀😀😀', 88, 14, 'GOOD', SYSTIMESTAMP);
