INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '친구랑 온지 15분 만에 한판 뚝딱. 어무 맛있어서 먹고 나서 접시 맛집이라는 것을 알았습니다. 완전 딸기딸기 한게 일본에서도 비슷한 걸 먹었지만 여기도 완전 맛집❤️담에 또 와서 다른 메뉴도 먹어보려구용🍓🍓🍓🫶🏻🫶🏻', 32, 6, NULL, SYSTIMESTAMP);
