INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '퐁신퐁신 ~ 수플레 재대로 만드는 수플레 맛집이에요 !! , 이쁘기도 진짜 이쁜데 맛이 대박입니다 ! 입에서 녹아내리는데 또 생각나는 너무나 이쁘고 맛있는 수플레 완전 추천이에요 :) 아메리카노도 원두가 느껴지는 향과 풍미가 대박인 커피, 디저트 맛집이네요 !! 또또 방문할 완전 추천할 수플레, 커피 맛집 ! 홍대 베리블리스 입니다', 65, 16, 'GOOD', SYSTIMESTAMP);
