INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '말차러버인데 말차 파르페를 판다고 네이버에서 보고 후다닥 가봤는데 너무 맛있어용 혼자 가도 자리가 다양하게 있어서 눈치 안보고 혼카페 즐기기에도 너무 좋더라구요 종종 파르페 먹으러 올듯🍀', 66, 13, 'GOOD', SYSTIMESTAMP);
