INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '분위기가 진짜 좋음! 여친이랑 데이트하러 갔는데, 화이트톤의 고급스러운 인테리어 덕분에 로맨틱한 분위기가 물씬~ 수플레 먹으면서 둘이 조용히 얘기 나누기 딱 좋았네요ㅎ 과일이 올려진 파르페도 예쁘고 맛있었어요 ~ :)', 22, 9, 'GOOD', SYSTIMESTAMP);
