INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '디저트 진짜 JMT... 친구들이랑 SNS에서 많이 본 카페라 가봤는데, 기대 이상이었어요! 팬케이크 위에 올려진 과일들이 너무 신선하고 달콤한 거 있죠? 게다가 인스타 감성 뿜뿜이라 사진 찍어 올리기에도 최고였어요 ㅎㅎ 가성비 좋은 편이라 부담도 덜하고 넘 좋아요~', 100, 25, 'GOOD', SYSTIMESTAMP);
