INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '매장이 넓어서 자리를 선택하기 좋아요! 중간중간 있는 소품들이 귀여워서 기분도 몽글몽글해집니다!!(´▽｀ ʃƪ)♡ 꿀밤라떼도 따뜻하고 맛있고 딸기요거트 스무디도 상큼달달하니 맛있었습니다 모찌 수플레도 쫀득하고 퐁신하니 식감이 너무 재밌고 맛있습니당💕', 4, 6, 'GOOD', SYSTIMESTAMP);
