INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '초코도 너무너무 맛도리구요.. 딸기 기대하고 갔는데 기대에 맞게 파르페 넘넘 맛있었습니다 달달하고 넘 좋아요 당떨어질때   최고🫶🏻🫶🏻', 39, 0, 'GOOD', SYSTIMESTAMP);
