INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '베리블리스에서 잇자! 친구랑 에이드랑 팬케이크 시켰는데 와 진짜 레전드~ 과일도 엄청 신선하고 달달하니 JMT였어요~ 여기 소문대로 분위기도 너무 좋고, 인테리어가 사진 찍기 딱 좋더라구요! 홍대 올 때 또 방문예정ㅎㅎ', 30, 1, 'GOOD', SYSTIMESTAMP);
