INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '친구들과 함께 디저트 카페에 왔어요!! 여기 디저트가 정말 부드럽고 맛있어서 감탄이 절로 나와요! 달콤한 맛과 감성이 가득한 분위기까지 완벽한 조합!! 이곳을 모르면 후회할지도 몰라요, 꼭 한번 와보세요!! 최고로 추천하는 디저트 맛집입니다!!', 32, 4, 'GOOD', SYSTIMESTAMP);
