INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '데이트하기 딱 좋은 베리블리스! 인테리어가 고급스러워서 마치 특별한 날을 기념하는 기분이었어요! 분위기 정말 좋음~ 파르페도 완전 만족! 커피도 맛있어서 둘이서 좋은 시간 보냈어요 :)', 41, 6, 'GOOD', SYSTIMESTAMP);
