INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '홍대에 있는 베리블리스 다녀왔어요! 인스타에서 봤던 그 팬케이크 드디어 먹어봄 ㅠㅠ! 과일이 올려져서 비주얼 끝장나고, 쫀득한 케이크가 입에서 살살 녹아요! 친구들끼리 수다 떨며 사진 찍기 최고였음 ㅎㅎ', 12, 4, 'GOOD', SYSTIMESTAMP);
