INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '1층과 2층으로 나눠져있어서 좌석도 많고 직원분께서 친절하게 안내해주셔서 좋았어요 !! 그리고 딸기가 신선하고 맛있어요 !! 딸기 좋아하시는 분들이라면 좋아할 것 같은 카페에용 다음에 또 재방문 할게요 ◡̎', 26, 7, 'GOOD', SYSTIMESTAMP);
