INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '베리블리스 디저트 맛집 인정! 친구들이랑 수플레랑 팬케이크 나눠 먹었는데 비주얼도 미쳤고 맛도 굿굿~ 과일이랑 같이 먹어서 그런지 상큼하고 너무 맛있어요ㅎㅎ 홍대 핫플답게 사진 찍기도 좋더라구요 :) 다음번에는 다른 친구들도 데리고 와야겠어요!', 15, 10, 'GOOD', SYSTIMESTAMP);
