INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '일 마치고 단 거 땡겨서 들어간 베리블리스, 수플레 비주얼에 한 번, 맛에 두 번 놀랐어요. 수플레 위에 딸기가 아낌없이 올라가 있어서 보기만 해도 힐링됐어요. 계절 바뀔 때마다 메뉴 바뀐다고 해서 또 가보려구요!', 24, 2, 'GOOD', SYSTIMESTAMP);
