INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '홍대에 있는 수많은 수플레 케잌, 디저트 맛집 다 먹어 봤지만, 여기가 제일 맛있는것 같아요 !! 너무 달지도 않고 무엇보다 너무 갓성비 그자체에요 제 단골집이 될 것 같습니다. 너무 맛있어요 감사합니다 😊😊', 23, 3, 'GOOD', SYSTIMESTAMP);
