INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '딸기 처돌이인데.. 진짜 딸기 너무 많이 주셔서 좋았어요!!! 수플레도 퐁실퐁실하니 좋았습니당☺️ 요즘딸기 작은 거 많은데 그렇게 작지도 않았어요!! 낮에 오니 한적해서 좋더라구요ㅎㅎ 딸기 좋아하시면 꼭 한 번씩 들러보세요!!', 41, 2, 'GOOD', SYSTIMESTAMP);
