INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '딸기 모찌 팬케이크랑 아이스 아메리카노 시켰는데 신경도 많이 써주시고 플레이팅이나 맛도 생각보다 더 맛있었어요>< 다음엔 언니랑 오고싶어요. 특히 사장님이 친절하시고 2층까지 직접 서빙해주셔서 편하게 먹을 수 있었어요.', 85, 11, 'GOOD', SYSTIMESTAMP);
