INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '여기 정말 둘이 오붓하게 디저트 먹기 좋은 곳이에요~ 데이트하러 갔는데 인테리어가 너무 예뻐서 감동했어요!ㅎㅎ 파르페랑 커피를 시켰는데, 디저트 퀄이 넘 좋았습니당!', 89, 13, 'GOOD', SYSTIMESTAMP);
