INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '베리블리스 다녀왔어요! 팬케이크 덕후인 친구들이랑 갔는데 JMT 인정이에요 ㅋㅋ! 세련된 인테리어라 사진 찍기에도 딱 좋았고, 과일이 아낌없이 올라간 디저트 덕분에 기분까지 좋아지는 것 같아요ㅎㅎ', 1, 2, 'GOOD', SYSTIMESTAMP);
