INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '데이트 맛집이라는 말이 딱 맞는 곳이에요! 여친이랑 데이트하러 갔는데, 조용하고 아늑한 곳에서 즐거운 시간을 보냈어요 ㅎㅎ수플레와 에이드를 주문했는데, 둘 다 비주얼도 예쁘고 맛도 굿~', 84, 14, 'GOOD', SYSTIMESTAMP);
