INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '네이버에서 엄청 유명하다길래 방문햇는데 인테리어도 넘 이쁘고 맛도 넘 젛아요!특히 요거트 딸기가 진짜 레전드입니다 ㅜㅜ 식성 좋으신 분들은 수플래 두개 추천 드려요  저희는 넘 순삭이여섴ㅋㅋㅋㅋ  다음에도 홍대오면  재방문 예정입니댜🥹🥹', 104, 23, 'GOOD', SYSTIMESTAMP);
