INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '오랜만에 수플레 땡겨서 왔어요!! 오랜만에 와도 변함없이 맛있는 딸기 모찌 수플레 .. ❤️ 친구가 수플레 좋아하는데 여기 진짜 맛있다고 좋아해서 괜히 뿌듯하네요 💕 홍대 오시면 수플레 맛집은 꼭 베리블리스!! 한 번 들려보세요 직원분들도 엄청 친절하구 조아요✨🩵', 36, 9, 'GOOD', SYSTIMESTAMP);
