INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '여자친구가 딸기를 좋아해서 방문하게 되었어요!! 수플레 팬케이크 먹었는데 진짜 부드럽고 맛있네요 ㅎㅎ 딸기 좋아하시는 분 있으면 꼭 방문해보세요! 저도 다시 올 예정 ㅎㅎ', 32, 1, 'GOOD', SYSTIMESTAMP);
