INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '2번째 방문입니다 -ෆ 너무 마음에 들었어서 지인 데리고 왔는데, 다들 좋아해줘요! 비주얼부터 분위기, 맛까지 마음에 들어하시는 제 지인들 ㅎㅎ 자리도 많아요 지인 초대하고 싶고, 초대하여 하여금 기분좋게 만들어주는 카페예요 💟 오래 존재하길', 22, 3, 'GOOD', SYSTIMESTAMP);
