INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '친구랑 맛있는 디저트 먹을 곳 찾다가 발견했어요!! 겨울이라 딸기 디저트 먹고 싶어서 시킨 수플레.. 처음 먹어보는데도 달다구리해서 넘 맛있었다요..❤️ 매장도 예쁘고, 직원분들도 친절하시고 얘기하기 좋았어요!!!', 83, 12, 'GOOD', SYSTIMESTAMP);
