INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '친구가 가자고 해서 왔는데 매장도 넓고 디저트도 맛있어요~ 보통 케이크 파는 카페는 음료 종류가 별로 없어서 아쉬운데 여기는 메뉴가 다양하고 신기한 메뉴도 많아서 좋았어요', 25, 5, 'GOOD', SYSTIMESTAMP);
