INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '아이들이 좋아해요~ 가족 모임으로 갔는데, 공간이 넓어서 편하게 즐길 수 있었어요 음료도 신선한 계절과일로 만들어서 아이들한테도 안심하고 줬습니다^^ 또 가고 싶어요', 2, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '대학 동기가 맛있는 홍대에 맛있는 디저트, 느좋 카페 있다고 해서 방문했어요 ! 소문대로 엄청 디저트, 커피에 진심이고 매장도 넓직해서 좋더라구요 ~~ 인기 있는 집이라서 그런지 좌석도 금방금방 가득찼고 브런치할 겸 11~12 시쯤 방문했는데 생각보다 사람 많아서 놀랐어요 !! 다음에도 또갈게요 :)', 17, 1, 'GOOD', SYSTIMESTAMP);
