INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '디저트 맛집 찾아다니는 1인 입니다. 인스타그램에 홍대 핫플로 떴길래 시간 내서 찾아갔어요. 우선 통창뷰라 너무 좋았어요 양도 진짜 많구요 제가 먹어본 수플레 중에서는 나름 TOP 5 안에 들어가는 최고의 맛이었어요 부드럽고 느끼하지도 않고, 말차랑도 엄청 잘 어울려서 감동 받았습니다.. ! 동네먼 가까우면 매일 가고 싶어요 허허 .. 계속 생각나는 맛.. 주말에 여기서 또 데이트 해야지 !!', 78, 12, 'GOOD', SYSTIMESTAMP);
