INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '어느 방면에서 찍어도 인스타감이에요!!! 딸기 제철 과일인지 너무 맛있고 수플레는 퐁싱퐁실해서 너무 맛있었어요!! 디저트뿐만 아니라 커피도 너무 맛있고 공간도 넓고 자리도 많아서 모임하기 좋을 것 같아요!!', 75, 18, 'GOOD', SYSTIMESTAMP);
