INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '홍대 카페투어 하다가 마지막 스팟으로 간 곳인데, 진짜 찐한 여운 남는 집이었어요. 수플레 팬케이크는 따뜻하고 말차 파르페는 시원하고, 완벽한 마무리...ㅠㅠ 나만의 디저트 엔딩요정...🍰', 125, 23, 'GOOD', SYSTIMESTAMP);
