INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '카페 뷰도 좋고 딸기는 달고 생크림은 적당히 달아서 조화가 좋았어요! 아아랑 마시니깐 최고네요 디저트들 비주얼이 다 좋아서 담엔 수플레나 파르페 먹어보고싶어용 왔다갔다 하는 시스템이 처음이라 당황했지만 친절하셔서 감사했어요 : )', 111, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '딸기디저트 좋아하는 언니랑 브런치 겸 다녀왔어요. 계절한정 메뉴라고 해서 시켰는데 맛도 비주얼도 만족도 최고였어요. 내부가 넓어서 북적이지 않고 조용히 대화하기 좋아요. 딸기덕후라면 무조건 좋아할 맛이에요.', 0, 1, 'GOOD', SYSTIMESTAMP);
