INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '친구랑 오랜만에 만나서 특별한 곳을 찾다가 여기로 와봤어요. 음료는 하겐다즈 베이스로 우리가 아는 그 맛있는 맛이었고 여기 수플레가 진짜입니다 생크림이 살살녹으면서 딸기랑 달콤하게 어우러집니다 강추~~', 29, 10, 'GOOD', SYSTIMESTAMP);
