INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '예약없이 갔는데 바로 들어갈 수 있어서 예약을 따로 안하고 가셔도 괜찮아요. 좌석안내도 친절하게 도와주시고 주문하고 수플레 나오는 시간도 알려주셔서 좋았어요. 딸기가 달달하고 특히 생크림이 맛있었어요 수플래랑 딸기랑 같이먹으면 완전맛있어요!!', 23, 8, 'GOOD', SYSTIMESTAMP);
