INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '겨울에 딸기 생각나면 무조건 여길 가야겠어요!! 수플레가 진짜 미친듯이 부드러운데 여기에 딸기도 제철 겨울 금딸기를 쓰셨는지 너무 맛있는데 음료도 인공맛이아니라 직접 바로바로 갈아주시더라구요 매장도 엄청 넓고 창도 통창이라서 들어오는 햇빛에 딱 브런치 먹기 너무 좋은곳이라니까요', 21, 1, 'GOOD', SYSTIMESTAMP);
