INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '수플레 JMT! 친구들이랑 홍대 돌아다니다가 베리블리스에 가봤는데 완전 핫플이었어요~ 수플레에 과일까지 잔뜩 올려져 있어서 비주얼도 넘예쁨! 음료도 시원하고 너무 맛있어서 또 가고 싶어요 ㅎㅎ', 87, 12, 'GOOD', SYSTIMESTAMP);
