INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '수플레 퐁실퐁실 너무 맛있어요 아이스크림도 다 하겐다즈 써서 맛남 아이스초코 굳 매장도 2층까지 잇어서 넓고 분위기 좋아욤!!', 79, 12, 'GOOD', SYSTIMESTAMP);
