INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '딸기 간판 보고 들어왔는데 딸기 진짜 많이주네요!!딸기로 만들수 있는 디저트가 여기 다있는 것 같아요! 분위기도 너무 좋아요! 다음에 또 방문할 예정이에요', 11, 5, 'GOOD', SYSTIMESTAMP);
