INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '세상에... 여기가 딸기 천국이네요 🍓🍓 친구와 딸기를 목적으로 만났는데 완전 성공이에요! 딸기밭수플레는 이름처럼 딸기가 가득 올려져 있고, 음료도 다양해요 .ᐟ.ᐟ 좋은 시간 보내고 갑니다 :) 다음에 또 방문할 의사 완전 있습니다😊', 36, 2, 'GOOD', SYSTIMESTAMP);
