INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '복숭아밭 수플레는 40분 기다려서 먹었어요 그만큼 정말 맛있었는데요 복숭아와 아주 궁합이 좋았어요 파르페도 정말 너무 맛있어요 복숭아와 자두 콜라보인 복자 스무디도 맛있었고 요거트스무디도 참 맛있었어요 어떤거 하나도 버릴게 없었어요 가게는 2층까지있고 주문과 계산은 1층에서 하고 음식 픽업과 반납은 2층에서 해요 너무 맛있어서 싹싹 긁어먹고 왔어요 자리는 1층은 거의 2인석이구요 3명이상이면 의자를 더 갖다주세요 가격이 조금 사악하긴해도 그만큼 가치가 있더라구요 계절에따라 과일이 바뀌는거같아요 딸기가 메인일때 또가고싶어요~', 23, 6, 'GOOD', SYSTIMESTAMP);
