INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '딸기를 너무 좋아해서 홀린듯이 들어왔어요🍓 위에 올려져있는 아이스크림도 맛있고, 그냥 수플레랑 음료도 너무 맛있어요 디저트가 너무 예쁘게 나와서 사진찍기도 좋았네욧 잘 먹고 즐기다 갑니당', 50, 3, 'GOOD', SYSTIMESTAMP);
