INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '카페 분위기가 너무 예뻐요 🍀 친구들이랑 얘기 나누려고 방문했는데 힐링하다 갔어요 카페도 깔끔하고 바깥 풍경도 예뻐서 더 좋았답니다 디저트, 음료도 다양하게 판매하고 있어 음료 고르기 어려울 정도!! 특히, 딸기 들어간 디저트 추천합니다 딸기 모찌 수플레 맛있었어요 ㅎㅎ', 90, 11, 'GOOD', SYSTIMESTAMP);
