INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '진짜! 너무 맛있어요! 스프카레를 먹고나서 분명 여자친구가 배부르다고 안먹겠다 했는데, 제가 딸기 꼭지를 따고 있는 사이.... 딸기가 하나 둘 사라지고, 아이스크림은 녹았다고 거짓말을 칠정도로 맛있습니다! 메이플 시럽은 더 달라고 말씀드리니 친절하게 그득그득 채워주셨고, 사장님 친절하시고, 수플레도 너무너무 부드러웠습니다ㅎㅎ 잘 먹었습니다!! 진찌 맛있어요!!', 482, 83, 'GOOD', SYSTIMESTAMP);
