INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '분위기도 좋고 딸기수플레가 정말 맛있어요 매장도 넓고 직원들도 친절하고 좋은 시간 보냈어요 커피랑 같이 먹기 좋았습니다 다른 메뉴도 먹어보고 싶네요 사람이 많은 이유를 알 것 같아요 잘 먹었습니다^^!', 53, 15, 'GOOD', SYSTIMESTAMP);
