INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '진짜 인생최대의 수플레에오!! 폭신폭신하고 딸기두 맛있구 조각내서 생크림, 아이스크림, 딸기랑 한번에 같이 먹으면 진짜진짜 맛있어요!! 같이 먹을수있는 커피도 정말 맛있고요 다시 꼭 재방문하고싶은 최고의 카페입니다!! 최고에옹!!!', 45, 8, 'GOOD', SYSTIMESTAMP);
