INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '딸기케이크와 고구마 라떼,아메리카노 시켰는데 다 너무 맛있는데 특히 딸기케이크가 가장 맛있었어요 🍰 분위기도 좋고 매장도 넓고 사진도 잘 나와요!!👍👍딸기 파르페랑 딸기 팬케이크도 먹어보고싶어서 다음에도 또 방문할거같아요!! 🤗🤗', 0, 6, 'GOOD', SYSTIMESTAMP);
