INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '지나가다가 왔는데 케이크가 정말 맛있어요!!! 그랜마 초코라떼 위에 마쉬멜로도 넘 귀엽고 맛있어요ㅎㅎ 그리고 너무 달지 않아서 딱 좋습니다!! 딸기를 아끼지 않고 넣어주시는 것 같아요!! 안에 크림도 정말 맛있네요ㅎㅎ 매장도 2층까지 좌석 널널하게 있어서 좋아요~~', 40, 4, 'GOOD', SYSTIMESTAMP);
