INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '말차 좋아해서 파르페 시켰는데, 말차향 진하고 크림 부드러워서 입안 가득 고급진 느낌이에요. 쌉쌀+상큼=완벽한 밸런스였어요. 재방문각!', 24, 6, 'GOOD', SYSTIMESTAMP);
