INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '데이트하고 마지막 코스로 디저트 먹으러 갔어요. 따뜻한 조명에 창밖 햇살까지 더해지니 앉아있는 것만으로도 힐링이더라구요. 재방문의사 200%, 봄 감성 충전 완료!', 20, 3, 'GOOD', SYSTIMESTAMP);
