INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '저번에 먹은 수플레가 생각나서 또 왔어요!! 이번엔 밀크티랑 같이 시켰는데 너무 맛있어서 눈물 흘리면서 먹었어요 🥹🥹🥹 수플레도 여전히 너무 맛있어요!! 여름 복숭아 시즌 때 다시 들릴게요!!', 54, 16, 'GOOD', SYSTIMESTAMP);
