INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '말차 디저트 찾다가 평이 좋길래 방문했는데 기대 이상으로 향과 밸런스가 좋았어요. 말차디저트는 텁텁하지 않고 향긋하게 퍼지는 맛이라 만족도 높았어요. 사진 맛집이면서도 맛까지 제대로라서 다음엔 친구랑 또 올만한 홍대 찐 디저트 맛집,,!', 63, 13, 'GOOD', SYSTIMESTAMP);
