INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '음료 커피 스무디 다 전부 맛있고 특히 치즈케이크가 진짜 말이 안됩니다.. 팬케이크도 아이스크림이랑 같이 주시는데 비싸긴 하지만 돈 값하는거 같아요. 인테리어도 너무 예쁘고 사장님도 친절하세요 강추!!!', 40, 1, 'GOOD', SYSTIMESTAMP);
