INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '딸기모찌수플레는 처음인데, 엄청 퐁신퐁신하고 맛있었어요! 쇼케이스에 생딸기 박스가 쌓여있는거 보고 이미 맛있음을 직감했어요..!💗 사장님도 엄청 친절하게 설명 잘해주시고, 커피도 맛있어요!ㅎㅎ그리고 배경이 하얘서 사진도 예쁘게 잘 나와요! 다음엔 남자친구랑 또 올게요!', 85, 11, 'GOOD', SYSTIMESTAMP);
