INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '홍대에서 밥먹고 디저트 카페를 찾던 도중 수플레 비쥬얼 보고 홀린듯 방문했습니다 ! 저는 초코베리 수플레 팬케이크를 주문했는데 퐁실퐁실 너무 맛있었습니다!! 음료도 괜찮고 달달함 채우기, 간단한 이야기 하러 방문하면 좋을것 같아요 👏', 21, 6, 'GOOD', SYSTIMESTAMP);
