INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '강원도에 사는 한 커플입니다 방학시즌이라 좀 뜻 깊은 추억을 가지자 해서 계획을 짜는 도중에 ‘베리블리스’라는 곳을 알게 되었고 저희 둘 다 특히 여자친구가 딸기를 굉장히 좋아해서 여기에 꼭 오기로 하고 처음으로 홍대에 와서 간 카페입니다 분위기 시설 디저트 모두 다 좋아서 여자친구한테 엄청칭찬 받았습니다 딸기 좋아 하시는 분들이면 무조건 오시길 추천 합니다!', 21, 6, 'GOOD', SYSTIMESTAMP);
