INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '벚꽃 시즌이라 홍대 돌아다니다가 예쁜 카페 찾아 들어갔어요. 디저트에 올라간 생딸기 색감이 너무 예뻐서 보는 것만으로도 기분 좋아졌어요. 감성 사진 찍기 딱 좋은 홍대 디저트 맛집입니당 ~~', 123, 21, 'GOOD', SYSTIMESTAMP);
