INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '친구랑 우연히 들렸는데 매장이 넓어 매우 쾌적하고 또 직원분들이 매우 친절하셔서 기분이 좋았습니다!! 또 시그니처 메뉴인 것 같은 모찌 수플레도 굉장히 맛있었고 다음에 또 방문하고 싶습니다!!☺️☺️', 38, 0, 'GOOD', SYSTIMESTAMP);
