INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '딸기 모찌 수플레 유명해서 방문 하고 싶었던 곳이었는데 역시 유명한건 다 이유가 있는거 같아요!! 분위기도 좋고 공간이 넓어서 좋았어요', 122, 22, 'GOOD', SYSTIMESTAMP);
