INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '커피도 맛있고 팬케이크도 너무 부드럽고 맛있어요 ^^ , 지나가는 단골입니다 ! 이미 SNS, 입소문 탄 맛집이라 주말에는 가끔 웨이팅 생길수도 있어요 ! 사장님도 엄청 친절하시고 앞으로 더 잘나가야할 홍대 디저트 카페 맛집입니다', 354, 77, 'GOOD', SYSTIMESTAMP);
