INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '오랜만에 친구 셋이서 홍대에서 수다 떨러 갔어요. 딸기랑 말차 조합이 낯설었는데 의외로 중독성 있었어요. 소음 적고 음악도 잔잔해서 혼자 가기도 좋을 듯해요. 다음에 또 다른 메뉴 도전하러 갈게요 :)', 42, 8, 'GOOD', SYSTIMESTAMP);
