INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '내부가 크고 인테리어도 너무 예뻐서 좋아요 ㅎㅎ 커피도 너무 맛있고 수플레 진짜 제일 맛있어요 ㅎㅎ 직원분들도 너무 친절하시고 분위기도 좋아요!', 20, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '친구 추천으로 처음 가봤는데 수플레가 진짜 폭신하고 안에 모찌가 쫀득쫀득! 디저트계의 마법이었어요. 이건 그냥 말이 필요없습니다.... 말로 다 못담아요 꼭 드셔보세요.', 35, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '봄이라 딸기가 먹고싶어서 검색해보고 왔는데 비주얼이 정말 정말 귀엽고 음료도 다 맛있었어요 딸기 디저트 먹고싶을 때마다 생각날것같아요🍓👍', 37, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '전부터 눈여겨보던 카페였는데 드디어 다녀왔어요. 외관부터 감성 가득이고, 수플레 팬케이크는 숟가락으로도 잘릴 만큼 부드럽더라구요. 한번 가보면 단골 확정;;;', 32, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '오늘 친구 추천으로 같이 와봤는데 매장도 넓고 화장실도 꺀긋하고 사장님도 친절하고 수플레팬케익이 완전 퐁실퐁실~ 의자도 너무 편해서 집에 훔쳐가고 싶네여 ^_^', 63, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '가게 분위기도 너무 좋고 음식이 정말 맛있어요!!! 제가 먹어본 제가 먹어본 팬케이크 중에 가장 맛있었던거 같아요😍😍 다음에도 꼭 다시 오겠습니다.❤️❤️❤️', 18, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '음료가 넘 맛있고 직원분들이 친절하셔거 다음에 또 방문하고 싶습니다! 케잌에 딸기가 엄청 큼직큼직해서 너무 맛있어요!!! 다들 오시면 딸기 디저으 드셔보세용', 23, 10, 'GOOD', SYSTIMESTAMP);
