INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '수플레 케이크 넘넘 맛있었어요! 달기도 단데 적당히 달고 시럽도 따로 줘서 더 달게 먹을수도 있고 매장도 크고 쾌적하고 예뻤어요! 나중에 또 오려구요 넘넘 만족 💓', 95, 22, 'GOOD', SYSTIMESTAMP);
