INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '일단 들어오면 수플레 냄새가 미쳤어요!!! 먹을 생각 없다가도 먹고 싶어서 결국 시켰는데 역시나 부드럽고 너무 맛있었어요🩷! 내부 엄청 넓고 따뜻한 분위기라 친구랑 와도 좋고 데이트로도 좋을거 같아용🤗🤗', 251, 57, 'GOOD', SYSTIMESTAMP);
