INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '친구들이랑 홍대에서 놀다 들른 베리블리스 ㅎㅎ 분위기 산뜻하고 좋았어요~ 화이트톤 인테리어 덕분에 사진 찍기 너무 좋고, 디저트도 비주얼 끝판왕! 에이드 시켜 먹었는데 상큼하니 딱 좋더라구요ㅎㅎ 디저트 카페로 강추', 6, 1, 'GOOD', SYSTIMESTAMP);
