INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '사장님이 엄청 친절하시고 차와 커피 모두 맛있어요! 주문하면 메뉴도 빨리 나왔어요 인테리어가 포근하고 따뜻한 분위기에 화이트로 깔끔한 느낌을 줘서 좋았어요! 사진도 잘나오고 다 좋아요 제발 오세요', 0, 6, 'GOOD', SYSTIMESTAMP);
