INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '수플레케이크 진심 퐁신퐁신 넘 맛있어요!! 🥰 직원분들도 다들 친절하시고 너무 기분 좋은 공간입니다 !! 다음에 수플레 좋아하는 친구 데리고 또 방문하겠습니다 ㅎㅎㅎ', 44, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '수플레 팬케이크 먹고싶어서 방문했는데 폭신폭신 달달해서 맛있게 먹었어요! 특히 생크림이 맛있어서 다음엔 케이크도 먹어보고싶네요 캐롤이랑 트리덕에 크리스마스 분위기두 느낄수 있어서 좋았어요', 33, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '카페가 너무 귀여워요~ 수플레 케이크도 너무넘 맛있고 아이스크림도 있어여!!! 딸기도 신선하고 정말 달아서 좋은 것 같아요🍓🩷🩷', 4, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '전에 먹었던 수플레 팬케이크는 계란 비린맛도 나고 별로여서 수플레는 좀 꺼려했는데 여긴 진심 1도 안비리고 폭신폭신 넘 맛있어요 !! 지나 다니면서 종종 봤는데 왜 이제 왔는지 후회중...! 사장님도 친절하시고 종종 올거같아요 👍', 126, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '단체석이 있어 여러명이 오기 좋은것 같아요! 수플레팬케익도 맛있었고 딸기도 많아요🍓 하겐다즈 아이스크림 사용해서 더 고급진거같아요!', 59, 15, 'GOOD', SYSTIMESTAMP);
