INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '주말에 혼자 홍대 나들이하다가 들렀어요. 디저트 플레이팅이 너무 예뻐서 먹기 아까울 정도였어요. 내부가 넓어서 북적이지 않고 조용히 대화하기 좋아요. 카페투어 하시는 분들 꼭 한 번 가보세요!', 30, 10, 'GOOD', SYSTIMESTAMP);
