INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '우연히 들렸는데 카페가 너무너무 이쁘고 메뉴도 엄청 다양해서 넘 좋아요 !!! , 분위기 좋고 편해서 카공하기도 좋았고 작업하기도 편한 홍대 디저트 맛집이에요 ~', 32, 6, 'GOOD', SYSTIMESTAMP);
