INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '날씨가 따뜻해서 봄 기분 내려고 친구랑 산책하다 들렀어요. 딸기 모찌 수플레 팬케이크가 봄 느낌 제대로 살려줘서 사진도 엄청 찍었어요. 여름 오기 전에 한 번 더 가고 싶어요!', 23, 6, 'GOOD', SYSTIMESTAMP);
