INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '수플레 퐁신퐁신하고 딸기도 양도많도 달달해서 너무 맛있어요🫶커피랑 찰떡궁합❤️홍대 수플레집중에 제일 맛있는거 같아요 담에또와야징👍🌟🌟🌟', 42, 5, 'GOOD', SYSTIMESTAMP);
