INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '딸기가 미쳤어요.... 퐁신한 수플레 케이크와 조화가 완벽해요... 밀크티에 올라간 아이스크림 스푼으로 먹다가 섞어서 먹으면 짱맛!! 12월이라 크리스마스 감성 낭낭하고 잔잔한 캐롤도 틀어주셔서 분위기도 최곱니다🤍🤍', 39, 9, 'GOOD', SYSTIMESTAMP);
