INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '딸기 시즌이라 딸기 디저트가 너무 먹고 싶어서 찾은 곳이에요 가격은 좀 있지만 자리도 넓고 쾌적하고 분위기가 좋아서 디저트랑 음료 시켜놓고 담소 나누기 좋은 것 같아용 재방문 의사 있습니다!', 94, 23, 'GOOD', SYSTIMESTAMP);
