INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '홍대 대형 카페 ♥️ sns에서 핫해서 궁금했는데, 실물이 더 예뻐요! ✔️ 수플레 팬케이크 (딸기 밭) ✔️ 하겐다즈 딸기 라떼 딸기를 와르르 쏟은 거처럼 듬뿍 올려주셨어요. 폭신폭신 수플레 팬케이크 3조각에 부드럽고 달큼한 생크림+시럽+딸기 아이스크림이 곁들여집니다. 속이 살짝 반숙이라 더 촉촉하고 부드러워요. 엔젤 시폰느낌인데, 갓 구워서 따끈해요! 반죽에서 약간의 바닐라 향이 나서 향긋합니다. 딸기 라떼는 새콤달콤하고 역시 하겐다즈 아이스크림이 올라가요. 아이스크림과 먹으니 녹으면서 시원하고, 딸기 맛이 더 진해지는 느낌이에요 ✨ 돌아가는 대형 트리도 있으니 크리스마스 분위기 만끽해보세요 🙂 (+달고 신선한 딸기와 함께)', 37, 2, 'GOOD', SYSTIMESTAMP);
