INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '팬케이크 먹으려고 먼 길을 달려왔는데 후회 없는 맛 🥹 진짜 부드럽고 달달하고!! 맛있어용 여태 먹은 팬케이크 중 원탑 👍🏻👍🏻 나오자마자 5분 만에 순삭 했어요🤗🤍', 69, 13, 'GOOD', SYSTIMESTAMP);
