INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '아기자기한 분위기의 카페에서 딸기 프라페와 딸기 라떼를 맛봤어요. 딸기 프라페는 얼음이 곱게 갈려 있어 시원하고 달콤했으며, 신선한 딸기 과육이 씹혀서 더욱 만족스러웠어요. 딸기 라떼는 부드러운 우유와 달콤한 딸기가 조화를 이루며, 진한 딸기 맛이 느껴져 따뜻하게 즐기기 좋았어요. 두 메뉴 모두 상큼한 딸기 맛을 제대로 살려서 딸기 덕후라면 꼭 한번 맛보길 추천합니다!', 73, 15, 'GOOD', SYSTIMESTAMP);
