INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '딸기 케이크 맛집이라해서 찾아갔는데 음료도 다양하고 딸기 디저트도 많아서 좋았어요!🍓 공간도 쾌적하고 딸기 수플레 케이크가 진짜 너무 맛있어서 친구랑 순삭 했습니다...🤤🤤 딸기도 엄청 달아요 다음에도 또 올 거예요🫰🏻', 40, 4, 'GOOD', SYSTIMESTAMP);
