INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '망고밭 수플레팬케이크랑 오롯이멜론, 오롯이딸기를 마셨습니다! 팬케이크가 너무 부드럽고 크림이 달콤해서 완전 사르륵 녹았어요ㅠㅠ 망고도 듬뿍 들어있고 생딸기와 생메론이 갈려 과육도 가득 찬 음료들도 너무 맛있었습니다! 잘 먹고 감댱', 90, 18, 'GOOD', SYSTIMESTAMP);
