INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '수플레 파는 곳을 찾다가 우연히 들어왔는데 분위기가 좋고 매장도 넓어서 엄청 쾌적하게 대화하기 좋았던 것 같아요! 그리고 무엇보다 이곳 수플레가 유명한 곳과 비교되지 않을 만큼 맛있어서 다음에 또 방문하고 싶은 카페에요!', 37, 7, 'GOOD', SYSTIMESTAMP);
