INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '창원엔 수플레 모찌가 없는데 서울에 친구 보러 온 김에 왔어요~! ''오롯이 딸기'' 음료는 생딸기 갈아서 찐~하게 너무 달고 맛있어요! 그리고 수플레가 퐁실퐁실 따뜻하고 빵이 맛있어요! 모찌랑도 잘 어울리고 같이 있는 딸기도 다네요! 매장도 넓어서 이야기 나누며 잘 먹었습니다 ㅎㅎ', 39, 8, 'GOOD', SYSTIMESTAMP);
