INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '홍대 수플레맛집 ‘베리블리스’ 카페 다녀왔어요!! 건물전체가 카페라서 넓고 쾌적하게 디저트 즐길 수 있어요~ 내부 인테리어도 감성적이어서 사진도 잘나와요👍🏻 외부테라스석도 마련되어 있어 날 좋은날 밖에서 먹어도 좋을거 같아요!! 쇼케이스에 케이크를 비롯해 디저트들고 다양하고 하나하나 너무 맛있어 보여요😊 주문한 포도밭수플레팬케이크 비주얼도 너무 예쁘고 음료도 맛있어요!!👍🏻 홍대 베리블리스 카페 추천이요👏🏻👏🏻', 129, 20, 'GOOD', SYSTIMESTAMP);
