INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '안내해주시는 직원분이 아주 친절하십니다☺️ 자리에 앉아서 기다리다보면 맛있는 파르페를 가져다 주세요.!! 맛있게 잘 먹고 갑니다~', 75, 16, 'GOOD', SYSTIMESTAMP);
