INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '친구따라서 처음으로 와봤는데 가게 직원분들도 너무 친절하시고 과일도 다 맛있어요 겨울 제철과일이 아닌 메론 쥬스도 시켜봤는데 달았어요! 딸기는 지금이 딱 철이라서 진짜 맛있었어요 다음에 또 올 것 같아요♡', 15, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '너무 마싯어요.. 망고 맛있어서 싹싹 긁어먹었어요 가격보고 뜨앗했는데 이정도 퀄이면 괜찮은 거 같아요 근처 살아서 다음에도 또 올 거 같아용 🤤🤤', 89, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '우연히 들어온 집인데 매장도 넓고 좌석 간격도 넓어서 대화하기 좋아요~ 딸기밭 수플레 팬케이크 시그니처라고 추천받았는데 비쥬얼부터 넘 예쁘고 넘 맛있네요~ 추천합니다^^', 70, 14, 'GOOD', SYSTIMESTAMP);
