INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '딸기 디저트 넘좋아해서 찾아보구 왔는데 넘 맛있고ㅠㅠ분위기도 너무 좋아요 좋은카페 알게된 거 같아서 너무 좋아서 앞으로 자주자주 오려구요ㅎㅎ', 44, 2, 'GOOD', SYSTIMESTAMP);
