INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '음료와 수플레 다 너무 맛있어요 !! 수플레 처음 먹어봤는데 딸기랑 조합이 말모..🍓🤍  내부 인테리어도 너무 예쁘고 분위기 있어서 데이트 장소로도 추천드려요 ! 다음에 또 방문해서 다른 메뉴 먹어보고 싶어요..🤤', 22, 5, 'GOOD', SYSTIMESTAMP);
