INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '요즘 크리스마스 분위기 나는 카페 찾고 있었는데 베리블리스 아기자기 하게 꾸며져서 좋았어요, 모찌 수플레는 쫀득하면서도 부드럽고, 신선한 과일이정말 듬뿍 들어가 있어요!! 사진도 잘 나오구 직원분들도 친절하셔요!', 87, 11, 'GOOD', SYSTIMESTAMP);
