INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '진짜 진짜 너무 너무 맛있어요 음료도 맛이 뭔가 달라요 적당히 달아서 좋아요 팬케잌도 빵이 너무 부드럽고 아이스크림 크림이랑 같이 먹으면 살살 녹아서 너무 좋아요 카페 분위기도 연말 분위기 나서 너무 좋구요 사람도 적당히 있어서 정말 추천합니다 다음에 또 오고 싶단 생각 들게 만드는 카페 입니다 ❤️', 119, 26, 'GOOD', SYSTIMESTAMP);
