INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '전부터 너무 오고싶었는데 마침 대기도 없어서 바로 입장했습니다!! 수플레 처음 먹어보는데 퐁신퐁신하고 넘 맛있어요ㅠㅠ 커피도 산미없고 좋습니다ㅎㅎ 담에 또 방문하겠습니다!', 18, 10, 'GOOD', SYSTIMESTAMP);
