INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '생각보다 매장도 엄청 넓고 직원분도 친절하세요 시킨 음식도 맛있고 다시 방문 할 거 같아요 그리고 딸기 디저트 종류가 많아서 딸기 좋아하시면 방문 하시면 좋을 거 같아요!', 9, 7, 'GOOD', SYSTIMESTAMP);
