INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '매장이 크고 넓어서 기다리지 않고 들어갈 수 있어 좋습니다.  직원분들도 친절하시고, 매장 내에서 잘 안내해주십니다. 커피도 맛있어요~~~', 26, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '퐁신퐁신한 수플레 팬케잌과 겨울시즌이라 나온 딸기가 매우 잘어울리는 생크림과 메이플 시럽까지,, 완벽 그자체의 디저트 네엽!! 음료도 .. 맛도리구 아이스크림 모두 하겐다즈 라 더욱더 마싯음 ㅜㅜ ♥️🎂🤪 잘먹엇숩니다 옴뇸뇸', 105, 20, 'GOOD', SYSTIMESTAMP);
