INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '오늘 우연히 가게 됐는데 너무 맛있어요 ~ 모찌 수플레는 여기서 처음 먹어봤는데요 우선 비쥬얼부터 찐 합격 너무 이쁘고 맛은 부들부들 달콤해요 ! 엄청 따뜻하게 먹을 수 있었고 미래의 남친이랑 같이 와서 꼭 먹으려구요 ,, 데이트 맛집입니다 !! 양도 많은데 생각보다 가격도 저렴해서 놀랐어요 ㅠㅠ 홍대 근처에 살았으면 매일마다 왔을것 같은데 집이랑 멀어서 너무너무 아쉬워요', 12, 6, 'GOOD', SYSTIMESTAMP);
