INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '빵이 부드럽고 맛있습니다. 홍대입구 역에서 가깝고 공간이 넓어 자리가 많다는 것이 장점입니다. 고구마라떼를 먹었는데 굉장히 나이스했습니다.', 42, 5, 'GOOD', SYSTIMESTAMP);
