INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '친구가 맛있다고 알려줘서 와봤는데 음료도 맛있고 케이크도 맛있어요!! 다음에 와서는 모찌 수플레도 먹어볼려구요! 카페 분위기도 좋아서 다들 친구,연인이랑 와서 즐겨도 좋을것 같아요', 61, 13, 'GOOD', SYSTIMESTAMP);
