INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '완전 데이트 맛집입니당! 깔끔한 인테리어 덕분에 프라이빗한 느낌도 있고, 홍대 분위기 좋은 카페로 추천!! :) 베리블리스에서 먹은 팬케이크도 최고였어요~', 23, 7, 'GOOD', SYSTIMESTAMP);
