INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '저도 그렇고 여자친구도 그렇고 둘 다 딸기를 엄청 좋아하고 디저트도 너무 좋아해서 찾아왔는데, 너무 맛있어서 배부른 것도 모르고 후다닥 먹었습니다. 너무 맛있었어요!', 9, 3, 'GOOD', SYSTIMESTAMP);
