INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베리블리스'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '무화과 수플레와 망고쥬스 아메리카노 조합으로 먹었는데 만족스러웠어요. 망고쥬스가 비싸다고 생각했는데 찐하고,생 망고까지 나와서 만족했어요. 수플레 계란 비린내도 안나고 부드러워서 굿. 무화과 당도가 좀 아쉬웠지만 듬뿍 나와서 좋았어요. 1층에서 주문, 안내해주시는 분도 친절하셔서 더 좋음. 😊 넓어서 자리 잡기도 좋고, 답답하지 않아서 좋았어요.', 73, 15, 'GOOD', SYSTIMESTAMP);
