INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '평일에 8시까지 밖에 안해서 방문 못했는데 드디어 입성~ 굴뚝빵 너무 궁금해서 퇴근하자마자 갔지만 몇개 안남아서 아쉬웠어요.🍰🍞 직원분이 추천해서 침니당고와 아이스아메리카노 주문했는데 당고가 굳어서 데워 주셨어요. 그래도 금방 다시 굳으니 참고하셔요. 치즈가 포함된 눅진한 크림이 가득 들어있고 많이 달지 않아서 커피랑 먹기 딱 좋았어요😍☕️ 1인1음료이니 참고하셔요. 1층과 2층 이색적인 인테리어와 아늑한 분위기가 데이트하기 좋고 큰 테이블도 있어서 단체모임하기 좋아요. 외국인 손님이 은근 많고 테라스 야외테이블도 많으니 봄 가을에 이용하기 좋겠더라고요🌳👍', 60, 17, 'GOOD', SYSTIMESTAMP);
