INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '기본빵 라인 좋아하는데, 씨솔트맛 먹고 반해부렀습니다. 🥰버터풍미+ 굵은 솔트+ 쫀득 빵 조화 너무 좋아요 입덧 심해서 요새 빵도 가리는데 (?) 진짜 맛있게 잘먹었네요 ..! 굴뚝빵이 가운데 비어서 안쪽 면까지도 겉면 처럼 맛있어요 !! 크기가 부담스럽게 크지않아서 애도 어른도 먹기 좋고 밥먹고 후식으로도 충분히 맛있게 먹을것 같아요:> 아이스크림이랑 섞는 메뉴도 있어서 당떨어지는 날 또올래요!!!♥️', 95, 24, NULL, SYSTIMESTAMP);
