INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '지나가다 아이스크림에 체리 올라가있는 팻말 보고 왔는데 문열자마자 분위기가 달라서 놀랐고 직원분 응대에 또 한번 놀랐네요 태블릿으로 결제하길래 결제하면 바로 적립 화면으로 넘어가는줄 알고 말씀 안드렸는데 안돼서 적립 요청드리니까 적립하시겠어요? 이러면서 다시 결제할게요 하시는데 뭔가 화를 참으시는 것 같았어요 옆에 계시던 남자 직원분은 친절하셨는데 여자분은 손님이랑 기싸움하자는건지 모르겠네요 음식은 아이스크림이랑 초코랑 조화도 좋았고 밑에 빵도 부드럽고 맛있었어요 제가 시나몬을 안좋아하는데 은은하면서도 입안에 오래 남는게 나쁘지 않았어요 그럼에도 불구하고 재방문 의사는 잘 모르겠네요', 59, 15, NULL, SYSTIMESTAMP);
