INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '와 분위기나 인테리어 너무 좋아요!! 갠적으로 2층이 더 좋음bb 평일이라 웨이팅도 없이 바로 들어왔구 빵도 다 맛있어보여서 고민 많이 했는데 피스타치오로 골랐ㅇ어요!ㅎㅎ크림 진짜 맛있다.... 담에 또 올 듯!!!', 5, 5, 'GOOD', SYSTIMESTAMP);
