INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '굴뚝빵이 신기해서 왔는데 안에 필링도 다양하고 골라먹는 재미가 있네요 딸들이 다 먹고싶어해서 고르고 골라서 더티, 토마토필드, 피자빵 먹어요. 애미는 시나몬롤 먹고싶은데 ㅎㅎ 커피랑 마시니 천국이네요~~♡', 32, 1, NULL, SYSTIMESTAMP);
