INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '지방에서 온 친구들과 특별하고 이색적인 카페에 오고 싶어서 찾아왔어요.분위기가 차분하고 굴뚝빵도 특이하고 맛있어서 특별한 추억 만들고 갑니다.들어오자마자 시나몬향이 나서 기분이 좋아요!', 23, 4, 'GOOD', SYSTIMESTAMP);
