INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '넘 와보고 싶었는데 주말 6시 30분쯤 방문하니 품절인 굴뚝빵이 꽤 있네요ㅠㅠ 선물박스도 있어서 주변에 선물하기 좋을 것 같아요 그래도 여름이라그런지 사실 아이스크림에 끌려 방문했슴다 ㅋㅋㅋ 분위기 넘 특이하고 노래도 좋고 인테리어 아늑해요 리뷰 남기면 씨솔트 or 시나몬 굴뚝빵 1개 증정해주는 이벤트도 진행중! 베스트 피스타치오 아이스크림 : 비쥬얼부터 넘 예쁘고,  가벼운 우유 아이스크림이라 맛있어요! 밑에 굴뚝빵은 피스타치오 맛보다 시나몬 향이 더 강해요! 아메리카노 고소한 원두라 제가 좋아하는 맛입니다 재방문의사100000%👍', 31, 0, 'GOOD', SYSTIMESTAMP);
