INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '지나다니면서 봤었는데 냄새가 넘 좋아서 들렸어요! 들리자마자 시나몬 향이 진짜 최고 ··· 👍 빵도 세 개나 시켰는데 기본이랑 다른 것들도 진짜 너무 맛있더라구요 ㅠㅠ 세상 사람들이 다 여기로 왓으면 좋겟어요... 친절하신 분들입니다 번창하세요 🫶🏻', 20, 0, 'GOOD', SYSTIMESTAMP);
