INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '굴뚝빵 안에 크림들이 딱 알맞게 들어차 있어요. ^-^ 홍대에 이색 디저트 카페가 있어서 데이트 하러 오기도 좋은 듯해요. 종류가 다양해사 골라 먹는 재미두 좋고 무엇보다 가격대가 적당하고 커피도 안 비싸더라고요. 가성비 좋네요~~~♡', 24, 1, 'GOOD', SYSTIMESTAMP);
