INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '침니맨션..! 이름 그대로 굴뚝모양의 가운데가 뻥 뚫린 독특한 컨셉의 빵이 여러종류가 다양하게 있어서 고르는 재미가 있어요~ 매장도 시원하고 분위기도 차분하니 좋아서 얘기하기 좋네요☺️', 63, 11, 'GOOD', SYSTIMESTAMP);
