INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '와~~~ 홍대에 이런곳이ㅠㅠ 홍대 분좋카 홍대 카페맛집 홍대카페 찾는분들 여기 트라이 하십셔 넘 마시써용 …. 화이트초코에 땅콩잼(?)뿌려진거 진심 존맛 !!!', 76, 16, 'GOOD', SYSTIMESTAMP);
