INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '처음 와봤는데 와 가게가 너무 멋있어요! 게다가 사장님(?)은 누가봐도 요 가게처럼 멋지셔요🐹 굴뚝빵 한국에서 첨 먹어봤는데 쫄깃담백..맛도리 그 자체 자주 오는 동네는 아니지만 오게 되면 종종 포장해갈거 같아용👍', 41, 10, 'GOOD', SYSTIMESTAMP);
