INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '굴뚝빵이 여러 종류가 있는데, 다 준수하게 맛있고.. 인테리어가 엄청 깔끔하고 이뻐요. 분위기도 좋고 맛도 좋은 곳인 것 같습니당', 0, 7, 'GOOD', SYSTIMESTAMP);
