INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '굴뚝빵 파는곳이 얼마 없는데 다양한 종류가 있어서 너무 좋아요!! 실내 분위기도 아늑하고 시원하고 체코 분위기 나서 넘 좋네요!', 2, 1, 'GOOD', SYSTIMESTAMP);
