INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '빵 너무 신기하고 메뉴가 다양해서 고르는 맛이 있었어용✨ 이번에 토마토 바질 맛이 품절이라 못 먹었는데 다음에 오면 먹어보려구요🥺🥺 맛있게 먹고 갑니당 ~🥰', 10, 3, 'GOOD', SYSTIMESTAMP);
