INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '공연보러 합정에 왔다가 우연히 방문하게 된 이 곳. 경쾌한 음악과 함께할 수 있어요 :) 굴뚝빵이 정말 쫄깃하니 맛있어요~~!! 재봉가위(?)로 자르는 느낌이 좋네요~! 든든하게 잘 먹었습니당!!', 29, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '홍대 굴뚝빵으로 유명한 대형카페 "침니맨션" 다녀왔는데요! 유럽풍의 주택을 개조한 카페라 완전 감성 넘치고 포토스팟도 굉장히 많았어요 1층부터 2층까지 이용 가능한 대형카페라 완전 취향저격이었어용 ​ 굴뚝빵은 종류가 정말 많았는데 대파베이컨, 침니당고, 바질토마토, 시나몬, 피스타치오, 고구마, 초코, 딸기까지 고르기 힘들 정도로 맛도리 디저트 천국이었어용 ​ 저는 오레오아이스크림, 침니당고, 바질토마토 굴뚝빵 먹어봤는데 아이스크림 굴뚝빵 완전 추천이에요! 맛도 6가지라 원하는 맛으로선택 가능하고 달달한 굴뚝빵+시원한 아이스크림 조합 여름에 이것보다 맛있는게 있을까용😋 ​ 침니당고, 바질토마토 안에 크림치즈가 정말 존맛탱 가게 분위기부터 맛있고 달달한 굴뚝빵까지 포장패키지도 이뻐서 선물용으로도 추천이에용!', 8, 10, 'GOOD', SYSTIMESTAMP);
