INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '해외에서 유명한 굴뚝 빵 한국에도 있어 그냥 갈 수가 없더라고요! 매장 들어와 보니 여러 가지 종류의 빵이 많아서 너무 고민되더라고요ㅠㅠ 빵자체도 맛있는데 토핑이 너무 가득이라 더 좋았어요!! 오신다면 피스타치오 곡 드셔보세요!!♥', 12, 1, 'GOOD', SYSTIMESTAMP);
