INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '우연히 들렸는데 빵이 멋지게 나열되어있네요 3가지 구매했는데 그중 토마토바질이 제일 맛있었어요 에그에그는 날이 더워 그런지 금방 쉬어서 못먹었어요 ㅠㅠ 아메리카노랑 먹어보기 좋을것 같아요', 48, 3, NULL, SYSTIMESTAMP);
