INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '굴뚝빵을 너무 먹고 싶어서 검색해서 찾아왔는데 분위기도 너무 좋고 상상한 맛 이상으로 맛있어요 아이들도 만있는걸 알아가지고 또 사달라고^^', 2, 1, 'GOOD', SYSTIMESTAMP);
