INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '처음 먹어보는 종류의 빵이었는데 정말 맛있게 먹었어요. 내부도 시원하고 인테리어도 너무 이뻐요 다음에 또 올 의향 있습니다 빵 고민되시는분들은 메론 추천드려요', 47, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '다른데 있는 침니맨션은 몇번 가봤지만 이곳은 분위기가 남다르네요 홍대라서 그런건지? 독특하고, 분위기 있습니다. 굴뚝빵은 말 안해도 맛있으니 설명할 필요가 없고 다음에도 또 오려구요 추천합니다!', 87, 15, 'GOOD', SYSTIMESTAMP);
