INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '체코에서 먹었던 굴뚝빵이 생각나 찾아갔어요! 현지하고 비교할 순 없지만, 파는곳이 많지 않아 생각날때 다음에 또 방문 할 거 같아요. 제가 주문한 건 피스타치오와 피넛하우스에요. 피스타치오는 기본베이스인 시나몬침니에 피스타치오 크림이 들어가 있고, 피넛하우스는 기본베이스인 씨솔트침니에 다크초코와 땅콩가루 그리고 카라멜시럽이 살짝 뿌려져 있어요. 둘 다 맛있긴 했지만, 개인적으로 피넛하우스가 더 제 입맛에 맞았어요. 달달한 걸 좋아하는 저도 피스타치오 크림은 너무 달았고, 기본 시나몬침니도 시나몬 가루보다 설탕이 더 많이 뿌려져 있어 달았습니다. 영수증 리뷰로 받긴 했지만, 갖구운게 아니라 좀 딱딱해 많이 아쉬웠어요. 그에 비해 피넛하우스는 맛없없 조합으로 다크초코라 많이 달지 않아 맛있게 먹었습니다.', 18, 8, NULL, SYSTIMESTAMP);
