INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '회사 근처로 왔는데 분위기도 좋고 빵도 다양해서 좋아요!! 한번 먹어보고 너무 맛있어서 주변 지인들 선물하고 싶어서 또 들렸어요🩷', 66, 18, 'GOOD', SYSTIMESTAMP);
