INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '지나가다가 우연히 발견되어 홀린 듯 들어와보니.. 제가 유럽에 온 줄 알았어요... 🌟 카페 인테리어도 너무 예쁘고 빵 가격도 저렴해서 가볍게 커피와 함께 먹기 좋은 것같아요 분위기도 좋아서 앞으로 지나갈 때마다 들를 것같아요😍😍😍', 41, 9, 'GOOD', SYSTIMESTAMP);
