INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '지나가다가 너무 힙한 뜨르들로 집이 있어서 들려보았어요!!! 시솔트랑 시나몬 맛이 기본인게 제일 제취향이네요 ㅋㅋㅋ그 외에도 감자맛이나 라즈베리 바닐라 같은 특이한 맛도 있어서 정신없이 골라담았어요🫶🏽 뜨르들로 맛집이 ㅈ진짜 없는데 강추합니다', 36, 5, 'GOOD', SYSTIMESTAMP);
