INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '빵종류가 많아서 뭐를 골라야항지 고민햇어요!! 다 맛있어보여가지구ㅠㅠ 인테리어도 너무이쁘고 사장님도 포스짱에 이뿌세오!!!🥰 이번에 굴뚝초코빵이앙 나이스미트투 먹어보고 다른맛먹으러 또올게용!!!♥️', 39, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '합저역근처 볼일보러 갔다가 저장해논 카페인 침니맨션이 갑자기 보여서 들어감;;  첨에는 소금빵인가 했는데,, 굴뚝빵이라고 함,, 매장인테리어도 전체적으로 굴뚝 감성인듯했음,, 굴뚝빵이 맛있어보이게 진열이 잘 되있어서 고르기 힘들었다,, 겉은 쫄깃하고 안에 들어간거에 따라서 조금씩 차이가 있었는데,, 안에 아무것도 안들어간 시나몬롤하고 피스타치오크림 들어간것 맛있었다!', 39, 7, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '합정역 골목골목 걷다 보면 빈티지 벽돌집 하나가 뿅!  마치 동화 속에 들어온 것 같은 🤎침니맨션🤎 여긴 헝가리식 ‘굴뚝빵’을 파는 디저트 카페인데, 주문하면 그 자리에서 빵을 슈우우웅 구워줘요. 겉은 바삭! 속은 몽글몽글➰따뜻한 굴뚝빵 한입 먹는 순간 행복해져요. 커피도 맛있고, 굴뚝빵도 맛있고🥹  주말에 오픈 시간에 맞춰가면 여유롭게 즐길 수 있어요.', 16, 7, 'GOOD', SYSTIMESTAMP);
