INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '토마토바질에이드 진짜 특이해보여서 시켰는데 완전 달달한 스테비아 토마토맛이라서 다음에 또 먹을거같아요 ㅠ 빵도 호불호없이 모두 좋아할거같은 맛이라 메뉴 다 먹어보고싶어요', 118, 22, NULL, SYSTIMESTAMP);
