INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '유튜브에서나 보던 굴뚝빵!! 파는 곳이 있길래 방문했어요 ㅎㅎ 아이스크림 추가한 굴뚝빵도 있고, 메뉴 종류도 정말 많아서 좋았어요. 무엇보다 매장 인테리어도 예쁘고 음료도 다양해서 친구들이랑 수다떨기 딱이었어요!', 32, 4, 'GOOD', SYSTIMESTAMP);
