INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '포장해사 친구들이랑 나눠 먹으려고 들렀는데, 너무 맛있어 보여서 루꼴라잠봉을 가게에서 바로 먹었어요! 진짜 맛있고 담백해서 만족했어요👍 다음엔 다른 메뉴도 꼭 먹어봐야겠어요~', 53, 12, 'GOOD', SYSTIMESTAMP);
