INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '이번주 친구랑 검색하고 왔다가 넘 맛있고 또 생각나서 지인이랑 또 왔어요~ 유럽 여행갔던 친구가 굴뚝빵 요기가 더 맛있다네요~^^ 단골 각 입니다~', 12, 8, 'GOOD', SYSTIMESTAMP);
