INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '분위기 정말좋고 아이스크림이 특이하고 맛있어요! 빵도 정말 퀄리티가 좋아요. 홍대카페 꽤 다녀 봤는데 이제 여기 자주 올거 같아요!', 95, 21, 'GOOD', SYSTIMESTAMP);
