INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '인테리어도 너무 멋지고 굴뚝빵을 팔고 있는데 종류도 너무 많아서 뭘 먹을지 정말 고민됐어요ㅎㅎㅎ 오랜만에 홍대 나왔는데 자리도 넓고 이렇게 예쁜 카페 찾다니 너무 좋은 거 같애요 배경도 진짜 이뻐서 사진도 잘 나오고 1층에는 약간 불이 나오는 거 같은 인테리어가 있고, 2층에는 천으로 되어 있는데 이런 부분이 너무 예쁜 것 같아요. >_<', 39, 7, 'GOOD', SYSTIMESTAMP);
