INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '굴뚝빵컨셉으로 인테리어도 굴뚝집이고 빵도 너무 맛있고 좌석도 너무 편하고 에어컨이 빵빵해서 대화하기 좋았어요 또 오고 싶어용~!', 38, 0, 'GOOD', SYSTIMESTAMP);
