INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '굴뚝빵을 처음 먹어보는데 맛있었어요. 아이스크림 메뉴도 있어서 여름에 시원하게 먹기 좋은 것 같고 빵 종류도 많아서 골라먹기 좋아요. 안이 너무 시끄럽지 않아서 대화하기 좋아요☺️', 5, 9, 'GOOD', SYSTIMESTAMP);
