INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '비오는 날 홍대 걷다가 우연히 발견한 카페인데 커피수혈이 필요한 찰나에 배이커리까지 맛있는 곳을 찾아서 완전 운이 좋았음!! 굴뚝빵 전문점이라 다양한 종류의 굴뚝빵이 있는데 비쥬얼부터 맛있어 보이는게 많아서 고르는데 시간 걸립니다. 메론크림 있는 꼬부기빵(?) 진짜 맛있음. 야외에도 테이블이 많은데 오늘은 비가와서 실내에만 있었지만 야외에서 커피마셔도 좋을듯?!', 2, 4, 'GOOD', SYSTIMESTAMP);
