INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '굴뚝빵 처음먹어봤는데 맛있어요! 아이스크림도 올려서 먹으면 밑에 있는 빵이 눅눅한데 달달하고 맛있어요 인테리어도 굴뚝이란 컨셉에 어울리게 멋있어여 ~ 맛도있고 분위기 좋으니 추천합니다 !', 20, 3, 'GOOD', SYSTIMESTAMP);
