INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '홍대 대형 베이커리카페 침니맨션에서 굴뚝빵 포장해왔어요. 매장에서 카페라떼도 마셨는데 분위기좋은 공간입니다. 친절해서 재방문 100프로 각입니다. 또 가고싶은 집이에요. 굴뚝빵 맛있어요.', 69, 17, 'GOOD', SYSTIMESTAMP);
