INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '우연히 지나가다 처음보는 카페 발견해서 들어왔어요 빵 종류가 엄청많더라구요 한입 먹어봤는데 빵이 엄청 쫀득한 느낌이구 시나몬 향이 조금 나면서 진짜 맛있더라구요 완전 제 취향입니당 우연히 들른곳 저장하고 자주 들리겠습니다', 85, 12, 'GOOD', SYSTIMESTAMP);
