INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '공간이 너무 예쁘고 특별한 메뉴가 있어요 평일 오전에 왔더니 굴뚝빵 종류도 엄청 많고 조용해서 좋았어용 빵이랑 시그니처 커피 후추크림이 넘 맛있어요🤤', 49, 1, 'GOOD', SYSTIMESTAMP);
