INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '와 유럽에서만 볼 수 있는 굴뚝빵을 한국에서 보다뇨ㅠㅠ 너무ㅜ너무너무 반가워서 냉큼 들어왔는데 아이스크림도 진짜 부드럽고 좋았어요!! 잘먹겠습니다 다음에 또 올게요!', 12, 1, 'GOOD', SYSTIMESTAMP);
