INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '빵 포장하러 들렸는데 알바생인지 직원인지..주말에 방문했는데 주문이 밀린것도 아니고 다 포장기다리는데 너무답답해서..느릿느릿 ..세월아 네월아..진짜 포장하는데 20분 기다리네요 .. 보니까 봉투에 담고 테이프하나 붙이면 끝이던데..이렇게오래걸릴 일인가요?', 40, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '서울여행중, 홍대쪽에 방문할 일이 생겨서 들렸다가 아쉬워 방문한 카페였는데 일단 매장이 너~무 시원해서 들어서자마자 좋았어요, 커피도 맛있었구요. 다만 가게가 조금 관리 안 된 느낌이 있긴했지만 크게 중요하진 않았습니당. 빵도 생각보다 맛있었어요! 크림 든 걸 먹을까하다가 화이트 초코랑 피스타치오가 붙어있는걸 먹었는데 크림이 필요없는 맛이었어요. 전체적으로 좋았습니다', 48, 0, NULL, SYSTIMESTAMP);
