INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '맛있는 굴뚝빵들이 많고 인테리어도 예뻐요ㅎㅎ여름이라 아이스크림 들어간 굴뚝빵을 먹었는데 추천드립니다🫶🏻👍🏻✨크림도 맛있어요!!', 20, 4, 'GOOD', SYSTIMESTAMP);
