INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '홍대 나들이 갔다가 지나는 길에 체코의 굴뚝빵이 생각 나서 들렀어요 미니 사이즈의 굴뚝빵 모양에 다양한 속 재료들이 어우러져 어느빵하나 맛있어 보이지 않는 빵이 없네요~ 포장으로 사왔는데 나중에 카페에 들러서  여유롭게 커피와 함께하기 좋은 디저트류가 많네요~ 또 들를게요^^', 26, 7, 'GOOD', SYSTIMESTAMP);
