INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '굴뚝빵을 파는 곳이 있다고 해서 찾아와봤어요. 침니 맨션이라는 이름 답게 마치 유럽 게스트 하우스 느낌의 인테리어가 인상깊었어요. 굴뚝빵도 너무 맛있네요. 합정 오면 들려보세요.', 23, 5, 'GOOD', SYSTIMESTAMP);
