INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '빵도 하나하나 너무 예쁘고 너무 맛있고 고소해서 완전 매력적이에요! 뷰도 너무너무 예쁘고 여자친구가 굴뚝빵을 너무 좋아해서 왔어요 처음왔는데 너무 매력적이라 다음에 와서 커피랑 같이 즐길 거에요💕', 4, 5, 'GOOD', SYSTIMESTAMP);
