INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '굴뚝빵이 궁금해서 가봤어요! 굴뚝의 구멍을 모티브로 재밌게 해석한 빵집인득한데, 한국인 및 외국인 손님도 많았어요! 사장님이 마케팅 잘하신듯 👍 2층으로 된 카페가 공간이 넓고 이색적인 인테리어가 인상적인곳입니다! 데이트장소로도 딱! 완전 강추에요😛', 267, 85, 'GOOD', SYSTIMESTAMP);
