INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '빵들이 다 너무 맛있고, 고소해요 ! 아이스크림도 빵이랑 너무 잘어울려요~ 완전 유럽식 분위기고 카페도 넓어서 많은 친구들이랑 같이 오기도 좋아요:)', 63, 13, 'GOOD', SYSTIMESTAMP);
