INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '정말 분위기 최고예요. 빵도 각 특색이 많아서 고르는 재미도 컸는데, 시그니처 메뉴인 아이스크림도 맛과 비주얼 좋았어요. 분위기도 좋아서 무언가 1층 및 2층 모두 편하게 인테리어를 즐기면서 머물기 좋았어요. 전체적으로 많아 달지 않아서 더 좋았어요. 재방문의사 많아요^-^', 65, 11, 'GOOD', SYSTIMESTAMP);
