INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '분위기 자체가 너무 멋있고 아늑한데 날씨 좋을때 오니까 더 좋아요! 데이트 하기에 너무 좋은것같아요 빵도 예쁘고 다른 카페들과 다르게 많이 비싸지 않아 더 좋은것같습니다!◡̎ 종류도 다양하고 조아여', 70, 13, 'GOOD', SYSTIMESTAMP);
