INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '굴뚝빵으로 유명한 이곳은 홍대 이색 카페 중에서도 단연 눈에 띄는 곳!! 가보고싶었는데 드디어 다녀왔어요~이곳을 다녀오고 나서 느낀 건, 단순히 맛있는 빵집을 넘어 홍대 놀거리로도 방문하기 좋은곳이에요!! 따뜻한 빵과 우유까지 즐길 수 있어 좋아요!', 80, 18, 'GOOD', SYSTIMESTAMP);
