INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '분좋카으ㅣ 대명사 대표메뉴인 침니커피 독특하고 맛있아요 아바라에 크림과 후추 넣은 음료인데 크림도 안느끼하고 중간중간에 느껴지는 후추향이 정말 별미!', 9, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '귀여운 빵과 맛있는 커피가 있어요! 빵도 종류가 정말 많고 예뻐서 맛있을 것 같아요! 데이트 코스에 완전 추천 해요! 커피도 맛있고 빵도 완전 맛있어요!!', 43, 9, 'GOOD', SYSTIMESTAMP);
