INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '지나가다 굴뚝빵 비주얼에 홀려서 들어간곳..✨ 굴뚝빵이란거도 신기한데 토핑도 다양해서 고르기 힘들었어요 음.. 솔직히 가격은 사악한거 같음 그래도 시나몬이랑 당고빵 맛있어요👍 카페 분위기도 좋고 안에 인테리어도 예뻐서 담에 방문하면 안에서 먹을거 같아요ㅎㅎ', 87, 17, 'GOOD', SYSTIMESTAMP);
