INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '분위기가 너무 좋고 좌석이 편하고 넓어요! 굴뚝빵이 종류별로 굉장히 많아서 고르는 재미가 있어요🥹❤️ 혼자 와서 포장 했는데 다음에는 친구랑 오고 싶어요!', 28, 1, 'GOOD', SYSTIMESTAMP);
