INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '매장이 깨끗하고 조용해서 대화하기 좋아요! 단체석도 프라이빗한 공간도 있어 연인 또는 친구들과 와도 좋은 카페일듯 싶네요. 디저트도 다양하고 맛있고 무엇보다 특이한 빵이라 꼭 드시길 추천합니다. 소중한 사람과 좋은 시간 보내다 가요~', 34, 10, 'GOOD', SYSTIMESTAMP);
