INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '지나가다가 예뻐보여서 우연히 들어왔는데 여기에 유명한 굴뚝빵이 종류별로 많고 전부 너무 맛있어보여서 고르기 정말 힘들었어요🥹🥹 좌석은 2층까지 있는데 테라스도있구(아직 정식(?)개방은 안하셨다고함) 그치만 예뻐서 앉았어용 커피도 빵도 정말 맛있구 분위기도 넘넘 죠아요🥰🩷 홍대 놀러오면 꼭 다시 오게씀미다 💛💛', 35, 7, 'GOOD', SYSTIMESTAMP);
