INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '친구랑 유럽에서 먹은 굴뚝빵이 너무 생각나서 서치해서 찾아왔어요!! 분위기듀 너무 좋고 가격도 괜찮아요 친구랑 너무 좋다면서 극찬하며 먹었네요!! 굴뚝빵 먹어보고 싶었던 분들은 여기 꼭 오세요!!🫶🫶❤️‍🔥', 57, 13, 'GOOD', SYSTIMESTAMP);
