INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '굴뚝빵 처음 먹어봤는데 맛있네요 쫀득하고 맛있어요~ 촉촉해서 좋네요! 매장 넓직해서 좋습니다~~ 아이스크림 느끼하지 않아서 좋아요~', 17, 8, 'GOOD', SYSTIMESTAMP);
