INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '맛있어요 컨셉츄얼 해서 데이트 용으로도 오기 좋은듯 다만 손님이 없을 때에도 빵을 여러개 사도 음료를 같이 꼭 시켜야해서 그건 단점인듯 합니다 그리고 이거 없다 이 메뉴는 안된다 이걸로 대체해야된다 등 내 돈 주고 먹는데 제한 사항이 많네요', 40, 0, NULL, SYSTIMESTAMP);
