INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '우연히 들린 카페~이런 소금빵 처음이에요. 여름날 들어오면 시원하게 앉아서 이야기 나눌 수 있는 곳~!  음식 포장해서 아이들에게 주려고 해요. 나만 먹을 수 없는 아까워서요.', 40, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '체코에서 먹어본 굴뚝빵을 한국에서 먹을 수 있는 몇 안되는 장소에요! 조용한 분위기에 인테리어도 가게 이름과 어울려서 좋아요 :) 특히 2층에서 굴뚝빵과 아이스크림을 같이 먹으면 bbb', 24, 9, 'GOOD', SYSTIMESTAMP);
