INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '매장 위생 관리하셔야할 것 같아요. 빵 진열대도 너무 더럽고 바닥이랑 테이블도 더럽고 천장에 거미줄까지... 계단에도 쓰레기가 굴러다녔어요. 그리고 기다리는 손님 없었는데 커피 두잔 받는데도 20분은 기다린거 같네요.', 69, 14, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '우와앙 빵이 너무 맛잇어요!! ㅠㅠㅠㅠ 안에 인테리어도 너무 이쁘고 분위기 좋아요!!! 💙 디저트는 말할것도 없고 정말 어버버버 했어요! 소리없는 비가 내릴 것 같은 분위기가 취향이신가요 🫶🏻 재방문의사 200%', 43, 2, 'GOOD', SYSTIMESTAMP);
