INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '굴뚝빵을 한국에서 먹을 수 있어서 너무 좋았어요! 메뉴도 진짜 많고 다 맛있어요. 메론 거북이빵은 안에 메론 크림이 들어있는데, 메론이 메뉴이름에 적혀있는 거 치고 메론맛나는 거 못봤는데, 얘는 ㄹㅇ 메론 맛 나고 크림도 안 느끼해요 ㅎㅎㄹ 피스타치오랑 굴뚝 아이스크림빵도 맛있어요 ㅎㅎ', 71, 16, 'GOOD', SYSTIMESTAMP);
