INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '블로그보고 방문했는데 빵 종류도 다양하고 가격도 합리적이라 무조건 재방문!! 무엇보다 커피도 맛있고 빵도 맛있어요ㅠㅠ 카페 인테리어도 제스탈입니다ㅎㅎ 담번엔 친구들이랑 같이오려고요~ 무조건 추천합니다!!', 29, 6, 'GOOD', SYSTIMESTAMP);
