INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '굴뚝빵을 너무 좋아하는데 달콤하게 먹는 디저트로도 완벽하고 먹을 때마다 행복해져서 진심 홍대올 일 있을 때마다 맨날 오는 곳입니다… 🥺🥺🥺🥺 저번에 왔을 때랑은 구성이 조금 달라져서 고르는 재미도 있었어요! 많이 파세요 ❣️', 28, 0, 'GOOD', SYSTIMESTAMP);
