INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '채코 프라하에서 매일매일 먹을 정도로 너무 좋아하는 굴뚝빵이 한국에서도 먹을 수 있다해서 한 걸음에 달려왔어요!! 프라하에서 처럼 똑같이 구워서 파는게 너무 신기!! 야러분도 좋은 곳 와서 맛난 빵 드시고 가시면 좋을거 같아요!', 3, 6, 'GOOD', SYSTIMESTAMP);
