INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '데이트로 방문했는데 너무 좋았어요! 조용하니 대화하기도 좋고, 인테리어 분위기도 훌륭해요🩷✨ 직원분들도 친절하셔서 담에 부모님 모시고 한번 더 오고 싶은 곳이에요🪽', 65, 13, 'GOOD', SYSTIMESTAMP);
