INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '생각했던 것보다 훨씬 멋진 인테리어에 반했어요..!! 굴뚝빵 종류도 다양한데 벌써 어떤 것들은 품절..!!ㅠㅠ 다음엔 고구마 먹어보고 싶네요!! 응대도 친절하게 해주셔서 좋았습니다 :)', 20, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '굴뚝빵젭이 여기에 있었는지 몰랐는데 지나가는 길에 들르게됐어요 ㅎㅎ 다양한 굴뚝빵들이 있네용 ㅎㅎ 나중엔 밤에와서 코젤맥주랑 같이 먹어봐야겠어요!', 35, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '아이들과우연히홍대를왓다가 커피마시러찾고잇엇는데 빵이눈에띄어서들어서들어왓어요 ㅎ굴뚝빵이래요^^ㅎ빵은포장해서가족들이랑먹고싶고크림이너무신기햇니주문햇서주문햇어요 너무부드러운맛이에요 잘나간다고하시더라고요^^', 67, 11, 'GOOD', SYSTIMESTAMP);
