INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '서울에 이렇게 맛있는 굴뚝빵이있다니!! 이근처 가신다면 꼭 가보세요 넘 맛있어요ㅠㅠ종류 넘 많아서 고르기 힘들었는데 시나몬 굴뚝빵이랑 침니쿠키 굴뚝빵 .. 진짜 맛있었어요 ㅠㅠ안에 생크림들어가서 진짜 부드럽고 맛있고 다하더라구요🥹 커피도 넘맛있었어요!', 58, 11, 'GOOD', SYSTIMESTAMP);
