INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '굴뚝빵이라고 해서 기본만 있을 줄 알았는데 종류가 많고 다양해요. 인테리어도 너무 예쁘고 벚꽃이 피는 날 야외 자리가 있다면 너무 좋을 것 같아요.', 125, 19, 'GOOD', SYSTIMESTAMP);
