INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '굴뚝빵 맛집!! 다양한 맛과 토핑의 굴뚝빵과 음료 커피 그리고 굴뚝빵에 채워 주는 아이스크림까지… 메뉴 구성과 맛 모두 대만족!! 인테리어도 감각있고 사장님 정말 친절하세요. 홍대 힙플레이스 맞네요', 2, 6, 'GOOD', SYSTIMESTAMP);
