INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '빵이 너무 예뿌고 마싯어요 ,,, 비 오는 날 맛있어보이는 곳 발견해서 !!! 네이버에 쳐보구 들어왔는데 아쉽게도 강고는 품절이라 없었지만 각종 굴뚝빵을 구매해씁니다 기분 좋은 빵냄새가 가득해요 🤤', 38, 0, 'GOOD', SYSTIMESTAMP);
