INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '조금만 더 늦었더라면 못 먹었을 굴뚝빵 ! 인기가 너무 좋아서 오전에 방문 하지 않으면 아이스크림 빵은 먹지도 못 하더라구요 🥲컹스 다음엔 오전에 방문해서 꼭 먹을 거예요. 커피랑 빵 모두 맛있었고, 직원 분이 친절해서 기분 좋았습니다🐶', 29, 3, 'GOOD', SYSTIMESTAMP);
