INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '그냥 길 가다가 빵 냄새가 너무 맛있게나서 들어가볼까 하고 들어와봤는데 들어오니 빵냄새가 역시나 미쳤고 흔하게 볼 수 없는 굴뚝빵도 있고 빵이 진짜 너무 맛있고 우유랑 함께 먹었는데 우유가 달지 않고 저지방 우유 맛이 났는데 정말 맛있더라고요 우연히 들르게 된 건데 너무 좋습니다. 인테리어도 정말 특이하고 예뻐요 카페 분위기가 조용해서 얘기하기도 좋고 작업하기도 좋을 것 같아요', 49, 1, 'GOOD', SYSTIMESTAMP);
