INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '외관이 범상치 않아 들어와봤는데 이국적인 옛정취가 녹아있는 정감있는 곳이었습니다. 게다가 참한 외국인 언니가 오더를 받는 곳~😻 허기가 질까 싶어 야채와 햄이 조금이라도 들어있는 루꼴라잠봉(?)을 시켰는데 빵 표면에 시나몬 설탕이 코팅되어있어 느끼하지 않았어요. 달콤해서 에너지 충전하기 딱이고 제공해주신 가위로 커팅하면 한 입에 들어가기에 간단하게 먹기 좋은 거 같아요. 이층에서 드시면 소소한 동네 길거리 구경도 하실 수 있어요. :) 참, 점심이벤트로 할인도 해주시네요. 들어오기를 참 잘했습니다. 또 올게욤💗', 7, 2, 'GOOD', SYSTIMESTAMP);
