INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '굴뚝빵을 한국에서도 맛볼 수 있다니 홍대근처에서 놀다가 끌린듯이 들어왔어요ㅎㅎ 메뉴도 정말 다양하고 내부 인테리어도 기가막히더라구요 무엇보다 너무 맛있어요ㅠㅜ데이트 코스로도 딱입니당', 64, 13, 'GOOD', SYSTIMESTAMP);
