INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '홍대에서 시간 떠서 대형카페 찾다가 방문했어요 2층이고 자리도 많아요 컨셉이 굴뚝인데 귀여워요.. 먹고 싶은 빵들이 너무 많아서 고르기 힘들었어여', 24, 3, 'GOOD', SYSTIMESTAMP);
