INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '크리스마스이브날 점심 무렵 방문했는데 이국적인 분위기에 굴뚝 컨셉 인테리어에 반했어요.❤️그리고 굴뚝빵도 이렇게나 다양하다니! 굴뚝빵계 최강자 카페네요! 식사대용 샌드위치같은 굴뚝빵도 있고 디저트로 좋은 굴뚝빵도 있네요. 브런치용으로 잠봉뵈르햄, 소시지 들어간 것으로 골랐는데 넘 맛있게 먹었어요. 아이들도 신기해 할 것 같아 다음에 같이 방문하고 싶네요. 굴뚝빵 이색빵이라 선물로도 특별할 것 같아요. 크리스마스 미니케이크와 슈돌렌 가격도 착하네요.❤️침니맨션티도 티팟에 작고 귀여운 찻잔에 나와 기분좋게 잘 마셨습니다. 침니맨션 와서  행복과 행운의 기운을 받아갑니다.', 125, 22, 'GOOD', SYSTIMESTAMP);
