INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '홍대 주변 놀러왔다가 추워서 분위기 있어보이는 카페 아무곳이나 들어온 건데 왠걸… 컨셉이 확실한 카페였습니당☕️✨ 굴뚝빵이 가득한데 특색도 있어요 점심 적당히 먹고 왔으면 무조건 먹었을것ㅠㅠ 아이스티를 좋아하는 입장에서 얼그레이피치 추천합니당 좌석은 그리 많지 않아서 창가에 앉았는데 대화하기 좋았어요', 74, 12, 'GOOD', SYSTIMESTAMP);
