INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '합정카페 검색하다가 비쥬얼에 반해 오게 되었어요! 다 맛있어보여서 결정이 힘들었어요 ㅠㅎㅎ 빵이 너무 부드럽게 맛있어요👍크림도 너무 부드러워요~다음에 합정오면 또 찾아올게요~^^', 47, 7, 'GOOD', SYSTIMESTAMP);
