INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '항상 오고 싶었던 곳 방문 했어요. 보자마자 빵이 너무 다 맛있어보여서 전부 먹고 싶었어요. 사장님도 너무 친절하세요. 재방문 하고 싶어요!', 21, 10, 'GOOD', SYSTIMESTAMP);
