INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '굉장히 특이한 인테리어에 카페였는데 아늑해서 조용히 책읽거나 친구들 모임에 좋을 것 같았어요. 시그니처인 굴뚝 빵도 맛있고 아이스크림 들어간 굴뚝 빵도 특이하니까 한번 드셔보시길 추천 드려요.', 18, 7, 'GOOD', SYSTIMESTAMP);
