INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '굴뚝빵 맛집이라 찾아왔어요 ㅎㅎ 들어오자마자 고소하고 달콤함 냄새…ㅎㅎ 너무 늦게와서 명란은 없다는게.. 아쉽.. ㅠ 카페 너무 예뻐서 좋아요 ㅋㅎㅋㅎㅋ', 38, 5, 'GOOD', SYSTIMESTAMP);
