INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '내부가 조금 추웠는데 (나중에 온도 올려주심) 저 안에 담긴차가 식지도 않더라구요! 맛도 좋고 맛있었어요 ! 빵은 생각했던거랑 달랐지만 맛있었어요 내부 인테리어도 좋았고 자리도 좋고 직원분도 너무너무 친절하시고 설명도 차분하게 잘해주시고 근데 혼자 계셔서 너무 바빠 보였어요 첨엔 2~3분계셨던것 같은데 얼굴 새빨게 지시도록 요리뛰고 조리뛰고 이거하고 저거하고 아들같아서 도와주고 싶었음 ㅠㅠ 보니까 내야할것도 내놔야하고 손님들 불편사항까지 시간이 조금 걸리지만 다 체크하고 계셨음 대단하세요 이곳은 친절해서 더 가고싶음', 2, 7, 'GOOD', SYSTIMESTAMP);
