INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '홍대이색카페입니다! 체코 분위기의 유럽 가정집스탈의 넓은 대형카페! 체코 전통빵 트르들로 굴뚝빵까쥐 >.< 분위기도 넘 좋라요🤍 녹차라떼 진하고 달달하고 존맛이요!!💚💚 #협찬', 68, 13, 'GOOD', SYSTIMESTAMP);
