INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '침니피스타치오 아이스크림과 침니솔트 먹었는데 맛있어요 갓 구워낸 침니브레드, 꼭 드셔보세요 카페 분위기도 독특하지만 편안해서 좋아요', 52, 15, 'GOOD', SYSTIMESTAMP);
