INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '작년에 방문하고 두번째 방문인데 메뉴도 많이 추가되고 딸기 들어간 메뉴도 나왔는데 맛있어요 다음엔 또 어떤 메뉴가 추가될지 기대돼요 😆😆', 39, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '침니맨션이라는 말이 바로 이해되는 곳이었어요! 굴뚝빵이라는 말에 잘 어울리는 빵도 너무 맛있고 내부 인테리어도 너무너무 귀여워요! 곳곳에 포토존도 잔뜩인데 빵이 일단 너무 맛있어요bb 사진으로도 느껴지는 귀여운 빵과 커피도 너무 맛있었어뇽!!', 86, 17, 'GOOD', SYSTIMESTAMP);
