INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '침니맨션 카페  빵 정말 맛있어요! 시끄럽지도 않고 인테리어도 너무 예쁘네요. 우연히 지나가다가 들렀는데 빵이 생각나서 다시 들립니다. 여전히 맛있어요❤️ 매장안도 시원해요!', 19, 5, 'GOOD', SYSTIMESTAMP);
