INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '올때마다 진짜 맛있게 먹고 있어요!!! 처음이 아니라 몇 번째 방문인데 근처 올 일 있으면 가족들 몫까지 포장해가곤 합니다!!! 정말 최고에용', 7, 6, 'GOOD', SYSTIMESTAMP);
