INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '빵 종류가 많아서 고르는데 시간이 엄청 오래걸렸어요. 빵도 맛있고 안에 인테리어도 예뻐서 데이트 할 때 오기 좋은 것 같습니다.', 11, 2, 'GOOD', SYSTIMESTAMP);
