INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '처음 와 봤는데 너무 인테리어가 너무 이쁘고 해리포터 느낌이 나서 신기 했어요 빵도 종류가 너무 많아서 좋았어요… 너무 다 맛있게 생겨서 고민만 5분 정도 한거 같아요!! 나중에 남자친구랑도 다시 한번 재방문 하려구요 ㅎㅎ 사장님 번창하세요❗️', 26, 10, 'GOOD', SYSTIMESTAMP);
