INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '굴뚝빵이 먹어보고 싶어서 들른곳이에용 여러 토핑들로 채워진 고르는 재미가 있어요! 아메리카노도 맛있고, 허니레몬진저티도 맛나요😆 2층 자리도 좋고 1층자리도 분위기가 정말 좋아서 데이트하기 좋은 곳 같습니당~~~', 116, 25, 'GOOD', SYSTIMESTAMP);
