INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '빵 종류가 굉장히 다양해서 누구든 하나정도는 취향에맞는 빵을  건질수있을정도에요! 커피도 깔끔하니 맛있고 가격도 합리적이라서 너무 좋아요. 가게 분위기가 따뜻해서 겨울 눈 오는 날 방문했더니 몽글몽글 기분좋은 데이투 하다 갈 수 있어서 좋았어요 재방문의사 매우있습니당~~', 6, 10, 'GOOD', SYSTIMESTAMP);
