INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '빵이 맛있어요ㅠㅠ전에 홍대 다니면서 외관이 너무 예뻐가주구 따로 찍어왔는데 드디어 왔네요. 겉에는 설탕가루 같은게 씹히고 안에는 버터맛나면서 쫀득쫀득했어요. 맛있게 먹고 갑니다.', 45, 1, 'GOOD', SYSTIMESTAMP);
