INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '서울 빵지순례를 떠나는날 홍대, 합정, 대형 베이커리 디저트 카페 침니맨션에서 재미있는 체코굴뚝빵을 먹는 날 - 굴뚝청소, 빨래 널기, 테라스 까지 재미있는 테마의 인테리어에서 다양하게 즐기는 체코 굴뚝빵. 주문과 동시에 구워 주는 시그니처 굴뚝빵은 꼭 드셔 보세요 ​침니시나몬 침니페퍼 침니솔트 음료도 맛있어요. 부드러우면서도 향긋한 차의 향 - 밀크티 진하고 깊은 에스프레소가 들어간 라떼에 달콤한 바닐라를 추가한 바닐라라떼. 침니맨션의 굴뚝빵과 즐기기에 좋은 음료입니다. ​ 맛있고 다양한 굴뚝빵과 재미있는 인테리어에 즐거운 시간 보내고 갑니다- 데이트 코스로도 추천해드리고 싶습니다!', 26, 5, 'GOOD', SYSTIMESTAMP);
