INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '옛날 유럽에서 먹었던 기억으로 굴뚝빵 찾아다녔는데 드디어 와보네요🥹 즉석에서 구워주셔서 따뜻하고 담백하고 고소해요. 시킨 음료도 처음에는 잔 하나에 나오나 싶어서 조금 비싼가 싶었는데, 포트에 나와서 엄청 가성비 좋게 느껴졌어요. 맛도 정말 있었구요! 합정에 오시면 한 번씩 들려보세요 😁', 16, 8, 'GOOD', SYSTIMESTAMP);
