INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '#협찬 홍대에서 체코 굴뚝빵 베이커리를 먹을 수 있는 이색 대형 카페 침니맨션🤎 외관부터 앤틱한 분위기 가득한데 연말 크리스마스 분위기에 맞게 꾸며져 있어서 인테리어가 더 예뻤어요❤️💚 시그니처 굴뚝빵 침니솔트도 아가베시럽이랑 먹으니 더 맛있더라구요 :) 든든한 식사대용으로도 추천하는 포테이토맨은 감자와 빵의 조합이 너무나도 좋았어요 ㅎㅎ 접시부터 커피잔까지도 느낌 가득한 침니맨션 또 방문할게요😊', 36, 2, 'GOOD', SYSTIMESTAMP);
