INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '음료는 맛있었는데 개인적으로 빵이 맛없었어요. 카스테라는 위에 설탕을 묻혔는지 식감이 별로였고, 명란마요는 소스가 끝에 안 뿌려져 있어 끝엔 그냥 빵 맛이었어요. 크림 종류는 못 데운다 해도 다른 건 전자레인지에 데워주시는 게 좋을 것 같아요. 빵이 조금 씹기 힘들더라고요.', 76, 17, 'BAD', SYSTIMESTAMP);
