INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '계속 가고싶었던 곳인데 드디어 지나가는길에 방문했어요. 생각했던 것보다 종류도 많고 아이스크림먹고 굴뚝빵 뜯어먹는데 츄릅 또 생각나요', 79, 15, 'GOOD', SYSTIMESTAMP);
