INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '인테리어가 멋지고 예뻐요 체코에서 굴뚝방 먹고 그리웠는데 이렇게 그리움을 충족할만한 곳을 우연히 찾아서 정말 좋았습니다 빈티지한 느낌과 넓은 매장을 원하시는 분들에게 추천합니다 빵도 아주 맛있어요', 335, 58, 'GOOD', SYSTIMESTAMP);
