INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '더블 피스타치오 사면서 직원분께 피스타치오 토핑 가져가도 되냐고 여쭤봤더니 흔쾌히 허락해 주셔서 잔뜩 가져왔어요 ㅎㅎ 저 피스타치오 진짜 존맛탱이에용!! 방문하시면 토핑도 드셔보세요 ㅎㅎ 크림은 고소하고 진한 맛이 확 느껴지고, 빵의 따뜻함과 피스타치오의 조화가 이렇게 완벽할 줄이야! 거기다 약간 유럽 감성이 느껴지는 인테리어에 조명이 은은해서, 빵 하나 들고 앉아 있으면 시간 가는 줄 몰라요. 무조건 재방문 각입니다ㅎㅎ', 3, 2, 'GOOD', SYSTIMESTAMP);
