INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '오빠가 유튜브로 유럽 빵 소개 보면서 먹고싶다고 하는데 집 근처라서 포장해가요~ 매장 분위기 짱이에요! 다음에는 데이트 하러 와봐야겠어요~', 72, 15, 'GOOD', SYSTIMESTAMP);
