INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), 'I''m Hungarian and I love this traditional Hungarian dessert but it''s quite hard to find it. So I was really surprised when I found this cafe, they have a huge selection of traditional and more experimental chimney cakes. I had the cinnamon chimney cake which was the best I had in all of Asia. The interior looks great too and I was actually surprised how cheap it all was. Highly recommended :)', 60, 18, 'GOOD', SYSTIMESTAMP);
