INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '해외에서만 먹을 수 있었던 체코 굴뚝빵이 있어서 좋았습니다. ~ 맛은 넘 눅눅한게 전혀 체코맛은 아니고 다른 빵이었어요 진열도 다 공개되어 있게 지저분해서 아쉽', 36, 10, 'BAD', SYSTIMESTAMP);
