INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '굴뚝방 궁금해서 검색해보다가 합정에 있다거 해서 후다닥 왔습니다 ! 종류도 다양하고 맛있어요~ 크기도 아담해서 여러개 먹을수 있다는 장점 ! 가격도 은근 저렴한거같아요 담에 또 오고싶어요', 33, 6, 'GOOD', SYSTIMESTAMP);
