INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '홍대 왔다 들렀어요:) 신혼여행으로 체코에서 뜨드들로 먹었던 추억에 꼭 와보고 싶었는데!! 매장 분위기도 아기자기 예쁘고 빵도, 커피도 맛있어서 완전 만족❤️ 특히, 커피를 주전자에 따로 주셔서 컵에 따라 마시니 따뜻함도 유지되고 감성 업👍🏼 근처 오시면 들러보세요:) 추천 드립니당😍', 13, 10, 'GOOD', SYSTIMESTAMP);
