INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '외관과 내부가 모두 독특하고 예뻐요. 빵 종류가 많아 고르는 맛이 있고 음료를 주전자에 내어줘서 신기하고 재밌네요. 골목이라 주차할 곳은 없으니 대중교통으로 오시길 추천드립니다 :)', 125, 24, NULL, SYSTIMESTAMP);
