INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '가족들과 놀러온김에 왔는데 크고 외국같은 분위기에 너무 좋은거같아요!! 디저트도 다양하고 직원분도 너무너무 친절하세요!! 굴뚝빵을 다양하게 먹을수있어서 너무 좋은거 같습니다 너무너무 추천해요!!', 23, 2, 'GOOD', SYSTIMESTAMP);
