INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '굴뚝빵 종류도 매우 다양하고 맛있어요! 커피도 산미없이 깔끔하고 맛있네요!! 분위기도 좋고 좌석도 꽤 있어서 좋았어요 다음에도 또 올것같아요!👍🏻', 40, 7, 'GOOD', SYSTIMESTAMP);
