INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '전부터 자주 왔었던 곳이에요! 늦게와서 빵 종류가 많지 않았지만 그래도 제가 가장 좋아하는 토마토 바질 빵이 있어서 좋았어요!! 맛에 비해 가격도 저렴해서 자주 오는 빵집이구 선물 포장용 박스가 너무 예뻐서 포장용으로도 추천해요! 너무 맛있어요!', 12, 8, 'GOOD', SYSTIMESTAMP);
