INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '굴뚝빵! 홍대에도 있는지 몰랐네요! 인테리어 겨울느낌 낭낭한게 요즘 오기 딱 좋은거같아요 ㅎㅎ 티 종류도 다양하고 빵도 다양하고 고르는데 미치는줄알았네요!', 20, 0, 'GOOD', SYSTIMESTAMP);
