INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '일요일 늦은 오후에 방문했는데 대기 없이 여유로웠어요! 주택을 활용한 카페라 분위기가 너무 좋고 굴뚝빵이라는 메뉴가 신선했어요. 빵 종류도 다양했습니다! 직원분들이 친절하셔서 기분좋게 시간 보냈어요ㅎㅎ 홍대 카페로 추천드립니다!', 19, 6, 'GOOD', SYSTIMESTAMP);
