INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '영화에 나올듯한 컨셉   각층의 분위기가 전혀다르고  재밌네요  굴뚝빵도 종류도 다양하고 커피 라떼도 다른곳과는 다르게 에스프레소 잔에 따라먹을수 있는 컨셉 좋았어요', 3, 1, 'GOOD', SYSTIMESTAMP);
