INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '오랜만에 홍대 나들이~ 다른곳과는 다른 특이한 디저트가 있어서 왔는데 맛도 좋고 매장도 예쁘고 아주 좋구용 ㅎㅎ 아이스크림도 너무 맛있고 이미 크리스마스 분위기라 설레고 좋았습니다~', 3, 6, 'GOOD', SYSTIMESTAMP);
