INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '굴뚝빵은 처음 먹어 보는데 맛도 다양하고 비주얼만큼 맛있었어요! 당고침니랑 더블피스타치오 존맛👍🏻 크림 들어간 건 다 맛있는 듯요 ㅎㅎ 아늑한 분위기 데이트하기 좋았어요💕 홍대 굴뚝빵 맛집 추천!', 85, 14, 'GOOD', SYSTIMESTAMP);
