INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '인테리어도 예쁘고 빵종류도 많아서 취향껏 골라서 맛볼수 있어 좋아용! 친구들, 연인들이랑 오기 좋은곳이예요:) 다음에도 또 방문할 것 같아요! 추천드립니당^,~', 23, 9, 'GOOD', SYSTIMESTAMP);
