INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '굴뚝빵 맛집이 있다고 해서 방문해봤어요 매장이 사진에서 보다 더 크고 예뻐서 놀랐어요 작은 동유럽에 온거 같아서 아기자기 볼거리도 많고, 굴뚝빵 처음 먹어보는데 정말 너무 맛있네요. 조만간 또 올거 같아요. 커피도 너무 맛있어요', 41, 3, 'GOOD', SYSTIMESTAMP);
