INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '홍대 이색 카페 굴뚝빵 베이커리 맛집 침니맨션! 독특한 인테리어와 굴뚝이라는 소재로 재밌는 데이트했어요. 외부도 내부도 볼거리도 많고 다양한 굴뚝빵도 맛있어요. 크리스마스 데이트 장소로 침니맨션 추천해요.', 41, 9, 'GOOD', SYSTIMESTAMP);
