INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '친구가 사고싶다고 따라 들어갔다가 비주얼보고 못참고 빵 여러개 샀어요.. 제발 홍대오시면 지나치지 말고 꼭 구매하셔야해요. 종류도 다양하고  맛은 말에 뭐해요!! 진짜 최고에요', 37, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '팔레뜨(@palette_1bee) 공연 보러왔다가 근처에 있길래 빵 샀어요ㅎㅎ 엄청 맛있어요!!!!!!🙆‍♂️🙆‍♂️🙆‍♂️🙆‍♂️👍👍👍', 45, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '침니맨션 합정역맛집이다. 인테리어 멋지다. 진짜 굴뚝모양빵의 벽돌집의 인테리어가 정말 동화속 같다. 아이스크림 맛있다. 다시오고 싶은 맛집이다', 16, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '분위기가 좋아서 와보고 싶었는데 빵 종류도 많고 맛있어보여요 근데 배불러서 못먹어서 아쉽지만 담에 또 먹으러 오려구요 카페 내부도 넓고 안에도 넘 조용해서 맘에 들어요', 4, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '체코 프라하에서 맛있게 먹었던 굴뚝빵을 한국에서도 먹을 수 있어서 행복합니다! 여기는 오리지날 빵에서 한국 사람들이 좋아하는 초콜렛, 피스타치오, 크림부터 식사빵까지 다양한 구성의 빵이 준비되어있어요. 굴뚝 컨셉의 인테리어도 흥미롭고 2층으로 가면 밖이 내려다보여서 좋습니다', 58, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '굴뚝빵 너무 맛있어요!!! 카페 분위기도 최고 ㅠㅠ 다음에 와서 굴뚝아이스크림도 먹어보고싶어요~~ 종류가 넘 많아서 고르느라 힘들었네요 ㅠ', 49, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '서교동에 이런 곳이 있다니! 🫢 인테리어도 너무 예쁘고 굴뚝빵은 처음 보는데 이색적이고 빵도 너무 맛있어요 😊 데이트 하기도 좋을 것 같아요 추천합니다 👍👍', 22, 0, 'GOOD', SYSTIMESTAMP);
