INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '빵종류가 다양하고 귀여워요 내부 분위기가 좋고 사람이 많아요 :) 사장님이 친절하시고, 음료까지 구매하시는경우에는 빵과 함께 한번에 내어주십니다. 굴뚝빵은 달콤 빵(피스타치오, 크림 등) 컨셉도 있고, 짭짤 빵 (대파크림, 베이컨 등) 컨셉도 있어서 먁어보고 싶은게 정말 다양했어요. 특히 소금과같은 단순한 굴뚝빵은 크림커피에 찍어먹어보고 싶네요 다음 방문시 먁ㅣ먹어보는걸로!', 55, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '직원분들은 친절하신데 자리가 엄청 적어요~ 그런데 사람은 많아서 빵 담을 쟁반이 없거나 집게가 없거나했어요ㅠ 겨우겨우 자리 잡았더니 버스킹예약자리라고 하더라고요ㅎㅎ 따로 공지사항 종이 붙여둔것도 아니어서 전혀 몰랐어요~ 덕분에 자리날때까지 계속 서있었어요~ 그래도 다행히 음료가 나오는데 엄청 오래걸려서 자리 다시 잡은후에 진동벨이 울리더라고요~ 맛은 그럭저럭 괜찮았지만 빵전시해둔게 위생적으로 괜찮을지싶더라고요~ 빵 담으려할때 빵위에 파리가 앉은걸 봤었거든요~ 엄청 기다려서 먹을정도는 아니니 참고하세요~ 아! 그리고 여기 화장실 버스킹할때는 못가니깐 화장실은 미리 다녀오시는게 좋아요~', 14, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '처음 보는 베이커리 종류인데 맛있어보여서 들어왔는데 매장도 예쁘고 조용조용해서 이야기하기 좋아요!! 다음에도 또 오고싶습니다!!!', 265, 94, 'GOOD', SYSTIMESTAMP);
