INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '지나가던 길에 우연히 들렸는데, 너무 이쁘고 마음에 드는 집이예요 굴뚝빵이라는 걸 파는데 안에 재료도 각기 다르고 새로운 맛이라서 너무 즐거웠습니다ㅠㅠ 다음에 이 근처오면 또 가고싶은 집이예요💕💕', 74, 14, 'GOOD', SYSTIMESTAMP);
