INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '🤎베이커리 맛집 침니맨션🤎 침니맨션 베이커리도 맛있는건 기본이고 인테리어도 깔끔하고 너무너무 예뻐요 👍 다음에 또 방문할게요~ 🫶', 25, 10, 'GOOD', SYSTIMESTAMP);
