INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '외국인 사장님이 예쁘고 친절해요!! 프라하에서 먹은 굴뚝빵이 생각났는데 너무 맛있게 잘 먹었습니다 다음에 또 방문할게요 ♡!!!', 48, 3, 'GOOD', SYSTIMESTAMP);
