INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '아이스크림빵 먹으러 일부러 찾아갔는데 하루 수량 한정이라 한개밖에 주문 못한다해 그거라도 달라며 바로 주문해 먹었는데 아이스크림빵 역시 맛나네요.  다른거 여러개 살 필요없었어요.  리뷰도 그자리에서 쓰면 굴뚝빵 한개 더 주는데 사진 정리하다 이제야 적네요.  출출할때 간단한거 먹고싶을때 가기 좋아요. 30분만에 다 먹고 일하러 갔답니다 ㅋ', 70, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '굴뚝모양의 빵을 파는데 빵이 너무 귀엽게 생겨서 저도 모르게 들어왔네요. 굴뚝 모양의 빵 위에 토핑이 되어있거나 안에 크림이나 내용물이 들어있는데 종류도 정말 다양하고 맛있어요. 가게 인테리어도 이뻐서 추천합니다👍🏻', 41, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '굴뚝빵이라는 독특한 시그니처 메뉴가 있어서 다녀왔는데, 기본 빵만 먹어도 존맛이라 베이커리 4개까지 더 포장해왔어요🥰 기본 굴뚝빵도 솔트,페퍼 등 종류가 꽤 다양했는데 사진으로 보는것 보다 크기가 커서 하나만 먹어도 든든한 기분? 같이 나오는 소스에 찍어먹어도 맛있어요! 인테리어도 감각적인데 침니맨션이라는 이름과도 찰떡같더라고요. 앤티크한데 어딘가 아기자기하고 귀여운? 우드 + 패브릭 좋아하는 분들이라면 무조건 취향저격ㅎㅎ 대형카페라 친구랑 편하게 쉬기도 좋고 맛있는 빵도 있어서 좋았습니다. 다른 빵 먹으러 또 갈게요!', 48, 0, 'GOOD', SYSTIMESTAMP);
