INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '빵순이가 처음 먹는 굴뚝빵 무지 맛있었습니다ㅠㅠ! 그런데 자리가없어서 그건 조금 불편했어요! 분위기도 좋고 음료도 완전 최고에요!', 90, 12, NULL, SYSTIMESTAMP);
