INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '체코에서 먹었던 굴뚝빵 정말 좋아하는데 홍대에도 생겼다고 해서 와봤어요:) 무엇보다 처음 건물 외관부터 벽돌건물을 잘 활용하셔 공간 자체가 고즈넉하니 예쁘고 좋았어요. 입구에 들어서면 굴뚝빵이 종류별로 촤라라 있어서 눈을 사로잡아요! 2층과 테라스더 2군데 있고 건물 구석구석에 소소하게 컨셉이 확실한 포인트들이 있어 귀여웠어요. 카페 안에 있는 굴뚝빵과 아이스크림 올라간 건 따로더라구요! 아이스크림 올라간 건 즉석에서 구운 후 아이스크림을 넣어주고 만들어진 빵은 진열되어 있고 두께도 좀 두꺼운 것 같아요. 좀 더 체코의 맛을 느끼고 싶으시면 아이스크림 올라간 것을 시키시는 게 어떨까 싶습니다. 피넛으로 먹었는데 진한 초코맛이 인상적이었어요! 재방문 의사 있습니다:)', 47, 2, 'GOOD', SYSTIMESTAMP);
