INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '굴뚝빵 먹고싶어서 온 침니맨션🩷 빵이 되게 신기하게 생겼고, 너무 부드러워용ㅠㅠ🤭 아이스크림도 같이 먹고 싶어서 시켰는데, 후추맛과 아이스크림이 잘 어울려서 또 먹고 싶네용🤍 분위기도 엔틱하게 너무 귀엽더라구요 다들 꼭 한번 와보세용ㅎㅎ', 17, 9, 'GOOD', SYSTIMESTAMP);
