INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '방문하였는데 길가다가 우연히 들어갔는데도 분위기나 모든면에서 사람을 끌리게 해서 좋았습니다! 분위기도 좋고 빵은 누구 선물하기도 좋은 비쥬얼입니다 ! 아이스크림까지 주문하면 그저 완벽합니다🫶🏻', 15, 2, 'GOOD', SYSTIMESTAMP);
