INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '음악도 은은하게 좋고 아직 맛은보지 못했지만 딱 봐도 맛있게 보여요~ 포장도 정갈하게 해주시고 굿입니다 아내가 꼭 사오라고 해서 사갑니다 맛이 기대되네요~!!', 33, 3, 'GOOD', SYSTIMESTAMP);
