INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '체코에서 먹던 굴뚝빵이 그리워서 찾아왔는데 쫄깃하고 부드러운 식감을 재현해주셔서 넘 맛있었어요~~ㅎㅎㅎ 굴뚝을 살린 인테리어도 너무 예뻤습니댜!!', 78, 13, 'GOOD', SYSTIMESTAMP);
