INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '와 여기 지나가다가 우연히 들린 건데 진짜 빵 다 너무 예쁘고 맛있게 생겨서 뭐 먹을지 한참을 고민했습니다 추천 추천 너무 추천합다', 34, 8, 'GOOD', SYSTIMESTAMP);
