INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '카페 분위기도 너무 좋고 사장님도 친절한데 굴뚝빵도 너무 맛있어요!! 굴뚝빵 너무 먹고싶어서 찾아간곳인데 실망없이 맛있게 잘 먹었습니다! 음료도 정말 맛잇엇어요!!!', 50, 3, 'GOOD', SYSTIMESTAMP);
