INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '체코에서 먹었던 걸 여기서도 먹을 수 있어요! 한국에서 굴뚝빵제일 잘 하지않을까 싶움 커피도 신맛 안나고 디카페인도 있어서 카페인 안좋아하는 분들도 부담없이 드실 수 있습니다!', 7, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '미국 친구네 집에 온 것 같은 외관 비주얼... 카페가 귀여워요! 시그니처 빵 모양도 신기한데 맛도 이써요. 다음에 또 오고 싶은 곳!', 83, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '동유럽 신혼여행에서 굴뚝빵을 먹으면서 이거 우리나라에 들어오면 좋겠다고 생각했는데 이렇게 제대로 하는 곳이 생겨서 너무 반갑고 신나네요. 기본빵부터 응용된 굴뚝빵까지 어느하나 맛이 없는게 없네요. 거기다가 인테리어도 감각적이고 좋더라구요. 너무너무 좋아요!', 35, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '와 빵순이 여러분 주목해 주세요! 홍대에 새로생긴 신상카페가 있어서 방문해 봤어요. 카페 들어가자마자 맛있는 냄새가 솔솔 코를 강타해요 ㅋㅋ 체코 여행중에 먹었던 굴뚝빵을 한국에서도 먹을 수 있어요. 카페 컨셉도 너무 귀엽고 아기자기해요. 글래서 카메라를 멈출수 없었어요. 빵도 쫀득하고 너무 맛있고 빵 종류가 많아서 고르는 재미도 있어요😍커피도 진하고 고소해서 빵이랑 같이 먹기에 좋아요. 저는 개인적으로 에그에그랑 더티 빵이 맛있었어요 ㅎ홍대 합정역에서 디저트 카페 찾으신다면 침니맨션 추천해요!👍', 98, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '요약: 주인장의 상상력 + 사업 감각에 박수를. 보통 <코로네>로 불리는 샤움롤레(소라빵)에 다양한 필링이나 토핑을 더한 메뉴들을 판매. 사실 이렇게 많은 종류가 가능할 줄 몰랐는데, 동일한 베이스를 사용하여 원가를 절감하면서도 요기(미트치즈볼, 루꼴라잠봉 등)와 디저트(침니당고, 커스터드, 아이스크림 등)가 모두 가능하게 만든 주인장의 아이디어에 무릎을 치고 감. 여러가지 시켜서 나눠 먹을 수 있도록 작은 가위를 함께 주는 센스까지. 가격은 개당 5-7천원 사이로, 천 원 정도 낮으면 좋겠지만 이해 가능. 개인적인 베스트는 나이스투미투(5200). 드링크는 피스타치오라떼(7000) 강추. 매장이 깔끔하게 잘 관리되어 있고, 좌석도 의자, 소파, 패티오 등으로 다양하며, 포토스팟도 제법 많음.', 44, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '인테리어가 예쁘고 디저트가 맛있어보이길래 합정역 카페로 방문했던곳이였어요☺️ 직원분들의 서비스는 좋은편이였고 빵들이 전체적으로 맛있어서 만족했어요👍 금액대도 괜찮고 포장도 예뻐서 선물로도 좋은거같아요 합정역 디저트 카페 찾으시면 추천드리고싶어요', 16, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '합정에서 만난 체코~♡ 체코를 가본적 없지만. 뭔가 유럽분위기 물씬이에요 ~~~~~~뷰도좋고. 합정역에서 가까운편이구요^^힐링하기좋은 쾌적한 카페에요 굴뚝빵 첨 먹어봤는데 진짜맛잇고 커피도맛있고 인테리어가 1.2층모두 이쁘네요♡♡ 지인들에게 모두 사진보냇는데 다들 이뿌다고난리 ♡♡번창하세요~~!', 48, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '굴뚝빵맛집😋 침니맨션😍 다들 굴뚝빵 드셔보셨어요??! 안드셔보셨으면 여기 필수방문입니다‼️ 저는 굴뚝빵 보기만했지 먹어보진 못했는데 침니맨션에서 먹어보니...나 굴뚝빵 좋아하네⁉️🤗 기본 굴뚝빵 주문하면 바로 반죽 돌돌돌돌 말아서 따끈따끈한 굴뚝빵이 나와요🔥🔥🔥 베이비피스타 - 피스타치오와 화이트초코의 만남😍 토마토바질필드 - 토마토바질 좋아하시면 바로 픽😋 솔티드캐러맬 - 달달구리 맛있게 먹었어용ㅎㅎ 레이디피치 - 얼그레이 좋아하시면 바로 픽🤗 빵이 부드러우면서 쫄깃하고 퐁신하고 너무 맛있었어용😄 침니맨션 체고🔥', 65, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '빵이 너무 귀여워요!! 굴뚝 모양의 빵들이 다양한 맛으로 있어서 고르는 재미가 있어요!! 다 먹고 싶은데 또 와야겠어요! 인테리어도 외국 느낌나고 좋아요', 21, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '굴뚝빵 전문 카페길래 방문했는데 커피 맛 좋네요. 아메리카노 한잔에 4500원이면 가성비 좋은데 아메랑 디카페인아메랑 다 맛이 좋아서 놀랬어요. 굴뚝빵도 따뜻하게 먹었으면 더 맛있었을것 같긴한데 쫄깃하니 맛있게 잘 먹었습니다. + 리뷰쓰면 주시는 굴뚝빵은 데워달라해서 따뜩하게 먹었는데 아쥬 맛있네요. 꼭 데워달라고 하세요! 재방문의사있습니다 소금추천 근본은 역시 오리지날', 75, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '침니맨션'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '굴뚝빵 먹고 싶어서 서교동 다녀왔어요. 굴뚝빵 종류도 다양하고 인테리어 감성적이고 분위기있어 데이트장소로 연인, 지인들과 함께와서 먹기에도 딱이더라고요. 빵 4종류 골라서 주니 한박스에 이쁘게 담아서 주셨어요. 선물하기에도 딱이었어요.', 26, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '친구에게 소개시켜주려고 홍대카페에 왔습니다. 건물에 붙어있던 대형 플랑카드가 없어지고 앞이 공사 중입니다. 8층에 내려 입구로 들어가는데 친구의 입에서 감탄사가 나오기 시작했습니다. 오잉~~??? 구조가 조금 바뀌었네요. 커피를 마시며...친구는 커피가 맛있다고 칭찬에 칭찬을.. 커피를 마시며 수다를 떨고 돌아가기 전 전층구경을 위해 루프탑으로 갔습니다. 여기서 부터 친구는 정신을 잃는 듯 감탄에 감탄을... 머....이 정도로...ㅋㅋㅋ 한 층 한 층 내려가며 사진을 찍는데 순간 친구는 나 사진 찍어줘...합니다. 조금 멀리서 온 친구는 홍대입구역 몇번 출구인가 확인하며 조만간 가족들이랑 같이 올 의지를 불 태웁니다. 친구에게 좋은 카페를 소개할 수 있는 자신이 뿌듯해지는 하루입니다.', 146, 31, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '진짜 공간말도안되게 이쁘고 멋지고 아름다워요❤️❤️❤️ 층마다 콘셉트도확실하고 진짜 최고에요!!! 모든층이 진짜 다 너무 좋아요. 탁트인 루프탑에서 석양이랑 야경도 보고싶어요. 디저트도 맛있고 음료도 맛나고. 진짜 넘넘 좋았어요☺️☺️☺️☺️☺️😍😍😍', 1, 3, 'GOOD', SYSTIMESTAMP);
