INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '친구가 홍대에 대형카페가 있다고,,, 건물 하나가 통 카페 각층마다 다른 컨셉으로 ^^ 커피한잔으로 오르락 내리락 ㅎㅎ 갠적으론 1️⃣K-pop미디어2️⃣LP뮤직,3️⃣갤러리4️⃣자연조경,등등 다,,,,괜찮음^^ 식물관도 좋은데 앉을 곳은 마땅치 않음^^ (신선한 공기와 초록의 향연을 눈과 코로 즐기면 될듯,,, 특히 선인장 🌵 🏜 의 다양함이 돋보임^^) 다양한 테마를 경험하는 것에 비함,,,,가격대는 비싼게 아닌듯 다만,,,홍대카페를 치면 홍대에 있는 여러 카페들이 줄지어 나와서리 명칭이 쫌,,,,,그나마 ㅎㄷ카페로 쳐야 그나마^^ 8층에서 주문하고 각층을 돌아보는 재미가 쏠쏠함 🥰😍🤩😘😎💯✌️🫰👍키워드가 5개만 되는게 안타까움 더 주고 싶어도 아니됨~~ㅎ', 55, 13, 'GOOD', SYSTIMESTAMP);
