INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '여기 완전 대박인곳이에요 커피한잔 값으로 카페 전층을 누릴수 있어요 8층에서 주문한후  본인이 맘에 드는 곳에서 편안하게 즐길수 있어요 루프탑은 낮보다는 해진후가 더 멋있을거같긴 하지만, 낮에도 한강까지 보여서 좋아요.더워도 잠깐이라도 꼭 올라가보세요 이곳은 층마다  다른 컨셉이라 돌아다니연서 구경하는 재미도 있어요. 8층은 주문..대나무와 조명..중앙의 대리석이 묘하게 조화로운 공간 7층은 k-pop media공간으로 뮤직비디오를 감상 6층은LP 뮤직감상과, 단체석들이 많아서 공부하기에도 좋을거같아요 5층은 gallery 차한잔으로 갤러리 작품을 감상할수 있다니.. 4층은 스톤밸리. 한쪽 벽먼에서는 바다의 파도영상+ 평상 3층 plant 작은 식물원 음료는 중간 맛정도~ 꼭 모든층 다 돌아보세요', 65, 16, 'GOOD', SYSTIMESTAMP);
