INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '최근 홍대에서 친구와 데이트하다가 우연히 방문한 ㅎㄷ카페, 정말 깜짝 놀랐어요! 9개 층을 모두 카페로 쓰고 있다니, 서울 최대 규모라는 말이 실감 나더라고요. 층마다 인테리어 컨셉이 달라서 마치 다른 카페 여러 곳을 방문하는 기분이었어요. 넓고 좌석이 정말 많아서 주말 오후에 방문했는데도 편하게 앉을 자리가 있었고, 테이블 간 간격도 넓어 쾌적하게 대화 나눌 수 있었습니다. 주문한 디저트도 최고였어요. 만다린 초코 케이크와 치즈 케이크를 시켰는데, 비주얼부터 너무 예뻐서 먹기 아까울 정도였어요. 맛은 말할 것도 없이 훌륭했답니다. 특히, 파나마 게이샤 커피를 마셨는데, 향이 정말 남다르더라고요. 부드러우면서도 풍부한 맛이 입안에 오래 남아서 감탄했어요. 괜히 커피가 맛있는 집으로 소문난 게 아니네요.', 13, 5, 'GOOD', SYSTIMESTAMP);
