INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '9층건물 중 2층 공사중(?) 제외한 전층 각 층별로 테마가 다르게 꾸며져있는 대형카페예요. 자리를 많이 띄어앉을 수 있는점도 좋아요 식물원같이 꾸며진 곳은 완전 프라이빗하게 앉을수도ᆢ 비 안 오는 날은 9층 루프탑으로 나가서 야외테라스기분도 낼 수 있어요. 케잌도 맛있고, 음료도 맛있어요.', 72, 18, 'GOOD', SYSTIMESTAMP);
