INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '복합문화공간 같은 대형카페인데, 특히 9층 루프탑 뷰 맛집이네요. 여의도 파크원타워에서 국회의사당까지 보이니 9월27일 불꽃축제도 여기서 구경하면 대박일듯요~♡♡♡ 9층까지 있는데, 층마다 컨셉이 달라서 맘에 드는 곳 골라서 커피마시고 쉬다가, 9층에서 인생샷 찍고 가면 딱 좋아요. 6층 lp뮤직,  음질 정말 좋습니다~ 다음에 혼자 올 때는 LP 뮤직층에 있을 거예요.', 123, 25, 'GOOD', SYSTIMESTAMP);
