INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '몇 주 만에 카페 제대로 즐겼는디 덕분에 넘 행복해지는 기분🥹 인테리어며 분위기며… 진짜 미쳤어요‼️ 포토존, 음악, 공간감까지 완벽✨ 홍대 감성+핫플 무드 다 잡은 곳👏 음료랑 디저트 맛도 깔끔 그 자체라서 한 입 먹을 때마다 기분 좋아져요🤍 무엇보다 층마다 분위기랑 컨셉이 달라서 구경하는 재미가 쏠쏠하고, 대형카페라 자리도 넉넉해서 편하게 오래 머물 수 있어요. 홍대에서 오래 앉아있을 카페 찾을 때도, 잠깐 시간 때우기에도 딱인 곳이라 홍대 올때마다 찾을듯ㅜㅠㅜ', 42, 1, 'GOOD', SYSTIMESTAMP);
