INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '막내와 홍대 빈티지투어 갔다가 커피마시러 들렀어요. 입구에서 바로 엘베타고 8층으로 올라가 주문하시고 픽업하여 원하시는 층으로 이동하시면 됩니다. 층마다 특색이 있어 구경하는 재미도 있네요. 오늘 날씨가 덥지않고 살짝 흐려서 루프탑도 분위기 있고 좋았어요. 화장실도 층마다 청결하게 관리 잘 되어 있고 좋네요.', 0, 8, 'GOOD', SYSTIMESTAMP);
