INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '왜 복합문화공간이라고 하는지 알겠는 공간 너무 예쁘게 잘 꾸며놨고, 대형카페 답지않게 디저트와 음료들도 너무 맛있다 홍대쪽 위치도 너무 좋고 층별로 홀도 커서 사람들이 아무리 많아도 북적이지 않을 것 같아 답답한 느낌이 없을 듯 하다 층층마다 컨셉이 달라서 매력적인 공간', 65, 12, 'GOOD', SYSTIMESTAMP);
