INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '홍대에 이런 대형카페가 있다니! 놀이공원 카페 온것처럼 신나게 층별 테마 감상하며 즐기고 왔습니다. 낮에는  아직 더워서 파란 하늘과 도심뷰 보고 왔는데 저녁에 홍대카페 루프탑에 가서 아경보고 오면 너무 좋을 것 같아요ㅎㅎ 음료와 디저트도 다 맛있었어요~', 43, 10, 'GOOD', SYSTIMESTAMP);
