INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '홍대 데이트하기 좋은 카페 홍대 카페에 다녀왔어요. 루프탑을 포함해 9개층을 모두 사용하는 홍대 대형 카페로 각 층마다 다른 컨셉의 인테리어를 구경하면서 시원하게 시간 보내기 좋은 홍대 카페였습니다.', 64, 13, 'GOOD', SYSTIMESTAMP);
