INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '홍대 루프탑 카페로 ㅎㄷ카페가 유명하다고 해서 점심시간에 직장동료들과 다녀왔어요. 층마다 테마가 있어서 구경하는 재미가 있었구요. 무엇보다 루프탑이 높은 건물에 있어서 탁트인 홍대뷰가 멋있었어요. 퇴근길에 지나다니며 보던 카페인데..낮보다 밤이 더 좋은걸 같아서 조만간 재방문 예정^^', 4, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
