INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '다양한 컨셉의 홍대 카페. 건물 전체가 카페라고 해서 예전부터 눈여겨봤던 곳이에요. 건물 외벽 미디어월도 멋져서 이 근처 자주 와보신 분들은 다 아실거예요. 각 층마다 다른 컨셉별로 공간이 꾸며져 있어서 원하는 컨셉의 공간에서 커피와 디저트를 즐길 수 있어요. 층마다 미디어월, 엘피 듣는 곳, 케이팝 영상 볼 수 있는 곳 등, 홍대 일대가 보이는 루프탑 외에도 볼거리가 많아요. 음료와 디저트도 다양하구요! 홍대에서 새로운 시각적 경험과 힐링 필요하신 분들께 추천해요!!! 자리 간격이 널찍해서 대화나누기도 넘 좋아요!', 23, 8, 'GOOD', SYSTIMESTAMP);
