INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '홍대 거리에 가장 쾌적하고 큰 이색카페에요🤍 8층짜리 큰 건물에 층마다 다른 컨셉의 공간이 마련되어있어 너무 좋았어요 서촌의 새련된 LP바, 아트적인 갤러리, 제주도의 청량함, 식물원에 온듯한 착각을 주는 푸릇함, 서울 시내 뷰가 한 눈에 보이는 테라스 등 한 카페에서 다양한 컨셉을 느끼기 좋았어요ㅜ 파마나게이샤라는 고급원두를 보유한 카페는 첨봤네요 디저트, 커피 품질과 맛이 훌륭해요 재방문의사 1000%😻😻', 47, 5, 'GOOD', SYSTIMESTAMP);
