INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '홍대에 있는 ㅎㄷ카페 다녀왔어요. 층마다 다양한 컨셉의 공간이 있어 사진 찍기도 좋고 구경하기에도 너무 좋았어요. K-pop media 존도 있어서 그런지 외국인 손님들도 많더라구요. 음료랑 디저트도 정말 맛있었어요 ㅎㅎ 홍대 대형카페로 홍대카페 추천합니다~~', 127, 20, 'GOOD', SYSTIMESTAMP);
