INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '건물 하나가 통째로 카페에요 8층에서 커피한잔 사면 맘에드는 컨셉의 공간에 앉아서 드시면되요 갤러리, 미디어 파사드, K-pop rounge 거기에 LP rounge까지... 저희는 6층 LP라운지에 자리잡고 앉아서 음악 골라듣다 왔어요 아쉬운건 수천만원짜리 오디오 시스템에 아이패드에서 나오는 음원으로 듣다왔다는거에요 그래도 뭐 내맘대로 선곡해서 빵빵한 사운드로 음악을 들으니 속이 뻥뚫리더라구요 비가와서 루프탑은 개방을 안했는데 가을되면 날좋을때 다시 가봐야겠어요', 78, 13, 'GOOD', SYSTIMESTAMP);
