INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '🌵넓고 쾌적한 홍대 카페! 지하부터 루프탑까지 한 건물이 카페로 이루어진 공간! 공간이 넓고 층마다 컨셉을 다르게 구성한 점이 독특했어요. k-pop 존은 사방이 스크린이라 아이돌이나 연예인들의 생일카페 대관으로도 좋을 것 같아요. 선인장 측은 조경이 예뻐 인증샷 남기기 좋고, 루프탑은 여의도까지 훤히 보여 초여름 혹은 가을 날 좋을 때 노상카페, 루프탑바 찾는 분들한테 딱! 일 것 같아요.', 20, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'INDUSTRIAL');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '매번 홍대 지나갈 때마다 가봐야지 가봐야지 했다가 방문했는데 정말 ... 테마파크 같은 곳. 층 마다 컨셉 다 다르고 이 넓고 큰 매장을 관리한다는게 진짜 대단한 것 같아요... 깨끗하고 테마 마다 취향따라 선택할 수 있고 음료 디저트 훌륭하고 에어컨 빵빵하고.... 진짜 너무너무 추천하고싶어요.... 홍대에서 쉴만한 카페 찾을 때도 자리가 너무 널널해서 뭐 더 둘러볼 것 도 없이 홍대카페 가자 할 것 같은 최고의 카페... 이정도 대형카페가 있는다는게 놀라워요', 50, 10, 'GOOD', SYSTIMESTAMP);
