INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '산미있는 커피를 좋아하는데 제 취향에 맞네요. 흘러나오는 음악의 바이브가 좋아요.🤩 층별로 각각 다양한 테마와 kpop 뮤직비디오로 덮여진 빈백룸, 루프탑뷰까지... 홍대에 이런 대형카페가 있었다니 놀랍습니다. 나중에 외국인친구와 오면 꼭 데려와야겠어요 ㅎㅎ🩷', 86, 18, 'GOOD', SYSTIMESTAMP);
