INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '층마다 다른 인테리어, 디저트 ,커피까지 너무 맛있네요 8층 그리고 루프탑까지  층마다 다른 인테리어 구경하느라 시간가는줄 몰랐어요 케이크도 맛있어서 디저트도 추천 루프탑 노을질때 추천해요👍🏻👍🏻👍🏻', 48, 10, 'GOOD', SYSTIMESTAMP);
