INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '매장 층마다 테마가 있어 구경하는 재미가 있어요 층층이 사람이 분산되어 북적이지 않아서 너무 좋습니다 맨 위층 루프탑 너무 뜨거워 3초 보고 바로 내려왔는데 날 선선해지면 거기도 경치가 엄청 좋을것같아요~~ 음료도 맛있고 볼거리가득이라 너무 좋네요', 12, 7, 'GOOD', SYSTIMESTAMP);
