INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '홍대에 이런 대형카페가 있다니! 넓고 좌석도 많아 쾌적하더라구요~ 우연히 지나가다가 알게되었어요. 건물 전체가 카페인데 층마다 테마가 달라서 내 취향대로 고르기 좋더라구요 :) 거기다 커피맛도 너무 좋았는데 디저트도 다양해서 고르기도좋고 맛도 좋았어요! 카페도 넘 예뻐서 홍대의 랜드마크가 될것같아요!', 110, 20, 'GOOD', SYSTIMESTAMP);
