INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '홍대에 이런 카페가 있다니!🫢 엄청난 규모의 카페인데 각 층마다 컨셉이 있어서 원하는 스팟가서 쉬기 너무 좋았어요 ㅎㅎ 음료와 케이크도 너무 맛있고 뷰가 정말 좋고 매장이 청결해서 혼자, 친구, 데이트까지 완전 딱이에요! 해피아워 시간에 루프탑에서 해가 지는 거 보니까 정말 좋았습니다 ㅎㅎ 재방문 하고 싶은 대형 카페!!', 34, 0, 'GOOD', SYSTIMESTAMP);
