INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '홍대카페 중에서 가장 마음에 들었던 초 대형카페 ! 너무 좋아요 ^^ 층마다 컨셉이 정말 좋았구요, 넓은 카페에서 커피와 디저트타임으로 힐링하고가요^^ 야외 루프탑도 가봤는데 홍대시내가 한눈에 아주 잘보이고 탁 트인 시티뷰가 좋았어요 ! 깔끔하고, 인테리어도 세련되고 커피도 맛있어요 💖', 8, 8, 'GOOD', SYSTIMESTAMP);
