INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '각 층마다 다른 컨셉의 카페라 구경하는 재미가 있는 카페예요. 전시회에 방문한 느낌도 들고 식물원이나 호텔라운지에 방문한 느낌도 들어서 홍대 가볼만한 곳으로 추천해요. 매번 동일한 패턴의 만남이 지겹다면 추천', 54, 18, 'GOOD', SYSTIMESTAMP);
