INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '홍대에 있는 대형카페, 층마다 특색있는 컨셉이 즐거운 복합문화 공간인 카페네요! 주문한 커피와 음료, 디저트도 맛있는 카페예요♡ 친구와 머물면서 편하고 즐거운시간 보내다왔어요^^ 홍대가면 카페에 안가볼 이유가 없는곳이네요', 14, 5, 'GOOD', SYSTIMESTAMP);
