INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '홍대에 이렇게 멋진카페가 있다니!! 8층까지 있는 거대하고 웅장한 카페 안에 층마다 다른컨셉으로 즐길 수 있는게 너무 좋네오! 만다린 케이크 맛있으니까 드셔보세요! 커피 한 잔 마시면서 공간을 즐기기도 너무 좋은데 홍대카페는 루프탑이 진짜 멋있답니다!! 날씨만 선선해지면 서울 아래가 보이는 루프탑에서 커피 한 잔 마시고 싶네오!!', 86, 17, 'GOOD', SYSTIMESTAMP);
