INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '서울 도심 내 이렇게 큰 카페가 있다니 신기하네요. 자리 걱정 할 필요 없을 정도로 넓고, 관리 잘되고 깨끗했습니다. 루프탑 뷰도 예술이에요', 50, 2, 'GOOD', SYSTIMESTAMP);
