INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '매장도 엄청 넓고 깔끔하니 이뻐요🩵 커피랑 디저트는 당연 맛있고 무엇보다 공간이 널널해서 단체로 이용하기도 넘 좋습니당 층마다 구경하는 재미가 있어서 중간중간 식물관이나 갤러리, k팝 같은 볼거리들도 많은 복합문화공간이라 방문하기 넘 좋았어요!!👍', 18, 5, 'GOOD', SYSTIMESTAMP);
