INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '오늘 주문한 메뉴는 아이스 아메리카노, 바닐라라떼, 그리고 과일(귤,체리)이 올라간 초코 케이크였어요. 아메리카노는 잡맛 없이 깔끔하고 깊은 원두향이 살아있어서 만족! 바닐라라떼는 부드러운 우유와 에스프레소 밸런스가 좋아서 첫 모금부터 고소함이 느껴졌어요. 케이크는 진한 초콜릿 시트에 상큼한 귤과 체리가 올라가 달콤·새콤한 조화가 아주 좋았어요🍊🍒 그리고 8층 한쪽 벽에는 다양한 원두 패키지와 감각적인 조명이 진열돼 있어서, 커피를 마시면서 구경하는 재미도 있었어요.', 34, 9, 'GOOD', SYSTIMESTAMP);
