INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), 'ㅎㄷ카페는 홍대에서 정말 큰 카페에요 공연장부터 루프탑까지 정말 다양한 즐길거리가 있더라구요 코코넛라떼도 맛있었어요 그리고 소금빵도 팔고 케이크도 종류가 다양해서 선택지가 넓더라구요 자리도 넓고 카페도 분위기있고 디저트랑 음료도 굿굿!👍👍', 34, 4, 'GOOD', SYSTIMESTAMP);
