INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '정말 눈 돌아가는 서울대형카페 홍대카페!! 케이팝 좋아하시는 분들 뿐만아니라 각 층마다 다양한 컨셉으로 꾸며진 공간들이 모두에게 만족스러울만한 넓은 카페예요 커피와 케이크, 메론소금빵도 맛있었어요 서울에 이런 대형카페가 있다는 사실이 놀라울 따름이에요 친구들과 주변에 많이많이 소개할거에요!!', 13, 0, 'GOOD', SYSTIMESTAMP);
