INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '갤러리처럼 인테리어가 정말 멋져요! 층마다 컨셉에 맞게 구성되어 있고 1층부터 8층까지 모두 이용 가능해요!! 8층에서 주문해서 원하는 층에서 먹을 수 있어요!! 저는 개인적으로 4층에 stone valley가 제일 마음에 들었어요!! 디저트랑 음료 종류도 다양했어요!! 소금빵부터 에그타르트, 케이크까지 디저트도 완벽!! 생크림 소금빵은 단짠 조합이 정말 잘 어울렸어요!! 음료는 코코넛라떼랑 베리아이스티 먹었는데 달달하고 너무 좋아요!! 대형카페 중 제일 화려하고 분위기가 좋은 것 같아요!!', 19, 4, 'GOOD', SYSTIMESTAMP);
