INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '루프탑 사진만 보고 방문했는데 여기는 상상 그이상으로 더 대박이었어요!! 음료 디저트 전부 다 맛있고, 전층이 각각 다른 컨셉으로 되어있어서 심심할틈이 없어요!! 새로운 공간에 여행온 기분🥹 20대 초반이후로 오랜만에 홍대와서 너무 재밌었네요! 진짜진짜 추천합니다!!', 46, 10, 'GOOD', SYSTIMESTAMP);
