INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '단순히 이야기만 나누는 카페가 아니라 층마다 다양한 컨셉을 즐기며 눈과 귀가 모두 즐거운 곳이였어요. 물론 맛있는 디저트.커피로 입도 즐거웠답니다ㅎㅎ 더운 여름에 밖에 나가기 힘든 요즘, 오랜만에 어머니와 즐겁게 실내 데이트하고 가요!', 8, 3, 'GOOD', SYSTIMESTAMP);
