INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '홍대에 위치한 대형카페 ㅎㄷ카페 다녀왔어요! 총 9개층으로 구성되어 있고, 각 층마다 테마가 달라서 구경하는 재미가 쏠쏠했어요. 저는 8층에서 아메리카노, 리치 아이스티와 함께 체리가나슈 케이크, 팥말차 다쿠아즈를 주문했는데, 디저트 퀄리티도 좋고 맛있었어요! 체리는 새콤하고 초코는 진하고, 말차는 향이 아주 진해서 만족도 높았어요. 공간도 넓고 깔끔해서 데이트나 혼카페로 추천해요. 사진 찍기 좋은 스팟이 너무 많아서 시간 가는 줄 몰랐답니다 :)', 41, 5, 'GOOD', SYSTIMESTAMP);
