INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '독특한 컨셉의 홍대 대형 카페 홍대카페 각 층마다 다 다른 컨셉으로 내 취향에 맞는 공간에 찾아가 맛있는 커피와 디저트를 즐길 수 있다는 게 엄청 매력적이었습니다. 20대 여성들이 좋아할 분위기와 음악도 흘러나오고요. 좋은 경험 잘 즐겼습니다 ㅎㅎ', 74, 17, 'GOOD', SYSTIMESTAMP);
