INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '홍대에서 핫한 대형카페인 “홍대카페”에 다녀왔어요. 8층에서 음료를 주문하고 모든 층에서 어디든 방문할수있어요. 각 층마다 테마가 다르구요. 노을이 지는 루프탑에 올라가보고 싶은데 오늘은 더워서 못간게 아쉬워요. 이곳은 파나마게이샤 커피도 있었어요. 가격은 두배였지만 고급원두가 있어서 좋았어요. 기본 아이스커피 마셨는데 그것도 맛있었어요.', 25, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '진짜 도심 한복판에 층마다 테마가 다르고 대형카페 건물이 있어요~!! 여기 진짜 컨셉도 👍 음료와 디저트 어느것 하나 빠지는거 없이 완벽한 곳이에요♡ 진짜 데이트 코스 추천합니다♡대형 매장 관리하기 힘든데 청결하고 직원분들 너무 친절해요♡', 56, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), 'ㅎㄷ카페 너무 궁금했는데 제 기대 이상으로 카페가 넓고 분위기가 미쳤네요!!! 층마다 컨셉이 달라서 구경하는 재미가 있고, 사진도 이쁘게 나왔어요:) 너무 더워서 루프탑에서 못 먹었지만 노을 보기 최고의 장소일 것 같네요. 커피가 맛있었고, 쑥 다쿠아즈 추천합니다!! Kpop존은 빈백에 누워서 삼면이 스크린인 곳에서 편하게 쉴 수 있는데요, 그게 너무 좋았어요!! 또 가고 싶네요!', 0, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '9층으로 이루어진 복합문화공간 카페로 색다르고 신기한 카페였어요😆 특히 케이크가 정말 맛있었고 각 공간들이 모두 특색있어서 구경하는 맛이 있었어요 ㅎㅎ 커피 애호가들 사이애서 유명한 파나마게이샤 원두가 있어요! ㅎㄷ 카페 이름도 특이하네용 ㅎㅎ', 4, 10, 'GOOD', SYSTIMESTAMP);
