INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '엄마랑 데이트하려고 열심히 알아본카페인데 너무좋아하셔서 좋았어요! 루프탑뷰가 미쳐서 동영상도 찍어봤어요! ㅋㅋㅋ꼭 다녀와보시길 추천드립니다', 78, 13, 'GOOD', SYSTIMESTAMP);
