INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '건물 전체가 카페라 아주 넓고 쾌적해요ㅎㅎ 층마다 특색있게 꾸며 놓으셔서 재밌게 놀았습니다~~ 케이크도 아주 맛있어요!! 저는 치즈케이크 추천', 290, 80, 'GOOD', SYSTIMESTAMP);
