INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '레몬요거트다쿠아즈랑 얼그레이쉬폰케이크 맛있어요 디카페인 아아는 산미있고 맛있대요 레드리치 아이스티는 달달해서 정신깨기 좋아요 내부 넓고 공간감좋아요 큰건물이라 여기저기 구경하면 좋아요', 49, 8, 'GOOD', SYSTIMESTAMP);
