INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '너무 맛있어요~ 음료수 종류도 독특했고 케이크도 맛없없 조합만 있었어요. 음료는 레드 리치 아이스티가 제일 맛있었구요~ 카페에 넓은 자리가 많은데 공간도 꽤 많아서 널널하게 앉았습니다. 좋았어요! 케이크 맛집이었어요ㅎㅎㅎ', 122, 25, 'GOOD', SYSTIMESTAMP);
