INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '에그타르트랑 초코가나슈 케이크 둘 다 넘 맛있고, 카페가 대형카페인데 층마다 컨셉이 달라서 넘 예뻤어요!! 식물관도 예뻤는데 계곡처럼 물 흐르는 소리에다가 평상 컨셉으로 의자있는게 완전 신기하고 센스 만점,,,', 1, 5, 'GOOD', SYSTIMESTAMP);
