INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '포토스팟이 많다고 해서 왔는데 층마다 분위기도 다르고 예뻐서 시간보내기 좋습니다^-^ 커피도 맛있고 메뉴도 다양해서 괜찮네요! 다음에 또 오고싶은 곳입니다:)', 101, 21, 'GOOD', SYSTIMESTAMP);
