INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '층마다 컨셉이 확실했고 다양한 볼거리가 있어서 좋았습니다!! 팥치즈케이크는 꼭 추천드리고 싶어요!! ㅎㅎ 갬성 사진 찍고 싶으신 분들 친구랑 와보세요! 가을에도 꼭 오고싶어요 루프탑 갬성 느껴보고 싶습니다 ㅎㅎㅎ원두 종류도 쉽게 접할 수 없는 것이라 더욱 좋았구요 ㅎㅎ', 7, 1, 'GOOD', SYSTIMESTAMP);
