INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '대형카페라 그런지 너무 매력적인 인테리어라 사진을 안 찍을 수 없는거 있죠 비가 오는날이라 루프탑이용을 못해서 아쉽지만 층층마다 다양한 컨셉으로 되어있어 사진찍는 재미가 있어요 음료랑 디저트도 너무너무 맛있어서 또오고 싶어요^^', 90, 12, 'GOOD', SYSTIMESTAMP);
