INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '8층이나 되는 대형카페인데 층별로 테마가 달라서 한번에 여러 카페를 방문한 것 같은 느낌이었어요 ㅎㅎㅎ 요즘같이 더운 날씨에 실내에서 알차게 놀 수 있는 카페라 강추합니다', 58, 12, 'GOOD', SYSTIMESTAMP);
