INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '디저트 + 감성 + 인스타 포토존 + 눈 호강 인테리어 이 조합, 세상에 또 없어요! 🌟 진짜 8층 전체가 커피도 사먹고 카페라니 혜자 아닌가요?ㅎㅎㅎ 특별히 얼그레이 케이크, 이건 그냥 ''인생 디저트 등극''이에요! 소중한 사람 데리고 가서 같이 감동하셔야 해요ㅠㅠ 카페 갈 계획인 분들! 얼그레이 케이크는 꼭 먹고, 루프탑에서 커피 마시면서 사진도 잔뜩 찍으시길~ 전 무조건 또 갈 거예요! 담엔 커피까지 제대로 음미하러!!!!', 45, 4, 'GOOD', SYSTIMESTAMP);
