INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '층마다 컨셉이 확실한 ㅎㄷ카페! 홍대카페입니다~ 구경하는 재미도 너무 쏠쏠하고 층마다 너무 예쁘게 인테리어를 꾸며놔서 너무 곳곳이 포토존이에요! 사진찍고 놀아도 반나절은 가겠더라구요~~ 제가 갔던날은 6,7층에 행사가 있었는데 다양한 행사도 진행하고 복합문화공간답게 공연이나 여러 행사도 많아서 너무 신기했어요~ 홍대 랜드마크는 ㅎㄷ카페! 홍대카페가 아닐까 싶습니다~~ 합정역카페나 상수역카페 찾으신다면 들려서 구경해보세요~', 67, 18, 'GOOD', SYSTIMESTAMP);
