INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '오랜만에 홍대에 와서 딸이랑 카페데이트왔어요. 얘기만 듣고 처음방문인데 직원분도 친절하시고 음료와 디저트도 맛있게 먹고 복합공간이라 층별로 구경도 하고 사진도 많이 찍고 다음에 딸이 또 오고 싶다고 조만간 또 올거같아요~^^', 123, 25, 'GOOD', SYSTIMESTAMP);
