INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '홍대 그렇게 자주 왔는데 이런 공간이 있는건 꿈에도 멀랐네요 🫢9층 건물 전체를 이용할 수있는 대형카페가 홍대 상상마당 바로 건너편에 있는데 층마다 분위기도 미쳤고 옥상에는 서울 전체가 보이는 루프탑에 디저트도 종류별로 준비되어있어 너무 신선한 공간이엿어요.. 진짜 다시한번 방문해봐야되는 또카페...🔥🔥 층마다 컨셉이 다 달라서 신기한 컨셉카페로 들리기에도 딱이엿습니다. 특히 식물덕후, 관엽식물덕후분들 3층 꼭 가보십쇼 너무나 충격적인 공간이에요', 9, 2, 'GOOD', SYSTIMESTAMP);
