INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '진짜 최고의 뷰맛집 디저트 카페랍니다 홍대 데이트 필수코스 관광코스 인정이에요 분위기 좋은 루프탑에서 힐링제대로인데 디저트도 다 맛있고 음료도 진짜 존맛도리,,❤️✨️ 안갈이유가 없어요 정말~~~ 재방문해서 메뉴 도장깨기성공!👍😭 진짜 왜안가 여러분~~', 23, 5, 'GOOD', SYSTIMESTAMP);
