INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '뷰 맛집, 커피 맛집, 디저트 맛집이었어요! 외국인 분들 엄청 많으시던데, 여행 와서 루프탑에서 시원한 음료 마시면서 일몰을 보면 정말 멋진 풍경으로 기억에 넘으시겠다 싶더라구요! 다음에 또 방문하고 싶어요!😄', 77, 13, 'GOOD', SYSTIMESTAMP);
