INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '홍대에서 카페 갈일 있으면 무조건 여기로 가요! 자리도 넓고 테마도 다양한데 디저트랑 음료가 맛있어서 어디 하나 빠지지 않는 것 같아요ㅎㅎ 더 자세한 리뷰는 🔻🔻🔻 https://m.blog.naver.com/dbgkdms1431/223938777385', 51, 14, 'GOOD', SYSTIMESTAMP);
