INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '이런 홍대대형카페가 있다는 게 너무 좋아요 각 층마다 테마가 달라서 구경하는 재미도 있구 커피도 맛있구 디저트도 맛있어서 완전 만족스러웠어요. 9층 루프탑이 진짜 멋있으니까 꼭 구경해보세용 ㅎㅎㅎ 노을 질 때 오면 더 좋을 거 같아서 다음에 또 와보려구용', 54, 15, 'GOOD', SYSTIMESTAMP);
