INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '8층에서 음료를 구매한 다음 전층을 돌아다니며 이용할수 있어요. 각 층마다 매력이 있지만 특히 7층 k pop media 관이 3면이 화면이고 편안한 빈백이 너무 좋네요.', 30, 2, 'GOOD', SYSTIMESTAMP);
