INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '홍대카페 중에서 제일 큰 대형카페가 아닐까싶네요!! 디저트 종류도 다양하고 파나마 게이샤 원두도있습니다~~!! 층마다 컨셉이 다양해서 사진찍기 좋았어요^^!!', 24, 8, 'GOOD', SYSTIMESTAMP);
