INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '분위기가 너무 좋고 각 층마다 새로운 테마로 꾸며져 있어서 구경하는 재미가 있어용 해질때쯤 루프탑 가니까 노을이 넘 예뻤어요 ㅎㅎ 커피랑 케이크도 넘 맛있어용 💖', 45, 4, 'GOOD', SYSTIMESTAMP);
