INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '한 층만 쓰는 일반 카페와 달리, 이곳은 음료 하나로 복층 문화공간을 자유롭게 이용할 수 있어서 체험형 카페 느낌이 강했어요. 커피 맛도 괜찮고 디저트 조합도 안정적이라, 혼자 가도 충분히 만족스러웠습니다.', 1, 0, 'GOOD', SYSTIMESTAMP);
