INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '합정과 상수역에서도 가까운 홍대입구역 대형카페에 다녀왔다. 각 층마다 컨셉이 달라서 사진 찍는 재미가 있는 데이트 명소이다. 루프탑에서 전망을 누리고 원하는 층에서 고급 원두 파나마게이샤를 마실 수 있다. 맛있는 체리 가나슈 케이크와 다쿠아즈도 준비돼 있으니 당충전을 해보는 건 어떨까?', 30, 6, 'GOOD', SYSTIMESTAMP);
