INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '홍대 9층에서 바라보는 서울 뷰가 너무 멋있네욤! 층별로 테마가 다른 것도 멋있고 무엇보다 음료, 디저트가 너무 맛있어요 ㅎㅎ', 120, 21, 'GOOD', SYSTIMESTAMP);
