INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '8층이 전부 카페라는 점에서 너무 놀랐어요!!! 심지어 층마다 다 다른 컨셉으로 되어있어서 시간가는 줄 모르고 놀 수 있을 것 같아요ㅎㅎㅎ', 84, 18, 'GOOD', SYSTIMESTAMP);
