INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '층마다 여러가지의 인테리어와 매력이 있어서 너무좋은것 같아욤 개인적으로는 7층이 제일편하더라고욤 음악들으면서 편하게 의자에서 있을 수 있어서욤 헤헷 ㅋㅋㅋ 정말 힐링합니다 홍대에 이런카페가 있다니 신선하면서 좋습니다~~ 다음에도 또 올려고욤 헤헷', 7, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '홍대에서 분위기 좋은 대형 카페 Rooftop 카페를 찾았습니다 커피 부터 디저트까지 정말 너무 맛있더라구요 8층 까지 즐길 수 있어서 그리고 각층마다 컨셉이 다 달라서 데이트로 연인들과 데이트하기 정말 좋은 곳이더라고요 서울 대형 카페 또는 홍대 마포 합정 상수에서 대형 카페를 찾는다면 ㅎㄷ 카페 정말 추천 드립니다 그리고 세계최고 국가 원두 파나마 게이샤 원두가 있다고 하더라구요 저도 처음 들어보는 원 되었는데 다음에 와서는 꼭 먹어 보도록 하려구요~~ 각층마다 인테리어와 분위기가 정말 다 다르고 깔끔하고 궤적 하다 보니 하루에 다 즐기 지도 못 할 정도로 너무 재밌었습니다 다음에 또 올게요', 24, 8, 'GOOD', SYSTIMESTAMP);
