INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '홍대 나들이 와서 어느 카페 갈까 찾아보다가 왔는데 정말 기대이상이였습니당 ! ! 😮😮😮 카페에 왔다기보다 복합몰 온 느낌이였어요 ,, 전시회도 있고 식물원같은 공간도 있고 k팝 공간도 있고 lp들을수 있는 곳도 있고 또 있었는데 기억이ㅠ 다음엔 엄마 모시고 또 오려구요 ,,', 110, 22, 'GOOD', SYSTIMESTAMP);
