INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '우선 케이크 너무 맛있어요 부드러운 생크림 질감의 케이크가 입 안에서 그냥 녹아버려서 순삭했어요.. 체리초코 넘 맛있도 전 오레오가 더 존맛 쉬폰같이 촉촉한데 달달한 크림도있어서 짱!! 못참고 우유소금빵까지 시켰는데 세상에 시원한 우유크림에 소금빵 조합 단짠•••ㅜㅜ 이런 대형카페 너무 오랜만이에요 각 층마다 컨셉이 정해져있고 분위기가 달라서 몇개의 카페를 하루에 다 탐방한 기분이었어요', 45, 6, 'GOOD', SYSTIMESTAMP);
