INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '와 층별로 이렇게 다른 매력을 보여줄수 있다는게 너무나 큰 장점을 가진 카페였어요 👍🏻 층마다 화장실도 깨끗하게 관리되어 자리하고있는것도 너무 좋았고요 홍대들리면 또 가고싶은 곳 포토존에서 사진찍기좋아하는 사람이라면 무조건 들려야할 장소', 123, 26, 'GOOD', SYSTIMESTAMP);
