INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '홍대카페. 홍대에 있는 감성 가득한 8층짜리 카페. 층마다 분위기가 달라서 하나하나 구경하는 재미가 있어요. 캐이팝을 앉아서 감상할 수도 있고, 아기자기한 갤러리도 있고, 좋은 음향이 흐르는 공간도 있어요. 홍대 한복판에 이런 여유로운 공간이 있다는 게 놀랍고도 반가웠습니다. 다음에 또 들를게요!', 26, 8, 'GOOD', SYSTIMESTAMP);
