INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '압도적인 카페 크기에 입이 떡 벌어지는 홍대 대형 카페😍🤩각 층마다 확고한 컨셉이 담겨 있는 게 맘에 들었어요 개인적으로 느좋 미디어아트가 나오는 층이 취저✔ 미디어아트 속 파도 소리와 물소리 들으며 맛도리 디저트와 음료 즐기니 주중의 스트레스가 싹 사라지네요 루프탑 위에서 바라보는 시티뷰도 멋져요 날씨 좋을 땐 여의도와 국회의사당 풍경까지 보이는데 동남아 루프탑 카페 느낌 나고 좋아요🌴✨ 홍대에서 독보적인 규모를 가진 이색 카페라 데이트 코스로 매우 추천드려요🙌🏻💯', 125, 24, 'GOOD', SYSTIMESTAMP);
