INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '일단 8층전부가 카페라는 게 미쳤어요! 전 7층 케이팝 존에 머물렀는데 누워서 좀 쉬다가기에도 너무 좋았어요. 나머지 층도 눈 호강하기 최고더라구요! 다들 덥고 지쳤을때 쉬다가기 최고니까 꼭꼭꼭 가세요🩷', 43, 5, 'GOOD', SYSTIMESTAMP);
