INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '나름 홍대를 너무 잘아는 곳인데 어쩜~~ 이렇게 좋은 카페가 있는지는 왜 이제 알았을까요 ㅠㅠ 저보다 외국인분들이 많아서 오히려 당황~~😱 층층마다 어마어마한 컨셉과 건물을 모두 사용하는 이런 고급진 카페라니... 이제부터 자주올거 같아요~~🥹 층층마다 구경하고 딸이랑 같이가서 7층에서 음악들으며 편하게 눕듯이 시간을 보냈어요~ 너무 너무 좋아요~~ 디저트와 음료도 맛있고^^ 주변에 많이 추천해야겠어요~~😍 강추해요~~👍🏻 너무 좋은 홍대카페!!! ㅎㄷ카페💗', 96, 19, 'GOOD', SYSTIMESTAMP);
