INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '완전 추천⭐️⭐️⭐️⭐️⭐️디저트도 맛나고 음료도 다양하고 맛있어요 ㅎㅎ 층마다 Lp,K-pop ,갤러리 등 컨셉이 달라서 층 돌아다니면서 구경할 수 잇어서 조아요 !!! 사진도 잘나오고 완전 짱', 27, 7, 'GOOD', SYSTIMESTAMP);
