INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '홍대 대형카페 ㅎㄷ 카페 완전 추천이요👍👍 층마다 컨셉이 확실하고 느낌이 다 달라서 여러 분위기로 즐길 수 있어요 😍 루프탑에서는 탁 트인 홍대 뷰까지 볼 수 있어요 디저트도 다양한데 치즈케이크는 진하고 부드러워서 추천😊', 7, 7, 'GOOD', SYSTIMESTAMP);
