INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '홍대 상상마당 건너편에 생긴 홍대대형카페입니다. 옥상뷰가 멋진 곳입니다. 여의도와 국회의사당이 예쁘게 보여요 낮에 더웠는데 해질때 올라가면 바람도 솔솔 불고 꽤 시원합니다. 각 층 별로 테마가 있어 둘러보는 재미가 있습니다.', 97, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '홍대에 이렇게 큰 카페가 있는지 몰랐어요!! 제거 가본 대형카페 중에서도 제일 대형인거 같아요 층마다 컨셉이 다 달라서 누가와도 필요한게 다 있어요 ㅋㅋ데이트,회식,카공 등 그리고 디저트도 맛있고 뷰도 좋았습니당 다음에 또 올게요 ㅎㅎ', 18, 4, 'GOOD', SYSTIMESTAMP);
