INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '몰랐는데 들어와서 알았어요!! 제국의 아이들 리더 문준영님이 사장님이신 것 같아요!!오오오오오🙀👏🏻✨ 건물 하나 통으로 카페라서 구경하는 재미도 쏠쏠하고 직원들도 엄청 다 친절하고 치케랑 다쿠아즈 넘 맛있네요 ⭐️😎 잘먹고가용~~!ㅎㅎ', 52, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '홍대에 큰 대형카페가 있다길래 가보았습니다. 층층별로 테마가 있어 빨리 주문하고 음료들고 가보았어요. 누워서 음악을 감상할 수도 있었고 갤러리에 앉아서 커피를 즐길 수도 있었고 선인장등 식물이 많아 기분이 상쾌해지는 층도 있었어요. 그중 저는 갤러리 층이 제일 마음에 들었습니다♡♡ 거기서 2시간동안 친구랑 수다떨다가 9층 루프탑도 구경하고 갔어요. 홍대에서 카페!하면 여기가 제일 좋은거 같아요', 101, 20, 'GOOD', SYSTIMESTAMP);
