INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '3층이 제일 제 취향🥹 카페+전시+음악+자연+감성 다 있는 종합 문화공간 느낌! 홍대커피 맛집, 홍대디저트카페, 홍대데이트 장소 찾는다면 여기 ㅠㅠㅠㅠ 전 재방문 의사 100% “하나의 카페로 이렇게나 다양하게 채워질 수 있구나…” 싶었던 곳인 것 같아요. 사장님도 친절하시고ㅠㅠ 재방문 꼭 하겠습니다!!', 80, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '오늘 홍대ㅎㄷ카페 처음와봤는데 와 매장이 너무 커서 놀랐어요ㅎㅎ 이렇게 큰 대형 카페가 홍대에 있는것도 신기하고 무엇보다 각 층마다 분위기가 너무 색달라서 사진찍을 맛도 나고 너무 좋았어요ㅎㅎ 특히 루프탑도 있고 k-pop 미디어라고 빈백 있는곳도 있어서 편히 쉬다 갈수 있었고 디저트랑 음료도 진짜 맛있었어요 ㅋㅋ 여기는 인테리어만 멋있는게 아니라 세계 최고 고가 원두 파나마게이샤 원두가 있다는데 제가 오늘은 코코넛라떼랑 에이드만 먹어서 담엔 커피마시러 또 와봐야겠네요 ㅋㅋ 매장도 넘 쾌적하고 워낙 자리가 많다보니 얘기하기에도 넘 편했어서 담에 또 올꺼에요😆🥰😝', 26, 7, 'GOOD', SYSTIMESTAMP);
