INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '인테리어가 진짜 멋지고 층층마다 컨셉이 달라서 구경하기 넘 좋네용~~^^  오레오케익 강추합니다~~ 아이스티도👍 카페인때문에 커피 잘 안먹는데 다른 음료들도 다 맛나요!❣️', 49, 6, 'GOOD', SYSTIMESTAMP);
