INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '디저트 맛있고 엄청엄청 넓어요!! 🍰🧁 평일에 갔는데 넓고 공간 쾌적해요 노트북 하기도 좋고 대화하기도 좋아요✨ 플랜드 공간 인상적이네요🍀', 32, 9, 'GOOD', SYSTIMESTAMP);
