INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '홍대 상상마당 바로 앞에 대형카페가 생겼다니 너무 궁금해서 바로 방문했어요! ☕️🍰 일단 1인 1음료를 주문하면 지하 1층부터 루프탑 9층까지, 총 8개 층을 자유롭게 이용할 수 있다는 점이 너무 좋았고 각 층마다 컨셉과 분위기가 완전히 달라서 둘러보는 재미가 쏠쏠하더라구요. 커피도 디저트도 맛있었고 무엇보다 볼거리가 많아서 커플 홍대데이트, 친구와 홍대놀거리 장소로 너무 추천드리고 싶어요!!🤍🤍', 6, 4, 'GOOD', SYSTIMESTAMP);
