INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '분위기 좋은 홍대카페 볼거리 믾고 즐길거리 많고!! 케이팝 좋아하는 외국인 친구들과 놀러와도 좋을거 같아요 인테리어도 좋고 분위기 좋네요 감각적이고 세련된 느낌? 마음에 들어요!!', 49, 8, 'GOOD', SYSTIMESTAMP);
