INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '이색데이트로 좋고 공간 활용도가 너무 좋아 만족수러워요 홍대더니면서 처음 가봤는데 왜 이제 가봤지 생각할 정도로 공간이 마음에 들었어요', 27, 3, 'GOOD', SYSTIMESTAMP);
