INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '마운틴허브차, 레드베리아이스티, 체리가나슈케이크, 치즈케이크 주문 디저트는 부드럽고 풍성, 음료는 향긋하고 깔끔했어요 8층에서 주문 후 루프탑으로 바로 올라가 홍대 전경 감상 가능! 한강보다 여유롭고 조용한 루프탑, 홍대에서 감성 힐링 원하면 여기!', 44, 5, 'GOOD', SYSTIMESTAMP);
