INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '홍대에 이렇게 큰 카페가 있는지 몰랐는데 정말 놀랬어요!! 층층 마다 컨셉이 확고해서 고르는 재미, 구경하는 재미도 있고 매장이 엄청 넓은데도 굉장히 깔끔하고 관리가 잘 되어있어서 너무 좋았어요! 여긴 카페 그 이상이에요 마치 복합 문화 예술공간인거 같았어요! 커피, 음료, 케이크도 다 맛있었어요♥️', 37, 2, 'GOOD', SYSTIMESTAMP);
