INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '#협찬 부산에서 서울 여행일정 잡으면서 너무 오고싶었던 곳이에요 ‼️ 연남동 홍대 카페가 많은데 그 중에서 8층 전체를 다른 테마로 전 층 이용할 수 있는 초대형 카페라 너무 궁금했어요 😆 저는 고민하다가 5층 갤러리테마를 선택하고 앉았는데 조용한데 잔잔한 노래가 나와요 ~ 알록달록 작품과 플랜테리어속에 둘러쌓여 힐링 그자체였어요 ! 8층에서 주문하는데 8층도 인테리어가 너무 매력적이에요 ..(첫 번째사진) 디저트는 초코랑 치즈케이크를 골랐는데 깜짝 놀랐던 점은 “적당한 달콤함”입니다 ! 연령대 관계없이 모든 디저트 호불호없이 먹기 좋을 것 같다는 생각이 들었습니다 👍🏻 매번 달콤한 디저트는 아이스아메리카노나 담백한 카페라떼와 먹는 편인데, 홍대카페는 바닐라라떼나 달콤한 음료와 즐겨도 맛있을 것 같아요❤️', 14, 1, 'GOOD', SYSTIMESTAMP);
