INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '인테리어도 너무 예쁘고 디저트와 음료도 다 맛있음 지하1층부터 9층 루프탑까지 이용할 수 있는 서울대형카페 찾으시면 추천! 이런데가 있는지 알았다면 진작 와볼껄 그랬어요ㅜㅜ 추천합니다', 109, 19, 'GOOD', SYSTIMESTAMP);
