INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '3층~9층 (지하 1층은 공연장인데 대관 있으면 사용하는듯) 통으로 사용하는 대형카페, 층별로 컨셉과 분위기가 모두 달라서 ‘이색 체험 카페’로 적합. 3층은 식물원, 4층은 수석과 계곡물 소리, 5층은 현대미술 갤러리, 6층은 lp 전시가 되어있고, 7층은 3면에 케이팝 최신 뮤직비디오가 연속재생되고 빈백들로 공간이 채워져 있음. 8층은 일반 카페고 9층 옥상은 계단식으로 되어있는데 홍대 전체가 보임. 분위기 개좋음. 공간 널널하고 옮겨다녀도 눈치 안주심.', 14, 6, 'GOOD', SYSTIMESTAMP);
