INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '서울에서 야경과 노을을 직관하며 커피마실 기회가 졀로 없는데 홍대에 이런 곳이 있을 줄은 몰랐어요! 디저트도 너무 맛있고, 눈도 호강하고👍 잘 먹고 갑니다 ㅎㅎ', 51, 11, 'GOOD', SYSTIMESTAMP);
