INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '카페가 엄청커요..!! 8층에 루프탑까지 있는데 그게 다 카페예요.. 그래서 좌석이 엄청 많아서 자리 없을 일이 없을 것 같아요 👍🏻❤️ 그리고 완전 청결해요!! 남자칭구랑 전 층 다 누비며 재밌게 놀다 왔습니다 ♪ 음료랑 디저트도 넘 맛나구 진짜 즐거웠네용ㅎㅎ 홍대에서 너무 많이 돌아다녀서 힘들 때 ㅎㄷ카페 추천드립미다 ㅎㅎ🫶🏻', 50, 2, 'GOOD', SYSTIMESTAMP);
