INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '홍대 대형 카페로 추천하는 ㅎㄷ카페 예전에 오고 또 왔지만 날마다 발전하는 느낌! 인테리어도 조금씩 추가되고 케이팝존도 바뀌고 너무 좋은듯 푹쉬고 대화하기 좋은 분들한테 추천하는 홍대카페🫶❤️ 그리고 점장님?이신듯한디 친절하셔서 좋아요 ㅎㅅㅎ 앞으로 번창하면 좋겠음 👍👍', 9, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '와•• 8층 건물을 통으로 쓰는 곳도 놀라운데, 층마다 다른 컨셉이라 구경하는 재미가 있었어요. 공연, 문화, 예술, 카페, 루프탑 모두 다 한 공간에서 해결할 수 있다니ㅋㅋ! •9F ROOF TOP - DJ 요즘 날씨에 루프탑 최고인거 아시죠😍 세상이 훤히 보이니까 너무 기분 좋더라고요ㅎㅎ 국회의사당까지 보인답니다?! 제 최애 공간이에요! •7F MEDIA ART 3면의 벽에 뮤비를 상영해주는데요! 빈백에 누워서 편하게 있을 수 있는 공간! 너무 편하고 노래 흥얼거리면서 쉬기 좋은 공간이라 진짜 일어나기 싫었던 차애 공간!ㅋㅋ 케이크도 크고 과일 듬뿍 들어있어요! 큰 이유는 홍케이크의 1/8이 아니라 1/6로 판매하셔서ㅎㅎ', 74, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
