INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '홍대근처 예쁜 카페 찾아보자...고 지인과 이야기하며 검색 중인데 관광안내하시는 분이 알려주신 서울에서 가장크고 3층 부터 8층까지 컨셉이 다른 카페입니다. 8층에서 커피 주문하면서는 다른 프렌차이즈보다 비싸네...했는데 두루 돌아보다가 이 정도면 커피값 너무 싸다...하며 여기저기 사진찍어 다른 지인들에게 보내기 바빴습니다. 말이 필요없는 곳. 힐링할 수 있는 카페. 카페가 행복을 주기도 하네요. 더 칭찬글 쓰면 관계자로 오해 받을 듯 합니다.', 42, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '딸기, 초코 생크림 케이크 부드러워서 맛있어요! 음료는 라떼랑 딸기라떼 시켰는데 라떼도 고소하고 딸기라떼는 적당히 달고 딸기 알갱이도 많아서 맛있었습니다. 8층에서 주문하면 3~7층, 옥상 모두 컨셉이 달라서 구경 가능해서 좋았어요. 특히 옥상은 해질녘에 너무 예쁠것 같더라구요. 연인이랑 데이트, 친구들이랑 대화하기 무조건 추천드리는 카페입니다!☕️', 49, 4, 'GOOD', SYSTIMESTAMP);
