INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '홍대 갈때마다 카페들 자리 없어서 넘 힘들었는데ㅠㅠ 여긴 수노래방 맞은편에 완전 대형카페로 되어있어서 좋은거 같아요!! 딸기케이크 너무 달달 맛있고 다쿠아즈도 폭신 두툼하고 디저트 맛집입니다!! 인테리어는 말할것도 없이 멋져요 홍대 올때마다 방문해야겠어용💕', 99, 20, 'GOOD', SYSTIMESTAMP);
