INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '홍대카페는 대형카페로, 넓어서 대화하기 좋았고 무엇보다 디저트 종류가 많고 정말 맛있습니다,,🩷 케이크 맛집입니다👍🏻👍🏻👍🏻 나중에 또 디저트 먹으러 가려구요', 33, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '9층 전체가 다 카페에요. 구경하다보면 대박이라는 소리만 나와요. 심지어 각 층마다 화장실이 있어요😲 8층(음료 주문하는곳은) 사람이 많지만 그 외 층은 조용해요.스톤벨리에서 공부했는데 사진 찍으러 오기만 하지 착석하는 사람은 없었어요. 홍대에서 새로운 데이트 장소나 힐링 공간을 찾고 계신다면, 꼭 한 번 들러보세요.', 50, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '간만에 친구들이랑 수다도 떨겸 찾아가게 됐는데 엄청 크더라구요! 무려 9층까지....... 테마별로 나뉘어 있어서 고르는 맛이 있었어용 저는 6층인 LP존에서 있었는데 분위기 왕왕좋구 사운드도 적당해서 대화하기 너무 좋았어용 음료는 당연히 너무 맛있었구 ㅠㅠ 디저트는 말모..🫶 루프탑이 너무 궁금해서 가봤는데 아니 분위기 너무 예쁘더라구요..? 오늘은 너무 더워서 있지는 못했지만.. 그늘로 가면 충분히 시원하고 좋았을 듯.. 화장실도 층별로 깔끔하게 되어있고 남녀 따로 구분되어있어서 너무 좋았어용!! 7층엔 빈백도 있었는데 담에는 거기 가서 빈백에 누워서 놀려구여~~', 1, 7, 'GOOD', SYSTIMESTAMP);
