INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '홍대에 이런 카페가 있다니!!😻 ! 건물이 다 카페에여 각층마다 테마도 다르고 너무 분위기 있고 좋아요!! 볼거리가 많아서 외국인 친구들 데리고 와도 너무 좋아할 듯해여! 케이크 맛있어 보여서 시켰는데 역시 맛있어용🤍🤍', 5, 4, 'GOOD', SYSTIMESTAMP);
