INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '가게가 매우 넓고 깨끗했어요✨️ 디저트&음료들도 매우 맛있었고, 총 8개의 층이 모두 카페 였는데 층마다 컨셉이 달라서 골라 가는 것이 좋았어요👍👍', 27, 6, 'GOOD', SYSTIMESTAMP);
