INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '9층 뷰 대박 ㄷㄷ 커피도 음료도 디저트도 모두 맛있고 매장도 정말 쾌적해요~!! ^^ 🙌🏻☕️🍰😋👀📸 포토스팟으로 강추 입니다 ㅎㅎ', 2, 2, 'GOOD', SYSTIMESTAMP);
