INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '홍대에 이런 대형 카페가 있다니! 여러 테마가 있어서 어디서 먹을지 고민하고, 구경할 수 있는 재미가 있었어요!  꼭 날씨 좋은 날 가세요ㅠ 루프탑이 정말 낭만 있더라고요✨ 햇빛이 잘 들어 대충 찍어도 분위기 있는 사진 맛집입니당 인생 사진 많이 건지고 가요~📷 넓어서 작업하기도 좋고 친구들이랑 편하게 이야기 나눌 수 있는 분위기였어용 커피는 조금 연한 편 입니당~ 에그타르트가 바삭한 게 괜찮았어영😋 홍대에서 조용히 데이트 즐기기 딱 좋은 장소 입니다🤭 다쿠아즈 종류도 많던데, 다음번엔 다쿠아즈 도전해 보고 싶네여!', 64, 14, 'GOOD', SYSTIMESTAMP);
