INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '층마다 다른 분위기 인데다 매장이 넓고 층마다 화장실이 있어서 더더욱 좋았어요!! 커피도 맛있지만 레드베리아이스티..짱👍 아메리카노는 파나마게이샤 추천드려요~!!! 케이크 오레오케이크 미쳐써요!!!! 매장이 넓어서 사진 찍을 맛도 나고 홍대에서 데이트 하면 꼭 여기 다시 올게요 좋은 추억 만들고 갑니다🥺🤍', 64, 11, 'GOOD', SYSTIMESTAMP);
