INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '핫플 홍대에 이렇게나 큰 대형카페가 있다니! 알았으면 진작 많이 왔을텐데 이제야 알게 된 게 아쉽네요. 층마다 테마가 달라서 여러 번 방문해도 방문할 때마다 새로울 것 같아요. 디저트맛집답게 케이크도 너무 맛있네요. 특히 만다린초코케이크가 맛있었어요 ㅎㅎ 다음에 또 재방문할게요~!', 26, 2, 'GOOD', SYSTIMESTAMP);
