INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '각 층마다 컨셉이 완전 다르고 깔끔하고 관리가 정말 잘 되어있어요!! 홍대에 이런 대형카페가 있었다는걸 왜 이제 알았을까요.. 😱😱😱😱❤️❤️❤️ 노트북으로 작업하기도 너무 좋고, 공부하기도 넘 좋아요!!', 5, 7, 'GOOD', SYSTIMESTAMP);
