INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '#협찬 초대형 홍대카페!! 진짜 크고 넓다. 루프탑은 날씨 좋을 때 다시 가보고 싶음. 3층의 선인장 가득한 곳도 좋고 7층의 빈백도 편하다. 8층에 루프탑까지 있으니 한바퀴 둘러만 봐도 한시간이 모자름...!!! 음료는 아메리카노 추천, 케이크가 찐짜 맛있어요!!', 35, 2, 'GOOD', SYSTIMESTAMP);
