INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '홍대에 이렇게 큰 카페가 있는줄 몰랐습니다. 각 층별로 테마가 다른 것도 흥미로웠고 커피도 엄청 맛있네요! 다음에 또 방문해야겠어요', 80, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '과일 케이크먹고싶어서 와봤는데,, 오후에 오니 과일케이크는 이미 솔드아웃ㅠㅠ 초코, 얼그레이케이크 + 게이샤커피 시켰는데 케이크 시트 촉촉하니 맛있고 산미커피 싫어하는데 기분나쁜 신맛아니고 되게 향긋한 신맛이라 맛있게 잘 먹었어요!', 7, 9, 'GOOD', SYSTIMESTAMP);
