INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '층마다 컨셉이 달라서 어디 앉아야할지 고민되더라구요ㅜㅜ 1일8카페 가능한 느낌이라 너무 특색있고 좋았어요!  대형카페라 자리도 많고 널찍해서 다인원방문도 추천입니다!', 52, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), 'ㅎㄷ 카페 지나가면서 한 번쯤 가보고싶었는데 이번에 가보고 너무 좋아서 일주일만에 다시 재방문했어요 ! 홍대에서 이런 대형카페 없을거예요 안에 놀거리도 많고 카페 공간도 넓고 쾌적해서 좋아요 ! 디저트 종류도 많고 케이크도 넘 맛있었어요 ☺️☺️ 이색적인 카페로 추천드려요', 59, 15, 'GOOD', SYSTIMESTAMP);
