INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '1층부터 8층까지 이용할 수 있는 대형카페라 넘 좋아요 ~ 층마다 컨셉이 달라서 구경하는 재미가 있고 디저트도 맛있어요!! 👍🏻 짱', 48, 1, 'GOOD', SYSTIMESTAMP);
