INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '이렇게 크고 예쁜 카페는 처음이에요!! 8개 공간에 컨셉도 다 달라서 여러 카페를 간 것 같은 느낌이네요👍 생크림케이크 진짜 존맛이에요 ㅠㅠㅠㅠ ㄱ커피도 깔끔하니 존맛 ㅎㅎ 자리도 많아서 다음에 단체 모임하러 오려규요!!', 75, 18, 'GOOD', SYSTIMESTAMP);
