INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '보드의 이런 멋있고 괜찮은 카페가 있는지 몰랐습니다. 3층부터 루프트답까지 다양한 컨셉으로 꾸며져 있어서 좋은 시간 보내기에 너무 좋은 공간입니다', 36, 1, 'GOOD', SYSTIMESTAMP);
