INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '이렇게 대형 카페가 홍대에 있다니,,, 정말 믿겨지지가 않는 스케일이에요! 디저트도 완전 다양하고 케익류가 정말 맛있었ㅇ요 ㅎㅎ 인테리어가,,, 정말 우와 소리가 자동으로 나오는 비쥬얼이고 파주나 서울 외곽이나 가야지 있는 대형 카페 느낌이라 사진도 열심히 찍고 여기저기 구경하면서 시간이 후딱 지나갔어요!', 86, 17, 'GOOD', SYSTIMESTAMP);
