INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '9층짜리 카페라니!! 루프탑 최고예요. 지금 가기 딱 좋아요. 시원하고 탁 트여서 기분 좋아집니당. 오레오케이크 강추. 진하고 맛있어요. 차도 맛있어요. 평일에 방문하니 한산해서 좋네요~~', 45, 9, 'GOOD', SYSTIMESTAMP);
