INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '서울에서 가장 큰 카페라던데 진짜 커요 ㅋㅋ 층별로 테마도 달라서 다양하게 즐길 수 있구여 원두 좋은 거 쓰셔서 그런지 커피가 진짜 맛있습니다!! 케이크도 꿀맛 🌟', 25, 5, 'GOOD', SYSTIMESTAMP);
