INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '8층 통째가 카페라서 눈이 즐겁습니다~ 케이크가 꾸덕하니 맛있고 커피는 생각보다 연해서 아쉬웠어요!! 자리 걱정없이 층별로 즐길 수 있어서 좋습니다 :)', 73, 17, 'GOOD', SYSTIMESTAMP);
