INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '엄마와 마주 앉은 따뜻한 오후에 처음 방문을 했는데 넓고 숲속에 들어 온 느낌과 분위기가 세련되고, 여유롭게 즐길다 갈 수 있어서 좋고, 사람들로 북적하면서도 활기찬 느낌이 강하게 느꼈습니다! 다음 방문에는 또 다른 커피와 디저트로 맛보고 싶은 마음이 생기게 된거 같아요!👍👍👍', 11, 1, 'GOOD', SYSTIMESTAMP);
