INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '상상마당 맞은편에 상상도못할 8층카페가!! 층마다 다르면서도 묘하게 연결되어있는게 더 신기함 :) 시즌 끝나기전에 딸기로 플렉스했쥬~ 딸라 딸케~ ㅋㅋㅋㅋ 음료도 케이크도 완젼 맛나요! 해질녁 루프탑 전경도 완전 믓지다는뎅 담번에 꼭 담아보려구요!! 티음료가 좋아하는 로네펠트네요 담번픽 층마다 다 매력있어서 방문할때마다 다른 넉낌으로 넘 좋을것 같아요~ 홍대에서 카페 찾으신다면 바로 요기 ㅎㄷ카페 추천꾹👆', 71, 12, 'GOOD', SYSTIMESTAMP);
