INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '매장 진짜 넓고 8층으로 되어 있는데 각 층마다 특색이 달라서 테마파크 놀러온 느낌이에요! 지인들이랑 연인이랑 오기 정말 좋은 것 같아요! 디저트도 맛있고 케익 특히 달달하고 촉촉해서 맛있었어요:) 재방문 의사 100프로입니다!', 21, 7, 'GOOD', SYSTIMESTAMP);
