INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '특히나 케이크들이 생크림 케이크가 많아서 좋았답니다! 층별로 테마가 다르게 꾸며져 있었어요. 9층은 루프탑이어서 천장이 없고 옥상에 계단식으로 되어있었어요. 날이 좋거나 야경이 예쁘면 앉기 좋을만해요', 93, 24, 'GOOD', SYSTIMESTAMP);
