INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '홍대카페 방문 후기! 와 사진으로 봤을때 이정도로 대형 카페인지 몰랐는데 규모가 엄청나요!! 볼거리가 많도 테이블도 많아서 커피 마시기 편해여~ 체리가나슈 생크림케이크 + 🧀 꾸덕한 치즈케이크까지 완벽 조합✨ 9층까지 전층 이용 가능해서 홍대입구역, 상수역, 합정역 카페 중 분위기 최고 ㅎㄷ카페, 다음엔 루프탑에 날씨 좋으면  노을 보면서 커피 마시고 싶어요! #협찬#홍대케이크 #홍대카페 #홍대대형카페 #ㅎㄷ카페', 13, 1, 'GOOD', SYSTIMESTAMP);
