INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '오래 걸어가지구 발 아파서 어디 갈만한 곳 없을까~ 하다가 찾게 됐는데 카페 분위기도 너무 좋아서 만족스러웠어요!☺️ 처음에 가격보고 좀 당황,,,을 하긴 했는데 음료랑 디저트는 정말 맛있게 먹었습니다!🤤', 16, 5, 'GOOD', SYSTIMESTAMP);
