INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '매층마다 다른 컨셉의 카페이고 홍대메인거리에 있어요!!! 아메리카노는 산미있는 편이고 조명과 분위기가 다양해서 좋습니다!! 디저트도 다쿠아즈 에그타르트 케익 등 다양합니다!', 352, 64, 'GOOD', SYSTIMESTAMP);
