INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '처음 와봤는데 눈이 휘둥그레질 정도의 규모에 놀랐습니다. 10여년 전 신랑이랑 데이트하러 많이 다녔던 곳인데 여전히 변함없이 젊음이 넘치는 곳이네요! 그 중에 단연 탑티어 힙힙 카페 홍대카페입니다♡ 케이크 커피 입에서 살살 녹게 맛있었고요♡ 7층까지 식물과 전시회 음악까지 즐길 수 있다니요~ 게다가 9층은 루프탑♡ 오늘은 비가 와서 아쉬웠을 뿐이네요^^; 아이랑 같이 비오는 저녁 즐거운 시간 보내고 갑니다!', 39, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
