INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '공간이 넓고 쾌적하네요 층마다 다른컨셉의 공간이있어서 선택의 폭도 넓어 고르는 재미가 있었네요 식물도 많아 미세먼지도 없는것같은 느낌적 느낌? 서울여행와서 넓은공간에서 충전하고 다시여행합니당', 27, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '홍대핫플카페👍 1-8층, 루프탑까지 전층이 카페구 각층마다 컨셉이 있어서 좋았고 LP판층은 잔잔한 음악이 나와서 일하기도 너무 좋네요 ㅎ 조용하게 대화하기도 좋아서 데이트하기 좋은 카페 추천 꾸욱! 커피, 디저트도 너무 맛있어요^^', 16, 0, 'GOOD', SYSTIMESTAMP);
