INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '홍대에 이런 대형카페가 있다는거 알자마자 달려왔어요! 층마다 테마도 다르고 사장님 너무 친절하셔서 갬덩..ㅠㅠ 가족들과 갔는데 아이가 3층 식물원이랑 7층 케이팝 존을 젤 좋아하더라고 ㅎㅎ 아침일찍 가서 여유롭게 잘 쉬다왔어요>< 영상이 도중에 끊겨서 풀영상 링크 남겨둬요! https://m.blog.naver.com/bunny_lu/clip/8396100', 55, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '분위기 좋고 규모가 큰 홍대 상상마당 앞 대형카페에요! 원두도 좋은거 쓰시고 공간도 넓어서 자리걱정 안하고 방문가능해서 좋네용!!', 17, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '지하1층에서 9층까지 전체가 ㅎㄷ 카페네요!! 각층마다 컨셉이 달라요 디저트 생각보다 엄청 맛있고 커피는 산미느낌닙니당~ 데이트, 부모님이랑 시간보내기 강추~👍🏻', 43, 7, 'GOOD', SYSTIMESTAMP);
