INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '층층 공간마다 너무 예뻐서 만족스러운 곳이였네요. 대형카페라서 좌석이 많아서 홍대가면 사람많고 카페 찾아야할땐 여기가면 될것같아요. 옥상 전망이 좋았어서 밤에 야경보러도 가보고싶네요~', 61, 17, 'GOOD', SYSTIMESTAMP);
