INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '층마다 분위기도 다르고 매장이 매우 넓어요!! 좌석도 진짜 많아서 여럿이 방문해도 좋을 것 같아요 디저트도 진짜 맛있어요~!! 특히 생크림 딸기케이크 jmt 층마다 구경하는 것만으로도 즐겁네요 친구와 즐겁게 얘기하다 갑니다~~', 36, 2, 'GOOD', SYSTIMESTAMP);
