INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '여기 완전 디저트맛집카페 !! 그 중 케이크 종류가 다양하고 달달함 그 자체였어요 💗 비주얼도 애니메이션 꿈빛파티시엘에 나올법한 퀄리티✨ 카페 분위기도 고급스럽고 감성적이고 루프탑도 있어서 한번올라가보는데 풍경이 장난 아니더라구요 !! 맛있는 디저트 먹으면서 풍경도 보고 ~ 힐링 그 자체인 카페 👍🍰', 36, 5, 'GOOD', SYSTIMESTAMP);
