INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '커피부터 디저트, 장소 시설까지 너무 다양하고 볼거리가 많아서 좋았어요!!! 엄청 큰 카페라 그런지 좌석도 많아서 작업하거나 회의하기도 좋은 장소 ~ 친구 연인 가족과 함께 놀러오는거 추천해요 :) 갤러리, 식물관, 루프탑, lp바 등등 문화시설이 많아서 전혀 지루하지않고 힐링하기 좋은 것 같아요! 외국인들도 관광지 여행으로 온다면 이곳을 소개시켜주고싶네요 !!', 62, 11, 'GOOD', SYSTIMESTAMP);
