INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '서울에서 가장 규모가 크다는 홍대카페! 지하 1층부터 8층, 루프탑까지 있었어요. 층마다 테마가 달라서 구경하는 재미도 있었고, 디저트도 너무 너무 맛있었답니다. 개인적으로 7층에 있는 K-POP MEDIA 층이 좋았어요. 세 개의 벽에서 뮤직비디오가 나오고 빈백에 누워서 편하게 쉴 수 있었거든요. 음료도 맛있었고 특이하게 파나마 게이샤 원두인 커피도 판매하고 있었어요. 그 커피는 먹어보지 못했지만 기회가 된다면 나중엔 먹어보고 싶네요 ㅎㅎ 평일 점심때쯤 갔을때는 사람이 엄청 많진 않았는데 4시? 쯤 되니까 점점 오시긴 하더라구요. 주말에는 사람 더 많이 몰릴것 같아요. 그리고 화장실도 층마다 있는데 청결하니 좋았어요.', 27, 1, 'GOOD', SYSTIMESTAMP);
