INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '홍대입구역 근처에 이렇게 큰 카페가 있었다니..! 무려 9층 전부 이용 가능하고, 층마다 인테리어와 테마가 달라서 구경하는 재미가 쏠쏠했습니다! 좌석도 엄청 넓고 청결해서 단체 모임이나 데이트 장소로 딱이에요~~ 커피는 세계 최고급 원두 파나마 게이샤 사용 메뉴가 있어서 커피 덕후라면 꼭 마셔봐야 해요. 저는 디저트로 만다린 초코 케이크와 레몬 요거트 다쿠아즈를 먹었는데 다쿠아주 추천드려료@@!', 34, 0, 'GOOD', SYSTIMESTAMP);
