INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '홍대오랜만에갔는데 홍대에서 이렇게큰카페는 첨봐요 층별로 컨셉도 다다르고 무엇보다 야외테라스가 뷰가 탁트여서 노을질때오면 딱이예요 오늘 날씨가 선선해서 엄청 시원하고 속이 뻥뚫리는기분이였어요 홍대갔다가 다리아프면 여기와서 쉬기좋을것같아요', 18, 7, 'GOOD', SYSTIMESTAMP);
