INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '친구와 함께 다녀왔는데 카페보다 전시장 같은 느낌에 넓어서 너무 좋았어요!! 디저트도 너무 맛있고 볼거리도 많아서 홍대가면 자주 이용할 것 같아요~', 43, 2, 'GOOD', SYSTIMESTAMP);
