INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '홍대 한복판에 이런 곳이!? 9층짜리 건물에 루프탑까지 있는 대형 감성카페 다녀왔어요. 층마다 컨셉이 다 달라서 마치 작은 전시관 같았어요. 8층 메인 카운터에서 주문하고, 9층 루프탑으로 올라가면 탁 트인 도심 뷰가 펼쳐지는데 사진 찍기 딱 좋더라구요📸 7층엔 K-pop 뮤직비디오가 나오는 빈백 소파룸, 6층은 LP 음악 들으며 여유롭게 앉을 수 있는 감성 가득한 공간, 5층엔 아트 전시, 4층은 몽환적인 무드의 영상 공간, 3층은 식물 가득한 힐링존까지! 층별로 돌아다니는 재미가 있어서 가족들과 수다 떨며 시간 보내기 너무 좋았어요. 감성 카페 좋아하시는 분들께 추천합니다😊 #홍대카페 #루프탑카페 #감성카페 #홍대데이트 #카페추천 #카페투어', 7, 7, 'GOOD', SYSTIMESTAMP);
