INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '정보없이 방문하게됐어요. 먼저 8층에서 음료를구입하면 건물안에 층마다 다른컨셉의 장소를 즐길수있어요. 아이디어가 너무좋고 독특해요. 아이도 재미있어하고 다른곳보다 커피값이 비쌌지만 그만큼가치있어요. 특별한경험이었어요.', 14, 2, 'GOOD', SYSTIMESTAMP);
