INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '디저트도 커피도 다 맛있지만 루프탑 뷰가 그냥 미쳤습니다!! 층별로 테마가 있어서 색다르게 즐길 수 있어서 좋았는데 참고로 루프탑이 그냥 최고....!', 9, 4, 'GOOD', SYSTIMESTAMP);
