INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '이곳은 서울최대규모 복합문화공간으로 공연, 문화, 예술, 카페, 루프탑을 모두 즐길 수 있는곳이더라구요.🫖 저는 딸기라떼&아이스초코&다쿠아즈를 먹어보았는데요, 다쿠아즈는 겉은 바삭하고 안엔 부드럽고 촉촉한 크림이 넘 맛있었어요.🥯 딸기라떼랑 아이스초코도 너무 맛있어서 아이들도 잘 먹었답니다. 디저트의 맛과 비주얼도 뛰어나고, 한층한층 다 구경해보니 각층마다 컨셉이 다 달라서 재밌게 구경할 수 있었어요. 게다가 공간이 워낙 넓고, 쾌적해서 단체이용에도 좋고, 친구나 가족과 함께 방문하기 딱 좋았어요.👍🏻', 29, 9, 'GOOD', SYSTIMESTAMP);
