INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '음료한잔값으로 8층건물을 통으로 구경하고 즐길수있어 좋았어요 다음엔 시간적여유를 갖고 길게 즐기다갈래요♡ 공간공간마다 인스타감성에 너무이뻤습니다', 8, 8, 'GOOD', SYSTIMESTAMP);
