INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '홍대 어울마당로 걷다가 들어간 감성카페! 조명 아래서 먹는 디저트는 분위기부터 다르네요. 치즈케이크는 진하고 부드럽고, 겉면 살짝 탄 부분이 진짜 고소해요. 생딸기 케이크는 달지 않고 상큼해서 너무 잘 먹었어요. 아이스 아메리카노는 산미가 깔끔하고, 라떼는 우유랑 에스프레소 밸런스가 딱 좋아요. 분위기 좋고 조용해서 대화하기도 편했고, 사진 찍기 좋은 포인트도 많아서 만족했어요!', 63, 14, 'GOOD', SYSTIMESTAMP);
