INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '디저트도 맛있고 볼거리가 넘쳐나는 홍대카페💛 3층부터 8층까지 통으로 카페인데 층마다 컨셉이 달라서 구경하는 재미가 있었어요 😆 특히 7층 케이팝 미디어존에서 빈백에 누워 뮤비를 감상하던 시간이 가장 재밌었네요 ㅎㅎ 이색데이트 원하시면 강추드립니다 👍🏻', 106, 20, 'GOOD', SYSTIMESTAMP);
