INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '홍대에 이렇게 멋진 카페가 있는 줄 몰랐어요 엄청 크고 쾌적해서 놀러오기 정말 좋을 것 같아요 층층별로 볼거리가 엄청 많네요 디저트도 넘 맛있어서 만족합니다.', 27, 10, 'GOOD', SYSTIMESTAMP);
