INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '입구부터 감성 넘치는 인테리어에 딱 마음을 뺏겼어여ㅠㅠㅠ💛 통창으로 들어오는 햇살 덕분에 사진도 너무 예쁘게 나오고, 조용한 분위기라 혼자 책 읽거나 노트북 하기에도 딱 좋더라고요. 음료는 시그니처 메뉴인 딸기라떼를 시켰는데, 진짜 달달해서 또 생각나는 맛이에요.🫶🫶 디저트로는 생크림 딸기 케이크를 먹었는데, 촉촉하고 부드러워서 커피랑 찰떡! 직원분들도 친절하고 자리 간격도 넉넉해서 불편함 없이 여유로운 시간 보낼 수 있었어요. 다음엔 친구랑 또 가려고요. 감성 카페 좋아하시는 분들께 강추!🤍', 47, 4, 'GOOD', SYSTIMESTAMP);
