INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '홍대카페에서 딸기생크림케이크와 딸기라떼를 즐겼어요. 케이크는 폭신한 시트와 상큼한 딸기, 부드러운 생크림이 조화롭게 어우러져 입안에서 살살 녹았고, 딸기라떼는 진한 딸기퓨레에 우유가 어우러져 달콤하고 신선한 맛이 인상적이었어요. 분위기도 아늑하고 감성적인 인테리어 덕분에 사진 찍기에도 좋았고, 데이트나 혼자 여유롭게 시간 보내기에도 딱이에요. 재방문 의사 100%!', 14, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
