INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '⭐️분위기, 맛, 넓은 공간 다 잡은 곳!!!!⭐️ 홍대에 이런 대형카페가 있는지 처음알았어요! 친언니가 딸기케이크 맛잇다고 전시회같이 분위기도 좋다고 한번 가보라 해서 방문하게 된 곳인데 정말 인테리어가 신기하네요 층층마다 컨셉이 달라서 취향따라 자리잡는 재미가 있어요! 9층까지 있는 대형건물이고 9층은 루프탑이라던데 비가 오는바람에 아쉽게도 못 갔는데 다음에 방문하면 루프탑 가고싶어요 층고도 높아서 서울공기 구경하기 너무 좋을듯 싶네용ㅎㅎ 그리고 여기 전체적으로 조명이 너무 이뻐요 사진 막 찍어도 잘 나오더라구요? 디저트는 딸기시즌이라 그런지 딸기케이크 종류별로 있구 제 최애 바치케도 있었는데 기대 별로 안했는데 뜻밖에 마싯었어요!! 리뷰 이렇게 정성들여 쓰는거 처음인데..재방문의사 1000000%!!', 83, 13, 'GOOD', SYSTIMESTAMP);
