INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '퇴근 후에 친구랑 맛있는 거 먹으면서 편하기 이야기 하고 싶어서 찾아 온 카페인데, 진짜 너무 좋아요! 얼그레이 케이크도 퐁신퐁신한데 크게 달지 않아서 단 거를 많이 안좋아하시는 분들도 엄청 좋아할 거 같아요!🥰 그리고 건물 자체가 다 카페 건물이라 사람 없는 층 가서 편하게 떠들 수도 있고, 층별로 특색있어서 원하는 층에서 놀면 될 거 같아요! 남자친구랑 와도 좋고 친구랑 와도 좋을 거 같아서 너무 추천드려요!', 45, 1, 'GOOD', SYSTIMESTAMP);
