INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '홍대에 이런 대형카페라니👏👏 층마다 테마가 있어서 너무 좋았어요❤️❤️❤️ 다음에도 다양한 케이크도 먹으려구요🍽 홍대 카페 강추합니다👍👍👍👍👍', 0, 9, 'GOOD', SYSTIMESTAMP);
