INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '홍대 8개층 사용가능한 ㅎㄷ카페!! 전층모두 느좋 제대로에 카페내부도 엄청 컸어요!! 홍대에 놀러온다면 한번쯤은 꼭 가볼만한 카페 !!', 7, 4, 'GOOD', SYSTIMESTAMP);
