INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '7층 k pop 존 이용했는데요. 빈백소파에 누워 뮤비 보니까 넘 시원하고 좋네여 ㅎㅎ 8층에서 오더하구 한층씩 내려가는 재미가 쏠쏠한 곳입니다 😀 데이트하거나 쇼핑하고 쉬어가기 딱 조아여 ㅎㅎ', 26, 2, 'GOOD', SYSTIMESTAMP);
