INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '홍대 카페 헤매다가 엄청 큰 대형 카페 발견했어요 !! 사실 1-2층 정도인줄 알고 들어간건데 엘베보고 9층 모두 한 카페 건물이더라구요~ 층마다 테마도 달라서 구경하는 맛도 있고, 사진은 말모 ~~ 다 잘나오더라구요 루프탑도 경치 넘 조아요. 저는 낮에 방문했는데 일몰도 넘 예쁠 거 같아요. 메뉴도 다양한 편이고, 특히 원두 종류가 다양해서 좋더라구요~ 메뉴 모두 맛있었고 친절하셨어요 :) 일단 저는 케이팝 미디어 층 가서 빈백에 누워있기도 해보고, 엘피 층 가서 음악 감상하며 넘 행복한 시간 보냈습니다. 카페 데이트가 아니라 실내 데이트라도 한 기분이었어요 ㅋㅋㅋㅋ👍', 33, 5, 'GOOD', SYSTIMESTAMP);
