INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '홍대에 이런 대규모 테마 카페가 있는지 몰랐어요! 심지어 층마다 다 다른 주제로 꾸며진 카페인데 매층마다 깔끔하고 관리가 잘 된 모습이라 더 쾌적하게 머무를 수 있었습니다. 층마다 음악이나 분위기가 달라서 데이트, 친목, 미팅 등 모두 가능하겠다고 생각들었어요. 케이크에 동물성 생크림만 사용한다고 하시던데 딸기 생크림케이크가 진짜 부드럽고 맛있고 라떼도 보통 남기는데 여기 라떼 넘 맛있어서 다 마시고 나와써요🥰 담에는 랩탑 들고와서 여유롭게 선인장 테마 층에서 머물다가 가고 싶네요. 친절하신 스탭분들도 인상깊어요👍👍', 9, 1, 'GOOD', SYSTIMESTAMP);
