INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '루프탑 뷰도 너무 예쁘고 8층 전체가 카페라 구경하기 좋고 음료도 맛있고 분위기 좋아요!! 케이크는 동물성 생크림 사용해서 느끼하지 않고 맛있습니다! 게이샤커피도 팔아서 커피 좋아하시는 분들이 가면 좋을거같아요~', 42, 10, 'GOOD', SYSTIMESTAMP);
