INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '혼자 공연보러 홍대옴~^^화장실 가고 싶어서 우연히 왔는데 건물한채가 모두 까페임~오늘 시간이 너무 여유가 있었는데 각층마다 테마가 달라 너무 잘온거같음~ 사진이 잘 나와서 므흣함ㅎ', 34, 8, 'GOOD', SYSTIMESTAMP);
