INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '홍대구경왔다가 커피랑 케이크 먹으로왔는데 층마다 구경하는 재미도 있고 루프탑 뷰도 너무 멋져요!! 샤인머스킷 케이크 상큼하고 너무 맛있어요👍👍👍', 48, 0, 'GOOD', SYSTIMESTAMP);
