INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '홍대입구에 이렇게 멋진 카페가 있었군요👍 건물 전체가 카페이고 층별로 분위기가 달라서 멋있었어요✨🌊 케이크도 굉장히 맛있었구요 :) kpop층은 특히 영화관 같기도 하고 웅장했어요!! 추천!!🩵', 6, 2, 'GOOD', SYSTIMESTAMP);
