INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '3층부터 루프탑까지 컨셉이 5개나되는 카페가 있다니!! 너무 신기했습니다👍 공간마다 분위기가 너무 달라서 취향따라 분위기를 즐길수 있을것같아요!! 커피랑 디저트도 맛있네요 루프탑 전망이 최고입니다 날씨 좋은 날 즐기세요!!!🤗', 29, 2, 'GOOD', SYSTIMESTAMP);
