INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '분위기 좋아서 사진맛집이네요~~ 공간공간 볼 요소들이 많고 케이크가 맛있어요~ 치즈케이크 부드러워서 음료와 함께 즐기니 찰떡이네요', 1, 9, 'GOOD', SYSTIMESTAMP);
