INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '홍대 데이트하다가 너무 더워서 우연히  들어간 카페가 홍대카페인데 😆😆 분위기도 정말 좋고 커피, 디저트 맛도 훌륭해서 좋았어요👍', 129, 21, 'GOOD', SYSTIMESTAMP);
