INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '홍대에서 연인 끼리 데이트하기 좋은 대형루프탑 카페에요!! 층마다 다른 컨셉으로 구경 거리가 많고 자리도 넓어서 좋았어요!! 음료 그리고 디저트 까지 다 맛있었고 홍대에서 데이트 또는 친구들과 오시는분들 아니면 공부 하시는분들 오셔서 있기에 좋은 카페여서 추천해요~!', 116, 25, 'GOOD', SYSTIMESTAMP);
