INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '오랜만에 지인과의 홍대 나들이💓💓💓 홍대에 대형카페가 생겼다는 말을 듣자마자 들리게 되었는데 9층까지!!! 다 한 건물인거 있죠?!! 각 층마다 테마가 다양해서 어디에 자리를 잡을지 엄청 고민했어요!! 그리고 저 먹음직 스러운 케이크와 에그타르트 등 다양한 디저트들까지😍😍😍😍 분위기가 너무 좋고 청결해서 더욱 좋았던거 같아요!! 아 참 맨 꼭대기 층에는 루프탑이 있는데 날이 좀 따뜻해지면 따스한 햇살과 커피한잔의 여유를 즐기면 좋을 것 같다는 생각이 들었답니다💓💓💓', 50, 10, 'GOOD', SYSTIMESTAMP);
