INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '남편이랑 아이랑 방문했는데 생각보다 더 괜찮아요~!! 층마다 화장실도 있고 층마다 테마도 다르고 케익이랑 다쿠아주 너무 맛있어요!!!👍🏻👍🏻👍🏻', 20, 10, 'GOOD', SYSTIMESTAMP);
