INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), 'ㅎㄷ카페는 조용하고 감성적인 분위기가 매력적인 공간입니다🫢 코코넛라떼는 고소하고 깊은 맛이 느껴졌고, 디저트도 정성스럽게 만들어져 하나하나 만족스러웠어요🍰친절한 직원분들 덕분에 기분까지 좋아졌어요👏👏꼭 다시 가고 싶은 카페예요☕️그리고 층마다 볼게 많아서 8층에 커피 두고 구경해보세요-!', 14, 6, 'GOOD', SYSTIMESTAMP);
