INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '홍대 대형까페!! 생겼단 말듣고 바아아로 다녀왔어여 8층짜리 루프탑까지 총 9층짜리 건물을 통째로 쓰는데 층마다 컨셉이 있어 너무 재밌는 공간입니다 :) 디저트도 커피도 맛나요 :)', 2, 0, 'GOOD', SYSTIMESTAMP);
