INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '✴️ 홍대가면 꼭 찾게되는게 대형카페인데 이번에 네이버 지도로 가기전에 검색을 좀했더니 이런 루프탑있는 카페가 있었다 🥭그리고 이 빌딩 건물 자체를 카페에서 층마다 다른 컨셉으로 운영하고있다보니 구경해보는 재미가 쏠쏠하다. 🅰️ 날씨가 좋아서 바람도 솔솔 느끼는 재미가 있고 저멀리 여의도 국회의사당까지 보이는 뷰가 인상적이였다.', 18, 0, 'GOOD', SYSTIMESTAMP);
