INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '홍대에 이렇게 큰 카페가 생겼다니..!!! 갤러리 + 카페를 합쳐놓은듯한 분위기에요! 음료도 맛있고 인테리어도 너무 멋지네요!! 외국인들도 많이오는 홍대 대형 맛집카페!!!😆😆💚💚', 60, 18, 'GOOD', SYSTIMESTAMP);
