INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), 'ㅎㄷ카페는 건물 전체가 다양한 컨셉의 공간으로 구성되어 있더라구요. 진짜 넓고 다양한 구성의 공간이라 데이트하기에 진짜 좋은 공간이라고 생각해요. 가히 충격적일 정도로 3층 공간은 이색적인 공간이었어요. 외국인들도 신기한지 많이 찍더라구요. ㅎㅎ 공간 자체가 깔끔했어요! ㅎㄷ카페 자체가 올해 방문한 카페 중에 거의 손꼽을 정도로 이색적인 공간이었답니다.', 69, 14, 'GOOD', SYSTIMESTAMP);
