INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '8층 모두 볼거리가 아주 넉넉한 카페네요:) 맛있는 디저트도 있고 커피맛도 굳굳~ 홍대 쪽 카페들은 웬만하면 공간이 좁거나 작은데 여긴 한 건물이 통째로 카페이기도 하고, 공간이 워낙 넓어서 시간 보내기도 최고고 아주 좋아요~ 인테리어도 예뻐서 보는 재미도 쏠쏠!! 사진 찍는 곳마다 포토존이라 친구들 데리고 오기도 넘 좋아서 담에는 같이 오려구요~!!^^ ♥️', 47, 7, 'GOOD', SYSTIMESTAMP);
