INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '여기 공간도 엄청 크고 층마다 분위기가 달라서 취향에 맞게 장소 선택할 수 있는게 넘 좋아요 🤍 그리고 디저트 넘넘 맛있어요💓 딸기케이크 강추✨ 다쿠아즈, 에그타르트도 팔아서 넘 좋아용 ㅎㅎ 공간이 정망 넓어서 부담없이 오기 좋아요>< 자주 올거같아요 !!', 38, 7, 'GOOD', SYSTIMESTAMP);
