INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '홍대에 이렇게 큰 대형 카페가 있다는게 너무 신기했어요! 층마다 다양한 테마가 준비되어있는데 기대감 가득 안고 보는 ..❤️ 인테리어도 너무 예쁘고, 디저트들도 맛있었어요 홍대에 오게 된다면 다음에 또 방문하고싶은 곳이에요🙃', 67, 18, 'GOOD', SYSTIMESTAMP);
