INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '와 한건물이 다 카페 공간인데 층마다 컨셉이 다 다르고 좌석도 많아서 너무 좋아요!! 저는 그 중에 6층 공간이 제일 최애였어요 ㅋㅋ 커피도 맛있어요😉', 49, 0, 'GOOD', SYSTIMESTAMP);
