INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '8층 전체를 사용하는 대형카페가 홍대 한 가운데에 있다니 진짜 대박이에요 ㅎㅎ 층마다 테마가 달라서 보는 재미가 있고 케이크도 종류가 은근 많아서 좋았어요 ><', 56, 14, 'GOOD', SYSTIMESTAMP);
