INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '케이크는 홍대케이크답게 부드러운 생크림과 달콤한 과일 조화가 일품이었다. 비주얼도 너무 예뻐서, 받자마자 자연스럽게 사진을 먼저 찍게 되는 디저트들이었다. 음료 역시 산뜻하고 달지 않아 디저트와의 밸런스가 좋아 만족도가 높았다. 각 층은 서로 다른 테마와 인테리어로 꾸며져 있어 걷는 재미, 구경하는 재미, 머무는 재미까지 느낄 수 있다. 대형 규모인 만큼 좌석도 넉넉해서, 주말이나 피크 시간대에도 자리를 걱정할 필요가 없다는 점이 특히 만족스러웠다. 이런 점에서 홍대데이트 장소로도 손색없는 홍대카페맛집이다.', 6, 4, 'GOOD', SYSTIMESTAMP);
