INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '카페가 엄청 커서 놀랐어요. 그만큼 좌석도 많고 쾌적한데 내부도 깔끔해서 같이 얘기하기 좋았어요! 각 층마다 테마가 있어서 원하는 곳에서 즐기기 좋아요. 음료와 디저트도 맛있어요. 저는 흑임자 인절미 다쿠아즈 추천드립니다!', 83, 11, 'GOOD', SYSTIMESTAMP);
