INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '뷰 보러 왔는데 그냥 카페 맛집이네요,, 케이크도 당연히 맛있지만 에그타르트 더 b. 강추!!!! 바삭한 식감에 적당히 달아서 더 맛있어요 3층부터 8층+루프탑 까지 엄청 넓은 공간이고 층마다 컨셉이 다른데 모든 층이 예뻐요 홍대 메인거리 중간에 있어 접근성도 좋고 다음에 또 올게요 :)', 8, 3, 'GOOD', SYSTIMESTAMP);
