INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '홍대대형카페 ㅎㄷ카페! 지나갈 때마다 궁금했는데 정말 크고 볼게 많네요! 디저트도 음료도 맛있고, 무엇보다 카페가 정말 크고 쾌적해서 마음에 들었습니다. 다음에 또 올게요☺️', 40, 4, 'GOOD', SYSTIMESTAMP);
