INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '홍대 한복판에 루프탑 포함하여 9층짜리 초대형카페라니 세상에 마상에 거기다가 층마다 컨셉이 완전 달라서 전혀다른카페를 온거같아요 방문할때마다 층층이 즐기는것도 방법일거같아요 :)디저트랑 커피도 너무 부드럽고 맛있어요', 28, 0, 'GOOD', SYSTIMESTAMP);
