INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '층마다 컨셉이 정해져있고., 총 8층이라 구경거리도, 쉴 곳도 매우 많습니다! 여기저기 둘러보는 재미가 있고, 편히 쉬었다가기 너무 좋네요~ 복잡한 홍대 거리에서 잠시 쉼이 필요하다면·· 이곳을 추천합니다!!!  🤍', 40, 5, 'GOOD', SYSTIMESTAMP);
