INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '홍대에 이렇게 대형카페인데 감각적인 복합문화공간이 있을줄은 몰랐네요! 공간만 멋진게 아니라 음료랑 디저트도 너무 맛있어요 ㅎㅎ 다쿠아즈는 제가 먹어본 다쿠아즈중에 젤맛있네요! 먹다가 전시구경하고 LP뮤직공간에서 노래듣고 시간가는줄 몰랐어요 지금처럼 추운겨울에는 실내데이트 장소가 귀한데 데이트장소로도 추천합니다!🤍🩵', 107, 25, 'GOOD', SYSTIMESTAMP);
