INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '다양한 테마로 이뤄진 ㅎㄷ 카페 하나의 카페가 아닌 여러개 카페를 한번에 들린 느낌이 들어서 너무 좋았어요 데이트 장소로 강추 드리구요~ 서울 놀러오시면 꼭 들려보세요 ㅎㅎ 재밌었어요', 111, 21, 'GOOD', SYSTIMESTAMP);
