INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '카페 생크림 초코케이크 너무 맛있어서 2개 먹고 싶을 정도였어요! 8층까지 놀 수 있는 곳도 많아서 아주 재밌게 데이트 즐기다가 가려고 합니다 😊', 28, 0, 'GOOD', SYSTIMESTAMP);
