INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '아니 여기 진심 미쳤어요 컨셉있는 카페 🤩 날씨 좋은날 루프탑가면 끝남 🤷🏻‍♀️😋 음료들도 좋았고 구경하는 재미가 있었고 외국친구들 데려오ㅏ도 좋을듯 !', 22, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '8층 건물 하나가 다 통째로 카페인데 층별로 컨셉이 다 달라요. 말로만 듣던 모든 컨셉의 카페가 다 있어요. 8층에 주문하는 층에는 사람은 진짜 많은데 다른 층으로 내려 가면 앉을 곳 많아요. 음료는 오렌지 에이드랑 베리 아이스티 먹었는데 오렌지는 직접 간 것 같이 상쾌하고 맛이 진해서 맛있었어요. 베리 아이스티는 많이 달지 않아 적당했어요. 디저트는 치즈케익이랑 흑임자 다쿠아즈 먹었는데 음료랑도 잘 어울려서 맛있었습니다. 추천하는 층은 6층 음악 공간이고 자리도 제일 많아요. 누워있으려면 7층도 편해보이고, 다른 층들도 각각 특색있어서 한번씩 가보고 사진 찍기도 좋았어요. 사람이 많으니 음료 나오는 시간이 있어서, 음료 나오기전에 구경하는 것도 좋아요.', 12, 5, 'GOOD', SYSTIMESTAMP);
