INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '주말에 카페는 사람이 많아서 여유로운 카페찾기가 힘든데 장소가 넓은점이 너뮤 좋은데다가 층마다 다른 인테리어로 꾸며져있어서 원하는 분위기 층에 가서 먹기 좋더라구요 디저트와 음료도 아주 굿굿!', 23, 9, 'GOOD', SYSTIMESTAMP);
