INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '홍대에 대형카페가 생겼다고해서 바로 방문해보았습니당 8층건물에 음료시키면 다 둘러볼수 있다고 해서 놀랐어요!! 디저트 종류도 많고 음료 종류도 많아서 입도 즐겁고 눈도 즐겁네요 ☺️☺️ 다들 여기 오시면 후회없을 거에요!!! 추천추천 🍀', 85, 18, 'GOOD', SYSTIMESTAMP);
