INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '홍대가 아니라 홍콩온 것 같아요!!! 층마다 다양한 컨셉으로 즐길 수 있어서 여기에만 머물러도 시간가는 줄 모르고 놀 수 있습니다👍🏻👍🏻', 36, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '홍대카페 9층으로 이루어진 공간을 다녀왔습니다 층마다 분위기가 확실하고 청결하고 음료도 맛있어서 너무 좋았습니다. 다양한 컨셉과 확실한 분위기를 느끼시려면 홍대카페 적극추천합니다!', 36, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '디저트도 너무 맛있고 커피도 맛있어요 무엇보다 층마다 컨셉이 다른 공간이 제일 매력적입니다! 사진도 잘 나오고 데이트하기 좋아요', 33, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
