INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '홍대 카페 항상 사람 많아서 복잡하고 정신없었는데... 상상마당 근처에 이렇게 큰 대형카페가 있으니까 넘 쾌적해서 이용하기 좋아요ㅠㅠㅠ 딸기케이크도 100퍼 동물성임... 적당히 달달하고 고소해서 너무 맛있어요👍 8층이 다 컨셉이 달라서 층마다 구경하는 재미도 있었어요. 좌석 간격도 넓고 노래소리도 별로 크지 않아 대화하기 좋아용 데이트 코스로 진짜 강강강추합니다!!❤️‍🔥', 42, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '9층 규모의 서울 역대급 대형카페! 각 층마다 다른 분위기를 선사하고 있어서 골라 앉는 재미가 있습니다. LP바, 갤러리, 식물, 미디어 등 다양한 공간이 준비되어 있고, 좌석도 2인석부터 단체석까지 다양하게 준비되어 있습니다. 한 번만 오기에는 아쉬울 정도로 분위기가 좋고 쾌적하니 홍대오면 가볍게 방문해 보세요!!😊😊 카페전문 유튜브 유리소리TV', 76, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '케이크는 정말 케이크맛집이라고 해도 손색없을정도로 맛있네요!! 옥수수라떼는 옥수수맛이 살짝나고 안달고, 리치에이드는 정말 너무맛잇어요!! 리치맛이 엄청 진해서 너무맛있어용 ㅠㅠ 분위기도 진짜좋고 커피 마시면 8층 전부 다 이용할수잇다는게 너무 신박하고 좋은것같아요! 다양하게 즐길수있고 디저트종류 음료종류도 많아서 좋네요 ㅎㅎ', 38, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
