INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), 'https://m.blog.naver.com/nyammyammi/223754412314 키워드가 5개 밖에 선택이 되지 않는게 아쉽네요 이렇게 규모가 큰데도 깔끔하게 관리 잘 되어있다는게 놀랍습니다 층마다 음수대 냅킨 종이컵 화장실 다 있어서 편해요 음료 맛도 디저트 맛도 훌륭합니다 코코넛 라떼는 코코넛 좋아하면 무조건 좋아할 맛이고 딸기라떼는 상상가능한 맛이에요 그래서 맛있는 ㅎㅎㅎ 다쿠아즈가 생각보다 되게 괜찮아요 필링도 두툼하고 당도도 적당합니다 딸기케익도 시트 촉촉하고 크림도 맛있고  딸기 많아요 !!! 크림과 시트의 밸런스가 적절합니당ㅋㅋㅋ 요즘 프차던 어디던 딸기 케익 한피스 8천원 이상 하는데도 많은데 좌석도 편하고 음료도 맛있는데 이 정도면 무조건 재방문입니다', 21, 6, 'GOOD', SYSTIMESTAMP);
