INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '핫하고 힙한 홍대입구역카페 홍대디저트카페 핫플 ㅎㄷ카페 너무 괜찮은데요?! 특별한 이색 데이트는 물론 넘나 맛있는 디저트들도 맛 볼수 있는 디저트 맛집이랍니다', 13, 2, 'GOOD', SYSTIMESTAMP);
