INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '카페에 왔는데 다양한 전시장을 들른 기분이에요! 8층에서 주문한 후 전 층을 다 구경다니며 커피&수다 타임🥰 근데  친구랑 음료들고 계단 내려가려는데 어떤 손님 두 분이 밑엔 카페 아니라고 말리며 엘리베이터 타고 슝 사라졌어요... 그분들은 잘몰라서 이 좋은 걸 못 즐기고 가셨겠더라고요?? 전층 자유롭게 이용 가능한 점이 진짜 매력적인데 안타까웠습니다 ㅠㅠ 담엔 다른 층 다 보고 가시길..ㅎㅎ 개인적으로는 물소리 들리는 4층 스톤밸리랑 미니 식물원느낌 3층 플랜트가 넘 힐링돼서 좋았어요! 빈백에 기대서 놀수있는 케이팝미디어존이랑 LP뮤직 층도 넘 포근해서 좋아요 층도 다양하고 좌석이 많으면서도 배치가 여유로워서 남들 신경 안 쓰고 놀기 좋아요 추워서 루프탑엔 못있었는데 날풀리면 다시 와서 놀아야겠어요💕', 18, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '#협찬문의 #광고 #협찬 🧚‍♀️🔮레인별🔮의 리뷰 📃 제품협찬 장소매장 (홍대카페) 🎀 #협찬 #광고 협찬 상품 음료2. 디저트2 🧚‍♀️🔮레인별🔮이 시킨메뉴 1.아메리카노 5.800 2.모카라떼 6.900 3.자몽에이드 6.900 4.치즈케이크 6.500 5.리본모양 크로와상 4.800 📸📄매장 관련 -놀거리도 풍부하고 층마다 다른스타일의 테마로 즐기실수 있어서 좋으실꺼같아요  매달마다 전시나 행사들에 따라 테마들이 바뀌고 밴드나 공연들도 볼 수있다고하니 좋을꺼같아요 -리본처럼 이쁜 크루와상안에는 맛있는크림도 들어가있어서 좋았어요 -분위기나 디저트들 맛도 너무좋고 지인들과 재미지게 둘러보면서 힐링했던 카페입니다 #디저트카페 #홍대카페 #ㅎㄷ카페', 5, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '대형카페를 많이 다녀보았지만 이렇게 테마가 다양한곳은 처음인거 같아요!! 각 층마다 분위기도 다르고 인테리어도 각양각색이어서 즐기기 충분한거 같아요👍🏻 그런데 이 모든 층을 음료 주문만 하고 이용할 수 있다니 정말 좋은듯합니다!! 데이트하기에도 좋고 조용한 층은 공부하기에도 좋은거 같아여~ 음료도 맛있고 케이크도 맛있어서 대만족합니당~!', 24, 3, 'GOOD', SYSTIMESTAMP);
