INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '카운터가 정말 깨끗하구요~~ 층층마다 화장실이 있어서 정말 편리해요!! 디저트는 적당히 달아서 음료와 함께 즐기기 좋았어요~~ 산미없고 고소한 아메리카노와 딸기라떼로 달달하게 기분을 더 끌어올리구 왔어요~~ 넘넘 잘 먹고 갑니다>_<💕', 34, 4, 'GOOD', SYSTIMESTAMP);
