INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '매장이 넓고 층마다 컨셉이 확실해서 재밌었어요. 음료값만 내도 이용할 수 있다는 게 좋습니다. 커피랑 디저트도 맛있어요~~~~ 가격이 비싸지도 않아서 부담없이 오기 좋아요!! 다음에 홍대 오면 또 방문할 것 같아요~~', 6, 1, 'GOOD', SYSTIMESTAMP);
