INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '공간미쳤다!!!! 🏡💖 층마다 분위기가 달라서 어디에 앉을지도 고민이에요. 카페가 아니라 전시장에 온 기분이에요😆 파도 있는 곳이랑 케이팝 존은 미디어아트 전시 온 것 같았어요👍🏻인테리어가 너무 예뻐서 어디서 찍어도 인생샷 💖 그리고 넓은 공간 덕분에 자리 걱정 없이  주말에도 편하게 즐길 수 있어서 더욱 만족입니다💯💯 디저트+음료도 맛있어서 진짜 최고 😍🥰❤🩷', 3, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '🔹주문 메뉴: 레드베리 아이스티 + 코파카바나 티 + 생크림딸기케이크 + 생크림 초코케이크 층마다 다양한 컨셉이 있어서 볼거리도 많고 공간을 다양하게 체험할 수 있어 좋았어요ㅎㅎ 개인적으로 LP뮤직 층이 분위기 좋고 가장 맘에 들었습니다 아쉽게도 음료와 디저트는 가격대비 그냥 그저 그렇습니다 오래 머물 수 있고 여유로운 분위기의 대형 카페 찾으시면 추천해요!', 81, 11, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
