INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '우와 홍대 한복판에 무려 8층짜리 카페라니!! 각층마다 테마가 다양해서 구경하는 재미도 있고, 공간도 예뻐서 사진찍는 재미가 쏠쏠해요! 먼저 엘베타고 8층에서 주문부터하고, 여러층을 자유롭게 이동할 수 있어요✨️ ◽️B1층. ㅎㄷ STAGE 특별한 공연을 하는 곳🎤 ◽️3층. PLANT 작은 열대식물원 느낌! 선인장 가득🌵 ◽️4층. STONE VALLEY 미디어 아트로 즐기는 자연🌊 ◽️5층. GALLERY 때마다 다양한 작품 전시가 열려요🖼 ◽️6층. LP MUSIC LP가 진열되어있고, 도서관같은 분위기⚫️ ◽️7층. K-POP MEDIA 빈백에서 편하게 스크린으로 케이팝 감상🎵 ◽️8층. COFFEE-ORDER 음료와 맛있는 디져트 주문🍰 ◽️9층. ROOFTOP-DJ 홍대 레드로드를 한눈에! 전망 굳🩵 강츄!', 45, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '3층부터 8층까지 엄청 큰 대형 카페예요 메뉴도 다양하고 다쿠아즈도 판매하는데 맛이 여러가지라 맛보기도 좋았고 진짜 맛있고 달아서 완전 제 취향저격이였습니다 ㅎㅎ 음료수는 자몽에이드를 시켰는데 자몽청이 많이 들어있어서 만족스러웠어요 층마다 테마가 달라서 구경하는 재미까지 좋은 시간 보냈습니다 ㅎㅎ', 21, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '각 층마다 다른 컨셉으로 인테리어 되어있는 이색카페입니다 디저트도 모두 맛있고 분위기가 좋아서 친구나 가족,동료와 같이 즐기기 좋은 카페에요!! 쾌적하고 넓은 공간에 깔끔하기까지해서 인기가 정말 많아용 상상거리에 이런 대형카페가 생기니 좋네요🩷 메뉴 종류도 많아서 선택의 폭이 넓고 직원분들 모두 친절하시기까지 합니당ㅎㅎ 각 층마다 반납대와 화장실까지 완비!! 완벽했어용 각종 행사도 많이 하는 카페인 것 같더라구요~~ 다음에 또 방문하겠습니당', 29, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '아니 여기인테리어도 예쁜테 커피 디저트까지 맛있으면 어쩌자는건지~!!>.<!! 아메리카노 원두가 신선해서 크레마도 가득하고 꼬소한 맛이에요!! 딸기생크림은 기본으로 맛있는데 에그타르트도 계란비린내안나고 달달하고 고소해요!! 인테리오도 예뻐서 단체석 커플석 많아서 좋아요!', 48, 2, 'GOOD', SYSTIMESTAMP);
