INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '디저트 맛집답게 케이크 종류가 진짜 다양해서 좋았어요!! 테마별로 꾸며진 넓은 공간 덕분에 사진도 많이 찍고 시간 보내기 좋았습니다ㅎㅎ 케이팝을 좋아한다면 7층 케이팝 미디어 공간 완전 추천해요👍', 55, 11, 'GOOD', SYSTIMESTAMP);
