INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '하나가 통으로 카페라 각 층마다 테마 다르게 즐길 수 있는게 좋아요🥹 분위기도 좋고 여기만 돌아도 시간 순삭이라 놀러오기 딱 좋은 것 같어요... 그리고 디저트가 미쳤어요 다쿠아즈랑 케이크는 꼬오옥 먹어야함', 24, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '앞으로 친구들 한번씩 홍대카페 데려오려고 합니다ㅋㅋㅋ 진짜 처음오는 사람들은 다 눈이 휘둥그레해질만한 곳이에요!! 남친 여친 친구 부모님 누구랑 와도 다 좋아할만한 곳이에요👍👍', 13, 1, 'GOOD', SYSTIMESTAMP);
