INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '카페가 너무 크고 넓고 쾌적해요. 길가다가 들어왔는데 더위 식히기 최고에요. 다음에도 홍대오면 또 편하게 들릴거같아요. 층층마다 컨셉달라서 보는 재미도 있어요~!', 30, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '카페 층수도 많고 각 층마다 컨셉이 다양해서 즐기기 좋았습니당! 사진 찍기도 좋고 메뉴 종류도 많아서 맛있게 먹고 시간 보내고 왔어요 만족스럽습니당☺️', 5, 3, 'GOOD', SYSTIMESTAMP);
