INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '홍대 상상마당 근처에 이런 대형카페가 있었다니…!!ㅎㄷ카페는 음료 한 잔으로 8개 전층을 모두 자유롭게 이용할 수 있고, 각 층이 전시관, 음악룸, 식물관, 루프탑 등 테마별로 꾸며져 있어 머무는 재미가 쏠쏠해 데이트 장소로도 안성맞춤! 딸기라떼랑 케이크 맛도 휼롱합니다! . 감성 카페 찾는 분들께 강추!', 29, 8, 'GOOD', SYSTIMESTAMP);
