INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '8층카페도 처음 가보는데 신기했고 층마다 컨셉이 다달라서 구경하는 재미도 있고 분위기도 너무 색달라서 좋았어요 ㅎㅎㅎ 초코올라간 케이크 두종류 먹었는데 딸기가 너무신선해서  짱맛잇어요!!👍🏻', 58, 14, 'GOOD', SYSTIMESTAMP);
