INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '1층부터 9층까지 한 건물이 카페인 대형 카페였어요! 각 층마다 컨셉도 달라서 취향에 맞는 층에서 즐기다가 다른층에서도 놀고 했어요 ㅋㅋ #실내데이트 하기 딱 좋은 곳이었답니다!! 여기 케이크 종류 디저트 찐 맛집입니당!!', 45, 7, 'GOOD', SYSTIMESTAMP);
