INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), 'ㅎㄷ 카페는 일단 규모가 어마어마 하고 층마다 컨셉이 달라 보는 재미가 남달랐고 아이스커피가 진짜 맛있었습니다. 종업원들도 친절하셨습니다.', 4, 7, 'GOOD', SYSTIMESTAMP);
