INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '홍대에 대형카페가 있는줄 몰랐어요 층마다 다른 테마에 이야기하기도 좋고 지인,가족,연인끼리 같이 즐기기 좋은 카페에요 💛💛너무 재미있고 즐겁게 놀다가 갑니다 또 방문할게요 힐링하는 공간이 많고,서울 홍대에 이렇게 넓은 카페가 있어서 좋네요', 72, 13, 'GOOD', SYSTIMESTAMP);
