INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '여기 진짜 너무 좋은데요! 홍대 갈때마다 들리게 될 거  같아요. 층마다 분위기도 다 다르고, 넓고 깨끗... 디저트도 고급지고, 맛있었어요^^', 13, 6, 'GOOD', SYSTIMESTAMP);
