INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '인스타 보고 온 카페 8층 각기 다른 컨셉 충분히 즐기러 평일 방문했는데 분위기 너무 좋고 에그타르트도 너무 맛있어요~ 다른 층도 전부 돌고 가면 여기만 와도 볼거리 가득 재방문의사 있어요', 0, 1, 'GOOD', SYSTIMESTAMP);
