INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '홍대에 대형카페 생겨서 방문했는데 엄청크고 자리도 많고 층마다 테마가 있어서 볼거리도 많고 자리도 편합니다ㅎㅎ음료 가격도 동네카페 가격대라 가성비좋습니다! 앞으로 홍대올때 자주 방문할것같아용🥰', 7, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '홍대 한복판에서 근교 대형카페의 쾌적함과 분위기를 느낄 수 있어요. 8층 건물의 층마다 테마가 다 달라서 구경하는 재미도 있고, 빈백 쿠션에서 편하게 쉬다 보니 시간 가는줄 모르고 있을 수 있었어요. 커피 맛도 기대 이상으로 맛있어서 아주 만족스러웠습니다.', 10, 4, 'GOOD', SYSTIMESTAMP);
