INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '여기 때문에 홍대를 방문한다고 해도 과언이 아닌것 같아요ㅎㅎ 디저트도 너무 맛있고 카페 구경도 너무 재밌어서 시간가는줄 몰랐어요! 특히 에그타르트 완전 강추입니다!! 너무 맛있어요! 다음에 재방문 의사 200%입니다ㅎㅎ', 7, 1, 'GOOD', SYSTIMESTAMP);
