INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '음료가격은 좀 비싼 것 같지만 디저트는 다른 카페와 비슷해요. 전층을 이용할 수 있는게 신기하고 재밌고 케이크 메론소금빵 다 너무 맛있게 먹었어요', 28, 1, 'GOOD', SYSTIMESTAMP);
