INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '우선 공간이 넓고 케익도 맛있어요 딸기가 사이사이 있으니까 더맛남 여러층 구경하느라 시간 잘가구요 사장님 잘생기시고 친절하세요 랩타일 전시도 좋았어요!!', 24, 10, 'GOOD', SYSTIMESTAMP);
