INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '우와 홍대에 이렇게 크고 이쁜 카페를 이제야 알았다니! 층마다 테마가 달라서 너무 신기했어요 너무 이뻐요 ㅠㅠ 어딜가나 진짜 포토존 그 자체! 인생샷 건지고싶으면 바로 달려가세요!! 커피, 디저트도 너무 맛있어요 하루종일 놀아도 너무 재밌고 시간가는줄 몰랐답니다 홍대카페 완전 강추에요 재방문의사 2만프로!', 30, 9, 'GOOD', SYSTIMESTAMP);
