INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '층마다 컨셉이 다른 대형카페라서 구경하는 재미도 있고 케이크도 맛있어서 너무 행복해써요😘 4층 파도 보는것도 좋고 6층은 노래도 잔잔하고 책상, 의자도 편해서 공부하기에도 좋었어여ㅎㅎ', 71, 12, 'GOOD', SYSTIMESTAMP);
