INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '평소에 잘 볼수없는 식물이 가득있는곳 커피 가격은 비싼편이고 의자가 좀 편안하면 더 좋았을듯 이색카페로 방문해보기는 나쁘지 않음', 116, 24, NULL, SYSTIMESTAMP);
