INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '포슬포슬하고 너무 맛있어요 딸기도 달달하니 넘 좋더라구요. 생크림도 고급스러운 맛! 재료에 아낌없이 넣은게 느껴져요 테이블마다 신경써서 조명이 사진도 잘 나오는게 되는것 같아요. 아메리카노도 맛있었어요.', 117, 25, 'GOOD', SYSTIMESTAMP);
