INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '더블초코케이크가 진짜 기가 막히게 맛있어요..🤤🤤 층마다 컨셉이 다 달라서 원하시는 컨셉의 공간에서 시간 보낼 수 있는 게 제일 큰 장점인 것 같답니다 구경하느라 진짜 지루할 틈이 없음..// 건물 구경만 해도 재밌어용 전시장이랑 공연장도 있다는 게 제일 신기햇어요.. 🫰🏻🫰🏻🧡', 41, 5, 'GOOD', SYSTIMESTAMP);
