INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '정말 넓고 다양한컨셉이 예쁜 카페였습니다. 루프탑에 올라가면 홍대가 다 내려다보이고 커피, 디저트도 다 맛있었어요! 추천합니다 :)', 13, 1, 'GOOD', SYSTIMESTAMP);
