INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '지하 1층부터 8층까지의 대형카페이다 보니 층마다 테마가 다양한 이색카페더라구요♡ 디저트와 음료도 너무 맛있고 포토존이 많아서 대만족했습니다!!', 76, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '이 건물 전체가 ㅎㄷ카페꺼라니요 ㄷㄷ 사장님 억만장자이신듯,,, 건물이 언청 크고 고급져보여서 들어와봤는데 가격이 당연히 비쌀거라 생각했는데 가격도 작은 카페들보다 싸네요....? 이정도면 요기서 안먹을 이유가 없는거같아요 심지어 시그니처 음료들이랑 케이크 시켜봤는데 다 너무너무 맛있음... 홍개카페로 진짜 강추입니다', 87, 14, 'GOOD', SYSTIMESTAMP);
