INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '카페에서 하루종일 있어도 좋을 정도로 다양한 테마가 있어서 좋아요 ㅎㅎ 1층부터 8층부터 다양한 테마가 있는데 저는 4층 물멍이 제일 좋았답니다', 49, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '매장이 넓고 단체석도 각 층마다 여유있게 배치되어있어서 쾌적하게 이용했습니다. 각 층마다 컨셉이 다양해서 층별로 다양하게 즐길 수 있던 카페였습니다. 방문 시에도 단체 손님이 많았고 그만큼 쾌적할정도로 단체석 여유가 많았습니다. 매장은 청결함이 높은상태로 유지되고있었고 메뉴들도 너무 맛있었습니다. 개인적으로 7층의 빈백이 있던 카페홀이 제일 맘에들었습니다.', 48, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '기대한 것보다 더 멋진 공간과 감성으로 가득한 홍대카페! 홍대의 아이덴티티를 느낄 수 있는 복합문화공간이라 홍대가 어떤 곳인지 알고 싶다면 여기부터 오셔도 될 것 같아요 커피랑 케이크도 존맛!', 18, 4, 'GOOD', SYSTIMESTAMP);
