INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '워낙 대형 카페라 지나다니면서 많이 보다가 처음 들어왔는데, 디저트가 맛있어요! 초코케이크, 딸기생크림케이크 추천드립니다. 다쿠아즈도 맛있게 잘 먹었고 다음엔 타르트도 먹어보려구요. 공간이 넓어서 쾌적하고 얘기하기도 좋아요!', 56, 12, 'GOOD', SYSTIMESTAMP);
