INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '층마다테마도있고 날좋은날 루프탑올라왔는데 분위기너무좋아요 데뚜하기도좋고 홍대가 다 보이네요 케익도 맛있는 생크림이라 맛있네요. 굿굿', 35, 5, 'GOOD', SYSTIMESTAMP);
