INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '홍대 중심에 이런 대형카페가 있다니 공간 층마다 느낌이 다른 컨셉이 다양하게 있어서 좋았고 음료랑 디저트는 당연히 맛있어서 사실 카페 여러곳갈필요없이 여기에서 다양하게 즐기기 좋을 것 같아요', 26, 7, 'GOOD', SYSTIMESTAMP);
