INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '층 마다 다양한 전시를 보는 느낌이에요! 특히 엘피바도 있는 6층도 이쁘고 아예 식물원을 옮겨놓은듯한 3.4.5 층까지 댖박입니다 ! 음료랑 디저트도 맛있어요 🩷', 19, 2, 'GOOD', SYSTIMESTAMP);
