INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '8F에서 주문하고 특색있는 다양한 공간에서 휴식을 취할 수 있는 멋진 대형카페네요^^ 분위기도 좋고 케이크도 에그타르트도 너무 맛있어요!', 20, 3, 'GOOD', SYSTIMESTAMP);
