INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '홍대 한복판에 이렇게 큰 규모의 카페 찾기 쉽지 않은데 너무너무 좋은곳을 발견했습니다! 루프탑맛집, 뷰맛집, 디저트맛집, 인테리어맛집이에요!', 55, 15, 'GOOD', SYSTIMESTAMP);
