INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '와 매장이 진짜 넓어요 테이블수도 많아서 단체로와도 부족함이 전혀 없어요! 층별마다 테마가 달라서 구경하는 재미도 있고 취향인곳 골라서 쉴수 있는게 정말 좋았어요 딸기 케이크 진짜 맛있네용 ㅋㅋㅋㅋ', 23, 5, 'GOOD', SYSTIMESTAMP);
