INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '맛있는 음료, 넓찍한 공간, 층별 다른 컨셉의 인테리어까지,, 사진 실컷 찍다 왔습니다! 에그타르트 ㅈㅁㅌ이에요 홍대에 요런 곳 있는 줄 몰랐는데, 다음에 또 올게요!', 27, 9, 'GOOD', SYSTIMESTAMP);
