INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '친구와 함께 방문한 ㅎㄷ카페! 8층 전체가 카페인줄은 몰랐는데 규모에 깜짝 놀랐어요! 층마다 다른 테마로 인테리어가 되어있고, 사람이 많이 있는데도 테이블간 간격이 넓어 대화하기도 좋아요~ 다양한 디저트류와 커피, 음료도 맛있네요~ 홍대 오면 카페 자리 찾기도 쉽지 않은데 넓은 좌석에서 편안히 대화나눌 수 있어서 다음에 또 오고싶어요~', 48, 3, 'GOOD', SYSTIMESTAMP);
