INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '딸기라떼랑 치즈케잌 너무 맛있어요~ 치즈케잌이 수플레 스타일이라 폭신하고 부들부들 진한맛나여 7층에서 누워서 핸드폰하니 편하고 넘 좋아여 홍대에서 이런 곳이 있는줄 왜 인제 알았쥬', 482, 79, 'GOOD', SYSTIMESTAMP);
