INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '커피 맛집입니다 1잔 마시고 1잔 더 마신 곳은 여기가 처음이네요 분위기도 좋아요 . 가족들과 함께 왔는데 모두 만족한 장소입니다', 46, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '홍대 한복판에 등장한 대형카페🌴 일요일 오후 2시 8층에서 음료 및 디저트 주문 후 루프탑부터 한 층 한 층 내려가면서 둘러봤는데 층마다 다른 인테리어에 감탄만 하고 갑니다 ,, *맨 처음 사진부터 순서대로 RF -> 3층 모임이나 친구, 가족끼리 와도 좋을 듯하지만 혼카페로도 정말 추천드려요 *LP 좋아하시는 분들은 6층☺ 각기 다른 공간도 정말 좋지만 디저트랑 음료도 맛깔납니다 에그타르트 정말 겉바속촉이고 다쿠아즈도 맛있어용 특히 아아는 산미도 없어요! 레드리치 아이스티는 아이 어른 할 거 없이 다들 좋아하실 맛입니다😊', 50, 9, 'GOOD', SYSTIMESTAMP);
