INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '음료와 디저트 모두 다 맛있어요 :) 무엇보다 카페 층마다 분위기와 인테리어가 달라서 누구와 왔는지에 따라 취향에 맞게 골라 앉을 수 있어서 정말 좋은 것 같습니다☺️ 매장도 너무 청결하네요 !', 16, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '홍대에 이런 카페가 있다니~~ 분위기 너무 좋아요^^ 날씨 좀 따뜻해지면 루프탑에서 마셔야겠어요 지인들이랑 왔는데 연인이랑 오기 너무 좋은 분위기예요', 67, 12, 'GOOD', SYSTIMESTAMP);
