INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '휴가인 신랑이랑 카페데이트 동네대형카페 자주 가다가 오랜만에 홍대나들이~ 인테리어가 너무 멋지네요~~8층까지 이곳저곳 구경할것 많아서 데이트하기 좋아요^^', 19, 10, 'GOOD', SYSTIMESTAMP);
