INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '분위기가 너무 좋아요. 초코 생크림 케이크도 달달하니 맛있고 다쿠아즈도 사장님이 추천해주신 레몬 요거트 맛있네요!! 홍대에서 이렇게 크고 아늑한 카페는 오랜만이예요. 전시공간같고 너무 좋아요.', 17, 7, 'GOOD', SYSTIMESTAMP);
