INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '홍대에 이렇게 대형 카페가 생긴지 몰랐네요! 다양한 음료와 디저트 메뉴 뿐만 아니라 복합문화공간으로 다양한 전시, 공연 심지어 서울패션위크 패션쇼도 진행하는 장소라니! 다양한 미디어 아트와 열대식물까지 8층 건물이라 홍대 여행 필수 코스로 ✅👍', 1, 2, 'GOOD', SYSTIMESTAMP);
