INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '🍓홍대에서 1티어 카페🍓 총 8층으로 구성되어있는데 각층마다 개성이 뚜렷하고 디저트맛에 치인다.. 근데 원두도 비싼거 쓰시는것같다 커피가 잔향이 많이 느껴지고 산미가 좋았다🍓', 26, 1, 'GOOD', SYSTIMESTAMP);
