INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '잘 먹고 잘 쉬다 갑니당 공간 대여 했다 생각하고 오면 좋을듯 사람 없어서 에어컨 안틀어준 곳들 있으니까 참고하길 공간 자체로는 매력적이고 맘에들었음 케이크 노맛', 48, 2, 'BAD', SYSTIMESTAMP);
