INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '분위기도 좋고 음료랑 디저트도 생각한거보다맛있어요!보통 이런데는 기대안하는데 맛있어요! 다만 주문하고 앞에순서가꼬였는지 많은사람들이 오래기다리더라고요', 64, 16, NULL, SYSTIMESTAMP);
