INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '딸기생크림케이크 두가지 종류 너무 부드럽고 촉촉하고 맛있어요~~ 딸기라떼 초코라떼도 달달하고 진해서 행복했어요 당땡길때 안성맞춤~👍🏻⭐️💕 뷰도 너무 좋고 층마다 분위기 너무 좋아용 ~~', 3, 9, 'GOOD', SYSTIMESTAMP);
