INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '각 층별로 다른 컨셉이 너무 재밌고 좋아요! 다른 카페를 6곳 방문한 것처럼 느낌도 다르고 사진찍는 맛이 있습니다 ㅎㅎ 커피도 맛있고 디저트도 달달해요!💗 최애는 LP바 였습니다 :)', 59, 11, 'GOOD', SYSTIMESTAMP);
