INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '8층으로 이루어진 홍대 대형 카페! 각층의 테마 구경하느라 시간 가는줄 몰랐네요 ㅎㅎ 시원한 물소리가 나는 4층이 제 원픽이였습니당 :) 다음에도 또 이용하러 올게요 💕', 20, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '방문 처음 했는데 직원 진짜 불친절하고 커피 좋아하는데 따뜻한 아메리카노 시켰는데 투샷이라고 하는데 아무맛도 안나고 그냥 따뜻한 물 맛만 나서 직원한테 말하니깐 ''커피 맛 나는데요?'' 대체 뭐가 문제죠? 라듯이 쳐다 보면서 말하네요. 그리고 저희 번호 누락 되었다고 하는데 직원 포스기 사용도 미숙하고 한시간 기다려서 물어봤는데 누락. 죄송하다는 말 한마디도 없이 기다려달라고만 말하고 끝이네요. 커피 진짜 맛없고 서비스 진짜 불친절. 두번 다시는 안 갈듯요. 원두향 1도 안나는 6,500원 커피 다시 만들어 주셨긴했는데 3샷으로 맛 똑같고 어떤 원두를 쓰는지도 모르겠고 원두 갈리는 소리도 안 나고 그냥 무맛. 자존심만 쎄고 인정없는 카페 처음이네요^^~ 장사 잘 하세용!!', 117, 20, 'BAD', SYSTIMESTAMP);
