INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '뷰는 좋습니다. 케이크가 너무 작고 음료도 그냥 그냥 뷰 보면서 먹기 좋은곳,, 케이크 크기보고 저게 7500원이야?? 했음 ㅎㅎ', 3, 8, NULL, SYSTIMESTAMP);
