INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '층마다 다른컨셉이라해서 무척 기대하고 갔는데.. 헉~~ 왜 다들 8층에만 있지? 어쩐지~😥 이렇게 더운데 8층외엔 에어컨이 다 꺼져있었어요~~ 평일이라 그랬나? 덕분에 3층이랑 루프탑.. 포기했네요~~ 아쉽아쉽~~', 24, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '홍대 오래간만에 나와봤는데, 이렇게 큰 카페를.. 8층에서 주문먼저..글고 둘러보는.. 커피 맛있네요.. 모카커피 넘 달달^^*', 35, 7, 'GOOD', SYSTIMESTAMP);
