INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '좌석 진짜 많고 실내 데이트 장소로 최고인 듯 포토스팟 많고 층층마다 구경하고 사진 찍으면 시간 순삭! 바닐라라떼 맛있음👍 재방문의사 완전 있음!!!', 1, 6, 'GOOD', SYSTIMESTAMP);
