INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '상수, 홍대쪽 놀러오시면 무조건!!ㅎㄷ카페 방문해보세요!!진짜 대박적💟여기 어디서 찍어도 사진 다 잘나오고 디저트부터 커피까지 다 맛있어요!!다쿠아즈 꼭 시켜서 드셔보세용💟 8층까지 있고 심지어 루프탑까지 있어요ㅠㅠ🙆‍♀️🙆‍♀️', 37, 5, 'GOOD', SYSTIMESTAMP);
