INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '음료 디저트 다 맛있고 테마가 다양해서 구경하는 재미도 있고 데이트하기 딱이에요🔥 날 풀리면 루프탑 가서 커피 마시고 싶어요~!~!', 110, 26, 'GOOD', SYSTIMESTAMP);
