INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '음료 한잔 주문으로 층마다 다른 컨셉 구경하고 좋네요^^ 음료 &다쿠아즈 맛도 좋고 직원분들도 넘 친절~ 음악까지 좋고~ 젤 맘에 드는 3층에 자리잡고.. 아무도 없어서 편하게 이야기도 하고 좋았어요~ 갤러리가 그림이 바뀌는지 궁금하네요..^^ 화장실 층마다 있어 좋은데 가방걸이 있음 좋을듯 싶어요~', 37, 0, 'GOOD', SYSTIMESTAMP);
