INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '커피나 디저트의 퀄리티를 생각하면 가면안되는곳이라 생각합니다. 기성품에 오토머신, 커피맛은 밸런스가 아예없어요. 8층이라 홍보가 너무많아서 심심해서 다녀왔는데 인테리어가 그냥 돈만 쓰고 디테일이나 이런건 하나도없어서...금방 사라지겠구나싶네요. 오픈한지얼마안된거같은데 화장실청결도 관리안되고요.', 15, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '이런 멋진 카페가 있었나~!깜놀! K-MEDIA LP-MUGIC GALLERY STONE VALLY PLANT 각층마다 다른 컨셉의 카페 지루할틈이 없으며 사진 찍기도 좋아요 추운겨울날  실내에서 멋진하루~~!', 68, 15, 'GOOD', SYSTIMESTAMP);
