INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '우연히 들린 카페 크고 좋네요.. 음료를 주문하면 전층 구경이 가능하다고 하고 아이들은 구경하러 가고…신랑과 잠시 쉬는 중 리본 크로와상 너무 맛있네요… 안에 무슨 크림일까요…너무 너무 맛나서 지금 하나 더 사먹어야 하나 고민 중이에요…ㅎㅎㅎ 다음에도 홍대 온다면 다시 올 꺼임요', 4, 9, 'GOOD', SYSTIMESTAMP);
