INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '감성도 좋고 케이크도 달달해서 엄청 맛있어요ㅎ.ㅎ 친구들이나 가족끼리도 오기 진~짜 좋을 것 같아요 음료 종류도 다양하고 케이크도 다양해요', 56, 16, 'GOOD', SYSTIMESTAMP);
