INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '서울에  있는 8층 대형카페. 커피도 맛있고 카페는 모던하고 차분하면서  심플한 인테리어였으며 갤러리에 방문한 느낌이예요. 굿', 22, 0, 'GOOD', SYSTIMESTAMP);
