INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '상상마당 바로 앞에 있어서 찾기 쉬웠어요ㅎㅎㅎ 컨셉별로 층마다 달라서 안에 볼거리도 많고 시간가는 줄 몰랐네요 ㅎㅎ3층 식물관에 들어서자마자 식물냄새 나서 힐링되는 느낌이고 굿굿!!👍🏻 사장님이 식물등까지 쓰셔서 애지중지하며 식물 키우신다고 하네요~ 다들 힐링하러 방문해보세요!!ㅎㅎ', 85, 18, 'GOOD', SYSTIMESTAMP);
