INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '8층이나 되는 대형 카펜데 층별로 테마가 달라서 거의 테마파크온 줄 알았어요… 이 돈 내고 다 즐겨도 되나 싶은 정도.. 완전 최고였습니다!!👍💕', 11, 8, 'GOOD', SYSTIMESTAMP);
