INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '홍대 여행중에 발견한 홍대카페  8층에서 커피를 주문하면 전 층을 다 둘러볼수있다는  신박함에  중학생 아이들과 함께 들렀는데 커피도 너무 맛있고 분위기도 너무 좋앟답니다 엄마아빠가 커피마시는 동안  다른층 구경에 신나아이들 커피마시러와서 좋은 경험하고 갑니다~^^', 34, 7, 'GOOD', SYSTIMESTAMP);
