INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '층 마다 컨셉이 다양해서 보는 재미가 있어요 사장님께서 식물을 좋아하시는지 대부분의 공간에 식물이 배치되어 있던데 이것도 감성적인 느낌이 나서 예쁘더라구요 조명빛도 은은해서 더 무드있었습니다 그래서인지 사진도 더 예쁘게 나온 것 같아요ㅎㅎ 날이 추워서 루프탑은 못 가봤지만 봄가을엔 야경을 봐도 예쁠 것 같고 밖에서 커피를 마셔도 좋을 것 같아요 층 마다 시간 가는 줄 모르고 구경했네요 다음에 또 오고 싶어요~', 45, 4, 'GOOD', SYSTIMESTAMP);
