INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '각층마다 테마가 다른 카페에요. 전망을 볼수 있는 루프탑부터 공연을 볼수있는 스테이지까지 음료한잔으로 8층까지 이용가능해서 좋습니다!', 36, 8, NULL, SYSTIMESTAMP);
