INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '홍대 대형카페 ㅎㄷ카페!!! 건물이 통으로 카페라서 완전 신기했어용 층마다 다른 분위기도 마음에 들고 ㅎㅎ 혼자 방문해도, 둘이 방문해도, 단체로 와도 좋을 듯!', 59, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '홍대에 대형카페 찾으시는분들이라면 여기에 다 모이셔요~ 1-8층까지 있고, 각 층마다 컨셉이 다양하게 있어요. 케이팝미디어, Lp뮤직, 갤러리,식물관 등이 있어서 구경하기도 좋더라구요. 그리고 공간도 공간이지만 카페 음료와 디저트도 맛도리에요🧡🧡', 33, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '단언컨데 카페 중에서는 전국 제일의 규모를 자랑하는 매장입니다. 층층별로 테마가 있는 인테리어와 소품들을 설치하여, 색다른 환경에서 쉴 수 있도록 배치하였습니다. 저는 개인적으로 k팝이 나오는 위층이 마음에 들었습니다. 이곳은 누울수도 있고. 너무 자리가 편하여 특히 여름에 쉬고 가기에는 그만인 곳입니다. 아울러 대형 선인장이 나오는 플랜트 층, 아름답게 꾸민 돌이나오는 스톤 층 등도 인상적이었습니다. 너무 특이하고 재미있는 곳이라, 홍대 쪽으로 오면 꼭 들려야할 곳 같습니다~ 저도 다음에 이촉으로 오면 이곳을 또 꼭 들릴거 같네요', 10, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '직원분들도 친절하시고 매장이 넓고 깔끔하며 시원하고 인테리어가 너무나도 이뻐요~ 루프탑 옥상 경치가 홍대가 한눈에 다보여서 너무 좋습니다~!', 43, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '홍대 카페는 도심 한가운데에 있는 보석 같은 곳입니다. 5층에서 예술적인 분위기에 젖어 풍부한 아메리카노를 즐겼습니다. 평화롭고 조용한 오후를 보내기에 좋은 곳입니다.', 40, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '층별로 테마가 달라서 즐거웠던 곳! 음료도 너무 맛있어요:) 특히 KPOP존은 빈백이 있어서 누워서 사방에서 나오는 뮤비를 감상할 수 있답니다! 다음에는 다른 층도 이용해볼 예정이에요💕 재밌는 데이트 코스 찾는다면 추천입니당', 35, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '홍대카페 ~kt상상마당을 마주보고 있네요~홍대.신촌상권에서 접근성이 좋고 건물이 통으로 되어있는 복합문화공간? 카페라 좋았어요! 옥상에 루프테마가 있는데, 계단을 오르기엔 날씨가 너무 더워서..ㅎㅎ"~ 좋았던 점은? 각 층마다 테마가 있어서 어느 층으로 갈까? 고민하게 되었네요. 각층마다 에어컨이 시원하게 나오네요! 저희는 7층 (k팝미디어)로 선택! 근데, 와!! 빈백도 널널하고, 더운날 눕기 좋아서 신났어용~영화관보다 편하네여~ ㅇ음료도 다양하게 있어욤! 코코넛 라떼 궁금해서 주문해봤는데 맛 좋아요~엘베로 원하는 층 내려갈땐? 문닫힐때 트레이가 안끼도록 주의하셔서 내려가세요!! 저희남편이 트레이 들다가 문에 끼어서 그만 제 코코넛라떼를 다 엎질렀어요...ㅜㅜ 홍대카페 접근성도 좋고 더운날 쉬어가기 좋아용', 1, 5, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '카페 깔끔하고 넓게 인테리어 잘 해서 좋네요:) 다룬 층도 가봐야겠어요😃 사이드에 있는 식물은 조화인줄 알았는데 생화였어요 ㅎㅎ 홍대 올 때 방문할 거같아요 딸기테린느 꾸덕하니 맛있습니다! 소금 다쿠아즈도 추천👍', 6, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '꼭 와보고 싶었는데 드디어 왔네요 ㅎㅎ 층마다 컨셉이 달라서 볼거리가 많은게 너무 좋네요 카페를 온 건지 갤러리를 온건지 헷갈릴 정도로 시간가는 줄 모르고 있게됩니다:) 커피도 맛있고 자리도 편하고,,  앞으로 자주 찾을것같아요~ 굿굿', 17, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '홍대 자주 가는데도 이런 카페가 있는지 몰랐어요. 건물 자체가 다 카페인데 층층마다 컨셉이 달라서 어 둘러보는 재미가 있고  너무 신선했어요.  그리고 루프탑에는 홍대 전체가 다 보이는 시원한 뷰여서  봄이나 가을에 오면 너무 좋을 것 같고 음료와 디저트도 맛있었어요', 21, 5, 'GOOD', SYSTIMESTAMP);
