INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '친구랑 방문했는데 내부도 매장 깨끗하고 인테리어도 예뻐요. 게다가 8개 층을 전부 사용할 수 있어서 좋구요. 코코넛 라떼는 고소하니 맛있어요.', 32, 5, 'GOOD', SYSTIMESTAMP);
