INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '홍대 오랜만에 놀러왔는데 상상마당 쪽에 큰 카페 보여서 들어와봤어요! 카페도 되게 넓고 인테리어도 예뻐요! 커플이나 친구끼리 와도 되게 좋을거같아용ㅎㅎ 커피랑 케익도 짱 맛있습니닷!ㅎㅎ 홍대 놀러오시는 분들께 추천드려용!!❤️', 109, 21, 'GOOD', SYSTIMESTAMP);
