INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '지인들이 다 좋아했어요 LP바 진짜 좋습니다  음향도 좋고 분위기도 짱이에요 다른층들도 다.좋아요 식물들도 생화고 큰 선인장도 이뻐요 특히 루프탑 올라가면 건물들이 다 내려다보이는데 정말 좋아요 홍대에 이런 곳이 있는 줄 몰랐네요 나중에 혼자 오고 싶을 정도에요', 29, 2, 'GOOD', SYSTIMESTAMP);
