INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '홍대에 생긴 8층짜리 대형카페! 층마다 색다른 인테리어로 분위기있네요 데이트하기 완전 좋고 음료랑 디저트도 넘나리 맛있는거ㅎㅎ', 55, 16, 'GOOD', SYSTIMESTAMP);
