INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '각 층마다 화장실 있어서 너무 편해요. 6층이 특히 데이트하기 좋아요. 등받이가 있어서 너무 편하고 노래가 적당해서 옆자리 사람들이 내 자리에서 뭐라고 떠드는지 들리지 않아요.', 50, 10, 'GOOD', SYSTIMESTAMP);
