INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '근처 카페 다 꽉찼는데 여긴 8층까지 있어서 자리가 넉넉하니 너무 좋네요 커피도 깔끔하고 매장고 청결해서 이쪽오면 여기로 다시 방문하고 싶네요 홍대 카페 1등!!', 29, 7, 'GOOD', SYSTIMESTAMP);
