INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '딸과 홍대 데이트하며 들른 홍대카페~연령대가 다양하고 음료도 맛있고 친절하네요! 커피마시며 전층을 즐기는 멋진곳이예요~ 음료값이 갤러리 입장권이라 생각하면 좋을것 같아요', 6, 4, 'GOOD', SYSTIMESTAMP);
