INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '매장이 8층 까지 있어서 홍대에서 카페 가야할때 좋은 옵션이 될 거같아요 매장도 넓고 음료도 맛있습니다 쾌적하고 실내에 화장실도 있어서 좋아요 😀', 19, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '올초 방문하고 너무 좋아서 재방문했어요. 독특한 컨셉도, 평온한 분위기도, 친절한 직원분들까지… 종종 오고 싶은 곳이에요 ^^ 특히 6층 최고!ㅋ 오렌지아메리카노 너무 맛있어요ㅎ', 59, 17, 'GOOD', SYSTIMESTAMP);
