INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '맨날 지나다니는 거리인데 카페가있는줄몰랐어요! 이렇게 크고좋은카페가있었다니🥹 앞으로 홍대오면 여기 맨날올듯 뷰도넘좋구 짱커요 3층부터 9층까지 다카페!! 오렌지아메리카노 짱맛 오렌지주스에 2샷 추가한 맛인데 오렌지가 더진한 커피!!', 123, 23, 'GOOD', SYSTIMESTAMP);
