INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '무려 8층짜리 커피숍 ! 층별로 다양한 테마가 있는 홍대카페 넓고 쉬기 좋았어요 ! 특히 케이팝 미디어 존은 거의 누울수도있습니다 ㅋㅋㅋ 8층 루프탑뷰도 감상가능하고 ,, 데이트 하러 오기 좋을 것 같아요 !!', 72, 18, 'GOOD', SYSTIMESTAMP);
