INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '커피도 맛있는데 케이크도 너무 맛있고 분위기도 좋네요.다음에 또 여기 놀러올 것 같습니다.매장도 많이 넓어서 사용하는데 불편하지 않고 좋은데 층마다 구경할 것도 있어서 생각보다 더 재밌게 논 것 같습니다^^', 129, 21, 'GOOD', SYSTIMESTAMP);
