INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '엄청 쾌적하고 시원하고 넓고 더운 여름에 들어가서 쉬기 딱인 공간! 음료나 디저트도 다양하게 많아서 너무 만족하고 잘 쉬다갑니당~🥰😆', 40, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '원래도 인스타에서 유명해서 왔는데 매장이 완전 넓어요 그리구 음료만 구매해도 다른층들 다 사용할 수 있는데 식물구경 음악 듣기 LP판도 있고 갤러리도 있어서 구경하기 너무 좋아요!! 음료수도 맛있어요 특히 패션후르츠 추천해요 톡톡 잘 씹혀서 맛있습니다!! 데이트 목적으로 오시면 최고입니다', 7, 4, 'GOOD', SYSTIMESTAMP);
