INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '각 층마다 컨셉이 있는 대형카페가 있다고해서 홍대 온 김에 들렀어요~ 공간도 넓직하고 시원하고 음료도 맛있어요!! 테린느도 특이하고 맛있네요 홍대 카페 방문 추천드려욥', 64, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '카페가 커서 쾌적하고 전층을 쓰는거라 더 좋은 것 같아요! 매번 보기만하고 처음 와봤는데 오길 잘 한 것 같아요 ㅎㅎ 다음에 또 올게요!', 7, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '매장 규모가 홍대에서 역대급인거 같아요..!! 층마다 분위기도 달라서 새로운 곳에서 마시는 느낌이에요 무엇보다 커피 맛도 좋아서 홍대 올 때마다 자주 올 것 같아용', 24, 6, 'GOOD', SYSTIMESTAMP);
