INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '층별로 컨셉들이 다양해서 좋았어요!! 저는 개인적으로 6층이 제일 예쁘더라구요☺️ 조용하구 시원하고 재방문 의사 100퍼 입니다ㅎㅎ', 3, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '홍대에서 제일 넓은 공간을 가진 카페입니다! 여러 명이서 같이 오기도 좋고 각 층마다 다른 테마들을 즐기러 오기 좋은 것 같아요👍🏻', 35, 3, NULL, SYSTIMESTAMP);
