INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '매장이 엄청 넓어요! 8층에서 오더만 하면 전층 다 이용가능해서 좋은 것 같아요💖 음료도 장소대비 가성비 좋습니당:) 합리적잉 가격대고 맛도 괜찮아용', 37, 9, 'GOOD', SYSTIMESTAMP);
