INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '홍대진짜 자주오는데 현수막보고 놀라서 들어왔어여!!않이 8층짜리 카페라니 신상카페니 무조건 와봐야저!!! 더더 다음엔친구들 더많이 데려와서 수다떨어야겠어요😘😘', 45, 4, 'GOOD', SYSTIMESTAMP);
