INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '카페가 진짜 크네요 사람이 많은 것 같은데 층별로 분산되니 자리는 넉넉하더라구요 홍대에 대형카페는 마니 못본거 같은데 커서 아주 맘에 들어요 가격도 적당한듯 해요', 79, 15, 'GOOD', SYSTIMESTAMP);
