INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '매장이 넒어서 단체로 오기도 좋을거 같아요 ㅎㅅㅎ 사장님도 친절하시고 복합문화공간이라 카페오면서 여러가지 음식 구경도 할 수 있어서 일석이조!! 다쿠아즈도 여러종류 있어서 같이 드시면 좋을거같습당 :)', 86, 16, 'GOOD', SYSTIMESTAMP);
