INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '홍대에 건물하나 다 쓴다는 카페 있다길래 궁금해서 방문해봤는데 일단 음료랑 디저트 종류가 많아서 좋았어요 아아도 진해서 합격 층마다 컨셉이 달라서 머무르는 재미가 있네요👍', 30, 4, 'GOOD', SYSTIMESTAMP);
