INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '컨셉이 여러개 있고 층별로 나눠져있어서 ㅎㅎ 연인끼리 와서 사진찍기 좋은 곳 같아요! 역시 홍대 이름 달고 카페 하는데라서.. 야무지네요!! 👍🏻', 13, 10, 'GOOD', SYSTIMESTAMP);
