INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '음료도 맛있고, 다양하게 볼거리가 많아요! 8층에서 커피 주문하고, 밑으로 쭉 내려오면서 둘러보면 딱이에요! 엄청 크고 넓어서 자리도 많아요! 홍대오면 카페는 항상 여기로 옵니다 ㅎㅎㅎ', 1, 9, 'GOOD', SYSTIMESTAMP);
