INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '음료도 너무 맛있고 공간을 잘꾸며놓으셔서 돈이 하나도 안아까웠어요! 계속 뭘 사먹어서 돈쭐 내고싶었습니다!!!! 최고 강추요!', 90, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '예전부터 와보고싶었던 ㅎㄷ카페! 드디어 홍대 온 김에 들렀어요 😘 분위기도 너무 좋고 가격도 좋고 친절해요~!!! 다음에 또 올게용 주변에 추천 많이할게요! 홍대 대표카페 ㅎㄷ카페 😍😍😍', 22, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '매장도 엄청 깔끔하고 층별로 컨셉이 달라서 너무 신기했습니다 :) 다쿠아즈도 완전 맛있어요 !!!! 재방문의사 100% 입니다 !', 52, 16, 'GOOD', SYSTIMESTAMP);
