INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '길 가다가 우연히 봐서 들어왔는데 매장이 너무 이쁘고 깨끗해요! 커피랑 딸기라떼 시켰는데 맛있습니다😆 8층까지 있어서 구경하기 좋은 것 같습니다~', 47, 7, 'GOOD', SYSTIMESTAMP);
