INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '어마무시한 홍대(ㅎㄷ) 카페. 음료한잔으로 8개 층의 복합문화공간을 이용할 수 있다. 케이팝미디어, 음악감상실, 미술전시장, 자연조경공간, 식물관, 공연장, 루프탑 야경까지. 여의도가 내려다보이는 야경이 죽인다.', 0, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '여러분.. 미쳤어요.. 이 카페… 찐 부자 건물주님의 냄새가.. 커피 한잔으로 홍대에서 느낄 수 없는 쾌적함과 층마다 컨셉 충만한 색다른 느낌을 받을 수 있어요!!! 3층 식물원도 정말 멋있고, 루프탑도 진짜 꼭꼭!!! 올라가보세요!!!!', 25, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '야경맛집에 층층이 테마가 있는게 너무 좋았어요✨✨ 홍대에 여기 안오면 아쉬울 정도로 너무 만족스러운 카페였구요, LP층에서는 한시간 멍 때리기 좋을 정도였어요! 널리널리 알아서 많이 왔음 좋겠어요😆😆 강추입니다!!', 58, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '홍대 카페 ㅎㄷ카페! 분위기가 너무 좋았어요! 한 건물을 통채로 쓰는 카페를 처음 방문해봤는데 8개 층 모든 층이 다 분위기가 있고 각 층마다 컨셉이 있어서 둘러보는 재미가 있더라구요! 비단 카페로서뿐만이 아니라 홍대 놀거리 찾으시는 분들도 방문하셔도 좋을 것 같아요💗 개인적으로 케이팝 뮤비가 미디어 아트처럼 전시되던 7층이랑 3층 식물원이 제일 기억에 남고 좋았어요🥺 그리고 커피 주문할 수 있는 8층도 자리가 넓고 손님들이 이용할 수 있는 공간이 많았는데, 조용조용한 분위기라서 친구랑 얌전히 수다 떨기에 너무 편안했던 곳! 다음에도 홍대 오면 또 방문하고 싶어요💗', 31, 6, 'GOOD', SYSTIMESTAMP);
