INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '홍대와 합정사이 KT&G 상상마당 건너편에 위치하며, 층별로 다양한 공간이 있는데 취향에 따라 조용히 혼자 커피와 음악을 즐기기 좋은곳이며, 시원한 루프탑에서 도심뷰 흠뻑 취할수 있는 매력적인 곳으로 홍대거리에서 휴식이 필요할때 방문하면 좋을듯하다~☆', 47, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '여긴 진짜 체고...😲‼️ 역대급으로 큰 홍대 루프탑 대형카페에요🩷 지하부터 9층까지 서울 최대규모의 복합문화공간이라 빵빵한 음질로 음악공연도 볼 수 있고 LP감상도 할 수 있었어용 ㅎㅎㅎ 짱....🎸🎧  홍대 놀거리 홍대 데이트 핫플 찾으시면 여기 무조건 방문필수에요!!!💯', 84, 18, 'GOOD', SYSTIMESTAMP);
