INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '코파카바나랑 아아 시켜서 구경도 잘하고 사진도 잘 찍었어요♡ 사진찍기 너무 좋은 곳이라 차 마시면서 구경하기 좋아요♡ 강추합니다♡', 35, 9, 'GOOD', SYSTIMESTAMP);
