INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '정말 오랜만에 고등학교 친구들이랑 홍대 나왔는데 우연히 발견해서 들어온 카페예요 커피 주문하고는 건물 전체를 이용할 수 있는 특별한 곳이네요', 37, 4, 'GOOD', SYSTIMESTAMP);
