INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '정신 없는 홍대에 이렇게 볼 것 많고 쉴 수 있는 복합문화공간이 생겼다니 너무 좋네요. 층마다 구경거리가 다양하고 여의도도 보이는 루프탑, 층간 계단에서는 홍대 거리도 보여요.', 479, 100, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '지인 통해서 알게 된 공간인데 넘 좋네요 ^^ 식물원이 따로 없어요~!!! 갤러리가 있어서 눈도 즐겁고 타임테이블별 아티스트들의 공연도 즐길 수 있는데다가 티켓 1장으로 자유이용권처럼 층층마다 구경하고 편한 곳에 자리잡고 즐기면 될 것 같아요 아티스트나 아트에 관심 있는 사람들의 아지트가 될 것 같네요 :)', 87, 11, 'GOOD', SYSTIMESTAMP);
