INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '1층부터 9층 루프탑까지 한층한층 너~무 예쁜공간들있어요! LP판으로 음악을 들을수있는공간도있고, 사진찍기 좋아하시는분 오시면 취저할 ㅎㄷ카페♡ 지하에서 공연도 볼수있고 보고 즐길거리가 많아서 데이트 하기 좋을것 같아요!!🥰 홍대 데이트코스로 극추천합니다:)♡', 127, 24, 'GOOD', SYSTIMESTAMP);
