INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '아주 만족스러워요!! 커피마시면서 구경하기 딱!좋고 층마다 컨셉이 달라서 아주아주 즐기기 좋아요~ 저는 특히 선인장컨셉층이 아주 맘에 들더라구요!! 힐링되는 공간도 있고 공연도 볼 수 있고! 케이팝을 사운드 빵빵하게 즐길 수 있는 공간도 있어서 좋습니다! 사진도 되게 잘 나오고 아주 굿이에요!', 9, 2, 'GOOD', SYSTIMESTAMP);
