INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '각 층의 테마가 달라서 너무 재미있고 넓어서 하나하나 구경하는 재미가 있아요 음료도 너무 맛있고 매장도 넓어서 재방문 의사 100%입니다!!!', 87, 17, 'GOOD', SYSTIMESTAMP);
