INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '홍대 ㅎㄷ카페 넘 좋아요.  층마다 컨셉도 달라서 볼거리 다양하고 특히 공연..  서정은님 정말 좋았어요.  커버곡에 자작곡까지 추운날씨에 딱 어울리는 포근한 목소리ㅠㅠ 15,000원에 공연에 음료까지.. 이런 호사스런 문화생활을 누리다니..  감사합니다. ^^', 5, 0, 'GOOD', SYSTIMESTAMP);
