INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '세번째 방문!!   여러분~  루프탑과 아티스트 공연 꼭 보세요~♡   아티스트 공연보다가 중간중간 쉬는시간에 한층씩 도장깨기해도 재미있어요^^   전 오늘은 시간이 애매해서 서정은님 공연만 보고 나왔는데요..  지난달하고 선곡이 많이 바뀌어서 새롭더라고요.  좋았어요~♡  시간 되시는분들은 다른 아티스트분들 공연도 쭉~  보세요.   힐링입니다~  조만간 네번째 방문 예약입니당^^', 11, 7, 'GOOD', SYSTIMESTAMP);
