INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), 'LP음감회라는 신선했던 경험을 ㅎㄷ카페에서 하게되었네요! 커피를 주문할수 있는 공간이 따로 마련되어 있어서 음감회에 집중할 수 있어 좋았습니다! Lp앨범을 발매한 아티스트들의 노래를 고급 엘피판, 스피커로 즐길 수 있어서 좋았던 공간입니다. ㅎㄷ카페 강추!', 73, 17, 'GOOD', SYSTIMESTAMP);
