INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '장소도 되게 넓고 층마다 다른 느낌이 들어서 너무 좋았어요! 저는 특히 5층에 갤러리존이 제 마음에 너무 쏙 들었어요! 지하에 공연도 해서 혼자 왔었다면 하루종일 있을 수 있을 것 같아요😆 (마들렌 리필은 대박이네요 넘 맛있었어용🤭👍🏻)', 77, 16, 'GOOD', SYSTIMESTAMP);
