INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '크리스마스를 맞아 간만에 젊음의 홍대 나들이 … 아들은 근처 미용실에서 백금발 탈색 3차중이라서 전 상담 마치고 자유와 젊음의 홍대 탐색중… 바로 눈에 들어온 비범한 외관의 ㅎㄷCafé 50%할인 입장료가 15000원이지만 충분한 체험가치가 있다고 생각… 먼저 9층으로… 노을이 지는 서울하늘과 크리스마스 트리가 차가운 이 겨울날의 공기를 따뜻하게 감싸는듯하다 .. 8층에서 따뜻한 카페라떼 한잔 주문하고 (입장료에 포함) 7층 케이팝 미디어공간 …대형스크린으로 플레이되는 걸그룹 뮤비타임 6층 lp뮤직공간에서 음악과 커피를 마시며 독서로 나만의 행복한 시간을  만끽중 …. 시끄러운 도심속  잠깐 조용하고 차분한 시간을 갖고  최상의 인테리어속에서  오감의 만족을 가질수있는 최상의 쉼공간-ㅎㄷCAFE', 61, 13, 'GOOD', SYSTIMESTAMP);
