INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '카페라기보단 복합문화공간이 맞겠네요! 여러 카페를 다녀봤지만 이런 컨셉은 처음입니다. 쉽게 접하기 힘든 LP, 라이브공연같은 문화를 맛있는 커피와 함께 누릴 수 있다는 점은 정말 만족스럽네요! 하루종일도 있을 수 있을 수 있겠네요!', 36, 10, 'GOOD', SYSTIMESTAMP);
