INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '복합문화공간으로 루프탑부터 지하까지 다 너무 잘 꾸며져있고 15000원으로 음료와 공연까지 즐길수있다니 너무 좋아요. 특히 코코넛라떼 넘 맛있음! 공연도 40분동안 매시간 있는데 분위기있고 시간제한없어서 오래 즐길수있어요', 66, 11, 'GOOD', SYSTIMESTAMP);
