INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '시설도 너무 깔끔하고 홍대에 이런곳이 있는줄 몰랐어요! 지하부터 9층까지 다양한 컨텐츠가 있어서 하루종일 실내에서 놀기 딱 좋은 곳이에요. 입장권 끊으면 음료 주고 모든 컨텐츠 이용할수 있어서 정말 정말 편하고 좋네요~~', 10, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '추운 겨울 몸도 마음도 녹일 수 있는 곳 특히 지하 싱어송라이터의 공연은 정말 힐링되었습니다 맛있는 커피와 조용하면서도활기넘치는 공간 입니다 와 보길 정말정말 잘했어요 딸아이와 왔는데 훙대오면 꼭 다시와보고 싶습니다', 386, 92, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '홍대에 복합문화공간이라고 해서 와봤는데 너무 분위기 좋아요. 8층 카페에서 음료 구매하면 여러 층의 다양한 공간을 다 즐길 수 있어서 너무 좋아요. 다음에 또 오게 될 거같아요!', 49, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '1인 15000원에. 커피+마들렌+허브티+공연. 커피 맛있고. 지하 공연. 조명 사운드 가수. 완벽한 무대. 9층 루프탑 야경도 이쁨. 주말인데 사람 없은편.', 10, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '엄청엄청 즐길 게 많고 큰 카페에요 !! 음료 한 잔으로 9층을 다 재미지게 즐길 수 있고 맛도 있고 인테리어도 예쁩니다 !🥰 홍대 오면 꼭 한 번씩 와보세용 🫶🏻', 42, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '어제 우연히 지인과 들렸다가 너무 좋아서 남편한테 얘기했더니 가보고싶다해서 같이 왔어요.. 어제는 공연 하나만 봤는데 오늘은 연달아 몇공연을 봤네요.  강추합니다^^', 13, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '진짜 서울에 이런 장소가 있다는 사실이 놀랍고 자랑스러워요!!!괜히 세계 최고가 아니네요!! 귀여운 선인장들이랑 좋은 노래들을 들어주는 LP바 !!! 그리고 잘생긴 직원들까지!!! 😋😋 그리고 공연장 음향이랑 조명 그리고 아티스트들도 징짜 최고였어요!!! 커피한잔 마시면서  휴식 즐기기에 정말 좋은 장소 같아요!!! Ps. 아 선인장은 매우 위험하니까 귀엽다고 만졌다간 큰일날수 있으니 조심하세요 전 이미 피를 봤답니다 ㅠㅠ', 11, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), 'ㅎㄷ카페에 왔어요 전체 이용료는 3만원이지만 지금은 이벤트 기간이라 만오천원에 음료2잔+공연까지 볼 수 있디니 완전 와~~^^ 층마다 테마가 있어서 볼거리가 있고 내가 선호하는 층에서 쉼을 갖기에도 딱이네요 요즘처럼 추운 날씨엔 실내에서 따뜻하게 지루하지않게 보낼 수 있어서 좋습니다~^^ 루프탑도 꼭 올라가보세요~ 성탄 트리 예뻐요♡', 16, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '홍대에서 가볼만한 복합문화공간! 9시까지 영업인데 사실상 8시 40분에 정리를 다 하시더라구요 저녁이후에가면 즐기기 어려울수 있어료 ㅠ', 34, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '인터넷에서 보고 찾아왔는데 기존에는 보기힘든 톡특한 구조였어요 한 건물전체가 층마다 분위기가 다른데 사진찍을곳도 많고 지하에서는 공연도 볼수있는데다가 음료2잔에 디저트가 입장료 15000원에 포함되어 있는게 장점인거같아요(음료중에 바닐라라떼 꼭 드세요😋)제한시간없다는것도 꼭 와야할 이유겠네요 나중에 또 홍대에 오면 꼭 리스트에 넣어놔야겠어요😙 직원분들도 친절하게 설명해주시고 평화로운분위기에 쉴수있어서 좋아요', 17, 0, 'GOOD', SYSTIMESTAMP);
