INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '홍대 중심에서 이런 다양한 복합문화를 즐길수있는 공간이있어 아주 좋네요:) 사진찍기도 좋고 음악을 즐기면서 커피마시기 너무좋습니당 입장료가 아깝지않아요', 50, 10, 'GOOD', SYSTIMESTAMP);
