INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '층마다 다양하게 문화시설을 즐길 수 있어서 좋아요! 음료 맛도 좋고 공연도 넘 재밌어요~! 층마다 화장실도 있고 깔끔해서 좋아요 ㅎㅎ', 32, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '아니 오랜만에 홍대 놀러왔는데 8층짜리건물을 통으로 쓰는 카페가 오픈했다길래 들어가봤어요.. 9층 루프탑은 진짜 경치에 놀라고 지하1층은 공연에 놀라고 무슨 공연 전시 식물 커피 디저트 티 사진찍다가 하루가 끝났네여…', 42, 9, 'GOOD', SYSTIMESTAMP);
