INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '처음보는 카페 처음에 입장료가 있어 놀랐는데 입장료가 너무 싸다 느껴질정도로 안에 다양하게 시설이 있네요ㅎㅎ 특히 지하에 공연장이 있어서 매일마다 공연하더라고요! 다들 홍대 오시면 꼭 방문해보세요!', 17, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '홍대카페'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '코코넛 라떼가 엄청 맛있네요 그냥 카페인줄 알았는데 복합문화예술공간(?) 이라고 하셔서 정확히 어떤곳인지 궁금했는데 지하에서 인디밴드 공연도 매시간마다 진행되고 루프탑에서 즐기는 디제잉 공간도 있어서 눈이 즐거운 시간이였습니다~ 음료 다먹으면 티도 한잔 제공해줘서 루프탑에서 구경할때도 춥지 않게 좋은 시간 보냈네요', 29, 7, 'GOOD', SYSTIMESTAMP);
