INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '홍대 휘낭시에 맛집 입니다 :) 리뷰보고 찾아왔는데 너무 맛있네요!! 커피도 밀크티도 맛있었고, 카페분위기도 넘 좋았습니다✨️ [주문메뉴] ✅️ - 휘낭시에(말리부 트로피컬, 코코넛, 무화과 크림치즈) - 애프터눈 밀크티 - 바닐라빈 라떼 -', 14, 10, 'GOOD', SYSTIMESTAMP);
