INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '커피가 정말 맛있어요! 디카페인 원두도 뭔가 다른지 텍스쳐가 엄청 부드럽고 맛있었어용 ! 마셔본 디카페인중에 제일 맛있는듯 … 구움과자 종류가 여러가지이고 다 맛있어서 입맛에 맞는거 고르시면 될것 같아요 😋', 89, 12, 'GOOD', SYSTIMESTAMP);
