INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '지나는 길에 추천을 받아서 왔어요. 분위기 좋고 깔끔한게 커피한잔 하고 가기에는 정말 좋네요! 라떼가 너무 맛있어요! 강추합니다. 다시 방문할게요. 선선해지면 야외 테이블도 좋을것 같아요.', 129, 22, 'GOOD', SYSTIMESTAMP);
