INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '방학을 맞이해 아들과 홍대 나들이 왔다가, 리밀앤밀리를 찾아왔어요. 까페 맛집 검색했다가 딱 꽂혔네요. 비엔나커피, 딸기라떼 모두 맛있네요. 😀 휘낭시에 맛집이라 해서 to go로 8종류 세트 데려갑니다. ㅎㅎ 맛이 기대돼요.^^', 22, 3, 'GOOD', SYSTIMESTAMP);
