INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '구움쿠키가 먹고싶어 우연히 찾으 들른 까페인데 겉바속초 너무 맛있고 커피도 맛있더라구요! 선물용 쿠키로도 넘 좋을 것 같고 담엔 바스크 치케도 먹어봐야겠어요!', 18, 7, 'GOOD', SYSTIMESTAMP);
