INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '디저트가 진짜 너무 맛있었어요 초코 마들렌은 촉촉하고 진했고 콘플레이크 쿠키는 고소하고 바삭해서 만족스러웠어요 말차라떼도 진하고 부드러워서 너무 좋았어요 분위기도 따뜻하고 창가 자리에서 여유롭게 즐길 수 있어서 더 좋았어요 또 가고 싶은 카페예요', 65, 17, 'GOOD', SYSTIMESTAMP);
