INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '연남동에 올 때마다 생각나는 카페에요☁️ 구움과자를 정말 좋아하는데 여기는 커피도 맛있고 구움과자 정말 맛있습니다! (진짜 찐찐찐) 오늘은 커피말고 엑스퓨레 디톡스 티랑 유자민트티 시켰는데 진짜 맛있어요 정말 진짜 다음번엔 티가 생각나서 올 것 같아요😊💓 감사합니다 또 올게요!!!', 47, 9, 'GOOD', SYSTIMESTAMP);
