INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '카페 분위기도 좋아서 사람들이 많이 와 있었고 편한 시간보내고 힐링하며 즐기고 있는 것이 눈에 보였습니다😊 특히나 바스크 치즈 케이크 처음 먹어보는데 여기 정말 부드럽고 너무나 맛있었습니다 무슨 스페인에서 직접 만들어다가 가져온 케이크인줄 알았습니다😆 초코라떼랑 초코휘낭시에도 엄청 달기보다 적당히 달아서 더욱 맛있었습니다😃 이후도 파스크 치즈 케이크 먹으러 더 들러야겠네요~😋', 63, 15, 'GOOD', SYSTIMESTAMP);
