INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '커피가 맛있다는 리뷰 보고 방문했는데 산미 없이 고소하고 부드러웠어요! 돌체라떼는 싼맛나는 시럽이 아니라 은은하게 달달한? 맛이라 좋았습니다 그리고 피칸쿠키도 처음엔 가격이 비싸다 생각했으나 먹어 보니 다른곳 보다 크기도 크고 꽉찬 느낌의 쿠기였습니다 맛있어요 다음에 주위에 온다면 재방문하고 싶어요', 74, 18, 'GOOD', SYSTIMESTAMP);
