INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '리뷰에 커피가 맛있다고 해서 왔는데 제 스타일이에요☕️ 고소한맛으로 시작해서 산뜻한 산미로 끝나는 게 너무 맛있어요~ 다음에 커피마시러 또 방문할 거 같아요~ ̆̈!! 비엔나커피도 크림에 달지않고 쫀쫀했고 아래에있는 라떼도 고소해서 맛있었어요:) 직원분들도 친절해요🤎', 102, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '시럽없는 음료 마시고 싶었는데, 녹차랑 히비스커스 등등이 들어간 디톡스티 마셔봤어요. 향도 좋고 맛있네요~ 인테리어가 다크한게 차분하고, 음악도 음량 너무 크지않고 잔잔한게 깔려주니 좋았어요! 힐링타임입니다!', 28, 9, 'GOOD', SYSTIMESTAMP);
