INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '저번에 방문하려다가 사람이 많아서 못 왔거든요. 오늘은 다행히 자리가 있어서 냉큼 들어왔습니다! 휘낭시에 쫀득하고 커피도 넘 맛있어요! 매장 분위기도 좋은데 음악이 넘나 제 취향이어서 에어팟 빼고 잠시 있었습니당👍🏻', 125, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
