INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '항상 카페 들어올 때마다 향이 너무 좋아서 재방문 안 할 수가 없어요. 디저트도 너무 맛있고, 더운날에 아이스아메리카노 너무 맛있게 먹었습니다!!', 79, 13, 'GOOD', SYSTIMESTAMP);
