INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '친구들이랑 디저트 먹고 싶어서 찾아갔어요. 구움과자 종류 다양하고 다크초코랑 솔티카라멜 먹었는데 맛있었어요. 친구가 커피도 맛있다네요. 전 밀크티 먹었는데 맛있어요.', 135, 92, 'GOOD', SYSTIMESTAMP);
