INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '연남에 놀러 왔는데 맛있는 커피 마시고 싶어서 찾다가 왔는데 진짜 라떼 너무 맛있어요! 연남라떼맛집 발견! 추천이요!! 원두 고소한맛으로 선택했는데 완전 마이서타일이네유 ㅎㅎㅎ 바스크 치즈케이크도 촉촉하면서 달달하니 맛있어요👍🏻👍🏻', 49, 10, 'GOOD', SYSTIMESTAMP);
