INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '찜해뒀던 카페인데 마침 시간이 나서 들렸는데 커피도 맛있고 마들렌도 상큼하니 맛있어요! 원두도 산미 없는거 있는거 고를 수 있어서 좋구용 화장실도 내부에 있고, 카페 내부 분위기도 아늑해서 편하게 있기 좋더라구요~ 무엇보다 남자 직원분이 엄청 친절하시고, 배달 기사님들한테도 일일이 인사해주시는거 보고 앞으로도 계속 와야겠다 생각했습니다ㅎㅎ', 18, 2, 'GOOD', SYSTIMESTAMP);
