INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '개인적으로 서교동 최애 카페. 비엔나커피 짱짱 맛있고 모든 음료, 디저트 사랑합니다. 분위기도 사진 잘 나오고 아늑해서 대화하기 좋아요. 아침 일찍 문여시니 직장인들에겐 모닝커피를 리밀앤밀리에서 시작할 수 있어 좋아유. 마치 방앗간 들리는 참새 짹짹.', 117, 22, 'GOOD', SYSTIMESTAMP);
