INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '사실 저 바다회사랑 우ㅔ이팅한다구 리밀앤밀리를 왔는데요! 기억을 더듬어보니 이전에 왔다가 자리가 없어서 나갔던 카페더라구여.. 이날 운좋게 바테이블 자리가 있어서 커피를 즐겼답니다! 아아 산미없는 거 4,000원/ 산미 있는 원두 팔레트는 오백원 추가해서 4,500원인데 둘 다 맛에 비해 최고의 가성비랍니다.. 너무 맛있었어요 밥만 안 먹으면 구움과자로 배채우고 싶었는데… 지인짜 먹음직스럽게 생겨서 눈물좔좔 구움과자류는 포장도 잘 해주셔서 선물용으로도 좋을 거 같아유! 아아가 맛있어서 라떼맛도 기대중인데.. 다음에 또 !!! 방문해서 구움과자랑 먹어보겠습니다!! 커피맛집 .. 🥹', 48, 1, 'GOOD', SYSTIMESTAMP);
