INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '홍대 근처가 은근히 카페 고르기가 고민됏던 터라 열심히 찾아보다 구움과자가 땡겨서 찾아왓어용 자리가 만석이라 잠시 기다렷지만 금방 자리가 나서 먹엇습니당 ㅎㅎ 휘낭시에 마들렌 바치케 다 잇어서 골라 먹을 수 있어용! 분위기도 차분하고 시끄럽지 않아서 대화하기 좋은 것 같아요!', 11, 9, 'GOOD', SYSTIMESTAMP);
