INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '여행 중에 딸아이가 검색해서 찾은 카페 [리밀 앤 밀리]~휘낭시에가 정말 다양해요. 고소한 무화과 크림치즈, 상큼한 레몬 휘낭시에 맛보았어요~커페라떼 커피맛이 깊고 좋아요~ 커피값이 참 착해요~ 휘낭시에 포장 손님이 많았어요~배달도 많네요. 인기있는 이유를 알겠어요~ 패션후르츠 에이드도 참 상큼하고 맛있어요^^', 27, 9, 'GOOD', SYSTIMESTAMP);
