INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '커피맛이 변했어요….정말 충격입니다 여기 오래 살면서 5년째 리밀 최애카페였고 항상 커피 맛있어서 가족 동생 친구들한테 다 칭찬하고 서교동에 많은 카페가 있지만 늘 여기만 애용해왔어요..ㅜㅠ 근데 요즘 커피 원두가 변한건지 아니면 새로운 알바분이 커피를 너무 쓰게 내리는지 진짜 처음에 맛이 변해서 몇일 뒤 다시 마셔보니(그날이랑 똑같은 직원분이 내려줌. 비교적 최근에 오신 분 같고 오래된 직원분은 아님)맛이 없어요 ㅠㅠㅠㅠㅠㅠ 이거 어떻게 된거죠…? 다시 돌아와주세요 ㅠㅠ….', 6, 1, 'BAD', SYSTIMESTAMP);
