INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '엔젤*** 에서 맨날 먹다가 회사 동료 분하고 방문 했던 기억이 나서 회사 출근할 때 포장 주문했어요~  커피도 맛있고 요청 사항 잘해주시고 너무 친절하시네요.  쿠폰도 주시고 좋아요 ! 자주 갈 거 같아요 !', 8, 2, 'GOOD', SYSTIMESTAMP);
