INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '홍대 카페투어중에 들렀습니다 좁은 골목길에 인테리어가 참 매력적이고 편안했어요. 직접 로스팅도 하는 커피 전문점이면서 파티시에 분이 따로 있어 디저트도 진심인 카페에요.', 23, 2, 'GOOD', SYSTIMESTAMP);
