INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '홍대입구 커피맛집 검색하고 찾아왔는데 라떼랑 비엔나커피 정말 맛있네요~ 직원분도 친절하시고 분위기도 좋고 좋은 시간 보내고 갑니다', 0, 8, 'GOOD', SYSTIMESTAMP);
