INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '마들렌이랑 휘낭시에 진짜 맛있어요! 레몬 마들렌은 안에 과육도(?) 들어가있는 것 같았어요 ! 씹히는게 있었고 상큼해서 더 입이 즐거웠고… 솔티카라멜 휘낭시에는 덮혀있는 카라멜이 진짜 꾸덕해서 더 ! 맛있었어요 드립도 진짜 산뜻해서 비오는 날 ☔️의 습하고 끈적한 기분을 싸악 씻겨주는 느낌 ! 🤧 드립이라 어쩔 수 없었을 거같긴 한데 커피 양이 조금 적게 느껴졌아요… 그래서 아메리카노를 추가로 주문했는데 아메리카노는 꼬숩고 아몬드 향이 좀 더 짙게 났어요 ! 둘 다 마셔보길 정말 잘한 것 같아요!! 산뜻한 커피 드시고 싶으신 분들이 계시다면 라 에스메랄다 원두 추천 드립니다! 🤤 마들렌이랑 휘낭시에 또 먹으러 갈게요 🏃🏿💨', 12, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
