INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '바닐라빈라떼 ice 맛집이네요~달콤달콤! 자모카 아몬드 쿠기 촉촉하면서 견과류가 알차게들어있어서 씹을때마다 고소함이 폭발 너무맛나용 휘낭시에 얼그레이 ,솔티카라멜,무화과크림치즈는 포장했어요~평일 점심시간대 방문했는데 근처 직장인분들 식후 커피마시러 많이오시더라구요~은은한 달콤함과 견관쿠키러버라면 리밀앤밀리 바닐라빈라떼,자모카 아몬드 쿠키 추천', 34, 6, 'GOOD', SYSTIMESTAMP);
