INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '정말 한적한 분위기의 카페예요💕💕 저는 휘낭시에 세트를 포장했는데 골고루 종류마다 이쁘게 담아주셔서 선물로 너무나도 좋은 디저트 맛집이에요 선물 받는 사람들도 행복할 만한 카페라 선물 할 일 있으면 자주 방문할 거 같아요!!😍', 41, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '지인과 둘다 오후에 일정이 있어 하루에 커피 두잔은 무리길래 차로 시켰는데;;; 그냥 커피 마실걸 ㅜㅜ 이 집에 오시면 시그니처 드세요 !! 시그니처 맛있어요 ❤️ 차는 그냥 ,, 차 맛입니다 🥲 그리고 하나 더 !!!!!! 차는 꼭 따듯한 걸로 드세요 ㅜㅜ 아이스 마시고 엄~~청 후회 했어요 디저트는 꼭 드시고요 여긴 디저트도 맛있어요 👍🏻 종류도 다양하고 야외에도 자리가 있어서 지금 가기 딱 좋아요 지역주민과 직장인 분들은 할인도 해주니 근처 출근 하시면 완전 딱이네여 ~ 저도 근처 올 일 있으면 굳이 한번씩 들리는 집이긴 해요 ㅎ 주변에 딱히 정해진 곳 없다면 한번 들러보면 좋은 집 입니다 ~', 39, 0, 'GOOD', SYSTIMESTAMP);
