INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '리밀앤밀리 휘낭시에는 생긴거부터 특별해요!! 금괴모양이 아니고 약간 통통한 아몬드 모양이라고 해야되나...? 그래서 일반 휘낭시에보다 더 양이 많게 느껴져서 좋아요 ㅎㅎ 선물포장으로 전체종류 다 구매해봤는데 친구랑 넘 맛있게 먹어서 다음에 쿠키 먹으러 다시 올려구요 💕 날 좋을 때 야외테이블에서 먹을 예정~~~', 19, 2, 'GOOD', SYSTIMESTAMP);
