INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '직장근처라서 산책하다 우연히 발견한 카페ㅎㅎㅎ 커피맛집인줄 알았더니,, 디저트까지 맛집인줄 몰랐어요!! 한번먹어보고 넘 맛있어서 선물용으로 가끔들러용ㅎㅎㅎ 레몬마들렌은 특히 당거싫어하는 저희엄마가 너무좋아하세요!!! 샤르르녹는맛이에요 강추드려용', 21, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '마들렌 휘낭시에는 리밀앤밀리 😍 평소 친구 선물용으로 테이크아웃 주문만 하다가, 오랜만에 매장이용했어요. 디저트가 정말 좋아서 차+휘낭시에 조합 강추해요!! ㅋㅋㅋ 담백하고 맛있어요 🩵', 22, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '휘낭시에 맛집… 나 휘낭시에 좋아했네 집이에요… 친구랑 왔는데 진짜 종류별로 다 먹어보고 싶었어요 ㅜㅜ 공간이 크진 않은데 이야기하기 좋고 조용, 아늑해요. 사람 많아지지 않았으면 하지만.. 많아져야 휘낭시에 평생 먹겠죠..? 쿠키도 맛있는데 휘낭이 찐! 진하고 달달해요. 얼그레이 최고 존엄이었고 무화과 솔티카라멜 두 누아(?) 먹었는데 다 맛있음. 몽실 쫀득..!', 114, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '홍대에서 조용한 카페가 있어서 너무 좋습니다. 구운 과자류 전문점이라 마들렌,휘낭시에 다 맛있습니다. 버터 함량도 높은거 같구요~~ 커피와 함깨하니 꿀조합 이네요! 고급 구움과자 좋아하신다면 추천합니다!', 26, 10, 'GOOD', SYSTIMESTAMP);
