INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '휘낭시에와 커피 맛집입니다 :-9 리밀앤밀리에서 휘낭시에를 하나만 맛본다는건 있을 수 없는 일이고요, 거기에 두툼한 쿠키까지 꼭!! 먹어줘야 합니다. 카페 내부도 편안하고 따뜻해서 커피와 디저트를 즐기기 좋답니다. 이렇게 맛있고 예쁜거 나혼자 즐기기엔 아까운데, 포장까지 이뿌게 해주시는 세트도 있다고 하니 네이버 지도에 꼭 가봐야할 카페로 저장해놓으세요!!', 49, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '휘낭시에, 쿠키, 마들렌, 바스크치즈케이크를 파는 리밀 앤 밀리! 주말 오후에 방문했는데, 매장에 사람이 꽉 찼더라고요~~ 휘낭시에 포장도 가능해서 포장했습니다! 겉은 적당히 바삭하고 속은 꽉차고 부드러운 식감의 휘낭시에였어요!', 49, 0, 'GOOD', SYSTIMESTAMP);
