INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '생일 케이크로 바스크치즈케이크 홀사이즈 주문했는데 정말 너무너무 맛있어요 다른 곳 보다 저렴해서 더 만족스러워요 휘낭시에도 사와서 먹었는데 진짜 맛있네요', 39, 8, 'GOOD', SYSTIMESTAMP);
