INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '휘낭시에 너무 맛있어요 대애박😛 카페 너무 이쁘고 따숩고 아기자기 해서 지나가다가 홀린듯이 옴 알고보니 지인이 자주오눈 카페라 지인 만남 커피도 아주 고소하고 맛나요 덕분에 잘 쉬고 갑네다 :)', 44, 0, 'GOOD', SYSTIMESTAMP);
