INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '디저트 맛집 😏 휘낭시에 겉바속촉으로 너무 맛있고 매장은 우드톤 인테리어로 따뜻하고 포근한 분위기라서 너무 분위기 있어서 좋았어요 포장해서 휘낭시에 먹어봤는데 얼그레이, 솔티카라멜 추천해요 😎 겉바속촉이고 크기고 크고 무엇보다 맛있어요 ,,,, 얼그레이 포장 뜯기도 전에 향이 나더니 한 입 먹으니 입 안 가득 향이 퍼집니다 ㅠㅠ', 44, 4, 'GOOD', SYSTIMESTAMP);
