INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '구움과자 정말 좋아하는 빵순이인데 빵앗간에 오니 너무 행복했어요🥰 휘낭시에 마들렌 완전 좋아하는데 맛별로 하나씩 다 포장해서 먹어봤어요! 휘낭시에 그랑뵈르, 레몬마들렌, 휘낭시에얼그레이, 휘낭시에 솔티카라멜 다 맛있어욤 ㅠㅠ 특히 제 원픽은 고메버터의 진한 풍미가 느껴지는 휘낭시에 그랑뵈르~~👍👍❤️', 65, 18, 'GOOD', SYSTIMESTAMP);
