INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '전체적으로 아늑한 분위기라서 포근한 겨울 느낌 낭낭한 카페! 친구랑 홈파티한다고 포장 해갔는데, 휘낭시에 너무 맛있음 진심 달달하고 폭신하고 부드럽고 .. 도톰해서 양도 많고 ㅠㅠ 완전 디저트 맛집입니다 강추', 26, 0, 'GOOD', SYSTIMESTAMP);
