INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '따숩고 포근한 분위기 가득인 리밀앤밀리 휘낭시에 맛집으로 유명해서 전부터 가고싶었다 특이한 모양의 휘낭시에인데 그 모양 덕분에 바삭한 겉면이 더 많아진 느낌 카페 분위기도 좋고 커피도 맛있어서 재방문의사 충만', 43, 4, 'GOOD', SYSTIMESTAMP);
