INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '구움과자 맛집이라고 해서 방문했어요 제가 휘낭시에를 좋아하는데 여기 휘낭시에 쫀득한 식감에 속이 꽉찬 (?) 느낌의 휘낭시에라 너무 맛났어요 달달함도 딱좋고 커피한잔이랑 마셔도 너무 좋을것 같네요 포장해서 가는길 못참고 몇개 뜯어먹었는데 존맛 ㅠㅠ 당골될것 같아요 !', 17, 5, 'GOOD', SYSTIMESTAMP);
