INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '합정역과 홍대역 사이에 차분한 분위기의 카페를 찾다가 알게 됐는데 카페 분위기도 좋고 디저트 종류도 다양해서 좋더라구요 구움과자를 좋아해서 다양하게 포장해왔는데 휘낭시에는 겉바속쫀 식감에다 재료마다 향이 너무 좋아서 호불호없이 다 좋아할 것 같아요 마들렌은 레몬향이 확 퍼지면서 상큼달달하니 맛있었어요 쿠키도 두꺼운 스타일에 아몬드가 아낌없이 들어가서 커피랑 마시기 좋은 맛입니다 디저트에 진심인 카페라 특별한 날에 선물용으로 사가기 좋아보여요! :)', 110, 19, 'GOOD', SYSTIMESTAMP);
