INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '연남동에서 분위기 최고인 구움과자 맛집입니다! 점심시간에 커피 테이크아웃하시는 직장인 분들도 많으시고 마들렌이나 휘낭시에 선물로 드리기에도 너무 좋더라구요!! 직원분들도 진짜 친절하셔요!!! 크리스마스 분위기의 기분 좋은 맛집인 카페입니다🍪❤️ 강력 추천드려요!!!👍', 33, 2, 'GOOD', SYSTIMESTAMP);
