INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '고급진 휘낭시에가 있는 홍대 합정역 카페 리밀앤밀리! 휘낭시에랑 쿠키 포장 하러 갔는데 매장도 아늑하고 조용한 분위기에 시간 보내기 넘 좋은거 같아요 레몬 마들렌은 촉촉 바삭하고 상큼해서 제 픽이에오ㅠㅠ 구움과자 전문점 답게 디저트 종류가 다양해서 너무 좋았어요! 🤎', 66, 15, 'GOOD', SYSTIMESTAMP);
