INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '구움과자가 맛있다고 해서 찾아가본 리밀앤밀리예요. 복잡스러운 홍대 근처에 이렇게 차분하고 분위기 좋은 카페가 있는지 처음 알았는데, 카페도 예쁘고 디저트도 소문대로 맛있더라구요!!! 쿠키랑 휘낭시에 포장했는데, 쿠키 정말 존맛존맛ㅠㅠ 가격 대비 묵직하고 내용물도 가득 들어있어요.', 19, 6, 'GOOD', SYSTIMESTAMP);
