INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '홍대 치즈케익 검색하다가 가본 카페인데, 여기 진짜 치즈케이크 맛집이더라고요! (내돈내산임) 꾸덕꾸덕하니 존맛탱이였어요. (놀랍게도 저는 치즈케익을 그닥 좋아하지 않는데도 말이죠!) 재방문할 마음있어요 😊😆', 176, 59, 'GOOD', SYSTIMESTAMP);
