INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '커피와 구움과자가 맛있는 서교동 카페! 감성있는 인테리어와 편안한 분위기가 아주 좋습니다. <추천메뉴> 솔티 카라멜 휘낭시에 3,500원 다크초코피칸쿠키 4,800원 피넛버터 & 잼쿠키 4,800원 단짠, 겉은 바삭 속은 쫀득한 디저트의 정석이예요. 당 충전 제대로 합니다.', 35, 4, 'GOOD', SYSTIMESTAMP);
