INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '크림 라떼 진짜 진짜 맛있어요!!! 엄청 달지도 않고 고소하니 넘 맛있습니다 마들렌도 맛있어요,,, 분위기도 좋고~ 대화하기 좋아요 매장이 크지는 않습니다', 20, 7, 'GOOD', SYSTIMESTAMP);
