INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '분위기도 디저트도 뭐하나 빠지지 않는곳👍🏻 크리스마스 분위기 낭낭한게 쉬어가기 머무 좋은곳 이였어요😆 특히 휘낭시에 너무 부드럽고 맛있는게 종류별로 하나힉 다먹어보고 싶어요! 르뱅쿠키도 엄청 두껍고 재료 재료 푸짐하게 들어가 있어서 하나만 먹어도 배불🥹 넘 맛있게 잘 먹고 갑니다!', 11, 7, 'GOOD', SYSTIMESTAMP);
