INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '거게분위기도 고즈넉하니 따뜻한느낌이라 좋앗어요! 디저트도 하나같이 다 맛있어서 더먹구싶더라구요 다음에 방문하면 다른걸로 다 먹어보고싶어용 ㅠㅠ 필터커피 주문했는데 평소에 꽃향나는 커피 좋아하는 편인데 정말 꽃향과 산미가 가볍지않게 나서 너무 만족스럽더라구요!! 자허블도 스벅보다 맛있는거같아용🫢👍🏼', 25, 5, 'GOOD', SYSTIMESTAMP);
