INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '홍대입구 합정역 사이에 있는 구움과자 맛집이에요! 골목에 있어서 생각보다 한가한데 이 근처에 카페들이 은근히 있어서 여유로운 공간 찾으신다면 가보세요 바 자리도 많아서 혼자 가도 좋고 특히나 휘낭시에가 겉바속쫀으로 엄청 맛있어요✔️', 95, 23, 'GOOD', SYSTIMESTAMP);
