INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '디저트 포장하러 방문함!!! 포장도 꼼꼼히 해주고 쿠키가  케이크같음!! 미니케이크처럼 포장해줌!!! 가격도 저렴하고 맛있음!', 52, 13, 'GOOD', SYSTIMESTAMP);
