INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '🫶 🫶 🫶 서교동 할인도 넘 좋은 것 같고 무엇보다 커피랑 디저트 둘다 맛있어요! 간만에 맛있는 아메먹어서 기분좋게 머물다왔어요:) 직원분들도 친절하시구 분위기도 좋아서 다음에 또 갈래요!', 46, 1, 'GOOD', SYSTIMESTAMP);
