INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '휘낭시에 먹고플 때마다 방문하는 곳!! 크기가 꽤 크고 종류도 다양해서 좋아요. 그리고 무엇보다도 괘맛있음 ♥ 휘낭시에 박스포장으로도 주문가능한데, 가끔 선물하기 좋아요! 받는 사람들마다 너무 좋아하더라구요 ㅎㅎ', 35, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '회사 근처 최애카페❤️ 유일하게 쿠폰 2장이상 모아서 써본곳... 너무 맛있어서 회사사람들한테 추천했는데 다들 단골 됨... 라떼 자뀨 생각나는맛... 월욜 오전 출근하는 나를 위로해줘요..ㅜㅜ 그동안은 포장만 해먹어서 몰랐는데 처음으로 매장이용했을때 서비스로 디저트 먹어보라고 주시고 이렇게 친절 한줄도 몰랐습니다..너무 감동..❤️ 여기 휘낭시에도 대박 맛있어요.. 종종 사먹고 여기 휘낭시에는 심지어 통통해요.. 다들 라떼 꼭 드세여', 3, 8, 'GOOD', SYSTIMESTAMP);
