INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '오후에 일찍 갔더니 품절된거 없어서 먹고싶었던거 다 고를수있어서 좋았어요 맛별로 하나씩 주문했는데 쿠키 휘낭시에 고른거 다 너무 맛있어서 순삭했어요', 10, 3, 'GOOD', SYSTIMESTAMP);
