INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '이 근방에서 제일 좋아하는 곳이에요! 재방문 몇번째인지.. 우선 휘낭시에 존맛이구요 선물하기도 좋아서 포장해서 몇번선물했어요. 커피맛도 정말 좋아서 데려가는사람마다 만족! 조용하고 아늑해서 좋아요 ♡', 8, 1, 'GOOD', SYSTIMESTAMP);
