INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '홍대 합정 디저트 맛집 리밀앤밀리 우드톤의 인테리어가 정말 예뻐요 내부 공간과 야외좌석까지 있는데 요즘같은 날씨에 밖에서 디저트 먹고 커피 마시기 딱! 좋은 밀가루 소금 사용해서 만드는 휘낭시에를 먹을 수 있다고 해서 기대했는데 휘낭시에 정말 맛 있네요! 제 취향 기준 무화과 크림치즈, 솔티카라멜 휘낭시에 추천드립미다❤️👍', 65, 16, 'GOOD', SYSTIMESTAMP);
