INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '서교동서 우연히 알게된 카페인데 휘낭시에가 진짜 맛있어요!!! 포장도 가능해 다음에 선물도 해야겠어요 💛 홍대 합정 중간쯤에 위치해 있는데 디저트 맛집이에요😆', 77, 11, 'GOOD', SYSTIMESTAMP);
