INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '서교동 골목에 있는 카페인데요 항상 지나다니기만 했는데 구움빵 맛집이였네요 마들렌이랑 커피랑 함께 먹으니 정말 맛있네요 다음엔 커피도 마셔보려구요', 33, 6, 'GOOD', SYSTIMESTAMP);
