INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '휘낭시에 맛있어서 오늘 또 포장했어요! 생긴게 좀 특이하지만 쫀득하니 풍미가 좋아요! 여기 커피가 산미가 있는데 휘낭시에와 잘 어울려요! 다른 커피랑 먹어봤더니 확 비교 되더라구요! 주차할곳은 없으니 참고하세요~~', 80, 18, 'GOOD', SYSTIMESTAMP);
