INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '여기 휘낭시에만큼 맛있는곳 못봤어요. 제일 맛있는듯. 모앙도 유니크해요. 마치 군함같은 모양인데 겉은 살짝 바삭, 속은 진득한 촉촉함이 살아있어요. 제가 젤 좋아하는 휘낭시에는 단짠 솔티카라멜 입니당♡ 추천해요! 홍대갈때마다 꼭 들러서 포장해오는 맛집이에요~><', 14, 4, 'GOOD', SYSTIMESTAMP);
