INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '휘낭시에 맛있다고해서 추석선물용으로 휘낭시에 구매하러 갔어요! 일단 휘낭시에 전문점답게 종류 다양해서 너무 좋았구요. 포장박스랑 포장봉투도 넘 이뻐서 딱이었어요. 선물 받은 사람에게 집 가서 먹어보고 후기 알려달라고 했더니 가는 도중 차 안에서 하나 먹고 넘 맛있어서 그 자리에서 다 뜯어먹어버렸다곸ㅋㅋㅋ 후후 얼그레이랑 초코 강츄츄 , 나머지도 당근 넘 맛있다고 뭐가 더 맛나냐 말하기가 어렵다며 ㅋㅋ 🫶 리밀앤밀리 휘낭시에 선물 대 성공이라 넘 기분 좋습니당', 16, 2, 'GOOD', SYSTIMESTAMP);
