INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '휘낭시에 모양이 독특해서 더 특별하게 느껴지네요. 다양한 종류의 휘낭시에가 있어 고르는 재미가 있네요. 버터리한 맛도 충분하고 달달해서 커피랑 같이 먹으니 찰떡입니다! 치즈케이크나 쿠키도 맛있을 것 같아요~', 78, 11, 'GOOD', SYSTIMESTAMP);
