INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '여기휘낭시에쫀득하고  맛있어요.^ 맛도 진하고 향 식감  완벽해요~그리고 좋은재료루만들었다는게  맛을보니 이해가되더라구요^ 담엔 커피랑같이 먹어야겠어요^', 1, 8, NULL, SYSTIMESTAMP);
