INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '와.. 마들렌하고 휘낭시에 진짜 맛있어요ㅠㅠㅠ 종류도 다양하고 하나같이 다 맛있는데 커피까지 맛있어버림👍👍 매장도 넓어서 친구랑 방문했는데 넘 좋았습니다!!', 84, 15, 'GOOD', SYSTIMESTAMP);
