INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '휘낭시에 먹자마자 버터 풍미가 한 가득이라 완전 고급진 맛이더라구요 ! 각각 재료도 듬뿍들어가 있어서 휘낭시에마다 맛이 특색있어서 좋아요 ~ 선물세트도 있던데, 연말 선물로 완전 추천 - ! 겉바속쫀에 고급짐이라 모두모두 좋아할 맛 💕', 49, 4, NULL, SYSTIMESTAMP);
