INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '구움과자 좋아해서 홍대 맛집들 찾아다니다가 발견했어요! 카페 자체는 크진 않은게 분위기도 너무 좋구 아늑했어요! 여성 손님들이 딱 좋아하실 느낌이었어요 게다가 구움과자들더 하나같이 이쁘고 맛있어서 다음에 또 재구매 하러 와야겠어용!! 특히 최애는 레몬 마들렌입니다🌸', 50, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '홍대쪽에 휘낭시에맛집이 있다고 해서 들렸어요~!! 공휴일이라 만석이라 포장만 하고 왔는데 휘낭시에 7종 주무가능해서 6개 여러가지 주문해서 포장해갑니다! 선물용포장도 있구~ 맛도 모양도 👍', 25, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '서교동 출판가& 카페 거리에 위치한 카페입니다. 밀리카페는 카페의 기본 요소에 충실한 카페? 라고나 할까요? 최근에 가본 카페 중에서도 마음에 드는 카페였습니다. 카페 외관은 깔끔합니다. 테라스 자리도 있고 적당한 규모였습니다.', 135, 67, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'TERRACE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '먹어본 휘낭시에 중에 제일 맛있었어요! 솔티카라멜, 무화과크림치즈 먹었는데 겉바속촉하고 풍미가 장난 아니에요🫢 아메리카노 사이즈업하고, 썸머라떼 테이크아웃했는데 스푼도 따로 챙겨주시고 예쁘게 포장해주셔서 좋았습니다. 음료 맛도 일품이구요! 커피, 디저트 어느 하나 빠짐없이 완벽한 홍대 합정카페에요. 카페 분위기가 조용하고 아늑해서 오붓하게 대화하거나 책 읽기에도 좋겠어요. 저만 알고싶은 홍대카페 하나 생겼네요🫶 구움과자 하나씩 다 먹어보러 가겠습니다 ㅎㅎ', 59, 11, 'GOOD', SYSTIMESTAMP);
