INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '휘낭시에랑 마들렌 정말 맛있어요!🥺 마들렌은 진짜 포슬포슬하니 부드럽고 휘낭시에도 쫀쫀한게 식감 최고..👍🏻 담에는 바스크 치즈케이크도 꼭 먹어보려구요!', 88, 15, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '진하게 올라오는 버터향이 강해서 너무 좋았어요. 그리고 개별 포장 되어있어서 누군가한테 선물하기도 좋고 시간이 지나도 맛이 안 섞이는 게 제일 좋았어요. 카라멜이 발라진 건 비닐 포장이 아닌 다른 식으로 포장해주신 센스. 휘낭시에 좋아하시면 강추입니다.', 98, 22, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '이 동네가 예전에 비해 카페가 진짜 많이 생겼고 이쪽 왠만한 카페 커피는 다 맛있지만 서교동 10년 넘게 거주한 동네주민 찐사랑 카페 넘버원입니당🩷 커피가 진짜 맛있어요 절대로 없어지면 안돼요.. 제가 먼저 이사가기전까지는 자주 갈거에요ㅋㅋ 놀러오시는 분들이 많아 착석은 가끔만 하구 대부분 테이크아웃 자주하지만 한번도 실망한적 없는 카페,,🥹', 30, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '쫀득하고 겉바속촉인 휘낭시에가 너무 당겨서 왔는데, 주문한 메뉴에 크림치즈가 들어서인지 마들렌처럼 부드러운 질감이었어요. 라떼+무화과 크림치즈 휘낭시에=9000원. 까페가 경의선 숲길에선 좀 떨어져 있지만 경의선 숲길 걸어 모교쪽 가려고 잠시 쉬어가요.', 30, 8, 'GOOD', SYSTIMESTAMP);
