INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '휘낭시에 맛집으로 유명해서 방문했는데 진짜 너무너무 맛있어요!! 대박! 휘낭시에 찐맛집 인정합니다ㅎㅎ 카페도 넘 예뻐서 다음엔 카페에서 먹으려구요!', 10, 7, 'GOOD', SYSTIMESTAMP);
