INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '휘낭시에 종류가 많아서 좋고 저는 특히 쿠키를 너무 맛있게 먹었어요 단골 카페할거같아요 분위기도 조용하니 괜찮고 디저트도 상당히 맛있네요 휘낭시에 왕 커요!ㅎㅎ', 36, 0, 'GOOD', SYSTIMESTAMP);
