INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '친절하셔서 기분좋았던 카페입니다~ 카페 분위기 좋고 조용해서 혼자 시간보내기 좋았어요ㅎㅎ 커피랑 구움과자 먹었는데, 커피 진해서 맛있었고 구움과자는 퀄리티 굿굿!!! 홍대, 합정 갈일 있을때마다 방문하고싶은 카페입니다~', 14, 10, 'GOOD', SYSTIMESTAMP);
