INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '일단 커피가 너무 맛있어요! 원두가 좋으니까 그렇겠죠? 기본템인 아아부터 넘 맛있었고, 구움과자 휘낭시에 종류별로 거의 먹어봤는데 진짜 넘 마싯고 향고 좋습니다! 테라스 석에서 초록 충전까지 잘 하고 갑니다 ㅎㅎ', 6, 2, 'GOOD', SYSTIMESTAMP);
