INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '동네에서 제일 애정하는 커피집이에요 놀러오시는 분들도 많아서 테이크아웃만 해오는 경우가 더 많지만요 ㅜㅜ 커피 맛있고 우유양 조절도 가능해서 너무 좋아요 평일 오전 방문했는데 남자직원이 커피를 너무 맛있게 만들어주셔서 행복했어요!', 75, 16, 'GOOD', SYSTIMESTAMP);
