INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '디저트 맛집 !!!!! 저 중 레몬마들렌이 제일 맛있었어요🧡 커피도 그럭저럭? 맛있어요 근데 1인이 오기에 좋은 카페는 아닌듯 해요 넓은 창가 자리가 비었는데도 거긴 1인은 못 앉는다며 못 앉게 하시더라구요; 2-4명이 가기에 좋은 곳입니다!', 28, 6, NULL, SYSTIMESTAMP);
