INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '라떼 종류가 다 맛있는 곳 입니다. 근처에 말차라떼 맛집이 없는데 리밀 말차라떼 맛있더라구요! 쿠키 굽는 냄새도 좋고 직원분들도 친절하셔서 항상 가면 기분이 좋습니다!', 19, 8, 'GOOD', SYSTIMESTAMP);
