INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '서울 여행 하면서 젤 만족했던 곳 🫶🏻 크림라떼 너어무 맛있었구요 휘낭시에 종류도 많고 넘 맛있었어요 🤍 얼그레이, 카라멜, 초코 먹었는데 다 맛있는데 초코가 매우 맛있었어욤 -`♥´- 바깥 자리도 분위기 있고 좋았고요 카페 내부도 편안하니 좋았어요 ㅎㅎ 화장실에 논픽션 핸드워시, 크림 까지 있는데 써보고 좋아서 저 그거 살려고요 (?) ㅋㅋㅋㅋ 아무튼 배려도 돋보이고 서울 살았다면 정말 자주 갔을거예요 .. 잘 먹었습니다 ㅜㅜ 🩵🩵', 59, 18, 'GOOD', SYSTIMESTAMP);
