INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '분위기 맛집 디저트 맛집 합정 리밀앤밀리예요 우연히 지나가다가 외관이 예뻐서 들어왔는데 내부가 더 예쁘고 시원하고 청량감 드는 카페예요 시그니처 레몬 마들렌 꼭 꼭 두개씩 드세요 한개만 먹으면 섭섭하거든요🤣', 15, 7, 'GOOD', SYSTIMESTAMP);
