INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '서울여행중 들린 마음편한 카페☕️ 완전 잘 찾은듯!!고소한 커피. 커피도 맛있고,그링뵈르, 치즈케익 다 맛있어요. 뭐하나 뒤쳐지는게 없었답니다. 번화가쪽이 아니여서 조용하고,이야기 나누기도 좋았답니다. 여행중 제일 맛있는 카폐였어요. 리뷰적으니 또 생각나네요.다음 여행 목록에 추가!!', 23, 3, 'GOOD', SYSTIMESTAMP);
