INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '부담 없이 들리고 커피 한잔 그리고 구움과자 하나 먹기 좋은 곳. 피낭시에는 무화과 크림치즈가 가장 낫고, 마들렌 추천. 커피는 라떼류 추천.', 40, 9, 'GOOD', SYSTIMESTAMP);
