INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '매장으로부터 할인받고 작성한 솔직한 후기입니다. 티라미수라떼 마스카포네 크림도 찐하고 커피향도 너무 좋았네요. 구움과자 종류도 꽤 많고 버터 풍미 가득해서 맛있게 먹었습니다. 분위기도 좋고 사진도 잘 나오는 사진 맛집이에요. 추천합니다.', 35, 7, 'GOOD', SYSTIMESTAMP);
