INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '망원동 산책하다가 만난 보물같은 카페! 휘낭시에 너무 좋아하는데 하나 하나 엄청 공들여 만든 티 나고 좋은재료 듬뿍 들어있어서 빵순이는 너무 행복했어요 ㅠㅠ 테라스도 있고 카페 분위기 조용하고 아늑하고 너무 좋네요! 휘낭시에 좋아하시는 분들이라면 꼭 가보세요!! 선물로 드리기도 좋고 포장해서 망원한강공원에서 피크닉하면서 하나씩 꺼내먹기도 좋아요!', 23, 1, 'GOOD', SYSTIMESTAMP);
