INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '취향저격이었던 내 스타일 카페💕 우리동네에는 오ㅐ 이렇게 분위기좋고 기저트도 맛있는데 가격까지 착한 카페 없냐구요 ㅠㅠㅠ 다녀본 홍대 개인카페중 최고였어요!!! 다음에는 못먹어본 바스크치즈 케이크랑 다른맛 휘낭시에 먹으러 갉거에요~~~~', 329, 27, 'GOOD', SYSTIMESTAMP);
