INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '제법 한산한 골목에 있는데도 여기만 핫플이다 주말 기준 만석 유지하는 듯? 테이크아웃 해서 집 가서 먹었는데도 맛있었음 b 휘낭시에 디저트도 굿굿 인기 많은 이유가 있다', 17, 3, 'GOOD', SYSTIMESTAMP);
