INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '커피 테이크 아웃 종종 했었는데, 4월부로 가격이 전반적으로 천원 단위로 인상 되었어요! 기존 단골을 위한 서교동 할인 이벤트가 있었어서 참고해서 할인 받으시길..! 구움과자가 있어 좋아요.', 39, 1, NULL, SYSTIMESTAMP);
