INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '조용하고 한적한 분위기가 마음에 들었던 서교동 카페입니다 인근 주민들에게는 할인을 제공하고 편안한 분위기에서 커피와 디저트를 즐길 수 있었어요 화장실이 깨끗하고 안에 따로 위치해 바깥으로 나가지 않아도 된다는 점도 너무 편했습니다~', 42, 1, 'GOOD', SYSTIMESTAMP);
