INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '매장으로부터 할인받고 작성한 솔직한 후기입니다. 여기 휘낭시에 안 먹어본 사람 없게 해주세요ㅠㅠㅠ 찐 휘낭시에 맛집입니다!!!! 게다가 이날은 날이 추어서 귀리우유로 변경해서 카페라떼 마셨는데요~ 우와!! 우유스팀이 분자가 곱고 미쳤어요!!! 스타벅스 귀리우유로 변경한 카페라떼보다 100배 맛있어욜!!!!!! 여기에서 귀리우유로 변경해도 맛있구나라는 걸 처음 알았답니다!!!!!', 49, 8, 'GOOD', SYSTIMESTAMP);
