INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '크림이 너무 부드러워요~~ 시그니처 커피 꼭 먹어보길 추천합니다 커피맛도 일품이네요 홍대커피맛집이라고해서 갔는데 구움과자는 이미 소진되서 맛도 못봤어요 꼭 다시 갈꺼예요 ~~|', 48, 4, 'GOOD', SYSTIMESTAMP);
