INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '혼자 와서 커피 한 잔과 휘낭이 하나 먹다가 금새 다 먹고 하나 더 추가하게 되는 맛이에요🫶🏻 개인적으로는 그랑뵈르와 두 누아 추천 드려요! 무화과는 약간 호불호가 갈릴 수도 있을 것 같습니다🥹 두 누아는 부드러우면서도 진한 초코 사이에 콕콕 박힌 초코칩이 매력적이에요💝 단 걸 별로 좋아하지 않는데도 맛있게 잘 먹었습니다! 근처 올 일 있으면 꼭 들리는 곳이에요❤️‍🔥', 3, 10, 'GOOD', SYSTIMESTAMP);
