INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '요새 드물정도로 친절하고 맛있는곳이에요. 오랜만에 좌석으로 가져다주시는 커피 창가에서 마시니 행복 커피맛에 진심이셔서 라떼마시러 자주 올게요.', 20, 1, 'GOOD', SYSTIMESTAMP);
