INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '매장으로부터 할인받고 작성한 솔직한 후기입니다. 홍대 디저트와 커피 맛집! 커피는 드립 커피랑 시그니쳐 크림커피 마셔 봤는데 둘 다 정말 맛있네요. 디저트는 오후에 가니 거의 품절일 정도로 인기가 많아서 남은 종류로 다 사봤는데 마들렌 사이에 바닐라빈이 잔뜩 박혀있어서 풍미가 너무 좋더라구요!', 26, 2, 'GOOD', SYSTIMESTAMP);
