INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '남자친구랑 합정 데이트 나갔다가 발견한 카페인데요! 날씨가 좋아서 휘낭시에 포장해서 나왔는데 비주얼이 너무 좋아서 ㅠㅠ 선물용으로 대박일 것 같아요.. 물론 저도 저에게 주는 선물로다가 ㅎ 상자 포장까지 야무지게..(+1,000₩) 사실 그럴 필요까진 없었던 걸까 싶기도 한데 저는 만족합니다 >.<ㅋㅋㅋ 포장도 너무 예쁘게 해주시구~ 나중에 시간 많을 때 테라스에서 커피도 한 잔 해보고 싶네용! 일단 제가 먹어본 휘낭시에는 왕맛있었기에 홍대 휘낭시에 맛집으로 추천합니다~ ^^', 88, 14, 'GOOD', SYSTIMESTAMP);
