INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '커피 진짜 맛있어요! 무화과 휘낭시에도 맛있고 좌석이 많지 않아서 그런지 사람도 적당하게 있고 조용하게 대화하기 좋았네요 직원분들도 친절하시고 다음에 재방문의사 있습니다:)', 55, 14, 'GOOD', SYSTIMESTAMP);
