INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '인테리어도 마음에 들고 음료와 디저트도 너무 맛났어요. 크림라떼 크림 정말 맘에 들어요. 맛이 진하고 좋았어요. 크림이랑 커피 따로 먹다가 섞어서 먹으니 또 다른 말이네요. 아메리카노 싱글오리진으로 주문했는데 맛이 조금 독특하고 맛있었어요. 디저트는 기본인 휘낭시에 그랑 뵈르와 무화과 크림치즈 그리고 레몬 마들렌 괜찮았고 마들렌은 우리에겐 너무 달았어요. 휘낭시에는 딱 좋았어요.', 124, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '커피는 맛있어요. 원두가 맛있는데 중요한건.. 바리스타님이 아메리카노 만드는 방식이 맘에들어요. 크레마가 살아있는 아메리카노. 굿이에요! 근데.. 가게는 좀 작은편이고. 마들렌은 그냥그래요', 11, 6, 'GOOD', SYSTIMESTAMP);
