INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '가게가 작지만 홍대 바글거리는 곳에서 살짝 벗어나 있어서 제가 갔을땐 빈자리는 꽤 있었어요! 레몬 마들렌 넘 맛있어서 다시 가고싶어용 바닐라라떼 말고 바닐라빈라떼 있는 카페 최고! 짱맛있음 ~ 😍', 93, 19, 'GOOD', SYSTIMESTAMP);
