INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '갑자기 들어간 합정의 서교동 카페 당근 거래 바람 맞고 목이 타서 열 식히려 우연히 갔는데 커피 맛있었어요 무화과 크림치즈 와 말차 휘낭시에 맛나네용! 우드 느낌 나는 카페 이고 밖으로 보이는 나무가 햇빛에 살랑 살랑 그늘지는 풍경이 좋았습니당 치유~~~~~  인테리어도 이쁘고 음료 괜춚한대 사진을 못 찍었네유 💗', 27, 7, 'GOOD', SYSTIMESTAMP);
