INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '디저트 음료 모두 완벽해요 👍 베스트입니다 그리고 냥이들 너무기여워요 ㅜㅜ 글고 사장님 너 친절하셔서 기분 좋게 다녀왔습니다 번창하세용 🤩', 21, 6, 'GOOD', SYSTIMESTAMP);
