INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '어우 역에서 되게 머네요.. 자리가 얼마 없고 밀크티 맛은 평범했어요. 컵은 엄청 크고 무겁고 얼음이 너무 많이 들어있어서 한손으로 마시는데 손목이 아플 지경이었네요', 19, 1, 'BAD', SYSTIMESTAMP);
