INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '커피랑 디저트 맛이 넘넘 좋아요~~ 제가 라떼 덕후인데 고소하고 부드럽고 맛있는 라떼 맛집이에요 :) 아메리카노도 산미 없이 부드럽게 먹기 좋은 맛이었어요! 디저트도 맛있단 평이 많아서 기대했는데 진짜 맛있습니다ㅋㅋ 점심만 많이 안먹었으면 혼자서도 3개 먹을 것 같아요🤣 카페 분위기도 좋고 맛도 좋고 강추해요~~!', 89, 12, 'GOOD', SYSTIMESTAMP);
