INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '인테리어가 유행만을 따르지 않고 클래식한 매력이 있어서 인상이 일단 좋았어요- 매장도 생각보다 커서 머무르기 좋았고 커피랑 디저트 모두 신경써서 작업하시는 것 같아요 :)', 23, 7, 'GOOD', SYSTIMESTAMP);
