INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '마카롱은 말할 것도 없고 오늘 구움과자 처음 사서 먹었는데 너무 맛있어요..!!ㅠㅠ 곧 이사 가는 게 너무 아쉽지만 ㅠㅠ 그래도 근처 갈 일 생기면 꼭꼭 가려구요. 번창하세요 사장님~~~', 79, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '광진구의 자랑... 마카롱집 100여곳은 먹어봤다고 자부하는데 단연 밀리가 1등입니다 근데 이제 이사가네요ㅠㅠ 사장님들도 친절하시고 좋았는데 너무 x100 아쉬워요 진짜 아쉬움 더 많이 먹을걸', 128, 24, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '리밀앤밀리'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), 'ㅠㅠ..... 정든 마카롱집을 두고 이사해서 너무 슬펐거든요... 이젠 울지 않아요!!! 인생 마카롱 집을 찾았으니까!!!!!!!! 배달 어플로 처음 맛보고 뒤집어지게 맛있어서 방문도 해봤어요 아 세상에 시그니쳐 마카롱도 너무 맛있고 다른 마카롱도 짠득한 꼬끄에 필링이 단단하게 차있어서 넘 취향이었어요(맛별로 부드러운 필링도 있지만요 저는 단단한 필링이 좋아요) 로또 당첨되면 당일 생산 마카롱 다 쓸어와서 그 날 휴무하게 만들고 싶은 그런 마카롱 맛집입니다ㅠ.ㅠ 로또는 그른거 같으니 자주 방문할게요♡♡♡', 9, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차백도 홍대1호점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '작년부터 보이던 차백도 드디어 처음 방문했는데 이미 젊은이(...)들한테 엄청 핫한 모양. 포장도 엄청 해가고, 매장에서 먹는 분들도 많았음. 맛도 다양하고 버블티도 많고 해서 종류별로 먹어보는 맛이 있는듯. 망고포멜로사고 과일엄청들어가서 맛있었음.', 25, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차백도 홍대1호점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '새로 생긴 매장이라 엄청 깨끗합니다. 우롱소이빈밀크티랑 망고포멜로사고 먹었는데, 우롱소이빈밀크티는 고소한 우롱티에 짭쪼름한 치즈폼위에 콩가루까지! 완전 추천입니다!! 차백도는 생과일을 사용하여 주스를만든다는데, 냉장고를 보니 애플망고를 사용하시는거같았어요! 그래서 인위적인 단맛이아닌 진짜 망고의맛입니다! 시원한 과일주스 먹고싶을때 시럽말고 진짜 과일의 맛이 먹고싶을때 추천드려요!', 482, 88, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차백도 홍대1호점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '홍대올때마다 들리는 곳이에요 청결해서 좋고 생과일이라 좋아요. 음료가 좀 비싸긴한데 맛있어요 초창기때처럼 생과일류의 메뉴 많이 나욌으면 좋겠어요 직원분들 다 중국인이신거같은데 한국어 잘하는거 같거 친절하고 사람은 항상많네요', 6, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차백도 홍대1호점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '매장 안에 사람 엄청 많고 대기 좀 있는 편인데 생각보다 음료 빨리 나왔어요! 자주 방문하는 데라 맛은 당연히 있고 직원분들도 친절합니다 강추!! (카운터쪽에 영수증 리뷰 이벤트 포스터 걸고 있는데 여쭤보더니 끝났다고 하십니다 참고하셔요^^)', 12, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차백도 홍대1호점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '진짜 밀크티라고 해서 일부러 찾아왔는데, 그 보람이 있었던 것 같아요. 정말 진하고 맛있었어요. 홍대오면 또 오고 싶어요 ㅠㅠ', 18, 5, 'GOOD', SYSTIMESTAMP);
