INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차백도 홍대1호점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '차백도 소이빈 밀크티랑 망고스무디 정말 맛있어요!! 바쁘신데도 친절하시고 음료도 빨리 나옵니다 홍대오면 무조건 들려요🥹 집 앞에도 생기면 좋겠어요 ㅠㅠㅠ', 16, 3, 'GOOD', SYSTIMESTAMP);
