INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차백도 홍대1호점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '차백도 홍대점이나 신촌점에서 항상 홍차라떼 (ice or hot), 당도50%, 펄 추가해서 먹어요!! 배부를 땐 펄 말고 ''사고'' 추가해서 먹으면 넘 더부룩하지도 않고 씹는 맛도 있어서 딱 좋아요 굿굿', 39, 4, 'GOOD', SYSTIMESTAMP);
