INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차백도 홍대1호점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '직원분들이 중국인이세요 체인점인데  대량으로음료제조하여 준비하여 좀 실망했어요 신촌점은 망고포멜로시킴 그라데이션있고 과일양도 많은데 이곳은 미리만들어놔서 다섞여져있고 과일양도 랜덤이에요ㅠ', 370, 50, NULL, SYSTIMESTAMP);
