INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차백도 홍대1호점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '여기 제가 정말 좋아하는 밀크티에요!! 특히 쟈스민 밀크티 진짜 맛있어요!! 그리고 타로볼이랑 사고를 토핑으로 먹으면 조합이 좋아요!!', 28, 5, 'GOOD', SYSTIMESTAMP);
