INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차백도 홍대1호점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '차백도는 우유가 참 맛있어요! 말리라떼는 역시 당도100이 제일 맛있는 것같아요 많이 안달아서 70도 조금 밋밋한 느낌!(제입맛기준)', 13, 10, 'GOOD', SYSTIMESTAMP);
