INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차백도 홍대1호점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '요런 중국차 체인점 중 제일 맛있어요 차향이 아주 ㄹㅇ임 바빠서 음료 나올때까지 대기는 필요함 중국 현지처럼 큐알 주문이 되면 좋겠네여 추천은 자스민 밀크티!', 42, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차백도 홍대1호점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '타로볼 밀크티 랑 망고포멜로사고 시켰는데 밀크티는 맛있고 망고포멜로는 생각보다 별로였어요~ 밀크티 먹으로 재방문 올 거 같아요~', 25, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '차백도 홍대1호점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '너무 맛있어서 정말 좋아하는데 문제는 올때마다 음료나 펄이 품절이에요.. 한두번도 아니고 늦은 시간도 아니었는데 최근 방문 3-4번 모두 그러니까 기대하고 왔다가 실망하고 돌아가네요', 15, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '홍대 커스텀케이크로 유명한 우드톤 카페🎂 블랙 톤의 다소 어둡고 차분했던 인테리어에서 우드톤의 화사하고 깔끔한 무드로 공간을 리뉴얼한 커피벌스데이. 화이트 인테리어에 밝은 베이지톤 우드 가구들로 꾸며져 감각적이고 여유로운 감성을 자아내던 공간, 햇살 가득 들어오는 반지하의 따스한 분위기 속에서 쉬어갈 수 있었어요 또한, 커피벌스데이는 빵과 크림, 무스, 토핑을 직접 선택해 나만의 케이크를 만들 수 있는 커스텀케이크가 유명해요!🍰 감각적인 공간에서 커피 한 잔과 함께 커스텀케이크 꼭 맛보길 추천합니다', 26, 6, 'GOOD', SYSTIMESTAMP);
