INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '가게 분위기도 너무 좋고 원하는대로 케이크를 커스텀 할 수 있어서 너무 좋아요! 크림이랑 무스, 과일 종류가 다양해서 정말 원하는 맛 그대로 먹을 수 있을 것 같아요😻 친구 생일에 데리고 오고 싶은 카페에요😻💕', 30, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '카페가 너무 예쁘고 디저트가 특별해서 너무 추천하는 곳 입니다!! 친구들 혹은 연인과 놀러오면 후회없이 즐길수 있을 것 같습니다!! 맛있는 디저트와 친절하신 직원분 그리고 좋은 분위기 삼박자가 다 좋았어요! 추천합니다!🥰😆', 80, 17, 'GOOD', SYSTIMESTAMP);
