INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '사실 케이크가 유명한건 알고있었지만 커스텀케이크일줄은 몰랐습니다 위에 올리는 무스,빵,소스,과일까지... 서브웨이 재료담는 느낌이어서 신선했어요 저는 피스타치오무스와 무화과,모카크림으로 해서 만들었는데 두바이초코느낌 나고 신박했어요 그리고 가나디들도 안에 들어올 수 있다니 너무 좋아요 분위기도 좋고 사장님과 직원분도 친절하셨어요', 48, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '커스텀케이크는 처음이라 설레는 마음으로 하나하나 골라보았숩니다 ♥ 피스타치오 무스에 진짜 피스타치오가 오독오독 고소하게 씹혔구요 초코랑 바닐라랑 조합이 너어무 좋았어요 ◡̈ 복숭아도 완전 맛있게 먹었답니다ㅏ 특별한 날에 와서 먹었더니 더 싱나요 *⸌☻ັ⸍*', 0, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '인스타그램 첫 게시물 작성하셨을 때부터 우연히 알고리즘으로 알게 되어서, 꼭! 한 번은 방문해야지~ 하고 마침 생일 당일에 휴무를 받게 되어 방문했어요 ㅎㅎ 어쩌다보니 오지랖으로 꼭 오고 싶었다~ 신박한 컨셉이라 넘 좋다고 말씀 건내다가 생일인 걸 말씀드리게 되었는데 서비스로 과일 더 챙겨주셔서 넘 감사하구ㅠㅠ 괜히 말한 것 같아 넘 죄송했는데, 특별한 날에 와주셔서 감사하다고 오히려 좋게 말씀해주셔서 또 감사했습니다 ㅎㅎㅎ 다음에 또 기회가 된다면 재방문할게요ღღღ', 6, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '생일기념 커피벌스데이~🎂 커스텀케이크에 생일 초까지 너무 귀염뽀짝 ❣️ 과일도 바로깎아주고 신선하게먹을 수 있다! ㅜ.ㅜ매장분위기도 좋고 특별한경험을 할 수 있어서 추천추천', 35, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '홍대 올때 종종 들렸었는데 생각나서 방문했습니다. 리뉴얼해가 분위기가 많이 바뀌었는데 이전보다 미니멀하고 고급스러운 느낌이 들어요. 케이크는 커스텀 방식으로 바뀌었는데 피스타치오 무스 케이크도 여전히 맛있네요! 더 꾸덕해진 느낌에 진합니다.', 85, 15, 'GOOD', SYSTIMESTAMP);
