INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '생일 맞이해서 특별하게 커스텀 케이크 먹으러 왔어요 ! 상상이상으로 더 화려하고 예쁜 케이크가 나와서 좋았어요 ◡̈ 과일도 싱싱해서 맛있게 먹었습니다 !', 34, 4, 'GOOD', SYSTIMESTAMP);
