INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '리뉴얼 하기 전에도 케이크가 넘 맛있어서 종종 들려서 먹고 포장도 했었는데 리뉴얼 하면서 나만의 커스텀 케이크를 만들 수 있다니 너무 소중하고 특별할 것 같아서 완전 기대 하다가 늘 웨이팅 있어서 못 갔는데 오늘은 시간이 돼서 다녀 왔어용! 아니나 다를까 너무 맛있고... 가게 이름처럼 고유한 경험으로써 생일 같은 날을 보내는 것 같아 일상 속에서도 하루가 넘 진귀해짐을 느끼고 갑니다.. 행복이란 무얼까 늘상 고민하는데 사랑하는 사람들과 맛있는 거 먹는 게 전부이더라구요. 여기서 다시 행복의 정의를 내리고 갑니다!! 케이크가 맛있고 인테리어가 근사한 가게를 너머 사장님이 손님과 함께하고픈 탄생이 있다는 게 넘 멋지고 감사한 일이에요ㅠㅠ 번창하세요!!', 35, 9, 'GOOD', SYSTIMESTAMP);
