INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '너무 예쁘고 귀여운 카페에요!!! 이렇게 바로바로 커스텀해서 먹을 수 있는 케이크라니ㅠㅜㅜㅜㅠ 정말 너무 귀여워요ㅠㅜㅠㅜㅠ 너무너무 행복해지고 기분 좋은데 맛도 최고!!! 강추입니다💓', 89, 18, 'GOOD', SYSTIMESTAMP);
