INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '커스텀 케이크 너무 맛있어요!!!♥️♥️ 직접 무스를 고를수 있어서 좋은것 같아요!!! 여기 홍대 오면 꼭 방문해보세요 !!!🥰', 27, 4, 'GOOD', SYSTIMESTAMP);
