INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '커스텀 케이크를 주문했는데, 바닐라 시트에 딸기무스와 바닐라 크림을 더하고 위에는 복숭아, 샤인머스켓, 무화과까지 올려 정말 화려하고 상큼한 조합이었어요 🍑🍇 과일이 신선하고 달콤해서 크림과 시트와도 잘 어울려 맛있었답니다. 함께 주문한 자두에이드는 상큼하고 청량감이 있어 케이크와 잘 어울렸고, 아메리카노도 고소하니 맛있었어요 ☕️✨ 분위기도 아기자기하고 케이크 퀄리티가 좋아서 특별한 날에 딱 맞는 카페였어요. 🎂💛', 49, 0, 'GOOD', SYSTIMESTAMP);
