INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '케이크를 직접 커스텀해서 먹을 수 있는 곳은 처음이에요ㅠㅠ 너무 특별하고 종류도 고르기에 적당해서 너무 좋았어요, 방문하기만해도 기분 좋아질 것 같아요 🥰', 34, 4, 'GOOD', SYSTIMESTAMP);
