INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '피스타치오체리케이크가 특별하고 맛있어요. 얼그레이자몽은 생각보다 자몽이 적어서 거의 얼그레이케이크에요 커피도 산미적은 호불호 없는맛이라 맛있게 마셨어요!', 21, 1, 'GOOD', SYSTIMESTAMP);
