INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '커스텀 케이크 너무 귀여워요~ 직원분도 너무 친절하시고 원하는 재료로 케이크 만들어 먹을 수 있다는게 참 좋은거 같아요 ㅎㅎ,', 17, 0, 'GOOD', SYSTIMESTAMP);
