INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '케이크 너무 귀엽고 특별해요~~ 맛도 있고 친구들끼리 와서 기념하기 너무 좋아요!! 카페도 분위기 좋고 너무 분위기 있습니당 ~~:)', 179, 58, 'GOOD', SYSTIMESTAMP);
