INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '케이크를 골라서 만드는 게 참신해요! 플레이팅도 너무 예쁘게 해주시고 카페 분위기도 넘 좋아요ㅎㅎ!! 과일 종류도 다양해서 좋아요~', 22, 4, 'GOOD', SYSTIMESTAMP);
