INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '케이크를 직접 커스텀 할 수 있어서 더 특별하게 느껴졌던 카페에요 ٩(๑❛ᴗ❛๑)۶ 직원분도 너무 친절하시고 분위기도 좋았던 ♥', 52, 14, 'GOOD', SYSTIMESTAMP);
