INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '🍰 케이크 맛집 발견! 🍓 케이크 종류가 다양하고 크기도 커서 좋았어요! 이번에는 말차 브라우니 케이크, 시즌 한정 스트로베리 말차 라떼, 그리고 자두 에이드를 주문했는데, 모두 기대 이상으로 맛있었어요! 😍 가게 인테리어도 감각적이고, 날씨 좋은 날엔 야외 좌석에서도 즐길 수 있어 더욱 매력적인 곳이에요!', 80, 15, 'GOOD', SYSTIMESTAMP);
