INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '케이크 너무 예뻐용... 커스텀해서 먹을수 있다는게 너무 좋은거같아요 서브웨이 온 것 같아서 재밌었어요 ㅋㅋㅋ🫶🫶 재방문 의사 있습니당...💕💕', 11, 3, 'GOOD', SYSTIMESTAMP);
