INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '너무 맛있어 보여서 결국 테이크아웃해서 나왔네요😂 애견 동반 가능한 카페라 안에서 마시다보면 가끔 귀여운 댕댕이와 고양이들이 들르는 모습이 너무 좋네요!😃 요즘 날이 풀려서 밖에서 마시고가도 따듯하게 햇살받으면서 마시기 좋을것 같아요😎 여자친구가 뭔갈 더 마시려고 하니까 케익을 많이 사서 그런지 덤으로 받은 레몬밤까지,, 이쁜 카페 덕분에 기분좋은 오후 만들고 갑니다😁😁', 35, 1, 'GOOD', SYSTIMESTAMP);
