INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '음료들도 분위기도 너무 좋았습니다 😃 자리에 비해 짐이 많았는데 사장님께서 신경써주셔서 짐 놓을수있는 자리로 옮겨주신 덕에 소비한 금액에 있어 너무 만족스러운 서비스와 매장분위기,맛 이였습니다💪🏻💪🏻 케익들이 종류가 많아서 하나 먹어보고 싶었는데 밥을 먹어야해서😂 다음에는 같이 먹을수있게 오겠습니다😎', 72, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '기념일 홀케이크는 무조건 커피벌스데이 플라워케이크로 예약하고 있습니당💗발렌타인데이 선물용으로 예약했는데 빨간 장미가 너무 예뻐요오오...재주문이라고 사장님께서 음료도 서비스로 챙겨주셨어용 ㅎㅎ 예쁜 플라워케이크 오래오래 해주세요:)', 26, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '음료 네잔 케이크 두개 결제 후 다시 돌아가 그냥 영수증 달라고 하니 환불해주겠다고 하심 영문 몰랐으나 확인해보니 밀크티 두잔 결제 되어있음 결제 잘못됐는데 알고계셨는데 말씀을 안하셨나보네요? ————————— 오해가 있었을 수는 있다고 인지합니다만, 곧바로 오셔서 하신 말씀이 “어떤점이 불편”하시냐고 “말해주시면” 사과드리겠다. 본인운 더 주면 더주면서 장사했지 그런사람 아니다. 라고 말씀하셨는데, 이 상황은 사장님께서 계산실수를 해서 생긴 일이지 저희 일행이 불어일으킨 오해는 아닙니다. 지속적으로 유리하게끔 답변 수정하시는 모습이 보이네요. 유감입니다.', 36, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '블루베리케이크와 아이스아메리카노 주문했습니다. 산미없는 다크한 느낌의 커피도 맛있고 케이크도 진한 블루베리맛이 좋았습니다!👍🏻👍🏻 카페 근처에 돌아다니는 뚱냥이는 카페 고양이인지는 모르겠지만 귀엽습니다.', 25, 5, 'GOOD', SYSTIMESTAMP);
