INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '취업선물 케이크 뭘로 할지 고민중 말차케이크 찾다가 검색해보니 케이크 맛있다는 후기 보고 구매했는데 같이 먹었는데 맛있었어요!! 다음엔 카페에서 먹어볼게요', 18, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '커피 디저트는 괜찮았는데 알바인지 사장님인지 너무 불친절해서 기분이 별로였어요 사람이 여럿이가서 의자가 부족햇는데 엉덩이 한쪽도 못앉을거 같은 작은 의자를 주고 다른테이블에 남는 의자를 쓴다햇더니 안된다고 해서 매우 당황스럽고 어이가 없었습니다', 20, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '사장님이 친절하고 케이크가 맛도리인 커피 벌스데이입니다🥳🥳 저는 바나나티라미수를 주문했어요ㅎㅎ 경의선숲길 근처구용 저는 이 근처는 처음인데 홍대, 연남하고는 또 다른 분위기더라구요?! 카페도 그 분위기에 딱 맞았습니다!! 바나나티라미수는 바나나가 층층이 으깨져있고 바나나 크림이 같이 있는데 진짜 한입 먹으면 와! 바나나🍌라는 말이 절로 나올정도에요🙊 엄청 진한 바나나가 달달해서 은근 티라미수랑 어울리더라구요!! 그리고 케이크위에는 그냥 바나나조각인줄 알았는데,, 바나나 칩입니다 열어분..! 다른 메뉴까지 궁금해지는 케이크 맛집이었어여👍', 90, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '이렇게 불친절하다 못해 불쾌한 기분까지 느낀 카페는 처음이네요~ 사장이신지 알바이신건지 모르겠는 여자분.. 이렇게 영업하셔도 장사 잘되시니까 피드백 들으실진 모르겠지만 ㅠ 가게손님한테 큰소리내서 무안주고 그러시면 맘이 편하세요?ㅠ 가게가 이리 갑질하는덴 첨보네요~', 37, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '사장님 서비스 태도가 실망스럽습니다 애초에 커피랑 케이크두면 끝나는 작은 원테이블에 짐을 개인이 소지해서 두라 하질 않나 겉옷 둘 곳이 없어 손님오면 다시 가져다 놓을 생각에 의자를 끌어오니 화장실을 막는다며 눈치를 주더라고요 그건 저희가 사장입장에서 막았다고 생각할 수 있어 다시 제자리에 두었습니다 그런데 저희 말고 다른 테이블에도 똑같이 말하며 손님들이 앉아있는데도 굳이 비집고 들어가 테이블들을 떼어놓더라고요 저희 포함 세 테이블뿐인 시간이었습니다….그러고 결국 나간 팀만 두팀이었네요..', 110, 19, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '지나가는길에 야외에 앉으면 좋을 거 같아서 들어갔어요~ 마감 1시간 전에 가서 커피가 안된다고 해서 ㅠ밀크티 마셨는데 맛있었고 애플조각케이크는 처음이었는데 맛있더라고요!! 조용한 골목길에서 힐링하다가 갑니다. 멍푸치노 파는데 강아지들 데리고 많이 오는 곳 같아요~😆', 11, 9, 'GOOD', SYSTIMESTAMP);
