INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '바나나티라미스케이크 제발 꼭 드세요ㅠㅠ인스타 보고 달려왔는데 진짜 맛있어요!! 커피향은 진하고 바나나맛이 듬뿍 들어가서 초코바나나 좋아하신다면 강추입니다🤎🤎', 29, 3, 'GOOD', SYSTIMESTAMP);
