INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '역시 플라워케이크는 커벌데가 최고에요..🎀거의 부케수준으로 풍성하고 예쁜케이크여서 친구도 너무 맘에들어했습니당 기념일이나 생일때마다 찾게되네용! 대부분 플라워케이크는 맛이 그저그렇던데 여기는 맛도 다양하고 심지어 맛있음!!!', 2, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '몇번째 방문인지 셀수도 없는 단골집이지만.. 항상 신메뉴 도전하고 실패한적이없음😋 헤이즐넛이 들어간 바나나라떼는 달달+고소 조합이 미쳤고 바나나 티라미수 케이크는 그냥 사르르 부드러워서 잇몸으로 씹어도 될정도! 힐링하고 갑니다 라떼 없애지 말아주세요ㅜㅠ♡', 16, 1, 'GOOD', SYSTIMESTAMP);
