INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '친구랑 올만에 데이또 하다 우연히 커피숍 들어갔는데 난 바나나티라미슈케익 과 헤즐럿 향이난 바나나라떼를  시켜 먹었는데 완전 부드럽고 사르르 녹아내려 겁나 맛있었네요. 다리 아픈게 온데간데 없이 수다 많이 떨고 달달하게 데이또가 됐어요~~^', 21, 9, 'GOOD', SYSTIMESTAMP);
