INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '초당옥수수케이크 존맛..ㅠㅠ여름에만 나오는 메뉴라 기다렸어용!!!!오랜만에 방문했는데 역시나 친절하신 사장님과 믿고먹는 커벌데케이크였습니다🤍', 65, 18, 'GOOD', SYSTIMESTAMP);
