INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '디저트가 맛있고 너무~~~~~~~예뻐요!! 커피도 정말 맛있습니다! 분위기도 너무 좋아서 친구랑 즐겁게 잘 놀다왔어요! 사장님도 친절해서 기분좋았습니다 다음에 또 놀러갈게요!!', 40, 0, 'GOOD', SYSTIMESTAMP);
