INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '여기 자두에이드는 여름 그자체구요ㅜㅜ 피스타치오케이크..진짜.. 사장님 사는동안 많이버시고 오래 팔아주세요🥰🥰 단골 맛집이지만 올때마다 영업하고 싶어지는 맛👍또먹고싶다ㅠ', 7, 6, 'GOOD', SYSTIMESTAMP);
