INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '사진찍는용이었던것 같습니다.. 시트도 퍽퍽하고 크림도 너무 꾸덕한게 입에 달라붙는느낌으로 일반적인 케이크 느낌이 아니었습니다😅', 32, 6, NULL, SYSTIMESTAMP);
