INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '딸기생크림 진짜 딱 제가 너무 좋아하는 케이크맛이였네요!! 넘 존맛  다른것도 먹고싶었는데 밥먹고바로와서 배불러서 하나만 먹었네요ㅠ 아쉬워요 케이크가격은 좀 비싼편이지만 구래도 넘 맛있게 먹고왔어용✨ 분위기도 넘 좋았어요', 42, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '오 개인적으로는 기대가 너무 컸나봐요. 베스트 애플크림 케이크가 맛이 괜찮긴 한데 좀 너무 달고 예상대로의 맛이었어요. 달아서 조금 남겼어요. 주말에 가니 다 차서 평일에 다시 찾아갔더니 입장 가능했어요. 분위기 너무 예쁘고 케이크도 알록달록 동화 분위기에요. 비주얼은 극강인듯! 다른 케이크는 더 맛있을 수도 있을거같아요.', 24, 8, NULL, SYSTIMESTAMP);
