INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '둘 다 생크림이 많은 메뉴를 시켜 목이 맥혔지만.. 디저트도 너무너무 맛있고 음료도 맛있었습니다! 딸기맛이 정말 살아있어요! 근데 .. ㅋㅋㅋ 가장 최고였던 건 거기서 파는 강아지 수제간식인 것 같아요 강아지가 이제 도넛이라는 말만 들으면 눈이 돌아갑니다 ㅠㅠㅠㅠ 반려견 키우시는 분들 완전 추천드려요!', 34, 7, 'GOOD', SYSTIMESTAMP);
