INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '저 퀄리티면 안비싸다고 생각할만큼 고퀄이어서 눈부터 호강하고 먹었어요 비주얼만 예쁘고 맛은 그닥인 경우도 더러 있는데 여기는 맛도 맛있었음 ..!!! 블루베리 진짜 알차게 구석구석 박혀있고 크림도 많이 안느끼하고 아아랑 먹었더니 다 뿌수고 왔어요 서울가면 또 갈게요🫐💙', 33, 8, 'GOOD', SYSTIMESTAMP);
