INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '한두번 지인들과 방문한적이 있었는데 올때마다 마음에들어서 꼭 혼자 와서 힐링하고 와야지!! 다짐했는데 드디어 혼카 해보네요 ,, 힐링 제대루하고 평일 오후에 방문해서 그런지 조용했어요 그래도 5시쯤 되어가니 점점 가득 차더라고요 손님들 테이블에 케이크 하나씩은 다 있는게 넘 귀엽고 케이크맛집인게 맛더라고요 초코케이크 먹빵 하고 갔는데 제티초코맛 나요!! 담엔 말차브라우니도 먹고 애플케이크도 묵우야지.. 아 그리고 음료도 직접 가져다주셔서 넘 좋아여 행복가득한 크리스마스가 되시길 .,💖🎄', 40, 7, 'GOOD', SYSTIMESTAMP);
