INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '케이크 사진이 너무 맛있어보여 방문했는데 보이는 것처럼 맛있네요 ㅎㅎ 사과쨈이 가득 들어있어서 달달하고 좋았어요 ! 어텀펌킨은 생각보다도 호박맛이 강해서 호불호가 있을 것 같지만 전 괜찮았어요', 49, 1, 'GOOD', SYSTIMESTAMP);
