INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '서교동에 이런 곳이 있을 줄이야 포장도 너무 이쁘고 정성껏해주시고 맛도 좋아용 물어보는거도 친절하게 알려주시고 자주 가고 싶어요~~', 5, 1, 'GOOD', SYSTIMESTAMP);
