INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '와 진짜 인생 케이크랍니당 포장을 어쩜이러케 이뿌게 해주시나여 진짜 친구가 너무 좋아해서 저도 뿌듯했어여 이쁘게 해주셔서 감사합니다💗', 35, 2, 'GOOD', SYSTIMESTAMP);
