INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '아니에브 케이크가 미쳣서요 진짜 와 커피도 너무 마싯구 인테리어는 힙한데 케이크는 아기자기 하네요 아니 근데 진짜 개마싯슴 ㄹㅇ 먹어본 블루베리맛 케이크 중에서 원탑;;;;애플시나몬 처돌이로서,,,애플케이크,,?절대 못 참지 ㅋㅋ 크림도 완전 묵직하니 케이크 먹고 아메리카노 마셔주면 극락감 ;;;;', 35, 9, 'GOOD', SYSTIMESTAMP);
