INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '반려동물이랑 가기 좋은거 같아요 커피 에이드 하이볼도 팔고 케익맛집이예요! 케익이 진짜 맛났어요!! 강아지가 먹을수 있는 디저트 음료 멍푸치노도 있어서 좋았어요 가격이 좀 있어서 아쉽지만 그래도 그만한 가치가 있다고 봐요 너무 맛있어요!!', 77, 15, 'GOOD', SYSTIMESTAMP);
