INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '💖연남동 케이크 찐맛집💗🎀🍰찾으신다면 여기로 모이세용 블루베리맛이 진하면서 너무 맛있어서 깜짝 놀랐어용!!🥹😳 케이크 한입 먹는순간 반해버렸어요..💗 다른 케이크들도 다 먹어보고싶더라구요🤤 분위기갑이고 너무 좋았어요!!', 0, 9, 'GOOD', SYSTIMESTAMP);
