INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '어텀 펌킨은 달달한 호박맛인데 예상보다 맛있어요~ 밀리터리라떼 주문했는데 말차 맛이 쾌 강해요~ 그리고 오늘의 주인공 애플케이크 너무 달달해서 아메라카노랑 같이 먹는거 나아것같아요~ 결론은 다 맛있는데 너무 달달해요~', 32, 6, 'GOOD', SYSTIMESTAMP);
