INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '홍대 케이크 맛집이라 사람들이 가득차있어요. 평일에 방문했음에도 사람들이 만석이라 발길 돌리는 사람들이 있을 정도…!!! 디저트는 딱 케이크만 있는데 케이크 종류도 많고 다 맛있어보여서 고민하다가 블루베리케이크 주문했는데 너무 옳은 선택이에용 크림이 완전 요거트 상큼폭발하고 꾸덕꾸덕해용 그리고 음료도 레몬머스켓요거트 진짜 뷰드럽고 밀크티는 향이 깊고 맛있어용💜💜🤍🤍', 24, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '디저트러버, 특히 케이크 러버들이라면 홍대입구역 “커피벌스데이” 추천드려요! 케이크 종류도 정말 다양하고, 홀케이크 예약도 가능해서 최고예요 👍🏻 얼그레이자몽케이크 먹고 반해서 재방문하여 블루베리요거트와 제주말차브라우니 도전했는데 역시 케이크 맛집답게 전 메뉴 다 맛있었습니다! 🩷 다음번엔 피스타치오 케이크 먹으러 갈 예정입니닷!', 17, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '완죤 케이크 맛집이에여💖 말차케이크랑 cbd커피가 잘 어울려요ㅎㅎㅎㅎ 아아파라서 시그니처 커피 있어도 원래는 잘 안마시는데 리뷰에 cbd커피 칭찬이 많아서 시켜봤는데 안마셔봤으면 후회할뻔했어요..🥺 넘 맛있네용 크림이 넘 고소해요!!!! 가까웠으면 맨날 갔을텐데 서울사람이 아니라 넘 슬퍼요🥹🥹 직원분도 넘넘 친절하셨어요♥️', 80, 14, 'GOOD', SYSTIMESTAMP);
