INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '산울림 소극장 근처에 위치한 커피 벌스데이, 카페 이름처럼 벌스데이를 위한(?) 케이크들이 종류별로 많았고 야외 좌석과 내부 좌석이 많아서 여러명이 와도 쾌적했고 애견동반이 가능해서 더더욱 좋았습니다. 케이크 맛집 답게 꾸덕 달달 부드러운 케이크가 일품이었습니다.', 42, 4, 'GOOD', SYSTIMESTAMP);
