INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '음료는 무난했고 초코케익은 맛있었으나 애플은... 너무달았어요ㅠㅜㅠ 진짜 제 짧은 인생 최고로 단 극강케익이었습니다. 보통의 달콤한 케익을 원하신다면 애플은 피해주세요..! 버터크림 위주라 버터크림 안좋아하시는 분들께도 비추드립니다.', 30, 5, NULL, SYSTIMESTAMP);
