INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '홍대 케이크 원탑 중 한 곳! 화려한 비쥬얼만큼 케이크 달달하면서 부드러운게 신메뉴 초당옥수수는 톡톡 씹히는 식감까지 대박💛 커피도 맛있구 힙한 인테리어에 계속 손님이 들어오는 곳! 반려동물 동반 기능해서 귀여운 댕댕이도 잔뜩 보고 홍대 근처 기념일 케이크 좋아하시면 강추드려요!', 14, 8, 'GOOD', SYSTIMESTAMP);
