INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '머물렀다 가기 좋은 곳. 지난 주에 애플케이크랑 고민하다 못 먹은 블루베리요거트가 궁금해서 또 왔다. 맛있지만 에플케이크가 좀 더 내 취향이다. 다음에는 레몬케이크 먹으러 또 와야지', 10, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '아는 동생이 알려줘서 방문했는데.. 디저트, 커피 맛집이네요ㅠ 저는 시그니처 커피인 cbd커피와 피스타치오 케이크 먹었어요. 케이크 부드러우니 맛나고 커피 진짜 최곱니다!! 서리태크림이라고 해서 흑임자 생각했는데 훨씬 더 부드럽고 고소해요. 저는 커피를 마시면 잠을 못자서 샷 한 잔만 먹었는데 그래도 👍👍 제가 먹은 커피 중에 최고였어요!!', 17, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
