INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '🍰💖소오올직히 진짜 맛있어요,,,!!!와!! 아니 요새 카페가 진짜 많은데 케익이 진짜 맛있다!! 이런데는 없었거든요!?!????? 근데 여긴 진짜 졸라 맛있네요???!!!!! 심지어 커피도 맛있어요 !!!!!!! 커피랑 케잌먹고 와!!!!! 맛있다 담에 또와야지 한데는 여기뿐…! 와 진짜 추천입니다!!!!!🫶🏻🫶🏻🫶🏻🫶🏻🫶🏻 솔찌키 케익ㅇㅣ9천원이면 당연히 맛있어야한다고생각하는 1인이긴하지만, 공장에서 납품받는 케익을 칠천원에 파는 양심 없는 카페들도 많으니깐요?!?!? ㅠㅠ 돈 더주더라도 진짜 맛있고 !!!! 과일 옥수수 듬뿍 들어간 케잇을 먹겠어요!!❤️ 결론 추천!!!!!!!💓💓💓💓💓', 5, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
