INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '요즘 디저트류에 빠져서 검색후 일부러 경기도 광주에서 찾아갔습니다.골목길안쪽이라 찾기가 힘들었고 연남.홍대 검색후 몇군데 투어한건데 케익맛이 공포스러웠습니다.겉보기에만 화려할뿐,크림양이 너무 많아서인지,식용색소때문인건지 먹는중에 니글니글거리고 건강한맛이 아니라 장난감같은 맛이랄까요? 크림양이 많다고 다 니글거리진 않거든요.먹고난후 계속 찝찝합니다. 꾸역꾸역 먹다가 도저히 안되겠어서 버려버렸어요. 일부러 멀리서 추운날 찾아간건데 사실적으로 남겨야하는게 맞다생각해서 솔직하게 남겼습니다.눈으로 보기에만 화려하고 예쁜게아닌, 건강한맛,건강한 재료의 케익이었으면 합니다.괜히 찾아가서 괜히 구매했다는 생각이 들었고 정말 돈이 아까웠습니다...이런 혹평남겨본건 처음입니다..', 0, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '기대한거랑 너무 다르게 꽃이 생각보다 많이 옹졸하게 있어서 솔직히 좀 실망하긴했지만 그래도 귀엽다고 생각하니 괜찮았어요 비쥬얼에 좀 실망했지만 날마다 꽃이 같을 수는 없으니까요.. 복불복인가봐요 사장님은 친절해서 좋았어요 케익맛은 대체로 이런 예쁜케이크는 맛이 없다는 걸 알지만 그래도 케익 맛집이라 기대를 했는데 맛은 그냥그래요 안에는 카스테라 시트,오레오,시트,오레오,시트로 되어있고 안에 생크림은 따로 없어서 겉에 있는 생크림을 걷어내서 먹었어용 굉장히 뻑뻑하고 꽉찬 맛이에요 쿠앤크케이크맛을 생각했는데 좀 달라요 이벤트나 특별한 날에 선물로 하는 케이크이니 맛보다는 기분내는걸로 만족합니다! 꽃다발은 별도로 꽃집에서 따로 구매했습니다', 32, 5, NULL, SYSTIMESTAMP);
