INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '케이크가 어쩜 이렇게 이쁜지.. 사진을 아무렇게나 찍어도 다 너무 잘나와요 ㅠㅠ 맛도 넘 맛있어서 남자친구랑 기념일때마다 꼭 여기 케이크 먹어요!! 집 근처에 이런 곳이 있다니••🩷 행복하네요', 46, 9, 'GOOD', SYSTIMESTAMP);
