INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '세상에,,, 케잌 포장 너무 예뻐요ㅠㅠㅠ 커피도 너무 맛있고 케잌은 이쁘기도 이쁜데 맛도 극강이네요...🫶🏻 제대로 선물하는 기분이라 특별한 날마다 방문하기 좋을 것 같아용!!', 130, 22, 'GOOD', SYSTIMESTAMP);
