INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '와 여기 진짜.. 분위기 맛집에 커피맛집에 디저트맛집까지ㅠㅠㅠㅠ찐 또 방문하고싶어용... 모던한 분위기속 크림커피 맛도링으로 cbd커피랑 딸기 생크림 케이크 꼭 드셔주세효...🙏 cbd커피 위에 흑임자 크림너무 고소하고 커피 원두 넘 맛도링이고 딸기 케이크에 생딸기로 넘 맛도링ㅜㅜ 그냥 너무 맛있음.....', 35, 10, 'GOOD', SYSTIMESTAMP);
