INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '케이크 종류가 4종류인데 수제 케이크라서 엄청 꾸덕해요 어디서도 먹어보지 못했던 피스타치오 케이크 특별한 맛이네여 ㅋㅋㅋㅋ 커피도 찐하고 산미없어서 제 취향입니다 뭣보다 분위기가 갬성있고 반려동물 동반가능하고 테라스도 있어서 요즘같은 날씨에 딱좋은 홍대입구 숨은 카페 홍대 카페 또는 홍대 케이크 찾으시는 분들은 여기 오심 만족하실 것 같아옄ㅋㅋㅋ', 488, 78, 'GOOD', SYSTIMESTAMP);
