INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '말차브라우니케이크는 진한 말차와 단초코맛이어서 커피나 차랑 먹는게 좋습니다.  얼그레이와 새콤쌉싸름한 자몽이 잘 어울립니다. CDB커피는 서리태콩크림이 위에 올라가 고소하고 달콤합니다. 케이크가격대가 높은 점이 아쉽습니다.', 71, 18, NULL, SYSTIMESTAMP);
