INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '여기 조각케이크가 맛있어서 홀케이크도 주문해봤는데 역시 너무 예뻐요~~!  아이스아메도 산미 없이 고소하고 맛있어요! 역시 케이크맛집💓', 49, 9, 'GOOD', SYSTIMESTAMP);
