INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '자두에이드는 태어나서 처음 먹어 봤는데 너무너무 맛있었어요!! 그리구 사장님이 너무 아름답고 친절하십니다... 👉🏻👈🏻 갑자기 폭우가 와서 못 나가고 있는데 사장님께 부탁드리니 우산을 주셨어요 ㅜㅜ 재방문 의사 있습니다 사장님 번창하세요!', 9, 10, 'GOOD', SYSTIMESTAMP);
