INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '인테리어가 너무나 취저였던 CBD !!! ♥ 인스타갬성 가득했던 공간의 카페였습니다 내부도 넓은 편이였고, 스프링 펀치 에이드도 정말 맛있었어요 : )', 116, 24, 'GOOD', SYSTIMESTAMP);
