INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '주말 이용시간은 2시간 높은 테이블이 많아서 좋았어요 피스타치오 케이크는 생크림에 피스타치오를 섞은 맛인데 층 중간에 오레오가 함께 씹혀요 맛있는데 꽤 느끼하고 달아서 셋이서 한조각 먹어도 물릴듯 말듯 했습니다', 42, 9, NULL, SYSTIMESTAMP);
