INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '홍대 카페 커피벌스데이☕️ 맛있는 디저트로 케이크를 먹을 수 있는 곳! 미드 센추리 모던 분위기의 내부에 반했어요ㅎㅎ 어딜 찍더라도 사진이 예쁘게 잘 나와요~ 고소한 원두맛의 커피도 대박,,! 커피 맛집이에요ㅎㅎ', 4, 1, 'GOOD', SYSTIMESTAMP);
