INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '두시간 시간 제한이 있습니다 근데 아직 두시간 안됐는데도 (몇 분정도 남은 상황) 웨이팅 있으니 정리해 달라고 오시더라구요... 솔직히 다시 오고 싶지는 않네요 맛도 그냥 보통 인스타 카페 정도의 맛 입니다', 112, 20, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '페스티벌케이크 예약해서 받아봤는데 , 사진이 실물에 안담기고 왕짱 예뻐여!!!꽃 아래 워터픽 꽃여있어서 안전하게 먹고 꽃도 별도로 보관 할 수 있어서 좋았어용~! 쿠키엔크림 케이크였는데 맛까지 미쳤버려요~~~! ㅎㅎ', 33, 3, 'GOOD', SYSTIMESTAMP);
