INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '🐶반려동물 동반가능🐶 커피가 너무 맛있어요!!!! 시그니처 cbd커피가 정말 맛있습니다😋 인테리어랑 분위기 좋아서 사진 찍기 좋고 잘 나옵니다 반려동물 가능 카페답게 강쥐 음료 간식도 팔아서 좋아요 멍푸치노 엄청 잘 먹더라구요', 10, 7, 'GOOD', SYSTIMESTAMP);
