INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '플라워패키징 진짜 비쥬얼이 미쳤어요ㅠㅠ 너무 예쁘고 받자마자 너무 좋았어요ㅠㅠ 꽃안에 물주머니 해주셔서 돌아다니기도 문제 없고 조각케이크 포장도 너무 이뻐서 선물하기 딱 좋아요!! 👍👍👍', 98, 25, 'GOOD', SYSTIMESTAMP);
