INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '인테리어도 예쁘고 버터크림라떼 맛있어요 !! 쌉쌀한 말차 맛 좋아하시는 분들 제주말차브라우니 추천합니다 . . 크림에서 말차의 쌉싸름한 맛이 강하면서도 브라우니는 달달해서 맛있었어요 !', 0, 2, 'GOOD', SYSTIMESTAMP);
