INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '음료도 독특하고 맛있어요! 피스타치오케이크 처음 먹어보는 맛인데 오레오도 박혀있고 달달해요:) 버터크림라떼 짱맛..💗 골목에 있고 홍대속 이태원느낌 나는곳👍 매장분위기 적당히 차분해서 대화하기에도 너무 좋아요☺️', 11, 1, 'GOOD', SYSTIMESTAMP);
