INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '전형적인 비주얼카페 단호박크림치즈케익인데 단호박도없고 크림치즈도없음🥲 심지어 위에 올라간 단호박에서는 시큼한 맛이 나서 바로 뱉었어요 ㅠㅠ 그나마 단호박라떼는 단호박맛이 나는것 같긴 했는데 너무 달고,,,', 109, 24, 'BAD', SYSTIMESTAMP);
