INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '카페 감성도 너무 좋구 CBD커피 흑임자크림 너무 맛있어요! 구리고 피치코코블랙티는 맨날 마시고 싶을 만큼 제스타일이에요..✨👍🏻💛 케이크도 초코가 너무 질리게 단 맛이 아닌 딱 좋은 맛있는 단맛이라서 분명히 점심에 배부르게 먹고 카페 온건데 계속계속 먹게되는 매직-⭐️ 또 오고싶은 욕구 뿜뿜한 홍대카페 예요!❤️', 82, 13, 'GOOD', SYSTIMESTAMP);
