INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '배부르게 식사를 하고 방문하였는데 우선 케이크 비주얼에 주문을 하였고 맛을 본 후 배고픈 사람들처럼 흡입했어요!!! 크림과 초콜릿, 딸기, 빵 모든게 잘 어울려서 맛있었습니당!!! 그리고 매장 인테리어도 좋았고 앉을 자리들도 꽤 많았고 화장실도 내부에 있어서 좋았어용!', 68, 16, 'GOOD', SYSTIMESTAMP);
