INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '주말엔 2시간 제한이 있어요 내부가 어둡고 습해서 그런지 하루살이들이 많아요 제가 벌레들을 무서워하고 싫어해서 그런지 무서워 죽는 줄 알았어요.. 몸에 달라붙고 먹는데 앞에 날아다녀요.. 그 외에는 괜찮습니다', 86, 14, 'BAD', SYSTIMESTAMP);
