INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '홍대 가면 이젠 무조건 들리게 되는 단골카페ㅠㅠ 사장님 항상 친절하셔서 갈때마다 기분좋아져요😊 우리 댕댕이도 반겨주시고~상냥한 사장님덕에 단골됐습니다..! 번창하셔요~', 119, 24, 'GOOD', SYSTIMESTAMP);
