INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '매장 분위기가 너무 좋아요~ 신맛 안좋아하는데 여기 커피는 고소한게 딱 제스타일이었어요!! 야외 테이블도 있던데 탐나드라구요 분위기 맛 등등 전반적으루 다 좋았습니당~~', 9, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '테라스에서 먹는 크로플이란 🤍 넘 맛있어요 취저 💗💗🫠 여기 커피도 맛있어요 ㅠㅠ날씨 따땃해서 테라스에서 먹으니까 기분 좋네요 사진도 잘나오고 매장도 이쁘구 담에 또 올게요 🙌🏻🙌🏻', 9, 7, 'GOOD', SYSTIMESTAMP);
