INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '케이크가 예쁘긴 한데 맛은 별로였어요..ㅎㅎ 평소에 단 음식 잘 먹고 보통 케이크 두 조각은 기본인데 여기 케이크는 많이 느끼했어요. 크림이 입안에서 부드럽게 녹는다기 보단 입안에 미끌거리게 남는 느낌. 녹차랑 피스타치오맛 먹었는데 피스타치오는 피스타치오마루 아이스크림이랑 비슷했고 녹차는 진하긴 한데 끝에 쓴맛이 많이 남았어요. 포장도 조금 실망이었어요. 꼭 2천원을 추가해야만 예쁜 모습 그대로 가져갈 수 있고 추가 안하면 케이크 높이보다 낮은 도시락 상자에 넣어줘서 윗면 크림 뭉개지는 거 감수해야합니다. 뚜껑이 닫히지도 않아서 살짝 열린 채로 스티커로 고정시키시더라구요.이건 미리 안내해주시긴 했는데 다른 카페에선 기본적으로 해주는 서비스를 돈 내고 하라니까 좀 그랬어요.', 15, 0, 'BAD', SYSTIMESTAMP);
