INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '핑크베리딸기크림 케이크 미쳤어요💖딸기맛이 듬뿍 ㅠㅠ 여름에 딸기케이크 먹을수 있어 행복해~사장님 정말 맛있는것만 만드시는 배우신분들🥹💖🫧', 50, 7, 'GOOD', SYSTIMESTAMP);
