INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '카페 분위기도 너무 좋은데 디저트랑 음료도 진짜 너무 맛있어요ㅠㅠ 사장님도 너무너무 친절하셔서 기분 좋게 먹고 왔어요!! 다른 케이크 맛도 궁금해서 케이크 도장깨기하러 또 올게요!! :)', 40, 6, 'GOOD', SYSTIMESTAMP);
