INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '진쨔 새로운 케익 나올때마다 다 먹어보는 중인데 어쩜 맛없는 케익이 없아요,,🥹 갬동받아서 칭구생일기념 홀케익도 주문해봤습니다!! 대만족 대성공이에요~~', 26, 0, 'GOOD', SYSTIMESTAMP);
