INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '오늘도 맛있는 커벌데 케이쿠.. 🍰🍋 홍대 올 일도 없는데 레몬케이크 먹으러 왔어여💖 ㅠ_ㅠ 진짜 저랑 평생가여.. 할머니되서도 먹을거야..', 4, 4, 'GOOD', SYSTIMESTAMP);
