INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '버터크림커피는 맛있었는데 검은색 커피는 살짝 공차같은 이 났어요..! 인테리어는 정말 예뻤어요. 인스타느낌 낭낭한 카페였어요. 딸기초코케이크에 있는 초코크림 꾸덕하니 맛있었습니당🫶 사람이 많이 없어서 수다 떨기 좋았던것 같아요.', 47, 2, 'GOOD', SYSTIMESTAMP);
