INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '제가 진짜 애정하는 맛집인데 이번 신메뉴로 피스타치오 오레오 케이크가 나와서 먹어봤어요 ☺️ 찐한 피스타치오 맛에 달달한 오레오로 포인트! 진짜 여긴 케이크 맛집! 거기에 선물하기 딱인 센스만점 패키징까지 👍 다음에 친구 선물하러 또 들릴게요 🥰', 30, 1, 'GOOD', SYSTIMESTAMP);
