INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '여기 분위기 너무 좋은것같아요ㅎㅎ 홍대 인데도 아늑하구 핫플레이스 느낌 제대로에요ㅎㅎ 스피커가 너무 이뻐서 보니까 좋은 스피커더라구요~! 그래서그런지 음질이 너무 좋구 외국스러은 느낌이나요! 인스타 감성의 인테리어와 맛있는 케이크가 넘 특색있구 레몬케이크 특히 넘 맛있게 잘먹었어요ㅠㅠㅠ 저는 시그니처 음료 청귤에이드도 마셨는뎅 넘 상콤합니당 ㅎㅎ 홍대에서 사람만날일이 많은데넘 좋은것같아요 요기 ㅎㅎ~! 자리잡으면 떠나기가 힘드네요…ㅋㅋ 아늑해서그런가ㅠ 암튼 담에 또오겠습니당🍎', 396, 49, 'GOOD', SYSTIMESTAMP);
