INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '점심먹고 들린곳인데 커피도 산미없고 부담없는 맛이여서 넘 맛있었고 , 인테리어 소품들이 너무 이쁘더라고요 ~ 다음에 여기서 여유롭게 커피마시면서 공부하기에도 좋을거 같았어요 ❤️', 35, 6, 'GOOD', SYSTIMESTAMP);
