INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '깨끗한 내부 화장실과 넉넉한 좌석, 멋진 인테리어가 만족스러워요 ♥️ 얼그레이 케이크 / 자몽이 2단으로 들어가서 아주 깔끔해요 크림에 찻잎이 그대로 들어가서 아주 진하고 부드럽네요. 밀크티를 마시는 것 같아요. 시트도 말랑하고 촉촉해서 식감이 좋습니다 청귤 그린 소다 / 보기에만 예쁜 게 아니라 맛도 좋아요 달콤함과 산미가 잘 어우러지고 톡톡 쏘는 탄산의 맛이 입을 깨끗하게 정리 해 주는 느낌! 추천합니다 좌석도 많고 빛이 잘 들어와서 사진이 예쁘게 잘 나와요 🫶🏻', 104, 22, 'GOOD', SYSTIMESTAMP);
