INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '매장 분위기가 따뜻하고 너무 좋아요🥰 휴식을 하기에 너무 좋은 카페인데다가 디저트랑 커피도 너무 맛있었어요! 반려동물과도 함께 올 수있는 곳이라 더 편안함이 느껴지는 공간인 것 같아요👍 케이크 먹으러 또 가고싶어요🥰', 80, 14, 'GOOD', SYSTIMESTAMP);
