INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '벌써 세번째 방문입니다. 언제나 기분좋아지는 커피벌스데이, 평일은 처음인데 이른시간이라 손님도 별로 없었고 조용한 장소에서 맛있는 케익과 음료를 먹으며 책을 읽었어요 행복하고 의미있는 시간들이었습니다, 간간히 찾아오는 강아지 손님들도 너무 귀엽고 ......좋았어요 다음에 또 방문할게여!', 15, 9, 'GOOD', SYSTIMESTAMP);
