INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '오늘도 여전히 맛있는 커벌데 (커피벌스데이) ㅠㅠ 오늘도 저의 최애 케이쿠 레몬케이크는 최고 맛있어여 🍋 멀어졌는데 생각나서 또 왔어염..', 26, 4, 'GOOD', SYSTIMESTAMP);
