INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '오트썸머라떼, 버터크림라떼, 레몬케이크 먹었어요 커피들 다 달달하니 맛있고 케이크도 너무 달지 않고 상큼하니 맛있습니당 분위기도 좋고 인테리어도 예쁘고 사진이 잘나와용', 11, 5, 'GOOD', SYSTIMESTAMP);
