INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '딸기초코케이크 먹었는데 디저트가 넘 맛있어요👍👍👍 카페도 예쁘고 애견동반도 가능해서 제약없이 오시기 좋을 것 같습니다. 공간도 꽤 넓어서 편안하게 머물다 왔어요.☺️', 60, 12, 'GOOD', SYSTIMESTAMP);
