INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '근래 갔던 카페중 제일 비위생적이였던 것만 빼면 좋은 공간이라 생각해요 :) 앉으려는데 자리에 음식물 굳어서 묻어있구,, 머리카락에 벌레 사체들이 너무 많아서 으악했는데 테이블도 커피 굳어있는 것 보니 청소를 안하시는 것 같더라구요,, ㅜ 그것만 빼면 감각있고 애견 동반이되어 강아지도 볼 수 있구 좋더라구요. 케익은 말라있다해야하나 퍼석하구 치즈맛이 별로 안나서 제입맛에는 그냥그랬는데 맛나보이는 디저트가 많아서 담에 간다면 다른 디저트류 도전해보고 싶어용  근데 위생이 ㅜㅜ 화장실에 휴지 없어서 여쭤봤더니 직원분이 휴지 없다고 하셔서  핸드타올 쓴 것도 생각나네요 ㅜ 무튼 다음에 간다면 뭔가 개선이 되어있길바라는 곳입니당 공간이 주는 느낌은 좋아요 :)', 20, 6, 'BAD', SYSTIMESTAMP);
