INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '할미입맛이라 흑임자 들어간 라떼 넘 맛있고요! 애견 동반 가능한 카페라서 수다떠는동안 4마리의 강지를봄.. 귀여워.. 주말은 2시간 제한 있다곤 하셨는데 대기자가 없으면 따로 나가라고는 안 하시는것 같아요.', 60, 17, 'GOOD', SYSTIMESTAMP);
