INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '카페 감성 낭낭해서 넘 좋아요😆😆 포토스팟도 인스타 감성 낭낭해서 셀카찍기 좋아요🥰 단호박케이크  단호박 맛 찐해서 꼬소하고 꾸덕꾸덕 맛있고 건강한 맛이에요😁😁 CBD커피는 흑임자가 들어간 커피라 믿고 먹을 수 있는 맛입니다~~ 비주얼도 감성 미쳤어요ㅎㅎ 막찍어도 잘나오네요ㅎㅎ 티라미수라떼 마스카포네치즈크림 풍미가 가득 담겨있어서 달달한거 땡길때 좋을 것 같아요!! 전체적으로 아주 굿굿인곳입니다 🥰', 13, 0, 'GOOD', SYSTIMESTAMP);
