INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '분위기... 완전 내서타일.... 우리강아지도 친구들실컷만나고... 애견동반되고 인테리어 센스최고에 음료도맛있고... 케이크먹으러 또갈게요...💓', 37, 8, 'GOOD', SYSTIMESTAMP);
