INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '음료와 케이크가 맛있고 크리스마스에 진심인 카페를 발견해서 넘 좋아요! 완벽한 크리스마스 분위기를 원허신다면 무조건 추천이요!!! 카페 뮤직플레이리스트 훔쳐오고싶을정도로 좋아요,,, 노래듣느라 집 못갈지경', 30, 8, 'GOOD', SYSTIMESTAMP);
