INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '사장님 너무 친절하십니다 ㅎㅎ 위치도 상대적으로 한적한 곳에있구, 조용한 분위기라서 너무 좋았습니다. 친구들이랑 편안하게 대화하다 왔습니다 :) 또 올거같애요', 53, 18, 'GOOD', SYSTIMESTAMP);
