INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '서리태크림이 올라간 시그니처 메뉴를 선택했는데 정말 고소하고 꾸덕꾸덕한 크림이 기분좋게 하는 맛이었네요! 민트티도 시원~해서 입안이 개운해져요 얼그레이 케이크도 향이 좋아서 계속 먹게되네요! 홍대에 분위기도 좋고 예쁜 카페 발견해서기분 좋네요❤️🫶🫶😊', 84, 15, 'GOOD', SYSTIMESTAMP);
