INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '이전부터 너무 오고싶었던 곳이였는데 분위기도 너무 좋고 예쁘고 맛있고 다 좋았지만.. 가게 사장님이신지 직원분이 너무 불친절하셨어요', 83, 17, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '분위기 맛집 홍대카페 커피 벌스데이✨ 힙한감성과 고요한 느낌이 공존하는 매장이였어요. 커피 벌스데이의 레몬버터크림 케이크는 새콤달콤함과 부드러운 느낌을 느낄 수 있었어요. 버터 좋아하시는 분들께 강추🙌🏻 각각 매력이 뚜렷했던 음료들과 컵에 커피 벌스데이만의 감성으로 꾸며져서 나와서 더 예뻣어요,,🧏🏻‍♀️ 친구랑 시간가는 줄 모르고 수다타임 하구왔어요 ㅎㅎ', 19, 10, 'GOOD', SYSTIMESTAMP);
