INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '오 일단 인테리어가 정말 예뻐서 여기저기 다 포토존이네용 ㅎㅎ 시그니처와 어텀메뉴들이 맛잇어요 cbd커피는 흑임자라떼인데 제주도 그 맛 살짝 생각남...그리고 피스타치오라떼 완전 취저ㅠㅠ 스티커 있는것고 넘후 좋구연. 담엔 단호박크림치즈케잌도 먹어보러 가야겠어용~~', 0, 3, 'GOOD', SYSTIMESTAMP);
