INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '푸들아가 데리고 홍대 볼일 있어 갔다 가장 가까운 애견동반 카페 땀 식히러 감 사람 많고 인기 좋고, 디저트가 맛있는지 다들 디저트 많이 시켜 먹더라 다만 대부분 초행 애견동반 카페든 식당이든 그렇듯이 강아지 넣은 캐리어를 의자에 놓고 내 옆 가까이 끌어다 놓으면 길을 막아서요, 다른 손님 불편하서요, 라며 미처 동의하지 않아도 의자와 캐리어 등을 마구 그냥 도로 갖다 놓는다. 필요한것, 정리할 새도 주지 않은채 막무가내로 무안 줄 거면 애견동반 운영 자체를 하지를 말기를. 그러고 단골이신듯한 견주 님은 자리가 없어서 카운터 바로 앞에서 다른 손님들 계산에 불편주든 말든 용인하는건 무슨 대처인지,', 112, 25, 'BAD', SYSTIMESTAMP);
