INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '찻잎이 크림에 섞여있어서 씹는 맛도 있고 얼그레이 향도 확 나요. 시트도 짱 부드러움!! 하이볼도 팔아서 예쁜 카페에서 낮술하기 넘 좋네용', 26, 2, 'GOOD', SYSTIMESTAMP);
