INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '개인적으로 요 근래 간 카페 중에 제일 좋았어요. 음료도 다 맛있었고 케이크도 맛있어서 만족스러웠지만 인테리어가 예쁘고 조용한 분위기가 넘 좋아서 재방문 하고 싶은 카페였어요. 사장님이 직접 음료도 가져다 주세요ㅎㅎ 친절하셔서 더 기분 좋았습니다! 담에는 비주얼 대박이었던 초콜렛무스 케이크 꼭 먹어볼 거예요ㅎㅎ', 6, 1, 'GOOD', SYSTIMESTAMP);
