INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '반려동물도 함께 어울릴 수 있는 공간이라 너무 귀엽고 좋아요☺️🫶🏻 다만 매장 내에서는 일회용품 사용 금지로 알고 있는데 종이컵으로 주셔서 아쉽ㅠ', 51, 17, NULL, SYSTIMESTAMP);
