INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '홍대 조용한 위치에 감성카페가 있다고 해서 남자친구와 갔다왔어요! 외부 테라스에도 캠핑장같은 느낌으로 꾸며져있고 내부도 따뜻한 분위기에 조용해서 너무 좋아요! 거기다가 케이크는 또 왜이렇게 부드러운지 ㅠㅠ 케이크 맛집 맞네요 빵도 엄청 부드럽고 크림도 촉촉하니 완전 맛있었어요 👍🏻 그리고 음료로 오트썸머밀크랑 cbd커피 시켰는데 오트썸머밀크 왜이렇게 맛있죠..? 바닐라 아이스크림과 연유의 조합도 좋고 커피도 너무 맛있어요🥹 다음에 다시가서 먹고와야겠어요 ㅎㅎ 홍대 카페로 강추합니당 ❣️', 28, 4, 'GOOD', SYSTIMESTAMP);
