INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '나의 레몬케이크 최애집이 너무 유명해져서 기쁘면서 슬퍼요..🥹✨진짜 한결같이 너무 맛있는 케이크 맛집…🍋 평생 해주실거죠..?', 2, 8, NULL, SYSTIMESTAMP);
