INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '시그니처메뉴인 바질토마토에이드와 CBD라떼 마셔봤어요! 바질토마토에이드는 처음 마셔봤는데 생각보다 너무 맛있어서 깜놀! 토마토랑 바질이 음료랑 너무 잘어울리면서 맛있었어요👍🏻 CBD라떼는 고소한 서리태크림이 올라간 아인슈페너 라떼 느낌이었는데 달달하고 고소해서 완전 짱맛! 강추해요 요거트케이크도 시켜봤는데 과일도 가득 들어가고 크림도 요거트크림이라 너무 맛있었어요🥰 인테리어도 넘 예쁘고 힙해서 사진도 잘나와요!! 인스타감성 낭낭합니다 ㅎㅎ', 382, 75, 'GOOD', SYSTIMESTAMP);
