INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '카페 내부도 너무 이쁘고 음료랑 디저트도 맛있어요!!! 액자랑 인테리어도 완전 취향저격😆 그리고 홍대 안쪽이라 보다 조용하고 쾌적해서 넘 좋은 거 같아요!!! 다음에 또 방문할게요💘', 32, 3, 'GOOD', SYSTIMESTAMP);
