INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '두번째 방문인데, 여기 치즈케이크 너무 맛있어서 또 방문했어요! 촉촉하고 겉이 달달해서 너무 맛있어요 ㅠㅠ 다른 케이크류도 많았는데 다 맛있어 보였어요 :)', 70, 15, NULL, SYSTIMESTAMP);
