INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '홍대 가면 꼭 가는 카페인데 언제 가든 분위기에 취하고 맛에 취하고,, 나만 알고 싶은 카페에요 휴ㅠ 양심상 케익 하나만 시키는데 진짜 요즘 홀케익 주문해서 퍼먹고 싶어용 히히 앞으로의 신메뉴도 넘 기대돼용🤍🤍', 27, 1, NULL, SYSTIMESTAMP);
