INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '내생일날 또 가고싶은 커피벌스데이~~디저트랑 커피 맛은 당연하고 어딜찍어도 갬성 사진 건질 수 있던 커피벌스데이!!! 저는 혼자가서 초코케이크 먹었는데요! 둘이 가서 2개 시켜도 행복할 곳입니다..🫶🏻', 79, 12, 'GOOD', SYSTIMESTAMP);
