INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '아아 맛집 간만에 찾았어요 댕댕이랑도 같이 갈 수 있고 댕댕쓰 간식까지 🤍 간만에 편하고 깨끗한 카페 찾아서 기분 좋아서 리뷰 씁니다 ~! 케이쿠도 맛있음 하지만 여기는 아아 맛집 ☕️', 428, 68, 'GOOD', SYSTIMESTAMP);
