INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '초코케이크친구가 맛있다그래서 와봤는데 진짜미쳤어요 달달하고 크림가득하고요...재방문해서 다른케이크들도 하나씩 뿌시려고요 넘 맛있습니다', 12, 0, 'GOOD', SYSTIMESTAMP);
