INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '케이크와 음료의 기대를 안고 방문한 보람 있습니다🫶🏻인테리어가 모던하고 매장 내 분위기가 좋아서 더 맛있게 느껴졌어요.무엇보다 케이크가 독특해서 맛봤는데 전 꼭 추천드려요✨얼그레이가 입안 가득 퍼지고 시트가 폭신하다 못해 부드럽기까지🍃🫧해서 꼭 드셔보시라고 추천해요. 케이크 존재감 엄청나네요🫧🖤🎂', 9, 2, 'GOOD', SYSTIMESTAMP);
