INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '여유, 공간, 모던과 참 잘어울리는 카페에요🍃 유독 시그니처 메뉴들과 독보적인 감성을 가진 디저트들이 많은데, 서리태크림, 바질, 토마토가 들어간 메뉴 신기해용 CBD커피는 쫀득쫀쫀한 서리태크림이 굿굿! 버터크림같은 느끼함이나 달달함은 덜고 그 자리에 고소함이 있어요. 애플망고요거트는🥭 지인한 달달상큼이 느껴져서 기분전환하기 딱이었습니당. 논커피러라면 강추하는 메뉴! 커벌데 케이크는 정말 추천하고 싶은게 겉보기에도 재료가 듬뿍 들어간게 보여요. 얼그레이를 굉장히 좋아하는데 잎 하나하나가 다 씹히는 얼그레이케이크는 처음이었습니다🎂. 그렇다고 자몽이 묻히지 않아요 홍차향, 자몽향 둘 다 존재감이 엄청나네요. 입안에서는 풍부함 가득…👍🏻', 45, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
