INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '비오는 날 방문했던 곳이여요 여기는 흐린 날이 더욱 예쁜 곳 같아요! 짙은 녹색과 살짝은 어두운 인테리어가 잘 어울려요 디저트는 말해뭐해 너무 맛있었어요 티라미수 라떼..! 제 원픽입니다 ☕️ 번창하세요 🌿', 51, 18, 'GOOD', SYSTIMESTAMP);
