INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '여기는 진짜 사람들한테 백번 추천하고싶은곳 시그니쳐 커피 하나같이 존맛에 분위기도미침 골목에있어 찾아가기 번거로웠는데도 비오는 날에도 사람 다차잇음,, 캬 미쵸', 90, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '카페는 조용하고 이쁜데 지금 겨울이라 추워서 난방을 틀어달라고 했었는데 실내온도에 맞춰져 있다고 처음엔 안틀어주시더라구요 손님도 많이 없었고 나중에 손님 들어오니까 틀어주셔서 그 부분이 좀 불편했었습니다 많이 추웠었거든요 디저트는 맛있었습니다', 16, 0, NULL, SYSTIMESTAMP);
