INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '우연히 걷다가 들어온 카페였는데 매장이 너무 예뻐서 반해버렸어용 골목에 있는데도 오후가 되니까 금방 만석이 되어버리는 핫플이었다는❤️‍🔥', 39, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '사장님도 너무 친절하시고 디저트 꼭 드세요 진짜 너무 맛있습니다ㅠ 제가 먹었던 디저트 중 최고라고 생각해요! 시그니처 흑임자 들어간 cbd음료도 추천 합니다 가까우면 매일 가고싶어요ㅠ', 27, 1, 'GOOD', SYSTIMESTAMP);
