INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '커벌데… 레몬 케이크 평생 해주세요..🍋 평일 오전에 가면 귀여운 강아지 친구들과 햇볕에 쏟아지는 자리에서 책읽고 가볍게 작업하기에도 좋아요! :3 버터크림커피도 맛있고 블루베리 케이크도 심.각.하게 맛있어요… 🫐 😠✨', 78, 15, 'GOOD', SYSTIMESTAMP);
