INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '모던한 인테리어가 트렌디하고 예뻐서 사진 잘 나와요! 바질토마토소다는 독특하고 처음 먹어본 맛이에요, 애플망고요거트는 무난해요!! 크로플은 비주얼만큼 맛있어서 나오자마자 사진찍고 사라졌네요..ㅎㅎ', 29, 9, 'GOOD', SYSTIMESTAMP);
