INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '거의 제 방앗간인데요,, 메뉴가 거를게 없이 다 맛있어서 그때그때 땡기는거 암거나 먹어도 실패하지 않아용!! 앞으로의 신메뉴도 넘 기대돼요🥹', 11, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '단골이라 커벌데 케익 진짜 자주 먹는데 사장님께서 신상케이크라고 추천해주신 오렌지카라멜케이크 너무 맛있어요!!또 먹으러올예정❤️‍🔥', 172, 74, 'GOOD', SYSTIMESTAMP);
