INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '홍대에 있는 커피벌스데이 입니다. 대표메뉴 중 하나인 CBD커피를 주문했습니다. 서리테크림이 고소하고 커피랑 잘 어울려서 맛있었습니다. 케이크는 먹진 않았지만 정말 맛있어보이네요. 손님이 몇 분 더 계셨지만 카페 분위기도 조용하고 좋았습니다.', 10, 0, 'GOOD', SYSTIMESTAMP);
