INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '케이크가많아서좋았어요 고르기힘들었네요.. 대표케이크먹었는데 담엔 다른것도 먹어봐야겠어요 상큼하고 아메랑 잘어울렸습니당 커피맛도 굿! 포장해어먹었는데 담엔 인테리어가 이뻐서 또 와야겠어용ㅎㅎ 밖에두자리있어 좋네용!', 0, 2, 'GOOD', SYSTIMESTAMP);
