INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '레몬버터케이크 괜찮았지만 얼그레이 자몽 케이크나 썸머라떼가 품절이라 아쉬웠어요. 커피 맛은 보통이에요. 사람이 많은 건지 가게 소리가 울리는 건지 손님들 대화하는 소리가 너무 커서.. 대화하기가 힘들었네요.', 3, 7, 'BAD', SYSTIMESTAMP);
