INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '커피벌스데이 아니고 케익벌스데이 인가봐요..커벌데 케익 다 맛있는데 요즘엔 얼그레이자몽 케키에 빠져벌임ㅠㅠ..자몽이 살살 녹아요 정말 너무 맛있어요ㅠㅠㅋㅋㅋㄴㅋㅋ내일 또 먹을지돟ㅎㅎ', 29, 8, 'GOOD', SYSTIMESTAMP);
