INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '레몬케이크 꼭 드세요..!! 이쁘기만 한게 아니라 맛도있네여 디저트 종류가 다양해서 다 맛보고 싶었는데 ㅠㅠ 담에는 다른거 또 먹어봐야겠어여 커피는 고소하고 다크한게 제가 딱 좋아하는 맛이에요 :-)', 80, 14, 'GOOD', SYSTIMESTAMP);
