INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '초코케이크 너무 맛있네요 진짜 인생케이크에요ㅠㅠ 커피도 맛있어서 같이 먹으면 순식간에 먹을수 있어요!! 사장님들도 너무 친절해서 좋았어요', 0, 4, 'GOOD', SYSTIMESTAMP);
