INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '버터크림라떼 처음 시켜먹었는데 너무 맛있어서 혼자 두 잔이나 마셨어요..ㅋㅋㅋㅋ 크림브륄레 음료수판이에요 너무 맛있어요ㅠㅠ 케이크도 다른 곳 케이크랑 굉장히 달라요. 레몬 케이크에서 신 맛은 안나고 단 맛만 나는데 식감이 카스테라처럼 엄청나게 부드러웠어요. 너무 맛있어서 크림까지 싹싹 긁어먹었어요ㅎㅎ 다음에 꼭 또 방문하고 싶네요 음료와 케익 모두 정말 맛있었어요', 336, 44, 'GOOD', SYSTIMESTAMP);
