INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '초코크로플 미쳤네요. 후기 보고 초코크로플 주문했는데 무조건 크로 폴은 초코로 드세요. 초코 범벅에 버터 풍미가 가득이에요..커벌데 사장님 초코에 미쳤어요🧈', 37, 1, 'GOOD', SYSTIMESTAMP);
