INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '메뉴도 맛있고 인테리어도 넘 예뻐서 홍대 갈 때마다 가게 되는 카페인데 이번에 또 신메뉴로 얼그레이자몽케이크 나와서 먹어봤어요🧡진짜 여기가 케이크 맛집ㅠㅠ생소한 조합일 것 같았는데 넘 조화롭게 맛있자나여!!!! 최애메뉴 바뀔 것 같아여~~', 42, 6, 'GOOD', SYSTIMESTAMP);
