INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '거의 최애카페 등극 인테리어도 정말 감각적이고 케이크도 독특하고 맛있어요!!! 강아지 간식도 있어서 강아지들도 많이 놀러오더라구여 진짜 넘귀❣️', 96, 19, 'GOOD', SYSTIMESTAMP);
