INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '디저트 맛있을 거 같아서 찾은 카페인데 너무너무 분위기가 좋아서 기분이 좋아졌네요. 구석구석 인테리어도 너무 예쁘고 마음에 안정이 찾아오는..ㅎㅎ 조명도 너무 예쁘고 창가자리에 햇살 맞으면서 수다 몇시간 떨다 갔네요. 생크림 딸기 케이크는 생크림이 되게 고급 맛 나고 엄청 달달하고 맛있었어요. 그리고 시그니처 라떼도 먹어봤는데 제가 서리태 처돌이라 그런지 크림 넘 고소하고 맛있었어요!', 25, 9, 'GOOD', SYSTIMESTAMP);
