INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '사장님이 너무너무 친절하시고 제가 좋아하는 메뉴가 많아 자주 이용하는 곳인데 새로운 케이크가 나왔길래 시켜봤어요!! 얼그레이자몽케이크 너무 취향저격으로 담백하고 맛있어요 담에 또 시켜먹을예정입미당❤️', 90, 14, 'GOOD', SYSTIMESTAMP);
