INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '왜 시그니처에이드인지 알거같아요!! 바질토마토소다 너무 맛있어요🍅토마토청이 달콤한데 바질향까지 나면서 톡쏘는맛? 한번 먹으면 또 생각날맛이에요ㅠㅠ바질토마토소다 완전추천!', 37, 2, 'GOOD', SYSTIMESTAMP);
