INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '이거 미쳤어요..시그니처 음료 새로 생겼길래 사장님 추천으로 먹어봤는데 토마토청이 원래 이렇게 맛있는거였나요ㅠㅠㅠㅠㅠ달콤하고 바질향이 대박이에요....집에갈때 하나 더 사서 갑니다 총총총', 105, 26, 'GOOD', SYSTIMESTAMP);
