INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '자몽케이크 먹었는데 얼그레이향 정말 진하고 자몽도 안쓰고 맛있어요 아메리카노랑 너무 잘 먹었어요~ 카페 인테리어 너무 이뻐서 사진도 잘나와서 좋아요 다른 케이크도 궁금하네용ㅎㅎ', 30, 6, 'GOOD', SYSTIMESTAMP);
