INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '커벌데 케익 오래오래 해주세요...올때마다 신상 케이크가 생겨있는데ㅠㅠ자몽 덕후인 제 취향저격이에오....진짜 너~~~무 맛있어요💓', 2, 3, 'GOOD', SYSTIMESTAMP);
