INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '휴..맛있다는 말도 부족해요ㅠㅠ 다른데서 케익 잘못 먹으면 넘 시거나 이 맛도 저 맛도 아닌 맛인데, 여긴 없던 입맛도 생겨나게 하는 맛이에요ㅠㅠ 커피랑 먹기에 딱! 케익 한 판 두고 퍼먹고 싶은데 홀케익으로도 판매 해주셨음 좋겠어요 헤헤,,🤍', 2, 0, 'GOOD', SYSTIMESTAMP);
