INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '제가 좋아하는 레몬케이크!!! 드뎌 맛집을 찾았습니당 ㅜㅜ 매장이 깔끔하고 인테리어 예쁘게 잘되어 있어서 분위기가 좋았어요 레몬케이크 또 먹으러 갈거에여 😋', 1, 2, 'GOOD', SYSTIMESTAMP);
