INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '블루베리요거트 케이크 미쳤어요.....어제 먹어보고 또 생각나서 오늘 포장하러 왔는데ㅠㅠㅠㅠㅠ너무맛있어요 친구도 존맛탱이라고 감탄쓰 또갈께여 사장님💜', 123, 25, 'GOOD', SYSTIMESTAMP);
