INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '긔여운 댕댕이들 볼수 있어서 보는 재미 맛잇는 디저트 덕분이 먹는 호강🍰 안에 분위기도 좋아요!!! 좌석도 다양하고 사장님 친절하세요!! 반려견 많이 데려 와주세요 ㅠㅠ 강아지하고 편하게 있기 좋은 카페였습니다!', 86, 16, 'GOOD', SYSTIMESTAMP);
