INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '매장 분위기도 너무 좋고 디저트가 진짜 맛있어요!! 치즈 케이크 덕후인데 이런 치즈 케이크는 처음 먹어봐용 나중에 다른 종류도 먹어보고 싶어요 👍🏻👍🏻', 78, 16, 'GOOD', SYSTIMESTAMP);
