INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '제 최애매뉴 중 하나인 플랫화이트랑 레몬버터케이크!!!! 예쁜사장님들이 항상 친절하게 맞아주셔서 기분좋구 메뉴들도 너무 맛있어요❤️', 120, 25, 'GOOD', SYSTIMESTAMP);
