INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '음료가 다 맛있고 공간을 잘 꾸며놔서 갤러리 근처 카페 같은 감성이에요 개인적으로 케이크는 시트 자체가 많은 편이라 선호하지 않지만 사진 찍기도 예쁘고 음료도 맛있어서 담에 또 들릴 예정이에요', 30, 6, 'GOOD', SYSTIMESTAMP);
