INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '분위기도 너무 좋고! 음식도 커피도 다 너무 좋았어요! 무엇보다 사장님이 정말 친절하셔서 더 좋았답니다! 분위기, 커피맛, 디저트맛 그리고 노래에 친절한 사장님까지 🧡 (심지어 화장실도 스멜굿) 홍대에 오면 무조건 오고 싶은 카페라서 앞으로 홍대 오면 카페는 무조건 여기만 올 예정입니다!', 53, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '음악 선곡도 좋고 매장 공간 하나하나 사진 찍으면 다 감성 있게 나와요! 조명이 특히 적당해서 편하게 대화하기 좋아요ㅋㅋ 시그니처 메뉴인 서리태크림라떼랑 피치허니블랙티 둘다 다른 곳과 다른 풍미가 느껴집니다!', 29, 2, 'GOOD', SYSTIMESTAMP);
