INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '사장님 정말 친절하세요. 😭 제가 오픈 시간을 잘못 알고 갔는데 아무렇지도 않게 커피 만들어주셔서 그때가 영업시간 아닌 것도 나중에 알았습니다… 사장님 도덕책…🌟 시원한 가을 날씨… 햇빛 들어오는 낮에 야외 좌석 앉아 커피 마시면 이것이 라이프…🥰', 1, 4, 'GOOD', SYSTIMESTAMP);
