INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '서교동의 숨어 있는 보석 같은 카페예요! 💎😍 🦮펫 프랜들리 카페라 🐶댕댕이 데리고 출입 가능합니다! 타이밍 잘 맞추어 가면 귀여운 댕댕이들 보며 맛난 커피 즐길 수 있어요 ☕️😆 아메리카노 라떼 둘 다 너무 맛있고요! 특히 아메리카노는 시지 않고 고소한 원두 풍미를 즐길 수 있어 취향저격입니다. 그밖에 피치허니블랙티도 적당히 달면서 쌉싸름한 블랙티를 시원하게 즐길 수 있어요~ 진짜 피치가 들어 있습니다. 🍑🧊 사장님 너무 친절하시고 카페 인테리어가 넘 예뻐요…!! 🤩✨🌟 카페 안에 화장실 있어요!', 11, 1, 'GOOD', SYSTIMESTAMP);
