INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '와, 오래 전인데 어디건가 영수증이 나와서 리뷰 남겨요 ㅎㅎ 이름이 마음에 들었어요. 크로플 맛있게 먹었고 무엇보다도 함께했던 사람과의 순간이 좋았네요. 번창하세요 :)', 447, 76, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '홍대 이쁜카페 놀러갔다왔어요~ 요즘 폭염심한데 들어가자마자 엄청 시원해서 일단 너무좋았구! 커피도 맛있었는데 오미자에이드 궁금해서 남자친구가 시켯는데 맛있어서 제가 뺏어먹었네요 ㅋㅋ 제일좋은건!! 반려동물입장이 가능하다는겁니다~ 분위기도 좋고 강아지랑 남자친구랑 좋은시간 보내고왔네요~ 친절하신 사장님이 강아지 물도 챙겨주시고 신경엄청 써주셔서 감사했어요 ㅎㅎ 또 방문할게요~~', 40, 10, 'GOOD', SYSTIMESTAMP);
