INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '힐링이 되는까페에요… 자몽에이드도 너무 시원하고 맛있어요! 마샬 스탠모어가 화룡점정 시간 날때마다 갑니다. 사장님은 꿈과 패기가 넘치시는 너무 멋진 분이세요. 언제나 응원합니다. 잘 쉬다 갑니다.', 45, 8, NULL, SYSTIMESTAMP);
