INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '골목에 숨어있는 카페,, 인테리어에 신경 쓰신게 느껴졌고 자리도 편했습니다. 시그니쳐 메뉴 다 맛있었는데 강원도 유명 카페 메뉴가 생각나는 맛이었어요. 분위기도 좋고 맛도 있어 재방문 할 것 같아요 ^_^ 대박나세요', 1, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '분위기도 좋고 사장님들도 친절하시고 커피도 맛있고 스콘도 적당히 달달하니 맛있어요ㅠㅠ🤎🤎 가볍게 책 읽기도 좋고 댕댕이들도 가끔 볼 수 있어서 좋아요! >ㅅ<', 12, 6, 'GOOD', SYSTIMESTAMP);
