INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '커피도 맛있고 인테리어도 넘 예뻐서 막찍어도 인생샷,, 반려견 동반 가능이라 더 좋아용ㅠㅠ 뭐 하나 아쉬울게 없어서 자주 갈 것 같아요 간만에 넘 맘에 드는 맛집 찾아서 행복,,', 88, 12, 'GOOD', SYSTIMESTAMP);
