INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '커피벌스데이'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '사장님도 너무 친절하고 분위기 왕왕 좋아요~! 커피도 맛있고 디저트도 주셨는데 너무 예뻐서 먹기 너무 아까웠지만 먹기를 너무 잘했어요..ㅎㅎ', 3, 9, 'GOOD', SYSTIMESTAMP);
