INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '홍대입구역에서 접근성이 아주 좋았어요. 건물이 오래 되어보였지만 엘베 있는 건물이라 굿굿 평일이라 다행히 웨이팅은 없었지만 테이블은 제법 차있었어요. 제철과일이 올라간 케이크들이 먹음직스럽고 예뻐요. 얼그레이 무화과-얼그레이 향이 많이 느껴지는 크림이 무화과랑 잘 어울림. 무화과도 신선해서 좋아요. 케이크 시트도 퐁신해서 굿 초당옥수수-이건 여름이라 잘 어울리겠다 싶어서 주문했는데 호불호가 좀 갈릴 듯 해요. 짠맛도 나고.. 근데 예쁘긴 예쁨 아아는 다크하고 진해서 달달한 케이크와 함께 즐기기에 나쁘지 않았어요. 일하시는 분들도 친절했고 지인과 좋은 시간 보냈습니다.', 64, 11, 'GOOD', SYSTIMESTAMP);
