INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '직장을 옮기고 난 뒤 자주왔던 발코니를 못오게되어서 이번에 정말 오랜만에 여친과 놀러왔슴다,,! 너무 더워서 시원한 망빙 먹으러 왔는데 복숭아+애플망고 빙수라뇨,,,!!! 😬 쵝오쵝오 !! 빙수도 달지 않고 위스키와 굿조합!! 이번에도 넘나 맛나게 먹고갑니당!!', 458, 78, 'GOOD', SYSTIMESTAMP);
