INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '급 찾아서 온 곳인데 들어오자마자 헉!소리가 나오게 예쁘더라구요~ 카페 이름에 가든이 들어간만큼 카페에 생화가 많아서 예쁘고 좋아요~* 8월이라 제철인 제주산 애플망고 빙수 시켜봤는데 좀 가격대가 있긴 하지만 맛있네요~ 홍대쪽 오면 재방문할 것 같아요~ 이야기 나누기도 좋아서 추천합니다♡', 17, 0, 'GOOD', SYSTIMESTAMP);
