INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '우와 테라스 분위기 머선일!!! 이국적인 느낌에 홍대 거리가 내려다보이는 뷰 맛집 ✨ 애플망고복숭아빙수 먹었는데 달콤한 과육에 요거트&우유 얼음이 진짜 잘 어울려요! 망고, 복숭아 둘 다 잘 익어서 맛있었어요 😋 그리고 빙수 먹으러 간 거라서 솔직히 기대 안했는데 케이크 맛집입니다!!!! 👍 블루베리 치즈케이크 추천해요 🧡 사장님 엄청 친절하시고 먹어본 메뉴들 다 맛있어서 재방문 의사 💯!!', 3, 1, 'GOOD', SYSTIMESTAMP);
