INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '복숭아랑 망고 둘 다 좋아해서 기대하고 시켰는데, 조합이 너무 좋았어요~! 복숭아 과즙 많고 달달했고, 망고는 약간 과일청처럼 진한 단맛이었어요.(제주망고쓰신대요!) 얼음은 우유얼음이라 부드럽고 고소한 편. 크림이나 토핑도 과하지 않아서 전체적으로 깔끔하게 먹기 좋았고요. 양은 꽤 많아서 둘이 나눠 먹기 딱 좋아요. 너무 달기만 한 빙수는 질릴 수 있는데, 이건 중간중간 상큼함이 있어서  복숭아+망고 조합 좋아하는 사람한테는 만족스러울 듯 합니당 더운 여름날 상큼하게 잘 먹고 가요💝', 33, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '☀️홍대 데이트 코스💕 실내정원느낌의 빙수가 맛있는 카페 사진의 복숭아애플망고눈꽃빙수가 있다고해서 먹으러 왔습니다! 사실, 디저트들도 너무 예뻐서 디저트도 먹고 싶었지만..배가 불러서 디저트까지는 못시켰어요.. 푸릇푸릇한 예쁜 실내정원 분위기의 공간이에요. 창문이 조금만 더 깨끗했으면 햇살까지 예쁘게 즐길 수 있었을 것같아요. 메뉴 🍑복숭아애플망고눈꽃빙수 복숭아 속 요거트 크림과 망고의 달콤함이 잘 어울려서 맛있었어요! 비주얼도 예쁘고 양도 넉넉✨ 가격대 있지만 만족도 👍 🌸 플라워 자몽에이드 꽃얼음이 포인트인데 생각보다 선명하지는 않았어요. 맛도 달달함보단 건강한 느낌이예요.', 64, 16, 'GOOD', SYSTIMESTAMP);
