INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '여기 빙수 급 생각나서  또 먹으러 왔는데 역시나 너무 맛있게 먹고 왔습니다 밍밍한 얼음빙수 아니고 고소한 우유빙수에 과일도 당도 높고 숙성 잘 된 애플망고랑 복숭아 바로 잘라서 얹어주니까 너무너무 맛있어요', 397, 90, 'GOOD', SYSTIMESTAMP);
