INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '빙수가 푸짐하고 과일이 많이 올라가 있어 먹기 좋아요 그리고 메론 케이크 처음 먹어보는데 메론이 조금 더 후숙되면 더 맛있을거 같아요! 데이트 하기 좋은 곳🍈🥭🍑', 13, 7, 'GOOD', SYSTIMESTAMP);
