INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '여름엔 역시 빙수고 빙수는 역시 발코니 가든 망고 빙수가 아닐까 싶습니다. 스무번 가까이 사먹은 찐단골 픽은 망고&복숭아 빙수!! 케이크랑 빙수 먹다보면 단맛이 입에 남는 느낌인데 향긋한 복숭아 향으로 싹 잡아줘서 입 안이 개운해진달까. 다시 리셋되서 열심히 흡입할 수 있어요. 요즘 발코니 케이크 종류가 엄청 많아져서 안먹어본 얼그레이자몽이랑 휩가나슈생크림 케이크는 테이크 아웃해서 다음날 먹었어요. 가나슈생크림은 엄청 꾸덕한 초코맛은 아닌 마일드한 맛이고 얼그레이 자몽은 기존에 먹던 얼그레이보다 한 단계 업그레이드 된 맛이랄까? 생각보다 상큼한 자몽이랑 잘 어울렸어요. 작년에 복숭아 철일때 복숭아 빙수 먹었던게 가끔 생각났는데 올해도 복숭아랑 망고 빙수 질리도록 먹어야겠어요.', 33, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '빙수랑 케이크 세트 시켰어요 가격은 진짜 (빙수 하나에 3만원이 넘어가요) 비싸지만 생망고랍니다 케이크도 과일 진짜 많이 올려줘요!', 44, 10, 'GOOD', SYSTIMESTAMP);
