INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '과일이 정말 듬뿍듬뿍 들어있어요!! 빙수도 얼음이 우유빙수라서 정말 맛있어요 가격대가 조금 있지만 그만큼 과일을 많이 넣어줘요', 65, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '너무 더워서 가장 가까운 카페를 찾았더니 여기가 나왔어요 어질어질 정신이 없이 왔는데 인테리어가 되게 예뻐서 눈이 좀 살아나는 것 같아요 음료도 맛있고 좋네요', 54, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '생딸기  눈꽃빙수 딸기가  가득이라  너무 맛있게 먹었고  리얼 후르츠 케잌도 부드러워서  살살 녹아요. 분위기도 좋고 생화가  가득 꽂혀  있어서  아름다워요. 테라스에서  얘기 나누며 4층이라 뷰가 좋고 좋은 시간 되었네요. 또 생딸기 눈꽃 빙수가 생각 날 것 같습니다. 역시 찾아 온 보람이 있었어요.', 90, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'TERRACE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '오늘 망고빙수 먹었는데 진짜 대박이에요! 망고가 엄청 신선하고 달달해서 한 입 먹는 순간 입안이 완전 여름🌴 시원한 우유 얼음이랑 잘 어울려서 마지막 한 숟갈까지 계속 손이 갔어요. 양도 푸짐해서 둘이 나눠 먹기 딱 좋았고, 비주얼도 예뻐서 사진 찍기 좋아요📸 망고 좋아하시는 분들은 꼭 한 번 드셔보세요! 재방문의사 100%입니다', 17, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '여름에 시원하게 즐길 디저트를 찾는다면 애플망고빙수가 딱이에요. 잘 익은 애플망고가 듬뿍 올라가 있어서 첫 숟가락부터 달콤한 과즙이 입안 가득 퍼져요. 망고 특유의 향이 은근하게 감돌고, 곱게 갈린 우유 얼음이 부드럽게 녹으면서 시원함이 두 배! 한 입 먹을 때마다 더위가 싹 사라지는 느낌이라, 여름엔 꼭 생각나는 메뉴예요.', 30, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '날씨가 더워서 야외 발코니 이용은 못했지만 실내도 아늑하고 인테리어도 예뻐요 케이크가 생각보다 맛없어서 놀랐어요 복숭아가 쓴맛 날정도여서 이 돈 주고 먹기 아깝다? 정도… 생크림 좋아하시면 괜찮으실 것 같습니다 분명 상품 설명에는 특제 크림 어쩌고 적혀있었는데 그냥 생크림이였어요', 11, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '디저트 맛있어요 음료는 무난해요 실내층에 사람이 많던데 날씨 좋아서 루프탑 이용하기가 더 좋았어요 다만 강아지 두마리가 묶여있는데 배고픈건지 답답한건지 펜스 넘으려고 엄청 돌아다녀서 좀 신경쓰여요', 46, 5, NULL, SYSTIMESTAMP);
