INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '재방문의사 ⭐️⭐️⭐️⭐️ 낮에 왔을때랑 저녁이랄 분위기 반전이 있어 좋어요!!ㅎㅎ 8월 시즌인 빙수도 너무너무 맛있었습니다아✨✨', 43, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '아이스 아메리카노랑 수박주스 시켜먹었어요. 수박주스는 정말 맛있었고 아아 반정도 먹었을 때 벌레가 들어가 있었어요. 만드는과정에 들어간건지 먹다가 들어간건지는 모르겠지만 ㅠ 벌레가 은근 크네여', 47, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '진짜 해도해도 너무 하시네 이과일을 빙수에 올릴때 생각은 안하고 주시는건가요? 4만원짜리 빙수 먹으면서 과일 이렇게 최악인건 처음봅니다 사장님 얼마나 남겨 먹을라고 그러시나요.. 복숭아 시고 다썩은거 주고 망고는 하나도 안달고 냉장고맛나네요 맛있는건 우유얼음뿐입니다 그럴거면 인절미 빙수 파세요 과일 최악인거 쓰시면서 과일 홍보하는게 웃기네요 그리고 이것만 그런거면 버리시던가 본인들이 먹으시지 왜이걸 돈주고 파는지 처리반인가요?? 밖에 보니 싱싱한 복숭아들 있는거보고 한번더 어이없어서 갑니다', 4, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '복숭아애플망고눈꽃빙수,땡모반 1인 1메뉴인데 케익은 포함이 아니고 빙수는 2인메뉴래요 참고! 빙수 진짜진짜 맛있어요 과일도 맛있고 얼음도 요거드+우유라네요', 18, 5, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '비가 엄청나게  비가 쏟아지던 날. 1시 오픈이라고 되어있는데 12시45분에 갔었고 (식사 후라 시간이...) 오픈 안했다고 갔다가 다시 오라고 하더라고요. 장대비 쏟아지는데 돌아나와야했습니다. 기분이 나빴지만 가보고 싶었습니다. 애플망고를 주 재료로하는 카페네요. 꽃도 여기저기 장식되어 있고요. 흑임자라떼를 주문했는데... 그냥 맹라떼 맛이네요. 아마도 건물내 보컬연습실이 있어 굳이 뜨내기(?)손님이 필요치 않은 듯 했습니다.', 10, 8, 'BAD', SYSTIMESTAMP);
