INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '유럽풍 느낌 낭낭한 인테리어 속 잔잔한 음악도 흘러 나오고 대화하기 좋은 카페인 것 같아요! 디저트들도 맛있고 시즌에 맞는 메론 케이크도 있어서 좋았습니당', 3, 0, 'GOOD', SYSTIMESTAMP);
