INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '매장 청결하구 완전 시원했어요 직원분들이 너무 친절해요!! 인스타에 올리려고 사진 찍었는데 뭐랄까 인생샷? 나올거 같아요~~~', 17, 8, 'GOOD', SYSTIMESTAMP);
