INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '남자친구 아버지 생신선물 시도르에서 빠르게 구매후 발코니가든 으로 튀튀 당 채우려고 딸기티라미수 크로플! 가격이 17,900(영수증리뷰 하면1,000원빼주셔서) 인데 생각보다 크고 양많아서 오 이정도면 ㅇㅈ 했음 플라워에이드(복숭아)는 원액을 따로 넣을 수 있는데 맛있어요!ㅠㅠ복숭아 러버는 꼭드쉐여🫶🏻 비오는날에 오니까 창가자리 매우 운치있음! 남자친구,여자친구 기분풀어주러 데려오기 좋아여 메뉴 다양하고 크로플 외에 케이쿠도 맛나보였음 생크림 프루트 케이크 왜케 맛있어보이지🥺🥺 향딸기티라미수크로플은 티라미수맛이 녹진한데 크로플위의 티라미수 크림 사이에 커피맛이납니다! 두번드세여', 2, 5, 'GOOD', SYSTIMESTAMP);
