INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '케이크와 플라워 에이드가 너무 맛있어요… 사람이 진짜 많지만 그만큼 기다릴 가치가 있는 디저트 입니더.. 늦게까지 해서 좋아요!!', 34, 2, 'GOOD', SYSTIMESTAMP);
