INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '케이크 예약 구매했고 픽업하면서 곰돌이 초도 하나 구매했어요! 케이크는 생각했던대로 예쁘고 맘에들어요~~근데 케이크 전문점이 아니여서 인지 기본 초나 케익칼,초에 불 붙일 성냥은 따로 없어요~! 아직 맛보기 전인데 과일 상태가 좋아보여서 기대돼요ㅎㅎ', 17, 1, 'GOOD', SYSTIMESTAMP);
