INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '커피도 맛있고 디저트도 맛있고 분위기도 좋았어요4 4층에 있어어 홍대 광장이 내려다보이고 뷰도 좋은네요!! 꽃향기가 나고 식물도 많아서 친구랑 힐링제대로 하고 왔어요! 분위기 좋은곳에서 달달한거 먹으니 좋더라구요^^', 3, 9, 'GOOD', SYSTIMESTAMP);
