INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '홍대 오면 종종 들리는 카페~~ 디저트류로 식사 대신 배 채우기도 좋고 음료도 인테리어도 사진 찍기 좋고 맛도 괜찮습니다 오래 머물기도 좋구요 저녁 시간대에는 불을 꺼주시는 것도 분위기 있고 좋아요:)', 12, 1, 'GOOD', SYSTIMESTAMP);
