INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '우유빙수고 다 맛있는데 딱복을 사용하신거면 슬라이스가 좀 더 작아야할 거 같아요! 먹기에 불편함이 살짝있습니다! 아님 물복이여도 좋을 거 같아요! 맛은 좋았습니다!', 94, 26, NULL, SYSTIMESTAMP);
