INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '더운날씨에 빙수가 먹고싶어서 찾아왔는데 발코니도 있고 디저트 종류도 엄청 많았어요 ! 빙수도 맛있고 밑에쪽에 시럽이있어서 끝까지 안밍밍하게 먹을수있어서 좋았습니당 🥹👍🏻', 7, 2, 'GOOD', SYSTIMESTAMP);
