INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '여자친구가 저번에 사 준 케이크 맛있다고 발렌타인 데이 케이크 발코니서 선물해 줬어요. 초코 시트와 생크림, 생딸기 듬뿍 들어가 있는데 엄청 달지 않고 맛있습니다. 열 번 넘게 가 본 찐단골인데 진짜 여긴 재료가 신선하고 맛있어요. 방어 먹고 술김에 생각없이 흔들었다가 저 모양되서 겁나 혼났네요. 여러분은 조심조심 들고 다니시길... 케이크 받고 다른 카페서 커피 마시다 집에서 와인이랑 곁들여 먹으니 달달하니 좋네요. 화이트데이엔 다른 버전으로 기획하신다는데 여자친구 선물해줄까 합니다. 암튼 케이크랑 빙수 맛집이라 자주 오는 곳이니 믿고 드셔보셔도 됩니다. 존맛 👍', 60, 18, 'GOOD', SYSTIMESTAMP);
