INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '케이크가 동물성크림으로 만들어져서 진짜 진짜 맛있어요! 입에서 샤르르 녹아요~ 딸기빙수 말모말모~ 빙수안에 딸기청과 초코청크가 같이 들어있어서 색다르고 더 맛났어용! 지금은 겨울철이라 테라스가 막혀 있지만 봄 가을에 정말 좋을 것 같네요!!! 홍대입구역 7번 출구 바로 앞이라 접근성도 넘 좋네요😍', 32, 0, 'GOOD', SYSTIMESTAMP);
