INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '분기별로 찾아오는 이 곳 ㅋㅋ 오늘은 한파를 뚫고 불금에 식사하고 들렀네요 추운날씨지만 고기파티 후에 상큼한게 땡겨 빙수한그릇하러!! 역시 빙수맛집!! 달달한 케익도 곁들여보고 ㅋㅋ 발베니에 달달구리한 디저트 조합 최고네요!! 😍 나중에 또 놀러올께용 🫶', 4, 2, 'GOOD', SYSTIMESTAMP);
