INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '홍대입구역 루프탑 카페 발코니가든을 방문했습니다. 아직 추워서 5층 루프탑공간은 개방되어 있지 않았지만 4층 실내카페는 이국적인 정원 느낌의 인테리어가 마치 식물원에 온 듯한 분위기를 선사해요. 딸기크로플은 바삭한 크로와상과 와플의 부드러운  조화가 일품이었고, 신선한 설향 딸기 토핑과 동물성생크림의 고소함이 잘 어울렸어요. 마르코폴로 홍차를 마셨는데  은은한 과일향과 꽃향이 카페의 분위기와 잘 어울렸답니다. 초코딸기케이크는 진한 초콜릿 시트와 생크림, 딸기의 조합이 절묘해 달콤함이 부담스럽지 않았어요. 곧 루프탑을 개방한다고 하니 봄날 데이트나 여자친구와의 만남, 소규모 모임에 방문하면 좋을 것 같아요. 특히 사진 찍기 좋아하는 분들에게 강력 제안하고 싶은 홍대 핫플레이스입니다.🙂', 11, 4, 'GOOD', SYSTIMESTAMP);
