INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '달기 빙수 완전 맛잇어요ㅎㅎㅎ 모양두 이브고 양도 넉넉해용 근처애서 딸기빙슈 몇번 먹엇는데 여기가 탑에 들어요! 추천합니댱🥰🥰', 5, 0, 'GOOD', SYSTIMESTAMP);
