INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '날이 어둑해지니 실내 조명이 분위기있게 바뀌어요 딸기케이크에 딸기 많이 들어가고 시그니처 청포도 에이드는 얼음에 꽃이 들어가 예뻤어요~ 분위기 좋은 카페였어요', 26, 0, 'GOOD', SYSTIMESTAMP);
