INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '발코니가든은 진짜 제가 찐찐 애정하는 디저트 맛집이라 계절마다 매번 가는 곳이에요 항상 홀케이크도 시켜보고 싶었는데 이번에 남자친구 생일을 맞이해 딸기 초코 생크림 케이크 주문해서 축하해줬어요💗 남자친구가 세상에서 제일 좋아하는 케이크가 바로 발코니 가든 초코케이크라서 완전 감동 받았다고 하더라고요 ㅎㅎ 그냥 매년 생일 케이크 여기서 하려고요! 가격대가 사실 좀 있긴 하지만 그만큼의 가치가 있는 케이크고 먹을 때마다 딸기 씹혀서 재료도 완전 많이 들어가 있어요!! 초코 시트도 맛있는데 여기는 초코 생크림?? 필링?? 뭐지 튼 저게 진짜 부드럽고 고급짘 달달한 맛이에요!! 내돈내산인데 진짜 강추…💗💗', 30, 6, 'GOOD', SYSTIMESTAMP);
