INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '겨울엔 역시 딸기 시즌 디저트가 최고🍓👍 딸기케이크 딸기크로폴 모두 상큼한 딸기가 더해져서 너무 맛있네요. 딸기케이크는 크림이 부드럽고 입에서 살살 녹아요❤️ 설향 딸기가 쇼케이스에 가득하고 사장님이 직접 만든 케이크는 비주얼 부터가 대박🍰 크리스마스 분위기 가득한 4층은 식물이 가득하고 블링블링 조명도 기분을 좋게 하네요. 산미없는 구수한 커피도 디저트와 잘 어울리고 5층 루프탑은 추워서 사용하지 못하지만 둘러 보는것 만으로 힐링 됩니다🎄봄 가을에 꼭 다사 오고 싶어져요 😍크리스마스 케이크 사전 예약 이벤트 진행중이니 서둘러 예약해야겠어요. 방금전에 있었던 포장케이크도 금방 사라졌어요🎂🎂🍓', 2, 9, 'GOOD', SYSTIMESTAMP);
