INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '아늑해서 대화하기 좋아요 . 편한다인석 테이블도 있고 대화나 가벼운 작업할만큼 테이블도 편안하구요 화장실도 내부에있어서 넘 좋습니다 디저트들도 다 만드시더라구요... 너무 맛있게 먹었습니다 음료는 플라워 종류들 예뻐서 추천해요!!!!!', 38, 3, 'GOOD', SYSTIMESTAMP);
