INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '너무 더워서 애플망고빙수 먹으러 홍대 발코니 가든 급!! 방문했습니다. 너무 맛있었고 더위가 확 날라갔습니다. 홍대 망고빙수는 역시 발코니 가든이 최고에요!', 50, 2, 'GOOD', SYSTIMESTAMP);
