INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '내일이 회사동료 생일이라 퇴근하고 부랴부랴 갔는데 너무나 멋지고 이쁜케익이 쨔란 있지모에요! 처음 우연히 와봤는데 너무 만족합니다!! 추천추천', 73, 11, 'GOOD', SYSTIMESTAMP);
