INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '연말에 홀케익 판매한다는 소식에 케익주문하러 왔습니당 딸케 비쥬얼 미쳤어여,,,, 선물용이라 먹어보지 못하겠어서 조각케익으로 대신해서 먹어보니 역시나 꿀맛! 위스키에 케익 조합도 꿀맛이네영 ❤️', 56, 12, 'GOOD', SYSTIMESTAMP);
