INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '발코니 가든 10번이상 다닌 찐단골로써 홀케이크 시작했단 소식 듣고 친구 생일 케이크용으로 사봤습니다. 친구들이랑 다 감탄하면서 귀신에 홀린듯 흡입했어요. 일단 설향 딸기 가득 들어있구요. 케이크 바닥 겉면에 보이는 딸기는 데코용 슬라이스가 아니라 1/2 딸기입니다. 근데 진짜 대박은 크림입니다. 동물성 생크림인건 당연한건데 뭔가 더 부드럽고 진한 맛이 나서 기존에 딸기생크림 케이크와 묘하게 다른 퀄리티의 맛이었어요. 인스타서 보니까 마스카포네 크림이랑 서울우유 생크림을 배합해서 쓴다고 하더라구요. 어쩐지 묘하게 다른 맛입니다. 진짜 바닥까지 핥아 먹었어요. 그래서 네이버 예약 들어가서 크리스마스 케이크 예약했습니다. 케이크는 두 종류가 있길래 안먹어본 디자인으로 예약했습니다. 앞으로 케잌도 발코니!!!', 45, 1, 'GOOD', SYSTIMESTAMP);
