INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '딸기케이크 🎂 덕분에 더더더더 행복한 크리스마스이브 보냈어요! 딸기 이렇게나 아낌없이 들어있는 케이크 첨입니다 부드러운 크림까지.. 사장님 체고... 🥹 너무 맛있게 먹었어요!!!  딸기초코케이크 먹으러 또 갈께요!', 28, 7, 'GOOD', SYSTIMESTAMP);
