INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '분기별로 찾아오는 이 곳 ㅋㅋ 오늘도 퇴근길에 동료와 저녁후에 들렸습니다!! 그런데 사장님께서 케익을 직접 만들어서 파시더라구요!! 능력자이신데 맛이 기가막히게 맛있는!! 들어간 과일도 넘 신선하구요! 👍 발베니에 케익과 빙수는 최고의 조합이었어요. 잘 먹었습니다~ 😆', 28, 0, 'GOOD', SYSTIMESTAMP);
