INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '여기 진짜 조용하고넘 맛있어요..쿠로플 꼭 드새요 겉바속촉 미쳤습니다 진짜... 위에 올라간 크림 왜이렇게 맛있죠...? 하 ,,,, 사랑해... 케잌도 완전 부드럽고 맛있어요!!! 강추드립니다 진짜 안에 분위기도좋고 식물도 많고 조용해요,,,', 22, 8, 'GOOD', SYSTIMESTAMP);
