INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '가격은 조금 비싼거같은데 인테리어랑 분위기가 너무 좋아요 지금 날씨도 따뜻해져서 5층에 야외 테라스 공간도 분위기 좋을것 같습니다 디저트도 딸기가 많이 들어가서 너무 맛있어요 ❤️', 27, 2, 'GOOD', SYSTIMESTAMP);
