INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '친구들이랑 간단하게 담소하러 왔는데 늦은 시간 까지 하는 카페라서 방문 했어요! 친구가 추천해줬어서 방문 해봤는데 분위기도 좋고 크로플도 너무너무 맛있게 먹었어요 ㅎㅎ', 90, 15, 'GOOD', SYSTIMESTAMP);
