INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '이름답게 발코니가 있고 메뉴들이 너무 다 맛있어 보여서 고르느라 힘들었는데 정말 크로플은 꼭 먹어보세요!! 다음엔 빙수도 먹으러 와보고 싶어요 :)', 30, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '발코니 가든 찐단골로써 여기 티라미수크로플 꼭 먹어야해요. 케이크도 맛있지만 전 크로플 강추합니다. 왜냐면 갓구운 크로플에 저 미친 크림이 듬뿍 올라가있는데 크림이 진짜 돌아버릴 정도로 맛있습니다. 예전엔 에스프레소 깔려있지 않았는데 리뉴얼 된 것 같아요. 확실히 훨씬 더 풍미가 느껴져서 좋습니다!! 제가 여기 메뉴는 다 먹어본 사람인데 여긴 여름엔 빙수 겨울엔 크로플입니다!! 오늘 눈 오고 엄청 추운데 따끈따끈 크로플에 크림 입에 쑤셔넣고 싶네요. 미친맛 ㅠㅅㅠ', 38, 0, 'GOOD', SYSTIMESTAMP);
