INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '처음 방문했는데 분위기 너무 좋고 딸기빙수 정말 맛있어요! 창문 밖으로 보이는 홍대 풍경이 낭만 넘칩니다~ 여자친구가 생긴다면 꼭 다시 오고 싶은 그런 카페!! 사장님 번창하세요 ㅠㅠㅠ', 1, 9, 'GOOD', SYSTIMESTAMP);
