INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '음료랑 디저트가 너무 맛있고 예뻐요!! 사진도 예쁘게 나오고 가격에 비해 배부르게 많이 먹었습니다! 다음에 또 올 것 같아요 감사합니당~', 69, 14, 'GOOD', SYSTIMESTAMP);
