INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '될 수 있으면 욕 안하는데 정말 불친절하네요. 가격은 비싸면서 손님을 귀찮아하는게 대놓고 티를 내고. 케익 한판을 사서 홀에서 먹으려고 하니 그냥 툭 주고 그냥 가네요. 어이 없어서 사장님 언제 오시냐고 물었습니다. 덕분에 기분 나쁘게 있다가 갑니다. 이렇게 장사할거면 무인카페하세요.', 45, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '기념일이라 딸기케이크 예약했어여🍓 크리스마스때 먹어보고 완전 반해서 케이크는 무조건 발코니가든!! 🎂 맛있는 케이크 감사해요!!!😆', 47, 7, 'GOOD', SYSTIMESTAMP);
