INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '딸기케이크가 엄청 먹고싶었는데 케이크도 너무 이쁘고 크림이 느끼하지않아서 진짜 맛있게 먹었어요..😍 바스크 치즈케잌도 치즈향이 장난아니게 맛있었고.. 초코도 정말 환상적이였어요ㅠㅠㅜ 사장님도 너무 친절하셔서 다음에 또 서울 놀러올일 있으면 여기서 케잌 예약하려구요..❤️', 90, 12, 'GOOD', SYSTIMESTAMP);
