INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '근처에 카페 어디에 있나 찾아보다 가까운데 있어서 가보았어요 ^^ 카페 분위기도 예쁘고 디저트들도 맛있어서 좋습니다...♡ 에이드도 정말 예뻤습니다~', 35, 7, 'GOOD', SYSTIMESTAMP);
