INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '덕분에 행복한 생일 보냈습니다 ~ 우유맛 나는 생크림을 찾았었는데 우유맛이 잘 났고 과일도 신선해서 좋았어요 ! 다음에 또 들리겠습니다ㅎ 감사합니다.', 22, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '밝은 조명에 요기조기 예쁘게 꾸며져 있어서 사진찍기 좋아요 통창에 탁 트인 뷰도 멋지구요 예쁜 공간에서 맛있는 디저트 먹으며 파란 도란도란 수다 떨다가 파란 하늘보며 멍때리다가 사진 찍으며 놀기 좋은 카페예요 시즌 메뉴인 설향딸기크로플과 설향딸기초코케이크 주문했는데 진짜 맛있어요 싱싱한 딸기와 부드러운 생크림의 조합이 환상적이에요 찐 케이크 맛집입니다 #발코니가든 #홍대카페 #홍대디저트 #홍대딸기케이크 #홍대케이크맛집 #홍대데이트 #연남동카페, #홍대입구역카페 #홍대딸기케이크, #홍대디저트 #홍대루프탑카페', 401, 90, 'GOOD', SYSTIMESTAMP);
