INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '웨딩임페리얼 허니밀크티, 아아, 생딸기초코케이크 주문했어요 케이크 부드럽고 맛있는데 딸기가 살짝 무른 느낌이여서 아쉬웠어요🍰 밀크티는 향이 좋고 우유의 비린맛이 없어서 좋았습니다!', 59, 11, NULL, SYSTIMESTAMP);
