INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '너므너무 이쁜 식물카페예요😊 크러플 존맛탱이니 꼭 드셔보세요. 주말에는 사람 완전 많으니 평일에 방문드리는걸 추천해요. 홍대입구역 바로 앞이라 위치도 좋아요. 홍대 디저트카페 추천드려요🫶', 60, 13, 'GOOD', SYSTIMESTAMP);
