INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '커피는 맛있었는데요,, 매장에서 키우는 강아지가 갑자기 옆에 오더니 똥을 쌌어요. 치워주시는 데 시간이 쫌 걸려서 냄새가 났어요. 그리구 빨대에 날파리가 붙어있었어요,, 케이크보다 크로플을 시켜볼 걸 그랬네요. 외국인이 많이 오는 카페. 강아지들은 귀엽긴 했네요^^..', 65, 11, NULL, SYSTIMESTAMP);
