INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '홍대 루프탑 카페하면 발코니가든!! 분위기 너무 좋아요~ 요즘같은 선선한 가을바람 부는 저녁에 앉아서 칵테일 마시면 감성 최고입니다! 무화과 몽블랑 크로플 꼭 드셔요... 다이어터인데 뇌빼고 흡입해버렸슴다.. 존맛탱❤️', 45, 0, 'GOOD', SYSTIMESTAMP);
