INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '케이크는 너무너무 맛있었는데 거의 받아오자마자 먹었는데도 케이크띠를 벗기자마자 전부 녹아내려서 온전한 맛을 모두 못 느꼈던 게 아쉽네요ㅠㅠ!! 그래도 맛있었습니다', 22, 1, NULL, SYSTIMESTAMP);
