INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '홍대 루프탑 카페 단연 1위! 분위기 좋은 루프탑 카페 찾다가 발견했어요. 지금은 할로윈 분위기에 맞게 잘 꾸며져 있어서 데이트 하러 오기 좋으실 거 같아요. 디저트는 물론 카페 메뉴도 맛있지만, 칵테일이 있어서 메뉴가 엄청 다양한데요. 논알코올 칵테일도 있어서 부담없이 좋으실 거 같아요. 음료는 물론 디저트까지 다 퀄리티가 높고 맛있어서 강추!', 81, 12, 'GOOD', SYSTIMESTAMP);
