INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '홍대입구 공항철도 쪽에 위치하고 있고 4층인데 낮에는 까페 저녁에는 칵테일도 판매하는거 같아요 케익은 없지만 츄러스나 크로플 종류가 있고요 맛나요 화초가 많아서 분위기 있고 아늑해서 조용하게 대화하기 좋아요  자주옵니다', 123, 24, 'GOOD', SYSTIMESTAMP);
