INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '가격대가 있어요. 일요일은 좀 일찍 닫고요. 가격대가 있는데도 저희가 픽업&리턴 다해야해요 이점은 아쉽지만 분의기도 좋고 맛있습니다~ 직원분도 친절하세욤!!', 28, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '늦은 시간 크로플이 먹고 싶어서 무작정 방문했는데 23:30까지 영업해서 좋았어요! 알밤 몽블랑 무화과 크로플 진짜 맛있었어서 추천하고 여기에 아이스 아메리카노까지 먹으면 정말 맛있을 것 같네요 🥹 다음에 또 먹고 싶은 맛입니다!', 40, 6, 'GOOD', SYSTIMESTAMP);
