INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '요즘 날씨 너무 좋아서 루프탑에서 스파클링 와인 마셨어요. 언제와도 루프탑 분위기 너무 좋은 곳이에요. 늘 커피랑 디저트만 먹었는데 밤에 루프탑에서 여자친구랑 부라타치즈 샐러드와 스파클링 와인으로 분위기 내니까 너무 좋아하네요. 바틀 가격도 생각보다 저렴하고, 일단 분위기 최고인 홍대 단골 카페입니다. 망고빙수, 딸기크로플 같은 디저트도 별미지만 술을 즐기기에도 좋은곳이라는걸 깨닫고 갑니다. 분위기 최고최고', 94, 23, 'GOOD', SYSTIMESTAMP);
