INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '홍대 근처에 볼일있어서 갔다가 저녁때를 놓쳐 그냥 분위기 좋은 카페나 가서 디저트나 제대로 먹을까하고 방문했어요. 생각보다 분위기 너무 괜찮더라구요 :) 밤에가서 낭만적인 분위기가 멋있었는데 낮에가면 또 다른 따뜻한 느낌이 나서 예쁠듯 했어요!! 몽블랑 크로플 비주얼 무슨일.. 구운 밤, 무화과, 밤 페이스트, 아이스크림을 듬뿍듬뿍 넣어줬는데 맛없을수가 없는 디저트ㅎㅎㅎ 논알콜의 예쁜 칵테일들이 많길래 하나 시켜 먹어봤는데 달달하고 맛있었어요! 데이트할 낭만적인 카페 추천해용 :)', 65, 15, 'GOOD', SYSTIMESTAMP);
