INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '무화과철이라 발코니가든으로 밤&무화과 크로플 먹으러 왔어요! 이 메뉴는 발코니가든에서밖에 못 본 독보적인 메뉴 같아요. 밤과 무화과, 바닐라 아이스크림과 크로플 조합이 최강!!! 가게도 유럽풍으로 예쁘게 꾸며두셔서 올때마다 기분이 정말 좋아요💛 5층 꼭꼭 올라가보세오!!', 48, 10, 'GOOD', SYSTIMESTAMP);
