INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '루프탑이 있는 카페입니당 루프탑과 실내 여러 공간 다 예쁘지만, 루프탑에 누울 수 있는 곳이 있어서 좋았어요 날씨가 딱 좋을 때라 커피 마시면서 누워있었던 게 아직도 좋은 기억으로 남아있어요 🥹 실내도 예뻐서 이제 날씨가 좀 추워졌으니까 실내 이용하러 또 가겠습니당', 21, 2, 'GOOD', SYSTIMESTAMP);
