INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '커피는 생각보다 괜찮았던거같은데 케이크는 실망했어요 전날 판거 그대로 주신거같은 밀가루 반죽과 딸기… 케이크 먹으러 온 사람이라 실망감이 더 큽니다', 55, 14, 'BAD', SYSTIMESTAMP);
