INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '카페 자리가 많지 않아서 대기자 명단에 전화번호 적고 10분정도 기다리다 입장했습니다. 설향딸기크로플이랑 아메리카노 세트로 시켰어요. 디저트 포함이면 리뷰이벤트 할인도 있어서 좋아요😊 식물도 많아서 카페 분위기가 좋아요 다음에는 칵테일도 시켜볼께요😊', 21, 5, 'GOOD', SYSTIMESTAMP);
