INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '홍대 갈때마다 가는 카페인데 크리스마스 케이크 예약받는다는 소식듣고 바로 예약했어요😊 디저트 맛집답게 케이크도 좋은 재료 쓰시는게 느껴졌고 특히 생딸기가 너무 맛있었습니다 ㅜㅜ 내년 크리스마스에도 여자친구랑 무조건 예약할 예정이에요❤️😉', 21, 6, 'GOOD', SYSTIMESTAMP);
