INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '딸기케이크가 유명한 듯 해서 시켰는데 아주 맛있었어요 그런데 시킨 음료 아바라 아이스티 밀크티는 정말 너무 별로네요.. 가격만 비싸고 저렴 프차보다 맛이 연해요 그리고 매장에 인스타용? 사진 찍는 사람이 많아 너무 어수선했습니다', 38, 1, NULL, SYSTIMESTAMP);
