INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '카페 너무 이쁘고 깔끔해요 크리스마스컨셉인데 진짜 예뼈요! 티라미수 크로플도 진짜 맛잇었습니다ㅎㅎ 분위기도 좋고 음료도 다 예뻐서 데이트장소로 좋운 거 같아요', 4, 9, 'GOOD', SYSTIMESTAMP);
