INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '오랜만에 만난 친구와 이른 저녁후 찾은 카페 아들이 가보고 싶어해 들렀는데 분위기도 괜찮고 음로도 커피도 좋았어요. 얼음 얼릴때 꽃과 허브를 같이 얼려 예쁘고 에이드도 복숭아로 시켰는데 작은 병에 따로 나와 직접 부어 마시게 되어있어요. 시간이되면 분위기가 확 바뀌는 타임이 있는데 좋았어요.', 48, 5, 'GOOD', SYSTIMESTAMP);
