INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '딸기 크로플 시켰는데 맛있어요! 딸기가 시지않고 단편이에요! 아메리카노도 안시고 고소해서 맛있어요~ 복숭아 에이드도 찐 복숭아 과육이랑 향도 인위적이지 않고 맛있는데 조금 달아요! 크로플에 생크림이 좀 아쉽네요🥹 딸기케이크 만드는 가게인만큼 생크림을 좋은 동물/식물 섞어서라도 사용해도 훨씬 맛있을것같은데 금방 휘핑 무너지는 캔 휘핑크림 맛이에요ㅠ 아이스크림은 맛있는데 전반적으로 휘핑크림 때문에 좀 마이너스 되는것같아요ㅠㅠ 이상한 향이라 해야하나 맛이 좀 나서 아쉬워요 크로플 하나 가격이 2만원에 가까운만큼 좀 더 좋은 휘핑크림으로 쓰셔도 되지않았나 싶어요!', 126, 24, 'BAD', SYSTIMESTAMP);
