INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '대화하고 떠들기 좋은 카페에요! 저녁되니까 불 끄고 무드등으로 켜두시는데 분위기 좋고 겨울인데도 따수워서 조아요~ 사장님두 친절하시고 굿입니다', 39, 8, 'GOOD', SYSTIMESTAMP);
