INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '발코니가 되게 멋진 그런 홍대빙수 카페 겸 펍이었습니다. 빙수도 과일을 한껏 써서 화려했고 칵테일도 예뻐요. 해당 리뷰는 업체로부터 할인권을 제공 받아 작성했습니다.', 11, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '와 가게가 진짜 생화로 진열해놨더니 들어가자마자 꽃향기가 나는 가든 같은 가게에영!! 빙수 시켰는데 빙수 냉동이 아니고 생망고에요!!o̴̶̷᷄  ̫ o̴̶̷᷄♥️대박 복숭아도 맛있고 밑에 빙수안에 과일도 있어여!! 또 너무단게 아니고 적당히 단맛에 또 오고 싶은 맛입니다! 단골 하고 싶은 가게입니당!!🥹😍', 19, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '들어가자마자 인테리어가 예뻐서 놀라고 디저트 먹고 맛있어서 놀란 곳이었어요! 무화과알밤 크로플 먹었는데 달콤하니 너무 맛있어서 힐링했습니다~', 49, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '홍대에 이런 루프탑 카페 있는지 알았으면 진작 왔을텐데 이제 알게된게 아쉬울 정도로 정말 예뻐요🌷지금 가을 하늘 넘 예쁜데 예쁘게 꾸며진 루프탑에서 사진 찍으니 사진도 잘나오고 칵테일과 무화과 크로플 먹었는데 그야말로 힐링이에요🩷 이국적인 분위기에 외국인 손님들도 있어서 외국 놀러간 듯한 기분이었습니다!', 43, 1, 'GOOD', SYSTIMESTAMP);
