INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '홍대역카페 발코니가든에서 애플망고눈꽃빙수외 땡모반수박쥬스 먹었다. 둘 다 진짜 달고 맛있다. 7번출구 바로 앞이라 약속잡기 편했다. 루프탑 진짜 멋지다. 시원한 가을 되면 야외에서 커피마시고 싶다', 15, 5, 'GOOD', SYSTIMESTAMP);
