INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '한 입 베어 무는 순간 딸기의 신선함과 부드러운 크림이 완벽한 하모니를 이뤄 입안에서 사르르 녹습니다. 정말 너무 맛있었습니다.', 13, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '케이크 자체는 맛있었는데 딸기가 물렀던건지 보관을 잘못하셨는지 전 전문가가 아니라 모르겠지만 제가 알던 생딸기 식감은 아니었네요', 6, 5, 'BAD', SYSTIMESTAMP);
