INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '빙수 먹으러 왔다가 오늘 신메뉴 나왔다고 해서 먹어봤어요. 발코니 가든 찐단골로써 이번 신메뉴도 아주아주 맛있습니다. 부드러운 크림과 달달한 밤과 상큼한 무화과가 어우러져서 아주 존맛탱입니다. 이제 가을인가 싶기도하고...아주 존맛탱구리니까 신메뉴 드셔보세요. 발코니가든 디저트는 역시 믿고 먹는 👍  홍대 최애 카페입니다.', 33, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '너무 맛있어서 이번엔 남자친구 데려왔습니다 !! 이번에 가격이 올라 30900원이네요 ㅠㅠ 그치만 그만큼 값어치 충분합니다 ~! 남자친구가 환장하고 먹네요 ㅎㅎ 진짜 데려올때마다 칭찬받는 곳이라 많이 아낍니다', 20, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '복숭아 망고 빙수가 너무 맛있었어요! 망고도 생망고인것 같고 복숭아가 넘 달달해용~ 우유맛 얼음도 짱맛! 그리고 배고파서 피자도 시켰는데 바질향 나면서 왜이렇게 맛있는지~~~ 다음에 또 먹고싶은맛! 아쉬운점은 조금 비싼가격? 그치만 맛있었으니 만족!', 20, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '애플망고를 생망고로 가득 올린 호텔식 빙수를 합리적인 가격으로 먹을 수 있는 곳이었습니다. 분위기도 너무 좋고 평일인데도 사람들 꾸준히 완전 인기있는 홍대빙수 맛집인듯.. 여기 커피도 엄청 맛있어요.', 33, 9, 'GOOD', SYSTIMESTAMP);
