INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '화사한 분위기가 너어어어무 이쁜 발코니가든이네용 ㅋㅋ 친구랑 갔는데 친구도 너무 이쁘다고 좋아했습니다 빙수 완전 맛도리라 또 갈거에용 추천🧡🧡🧡', 76, 12, 'GOOD', SYSTIMESTAMP);
