INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '근처에 빙수 맛집 검색해서 왔는데 메뉴가 다양하더라구요! 과일도 신선하고 달달하고 맛있네요 🫶🏻 주차가 어려워서 근처 공용주차장에 주차하고 오니까 1분컷이라 괜찮네요! 다만 인기가 많아 웨이팅있을 수 있으니 잘 알아보고 오시면 좋을것 같네요 ㅎㅎ', 15, 8, 'GOOD', SYSTIMESTAMP);
