INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '루프탑감성 느끼려고 가끔 찾아요~ 사진도 잘 나오고 분위기 너무 좋아요💗 연인끼리 친구끼리 동료끼리 가도 좋아서 다양하게 찾아오시는 거 같아요! 아쉬운건 아인슈페너가 생크림휘핑이 올라간 게 조금 독특한 음료도 있고 다양한 음료, 칵테일, 디저트 있어요', 73, 15, 'GOOD', SYSTIMESTAMP);
