INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '분위기 넘 좋고 빙수 맛있어요! 생망고 엄청 달달하구 고퀄이에요ㅎㅎ 2층 테라스도 분위기 좋더라구요 :) 또 방문하고 싶은 곳이에요!', 46, 3, 'GOOD', SYSTIMESTAMP);
