INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '홍대입구역 7번 출구 바로 앞에 있어요~ 맛있는 빙수와 테라스가 멋진 카페입니다. 애플망고빙수 정말 과일을 듬뿍 넣어주셔서 눈꽃빙수가 더 맛있어요. 저녁에는 시원한 테라스에서 맥주와 주류도 즐길 수 있어요', 46, 0, 'GOOD', SYSTIMESTAMP);
