INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '분위기 너무 좋고 메뉴가 다양해요~!! 센스있게 크로플이랑 아메리카노 세트가 있더라고요🥰 달달한거 먹고 물릴 대 아메리카노 먹으면 딱이에요! 테라스도 한번씩 구경가 보세요', 40, 3, 'GOOD', SYSTIMESTAMP);
