INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '애플망고 복숭아빙수랑 커피2잔세트해서 먹었는데 맛있었어요 빙수가 하나에 3만원정도해서 비싸다고생각했는데 생과일 한가득 올려주니까 납득했습니다 ㅎㅎ 복숭아도 망고도 말랑달달해서 10분만에 순삭했어요 일요일 4시쯤갔는데 대기명단에 이름이랑 전화번호적고 5층에서  30분정도 웨이팅하고갔어요', 5, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '가격도 괜찮고 무엇보다 빙수 양과 과일 퀄리티가 너무 좋았어요!!!!! 저희가 방문했을 때 대기가 1팀 있었는데 금방 5~7분 이내로 연락이 왔어서 덥지 않은 시간에 빙수 먹을 수 있어서 좋았습니다 👍 게다가 보통 빙수 따로 커피 따로 판매하는 점포들이 많은데 여기는 세트 상품으로 판매해서 둘이서 먹기에 딱 좋았어요! 망고빙수 & 복숭아빙수 좋아하시는 분들 추천드려요~!', 36, 1, NULL, SYSTIMESTAMP);
