INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '서울여행와서 지쳐 들어간 카페였는데 너무 만족했어요 특히 빙수의 과일과 우유얼음이 잘 어울려서 더욱 잘 먹었습니다! 오늘은 크로플이 다 떨어져서 못 먹었지만 다음에 기회가 된다면 다시 와서 크로플 먹어보려고요!', 34, 8, NULL, SYSTIMESTAMP);
