INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '홍대 놀러왔다가 망고빙수 먹으러 왔어요!! 매장 인테리어도 스튜디오처럼 사진찍기 좋게 잘 해놓으셨고 빙수 위에 망고랑 복숭아 토핑도 푸짐하게 올라가있는게 정말 맛있게 잘먹었습니다!!', 32, 6, NULL, SYSTIMESTAMP);
