INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '오래하고 분위기가 좋아요! 루프탑까지 있어서 요즘 같은 날씨에 머무르기 좋았고 디저트까지 맛돌이❤️‍🔥 빙수까지  버억 먹고 재밌게 놀다가유~', 119, 24, NULL, SYSTIMESTAMP);
