INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '여친이랑 왔어요☺️ 데이트하기 딱 좋아요 메뉴도 다양하고 다 먹음직스러워 보여요 🤤 여친이 만족하는 맛이에요 사랑한다고 전해달래요😍 진심으로 너무 맛있고 다음에 또 올래요 미친맛 저도 사랑한다고 고백하고싶어요!!', 25, 4, 'GOOD', SYSTIMESTAMP);
