INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '꽃과 푸릇푸릇한 식물들이 있어서 넘 예쁜 곳이에요! 게다가 디저트와 칵테일도 맛있음🩷 홍대역 바로 앞 이런 카페가 있는지 몰랐는데 조용해서 다음에 여기 또 갈거에요!', 73, 15, 'GOOD', SYSTIMESTAMP);
