INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '커피가 투샷이라고 하는데 너무 싱겁고 맛이 없습니다. 저가 브랜드 커피가 오히려 더 맛있습니다. 분위기가 좀 시끄럽고요. 돌체캬라멜딸기라떼는 많이 느끼해서 못먹겠더라고요. 케이크도 딱히... 요즘 좋은 카페가 많은데 굳이 추천하고 싶지않은 카페네요.', 7, 0, 'BAD', SYSTIMESTAMP);
