INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '티라미수 크로플 정말 맛있구여!!! 음료도 너무너무 맛있어요!!!😋 인테리어도 이뿌고 사진도 잘 나와요ㅠㅠ 다른 디저트도 먹어보러 또 와야겠어요!! 🤗', 8, 4, 'GOOD', SYSTIMESTAMP);
