INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '생망고보고 온건데 복숭아까지 생과일이라 더 좋았어요!! 과일도 맛있고 안에 우유얼음에 위에 바닐라 아이스크림도 찐한맛이라 아이스크림만 먹어도 맛있습니다!! 날이 너무 더워서 급하게 찾아서 온건데 앞으로 자주 오려구요👍👍', 23, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '애망빙 철이 끝나갈거 같아서 그전에 먹어보러 찾다가 생망고로 만드는 곳 찾아서 왔어요~ 망고는 위에 보이는 양이 다인데 안에 망고잼? 비슷한거 조금씩 들어있어요 망고가 신선하긴 한데 철이 좀 지나서 그런지 많이 달지는 않지만 오히려 적당히 달아서 좋아요 2~3인이 먹기 충분해요', 56, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '*제품을 제공받았습니다. 애플망고빙수 먹었는데 숙성 진짜 잘되서 너무 맛있었어요. 과일도 큼직하고 얼음도 우유 얼음이고 아이스크림까지... 신라호텔망고빙수 부럽지 않은 맛이었습니다! 칵테일도 시그니처라서 독특하고 고급스러웠습니다!', 21, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '애플망고 복숭아 눈꽃빙수 +아메리카노 1잔 세트 주문했습니다. 키오스크 주문하는데 옆에 냉장고에 복숭아가 냉장보관 되어있어 뭔가 더 믿음직스러운 느낌이었어요. 잠깐 기다리니 메뉴가 나왔는데, 달달한 망고에 향긋한 복숭아 맛이 좋았습니다.', 91, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '가을이라 몽블랑&무화과 크로플이 나왔더라고요! 커피랑 세트로 시켰는데 밤 맛도 달달하면서 안에 무화과가 가득 들어있어서 맛있었어요ㅎㅎ 둘이서 먹으면 딱 좋을 것 같아요🩷', 97, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '망고빙수를 워낙 좋아해서 맛집 중의 맛집만 골라다녀서 그런지.. 3만원까지의 맛은 아닌듯 합니다 망고퓨레가 있었으면 더 좋았겠지만 우유빙수에 복숭아요플레? 베이스 맛이 강했어요 복숭아도 단맛나도록  절여놓으신 건지 뭔가 톡쏘는 맛이 나서 다른 건 다 맛있었는데 엥?했던거 같아요 그래도 저녁에 분위기 있는 음악 들으면서 루프탑에서 먹으니 기분 좋았네요! 한번쯤은 드셔봐도 좋을 맛입니다~', 27, 0, 'GOOD', SYSTIMESTAMP);
