INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '리얼 생과일 토핑에 우유빙수 찐인 맛집입니다~ 들어오자 마자 생화향기에 한번 반하고 분위기에 취하고 빙수맛에 그냥 끝장입니다~', 50, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '여자친구가 빙수를 엄청 좋아하는데 여자친구를 만족시킬 빙수를 찾지 못하다가 발견한 발코니가든입니다 빙수가 진짜 미쳤어요 가격이 좀 나가지만 가격에 걸맞는 빙수를 원하신다면 발코니가든을 추천드립니당', 34, 1, 'GOOD', SYSTIMESTAMP);
