INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '맛있어 보이는 디저트가 너무 많아서 고르기 힘들었어요 ㅜㅜ 차 종류도 다양하고 음료 종류도 다양해서 커피 못 드시는 분들도 찾아오기 좋을 거 같아요!', 12, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '발코니가 눈에 띄어서 들어온 발코니가든 오늘같이 선선한날 너무좋은 루프탑👍 커피도 맛있고 같이먹은 달달구리도 좋아요 수다 잘떨다 갑니다 :)', 39, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'TERRACE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '복숭아랑 애플망고 반반 빙수가 나왔더라구요?? 와...진짜 미쳤어요. 달달한 망고에 아삭아삭 씹히는 복숭아 식감이 더해지니 완전 찰떡. 마지막에 복숭아 향이 입안에 확 퍼져서 너무 좋아요. 복숭아랑 망고 다 먹고 나서도 중간중간 과육들이 있어서 끝까지 맛있게 먹을 수 있어요. 루프탑도 넘 예뻐서 이리저리 들고다니면서 SNS용 사진도 잘 건졌어요 ㅋㅋ 다음엔 애플망고랑 딸기 반반 빙수 먹으러 올게요', 19, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'TERRACE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '망고빙수 맛집이라고 해서 왔는데 망고가 진짜 양도 많았고 달달했고 아이스크림 + 우유빙수였어서 당충전 제대로했어요! 저녁되니까 불끄고 조명도 틀어주셔서 더 분위기가 좋았습니다!', 23, 4, 'GOOD', SYSTIMESTAMP);
