INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '과일이 냉동이 아니라서 신선하네요. 딸기는 새콤달콤하고 망고는 잘익어서 달달하네요. 내부에 자리가 없어서 외부에 왔는데 아무도 없어서 오히려 좋네요. 루프탑은 여름에 비 온 다음날이나 봄 가을에 오면 좋을 거 같아요.', 57, 11, 'GOOD', SYSTIMESTAMP);
