INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '정원이 있는 테라스 카페라서 궁금해서 방문했어요! 메뉴 다양하고 식물원 분위기라 재밌어요 생각보다 에어컨은 약한 느낌 ㅠㅠ 메뉴도 다양하고 빙수도 맛있었어요!! 생망고써서 더더욱 맛있었어요', 37, 3, 'GOOD', SYSTIMESTAMP);
