INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '생애프랑고 빙수라고 해서 방문하게 되었는데 애플망고도 너무 맛있고 커피도 맛있고 무엇보다 분위기가 정말 미쳤어요! 플랜테리어 너무 예쁘게 잘 보고 갑니당', 16, 3, 'GOOD', SYSTIMESTAMP);
