INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '과일 너무 싱싱하구 많이 들어있어요!! 복숭아랑 망고 빙수인데 존맛 ㅠㅠㅠㅠ 과일빙수 오랜만인데 너무 맛있어서 조만간 재방문각🩷🩷 안 유명해졌으면 좋겠다 지금도 웨이팅 많고든욧 오늘은 자리 하나 남았을때 바로 앉아서 완전 럭키걸 🥹✨', 10, 2, NULL, SYSTIMESTAMP);
