INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '친구랑 둘이 와서 하나 먹었는데 둘다 배부르게 먹었어요 ㅎㅎ 과일도 맛있고 양도 많아요! 빙수 밑에 초코칩도 있어요. 망고가 생망고에요 중요함 이거. 그리고 분위기도있네요. 근데 아이스크림은 오묘해요. 가격대는 좀 있는데 과일이 많아서 그렇게 아깝지는 않네요~ 잘 먹었습니다~', 5, 1, 'GOOD', SYSTIMESTAMP);
