INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '진짜 너무너무너무너무 맛있어요!! 저랑 친구는 사실 디저트 먹으면서 공부하는게 주 목적이여서, 디저트 포장해서 근처 공유오피스로 갈까 했었는데 디저트류는 포장이 안된다고 하더라구요ㅠㅠ 잠시 스터디를 포기하고 디저트를 즐긴게 후회되지 않을정도로 맛있습니당', 75, 15, NULL, SYSTIMESTAMP);
