INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '애플망고 복숭아 눈꽃빙수 🧡💛🩷 ₩28,900원 생각보다 가격이 나가지만 그만큼 생과일이라서 아깝지 않았어요 ! 상큼하고 달달하고 기분 좋은 ~~ ♥ 여름에 이만한 디저트가 있을까요 !! 진짜 최고', 24, 3, 'GOOD', SYSTIMESTAMP);
