INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '망고빙수 유목민들은 집중.. 냉동 망고는 싫어서 호텔식 빙수라는 말에 방문했는데 진짜 생과일이라 대대대만족!! 우유얼음이랑 바닐라 아이스크림도 너무 맛있고 잘 후숙된 생과일들 넘넘 맛있어요ㅠㅠ 땡모반이랑 코코넛 망고 쉐이크도 대만족👍👍', 33, 5, 'GOOD', SYSTIMESTAMP);
