INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '너무너무 맛있었어요. 망고도 달짝지근한데 복숭아는 더더더더더더더더 달짝지근해서 둘이 먹다가 하나 죽어도 아이돈노할 정도로 맛있고 아이스크림은 달코달콤다다다달콤해서 안그래도 더운 날씨인데 아주 시원했어요', 59, 14, 'GOOD', SYSTIMESTAMP);
