INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '저녁에 갔는데 너무 좋았어요! 바람도 선선해서 루프탑에서 분위기도 너무 좋게 먹었습니다! 망고가 냉동 망고가 아니고 생망고라서 너무 좋았습니다!', 40, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '애플망고 복숭아 눈꽃빙수 너무 맛있어요🫢💛 과일 다 신선하고 눈꽃 얼음이랑 아이스크림도 맛있어서 거의 5분만에 쉬지 않고 먹었어요! 둘이서 먹기에 적당한 양인 것 같아요:)', 61, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '비오는 날에 친구랑 왔는데 처음에 사람이 많지 않은데 윗층에 사진을 찍으려고 윗층에 갔다왔더니 자리 없을 정도로 사람들 엄청 몰려있더라고요. 비가 와서 윗층 앉아서 힘들어서 사진만 찍고 내렸어요. 디저트 비쥬얼이 짱임 👏👏 이쁘고 맛있어요^^', 75, 12, 'GOOD', SYSTIMESTAMP);
