INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '마싯어여 애플망고 복숭아 빙수ㅎㅎ 너무 먹고 싶어서 우연히 찾게 된 곳인데 성공했어요! 가격이 좀 아쉬워요 ㅠㅠ 너무 비싸다?ㅎ 양대비 가격이.. 그치만 맛은 만족해요!', 3, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '빙수 맛있어요! 커피는 산미가 조금 있는 편이에요 날이 덥고 사람이 많아서 그런지 카페 내부가 그렇게 시원하진 않았어요... 그렇지만 폭염으로 힘들었던 상황이라 더운 와중 너무 꿀같은 카페였습니다', 46, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '비싼가 싶지만 양도 푸짐하고 달달하니 너무 맛있어요 ! 날도 적당이 선선해지니까 테라스에서 뷰 바라보고 있자니 제대로 힐링돼요~ 선곡도 좋고 조명이 예뻐서 밤에 가시는 거 추천합니다! 초코크로플도 당충 제대로 되고 추천이에오', 71, 16, 'GOOD', SYSTIMESTAMP);
