INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '생화에 생과일 듬뿍 보는맛도 훌륭했던 카페 직원분들 친절하시고 다음엔 밤에 방문해서 칵테일 마셔보고 싶어요 홍대 분좋카 추천!!', 103, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '가격에 놀랐는데 가격값 하네요🙂‍↕️🙂‍↕️ 애플망고가 특히 맛있고 복숭아 퓨레가 들어있어 달달하고 상큼했어요 사람이 많아서 창가자리에 못 앉아서 아쉬웠는데 다음에 오면 꼭 창가 앉으려구요!! 잘먹었습니다', 43, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '5층에 웨이팅석 있으나 야외라서 더움주의. 앞에 2팀 있었고 한 20분 기다렸네요. 더울땐 2층 피규어샵 구경 추천ㅎㅎ 인테리어 이쁘고 빙수 맛있어요.', 32, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '2년 전에 친구랑 왔다가 이번에 또 방문 했어요 지나가다가 팜플렛 봤을 때 빙수 먹고 싶었는데, 생 망고랑 복숭아 때문에 너무 맛있게 먹었어요. 직원 분들도 친절하시고 매장도 청결 해요.', 19, 4, 'GOOD', SYSTIMESTAMP);
