INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '더위를 피하려고 빙수 맛집 찾아서 친구들이랑 왔는데 매장도 넓고 콘센트도 있고 의자도 편했습니다! 친구들이랑 수다 떨면서 쉬기 너무 좋은 공간이었어요 ㅎㅎ 빙수는 애플망고/복숭아 반반으로 했는데 과일도 엄청 달고 맛있고 과일이 바닥까지 들어있어서 끝까지 맛있게 먹을 수 있어서 좋았어요 👍', 46, 5, 'GOOD', SYSTIMESTAMP);
