INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '진짜 오늘 너무나 더웠는데 시원하고 맛있는 빙수 + 아메리카노 덕분에 살아났습니다 ㅜ ㅜ♡ 자리도 처음에 잡았던 곳이 너무 더웠는데 옮겨주시고 너무 감사드려요! 생과일이 들어간 빙수라서 그런지 너무 달달하고 맛있었어요 !😊', 96, 26, 'GOOD', SYSTIMESTAMP);
