INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '냉동망고가 아니라 생망고여서 좋았어요!! 딸기도 맛있고 다음에 또 와서 먹고싶어요 ㅎㅎ 인테리어도 이쁜데 저녁에 와서 칵테일 마시면 더 좋을거 같아요~! 사진 별로 못찍어서 아쉬워요😢', 44, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '야외 풍경도 너무 좋고 복숭아망고빙수 진짜 너무 맛있음니다.. 퀄리티도 너무 좋고 망고도 생망고 써서 더 맛있어요!! 분위기도 좋아서 데이트 장소로 좋을 것 같아요 잘 떠들고 잘 먹고 갑니당🩷🩷', 17, 6, 'GOOD', SYSTIMESTAMP);
