INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '너무 더워서 빙수 찾아왔어요~! 냉동과일이 아니라 좋았어요 과일 자체가 달콤해요 과일이 적나 싶었는데 밑으로 먹어갈수록 과일이 계속 나와요 ㅎㅎ 홍대 빙수맛집으로 재방문 의사 완전 있어요~', 9, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '조금 기다리긴 했지만 윗층에 테라스에서 대기해서 시원하게 기다렸다가 주문했습니다 빙수도 맛있고 카페 내부도 예쁘고 시원해서 좋아요~~', 14, 6, 'GOOD', SYSTIMESTAMP);
