INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '생과일을 사용하셔서 과일이 너무 싱싱하고 맛있었고 빙수도 너무 예쁘게 나와서 맛있게 먹었습니다:) 분위기도 좋고 뷰도 좋아 강추드립니다!', 13, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '역시나 실망시키지 않는 곳!! 이번엔 망고복숭아 빙수가 뙇 ㅋㅋㅋ 디저트배가 따로 있다는 말이 괜히 있는게 아닌듯해요 🫠 오늘도 잘 먹고 갑니다!!', 40, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '오랜만에 찾아온 발코니입니다!! 마침 직장동료도 이 곳을 알던지라 식사 후 디저트 뿌시러 왔네요 ㅋㅋㅋ 망고딸기의 조합 미쳤따리~~~ 스페샬한 메뉴 넘넘 좋아요!! 날씨도 좋아 5층 야외는 만석이라 못 앉았지만 또 놀러올께요!!', 4, 9, 'GOOD', SYSTIMESTAMP);
