INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '빙수가 먹고 싶어서 찾아서 왔는데 진짜 맛있어요 우유맛 완전 찐 더워서 그런지 다들 빙수 하나씩 드시고 계시더라구요 빙수 맛집인듯ㅋㅋ 그리고 목말라서 수박주스도 하나 시켰는데 더운 날에 먹어서 그런지 몰라도 겁나 맛있음.......한입 먹는순간 게임오바 싹다 구속시켜', 14, 3, 'GOOD', SYSTIMESTAMP);
