INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '친구 추천으로 방문했는데 인테리어도 예쁘고 디저트들 맛도 좋았어요! 대기 없이 바로 입장할 수 있었고, 주문해도 오래 기다리지 않아도 됐어요. 칵테일 종류도 다양한데 논알콜으로도 선택할 수 있어 좋았고 전부 정말 맛있었습니다~~ 🥰', 43, 0, 'GOOD', SYSTIMESTAMP);
