INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '조금 비싸다 생각했는데 그냥 너무 맛있어요 돈값해요 지금 복숭아 철이라 복숭아 빙수 존맛... 안에 퓨레도 들어있어요 5명이서 두개 10분컷했서오💖', 11, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '딸기빙수 맛있어요. 진한 우유맛이나는 빙수에 설향딸기 올려주시더라고요. 4층에 있어서 긴가민가 했는데 올라오니까 넘 예쁘고 만족스러워요. 발코니 그늘에 뷰도 괜찮고 예쁜 꽃 잔뜩 있는 예쁜 카페네용❤️', 0, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '매장이 너무 덥고 웨이팅 관리 안하심ㅜㅠ 직원분들끼리 수다떨다가 웨이팅 밀려있는데 문의하니까 그때서야 테이블치우고 전화 돌리고 … 메뉴판이랑 키오스크 메뉴랑 종류 차이 엄청 많아요', 2, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '망고랑 복숭아가 듬뿍 들어가서 과일만 먹어도 맛있고 위에 올라간 아이스크림도 너무 부드럽고 맛있어요!! 매장도 예쁘고 분위기도 좋아서 다시 오고싶은 곳이예요💞', 49, 5, 'GOOD', SYSTIMESTAMP);
