INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '오 너무 맛있어요! 복귀하기가 싫어지는 맛이네요 ㅎㅎ 정말 맛있어서 한 번만으로도 충분히 오래 기억될 것 같네요😁 잘 먹고 갑니다.', 79, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '복숭아 맛있었고 1스쿱떠준 바닐라아이스크림이 요거트였으면 더 맛있었을듯 ( 개인적으로 바닐라는 안좋아함) 먹다보면심심한대 접시바닥에 과일조각이 더있어서 섞어먹으면 덜심심함', 28, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '홍대 오면 종종 들리는 곳인데 망고랑 복숭아 반반 빙수 판매하길래 먹어 봤는데 너무 맛있어요 앞으로 빙수 먹으러 자주 방문할 것 같아요 애플망고가 특히 맛있으니까 망고 좋아하시면 반반 말고 망고빙수로 드세용 더워서 못 나갔지만 테라스도 정말 예뽀요 🤍', 18, 3, 'GOOD', SYSTIMESTAMP);
