INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '망고빙수 먹고싶어서 검색해서 간곳인데 양많고 맛있었어요!! 루프탑좌석이 빙수먹기 아주 좋았어요🥭 아메리카노는 시거나 쓰지않고 딱이였어요🙂', 82, 16, 'GOOD', SYSTIMESTAMP);
