INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '맛있고 상큼하고 매장이 시원해요 과일 맛있네용 복숭아 살짝 물복이라 맛있고, 애플망고도 냉동 아니어서 맛있어요. 수박주스는 냉동이라 그런가 그냥 그래용', 28, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '너무 더워서 복숭아 망고 빙수 먹으러 왔는데 당도도 쩔고 아이스크림 기본 베이스도 달콤하고 시원해서 너무 맛있더라구요 >_< 여름 가기 전에 망고 복숭아 빙수 꼭 드세용!!', 370, 38, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '홍대 망고빙수 찾다가 들어왔는데 망고도 완전 달달하고 복숭아도 완전 향긋하고 달아여 말딱숭아여서 빙수랑 같이 먹기 넘 좋고 마싯습니다 진짜 미싯그여 그리고 마싯그여 정말로 마싯어여', 54, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '빙수 먹으러 왔어요~! 망고+딸기랑 망고+복숭아 중 제철인 복숭아로!! 비주얼은 당연히 합격입니다. 얼음 위에만 과일이 있는 줄 알았는데 안에 과일이 무더기로 파묻혀있네요!!! 넘 맛있어요~!', 23, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '잘 익은 생과일이라 부드럽고 너무 맛있어요!!ㅠㅠ 밑에도 복숭아가 잘게 깔려있어서 끝까지 맛있게 먹었습니다! 웨이팅은 한 30분 이내였습니다!', 33, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '홍대에 루프탑이 있는 카페를 찾으신다면 요기-! 실내도 푸릇푸릇하게 이쁘게 꾸며놓아져있고 루프탑도 굉장히 시원해서 좋아요 :-) 칵테일도 있으니 밤에 와도 좋을 거 같아요 !', 0, 8, 'GOOD', SYSTIMESTAMP);
