INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '비 오는 날 방문해서 달달한 디저트가 먹고 싶었는데 딸기🍓가 너무 싱싱하고 맛있었어요. 빙수🍧 너무 맛있고 기분 좋게 달달하고 크로플🧇도 너무 맛있었어요. 인테리어가 너무 이뻐요!!💓 큰 식물🪴들이 많아서 자연적인 분위기라 너무 좋았어요👍👍', 51, 18, 'GOOD', SYSTIMESTAMP);
