INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '진짜 솔직하게 처음엔 빙수 이 가격이면 싸지는 않네 라고 생각하고 있었는데 한 입 먹자마자 모든 가격이 납득되는 맛임 이 곳의 문제는 딱 하나입니다 입맛이 겁나 높아져서 이제 다른 빙수는 성에 안 찬다는 거,,, 과일도 얼음도 아이스크림도 다 미친맛인 건 여기 하나...', 7, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '망고빙수 검색하다가 비쥬얼 보고 홀려서 찾아왔어요 제가 좋아하는 망고 복숭아 둘 다 먹을 수 있어서 너무 좋았고 아이스크림도 달달하니 맛있어요 ㅠㅠㅠ 얼음은 설레임 맛이었어여 최고', 54, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '여긴 뭐지?하는 마음으로 들어왔는데 생각보다 사람도 많고 분위기도 좋았습니다 빙수 가격이 비싼편인데 그만큼 맛있고 또 오고 싶어요🙆‍♀️', 5, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '딸기가 많아서 너무 맛있어요! 음료도 깔끔하고 괜찮네요❣️ 딸기크로플은 바삭하고 달달하니 좋아요!! 딸기 눈꽃빙수는 말모 ㅠ 치즈 카나페는 먹기 편해서 좋았네요 뷰도 죽여서 날씨좋은 봄날에 딱이에요 ☺️', 59, 17, 'GOOD', SYSTIMESTAMP);
