INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '진짜 배불러도 들어가는 존맛 빙수..💗 인테리어도 너무 이뻐서 데이트로도 꼭 다시 오겠습니다 :) 선곡도 너무 좋고 분위기도 너무 좋아요 ㅎㅎ', 40, 9, 'GOOD', SYSTIMESTAMP);
