INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '저번에 망고빙수 맛있어서 다시 방문했습니다! 주말에 와서 쫌 기다리긴했는데 빙수는 여전히 맛있어용 위에 대기공간도 있어서 추천합니다!', 100, 24, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '망고빙수에 미쳐서 여기저기 가보고있는데 오늘도 성공이네요💛💛💛💛 과일도 맛있고 빙수얼음도 맛있어요!! 플랜테리어도 예쁘고 시원합니다 ㅎㅎ 색다르고 맛있어보이는 메뉴들도 많아요🧚‍♀️', 41, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '정말 뜬끔없이 4월인데 28도를 찍는 엄청난 날씨여서 눈에 보이는 가장 시원할 것 같은 카페를 골랐어요. 가게에 들어왔을때는 더웠는데 옥상 올라오니까 뻥 뚫려있고 바람도 불어서 시원하네요. 홍대 거리가 다 내려다보이는 뷰도 너무 좋아요. 홍대 오면 자주 올거같아요. 개꿀.', 9, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '어쩌다가 발견하게됬는데 음식부터해서 디저트나 칵테일까지 있어서 되게 다양하게 즐길 수 있어요. 제가 되게 사진 못 찍는 편인데도 그냥 아무곳에서나 찍어도 이쁘게 나오더라고요ㅎㅎ', 20, 9, 'GOOD', SYSTIMESTAMP);
