INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '매장에 들어오자마자 생화향이 퍼져서 너무 기분이 너무 좋았어요 곳곳에 싱싱한 생화들이 있어 분위기가 너무 좋소 쇼파도 너무 푹신해서 힐링하는 기분이에요 차도 술도 함께 시킬수 있고 빙수나 디저트 종류도 다양해서 일행수가 많더라도 호불호가 없을것 같아요 차 향도 깊고 생각보다 너무 즐겁네요 커피류가 8시 반이면 주문이 안되는게 좀 아쉽긴합니다 좌석이 붙어있어서 다소 시끄러울순 있는데 꽃으로 파티션이 나뉜 느낌이라 공간이 분리된 느낌은 들었어요 홍대 지리 잘아는 동생이 데리고와줬는데 맛집 리스트 뺏어 보고 싶을만큼 너무 맘에 들었습니다 담에 다른친구들 데리고도 와보고싶어요 :)', 6, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '낮에 한 번 왔었는데 밤에 오니 색다른 분위기라 좋네요. 빙수가 가격대가 있는 편인데 왜 비싼지 알겠어요. 과일을 냉동이 아니라 다 생과일을 쓰더라구요. 생애플망고는 처음 먹어보는데 입에서 살살 녹습니다... 망고빙수 꼭 드셔보세요 추천추천', 75, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '우유 얼음이 되게 부들부들하고 담백해요.ᐟ 홍대에서 주말에 자리 있는 카페 찾기 힘든데 운좋게 바로 자리가 있었고 붐비지도 않았어요~ 망고빙수 맛있게 먹었습니당😋', 21, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '더위 피하려고 급하게 들어왔는데 웬걸 너무 맛있는 빙수를 찾아버림.. 복숭아망고빙수 시켰는데 위에 토핑 전부 생과일이고 밑에도 통조림 복숭아 같은게 깔려있어서 완전 요맘때 맛임 쫀맛탱구리..', 18, 0, NULL, SYSTIMESTAMP);
