INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '복숭아와 망고 조합이라니🥹 조금 비싼감이 있지만 맛있어요! 눈꽃얼음도 맛있네용 ㅎㅎ 5층 야외 테라스 이용했고 저녁엔 시원해서 좋네요!', 25, 7, 'GOOD', SYSTIMESTAMP);
