INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '크로플 비주얼부터 대박,,, 진짜 맛있고 복숭아요거트?? 이것도 진해서 맛있어요! 늦게와서 시간이 촉박해서 아쉬워서 다음엔 일찍 올게요!', 0, 5, NULL, SYSTIMESTAMP);
