INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '생망고랑 복숭아 가득 올라가 있는데 과일맛이 진짜 최고네요👍👍👍 우유얼음 밑에도 시럽+망고 깔려 있어서 끝까지 맛있게 먹었습니다 망고빙수 최고🥭', 14, 3, 'GOOD', SYSTIMESTAMP);
