INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '빵 냄새 너무 좋아서 크로플 시켰는데 진짜진짜진짜 맛있어요 훠궈 무한리필집에서 엄청 먹고 왔는데도 너무 맛있어서 감탄했네요 인테리어도 예쁘고 음료도 맛있습니다:) 다음엔 생크림 크로플 먹으러 올 거 같아요!! 강추합니다👍👍☺️☺️', 49, 5, 'GOOD', SYSTIMESTAMP);
