INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '빙수가 먹고싶다고해서 찾다가 방문했습니다! 아쉽게도 제일 높은층은 수리중으로 못갔지만 다행히 자리가 있어서 바로 앉았습니다 (그래서그런지 좀 바글바글했어요) 망고랑 복숭아 굉장히 맛있게 먹었고 망고는 너무 숙성되서 따끔거릴정도였네요ㅋㅋ 다만 가격대가 높아서 또 올지는...하하', 42, 8, NULL, SYSTIMESTAMP);
