INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '일단 올라오자마자 카페가 너무 이뻐서 반했고 커피가 맛있어서 또 반하고 디저트가 너무이뻐서 또 반했습니다ㅎㅎㅎ 홍대가 좀 번잡스럽고 시끄러워서 별로 안좋아하는데 이 카페는 사람많아도 안복잡하고 너무 좋아요!! 회사에만 갇혀있다가 야외에서 커피마시니까 너무 좋네요 꼭 와보시길 추천합니당!', 62, 17, 'GOOD', SYSTIMESTAMP);
