INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '일단 매장 발코니 부분이 트여있어서 낮에 와도 좋을 것 같아요! 매장에 꽃이 가득해서 꽃향기가 드문드문 나고, 주문할때도 바로 옆에 꽃이 있어서 향긋하고 기분좋게 주문이 가능합니다🫶 크로플 시키면서 딸기가 혹시 맛없으면 어쩌나 했는데 새콤달콤하고 크림도 우유크림인지 깔끔하고 고소했습니다 :) 플라워에이드는 일단 눈으로 즐기고..맛도 너무 달거나 하지않고 은은해서 맛있었습니다. 밀크티도 직접 우리시는지 가루밀크티 맛이 안나서 최고!', 38, 6, 'GOOD', SYSTIMESTAMP);
