INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '생망고 빙수 시즌이 지난 곳이 많아서 찾다가 온 카페에요! 더웠는데 시원하게 잘먹었습니댜 저녁에 바 메뉴도 있어서 홍대에 왔다면 들려보세요~~~', 75, 14, NULL, SYSTIMESTAMP);
