INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '반짝이는 조명부터 인테리어까지 정말 예뻤던 홍대카페!✨ 꽃과 식물들 사이 은은하게 퍼지는 꽃향도 너무 좋았고요:) 신선한 설향딸기 가득~ 겉바속쫀 딸기크로플은 필수 디저트였습니당🍓 진하고 고소한 아몬드 크림라떼, 은은한 산미와 묵직함의 아메리카노까지 커피도 맛집! 저녁 시간에는 조명이 바뀌면서 분위기가 더 살아났는데 음악까지 완벽..👍🏻 이 땐 칵테일 즐기기 딱이더라구요~!🍸 포토존 가득하면서 데이트하기 넘 좋았던 홍대디저트맛집이었습니다❤', 47, 3, 'GOOD', SYSTIMESTAMP);
