INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '설향딸기초코크로플 진짜진짜진짜진짜 맛있어요 ㅜㅜ 친구랑 대화도 안 하고 먹기만 했어요… 와플도 블렌딩 홍차도 정말 너무너무 맛있구 카페도 예뻐서 좋았습니당… 다음에 또 올 것 같아요 🥹🫶🏻', 34, 4, 'GOOD', SYSTIMESTAMP);
