INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '빙수가 너무 맛있었어요 ! 분위기도 정말 좋았어요 ! 조금 어두워지기 시작하면 불도 꺼주시는데 되게되게 예쁘고 감성있어요 촛불도 켜 주신답니다 :> 예쁜 거 맛난 거 잘보구 맛보구 갑니당~!🤗', 9, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '사진 찍기 너무 이쁘고 야외테라스 꼭 가보세요 !! 2층으로 되어있어서 테이블도 넉넉하고 이쁘게 꾸며져있어서 어디서 찍든 인생샷입니당😀 빙수도 맛있구 아메리카노는 산미가 조금 느껴져서 디저트랑 먹기에 잘 어울렸어요 ! 홍대 카페 간다? 발코니가든으로 오세요 😍', 105, 19, 'GOOD', SYSTIMESTAMP);
