INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '카페가 너무 예뻐서 친구랑 방문했어요 !! 직원분들도 친절하시고, 디저트도 다 너무 맛있었고 카페 내부랑 루프탑이 너무 예뻐서 한번 더 놀랐어요 수다 떨기도 좋고 밤되니까 루프탑 저녁뷰가 보여서 더 예뻤어요🥹 다음에 또 방문할게요 번창하세요 사장님 !', 16, 1, 'GOOD', SYSTIMESTAMP);
