INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '냉동과일 아니고 생과일 쓰는 것 같아요 싱싱하고 맛있어요 대기가 조금 있긴 했는데 명단에 작성해두고 5층에서 쉬다가 들어갔어요! 재방문의사 있습니당👍👍', 69, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '요긴 완전 뷴위기맛집이에요 .. 매장 내부 인테리어 대박이고 루프탑도 완전 예쁘게 꾸며져 있담니다. 루이보스티 홍차 시쿘는데 8천원이라 잉 개비싸당 했는데 ㅋㅋㅋㅋ 티포트에 나오네요.. 안 비쌈^^ 다음에 남틴이랑 오고싶어용~~ 근데 소파자리는 다 예약이라 못앉았는데 아무도 안왔어여.. ㅠ 소파자리 앉고싶어여', 33, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '크로플이랑 빙수가 양이 많아요!! 비싼 값 해요 그리고 맛도 정말 좋아요 특히 크로플 너무 제취향.. 둘이서 간단하게 다 먹을 줄 알았는데 배부르게 먹었어요 재방문 의사 있습니다', 81, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '운이 좋게 루프탑에서 마셨어요! 맥주는 조금 비쌌고, 과일치즈 카나페는 맛이 너무 많았어요… 아마 향신료에 민감하신 분은 햄에서 냄새난다고 느낄 수도 있는데, 저는 향신료를 잘 먹어서 괜찮았어요. 그런데 요거트가 생각보다 달았는데, 이걸 확잡는 짠맛이 없다고 해야하나… 비스킷이 너무 무맛이라고 해야하나… 다음번에 가면 다른 걸로 시켜보겠어요', 9, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '딸기빙수 진짜 맛있어요!!ㅎㅎ 카페에서 나는 향기도 너무 좋아요 o̴̶̷̤  ̫ o̴̶̷̤ 뷰도 좋은데 날씨좋을때 와서 너무 좋네요 다음에도 또올게요', 15, 4, 'GOOD', SYSTIMESTAMP);
