INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '여기 제 최애 술집이라 친한 동생을 오늘 데려와보았습니당ㅋㅋㅋㅋ맨날 오는데 리뷰는 이제 처음 써보는거 실화?ㅠㅜ 앞으로 더 자주자주 써보겠습니다:) 제가 추천하는 메뉴는 피나콜라다 인데, 다른곳과 다르게 훨씬 코코넛 맛이 풍성하다 해야하나? 그래서 올때마다 이거만 먹어요ㅋㅋㅋ완전 추천합니다💛🤍 케이크랑 음료도 엄청 맛있는데, 겨울 시즌이라 딸기가 왕창 생기고 들어갔네요ㅠㅠ여름에 나온다고 하니까 그때 또 먹으러 오려구요 ㅎㅎ 카나페 햄과 블루베리, 크림, 과자의 조합이 너무 잘어울려요! 존맛❤️', 27, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '빙수랑 음료 다 너무너무 맛있어요! 카페 인테리어도 멋지고 꽃향기도 너무너무 향기롭고 좋습니다! 예쁘고 편안한 데이트 하다가 갑니다~🩷', 50, 8, 'GOOD', SYSTIMESTAMP);
