INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '빙수랑 아이스티 놔눠 먹었는데 아이스티는 덜 단 아이스티여서 먹을만했어요 빙수는 과일이 아직 좀 단 맛 보단 끝에 쓴맛이 나긴해요. 가게 웨이팅은 제가 갔을때 바로 자리가 나와서 앉자있었는데 뒤에 두팀 오셔서 웨이팅 걸어두고 좀 걸리더라고요', 22, 6, NULL, SYSTIMESTAMP);
