INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '발코니가든'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '매장 분위기가 진짜 좋구요 커피도 맛있구 디저트도 진짜 짱맛있습니다... 눈호강 입호강 하고 왔습니다 넘 추천해요! 딸기시즌이라그런지 디저트에 나온 딸기 신선하고 존맛♡평일 낮에와서 그런지 웨이팅이나 주문 밀리거나 이렁거 없이 들어왔습니다~!', 32, 10, 'GOOD', SYSTIMESTAMP);
