INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '빵순이가 애정하는 연남동 빵집 베이커리 카페 🥰 예전에 왔었는데 오랜만에 와도 넘 맛있는 연남카페에요. 다양하고 맛있는 빵이 한가득!! 포장도 되고, 매장에서 먹고 가기도 좋아요. 배달 포장 주문도 많이 들어오는거 같더라구요. 신선한 치아바타 샌드위치에 커피 먹으면 든든하고 완벽한 브런치 먹기 좋습니다.😋 치즈 좋아하시는 분들은 치즈식빵 꼭 드셔보세요! 단짠단짠 황치즈 소스맛이 아주 제대로에요. 달콤한 맘모스빵도 리얼 꿀맛 그자체입니다. 팥앙금,녹두앙금,견과류,밤,생크림이 알차게 들어있는데 담백한게 아니라 진짜 꿀처럼 달달해서 커피랑 먹으면 계속 들어가요.🥳', 17, 6, 'GOOD', SYSTIMESTAMP);
