INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '2-3년 1-2층으로 확장한 연남동빵집 ‘베어스덴베이커리’ 서교동 살때 오히려 더 자주왓던 듯! 커피도 맛있고 빵들이 아주 맛있음! 와인모임할 때 치아바타나 식빵 준비하기도 좋고 뱅오쇼콜라나 크림빵류도 매우 추천함! #베어스덴베이커리 #펑키와인맛집', 38, 3, 'GOOD', SYSTIMESTAMP);
