INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '홍대 베어스댄 베이커리는 귀여운 곰돌이 감성과 맛을 함께 즐길 수 있는 브런치&빵 맛집이에요. 매일 직접 구운 빵이 진열대에 가득하고, 내부는 우드&화이트톤 인테리어에 곰돌이 소품들이 아기자기하게 꾸며져 있어 보는 재미가 있습니다. 이번에 치아바타 샌드위치, 에햄샌치, 오늘밤 반달(맘모스빵 1/2), 그냥내가젖소(우유크림빵), 오늘의스프(양송이), 아메리카노, 베베슈페너를 주문했는데 모두 맛있었어요. 특히 양송이 스프는 진하고 크리미해 빵과 찰떡궁합이었고, 치아바타 샌드위치는 신선한 채소와 햄·치즈가 듬뿍 들어가 든든했습니다. 베베슈페너는 달콤한 두유 크림과 진한 에스프레소, 곰돌이 쿠키까지 올라가 비주얼과 맛 모두 만족스러웠어요🤍 브런치카페로 완전 강추입니다!', 96, 20, 'GOOD', SYSTIMESTAMP);
