INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '베어스베이커리 홍대에 베이커리 카페 찾다가 들린 카페인데요~분위기 차분하니 너무 좋고 맛있는 빵 종류가 많아서 도파민이 폭발해요!치아바타 샌디위치 퐁신한 빵 신선한 맛이 너무 맛있고 허니바게트는 맛있는 꿀이 바게트에 있는데 진짜진짜 맛있어요!홍대에 들릴 일 있으시면 꼭 들러서 드셔보세요!😄👍', 76, 18, 'GOOD', SYSTIMESTAMP);
