INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '귀여운 인테리어와 따뜻한분위기가 빵순이라 끌려서 들어온곳입니다 빵이름이 신선해서 맘에들어요 다양한 빵들  다먹어보고싶지만 인기 빵부터 하나하나 먹어봐야겠어요 시그니처 베베슈페너도 마니 달지않고 베어 퐁당 넘 귀엽고 달달한게 맛나요 강력추천해요 평일에는 조용해서 혼자 여유롭게 좋아요', 36, 0, 'GOOD', SYSTIMESTAMP);
