INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '지나가다가 빵 종류가 많아보여서 들어왔어요 !!! 아기자기한 무드에 빵도 다양하고 주문하면 따뜻하고 감성적이게 나와서 좋아요 !!! 이야기 나누기도 좋고 시원하고 아주 쵝오입니다,,,! 하 정말 조하요 천국〰️🤍', 34, 3, 'GOOD', SYSTIMESTAMP);
