INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '별이빛나는밤식빵, 오늘밤보름달, 크로와상 샌드위치, 베베슈페너, 아인슈페너를 먹었습니다. 별이빛나는밤식빵은 색감을 잘 뽑아내어 이뻤고, 촉촉한 식감과 달콤하고 고소한 밤이 많이 들어가 있어서 맛있게 먹을 수 있었습니다. 오늘밤보름달은 팥앙금, 완두앙금, 딸기잼, 견과류, 우유버터크림이 묵직하게 들어가 식사 대용으로도 좋았고 커피, 우유와 곁들여 먹기 좋습니다. 크로와상 샌드위치는 신선한 채소와 햄 그리고 치즈가 많이 들어가 다이어트 음식으로도 좋아보였습니다. 베베슈페너와 아인슈페너는 위에 고소하고 달콤한 수제 크림이 올라가 완벅한 디저트 음료였습니다. 분위기는 아늑하였고, 2층으로 이루어져 가족, 단체, 연인 데이트에 방문하기 좋았고, 빵이 이쁘고 맛있어서 만족도가 높아 다음에 또 오고싶습니다.', 20, 0, 'GOOD', SYSTIMESTAMP);
