INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '제 연남동 최애 공간 베어스덴베이커리 ㅎㅎ 여기 빵 실패없이 모두 맛있고, 특히 별이빛나는밤식빵은 진짜 꼭드셔보세요 ^^! 이 집 시그니처 빵이에요 매장 분위기가 일단 너무 좋습니다. 에어컨도 빵빵하게 나와서 시원해서 너무 좋고, 사장님도 정말 친절하세요. 그리고 여기는 별도의 2층 공간도 있는데 여기는 6인이상 단체석도 있어서 가족끼리 방문해도 너무 좋을 것 같아요 연남동에서 제일 맛있는 빵집 베어스덴베이커리 강추드립니다!', 70, 16, 'GOOD', SYSTIMESTAMP);
