INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '귀여운 분위기와 친절한 사장님들이 있던곳이엥요 빵 종류도 많고 이색적인 빵들듀 있어서 사진으로 담기 좋았습니다. 맛은 기본! 맛있었어용 😆 저희가 주문한빵은 밤식빵이였습니당', 30, 0, 'GOOD', SYSTIMESTAMP);
