INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '허니바게트 진짜 맛있어요! 하나 꼭 담아보세요🥖 그리고 아아도 쓴맛 탄맛 없이 고소한 제 취향이었고 레몬에이드는 그냥 시럽만 대충 넣고 만든 음료와는 차원히 다릅니다,, 💛🍋 제가 먹은 레모네이드 중에 갑', 37, 1, 'GOOD', SYSTIMESTAMP);
