INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '빵이 너무 맛있어요~😋 허니바게트 좋아해요~😁 맛있는 빵 종류가 많고 분위기도 좋아서 연남동에서 친구랑 종종 가고 있어요~ 또 맛난 빵 먹으러 갈게요🐻🤎', 36, 8, 'GOOD', SYSTIMESTAMP);
