INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '빵이 쫀득하고 다 맛있어요🥹🥹 초승달 달달한 에그타르트를 빵에다 먹는 느낌.. 커피랑 먹기 너무 좋아요 ㅠㅠ😍😍 좀 늦게 와서 인기빵은 많이 없었는데 다른 빵도 다 맛있어효… 그리고 밀크티 향이 너무 좋아요 ㅠㅠ 밀크티 애호가로서 인정하는 맛입니다..🥵', 48, 5, 'GOOD', SYSTIMESTAMP);
