INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '일단 제가 곰돌이를 디게 좋아하는데 곰으로 다 꾸먀져 있어서 너무 귀여웠습니다••♡ 곰돌이 크로와상? 같은 것도 먹고 싶었늗데 다른 디저트들도 너무 맛있어 보여서 고르기 힘들었습니다🥺🫶🏻', 10, 3, 'GOOD', SYSTIMESTAMP);
