INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '8년전부터 알았던 곳인데 여전히 맛있네요!! 독창적인 메뉴들이 많고 식빵 종류도 넘나 맛있고 페스추리 종류도 다 맛있어요~~ 초코곰돌돌 초코러버들께 추천👍 별이빛나는밤식빵 독보적인 비주얼👍 크로와상 샌드위치 브런치로 넘나 추천하고요👍 베베슈페너와 함께 드시면 더욱 든든한! ☕️ 커피도 맛난 곳입니다. 연남 데이트코스로도 추천해용🫶🤍', 12, 0, 'GOOD', SYSTIMESTAMP);
