INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '엄청 힙해 보이는(=제빵과 멀어보이는) 분이 계시길래 리뷰에 낚였나 생각했지만 기왕 갔으니 시그니처 식빵 사봤어요. 알고 갔는데도 막상 고르려니 참 손이 안가는 색이 더라구요 ㅋㅋㅋㅋㅋ 진짜 도전정신으로 사 본 건데 의외로 맛이 있데요?? 식감도 좋고 이상한 맛도 전혀 없구요 🤣 인공색소같은 맛이 날까 했거든요. 세상은 넓고 빵의 세계도 다양허네요. 편견깨고 도전해보길 잘 했어요.', 75, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '홍대 비어스덴에서 맛있는 빵과커피를 먹었어요!! 밤식빵이 정막특이하고 맛있어요 2층에가보니 반고흐 별이빛나는 밤 밤식빵입니당. 샌드위치도 야채랑 치즈햄이 듬뿍 들어있어서 추천드립니다. 홍대 베이커리 맛집 추천드립니당!!', 66, 15, 'GOOD', SYSTIMESTAMP);
