INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '커피도 고소하니 맛잇고 특별한 빵 지인에게 선물하려고 방문햇는데 인테리어도 차분하고 깔끔하니 처음 방문햇는데 좋아요 직원분도 친절하십니다 빵 종류도 많아서 겨우 참앗어요 !! 평일 주중 시간보내기 좋은 곳이에요 굿', 12, 0, 'GOOD', SYSTIMESTAMP);
