INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '만나서 가볍게 먹기 위해서 왔는데 귀여운 메뉴들이 꽤 많고 음료도다양해서 고르기 어려웠어요ㅠ 오래 고민한 만큼 너무 맛있어서 또 오자고 얘기했네요:) 매장도 넓어서 앉아서 먹기도 좋고 음악도 나와서 얘기하는데도 불편함없어서 좋아요!', 46, 0, 'GOOD', SYSTIMESTAMP);
