INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '더운 여름에 가족들과 돌아다니다 발견한 아늑한 분위기가 독보이는 카페 딸기 밀크티라는 신기한 조합의 메뉴를 시켜봤는데 진짜 신의 한수였음 기본적으로 딸기 우유 맛에서 끝맛에서 홍차의 향이 치고 올라가 너무 맛있어서 모두에게 강추함 빵은 시그니쳐 메뉴가 아니라 무난한 허니 브레드를 시켰는데 너무 맛있어서 시그니쳐 메뉴는 얼마나 맛있을까 궁궁해서 후회될 정도의 맛임 추천', 18, 1, 'GOOD', SYSTIMESTAMP);
