INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '워낙 유명한 곳이라 방문했는데 빵 종류도 많고 쾌적해서 다음엔 매장에서 커피랑 먹어봐야겠어요 !!! 맘모스 빵은 배신 안 하니까 !!! 배고플 때 와서 이것저것 다 먹어보겠습니닿ㅎㅎㅎ !!!!!', 33, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '빵이 맛있다는 소문듣고 아이랑 오픈런했어요!!! 종류도 다양하고 음료와 커피도 다양했어요 특히 아이도 좋아하고 저도 너무 맛있게 먹었습니다!! 자주 올게요♡', 62, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '히히 카페 넓어요 빵도 많고 다양해요 잠깐 쉬다 가기 좋아요 점심 못 먹고 카페에서 만나기에 딱 좋아요 샌드위치 때깔 보세요!! 여기 콘센트도 있어요!!!', 14, 10, 'GOOD', SYSTIMESTAMP);
