INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '빵순이라 여러 곳을 방문해봤는데 이곳에서만 먹어볼 수 있는 개성적인 빵들이 있는 곳이예요! 종류가 많아서 고르는 데 고민이 되긴 합니다만 :) 특히 이 치즈 듬뿍 들어간 빅뱅빵 너무 맛있어요! 치즈의 짠맛과,, 빵의 달달한 맛이 너무 잘 어울려요! 제가 진한 커피 좋아해서 얼음 적게 부탁해서 커피 양이 적어보이는데; 커피도 빵과 잘 어울리고 맛있어요! 고흐의 ''별이 빛나는 밤''에를 컨셉으로 한 빵도 나중에 먹어보고 싶어요♡ 아늑하고 귀여운 인테리어에서 편안히 먹을 수 있는 곳 입니다 😀', 23, 0, 'GOOD', SYSTIMESTAMP);
