INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '보름달빵 맛도리입니다! 맘모스 업그레이드 버전같아요! 크림빵도 크림이 한가득이어서 크림 좋아하시는 분들은 너무 좋아하실 것 같아요! 분위기도 아늑해서 좋으니 연인과 함께 데이트 하시면 좋을 것 같슴다!', 33, 7, 'GOOD', SYSTIMESTAMP);
