INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '맛집 추천 받아 방문했어요. 늦은 시간 방문해서 빵이 좀 비어있었지만 선택한 빵들 모두 맛있게 먹었습니다~ 크림 잘 안먹던 아이도 크림빵 혼자 다 먹었어요. 빵 이름도 독특하니 센스가 철철 넘치는 곳이에요^^b 시그니처 베베슈페너 또한 자극적이지 않고 여기서만 맛볼 수 있는 특별한 맛이였어요~ 다음번엔 좀 이르게 방문해서 오늘 비워져 있던 빵들과 음료를 먹어봐야 할 거 같아요^^', 22, 1, 'GOOD', SYSTIMESTAMP);
