INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '홍대입구역 근처 빵집을 찾다가 베어스덴베이커리를 발견하게 되었어요!😝독특한 색감의 빵이 눈에 띄었는데요!🌈 저는 치즈 빅뱅이랑 오늘밤초승달을 구매했어요~ 어쩌다보니 치즈 들어있는 빵만 샀네요🧀?ㅋㅋ 집에 와서 먹기 좋은 크기로 잘라서 냉동보관하고 에어프라이어 돌려서 먹었어요~ 이렇게 먹으니 치즈가 쫀득 꾸덕하니 맛있더라구욤:) 적당한 치즈를 먹고싶다면 치즈빅뱅🌪, 넘치는 치즈를 먹고싶다면 오늘밤초승달🌛 빵을 추천드릴게요! 치즈 빵 먹고 싶을때 베어스덴베이커리 방문해 보세요💛🤍', 38, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '연남동와서 어디갈까 검색하다가 후기가 좋아서 왔는데 역시 후회 없습니다! 빵도 맛있고 음료도 맛있어요!ㅠㅠ 치즈빅뱅은 체다치즈가 양이 많아서 느끼할 수도 있지만 아메리카노로 쏴악 내려주면 기가막힌 맛이에요 짭조름한거 좋아하시는분들은 진짜 좋아할만한 맛!! 베베슈페너도 맛있고 뺑스위스도 맛나게 먹었습니다! 재방문 의사있고 집만 가까웠으면 여러번 배달시켜먹었을 것 같아요,,♡♥', 93, 20, 'GOOD', SYSTIMESTAMP);
