INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '초승달빵에 치즈 커스터드크림이 가득 들었어요 ㅎㅎ 크림빵도 제가 좋아하는 쑥크림 흑임자크림 우유크림 다 있어서 종류별로 다 있어서 좋았어요 🥰 크림이 왕왕 많이 들어서 넘 좋네요 ㅠㅠㅠㅠ', 97, 19, 'GOOD', SYSTIMESTAMP);
