INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '베이커리가 잘 갖춰진 카페를 찾아 여기로 왔어요. 다른 시그니처 빵도 있지만 어른들도 좋아하실만한 맘모스빵이 있어 잘 나누어먹었네요ㅋㅋ 아침 대용으로 먹을만한 치아바타나 식빵도 많이 있어 사갑니다 ㅋㅋ', 14, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '연남동 빵 맛집 찾다가 너무 맛있어 보여서 들어왔는데, 빵 종류가 다양해서 좋았어요!! 먹고 싶은 거 몇 개만 고르는 것도 힘들더라고요🥹 대표메뉴인 별 밤식빵은 늦게 가면 품절이니까 꼭 일찍 방문하세용.. 음료 메뉴도 있고 먹고 갈 수도 있는데, 내부도 아기자기하고 귀여워서 다음에는 카페 이용도 하려고요! ❤️', 27, 10, 'GOOD', SYSTIMESTAMP);
