INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '빵 종류가 너무 많아서 고르기 힘들었어요 ㅋㅋㅋㅋ 별으 빛나는 고소한 밤 식빵이랑 크림 가득한 내가 젖소 ㅠㅠ 크로와상 샌드위치는 식사 대용으로 딱이에요 ! 오늘밤 초승달 제 원픽입니다 !! 달콤한 카스타드 너무 맛있어용 ❣️ 귀어운 베베슈페너까지 ㅎㅎ 당일 생산한 신선한 빵이라 너무 맛있어요 😍', 46, 10, 'GOOD', SYSTIMESTAMP);
