INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '베베슈페너 맛있는데 너무 기여워여😆 ㅎㅎㅎ 타르트도 맛있구 카페 분위기가 아늑하고 편안해서 기분이 좋아요💛 근처 올때 꼭 들려야겠어요!!!', 39, 2, 'GOOD', SYSTIMESTAMP);
