INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '좀 늦은 시간에 와서 원하는 빵은 없었지만 대체적으로 빵이 다 가성비가 좋아요! 오실때 참고하시면 좋을 것 같습니다. 그래서 빵 대신 초코라떼 시켰는데 달달하니 맛있었어요 사장님도 친절하시구 넘 좋습니다!!', 27, 10, 'GOOD', SYSTIMESTAMP);
