INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '빵 종류가 많고 내부가 쾌적해요! 차분한 분위기여서 둘이 이야기하기 좋았어요. 혼자 카공하기도 좋을 것 같아요~!! 그리고 피스타치오 빵 달콤고소하고 넘 맛있어서 다음에도 방문해서 먹고 싶어요! 좋은 공간 감사합니다👍🏻👍🏻👍🏻', 37, 0, 'GOOD', SYSTIMESTAMP);
