INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '연남동 카페 베어스덴베이커리 너무 좋았어요... 커피는 곡물두유 들어간 베베슈페너 진짜진짜 너무 강추하고 크로와상 샌드위치랑 오늘밤보름달, 뺑오쇼콜라 진짜 퀄리티 높은 맛이라 꼭 드셔보세요ㅜㅜ 매장 잔잔하고 차분한 분위기라 데이트하기 좋았고 사장님 진짜진짜진짜 친절하셔서 재방문 하고 싶습니다🥹', 22, 6, 'GOOD', SYSTIMESTAMP);
