INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '일단 빵이 맛있네요. 초코크림도 달아서 맛있어서 소라빵 추천합니다. 내부도 넓고 깔끔하고 좋습니다. 데이트로 오면 좋을 것 같습니다.', 67, 14, 'GOOD', SYSTIMESTAMP);
