INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '별이빛나는밤식빵이랑 빅뱅치즈식빵 주문했는데 진짜 너무 화려하고 예뻐요!!!!!!!! 맛은 말모 ㅠ.ㅠ 치아바타도 클래식입니다!!! 여기 너무 추천이에여!!', 16, 2, 'GOOD', SYSTIMESTAMP);
