INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '에그타르트가 너무 맛있어요!! 매장이 2층까지 있어서 여러명에서 와서 앉아있기 좋고 매장 안이 청결해서 좋았어요! 사장님도 넘 친절하셔요~ 🐹😖😖😖😖🐹', 8, 6, 'GOOD', SYSTIMESTAMP);
