INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '밤식빵은 다 떨어져서 못먹었지만-! 치즈가 가득한 빅뱅 픽!! 치즈 좋아하는 저에겐 넘 맛있어요~~!~!! 크림빵도 크림 진짜 맛있어요ㅎㅋㅋㅋ❤️ 배부를까봐 하나만 먹으려했는데 둘 다 주문해보길 다행이네욧ㅎㅎ😆😋😋', 124, 22, 'GOOD', SYSTIMESTAMP);
