INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '점심을 애매하게 먹고 홍대 볼일 있어 오게 됬는데 근처 가까운 곳으로 걷다가 우연히 들어왔어요 근데 빵 너무 맛있고 추가로 허니바게트도 주문 해버렸어용 빵 맛집 🥖🍞🥨', 29, 1, 'GOOD', SYSTIMESTAMP);
