INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '빵지순례🫶 경기도민을 서울까지 오게하는 빵맛집이에요,, 멀어서 자주 못오는데 여기 빵집만큼 맛있는 빵이 없어서 주기적으로 빵사갑니당🤣', 68, 11, 'GOOD', SYSTIMESTAMP);
