INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '그릇들이 너무 귀엽고 시그니처 커피 너무 맛나요 >< 두유맛이 넘 고소해요 빵도 종류가 많고 제 취향 빵이 많아서 고르는데 고민됐어요. 너무 맛있게 먹었습니당💛😘 매장 안 분위기도 아늑하고 쾌적해요. 냉방도 잘 되어있습니당~', 8, 9, 'GOOD', SYSTIMESTAMP);
