INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '언제나 맛있는 베어스덴 빵^_____^ 오늘 해볕이 넘 강렬해서 쉴 겸해서 왔는데 번잡하지않고 고요한 이 느낌, 넘 좋습니다^^ 잘 쉬다 갈께요!^^', 50, 2, 'GOOD', SYSTIMESTAMP);
