INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '혼자 시간 때울 겸 점심 먹을 겸 빵집 찾다가 비주얼 최강인 빵집을 발견해서 방문했어요. 치즈 광인이라 치즈빅뱅 식빵이랑 치즈케이크? 맛나는 빵 주문하고 아메리카노랑 먹었는데 .. 하 너무너무 맛있네요 녹진하고 꾸덕한 치즈의 맛이 저의 입안에 축복을 주었습니다 .. 편안한 분위기에 가성비와 막 좋은 빵 맛집 베이스덴베이커리 추천합니다잉 ☺️☺️', 88, 16, 'GOOD', SYSTIMESTAMP);
