INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '매장내부에 앉을 자리도 많고 빵도 너무 맛있는 베이커리 카페에요^^ 별이 빛나는 밤식빵은 부드럽고 쫀득쫀득한 빵에 달달한 밤이 아주 잘 어울리는 식빵이에요. 허니바게트와 오늘밤 보름달은 테이크 아웃 했는데 벌써 너무 기대되요~^^', 0, 10, 'GOOD', SYSTIMESTAMP);
