INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '바나나푸딩 파는곳이 많이 없는데 있어서 좋아요!!위에 곰돌이 쿠키가 매우매우 귀여우네요. 시원하고 쾌적하니 쉬어가기 좋습니다!!', 9, 3, 'GOOD', SYSTIMESTAMP);
