INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '크로와상 샌드위치 겉은 바삭 속은 촉촉한 크로와상에 신선한 양상추, 짭조름한 햄,치즈, 달달소스가 들어가서 찰떡 궁합 크로와상 샌드위치에요^^ 어니언 크림치즈 겉은 바삭 고소하고 꾸떡한 양파 크림치즈가 들어가서 중독적인 빵이에요. 치즈빅뱅 : 식빵부분은 담백하지만 속에 달달하면서 부드러운 치즈가 듬뿍들어가 있고 빵사이사이 콕콕 박힌 치즈가 매력적인 식빵이었습니다. 명란감자페이스트 : 겉은 바삭바삭 페스츄리에 속에 부드러운 감자, 짭조름한 명란과 톡톡 터지는 옥수수가 매력적인 빵 아이스 아메리카노 : 산미 없고 고소한 맛에 아이스 아메리카노여서 빵들과 잘 어울렸어요. 베베슈페너 : 부드럽고 달달한 크림에 고소하 커피가 아주 잘어울리는 슈페너에요^^', 0, 2, 'GOOD', SYSTIMESTAMP);
