INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '빵을 너무 좋아하는 빵순이라 밥먹고 디저트먹으러 달려왔어요! 커피랑 같이 먹는 크림빵도 선물로 산 빵도 너무 맛있어요! 커피는 빵이랑 참 잘어울려요! 빵 사러 또 올게요~', 3, 0, 'GOOD', SYSTIMESTAMP);
