INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '샌드위치를 정말 좋아해서 무작정 샌드위치를 먹고자 검색해서 가까운 곳으로 갔던건데 럭키였던거죠... 빠작한 치아바타 취향임에도 빵이 고소하고 쫄깃해서 맛있었고 신선하고 기본인데 정말 맛있는... 그게 더 어려운거 아시죠? 먹는데 비닐장갑 하나 주시는 센스도 좋았습니다 홍대 샌드위치는 베어스...', 0, 8, 'GOOD', SYSTIMESTAMP);
