INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '브런치로 너무 좋았던 연남동 빵 맛집에 다녀왔습니다! 리뷰쓰면서 다시 침고이네요ㅠㅠㅠ 특별한 밤식빵도 완전 꿀맛에 비쥬얼 최고봉이었어요>_< 맛있게 잘먹었습니다♡', 33, 4, 'GOOD', SYSTIMESTAMP);
