INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '별이 빛나는 밤 식빵이 유명하다고 해서 홍대 온김에 들렀어요 :) 빵도 빵이지만, 분위기도 너무 좋아서 다음에 또 들를라구요!! 데이트 하기 딱입니다.', 112, 25, 'GOOD', SYSTIMESTAMP);
