INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '지난번에 먹고 맛있어서 집에갈때 치즈식빵과 밤식빵을 사서 모임에 가져갔는데 치즈식빵은 아이들이 너무 좋아해서 사진도 못찍을만큼 순식간에 없어졌네요😄 엄마들 입맛에는 밤식빵이 담백하니 좋아했어요. 색깔이 반고흐의 ''별이 빛나는 밤''이 떠오른다며 인기만점이였어요.', 41, 9, 'GOOD', SYSTIMESTAMP);
