INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '연남동 빵집 베어스덴 베이커리! 귀여운 곰돌이들이 반겨 주는 곰 굴입니당 ㅋㅋㅋㅋ 🐻🐻 데이트 분위기로 완전 제격인 아늑함에 빵맛도 보장된 곳 ❤️ 시그니처인 별이 빛나는 밤식빵은 보기만 예쁜 게 아니라 빵도 촉촉하고 밤도 많이 들어 있어서 맛도 좋아요 🤤 전반적으로 크림이나 재료가 알차서 든든하구 커피도 맛있어요 🫶', 41, 9, 'GOOD', SYSTIMESTAMP);
