INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '고흐식빵사러 들렀는데 너무 맛있어보이는 빵이 많네요 🥰❤️ 너무친절하시고 가게도 깨끗하고 커피도 맛있어서 다음에는 여러명이랑 와서 이것저것 다 시켜먹을 예정입니다 ㅎㅎㅎ', 64, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '친척들이랑 아이들이랑 홍대 구경왔다가 10명이 글어갈 카페를 찾아보다가.. 다들 지친 발걸음으로 와봤는데 2층 전체를 프라이빗하게 이용할 수 있어서 좋았어요! 심지어 빵 플레이팅도 너무 이쁘고 카패라떼도 너무 맛있어요! 아이들도 먹을 수 있는 음료가 있어서 좋았고 무엇보다 친절하셔서 감동이었습니다! 연남동 올때 또 올거 같아요~~', 21, 3, 'GOOD', SYSTIMESTAMP);
