INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '빵 맛집이라고 해서 와본 베어스덴 베리커리!! 날 좋은 일요일이라 웨이팅 있진 않을까 걱정했는데, 다행이 자리는 넉넉했어요!! 빵 종류가 가게 크기에 비해 많은 편이었는데, 그 중에서 곰스타치오를 골랐어요. 피스타치오 좋아하시는 분들은 추천이구요, 엄청 진한 크림은 아니지만 피스타피오 맛 버터 크림이 들어가서 먹물빵이랑 조합이 너무 좋았답니다! 먹물빵 단독으로만 먹으면 심심할 듯 해요~ 다음엔 바게트류도 먹어보고 싶습니다 :)', 129, 23, 'GOOD', SYSTIMESTAMP);
