INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '맛있는 빵 먹을 곳 찾다가 발견해서 들어왔는데 기대 이상으로 너무 맛있어요!! 커피도 너무 맛있어요!! 다음에 홍대올 때 또 들릴 것 같아요!!~~', 0, 1, 'GOOD', SYSTIMESTAMP);
