INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '근처 살 때 다니던 가게인데 오랜만에 오니까 많이 번창하셨네요!!! 괜히 내가 다 기쁜.. 맨날 식빵만 사먹다가 크림빵은 처음 먹어보는데 너무 맛있습니다. 쑥라떼랑 팥빵을 같이 먹는 느낌!', 68, 16, 'GOOD', SYSTIMESTAMP);
