INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '빵도 맛있고 커피도 맛있었습니다. 편하게 쉬기 좋고 역과의 접근성도 좋아 잠시 쉴곳찾다 찾았는데 너무 좋네요!!! 다음에도 또 오고 싶습니다!!', 29, 5, 'GOOD', SYSTIMESTAMP);
