INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '분위기도 아늑하고 따뜻한데 개성있고 다양한 빵들이 많아서 좋아하는 빵집이에요♡ 별이빛나는 밤식빵이 최애긴 한데 다른빵들도 먹어보고싶어 도전했어요 ㅋㅋㅋ 여기 샌드위치도 엄청 맛나더라고요><!!', 46, 8, 'GOOD', SYSTIMESTAMP);
