INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '배달로 많이 시켜먹었는데 처음으로 오프라인매장 왔네요 :) 크림빵 맛집인데 레몬타르트 도전해봤어요! 근데 상큼하게 맛있네요!!! 다음에 또 매장으로 오려구요!', 46, 3, 'GOOD', SYSTIMESTAMP);
