INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '빵순이라면 꼭 와봐야 할 맛집입니다! 소문 듣고 왔는데 정말 빵이 촉촉하고 맛있네요🥹 특히 별이빛나는밤 식빵 진짜 비주얼만큼 맛있어요!!!', 4, 0, 'GOOD', SYSTIMESTAMP);
