INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '밤 식빵 먹으러 한 번씩 오는 곳입니다!! 밤식빵 진짜 너무너므 맛있어요...! 빵 종류가 많아서 밤식빵 사면서 하나씩 도전해 보겠습니다!!💖', 40, 6, 'GOOD', SYSTIMESTAMP);
