INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '예쁜식빵과 다른 여러가지 빵들이 있어 여행 중 찾은 곳! 달달하고 보들보들한 밤식빵, 눈으로 담고 입으로 느끼네요~ 함께 먹은 에그타르트도 맛있어요^^ 선물용으로 굿~ 커피도 고소하니 맛있네요^^ 홍대에 오게되면 또 방문하고 싶네요!', 27, 4, 'GOOD', SYSTIMESTAMP);
