INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '빵잘알 친구가 여기 맘모스가 그렇게 맛있다구 엄청 추천해서 와봤어요..!! 허니바게트가 최애였는데 이제 올때마다 둘다 사가려구요 역시 베어스덴 .... 늘 최고의 맛이에요🥹🥹', 23, 2, 'GOOD', SYSTIMESTAMP);
