INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '빵 먹으러 왔다가 커피도 맛있어서 놀랐어요 ㅎㅎ 산미는 적고 고소한 맛이 착 감겨서 좋았어요 ㅎㅎ 에햄샌드위치<에그햄 샌드위치를 이렇게 귀엽게ㅠㅠ 안 시킬 수 없었는데 귀여운 곰돌이 접시에 주셔서 행복하네요 ㅎㅎ', 24, 7, 'GOOD', SYSTIMESTAMP);
