INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '매장 분위기도 넘 좋고 빵 맛있고 커피도 맛있어요~ 빵들이 다 맛있어보여서 고르기 넘힘들었어요~ 사장님은 친절하시구 빵도 데워주셔서 따듯하게 넘 맛있게 먹고가요~ 크림빵도 안에 크림가득이라 고숩달달하니 맛있어용', 50, 10, 'GOOD', SYSTIMESTAMP);
