INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '오늘도 베어스덴베이커이에서 빵쇼핑 잔뜩했어요!! 치즈빅뱅은 역시나 왕맛탱!!! 내가참치? 진심 이것도 짱맛!! 남편 픽은 바질식빵!!', 21, 8, 'GOOD', SYSTIMESTAMP);
