INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '갈릭바게트 시켰는데 너무 고소하고 바삭하고 달달합니다 💛 완전 최고 ㅎ 우유까지 메뉴에 있어서 딱 빵집카페 느낌 물씬나요🔥 완벽합니다 추천🙂', 44, 2, 'GOOD', SYSTIMESTAMP);
