INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '공항가기전에 샌드위치와 커피 마시려고 잠시 들렸는데 샌드위치가 신선하고 너무 맛있었어요! 매장도 넓고 시원하고 좋았습니다☺️ 커피는 고소하고 멋있었어요!', 130, 22, 'GOOD', SYSTIMESTAMP);
