INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '저장만 해두다가 처음 와봤는데 빵 종류도 다양하고 가성비있는 것 같네요 :) 분위기도 차분해서 완전 마음에 쏙 들었습니다 ! 다음에 또 방문할게요~', 45, 8, 'GOOD', SYSTIMESTAMP);
