INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '오늘 처음 방문했는데 매장 분위기도 차분하고 빵도 너무 맛있게 먹었어요 !! 리뷰에 있는 갈릭바게트 후기를 보고 바로 사먹었는데 속이 촉촉하고 겉은 쫄깃해서 맛있게 해치워버렸습니다 ㅎㅅㅎ 나머지 소세지 페이스트리도 기대했던 맛이라 오히려 좋았어요 !! 너무 배부르네요,, 🫠 조용한곳 선호하시고 빵을 좋아하시는 분들이게 완전 강추 합니당 !!', 12, 10, 'GOOD', SYSTIMESTAMP);
