INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '빵의 너무 예쁘고 맛있어서 자주 방문하는 가게에요. 특히 별이 빛나는 밤식빵은 예술작품 같기도 하고 밤이 듬뿍 들어서 제가 좋아하는 빵이에요. 샌드위치는 치아바타랑 크로와상 2가지 빵 중에 고를 수 있다는 점이 취향껏 먹을 수 있다는 느낌이 들어서 좋았어요!', 23, 3, 'GOOD', SYSTIMESTAMP);
