INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '연남 빵집은 여기 아니겠습니까!!! 무조건 강추!!! 지금 리뷰 이벤트 기간이라서 맛있는 빵도 사고 맛있는 빵도 얻어가요!!!최고에오!!!', 56, 15, 'GOOD', SYSTIMESTAMP);
