INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '디저트 빵같은거랑 커피를 좋아하는 스타일인데 홍대 가다가 눈에 띄어서 와봤는데 맛있더라구요!! 마늘 바게트도 좋아하는데 따뜻하게 데워주시고 맛있었어요~ 다음에는 다른 빵 종류와 샌드위치, 그리고 스프도 좋아하는데 먹어볼게요!', 43, 1, 'GOOD', SYSTIMESTAMP);
