INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '연남에서 유명한 빵집이어서 저장해놓고 있다가 방문했어요! 다 맛있어보여서 잔뜩 포장해서 쟁였어요 ㅎㅎ 예뻐서 아기도 주면 넘 좋아할 것 같아요 ㅎㅎ', 99, 24, 'GOOD', SYSTIMESTAMP);
