INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '빵종류가 많고 인테리어가 이뻐요~! 사장님도 친절하십니다~!! 별이빛나는 밤식빵 먹으러 왔지만 품절되어 다른빵을 먹었지만 맛나요~!❤️ 홍대 베이커리 빵집으로 추천드려요!', 35, 6, 'GOOD', SYSTIMESTAMP);
