INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '입구부터 기분이 좋아지네요. 분위기가 밝고 상쾌하네요. 직원분도 친절해서 좋은데 음료도 깔끔해요. 음익도 매장 분위기랑 질맞네요', 39, 2, 'GOOD', SYSTIMESTAMP);
