INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '빵이 전체적으로 촉촉하고 신선해서 한 입 먹자마자 감탄했어요. 수체레몬청을 넣은 레몬티도 정말 맛잇엇고 시그니처음료 크림이 부드럽고 달달해서 추천해요~! 빵과도 잘어울렸어요. ☕️ 조용하고 아늑한 분위기까지 완벽한 곳, 재방문 의사 100%! ❤️ 이렇게 작성하면 어떨까? 원하는 분위기나 강조하고 싶은 부분 있으면 말해줘~ 😊', 19, 7, 'GOOD', SYSTIMESTAMP);
