INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '전날 지나가다 보고 빵들이 너무 맛있게 생겨서 아침에 커피에 빵 한조각 하려고 바로 방문했어요! 빵 종류가 생각보다 정~말 많았고, 메뉴 이름이 곰돌이 관련되어서 너무 귀여웠어요! 바삭한 빵에 초코크림과 곰돌이가 박혀있는 초코곰돌돌이랑 녹차라떼, 카페라떼 주문했는데, 추운 날씨에 커피 따뜻하게 맛있게 먹었어요! 초코곰돌돌 진짜 바삭하고 초코크림 진하고 맛있어요! 빼꼼 보이는 곰돌이 쿠키가 너무 귀여워요💖🐻💖 빵 종류가 다양해서 다른 빵도 먹어보고 싶어요😆', 45, 8, 'GOOD', SYSTIMESTAMP);
