INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '예전부터 저장해둔곳인데 근처 볼일있어서 왔다가 들어왔어요! 맛있어보이는 빵 너무 많았고, 피스타치오 버터 넣어준다 그래서 시킨 곰스타치오!! 진짜 맛있어요!! 아메리카노랑 완전 어울림!!!!!!!!', 46, 0, 'GOOD', SYSTIMESTAMP);
