INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '평일낮에 왔는데 조용하고 빵 진짜 맛있어요! 치아바타 샌드위치 먹고 싶었는데 품절이라 크루아상 먹었는데 짱 맛 있 어요 ㅜ!! 허니바게트도 꿀이 생각보다 많이 들어있어서 짱맛 짱달달구리 >..< 다음에 밤빵이랑 치아바타 먹으러 또 와야겠숨다 추천 💛', 5, 7, 'GOOD', SYSTIMESTAMP);
