INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '빵 종류도 다양하고 크림이 맛있어서 자주 사다 먹어요! 연남에서 여기만큼 크림빵 잘 하는 집 없는 것 같아요,,✨모든 맛이 다 저마다의 매력이 있으니 이것저것 시도해 보시길 추천합니다☺️', 13, 0, 'GOOD', SYSTIMESTAMP);
