INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '자주오진 못하지만 올때마다 매장 분위기가 (더 좋게)바뀌어 있어서 넘 좋아요! 제 인생 맘모스인데 보통 생크림이 들어가는데 베어스덴은 크림치즈가 묵직하게 들어가서 고급스러운 맛이나요! 반개도 판매하니 꼭 드셨음 좋겠어요~ 오랜만에와서 예전과 맛이 다를까 걱정되서 포장은 아직 안했는데 진열된거 다 가져가고 싶을만큼 여전히 맛있어요👍', 40, 8, 'GOOD', SYSTIMESTAMP);
