INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '크림이 폭발할정도로 많이 들어있고 우유크림이 가득인데 느끼하지도 않아요! 많이 달지도 않아서 진짜 쑥쑥 들어가네요~>_< 예전에도 한번 온 적있는데 카페가 넓어져서 먹고 가기도 좋아졌어요♡ 다음엔 샌드위치를 먹어야겠어요!', 83, 14, 'GOOD', SYSTIMESTAMP);
