INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '일주일에 4일은 매번 들러서 치아바타샌드위치나 크로와상샌드위치 포장해가는데 둘 다 너무 맛있어요 치아바타 엄청 촉촉해요.. 가끔 사람 많을때가면 치아바타는 품절이더라구요 ㅠ ㅠ 오늘도 역시 포장해왔습니다 💗', 44, 3, 'GOOD', SYSTIMESTAMP);
