INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '빵도 음료도 다 맛있는 베어스덴 🩷 애정하는 연남동 카페에용 오면 밀크티만 마시는 밀크티맛집!!!!! 23년도에 알게되어서 그때부터 연남동오면 무조건 베어스덴만 찾게되네요ㅋㅋ 갈릭바게트랑 에그타르트 진짜 맛있어요 굿굿 🩷', 16, 5, 'GOOD', SYSTIMESTAMP);
