INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '매번 배달로만 먹었는데 오늘 볼 일 보고 잠깐 들려서 구매했어요. 빵 역시 너무 맛있어요~~! 카페도 넓고 다음엔 카페에서 먹어봐야겠어요.', 101, 26, 'GOOD', SYSTIMESTAMP);
