INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '빵이 유명하다고 해서 식당웨이팅하는 동안에 방문했어요! 테이크아웃하러왔지만 매장이 넓고 아늑해서 먹고가도 너무 좋을거같아요~ 유명하다고 한 치즈빵들을 사봤는데 비주얼도 이쁘고 맛도 기똥차서 종종 방문하려고 합니다🩵 연남동 존맛빵지순례로 추천드려요❤️', 18, 9, 'GOOD', SYSTIMESTAMP);
