INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '치즈빅뱅 빵에 치즈가 엄청 많아서 맛있어요!! 괜히 인기 메뉴가 아니네요 ㅎㅎ 그냥내가젖소도 크림 완전 많이 들었고 빵 2개 다 촉촉해서 더 맛있어요!!! 다음에 또 와야겠어요 ~~ 추천드려요!', 38, 10, 'GOOD', SYSTIMESTAMP);
