INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '늦게 와서 별이 빛나는 밤 식빵 못 사서 아쉽지만 ㅜㅜㅜㅜ 다른 메뉴도 충분히 맛있어보여서 만족합니다 ㅎㅎ 분위기 좋고 시원해용', 66, 14, 'GOOD', SYSTIMESTAMP);
