INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '빵도 부드럽고 인테리어도 넘 좋아용!! 에그타르트랑 샌드위치도 맛있는거 팔아가지구 빵순이 오면 환영! 자리도 넉넉해서 좋아요~! 담에 또 오려구여!', 35, 8, 'GOOD', SYSTIMESTAMP);
