INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '빵 종류가 정말 다양하고 다 맛있어보여요! 이번에 먹은 오늘범 반달 이 빵 너무 맛있었어요!!👍🏻 가격 대비 너무 괜찮은 것 같아요 호두도 큼직하고 만족스러웠습니다 :) 그리고 친구랑 나눠 먹기 좋게 컷팅도 미리 해주시고 직원분들 센스 만점입니다! 음료도 맛있고 카페에서 나오는 노래도 좋아요ෆෆ', 28, 3, 'GOOD', SYSTIMESTAMP);
