INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '연남동빵맛집으로 찾아왔는데 클쓰분위기도 좋고 빵들도 다 느무 맛있네요!! 유니크한 식빵부테 에타,크로와상 다 존맛탱입니다ㅋㅋ #연남카페 #홍대카페 #베어스덴베이커리 #밤식빵맛집 #에그타르트맛집 #연남동베이커리카페', 19, 2, 'GOOD', SYSTIMESTAMP);
