INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '사진실력을 발휘못해서 아쉽 ... 역 근처 카페 우연히 발견한건데 메뉴보니 특이해서 와보고싶었어요 크루아상샌드위치 제가 진짜 좋아하는 스타일이라 먹어보고싶었는데 먹기 좀 힘들지만 .. 맛은 너무너무 맛있어요 존맛탱 ,, 그릇들도 곰돌이고 심지어 크루아상 그릇도 곰돌이더라구욬ㅋㅋㅋㅋㅋㅋ 너무 귀여워요 ...... 다음에 또 오고싶습니다', 22, 2, 'GOOD', SYSTIMESTAMP);
