INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '아침에 이야기 하면서 간단하게 먹을 수 있는곳 찾아 보가가 방문했어요  찾아본 사진처럼 매장도 넓고 깔끔하고  이야기 하기 좋은 분위기 입니다 빵 종류도 많고 사장님도 친절 하셔서 편안하게 시간 보내다가 왔어요 홍대에서 이야기 할만한 곳 찾는다면 "베이스던 베이커리" 추천해요', 73, 15, 'GOOD', SYSTIMESTAMP);
