INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '원래 빵 잘 안 먹는데 가끔 빵 땡기는 날 꼭 오는 베어스덴! 우선 귀여우니까 지구정복이에요. 접시도 곰돌이, 매장 지킴이도 곰돌이! 최애는 올리브 치아바타에 아아 입니다. 완전 강추! 에햄 샌드위치는 처음인데 엄청 든든해요! 굿!!', 36, 8, 'GOOD', SYSTIMESTAMP);
