INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '매장이 아늑하고 디저트류 빵이 아닌 치아바타 소금빵 등 종류가 있어서 애매하게 배가 고플 때 좋을 것 같아요. 올리브 치아바타 3,600원으로 연남동 물가대비 괜찮습니다. 다만 조금만 더 친절하게 응대해주시면 더 좋을 것 같습니다 알바비를 못받으셨다면 무죄입니다', 48, 10, NULL, SYSTIMESTAMP);
