INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '올리브 치아바타 먹었는데 빵이 되게 부드럽고 폭신폭신해요 ㅠㅠ 매일 자극적인 디저트류만 먹다가 이런 담백한 빵 먹으니까 힐링되는 기분입니다! 담백하고 깔끔한 빵 좋아하시면 추천해용', 13, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '맛있는 빵이 너무 많아서 뭘 사야할지 고민이 너무 되더라구요. 다음에는 식빵을 사봐야겠어요. 흑임자를 좋아해서 흑임자빵이랑 이름이 웃긴 참치 빵 샀는데 둘 다 맛있어요.. 브런치 먼저 먹고 빵 포장했는데 브런치에 나오는 빵도 맛있어서 참을 수 없었어요. 가게 이름에 걸맞게 곰돌이가 많아서 귀여워요..', 62, 15, NULL, SYSTIMESTAMP);
