INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '점심으로 먹으려고 사러 왔어용🤓 치즈빅뱅은 치즈 좋아하는 분이면 무조건 드세요ㅎㅎ 초승달이랑 명란감자도 존맛탱 맛있게 먹겠습니닷!!😆', 45, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '크리스마스에 방문했습니다! 트리랑 음료가 너무 귀여워서 덕분에 크리스마스 분위기 낭낭하게 잘즐겼습니다🎄😁 빵이 다 맛있네요 크림이 담백해서 술술 들어가요 집가는 길에 또 사가려고요! 담에 또 올게요💕', 28, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '접때도 왔는데 역시 빵들이 다 맛있고 매장도 여전히 포근하고 좋더라구요!! 새로운 빵들이 느무 맛있어서 담에 또 다른 빵 먹으러 오려구욧', 124, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '평소에 마늘빵을 워낙 좋아해서 마늘빵 맛집을 찾으러 다니는데 ㅎㅎ 여긴 진짜에요!! 마늘을 아낌없이 넣어주셨고 겉은 약간 바삭하고 안에는 마늘이 듬뿍들어 촉촉하고 맛있어요~! 커피랑 같이 먹으니 넘 맛있어서 순식간에 먹었어요. ㅎㅎ 크림빵으로 더 유명한 곳이지만 오셔서 마늘빵도 꼭 드세요!', 42, 4, 'GOOD', SYSTIMESTAMP);
