INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '제 최애 빵집인 베어스덴 베이커리에요 ㅎㅎ 몇년째 다니고 있습니다 최애는 마늘빵이구요 ㅎㅎ 더더 번창하시구 빵들 넘 맛있어요 ㅎㅎ', 57, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '페이스트리 빵 좋아하는데 크루와상이랑 소세지페이스트리 넘 맛있게 잘 먹었어요🤤 빵 종류도 다양하고 특히 밤식빵 너무 예뻐서 밤 좋아하는 부모님 드릴려고 포장했어요. 집에서 먹어봤는데 너무 맛있더라구요. 인기메뉴인 이유가 있음!! 리뷰이벤트로 받은 쑥쓰럽소 크림빵도 진짜대박 맛있어요😵🫨 매장에 인테리어도🎄 예쁘고 사장님도 친절하셔서 좋아요🥰 다음에 홍대 올 일 있으면 또 방문하고 싶어요👍👍', 90, 12, 'GOOD', SYSTIMESTAMP);
