INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '2번째 방문이에요! 맘모스빵 가성비도 좋고 안에 호두도 씹혀 진짜 추천!매장이 아늑하고 따뜻한 분위기여서 여행객에게 너무 추천드려요!', 62, 13, 'GOOD', SYSTIMESTAMP);
