INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '내가 사랑하는 베어스덴🫶 진짜 오랜만에 홍대 나왔는데 1ㅔ어스덴 안갈수가 없지요ㅠㅠ 내사랑 베어스덴! 오랜만에 베어스덴 빵 보니깐 넘나 행복해욤!!!!❤️ 추워도 홍대 자주 나와야 겟어욤🙂', 20, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '아이와 홍대 나들이에 방문해보았습니다. 아이는 귀여운 초코곰돌돌을 저는 오늘밤초승달을 선택했는데 둘다 달달하고 맛있습니다. 다음 방문때는 다른 종류의 빵도 먹어봐야겠어요.', 168, 38, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '빵이 하나같이 눈돌아가게 생겼어요😋😋 저는 갈릭브레드 먹었는데 넘 감칠&달달하니 맛있었습니다ㅎㅎ 연남동 오면 또 들를 것 같아요!', 15, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '홀 없이 2층에 자그마한 매장에서 테이크 아웃 판매만 하실때부터 이용했는데, 여전히 그 자리에 계시고 여전히 그때 먹었던 빵을 살 수 있는데다 확장까지 되어서 기쁜 동네주민 1인입니다 ㅎㅎ 특히 이 [별이 빛나는 밤] 빵과 [치즈 빅뱅]은 선물하면 다들 색감에 한번 놀라고 맛도 좋아서 두루두루 추천할만한 메뉴예요. 물론 다른 빵도 다 맛있지만 이렇게 아티스틱한 빵은 딴데서 또 보기 힘들다는 점에서 ㅎㅎ 강추합니다요!', 96, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '특이한 컨셉의 빵이 많아서 왔어요~ 크림빵에 크림이 가득해요!!! 늦게 와서 밤식빵이 없어서 다음에 밤식빵 사러 올게요~ 내부에 자리가 넉넉해요!!', 94, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '눈과 입 모두가 즐거워 지는 시간이었던 거 같습니다. 주문 후 빵을 받자마자 빵 비쥬얼에 첫 번째로 감탄하였고 빵 맛을 보자마자 두번째로 놀랐던 거 같습니다. 이렇게 이쁘고 맛있는 빵은 너무 오랜만에 본 거 같아요. 이미 카페에서 빵을 배불리 먹었지만 너무 맛있어서 크림빵을 더 사갔네요 ㅎㅎ 홍대를 오게 된다면 다시 방문해서 다른 빵들도 먹어볼 생각입니다. 아늑한 분위기를 좋아하시는 분들, 이색적인 디저트를 찾으시는 분들 에게 적극 추천 드립니다 🤗🤗', 75, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '여기 빵류도 맛잇는데 브런치세트가 찐인 것 같아요! 치즈가 살짝 들어간 스프도 고소하고 맛있고 크로와상 같은 경우에는 신선한 채소하고 재료가 잘 어울려서 맛있어요! 크로와상 먹고 아인슈페너 한잔 하면 완전 좋습니다!⭐️👍🤤', 99, 26, 'GOOD', SYSTIMESTAMP);
