INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '항상애용하는 빵집💛 오늘은 친구네 집들이 가서 맛있게 먹을 빵 사러왔어요~~ 누구나 좋아할 만한 맛이라 자신있게 사러왔습니다!', 53, 15, 'GOOD', SYSTIMESTAMP);
