INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '맘모스빵 맛집이래서 갔는데 가보니 다른 메뉴들도 맛있어보여서 샀어요☺️☺️ 곰스타치오랑 허니바게트 샀는데 허니바게트는 달고 바삭한 맛이 좋았고 곰스타치오는 크림이 진짜 맛있었어요. 맘모스빵은 단면부터가 뚱실하니 재료가 듬뿍 들어가서 한입먹으면 행복해치는 맛이니 꼭 드셔보세요💕', 6, 9, 'GOOD', SYSTIMESTAMP);
