INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '따듯하고 아늑한 카페에요 홍대입구역에서 가까워서 좋고 빵도 종류가 많아요 엄청 맛있고 양도 많아요! 조명도 예뻐서 사진도 잘 나오네요☺️', 90, 18, 'GOOD', SYSTIMESTAMP);
