INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '시그니처 빵을 먹고싶었는데 인기 품목이라 늦게오니 놓쳤어요 ㅠㅠ 일찍오세요~~ 2층에 테이블도 넓고 단체 방문하기 좋아요^^ 추천해요', 106, 22, NULL, SYSTIMESTAMP);
