INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '연남동 카페하면 베어스덴베이커리❣️ 쫄깃한 빵피속에 달달짭짤한 치즈크림 가득🤦🏻‍♀️ 안먹어본 사람은 몰라서 안먹는거예여.... 진챠 맛있다구용🥰 곧 나올 브런치메뉴도 먹으러 와야겠어용❤️‍🔥', 4, 8, 'GOOD', SYSTIMESTAMP);
