INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '아🤦🏻‍♀️ 진짜 브런치 맛있어요!!!! 에그베네딕트 수란 터뜨려서 치즈소스 듬뿍 묻혀 먹으니 촉촉해서 맛있고🤤 아보카도 꼬소함과 폭신한 빵까지 완벽❣️ 샐러드야채가 신선해서 남기지 않고 다 먹었어요! 따뜻한 양송이 스프 숟가락으류 뜨면 늘어나는 치즈까지- 날이 추운데 스프 순삭해버림❤️‍🔥 연남동 브런치맛집으로 인정합니다😎', 20, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '연남동카페 맛집~!! 포장만했는데 오늘은 매장에서 냠냠!! 크림빵 크림가득 들어있어서 너무 좋아요. 오늘밤보름달 맘모스빵도 여기가 젤 맛나요.', 49, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '연남동에 엄청 특이하고 맛있는 빵집이 있다고해서 약속 가는길에 들렸어요 평일이라 그런지 손님은 아예 없었고 이쁜 우드톤의 인테리어와 조명들이 마음에 쏙 들었어요 궁금했던 초승달과 빅뱅치즈빵, 곰스타치오를 시켰는데 굉장히 맛들이 강하고 짭쪼름하고 맛있어요! 초승달은 치즈랑 커스타드 맛이 섞였고 부드러운 크림이랑 쫀득한 빵 식감이에요 치즈빵은 짭쪼름하고 뽀또랑 체다맛이 섞여있어요 무엇보다 이쁘게 생겼잖아요 ㅠㅠ 이뻐요 다음엔 친구와 함께 와서 별빛의 색깔을 담은 밤식빵을 먹어보고싶어요 색상들이 너무 이뻐서 눈도 즐거운 빵집 입니다 연남동 카페 추천해요 :)', 20, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '모든 빵이 다 맛있다는 리뷰 보고 왔는데 진짜 다 맛있어요! 대응도 친절하시구 2층도 있어서 조용하게 이용 가능해요. 저는 오늘밤 반달 먹었는데, 평범해보이는 외견이라 큰 기대안했는데 안에 견과류랑 버터가 진짜진짜 맛있어요. 다른 빵도 먹어보고싶어요!! 여러명이 와서 빵 다 먹어봐야해요 🥹', 44, 8, 'GOOD', SYSTIMESTAMP);
