INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '빵이랑 음료 맛있었어요! 조용한 분위기지만 수다떨기 좋은장소예요! 밥먹기 애매해서 브런치먹으러 온거였는데 맛있게 잘먹었습니다❤️', 46, 7, 'GOOD', SYSTIMESTAMP);
