INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '브런치 메뉴와 빵 먹었는데 맛있었어요~~ 유명한 별이 빛나는 밤식빵을 못 먹어서 아숩지만, 그래도 그래도 다 맛있어서 아수움을 달랠 수 있어요~~ 담에 또 먹으러 와야겠어요~', 24, 0, 'GOOD', SYSTIMESTAMP);
