INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '허니바게트는 제 최애메뉴입니당🫶🏻 시나몬롤 처음 먹어봤는데 페스츄리 결이 살아있고 바삭해서 너무 맛있었어요!! 홍대 약속있을때 친구들 데리고 오는 곳이에요! 홍대&연남 카페로 완전 강추요❤️', 446, 96, 'GOOD', SYSTIMESTAMP);
