INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '몇번왔었는데 여기 크림빵도 정말 맛있구 빵 맛집이에요 자리도 은근 많고 넓어서 수다떨기도 좋구 깔끔해요!! 크리스마스트리도 있어요 연남동 카페추천  , 홍대 카페 추천합니다!!', 49, 1, 'GOOD', SYSTIMESTAMP);
