INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '와 솔직히 맛은  비주얼만하지 못할거라 생각했는데 진짜 역대 먹은 밤식빵중에 젤 맛났어요 ㅋㅋㅋㅋㅋ 생긴것도 넘 예쁘고 플레이팅 하나하나 정성스럽고 매장 분위기도 좋고ㅜㅠㅠ 홍대입구역 근처에 이런 카페가 있었다니!!! 자주 방문해서 먹을 거 같아요 완전 대만족 !!!', 35, 10, 'GOOD', SYSTIMESTAMP);
