INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '크리스마스 느낌나는 아늑한 분위기에요! 작은데 빵들도 나름 다양하고 좌석들도 편하고 음악도 좋고 조용히 있다 가기 좋습니당 ㅎㅎ 홍대 카페 추천, 연남동 카페 추천이요!', 28, 6, 'GOOD', SYSTIMESTAMP);
