INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '🥯 여기임자있소 (흑임자크림빵) 3.6 🥪  에햄샌드위치 (에그샐러드+햄+딸기쨈 샌드위치) 3.0 ☕️ 아이스아메리카노 4.5 토요일 오전에 혼자 방문한 카페 :) 흑임자 러버로써, 흑임자크림빵은 꼬수운 크림이 낭낭했고 에햄샌드위치는 듬뿍 들어있는 에그샐러드와 딸기쨈 (파시는거 보니 수제딸기쨈 같아요?!)이 조화롭게 맛있어요! 가격까지 착함 🫶🏻💕 아메리카노는 딱 맛있는 맛! (저는 산미 별로 안 좋아함ㅎㅎ) 매장도 넓은 편이고, 차분하고 아늑한 분위기에요. 재방문 의사 완전 🙆‍♀️🙆‍♀️🙆‍♀️ #홍대까페추천 #홍대카페추천  #연남동까페추천 #연남동카페추천', 68, 17, 'GOOD', SYSTIMESTAMP);
