INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '고흐의 그림이 생각나는 빵, 비주얼도 예쁘고 맛도 좋아서 선물하기에도 너무 좋은 빵입니다. 치즈빅뱅은 치즈가 흘러내릴 정도로 풍성하고 풍미가 있어요 매장도 넓고 인테리어도 예뻐서 좋습니다', 29, 3, 'GOOD', SYSTIMESTAMP);
