INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '빵이 너무 맛있어보여서 꼭 먹으러 와보고싶었어요! 빵도 맛있고 매장 분위기도 편안하고 예뻐요😍😍 다들 크리스마스 되기 전에 와보세용👍', 62, 17, 'GOOD', SYSTIMESTAMP);
