INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '조용하게 대화하기 좋은 카페예요! 오늘 첫 출시한다는 딸기타르트도 맛있게 먹었습니다😚 그릇도 너무 귀여워서 더 맛있게 먹었습니다 ㅎㅎ👍🏻', 73, 18, 'GOOD', SYSTIMESTAMP);
