INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '약속가기전 잠깐 들렸는데 분위기도 너무좋구~ 무엇보다 빵이 너무 맛있어요!!!!!찐한 갈릭소스랑 향이랑 맛에 아아도 딱이에요!!↗️🤦‍♀️빵도 따듯하게 데피주시고^-^진짜 강추합니닷🎵다양한 빵 종류가 있어서~ 완전!!!친구들과 와도 강추❤', 99, 21, 'GOOD', SYSTIMESTAMP);
