INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '홍대로 놀러가면 항상 찾아가는 카페에요! 임자있소 빵 크림이 느끼하지 않고 너무 맛있어서 오면 꼭 빵 하나씩 사 먹는 거 같아요♡ 다른 종류의 빵들도 많아서 하나씩 도전깨기로 홍대오면 자주 들릴 것 같아요! 번창하세요~', 19, 9, 'GOOD', SYSTIMESTAMP);
