INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '금요일 아침 오픈 시간 맞춰 가서 한적하게 여유 즐길 수 있어서 기분 좋고 넘 맛있네요ㅠㅠ 리뷰가 다들 넘 좋으셔서 오히려 의심(?) 했는데 다들 칭찬 일색 하시는 이유 알았습니다 ㅠㅠ 햇살 맞으며 브런치먹는데 성공한 인생 같고 조아여.. 크루아상도 너무 맛있어여 하나 더 먹을 것입니다', 32, 6, 'GOOD', SYSTIMESTAMP);
