INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '밤식빵 색이 재밌어서 사봤는데 담백하고 맛있어요! 달지도 않고 딱 적당하니 자꾸 손이 가네요. 음료도 맛나요~~ (근데 화장실이.. 좀 더 청소가 잘 되어 있음 좋겠어요~ 나쁜 편은 아니지만 매장 수준에 비해서 청결도가 떨어지네요.)', 66, 16, NULL, SYSTIMESTAMP);
