INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '추천받아 왔었고, 맛있어서 40분 걸리는데 재방문 했어요... 가족들도 선물하려구요! 달지않규 맛있늠... 다 맛있는네 흑임자로 추천합니다!!', 84, 13, 'GOOD', SYSTIMESTAMP);
