INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '작품을 먹는듯 예쁜 식빵 넘 맛있구요 선물하기도 넘 좋겠더라구요 여러가지 빵 다 맛있어서 넘 행복하게 먹었네요 음료도 맛있는데요 베베슈페너에 올라간 곰돌이 쿠키 넘 귀엽구요 크림이 너무나 맛있어서 힐링 제대로 됐네요 2층에도 홀이 있어 프라이빗하게 데이트도 가능해요 넓은 테이블이 있어 소모임에도 좋구요 별이빛나는 밤식빵 넘 맛나구요 치즈빅뱅~대박입니다 훌륭한 비쥬얼 만큼 맛도 있어요~포장이 넘 이뻐 선물하시는것도 추천드려요~^^', 35, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
