INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '베어스덴은 연남동에서 오래 자리잡고 있는 베이커리 카페에요. 빵을 여러번 구매했는데 리뷰를 처음 써봐요. 사진 속 빵들은 촉촉하고 달달한 오늘밤 초승달과 여기임자있소예요. 오늘밤 초승달은 저처럼 진한 치즈케이크를 좋아하시는 분들에게 추천드려요. 여기임자있소는 부드러운 흑임자 크림이 가득 들어있어요. 크게 달지도 느끼하지도 않고 고소해서 부모님이 정말 좋아하셨어요! 일반적인 우유크림과는 달리 물리는 느낌도 없었어요. 빵은 상관 없지만 카페 이용시 1층 카운터에서 1인 1음료를 구매해야 2층 이용이 가능하다 해요. 두 층 모두  깔끔하고 아늑해서 매장 이용하는 손님들이 많은 것 같아요.', 12, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '갑자기 빵이 땡겨서 검색하고 찾아갔는데 배달 주문도 많이 들어오는 곳인가봐요~ 마침 내일 추석이라 가족들 선물까지 꽤 많이 사왔네요^^ 일단 감자치즈치아바타 너므 촉촉 쫄깃 맛있게 먹었고요! 치즈빅뱅도 맛났고 뺑스위스는 단거 좋아하는 제게 딱이었어요ㅋㅋ 내일 먹게 될 빵들도 기대되네요 ㅎㅎ 베베슈페너는 두유맛이 확 나는 커피네요! 회사랑 가까워서 자주 가서 사먹게 될 거 같습니다 :) 아! 사장님이신거 같은데, 크림빵도 맛있다고 서비스로 두개나 주셨어요~ 크림빵은 잘 얼렸다가 며칠 후에 먹어봐야겠어요 ㅎㅎ 감사합니다!!', 16, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '예술적인 빵을 판다고 해서 찾아 갔습니다. 일반적인 밤 식빵과 바질 식빵이지만 명화를 구현한 식빵이라 특이했습니다. 맛있어 보이네요 ㅎㅅㅎ', 64, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '빵이 하나하나 다 이색적이고 너무 맛있어서 깜짝 놀랐네요! 빵순이라서 종류별로 하나씩 다 맛 보고 싶어졌어요. 베베 슈페너도 완전 굿굿! 인기 많은 메뉴들은 역시 이유가 있었군요. 빵들도 가성비가 좋고 퀄리티가 뛰어나요', 13, 6, 'GOOD', SYSTIMESTAMP);
