INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '홍대 예쁜 카페 찾고 계신분들 여깁니다!!!! 빵도 너무 예쁘고 맛있어 보이는 빵 가득이에요.... 전 테이크아웃 해 가지만 카페도 아기자기하고 예뻐서 다음에 먹고 가보려구요!! 담엔 꼭 별빛밤 치즈빅뱅도 먹어보고 싶어요', 40, 0, 'GOOD', SYSTIMESTAMP);
