INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '항상 밤 늦게 지나만 다녀서 꼭 한번 와보고 싶었던 카페인데 드디어 왔네요! 빵 종류도 다양하고 밖에서 못 보던 디저트 종류들도 있어서 좋았어욯ㅎㅎㅎ 쇼케이스에 있는 빵이 수량이 부족해도 요청하면 안쪽에서 꺼내주세요! 조용하고 자리도 많아서 홍대 카페 추천이요🙋‍♀️', 16, 4, 'GOOD', SYSTIMESTAMP);
