INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '뺑스위스랑 어니언 크림치즈 먹었을때 넘 맛있게 먹어서 연남동 나간김에 또 방문했어용! 오늘은 새로나온 뽀또식빵 도전 주중이라 그런지 저녁에도 빵종류는 조금 남아있었어용! 사장님도 친절하시고 담에는 카페좌석도 편안해보여서 담에는 먹고 가도 좋을거같아여', 22, 0, 'GOOD', SYSTIMESTAMP);
