INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '지나가다 우연히 들렸는데. 특별한 빵이 많아 놀랐어요. 홍대카페 추천합니다. 특별하고 맛있는 베이커리와 음료로 즐거운 시간 보내길 추천합니당', 35, 3, 'GOOD', SYSTIMESTAMP);
