INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '빵들이 다 너무 맛있어보여서 잔뜩 샀어요! 크로아상 샌드위치는 매장에서 바로 먹었는데 크기가 엄청나서 놀랐습니다ㅋㅋㅋㅋㅋ 커피도 맛있고 빵 종류도 다양하고 큼직해서 너무 좋아요🥐', 30, 8, 'GOOD', SYSTIMESTAMP);
