INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '보름달 맘모스 빵은 꼭 드세요. 속재료도 듬뿍 들었고 고소하고 아주 맛있어요!! 커피도 괜찮지만 식빵부터 시작해 여러가지 빵들이 진짜 맛있고 귀여워요♡ 인테리어는 깔끔 깨끗하고 2층창문에 포토스팟 있어요. #별이빛나는밤 식빵은 예술이 따로 없음!! #식빵맛집 #베어스덴베이커리 #맘모스빵 #협찬', 22, 6, 'GOOD', SYSTIMESTAMP);
