INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '커피도 깔끔하고 빵이 진짜맛나요 사장님도 친절하시구 빵 가격도 착해요 2층까지 있는데 2층엔 테이블 3개+창가자리있어욤. 저는 2시쯤 안돼서 갔는데 자리 있었는디 그 후로 바로 만석이었어요 ㅜㅜ 시끄럽지도 않고 빵먹으면서 수다떨기 좋아요 ~ 또 갈생각 💯💯 빵 종류가 많아서 쭈아요 ㅎㅎ', 20, 8, 'GOOD', SYSTIMESTAMP);
