INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '하.. 진짜 존맛빵...!!!!!!! 너무 맛있어서 바로 블로그 포스팅 했어요ㅠ 진심임..  이것만 시키고 맛있어서 더시켰는데 흑임자, 초코칩박혀있는빵, 허니바게트, 에그샌드위치 등등 아니어떻게 빵이 이렇게 다 맛있을수가 있어요? 평범한맛의 빵이 없고 그냘 전부 맛있구요 음료도 딸기밀크티좀 먹어보세요 딸기우유+밀크티 오묘하고 달콤한 존맛밀크티ㅠ 제발 누가 소문좀 내라ㅠ !! 내가 냄!!! 일단 일하시는 모든분이 너무 친절하셔서 기분이 너무 좋았음.. 빵추천+빵대펴주시기+음료추천 너무 쏘스윗해서 제발 가까운곳에 하나더내달라고 말씀드리고 싶음 홍대사시는분들은 좋겠다 여기 자주갈수있어서ㅠ 이 날 밥 오지개 먹었는데 빵도 한바구니먹음 다음에 또갈게효🥲💖', 23, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '홍대나 연남동 카페 추천 한다면 이곳를 추천하고 싶음..! 아니아니 밤식빵을 누가 이렇게 귀엽게 만드냐구요 ㅠㅠ 에햄 샌드위치도 기본이지만 맛있어보여서 샀어요! (에그샐러드+햄+딸기잼 조합 어케 참냐구.. 아는맛이 무서워..!) 오늘은 시간 없어서 포장하지만 빵 러버들은 빵사서 커피랑 먹으면 딱일듯,, 담에는 먹고 가야징! 😋', 12, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '저번에 크림빵 먹고 너어어어어어무무무무무 맛있어서 또 방문했어요!!! 크림빵에 크림이 가득들어있는데 느끼함 1도 없이 그냥 진짜 너무 맛있러요.... 치즈빅뱅도 너무 궁금해서 사봤어요 보나마나 ㅁ맛있게쬬... 다음에 또 올게요!!!!', 129, 20, 'GOOD', SYSTIMESTAMP);
