INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '지나가다 들렸는데 분위기가 좋고 빵도 맛있어요😍 사람이 붐비지않아 편하게 다녀왔습니다 ㅎㅎ 의자도 딱딱하지않고 푹신해서 좋아요 분위기 갬성 맛집입니다👍👍', 41, 1, 'GOOD', SYSTIMESTAMP);
