INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '빵이 너무예쁘고 접시도 너무귀여워요! 보기만좋은게 아니라 맛도 너무맛있어요ㅎㅎ 길다니다가ㅈ우연히 들어온 카페인데 너무맛있게 먹었어요 재방문의사 완전있습니다!😊', 46, 3, 'GOOD', SYSTIMESTAMP);
