INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '크리스마스라 그런지 크리스마스 분위기가 나요! 채소는 싱싱하구 빵은 맛있어요 스프는 좀 달달해요 블루베리 잼이 진짜 맛있는 것 같아용 다음에 또 오고 싶어요!', 95, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '토요일 12시 30분?쯤 방문했는데 별이빛나는밤빵은 없었어요ㅠㅠ 어쩔 수 없이 치즈폭탄빵이랑 바질빵 샀는데 예상 외로 치즈빵이 진짜 맛있었어요! 다음에도 또 방문하고 싶어지는 맛이었습니다. 치즈가 어떻게 흘라내리려나 궁금했는데 전자렌지에 데워먹으니 진짜 그냥 주룩주룩 흘러내리더라구요. 다음에 가면 치즈빵이랑 별이빛나는밤빵 사오려구요. 빵은 1차생산만 한다고 하니 주말에 가시는 분들은 일찍 가셔요.. 🥲', 18, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '배달의 민족에서 항상 주문 시켜먹다가 직접 방문해서 빵 구매했습니다! 인테리어도 멋지고 빵도 존맛탱입니다. 진짜 크림빵이 미쳤습니다. 강추드려요.', 11, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '든든하고 따뜻한 브런치 잘 먹었어요! 가게 내부도 크리스마스 분위기로 가득해서 연말 느낌나고 기분 좋았어요ㅎㅎ 빵이 맛있었는데 나중에 매장에 진열된 다른 빵들도 구매해보려구요!', 3, 8, 'GOOD', SYSTIMESTAMP);
