INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '식빵이 정말 부드럽고 맛있어요! 아인슈페너 좋아하시면 시그니처 음료 꼭 드샤보세요 곰돌이쿠키도 귀엽고 꼬소하고 맛있습니당..ㅎㅎ, 다음엔 다른 메뉴 먹어보러 올게요!', 24, 5, 'GOOD', SYSTIMESTAMP);
