INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '평일 점심시간 대 방문❣️ 아주 옛날에 왔을 땐 남자 사장님 혼자 운영하는 가게였는데 간만에 방문했더니 글쎄!! 매장이 엄청 커졌어요😊 빵 종류 많아요. 시그니처 빵들은 수량 넉넉해요. 근데 여자 직원 분..? 조금 불친절..ㅎ..그치만 빵이 맛있어서 용서 가능함🥖', 50, 6, 'GOOD', SYSTIMESTAMP);
