INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '레몬타르트 너무 맛있는데요…ㅠㅠ 값어치를 함… 진짜 맛있음… 또 와서 먹을 의향 있음 다음엔 밤식빵 먹어보고 싶어요 연남동 자주 와서 놀고 가는데 할로윈 분위기로 아기자기 잘 꾸며져있고 좋네요! 연남동 카페 추천합니다!!!', 48, 7, 'GOOD', SYSTIMESTAMP);
