INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '가끔 연남동 올때마다 별헤는밤 밤식빵은 꼭 사가요 예쁘기도 예쁘지만 진짜 맛있어요 카페처럼 확장된 이후론 처음인데 인테리어도 예쁘고 넘 좋네요 홍대카페추천, 연남동카페추천 해달라하면 여기가 딱입니다!', 75, 15, 'GOOD', SYSTIMESTAMP);
