INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '빵이 너무 맛있어요!! 곰스타치오 먹었는데 버터크림이 굉장히 맛있었습니다 다음에 오면 다른 것들도 먹어보고싶네용 😋😋 그리고 좌석들이 다 편하게 돼있어 너무 좋았어요 연남동 카페 추천합니다👍👍', 84, 15, 'GOOD', SYSTIMESTAMP);
