INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '홍대에 온 김에 빵사려고 들렸네요 :) 홍대 맛집 빵이라 기대하고 왔어요! 바질식빵 완전 기대!!!! 다음에는 꼭 일찍와서 별이빛나는 밤식빵 먹어 보고 싶네요ㅎㅎ 매장도 깔끔하구 넘 좋아요! 추천합니닷!', 1, 1, 'GOOD', SYSTIMESTAMP);
