INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '베베슈패너 너무 귀엽고 맛있어요🥹ㅠㅠ 두유맛도 고소하게나면서 크림은 부드럽고 위에 쿠키도 귀엽고 맛잇고ㅜㅠ이 시그니처음료는 꼭 다들 시키세요!!치즈빅뱅 뽀또맛 찐하니 너무맛나구요 곰피스타치오도 왜캐맛있나요🥲 2층은 조용하기도하고 분위기도 좋아서 맛난 디저트랑 커피마시기에 딱인듯해요! 다음에도 또올게요 ❤️', 49, 3, 'GOOD', SYSTIMESTAMP);
