INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '청포도에이드 추천이요!! 달달하고 맛있어용 ㅠㅠ 홍대카페, 연남동카페 오실분들 추천합니다!! 매장도 깔끔하고 분위기 좋아요👍🏻👍🏻👍🏻', 96, 24, 'GOOD', SYSTIMESTAMP);
