INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '홍대는 베어스덴 때문에 오쥬😄 오늘도 상수역에서 밥먹고 일부러 여기까지 걸어왔어요! 베어스덴 사서 집에 가려고:) 늦게 와서 품절된 빵도 있었지만! 그래도 빵 많이 사서 기분이가 좋습니다!❤️ 오늘도 맛나게 잘머글께요👍👍', 80, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '홍대 카페 검색하다가~ 발견한 베어스덴베이커리! 벌이빛나는밤식빵 인스타에서 종종 봤어서~ 궁금했는데! 여기였네요~~🥰 깔끔하고 조용한 분위기가 좋아요~ 2층에 단체석도 마련되어 있어요!^*^', 55, 15, 'GOOD', SYSTIMESTAMP);
