INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '식빵사러왔는데 아쉽게 품절이네요.ㅜㅜ 그래도 허니바게트 살 수 있어서 다행입니다!! 다음에 식빵사러 더 빨리와야겠어요!! 맛집인정!!', 79, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '별이빛나는밤식빵 처음 도전했는데 존맛탱이네용🥹💕 그리고 갈때마다 사먹는 빨미까레도 역시 맛있어요ㅠ 에햄샌치는 출근전에 아침으로 먹으려고 샀는데 엄청 알차요!!!!👍👍👍', 11, 9, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '밤식빵을 선호하진 않지만 너무 예뻐서 사버렸습니다 예쁜만큼 맛도 좋네요 ㅎㅎ 연세우유빵 상위호환 우유크림빵과 상큼한 레몬타르트 가성비좋고 진짜 맛있어요~ 배만 안부르면 몇 개 더 사가고싶을만큼 가장 맛있었던 <오늘밤초승달> 이건 꼭 드세요! 데워주셨는데 마치 이게 맞는 조합인가싶은 치즈에그타르트피자 같은 느낌인데...정말 맛있어서 깜짝 놀랐습니다 꼭 사드세요 아 그리고 쿠키 올라간 시그니처 슈페너도 부드럽고 맛나요 ㅎㅎ 분위기도 좋고 가성비도 좋은 맛도리빵집입니다', 32, 9, 'GOOD', SYSTIMESTAMP);
