INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '빵이 너무 먹고싶어서 방문한 베어스덴베이커리! 빵이 바삭하고 밀도가 높아서 너무 맛있게 먹었어용 아아 같이 먹으니까 빵 순삭! 맛있는 빵들 많아서 추천드려용👍🏻👍🏻👍🏻😊', 46, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '홍대 나오면 무조건 들리는 베어스덴!!! 오늘도 집에 가는길 참새가 방앗간을 지나치지 못하고 결국 들려서 빵쇼핑을 하고 갑니다🙂 제가 애정하는 허니바게트랑 치즈빅뱅은 무조건 장바구니 겟겟이에요!!!! 오늘도 베어스덴 먹고 힘내야겟어요💪💪', 4, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '비오는날... 밤식빵 하나 보고 찾아온 베어스덴이예요! 첫 방문인데 귀여운 곰돌이가 맞이해주고 있습니다 ㅎ_ㅎ 2층에도 너무 예쁜 공간이 있어서 아주 잘 맛있게 먹겠습니댜 !!! 아아도 맛있고 밤식빵 진짜 맛있어요ㅠㅠㅠ🩷', 15, 3, 'GOOD', SYSTIMESTAMP);
