INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '아인슈페어 너무 귀여운 쿠키가 올라가져 있어서 맛도 있으면서 좋네용 딸기 밀크티도 딸기우유에 밀크티 탄 맛이라 무난하게 마시기 좋네용 ㅎㅎ 더운 여름에 시원하면서 아늑하고 조용한곳 찾으신다면 한번쯤 오실만한거 같아요! 주말에는 이용시간 2시간 한정이라 그 부분이 아쉽지만 그래도 만족스러운 카페입니당', 3, 7, 'GOOD', SYSTIMESTAMP);
