INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '간단하게 먹고 싶어서 왔다가 양도 많고 너무 맛있어서 배부르게 먹고 갑니다 👏🏻👏🏻 사진 예쁘게 찍었는데 왜 때문인지 사진이 안 떠서 못올리네요ㅠㅠㅠㅠ 가게도 아늑해서 편하게 있을 수 있고 일이나 과제하러 오기 좋을 것 같아요~ 덕분에 편안한 시간 보내고 갑니다❤️', 15, 1, 'GOOD', SYSTIMESTAMP);
