INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '자몽차가 너무 맛있어요! 갑자기 비가와서 급하게 들어온 카페인데 맘에 들어요. 자몽차가 굉장히 깔끔하고 헤이즐넛 라떼도 헤이즐넛 향이 좋아요.', 5, 1, 'GOOD', SYSTIMESTAMP);
