INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '밤식빵이랑 어울리는 향 좋은 녹차가 있었으면, 하는 생각이 들었어요. 빵 바로 나왔을 때 먹으면 더 좋을 것 같지만 식빵 쫀득하고 밤도 달달하고 맛 좋습니다. 비주얼때문에 온거지만 다시 봐도 신기한 비주얼이네요😄', 1, 1, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '별이 빛나는 밤식빵 보고 방문했는데 크림빵도 너무 맛있었어요😋😋 밤식빵은 속이 촉촉하고 쫀득하고 당적밤도 달콤해서 사라지는 게 아깝다고 생각하고 먹었어요! 크림빵은 오메기떡 같은 속이 들은 빵을 먹었는데 쑥크림이 진하고 향긋해서 크림만 먹어도 정말 산뜻하더라구요! 친구들이랑 방문하기도 좋은 것 같아요ㅎ.ㅎ', 13, 4, 'GOOD', SYSTIMESTAMP);
