INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '홍대에서 제일 맛있는 빵집은 여기죠:) 늘 일부러 찾아오는 베이커리 맛집!!! 직원분도 친절하시고 매장도 크고 이뻐서 인스타 갬성🤍 오늘도 야무지게 빵 사갑니다🙂 홍대오면 꼬옥 들려야될 빵 맛집 모두 메모하세욤 📝', 7, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '일단 역이랑 가까워서 잘 찾아갈수있었어여 🫶🏻 카페도 넘 이쁘구 제가 똥손이라 사진을 못찍은건데 실제로 빵보고 기절.. 🥹💛 빵이 이렇게 이뻐도 되나여💌 베이커리 카펜데 음료 존맛탱 앉는자리에서 음료 두번 먹었어여 ㅋ ㅋ ㅋ ㅋ ㅋ ㅋ 빵도 먹자마자 다시 카운터가서 집에 가져갈거 포장주문💛 미쳤어여 홍대에서 최고 아니 제가 살면서 먹어본 빵집 중 최고에여 육아중인대 육아하면서 빵 생각만 날 정도로,,, 쮼맛... 😍 그리고 다들 너무 친절하시구❤️ 예스키즈존이라 아들 데리구 또 갈겁니다✅💚 베어스덴 최고 🎂 오래 있어주세여😍', 48, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '홍대에 볼 일 있어 들렀다가 베어스덴을 발견했습니다! 예쁘고 아늑한 카페에 맛있는 빵이 가득해서 혼자 와도 친구들끼리 와도 넘 맛있게 먹을 수 있을 것 같아요ㅎㅎ 홍대 까페 추천합니당 ><', 58, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '빵종류도 다양하고 처음보는 메뉴도 많아서 신기했어요ㅋㅋ 여기 치즈빅뱅사서 이미 먹어봤었는데 에어프라이어에 돌려 바삭하게 먹으면 더 맛있어요! 꼭 드셔보세용👍', 15, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '아낌없는 재료의 다양한 빵 종류 2층카페라서 먹고가기도 포장해가기 좋아요 🥐 빵마다 재료가 풍부하게 들어가 알차게 맛있고 빵 종류 선택의 폭이 넓고 연남동 초입에 가까워서 빵포장 빵선물하기 좋은 곳 😀 맘모스빵을 좋아한다면 무조건 오늘밤보름달! 맘모스빵 맛집으로 유명한데서 몇시간 기다려서 사먹은데보다 진심 맛있어요 🌕 맘모스가 묵직하고 밤이랑 크림 소보루 등 재료가 알차서 한두 조각만 먹어도 배부를 정도.. 맘모스빵 맛집이예요 💛 에그타르트 좋아하신다면 필수! 파삭파삭 파이지의 결이 살아있고 몽글몽글 부드러운 에그타르트도 수준급 흑임자,, 쑥필링이 들어있는 크림빵 할매입맛 저격 보드라운 크림 끝없이 먹고싶어요 👵 바게트는 고소한 볶은호두와 크랜베리 씹는 맛이 담백한 매력 고른빵 빠짐없이 다 맛나요 🧡', 24, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '빵 맛집으로 소문난 곳❤️ 가보고 싶었는데 오늘 와보네용 먹어보고 맛있으면 또 방문 오겠습니다! 감사합니다🥰 홍대까페추천❤️연남동까페추천💛', 76, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '연남동을 자주 오는데 요렇게 예쁜 베이커리가 있었다니..!! 고흐 모티브로 한 밤식빵이 베어스덴 시그니처인데 밤식빵 좋아하는 분들 추천 🥺🩷 밤도 듬뿍 들어가있고 넘 고소하고 같이 주문한 베베슈페너 크림에 찍어먹어도 그렇게 맛있다구요 ?! 소세지 페이스트리도 바삭바삭한 식감 최고 ㅠㅠ 저 진짜 빵순이랑 빵 진짜 많이 먹는데 여기 있는 빵 다 먹어보고 싶어서 눈이 가는 빵들 포장해왔어요 ;) 크림빵 종류는 냉장보관, 식빵은 3-4일 후 드실 예정이면 냉동보관 가능하다고 하셨어요 !! >_<', 20, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '빵 이름들이 독특하고 빵도 예뻐요! 분위기도 차분하고 빵 종류도 많은데 먹어 보고 싶은 것들이 품절이라 아쉬웠어요 ㅠㅠ 다음에 또 올 거예요!', 21, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '디저트 카페 찾다가 들어간 베어스덴카페에요! 인기 메뉴인 에그타르트랑 우유크림빵 먹어봤는데 기대이상이었어요!! 에그타르트는 크리스피 부분은 빠쟉하고 계란 부분은 부드럽고 ㅠㅠ 크림빵도 안달고 맛있어요ㅠ 빵 좋아하시면 베어스덴 추천합니다!!🥰🥰', 51, 11, 'GOOD', SYSTIMESTAMP);
