INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '매장이 넓고 좌석이 많고 빵이 맛있어요! 크로와상 샌드위치 크로와상이 커서 너무 좋았습니다. 커피도 좋네요~! 치즈식빵도 치즈가 진짜많음!', 13, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '제가 최근에 먹은 빵들중에 손에 꼽힙니더 너무 맛있고 개성 있어서 좋아요 ㅠㅠ 무엇보다 진열되어 있는 게 깔끔하고 청결해서 너무 맘에 들었고 특히 요 시그니처 밤식빵이 색이 예쁘고 밤이 한가득 들어가서 너무 맛있었어요 ㅠㅠ 커피랑 같이 먹으면 힐링 그자체....그리고 허니바게트 제발 꼭 드세요 진짜 찐으로 너무 맛있음 순삭킬러함..너무 맛있음 제발 드세요 꼭 드세요...베이커리 찐맛집입니다 ㅠㅠㅠ너무 맛있음..달달하고 부드럽고 좋아요..재방문 의사있어요❤', 49, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '연남동 올때마다 방문하는 최애까페❤️‍🔥 여유있는 공간에 노래 맛집 분위기 맛집 진짜 동네에 있어서 매일 오고싶은곳! 허니바게트 달달하니 고소해서 진짜 맛있어요 앙버터- 팥가득 버터가득 미쳤어요!!!! 에그타르트, 베베 에그타르트 먹구 다른곳에서 에그타르트 안먹어요 진챠!!!!🤦🏻‍♀️ 더운날엔 상콤한 레몬타르트에 따뜻한라테🫶🏻', 31, 4, 'GOOD', SYSTIMESTAMP);
