INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '빵에 진심인 카페! 빵 잘하는 집은 기본빵이 훌륭한데 여기 치아바타는 쫄깃하니 진짜맛있어요. 👍🏻 요즘 크루와상샌드위치에 푹 빠져서 주 3회는 먹는데 최근에 먹어본 샌드위치 중 탑임. 홀그레인머스타드 소스가 신의 한 수! 다른 빵도 맛있었지만 크루와상샌드위치먹으러 재방문하려합니다❤️❤️❤️❤️', 15, 7, 'GOOD', SYSTIMESTAMP);
