INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '보름달 빵이 먹고싶어서 배달 시켜먹다가 직접 사러 왔어요 ㅋ.ㅋ 우유버터크림 엄청 맛있고 개인적으로 살짝 얼려 먹으면 더 맛있어요. 앞으로도 배달 시킬거임!', 8, 2, 'GOOD', SYSTIMESTAMP);
