INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '미리 보고 간 것보다 메뉴가 많았어요!! 카페가 아니라 빵집으로 생각해도 될 정도!! 연희,연남의 매력적인 골목속의 빵냄새 풍기는 공간 ㅎㅎ 낭만적입니다.', 32, 2, 'GOOD', SYSTIMESTAMP);
