INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '빵이 너무 예뻐서 먹기 아까울 정도이나 한 입 먹는 순간 맛있어서 순삭하게 되는 그런 맛입니다😭 오늘밤 반달도 먹었는데 안에 크림치즈랑 호두가 장난아니에요... 연남 또는 홍대에서 데이트 하시는 분들은 꼭! 꼭! 방문해보시길 추천드립니다!!', 33, 3, 'GOOD', SYSTIMESTAMP);
