INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '작년 여름에 우연히 들렀다가 먹은 피스타치오 크림빵이 너무 맛있어서 다시 찾아왔어요~ 여기 바게트, 식빵도 유명하지만 저는 곰스타치오가 젤 맛있었어요ㅋㅋ 피스타치오 좋아한다면 꼭 한번 드셔보세요!', 37, 9, 'GOOD', SYSTIMESTAMP);
