INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '늦은 점심먹고 후식으로 빵먹고싶어서 왔는데 너무 맛있어요,,,, 추억의 맘모스빵,,, 완전 맛있고 갈릭 바게트 센스있게 데워주시고 초코크림빵에 크림이 흘러 넘쳐서 앞에서 남자친구가 다뭍히고 먹으면서 행복해 하네요 ,,,😆 저도행복하게 잘먹었습니다~', 48, 10, 'GOOD', SYSTIMESTAMP);
