INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '배민에서도 자주 시켜먹다가 지인 선물해 드리려고 포장하러왓는데….역시 베어스덴 항상 맛잇는 빵 🥹🫶🏻 밤식빵 밤양도 미쳣는데 너무 예뽀🤧❤️', 84, 11, 'GOOD', SYSTIMESTAMP);
