INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '베어스덴베이커리의 별이 빛나는 밤식빵을😍먹게 되었네요! 유명한 빵을 드디어 먹어보게 되어 기뻐요! 카페 분위기도 아늑하고 넘 좋습니당❤️', 130, 23, 'GOOD', SYSTIMESTAMP);
