INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '2021년에 우연히 방문 후 홍대 올 때마다 오는 빵집이에요..! 자주 오지는 못하지만 빵이 너무 맛있어서ㅎㅎ 항상 즐겁게 방문합니다:) 다음에 또 올게요!! 오래오래 장사해주세용 사장님!❤️', 1, 0, 'GOOD', SYSTIMESTAMP);
