INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '빵이진짜 맛있어요!! 지금까지 다닌 베이커리 카페중에 제일 맛있었어요!! 자기전마다 생각나용ㅠㅠ🥹🥹 다음에 가면 잔뜩 쟁여오고싶네요!!', 0, 4, 'GOOD', SYSTIMESTAMP);
