INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '여기 빵맛집이라 배달시켜먹다가 퇴근길에 들러봤습니다! 홍대 카페 추천 이예용! 혼자와도 분위기도좋고 시끄럽지 않아요! 참치빵 진짜 최애 대존맛 ㅠ 커피도 맛있습니다', 428, 36, 'GOOD', SYSTIMESTAMP);
