INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '이동네 올때 항상 들려서 바질식빵 사가요~~ 오랜만에 왔는데 오늘은 갈릭바게트도 있어서 넘 좋네요 바질식빵은 여기가 최고맛있어요 ㅠㅠ~~', 432, 87, 'GOOD', SYSTIMESTAMP);
