INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), 'ㅠ 오늘은 너무늦었네여ㅠㅠ 내 최애중 빨미까레만 남았어요 그래도 이거라도 남은걸 다행으로여기구ㅠㅠ 신메뉴? 에그마요샌드위치랑 아아로 슬픔달래고 갑니다ㅠㅠ 에그마요 랑 아아 찰떡쿵야네요ㅎㅎ 에그마요 2-3개 챙겨서!! 담날먹어야겠어여 담주는 일찍올게여ㅜㅜ 빵 남겨줘요ㅜㅜ😂🤣', 263, 80, 'GOOD', SYSTIMESTAMP);
