INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '초코소라빵은 생각보다 커요! 손바닥 1.5배?ㅎㅎㅎ바삭한 패스츄리로되어있어서 타빵집이랑 다르게 너무 맛있을것같구요 밤식빵속에 밤 쪼금 들어있음 섭섭하잖아요....근데 풍부하게 푸짐~~~~히 들어있습니당^.^일부러 찾아올맛 나는것같아요히히', 81, 11, 'GOOD', SYSTIMESTAMP);
