INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '배달로도 시켜먹어본 곳인데 너무 맛있어서 잊을 수가 없었거든요!!??근데 연남에 우연히 왔다가 찾아서 진짜 감격스러워요..빵이 너무 맛있고..그냥 빵피부터 내용물까지 다 맛있어요 최고에요 !!!!빵순이 대만족', 25, 4, 'GOOD', SYSTIMESTAMP);
