INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '분위기도 좋고 빵 종류도 많아서 데이트하기 좋아요! 넘 유명한 곳이라 빵 맛은 믿고 포장 해갑니다~ 치즈 빅뱅 치즈가 폭포처럼 흘러내리던데 기대돼요!! 크림빵도 넘 맛있을거같아용ㅎㅎ', 23, 9, 'GOOD', SYSTIMESTAMP);
