INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '빵 종류가 진짜 다양해요! 매장에서는 레몬타르트랑 진짜 적당한 상큼함과 달달함으로 아아메랑 진짜 잘어울리고 내가 젖소는 먹어본 우유크림중에 제일 맛있었어요! 농축된 투게더 맛크림에 쫄깃한 빵이라 너무 맛있었어요!! 그리고 커피는 바닐라라떼가 진짜 맛있습니다🤤', 102, 21, 'GOOD', SYSTIMESTAMP);
