INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '진짜 너무 맛있어요ㅠㅠ 치즈빅뱅이랑 내가젖소 진짜 모든 사람이 한번씩 다 먹어봤으면 좋겠을 정도입니다..❤️ㅋㅋ 집에서 나중에 배달시켜먹으랴규요!', 10, 6, 'GOOD', SYSTIMESTAMP);
