INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '진짜 자주오다가 이직해서ㅠ 너무 오랜만에 들렸는데 신메뉴도 많이생기구! 곰스타치오.. 피스타치오버터크림 부족함없이 잔뜩들어있네여🙊🙊 넘좋습니다ㅠㅠ 소세지빵은 당연히샀고 별이빛나는밤식빵  항상 품절이었는데!! 마지막 남은거 있길래 바로샀어여 와ㅠㅠ 너무 잘먹겠습니다ㅠㅠ 🙈🙊🙉👍 곰스타치오,별이빛나는식빵,소세지빵 강추해여!!!👍❤️', 13, 5, 'GOOD', SYSTIMESTAMP);
