INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '베베슈페너 강추!! 곰돌이 쿠키도 너무 귀엽고..🐻💖 커피 맛이 넘 좋아요ㅠ 생각보다 많이 달지도 않고 기분좋은 두유맛이 잘 느껴져요! 귀여운 이름의 크림빵안에는 크림이 한가득..🫶 입 안 한가득 폭식폭신 크림이 넘 맛있어요..☁️ 재방문의사 100%입니당!!', 10, 3, 'GOOD', SYSTIMESTAMP);
