INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '홍대역 3번출구에 공원 바로 앞에 있어서 찾기 쉬웠고, 치아바타 빵이 정말 폭신 쫄깃 너무 맛있었다. 별이빛나느밤에는 어쩜 이렇게 파란 색을 내셨는지 궁금했고 안에 밤이 가득, 견과류도 같이 들어서 좋았다. 빵 이름들이 다 귀여웠고, 크림치즈 넣어주는 까만빵 맛있었다. 아늑한 공간에서 시그니쳐커피 곰돌이 쿠키 넣어주는 커피 달달하고 맛있다. 아래 있는 커피는 쓰지만 같이 먹으면 달달하다.', 58, 12, 'GOOD', SYSTIMESTAMP);
