INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '소금빵이랑 크림빵 전부 다 너무너무 맛있어요 🥰 저는 늦게 와서 빵이 별로 없어가지구 아쉬웠어요..ㅠ 그래서 다음에 또 방문해서 왕창 사가려구요 ❣️❣️❣️ 다들 연남동 들리실 때 베어스덴 가서 빵 하나씩 사가셔요 ㅎ💕', 31, 3, 'GOOD', SYSTIMESTAMP);
