INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '내부가 너무 깔끔하고 인테리어가 너무 이뻐요!! 그리고 빵이 너무 맛있고 캐릭터 로고가 너무 귀여워요ㅜㅜ 다시 꼭 방문하고 싶어요ㅎㅎ', 44, 0, 'GOOD', SYSTIMESTAMP);
