INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '오랜만에 홍대 방문!! 리뷰보고 방문한 빵집인데.. 빵들이 너무너무너무 맛있어보여요♥︎ 빵 한가듯 사서 나들이~♥︎ 사장님도 넘 친절하답니당 ◡̎ 집에와서 먹어본 후기 - 소금빵 미쳤어요.. 왜 한개만 사왔을까 ㅠㅠ 내가젖소 얘는 뭔데 또 이렇게 부드럽고 맛있는지.... 여기 빵 사러 홍대 조만간 또 갈거같아요!!!!!!!', 32, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '빵이 너무 부드럽고, 크림이 진짜 맛있어요! 음료도 가격이 착한 편이고, 특이한 메뉴가 있어서 놀러오기 좋은 곳인 것 같아요:) 재방문 의사 있어요!!!', 87, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '카페분위기가 좋아보여서 들어왔어요!! 빵 종류도 다양하고 포장해가시는 분들이 많아보였어요~ 앙버터도 엄청 크고 안에 단팥이 너무 많이들어서 먹는 동안 행복했습니당🤎', 1, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '쑥 디저트 너무 좋아해서 쑥크림빵 찾아왔어요. 크림이 진하고 맛있는데 너무 달았어요ㅠㅠ 쑥크림도 달고 팥도 달달해서.. 당도가 너무 높게 느껴졌어요. 쑥보다 기대 안했던 흑임자가 오히려 너무 맛있었고 당도도 적당했어요. 흑임자는 재구매 할 것 같고 쑥은 너무 달아서 재구매는 안할 듯 합니다😢', 43, 3, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '😝지난번 방문때 빵과 음료도 맛있었고 분위기도 좋았던지라 다시한번 찾게 되었어요😋 🏠베어스덴에 오면 꼭 먹어봐야 하는 빵이 바로 💥''별이빛나는 밤식빵''이어서 다시한번 주문완료!!! 💙파랑💛노랑색의 알록달록한 빵의 모양을 빈센트 반고흐의 명화 🌃[볓이빛나는밤]을 모티브로 만든 빵이어서 색감도 좋고 달달한 밤이 들어가서 넘 이쁘고 맛있걸랑요😋 🌜오늘밤초승달은 초승달 모양의 빵에 🍯잼이 듬뿍 토핑되어 있어 빵과 잼의 조화는 달달하기가 초승달과 같다지요 ㅋㅋㅋ👻 🫐크치 블루베리는 겹겹층의 빵 중앙에 🫐블루베리잼이 빵컵에 담겨있서 사르르 부서지는 🥞빵과 잼맛이 그야말로 짱맛도리에용🤡 🍹자몽에이드와 청포도에이드는 💫새콤달콤 상큼한맛이었고 💓전체적으로 빵이나 음료가 너무 맛있고 달달하니 넘 좋았어용!!!💯', 3, 9, 'GOOD', SYSTIMESTAMP);
