INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '맘모스빵이 먹고싶어서 서칭해서 왔어요!! 안에 알차게 들어있어서 너무 맛나요 ㅎㅎㅎ 다양한 빵들도 많아서 다음에 또 방문하려고요 🩵💗', 79, 12, 'GOOD', SYSTIMESTAMP);
