INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '몇년째 여기 올 때마다 꼭 사가는 빵이에요 오늘도 2개 구매하려고 했는데 하나밖에 안 남아 있어서 슬퍼요ㅠㅠ 많이 달지도 않아서 부모님도 좋아하시고 저도 항상 맛있게 먹는 빵이에요 ❤️❤️❤️', 47, 2, 'GOOD', SYSTIMESTAMP);
