INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '인스타에서 별이 빛나는 밤식빵 보고 왔는데 주문은 다른 걸 해버렸지만.. 완전 만족합니다!! 우선 빵 크기에 엄청 놀랐어요 ㅋㅋㅋㅋㅋㅋㅋㅋㅋ 절대 이 가격에 살 수 있을거라 생각할 크기가 아니었어서.. 가성비 너무 좋고 이색적인 빵이 많아서 빵순이인 저에겐 빵지순례 한 코스이기도 했습니다!! 빵도 퐁신하고 크림도 가득 너무 맛있어요~ 매장도 1,2층 구성 되어 있어서 넓고 쾌적하니 친구끼리 오거나 혼자와서 일하기에도 좋을 것 같아요~', 50, 3, 'GOOD', SYSTIMESTAMP);
