INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '연남동 철기에서 조금만 벗어나면 만나는 분위기 있는 카페. 커피도 맛있고, 디저트도 맛있어요. 사장님이 라떼에 캐릭터도 정성스럽게 만들어주시고 매우 만족합니다. 👍🏻 맛있는 디저트 드시고 싶으시면 여기로 오세요 :)', 47, 6, 'GOOD', SYSTIMESTAMP);
