INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '점심시간에 날이 너무 좋아서 동료랑 산책하다가 찾은 카페 요즘 크림커피에 빠져있어서 아인슈페너 시켰는데 너무 귀여운 곰도리가 올라가있음 🐻🐻 크림도 너무 맛도리 ..🥹🥹 가볍게 업무 보기도 좋고 2층에 날이 좋아서 창문 열어둔 바 테이블? 이 너무 분위기가 좋음 !! 사내 메신저에 추천해놔가지고 앞으로 직원들이랑 산책겸 자주 올거 같음', 26, 1, 'GOOD', SYSTIMESTAMP);
