INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '직원분이 너무너무 친절하시구 크림빵 종류 완전 다양해서 고르기 어려웠어요!!너무 맛있어 보이는 빵이 쇼케이스에 왕창..!!다사고 싶었는데 다음에 떠 방문해야겠습니당🫶🫶번창하세용', 26, 10, 'GOOD', SYSTIMESTAMP);
