INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '주변에서 밥먹고 괜찮은 카페 검색하다가 방문했어요! 빵종류도 다양하고 가격도 착해서 좋아요💗 시그니쳐 베베슈페너도 부드럽고 맛있어요 담에오면 리뷰많은 별이빛나는 밤식빵 먹어보고 싶어용', 4, 8, 'GOOD', SYSTIMESTAMP);
