INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '여기 크림빵 크림이 완전 맛있어용 다른데는 크림이 느끼한데 가볍고 좋아용 맘모스빵도 맛있어용 거의 맘모스가 살아돌아온 느낌이었어용 강추예요 그리고 넘 깨끗하고 편해용 빵 맛있당', 68, 17, 'GOOD', SYSTIMESTAMP);
