INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '아이들과 같이 왔는데 빵 종류도 다양하고 평상시 보지 못했던 빵 종류도 있어 신기했어요.  빵도 음료도  맛있어요. 아이들이 너~~무 잘 먹네요^^ 매장도 넓고 깨끗해요!!', 106, 24, 'GOOD', SYSTIMESTAMP);
