INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '배달만 매번 시켜먹다가 오늘이 직접방문 두번째요! 오늘은 식빵을 샀는데 쫀득하고 부드럽고 맛있어요 여기는 크림빵도 마늘바게뜨도 다 맛있으니 추천이요 배달만큼 매장도 깨끗하고 넓네요 :)', 4, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '빵친자의 연남 최고 빵맛집👍 사장님이 찐빵돌이라 그런지 맛잘알이세요 너무 맛있습니다!! 허니바게트는 다른곳에서 먹어보지 못한 진짜 꿀맛이에용ㅎㅎ', 37, 1, 'GOOD', SYSTIMESTAMP);
