INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '친구랑 같이 놀러왔다가 출출해서 가는데 맛있는 냄새가 나서 들어가봤더니 세상에…💗 너무 맛있었어요 진짜 아인슈페너 크림 진짜 개맛있고여 빵도 다 존맛이었어요..😋', 45, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '다시 온 베어스덴베이커리 오늘은 속이 저번보다 괜찮아서 빵도 같이 주문 허니바겥흐~ + 자몽티 hot 에어컨에 붙어있는 달력 귀여워서 찍었는데 알고보니 오는 손님 다주는것(소진되면 끝이래요 Baaam) 서둘럿!!! 전등이 이뻐서 찍었구, 이 매장은 시그니쳐 스티커 종류가 많아서 좋와요. 이번에는 시그니쳐 빵 스티커로 ! 저번에는 식빵이었지롱 허니바게트 제 취향이네요. 맛난다 맛나 대화도 맛있구 빵도 맛있고 인디분위기 노래에도 치한다 치해~~ 기분 좋게 이야기도 하고 시간도보냈네요. 여전히 영수증리뷰 이벤트는 하고있으니 방문해서 맛있는 디저트도 옴뇸뇸 하시구 영수증리뷰 이벤트로 빵 도 받아가방', 14, 4, 'GOOD', SYSTIMESTAMP);
