INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '별이 빛나는 밤식빵 사진보고 너무 예뻐서 사러 갔어요. 밤식빵이랑 치즈식빵이 인기 많은 것 같아서 요 2가지 포장했고 먹어보니 고소하고 부드럽고 촉촉하니 너무 맛있아요. 특히 밤식빵 완전 제 스타일이라 또 사먹으러 가야겠어요..💕', 72, 15, 'GOOD', SYSTIMESTAMP);
