INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '너무 맛있어서 자주와용! 특히 밤식빵도 너무 맛있고 귀여운메뉴들이 너무 많아요! 근데 다 맛있음 ㅠㅠㅠ 데이트로듀 친목으로도 너무 좋음! 홀도 깨끗하고 예뻐용 연남동 빵맛집❤️', 87, 17, 'GOOD', SYSTIMESTAMP);
