INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '우연히 들어간 카페였는데 빵 종류도 많고 음료도 맛있어서 목도 축이고 배도 채웠어용🫶🏻  인테리어도 아기자기하고 친구들이랑 휴식할 수 있어서 좋았습니다@@ 사장님두 친절하시구오 다음에 다른빵도 먹으러 올게용✨✨', 50, 6, 'GOOD', SYSTIMESTAMP);
