INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '곰돌이빵이 너무 귀여워요! 조용하고 비교적 넓직한 카페를 찾고 있었는데 발견하자마자 왔네요! 빵 이름도 독특해서 괜히 눈길이 더 가요 😖 다음번엔 흑임자빵을 사먹어보려고요!! (에그타르트가 큰게 너무 좋았어요...... 다른데는 한입컷인데!)', 121, 26, 'GOOD', SYSTIMESTAMP);
