INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '🏡홍대 연남동 오면 꼭 방문해야되는 🍞베이커리카페로 유명해서📺''모닝와이드''와 ''생방송오늘저녁''에서 방영된적도 있더라구요🤠 🏠베어스덴에 오면 꼭 먹어봐야 하는 빵이 바로 💥''별이빛나는 밤식빵'' 빈센트 반고흐의 명화 🌃[볓이빛나는밤]을 모티브로 만든 빵이어서 색감도 좋고 달달한 밤이 들어서 넘 이쁘고 맛있었어요😋 🐻초코곰돌돌은 곰돌이가 넘 기욤기욤🥰 🌪꽈베기안에 초코가득 들어있어 빵과 곰돌이를 🍫초코시럽에  찍어먹으니 넘 달달하니 맛있어요🍭 🧁몽블랑은 겹겹이 빵결이 살아있어 뿌려진 가루와 함께 먹으니 요것도 아주 짱맛도리고 🍞플레인 치아바타는 말랑말랑하니 임팩트 있는 맛은 안나지만 은은한 맛이 느껴져요✨️ 🍹스트로베리와 🍸청포도에이드로 시원하게 입안을 정돈해주니 펄펙트💯', 84, 14, 'GOOD', SYSTIMESTAMP);
