INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '믿고 오는 홍대 빵맛집! 곰스타치오,허니바게트,오늘밤 초승달 요 3개 저의 픽들입니다. 아낌없이 재료를 쓴게 느껴져서 가격이 아깝지 않아요! 강추👍👍👍', 30, 7, 'GOOD', SYSTIMESTAMP);
