INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '맘모스빵이 있어서 너무 좋아요ㅠㅠㅠㅠ크림도 팥 앙금도 너무너무 맛있어요! 두개의 층으로 되어있고 윗층에는 큰 테이블도 있어서 단체로 오기에도 좋을 거 같아요~! 사장님도 친절하시고 빵 너무 맛있습니당!!', 81, 16, 'GOOD', SYSTIMESTAMP);
