INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '빵에 진심이신 엄마와 남편, 커피좋아하시는 아버지 모시고 왔어요~ 식빵이랑 맘모스빵은 포장하고 초승달빵이랑 쑥크림빵 먹었는데 빵은 담백하고 크림은 느끼하지않고 너무 맛있네요~ 커피도 깔끔하고 맛있습니다^^ 사장님도 너무 친절하시고 다음에 꼭 다시 오고싶은 곳이에요~~', 14, 6, 'GOOD', SYSTIMESTAMP);
