INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '벌써 3번째 방문하는 베어스덴 차분하고 , 아늑한 분위기 그리고 맛있는 빵들 이집의 큰 메리트 인 것 같다. 아직 못먹어본 빵들이 많은데, 속이 좀 괜찮아지면 도전해보고싶다!! ㅠㅠ 시그니쳐 스티커들은 종류가 많아서 매번 다른 스티커 받아가는중 이번 리뷰 이벤트는 흑임자 있소로 가져갔다🤭 흑임자의 고소함과 크림이 오..묘한데 중독성 있었다. 매번 여기서 진지한 이야기를 하는데 진지한 이야기 하기 좋은 곳 머물다 가기 좋은 곳 ! 👍🏻', 46, 3, 'GOOD', SYSTIMESTAMP);
