INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '치즈식빵 밤식빵사러 왔는데 다른빵들도 너무 맛있을거같아요 너무 먹음직스러워요 가게도 깔끔하고 예뻐요 다음번엔 커피와함께 빵먹어볼래요', 74, 17, 'GOOD', SYSTIMESTAMP);
