INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '빵이랑 음료 다 너무 맛있어요! 아무 생각 없이 매장에 들어갔는데 분위기도 너무 좋고 청결하고 직원분들도 친절하셔서 힐링하다 가요.', 16, 6, 'GOOD', SYSTIMESTAMP);
