INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '올때마다 갈릭바게트 5개씩 사가요ㅠㅠ 바로 먹으면 당연 꿀맛이지만 얼려뒀다 에어프라이어 돌려 먹어도 겉바속촉으로 극락가요ㅠㅠ 식빵, 앙버터, 크림빵, 치아바타 뭔들,,, 전부 최고입니다👍🏻', 41, 7, NULL, SYSTIMESTAMP);
