INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '어느카페나 주말에 너무 시끄럽고 자리도 없어서 난간했었는데 우연히 들어간 골목에 조용하고 아늑해보여서 방문했어요. 인테리어가 화이트앤우드 컨셉으로 따뜻해보여서 좋았고 빵 종류도 많아 고르는데 한참 걸렸어요~ 원두도 좋은거 쓰셨는지 너무 맛있어서 만족했습니다.', 426, 76, 'GOOD', SYSTIMESTAMP);
