INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '인테리어도 분위기도 아늑하고 조용해서 디저트먹기 넘 좋고 무엇보다 빵이너무 맛있어요  사장님도친절하시고 지하철역에서 가까워서 접근성최고네요^^ 별이빛나는 밤식빵은 꼭 먹어보세요^^최고 ㅋㅋ', 23, 7, 'GOOD', SYSTIMESTAMP);
