INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '책도 읽을겸 빵이 땡겨서 돌아다니다가 분위기 좋아서 들렀어요ㅋㅋㅋㅋㅋ 사장님도 너무 친절하시고 빵도 맛있네요ㅋㅋㅋ카페라떼도 맛있어요ㅇㅅㅇ 종종 방문해야겠어요 잘 먹고 갑니다~~!짱짱맨', 13, 1, 'GOOD', SYSTIMESTAMP);
