INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '빵 종류도 진짜 다양하고 다 맛있어요!! 커피랑 같이 먹으면 극락-☆ 카페 내부도 널찍하구 깔끔해서 좋아요.ㅎㅎ 2층에도 자리가 있어서 자리 걱정 없이 갈 수 있는 곳❤️ 단골빵앗간 예약이용!!', 31, 0, 'GOOD', SYSTIMESTAMP);
