INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '올때마다 늘 감탄하구 갑니다 ㅜㅜ 사장님 너무 친절하시구 먹어봤던 소금빵 중에 여기가 최고에요! 남편이 맨날 오자구 하네요 ㅠㅠ 잘 먹구 갑니당💕', 89, 13, 'GOOD', SYSTIMESTAMP);
