INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '빵 종류도 많고 오늘밤 반달빵 진짜 맛있어요!! 커피도 맛있고 분위기도 좋고 감자치즈치아바타도 담백하니 커피랑 잘 어울렷어용😊😊', 64, 16, 'GOOD', SYSTIMESTAMP);
