INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '비오는 날 연남동에서 우연히 발견한 카펜데 진짜 맛잇네요!! 오늘밤 보름달 진짜 맛있고 빵이 녹아내려요. 빵이 다 팔려서 아쉬우니 담엔 일찍 올게요😖', 60, 15, 'GOOD', SYSTIMESTAMP);
