INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '홍대 온 김에 식빵 사러왔는데 특별한 메뉴도 많고 인테리어도 이쁘고 카페 분위기도 너무 이뻐요 ~~🩷 다음에 또 홍대오면 방문 예정!!😆', 119, 25, 'GOOD', SYSTIMESTAMP);
