INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '홍대입구역3번 출구에서 엄청 가까워서 찾기 쉽습니다. 매장도 깔끔하고 아늑한 분위기라 매장에 있는 동안 마음이 편안했어요🎵 여기 빵들은 당일 생산, 당일 판매가 원칙이라 다 신선해요! 저는 오늘밤 보름달 강추합니다. 재료를 아끼지 않고 듬뿍듬뿍 넣어서 보통의 맘모스빵과는 레벨이 달라요. 크림 치즈, 밤, 앙금 등 정말 아낌없이 들어갔어요. 정정 - 크림치즈 아니고 우유버터크림😁 에그타르트, 스콘도 많이 달지 않아서 너무 만족스러웠어요. 특히 스콘은 약간의 산미가 느껴지는 커피와 정말 잘 어울립니다. 홍대에서 꼭 가봐야할 빵집중의 하나라고 생각해요. 위에서도 언급했지만 대중교통 접근성이 좋아 약속 장소로도 그만입니다. 홍대 베어스덴은 베이커리❣️ 꼭 한번 방문 해 보세용🐻', 35, 5, 'GOOD', SYSTIMESTAMP);
