INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '빵 종류가 많은게 맘에 들어서 방문하게 됐어요 치아바타는 부드러웠고 맘모스도 맛있었어요! 담에 또 오면 그 때는 다른 메뉴도 도전해봐야겠네요ㅎㅎ', 47, 7, 'GOOD', SYSTIMESTAMP);
