INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '빵 종류가 엄청 많아용 인기메뉴로 골라서 먹었는데 전부 맛있어요!! 에그타르트가 부드럽고 크고 맛있습니당 여기 특제 커피인 베베슈페너가 달달하고 부드럽고 맛있습니당', 115, 23, 'GOOD', SYSTIMESTAMP);
