INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '지인 분이 허니바게트를 사다주셨는데 너무 맛있어서 지나가는 길에 들렀습니다. 허니 바게트와 뺑스위스 달지도 않고 너무 맛있어요!! 꼭 드셔보세요👍🏻😀', 31, 6, 'GOOD', SYSTIMESTAMP);
