INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베어스덴베이커리'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '빵 종류가 너무 다양해서 고르다가 기절하는 줄 알았어요😇 그중에 고른 제철맞은 딸기가 들어간 딸기젖소! 달콤한 게 너무 맛있어요☺️ 맛있는 빵이랑 음료 드시러 베어스덴베이커리 오세요🩷 여자사장님 너무 예쁘고 친절해요…🩵 2024년 대박나세용🐲🐉🍀', 26, 5, 'GOOD', SYSTIMESTAMP);
