INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '카페도 너무너무 이쁘고 음료도 맛있고 디저트도 완전 맛있어요!! 생크림이 하나도 안 느끼하고 완전 맛있는 생크림이라 만족스러웠습니다 🫶🫶🫢🫢 카페도 피규어 완전 많아서 눈이 즐거워요!! 이쁘고 멋있어보이는 피규어가 많아서 잘 구경하고 왔습니다!! 추천해용 👍👍', 42, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '애니 마블 피규어 건담까지 키덜트 천국인 홍대 카페공간!! 귀멸의칼날 마블 히어로즈 고담시티 조커 피규어 건담까지 키덜트들 아지트라고 유명할만하고 내부가 진짜 쾌적하고 넓어서 힐링하기 딱 좋아용ㅎㅎ 케이크랑 음료, 시그니처 메뉴들까지 선택지가 넓어서 좋고 다 맛있어요ㅎㅎ 케이크도 사계절 테마로 만드신만큼 맛과 제철과일이 잘 어울렸고 재료도 아낌없이 넣어주셔서 좋아용ㅜ 피규어 구경하다가 디저트로 당충전하고 사장님이 친절하셔서 힐링까지 하다 갑니당~ 최고임ㅜ', 46, 2, 'GOOD', SYSTIMESTAMP);
