INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '카페공간 홍대점 홍대/상수역 올때마다 또또간집 취향저격 카페입니다 :) 매장 들어서는 순간 아기자기한 피규어와 감성 있는 인테리어에 진짜 감탄스럽구 눈호강하고용. 음료와 디저트까지 전부 기대 이상이었어요. 모든 케이크를 직접 매장에서 만드신다고 하시던데, 특히 망고케이크는 진짜 맛이 미쳐서 한 입 먹자마자 ‘아 이건 포장해가야 한다’ 생각이 절로 들었어용.. 모두에게 맛보여주고 싶음 진짜 ㅠㅠ 부드러운 크림과 달콤한 망고가 입안에서 촉촉하게 어우러져 행복 그 자체였어요. 자리도 넓고 조용해서 수다 떨기에도 좋고, 사진 찍을 포인트도 많아서 시간 가는 줄 모르고 즐기다 왔네요 피자도 최근에 개시하셨는데 건강하고 맛있었어유🤍 갈릭소스랑 찰떡쓰 ㅎㅎ재방문의사 1000%입니당 ~~', 14, 0, 'GOOD', SYSTIMESTAMP);
