INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '유튜브 보고 찾아왔는데 정말 실물이 더 레전드입니다,,,🥹 눈이 너무너무 즐거운데 커피까지 맛있어요 ㅠㅠ 퀄리티 정말 너무너무 좋고 휴식할 맛이 납니다!! 피규어 좋아하시는 분들 꼭 한 번 들러보시길 추천드립니다 :)', 54, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '맛있어서 또왔어요 벌써 두번째 방문이에요 매장 내에 피규어들이 짱 많은데 자주 배치를 바꾼다고 하시더라구요. 그래서 보는 즐거움이 새롭습니다! 커피나 음료 재료들이 다 신선하고 좋아요 꾸덕하니 맛있습니다', 134, 49, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '피규어 유명해서 찾아왔는데 정말 좋은 구경했습니다. 사장님이 여러가지 피규어 전시헤놓으셨는데 구경하는재미가 상당하고 매우 친절하셔서 기분좋게 즐기다 가요^^ 사장님이 이벤트도 여러가지 해서 참여하시면 증정품도 주시니까 방문하면 꼭 해보세요! ㅎㅎ', 5, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '귀칼 정주행하고 한창 덕질하던 중 친구가 추천해줘서 보고 와 이건 와야한다 하고 남자친구랑 맘먹고 온 곳인데 기대 이상..❤️ 진짜 크고 화려한 번쩍번쩍한 피규어 겁나 많고 그냥 공간 자체가 너무 진심이신 곳… ㅋㅋㅋㅋㅋㅋㅋㅋ 좌석도 사이사이 꽤 넓고 구경하기 조아여 걍 귀칼 조아하시면 꼭 오시길….', 35, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '귀멸의 칼날에 빠져서 덕질 중에 전시로 꾸며진 카페가 있다고 해서 방문했어요! 큰 피규어들이 정말 멋있게 전시돼 있어서 눈이 즐거웠어요. 특히나 영화표 인증시 일륜도 코등이도 증정하는 이벤트가 있어서 좋았답니다. 다른 마블이나 F1 등등도 볼 것이 가득하고, 특히 수박주스가 덜 달아서 안 물리고 맛있네요 추천👍', 83, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '진짜 피규어 너무 많고,, 컨셉 너무 좋아요ㅠㅠㅠㅠ취저ㅠㅠㅠ❤️❤️👍 귀칼보고 카페오게 됐는데 진짜 가챠도 주시고!! 음료도 맛있고 케이크 종류도 많아요! 조용하고 볼거리도 많은 카페가 홍대에 있다니 몰랐네요,,, 퀄리티가 대박이에여… 아니 박물관인지 카페인지 디테일 무엇이냐고요!!! 박물관에 온 거 가타요…🔥❤️ 좋은 취미를 갖고 계셔주셔서(?) 감사합니다ㅠㅠㅠ', 11, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '상수역에 이런공간이 있다니🥹 레고나 피규어 좋아하시는 분들은 꼭 가셔야합니다!  전시도 너무 예쁘게 잘 되어 있고 음료랑 케이크도 맛있고 예뻐서 일반 분들도 가시기 좋습니다. 저도 레고나 피규어 세상을 잘 모르지만, 남자친구 데려가니까 너무 좋아하고 고마워하더라규요 ㅋㅋㅋ 테이블마다 있는 레고 꽃이랑 작은 피규어 구경하는 재미도 있고 케이크도 맛있어서 자주 오고싶은 곳입니다💗', 36, 2, 'GOOD', SYSTIMESTAMP);
