INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '오렌지향 커피의 특별한 맛 시그니처 비포선셋 너무 맛있습니다 🥹 커피 잘 못 드시는 분들도 꼭 드셔보세요 🍊☕️🧊 음료같으면서 커피향이 느껴집니다 인테리어도 독특해서 피규어 좋아하시는 분들 방문하기에 너무 좋을 것 같아요 케이크도 너무 부드럽고 크림이 느끼하지 않아 무한 흡입 가능한 맛 🍰 조용하고 분위기도 좋아서 홍대 데이트 장소로 추천드립니다 bb', 29, 1, 'GOOD', SYSTIMESTAMP);
