INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '우연히 릴스로 보고 찾아왔는데 기대 이상이었어요.. 사장님의 애정을 한눈에 볼 수 있습니다. 귀멸의 칼날부터 디즈니, DC, 포켓몬, 짱구, 건담, 레고 등 프라모델까지 눈이 너무 즐거워요 사장님도 너무 친절하셔서 여기 공간에 즐거운 시간을 보낼 수 있었습니다 :)', 29, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '새로 나온 크레이프 케익 넘나 맛있습니다!! 귀멸의칼날 극장판 피규어가 카페에 잔뜩 있어서 신기했어요!! 또한 귀여운 가챠뽑기 이벤트도 진행중이니 많이 참여해보셨으면 좋겠습니다!!', 47, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '피자가 너무 맛있어서 두번째 먹습니다! 사장님이 직접 제작하신 피자라 그런지, 도우부터 토핑 하나하나까지 정성이 듬뿍 느껴집니다. 특히 이탈리아산 도우와 치즈를 사용하셨다는데, 진짜로 한국에서 흔히 접하는 피자와는 완전히 차원이 다른 맛이었어요! 마치 이탈리아 본토의 맛 또한 좋았던 건 양! 사진으로는 감이 안 올 수도 있지만, 둘이서 배부르게 먹고 든든했어요. 이건 정말 여기서만 맛볼 수 있는 특별한 피자입니다', 33, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '피규어카페 카페공간에 다녀왔어요! 카페 안에는 다양한 캐릭터 피규어들이 전시돼 있어서 구경하는 재미가 완전 쏠쏠>< 크고 작고 귀엽고 멋진 피규어들 구경하느라 시간 몰랐고 사진 찍기 좋았답니당 케이크는 상큼달달한 스프링 인 레몬을 골랐어요, 아메리카노는 산미와 고소한 맛 고를 수 있어서 그 점도 만족 힛~* 커피 중 비포선셋 맛있어요! 여름과 잘 어울리는 맛으로 추천드려요👍🏻 조용하고 아늑한 분위기라 여유롭게 쉬다 오기 좋았습니다! 피규어 좋아하는 분들에게 강추!', 15, 4, 'GOOD', SYSTIMESTAMP);
