INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '피규어만으로 인테리어가 되다니.. 들어오자마자 깜놀했어요 커피 기다리는 동안 구경해도 모자를만큼 엄청 많아요! 신기하고 유니크한 피규어들 많아서 매니아라면 흥미롭게 보실 듯.. 커피도 맛있고 디저트도 야무지게 잘 먹었습니다!!', 33, 1, 'GOOD', SYSTIMESTAMP);
