INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '더운날 우연히 발견한 카페! 다른 일반 피규어샵&카페인줄알고 들어갔는데 OMG...고퀄리티 피규어들이 있었어요!! 음료 시키고 한바퀴 보면서 볼 때마다 입이 쩍🫢 음료도 맛있고 눈도 호강하네요! 근처올 때마다 올거에요!', 6, 0, 'GOOD', SYSTIMESTAMP);
