INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '피규어 좋아하는 남자친구 따라왔는데 귀여운 것도 많고 디저트랑 음료도 예뻐서 좋았어요! 엄청 디테일한 1대1 사이즈 아이언맨도 있구 의자에 앉아있는 짱구도 있는데 혼자 오시는 분들 짱구랑 같이 앉으시라고 둔거래요🥲 여태 가본 피규어카페 중에 제일 잘되어있어요👍🏻', 7, 5, 'GOOD', SYSTIMESTAMP);
