INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '남자친구가 귀멸의 칼날 덕후라서 같이 방문했는데 완전 만족했어요! 입구부터 피규어들이 가득 전시돼 있어서 사진 찍기 너무 좋았고, 분위기 자체가 덕후 감성 뿜뿜✨ 디저트도 생각보다 종류가 다양해서 골라 먹는 재미가 있었어요. 맛도 괜찮고 음료까지 예쁘게 나와서 인증샷 필수! 귀멸 좋아하는 분들이라면 꼭 와보셔야 할 곳 같아요ㅎㅎ 저희는 다음에 또 방문하려구요 >.<', 35, 10, 'GOOD', SYSTIMESTAMP);
