INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '사장님의 어마어마한 덕력을 느낄 수 있었어요..! 들어가자마자 귀칼 피규어 보고 짜릿했네요 잠깐 근처에 볼 일이 있어 앉아서 커피 마실 곳이 필요했어요. 아메리카노 한 잔 사 먹었는데 원두를 좋은 걸 쓰시는지 맛있었어요 :) 다음에 합정/홍대에 볼 일 있으면 재방문해야겠어요', 44, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '피규어가 있는 이색카페가 있대서 와봤는데 너무 신기하네요!! 볼거리도 많고 카페 음료 맛도 좋아서 시간 너무 재밌게 즐기다 갔어요~ 카페 공간도 넓고 좌석간 간격도 넓은 편이라 편안하게 시간보내기 너무 좋습니다ㅎㅎ 홍대오면 또 놀러갈려고요~', 9, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '얼그레이 아이스티 마셨는데 진짜 지금까지 마셔본 아이스티중 top3 안에 듭니다!! 시그니처인 비포선셋도 정말 맛있어요!! 계절을 컨셉으로 한 케이크도 너무 좋구요!☀️ 그리구 무엇보다 덕후의 심장을 울리는 다양한 피규어들의 인테리어가 심장을 뛰게 하네요ㅠ 마블, 귀칼, 레고, 포켓몬, 짱구 등 다양하게 많아서 구경할 수 있어서 너무 좋아요! 저도 갖고시퍼져요', 39, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '❣️피규어카페가 홍대에도 생겼다 해서 예약하고 방문했는데요 와..! 피규어가 엄청 다양했어요!! 레고,건담,디즈니,어벤져스,짱구 등등 피규어 무료전시에다 매장도 넓어서 보는재미, 먹는재미가 있어요 신메뉴로 ''마르게리따'' 피자와 음료를 먹으면서 즐기니 더욱 좋았어요~ 커피와 케잌까지 디저트로 먹으면서 여유롭고 맛있고 즐길 수 있었어요~~ 사장님이 친절하시고, 피규어에 진심인걸 느낄 수 있었고요 설명도 잘해주셔서 도슨트 듣는 느낌이라 더욱 좋았답니다!!😁❣️', 41, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '첫 방문이었는데 신기한것도 많고 볼거리도 많아서 좋았어요!! 매장도 너무 깔끔하고 친절하고 커피랑 케이크도 부드럽고 너무 맛있었어요!', 33, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '세상에~~  홍대에 이런 곳이 있었다니... 진작 알았으면 친구들과 더 자주 방문 했을텐데 이제라도 알게 돼서 너무 다행인? 👍 인테리어를 사진으로만 봐도 넘나 멋지다는게 느껴지는 이곳은 친절하신 사장님과 멋진 피규어들을 한곳에서 감상할 수있는 굉장히 특별한 카페였어요. 무엇보다 음료와 디저트를 맛보고 두번 눈이 감기며 감격 또 감격 받았다는건 안비밀요~~^^ 재방문 의사는 당연히 있고요. 멋진 사장님께서 오래오래 운영 하시고 사업 번창하셔서 많은 분들이 즐길수 있는 공간이 되길 바래요~^^', 63, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '피규어가 정말 다양하게 전시되어 있어서 보는 재미가 가득한 매장이었어요. 캐릭터별로 정리도 잘 되어 있어서 구경하기 편했고, 희귀한 제품들도 많아 눈이 휘둥그레졌습니다. 덕후라면 꼭 한번 방문해볼 만한 곳이에요. 가격도 합리적인 편이고, 피자도 맛있었어용!', 24, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '사장님이 너무 친절하시고 메뉴도 하나하나 설명해주셔서 너무 좋았어요! 무엇보다도 피규어가 고퀄리티라 눈호강이 짱이고 전시회에서 즐기는 기분이었습니다!💜 배가 너무 불러서 디저트는 못먹었는데 디저트들이 다 마있어보이고 신기한 디저트들도 있어서 신기했어요! 다음에 방문할땐 꼭 디저트도 먹어볼까합니다! 커피는 말할것도없이 고소하고 커피향이 너무 잘맞아서 좋았습니다🥰', 82, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '신랑이 키덜트족이라 카페공간 홍대점 방문하였어요 아이도 함께하였는데 곳곳에 피규어와 레고 구경할게 많았고 음료도 너무 맛있었어요 대표 시그니처 메뉴인 비포선셋 주문하고 너무 예쁜 바다라떼 그리고 아이는 청포도 에이드로 주문했는데 눈과 입이 호강하네요 사장님께도 궁금한점 질문하니 하나하나 친절하게 답변주시고 기분이 좋네요 홍대오시면 방문해보세요^^', 10, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '지인 추천으로 방문했어요. 매장 조명과 음악이 편안한데 사장님께서도 정말 친절하셔서 분위기가 너무 좋았어요! 음료도 독특하고, 멋지고 귀여운 피규어로 잘 꾸며져 있어서 시간가는 줄 모르고 구경했습니다😀 쉽게 보기 힘든 인테리어라서 직접 방문해보시기를 추천드려요~! ※ 테이블마다 짱구 캐릭터가 있는데 제일 귀엽습니다ㅋㅋ', 93, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '친절한 카페 재방문했어요 ㅎㅎ 케이크 종류가 바뀌었길래 시켜봤는데 달지않고 맛있어요! 피규어가 언제와도 넘 멋있어요 눈이 즐거워요 조용하고 시원해서 이야기하기도 좋아요', 16, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '잠깐 머물 카페를 찾으려다가 발견했는데 이정도로 좋을지는 몰랐어요ㅠ 진짜 감성도 넘 좋고 피규어들도 엄청 이뻐요💗 둘러보면서 힐링하기도 좋고 오자마자 정말 오기 잘했다고 생각했어요! 다음에 기회가 된다면 무조건 또 올겁니다🥹 대만족이요👍💖', 36, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '들어오는 순간 피규어 박물관에 온 것 같은 기분이었어요!!! 입장료 없이 음료만 마셨을 뿐인데 이런 수많은 피규어들을 볼 수 있어서 너무 좋습니다! 특히 마블팬들과 귀칼 덕후들은 오면 눈이 돌아갈 겁니다... 개인적으로 홍대 오타쿠 투어에서 카페 공간 꼭 들려보시는것도 좋을 것 같아요!!!! 음료 가격도 착하고 맛있습니다!!!', 21, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '귀멸의칼날 피규어 잇다고 해서 와봤는데 진짜 멋있어요!! 다른 피규어 전시해놓으신것들도 퀄리티가 넘 좋아서 보는 재미가 있었습니다!! 신기한 메뉴들도 많고 커피도 맛있어요 :-)', 31, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '와 피규어 구경하려고 홀린듯 들어왔다가 즐겁게 있다갑니다 어떻게 이렇게 사장님이 피규어를 모으신건지..!! 너무 멋진 피규어랑 레고들이 많아서 넋놓고 보다가 겨우 정신차렸습니다 ㅋㅋ커피도 너무 맛있고 계절별로 케이크 컨셉이 있어서 가장 이뻐보이고 맛있어 보이는 썸머 인 그린 케이크도 먹었어요~ 피규어 레고 좋아하시는 분들 강추입니다 토니 스타크랑 헐크 흉상이 미쳤어요..!', 4, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '홍대에 음료 주문만 해도 엄청난 피규어 구경이 가능한 키덜트의 새로운 랜드마크기 생겼다고 해서 와봤다!! 이야~ 피규어, 프라모델, 레고, 가챠까지 볼게 많았고 분위기 차분하고 음료도 맛있어서 대 만족!!! 홍대를 왔다면 키덜트든 아니든 꼭 한 번은 와보시길. 강추!!', 107, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '음료도 맛있고 피규어도 맛집입니다ㅎㅎ 어벤져스 듄 귀멸의칼날 짱구 디즈니 등등 피규어가 다양하게 있어서 입도 즐겁고 눈도 즐겁고 즐거워요 ^^b', 48, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '짱구가 도와주는 짝궁과의 데이트!!! 케이크 퐁실퐁실 너무 맛있고, 무엇보다 이 카페의 인테리어가 각종 피규어로 대박이랍니다!!! 다들 꼭 한번 오셔서 진짜 대박 피규어들 보고 가세요!!! 물론 커피랑 케이크는 맛이랑 미 둘다 잡았어요!!', 37, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '다리가 아파서 근처 카페에 왔는데 🤩 개멋진 카페네요~😱 사장님 되게 친절하시고 마블,귀칼,레고피규어들이 잔득있었는데~ 다 제가 좋아하는것들이여서 구경하는것도 정말 즐거웠어요~~🙆🙆 커피랑 케이크는 당연히 맛있었구요 제가 시골학생이라 여기 자주 못오는데 어른이 되어서 서울 멋쟁이가 된다면 여기 단골이 되고 싶네요~👀💁 정말 좋은곳이에요~~🐴', 6, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '한태산 생일 카페 돌고 점심 겸 커피 마시기 위해 방문했는데 고양이 티스푼과 티슈를 발견해서 기분이 좋았는데 피자 스몰 사이즈인데도 양이 많아서 배부르게 잘 먹었고 커피랑 음료 둘 다 맛있었어요!! + 내부 전시가 찐이에요. 사진을 다 찍진 못했지만 사장님의 진심이 느껴지는 남다른 클라스. 애니메이트 뺨치는 수준 디져트도 너무 맛있어보였는데 배불러서 못먹은게 너무 아쉬워서 다음 재방문 때는 디져트까지 뿌셔보겠습니다💓 또 저는 화장실 매우매우 중요한 사람인데 깔끔해서 좋았습니다.', 55, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '여긴 카페가 아니고 박물관이에요..... 홍대에서 대박인곳이에요!!!!!! 데이트하러 꼭 오세요!!!!❤️❤️❤️❤️ 피자 너무 맛있고 이태리 맛이에요!!!!!', 17, 2, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '공간이 너무 매력있는 카페 공간입니다! 키덜트라면 무조건 좋아할 수밖에 없는 곳이에요🥹 피규어에 대해 잘 모르는 저도 많은 피규어들을 구경하고 관람하며 감탄이 절로 나온 곳이었습니다! 자리에 짱구와 레고 화분을 두어 세심한 부분까지 정성스럽게 꾸며져있는 모습이 너무 좋았고 사장님께서 진심으로 이곳을 운영하신다는 게 느껴질 정도로 친절하게 음료나 피규어에 대해 설명해주시고 자리를 살펴주셔서 너무 기분 좋게 카페를 즐길 수 있었어요!! 다음에 친구들과 또 오고싶은 곳입니다 🤍', 22, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '갤러리형 피규어 카페라고 하길래 귀여운거 생각하고 왔다가 완전 멋있어서 반하고 가요!! 입장료 없고 음료만 마시면 되는데 이색카페나 데이트하기에도 넘 좋더라구요♡ 추천드려요', 465, 58, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '여기 진짜 멋져요!!!!!!!!! 입장료 없는게 말이 안돼요!!!! 아이언맨 진짜 리얼 그자체 사장님이 피규어 진심인게 느껴지고 엄청 친절하세요! 디저트도 다양하고 맛있고 볼 거 진짜 많아요! 홍대에 이색데이트로 무조건 추천이에요👍👍👍', 18, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '홍대 상수역 근처에 있는 키덜트 카페 공간에 방문했어요!! 일단 카페 안에는 피규어 박물관에 온 것처럼 눈이 휘둥그레지는 찐고퀄 피규어가 쭉 전시되어 있어요...! 하나하나 구경하다보면 시간이 후딱 갑니다 ㅎㅎ 귀엽고 아기자기한 가챠, 레고부터 실제보다 더 실제 같은 흉상피규어까지... 커피 마시다가 눈 마주칠 수 있습니다 😆 커피도 맛있고 무엇보다 디저트 맛집이에요! 케이크 달지 않고 과일도 신선하니 아주 맛있었습니다 😋 피규어도 계속 바뀐다고 하니 또또 방문하고 싶어요!', 1, 2, 'GOOD', SYSTIMESTAMP);
