INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '진짜 너무 이뻐요... 갖고싶은 피규어 여기 다 있어요... 여기 살규싶어요 거기다가 커피도 맛이고  복숭아 케이크 꼭 드세영!', 3, 0, 'GOOD', SYSTIMESTAMP);
