INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '좋아하는 캐릭터들을 한자리에서 볼수 있다니😃😄 키덜트 덕후들의 천국이에요,, 케이크랑 커피도 맛있고 제 남편들도 여기 있네요,,, ㅎ ㅎ 켘 귀칼 , 마블 , 디씨 다양하게 즐겨보아용', 27, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '매장입장하자마자 우와 여기 진짜 멋있다라는 감탄사가 나왔고 테이블마다 짱구 피큐어가 있어서 너무 귀여웠어요! 메뉴구성 특이하게 케이크가 계절별로 되어있더라고요!! 많이 안 달고 맛도 좋고 설명해주셔서 좋았습니다:) 시그니처 커피도 독특하고 오렌지 쥬스에 커피를 첨가한 느낌이 맛인데 여기를 가시면 한번쯤 드셔보시면 좋을 거 같아요!!', 34, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '잠깐 커피 마시러 들어왔는데 놀랐습니다!!! 카페가 각종 피규어로 가득 차있습니다. 사장님 취향을 확실히 알 수 있는 피규어들이네요ㅎㅎ 저도 귀멸의칼날 좋아합니다🥹 음료 마시는 것도 잊고 엄청 구경했어요!! 케이크나 에이드청도 직접 만드시는 것 같습니다. 입과 눈이 모두 즐거운 카페입니다ㅎㅎ', 53, 13, 'GOOD', SYSTIMESTAMP);
