INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '사장님이 엄청 친절하세요 커피가 고소하고 디저트도 예뻐서 좋았어요 피규어들이 잘 관리되어 있어서 보는 즐거움이 있었습니다 너무 멋있어서 또 놀러오려구요', 49, 1, 'GOOD', SYSTIMESTAMP);
