INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '홍대에 이런 카페가 있는 줄 전혀 몰랐네요 ㅎㅎ 너무 시원한데 이색데이트로 완전 딱이에요!! 자리마다 귀여운 피규어도 놓여있어서 너무 기분좋고 케이크도 넘넘 맛있고 특히 비포선셋 완전 맛있었답니당!!!', 90, 15, 'GOOD', SYSTIMESTAMP);
