INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '카페공간 수제피자 완전 강추합니다!! 도우부터 맛이 다릅니다 완전 이탈리아의 맛! 양도 많아서 먹다가 배 터지는줄 여태 먹어본 피자중에 가장 맛잇엇습니다 다들 꼭 드셔보세요', 55, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '단순한 카페가 아니라 진짜 문화 공간이에요!! 🎨🍰 케이크도 직접 만든 거라 디테일부터 감동 그 자체💖 심지어 피규어 하나하나가 1:1 사이즈, 1:3사이즈 가격대도 300-700만원대… 거의 작품 수준이에요🔥 안에 들어가면 그냥 ‘카페 왔다~’가 아니라 레고, 짱구, 귀칼, 드래곤볼 같은 누구나 좋아할 만한 피규어들이 전시되어 있어서 거의 피규어 박물관 같은 느낌!? 컨셉도 완전 제대로 잡혀있고, 8개월마다 테마도 바뀐다니 다음 방문이 더더 기대돼요🧡 그리고 뭐니뭐니 해도..친절도 맥스!!! 직원분들 진짜 친절해서 처음 간 사람도 마음 편하게 즐길 수 있어요✨감성+즐거움+맛까지 한 번에 즐길 수 있는 곳! 완전 강추입니다💯💯 재방문 의사 500%(진심)', 463, 91, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '국내 단 4개뿐인 아이언맨 로다주 상체 피규어 미쳤습니다... 들어갈 때부터 기깔난 대형 피규어들에 정신을 못 차렸어요 마블 시리즈 피규어에 귀칼 메인 캐릭터들의 기술 피규어, 유명한 렌고쿠와의 맞대결 피규어, 각종 건담, 짱구, 포켓몬, 레고 등 진짜 너무 즐기다 갑니다 커피도 시그니처로 직접 만드시고 제철 과일로 사계절을 표현한 케이크들은 침이 주르륵 흘렀어요,,, 커피를 못 마셔서 비포 선셋은 못 마셨지만 그래도 어텀 인 얼그레이 케이크는 너무 맛있었고 혼자 왔다고 짱구 피규어를 반대편에 앉혀주신 것도 너무 센스 넘치고 좋았습니다 ㅠ 더운 여름인데 에어컨도 빵빵하고 거의 각 테이블마다 공업용 선풍기를 바닥에 깔아주셔서 너무 너무 시원했어요 👍 다음에 또 가겠습니다 ㅎㅎ', 6, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '피규어가 전시되어있어서 더 독특한 카페 같아요 ㅎㅎ 이색카페 체험하시고 싶을 때, 뻔한 카페말고 컨셉있는 곳을 가고싶을 때 강추드려요!! 케이크도 계절별 4가지 케이크 있는데 겨울맛 케잌 넘 맛있었어요 ㅎㅎ 음료도 존맛탱이었답니다 ! 큰 피규어들도 많아서 보는 재미가 있었네요 ~~', 34, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '너무 즐거웠던 키덜트 갤러리 피규어 카페🖤 너무 더울때 실내에서 놀거리 항상 고민했는데 앞으로 여기로 올꺼 같아요! 높은 퀄리티의 피규어와 다양한 메뉴의 카페까지 아이부터 어른까지 남녀노소 모두가 좋아할 카페인거 같아용😘 사장님도 넘 친절하셔서 힐링한 하루였습니다 👍🥹', 21, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '다양한 피규어들이 많아서 피규어 박물관에 온 기분 입니다! 입장료도 따로 없이 1인 1메뉴에 이렇게 관람할수 있다니 사장님 남는게 있으신가요?!!! 피규어를 잘 모르시는분도 진짜 우와 대박~ 소리가나오는 인테리어였습니다!', 22, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '귀멸의칼날 무한성편 관람 후 카페방문하면, 귀칼 굿즈를 주는 이벤트가 진행중이라고 합니다!! 굿즈도 받고 귀칼 피규어도 구경하고 일석이조!!', 9, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '홍대에 딱 맞는 카페🥰🥰 구경하는 재미도 있고 디저트들도 다양하고 너무 귀엽고 멋지고 맛까지 있어요🔥 짱짱추천합니닷 커피도 산미있는거랑 고소한거랑 둘중에 선택할 수 있어서 매우 좋습니닷', 20, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '바치케 먹고싶어서 찾아왔는데 매장 넘 이뻐요 귀엽고 신기한 피규어들이 많아요!! 그리고 디저트 종류도 많아서 자주 올 것 같아요❤️', 16, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '진짜 실물같은 아이언맨이 있어요! 피규어 천국이고 음료도 맛있고 디저트도 직접 만드셔서 그런지 더 맛나는거 같아요! 건담, 어벤져스, 귀멸의 칼날, 짱구, 레고 등 다양한 피규어들을 보실 수 있어요! 자리에 작은 레고와 짱구가 얼마나 귀여운지 모릅니다 ;) 항상 같은 피규어가 있는게 아니고 계속 추가되고 바뀐다구 하시더라구요. 실물같은 어벤져스를 눈으로 직접 만나보세용!!', 13, 6, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '케익도 너무 맛있고 비포선셋 이라는 오렌지 커피 처음 맛 보았는데 색다른 커피를 즐길 수 있었어요 무엇보다 피규어가 너무 멋있어서 시간가는 줄 모르고 쉬다 갑니다 카페공간 강력추천 합니다.', 27, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '홍대피자는 여기입니다. 실제 로다주도 보고 진짜 박물관테마의 음식점. 데이트하기 좋았어요. 그리고 사장님이 챙겨준 서비스덕에 여친도 자주 와도 된대요!! 감사합니다.', 76, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '직원들이랑 왔다가 너무 좋아서 주말에 남동생들과 왔어요!! 음료 넘 예쁘지 않나요ㅎㅎ역시 반응이 뜨거워서 뿌듯했어요ㅋㅋ 사장님이 너~무 친절하시고, 피규어에 대한 자부심이 넘치시고 설명도 잘 해주셔서 즐거운 시간이였어요! 마포구의 명물이 되길🙏🙏', 16, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '짱구를 좋아하는 아이가 가보고 싶다해서 왔늠데 제가 더 좋았어요. 희귀템들도 많고 특히 아이언맨은 국내에 몇 개 없다고 하는데 눈썹 한 올 한 올 모공 하나하나까지 얼마나 정교한지 한참을 들여다봤어요. 남편과 한 번 더 와보려구요. 음료도 상큼하니 맛있었어요.', 53, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '피규어 구경하는걸 좋아하는데 가본곳중에 가장 피규어가 많고 사실적이어서 시간 가는 줄 모르고 구경했습니다 테이블마다 귀여운 짱구랑 화초 피규어도 너무 이뻐요 . 신기하게 구경하고 있으면 사장님이 설명도 해주시도 엄청 친절하세욥 유튜버들도 많이 왔다갔더라고요. 사장님이 관리하는데 공을 많이 들이시는 태가 납니다.커피도 맛있고 수박주스 완전 생과일말고 암것도 안들어있어서 너무 맘에 들어용 생수박 조각도 들어간데는 첨 봤어요!!😲', 2, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '어벤져스 아이언맨 피규어가 실물사이즈로 있어서 너무 신기해요. 진짜 리얼해서 앞에 사람이있는것같은 느낌이랄까. 커피도 마시고 색다른 구경도 하니 너무 재밌네요. 리뷰하시면 가챠뽑기도 할수있어서 굿이랍니다', 0, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '와~~~피규어 박물관 토이 천국~♡ 퀄리티 느므느므 높네요~~~예술 작품 잘 감상하고 갑니당~ 딸기라떼 너무 맛있고 케익도 맛있습니다~♡ 최고 👍', 25, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '유투브 보고 한 번쯤 와보고 싶다고 생각했었는데, 마침 근처 지나가다 들렸어요! 근사한 피규어들도 구경하고 더운 날씨에 쉬어가며 보낼 수 있는 곳이에요! 사장님께서 정말 이쁘게 내부를 꾸미고 깔끔히 정리도 해두셔서 동선이동도 편하고 피규어 구경도 넘 잘 하고 갑니다!~~😀', 457, 42, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '사자비 보려고 왔는데 엄청나네요 다른 영화 애니 f1 피규어도 멋지게 전시되어 있어서 재밌게 구경했어요 피규어 보려고 갔는데 커피 케이크도 맛있어서 정말 만족스러운 시간 보내고 갑니다!!', 16, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '레고와 건담, 피규어가 있는 카페가 홍대에 있다고 해서 찾아왔어요! 입구부터 전시품들이 보이는 게 너무 멋있었고, 들어오니 사장님이 친절하게 맞이해주셔서 기분이 좋았습니다! 음료는 저렴한 가격인데 너무 맛있었고 밥 먹고 방문했지만 쿠키 가격이 착해서 구매했습니다ㅎㅎ 전시품이 많아서 볼거리도 많고 그 사이에 앉아서 음료 마시는 것도 특색있고 좋았어요! 레고랑 메탈스트럭처는 탐날 정도로 웅장하고 멋있네요 기분 좋은 방문이었습니다🫶', 74, 11, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '다양한 피규어를 단독 전시장을 통해 보게 되니 피규어들이 더 빛나고 멋져보입니다. 평일에 왔는데 한적하고 너무 좋네요. 사장님의 짧은 설명도 너무 좋고요. ☆바다라떼 너무 예쁘고 맛있어요☆', 5, 1, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '지나가다 들렀는데 이런 보물같은 곳을 발견하다니 넘 좋아용 딸기라떼 크림이 진짜 맛있었어요 맥주도 조은가격 좌석마다 레고 꽃 있어요 네이버 리뷰 보고 제 장르 없는것 같아서 기대 없이 왔는데 생각보다 1억배 재밌었어용 ㅠ 피규어랑 인테리어 계속 업데이트 하시는것같아용 자주 올래요♡︎', 110, 19, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '고퀄피규어에 눈돌아갑니다 ˗ˋˏ 멋지다 ˎˊ˗ 라떼도 진하고 맛있어요.ᐟ  바스크치즈케이크도 꾸덕허니 끝장나는 맛👍 오늘 귀칼보고 한 번, 맛있어서 두 번 울고갑니다ㅠ', 30, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '귀멸의칼날 디오라마, 마블ㆍDC, 레고, 영화 등 다양하고 멋있는 피규어와 함께 할 수 있는 카페입니다. 2층이라 뷰도 좋아요. 아메리카노와 오렌지를 블렌딩한 음료는 목넘김도 좋고 새롭고 맛있었어요. 큰 피규어뿐 아니라 작은 소품까지도 신경 쓴 사장님의 진심이 느껴지는 카페입니다. 데이트, 취미 장소로 추천해요!', 32, 7, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '피규어가 너무 멋있어요!! 고가의 피규어들을 이렇게 음료를 즐기는 것만으로도 관람할 수 있다는게 너무 행복하네요!!!! 심지어 음료도 너무 맛있어요 ㅜㅜ 사장님 제발 오래오래 해주세요!!', 34, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '소문 듣고 찾아 왔는데 카페에 많은 피규어들이 있어서 아이가 참 좋아하네요. 쉽게 보기 힘든 파규어도 많아 좋았어요. 마지막으로 맛있는 아이스아메리카노와 함께 하니 분위기도 있어 매우 좋았습니다. 참, 사장님이 너무 친절해요!', 42, 3, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '아들하고 피규어 가게 돌다가 타이타닉보면서 어 저기 피규어 카페인듯 오니 그냥 기분 좋고 케이크 맛집이네용 멀리서 왔어용 사장님 대박나시고 테마 바꿔어지면 공지 해주세용 ㅋ 기다릴께용', 40, 0, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '귀칼 피규어 많고 그 외 멋진 피규어가 많아요!! 이렇게 좋은 퀄리티의 피규어를 볼 수 있는 카페라니 !! 너무 좋은 것 같아요…🫠 음료도 너무 맛있고 사장님도 친절하십니당 ㅎㅎ 담에 또 올거같아요!!', 109, 25, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '남편이 건담프라모델을 좋아해서 가고싶다고해서 방문했어요. 리미티드에디션도 있고 피규어도있고 정리가 잘되어있어서 보기좋네요. 주인분도 친절하세요. :)', 41, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '시그니처 커피도 맛있고 무화과 케이크도 맛있어요! 가챠도 할 수 있고 대형 고퀄 피규어도 정말 많아서 눈도 즐거워요 너무 좋은 곳인 것 같아요!', 76, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '산책하다가 창가의 멋진 배 모형을 보고 들어왔어요. 사장님의 컬렉션 스케일이 어마어마 합니다. 간단하게 아이스아메리카노 마셨는데 커피도 맛있고 스장님도 너무 친절하세요. 가게 분위기도 너무좋구요~~!! 다음에 친구들이랑 또 오겠습니다!!', 6, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '피규어가 너무 압도적이어서 눈이 계속 머물렀어요!! 하나하나 디테일이 살아있어 덕후심을 제대로 자극하더라고요ㅎㅎ 분위기만 좋은 게 아니라 음료, 음식, 케이크까지 전부 기대 이상으로 맛있었어요. 특히 케이크는 달지 않고 부드러워서 끝까지 맛있게 먹었고, 음료도 메뉴마다 개성이 느껴졌어요. 멋진 피규어 감상하며 맛있는 음식까지 즐길 수 있는 곳이라 오래 기억에 남을 것 같아요❤️', 24, 4, 'GOOD', SYSTIMESTAMP);
