INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '친구랑 방문했는데 피규어가 진짜 많아요! 키덜트를 위한 천국♥ 마블이랑 에프원 좋아하는데 관련 피규어,레고도 있어서 넘 반가웠네요 특이한 카페 찾으시는분 꼭 여기 와주세요!', 114, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '피규어 구경하러 왔다가 음료랑 디저트 맛에 더 감탄함 카페의 본질에 엄청 충실한 공간이에요!! 나만 알고 싶지만 번창하셔서 더더 많은 피규어 들여놔주셨으면 좋겠어여ㅋㅋㅋㅋㅋ자주자주 오고 싶은 좋은 곳입니다.', 32, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '홍대에 피규어 구경하러 방문하였습니다! 사장님도 너무 친절하시고 무엇보다 디저트와 커피가 너무 맛있었네요 ㅎㅎ 볼거리도 많고 데이트코스로 좋은것같아요~😊', 35, 2, 'GOOD', SYSTIMESTAMP);
