INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '피규어맛집인줄은 알았지만 케익도 너무 이쁘고 맛있잖아요 😆😆💛 구경하는재미 먹는 재미가 너무 좋습니다! 디저트 맛집이니까 케잌꼭 드세여 케잌 색감 넘 이쁘고 적당히 달아서 맛있는 그느낌입니다!', 8, 7, 'GOOD', SYSTIMESTAMP);
