INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '공간과 음료 모두 정성이 가득하다고 느껴졌어요 흔치않은 분위기가 너무 좋아요 그리고 아이들이 너무 좋아할  만 하고 피규어 까지 볼수있어서 정말 좋아요 또 피규어가 한 종류가 아니라 여러 종류 여서 질리지도 않고 너무 좋습니다', 69, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '남편하고 카페공간을 처음 방문했는데 입구 들어서자마자 다양한 피규어들이 너무 화려하게 있었고, 사이즈도 큰 피규어도 있어서 피규어 박물관에 온 느낌이었어요. 제가 마블에서 아이언맨 좋아하는데 아이언맨이 멋지게 자리를 잡고 있어서 계속 보게 되었어요^^ 그리고 테이블이 피규어 쇼케이스 사이 사이에 있어서 더 기분이 좋았어요!!', 19, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '사장님이 정말 친절하시고 음료가격도 착하고 더군다나 맛도 맛있습니다. 가게안에 멋진 피규어둘과 레고들도 많아서 구경하기 좋습니다. 좌석도 넓게 편안하게 배치되어있어 편안하게 쉬다갈 수 있어요. 감사합니다.:)', 118, 22, 'GOOD', SYSTIMESTAMP);
