INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '레고와 피규어를 좋아하는데 지나가다 마침 있어서 들렀어요! 멋진 피규어들이 많고 정말 멋져요! 음료도 맛있어요! 근데 정말 멋있네요ㅎㅎㅎㅎ', 34, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '지나가다가 보고 기대없이 왔는데 진짜찐짜 너무너무 볼거리가 많아서 눈돌아가요! 사장님도 친절하시고 설명도 해주셔서 더 재밌게 구경했습니당 !!!! 커피도 맛있고 케이크도 리뉴얼 된다고 하니까 홍대오시면 꼭꼭 와보세용 레고는 점점 더 많아진다고 하셔서 저는 또 오려구요! 강추합니당 진짜 멋있는 레고랑 피큐어 커스텀제품들 진짜많아요', 116, 22, 'GOOD', SYSTIMESTAMP);
