INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '일단 궁금했던 피규어들을 실물로 볼수 있었던게 너무 좋아요 그리고 무엇보가 피규어랑 장식 때문에 음료랑 디저트는 별로 인곳들도 많은데 여긴 음료도 디저트도 맛있어요!!! 특히 케이크는 직접 만드시는것 같아요!! 담에 또올께요!!', 13, 3, 'GOOD', SYSTIMESTAMP);
