INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '피규어가 정말 다양해서 보는데 넘 재밌어요! 글구 피규어 퀄리티가 진짜 좋아요.. ㅋㅋ 음료랑 케이크도 완전 맛있네요??? 홍대 이색 카페로 좋은거같아욤ㅎㅎ😀', 9, 0, 'GOOD', SYSTIMESTAMP);
