INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '홍대에 예쁜 카페가 있다고 해서 달려왔습니당🥰 피규어가 다양하게 많아서 볼거리가 넘쳐용ㅎㅎ 커피도 꼬숩고 맛있어요! 다음에 또 올게요🙌', 439, 47, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '들어오면 로다주와 시노부가 맞이해주는 카페입니당…💗 퀄리티 미쳐버린 피규어 구경만해도 1시간 뚝딱이에용 커피도랑 케이크도 진짜 맛있고 좋네용🥵💖💖', 73, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '맛있는 커피와 화려한 피규어까지 감상할 수있는곳이라 너무 행복한 시간이었어요!! 최근에 개봉한 귀멸의칼날 피규어도 많아서 너무 추천드립니당', 43, 8, 'GOOD', SYSTIMESTAMP);
