INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '오랜만에 찾아왔어요~ 그사이에 전시품들이 더 늘어난것 같아요~ 항상 친절한 사장님과 맛있는 디저트케이크, 그리고 많은 전시품까지. 잘 보고 갑니다.^^', 34, 6, 'GOOD', SYSTIMESTAMP);
