INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '매장에 들어가자마자 압도 당할 정도로 다양한 피규어와 레고에 놀라웠습니다! 사장님도 너무나도 친절하게 대해주시고 디저트에 대한 자세한 설명을 해주시는 것을 보고 사장님께서 이 공간을 카페로서도 참 사랑하고 계신다는 걸 느꼈습니다! 음료와 디저트도 맛있었고 너무 즐거운 시간이었어요', 20, 7, 'GOOD', SYSTIMESTAMP);
