INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '나만의 아지트 같은 키덜트카페...💖 이런 곳이 있을 줄이야ㅠ 케이크도 직접 다 만드신다는데 사진 너무 잘나와요 진짜! 카페 컨셉에 완전 충실 ㅎㅎ 피규어랑 레고가 진짜 많아서 구경하는 재미가 있네요 이런데 입장료도 안받으신다니ㅠ 피규어 좋아하는 남자친구 데리고 오면 환장할 것 같아요 ㅎㅎㅎㅎ', 19, 10, 'GOOD', SYSTIMESTAMP);
