INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '피규어 카페들이 없어지고 있던 요즘 혜성처럼 나타난 카페!! 홍대에 생긴 카페공간이란 피규어 카페인데 사장님이 굉장히 친절하시고 심지어 다양한 장르를 섭렵하셔서 접해보지 못한 장르도 있고 레진 대형 피규어 뿐 아니라 레고 건프라 합금피규어 등등 있어요~!!! 꼭 한번 들려보시길!!', 173, 38, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '수박라떼, 진짜 수박 많이 들어가있어서 정말 좋았어요. 피규어부터 음료까지 사장님손이 직접 닿아서 그런지~ 머하나 흠잡을때까지 없네요~:)', 15, 7, 'GOOD', SYSTIMESTAMP);
