INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '귀칼 팬이라서 피규어볼겸 왔는데 너무 만족하고 다른 멋진 피규어들도 잘 구경하고 갑니다~~사장님 갑자기 피규어관련 질문 드렸는데 너무 친절하게 답해주셔서 감사했어요 ㅎㅎ', 39, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '더위 대피할 겸 피규어보러 왔는데 기대 이상으로 커피도 맛있고 생과일 케이크도 왕 맛있어요💕💕 실내도 파워냉방인지 엄청 쾌적하고 실제로 보기 힘든 스테츄 작품들이 많아서 눈호강 하고 갑니다😍 또 오고싶어요!!!', 110, 26, 'GOOD', SYSTIMESTAMP);
