INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '키덜트족이라면 꼭 한번은 와봐야할곳! 멋진 피규어들도 감상할수있고 테이블 공간도 넓어서 친목하기에도 좋아요ㅎㅎ 커피도 너무 맛있습니다:)', 18, 9, 'GOOD', SYSTIMESTAMP);
