INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '홍대 놀러왔다가 피규어가 가득한 카페가 있다고해서 방문했어요~ 사장님두 너무 친절하시구 최근 귀멸의칼날 보구왔는데 귀칼 피규어두 있어서 반가웠고, 다양한 종류의 피규어들이 가득했어요^^ 카페는 생각보다 조용하고 분위기 있어서 편안한 분위기였습니당~ 혼자와도 넘 좋을듯 해요👍🏻', 2, 2, 'GOOD', SYSTIMESTAMP);
