INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '홍대에 이런 공간이 있었다니... 귀칼 좋아하시면 꼭꼭꼭 가보셔요🩷🩷 피규어 전시회에 온것 같아요..🥹 보고 감동 받은 피규어들이 많았어요 귀멸의 칼날 뿐만 아니라 디즈니, 레고, 짱구등 너무 많아요!!!', 44, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '친절한 사장님과 엄청난 피규어 컬렉션들을 보니 너무 가성비가 좋은 것 같습니다 귀멸의 칼날 레진 피규어들도 있어서 꼭 방문 추천드립니다!!!!', 130, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '안와본 사이에 케이크가 바꼈네요. 케이크 안에 복숭아가 이렇게 많이 들어간 케이크는 처음입니다. 8800원에 이정도 케이크면..요즘 빵값 비싸다고 하는데 여기만큼은 더 받아야 된다고 생각해요~ 사장님! 부디 오래오래 계세요!!', 4, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '생일선물로 산 프라모델을 조립할 곳이 마땅치 않아 전화로 여쭤보니까 흔쾌히 허락해주셨어요! 친절하신 사장님 덕분에 재밌는 추억 만들고 갑니다! 매장 안에 볼거리가 많고 디저트도 다양했습니다. 오레오쿠키프라페 달달하고 넘 맛있었습니다💗', 42, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '뷰, 위치, 시야 끝내주는데 💘 살면서 처음보는 진귀한 광경에 남자친구랑 꺄르르 하면서 이야기 할 거리가 많았어요 저는 피규어 수집가는 아니라서 평소에 아주 큰 관심이 없었는데도 디테일이 너무 실제와 유사한건 처음 봐서 하나하나 구경하느라 눈떼기 힘들었어요 👀 가챠(피규어?)뽑기 이벤트해서 아기짱구 나와서 넘 귀여워서 환호성 질렀어요! 음료는 이색카페라 기대 안했는데 딸기라떼 댕강추!💖 일반 카페보다 맛있어요! 귯', 35, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '사장님이 너무 친절하시구 케이크가 징짜 맛있어요 어텀인얼그레이 진짜 맛있어요 피규어 짱 많아서 너무 좋아요 귀여운거 진짜 많고 멋있는 피규어도 많아요', 68, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '입구 올라오기 전부터 창밖으로 보이는 큰 레고 모형이 시선이 가는데 올라오자마자 마블 캐릭텅하 에펠탑이 맞이해주는 어덜트카페중에 정말 최고 인거같아요 사장님께서 케익 설명도 자세히 해주시고 자리까지 음료 가져다 주시는데 섬세함이 너무 좋았습니다 자리마다 중복 되지 않게 각종 피규어 와 소품으로 꾸며 져있고 눈이 너무 즐거운 곳이네요!!!!', 2, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '상수역 근처에 이색적인 카페가 있다고 주변에서 소개받아서 방문해봤어요! 사장님도 너무 친절하시고 영화나 애니를 좋아하시는 분들이 방문하시면 구경하실것도 많고 음료도 맛있고 특히 어텀인 얼 그레이 부드럽구 달콤해서 너무 맛있었어요! 😭 아이언맨 전시되어있는게 거의 사람이랑 똑같구 추후에 다른 작품들도 들어온다고 해서 다음엔 여자친구랑 재방문 의사 200프로입니다! 특히 마블이나 dc도 있지만 레고나 귀멸의칼날 좋아하시는분도 구경할만한게 다양하게 있어서 좋을거같아요! 친절히 응대해주신 사장님 너무 감사드리구 다음에 또 갈게요! 리뷰 잘 안쓰는편인데 추천드려요!', 87, 11, 'GOOD', SYSTIMESTAMP);
