INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '특별하고 시원한 커피 비포선셋 진짜 강추드려요 커피맛과 오렌지맛이 이렇게 잘 어울릴 줄이야... ㅠㅠ 케이크도 계절별로 있어서 보는 눈도 입맛도 즐거워지는 시간 ㅎㅎ 사장님이 인테리어뿐만 아니라 디저트와 커피류에도 진심이라 간만에 힐링 하구 왔네요 💕', 74, 14, 'GOOD', SYSTIMESTAMP);
