INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '이렇게 잘 되어 있는 피규어 카페 처음 봐요! 케이크랑 커피도 너무 맛있고 피규어 좋아하시면 추천합니다 마블 뿐 아니라 엄청 다양한 피규어가 있어요!!', 18, 4, 'GOOD', SYSTIMESTAMP);
