INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '카페 찾다가 그냥 아무데나 들어왔는데 너무 좋아요! 귀멸의 칼날 보고왔다고 하니까 우산손잡이도 주셨어요🔥 구경할것도 많고 음료도 맛있구 케이크도 맛있습니다🫶 사장님도 너무 친절하셔서 기분좋게 쉬고가요🥰', 21, 9, 'GOOD', SYSTIMESTAMP);
