INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '구경하는 재미도 쏠쏠한데 케이크도 진짜 맛있구 시원해서 너무 좋았어요!!!🥺 아이들이랑 가기에도 좋고 데이트하기에도 좋은 카페 추천!!!!', 65, 14, 'GOOD', SYSTIMESTAMP);
