INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), 'JND피규어 궁금했는데 너무멋있어서 저도 사고싶었어요 피규어 하나하나 맞춤장식장해놓으신것도 고급지고 취미생활에 아낌없이 투자하시는모습도 너무 멋있네요 한번쯤 꼭와볼만한곳 같아요 사장님이 친절하게 설며해주시는데 재밌게들었어요!! 잘보고갑니다!!', 45, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '피자 작은 사이즈인데도 둘이 배부르게 먹을만큼 양도 많고 너무 맛있었어요! 레모네이드도 너무 맛있었어요 피규어에 대한 사장님의 진심이 느껴지는 곳입니당', 41, 8, NULL, SYSTIMESTAMP);
