INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '와 피규어 디테일들이 미쳤어요...토니스타크 미쳤고 조커 미쳤고 다른 피규어들도 진짜 너무 멋있어요!! 카페왔는데 전시장을 온것 같은 느낌이에여 커피랑 레몬에이드도 맛났습니다!', 2, 1, 'GOOD', SYSTIMESTAMP);
