INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '너무 좋은 공간입니다. 음료도 맛있고 무엇보다 사장님이 정말 친절하세요! 디카페인이 메뉴에 없는데 여쭤보니까 원두가 있어서 핸드드립으로 디카페인 아아를 한 잔 만들어주셨답니다~ 진열되어 있는 피규어들은 거의 그냥 박물관 급이에요. 이건 관람료 내야하고 봐야하는 것 같은데라는 생각이 들더라구요. 케이크도 직접 만드시고 너무 맛있더라구요. 재방문 의사 백퍼입니다!', 30, 5, 'GOOD', SYSTIMESTAMP);
