INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '친구들이랑 지친몸을 안고 거느적거느적 걸어가다가 분위기가 좋아보이는 카페에 들어갔는데 기본적으로 사장님께서 친절하시고 차분하셔서 정말 좋았어요 매장을 이용하시는 손님분들도 상냥하셨고요 음료에 신경쓰신티가 많이나서 사진에도 잘 담겼네요 티도 향긋하니 기분도 좋아졌고요 ㅎㅎ 차가운 티는 왠지 꺼려져서 따뜻한 티로 가능하냐고 여쭤봤는데 메뉴판에 없는데도 불구하고 최대한 제 니즈에 맞춰주셔서 감사했습니다 다음에도 또 봬요 ☺️', 78, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '서울에 이런곳이~'' 너무 좋네요 고가의 리얼리티 피규어도 보고 맛있는 커피에 사장님 너무친절♡♡ 피규어설명도 같이해주시고 매장이 하나의 전시장같아요 ~~ 피규어 좋아하신분 ,연인 같이오면 좋은추억이될듯~~^^ 피규어 전시가 늘어날 예정이라서 종종 자주 올께요 ~~ 밤에오면 조명이너무예뻐서 밤에 다시 발문할예정입니다 ~~ 내돈내맘 진심 리뷰', 25, 6, 'GOOD', SYSTIMESTAMP);
