INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '홍대에 피규어 좋아하시면 여기는 필수 코스에요 !! 케이크 음료 다 맛있고 피규어 구경하는 재미가 쏠쏠해용 과일 실사화 케이크도 먹으러 또 와야겠어요 ㅎㅎ', 39, 9, 'GOOD', SYSTIMESTAMP);
