INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '다양한 영화, 애니 피규어가 있어서 보는 재미가 더 있어요!! 서울 한복판에 이런 곳이 있다니ㅠㅠ 박물관 축소판 느낌😆 덥고 습한 요즘 실내에서 놀기 딱 좋은 카페예요ㅎㅎ 음료랑 디저트도 맛있어요!!', 59, 11, 'GOOD', SYSTIMESTAMP);
