INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '요즘 피규어 카페가 많이 없는데 실제로 피규어를 볼 수 있어서 너무 좋았고 피규어 카페인데 음료가 너무 맛있었습니다!!! 그리고 사장님도 진짜 친절하셨습니다!!!ㅎㅎㅎ', 13, 7, 'GOOD', SYSTIMESTAMP);
