INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '직접 만든 수제 케이크가 정말 맛있고, 공간 곳곳에 마블 피규어랑 레고 전시돼 있어서 카페라기보다 작은 전시관 같은 느낌이에요. 덕분에 커피 마시면서 구경하는 재미까지 있어서 힐링 제대로!', 91, 23, 'GOOD', SYSTIMESTAMP);
