INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '오레오 프라푸치노 꼭 드셔보세요 존맛탱 엄청 달지도 않고 딱 적당히 달고 맛있어용 그리고 입장하자마자 피규어 퀄리티가 다른 매장보다 훨씬 좋아용', 10, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '토니스타크가 왔다는 소식에 달려왔어요~:) 진짜 똑같네요 ㅋㅋ 남친이 환장함 ㅋㅋ 피자도 가볍게 먹기 좋아요~♡ 사장님의 설명에 더 재밌게 놀다갑니다 또 올께요~:)', 59, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '길가다가 케이크가 귀여워서 왔는데 이름이 키덜트 공간인 이유가..! 들어오자마자 압도됐어요ㅋㅋ 음료도 맛있고 매장도 넓고 보는 재미도 있어서 추천합니다!! 피규어 좋아하시는 분들 강추!', 0, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '커피 원두를 선택할수있고 저는 고소한 맛으로 먹었습니다! 자몽 에이드는 청으로 만들어서 달콤한맛이 좋았어요 피규어도 구경하는 재미가 있었어요!  DC,마블 좋아허시는 분은 꼭 와야합니다 조커, 아이언맨, 헐크 상반신 피규어가 멋있습니다.', 15, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '피규어가 멋지게 전시되어 있는 곳이라서 방문해봤는데 생각했던것 보다 더 대단하게 전시해놓으셔서 눈호강 잔뜩 하고 갑니다!!ㅎㅎ 너무 멋져요~! 커피도 고소해서 맛있고 다음번엔 시그니처 메뉴 마셔보고 싶네용 사장님께서도 너무 친절하세요ㅠ 자주 올게요~!', 45, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '사무실 건물에 너무 멋진 카페가 생겼어요. 너무 멋진 피규어들이 아주 많아요. 정말 멋있고 리얼해서 구경하는 재미가 쏠쏠하답니다. 심지어 커피와 디저트도 너무 맛있어서 자주 가게될거같아요. 지금 방문하면 리뷰이벤트로 가챠도 주셔서 커피마시면서 가챠 조립하는 재미도 있더라구요. 아! 그리고 무엇보다 사장님과 직원분들이 너무 친절하셔서 너무 좋은 공간이에요. 커피컵도 생분해컵이라 친환경적이라 기분좋더라구요. 홍대 합정 상수 오셔서 색다른 카페 오시고픈 분들은 꼭 ‘카페공간’에 들러보세요. 절대 후회하지않을겁니다.', 46, 9, 'GOOD', SYSTIMESTAMP);
