INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '너무 맛있게 잘먹었어요 디테일 장난아닌 피규어가 많아요 피규어 관심 1도없는데 눈이 휘둥구레질 정도로 놀랐고 이것저것 얘깃거리가 생겨 재미가 납니다!! 단골됐어요', 37, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '생각보다 번쩍거려서 놀랐는데 볼거리가 많아서 좋아요! 일단 디저트가 너무 예쁩니당 ㅎㅎ 사진도 잘 나와요!! 창이 탁 트여있어서 좋아용 ㅎㅎ', 43, 7, 'GOOD', SYSTIMESTAMP);
