INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '음료도 맛있고 사장님도 친절하셔요! 볼 거리가 많아 좋았어요~ 스타워즈, 레고, 건담 등등 평소에 보기 힘든 크고 멋진 애들이 많아서 색다른 경험을 할 수 있어요👍🏻🩷', 0, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '카페에서 이렇게 피자가 잘 나올꺼라곤 생각못했다. 담에 친구랑 같이 꼭 와야겠다. 1대1 로다주도 볼수 있고, 사장님 번창하세요!!', 14, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '피규어를 이렇게 많이 본건 처음이었어요!! 멋있는 공간에 맛있는 디저트와 음료까지 있어서 만족스러웠습니다 피규어 좋아하시는 분들 꼭 방문해 보세요 ㅎㅎ', 7, 4, 'GOOD', SYSTIMESTAMP);
