INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '홍대에 키덜트카페가 생겼네요! 역대급 스케일 피규어들이 가득한곳이라 너무 재미있었어요! 특히 입구에 헐크와 타노스 스케일 뭐죠? 정말 미쳤어요 홍대에서 색다른 놀거리 찾으시는 분들은 바로 여기입니다!', 49, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '이상훈 TV에 나와서 방문했는데 시그니처 음료인 비포선셋 정말 부드럽고 인테리어는 눈이 휘둥그레 지네요. 피규어 좋아하시는 분께는 정말 강추합니다.👍👍👍', 65, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '디저트도 너무 맛있고 사장님께서 너무 친절하셔서 계속 오고싶어지는 곳이에요! 레고와 피규어들이 많아서 매장 구경하는 재미도 있고, 특이한 디저트들도 많고 맛도 정말 맛있어요!', 113, 22, 'GOOD', SYSTIMESTAMP);
