INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '역시 작품을 실제로 눈 바로 앞에서 보는것은 갤러리를 방문하는 가장 큰 이유인데 이곳이 그런 곳이네요. 어릴적 TV나 영화속 주인공들을 보며 그시절 순수했던 제 자신의 추억과 감정을 잠시 꺼내본것 같아 좋은경험이였습니다. 아 그리고 케이크와 커피도 퀄리티가 너무 좋았습니다. 특히 케이크는 미쳤네요 ㅎ케이크만 먹으러 가도 될정도 ㅎㅎ', 45, 4, 'GOOD', SYSTIMESTAMP);
