INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '피규어가 엄청 다양하게 많는 카페네요. 근래 ‘F1 더 무비’ 영화를 봐서 에프원에 관심이갔는데 이 카페에 피규어가 있어서 너무 좋았어요 홍대오시면 꼭 들러보세요!', 24, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '오늘 두번째 방문했는데 새로운 피규어도 있어서 좋았어요 사장님도 엄청 친절하시구 짱구랑 건담 등등 되게 다양한 피규어 있어용~ 다음에 또 방문할게용~!!', 65, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '피규어 좋아하시는 분들이라면 강추! 카페가 정말 멋있어요! 캐릭터 구경하는 재미가 있고, 퀄리티가 어마어마해요. 커피와 케이크도 괜찮아요😊👏🏻', 13, 8, 'GOOD', SYSTIMESTAMP);
