INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '친구랑 같이 홍대에 이색적인 곳을 와보고 싶어서 검색하던중 피규어 전시응 해놓은 카페가 있다고 해서 와 봤는데 여름이라 더웠는데 매장안은 너무 시원하고 디저트도 너무 예쁘고, 무엇보다 피규어 하나하나 너무 예쁘게 전시가 되있었어요 리뷰쓰고 있는 중인데도 친구는 피규어 구경 갔네요 하나하나 관리도 너무 잘되있고, 사장님도 너무 친절해서 좋았어요', 48, 8, 'GOOD', SYSTIMESTAMP);
