INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '진짜 살면서 꼭 한 번은 와봐야 할 것 같고 여러번 더 와도 좋은 곳인 것 같아요! 엄청 귀한 피규어들이 많고 특히 아이언맨은 진짜 살아숨쉬는 사람이 눈 앞에 있는 느낌이에요! 피규어만 기대하고 왔는데 음료, 케이크 다 장인이 만든 것 같은 맛이에요 사장님.. 땅파서 장사하시는거 아닌지 걱정될 정도로 음료 디저트 퀄리티도 좋아서 방문하고 절대 후회 안할 곳이에요!!', 19, 9, 'GOOD', SYSTIMESTAMP);
