INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '피규어를 좋아하는 분들께는 꿈의 공간이네요. 큼직한 피규어들을 감상하며 마시는 음료와 디저트가 딱인 듯 합니다. 친절하신 사장님과 아늑한 분위기도 좋고요. 꼭 방문해보세요!', 79, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '커피, 디저트 빠짐없이 맛있어요~~ 들어오자마자 피규어 레고들로 시선이 빠져드네요! 오래있고 싶어요! 이 더운날 쉬다가기 좋은 공간입니다.', 8, 3, 'GOOD', SYSTIMESTAMP);
