INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '아이들도 어른도 너무 만족할 수 있는 예쁜 카페예요. 레고, 피규어, 실사 캐릭터들이 전시되어 있는데 구경하는 재미가 쏠쏠해요! 선셋커피도 너무 맛있어요! 피규어들에서 빛이 나와서 너무 예뻐요. 다음에는 밤에 와봐야겠어요! 사장님 정말 친절하세요~ 잘 놀고 힐링하고 갑니다~', 22, 3, 'GOOD', SYSTIMESTAMP);
