INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '사장님 진짜 친절하시고 피규어 좋아하는 제게 너무 행복한 장소였습니다! 음료도 다른곳과 차별화된 느낌이고 케익도 너무 예쁘고 뭐하나 빠질게 없는 장소네요! 사진도 진짜 블링블링하게 잘나와요!! ㅠㅜ 조커 특히 완전 반했어요!!!!!!', 99, 23, 'GOOD', SYSTIMESTAMP);
