INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '일단 인테리어가 들어오자마자 너무 압도적으로 멋지네요!! 음료도 너무 맛있고 디저트도 사장님의 열정이 느껴집니다 그리고 사장님이 너무 친절하세용 데이트나 친구들이랑 음료 마시면서 쉬러 오기 너무 좋은 거 같아용~!!', 40, 2, 'GOOD', SYSTIMESTAMP);
