INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '멋진 피규어도 많고, 비포선셋의 경우 오렌지가들어간 커피는 맛있게 만들기 힘든데, 엄청 여름생각나게 맛있습니다 상상마당 온다면 강추', 2, 9, NULL, SYSTIMESTAMP);
