INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '일반카페인줄 알고 왔다가 구경할게 많아서 정말 놀랐네요 저처럼 만화 레고 피규어 좋아하시는 분들 정말 만족하실듯 치즈케이크도 안먹었음 후회할뻔..!', 0, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '귀멸의 칼날 팬으로써 이 카페는 여러분들도 꼭 한 번 방문 해봤으면 좋겠습니다 피규어들도 너무 많이 있고 볼 곳도 많아서 기분이 좋았습니다', 86, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '홍대역근처왔다가 커피마시려고 카페알아보다가 인테리어가 멋져서 들린 카페공간! 오랜만에 다양한 피규어들과 갤러리느낌의 멋진 인테리어를 볼수있어서 너무좋았습니다!! ><', 8, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '프라모델,피규어 좋아하면 무조건 들려야하는 곳❣️ 홍대올때마다 와야겠어용 이런 분위기카페 찾다찾다 넘 좋은곳 발견함ㅎㅎ🫶🏻🫶🏻', 56, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '초등고학년 아이랑 같이 왔는데 아이가 좋아하네요~! 사진도찍고 볼거리가 많아서 만족합니다^^ 커피도 고소한맛이랑 산미있는거 선택할수있어서 더좋아요~! 더운데 잘쉬어갑니다~!', 98, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '오랜만에 홍대갔다가 특이한카페에 갔음 피규어 레고성 진짜 다양하고 신기햇음 구경하믄서 얘기하니 별로 안친한사람과도 시간 팍팍 갈듯함ㅋㅋ 사장님 친절하게 설명도잘해주고 대박은 딸기라떼에 얼음거의 없구 딸기가 왕창 ㅋㅋ 생크림넣은건지 부드럽고 자꾸생각나는맛 담에또갈게요!!딸기마니마니 줘요', 13, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '이런곳이 홍대에 있었다니.. 놀러올곳 하나더 생겼네요!! 피규어들 너무나 멋지고 퀄리티 장난아닙니다. 피규어들도 진짜사람 같던데 여긴 디저트도 진짜과일같네요~~ 치즈케익덕후라서 치즈케익 먹었는데 부드럽고 진하고. 진짜 맛있게먹고 잘놀다가요 시간가는줄 몰랐다는..😏', 17, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '유튜브 보고 방문했어요. 레고랑 피규어 좋아하는 가족이라 구경할게 많아서 눈이 즐겁고 음료도 맛있어서 입도 즐겁네요 💕  아이랑 신기해서 한참 구경했어요 👦🏻🤍 다음에 또 방문할게요 👍🏻🤍', 99, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '커피도 음료도 다 너무너무 맛있구요~ 피규어도 보는맛이 뛰어나네요 ㅎㅎ 잘 먹고갑니다 보다는 잘 보고갑니다가 어울리는 카페 같아요~😆', 0, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '카페인데 고퀄리티 피규어들이 많아서 볼 것이 많아서 좋았어요~사장님들도 너무 친절하시고 야외뷰 자리도 있어서 봄바람 즐기면서 커피 마실 수 있어서 너무 좋았어요😀 케익도 직접 만드신다는데 너무 맛있습니다ㅎㅎㅎ', 3, 10, 'GOOD', SYSTIMESTAMP);
