INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '홍대에 진짜 특이한곳이 생겼네요. 남친눈이 휘둥그레지는 피규어에 상큼한 케이크까지 한라봉은 진짜 한라봉인줄 알았어요~:) 케이크였다뇨 ㅋㅋ 그리고 여기의 kick은 사장님이 진짜 친절함?!!', 94, 19, 'GOOD', SYSTIMESTAMP);
