INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '들어오자마자 멋진 피규어들이 전시되어있어서 놀랐어요!! 전시회 온것처럼 구경하는 재미도 있었고 음료수랑 케이크도 너무 맛있습니당ㅜㅜ', 7, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '멋진 피규어와 전시품들을 좋은 카페공간에서 볼 수 있다니 너무 좋네요. 음료도 놀랄 정도로 맛있고, 디저트들도 맛있었습니다. 카페 분위기도 근사하고, 사장님께서도 정말 친절하십니다. 보통 피규어 카페를 보려면 차 타고 멀리 나가야 했는데 홍대에 생겨서 너무 좋네요. 자주 와야겠습니다. 카페공간 강력히 추천합니다!', 125, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '애인이랑 귀멸의 칼날 보고난후에 방문 하게되었어요!!! 다른sns에서 보고왔는데 너무 멋지고 레진 피규어들도 멋지고 키링도 멋진거 얻었습니다!!! 너무 즐거운 시간 보내고가영ㅎㅁㅎ', 14, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '홍대 놀러왔다가 우연히 들렸는데 분위기도 너무 좋고 피규어가 많아서 구경하는 재미까지 있었어요! 다음에 또 방문할 예정입니다🤭', 22, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '좌석간 간격이 충분해서 프라이빗한 느낌으로 대화하기에 좋아요! 수박주스랑 조각케익 주문했는데 비주얼도 예쁘고 상큼하고 너무 맛있었습니다! 그리고 사장님 두분이신거 같은데 너무너무 친절하세요 짱 번창하시길🩷 (케익너무 예뻐서 사진 올리고싶은데 제폰이 오류인지안올라가요... 다음에 꼭 다시 올게요ㅜㅜㅜ)', 40, 2, 'GOOD', SYSTIMESTAMP);
