INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '카페공간 디저트 강추합니다!! 사장님께서 직접 만드시는 수제케익이라고 하는데 초코코팅, 크림치즈, 사과알갱이가 들어있고 커피를 부르는 맛입니다!! 방문하시면 한번씩 드셔보세요', 45, 5, 'GOOD', SYSTIMESTAMP);
