INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '계절 컨셉별 케이크도 너무 이쁘고 맛있구 피규어때문에 보는 재미도 있어요! 그리구 무엇보다 사장님 대친절하셔서 기분 너뮤 좋아져요ㅠㅠ 다음에 또올게용☺️', 21, 1, 'GOOD', SYSTIMESTAMP);
