INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '향이 좋은 커피와 눈이 즐거운 피규어들이 가득한 덕후들을 위한 공간입니다! 사장님과 함께 스타워즈나 건프라같은 이야기를 나눌 수 있어서 너무 좋았습니다!', 19, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '볼거리가 풍부합니다. 사장님도 친절하시고 피규어나 이색공간 좋아하시거나 작업이나 공부하기에도 최고입니다. 아메리카노 할인 이벤트에 가챠까지 이벤트중입니다. 자주 올거 같아요!', 22, 8, 'GOOD', SYSTIMESTAMP);
