INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '피규어 구경하러 왔는데 커피도 디저트도 맛있어요~!! 귀멸의칼날 레진피규어도 많이있고 마블 피규어도 있는데 퀄리티가 진짜 너무 훌륭해요. 시간 가는줄 모르고 구경했네요!! 사장님도 넘 친절하셔요', 16, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '피규어카페인데 피자가 너무 맛있어서 또왔음... ..... .. . 어디서납품받으시는지 물어보고 싶을정도로 피자가 맛있네요.. ... 진짜 피자맛있네요 저 피자안좋아하는데 진짜맛있네 희안해요', 21, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '음료와 디저트도! 너무 맛있습니다~ 너무 달지도않고 진짜 먹은것중에 젤 맛있어요! 앉아서 편하게 액션피규어보면 감탄만 나오네요!! 번창하세요!!', 41, 7, 'GOOD', SYSTIMESTAMP);
