INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '피규어랑 레고 등 볼거리가 많아 구경하는 재미가 있습니다! 커피랑 케이크도 맛있고 사장님이 정말 친절하셨어요☺️ 다음에 또 방문하겠습니다!', 4, 2, 'GOOD', SYSTIMESTAMP);
