INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '커피도 너무 맛있고 피규어 구경도 함께 하니까 다채롭네요! 조용해서 이야기 나누기도 좋은 공간이예요:)  피규어 좋아하시는 분은 물론 그냥 예쁜 카페 찾으시는 분들에게도 추천드려요!', 84, 15, 'GOOD', SYSTIMESTAMP);
