INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '지나가다 반짝거리는 조명에 이끌려 올라가보았습니다 커피가 맛있구 신기한 피규어들이 많아서 구경거리가 많았어요 새로오픈한거같던데 번창하시길', 15, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '올때마다 맛있는 커피들 마실 수 있어서 너무 좋고 인테리어 해두신 각종 피규어들 보는 재미가 있습니다 홍대쪽 들를때 한번씩 오게되는거 같네요 :)', 36, 0, 'GOOD', SYSTIMESTAMP);
