INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '일요일주일오후 레고 좋아하는 아들과 함께 홍대 카페공간을 방문했습니다. 실제로 타이타닉 레고와 에펠탑 실물을 보고 싶어서 왔습니다. 멋진 레고 작품들과 건담 다양한 캐릭터들에 아이들과 시간 가는줄 모르고 구경하느라 정신없었습니다. 밀레니엄 팔콘을 꼭 만들어 보고싶다는 아이의 큰 꿈을 꼭 이루어 주는 엄마가 될수 있도록 부지런히 돈 벌어야겠어요^^ 오랫만에 홍다나들이에 행복한 시간 보냈습니다.', 12, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '이제 홍대 카페는 이곳만 오기로 결정했습니다!!!! 카페가 엄청 여유롭고 커피 마시면서 쉬다가기 너무 좋아요. 볼거리도 엄청 많아서 연인과 함께 여유롭게 데이트하기 좋은 곳입니다!! 추천!!!', 15, 5, 'GOOD', SYSTIMESTAMP);
