INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '남편이랑 왔는데 너무 좋아해요 ㅎㅎ 고퀄리티의 피규어를 가까이 볼 기회 없었는데 눈도 즐겁고 맛있는 케이크에 입도 즐겁고 너무 좋아요', 6, 3, 'GOOD', SYSTIMESTAMP);
