INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '레몬에이드랑 자몽에이드 주문했는데 새콤달콤하니 맛있구요 공간 자체도 조용하고 볼거리도 많아서 너무 좋아요! 사장님도 굉장히 친절하셨어요!', 29, 7, 'GOOD', SYSTIMESTAMP);
