INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '홍대 어울마당로의 멋진 키덜트갤러리 카페공간! 사장님이 개인적으로 수집한 방대한 양의 키덜트를 감상하며 맛있는 케이크와 음료를 즐길 수 있는 공간, 개방된 통창으로 동네뷰를 바라보며 여유로운 힐링이 가능해 오감만족 행복한 디저트타임 보냈어요 ㅎㅎ 합정 상수 올때마다 들러서 쉬어가고싶은 곳, 오래오래 번창하세요 ~^^👍', 13, 6, 'GOOD', SYSTIMESTAMP);
