INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '여긴 남자들에겐 천국과 같네요. 사장님의 컬렉션이 왠만한 샵보다 좋습니다. 입장료받으세요!!! 그리고 하나하나 설명해주셔서 재밌었습니다. 전 단골 될꺼 같아요.', 96, 22, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '키덜트 성지될것같다는 예감!!!!! 커피 안먹어서 딸기라떼 주문했는데, 딸기 이렇게 많이 주는데는 첨이네  ㄷㄷㄷ 사장님 ㅋㅋ 피규어에 관심주면 설명해주심 ㅋㅋ 친절하시네요~ 또 올께요~ :)', 98, 26, 'GOOD', SYSTIMESTAMP);
