INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '유튜브로 통해 접해서 오늘 처음 방문 했는데 인테리어도 멋지고 매장안도 깨끗하고 넓어요~ 되게 아늑하고 좋아요~ 나중에 또 재방문 의사 있어용~', 116, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '이쁜 피규어들 짱많아요!!! 귀멸의 칼날 외에도 여러 영화, 애니 피규어들도 많아서 눈이 즐거워요 음료도 맛있고 사장님도 매우 친절해요!! 귀멸의칼날 영화본거 인증하면 우산에 꽂을 수 있는 키링도주세요. 다음에 또 방문하겠습니다!', 28, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '피규어 좋아하는 사람들이 오면 눈이 커지는 공간🫨🫨 피규어를 잘 모르는 사람이 와도 신기하고 재밌어요!!😻 디저트도 눈으로도 이쁘고 맛있는 디저트가 잔뜩 있어서 신기했어요!!🩷', 9, 7, 'GOOD', SYSTIMESTAMP);
