INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페공간 홍대점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '우연찮게 새로 오픈한 키덜트카페를 봤어요~볼거리 장난 아니에요~시간 가는줄 모르고 보고 찍고 먹고…다음에 친구들도 데리고 또 갈려구요.', 51, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '홍대에서 카페 찾으면 무조건 방문하는 카페345! 층고가 높아서 개방감 장난없고 음료도 찐하고 맛있는데다가 다양한 디저트 라인업부터 분위기까지 너무 완벽한 곳이어서 몇번째 재방문인지 모르겠어요. 카공하기도 좋고 테이블도 많아서 대화하기도 좋아요 후후', 121, 23, 'GOOD', SYSTIMESTAMP);
