INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '카페345 고딕체 간판에 끌려 벼르다 왔습니다. 매장이 넓고 층고가 높아 쾌적한 느낌입니다. 아파트에 사는 사람들은 높은 층고에 대한 로망이 있지요. order here 라고 쓰여있어 주문을 하는데 키오스크로 주문을 하라고 합니다. 두리번 거리다 한 여행객 가족이 줄서 있는 곳을 찾아냅니다. 주문을 하고 폰의 삼매경에 빠져있다보니 어라? 주문한 음료와 케익이 왜 안나오지...싶어 물어보니 진동벨 달라고 합니다. 진동벨 없는데.... 주문할 때 진동벨 번호를 누르게 되어있는데 키오스크 옆에 진동벨이 있고 그걸 집어들고 해당하는 번호를 누르는 것 이었나봅니다. 그냥 좋아하는 번호 누르고... 부르는 소리도 못듣고... 15분 지나 케익은 다 녹고.. . 그럼에도 불구하고 헤이즐럿 쵸콜릿 케익은 맛있습니다.', 7, 6, NULL, SYSTIMESTAMP);
