INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '공간이 넓고 예쁩니당❤️ 밀크티랑 스콘 시켰는데 밀크티 진하고 맛있어요!! 초코 스콘도 꾸덕해서 진짜 맛있었어요 ㅋㅋㅋ다음에 오면 크로플도 먹어보고싶어요옹💚홍대 완전 중심가에 있으면서 은근 한적한 골목이라   언제 와도 좋을 것 같습니다 강추🌸', 43, 2, 'GOOD', SYSTIMESTAMP);
