INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '매장에 크고 시원해서 좋고요! 커피, 케이크 둘다 너무 맛있어요😍👍🩷 말차라떼 먹은친구도 진하고 맛있다고하네요~ 무화과 케이크 꼭 드세요!!!', 122, 23, 'GOOD', SYSTIMESTAMP);
