INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '홍대역이랑 가까이 위치해 있어서 접근성이 좋아요! 바닐라라떼아이스 디카페인 음료 시켰는데 부담스럽지 않게 달달하고 히비스커스에이드도 탄산이 과하지 않아서 끝까지 맛있게 먹었어요🙂 스콘도 너무 퍽퍽하지않아서 좋았어요! 다음에 남친이랑 오려고요', 39, 3, 'GOOD', SYSTIMESTAMP);
