INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '더위를 피해서 온 카페삼사오 카페가 널찍하고 좌석이 많아서 가끔와요! 벌써 세번째… 홍대가 핫플이라서 예뻐도 공간이 작은 카페는 항상 만석이라 가기 힘든데 여기는 좌석이 많다보니 나름 만석의 걱정을 덜하고 옵니다! 오렌지비앙코 맛있었어요 딱 생각했던 맛👍🏻 원두는 디카페인으로 변경! 다른건 자몽 히비스커스 에이드인데 자몽과 히비스커스의 조합 괜찮았어요! 새콤달콤 시원한게 헤이즐넛 초콜릿 케이크와 잘어울림🙌🏻 오렌지 비앙코 먹다가 케이크랑은 에이드가 잘 어울려서 세입 빼앗아 먹은 것은 안 비밀! 남자칭구가 그만좀 뺏어먹으래여😋 사진은 인생샷 까지는 아니지만 그래도 조명도 그렇고 좌석도 블랙에 뒤에 스크린이 있어서 나름 있어 보이게 촬영할 수 있어요!', 34, 4, 'GOOD', SYSTIMESTAMP);
