INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '홍대입구카페 중에 이렇게 넓고 쾌적한 대형카페가 있는 줄 몰랐어요! 음료, 디저트 메뉴도 다양하게 있고, 맛있었어요! 커피 원두 선택도 가능하더라고요 🎶 매장도 쾌적하고 직원분들도 너무 친절하셨어요! 아이스크림도 진한 우유 맛에 초코 코팅이 가득 올려져있어 달콤하고 맛있었습니다 🍦🍫', 26, 9, 'GOOD', SYSTIMESTAMP);
