INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '커피 원두도 여러종류라 취향에 맞게 먹을수 있어서 좋아요 피스타치오라떼를 시켰는데 너무 맛있어요 처음 먹어봤는데!!! 피스타치오 맛이 쫙 찐하게 느껴져서 행복합니당❤️ 얼그레이 스콘 추천해용 물론 제가 좋아하는거라서 히히❣️', 77, 15, 'GOOD', SYSTIMESTAMP);
