INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '간략히 써본 카페 장점 1. 트렌디한 색감과 인테리어 속 편안함 2. 넓은 공간에 테이블 간격이 그리 좁지 않음 3. 사진 잘 나오게 만들어주시는 음료와 디저트 4. 대화하기 좋고 혼자서 공부하기도 좋은 공간', 432, 74, 'GOOD', SYSTIMESTAMP);
