INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '커피랑 스콘이 너무 맛있었어요! 스콘이 생각보다 엄청 크고 얼그레이 향이 많이나서 제 취향이였습니다. 홍대에 드문  대형카페라서 좌석도 넓고 수다떨기도 좋았어요. 충전좌석도 있고 무엇보다 원두도 선택할 수 있어서 커피 취향을 맞출 수 있었어요!', 51, 18, 'GOOD', SYSTIMESTAMP);
