INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '너무 더운 한 여름에 잠시 쉬려고 온 카페! 커피도 너무 맛있고 아이스크림 진짜 최고! 우유라서 느끼하려나 했는데 기본이 맛있어야 다른 게 맛있잖아요!! 여기 바닐라 소프트는 최고에요!!!', 31, 1, 'GOOD', SYSTIMESTAMP);
