INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '아이랑 나들이나왔다가 들르게된 대형카페.... 엄청 넓고 시원하고 요새같이 더운날 진짜 천국같았어요 매장 내 테이블도 4~6인석이 많아서 여럿이 모였을때도 좋을거같고 아주 인상적인 내부였습니다 다만 ... 아이가 시킨 아이스크림크로플 메뉴에 스푼이 제공되지않는점이 매우 의아하네요. 아이스크림을와플 위에 얹어서 나온거라면 이해하겠는데 유리컵에 와플과 별도로 서빙되었고 아이스크림 개별메뉴도있는 집인데 스푼을 요청했더니 이 메뉴는 스푼을 주지않는다고 딱잘라말하니 당황했고 이후에 재차 스푼요청을하니 작은 티스푼을 제공해주셨는데 처음부터 그냥 스푼을 주셨으면 어땠을까싶네요... (서빙해주시던분 인상이... 말을 걸기 어려운편이었습니다) 그부분만 제외한다면 추천드리는 장소입니다^^', 4, 7, NULL, SYSTIMESTAMP);
