INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '홍대 입구에 이렇게 큰 카페가 있다니 너무 좋아요~ 역에서도 가깝고 매장이 진짜 넓어요! 외관부터 노란색이 눈에 띄고 멋져요 쾌적하고 깔끔한 편이에요 음료 종류도 다양하고 커피 진짜 고소하고 맛있어요~ 스콘도 퍽퍽하지도 않고 맛있네요👍🏻', 1, 5, 'GOOD', SYSTIMESTAMP);
