INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '아이스크림은 우유맛이 가득해서 좋았어요. 카푸치노도 부드럽고 맛있습니다. 음료한잔당 최대 2시간 이용 가능하지만 의자가 쿠션이 없는 딱딱한 의자에요.', 98, 22, NULL, SYSTIMESTAMP);
