INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '넓고 쾌적하고 깔끔하고 좋아요 커피도 맛있고 디저트랑 잘 어울려서 맛있게 먹었고 직원분도 친절해요~ 키오스크도 있어서 편하고 일단 넓으니까 답답하지 않고 쾌적하고 편하고 좋네요 다음에 또 방문할게요', 4, 10, 'GOOD', SYSTIMESTAMP);
