INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '🏷 한줄평 - 홍대 미쿠감사제 시즌에 들른 감성 카페. 통유리 구조 덕분에 분위기와 사람 구경 모두 만족스러웠어요! 🏠 공간 - 매장이 넓고 좌석도 다양해서 단체 모임이나 친구 약속 장소로 잘 어울렸어요. 화장실도 깔끔했어요. 🍽 음식 - 아이스 아메리카노는 무난했고, 피스타치오 음료는 호불호가 갈릴 수 있는 맛이라 참고하시면 좋아요. 🙏 서비스 - 직원 응대는 친절했고, 행사 참여 시 미쿠 굿즈도 받을 수 있어서 재미있는 경험이었어요. 🚉 교통 - 홍대입구역 9번 출구에서 도보 약 2분 거리로 접근성도 좋고, 처음 방문하는 분도 쉽게 찾을 수 있어요.', 78, 15, 'GOOD', SYSTIMESTAMP);
