INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '홍대에 이렇게 넓은 카페가 있는줄 몰랐는데 테이블 간격도 멀어서 더운날 친구랑 편하게 수다떨고 왔습니다 수박주스는 진짜 수박을 갈아 만드신거같은데 다른 카페들처럼 달지않아서 좋았어요 딸기라떼는 맛없없이고 평소에 스콘을 잘 안먹는편인데 다른곳보다 촉촉한 식감이라 배부른데도 맛있게 먹었습니다! 넓은 테이블도 있어서 학생분들 과제하러 방문하셔도 좋을거같아요!!', 40, 10, 'GOOD', SYSTIMESTAMP);
