INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '매장이 크고 메뉴랑 디저트가 다양해서 좋아요 ! 대화하기 좋고 좌석 공간 사이도 넓게 배치되어 있어 번잡하지않고 편리한 곳인 것 같습니다', 14, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '홍대에서 카페 찾으시는 분들 추천합니다! 원두 종류가 3개여서 취향에 맞게 선택가능하고 디저트도 다양하게 준비되어있어요🫶🏻 무엇보다 좌석이 많고 넓어서 웨이팅 걱정없음! 모임이나 인원많은 분들 꼭 가시길…!', 26, 2, 'GOOD', SYSTIMESTAMP);
