INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '홍대입구역이 아니고 홍대입구 진짜 입구 앞에 있는 아주 큰 대형 카페!!!일층에 위치에 있어서 진입이 아주 좋고 노트북 들고 와서 집중하기도 좋아요🤭🤭커피가 생각보다 너무 맛있었고 함께 먹은 얼그레이 스콘도 아주 맛있었습니다♥️좌석이 많아서 여러명 우루루 와도 괜찮을 정도고 소리가 안 올려서 생각보다 조용해요!', 21, 5, 'GOOD', SYSTIMESTAMP);
