INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '홍대에 이렇게 큰 대형카페가 있는 줄 몰랐어요 !! 매장 너무 넓고 시원하고 좋아용☺️ 얼그레이 스콘 짱 맛있고 수박주스도 진짜 찐수박 갈은 맛이라 맘에 들었어요💗💗 바닐라라떼도 맛있음 추천 ~~~', 72, 17, 'GOOD', SYSTIMESTAMP);
