INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '공간이 넓고 너무 쾌적해요 엄청 더웠는데 카페 들어오니까 살거같은 느낌 딱 피넛버터쿠키 먹고싶었는데 원했던 그맛 그대로여서 너무 좋았어요 허니자몽블랙 아이스티로 목 축이고 말차라떼도 너무 맛있을거같아서 마셔봤는데 크림 이랑 진짜 맛있어요 추천!!! 담에 또올게용', 6, 6, 'GOOD', SYSTIMESTAMP);
