INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '제에에발~!! 자두-자몽 히비스커스 에이드 드셔보세요...자두가 인공적인 맛이 아니라 진짜...진짜 자두...상큼 시원해서 흡수했어요 얼그레이티도 진짜 진~하고 별기대안하고 마셨는데 너무 만족스럽...홍대에 이렇게 작업하기 좋은 대형카페가 있어서 너무 좋아여', 48, 4, 'GOOD', SYSTIMESTAMP);
