INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '홍대입구역 9번 출구 마포평생학습관 코앞에 있는 홍대 대형 로스터리 카페인 카페삼사오에 머물렀다. 상콤달콤한 오렌지비앙코와 제철음료 수박주스, 향이 좋은 얼그레이 스콘으로 한낮의 더위를 식혔다. 매장이 넓어서 어디 앉든 시야가 훤히 트여 좋다.', 36, 4, 'GOOD', SYSTIMESTAMP);
