INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '홍대 주변에서 보기 힘든 대형 카페예요! 음식류도 많이 팔아서 커피랑 마실수있어 좋고, 자리도 1인자리부터 대형 테이블까지 다양해요. 홍익대 근처에서 미팅이나 팀플 등 있을때 모임장소로도 추천해요', 3, 10, 'GOOD', SYSTIMESTAMP);
