INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '홍대입구역 바로 근처에 있어 접근성이 너무 좋습니다! 여름에 먹는 수박주스 정말 달고 맛있었어요 스콘은 너무 부드러워서 앉은 자리에서 지인과 순삭했습니다 매장이 큰 편이지만 대화하기 무리 없어요!', 117, 20, 'GOOD', SYSTIMESTAMP);
