INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '알바생이신지... 남자 알바생분 바로 앞에서 여러번 불렀는데 쳐다보지도 않고 계속 할거만 하시고... 작게 부른것도 아니고 크게 불렀는데 일부러 안들은척 하는것처럼 보였습니다. 결국 뒤늦게온 여자직원분이 대응해주셨구요. 그리고 저희가 진동벨 드릴때도 한손으로 뺏어가듯이 가져가시던데 원래 이런 리뷰 안 남기는데 일하는 태도가 좋아보이진 않아 리뷰 남깁니다.', 9, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '매장도 넓고 커피, 음료, 디저트 종류가 많아서 좋아요! 홍대에 이런 대형카페 흔치않은데, 여기는 정말 넓네용 작업하기에도 데이트하기에도 좋습니다~', 94, 26, 'GOOD', SYSTIMESTAMP);
