INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '매장이 넓고 쾌적해서 좋아요! 감성있고 힙한 무드입니다 커피 원두도 세개 중 고를 수 있고 디카페인도 있네욤 홍대에 대형카페라 넘나 좋습니댜👍🏻😊', 17, 2, 'GOOD', SYSTIMESTAMP);
