INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '매장이 넓어서 혼자서도 좋고 길고 넓은 테이블도 있어서 간단한 미팅이나 소규모 모임을 하기에도 좋은 공간인 것 같아요!  피넛버터 쿠키는 짭조름하면서도 생각보다 부드럽게 부서지는 식감이 인상적이었어요! 겉은 살짝 바삭하지만 안은 촉촉하고, 은근히 쫀득한 느낌도 있어서 먹는 재미가 있더라고요!', 33, 4, 'GOOD', SYSTIMESTAMP);
