INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '외관부터가 왕왕 대형카페인거에요? 진짜 들어가자마자 완전 넓어서 단체로 오기 진짜 좋겠다고 1차로 생각, 자리 배치도 잘 되어 있어서 괜찮네 2차로 생각. 원두 종류 3개인거 보고 오? 좋은데! 하고 디저트까지 합격 목걸이 쥐어드립니다.스콘 너무 맛이숴요. 영업시간도 늦게까지 하고 홍대에서 이만한데도 없겠어요!!!', 29, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '홍대대형카페답게 매장이 엄청 넓고 쾌적해요. 매장이 깔끔해서 넘 좋았음! 커피 메뉴 다양하고 케익, 스콘, 쿠키, 크로플까지 디저트도 엄청 많더라구요ㅎㅎ 홍대입구역에서 가까워서 뚜벅이들 방문하기 넘 좋음!', 7, 2, 'GOOD', SYSTIMESTAMP);
