INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '홍대입구에 공부하면서 혼자 시간 보내려고 카페 찾다가 들어간 곳입니다!!! 보통 홍대쪽에 대형카페가 잘없어서 찾아다니고 있었는데 바로 발견해가지구 너무 좋았어요😊 분위기도 좋고 조용하고 잔잔해서 시간 잘 보내고왔습니다~!', 30, 9, 'GOOD', SYSTIMESTAMP);
