INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '진짜 쾌적한 카페입니다👍 테이블수도 많고 편하게 대화하거나 카공하기에도 안성맞춤이에요ㅎㅎ 사장님께서 말차라떼 추천해주셔서 마셔봤는데, 완전 맛있었고 수박주스도 시원하고 달달하게 잘 마셨어요!! 초코스콘은 말할 것도 없고요😋 다음에는 케이크 도전해보려고 합니다!', 52, 17, 'GOOD', SYSTIMESTAMP);
