INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '매장 크고 대화하기 편하네요. 부재시 30분후 분실위험 방지를 위해 고객의 음료 및 소지품을 수거하여 보관한다고 합니다. 1인 1주문이고, 카페 이용은 음료 한 잔당 2시간 미만으로 부탁한다고 하니 참고하세요.', 2, 0, 'GOOD', SYSTIMESTAMP);
