INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '여기 혼자오기도 좋고 음료가 맛나요 자몽히비스커스에이드 강추 그리고 바닐라빈라떼가 달지 않고 맛있어용🩷 그리고 수제피넛버터 쿠키가 고소해서 맛있었어요 저는 달지 않은걸 좋아하는데 달지 않아요 ~', 33, 9, 'GOOD', SYSTIMESTAMP);
