INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), 'ㅎ.ㅎ 친구들이랑 같이 왔는데 매장 넓어서 떠들기 좋아요~~ 오렌지 비앙코도 궁금했었는데 맛있어요!!! 시간이 늦어서 디저트는 품절이 많아가지고 안시켰는데 맛있어보야요', 36, 2, 'GOOD', SYSTIMESTAMP);
