INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '홍입역 왔다가 잠깐 과제하러 친구랑 들럿습니다.. 아이스크림 종류 다양하고 커피도 맛있어요! 원두 고를 수 있어서 산미 없는 고소한 맛 시켰는데 맛있네용🥰 넓어서 쉬었다가기 좋은 것 같아요! 다음에 또 방문하겠습니다~', 37, 4, 'GOOD', SYSTIMESTAMP);
