INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '홍대 입구에 위치한 감성카페 345 매장에 들어가자마자 넓고 쾌적한 분위기가 너무 좋았는데요 진짜 매장이 너무 깔끔해서 한번 놀라고 직원분들 서비스도 너무 좋았답니다 밀크티 오트카푸치노 얼그레이 스콘 이렇게 3가지를 주문했는데요 저도 현직 바리스타지만 이렇게 맛있는 카푸치노 정말 오랜만에 마셨습니다 ㅋㅋㅋ 또 마시고 싶은 생각이 분명 생기는 맛!! 얼그레이 스콘은 도대체 무슨 맛일까 엄청 궁금했는데 은은한 얼그레이 향이 입안에서 촤라락 퍼지며 스콘의 달달한 맛이 느껴지더라구용 진짜 너무 맛있었습니다', 40, 7, 'GOOD', SYSTIMESTAMP);
