INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '고구마라떼랑 말차라떼랑 초코스콘 먹었는데 고구마라떼는 꾸덕달달하니 한끼식사로도 손색없어요 완전 든든! 말차라떼도 너무 맛있고 특히 초코스콘이 너무 맛있습니당!! 또 가서 먹을래용 그리고 매장이 완전 넓고 느좋이라 기분전환하기 좋아요 히히', 118, 24, 'GOOD', SYSTIMESTAMP);
