INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '이른오전에 방문했는데 조용하고 넓어서 작업하러오기 좋아요. 주문한 음료랑 디저트도 독특하고 맛있어요. 홍대입구역이랑 가까워서 홍대에 나왔을때 접근성이 좋은것같아 자주 들를것같아요🤭', 35, 4, 'GOOD', SYSTIMESTAMP);
