INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '카페 345에 방문해서 여유로운 시간을 보냈습니다. 넓고 쾌적한 공간 덕분에 대화하기 좋았고, 직원분들도 친절했어요. 주문한 음료와 디저트 맛있어서 다음에 또 방문하고 싶습니다.', 62, 13, 'GOOD', SYSTIMESTAMP);
