INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '카페 분위기도 너무 좋고 더운날 시원하게 방문할 수 있어서 좋아요🤍🤍수박주스 완전 강추..😭🤍 더위 식히러 오시면 너무 좋을 것 같아요', 34, 4, 'GOOD', SYSTIMESTAMP);
