INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '바닐라빈라떼 제가 찾던 파우더 사용하는 바닐라라떼라서 너무 맛있게 먹었고, 심지어 수박주스도 리얼 수박 갈아주셔서 넘 맛있었습니다!! 홍대카페 찾는다면 요기 추천해요!!👍🏻👍🏻👍🏻', 32, 5, 'GOOD', SYSTIMESTAMP);
