INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '단체로오시면 좋을것같아요 많이 시끌벅적한곳이라서 묻힐수있슴댴ㅎㅋㅎㅋ 굉장히 활기찬곳이네용 한적할때는 좋습니당 커피도 맛있고 깔끔해요!', 3, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '매장이 굉장히 넓고 쾌적해서 단체 모임하기 좋고 분위기도 트렌디하고 힙한 느낌이라 너무 좋아요~ 바닐라빈라떼와 초코스콘 먹었는데 너무 맛있어용! 원두도 다양해서 너무 좋아용!!', 29, 5, 'GOOD', SYSTIMESTAMP);
