INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '홍대입구역에서 도보로 5분정도에 가깝게 위치한 대형카페였어요!! 매장이 진짜 넓고 깨끗했으며 음료와 스콘도(특히 스콘이) 맛있었어요😍 일찍부터 늦게까지 한다니까 더 좋은 것 같아요!!!', 32, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '사장님인지 직원인지 모르겠지만.... 진동벨 깜빡하고 안들고가서 커피 나온거 모르고 있었는데 커피 안받아간다고 화를내시네요^^ 커피 안받아가는게 화를 낼 일인지... 영수증 보여달라고 따지듯이 물어보길래 왜이렇게 공격적으로 하냐고했더니 진동벨 안챙겨갔냐고 챙겨야한다고 하면서 아무 사과도 없네요.. 차라리 스타벅스 갈걸 그랬어요 커피 안받고 나왔습니다. 많이 파세요', 4, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '크고 넓은 분위기 좋은 카페였어요✨ 인테리어도 감성적이라 사진 찍기 좋았고, 바질스콘이 넘 맛있었어요!! 음료 맛도 깔끔하고 디저트도 다양해서 선택의 폭이 넓어서 좋았어요~ 혼자 와서 여유롭게 시간 보내기에도 좋고, 친구랑 수다 떨기에도 좋은 곳! 자리도 넉넉해서 오래 머물러도 편안했어요☕️', 16, 4, 'GOOD', SYSTIMESTAMP);
