INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '음료가 진짜 맛있고 매장이 넓고 천장이 높아서 개방감있고 좋아요~! 그리고 여기 커피 로스팅된 원두도 고를 수 있고  초코스콘 진짜 맛있으니 꼭 드셔보세요!', 23, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '남자친구랑 할 일 하러 갔는데 카페가 넓고 쾌적해서 만족했습니다! 음료 종류도 다양하고 홍대대형카페여서 커피가 괜찮을까 걱정했는데, 충분히 만족하며 마시고 왔네욤 공부하실 분들 단체 모임 장소 필요한 분들 다 추천!', 38, 1, 'GOOD', SYSTIMESTAMP);
