INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '홍대 바로 근처에 있고 새벽 4시까지 운영해서 과제하기 넘 좋아요. 매장도 넓고 분위기도 좋습니다. 자두,자몽 히비스커스 에이드랑 신메뉴 피넛버터쿠키 먹었는데 진짜 맛있어요!! 추천드립니다!', 70, 16, 'GOOD', SYSTIMESTAMP);
