INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '매장이 크고 테이블이 많아 단체방문, 카공으로도 좋아요 메인거리에 있어 접근성도 좋고 스콘도 맛있습니다. 늦게까지해서 새벽까지 과제하거나 팀플모임하기 좋아요!', 90, 17, 'GOOD', SYSTIMESTAMP);
