INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '홍대입구역이랑 가까운 대형카페라 자주 오곤 합니다. 좌석이 많고 내부가 엄청 커서 친구들이랑 공부하거나 수다떨기도 좋아요. 화장실도 비번으로 잘관리되어서 쾌적해요!!😍', 87, 14, 'GOOD', SYSTIMESTAMP);
