INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '홍대에 이런 대형 카페가 있다니 쾌적하고 너무 좋아요!! 쇼콜라 라떼 컬스는 너무 달지 않고 질리지 않게 끝까지 먹을 수 있었어요! 그리고 피넛버터쿠키도 포만감있고 너무 고소해요ㅜㅜ', 11, 5, 'GOOD', SYSTIMESTAMP);
