INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '넓고 쾌적한 대형카페예요! 자리도 정말 많구 넓은 데스크테이블이 많아서 작업하는 사람들도 좀 보였어요 ㅎㅎ 저는 쇼콜라 라떼 컬스와 모카 라떼, 얼그레이 스콘 주문했는데요! 정말 달달하고 묵직한 초콜릿 라떼 컬스ㅜㅜ 첨 먹어봤는데 초콜릿 좋아하는 사람이라면 꼭 먹어보시길 😭 당충전하기 넘 좋았어요 ! 모카라떼도 맛있다고 해요 ㅎㅎ 홍대역에서 3분거리 엄청가까워요 밤늦게까지도 열어서 나중에 또 가보려고요💕', 122, 26, 'GOOD', SYSTIMESTAMP);
