INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '우선 매장이 넓고 쾌적해서 다수의 인원을 수용할 수 있다는 것이 큰 메리트 인 것 같아요! 콘센트도 넉넉해서 작업하기에도 공부하기에도 좋을 것 같아요. 직원분들도 친절하시고, 음료와 디저트의 종류가 많고, 맛도 있어서 홍대 근처 대형카페를 찾으신다면 추천드립니다 👍🏻', 9, 2, 'GOOD', SYSTIMESTAMP);
