INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), 'KAFFEE345는 홍대입구 9번출구에서 5분거리에 위치해 있는 카페에요. 홍대 메인거리와 완전 가까운 곳에 위치한 카페입니다. 바닐라빈 라떼가 맛있고 아이스크림 크로플이랑 스콘이 맛있더라구요. 원두도 선택할수 있고 공간이 넓고 무드가 있는 곳이라 홍대에서 머물다가기 좋은 카페인거 같아요~ 직원들도 친절하고 매장이 진짜 청결합니다', 6, 5, 'GOOD', SYSTIMESTAMP);
