INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '매장이 진짜 넓더라구요👍🏻 매장 자체가 넓은데 매장 안에 2인 테이블, 4인 테이블 그리고 단체로 앉을 수 있는 큰 좌석까지 다양하게 구성되어 있는 게 너무 좋아용! 음료와 디저트도 모두 맛있었는데 리얼 바닐라빈 라떼 추천합니다✨', 36, 5, 'GOOD', SYSTIMESTAMP);
