INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '홍대입구역 근처에 있는 넓고 쾌적한 대형카페예요. 패션망고에이드는 상큼하고 탄산감이 좋았고, 플랫화이트(LEICHT 원두)는 부드러워서 맛있게 마셨습니다. 올리브바질스콘은 담백하고 짭짤한 맛이 조화로워 커피와 잘 어울렸어요! 직원분들도 친절하고 매장도 청결해서 만족스러운 방문이었습니다 :)', 24, 3, 'GOOD', SYSTIMESTAMP);
