INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '다소 거칠어 보이는 직원분 외모에 움찔 했으나 청결에 신경쓰고 꼼꼼하게 메뉴 확인하는 모습에~ ㅎ 넓은 실내에 테이블도 여유가 있어 좋음 디저트 음료 맛도 좋고~^^', 118, 24, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '매장이 채광도 좋고 분위기도 좋아서 데이트코스로도 좋을 것 같아요! 특히 테이블도 단체석들이 많이 구비되어있어서 회의장소나 팀플하기 너무 좋을 것같고 늦게까지 운영해서 더더욱이나 자주 애용할 것 같아요👍👍완전 추천추천!!!', 29, 7, 'GOOD', SYSTIMESTAMP);
