INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '안녕하세요, 홍대에 있는 넓고 쾌적한 대형카페에 다녀왔어요 지인과 대화할 일이 있었는데 넓고 쾌적하고 커피 맛도 좋아서 이곳 방문한게 잘한 선택이란 생각이 들더라구요. 홍대쪽 오실분들 추천해요:)', 34, 2, 'GOOD', SYSTIMESTAMP);
