INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '매장이 넓고 쾌적합니다. 통창 근처는 컬러풀하고 화사한 느낌이라 시끌시끌 대화하기 좋고 반대편은 조용하고 깔끔함 블랙&우드 컨셉으로 혼자서도 노트북으로 작업하기 좋게 만들어져있어요.', 0, 9, 'GOOD', SYSTIMESTAMP);
