INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '항상 작은 카페를 가다가 여기 카페를 오니깐 엄청 넓어서 탁 틔인 느낌이라 좋았고, 홍대입구역에서 가까워서 자주 올 것 같아요! 날씨가 추워서 따뜻한 라떼랑 초콘스콘 시켜서 먹었는데 아주 맛있었어요!! 초코스콘은 겉바속촉이라 맛있으니깐 꼭 다들 드셔보세용💗 라떼아트도 예쁘게 해주셔서 마시면서도 기분이 좋았습니당☺️ 그리고 요기 금토에는 새벽4시까지해서 새벽작업 필요할때나 친구랑 늦게까지 놀때 또 방문할 것 같아요! ㅎㅎ', 37, 2, 'GOOD', SYSTIMESTAMP);
