INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '홍대 근처 매장 큰 대형카페가 있다고 해서 카공하려고 방문했어요!! 커피도 원두 세가지 골라마실 수 있는게 너무 좋았고 천장도 높아서 집중 너무 잘됐어요!! 카공하는 사람들 한 4-50% 정도 됐어요!! 홍대카페는 오래 머물기 애매한 곳들이 많은데 널찍하고 아침 8시부터 해서 아침공부하러 종종 올 예정입니다~! 직원분들도 친절하시고 스콘도 넘 맛나버렸어요👍😊', 77, 12, 'GOOD', SYSTIMESTAMP);
