INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '미쿠 팝업 때문에 아침에 줄 서 있는데 서있는 사람들한테 사장님인지 직원인지 나와서 욕설 날리셔서 무서웠어요…. 아이 데려온 부모님들도 많았는데 걱정돼서 리뷰 남깁니다', 21, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '홍대입구역에서 가까운 대형카페예요! 오늘 날이 너무 추운데 역에서 가까워서 금방 들어와 좋았어요 ☺️ 그리고 공간도 넓고 통유리라 개방감에 속이 트여요! ㅎㅎ 그리고 고구마라떼랑 쇼콜라라떼 컬스 마셨는데 맛이 깊고 다른 카페보다 더 맛있었어요! 진하고 맛이 깊달까요? ㅎㅎ 단체 모임 하기도 좋을 것 같네요! 자세한 리뷰는 여기에 있어요 🥰 https://blog.naver.com/ilfml_7/223753033986', 12, 6, 'GOOD', SYSTIMESTAMP);
