INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '바닐라빈 라떼가 시그니처 메뉴라더니 진짜 아래에 바닐라빈이 잔뜩 깔려있어요 ~!!😆👍 그리고 얼그레이 좋아해서 얼그레이 스콘도 함께 시켰는데 스콘에 얼그레이향이 엄청 진하고, 촉촉해서 당충전하기에 넘 좋앗어요', 65, 12, 'GOOD', SYSTIMESTAMP);
