INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '말차라떼 맛있고, 홍대근처에 회의하기 좋은 대형카페에요. 대형 테이블 좌석이 엄청 많고 걷고싶은거리 바로 시작에 있어서 찾아오기도 좋아요. 조용한편이라 공부하러오기도 좋을것같네요.', 8, 6, 'GOOD', SYSTIMESTAMP);
