INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '두번째 방문인데 커피도 맛있고 분위기도 너무 좋아서 다시 방문했어요!! 친구들끼리 얘기하기 너무 좋고 넓어서 자리 부족할 일은 거의 없더라구요~ 다시 방문할거 같아요!', 411, 38, 'GOOD', SYSTIMESTAMP);
