INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '홍대랑 가까워서 위치가 좋아요! 홍대에서 이정도 큰 카페가 몇 없는데 넓은데도 내부가 정말 청결했고 분위기가 좋네요! 대규모 인원으로 오기도, 혼자 작업하기도 좋을 듯한 공간! 무엇보다 영업시간도 길어요 ㅎㅎ 샤또라떼랑 올리브바질스콘 맛있었어요~', 54, 11, 'GOOD', SYSTIMESTAMP);
