INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '홀이 매우 넓어서 카공하거나 단체모임에 최적화되어있음. 팝업도 가능하다고하니까 매장으로 문의-! 홍대 대형카페 찾기가 은근히 힘든데 역이랑 가까운곳에 위치해있어서 접근성도 너무 괜찮음!! 층고도 높아서 답답함 없이 작업하거나 대화하기에도 좋음. ​ 대형카페는 음료나 디저트가 맛없을 수도 있는데 카페345는 둘 다 굉장히 신경쓰는 게 느껴짐! 콘센트도 자리마다 많아서 작업하기에도 딱 좋음!! ​ 원두선택도 가능하고 디카페인 원두도 준비되어있음! 홍대에서 넓은 카공하기 좋은 카페를 찾는다면 추천!', 16, 8, 'GOOD', SYSTIMESTAMP);
