INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '플랫화이트랑 스콘 맛집이네요!!! 조용히 작업하기 좋은 장소예요. 특히 오전엔 조용하고 아점으로 커피랑 스콘 조합으로 먹기 참 조아요 동네 살면 매일갈 것 같아요 ㅎㅎ', 105, 22, 'GOOD', SYSTIMESTAMP);
