INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '커피가 향이 좋고 맛있어요~!,아메리카노도 괜찮고 라떼가 너무 내취향~! 공간도 넓고 콘센트도 있어서 이 근방에서  찾기힘든 홍대입구 근처 대형홍대인것같습니다~', 358, 83, 'GOOD', SYSTIMESTAMP);
