INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '딸기라떼랑 초코스콘 치즈케익 냠냠 신선한 딸기로 만든 딸기라떼 달콤하지만 과하지 않아서 좋아요 초코스콘은 겉바속촉! 초콜릿의 진한 풍미가 느껴져 커피나 라떼와 잘 어울릴거같아요. 딸기라떼와 초코스콘도 괜찮은 조합이에요.', 33, 9, 'GOOD', SYSTIMESTAMP);
