INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '커피 쓴 맛이 거의 없이 깔끔한 맛의 아메리카노, 부드럽고 달콤한 딸기 라떼와 향긋한 올리브 바질 스콘까지 - 맛있는 후식 먹고 왔습니다. 매장 넓어서 편히 앉을 수 있어 좋았어요', 30, 0, 'GOOD', SYSTIMESTAMP);
