INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '식사 후 가볍게 방문하여 디저트와 음료 마시기에 좋았어요! 층고가 높고 공간이 넓어서 단체 손님들도 꽤 있었고, 노트북으로 작업하러 오시는 분들도 많은 핫플이더라구요💕 원두 종류도 많고 핸드드립이 유명하다 하여 다음에는 핸드드립 커피를 마셔볼 예정입니다!', 103, 23, 'GOOD', SYSTIMESTAMP);
