INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '커피숍은 많은데 커피 잘하는 곳 찾기 쉽지않은데 커피맛으로 승부하는 곳 같아요! 아이스크림 맛나요!!아포카토 갬동!! 홍대역에서 가깝고 매장이 완전 넓어 대화를 나누기에도 좋고 1-2인 테이블이 꽤많아 카공하기에도 좋아요!', 128, 19, 'GOOD', SYSTIMESTAMP);
