INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '오랜만에 홍대에서 데이트했어요! 홍대입구랑 가까워 저녁먹기전 방문했는데 원두도 3가지 중 고를수 있고 아인슈페너 크림도 너무 부드럽고 스콘은 꼭 먹어보세요🖤', 43, 9, 'GOOD', SYSTIMESTAMP);
