INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '대형카페여서 노트북으로 작업하시거나 팀플 또는 과제하기 좋을 것 같아요 다만 집중해야 하는 공부는 매장에 음악이 나와서 괜찮으신분들만 추천드리겠습니다 플레이리스트가 정말 취향저격이었고 바닐라라떼가 안달고 고소한 곳은 오랜만이어서 너무 맛있었어요 매장도 너무 넓어서 탁 트인 느낌이 좋았답니다 매장이 커서 공간감도 있고 무엇보다 크리스마스 트리가 너무 예쁘네요 🎄 직원분들도 친절하셨고 잘 머물고 수다 잘 떨다가 가요 근처나 홍대에 또 올 기회가 생기면 다른 음료도 먹어보고 싶네요!', 324, 56, 'GOOD', SYSTIMESTAMP);
