INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '홍대입구 공부하기 좋은 카페 찾다가 방문하게 되었는데 매장이 엄청 넓고 쾌적해요! 조용해서 공부하거나 노트북하기에 딱좋습니다. 또 디저트 메뉴들이 다양해서 좋았답니다.❤️', 60, 14, 'GOOD', SYSTIMESTAMP);
