INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '직접 로스팅하는 곳이라서 커피가 맛있는 곳이에요. 매장에서 스콘 먹어보고 맛있어서 집에 갈때 스콘 하나 더 포장해갔어요 매장도 넓고 조용해서 좋았습니다. 무언가 작업할일이 있을 때 가면 좋을 것 같아요.', 85, 15, 'GOOD', SYSTIMESTAMP);
