INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '얼그레이스콘이 엄청 맛있었고, 늦은 시간까지 이용할 수 있어서 넘넘 좋았어요! 공간이 넓고 빔프로젝트로 가능해서 팝업공간 하기도 좋을 것 같아요~!!', 105, 20, 'GOOD', SYSTIMESTAMP);
