INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '매장도 넓어서 단체손님도 꽤 있었어요. 콘센트 있는 곳에 앉아서 작업했는데 편하게 일하기 좋았어요. 음료도 맛있었고 쿠키도 추가로 주문해서 먹었는데 맛있었어요!', 32, 8, 'GOOD', SYSTIMESTAMP);
