INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '커피맛집 찾다발견한 홍대입구 커피맛집 발견! 젊은 남자사장님들이 운영하시는거같은데 커피부터 디저트까지 야무딱지게 개맛있음 대추천 넓은 1층이고 소리가 좀 울리는편이나 맛이 좋아서 무조건 재방문할듯 아이스아메리카노 ₩4,500 아아도 산미없이 고소하고 탄맛이 심하지않아 좋았음 양이 조금 적게 느껴져서 아쉽, 쪼롭 몇번하니 금방 없어짐 얼그레이 케이크 ₩6,500 처음에 케이크 얇기보고 조금 실망스러웠는데 맛은 확실히 있음 아주 존맛탱, 크림도 안느끼하고 밑에 묵직한 파운드케이크같은빵도 얼그레이 크림과 잘 어울렸음 다만 끝쪽에는 빵은 없고 크림밖에 없어서 너무 아쉽...', 45, 10, 'GOOD', SYSTIMESTAMP);
