INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '저번에 한번 가보고 괜찮길래 재방문 했어요. 홍대 카페들이 사람이 다 많은데 공간이 넓어서 좋았어요. 화장실도 깔끔해서 더 좋아욤!!!!😀', 89, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '홍대에서 위치도 좋고 매장도 넓어서 좋아요. 친구랑 얼그레이 스콘 먹었는데 너무 맛있더라구요. 얼그레이 향과 맛이 느껴져요 라떼도 너무 맛있고 여기는 커피 원두도 선택 가능하고, 디카페인도 선택 가능해서 좋네요. 친구는 콜드브루도 맛있다고 하네요 이렇게 홍대 가까이 커피맛집이 있어서 좋네요 매장이 넓고 화장실도 쾌적해서 좋아요 직원분들도 친절하고 좋아요 홍대 있을 때 친구랑 만남 있을 때 오기 편하고 좋은 것 같아요💛💛', 24, 6, 'GOOD', SYSTIMESTAMP);
