INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '카페345 홍대에서 발견한 완전 큰 대형까페 북적이지 않고 무엇보다 커피 종류도 많고 맛있음 디저트는 얼그레이 스콘 추천합뉘다', 129, 24, 'GOOD', SYSTIMESTAMP);
