INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '원두도 세 가지 중에 선택할 수 있는데 고소한 맛 너무 맛있었어요. 크리스마스 트리 있어서 연말 느낌도 나더라고요. 수제 스콘에는 마카다미아가 듬뿍 들어있어서 놀랐다는!!', 19, 5, 'GOOD', SYSTIMESTAMP);
