INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '우선 홍대에 많은 카페를 가봤지만 이렇게 널찍한 카페가 있었나 싶을정도로 넓어서 쾌적했습니다! 원두는 3가지 중 고를 수 있어 단체 손님이 방문했을때 커피 취향이 달라도 괜찮겠더라구요 스콘 맛집 입니다 커피랑 아주 잘어울려요', 46, 0, 'GOOD', SYSTIMESTAMP);
