INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '매장이 엄청 넓어서 왜 대형카페인지 바로 납득가능 ㅎㅎ! 홍대에 이렇게 큰 카페는 처음이었어요! 테이블도 다양해서 여럿이가도 수용가능이더라구요 대규모 인원에게 완전 적합한 카페로 추천해요!', 38, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '연휴동안 친척들과 홍대 돌아다니다가 발견한 카페입니다! 매장이 넓고 쾌적해서 다인원도 수용 가능해서 좋았구 커피 선택지가 다양해서 고르는 재미가 있었어요! 다음에 다른 커피 마시러 또 오고싶네욤! 아이스크림은 사촌동생 픽인데 아이스크림 부드럽구 초코는 빠쟉하니 좋아하더라구용👏 종종 오고싶은 카페입니당🤍', 6, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '대형카페라서 공간이 엄청 넓고 자리도 많아서 좋았습니다. 음료랑 디저트도 맛있고 직원분들도 친절해요. 홍대에 대형카페 있는지 처음 알았는데 쾌적해서 자주 갈 것 같네요. *업체로부터 식사권을 일부 제공받았습니다.', 12, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '매장이 넓고 쾌적해요 낮에도 좋은데 새벽늦게까지 해서 너무너무 좋아요ㅠㅠ 그리고 잔나비 뜨여남품 나오는점도 아주 맘에 들어서 리뷰를 쓰게되었어요 오래오래 있어주세요 카페삼사오오오', 4, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '저랑 친구는 드립커피를 각각 다른 걸로 주문을 했는데 커피 문외한이라 구분 못할 것 같았는데 다행히 커피 이름이 적힌 카드를 주셔서 쉽게 구분할 수 있어서 센스있다 싶었어요. 바디감이 있는 다크원두 성분이 충분히 활성화되어서 가장 좋은 휘발성 커피향이 나타나고 있는 포인트까지 로스팅하여 쓴맛보다 다크초콜릿의 향미를 살리는 좋은 커피와 과일과 꽃향의 플레이버를 나타내기 위해서 로스팅 시간이 상대적으로 다크보다는 짧고 배출 온도가 낮지만, 로스팅 열을 부드럽게 조정하여 자극적인 산미 대신 달콤한 과일의. 산미를 Tea처럼 표현한 로스팅까지 커피를 잘 모르지만 평소 마시던 커피보다 향긋하고 텁텁함이 없어 입에 맞더라구요~ㅎㅎ', 40, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '대형카페이고 음료&디저트 종류가 다양하고 맛있어요 데이식스 좀비가 나와서 좋았어요ㅎㅎ 와이파이 속도는 조금 느리지만 그래도 있습니다', 6, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'WIFI');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '음료가 맛있고 매장이 매우 커서 부담없이 시간을 보낼 수 있었습니다 깔끔하고 다인원으로 매장을 찾을 시 이 카페 괜찮을 것 같아요 홍대입구역 근처에 있고 접근성도 굿굿', 37, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '8명이 왔는데 계속 기분 나쁘게 직원 분들 네 분이서 곁눈질로 쳐다보시다가 와서 하는 말이 7잔밖에 안 시키셨다고 1인 1메뉴 하라고 하네요 화장실 급해서 비번 알려달라고 하니까 네 자리 숫자 말하는 게 어려운지 영수증 하단 보세요 ^^ ㅋㅋ 그렇게 굳이 어렵게 간 화장실은 세면대가 고장 났어요! 그냥 매너들이 딱 요즘 희화화하는 인스타 감성 카페 같아용!', 6, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '매장이 넓고 직원분들 친절해요. 테이블이 좀 다닥다닥 붙어 있는것 같아요. 커피는 신맛이더라구요. 전 고소한 맛을 좋아해사 ㅎㅎ', 57, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '홍대 놀러갔다가 리뷰가 좋아서 갔어요~! 매장이 진짜 넓어요! 날씨가 더웠는데, 에어컨 빵빵하니 넘 좋았고, 무엇보다 조용해서 좋았습니다 ㅎㅎ 공부하시는 분들도 계시더라구요. 커피 원두도 두종류라 선택 가능 하고, 커피 맛도 좋았습니다👍', 9, 9, 'GOOD', SYSTIMESTAMP);
