INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '홍대에 보기 드문 넓고 쾌적한 카페 발견😆 커피랑 케익도 맛있어서 자주 방문 할 것 같아요 ㅎㅎㅎㅎ 얼그레이 케익짱맛… 직원분들도 친절하셔서 기분 좋게 친구들이랑 쉬다가 갑니당ㅎㅎ', 127, 25, 'GOOD', SYSTIMESTAMP);
