INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '홍대에 이렇게 넓은카페 많지않은데, 매장도 엄청 넓고 확 트여있어서 너무 좋아욤!! 아이스크림이 먹고싶어서 방문했는데 아이스크림도 우유맛이 진해서 맛있습니당', 80, 17, 'GOOD', SYSTIMESTAMP);
