INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '홍대입구역, 홍익대학교 근처에 있어서 접근성이 좋고 음료와 디저트 모두 맛있는 카페! ​ 내부 인테리어가 특이해서 사진 찍기도 괜찮고 희한하게 사람들이 많은데도 많이 시끄럽지가 않더라고요! ​ 그래서 공부하기에도 괜찮은 카페이고 내부 인테리어하실 때 방음을 튼튼하게 하신건진 모르겠지만 수다 떨어도 전혀 눈치 보이지 않는 분위기!', 28, 7, 'GOOD', SYSTIMESTAMP);
