INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '매장이 넓고 시원해서 좋았고, 음료 맛있게 먹고 왔어요🤍 커피 원두 종류도 고를 수 있고 디저트도 마련되어 있더라고요 :) 더운 여름 쾌적하고 편하게 머무르다 가기 좋은 카페라, 홍대 대형카페로 추천할만한 곳이에요!', 49, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '아침에 문 연 곳이 별로 없어서 기대없이 들어와봤는데 매장이 넓고 쾌적하고 좋네요. 일행이 디카페인만 마셔서 주문해봤는데 주문 들어오면 원두를 그때그때 갈아서 내려주고 커피맛도 좋아요', 26, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '진동벨이용 홍대 우동서 점심먹고여기옴 늘봄가든 예약 예매 되있어서 진동벨 이용 해야함 키오스크옆에진동벨이 싸여있는데 그거보고 선택하는건데 그낭 17찍음 마침있었 뒤늦게발견 화장실다녀오니진동울림 처음보고 6500씩이나하는데 육각형머지이거 양이쩍어 쥐새기야? 혼자말 맛은있음고급짓만', 49, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '매장으로 들어올 땨 부터 커피향이 그윽하게 나서 기분이 좋았고 아인슈페너는 달디단 크림과 커피의 조합이 잘 어울렸어요 허니자몽블랙티는 상큼한 티라 상쾌하게 마실 수 있어 좋았네요 만족스러워요', 1, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '커피 맛은 괜찮은데 얼음을 너무 적게 줘서 리필 안받으면 얼음 금방 다녹고 안시원했어요. 키오스크에서 시간도 평균 걸리는 시간보다 더 걸리더라고요. 직원 대응도 별로였고 좀 껄렁댄다...?란 느낌 드는 곳이였어요.', 1, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '홍대카페 카페345 다녀왔어요, 주변에 이렇게 큰 대형카페가 없어서 내부도 시원하고 천장이 높아서 좋았어요 핸드드립 커피 파나마 마셨는데 너무 맛있어요 시나몬 스콘은 빵같은 촉촉한 스콘이에요 안에 마카다미아랑 초코칩이 들어있어 맛있어요', 11, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '넓고 다 좋은데 음료 양이 너어어무 적어요. 5천원~7천원대 가격인데 200ml는 넣었으려나요. 남자 입장에서 두세모금이면 끝나니 그 점은 참고하시길.. 맛은 좋습니다.', 3, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '다크로 원두 선택해서 먹었는데 커피는 맛있고, 크로플 자체도 맛있는데 데워줬으면 좋았을텐데, 그냥 바로 내주어서 표면이 너무너무너뮤너무 바삭해서 약간 딱딱할 정도라 칼로 잘 안 썰리더라고요. 그래서 맛도 그냥 쏘쏘였어요. 크로플은 데워주면 더 좋을 거 같아요!', 45, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '홍대 골목길에 우연히 발견한 카페. 규모가 상당히 큽니다. 매장내 테이블도 간격이 널직해 쾌적한 상태에서 커피 한 잔 하기 좋은 것 같습니다. 밀크티 아이스 주문했는데 맛있게 잘 마셨습니다. 간단히 업무보기에도 좋은 것 같네요.', 122, 20, 'GOOD', SYSTIMESTAMP);
