INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '매장이 넓고 분위기 좋아서 대화하기 좋아요! 음료 금액도 괜찮고 커피도 맛있습니다 👍 홍대에서 카페 찾고 있다면 카페 345 와서 편히 쉬다 가는 것도 좋을것같아요!!', 101, 23, 'GOOD', SYSTIMESTAMP);
