INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '매장도 넓고 그래서 친구들과 함께 오기에도 좋고 특히 핸드드립 커피가 퀄리티가 정말 좋아요. 다른곳보다 훨씬 더 퀄리티 좋은 핸드드립커피^^ 진심  맛있어요 추천', 115, 22, 'GOOD', SYSTIMESTAMP);
