INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '아메리카노 다크로 선택했는데 원두 제가 딱 좋아하는 맛이에요! 맛있어요!! 크로플+아이스크림 세트도 있어서 아이도 잘 먹었습니다❤️ 매장 넓고 시원하네요 ㅎㅎ 위치도 좋아서 홍대 지나다가 다음에 또 들리겠습니다😁', 17, 8, 'GOOD', SYSTIMESTAMP);
