INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '핸드드립 커피 맛집! 파나마랑 콜롬비아 선택했는데 둘다 깔끔하고 풍미가 깊어요~ 직접 로스팅하신다고 하던데 그래서 그런가 향도 좋고 맛도 좋습니다. 스콘도 촉촉하니 맛있어서 드립커피랑 잘 어울리더라고요✨ 서교동 카페는 여기! 드립커피 맛집!', 68, 18, 'GOOD', SYSTIMESTAMP);
