INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '직접 로스팅한 커피와 달달새콤한 허니자몽블랙아이스티 그리고 시나몬 스콘 주말을 맞이하기전 금요일 밤에 즐기기에 정말 좋았던 조합이었습니다! 특히 커피향과 맛은 다른곳에서 느끼기에는 힘들것 같다는 생각이들었습니다.', 111, 19, 'GOOD', SYSTIMESTAMP);
