INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '엄청 넓고 쾌적했던 매장! 아아메도 4500원이고 디저트 케이크도 6,500-7,000원대로 합리적인편 홍대에서 이정도로 넓은 곳은 처음이라 좋았다 또 갈듯 ㅋㅋ', 84, 16, 'GOOD', SYSTIMESTAMP);
