INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '평소 핸드드립 정말 좋아하는데 ㅎㅎ 홍대 카페 삼사오의 핸드드립 저렴하면서도 맛도 좋아요! 초코칩 쿠키는 바삭하고 초코칩이 정말 한가득,,, 게다가 공간이 넓어 단체 인원 수용도 문제없겠더라고요! 전 개인적으로 카공하러 다시 재방문하고 싶어집니다 ㅎㅎㅎ', 48, 4, 'GOOD', SYSTIMESTAMP);
