INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '매장이 엄청 넓고 상이 대체로 적당한 높이라 좋아요 의자 등받이 있는 것도 너무 좋구요 🖤 핸드드립 커피 맛볼 수 있어서 더더더 좋아요 🖤🖤 스콘도 맛있으니 추천이에요!!', 4, 4, 'GOOD', SYSTIMESTAMP);
