INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '쓰흡.. 남친이 사진 찍기 전에 휘저어버림... 맛은 아주 아주 달고 맛있다고 합니다.. (...) 얼어 죽어도 아이스만 마시는 저는 허니자몽블랙티를 마셨습니다 요새 티 종류에 빠져서 이것저것 마셔보는 중인데 이것도 마시기 괜찮은 거 같아서 다른 곳에서도 마셔봐야겠어요 ㅎㅋㅋㅋ 매장도 넓고 깨끗해서 웨이팅 없이 앉아서 얘기 나누기엔 참 좋을 것 같습니당', 115, 26, 'GOOD', SYSTIMESTAMP);
