INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '홍대카페345 드리커피 맛집이에요. 친구는 파나마 잔슨 클래식 게이샤 워시드 저는 콜롬비아 라 마카레나 옐로우 타비 둘다 만족스러웠어요. 거기다가 얼그레이 스콘까지 잘 어울려 최고의 디저트와 커피를 마시고 왔어요. 홍대에 오셔서 직접 내린 수제 드립 맛보시는 거 추천 드려요.', 87, 18, 'GOOD', SYSTIMESTAMP);
