INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '매장이 넓고 쾌적해요. 커피도 맛있고 시나몬쿠키도 맛있어요. 넓은 공간이라 단체 방문도 가능할 것 같아요. 홍대와 가까워서 접근성도 좋아요.', 34, 5, 'GOOD', SYSTIMESTAMP);
