INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '1월 평일 오전 10시30분. 홍대길을 거닐다가 일하려고 조용한 카페를 찾았는데, 편안한 분위기에 음악, 커피도 맛있네요. 😁', 89, 14, 'GOOD', SYSTIMESTAMP);
