INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '홍대 데이트 하러 나왔다가 노란색 간판이 눈에 띄어서 들어갔는데 매장이 넓고 쾌적하네요 파마나 게이샤 핸드드립 커피 마셔봤는데 복숭아 향이 독특하고 맛있었어요 커피연구실도 한켠에 있는 것 보니 커피에 진심인 곳인 것 같았어요 편하게 머물다 갑니다', 24, 3, 'GOOD', SYSTIMESTAMP);
