INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '커피 원두는 두가지 중에 택할 수 있고 커피 맛있어요 ! 산미 땡길 때는 산미있는걸로 아님 없는걸로 딱 두가지라 결정장애 있으 신 분들한테 편하구여 케이크 종류도 다양해서 취향대로 입맛대로 고르시면 됩니다. 매장이 트여 있어서 좋아요. 케이크 + 음료 시켜놓고 수다떨기 좋은 공간 👍🏻', 84, 15, 'GOOD', SYSTIMESTAMP);
