INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '겉만 보고는 들어가면 안되나 싶었는데 (팬카페 같아서) 들어가보니 엄청 크고 쾌적해요. 커피가격에 비해 양이 적네 생각했는데 엄청 맛있어요. 저는 신맛 좋아하는데 깔끔하고 향도 좋아요.', 54, 18, 'GOOD', SYSTIMESTAMP);
