INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '디카페인커피가 있어서 카페인 못드시는 엄마도 모시고 올수 있었어요!! 커피도 진하고 고소하고 정말 맛있었어용 그리구 사장님 진짜 대박 친절하셔요🥹 감동.... 인류애 충전하고 갑니당ㅠㅠ', 82, 12, NULL, SYSTIMESTAMP);
