INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '다채로운 맛이 나는 핸드드립 커피를 맛볼 수 있는 카페입니다. 실력 좋은 바리스타가 본인이 의도한 맛과 향을 정확하게 구현하기 때문에 커피를 두개 주문해 맛을 비교해가며 먹기 좋았습니다. 1. 층고가 높아 개방감이 있고, 테이블 간격이 넓어 옆 사람을 신경쓰지 않고 편하게 앉아있을 수 있습니다. 직원분께서 매장을 정말 청결하게 관리하는 것을 앉아있는 내내 볼 수 있었습니다. 2. 테이스팅노트에서 설명한대로의 핸드드립 커피을 맛볼 수 있습니다. 특히 파나마 게이샤 워시드 원두는 마셨을 때 베르가못과 복숭아향이 은은하게 입안을 맴돌고 삼킨 이후에도 입 속에 잔향이 맴돌았습니다. 3. 바리스타가 잘생겼습니다. 진심.', 45, 10, 'GOOD', SYSTIMESTAMP);
