INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '핸드브루잉 종류가 다양해서 묵직한 바디감부터 산뜻한 산미감까지 즐기기 좋은 카페345! 정량으로 무게 재서 그라인딩부터 드립까지 정성 가득했어요♡', 32, 2, 'GOOD', SYSTIMESTAMP);
