INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '홍대거리를 한참 돌고 비니도 모자도 사고 다리가 아픈데 편하게 앉아 커피 & 아이스크림 먹으며 오래 쉬기 편합니다. 잠이 오네요. 쵸코렛코팅 밀크 아이스크림 맛있네요.', 18, 8, 'GOOD', SYSTIMESTAMP);
