INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '핸드드립 커피 진짜 맛있어요!@ 파나마 잔슨 게이샤 워시드로 먹었는데 대감동..! 너무너무 맛있어요 !! 산미가 살짝 있는데 너무 향기로워요!! 그리고 쿠기도 마카다미아가 한가득 들어있어서 넘넘 맛나요!!', 46, 7, 'GOOD', SYSTIMESTAMP);
