INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '어디가지 하고 정처없이 걷다가 들어왔어요 목말라서 그런가 가격에 비해 커피 양이 적어서 아쉬웠지만 맛은 있었어요!ㅎㅎ 아주 자리가 많고 큰 카페여서 잘 쉬다가 갑니다', 16, 3, NULL, SYSTIMESTAMP);
