INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '커피 너무 맛있었습니다! 친구들이랑 더워서 다들 당떨어진다.. 카페인 땡긴다 하다가 들어간 곳인데 원두종류도 여러가지고 핸드드립 커피 맛이 넘 좋아서 만족했습니다 얼그레이 쿠키도 맛있었어요 다음엔 다른 쿠키도 종류별로 먹어보려구요', 39, 6, 'GOOD', SYSTIMESTAMP);
