INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '홍대 이런 대형카페  있는줄 몰랐네요 직접 로스팅해서 커피판매하는 드립커피전문점이기도 하면서 노말카페이기도 한듯~ 비가와서 따뜻한 드립커피주문햇는데 콜롬비아산커피 너무 맛있어용:) 좌석많아서 좋아요:)', 33, 10, 'GOOD', SYSTIMESTAMP);
