INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '홍대입구역카페로 브루잉 커피가 맛있는 대형 카페입니다.  브루잉 커피 2종류를 ICE로 주문하고, 바스크 치즈 케이크를 추가했습니다. 매장 인테리어도 멋지고 쾌적해서 요즈음 같은 더운 날씨에도 홍대데이트를 즐기기 좋은 곳입니다. 매장에서 직접 로스팅해서 맛있는 핸드드립 커피를 마실 수 있습니다. 전 파나마 잔슨 클래식 게이샤 워시드(ICE)를 주문했는데 맛이 깔끔하다는 생각이 들었습니다.  카페345는 홍대정문과 홍대입구역 사이에 있고, 가까이에 마포평생학습관도 있습니다.', 28, 10, 'GOOD', SYSTIMESTAMP);
