INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '매장에서 직접 로스팅한 원두로 제공되는 서교동카페👍 에스프레소나 핸드드립 커피 종류도 많아서 취향에 맞게 골라마시는 재미도 있고, 카페345만의 프라이드가 느껴지는 원두설명을 읽는 재미도 있다. 그리고 홍대에서 프렌차이즈 말고 이렇게 큰 카페 처음 봤음👏👏 매장이 넓고 깔끔해서 너무 좋아따', 31, 1, 'GOOD', SYSTIMESTAMP);
