INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '커피는 아메리카노 시켰는데 깔끔하고 괜찮았어요! 양이 아쉽 ㅜ 매장은 널찍해서 좋았는데 화장실이 조금 관리가 안된 것 같아서 아쉬웠습니당 ㅜㅜ', 39, 1, NULL, SYSTIMESTAMP);
