INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '후기에 쿠키가 꾸덕하다고 해서 주문했는데, 너무 딱딱하네요... 조금 아쉽.. 커피는 맛있어요. 쾌적하고 넓어서 앉아서 업무 보기 좋아요!', 0, 2, NULL, SYSTIMESTAMP);
