INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '무심코 들어간 카페였는데 핸드드립 맛집이었어요...🤍☕️ 얼그레이 쿠키랑 너무 잘 어울리는 브라질 원두 커피였는데 진짜 깔끔하고 향도 너무 좋았답니당.. 카페 내부도 널찍해서 좌석들도 많구! 혼자 작업하기도 좋았던 공간입니당!', 24, 5, 'GOOD', SYSTIMESTAMP);
