INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '커피가 진짜 맛있어요! 안 쓰고 커알못이지만 뭔가 깊이가 느껴지는..? 진짜 커피 자체가 맛있어서 라떼 이런거 먹어도 대존맛일거 같아요!!!! 저는 다크 원두로 먹었는데 요건 산미가 전혀 없어서 좋아요! 산미 있는건 라이트엿던거 같아요!', 69, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '너무 더워서 잠깐 쉬려고 들어갔는데 매장도 깨끗하고 엄청 넓어서 좋았습니다. 아이스크림 존맛.. 다만 레모네이드는  레몬맛은 밍밍하고 맛은 너무 써서 좀.. 차라리 체리콕 시킬껄 후회했습니다.', 45, 6, NULL, SYSTIMESTAMP);
