INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '서교동 카페 찾다가 카페345 방문했어요🙂 넓고 좌석 간 간격도 넓은 편이라 좋았는데 핸드드립 커피까지 맛있어서 더 좋았습니다ㅎㅎ 서교동 카페 중에 넓고 쾌적한 곳 찾는 분들은 카페345 가보시길 바랄게요!', 32, 9, 'GOOD', SYSTIMESTAMP);
