INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '커피 원두가 다양해서 취향에 맞게 고를 수 있는 부분이 좋았어요 커피에 대해서 잘 모르는데 설명을 너무 잘 해주셔서 편하게 고를 수 있었고 원두를 시향해볼 수 있는 부분이 재밌기도 했어요:) 얼그레이 쿠키 안에 마카다미아(?)가 들어가 있어서 고소하고 맛있었구 대화하기 좋았습니다. 벽이 흰색이라 사진이 아주 잘 나오더라구요. 작업하시는 분들이 많아서 미팅이나 작업할때 방문하기 좋은 카페라고 생각합니다:)', 56, 11, 'GOOD', SYSTIMESTAMP);
