INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '블루잉 커피 향이 미쳤어요 커알못이 마셔도 느껴지는   브루잉커피의 매력 ㅎㅎㅎ 가성비도 좋고 수제쿠키더 커피랑 정말 잘어울렸습니다 인테리어까지 펄팩트!!!', 42, 4, 'GOOD', SYSTIMESTAMP);
