INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '직접 로스팅한 원두로 만든 핸드 드립 커피를 맛볼 수 있어서 색달랐어요 원두에 대한 간단한 설명도 적어주셔서 커알못이지만 지식이 쌓이는 기분이었던ㅎㅎ 쑥쿠키는 재료가 조화로운 맛이라 맛있게 먹었어요 핸드드립 커피 마시러 재방문하고 싶어요😚', 53, 12, 'GOOD', SYSTIMESTAMP);
