INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '인테리어가 애매해서 긴가민가하며 들어왔는데, 커피가 정말 맛있어요♡안쪽에 로스팅룸도 있고 핸드드립과 로스팅원두메뉴도 있는거 보고 기대했는데. 역시 기대만큼 맛있습니당~ 연한원두타입은 꽃향과일향나는 상큼한 커피였고 저는 다크 마셨는데, 너무 쓰지않고 딱 좋아요 에어컨이 세서 좀 춥네용ㅎㅎ', 193, 67, 'GOOD', SYSTIMESTAMP);
