INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '매장도 깔끔하고 넓고 핸드드립 커피 너무 맛있고 좋네요 여러명 방문해도 취향따라 즐기기 좋아요 원두 설명 카드도 좋아요 커피지식 +1된 기분☺️', 55, 15, 'GOOD', SYSTIMESTAMP);
