INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '드립커피 섬세한 맛이 느껴지고 깔끔하고 넘 맛있어요~~!!  공간이 넓고 쾌적하고 정말 편해요~ 얼그레이 쿠키 마카다미아가 듬뿍 얼그레이향도 좋으네요:)  자주 오게 될거 같아요', 57, 16, 'GOOD', SYSTIMESTAMP);
