INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '로스팅 기계도 있고 뜨아 넘 맛아유!.! 쿠키도 맛나융 커피맛이 일품이네요 전시회때미 왔다가 커피맛에 반하고 갑니다. 그리고 무엇보다 친절하세요!!! 잘먹고 갑니다', 54, 12, 'GOOD', SYSTIMESTAMP);
