INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '홍대 카페는 일단 기본적으로 좁고 테이블이 다닥다닥 붙어있어서 시끄러운 곳이 많은데 카페345는 카넓고 쾌적해서 친구와 대화하기도 너무 좋았어요 드립커피 맛집이라 드립커피 주문했는데 원두 선택할때 친절하게 설명도 해주시고 브루잉 하는 것도 바로 볼 수 있어서 좋더라구요-!! 또 카페345는 커피에만 진심인 것이 아니고 디저트에도 진심이니 디저트를 꼭 먹는 것을 추천합니다 :) 꾸덕끄덕한 쇼콜라 케이크는 진한 커피와 너무 잘 어울리고 맛있었어요!', 36, 3, 'GOOD', SYSTIMESTAMP);
