INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '진짜 홍대입구역카페 중 커피 최고 맛집이에요. 매장도 넓어서 단체로 와도 좋을 것 같고 적당한 산미에 커피 특유의 초콜릿 맛과 넘 조화로워서 또 올 것 같네요. 역이랑도 가까워서 모임 끝나고 집 가기도 편해요.', 5, 0, 'GOOD', SYSTIMESTAMP);
