INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '여기 핸드드립 커피 진짜 개존맛..👍🏻 원두 선택했는데 설명되어있는 종이도 같이나오고 쇼콜라케익도 개존맛탱이었어요~ 가나초콜릿맛임🤎 직원붙들 엄청 친절하셨고 핸드드립 해주신분 잘생기셨어요🥰 매장도 넓고 화장실도 깨끗햇어요!!! 핸드드립 개존맛 💕', 17, 2, 'GOOD', SYSTIMESTAMP);
