INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '치아바타도 같이 시켯는데 당당히 음료만 주고 진동벨도 다시안주고 황당하네요ㅋㅋ영수증보여주고 그제서야 진동벨 다시주고 만들어준다함..', 33, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '핸드드립으로 파나마 잔슨 클래식게이샤워시드랑 콜롬비아 라 마카레나옐로우타비 시키고 초코마카다미아 쿠키 시켰는데 산미 좋아하시는 분들은 콜롬비아 커피 진짜 좋아하실거 같아요. 아이스로 마셨는데 엄청 시원하고 산뜻하고 청량감있어요~ 그리고 초코 마카다미아쿠키 대박이예요!!! 마카다미아가 통으로 완전 잔뜩 들어있고 초코도 맛있는 초코예요!!! 대만족♥️', 108, 20, 'GOOD', SYSTIMESTAMP);
