INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '메뉴 고민되서 추천받았는데 핸드드립 너모 괜찮았어요!!! 은은하게 꽃향기가 남는게 신기하구 부드럽고깔끔하네여진쨔! 좌석도 넓어서 좋았습니다👍🏻 감사해요!', 2, 4, 'GOOD', SYSTIMESTAMP);
