INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '홍대 메인거리에 이렇게 넓고 쾌적한 매장이 있다니 앞으로 여기 자주 올거 같아요 좌석도 다 넓어 편하고 복잡하지 않아 좋아요 그리고 무엇보다도 커피가 정말 맛있어요 마침 핸드드립 메뉴 있어서 먹었는데 추천해주신 원두로 먹으니 정말 맛있다는 말이 계속 나오네요. 더워서 아이스로 마셔서 깊은 맛 음미할 수 없을 줄 알았는데 아이스로 마셔도 특유의 맛이 다 느껴지더라구여', 83, 16, 'GOOD', SYSTIMESTAMP);
