INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '카페345~! 드립커피!! ☕️🥃 핫이아니고 아이스면 맛과향이 들 할 줄알았는데 너무 풍미깊은 아이스드립커피였습니다~! 🧊 그리고, 티라미슈는 증말~ 맛쪘어요~!!! 🥧 티라미스의 정석+@ 맛입니다~!!!😍', 49, 6, 'GOOD', SYSTIMESTAMP);
