INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '커피랑 디저트 먹다가 멋있어서 샌드위치랑 쿠키도 더 시켜먹었어요. 직접 로스팅 하는 카페니 핸드드립 커피를 추천드려요. 파나마의 베르가못 복숭아 향 나는 커피가 특히 맛있었어요. 케이크도 꾸덕하고 진하고 맛있습니다!', 94, 19, 'GOOD', SYSTIMESTAMP);
