INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '핸드드립이 깊은맛이 나고 밀크티도 너무 맛있었습니다 다른 카페와는 다르게, 고소한 맛이 나서 좋았습니다!! 다들 추천드립니다~ 넓고 시원해서 좋아요 ㅎㅎ', 14, 10, 'GOOD', SYSTIMESTAMP);
