INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '커피맛집, 원두맛집! 원래 산미있는 커피 안좋아하는데 게이샤 워시드 커피 진짜 너무 맛있다!!! 바스크치즈케이크도 꾸덕꾸덕 꿀맛♡ 커피먹으러 또 가고 싶댜', 91, 24, 'GOOD', SYSTIMESTAMP);
