INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '직원이 불친절해요. 들어가자마자 음료 안시키면 득달같이 달려와 음료시키라고 푸시하고, 일행이랑 같이 테이블을 사용하지 않는다고, 다음부터 안와도 된다는 말만 앵무새처럼 반복합니다. 일요일이었고 매장은 텅텅 비어있었습니다. 오지말라는 얘기냐고 되묻고 따지니 그런 말은 한적 없다며 경찰을 부르겠다는 협박도 받았습니다. 자리 먼저 찾고 가방 내려놓고 있으면 당장 달려와서 음료 시키라고 난리입니다. 지인에게 물건 갖다 주려고 잠깐 방문한 것도 (착석하지도 않음) 음료 안시킨 것으로 기억하고 따지고 드니 방문에 참고하세요.', 43, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '리뷰쓰기도 전에 날이 더워서 드링킹해버릴만큼 매장도 깨끗하고 시원하고 앉아 대화하고 가기 좋아요~ 커피는 물론 맛있구여 카페가 넓어서 답답하지 않고 추천합니다!!', 44, 3, 'GOOD', SYSTIMESTAMP);
