INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '외국인 친구랑 왔는데, 카페가 넓직 넓직하고 얘기하기 편해 너무 맘에 들었어요^^ 로스팅도 직접하고 위치도 좋아 홍대오면 자주 찾을것 같습니다. 잘 마시고 가요~', 31, 10, 'GOOD', SYSTIMESTAMP);
