INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '급하게 화상회의 할 곳이 필요해서 들렀는데 이 날씨(5월초)에 에어컨이 너무 쎄서 좀 추웠어요.. 잠깐 동생 커피사주고 컴퓨터 하는데 음료 시켜야 매장이용 가능하다 그래서 좀 급하게 당황타며 주문한 감이 있었네요. 그래도 콘센트 종종 있고 공부하고 매장이 아주아주 커서 대화하기도 공부하기도 가볍게 들르기 좋은곳 같아요!', 77, 18, NULL, SYSTIMESTAMP);
