INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '홍대에 새로 생긴듯한 카페 카페가 크고 좌석이 많아요 스터디나 그룹모임 하러 오기도 좋을거 같아요 사람은 많은편이 아니라 조용한점도좋습니다 음료도 맛있어요 카페크림은 아인슈패너 매뉴인데 크림이 굉장히 쫀득하고 맛있습니다 얼그레이 케익은 조금 달달한 편이에요', 122, 20, 'GOOD', SYSTIMESTAMP);
