INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '요 골목에 있는 카페들 중에 크기가 큰 편이에요! 지난번에 왔을 땐 아메리카노를 마셨는데 4천원이었고 비싼 편 아니고 맛있었다고 느껴서 재방문 합니다! 노래가 아주 시끄러운 편이 아니고 테이블 간격도 따닥따닥 붙어있는 편이 아니라 대화하기 좋아요 :)', 33, 6, 'GOOD', SYSTIMESTAMP);
