INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '뱅쇼는 생각보다 시큼해서 단맛을 좋아하면 다른 음료를 추천합니다 얼그레이롤은 진하지는 않고 은은해서 무난했고 커피는 산미가 적고 고소해서 저녁에 마시기 좋았어요 공간은 넓고 좋네요 푹신한 의자는 없지만 인테리어가 도시적이라 재밌어요', 15, 2, 'GOOD', SYSTIMESTAMP);
