INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '홍대에서 보기 힘든 넓고 트랜디한 카페예요!! 아직 사람들이 잘 모르는지 나만 알고 싶은 가게 같은 카페 ☺️ 넓고 조용해서 작업하기에도 좋고 복작대지 않아서 너무 좋아요 👍🏻', 54, 12, 'GOOD', SYSTIMESTAMP);
