INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '디피가 예뻐서 시켜봤어요. 스푼도 나와서 초콜렛 떠먹거나 섞어줘도 좋답니다. 진한 초코맛이고요, 적당히 달아서 좋았어요. 크림이 부드럽기도 했고요. 아쉬운 점은 양이 좀 적다는 거? 더울 때 땀식히고 당 채우기 좋다고 생각해요', 1, 9, 'GOOD', SYSTIMESTAMP);
