INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '요즘 핫플로 유명하고 데이트 코스로도 좋고 친구들끼리 와서 수다떨기 좋고 공부하기도 좋습니다. 그리고 여기 롤케익이 유명하니 드셔 보세요. 롤케익 음료 세트도 있으니 세트로 저렴하게 드세요! 추천합니다.', 73, 18, 'GOOD', SYSTIMESTAMP);
