INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '카페 안도 넓고 밑에 전시공간도 있어서 너무 좋아요!! 노래도 크지 않고 쾌적해서 대화하기 넘 좋네용 위치도 홍대 번화가 가까이에있어서 좋아요 ㅎㅎ', 86, 14, 'GOOD', SYSTIMESTAMP);
