INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '@쇼콜라라떼 직접 갈아만든 초콜릿. 진한 초콜릿 맛이 느껴지며 달달한 크림과의 조화가 좋아요~ @귀리라떼 우유와 다른 고소함이 더욱 느껴지는 귀리라떼. 적절한 시럽도 추가한다면 달달 고소 카페인을 원한다면 강추☆입니다~', 35, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '일단 매장이 엄청 넓고 쾌적해서 단체로 오기 좋은 곳인 것 같아요👍 사진찍기도 좋고 밀크티도 너무 달지 않아서 좋은 것 같아욥😆', 48, 4, 'GOOD', SYSTIMESTAMP);
