INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '커피숍에 들어갔을 때 은은허게 퍼지는 커피 향이 정말 좋아요. 개인적으로 아주 진한 커피를 좋아하긴 하지만 은은한 드립 커피도 좋네요. 꾸덕꾸덕한 치즈 케이크도 너무맛나요. 추천해요!!!', 16, 4, 'GOOD', SYSTIMESTAMP);
