INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '모카라떼와 비타오렌지주스를 마셨습니다. 일단 점원들께서 친절하게 모카라떼는 좀 더 저어서 먹으면 좋다고 알려주셨어요. 비타오렌지주스는 우선 오렌지 알갱이가 씹혀서 좋았습니다. 비타민 맛도 나요!! 영수증 이벤트하면 디카페인 원두가루를 증정으로 받을 수 있어요. 집에서 커피모카로 마셨는데, 커피가 고소하더라고요. 다른 분들도 한 번 참여해보세요~', 18, 0, 'GOOD', SYSTIMESTAMP);
