INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '일회용컵에  나오는 라떼만 마시다가 샛노란색잔에 나오는 라떼 넘 감동이네요 매장도 넓고 쾌적하고 음향이 너무 좋아요 힐링  힐링~~~', 25, 9, 'GOOD', SYSTIMESTAMP);
