INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '이번에는 따뜻한 걸로 마셨어요. 차가운 것도 괜찮지만 역시 초코음료는 따뜻한 게 정석으로 생각해요. 목넘김이 부드러운 건 마찬가지고요.', 20, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '노란색 포인트 인테리어가 시선을 사로잡고 Tea 종류와 커피 종류가 다양해서 골라먹기 좋았어요. 디저트와 페어링되어있는 메뉴도 있어서 음료와 어울리는 디저트 찾을때 고민없이 선택할 수 있어서 좋아보여요.', 18, 1, 'GOOD', SYSTIMESTAMP);
