INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '지나가다 들렀는데 매장이 너무 쾌적하고 원목 책상도 있어서 과제하기도 너무 좋을 것 같아요 커피 휘낭시에 맛있는건 당연하구요 추천추천입니다 ㅎㅎㅎ', 47, 3, 'GOOD', SYSTIMESTAMP);
