INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페345'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '커피산미없고 다크 찐하니 좋고 과일주스는 진짜 과일로만했는가 착즙한거같은 맛이에용 맛있어용 ㅎㅎ 매장 깔끔하니 스피커도 우퍼가 빵빵한지 웅웅 울려여', 57, 12, 'GOOD', SYSTIMESTAMP);
