INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '남자친구랑 둘이 왔어요 어둠 속에서 같이 게임하고 대화 나누니까 90분이 금방 갔어요! 서로 잘 알지 못할 때 와도 너무 재밌을 것 같아요 어둠속에서 서로가 안보여도 서로를 알 수 있는 느낌이 좋았습니다:) 재밌는 체험하고 갑니다!!', 96, 21, 'GOOD', SYSTIMESTAMP);
