INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '암흑 게임 하러 왔어요ㅋㅋㅋㅋㅋㅋ 게임은 스포할 수 없지만 재밌습니당 어두운 곳에서 게임을 어떻게 하지 싶었는데 다 방법이 있습니다ㅋㅋㅋㅋㅋㅋ재밌어요 친구들이랑 와도 재밌을거같고 애인이랑 데이트 장소로도 추천합니다!', 15, 1, 'GOOD', SYSTIMESTAMP);
