INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '120분 체험을 해봤는데, 정말 짧다고 느낄만큼 금방 지나갔어요! 정말 재밌었고 어두운 곳에서 시각을 제외한 모든 감각을 활용해서 다양한 게임도 하고 대화도 하며 즐거운 시간을 보냈어요! 다음에 다른 친구와도 함께 오고싶어요!!', 9, 2, 'GOOD', SYSTIMESTAMP);
