INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '연인이랑 데이트하기 좋습니다ㅎㅎ 혹시 썸타시는 분 있으시면 꼭 같이오세요ㅎㅎ 리뷰 쓰면 인형뽑기도 할 수 있고 선물도 받을 수 있어요! 위치도 역이랑 가깝고 좋아요! 매장이 청결하고 직원분들도 너무 친절하세요☺️❤️', 38, 7, 'GOOD', SYSTIMESTAMP);
