INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '여자친구랑 방문했는데 안 보여서 뭘 할 수 있을까 걱정하면서 갔는데 생각한것보다 구성도 알차고 재미있게 짜놓으셔서 데이트 잘 하고 갑니다!! 직원분들도 친절하게 안내 잘 해주셔서 이색데이트 찾으시는 분들 강추드려요!!', 24, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '남칭구랑 데이트 할 거리 찾다가 와봤는데 어둠 싫어하는데도 좋은 사람이랑, 사랑하는 사람이랑 같이 오니까 너무 재밌고 행복하고 추억 가득한 시간이었어요 :)ㅎㅎ 진짜 프로그램도 알차고ㅎㅎ ㅋㅎㅋㅎㅋㅎㅋㅎㅋㅎㅋㅎㅋㅎㅋㅎㅋㅎㅋ지점토 만드는거 진짜 재밌어요ㅋㅎㅋㅎㅋㅎㅋㅎㅋㅎㅋ 그림그리는것두 재밌구용! 다음번엔 다른 주제로도 해보고 싶네요!!', 14, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '남자친구랑 이색데이트하고싶어서 암실카페왔어요! 처음들어갔을때는 처음느껴보는 어둠이라 조금 무서웠지만 금방 적응하고 즐겁게 게임했습니다 2시간이 이렇게 짧은지몰랐어요!! 너무즐거운 시간이였습니다!', 73, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '홍대 씨더라이트는 정말 색다른 경험을 할 수 있는 곳이었어용. 고등학교 친구들이랑 1년 만에 모여서 갔는데, 빛 하나 없는 완전한 어둠 속에서 게임도 하고 그림도 그리다 보니 엉뚱한 결과물에 다 같이 웃음이 끊이질 않고 놀 수 있었습니다!! 처음엔 낯설었지만 금세 적응돼서 오히려 평소보다 더 집중해서 서로 얘기하고 즐길 수 있었고, 2시간이 어떻게 지나갔는지도 모를 만큼 시간이 순식간에 흘렀어용 ㅜ직원분들도 친절하시고 준비가 잘 되어 있어서 처음 온 저희도 불편함 없이 즐겼답니다. 오랜만에 친구들과 특별한 추억을 만들기에 정말 좋았습니다!', 81, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '저희는 에약 없이 왔는데 취소 자리가 나서 바로 들어갈 수 있었어요!! 예약하시는 걸 추천드립니다!! ✨ 120분 동안 재밌는 게임과 대화를 많이 할 수 있어서 좋았어요 아예 안 보이는 공간에서 이런저런 체험을 하니 정말 신기하고 뜻깊은 경험이였습니다 💓 마지막 멘트는 정말 감동적이고 생각이 많아지는 시간이였습니다 🥲🥲 재밌었어요 !!! 🫶🏻', 18, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '3주년으로 이색데이트 찾아다 오게되었는데 진짜 하~~나도 안보여서 오히려 서로 진지한얘기도하고 장난도 칠 수 있어서 좋은 추억 만들었습니다 직원분들도 엄청 친절하시고 다른 커플분들한테도 짱 추천합니다 평범한것들이 평범하지않은 시간이없습니당 👍', 29, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '남자친구랑 같이 방문한 홍대 이색데이트 씨더라이트!! 이런 특색카페가 있는지 몰랐는데 완전 어두운 암실에서 둘이 게임하니까 너무 색다르고 재밌었어요 ㅋㅋㅋㅋ 지점토만드는거 생각보다 잘 만들어서 놀랐고.. 그림그리는건 정말 어렵더라구요 ㅠ 생각보다 다양한 게임이 있어서 120분이 금방 지나갔어요 주변 지인들에게 많이 추천해주고싶어요! 약간 썸타는 사람들끼리 가면 너무 좋을것 같은 느낌 ㅋㅋㅋ 부모님이랑 와도 재밌을거같아요~.~ 이색데이트 강추 👍', 35, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '눈 감고 게임하니까 쉬운 게임도 엄청 어렵게 느껴지고 더듬더듬하느라 웃겼어요 점토로 서로 얼굴 만들어주는 건 안보이니까 뭘 만드는지 감도 안잡혔는데 밝은 곳 나와서 보니까 나름 특징 살려서 만든게 많이 신기했슴다 ㅋㅋ', 42, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '데이트로 방문했는데 암실 체험은 처음이었는데 색다르고 좋았습니다! 씨 더 라이트란 의미대로 생각해보지 못했던 걸 다시금 새롭게 생각해보게 되는 시간이었네요.. 직원분들도 친절하셔서 좋았습니다!', 87, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '홍대에서 너무더워서 실내데이트 찾다가 방문하게되었습니다! 진짜 하나도 안보이는 암흑이었고 ㅋㅋ 더듬더듬하면서 찾으면서 하니까 너무 어이없고 재밌더라구요 ㅋㅋㅋ 색다른데이트 너무 즐거웠습니다!', 26, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '대구에서 이거 하려고 왔어요!! 세상에서 하나뿐인 컨셉이라고하니까 꼭 오세용. 체험도 10가지 정도 있었고 그림이나 점토로 만든건 들고갈 수 있어용! 무서우면 불켜고 안대끼고 해도 돼용.', 35, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '굉장히 색다른 경험으로 연인과 데이트할 수 있는 장소였어요! 어두운 암실에서 뜻밖의 재미난 활동을 하면서 시간 가는줄도 몰랐네요 ㅎㅎ 연인뿐만아니라 가족이나 친구들끼리 방문해도 재밌을 것 같아요! 강추합니다❗️❗️', 59, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '어둠 속에서 하는 이색데이트라고 해서 와봤는데 생각보다 너무 재미있었고 즐겁게 체험했습니다 잘 안보이는 상황에서 서로에게 더 집중해볼 수 있는 시간이였고 대화도 더 많이 나누게 되었어요!!', 13, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), 'see the light 신랑과 함께 방문했습니다. 무더운 여름에 실내 데이트 할곳를 찾다가 방문했는데 이색적이고 새로운 카페라서 좋은 추억 남기고 갑니다. :) 직원 분들도 친절하고 시간도 금방갈 정도로 재밌습니다. 친구들이나 썸남썸녀 또는 커플들이 오면 재미있게 즐기고 갈 수 있을수 같습니다.!', 91, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '홍대 이색데이트 추천드려요 처음하는 경험이였는데 너무너무 재미있었어요 오랫동안 기억에 남을 거 같고 내년에 다른 컨텐츠도 즐겨보고 싶네요 !!', 81, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), 'ㅋㅋㅋ재밌었어요 이렇게 암흑을 일부러 체험해볼 일이 없는데, 핸드폰 멀리하고 둘이서만 대화하고 게임하는게 한번쯤은 해보기 조은 거 같아용 ! ㅎㅎ', 63, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '여러가지 게임들 한다고 시간가는줄 모르고했어용!!! 막 너무 어렵지않고 되게 간단한게임들인데 어두운데서 하니까 더 재밌게 느껴졌어요!! 남자친구도 처음엔 이상해하더니 나중에는 적응해서 재밌게 잘놀더라구용ㅎㅎ더운날 하기 좋은 실내데이트였어요 재밌었습니다~:)', 97, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '색다른 실내 데이트를 원한다면 강추! 암실 속에서 대화는 물론 게임까지 다양하게 즐길 수 있어서 시간 가는 줄 모름,, 한번쯤 가볼만한 홍대 놀거리!', 31, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '암실카페는 처음 와봤는데 정말 아무것도 안보이네요 ㅋㅋㅋ 2시간 동안 안보이는 상태에서 다양한 게임을 했고 컨셉이 독특하고 재미있어서 추천 드립니다!', 48, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '120분 시간 정말 금방 갔네요 ! 친구들이랑 셋이왔는데̄̈ 게임도 많이하고 재밌었어요~ 찰흑으로 개구리(?)만들어서 시합도 했습니다 ㅎ', 25, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '포토존도 너무 이쁘게 꾸며져 있었고 컨셉이 독특해서 시간 가는 줄 몰랐어요 안내도 생각보다 잘 되어있었고 연인끼리 오기 좋을 것 같아요☺️🙏🙏🙏', 81, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '여자친구랑 이색데이트하고 싶어서 왔어요!! 진짜 아무것도 안보이고 둘이서 게임 진행하는데 인물맞추기랑 다양한 게임들이 너무 재밌었어요! 지점토로 서로 만들어주기도 있는데 저는 너무 못만들어서..부끄럽지만 주변도 조용하고 mp3로 특별한메시지도 주고 정말 재밌었어요 강추입니다 꼭 와서 보세요', 81, 17, 'GOOD', SYSTIMESTAMP);
