INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '120분 플레이 했습니다! 다양한 종류의 게임도 준비되어있고 밸런스게임ㅁ, 말하기 주제가 미리 준비되어있어서 더 좋았습니다👍🏻', 21, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '여자친구랑 데이트겸 공부하다가 들렸는데 너무나 좋은 추억 만들고 갑니다! 게임 너무 다양하고 암실에서 진행되다 보니 평소와는 다른 특별한 데이트가 된 것 같습니다😊', 72, 11, 'GOOD', SYSTIMESTAMP);
