INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '암실게임 120분을 체험하면서 처음에는 어둡고 무서웠지만 다양한 체험들을 하면서 소중한 사람과  소중한 시간을 보낼 수 있었던 좋은 체험이였습니다😎😎 홍대에 이색데이트로 강추😎😎', 30, 6, 'GOOD', SYSTIMESTAMP);
