INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '어둠속에서 게임하면서 대화하니 재밌었어요!! 평소에 못해본 데이트를 해서 그런가 시간도 빨리 가고 더 가까워진 느낌이 들어요 ㅎㅎㅎ 완전 추천합니다!', 28, 0, 'GOOD', SYSTIMESTAMP);
