INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '암실이라는 컨셉이 독특했어요! 여자친구와 재미있는 시간 보내고 갑니다. 게임들이 다양하고 아기자기해서 시간가는줄 몰랐어요!! 엄청 깜깜해서 진짜 아무것도 안보입니다… 굳', 51, 11, NULL, SYSTIMESTAMP);
