INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '남자친구 생일 기념으로 와봤어요~ 독특한 경험이였고 2시간 코스 이용했는데 시간 가는 줄 모르고 게임했네요 ㅎㅎ 특별한 날, 서로에 대해 알아보고 싶거나 독특한 데이트가 필요한 븐들께 추천합니다!', 24, 1, 'GOOD', SYSTIMESTAMP);
