INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '색다른 데이트를 원한다면 추천합니다. 처음에는 어둠에 잘 적응이 안되긴했지만 금방 적응되고 시간이 언제가는지 모를만큼 빨리 지나간 것 같습니다. 보이는것에 감사하는 시간이 되었습니다.', 36, 3, 'GOOD', SYSTIMESTAMP);
