INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '암흑이라는 독특한 컨셉 속에서 재미있는 게임 즐겁게 했습니다😆 새로운 경험을 해봐서 너무 좋았어요! 친구들과 즐거운 시간 보내구 갑니다!!', 4, 4, 'GOOD', SYSTIMESTAMP);
