INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '처음 와보는데 생각보다 구성도 알차고 너무 재밌었어요! 처음에는 어두웠지만 금방 적응이 되서 재밌게 놀고 왔습니다! 얘기 할 수 있는 주제들이 많아서 연인분들 오시면 좋을거 같아요', 51, 12, 'GOOD', SYSTIMESTAMP);
