INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '2시간 암실게임으로 예약했는데 처음엔 2시간이 부담스러웠지만 실제로 체험해보니 너무너무너무 짧았어요! 그만큼 정말 재밌었고 암흑속에서 색다르게  게임도,대화도 즐기며 시간 보냈습니다! 완전 추천드려요', 31, 2, 'GOOD', SYSTIMESTAMP);
