INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '시각을 제외한 상태에서 다른 감각으로만 여자친구와 소통해서 재미있었습니다. 이색 데이트로 추천합니다! 평소 해보지않았던 경험이라 의미있었습니다.', 436, 57, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '예약 후에 연인과 방문했어요! 입장하자마자 공간이 아늑해서 체험이 기대됐습니다☺️ 암실 체험은 실제로 들어가서 불이 꺼지면 상대방의 얼굴도 물건도 안 보여요! 다만 처음에 적응할 수 있는 환경이 주어져서 다행히 놀라지 않고 체험했습니다 ㅎㅎ 게임들도 정말 다양하게 준비되어있고, 공간의 특성을 잘 활용해서 구성된 게 느껴져요! (이미 유명한 서로 얼굴 그려주기 등등) 또 방 안의 MP3를 통해서 밸런스게임이나 서로에 대한 Q&A도 할 수 있는데, 평상시보다 더 깊은 대화를 할 수 있는 의미있는 장치였어요✨ 암실이다보니 약간의 긴장감(?)을 가지고 체험했는데, 그래서인지 90분의 시간도 정말 빨리 지나갔습니다☺️ 이 시설 자체의 기획의도도 정말 멋진 것 같아요🥺 소중한 사람과 다녀오기 좋은 곳이에요!', 30, 0, 'GOOD', SYSTIMESTAMP);
