INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '암실이 상상 이상으로 암실입니다. 압도적인 어둠 속 왁자지껄 깔깔 재미지게 놀았습니다. 직원 분들도 아주 친절해요. 가게도 참 이쁘고 포토 스팟도 있고 아무튼 좋습니다. 꼭 한번 놀러오세요.✌️😎', 1, 7, 'GOOD', SYSTIMESTAMP);
