INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '남자친구랑 여행 와서 뭐할까 하다가 급하게 예약했는데 정말 잘 놀다 갑니다 ㅎㅎ ! 사장님도 친절하시구 완전 재밌었어요~ 더운날 실내데이트하기 딱!!😊😆 추천해요', 29, 6, 'GOOD', SYSTIMESTAMP);
