INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '컨셉이 독특해서 재밌었어요 눈이 안 보이니까 다른 감각에 더 집중하게 되고 서로에 대해 잘 알게된 것 같아서 좋았습니다!! 다음엔 어둠대화도 해보고 싶어요:)', 9, 2, 'GOOD', SYSTIMESTAMP);
