INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '무더운 여름날 시원하게 실내에서 놀고싶으면 추천합니당 특별한 경험 쌓고 가요!! 정말 한치 앞도 안보이는 상태에서 게임을 진행하는데 재미있습니다♡', 3, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '다른곳에서는 할 수 없던 암흑게임을 즐길 수 있어 좋아요! 단순한 게임도 여기서 하니까 색다르고 너무 재밌더라고요. 썸타는 사이나 연인들이 하면 더 효과만점 일 것 같아요. 완전추천 !!', 54, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '리뉴얼 됐다고 해서 또 찾은 씨더라이트! 첫번째는 남자친구와 방문하고 이번에는 친구들과 방문했어요. 두번째 방문인데도 너무너무 재밌었고, 친구들한테 이런 경험을 시켜줬다는게 넘 뿌듯합니다. 꼭 들러보세요! 위치도 좋아서 씨더라이트 체험 앞뒤로 홍대맛집 카페 가기 넘 좋고 무엇보다 웃느라 빼 찢어집니다.', 11, 6, 'GOOD', SYSTIMESTAMP);
