INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '어두운 공간 속에서 서로를 지점토로 만들어주었는데 저는 사람이 아니네용 마지막 결과물을 칠흙속에서 벗어나 확인하니 상처가 이만저만이 아니지만 재밌었습니다.☺️☺️❤️❤️ 남자친구와 함께 오는거 추천드릴게요 굿굿입니당', 34, 3, 'GOOD', SYSTIMESTAMP);
