INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '색다른 데이트를 하고싶어서 방문했는데 서로 대화에 더 집중할 수 있어서 좋았던 시간이었습니당!! 분위기도 좋고 마지막에 사장님이 간식도 챙겨주셔서 좋았어요 커플분들 꼭 한번은 방문하세여', 83, 15, 'GOOD', SYSTIMESTAMP);
