INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '씨더라이트에 방문하면서 아무것도 보이지 않는 곳에서 여자친구와 이야기에 집중하고 다양한 게임들도 할 수 있어서 너무 좋았습니다!', 23, 1, 'GOOD', SYSTIMESTAMP);
