INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '암흑속에서 게임하기 진행했습니다 ㅋㅋㅋ 생각보다 더 어둡고 시간이 빨리 가요! 색다른 체험 해볼 수 있어서 좋아요 나중에 게임 바뀌면 또 해보고 싶어요', 43, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '너무 재밌는 경험이었어요~보이지 않는 공간에 둘만 있다고 생각하니 되게 의지되고 시간도 엄청 빨리지나가더라구요!! 담엔 다른테마로 또 방문하고싶어요~', 27, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '깜깜한 어둠속에서 즐기는 다양한 게임들이 정말 신선한 경험이였고, 게임도 다양해서 2시간이 흐른지도 못한 채 즐겼습니다. 현재 A코스가 준비되어있는데 출시예정이라는 B,C 코스도 나오면 꼭 경험해보러 와야겠어요!', 34, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '여자친구랑 이색데이트를 찾다가 이용해봤는데 즐거운 데이트도 할수있고 작은빛에 대한 소중함도 알게되는 시간이었습니다 연인,소개팅 코스로 좋아요~', 57, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '서울에 놀러온김에 해봤는데 신선하고 재밌어요 꼭 서울오면 해보시길 추천드립니다!! 저는 친구랑 했는데 둘다 재미잇어했고 되게 독특해서 전부터 하고싶었는데 이색적이고 좋았어요 서울에서 이색적인거 하고싶은 분들 추천드립니다!!', 31, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '씨더라이트 인스타에서 보고 궁금해 다녀와봣습니당! >_< 생각보다 알찬구성이어서 한번쯤 해보면 좋을거같아요! 포토존도 이쁘고 화장실이 깨끗해서 굉장히 굿 연인과 와도좋지만 친구들이랑 와도 재밋을거같아요!', 32, 5, 'GOOD', SYSTIMESTAMP);
