INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '이색데이트를 즐기고 싶어서 찾아보다가 오게되었는데 정말 120분 게임 구성이 알찼던 것 같아요 시간에 쫓기지도 부족하지 않고 여유롭게 대화나누며 시각 외 다른 감각에 의존하여 시간보내다보니 상대방의 감정에 더 집중하며 데이트 잘 즐겼습니당!🥰', 73, 11, 'GOOD', SYSTIMESTAMP);
