INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '직원분이 너무 친절하시고 안내따라 들어가면 엄청 깜깜한 아무것도 안 보여요 신서유기 좀비게임이 진짜인지 아닌지를 확인할 수 있었습니다', 11, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '일전에 할 수 없었던 경험들을 접할 수 있어서 신선하고 재밌었어요. 여러가지 많은 컨텐츠가 준비되어 있어 지루할 틈없이 시간이 지나갔어요! 추천!', 3, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '방법도 너무 친절하게 알려주시구 즐겁고 재밌는 경험 제대로 하고 갑니다 덕분에 이색체함 제대로 합니다 강추강추 연인끼리 꼭 오세요', 31, 7, 'GOOD', SYSTIMESTAMP);
