INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '암흑카페 이번에 갈 기회가 돼서 처음 와서 120분 체험 했어요! 2시간이라 길다 생각했는데 생각보다 너무 재밌어서 시간 가는줄 모르고 했네요 ㅎㅎ 색다른 경험을 해보고 싶다면 씨더라이트에서 즐기면 좋을거같아요!', 91, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '전부터 해보고 싶던 암실카페 다녀왔어요 ~~ 컨셉도 독특하고 직원분이 게임 설명부터 가이드까지 넘 친절하게 해주셨어요 ㅎㅎ 특히 그림 그리는 부분에서 서로 빵 터졌어요!! 다른 분들께 이색데이트로 강추합니다 ~~ 😄😆', 13, 4, 'GOOD', SYSTIMESTAMP);
