INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '새로운 컨셉이 정말 독특했고 생각보다 어둠속에서 할거리가 많아서 신기했고 재밌었어요~친구랑 와도 재밌지만 이성친구랑 썸남이랑 오면 더 재미있을것 같아요🙆‍♀️', 43, 0, 'GOOD', SYSTIMESTAMP);
