INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '너무 재밌었어요! 생각보다 120 분이 생각보다 짧았고 암흑속에서 진행 되니까 더 집중할 수 있고 마지막에 오디오를 들으면서 평소 당연하게 생각했던 시각에 대해 다시 생각해 볼 수 있었던 소중한 시간이었던 것 같아요! 연인이랑 가도 좋고 친구랑 가도 좋을 것 같아요_완전 추천합니다!', 52, 12, 'GOOD', SYSTIMESTAMP);
