INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '후기 보고 기대를 많이 하고 왔는데 20대 후반들끼리 하긴 좀..^^; 그랬네요.. 나중에 아이랑 와보기는 좋을 것 같아요~!..', 76, 12, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '120분 동안 아무것도 안보이는 곳에서 여러가지 준비된 게임들을 할 수 있었어요. 생각보다 안보였고 마지막까지 안보였어요 ㅋㅋㅋㅋ 조금 답답했지만 밸런스게임이랑 여러 게임들하다보니 답답하니까 새로워서 더 시간이 잘 갔던거같아요.', 37, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '특별한 경험을 해볼 수 있어서 좋았어요. 담에도 시간되면 다시 오겠습니다. 썸 탈때 오면 연인돼서 나갈 것 같아요 꼭 한 번 와보세용~~', 13, 10, 'GOOD', SYSTIMESTAMP);
