INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '색다른 경험을 원한다면 여기 추천드립니다! 2시간이 순식간에 지나갈만큼 너무 재밌어요! 나와서 결과물을 보면서 웃기도 하고 정말 즐거운 시간 보냈습니다', 84, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '어둠 속에서 대화를 해 보니까 너무 신선하고 좋았어요! 다양한 게임을 해보니까 눈이 보이는 상태에서 했던 것보다 다른 느낌이었어요 데이트나 친구랑 오는 거 강추합니다 ㅎㅎ', 19, 5, 'GOOD', SYSTIMESTAMP);
