INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '처음에는 약간 긴장 됐는데 게임하니 너무 재밌었어요!!! 다양한 게임들이 있는데 하나하나가 재밌고 특히 남친 여친이랑 하기 좋아서 강추👍👍 그리고 마무리 멘트가 넘나 좋았어요..', 42, 2, 'GOOD', SYSTIMESTAMP);
