INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '어둠속에서 하는 게임이라 색다르고 재밌어요! 얼굴이 안보이니 평소에 하지 못했던 진솔한 대화도 할 수 있어서 좋았어요! 강추입니당!!', 79, 16, 'GOOD', SYSTIMESTAMP);
