INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '오랜만에 여자친구랑 이색 데이트를 하고싶었는데, 그러던 중 눈에 들어온게 씨더라이트 홍대점이었어요! 어둠속에서 여자친구와의 관계도 더욱 돈독해지고 정말 소중한 경험이었습니다! 사장님도 너무 친절해요!', 48, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '평소에 잘 경험해 볼 수 없는 암흑 속의 공간을 체험 할 수 있어서 좋았고, 다양한 미션을 수행하는 과정에서 친밀도가 올라가서 좋았습니다.', 9, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '되게 독특하고 자유도 높은 2시간이었어요 ㅎㅎ 이미 잘 알던 사이에서 몰랐던 새로운 걸 알기도 좋고, 잘 모르는 사이라면 부담 없이 알아가기에 정말 좋은 장소인 듯요! 특히 지점토로 하는 활동이 재미있었어요 ㅎㅎ 강추드립니당', 48, 4, 'GOOD', SYSTIMESTAMP);
