INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '암실 특성 상 상대에게 더 집중 할 수 있었던거 같습니다 여자친구랑 방문했는데 두시간 시간 가는 줄 모르고 대화했습니다 😀 너무 좋은 시간이였어요 ㅎ', 76, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '친구 생일에 뭐할까 고민하다가 네명이서 신청해서 왔는데,너무 재밌고 특별한 시간이 되었어요!! 게임도 재밌고 대화도 재밌고!! 왠지 모르게 어둠속에서 사는 박쥐가 떠올라서 게임 소재로 이용했네요!!ㅎㅎ 이용하고 마지막에 나오는 멘트도 씨더라이트의 의미를 다시 한번 찾게 되는 뭉클한 시간도 되었답니다!! 다음번에 여자친구랑도 또 오고 싶어요!!', 96, 19, 'GOOD', SYSTIMESTAMP);
