INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '다른 곳에서 못 해보는 색다른 체험이라 신기하고 재밌었어요 120분동안 상대방한테 집중할 수 있는 시간이었습니다 제가 암흑에 약하다는걸 깨달았어요ㅠ 상대랑 좀 더 친해진 것 같아 추천합니다', 40, 10, 'GOOD', SYSTIMESTAMP);
