INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '너무 재밌구 이색데이트 하기 좋은 곳이에요! 직원분들도 친절하셨구 에어컨도 빵빵해서 좋았어요! 다음엔 다른 버전하러 오겠습니다! 감사해요 :)', 47, 3, 'GOOD', SYSTIMESTAMP);
