INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '완전 이색적인 홍대 데이트코스예요!!ㅋㅋㅋㅋ 암실게임 A 재밌게 즐기고 갑니다~~ 다음에 B랑 C 나오면 또 오고 싶어요❤️🥰🥰', 43, 4, NULL, SYSTIMESTAMP);
