INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '오랜만에 새로운 컨텐츠를 체험할 수 있어 흥미로웠습니다. 다만 전반적인 진행 방식은 조금 더 사용자 친화적으로 개선될 필요가 있다고 느꼈습니다. 암실에서 긴 설명서를 읽고 12분짜리 영상을 본 뒤 바로 게임을 이해해야 하는 방식은 다소 어려웠고, 필요한 시점에 간단히 안내가 추가되면 훨씬 편리할 것 같습니다. 또한 배경지식에 따라 난이도가 달라지는 점은 아쉬웠습니다. 체력적 부분에서도 개선이 필요했는데, 음료 제공이나 안내가 없었고, 장시간 앉기엔 의자가 불편했습니다. 이런 부분이 보완된다면 더 즐겁게 참여할 수 있을 것 같습니다.ㄱ', 60, 18, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '친구들이랑 함께 방문했는데, 암흑이 정말 암흑이었어요!! 보이지 않아서 친구들이랑 더 재밌게 놀 수 있었습니다. 색다른 경험이나 데이트 해보고 싶으신 분들께 추천드려요~!', 48, 0, 'GOOD', SYSTIMESTAMP);
