INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '남자친구한테 비밀로 하고 예약하고 왔는데 남자친구가 도착해서 호기심 있어 하는 모습이 재밌었어요 서로 룰 잘 이해 못해서 어리버리했는데 남자직원 분이랑 여자분이랑 친절해서 좋갔어요 특색있는 경험하고 가서 좋은 추억이 될 거 같아요 감사합니다:)', 37, 4, 'GOOD', SYSTIMESTAMP);
