INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '진짜 독특한 컨셉에 많은 교훈을 얻어가는 장소가 되는거 같아요!!! 다음에도 기회가 된다면 다시 방문하겠습니다~~! 너무 재밌었어요🤩🤩', 123, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '암실 체험은 처음 해봤는데 여다친구와 재밌는 경험을 할 수 있었습니다. 정말 재밌고 신기한 이색 데이트였고 다른 분들도 진짜 추천드려요!', 26, 4, 'GOOD', SYSTIMESTAMP);
