INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '암흑카페 신기해서 예약했는데 생각보다 재밌었어요!. 게임내용이 알차고 많았어요. 시간이 지너면 눈이 적응할 줄 알았는데 정말 아예 안보이니까 신기하고 게임이 새롭더라구요!!', 33, 0, 'GOOD', SYSTIMESTAMP);
