INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '90분이 길어보였는데 막상 주어진 게임하고 놀다보니 시간이 금방 흘렀어요! 완전한 암흑인 상태에서 글쓰고 그림그리기가 너무 힘들었는데, 마무리멘트 들으니 교훈도 있고 좋네요!ㅎㅎㅎ 다음에 게임 또 리뉴얼되면 체험하러 올게요!!', 16, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '기념일에 좋은 경험 제공 해주셔서 감사합니다!! 너무 시끄럽지 않고 조용한 분위기 속에서 체험에 집중할 수 있었어요!! 새롭고 이색체험 원하시면 돈 아깝지 않게 체험 하실 수 있을거 같아용!!', 91, 22, 'GOOD', SYSTIMESTAMP);
