INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '첫 데이트로 남자친구와 와본 씨더라이트! 어둠속에서 게임하면서 대화하다보니 더 가까워진 느낌이 들더라구요 ㅎㅎ 색다른 데이트로 강추합니다!', 63, 14, 'GOOD', SYSTIMESTAMP);
