INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '새롭고 재밌었습니다! 남자친구 손이 똥손이라. 다음부터 지점토 안 맡기려구요^^. 특별한 경험이었습니다~ 기념일이나 이색데이트 해보고 싶을 때 오면 좋을 것 같아요!~', 15, 3, 'GOOD', SYSTIMESTAMP);
