INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '암실 게임은 처음 이용해봤는데 어두운 공간에서 색다른 게임을 하는게 정말 독특해서 재밌었네요!! 이색 데이트뿐만 아니라 친구들끼리와도 괜찮을 것 같은 느낌이에요!', 48, 9, 'GOOD', SYSTIMESTAMP);
