INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '신선한 경험이었어요. 데이트로 추천합니다. 신기해하고, 게임설명 보고, 게임하면 대화까지 나누기에는 2시간이 부족하다고 느껴져요.', 72, 17, 'GOOD', SYSTIMESTAMP);
