INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '애인이랑 처음 와 봤는데 생각보다 재밌었고 게임도 다양한 데다 대화거리도 많아서 좋았어요 감각의 소중함을 새삼 느낄 수 있어서 좋았습니다 메시지가 좋아서 다음에 또 이용해보고 싶을 정도네요 :)', 16, 4, 'GOOD', SYSTIMESTAMP);
