INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '독특하고 재미있는 주제들의 게임들이 가득해서 시간가는줄 몰랐어요 ㅎㅎ 어두워서 어려울줄 알았는데 금방 적응해서 광장히 즐거웠습니다.', 22, 0, 'GOOD', SYSTIMESTAMP);
