INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '특별한 데이트 하고 싶어서 찾아보다가 오게 되었어요! 직원분들도 너무 친절하시고 재밌는 게임이 많아서 시간 가는 줄 모르고 놀았네요:) 다음에 또 오고 싶어요!', 43, 9, 'GOOD', SYSTIMESTAMP);
