INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '암흑카페라는 컨셉에 이끌려서 데이트하러 오게된 곳이에요! 처음에는 암흑에다가 어떻게 하는지 몰라서 허둥지둥 했지만 하다보니 적응해서 둘다 금방 게임하고 그랬어요! 120분은 게임만 하게 되는거라 다음에는 대화주제도 주시는 90분 짜리 해보고 싶어요!!💕', 38, 1, 'GOOD', SYSTIMESTAMP);
