INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '정말 이색적인 체험인 것 같아요!! 남자찡구랑 왓어요~~ 더운데 실내에서 두시간 동안 야무지게 잘 놀고갑니당👍🏿👍🏿 120분 햇어여 다른분들은 예약하고 오세용^_^', 176, 90, 'GOOD', SYSTIMESTAMP);
