INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '친구와 함께간 씨더라이트! 여름날씨를 피하기도 좋고 컨셉과 게임도 다양해서 너무 좋았어요!! 친구와 친목 다지기 최고! 꼭 가보세요~!👍', 91, 24, 'GOOD', SYSTIMESTAMP);
