INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '네이버 예약으로 암실카페인 씨더라이트를 방문해봤어요! 하나도 안보이는 공간에서 다양한 게임들을 하다 보니 시간 가는 줄 모르고 즐겼어요🙂 이색 데이트로 추천합니다👍👍', 3, 2, 'GOOD', SYSTIMESTAMP);
