INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '여자친구와 함께 이용했는데 너무 재미있었습니다. 2시간 동안 많은 다양한 놀이를 할 수 있었고 서로를 볼 수 없다는 독특한 컨셉이 너무나 흥미로웠습니다.', 20, 2, 'GOOD', SYSTIMESTAMP);
