INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '여자친구와 주말 맞아 이색 데이트 하러 갔어요~~~~ 헐 한시간 반 순간삭제됐어요 ㅎㅎ 엄청 재밌고 뜻깊습니다 ㅎㅎ 강력추천!!!', 18, 9, 'GOOD', SYSTIMESTAMP);
