INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '캄캄한 암실에서 대화하면서 게임도 즐기니 시간이 금방 갔습니다!! 게임 구성들도 알차고 마지막에는 교훈도 얻을 수 있어서 좋은 경험이었습니다. 연인과 함께 오면 재미있는 추억 쌓을 수 있습니다!!', 8, 5, 'GOOD', SYSTIMESTAMP);
