INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '처음엔 무서웠는데 갈수록 너무 신기하고 재밌었어요 ㅋㅋ 여자친구랑 하면서도 빵터지고 결과물 봐도 빵터지고 ㅋㅋ 재밌었습니다 :)', 49, 0, 'GOOD', SYSTIMESTAMP);
