INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '이색체험으로 암흑카페를 이용해봤는데 너무 신선하고 재밌었어요 완전 암흑이니깐 게임,대화에 더 집중하게 되어서 시간 가는줄 모르고 즐겼습니다', 19, 7, 'GOOD', SYSTIMESTAMP);
