INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '생각보다 엄청 깜깜해서 몰입도가 높았어요~ 다양한 게 많이 있어서 평소엔 하지 못했던 새로운 경험을 할 수 있어서 좋았어용 !!', 44, 4, 'GOOD', SYSTIMESTAMP);
