INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '게임으로 진행했습니다! 재밌는 요소들도 많고 대화할 거리들도 많아서 두 시간이 너무 금방 지나가버렸어요. 계속 붙어있어야하고 어색함도 풀 수 있어 추천합니다', 23, 9, 'GOOD', SYSTIMESTAMP);
