INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '처음에 안내문 보고도 불 꺼지면 이걸 다 어떻게 외우고 해야할지 조금 막막했는데 막상 하니까 너무 너무 재밌었어요!!! 90분이 10분처럼 느껴질 정도예요 ㅎㅎㅎ 대신 안내문을 꼼꼼히 읽고, 지시사항도 잘 지켜야 재밌게 즐길 수 있을 것 같아요 :) 연인이랑 온다면 더 즐겁게 하기 좋을 것 같고 친구랑 오면 승부욕이 불타오를 게임들이 많아서 좋네요 ㅎㅎ 특별한 추억을 또 하나 만들고 가게 되어서 너무 좋았습니다! 감사합니다, 번창하세요 🥰', 1, 4, 'GOOD', SYSTIMESTAMP);
