INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '120분짜리 체험으로 선탹해서 지루할줄 알았는데 미션이 엄청 다양했어요 정말 말 그대로로 암흑이라서 아무것도 안보였어요 색다른 체험이 될 수 있다! 나름의 의미도 있는 체험이었어요🌟', 25, 1, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '좋은 메세지도 많고 암흑 속에서 특별한 체험을 많이 해보았네요ㅎㅎ 여름철 시원하게 데이트하기에도 추천드리고 이색 데이트 원하시면 추천드립니다✨🙌🏻', 27, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '특이한 컨셉이어서 재밌었습니다! 120분이 좀 길지 않을까 걱정했는데 게임이 생각보다 종류가 많고 규칙 숙지하는데 시간이 좀 걸려서 순식간에 끝난 느낌이에요ㅋㅋㅋㅋㅋ 오늘은 남자친구랑 왔는데 나중에 친구들이랑 단체로 와도 재밌을거 같아요!', 80, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '친구랑 같이 방문하여 즐거운 추억 쌓았습니다! 게임이나 미션을 숙지하여 스스로 진행해야돼서 처음엔 조금 어려웠는데 친구랑 하다보니 자연스럽게 재밌게 놀 수 있었습니다! ㅎㅎ 색다른 경험이었습니다', 24, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '이색데이트로 추천합니다! 처음엔 무서웠는데 그만큼 서로에게 의지할 수 있어서 좋은 추억이 된 것 같아용! >_< 강추하니 꼭 와보십셩', 41, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '아무것도 모르고 얼마 전에 만난 새 친구들이랑 가서 처음엔 뭘해야될지도 모르고 조금 어려웠어요. 근데 하다보니 게임도 대화도 암실에서 하니까 어색함도 없고 좋았어요.', 77, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '처음에는 길다고 생각했는데 90분이라는 시간이 생각보다 훨씬 빠르게 지나갔고 다양한 게임으로 다 못하고 올 정도로 많았고 다음에도 꼭 이용하고싶어요!! 즐겁게 잘 놀다왔습니다 감사합니다~', 8, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '첨 방문했는데 재밌네요 ㅎㅎㅎ ☺️☺️ 직원분도 친절하시고 이색데이트하기 좋은거같아요 !! 다음에 기회된다면 또 와서 다른 코스로 체험해보겠습니다 !!', 126, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '처음에 들어가는데 어두워서 쫄보인 저희는 좀 쫄았지만 막상 들어가니까 편안한 분위기에서 대화하고 놀 수 있어서 좋았어요! 편하게 앉아서 여유롭게 있다가 간 것 같습니다 추천해요☺️🤍', 26, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '남친이랑 데이트하러 방문했습니다! 완전한 어둠 속에서 진행하는거라 독특한 경험이었습니다 이색적인 데이트 장소 찾으시면 체험해보시면 좋을 것 같습니다! 이것저것 할 게임들이 많이 준비되어있어서 두시간이 금방 사라졌어요ㅎㅎ;', 22, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '이렇게까지 안보일줄 몰라서 당황했는데 생각보다 재미있었어요! 할것도 많고 대화를 좀 거 많이하고 더듬더듬 찾아서 찾는 재미가 있네요ㅋㅋㅋㅋㅋ 이색데이트로 강추입니다!', 19, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '암실에서 여러가지 게임하고 체험할 수 있었어서 색다른 경험이였어요! 정말 암실이 생각한것보다 정말 하나도 안보여서 더 신기했던것같아요👍🏻', 24, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '처음 90분짜리 암흑 카페 해봤는데 저는 설명이 조금 빠르고 약간 부족하지 않앗나싶엄ㅅ아요. 근데 컨셉이 확실해서 안에 정말 아무것도 안보이고, 엠피쓰리로 밸런스게임 하는 것도 재밌어서 금방 시간이 다 갔네요 ! 뿅망치 등 게임들이 안에 잇는데 이건 시간이 부족해서 못했지만 재밌을거 같아요~~ 락커 다 있고 핸드폰 가지고 못갑니다. 여기 오신다면 락커가 작아서 사람 두명 짐 다 못넣고 큰 부피 안들어가니까 짐 작게 들고오세요~', 60, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '더운데 시원한 곳에서 편안하게 신기한 체험 하기 좋아요!! 게임을 7개 정도 제공해 주는데 재밌었고 시간 가는 줄 몰랐어요 그리고 마지막 멘트가 감동적입니다', 15, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '단순히 불 끄고 있는 공간이 아니라 빛이 없을 때 느껴지는 감각, 속도, 감정을 다르게 체험할 수 있는 곳이었어요. 눈을 감고 서로를 그려주거나, 뿅망치 게임, 돈 맞추기 같은 활동이 처음엔 웃기고 어색했는데, 하다 보니 오히려 눈이 없어서 더 집중하게 되는 느낌이 정말 신기했어요. 특히 빛이 없으면 오래 걸리는 행동이라는 말이 그냥 어두운 게 아니라 진짜 감각이 줄어든 상황이라는 걸 체감하게 해줬고, 그 안에서 평소보다 더 진심으로 상대를 마주하게 됐어요. 익숙한 게임도 암흑 속에선 전혀 다른 감정으로 다가와서 누구랑 가느냐에 따라 완전히 달라지는 장소라고 느꼈어요. 조용히 웃고, 진심으로 집중하고, 다시 돌아보게 되는 경험이었어요. 진짜 한 번쯤 꼭 가보면 좋을 곳이에요!', 32, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '암실이라 해도 빛이 조금은 있을 줄 알았는데 진짜 어두워서 신기했어요! 자연스럽게 대화주제가 생기는 게임코스 너무 알찼습니다🥹 암흑 속에서 예상치 못한 게임 을 진행하다보니 시간가는 줄 모르고 즐겼네요~😆 저는 친구랑 왔지만 썸을 타거나 연애 초반에 오면 좋을 것 같아요!', 12, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '한번쯤 경험하긴 좋아요. 120분 굳이 안하고 90분 해도 충분합니다 데이트 목적으로 오기에는 좀 지루한 편이고 친구들이랑 다같이 오면 즐겁게 즐길 수 있어요!', 30, 0, NULL, SYSTIMESTAMP);
