INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '특별한 이색데이트 하러 방문했습니다 정말 아무것도 안 보이는 곳에서 여러 게임을 하며 시간 가는 줄 몰랐어요 암실게임 b, c도 빨리 오픈했으면 좋겠어요!!', 20, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '색다른 경험! 다양한 게임들을 어둠 속에서 즐길 수 있어서 정말 즐거웠습니다!!! 볼 수 있다는 것이 소중한다는 걸 깨닫는 소중한 시간이 되었습니다. 이색 데이트를 원하신다면 방문하세요!!', 11, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '상상했던것보다 훨씬 참신하고 재밌는 놀이가 많아서 시간이 엄청 빨리 지나갔습니다! 할게 없는 커플이나 친해지고싶은 사람끼리 가면 진짜 빨리 친해질 수 있습니다!', 39, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '홍대에서 색다른 데이트 코스 찾다가 방문하게 되었습니다 처음에 어둠속에서 적응하는 시간이 좀 걸렸고 적응하고 나니 재밌게 놀았어요! 시간 순삭 감사합니다:)', 24, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '들어오자마자 직원분들께서도 친절하게 안내해주시고 컨텐츠 같은 것들도 다양해서 2시간동안 시간 가는 줄 모르고 즐겁게 체험하다 왔어여!! 암흑카페 경험이 없으시다면 한 번씩 방문 하시는 것도 좋을 거 같아요!', 33, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '어둠속에서 다른 감각만으로 게임하면서 꺄룩거리고 때로는 진지한 얘기도하면서 두시간이 너무 후딱 지나갔어요! 여름에 시원한데서 데이트하고싶은 커플들 재미있게 잘 놀것같아요☺️ 오래된 커플보다는 만난지 얼마 안된 커플들 추천', 43, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '처음에는 암실이 좁고 어두웠는데 같이 가는 친구랑 재밌게 놀다보니 2시간이 정말 순간 지나가버렸어요..ㅋㅋ 정말 강추입니다. 근데 방안이 살짝 덥긴해요', 7, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '2주년이 다되어가는 국제커플... 이색적인 데이트를 하고 싶어서 찾아오게 되었어요! 너무 어두워서 약간 어지러운 것 같기도 했지만 시간이 지나니까 점점 익숙해지더라구요 ㅋㅋㅋ 이야기도 많이 나누고 즐거운 시간 보내고 갑니다 :) 처음에 두시간이라 해서 꽤 길다 했는데 시간 가는줄 몰랐어요! 다음에 또 방문할게요~', 69, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '남자친구 생일 기념 놀러왔는데 기대 안 하고 왔는데 컨셉이 독특하고 즐거웠습니다! 깜깜한 곳에서 120분동안 게임을 하니 서로에 대해 더 잘 알게 될 수 있는 좋은 시간이였던 것 같습니다 친구랑 와도 재밌을 거 같아요 추천합니다🤗🤗', 13, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '진짜 어둡고 아무것도 보이지 않아서 처음에는 무서웠지만 점차 분위기에 적응되고 같이 온 사람에게 집중하며 대화할 수 있는거 같았습니다!', 21, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '컨셉 독특하고 신기한 경험이에요. 암흑 카페가 무슨 의미인지 궁금했는데 마지막에 어둠 속에서 빛나는 달처럼, 그 사람을 떠올른다는 등 의미있는 말들이 인상 깊었으며 시각장애인의 입장이 이해되는 시간이었습니다', 8, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '인스타 확인하고 왔는데 너무 재미있게 하다갑니당!! 가장 재밌었던 건 암흑에서 서로 얼굴 그려주깈ㅋㅋㅋㅋ 진짜 결과도 너무 재밌게 나왔어용 담에 또 120분하러 올게여', 49, 9, 'GOOD', SYSTIMESTAMP);
