INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '남자친구랑 잘 즐기고 왔어요! 여러가지 게임 암흑 속에서 재밌게 진행했습니다~ 다만 설명이 좀 부족해서 처음에 헤맨 게 아쉬웠네용 ㅜ', 55, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '처음 해보는 독특한 컨셉이라 색다르고 재미있어요 !! 암전이라 어려울 것 같지만 설명서 잘 읽고 시작하니 이해가 잘 됩니다 !! 매장도 청결하고 직원분도 친절해서 기분좋은 체험 이었습니다 :)', 26, 2, 'GOOD', SYSTIMESTAMP);
