INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '재밌는 게임하면서 서로에게 집중하고 대화하기 좋았습니다 지점토 만들기로 유재석을 주제로 했는데 제가 이긴것 같네요 ㅎ  이색적이고 재밌는 데이트였습니다', 49, 0, 'GOOD', SYSTIMESTAMP);
