INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '어디에서도 볼 수 없는 특별한 컨셉이라 재밌었어요 무서울까봐 걱정했는데 노래도 차분한거 나오고 재밌어서 대화에 집중이 잘됐어요 재밌었습니다', 15, 4, 'GOOD', SYSTIMESTAMP);
