INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '시간 가는줄 모르고 놀앗어요ㅎ 이야기도 많이 하고 웃다보니 목이 아플정도로 즐거웟습니다 오늘 다 못해본 게임들 다음에 또 하러 오려고요^^', 21, 2, 'GOOD', SYSTIMESTAMP);
