INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '리뷰를 보니 게임도 하고 미션도 다양하게 한다고 해서 남자친구랑 많이 기대하고 갔는데 .. 처음 직원 분의 설명이 진짜 매우 부족하고 들어가자마자 아무것도 못 한 채로 직원 분만 3번을 호출했네요 둘 다 그런 거 차분히 못 하는 성격도 아닌데 처음이었어요 .. 어떤 체험을 하고 돈이 아깝다는 생각이 든 것도 처음이었습니다 유독 저희 시간만 그런 건지 모르겠지만 개선이 필요할 것 같아요', 38, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '처음 해보는 경험에 재밌고 좋았습니다ㅏ 다음에 다른 버전이 나오면 또 와서 해보고 싶어요! 연인도 좋고 친구링도 좋을 거 같아요~', 12, 9, 'GOOD', SYSTIMESTAMP);
