INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '홍대 데이트코스로 유명한곳💗 어둠속에서 약 2시간 동안 친근한 사람과 즐거운 시간 보낼 수 있습니당. 혹시 썸타는 중이라면? 당장 오세요.. 바로 커플각 (오기 전 간단한 음료나 과자 갖고 오시면 당 안 떨어지게 놀 수 있을 것 같아요🥰 정말 정말 어둡기 때문에 생각보다 체력 소모가 있어요..!)', 120, 19, 'GOOD', SYSTIMESTAMP);
