INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '홍대에서 이색데이트로 시간 보내기 진짜 재밌고 좋아요!! 진짜 아무것도 안보여서 컨셉에 충실하다고 느껴졌어요! 다음에 또 올 거 같아요 ㅎㅎ 재밌었어요!', 7, 2, 'GOOD', SYSTIMESTAMP);
