INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '요로굘속 쇄석하고 최악의 몸상태로 탑승해썽요.. 친절하시고 사진도 잘찍어주세요! 나중에 몸상태 좋을때 한번 더 와보고 싶어요!! 멀미 약간 했지만 그래도 좋아용 만족합니다', 66, 14, 'GOOD', SYSTIMESTAMP);
