INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '완전히 어두운 암실에서 1시간 반정도 게임했는데여!!! 정말 신기하고 재미있는 경험이였어욤 특히 시각이 차단되어서 목소리, 촉감 같은 작은 감각에 오롯이 집중하게 되더라구여 ㅎㅎ 재밌습니다 추천! !', 5, 3, 'GOOD', SYSTIMESTAMP);
