INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '암실이다 보니 잘 안보이고 답답했는데 마지막에 멘트를 들어보니 그게 다 의도한 거고 그 속에서 같이 온 상대가 더 소중하다는 것을 알게되는 좋은 시간이었다.', 74, 17, 'GOOD', SYSTIMESTAMP);
