INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '첫 홍데데이트리 뭐할지 고민하다가 급찾게되어 와봤는데 너무 이색적이구 신선해서 시간후딱갔어요! 더운 여름 실내데이트 장소로 제격이네요~ 새로운 게임테마가 생기면 또 와보고싶어요!', 105, 19, 'GOOD', SYSTIMESTAMP);
