INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '완벽한 암실에 있는 걸 처음 겪어봤는데 눈이 불편하신 분들의 고충을 잠깐이나마 겪을 수 있었고 바구니에 재밌는 게잉들도 여럿 있었다. 독특한 컨셉으로 한 번쯤 가보는 것도 추천!', 50, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '암실에서 재미있는 게임 진행해서 매우 재미있었어요😶 커플끼리 아님 단체로 와도 무척 잘 놀다 갈 수 있을 것 같습니다 !! 직원분도 친절하시고 잘 도와주셔요 왕큰 추천 드립니다', 95, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '생각보다 너무 너무 재미있었습니다 다양한 게임들을 특이한 분위기에서 직접해볼 수 있는 특별한 경험! 하지만 개임당 시간 배분을 잘 해야할 것 같아요! 마무리 추억의 간식 너무 좋습니당~', 33, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '오래된 연인보다는 사귀기전, 후로 좋을 데이트 코스입니다. 10년 넘게 연애한 저희는 설렘보다는 음,,,~ 이게다야? 요론 느낌이에요 아쉽다면 아쉬운 데이트였습니다', 21, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '상상만큼 알차진 않고 그냥 궁금하면 한 번 와볼정도 인것 같아요 저는 이 돈주고 오는건 좀 아닌것 같애요 ㅠㅠㅠ 이색데이트로 나쁘지는 않다~', 27, 7, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '몇 년 전 아는 사람이 추천해 줘서 방문했었어요 당시 암실이라는 인공지능이 해주는 암흑소개팅이 너무 신선했던 기억이 나요 다양한 체험도 좋았고, 그 뒤로 주변 사람들에게 많이 추천했었는데 이번에 공지를 보고 알았어요 주변에서 다들 헷갈렸던 이유가 이런 거였군요 솔직히, 남이 애써 만든 걸 그대로 따라하려는 건 이해가 안 되네요 부디 잘 해결되길 바랍니다 암흑소개팅 주변 솔로 친구들이 너무 아쉬워하고 있어요 ㅠ 처음엔 친구가 무섭다고 못하겠다고 했었는데 주변에 다른 사람들이 같이 있어서 괜찮아졌다고 하더라구요 가격이 예전보다 올랐지만, 2시간 넘게 체험할 수 있고 구성도 훨씬 알차졌어요 선물까지 포함하면 충분히 납득할 만한 가격이라고 생각해요 솔직히, 이곳만큼 특별한 곳은 없었습니다. 또 방문할게요', 28, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '설명 영상 퀴즈가 꽤나 헷갈렸지만 다행히 다 맞혔습니다 ㅎㅎ 준비된 게임이 생각보다 쉽지 않은데 그래도 재미가 쏠쏠했어요. 협동도 하고 서로 경쟁도 하는 방식이라 재밌었어요! 협동이 있다보니까 정말 아무것도 안보이는 상태라 좀 답답하기도 했지만^^.. 그래도 즐거운 경험이었어요 ㅎㅎ 90분 다 채우고 나왔네요 의미도 감동있고 직원분들이 정~~~말 다들 친절하셔서 너무 좋은 경험이었습니다🥰', 3, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '겨울이여서 날씨가 춥기 때문에 실내에서 할 수 있는 이색데이트를 찾다가 알게되서 방문했어요! 2시간 동안 어떻게 하지 하고 생각했는데 막상 하니까 시간이 엄청 빨리 지나갔고 생각보다 엄청 재밌었어요 모든 것들을 직원분들이 잘 안내해주셔서 어려움 없이 쉽게 할 수 있었고 이색 데이트 코스로 추천추천 담에 다른 코스도 해보고싶네요 ♥️ 재방문의사 있음!', 13, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '암실 체험은 색다른 컨텐츠라 한 번 해보고 싶어서 신청했는데, 정말 재미있었어요! 보통 리뷰 이벤트 아니고서야 후기를 잘 쓰지 않는 편인데도, 정말정말 재미있어서 후기 작성합니다! 아무것도 보이지 않는 곳에서 연인이랑 이것저것 맞추고 게임하는 게 정말 색다른 재미를 주더라구요. 시간 정말 빨리 갔고 대화할 거리도 많이 생긴 것 같아요! 마지막에 미션 성공 한 개수만큼 간식도 주시는데, 푸짐하게 주셔서 정말 좋았습니다! 나중에 암실 게임도 해보려구요, 정말정말 추천드려요! 다들 꼭 해보세요!', 56, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '지인이 암실카페를 이용해봤는데 엄청 좋았다고 해서 꼭 가보고 싶어서 검색해봤는데 비슷한 곳이 근처에 하나 더 있더라구요? 처음엔 헷갈렸는데 여기가 더 오래 하신 거 같더라구요 😊 망설임 없이 이곳으로 예약했습니다. 역시나 가보니 직원분들도 다들 엄청 친절하시고 오랜 노하우로 막힘없이 진행해주셔서 프로그램에 온전히 집중할 수 있었답니다! 이용 프로그램도 알차고 영상으로 암실에서 진행할 프로그램을 먼저 숙지하고 퀴즈까지 맞추게 하니까 내용도 쏙쏙 들어와요! 이런 부분은 자칫 암실에서 아무것도 기억 안나서 프로그램을 제대로 이용 못할 것을 생각한 세심한 배려인 것 같아서 참 감사한 마음이었습니다. 암실이다 보니 처음엔 무서웠지만 여자친구와 함께 진솔한 대화를 나눌 수 있었답니다. 오래오래 방문하고 싶은 곳!', 126, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '친구들과 함께했는데 너무 재미있었어요! 어떻게 이런 게임을 구성하셨을까 하는 생각이 들었어요. 다음번에 또 갈 의향이 있습니다~', 70, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '지인이 신박한 거 해봤다고 AI 이름이 암시리(암실ㅋ)인데 어둠 속에서 암흑 소개팅도 해주고 게임도 한다고 해서 어바웃타임 실사판이라 너무 궁금했어요 검색하니 여기 말고 또 있어서 분점인가 했는데 지인한테 물어보니 여기 카피한 곳이 생겼다고 잘 보고 가라고; 첨엔 조금 시끄럽겠다 생각했는데 백색소음 같았고 오히려 다른 사람들이 있어서 무섭지 않았어요 이어폰에서 나오는 밸런스게임 내용 너무 웃겨요ㅋㅋ 이걸로 평소에 안 하던 대화도 많이 했고 클레이 보고 올해 중에 제일 많이 웃었습니다ㅋㅋ 2시간이 순삭이었네요 글자 찾기랑 연결되어 있는 메시지도 좋았고 의미 있는 선물도 있어서 조금 가격이 있지만 돈이 아깝지 않은 체험이었다고 생각해요!!💜 다음에 다른 메뉴도 또 하러 올게요~~', 49, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '암실에서 모든게 진행 되다 보니 입장 전 진행 방식에 대해 영상으로 소개해 주는데 이해하기 쉽게 잘 만들어져 있고, 들어가기 전 간단한 테스트 진행으로 이해도 체크까지 해주셔서 너무 좋았습니다 주변 사람들 소음까지 같이 들렸다 보니 좀 시끄러운 부분도 있었지만 ㅜ 다양한 게임과 대화를 통해 상대방을 좀 더 알고, 자연스럽게 스킨쉽도 할 수 있어 좋았던 것 같습니다 B,C 등 업그레이드 버전의 테마도 곧 출시 예정이라고 하는데 나오면 또 방문해 봐야 겠어요 ㅎㅎ 참, 입장 전 영상 시청 + 본게임 + 눈 릴렉싱 시간과 게임 결과 확인 + 패자 벌칙 등이 있어서 120분 예약 하실 분들은 30분-1시간은 더 여유 있게 방문하는걸 추천 드립니다', 36, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '크리스마스라 이쁘게 꾸며놓으셨어용ㅎㅎㅎㅎ 남자친구랑 갔는뎅 진짜 깜깜해서 암것두 안보임 ㅠ 그만큼 서로한테 더 집중하게되구 게임도 재밌슴당 ㅎ 한번쯤 해보면 나쁘지 않을듯 !', 34, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '처음해보는 코스로 진행했는데 처음에 안내영상을 보고 어려워보여 당황했었습니당 ㅋㅋ 근데 막상 들어가고 보니 할만하더리구요!!  간만에 재밌는 체험했습니당', 26, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '예약하고 예약시간보다 20분정도 일찍 도착했는데, 45분 정도 기다리고 들어갔습니다. 뒤에 다른 일정 잡았으면 어그러질뻔했네요. 전체적으로 사람 많고 소란스러운데 안내가 미흡하다는 생각이 들었습니다. 대기하고 있는데 예약시간 지나서도 언제까지 대기해야한다는 말이없고 제일 처음 입장했을 때 대기하고 있으면 안내주겠다고 했지만 기다리다가 말이 없어서 물어보니 그제서 안내해주는 걸 보고 기분이 상했네요.', 35, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '정말 색다른 경험 하고 왔습니다!! 일단 화장실이 너무 깔끔하고 포토존도 너무 잘되어있어요! 암실게임도 너무 재밌게 하고 왔습니다 특히나 직원분들이 너무 유쾌하고 재밌었어요!', 121, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '스포 방지 차원에서 어떤 게임들이 진행되는지 모르는 상태로 가게 되었는데, 생각보다 간단한 게임들이더라구요! 근데 게임 수가 적지 않아서 100분이 엄청 짧게 느껴졌답니다..?🤣 그냥 평상시에 했으면 재미가 덜했겠지만, 아무것도 보이지 않는 상태에서 진행하니 조금 더 신기하고 재밌었던 것 같아요~', 105, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '컨셉이 독특하고 좋음. 새로 사귀기 시작한 커플이나 썸타는 분들에게 좋을듯. 근데 알바분들이 좀 어려서 그런지 좀 자기들끼리 쑥덕거리고 그런 게 있음.', 47, 2, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '예전부터 가보고 싶었던 곳인데 드디어 가보네요🌕✨ 사장님, 직원분들이 너무 친절하시고 게임도 다양해서 2시간 꽉꽉 채우고 옵니다 ㅎㅎ 이런 곳 너무 좋아요 :) 또 놀러올게요~!', 25, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '몇 년 전에 여기서 암흑 소개팅해서 커플 된 사람입니다💑 대화 주제가 무한으로 나와서 어색하지 않게 4시간 토크 했고 내면이 아름다운 친구라는 걸 알게 되서 아직까지 잘 만나고 있어요 고마운 맘에 그동안 여러 친구들한테 꼭꼭 가라고 추천했었는데 친구가 별로라고 해서 깜짝 놀랐어요 알고 보니까 여기 흉내 낸 곳으로 잘못 갔더라구요😱 다른 분들도 헷갈리시는 거 같은데 뭔가 조치가 필요해 보여요🤔 오랜만에 신메뉴 하러 왔는데 암흑 카페보다 더 신박하네요 물,과자,향 맞추기,지점토,소리 변조 등 4감각을 계속 활용할 수 있게 구성한 게 전 좋았어요 아 그중에 제일은 밸런스게임입니다👍 두 시간이 정말 순삭이었고 행복한 데이트가 되었어요👏 신메뉴도 무조건 해보라고 꼭꼭 소문 많이 낼게요 번창하세요🙌', 2, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '원래 후기 잘 안넘겼는데 너무 좋았어서 남겨요^^ 연인이랑 그저 마음편하게 이색데이트하고 파서 갔는데 놀고나서 너무 갬동먹었어요ㅠ 감사합니다', 64, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '남자칭구랑 기념일에 이색데이트로 방문했어요💕 진짜 아무것도 안보이는데 생각보다 더 재밌었어요! 직원분들도 친절하시구 게임도 여러가지로 잘 구성돼있어요!', 77, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '진짜 개개개개속상해서씁니다 점토 만든 거 가져가려면 3만원 내라해서 눈물 머금고 두고갔는데 그냥 장난이셨나요? 지인한테 너무 재밌었다고 추천해서 바로 예약하게 만들 만큼 너무 만족했었는데 장난이었으면 장난이라고 말씀 해주시지 지인은 그 점토 그냥 가지고 나왔다네요 😭😭😭ㅅㅏ장님 이게 무슨 일인가요......... 진짜 절 울리지 마세요 눈치 없는 제 탓인가요? 내향인이라 장난이냐고 재차 확인 못한 제 잘못인가요.........', 49, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '어떤 부분은 스포가 될까봐 자세히 남기지는 못하지만 독특한 컨셉의 재밌는 대화와 게임 잘하고 왔습니다! 포토존도 옷만 더 이뿌게 입고 갔으면 각 잡고 찍었을거에요ㅠㅠ 이뿌고 친절하고 끝까지 해보면 뜻까지 좋은 그런 컨텐츠 덕분에 잘 즐겼습니다~~', 29, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '친구랑 2명이서 하러 갔습니다. ‘암실’ 이라는 독특한 환경 때문에 더욱 특별하고, 재미있던 곳이었습니다. 나중에 암실카페도 생기고, 암실게임 B, C 등도 생기면 다시 체험해보고 싶을 정도입니다. 잘 놀다 갑니다~', 55, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '친구랑 갔는데 너무 재밌었어요!!ㅎㅎ암실카페는 처음이었는데 진짜 아무것도 안 보이고 게임하다가 너무 웃겨서 죽을 뻔ㅋㅋㅋ좋은 추억이었습니다', 83, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '두가지 메뉴 다 해봤지만 암실게임은 진짜 더 신박하더군요. 밸런스게임에 나오는 주제가 너무 웃겼고 할리갈리하는데 승부욕 때문에 밑장빼기(?)하다 걸려서 반칙패했네요ㅠㅎㅎ 음성변조기계로 성대모사 대결했는데 웃다가 침 흘렸어요 ㅋㅋㅋ 더 쓰면 스포 되니까 여기까지만 쓸게요. 천천히 말하면서 하는편이라 시간이 부족했는데 저희 끝날때까지 보너스 시간도 엄청 많이 주셔서 감사했어요. 선물로 의미있는 상품도 주시고 교훈도 있어서 소중함을 다시 생각해보게 되었습니다. 어디에서도 이런 체험을 할 수 없다고 생각하구요. 썸이나 애인이 있다면 필수 코스라고 생각합니다. 새로운 메뉴도 얼른 만들어주세요!!', 72, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '친구 추천받았는데 처음에는 조금 가격이 있어서 고민했었는데ㅠ 보통 방탈출도 1시간에 5만원정도인데 여긴 2시간에 5만원이고 그만큼 체험이 다양하고 색다른 경험이였어서 돈이 아깝지 않았고 탁월한 선택이었다고 생각해요 괜히 입소문으로 유명해진게 아니더라구요 미션이랑 게임이 너무 많아서 처음에는 좀 헷갈리고 무서웠는데 직원분들이 친절하게 설명이랑 정리도 잘 해주셨고 장난도 쳐주셔서 긴장이 풀려서 정말 2시간이 순삭이였어요 등에 그림이랑 클레이한거 너무 웃겨서 집에 잘 모셔놨습니다^^ 저도 주변 사람들에게 강력 추천 할게요', 39, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '여기 따라하는 곳이랑 착각해서 다른 데 다녀왔는데 거긴 할 게 없어서 한 시간 체험이 지루했습니다. 그런데 여긴 체험이 너무 많아서 오히려 두 시간이 모자르더라고요. 먼저 직원분들이 쾌활하고 친절하셨고 처음에 영상 볼 때는 조금 황당했지만 황당한 만큼  오히려 이색적인 추억이 되었습니다. 저희는 클레이 만드는 게 너무 웃겼어서 제일 기억에 남고요. 체험과 관련된 교훈도 있어서 더 좋았습니다. 선물로 받은 무드등도 집에서 보니 너무 이쁘네요. 최고의 이색 데이트였습니다.', 50, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '이색데이트로 아주아주 추천합니다. 전하는 메세지도 뜻깊고 시력의 소중함도 함께하는 사람의 소중함도 느낄수있었어요 더 자세한 리뷰는 blog.naver.com/hyewols', 49, 0, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '생각보다 더더더 어두워서 입장할때 겁 먹었는데 직원분이 친절하게 괜찮냐고 물어보시고 잘 안내해주셔서 즐겁게 즐기고 왔습니당 🩵🩵🩵', 7, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '색다른 경험를 하고 왔어요! 정말 어둡고 진짜로 안보입니다 ㅎㅎ.. 연인과 가서 같이 게임도 하고 더 가까워지느 시간이였네요 ㅎㅎ 좋은 장소 제공해주셔서 감사합니다~', 35, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '한국에서 유일한 암흑카페 씨더라이트 기대만땅하고 다녀왔는데 생각보다 구성이 탄탄하지는 못했다 1인 30,000원이라는 결코 저렴하지 않은 금액대인데 실망감을 감출 수는 없었다 그럼에도 궁금하다면 다녀오시길! 커플이 간다면 만난지 얼마 안되었거나 맥시멈 20대 초반까지만 가는 것을 추천', 97, 21, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '남자친구랑 같이 다녀왔어요. 씨더라이트가 주는 메시지가 너무 좋습니다. 특별한 날의 이색 데이트로도 좋고, 평범한 하루에 특별한 경험으로도 좋습니다♥︎ 직원분들이 친절하고 유쾌하게 안내해주셔서 기분 좋게 이용하고 왔습니다. 할까말까 고민 중이시라면 해보세요! 추천합니다👍', 73, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '남자친구랑 다녀왔는데 되게 신기하고 재밌는 경험이었습니다!! 아무것도 안보이는데 게임은 열심히 해야겠고ㅋㅋ 마지막에 결과 확인하는것도 넘 재밌었어요 ㅠㅠ 직원분들도 친절하셔서 아주 좋았습니당:)', 51, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '너무 재미있었어요~ 암흑카페라 조금이라도 보일줄 알았는데 정말 아무것도 안 보여요 ㅎㅎ 빛의 소중함을 알게 되었어요~ 정말 직원분들이 친절하셨어요 ㅎㅎ 그리고 이색데이트에 딱 맞아요~ 특별한 날 한 번 가보시는 걸 추천드려요~', 3, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '화장실 깨끗해서 일단 좋았구요. 돈이 아깝지 않게 재미있게 하고 왔어요! 스태프분들도 정말 리뷰에서 본 것처럼 친절하고 농담도 해주셔서 재미있었구요! 정말 하나도 안보이더라고요!! 또 가볼 의향 100퍼입니다!!', 11, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '엄청 어두워서 처음엔 좀 두려웠지만 여러 게임들을 하다보니 재밌었습니다 씨더라이트의 뜻과 뽑기로 얻은 간식들 잘 받아갔습니다!', 85, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '처음 가봤는데 너무 신기하고 재미있었어요. 어둠 속에서 더듬더듬 찾아내는 재미와 상대방과의 관계는 지금까지 경험해보지 못한 특이한 체험이었습니다. 연인 또는 친구와 꼭 한 번 쯤은 가보시길 추천드려요.', 96, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '게임 세트 중 잘 못준비되어있는 게 있어서 흐름이 끊겨서 너무 아쉬웠어요ㅠ 시끄럽기도해서 좀 아쉬워요ㅠ 그래도.친절하시고 나름 재밌었어요!', 41, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '남자친구랑 데이트 전전날 뭐할까 ~  하다가 예전부터 가보고 싶었던 곳이 뜨길래 해보자 ! 하고 예약해서 갔는데 시설도 너무 좋고 직원분들이 리뷰에 나와있는거 처럼 다들 친절하시고 재밌으셨어요  정말 아무것도 안보여서  깜깜한거 무서워 하시고 폐소 공포증 있으신분들은 힘들거에요!  남자친구도 첨엔 살짝 무서워 하긴 했는데  저랑 게임하다 보니까 긴장이 많이 풀렸다고 하더라구요  아무것도 안보이는 곳에서 게임을 해서 그런지 이생각 저생각 많이 들었던  의미있던 시간을 보냈던거 같아요 남자친구랑 둘이서 게임도 깔깔 웃으면서  했네요!! 꼭 한번쯤 가보시는거 추천 !!', 92, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '동생이랑 색다르게 놀고 싶어서 방문하게 되었는데 후회 없는 선택이었어요! 게임 종류도 많고 시간도 넉넉해서 잘 놀았습니다😊 직원분들도 친절하셔서 기억에 더 많이 남는 것 같아요. 동생이 이겨서 예쁜 무드등 받고 나왔는데 엄청 좋아해요. 나중에 다른 암실게임도 생기면 친구들이랑 오고 싶어요😆', 9, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '예약을 하고 갔음에도 예약시간보다 20분 더 기다린 것 같아요. 직원분들은 친절하셨으나 대기시간 안내를 한번더 해주셨으면 좋았을 것 같아요. 캄캄해서 정말 아무것도 안보였고 암순응도 없어서 눈이 안보이니까 촉각, 청각이 점점 예민해지더라구요! 내부 게임들은 즐겁고 재밌었고 이색데이트하기 좋았어요~ 이용시간 2시간이 짧게 느껴졌어요. 다만 시간이 끝날수록 살짝 답답해서 조금 빨리 나왔습니다~ 직원분들이 요정이신지 내부 구조를 외우신건지~ 어두운 공간을 이리저리 다니셔서 신기했답니다😁 한번쯤은 해볼만한 특별한 경험이었어요~', 108, 23, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '암흑카페도 해봤는데 전 암흑게임이 더 재밌었어용 게임도 훨씬 다양해옄ㅋㅋ 음성변조ㅋㅋㅋㅋ 할리갈리ㅋㅋㅋㅋㅋ 2시간동안 너무 웃어서 지쳐서 배고팠음 스킨쉽도 자연스럽게 되고 분위기 너무 좋아짐♡ 여긴 같은 메뉴도 딴사람이랑 오면 또 다르게 느껴짐 그게 제일 장점인거가틈 그래두 게임B도 빨리 나왔으면 좋겠어요 평일이라구 시간도 많이주구 선물도 주심♡ 사람이 좀 많은건 단점이긴한데 사람이 많다는건 그만큼 인기가 많다는거겠쥬 아 글구 다른분들 검색할 때 여기 베껴서 따라하는곳 있으니까 헷갈리지마세요!! 저도 첨에 친구 아니였으면 낚일뻔했어요ㅜㅠ 아니 뭐 로고도 메뉴도 다 따라해쎀ㅋㅋㅋㅋㅋ 글구 크리스마스 꾸며놓은거 이쁨 굿뜨♡', 46, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '남자친구와 더 가까워 질 수 있었고, 평소에 잘 못해보는 경험이라 더욱 의미있었고 기대이상으로 재밌었습니다! 또한 시각장애인들을 조금은 이해 할 수 있게되어 기쁨니다!', 27, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '실제리뷰.들어간지 30분만에나왔습니다.  암실이 너무 시끄러워요. 대화소리도서로잘안들리는데.. 소리지르며대화하고.. 그 게임들 좀.. 같이간사람이 어이없어했어요', 21, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '너무 독특하고 재미있는 시간 보내고왔어요! 암실이라해도 정말 이렇게 아무것도 안보이게 깜깜할거라고는 생각 못했는데 신기할정도였어요! 직원분들도 다 너무 친절하셨어요 ㅎㅎ 암흑카페??대화??도 궁금해져서 다음번에는 그걸루 체험해보려구요!! 🤍', 40, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '친구들이랑 계속 게임하고 떠드느라 시간 가는 줄도 몰랐어요! 2시간동안 재밌게 즐기고 갑니다 완전 암흑이라 시간 지나도 암순응 그딴거 없이 진짜 아무것도 안 보여요ㅋㅋㅋㄱ 색다른 경험 해보시고 싶은 분들께 강추합니다', 24, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '진짜 너무 새로운 경험이었어요 무엇보다도 좋았던건 직원분들이 너무너무 착하시고 잘 대해주시고 친절해서 더 더 좋았습니다♡ 추천해욘', 30, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '음...솔직히 좀 넘  정신이 없었어요ㅜㅜ 아이가 가고싶어해서 갔는데 예약  후 갔음에도 불구하고 꽤 10분이상을 기다렸고 암흑 속에서 다른 사람들 목소리가 너무 섞이다보다 시끄럽고 정신이 없었어요.. 무엇보다 공기가 좋은편이 아니라 아이와 게임을 하면서 연실 기침을 했어요 결국 게임을 다 해보지 못했지만 직원분 호출 후 그냥 나왔어요ㅜㅜ 진짜 너무 아무것도 안보이니까 무섭기까지 하더라구요^^;;', 1, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '안내하시는분들은 엄청친절해요 하지만 진행자없이 둘이서 진행하고 노는거라 다소 어려움이 있었어요 생소한거라 기대를 많이했는데 T커플들에겐 다소 재미가....ㅎ F들은 좋아할것같아요', 44, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '재미있었어요. 암실이라는 컨셉이 독특했고, 다양한 미션을 깨면서 데이트하기 좋았어요.  비싼감이 없지않아 있긴했는데, 마지막에 사은품이랑 과자도 주셔서 잊지못할 추억이 될 것 같아요', 2, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '기대를 너무 하고 갔나봐요 생각보다 그렇게 좋진 않았어요 다 뚫린 공간에서 게임을 진행했던지라 주변이 너무 시끄러워서 대화가 제대로 되지 않았어요', 13, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '들어가기 전에는 입장 후에 게임방식을 설명하는 방법도 나름 체계적이라고 생각했고, 이 카페 자체가 너무 새로운 콘텐츠여서 기대가 많았는데 내부 상황이.. 기대에 비하면 조금 아쉬웠어요😂 음.. 각 방 안에서 진행됐으면 좋았을거같은데 커튼 정도만 쳐져있고 큰 하나의 방안에서 다른 팀들도 동시진행 되는거라 방음같은게 전혀 안돼서 우리 팀 게임하는 소리랑 다른 팀 게임하는 소리가 막 합쳐서 들리는데 다른팀이랑 우리팀이 하는 게임 내용이 다른게 아니라 같은 걸 하는거리 스포당하기도하고..ㅜㅜㅋㅋㅋㅋ 그런게 좀 아쉬웠네용 그래도 새롭고 재밌었습니다!', 11, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '남자친구랑 뭔가 색다른경험을 해볼려고 예약했습니다 :) 알바샹분들 너무 친절하셨고 남자친구랑 재밌는 시간 보낸것같아요! 다음에 또 올것같습니당~', 8, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '헷갈려서 다른 곳 갔다 왔는데 진작 여기로 올 걸 그랬어요 다양한 미션이랑 게임들을 했는데 조금 헷갈렸지만 친절하고 유쾌하게 설명을 잘 해주셔서 어려움 없이 시간 가는 줄도 모르고 재밌게 즐겼습니다. 특히 지점토 만들기는 어릴 때 추억이 생각이 나서 더 좋았어요 이런 생각을 어떻게 하셨는지 참 대단합니다 광고로 죄다 이색 데이트라고 하는 곳들이 많은데 여기보다 이색적인 곳은 없었습니다 인정 잘 안 하는데 솔직히 인정합니다 다음에 다른 메뉴도 하러 올게요', 27, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '강추에요!!! 컨셉자체가 일단 너무 신기하고 좋아요! 정말 앞이 안보일정도로 암흑이지만, 촉각으로만 게임하고 또 대화하는게 굉장히 좋았어요!! 이런저런 생각 느끼게 해주는 점도 많구요. 굉장히 좋았구, 특히 이 씨더라이트 카페의 의미를 알게되니까 더 감동이었습니다!! +) 그리고 직원분들이 정말 친절하시구 센스가 정말 미쳤어요...!!! 많이 챙겨주셔서 감사했습니다!! 특히  깜짝으로 챙겨주시는 거 너무 감동이었어요..!! 다시한번 감사드려요 :)', 49, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '여기는 뭐하는 곳인지 잘 모르겠어요 ㅋㅋㅋㅋ 시간 예약하고 갔는데도 10분은 넘게 앉아서 기다렸고, 입장했을 때는 암실 너무 깜깜해서 진짜 하나도 아예 아무것도 안 보입니다. 직원들은 어떻게 다니는지 너무 신기할 정도예요. 게임은 쏘쏘... 직원들 활기차고 좋아요.', 34, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '재미있었어요!! 정말 아무것도 안보여서 오로지 상대의 목소리에 집중할 수 있는게 좋았어요 게임도 재미있었고 많이 웃을 수 있었어요~~😆🤣 서로에 대해 더 자세히 알고 싶다면 추천합니다~👍', 41, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '진짜 특별한 데이트를 할수 있어요 모든 것은 비밀이지만 진짜 대만족 데이트를 했어요! 요거 시즌 재라는데 다음 시즌에 또올꺼예요 특별한 데이트를 원하시다면 강추!', 0, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '처음해보는 체험들이 많았어요. 체험을 통해 현재에 감사할 줄 알게되었습니다. 다만, 차분한 분위기 속에서 진행되는 체험인 줄 알았지만 많은 사람들을 수용하기 위해서 인지 빠르고 기계적으로 체험이 진행되었습니다. 그부분은 조금 아쉬웠습니다. 그리고 암흑속에서 진행되다보니 약간의 어지러움이 발생하였습니다. 안내사항 꼭 읽고 참여하면 더 행복한 체험이 되지 않을까 싶네요 !', 36, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '재미있었어요! 단순 체험이 아니라 배울 점도 있어서 커플이나 친구끼리 한 번 정도 가면 좋아요😘😘 어둠 속에서 시간 알려주는 타이머도 있어서 시간 계산하고 나갈 수 있어요! 기본 90분 이외엔 추가요금 발생해요! 직원분들 엄청 친절했어요🤪🤪💕', 29, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '스포할 수는 없지만 일단 직원 분이 엄청 텐션 높게 유머를 잘하셔서 분위기가 너무 좋았어요! 엄청나게 깜깜해서 놀랐지만 100분 동안 손 잡고서 이것저것 해보고 재밌었네요! 여자친구도 다음날에 여기 좋았다고 계속 얘기해줘요ㅋㅋㅎ 또 놀러올만한 경험입니다 진심으로!!', 13, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '추천 받아서 와봤는데 진짜 오길 잘했네요^^ 정말 이렇게 안보일지 몰랐는데 아무것도 보이지 않았고 영화 어바웃타임 카페 컨셉답게 그동안 했던 데이트와는 달리 정말 색다른 시간을 보낼 수 있었어요😊 암실카페 매뉴를 체험했는데 오래된 커플인 저희도 색다른 대화를 나눌 수 있었고 평일이라 주말보다 한적하고 조용하다고 하셨는데 다른 사람들이 보이지 않으니까 신경 안쓰고 대화하기 편해서 그간 못나누던 많은 얘기도 나누다보니 사이가 더 돈독해진 것 같아요💕 미션하면서 더 재미있고 웃다가 시간 다 갔는데 마지막에 감동포인트까지 ☺️ 더 말하면 스포될테니 여기까지만 적을게요.ㅋㅋ매장 곳곳이 다 사진 스팟이라 예쁜 사진도 많이 건졌고 친절히 응대해주신 직원분들 감사했습니다. 암실게임매뉴하러 곧 또 올게요^^ 강추👍', 51, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '사진을 제대로못찍은게 아쉬울 정도로 컨셉이 독특하다고 생각합니다ㅎㅎ 암실이라서 엄청 무서울줄알았는데 생각보다 너무 친절히 잘설명해주시고 직원분들의 밝은 분위기덕분에 즐겁게 게임도 했구요 ㅎㅎ 커플들이 오기 딱좋은 컨셉인것같아용', 63, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '이색 데이트 코스에요 눈이 안보이니깐 서로애게 더 집중할 수 있고 재밌는 대화 할 수있고 게임ㄷㅎ 재밌고 아쉬운건 방음이 안되어서 같이 있는 사람들 시끄러우면 좀 시끄러워요', 129, 26, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '완전 추천! 암실게임으로!! 개인적으로 돈 아깝진 않았어요 평일 추천. 게임 10가지인데 막상 들어가면 까먹어서 몇개는 못 함ㅋㅋㅋㅋ 개인적으로는 밸런스게임 질문들이 빼빼로 vs 콘칩 마냥 너무 귀염뽀짝해서 커플용 친구들용같은 커플질문이 좀 더 많았으면. 밥 카페 영화 데이트 류에서 정말 이런거 너무너무 좋습니다 직원분도 짱 친절하시고 진짜 어두우니까 무서워서 자연스럽게 손잡고있게 되는거같아요 주변 사람들에게 추천의사있습니다 꿀잼 암실게임 추천', 94, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '썸타는 사람이랑 갔는데 너무 좋았습니다!! 어색한 거 다 풀어지고 엄청 편해졌어요 ㅎㅎ 무서운 요소 하나도 없고 직원분도 너무너무 친절하세요!! 시간 가는 줄 모르고 돈 아깝지 않은 경험이었습니다 ㅎㅎ 친구, 연인, 썸타는 사이 모두 추천해요!', 31, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '아아아아 무것도 안보여어어어 안에 결과 확인하는게 늦어지고 핸드폰 맡긴거 찾는데 시간이 좀 걸려서 추가요금을 냈지만..? 그래도 한번쯤은 이색데이트 추천하는곳', 29, 1, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '특별한 경험이긴 했는데.. 주말에 방문해서 그런지는 모르겠는데 알바생분들도 부산스럽고 사람도 너무 많아서 집중이 잘안돼서 아쉬웠어요 딜레이도 많이 돼서 예약한 시간부터 2시간 넘게 소요됐어요!😭', 80, 13, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '썸 타던 남자랑 여기 왔는데 이제는 약 1년 반정도 만난 새로운 인연이 되었어요! 두번째로 올 때에는 연인인 상태로 왔는데, 또 다른 색다른 경험이욨어요. 첫번째로 올 때에는 노래 맞추기 게임을 시간이 없어서 못했는데 두번째에 이거 해보니까 엄청 재밌더라고요. 다들 이건 꼭 하고 가세여!!', 15, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '이색 데이트를 찾으신다면 강추!! 처음 경험해보는 암흑이라 당황하고 무섭기도 했지만 나름 재밌게 좋은 추억 쌓고 왔습니다! 직원분들도 다 친절하셔서 민망하실텐데 센스있는 장난도 쳐주시면서 분위기 띄어주시고 재밌었습니다ㅎㅎ', 30, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '잊고있던 소중함을 다시 알게되었고, 눈을떠도 정말 아무것도 안보이는게 신기한 경험이 되었습니다 독특한 컨셉이지만 체계적으로 잘 만들어진 곳입니다~ 직원분도 친절하십니다~! 추천이에요', 41, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '독특한 컨셉에 다양한 게임까지 너무 즐겁고 재미있었습니다. 덕분에 소중한 사람과 행복한 시간을 보낼 수 있었습니다. 고맙습니다😊', 61, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '전남친이랑 갔었는데 리뷰는 지금 쓰네요🤣♥️! 그만큼 컨텐츠는 넘 재밌었습니다ㅜㅠ 보통 다시 가기 싫어지는 경우가 많은데 새 인연과 또 오지 않을까 싶은 재미였어요👍👍 달달한 암흑속 데이트라기보다 서로 내기 걸고 하는 맛이 쏠쏠했어요', 25, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '남자친구랑 이색 데이트를 해보고 싶어서 갔는데 생각보다 너무 더 재밌었고 다른분들께 추천해주고 싶을정도로 시설이나 게임설명을 너무 세세하게 잘 해주셨고 게임도 재밌었어요 !', 71, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '색다른 놀거리라 너무 좋았어요! 진짜 진짜 아무것도 안보이더라구요 ㅋㅋㅋㅌ 안보여서 그런지 서로 솔직해지는 것도 있구 너무 좋았슺니당', 63, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '색다른 체험에 교훈을 주는 프로그램이 독특하고 애인이랑 가서 좋은 추억 만들기 최고에요👍🏻 진짜 하나~도 안보여서 공포감은 있지만 적응하고 여러가지 미션도 하고 재밌었어요', 10, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '예약 시간보다 5분 더 일찍 와달라는 안내문을 보고 10분 정도 일찍 도착했는데 예약 시간보다 30분 뒤에 입장했어요 늦는다는 별다른 안내 없이 저보다 늦게 오신 분들이 먼저 입장하시더라고요 너무 오래 기다려서 기분이 안 좋았어요 90분에 인당 21000원 너무 과한 것 같아요 그 정도의 금액의 프로그램인가 생각하게 되네요 준비과정내내 어수선하고 정돈되지 못한 느낌이었고 암실이라는 콘셉트 외에는 테이블 간의 간격이 좁아 (옆 테이블의 대화가 다 들리는 부분) 프라이빗 한 대화는 할 수 없을 것 같고요 예약이 계좌이체밖에 안된다는 점도 조금 불편하네요 재방문은 안할것같아요', 20, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '기대 별로 안 했는데 생각보다 재밌었어요!! 그림그리기 결과 너무 웃기고 색다른 체험이었어요 커플들 꼭 해보기 추천! 오래 사귄 커플은 이색 체험하면서 소중함도 깨닫고 더 돈독해질 것 같고 얼마 안 된 커플은 암실에 있으면서 설레고 더 친해질 수 있어요', 34, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '이색데이트 찾아보다가 발견했어요 정말 색다른 경험이였고 게임도 종류가 많아서 재밌었어요 몰랐는데 제가 어둠을 무서워하는것도 알게되었어요🥹 그렇게 심한건 아닌데 살짝 갑갑함이 있어서 폐쇄 공포증이나 저 처럼 어둠에 답답함을 느끼시는 분들은 생각해보시는 것이 좋을 것 같아요!', 30, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '암실카페라는 이색카페가 있다고 해서 들렸는데 너무 재밌어서 시간 가는 지도 모르고 놀았네요ㅎㅎㅎㅎ직원분들도 친절하시고 유머스러워서 더욱 재밌었던 것 같아요!', 2, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '너무 유익했던 시간이였고 직원분들도 너무 친근하게 응대 해주셔서 너무 재밌게 놀다 갔습니다 ㅎㅎ!다음에 새로운 거 나온다고 하셔서 한번 더 방문 해볼 것 같습니당 강추!!', 76, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '이색적이어서 좋았으나 룸식일줄 알았는데 오픈되어 있어서 좀 정신없고 시끄러워서 그점이 좀 아쉬웠어요 ㅠ 안그래도 안보여서 촉각 청각에 의존하게 되는데..', 32, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '남자친구 생일날 신선한 데이트 찾다가 마지막 코스로 선택했는데 생각보다 더 재밌고 특별한 경험이었어요 ! 스탭분들 모두 다 친절하시고 데이트 코스로 한번쯤 꼭 가볼만해요 ㅎㅎ 추천합니당', 41, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '처음 암실에 입장했을때 눈을 떠도 감아도 안보이니까 너무 답답했어요 제 남자친구도 너무 답답하니까 그냥 나가자고 할까 했다더라구요 하지만 1분만 그냥 있어보세요 무서우면 남자친구의 손을 잡고 안정을 취해보세요 그럼 서서히 적응이 될거에요 적응하고 나면 미션과 게임 하느라 눈을 뜨고 있는지 감고 있는지도 모를만큼 집중하게 됩니다', 30, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '이색 데이트 장소로 딱이에요 매번 똑같은 루트에  지루함을 느꼈다면 여길 가보는 것도 추천해요 정말 하나도 안 보여서 막막하면서도 그게 또 재미로 느껴졌어요 제한 시간이 너무 짧아서 못한 것도 있는데 다음에는 이번에 못했던 게임도 하고 싶어요 아 그리고 직원 분들이 굉장히 유쾌하셔서 저까지 웃음이 났답니다ㅎㅎ', 67, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '미리 예약해야하구요~ 이색카페 원하시면 강추요~ 어둠에 익숙하지않은데 깨달음을 얻고 많은걸 느끼고갔습니다. 일상의소중함을 다시한번 되새기는 좋은시간이었어요  재방문하려구요', 50, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '직원분들이 친절하고 평범한 일상 속 특별한 일, 혹은 신나는 일, 혹은 소중한 추억을 만들어가고 싶은 분들에게 추천합니다. 프로그램도 재미나고 깨달음을 얻을 수 있는 유익한 시간이었어요.', 56, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '너무너무너무 이색적인 경험입니다. 정말 지금까지 해 본 데이트 중 가장 이색적이네요. 아무것도 보이지 않는 곳에서 무엇을 한다는 게 색다릅니다. 무조건 추천!!', 35, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '직원분들이 친절하셔서 더 재밌게 할 수 있었던거 같아요 포토존도 예쁘고 맛있는 간식들이랑 예쁜 꽃도 받아서 좋은 시간이였어요!! 친구들에게 소문 많이 낼게요~~', 15, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '아무것도 안보이는 곳에서 여러가지 재미있는 게임들을 하고 대화도 나누면서 남자친구와 더욱더 뜻깊고 꽁냥꽁냥한 시간 보내고 왔어요😍', 97, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '색다른 경험 너무 좋았어요~ 그리고 그 경험에 의해서 깨달음도... 얻어갑니다.사장님도 직원분 모두 친절하시고 설명도 잘해주시고 또다른 테마 생기면 꼭 갈거에요😍', 66, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '어렸을 때 티비로만 봤던 그 암흑카페를 성인 돼어서 왔네용! 처음에는 진짜 아아아아아무것도 안 보여서 어떻게 하지…? 하고 막막 했는데 다양한 게임과 체험으로 너무너무 값진 경험을 하고 왔어요! 직원분들도 서로 돈독해 보이고 엄청 친절하셔서 행복한 추억 남기고 가요! 마지막에 뽑기 같은 것도 하는데 스크래퍼 받았어용ㅋㅋ! 또 다른 컨텐츠 준비중이시아고 하시던데 인스타 안 지울 테니까 소식 들리면 다시 달려가겠숩니당ㅠㅠ 많이 번창하시길🌷', 72, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '한번쯤은 가볼만한 곳이에요 가격이 저렴하지 않지만 여러가지 체험도 할수있고 너무 당연하게 생각했던 것들을 다시 한번 생각해볼수 있는 시간이에요', 19, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '설명 듣는게 많아서 그게 좀 별루에요... 특히 마지막엔 헤드셋 설명 듣는거 땜에 돈까지 추가되서 넘 상술 같았음.. 생각보다 금액이 많이 나올 수 있으니 유의하세요. 컨셉은 특이하고, 알바생 분들도 넘 귀엽고 친절해요. 20대 초반 분들이 가시면 좋을듯요!', 1, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '되게 이색적인 체험을 한 거 같아요 제 눈이 소중해지는 시간이랄까? 아쉬운점이 있다면 1시간만 하기엔 부족해서 이용시간 1시간이 넘게 되면 추가요금이 있는데 좀 가격대가 있는편이에요 나머지 외엔 한번쯤 해보시는걸 추천 합니다!', 20, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '암실이라고 해봤자 어둠에 적응되면 보이겠지 했는데 이건 무슨 아무것도 안보여요…ㅋㅋㅋ 직원분들이 암실로 들어가서 자리 안내 해주시는데 어떻게 찾아 가시는건지 진짜 너무 신기….. 그런 어둠을 본게 처음이라 색다른 경험이 되었어요 직원분들이 다들 친절하시고 진짜 저희 커플 유치한거 맞춰서 재미있게 해주셔서 너무 감사했어요ㅠㅜ 상품으로 받아온 짱구 스티커는 다이어리에 이쁘게 꼬옥 이쁘게 붙여둘겁니다ㅎ.ㅎ 만나면 매일 밥먹고 카페가고 영화보고 같은거만 반복하다가 새로운걸 해보고 싶어서 다녀왔는데 너무 좋았어요 색다른 경험!! 잊지못할 추억 하나가 늘게 되었어요:) 연인끼리 와도 좋고 친구끼리 가도 좋을것 같아요 새로운 테마가 생기면 다음에 또 방문할 예정입니다!!', 41, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '진짜 안보여요 검정색 그 자체🖤🖤🖤🖤 여러가지 미션 주시는데🔫🔫 보상도 푸짐하고 재밌는 시간이었어요🎁🎁🎁 진짜 아무것도 안보여서 이게 뭐고 저게 뭐고 탐색전이 좀 길었지만 정말 이색적이고 의미 있는 시간 보냈어요‼️', 28, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '지인 추천으로 가게 되었는데, 굉장히 독특한 컨셉입니다. 빛의 소중함과 함께 같이 간 상대와 더 친해질 수 있고, 진솔한 대화를 나눌 수 있는 좋은 기회였습니다.', 37, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '전 개인적으로 재미없었네요.. 다른 커플의 추천을 받아서 갔는데 취향이 다 다르니까요.. 그냥 눈감고 보드게임하는게 다에요. 그리고 동시다발적으로 진행해서 다른 커플들 대화소리 전부 다 들려요', 59, 15, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '남자친구랑 기념일 날 가기로했었는데 씨더라이트 들어가기 전에 싸웠거든요~ 그런데 어두운곳에서 오로지 소리와 촉감에 집중하고, 서로에게 잘 집중 할 수 있던 시간이었어서 웃으며 잘 풀고 나왔고, 오빠도 신기하고 좋은 경험이라고 했어요^.^', 15, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '이색 데이트 추천합니다. 들어가면 정말 아무것도 안보이고 신기해요 직원들은 어떻게 다니는건지ㅋㅋㅋㅋ 근데 한시간은 너무 촉박해서 주어진 미션이랑 다하려면 거의 무조건 시간 추가되서 결제해야 할듯요ㅠㅠ 그래도 시각장애인의 불편함과 눈의 소중함도 알려주려 하고 취지도 맘에들고 직원분들도 아주 분위기 좋게 이끌어 주셔서 재밌었어요~~', 57, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '직원분들 다들 너무 밝고 친절하셨어요! 에너지 받아갑니다~^^* 동생들이랑 색다른 체험해보고싶어서 가봤는데 넘 유익하고 넘 재밌었네요!', 58, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '얼굴보고 이야기하고싶으나 그게 익숙지 않는 경우! 그리고 썸타는 또는 아주친한남사친과함께가면 아주 좋습니다👍🏼 게임도 게임인데 대화하다보니까 시간 금방가더라구요!', 33, 3, 'GOOD', SYSTIMESTAMP);
