INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '처음에는 한시간만 하고 나올것 같았는데, 웬걸 1시간 30분이나 재미있게 놀다가 나왔어요! 여자친구와 즐거운 추억 간직하고 갑니다. 좋은 시간이었어요 :)', 53, 18, 'GOOD', SYSTIMESTAMP);
