INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '직원들이 정말정말 밝고 친절하셨어요^0^!!! 덕분에 더 재밌게 즐긴것 같습니닿ㅎㅎ어두운 곳에서 즐긴 다양한 활동들도 진짜 재밌었어요 최고최고 정말 추천합니당bbb', 28, 5, 'GOOD', SYSTIMESTAMP);
