INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '직원분들 텐션도 너무 좋고 너무 재밌게 놀다 간거 같아요! 연인분들이나 아직 안 친한 친구들끼리 가서 같이 놀기 너무 좋은 곳 같습니다😁 소중한 추억 만들어주셔서 감사해요😊', 48, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '정말 하루가 뜻깊게된것같아요 눈뜬 장님이 뭔지 알것같았어요 아에안보이더라구요 그래서 시간가는줄 모르고 놀았어요 단순히 놀려고 즐기는 카페가아닌 씨더라이트 본연의 의미를 제대로 알고 의미 그대로 앞을 볼수있는 소중함 가치가 얼마나 소중한지 알면서 노니 더 하루가 소중해지더라구요 애인이랑와서 큰 시간과 추억을 남겼어용 설명해주시는 언니오빠들 너무 친절하고 재밌었어용ㅠㅠㅠ💗💗 감사합니다', 4, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '이색 데이트 하기 너무 좋았어요. 정말 말그대로 암흑 카페 아무것도 안보여요. 그래서 더 진솔한 대화 나눌 수 있어 좋았고, 암흑속에서 여러 게임 할 수 있어서 즐겁게 시간 보낸거 같아요. 직원분들도 너무 친절하시고 재밌으셨어요. 새로운 프로그램 나오면 또 방문할게요 !', 45, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '서비스가 정말 최고였어요! 말을 정말 재미있게 잘해주셔서 들어갈때부터 집갈때까지 정말 재미있게 즐기고가요!! 그림에 이름 붙여주셔서 너무 웃겼어요!', 47, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '친구추천으로 어떤곳인지도 잘 모르고 방문했는데 진짜 정말 좋았습니다!! 모르고 갔던게 더 좋았던거 같아요~~! 기본게임들도 재밌고 추가게임이랑 이어폰 질문들도 정말 유익하고 넘나 즐거운 시간이었습니다😆 게임이외로도 숨겨친 체험의 순 가치도 알게되어 더 의미있는 경험이 된거같아요~! 다시 한번더 방문해보고 싶을정도로 좋았구용! 게임많이 맞춰서 추억의 상품도 받고 앵무새도🐦 타가구 시그니처 꽃도 받고 왕창 선물받고 왔습니당!! 많은분들도 가보시고 좋은 의미있는 경험 쌓으시길바라욤~~! 남친이랑 좋은 추억에 꽃선물도 받고 좋은하루였어요 감사해용😆⚘ 🐦', 24, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '직원분들이 다들 유쾌하시고 친절하세요. 이렇게까지 안 보일 줄은 몰랐는데 진짜 하나도 안 보이더라고요. 친구 3명이서 갔는데 정말 재밌었어요. 홍대에서 놀 거리로 추천합니다.', 0, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '근무하시는 직원분들이 다 너무 상냥하고 유쾌하고 재미있어요! 다들 긍정적인 분위기를 내뿜고 있어서 곁에있는 저희도 너무 기쁘고 행복했어요! 단순히 게임만 즐기는 것뿐 아니라 깊은 의미를 내포하고 있어서 체험하는 동안 더 인상깊고 즐거웠어요! 여러 체험들을 해봤지만 씨더라이트는 평생동안 기억에 오래 남을것같아요 :)', 27, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '커플이라면 묻따말 그냥 가세요 추억이며, 의미 . 무조건 남습니다!! 주변에 추천하고 난리... 스포방지위원회는 여기까지 ㅎㅎ', 24, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '진짜 알바생분들 다들 무슨일...! 같은 재질 사람들만 채용하셨나봐요🤭 너무 친절하시도 유쾌하셔서 이색체험도 즐거웠지만 사람들 덕분에 더 즐거웠네요! 좋은 교훈도 얻고가고 소중한 추억 가져갑니다 담에 또봬요!', 31, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '그냥 어두운 카페를 체험 하는 곳인줄 알았는데 깊은 의미와 정성이 느껴지는 장소라서 뜻 깊었어요 체험뿐만 아니라 체험 전 후 호 이 체험을 왜 하는지 왜 필요한지 내가 얼마나 편하게 살고 있었는지 주변 사람들과 지내는 소중함을 알게 된 계기였어요 어두운건 정말 적응이 안되더라구요 재밌었고 너무 친절 하셔서 기분 좋았습니다💕 🌷🌷', 353, 32, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '썸타시는 분들 스킨쉽 한지 별로 안되신 분들께 추천 저는 몰랐는데 폐쇄 공포증이 있는지 처음 알았네요 ㅠㅠ처음에 무서 웠네요 .. 이색체험은 체험인듯 게임 좋아하시는 커플께 추천 합니다', 29, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '안내데스크 인포누님들 너무 친절하신 거 아닙니까??ㅎ 너무너무 유익하고, 의미있는 시간 보냈어요! (장미 신상 강추 하셔서 두 친구 겟했습니다!)', 27, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '게임도 다양하여 재밌었지만, 이어폰에서 대화주제를 계속 던져주는 것이 정말 좋았습니다!! 암실이 상대의 말에 더 집중할 수 있게 해주고 깊은 대화를 나눌 수 있어서 정말 좋은 시간을 보낼 수 있었습니다. 시간 가는 줄 모르고 대화하다 보니 세 시간 가까이 이용했어요 :) 직원분들도 넘넘 친절하시고 좋으셔요~!! 비눗방울 감사합니다!!', 71, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '그냥 단순히 암실에서 게임이나 미션등을 하는 곳인줄 알았는데, 물론 게임도 재밌었지만 암실체험을 마치고 나와서 듣게된 교훈들이 굉장히 의미있다는 생각이 들었습니다 :) 직원분들도 너무 밝으셔서 안내 받는 내내 재밌었고 주변에 커플들에게 꼭 추천해주고싶어요💁🏻‍♂️', 21, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '암실카페라고 해서 호기심에 왔다가 느끼는바가 너무많아서 좋은 시간이였던거같습니다! 직원님들도 너무 친절히 설명해주셧고 체험도 너무 재밌었고 숨어있던 의미도 듣는순간 너무 유익하고 오길 잘했단 생각이 들었습니다 오면 정말 후회없는 시간 되실거라 생각합니다🌒🌓🌔🌕🌖🌗🌘', 26, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '너무 즐거운 시간 보냈어요! 포토존도 이쁘구 직원분들이 다들 엄청 해피해피🎶 하셔서 기분이 좋았습니당ㅎㅎㅎ 뽑기 해서 간식도 쏠쏠히 챙겨왔구요ㅋㅋㅋ 안에 있는 동안은 시간 가는줄도 모르고 웃다가 나왔어요~ 그리고 한 번도 생각해보지 못한 것을 생각하게 됐어요! 마침내 이해하고, 깨닫게 된😌!! 단순히 암흑카페 놀러온 것 그 이상으로 많은 걸 얻어 갑니다👍🏻 리뷰를 너무 많이 보면 스포당할 수 있으니 그냥 저 믿고 다녀오세요~!! 저는 친언니랑 왔는데 넘 특별했고 기억에 오래오래 남을 것 같아요! 감사해요💛💛 -제2의 아버지까지 같은 쌍둥이 자매👭🏻-', 71, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '암실카페. 진짜 아무 것도 보이지 않는다 많은 것을 깨닫고 가는 하루인 것 같다 게임도 게임이지만 여기서 전달해주는 메세지 특히 중요한 것 같다. 궁금하다구요? 궁금하면 지금당장 암실카페로 오세요 색다른 경험을 해보고 싶으신 분 남녀노소, 연인이든 친구든 가족이든 이 곳에 한 번쯤 가보는 것을 추천한다 “씨더라이트” 잊지말자! 여기 일하시는 분들 한 분 한 분 너무 친절하시고 잘해주셔서 너무 감쟈드립니다!', 17, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '스쳐 지나갈뻔한 기억일 것 같았는데 너무 인상깊었던 시간이었어요! 직원분들도 세세하게 신경써주시고 씨더라이트의 의미도 정말 오래 기억될 것 같아요. 재밌게 놀다 갑니당! :)', 90, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '🌹12월4일에 남자친구랑 방문해서 너무나도 좋은 기억 얻구왔습니다!지금도 씨더라이트에서 뽑기로 얻은 간식 같이 먹구있어요ㅋㅋㅋㅠㅠ처음엔 이렇게나 오랜시간 있을 줄 몰랐는데 너무나도 재밌구 즐겁고 뜻깊고 행복해서 다음 약속에 늦으면서까지 거의 두시간반을 체험하고 왔네요🥺암실 속에서 소중한 사람과 함께한다는 일이 단순히 재미만 있고 신기하기만한게 아니라 각자에게도 서로에게도 그 이상을 준 것 같아서 너무 좋았습니다 인생에 꼭 한번 혹은 그 이상 체험해봐야 할 일 인것같아요🥰물론 재미두,,너무 많이 있었구요,, 떼굴떼굴 굴렀습니다!마지막으로 직원분들 너무 재밌으시고 친절하셔서 체험내내 웃음이 끊이질않았습니다☺️감사해요! 체험하고 나오면서, 또 이렇게 리뷰를 쓰는 지금까지도 기분좋게 행복하게 만들어주셔서 감사합니다!', 9, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '우선 직원분들이 너무 너머 친절하고 유쾌 하셔서 가자마자 기분이 좋아지는 공간이였어요!! 지나가다가 우연히 보고 너무 궁금해서 방문 하게 되었는데 상상이상으로 할것도 많고 시간도 너무 빨리가고 뜻 깊은 시간이였습니다♥️ 앞으로 살아가는데 감사함을 느껴야겠다는 생각이 많이 들었고, 색 다른 체험, 뜻 깊은 시간 보내고 싶으신 분들한테 추천 드려요!!👩🏻‍🎨👒', 89, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '남자친구 생일 겸 크리스마스 데이트로 일주일 전에 미리 예약하고 다녀왔어요. 예상했던 것보다 훨씬 더 재미있고 의미 있는 시간이었어요. 어둠 속에서 글씨쓰고 그림 그리고 서로 목소리 듣고 촉각으로 맞추고 하는 시간들이 보이는 것의 중요성을 다시 한 번 알게 되는 기회였어요. 둘 다 게임에 진심이었던지라 모든 게임 엄청 열심히 하고 선물 잔뜩 챙기구 깔깔 웃다가 나왔네요. 현실에서는 진짜 간단한 게임일텐데 안 보이니까 좀 어렵기도 하구 즐거웠어요. See the light 말 그대로 뻔한 것을 깨닫고 깊숙히 이해할 수 있을 것 같아요. 오늘 저녁에 마지막 숙제까지 잘 마무리해볼게요ㅎㅎ 오늘 즐거운 시간 보낼 있었어요 감사해요~🐯🎂', 97, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '곧 1800일 되는 여자친구와 방문했습니다. 시간가는줄 모르게 재미있었고 감동도 느낄 수 있어서 매우 의미 있는 시간이었습니다. 고등학교 때 반에서 ''어둠속의 대화'' 체험을 했었는데 그 때가 기억났습니다. 그 당시와 같은 기분을 느낄 수 있었는데 나이가 들어 다시 비슷한 체험을 하니 전에는 알지 못했었던 것들을 경험할 수 있었습니다. 눈을 떠도 보이지 않아서 편하게 눈을 감고 체험을 할 수 있었습니다. 그래서 익숙하지 않은 낯선 공간에서 여유로운 시간을 보낼 수 있었습니다. 눈으로 볼 수 있다는 것에 대한 소중함에 대해서 다시 느낄 수 있었으며 감동과 재미 둘다 얻어 많은 분들이 방문하면 좋겠습니다. 빛나는 장미꽃 너무 이쁘고 감사합니다. [★닭대가리 이모티콘은 못찾겠네요★]', 102, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '즐겁고 의미있는 시간이었어요!^^ 가벼운 마음으로 찾아왔다가 마음 든든하게 채워가요~ 다음에 다른 친구들과도 다시 오고싶네요ㅎ 곧 오픈하신다는 암실게임!!기대하고있을게요♡', 76, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '커플, 썸남썸녀에게 강추!!👍👍 지인의 추천으로 알게 되어서 갔는데 생각했던 것보다 더 좋고 가치있던 체험이었어요! 처음 갔을 때부터 나올 때까지 직원분들은 친절하시고 유쾌하시고 너무 재밌으셨어요😆 어느정도의 실루엣은 보이지 않을까 생각했는데 진짜 하나도 안보이더라고요.. 그래서 되게 놀랐지만 이 체험의 의미와 가치에 대해 더 깊이 경험할 수 있었지 않을까 싶어요! 여러모로 재밌고 의미있었던 시간이었습니다~😄', 35, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '남친이 어바웃타임 재밌게 봤다던게 생각나서 왔습니다. 그냥 암실게임카페 정도로 생각하고 갔는데 느낀 것도 많고 소중한 경험하고 온 것 같아요!! 사소한 것부터 함께 있어주는 가족, 남친까지 다시 생각하게 되는 시간이었습니다~ 직원분들 에너지가 너무 넘치셔서 엄청 웃고 왔네요 ㅎㅎㅎ 내부가 생각 이상으로 어두워서 평소에 항상 잡던 손인데도 새로운 설렘이 있었던 것 같아요 :) 나오는 질문들도 너무 좋아서 대화만 조금 해도 시간이 엄청 빨리 가더라구요 ㅎㅎ 좋은 추억 선물해주셔서 감사합니다!! 다음에 암실게임도 열면 다시 오기로 했어요 히히 🙆🏻‍♂️🙆🏻‍♀️', 4, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '크리스마스에 남자친구랑 같이 갔어요. 처음에는 너무 깜깜해서 무서웠는데 서로 의지하고있다고 생각하니까 금방 괜찮아졌어요. 직원분들도 너무 재밌으시고 암실에서 미션하고 게임하는것도 재밌어서 시간가는줄 모르고 하다가 맨 마지막으로 나왔어요. 상품으로 간식이랑 장난감이랑 펭귄얼음깨기까지 받았는데 핫팩이랑 장미까지 더 챙겨주셔서 정말 맘이 따듯했던 크리스마스였습니다. See the light의 의미도 마음 속에 단단히 새기고, 당연하게 여겼던 일상의 소중함을 느낄 수 있었던 시간이었습니다. 🌹🌹', 19, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '암흑카페 처음 방문했는데 정말 재미있게 놀았습니다 보드게임카페랑 다른 재미가 있고 이색 놀이로 정말 추천합니다 다음에 또 재 방문 하겠습니다 사장님들도 재미있고 친절하셔서 너무 기분 좋게 놀다 가요 감사합니다 씨더라이트 최고 ♡', 7, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '소재가 신선하고 연인끼리 가면 재밌게 즐길 수 있습니다. 근데 매장이 약간 어수선하고 직원들 끼리 동선에 대한 커뮤니케이션이 부족해서 우왕좌왕하는 모습이 보였습니다.', 86, 16, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '작년부터 오고 싶었었는데 드디어 ! 여자친구랑 날 잡아서 오게 되었어요 ~ 근데 완전 .... 친절하고 유쾌한 직원분들 덕분에 특별하고 재밌는 시간 잘 보내고 왔습니다 !  재미 뿐만 아니라 흔한 일상들의 무심코 지나갔던 것들에 대해서 씨더라이트 속의 숨은, 값진 의미들을 알게 되는 유익한 시간이었습니다 ! 꼭 모든 분들이 방문했으면 하는 장소에요 다음에 또 재방문 할 의사 100프로 ~ 좋은 추억 만들어주셔서 감사합니다 ~', 101, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '기대이상으로 재밌고 유익한 시간이였어요! 어둠속에서 다른 감각을 이용해서 게임하는데 시간가는줄 모르고했어요! 직원분들도 너무 친절하시고 포토존도 이쁘고 뽑기도 재밌고 즐거움 가득한 시간이였습니다 친구들에게도 추천할 정도로 좋았습니다~! 🐰🐰', 62, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '주변에서 암실카페 너무 좋다고 추천을 많이 해줘서 이번에 방문해봤는데, 너무 재밌었어요! 게임 소개부터 나갈 때까지 직원 분께서 너무 친절하고 재미있게 설명해주셔서 좋았구요:D 게임들도 정말 재미있었어요! 다음에 암실게임도 오픈하면 재방문하고싶어요 ㅎㅎ 평소면 20초도 안 걸릴 일들이 아무것도 안 보이니까 정말 오래 걸리고, 시각 외의 감각들에 엄청 의존하게 되더라구요. 시각이 중요하다는 건 늘 알고 있는 거였지만, 그것을 몸소 체험할 수 있는 귀중한 시간이었던 것 같습니다 ~! 게임 끝나고 선물도 받았는데 선물 너무 귀여워요 ><@/ 꼭꼭 방문해보세요 <3', 9, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '친구랑 둘이 처음 방문했는데 다음에 또 오고 싶을 만큼 너무너무 재밌었습니다! 유쾌하신 직원분들 덕분에 들어가기 전부터 엄청 웃었어요 ㅋㅋㅋㅋ 처음 입장 때는 설레임으로, 진행하면서는 신기함과 재미로, 마지막 퇴장은 반가움과 깨달음으로 끝나는 경험이였습니다! 너무 인상 깊게 체험했고 안에 게임들도 진짜 재밌어서 계속 깔깔대면서 했어요 ㅋㅋㅋㅋ 셀프 채점 때는 충격과 공포...🤣 뽑기로 홀로그램 장미랑 간식, 친구는 무드등도 뽑혔어요!! 이색 데이트로 너무 추천하고 싶고 나가서 친구들한테 널리널리 알리려구요 ㅋㅋㅋㅋ 저희 대학생으로 봐주셔서 감사하고..😂 다음에 또 방문 할게요❣ (마스크는 사진 찍을 때만 잠시 벗었습니다:D)', 23, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '어바웃타임이 인생영화라서 암실카페 너무 가보고 싶었는데 입장 하는 순간부터 직원분들의 에너지가 엄청 넘치시고 다들 친절하셔서 저희 기분까지도 좋아졌어요ㅎㅎ 미션들도 다 색다르고 재밌었고 재미 뿐만 아니라 씨더라이트의 뜻까지 알게 됐어요 ㅎㅎ 미션 성공 후에는 뽑기로 인해 받는 상품들도 추억의 간식부터 장난감과 예쁜 홀로그램 장미까지 남자친구와 너무 뜻깊고 좋은 시간이었습니다❤️', 8, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '단순히 게임을 하는 공간이 아닌 일련의 과정과 암실을 통해서 깨달음을 얻게 되는 뜻깊은 시간이었습니다! 진행해주시고 설명해주시는 분들의 노력과 진심이 씨더라이트의 8할 이상이라고 할 수 있을 정도로 너무 좋았습니다. 더 많은 분들이 경험해보셨으면 좋겠어요 :) 🐰🖤', 20, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '안내해주시는 분이 진짜 너무 친절하셨어요! 약간 동심의 세계로 돌아간 기분이 들 정도?><  가게도 포토존도 넘 이쁘게 잘 꾸며져 있고 진행 내용들도 재밌고 친구들끼리 가기도 좋았던 거 같아요! 나중에 남친 생기면 남친이랑 와보고 싶은 생각도 드네용! 굳굳', 2, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '리뷰처럼 직원분들이 너무 다들 친절하시구 재밌었어요!̈ 게임도 정말 시간가는 줄 모르고 했구요 이색 데이트 하기에 안성맞춤인 곳이었어요!̈ 그 외에 그냥 게임을 하러 간거였는데 게임을 마지막까지 하고나서 주는 교훈이라고 해야되나...ㅎㅎ 감동적인 부분까지 완벽했습니다😭 또 개인적으로 남자친구 생일을 축하해주기 위해 따로 부탁을 드렸었는데 흔쾌히 사장님이 허락해주시구 축하도 예쁜 직원분들 모두 많이 축하해주셔서 최고의 생일로 만들어줄 수 있었어요 감사합니당☺️ 게임이 현재 한개밖에 없어 아쉬웠지만 다음 게임도 오픈하면 꼭 다시 가볼 예정이에요 ㅎㅎㅎㅎ', 10, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '게임 하는 내내 너무 웃었어요 ㅎㅎㅎㅎ 이색데이트로 최고에용 !!!☺️☺️☺️☺️ 담에 또 오고싶어요 시간가는줄 몰랐어요 ㅎㅎ 게임 끝나고 메세지도 좋았어요 평생 못잊을듯🌷🌹🌹🌷🌹🌷', 23, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '재밌을것같아서 방문했다가 진심으로 깊이 깨닫고 나옵니다ㅠㅠ 단순한 암실카페가 아니에요. 어느샌가 시각을 제외한 나머지 감각으로 모든걸 느껴야하더라구요. 눈이 사라지니 그 막막함속에서 소중함 이상의 무언가 울컥함을 느꼈습니다☺️ 끝나고 여자친구와 정답도 맞춰보며 재밌게 마무리하고 예쁜 경품까지 받아가서 너무 행복했습니다♥️♥️♥️ 정말정말 강추해요, 댓글알바가 아니라 진짜 정말 진심으로 강추합니다👍👍👍🌟', 80, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '리뷰 잘 안쓰는 편이지만 여기만큼은 정말 데이트 코스로 추천합니다. 저도 무작정 깜깜한데서 얘기하거나 게임만 하는 것 줄 알았지만 더 뜻 깊은 시간을 가질 수 있는 시간이었던 거 같습니다 저도 1시간이면 당연히 충분할 줄 알았지만 시간이 지나고 보니까 두시간이 지나 있었고 잊을 수 없는 경험이자 추억이었던 거 같습니다 다만 정말 소재로서 완벽하고 좋은 시간이었지만 나중에 신난 음악보다는 잔잔한 음악을 틀면 좋겠다는 아주 개인적인 의견을 내고 싶습니다 ㅎㅎㅎ!!! 좋은 크리스마스 시간을 보내게 해주셔서 감사하네요 ㅎㅎㅎ ☃️', 34, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '암흑이라는 색다른 주제를 가진 게임카페를 알게되어서 지난 토요일 남자친구와 방문했습니다ㅎ 암흑에서 하는 다양한 게임과 미션에 설레어서 입장하고 서로를 더 잘 이해하게되며 체험을 하였고 씨더라이트의 의미를 되새기며 옆에 있는 사람의 소중함을 한번더 깨달으며 퇴장하였습니다❣️처음엔 체험이 재밌을것 같아 가봤지만 그 이상의 의미를 얻게 된 하루였습니다ㅎ(마지막에 눈물이 고였어요😂) 암흑 속에서 게임하고 서로 대화하며 시간가는줄 몰랐고 직원분들의 유머와 재치가 저희를 더 즐겁게 했습니다! 다양한 이벤트도 준비되어있고 예쁜 포토존까지! 가볼까 말까 고민된다면 주저하지말고 방문하세요!! 옆에 있는 사람의 소중함과 빛의 소중함까지 느끼고 많은걸 배우고 올 수 있습니다👍다음에 또 남자친구와 방문하겠습니다❤️', 95, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '사장님도 친절하시고, 게임도 재밌었고, 남자친구랑 이런 기회로 중요한 이야기도 나누고, 또 좋은 메세지도 얻은 너무 행복한 경험이었습니다. 핸드폰의 존재를 까먹을 정도로 재밌고 시간도 금방 가더라구요. 진짜 친해지고 싶은 사람이랑 꼭 가셨으면 좋겠어요!', 8, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '색다르고 뜻도 깊은 체험형 카페였습니다. 안에 들어가면 정말 아무것도 보이지 않아서 살짝 무서웠지만 여자친구랑 함께 의지하며 미션도 하고 게임도 할 수 있어 좋았습니다.', 34, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '직원분이 너무 재밌으시고 굉장히 친절하세요 평상시에 절대 경험할 수 없는 체험을 할 수 있고, 의미도 찾을 수 있는 이색데이트로써 최고라고 생각합니다', 2, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '저희 둘 다 어바웃타임 영화를 너무너무 좋아해서 암실카페 꼭 와보고 싶어서 방문했어요!! 예약할 때부터 직원분들이 너무 친절하신게 느껴졌구 매장 방문해서는 더더욱 느껴졌어요!! 정말 정말 친절하시구 재밌으세여!!! 암실카페 안에서는 보이는 것도 소중하지만 보이지 않는 것도 소중하다는 것을 느낄 수 있었어요! 나와서는 옆에 있는 내 사람이 정말 소중한 사람이 느낄 수 있었어요! 직원분들 또 봽고 싶네여!!@ 정말 감사했습니다!!! 여러분 고민하지 말고 가세요 두 번 가세요!!', 4, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '오늘 남자친구 생일이라 고르고 고르다 왔는데, 인생데이트 한거 같아요❤🤭 오늘의 이 시간과 의미,  See the Light 잊지 않을게요~^^ 재미와 의미 두 가지 모두 잡는 특별한 장소에용ㅋㅋ', 38, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '의미있는 경험이었습니다 :) 자세한 체험 내용은 스포일러가 될 수 있어 얘기하지 않겠지만, 암흑카페가 정확히 뭘 하는 곳인지 모르고 방문하는 분들이 많을 것 같은데, 여러가지 체험들을 잘 준비해두셨더라고요. 마음 편히 방문했는데 입장할때부터 퇴장할때까지 체계적으로 잘 준비되어있어서 즐거운 시간 보낼 수 있었습니다. 이름은 카페지만 암흑 속에서 다양한 체험을 하고 여러가지 생각과 의미도 느껴볼 수 있는 문화공관으로 보면 될 것 같아요 :)', 33, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '우연히 홍대 놀거리 찾다가 방문 했는데 생각보다 더 흥미로웠고 좋은 체험이 돼서 좋아요! 놀기만 한게 아니라 느낀점도 많아서 이색 데이트로 좋은거 같아요 또 방문 하고싶네용 ㅎㅎ🌙🌙🌙', 98, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '오늘 첫 방문인데 너무너무 즐겁게 경험하고 가요 ㅎㅎ 저희 금손인가봐요 ㅠㅠㅠ 좋은 상품들 뽑아가지구 넘 행복해요!!😍 직원분들도 너무 친절하시고 재밌으셔서 광대가 아플 지경이었어요ㅠㅠㅋㅋ 친구랑 간만에 홍대데이트 너무 이색적이고 좋은 경험이었구, 빛을 볼 수 있다는 것에 감사히 지내야 한다는 걸 다시금 소중히 생각하면서~ 다시 한번 너무너무 즐겁고 소중한 추억 쌓고 가요❤ 재방문 의사 만퍼센트😍', 94, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '직원분들 모두 무척 밝으시고 안내도 자세히 해주셨어요! (긍정에너지 넘침!!) 항상 비슷한 데이트만 하다가 이렇게 특별한 경험을 하게돼서 좋았어요 ㅎㅎ 기본 미션들과 간단 게임들도 재미있었지만, 더듬더듬 물건 찾거나 일행 위치 찾는 아주 간단한 행동 하는거도 쉽지 않아서 무척 신기하고 재미있었어요 ㅎㅎ', 58, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '생각할 게 많은 시간이었습니다. 일상의 감사함은 물론이고, 함께하는 사람의 소중함까지 느낄 수 있었네요. 친절한 직원분들과 알찬 구성의 체험을 하며 아주 좋은 하루를 보냈습니다. 커플뿐만 아니라 친구나 가족 그 누구와도 알차게 보낼 수 있는 시간이 될 것 같습니다.', 61, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '안녕하세요 천사입니다 ㅎㅎ 👼  직원분들 진짜 리액션 좋으시구 재치도 있으셔서 재밌게 놀다가용 ㅎㅎ 선물도 너무 재밌는게 많이 준비되어 있어서 좋았어요~  오늘은 여자인 친구랑 왔는데 암실게임 오픈되면 남자친구랑도 올게요~!', 3, 0, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '최근 데이트한 곳 중에서 가장 웃음이 많았던 것 같아요. 정말 아무것도 안보이는데 이것저것 게임을 하려니까 엄청 엉뚱하게 돼서 웃음이 끊이질 않았네요 재밌어서 두시간이나 지난줄도 몰랐는데, 직원분들도 너무 친절하시고 유쾌하게 대해주셔서 행복한 시간이었어요! 100일이었는데 기억에 남을 데이트가 된 것 같아요 :)', 17, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '어바웃타임에 나왔던 암흑카페 체험해보고 싶어서 가게 되었는데 정말 어바웃타임 이상의 감동과 재미를 얻고 갑니다ㅎㅎ 직원분들도 너무 재밌고 친절하시구 다른 데서는 얻을 수 없는 색다른 경험이었어요!!  특히 어둠속에서 서로에게 편지를 쓰고 서로의 얼굴을 그려주는 활동이 있었는데 나중에 그림 확인하고 어찌나 웃었던지...ㅋㅋ 한달동안 웃을거 여기서 다 웃고가는 것 같아요ㅎㅎ 이외에도 너무 재밌는 게임이 많아서 시간 가는줄 몰랐어요ㅎㅎ 연인사이나 친구 사이에 꼭!!! 해봤으면 하는 경험입니다^^ 진짜 최고의 데이트였어요! 상품도 정말 많이 주시구...재미 이상의 감동과 의미를 찾을 수 있었던 시간이었습니다❤ㅅ', 45, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '오늘 비가 너무 많이왔는데 우산이없어서 비맞구 도착한 씨더라이트! 우선 직원분들이 너무 친절하게 맞이해주시고 재치있으셔서 카페에서 활동하는 내내 너무 힐링됐어요ㅎ 무엇보다 암실카페라는게 조금 생소할 수도있는데 설명도 너무 잘돼있고 신선한 게임들을 할 수 있어서 행복했습니다! 선물도 많이 주시구 마지막에 비 맞지 말고 가시라고 우산까지 챙겨주셨습니다ㅠㅠ 너무 감동했어요... 단순한 카페가 아닌 '' 이해하다 '' 라는 표현을 조금더 깊게 깨닫게 해주는 감동적인 카페입니다ㅎ 많이많이 가세요~~!! 더 칭찬하고 싶지만 너무 유명해 져서 예약 못할까봐 여기서 리뷰 끝!', 8, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '기대 이상으로 유익하고 뜻깊은 시간이었어요 재미만 생각하고 가볍게 갔는데 이런 뜻깊른 선물들이~~ 많은 커플 친구들에게 추천합니다!', 20, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '예전부터 가보고싶었던 이색카페였는데 안내해주시는 직원분도 친절해서 좋았고 시설도 깨끗해서 좋았어요 어두운 암흑에서 목소리에 집중 할 수 있고 1시간만 보내려고 했는데 시간가는줄 모르고 오래있었네요 주차 공간이 없어 좀 아쉽지만 주변 공영주차장에 잘 주차해서 이쁜 추억 만들고 가요 다음 시리즈가 너무 기대되네요!! 더 친밀해 질 수 있었던 시간 이였어요', 36, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '진짜 하나도 안보여요 색다른 경험이였고 시각에 대한 소중함이 느껴져요 게임 하는것도  재밌어요  직원분도 친절하시구요 화장실도 너무 깨끗해요 아쉬운건 가격대가 좀 있고 테이블끼리 조금 가깝게 있어서 다른테이블소리가 잘들려요 그래도 암전게임 오픈하면 재방문 할거에요!!!!', 129, 23, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '이마깐 남성분입니다!! ㅋㅋㅋ 직원들이 친절함과 센스까지 겸비해서 체험 이전,이후 설명들을 때까지도 너무 재밌었어요!! 일반 보드게임카페인 줄알고 갔다가 정말 많은 걸 느끼고왔네요 ㅎㅎ 강추 of 강추입니다!!', 2, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '카페 찾아보다가 너무 재밌을거 같아서 방문하게 되었는데 재미뿐만 아니라 인생의 교훈도 얻을 수 있었던 경험이었습니다!! 아무것도 안보여서촉감, 청각에 의존해서 게임하고 퀘스트를 깨나가는 과정이 재밌었고 서로에게 더 솔직해질 수 있었던 시간이었어요! 소리맞추는 게임강추!!! 짱재밌어요ㅎㅎㅎ썸타시는 분들이나 커플분들이나 친구분들 모두 재밌고 뜻깊은 시간이 될거같아요ㅎㅎ다음에 게임 추가되면 또 방문할게요^_^ 직원분들도 너무 쾌활하고 친절하게 대해주셔서 기분이 덩달아 좋아졌습니다🤗상품으로 받은 장미도 너무너무 예뻐요~~! 씨더라이트 화이팅🤩', 39, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '항상 같은 실내데이트를 하다가 검색해서 알게된 이색데이트 ! 호기심에 바로 예약 후 방문했습니다😳 좀 일찍갔었는데 포토존도 있어서 사진 찍으며 기다리다보니 친절하게 안내해주셨습니다 단순히 게임만 하는 곳인줄 알고 놀러왔다가 다양한 체험들을 통해 많은 깨달음을 얻고 갑니다 I see the light ⭐️ -E-', 8, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '인테리어도 너무너무 예쁘고, 직원 분들은 너무너무너무 친절하시고❤️색다른 데이트, 놀거리로 짱짱 추천합니다!! 단순히 암실 체험이 아니라 체험이 끝나고 나니 당연한 것은 아무것도 없다는 교훈도 주는 테마카페라뇨,,,🥺❤️ 코로나로 당연한것들을 많이 잃은 지금 그냥 호기심에 방문한 곳이었는데 즐거움에 소중한 교훈까지 얻어갑니댜❤️❤️진짜 짱짱 추천 친구, 연인끼리 너무 좋아용❤️ 번창하세요오👍🏻👍🏻', 2, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '친구 추천으로 갔는데 기대 이상으로 의미있고 즐거운 시간이었어요! 직원분들도 밝고 친절하셔서 좋았습니다😊 다른 친구에게도 추천할 것 같아요👍👍', 70, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '사장님 직원분들 엄청 친절하시고, 시간 가는 줄 모르고 2시간 순삭 당했습니다😂 사장님의 재치있는 입담도 너무 재미있었고, 좋은 교훈과 예쁜 경험 잘 담아갑니다❤️', 46, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '직원분들이 굉장히 친절하시고 이용객들에게 색다른 경험을 주기 위해 많이 노력하신다는게 잘 느껴집니다. 좋은 경험이었고 즐거운 시간이었습니다.', 6, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '리뷰를 너무 늦게 작성하네요ㅠㅠ 오픈 시간보다 조금 빨리 왔었는데 직원분이 처음부터 반갑게 맞아주셔서 입장할때부터 기분이 좋았어요ㅎㅎ 처음에는 색다른 체험을 해보고 싶어서 왔는데 생각보다도 너무 재밌었고, 전해주는 메세지가 많다는 사실이 제일 좋았던 것 같아요. 정말 단 하나도 안보여서 시각 말고 다른 감각에 의존해야만 해서 더 집중할 수 있었어요. 평상시에는 몇 초면 할 일을 암흑 속에서는 오랜 시간을 투자해서 겨우 해내거나 아예 하지 못했는데, 빛이 주는 소중함이 얼마나 큰지 새삼 깨닫게 됐어요. 분명 한시간만 이용하려고 했는데 구성이 너무 알차고 시간이 너무 빨리 가버려서 결국 한 시간을 더 했는데 비용은 아깝지 않았어요 ! 뜻 깊은 시간 보낼 수 있는 기회를 주셔서 감사합니다 :)', 46, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '부산에서 서울여행와서 암흑카페 꼭 가고 싶었는데 ~~ 직원분들도 멀리서 와주셨다고 신경써주시구 ㅎㅎ 너무 이쁜 추억 만들고 갑니다 :) 친구들한테 많이많이 소문낼게요 !!', 39, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '기대안하고 지인 추천으로 왔는데 생각보다 너무 재미있었어요ㅠㅠㅠㅠ특히 직원분들이 너무 착하고 친절해서 기분좋게 다녀갑니다! 게임도 너무 재미있고 의미있는 추억을 얻고 갑니다!', 18, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '소중한 것들을 다시금 되뇌이는 시간을 가졌던 것 같습니다. 무엇이든 당연한 건 없으니까요. 내 옆에 있는 사람들과 내 모든 것들을 한 번 더 돌아보게 되었습니다. 인생에서 한번쯤 경험해보면 좋을 것 같습니다!!', 43, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '단순히 보드 게임만이 아니라.깨달음과 생각하는 시간도 가질수 있는 의미있는 시간이였습니다. 친절한 직원분들 덕에 유쾌하면서도 뻔한것들에 대한 소중함을 알고갑니다!', 24, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '안에서 진행하는 게임도 너무너무 재밌고 단순 재미만이 아니라 다양한 의미들도 있어서 너무 좋았어요! 직원분들도 너무 친절하셔서 다음에 또 오고싶어요😄', 54, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '처음 가봤는데 너무 재밌었어요! 암흑 속에서 할 수 있는 게임이 많더라구요~ 다양한 게임 하느라 시간 가는줄 몰랐네요ㅎㅎ 남친과 갔는데 서로 사이도 돈독해지고 좋았어요. 직원분들도 너무 너무 친절하시고 색다른 경험이였습니다! 덕분에 좋은 추억 만들고 가요!💕 또 방문할께요~😊', 33, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '게임도 너무 재미있고 직원분들도 너무 친절 해서 좋았어요! 1시간 예상하고 갔는데, 설명 듣고 들어가고 게임 시간보다 준비하고 나오는 과정에서 시간 소요가 은근 많이 되더라구요 ㅠㅠㅠ 추가요금 1시간 더 내서 ㅠㅠ 조금 아쉽긴합니다!! 그래도 엄청 재밌었던 경험이였고 즐거웠습니다!!', 24, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '남자친구와 함께 다녀왔는데 직원분들이 너무 친절하겨서 재밌게 놀다 갑니다 ㅎㅎ 설마 단 한문제도 못맞출거라고 생각 못했는데 저희가 그렇게 됐네요 ㅋㅋㅋㅋㅋ 마지막 손님으로 가서 더 신경 많이 써주셔서 감사합니다 다음에 또 방문할게요~ 음료수 맞추기 어려웠어요 ㅋㅋㅋ', 23, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '주말에 생일 기념으로 다녀왔어요! 좋아하는 영화인 어바웃타임을 보고 암실카페를 찾다가 방문하게 되었는데, 재미 뿐만 아니라 배운것도 많은 체험이라 방문하기 너무 잘한것같아요 ! 진행해주시는 직원분들께서도 너무 친절하시구 진심으로 생일 축하해주셔서 정말 감사해요♥️ 무엇보다 체험을 통해 전하고자 하시는 메세지가 분명하고, 다양한 프로그램이 있어서 시간이 훅 가버렸다는 점도 좋았어요 ㅋㅋ! 친구나 가족과 같이 가도 좋을것같아요 ㅎㅎ 다음에 기회있음 또 방문할게용 또 뵈어요 우리🌞', 126, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '우연히 블로그 리뷰를 보고 여자친구와 함께 방문하게 되었습니다. 별다른 기대 없이 갔다가 너무나 뜻깊은 경험을 하고 돌아와서 생애 처음 리뷰 써봅니다. 평소에 내가 당연시 여기던 것들이 나와 다른 타인에게는 얼마나 소중한것이고 간절할까 생각하니 현재 내가 살고 있는 삶이 너무나 감사하게 여겨지더라구요. 이런 경험을 할 수 있도록 도와주시고 많은 재미를 선사해준 직원분들께도 정말 감사합다고 전하고 싶습니다. 삶이 무료하고 따분할때 꼭 가서 색다른 경험을 즐겨 보세요!!👍', 32, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '홍대에 올때마다 체험해보고싶었는데 드디어 해봤습니다! 예약을했으나 차가 밀려 5분정도 늦었는데도 괜찮다고 말씀해주셨습니다. 들어가기전 설명을 매우 꼼꼼하게 해주시고, 암실이라 사람들의 안전을 최우선으로 생각해주셨습니다. 암실에서 게임을 어떻게하나 걱정을했는데, 프로그램이 아주 잘 짜여져있었습니다. 인형의 모습을 맞추거나 돈을 세거나 물건을 맞추는 게임 등이 있습니다. 시간가는줄 모르게 게임을 했어요!! 또 상대방에게 편지쓰거나 모습을 그려주는것도 재밌었습니다! 게임이 끝나면 직원분들의 설명과 경품추첨도 있으니 꼭 한번 하시길 추천합니다! 씨더라이트 라는 뜻처럼 특히 뻔한것을 마침내 이해하는, 삶이라는 뻔한 하루를 마침내 이해하며 인생을 좀 더 특별하게 생각하는 계기가 되었습니다. 정막 추천드립니다!', 101, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '암실카페 소문으로만 듣다가 어린이날에 방문했습니다! 처음에 룰 설명해주실 때 ''절대 가볍지 않다''라는 인상을 받았고, 어두운 방으로 이동하는 것 조차도 재밌었어요 ㅋㅋㅋㅋ 직원분들이 너무 재밌고 인상도 좋습니다. 서로 협력하면서 좋은 분위기에 일 하시는 게 느껴지니까 저희 커플도 배려 받는 기분을 받았어요 ㅎㅎㅎ 특히 카운터에서 안내해주시고 마무리까지 도와주신 여성직원분은 정말 이 일에 대해 사명감을 가지고 일하시는 것이 느껴졌습니다. 마지막엔 귀한 강연을 듣는 기분이었어요 :) 길 안내해주신 남자직원분은 드립이 너무 찰지더라구요 ㅋㅋㅋㅋ 덕분에 긴장되는 암실카페를 기분 좋게 임할 수 있었습니다. 직원분들 칭찬이 절반 이상이네요! 보이지 않는 곳에서 미션을 수행하는 재미 최고입니다!! 글자 제한 아쉽다! ㅎ', 73, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '재미는 물론이고 더깊은생각까지할수있는 카페.진짜 돈아깝지않은,,,사장님이 정말정말정말 친절하고 유머러스하세요 하루를 굉장히 알차게 잘 보낸것같단생각이드네요 선물도 진짜많이받음...최고', 1, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '재미있을 것 같아서 가보았는데 예상치 않게 많은 걸 보고(???) 느끼고 가게 되어서 정말 좋은 시간 보냈네요! 이런 귀한 경험하게 해주셔서 감사합니당ㅎㅎㅎ 많은 분들이 꼭 한 번은 가보셨으면 좋겠어요~!!!', 2, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '씨 더 라이트 게임도 다양하고 사장님도 정말 친절하셔서 너무 좋았어요ㅠㅠ 안내해주시는 분이 아이스브레이킹도 해주시는 데 너무 웃겨서 친구랑 엄청 웃어ㅆ어욬ㅋㅋㅋ 암실카페에서 게임만 하는 게 아니라 씨더라이트의 모토와 알고가면 좋은 메세지도 알려주시더라구요 감동.... 담에도 또 와서 놀다 갈 생각입니다ㅎㅎㅎ', 47, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '다른 리뷰처럼 직원분들이 정말 유쾌하고 친절하셨어요. 솔직히 첨에 너무 깜깜하고 무서워서 숨이 턱 막혔는데 그래도 할만했던 것 같습니다. 이색데이트로 좋은 것 같아요. 깨닫는 것도 있고요. 시간가는 줄 모르고 했더니 요금이 너무 많이 나와서 놀라긴 했네요ㅋㅋㅋ', 45, 9, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '진정한 암흑의 의미를 체험할수있었고 친절하고 재밌는 직원분들의 설명과 도움까지 너무 뜻깊은 시간이였습니다. 저희 커플 이뻐해주셔서 감사해요!! (아들 딸 커플입니다... ㅋㅋㅋ) 다음에는 암실게임하러 방문할게요!!', 44, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '사장님들도 너무 착하고 파이팅이 넘쳐 재밌고 좋았습니다 ㅎㅎ 활동도 여러 가지의 게임을 할 수 있고 같이온 사람과 얘기도 많이할 수 있어 좋습니다. !!', 84, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '처음에는 그렇게까지 아무것도 안보일줄 몰라서 너무 무서웠는데, 남자친구 혹은 친구와 같이 할 수 있는 게임도 많아서 좋았어요!! 정말 암흑이라 처음에는 조금 답답했는데 게임에 빠져 하다보니 어느덧 두시간이 훌쩍 지났더라구요,, 꿀잼,, 특히 사장님도 너무 친절하시고, 게임 잘하면 상품도 줘서 참 좋습니다~ 씨더라이트의 의미와 게임의 속뜻도 있으니 궁금하시면 가보시는거 추천드려용 그냥 가보세요 강추!!', 31, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '➡️진짜 꼭 가보세요 후회 안 합니다⬅️ 남친이랑 같이 갔는데 너무 재미있어요ㅠ 암흑 속에서 이런 저런 이야기도 나누고 게임도 하고👍 더 사이가 좋아졌답니당ㅎ 직원분들께서도 엄청 이야기를 재미있게 해주십니당❤️ 분명 낮에 들어갔는데 해가 떨어지고 나서 나왔습니당ㅎ 배고픈지도 몰랐어요ㅠㅠ🤍➰🤍 하루동안 좋은 추억 만들어주시고 정말 감사합니당🤍 꼭 한 번 가보세요 진짜 후회 안합니다 경품추첨해서 받은 간식도 맛있어용', 26, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '처음 왔는데 카운터에 계신 분께서 정말 친절하고 유쾌하게 설명 잘 해주셔서 게임하는데 너무 재밌었고, 대기 시간이 조금 있는데 그 시간 동안에도 즐겁게 해주셔서 너무 감사했어요 ㅎㅎ 게임 종류도 정말 다양하고 카페 내부가 어두워서 서로 의지하는 계기가 되니까 사랑하는 사람이랑 오는거 완전 추천합니다~~ 경품도 엄청 준다는건 비밀이에여 ㅎㅎ', 18, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), 'ㅎㅎ너무 좋은시간 보냈어요 :) ! 단순한 암실카페인줄 알고 있었는데 ''씨더라이트''뜻을 제대로 알고 갑니다! 다음에 또 올게용~', 50, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '단순히 즐거움을 위해서 이색카페를 검색해서 찾아갔습니다. 카페에서 체험을 하고 난 뒤 단순한 즐거움뿐 아니라 여러가지 의미가 담겨있는 체험을 했다는 사실을 알고 즐거움이 더욱 커졌습니다. 직원분들도 너무 재밌으시고 친절하셔 즐거운 시간 보내고 갑니다. ㅎㅎ 선물도 잔뜩 받을 수 있는 기회가 있어서 좋았습니다. 비눗방울 잘 쓰겠습니다~ 추천!', 1, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '단순 이색카페가 아닌 좋은 취지로 만들어진 카페라 더욱 의미있고 뭔가 즐거움과 감동을 얻고 가게 되는거 같아요, 좀 더 많이 알려져서 많은 분들이 암실카페 이용했으면 하는 바램입니당ㅎㅎ우리와 또 다른 삶을 살아가시는 분들의 입장에서의 마음을 느낄 수 있는 시간이었어요. 남자친구랑 갔었는데 나오고 나서 계속 여운이 남아서 이야기 많이 나누고 나눠주신 선물 덕에 가는길 내내 많이 웃었어요! 마지막에 끝나고 직원분께서 이야기 해주시는 부분이 있었는데 들으면서 뭔가 뭉클하고 오길 잘했다 싶었어요! 여자 직원분 얼굴도 이쁘신데..너무 친절하셔서 너무 기분 좋았습니다 ❤️ 포토존도 있어서 사진도 찍을 수 있고, 카페에서 다양하게 구성된 활동들이 많아서 정말 너무 즐겁게 보내고 갔어요ㅎㅎ정말 강추해요 꼭 가보시길💛', 79, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '심심해서 들어왔다가 너무 좋은 시간 보내고 갑니다!! 직원분들도 너무 유쾌하시고 친절하셔서 너무 좋았어요! 재미 뿐만 아니라 의미도 있는 시간이었어요 ㅎㅎ 다음에 암실게임 오픈하면 또 가려구요~~ 즐거운 시간 보내게 해주셔서 감사합니당♡ ♡', 15, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '친구 4명이랑 1시간만 하고 나오려고 했는데 2시간하고 나왔어요 ㅋㅋㅋㅋ 조명이 좋아서 포토존도 너무 이쁘게 잘 나오고 직원분들더 정말 친절해요!!! 너무 감사해요~~♡', 29, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '완전완전!!! 재밌었어용 직원분들도 너무 친절하시고 ㅠㅠ 색다른 경험도 했고 진쨔 너무재밌었어요 완전 추천합니다 !! 조만간 또 방문할게요 ㅎㅎ🤍', 72, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '언니 하*&동*이에요❣️ 단순한 카페가 아니라 너무 뜻깊은 의미를 내포하고 있어서 살짝 울컥했어요.. 너무나 당연한 행동들을 고마워하시는 언니때문에 더 울컥했어요..살면서 당연한 일들은 없다는 걸 알면서도 잊고살때가 많은데 오늘 체험으로 다시 한번깨닫게 되었어요! 감사합니다 다음에 기회가 되면 또 갈게요!(언니 보러)❣️', 31, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '지인 소개로 방문했는데 직원분들이 친절하시고, 재밌었습니다.  특히 남자분 원빈 닮으심!!! 시간 가는 줄도 모르고 게임 했던 것 같아요.! 다음에 또 올게요👍', 106, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '색다른 경험을 할 수 있어서 좋았어요 ! 생각한 것보다 다양한 체험이 준비되어있어서 알찬 시간 보냈습니다 직원분들도 되게 친절하셔서 너무 좋았어요 ~ 예약하고 가시는 거 추천해요', 7, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '간만에 배꼽 빠지게 웃었네용😊 사장님께서 정말 친절하시고 재밌으셔서 더욱 더 좋은 시간 보낼 수 있었습니다~ 강력추천합니다⭐️⭐️⭐️⭐️⭐️', 31, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '너무 재밌어요!! 보통 암실카페 연인들이 간다고 하는데 저는 친구랑 둘이가서 더 재밌게 놀다온거같아요! 암실속에서 하는 게임도 재밌지만 직원분 입담이 최고입니다! 설명듣는 내내 웃다왔어요', 2, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '홍대에서 마땅히 할 게 없어서 알아보던중에 이곳 찾아서 방문해봤는데 직원분들도 너무 친절하시고 처음이랑 마지막에 진행도 너무 잘해주셔서 대기시간 전혀 심심하지가 않았어요! 진행 도중에 실수로 음료를 쏟았는데 옷부터 걱정해주시고 너무 친절하세요😭  프로그램 자체도 너무 구성 좋고 재밌어요🥰 진짜 친구끼리 커플끼리 가족끼리 누구랑 와도 재밌게 즐길 수 있을 것 같아요! 마지막에 포토타임 갖기 전에 사나.. 닮았다고 말씀해주셔서 너무 당황스러웠는데 속으로 되게 기분 좋았어요 ㅎㅎ.. 직원분들이 두분다 너무 인싸느낌.. 프로그램 자체도 너무너무 재밌어서 돈 시간 아깝지 않았어요! 재방문 의사 있고 정말 이색데이트 코스로 추천드려요😊', 45, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '한 때 예능 프로그램에서 유행했던 암실카페가 궁금했었는데 드디어 직접 가봤어요. 늘 쓰던 시각이라는 감각을 차단하고 다른 감각에 온 신경을 집중하느라 시간 가는 줄 몰랐네요. 특별한 경험을 원한다면 강추!!', 33, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '일단 사장님 너무 친절하시고 재밌고 웃기셔서 설명해주실때 웃음이 안 멈췄죠ㅋㅋㅋ너무 좋았고 남자친구랑 색다르고 특별한 시간을 보내고 왔어요 평소에 눈으로 세상을 보는 것이 당연하다고 생각을 하며 아무런 자각없이 살았는데 엄청 감사할 일이고 축복받은 일이라는 것을 느끼게 되는 참 좋은 시간이었어요 나중에 암실 게임 추가 되면 또 갈거에요 꼭!!!❤️😖❤️', 2, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '이색데이트 찾다 발견한 곳이에요~~ 가볍게 갔다가 너무 좋은 시간과 경험들을 하고 왔습니다^^ 다음에 또 가고싶어요~~ 너무 친절하시고, 따뜻하십니당ㅎㅎ', 63, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '저번주에 못가서 이번주에 다시왔는데 진짜 정말정말정말정말 좋고 정말 아무것도 안보여서 처음엔 무서웠는데 알차게 잘되있고 진짜 또 오고싶어용🖤🖤그리고 설명해주시는 남자분도 완전 재밌고 특히 다 끝나고 마지막 설명해주시는 여자분!! 완전 친절하시고 부끄러워서 말 못했는데 너무 이뻤어요,,🖤 정말 진짜 강추입니다. 꼭 가세요 제발ㅜㅜㅜㅜㅜㅜ200일에 한번 더 갈게요❣❣❣❣', 121, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '그냥 이색카페인줄 알고 재밌겠다라고만 생각하고 들렸는데, 진짜 재밌고 뜯깊은 시간이었어요! 진짜 커플들이나 소개팅하는분들에게 강추할예정입니다. 가게 널리퍼졌으면 ㅠㅠㅠㅠ', 51, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '이색적인 카페라 흥미가 생겨서 방문하게 되었는데 너무 친절하시고 활기차셔서 너무 보기 좋았구 가게의 뜻도 너무 뜻깊었습니다 재미 추구하러 가서 재미도 있으면서도 한편으론 감사하는 마음도 가지게 해준 좋은 취지의 카페인것 같고 직원분들 엄청 친절하세요 ㅎㅎ강추합니다', 49, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '좋아하는 사람과 소중한 추억을 간직할 수 있었습니다! 사장님이 친절하고 재밌어서 더욱 즐거웠습니다ㅎㅎ 암실게임 열리면 갈게요~', 47, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '씨더라이트'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '뜻 깊은 시간을 보낼 수 있었던 카페였어요! 암흑속에서 진솔한 대화 나눌 수 있어서 좋았고 게임을 통해 서로에 대한 애틋한 마음을 더욱 가질 수 있었어요ㅎㅎ 직원분들도 너무 친절하시고 재밌게 해주시려고 노력하시는 모습이 너무 감사했습니다. 카페 나오고나서 여운이 강하게 남았네요~💙', 126, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '포르투갈에서 알게된 지인과 추억회상을 위해 방문해보았습니다. 어디서 먹어도 에그타르트 맛이 달랐는데 여기는 필링맛이 똑같아요!!ㅋㅋ (페스츄리는 살짝 아쉽😂) 서울서 이만큼 비슷하게 하기 어려울 것 같아여 ㅋㅋ 담에 또 올게요', 38, 4, NULL, SYSTIMESTAMP);
