INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '머리를 비우고 싶을 때 여길 오면 도움이 많이 된다. 멍 때리기 좋은 여유로운 분위기. 아무것도 안 해도 될 것 같은 편안함을 느낀다. 봄이라서 테라스 화단에 꽃이 예쁘게 피었다. 커피도 에그타르트도 다 맛있어서 먹는 동안 기분이 좋아진다. 사장님이 여기서 오래오래 장사해주셨으면 좋겠다.', 37, 2, 'GOOD', SYSTIMESTAMP);
