INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '포르투갈 추억 앓이 하기 딱 좋은 곳! 포르투갈 여행 전에 들리면 더 좋은 곳! 인테리어가 아기자기 예쁘고, 빵과 디저트도 맛있어요. 좋은 시간 보내다가 갑니다! #연남동카페 #포르투갈느낌카페', 10, 6, 'GOOD', SYSTIMESTAMP);
