INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '회사근처 입구가 이뻐서 들어가본곳   상벤투샌드위치 나름소소  다음에는 아보카도가 들어간 도우로샌드위치 도전 직원들이 다정해서 좋았다 상술이 느껴지지않는~  접시는 좀컸으면 좋겠다 자르기가 불편 ㅜㅜ  가게가 아기자기하다 ~', 15, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '잠깐 시간텀이 남아서 찾아 들어왔는데 너무 아늑하고 포르투에 온 것만 같아요 ..! 다음번엔 시간 넉넉히 해서 와야겠어요 ~ 사장님도 정말 친절하고 .. 에그타르트 너무 맛있어요 ♥', 61, 15, 'GOOD', SYSTIMESTAMP);
