INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '포르투갈 여행 가고 싶게 만드는 포이지아. 근데 포르투갈 가고싶을 때마다 포이지아에 와서 앉아있으면 뽐뿌가 가라앉는다. 그만큼 여행 온 듯한 기분이 나는 찐 포르투갈 바이브 카페.', 39, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '아늑한 느낌의 카페라 혼자도 여럿이도 좋을 것 같아요. 우연히 들러 소금빵이랑 커피 맛있게 먹었어요! 담엔 에그타르트 먹어볼래요😊', 2, 10, 'GOOD', SYSTIMESTAMP);
