INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '포르투갈 향수를 느끼게 해줬던 성산동카페 포이지아! 직접 구워낸 포르투갈 스타일의 나타와 향긋한 커피를 맛볼수 있어요~😍 포르투갈의 영혼의 음악인 파두 pado를 포이지아에서 듣다니!! 애절한 아말리아 로드리게스 목소리를 들은지 얼마만인지~~💕💕 야외 공간도 넘 예뻐서 인스타사진 100장 찍고왔어요 ㅋㅋㅋ 포르투갈 여행을 다녀오신 분이라면 추억을 느껴보실수 있을거에요!!', 17, 7, 'GOOD', SYSTIMESTAMP);
