INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '비오는날 카푸치노 생각나서 포이지아카페에 왔어요 세번째 재방문하는 곳인데 올때마자 항상 기분좋아지는 카페에요😊 같이 주문한 에그타르트도 정말 맛있어요! 서비스로 주신 소금빵도 맛있게 잘먹었어요😍최고!!👍', 10, 6, 'GOOD', SYSTIMESTAMP);
