INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '포이지아에서 먹은 크림라떼는 지금껏 마셔본 라떼 중 단연 최고였어요. 크림이 입안에서 사르르 녹는 느낌이랄까? 거기에 에그타르트까지 곁들였더니 이건 그냥 완벽한 조합이더라고요. 내부 인테리어도 유럽 느낌 물씬이라 사진 찍기에도 최고!', 88, 17, 'GOOD', SYSTIMESTAMP);
