INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '대체적으로 잔잔한 재즈나 어쿠스틱 음악이 들려오는 .. ~ 너무 크지 않게 흐르는 음악은 대화를 방해하지 않으면서도  공간의 분위기를 한층 부드럽고 감성적으로 만들어주며 손님들이 대화를 나누거나 혼자만의 시간을 보내기 너무 좋은 카페라는 점 !', 41, 3, NULL, SYSTIMESTAMP);
