INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '헉!!!!집 주변에 카페 찾아보다가 발견해서 처음와보는데 너~~~~무 맘에드는 곳입니당🩷에그타르트도 쵹쵹해서 넘 맛있고 소금빵듀 안에가 꽉 차 있어서 좋아효~~음료도 맛있구 카페 분위기도 느낌있어서 멍때리기 좋은 카페랍니다🤤', 44, 7, 'GOOD', SYSTIMESTAMP);
