INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '포이지아 두 번째 방문했는데 너무 좋아서 앞으로도 계속 방문할 예정이에요 커피도 맛있고 디저트도 맛있는데 분위기도 좋고 음악도 끝내줘요 정말 조용하고 너무 마음에 드는 카페네요 👍 👍 👍', 98, 23, 'GOOD', SYSTIMESTAMP);
