INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '성산동 골목 무심코 지나치던 까페 였는데 브런치메뉴가 있어서 방문해봤어요. 매장에서 직접 구운 소금빵으로 만들어주신 샌드위치 넘넘 감동입니다. 아보카도도 아낌없이 들어가고... 한조각만 먹어도 배부르더라고요. 안쪽에 분리된 공간이 있어서 실컷 수다떨다 갔어요~', 43, 3, 'GOOD', SYSTIMESTAMP);
