INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '여기 에그타르트 찐맛집입니다👍🏻👍🏻 포르투갈식 좋아하는데 여기 제대로!! 슈가파우더랑 시나몬파우더도 챙겨주셔서 뿌려먹으면 더욱 맛있어요! 상벤투 샌드위치는 망고맛 달달하니 너무 맛있어요 ㅎㅎ브런치로 즐기기 딱입니당! 밀크티도 부드럽고 맛있네요ㅎㅎ 유럽 온 거만 같은 분위기라 좋아요!', 7, 5, 'GOOD', SYSTIMESTAMP);
