INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '가게 외관부터 안까지 분위기가 정말 좋았어요. 대표메뉴 중 하나인 도우로 샌드위치와 아메리카노+에그타르트 세트를 선택했는데요, 소금빵과 아보카도, 계란이 너무 잘 어울려서 진짜 맛있었어요. 소금빵으로 만들어져서 그런지 식감도 다른 샌드위치에 비해서 정말 맛있었습니다. 에그타르트도 시나몬 가루와 슈가파우더를 함께 주시는데, 뿌려먹으니 진짜 맛있네요. 성산동, 연남동 카페 맛집으로 인정입니다!', 56, 14, 'GOOD', SYSTIMESTAMP);
