INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '잠깐 있기에는 포인트가 정말 많았던 성산동 카페 포이지아. 여유로운 시간에 엄마랑 방문해서 에그타르트 , 소금빵 커피까지 쭉 느긋하게 먹어봤는데 굉장히 만족스러웠어요! 이국적인 음악이며 포르투갈 스타일의 에그타르트 디저트, 사진작가님이신 사장님께서 직접 찍은 여행 사진까지 간접 체험이지만 직접 여행 온 기분. 연남동 끝자락까지 걸어왔는데 충분히 재방문할 가치가 있었던 카페였어요!', 73, 18, 'GOOD', SYSTIMESTAMP);
