INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '성산동 카페 포이지아 다녀왔어요! 에그타르트 맛집에 디카페인 원두도 있는 카페라 너무 좋았어요!! 포르투갈 감성 작고 예쁜 카페라 내부에 있는 것 만으로도 힐링되는 기분이였어용🤍', 46, 5, 'GOOD', SYSTIMESTAMP);
