INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '여기 분위기가 너무 좋았어요!!! 가좌역에서 가깝고 연남동 끝자락의 카페이지만 그래도 붕붕이가 있어서 타고 갈수 있었습니더!! 바닐라빈라떼도 너무 맛있고 에그타르트도 완전 부드럽고 맛있었어요!! *본 포스팅은 이용권을 제공받았지만 솔직하게 작성된 글입니다.', 19, 5, 'GOOD', SYSTIMESTAMP);
