INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '성산동카페 포이지아에서 포르투갈 여행하고 온 것 같다. 여행작가님이 하는 가게 답다. 에그타르트, 샌드위치가 모두 포르투갈식이다. 우린 마자그란 마셨다. 아주 신 레몬 커피다. 레몬 좋아하는 사람에게 딱임. 바닐라빈라떼는 덜 달다.', 88, 16, 'GOOD', SYSTIMESTAMP);
