INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '오랜만에 성산동에 갔는데 이런 카페가 생겼다니! 포르투갈 컨셉의 카페라 인테리어도 재밌었고 상벤투 샌드위치와 에그타르트 모두 맛있게 잘먹었습니다~', 56, 18, 'GOOD', SYSTIMESTAMP);
