INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '혼자만의 시간을 보내려 갔는데 샌드위치도 맛있고 에그타르트도 달달하니 맛있었어요! 커피도 다 디카페인으로 변경 가능해서 카페인에 약한 저한테 딱이었습니다! 혼자 여유 있는 시간 보내고 왔네요! 최고👍', 36, 0, 'GOOD', SYSTIMESTAMP);
