INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '늦게 갔더니 여러 메뉴가 매진이라 슬펐지만, 상벤투가 너무너무 맛있어서 다 용서되는 곳이었습니다. 망고와 베이컨의 조합이 정말 고급스러운 단짠이란 이런걸까? 싶을 정도로 조화롭게 달고 짜서 먹는데 너무 행복했습니다. 공간도 아름다워서 낮에 에그타르트 먹으러 또 가려 합니다.', 0, 4, 'GOOD', SYSTIMESTAMP);
