INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '혼자방문해서 아이스밀크티 마시고, 따스한 차한잔도 하고 싶어서 디카페인아메리카노도 추가주문해서 마셨어요😊 주문한 음료 다 만족스럽고, 분위기가 정말 좋았어요!!🤩', 78, 13, 'GOOD', SYSTIMESTAMP);
