INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '분위기도 좋고 인테리어가 멋스러워요 집중해서 작업하기에도 좋은곳같아요 에그타르트도 많이 안달고 크림라떼에 브라운치즈는 잘어울립니다', 13, 8, 'GOOD', SYSTIMESTAMP);
