INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '진짜 너무너무 맛있고 완전 인생카페예요...♡ 포르투칼식 에그타르트라 진심 짱 맛있고 엄청 부드럽고 겉은 바삭해요! 특히 피칸에그타르트가 넘 맛있었어요! 그리고 커피 원두 다 선택 가능하고 다양한 유럽식 커피/음료가 있어서 좋았어요! 밀크티 짱 찐하고 마잔그란?이라는 레몬 커피는 완전 상큼상큼 매력적이었답니다! 인테리어도 포르투칼 가정집 같은 분위기에 넘 예쁘고 사진이 잘 나와요 ㅎㅎ', 36, 0, 'GOOD', SYSTIMESTAMP);
