INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '조용하게 쉬어가기도 좋고 지인들과 조근조근 수다떨기도 좋는 연남동 감성카피 포이지아는 독특한 메뉴들이 있어 도장깨기하기 넘 좋더라고요. 특히 에그타이트는 찐하고 맛있어서 한 판을 샀어도 다 먹을 수 있을 거 같았어용. 레몬커피도 완전 맛도리. 샌드위치는 소금빵과 망고의 단짠 조합이 짱짱했습니다.', 50, 10, 'GOOD', SYSTIMESTAMP);
