INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '포르투갈의 정서를 담은 독특한 인테리어와 메뉴 구성으로, 단순한 카페 이상의 경험을 제공합니다. 대표님이 여행사도 운영하고 있어서 여행에 관련된 다양한 이야기를 들을 수 있는 것도 이곳의 매력 중 하나에요', 482, 46, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '커피가 맛있고 샌드위치 존맛 ㅠㅠ 빵 별로 안좋아하는데 감탄하고 가요,, 물론 에그타르트도 맛있어요.. 분위기도 유럽온거 같고 넘 좋았어요!', 5, 10, 'GOOD', SYSTIMESTAMP);
