INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '가게 분위기가 너무 예쁘고 이국적인 감성까지 느낄 수 있어 정말 좋더라구요. 분위기도 예쁜데 커피도, 디저트도 정말 맛있어서 조만간 스터디원들과 가려고요 :) 데이트는 물론 모임하기도 좋은 곳👍🏻', 13, 7, 'GOOD', SYSTIMESTAMP);
