INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '유럽느낌 가득한 인테리어가 너무 분위기 좋고 예뻐요! 부드러운 크림에 은은한 커피향 머금고 브라운치즈까지 먹으면 단짠 매력 넘치는 시그니처 포이지아 크림라떼도 정말 맛있어요. 레몬 그라니따도 생레몬 그대로를 갈아넣어 정말 시원하고 상큼하니 맛있고요. 부드럽고 촉촉한 에그타르트와 라떼 한모금에 유럽갬성까지 더해져 기분좋게 힐링되는 곳이입니다~', 14, 10, 'GOOD', SYSTIMESTAMP);
