INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '포루투 느낌 가득한 포이지아!!! 에그타르트가 정말 유명하고 현지에 살다온 분이 차린 카페라해서 갔는데 완전 대만족 ㅠㅠㅠㅠ 저 이렇게 맛있는 에그타르트 처음 먹어봐요..!!! 퐁실퐁실해서 입에서 그냥 녹아요..! 그리고 포루투갈식 레몬커피 마셨는데 상콤하니 너무 맛있네요~~! 또 갈 카페!!', 97, 22, 'GOOD', SYSTIMESTAMP);
