INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '아이스바닐라떼 에그타르트 샌드위치 조합 너무 좋아요. 에그타르트는 계속 들어갈것 같아요! 에그타르트는 진짜 대박임,, 샌드치도!! 혼자 가기도 여럿이 가기도 좋아용', 42, 9, 'GOOD', SYSTIMESTAMP);
