INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '마포 성산에 분위기 완전 좋은 감성카페 포이지아 포르투갈에서 살다오신 사장님이 운영하시는 곳이라 포르투갈과 유럽의 감성이 물씬 느껴지는 카페에요! 커피도 맛있고 시그니처 메뉴인 에그타르트도 맛있고 티그레는 처음 먹어봤는데 티그레가 진짜 맛있었어요! 포이지아 가시는 분들은 티그레 강추입니다:) * 이 글은 슈퍼멤버스 앱을 통해 본 업체에서 할인을 제공받아 작성되었습니다.', 33, 0, 'GOOD', SYSTIMESTAMP);
