INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '진짜 와보고 싶어서 몇 달동안 갈 수 있는 타이밍만 노렸습니다! 거리가 애매해서 못 오다가 오늘 여유가 생겨서 방문했는데 진짜 다음에 가서 에그타르트 무데기로 사오고 싶어요. 매장 분위기도 좋고 가격도 만족스러워요:)', 5, 8, 'GOOD', SYSTIMESTAMP);
