INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '포르투갈에서 직접 거주하다 오신 사장님이 꾸민 카페라 그런지 매장 인테리어도 되게 엔틱하고 유럽식 디저트도 맛있게 즐길 수 있었어요!! 가볼만한 연남동 카페를 찾는다면 한번 방문해보시는걸 추천합니다!', 86, 14, 'GOOD', SYSTIMESTAMP);
