INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '성산동 카페 포르투갈을 닮은 감성카페 포이지아! 여행작가가 차린 카페답게 카페 자체가 작품같아요. 플랫화이트도 레몬에이드도 아보카도듬뿍샌드위치까지 취향저격이에요. 감성카페 포이지아 데이트 장소로 추천해요.', 39, 7, 'GOOD', SYSTIMESTAMP);
