INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '에그타르트 좋아하는 저에겐 너무너무 좋았던 카페 종류별로 다 먹었는데 담백하고 촉촉해서 맛있어요 카페라떼도 밀크티도 부드러워서 같이 먹기 좋았어요', 41, 2, 'GOOD', SYSTIMESTAMP);
