INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '연남동 성산동 멋진 카페 포이지아에서 에타랑 아아 먹었어요. 동네 골목에 멋진 카페가 숨어있어서 놀랐어요. 에타 맛집이라는데 피칸도 맛있었어요. 타르트 반죽 직접 만드시는걸 보니까 더 신뢰도 가고   원두 세종류 향도 맡고 고를 수 있었습니당.', 39, 6, 'GOOD', SYSTIMESTAMP);
