INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '성산동에 이런카페가 있을줄이야..💛 여기 진짜 너무 예쁘고요!! 디저트들도 다 너무 맛있어요 ㅠㅠ 샌드위치랑 에그타르트 꼭 드셔보세요🥹🫶✨ 사장님들도 친절하시고 분위기가 깡패입니다 여기가 포르투갈인줄..>_< 연남동 붐비는 거리와는 약간 떨어져 있는데도 벌써 조금씩 핫플로 소문나는 것 같더라구요ㅠ 완전 핫플되기 전에 이번주안에 한번 더 가려고요 ㅋㅋㅋ💛 진심 추천합니다아💛 * 체험단을 통해 서비스를 제공받았지만 솔직하게 작성한 후기입니다.', 10, 10, 'GOOD', SYSTIMESTAMP);
