INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '킬리배낭을 함께 볼 수 있는 곳으로 포르투갈 및 유럽여행에 대한 향수를 달랠 수 있어 좋아요! 음료만 마셨는데, 다음에는 빵들도 먹어보고 싶네요!', 103, 21, NULL, SYSTIMESTAMP);
