INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '오픈한지 얼마 안된거 같은데 이미 핫플인 포이지아! 유럽감성 분위기 너무 좋고 커피랑 디저트 넘 맛있었어요. 여유롭게 시간 보내기 딱이네요. 포르투갈에서 살다 온 여행작가님이 차리신 카페라 그런지 여행감성도 느껴지고  곳곳에 소품과 사진도 멋있었어요.', 4, 5, 'GOOD', SYSTIMESTAMP);
