INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '에그타르트가 쇼케이스에 있으면 무조건 추가해야 합니다. 한번이 3개 (그 이상도) 가능한 맛 오늘은 사장님이 배려해주셔서 한개 맛봤습니다! 감사합니다', 41, 7, NULL, SYSTIMESTAMP);
