INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '매장이 주는 빈티지하고 감성적인 분위기가 너무 좋았고 날이 좋아서 밖에 테라스 좌석이 정말 예쁘더라고요 ㅠㅠ 에그타르트 정말 좋아하는데 포르투갈 에그타르트가 최애인데 페스츄리 식감과 필링 정말 너무 맛있어요 🥹 콤보메뉴 있어서 저렴하게 먹어서 더 더 기분 좋네요 :)', 15, 9, 'GOOD', SYSTIMESTAMP);
