INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '연남동 보물같은 감성카페 포이지아 🤎 포르투갈식 에그타르트 넘 먹고 싶었는데! 제일 비슷한 곳인것 같아요 정말 연남동 포르투갈 그 자체 🥹 카페 인테리어도 정말 예쁘고 사장님도 친절하셔서 좋은 시간 보내고 갑니다아 화장실에 핸드크림도 있는 센스으 ✨ 연남동 디저트 맛집 감성 카페 찾으신다면 추천추천 💛', 21, 9, 'GOOD', SYSTIMESTAMP);
