INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '카페 자주 다니는데 이렇게 이쁘고 힐링되는 카페는 처음인 것 같아요!😍 분위기 너무 좋고 정말 외국의 어느 카페에 온듯한 기분이었어요🌸 디저트들도 다양하게 먹어봤는데 가치있는 연희동 카페입니다👍 에그타르트는 시나몬이랑 슈가파우더 따로 주셔서 뿌려 먹었는데 세상 존마탱🫶 소금빵도 폭신쫄깃 거리고 커피까지 진하고 좋아요! 가격도 가성비 좋으니 꼭 가보시길 추천합니다🔥🔥', 52, 13, 'GOOD', SYSTIMESTAMP);
