INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '에그타르트가 유명하다고 해서 방문했는데 찐맛집이에요 ㅋㅋㅋㅋ진짜 먹어본 에그타르트 중 1등! 겉바속촉인데 달달하고 부드럽고 너무 맛있어요 ㅋㅋㅋ다른 디저트도 다 맛있고 커피랑 음료마저 맛있어요..💛 매장 인테리어 예쁘고 친절하셔서 또 방문할거예요!!!', 67, 12, 'GOOD', SYSTIMESTAMP);
