INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '일단 분위기가 너무 좋아요. 진짜 포루투갈을 여행하는 것 같은 느낌을 받을 정도로 인테리어가 정말 너무 예쁩니다. 어디서 사진을 찍어도 다 포토스팟이에요, 심지어 화장실까지두여!! 아늑한 분위기도 있어서 그냥 혼자가서 노트북켜고 묵묵히 일을 보거나 혼자 책을 읽어도 너무 좋을 것 같습니다. 물론 친구랑 가도 좋겠지만요ㅎㅎ저는 여행에서 만난 친구를 이곳에 조만간 꼭 데려오고 싶단 생각이 들었어요. 뿐만 아니라 여기 커피맛 미쳤어요! 적당한 고소한맛과 산미의 밸런스도 너무 좋고 깔끔해요. 시그니처 메뉴로 있던 레몬커피도 처음마셔보는데 너무 맛있고 독특해서 친구꺼 다 뺏어먹고 제가 하나더 시켜줬습니당ㅋㅋ 다행히 매장에 딱 두개 남아있던 에그타르트두 겟해서 먹었는데 겉바속촉에 넘 달지않고 사이즈도 커요!! 굿💓', 7, 6, 'GOOD', SYSTIMESTAMP);
