INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '포이지아 분위기도 너무 좋고 에그타르트도 짱 맛 ,, 🤍 사장님과 직원분도 너무너무 친절하셔서 기분 좋았어요 ㅎㅎㅎ 다음에 또 방문할게요 포이지아 에그타르트 짱 !!!', 24, 7, 'GOOD', SYSTIMESTAMP);
