INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '카페와 디저트가 무척 맛있어요! 자주 방문하는 카페입니다. 새로운 메뉴로 간단하게 음식도 생겨서 너무 좋아요. 분위기나 음악, 사장님들 친절함까지 최고.. 👍🏻 늘 편안히 머무르다 갑니다. 감사합니다!', 32, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '가좌역에서 가까운 카페 포이지아 가봤어요. 분위기 너무 좋고 샌드위치도 맛있고 커피는 더 맛있어요. 사장님도 정말 친절하세요.. 다음에는 망고 샌드위치 먹어보려고요. 화장실 진짜 깨끗하고 고급스러워요.참고하세요♡', 6, 1, 'GOOD', SYSTIMESTAMP);
