INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '아늑하고 좋은 분위기와 음악. 때마침 부슬부슬 내리는 비와 함께, 맛있는 음식과 차가 어우러진 한 순간을 느끼실 수 있습니다. 하나하나 직접 숙성시키고 준비한 시그니처 밀크티와 눈 앞에서 요리해 주시는 에그 베네딕트 !! 정말 맛있습니다. 한번 두번 계속 오셔도 됩니다ㅎ', 40, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '진짜 여기 인테리어 장난 없어요! 조용한데 감성있는 카페 찾으시면 무조건 여기요! 또 방문할 예정일정도로 만족도 100입니다! 아 에스프레소랑 에그타르트 완전 맛있어용ㅎㅎ 여기 유명해지지 않고 나만 알고 싶지만 또 모든사람이 알아줬으면 좋겠고..ㅠㅠ 암튼 사장님 흥하세요!', 57, 17, 'GOOD', SYSTIMESTAMP);
