INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '기분이좋아 친구에게 밀크티를 쐈더니 친구는 나에게 피칸에그타르트를 쏩니다 의좋은형제같당🌾 그래서 긍가 밀크티도 타르트도 더 달고 맛나당💕', 25, 2, 'GOOD', SYSTIMESTAMP);
