INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '몇달 전에 다녀왔던 포루투갈 포르투를 그대오 옮겨 놓은 것 같은 카페!! 소금빵 아보카도 망고 샌드위치 너무 맛있어서 브런치로도 대만족이었고 에그타르트는 포르투 맛집에서 먹은것 만큼 맛있었어요 ㅎㅎ', 33, 0, 'GOOD', SYSTIMESTAMP);
