INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '국내 최초 포루투칼 컨셉의 메뉴와 낮술을 제대로 즐길 수 있는 대형카페!! 분위기가 미쳤을 뿐만 아니라 가격도 상당히 착하고 맛있습니다 두번 가세요!', 57, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '근처에 볼일이 있어서 갔다가 우연히 들어갔어요. 특별한 메뉴를 가지고 있는 것 같아서 주문해 봤는데(레몬커피) 취향저격 당했어요. 호불호는 갈릴것 같아지만요. ㅎ 이국적인 분위기에 음악도 넘 좋고 레몬 커피 마시러 또 갈것 같아요.', 15, 1, 'GOOD', SYSTIMESTAMP);
