INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '일단 들어서는 순간부터 포르투갈로 순간이동하는 느낌입니다. 주인장님이 직접 포르투갈에서 공수해온 아이템들로 셀프 인테리어하셔서 분위기 너무 좋고 바리스타님도 진짜 전문적으로 공부하고 배우셔서 커피맛 최고👍 커피랑 디저트 가격도 부담스럽지 않고 햇빛 잘 드는 창가에 앉아 책읽고 공부하고 싶은 아지트 같은 곳이에요!!!❤️❤️❤️', 67, 17, 'GOOD', SYSTIMESTAMP);
