INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '곳곳에서 포르투갈이 온듯한 느낌을 받을 수 있는 분위기 좋은 카페예요. 소품 디테일 하나하나에 많은 공이 들어가있어요. 커피랑 디저트도 좋았어요.', 34, 2, 'GOOD', SYSTIMESTAMP);
