INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '여기만 오면 꼭 포루투갈에 온거 같아요! 커피 디저트도 너무 맛있네용 ㅎㅎ 한 달 동안 4번은 온거 같아요 ㅋㅋㅋ날씨가 좋고 채광이 들어와서 힐링이되네요!', 37, 2, 'GOOD', SYSTIMESTAMP);
