INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '여긴 유럽감성 제대로 느낄수있는곳이더라고요. 사장님 정말친절하셨고 커피 맛있었어요. 티그레의 맛이 계속생각나서 또 갈곳입니다. 인테리어 소풍하나하나 다 디테일이👍👍👍 에그타르트도 겉바속촉을 제대로 느낄수있어 좋았어요 ☆체험단을 통해 일부 제공받았지만 솔직하게 작성한 리뷰입니다.', 27, 3, 'GOOD', SYSTIMESTAMP);
