INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '포이지아!! 시그니처 메뉴인 밀크티와 디저트로 에그타르트와 티그레. 최근에 마셔보았던 밀크티 중 최고였습니다. 그리고 디저트는 처음 맛보는데, 맛있었어요!!!', 12, 10, 'GOOD', SYSTIMESTAMP);
