INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '외국에 온듯한 따듯하고 멋있는 분위기입니다! 티그레는 많이 달지않아 좋고 사장님이 친절하세요!! 다음엔 에그타르트 먹으러 가보고싶어요!! 🤓', 87, 11, 'GOOD', SYSTIMESTAMP);
