INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '올해 다녀본 카페중에 가장 ''멋지고'' ''느낌이 좋은'' 곳이었어요. 눈길 닿는 모든곳이 근사했어요. 매장이 꽉 차있는데 사장님 혼자 모든걸 소화하고 계셔서 친절은 기대하지 않았는데, 한순간도 상냥함과 정중함을 잃지 않으시던 모습이 인상깊었어요. 사장님의 배려로 5살 아이와 잘 쉬다 갑니다. 감사합니다👍✨️', 42, 2, 'GOOD', SYSTIMESTAMP);
