INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '이렇게 분위기 좋고 맛 좋은 카페 찾아낸 나를 칭찬~.~ 샌드위치 존맛이어서 와인 한 잔만 마시려 했는데 두 잔이나 마셨어요 ㅠ 핑계아님,, ㅋ ㅋ ㅋ 레몬샤베트는 친구랑 저랑 코박고 먹음 ㅎㅎㅎㅎㅎㅎ', 22, 2, 'GOOD', SYSTIMESTAMP);
