INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '내부 인테리어가 너무 이쁘고 여행 온 기분이에요~!! 에그타르트 진짜 맛있고 성산동에 이런 맛집이 있다니,, 사장님도 친절하시고 원두도 두 종류라 취향대로 고를 수 있어서 좋았어용 ㅎㅎ 마포 놀러오면 또 올게요!!! 😆', 41, 1, 'GOOD', SYSTIMESTAMP);
