INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '성산동 이런 예쁜 카페가 있다니!! 사장님도 너무 친절하시고 인테리어도 너무 예뻐요 여행 좋아하시는 분들은 오셔서 구경하셔도 너무 좋을 것 같아요! 예쁜 여행 사진들도 가득하고 배낭도 있더라구용 에그타르트 짱맛!!💓 또 올게요 😝😝‼️‼️', 53, 12, 'GOOD', SYSTIMESTAMP);
