INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '🌟 에그타르트 3,000원 이 리뷰 보시는 분은 에그타르트 5개 사 오세요… 저처럼 1개밖에 안 샀다가 후회하지 마시길… 이렇게 맛있는 에그타르트는 처음입니다 그냥 기분 나쁘게 퍽퍽하고 포만감만 넘치는 에그타르트하곤 차원이 다릅니다 입에 넣자마자 파사삭하고 부서지는 타르트지 속 몽글 척촉한 필링,,, 하 제발 또 먹고 싶어요… 광주 살아서 먹고 싶다고 당장 먹을 수 없꼬 ㅠㅠㅠ', 39, 4, 'GOOD', SYSTIMESTAMP);
