INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '여기 커피 찐맛집이네요🥹 어젠 아이스바닐라라떼 마셨고 오늘은 아메리카노 마셔봤는데 다 맛있어요 특히 진하고 부드럽고 적당히 달달한 아바라 좋아하시는 분들은 무조건 강추입니다 앤틱가구랑 조명 엄청 좋아하는데 여기 조명, 소품, 가구들 보는 재미도 쏠쏠해요 하나하나 엄청 탐나네요🥹', 13, 6, 'GOOD', SYSTIMESTAMP);
