INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '포르투갈 카페로 컨셉이 너무 좋은데 커피맛까지 정말 좋습니다!! 직원분들도 멋지신데 친절하시네요~ 앞으로 자주 이용할 것 같아요! 포르투갈 밤이 생각납니다🙂', 20, 1, NULL, SYSTIMESTAMP);
