INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '우연히 들렸는데 무척 만족했어요! 일단 커피가 맛있어요! 원두 향이 잘나고 카푸치노도 맛있어용 ㅋㅋ 에그트라트 티그레 둘다 맛있는데 세트 구성도 있어서 가격도 저렴해요! 카페 인테리어도 멋있어서 유럽카페 느낌 물씐이에용!! 근처라면 자주올거 같네요👍🏼', 49, 3, 'GOOD', SYSTIMESTAMP);
