INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '회사 근처여서 와보게 되었는데 너무 좋아요...🥹🥹 분위기는 말할 것도 없고 음료, 디저트 다 맛있네요!! 에그타르트에 시나몬은 처음 뿌려 먹어봤는데조합이 잘 어울리고 맛있어요!! 인테리어만 봐도 포르투갈에 온 기분이고,,소품들도 너무 귀여워요🤎 사장님이 정말 친절하셔서 더 좋습니다!!', 19, 4, 'GOOD', SYSTIMESTAMP);
