INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '예쁘고 아름다운 카페네요. 직원분들 친절하시고, 무엇보다 커피가 맛있어서, 리뷰라도 적어서 보답하고 싶어서 리뷰 올려요! 적극추천 합니다.', 12, 0, NULL, SYSTIMESTAMP);
