INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '포르투갈 카페 느낌 물씬나요. 사진들도 직접 찍은거라 그런지 더 멋있는거같아요. 특히 에그타르트 겉에 빠삭하고, 속은 촉촉하고 너무맛있어요 꼭드세요!! 아메리카노랑 시그니쳐라떼도 에그타르트랑 잘어울려서 너무맛있게 잘 먹었네요', 63, 12, 'GOOD', SYSTIMESTAMP);
