INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '커피랑 디저트 존맛탱,,💛💛 개인적으로 슈톨렌 너무 맛있었음!! 포이지아 방문하면 슈톨렌은 기본으로 시키는 거 추천!!!!! 그리고 포르투갈 컨셉의 카페인데 분위기 진짜 대박,, 재방문 의사 완전 있음!!!!! ദ്ദിᐢ. .ᐢ₎', 20, 9, 'GOOD', SYSTIMESTAMP);
