INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '우연히 들어왔는데 이렇게나 분위기 있는 카페라니.. 소품 하나하나, 카페 곳곳 사장님의 포르투갈 사랑이 느껴집니다. 독특한 메뉴도 있는 데다 맛도 정말 좋습니다. 집 앞에 이런 카페라니, 보석을 발견한 느낌이네요. 와인도 있어서 다음에 와인 마시러 오고 싶네요.', 68, 15, 'GOOD', SYSTIMESTAMP);
