INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '새로생긴 카페인데 금방 유핫플될거같은 너낌 …🫢 주차가 가능하다고 해서 저녁시간대에 방문해봤어요!! 디저트도 맛있고 ,, 인테리어도 완벽해용 분위기가 아늑해서 좋았고, 걸려있는 사진들도 해외감성이라 사진전 보는 것 같았어요 ..! 제 최애 디저트는 판나코타 … 🩷🩷 탱글탱글하고 ,, 인스타 갬성이에용 오랜만에 만난 친구랑 대화 잘 하구 갑니다!! 포이지아 라떼에는 꼬리꼬리한 브라운치즈 올라가서 달달하구 맛도리… 슈톨렌은 품절이라 못먹고가네요 ㅠ ㅠ 아수워요 … 담에 다시 와서 꼭 먹고 갈게요 🙌🏻', 27, 2, 'GOOD', SYSTIMESTAMP);
