INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '얼그레이도 커피도 달콤한 디저트와 분위기까지도 너무 멋찐 곳입니다. 인테리어와 장식들 하나하나 사장님의 정성과 애정이 가득한것 같아요. 사장님이 너무 친절하신데 게다가 완전 미남이세요.👏 간판이 잘 안 보일 수 있는데 녹색간판이에요. 사장님 친절함에 감사드리고, 재방문하겠습니다!!', 26, 3, 'GOOD', SYSTIMESTAMP);
