INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '포르투갈 분위기가 물씬 나는 카페가 연남동에 생겼다니 정말 자주 애용할꺼같아요 👍👍👍음료랑  에그타르트가 정말 맛있는거같아요 :)', 18, 1, 'GOOD', SYSTIMESTAMP);
