INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '🌷분위기 포르투갈 감성이 물씬 풍기는 카페네요 ㅎㅎ 우드톤의 인테리어 분위기로 아늑한 느낌이 가득해요 사장님이 직접 찍으신 여행 사진들은 이곳의 특별함을 더해주네요 ㅎㅎ 연말에 연인과 방문하면 좋을것 같아요 🌷맛 판나코타를 시켜먹었는데, 고급스러운 커피 품질과 함께 제공되는 디저트의 풍부한 맛을 느낄 수 있었어요 ㅎ 덕분에 따뜻하게 있다가 갑니다 ~', 128, 19, 'GOOD', SYSTIMESTAMP);
