INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '가오픈 기간중에 방문했는데 분위가와 맛이 너무 좋아요🤍 커피는 산미 많이 없는 고소한 맛이어서 자주 갈거같아요!!! 초코라떼는 고급진 초코맛이어서 완전 추천이요!!🙂 슈톨렌있는 카페가 많이 없는데 사장님이 맛보여주셔서 크리스마스에 큰거 주문할려구요🤩🥳💕 바나나브륄레는 꼭 드세요!!!! 너무 맛있어서 필수에요오우우ㅜ🧡🧡', 30, 5, 'GOOD', SYSTIMESTAMP);
