INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '와 사장님 인테리어를 직접하셨다고 들었는데 장난아니네요👍👍👍 사장님이 여행하면서 찍은 사진과 인테리어 속에서 진한 커피 한 잔하니 가본 적 없는 포르투에 온 것 같아요! 금손💪 그리고 디저트도 너무 맛있네요! 겨울시즌이라 슈톨렌도 먹어보고 싶었는데 인기가 많은가봐요 솔드아웃이라ㅠ 다음에 먹으러 오겠습니다! 덕분에 맛있게 먹고 갑니다😎 참, 개업 선물로 주신 엽서 너무 이뻐요! 감사합니다!', 46, 8, 'GOOD', SYSTIMESTAMP);
