INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '매장 하나하나 정성드려서 꾸미신 티가 나서 대접받는 기분이라 좋았어요 ㅎㅎ 음료도 너무 맛있고 에그타르트도 여기가 포르투칼입니다!… 디저트 필수,,,', 24, 9, 'GOOD', SYSTIMESTAMP);
