INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '커피도 맛있고 우드톤이라 아늑해요. 연남동 인근 주민이라 여기저기 예쁜 카페 다녀봤는데, 최근에 가본곳 중 가장 마음에 드네요 ㅎㅎ창가 1인석이 있어서 자주 올 것 같아요.', 104, 21, 'GOOD', SYSTIMESTAMP);
