INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '주변 지나가다가 신상 카페가 있어서 방문했어요! 사장님이 무척 친절하시고, 디저트가 맛있어서 지인 크리스마스 선물로 몇개 더 샀어요. 연남 오면 종종 들리고 싶네요.', 3, 4, 'GOOD', SYSTIMESTAMP);
