INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '지인 추천으로 방문한 카페인데 분위기도 좋고 음료도 맛있어요. 특히 디저트... 꼭 드셔야해요! 사장님 직원분 너무 친절하셔서 기분 좋아졌어요. 재방문 의사 있습니다! 포이지아 짱!🤍', 44, 10, 'GOOD', SYSTIMESTAMP);
