INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '가족들이랑 다 같이 방문했는데, 카페 안쪽 룸에서 도란도란 얘기하기 너무 좋았어요 💕 어른들은 와인이랑 커피 마시고 초딩은 초코라떼 먹었어요! 친구들 모임으로도 자주 올게요!', 46, 9, 'GOOD', SYSTIMESTAMP);
