INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '포이지아'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '가좌역 가는 길에 우연히 들린 카페였는데, 커피랑 디저트로 푸딩 시켰는데 너무 달지 않아서 너무 맛있게 먹은 것 같습니다 :), 여자친구도 맘에 들어했어요! 아늑하고 따뜻한 분위기라 겨울에 방문하기 좋은 카페였어요!', 18, 1, 'GOOD', SYSTIMESTAMP);
