INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '줄설까바 조마조마하면서 달려왔어요! 그래도 점심시간 이후라 다행이 손님이 줄었어요! 자리도 넓고 인테리어 너무예뻐여!!!!!!! 혼샐러드 하기 너무 좋아요!!!!! 다이어트중인데 알맛게 양도많고 맛있게 먹었어요! 대박나세여', 15, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '훈제연어 과카몰리 샐러드, 바질 봉골레 파스타, 통다리로제현미리조또 먹었어요, 샐러드가 제일 취형저격이네요, 친구들과  수다떨며 즐겁게 먹었어요.', 59, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '점심을 간단하게 먹고싶어 언더랩으로 출동! 감자스프 .현미 닭다리 리조또 라자냐 (사이드 ) 우삼겹 들깨깻잎 파스타 에요! 음식이 전체적으로 부담이 하나도 없는 건강한 맛이에요! 담백하고 위가 부담이없어요! 기분좋게 배불러요✨ 인테리어는 이태리에 앤티크한 느낌이에요! 위치는 조금 구석에 있어서 잘 찾아오셔야해요! 감자스프는 크리미한 감자에 고소하고 담백하구 리조또는 현미의 식감과 닭다리의 짭쪼름함 덕에 술술 잘 들어가구 파스타는 익기 너무좋구 고기도 담백하구 들깨가 많이있어두 깔끔해서 신기해요! 라자냐는 진짜 추천해요✨ 여기 라자냐는 부담이없어요! 진짜 존맛탱이에요! 매우 건강한 음식들 , 친절하신 직원분들 , 기분좋은 배부름 최고에요! 🫡 키오스크 주문후에 기다리면 가져다 주십니다! 잘먹었습니다!!!', 40, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '훈제오리랑 포케 조합이 신기해서 시켜봤는데, 생각보다 훨씬 잘 어울려서 놀랐어요. 훈제오리가 기름지고 진한 풍미가 있는데, 위에 올라간 부추가 느끼함을 싹 잡아주면서 향긋한 맛을 더해줘요. 소스도 과하지 않고 재료 본연의 맛을 살려줘서 끝까지 질리지 않게 먹었어요. 보통 포케는 연어나 참치 같은 해산물 느낌이 강한데, 이 메뉴는 한식 느낌도 나서 색다르고 재미있었어요. 양도 든든해서 한 끼 식사로 충분했고, 신선한 채소랑 오리가 조화롭게 어우러져서 만족스러웠습니다.', 30, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '연남 많이 갔는데.. 여기는 왜 이제서야 알게 된 맛집일까요..😆 가성비 갑 맛도 갑인 곳이에요✨ 남자친구랑 기념일이라 다녀왔는데, 가격이 웬만한 양식집보다 저렴하구요 저렴한데 맛은 비싼 파스타랑 다를게 없어요👍👍 매장이 청결하고, 직원분들도 넘 친절하십니다💕 데이트 코스로 손색 없는 곳이에요 ㅎㅎ 남자친구랑 여기 또 오자면서 맛나게 그릇 비웠네요 ㅋㅋ 우삼겹들깨깻잎파스타랑 통다리로제현미리조또 와방 추천하는 메뉴구요!! (넘 맛있게 먹었어요 ㅎㅎ) 다음 연남 데이트 때 또 갈거에여 진짜루🤭🎀', 38, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '너무 그리웠던 두치샌 ,, 🥹 ,, 연남에 다시 생겨서 너무 기뻐요 !!!! 인테리어도 너무 예쁘고 건강한 식사로 완벽해요 🩷', 226, 69, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '가벼운 개 먹고 싶어서 다녀왔어요 . 연어 포케 시켰고 연어가 신선해서 맛있었습니다! 속재료로ㅠ들어가는  토마토랑 버섯도 예상 못했는데 잘어울리더라구요', 47, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '처음 가게 고를 때부터 메뉴가 시선을 끌어서 방문했는데 가게도 너무 예쁘고 음식도 정말!!! 맛있었어요 특히 파스타가 살짝 매콤한데 맛있어서 너무 좋았어요🥹 사장님도 정말 친절하시고 매장 분위기도 너무 좋고 진심으로 추천합니다✨️', 19, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '건강한 식사 하고 갈 수 있는 곳 같아요! 특히 인테리어가 너무 예뻐요~~ 두유 크림치즈 샌드위치 너무 맛있어보여요 다음에 또 올 것 같아요🤩🤩', 7, 0, 'GOOD', SYSTIMESTAMP);
