INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '샐러드집 찾다가 발견했는데 샐러드는 안먹고 다른것만 시켰지만 탁월한 선택이였습니다! 후무스라는걸 처음 먹어봤는데 완전 취저~ 다들 와서 먹어보세요 음식들이 다 맛있어요!', 9, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '브런치 먹고싶어서 찾아보다가 언더랩 추천 많이 들어서 와봤어요! 가게 분위기도 넘 좋고 파스타는 사이드메뉴로도 있어서 좋더라구요ㅎㅎ 잘 먹었습니다👍🏻', 64, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '토요일인데도 웨이팅 없이 바로 입장했고 음식도 바로 나왔어요!! 브런치 요즘 넘 비싼데 저렴하구 메뉴를 골라 담길 수 있는게 좋은 것 같아요!! 저는 일본인인데 입맛에 잘맞았습니다!', 83, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '저장하고 와보고 싶었던 곳이었는데 너무 만족합니다! 우선 양도 많고 신선하고 맛있었댜😋… 두부 후무스 샐러드 포케 시켰는데 건깅하고 든든해요! 친구들이 시킨 나만의 브런치 메뉴들도 조금씩 맛 봤는데 다 맛있어요 재방문 꼭 해서 다음은 나만의 브런치 세트로 먹고 싶어요 ㅎㅎ', 25, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '근처에 일 있어서 왔다가 검색해서 방문했어요. 골목길에 위치해 있어서 눈에 잘 띄진 않지만 리뷰가 좋아 방문했는데...비주얼에 보다는 맛이 더 좋은 곳이네요.특히 우삼겹들깨깻잎 파스타가 들깨향이 풍부해서 맛있게 먹었습니다.', 71, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '자냐자냐 라자냐~~ 연어포케 우삼겹포케 바질페스토 샐러드 진짜 다 맛있어요❤️ 색감도 너무 이뻐서 먹기아까웠어요 ㅠ 신선함이 보여요🌸 셀프주문이지만 음식은 가져다 주신답니다^^', 15, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '첫 방문인데 맛있어서 또 오게 될 것 같아요! 인테리어도 너무 예뻐서 약속장소로 딱이에요! 다이어트 하시는 분들 강추입니더 ㅎㅎ', 1, 6, 'GOOD', SYSTIMESTAMP);
