INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '단호박크치샌디치 넘 먹고싶어서 방문했어요!! 생각보다 매장 내부 분위기 엄청 힙해요!! 평일 오후 방문했더니 여유있고 좋아용 ❣️', 45, 7, 'GOOD', SYSTIMESTAMP);
