INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '두번째 방문이예오~홍대입구역에서 가까운 펀이고 밥이랑 디저트도 다 먹을수있고 애매한 시간에 밥+카페 다 되서 모임장소로 더 좋은 것 같아요! 분위기도 차분하고 음식도 메뉴도 많고 다 맛있어요🥰', 21, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'MEETING');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '메뉴구성이 좋은데 맛있고 건강해요!🌿 단호박에 두유크림치즈조합이 너무 맛있을것같아서 왔는데 맛있고 신선하고 건강하네요 재료관리를 잘하나봐요! 연남동 브런치 검색해서 왔는데 메뉴구성이 하나같이 좋아서 다음엔 나만의BRUNCH SET로 3가지 조합해서 먹으려구요 재방문의사 있습니다!(집앞이면 창가석으로 혼자주올것같은!)', 12, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '단호박을 워낙 좋아라하는데 여기에 두유로 만든 크림치즈까지 넣은 샌드위치가 있어서 찾아왔어요! 맛없없 조합인데다가 재료도 신선해서 맛있어요~ 빈티지한 소품들과 연남동다운 chill한 바이브도 인상적인 곳입니다!', 42, 0, 'GOOD', SYSTIMESTAMP);
