INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '친구들이랑 브런치 먹으려고 방문했는데 매장도 넓고 음식도 너무 맛있어요!! 평일 오전엔 사람도 많이 없어서 편하게 식사했습니당~~', 57, 18, NULL, SYSTIMESTAMP);
