INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '건강한 음식 가볍게 맛있게 잘먹었습니다! 음악도 잔잔하고 인테리어도 예쁘고 깔끔한 매장에서 둘이 대화하면서 먹기 좋았어요! 다음에 또 올게요~', 29, 5, 'GOOD', SYSTIMESTAMP);
