INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '처음 와봤는데… 왜 이제야 알았을까요? 오늘은 연어훈제포케랑 나만의세트로 라자냐 + 레몬크림치킨 + 시금치페스토파스타 먹었는데요, 진심 하나도 빠짐없이 다 맛있어요!! 연어훈제포케는 신선한 야채에 훈제연어가 푸짐하게 올라가 있어서 한입 먹자마자 상큼+고소 폭발!! 포케 좋아하는 분들 무조건 만족하실 듯요.', 117, 21, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '연남동에서 이렇게 분위기 좋은 곳 처음 봤어요 ❤️조용하면서 대화하기도 좋고 사진도 잘 나와요 완전 자연광 맛집 혼밥으로 먹기도 좋게 메뉴 구성도 좋고 다이어터들도 약속에 부담없이 먹기 좋아요 맛있어서 진짜 싹싹 비웠어요….추천합니다 👍👍', 83, 18, 'GOOD', SYSTIMESTAMP);
