INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '데이트하는데 한 명만 다이어트 하고있어서 포케랑 일반식 같이 먹을 수 있는 곳 찾다가 방문했습니다 🫧 파스타랑 포케 둘 다 맛있구 사장님도 친절하셔요 🫶', 73, 18, 'GOOD', SYSTIMESTAMP);
