INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '일단 인테리어가 너무 너무 예쁘고 ... 나만의 세트 메뉴로 제가 먹고 싶은 걸 다양하게 혼자 먹을 수 있어서 너무! 좋아요 이제 홍대에 오면 여기로 밥 먹으러 와야겠어요🤍🐾', 7, 3, 'GOOD', SYSTIMESTAMP);
