INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '꼭 와보고싶었던 언더랩❤️ 단호박두유크림치즈 샌드위치와 우삼겹 들깨깻잎 파스타 시켰는데, 너무 맛있고 파스타는 특히 들깨가 들어가서 고소하니 더 맛있었어요ㅎㅎㅎ 브런치 카페에서 이렇게 맛있는 식사 오랜만 인것 같아요🥹', 25, 10, NULL, SYSTIMESTAMP);
