INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '다이어트 중인데 식단 할수 있는 이쁜 샐러드 가게가 있어서 참 좋어요 >_< ♥️맛도 좋고 분위기도 좋고 감사히 잘묵었습니다 ^^', 39, 10, 'GOOD', SYSTIMESTAMP);
