INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '들어올때부터 친절하게 안내해주시고 양이많고 맛있어요♡ 브런치 세트 고를 수 있는게. 너무좋아요♡ 주차는 불가해서 공용주차장에대고왔어요', 101, 23, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '햇살 맛집 언더랩!!오랜만에 맛있는 샌드위치가 끌려서 왔는데 샌드위치와 커피의 조합이 역시나 짱이였어요!! 다이어터지만 좋은 분위기에서 한끼 드시고 싶다면 무조건 언더렙입니다', 20, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '벌써 4번째 방문일 정도로 너무 맛있어요 🤍 다른 데에서도 비건 단호백 샌드위치 먹어봤는데 이 맛이 안 나더라구요 .. 😇 너무너무 추천합니다!! 🥹', 70, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '나만의 세트 구성을 내가 골라담을 수 있는게 넘 좋아요 맛있는게 많은 언더랩에서 다양한 걸 한 번에 먹을수있어요 딸기두부크림치즈 샌드위치도 짱맛ㅜ 또갈게요!', 19, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '피부 관리에 진심인 남친을 위해 건강하면서 맛있는 식당을 찾다가 오게 되었어요! 모든 메뉴가 다 맛있어요🩷 특히 필라프랑 라자냐 최고ㅠㅠ 나만의 세트로 골라서 먹었는데 추가금도 많지 않고 가성비 좋게 너무 잘 먹고 왔습니다! 먹다보니 너무 배불러서 리뷰이벤트 음료는 안 받았지만 개인적으로 넘 만족스러워서 리뷰 남겨요!! 무조건 재방문 예정입니다☺️☺️', 98, 19, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '단호박두유크림치즈 먹고 싶어서 방문했어요! 같이 주문한 레몬크림치킨도 넘 맛났어요! 다이어트 할때 칼로리 걱정안하고 부담없이 건강하고 맛있게 먹을 수 있는 레스토랑입니다! 엄마랑 여동생이랑 왔는데 셋다 만족하고 갑니다 ㅎㅎ', 20, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '오픈시간부터 핫한곳이네요! 맛있는데 건강한 재료들이 들어가서 더 기분좋게 먹었어요. 양도 넉넉해서 부족함없이 먹었어요. 그리구 직원분들 바쁘신 와중에도 모두 친절하셔요~', 23, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '우삼겹들깨깻잎파스타 신선한 조합인데 넘 맛있어요 딸아이가 싹싹 긁어 먹었습니다 그리고 가라아게청양파스타도 매콤꾸덕하니 맛있고요 라자냐가 정말 맛있었어요 라자냐를 5천원대에 먹을 수 있게 해주신 사장님 감사합니다 매장도 예쁘고 다 좋았어요', 80, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '다이어트 중이여서 포케 맛집 추천받아서 왔습니다. 후무스랑 구운 버섯이 진짜 맛있어요ㅜㅜ 저는 여자중에서 상당히 잘 먹는 편인데도 양 괜찮았습니다. 내부 인테리어도 예뻐서 데이트로도 좋을 것 같아요.', 21, 8, 'GOOD', SYSTIMESTAMP);
