INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '맛있어서 재방문 했습니다! 홍대 오면 파스타 집은 항상 이곳으로 방문해요 가격도 괜찮고 맛있어서 다음에도 재방문 의사 있습니다👍👍👍👍', 44, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '집에서 배달로 먹어보고 맛났던 기억이 있었는데 오늘 우연히 아가랑 지나가다 발견해서 먹으러왔어요! 지난번에 못먹어본 메뉴까지 먹아봤는데 역시 다른 메뉴도 맛나네요🤩', 42, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '인테리어 연남동 갬성..❤️ 이맛에 연남동 와요 ㅎㅎ 맛있어요!! 로제 파스타 맛집입니다 친구가 자꾸 로제 맛있다구 ㅋ̄̈ㅋ꙼̈ㅋ̆̎ㅋ̐̈ㅋ̊̈ 라자냐도 맛나대용 ㅎㅎ', 4, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '브런치 세트에 메뉴구성을 고를 수 있어서 좋아요ㅎㅎ 두유단호박 샌디치 넘맛있어요ㅠㅠ 매장도 예쁘고 아늑해서 비오는 날 최고의 선택이였습니다!! 또 올게요🤍', 14, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '오늘 아이친구 엄마들 만나러 브런치집 알아보다 언더랩 연남점 보이길래 처음으로 왔어요~ 가성비 좋고 깔끔하고 대화하면서 먹기 참 좋아요~ 편암해서 다음에 또 방문해볼 예정이예요~^^', 26, 4, NULL, SYSTIMESTAMP);
