INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '맛있어요 ♥ 들깨와 깻잎이 잘못하면 향이 너무 세기 마련인데 적당하고 잘 어울렸어요! 현미 리조또도 식감도 좋아서 기대 이상이에요 😋', 9, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '친구랑 같이 왔는데 뷰도 좋고 분위기도 좋고 직원 분들도 친절했어요! 대기 없이 바로 입장했고 둘이서 오기 딱 좋은 거 같습니다. 음식도 맛있었어요 ㅎㅎ 감사합니다!', 26, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '재료가 전부 신선하고 맛있어요! 브런치 메뉴류나 포케 좋아하시면 너무 만족할 밥집 입니다! 특히 후추나 스리라차 소스가 구비되어있어서 입맛에 맞게 먹는게 너무 좋았어용!', 44, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '세트메뉴도 있고 단일메뉴로도 꽤 착한 가격대라 여러개를 시켜서 먹을 수 있어서 좋아요~ 내부가 따뜻하고 해가 잘 들어서 기분 좋게 식사할 수 있습니다~!', 40, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '다이어트 중이라 지인이랑 뭐먹을지 고민하다 방문했어요 ㅎㅎ 다이어트하는 사람치고 아주 많이 먹었찌만... 다 먹고싶어서... 다 시킬 수 밖에 없었어요🥲 너무 맛있게 잘 먹었습니당! 야채도 신선하고 구운버섯 추가하기 너무 잘했고 ㅠㅠ 닭가슴살이랑 달걀도 넘 맛있었어요!! 후무스랑 당근라페도 넘 맛있어요 ㅠㅠ 특히 후무스... 양도 엄청 많고 최고다요 진짜.... 양 짱 많아서 놀랐어요...ㅎ 후무스 남는거 있으세요?!?! 지짜 또 방문할게요 ㅠㅠ 직원분들도 너무 친절하셔서 좋은 기억만 가지고 갑니당!!', 46, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '다이어트 중에 데이트 장소를 찾다가 발견했는데 연남에 이렇게 예쁘고 맛있는 포케집이 있었다니🥺 여길 왜 이제야 찾았을까요... 두유 크림치즈 정말 맛있고 포만감 대박,, 토핑들 푸짐해서 너무 좋아요ㅜㅜ 육회포케 강추합니당!!!', 19, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '브런치 가게 찾다가 아무 정보없이 오게 됐는데 메뉴도 다양하고 맛도 있습니다~// 브런치 즐기고 싶으신 분들에게 강추합니다bb', 54, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '실내가 깔끔하고 아늑한 느낌이라 친구랑 와서 가볍게 먹기 너무 좋아요! 메뉴도 포케종류도 다양하지만 그 외에도 먹고싶은 메뉴가 너무 많아요 ㅎㅎ 다음에 재방문의사 있습니다', 76, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '포케 먹고싶어서 들어왔는데 넘 분위기도 좋고, 음악도 좋고!!! 일찍왔더니 차분하고. 무엇보다 빈티지한 인테리어가 너무 좋았다. 홍대근처에 은근히 포케, 샌드위치 집이 있는 것 같으면서도 없어서 아쉬웠는데 앞으로 여기 와야겠음. 단호박두유크림치즈 샌드위치가 너무 맛있어서, 집가는길에 딸기말차샌드위치도 사감. 존맛탱! 자주와야지.', 78, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '여자 여섯이서 점심 회식으로 살안찌고 괜찮은 곳 없을까 찾다가 분위기 좋은 샐러드가게를 찾았어요🍀 사장님께서 테이블도 붙여주시고 가게 분위기도 예쁜데 음식 맛이 너무 좋네요 👍 건강한 메뉴인데 너무 너무 맛있어요 매일 와야징💗💗', 22, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '비오는 날 들어갔는데 가게가 너무 깨끗하고 좋네요. 브런치 세트 구성해서 먹고 싶은대로 골라먹을 수 있어요. 레몬치킨이랑 라자냐 존맛탱ㅎㅎ', 17, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '양도 많고 가성비가 너무 좋아요!!! 잘먹었습니다 ㅎㅎㅎ 맛도 있고  분위기도 좋아서 자주 올 것 같아요 😊 데이트코스로 추천해요', 121, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '양도 많고 음식도 마싯어요 ! 인테리어도 멋있고 의자가 편해서 밥 먹기 좋습니다 ㅎㅎ 원하는 메뉴를 직접 선택할 수 있어서 좋아요', 46, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '포케 양 엄청 많고 맛있어요! 종류가 다양하고 드레싱 추가할수있는거 많아서 좋았어요 ღ•͈ᴗ•͈ღ 포케시러인간은 파스타먹을수있어서 좋았습니다', 46, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '친구가 찾은 맛집이라서 저녁에 방문했는데 인테리어도 예쁘고 도란도란 얘기하면서 먹기에 좋아요!! 자극적이지 않고 깔끔하고 건강한 맛이라서 편하게 먹고 갈 수 있습니당ㅎㅎ 한 플레이트에 여러 음식을 담을 수 있어서 좋앗어요!!', 44, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '연남동에서 먹어본 포케들 중에 제일 신선하고 양이 많은거같아용 지인이 먹던 파스타도 다 맛있고 감자/단호박스프 진짜 존맛입니다...이재 포케집 여기로 정착할거같아요', 43, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '음식이 깔끔해서 좋아요!!ㅎㅎ 현미밥과 채소 겻들여 먹고 있는데 든든하게 먹을 수 있어서 좋은것 같아요 :) 인테리어도 독특해서 보는 재미도 있네요ㅎㅎ 다음에 또 방문하게 될 것 같아요~~ㅎㅎ', 70, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '두번째 방문인데 오늘도 너무 맛있어요ㅠ 제가 먹었던 포케 중에 원탑이에요 따릉이 -> 언더랩 식사 코스 추천 드려요 ㅋㅋ 존맛!', 35, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '연남동 포케집 검색해서 처음 방문했는데 크리스마스 시즌에 알맞게 꾸며진 아늑하고 따스한 인테리어가 1차로 마음에 들었고 그릴드비프 포케가 맛있어서 2차로 마음에 들었습니다. 키오스크 주문하고 요청사항 말씀드리니 잘 반영해주셨어요. 토마토살사 소스는 처음인데 생각한 맛은 아니지만 나름 새콤하니 괜찮았습니다', 49, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '단호박두유크림치즈 샌드위치랑 시금치바질후무스 시켜봤어요~ 두유크림 엄청 맛있습니다 시즌메뉴로 딸기두유크림치즈 샌드위치도 있는데 두개 고민하다가 단호박이랑 더 어울릴듯해서 주문했는데 탁월한 선택이였어요 ㅋㅋ 그리고 바질을 좋아해서 홀리듯 시금치바질후무스 도 추가주문했는데 진짜 이것도 너~ 무 맛있네요 ㅋ 조만간 또 와서 다른메뉴도 먹어봐야겠어요^^ 식탁보도 크리스마스 분위기.. 음악도 클스분위기 물씬이고요 여기 커피도 맛있네요^^', 87, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '가벼운 한 끼 찾다가 파스타 주문했는데 소스랑 면 비율이 적당해서 마지막까지 맛있게 먹었어요 샐러드랑 곁들여 먹으니 더 좋았어요 파스타 종류는 다 맛있은 거 같아요 ^^&', 50, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '포케 맛집입니다. 샐러드나 면이나 현미밥 선택이 가능하고요. 감자스프가 특히 맛있어요. 매장이 예뻐서 친구랑 가기도 좋고요. 혼밥으로도 좋아요. 신선하면서 맛있는 샐러드 먹을 수 있어서 좋았어요. 다이어터들에게 너무 좋네요', 19, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '로제파스타 좋아하는데 통닭다리까지 같이 나오니까 더 든든하고 좋았어요 부드러운 닭고기를 소스에 찍어 먹으면 풍미가 배가 돼요 분위기도 좋아서 데이트하기도 딱입니다. ~~', 13, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '바질향 가득한 봉골레파스타를 찾다가 방문했어요 조개도 푸짐하고 소스가 깔끔해서 마지막까지 남김 없이 먹었어요 분위기도 좋아서 편안하게 식사했어요 😊', 13, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '통닭다리로제파스타 먹었는데 진짜 닭다리가 통째로 나와요~로제 소스가 진짜 맛있어요! 플레이팅도 예쁘게 나와서 좋고 분위기도 짱짱!!😍', 28, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '내가 만들어먹는 브런치세트에 두유로만든 크림치즈 샌드위치까지 너무 맛도리쟈나~~~ 전부 신선하고 양도 많아서 배불렀다! 특히 치킨이랑 파스타가 완전 존맛🫶', 2, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '연남에 파스타 맛집 참 많지만 언더랩만큼 만족스러운 곳 드물어요! 연남 포케 맛집으로 이미 접했는데 포케가 너무 맛있어서 최근에 파스타 신메뉴가 생긴 거 보고 두 번째 방문으로 파스타 먹어봤는데 역시 맛있어요! 데이트 하시는 분들 점심으로 여자친구 데려가서 포케랑 파스타 먹이면 무조건 칭찬 받아요! 포케로 가볍게 죄책감 덜어주고 파스타로 적당히 배 채워주고 ㄹㅇ 일석이조(경험담)', 66, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '딸이 데리고 온  맛집! 너무 신선하고  맛있게 먹고 가요. 어쩜  음식들이  깔끔하고 건강한 맛일까요? 친구들 데리고  와야겠어요. 아담하고  좋아요.', 114, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '봉골레파스타 맛있어요>.< 조개도 듬뿍 들어있고 양도 꽤 많아서 배불러요! 매장이 깔끔하고 샐러드, 파스타 종류 다양해서 좋네요', 25, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '언더랩 광화문점때부터 자주갔었는데, 연남점에 생겼다능거알고 이제야와보네요! 그때 먹었을때도 너무 맛있게 먹었었고 회사 지인들한테 엄청 추천했었는데 그 맛 그대로 연남점에 생겨서 너무 좋아요❤️ 인테리어도 지금 크리스마스 분위기로 이쁘게 꾸며놔서 더 좋네용..🥰', 50, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '페퍼로니 라구 파스타 진짜 맛있어요 최고 !! 메뉴도 다양하고 양도 포만감 느껴질정도로 많이 주세요! 원래 이런 리뷰 한번도 안쓰는데 추천하고싶어 올립니다~!!!!', 15, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '봉골레파스타 너무 좋아하는데 사장님도 친절하시구 매장도이쁘고 맛도 일품이였어요!! 너무 맛잇어서 두그릇먹고 싶을정도...😆 다음에 또 방문할게용~!', 31, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '다이어트 중이지만 친구를 만나야 된다면 언더랩 연남점 추천합니다! 토마토살사 소스 처음 먹어보는데 너무 맛있네요 🥹 다음에 또 올 의향 있습니다! 훈제연어 오리고기 포케 다들 드셔주세요', 19, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '혀나랑연수랑 오랜만에 만나서 홍대데이트! 여기 포케 개맛있더라ㅠㅜㅜㅠ 앞으로 친구들이랑 이런 건강한 음식 먹어도 좋을것같다 ㅎㅎ 연수 너무너무 좋은 소식도 들어서 좋았다 ㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠ연수야너무축하해진짜ㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠ행쇼ㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠㅠ', 1, 5, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '힐사이드테이블 그리워하다 발견했어요! 다이어트중에 괜찮을 것 같아서 먹었는데 생크림이 들어있더라구요ㅠㅠ 적혀있으면 좋았을 것 같아요 비싸지만 맛은 있었습니다!', 15, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '포케맛집 찾다가 처음 와보는데 매장도 너무 예쁘구 사장님도 친절하시구 양도 많아요! 맛도 물론 이백점! ⋅⌣⋅ᰔᩚ  자주올게요!', 56, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '구운두부 후무스 포케 존맛입니다!! 후무스 2종 들어가서 완전 고소하고 건강한데 넘 맛나네요 감자스프 시금치 키쉬 모두 건강한 식재료 맛이 잘 느껴져서 좋더라구요~~단호박두유크림 샌드위치 하나로도 충분히 배불러요^^', 66, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '나만의 델리에 푹 빠져 자주 찾고있는 언더랩 연남점. 메뉴 하나하나 본연의 맛이 잘 느껴질 뿐 아니라 맛있고 건강하게 한끼할 수 있어 좋아요. 게다가 포근한 느낌이 드는 인테리어는 덤!!', 26, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '#협찬 메뉴를 골라서 먹을 수 있는 연남동 브런치 맛집 이라길래 친구랑 방문했어요! 아침 일찍 열어서 아기들 등원 시키고 오기 좋았구요~ 연남동에서 몇 없는 아기의자 있는 맛집이었어요! 재료도 실하고 브런치인데 가성비가 완-전 좋더라구요! 그리고 재료도 신선하고 구성도 조합도 다양하게 할 수 있어서 좋았답니다. 사실 풀때기 먹으면 금방 배 꺼지고 배고프잖아요.. 여기는 양도 많은데 포케는 현미밥, 메밀면, 파스타면 구성 중에 고를 수 있어서 든든하게 먹을 수 있더라구요. 분위기도 레트로해서 좋았어요. 다음번에는 아기 데리고 남편이랑 가족 외식 하러 오려구요❤️', 20, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '연남동 포케집 찾다가 방문했어요! 메뉴 옵션도 다양하고 색다른 메뉴도 있어서 좋았어요 다음엔 브런치 세트 먹어보려고요! 직원분들도 친절하셔서 좋습니다 ✌🏻', 84, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '나만의 브런치 세트로 3가지 메뉴를 골라 먹을 수 있는 점도 마음에 들고 제가 선택한 메뉴들이 다 맛있어서 너무 좋았어요~! 건강하고 신선한 메뉴들이 많아서 좋았고 브런치 뿐만 아니라 포케도 너무 맛있게 먹었네요~ 이렇게 맛있게 먹으면서 다이어트 할 수 있다는 점이 너무 좋네요~!', 333, 45, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '가성비 있게 서양식 브런치를 건강하게 먹을 수 있는 곳이에요 레몬크림치킨과 콜드페스토파스타 너무 맛있네요 같이 주문한 감자스프도 속 뜨끈하니 좋네요', 51, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '포케도 너무 맛있구 종류도 많고 구성도 좋아요! 분위기도 너무 좋아요! 포케, 샐러드 종류 파는 집이 이렇게 분위기 있을 일인가요🥹 너무 예뻐요!! 다음에 연남동 오면 또 올게용🤍😆', 417, 40, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '넘넘 맛있는 연남동 브런치 맛집이어요🤤 샐러드랑 샌드위치, 스프 시켰는데 먹은지 세시간 지난 지금도 배가 부른 기적✨ 양넘많… 특히 후무스가 들어가서 색달랐고 볼 안에 따뜻한 재료가 들어가서 추운 날씨에 든든한 샐러드 식사 했어요👀 인테리어도 예쁘고 메뉴도 다양해서 혼밥하러 또 갈듯!', 74, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '두유크림샌드위치가 너무 궁금해서 먹어보고 싶었어요!!! 딸기까지 들어가 있으니 딱 겨울 샌드위치로 좋은 것 같아요~ 매장 분위기도 괜찮고 연남동에서 건강한 메뉴 찾으시는 분들한테 추천드려요!', 45, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '재료너무 신선하고 언더랩을 알고난 뒤로 계속 언더랩 오는중…. 분위기도 힙하구 요즘 제주변사람들이랑 맨날 언더랩갑니다 파스타도 있고 샌드위치 포케 등 메뉴가 다양해서 더 좋아요', 19, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '갑자기 추워진 날씨에 숙소에서도 가깝고 11시 반전에 여는 음식점을 찾아 들어왔어요. 따뜻하고 포근한 분위기의 브런치카페네요. 내부가 생각보다 넓고 음식도 맛있게 먹었습니다. 아이와 가기에도 좋네요^^', 70, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '연남동 골목 샐러드, 브런치카페 언더랩에 처음 방문했어요!! 건강하고 다양한 메뉴들이 있어서 좋아요! 부담없는 가격으로 이것저것 시켜 먹을 수 있는게 정말 좋은점 같아요👍🏻 재료들도 신선하고 푸짐해서 주문한 메뉴들 배부르게 즐기고 왔어요♥️ 연남동 언더랩 추천해요☺️', 44, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '연남 브런치 맛집 발견했네요..💗 단호박 두유크림치즈 샌드위치 첫 입 먹고 진짜 반해버렸어요 !! 완전 강추 메뉴입니다👍 나만의 세트로 레몬크림치킨, 현미불고기필라프, 라자냐 선택했는데 너무 맛있었어요🫶🏻 시금치페스토파스타도 맛도리 메뉴 입니다😎 어떤 메뉴를 시켜도 실패없을 것 같아요 💜', 12, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '친구랑 다이어트 중이라 왔는데 분위기도 너무 돟아요!!! 너ㅜ 맛있게 생겼는데 신선하고 구성이 알차요!!! 샌드위치도 너무 맛있어보여요ㅠㅠㅠ 다음에는 꼭 먹으려고요', 20, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '역시 맛있는 언더랩! 메뉴구성도 다양하고 샌드위치 최애에요💓 그리고 단품구성으로 레몬크림치킨도 먹을수있어서 너무좋아요♥️ 사장님이 너무 친절하세요!', 30, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '인테리어도 너무 예쁘고 포케 양도 많고 넘맛있어요!!! 구운 버섯이 킥입니다...한입먹자마자 추가하고시픔.. 직원분들도 엄청 친절하셔요!! 저장해두고 자주와야겠어요 ㅎㅎ ❤︎', 25, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '와 무화과 두유크림치즈 샌드위치 진짜 넘 맛있어요!!! 사실 샐러드집이라 샌드위치는 기대하지 않았는데 넘 맛있어서 놀랐어요 ㅠㅠ 우삼겹샐러드는 뭐 당연히 맛있구용 제 자신에게 건강과 맛 둘다 챙기고 싶을 때마다 들리려구용', 36, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '단호박두유크림치즈 샌드위치랑 메밀면 포케 브런치 먹고 왔어요🥰 단호박이 이븐하게 익어서 식감이 넘 좋았고, 두유크림치즈가 넘 고소하고 부드러워서 맛있었어요👩🏻‍🍳 일반 크림치즈보다 더 건강한맛이라 부담도 없고 좋네요! 주말 브런치 데이트로 넘 잘먹고 갑니당🤍🧡 둘이 가시면 샌드위치는 꼭 하나 시키는걸 추천드려요🫶🏻', 49, 0, 'GOOD', SYSTIMESTAMP);
