INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '요즘 다이어트 중이라 시험도 끝나고 약속도 있는데, 어디로 놀러가지 뭐먹지ㅠㅠ 하던 중에 검색해서 알게된 곳이라 와봤는데 분위기도 너무 좋고 자주 올 거 같아요..! 숨겨진 맛집 이런 분위기..너무 좋아요🥺🫧 오래 장사해주세요..🩷🤤 예쁜 곳 힐링하는 곳 잘즐기다 갑니다! 자주 방문할게요🤤🤍🖤🍀', 35, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '델리브런치 원하는 메뉴들로 고를 수 있어서 넘 좋고 건강에 좋은 메뉴들이라 와봤는데 맛도 넘 좋네여!! 인테리어도 예뻐서 더 좋아요 ㅎㅎ', 113, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '보통 연남 카페에 기대하는게 예쁜 공간 + 맛있는 음식일텐데 여기는 두 가지를 다 갖췄어요 샌드위치랑 포케 모두 좋은 재료로 제대로 구성하신게 느껴지고 브런치라고 양 쪼매나지 않고‼️ 든든하게 잘 먹었습니다 연남에서 브런치 생각나면 여기 와야겠어요 포케 베이스를 only채소, 파스타/메밀면, 밥 중에 고를 수 있는데 소스도 여러가지 있어서 취향에 맞게 먹을 수 있어요 🥰 그래서 재료 이것저것 여쭤봤는데 사장님께서 친절히 대답해주셔서 감사했습니다 두유크림치즈샌드위치 처음 먹어보는 음식이었는데 상큼하고 너무 맛있어요 달달한 무화과랑 찰떡궁합...🩷 계절과일 달라지면 또 먹으러 오려구요', 17, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '매장 분위기도 너무 좋고 샐러드도 너무 맛있어요!!! 먹는내내 너무 맛있다고 우리집앞에도 있었으면 좋겠다 했어요~ 이렇게 건강한데 맛까지 있는곳 너무 좋아요 샐러드 먹으러 연남동 자주 올 것 같아요❤️❤️', 21, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '다이어트중이라 포케집 찾아서 왔어요!! 인테리어도 이쁘고 맛도있고 양도 매우 푸짐합니다😆😆 그리고 포케를 취향껏 토핑을 고를수있어서 조아용!', 28, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '포케 엄청 빨리나와요 친구는 오리, 전 연어로 골라 먹었는데 재료도 신선하니 좋았어요 양은 좀 적은 느낌이었지만 골고루 먹어서 건강해지는 기분이 들었어요ㅎ 특히 버섯구이가 맛있었어요~~', 110, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '후무스 있어서 너무 좋아요 콜드파스타도 젛아하는데 있어서 좋습니다 포케 많이 먹어서 질렷엇는데 여기는 새 메뉴들이 많아서 좋아요! 콜드파스타 진짜맛잇네요!', 66, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '재료하나하나가 단백하고 재료본연의 맛이 잘 느껴져 맛있었어요!! 모든 메뉴가 맛있었지만, 감자스프의 쫀득함에 놀라움 가득🌟🌟 감자스프랑 포케 추천해요!!', 23, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '퀴노아후무스, 라자냐, 당근라페 주문했어요. 혼밥, 혼술이었는데 단품으로 조금씩 맛볼수 있어 무척 좋았습니다. 양도 넉넉하고, 잔 와인도 생각보다 훨씬 맛있네요. (네이버지도앱 와인 쿠폰 놓치지 마세요) 후무스맛은 독특한 편이고(타히니와 마늘맛보다는 인절미맛이 많이 나요!) 라페는 달짝지근해서 라자냐와 어울리네요!', 70, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '분위기도 좋고 뭔가 나만 알고싶은 가게 느낌이에요!! 내부도 진짜 깔끔하고 데이트하기 좋은 곳이에요 파스타랑 포케도 있으니 골라서 먹기 좋아요🥰', 48, 9, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '포케가 맛있는 언더랩! 감자스프도 사이드로 시켰는데 굿! 종류가 다양해서 골라먹기 좋고 건강식으로 딱이네요~ 포케맛에 푹 빠졌어요>.<', 50, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '포케가 먹고싶어 찾아보다가 언더랩에서 먹어본 적이 없어서 궁금해서와봤어오 ! 인테리어도 너무 멋지고 포케 구성도 너무 좋아요 🥗 현미밥, 메밀면 등 채소&면 및 소스도 자유로이 고를 수 있어요~ 그리고 무엇보다 너무 맛있네요..🥹 훈제연어와 과카몰리 조합이 최고임미다〰️', 53, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '재료들이 신선해서 정말 맛있었습니다. 특히, 밥과 야채, 의 조화가 좋았고, 소스도 입맛에 맞게 선택할 수 있어서 만족스러웠습니다. 포케 위에 올려진 과카몰리와 토핑들도 신선하고 맛있었어요.', 2, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '포케 좋아하는데 종류도 다양하고 양이 진짜 많아요! 재료도 신선하고 건강식으로 먹기 좋더라구요. 점심시간에 포케 먹으러 자주 이용하려구요🙏', 86, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '와이프랑 가볍게 식사하려고 들렀는데 맛도 있고 가격도 저렴해서 좋았어요 그릴드 치킨 포케샐러드 먹었는데 가볍게 식사대용으로 좋았습니다 재방문각입니다~', 42, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '다이어트 할 때만 샐러드 먹나요⁉️ 맛없고 지루한 샐러드 먹을 생각에 속상하시나요⁉️ 그릴드치킨, 훈제오리, 육회, 비프파스타 등등 진짜 다양한 토핑으로 입맛대로 취향대로 시켜먹을 수 있는 이 핫할 샐러드집 👉 ⭐️언더랩 연남점⭐️ 저도 사실 샐러드는 다이어트 할때만 먹고 그래서 사실 샐러드에 대한 이미지가 반갑지는 않아요ㅋㅋ 약간 식단조절 들어간다~~ 이런느낌‼️ 근데 저 샐러드, 언더랩에서는 자주 먹을 거 같네요 샐러드 말고도 다양한 포케도 있고~~ 특히 사이드메뉴가 다양한게 너무 좋았어요ㅎㅎ 감자스프, 라쟈냐, 레몬크림치킨, 당근라페 등등 진짜 다양해서 사이드 고르는데 한참 걸렸어요 시킨 메뉴 모두 다 재료가 신선했고, 건강하면서도 맛있었고❤️ 오랜만에 나에게 건강하고 맛있는 한 끼 선물했네요🥰', 3, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '언더랩은 처음인데 음식이 담백해서 좋았어요 구운두부 샐러드 먹었는데 맛도 좋고 야채에 과일에 두부까지 구성도 좋고 가격도 저렴해서 좋았어요', 18, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '육회샐러드 넘 맛있고 양도 엄청 많아요! 인테리어도 이뿌고 직원분도 너무 친절하구 주변에서 샐러드 먹을 일 있으면 꼭 다시 오려구요!!', 40, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '지인분이랑 처음 방문했고 단호박두유크림치즈 샌드위치 주문했는데-! 생각보다 단호박 양이 어마어마하고 맛있어용 ㅎㅎㅎ 가격대비 양이 실한 것 같아용 ! 포케&샌드위치 좋아하시는 분들 추천합니다-!', 20, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '건강하고 마싯는 브런치를 먹고싶다면 연남 언더랩으로,, ㅠㅠ 동생 샐러드 안먹는 사람인데 푸파했어요 ㅋㅋ 물론 저도 푸파하고 .. 왜캐 다 맛도린지 샐러드로 배빵빵 채우고 갑니당. 옴뇸뇸 특히 계절 과일 무화과 두유 크림치즈 샌디치 왕마싯음.. 😋', 55, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '구운두부 후무스 포케 샐러드는 처음인데 다이어트 샐러드로 좋았어요 두부도 부드럽고 맛은 정말 담백했어요 재료가 워낙 신선하니 맛도 좋았습니다', 36, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '친구랑 우삼겹 포케샐러드 먹었는데 우삼겹고기도 부드럽고 토마토에 어니언후레이크까지 재료가 정말 신선했어요 가성비 있게 먹고 왔습니다', 35, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '두유크림치즈라는게 특이해서 방문해봤는데 카페아늑하고 인테리어도예뻐요! 무엇보다 샌드위치가 양이많아서 식사로 충분할꺼같아요 ㅎㅎㅎ! 건강하면서도 맛있는 한끼로 추천해요', 79, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '친구소개로 알게된곳인데 그릴드비프 사워크림 포케샐러드 먹었어요 고기는 엄청 부드럽고 토마토에 어니언 후레이크에 푸짐하고 맛있었어요', 125, 25, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '다이어트 음식도 일케 푸짐하고 맛있게 먹을수 있다니 놀랐어요 재료가 신선해 씹는 맛도 좋고 간이 강하지 않아 재료 본연의 맛이 느껴졌어요', 46, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '플레이팅이 너무 예쁘고 양이 되게 많아요 스프 꼬소하고 넘 맛나용 사이드도 다양하고, 연남동에서 가격 부담 없이 포케 먹을 수 있는 집인것같아요 ㅎㅎㅎ', 55, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '음식이 넘 맛있어 다이어트 음식이라는게 믿어지지 않았어요 영양 가득하고 신선한 재료로 만들어 포만감이 금새 느껴겨 친구와 배부르게 먹을수 있었어요', 59, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '연남동 브런치하면 여기죠! 골라서 먹을 수 있는 브런치라 이색적이고 맛있어요:) 건강식으로 먹기 좋고 가격대도 적당한거 같아서 좋네요', 22, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '매장 분위기도 너무 좋고 포케, 샐러드, 파스타 맛있게 잘해요 👍 첫 방문이였는데 재료도 신선하고 양도 꽤 많고 포만감 제대로네요 너무 맛있어요', 36, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '우선 깔끔한 인테리어에 놀랐습니다. 메뉴는 샐러드 인데 , 평소 샐러드를 즐겨서 먹지를 않는데, 일반 샐러드와 달리 고기와 생선 여러가지 야채와 더불어 건강한 샐러드 종류가 많고, 재료 본연의 맛을 살린 메뉴가 많아서 좋았습니다.', 17, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '언제먹어도 너무 맛있는 언더랩의 브런치에여~♡ 배달로만 먹다 매장와서 먹었더니 더 맛있는~♡♡ 엄마도 만족!! 내일은 편하게 점심은 포케로 시켜먹어야징~', 9, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '사이드메뉴 선택할수있는게 많아서 좋았고 소량으로 적당히나와서 혼자방문했는데도 맛있는 라자냐를 먹을수 있어서 너무좋았어요 ㅎㅎ 진짜 맛있어서 메뉴다뿌시러 자주오려고요', 11, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '훈제오리부추포케샐러드 먹었는데 양도 넉넉하고 오리고기도 담백고소해서 첫 방문에 만족! 깔끔한 매장 분위기와 사장님 친절 덕에 단골로 정할 듯해요.~~', 75, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '언더랩 연남점 처음 와보는데 연어포케가 너무 맛있어요 너무 신선해요 재료가 신선하고 양도 많아요 연남동 포케 맛집으로 추천합니다 메밀면도 맛있어요', 60, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '포케와 단호박 샌드위치가 담백하고 채소가 싱싱해서 아삭한 식감이 좋았어요. 다이어트 메뉴로 너무 좋을 것같아 단골 예약입니다.^^', 61, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '단호박 너무 맛있고 두유크림치즈 궁금해서 먹으러와봤는데 완전 맛있어요 ㅎㅎ 건강하게 담백한 맛이에요!! 안에 잼도 발라져있어서 심심하지않게 먹을 수 있습니다 😋', 95, 24, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '원하는 3가지 메뉴를 선택해서 먹을 수 있고 재료들도 신선하고 가득해 포만감이 느껴져요. 가격도 부담 없고 퀄리티 좋은 한 끼로 만족스러웠습니다.~~', 9, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '양도 진짜 너무 많아서 포만감도 느낄수있구요 재료도 정말 신선해서 채소의 아삭한 식감도 좋구요! 음식도 깔끔하고 사장님도 친절하셨슴당^^ 자주 갈께요', 41, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '매장도 너무 감성적이고 음식이 너무 맛있어요 !!! 연남동에서 프레쉬하고 건강하지만 든든하고 맛있는 브런치 먹고싶을 때 완전 강추 👍🏻👍🏻', 53, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '평소 포케는 배달로 자주 시켜먹었는데 연남동에 위치한 샐러드 전문점 언더랩에 직접 방문해서 먹으니 더 맛있네요~일단 가게 분위기가 아늑하고 포케는 기본에 충실하면서도 토핑이 다양해요 메인 메뉴에 곁들일 사이드메뉴도 다양해서 다이어트하더라도 포만감 있게 먹기 좋을 것 같아요!', 83, 16, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '매장이 넓구 깨끗하고 예뻤어요! 음식도 가성비 있게 맛있게 먹을 수 있어서 좋았습니다 친구랑 왔는데 남자친구도 데려와도 될거같아요 혼밥하기도 좋습니다 맛있게 먹었어용', 34, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '진짜 자주자주 오게되는 맛집! 메뉴는 진짜 다 추천이라고 할 수 있을 정도!! 맛있어요!~ 저는 그릴드치킨하고 훈제연어 좋아해요~ 지인들한테 추천하고 있어요^^', 12, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '홍대주변 다이어트식 찾다가 언더랩 발견하고 들어왔어요! 메뉴구성이 너무 알차고 구운버섯 추가했는데 버섯이 진짜 맛있습니다… 나만의 세트로 메뉴를 다양하게 맛볼 수 있어서 좋았어요! 그리고 후무스 어떻게 만드신거죠 중독성 있어요ㅜㅜ 집에 가져가고싶습니당 번창하세요🫶🏻🫶🏻', 48, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '재재 방문, 그릴드치킨 맛을 잊지 못해서 재방문했어요. 평일 점심방문이어서 그런지 사람도 없어서 브런치하기 넘 좋았습니다 !🤤', 43, 4, 'GOOD', SYSTIMESTAMP);
