INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '광화문 쪽 언더랩을 자주 이용했는데 집앞에도 있는걸 알았다면 더 빨리 올걸 그랬어요ㅜㅜ 항상 맛있는 언더랩 믿고 먹습니다 ㅎㅎㅎ 당근라페도 넘 맛있어용', 75, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '다이어트 중에도 맛있게 먹을 수 있는 곳! 신선한 재료와 적당한 포만감 덕분에 자주 찾고 있어요. 건강을 챙기는 느낌이에요.😋', 46, 10, 'GOOD', SYSTIMESTAMP);
