INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '와 여기 포케랑 단호박샌드위치 진짜 맛있어요~! 담백하고 채소도 싱싱해서 아삭아삭 식감도 넘 좋구! 소스도 진짜 맛있어요 단골 해야겠어요 💚', 70, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '점심식사를 가볍게 먹는 걸 좋아하는데, 샐러드집 찾다가 리뷰가 좋아서 방문했어요!! 다양하게 커스텀할 수 있고 양도 많아서 좋네요 ㅎㅎ 다음번에는 브런치메뉴 즐기러도 방문드릴게요 ❤️', 46, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '음식이 아니라 건강을 먹은것 같아요 신선한 야채의 아삭한 식감이 좋았고 다이어트중인데 적은 칼로리로 배부르게 먹을수 있어 너무 행복했어요', 1, 4, 'GOOD', SYSTIMESTAMP);
