INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '연남동 최강 맛집인듯해요 샌드위치집 많이 가봤는데 샐러드 들어간 샌드위치어서 그런지 정말 신선해지고 건강해지는 느낌이어서 좋네요 ^^', 25, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '저 여기 단골입니다. 여긴 모든 메뉴가 다 맛있고 야채들이 굉장히 조화로워요 특히 사이드도 기가막히게 맛있습니다 여긴 무조건 세트로 드시는걸 추천해욤 언더랩 짱!! 또 올게욤💜', 6, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '훈제오리 부추포케샐러드 먹었는데 재료가 신선하고 아삭해서 식사 후에도 기분이 상쾌하네요. 다양한 메뉴와 깔끔한 플레이팅까지 브런치로 딱입니다.^^', 30, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '육회포케 아주 맛있어요! 버섯 식감이 아주 예술입니다아 당근 좋아하시는 분들은 라페 추가 꼭 하세요🧡🥕 분위기도 좋아서 기분 좋게 다이어트 가능', 79, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '연남동 샐러드 맛집 언더랩에서 포케로 점심 해결했어요 샐러드 재료도 다양하게 들어있고 너누 맛있게 먹었어요 점심으로 먹었는데 포만감 제대로네요♡_♡', 3, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '냠냠.. 신선하고 맛나요! 처음와봤는데 양도 혜자스럽고! 스프도 정말 고소하구! 가게도 깔끔하고 사장님도 친절! 단골가게로 찜~!', 39, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '연어포케 맛있게 먹었어요>.< 포케 중에서도 연어 들어간거 좋아하는데 양도 많고 은근히 포만감도 있네요. 가성비 좋게 포케 먹고 와서 기분 좋아요🎈', 11, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '훈제오리, 부추 세트와 라자냐 먹었어요. 플레이팅도 깔끔하게 나오고 훈제와 부추 조함 미쳤어요!! 칼로리도 적고, 브런치로 먹기 괜찮네요 :D', 46, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '너무 헤비하지 않으면서 적당한 포만감을 줘서 다이어트 할때면 오는곳입니당. 사장님 항상 신선한 재료 사용해서 믿을 수 있습니당', 37, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '후무스가 먹고 싶어서 방문했는데 매우 만족스러운 식사였어요! 포케 구성도 알차고 현미밥도 고소하니 정말 맛있었어요~ 인테리어도 이뻐요! 힐링 뿜뿜!!', 129, 26, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '재료들 다 신선하고 같이 주시는 드레싱 뿌려서 먹자마자 입맛 확 돌아요 포케 보통 다이어트 때 맛 영양 다 잡으려고 먹는데 맛있어서 많이 먹고 싶으니까 코끼리 될 판이네요ㅎㅎㅎ사이드 메뉴도 뭐 하나 빠짐없이 다 맛있어요! 특히 여성분들 완전 추천 과하지 않으면서 딱 진짜 맛있습니다!! 사장님들 외모만큼 완성도 높은 음식이었습니다:)', 112, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '혼밥하러 왔는데 분위기도 좋고 인테리어도 예쁘구 무엇보다 음식이 너무 맛있어요 !! 꼭 재방문 예정! 주문 잘못해서 사장님한테 요청드렸는데 엄청 친절하게 응대해 주셨어요ㅎㅎㅎ 진짜 친절하세요 번창하시길👍👍', 58, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '맛있고 건강한 한끼 식사 포케가 먹고 싶어 방문했는데 다양한 메뉴에 구성이 너무 좋더라구요! 세트 메뉴료 푸짐하고 맛있게 잘 먹었습니다 매장 분위기도 깔끔하고 편안한분위기라 너무 좋았어요!', 123, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '이렇게 한끼 하기 좋은 곳이 있다니 좋네요! 샌드위치 안에 재료가 듬뿍 들어있어 포만감도 있구요! 엄청 신선해요 맛도 좋아요!^^', 129, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '스리라차소스도 있어서 다이어트할때 가기 좋을 것 같아요! 새로생겨서 그런지 인테리어도 너무 분위기가 좋고 친구들이랑 약속장소로도 딱인 것 같아요! 그리고 후무스랑 두유크림치즈 너무 마시써요ㅠ', 124, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '다이어터 혼밥하러 갔는데 너무 깔끔한 매장에 바로 음식 조리해주시고! 재료도 신선해요!!! 넘 맛있어요!! 추천합니다 💪🏻👍🔥', 18, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '올때마다 재료도 신선하고 맛있어요! 인테리어도 넘나 깔끔하고 사장님도 친절하십니다 ㅎㅎ 우삼겹 포케랑 요번에는 못먹었지만 두유크림치즈 샌드위치 강.추.합니다', 62, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '재료가 너무 신선하고, 맛있어요😊 평소 샐러드 많이 먹는데, 여기 정말 맛있는것 같아요 인테리어도 너무 예쁘고, 직원분도 정말 친절하세요. 다음에 또 방문 하고 싶습니다:)', 6, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '너어어어엉어어얼엉무 맛있게 잘 먹었어요!! 매장도 넘 예쁘고 분위기 굿 포케 넘 맛나여;; ㅠ 라자냐도 어느 전문점보다 맛있음,,, 저렴한 가격에 맛있는거 맛보게해주셔서 감사합니다 간만에 건강하게 식사했어요 >_< 홍대 포케맛집 샐러드맛집', 37, 4, 'GOOD', SYSTIMESTAMP);
