INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '이렇게 맛있는 샐러드집을 알게 되어서 기뻐요! 특히 파스타 샐러드 넘 맛있고 사이드 레몬크림치킨이 제 원픽! 친구 데리고 샐러드집 가기 미안했는데 매장 분위기가 좋아서 ,, 나중에 남친도 데리고 가려구요 ㅋㅋㅋ', 5, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '작년 여름 광화문점 가보고 연남에도 지점이 있는 줄 최근에 우연히 알아서 다녀왔습니다! 육회 너무 맛있고 양도 많고 가격도 맛과 양 대비 매우 합리적이에요! 매장인테레어도 너무 예쁩니다', 3, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '아직 안먹어봤는데 벌써 맛있어요 👉🏻👈🏻 매장이 시원해서 천국같아요 체고 음식이 착하고 선생님이 맛있어요 !!! 담에 또올게요🩵❤️🩵❤️', 25, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '직원분들 너무 친절한데 왜케 잘생겼죠❤️ 눈도 훈훈하고 입도 즐거운 곳이네용~~ 재료도 신선하고 후무스 너무 맛나고 식단중인데 분위기도 너무 좋고 자주올거 같아요!!', 46, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '양이 생각했던 것보다 훠월씬 많고 건강한재료 아낌업ㄹ이 듬뿍 넣어주셨어요! 혼밥하기도 좋고 다이어트 건강식으로 부담 없이 먹응 수 있어좋아요🤍🤍', 119, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '연암동 분위기랑 어울리게 가게를 잘해놓으셔가지고 분위기도 좋게 맛도 맛있게 기분 좋게 좋게 잘 먹고 갑니다 감사합니다🙇🏻‍♂️', 45, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '매장이 일단 넓어서 너무 좋구요! 건강한 재료들이 듬뿍 들어가 있고, 베이스 & 소스 선택이 다양해서 다음에 또 오고 싶습니다!', 6, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '엄마랑 연남동 데이트 하는데 가볍게 먹을 브런치를 찾다가 들렸습니다. 포케와 샐러드 재료가 너무 신선하고 맛있었구요 무엇보다 엄마가 너무 맛있다고 좋아하셨어요🥹 두유크림치즈 꿀바게트를 사이드로 시켰는데 엄마는 이 크림치즈가 맛있다며 다른것도 계속 찍어 드셨습니다. 인테리어도 너무 깔끔하고 예뻐서 사진찍기 좋았어요❤️', 473, 39, 'GOOD', SYSTIMESTAMP);
