INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '샐러드 양이 많고 재료도 신선해서 다이어트중에 한끼 건강하고 든든하게 먹었어요! 직원분들도 친절해서 재방문 할 예정입니다 :-)', 40, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '평소 샐러드 좋아하는데 언더랩 샐러드 먹어보고 완전 반했어요 들어간 구성들의 조화가 너무 좋고 자극적이지 않아 더더 좋았어요 혹시 좀 부족할까 사이드로 라자냐랑 키쉬도 주문했는데 맛있었음!! 요즘 식단조절 중이라 자극적인거 피하고 1일 1샐러드 꼭 먹는데 언더랩 완전 만족이요💕💕', 5, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '셀러드 먹고 싶어서 연남동 맛집 검색해서 다녀옴. 역시나 사람들 바글 바글...다행이 사장님 너무 친절하시고 음식도 빨리 나와서 포장해서 왔는데 괜히 맛집이 아님. 맛도 좋고 양도 많아서 만족!! 자주 먹을듯', 8, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '오 정말 일단 매장 분위기가 예뻐서 완전 마음에 들었어요!! ㅎㅎ 건강한 식단으로 기분좋게 먹어서 좋습니다 :) 친절하게 설명도 해주셔서 사이드도 시켜봤어요 ㅎㅎ 또 오겠습니다앙 ☀️😊🐥', 42, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '각 재료의 조화가 너무 좋아서 너무 건강하고 맛있게 즐기고 왔답니다. 전 다음에 와도 또 이 메뉴를 시킬 겁니다. 구운버섯이 너무 맛있었답니다. 무엇보다 가격이 착하게 구성되어 있고 연남동샐러드 구성도 되게 좋고 연남동포케 로도 재료 구성이 너무 좋아서 여기 곧 핫플레이스로 될 것 같은 느낌이 팍팍 들었습니다. 재방문 의사 100%인 곳이에요. 또 오고 싶습니다! #연남동맛집 #홍대맛집 #연남맛집 #다이어트맛집 #샐러드맛집 #언더랩연남본점 #다이어트푸드 #연남동건강식 #연남동포케 #라자냐 #연남동맛집언더랩 #홍대맛집언더랩 #다이어트데이트코스 #데이트추천 #데이트장소 #데이트코스', 3, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '우연히 와봤는데 넘 맛있어요!! 재료도 풍성하고 특히 사이드메뉴가 많아서 먹는 재미가 있어요🥹 벌써 이틀째 연속으로 오는 중입니다! 자주 올게요~!~!!', 16, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '매장 넘 예쁘구 포케 샐러드 사이드까지 너무 맛있어요! 육회 포케 특이해서 주문했고 연어 추가해서 먹었는데 진짜 최고에요! 점심에 친구들이랑 먹기 딱 좋아요! 광화문 쪽에서 처음 먹어보고 넘 맛있어서 연남점도 생겼다길래 찾아온건데 진짜 언더랩 팬됐어요! 광화문점이랑 메뉴가 쪼끔 다른데 하나하나 이렇게 맛있을 수가 없어요!', 104, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '언더랩 안오는 거 어떻게 하는건데요 🥹 제발 진짜 저 레몬크림치킨 다들 꼭 드셔주세요,, 매일 생각나요 진짜로 번창하세요 사장님 꼭..💜 평생 먹을라니까ㅜㅜ', 50, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '전부터 와보고 싶었던 곳이었는데 기대했던 것보다 매장도 더 넓고 쾌적해서 좋았어요! 메뉴 양도 많고 가성비 있어서 추천합니다🤭 메뉴 나오자마자 향도 너무 좋고 맛있어요 ㅠㅠ 파스타 메뉴들도 있어서 다이어터 아닌 친구 데려와도 될 것 같아요~! 앞으로 홍대 올 때 식사 약속은 여기로 잡아야겠어요!', 28, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '근처 샐러드 가게 중에서는 가장 맛있는 것 같아요. 재료도 신선하고 샐러드가 아삭아삭해서 씹는 맛이 있어요. 다음에도 올 생각 있어요.', 0, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '연남동 샐러드 하면 생각나는 이 곳! 채소가 싱선하고 종류도 많아서 푸짐하게 먹을 수 있어서 좋습니다. 매장도 깨끗하고 사장님들도 친절하셔서 연남동에서 샐러드는 항상 이곳으로 먹으러 와요. 연남동 샐러드 맛집으로 추천해요~', 38, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '홍대에서 샐러드 맛집 찾는 중에 음식이 맛있고 신선하다는 후기가 많아 오게 되었어요! 재료가 신선하고 가성비가 좋아요! 예쁘게 그릇에 담아주시는데 사진에 다 담기지 못해 아쉽네요 인테리어도 깔끔하고 산뜻한 분위기로 사장님께서 인테리어 신경 많이 쓰신것 같아요! 친한 언니와 맛있게 저녁시간 보내고 갑니다👍👍', 12, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '양이 생각보다 많고 채소가 싱싱하고 많아서 더 좋았어요! 현미밥이 부족할까봐 추가했는데 다른곳 현미밥보다 양이 많아서 완전 든든해요ㅎㅎ매장도 크도 좌석도 많아서 쾌적하고 혼밥하기에도 좋을거같아요!', 78, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '레몬크림치킨 완전 겉바속촉 감동의 맛이네요ㅜㅜ 다어어트 메뉴 찾아왔는데 건강하면서도 맛있어요 라자냐도 신선하면서도 재료가 가득 들어 좋아요!! 홍대오면 자주 방문할게요~~^^', 26, 7, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '홍대 샐러드 맛집 찾다가 방문했어요! 엄마 모시고 왔는데 재료도 신선하고 맛있게 먹고왔습니다👍🏻😙 언더랩샐러드, 비프파스타샐러드 추천입니다!! 사이드 메뉴 두유크림치즈 바게트도 맛있었어요🤍', 9, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '연남 포케 샐로드 집들 중 맛 너무 맛있어오!! 가게 분위기도 너무취향저격이고 사이드 라자냐 너무 맛있어오!!!! 음악도 좋고 레몬에이드도 맛있어요! 다음에도 연남에서 샐러드랑 포케 먹을때 방문할거같아요!', 12, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '#브런치맛집 #샐러드맛집 친구랑 방문했는데 평일 13시 대기없이 바로 들어왔고 매장 쾌적하고 좋아요!! 육회포케 신선하고 건강한 맛이고 꿀바게트&두유크림치즈는 애기들도 좋아할 달달한 맛이었어요!!!', 19, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '연남동에 포케, 샐러드 전문점이 있다고 해서 다녀왔어요 생긴지 얼마 안되서 그런지 리뷰가 없어서 걱정했는데 와 진짜 맛있어요ㅠㅠ 건강한 음식이 이렇게 맛있을 줄이야 매장도 넓고 쾌적하고 좌석도 편해서 저 또 갈거에요 라자냐 맛있으니까 꼭 드셔보세요!', 8, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '포케를 처음 먹어봐 기대하면서 먹었는데 너무 맛있습니다!! 양도 적당하구 다이어트 음식으로 너무 좋구 인테리어나 식탁등이 깔끔하고 예뻐요!', 24, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '매장도 너무 너무 예쁘고 자연광이 정말 최고였어요 사진도 너무 잘 나오고 감성있는 맛집이였어요 맛도 정말 맛있고 인스타 감성 있는 카페 같은 느낌인 샐러드 집이었어요 진짜 완전 맛있고 연어 포케 진짜 너무너무 맛있었어요 최고!!! 강추💓', 21, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '맛있어염! 양이 그렇게 많지는 않아서 저는 너무 좋았어요 라자냐를 먹을 수 있거든요 ^^ 다음에는 두유 크림치즈도 먹어볼게요!', 76, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '연남동 골목에 위치한 분위기 좋은 샐러드 가게. 몸에 좋은 걸 가볍게 먹고 싶을 때 딱이에요. 메뉴도 다양하고 매장 분위기와 배경음악까지 잔잔하니 좋았습니다. 혼밥하기도 좋고 아기자기한 소품들에 눈과 입 모두 행복한 식사였어요!💚💚', 9, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '샐러드 먹고 싶어서 언더랩 방문했어요 세트로 시키면 델리메뉴와 미니샐러드도 같이 먹을 수 있어서 좋고 맛있어요~ 분위기도 너무 좋았어요🫶🏻', 25, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '친구랑 오랜만에 만나서 정한 메뉴가 샐러드였는데 너무 만족스러웠어요 육회를 파는 포케 샐러드집이 흔하지않은데 존재자체로 완전 감사합니다 ㅠㅠ 인테리어도 아기자기하고 이쁘고 사장님들도 친절해서 너무 젛았어요 혼밥하는 사람들도 많아서 주변에 살면 건강식으로 너무 좋은것같아요 여기는 사이드도 다양해서 너무 좋았습니다 다음에도 또 올게용 ㅎㅎ😘', 84, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '연남에 포케집이 새로 생겨서 가봤어요! 매장도 깔끔하고 다른 포케집에는 없는 메뉴도 있어서 좋았습니다. 맛도 맛있었어요! 새로운 매뉴 찾는 분들께 추천해요', 47, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '훈제연어포케 우삼겹메밀면샐러드 두유크림치즈&꿀바게트 언더랩이라는 포케가게는 처음 봤는데 전체적으로 너무 맛있었어요 훈제연어포케는 연어도 신선하고 과카몰리도 적당히 셔서 맛있었네요 비린내도 안 나고 굿! 우삼겹메밀면샐러드는 우삼겹이 많이 들어가서 마은에 들었어요 우삼겹혜자... 고기 좋아하는데 마음에 듭니다 두유크림치즈는 되게 고소하고 연세크림빵 같은 그런 부드러운 크림이고요 바게트랑 조합도 좋고 너무 맛있어요', 49, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '매장이 너무 매력적이에요. 햇빛이 들어와 따뜻하고 기분 좋아지는 분위기 입니다. 전체적으로 깔끔하고 스리라차랑 후추 마음대로 뿌릴 수 있어서 좋아요 메뉴들도 너무 맛있고 주변 상권에 비해 저렴해서 좋아요!', 1, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '너무 맛있어요! 사이드가 많아서 고르는 재미도 있고 토핑추가도 여러가지 되서 고민없이 메인 고를 수 있었어요! 사장님도 너무너무 친절하시구요! 재방문의사 100%입니당!', 34, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '사장님이 너무 친절하시고, 너무 신선한 음식들이 맛있어요! 데이트로도 혼밥으로도 너무 좋을 것 같아요!! 인테리어도 정말 멋져요!🩷', 31, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '맛있게 잘 먹었어요! 가성비도 좋고 맛도 훌륭하고 mac ayres 전곡을 재생하는 사장님 감각최고 연남동 포케는 여기로 정착하겠습니다 충성!!', 44, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '후무스 처음 먹어보는데 너무 고소하고 맛있어요 !! 정확한 칼로리나 영양성분이 안 나와있어 아쉽지만 건강하고 엄청 든든한 한 끼였습니당', 63, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '전부터 와보고 싶었던 언더랩 🥹 우삼겹메밀면샐러드 시켰는데 맛도 너무 좋고 매장 내 분위기가 차분해서 더 좋았던 것 같아요 :) 통창이라 해가 잘 들어와서 오후 고즈넉한 분위기가 최고였어요! 다음엔 포케 먹어보려구요 배가 많이 안 고파서 사이드는 패스했는데 다음에 와서 꼭 먹어보고 싶은 사이드가 한가득 😭 전 메뉴 섭렵할 때까지 재방문 의사 있습니다 🥹', 25, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '다이어트 하는 친구 따라서 온 샐러드집 샐러드로 배부를수도 있군 그래도 샐러드만 먹기엔 좀 심심한데 미니 라자냐가 참 적덩한 양이고 맛났다', 31, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '우연히 지나가다가 인테리어가 예뻐서 방문한 가게입니당! 샐러드 가게같지 않은 우드틱한 분위기가 넘 좋았어용! 분위기 맛집답게 샐러드도 맛있었습니다!! 무엇보다 양이 진짜 많아용ㅋㅋㅋㅋ샐러드 먹고 배 뽈록 나온 적 처음입니당~~ 당근모양 당근라페도 넘 맛있었어요!! 담에 또 방문할게요🫶', 20, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '샐러드집 찾다가 가성비있고 재료도 좋아서 방문하게 됬어요! 분위기도 좋고 친구들이랑 수다떨기도 좋았습니다 :) 다음에도 방문할것 같아요!', 16, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '저번에 훈제오리 먹고 오늘 아보카도 땡겨거 아보카도 닭가슴살 샐러드 시켰어요 ㅜㅜ 아보카도 후숙 너무 잘 돼서 맛있었습니다 전메뉴 다 먹어보는 그날까지... 잘부탁드려요 🥹', 73, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '저번에 처음 방문하구 좋앗던 기억이 있어서 오늘도 방문✨ 후무스 저번에 넘 잘 먹어서 오늘은 추가해서 먹엇는데 세상에나..! 🤍 사장님!! 이런 플러팅.. 전 빠져듭니다..💜 언더랩은 포케나 샐러드 외에 사이드 세트로 해서 음료랑 먹을 수 있는 조합이 있는게 가장 큰 장점인거같아요!! 아메리카노는 산미가 있는 편! 원두 먼가 예가체프 종류 쓰시는 거 같아요 (탐정인척~) 암툰 아침 이른 시간에 운영하구 공간도 노래도 좋아서 포장도 좋지만 먹구 가는거 추천임당😌 3월까지 네이버 리뷰 이벤트도 하구 잇는데 전 참고로 리뷰이벤 안하구 대가없이 쓰는 찐 리뷰..! 또 방문할게용 >_< ✨ +) 저녁에 또 방문햇지요💚 아보카도닭가슴살샐러드도 든든그자체 덕분에 건강하게 잘 먹구 갑니당💪🏻', 28, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '포케 가 거기서 거기 아니야? 생각했던 저, 언더랩을 만난 이후 무릎을 탁치고 생각을 바꿨잖아요. 확실히, 여태 먹었던 프랜차이즈 포케랑은 확실히 다릅니다!! 가격대비 구성도 알차고, 재료 조합도 미쳤는데 신선하기까지 하다니. 포케계의 혁명입니다 담엔 배민주문할래요', 11, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '더운 여름날 남자친구와 신선하고 맛있는 포케 잘먹었어요~~사이드들도 맛있구요 다음에 꼭 다시오고 싶은 집!!! 연남오면 무조건 여기 들릴 것 같아요~~', 49, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '샐러드 포케 집 찾아 다니는 거 좋아하는데, 그 중 가장 좋아하는 맛집이에요!! 가성비도 좋고 양도 많고 무엇보다 죤맛 ..🌿🤍', 13, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '다이어트 기간에 다양한 메뉴를 맛볼 수 있어 좋았습니다. 샐러드와 포케도 있지만 사이드로 라자냐, 꿀치즈 바게트도 좋고 메밀면도 메인에 추가할수있어 든든합니다.', 50, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '더운 여름날 여자친구와 신선하고 맛있는 포케 잘먹었어요~~사이드들도 맛있구요 다음에 꼭 다시오고 싶은 집!!! 연남오면 무조건 여기 들릴 것 같아요~~', 66, 11, 'GOOD', SYSTIMESTAMP);
