INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '샐러드 포장해와서 집에서 먹었는데 시간이 꽤 지났는데도 불구하고 채소와 토핑들이 여전히 신선해서 정말 맛있었어요! 특히 우삼겹메밀면샐러드에 우메드레싱 강력 추천 드립니다~~너무 맛있었어요 ㅎㅎ', 67, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '전에 친구랑 왔을 때의 기억이 좋아서 혼자 또 와봤어요 제가 아는 샐러드집 중에 구성이 가장 알차고 맛난 것 같아요… 매장도 깔끔한 듯 감각적이라 배경음악에도 잘 어울리고 바람도 잘 들어와서 기분 좋게 식사하기 좋아요! #브런치맛집 #샐러드맛집', 23, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '연남동와서 첨와보눈데 인테리어도 그렇고 매장도 깔끔하고 좋아요 ㅎㅎ 다이어트하려고 샐러드선택한건데 정말 다이어트와 상관없이 정말맛있습니다 강추강추', 128, 19, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '매장이 깔끔하고, 무엇보다 샐러드가 너무 맛있었어요. 여름철 더운 날씨에 입맛 없을 때 완벽한 선택💚 연남동 오시면 꼭 언더랩!! ><', 79, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '#브런치맛집 #샐러드맛집 #포케맛집 매장이 분위기도 너무 좋고 위치도 너무 좋고 청결하고 맛도 좋고🥹 완전 최애 샐러드집 될 것 같아오💗🩷 번창기원합미다❤️', 70, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '운동후에 포케먹고싶어서 급찾아서 왔는데 너무너무젛아요!!!! 홍대오면 언더랩 꼭꼭 오세요💗💗🫶🫶 그릇도 예쁘게 플레이팅해주시네여~~~~ 맛나요오!!! 양도짱많아요!!!', 104, 20, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '포케는 양도 많고 맛있어요 내부 분위기도 좋아요 생긴지 얼마 안된 곳이라 너무 깨끗해요 4인 테이블도 있어서 여럿이 오기 좋을 것 같아요 사장님도 친절하세요!', 29, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '점심에 광화문점은 자주 갔었는데 연남동에도 생겨서 와봤어요! 넘 예쁘고 분위기 좋아요 ㅠㅠ 사이드메뉴도 광화문보다 많아서 좋네용 *_*', 98, 26, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '진짜 .. 광화문까지 갔었는데 이젠 집앞에도 생겨서 너무 좋아요 ㅜㅜ 진짜 너무 맛있어서 화나요 ㅋㅋㅋ 음식이 맛있고 사장님도 맛있어요 ㅋ 아니 사장님 얼굴이 아니 후 ㅎㅎ 암튼 여러모로 맛집이에용 저만 알고싶지만 .. 장사 잘돼서 사장님 행복했으면 좋겠어요 ㅋ 🚰·̫🚰 존맛탠 ㅋ', 54, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '맨날 스리라차 마요 소스만 먹다가 언더랩 포케 소스를 먹었는데 오히려 소스가 가볍고 깔끔한 맛이어서 더 맛있었어요 !! 인테리어도 좋고 다음에 포케 또 먹고 싶을 때 여기 또 오고 싶어요 !!', 30, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '음식도 너무 맛있고 직원분이 너무 친절하세요:) 인테리어도 예쁘고 음악도 다 너무너무 좋아서 데이트하기에도 좋을 것 같아요!! 오늘 첫방문인데 다음에 또 오겠습니다💗', 21, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '기대하지 않았는데 너무 맛있어서 먹고 나서 선물하려고 시금치포테이토키쉬 두개 포장해 왔어요~~ 사이드 메뉴가 부담스럽지 않은 가격이고 샐러드나 포케에 사이드메뉴 하나만 추가하면 아메리카노나 와인 한 잔이 세트메뉴로 나와요^^', 7, 1, 'GOOD', SYSTIMESTAMP);
