INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '다이어트 하는 사람, 안하는 사람 같이 가기 좋음. 라자냐 사이드 메뉴인데도 불구하고 맛있음. 레몬크림 치킨  소스가 너무 맛있음', 48, 3, 'GOOD', SYSTIMESTAMP);
