INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '광화문점에서도 너무맛있게먹엇눈데 연남점도 오픈해서 너무좋아요!!!샐러드를 원래안좋아하는데 언더랩을 알고난후로는 샐러드도 좋아하게됬어용!다양한 메뉴가있어서 안질리궁 포케도 넘넘 마싯구 사이드디쉬들도 다 너무맛있습니다앙🥰연남점은 광화문과는다르게 인테리어도 너무 에뻐서 데이트하러오기에도 좋을거같아용💗💗💗오래오래 팔아주세요옹🥹🫶🏻🫶🏻🫶🏻', 100, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '다음주 웨딩촬영이어서 샐러드집 찾아보다가 알게되었는데!! 인테리어도 너무 이쁘고 음식도 깔끔하고 양도 많고 맛있어요~! 앞으로도 자주 찾아올거 같아요☺️☺️', 70, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '너무너무 건강하게 맛있는 맛입니다! 한식처럼 든든하게 느껴지는 맛이라 좋은 것 같아요 ㅎㅎ 입맛없을땨 상큼하고 든든하게 먹기좋아용 왼전추천♥️', 113, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '연남에 볼 일 있어서 왔다가 포케가 먹고싶어서 왔는데 인테리어도 예쁘고 너무 맛있네요🤤 애매한 시간대에 와서 손님도 없고 혼밥하기 좋았어요~', 10, 10, 'GOOD', SYSTIMESTAMP);
