INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '연어포케, 육회포케 맛도리에요😋❤️매장 분위기도 좋구 레스토랑 같은느낌..?!!여유롭게 점심 먹고 왔습니다:) 라자냐도 추천드려요!!', 9, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '라자냐 너무 맛있고 오리고기도 큼지막해서 맛있게 잘먹었어요!! 재방문 의사100%입니다 ..🤍 다만 추가해서 먹은 아보카도 후숙이 조금 덜 된것같았어요! 그래도 맛있게 잘먹었습니다 ㅎㅎ', 25, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '평소에 포케 되게 좋아하는데 여기 포케 지인짜 맛있어요 !!!! 포케에 들어가는 재료도 많은데 구성하는 모든 재료가 조화로워요 .. 드레싱도 포케랑 너무 잘 어울려서 좋았어요 ! 시간이 없어서 포장 해왔는데 담엔 매장에서도 먹어보려구요 매장도 넓고 깔끔해용 ㅎㅎ 자주 갈만한 포케집을 찾아서 기쁩니당 ☺️', 8, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '다이어트중이라 일부러 찾아서 왔어요 매장이 깨끗하고 메뉴가 많아요 양도많고 신선하고 알차게 구성되어있네요 잘먹었어요~ 담에 또 방문할께요~', 20, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '처음 방문한 곳인데 너무 만족하고 갑니다! 포케도 정말 맛있고 무엇보다 채소들이 신선해서 좋았어요. 가격도 착해서 재방문 의사 있습니다🙂 창밖으로 보이는 뷰가 좋아서 눈도 즐거운 곳이라 추천합니다🍃', 45, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '광화문에서 맛있게 먹은 기억이 있어서 인스타 팔로우 하고 있었는데 연남동에 오픈한다는 소식에 시간 내서 바로 찾아갔습니다!! 구성도 너무 알찰뿐더러 가격이 너무 저렴해서 놀랐네요...😮 사장님한테 가격 올리셔야하는거 아니냐고 할정도로 참...😭 샐러드 및 사이드 맛이며 퀄리티며 구성이며 너무 좋았습니다👍🏻 평소에는 샐러드 찾아 먹는 편이 아닌데 언더랩은 찾아가고싶을정도의 맛집...!! 여기 가성비 미쳤으니 다들 돈쭐 내러 가주세요😡', 55, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '매장 공간이 너무 예쁘고 음악도 좋아요 메뉴도 다양하고 가성비도 좋은 것 같아요 ! 스리라차소스도 구비되어 있네용 다음에 또 와보고 싶어요', 27, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '건강식은 역시 언더랩샐💚 따똣한 아메리카노랑 먹으면 넘 마싯자나영 >_<  샐러드맛집 폼 미췃슴당 ✨ 애착 후무스는 물론이구 갓 구운 두부구이 짱짱 요청사항도 감사합니다 :)', 15, 6, 'GOOD', SYSTIMESTAMP);
