INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '광화문에서 유명한 언더랩이 연남에 생기면 당욘 가야죵💜 후무스 처돌이라 넘 조아요 꺄항~~ 버섯구이 못 먹어서 빼달라구 말씀드렷더니 두부를 더 채워주셧어요 ㅠㅡㅠ 세심함과 친절 맛까지 다 잡앗다니,, 넘 행복한 점심입니당✨', 32, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '저 진짜 다이어트 하면서 이렇게 맛있으면서 이쁜 샐러드집 처음 봤어요🥹💚 병아리콩이랑 올리브 못먹는 저한테 구성도 너무 좋고 레몬크림치킨은 미쳤어요 앞으로 제 단골집 ㅜㅜ🩷', 66, 11, 'GOOD', SYSTIMESTAMP);
