INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '#브런치맛집 #샐러드맛집 신선하고 좋은 재료가 알차게 들어있어서 너무 맛있게 잘 먹었습니다. 매장 분위기도 좋아서 친구랑 모임하기도 좋았어요😃', 74, 15, 'GOOD', SYSTIMESTAMP);
