INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '음식도 너무너무 맛있고 가게 분위기도 좋아요! 근데 버섯 어떻게.. 구우시는거에요..? 그냥 고기 같아오.. 너무 맛있어요..', 26, 9, 'GOOD', SYSTIMESTAMP);
