INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '연어포케와 브런치 세트 먹었습니다! 광화문점에서 종종 먹다가 연남동에 2호점이 생겼다하여 방문하였는데 너무너무 맛있게 먹었습니다! 다음에 또 올게용🙂👍🏼', 39, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '언제와서 먹어도 너무 맛있어요😭😭 집앞에도 생겨서 맨날먹구시푼맛...!!!💗 리뷰보고 육회포케에 연어추가했는데 너무맛잇더라구오ㅠㅠ 광화문에서 감자스푸 최애엿눈데 연남점은 사이드가많아서 다른거먹다가 올만에먹으니까 더더너무맛잇구 베스트메뉴 두유치즈도 꿀아예 전체적으로 뿌린다음에 푹 찍어먹으니까 더마싯도라구여🥰 사댱님 대박나세용 그래서 맨날 장사해주세요오🥹💓💓💓', 86, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '진짜 너무 잘 먹었습니다 사장님들 인품이 아주 멋스러웠어요 가게 분위기 편하고 이쁘네요 잘 해놓은 가게에서 좋은 음악과 맛있는 샐러드 잘 먹었어요 !! 사이드 두부 뭐시기 꼭 드세요 진짜 미쳤네요 맛있어요', 34, 0, 'GOOD', SYSTIMESTAMP);
