INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '점심 먹으러 왔어요. 날이 따뜻해져서 너무 무거운 음식은 안 먹고 싶더라고요. 채광도 좋고 매장도 귀여워요. 맛있어요. 다음에 방문해서 다른 메뉴들도 먹어보려고요🌿', 31, 1, 'GOOD', SYSTIMESTAMP);
