INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '식단도 하면서 맛도 있어서 맛도 챙기는 1석2조 음식이였고 무엇보다도 야채가 신선하고 시금치파스타 맛 너무 신선하고 좋네요 강추합니다 두유치즈랑 빵도 같이 먹는거 추천해요 건강식 좋습니다', 53, 17, 'GOOD', SYSTIMESTAMP);
