INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '포케 양이 많구 재료가 여러가지 많이 들어있어서 가성비가 좋아요!! 매장도 넓구 쾌적해요 분위기가 좋어서 연인이란 와도 좋을 것 같아용', 5, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '포케도 라자냐도 너무 맛있어요! 비프 파스타 샐러드도 강추입니당 ㅎㅎ 샐러드집에서 라자냐 크림치즈바게트 이런 다양한 사이드도 같이 파니까 넘 좋은 것 같아요ㅎㅎ', 14, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '새로오픈햇다해서 와이프랑 일부러 찾아감. 청년둘이 열심히 일하는모습 좋고 맛도 좋음. 양도 넉넉. 분위기도 깔끔. 재방문 의사 잇음. 실내온도도 틈틈히 체크하고 온풍기 껏다 틀엇다 센스잇음. 밖에 담배냄새 창문 열어서 다 들어오는게 문제. 재떨이 잇는 흡연구역이라 어쩔수 없는게 아쉽. 바람 솔솔 들어오는게 너무 좋앗는데.. 여튼 화이팅!', 50, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '포케만 먹다가 오늘은 메밀면샐러드로 먹어봤는데 양도 많아서 든든하고 너무 맛있어요!!!!재료들도 늘 너어무 신선해요! 이 가격에 이 퀄리티는 언더랩밖에 웁서요😣 감자스프도 숨은 맛도리 ! 꼭 드셔보시길…🩵🩵', 26, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '광화문 1호점때부터 애용하던 곳인데 연남점 오픈 소식 듣고왔어요 여기 정말 다른 체인 샐러드집과 결이달라요 사이드도 대충 냉동 데우는게 아니라 하나하나 다 직접 만든 맛이 나는게 느껴집니다 포케랑 샐러드도 사장님 진심이 느껴져요 근데 너무 맛있어서 항상 많이먹는데 샐러드 먹는 의미가 사라질까 두려워요😭 무튼 존맛입니다 수구요', 49, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '정말 맛있게 먹었습니다!! 새로 신규 오픈했다고 들었는데 진짜 양도 많고 가격도 합리적인 거 같아요.. 라자냐가 5900원인데.. 진짜 맛있었고 들기름 메밀면 샐러드도 진짜 맛있었습니다!! 광화문에서 원래 있던 언더랩.. 홍대에서도 생겼다길래 갔는데.. 신메뉴인 꿀바게트 크림치즈.. 도 꼭 드세요... 존맛탱! 재방문의사 1000프로입니다!!', 117, 22, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '요즘 다이어트 한다고 식단하고 입맛 진짜 없었는데 샐러드라도 먹자 하고 방문 했어요.. 근데 샐러드가 이렇게 맛있는 음식이라는 걸 일깨워준 식당입니다 ㅜㅜ 샐러드는 최고에요 다이어트하다가 버티기 힘들때마다 방문하려고 해요 너무 맛있어서 다이어트 끝나도 먹으러 다닐듯!! ㅜㅜ 사장님도 친절하시고 음식도 맛있어서 정말 기분 좋은 시간이였습니다🥰', 50, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '근처에 사는데 새로 생겨서 와 봤어요!! 매장 인테리어도 너무 예쁘고 분위기도 좋아서 다음에 또 올 것 같아유 ㅎㅎ 분위기 맛집 브런치 맛집 연남동 맛집입니당..❤️✨', 0, 4, 'GOOD', SYSTIMESTAMP);
