INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '프레쉬한 음식 먹고 싶어서 찾다가 왔는데 너무 맛있어요👍 배도 든든한데 맛이 아주 좋아요!!!특히 저 두유크림치즈 진짜 맛있어요~~~~!! 포케 먹으면서 꼭 드셔보세요 강추', 104, 20, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '친구들 모임에 속을 좀 편히  먹을수 있는 음식을 찾다가 딸내미들한테 맛집 추천 요청!! 언더랩^^   강추!! 언더랩  연남점 새로 오픈 했다고 해서 방문~~^^ 솔직히 추천을 해달라구 했지만, 샐러드,포케??^^;; 6명이  각각 다른음식으로 주문하면  솔직히 미안한 마음도 있지만 , 줌마들은  다 먹고싶다는 강한 의지로 주문~~~ 언더랩에 사장님과 직원인듯 한 젊은 청년들은  환한 얼굴로 음식 하나하나 설명하면서  주문을 직접해주시는 센스!!!^^  감사 음식을 보고 먹고 깜놀!! 너무 맛있고 신선하고 푸짐함 감동~~~가성비 갑👍 참고로  아보카도 연어샐러드 인가??진짜 맛있었어요 조용히😊 수다떨다가 커피도 두잔씩 먹고~~ 건강해지는 느낌   만땅   한손가득  테이크아웃도 하고 ~', 109, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'MEETING');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '혼자 방문~ 프레쉬하고 맛깔난 음식, 친절한 스태프, 분위기 작은 골목 끝에 있는 것도 굿. 백퍼 재방문할 거임. 사진을 미리 찍지 않아서 못올림이 아쉬움', 117, 19, 'GOOD', SYSTIMESTAMP);
