INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '새로생긴 샐러드&포케집이 있다고해서 운동끝나고 들렸는데 매장도 깔끔하고 음식도 맛있고 무엇보다 사장님이 친절해서 기분좋게 먹고갑니다!! 다음에 또 오겠습니다 :)', 43, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언더랩 연남점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '여자친구와 데이트 중 포케가 먹고싶다해 언더랩을 다녀왔습니다 여자친구도 만족하고 맛도 꽤 맛있어 참 만족도가 높네요 다음에 또 와서 머글라고요', 23, 9, 'GOOD', SYSTIMESTAMP);
