INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '짱맛 샌드위치집 알게 되서 기뻐요🥹 🏡 공간 -경희선숲길 골목에 위치. 전체적으로 우디우디하고 가게가 크지 않은편이에요. 평일 점심 지나서 방문했는데도 만석이었으니 참고. 🍽️ 맛 - 크리미에그번, 그릴드페스토 주문🥪,카페라떼,아메리카노 주문. 크리미에그번! 진짜 퐁신퐁신 크리미이이~ 해요! 번도 정말 퐁신하고 오믈렛,치즈,스리라차 조합이 진심 맛있네요🥹계란이 일본식처럼 달짝지근하고 보들보들 퐁신퐁신🧡적당한 단짠의 밸런스가 정말 굿이에요ㅠ 그릴드 페스토도 바질,올리브,드라이토마토,치즈 조합이 정말 맛있고 빵도 겉은 바작하고 속은 촉촉하게 잘 구워짐! 라떼도 진하고 맛있어요. 메뉴 전부 만족스러워서 조만간 다른 메뉴 먹으러 또 갈꺼에요🥹 🤵🏻‍♀️서비스 -직원분들도 친절하세요. (지극히 개인적인 후기입니다)', 126, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
