INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '애인과 방문했습니다. 인스타그램에서 보고 방문했어요. 소소하게 웨이팅이 조금 있고, 가게가 그리 넓진 않아서 주문란 브런치 먹고, 얘기 좀 하다 나가는 느낌입니다. 빵 냄새 좋고, 전체적으로 맛있어요. ''크리미 에그번''이 누가봐도 시그니처라서 먹었는데, 젤 만족스러웠습니다. 계란 초밥의 계란 정도의 달기와 퐁실퐁실하게 풀린 게 굿이고, 칠리소스 살짝에 짧짤한 치즈가 조화가 좋네요. 빵이 적당히 버터버터한 느낌이라, 고소함도 좋고. 전체적으로 밸런스가 젤 좋았습니다. 레드빈 토스트는 무난한 앙버터 토스트 느낌? 아주 좋네용. 추천합니다~', 2, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '오랫동안 위시리스트에 있었던 샌드위치 가게인데 드디어 방문하게 되네요.웨이팅이 있었지만 운좋게 빨리 앉을 수 있었어요.샌드위치 전문점이라 혼밥도 괜찮은 곳이고 두명이상 방문은 한가한 시간을 노리시는게 좋을 것 같아요.이 집의 시그니처 메뉴 크리미에그번 주문했는데 진짜 이마를 탁 치게 만드는 어마어마한 맛.인생 샌드위치로 등극했습니다. LA 에그슬럿에서도 느끼지 못한 정말 감탄이 나오는 맛인데 혼자 간거라 속으로 내적 감탄만 외치며 순삭 했습니다.샤이하면서 친절하신 사장님?이 계속 만드시던데 이 분 생활의 달인에 출연 시켜야해요.어떻게 이런 에그번을 만드시는지 진짜 금손이세요.레드소스가 킥인거 같은데 없어도 충분히 감탄을 자아내는 맛입니다.무조건 재방문 각이고 샌드위치 도장깨기 할꺼에요.퐁실 에그번 최고!', 0, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '약 1년만에 방문해서 혼자 샌드위치 두개 먹고 왔습니다ㅎㅎ 여전히 맛있고 여전히 인기가 많네요! 크리미 에그번이랑 플레인 토스트 둘다 짱맛있었어요! 조금만 더 늦었으면 웨이팅 할 뻔 했습니당', 33, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '어쨌거나 저쨌거나 크리미 에그 번은 빵과 계란말이와 소스의 조합이 넘사벽. 전에 있던 여러 제빵류들은 거의 다 없어지고 주로 샌듸츼류만으로 메뉴 구성이 됨. 바 테이블도 있어 1인 착석도 용이. 커피는 싱겁고 밍밍한 편.', 113, 26, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '친구랑 함께 방문했어요! 저번에 포장으로 에그번 먹었었는데 이번에는 매장에서 먹었습니다. 에그번은 첫입은 맛있는데 치즈가 들어있어서 느끼한걸 잘 못먹는 저에게는 피클이 필요한 맛이었어요. 치즈같이 느끼한 맛 좋아하시는 분들은 좋아하실 것 같아요. 메쉬드 포테이토는 야채도 신선하고 바게트가 아주 바삭했어요. 구매하고 바로 먹는게 좋을 것 같습니다. 한 메뉴가 양이 얼마 안되어 보이는데 막상 먹으면 배불렀어요!', 8, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '에그번 먹고 신세계 경험해서 또 먹으러 왔어요~~ 여전히 맛나요🥹👍 점점 인기가 많아지는건지 지난번 방문 했을때보다 웨이팅 오래했는데 다 먹고 나오니 웨이팅이 더 늘어나있네요😂', 24, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '샌드위치 러버로서 또 하나의 샌드위치 맛집을 발굴해서 기쁩니다. 혼자 왔을 땐 모르타델라 포카치아를 드시고 둘이 왔을 땐 토마토칠리치킨까지 시키십셔. 대신 칠리치킨은 좀 많이 매워요 맵찔이들 조심 ~ 😉', 4, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '크리미 에그번-퐁신퐁신한 빵속에 두툼하고 부드러운 오믈렛과 치즈+칠리소스 조합! 분명 집에서 만들수 있을 것 같고 아는 맛인데 집에서 만들면 절대 만들어지지 않는 그런맛!! 너무너무 맛있고 폭신폭신해요ㅎㅎ 평일 11시 10분에 갔는데 거의 만석이였고 11시 30분 부터는 대기 생기기 시작했어요 오픈런 추천드립니다', 7, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '최근에 먹은 샌드위치 중에 가장 맛있었어요,, 애매한 시간에 갔는데도 15분정도 웨이팅 했습니다! 빵이 폭신한데 계란이 촉촉하고 안에 소스랑 넘 잘어울랴요.. 다시 생각하니 또 먹고싶은 맛이에요ㅠ!!! 포장해서라도 먹고싶은데 가게에서 먹는게 젤 맛있을것 같네요ㅎㅎ 다른 빵도 많았는데 다음엔 다른 빵 도전하러 가뷰겠습니다!!', 40, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '크리미에그번 레드빈토스트 먹고 맛있어서 샌드위치 추가 모르타델라포카치아 너무 맛있어요 내돈내산 리뷰 https://m.blog.naver.com/mar_quito/223890791678', 57, 16, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '커피까지 맛있을 줄 몰랐어요☕️🫶🏻 보통 샌드위치에 치중하면 커피맛이 별로인곳이 많은데 라떼가 너무 맛있네요 크리미에그번은 포장해서 먹었는데 왜 대표인지 알겠어요! 포카치아나 바게트에 햄치즈루꼴라 스타일을 좋아하는데 여기선 포카치아보다 에그번이 승👍🏻', 42, 0, 'GOOD', SYSTIMESTAMP);
