INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '모르타델라는 그냥그랬는데 에그번이 정말 맛있었어요! 다음에 방문하면 그릴드 샌드위치 먹어보려구요:) 라떼는 좀 밍밍한편이고 아메리카노는 산미가 살짝 있는 편이에요!', 86, 11, NULL, SYSTIMESTAMP);
