INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '샌드위치가 맛있습니다:) 계란도 퐁실퐁실하고 만드시는 과정도 다 보이고 깨끗한 것 같습니다! 빵 포장만 하시는 분들도 있으시던데 궁금해서 먹으러 가려구요! 매장이 큰 편은 아니지만 좌석이 꽤 있습니다!', 28, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '빵보다 안에들어간 오믈렛?달걀이 더 커서 깜짝놀랐어요 사랑니빼고 이아파서 딱딱한 빵류는 못먹어서 고른건데 진짜 퐁신퐁신하고 부드러워서 잘 먹었습니다. 커피는 제 취향이 아니여서 그냥 그랬는데 다음에 다른 메뉴도 먹어보고싶네요 (끝으로 갈 수록 살짝 물릴 수 있다는점 참고하세요)', 8, 3, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '지나가면서 매번 한번 가야지 하다가 첨 들어와본 가게! 빵이 진짜 제대로에요 고소하고 쫄깃하면서 담백한! 그릴치즈앤어니언+아아 조합 아주 맛있었어요 다른 브런치류도 맛있을 것 같은 예감이...! 하나씩 도장깨기하러 와야겠어요', 29, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '매장이 넓진 않음 그리고 평일인데도 점심시간쯤에는 사람이 많아서 자리가 없을수도 있음 커피가 굉장히 맛있음 크리미 에그번은 폭신하고 맛있는데 계란이 많이들어가는지 반 정도 먹었을 때 배불러 미치는 줄,, ㅎ 그리고 배부르니까 좀 속이 느글거리긴 했음 어쨌든 맛은 있어서 다른 메뉴도 궁금함', 61, 17, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '매장 분위기도 좋고 빵도 맛있고 커피까지 맛있어요. 크리미에그번 & 따뜻한 아메리카노 조합 강추! 솔트버터번, 시나몬번, 피스타치오번은 포장해서 먹어봤는데 각각 사서 다 맛봐야합니다.(중요) 다음번에 포카치아 맛보러 갈거에요...🏃‍♀️🏃🏃‍♂️ -지나가던 빵쟁이의 후기-', 73, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '샌드위치를 워낙 좋아해서 꼭 가야지••• 하며 찜 해놨던 어 슬라이스! 포카치아는 포장으로, 에그번은 매장에서 먹었어요. 에그번의 달달한 오믈렛과 퐁실퐁실 브리오슈번의 조합은 말모말모. 매장에서 따듯하게 먹어서 더 맛났어요. 포카치아는 기본에 충실한 맛이고 중간중간 들어가있는 토마토 마리네이드가 킥입니다! 빵 냄새를 맡으며 여유로운 주말을 느끼고싶다면 어 슬라이스로 당장 달려가세요..🥪🏃🏻‍♀️', 0, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '이날은 날씨가 쌀쌀했어서 따뜻한 라떼랑 아이스 바닐라라떼 먹었어용!! ㅎㅎ 카페 분위기는 따뜻하고 아늑한 느낌을 줘서 머무르는 시간동안 너무 편안하게 보냈습니다.. 배가불러서 디저트 종류는 주문못했는데 다음에 먹어볼려구요 ㅎㅎ', 39, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '그릴드 페스토, 아이스 카페라떼 맛있습니다. 명불허전! 다만 그릴드 페스토는 식빵이 2장이 아니라 3장이 들어가서 좀 부담스럽네요. 맛에는 아무 문제 없는데 탄수량이 걱정됩니다ㅜㅜ', 18, 5, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '일행이 추천해 줘서 가본곳인데,일단 제가 좋어하는 우드 인테리어가 너무 맘에 들었고 가게 내부 넓지 않았는데 좌석도 여러형태라 골라 앉을 수 있었어요, 아몬드 크림라떼는 고소하면서 맛있었고 아이스크림 번도 정말 맛있었습니다. 다음엔 다른것도 먹어 보고 싶네요, 잘 마셨습니다 :)', 36, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '아이들이랑 갔는데 너~~무 맛있고 푸짐하게 잘 먹고왔어요^^ 아이가 입맛에 딱 맞는 음식 먹을때만 웃긴표정 지으며 춤추는데 햄버거먹으면서 내내 엄지척하며 먹었네요^^ 다음엔 남편이랑도 같이 와야겠어요~~', 114, 20, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '가게 이전하고 처음 방문했는데 구석진 곳에 있는데도 사람이 바글바글했어용 ! 저 들어오고 몇분 지나니까 웨이팅도 생기더라구요 ! 그릴드 페스토와 바닐라 라떼 주문했는데, 따뜻하고 내용물도 아낌없이 들어가있고 커피도 너무 맛있었습니당 ! 앞으로 브런치 먹으러 자주 와야겠어용 홍홍 🤎🤎🤎 (근데 이제 오픈런해야겠네용,,,🥹🥹)', 7, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '샌드위치 하나하나 다 맛도리세요🫶🏻✨ 크리미 에그번, 그릴드 페스토 넘나 취향 저격이었고 매쉬드 포테이토는 생각보다 퍽퍽하고 찔겨서 조금 아쉬웠어요! 그래도 전반족으로 매우매우 맛있게 먹었습니다ㅎㅎ 또 와서 다른 메뉴들 털어볼래요,,', 5, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '진짜 빵 천재에요,, 모르타델라 포카치아 🥙 피스타치오 크림번 먹었는데 진짜 너무 너무 맛있어서 눈이 뛰용 했어요,, 🍃💛미쳤어요,, 다른 메뉴도 너무 궁금해서 또 가보려구요.. 전 피스타치오 번에 푹 빠져서 포장을 못해온게 한이 되었어요.. 그 맛을 잊을 수가 없어요 🥹', 2, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '며칠전에 포장으로 이용했었는데 너무 맛있게 먹었던지라 이틀만에 또 왔어요! 오늘은 그릴드치즈 어니언이랑 카페라떼 아이스 도전했는데 둘다 매우 만족스러운 맛이었어요!', 61, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '홍대와 신촌 골목 사이 어딘가에 조그맣게 위치해있던 작은 카페, 알고보니 나만 몰르고있었다.. 혼자 방문했는데 커피와 메뉴 두개를 주문했는데 구구절절 설명해봐야.. 백문이 불여일견 사장님 부부가 너무 친절하시고 메뉴와 커피 맛이 너무 좋았 어요 맛있게 먹고왔습니다 와이프랑 같이 먹으려고 번 3개와 신메뉴라고 말씀하신 샌드 위치까지 포장해왔는데 이것도 너무 맛있게 먹었네요 아직 방문 안해보셨으면 꼭 방문해보세요:)', 43, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '빵맛집이에요🥹❤️❤️❤️ ㅋㅋ너무맛있어서 먹다보면 또 추가해서 먹고 …. 그렇게되실거에욬ㅋㅋㅋㅋㅋㅋㅋㅋㅋ 신메뉴로 잠봉 나왔눈데 진짜 맛있답니당ㅇ 그리고 여기가면 크리미에그번은 꼭 꼭 드세요! 조만간 아이스크림번 먹으러 또갈거에요', 21, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '따끈 퐁신 달큰 촉촉 꾸덕 다하는 에그번.. 왜 여기 줄 안서요..? 왜 더 유명하지않은거지요..? 매장도 넘 따숩고 예쁜 분위기.. 기분좋은 주말아침같은 곳..', 107, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '맛있어요. 그런데 조리 시간이 걸려서 나오는데 20분 걸린것같았어요~ 시간 여유있을 때 가시면 좋을 것 같습니다!! 카페 분위기 너무 좋아요✨', 22, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '진짜.. 집이랑 가까워서 너무너무 행복한 어슬라이스.. 😭 빵이 진짜 맛있어요..!!!! 원래 크리미 에그번이 최애라 두개도 먹을 수 있는데, 신메뉴 잠봉도 대존맛이었어요.. 먹어본 잠봉 중에 최고 💘 잠봉 꼭 드세요 두번드세요', 72, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '이전한 매장은 처음 방문했어요 예전보다 빵 종류는 줄어들어서 아쉽지만 분위기는 더 좋아졌어요 샌드위치는 포장했는데 빵이 살짝 질긴 느낌이라 아쉬웠어요', 48, 9, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '마포구 주민 18년차 최소한 마포구에서 여기보다 맛있는 빵집 못 찾았습니다. 소금빵&감자빵 장인이었던 어슬이 한층 더 업그레이드돼서 돌아오신것을 격하게 환영합니다🤍🤍 자타공인 빵천재답게 샌드위치도 역시 남다르게 맛있어요. 재료가 얼마나 알차게 들어갔는지 낮에 먹어도 저녁까지 속이 든든하답니다. 처음 오신 분들은 기본 빵들과 브리오슈번 메뉴로 입덕하시는 것을 추천드려요🤗 요즘 물가 미쳐 날뛰는데도 여전히 착한 가격에 팔아주셔서 황송할 따름입니당. 라떼가 넘 맛있어서 순식간에 호로록해버리는 바람에 사진도 못 찍었는데 두번드시구요! 어슬 들러서 빵 사오면 좋은 기분까지 같이 구매하는 느낌이에요. 매장 이사하고 넓어져서 제가 다 뿌듯해요 흑흑 부디 돈쭐나시고 오래오래 빵순이들의 꿈과 희망이 되어주시길💌', 30, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '소문난 빵 맛집! 집에 여러개 포장해 와서 냉동시켜놨다가 에프에 돌려먹었는데 진짜 빵 너무 맛있어요!! 완전 겉바속쫀입니다..✨✨ 빵 좋아하시는 분들은 한 번 드셔보시면 여기 빵 계속 계속 생각나실꺼에요… 다음 번에 방문하면 더 많이 사와서 먹고 싶을 때마다 꺼내 먹어야겠어요🥹 조만간 남편이랑 매장 방문해서 샌드위치랑 다른 메뉴도 먹어볼 예정입니다. 빵 좋아하시는 분들은 무조건 한 번 방문해보세요!', 4, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '커피맛은 기대안하고 갔는데 커피 맛집이네요!! 샌드위치와 커피 맛있게 잘 먹었어요 그리고 피스타치오 번도 포장으로 먹었는데 역시 👍 가게 내부 분위기도 좋아서 여러모로 만족스런 시간을 보냈습니다.😍', 32, 0, 'GOOD', SYSTIMESTAMP);
