INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '어슬라이스 레몬 에이드랑 소금 버터번이랑 궁합이 너~무 좋아요💕 항상 에그번만 먹다가 오늘은 소금 버터번 먹었는데 바삭하고 고소한 버터향이 진짜 좋았어요👍🏻', 8, 10, 'GOOD', SYSTIMESTAMP);
