INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '기대안하고 혼자 갔는데 웨이팅도없이? 너무좋았어요!! 뷰도좋고. 혼자 생각할때 좋습니다. 저만알고싶은..친절해요. 빵도맛있고ㅎㅎ', 6, 10, 'GOOD', SYSTIMESTAMP);
