INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '정말 감작 놀라는 맛이에요 우와 샌드위치가 이렇게 맛있을 수가(?) 이렇게 자극적일 수가 있군! 다른 것도 다 맛있다고 하던데 저는 에그번이 제일 좋아요🐣 그거랑 머핀같이 생긴 것도 다 먹어봤는데 제 픽은 초코! 얘도 초반엔 맛이 좀 심심하더니 오늘 혹시나 시켜봤더니 아주 진한 쵸코 맛이 황홀합니다🍫 근데 사장님 제발 칼 좀 바꿔주세요ㅠㅠㅠ 너무 안 들어요ㅠㅠㅠ맨날 종이랑 같이 먹어요ㅠㅠ', 23, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '리뷰 안 남기는 빵순이인데 눈이 띠용해져서 남겨요. 아이스크림번 제대로 미친 맛.. 충격적으로 너무x10000 맛있어요. 스트레스 받은 날 무조건 어슬라이스로 달려가서 아이스크림번 시키세요!!! 모타델라 포카치아랑 그릴페스토도 말해 뭐해~~~~ 요즘 돈 아낀다고 카페랑 디저트 멀리하고 있는데 여긴 가격까지 착해서 정착하기로.♡ 친구의 적극 추천으로 왔는데 제대로 팩트체크하고 갑니다ㅎㅎㅎ', 46, 10, 'GOOD', SYSTIMESTAMP);
