INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '매장 이전하고 처음 방문했는데 기존보다 빵 종류는 적어졌지만 샌드위치 종류가 다양해져서 커피랑 먹고갈수 있어서 개인적으론 더 맘에들어요🫶', 49, 7, 'GOOD', SYSTIMESTAMP);
