INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '가게 이전후 첫 방문 매장이 더 넓어지고 깨끗해 보이고 사장님들이 알아봐주셔서 놀랐다..😅 메뉴 추천을 받아서 먹어 봤는데 최애 샌드위치가 바뀌어 버렸다.. 진짜 개맛있다......', 57, 11, 'GOOD', SYSTIMESTAMP);
