INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '저번에 머쉬룸 샌드위치를 먹어보구 너무 맛있어서 재방문.. 요번에는 사장님이 추천 해주신 포카치아를 포장해서 집와서 먹었는데 빵은 바삭쫄깃하고.. 그냥 너무 맛있다... 미쳤다', 21, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '우선 빵이 맛있고 샌드위치도 기가막힙니다. 무엇보다 재료가 가진 맛을 제대로 살려 심플하지만 풍미가 깊고 깔끔한 맛을 내서 너무 감탄했습니다. 인위적으로 멋 부려서 괜히 요리랍시고 지지고 볶아서 뭉개버리지 않고 빵의 고소한 맛, 페스토의 짭자름한 맛, 썬드라이드 토마토의 단맛 그대로 살려 치즈와 가볍게 구운 샌드위치는 진짜 ... 국내에서 먹은 샌드위치 중에 최고였습니다. 온기와 빵굽는 냄새가 가득한 아늑한 실내 공간이나 리쉬 티백을 사용하는 티 메뉴도 아주 훌륭합니다. 집근처라면 매일 아침을 맡기고 싶은 맛집!!', 49, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '오픈하고 30분뒤쯤 가니깐 벌써 꽉 차있더라구요! 쉐어테이블에 앉았어도 편했어요☺️ 피스타치오크림번🥜 먹었는데 너무 맛있어서 다음에는 브런치 종류로 먹어보려구요🩷', 22, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '소금빵이랑 감자빵 먹었어요!! 감자빵은 모르겠고 소금빵은 데워줘요 소금빵 맛집이라고 해서 갔는데 저는 소금빵보단 감자빵이 더 맛있었어요 감자맛 엄청 많이나요 진짜감자빵임 거기에 치즈가 살짝 맛을 더해줘서 더 맛있었네요 다음엔 치즈버거랑 감자빵 먹으러 가고 싶네요', 9, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '여기 빵 미쳤습니다 … 소금빵 덕후인데 소금빵 맛있는걸로 top5 안에 듭니다. 겉은 바삭하고, 속은 버터로 촉촉합니다. 버터 구멍 저렇게 큰거 처음봐요. 소금빵 아니여도 감자빵도 같이 먹었는데 엄청 맛있어요! 짭쪼름하고 부드럽고 맛있습니다 여기 빵 먹으러 또 가고싶네요', 39, 2, 'GOOD', SYSTIMESTAMP);
