INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '이사 온 게 집 앞이라 거의 매일 들러 포카치아 사먹고 있는데.. 전 분명히 빵 안좋아하는 사람인데 포카치아 왜 이렇게 맛있죠?? 밸런스가 너무 완벽해요. 첫입부터 끝입까지 맛있음', 41, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '신상 시나몬롤 먹으러  방문했어요. 결이 살아있는 빵에 설탕과 시나몬의 조합은 당 떨어질때 최고의 디저트 같아요. 깜빠뉴는 언제나 넘버원이지만 오랫만의 방문이어서 일까요.. 치솟는 물가탓인지 크기가 아담해졌어요. 작아져서 더 맛있게 느껴졌습니다^^;;', 27, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), 'ㅠㅠ 너무 예쁜곳 일단 빵도맛있고 다른메뉴들도 맛있고 커피도 맛있고 인테리어도 너무 예쁘고 청결해요 사장님 너무 미인❤️ 다음에 또 올게요!', 33, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '인생 샌드위치입니다 너무 맛있어요 특히 매쉬드포테이토 샌드위치가 제일 맛있었어요. 다음엔 다른메뉴도 먹어보고 싶어요 또올게욤!', 6, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '최애는 에그번이었는데 새로 나온 그릴드페스토 진짜 존맛..,💚💚💚💚💚 새로운 샌드위치가 많이 생기는거 같아 넘 좋아요 맛도 분위기도 참 좋은 이곳 나만 알고싶음 ㅠㅠㅠㅠㅠㅠㅠㅠㅠ', 23, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '가게가 숨어 있어서 잘 몰랐다가 오늘 처음 갔는데 커피도 맛있고 빵도 맛있네요. 가게가 작아서 매장에 앉아서 먹는 건 약간 힘들겠지만 바로 앞 계단에 앉을 때 커피 테이크아웃해서 마실 것 같아요~', 5, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '길 한켠 구석에 쏘옥 숨어있는 카페가 궁금해서 들어와봤는데 유명한 곳이었네요! 음악이 너무 좋아서 홀린듯이 커피 주문했는데 너무너무 좋아요!', 66, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '마감시간이 다 되어 소금빵을 사러 갔는데 이미 많은 빵들이 품절되어서 햄버거와 커피를 먹었습니다. 저녁먹으러 가기 직전에 들린 곳이라 햄버거 하나를 친구와 나눠먹었는데... 잘못된 선택이였어요🥲 배부르든 식사 약속이 있든 꼭 햄버거는 혼자 드세요ㅠㅠ 너무 맛있어요🫠🫠🫠🫠 다음엔 꼭 일찍 가서 다른 빵들도 먹어보겠어요!!', 32, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '소금빵이 궁금해서 방문! 요즘 개인적으로 소금빵에 꽂혀서 여기저기 먹어보는중인데 아주개인적으로 잘안맞앗어요 ㅠㅠ 개인적인거라 취향이 맞으신분들도 많을것같아요 그리고 매장분위기랑 빵 판매대가 너무 개인취향에 잘맞는곳! 다만 매장이 작아서 큰테이블하나랑 바형식하나라 혼자 방문추천해요', 3, 7, NULL, SYSTIMESTAMP);
