INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '앙버터 바게트가 서촌 *이버 앙버터처럼 엄청 가벼운 식감이네요:) 팥은 조금 달달한 편이고 버터풍미가 진하진 않은데 그래도 무난하게 맛있었어요 !', 41, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '문을 일찍닫아서 아쉽지만 사장님들도 주말이 있으셔야하니까😉 더블치즈버거와 앙버터 클리어하고 왔습니다 버거 번이 진짜 너무 맛있었어요! 치즈버거 좋아하시는분들은 꼭 한번 드셔봐야할 맛이에요', 62, 11, 'GOOD', SYSTIMESTAMP);
