INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '에그번이랑 소금빵,치즈소금빵 포장했는데 오늘은 에그번만 먹어봤어요! 1분 30초정도 데워서 먹었는데 진챠…진챠 맛있어요 뭔가 버거의 정점을 먹은 느낌이랄까.. 막 엄청난 재료가 아닌데 빵,에그,소스가 각각 너무 맛있었어요 빵이 일반 프렌차이즈는 비교대상도 아니고 수제버거집 중에서도 맛있구여 안에 계란이 몽실몽실 가득가득하구 소스가 매콤한데 무슨 소스인진 모르겠지만 진짜 맛있어요!!! 매장이 뭔가 지브리 영화에 나올 것 같은 분위기이고 뭔가 제빵천재이신 것 같아요…재방문의사 완전 있어요 잘 먹었습니다!!!!', 48, 3, 'GOOD', SYSTIMESTAMP);
