INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '사진엔 없지만 올리브 푸가스가 너무 커서 선물하면 장발장같고 웃기겠다 싶어 구매. 맛은 어떨지모르겠지만 선물시 당황시키기엔 성공했다', 81, 12, NULL, SYSTIMESTAMP);
