INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '포장해와서 먹었는데 정갈하고 예쁘게 포장해주셨어요. 맛도 있습니다.! 매장은 조용하고 아늑했어요. 다음엔 매장에서 먹어보고싶네요.', 23, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '더블치즈버거가 먹고싶었지만 안된다고 하셔서ㅠ 매쉬드포테이토 샌드위치 먹었는데 양도 많고 맛있었어요! 버거 먹으러 재방문할예정입니다', 28, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '신상 캬라멜바 먹으러 방문했어요 극강의 단짠단짠 ^^;; 깜빠뉴 최애 단골집인데 주3일만 오픈해서 아쉬워요 친절한 사장님 오래오래 판매해주세요~', 1, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '드디어! 먹어봤어요!!! 빵집이라서 번은 무조건 맛있구 고기패티까지 엄청 맛있습니다!!! 홍대쪽 살면 우울할 때마다 먹으러 올 듯 해요ㅠ 조금 간이 셌지만 아마 할라피뇨때문에 그런 것 같아요! 맛있게 잘 먹었습니다!', 36, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '카페라기 보다는 빵집에 가까운 곳입니다. 리뷰가 좋아서 기대하고 방문했는데 치즈바게트 좀 짜긴 하지만 맛있어요. 다음엔 다른 빵도 먹어보고 싶네요. 직원분 친절하셔서 좋은 기억으로 남았어요.', 40, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '소금빵이 맛있다고해서 다녀왔어요! 인생소금빵까진 아니더라도 맛있게 먹었습니다😃 너무 일찍가면 다른 빵들이 많이 없으니 12시 이후에 가는 게 좋을듯!', 39, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '포장하면 데워먹는 법까지 알려주시고 엄청 친절하세요!!! 나중에는 치즈버거 먹으러 꼭 다시 방문하려고요!!! 다른 종류도 다 먹어보고 싶어요!!!', 48, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '먹어본 소금빵중에 인생소금빵이에요 진짜 너무 맛있어요 다른빵도 하나씩 먹어보는중인데 하나같이 너무 맛있어서 기절… 월화 휴무인게 통탄스러울 정도ㅠㅠ', 13, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '우선 소금빵은 무조건 드세요ㅎㅎ 다음날 오븐에 살짝 구워먹어도 눈이 동그래져요 ♡ 치아바타 파는데가 흔치 않고 심지어 맛있는데는 손에 꼽는데 여기 치아바타 먹고 정말 감동 받았어요! 사워도우라서 아무리 많이 먹어도 안 질리고 계속 먹을 수 있을 것 같은 느낌.. 사장님도 넘 친절하셔서 기분 좋게 먹고 갑니다! 앞으로도 오래오래 맛있는 빵 만들어주시고 새해 복 많이 받으세요!', 33, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '당일 처음 맛보고 맛있어서 네개나 테이크아웃 햇어요!!! 사장님 친절에 또 감동받아 널리 알리고파 블로그에도 상세히 기록해뒀어요! 지금처럼 늘 한결같이 유지되길 https://m.blog.naver.com/jr5529/222525459103', 76, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '소금빵 맛집✨ 클래식한 빵들이 많아서 짱짱좋아요👍🏻 식사대용으로 제격입니다아!! 다음엔 햄버거도 먹고 크림치즈 깜바뉴도 먹을래요! 글구 소금빵이랑 스콘 백개 포장해와야디', 43, 8, 'GOOD', SYSTIMESTAMP);
