INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '햄버거가게인 줄 알고 갔음...빵집임 햄버거가 맛있음 패티에 진심임(조금짜다) 감튀도 좋음 역시 번은 최상임 다음에는 빵도 대량구매하고싶음', 126, 21, 'GOOD', SYSTIMESTAMP);
