INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '5점아니고 500점이고요,, 여기 모르는 서강대생 없읍니다,, 존맛탱은 기본이고요,, 사장님 친절하죠 인스타에 빵나오는 시간 다 나와있죠 분위기 좋고요 조용하고 빵냄새가 솔솔 나고요,, 가격도 착해요,, 저도 입학하기 전에 a slice부터 배웠읍니다,, 녹크치 앙버터가 최애입니다,, 두개 사서 친구랑 반반 나눠 먹으면 되는 겁니다,, 안 와본 사람은 신촌 한 번 더오셔야될 거에요,,', 64, 15, 'GOOD', SYSTIMESTAMP);
