INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '이전 가게였던 여심때부터 단골이었는데 새로 이전하신 곳이 훨씬 더 좋고 맛도 좋아졌네요!! 그리고 이제 커피도 파시구 빵이랑 함께 먹을 수 있는 테이블까지😭😭 진짜 최고였습니다 경의선숲길 담에 올땐 어 슬라이스에서 앙버터랑 커피 테이크아웃해서 피크닉하러 가야겠어요~❤️❤️', 42, 2, 'GOOD', SYSTIMESTAMP);
