INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '나만 알고싶은 맛집-! 홍대가면 무조건 들르는곳이에요ㅎㅎ 카페도 같이 하셔서 커피랑 갓 나온 빵을 바로 먹을 수 있어서 좋습니당:)', 53, 17, 'GOOD', SYSTIMESTAMP);
