INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '인스타에서 보고 찾아갔는데 젊은 사장님이 하시는 성실한 빵집같았어요 인상적이었던 건 앙버터를 주문과 동시에 만들어주시더라구요. 하드계열 빵은 미리 잘라두면 표면이 빨리 말라 그렇게 한다고 하시더라고요 너무 맛있었어요.. 추천입니다 또먹고싶어요', 48, 4, 'GOOD', SYSTIMESTAMP);
