INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '사장님도 너무 친절하시고 저는 사실 떡순이였는데 a slice빵 덕분에 빵순이로 입덕하기로 결정했어요!  치즈바게트 진짜 최고최고!💛커피도 너무 맛있었습니당^.^ 재방문 의사 100000%%%%', 27, 7, 'GOOD', SYSTIMESTAMP);
