INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어 슬라이스'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '신촌에 숨어있는 자그마한 빵집이예요. 골목길 올라가기가 힘들지만 올라간 보람이 있습니다. 종류가 많지는 않고 라인업이 크게 변하진 않아요. 그래도 기본 빵에 주문 즉시 이런저런 재료 넣고 만들어주시는 빵들이 참 맛있어요. 빵 자체도 담백하고 고소해서 종종 찾아갑니다. 샌드위치랑 크림치즈빵 추천해요!', 53, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '친구에게 공미학을 소개시겨주고 싶어서 들렀는데 일요일 오전에만 오다 평일 낮시간에 들리니 손님이 많네요. 친구도 흡족해 하는 공미학... 걷고싶은 돌다리는 손님이 많은 관계로 한번만 왕복해봅니다. 앉는 좌석의 방향이 바꿔니 보이는 풍경이 달라집니다. 몇번을 와도 늘 새로운 느낌으로 잘 쉬고 갑니다.', 7, 9, 'GOOD', SYSTIMESTAMP);
