INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '저희는 바캉수박주스랑 아메리카노 주문했는데, 수박주스는 생수박이 그대로 씹혀서 상큼하고 시원하게 에너지 충전하기 딱 좋았어요 🍉 아메리카노도 깔끔하게 잘 내려와서 만족했습니다. 위치도 카카오프렌즈샵 위에 있어서 쇼핑 동선이랑 딱 맞고, 아이들이랑 같이 들르기 좋은 공간이에요. 특히 영수증으로 아메리카노 한 잔을 증정받을 수 있어서 더 기분 좋게 즐기고 왔습니다 ☕ 전체적으로 동선 편하고 음료 퀄리티도 좋아서 홍대 나들이 때 또 들르고 싶은 카페였어요 👍 #홍대까페#홍대입구역까페', 73, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
