INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '홍대 카카오 프렌즈를 방문한 김에 이끌리듯 커피를 마시러 위에 카페로 올라갔어요~ 오후라 빵은 이미 많이 팔린 상태였고 이벤트 중이던 고구마빵도 없어 아쉬웠지만 도쿄멜론빵과 아메리카노로 선택했어요~~  커피원두가 쓰지않고 고소한 맛이라 좋았고 생각없이 골랐던 도쿄 멜론빵도  꾸덕촉촉한 메론 크림에  겉은 얇은 소보로 느낌에 은은달달한 딱 도쿄 메론빵의 정석이었어요~ 오랜만에 방문했는데 인테리어도 정갈하고 넓어져서 좋네요~카카오프렌즈에서 함께산 햄찌춘식과도 찰떡이네요 ㅎㅎ 시원하게 잘 있다 갑니다!,', 74, 15, 'GOOD', SYSTIMESTAMP);
