INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '친구랑 평일 저녁에 방문했는데, 자리도 넉넉하고 음료도 자리에서 태블릿으로 바로 주문할 수 있어서 좋았어요 :) 카페 분위기가 완전 인스타 감성..⭐️👍 #홍대입구 #홍대입구역 #홍대입구카페 #홍대입구역카페', 20, 5, 'GOOD', SYSTIMESTAMP);
