INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '카카오프렌즈 구경 왔다가 들렀어요~ 춘식이 고구마빵에 아이스크림 올라간거 맛있네요~ 수박주스도 진짜 수박이 들어가서 맛있네요~ 컨셉이 예뻐요^^ 사진찍기도 좋아요~ 바닥이 자갈돌이라서 조심히 다니셔요~ #홍대카페 #홍대입구역카페', 64, 14, 'GOOD', SYSTIMESTAMP);
