INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '멋진 인테리어에서 쉴 수 있는 카페에요 커피부터 시그니처 음료와 다양한 베이커리까지 여러 메뉴가 있고, 좌석도 엄청 쾌적해요 여름이라 수박주스 시켰는데 과육이 하나하나 느껴지는 미친퀄리티에 감동받았어요🥲 초코라떼랑 메론빵도 완전 꾸덕하고 시원했어요ㅎㅎ! 혼자와서 쉬기도 좋고 2인부터 6인까지 좌석이 다양하게 있어서 홍대에 온다면 무조건 들러야 하는 곳입니다!! 연인이나 친구들과 맛있는 음료와 간식 먹으면서 쉴쉴 곳 찾으시는 분들 강추드려요!! #홍대카페 #홍데데이트 #디저트맛집 #분좋카 #인테리어맛집', 50, 1, 'GOOD', SYSTIMESTAMP);
