INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '가격이 살짝 나가는 편이지만, 카카오프렌즈 콜라보도 즐길 수 있고, 카카오프렌즈에서 제품 구매시 받는 [1만원 이상 구매시 아메리카노 무료 쿠폰]을 적용하면 나쁘지 않은 가격에 여유를 즐길 수 있어서 좋습니다. 커플이 방문하면 넓고 잘 꾸며둔 공간에서 사진 찍기도 좋고 붙어서 시간 보내기 좋아요~ 홍대, 홍대입구역 근처에서 여유롭고 색다른 내부 인테리어의 넓은 카페를 찾는다면 추천합니다. #홍대카페 #홍대입구역카페 *테이블에 리뷰 QR이 구글이라 그거로 했는데, 네이버만 리뷰 이벤트 혜택이 된다고 하네요. 참고하세요~', 31, 1, 'GOOD', SYSTIMESTAMP);
