INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '우연히 찾아서 들린 카페인데 너무 감성 있고 커피도 맛있어요! 분위기도 차분하고 시끄럽지 않아서 지인들과 이야기하기 좋았어요. 위치도 홍대 입구역에서 도보로 2분 이내여서 접근성도 좋았어요! 재방문의사 200퍼 입니다!', 15, 8, 'GOOD', SYSTIMESTAMP);
