INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '#홍대카페 홍입 8출이랑 가깝고 좌석 간격도 넓고 분위기도 좋네요 ☺️ 주문도 자리마다 키오스크가 있어서 편해요 ~•●•° 커피도 맛나서 맘에 듭니다 !!!! #홍대입구역카페 추천!!!', 12, 3, 'GOOD', SYSTIMESTAMP);
