INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '카카오프렌즈 들렸다 방문한 홍대카페 공미학 분위기도 좋고 커피맛도좋은 홍대입구역 카페 ☕️ 넓고 심플한 인테리어도 멋져요!! #홍대카페 #홍대입구역카페', 3, 5, 'GOOD', SYSTIMESTAMP);
