INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '홍대입구 바로 앞에 위치에서 찾아오기  좋고 카카오 프렌즈랑 콜라보한 거 때문에 귀엽고 깜찍한 디저트들도 많아요!! #홍대카페 #홍대입구역카페', 65, 15, 'GOOD', SYSTIMESTAMP);
