INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '음료 나오는 그릇이 너무 예뻐요 선라이즈 에이드의 경우 나올때 데코도 예뻐서 눈으류 보기에도 너무 좋습니다 내부 인테리어도 감성적이어서 연인끼리 오기에 너무 좋을거 같아요! 홍대입구역 바로 앞에있어서 위치도 너무 좋습니당 #홍대카페 #홍대입구역카페', 55, 18, 'GOOD', SYSTIMESTAMP);
