INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '친구들이랑 카페 어디가지 하면서 여기로 왔는데 무엇보다 분위기가 너무 좋더라고요 ! 다른 카페들과는 다른 분위기라 새로웠어요 ! 노래도 굳 음료수랑 커피도 엄청 맛있어요 다음에 또 오겠습니다 #홍대카페 #홍대입구역카페', 82, 14, 'GOOD', SYSTIMESTAMP);
