INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '오랜만에 들른 곳입니다. 카카오프렌즈 매장 위 층에 있어고 많이 바뀔 줄 알았는데 그대로네요. 이곳은 음료나 간식류도 괜찮디만 인테리어가 흥미로운 곳이죠.', 5, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '#홍대카페 #홍대입구역카페 일단 카페 자체는 깨끗하고 좋아요! 테이블마다 키오스크도 있어서 주문하기 편해서 좋았습니다. 커피랑 수박쥬스 빵 2종 시켜봤는데 음료는 괜찮았는데 빵이 조금 눅눅한데 맛은 나쁘지 않아요. 소금빵 제대로 안보고 시켜서 트러플인지 몰랐는데 트러플 소금빵이니 드실분들 꼭 참고하시길!', 123, 26, NULL, SYSTIMESTAMP);
