INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '분위기도 예쁜데 음료까지 정말 맛있게 먹었어요!!!! 리얼 자몽에이드와 연유 아몬드라떼 주문했는데, 자몽에이드는 과육이 듬뿍 들어가서 상큼하고 시원한 맛이였고,연유 아몬드라떼는 고소한 아몬드 풍미에 연유의 달콤함이 더해져 부드럽고 진한 맛이 대박이였어요!!! 한 모금 마실 때마다 조용한 음악과 감성 인테리어가 어우러져 힐링되는 느낌~.~ 창가 자리 앉아서 여유롭게 친구랑 수다 떨기 딱입니다! 직원분도 친절하셔서 기분 좋게 머물다 왔습니다~ 마포역 근처에서 예쁜 카페 찾는다면, 공미학 추천드려요!', 37, 3, 'GOOD', SYSTIMESTAMP);
