INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '밤 늦게 여는 카페 별로 없는데 여기는 오랫동안 운영하고 좋아요. 냅킨도 이쁘고 사진 아무렇게나 찍어도 잘 나오는 느좋 카페네요 ㅎㅎ 음료잔도 이쁘고 맛있어요~ #홍대카페 #홍대입구역카페', 69, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '🙂 아메리카노 - 맛있어요. 홍대에서 이가격에 이사이즈면 좋죠. 🤨 롤크레이프 - 단거 좋아하시면 ok. 그런데끝부분들이 살짝 말라있어요. 그래도 가운데 부분은 괜찮아요. 🤨 쑥라떼- 쑥맛이 아니라 선식맛이에요. 그리고 선식가루 맛 나는 이 재료는 냉장보관인거 같은 냉장냄새의 느낌이 확 와요. 위에 떡은 당고가 아니라 그냥 꿀떡인데 좀 딱딱해요. 😡화장실- 지하철 화장실 갈걸🫠', 22, 10, 'BAD', SYSTIMESTAMP);
