INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '카카오랑 같이 있는데 공간이 꽤멋지네요!! 사람들도 많고 베이커리류도 많아요 ㅎㅎㅎ 구경하면서 들르기 좋은 멋진 카페네용 추천해요!!', 1, 8, 'GOOD', SYSTIMESTAMP);
