INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '공미학의 장점은 콘센트가 있다. 그리고 자리에서 주문이 가능하다. 그리고 음료나 디저트가 맛있다. #홍대입구역카페 #홍대카페 바라는점 1. 조명이 전시장용 레일 조명이라 너무 밝다. 그 들어와서 왼쪽창가 쪽 자리에 앉으면 눈뽕이 있다. 2. 디저트에 덮개가 없어서 날파리가 주위에 돌아다니는 것을 보았다. 덮개가 있다면 좋을듯 3. 자리에서 주문하는데 픽업을 하러가야하는게 약간의 흠. 안바쁠땐 서빙해주면 훨씬 좋지 않을까. 4. 갈대 인테리어를 지나갈때 여름철에는 살갖이 많이 쓸렸다. 5. 달 포토존 약간유행지난 느낌인데, 뭔가 바꾸는게 좋지 않을까,, 6. 홍대 새벽 영업까지 할게 아니라면 굳이굳이 펍을 유지하며 술을 팔 이유가..? 잘모르겠음.. 여기에 낮부터 술마시러 올 사람이 있으려나..', 55, 14, NULL, SYSTIMESTAMP);
