INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '카카오프렌즈샵 왔다가 3층에 멋진 카페가 있어 방문해보았습니다! 깔끔한 인테리어와 카카오와 콜라보한 특별한 메뉴가 좋네요 ㅎㅎ #홍대카페 #홍대입구역카페', 20, 5, 'GOOD', SYSTIMESTAMP);
