INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '엄마랑 홍대 나들이 왔다가 홍대 카페 어디갈지 검색하다가 가까워서 왔는데 너무 만족했어요. 엄마가 시그니쳐 쑥라떼가 너무 맛있다며 그 자리에서 바로 마시셨어요. 분위기도 좋고 따로 공부할 수 있는 자리도 있어서 좋았어요. 무엇보다 너무 깔끔하고 넓어서 시원했어요. 음료도 맛있고 직원 분들도 친절하세요 #홍대카페 #홍대입구역카페', 60, 14, 'GOOD', SYSTIMESTAMP);
