INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '그냥그냥. 카카오프렌즈 왔다가 다리 아프고 목아파고 화장실 들를까하고 겸사해서 들름.  특별한 맛은 아님. 일단 화장실이 너무 드러워서 다시는 안올듯', 26, 3, 'BAD', SYSTIMESTAMP);
