INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '너무 맛있어요~~!👍 검색해서 왔는데 역 근처에 이런 좋은 카페가 있는지 몰랐네요!! 또 올게요! #홍대카페 #홍대입구역 카페', 39, 9, 'GOOD', SYSTIMESTAMP);
