INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '카카오프렌즈 샵 위층에 있길래 갔는데 분위기 좋고 음료도 정말 맛있어요! 특히 에이드가 상큼하고 시원해서 여름에 딱이에요. 디저트도 비주얼이 너무 예쁘고 맛도 좋아요 :) 연인이나 친구랑 수다 떨기 좋은 홍대 입구역 근처 카페로 추천합니다! #홍대카페 #홍대입구역카페', 23, 0, 'GOOD', SYSTIMESTAMP);
