INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '항상 1-2층에 있는 카카오프랜즈 샵만 들렸는데 3층에는 카페도 있다는 소식을 듣고 가게 되었어요!! 들어가자마자 확 달라지는 분위기에 놀라고 안에 인테리어를 보고서 많이 놀라게 되었어요!! 안에 나무도 있고 정원을 보는 곳 같은 바닥과 호수 정말 아름다웠어요!! 특히 디저트는 카카오 프렌즈와 콜라보 한것이 많았어요!! 다만, 밤에 와서 그런지 디저트의 종류가 적어서 너무 아쉬웠어요… 그래도 음료 너무 맛있고 디저트도 너무 맛있어요!! 다음에도 또 카카오 프랜즈 샵을 들리게 되면 여기를 반드시 또 들려야 겠어요!!', 13, 1, 'GOOD', SYSTIMESTAMP);
