INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '시즌으로 나온 수박주스는 달달하고 이쁘게 나왔고 블랙의 미학은 건강(?)한 맛이 났어요!ㅋㅋㅋ 직원분이 친절하시고 인테리어도 이뻐서 좋았어요~', 38, 2, 'GOOD', SYSTIMESTAMP);
