INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '데코레이션 진짜 예쁘고 커피라유음료 맛있어요. 빵랑 케이크도다양하게 있는데 매진 종류들도 있어서 먹고 싶은거 없었어 있는빵만 시켰어요. 그거도 맛있어요  사진 찍기 좋은 카페에요. 조용하게 대화를 할수 있는 공간이에요.', 36, 2, 'GOOD', SYSTIMESTAMP);
