INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '분위기 좋고 데이트 하러오기 좋아요! 주말에는 사람 많은 편인데 평일 저녁에 오니까 사람도 많이 없고 분위기도 좋네요! 음료도 맛있습니다', 74, 11, 'GOOD', SYSTIMESTAMP);
