INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '남자친구랑 카카오프렌즈샵 온 김에 처음 방문했는데 인테리어가 너무 느좋이라 놀랐어요ㅠㅠ 전시 되어있는 춘식이들도 너무 귀엽고 테이블마다 키오스크가 있어서 너무 편했어요! 저는 딸기라떼 마셨는데 딸기 다이스 올려주셔서 새콤한게 씹는 맛두 있고 좋았어요! 카카오프렌즈샵은 홍대 올 때마다 왔었는데 여기를 이제 오다니ㅠㅠ 앞으로 올 때마다 매번 들릴거 같아요!!', 32, 0, 'GOOD', SYSTIMESTAMP);
