INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '춘식이 고구마빵 따뜻하게 나오니 더 맛있게 잘 먹었어요~! 수박주스도 예쁘고 샤베트 올라가 있어 시원했어요. 아메리카노도 산미가 있어 빵과 어울렸어요.', 87, 12, 'GOOD', SYSTIMESTAMP);
