INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '카카오프렌즈 스토어에 왔다가 들러 봤어요. 춘식이빵 궁금했었는데 먹어보니 쫄깃하고 넘 맛있네요. 아이스 아메리카노 연하게 마셨는데 춘식이빵이랑 잘 어울려요! 공간도 멋지고 분위기 좋네요!', 19, 5, 'GOOD', SYSTIMESTAMP);
