INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '카카오 프렌즈 구경하다가 우연히 방문하게 되었는데 인테리어도 이쁘고 분위기가 넘 좋아서 오랫동안 앉아있었네용 디져트도 맛있어요!! #홍대카페 #홍대입구역카페', 25, 6, 'GOOD', SYSTIMESTAMP);
