INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '주말 홍대라서 사람 많았지만 그래도 앉을 자리가 있었고 자리에서 바로 키오스크 주문 가능해서 편했음~ 인테리어가 독특한데 분위기가 나름 운치있었고 옆에 카카오프렌즈 매장도 있어서 심심할때 구경하면 좋을듯함! +커피는 산미 있는편, 메론빵은 겉은 퍽퍽...에 가까운 바삭/가운데 크림 몰빵되어잇음, 맛 무난하고 크림 있는 메론빵 러버라면 추천', 73, 17, NULL, SYSTIMESTAMP);
