INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '홍대에서 예쁜 카페를 찾다가 와봤어용! 디저트도 맛있고 커피도 맛있었습니당ㅎㅎ 다만 의자와 테이블이 생각보다 편하진 않았어요ㅜ 편한 자리가 있긴하지만 몇개 안되어서 아쉬웠습니당ㅜ 그 자리가 남아있다면 또 올 의향 가득해요!!ㅎㅎ 행운이 따르시길 바랍니당🍀', 83, 18, NULL, SYSTIMESTAMP);
