INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '카카오프렌즈 춘식상회 구경 왔다가 공미학도 들러봤어요~ 수박주스랑 자몽주스 시켰고 둘 다 상콤하니 맛있었답니다! 매장 인테리어가 여름에 오면 정말정말 그 분위기가 찰떡일 것 같은 느낌이에요!', 37, 2, 'GOOD', SYSTIMESTAMP);
