INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '홍대올때마다 들리기는 하는데 이번에는 더 친절함에 감동... 친구가 아메리카노 연하게 먹는데 혹시 너무 연할까 샷도 준비해주시는데 어찌 이곳을 안 알릴수 있을까요...? 곡 선곡도 너무 좋습니다', 38, 5, 'GOOD', SYSTIMESTAMP);
