INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '홍대 거리 돌아다니다가 잠깐 쉬려고 들어간 카페인데 너무 만족했어요! 공간도 넓고 분위기도 좋고 디저트도 맛있는 편이에요~~ 계단만 내려가면 카카오프렌즈 샵과도 연결되어 있어서 볼거리도 많고 좋았습니다 홍대 가게 되면 자주 들르고 싶어요~!', 96, 24, 'GOOD', SYSTIMESTAMP);
