INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '친구랑 돌아다니다 들렸는데 분위기도 좋고 아늑해요 카카오프렌즈 샵이랑도 가까워서 구경하고 오거나 들렸다 구경하기 좋아요!! 가격도 나쁘지 않아요!!', 31, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '홍대 근처 카페 찾다가 가게된 공미학. 일요일 저녁시간이라 딸기라떼는 딸기 재료 소진, 빵들은 거의 다 없었.... 커피 맛은 연한 편이이어서 그나마 마실만 했어요 다른 음료는 안먹어봐서 모르지만 다음에는 다른 지점도 가볼까 합니다.', 0, 6, NULL, SYSTIMESTAMP);
