INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '라벤더차 수색이 너무 예뻐요🥹🥹🥹 주스도 엄청 맛있고 알차요 가게도 넓고 쾌적하고... 무엇보다도 직원분이 친절하십니다! 부모님 모시고 오기 너무 좋았어요 잘 쉬고 갑니다!', 4, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '홍대입구랑 가까워서 좋고 메뉴도 다양하고 자리도 넓어서 친구들이나 지인들과 오기 좋은 카페입니다 가게도 조용한 분위기라 너무 좋았습니다 다음에 또 방분할게요~!', 32, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'MEETING');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '이곳의 시그니처 메뉴인 블랙의 미학을 주문해봤는데 고소하고 맛있었어요 매장이 넓고 인테리어도 마음에 들고 특히 바닥에 둔  자갈들이 마음에 들었어요', 75, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공미학 마포홍대점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '기대안햇는데 음료가 너무 맛잇고 깔끔해요! 분위기도 좋고 자주 올거같아요  카카오프렌즈 3층에 이런곳이 있다니 너무 좋아요!!', 124, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '합정에 이런 완벽한 카페가 ... 주차도 가능하고 이벤트 메뉴까지 다 해서 주문하니까 무슨 뷔페에 온거같아요 ㅎㅎㅎ 가성비가 너무 좋고 커피도 너무 맛있어요!! 커피머신도 좋더라구요..!! 쾌적하고 의자도 편안하고 직원분들도 아주 친절해요!!!', 55, 14, 'GOOD', SYSTIMESTAMP);
