INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '합정역이랑 가깝고 인테리어가 너무 멋져요❣️첫 방문인데 이런카페가 숨어있어다닝..합정올 때 마다 올듯요! 요즘 말차에 꽃혔는데 말차크림라떼도 넘 맛나요 ㅠ 분위기도 좋고 많이 시끄럽지도 않아서 최애카페 될 것 같아요', 90, 11, 'GOOD', SYSTIMESTAMP);
