INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '넓고 쾌적하고 친절하세요. 3층은 꽉차서 이번엔 1층 이용했어요. 테이블간격이 넓어서 편하고 좋아용 여러가지 음료나 디저트 이벤트도 해주셔서 넘 좋습니당 ㅎㅎ', 75, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '와.. 분위기, 맛, 멋 모두 퍼펙트...!! 너무이뻐요 ㅎㅎ 커피도 크레마 찐하니 구수하고 맛있어요 무엇보다 인테리어가 이국적인게 여행온느낌~_~ bgm도 짱좋아요 ㅎㅎ 단골찜꽁!', 24, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'INDUSTRIAL');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '매장 - 서교동 조용하고 분위기 좋은 카페 /  합정역 3번 출구에서 도보로 약 5분 거리 / . 모던하고 세련된 우드톤 인테리어에 식물이 조화롭게 어우러져 따뜻하고 감성적인 분위기 메뉴 - 아이스아메리카노: 5,300원 약간 비싼편, 산미 없이 무난한 맛으로, 개성이 강하지 않아 누구나 편하게 즐기기 좋음 / 멧멜랑슈, 크림카라멜커피, 말차크림커피 등이 대표적인 시그니처 메뉴 / 최근에는 아인슈페너와 말차 아인슈페너도 인기 후기 - 멧커피의 아늑하고 조용한 분위기 만족 / 네이버 리뷰 작성 이벤트를 진행하고 있어, 리뷰를 남기면 너무 이쁘고 귀여운 미니 초코 생딸기 케이크를 받을 수 있어요.', 65, 18, 'GOOD', SYSTIMESTAMP);
