INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '빵순이 남편이 우연히 "아펠슈트루델" 오스트리아 대표 간식을 알게되어 찾아보니 멧커피 홍대점에만 판매해서 오게됐어요 페스츄리같은 빵 식감에 안에 졸인?사과가 들어 있고 생크림에 푹 찍어보니 달콤하니 너무 맛잇어요 디저트도 맛나지만 아인슈페너도 맛잇고 카페 분위기가 너무 좋아서 계속 오고 싶어지는 곳이에요 주차도 두자리 가능합니다 자주 올께요😍😍', 80, 13, 'GOOD', SYSTIMESTAMP);
