INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '커피 맛있다고 해서 왔는데 진짜 맛있네요 ㅎㅎ 매장이 3층까지 있어서 뷰가 되게 좋아요👍 무엇보다 의자와 테이블이 널찍하게 떨어져 있어서 여유롭고 대화하기에도 아주 좋습니다. 카페 안에 공간이 많은데 곳곳마다 테마있게 꾸며진 느낌이라 다음에 꼭 지인들이랑 함께 오고 싶은 곳이에요 😊 혼자 여유있게 즐기다 갑니다~!', 369, 30, 'GOOD', SYSTIMESTAMP);
