INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '말차크림이 진하고 달달하니 맛있었고 ! 미니케이크도 같이 먹으니까 당 충전 제대로였어요 ㅎㅎ 날씨도 너무 덥고 말차 들어간 커피 먹고 싶어서 찾아보다가 들어왔는데 좌석도 편하고 매장도 쾌적하니 좋았습니다 💚🖤🤎', 14, 6, 'GOOD', SYSTIMESTAMP);
