INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '키오스크로 빠르게 주문이 가능했고 1층라운지랑 3층이있는데 3층도 대화하기 좋고 아늑했어요! 옆에 빵굽는곳도 보였는데 직접만드시는거같아서 더 맛있어보이고 실제로 맛있었습니다. 합정가다가 홀린듯 들어갔는데 만족해요!', 30, 8, 'GOOD', SYSTIMESTAMP);
