INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '아 매장이 너무 예쁘고요~~ 아인슈페너가 너무 맛있어요!!! 아메리카노 원두는 산미가 있는편이고 다른 음료들은 크림이 엄청 진해요. 쟁반이랑 그릇도 너무 예쁘고, 컵이랑 뚜껑이 너무 센스있어요. 청결도도 너무 좋아서 재방문할거같아요', 18, 10, 'GOOD', SYSTIMESTAMP);
