INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '멧커피는 우연히 지나가다가 조용한 분위기가 마음에 들어 들어가 보게 된 곳이에요. 사람도 많지 않고 전체적으로 잔잔한 분위기라 혼자 머물기 참 좋았어요. 저는 아이스 아메리카노를 디카페인으로 한 잔 주문했어요. 주문도 빠르게 나왔고, 맛은 전체적으로 깔끔하면서 산미는 거의 없어서 마시기 편했어요. 디카페인인데도 밍밍하지 않고 은은하게 풍미가 살아 있어서 만족스러웠습니다 :) 전체적으로 조용하고 차분한 분위기 속에서 커피 한 잔 하기 좋은 곳이었고, 다음에도 근처 지나가게 되면 다시 들르고 싶다는 생각이 들었습니다💚', 45, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '합정,홍대 통틀어 애정하는 3대 카페 중 하나예요. 인테리어,음료,디저트 다 고급스러움 그 자체. 5~6번 째 방문인데 2층은 남성적으로 멋있는 공간이라면  4층은 여성적으로 예쁜 공간?ㅎ 같이 간 친구도 너무 좋아했어요~~♡', 50, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '합정역 주변 편안히 쉴만한 카페 찾던중 들어왔는데 커피뿐만 아니라 시그니쳐 메뉴들도 매력적이에요 잘쉬고 편안하게 먹고가기 좋아요!:)bb', 12, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '말차투어 다니고 있는 중인데 여기 말차 진짜 진짜 맛있어요!! 말차딸기라떼 먹어본 것 중에 젤 최고에요 진짜임. 딸기라고 해서 엄청 달지도 않고 말차랑 진짜 잘 어울려요 직원분도 너무 친절하셔서 다음에 꼭 또 오고싶어요 카페 분위기도 대화하기 좋고 너무 좋아요 합정역 느좋카페입니다 ~!~!!', 46, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '회사 직원들이랑 자주 오는 곳이에요~ 장소도 쾌적하고 커피랑 디저트도 넘 맛있어요ㅠㅠ 날씨 좋을 땐 여기 외부 테이블도 좋아해요', 63, 15, 'GOOD', SYSTIMESTAMP);
