INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '공간 넓고 층 여러개라 카공하기에도 좋고 떠들기도 좋아요. 담요도 배치되어있고 통창이라 사진도 너무 잘나와요. 레몬파운드케이크 너무 맛있어요! 물론 음료도 맛있구요', 9, 5, 'GOOD', SYSTIMESTAMP);
