INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '벌써 두번째 방문인데, 올때마다 분위기도 너무 좋고 커피랑 음료도 너무 맛있어서 놀라고 갑니다! 이렇게 좋은 곳인데 왜 더 많이 안알려졌지.. 좋은 마음 반 아쉬운 마음 반인데 개인적으로 저만 알고 싶은 카페에요! 직원분도 너무 친절하십니다🍀', 49, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '추천 받고 찾아왔는데, 기대 이상으로 맛있었어요! 디저트 종류도 다양하고 음료 선택지도 다양해서 좋았어요 ㅎㅎ 다음에 기회되면 한번 더 찾아오고 싶어요! 말차 음료 좋아하시는 분이라면 방문 추천합니다 👍', 15, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '시그니처 말차크림커피에 올라간 말차크림이 적당히 달고 맛있고 말차라떼도 맛있고 딸기케이크 맛있다고 해서 기대했는데 정말정말 맛있어요 카페가 넓고 쾌적하고 분위기가 좋아요', 103, 26, 'GOOD', SYSTIMESTAMP);
