INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '시그니처 마차 커피 마셨어요 너무 맛있어요 은은한 커피의 맛과 마차크림이 잘 어울러지는 부드러운 맛입니다. 인테리어도 너무 이쁘고 커피머신들이 멋있어요 재방문의사 있어요', 58, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '멧커피 재방문 1000% 다음번엔 지인들이나 남자친구랑 올게요! 기억하고 싶어서 몇 자 적어봐요 . . 1. 공간마다 특색있는 분위기 🫶🏻 2. 우드톤 인테리어 그린 몇 방울 🌿 3.  말차아인슈페너 *️⃣ 디카페인 변경도 가능 4. 잠봉뵈르샌드위치 포함 다양한 디저트 또 오고싶은 곳 - !!! 💚💟', 34, 0, 'GOOD', SYSTIMESTAMP);
