INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '잠시 일할게 있어서 방문했는데 정말 청결하고 인테리어도 예뻤어요 카공하기 딱 좋고 친구들이랑 방문해도 좋을 것 같습니당 커피도 맛있고 빵도 맛있었어용☺️ 예쁜 카페 운영해주셔서 감사합니당 좋은 하루 되세용 사장님💕', 8, 5, 'GOOD', SYSTIMESTAMP);
