INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '근처에 올 일이 있어서 우연히 들린 카페인데 리뷰 이벤트하고 있어서 맛있게 먹었어요! 뭐지 말차 크림 커피 진짜 너무 맛있어요ㄷㄷ 공간도 넓고 쾌적하고 합정 오면 멧 커피 웨 안 와🤤🤤', 49, 5, 'GOOD', SYSTIMESTAMP);
