INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '생초콜릿이 미쳤네요… 진짜 너무 맛도립니다 이거때메 리뷰써요 ㅜㅜ 방문했을 때 손님이 거의 없어서 조용하고 아늑하게 잘 쉬다 갑니다 ㅎㅎ 인테리어도 좋고 화장실 깔끔하고 사장님도 친절하세요~!!! 담뇨도 있더라구요 콜드브루는 쏘쏘', 14, 8, 'GOOD', SYSTIMESTAMP);
