INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '말차 슈페너 맛있어요 ㅎㅎ 매장이 넓은데 인테리어도 예쁘게 잘 꾸며져 있고 날 시원해지면 야외자리도 좋을것 같아요~! 통창이라 풍경도 좋네요 🪴', 43, 3, 'GOOD', SYSTIMESTAMP);
