INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '아펠 슈트루델 먹고 싶어서 멀리서 찾아왔어요! 말차라테도 달달구리하면서 쌉싸름한게 넘 맛있고, 아메리카노는 산미없이 고소해서 취향저격이었어요~ 대망의 아펠슈트르델은 생크림과 사과의 조화가 좋어요 빵도 넘 부드러워용 🥰❤️', 102, 26, 'GOOD', SYSTIMESTAMP);
