INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '잠봉뵈르도 엄청 맛있고 피자도 촉촉하니 너무 맛있어요!! 그 무엇보다도 맛있는건 저 딸기케이크 엄청 촉촉하고 딱 먹자마자 와우 딸기케익🩷🩷 이느낌 이예요!! 여기 가격대비도 괜찮고 너무너무 좋아요!! 자주 올 것 같아요', 53, 15, 'GOOD', SYSTIMESTAMP);
