INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '조용하고 따뜻한 분위기가 너무 좋은 카페예요🥺 우드톤 인테리어에 포근한 조명, 넓게 떨어진 테이블 배치 덕분에 사람들 시선 신경 쓰지 않고 편하게 작업하거나 책 읽기 정말 좋았어요. 의자도 푹신하고 공간도 쾌적해서 오랜 시간 머물기에도 부담 없었습니다🤍 곳곳에 전시된 사진들과 아날로그 오디오 장비가 감성적인 무드를 더해주고, 구석구석 신경 쓴 인테리어 덕분에 사진 찍기에도 좋아요. 디저트도 정성스럽게 나와서 커피랑 같이 먹기 딱 좋았고, 전체적으로 조용하고 여유로운 분위기라 혼자 오기도, 친구랑 이야기 나누기에도 참 괜찮은 공간이었습니다! 일정 마감하거나 생각 정리할 공간 필요할 때 또 오고 싶은 곳이에요. :)', 4, 2, 'GOOD', SYSTIMESTAMP);
