INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '한 번씩 들려 커피 마시는 곳이에요. 우연히 들려본 곳인데 커피, 디저트 맛이 생각나는 맛이에요~^^ 1층, 3층 공간이 있는데 지인과 만남장소로도 추천해요', 54, 13, 'GOOD', SYSTIMESTAMP);
