INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '카페가 크고 깔끔합니다! 앉을 곳도 많고 의자가 편해서 좋았습니다.  디저트랑 음료의 종류도 많았고 주문 받는 곳 뒷쪽에 제빵하는 곳에서 직접 베이킹 하는 것을 볼 수 있습니다! 후기로 받은 피자빵이 담백하고 너무 맛있었어요 야채도 많고 너무 취향이었습니다! 합정에서 갔던 카페 중 가장 좋았고 자주 찾게 될 것 같아요!', 41, 10, 'GOOD', SYSTIMESTAMP);
