INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '말차크림커피 진짜진짜 맛있어요 ! 진득한 말차맛과 적당히 달달한 크림 커피 맛을 원한다면 강추🍵 직원분들 넘 친절하셔서 좋았구, 쇼핑하다 쉬었다 가기에 완전 적합한 카페입니다아', 42, 10, NULL, SYSTIMESTAMP);
