INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '테이블 간격 넓어서 좋구 작업하기도 좋아요 커피 맛있고 공간이 예뻐요 이벤트 피자도 맛있는ㄷ데… 3층 엘베 불편, 화장실 외부 불편 이슈 있지만..', 18, 1, NULL, SYSTIMESTAMP);
