INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '벌써 세번째 리뷰를 남기게 되네요. 멋진 사장님의 센스가 돋보이는 2층에서 친구와 행복한 시간을 보내고 왔습니다. 햇빛이 기분좋게 쏟아지는 2층에서 조명따윈 필요없어요. 햇빛을 조명 삼아 열심히 미친듯 사진 찍습니다. 흰색 커튼이라 더 맘에 듭니다. 커피가 맛있어서 이곳은 나가려다가도 한잔 더 마시고 가게끔 만드는 카페지요~ 또 갈게요!', 23, 5, 'GOOD', SYSTIMESTAMP);
