INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '우연히 찾은 가게인데 확실히 분위기가 너무 좋아요!! 딸기케이크 맛잇다고해서 시켜봤는데 너무너무 맛잇더라구요! 입에서 녹아요 안느끼하고 좋아요 아이스말차라떼도 강추!! 안쓰고 부드러워요 ㅎㅎ 음료도 디저트도 다 맛있어요!! 분위기도 감성낭낭해요 일층도 삼층도 넓고 예뻐요 ㅎㅎ', 80, 14, 'GOOD', SYSTIMESTAMP);
