INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '내부 인테리어 넘 이쁘고, 3층도 있어요!! 요즘 핫한 말차 종류 많구, 화장실도 넘 깔끔해요~~ 이색 디저트라고 해서 시켜봤는데 애플파이 같아요! 강추합니당ㅎㅎ', 5, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '자몽에이드도 시럽없이 먹을 수 있어서 너므 좋았어요! 시럽없이도 너무 맛있구요! 커피도 맛있고 자리가 편하네요!! 빵디저트 종류도 많아서 좋아요!!! 직접 베이킹까지 하시는지 맛도 넘나 좋습니다 👍🏻', 68, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
