INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '오랜만에 같이 모인 친구들과 저녁식사 장소 옆에 있길래 방문했어요! 음료 크림이 너무 맛있구 크림이랑 음료랑 밸런스가 너무 잘 맞아요.. 초콜릿이랑 빵 주시는 이벤트도 많이 해주셔서 놀랐구 좋아요🌿 카페두 넓고 소파 자리도 편안해서 더워진 날씨에 잘 쉬다 가요🤎', 4, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '예쁜 케이크에 홀려서 들어왔습니다🤣 딸기 케이크 딸기가 정말 맛있어요. 특히 요즘 케이크들은 위에 올려진 딸기에 설탕 코팅 하던데 없어서 과일 그 자체의 단맛을 느낄 수 있어서 정말 좋았습니다! (생크림도 맛있어요~) 리뷰 이벤트로 받은 케이크는 초코가 엄청 딥해서 조금 달았지만 정말 맛있는 초코맛이었어요🍫', 2, 7, 'GOOD', SYSTIMESTAMP);
