INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '퇴근 후 영어학원 가기 전에 간단하게 빵 먹으면서 쉬었어용 ㅎㅎㅎ 음료도 다양하고 베이커리류도 많아서 좋네요~ 잠봉뵈르 베이글은 품절이라서 아쉬웠어요 인기가많나봐요 다음엔 일찍와야겠어요', 36, 0, NULL, SYSTIMESTAMP);
