INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '근처에 점심 먹으러 나왔다가 들렸는데 3층까지 있어더라고요! 공간도 예쁘게 꾸며져 있어서 기분이 좋아져요...🌷💖 커피랑 케이크도 맛있게 잘 먹었습니다!', 17, 7, 'GOOD', SYSTIMESTAMP);
