INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '지나가다가 들렸는데 분위기도 너무 좋고 디저트랑 음료 너무 맛있어요 말차 러버인데 진짜 맛도리입니다. 너무 시끄럽지도 않고 음악도 잔잔하니 좋아용~😃😃', 45, 5, 'GOOD', SYSTIMESTAMP);
