INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '홍대에서 유명하다길래 찾아가봤는데 왜인지 알거같았어요!! 분위기 독특하고 인테리어 짱이뻐요:) 커피도 진짜 맛있더라구요!! 주문도 자리에서 네이버로 바로 할 수 있어서 편하고 좋았어요-', 14, 4, 'GOOD', SYSTIMESTAMP);
