INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '즉흥적으로 들어간 곳인데 너무 만족했던 카페예요 ! 매장도 넓고 사진 너무 잘나와서 사진 건지고 가용 ! 그리고 편한 좌석 좋아하는 사람인데 여기 쇼파의자도 있고 좌석도 편합니다 ! 여기 딸기라떼 말차라떼 다 맛있으니까 홍대 카페로 추천해용 !', 84, 18, 'GOOD', SYSTIMESTAMP);
