INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '카페가면 대화하기 힘들 정도로 시끄러운 곳이 많은데 조용하고 아늑하면서도 커피도 맛있고 잠봉뵈르도 말차크림커피도 다 맛있어서 행복하게 즐기다 왔습니다~~!!', 20, 6, 'GOOD', SYSTIMESTAMP);
