INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '우와우 합정에 이런카페가 있었다니 😲 보물 발견이네여 케이크도 존맛탱이고 맛차아인슈패너 도라이에요 개맛있어요 그냥;;; 디저트 한입 먹어보고 반함 넘 맛있따.. + 카페 자리도 엄청많고 분위기 미쳤네요 과제하러 오거나 여유롭게 노트북들고 할일 하기도 넘 좋은듯 👍 합정은 붐비기만 하는 줄 알았더니 이런 쾌적한 곳이 있었다니!!!!', 34, 4, 'GOOD', SYSTIMESTAMP);
