INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '전에 왔다가 너무 맛있어서 경기도에서 또 방문했습니다. 태어나서 먹은 말차 중에 압도적인 1등입니다. 합정 홍대 올 일 있으면 무조건 올 것 같네요 !', 43, 8, 'GOOD', SYSTIMESTAMP);
