INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '말차크림생딸기라떼, 말차크림커피, 아이스초코라떼, 생딸기케이크 주문했어요~ 1,3층이라 자리도 꽤 많고 조용해서 좋네요 음료도 말차류 맛있어요! 케이크는 진짜 작아요 진짜 진짜..이렇게 작은 조각케이크 첨봐요 맛은 생크림이 달고 빵부분은 살짝 파운드밀도? 같아요 음료류 시그니처 메뉴 추천이요!', 15, 3, 'GOOD', SYSTIMESTAMP);
