INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '매장 너무 넓고 쾌척하고 조용해서 좋아요! 음료도 너무 맛있고 오스트리아 디저트도 너무 맛있네요! 네이버로 쉽게 주문할수 있어서 편리하고 좋더라구요 적극추천👍🏻🥰', 17, 5, 'GOOD', SYSTIMESTAMP);
