INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '슈트루델이 너무 맛있고 밀크티도 맛있었습니다. 밀크티가 많이 달지않고 진해서 좋았습니다. 3층 분위기도 좋고 의자도 편해서 좋은 시간 보낸 것 같습니다!', 13, 1, 'GOOD', SYSTIMESTAMP);
