INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '커피 맛이 정말 좋았어요. 원두 향이 진하고 균형 잡힌 맛이라 만족스러웠습니다. 특히 이곳에서만 맛볼 수 있는 특별한 디저트가 인상적이었어요. 다른 데서 쉽게 볼 수 없는 메뉴라 더욱 기억에 남습니다. 또한 공간이 넓고 탁 트여 있어서 답답함 없이 여유롭게 시간을 보낼 수 있었어요. 햇살도 잘 들어와서 앉아만 있어도 기분이 좋아지는 곳입니다. 재방문 의사 100%입니다!💯💯', 1, 10, 'GOOD', SYSTIMESTAMP);
