INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '인테리어에 신경쓰신 게 느껴졌어요! 조명도 이쁘구요!! 자몽에이드랑 밀크티도 맛있더라구요!! 시식으로 받은 피자도 너무 맛있어서 잘 먹었습니다', 17, 8, NULL, SYSTIMESTAMP);
