INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '더운 날씨에 한줄기 빛 ㅠㅠ 매장 시원하고 쾌적해서 잘 쉬다 갔어요 매장도 널찍해서 할일 하기도 좋구요 직원분도 친절하셨어요~~~~~', 35, 6, 'GOOD', SYSTIMESTAMP);
