INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '친구들이랑 만니서 카페 찾다가 걀국 못 찾아서 여기로 왔는데 맇단 카페가 너무 깨끗하고 너무 예뻐요 사진도 진짜 잘나오고 조명색감도 예쁘고 은근 조용해서 과제나 공부할땨 와도 괜찮을거 같아요!! 디저트도 케이크가 진짜 크림이 느끼하지도 않고 너무 맛있었습니달! 음료도 너무 달지 않고 다 적당하니 맛있고 힘들었눈데 쉬다가 갔습니다!!', 56, 16, 'GOOD', SYSTIMESTAMP);
