INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '한번왔을때 맛잇게마신 음료가 단종되어서 슬프지만.... 그래도 크림이너무맛잇는카페라서 생각나요. 아인슈페너 시켯는데 샷이랑 너무잘어울리네여. 홍대 합정 카페중 숨겨진 분위기좋은 카페', 21, 3, NULL, SYSTIMESTAMP);
