INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '말차아인슈페너 추천입니다. 마셔도 마셔도 나오는 풍부한 말차크림이 진하고 맛나요 ㅜㅜ 3층은 포토맛집이에요. 인테리어 좋고 야외석도 많아요. 합정에 이런 카페가 있었다니..', 37, 3, 'GOOD', SYSTIMESTAMP);
