INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '매장 3층이나 있어서 넓고 쾌적해서 좋아요!! 직원분들도 친절하셔서 더 즐겁게 있다가 갈 수 있는 시간이었어요!! 물론 음료도 맛있습니다 ㅎㅎ', 19, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '골목쪽에 위치한 느좋카페!! 인테리어가 되게 감각적이고 어디에서 찍어도 포토스팟처럼 조명 분위기 인테리어 다 만점이에요 💯 시그니처 커피 2개 친구랑 하나씩 다른 종류로 시켰는데 근래 먹었던 것중에 가장 맛있었어요ㅎㅎ 그리고 보통 다른 개인카페 시그니처 커피보다 양도 많고 커피의 깊은 맛도 진한 것 같습니다😊🥰', 49, 2, 'GOOD', SYSTIMESTAMP);
