INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '우연히 알게 된 카페인데, 커피와 케이크도 정말 맛있지만, 분위기가 정말 좋은 카페입니다. 여유롭고 편안한 느낌의 공간이라, 책 읽기에도 좋고 휴식하기에도 좋네요. 휴일에 자주 올 것 같습니다. 추천합니다.', 8, 1, 'GOOD', SYSTIMESTAMP);
