INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '멧커피에서 아인슈페너 주문했어요! 진한 에스프레소와 부드러운 크림이 조화를 이뤄 고소하고 풍부한 맛이 인상적이에요. 카페 인테리어는 모던하고 세련된 분위기로, 따뜻한 우드 톤과 감각적인 조명이 어우러져 편안하게 머물기 좋아요. 다음에 또 방문할게요~', 42, 10, 'GOOD', SYSTIMESTAMP);
