INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '1층은 우드톤에 좀 아늑하고 3층은 화이트톤에 밝아서 원하는 곳에 앉으면 좋아요. 자리가 넓어서 편하고, 대화하기에도 카공하기에도 좋아요! 아인슈패너랑 잠봉뵈르 둘 다 맛있어요 추천.. 파운드케익도 궁금하네요. 무엇보다 되게 친절하세요 !! 재방문의사 백프로🙆🏻‍♀️', 46, 6, 'GOOD', SYSTIMESTAMP);
