INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '해외디저트 좋아해서 남자친구랑 같이 방문했는데, 인테리어도 깔끔하고 디저트도 기대했던 것보다 정말 많이 맛있었어요 !! 아인슈패너는 투게더맛이라 맛있었구, 디카페인 커피도 일반카페보다 맛잇엇습니당 :)', 128, 22, 'GOOD', SYSTIMESTAMP);
