INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '1층,3층으로 돼있어서 특이하면서 인테리어도 멋있고 커피랑 같이주신 초코디저트도 맛있었고, 여름에 온도조절 잘못하면 엄청 추운데 그렇지않아서 좋았어요 시끄럽지도 않아서 잘 쉬다갑니다🙂', 108, 22, 'GOOD', SYSTIMESTAMP);
