INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '분위기도 조용하고 너무 좋고, 사장님도 넘 친절하세요 아아를 핫아로 시켰는데 잘못시켰다고하니, 얼음이랑 컵 따로 주셨어용 감사합니당', 68, 18, 'GOOD', SYSTIMESTAMP);
