INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '홍대쪽에 공간 넓고 감성있는 카페를 찾다가 정말 우연히 들어갔습니다 직원 분들도 친절하시고, 특유의 감성이 정말 좋네요 홍대쪽 오면 여자친구나 친구와 대화하러 오기 좋습니다 특히 디저트류가 다 맛있는데, 아펠슈트루델을 처음 먹어봤는데 사과파이 같은 걸 좋아하는 제 입맛에 딱 맞았습니다 잘 먹고 쉬다 갑니다', 33, 6, 'GOOD', SYSTIMESTAMP);
