INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '베이글 치즈 찍어먹으면 기절해요… 너무 맛있어서ㅎㅎ 비오는 날 3층에서 밀크티에다 케이크 베이글 먹고 나니까 기분이 다시 좋아지는 비밀🥹 너무 맛있어요ㅎㅎ 추천합니다👍👍 베이글 꼭 먹어봐용 치즈 추가해서ㅎㅎ', 76, 14, 'GOOD', SYSTIMESTAMP);
