INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '멋진 공간과 음악이 있는 장소 합정에서 몇 안 되는 주차가 가능한 카페이고 커피가 아주 맛있습니다! 크림이 엄청 찐하고 달달해요☺️ 3-4년 전인가.. 와 보고 항상 사람이 많아서 오랜만에 온건데 역시나 좋네요', 21, 8, 'GOOD', SYSTIMESTAMP);
