INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '오랑지 에이드가 너무 맛있어서 한입 먹자마자 흡입했습미닷 쪼오오옥 한방컷😎 케이크두 크림이 너무 맛있어서 강추합니다ㅏ!!!!!! 맛있게 먹구 대화두 잘 하고 갑니다~~', 4, 8, 'GOOD', SYSTIMESTAMP);
