INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '미니생딸기케이크가 정말 맛있었어요🥰 일반 딸기케이크랑은 맛이 달라요. 딸기케이크는 딸기케이크인데 치즈케이크 맛이 살짝 나는 게 무지 맛있습니다. 후회하지 않으실 선택입니다👍 인테리어도 예쁘고 3층에 공간이 따로 있어서 쾌적해요~😊', 23, 5, 'GOOD', SYSTIMESTAMP);
