INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '안도 깔끔하고 너무 예뻐요!! 3층 공간에는 엘리베이터타도 올라가면되서 편하게 음료가지고 푹 쉬고 이야기도하면서 쉴 수 있었어요~~🥰🥰', 62, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '오스트리아 디저트 아펠슈트루텔과 아인슈페너를 먹었습니다. 주말 선착순 이벤트로 100원으로 이것들을 누렸는데요, 이래도 되나 싶었습니다, 감사합니다 :) 아펠슈트루텔은 처음 먹어보는 유럽으로 데려가주는 이국적인 맛이었는데, 고급적인 애플파이라고 설명할 수 있겠습니다. 안쪽에 사과와 포도로 보이는 과일 조각과 시나몬이 더해져 뱅쇼를 먹는 듯이 달콤하고 향기로운 맛이 납니다. 멧커피 이곳은 공간이 많고 아름다운 오브제들로 둘러쌓여 있습니다. 음악도 너무 좋고, 멋진 취향이 쌓여 이렇게 제공되고 있는 점이 멋지고 감동적이며, 이 공간에 있는 사람들에게 에너지를 주는 것 같습니다, 최고입니다♡', 15, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '완전 느좋 카페🥰 자리도 완전 넓고 삼층으로 가는 엘레베이터도 있어요!!! 제가 똥손이지만 분위기도 너무 좋고 사진도 딱 잘나와요..🫶🏻 주차도 두대정도 자리 있더라구요!! 차있으신분들 홍대에 주차할데 잘 없는데 멧커피 강추입니다! 중요한 커피맛! 차종류도 너무 맛있고 커피도 맛있고 빵도 왕맛! 아펠슈르델 왕맛…. 다음에 와서 아메리카노도 마셔봐야겠어용💗', 85, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PARKING');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
