INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '공간이 넓어 보여서 방문하게 되었어요. 그런데 진짜로 넓고 쾌적하네요. 1층과 3층이 느낌이 좀 달라요. 1층은 아늑한 초록초록한 느낌이면 3층은 채광도 많이 들어오고 따뜻한 느낌이에요 커피도 고소하니 맛있고, 파운드케이크도 부드러우면서 상큼하네용 굿! 영수증리뷰이벤트중인데 미니초코케이크도 주십니당 생크림이 달아요.. 이벤트용 케이크까지 맛있어요... 🥰', 56, 14, 'GOOD', SYSTIMESTAMP);
