INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '아인슈페너, 오렌지에이드, 카페라떼, 잠봉뵈르 샌드위치 주문해서 먹었는데 맛있었어용 :) 카페 시원하고 좌석도 많아서 마음에 듭니다 !', 4, 9, 'GOOD', SYSTIMESTAMP);
