INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '오랜만에 만난 친구랑 방문했습니다! 걸어가다가 발견한 카페인데 인테리어도 좋고 디저트도 맛있었던 것 같아요~ㅎㅎ 말차파운드케익이랑 뜨거운얼그레이티,아이스아메리카노 시켰어요 파운드케익 오랜만에 먹는데 엄청 맛있더라고요. 위에는 말차맛 초코로 덮여있고 파운드케익은 계란향이 솔솔나는 고소한 케익이였습니다. 계란과자 맛이 나더라고요!!맛있고 행복해지는 맛이였어요 얼그레이티는 좀 상상할 만한 수준이였고 아메리카노는 못 먹어봤습니다. 전체적으로 통창 하늘하늘한 화이트 인테리어이고 녹색이 시그니터 색깔인것 같더라고요~너무 잘 어울렸어요! 생초코는 선착순 서비스인데 생초코 3개 들어있었어요 생초코중에 파베초콜릿 유명한데 그거랑 맛이 비슷했습니다 ㅎㅎ 감사히 잘 먹었습니다!', 25, 9, 'GOOD', SYSTIMESTAMP);
