INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '길가다 그냥 들렸는데 디저트 종류도 많고 음료도 맛있어요..!! 게다가 아펠슈트루델?! 사과파이 같으면서도 페스트리 같은 디저트가 진짜... 👍 옆에 휘핑도 같이 주시는데 버무려서 한 입 먹으면 너무 좋아요🥰 행복해지는 맛', 19, 3, 'GOOD', SYSTIMESTAMP);
