INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '카페 분위기가 너무 좋아요!! 😆인테리어도 너무 멋지고 자리도 많고 야외자리도 있어요. 대표메뉴 아인슈패너도 너무 맛있어요!!👍👍', 8, 0, 'GOOD', SYSTIMESTAMP);
