INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '분위기도 좋고 주차도 되고 이벤트도 하고 오기좋은공간이예요 !! 3층까지 있어서 자리도 넉넉하고 넘 좋습니다,, 벌써 두번째방문입니다', 37, 1, 'GOOD', SYSTIMESTAMP);
