INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '합정에서 처음 와본 ''멧커피'' !! 우드톤 공간에 테이블 간격도 넓고 선곡도 최고.. 완전 우리 스타일이다.. 디저트 직접 만드는 공간도 보이는데 다음에는 꼭 배고플때 방문해서 먹어봐야겠다 커피도 너무 맛있음!!!', 10, 5, 'GOOD', SYSTIMESTAMP);
