INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '지나가다 들어왔는데 분위기가 너무 좋아요! 커피도 맛있고 딸기 듬뿍 들어간 케이크도 넘넘 맛있어요! 제 최애 카페 될 것 같아요🥰❤️', 18, 5, 'GOOD', SYSTIMESTAMP);
