INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '합정역 근처 쾌적한 카페에요. 좌석이 넓어서 널널하게 쉬다 갈 수 있고 디저트가 맛있어요! 우연히 방문했는데 재방문 할 것 같습니다!', 59, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '딸기케이크를 먹고싶어서 왔는데 품절이어서 넘 아쉬웠어요 ㅜㅜ 그래두 얼그레이케이크랑 레몬파운드 먹었는데 맜있었어요~~ 피치우롱차는 전혀 달지 않으니 참고하세용', 36, 4, NULL, SYSTIMESTAMP);
