INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '우연히 발견한 카페인데 너무 대만족입니다!! 분위기도 좋고 저는 혼자왔지만 대화하러오기에도 너무 좋을 것 같아요 그리고 특히 말차크림라떼가 기대이상으로 너무 맛있고 양도 많아서 놀랬어요!!! 꼭 한 번 드셔보세요! 매장도 3층까지 있어서 엄청 넓고 화장실도 청결해요! 잘 머물다 갑니다♡', 85, 11, 'GOOD', SYSTIMESTAMP);
