INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '인테리어도 너무 이쁘고, 음료와 디저트가 너무 맛있어요!! 개별 주차공간도 따로 마련되어 있어서 너무 편리한 것 같아요!! 👍👍', 86, 16, 'GOOD', SYSTIMESTAMP);
