INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '디저트도 음료도 빠지는 거 없이 진짜 맛있고 가격도 괜찮고 공간도 예뻐요 특히 3층이 채광도 좋고 인테리어도 예뻐서 사진찍으면 진짜 잘나옴 데이트 추천해요!!!', 77, 13, 'GOOD', SYSTIMESTAMP);
