INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '3층까지 올라가는 엘베가 있어서 신기한 구조입니다! 커피 종류가 막 많은건 아니지만 기본적인건 다 있고 디저트가 다양해서 좋았습니다 ㅎㅎ 촬영스튜디오 처럼 깔끔하고 이쁜 인테리어라 사진도 잘 나올 것 같아요~~', 75, 18, 'GOOD', SYSTIMESTAMP);
