INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '분위기도 너무 좋고 조용하고 인테리어 깔끔해서 합정 온다면 또 재방문 할 거 같아요💚 특히 생크림딸기케이크가 진짜 존맛 ㅠ 강추합니당 아아메도 고소하고 맛나여!!!', 31, 1, 'GOOD', SYSTIMESTAMP);
