INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '커피도 너무 맛있고 분위기도 조용하니 너무 좋고 디저트도 다 맛있어용 ! 특히 슈트루델은 파는곳이 많이 없는데 여기 있어서 너무 좋아용 ~ 슈트루델 꼭 드세용용', 88, 14, 'GOOD', SYSTIMESTAMP);
