INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '말차크림생딸기라떼가 진짜 맛있어요.. 딱 제가 좋아하는 맛….. 말차크림이 진짜 맛있고 밑에 딸기도 달달상콤하니 맛있어요 다시 올 의사 100%😁😁😁 말차🍵크림생딸기🍓라떼 또 먹으러 올 거예요!!', 46, 6, 'GOOD', SYSTIMESTAMP);
