INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '합정에서 어떤 카페를 갈까 찾던 중 우연히 들르게 된 멧커피 입니다 인테리어도 매우 고급스럽고 3층까지 이용이 가능하여 공간도 아주 넓고 쾌적합니다 맛있는 케이크도 있어서 좋은거 같습니다', 36, 0, 'GOOD', SYSTIMESTAMP);
