INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '아메리카노도 괜찮은데 크림카라멜이 달달하면서 너무 맛있었어요 !! 시그니처가 여러가지 있던데 다음에 또 방문해서 하나씩 먹어볼 생각이에요〰️〰️ 케이크는 살짝 비싸긴 하지만 크림이 가벼우면서 달달하고 안에 딸기가 많이 들어있어서 맛있더라구요💗', 36, 2, 'GOOD', SYSTIMESTAMP);
