INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '좋아하는 분위기와 적당히 초록초록하고 우디한 인테리어, 다른 곳에서 먹어보기 힘든 메뉴들이 너무 마음에 들어요. 다른 곳에 있다가 17분 걸어왔는데 다음 번에 20분 걸어야한다고 해도 방문할 것 같아요💚 일하러 왔다가 힐링하고 갑니다!', 35, 5, 'GOOD', SYSTIMESTAMP);
