INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '2층까지있어서 좌석이 코ㅔ적헤요! 각 테이블마다 콘센트가 하나씩 있다는 점이 좋았어요. 저는 말차라테를 마셨는데 파유더맛이 아니라 부드러운 말차맛이 나서 너무 맛있게 마셨습니다! 직원분이 친절히 안내해주셔서 서비스도 만족스러웠어요.  종종 올듯하네요😻', 8, 4, 'GOOD', SYSTIMESTAMP);
