INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '두번째 방문인데 매장이 분위기 있고 예뻐요! 답답한 느낌이 드는 카페를 선호하지 않는데 그런 느낌없이 편안해서 생각나서 오게 되었네요:) 디저트는 저번에도 맛있었는데 여기 디저트가 제 스타일이에요ෆ 저랑 비슷한 취향이신 분들은 추천입니다:)', 3, 0, 'GOOD', SYSTIMESTAMP);
