INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '합정홍대카페멧커피 + 아메리카노 #홍대커피 #홍대카페 #합정카페 #멧커피 #카페추천 아메리카노 너무 맛있고 분위기가 좋아요!!👍👍', 90, 14, 'GOOD', SYSTIMESTAMP);
