INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '분위기 너무 좋아요 생각보다 넓어보이는데 사람들이 많아서 자리가 부족해요 ㅋㅋ 그래도 빽빽하지 않은 현재가 더 좋아요 커피 너무 맛있구 시그니처 인정 ㅠㅠ', 2, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '카페 인테리어 분위기 맛 뭐 하나 빠지는 거 없이 완벽.. 커피랑 디저트 너무 맛있고 카페도 넓어서 홍대 카페는 여기도 정착합니다.. 제발 여기 와주세요', 409, 39, 'GOOD', SYSTIMESTAMP);
