INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '음료도 맛있고 매장 넓고 분위기 좋아요. 사진찍기 굿굿. 화장실도 깔끔스~ 3층 이용은 엘레베이터 있고 네이버주문도 가능해서 편해요.', 47, 2, 'GOOD', SYSTIMESTAMP);
