INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '너무 아늑하고 좋은 곳이에요 유명해지지 않았으면 좋겠을정도로..!!! 작업하러 왔는데 데이트로도 좋을 것 같아요 직원분들도 무척 친절하십니다🥹 최애카페 등극', 96, 20, 'GOOD', SYSTIMESTAMP);
