INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '테라스 맛집입니다❤️ 날씨가 좋아서 근처 돌아다니다가 우연히 들어왔는데 너무 만족해요. 커피를 마셔서 차 시켰는데 종류도 많고 민트차 강추해요. 디저트도 많이 달지 않고 맛있어요. 다음에 오면 다른 디저트듀 먹어보려구요😊', 45, 6, 'GOOD', SYSTIMESTAMP);
