INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '한 달에 두번은 꼭 방문하는 최애 카페입니다,,🥹 올때마다 인당 1슈투루델을 먹고있어요! 정말 맛있기때문입니다 ㅠㅠ 모두 드셔보시길👍 앞으로도 자주 올게요 :)', 43, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '저의 아지트... 잠봉뵈르가 넘넘 맛있어요 👍🏻 직원분들도 친절하시고 공간도 넓어서 대화하기 좋아요 특히 햇빛이 들어오는 모습이 예뻐서, 화창한 낮에 여유롭게 커피 마시면 힐링 그자체... 자주 올게요 💚', 13, 2, 'GOOD', SYSTIMESTAMP);
