INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '인테리어가 차분하고 따뜻해서 다양한 용도로 방문하기 좋아요! 진동벨 울려서 갔는데 음료만 준비된 상태였고 서서 기다렸어요. 그러다 초코 파운드 케이크를 트레이에 떨어뜨리셨는데 그냥 집게로 다시 그릇에 담고 서빙하시더라고요! 생각해보니 직원분 손으로 쳐서 트레이에 떨어진거였는데 사과도 안하셨고 적절한 대처가 아니라고 생각돼요. 누구도 남의 손에 닿은 음식 먹고싶진 않으니까요 ㅎㅎ', 84, 14, NULL, SYSTIMESTAMP);
