INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '넓은 매장이라 친구들과 대화하기 편안하고 나중에 여러명이서 모임하기도 좋을 거 같아요! 커피도 맛있고 인테리어도 감각적인데 쾌적해서 자주 올 거 같아요! 홍대 맛집입니당', 21, 1, 'GOOD', SYSTIMESTAMP);
