INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '분위기가 압도적이에요.. 3층까지 있는데 3층은 사람이 많이 없어서 대화하기 좋아요! 시켰던 허브차도 향긋하니 맛있었어요 재방문 꼭 하고싶습니다ㅎㅎ', 10, 6, 'GOOD', SYSTIMESTAMP);
