INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '합정 근처에 이렇게 예쁜 대형카페가 있는줄 몰랐어요ㅠㅠㅜ 음료도 너무 맛있구 자리도 많아서 좋아요!!! 다음에 또 오고 싶어서 바로 저장해놨습니다ㅎㅎㅎ', 76, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '합정에서 조용하면서 분위기 좋은 카페 찾다가 왔어요~~ 음료와 디저트도 다양하고, 인테리어도 예뻐요ㅎㅎ 합정 홍대 느좋카페 추천합니다아~!! #홍대카페 #합정카페 #멧커피 #카페추천 #딸기케이크', 21, 0, NULL, SYSTIMESTAMP);
