INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '1층, 3층으로 공간이 넓고 1층은 다크+정원한 느낌으로 분위기 좋구, 3층은 공간이 러블리해요. 더위에 지쳤는데 상큼한 음료랑 달달한 디저트 덕에 힘나요', 73, 13, 'GOOD', SYSTIMESTAMP);
