INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '친구랑 공부하구 얘기하러 왔어요!! 분위기 아늑하고 디저트랑 음료도 너무 맛있어서 행복했습니다~ㅎㅎ 재방문 의사 완전!! 있습니다!!😋', 3, 3, 'GOOD', SYSTIMESTAMP);
