INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '벌써 세번째 방문중인 멧커피에요. 멧커피는 음료도 맛있는데 베이커리류가 진심으로 맛있어요. 항상 파운드케이크 먹다가 오랜만에 왔더니 아펠슈투루델(사과파이)이 나왔더라구요!!! 유럽에서 유학하면서 진짜 즐겨먹던 디저트였는데 세상에. 얼마나 반갑던지... 맛도 현지랑 거의 비슷해서 진짜 깜짝놀랐어요. 멧커피 사장님께서 수제로 만들어주시는 아펠슈투루델 꼭 맛봐야해요. 말차크림커피 마시고 너무 맛있어서 수제밀크티도 주문했는데 진짜 오후 주말에 이보다 더 완벽한 음료는 없어요. 따스한 햇살 쬐면서 마시는 밀크티 너무 맛있어요. 밀크티는 사장님께서 아침마다 찻잎을 우려서 우유랑 섞은다음에 냉침로 숙성해서 액기스만 추출해서 만드신다고 해요.. 밀크티에 올라간 크림이 진짜 맛있어요 ㅠㅜ 제발 모두가 맛보면 좋겠어요!!!', 105, 25, 'GOOD', SYSTIMESTAMP);
