INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '원래 아메리카노만 먹는데 라떼가 너~무 맛있어  보여서 먹어보니까 성공적... 🩷 생크림이랑 같이 먹는 아펠슈투루델이 넘넘 취향이라 이거 먹으러 다시 올듯 ㅠㅠ 3층 인테리어도 너무 예뻐요 🥰', 41, 7, 'GOOD', SYSTIMESTAMP);
