INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '분위기도 차분하고, 평일에 방문했더니 사람도 없어서 더 좋았어요 !! 🍓🤍🤍 미니 생딸기 케이크도 부드럽고 맛있습니당 ㅎㅎ 오시는 분들은 꼭 드셔보시길 :)', 59, 13, 'GOOD', SYSTIMESTAMP);
