INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '인테리어가 정말 예뻐요! 플레이리스트가 매장이랑 너무 잘 어울려요 디저트도 꾸덕하고 맛있고 음료도 맛있네요! 서울에 있는 곳 치고 가격도 너무 저렴해서 좋았어용', 21, 3, 'GOOD', SYSTIMESTAMP);
