INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '합정 돌아다니다 인테리어가 너무 이뻐서 들어왔어용!커피메뉴가 다양하고 넘 맛있어 보여서 뭐먹을지 친구랑 한참 고민했어용~ 결국은 아인슈페너랑 크림카라멜 픽했습니당 생짤기초코케이크도 짱 귀엽고 완전 맛있어용~~~', 16, 4, 'GOOD', SYSTIMESTAMP);
