INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '여기만한곳이없어용 주차도 되고 커피도맛있고 편히 즐기면서 야외테라스도있어서 넘 좋아영 여유즐깁시당 그리고 디저트 강추!!달달하니  귀여운거어케먹어용 근데 맛있어서 순삭', 32, 0, 'GOOD', SYSTIMESTAMP);
