INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '첫 인상부터 너무 좋은 카페입니다. 네이버지도 앱에서 ''대형카페'' 검색하니 주변에 나와서 처음으로 방문했습니다. 분위기 너무 좋고 의자도 편하네요^^ 1층과 3층 모두 넓은 공간이 있고, 곳곳에 사진찍을 스팟도 넘쳐납니다. 시그니처 메뉴 한개를 백원에 맛볼 수 있게 해주셔서 너무 좋네요. 생크림이 조금 묽게 나와 다시 해주신다는 섬세함까지 감사한 곳입니다. 다음엔 아내와 같이 오겠습니다^^', 50, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '친구 생일이라 점심먹고 오후 세시가 다되어 들린곳이예요.오호 이렇게 이쁘고 좋은 카페를 이제야 발견하다니요. 음료가 너무 이쁘고 정성스럽게 나온것도 감동이지만,여직원분 친절함에 너무 기분 좋아졌어요. 실내가 이뻐서 이곳저곳 사진찍고 영상남기고 생일인 내 찐친 오늘 너무 행복해하니 기분 더 좋아집니다. 조만간 또 갈게요!', 87, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '짜지 않고 맛있어요~~~!! 잠봉뵈르도 그렇고 피자빵도 재료가 빵빵해서 좋아요! 매장 분위기도 세련되고 조용하고 좋습니당! 재방문 의사 있어요👍🏻👍🏻', 30, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '너무 맛있어욯ㅎㅎㅎ 카페 분위기도 너무너무 좋구요! 신메뉴 피자도 정말 맛있네요❤️❤️❤️❤️👍🏻👍🏻👍🏻👍🏻 또 올게요~~~~~!', 53, 14, 'GOOD', SYSTIMESTAMP);
