INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '요즘에 말차에 너무너무 빠져서 여기에 짝꿍 데리고 와봐야겠다 생각했었는데 마침 오늘 와보니 너무너무 맛있어요ㅠㅠㅠㅠㅠㅠㅠㅠㅠ 잘 먹고갑니다앙', 12, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '초코라떼 진하고 맛있고 티도 과일향이 너무 좋아서 추천드려요!!☺️☺️ 그리고 아펠슈트루델은 파이층이 바삭하면서도 쫀득해서 너무 맛있었어요ㅠㅠ 사과도 아삭거리고 달달해용🍎🥧 옆에 있는 크림도 산뜻하고 신선한 우유맛이 제대로 나서 잘 어울렸습니당😋 분위기도 조용하고 노래도 좋아서 책읽거나 작업하기도 좋은 것 같아요 꼭 방문 추천합니당👍🏻👍🏻', 74, 13, 'GOOD', SYSTIMESTAMP);
