INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '배부르게 밥을 먹고 문을 연 카페를 찾았는데 세상에 이렇게 분위기 있고 조용한 예쁜 카페가 있어서 정말 좋았어요 우유를 못 먹는 저에게 오트밀 우유 베이스 변경도 있어서 말차 라테도 맛나게 먹을 수 있었습니다!! 설날 당일 문열어주셔서 감사합니다~!', 25, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '와 말차러버로써 말차크림커피랑 말차 파운드케이크만 보고 왔는데 매장 분위기랑 맛에 취하고 갔습니다...💚 사실 첨엔 그렇게 기대하지않고 파운드케이크가 맛있다고 해서 방문했는데 매장 분위기가 엄청 편안하면서 무드있어서 놀라고 (예상과는 달랐음 인테리어 기대 안함ㅎㅎ) 두번째론 엄청 멋지신 직원분이 만들어주셔서 너무 좋았고💖 마지막으론 젤 중요란 말차 파운트케이크랑 말차크림커피먹고 왜 리뷰에 재방문 맛집이라 하는지 알았음👍🏻👍🏻👍🏻 장사가 잘되는지 원래 없둔 3층까지 오픈했다는데 담엔 거기가서 먹어봐야겠음용🐰✨🌷 쨋던! 여기 홍대 흔치않은 디저트 맛집 인정!!🍀', 30, 9, 'GOOD', SYSTIMESTAMP);
