INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '메뉴가 다양하고 특히 제가 좋아하는 말차랑 딸기 관련 종류가 많아 너무 좋았어요ㅠ 분위기도 좋고 의자가 편해서(매우 중요) 앞으로도 종종 찾을 것 같아요😋', 4, 2, 'GOOD', SYSTIMESTAMP);
