INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '홍대에 오랜만에 왔더니 이런 예쁜 카페가 생겨있네요 베이커리 디저트도 있고 인테리어도 너무 예뻐서 좋은것 같아요 커피도 너무 맛있습니다.', 33, 10, 'GOOD', SYSTIMESTAMP);
