INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '뷰가 미쳤다~~  야외좌석 뷰가 트여서 너무 편안하고좋아요 . 좌석 자체도 불편히지않고 분위기짱입니다. 아인슈페너도 맛나영❤️', 90, 16, 'GOOD', SYSTIMESTAMP);
