INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '지나가다가 우연히 들르게 된 곳인데, 매장도 넓고 탁 트여서 좋았어요! 특히 낮에 오니까 완전 햇빛 맛집이네요!! 음료도 빠르게 나왔고, 디저트도 맛있었어요! 바 테일블에는 하단에 콘센트도 있어서 다음에 작업할때도 와보고 싶은 곳이에요!!', 25, 6, 'GOOD', SYSTIMESTAMP);
