INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '인테리어가 참 멋져요! 1층은 우드랑 그린 위주라면 3층은 모던하게 블랙&화이트 위주 인테리어라 다른 모습을 볼 수 있었네요 생각보다 더 넓은 데스크와 공간에 편하게 방문했다 갈 수 있어 좋았어요~', 77, 13, 'GOOD', SYSTIMESTAMP);
