INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '멜랑슈와 아펠슈트루델을 아시나요? 라떼에 부드러운 우유거품을 올린 오스트리아식 커피 멜랑슈. 이곳에서는 달달하게 아이스크림까지 올립니다. 그리고 종잇장처럼 얇디 얇은 겹겹의 페이스트리 안에 사과와 건포도를 넣어 굽고, 생크림을 얹어 먹는 아펠슈트루델. 오스트리아로 여행 가본 적 있는 친구와 함께 왔습니다. 저는 멧커피만 있다면 서울에서 빈의 정취를 느낄 수 있을지 모르겠다는, 다소의 억견이 담뿍 들어간 생각이 들었습니다. 그것은 멜랑슈에 부드러운 아이스크림이 담뿍 들어갔고, 또한 아펠슈트루델에 생크림을 듬뿍 묻혔기 때문일 터입니다.', 66, 16, 'GOOD', SYSTIMESTAMP);
