INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '말차크림커피랑 생딸기 케이크 강추드려요!! 친구들 모두 인생 딸기 케이크라고 했어요!! 너무 맛있고 공간도 넓고 깨끗해서 추천드립니다!!', 51, 14, 'GOOD', SYSTIMESTAMP);
