INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '멧커피 처음 방문해보았는데 매장이 넓고 쾌적하네용 3층에도 공간이 있어서 너무 좋아요 분위기도 넘 좋구요~ 😋 딸기생크림케이크가 달달하고 맛있어요 디저트 최고:)', 72, 16, 'GOOD', SYSTIMESTAMP);
