INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '넓고 시설도 깔끔합니다! 무엇보다 친절하게 응대를 해주셔서 기분좋게 커피랑 디저트를 먹고 나올수 있었습니당~ 다음에도 또 올게요:)', 49, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '<합정 홍대 카페 멧커피 아펠슈트루델, 생딸기케이크> 너무 맛있어요 특히 생크림이 부드러워요 빵과 조화롭게 어울리고, 아펠슈트루델이라는 생소한 디저트가 생각보다 너무 맛있어요 애플파이와 생크림을 같이 먹는맛인데 사과 알알이 살아있어요 강추해요 #홍대카페 #합정카페 #멧커피 #카페추천', 16, 9, 'GOOD', SYSTIMESTAMP);
