INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '음료 너무 맛있었고 케이크도 정말 맛있었습니다!! 조용하고 넓어서 대회하기도 좋았던 것 같아요 다음에 합정 오면 재방문하겠습니다~!', 25, 2, 'GOOD', SYSTIMESTAMP);
