INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '친구들이랑 합정 왔다가 우연히 들렀는데 카페 분위기도 좋고 디저트들이 너무 귀여워요~~ 내부 매장 안도 넓어서 여럿이 오기 좋아요!', 25, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '카페 어디갈지 찾아다니다가 이 곳을 발견해서 들어왔는데 일단 카페가 엄청 넓고 분위기가 좋았어요 👍 친구랑 무난하게 밀크티가 괜찮을거 같아서 시켰는데 먹어보니까 생각한 이상으로 너무 맛있었어요오!! 딸기케이크도 부드럽고 달달해서 맛있었어요😋', 269, 61, 'GOOD', SYSTIMESTAMP);
