INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '슈트르델 맛있어서 하나 더 시켰어요~! 커피도 정말 맛있고 대화나누기도 좋은 공간입니다. 3층 공간은 스튜디오같이 더 멋지더라구요👍', 46, 8, 'GOOD', SYSTIMESTAMP);
