INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '김마미? 피자 이벤트하는데 맛나더라구요. 커피랑 밀크티도 먹었는데 맛났어요. 대화도 공간이 넓직해서 이야기하기 너무 좋았습니다. 다음에 또 올게용 ㅎㅎ', 16, 10, 'GOOD', SYSTIMESTAMP);
