INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '레몬에이드에 샷추가 가능하냐고 물었는데 흔쾌히 가능하다고 하셔서 너무 좋았습니다... 친절한 사장님과 어딜 찍어도 스튜디오같은 분위기가 친구랑 와도 좋고 데이트로 와도 좋을 거 같아요', 39, 10, 'GOOD', SYSTIMESTAMP);
