INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '두번째 방문이예요. 지난번 와보고 느낌이 좋아서 친구델꼬 재방문 했어요. 역시 분위기 좋구요.사진찍기 좋아라 하는 친구 아주 신나게 사진 찍습니다ㅎㅎ 지난번 방문했을때 리뷰를 썼는데 사장님이 컵을 친구꺼 까지 두개나 주셨어요. 완전 감사하구요 사업 번창하세요. 또 갈게요!', 0, 10, 'GOOD', SYSTIMESTAMP);
