INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '인테리어도 이쁘고 커피도 맛있어용!!! 추운날인데 가게 완전 포근하고 넓고 좋습니당 마지막사진은 멧커피에서 찍은 무지개하투❤️🧡💛💚💙💜', 45, 0, 'GOOD', SYSTIMESTAMP);
