INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '기본적으로 커피가 맛있고, 친절합니다. 종류 다양한 메뉴도 차별화되어 고르는 맛이 있습니다. 주말에도 일찍 오픈하는 홍대카페라서 맘에 드네요. 새로 오픈한 3층은 스튜디오빌린 것처럼 넓고 아늑해서 조만간 지인들 데리고 재방문하고 싶어요. 디저트도 상당히 먹음직스러워서 맘에 듭니다.', 34, 3, 'GOOD', SYSTIMESTAMP);
