INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '매장도 넓고 직원 분들이 친절해요😊 베이커리류도 카페에서 직접 만드시더라구요. 1,3층 있고 테라스도 있어서 다음에 날씨 좋을 때 또 오려구요! 크림커피 시켰는데 크림이 진하고 맛있어요!!!', 71, 13, 'GOOD', SYSTIMESTAMP);
