INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '인테리어가 아늑하고, 자리도 널찍해서 오래 앉아 있어도 편하더라고요. 직원분들도 친절해서 기분 좋았고, 무엇보다 음악이 너무 시끄럽지 않아서 좋았어요.', 102, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '디저트 엄청 저렴한데(리뷰이벤트로 0원.!!! 그리고 신메뉴 이벤트로 1000원) 너무 맛있어요!! 매장 3층 엄청 넓고 통유리라 햇살도 잘 들어오고 분위기 넘 좋아요~🥰✨', 46, 9, 'GOOD', SYSTIMESTAMP);
