INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '매장은 넓어서 대화하기 좋은데 1층에서 혼자 트레이 들고 3층까지 올라가는게 좀 불편해요. 따뜻한 아메리카노 주문했는데 아이스로 주셨지만 그냥 귀찮아서 마셨어요.', 86, 17, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '친구랑 오랜만에 합정에서 분좋카 찾아 방문해 봤어요! 둘다 말차 좋아해서 시그니쳐인 말차라떼, 말차아인슈페너 주문해 먹었어봤는데 부드러운 말차맛 크림이 커피랑 잘 어울려 맛있었습니다. 공간 자체가 여유있고 편안한 분위기여서 2시간 동안 재밌게 수다 떨고 갑니다:)', 97, 23, 'GOOD', SYSTIMESTAMP);
