INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '아이스 아메리카노랑 얼그레이 케이크, 미니 생딸기 초코 케이크 먹었는데 다 맛있었습니다. 아메리카노는 산미랑 쓴맛 밸런스가 잘 맞아서 디저트랑 먹기 좋았고, 얼그레이 케이크는 홍차 향이 은은하게 나면서 크림이랑 잘 어울렸어요. 미니 생딸기 초코 케이크는 초콜릿이 진하면서도 딸기가 상큼해서 조합이 좋았습니다. 가게 분위기도 아늑하고 편해서 편하게 쉬다 갈 수 있었어요. 다음에 또 오고 싶네요.', 41, 7, 'GOOD', SYSTIMESTAMP);
