INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '디저트 이름이 특이했는데 정말 맛있었어요! 공간도 넓고 카운터랑 분리가 되어있어서 편하게 머무르다 갈 수 있었습니다ㅋㅋ 앞으로도 종종 이용할 것 같아요!', 61, 15, 'GOOD', SYSTIMESTAMP);
