INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '1층, 3층으로 나눠져 있는데 3층은 자리가 더 예쁜대신에 리유저블컵으로 줘요! 말차아인슈페네 맛있고, 리뷰이벤트하면 미니케이크도 주세요', 50, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '합정에서 이보다 디저트가 맛있는 카페는 아직 보지 못했습니다. 음악 소리가 살짝 크기는 한데, 도란도란 이야기할 만합니다. 압펠슈트루델은 꼭 먹어보세요! 엄청 맛있는데 잘 알려져 있지 않은 디저트네요. ㅜㅠ', 16, 6, 'GOOD', SYSTIMESTAMP);
