INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '예전에 방문한 적이 있는데 분위기도 너무 좋고 커피도 맛있어서 재방문했어요. 그 사이에 3층도 오픈하고 공간이 더 예뻐진 것 같습니다. 주차도 가능하고, 작업하거나 공부하기에도 좋아요', 59, 12, 'GOOD', SYSTIMESTAMP);
