INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '맛이나 위생 이슈로 커피는 머그잔에 맛있는 원두가 있는 곳으로 가서 먹는 편이예요:)  세련된 그린 컬러의 외관이 눈에 띄어 들어갔는데, 주문해 먹은 아메리카노와 레몬 파운드 케잌이 딱 생각하던 제일 맛난 맛이더라고요! 말차 커피는 말차와 커피의 조화가  달지도 않고 크리미해서 너무 맛있었어요! 특이하고 맛있어 보이는 메뉴가 많아서 도장깨기 하러 또 방문해야겠어요!', 22, 0, 'GOOD', SYSTIMESTAMP);
