INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '제가 사진을 잘 못찍어서 그런데 음료랑 디저트 정말 예쁘게 담아주시고 자리도 많고 의자도 편하고 무엇보다 진짜 맛있어요 멜랑슈와 아펠슈투루델 정말정말 맛있어요 꼭 드셔보세요~', 38, 3, 'GOOD', SYSTIMESTAMP);
