INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '커피 안먹는 편인데 말차크림커피가 넘 맛있게 생겨서 도전했습니다 대성공! 고소하고 쌉싸름 맛있어요! 근처 저녁 약속시간까지 시간이 떠서 혼자 시간때우려고 들어간 카펜데 인테리어도 예쁘고 분위기도 좋아서 만족스러웠습니당 직원분도 대박 친절🫶 담에 또 와서 디저트도 먹어보랴구용', 81, 18, 'GOOD', SYSTIMESTAMP);
