INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '오자마자 너무 기분이 좋아졌던 카페였던 것 같습니다. 비도 와서 조금 축 쳐져있었지만 여기 카페는 그 나름의 분위기도 있네요! 디저트도 맛있습니다 ㅎㅎ', 19, 6, 'GOOD', SYSTIMESTAMP);
