INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '여자친구랑 분위기좋은 카페를 찾다가 발견해서 들어왔어요. 아늑하고 쿠키 향이 좋아요. 데이트하기 분위기가 정말 좋습니다! 조용하고 분위기좋은 카페 찾는 분들에게 추천합니다', 11, 1, 'GOOD', SYSTIMESTAMP);
