INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '분위기도 좋고 매장도 진짜 넓고 깨끗해요! 빵이랑 케이크도 너무 맛있고 혼자 혼기도 너무 좋은거같아요! 평일에 혼자 책읽기 딱좋은 카페에요~ 조용하고 너무 맘이들어요', 3, 10, 'GOOD', SYSTIMESTAMP);
