INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '커피도 맛있고 디저트도 맛있습니다! 매장도 넓어서 편하게 앉아있을수있어요. 메뉴종류도 많고 다음에 또 오겠습니다!!리뷰이벤트도 하고있어요!!', 30, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '전에는 밤에 한번 방문하고 분위기가 좋아서 이번에 한번 더 방문해본건데 낮이 더 햇빛 받아서 그런지 분위기가 넘 좋네요:) 같이 방문해도 혼자 방문해도 좋은 곳 같아요! 음료도 디저트도 정성 들여 만들어주신게 보여서 넘 만족하고자주 방문하겠습니다', 20, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '친구와 걷다가 우연히 들어왔는데 뭔가 분위기가 (음악도^^)따뜻한 느낌이예요. 음로도 다 맛있어 보여서 선택하는데 오래 걸렸어요.ㅎ 오렌지에이드로 선택했는데 심하게 달지않아서 좋네요', 68, 11, 'GOOD', SYSTIMESTAMP);
