INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '원래 이런카페는 양 완전 적은데 여긴 많아서 좋아요. 그래서 가격이 비싸보이지만 양 생각하면 가격 적당한거가틈 화장실도 진짜 뜨끈뜨끈하고 조음', 2, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '시간 때울 겸 들어온 곳인데 너무너무… 좋아요 아늑하고 따뜻한 감성에 맛있는 커피까지.. 최고입니다 매장도 넓어서 이야기하기도 좋아요', 61, 16, 'GOOD', SYSTIMESTAMP);
