INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '비도오고 근처에 카페 어디갈까 하다가 오게됬는데 분위기도 너무 좋고 장소도 넓어서 편하게 있을수 있어요 케이크도 맛잇고 음료도 맛잇어요 다음에 또 다시 방문하고 싶어요╰(*´︶`*)╯♡', 29, 9, 'GOOD', SYSTIMESTAMP);
