INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '선글라스를 잃어버렸는데, 너무나 친절히 확인해주시고 ㅠㅠ 씨씨티비도 봐주신다고 ... 너무 감사합니다 ... 커피도 넘 맛잇고 디저트 최고에요', 19, 1, 'GOOD', SYSTIMESTAMP);
