INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '연유라떼 핵핵핵 존맛탱입니다!!! 진하고 맛있어요!!!!!!!!! 눈이많이와서 우연히 왔는데 핵 존맛탱... 행복합니다... 연유라떼 시키고 밍밍한 곳 많이봤는데 여긴 진해서 맛있어요!!! 디저트도 미쳤어요 완전 부드럽고 핵 존맛탱 진짜로;;;; 저 퍽퍽한거 너무 싫어해서 파운드 안좋아하는데 여긴 핵 맛도리입니다 디저트며 커피며 다 존맛탱 ;;;; 또 올꺼에오', 58, 16, 'GOOD', SYSTIMESTAMP);
