INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '친구들이랑 합정 돌다가 눈에 띄어서 들어왔는데 내부가 넓고 층도 높아서 너무 좋아요! 야외뷰도 끝내주네요... ✨ 합정 또 올 일 생기면 다시 한번 방문하고 싶습니다! 디저트도 너무 먹음직스러워요 😻 카페 인테리어나 분위기도 전체적으로 차분해서 편하게 잘 쉬다 갑니당 ❤', 74, 15, 'GOOD', SYSTIMESTAMP);
