INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '공간이 너무조아요! 아늑하고 집중하기 좋고 테이블간 간격도 적당해서 기분좋게 머무를 수 있어요:) 음료도 다양하구 커피도 너무 맛있어요..🥹', 64, 15, 'GOOD', SYSTIMESTAMP);
