INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '친절하신 직원분 덕분에 괜스레 기분이 좋아지는 저녁이에요 :) 지나가다 우연히 방문했는데 아늑하고 따뜻한 분위기가 너무 좋네요 종종 와서 시간을 보낼 것 같습니다😊', 27, 6, 'GOOD', SYSTIMESTAMP);
