INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '분위기도 힙하구 시그니처 말차크림라떼 너무 맛있어요 간만에 친구랑 만나는데 얘기하기 좋은 카페 찾은거 같아서 기분이 좋아요 직접 만드시는 디저트도 너무 예쁘고 맛있어요!!', 13, 6, 'GOOD', SYSTIMESTAMP);
