INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '홍대 골목길을 다니다가 발견한 카페. 야외 테라스까지 있고 밤에는 불멍도 할 수 있는 곳이라 아주 매력있는 곳이에요. 매장에  베이킹실이 있어서 빵도 직접 만들고 음료도 맛있는데 분위기까지 좋아서 은근 찿아오는 분들이 않더라구요. 더위가 지나가면 테라스 자리는 완전 인기있을거 같아요~~~', 20, 0, 'GOOD', SYSTIMESTAMP);
