INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '합정 카페 맛집이네요♡ 멀리서도 눈에 띈 건물이 멋지고, 카페 내부는 더 감각적인 인테리어로 머무는 시간 내내 기분좋은 편안함이 가득한 곳이었어요^^ 커피도 맛있고 디저트도 맛있던 카페♡ 강추해요', 14, 10, 'GOOD', SYSTIMESTAMP);
