INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '블루베리 라떼 7000원, 씹히는 블루베리가 매력적이고 부드러운 크림이 음료와 잘어울려요. 바테이블이 있어 주말 혼자 오기에도 좋고 음악도 잔잔해서 감성 있어요. 잠시 책읽으러 들렸는 데 좋네요. 친구랑 또 오고 싶어요.', 6, 1, 'GOOD', SYSTIMESTAMP);
