INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '카페가 전체적으로 엄청 넓고 조용하고 쾌적해요! 디저트도 너무 맛있고 공부하기도 좋고 데이트하러 오기도 좋고 인테리어도 너무 예뻐서 넘 좋았습니당 주차도 편했어용! 꼭 다시 방문하고 싶어용', 9, 10, 'GOOD', SYSTIMESTAMP);
