INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '1시간 정도 시간이 떠서 책 읽을 겸 근처 카페로 온건데, 매장이 굉장히 넓고 바테이블에서 혼자 책 읽으니 집중도 엄청 잘되더라구요. 바테이블에 앉아서 몰랐는데 매장 규모는 엄청 큰데도 일반 테이블은 만석이었습니다.. 인기 카페였더라구요', 92, 22, NULL, SYSTIMESTAMP);
