INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '다양한 메뉴들이 있어서 좋았어요. 특히 요즘 유행하는 스모어쿠키 있어서 좋았어요!ㅎㅎ 커피 말고도 술 종류도 있고, 공간자체가 워낙 예쁘게되어있어서 좋았습니다. 근처 와서 대화나누기 좋은 카페 찾으시면 너무 추천하는 곳이에요!!', 96, 24, 'GOOD', SYSTIMESTAMP);
