INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '결혼 청첩모임으로 오게 되었는데 분위기 있고 너무 좋네요😆 날씨가 선선해지는 요즘, 야외테라스도 있어서 딱 좋습니다! 시즌메뉴로 시켜먹어 보았는데 맛있습니다😝', 2, 1, 'GOOD', SYSTIMESTAMP);
