INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '매장이 깔끔하고 인테리어가 센스있어서 마음에 들었어요. 메뉴도 다양해서 선택지도 많고요. 말차 크림커피를 주문했는데 진하면서도 부드러워서 딱 제취향이네요 베이글도 고소하고 맛있어서 한끼 식사로도 제격이네요 재방문의사 있어요:)', 76, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '분위기가 아늑하고 조명 덕인지 눈도 편안해요 잔잔한 노래속에서 편하게 얘기 하기 좋은 곳이었어요 당연하지만 음료와 디저트 모두 맛있었습니다 특히 말차가 시그니처인 이유가 있는 듯 말차러버들이라면 꼭 한번 들려보시길 추천 🍵', 17, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '합정에 이렇게 멋지고 근사한 카페가 있었다뇨..! 1층과 3층 두 곳의 매장 느낌이 완전 달랐는데, 1층은 전시를 보러 온 듯한 느낌이었다면, 3층은 실내 스튜디오 같은 느낌이었습니다:) 전체적으로 너무 예쁘고 멋진 카페였어요 ! 테이블도 많고 매장도 커서 취향껏 자리해도 좋을거 같아요:) 메뉴도 다양했는데 저희는 시그니처 메뉴와 아이스 아메리카노, 베이커리를 하나 먹었는데 전체적으로 커피는 고소하고 빵은 초촉하고 부드러웠어요!  공간 곳곳 너무 예뻐서 카메라를 어디에 두어도 정말 예쁘게 나온다는 점도 굳굳! 다음 번에는 3층을 이용해봐야겠어요 :)', 65, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
