INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '잠봉뵈르 잠봉이 엄청 넉넉하게 들어있어서 맛있어요! 제 개인적인 취향으로는 베이글이 조금 질겼지만 만족스러웠습니다 ㅎㅎ 음료는 2잔 모두 너무너무 맛있었어요❤️', 79, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '잠봉뵈르베이글이 그렇게 맛있다고해서 왔는데 안이 정말 꽉 차있고 맛있습니당 자몽주스도 완전 생과일이라 과육이 엄청 많아서 식감과 맛을 다 잡았네용! 시원하고 분위기 좋아요 최고당', 2, 7, 'GOOD', SYSTIMESTAMP);
