INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '합정 예쁜 대형카페! 그냥 인테리어랑 좌석들이 미쳤음. 그런데 음료랑 디저트도 너무 맛있음. 진짜 숨은? 나만의 아지트를 발견한 기분. 분위기도 좋은데 음료랑 디저트도 맛있어서 앉아있던 시간이 행복해지는 카페', 11, 1, 'GOOD', SYSTIMESTAMP);
