INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '전에는 낮에 한번 왔었는데 저녁에 오니까 또 분위기가 색다르네요! 커피는 여전히 맛있습니다. 2층은 포근하고 편안한 분위기고 3층은 세련된 느낌이네요✨ 대화하기 너무 좋은 공간인데 커피랑 디저트까지 완벽! 합정 카페로 멧커피 넘 좋습니다☺️', 6, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
