INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '합정 카페를 검색하다 찾아서 가게된 카페에요. 조용하고 분위기 좋다고 해서 방문했는데 아늑한 분위기에 개화하기 좋아서 만족스러웠어요! 커피도 맛있고 음료 종류도 다양해서 모두 만족😍 합정에서 넓고 쾌적한 공간에서 분위기를 즐기고 싶다면 멧커피를 가세요!👍🏻', 24, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '합정상수역 근처에 이렇게 힙하면서 분위기있는 카페가 있는줄 몰랐네요..✨❤️ 항상 지나가기만했는데 매장도 크고 1층3층으로 운영하고 있더라구요! 1층은 우드인테리어 3층은 스튜디오 느낌? 둘다 이쁨;; 블루베리라떼랑 시그니처 apfelstrudel 시켰는데요 블루베리라떼가 지금까지 먹은 것중 젤 맛도 잘나고 밍밍하지 않아서 완전 맛도리에요❤️ 디저트는 시그니처인 이유가 있더라구요~ㅎㅎ 다른 파운드케이크도 있어서 다음에 먹으러 또 와야겠어요 ><🙆🏻‍♀️🩷', 94, 19, 'GOOD', SYSTIMESTAMP);
