INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '초코 파운드케잌이 진하고 달콤해서 따뜻한 차랑 정말 잘 어울렸어요! 데이트하기 좋은 카페라고 해서 찾아갔는데 확실히 대화하기도 편하고 분위기도 멋들어지고 예쁘네요 비가 오면 3층은 운영하지 않아 조금 아쉽긴 하지만..ㅠㅠ 합정에서 데이트 카페로 가기 좋은 곳 같아요!', 21, 1, 'GOOD', SYSTIMESTAMP);
