INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '여기 밤에 분위기가 ㄹㅇ 미쳤습니다. 주광빛 조명이 진짜 분위기를 맛도리로 자몽에이드도 ㄹㅇ 찐맛도리 자몽에이드로 자몽러버이신 분들은 꼭 드셔봤으면 하는 메뉴로 여기 에이드 종류가 굉장히 많았는데 그냥 하나씩 다 부수러 가려고요 .', 86, 17, 'GOOD', SYSTIMESTAMP);
