INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '합정역 근처 넓고 쾌적한 멧라운지 카페에 방문했는데 너무 추천이요!!☺️ 공간이 멋스럽고 포토존도 많아요 자리도 많으면서 자리 간 간격도 넓어서 대화하기도 좋고 커피와 디저트로 당충전하기에도 좋습니당👍🏼😆', 44, 7, 'GOOD', SYSTIMESTAMP);
