INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '멧커피 홍대점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '영화 보고 걷다가 처음 와봤는데 분위기 넘 좋아요. 망고커피 맛있게 마셨습니다! 체다치즈케이크도 살짝 데워서 주셔서 촉촉하게 잘 먹었어요. 3층이 더 예쁜데 첫 방문이라 1층에서 주문해서... 이제 알았으니 다음엔 3층 갈래요! 화이트톤에 채광 장난 아니라 사진 잘 찍힐 것 같아요ㅎㅎ', 47, 10, 'GOOD', SYSTIMESTAMP);
