INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '처음 피오니 딸기빙수를 먹었을때 충격을 잊을 수 없어요 여름만 되면 늘 생각나요 케이크는 안 먹어봐서 모르겠는데 여기 딸기 빙수는 진심으로 추천합니다 또 가고 싶어요', 34, 7, 'GOOD', SYSTIMESTAMP);
