INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '예전부터 좋아하던 케이크 였어요- 간만에 사먹었는데도 너무 맛있네요- 임산부라 남편이 서울에서 집까지 사왔네요 ❤️ 그래서 그런가 더 맛나게 먹은듯 한!', 10, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '생일이라 데이트하러 나갔다가 지나는길에 들러서 케이크 사고 음료2잔도 마시구왔어요. 산미있는거 싫어해서 드립은 과테말라로 주문. 아인슈페너는 약간산미있는 커피네요. 맛있었어요.', 24, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '예약한 케익을 찾을겸 방문한 매장에서 커피와 조각케이크를 주문했습니다. 남자 직원분 정말 불쾌한 말투와 표정이더군요. 휴일  소중한 여가시간인데 기분이 상해서 나와서 너무 안타까웠네요. 웃진 않으시더라도 기본적인 서비스 마인드는 필요해 보입니다.', 44, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '망고딸기 조각 케이크, 커피 먹었어용 여름에는 역시 딸기는 비추입니당 크림이 맛있지도 않고용 다른 지점에서 케이크를 가져오시는 것 같았어용 딸기케이크가 만드는 난이도가 높나봐요 지방에서 먹은 딸기케이크가 훨씬 맛있습니당 대화나누기에 좌석 간 자리가 넓진 않아요', 31, 0, NULL, SYSTIMESTAMP);
