INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '가족 생일 때도 구매하는 케이크인데 이번에 지인 생일이어서 키친205 홍대점에 갔다가 맛 없어서 버리고 피오니 조각 케이크를 샀어요. 달달한 케이크를 좋아하지만 여기는 그렇게 달지 않아서 괜찮은데 딸기가 좀 더 많았으면 좋겠어요.', 1, 5, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '생크림 좋은거 쓰는거 같아요 하나도 안느끼하고 적당히 달달하고 딸기 신선하고 다 맛있어요. 보냉백사서 반나절이나 들고 다녔는데도 상태가 너무 좋아요. 맛있고 갓 만들어진것 같아서 감동스러웠어요.', 109, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '홍대에 오면 항상 자주 방문하는 피오니입니다. 케이크부터 커피까지 정말 맛있어요 ! 나중에 홀케이크로 사러 오는것도 좋아보입니다', 44, 0, 'GOOD', SYSTIMESTAMP);
