INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '홍대 딸기케이크 맛집 블루리본 카페 피오니예요❤️ 추천 받아 맛보았어요^^ 테이블 간격이 좁았지만 거의 만석이라 웨이팅없이 먹을 수 있음에 감사했어요 ㅎㅎ 딸기생크림 조각(7.5), 딸기주스(7.5) 픽, 일단 금액이 합리적이어서 마음에 쏙 들었어요 ㅎㅎ 딸기 비중 낮지만 제누와즈가 부드러우면서도 부드럽지만은 않은 식감이 딱 좋았고, 생크림 깔끔하고 은은하게 고소함이 느껴져 맛있었어요~! 딸기주스는 no시럽으로 주문, 딸기의 맛이 고스란히 전해졌는데, 달콤함은 그닥인 새콤한 딸기였어요 >.< 그래도 딸기청으로 만든 게 아닌 생딸기주스라, 딸기의 싱싱함이 느껴지는 건강한 맛이라 괜찮았어요. 곧 저녁시간인데다 낮에 커피를 마셔 커피 대신 딸기주스 골랐는데, 커피도 맛있을 것 같아요^^', 26, 0, 'GOOD', SYSTIMESTAMP);
