INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '여전히 건재한 피오니 아주 초반에 테이블 한두개 시절에 먹었던 케이크가 생각나 예약하고 픽업했습니다. 테이블 개수 많은데 전부 꽉 차 있었습니다 선물해서 맛 보지 못했지만 다음에는 케이크 먹으러 가려구요 초코 케이크가 궁금하네요', 35, 9, NULL, SYSTIMESTAMP);
