INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '정말 딱 맛있는 딸기케이크의 정석이에요 🍓🍰 원래 단 음식을 잘 못먹는 커플인데 여기 피오니는 너무 맛있어서 대만족하면서 먹었어요. 특히 생크림이 너무 맛있어서 둘이서 한 판 바로 다 먹었답니다 (ㅎㅎ)', 54, 18, 'GOOD', SYSTIMESTAMP);
