INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '10년전에는 작은 가게였는데 크게 성업하신 것 같네요 저렴한 가격은 아니지만 장소가 장소인지라 나름 괜찮은 것 같아요 빙수에 딸기청 따로 주신 것 괜찮았어요', 8, 8, NULL, SYSTIMESTAMP);
