INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '오랜 기간 사랑받는 피오니 연남동 때부터 다녔는데 우연히 이름이 같아 들어와보니 그때 그집이다 :) 디저트 여전히 멋지고 맛지고 커피는 다소 연한편 (핸드드립기준) 좁고 협소하긴해도 그덕에 좌석이 제법되고, 잠시 머물러 당충전하기에는 괜찮다 번창하셔서 멋집니다 매니저님 친절 감사합니다', 39, 8, 'GOOD', SYSTIMESTAMP);
