INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '입에  넣는  순간  그냥  입에서  녹아 사라져버려요. 지나치게  달지않고  넘  맛있는  케잌! 친구 생일이라  주문했는데  생일인  친구뿐만 아니라  모두들  감탄하며  먹었어요! 딸기케잌  맛집인정!!', 20, 1, 'GOOD', SYSTIMESTAMP);
