INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '하도 피오니 딸기케이크가 맛있다는 이야기를 많이 들어서! 급 딸기케이크가 먹고 싶어진 날 드디어 가봤습니다~! 진짜 맛있더라구요?! ㅎㅎㅎ 듣던 대로 크림이 맛있고 안에 들어가는 딸기도 괜찮았어용!🍰 커피도 원두 다양하게 취급하고 계셨고 직원분들도 친절하셔서 좋았습니다 ㅎㅎ 다만 인기가 너무 많아서 사람들이 북적이기도 하고 노래도 틀어두셔서 조용히 무언가 할 분위기는 아닙니다! 수다 하면서 케이크 한 조각 하러 가기 좋은 카페 같아용~', 49, 5, 'GOOD', SYSTIMESTAMP);
