INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '시아버님 생신때 주문했고 오늘 이종사촌 생일때문에 또 주문하다가 리뷰를 안썼길래 생각나서 씁니다 10년전에 아는 지인때문에 먹어보았다가 잊지못한 케잌인데 10년이 지나서 먹어도 맛있습니다 여러지역에 유명하단 딸기 생크림케잌은 구매해서 먹는중인데 피오니만한데가 없어서 또 예약했습니다', 19, 7, 'GOOD', SYSTIMESTAMP);
