INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '커피(과테말라) 핫 5,000원 루이보스 아이스 6,000원 딸기생크림조각케이크 7,500원 초코딸기조각케이크 8,000원 피오니는 역시 딸기케이크 맛집🍓🍰', 30, 10, 'GOOD', SYSTIMESTAMP);
