INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '1년에 한 번은 꼭 오는 피오니 딸기생크림케이크는 품절이라 새로운 메뉴 도전 ! 맛있다 날 추우니까 차로 시켰는데 힐링되는 맛 .. ❤️', 45, 4, 'GOOD', SYSTIMESTAMP);
