INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '설명이필요없는딸기생크림케이크세상에서제일맛있는집입니다. 한조각은 모자라니 두조각은 주문해야해요.  3명이서 미니홀케익 주문하니 만족스러웠어요.', 20, 5, 'GOOD', SYSTIMESTAMP);
