INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '사람이 아무도 없길래 이젠 옛날같이 사람 별루 안오나했는데 저들어오고나서 계속 들어왔네요~ 선물만 받아보고 매장은 처음와봤는데 케잌 한조각에 커피에 맛있게 혼커했네요❤️ 사장님도 친절하시고 요새 케이크도 한조각에 더 비싼데 가격도 합리적인거같아요 !', 2, 10, 'GOOD', SYSTIMESTAMP);
