INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '16일에 네이버예약하고 18일에 픽업했어요! 앞선 일정이 조금 일찍 끝나서 빨리 픽업 가능한지 전화로 여쭤봤는데 가능하다고 하셔서 15분 정도 일찍 픽업했습니당🫶🏻 운동모임에서 연말파티 겸 축하할 일이 있어서 맛있다고 유명한 피오니 딸기케이크 준비해갔는데 다들 너무 맛있다고 해줘서 너무 뿌듯했어요（╹◡╹） 생크림이 진짜 너무 맛있어요 !!!!!! 덕분에 더 풍성한 연말파티였습니다❤️✨', 28, 2, 'GOOD', SYSTIMESTAMP);
