INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '딸기많이1호 약간 비싸긴한데 딸기가 엄청 많았고 딸기가 달지않고 상큼했고 크림이 많지않아서 엄청 달지는 않았어요 다음에는 다른 케이크 먹어보고 싶네요', 32, 3, 'GOOD', SYSTIMESTAMP);
