INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '녹차딸기랑 생크림딸기 먹었는데 확실히 동물성이라 그런지 잘 넘어가네요 원래 생크림 물려수 한 조각 이상 못 먹는데 친구랑 둘이 반 조각씩 맛있게 먹었어요 나오자마자 녹차딸기 먹어서(포장이 안됐거든요) 따땃~하니 좋았어요', 8, 9, 'GOOD', SYSTIMESTAMP);
