INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '현장에서 캐치테이블로 대기 걸어두고 주변 돌아다니다가 20분 안에 연락와서 바로 들어갔어요! 트리가 아주 이쁘더라구요! 피오니 딸기케이크 처음 먹어보는데 우유맛 많이나는 케이크 좋아하시면 추천드려오!!', 240, 85, 'GOOD', SYSTIMESTAMP);
