INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '크림이 너무 맛있습니다. 딸기와 시트도 너무 맛있었어요. 안내도 친절하고 좋았어요. 지인 생일이라 샀는데 모두 너무 만족했습니다.', 10, 0, 'GOOD', SYSTIMESTAMP);
