INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '딸기케이크 2호 예약해서 픽업했습니다! 저는 이전에 먹어본 적이 있어서.. 그냥 맛있었지만 ㅋㅋ 모임 사람들 다 좋아하더라구요! 시트는 적당히 두껍고 부드럽고, 크림은 느끼하지 않고 가벼우면서 적당히 달달해요. 기본기가 탄탄한 케이크입니다. 큼지막하니 양도 많아서 잘 나눠먹었어요🍰', 45, 10, 'GOOD', SYSTIMESTAMP);
