INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '드립커피로 내려주는 커피가 정말 맛있음 고소한 맛 좋아하는 사람은 과테말라 추천 딸기케이크 먹으러 갔는데 커피가 정말 맛있어서 또 가고싶어요(케이크도 맛남) 사람이 많으면 우글우글 시끄러운 분위기가 조금 아쉬웠어요', 31, 1, NULL, SYSTIMESTAMP);
