INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '급하게 카페 찾다가 왔는데 케이크 맛있네요~ 음료 사이즈가 작긴 하지만 매장도 깨끗하고 친구들과 이야기하며 시간 보내기 좋아요🍓🤍', 34, 3, 'GOOD', SYSTIMESTAMP);
