INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '크리스마스 임박해서도 예약이 가능하길래 후다닥 예약했어요 당일날 오픈시간에 맞춰 친구가 대신 수령하려갔는데 현장 대기줄이~ 예약한 사람 따로 예약안한 사람 따로 줄을 서야할 정도였다고 하네요 평소에 단거 많이 안먹어서 케이크도 금방 물려하던 저였는데 친구랑 둘이 미니 케이크 완판🤭🫢 부드럽고 물림 없는 케이크는 오랜만이였어요 사알짝 비싸지만 기념일때 또 먹을만 한거같아용👍', 50, 2, 'GOOD', SYSTIMESTAMP);
