INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '딸기케익이 유명하다는걸 알고있지만 그전에 먹은 식사가 너무 배불러서 아쉽게도 딸기케익은 먹지 못했어요..ㅠㅠ 그래도 음료는 맛있게 먹었습니당 다음에 꼭 딸기케익 도전하기로!!', 32, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '동물성 생크림이여서 그런지 느끼하지 않고 그 자리에서 하나 다 먹어버렸어요!! 특별한날 소중한 사람과 함께 먹는걸 추천드려요!', 18, 9, 'GOOD', SYSTIMESTAMP);
