INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '딸기 케이크 1등이에요… 진짜 여기 케이크 따라올 집 없다고 생각합니다… 너무 맛있어서 또 먹고싶어요ㅠㅠ 케이크는 늘 여기서 사서 먹어요! 멀리서 찾아서 올 만한 가치가 있습니다🫶', 42, 4, 'GOOD', SYSTIMESTAMP);
