INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '딸기생크림 케이크 맛집의 원조.. 10년만에 다시 찾은 것 같은데 여전히 맛있네요 웨이팅이 많아서 카페 이용은 테이블당 1시간 가능하다고 하네요', 15, 6, 'GOOD', SYSTIMESTAMP);
