INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '케이크 예약 후 방문하였습니다. 바쁘신 것 때문인지.. 너무 불친절하시더라구요 아무리 예약픽업만 하는 것이라도 그렇지 너무 불친절하셔서 조금 당황했습니다.. 케이크는 항상 맛있네요. 생크림은 물론 딸기도 적당히 새콤달콤하고 맛있었습니다.', 30, 3, NULL, SYSTIMESTAMP);
