INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '케이크 예약하고 픽업해서 친구들과 파티룸에서 먹었어요!! 4인이 먹기에 딱 좋았고 느끼하지 않아서 끊임없이 들어갔어요. 안에 딸기도 가득 들었고 크림도 맛있어요!!! 기본제공 초가 없던것은 조금 아쉬웠어요~', 46, 10, 'GOOD', SYSTIMESTAMP);
