INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '비싸긴했지만 다들 맛있다고 해줘서 뿌듯했습니다! 케이크만 수령했는데 카페는 사람이 꽉 차있었어요...! 원래 홍대에서 딸기케이크 맛집으로 유명했다고 하더라구여', 36, 0, 'GOOD', SYSTIMESTAMP);
