INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '예전에 사먹은 적이 있는데 여기 딸기 케이크가 생각나서 먹으러 왔습니다!! 역시 생크림과 빵이 확실히 맛있어요!! 대신 딸기가 이번엔 조금 셔서 아쉬웠습니다 ㅜㅜ 그래도 맛있습니다!! 추천!!', 11, 5, 'GOOD', SYSTIMESTAMP);
