INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '사진을 못찍었네요 ㅠㅠ 딸케가 유명하다고해서 샀는데 조각케잌하나만 샀으몀 좋았을걸 후회했어요~~ 제입에는 크림이 너므 많았고 크림이 달아서 많이 못먹겠더라구요~~ 주변에 다른 딸케유명한곳들보다 저렴하다했는데 딸기가 많이 안들어가 있어요~~ 다른곳에비해~~', 10, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '생크림은 라이트한 맛은 아니고 좀 느끼한 편에 속함. 시트는 촉촉하고 맛있어요 그런데 딸기를 너무 아낀 느낌? 딸기양이 너무 적어서 몇입 먹다보면 금방 물리는 맛.. 생크림이라도 가벼웠다면 물리지 않았을텐데요 ㅠ 선물까지 하기엔 아쉬운 케이크', 48, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '딸기케이크로 유명한 곳이에요🍰 주말엔 붐벼서 자리가 없을 수도 있고 주말 매장 이용시간 1시간입니다. 테이블 간 좌석 간격이 다소 좁은 편이고 커피는 에스프레소 메뉴는 없고 전부 드립메뉴만 있습니다. 말차딸기케이크 먹었는데 케이크 시트지는 좀 퍽퍽한데 크림이 말차맛나고 딸기도 맛있었습니다~', 40, 7, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '생크림케이크가 유명하다고 해서 구매해봤어요 생신케이크로 준비해서 가족 모두가 같이 먹었는데 다들 맛있다고 하네요 생크림이 느끼하지 않고 너무 달지도 않고 담백하게 부드럽게 녹아내리는 맛이에요 안에 빵도 촉촉하니 맛있고 딸기도 신선했어요 후기가 좋은 이유를 알겠더라구요', 41, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '사진을 못 찍고 그냥 먹어버렸네요..생크림이 너무 맛있었어요~생크림을 좋아하지는 않지만..여기 생크림은 부드럽고~달지 않아서 좋았습니다~^^가서 줄 서있는거 보고 놀랬지만,예약 했다고 하니 옆쪽에서 체크 하신 후에 바로 받아 올 수 있어서 편했습니다~^^', 55, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '외관도 예쁘고 생크림도 안 느끼하고 딸기도 달달하니 다 너무 좋았는데, 먹다가 작은 머리카락이 나왔어요...머리카락 길이도 짧고 그거 말고는 모든 점이 괜찮아서 그냥 다 먹긴했는데 좀 찝찝하네용... 뭐 수제니까 어느 정도 이런 일이 발생 할 수 있다는건 이해하겠는데 그래도 값이 저렴한 것도 아닌데 좀 더 철저하게 위생관리를 해줬음 좋겠어요.', 18, 6, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '괜히 예약했어요 크림은 혀에 맴돌게 텁텁하고 느끼하고 케이크 시트 안에는 딸기가 정말 얇게 슬라이스 되어 있어서 딸기 맛도 별로 안나고요 이럴거면 그냥 돈 좀 더 내서 다른 곳에서 예약할 걸 그랬어용 하다못해 투썸 스초생이 더 나을 것 같은 느낌 그치만 케익에 별로 관심 없으신 분이라면 추천합니다 엄청 최악은 아니에용', 16, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '음...추억속 장소라 방문했는데 워낙 요즘 딸기빙수 맛있는곳이 많아서인지 여기 딸빙은 그냥.. 케익도 예전 명성만 할까 싶은마음이 들더라고요. 유명했던곳의 고충인걸까?하며 더 맛있는 집들은 계속 생겨나고~', 58, 15, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '피오니케이크 너무 좋아해서 자주 와요ㅎㅎ 아직 딸기철이 아니라 딸기가 조금 부실하네오 맛도 달지않고 ㅎㅎ 겨울되면 먹어야겠어요! 부드러운 생크림맛은 여전합니다^^', 15, 3, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '딸기케이크 미니 포장이라 대기없이 바로 주문가능했습니다. 아주 오랜만에 피오니케이크 먹고싶어서 간건데 예전같은 감동의 맛은 사라졌네요… 케이크는 둘째치고 커피… 아주 문제있습니다.메뉴에 드립커피만 있길래 자신있나보다 했는데 웬걸 한입먹고 클레임 걸고 싶었네요. 아이스인데 얼음은 다 녹고 커피라고할 수 있는 음료인지 무슨 까맣게 탄 군고구마 먹는 맛이었습니다. 개선이 필요한 듯 싶네요.', 3, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '역시 믿고 먹는 딸기케잌이네요. 크림이 진짜 담백해서 크림 듬뿍 먹어도 입안에서 불쾌하게 단 맛이 남지 않는 건강한 맛이에요! 빵도 촉촉하게 맛있고 딸기와 궁합이 아주 최곱니다. 강추강추 강강추!!!!!!!!!', 4, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '여전히 엄청 맛있네요 ㅠㅠ 여전히 그대로 맛있어서 감사합니다. 항상 사람이 부적거렸는데 너무 한산해서 문 닫으실까바 걱정했어요. 쓸데없는 걱정이겠죠?  :) 오래오래 번창하세요!!!', 5, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '피오니 딸기케익 유명해서, 미리예약하고 픽업했습니다. 보관방법 여쭤보니, 귀찮다는듯이 말씀하니.. 힘든건 이해하는데 기분은 좀 별루네여. 케익은 깔끔하고 맛있었습니다.', 32, 8, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '한10년만에 먹은거 같아요 아이들과 함께 먹어 더욱 만족스러웠습니다. 예전엔 이런 종류의 디저트가 없었는데 이제는 시대가 너무 상향 평준화가 된듯..', 0, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '케이크 박스에서 꺼내보고 딸기가 너무 작아서 놀랐어요. 요즘 철이 아니라 그런지 맛도 확실히 새콤하기만하고, 단맛이 전혀없어서 생크림맛으로 먹었는데 집안 어른 생신이라 맛있는 케익 가져간다고 말씀드려놨던 상황이라 조금 민망했습니다. 역시 과일은 제철에 머겅야 만족도가 큰 것 같아요.', 25, 3, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '여름에 냉동 딸기가 아닌 생딸기라니요....🍓🍰❤️ 딸기 빙수 너무 너무 맛있었고요. 연유도 따로 안 주시는데 우유 얼음이 충분히 달아서 새콤시큼달콤 딸기랑 찰떡!!! 너무 맛있어요!', 9, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '하... 제가 너무 속상하고 화나는데 말할곳이 여기밖에 없네요. 친구 생일이라 저번주에 미리 전화로 초코바나나샌드 예약을 3번이나 재확인 후 예약금 입금까지 완료한 상태였습니다. 오늘 선물해주고 안에는 딸기 말고 다른 과일 들어가 있다고 말했는데 딸기라더군요.. 집이라도 가깝고 여기밖에 딸기케이크가 없었다면 모를까 전 집도 멀고 굳이굳이 바나나샌드여서 여기로 방문하고 예약한건데 너무 허무하고 속상합니다. 그때 전화받으셨던 직원분께서 수화기 너머로 매니저님?께 바나나샌드 가능한지 확인하고 가능하다 하여 예약진행한거였습니다. 근데 다른샌드라니; 이런실수는 돈받고 파시는건데 아닌것 같습니다. 알바분이든 직원분의 실수든 이미 지나간 일이지만 저같은 일 다른분이 겪지 않으셨으면 하여 적습니다.', 11, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '친구들이 여기 딸기 케이크를 안먹어봤냐구 하며 바로 데려온곳 입니다 명성만큼 맛있었어요 커피도 맛있었구요! 케이크가 시트가 부드럽고 우유크림이 느끼하지 않네요 같이 시킨 다크초코 치즈케이크도 맛있었습니다!!! 그치만 딸기 생크림 케이크가 진짜 넘사벽 부드럽고 맛있었습니다🫶🏻', 41, 4, 'GOOD', SYSTIMESTAMP);
