INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '가족들이 생크림케이크와 딸기를 좋아해서 생일때마다 피오니에서 케이크를 사서 축하하는데, 느끼하지않고 깔끔하고 부드러운 생크림과 신선한 딸기를 함께 먹을 수 있어서 좋아요!! 역시 합정에서 생크림딸기케이크는 피오니!! 오픈시간이 아닌데 포장은 가능하다고 하셔서 11:47분에 포장구입했어요!', 4, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '제가 너무 좋아하는 케잌이에요!! 숏컷?하신 직원분 커피 설명도 천천히 쉽게 잘해주셔서  너무너무 감사했어요! 설명말고도 그냥 친절함 그 자체셨어요! 덕분에 맛있는 케잌과 음료 잘 마시고 갔습니다!', 28, 2, 'GOOD', SYSTIMESTAMP);
