INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '케이크가 워낙 맛있다고 유명해서 방문해봤어요!!🍓🍓 딸기 철이 아닌데도 새콤 달콤 케이크가 넘 맛나요😋💕 커피 원두 종류도 다양하고 드립커피 맛있게 내려주십니다! 화장실도 남녀구별 되어있고 깨끗하게 관리되고 있어서 더더 호감이에요🫶🏻🫶🏻 담에 케이크 사러 또 와야겠어요🥰', 34, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '남친이 친구들과먹으라구 사쥼.. 근데 가격대비 ... 이정도비쌀 케익인가 싶음 2호 52000원인데 파바랑 그닥...차이못느낌... 가격보면 우와대박 이런느낌이나야될거같은데 흐음', 26, 10, 'BAD', SYSTIMESTAMP);
