INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '커피는 양이 적어 사악하고 테이블 빈자리 적어 다닥다닥이라 오래 앉아있고 대화하기는 안 좋지만 동물성생크림 케이크 단연 전국수준이라 생일케이크 홀케이크 예약해서 받는게 인생의낙이라 감히 말해봐요 빙수는 안 좋아해서 첨 시켰는데 왜 시그니처 메뉴인지 알겠어요 설빙 투썸빙수보다 더 저렴한데 백배 더 맛나요', 14, 10, 'GOOD', SYSTIMESTAMP);
