INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '언니 생일케이크로 구매했어요! 둘~셋이 먹기 딱 좋은사이즈였고 맛있었습니다! 조금 가격이 있지만, 요즘 케이크가 다 비싸서 ㅎㅎ 이쁨비용이라 생각해용', 35, 3, 'GOOD', SYSTIMESTAMP);
