INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '먹자마자 감탄이 나오는 딸기빙수,,🍓 정말 사랑합니다 피오니,,,♡ 초코케익은 처음이었는데 많이 안 달아서 좋았고 역시 생크림 케익이 좀 더 취저♡ㅋㅋㅋ', 8, 2, 'GOOD', SYSTIMESTAMP);
