INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '딸기빙수랑 딸기케이크 완전 맛있어요 !! 디저트 먹어보는 순간 왜 유명한지 알겠더라구요 🥰 딸기빙수가 특히 대박임 ㅜㅜ 진짜 진짜 맛있는 연유?를 그대로 눈꽃빙수 만든맛 💛 커피는 평범했던거 같아요 (신맛나서 호불호 갈리는듯함) 디저트 먹으러 또 가고 싶음 👍🏻👍🏻', 45, 0, 'GOOD', SYSTIMESTAMP);
