INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '워낙 유명한 가게라 말하기 입 아프지만 딸기 케이크 최고! 한 2년 만에 먹는 건데도 여전히 맛있네요. 드립커피도 달달한 빙수도 맛있었습니다! 월요일에도 오픈해서 좋아요ㅠㅠ!', 11, 9, 'GOOD', SYSTIMESTAMP);
