INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '고등학생때도 유명한 케익집이었는데 서른이 된 지금도 여전히 그 맛을 잃지 않았더라구요. 아버지 환갑이란 소중한 날에 함께했습니다. 넘 맛있던 케익 덕분에 가족끼리 한층 더 행복한 시간이었습니다. 감사합니다.', 23, 9, 'GOOD', SYSTIMESTAMP);
