INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '딸기케이크가 유명한 피오니! 여름이라 빙수가 먹고싶어서 딸기빙수도 먹어봤어요 너무 맛있지만 테이블이 다닥다닥 붙어있기도 하고 사람이 워낙 항상 많은 카페라 대화할때 소리가 잘 안들려요 ㅠㅠ', 101, 25, 'BAD', SYSTIMESTAMP);
