INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '역시 피오니 생일케익 여기저기에서 돌아가면서 주문하다가 다시 돌아온 피오니  인기가 가장 많음 그냥 여기로 고정해야겠음 5년 전이나 지금이나 맛이 똑같이 맛있음 10년뒤에도 이맛 유지 해주세요~', 3, 0, 'GOOD', SYSTIMESTAMP);
