INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '피오니 딸기 케이크 맛있는 건 이미 유명하죠~~ 🙊🙈 남자친구가 며칠전부터 피오니 딸기케이크 먹고싶다고 말했어서 합정 간 김에 들러서 포장했어요!🍓 여전히 맛있더라구용🩷 줄이 좀 있어서 조금 기다렸습니당~~', 29, 2, 'GOOD', SYSTIMESTAMP);
