INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '딸기 케이크하면 피오니부터 떠오를 정도라 몇 년 만에 시간 내서 방문했습니다. 딸기 생크림, 초코 생크림 케이크 포장으로 구매하고 포스 보시는 분 말고 다른 분이 포장해 주실 줄 알고 기다리려 했는데 포스 보시는 분이 바로 맨손으로 케이크 꺼내서 포장해 주시더라고요 ..? 케잌에 아무리 비닐 둘러져 있다고 하더라도 위생은 별로 신경 안 쓰는 매장인가 싶었습니다. 그리고 옛날에도 이랬었나 싶을 정도로 딸기가 회 뜬 것도 아니고 슬라이스 쳐서 들어가 있어서 먹으면 딸기 맛 거의 안 나고 크림하고 시트밖에 안 씹혀요. 특히 케잌 뒷부분엔 아예 샌딩된 딸기도 없어서 그냥 시트하고 크림이에요. 업체 사진이랑 너무 다르지 않나요 ㅎㅎ 재방문은 안 할 것 같아요.', 69, 17, 'BAD', SYSTIMESTAMP);
