INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '가격 대비 양은 정말 사악하지만 딸기케이크의 정석과 같은 곳이라서 상수쪽 나갈 일 있으면 언제나 테이크 아웃해서 와요!개인적으로 딸기초코치즈케익이 베스트 인듯....정말 진하고 맛도리ㅠㅠ여름에는 딸기빙수도 진짜 최애에요', 48, 1, 'GOOD', SYSTIMESTAMP);
