INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '딸기케이크 너무 달지않은 가벼운 생크림이었어요! 딸기랑 전체적으로 잘 어울렸어요. 순삭 드립커피 원두 종류가 6가지 이상있는 집이었어요! 다만, 드립커피 라떼는 콜롬비아로 고정이에요. 안쪽 창으로 야외가 보이는 게 신기하고 예뻤어요', 130, 26, 'GOOD', SYSTIMESTAMP);
