INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '💛딸기 조각케이크, 디카페인 커피 🩷딸기조각케이크는 딸기가 가득있어서 맛있어요! 디카페인 커피는 산미가 있어서 저는 좋았습니다', 45, 0, 'GOOD', SYSTIMESTAMP);
