INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '항상 딸기케이크만 먹어서 초코로 사봤습니다! 안에 딸기인줄 알았는데 바나나 케이크더라구요! 사실 별로일 줄 알았는데 완전 맛있게 먹었어요 ㅎㅎ 초코랑 바나나가 완전 잘어울려요!😋', 14, 10, 'GOOD', SYSTIMESTAMP);
