INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '딸기도 달달하고 엄마 생일 케이크로 샀어요~ 사이즈가 너무 큰 것보다 딱 적당한 게 좋았는데 마침 현장 당일 구매가 가능해서 다행이었어요🥹', 34, 4, 'GOOD', SYSTIMESTAMP);
