INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '유명세에 비해서는 평범하다 (케이크가 너무 많이 상향평준화 됐기 때문에) 그래서 가성비는 나쁜 편이다 but ''맛있다''는 명제만큼은 참이다', 6, 2, NULL, SYSTIMESTAMP);
