INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '커피 맛있어요. 산미가 싫어서 과테말라원두커피로 먹었는데, 딱 좋은거 같아요. 크림커피는 진짜 너무맛있어요!!! 딸기생크림 케이크 먹으러 갔는데, 프레지아 케이크에 반했네요!!', 96, 20, 'GOOD', SYSTIMESTAMP);
