INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '월요일 오후에 갔는데도 만석이더라구요 여전한 인기에 깜짝 놀랐어요ㅎㅎ 홀케이크 사가지고 왔는데 크림이 더 진해진 느낌이라 맛있게 먹었어요😀', 32, 10, 'GOOD', SYSTIMESTAMP);
