INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '피오니 오랜만에 방문햇어요😆 역시,, 케이크 너무 맛있어서 하나 더 시키고, 커피도 한잔 더 먹고 나왔어요🩷 평일에 방문해도 피오니는 역시 인기 많더라구요👍🏻 넘 맛있었어요~☕️🍰', 37, 8, 'GOOD', SYSTIMESTAMP);
