INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '이 날 정말정말 추웠는데 오픈 딱 5분전쯤에 안에 어떤분도 앉아계시고 준비가 다 돼있는 분위기길래 들어가도 되는건가 싶어 들어가봤더니 오픈 전엔 밖에서 기다려야 한다고... 물론 그래야겠지만 주문하겠다는 것도 아니고 몇분정도는 추운데 그냥 안에 들어와계시라 하는게 서비스 차원에서 맞지않나 싶었습니당... 불친절하거나 하신건 아니었지만 조금 아쉬웠음!🥲 딸기케이크 시즌이라 딸케로 그렇게 유명하다는 피오니에서 조각으로 하나 먹어봤는데 생각보다... 많이 평범했어요ㅎ 그래도 특징을 꼽자면 빵 시트의 갈색부분이 얇은데 이런 디테일이 퀄리티 있는건가?! 하는 생각은 들었습니다 전체적으로 굉장히 부드러워요 근데 그래서 크림이나 시트의 맛이 크게 와닿지 않는달까🤔 개인적으론 굳이 재방문하진 않을 것 같아요', 50, 4, NULL, SYSTIMESTAMP);
