INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '오랜만에 너무 맛있었어요🫶 단거 안좋아하는데 많이 달지도 않으면서도 피오니만의 부드러운 크림맛이ㅠㅠㅠ❤️ 크리스마스 잘 보냈어용!!!', 106, 24, 'GOOD', SYSTIMESTAMP);
