INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '미니케이크 많이 작지않고 파티하기에 딱이에요! 홍대상수에서 당일에 살수있는 케이크 중에 이렇게 딱 적당한 크기와 맛있음을 다 갖춘 케이크는 피오니밖에 없는 것 같아요❤️', 69, 17, 'GOOD', SYSTIMESTAMP);
