INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '주변에 유명한 사진관 있는데 생일 기념 사진찍으려고 피오니에서 케이크 포장해서 갔어용 단면이 넘 예뻐서 사진도 잘 나오고 또 집가서 먹었는데 촉촉하고 넘 맛있었어요', 6, 0, 'GOOD', SYSTIMESTAMP);
