INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '전 딸기케이크 성애자에요. 피오니 케이크는 너무 무난해서 특징이 없는듯 하지만 확실히 이런케이크가 어려운지 다른곳에서는 이만큼 무난하게도 못만드는것 같아요. 크림은 느끼하지 않고 시트도 적당히 촉촉하고 부드러워여', 16, 7, 'GOOD', SYSTIMESTAMP);
