INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '여기 진짜 빙수 맛집,,,, 빙수 하나만 시켜도 되어서 너무 좋아요 ㅠ 다른카페는 1인1음료에+디저트인데 너무 좋습니다!! 왘전 맛있어요', 25, 5, 'GOOD', SYSTIMESTAMP);
