INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '딸기케이크 맛집, 피오니케이크! 올해 생일 우유크림이 깔끔하게 발리고 빨간 딸기가 아낌없이 든 피오니케이크를 선물받고 또 생각이 났었는데 기회가 좋아 웨이팅없이 찾게 된 피오니에서 오늘은 프레지에와 조각케이크를 겟겟^^ 맛이 변함 없어 좋았고 딸기가 무르지 않고 아삭하니 상큼해서 더 좋았던 맛! 역시 웃음짓게 하는 맛:)', 14, 2, 'GOOD', SYSTIMESTAMP);
