INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '딸기케이크가 넘 맛있어서 홍대 올때마다 꼭 들려욤 홀케이크 포장해가려했는데 품절이라 아쉬워요ㅜㅜ 있을 때 고민없이 바로 사야하는..', 6, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '길걷다 목이말라 그냥 쓱~ 들어간곳. 디카페인은 아메리노밖에 없는곳. 당이 당이땡겨서 아인슈페너 시켜먹음 완전 내스타일. 적당히 달고 적당히 구수하고 전부 다~ 마시고 나옴 공간도 쾌적.의자도 편하고 좋네~', 30, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '가격대비 패키지무슨일이예요? 케이크 1,미니를 샀어요 6만원이 넘는금액을 결제했고 선물용으로 구매했는데 계산시에 비닐백이던 종이봉투를 따로 고객에게 구매의사를 물어봐야하는데 물어보지도 않았고 황당해서 집으로 돌아온뒤 피오니에 전화해보니 아 그건 비닐은 있구요 따로 판매합니다를 이제야 물어물어 듣네요 패키지 정말 무슨일인가요 안내를 똑바로 해주든가 고지를 하셔야지 선물용으로는 기대이하네요 이런 후기를 남겨본적도 없어요', 32, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '오랫만에 딸기빙수가 먹고싶어서 성인2명이 찾아간 곳..🍓🍓 두명이 배가불러서 커피는 못먹고 빙수1개만 시켰는데도 친절하게 응대해주셔서 감사했어요👍🏻 요즘 1인 1메뉴라서 저같은 소식하고 싶은 사람에게는 매장에서 식후 디저트 먹기가 너무 부담스럽거든요.. 매장도 깔끔하고... 맛은 말해 뭐하나요.. 😆👏 1.1만원인데2,3만원 짜리 빙수보다도 훨씬 맛있고 심심할까바 딸기청도 취향존중 따로 주고..특히!! 우유를 갈아 넣은 얼음이 너무 부드러웠어요. 가격도 저렴하고 또 방문하면 딸기 홀 케이크 사가야겠어요. 🍓🍓 근래 먹었던 빙수중에 정말 맛있었습니다.🤩👍🏻', 15, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '홍대 상상마당 바로 옆 일본 감성 뿜뿜 이자카야~~ 안주맛집!! 가성비가 넘  좋아용!! 🤍🤍🤍특히 늦게까지 영업해서 여기서 먹다 첫차 타세용 다들🫶🏻', 28, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '딸키 케이크가 먹고 싶어서 찾아간 곳! 미니케익을 픽업해왔는데 생크림이 고소하고 안달아요. 딸기도 신선해요. 딸기 케익 맛집!', 28, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '딸기케이크가 동물성크림이라 우유맛도 진하고, 많이 달지 않고 딸기도 많이 들어있어 정말 맛있어요. 미니로 샀는데 사이즈는 아담한데 여자 넷 친구 생일파티하고 남기지 않고 먹을 수 있어서 딱 좋았습니다 ~홍대앞 주말이라 매장에 사람이 많이 붐벼서 포장해왔습니다.', 47, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '생일선물로 받은 케익인데, 여기가 그렇게 인기가많다는데, 먹어보니까 그이유를 알겠네요! 먹다보면 빵사이사이 안에있는 과일이나, 위에올라간 딸기는 진짜 신선하고, 무엇보다 생크림이 진짜 맛나요! 너무.달지도 않고, 느끼하지않아서 흡입했어요! (물론.개인적인 생각ㅎ)', 0, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '일년내내 딸기케이크 살 수 있어서 너무 좋아요~! 동네 카페에서 홀케이크 살바에야 이왕이면 피오니에서 사자하고 샀는데 가족 모두 너무 맛있게 잘 먹었어요~!', 55, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '피오니는 케이크도 유명하지만 사실 녹차라떼 맛집입니다 ㅠ ㅠ 진짜 초장기때부터 그린티러버였어요 테이크아웃으로도 충분히 맛난 음료예요!', 11, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '딸기 좋아하는 사람으로써 빠질 수 없는 피오니! 지금 딸기 제철이 아니라 조금 아쉽지만ㅠㅠ 딸기주스에 딸기가 가득 들어있어서 좋아요 ㅎ.ㅎ 겨울에 딸기 케익 먹으러 다시가야겠어요', 31, 5, NULL, SYSTIMESTAMP);
