INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '오랜만에 피오니 케이크로 생파했는데, 이젠 예약안하고도 사먹을 수 있네요! 기본 딸기 생크림케이크 먹었지만 초코도 있고 타르트도 있고 기본에서 베리에이션된 다양한 케이크가 있어서 좋았어요! 매장도 넓어서 조각케이크랑 음료마시고 가기 좋지만 사람은 많았어요 ㅎㅎ 붐비는 합정 골목에 있어 주차는 앞에 잠시 임시로 했어요!', 24, 3, 'GOOD', SYSTIMESTAMP);
