INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '초코 생크림 둘다 먹어봤습니다 개인적으로 저처럼 두개를 드신다면 초코먼저 먹고 생크림을 다음에 먹는걸 추천! 초코가 단내폴폴 초코가 아니라 적당히 쌉싸롬해서 깔끔한 맛이나요!', 14, 1, NULL, SYSTIMESTAMP);
