INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '케이크 할 때마다 항상 피오니를 찾게 되는 것 같아요! 크림도 전혀 느끼하지 않고 딸기도 싱싱해서 좋아요! 너무 맛있어요 🎂🍰🍓', 37, 10, 'GOOD', SYSTIMESTAMP);
