INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '남자친구 추천으로 갔는데 빙수를 못먹고온게 한이네요,,, 다음에는 빙수도!! 음료는 둘다 너무 맛있었는데 핑크레몬에이드 둘다 취저당해서 제거 다 빼앗겼어요 ㅋㅋㅋ', 78, 17, 'GOOD', SYSTIMESTAMP);
