INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '먹다가 생각나서 사진이 좀 그렇긴 한데; 미리 예약하고 가서 픽업하니까 편해요! 크림이 많이 달지 않아서 어른들이 먹기도 좋구 딸기가 많이 들어 있네요^^ 맛있어요 근데 가격 대비 가성비가 좋진 않네요', 7, 8, NULL, SYSTIMESTAMP);
