INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '딸기 케이크 맛집이래서 찾고 찾아왔어요🥰 평일 저녁이라 그런지 자리가 많았어요😊 다른 분의 추천으로 더치 아인슈페너도 시켜봤는데 크림이...😆 아주 대박입니다. 커피랑도 잘 어울려요 다음에도 카페를 가게 된다면 피오니로 꼭 올 거예요😘', 53, 13, 'GOOD', SYSTIMESTAMP);
