INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '요즘 도시락 케이크 가게도 많은데 그 가격이면 피오니 케이크 미니로 사는게 더 나은거 같아요! 맛도 가격도👍 친구 생일에 미니 케이크 구매했는데 셋이서 먹기 딱 좋았어요😙', 260, 75, 'GOOD', SYSTIMESTAMP);
