INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '프레지어 7500 딸기생크림케이크 7000 주말 5시반인가 갔는데 대기팀이 많더라구요 한 4~5팀? 포장은 줄 안서도 되길래 포장해왔어요 제가 딸기생크림케이크 좋아해서 여러곳을 먹어봤지만 피오니만한 곳 못 본것같아요 생크림과 시트에서 달달한 맛이 나는 딸기생크림케이크st인데 제가 좋아하는 스타일의 딸기생크림케이크에요 그리고 사실 프레지에는 그냥 사본건데 프레지에가 너무 맛있어서 놀랐어요 무슬린 크림이 진짜 맛있더라구요 크기는 작지만 너무 맛있어서 다음에는 프레지에 사러 다시 가고 싶어요', 40, 4, 'GOOD', SYSTIMESTAMP);
