INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '딸기 🍓 생크림 케이크 🎂  에 홀딱 빠졌어요. 2호 큰거를 한번에 휘리릭 흡입한답니다. 커피도 짱 맛있어요. 거리만 가까우면 매일 가고 싶어요 ㅎㅎ', 28, 5, 'GOOD', SYSTIMESTAMP);
