INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '예상치 못한 보냉백 가격이 꽤 나가네요. 그래도 없으면 케익이 금방 녹을 것 같아요. 딸기철이 아니라 딸기가 달진 않지만 생크림과 새콤달콤 조화가 좋아요.', 20, 4, NULL, SYSTIMESTAMP);
