INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '우와.... 진짜 너무 맛있어요. 케이크 너무 부드럽고 딸기쥬스도 와 상큼 그 자체. 걸어다니다 그냥 맛있어 보여서 들어갔는데 맛집이었네요ㅜㅜㅜ 케이크 사올 걸 하고 후회돼요....ㅎ 또 가고 싶네용 :)', 18, 5, 'GOOD', SYSTIMESTAMP);
