INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '역시 피오니는 오리지널 메뉴인 딸기 생크림 케이크가 제일 맛있는 거 같아요 ~ !! 아주 오랜만에 들린 곳이었는데 이전 하기 전 추억의 맛과 똑같네요 ♥️ 조만간 블로그 포스팅 써야겠어요 ~', 67, 17, 'GOOD', SYSTIMESTAMP);
