INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '케이크가 진짜 다양하고 레알 존맛!!!! 여기 케이크 생일때 선물하면 진짜 사랑받아요!! 너무 부드럽고 맛있어요!!😍😍 커피도 부드럽고 핸드드립인데 진짜 잘 만들어요!', 4, 0, 'GOOD', SYSTIMESTAMP);
