INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '초코케잌은 처음 먹어봤는데 역시 대존맛 ! 초코가 적당히 달고 바나나와의 밸런스가 좋음. 근래 먹은 케잌 중 가장 만족도가 높았음.', 75, 11, 'GOOD', SYSTIMESTAMP);
