INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '몇 년만에 방문했는데도 변함 없이 맛있었습니다. 다만 생크림 케이크가 달기 때문에 같이 마실 음료로 핑크레몬에이드는 비추천합니다.', 45, 8, NULL, SYSTIMESTAMP);
