INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '초코딸기와 딸기생크림을 먹었습니다 솔직하게 말하자면 이게 왜 그렇게 유명한건지, 웨이팅까지 하면서 먹어야 하는 케이크인지, 잘 모르겠어요... 이 가격에, 이 케이크를, 굳이 먹겠다고 홍대를 올 필요성도 못느끼겠어요. 집근처에 이정도 맛의 7천원대 딸기케이크는 어디서도 팔지 않을까 라는 생각? 유명해지면서 퀼리티가 떨어진건지, 원래부터 이 맛이였는지, 아니면 오늘이 유독 맛이 없던 날이였는지.. 전.. 모르겠습니다. 커피는 드립커피 6종류 원두가 준비되어있어서 좋았지만 그래요 그게 끝이네요. 커피 맛은 괜찮았습니다,', 56, 13, 'BAD', SYSTIMESTAMP);
