INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '여자친구랑 돈까스 먹고 디저트로 딸기 케익 먹으러왔는데  녹네요녹아! 맛있긴한데 상남자인 제가 먹기에는 케이크가 좀 작은것같아요. 아 여자친구랑 먹어서 더 맛있습니다 ^^😍', 98, 23, NULL, SYSTIMESTAMP);
