INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '딸기케이크 여전히 맛있지만 제가 방문한 날만 좀 이상했는지.. 생크림 딸기케이크 빵이 약간 퍼석하더라구요. 초코케이크는 괜찮았는데..!! 약간 복불복이네여 ㅋㅋ', 46, 4, NULL, SYSTIMESTAMP);
