INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '딸기케이크가 유명하다해서 사서 선물줬어요~~ 10년 넘은 가게라던데 이미 말다한거 아닌가싶네요~ 가게 안에서 드시는 분도 만석이고ㅎ 미니사이즈(24000원) 케이크가 잇어서 좋앗어요', 67, 13, NULL, SYSTIMESTAMP);
