INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '크리스마스 기념 딸기케이크 샀어요! 예약 못해서 퇴근하자마자 들렀는데 다행히 겟!! 처음 먹어본건데 너무 맛있네요...ㅜㅜ 우유맛 진한 생크림에 속까지 차있는 딸기 최고 ♥ 주문 받아주시는 직원분도 너무 젠틀하고 친절하셨어요 (*´꒳`*)', 21, 0, 'GOOD', SYSTIMESTAMP);
