INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), 'ㆍ생크림 딸기케이크 입문하기 좋은 케이크 전문점 ㆍ언제나 손님들이 많아 주말에 웨이팅은 필수 ㆍ맛이 전보다 덜한것 같은건 기분탓인지..', 39, 7, NULL, SYSTIMESTAMP);
