INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '테이크아웃으로 딸기케이크 포장해왔어요. 예전보다 크기는 작아진듯하지만 여전히 너무 맛있네요. 생크림딸기케이크는 언제나 피오니가 최고..!', 77, 16, 'GOOD', SYSTIMESTAMP);
