INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '홍대 피오니 케이크, 딸기 생크림 케이크로 유명하다는 건 이전부터 알고 있었기에 한 번은 방문해보고 싶었어서 평일 목요일 오후 8시 넘어서 방문하니 조각 케이크가 없길래 네명이서 한 판 시켜 먹었어요! 일단 한 판을 시키니 음료는 시키지 않아도 된다며 친절하게 응대해주셔서 한 번, 케이크 시트 사이사이에 가득한 딸기에 한 번 반했어요 🍓 괜히 저녁 시간에 가면 품절 되어있고 주말엔 웨이팅 있는게 아니네요 🫶 카페 내부엔 자리도 은근 많고 아늑하며 인테리어도 예뻤어요! 생크림도 느끼하다는 생각이 들지 않아서 좋았고 위에 토핑도 깔끔하게 예뻐서 잘 먹었습니다! 인원이 된다면 조각 케이크보단 한 판으로 구매해 먹는걸 추천드려요 ~ 🍀', 1, 3, 'GOOD', SYSTIMESTAMP);
