INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '피오니 케이크로 미리 메리크리스마스 했습니다♥ 다른케이크집은 딸기가 정말 맛이없는데 여기딸기는 정말 신선하고 상큼 달콤해요... 정말 케이크를 입에 넣는 순간 사르르 녹아요...♥ 언제 한조각먹었는지 순삭 해버리는 마법의 케이크!', 75, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '아는것만 5-6번 혹은 그 이상 이사다녀서 불편했는데 이제는 자리를 잡은건지.. 오랜만에 갔는데 예전만 못하네요.. 딸기케잌으로 유명해진곳인데 생크림도 줄고 딸기양도 현저히 줄고.. 크기도 줄고..빵은 푸석하고..직원분들은 안 친절하시고(불친절은 아님,안 친절) 드립커피로 바꼈던데 설명도 안해주시고 물어봐도 원두 설명 못하시고 그냥 고르라고 하고; 그리고 이용시간 한시간 뭔가요? 아무리 유명한곳 가도 한시간인곳 본적 없네요. 그냥 빨리먹고 나가라 아닌가요? 이런곳 처음봄;;; 좌석도 다닥다닥 옆사람이랑 일행인줄; 정말 오래동안 다닌곳인데 이제 안갈거같아요.. 초심도 맛도 싹 다 잃은듯. 여러모로 진짜 대 실망하고옴.', 60, 11, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '피오니하면 역시 디저트 피오니 디저트하면 딸기 빙수가 고봉밥처럼 나와서 별 생각없이 입에 넣었는데 넣자마자 사르르륵 녹으면서달달한 맛 딸기청에 올려먹어도 맛있지만 그냥 먹어도 맛있어요 딸기 조각케이크 뭔데 뭐이리 생크림이 부드러운건데 진짜 생크림이 부드러워서 아 이래서 웨이팅이 많구나라고 생각이 들었습니다 커피는 드립커피여서 시간이 10~15분?정도 걸리고 원두를 선택해서 먹을 수 있다는게 좋았습니다 단점은 차마 샷추가를 못 말하겠다는 점..?달달한 하루였습니당ㅎㅁㅎ', 47, 8, 'GOOD', SYSTIMESTAMP);
