INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '피오니케이크 7년 넘게 이용하지만 늘 맛있고 한결같고 떨기생크림케잌 가격도 합리적이에요!! 레터링이나 제작케이크보다 훨씬맛있고 크림이 느끼하거나 너무 달지도 않고 맛있어요. 딸기도 안익거나 신것없이 늘 맛있어요^_^', 57, 12, 'GOOD', SYSTIMESTAMP);
