INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '홍대 디저트 맛집 피오나 대기 5분정도~ 수요일 평일인데도 워낙 인기 디저트 맛집이라~ 1시간 이용시간이라서 아쉽긴 했어요 ㅜㅜ 먹으면서 수다 떠느라 시간이 순삭~ ㅜㅜ', 113, 20, NULL, SYSTIMESTAMP);
