INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '먹자마자 크림이 부드럽게 녹는 딸기 생크림 케이크 피오니하면 이 케이크가 유명하죠 덤으로 더치커피도 깊이가 있고 참 좋았어용!!!', 36, 3, 'GOOD', SYSTIMESTAMP);
