INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '딸기케이크 워낙 유명해서 먹어봤어요! 가격이 좀 높은  편이지만 싱싱한 딸기가 많이 있도 생크림이 너무 달지않게 부드러워요 맛있는 딸케였어요', 49, 5, 'GOOD', SYSTIMESTAMP);
