INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '아 최근 중 가장 충격먹었습니다. 홍대 딸기케이크 대장? 진짜 이게 맞나요..? 동물성+깔끔함 의 딸기케이크 일뿐.. 2023년 기준으로는 왜 극찬받는지는 모르겠습니다. 식물성크림이 주로 사용될 때는 동물성생크림 사용만으로도 센세이션했을 수는 있겠지만.. 그냥 딱 기본입니다.. 최근 기준으로는 극찬할 정도인지는..모르겠어요 정말..', 300, 61, 'BAD', SYSTIMESTAMP);
