INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '근처 가방가게 들렀다가 유명해도 사람 너무 많아서 지나치려고 했는데 지나가는 사람들이 맛있다는 말에 방문!! 맛있다는건 못참지ㅋ 원두 선택할수 있어서 좋아요 산미 안좋아해서 코스타리카1 과테말라1 커피 맛있고 케이크도 소문대로 맛있네요 너무 달지도 않고 크림 부드러워요', 34, 3, 'GOOD', SYSTIMESTAMP);
