INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '홀케이크 샀는데 고정핀이 없어서 살짝 아쉬웠어요 먼거리로 가져가는데 지옥철까지 타고 돌아가느라,,그래도 무사히 사수해서 맛있게 먹었습니다ㅎㅎ', 7, 3, NULL, SYSTIMESTAMP);
