INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '오~! 호텔 케잌에 준하는 맛있는 딸기케잌입니다. 생크림 아주 고소하고 딸기 신선하고 달아서 아주 좋습니다. 저녁에 샵 들어갈때 사람 많길래 제대로 찾아왔다 싶었는데 역시나 굳이네영! 다음엔 다른거 홀케잌 먹어봐야겠습니당', 48, 5, 'GOOD', SYSTIMESTAMP);
