INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '매장이 크고 깔끔해서 좋았고 케이크가 엄청 촉촉하고 폭신하면서 부드러워서 좋았어요❣️ 아쉬운 게 있다면 셋이 앉기에는 책상이 너무 작네요ㅠㅠㅠ', 39, 3, NULL, SYSTIMESTAMP);
