INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '홍대,연남 이 시기에 가야 피오니 딸기 케이크를 만날 수 있어요!!!! 친구 생일에 딸기케이크 선물하려고 구매해서 갑니다~ 생파에 필수 피오니 딸기케이크🍓🍰', 8, 8, 'GOOD', SYSTIMESTAMP);
