INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '점심 식사후 찾은 카페~드립커피(콜롬비아) & 딸기빙수 주문!! 배가 너무 불러서 딸기케익은 먹어보진 못했지만 딸기빙수로도 만족!!^^', 33, 10, 'GOOD', SYSTIMESTAMP);
