INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '처음 생겼을때부터 쭈욱 여전히 핫한 피오니! 갑자기 홀케이크가 필요했는데 피오니가 있어서 너무 다행이였습니다 다른곳들은 주문제작이나 예약을 해야하는데 피오니는 당일방문으로 홀케이크를 구매 가능합니다 정말 좋은시간 보냈네용 빠르고 정성스러운 포장과 안내에 감사합니다', 82, 16, 'GOOD', SYSTIMESTAMP);
