INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '1인1케잌 해야해요🍰 너무 맛있고 양이 많지 않아서 금방 없어지거든요 먹고 아쉬워서 프레지아도 하나 더 시켰는데 그냥 케잌을 하나 더 시킬걸 후회했음 맛없는건 아닌데 케잌에 비하면 좀 쏘쏘였어요 카페를 웨이팅해서까지 들어간건 첨인데 시간이 아깝지 않았습니다! 또하나 단점은 내부에 테이블 수가 많고 서로 붙어있는 편이라 좀 시끄럽고 답답하게 느껴질 수 있어요 전 좀 기빨려서 오래있지 않고 후딱 먹고 나왔네요', 2, 6, NULL, SYSTIMESTAMP);
