INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '와~완전 속았네요!! 맛있을줄 알았는데 딸기도 시큼하고 속에 있는건 거의 물러서 더 시큼한 맛이 강해서 배탈날까봐 못먹었어요. ㅠㅠ; 영하 10도 저녁에 사서 냉장고 바로 보관했고 담날 먹었는데 이래요~~빵도 싸구리 맛이 나서 다른곳보다 비싼데 파리바게뜨 냉동케익 맛과 비슷하네요. 알바 리뷰라도 쓰나봅니다. 밑에 사진만 봐도 그렇네요!! 세상에 추운날 골목 찾아가서 사온건데 실망 대박입니다. 가지 마세요~ㅠㅠ;;', 77, 14, 'BAD', SYSTIMESTAMP);
