INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '딸기 생크림 케이크가 정말 맛있네요 :) 생크림 맛이 아주 좋아요! 딸기는 생각보다 많이 들어있진 않은듯…그래도 상큼하고 맛있어요!!! 매장이 바쁜데도 직원분들은 친절👍🏻 저희는 포장했는데…매장안이…거의 시장통^^; 인기가 많은 카페니 좌석이 많아서 그런지, 카페 앉아서 여유로운 시간을 보내기엔..? 엄두가 안나는 매장이었어요 ㅋㅋㅋ', 69, 18, NULL, SYSTIMESTAMP);
