INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '딸기케익 유명해요 맛있음… 밤에가니 딸기 조각케익 하나 겨우포장했네요 10년 가까이 자리잡고 하는것도 대단하다 생각됨 근데 케익 생크림에 앉은 옷먼지?는 좀 그래요.. 뭔 니트 털 날린건지 관리좀 해주세요', 35, 4, NULL, SYSTIMESTAMP);
