INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '오늘 처음 가봐서 방문했는데 직원들도 친절하시고케잌이랑 커피도 다 맛있었습니다 케잌이 딸기 맛이나 더욱더 맛이 있었습니다 다음에도 또 방문할게요 ^^', 27, 7, 'GOOD', SYSTIMESTAMP);
