INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '딸기와 관련된 다양한 케익과 빙수가 있어요. 빙수와 케익 모두 맛있게 먹었어요.빙수는 토핑이 따로나오고 그렇게 먹어야 맛있다네요. 카드내역에 주문내역이 나오지 않고 총금액만 나와요. 이건 아쉅네요. 딸기생각날때 다시 올것 같아요', 20, 6, NULL, SYSTIMESTAMP);
