INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '모든 업종 불문하고 올 해 가본 곳 중 가장 불쾌하고 최악의 경험을 준 곳입니다. 1분도 되지 않는 짧은  시간 동안 이렇게 기분을 더럽게 만들어 줄 수 있구나 하는 놀라운 경험을 했네요. 전날 전화로 크리스마스 케잌을 예약하고 현장 결제 하겠다는 연락 후 방문하였으나 응대직원은 전혀 말귀를 못 알아 듣는것은 물론 똑같은 질문만 반복하여 그 때부터 당황하게 만들었습니다. 예약 메모 및 코맨트는 전혀 전달이 안된것 같았으며 결제시 바로 픽업해야한다는 부분만 반복하여 말해주네요. 아니 크리스마스에 가져갈 거 지금 계산하러 온거라구요.. 아.. 답답.. 예약은 왜 받는거니?? 계산할때까지 기분 나쁘게 하고 계산시 굉장히 짜증 섞인 말투로 카드 리더기에 카드를 막 긁는 추악한 행동까지 하네요. 대단하네요. 여기.', 30, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '막내 학원도 바래다줄겸 와이프와 홍대합정 데이트 겸 매주 놀러오고 있어요. 오늘은 원래 가던 커피숍이 없어져서 주변 검색을 하다가 우연히 찾아서 방문했는데 이렇게 예쁜 매장이 있는지 몰랐네요. 딸기빙수와 초코딸기케이크에 아메리카노 두잔, 녹차라떼 한잔, 아이스초코 한잔 주문했어요. 매장 이용시간은 한시간 제한이 있지만 오늘 같이 더운날 냉방도 빵빵하고 매장도 이쁜데 디저트가 정말 너무 예쁘고 맛있어요. 커피와 음료도 맛있어서 좋아요 매주 방문 해야겠어요.', 62, 11, 'GOOD', SYSTIMESTAMP);
