INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '겉으로 볼 때 생크림 결이 살아있어서 좋았어요 맛은 생크림에서는 우유 맛이 나서 고소했고 딸기는 두툼하고 달달했어요 그리고 빵 자체가 달아서 맛있었어요', 128, 20, NULL, SYSTIMESTAMP);
