INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '그동안 먹었던 것과는 너무 달라요... 오랜만에 크리스마스 기념으로 구매했는데 안에 딸기가 너무 없고 물러터졌어요. 너무 실망했습니다. 이럴줄 알았으면 안샀을텐데..', 114, 26, 'BAD', SYSTIMESTAMP);
