INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '아주 오래전에 맛있게 먹었던 피오니 케이크가 먹고싶어서 방문했습니다 조용하고 아늑한 분위기에 음악도 좋았고 커피도 케이크도 맛있게 잘 먹었습니다 -딸기 슬라이스가 조금 더 추가되면 좋을 것 같습니다👍🏻', 30, 0, 'GOOD', SYSTIMESTAMP);
