INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '딸기빙수 맛있어요!! 우유+연유 맛 같은데 토핑이랑 같이 먹으니까 맛있었어요 시원하게 잘 먹었습니다😋 매장 되게 넓은데 사람 많으면 이용시간 1시간으로 제한하고 있는 것 같아요 주말 오후에는 웨이팅 있을 것 같네요 다음엔 커피도 맛보러 오고싶어요~', 17, 5, 'GOOD', SYSTIMESTAMP);
