INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '딸기케이쿠랑 다크초코치즈 케익 존맛이에요 더 달달한 건 다크니까 달달한거 좋아하시는 분들에게는 초코 추천합니당 ! 그리고 여기도 한시간 시간 제한 있어요', 91, 19, 'GOOD', SYSTIMESTAMP);
