INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '초코 생크림 딸기/ 딸기빙수 원래는 생크림 딸기 먹을려했는데, 초코보니까 초코에 끌려서 먹은~ 달달하고 상큼해서 맛있게 먹었네요ㅎ 딸기빙수는 딸기청을 붓는 형식이 아니라 떠먹는 형식인데 달달해서 그냥 먹어도 맛있었고 색달라서 좋았어요ㅎㅎ', 69, 14, NULL, SYSTIMESTAMP);
