INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '방문하기 전 이곳이 딸기케이크 맛집인줄은 알았는데 기대 안했던 바닐라라떼가 정말 맛있었어요 ! 적당히 달면서 바닐라향도 나서 만족하면서 마실 수 있었습니다! 바닐라라떼는 원두를 선택할 수 없었지만 맛있었고, 원두를 고를 수 있던 아메리카노도 한입 뺏어서 먹어봤는데 체인점에서 맛봤던 아메리카노보다 산미가 없어 쉽게 마실 수 있었습니다 🤍 아 그리고, 케익이랑 빙수 같이 시켜먹을 땐 꼭 케이크를 먼저 먹고 빙수를 드시는 걸 추천해요! 빙수가 워낙 달아서 빙수 먹고 케이크 먹으면 케이크의 단 맛이 느껴지지 않거든용!', 94, 26, 'GOOD', SYSTIMESTAMP);
