INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '딸기 생크림 케이크 먹고싶어서 네이버 검색하다 방문했는데 피오니 짱맛입니다. 내부에 사람 많고 1인 1케이크 하려했는데 재료가 저희 마지막 1개로 끝나버렸네요ㅠㅠ 인기가 많은 탓이겠죠 재료가 없어서 아쉬운거 빼곤 맛있었어요', 51, 15, NULL, SYSTIMESTAMP);
