INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '과테말라 커피 맛있어요. 커피 양이 너무 적어요. 케이크도 딱히 맛있는지 모르겠구요. 이뻐서, 후기보고 방문했는데 딱히… 추천은 그리고 좌석 간격이 넘 좁아서 사람도 많은데 조금 걱정이 됐습니다', 39, 6, NULL, SYSTIMESTAMP);
