INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '맛집이라고 해서 갔는데 웨이팅만 길고 맛은 별로여서 아쉬웠어요! 안에 들어가니 테이블간 거리도 좁아 다니기 힘들었고 너무 시끄러워서 지인이랑 소리지르면서 말했네요.. 커피는 그냥 그랬고 케이크는 생각보다 촉촉하지 않고 퍽퍽했습니다 재방문 의사 없어요😢', 30, 8, 'BAD', SYSTIMESTAMP);
