INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '워낙 유명한 곳인건 익히 들어 알고있었어서 나름 기대를 하고 갔는데 음 그냥 딸기빙수예욬ㅋㅋ얼음만 먹어도 엄청 달아요 안에 따로 고명이 없고 해서 이걸 11000원에...먹으라면..전 그냥 설빙갈것같아요..ㅎㅎ 그리고 사람이 되게 많고 사장님처럼 추정되시는분이 계속 도시면서 다 먹은 사람 언제가나..약간 초조(?)해보이셔서ㅋㅋㅋㅋ 후다닥 먹고 나왔어요 사장님이 막 나가라고 하신건 아니지만ㅋㅋㅋ그냥 너무 정신없어요 한번 와본걸로 아주 충분하네용', 16, 9, 'BAD', SYSTIMESTAMP);
