INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '맛있어요 근데 직원중에 안경쓰신 직원 서비스교육이 전혀 안돼어 있네요 빙수 받았을때 감사합니다 말씀드리니 멀뚱멀뚱 쳐다만 보셔서 그려러니 했습니다 빙수 다 먹은 후 잘 먹고 갑니다 말씀 드리니 처음과  마찬가지로 보고만 계시네요 빈말이라도 "네" 라도 말씀하시는게 그리 어려우신가요? 일하는게 힘드신가요? 서비스의 기본은 인사 아닌가요? 먼저 인사하라는게 아니고 고객, 손님이 정중히 인사를 하면 받아주시는 척이라도 하세요 매우 불쾌합니다 안경쓰신 직원분', 9, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '딸기케이크로 유명한 카페! 맨날 지나칠때마다 줄 서있기도 했고 갈 때마다 줄 서있어서 못 먹었는데 오늘은 줄도 없고 그래서 바로 들어감!! 푸딩 같은 거 이름이 잘 생각 안나는데 저게 엄청 맛있다!!🤤 부드럽고 탱탱한게 엄청 맛있다. 추가적으로 딸기케이크도 시켰는데 그건 사진이 없으니 리뷰는 패스~~ 😊😊😊😊', 56, 16, 'GOOD', SYSTIMESTAMP);
