INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '딸기케이크 깔끔하고 무난했습니다! 힙한 분위기여서 그런지 주말 오후 시간대 기다리시는 분들이 좀 있으시네요! 테이크아웃 케익 메뉴 따로 있습니다', 25, 3, 'GOOD', SYSTIMESTAMP);
