INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '딸기케이크 맛집! 딸기철이 아니라 딸기자체는 아쉽지만 크림자체가 많이 안달고 맛있어서 끝없이 들어간다 커피 원두도 다양하고 맛있다 🌸', 30, 6, 'GOOD', SYSTIMESTAMP);
