INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '주말 오후에 웨이팅이 30분 넘게 있었지만 엄청 달지도, 너무 배부르지도 않고 좋았어요. 물리는 맛도 아니고 정말 고급스러운 맛이었습니다.', 38, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '테이크아웃만 줄서서 하다가 이날은 자리가 있어서 매장 첨 이용해봤는데 좋았어요 초코바나나 케이크 새로 나온 것도 맛있고 딸기 쥬스도 맛있고 딸기 케이크도 맛있고 깔끔하면서 촉촉 단 맛 케이크 맛집 최고입니다😄최고최고짱짱', 64, 12, 'GOOD', SYSTIMESTAMP);
