INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '딸기 케이크를 워낙 좋아해서 예전 위치에 있을때도 찾아와서 먹었는데 딸기 케이크는 예전보다 좀 퍽퍽해진 느낌이였습니다 딸기도 단 딸기는 아니였어요 그래도 케이크 맛이 워낙 좋아서 만족스러웠습니다 기대 안했던 초코 바나나 케이크가 더 인상 깊었어요 다시 사먹고싶네요 ㅎ 커피도 여러 원두 있어서 고르는 맛이 있고 드립커피라서 맛있게 먹었습니다', 85, 11, NULL, SYSTIMESTAMP);
