INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '엄청 오랜만에 방문했는데 여전히 맛있어요. 주말 웨이팅 많고 테이블 1시간 제한 있어서 오래 머무르기엔 적합하지 않지만 다 먹는 데는 지장 없어요!', 45, 8, 'GOOD', SYSTIMESTAMP);
