INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '딸기 쇼트케이크가 유명하대서 친구와 함께 방문! 인기가 많아 그런지 사람이 굉장히 많고, 테이블 이용 시간이 1시간으로 정해져있었지만 디저트가 너무 맛있어서 좋았습니다.', 11, 1, 'GOOD', SYSTIMESTAMP);
