INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '피오니'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '원래 먹던곳이라 갔습니다 직원분들 친절하신데 픽업때 두개 주문했는데 한개만 주심 그리고 말씀드려야지 주시더라구요 ? 먼저 확인 하시고 주시면 좋을거같아요 남자직원분', 3, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '주문한 메뉴는 딸기 크림브륄레 크레페.단비라떼.제주청귤티 딸기 크림브륄레 ..크레페위에 커스타드 크림을 얹고 토치로 바삭하게 구워낸 브뤌레.. 엄청 달까봐 걱정했는데. 적당히 달아서 넘 맛있었어요. 보통 크레페는 넘 달아서 먹다가 버리는데..이건 끝까지 다 먹었어요. 그 정도로 넘 달지않고, 고급진 맛이었어요 단비라떼는 저에겐 약간 연한 듯했지만, 친구는 적당하다 그러더라구요. 참고로 전 커피 샷 추가해서 먹어요 끝맛은 깊고 풍부한 고급진 커피맛이 느껴지더라구요 청귤티는 아이스티 아니고 ,티에요. 그래서 달지 않아요 첨엔 이것도 연한듯 하지만, 마시다보면 깔끔하고 상쾌함이 전해져서 좋더라구요. 음료 둘다 마실수록 더 맛있는 느낌이었어요', 5, 6, 'GOOD', SYSTIMESTAMP);
