INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '와.. 여기 쿠앤크바나나 ㅠㅠㅠ 미쳤어요 바나나도 가득한데 쿠키도 가득하고 달달한 완충하고 갑니다✨ 그리고 크레페가 완전 촉촉하면서 바삭한 부분도 있고 진짜 갓나와서 그런지 너무 맛있었어요 단비라떼는 뭔가 너무 달지도 않으면서 딱 적당한 당도였고 아이스티는 새콤하고 달콤한맛이 나는데 되게 맛있었어요!!', 128, 26, 'GOOD', SYSTIMESTAMP);
