INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '홍대 레드로드 메인 스트릿에 있어요. 수노래방에서 러쉬 쪽으로 가면 있는데 크레페 진짜 맛있어요!!! 딸기도 맛있고 녹차는 안 먹어봤는데 녹차브륄레 크레페 진짜 특이하고 맛있을 것 같아요. 주문하자마자 만들어주셔서 완전 따끈따끈합니당 홍대 디저트 맛집으로 인정인정👏☺️💙', 26, 5, 'GOOD', SYSTIMESTAMP);
