INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '홍대 크레페 맛집 저스트단비 맛있는 이색디저트를 찾는다면 저스트단비 음료도 맛있고 크레페 굿!! 한개가 금방 순삭 넘 맛나요 먹으면 먹을수록 맛있는 크레페 맛집 여기서 만날수 있어요!!!!!', 20, 6, 'GOOD', SYSTIMESTAMP);
