INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '딸기브륄레+소스누텔라+아이스크림 조합이 미쳤어요 ㅎㅎ… 진짜 겉이 바삭바삭 속은 촉촉한 단맛이어서 식감이 너무 좋았답니다:) 그리고 사장님이 추천해주신 단비라떼도 살짝은 달달하면서 넘나리 맛있었어요. 오늘 회사에서 스트레스 엄청 받은 날이었는데 후.. 단비라떼 덕분에 위로가 되네요~~~👍🩷❣️ 크레페도 꼭 드셔보세요잉ㅠㅠㅠ🫶🥹', 36, 8, 'GOOD', SYSTIMESTAMP);
