INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '홍대 저스트단비 다녀왔는데 크레페 진짜 맛있네용!!!! 제거 먹은 건 딸기 크레페였는데 안에 누텔라가 발려 있어서 달콤함이 두 배~~~겉은 얇고 쫀득, 안은 부드러운 크림과 딸기가 가득해서 한입 먹자마자 행복해져요ㅋㅋㅋㅋ같이 마신 아메리카노는 깔끔했고, 단비라떼는 부드럽고 고소해서 크레페랑 찰떡 조합이에요ㅎㅎㅎ가게 안이 아늑하고 분위기 좋아서 데이트 코스로도, 가족들이랑 하나씩 들고 먹기에도 딱 좋아요!❣️ 다음에 홍대오면 또 올거예요~~👍👍', 19, 2, 'GOOD', SYSTIMESTAMP);
