INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '가뭄의 단비처럼 달콤하고 부드러워요~ 단비라테는 올여름 필수품인거 같아요!! 달콤한게 더위에 지친몸과마음 완충 해줍니다~!! 크레페 크림브륄레 바삭 달달하고 그 안에 크림 풍성히들어있어서 행복 그자체입니다🤤😍', 17, 2, 'GOOD', SYSTIMESTAMP);
