INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '지난번에 딸기 시즌에 여자친구랑 와서 먹었는데 너무 맛있었어서 홍대쪽에 일정이 있어서 다시 한번 오게되었습니다! 매장도 깨끗하고 사장님도 친절하시고 크레페가 너무너무 맛있어요 ㅠㅠ 다음에도 또 재방문 예정입니다!', 55, 11, 'GOOD', SYSTIMESTAMP);
