INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '크림뷔렐레 크레페 특별해서 꼭 먹어보고 싶었는데 맛있네요!! 단비라떼는 포근포근한 거품이 마음에 들었고, 커피향이 은은해서 좋았어요! 딸기라떼도 은은한 맛이라 부담스럽지 않았어요!! 맛이 강하지 않은 음료 좋아하시는 분들께 추천!!! 크레페 맛집이네요💗', 58, 15, 'GOOD', SYSTIMESTAMP);
