INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '홍대 레드로드에 왔다면 크레페를 꼭 먹어주기 !!! 사장님도 너무 친절하세요 ㅎㅎㅎ 크레페 종류가 다양해서 고르는 재미가 있고, 같이 마실 음료도 있으니 쉬었다 가기 너무 좋아요 ! 달달한 크레페로 당충전 하세용>_<!!', 39, 2, 'GOOD', SYSTIMESTAMP);
