INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '오랫만에 오는 저스트단비♡우리집과는 서울 동쪽끝에서 서쪽끝이라 맘먹고 와야만 하는곳😭😭어릴땐죽순이었는데🤣🤣🤣언제나 친절하고 깔끔하고 맛있고~애정하는 크레페가게♥♥♥♥진짜 뜨거운 태양을 맞으며 왔어도 한입 먹으면 피로가 사르르~ 매일먹어도 좋을만큼 맛있는 크레페와 시원한 청귤차 & 커피도 맛있는 저스트단비♡♥♡♡♡♡♥♡', 16, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '“브륄레 맛집“ 오늘 홍대왔다가 너무 더워서 시원한음료 생각에 방문 했었어요 브륄레가 있어서 주문해봤는데 정말 맛있었어요!!  매장이 조용하고 깔끔해서 개인적으로도 마음에 정말드는 매장입니다 홍대 메인거리 근처에 위치해있어서 자주 오게 될거같아요!!', 24, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '인스타에서 핫한 크레페 먹으러 왔어요ㅎㅎ 브륄레 크레페는 설탕 코팅 깨먹는 재미도 있고 요즘 핫한 말차맛도 있어서 너무 좋았어요! 홀에 좌석도 있어서 여름에 걸어다니면서 먹기 힘든데 편하고 시원하게 앉아서 먹고갈 수 있어서 너무 좋아요! 더 자세한 리뷰는 🔻🔻🔻', 76, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '친구랑 일 년만에 만나서 기분전환이 필요했는데! 달달구리하구 기분 좋게 시간 보낼 수 있어서 너무 좋네요!! 크레페 아이스크림 꼭 추가하세요!! 진짜 맛있어요!! 지인들에게 추천하고 싶은 맛집이네용!! 번창하세용 ◡̈', 43, 10, 'GOOD', SYSTIMESTAMP);
