INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '아이와 함께 홍대 거리 걷다 우연히 들른 저스트단비크레페! 딸기녹차브륄레랑 더블딸기크레페(누텔라 소스) 조합이 진짜 미쳤어요. 단비라떼랑 복숭아젤리블랙티(ice)도 달달하니 디저트랑 찰떡이었고요. 리뷰 남기니까 겐지코프레 2종(초코, 바닐라)까지 챙겨주셔서 기분 최고였어요. 달콤한 휴식 원하신다면 이 조합 추천합니다!', 64, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '홍대에서 크레페하면 여기가 떠오를 정도로 진짜 꾸준히 맛있는 곳이에요 친구들이랑 나눠먹기에도 좋은데 맛있어서 항상 1인 1크레페 하게 되네요 ㅎㅎ 사장님도 진짜 친절하시고 이번에 신메뉴도 나왔다해서 먹어봤는데 진짜 취향저격 ㅠㅠ 디저트라서 커피랑도 잘 어울리는데 단비라떼도 추천!', 19, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '끝쪽에 빠삭 안쪽에는 쫀득한 크레페여서 너무 맛도리네요..! 위에올라간 딸기도 크고 신선해서 너무 맛있었지만 안쪽에도 딸기가 콕콕 박혀있어서 끝까지 맛있게 먹을 수있었어요! 안에 들어가는 슈크림도 맛있어서 크레페맛집 ㅇㅈ입니다', 75, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '처음 왔는데 사장님께서 엄청 친절하시고 크레페 종류도 다양하고, 크림브륄레랑 딸기크레페 시켰는데 넘 맛있어요~ 테이블 네개정도 있고 좌석도 꽤 있어서 머무르기 좋네요!', 19, 8, 'GOOD', SYSTIMESTAMP);
