INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '홀대에 말차 크레페 맛집으로 유명해서 와봤는데 너무나 맛있고 감성 있어서 또 올거 같아요!!! 무엇보다 생각보다 안에 테이블이 많아서 좋았던거 같습니다!', 46, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '우연히 방문한 크레페 가게인데 크레페가 너무 너무 맛있는 크레페 맛집이었어요💛 달달한 크레페와 아이스 커피를 함께 먹으면 최고의 조합이랍니다 ..👍🏻 저는 기본 크림브륄레를 먹었는데 다른 맛도 너무 맛있을 것 같더라고요 ! 그리고 사장님이 친절하셔서 더욱 더 좋았습니다 :)', 12, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '크레페 달달하니 맛있네요! 커피랑 같이 먹으니 피서지가 따로 없어요 ჱ̒ ｰ̀֊ｰ́ ) 여자친구들은 무조건 좋아할 맛이니 데이트코스로 딱입니다', 16, 8, 'GOOD', SYSTIMESTAMP);
