INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '딸기녹차브륄레는 위에 큰 딸기가 하나 얹혀있고 그 밑에 브륄레가 있고 또 그 밑에는 녹차크림과 생크림이 잇어요! 브륄레는 달콤하면서 쌉쌀한 게 좋고 또 그 조화가 녹차랑도 잘 어우러져요! 녹차의 진한 맛이 너무 맛있고 크레페도 바삭하고 맨밑까지 딸기가 야무지게 들어있어요! 딸기라떼도 연유?맛도 있어서 단맛이 추가되어 더 맛있었어요!', 11, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '크림브륄레?? 마시쪄요 크림이 입안에 가득차는게 달달구리 더운날 당떨어질때 최고❤️ 커피도 구수하니 시원하고 여름날에 쉬어가는 카페로 쵣오 다음에는 녹차한번 먹어봐야겠어요.', 82, 11, 'GOOD', SYSTIMESTAMP);
