INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '길거리 큰 크레이프를 생각하고 왔는데 그것보다는 크기가 작지만 안에 크림이 많아서 맛있게 먹었어요!! 부드러운 에그타르트 느낌! 커피랑 굉장히 잘 어울려요👍🏻매장은 좀 작은데 음악이나 공간이 뭔가 편안하고 차분해서 친구랑 수다떨기 좋았어요!!!🤤🫠', 0, 8, 'GOOD', SYSTIMESTAMP);
