INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '크레페랑 아메리카노를 시켯는데 아메리카노가 진짜 고소하게 맛있습니다!! 크레페는 그냥 잇길래 시켯는데 여름엔 꼭 아이스크림 추가해서 먹어보세요! 극락입니다ㅎㅎ', 100, 26, 'GOOD', SYSTIMESTAMP);
