INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '홍대에 크레페 생겼다해서 당장 달려옴!! 가성비도좋고 위치도 좋다, 가게는 작고아담해서 포장도 많고 요즘 딸기철 고급진 딸기인가 아주 싱싱하고 달고 크레페 잘못먹으면 느끼하고 달고 물리는데 전혀 사장님이 처음부터 끝까지 수제로 반죽,크림,원두 하나하나 다 신경써서 하신다고 그맛이 느껴진다 먹다보면 손에묻거나 질질 흘리는데 아주살짝은 있지만 과하지는 않은거같아 들고다녀서 먹기 좋을거같다 ㅋㅋㅋㅋㅋ커피도 원두가 맛있음', 58, 14, 'GOOD', SYSTIMESTAMP);
