INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '딸기라떼, 딸기브뤌레,단비라떼 주문했구요. 단비라떼 일반 라떼랑 다르게 고소하고 진짜 맛있네요!💕👍 블뤌레 안에도 딸기 들어있고 저는 누텔라 선택했는데 와👀진짜 맛있어서 순삭했어요! 다른 맛들도 다 먹어보고 싶네요!!', 16, 4, 'GOOD', SYSTIMESTAMP);
