INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '저번에 크레페 먹으러왔다가 맛있어서 두번째 방문했어요! 크레페는 원탑인듯…. 커피도 너무 맛있고 매장 분위기도 너무 좋아요☺️', 73, 11, 'GOOD', SYSTIMESTAMP);
