INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '딸기 크레페 맛나요! 딸기 가득 들은 거 보이시죠 ㅎㅎ 안에 누텔라도 발려져 있어서 끝으로 갈수록 더 맛나더라구요! 단비라떼는 커피아이스크림 맛이랑 유사해서 넘 달달하고 좋았고, 딸기라떼도 넘 진하지 않아서 크레페랑 조화가 잘 되었어요 ㅎㅎ', 89, 11, 'GOOD', SYSTIMESTAMP);
