INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '오후 세시쯤 달콤한게 드시고 싶을때 오셔서 드시면 좋을거 같아요. 크림브뤌레 딸기 크레페 누텔라로 꼭 드셔보세요 진짜 최고에요! 맛있게 잘먹고 갑니다.', 50, 5, 'GOOD', SYSTIMESTAMP);
