INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '크레페 다른데보다 훨 비싸게 팔면서 크레페 먹으러 온 사람들한테 매장 이용하려면 크레페 말고 1인 1음료 해야한다고 하네요.. 그럼 당연히 인당 크레페 하나에 음료 하나까지 나가는데 돈도 많이 깨지고 심지어 크레페도 아주 작고 소중한 크기에용,, 영수증 리뷰 쓰면 주시는 과자도 너무 맛없어서 놀랐고 무엇보다 아이스크림 담아주신 그릇에 먼지가 너무 많아서 이거 먼지 너무 많은데 혹시 새로 주실 수 있냐고 하니까 죄송합니다 말도 없이 원래 있던 프레첼 과자같은거 다빼고 진짜 아이스크림만 퍼주시던데ㅠ 웃긴건 바꿔주신 그릇에 먼지가 훨씬 덕지덕지 붙어있었어요ㅠㅠ 친구랑 같이 인스타그램 찾아보고 설레서 방문했다가 둘이 같이 기분이 너무 상해서 종일 찜찜하게 돌아다녔네요.. 다시는 안갈거같아요', 28, 8, 'BAD', SYSTIMESTAMP);
