INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '홍대 근처에 위치한 크레페&커피 맛집 ‘저스트단비’에 다녀왔습니다!! 살면서 ‘크레페’를 처음 먹어봤는데요 :) 딸기브륄레 크레페 누텔라 맛으로 선택했답니다 위에는 에그타르트처럼 고소하고 달달한 토핑이 올려져있고 먹을수록 누텔라와 딸기가 어우러져 너무 맛있었습니다!! 음료는 단비라떼와 오르조 유기농 커피 먹어봤습니다! 단비라떼는 크림이 달달하면서 커피의 진한 맛도 함께 맛볼 수 있어 크레페와의 조합이 완벽한 이곳만의 시그니처 음료입니다! 오르조 유기농 커피는 100% 이탈리아산 보리를 직접 로스팅해서 만드신 커피맛 보리차입니다! 너무너무 신기했어요 맛은 분명히 커피인데 어디선가 보리의 구수한 맛이 느껴집니다 :) 카페인이 부담스러운 날엔 꼭 드셔보시길 추천드립니다!!', 4, 0, 'GOOD', SYSTIMESTAMP);
