INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '녹차와 딸기의 계절인만큼 녹진한 녹차크림에 쫀득한 반죽과 너무 잘 어울려요! 크림브륄레로 위를 만들어주셔서 달콤쌉싸름의 조화에 부드러움까지 낭낭해서 입이 행복해졌어요! 자세한 리뷰와 네이버클립 영상을 제 피드로 오면 상세하게 확인가능해요! https://m.blog.naver.com/qkrrudcnr/223736696617', 69, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '🧀크림브륄레 좋아하고 크레페 좋아하면 아묻따 방문권장 🍈딸기크레페 한정 출시 🇺🇲미국밀가루 사용으로 쫀쫀하고 식감좋음 🧉누텔라와 로투스잼 택1로 악마의잼 선택가능', 55, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '처음 방문해봤습니다. 기다리는 중에 리뷰 남겨요. 매장은 생각보다 크지는 않고 테이블 4개 정도 있습니다~!! 테이블 착석 시 1인 1음료 주문입니당😊😊 추천 받아서 방문했어요~~!!', 476, 83, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '홍대 크레페 맛집입니다. 딸기에 크림에 브륄레까지 입혀서 정말 달달하고 고소한 디저트였어요. 음료들도 다 맛있는데 시그니처 단비 라떼가 최고였어요.', 25, 10, NULL, SYSTIMESTAMP);
