INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '가게 분위기가 아늑하고 크레페가 정말 맛있었어요 :) 저희는 더블딸기 크레페를 주문했는데, 안에 기본으로 누텔라가 발라져 있어서 달콤한 초코맛과 상큼한 딸기가 잘 어울리더라구요! 겉은 얇고 쫀득하면서 안은 크림이랑 딸기가 가득 들어있어 한입 먹을 때마다 행복했어요ㅎㅎ 음료는 아메리카노랑 단비라떼를 같이 주문했는데, 아메리카노는 깔끔하고 단비라떼는 부드럽고 고소해서 크레페랑 찰떡 조합이었어요. 홍대 오면 또 들르고 싶은 곳이에요 👍', 63, 13, 'GOOD', SYSTIMESTAMP);
