INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '크레페 진짜 맛있어요! 바삭하면서도 쫀득한 식감이 딱 좋고, 안에 들어간 재료들도 신선해서 한입 먹을 때마다 기분 좋아지는 맛이에요. 특히 딸기 브륄레는 달달하면서도 부담스럽지 않아서 계속 손이 가더라고요. 가게 분위기도 아늑하고 편안해서 천천히 즐기기 좋았고, 직원분들도 친절해서 더 기분 좋게 먹고 왔어요. 크레페 좋아하는 분들은 꼭 한 번 와보세요! 다음에 또 올 생각입니다.', 24, 0, 'GOOD', SYSTIMESTAMP);
