INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '점심을 배부르게 먹고 더 이상 들어갈 공간이 없음에도 불구하고 너무 맛있어서 슉슉 들어가는 크레페 다른 집 크레페도 먹어봤지만 중간서부터 질리기 마련인데 여기만큼 처음부터 끝까지 먹을때 질리지 않은 크레페는 처음이에요 저는 크림브륄레를 맛봤는데 윗부분이 설탕 녹인 부분이라 달긴하지만 또 이게 엄청 단맛이 아닌 적당히 단맛이라 맛있어요 안쪽에는 생크림만 들어있는 줄 알았지만 슈크림도 들어있어 맛있는 빵을 먹는 기분도 들구용 라떼랑 먹으면 최고의 조합 커피인 단비라떼도 정말 맛있어요 고소하면서 달달한맛이 슬슬나는게 크레페도 맛있고 커피도 맛있는 카페 크레페 좋아하시는분들은 진짜 꼭 한번 방문해보세요 저는 다음에도 또 방문 할 예정이랍니다', 0, 7, 'GOOD', SYSTIMESTAMP);
