INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '맛있다고 들어서 와봤는데 정말 맛있네요! 사장님도 너무 친절하시고요~ 크레페 먹고 싶을 때 또 올 거예요 💚 녹차크레페는 처음인데 진짜 맛있어요! 녹차좋아하시는 분들 추천드려요 위에 브륄레도 완벽,, 너무 맛있아서 순삭했어용', 20, 8, 'GOOD', SYSTIMESTAMP);
