INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '누텔라크림브륄레를 주문해봤는데요 사장님께서 적당한 단맛의 비율을 맞추기 위해 노력하셨다고 하셔서 먹기전부터 기대기대!!! 누텔라 맛이 진하지 않고 부드러운 식감이 달콤한 누텔라맛이 스쳐가면서 너무 달지 않고 맛있더라구요 👍👍 겉에 크림브륄레가 바삭한 식감을 더했더니 환상의맛! 반죽도 밀가루 이것저것 섞지않고 미국산 100%이고 본연의 맛을 잘 살린 우유와 포천농장에서 키워진 계란을 사용해서인지 크레페 반죽도 너무 부드러웠습니다🩷 함께 먹은 단비라떼도 크림이 부드럽고 고급진 라떼맛이라 달지 않아 좋았습니다.', 44, 4, 'GOOD', SYSTIMESTAMP);
