INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '제 인생크레페 찾았어요. 일본 도쿄에서 먹은거 걍 저리가라입니다. 진짜 홍대 올일 있으면 와서 드셔보세요…..🥹 사장님 오래오래 해주세요🫶 인천에서 다시 찾아왔어요💦🐶🐶', 49, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '홍대 2번째 방문해 봤는데, 이런 맛나는 디저트집 찾기 힘든데 웨이팅 없어서 좋습니다 :) 날이 따듯할 때 테이크아웃 해가면 좋을거같아요!! 다음엔 녹차크림브륄레도 도전 해보고 싶습니다! 여자친구가 딸기 귀신인데 맛있다고 다음에 또 오자네용 ㅎㅎ', 43, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'TERRACE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '크림브뤌레 크레페가 진짜 맛도리🥰🥰🥰🥰🥰 딸기라테랑 커피는 생각하는 맛 그대로 맛있는데, 딸기라떼에 있는 딸기가 진짜 생딸기같아서 아주 맛있네요😊😊😊', 61, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '가게가 귀엽고 사장님이 정말 친절하세요 :) 크레페 먹고싶어서 방문했는데, 분위기가 좋아서 기절- 딸기는 11월 중순 이후에나 나온다고 하니깐 방문에 참고하세요 !! :)', 5, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '상당히 불친절했어요. 보통 리뷰이벤트 하면 리뷰 쓴거 확인만하시는데 제 폰으로 클릭도 하시고 불편했습니다.  서비스업을 하시기엔 너무 불쾨했습니다.', 391, 56, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '새로 나온 녹차브릴레를 먹었는데 안에 녹차 크림이 가득 들어가 맛있었으며, 위에 브릴레도 바삭하고 달콤하여 디저트로 즐기기 넘 좋았어요. 음료로는 담비라떼, 판단라떼를 주문하였는데 담비라떼는 우유의 담백한 맛을 즐기기 좋은 라떼여서 크레페와 함께 먹기 좋았어요. 판단라떼에 경우 동남아시아 열대식물인 판단잎을 활용하여 만든 라떼인데요. 라떼가 옥수수라떼처럼 고소하고 부드러워서 고소한 라떼를 좋아한다면 주문을 추천드린답니다. 저스트단비 크레페는 내부 분위기도 좋고, 달콤한 크레페를 다채롭게 먹을 수 있는 홍대 디저트 카페이오니 홍대 카페를 찾고 있다면 방문을 강추드려요.', 20, 1, 'GOOD', SYSTIMESTAMP);
