INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '크레페 먹고싶어서 찾아보다 발견한 저스트단비!! 종류도 많고 매장에서 먹을수 있어서 넘 좋았는데 바로 구워주시니깐 따뜻하고 크림도 부드럽고 색다른 샌드위치메뉴도 있어서 좋았어여 식사용으로 든든하더라구요 소스도 선택할수 있어서 다양하게 맛볼수 있어서 추천드려요 한끼 가볍게 먹을때 좋을것 같아요🤭🩷', 24, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '제 먹킷리스트에 있던 크레페집을 드디어 와봤네요!! 보통 테이크아웃만 있는 다른 크레페집과는 다르게 내부 홀도 있어서 크레페를 먹고 갈 수 있는게 너무 좋았어요 겨울시즌에 잘 맞춰서 와서 딸기 크레페 먹어봤는데 딸기가 완전 가득 들어있고 달콤상콤 최고라서 너무 맛있었어요ㅠㅠ 크림브륄레 크레페도 제가 기대했던 것 보다 더더더 맛있었고 진짜 인생맛집 등극🫶🏻 홍대 올 때마다 들릴 것 같아요ㅎㅎ 원소기호 같은 독특한 메뉴판도 귀엽고 내부도 아늑해서 너무 좋아요! 사장님도 짱 친절하십니다 홍대 오시는 분은 꼭 들러보세요🩷', 41, 10, 'GOOD', SYSTIMESTAMP);
