INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '고기먹은 뒤 가볍게 크레페 하나 나눠먹으며 전철역가려고 했는데... 한입 먹고 홀딱 반해 다시 가게로 들어왔어요.^^  더블 스트로베리가 시즌상품이라 없어서 살짝아쉬웠지만 다음을 기약해 볼게요^^ 크레페 빵?이 정말 예술인거 같아요.. 홍대 올때마다 그냥 지나가기 아쉽겠어요~', 20, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '크레페를 여자친구 때문에 처음 먹어봤습니다. 먹기 전까지 진짜 이게 맛있어?? 했는데 저스트단비 크레페 먹고 한개 더 시켰습니다.. 너무 맛있네요!! 추천합니다', 57, 16, 'GOOD', SYSTIMESTAMP);
