INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '홍대에서 크레페집 찾기가 힘든데 만나서 너무 반가웠어요 ㅎㅎ 크림브륄레 크레페는 누텔라 맛을 많이 사가시는 것 같아요 녹차 크레페도 매우 추천합니다!!', 4, 1, NULL, SYSTIMESTAMP);
