INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '에그샐러드 크레페 진짜 맛있어요..✨ 양도 푸짐하고 재료도 신선해서 식사 대용으로도 좋을 것 같아요!! 매장 분위기도 아늑하지만 힙하고 미국 감성이 느껴졌으며, 시그니처 단비라떼도 적당히 달달한 맛에 라떼의 깊은 풍미가 느껴져서 크레페랑 같이 먹으니 조합이 좋더라구요 !! 크레페 생각날 때마다 자주 올게용 !!', 72, 16, 'GOOD', SYSTIMESTAMP);
