INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '홍대에서 크레페 먹고싶어서 찾다가 알게된 곳이에요 크레페 먹기전 궁금해서 시켜본 단비라떼 달달하니 맛있어요! 요고요고 추천드립니다😊 요즘같이 더운날 크레페 들고다니면서 먹기 불편한데 크레페만 전문으로 하는 카페라니 너무 좋고요! 달달한 디저트 종류도 있지만 식사대용으로 할만한 크레페 종류도 있으니 홍대에서 크레페 생각나는 분들 요기로 오세요ㅋㅋㅋㅋㅋㅋ', 8, 10, NULL, SYSTIMESTAMP);
