INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '홍대디저트맛집 저스트단비 크레페 홍대점에서 존맛탱 크레페 뿌수고 왔어요. 시그니처인 단비라떼는 크림이 느끼하지않고 맛있어요. 크레페도 건강하고 맛있는 찐맛이에요. 크레페가 얇아서 더더더 좋았어요. 저스트단비 크레페 홍대점을 홍대디저트카페로 추천합니다. 또 올게요', 11, 7, 'GOOD', SYSTIMESTAMP);
