INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '홍대 분위기 좋은카페 ! 크레페 맛집을 찾는다면 무조건 추천하는 저스트단비 ! 저는 신메뉴인 녹차브륄레크레페를 주문해봤는데용 🍀 진짜 겉바속촉 그 자체 •• 👍👍빠작빠작 달콤한 표면에 부드러운 녹차커스타드 크림이 가득들어간 녹차크레페 ! 포천농장에서 키워진 신선한 계란을 사용하신다고 하셨는데 그래서 그런지 크림이 진짜 고소하고 부드러운 맛이었어요! 심지어 녹차크레페반죽에서도 녹차향이 나서 녹차 러버들 완전 취향저격 ~! 주문 즉시 바로바로 만들어주시는 크레페라 그런지 받자마자 따끈하니~ 넘 부드럽고 맛있었어요 !! 시그니처라떼인 단비라떼는 우유의 고소함과 달큰함이 잘느껴지는 라떼였어용..💛 크레페랑 같이 먹기 딱 좋으니 왕왕 추천 ! 홍대카페 찾는다면 저스트단비 추천드려용​', 23, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
