INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '생과일이 가득한 부드러운 수제 크레페와 음료가 맛있었어요!! 벽에 붙은 원소 주기율표를 자세히 보면 메뉴들의 약자로 구성되어 있어 구경하는 재미가 있었습니다😆 가게의 크기 자체는 아담하지만 내부가 잘 꾸며져 있어 머무르기 괜찮았습니다. 후르츠 크레페는 청포도, 바나나, 블루베리, 체리에 부드러운 크림과 누텔라, 고소한 크레페 시트가 어울린 맛있는 크레페였어요! 단비라떼의 경우 풍성한 우유크림과 섞어 마시는 라떼로 일반 카페라떼보다 더 고소하고 부드러웠습니다. 복숭아 젤리 블랙티는 적당한 당도의 블랙티에 밑에 깔린 쫄깃한 젤리가 매력적이었어요🍑 여러모로 만족 스러웠습니다!!', 129, 20, 'GOOD', SYSTIMESTAMP);
