INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '홍대 디저트 맛집 저스트 단비 이색적인 메뉴판이 눈에 띔 사장님 혼자 크레페 만드느라 바빠보이심 테이블은 만석 크레페아주맛잇음 커피랑 한잔하면 든든한 간식! 식사대용 으로 먹을수잇는 것도잇음~ 달달하고 바삭한 크레페 잘먹고 갑니닷', 19, 8, 'GOOD', SYSTIMESTAMP);
