INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '크레페가 오랜만에 너무 먹고 싶어서 방문했는데요! 크레페 찐 맛집 저스트단비 너무 맛있게 먹었어요 엄청 부드럽고 입에서 살살 녹아서 순삭했답니다 크레페 먹고 싶으면 또 방문할것 같아요~~👍🏻👍🏻 커피도 부드럽고 맛있었습니당 *제공받고 솔직하게 작성했습니다*', 9, 4, 'GOOD', SYSTIMESTAMP);
