INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '아이가 녹차 좋아해서 홍대 온 김에 들려봤어요 녹차크림 부드럽고 크래페도 바삭하고 넘나 맛있어요 단비라떼도 많이 달지 않고 딱 좋아요', 69, 11, 'GOOD', SYSTIMESTAMP);
