INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '홍대에서 데이트 시 방문하기 좋은곳!! 홍대이색카페 찾으시면 저스트단비 에요! 음료종류도 다양하고 무엇보다 크레페를 파는데, 주문시 바로 구워주시는 따듯한 크레페...너무 맛있어요!!! 달달이디저트 찾을때 먹기 딱 좋아요! 인테리어도 멋져서 사진찍기도 좋아요 *업체로부터 식사권 제공받아 작성한 후기입니다', 17, 9, 'GOOD', SYSTIMESTAMP);
