INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '우와!!!! 진짜진짜진짜 넘흐 완전!!! 맛있어요!! 오늘 비도 많이오는데 손님들도 많구 찐맛집입니다!!!!!!👍👍👍👍강력 추천쓰 ㅎㅎ', 25, 9, 'GOOD', SYSTIMESTAMP);
