INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '10년된 홍대 크레페 맛집이에요. 자주 생기고 없어지는 홍대에서 이렇게 오래 버텼다? 당연히 홍대 디저트 맛집이고요~~ 완전 아는 사람만 가는 곳이랍니다!! 홍대 제대로 된 카페 찾는다 하면 강추 드릴게요. 저스트 단비 크레페는 진짜 너무 달지도 않고, 적당한 단맛에 촉촉한 크림이 숙성된 반죽? 도우? 랑 잘 어울려요. 얇아서 거의 맛있는 크레이프케이크 먹는 느낌이랄까요? 다 먹어갈 때까지 밀가루 맛은 1도 안나고 끝까지 달달하니 맛있게 즐길 수 있는 카페!! 식사하시고 맛있는 디저트 땡긴다 하시면 저스트단비 가보세요!!', 35, 8, 'GOOD', SYSTIMESTAMP);
