INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '너무 맛있게 잘 먹었습니다! 당충전할 때 딱이에요. 다음에는 로투스 말고 누텔라 맛으로도 먹어보러 오겠습니다! 딸기랑 크림브륄레 다 완전 맛있었어요!!!', 11, 1, 'GOOD', SYSTIMESTAMP);
