INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '여기 완전 맛집이에오.. 처음 와봤는데 생각보다 너무 맛있어서 또 오고싶은 느낌 낭낭이였습니다..🥺💗 그리고 사장님이 친절하고 분위기도 완전 좋았어요..다들 한번씩 꼭 들러도 후회 안할것 같아요🫶🏻🫶🏻', 128, 26, 'GOOD', SYSTIMESTAMP);
