INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '예전 여행지에서 먹었던 기억이 있었는데, 오늘 검색을 해보니 홍대에 크림브륄레 크레이프가 있어서 찾아오게 되었습니다 직원분도 매우 친절하시고, 매장도 청결하고 맛있게 먹었습니다!!💕', 10, 0, 'GOOD', SYSTIMESTAMP);
