INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '아기가 카레펫 먹고 싶다고 해서 방문했어요. 소문대로 양도 많고 맛있어서 다음에 또 오고 싶다는 생각 들었습니다♡ 감사합니다!', 17, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '든든한 끼니로 먹을 수 있는 크레페 너무 좋네요 야채도 고기도 들어간 든든하고 다양한 크레페가 너무 매력적이예요 쫀득한 시트에 소스도 선택할 수 있고 토핑토 다양하다보니 만족스럽네요.', 24, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '너어어어무 맛있어요 ❤️ 크림브륄레 진짜 👍🏻👍🏻👍🏻☺️ 짱맛있어요!!!! 사장님두 너무 친절하시구 ㅎㅎㅎㅎ!! 다음에 또 올게요🥰', 35, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '분위기 좋고좋고~ 크레페 너무 좋아하는데 행복해요 ㅠㅠ 녹차브륄레는 녹차의 맛이 너무 잘 담겨있어요 저 수헬리베 붕탄질산에 크레페 대입한것도 웃기고 테이블도 크레페 모양같아서 재밌네욯ㅎ 추천해요', 33, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '아기자기 너무나 귀여운 크레페집..💛 다양하게 조합해서 먹을 수 있는 크레페 메뉴가 준비돼있어서 식사 대용으로도 충분히 가능해요!! 시그니처인 단비라떼도 부드럽고 달달한 우유거품이 잔뜩 올라가 있어서 남녀노소 좋아할 맛🥰 내부가 작지만 좌석이 네개나 있어서 달달한 크레페랑 커피 땡길때는 꼭 들려야하는 곳!', 103, 25, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '너무 맛있어요~! 홍대에 디저트 찾아보다가 분위기 있는 카페같아 들려봤는데 기대이상으로 맛있습니다❤️ 특히 크림 브뤨레 누텔라가 제 입맛이네요 😄😄사장님 번창하세요✌️😃 다음에 친구랑 방문 하겠습니다!', 123, 25, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '친구랑 홍대 나들이 하다 방문한 크레이프 맛집!!저는 바삭삭한 크림브뤼레를 주문했는데 진짜 바삭바삭하고 안운 촉촉하니 너무 맛있어요!! 같이 주문한 아메리카노는 고소하고 커피맛집입니다!!', 16, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '홍대에 오면 매번 들리는 매장. 여러분 여기서 크레페 주문하시면 치즈 크러스트를 꼭 추가하세요!! 오늘 처음으로 추가해서 먹었는데 2천원이 아깝지 않았습니다!!! 다이어트를 하기 위해 치킨가슴살 크레페 주문했는데 과일, 치즈, 견과류, 채소가 가득해서 이거 하나 먹어도 배가 부르네요!!! 다이어트 하시는 분들에게 추천추천!! 기분 좋게 잘 먹고 갑니다!!', 15, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '크림브륄레 크레페는 그저 사랑입니다💕💕 신선한 식재료와 사장님의 정성이 한가득 담겨 있는 크레페에요! 소스도 기호에 맞게 선택할 수 있는데 개인적으로 누텔라 소스가 찰떡콩떡 궁합이었어요🥰복숭아 젤리 블랙티도 달콤 쌉쌀한 맛이 일품! 여기 오면 꼭 크림브륄레 크레페 먹어보세요 매우 추천합니당👍🏻💯', 58, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '크레페 장난아니에요..! 크림브륄레가 메뉴 첫번째에 있는 이유가 있어요 소스는 누텔라로 선택했구요 안쪽에는 생크림과 커스터드 크림이 가득찬데 느끼하지 않고 진짜 맛있어요 배만 안불렀으면 하나 더 먹었을텐데ㅠㅠ 추천!!', 28, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '정말 맛있는 크레페집입니다. 매장이  협소해서 오래 있진 못했지만, 크림브륄레 크레페랑 오레오바나나? 시켜서 먹었는데 싹 당충전 되는 맛이었습니다. 달달한 크레페 좋아하시면 가서 먹어보시길 강추드립니다!', 29, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '홍대에 있는 저스트단비 다녀왔어요! 너무 더운날 커피도 먹고 싶고, 달달한 크레페도 먹고 싶어서🐽 다녀온 저스트단비! 👍🏻👍🏻 ⠀ ⭐️크림브륄레 크레페 ⭐️단비라떼 ice ⭐️아이스 아메리카노 ⠀ 크림브뤨레 크레페는 소스 선택 가눙! 누텔라랑 로투스 중 저는 로투스를 선택했어요😇 ⠀ 아이스크림 추가도 가능해서 잠시 고민했지만, 음료도 시켰기에 스킵! 단비라떼는 몽글몽글한 크림이 가득! 달달한 한 입 먹자마자 당 충전!! ⠀ 근데 크레페 진짜 대박이였어요.🫶🏼 보통 크레페는 도우가 말캉한거아시죠?? 근데 저스트단비 도우는 정말 바삭했어요♥️♥️ ⠀ 날씨가 이렇게 습한데두,,,, 넘나 바삭해서 진짜 놀랬어요. 게다가 크림이랑 로투스 소스 머선일 양 정말 낭낭해서 달달함 진짜 1000% 충전 완료!🔋🔋', 12, 0, 'GOOD', SYSTIMESTAMP);
