INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '홍대에 들렀다가 크레페가 먹고싶어 가본 곳이에요! 주문하자마자 구워주시는데 도우가 따뜻하니 맛있었고 안에 든 생크림과 과일토핑이랄 잘 어우러져서 너무 맛났어오! 단비라떼를 먹었는데 이게 또 진짜 맛도리더라구욤🫶담에가도 다시 먹을거 같애요', 16, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '아이스크림 추가하니까 엄청 쫀득한 아이스크림이었음!! 아메리카노는 약간 씁쓸한 맛이라 크레페랑 어울려요~ 바나나도 신선하고 크림브륄레도 빠삭함!! 근처 오시면 꼭 드셔보세요, 짱 맛있다...', 8, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '크레페가 엄청 많이 단게 아니라 먹기 딱 좋았어요♥️ 바삭쫀득한 식감의 크레페에 상콤달달한 과일까지 올라가니 조합 최고! 시그니처 단비라떼도 존맛이지만 복숭아 젤리가 가득 들어있는 복숭아젤리블랙티도 추천👍🏻', 15, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '맛있습니다! 크레페 전문점답게 얇게 잘 펴진 크레페에 속 꽉찬 토핑이 올라가져있어 맛있게 먹었어요! 단비라떼도 카페라떼보다 훨 부드러웠고, 복숭아젤리블랙티도 입가심으로 더운 여름 시원하게 마실 수 있었어요~', 45, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '홍대 유명한 크레페 맛집 진짜 맛있어요 중독되는이맛 특히 다른곳에서 맛볼수없는 퀄리티가 남달라요 달달하고  부드럽고 촉촉함 그자체 꼭꼭 주문하세요', 84, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '엄마랑 식사 후 커피와 맛있는 파르페를 먹으려고 왔어요. 파르페가 바삭바삭 얇고 정말 맛있어요. 누텔라 소스로 계절과일이 들어간 프루츠 파르페를 주문했는데 생각보다 달지않고 맛있었어요. 단비라떼, 딸기라떼도 시원하게 맛있었어요. 단비라떼 부드럽네요~^^', 17, 1, 'GOOD', SYSTIMESTAMP);
