INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '크레페너무 이쁜거같지않나요  와우 이쁜디저트카페 사장님께서직접 구워주시는데  와  향미쳤고  음료도 평타치고 굿이였어요 단비라떼라고 여기시그니저음료 드셔보세요💕🧡💕🧡💕💜💕💚💚❤️💚❤️💚💕💚💕💚💕💚💕💚💕💚💕💚💕💜💜💕💚❤️💚💕💚홍대가면꼭갈곳♡', 89, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '크레페 달고 맛있어요! 단비라떼, 아이스아메리카노랑 같이 먹었는데 잘 어울리고 너무 맛있네요!! 디저트 먹고 싶을 때 자주 올 것 같아요', 50, 5, 'GOOD', SYSTIMESTAMP);
