INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '너무 자극적이지 않으면서 맛있는 디저트를 찾고싶어서 방문한 곳!! 크레페 종류가 엄청나게 많았는데 치킨가슴살크레페가 눈에 띄어서 주문😋 가슴살인데도 엄청 촉촉하고 야채과일도 잔뜩 들어있어서 한끼로도 든든할 것 같은 메뉴임!!! 집 근처였으면 자주 먹었을텐데ㅠㅠㅠ아아도 깔끔하고 단비라떼도 엄청 달지않아서 너뮤 좋움! 크림이 부드러워서 맛났댱💗💗👍', 89, 14, 'GOOD', SYSTIMESTAMP);
