INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '홍대입구 상상마당 근처에 있는 저스트단비 카페에 방문하였는데요~ 아담한 카페이지만 분위기가 좋더라구요! 맛난 음료를 마시니 힐링되었답니다ㅎㅎ', 19, 4, 'GOOD', SYSTIMESTAMP);
