INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '크레페는 항상 달디단 맛만 먹어봤었는데 이번에 후르츠가 있길래 !! 도전해봤어용 계절 과일 넣어주샤서 왕 마싯구 누텔라랑도 잘 어울리더라구옹 반죽도 빠삭빠삭하니 맛잇엇움 .. 🍒🍌🍇 자몽젤리블랙티두 상큼하니 맛나용 저는 오늘 상큼함 충전하고 갑니댜 총총', 6, 9, 'GOOD', SYSTIMESTAMP);
