INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '딸기 크레페에 추천해주신 누텔라로 주문했는데, 먹기도 편하게 귀여운 컵에 나와서 좋았고, 넘 맛있고 느끼하지 않은 맛이라 좋았어요! 이렇게 알찬 구성으로 주셔서 든든했어요! 딸기 크레페에 딸기라떼 넘 잘어울려서 추천합니당 내부 컬러가 레드 색상이 예뻐서 더 잘어울리고 좋았던 것 같아요:)', 34, 6, 'GOOD', SYSTIMESTAMP);
