INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '홍대에서 크레페를 파는 곳이 생겼다니 ,, 가게는 아담하지만 손님들이 자꾸 들어오시더라구요 크레페 누텔라 적당히 넣어주셔서 많이 달지 않고 미숫가루 맛있어요 ! 잘 먹었습니다', 8, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '오랜만에 방문한 홍대 크레페 카페 저스트단비! 전보다 플레이팅도 메뉴도 너무 예쁘고 풍부해졌네요! 그때도 맛있었는데 오늘 특히 분위기 장난없고 너무 맛있어서 앉아서 메뉴 나오자마자 폭풍흡입...ㅋㅋㅋ 진짜 맛있게 잘 먹었습니다!', 42, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '저스트단비에서 단비라떼(5,000원),  딸기라떼(6,500원), 치킨가슴살크레페(8,500원)를 맛보고 왔어요. 일반라떼보다 더 고소하고 진한 단비라떼가 찐이에요. 특히 반죽이 얇고 달지 않으며 고소한 치킨가슴살크레페가 인상적이네요. 크레페의 모양도 일반 크레페와 달리 마블링처럼 모양이 나와서 특이했어요. 홍대입구거리에서 활기차게 북적이는 사람들을 보면서  크레페를 먹으며 거리를 다니니 왠지 힐링되네요. 에너지가 필요할땐 가셔서 크레페 들고 거리를 활보하며 충전하세요.', 125, 24, 'GOOD', SYSTIMESTAMP);
