INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '홍대 디저트 맛집 크레페 ㅋ 혼자 방문했습니다 ㅋㅋ 크레페 종류도 다양하고,, 주문 즉시 바로 조리를 시작해서 신선하고 더 맛있었어용ㅎㅎ 참고로 네이버 영수증 리뷰를 남기면 켄지고프레 2종을 증정함니다 ㅋㅋ 깔끔하고 적당히 고소한 맛의 단비라떼와 달달한 크레페를 함께 먹으니 꿀조합이네용 신선한 과일이 듬뿍 들어간 후르츠 크레페!  부드러운 크레페 반죽과 달콤한 과일, 누텔라, 생크림의 조합은 맛없없! 다음에 또 방문해서 다른 종류도 먹어보고 싶네용 ㅎㅎㅎ 본 업체로부터 서비스를 제공받았으나 솔직한 후기를 남깁니당!', 0, 0, 'GOOD', SYSTIMESTAMP);
