INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '크레페가 먹고 싶어 찾은 가게였어요!̆̈ 길거리에서 먹기보단 자리에 앉아 먹고 싶은 마음에 찾은 가게인데 반죽을 바삭하고 얇게 만들어주시구 그게 과일, 누텔라랑 잘 어울렸어요 사장님도 친절하십니다 재방문할게요🩷🩷', 36, 9, 'GOOD', SYSTIMESTAMP);
