INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '크림브륄레 크레페에 단비라떼, 복숭아젤리블랙티를 마셨어요 단비라떼는 일반 카페라떼보다 더 고소하고 진한 맛이 나더라구요 복숭아젤리블랙티는 블랙티에 복숭아 젤리가 들어있어서 버블티 먹듯이 씹는 맛이 있어서 좋았어요 너무 달거나 쓰지 않아서 더 좋았어용! 크레페는 사장님이 직접 만드시는데, 미국산 100% 밀가루, 본연의 맛을 잘 살린 우유, 포천농장에서 키워진 계란을 사용해서 만든 바삭하면서 부드러운 맛있는 크레페에요 저는 크림브륄레에 누텔라소스를 선택해서 먹었는데, 로투스소스로 먹거나 다른 메뉴들도 맛있을것 같아요 디저트 느낌말고 샌드위치처럼 먹을 수 있는 메뉴들도 있더라구요 음료도 종류가 다양해서 자주 와서 다 먹어보고 싶어요ㅎㅎ', 10, 1, 'GOOD', SYSTIMESTAMP);
