INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '크레페 먹고 싶어서 비오는 날 찾아갔는데.. 넘나 맛있어요! 주기율표를 활용한 재료설명까지 신박하네용ㅎ 바삭촉촉달달상큼꾸덕+비주얼까지 전부 다 느끼고 왔습니다! 또 방문할게용◡̈', 2, 0, 'GOOD', SYSTIMESTAMP);
