INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '크레페 너무 먹고 싶어서 왔습니다! 사장님이 너무 착하셔서 행복했어요🥰 겉은 바삭하고 속은 과일로 꽉 찬 게 맛집 진심 탐방러로써 강력 추천드립니다!!!💗😋😋', 118, 24, 'GOOD', SYSTIMESTAMP);
