INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '라떼의 부드러운 그림과 라떼의 고소함이 상당히 고급스럽게 느껴졌고. 아이스티는 일반 카페 가서 아이스티 시키면 엄청 탄 맛만 나는데 저스트 단비에서 주문한 아이스티는 많이 달지 않으며, 고급스러운 아이스티를 먹는 느낌이라 좋았고 저처럼 단 걸 별로 안 좋아하는 분들에게 추천하고 싶어요~ 더블 딸기 크레페는 신선한 딸기와 달콤한 생크림과 조화가 한입 먹으면 오늘 하루의 피로가 녹아내리는 맛을 느끼다가 중간쯤 먹었을 때 악마의 크림이라는 명성에 걸맞게 딸기와 함께 먹는 사람을 유혹하는 행복한 맛이네요~~🥰 그리고 딸기가 마지막 심지 부분까지 가득가득들어있었어요~ 마지막 한입까지 신경써주신 사장님의 배려가 느껴지네요~~ 오늘 하루 너무나도 피곤했지만 행복한 음식으로 모든 게 보상되는 하루였습니다~❤', 73, 16, 'GOOD', SYSTIMESTAMP);
