INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '홍대입구역에서 가까운위치에 있어서 찾기도 쉽고 또 주변에 많은 맛집이 있어서 밥먹고 가기 딱좋은 코스에요. 저스트 단비 크레페의 밀가루는  이것저것 섞지않고 미국산 100%, 본연의 맛을 잘 살린 우유와 포천농장에서 키워진 계란을 사용한다고 하셨는데 갓 구워 나와 따끈따끈한 크레페가 바삭하면서도 매우 부드러워요~ 단비라떼 부드러운 크림이 달지않은 커피조합이 너무 잘어울리는 크림라떼였어요. 간단한 식사대용뿐만 아니라 디저트가 생각날때 간단하게 즐길수 있는 크레페메뉴! 홍대디저트카페로 부드러운 크레페가 생각날때 추천해요^^', 0, 5, NULL, SYSTIMESTAMP);
