INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '친구 추천으로 같이 왔는데 생각보다 분위기도 있고 직원분이 친절하셨어요!! 먹으니까 징짜 이 세상에 존재하지 않는것처럼 맛이 장난아니게 달고 맛잇어요ㅠㅠㅠ 비주얼도 장난 아니넹요 잘먹겠습니다!!', 67, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '음 나오는 시간이 좀 오래걸려요 ㅎ 크레페는 저 퀄리티에 비해 가격이 비싼 편이에요 그래도 과일이 신선해요 저 가격에 먹을 건 아닌 것 같아요 홍대라 이해할 뿐 아니 그리고 음식 나오지도 않았는데 사진 리뷰 쓰라는건 뭐 옆테이블 음식 찍으라는 건가요? 진짜 궁금해서.. 본 리뷰는 공익 목적으로 소비자의 선택을 돕고자 작성했습니다.', 38, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '크레페 먹고 싶어서 검색해서 왔는데 너무 맛있어요! 크림브륄레 설탕이 딱 깨지면서 커스터드 크림이랑 같이 먹으니 진짜 극락입니다ㅜㅜ 크림이 진짜 찐하고 마싯어요! 더블딸기도 딸기 듬뿍 들어가서 상큼하니 넘 맛있슴다 크레페 빵이 끝까지 바삭해서 다 먹을때까지 넘넘 맛있게 먹었어요ㅎㅎ 오랜만에 넘 맛있는 집 발견했어요 앞으로 자주 방문하겠습니다!!!', 7, 5, 'GOOD', SYSTIMESTAMP);
