INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '너무 예쁘고 맛있어요 기분전환 제대로 하고 온 데이트 카페였어요🥰🫶 일본에서 크레페 먹고 온 후로 앓이앓이 하고 있었는데 다른 매력으로 겉바속촉 달콤해서 너무 맛있어요 단비라떼가 너무 달지 않아서 크레페랑 너무 잘 어울리고 딸기라떼도 상큼하고 적당히 달콤해서 너무 맛있게 먹었어요', 17, 5, 'GOOD', SYSTIMESTAMP);
