INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '사장님이 너무 친절하시고 직접 만드신다고 하니 더 맛있었어요 !! 크레페 진짜 바삭하고 단비라떼 부드럽고 달달한게 최고입니다!', 90, 11, 'GOOD', SYSTIMESTAMP);
