INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '*저스트단비 단비라떼(₩5,000) 딸기라떼(₩6,500) 쿠앤크바나나(₩7,500) 단비라떼  달달구리 라떼~ 깊은 커피의 풍미가 은은하게 느껴지는 단비라떼~ 딸기라떼 달콤새콤 + 조각 딸기 가득가득~ 시원한 라떼 , 입안 가득 상쾌함!! 쿠앤크바나나 크레페 바삭한 쿠앤크 초코과자와 부드러운 바나나 ~ 그위를 덮은 누텔라 소스!!! 달달함의 끝판왕 스트레스가 휙휙 날라가여~~ 크레페와 라떼의 조합!!  나쁘지않은것 같아여 !!! 저스트 단비로 놀러오세요~', 43, 1, NULL, SYSTIMESTAMP);
