INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '더블 딸기 크레페는 안에 누텔라,블루베리,생크림,딸기가 듬뿍 들어 있어 단거 좋아하시는 분들에게 완전 추천 !! 단비라떼는 위에 부드러운 크림과 커피가 잘어우러져 달콤쌉싸름 한맛이다 딸기라떼는 우유의 고소한 맛과 딸기의 자연스런 단맛이 잘어우러져 딸기쳐돌이들에게 추천 !', 55, 17, NULL, SYSTIMESTAMP);
