INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '크림브릴레가 너무너무 맛있어요!!!!! 허니 치즈는 꾸덕 고소해요! 즉석에서 바로 만들어쥬셔서 크레페 반죽이 눅눅하지 않고 바삭하고 쫀득해요!!', 7, 4, 'GOOD', SYSTIMESTAMP);
