INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '✔️더블딸기 누텔라 8,000 ✔️단비라떼 5,000 아늑하고 사장님이 혼자 운영하시는 것 같았어요. 직접 만들어주시는 크레페! 엄청 바삭하고 담백해요!! 과일도 달고 양이 많아요🍓 단비라떼는 약간 믹스커피 같이 달달구리한 커피였어요ㅠㅠ 위에 거품도 부드러워용☕️', 6, 4, NULL, SYSTIMESTAMP);
