INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '오랜만에 크레페가 먹고싶어서 방문했어요! 종류도 다양하고 식사대용으로 할만한 크레페들도 많더라구요. 저는 그중에 더블딸기 크레페 시켜봤는데 메뉴이름대로 딸기가 정말 가득 담겨있어서 좋더라구요! 단비라떼는 카페 특색메뉴인거 같았는데 크림도 달달하니 맛있고, 복숭아젤리블랙티는 밑에 젤리 씹히는것도 넘 맛있고 크레페랑 조합이 좋더라구요~! 가격도 합리적이고 위치접근성도 홍대길거리에 있어서 찾아가기 좋을거 같아요 :)', 77, 18, 'GOOD', SYSTIMESTAMP);
