INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '빵이 부드럽고 크림이나 속 재료들이 좋은 거 같아요:) 너무 달아서 부담스러울 수 있는데 그러지 않아서 좋은 거 같아요 이런 종류의 간식은 먹기 불편한데 이건 손으로 먹기 편하고 안에 있는 과일들이 빠져 나오지 않아서 좋았어요:) 담에 또 먹으러 올게요🍀', 6, 9, 'GOOD', SYSTIMESTAMP);
