INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '📌크레페 자체가 굉장히 좋은 재료를 쓰는 곳이란 게 느껴집니다! 고소하고 겉면은 바삭하면서 안쪽은 완전 촉촉~하거든용 😋 밀가루도 다른 거 안 섞고 100% 순밀가루로 쓰신다고 하더라구용 📌토핑을 진짜 낭낭하게 넣어주세요 ㅠ 쿠앤크바나나인데 어디를 씹든지 무조건! 토핑이 같이 씹혀요 ㅎㅎ 비주얼도 예뻐서 일본 크레페 감성 저리가라예요 💖 📌같이 마신 단비라떼도 추천합니다,,, 이거 완전 대박이에요 크림폼 자체가 두껍게 올려지고, 부담스러운 단 맛이 아니에요! 하지만 커피와 같이 마실 때 부드러운 목넘김이 정말 좋았어요 :) 크림커피 좋아하시는 분들 맘에 들어하실 거 같아융 👍 +) 마지막엔 저번에 사먹을 때 찍은 더블딸기도 첨부합니당 이것도 진짜 존맛탱 🍓', 38, 9, 'GOOD', SYSTIMESTAMP);
