INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '제가 크레페 좋아해서 여러군데 다녀봤는데요 이집이 단연 최고의 맛집입니다. 토핑부터 신선하고 생과일에 빵의 굽기까지 모하나 디테일 빠지는게 없어요! 재료가 다른거 같아요 고퀄리티에요. 단비라떼는 필수로 드셔보시길요 맛있어요 . 주차는 근처에 가능하고 맛은 보장이니 강추에요', 22, 5, 'GOOD', SYSTIMESTAMP);
