INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '크레페 크레페❤️.❤️ 넘넘 맛있어요!!! 와 진짜 인생크레페에요 ㅎㅎㅎ 역시.크레페는 딸기와 누텔라가 만나야죠! 커피도 산미없이 고소하니 넘 맛있어요! 홍대오면 무조건 크레페먹으러올것같아요!!', 88, 16, 'GOOD', SYSTIMESTAMP);
