INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '홍대에서 10년째 자리잡고 있는 홍대디저트카페 저스트단비에 다며왔어요! 딸기 시즌철에 맞춰 더블딸기 크레페 먹었는데 너무 맛있어요~ 와플과 다르게 얇은 빵에 사이사이에 상큼한 딸기와 달달한 크림이 함께 조화로운데 진짜 최고💕 음료는 복숭아젤리블랙티와 단비라떼 먹었는데 둘 다 맛있음 ㅎㅎ 퐁신퐁신한 크림이 올려진 단비라떼도 맛있지만 특히 젤리가 씹히는 식감이 너무 재밌는 복숭아젤리블랙티 완전 제 스타일😍😍', 19, 0, 'GOOD', SYSTIMESTAMP);
