INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '인스타에서 처음 보고 어머! 여기 꼭 가봐야지 하고 찜콩해뒀던곳인데 좋은 기회로  인근에 점심먹으러 들렀다가 아이랑 같이 후식으로 크레페 먹자고 방문했어요~^^* 봄엔 역시 딸기 들어간 디저트 먹어줘야죠! 크레페와 음료들 비쥬얼이 진짜 예술! 사장님도 넘 친절하시고 정성가득하게 만들어주셔서 좋더라구요~^^* 맛도 있어서 아이랑 즐건 디저트 타임 가졌어요! 주차는 따로 자리가 없어서 근처 주차장을 이용했는데 되도록 도보이용하면 좋을듯요!', 2, 9, NULL, SYSTIMESTAMP);
