INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '크레페 가게 요즘 보기 힘든데 우연히 찾아서 냉큼 달려왔습니다!!! 쿠앤크 바나나랑 후르츠 크레페 메뉴 제일 많이 주문하시길래 저희도 똑같이 했는데 맛없없!! 너무 맛있게 먹고 갑니다🥹💛', 78, 14, 'GOOD', SYSTIMESTAMP);
