INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '오랜만에 크레페가 먹고 싶었어요, 홍대에 크레페맛집이 있다고해서 찾아온 ⭐️저스트단비⭐️ 매장 분위기 너무 좋아요😀 노래도 잔잔하게 나오고 인테리어도 뉴욕의 크레페집처럼 발랄하고 인테리어 소품들도 아기자기 분위기있고 좋아요👍 저는 후르츠크레페와 크림브륄레크레페, 단비라떼, 아메리카노를 시켰어용~ 시키자마자 고소하고 달달하고 맛있는 냄새가 나요😆 크레페주문하면 안에 시럽이 누텔라와 로투스 중에 하나 선택할 수 있어요~ ⭐️크림브륄레크레페 - 크림이 부드럽고 막 달지도 않고 적당히 달면서 너무 맛있었어요🫶 ⭐️후르츠크레페 - 제철과일도 들어가고 상큼달콤 너무 맛있었어요🫶 ⭐️단비라떼 - 여기 시그니처 메뉴라는데 이해가요!! 라떼 맛집이네요!!! ⭐️아메리카노 - 산미없고 고소하고 맛있네요ㅎㅎㅎ', 25, 2, 'GOOD', SYSTIMESTAMP);
