INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '크레페 파는 곳이라서 방문했어요! 무려!! 크림브륄레 크레페를 취급합니다 쓴맛 나지 않고 파삭파삭한 설탕막이었고 커스터드도 정말 맛있었습니다🥰🥰 더블딸기는 딸기가 상큼하고 과일 비중이 컸어요! 오히려 크림이 좀 적었음🫢 복숭아젤리블랙티는 너무 달지도 너무 싱겁지도 않고 딱 좋았어요!! 덕분에 만족스러운 디저트타임이었습니다🫶', 34, 10, 'GOOD', SYSTIMESTAMP);
