INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '아이와 홍대 데이트 갔다가 들러서 커피 수혈하고 크림브륄레 크레페 먹었는데 너무 맛있게 먹었어요 ! 크레페도 바삭하고 누텔라 소스로 했는데 많이 달지 않고 맛있었어요 ! 다음에 홍대가면 또 먹으러 오자고 하네요 :)', 117, 21, 'GOOD', SYSTIMESTAMP);
