INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '홍대입구랑 가까운 디저트 맛집! 크레페 먹고 싶을때 방문하기 좋을것 같아요 소스도 고를수 있고 종류도 다양한데 일단 신선한 재료라서 좋은것 같아요 10분 내외로 제작되서 갓만든 따끈한 크레페를 먹을 수 있다는게 가장 좋아요! 매장 내부는 넓지 않아서 테이크아웃 하시는 분들이 많더라구요 회전율이 좋은 편이라 오랜 웨이팅 걱정은 하지 않으셔도 됩니다! 다이어트 하시는 분들을 위한 샐러리 메뉴도 있어서 굿굿 제품을 협찬받아 솔찍하게 작성된 리뷰입니다', 20, 2, 'GOOD', SYSTIMESTAMP);
