INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '저스트단비 크레페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '한국에 크레페 파는곳 마니없는데 크레페라닛..🩷 다른곳이랑 다르게 로투스잼이 있어서 요게 은근 맛도리도라구요..!! 그리구 크레페 겉에가 밀가루맛만 나는게 아니라 약간 바삭한 와플같아요ㅠㅠ! 맛도리..🫢😍', 28, 5, 'GOOD', SYSTIMESTAMP);
