INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '줄이 길어 언제나 망설여졌던 경의선 숲길 연남 자연도소금빵에 다녀왔습니다. 메뉴는 4개 1팩의 소금빵 set가 유일합니다. 팩 구성이 간소하지만 예뻐 선물용으로도 좋을 것 같았습니다. 뿌려진 소금은 굵지 않고, 버터는 적당한 풍미가 났습니다. 다소 기름질 수는 있지만 커피가 있다면 일행과 나눠 먹기 딱 좋겠습니다.', 22, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '홍대입구역에서 연남동쪽으로 걷다보니 어디선가 솔솔나는 구수한 버터향에 이끌려 주문하게된 자연도 소금빵~ 줄서서 기다리는 사람이 많아서 한번에 맛집임을 알아 볼 수 있지요. 4개 한세트로 판매하니 감질맛 나는 갯수이긴 하지만 하나만 먹어도 큼직하니 배불배불! 풍부한 버터향과 간이 정말 잘된 소금빵은 지금까지 먹었던 소금빵과는 차원이 다른 맛에 깜짝 놀라게 되는데요 옆에 있던 참새도 자연도소금빵 한조각을 순식간에 채가더라고요.', 45, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '와 이거 진짜 지나가다가 냄새가 안 살 수가 없는 냄새였어용 줄은 금방 빠져서 기다리는 건 어렵지 않았구용 사실 너무너무 기대했나? 처음에 한 입 먹었을때 좀 응..? 했는데 한입 두입 점점 먹다보니까 너무 맛있어서 ㅋㅋㅋㅋㅋㅋ 계속 생각나는 맛이에용 ㅠㅠㅠ 다음에 또 재구매 각..🥖💛', 67, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '빵 나오는 시간에 딱 지나가다가 샀어요. 외국인도 줄 서 있고 해서 뭐지? 했는데 이정도 퀄리티에 이 가격이면 괜찮네요. 포장도 예뻐서 어디 선물 하기도 좋겠어요. 빵은 전에 먹던 소금빵 보다 조금 더 짭쪼름한 느낌.', 16, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '웨이팅이 길었던 걸 봐서 두려웠는데 평일 오전 일찍 가니 웨이팅이 없어서 너무 좋았어요 빵좋아하는사람은 4개 한세트 부족할듯하니 잘 계산해서 주문해셔야할듯 혼자 앉은자리에서 3개 꿀꺽했어요', 31, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '지나가다 냄새에 반하고 사먹으면 바삭한 겉과 촉촉하고 부드러운 속살의 식감에 반하고 고급스러운 버터 풍미에 녹아내리다 소금 짠맛에 느끼함 싹 날아가 순식간에 먹어버리는 소금빵...', 46, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '연남동 연트럴파크에 가면 온 거리에서 여기 빵봉지를 들고 있는 사람들을 볼수 있어요. 그만큼 많은 분들이 찾고 유명하다는거죠. 근데 한번 맛보면 그냥 올때마다 먹게됩니다. 이래서 점점 거리에 소금빵 봉투를 든 사람들이 늘어나는거겠죠. 결제도 웨이팅을 해야하고, 몰리는 시간에는 픽업도 웨이팅을 해야하지만 막상 빵을 입에 넣으면 줄섰던 기억은 잊고 맛있는 웃음만 나오네요. 재료들도 좋고, 특히 버터가 어마어마하게 들어가서 그런지 맛이 없을 수가 없죠. 손에도 기름기가 반들반들하게 묻으니 물티슈 꼭 준비하세요~', 44, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '여기 소금빵 버터에 절여져서 정말 맛있어요 ㅋㅋㅋㅋ절여졌다는 맛이 딱임… 남편이랑 여기까지 한참 걸어서 산책하러왔다가 소금빵 사서 돌아가는데 살이 빠지진 않을거같아요 ㅋㅋㅋㅋ 4개는 아쉬워서 8개 사갑니다 4개이후로는 2개단위로 구매 가능하면 좋을 것 같아요', 47, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '연남동 초입 도로변에 있어서 늘 줄 길게 서 있는 것만 봤는데 운좋게 바로 구닙해서 도전 성공했어요! 소금빵 맛집 답게 맛있어요🤍', 119, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '매번 지날 때마다 사람이 많아 궁금했던차 드뎌 방문. 무난한 맛에 겉바속촉이라 맛있게 먹을 수 있다. 간혹 소금이 뭉쳐있어 살짝 짠데 이게 컨셉(?)일 수도 있겠다 싶다~ 참고로 댕댕이도 소금빵은 못참는다♡', 1, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '성수랑 압구정만 가봤는데 연남도 오늘 가봤어요. 줄 별로 안길어서 운 좋게 금방 포장했고 믿고 먹는 자연도소금빵입니다. 개인적으로 굉장히 좋아하는 소금빵집!!🥰 안드셔보셨다면 무조건 드셔보시길! 추천합니다🤎', 35, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '성수점 앞에 지날 때마다 항상 줄을 서있어서 궁금했던 곳인데 연남점은 한산하길래 구매해 봤습니다. 4개 1세트씩 판매하네요. 빵은 모닝빵처럼 부드러운 스타일이고 버터가 꽤 많이 들어갔는지 안쪽은 푹 절여져 있어서 버터 풍미가 진합니다. 빵 아래쪽은 흘러나온 버터에 파삭하게 구워져서 식감이 좋네요. 개인적으로는 좀 더 담백한걸 선호해서 약간 느끼하긴 했으나 경험해 봐서 좋았습니다.', 26, 9, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '핫플이라고해서 연남동 지나다닐때마다 궁금했는데 홍대에서 일정 마치고 잠시 들렀더니 친절하시고 바로 빵 받아서 집에와가지고 에어프라이어에 다시 구웠더니 따뜻하고 겉바속촉...! 제 인생 소금빵으로 등극했어요♡', 26, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '소금빵 4개 12,000원 단일 메뉴만 팔고 포장만 가능한 곳입니다. 오픈 주방이 깨끗하고 직원분들도 친절하십니다. 소금빵은 따뜻할 때 먹으면 버터 풍미랑 소금의 은은한 짠맛이 잘 어울립니다.', 40, 2, NULL, SYSTIMESTAMP);
