INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '평상시 줄이 엄청길어서 못샀는데 줄없을때 한번 사봤어요 생각보다 엄청 기름짐,, 집으면 손에 기름범벅일정도로,,근데 소금은 많고 푹신해서 맛있어요', 46, 7, NULL, SYSTIMESTAMP);
