INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '숭실대 입구 오이도에 들어 있는 자연도 소금빵 볼때마다 구입하는 것 같습니다 부드럽고 버터향이 가득한 소금빵이에요. 소금이 잔뜩 묻어있는게 좋습니다 단짠 자연도소금빵 포장도 귀여워서 선물로도 좋아요', 122, 22, 'GOOD', SYSTIMESTAMP);
