INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '키오스크로 주문하고 바로 줘서 좋아요 기대보다 더 맛있네요🥐🥖 소금양은 줄여도 좋을 것 같아요🧂 따듯하게 먹을 수 있어 좋아요~', 9, 8, NULL, SYSTIMESTAMP);
