INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '잉?❔❓😦 언제 생겻ㅈ ㅣ여?🤷🏻‍♀️ 연남동에도#자연도소금빵🥐 체인이 되벌렷어⚠️ 그치만 같은재료 쓱 지나가니 냄ㅅ ㅐ끝장난다*^^**^^^ 안사갈수없엇다😆', 119, 22, NULL, SYSTIMESTAMP);
