INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '진짜 바삭하고 안에 버터맛의 기름이랑 짭짤한 소금이랑 너무너무 잘 어울려요! 앉은 자리에서 바로 다 먹었어요ㅎㅎ방금 나온거 먹으면 엄청 맛있을거같은데 조금 식었는데도 맛있어요 바삭함이 정말 짱 !!', 67, 16, 'GOOD', SYSTIMESTAMP);
