INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '얼떨결에 지나가다 줄서서 사먹었어요 ㅎㅎ 소금빵이 엄청 크고 부드러워요 끊어짐없이 이어져서 놀랬어요 4개 세트 ₩12,000원 혼자 4개 다 먹으면 살쪄요~ 친구랑 1개씩...2개씩 나눠드세요 커피랑도 맛있겠지만, 우유랑 먹음 더 꿀맛일듯', 13, 5, NULL, SYSTIMESTAMP);
