INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '이건 받자마자 그자리에서 한개는 꼭 먹어봐야함 버터 듬뿍 겉바속촉 최고임 식어도 맛있음 말모해 내가 젤 좋아하는 소금빵이지 영종도 점만 몇번 가봤는데 여기 홍대 온김에 구매함', 17, 3, 'GOOD', SYSTIMESTAMP);
