INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '매번 성수 자연도 앞을 지날 때 줄이 너무 길어서 못 샀는데 일요일 오전 10시30분쯤에 연남 지점 방문하니 줄이 그리 길지 않아 구매해서 먹어봤습니다 🥐 소금빵 4개 1세트에 12000원으로 나쁘지않다는 생각 들었고, 당일 바로 먹었는데 버터 잘 녹아있는 딱 맛있는 소금빵 .. ♥ 좋은 소비였다…', 39, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '친구 추천 받아서 다녀온 소금빵집! 메뉴는 소금빵4개 12,000원 하나뿐. 평일 12시45분쯤에 갔는데 줄 하나 없이 바로 받을 수 있었습니다. 부드러운 크로와상을 먹는 것 같았네요', 60, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '기대했어요 줄그렇게 길지않았고 맛있긴해요 소금짭짤 버터리하고 모닝빵이랑 크로와상 안쪽먹는듯한부드러움 .그리고바닥은 바삭했어요 요즘은 소금빵하는집이 워낙많아서 그렇게 특별하진않았어요 한번쯤 먹을만하지만 두번은. 그닥?ㅎ', 4, 9, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '옆 술집에 있는데 계속 빵냄새가 와서 어디지?찾다가 근원지인 이곳을 발견했어요! 소금빵을 많이 먹어보진 못해서 특별히 더 맛있다고 말씀드리긴 어렵지만..! 그래도 맛있게 잘 먹었습니다. 4개입 1세트 12000원으로만 구매 가능한 점은 아쉬워서 4인 이상일 때 방문할 것 같아요ㅎㅎ', 25, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '지나갈 때 마다 웨이팅 줄이 상당해 냄새만 맡아보던 자연도소금빵 근방에 라멘먹으러 왔다가 냄새가 너무 좋아서 홀린듯 웨이팅했어요. 줄이 꽤 길었는데 매장 안에 소금빵 공장이 있는가.. 기다린지 10분도 안지나 따뜻한 소금빵을 받을 수 있었어요. 12000원에 4개 구성인 단일메뉴 확실히 따뜻할 때 먹는게 맛있네요. 기대를 너무 많이한 탓인지 꽤 맛있는 편이긴 한데, 먹어본 소금빵 중에 최고로 맛있다는 아녔어요 ㅎㅎ 3.5/5.0', 24, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '자연도 소금빵 기대하고 사먹었는데 ㅠㅠㅠ진짜 이렇게 맛없는 소금빵은 처음 먹어봄 짜고 느끼하고 ㅜㅜㅜ 최악의 소금빵!!!줄서있는 외국인들 불쌍ㅠㅠ 한국에 진짜 맛있는 소금빵 많은데 하필 ㅜㅜㅜ', 81, 14, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '줄서서 먹길래 궁금해서 줄서봄 4개에 12,000원이고 결제하고 픽업하는 시스템 받자마자 빵냄새 때문에 못참고 하나 순삭함 갓나온 따뜻한 빵은 쵝오👍 집에 가서 식은빵도 데워먹으니 꿀맛 적당히 짠맛 때문에 감칠맛나고 빵하나 그냥 순삭임 두세트는 사야함요 :)', 55, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '성수에서만 구매할 수 있는거 연남에서도 구매할 수 있어서 너무 좋아요~! 단품으로는 판매 안하시고 1세트(4개)로만 판매하세요!', 5, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '영종도가 원조라고 들어서 알고는 있었는데, 가는 길에 마침 있길래 궁금해서 구매해봤어요! 엄청 맛있는 냄새가 나고 버터 아낌없이 들어갔고 소금 뿌려져있고 저는 하나 먹으니까 배부르더라구요💟', 17, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '저번에 먹고 너무 맛있어서… 서울 다시 놀러온김에 2봉지 샀습니다아!!! 제 인생 소금빵 ㅠㅠㅠ 길빵 하면서 너무 행복했어요오오❤️💖', 29, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '소금빵 버터 많이 들어가고 맛있네요. 우리것 하나 지인 선물로도 2세트 사드렸어요. 한 세트에 4개 들어가는데 2인(2개) 세트도 있으면 좋겠네요^^', 102, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '연암동 거리를 걷다가 사람들이 줄 서 있어서 사게 됐습니다. 소금빵인데 짜지 않고 맛있네요. 기름진 것이 입에 착 붙습니다. 커피랑 잘 어울릴 것 같아요', 32, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '성수에서 맛보던 자연도 소금빵을 연남동에서 👍 그냥 지나칠 수 없는 버터향 가득 소금빵을 바로 나온 그대로 포장해서 먹으면 따듯 쫄깃 부드러운 버터향과 함께 입 안에서 녹아버리는 맛 💕', 122, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '자연도 소금빵이 제가 먹어본 소금빵 중 젤 맛있어요 🥹 사람에 따라 살짝 기름지다고 느낄 수도 있는데, 전 오히려 겉은 바삭하고 속은 촉촉한 버터리한 식감이 자연도만의 매력이라고 생각해요 !', 48, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '익선동에서 줄 서서 먹는 소금빵 집이라길래 궁금해서 와 봤습니다 ^_^ 비 오는 날이라 그런지 이번에는 줄이 없었어요. 4개 1세트 단일 메뉴로 팔길래 친구들과 나눠 먹으려고 1세트 사왔습니다. 맛있었어요👍', 109, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '소금빵이 그냥 다 비슷한 소금빵이겠거니하고 지금껏 흐린눈하다가 웨이팅없길래 슬쩍사본🧐 버터향 미쳤고 식감도 미챴고..,🧈 다들 줄서는데는 이유가 있었음👍🏻 당연한 말이지만 따뜻할때 드세용', 45, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '가게 느낌과 포장은 그럴듯한데 너무 기름지고 너무 짜고 차가워서 별로..테이크아웃만 가능하고 최소 4개 세트(1.2만원)부터 판매하는데 미리 만들어놓은 걸 팔아 차갑고 맛없어요.', 107, 22, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '❇️ 지나가다 우연히 줄이 있길래 구입 ❇️ 계산하는 줄과 빵 받는 줄이 달라서 헷갈릴 수 있음 ❇️ 그냥 맛있고 느끼한 소금빵 맛', 4, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '영종도 가게 되면 꼭 먹고 싶었던 곳이에요! 워낙 유명하다보니깡 맛은 보장이여랑~~! 낱개로 구매는 어렵고 1봉지(4개)로만 구매 가능합니당!! 픽업만 가능해서 도로변에 위치해있어서 앞에 잠!깐! 주차하고 호다닥 구매했습니당! 감사합니당ㅎㅎ', 33, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PARKING');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '무조건 4개씩 묶어서만 판매. 1개나 2개는 구매 자체가 불가하고, 키오스크에 소금빵 4개 단일메뉴. 얇은 하얀 빵 봉투 종이백에 담아 주면서 종이백 여분 부탁하니 줄 수 없다고 함. 멀리 가야 해서 비닐 없냐고 하니까 비닐 도 없다고 함. 심지어 친절하지도 않고 집에 와서 보니까 빵이 너무 작아서 놀람. 맛도 별로. 하나에 3000원인데 다신 사먹지 않을듯.', 11, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '맨날 줄 서 있길래 궁금해서 사봤어요. 평일 오전 11시쯤 갔더니 줄이 짧더라구요. 소금빵이 나오는 시간대가 있고 4개 한 세트로만 구매가 가능하더라구요. 낱개로 안 팔아서 아쉬웠습니다. 맛보니 엄청 부드럽고 파사삭 하고 사라지더라구요. 길게 줄 서서 먹을 정돈 아니지만 맛있어요. 1개 3000원이라 비싼가 싶었는데 한번쯤 사먹을만 합니다!', 19, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '영종도에서 봤던 빵집!! 연남동에있어서 줄이 짧아서 구매해봤어요! 얼마인지 안내도 안되어 있고 결제할때 한세트 할거냐고 다짜고짜 물어보는데 …ㅋ 최소구매가 세트인가요? 세트가 몇개들었어요? 얼마에요? 질문을 폭풍으로 할수밖에없는..그런..아쉬운..곳.. 😢', 10, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '먹어보고 맛이 좋아 직장 동료들에게 간식으로 쏘았습니다~! 진하고 버터리한 풍미가 넘넘 좋다고 맛있게 먹어주어 감사했습니다~^^', 2, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '성수랑 연남에서 지나다 봤는데 평소 빵을 많이 사먹는터라🤭 사람들 줄 서있는 거 보니 궁금하더라구요 후기보니 오래 기다릴 정도는 아니라는🙄 평도 있었지만ㅋㅋ 연남 들어설 때 버터향이 강하게 나고 곳곳에 사람들이 앉아 먹고 있어 저도 구입해봤습니당!! 4개 세트 포장으로만 구입가능해서 웨이팅은 금방 줄었어요~~ 세상에서 제일 맛있다는 자신감이🧐 어떤 맛일까 했는데 소금빵 좋아하심 한번 먹어볼만 한 맛?!😎 겉바속촉이고 윗쪽엔 소금이 뿌려져 있고 바닥이 살짝 기름져요 포장도 들고 다니기 좋은 편이고 컨셉과 마케팅 성공사례가 아닌지ㅎㅎㅎㅎ', 82, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '딱 한가지 소금빵만 판매하고 일일 판매량 끝나면 운영을 마치는 자연도 소금빵. 압구정과 성수에 이어 연남에서도 보게되어 지나가다 사먹어봄ㅋㅋ 역시 맛있고 바로 따끈하게 나오는 맛이 포인트임. 아침부터 외국인 줄서고 바쁜 매장. 여전히 맛있음~', 33, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '그냥 지나가다가 있어서 들른건데.. 언니가 유명한곳이래요!!! 길가다가 길빵하면서 먹었는데 wow 왜 유명한지 바로 알겠어요 밑에 부분이 바삭하면서 버터맛이 확 오는데..!! 진짜 너무 맛있어서 다음에 서울 또 오면 언니랑 같이 먹으려고요 언니도 먹고 엄청 맛있다면서 극찬을 아끼지 않았어용 ㅋㅎㅋㅎ', 114, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '연남점이 생겨서 들려봤습니다. 기대가 높았는데 기대한 만큼 엄청난 맛은 아니여도 부드럽고 버터향이 진하게 나는 맛있는 소금빵이였습니다.', 20, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '소금빵 맛있어요. 근처살아서 여러번 사먹었어요. 다들 친절하셔서 늘 기분좋게 사먹었는데 직원분이 바뀐건지 굉장히 불친절하시네요. 웨이팅이 있는것도 아니고 사람이 많은것도 아닌데 왜이리 호통을 치시고 명령을하시는지 내돈내고 빵사면서 빌어먹는 기분이네요 저하나 다신 안사먹는다고 매출에 영향 1도없겠지만  그래도 서비스 점검은 한번해보시길  바랍니다', 91, 23, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '소금빵 중 단연 1등 🗯️❗️ 자연도소금빵은 줄이 조금이라도 짧다 ? 그럼 그럼 사셔야합니다 . . 고소 짭짤 + 버터 풍미 조화가 뭐하나 과하지않게 맛있는 소금빵입니다. 밑부분 콰자작 먹을때 도파민 풀로 터지거든요 🥹 사자마자 길에서 바로 길빵💥하시는 걸 추천드립니다 ⛧ 줄이 길더라도 빵 나오는 시간들이 있어서 오래 줄 스지 않아 더 좋습니다. ( 옆에서 결제하고 줄 라인에서 대기하시면 됩니다 ) 리뷰 쓰면서도 먹고싶은 맛 . . . 🤤', 124, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '소금빵 맛집 ~ 연남동에 있어서 방문하기 편해요!! 소금빵 키오스크로 주문해서 편합니당 4개씩 판매해서 포장해가기 딱 좋아요~ 소금빵 좋아해서 자주 사먹는데 여기 너무 맛있어요 ㅠㅠ 최고👍🏻👍🏻👍🏻', 27, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '빵 사진을 못 찍었는데 자연도소금빵은 제 최애 소금빵집이에요🫶🏻 처음에 명동이었나? 거기서 먹었다가 반해서 항상 보이면 무조건 사먹어요! 📍꿀팁은 빵 나오는 시간대에 사셔야 훨배 맛있어요! 📍기름기가 있으니 휴지있으면 감싸서 먹으면 손에 안 묻고 즐길 수 있어요 ㅎㅎ 📍그냥 보이면 꼭 사 드세여… 개추 누르고 가게 되실 거예요 ㅋㅋㅋㅋㅋㅋ', 23, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '지나가는 사람들이 들고다니는 하얀 봉투가 심플하고 호기심을 불러일으키는 가운데, 빵냄새에 이끌려 구매! 4개 포장판매! 일일 개수 제한! 맛보면 나눌려고 충동구매하게 됨! 그냥 맛보고 체험하세요. 소금빵이 맛있다는 거! 음료없이 잘 먹힌다는 거 알게 됨! 노하우로 만들어진 소금빵, 잘 먹었습니다.', 14, 3, 'GOOD', SYSTIMESTAMP);
