INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '을왕리 자연도 소금빵 다녀왔는데 너무 맛있는 곳🫶🏻 을왕리도 생기다니 ㅠㅠㅠ 빵 나오는 시간 맞춰서 구매해서 따뜻하고 맛있었어요', 91, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '저때 줄서있길래 눈여겨 봤는데 이번에 줄없어서 먹어봤어요 오…! 인생 소금빵이에요 겉바속촉이랑 다른느낌 크로와상 느낌이 나는 소금빵이에요!!!! 소금맛은 별로 안났지만 버터맛이 많이 나는 소금빵이였어용 ㅎㅎ', 12, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '비가 내린 날이라 대기가 전혀 없어 친구꺼랑 같이 구매했는데, 집에서 먹어보니 먹어본 소금빵 중 진짜 맛있네요!! 고소한 향이 좋았고, 재료가 좋은게 느껴졌어요!!', 20, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '예전에 영종동에서 먹어봤는데 연남동에도 생길걸 보고 냉큼 사왔네요 ㅋㅋㅋ 간만에 먹었지만 겉은 바삭 속은 촉촉🥐 여전히 맛있어요! 에어프라이어에 데워먹으면 더 맛있음😋', 5, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '제가  빵빵 거리는 사람이 아닌데, 소금빵 여기꺼 먹고  빵빵거려요  다른 소금빵이랑 비교불가😂 심지어 가격도 4개 12000원,,,, 다른곳보다  저렴한데 젤맛있어요👍👍👍', 4, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '✔️음 생각보다 평범해서 아쉬웠던 맛ㅠㅠ 꼭당일에 먹어봐야지하고 오후 6시쯤 구매해서 근처 스벅가서 먹었는데,, 재구매까진 모르겠다 ✔️꼭 4개씩 구매해야하는것도 좀 아쉽고 궁금했는데 먹어본걸로 만족입니당', 126, 24, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '제가 먹은 소금빵 중에 제일 맛있음(몇개 안먹어봄 부산에서 맛있어서 연남에서 먹어봤는데 줄은 20분정도 기다린 것 같고요. 버터가 많아서 기름집니다. 짱맛', 35, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '길을걷다 사람들이 줄지어 있길래 보니 소금빵집이더라구요 계획에는 없었지만 한번 먹어보자해서 구입했어요 낱개로는 구입이 안되는것 같고 세트로 봉투에 담아서 판매해요 회전율이 빠르다보니 빵이 따뜻했어요 좋은재료로 만들어지는 빵인것같아요 봉투에 써있는걸로봐서는. 맛은.. 소금빵맛이에요 ~ 갓구워나온빵은 진리죠 무조건 맛있죠 식었을때는 어떨지모르겠지만 4개구입했고 12,000원이요 개당 3000원이네요 갓구워나온빵이 먹고싶다면 추천하지만 굳이 가서 먹진않을것같아요~(저는)', 54, 15, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '요즘 가는 핫플마다 있어서 사먹기 편한 자연도소금빵! 줄이 너무 길어서 기다릴 엄두를 못 내다가 줄이 별로 없는 걸 발견하고 얼른 사먹어봤어요 그 동안 먹어본 소금빵 중 단연코 no.1입니다 일단 재료가 좋아서 천일염 맛이 잘 살아있어 짭쪼름함과 버터의 풍미가 매우 잘 어우러져요 빵도 쫄깃쫄깃 너무 맛있어요', 15, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '지나가다 구매하게 된 곳인데… 진짜 맛있어요❤️❤️따뜻할때 먹어야 진짜 꿀맛 ㅠㅠㅠ 여기 소금빵이 생각날정도로 맛있었어요✨ 최고👍🏻👍🏻', 5, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '비싸긴 하지만 제 인생 소금빵이에요! 버터향이 진해요. 선물용으로 샀습니다. 먹을 수 있는 공간은 따로 없습니다. 최소 주문은 4개=1세트 12000원입니다. 4개는 많은가 싶다가도 너무 맛있어서 계속 먹게 됩니다.', 23, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '연남동 들렀다가 아이도 좋아하는 자연도 소금빵 구매해왔어요!! 항상 사람이 많은데 운좋게 바로 살 수 있었어요👏🏻 버터향 그득하고 바삭짭짤한 맛이 정말 맛있어요!! 45개월 아이도 하나 뚝딱 먹네요☺️', 27, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '금요일 기준 1시 반 조금 넘어서 방문했는데 12시 반 소금빵이 남아있어서 바로 구매했습니다@ 갓나온빵이 아니라 식었지만 에프에 구워먹으려구용', 36, 6, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '다들 가게 앞에서 사진찍길래 저도 찍어봤네요 ㅋㅋ 낱개로 살 수 없고, 저렇게 셋트로만 판매해서 처음에 살까말까 고민 했어요 ㅋㅋ(4개들어있어요) 그냥 맛만볼려고 했던거라..~ 소금빵 좋아하니까 그냥 샀는데, 진짜 버터향 많이 나고 쫀득하니 맛나긴 하네요~ 포장만 가능하다보니 연남숲길에 자리잡고 바로 먹기도 하던데 ..(너무 추워보여서.. 먹다가 체하면...;) 집에서 에어프라이어에 180도 3분 돌려서 커피와 먹었는데 맛있네요 ㅎ 또 사먹을 순 있을 것 같아요! (그런데 바닥이 살짝 탔더라고요 ^^;) 웨이팅 아주 조금 있는데 금방금방 빠져요. 간단히 선물주기도 좋을듯 해요', 36, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '4개씩만 판매한다 하셔서 12000원에 구입! 바닥부분은 버터에 절여(?)져서 기름범벅이에요 제 취향은 아니었어요 윗부분은 쫀득해서 맛있었구요!', 65, 12, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '⭐️ 연트럴파크 걷다가 들려야할 자연도소금빵 ⭐️ 연남동에 위치한 자연도소금빵~ 성수동에서 맛있게 먹었는데 연남동에도 생겨서 좋았습니다~ 맛은 여전히 맛있고 갓구워지자마자 먹으면 극락🩵', 28, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '열시에 스크럽마사지 예약 시간 맞춰 연남동 가서 자연도소금빵 키오스크 줄섬. 토요일 이지만 아침 9시반이라서인지 줄은 외국인 다섯팀 정도.. 직원 한명이 나와 키오스크 앞에서 당황하는 외국인을 도와 익숙하게 주문 해 줌. 주문즉시 바로바로 포장해서 나옴. 구입은 4개 단위로 살수 있으며 난 트레이너 쌤 선물하려 4개 한셋트만 구입, 왜냐면 내 냉동실에 이미 몇개 잘 있는 상태라서...  쌤 반응 좋았음. 방금나온 버터뤼한 소금빵은 그 자체로 입에 촥 감기니까... 같이 사가지고 간 스벅 더블크림에쏘라떼랑 찰떡... 못참고 두개 연속 드심.ㅋㅋㅋ 덕분에 즐거운 분위기에서 스크럽마사지 끝맞췄지만 그만큼 마사지 후 점심식사가...덜 감동적이었다는 후기...', 36, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '경의선 숲길 지나가다 궁금했는데 아침에 금방 나온 4개 세트로 구성되어있는 소금빵 먹었어요. 소금빵이 속과 겉이 부드럽고 찢어먹을때 잘 찢어지는 빵이었어요^^ 산책하며 간식으로 먹기 좋은 담백한 빵이예요. 버터향이 가득한 부드럽고 고소한 소금빵입니다.', 25, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '길가다가 냄새를 못참고 그만....ㅎ...... 소금빵만 판매하고 결제줄 픽업줄 따로 있으니 꼭 확인잘해주세요! 외국인 손님이 많아서 고민하다가 샀는데 길빵했다는 ㅎ 따뜻하게 드십쇼.....ㅎㅎ 또 먹구 싶네요ㅜ', 29, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '빵 시간 맞춰 가게 되서 바로 한 봉지 사서 먹었어요~ 4개가 한 묶음이고~ 제가 먹어본 소금빵 집 중에는 제일 괜찮네요~ 버터와 소금의 조합이~ 너무 좋았고 향이 대박입니다~ 안 살 수가 없었어요~ 대기 줄이 없어서 쉽게 살 수 있었어요~ 주말에는 줄이 엄청 나겠죠? ㅋ 맛난 소금빵!!!', 54, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '연남 경의선 철길공원 가면 그냥 지나칠수 없는 곳, 지나가는 수많은 인파에 많은 사람들 손에 들고ㅈ다니는 하얀 종이주머니들... 그리고 근처에 가면 벌써 훅 들이대는 찐하게 구워대는 버터향기, 어디지? 하고 둘러보면 두줄로 길게 늘어선 외국인들을 볼수 있다. 연남에서 저녁 먹고 헤어지기 아쉬워하며 전철역 쪽으로 가다가 왠일로 대기 줄이 짧아서 반가운 맘에 얼른 세셋트 포장주문...잔뜩 먹어 배부르지만 이거  한봉지씩 집에 들고가면 왠지 기분이 좋다.. 밤에 미지근할 때 한개만 먹고 담날 데워도 고소하게 결대로 찢어져 충분히 맛있다.', 41, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '남자친구랑 동네 산책하다가 오늘은 연남동까지! 몇달 전에 익선동 갔다가 소금빵 줄 섰는데 바로 앞에서 끊겨서 못 먹고 아쉽게 돌아갔는데ㅠㅠㅠㅠ 연남동에도 있어서 사서 벤치에서 한입 냠 오른쪽 줄에서 키오스크 주문결제 후 왼쪽 픽업 줄 다시서야하는데 어르신들은 잘 모르시고 줄 서시기도 하시더라구요 밀은 캐나다 버터랑 소금은 프랑스산이라는데 버터의 눅진함에 결결이 찢어먹으니 정말 맛잇어요ㅜㅠ 소금빵 나오는 시간이 정해져 있어서 시간 맞춰 온다면 따끈한 갓 나온 소금빵을 먹을 수 있을 것 같아요🤍', 48, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '유명한 자연도 소금빵을 홍대에서도 보게 되었네요! 이제 서울 서쪽과 동쪽에서도 다 만나볼 수 있다는게 넘 좋아여ㅎㅎ 맛은 말해뭐해 넘넘 맛있어요! 다만 포장 전용 매장인게 아쉬워요', 19, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '지나가다가 사람이 많길래 저도 하나 샀어요ㅎㅎ다행히 웨이팅은 금방 빠졌고 직원분들도 친절했어요.소금빵 맛집으로 유명한 곳인거같더라고요?솔직히 제 기준 웨이팅할 정도는 아니었지만,그래도 괜찮았어요😂', 34, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '영종도에서 우연히 지나가다 줄이 길게 서있어서 처음 자연도를 알게되었고,너무 너무 맛있어서 검색해보니 가까운 연남동에 있다는걸 알고 주말에 종종 모닝으로 먹고 있습니다.거의 오픈시간에 맞춰 가기때문에 연남에서 대기한적은 없어요~~~먼저 키오스크에서 주문하고,픽업대기줄로가서 주문한갯수만큼 받을수 있고  소금빵도 맛있지만 친절에 기분이까지 좋아져요~ 버터에 고소함과 바삭한 식감  너~~~~무 맛있어요. 운전하고 오면서  빵을 다 먹어서 빵은 찍지 못했어요 안먹어본 사람은 있겠지만 한번만 먹어본 사람은 없을듯 합니다 아마도!!  :) Top Five안에 드는 소금빵 입니이~~', 80, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '일단 무조건 길빵을 하십쇼 바로 먹어야 제일 맛있더라구요 냉동하고 에프에 구워먹어도 된다고해서 여러개 샀어요 성수에서 줄 너무 길어가지고 못먹었는데 연남에 생겨서 너뮤 좋아용', 101, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '빵은 다음날 먹어도 맛있음.. 두개 주문했는데 따로 손잡이가 불편해서 가져가기는 힘드네요.. 별도로 쇼핑백 있었으면 하는 바람이에요', 18, 2, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '9시에 소금빵 첫 나오는시간. 맬맬 상당한 줄을서서 못샀는데 오늘은 일찍 나가는길에 대기자없이 바로 나온빵을 살수있어서 기분좋네요. 아직 안먹어봤지만 좋은재료로 만들었다니 기대해봅니다.', 48, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '웨이팅이 길고 냄새에 홀려서 사게된 소금빵 빵이 나오는 시간이 정해져있고 웨이팅은 짧은 편 딱 잔형적인 소금빵이고 버터동굴은 있지만 그 안에 버터의 촉촉함...?이 느껴지는 버터동굴은 아님 4개 12000원 세트로 팔고 있어서 웨이팅이 없다면 먹어볼만한 곳', 108, 22, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '연남동 경의선숲길 다녀왔어요 날씨가 좋아서 걷다가 그늘에 앉아 쉬기도 했어요 그리고 필수코스~~!! 자연도소금빵 🥐 오늘도 역시 줄이 길었지만 고소한 버터냄새 맡으며 즐겁게 기다렸어요 4개들이 2봉지 구입했고 맛있게 먹었습니다 👍', 34, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '오랜만에 만나는 옛 직장동료... 와의 저녁식사에 끝나고 들고들 가라고 자연도 소금빵 한봉지 구입... 식사후엔 못 살까봐 대기 줄 없을 때 얼른 구입. 맛이야 아는 맛이니 헤어지고 집에 가서도 버터가득 고소하고 쫄깃한 소금빵 한입 하면서 만남의 여운을 즐기기 바람.', 47, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '연트럴파크 줄서는 투고 맛집 버터에 푹~~~ 절인 소금빵 역대급 독보적인맛 👍 단 구매후 뜨끈할때 바로 먹어야 제맛을 느낄수있다는 사실🤗🤩', 9, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '홍대 갔다가 사람들이 엄청 줄서있는곳이 있길래 저도 모르게 줄을섰어요(?) ㅎㅋ 알고보니 평소에 엄청 먹어보고 싶었던 자연도소금빵!! 포장해서 에프에 돌려서 먹어봤는데 와.. 진짜 인생소금빵 .. 😋 버터풍미가 대박이고 겉바속촉에 적당한 짭짤함까지 빵자체도 너무 맛있어요 한봉지만 사온 저에게 너무 화가나네요 다음에 가면 무조건 왕창 쟁여오려구요 ☺️ 직원분들도 친절하세요! 조만간 또 갈게요 !', 349, 93, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '아니 밑바닥이 너무 맛있어요,, 소금빵 바닥부분 맛있는 곳 생각보다 그렇게 많지 않던데 너무 맛있음 다음날 먹은건데도 맛있음😋', 41, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '평소에 사람들이 줄 서 있어서 기대하고 먹어봤는데 생각보다는 무난한 맛? 겉이 바삭한 소금빵을 원하면 여기보다는 다른 곳을 찾아야할 듯~_~', 68, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '맛있어요… 기름 쫙쫙 나오구… 다만 오랜 웨이팅으로 먹을 맛은 아닌? 저는 웨이팅 없이 바로 구매하고 먹어서 괜찮았던 것 같아요. 특별한 맛은 아닙니다~', 40, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '맨날 줄서있어서 궁금했는데 오전엔 좀 힌가한듯하여 먹어보았습니다. 버터가 가~~~득 들어간 묵직한 맛의 소금빵이었어요. 그래서 그런지 첫입의 감동이 컸습니다. 지나가다가 줄이 적으면 한번쯤 또 사먹고싶습니다. - 4개 세트가 기본입니다. 낱개로는 안파는거 같아요', 12, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '자연도를 통해 소금빵의 진가를 알게 되었습니다.😹🤤😹 이날 눈이 오는날이였는데 길에서 먹다가 울뻔 했습니다. 바삭바삭한 빵 사이러 흐르는 버터의 고소함과 소금의 짭짜롬함이 절 미치게 만들어요! 연남동 가면 출근도장 퇴근도장 찍게 만드는 곳! 연남동 도착? 바로 자연도🚶 집에 간다? 바로 자연도 🚶 집 앞에 있어줘 제발 ,,', 24, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '종로점에서만 먹다가 연남동에도 있길래 방문했는데... 너무 실망스러웠어요ㅠㅠ 제가 알던 자연도 맛이 아니에요 종로랑 왜 다른거죠? ㅠㅠ', 4, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '연트럴파크 들렀다가 빵냄새에 이끌려 들어갔어요 매장도 너무 이쁘고 저 다음으로 줄이 갑자기 길어져서 놀랐네요! 소금빵은 4개 세트로만 파는게 아쉬워요! 빵은 맛있어요~', 7, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '키오스크에서 꼭 먼저 결제하시고 대기줄에 서세요. 모르고 줄 부터 서시는 분들이 간혹 있어요. 결제하고 줄서면 생각보다 빨리 빵을 받을 수 있어요. 버터리하면서 맛있는 소금빵입니다.', 16, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '잠깐 기다렸다가 갓 나온 빵으로 받았는데 원래 바로 나온 빵은 이렇게 맛있는거구나 하고 감동받았어요 너무 맛있다 진짜 최고❤️‍🔥❤️‍🔥 근데 그 전 시간에 만들어진 빵들은 어떻게 되는건가요? 폐기?', 22, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '본점이 따로 있고, 홍대점은 생긴지 그렇게 오래되지 않았지만 아내랑 딸이 이 집 빵 좋아해서 오가다 사람 없으면 사갑니다. 관광객들도 많이 구매하는 것 같던데... 사면서 앞에서 빵 먹고 있는 일본 가족들이 "오이시~"하는 거 보고 맛집은 맛집이다 했습니다.(일본도 워낙 괜찮은 빵집이 많은 나라라서요)', 4, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '빵집에 사람들이 줄서서 기다리니 호기심에 두박스 구매함 운전하면서 한개 먹어보니 기름빵이라서 집에서 데워먹으면 괸찮을줄 알았지만 너무 느끼함 딱 한개만 어떤맛인지 먹어보면 그걸로 아~~ 이렇구나 끝... 소금빵이 기름소금빵 인줄 알았음... 그냥 호기심 딱 거기까지임...', 17, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '경의선 숲길 걸어다니다 많은 사람들이 줄 서 있길래 봤더니 소금빵을 파는 곳이네요. 아이들이 소금빵을 좋아해서 구매해서 먹어보았고, 차원이 틀린 식감이었어요. 아이들이 너무 맛있어서 한번 더 샀어요.', 36, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '연트럴파크 걷다가 줄이 엄청 길길래.. 뭐지 했는뎅 소금빵 맛집이더라구용 낱개로 판매 안하구 박스로 판매하고, 유명한 체인점이었어용 외국인분들이 엄청 많이사가시더라구요 ㅋㅋ 성수랑 압구정 홍대 세군데에있어요 테이크아웃매장이라 금방구매가능합니당', 57, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '4개1세트로 밖에 안팔아서 낱개로 구매가 안되는 부분은 조금 아쉬웠습니다만 뜨끈한 바로나온 소금빵 맛은 미쳤습니다 ㅠㅠ 바삭한 부분이 많아서 넘 고소하고 맛있어요', 11, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '나 소금빵 그냥 그런데..  라고 해놓고 받자마자 길빵으로 다먹어치워버림. 뜨끈하고 부드럽고 겉바속촉 짭짤 고소 미쳤음ㅜㅜ 이런 소금빵이면 진짜 인정이요!! 왜 줄서서 사가는지 이해되는맛', 19, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '저녁 거하게 먹고 경의선 숲길 산책중 자연도 소금빵이 보여 1봉지 픽해봅니다. 둘째가 유모차에서 자느라 저녁을 못 먹어 배고플까봐 산것도 있지만 자연도 소금빵은 그냥 지나칠수 없었기에 산것도 있어요ㅋㅋㅋ 근처로 지나가면 고소한 버터향이 너무 나서~~ 배고픈 분들은 참기 어려울듯^^ 사자말자 한입 먹었는데 너무 고소 하네요ㅎㅎ 자연도 소금빵은 핫한곳은 다 있는듯 하네요~~(성수동, 익선동,연남동)', 68, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '연남동 태국식당 저녁약속 전에 미리 포장 해서 공수함. 저녁식사 과식으로 배 부르지만 못참고 밤 늣은 시간에 두개 흡입... 진한 버터향 고소짭잘...나머지 두개는 상온에 밤치했다가 담날 데우지도 않고  먹어도 너무 맛있음.  이틀 까지는 그냥 계속 맛있음.', 13, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '운이 좋았는지 바로 구매할 수 있었습니다. 빵이 막 나오는 시간었어요^^ 지인들도 빵을 먹고 다들 맛있다고 좋아했습니다. 어떤 소금빵은 버터가 흘러 나와서 별로인데 이곳 빵은 그렇지 않고 맛있다고 했습니다. 인기가 많은 이유가 있습니다^^', 50, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '자연도소금빵.. 지난번 감질나게 하나 먹었는데 오늘 두봉지 득템 밥먹고 오자마자 구입해서 받자마자 1봉지는 뚝딱.. 3봉지를 샀어야했을끄나^^ㅋ 계속 생각나는 소금빵입니다~  ^^ 홍대는 오른쪽에 키오스크 줄부터 먼저 ^^', 36, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '출근길 빵 냄새에 못참고 샀어요 우선 인테리어도 너무 이쁘고 포장도 정성스럽게 해주시고 기분좋게 빵 들고 출근 했어요🤩 소금빵 너무 맛있어요~~~🫶🏻', 125, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '생긴지도 몰랐어요 그냥 길가다가 있길래 샀어요 ㅎㅎ 다른지점이랑 다르게 줄없이 바로 살수있음 집에서 발뮤다로 살려서 먹었는데 버터 역시 많네요', 70, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '솔직히 맛있어요 소금이 떨어지지 않고 붙어 있는게 정말 신기하구요 밀은 캐나다 최고등급 프랑스 토판 천일염 버터는 AOP 인증버터 (특정지역에서 전통방식으로 생상하는 것을 인증 받은 것) 재료 자체를 선별해서 만들고, 자연도만의 방법이 있기에 맛있어요 지나갈때마다 버터 냄새에 포장안할 수가 없죠 익선, 청담, 성수만 가다가 드디어 서북권에서도 편하게 구매할 수 있어서 좋네요 낱개로도 팔아주면 좋을 것 같고 매장내 안내판에만 있는 문구를 종이봉투에 표기해준다면 단점이 없을 것 같아요 선물하거나 그러면 항상 그걸 묻더라구요! 이곳은 모르시는 분들이 없기에 자세한 설명은 생략해볼까 합니다!', 44, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '지나가다가.. 검색해봤는데 유명한 소금빵 맛집이라고 해서 포장해왔어요! 온니 포장만 가능한 곳이예요. 그리고 메뉴도 오직 소금빵4개 1세트 12,000원 밖에 없어요. 그래서 빨리 나오는 장점이 있지만, 갯수 선택해서 살 수 있으면 좋겠네요. 귀찮아서 그냥 먹었는데... 버터 풍미가 진한 약간 기름진 소금빵인데, 쫄깃하면서 짭쪼롬한게 빵 맛은 좋네요. 에어프라이어에 돌려먹으면 더 맛있다고 하니, 다시 먹어봐야겠어요. 빵 맛은 좋아요👍', 2, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '연남동에서 놀고있는데, 소금빵 핫플이 보이는거에요 ! 💙💙 빵순이인 저는 지나칠 수 없었죠 ,, 헿 4인 가족 먹을 4개분량을 똭 사버렸다쥬..😖🩶 저는 바로 못먹어서 냉동 후 에어프라이기 돌려 먹었는데 진-짜 맛있었습니댱 🫠🖤 연남동 가면 또 하나 구해올 것 같아요 !!!', 48, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '소금빵 여기가 제일 맛있다고 그래서 선물로 사갔어요 다들 맛있다고 넘 좋아하네요😆 친구들도 소금빵은 아랫부분이 갈색(?)이면 맛있는거라며ㅋㅋ 좋아하네요', 63, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '믿고 먹는 자연도 소금빵! 성수에서 처음 먹어보고, 좋은 기억이 있어서 홍대에 오픈한 체인점에 바로 달려갔습니다. 너무 좋습니다 :) 따뜻한 상태에서 먹는 달달하고 고소한 겉바속촉 소금빵 너무 맛있게 잘 먹었습니다! 홍대 갈 때마다 사서 먹을 것 같아요👍😍', 106, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '소금빵을 4개 단위로만 살 수 있어요! 키오스크 주문 - 소금빵 수령이 기계적으로 이루어지는 시스템. 소금빵은 매우 맛있었다.', 7, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '길을 지나다 새로 생긴 곳인데 소금빵만 파는 게 특이해서 구입해 봄. 1개만 먹어보려 했으나, 한 번에 4개를 한꺼번에 판다고 해서.. 12000원 주고 4개 사 봄. 엄~ 청 맛났으나.. 나중에 먹어보니 이건 복불복이었음. 맛있었을 땐 오후 12시 반에 나온 빵이었으나 나중에 오전 9시에 나온 빵을 먹으니 기름지고 완전.. 그냥 크로아상과 다를 바 없었음. 맛나긴 하나 맛이 일정하지 않는 것 같음.', 31, 7, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '소금빵 대표맛집 연트럴파크 놀러갔다가 웨이팅없이 구매 맛있는 아메리카노함께 먹으면 진짜 맛있어여 버터향이 가득해서 빵지순례필수코스랍니다', 36, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '역이랑 가깝구 먹어본 소금빵 중에 제일 맛있어요.. 하나도 안질기고 부드러워서 맛있서요..🥹 홍대 놀러 갈때마다 사오는거 같아요ㅎㅎ', 15, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '유햄한참일때는 엄두도 못내다가 줄도 적당하고 해서 겟 워낙에 이런저런 소금빵 다 먹어봐서 별 감흥은 없었지만 궁금증 풀어서 만족', 47, 5, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '연남동 지나갈 때마다 버터 냄새를 참기 힘들었는데 드디어 구매해버렸습니다...! 역시나 자연도 소금빵은 맛있어요... 벌써 n번째 먹고 있지만 매번 다 맛있네요!', 39, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '출근길에 ..빵냄새가 자꾸 절 유혹해요.. 저녁엔 항상 줄이길어 아침마다 유혹을 참지못하고 사는데 너무 맛있습니당~ 소금빵중에 최고여유', 65, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '일반적인 원조 소금빵과는 다른 느낌일 수 있지만 맛이 없진 않아요! 겉이 한껏 바삭합니다. 꽉찬쫀득 느낌 보다는 페스츄리 느낌이 강하구요. 꼭 한번 먹어보긴 하세요! 느끼할 수 있는데 저는 원래 느끼한걸 좋아해서 잘 먹었어요!!', 28, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '부드럽고 맛있네요. 버터가 많이 들어가서 다서 기름져요. 4개씩 판매하는데, 개당 3천원이네요 ㅎ 직원분들은 겁나 친절하세용.', 87, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '근처에서 점심먹고 나오는길에 빵이 맛있어보여 살짝 줄서서 샀네요~ 소금빵 전문점인가봐요~ 4개한세트 저렇게 포장해주시는데 포장깔끔하니 좋더라구요 바로먹었으면 더 맛있었을텐데 배가불러 집에와서 저녁때 먹었는데도 쫄깃하니 맛있더라구요 담에 서울갈때 또가봐야할듯!!!', 37, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '소금빵을 너무너무 좋아해서 간판에 소금빵이 적힌걸 보고 바로 구매했어요 사실 하나만 사먹고싶었는데 꼭! 세트로만 팔더라고요 당황해서 그냥 구매해서 먹어봤는데 흠… 무슨 자신감으로 세트로만 파는것인지 모르겠어요 맛없진 않아요 맛있어요 근데 좀 느끼해요 식감도 그렇게 특색있진않구요 혹시나해서 에어프라이기로 데워먹어봤는데 더 맛있긴하지만 역시나 특별한 맛은 없네요😞 재구매 의사 없습니다 직원분들은 친절하셨어요', 12, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '소금빵 안좋아하는데 우연히 지나가다 줄서있길래 기대없이 사봤는데 먹어본 소금빵중 1등임.. 겉바속촉 이런게 아니라 풍미넘치고, 겉모습은 모닝빵같은데, 베어물면 얇은 부드러운 패스츄리느낌! 간도 좋고 밸러스가 완벽!', 47, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '자연도소금빵 유명하다고해서 인천가볼까했더니 동네생겼음  주말에는 사람진짜많아요 빵나오느시간에는 줄이 길어요 2시빵 3시에 사먹음. 밑에부분이바삭바삭 위에는  폭신폭신. 버터리합니다 버터버터빵. 굉장히 고소해요.  4 개 셋트로만 팔아요. 많은 소금빵을 먹어봤는데 여기 소금빵  괜찮다!!??', 47, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '기다려서 먹을 소금빵. 짠듯 느끼하게 맛있음. 봉투에 든 빵 넷을 먹는데 줄어드는 게 아까울 정도로 좋았음. 먹어볼만함. 앉을 자리 없이 기다렸지만 그럴 정도는 됐음.', 74, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '연남동에 새로 생겼는지 줄은 하나도 없었어요! 최소 4개부터라 아쉽지만 소금빵 엄청 부드럽고 짭짤한 버터로 바닥면이 구워진 느낌이라 새로워요 😋', 368, 30, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '📍주문줄과 수령줄이 양쪽으로 나눠져있어요. 오른쪽에서 키오스크로 시간대별로 오픈되어있는 상품으로 구매하시면됩니다! 4개씩 한세트가 (12,000) 단품으로 구성되어있습니다. 빵은 에어프라이어에 데워서 먹었는데 역시 풍부한 버터맛이 맘에듭니다. 아쉬운점은 줄이 있는데도 불구하고 모두가 중구난방서있어서 중간중간 대기중인 손님들 정리해주시면 더 좋을 것 같습니다.', 24, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '항상 웨이팅이있는 곳인데 평일 아침에 줄이 하나도 없길래 빵 사봤어요. 무조건 4개 세트로 구입해야하네요. 소금빵 4개 12,000원 맛 없는 건 아닌데 요즘 이정도 소금빵은 어딜가든 먹을 수 있지 않나요…? 왜 줄이 그렇게 까지 긴건지 모르겠음', 65, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '자연도소금빵이 서울에 있다니🤍 제가 유일하게 조아하는 소금빵인데 너무 반가워서 보자마자 직진해서 구매했어요 다음날 아침에 살짝 데워서 우유와 함께 먹었답니다🫶🏻🥐🤍', 17, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '맛이 복불복 며칠 전 먹을때 넘 맛있어서 지인에게도 선물해 주려고 3봉지 가지고 왔는데..  세상에 ㅠㅜ 기름지고, 거뭇거뭇한 게 많이 묻어있더니.. 그 부분은 다 짜고 완전.. 기름범벅 크로와상. 처음 먹은 건 12시 반에 나온 걸 50분 뒤에 산 거였고, 이번에 산 건 오전 9시에 나온 걸 12시쯤 산 거였는데.. 완전.. 이거 뭥미?? 12시 반 껄 사야하는 건가? 이게 왜 그런지 모르겠음. 맛이 일정하지 않으니.. 뽑기하듯 먹어야 함', 50, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '일요일 오후인데 웨이팅 없이 바로 키오스크 주문했어요 하나씩 살 순 없고 4개 세트로 되어있는 것만 가능했습니다! 유명한 곳이라 기대 많이 했는데 생각보다 모닝빵 같은 느낌..? 재방문은 없을것 같습니다', 86, 18, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '매번 포장이 너무 예뻐서 선물하기도 좋고 구매할 때도 선물받는 기분이라 너무 좋은 것 같아요. 4개 묶음이라 살짝 많은 것 같지만 한번 먹으면 1~2개는 순식간에 먹기 때문에 ㅎㅎ 🙌여기 앞에 지나갈 때 빵냄새가 거리에서 엄청 나는데 홀린듯이 들어가게 됩니다. 아는 맛이 더 무서운 것 같아요🙌', 12, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '지나가다가 빵 냄새에 홀려서~ 샀어요!! 막 구워서 따뜻했고, 빵이 쫀득쫀득♡ 진짜 맛있어요! 그 자리에서 두개 바로 먹고 한 세트 또 사서 왔네요:)', 5, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '요즘 무섭게(?) 확장세를 보이는 자연도 소금빵이 연트럴파크에도 생겼네요. 오픈한 지 얼마 안 되어서인지 아직 줄도 짧아서 구매해봤어요. 4개씩 묶어서 판매해서 아쉽긴 한데 먹어보니까 아주 버터리해서 금방 순삭. 생각보다 부드럽고 쫄깃한 타입의 소금빵인데 에어프라이어 굽굽해서 먹어도 맛있을 것 같네요.', 92, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '지인이 사다달라고해서 방문했어요 한입 먹자마자 기름기가 잔뜩 속세의 맛이에요 다른 소금빵 보다 더 짭쪼름하구요 근데 계속 먹다보니 되게 별로에요 기름이 너~~무 많이 느껴져서 느끼하고… 그리고 3세트나 샀는데 종이가방 하나없이 그냥 끈으로만 묶어주네요.. 별걸 다 아끼네요.. 하나만 먹어보려고 낱개구매 문의했는데 낱개로는 못산다네요 ㅎ ㅋㅋ', 47, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '워낙 유명한 자연도 소금빵이 연남동에 오픈했네용!! 오픈한지 얼마 안되서 그런가 대기없이 구매할수 있어서 아주 좋았어용!! 에이스과자맛인데 너무 맛있습니당!! 참고로 4개 세트로만 구매 가능해요 👍👍', 30, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '연남사는 사람이면 안갈 수 없는 곳... 또 포장해서 먹었습니다. 저는 저녁에 사서 갓 나온 빵은 아니라서 아쉬웠지만 그래도 너무 맛있었어용. 우유랑 같이 먹으면 극락이니 참고하시길..', 114, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '가장 좋아하는 소금빵집이 집 가까운곳에 생겨서 좋아요~~ 매번 성수까지 가서 먹었는데 행복합니더 ㅎㅎㅎ 바삭, 촉촉하고 버터풍미 가득 느껴지는 소금빵 좋아하시는 분은 맛있어 하실거에요!!! 냉동하고 에어프라이기 돌려먹어도 맛있어서 4개 사가도 나쁘지않아요 하지만 하나씩도 판매하면 좋겠어요~', 84, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), 'well golly gee! I''m amazed! I''m from California...and I thought our bread was good. this bread is top notch and top shelf. hey!yeah! I love it like a latte.', 25, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '먹어봤던 소금빵 중에서 제일 기름이 많아요. 줄서서 먹는 집이라서 기대했는데 별 다를게 없는 빵이였어요. 그리고 소금이 뿌려지지 않은 부분도 짠 맛이 있네요.', 35, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '몇달 전 인천 항구 근처에서 구입-포장해 오다가 너무 맛있어서 차에서 다 먹어버린 그 소금빵이 연트런파크 바로앞에 생겼다. 넘 반가워...며칠 노렸는데 볼때마다 길게 웨이팅 있어 엄두를 못 내다가 평일 이른시간에 마침 줄이없어 얼른 구입했다.  작고 소중한 빵. .. 보드라운데 유난히 작아서 버터향 찐하고 더 맛있게 느껴지는 것일수도...십후라도 4개세트 한번에 끝나며 약간 아쉽기도. 간단하지만 귀여운 끈 포장도 한몫 해서 가벼운 선물용으로도 딱', 45, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '키오스크로 주문하고 15분 정도 뒤에 수령했어요. 매장 인테리어가 꼭 일본에 온 것처럼 분위기가 있네요. 빵도 따뜻할 때 먹으니 정말 부드럽고 맛있어요. ^^', 118, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '4개씩 묶음으로 구매 가능하고요. 평일 오후 2시에ㅡ가니 안 기다리고 바로 구매 할수 있었어요. 진짜 버터리 한데 신기하게 종이 가방이 안 젖었더라고요? 집에가서 데워 먹으면 더 맛있을거 같아요.', 35, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '4개 세트로만 판매해서 처음에는 좀 당황했지만 밀봉해서 냉동보관하면 되기도 하고 맛도 고소하고 버터향이 많이 나서 좋았습니다!👍🏻', 4, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '지나갈때마다 쏟아지는 고소한 향기. 운좋게 앞 손님께서 마지막 봉지를 양보해주셔서 영접했습니다. 너무 고소하고 맛있어서 집에 돌아오는 길에 두봉 더 포장했네요. 두고두고 생각날듯한 맛. 아~~지방러는 웁니다ㅠ', 21, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '지나가다가 우연히 발견하고 폭우를 뚫고 들어갔어요 낱개 판매가 안되는 게 아쉽지만 먹어보니 너무 맛있어서 다음에 오면 또 먹으려고용 ♡', 4, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '자연도 소금빵 웨이팅 없이 구매할 수 있는 곳! 산 날 먹는 게 제일 맛있오요ㅠㅠㅠ 바닥의 빠삭한 버터에 절여진 부분이 젤 맛있습니다', 89, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '냄새에 이끌려 우연히 사게되었는데 지금까지 먹어본 소금빵 중에 제일 맛있었어요.. 직원분들도 친절하시고 한 봉지만 산거 후회하고 있어요ㅠ 가족들도 먹어보고 너무 맛있다고 하고 나중에 또 서울에 간다면 무조건 들릴 것 같습니다😭 제가 사는 지역에도 언젠가 생겼으면 좋겠어요ㅠ!', 88, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '소금빵만 파는 소금빵 맛집..! 가게마다 특색이 좀 다른데 여기는 버터가 좀 많이 들어가서 시간이 지나면서 빵이 좀 눅눅해지고 식빵 같아진달까? 그래서 제 취향은 아니었어요..! 그리고 한번에 4개씩 사야하는것도 너무 많아요 ㅠㅠ', 26, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '줄이 길었는데 다시 오니 줄이 없어서 얼른 구매했어요. 바로 구워서 판매하니 인기가 좋은 것 같아요. 최소 판매가 4개들이라 맛볼려고 2개만 사고 싶었는데 어쩔 수 없었어요. 바로 먹으니 바삭하고 맛있는데 식으면 좀 느끼할 것 같아요.', 17, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '대기는 없었지만.. 일부러 시간떼우면서 빵나오는 시간 맞춰갔는데, 다 식은 만든지 오래된 빵을 주셔서… 황당 당황.. ㅜㅜㅜㅜ 맛은 있었어요.. 갓구운빵 먹고싶어요..', 20, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '한셋트만 산게 후회되네요ㅠ 정말 맛있어요 근데 줄서는 구조는 다시 한번 고려해 보시는게 나을거 같아요 겹쳐서 불편해요 아님 줄서는거 도와주시는 분이 계시는게 맞는듯 함니드', 35, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '익선동에서 여러번 사먹었고 연남 사무실근처 생겼길래 어머, 생겼네하며 1개만 먹고 싶었지만 4개 셋트로만 파시니 어쩔수 없이 오랜만 먹고 싶어  샀는데 익선동이랑 맛이 다르네요???, 1개만 사먹었다면, 덜 기분나빠 혹시 날씨따라 효모등 빵 숙성등 달라질수도 있다고 생각돼 다시 또 도전해볼수 있겠으나, 4개로만 파시니 12000원되는 피같은 돈을 기대에 못미치는 빵에 투자할수는 없을것같아 다시 사먹기는 어려울듯', 32, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '자연도소금빵in연남'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '마지막회차에 나온 빵을 겟했는데 너무 맛있어서 앉은자리에서 인당 2개씩 순삭했네요!!!! 왜 사람들이 줄서서 먹는 지 알것 같았어요. 버터맛이 너무 좋아요!! 빵 향도 너무 좋아요 ㅎㅎ', 16, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '요즘 핫한 밀크티 카페 헤이티를 다녀왔습니당! 저는 밀크티 엄청 좋아하는 편인데, 독특한 메뉴가 있길래 ‘말차 코코넛클라우드 블루’를 시켜봤어요! 🧋 아쉬운건 나와도 딱히 불러주시지 않고 번호로만 뜨는데 그것도 소리가 안나서 나온지도 몰랐어요 ㅠ 뭔가 알려줄수 있게 띵동 소리가 나면 좋을거 같아요! 그리고 밀크티 맛을 얘기하자면 아래는 코코넛밀크, 녹차폼이 살짝 올려져있는데 녹차향보다는 코코넛향이 강해요! 코코넛워터 마시는 느낌이랄까요..? 전 조금 아쉽긴 했지만 건강한 맛이 났어요 😅 (당도 70해도 많이 안 달아요! 단걸 좋아하시는 분은 100으로 드셔용!) 그리고 코코넛 좋아하시는 분들께 추천드려요! 양은 나름 많았지만, 그만큼 비싸긴합니다! 🥲', 23, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '홍대 ‘HEYTEA'' 흑당 버블티때문에 홍대 갈때마다 먹고와요 달달하고, 주문이 많이도 음료가 빨리나오고 직원분들더 친절해요!', 63, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '중국 국민티라고 할만합니다! 공차보다 펄도 훨씬 쫀득쫀득하고 부드러우며, 당도도 너무 적당하고 부드러워 목넘김도 좋습니다. 계속 생각나는 맛이에요 다만 얼음이 너무 많아 가격대비 음료가 조금 부족한 느낌도 있었어요 ㅎㅎ 홍대점은 외부에 대기 의자도 많아서 주문 후 나올때까지 앉아있을수 있습니다 또 방문할게요!', 30, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '대표 메뉴인 로스티드 브라운 슈가 보보 주문 중국의 국민 밀크티라고해서 기대가 너무 커졌나보다. 일단 주말 주문이라 줄이 길었고 주문도, 수령도 오래 걸렸다. 맛은 생각보다 진하지 않은 밀크티. 좀 느끼한 맛에 아주 달고 향이 강하다. 들어간 재료들이 전혀 조화를 이루지 못하는 느낌. 그나마 유일하게 좋은 점은 쫀득한 펄의 식감. 그 외에는 공차보다 못한 느낌이다. 그리고 자재관리가 안 되는 듯. 자꾸 새길래 뚜껑 결합이 잘 안 되었나 싶었는데 칼집 난 듯 갈라져있는 컵. 최악의 경함이라 또 찾지는 않을 것 같다.', 50, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '헤이티 핫해서 넘 궁금했는데 드디어 먹어봤어요오! 밤10시인데 대기20명있었어요! 한 30분 기다렸나,,ㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋ 가격대가 쎄긴한데 그 값 제대로 하는것 같아요! 맛이 엄청 깔끔하고 맛도리💙 리유저블컵은 와 쓰는건지 모르겠어요,,다 버리드먼,, 암튼 처음 드셔보시는거면 망고사고츄천! 상콤달달 존맛탱구리입니다🥭💯👍🏻', 18, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '상하이 여행 갔을 때 맛있게 먹었던 기억이 있어서 기대하고 먹어봤는데, 가격도 상하이에 비해 높고, 맛도 달라요.. 그래도 여행가서 먹을 수 있었던 걸 가까이서 먹을 수 있으니 가성비라고 생각합니다 ㅎㅎ', 13, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '중국 헤이티 카페에서 유명하다는 포도치즈폼🍇이 먹고 싶어서 찾아옴. 한국 메뉴명 이름은 ''클라우드 크리스프 그레이프'' 인가봐요. 엄청 맛있진 않지만  쬐금 들어가있는 치즈폼이 맛있습니다', 39, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '오디 맛 진하게 담겨진 멀버리 붐 ♥ 깔끔한 달콤함!! 홍대 헤이티는 젊은 외국사람들이 진짜 많네요! 역시 젊음의거리인가요!! 캬캬', 26, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '중국 밀크티 매장. 직원분도 중국인이신데 친절하고 한국말 잘 하세요. 여기 1+1 할인도 해서 사람 진짜 많아요. 매장에 취식할 만한 공간은 낮은 테이블과 앉은뱅이 의자뿐. 심지어 입구를 활짝 열어놓아 시원하지는 않아요ㅠ 그래도 음료도 맛있고 가성비 좋아 사람들이 붐비는 곳. 홍대 메인거리에 생긴 새로운 음료맛집 말차 종류 좋아한다면 추천합니다', 37, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), 'ㅋㅋㅋ카운터 안쪽에서 주방 썩은내 나서 놀램 ㅠㅋ 직원 한분만 더듬더듬 한국어하는정도..나머지는 못하시는듯.. 음료는 맛있었는데 먹고싶은 것도 품절이었고 너무 어수선하고 악취때문에 해당지점 재방문 의사는 없습니다.', 93, 26, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '홍대 핫플이라 해서 들렸어요. 음료 가격 한 잔에 7400원이라 깜짝 놀랐네요 ㅋ 호기심에 들려봤는데 테이크아웃 중심 가게라 좌석은 몇개 안 됩니다.', 12, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '사고펄이 기본으로 들어있는 줄 모르고 블랙펄 추가함 블랙펄은 진짜 쫀득하고 남다른데 사고 느끼해 하는 편이라 많이 못먹어서 아쉬웠음 그리고 비쌈 직원들이 중국인이라 그런건지 바빠서 그런건지 메뉴판도 직원도 설명이 부족한 느낌', 69, 15, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '음료 한잔에 6900원인데 맛이 별로에요 중국 놀러갔을때 먹었던 헤이티 생각하면 안됩니다 그냥 홍대 놀러가서 중국에서 먹었던 추억생각하면서 한번쯤은 먹어볼만합니다. 사람은 무지 많아요', 14, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '인생 밀크티 랭킹 1위 바꿨습니다. 진짜 너무 맛있었구요, 집 앞이었으면 맨날 시켜먹고 싶을 맛이었습니다. 대신 좌석이 많지 않아서 테이크아웃에 가까운 매장이라 아쉽고, 사실 저당으로 마시려고 브라운 슈가 밀크티 취소하고 다른 거 시켰는데 실제 주문은 처음 말씀드렸던 걸로 그대로 갔더라구요. 영수증 받고도 확인 안 한 내 잘 못 이지만..^*^ 열분도 영수증 잘 확인하십셔. 직원분들이 다 중국인들이라 의사소통 잘 신경쓰셔야 할 겁니다.', 19, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '중국에서 들어온 밀크티 브랜드, 헤이티. 농밀한 녹차의 식감이 좋았습니다. 다만, 가격대가 조금 높고 내부에 마시는 공간이 좁은 게 아쉽네요. 🍵', 79, 13, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '여기 망고가 유명해서 망고 음료 두잔시켰는데 영수증을 보니 한잔이 코코넛 블루로 들어가서 바로 주문 취소하고 싶다했더니 안된다고 해서 진짜 너무 화났습니다. 어떻게 한국인데 한국인 직원을 안쓰고 외국인을 쓰시나요.. 망고랑 블루 발음을 구별 못하는데 다시는 안감 안에 매장청결도 그렇고 걍 실망 역시 중티', 498, 47, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '여기 일부러 인터넷 보고 찾아왔는데 진짜 퀄리티 끝내주고 친절하고 조아용 웨이팅 필수입니다 꼭 참고부탁드립니다 직원분 다 고생 많으심 재방문 의사 만땅 천프로 찍습니다 ㅎㅎ 무조건이요', 66, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '텀블러에 음료 요청하니까.. 가격은 500원 할인된거 같은데 대신 주문서 스티커 떼는 번거로움을 주심.🥲 그치만 맛있었으니까~ 텀블러에 담는거 비추여. 다 얼어서 음료가 잘 안 나왕ㅜㅜ 그냥 #喜茶 #heytea 에서 제공하는 컵에 드시길..🙏 자세한 리뷰는 블로그 참조. https://m.blog.naver.com/green_kim_2117/223881565043', 72, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '음료랑 교환하려고 교환권 내밀면 보통 음료랑 교환해서 가져가거나 쓰레기통에 버려달라고 말할텐데 여기는 안내없이 멀뚱멀뚱 쳐다보기만 해요... 음료도 맹물에 얼린망고 부순거 넣은맛이에요 맛이 이상해요', 46, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '여긴 종업원들이 다 중국인이라 한국어를 잘 못해요. 그래서 설명이 이해가 잘 안 돼서 음료에 기본으로 펄이 있는지 모르고 또 추가해버렸네요. 굳이 이렇게 해야되는 이유가 뭔지…. 음료는 맛있어요. 특히 코코넛 망고 붐 추천합니다!(당도70)', 50, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '또 헤이티. 배불러도 땡기는 맛, 날 더워져서 웨이팅 길어질까 걱정. 오늘도 코코넛망고붐. 제로로 주문했더니 맛이 덜하다. 오십퍼센트 당도로 빡 달게 먹어야 존맛', 68, 16, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '요새 sns에서 세상핫한 헤이티🙌🏻 노멀한 브라운슈가 밀크(카페인x) 골랏는데 펄이 진짜 맛있엇어요😋 사람많으니 어플로 미리 주문하고 가길 추천!', 41, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '시그니처 밀크티를 먹었어요 공차랑 비교 하자면 차 맛이 조금 얇아요 버블은 먹을만하구요 치즈 폼이 짭짤 해서 단 짠 느낌이 강해요', 23, 5, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '상해다녀온 후 헤이티가 아른거려 바로 찾아갔어요. 근데 뭔가 상해랑 맛이 조금 다른지 엄청 맛있다는 느낌은 아니었어요 🥲 그치만 맛없진 않고 맛있긴해요..!', 32, 2, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '여긴 영수증 하나도 뭐가 이리 정성스럽지? 싶어서 놀랐음 자스민라떼 시켰는데 향이 너무 좋았고 묵직함 보다는 가벼운 라떼로 느껴져서 오히려 자스민 향이 더 잘 느껴져서 좋았음 참고) 주문하고 생각해보니 진동벨도 없고 부르지도 않길래 저세히 보니 주문하는곳 위 전광판?에 주문번호 뜸.', 12, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '셋이 근방에서 저녁먹고 배 부르지만 이 맛을 못잊어서 저절로 발걸음...난 또 코코넛망고붐.ㅋㅋㅋ  지인 들은 코코넛그레이프푸릇붐? 인가 하고 다른거 주문했음. 배가 부른 상태에서 맛있으면 정말 맛있는 거라고 했던가... 정말 맛있어서 1일 1 헤이티 해야 한다고...', 35, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '오늘도 코코넛망고붐. 다소 늣은 저녁식사로 급하게 소고기 과식하고 배 부르다고 생각하며 조금 망설이며 헤이티로 향했다. 지금 부른 배에는 가까운 라이즈 지점 블루보틀의 산미 있는 커피가 더 괜찮지 않을까 잠깐 생각하다가 시간이 늣었으니 커피 보다는 헤이티가..하는 생각.  코코넛망고붐 맛을 떠올리니 이미 입안에  군침이., .ㅋㅋ  역시는 역시다. 잠깐 사이에 반 넘게 흡입.  날씨 추워지니 그 길던 주문줄, 대기줄 짧아져서 나는 더 좋다. 잘 먹었습니다.', 44, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '리얼 우유와 리얼차로 만든 헤이티 많이 달지도 않고 먹을수록 중독적이네😍 로스티드브라운보보밀크티 는 달달하면서 펄이 진짜 쫀득하고 입안에서 사르르 녹아요. 타피오카펄이 잊지 못할맛❤️ 망고레드자몽사고는 부드러우면서 밀키하고 상큼해요. 자몽이 톡톡터지는 느낌이 좋고 망고향이 솔솔 맛있어요😍👍 사고펄도 부드럽게 쫀득해서 레베루가 다르네요. 손님이 너무 많아서 웨이팅 해야 하는것만 빼면 매일 가고 싶네요🥤전체적으로 강하지 않는 부드러운 맛!', 24, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '맛있는 헤이티 재방문 ಇ 시그니처 메뉴로 주문했는데 모두 맛있었어요! 기본 밀크티랑 망고 사고? 메뉴 마셨는데 굿 👍🏻 또 마시고 싶네용 ,, 체인점 많이 생기길 … 🥺', 3, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '오늘의 픽은 스트로베리붐🥤🍓 시원한 딸기슬러쉬 맛.. 🤭 개인적으로는 망고코코넛이 제일 맛있어요 날이 더워지면 더 자주 찾게 될 것 같아요', 53, 15, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '진짜 한국에서 장사할꺼면 한국말 할줄아는 직원두세요. 친구가 앞에서 쩔쩔매길래 뭔상황인가 하고 가니깐 다 영어 메뉴에 한국말도 어눌한 사람이 응대하고있네…', 41, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '중국에서 유명한 차 음료 체인점이라길래 방문했어요! 기대가 컸던만큼 실망도 컸습니다.. 가게 내부 작고 테이블 갯수도 적어서 거의 테이크아웃 위주입니다 코코넛 망고 붐..망고 너무 적어서 맛도 안나요 동남아의 코코넛+망고 조합을 생각한다면 절대 시키지마세요 자스민 라떼는 괜찮았으나 호불호가 갈리긴 할 것 같네요 상하이 자주 가는 지인한테 헤이티 왜이렇게 맛없냐하니까 중국 현지에서 판매하는 베스트 메뉴는 한국에 없다고하네요ㅠ 나중에 중국 방문하게되면 먹어야겠어요', 41, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '싱가폴에서 그레이프를 너무 맛있게 먹었어서 기대하고 먹었는데, 맛있지만 기대만큼은 아니었습니다 ㅠㅠ 망고레드자몽은 너무 맛있었네요 👍', 25, 0, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '헤이티는 처음인데 이거 완전 대박.. 액상과당을 안 마시는 편이라 코코워터말차 시켰는데 코코넛의 그 비린맛?은 전혀 없고 오히려 풍미가 더 좋았어요! 위에 폼이 진짜 ㄹㅈㄷ 맛도리구요 또 사먹을거에요!!', 35, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '쌤이랑 저녁식사로 얼큰한 등촌샤브샤브 먹고 내려오는 길에 오늘도 엑시 참새방앗간 들른 헤이티...난 또 코코넛망고붐. 쌤은 클라우드그린티로...  난 다른 맛을 한번도 못 먹어봄.ㅋㅋㅋ   아이고 오늘도 너무너무 맛있다. 역시...', 17, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '#협찬 버블티 헤이티 홍대점에서 말차 밀크티를 주문했어요. 달콤씁슬한 말차맛과 쫀득한 타피오카가 조화롭게 어우러져 맛이 좋았어요. 전체적으로 만족스러운 경험이었고 다음에 또 방문할 의향이 있습니다! 매장은 깔끔하고 직원들도 친절해서 주문 과정이 원활했어요. 주말엔 사람이 많아요.', 6, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '또 헤이티... 주말 점심,  끝내주는 파스타  배불리 먹고 후식으로 헤이티... 나는 자동으로 코코넛망고붐. 그리고 쌤은 로스티드브라운슈가밀크티. ㅋㅋ 우리 둘은 매번 다른거 궁금하다며 막상 줄 서면 자동으로 이거  두가지..  날이 추워지니 길게 서던 줄이 없어 오히려 반가움. 오늘도 앞에 한팀. 바로받아 매장에 앉아 올리브영에서 구매한 제품들 포장 벗기면서 반쯤 마시다 나옴.  마지막 한입까지 건더기가 같이 딸려나오는 헤이티의 푸짐함과 넉넉함..역시는 역시다. 대 만 족.', 20, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '자스민티 맛이 뚜렷함!!! 이거 모르면 음료가 왜 향긋하지? 이럴 수 있음(내 친구 얘기) 당도 기본인데 그렇게 많이 달지않아서 좋음. 컵이 튼튼하고 좋음. 디저트39랑 다름 헤이티는 중국브랜드임.', 6, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '음료는 맛있는데 주문 받는 직원분이 한국말이 서투셔서 의사소통이 원활하지는 않았습니다 그리고 매장 내에 작은 테이블 2~3개 있는데 빈 테이블 위에 음료인지 뭔지 흥건하게 물기가 있었고, 쓰레기도 올려져 있었는데 전혀 치워지지 않은 상태였습니다…', 33, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '홍대점이 헤이티 압구정점에 비해서 너무 맛없어요.. 압구정에서 먹는 레드 자몽 사고는 재료가 풍부해서 항상 맛있게 먹는데 홍대점은 두 번이나 트라이 해봤지만 재료가 너무 부실해요.. 많이 아끼시는듯..  몇 입 먹으면 밍밍해서 못 먹겠네요 ㅠㅠ 왜 이렇게 다른건가요 외국인 관광객들 엄청 많던데..  그래서 그런건가요 가격대도 꽤 있는 편인데 ㅠㅠ', 5, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '보보밀크티 맛있어요. 전체적으로 음료 자체가 부드럽네요. 펄은 갸인적으로는 공차를 좋아하는데 공차기준보다 더 삶는것 같아요. 좀더 말랑거리는 식감이라고 보시면 됩니다.', 116, 19, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '오늘도 헤이티...주말 점심으로 칠리크랩이랑 태국음식 맛있게 먹고 배가 너무 불러 일부러 멀리 주차해 두고 걸어서 다녀 옴... 그런데 큰컵 사들고 걸어 오면서 다 먹고... 부른 배 두드리고 있넹. 오늘도 나는 역시 코코넛망고붐을, 옆에서는 크리스프그레이프치즈붐... 역시 내꺼가 내입엔 더 맛있다. 호캉스 왔으니 낼 첵아웃 후에 또 먹어야쥐.', 21, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '배가 터지기 직전까지 저녁 먹어놓고 슬금슬금 또 여기로..ㅋㅋ  사람이 어찌나 많은지 멀리서 보고는 무슨 일 났는 줄... 나는 또 코코넛망고붐...옆에 애는 지난번 얌베리 맛있었다고 주문 했는데 솔드아웃으로 까여서 스트로베리 치즈붐 주문.. 한입 뺏어먹어보니 내꺼가 훨씬 맛있음...입맛은 다 다른거니까.  아이고오...  대기 중에 모기 백이십만번 뜯김. 그래도 기다린 보람 있어 너무 맛있음.  결국 배 터짐.ㅋ', 86, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '얼마나 맛있으면 사람들이 바글바글!!??? 넘 궁금해서 다녀왔어요!! 공차랑 똑같겠지 했는데 ㅋㅋㅋ오마이갓 😝 차를 우린거라 거기에 과일이 들어가니까 상큼 향긋한 맛이 참 상콤하더라구요!?!?! 얼음중간 당도중간 기본값으로 드세요!!!', 10, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '드디어 홍대에도 헤이티가 생겼네요! 기대보다 더 맛있어요. 대기가 긴 데, 생각보다 음료는 금방 나옵니다~ 다음에 홍대 들르면 또 올 것 같아요🩷', 23, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '또 갔음. 그냥 지나칠수 없음. 불금 저녁으로 참치머리해체쇼를 만끽하고 실컷먹어 느끼한 입을 달래러 감. 나는 또 코코넛망고붐, 상대는 배부르다고 퓨어그린티...   역시 내꺼 압승. 너무 맛있고요...  마무리 완성. 담엔 메뉴 공부좀 해서 다른거 도전해 봐야쥐.', 30, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '저녁 약속 연남동 태국식당에서 배뻥 먹고 들름. 난 오늘도 코코넛망고붐. 그대는 얌베리치즈폼... 내 최애 망고붐 먹다가 한입 뺏어먹어보니 상대적으로 더 새콤하고 덜달고 밍밍하게 까지 느껴졌으나 잘근잘근 씹히는 자극적은 얌베리 과육이 계속 생각나더라는...  역시 헤이티.', 30, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '새벽에 보던 유튜브에서 이꼬르영이 상하이 가서 1일 1헤이티 하게 해 달라던 영상 보면서 침 질질 흘리다가 홍대에서 같이 점심먹은 지인 꼬셔서 달려간 곳.  압구정 1호점 이어 홍대에 생기다니...진입문턱이 낮아져서 너무 신난다. 대기시간 5분..주말 점심 치곤 아직 몰리지 않아 더 좋다. 그래도 메뉴가 많고 대부분 외국인이라 메뉴판 사진만으로 구분이 잘 안가서 주문할때 시간이 좀 걸리는 편이지만 역시 외국인인 담당 카운터분이 더듬더듬 한국말로도 메뉴설명을 시원시원하게 잘해줘서 뒤에 줄서 있으면서도 캐치될정도로 잘 들려서 바로 주문할수 있었다.  코코넛 망고 붐, 로스티드 브라운슈가 보보... 둘이 주문한 두가지 모두 맛있어서 다음엔 다른거 시도해 보고싶다.', 46, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '홍대 저녁약속 후 홀린 듯이 들른 곳... 나는 역시 또 코코넛망고붐 주문...상대는 로스티드브라운슈가 어쩌구 주문한다더니 주문직전 치즈그린티로 변경.  줄은 앞에 두팀밖에 없었으나 진상 만남...메뉴 종류많고 토핑등 작은차이로 비슷비슷한 애들이 많은데 손톱만한 사진 보고 고르면서 하나하나 질문하고 주문했다 변경하고...짜증났다.  겨우 가라앉히고 주문하니 대기시간 8분 뜸. 자리 나서 편하게 대기... 생각보다 금방 나옴. 코코넛망고붐은 역시 실망없는 확실하게 꽉찬 맛. 가볍고 시원한 음료 기대하는 사람은 피해가야 하는 맛. 설빙 빙수먹는듯 다양한 재료들로 하나가득 채워서 빨아올릴때마다  계속 다른맛과 식감이 느껴지는 잼있는 맛. 치즈그린티는 자스민티향이 강하고 공차보다 살짝 쳐지는 풍미. 나랑 안맞음.', 64, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '1. 보보 밀크티 - 적당히 달달한 현지 밀크티(대만과 비슷해요..!) 2. 코코넛 망고 볼 - 코코넛 펄 과 사고 펄 그리고 망고 과육과 코코넛 밀크가 잘 어울리는 맛이에요! 게다가 많이 많이 달지 않아서 물리지 않는 맛이에요:) 3. 퓨어 그린티- 정직한 자스민 녹차 맛입니다! 저는 차를 좋아해서 맛있게 먹었지만 일행분들은 좀 쓰다고 했어요😂', 36, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '오늘만큼은 다른 과일티 먹어보려고 생각하면서 줄섰는데..,또 이거...코코넛망고붐.  이건 왜 이렇게 맛있는 것일까.  1일 1 헤이티 하게 해 주세요.', 37, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '헤이티라는 브랜드가 중국에서 인기많다고 해서 이번게회에 홍대역 헤이티 먹어봤습니다! 일단 포도슬러시랑 생과일 포도가 밑에 들어가는데 맛은 생각보다 괜찮았습니다. 근데 6900원이라는 가격대로 보기에는 조금 비싸다는 느낌이 조금있네요! 그리고 매장 사장님이 정말 친절하십니다~~!👍', 4, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '또갔음. 홍대 약속있으면 여기부터 떠오르니...어쩔수가 없음. 심지어 메인 식사에 집중이 안됨. 얼른밥먹고 헤이티 갈 생각에..ㅋㅋ 바로 앞에서 시식 나눠주는 청년이 알아보구 인사해 주심.ㅋㅋㅋ   다른거 먹어본다구 하고서는 막상 차려오면 코코넛망고붐. 자동발사...ㅋㅋ  오늘도 잘 먹었습니다.', 65, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '중국에서 맛있게 먹었던 헤이티인데 한국에서 보니 넘 반갑네요! 브라운슈가밀크티 넘 맛있어용🧋🧋 홍대버블티 맛집으로 추천합니다!', 11, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '헤이티가 생겻네요 반가운 맘에 바로 들어갓어요 ㅎ 대기공간만 잇는 테이크아웃점 같아요 가격은 중국현지에 비한다면 말도 안되게 비싸지만 맛잇습니다!!!!😚😋', 31, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '여기는 올때마다 캐셔분들이 소통이 잘안됩니다.. 그리고 점바점인지 압구정점이랑 맛차이가 있었어요 그래도 차를 마실수있다는 점에서는 좋아서 자주 방문해요', 0, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '사람들이 엄청 줄 서있어 이끌리듯 기다리고 대표 음료중 하나 망고 코코넛? 먹었는데 달지 않고 맛있네요 다음에 다른 음료도 맛보고 싶네요', 118, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '맛있음.. 여행 유튜브에서 여러번 보기만 하다가 가까운 홍대에 생겨서 달려간 곳. 경험해 본 것만해도 설레였는데 막상 먹어보니 이건...완죤 내취향.  찐한 퓨레스타일  망고쥬스에 밍고사고랑 코코넛알갱이가 한가득. 끝까지 맛있게 먹었다. 자주 올거 같다.', 0, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '신촌에 일보러 갔다가 헤이티 오픈소식 듣고 일부러 방문했어요. 역시나 헤이티는 최고예요~~ 특히나 코코넛 망고 붐은 최애입니다~♡♡', 17, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '맛있어요.상해에서 먹었을때랑 비슷해요. 자주갈것같아요 그레이프붐은 진짜 건강한맛.주문,픽업시 친절하고  주문객도많지만 직원분들도 엄청많아요.', 12, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '상하이 인기 카페 헤이티 홍대에 오픈! 7월29일-31일 까지 한잔 구매시 한잔 무료이벤트 진행하고 있습니다. 직원 추천으로 망고 레드자몽 사고 마셨는데 아주 맛있어요.', 10, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '중국브랜드인가요?? 줄이 길어 호기심에 가봤는데 손님도 일하시는분들도 모두 중국분:) 음료가 독특했는데 달달하니 맛났어요!!! 근데 저당하시는 분들은 스킵하셔야 할 듯:) 줄서면서 친절한 중국분이 시그니처 메뉴랑 알려주심😀', 0, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '상하이 여행가서 먹어봤던 헤이티가 한국에 상륙했대서 가보았어요! 메뉴 가짓수는 현지보다 훨씬 적어보였고 가격도 훨씬 비싸서 놀랐지만 ㅠ 흑당과 치즈폼의 조화가 좋고 차 베이스도 향긋하며 부드러워 맛있어요', 124, 22, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '중국에서 먹었던 헤이티 기대하고 한국에 들어오기만을 기대했던 사람인데 진짜 얼마나 케이패치된건지 같은구석을 찾아볼수가없네요 치즈폼은 묽고 냉동과육쓰고 사이즈도 중국 반만하고 사먹을 가치가 하나도 없어요 이럴거면 왜 헤이티 이름 달고 들어온건지 한국에서는 다시는 안사먹을듯', 32, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '타지사람인데 매장이용 후 홍대를 떴는데 결제가 두번 된 걸 알고 전화했더니 직접 방문해달라고하심. 이미 다른곳으로 가버려서 못간다고 했더니 다시확인하고 전화준다고 하시고 다시전화와서는 남자매니저가 카드들고 와야한다고 또 얘기함. 단한번도 죄송하다는 소리조차 하지않고 두번이나 카드 들고 와야한다고만해서 못간다고 했더니 그제야 원격으로 해주겠다고 하고 취소해줌. 자기들이 실수해놓고 죄송하단 소리도 한번도 안하고 전화끊어버림. 바쁜건 알겠는데 너무 불친절해요', 65, 14, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '매장안에 테이블 없음. 무조건 포장(테이크아웃) 원플원행사때 먹었는데, 그냥 사먹으려고 하면 비싼편 같다. 진짜 과일과육을 사용하는게 맛있다', 46, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '오픈 이벤트로 그레이프, 코코넛망고, 우롱티를 모두 마셔봤는데 심하게 달지 않아서 좋았는데 비싸서 언제 또 먹을지는 모르겠네요. 🤣', 120, 24, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = 'HEYTEA 홍대점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '喝了好多次 奶盖系列的奶盖越来越少 今天根本就只有薄薄一层 为了省钱多做几杯也不能这样吧 요즘 밀크폼 시리즈는 밀크폼이 점점 줄어드는 것 같아요. 오늘 건 진짜 얇게 한 층만 있었어요. 아무리 아껴서 몇 잔 더 만든다고 해도 이렇게 하면 안 되죠.', 70, 11, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '인테리어와 공간이 주는 분위기가 특별합니다. 절제된 느낌이 작업에 집중을 할 수 있도록 도움을 줍니다. 주문한 음식이 서빙되는 방식 또한 흥미로워서 다른 곳에서 느껴보지 못한 커피와 분위기를 느끼고 싶다면 충분히 방문할 가치가 있는 곳입니다.', 61, 17, 'GOOD', SYSTIMESTAMP);
