INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '작업하기 좋은 곳을 찾아다니다가 알게된 커피 맛집이에요. 드립커피 종류도 다양하고 잔도 예뻐요! 레일로 전달되는 방식도 독특해서 기억에 남을 것 같은 카페예요☺️', 14, 8, 'GOOD', SYSTIMESTAMP);
