INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '남편 회사 근처 카페 따라갔는데 너무 특이하고 맛있어요! 디저트도 맛있고 커피도 맛있고 특히 음악이 좋네요! 집에서 가까우면 자주 오고 싶어요 :)', 7, 10, 'GOOD', SYSTIMESTAMP);
