INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '여기 진짜 강추!!!!!!!!!!!!!!!!!!!!!!!!! 서빙 진짜 독특하고 합정에 조용하게 대화할 수 있는 카페 찾으시면 무조건 여기! 컴파일 ! !', 5, 4, 'GOOD', SYSTIMESTAMP);
