INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '제가 정말 아끼는 공간이에요. 언제 오든, 몇 번을 오든 늘 좋습니다. 같은 자리에서 변하지 않는 한결같음을 느낄 수 있는 곳이에요.', 40, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '노트북 작업하고 싶어서 카페를 찾아다녔는데 2인석도 두명이 노트북을 펴도 부담없는 사이즈고 테이블 간격도 다닥다닥하지 않아서 좋았어요!', 13, 5, 'GOOD', SYSTIMESTAMP);
