INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '완전 자동화 되어있어서 좋네여~ 그래도 원두는 직접 로스팅한 원두로 핸드드립으로 내려주셨는데 커피 너무 맛있어요 개인적으로 코코넛향을 너무 좋아하는데 피칸치즈케잌이랑 너무 잘어울려서 깜놀~ 딸기향나는 원두 조만간 먹으러 가보려고요~ 너무 맛있게먹어서 단골로 찜했어여 조만간 또 가려고ㅗ요~ 감사합니다', 28, 6, 'GOOD', SYSTIMESTAMP);
