INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '핸드드립커피 전문점이어서 와봤습니다. 일단 전체적인 컨셉이 독특해서 마음에 들었고 커피도 자체의 향이를 잘 나태내는 맛이어서 좋았습니다. 인테리어중에 컨베이어벨트가 특히 신기했습니다🫢', 86, 15, 'GOOD', SYSTIMESTAMP);
