INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '예전부터 가보고 싶은 카페 찜콩해두었습니다. 드디어 방문했는데 역시나 제 픽은 완벽하네요 ㅋㅋ 너무 좋은 시간이었어요~ 트렌디한 컨셉과 인테리어, 조용한 분위기, 맛있는 커피를 레일로 내어주는 센스와 맛있는 디저트!!  그냥 다 좋네요. 음악도 좋구요!! 사장님도 넘나 친절하게 설명해주시는 부분 좋네요~ 잔도 너무 예쁘고 디저트와 커피의 페어링도 좋아요!! 조용하고 고요한 분위기 너무 좋아요!! 반하고 갑니다!', 89, 15, 'GOOD', SYSTIMESTAMP);
