INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '공장같은 인테리어에 개인이 쓸 수 있는 공간이 정말 잘되있습니다! 자리마다 1구 코드도 있어서 작업하기 좋아용. 커피를 레일로 주셔서 오로지 집중할 수 있는 공간..', 86, 14, 'GOOD', SYSTIMESTAMP);
