INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '드립커피 전문점 아니면 잘 안먹게 되는데 여기 드립 잘하네요! 라떼 잘한다고해서 궁금해요. 다음에 또 오려구요. 집중이 너무 잘 되서 생각치도 못하게 너무 오래 있었어서 직원들께 죄송할 정도네요.', 24, 8, 'GOOD', SYSTIMESTAMP);
