INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '내 방앗간 1호 콤파일. 특히 꼬소한 향미가 있는 커피가 맛있다. +) 매장에서 나는 향이 정말 좋아서 갈때마다 기분이 너무 좋아진다 🩶', 35, 0, NULL, SYSTIMESTAMP);
