INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '커피는 맛있습니다! 다만 키크신 남자 직원분이 좀 친절하셨으면 좋았을텐데 아쉽네요.. 살짝 불쾌해서 앞으로는 방문 하지 않을것 같아요. 그래도 인테리어가 신기하고 예쁜 카페입니다.', 7, 2, 'BAD', SYSTIMESTAMP);
