INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '합정과 홍대 사이에 있는 카페 콤파일 방문했습니다. 컨셉도 독특하고, 세련미 넘치는 인테리어가 넘 맘에 들어요♥️ 드립커피, 플랫, 피칸버터바 주문해서 맛봤는데 커피는 향이 넘 좋고요!! 커피와 잘 어울리는 버터바 증말 맛나게 먹었어요👍🏻👍🏻 분위기 좋은 콤파일 추천입니다🥰', 60, 14, 'GOOD', SYSTIMESTAMP);
