INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '커피가 정망 맛있더라구요! 레일로 배달해줘서 귀여움...✨ 공부하시는 분들이 많아서 조용한 곳인데 커피 좋아하시는 분들 추천합니당🤍', 29, 1, 'GOOD', SYSTIMESTAMP);
