INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '노트북 하기 좋은 카페라고 들어 방문했습니다. 자리마다 콘센트가 구비되어 있어서 편했어요. 곳곳에 개발자 컨셉으로 꾸며진 게 보여 재미있었습니다.', 56, 11, 'GOOD', SYSTIMESTAMP);
