INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '항상 노트북해야할 때 찾게되는 것 같아요 평일엔 혼자 방문해도 4인 테이블석 착석이 가능하다고 하셨어요 여기서 디저트는 처음 먹어봤는데 디저트도 무난하니 괜찮았어요 다만 가격이 있어서 오래 머무를 게 아니라면 음료만 시키는 걸 추천드려요 테이블마다 콘센트 꽂을 수 있어서 좋아요', 25, 3, NULL, SYSTIMESTAMP);
