INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '드립커피 개맛도리😋 친구끼리 아님 혼자서 사색하기도 좋은 합정카페 드립 맛나다고 해서 요즘 폼 도랏다는 라 노리아 첫 도전 버터바랑 같이 먹어도 달달함이 장난 아니라 깜짝 ୧ʕ•̀ᴥ•́ʔ୨ 드립 좋아하시면 에콰도르 라 노리아 꼭 마셔봐야 됨 버터바도 꾸덕한 게 야르 종류 6가지나 있음 ㄷ ㄷ', 29, 6, 'GOOD', SYSTIMESTAMP);
