INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '홍대와 합정사이 작업하기 최적의 장소예요. 내부는 두 개의 컨베이어 벨트를 중심으로 테이블이 배치되어 있는데, 주문한 커피가 컨베이어 벨트를 통해 테이블로 전달되는 방식이 재미있답니다. 이 움직이는 요소가 정적인 공간에 동적인 활기를 더해주어  경험을 선사해요 고요한 분위기속 잔잔히 흘러나오는 음악까지, 집중하기 더할나위없이 좋습니다', 50, 3, 'GOOD', SYSTIMESTAMP);
