INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '커피맛에 집중할 수 있는 조용한 분위기, 커피잔 커피 맛을 해치지않는 선에서 페어링하는 디저트 버터케잌까지 즐길 수 있는 공간이어서 너무 좋았어요', 16, 1, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '작업하기엔 좋은데 직원 서비스가 아쉬웠습니다 ~ 친구가 한시간 반 먼저 도착했고, 저는 늦게 도착했는데대기인원 발생하면 2시간 이용 제한 있더라구요,, 저는 카페 들어간지 40분만에 이용시간 끝났다고해서 나왔어요~이용시간을 친구 주문 시간 기준으로 하시더라구요..  전 커피도 다 못마셨는데 나가라고 해서 그냥 나왔네요 😅  이용하는데 기분은 별로 안좋아서 앞으로는 안갈것같아요 ~ 커피는 맛있었습니다~~! + <첫 주문>을 기준으로 이용시간 제한된다고 하여 당연히 <저의 첫 주문시간>으로 이해했습니다. 처음부터 <일행 분 주문시간기준> 이라고 설명을 안해주셨습니다. 그 기준이면 굳이 제가 30분 앉아있을거 결제 안했을텐데요. 기준을 명확히 해주셔야할것같아요~ 저 또한 커피를 결제했는데 저에대한 형평성은 없네요', 120, 21, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '정말 감각적인 카페에요 시끄럽지도 않고 조용한 편이고 비지엠도 조용해서 더 좋았어요 인테리어도 재밌고 신기하고 모던합니다 드립커피를 좋아하는데 종류가 다양하고요 기존 버터바랑은 또 다른 느낌이네요 특이하고 밋있네요 또 갈 것 같아용 ◡̈', 32, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '홍대주변에 핫한 카페들은 이미 사람 많고 대화도 불가능이라 좀 합정쪽에 있는 곳으로 갔는데 분위기에 반하고 옴 커피를 특이하게 레일로 전달해주는 곳인데, 컨셉에만 너무 집중해서 맛을 걱정했지만 디저트와 커피까지 아주 충실한 곳이었음 커피는 내가 원하는 취향의 원두를 고를수 있었고, 디저트는 기본적으로 버터바인데 종류가 다양하고 특이한 메뉴가 있어서 고르기 어려웠음 ㅋㅋ 버터바는 적당한 달달함에 음료랑 찰떡인데 먹다보면 하나 더 먹고싶은데 하는 맛이 들었음 카페 분위기는 조용하고 대화가 적당히 오가는 분위기라 작업하시는 분들도 은근 있었고 컨셉 포인트들이 귀여운 부분이 많아 은근 즐거웠음', 12, 7, 'GOOD', SYSTIMESTAMP);
