INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '컨셉이 진심이여요 드립커피가 진짜 맛집 디저트도 넘 맛있었습니다 각 자리마다 콘센트가 있어 작업하기 좋아요 주말 저녁-밤시간대에 갔는데 사람이 많았어요 혼자 오기도 좋을 것 같아요', 35, 3, 'GOOD', SYSTIMESTAMP);
