INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '카페 콤파일입니다. 홍대 뒤편에 위치한 조용한 카페고요. 대부분이 작업하거나 공부하는 분들입니다. 수다 떨거나 얘기하러 온 분들은 거의 없습니다. 음료도 레일로 배달되는 식의 독특한 컨셉이라 신기했고요. 카페 내부는 되게 어두워요. 음료는 시그니처보다 라떼가 더 맛있어요.', 38, 8, NULL, SYSTIMESTAMP);
