INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '아조씨 홍대입구 탐방,,, 분위기,,, 콘셉트,,, 확실한 장소 방문,,, 좋은 점: 레일을 타고 오는 음료와 디저트,,, 직원분들의 복장,,, 메뉴 모니터,,, 음악,, 전체적인 인테리어,,, 컨셉에 진심인 곳입니다,,, 경험,,, 한번 해볼만 합니다,,, 레일이 생각보다 느리고 소소해서,,, 오히려 재밌었읍니다,,, 아쉬운 점: 감성이 가득 담긴 대신,,, 음료 가격이 거의 두배입니다,,, 커피 외 음료는 양도,,, 아쉽읍니다,,, 경험 한번 하는 목적이면 좋지만,,, 음료를 음미하는 느낌으로는,,, 두잔은 마셔줘야 합니다,,, 행복은,,, 어디에나 있는 것,,,^^', 47, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '커피맛이 예술이에요! 분위기가 좋아보여 친구들과 온건대 진챠 맛있어요 산미있는걸 좋아해서 에티오피아 한잔먹고 반해서 추가로 추천받아 한잔 더 마셨는데 커피인데 블랑마시는듯한? 향과맛이나는 커피는 처음인데 너무 제스타일이었던 ㅎㅎ 디저트도 달달하니 너무 맛있었어요 집근처면 또가고싶어여❤️', 72, 17, 'GOOD', SYSTIMESTAMP);
