INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '조용한 분위기, 친절한 직원의 설명이 인상깊은 곳이었습니다. 컨베이어 벨트로 커피를 내주는 건 신박했습니다 ㅎㅎ 혼카페 작업러들에게 추천드려요!', 25, 6, 'GOOD', SYSTIMESTAMP);
