INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '산미 있는 드립은 잘 안 먹는 편이라 롱블랙을 주문했어요. 롱블랙은 다른 음료에 비해 양이 적긴 해서 이 부분 참고해 주문해야 해요! 버터바 중 덜 단 것 추천해 달라 말씀드렸더니 친절하게 알려 주셨고 너어무 맛있었습니다. 자리마다 콘센트 있고 조용히 작업하기 딱이었어요. 건물 화장실인 점 빼곤 맘에 들었습니다!', 32, 4, 'GOOD', SYSTIMESTAMP);
