INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '일하기는 좋으나 너무 춥습니다. 별도 시스템없이 난로 2개에 의존하는 것으로 보였는데, 기름이 떨어져서 한개는 가동이 안되더라고요. 분명 커피도 맛있고 트레일로 가져다주는 시스템도 충분히 흥미로웠는데, 정상적으로 커피를 즐길 수가 없었습니다. 날씨가 따뜻해지면 다시 갈 의향은 있지만 그때까지는..!', 11, 4, 'BAD', SYSTIMESTAMP);
