INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '솔직히 레일 위로 다가오는 커피 영상 찍으러 왔어요. 사실 겨울엔 우풍이 불어서 추워요. 그리고 제한시간 두 시간이라 컴퓨터 작업하고 가기엔 시간이 조큼 부족하긴 했음..', 34, 10, NULL, SYSTIMESTAMP);
