INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '굉장히 독특한 컨셉의 카페네요. 분위기도 좋고 커피도 수준급입니다. 조용한 느낌의 카페라서 수다 떨기에는 적합해 보이지 않습니다. 멋진카페 입니다.', 48, 9, 'GOOD', SYSTIMESTAMP);
