INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '재방문의사: 🌕🌕🌕🌕 노트북으로 작업하실 분들은 여기 방문하시면 정말 만족하실 것 같아요 평일에 방문했는데도 작업하시는 분들이 많아서 빈자리는 거의 없었고 커피 주문 시 처음 방문했다고하면 세세하게 커피에 대해서 설명해주시는 데 커피에 대한 진심을 느낄 수 있었습니다. 노트북 작업하기에 각 자리마다 콘센트가 있기 때문에 너무 좋은 곳이고 커피며 디저트며 맛있었습니다. 메뉴 이름이 기억나진않지만 첨부 사진에 있는 바나나치즈케이크가 정말 맛있었습니다', 17, 10, 'GOOD', SYSTIMESTAMP);
