INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '굉장히 친절하시고 좋았어요 커피도 괜찮았습니다 다음에 또 가보고싶어요 커피가 레일을 타고 이동하는것도 신기했어요 근데 두 잔 이상부터 레일 타나봐요 ㅎㅎ 신기방기', 51, 16, 'GOOD', SYSTIMESTAMP);
