INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '독서실 같은 분위기에 카공족들 집합소! 카페가 조용해서 정말 좋았습니다! 수다 떨기보다는 비즈니스하거나 개인 작업, 공부하기 좋은 카페!! 드립커피도 맛있고, 시그니처 크림라떼 달달하네용ㅋㅋㄱ', 57, 15, 'GOOD', SYSTIMESTAMP);
