INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '또또또간집입니다 ㄹㅇ 작업하기에 이만한데가 없어서 자주 방문하게 되네요. 자리 싸움이 치열한 카페들이 보통 많은데... 여기는 좌석이 다 똑같고 콘센트도 좌석마다 있고 넓직해서 항상 걱정없이 방문해요! 주말에는 만석시 2시간 시간제한 있었는데 평일엔 없네용 더 유명해지지마 제발.... 아니 유명해져.. 아니 유명해지지마', 6, 8, 'GOOD', SYSTIMESTAMP);
