INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '시그니처커피 넘 맛있어요~~^^ 딸기청 또는 시럽이 전혀 안 들어갓는데 딸기맛이 나다니 넘 신기해~~^^ 디저트도 넘 맛있어용~~^~^', 65, 18, 'GOOD', SYSTIMESTAMP);
