INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '역간 어둑한 분위기에 완전 작업하기 좋다고 생각하고 있었는데 메뉴 시킨게 레일 따라서 조명으로 오는데 넘 신기하고 기획력 짱이라고 생각했습니당! 색다른 느낌이고 커피도 맛있을 것 같아요><!', 16, 7, 'GOOD', SYSTIMESTAMP);
