INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '버터바 생각나서 재방문했어요🥺 당충전 제대로 하고싶어서 초코크런치 시켰는데 꾸덕하고 달달하니 역시 존맛탱이었습니당..... 주기적으로 먹어줘야함ㅠㅠ 갈때마다 항상 친절하게 맞아주셔서 좋아요❤️', 9, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '분위기 괜찮은 카페입니다. 인기가 많아서 대기도 금방금방 생기더라고요. 원두 친절히 설명해주셨는데, 다음번엔 드립커피 한 번 먀셔보러 가야겠습니다', 4, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '분위기도 너무 좋고 커피 향이나 디저트 맛까지ㅠㅠ 정말 다 만족스러운 곳이였습니다!! 자리마다 콘센트도 한 두 개씩 다 준비되어있어 노트북 작업하기에도 완벽하고, 그냥 커피나 디저트 즐기러 가기에도 완벽한 곳이였어요ㅎㅎ 강추하는 합정 카페입니다!!~👍', 93, 24, 'GOOD', SYSTIMESTAMP);
