INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '아 계속 찾고 싶은 곳❣️평일 한 낮에도웨이팅이 있는 이유를 와보니까 알겠어요🌚 공간과 음악 무엇보다 커피 맛에 취저당한 1인 후기 완료', 26, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '주변에 카페많던데 웨이팅 잇던곳은 여기뿐ㄷㄷ.. 커피전문점답게 원두종류도 다양하고 핸드드립,에소프레소커피 골라서 마실수있어요. 직원분도 참 상냥하시고 잘 뽑으신거 같아요.', 17, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '핸드드립이 넘나 맛있고 컴퓨터 작업하기 좋은 카페에요 거의 혼자오는 손님이 많았어요 디저트까지 jmt라서 놀래고 갑니다 ㅎㅎㅎㅎ 레일에서 서빙되는거도 재밌네요 ㅋㅋㅋㅋ 담에 또 올게요 😆', 11, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '서교동에서 제가 제일 사랑하는 공간이에요 적립 개수 세어봤는데 오늘까지 47번째 방문이더라고요 사장님이 워낙 좋으셔서 그런가 직원분들도 전부 친절하고, 저는 와서 주로 작업만 하다 가지만 너무나 제 취향인 인테리어 그리고 음악 덕분에 늘 휴식같아요 커피 맛있어요 싱글은 훌륭하고 기본 원두 두가지도 너무 괜찮아서 기분 따라 매일 번갈아 마십니다 메뉴도 그렇고 모든 곳에 신경 많이 쓰신 티가 나서 더 좋아하게 된 것 같아요 리뷰 잘 안쓰는데 응원 겸 기록 남겨봅니다 매장에 대기 생기면 역시 사람들 안목이 있구나 싶으면서도 자리가 없어서 속상해요 콤파일 유명해지지마..하지만 번창하길….', 21, 6, 'GOOD', SYSTIMESTAMP);
