INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '보통 노트북 쓰기 좋은 카페는 이렇게 트렌디하게 예쁘진 않은데, 여긴 인테리어도 너무 좋고 커피가 배달되는 시스템도 편하고 디저트도 너ㅓ무 맛있어요!!', 9, 7, 'GOOD', SYSTIMESTAMP);
