INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '사진으로 봤을 때는 아주 조용한 공간인 줄 알았는데 아니에요. 너무 조용하지 않아 작업하기에도, 이야기 나누기에도 좋아요! 주문한 메뉴가 레일을 따라 나오는 것이 독특해요. 주말에는 2시간 제한이 있지만 커피도 맛있고, 디저트도 맛있어서 합정에서 오기 좋은 카페에요 ☺️', 282, 98, 'GOOD', SYSTIMESTAMP);
