INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '메뉴 주문하면 컨베이어 벨트로 전달받아요. 컨셉이 독특합니다! 다만 작업하기 좋은 카페라고 해서 찾아갔는데 의자가 딱딱해서 오래있을 순 없었어요! 2시간 정도 노트북하긴 좋습니다. 커피맛도 독특하고 디저트 메뉴 맛있었습니다!', 13, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '주문 받으시는 여자 직원분이 너무 친절하셨어요. 이것저것 더 필요한거 없는지 꼼꼼하게 체크도 해주시고 감동😍 커피 원두도 다양하고 직접 핸드드립으로 내려주시는거 같더라고요. 저는 카페인 없는 차로 마셨는데 터메릭티 찾기 쉽지않은데 여긴 있어서 좋았어요. 버터바 종류도 많아서 다음에 가서 다른것들도 먹어보고 싶습니다. 그리고 자리에 앉아있으면 특이하게 컨베이어 벨트로 자리까지 오더라고요. 특별한 재미도 있어서 좋았어요. 재방문 의사 있어요🫶🏻🫶🏻🫶🏻🫶🏻', 34, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '아늑하고 어두워서 집중해서 작업하거나 책 읽기 좋은 곳인데다가 커피가 맛있어요. 요즘 카푸치노 있는 곳이 별로 없는데 카푸치노 메뉴가 있어서 반가웠어요! 바나나브륄레도 적당히 꾸덕하고 맛있습니당 가사 없는 잔잔한 음악이 나오고, 레일로 자리까지 음료가 서빙되는 것, 자리마다 콘센트가 구비된 것, 영수증으로 각각 안내되는 정보들, 친절한 직원분들까지 전체적으로 섬세한 공간이라는 느낌을 받았습니당 그리고 킨토 머그 손잡이가 잡았을때 손가락이 받쳐져서 들기가 아주 편하더라고요..이런 작은 디테일 감동스러워요.. 아무래도 단골 될 것 같아요☘️', 68, 13, 'GOOD', SYSTIMESTAMP);
