INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '컨셉이 독특해사 방문했는데 커피도 원두 캐릭터를 잘 표현해주셔서 너무 좋았습니다(향이 매우 달았음!! 갓 구운 군고구마향이 느껴지면서 베리향의 달달함도 같이 올라옴 마시면 허니하다는 표현이 적당할거같음 그러면서 쌉쌉할 맛이 안정적으로 잡아줘서 밸런스거 참 좋았습니다) 디저트도 밸런스가 잘 잡혀있고 커피와의 조합도 참 좋았습니다', 73, 18, 'GOOD', SYSTIMESTAMP);
