INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '홍대 노트북 카페 검색하면 뜨던 곳!! 홍대보다는 합정에 더 가깝고 아늑하고 조용한 분위기 만족스러웠습니당ㅎㅎ조명이 어두운 편이라 카공하기엔 적합하지 않은 것 같고 테이블마다 콘센트 있어서 노트북 작업하기에 좋아요!!', 6, 1, 'GOOD', SYSTIMESTAMP);
