INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '너무 추운 날 보이는 카페 들어왔더니 핫플이었어요.. 후기를 안 찾아보고 갔어서 메뉴 등장할 때 친구랑 띠용ㅋㅋㅋ 핸드드립 커피가 유명하고 특이한 차들을 팔아서 선택지가 다양해요. 인테리어는 감성 핫플 그 자체.. 먹었던 디카페인 핸드드립은 쓴맛이 덜하고 부드럽던데 다른 원두랑 디저트 먹어보러갈 예정입니다~~', 37, 2, 'GOOD', SYSTIMESTAMP);
