INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '블랙무드 인테리어 커피가맛있는 콤파일 방문했어여 이색적이고 드립커피로 정성이가득한 커피한잔 아무기대안한 디저트 달지않고 존맛탱구리 자주 방문할듯요 번창하세요', 70, 11, 'GOOD', SYSTIMESTAMP);
