INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '버터바도 맛있는데 커피가 진짜진짜 맛있어요 홍대 합정 망원 일대에서 탑인 것 같음 ㅜㅜ 그리고 작업하기 좋은 환경이라는 것도 한몫합니다 제발 없어지지 말길 ㅜㅜ', 41, 10, 'GOOD', SYSTIMESTAMP);
