INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '메뉴가 트레일러로 움직여서 오는게 신기해요 매장 내 향이 좋고 산미있는 라떼 맛있어요! 분위기 좋고 음악도 잘 어울려요 대화하기도 좋고 작업하기도 좋아요 책을 읽기에는 어두운 편이에요 담에 커피 마시러 올것 같아요', 18, 5, 'GOOD', SYSTIMESTAMP);
