INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '약속시간까지 시간이 비어서 혼자 쉴곳을 찾아보다가 방문했다. 원두의 향미가 명확한곳은 너무 오랜만이라서 기분이 좋다. 조용한 분위기도 좋고 음악까지 완벽하다. 도시속에서 숨은 보석같은 카페를 찾았다.', 104, 19, 'GOOD', SYSTIMESTAMP);
