INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '너무 멋진공간 잘왔다가요~! 분위기도 좋고 맛도좋고 특히 디저트 버터바중에 프랄린피칸 진짜 강추,, 필터커피는 말할것도 없이 좋구요 ㅎㅎ다음에 꼭 또 올꺼에요 꼬옥~', 86, 14, 'GOOD', SYSTIMESTAMP);
