INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '아날로그와 디지털 사이에 있는 컴퓨터 레일에 깔려나오는 음료들 첨단과 최첨단 사이의 공간은 커피의 맛으로 채울 수 있다. 버터브릭은 비록 먹어보지 못했지만 충분히 맛있었으리라 생각한다.', 34, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '친구의 추천으로 처음 방문했는데 분위기가 너무 좋고 다양한 종류의 드립커피를 음미해볼 수 있다는 게 좋았어요! 커피가 레일로 전달되어 나와 편안하면서 대화의 흐름을 깨지 않았다는 점도 좋았구요💭', 36, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '버터리 라떼 선택했습니다. 깔끔한 스타일의 라떼였어요. 개인적으론 더 진한 걸 좋아해서 다음에는 핸드드립으로 마셔보려고 합니다.', 6, 4, NULL, SYSTIMESTAMP);
