INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '홍대 노트북 하기 좋은 카페 콤파일 !! 처음 가봤는데 분위기 너무 좋고 차분한데 노트북 하기에 좋은 분위기라 작업 하러 가기에 너무 좋아요. 추천한 핸드드립 커피도 마셔봤는데 진짜 신기한 향에 맛까지 좋았어요! 💙 집 가까이에 있다면 자주 방문했을 것 같은 카페🫶🏻', 124, 19, 'GOOD', SYSTIMESTAMP);
