INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '커피가 우선 훌륭합니다. 핸드드립을 좋아하는 사람에겐 굿~ 근데 여기 음악도 너무 멋져요. 뭔가 집중하게 만드는…근데 네이버는 왜 음악들려줘도 뭔지 모르는 건데? … 암튼 말로만 듣던 버터바도 호기심에 먹어봤는데 맛있군요~ 조금만 덜 달면 더 좋겠다는..ㅎㅎ 암튼 커피 좋아요~', 273, 54, 'GOOD', SYSTIMESTAMP);
