INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '지나가다우연히발견한너무매력적인카페예요. 끌리듯이들여다보다,스르륵문을열고들어왔는데,공간에매료되어한참을서성이다,맛있는음료에눈이휘둥그레해졌어요.공간,분위기,음악모두최상입니다:D', 47, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '컨베이어 벨트에 커피가 스르르륵 내 자리까지 도착 어둡고 노래가 크지만 오히려 이 느낌이 더 몰입하게 만든다 !! 그리고 직원분께서 계속 뭔가 청소하고 계셔서 깔끔하다.. 무균..인거같고 .. 겨율날 아늑한 이 감성 추천', 29, 5, 'GOOD', SYSTIMESTAMP);
