INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '언젠가 한번쯤 와보고 싶어 즐겨찾기 해놨었는데 우연한 기회로 방문하게 되었습니다. 깔끔한 인테리어, 어둑한 분위기, 공간과 어울리는 음악, 커피까지 너무 좋았어요 !! 다음에 또 방문하고 싶습니다 ♡︎', 59, 16, 'GOOD', SYSTIMESTAMP);
