INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '콤파일 두번째 방문이에요! 매장에서 좋은 향기가 나고, 커피가 너무 맛있어요 :D 컨베이어 벨트에 커피 보내주시는 것도 색다르고 좋아요. 적당히 조용해서 대화 나누기에도 작업하기도 좋은 서교동 최애 카페에요!', 2, 7, 'GOOD', SYSTIMESTAMP);
