INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '컨셉이 독특해서 구경하는 재미가 있어요. 컨베이어벨트로 커피 나오는게 재미있어요. 어두운 조명인 편이지만 집중하기 좋고 대화 나누기도 좋아요! 커피 매일 마시는 사람인데 커피맛도 좋다고 느낀거 오랜만이에요. 좋습니당ㅎㅎ', 75, 11, 'GOOD', SYSTIMESTAMP);
