INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '깔끔하고 군더더기 없는 실내와 차분한 BGM 덕분에 커피맛을 음미하고, 이야기나누기에 좋아요🌿 작업에 몰두하기에도 좋을 것 같아 혼자 다시 방문하려고요. 컨베이어 벨트가 있어 주문하고 다시 가질러가지 않아도 되서인지 북적임도 덜한 것 같아요.🫶🏻', 27, 9, 'GOOD', SYSTIMESTAMP);
