INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '콤파일은 항상 음료랑 디져트를 정갈하게 놔줘서 넘 좋아요 음악이 흐르는 이분위기도 넘 좋고 유니크해요 ㅎㅎ 집이 멀어서 자주는 못오지만 합정에 오면 꼭 드르는 곳이랍니당👍🏻♥️', 25, 7, 'GOOD', SYSTIMESTAMP);
