INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '근처에서 볼 일이 있어서 잠시 시간이 남아 들렸는데 너무 만족 스럽네요 차분한 분위기에 커피도 엄청 맛 있어요 작업을 하거나 글을 쓰거나 책을 읽을 때 와도 엄청 좋을거 같아요 오늘은 다음 일정 때문에 오래 못있었지만 다음에 기회가 된다면 와서 작업하거나 독서를 하고싶은 분위기 입니다 !', 0, 1, 'GOOD', SYSTIMESTAMP);
