INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '차분하고 어둑한 분위기의 힙한 카페에요. 커피가 옆에 벨트로 슝 배송되니까 놓치지않고 구경하세요! 다양한 커피메뉴가 있어서 고르는 맛이 있었고 컨셉에 맞춰서 다양한 소품들을 구경할 수 있어서 좋았어요💾💞', 8, 10, 'GOOD', SYSTIMESTAMP);
