INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '차분한 공간입니다 종종 생각나서 작업하러 들러요 고구마 버터바랑 쑥차 맛있었어요 특이한 인테리어도 분위기도 그저 컨셉이 아니라 이유가 담겨있는 것 같아 너무 좋습니다', 5, 6, 'GOOD', SYSTIMESTAMP);
