INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '분위기 너무 좋고 음악도 제 취향이라 자주옵니다ㅜㅜ 인센스스틱 향도 너무 좋아요!! 무엇보다 커피 너무 맛있고 테이크 아웃하면 할인도 됩니다~ 쿠폰도 찍어줘서 이득이에요 ㅎㅎ 디저트는 오늘 처음 먹어봤는데 진짜진짜 맛있더라구요..? 오늘 데리고 온 친구는 자기가 올해 먹은 디저트 중에 손에 꼽는다구 하네요!! 자주올게요 ㅎㅎ', 46, 6, 'GOOD', SYSTIMESTAMP);
