INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '독특한 디자인에 반하고, 맛있는 커피에 한 번 더 반했네요 ! 매니저님도 직원분도 친절해서 기분 좋았어요 ! 원두도 샀는데, 설명도 잘해주셨습니다 ^^', 111, 20, 'GOOD', SYSTIMESTAMP);
