INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '와이니 베리 원두로 아이스아메리카노 시켰는데 원두 설명이 딱 알맞게 떨어지는 향기가 나는 커피에요 정말로 시나몬, 베리 향이 나는 뱅쇼같은 커피라서 맛있게 잘 마셨어요 :-) 향긋한 커피 좋아하시면 맛있게 즐기실 수 있을 것 같아요!', 36, 10, 'GOOD', SYSTIMESTAMP);
