INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '카페 분위기도 좋고, 처음 왔는데 메뉴 설명도 정말 친절하셨어요! 커피도 드립 커피 주문했는데 잔도 예쁘고 맛도 좋았습니다:):) 버터 블록은 바나나브륄레강추 ㅠㅠ 합정 근처에서 조용한데 얘기 나누면서 맛있는 커피랑 디저트 찾으시는 분들께 추천추천!!', 37, 5, 'GOOD', SYSTIMESTAMP);
