INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '커피가 맛있습니다! 저는 와이니베리 마셨는데 너무 맛있어요!!! 공간도 아주 좋아요!!! 조용하지만 도란도란 이야기하기도 좋고 책 읽거나 작업하기도 좋습니다!! 독특하게 컨베이어 벨트타고 음료가 온답니다~~', 115, 24, 'GOOD', SYSTIMESTAMP);
