INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '컴파일이라는 카페 이름처럼 메뉴판이 코딩 화면처럼 디자인되어 있어 신기했어요! 다양한 핸드드립 원두가 있어 기호에 맞게 선택할 수 있었는데 저는 복숭아와 산딸기를 골랐습니다. 커알못이라 설명대로의 과일 향을 느끼진 못했지만 평소 산미 있는 커피를 잘 못 마시는데 이건 담백하고 깔끔하게 잘 넘어가더라구요! 그리고 컨베이어벨트에 커피와 디저트가 자리까지 배달되어 오는데 재미있는 경험이었어요! 꼭 바나나 브륄레 버터바를 곁들이길 추천합니당 커피랑 정말 잘 어울리는 디저트였어요', 74, 14, 'GOOD', SYSTIMESTAMP);
