INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '인스타에서 보고 독특해서 찾아왔어요! 밖에서 봤을때 너무 어두워서 영업 안하는줄 알았는데 들어오니까 아늑하고 깔끔해서 좋았어요 버터바도 너무 맛있고 차를 시키니까 주전자와 찻잔이 나오는게 너무 좋았어요☺️', 29, 10, 'GOOD', SYSTIMESTAMP);
