INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '처음 와봤는데 컨셉과 분위기가 맘에 들었어요. 작업학는데 집중하기 너무 좋고 매장에서 나오는 배경음악도 분위기와 집중하는데 좋았습니다. 시그니쳐 커피는 과하지 않게 달달하면서 맛있고 핸드드립 디카페인은 콜롬비아 원두인데 깔끔한 맛이 너무 좋았습니다. 담에 또 기회가 되면 오고 싶은 매장이네요 :)', 89, 15, 'GOOD', SYSTIMESTAMP);
