INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '라떼 안좋아해서 기대반 호기심반으로 시그니처 먹어봤는데 왜 시그니처 인지 알거같아요 한입 먹자마자 감탄 컨베이어로 갖다주는것도 아이디어 넘치고 힙해요 직원분들도 매우친절쓰', 29, 3, NULL, SYSTIMESTAMP);
