INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '인테리어가 깔끔하고 특색있어서 너무 좋아요~! 컨셉 진한 카페 좋아해서 완전 취향! 테이블마다 콘센트 있고 테이블도 넓어서 작업하기 좋아요. 서빙이 진짜 신식입니다. 신기해서 멋져요👍🏻 카공 열심히 하다가 갈게요. 멋진 공간 감사합니다🩶', 53, 14, 'GOOD', SYSTIMESTAMP);
