INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '블랙감성 취저까페예요^^ 원두도 선택할 수 있고 kinto 컵에 컨베이어 벨트로 나오는 재밌는 시스템이예요^^디저트도 초코크런치로 먹었는데 케이크 보다 맛있더라구요 합정에 담택(일본라멘)집 갔다가 들리면 딱 좋아요^^', 71, 13, 'GOOD', SYSTIMESTAMP);
