INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '음악도 좋고 커피맛이 아주 좋아요 특히 친구가 먹은 와이니베리 원두는 특이하고 너무 맛있네요! 레일로 서빙되서 신기방기 컨셉에 맞게 메뉴판부터 인테리어 하나하나 좋아요 업무도 할수있고 디저트 먹으면서 수다떨기 좋아요', 49, 1, 'GOOD', SYSTIMESTAMP);
