INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '커피가 너무 맛있다고 하여 지인 추천으로 왔습니다! 지금 기다리고 있는 중인데 레일로 커피를 보내주시는 것 같아요 ㅎㅎ 분위기가 좋습니다. 메뉴판이 c 언어 처음 배웠을 때를 생각나게 하네요 ㅋㅋ 다음 번에 개발자 동기들 데리고 와야겠어요 와 커피에서 포도쥬스 향이 나요 진짜 맛있어요!! 딸기쨈? 들어간 코코넛 버터바도 제 취향입니다.', 44, 7, 'GOOD', SYSTIMESTAMP);
