INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '우연히 지나다 들어온 카페인데 굉장히 신비롭습니다 사장님이 힙하신데 커피에 진심인듯합니다  진지하게 커피를 만드시는 모습에 전문가의 느낌이 나네요 커피 종류가 여러가지라 선택해서 마실 수 있어요 처음 마셔보는 커피맛도 있었는데 굉장히 독특하고 맛있었어요 처음 매장에 들어오면 커피향보다는 뭔가 이국적인 향이 먼저 나요 음악도 몽환적인게 독특해서 좋았어요 카페 인테리어가 깔끔하고 넓어서 시원시원합니다 커피도 맛있는데 분위기도 좋아서 매우 만족', 23, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '블로그 글보고 열심히 찾아왔는데 조명이 은은해서 카페인 줄 모르고 지나칠 뻔 했네요 들어와보니 분위기가 압도적입니다. 음악, 조명, 인테리어 조화가 완벽하고 커피 맛도 엄청나네요. 이 주변을 그렇게 어슬렁 거렸는데 왜 이제서야 알았지 싶을 정도로 훌륭한 카페입니다.', 90, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '차 향이 너무 좋아요! 그리고 분위기도 독특해서 집중이 잘 될 것 같아요! 노트북 작업하러 왔다가 만족하고 갑니다~담에 또올게요!', 14, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '홍대 근처 작업하기 좋은 카페 검색해서 찾아 왔습니다. 테이블 사이에 놓인 컨베이어 벨트? 레일로 주문한 음료, 디저트를 전달해주십니다. 카페입구 유리문에 쓰여진 코드처럼 컨셉이 확실해서 인스타그램용 카페아닐까 생각했는데 원두 종류 다양하고 테이스팅 노트 상세하게 써 있어서 커피알못이지만 커피에도 진심인 것 같다는 인상을 받았습니다. 그리고 차분한 음악과 공간의 울림이 뭔가 사유하는 경험을 제공하는 전시 공간 안에 있는 것 같다는 느낌이 들었어요. 가만히 커피만 마셔도 멋진 뭔가를 하는 것 같은 경험을 제공해주는 신기한 카페. 테이블마다 콘센트있어서 작업하기도 물론 좋습니다. 아 저는 산딸기 코코넛 버터바?블록을 먹었는데 양도 많고(의외임) 진짜 진짜 맛있습니다. 추천해요.', 41, 8, 'GOOD', SYSTIMESTAMP);
