INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '노트에 적힌 그대로 느껴지는 커피 정말 오랜만에 마셔보는데 넘 맛있고 좋아요🫶 매장도 넓고 레일타고 메뉴 나오는것도 재밌어용ㅎ 직원분들도 친절하시구우 버터블럭 진짜진짜 맛됴리 진공청소기처럼 마셨어요 짱짱짱', 58, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '분위기 최고 카페. 카페 들어서자마자 조용하고 잔잔한 분위기에 첫인상이 너무 좋았어요. 시그니처 커피랑 라떼, 바나나 브륄레 먹었는데 셋다 너무 강추합니다 시그니처 커피 크림 달달하니 커피 쓴 맛 싫어하시는 분들도 잘 먹을 수 있고 라떼는 진짜 진해요 다크한 원두 골랐는데 산미없고 묵직한 라떼!! 완전 성공 바나나 브륄레도 빵? 쿠키?랑 바나나가 잘 어울려서 다음에 무조건 한번 더 올 예정입니다 그리고 컨베이어벨트로 보내주시는게 너무 신기함ㅎㅎㅎㅎ 처음 왔다고 하니 직원분께서 친절하게 다 설명해주셔서 메뉴도 다 성공한거같아요 들어갈 때부터 나올 때까지 계속 기분 좋았던 시간이었어요 완전 강추합니당', 17, 6, 'GOOD', SYSTIMESTAMP);
