INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '처음에 너무 어두워서 카페 못찾을 뻔 했어요..! 그런데 분위기 너무 좋고 이색적이에요~! 커피도 저렇게 자리로 가져다 줍니다ㅎㅎ 커피 맛은 잘 모르겠는데 약과 디져트는 맛있었어욤~~ 카페 직원분들도 너무 친절하시고 좋았습니다👍🏻', 37, 7, 'GOOD', SYSTIMESTAMP);
