INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '컨셉이 확실한 카페! 너무 좋아요 개발 공부하는 사람인데 반가운 마음에 와봤어요 편하게 작업하고 갑니다~~ 커피 짱 맛있어요.ᐟ.ᐟ 쑥차도 대박임', 7, 8, 'GOOD', SYSTIMESTAMP);
