INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '특이한 느낌의 카페, 음악 소리에 사람들의 대화소리가 잔잔하게 소음으로 변해서 좋음 버터바는 너무 꾸덕하지도 않고 적당해서 맛났음 핸드드립, 라떼, 아메리카노 등을 팜', 5, 7, 'GOOD', SYSTIMESTAMP);
