INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '커피는 무난하고 맛있어요! 무엇보다 매장 분위기가 독특하고 구경하는 재미가 있었습니다ㅎ.ㅎ 조명이 은은하고 잔잔한 노래 덕분에 집중하거나, 가벼운 수다떨기 좋은 것 같아요. 다음에 또 와서 차 종류도 먹어보고 싶어용', 2, 5, 'GOOD', SYSTIMESTAMP);
