INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '주말에 작업하기 좋은 카페 찾던 중에 발견했어요! 음료나 디저트에는 별 기대 없었는데, 세상에 너어무 맛있어요! 커피는 세상 꼬숩고 바나나 브륄레는 브레드가 속이 꽉찼어요 꼭 작업이 아니더라도 커피랑 디저트 먹으러 재방문 할것같아요', 89, 15, 'GOOD', SYSTIMESTAMP);
