INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '근처에 있다가 필터 커피를 마시고 싶어서 검색해서 찾았어요. 문을 열면 인센스 스틱 향이 나는데 굉장히 편안했어요. 카페 컨셉도 좋고, 컨베이어 벨트에 커피를 보내주시는 데 신기했답니다. 전체적으로 조용해서 집중하기 좋은 분위기 인 것 같아요.', 91, 20, 'GOOD', SYSTIMESTAMP);
