INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '유튜브에서 보고 커피 맛있다길래 왔는데 정말 너무 맛있었어요! 브루잉 커피도 맛있고 아메리카노도 베리 향미 뿜뿜이라 라떼도 진짜 맛있을 것 같았습니다! 재방문 의사 110%!!!', 55, 12, 'GOOD', SYSTIMESTAMP);
