INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '첫방문이라 시그니처로 주문했어요! 딸기청이나 딸기 시럽이 안들어갔는데도 딸기 맛이 나는 커피라니 다마시고 너무 놀랐습니다..! 이렇게 맛있는데 어떻게 커피만으로 구현해낸거지 ?!?! 잘 저어 마시란것도 다 마시고 알았네요 😅 공간에서 주는 울림이 있는것 같아요 잘은 모르겠지만 음향도 한몫 하는것 같아요 😻 동네 주민으로서 합겨억  💯', 47, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '카카오에 시나몬향이 은은하게 나서 맛있어요 ㅎㅎ 디저트도 진짜 맛있고 운남백차도 향긋하니 좋아요! 인테리어도 신기해서 또 오고싶어용ㅎㅎ', 28, 2, 'GOOD', SYSTIMESTAMP);
