INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '잔잔한 음악과 오롯이 나에게 집중할 수 있는 시간, 친구와의 대화도 차분하게 나눌 수 있었어요. 레트로감성이 곳곳에 녹아있고 현대적 모던하고 깔끔한 인테리어 너무 마음이 들었습니다:) 레일영상 패션쇼처럼 촬영해봤어요 ㅋㅋ 자주 올 것 같아요', 31, 1, 'GOOD', SYSTIMESTAMP);
