INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '처음 와 봤는데, 마음을 편안하게 해주는 향과 분위기가 너무 좋네요. 맛있는 커피와 디저트는 물론이고 메뉴가 컨베이어 벨트로 이동하는 장면도 신선해요!!', 45, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '✔️매장 매장이 넓어서 좋았어요! 제가 갔을 땐 사람도 많지 않아서 대화하기에 좋았고 어둡고 차분한 분위기의 매장이였어요 ✔️커피&디저트 전 커피를 안 마시는데 동생은 커피 너무 잘한다며 두 잔이나 마셨어요! 제가 마신 바나나밀크(?) 도 꾸덕하니 맛이 너무 잘 느껴져서 좋았구 버터바는 크림브륄레 진짜 존맛도리였어욥 그리고 주문한 오더가 나올 때 컨베이어벨트(?) 같은 곳에 나오는데 특이해서 좋았어요! ✔️서비스 친절하셨어요! 버터바가 다 맛있어보여서 좀 오래 고민하고 이것저것 물어봤는데 대답 다 해주시고 기다려주셔서 감사했어요! 잘 있댜 갔습니댜!', 73, 16, 'GOOD', SYSTIMESTAMP);
