INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '절제되고 미니멀한 분위기 속에서 느껴지는 편안한 분위기가 매력적인 공간이에요. 또 컴파일이라는 가게 이름과 함께 테이블 번호는 디스크에, 서빙은 컨베이어 벨트로, 화장실 비번은 컴퓨터언어로 구성된 일관된 컨셉이 집중력을 끌어올리는 곳이에요. 그리고 자칫 삭막해 보일 수 있는 벽의 일부를 창문으로 노출시켜서 햇빛과 나무 인테리어가 잘 어울리는 장소에요. 커피는 말 할 것도 없고요.', 268, 75, 'GOOD', SYSTIMESTAMP);
