INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '분위기 너무 좋고 커피 진짜 맛있어요 커피 나올때부터 고소한 향 퍼지고 향만큼 맛있어요! 디저트도 진짜,, 맛있고,, 합정 카페로 추천해요오💕', 10, 6, 'GOOD', SYSTIMESTAMP);
