INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '회사 근처 라떼 맛집이라 종종 오는데 디저트도 정말 맛있습니다. 프랄린피칸 버터블럭을 먹었는데 가운데는 꾸덕하고 토핑은 바삭하니 식감이 좋고 커피랑 너무 잘어울려요! 분위기도 독특하고 좋아서  굉장히 만족하는 곳입니다!', 44, 4, 'GOOD', SYSTIMESTAMP);
