INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '음악도그렇고 음료가 나오는 방식이나 쿠폰이나 설명서에 써진 글씨체까지 콤파일이라는 이름에 맞는 컨셉이에요. 시그니처 음료에 딸기가 안들어갔는데 딸기비스킷 맛이 나는게 너무 신기해요! 커피도 맛있고 버터바도 아주 맛있습니다 ㅎㅎ 디테일적인 부분까지 컨셉에 신경 쓴 곳이라 강추합니다!', 0, 2, 'GOOD', SYSTIMESTAMP);
