INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '피칸버터바 맛있어요!! 커피 잘 안마시는데 시그니처 커피 맛있습니당 추천 음료 나올때 컨베이어벨트로 나오는데 특색있고 재밌네요', 37, 10, 'GOOD', SYSTIMESTAMP);
