INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '레일로 서빙해주는 독특한 카페입니다. 은은한 조명도 좋고 무엇보다 원두  종류가 많아 핸드드립 원두를 고르는 재미가  쏠쏠합니다', 0, 4, 'GOOD', SYSTIMESTAMP);
