INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '인스타그램에 카페를 전문적으로 리뷰하는 친구에게 커피맛있는곳으로 가고싶다라고 얘기하니 ''콤파일''을 추천해줘서 같이 오게됐는데요 1. 커피 : 맛있음 (2잔 시켜먹음, 아메리카노•핸드드립) 2. 디저트 : 맛있음 (바나나브륄레) 3. 분위기 : 매우좋음(뭘하더라도 눈치안볼수 있는 분위기) 4. 총평 : 첫방문이었는데 서교동에 오면 또 방문하고 싶다.', 81, 16, 'GOOD', SYSTIMESTAMP);
