INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '정말 의외의 장소에서 발견한 보물 같은 곳 입니다. 핸드드립 커피도 정말 훌륭하고, 가게의 분위기와 컨셉, 음향도 더할 나위 없습니다.', 49, 9, 'GOOD', SYSTIMESTAMP);
