INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '인테리어가 너무 멋있고, 조도가 낮아서 집중이 잘 돼요 공간이 너무 좋아서 큰 기대는 없었는데, 커피도 너무 맛있어요! 또 오고 싶어요', 19, 5, 'GOOD', SYSTIMESTAMP);
