INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '드립 커피를 선호 하는 편이 아닌데도 여기 드립 커피가 너무 맛있어요! 다음에와도 드립커피 시키려구요!! 지난번 방문때는 자리가 없어서 이용을 못 했는데 오늘은 자리가 널널해서 좋았어요 매장이 어두운 편이라 책을 읽기에는 좀 어려운 듯 하지만 노트북 작업을 하거나 친구와 대화하기엔 좋아요 직원분이 친절히 메뉴 설명도 해주셔서 더 좋았습니당!', 21, 7, 'GOOD', SYSTIMESTAMP);
