INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '디저트도 맛있고 음료도 맛있습니다. 커피도 다양한 원두가 준비되어 있어 좋습니다. 카페 분위기도 미니멀하면서도 독특해서 데이크 하기 좋습니다. 테이블마다 콘센트도 있어서 작업할게 있을때 와도 좋을것 같습니다', 89, 14, 'GOOD', SYSTIMESTAMP);
