INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '드립커피 찐맛집 !! 커피 좋아해서 맛있다는 커피집은 다 다니는데 여긴 인생의 드립커피 맛집이예요 완전 베스트1순위인 곳! 너무너무 맛있어요 커피 마시고 힐링하고 갑니당ㅎㅎ', 41, 3, 'GOOD', SYSTIMESTAMP);
