INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '커피가 너무 맛있어요 ... ☕❤ 다음에 또 방문하고 싶은 카페입니다. 인테리어도 멋져요! 멍 때리고 작업하기 좋은 공간입니다.', 20, 10, 'GOOD', SYSTIMESTAMP);
