INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '너무 마음에 드는 곳이에요! 콘셉트가 뚜렷한데 그게 튀는 게 아니라 편안하게 다가오고요. 컨베이어 벨트로 음료가 운반될 때마다 환기가 되고, 일상 속 작은 즐거움이 됩니다. 주말엔 손님이 많아 다소 소음이 있지만 그래도 전반적인 음향과 분위기 덕에 혼자 고요한 시간 보내기 좋구요~ 아메리카노도 원두가 좋아서 넘 맛있어요 ㅎ 친절하고 공간 속에서 편안하게 있게끔 배려가 느껴집니다.평일에 꼭 재방문 해보고 싶구요. 그때는 디저트도 꼭 먹어보렵니다!', 6, 3, 'GOOD', SYSTIMESTAMP);
