INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '회사에서 평일에 종종 오는 곳인데 토요일에 들려봅니다. 사람 정말 많아서 놀랐어요 ㅎㅎ 바나나 브륄레 정말 맛있어요 강추! 👍❤️', 61, 18, 'GOOD', SYSTIMESTAMP);
