INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '들어오자마자 특이한 카페 분위기며 깔끔한 인테리어도 맘에 들고 음료도 깔끔해서 너무 좋았습니다 시끄럽지도 않고 해서 자주 방문 할 것 같습니다!', 59, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '혼자 작업하고 책읽기 좋은 카페에요. 매장 내 조명이 어두워서 몰입하기 좋고, 향이나 음악도 아늑한 무드입니다. 이솝 매장같은 느낌 좋아하는 분이라면 좋아할만한 카페에요', 15, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '이유는 알 수 없지만 여기서 작업을 하면 잘 될것 같은 기분이 듭니다. 음악도 편안하고, 인테리어도 진짜 감각적이에요! 그리고 음료가 컨베이어 벨트로 전달되는데, 이게 진짜 기해요!! 꼭 와봐야만 합니다', 58, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '조용하고 깔끔한 카페 매장도 넓어서 답답한 느낌이 없어요. 시그니처 커피 먹는데 사장님이 진짜 원하시는 맛이나서 신기했어요! 매장 안쪽인 레일 시작하는 부분에 앉았는데 기계소리가 조금 거슬리는 거 말곤 괜찮았어요 이어폰이나 헤드셋 안쓰실 분은 바깥쪽에 안는 걸 추천드려요', 57, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '집에서 1분 거리에 이런 멋진 카페가 있다는 걸 이제서야 알았네요. 혼자서도 함께도 시간 보내기 좋은 곳이에요. 낮은 조도와 정갈한 무드가 아름다워요. 무엇보다 인테리어와 직원분들 메뉴와 오브제 곳곳에 맥락 있는 연결이 느껴져 감탄했습니다. 또 카페의 기본인 커피와 음료도 맛있었어요.', 22, 2, 'GOOD', SYSTIMESTAMP);
