INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '이 동네에 들렀다면 놓치면 안될 가게 지나가다 멋진 분위기에 이끌려 들어온 가게 메뉴판부터 너무 힙하고 예뻐서 눈길을 사로잡았고 컨베이어 벨트로 나오는 커피도 신선하다 인테리어와 컨셉은 물론 커피랑 히비스커스 티도 맛있음! 추천합니다', 79, 16, 'GOOD', SYSTIMESTAMP);
