INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '매장이 어두워서 좋아요 노트북으로 작업하기 좋은 곳이에요! 음악도 너무 좋아서 에어팟 한 번도 안 끼고 작업했어요 직원분들도 친절하시고 음료 나오는 방법이 독특해서 소소한 재미도 있어요 ㅎㅎ', 14, 9, 'GOOD', SYSTIMESTAMP);
