INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '분위기, 커피맛, 인테리어 모두 독특하고 맛잇었어요. 주문한 시그니처 커피, 필터 커피 다 진심으로 만들어주시는게 보여서 더 맛나네요 !!', 27, 1, 'GOOD', SYSTIMESTAMP);
