INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '분위기 너무 좋구요 자리마다 콘센트가 있어서 노트북이나 뭐 다른 전자기기 있으신 분들 오기 너무 좋을 것 같아요. 주말인데도 사람이 많지 않아서 좋고 노래 넘 좋아요~! 근데 다른 것보다 커피가 진짜 맛있습니다. 커피를 별로 안 좋아하는 편인데 맛있는 커피가 이런 거구나 싶었어요!! 앞으로 자주 올 것 같아요!‘', 43, 0, 'GOOD', SYSTIMESTAMP);
