INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '공간도 멋있고 노래가 딱 조용한 핫플레이스에서 나오는 노래네요 🎵 평일에 손님 많이 없을 때는 노트북 작업하기 좋고, 주말에는 손님 많을 것 같은 카페에요 🤍 커피도 맛있고 버터바 다시 사먹어야겠다 싶은 곳 많이 없는데 여기는 버터바 퀄리티가 되게 높네요 (라즈베리 코코넛 먹었어요)', 14, 4, 'GOOD', SYSTIMESTAMP);
