INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '첫 방문인데 뜨거운 여름 날씨에 잔잔한 분위기가 마음을 차분하게 만들어주네요 :) 자리에서 기다리면 주문한 메뉴가 레일을 타고 오다가 딱 멈춰요! 번호표는 냅두면 레일이 다시가져가는 귀여운 모습 ㅎㅎ 카페인을 잘 못 마셔서 디카페인 필터 커피를 시켰는데 이렇게 노트가 적힌 메모지도 있어서 더 향을 즐길 수 있네요. 산미와 고소한 맛이 적당한 밸런스 ~ 약과 디저트는 맛있어서 포장합니다.. 적게 일하고 돈 많이 버세요... (약과 홀릭)', 25, 5, 'GOOD', SYSTIMESTAMP);
