INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '조용하니 집중도 잘 되고, 무엇보다 인테리어가 정말 신기해요.. 레일로 타고 오는 커피라니 커피도 정말 맛있고 세세하게 노트와 정보 알려 주셔서 커피 고르는 데 어려움 없었습니다 🌹', 64, 13, 'GOOD', SYSTIMESTAMP);
