INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '아지트처럼 자주 가는 공간이에요! 집중하기 좋고, 음료가 특히 맛있어요 방문하면 시그니처 꼭 마셔보세요! 딸기향이 맴돌면서 달콤하고 진득한 라테 맛이 일품이에요🙂', 78, 16, 'GOOD', SYSTIMESTAMP);
