INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '일단 카페 공간이 너무 특색있어서 들어가는 순간부터 좋았어요. 향과 음악도 센스있었어요. 첫 방문이라 시그니처를 먹었는데 딸기향이 진짜 나네요 신기합니다. 테이크아웃 할인도 되고 종종 들를 것 같아요! 작업하러 와도 좋을 것 같네요.', 3, 9, 'GOOD', SYSTIMESTAMP);
