INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '드립커피도 버터바도 맛있어요. 다른 곳에서 버터바 한번 먹어봤는데 제 입맛에 안맞네 생각했어요, 근데 우연치 않게 콤파일 바나나브릴뤠?버터바를 먹어보게됬는데 제 입맛에 딱 맞았어요.', 23, 5, 'GOOD', SYSTIMESTAMP);
