INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '합정, 홍대 근처에 가본 카페 중에 정말 손에 꼽을 만큼 예쁜 카페인 것 같아요. 버터바 향기, 조도, 분위기, 아메리카노 맛까지 모두 좋았습니다. 😁', 122, 26, 'GOOD', SYSTIMESTAMP);
