INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '블렌드가 너무 맛있어요! 웬만한 핸드드립 이상의 맛입니다!!! ㅠㅠ 특히 와이니베리는 테이스팅 노트에 적힌 것처럼 마시기 전부터 달콤한 시나몬과 과일의 향에 취했습니다…!!! 그리고 따뜻하게 마시는 걸 강력 추천드립니당!!🤭🖤🖤🤎🤎☕️', 130, 26, 'GOOD', SYSTIMESTAMP);
