INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '들어오는 순간 입구에서부터 좋은 향이 느껴지면서 기분이 너무 좋아집니다. 공간 기획이 너무 제 취향이고 커피, 디저트 맛도 좋아서 종종 오게되는 곳입니다.', 26, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '커피 원두도 고를 수 있고 컨베이어로 서빙해주셔서 재밌는 공간 같아요. 사장님의 배려가 가득 담긴 공간에서 잘 쉬다 갑니당 🫶', 28, 8, 'GOOD', SYSTIMESTAMP);
