INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '친구가 코딩카페라 해서 와봤는데 진짜 마인크래프트 속에 들어온 느낌ㅋㅋㄱㄱㅋㄱㅋㅋ 너무 재밌었는데 그와중에 음료랑 디저트 존맛', 37, 4, 'GOOD', SYSTIMESTAMP);
