INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '개발자들은 여길 보자마자 매료될 수 밖에 없습니다.. 내부 인테리어 중에 컨베이어로 커피 운반해줄때 조명도 같이 따라오는거 너무 매력있어요. 혼자 작업할때 집중하기 좋습니다. 커피도 맛있어요', 1, 3, 'GOOD', SYSTIMESTAMP);
