INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '컨베이어 벨트 시스템이 독특했던 콤파인 서교! 시그니처 음료도 굉장히 독특했고 버터바도 생각보다 느끼하지 않고 맛있었어요. 공간도 굉장히 넓직해서 대화하기도 좋았어요 :)', 5, 4, 'GOOD', SYSTIMESTAMP);
