INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '조용하고 분위기 좋은 카페에요 컨셉 확실하고 커피 퀄리티도 높네요 작업하기도 좋고 대화하기도 좋아요 자리마다 콘센트도 있어요 미쳐따. 다음에 또 재방문 할 것 같아요~', 30, 7, 'GOOD', SYSTIMESTAMP);
