INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '여기 가보라는 추천이 너무 많아서 드디어 왔네요! 컨베이어 벨트 타고 배달되는 커피 감성 너무 좋고요, 분위기도 좋네요! 작업하기도 좋고, 눈과 귀가 편-안 합니다!', 58, 12, 'GOOD', SYSTIMESTAMP);
