INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '너무 맛있어서 기억했다가 재방문합니다!! 브라질 빈할 그레이프가 정말 맛있어요! 디저트도 달지 않고 적당해서 커피 맛을 해치지 않아요. 꼭 오래오래 해주었으면..!', 43, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '홍대 놀러갔다가 유명한 카페라고해서 들렸어요! 컨베이어 벨트에 음료가 나오는 독특하고 신선한 컨셉이예요! 카페 간판이 따로 없으니 잘 찾으셔야해요! 도로 한복판에 있는데도 못찾았다는게 함정.... 주문하고 자리에 맞춰서 움직이다가 테이블 앞에서 멈춰요! 너무 편하고 좋았답니다💗 누가 이런 기발한 컨셉을 생각한걸까요... 또 가고싶어여 ㅠㅠ', 8, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '합정 최고의 카페입니다! 올때마다 분위기와 맛 둘 다 너무 만족하고 갑니다 ㅎㅎ 더이상 유명해지면 섭섭할정도로 좋아하는 매장입니다', 20, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '차분한 분위기가 좋아보여 가게되었는데 분위기와 맛 모두 완벽한 곳이네요! 원래 산미없는 커피를 좋아하지만 여기는 와이니베리 원두가 설명 그대로의 맛이 나서 추천하고싶습니다! 컨베이너벨트로 전달 받는 방식도 너무 독특하고 매력적이예요! 직원분들도 친절하셔서 자주 들리려고 합니다!', 44, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), 'import coffee from "cafe_compile" const review = () => { let taste = coffee.taste; taste = good; const interior = good; const evaluation = taste + interior; /*  커피도 맛있고 스터디 하기도 좋은 카페 */ return evaluation; }', 18, 8, 'GOOD', SYSTIMESTAMP);
