INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '분위기, 인테리어가 좋아요 대화하기에도 좋고 간단하게 업무 처리하기도 좋아요 커피도 맛있고 케익도 맛있어요 재방문 의사 있어요', 10, 0, 'GOOD', SYSTIMESTAMP);
