INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '컨베이어 벨트로 커피를 자리로 가져다주는 재미있는 카페 ☕️ 디카페인 드립커피로 주문했는데 너무 깔끔하고 맛있었어요. 커피랑 같이 나온 설명지?처럼 초코랑 아몬드향이 은은하게 나서 신기했어요 ☺️ 마셔본 드립커피중에서도 정말 손에꼽을 만큼 맛있어요! 의자가 푹신하지는 않아서 오래앉아있을 수는 없었지만 조용하게 커피마시기에 아주 굳이었어요 ~', 118, 19, 'GOOD', SYSTIMESTAMP);
