INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '이번에 시킨 콤파일에 논커피도 완전 대박적…! 히비스커스 크림슨 에이드는 상콤하고 시원하고 깜끔한맛…! 너무 마싯고 카카오 바나나 밀크는 달달 바나나향 쪼곰만 느껴져서 너무나도 취향인 부분👍🏻 버터바는 워낙 좋아하는 디저트라서 말모 무적권 먹어봐야할 디졑..❣️ 집만 가까왔어도… 맨날 오겠눈데.. 주말엔 인기 넘 많아 ㅠㅠ 그래도 자주 올래요❤️❤️❤️', 20, 8, 'GOOD', SYSTIMESTAMP);
