INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '우연히 방문하게된 카페인데, 인테리어도 신기하고 컨셉도 감성있어서 너무 분위기 좋아요! 커피도 정말 깔끔해서 맛있습니다! 드립커피 추천드려요!', 8, 4, 'GOOD', SYSTIMESTAMP);
