INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '카페 노래랑 분위기가 너무 좋고, 커피 종류 친절하게 설명해주시면서 메뉴 선택 도와주셔서 정말 좋았습니다. 다음에 또 오고싶어요.', 24, 3, 'GOOD', SYSTIMESTAMP);
