INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '컨셉이 확고하고 공대감성 묻어나는 인테리어에 구경하는 재미가있었어요! 어둡고 좀 시끄러운 거 빼면 의자&책상도 넓찍하고 자리마다 콘센트도 있어서 짧게 일하기엔 괜찮은 것 같아요!주문한 메뉴가 회전초밥집마냥 컨베이어벨트에 올려져서 전달되는 게 신기했어요!! 에이드는 잘 섞어먹어야하고 탠저린보다는 히비스커스 에이드가 더 맛있었어요', 28, 7, 'GOOD', SYSTIMESTAMP);
