INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '깔끔하고 트렌디한 카페. 친절함. 블루베리크럼블 6처넌 맛있어요! 조용한 분위기가 좋았습니다. 혼자와서 책 읽거나 작업하기 좋아보여요. 노래는 느낌있고 가사없어 asmr같이 좋았는데 한 곡이 크게 반복되서 오래 들으면 어지러울 수 있을 것 같아요! 전반적으로 마음에 드는 카페였어요 :) 케이크도 해주세용', 35, 8, 'GOOD', SYSTIMESTAMP);
