INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '간판없어도 많은 사람들이 찾아오는 카페에요! 사장님도 친절하시고 커피도 맛있고 레일이 독특해요!!! 분위기도 좋고 향도 좋은 곳!!!👍🏻👍🏻', 10, 4, 'GOOD', SYSTIMESTAMP);
