INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '컨셉 확실하고 분위기도 꽤 괜찮고요 레일로 메뉴 배달되는 것도 특이하고 좋아요 매 자리마다 콘센트 있고요 힙한 카페인데 직원분들도 친절하세요 맛도 괜찮은 편 요즘 제일 자주 가는 카페인듯?', 76, 13, 'GOOD', SYSTIMESTAMP);
