INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '인테리어가 너무 좋고 신기해요 내린커피 종류가 다양하고 맛있어요 아메리카노도 맛있고 디저트도 짱입니다 레일로 커피주는 컨셉도 너무 재밌습니다 커피 재밌게 먹구 갑니닷 ㅎㅎ', 25, 10, 'GOOD', SYSTIMESTAMP);
