INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '외관에서 건물과 하나가 된 듯한 느낌을 받으며 안으로 들어가면 차분한 분위기의 공간이 나온다. 스트레스해소&수면유도 음악이 나오는 카페다. 레일을 타고 서빙하는 방식은 굉장히 특이하고 재밌다. 옛날 486컴퓨터 시대의 감성이 독특하다. 커피가 맛이 없다. 아로마와 산미만 있을뿐 ‘맛’ 플레이버 자체가 되는 단맛이 부족하다.', 26, 5, 'BAD', SYSTIMESTAMP);
