INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '합정과 홍대 사이, 숨겨진 보석같은 카페 콤파일. 프로토콜이나 궤도같은 분위기의 카페가 취향이라면 꼭 가보길 추천하는 곳이었어요😁😁 학교처럼 책상이 열을 맞춰 배치되어 정돈된 공간과 몽환적인 음악, 차분하고 조용한 분위기 모두 취향저격! 레일 위로 주문한 메뉴가 나오는 것도 재미있는 경험이었어요 시그니처 커피 크림은 딸기가 들어간 크림라떼였는데 산미있는 라떼 좋아하면 강추하고 싶은 맛! 파운드케이크도 안에 잼과 크림치즈가 들어가서 맛있었어요 커피나 디저트, 공간 분위기까지 퀄리티가 좋아서 최근 간 곳 중 가장 좋았던 카페👍', 14, 8, 'GOOD', SYSTIMESTAMP);
