INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '커피랑 음료 디저트까지 정말 맛있고 조화도 너무 좋았어요. 카페만의 노래, 향 아울러 분위기도 좋고 차분해지는 느낌이 들어서 자주 방문해서 잠시 쉬었다 가거나 공부하기 너무 좋은 것 같아요.🫶🏻', 34, 9, 'GOOD', SYSTIMESTAMP);
