INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '스트로베리 와인향이 나는 커피 너무 맛있게 먹었어요! 약과 먹어보고 싶었는데 아숩네요! 잔잔한 음악 나와서 대화나 집중하기 좋아요!', 29, 7, 'GOOD', SYSTIMESTAMP);
