INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '인테리어도 특이하고, 차분하고 아늑한 분위기에 조용히 친구와 이야기하기도 좋아요. 바닐라빈라떼랑 카카오바나나 마시고 쉬다가는데, 특히 드립커피가 유명한데 담에 낮에와서 먹어보려고요~ㅎㅎ', 24, 4, 'GOOD', SYSTIMESTAMP);
