INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '👩🏻‍💻💬차분한 분위기라서 작업공간으로도 대화 나누기에도 좋은 분위기에요! 무엇보다도 컨베이어 벨트에 메뉴가 나온다는 점이 독특해서 컨셉이 마음에 들었어요. 바닐라빈라떼는 많이 단편은 아니라서 좋았습니다. 보이숙차는 아이스로 시키면 뜨거운상태로 나와서 얼음 다 녹을 줄 알았는데 꽤 오래 차가운 상태가 유지돼요!', 43, 1, 'GOOD', SYSTIMESTAMP);
