INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '매일 먹는 커피지만, 특별한 커피를 마시고 싶을 때 가는 곳 와 카카오바나나 내가 먹어본 아이스초코중 대박 넘 맛있고 친절하심 👍🏻', 7, 8, 'GOOD', SYSTIMESTAMP);
