INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '재미있는 요소가 많지만 유치하지 않고 세련된 느낌의 카페. 주문을 하면 컨베이어 벨트로 플로피디스크 번호표, 조명과 함께 음료가 제공됩니다. 컨셉은 차갑지만 이에 대비되는 직원분의 친절하고 세심한 메뉴 안내와 응대가 인상적입니다. 에스프레소 원두 두 가지의 성격이 극단적으로 다른데 비교하는 재미가 있었습니다. 식감이 부드러운 블루베리 크럼블도 맛있게 먹었습니다.', 49, 7, 'GOOD', SYSTIMESTAMP);
