INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '지나가다가 분위기가 너무 좋아서 들렸는데 카페가 아니라 전시회관같았어요ㅠㅜㅜㅜ 진짜 넘 이뻐요🤤 커피 원래 잘 못먹는데 커피가 주류같아서 사장님이 추천해주신거 시켜봤는데 와 진짜 처음 먹어보는 커피맛이였어요! 너무 맛있었습니다..♥️ 커피생각나서 꼭 다시갈거같아요! 디저트도 시켰는데 두개 다 고급스럽고 정말맛있었어요🥰🥰', 83, 11, 'GOOD', SYSTIMESTAMP);
