INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '카페 인테리어보고 왔는데 분위기와 커피맛에 치이고 갑니다... 진짜 혼자 집중하러 오기도 좋고 이야기하기에도 너무 좋아요!! 꼭 한번와서 커피드셔보세요. 커피맛이 기가막혀요ㅜㅠ 드립최고에요!!!', 12, 6, 'GOOD', SYSTIMESTAMP);
