INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '히비스커스 크림슨 에이드 초 강추 ! 오미자차 느낌나~믄서~ 달달구리 차 느낌! 매장자체가 깔끔하구 감성에 젖으러 오기에도 완전 좋음ㅎ 디테일적인 부분도 사장님이 상당히 신경쓰신게 보임 뭐 중앙 냅킨 배치라던지! 그리고 음료를 레일로 받아볼수있는 새로운 경험을 하게됨!! 이건 와서 확인하면 무슨말인지 바로 이해!', 98, 20, 'GOOD', SYSTIMESTAMP);
