INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '인테리어가 멋있어서 방문했는데 커피가 너무 맛있어서 놀랐어요!!! 유명한 로스터리 원두들이 준비되어있고 커피에 진심인거같아서 더 맛있게 느껴졌습니다 사진 막찍어도 인스타 감성샷처럼 나와서 좋았어요', 24, 9, 'GOOD', SYSTIMESTAMP);
