INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '카페 많기로 유명한 서교동에 오픈한지 얼마 안되는  카페에요 아주 특별한 것은 없지만 특유의 차분한 분위기때문에 종종 오게되네요~ 동네 시세에 비해 가격은 좀 있는 편이고요 카페 내부가 어두워서 작업하기엔 좋지 않을거 같아요 전 늘 수다 떨러 갑니다', 23, 3, 'GOOD', SYSTIMESTAMP);
