INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '이름부터 컴파일이라니 사장님이 어떤분이실지 궁금해질 따름이었습니다ㅎㅎㅎㅎ 독특한 서빙 방식도 한몫하네요! 커피도 맛있습니다. 보통 피치향이 들어있는 원두를 선택하는데 디카페인이라 살짝 머뭇거렸지만 역시 좋은 선택이었네요! 향과 맛이 아주 좋아요!', 52, 11, 'GOOD', SYSTIMESTAMP);
