INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콤파일'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '커피가 너무 맛있어요! 노트에 나온 그대로 맛이 표현돼서 맛있게 먹을수있었어요! 직원분들도 다 친절하시구 디저트도 너무 맛있어요 집앞에있었으면 맨날 올텐데 그게 너무 아쉬워요ㅜㅜ', 67, 11, 'GOOD', SYSTIMESTAMP);
