INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '유명한 커피집이라 방문해봤어요. 솔직히 가격대비 커피가 그렇게 맛있진 않았는데,,, 직원분들이 워낙 친절하시고 공간이 감각적이었어서 좋았어요!', 337, 62, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '도쿄에 있던 푸글렌에 좋은 추억이 있어서 서울에 생긴걸 알고 다녀와 봤습니다 기억은 흐릿해져서 그때 느꼈던 맛이랑 같은가? 긴가민가 했어도 ㅋ 커피는 정말 맛있었어요 :) 추억여행 제대로 하고 즐거운 시간 보내고 왔습니다-!', 60, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '라떼, 샤케라또 마셨는데 산미 강해 내입맛은 아니었지만 그렇다고 에스프레소가 맛이 없는 건 아님. 마시다보면 나름 독특한 향이 있음. 대기 시스템이 없어 만석이면 입구에 서서 기다려야 함. 실내는 협소한 편이나 구석구석 공간 활용은 잘 함. 맛보다 이곳 스텝분들 친절함이 인상적임. 아주 후렌들리함. 구석 2인 자리 생겨 가방 둘 곳 없어 대충 구석에 놓고 있는데 갑자기 외국인 스텝분 나타나서 가방 둘 해먹(?) 주고 가심. 와이파이 비번 물어볼 때도 그렇고 매우 친근하게 응대하심. 스텝분들 친절함 때문에 푸글렌에 대한 호감도 완전 상승. 사람들 바글바글한 와중에도 흐트러짐이 없다. 가격대가 비싼 편인데도 친절하니 그냥 납득해버림.', 15, 3, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '북유럽 3대 커피 중 하나인 노르웨이 🇳🇴 스페셜티 커피 브랜드, 푸글랜. Fuglen.  1963년 오슬로에서 시작된 푸글렌은 노르웨이로 ‘새‘ 🕊️ 를 의미해서 입구에 푸글렌 로고가 눈에 확. 2년 전 일본 동경 놀러갔을 때 방문했었는데 드디어 한국 상수동에도 1호점 상륙.  매장 내부는 스칸디나비아 빈티지 가구와 벽지 등 현지에서 직접 조달한 만큼, 북유럽 특유의 정서를 연출하고자 노력한 흔적이 엿보임. 아이스커피(케냐)와 오늘의 커피(콰테말라) 주문했는데 인텔리젠시아 못지않은, 커피 ☕️ 찐 맛집 인정. 👍🏻 메뉴에 있는 커피 다 먹어보고 싶음. 🤤 커피 맛집이지만 저녁에는 칵테일 🍸도 마실 수 있어서 영업 시간이 새벽 1시까지. 주차는 따로 지원이 안되니 인근 주차장 이용. 8시 🕗 오픈런하니 여유가득.', 42, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PARKING');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
