INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '저녁에 방문했는데 힙한 분위기가 매력적이예요! 푸글렌 아이스 커피(벤자민파즈), 오늘의 커피(엘레호) 두잔 마셨는데 푸글렌 아이스는 산미 살짝 있고 오늘의 커피는 발란스 좋았어요! 낮에는 카페로 저녁엔 바로 운영된다고 하는데 다음에는 낮에도 한번 방문해 보고 싶네요!', 10, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '커피가 제스타일은 아니었어요. 브루잉커피(오늘의커피) hot으로 마셨는데 산미가 너무있었어요. 오히려 식고나서 다 마실때쯤 밸런스가 좋더라구요...정말 한모금 남았을때.. 개인적으론 원두 로스팅후 시간을 더 두었다가 브루잉해야 제대로 밸런스가 날것같았어요.', 5, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '마포구 상수동에 있는 푸글렌커피에 다녀왔어요 상수역1번출구에서 도보로 1분이면 도착하는 거리구요 북유럽감성 가득한 커피숍이랍니다 노르웨이 오슬로에서 직접 원두를 가져오는 이곳은 부드러운커피맛을 지향해요~ 우리나라에선 최초로 오픈한곳이고 현재 일본에는 동경과 후쿠오카에 있다고 해요 저는 페루산 원두로 만든 아메리카노를 마셨는데 커피맛을 모르는 제가 마셔도 너무 부드럽고 좋아요~ 노르웨이 커피는 생두가 가진 본연의 맛을 잘 표현하기위해 로스팅적인 맛을 배제해 가벼운 로스팅을 해서 그렇다네요^^ 북유럽 감성가득한 멋진커피를  5000원에 맛볼수있어좋아요 저녁에는  술을 파는 바(bar)로 변신해요 커피맛과 한잔의 분위기 둘 다 누릴수 있는 멋진곳이네요^^주차지원이 안되니 대중교통을 이용하는것이 좋아요^^', 109, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '샤케라토 라떼-비추! 샤케라토가 설탕거품인데 단맛도 안나고 거품에 특색이 없어서 라떼 드실 분들은 일반 카페라떼 드세용,, 라떼라고 해서 우유의 부드러움을 기대하시면 안되고 커피 맛이 강해요! 아포가토-아이스크림이 달달해서 산미를 좀 잡아주더라구요 요건 추천합니다! 일본에서 너무 맛있게 먹어서 한국 들어온다고 했을 때 기대했는데 한국 푸글렌은 산미가 너무 강해요 ㅜㅜ 그래도 분위기 만큼은 진짜 독보적이고 좋아요 ..', 0, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '고즈넉한 인테리어가 멋있고, 직원분들이 모두 친절하셨습니다 ! 푸글렌 아이스 커피는 산미가 강한편이니, 참고해주시면 좋을듯 싶네요 ☕️', 64, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '푸글렌서울! 제가 산미있는 커피를 좋아하는데 오늘의 커피가 산미있는 커피라 넘 만족했어요! 다만 주말토욜이라 사람이 많아서 자리선정이 좀 어려웠지만 커피가 맛있어서 만족하네요! 상수동 1번출구에서 가까우니 꼭 한번 들르셔서 커피한잔 하시길요! 추천함돠!', 17, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '신촌에서 기대보다 더 맛있었던 닭도리탕을 먹구 집에 가는 길에 일부러 삥~~~ 돌아서 상수역까지 커피 마시러 왔습니다  이 근처까지왔는데 푸글렌을 어찌 지나치나요? ㅎㅎ 오다가 현백에서 사워도우빵 하나 사서 옆에 끼고 아까 포비에서 못마셨던 라떼를 푸글렌에서 마셔봅니다 역시나 은은한 꽃향기가 입안에서 촤르르르 퍼지며 부드럽고 맛있네요♡  이러니 푸글렌을 애정할수 밖에요 그치만 커피말고는 좌석배치 주문동선   실내의 넘 어두운 분위기등은 사실 그리 선호하지는 않습니다 후쿠오카푸글렌의 층고높은 탁트인 매장 캐주얼한 스탭들 편한 좌석 및 편한 배치와 동선 그리고 커피와 잘어울리는 핑거푸드들에 비하면 푸글렌코리아 분위기는 넘 조잡해보이는 건 사실... 😅', 12, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '도쿄에서부터 유명한 거라면서요?? 아아는 다 똑같다고 생각하는 사람으로 별 차이 모르겠어요 살짝 산미있는 아아? 사람 엄청 많아요', 16, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '라떼 엄청 부드럽고 크루아상도 맛있었어요! 더 오래 머무르지 못한 게 아쉬울 만큼 분위기도 좋았고, 무엇보다 주문 받아 주셨던 여자 직원분 너모 친절하심😍', 45, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '상수역에 일찍 도착해서 친구 기다릴 겸 들린 커피숍인데 커피도 너무 맛있고 인테리어도 너무 예뻐서 사진 찍기 좋아서 그런지 관광객들도 많이 방문 하는 것 같더라구요. 아침 일찍 들리면 혼자 여유있게 책 보면 시간 즐기기도 좋은 것 같습니다. 낮 시간대가 될수록 사람들이 점점 많아지긴 해요.', 56, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '저번 방문이 넘 만족스러워서 이번주에 또 푸글렌을 방문했어요! 평일 오후에 방문해서 그런지 자리가 널널했어요! 이번에는 ✅오늘의커피와 ✅핸드므루(온두라스)를 마셨어요! 오늘의 커피는 케냐였고 케냐 특유의 산미와 과실리 잘 살아있었어요! 배치브루여서 그런지 다크한맛이 중심를 잡아줘서 식어도 맛있게 마실 수 있었어요😊 핸드드립(온두라스 워시드)른 과실이 정말 잘 살아있었고 향긋해서 조금씩 식히며 마시기 좋았어요! 전 개인적으로 저번에 마신 콜롬비아 예니라모스가 더 취향이긴 했어요! 평일 오후에는 아침 손님으로 인해 빵은 남아있니 않았어요! 다음에는 꼭 빵도 먹어보고 칵테일도 마셔봐야겠어요🤩 커피를 좋아하신다면 푸글렌 상수 실망하시지 않으실 거예요!', 5, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '주말 방문에도 대기 없이 입장했어요! 한국 진출하자마자 높은 인기로 오래 기다릴줄 알았는데, 토요일 1시 30분쯤 방문했더니 자리가 있었어요. 공간 인테리어 센스가 돋보여요. 전반적인 우드톤 공간에서 편안한 느낌을 받았어요. 직원들의 적극적이고 친절한 응대가 공간을 더 특별하게 만들어줬어요. 필터커피, 우유 베이스 커피 다 맛이 복합적이고 흥미로웠어요! 여타 한국진출 유명 커피 브랜드와 달리, 자체적인 서비스와 감각, 맛까지 훌륭해요! 계속 방문하고 싶은 곳이에요 🍀😋', 40, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '일본에서 워낙 유명한 카페였던 푸글렌커피☕️ 한국에 생겨서 어마어마한 웨이팅 때문에 오픈하고 안가다가 평일에는 역시나 많은 사람이 있지는 않아서 바로 방문! 맛있는 커피와 세련되면서도 고급스러운 분위기에서 즐기는 커피는 환상적 무엇보다 향긋하면서도 다양한 캐릭터를 느낄 수 있는 커피를 즐길 수 있어 꼭 가보시길 추천👍🏻', 11, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '도쿄는 멀어서 못가고 홍대에서 푸글렌 커피를 마셔보내요. 사케라또라테. 푸글렌아이스커피를 주문해봤고 커피는 산미가 강하지는 않은데 약간 있네요. 사케라또는 설탕쉐이크라 보시면 될듯요. 홍대 푸글렌안에서 일본을 살짝 느껴보내요.  커피 갠적으로 맛은 있내요.', 482, 76, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '오늘의 커피 라지 사이즈 5,000원 아이스 카페 모카 7,900원 아주 더운 날씨 야외에서 마시지만 오늘의 커피는 포기할 수 없는 사나이 스타벅스도 콜드브루 다음으로는 오늘의 커피 숏을… 솔직히 맛은 특별한지 모르겠음 산미가 강함', 47, 10, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '북유럽 커피를 만나볼 수 있는 푸글렌 서울에 방문했어요! 커피는 ✅카푸치노(더블)과 ✅핸드드립(콜롬비아 예니라모스)를 주문했어요! 에스프레소 음료들은 샷을 싱글과 더블로 선택할 수 있었고 전 더블로 선택했습니다! 카푸치노는 거품이 거칠지 않고 에티오피아 에스프레소와 잘 어울렸어요! 약간 쌉싸름하면서도 베리의 맛과 향이 잘 느껴졌어요👍 드립커피는 정말 깔끔했고 레몬티의 뉘앙스가 날 느껴지는 워시드커피였어요! 워시드 좋아하신다면 무조건 좋아하실거예요😋 오후 1시쯤 방문했는데 운좋게 바테이블 자리가 비어 바로 앉을 수 있었어요😊 앉은 후에 테이크아웃과 웨이팅하시는 분들로 가게가 쉴틈없었어요! 바리스타 분들의 친절함과 환대에 놀랐고 커피에 대한 질문에 다 답변해주셔서 정말 기분좋은 시간 보내고 왔습니다🤩', 4, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '바쁜 홍대에서 벗어나 고즈넉한 분위기에서 즐기는 커피가 참 맛있네요. 산미있는 커피를 좋아하는 저에게 아주 좋은 커피였습니다.', 63, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '아늑한 바에 온 것 같아요. 첫 방문이라 메뉴 고심하고 있었는데 남자직원분이 친절하게 가이드 해 주셨어요. 그냥 기계적인 메뉴 설명과 추천이 아니라 엄청 섬세한 느낌이었습니다. 덕분에 커피 입맛에 맞았고 정말 맛있게 마셨어요. 커피도 좋지만 처음 보는 맥주들도 있어서 머릿속에 물음표 백만개 생긴 상황이라 그것 때문에라도 재방문 하게 될 것 같아요.', 31, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '얼마전까지 푸글렌 가고싶은 게 후쿠오카 가는 이유중 하나였지만 작년에 드뎌 한국에도 1호점이 론칭이 되서 이젠 그것때문에 가는 일은 없지만 그외 가야하는 수십가지 이유가 있기때문에 여전히 가는중 ㅎㅎㅎ 다음주에 또 갑니다~~~ 또쿠오카 4박5일!!! 하튼 ^----^ 홍대에 왔다가 그냥 갈수없어서 푸글렌 왔어요 오늘의커피(라지5000원) 마시는데 크으 역시 이 클린하고 군더더기없는 맛!!!  깔끔하게 블루베리뉘앙스 훅 던져주고 단맛과 신맛의 완벽한 균형을 이룬 맛!!! 푸글렌스런 한잔이고 푸글렌스런  오후네요♡', 15, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '북유럽 3대 커피라고 해서 궁금해서 방문했습니다. 노트북, 키보드를 두드리기 보다는 이곳의 분위기와 대화에 집중하게 되는 공간이었구요. 창가 자리가 인기가 좋았는데 저는 혼자 방문해서 아늑한 자리에서 충분히 공간의 아늑함을 느끼며 머무르다가 왔습니다. 평소 산미 있는 커피를 즐기지는 않는데 산미가 있음에도 라떼맛이 좋았어요. 다만 거의 먹을때쯤은 산미가 좀 더 느껴졌습니다. 추가로 팡오쇼콜라 주문했는데 물티슈만 제공되서 손으로 뜯어먹는 맛이 있었습니다. 빵 부스러기 걱정했는데 직원분이 손님들 가시면 전용 빗자루로 바로 잘 치워주시더라구요. 여유롭게 즐기고 오시기를 추천드립니다.', 24, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '분위기 너무 좋았고 직원분들께서도 너무 친절하셨어용🤍 그리고 오트밀 변경이 있어서 카페모카 주문해봤는데 진짜 부드럽고 맛있었어요!!', 119, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '카페 이용하는 사람이 많았으며 직원분들은 손님에게 적극적이시며 친절하셨습니다 커피도 나쁘지 않았습니다 나중에 여유있는 시간에 들려보고 싶네요.', 37, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '아침일찍오픈해서 너무 좋아요◡̈ 푸글렌아이스커피는 산미가 과일먹는것처럼 느껴져서 맛잇게 마셨어요. 샤케라또는 생각보다 안달고 가벼워서 아침에 마시기에도 부담스럽지않더라구요. 즐거운 커피타임하고 갑니당ㅎㅎ', 21, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '평소 산미 있는 원두를 즐겨 마시진 않는데, 푸글렌 산미가 강한데도 불구하고 너무 맛있습니다! 향도 너무 좋구요. 날씨가 좀 풀리면 테라스에서 커피 즐기고 싶어요! 상수를 종종 가게 되는 이유. 서울 2호점은 성수에 생겼으면 좋겠어요 🫢 직원분들 친절한 응대가 너무 마음에 들고 전체적인 우드톤의 인테리어가 따뜻한 느낌을 줘서 엄청 아늑한데, 배치된 가구들도 편안해서 좋아요 :)', 2, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'TERRACE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '커피 산미가 강한데 강하기만 한게 아니라 부드러워서 커피가 맛있게 느껴졌어요. 직원분들도. 사장님도 친절하시고. 기분좋게 다녀갑니다^^', 46, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '푸글렌 커피 궁금해서 와봐야지 하다가 일요일 아침 부지런히 상수점에 왔습니다.일찍 문여는 곳이라 이미 카페안엔 손님들이 많았구요:그래도 혼자 앉을수 있는 좌석이 있어서 기다리지 않고 라떼! 마실수 있었네요:-)라떼가 정말 순하고 엄청 크리미하고 단정해요.우유가득한 라떼 찾으시는 분들은 좋겠어요.매장내 음악 참 좋네요.카페 음악이 늘 거슬리던 사람이였는데 이곳은 공간과 음악의 발란스가 참 좋아요.매장안 구석구석 모아둔 그림이나 소품은 북유럽.교토의 참 다양한 표정들이구요.어떤 한가지 컨셉으로 규정짓기 애매한데 그런 언발란스가 참 묘하게 어울려요.아침이라 오늘의 커피에 따뜻하게 데운 크루와상드시는 분들이 많네요!나도 다음엔!그렇게!도톰한 유리잔의 라떼.잘 마셨어요!', 79, 15, 'GOOD', SYSTIMESTAMP);
