INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), 'Espresso martini was lit!! 🔥 If you are looking for a hard liquor kinda cocktail, i would def go for espresso martini! Its on the pricier side but totally worth it!', 107, 24, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '카페라떼 싱글, 아메리카노 싱글 마셨습니다👀 아메리카노는 약간의 산미가 느껴지고 라떼는 부드러워서 목넘김이 좋아요!!! 푸글렌 전메뉴 도장깨기 진행즁🩵', 32, 5, 'GOOD', SYSTIMESTAMP);
