INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '지나가다 사람 별로 없어서 대기없이 테이크아웃 했네요. 커피가 향이 좋고여. 사실.산미있는커피는 그닥 즐기지 않지만 푸글렌서울 아메리카노는 싱그러운 향기와 산미와 모든 맛이 조화로워서 입과 코가 즐겁게 마실수 있는듯 해요.', 23, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'TERRACE');
