INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '싱글 따아, 싱글따라 늦은 저녁에 찾아서 가게된 푸글렌상수 분위기 너무 좋고 창가석에 모닥불 바라보면서 마시믄 커피한잔 여유 💕 푸글렌 늦은 밤에는 위스키도 가능해서 담엔 한번 경험해볼려구~~ 모닥불 냄새가 온통 퍼지는 ㅎㅎㅎ', 73, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '상수의 핫한 커피숍. 요즘 신생 카페들처럼 화려하진 않지만 공간이 주는 아늑함이 참 좋은 곳. 우드톤의 인테리어와 낮은 조도의 조명이 편안함을 준다. 라떼는 싱글샷에 오트밀크로 변경하였는데 부드럽게 마실수 있어서 너무 좋았다 ! 진한 커피 향을 원한다면 투샷을 추천 ! 디카페인 메뉴가 없어 호박차를 주문하였는데 웬걸 은은한 호박의 향과 단맛이 올라와 너무 편안하게 즐길 수 있어 좋았다. 양이 적다는 아쉬움이 있었지만 호박의 새로운 발견 ! 직원분들 너무 친절하고 공간이 좋은곳. 최애 카페가 될 것 같다.', 243, 92, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '커피가 맛있어서 또 왔어요~! 저번에는 라떼 싱글샷을 마셨어서 이번에는 더블샷으로 주문!! 근데 싱글이나 더블이나 맛이 조금 라이트했어요 (내기준) 그래도 원두가 너무 맛있는 것 같아요. 원두 맛이 이렇게나(?) 신선하고 디테일하게 느껴지는 커피.. 푸글렌에만 있는듯? ㅋ 뭐 암튼... 웨이팅이 좀 이상하게 있지만 (그냥 카페 입구에 우두커피 서 있어야 함) 커피가 맛있어서 만족입니다. 직원분들도 친절하시고... 다만 테이블이 넘 불편하다고 해야하나.. 힙하다고 해야하나..  뭐.. 어쨋거나.. 카페에 있는 꽃이 생화여서 더더 만족했습니다. (카페에 조화 있는거 싫어하는 1인)', 393, 63, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'TERRACE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '유럽풍인가 싶은데 먼가 친근한 분위기로 있는데 일하기 싫어하는게 너무 티가나는 직원이 분위기 망치는 카페 공간은 너무 이쁘게 뽑아서 보기 좋음. 홍대라 다행이다 ㅎㅎㅎ', 6, 8, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '그 유명한 푸글렌인데 그냥 원래 있던 오래된 카페처럼 화려하거나 요란하지 않은 느낌이라 편안했어요. 커피는 산미가 있었는데 제 입엔 잘맞았구요, 뺑오쇼콜라 주문하니 데워주셔서 커피랑 맛있게 잘먹었습니다.', 45, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '도쿄에서 항상 실패하다가 결국 서울에 오픈해서 가봤네요. 아침일찍 가서 자리는 많았는데 11시쯤 되니까 금새 만석 됬어요. 산미가 강하다 했는데 카푸치노 싱글로 시키니까 마실만 했어요~~ 분위기가 좋아요!', 90, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '빵과 커피가 맛있어요! 뺑오쇼콜라가 특히 맛있었는데 푸글렌은 포크와 나이프를 주지 않더라구요 ㅜㅜ 먹기 굉장히 힘들었습니다…. 😂 이부분은 개선되면 좋을것 같다는 생각이드네요! 저녁에는 또 다른 분위기를 느낄 수 있더라구요. 음악도 좋고 직원분들도 친절하셔서 자주 방문할것 같아요 :)', 22, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '노르딕 커피를 경험해보기 위해 다녀왔습니다! 도쿄 푸글렌을 못가서 아쉬워하다가 상수에 있길래 가보니 핫플답게 역시 사람이 많더라고요. 🫢 내부에 자리가 없어서 야외 테이블에서 먹었는데 날씨가 춥지 않아 딱 좋았습니다. 라떼 연하게 먹으니 딱 제 취향! 약간의 산미가 있었던 것 같아요.', 59, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'TERRACE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '도쿄에서 시간상 못갔던 푸글렌을 합정동에서 만나니 행복했어요. 밤엔 칵테일 마시기 좋은 바로 변신하는데 커피 먼저 마셔보기로. 맛있어요!', 80, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '엄청 유명하더라구요🙂 아메리카노 싱글샷. 라떼는 더블샷으로 먹어봤어요☕️ 기대가 컸나봐요. 아메리카노는 약간 묵은맛이 났고 라떼는 보통. 매장 조명이 너무 예쁘고 건물이 인생샷 찍기에는 너무 좋더라구요🤎 직원분들도 넘 친절하셨지만 커피는 아쉬웠어요💓 그래도 다음에 또 들려서 다시 먹어보려구요! 감사합니당😊', 38, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '푸글렌이 서울에도 오픈했다는 소식에 바로 들러보고팠지만 오픈과 동시에 엄창난 핫플이라는 얘기에 이제야 방문해보았습니다. 수년전 방문했던 도쿄의 푸글렌과 비슷해서 오자마자 바로 추억돋더라구요. 인테리어도 완전 멋스럽습니다👍 이날은 푸글렌 아이스커피와 오늘의 커피를 주문해보았는데 커피도 너무 맛있었어요😍👍덕분에 추억 돋는 기분 좋은 방문의 푸글렌 서울이었어요.👍', 23, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '명절 연휴에 다녀왔어요. 사람 많아서 테이크아웃했구요. 바깥 자리 있었는데 추워서 마시진 못하겠더라구요. 카페모카로 주문했구 적당히 달구 맛있었어요.', 16, 1, NULL, SYSTIMESTAMP);
