INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '2024년 10월 드디어 노르웨이의 커피 명가 푸글렌 서울 홍대거리에 오픈 주차는 메세나폴리스 지하3층에 주차 후 산책겸 걸어서 도착 로스팅을 중정도로 싱글과 더블로 기호에 따라 선택 가능 오늘의커피가 아메리카노보다 더 부드러움 다른 브랜드보다 커피맛이 강하지 않으니 약이나 중으로 커피 드시는 분들에게 좋음 이미 핫플레이스인지 가게안엔 젊은이들로 가득 자리가 없어서 테이크아웃 저녁8시부터는 커피 칵테일도 맛볼수 있다네요 커피칵테일 맛이 궁금해 기다려 볼까 했는데 일단 오늘은 그냥 커피만 맛보기로 결정 노르웨이 사람들은 이리 커피를 약이나 중배합으로 음미하며 즐긴다 하네요 산미도 살짝 나니 좋고 저처럼 투썸이나 스벅 투샷이 진해서 원샷으로 드시는 분들은 강추! 컵이 참 예쁘네요! 커피칵테일 맛보러 재방문예정', 88, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PARKING');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
