INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '매장이 적당히 여유가 있고 날씨가 선선해서 너무 좋습니다. 안쪽은 어둡고 아늑한 편이고 창가는 개방감이 좋습니다. 커피는 매우 빨리 나오고 셀프로 들고 가게 되어 있어요.', 11, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '1. 도쿄에서만 가봤던 노르웨이의 커피 명가를, 이제 서울에서도 만날 수 있다는 자체만으로도 좋았습니다. 2. 좌석은 한정되어 있는데 손님들이 본인 옆에 의자 하나만 띄어놓고 앉는 바람에 다른 2명의 손님들은 자리를 앉지 못해 웨이팅하는 모습들이 보이더라요. 3. 멕시코 원두를 선택했는데 산미가 그리 강하지도 않고 부드러웠어요. 잔으로 대략 2잔 정도 나온 것 같습니다. 이 가격에 이 정도의 커피라면 아주 만족스럽죠.', 79, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '공간이 멋있어요... 노르딕 산장느낌이랄까 커피는 아이스 아메리카노 시켰는데 브라질 원두였는데 덜익은 과일의 떫은 맛의 신맛이 느껴졌어요. 라테는 친구가 1샷 옵션이 있어서 선택했는데 완전 연한 라테이니 꼭 2샷 다해서 드시길 추천드립니다!', 5, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '와.. 저녁 푸글렌 정말 매력적이네요✨ 빈티지하면서 멋스러운 인테리어도 좋고, 아늑한 공간과 어울리는 음악이 잔잔한 대화소리와 섞여 편안함을 주네요. 핸드드립도 맛있습니다. 다음 일정 때문에 잠깐 머물렀다 이동했는데 넘 아쉬웠어요. 또 방문 예정!', 6, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '연휴 마지막 날 늦은 사간이라 사람이 없었어요. 커피향 가득한 커피 칵테일 시나몬 프라페가 좋았고 다른 커피 칵테일도 다 먹어보고 싶네요.', 18, 7, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '내부공간이 넓지 않지만 아늑하고 분위기가 너무 좋습니다 테이블 의자 아기자기한 소품들까지 직원분들 친절하시고 여러잔 주문해서(트레이가 없더군요) 직원분이 직접 가져다 주셨어요 약간의 산미에 전체적으로 깔끔한데 발효취같은 꿈꿈한 노트가 느껴져서 신기했음', 11, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '상수의 핫한 분위기를 이끌고 있는 커피맛집 푸글렌 서울 오픈한지 일주일이 되지 않은 상수역 근처 따끈한 신상카페 푸글렌 10월24일 오전10시부터 문을 열어 현재까지도 많은 사랑을 받고 있다. 29일 평일 오픈 시간이 30분정도 지난 시간의 모습이며, 웨이팅은 생기지 않는듯 했지만 확 빠지고 확 들어오는 손님들을 볼 수 있었다. 다가오는 주말이라면 다시 웨이팅을 각오해야될수도 푸글렌 서울은 북유럽 3대 커피로 이미 전세계에서 많은 사랑을 받고 있는 카페 아시아에서는 일본 인도네시아에 이어 한국 상수동으로 착륙했다고 한다🛫 그 전에는 도쿄점이 그나마 친근한 느낌👀 직원분들도 너무 친절하시며 조금 정신 없는것을 제외한다면 맛과 분위기 모두 좋았던 푸글렌 서울 더 자세한 정보는 최제로 블로그🙇🏻‍♂️🌼', 5, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '북유럽 3대커피 푸글렌이 한국 상수동에 상륙했어요🎉 노르웨이어로 ‘새’를 뜻하는 푸글렌은 1963년부터 시작한 노르딕 커피로 생두를 약하게 볶아 원두 본연의 풍미를 느낄 수 있는 브랜드. 일본, 인도네시아에 이어 3번째로 오픈한 한국 매장은 한국적인 외관과 북유럽 스타일의 내부의 조화로 멋스러움이 느껴지고, 카페와 칵테일바를 겸하는  매장 컨셉과 어우러지는 인테리어가 특징이에요 독특한 커피 맛과 이국적인 감성을 즐길 수 있는 곳이며 많은 사람들의 이목을 끈 카페로 커피 좋아하는 사람들은 꼭 방문해보세요', 5, 10, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '과일의 향긋한 산미가 느껴지는 케냐AA 한 입 베어물면 바사삭 깨지는 겉바속촉 달콤한 뱅오쇼콜라 짱짱!!! 절로 휘게문화에 젖어들수있어요 생각보다 앉는 자리가 많아서 좋았구요 사람이 많아서 그런가? 화장실에 휴지가 넘쳐서 ㅠㅠ 좀…. 직원분들 친절하고 여유있는 모습에 기븐 좋았어요', 37, 0, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '한국에 상륙했다하여 기대하고 간 푸글렌서울 인상적인건 아직도 대기가 있다는 것과 테이크아웃 컵이 독특했다는 점 글쎄 두번째는 고민이 필요한', 40, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '노르웨이 오슬로에 본점이 있는 푸글랜커피! 북유럽 3대커피 중 하나인데 서울 상수에 매장이 생겼어요👏👏 아시아에서는 일본을 제외하고 2번째로 진출했다고 해서 그런지 오픈때부터 아직까지도 낮에는 웨이팅이 장난아니더라고요. 푸글렌커피 웨이팅 없이 방문하는 꿀팁은 낮시간대는 피하고 아예 아침 혹은 아예 저녁에 방문하는거에요! 평일에는 아침8시부터 저녁11시까지 주말은 새벽2시까지 영업하더라고요. 그리고 여기는 커피만 파는게 아니라 다양한 위스키로 판매하는 bar로 변신하는곳이에요!! 매장 외관부터 내부까지 인테리어가 굉장히 빈티지하고 고급스러우면서 모던한 느낌이라 인스타갬성 사진 남기기도 딱이에요😎', 97, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '일본에 이어 아시아에 2번째로 진출한 노르웨이 커피 브랜드 푸글렌의 매장이 서울 상수동에 오픈했어요. ​ 상수역 3번 출구에서 도보 2분거리에 위치하고 있고 대로변이라 접근성이 좋은 편이에요. ​ 푸글렌의 커피가 특별한 맛을 내는 건 아니지만 일본 도쿄나 미국 뉴욕여행했던 분들이라면 푸글렌에 한 번쯤 방문했을 거예요. ​ 내부 인테리어와 분위기가 좋고 낮에는 커피를, 밤에는 칵테일을 파는 매력이 있어 휴식과 따스한 분위기를 느끼고 싶은 분들에게 방문을 추천해요!', 63, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '좋네요 인테리어도 이쁘구 외국인분들이 바테이블에 앉아계시니 외국에 온것같은 느낌도 들고 너무 좋네요 혼자와서 여유롭게 커피 즐기기도 좋을 듯 합니다! 테라스도 있고 루프탑 공간도 있으니 날씨가 좋을땐 이용해보고싶네요', 36, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'TERRACE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '상수역과 가까워서 찾기 편하고 하얀색 외관과 간판이 눈에 확 들어와요~!! 일인석 바도 꽤 자리가 많고, 분위기도 좋았고 화장실이 실내이기도 해서 편했어요 라떼는 살짝 산미가 있는 느낌이고 더블이라 가격이 7천원이기는 하지만 방문해보기 잘한듯해요', 34, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '오슬로 커피 푸글렌. 우리나라에 작년 겨울 들어왔다. 오슬로 밖에는 도쿄에 몇 군데 있는 걸 알았는데 서울에도 상륙했다. 1960-70년대 스칸디나비아 인테리어와 신맛이 강한 북유럽 커피 전통, 그리고 저녁에는 칵테일 바로 변신해 새벽 2시까지 영업, 이 세 가지가 푸글렌이다. 1963년 오슬로에서 시작해 그 당시 북유럽 분위기를 이어오고 있다. 유럽에서의 전쟁 후 젊은이들이 새로운 세상을 추구하던 시절이다. 그 시절의 인테리어, 커피, 열정(커피와 칵테일)을 담았다. 그 전통이 지금에 와서 동아시아에서 각광받고 있다. 상수역 바로 옆에 있는데 잘 안되던 자리다. 이럴 때 보면 브랜드의 힘이 느껴진다. 오슬로는 커피의 수도라고도 불리운다. 오슬로로 일본인들이 커피투어 간다. 겨울에 북유럽을 느끼고 싶다면.', 10, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
