INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '카페투어나 카페탐방에 커피일을 하기전에는 관심이 없던1인, 2019년 팀웬들보 원두를 마신 이후 관심갖게 된 노르딕커피 중 커핑으로는 조금 아쉬움이 있던 푸글렌원두! 이번에 상수역에 오픈하였다고 해서 커피리브레 파란점 퍼블릭커핑도 갈겸 즉흥적으로 방문, 생각보다 웨이팅 줄이 길지않아 예상보다 빠르게 입장하고 싱글샷 에소 3,000원에 놀라 바로 주문하였다 픽업하기 기다리며 바리스타분께서 도징부터 탬핑하는 마지막단계까지 볼수있었는데 디스트리뷰터 & 마무리탬핑까지 얼마나 많은 Shot을 추출하셨을지 바이브가 느껴지는 멋진모습에 감탄하였다! 결과는 대만족스런 한잔, 아로마부터 오렌지블로썸이 좋았는데 Vibrant와 Raisin, 두모금 Cacao Sweet에 오렌지블로썸 & 셋 :) 쥬시와 미디엄바디까지☕️😋', 2, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '밤에 방문하니 카페보다는 위스키바같은 느낌이 드네요ㅎㅎ 원두가 산미가 강해서 고소한 맛을 좋아하는 분들에게는 도전일수도 있습니다ㅎㅎ 푸글렌 서울이 생겨서 푸글렌 도쿄 인생샷 찍으러 안가도 될듯~!!! 원하는 좌석 앉으려면 운이 필요하긴 한데 요즘같은 날씨에 밖에서 먹으면 운치가 넘 좋으니 추워지기 전에 빨리 방문해 보시길!!ㅎㅎ', 41, 7, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
