INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '아늑하고 괜찮았어요. 오늘의 커피 주문했는데 코스타리카 원두라고 이야기 하신듯 하네요 빨리나오고 좋네요 ㅎㅎ 일행이 주문한 모카는 옅은 농도의 코코아 맛이었고 간만에 소파에 앉아 여유 만끽하고 갑니다', 52, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '일본 푸글렌 원두를 맛있게 마셔서 가고 싶었는데 오픈빨 조금 빠지고 방문했어요. 핸드 브루는 에어로프레스로 좋게 말하면 라운드하고 편안하게, 제 취향으로는 뭉툭하게 내려서 취향은 아니었고 배치브루로 내리는 오늘의 커피, 아이스 커피가 정말 맛있더라구요. 평일 낮에도 바쁘지만 커피나 추출에 대해서 물어보면 직원분들 모두 잘 답해주시고 서비스가 너무 좋았습니다. 새것 티나기보다 빈티지하고 편안한 느낌의 인테리어는 말할 것도 없구요. 원두가 오슬로 직배송이라 일본에 비해 가격이 좀 더 붙는 것 같은데 한국 자체 로스팅이 됐으면 하는 바람입니다.', 40, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '분위기는 정말 좋습니다만 커피의 맛은 그렇게 특출나지 않은 듯 하고… 빵을 주문하는데 식기를 주지 않을거면 물티슈라도 제대로 주셔야 하는 것 아닌지. 물을 셀프로 따라 마시는 곳에선 덜 마른 유리컵을 겹쳐놔 잘 빠지지도 않습니다.', 69, 18, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '푸글렌 상수의 원두는 노르웨이 오슬로(로링 로스터기)에서 볶은 콩을 항공으로 공수되었다고 한다 향후 도쿄에서 볶은 콩으로 대체될 수도 있겠다 싶다 리네아pb 머신에 메져 콜드s 그라인더 조합 3천 원의 싱글 에스프레소는 브라질 싱글 내추럴 원두 모든 커피는 블렌드(잡곡)가 아닌 싱글(쌀밥)원두만 사용 에스프레소는 탄내 쓴맛 없이 적당한 스모키에 카카오 함량 높은 다크초콜릿 탑 노트가 좋다 꽃이나 과일 향미는 없다 아주 분명한 다크초콜릿이다 매끄럽고 부드러운 텍처가 참 좋다 설탕이 들어가지 않아도 진하고 점성 가득한 질감은 나무랄 데가 없다 브루잉커피는 펫코 xts 배치브루 추출 같다 디팅의 kr807 랩스윗 하이엔드 그라인더 에스프레소 싱글(3천 원)/오늘의커피(4천 원)는 무조건 추천한다', 33, 4, 'GOOD', SYSTIMESTAMP);
