INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '북유럽 3대 커피 푸글렌 서울 오픈 2일차 금요일 3시쯤 방문해서 40분정도 웨이팅하고 들어갔습니다 테이블링이나 예약으로 웨이팅 하는게 아니라 줄 서서 계속 기다리셔야 합니다.. 푸글렌 아이스커피, 카페라떼, 샤케라또를 주문해서 마셨는데 아이스커피가 가장 맛있었어용! 산미가 조금 있는 편이고, 푸글렌만의 방법으로 커피를 내려줘서 독특하고 한번쯤 경험해볼 만한 카페입니다 북유럽 인테리어로 감성적이고 테이크 아웃하면 예쁜컵에 담아줍니다~ 테이블바에 쿠키도 무료이니 함께 먹어 보세요!', 11, 2, 'GOOD', SYSTIMESTAMP);
