INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '북유럽 커피 3대 라고 해서 찾아가봤지요 오후3시쯤 가서 그런지 웨이팅이 심하진 않았지만 사람이 많긴헀어요 필터커피랑 카페라떼 주문했고 원샷을 먹었는데 더블샷도 괜찬았을거 같아요 커피 너무 부드럽게 맛있었습니다', 99, 23, 'GOOD', SYSTIMESTAMP);
