INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '한국에 상륙한 푸글렌!! 개인적으로 일본 여러번 놀러갔어도 방문 안 했던 곳이라, 동네에서 방문할 수 있게 되었을 때 더 좋았어요😆 저녁에 방문하니 더 여유롭기도 했고, 낮에 지나가면서 보았을 때랑은 또 다른 분위기라서 좋더라구요!!! 노르웨이 산장에서 커피/칵테일 마시는 느낌 낭낭해요💓', 49, 4, 'GOOD', SYSTIMESTAMP);
