INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '커피맛집이라고 해서 가봤어요 역에서 가까워요 신상까페라 외부 내부 모두 깔끔하고 직원분들은 친절해요 안에 좌석이 많지 않고 야외 테이블이 많아요 원두는 신맛이 강하다고 해서 저희는 우유가 들어간 라떼와 카푸치노를 주문했어요 음..맛은 그냥 평범해요 원두는 무직함보다는 가볍고 우유도 유기농 우유가 아닌 일반우유인거 같아요 진하고 고소한맛이 덜해요 요즘 시그니처커피 파는곳도 많고 에스프레소 파는곳도 많은데 굳이 커피 하니때문에 또 방문할것 같진 않네요 궁금하다면 호기심에 한번쯤은 와도 좋을듯하네요', 72, 17, NULL, SYSTIMESTAMP);
