INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '월요일 오후에 방문한 푸글렌 평일임에도 웨이팅이 조금 있었지만 운 좋게 바로 착석 :) 싱글 종류도 다양하고 커피도 맛있게 잘 마셨습니다', 15, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '더블 카페 라떼 7.0 오늘의 커피☕️ 4.0 리필 가능🥤2.0 크로와상🥐 5.4 상수역 1번 출구에서 가까워서 좋았어요❤️ 프랜들리한 바리스타님들 덕분에 행복한 시간 되었습니다☘️👍🏻', 40, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '커피 퀄리티가 참 좋아 벌써 세번째 재방문 입니다. 배치브루도 드립도 꽤나 밸런스 좋고 은은한 산미의 티라이크한 느낌의 커피들이라 QC가 잘 유지되는 브랜드라는 인식이 인상깊은 곳입니다. 설 연휴이고 꽤나 매장 내가 혼잡했는데, 그래서인지 오늘 카운터에서 응대해주신 남자 직원분이 다소 불친절하셔서 좀 놀랐습니다. 설명을 요하는 질문도 귀찮은 듯 단답으로 주시고 단호하고 퉁명스러운 응대가 일행도 느껴졌다고 하여 데려간 입장에서 약간 무안하게 느껴졌어요. 이전까지 서비스에 대해 아쉬웠던 점이 없었던 터라 오늘 좀 아쉬움이 남습니다. 무안함에 테이크 아웃 받아 바로 나왔습니다.', 27, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '일본여행갔을때 사람이 너무 많아서 못가봤는데 이렇게 서울에 매장이 생겨서 다녀와봤어요. 커피맛도 좋고 카페 분위기도 너무 좋아요', 45, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '너무 좋아하는 곳이라 일주일만에 또 찾아왔어요❤️❤️ 드립커피마셨는데 빨리 식어서 좀 아쉬웠어요🥹🥹 산미있는 커피 좋아하는 터라 커피 맛은 너무 좋았습니다', 224, 28, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '오후 5시 조금 넘은 시각에 방문했어요. 거의 기다림 없이 음료를 받았네요. 실내공간보다는 야외가 더 많아요. 서서 마시는 좌석도 많이 있어요. 라떼의 우유는 연한 느낌이었어요. 편안하지만 진한 느낌은 아니라 호불호 갈릴 것 같아요. 라떼는 원샷과 투샷 옵션이 있는데 투샷 추천합니다. 아이리시 커피는 저녁 6시부터 주문할 수 있어요. 다음 일정이 없었다면 마셔봤을지도 모르겠네요.', 10, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '핫플에 방문!! 핫플이어서 그런가 손님 중 우리가 제일 늙은 느낌... 지울수 없네.. 콰테말라 커피랑 라떼 더블샷 주문! 커피맛이 굉장히 신선하고 맛있다. 라떼는 조금 밍밍하고 라이트한 느낌.. 싱글이어서 그런가.. 맛있긴 한데 너무 라이트한 느낌.. 웨이팅이 있고 자리가 나면 바로바로 안내해준다. 자리변경은 불가능... 계속 웨이팅이 있어서 더더욱 ㅋ 그래서 원하는 테이블에 앉을 수가 없음... 새벽 2시까지 영업한다는데.. 오픈런이나 밤늦게 와야 원하는 자리에 앉을 수 있을 듯 ㅋㅋ', 39, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '북유럽 갬성 카페가 오픈했다고 해서 근처에 일보러 갔다 들렀어요. 일반 가정집을 개조한 공간인데 실 외에도 작은 테이블을 두고 있네요. 내부는 깔끔하게 개조되어 있어요. 외국인 바리스타가 기계처럼 계속 커피를 뽑고 있네요. 임장하는데 한 15분 기다린 것같은 데, 카페 들어갈 때 기다려 보기는 처음이네요. 카푸치노를 주문하고 가장 안 쪽 소파 자리를 잡았어요. 모르는 다른 사람들과 테이블을 공유하는 자린데 직원이 공짜 과자를 주더군요. 커피는 평범한 커피맛이고 좀 쉬다 가려고 했는데, 사람들이 계속 들아와서 자리 찾아 두리번 거리고 다니니 그냥 빨리 마시고 나오게 되더군요. 아직은 오픈빨이 강해선지 사람이 치이는 느낌입니다. 여담이지만, 푸글렌을 나와서 철역으로 이동하는데 근처  카페는 빈데가 많더군요.', 45, 5, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '애매한 시간을 잘 맞추면 웨이팅이 없더라구요! 푸글렌 일본가면 꼭 들리는 장소인데 서울에 생겨서 행복합니다❤️❤️ 내부 인테리어도 너무 좋고 커피맛도 더할나위 없습니다❤️❤️', 9, 1, 'GOOD', SYSTIMESTAMP);
