INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '푸글렌 아이스 커피 짱 맛있고 칵테일도 예술입니다 사람 냄새 풀풀 나는 바👍👍👍 친구랑 가서 몇 시간 떠들다가만 왔네요 또 가야지~', 21, 6, 'GOOD', SYSTIMESTAMP);
