INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '싱글라떼 원샷했어오. 뺑오랑 함께 -* *뺑오쇼콜로 정망 맛있어요. 매번 카페랑 콜라보하는 킨토도 구매해서 바로 푸글렌 아이스커피 투고했어요. 두 번째 커피타임 !', 41, 2, NULL, SYSTIMESTAMP);
