INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '라떼 부드러운데 생각보다 연해서 무조건 더블 추천! 공간 넘 예쁜데 지금은 워낙 핫해서 조금 지나거나 오픈시간에 다시 가서 여유있게 마시고 싶어요!', 83, 12, NULL, SYSTIMESTAMP);
