INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '주말인 토요일에 갔는데도 자리도 널널하고 웨이팅도 없었어요☺️ 오늘의 커피도 4,000원밖에 안해서 가성비있고 가을에 치열했던 테라스자리도 오히려 겨울이라서 널널하게 찍을 수있어 좋았습니다☕️🫶🏻', 51, 15, 'GOOD', SYSTIMESTAMP);
