INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '도쿄 후글렌보다 넓고, 후쿠오카 후글렌보다 훨씬 멋진 인테리어. 접근성도 좋고, 저녁시간의 낮은 조도와 어울리는 평온한 커피밸런스. 마음에 들어요', 2, 0, 'GOOD', SYSTIMESTAMP);
