INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '다행히 실내에서 웨이팅할 수 있었고 매장 분위기는 좋아요 하지만 자리가 굉장히 협소해요 거의 구겨져서 앉는 느낌,,,ㅋㅋㅋㅋ 유명한 곳이라 비쌀줄알았는데 생각보다 저렴하더라구요! (호박차 5000원)', 70, 17, NULL, SYSTIMESTAMP);
