INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '도쿄점보다 맛있어요 - 캐치테이블 같은 별도의 대기 시스템 없음 - 안에서 마시고 갈 줄, take-out 줄 별도로 존재 - 추위 감수하고 바깥 자리에서 마신다고 하면 먼저 주문도 가능 ㅎ', 11, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '매장 인테리어가 도쿄, 오슬로 푸글렌과 통일성이 있어서 좋았습니다. 다만 1) 짐을 놓을 거치대가 너무 적고, 2) 스태프 분들의 응대가 일관성이 없으며, 3) 핸드드립이 다 식어서 나오더군요. 매장이 한산할 때 방문했는데 가방 거치대가 보이지 않아 옆 자리에 두었더니, 스태프분이 쫒아오셔서 다른 손님과 쉐어하는 자리라고 이야기하시길래 당황스러웠습니다. 그럼 거치대를 좀 넉넉히 놔주세요. 핸드드립도 포트를 뚜껑없이 주셔서 너무 빨리 식었습니다. 커피도 주문한 커피명으로 불러 내놓으시니 손님들이 계속 주변에서 본인 커피인지 서성이셔서 번잡스러웠습니다. 산미있는 커피가 좋아 여러번 방문 중이지만, 커피를 즐길수 있는 원조 오슬로 푸글렌처럼 편안한 분위기를 만들어주셨으면 좋겠습니다.', 44, 0, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '노르웨이 오슬로에 본사를 둔 푸글렌이 서울 상수동에 오픈했어요 이제 도쿄가서 먹지 않아도 서울에서 푸글렌 커피 즐길수 있어 넘 좋네요', 53, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '점심 먹기 전에 리얼차이 마셨는데 분위기도 너무 취향이고 커피맛도 궁금해서 또 들렀어요. 커피는 너무 기대해서 생각보다는 평범했지만 퀄리티 높아요. (커피 좋아해서 디저트보다 커피만 보고 카페 고름) 다만,, 혼자 바 자리에 앉았는데 커피 조금 남았을때 화장실 다녀오니깐 치워져 있었더라는... 슬펐습니다. 치울까봐 조마조마했는데.. 그만큼 빠르게 매장 관리를 하시는 거겠죠..? 알바들은 모두 방긋방긋 친절했습니다. 대접받는 기분!', 1, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '힙하긴 한데.. 커피 자체가 그 정도로 맛있다는 느낌은 아니어서 아쉬웠습니다. 칵테일 메뉴가 다양하게 있던데, 그쪽은 어떨런지 모르겠네요ㅎㅎㅎ', 40, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '소문듣고 방문 매장 북적북적 사람 정말많네요 텍아웃해서 먹었는데 커피 맛있네요 원두 담에 사려고요 이정도맛에 가격도 괜찮다고 생각합니다👍', 82, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '여전히 핫플!! 평일점심 끝없는방문이 이어지네요 오늘의커피 과테말라였는데 정말 맛있게 마셨어요 컵도 커피마시기좋네요 컵좋단생각 처음해봐서 화들짝...', 55, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '밤에 방문해서 커피 말고 초콜릿우유를 마셨어용! 많이 달지 않고 좋았어요 ㅎㅎ 분위기가 되게 포근하면서 힙한 느낌? 낮에는 어떤지 모르겠지만 밤에는 알콜 메뉴도 운영하시더라구용', 110, 21, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '오픈 초기라 역쉬나 많은 사람! 안에 내부가 칵테일바 같은 느낌! 라떼먹어봄! 우유의 부드러움이 더 메인인 커피맛이 살짝 부족 특별한 맛은 없고 고급과 저렴의 중간티어?! 굳이 재방문은 없을듯,,', 48, 2, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '추운날씨라서 밖에 앉을수없어 매장은 많이 혼잡하고 제대로된 웨이팅 시스템이없어서 기다리다가 그냥 가는분들도 많았어요 편하게 커피를 마시기에는불편한 카페예요 푸글렌커피를 한번 경험해본다면 방문해보세요  산미가 있어서그런지 라떼는 별로였습니다', 409, 89, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '매장이 넓은 것 같으면서도 테이블은 별로 없어요. 분위기는 아늑하고 따뜻한 가정집 분위기에요. 커피가 엄청 맛있다는 모르겠어요. 라떼 맛이 좀 맹맹한 게 특이해요. 가격이 비싼편입니다.', 54, 14, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '언니가 가고 싶대서 방문! 사람 많았지만 좌석이 다양하게 있어서 선택하여 앉기 좋았어용! 간 날에 커피 원두 시음 이벤트가 있어서 설명도 듣고, 커피도 마시고, 날씨도 좋고~ 넘 좋은 시간🙂', 46, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '군인이라서 평일외출 나왔을 때 여자친구와 함께 방문했는데, 격려의 말과 함께 제 커피값을 안받으셔서 죄송스럽고 너무 감사했습니다! 군복을 입고 잠깐 사회로 나오게 되면 놀리는 친구들도 있고, 무시하는 사람들도 종종 있고, 지하철에 자리가 있어도 왠지 일어서서 가게되는 순간들이 있습니다. 또한 가끔은 군 복무하는 이 시간이 원망스럽게 느껴지기도 합니다. 하지만 푸글렌에서의 맛있는 커피와 함께 받은 따뜻한 마음이 위로가 되었습니다. 앞으로 남은 군생활 최선을 다할 작은 동력이 될 것 같습니다.', 22, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '서울에도 생겼단 소식에 반가워서 가봤어요 도쿄랑 거의 비슷하고 역시 사람이 많네여 ㅎㅎㅎ 후글렌커피는 무난한 맛 특별하진 않았어요 샤케라떼를 먹어야할듯', 4, 10, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '도쿄느낌 기대하며 방문, 야외도 그렇고 안쪽 테이블 바 계산 분위기 좋아요! 1,2층 야외좌석도 꽤나 있고 바 테이블도 좋고요. 다만, 자리잡고 주문하거나 하는 시스템이 아니라 주문하고 음료를 받아들고 자리를 잡아야하는 시스템으로 안내를 하다보니 대혼잡!!!!! 자리가 있는지 없는지 체크도 안되거니와 안내받을 수도 없음. 이 부분 아쉽고요, 음료 가격에 비해 양이 일단 작고 크로와상 주문에 포크나이프 없음. 아포가토 레모네이드 등 안되는 음료가 꽤 있어서 요건 아쉬워요.. 커피 맛은 좋은데 양이 작고, 심볼앞에 웨이팅 줄이 서있다보니 소심이들은 사진 찍기 힘들.. 날씨가 좋아서 지금 딱 테라스 계절 즐기기 좋고 밤에 칵테일 분위기는 또 다를거 같아요!!!', 66, 17, NULL, SYSTIMESTAMP);
