INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '카운터에서 주문받으시던 여성직원분께 라떼 주문하면서 “우유는 어떤거 사용하세요?”라는 제 질문에(라떼에서 우유맛이 차지하는 비중이 크고 브랜드별로 맛이 상이하므로) “우유업자세요?” 라고 되물으셨죠. 기분 나빴지만 뒤에 사람들이 많아 참았습니다 모모스커피에서도, 앤트러사이트에서도, 커피냅에서도 같은 질문을 했지만 이 손님은 우유맛을 구분하시는구나 생각하며 오히려 친절히 응대해주셨는데, 저런 어처구니없는 반응에 당혹스럽네요 라떼는 우유가 중요하답니다 이 글 꼭 보셨으면…', 47, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '푸글렌이 서울에 오픈했다고 해서 방문햇어요! 가격대는 블루보틀보단 조금 싼 정도? 라떼가 유명해서 시켰는데 맛있었습니다.. 다만 잔이 유리잔인데 트레이도 없이 주셔서 뜨거운거 집을 때 너무 ㅋㅋㅋ불편했어요;; 깨지면 어쩌려고 흠.. 그 부분은 개선되어야할 것 같아요..', 94, 26, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '오늘의 커피와 카페 라떼 추천드려요. 웨이팅은 오픈일 기준 평균 2시간이고, 손님이 적으면 1시간 정도입니다! 웨이팅 꿀팁은 https://m.blog.naver.com/cha_cha_cha_official/223631909993 블로그에 적어두었는데, 절대적인 꿀팁보다는 오늘 현장 웨이팅 결과 추천 시간대 정도입니다:) 주말은 다를 것 같아서, 참고용입니다.', 41, 1, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '인터넷 검색을 통해 푸글렌을 알게 되어 방문 1번 출구에서 직진했다가 조금 헤매다 지도를 보고 찾음. 커피는 순한 편이라 싱글샷보다 투샷을 다음에 오게 되면 맛보아야 할듯 진동벨이 없어 매우 불편( 거의 모든 손님이 카페라떼와 카푸치노를  주문해) 부를 때 마다 어리둥절', 50, 9, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '오늘의 커피(에티오피아)의 맛은 약간 산미가 있고 평범한 편입니다. 1층 실내는 음악이 잔잔히 흘러 분위기가 있고 날씨가  맑은 날에는 야외루프탑도  괜찮습니다. 오픈초기라 웨이팅이 있습니다.', 37, 5, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '오픈초기에 갔을때는 자리먼저 잡고 음료주문을했는데 두번째 방문에는 가족들과 방문해서 어렵게 자리잡았는데 음료주문을 먼저하고 픽업까지 끝낸후에 자리를 잡으라는 다소 의아한 시스템이어서 너무 불편했고 주문할때도 저번에 분명 케냐커피를 마신기억이있어서 케냐같은 산미있는 커피가 있는지 물어봤는데 손님 응대하는 단발머리 여자분이 자기들은 케냐를 판적이없다고해서 몹시 당황스러웠고 손님이 자세히 물어보지않는한 커피원두설명을 하나도 안해줘서 처음 갔던 좋은 기억이 전부 사라졌습니다. 다른 나라 푸글렌?가봤는데 이렇게 자리잡는 시스템? 전혀 없었습니다. 두번 다시 방문할 일 없을겁니다.', 64, 12, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '한적한 오후에 커피한잔하러갔다 기분상하는 경험을 하고왔네요. 주문 후에 자리를 잡아야하는게 브랜드 방침이면 사전에 안내가 필요해보입니다 주문하는 손님한테 자리 비워달라는 요청하는게 아니라요.. 안내문이 필요할것같다는 요구에 다른 나라의 매장도 동일하다는 직원분의 응대 또한 너무 아쉬웠습니다.. 다른나라 매장안가본 사람도 분명이 있을텐데요 그리고 대부분 손님들 자리잡고 주문하시던데 방침이 있으시면 동일하게 적용해주세요 여러모로 아쉽고 불쾌한 기억이 남습니다', 76, 18, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸글렌 서울'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '두번째방문은 실망! 일단 라테폼이 하나도없고. 아트를 도전하던데 라떼 아트도안나오고... 바리스타 자질의심! 커피는 향도.산미도 아무맛도없이 밍밍. 저번과는맛이다름. 또한! 주문누락으로 한참기다렸음!', 8, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대L7점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '🤎팥빙 젤라또 파르페 한 동안 SNS 난리를 치던 팥빙을 이제 먹게됐다..🥹 팥빙 자체 조합과 맛은 흔히 먹을 수 있는 거지만 가격과 퀄리티를 봤을 때 아주 우수 제품. 특히 아이스크림이 팥맛이 잘 나서 좋아요. 얼음 아작아작 깨먹을 때마다 종종 쫀득하게 씹히는 떡과 아래에 가라앉아있던 달콤한 팥들이 진짜 존맛탱. 팥빙 자체는 8월까지 하고 9월부터는 가을 에디션으로 바뀐다고 해요. 그러니까 다들 후회하지 말고 한 번쯤 경험하도록 하십시다! 홍대 메가커피 가게는 엄청 크진 않았지만 그래도 많은 사람이 앉을 수 있을 정도이고, 메뉴도 다양하게 있어요. 직원분들도 친절하시고 좋습니다👍👍', 267, 83, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대L7점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '요즘 그렇게 핫하다는 팥빙 젤라또 파르페 드디어 먹어봤네요. 간편하게 먹기편하고 밸런스도 잘 맞아서 인기있는 이유가 있어요. 올여름 자주 먹을듯하네요.', 12, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대L7점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '오후 알바생 너무 불친절하네요 밖에 있는 키오스크가 에러가 났는지 안 되길래 말했더니 대답도 안 하시고 그냥 무시하셨어요 자주 가는 곳인데 .. 개선되길 바랍니다', 80, 11, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대L7점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '아사이볼 시켰어요... 우리동네 메가는 아사이볼 한스쿱인가 엄청 조금 주는데 여기는 3스쿱 주는듯 ... 암튼 넉넉하게 줌 좋아요~~~~ 글고 아사이볼은 디저트라 스탬프 적립안됨~~ 참고요', 14, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대L7점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '저녁에 방문했는데도 번화가에 위치해서 그런지 매장 내 머무는 분들이 많이 계셨습니다. 테이크아웃으로 주문하고 음료를 수령하는데 컵홀더가 되어있지 않아 의아했는데 별도도 바구니에 컵홀더를 비치해 두고 있었습니다.', 66, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대L7점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '월요일 오후 4시 20분 경 방문했고, 안경 쓴 여자 직원 분 혼자 계셨습니다 음료를 기다리며 밖에서 제조 과정을 보는데 티백을 걍 손으로 만지시더라고요…? 프랜차이즈 카페 알바를 한 사람으로서 티백 꺼낼 때는 미니 집게를 사용해 손이 안 닿게 했었는데 … 사람이 안 보더라도 기본적인 위생 규칙은 지켜야 하지 않을까요 그 손으로 포스기, 손님 카드, 볼펜 이런 거 다 만졌을 텐데 너무 실망입니다 ..', 6, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대L7점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '도넛&제로 아이스티 세트 시켰는데 제로아이스티는 맛있으나 노티드 도넛 냉동에있다가 꺼내주는데 안에크림 그냥 아이스크림마냥 얼어있어서 맛없습니다 그냥 노티드가서 사먹는게 나을듯합니다 여름이라 그렇다하면 차라리 냉동보단 냉장이 더 낫지않았을까 싶기도하고 그렇네요 ..매장은 넓고 시원해서 좋아요', 44, 10, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대L7점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '늘 지나다니는 길에 있지만 이용한 적은 어제가 처음이었는데요. 바쁘신거 백번 이해합니다. 인력이 부족해보였어요. 그런데 홀상태가 이게 맞습니까? 음료 픽업대 위도 물자국이 얼룩덜룩하던데 홀이 깨끗한 상태에서 그 픽업대를 봤으면 어제같은 날은 습도도 높았으니 습도 때문인가 하고 아무생각 없었을 텐데 단 한 테이블도 깨끗한 곳이 없는 홀을 보다 음료 픽업대를보니 마치 물떼가 낀것처럼 느껴져서 진심으로 속이 울렁대고 이 음료 마셔도 되나 싶더라고요... 저 음료 쏟아진 테이블은 제가 들어가기 전 언제부터인지 모를 시점부터 제가 머물러있는 삼사십분동안 그대로 방치되어있었고 음료도 먹다가 도저히 안되겠어서 그대로 남기고 왔습니다. 아무리 저가커피여도 못먹으면 돈 아까운건 매한가지에요...', 257, 60, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대L7점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '내부에도 키오스크 하나 있어서 편하게주문하고기다림. 알바언니기 주문 많이밀려있어서 10분정도걸린다고 안내해주시고 바쁘신데도 친절하게 멘트해주심.', 49, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대L7점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '홍대 메가커피점 중에 여기가 제일 조용하네요. 사람들이 다른 곳보다 적어서 대화하기 좋고, 좌석도 편해요. 신메뉴 그린애플펄에이드, 그린애플요거트스무디, 핫치킨딥치즈치아바타 먹어봤어요😃', 49, 8, 'GOOD', SYSTIMESTAMP);
