INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대L7점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '일정이 있는데 사이에 시간이 붕 떠서 급하게 카페 찾아서 온건데 매장도 넓고 번화가에 있어서 그런지 사람들도 꽤 많은가봐요! 오후 4시에 가도 사람들이 꽤 있지만 그래도 좌석이 없는 편은 아니에요!ㅎㅎ', 38, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대L7점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '내가 먹어본 메가커피 아메중 젤 맛있었습니다 사장님이 머신 관리도 잘하고 맛있게 잘 내리네요.. 근처살았으면 자주 방문했을거 같습니다~', 40, 3, 'GOOD', SYSTIMESTAMP);
