INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대L7점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '쇼콜라 딸기라떼 프라페를 시켰는데 와 딸기도 초코도 둘다 진해서 진짜 맛있어요👍🏻 먹다보면 묘하게 돼지바 느낌도 나요 ㅋㅋㅋ 양 정말 많으니 텀블러 가져가실 분들은 진짜 큰걸로... 챙기시길 바랍니다😘', 22, 1, 'GOOD', SYSTIMESTAMP);
