INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대L7점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '메가커피 신상메뉴 화이트뱅쇼, 스노우샹그리아에이드, 따끈따끈간식꾸러미 먹어봤어요~ 겨울메뉴로 저렴이 버전으로 먹고 싶다면 한 번 먹어보세요~😃😃😃😃', 14, 6, 'GOOD', SYSTIMESTAMP);
