INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대L7점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '핫초코 맛이 생각보다 없었어요 없었어요메가커피는 핫초코가 메인이 아니니깐요 근데 매장 홀에 우유를 흘려놓은것같은데 치우시는분이 없더라구요', 22, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대L7점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '잠시 폰배터리없어서 커피먹으면서 충전하려고 갓는데 콘센트 망가진곳잇어서 아쉬웠어요ㅠ 그래서 자리 옮겻어요., 커피는 항상 맛나요', 19, 1, 'BAD', SYSTIMESTAMP);
