INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대L7점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '겨울 신메뉴 시켜봤는데 넘 맛있어여!! 겨울 꾸러미 구성 넘 알차고, 크기가 작아도 맛은 그대로라 놀랐어요:) 음료도 맛있어요😊', 57, 16, 'GOOD', SYSTIMESTAMP);
