INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대L7점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '메가커피 좋아하는데 와 수박주스 너무 맛없네요ㅠㅠㅠㅠㅠㅠ 여름이라 시원하고 달콤하게 과일주스 시도했으나 대실패,,,,,, 다른 메뉴 드세요.', 105, 21, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대L7점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '오전에 직원 혼자 일하시는 게 아주아주 바빠 보였습니다... 싱크대는 설거지할 게 쌓여 있고, 덕분에 저도 이런 상태의 음료를 받았답니다.', 2, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대L7점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '여기 너무 지져분해요  파리 날파리가 너무 많고  바빠서 그런지 손님 나가도 테이블 치우지도 않음  사장님 청결에 신경좀 써주세요', 28, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대L7점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '가성비가 좋아서 옵니다. 근처에 스벅 컴포즈 이디야가 다몰려있어서 메뉴봐가면서 고루고루들리는데.. 오늘은 요거트스무디는 컴포즈보다 여기가나은것같아서 들렸어요 ㅎㅎ', 47, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대L7점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '항상 출근 시간엔 사람이 많아서 3-5분정도 기다려야 하는데 오늘 유난히 오래걸리더라구요. 당연히 바쁘기 때문에 그것에 대해 불만을 삼는것은 아닙니다. 저도 출근길이기 때문에 시간을 알고자 얼마나 기다려야하냐는 질문을 5분 간격으로 2번이나 했습니다. 그때마다 알바생이 잠시 기다려야 한다고 했습니다. 결국 너무 지연되어 출근이 늦어질것 같아 취소 했고 결국 지각했습니다. 애초에 너무 오래 걸릴거 같으면 물어봤을때 대략적으로 몇분 걸린다고 말해야 하는거 아닌가요? 제가 몇분 걸리냐고 물어봤을때 시간을 말하는것이 아닌 순서대로 나가야한다는 동문서답을 했습니다. 결국 커피도 못마시고 시간도 낭비하고 지각도 하고.. 단지 커피가 늦은거에 대해 말하는것이 아닌 알바생의 업무 태도에 불쾌했습니다.', 70, 14, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대L7점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '친절하신 직원분때문에 커피맛이 더욱더 좋더라구요. 다른 메가커피는 패스오더로 미리 주문 가능한데 여기는 제가 못찾는건지 모르겠어요.', 49, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대L7점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '시간이 떠서 쉬어 가는 길이었는데 친절하시고 혼자 앉을 수 있는 창가 자리가 생각보다 편했습니다. 홍대 왔다가 시간 때워야 할 때 또 들러 보려구요.', 42, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대L7점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '누락되었다고 20분이나 기다렸어요 계속 주문기앞에서 기다렸는데... 저보다 늦게온 사람들 음료가나와 물어봤더니 시스템 누락이라는 말도안되는  변명하며 취소하겠냐네요 ㅎㅎ 아아랑 아이스라떼 만드는데 아주 하루종일 걸리겠네요... 황당했고 , 직원들 두명 정말 불친절하고  자기들끼리도 정신없이 우왕좌왕하느라 ...음료 잘못만들고 , 테이크아웃잔에 제조했다 매장잔으로 옮겨담느라 난리고 ..... 아아나온거 버리고.. 총체적 난국이였어요 다신 방문안할거에요', 5, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대L7점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '진짜 최악이에요..평일 저녁 8시에 가서 아이스티랑 쿠키프라페에 아이스크림올린거를 주문했는데 휘핑크림 아이스크림 전부 마감했다고..ㅋㅋ 이게 말이 되나요? 영업시간이 월~금 07:30 ~ 23:30라고 나오는데 저녁8시부터 마감하나요? 제가 10시에 간것도 아니고 8시에간건데 진짜 아닌것같습니다 그리고 품절이면 무인판매기에서 메뉴를 빼던지..그것도 아니고 뭐하자는거죠? 심지어 사과는커녕 따지듯이 말하더군요 환불하려다가 알바생 표정이 썩었길래 말았네요 결국 휘핑,아이스크림 없이 음료만 받았어요 다시는 안갈것같아요 메가커피 좋아해서 자주 가는데 이렇게 황당한적은 처음이네요', 41, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대L7점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '퐁크러쉬 시켜먹었습니다. 보통 메가커피에서 퐁크러쉬 시키면 죠리퐁 나왔었는데 여긴 딱딱한 과자같은 게 나왔어요.. 맛도 없었구요 달달구리한 일반 죠리퐁맛을 생각하신다면 퐁크러쉬는 시키지 마세요', 42, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대L7점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '커피와 딸기샌드가 맛있었습니다, 그러나 토요일영업시간이 오전7시반으로 공지되어 있는데 8시로 변경 필요해 보입니다. 7시반부터 8시까지 직원 덕분에 안에서 기다릴 수 있었습니다. 그러나 여자 화장실 변기와 천장은 수리가 필요해보입니다.', 25, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 홍대L7점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '사진은 당시에 찍은 아메리카노가 없어서 다른 메가커피 음료 올린거에요 오히려 커피탄맛을 좋아하는 사람은 여기만한 가격대 커피 없을거에요 로스팅 오래하면 나는 향 선호해서 메가커피 보이면 샷추가해서 종종 마셔요', 29, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '커피 원두를 선택할수있고, 커피맛도 좋음. 카스텔라가 시그니처고 그외 베이커리가 꽤많은곳 카스텔라가 밀도가 있다. 카페가 넓고 북까페 스타일로 열람용책도 많다. 일상을 여행처럼이라는 문구도 이곳을찾는이에게 쉼과 여유를 주는것같다.', 43, 5, 'GOOD', SYSTIMESTAMP);
