INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '책도 읽을수 있고 도서관 분위기 카페 꼼마에 왔어요. 커피도 향, 맛 좋고 디저트 한라봉 홍차 케이크 달지도 않고 한라봉 향기 긋   맛있어요.', 30, 4, 'GOOD', SYSTIMESTAMP);
