INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '카페꼼마... 이름이 참 예쁘지요. 일상에 지친 현대인들에게 필요한 쉼. 알면서도 잘 되지 않는 삶. 이름이 마음에 들어 찾아온 이곳은 홍대입구역 3번 출구에서 직진하면 보여서 찾기도 쉬운 북 카페네요. 층고가 높아 시원하고 쾌적한 느낌이라 열람용이라고 되어 있는 책을 읽으며 시간을 보내기도 좋고 카페에서 눈을 끄는 문구 ''일상을 여행처럼'' 과 같이 창밖을 내다보며 멍때리는 시간도 좋은  것 같아요. 단아힌 계단의 2층은 올라가보지 않았지만 외부에서 보이는 2층과 1층 내부에서 유추해 보면 더 안락하지 않을까 싶습니다. 요즘빠져있는 흑임자라떼에도 쉼표가 편안함을 더해 주었고 얼그레이 가토쇼콜라는 달지 않아서 더 좋았습니다. 폰번호를 입력하면 3%마일리지 적립을 해 줍니다. 잘 쉬었다 갑니다.', 57, 14, 'GOOD', SYSTIMESTAMP);
