INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '위치가 좋아요 홍대입구에서 엄청가까워서 약속기다리면서 있기엔 좋으나,, 테이블이 다닥다닥 붙어있는 편, 화장실이 작고 줄이 길어서 불편,, 그리고 생각보다 책을 읽기엔 너무 시끄러워요 ㅠ', 389, 35, 'BAD', SYSTIMESTAMP);
