INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '지난 번에는 1층에서 시간을 보내서 오늘은 2층으로 올라갔습니다. 소나기가 쏟아져서인지 손님들이 엄청 많습니다. 2층 안쪽은 스피커소리도 크고 (부분적으로 조정이 안된답니다) 에어컨이 있어  춥기까지 합니다. 친구는 바깥의 초록초록한 풍경을 볼 수 있다고 너무 좋아합니다. 쉼이 필요할 때... 카페 꼼마입니다.', 10, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
