INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '맞은편 카페를 못 가서 대안으로 들어간 곳입니다. 그런데 생각보다 좋았습니다. 우선은 책으로 한 면이 다 인테리어되어 있어서 좋았고 높은 천장이 사람들이 많아도 떠드는 소리가 시끄럽게 들리지 않아서 좋았습니다. 카페는 차를 마시러도 가지만 이야기하러 가는 곳이기도 하니까요. 커피야 제가 큰 사이즈로 주문을 해 버려서 마시는데 조금 힘들었지만 쇼콜라 케이크는 아주 맛있었네요. 가운데 자리가 비어 있었던 이유가 냉방기의 냉기를 정면으로 맞는 곳이어서...... 하지만 요즘처럼 더운 날에는 시원하게 하는 곳이 좋은 곳이니까 뭐..... 연남의 젊은 거리를 바로 볼 수 있는 그런 장소였던 것 같네요.', 58, 17, 'GOOD', SYSTIMESTAMP);
