INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '전부터 북카페로  알고 있어서 와보고 싶었는데 대화하기에 좋네요. 책들도 많구 나중엔 책과 함께 티타임 조용히 (홍대에선 쉽지 않겠지만 ㅎㅎ)', 24, 10, 'GOOD', SYSTIMESTAMP);
