INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '우연히 보고 예뻐서 들어갔어요.매장도 엄청 넓고 인테리어도 이뿌고 사람도 진짜 많아요.아아만 먹기는 아쉬워서 딸기 크림 수플레 카스테라도 같이 시켰는데 양이 넘 많아서 거의 남겨서 아까웠지만 맛있었어요.사람이 넘 많아서 정신없는 느낌은 있어요.', 41, 10, 'GOOD', SYSTIMESTAMP);
