INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '브런치 먹고 지나다 들린 곳 책이 있어 그런가 분위기 사믓 다르고 좋네요 라떼 좋아하지만 바로 먹고 나와 이쁜 거 먹어보고 싶어서 ㅋ 그린 폼 딸기 라떼 역쉬나 눈으로 이쁘면 맛도 좋다는 진리 ❤️ 딸기맛 그대로 부드러움 👍 봄이 와쑥  도 맛있었어요 담에 다시 오고 싶은 곳 ❤️', 81, 12, 'GOOD', SYSTIMESTAMP);
