INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '에어컨 개빵빵하고 홍대 한복판이라 쉬다가기 조흠 친절하시구 매장도 좋아요 근데 다만 매장크기에 비해 화장실이 남녀공용 하나 뿐인거 같아 아쉽', 2, 0, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '연남동 쪽 약속있으면 종종 오는 곳이예요.. 아침 10시에 방문할 수 있는 카페가 근처 할ㄹㅅ 이외는 11시 12시 오픈인데 10시 오픈이라 좋구요. 오후엔 사람들 많아서 너무 시끄러운데 오전타임엔 조용하고 햇빛 잘들어와서 너무 좋은 곳이예요. 혼자 책읽가도 좋고 여기저기 조용히 작업하시는 분들도 있답니다! 음료나 베이커리 가격은 조금 있는 편입니다. 딸기라떼 7000원인데 tall사이즈 정도 되요', 30, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '지나가다가 괜찮아 보여서 들어갔습니다. 자리가 꽉 차기는 했는데 운좋게 한 자리가 비어있어서 앉을 수 있었습니다. 커피도 케이크도 맛있어서 기분 좋게 얘기하고 나왔습니다. 다만 사람이 많아서 매장이 다소 소란스럽고 화장실도 한참 줄서야 들어갈 수 있을 때도 있었습니다. 자리가 없어서 그냥 돌아서 나가는 사람들이 꽤 있었는데 소지품, 충전기를 놓고 한참을 자리를 비운 테이블 관리만 좀 하면 나아질 것 같습니다.', 66, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '날 좋아지면 바깥에 앉기 좋은 곳..!🥹 인테리어도 예쁜데 실내(특히 2층)소리가 좀 울려서 사람 많고 시끄러운 분위기에서는 귀도 울리는 그런.. 것도 있지만 괜찮아요!! 제가 예민한 걸지도.. 주문 받으시는 직원분은 밝고 친절하셨어요!:) 딸기 크림 수플레 카스테라 진짜 맛있어요! 디카페인 라떼랑 같이 먹었는데 옴총.. 완전 맛있었숩니닷.. 커피도 맛있던데 또 올거에요ㅠㅠ', 11, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'TERRACE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '홍대입구역 3번 출구에서 아주 가까운 카페 콤마. 여의도와는 아주 다른 분위기. 위치가 좋아 손님이 많은곳. 1-2층인데 화장실은 2층에 공용인 단점. 커피는 디카페인도 있고 세가기 맛중 선택가능.  크림 두툼 카스테라 먹고싶었으나 배불러서 다음으로', 110, 26, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '핸드폰 노예일때 와서 책읽기 좋은 곳 일단 북카페이라서인지 보고싶어지는 책들이 책장에 아주 많아서 책읽고싶다는 생각이 들어지는 곳임 북카페는 주로 자리이용요금까지 받아서 좀 가격이 있다고 생각이 드는데 여기는 음료값만 내면 됨 그래서 인지 음료값이 좀 나가는 편임 자리는 생각보다 많은데 자리마다 콘센트가 없는 자리가 대부분이라 디지털과 잠시 멀어질수 있는 시간을 갖을 수 있음', 120, 23, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PLUG');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '연남동 디저트 카페 꼼마 동교점을 방문했어요. 원래 연남 대형카페가 있던 자리였는데 카페꼼마가 들어왔더라고요! 오랜만에 커피, 디저트와 함께 책을 읽으며 여유로운 오후를 보내고 왔어요. 홍대 볼거리로 추천드리며, 연남동에서 데이트 장소 찾는 분들도 가보시면 좋아할 거예요.', 54, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '오 겨울이앙? 카스테라 먹었는데 크림이 많아 부담스러울까 걱정했는데 딱 적당했고 바밤바느낌이었음 카스테라빵이 무엇보다 맘에 들어서 다른 맛도 궁금함 소금빵은 내기준에선 쏘쏘', 90, 16, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '쉽지않은 자리잡기,, 위층으로 올라가는 길은 꽤나 힘듭니다. 북카페인듯 한데 주말에는 책읽기 적합하진 않은거 같아요. 콜라보가 끝났는지 디저트가 좀 아쉬워졌네용 ㅠ', 42, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '밥먹고 아메리카노 한잔 마심 근데 남자 알바생분 왤케 서비스를 안하죠? 그딴식으로 할꺼면 알바를 안하는게 나은듯 리뷰보니까 알바생한테 불쾌함 느꼈다는 사람들 많아서 웃기네 아마 같은직원인거같은데 제가 메뉴 말하고 주문 끝날때까지 한마디도 안하는게 이게 맞나용ㅋㅋㅋㅋ 키오스크도 아니고 ㅋㅋ 인삿말이라도 하는 버릇 길러라야할듯 진짜 기분나쁘네 ㅋㅋ', 27, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '문학동네 회원이라 꼼마 자주이용하는데 홍대점은 처음이네요! 다른 지점에 비해 공간이 협소하지만 아늑합니다. 주말엔 사람이 붐벼서 평일에 오면 좋을것 같아요. 음료는 늘 맛있습니다.', 16, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '연남치고 가격이 괜찮아서 왔는데 맛이 좀 연한 편인 것 같고, 카운터 보는 여직원분은 서비스업에서 일하시면 안될 것 같네요.. 카페가 아니라 빈티지샵에 온 줄 알았어요. 표정도 말투도.', 40, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '건물이 너무 이쁜곳 연트럴파크 오다가며 늘 들러보고 싶은곳이었는데 진짜 외관만 이쁜㏊㏊㏊！ 딸기라떼가 진짜 별루였어요🤣🤣🤣 초코라떼는 진득진득 너무 달았구요 잠깐 추위 피하러 들어간 카페라ㅎㅎ 다음에는 서치해서 친절한 이쁜 카페 가기로 그래도 짧은 시간 잘 쉬다가 나왔어요 ( 참고: 연휴라 그런지 사람이 너무 많아서인지 몰라도 직원관리가 필요한듯 보였어요 화장실 더럽 ) 이런 리뷰 잘 적지않는데 ㅎㅎ 살짝쿵 그랬슴다 개취니 걸러서들 들으시고 평일에 가면 다를듯 하지만 바쁜날 간 저의탓😓 홍대에 숨은 이쁜 카페들 많아요 요기 사장님 이 글 좀 보셔야할듯ㅎ 바쁜날 직원 두명이서 일회용컵을 앉아서는 오랜만이네요', 42, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '‘일상을 여행처럼’ 카페꼼마... 홍대점을 방문했는데 겨울철 경의선숲길을 바라보며 너티풀레저와 레몬 얼 그레이 스콘과 함께한 따스한 시간~참 좋았답니다☃️', 122, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '크림 카스텔라는 남이 사주면 먹을 맛, 초콜릿 라떼는 내 돈 주고 사먹을 맛. 플레인 크림 수플레 카스텔라(￦7,000), 초콜릿 라떼(￦5,500). 수플레 카스텔라라는데 예전에 유행하던 대만 카스테라와 비슷한 느낌이 났다. 막 맛있진 않고 그냥 배를 채우는 용도로 먹는 느낌... 크림이 없었으면 얼마나 뻑뻑했을지 생각도 하기 싫다. 초콜릿 라떼는 섞기 전에 먹었을 땐 진하지만 좀 단 느낌이었는데, 섞고 나니 비율이 딱 맞았다. 초콜릿 맛이 진하게 나는 딱 맛있는 초콜릿 음료. 요즘 음료들 가격 생각하면 그리 비싸지도 않고 양도 적지 않았다. 얼음으로 양을 속이는 느낌도 없었고. 빨대나 머들러 같은 게 없다면 섞기가 힘들다는 게 굳이 꼽은 단점. 책과 함께 하는 공간이라서인지 시끄럽지 않아 재방문의사 있다', 26, 1, NULL, SYSTIMESTAMP);
