INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '카페 꼼마는 망원동에 있는 지점만 가봤는데 연남에도 생겼길래 가봤어요 연남카페거리까지 가려면 도보로는 꽤 멀어서 가기 애매했던 적이 많은데 이제 여기 가려고요 단, 주말 기준 사람이 엄청 많았고 좀 어수선한 분위기인 점 고려하면 좋을 거 같네요', 16, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '늦은 밤이라 디카페인커피에 얼그레이 케익.. 음~~케익 너무 맛있어요. 얼그레이 향이 입안 가득~~ 디카페인 커피도 특유의 향 없이 맛있네요', 89, 11, 'GOOD', SYSTIMESTAMP);
