INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '예쁘고 비싸고 맛난 디저트가 많아서 한번쯤 방문하기 좋아요 독특해서 선물하기도 좋습니다 종류 다양해요 홍대 놀러가면 카페꼼마 들려서 구경해보세요ㅎㅎ 비가 와서 잠깐 피신하러 왔다가 비주얼에 이끌려 포장하게 되었네요', 14, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '가을뷰가 아름다운 곳 연트럴파크 홍대3번출구나와 직진하면 보이는곳으로 약속장소로도 좋다 원두도 디카페인 포함 3가지 중 고를 수 있고 빵도 책들도 있다~~~ 하지만 많이 시끄럽다는 단점 ...... 좌석쪽으로 갈때까진 조용한 듯하지만 1,2층 모두 시끌시끌....ㅎㅎㅎ', 4, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '홍대나 연남 왔을 때 스벅이나 할리스 같은 프랜차이즈 카페 위주로 많이 방문하다가 외관 여우가 독특해서 방문해 봤습니다. 카페도 2층이라 꽤 크고 인테리어도 모던하면서도 메뉴도 다양해서 마음에 들었네요. 그래서 최근 연달아 방문하고 있습니다. 벌써 3번이나 왔는데 빵이랑 커피 맛도 모두 괜찮아서 이렇게 리뷰도 작성하게 되네요. 또 오후에 오면 일부 빵들 30% 할인도 적용되어서 저렴하게 먹을 수 있는 것도 좋습니다.', 103, 19, 'GOOD', SYSTIMESTAMP);
