INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '연남동에서 걷다가 너무 더워서 들어갔는데 전체적으로는 쏘쏘했어요 수박 스무디는 슬러쉬기계에서 컵에 담아주시는데 맛도 스무디보다는 슬러쉬느낌이었어요. 케이크는 쫀쫀하니 맛있었어요.', 34, 6, NULL, SYSTIMESTAMP);
