INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '음악이 커서 책 읽기는 솔직히 무리구요.. 그래서 인지 북카페인데 책 읽으시는 분들은 0명이곸ㅋㅋㅋㅋ 수다 떨러 오거나 작업하시는 분들이 훨씬 많으셨네요~ 커피는 맛있어요', 35, 5, 'GOOD', SYSTIMESTAMP);
