INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '시그니처 메뉴 치즈 플로트 고급지게 맛있어요 😊 친절한 응대도 인상적이고! 디카페인 변경, 얼음 제거등 세심하게 확인해주세요! 감사했어요~ 참! 여긴 디저트 버터도 좋은 거 사용해서, 정말 맛있어요 👍', 4, 10, 'GOOD', SYSTIMESTAMP);
