INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '매장은 넓으나 빈자리는 없었으며 포장하였습니다. 파리브레스트는 맛있었고 플랑바닐라는 제 기준 약간 느끼했습니다. 음료는 맛은 있으나 사진과 같이 양은 많지 않았습니다.', 34, 5, NULL, SYSTIMESTAMP);
