INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '오 뭐야 커피 맛있네요? 카페 꼼마 다른 지점은 커피가 별로였어서 큰 기대 안했는데.. 커피두 맛나구 공간도 편하고 차분해서 잘 쉬다 왔습니다 ㅎㅎ', 88, 13, 'GOOD', SYSTIMESTAMP);
