INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '에끌레르 맛있어요. 완전 달달달한 초코 맛이 치고 올라오다가 럼향이 달달함을 좀 달래줘요. 아포가토 커피 향 적당하고, 빵류 대체로 괜찮았는데 크루아상은 그냥 그랬어요. 타르트 마롱도 맛있는데 에끌레르의 강렬함에 약간 밀렸네요. 얀 쿠브레 메뉴는 다 맛있을 것 같긴 해요.', 27, 9, 'GOOD', SYSTIMESTAMP);
