INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '유명한 얀 쿠브레 빵들 중 궁금했던 퀸아망, 뺑오쇼콜라 두가지를 먹어보았어요. 역시 명불허전. 입에 착 붙고 풍부한 버터향에 짜지 않고 고소한 ~~~~ 강추 합니다 ~~', 81, 11, 'GOOD', SYSTIMESTAMP);
