INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '✅ 메뉴 : 🧸 딸기 & 히비스커스 소르베 ₩5,300 🧸 피스타치오 젤라또 ₩4,800 ✅ 서비스 : ✔️ 대면주문 ✅ 총평 : 상하목장 아이스크림이라 역시 맛있네요 ㅋㅋㅋ 딸기히비스커스 소르베는 추천해용. 피스타치오는 개인적으로 베라같은 느낌 좋아하는데·· 상하목장 피스타치오는 제스타일 아닌걸로..😭 P.S 화장실은 2층에있고 남녀공용에 딱 1칸이에요ㅋㅋ 남녀공용이라 좀 부담스럽네요ㄷㄷㄷ', 10, 2, NULL, SYSTIMESTAMP);
