INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '매장은 넓은 편인데 사람 언제나 많음 한정메뉴 자주 나옴 근데 한정메뉴 전시만 해놓고 소진됐다고 팔지 않음 에스프레소 종류가 점점 줄어들고있음 음료 맛있다고 생각했는데 점점 맛이 그냥저냥같음 논커피보다 커피가 낫다 디저트는 언제나 맛있음 이쯤되니 퀄리티 대비 가성비 좋음', 9, 6, NULL, SYSTIMESTAMP);
