INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '오며가며 가보고싶던곳인데 드디어 가봤네요. 커피도 맛있고 디저트도 너무 맛있네요. 디저트 가격이 사악한것만 빼면 다 좋네요^^;;', 80, 12, NULL, SYSTIMESTAMP);
