INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '디저트는 맛있는데 알바생들이 몹시 친절하지 않다 수준을 넘어서 기분이 나쁨.. 가격대가 있는 편이고 이름들이 다 어렵고 익숙하지 않다보니 이름이 조금 어려워서 제가 알바생분께 아지티스롤이라고 잘 못 말씀드렸는데 진짜 무시하는 표정과 말투로 이자티스롤 이여?? (+나만 그렇게 느낀게 아니였음) ++ 또 처음 보는 빵 종류들이 많아서 그냥 이름이랑 외관만 보고 골랐는데 이름표가 잘 못 놓여있었음 집에가서 포장한거 보니 내가 예상한게 아니였음 밑에 작은 설명까지 잘 보세요 그 빵이 맞는지…++타르트류 포장시 아이스팩을 해주시는지 저는 제 일정상 그리고 날이 추워서 아이스팩이 크게 무의미 할것 같아 상황 설명 드렸는데 계속 무시하고 본인말이 맞다는 듯 가르치려는듯  "이동하시는데 몇시간 걸리시는데요"라고 하는곳', 24, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '돈 아깝습니다. 아무리 비싼 동네라지만....수박스무디는 학교앞에 1~2천원주고 사먹던 슬래시같고 시럽맛이 너무 강합니다. 곡물스무디도 입구에 여름 특별 메뉴인 것처럼 소개해놨는데......너무 달았습니다. 7천원, 6천원 주고 사먹는데 종이컵에 주고... 다른 프랜차이즈 가서 먹을 듯.......비추....ㅠㅠㅠㅠㅠㅠㅠ', 14, 8, 'BAD', SYSTIMESTAMP);
