INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '포근한 마스카포네 바닐라 크림 위에 바질과 신선한 딸기를 사용해 상큼하고 달콤한 타르트 입니다. 플랑 바닐라 크게 달지 않고 푸딩 느낌입니다.', 17, 4, NULL, SYSTIMESTAMP);
