INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '홍대 디저트 맛집, 너트플레저 커피 진짜 너무 맛있어요!! 디저트들도 하나하나 다 맛있는데 넘 비싼게 큰 아쉬움이네요...ㅠㅠ', 13, 0, NULL, SYSTIMESTAMP);
