INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '픽업한 디저트는 맛있는데, 알바생 태도와 회사 정책이 너무 별로네요. 진열대에 9개?정도 있었는데, 위에 올려져있는 토핑이 하나하나 크기가 너무 다르길래 큰 토핑으로 달라고했더니, 큰토핑이 요번에 리뉴얼된 제품이고 얇게 뿌려져있는게 리뉴얼 전꺼라 이거 먼저 소진시켜야된다고 처음엔 안된다는거에요?ㅎㅎㅎ 어이없어서ㅎㅎ 그럼 미리 만들어놓은 리뉴얼 전꺼를 먼저 먹으란 소린데, 하나에 만원짜리 크기도 엄청작은 디저트 내맘대로 고르지도못하고(한눈에봐도 토핑 크기가 엄청 차이나는데), 리뉴얼되기 전 제품을 먼저 팔아야된다는 신박한 정책?과 알바생의 대처에 어이가 없었네요. 한소리했더니 그제서야 원하는걸 꺼내주는.....', 45, 7, 'BAD', SYSTIMESTAMP);
