INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '연남동일보러갔다가홍대역3번출구가까이카페에들어갔는데디저트도맛있고커피도맛있었어요 라떼도맛있구요달달구리가땡겨서타르트시켜서먹었더니너무맛있었어요평일이라도사람이쫌있었네요 담에또와보고싶어요', 50, 8, 'GOOD', SYSTIMESTAMP);
