INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '디카페인 커피가 없어서 석류에이드랑 유자 에이드 마셨어요~ 친구가 석류에이드가 더 맛있다고 하네요 ㅎㅎ 디저트는 안먹어보기는 했는데 맛있을 것 같아요 ^^', 216, 80, NULL, SYSTIMESTAMP);
