INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '지나다닐 때마다 보였는데 여기가 카페꼼마인 줄 몰랐네요😂 비싼 메뉴도 있는데 상대적으로 괜찮은 것도 있어요 적당히 달아서 저는 맛있었는데 남자친구는 입맛에 별로 안 맞았나봐요 2층 올라가면 좌석도 많고 공간도 넓어서 좋아요 근데 저는 카페인이 몸에 안 받아서 디카페인도 못 먹는데 논커피로 표시가 되어야 하는 메뉴에 디카페인으로 적혀있어서 헷갈렸어요 혹시 티에도 소량의 카페인이 들어가는 건지 헷갈렸는데 우유에 디카페인 적혀있는 거 보고 이해했네요...😅', 10, 4, NULL, SYSTIMESTAMP);
