INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '포장도 예쁘고 맛도 있음. 선물로도 추천! 슈는 만든지 시간이 좀 지난 느낌이 있어서 쪼끔 아쉬웠지만,, 기억이 가물가물하지만 크림 향도 특별했고 맛있게 먹음!', 38, 4, NULL, SYSTIMESTAMP);
