INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '커피와 디저트가 정말 매우 훌륭하게 맛있습니다~디저트 카페중 단연 최고입니다~시간대를 잘 맞추면 아주 좋은 자리에 앉을 수있습니다~시트론케이크는 최애입니다~👍', 71, 18, 'GOOD', SYSTIMESTAMP);
