INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '여자 직원분한테 주문받았는데 너무 친절하셔서 성함 물어볼까 했는데 다른 직원분들이 부매 님이라고 말씀하시는 거 보고 부매니저님 너무 친절해서 리뷰 작성합니다!!! 빵도 너무 맛있고 편하게 쉬고 갑니다!!', 44, 9, 'GOOD', SYSTIMESTAMP);
