INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '우연히 들렸던 곳이 었는데 디저트가 너무 맛있고 자리도 넓어서 좋았어요! 특히 저 여우그림케이크가 페로로 로쉐의 케이크 버전이라 맛있게 먹었네요😘', 36, 2, 'GOOD', SYSTIMESTAMP);
