INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '홍대입구역 3번 출구 나오면 바로 있는 예쁜 2층 카페! 특별한 디저트가 많은 곳이에요. 타르트 종류별로 다 맛있어요. 강력 추천합니다.~~!', 42, 4, 'GOOD', SYSTIMESTAMP);
