INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '첫방문인데 화장실도 괜챦았고 분위기도 괜챦았고 답답하지않아서 좋았어여 환기는 잘되더라구요 다만 일하시는분들이 친절하면 더 좋았을거 같아여 신랑이 불쾌했나보더라구요', 49, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '그냥 아무 생각 없이 들어갔는데 유명한 베이커리였던….! 늦게가서 남아있는거 거의 없었지만 구래도 6시 넘어가면 빵 종류들 30프로 할인해주더라구요 개이득♥️', 33, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '홍대입구역 3번출구에서 가깝고 매장이 커서 좋아요 1,2층 모두 좌석이 있고 깔끔한 인테리어가 좋습니다! 프랑스 버터로 만든 비에누아즈리류와 퀄리티 좋은 파티스리류가 있어서 홍대 디저트 카페를 찾으신다면 추천하고싶은 곳이예요. 아메리카노는 원두 선택이 가능해서 좋았고 밤기차 원두가 산미없이 고소한맛이에요~ 디저트와 즐기기 좋았습니다. 다양한 구성으로 만들어진 메르베이유가 대표메뉴인데 과하게 달지 않고 고급진 쁘띠갸또였어요. 정말 맛있어요! 헤즐넛 프랄리네의 퀄리티가 뛰어납니다. 에끌레르는 슈 부분이 질겨서 아쉬웠어요. 체리플럼 스무디도 상큼하고 시원해서 추천해요 ~ 대화하기 좋고 분위기도 좋습니다. 비오는 날 창가자리에 앉아서 연남동 구경하기 좋았어요', 20, 4, 'GOOD', SYSTIMESTAMP);
