INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '예쁜디저트에 사악한 가격이지만 확실히 맛있어요. 피넛버터,아몬드의 고소함 좋아하신다면 파리브레스트 왕추천! 내부도 쾌적하구 일단 앞에 뷰가 연트럴파크뷰여서ㅎㅎ 먼가 여유로운 느낌이 좋은것같아요! 다른 디저트도 먹으러 재방문의사 100% 화장실은 1층에 1칸있고 다먹고 트레이 넣어두는 곳에 정리하고 가셔야해요!', 39, 3, NULL, SYSTIMESTAMP);
