INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '가성비는 그렇게 좋은편은 아니지만 (베이커리가 비쌈 ㅜㅜ) 그래도 넓고 나쁘진 않았어요~~ 계단이 아슬아슬하지만 2층 올라가니 괜찮았고 화장실이 깨끗해서 좋았어용', 44, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '원두 선택할수 있어서 좋아요~^^ 직원분들 친절해요. 연휴라 사람이 많아서 정신없었는데 자리 선택 탁월ㅎㅎㅎ 자리도 넓고  대화하기 좋았어요.^*^', 22, 2, 'GOOD', SYSTIMESTAMP);
