INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '매장도 넓고 예뻐요. 다만 그만큼 인기가 많아서인지 주말엔 자리 잡기가 어렵네요. 자리도 많고 사람도 많은데 화장실이 단 한칸인게 흠이라면 흠 ㅠ', 31, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '싱겁기 그지 없던 티. 불편한 눈초리로 손님을 째려보던 음료담당 여직원. 전반적으로 불친절범벅. 가격대비 여긴 다시 안가려고요.', 33, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '테이블 자리 하나도 없어서 창가에 나란히 앉았어요. 6시 이후부터 디저트류 30프로 할인이더라구요. 저녁먹고 헤어지기 아쉬워서 들른 카페였는데 커피만 간단히 마시려다가 빵도 하나 먹었네요. 바삭하고 촉촉하니 맛있었어요.', 8, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '커피도 디저트도 맛있어요 그런데 테이블은 다리가 안맞는지... 뜨거운음료 취급하는데 테이블이 흔들려서 불편했구요. 테이블 청결관리가 잘되어있진않았어요. 1층 비어있는 테이블다수가  빵 부스러기, 흘린음료자국이 조금씩... 제가 치우고 앉았습니다.', 36, 8, NULL, SYSTIMESTAMP);
