INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '커피는 그냥저냥 괜찮아요 근데 에이드는 비추입니다 ㅠ 약간 다이어트 음료 같이 탄산 적고 티백으로 음료 만들어줘요 에이드 6,300원인뎅 ㅠ', 126, 24, 'BAD', SYSTIMESTAMP);
