INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '플랑 맛있어요! 탱글탱글해보여서 너무 젤리같을까봐 걱정했는데 입에 들어가는 순간 크림으로 녹아내리네요 특히 파이지가 버터향이 찐하고 식감이 너무 좋아요', 15, 0, 'GOOD', SYSTIMESTAMP);
