INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '오가다가 본 곳인데 오늘 처음 가봤어요. 디저트가 가격대가 꽤 있는데 맛있어요. 피스타치오 타르트 특히 너무 취향이에요! 견과류 러버한테 딱입니당', 39, 9, 'GOOD', SYSTIMESTAMP);
