INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '매달 디저트 메뉴가 조금씩 달라져요. 이번 9월 신상 피스타치오 타르트 먹으러 갔는데 느끼해서 취향은 아니었어요. 저번달 신상들은 이제 없더라고요 아쉽.. 에스프레소가 맛있어요. 체리 쇼콜라 라떼 맛있는데 체리 플럼 스무디는 맛이 아쉽네요. 플랑 바닐라는 취향이 아니었는데 얀쿠브레에서 다양한 디저트 먹어볼 수 있어서 좋아요.', 8, 9, NULL, SYSTIMESTAMP);
