INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '맛있고 이뻐요!!! 근데 타르트종류가 매우 비싸서 깜!짝! 놀랬습니다 손바닥만한게 만원이 넘는.. 어떤맛일지 궁금했지만 ㅎ 조금 합리적인 가격의 디저트를 선택했습니다 ㅎㅎ 비오는 순간 비 피하며 맛있게 잘먹었습니다! 티포트에 주는 허브차 아주 굳이었습니다', 49, 2, 'GOOD', SYSTIMESTAMP);
