INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '디저트 맛집같아서 갔는데 맛없어서 다 남겼어요 에끌레어 먹었는데 같이 먹은 사람이 싸구려 케이크 맛 난다고 하더라고요 타르트는 아직 안 먹어봐서 모르겠지만 맛있으면 좋겠어요 커피도 맛없었어요 에끌레어 시트 퍽퍽하고 딱딱했어요 + 와 코코넛 타르트 오늘 먹었는데 이것도 별로네요 비주얼은 진짜 멋진데 맛 밸런스는 …', 46, 6, 'BAD', SYSTIMESTAMP);
