INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '매장이 넓고 디저트 종류가 다양해요. 사실상 디저트가 메인? 개당 1만원 정도라 놀랐지만 맛있어서 화나는 맛..ㅎㅎ 비싸니까 맛있어야 ㅎㅎ', 13, 6, 'GOOD', SYSTIMESTAMP);
