INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '홍대입구역 3번 출구 근처 카페, 크고 예뻐서 방문했는데 분위기는 좋았어요~ 베스트라고 해서 집었는데, 타르트 이자티스가 10,500원이었네요🥲 맛은 그럭저럭 쏘쏘 아메리카노 양 많았어요', 46, 4, NULL, SYSTIMESTAMP);
