INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '가격이 좀 쎄지만 맛 있어요. 파리에서 가장 각광 받는 디저트 브랜드라고 하네요. 디저트가 너무 예쁘고 맛있어요.  디저트와 음료는 고급지고 맛있는데 인테리어나 좌석은 너무 평범하네요.그점이 좀 아쉬워요.', 60, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '한여름에 왔는데 카페 공간은 넓지만 생각보다 테이블이 많지 않고 에어컨이 닿지 않는 공간은 더워서 아쉬웠어요ㅠ 항상 주말마다 오고싶어서 들어왔다가 자리없어서 돌아가기 일수였는데 드디어 자리잡고 앉아봤어요 음료는 맛있었습니다! 디저트도 먹어보고싶었지만 점심 배터지게 먹은 후라 다음기회에...', 37, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '카페 콤마 여러 매장을 가봤지만 가장 지저분 했던곳. 화장실바닥 휴지 난리..  반납트레이 가득 야외테이블은 쏟은 음료를 닦고 앉아야 했던..', 27, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '연트럴파크 앞에 위치한 카페. 시원한 2층에서 밖을 보기가 좋고, 에스프레소가 맛있네요. 가게에서 파는 플랑은 여기서 처음 먹어봤는데 맛있게 잘 먹었어요. 디저트들이 전반적으로 가격대가 높긴 하지만 퀄리티가 좋아요.', 26, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '자주 와요 자리 넓고 맛있고 디저트 독특해요. 이번 신메뉴 나와서 맛보러 왔어요. 원래 몽블랑을 선호하지 않아서 빼고 피어아몬드, 시트론베르코코 주문. 시트론 베르 코코는 기존 시트론 타르트보다 훨씬 조화롭고 좋아요. 코코넛과 잘 어울리고 기존 제품보다 더 부드럽고 맛있어요. 피어 아몬드는 무난하고 맛있어요. 중간중간 씹는 식감이 좋아요. 에스프레소 쇼콜라는 언제 마셔도 맛있어요. 커피와 크림 모두 달콤하고 적당한 농도라 그냥 마셔도 좋아요. 에스프레소 로마노는 레몬 조각 끼워서 나오는데 즙 짜서 섞으면 나쁘지 않아요. 대신 레몬 조각 짜다가 씨도 같이 들어가서 귀찮음. 씨 없는 레몬 조각이면 훨 편할 듯. 에스프레소 주문하면 기본 얼음물이 아니라 얼음탄산수가 나오니 참고.', 12, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '연남 갈 때마다 지나가면서 한 번쯤은 가보고 싶은 카페였는데, 지인과 가볍게 이야기할 수 있는 카페를 찾다가 방문하게 되었어요 ~ 인테리어도 예쁘고, 디저트도 달달해서 좋았어요 ☺️', 11, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '영수증에 나오는 주소와 실제위치가 상이합니다 (영수증의 포은로 49는 합정점 위치에요) 종류 다른데서 보지 못하는 디저트 종류가 많아요 맛있지만 가격대가 높은 편입니다. 화장실 딱 하나 있어서 음료 나오는 시간보다 더 오래 기다려야해서 불편한 것 빼고는 뷰도 예쁘고 좋아요. 스탬프 쿠폰 전 지점 사용가능한 것 좋네요', 41, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '널찍한 창들과 연남동만의 힙한 분위기가 넘 근사했던 곳. 커피도 훌륭했고, 디저트도 특별했어요♡ 다만 커피양이 좀 적었다눈^^', 68, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '프랑스 정통 디저트 얀큐브레 착하지 않은 가격이지만 고급진 맛이 값어치를 합니다. 메르베이유의 저 여우 무늬, 너무 멋져요. 카페가 연트럴파크 볕좋은 곳에 있어서 커피와 이것 먹으며 앉아 있으면 절로 힐링이 됩니다', 416, 85, 'GOOD', SYSTIMESTAMP);
