INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '버터스카치 라떼 맛있어요. 어린이와 같이 방문해서 메르베이유를 함께 구매했는데 입맛에 맞지 않다고 해서 단x단 먹느라 힘들었다는… ㅋ', 29, 8, 'GOOD', SYSTIMESTAMP);
