INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '케익이 너무 맛있다는 소문을 듣고 딸래미와 방문한 얀 쿠브레 동교점~♡ 건물도 아기자기하고 뷰도 좋고 케익도 맛있었는데 왠걸 게다가 멋진 미술작품도 볼 수 있었다 화려하면서 신비했던 작품이 보이는 자리에서 한참동안 감상하면서 힐링할 수 있었던 시간~♡ 너무 좋았다 :)', 101, 22, 'GOOD', SYSTIMESTAMP);
