INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '비싸지만 정말 맛있어요 공간도 은근히 넓고요 작업하는 사람들도 많습니다 대신 넓은만큼 와이파이 신호가 안잡히는 자리가 있습니다', 112, 21, 'GOOD', SYSTIMESTAMP);
