INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '합정점만 이용하다가 얀쿠브레는 처음 왔어요. 매장이 굉장히 깔끔하고 고급스러워요. 쿠피는 여전히 맛있었고, 다음번에는 케이크 먹어보려구요 ~', 8, 6, 'GOOD', SYSTIMESTAMP);
