INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '오랜만에 디저트 맛집 찾은것 같아요:) 몽블랑 만다린은 몽블랑 좋아하시는 분들이라면 추천드려요. 샹티 크림과 위에 올라간 마멀레이드가 마롱 맛을 헤치지지 않고 조화로워 좋습니다. 파리 브레스트는 정석대로 만든 디저트 느낌이에요. 부드럽기보다는 거칠게 헤이즐넛 맛이 팍! 나서 좋은데, 보관 문제린지 크림이 많이 말라있어서 아쉬웠습니다. 타르트 시트론 베르 코코는 레몬 타르트를 크게 선호하지 않음에도 반했던 디저트에요. 레몬 향과 맛을 잘 살려서 상큼한 맛이 첫입에 느껴지는데, 마지막에는 코코넛이 부드럽게 감싸줍니다. 파운드 제품들은 냉장보관해서인지 실온 보관하렸다가 드시는것을 추천드려요. 바로 먹었을때는 퍽퍽하니 별로더라고요..ㅎㅎ', 60, 11, NULL, SYSTIMESTAMP);
