INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '사진에서 딸기 얹은 거 말고 나머지 두개 여기서 구매했는데 다 맛있었어요! 치케같은데 치케랑 완전 다른 맛 시트론 ~코코 뭔가 계속 손이 가는 맛..! 비싼게 문제다🥶🥶🥶', 38, 8, 'GOOD', SYSTIMESTAMP);
