INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '홍대입구역 근처 카페 중 규모가 큰 편이라 테이블이 많이 있어요 디저트가 맛있어 보였는데 식사후 방문한거라 커피만 마셨어요 커피 원두는 선택가능하고 맛이 괜찮았어요', 80, 15, 'GOOD', SYSTIMESTAMP);
