INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '외관도 너무 이쁘고 인테리어도 좋네요. 특히 디저트중에 메르베이유 모양도 그렇고 맛, 밸런스도 좋고 식감도 다양해서 추천합니다.', 3, 9, 'GOOD', SYSTIMESTAMP);
