INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '매장이 하얗고 커서 시원한느낌이었어요 에어컨도 빵빵하고 ㅎㅎ 사람이 많은데 좀 기다리면 금방 자리가 나는 편인거같아요 창가자리가 풀밭 구경하기도 좋앗어요', 8, 9, 'GOOD', SYSTIMESTAMP);
