INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '평일에오니 한적하고 좋아요 커피맛있고 특히 빵이 너무 맛있어요!!화장실도 깨끗하고 사진도 잘나오고 2층 뷰가 좋네용 빵맛집 🥐', 32, 9, 'GOOD', SYSTIMESTAMP);
