INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '제가 자리 치워달라부탁했는 컵만 치워달라는거 아니었어요? 거리는 인성 터진 몸에 타투 바른 여자 알바생만 아니면 완벽한 카페같습니다! 트레이 놓고간것도 그 손님보고 치우라고 시키고 자리 점검 안하나요? 더러운데 그냥 지나치길래 놀랐다니까 아 저는 컵만 치우라는건줄 알아서요 거리네요 이런 기본도 안되는 태도때문에 기분 잡쳐서 줄줄이 글쓸줄은 몰랐네요 ㅠㅠ 식당 가셔서 똑같은짓 당해보시면될듯', 2, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '디카페인커피가 없어 아쉬웠지만, 독특한 디저트류가 많아 위안이 되었다가 가격보고 또한번 깜놀ㅋㅋ29000원이라 써있는거보고 가격 다시 세봤네요.디저트 아닌 작품이 왜 여기있나요?', 65, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '디저트가 맛있어서 재방문 했습니다. 카라멜이 들어간 달달한 디저트만 주문했더니 입이 많이 달더라고요. 상큼한 디저트도 같이 주문하는걸 추천드립니다 ㅎㅎ 무스케익 전체적인 조합이 좋았어요!', 38, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), 'Very atheistic on the outside, inside was normal and kind of packed. Tbh a bit overpriced but opens until 10pm, later than most other non chain cafes.', 21, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '깔끔하고 고급스러운 외관이 연트럴파크에서 한눈에 들어옵니다. 따뜻하고 청결한 매장에 디저트들이 나열되어있는게 식욕을 자극합니다. 디저트종류가 다양하고 언제나 손님이많아 앉을자리 찾기는 조금 어려울수있습니다. 디저트는 취향이따르겠지만 대체적으로맛은 기본적으로 괜찮습니다. 다만 플랑바닐라는 커스터드가 오버쿡되고 젤라틴이 과잉으로 들어가 맛과 식감이 좋지않았습니다. 파리브레스트는 슈가 조금 눅눅했지만 필링의 너티함이 좋았고, 타르트 이자티스와 메르베이유는 모양만큼 괜찮았습니다. 대체로 테크닉도좋고 재료도 좋은것같으나 기본이 조금 부족한것같습니다. 포장재질도 고급지지않구요. 인스타에서의 비쥬얼만 보고 갔었는데 기대이하라 조금 실망스러웠습니다. 재방문 의사는 없습니다.', 6, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '아메리카노, 말차라떼, 리얼바닐라라떼 원두 선택이 가능하고 디저트 종류가 많은 곳 2층까지있구요 자리마다 간격 넓어 답답하 느낌없이 아주 좋았습니다', 25, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '옥수수라떼를 먹어보고싶었는데.. 일욜 저녁에 가니 품절이었습니다 ㅠㅠ 바나나 라떼는 인공적인 맛이었지만 버터스카치 라떼는 맛있었어요! 공간이 넓어서 자리잡기 좋았습니다.', 118, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '얀꾸브레의 특별한 디저트라 궁금해서 갔던 카페꼼마 음료맛은 그냥저냥 평범한 편이에요. 디저트는 버터듬뿍 견과다양 좋은재료인거 알겠는데 식감이 색다르고 짠맛이 좀더 강해서 호불호가 갈리네요. 평범하지 않은 맛', 29, 3, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '가족 생일, 친구 학교 졸업식 같은 기념일에 꼭 선물하는 메르베이유! 글루텐 프리여서 밀가루를 먹지 못하는 친구에게 선물했더니 맛있게 잘 먹어서 뿌듯했어요ㅎㅎ 생긴 것도 고급스럽고요:) 슈게트 크렘 바닐라는 이번에 처음 먹어보는데 눈이 확 뜨일 만큼 맛있고 달콤했어요. 앞으로도 계속 애용할 곳!', 24, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '검색했을때 건물외관과 디저트 비주얼때문에 방문을 했는데 메뉴 선택미스였는지 정작 제일 중요한 맛이… 아쉬웠어요ㅠㅠ 크림이 부드럽지 않고 텁텁한 느낌이였고 비주얼에 비해서 맛은 부족하지 않나 싶었습니다., 주말에 방문했는데도 매장은 여유가 있어서 테이블 이용은 편했습니다!', 40, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '좌석 많은 편이라 프랜차이즈 카페 가는 느낌으로 가요. 사람 많아서 시끄럽고 정신 없긴 해요. 그래도 통창이라 답답하지 않아서 좋아요', 51, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '건물이 이쁘고 공원 뷰가 멋져서 절로 들어가고 싶어지는 카페.. 여우 패턴 케잌, 종이백도 다 귀여워요😍 가격이 좀 높은만큼 디저트들이 고급스러워 보이는데 특히 초콜릿 들어간게 베스트인듯! 바삭바삭한 초콜릿과 아몬드 크림의 조화도 절묘해요. 잔두야 에스프레소도 좋았는데 초콜릿 맛집이네요.', 49, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
