INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '예뻐서 예전부터 와보고싶었는데 음료가 꽤 비쌌어요 그래도 맛있었어요 근데 2층 너무 소리 많이 울려서 대화하거나 책읽기는 좀 시끄러운 듯했어요', 39, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '경위선 숲길 공원을 처음 걷는 분들이라면 눈길이 자연스레 갈만큼 외관 모양이 이국스럽고 색상이 예뻐요. 일반 커피샵이라고 하기엔 베이커리 종류들이 다른데서 보기 힘든 특별한 메뉴들이 많았어요. 음료 종류도 커피 외에 티 종류, 에이드나 밀크티 종류도 다양했습니다. 고르는데 시간이 걸려도 직원분이 친절하게 기다려주시고 기다려주셨습니다.', 24, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '디져트 가격이 굉장히 후덜덜 합니다. 하지만 그만큼의 가치를 한다고 생각합니다. 이자티스 타르트를 먹었을때 카라멜 크림속에 조금씩 씹히는 카라멜 부분이 맛있었습니다. 하지만 화장실이 더러웠고 직원수는 많은데 뭔가 주분 받고 처리하는 속도가 느렸습니다. 디져트는 확실히 비싸지만 그만한 값을 하니 망설이지 말고 꼭 드셨으면 좋겠습니다!', 35, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '심플한 느낌의 깔끔함이 매번 눈길을 끄네요. 커피맛 좋았고 브레산도 과하게 달지 않아 맛있었어요. 디저트 가격은 후덜덜하지만 다 맛있어 보여 유혹적이에요. ^^', 42, 9, 'GOOD', SYSTIMESTAMP);
