INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '가격대는 좀 있는편인데 자주다니던 프랑스식 케이크집이 매장이전으로 ...부산으로 내려가서 홍대 왔다갔다하다가 눈여겨본집 첨으로 방문 맛있어요 좌석은 많은편인데 사람들도 많아서 좌석잡기 쉽지 않네요', 29, 4, NULL, SYSTIMESTAMP);
