INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), 'Great dessert and coffee. The deco and the view is nice. This place gets pretty crowded during weekends but it''s comfy during the weekdays.', 45, 9, 'GOOD', SYSTIMESTAMP);
