INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '홍대입구역 3번 출구에서 2분 거리에 위치한 민트민트한 건물입니당 오후 6시 이후에 방문하시면 베이커리류 30% 세일이라고 하니 참고하세요! 오틀리 그라니따는 귀리음료로 만든 얼음 슬러쉬에 아몬드 시럽을 섞은 음료입니다. 카페 추천메뉴라고 적혀있어서 먹어 보았는데, 맛나게 잘 먹었어요😆👍 다음에는 다른 디저트 메뉴 먹어보러 재방문하고 싶어요! 무엇보다도 직원분들이 모두 친절하셔서 더더욱 재방문 의사있습니다 :)', 7, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '홍대입구역 3번출구에서 쭉 직진하면 바로 있는 접근성 덕분에 사람이 항상 붐비는 카페인 듯 합니다. 커피와 티 메뉴 모두 나쁘지 않았습니다. 그런데 일부 디저트는 터무니없이 고가입니다. 맛이 없다고 평할 수는 없겠지만, 손바닥만한 케이크(과장 아닙니다..)가 11000원이었습니다. 디저트는 제가 산 건 아니라 감사하며 먹었지만, 배짱으로 장사를 하시는 곳이구나 라는 게 좀 느껴졌습니다. 조금만 걷더라도 핸드메이드로 맛있는 디저트를 파는 곳이 많으니 디저트메뉴는 다른 카페에서 즐기시길 바라요! 연남동 약속장소로는 추천합니다.', 5, 1, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '뭐가 그렇게 대단하길래 만원가까이 하나 했는데 입에서 보드랍게 녹는 크림과 카라멜 맛에 반했어요... 진짜 고급지고 선물하고싶은 맛..! 다음엔 에끌레어도 도전해보는걸로 .. 월요일에 왔는데도 사람 북적이던 곳', 42, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '외관은 이쁜데 안에 테이블과 의자는 평범하고 분위기 좋은 카페는 아니에요. 주말이라 더더욱 사람많고 그냥 일반 프랜차이즈카페 느낌이었어요. 커피는 원두 2가지중 선택가능했고 맛도 좋았으나 디저트가 크기도 작은데 너무 후덜덜한 가격이라 주문포기했네요. 조용한 카페 검색해 찾아간 곳이라 실망. 분위기나 조용한곳 찾는다면 이곳은 아니에요.', 46, 7, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '쿠글로프. . . . 너무 맛있어요🙊 오렌지향이 싸악 퍼지는데 겉은 달콤하게 바삭 안은 촉촉. . . 어? 어느새 다먹었. . . 아쉬워서 포크만 할짝할짝 다른 타르트나 케이크 등 디저트들도 많은데 비싸서 과감하게 패스했는데 쿠글로프 맛집이네요😁 인테리어도 예쁜데 사람이 너무 많아서 사진 찍을 타이밍 실패했어요ㅠㅠ', 6, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '디저트류가 맛있습니다. 단맛이 과하지만 인기많은 Flan à la vanille bleue, Tarte Isatis, Tarte citron vert 추천합니다.', 7, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '아메리카노는 밤기차?로 선택했는데 맛있어요!!!! 디저트는 기대했는지 모르지만 먹기 적당했습니당ㅎㅎㅎ 카페 위치가 좋은건지 사람이 정말 많네요!!! 고객들 많아서 정신없을텐데도 불구하고 직원분들이 진짜 친절해요 직원분들이 친절한곳은 또 가고싶어지는데 여기가 딱 그런 가게입니닷♡', 50, 0, 'GOOD', SYSTIMESTAMP);
