INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '좌석이 많고 맛있는 빵,디저트 종류도 많이 있어요 ~ 가격이 착한편은 아니지만 매장이 넓고 홍대입구 3번출구에서 멀지도 않아서 친구들과 만나서 가기 좋은거같아요 오늘은 포장해서 갔지만 나중에 오면 분위기가 좋아서 느긋하게 앉아 먹고싶네요', 30, 8, 'GOOD', SYSTIMESTAMP);
