INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '여기 대박이에요.. 맨날 맨날 가고싶어요 디저트 진짜 이쁜거도 많았는데 근데 넘 비싸고 고퀄이라.. 저 여우모양 빵 좀 보세요나중에 선물용으로 좋을듯 제 입에 넣기는 아까웠습니당 암튼 간식도 먹고 책도 읽고 데이트도 하고 냠냠굿 비오는 날 데이트 잘했어용 쵝오 ㅜ ㅜ', 45, 7, 'GOOD', SYSTIMESTAMP);
