INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '얀 쿠브레 디저트 중 메르베이유가 궁금해서 주문했구요. 헤이즐넛 크림과 초콜렛 무스가 완전 제 취향이었어요. 차향은 입안 가득 퍼지는 은은한 자스민 꽃내음이라 좋았어요. 창가 자리가 많아서 경의선 숲길이 시원하게 잘 보여요.', 15, 1, 'GOOD', SYSTIMESTAMP);
