INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '에클레어 해동이 잘 안된건지 좀 딱딱해서 살짝 아쉬웠지만 초컬릿 맛이 풍부하면서 참 맛이 고급지네요. 루이보스 바닐라 차도 맛있었어요. 인테리어도 깔끔하고 위치도 좋아서 경의선 공원 약속 잡기에 최적입니다', 20, 9, 'GOOD', SYSTIMESTAMP);
