INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '기대를 많이 했는데 기대만큼 전 맛있었어요! 근데 1층 계산대 분위기는 참 좋은데 2층은 꼭 기차타기전 대기실같은 분위기 엄청 어수선해서 쫌 당황스러웠어요 😭', 39, 1, NULL, SYSTIMESTAMP);
