INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '프랑스 디저트 카페를 서울에서 몇 군데 가보고 좀 실망했었거든요; 사실 대체로 그냥 그랬어요ㅠ 근데 여긴 두가지 모두 맛있네요ㅠ 산미있는 아아와 함께 먹으니 천국이 따로 없어요ㅎㅎㅎ 맛있어요 달콤하고 고급진 느낌의 프랑스 디저트 좋아하시면 추천해요 옆의 카페꼼마 커피도 아주 뛰어나진 않지만 디저트와 함께 하기 나쁘지 않아요 토요일에 오면 북적이지 않고 여유있는 디저트 타임을 즐길 수 있을 거 같아요 에끌레어가 솔드아웃인 게 아쉽지만ㅠ 여긴 또 오고 싶어요~', 63, 11, 'GOOD', SYSTIMESTAMP);
