INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '연남동 초입인데다가 아침 일찍 문을 여는 거의 유일한 카페라서 선택의 여지없이 들어감. 일단 깔끔한 인테리어와 널찍한 좌석 등 외관은 꽤 훌륭함. 메뉴는 프랑스식 베이커리 위주고 에스프레소 종류가 다양함. 음료와 디저트 가격은 연남동답게 매우 비싼편. 에스프레소 꼰파냐 5500원, 에끌레어 8500원. 맛이 있다면 이 가격이 아깝지 않겠으나 맛이 없음 ㅜ 특히 에끌레어 대실망… 그나마 친구가 주문한 아메리카노와 뺑오쇼콜라는 맛있어서 다행. 재방문 의사는 없습니다 X', 95, 24, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '사이즈보면 이게 4인용? 싶지만 한 입 먹고 느꼈습니다. 아 이건 6인용이다ㅋㅋ 왕큰ㅍㅍㄹ로쉐?아니면 어른용ㅋㄷ조이. 상콤한걸로 할까 고민하다가 다들 얀쿠브레 첫경험이라 시그니처로 골랐는데 초코 찐해서 커피랑 디저트로 좋았어요. 요즘 케이크 너무 비싸서 파티 케이크 대신에 선택했는데 너무 맛있게 잘먹었습니다.', 226, 100, 'GOOD', SYSTIMESTAMP);
