INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '직원분들이 너무 친절하셔요!! 손님도 엄청 계속 오는데도 친절을 유지하시고 커피고 맛있게 만들어 주세요!! 덕분에 기분좋은 음료와 디저트 먹고갑니다!! 감사합니다!! 신사동에도 얀쿠브레 있던데.. 거기는 안바쁜데 왜 서비스가 그모양이죠… 같은 회사 아닌가요..?? 좀 보고 배웠으면 좋겠어요… 왜 동교점이죠..?? 홍대점으로 해주시지… 여튼 동교점은 서비스 맛 다 너무 좋음!!!', 18, 6, 'GOOD', SYSTIMESTAMP);
