INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '디저트랑 커피가 맛있어요~ 내부 화장실 도 있어 편리해요 홍대입구 초입이고 규모가 커보여서 많이들 방문하는데…자리가 넘 협소해요 ㅠㅠ', 96, 22, NULL, SYSTIMESTAMP);
