INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '플랑 새로 나왔다해서 먹어봤는데 에그타르트 같은 부드러운 텍스쳐보다는 탱글한 푸딩같은 질감이에요. 바닐라 맛은 좋아요. 하지만 제 최애 메뉴는 파리브레스트.. 다음엔 파리브레스트 먹으러 또 갈래요.', 27, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '갑자기 밀크티가 땡겨서 둘어갔습니다. 들어가자마자 보이는 디저트가 눈길을 사로 잡았는데 가격이 후덜덜 합니다 ㅋㅋㅋ 밀크티도 가격이 후덜덜 합니다 ㅋㅋ', 26, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '바닐라라떼가 바닐라빈으로 되어있어서 엄청 달지 않아서 오히려 좋았다! 그리고 이자티스는 진짜 맛있었다.. 방문할때마다 디저트에 감탄..하고 갑니다!!!!', 21, 7, 'GOOD', SYSTIMESTAMP);
