INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '커피가격이 합리적이에요, 디저트, 빵류 맛있었어요. 사람이 많아서 자리 찾기가 힘듭니다. 그리고 안타깝게도 화장실 관리가 잘 안되었지만 그럼에도 또 가고 싶긴 합니다.', 127, 21, NULL, SYSTIMESTAMP);
