INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '우연히 들렸는데 커피,  디저트 맛집이네요. 요즘 커피 맛있기 쉽지 않은데 마지막 한 모금까지 좋았어요. 물론 디저트도 만점.', 90, 15, 'GOOD', SYSTIMESTAMP);
