INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '시그니쳐 파리 브레스트와 아메리카노 먹었음. 디저트가 달지 않고 맛은 있는데 많은 사람들의 의견처럼 가격이 비쌈. 인스타용으로 한번정도 방문할듯', 19, 9, NULL, SYSTIMESTAMP);
