INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '홍대에 얀쿠브레만한 곳이 없어요. 음료 맛있음 디저트 맛있음 자리 넓은 편 가격이 있어도 맛이 다 커버해줌 보장된 맛 아주 좋음. 빵도 저렴한 편이고 저녁에 할인까지 함 최고.', 42, 7, 'GOOD', SYSTIMESTAMP);
