INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '디저트는 전체적으로 너무 맛있고 고급지고좋은데 주문받는 태도가 너무 싫었습니다. 주문하는내내 기분이 너무안좋고 불쾌했습니다 서버의 불친절함 문제가 있지싶어요. 바쁜건 알겠는데 이건아니죠..', 21, 3, 'BAD', SYSTIMESTAMP);
