INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '바닐라 밀푀유는 좀 비쌌지만 맛이 황홀할 지경이어서 값어치를 한다는 생각. 얇게 구운 빵 사이 가득 있는 바닐라 크림은 지금껏 먹어본 바닐라 중 최고. 얇게 구운 빵과의 조화도 좋습니다 크로와상은 엄청 뚱뚱하고 큰데 역시 맛있고가격도 저렴', 8, 4, 'GOOD', SYSTIMESTAMP);
