INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '가격이 좀 비싸지만 디저트가 독특하고 맛있었어요 파리 브레스트랑 에끌레르 👍🏻 화이트템플 아이스로 마셨는데 향긋하고 깔끔했어요~', 46, 10, 'GOOD', SYSTIMESTAMP);
