INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '카페 외관도 내부도 넘 이뻐요. 홍대와 연남동 사이 위치도 굿이구요. 디저트계 샤넬값이라고 누가 그러던데 진짜 비싸네요. 그래도 파리 브레스트 예쁘고 맛은 있네요. 카페 꼼마와 콜라보한건지 아무튼 문학동네 북클럽회원이라 커피 50퍼 할인받았어요.', 18, 4, NULL, SYSTIMESTAMP);
