INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '견과류의 크리스피함, 단짠단짠, 헤이즐넛페이스등 온갖 맛있는것만 모아놓은 조합. 맛있다는 말밖에ㅠㅠ 아래 페스츄리에 보석같이 캬라멜땅콩이 숨겨져서 보석함 같은 느낌도 남. 다먹어보고싶지만 그러기엔 내 지갑이 너무 얇다ㅜㅜ', 37, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '음... 고급스러운맛이라는 얘기를 많이들었는데.. 그냥 살짝 쓰다느낄정도로 진한 견과류퓨레?크림과 ...결국 페레로로쉐맛..9처넌짜리 페레로로쉐에여 잘 잘리지도않아서 먹기 되게 불편했고.. 아무튼 그저 아쉽....', 33, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '파리브레스트를 파는곳이 잘 없어서 방문했습니다. 외국에서 파리브레스트를 즐겨먹다가 들렀는데… 맛은 있어요. 근데 가격이 너무 비양심적 이라서 글 남깁니다. 8,500원 받아도 무방한 가격인데, 10,400원을 받더라구요.  사이즈가 큰것도 아니고…. 헤이즐넛과 크림이 비싼건 알지만 너무 장사치 마인드네요. 재방문 안하고싶어요.', 44, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '뺑오레장과 에끌레어 정교한 만듦새와 맛이 완벽해요. 서울내에서 먹은 뺑오레장 중 베스트였어요. 베이커리류는 가격대가 아주 적당하고 케이크류는 값을 합니다. 리뷰에 가성비 얘기가 많은데 가격대비 너무 좋은 곳이에요.', 29, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '50개한정이었나? 포스터있길래 혹시나해서 아직 있냐고물어보니 있다하여 주문했는데 찍히는 가격에 솔직히 욕할뻔함.. 맛은..더 기대이하.. 웨이퍼롤 얇게 펴서 안에 바닐라커스터드크림 발린 평범하기 짝이없는 아는 그맛.. 가격에비해 너무 창렬하다 느낌 디저트 네..다신안가요', 18, 0, 'BAD', SYSTIMESTAMP);
