INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '라임이랑 깻잎이라길래 궁금해서 먹어봤는데 완젼×10000새콤 요거 먹을때는 좀 초코같은 달달한 음료 먹어야 조화로울듯한 아무튼 짱!시지만 맛있었다! 느낌 다음에는 메르베이유 꼭 먹어보고 싶어요~ 여우 무늬 너무 귀엽', 38, 4, 'GOOD', SYSTIMESTAMP);
