INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '디저트 너무 맛있어서 이틀 연속 갓어요ㅠㅠ 화장실이 하나라서 계속 줄서야해서 그거는 좀 불편한데 디저트 종종 사러갈 것 같아요', 88, 13, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '메르베이유 무스, 시트론 베르 타르트 포장했어요. 메르베이유 무스 속 헤이즐넛프랄린 진짜 진하고 깊어요. 초코무스와의 조합이 부드럽고 진하고 좋았어요. 시트론 타르트는 기대보단 많이 시고 한국오픈을 기념하며 한식재료인 깻잎을 쓴 새 메뉴라는 타르트는 기대 치고는 임팩트는 조금 약했던거 같아요. 정말 신것 좋아하심 사먹으세요. 기대보다 신선한 발견은 아니었어요 그리고 수요일 저녁 7~8시쯤 포장 했는데. 그때 홀에서 계산하던 ''염색한 단발머리 여직원''의 손님응대가 ''불친절하고 무성의 했던 것'' 때문에 적어도 그 시간대에는 다신 방문하고 싶지 않아요. 그 사람이 없는 시간대에는 한 두번은 더 갈 거 같아요. 유명한 셰프의 한국최초 지점인데.. 고객응대 교육에 신경 좀 써주세요..', 34, 2, 'BAD', SYSTIMESTAMP);
