INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '외관이 민트색이여서 예쁘고 눈에 띄어요:) 여우캐릭터가 마스코트에요! 크로와상이랑 뺑 오 쇼콜라 2900원에 주먹 4개만해요!(제 기준임) 아메리카노의 블렌드를 고를 수 있어서 좋았어요! 산미있고 깊은 맛(이름 기억 안남)이랑 고소하고 묵직한 밤기차 두개 중 고를 수 있었어요', 19, 10, 'GOOD', SYSTIMESTAMP);
