INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '얀쿠브레 인별 친구였는데, 갑자기 홍대에 매장이 생긴다해서 깜짝 놀랐던 나!! 오픈때 가보고 싶었지만, 사람들이 너~어~~무~~~ 많다는 소식에 엄두도 못내고 있다가 오후5시 클로징 시각 앞두고 기대안하고 들러본건데 그래도 다행히 맛볼것들이 있었다🥮', 15, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '와.... 정말..... 이렇게 맛이 없을수가..... 6000원짜리 애플피치에이드는 초등학교 앞에서 팔던 슬러시만도 못했어요... 시럽과 얼음맛..🥺 꼼마 커피는 원두가 동일한데, 여긴 커피도 맛이 없었어요....', 20, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '디저트 하나같이 예뻐요. 프랑스 현지 가격이랑 똑같다고 해서 비싸려나 했는데 홍대 빵집 가격대 생각하면 큰 차이도 없는 것 같아요. 디저트 도장깨기 하고 싶네요.', 83, 18, 'GOOD', SYSTIMESTAMP);
