INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '매장입구 들어서마자 보이는 쇼케이스… 예술이예요. 가격대는 높은 편이지만 그만한 가치가 있는 디저트들이예요. 유행 따라 비슷한 메뉴 만들어내는곳들과 차별성을 갖고 오래 오래 사랑받는 곳이 되길 빌어요!!', 4, 1, 'GOOD', SYSTIMESTAMP);
