INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '직원분들 전문성이 없어요 앞에 아무도 없는데 직원들끼리 얘기하느라 주문하는거 기다리고 뭐 물어보면 네? 하고 빤히 쳐다보시고…', 61, 13, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '프랑스 마레 지구 얀 쿠브레(Yann Couvreur)디저트 카페는 자연주의를 추구한다고 하는데 매장 분위기나 디저트 메뉴에 고스란히 담겨 있습니다. 얀 쿠브레 파티세의  절제된 디저트, 여우가 그려진 포스터에 마음이 낙엽처럼 내려옵니다.', 21, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '대표메뉴 2개+@먹었습니다 파리브레스트 맛☆☆☆☆ 맛있음 중간 크림은 헤즐넛 향이 강하고 느낌이 누텔라+생크림 섞은 느낌 가격☆ 겁나 비쌈 손바닥 반만한 사이즈인데.. 재구매? 안할것 같아요 내돈내고 먹기엔 아까움 핫폭스 오리지널 맛☆☆ 페스츄리 너무 바삭, 다 부서지고 딱딱함. 소세지는 다 탄건지 시꺼멓고ㅠ  일단 너무 짬. 밥도둑이 아니라 커피도둑 아니지 거의 강.도. 수준 가격☆ 겁나 비쌈 손가락2개 굵기에 한뼘사이즈 재구매? 안함 내돈이 아니라 남의 돈으로 사먹어도 아까움.. 남이라도 말릴듯 크루아상 맛☆☆☆☆☆ 맛있어요 폭신폭신 버터향 굿 가격☆☆☆☆나쁘지 않음 저렴하거나 가성비가 좋은건 아니나 아깝지 않음 돈값함. 재구매 의사 있음 특별한 날(소개팅식사후, 데이트 등)만 기분낼때 이용할듯', 54, 16, NULL, SYSTIMESTAMP);
