INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페꼼마 홍대점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '파리에서나 먹을 수 있는 얀쿠브레를 서울에서 먹을 수 있어서 좋아요. 파리브레스트 비주얼만큼이나 맛있네요. 커피는 무난. 다만 매장 운영이 아직도 좀 어수선한거 같아요.', 19, 5, NULL, SYSTIMESTAMP);
