INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '맛있는 커피가 먹고 싶어서 찾다가 발견한 카페예요 플랫화이트를 주문했는데 굉장히 크리미하고 진한 커피 맛이 기분좋아지더라고요 처음엔 부드럽고 중간은 진하면서 고소하고 끝맛은 커피의 여운이 살짝 남는 느낌이에요 단맛이 없어서 더 좋은 커피였습니다 분위기도 레트로하고 아늑해서 갑자기 내린 비와도 참 잘 어울리는 카페네요😊☂️', 0, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '크로플이 맛있어봤자 얼마나 맛있겠어라고 생각하신다면 착각이세요,,,,,!!!!! 진짜 맛있어요 위에 올려주시는 생크림? 주문 즉시 만드시는데 정말 부드럽고 느끼함 일도 없어요 그리고 크로플 반죽자체도 얇고 바삭하면서 속은 부드러워요 크로플 꼭 드셔보세요:) 하와이언 라떼도 코코넛 맛 달달하고 설탕제로인 라즈베리티도함게 즐겨보세요💞💞', 42, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '좋은 음악이 흘러나오는 분위기 좋은 곳이에요~ 커피도 너무 맛있고, 같이 주문한 음료들도 다 맛있었어요~ 특히 미라지커피 크로플은 진짜 최고예요. 로즈마리의 향이 은은하게 베인 크림가득에 크 크런치가 너무 잘어울리고 맛있는 크로플이었어요.', 29, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '#협찬 ✔️프렌치 클래식 크로플 : 수제크림이 두덩이나 올라가있는데 크로플, 로즈메리 향이 베이도록 놔두라는 철학있는 사장님👍🏻 크림이 뿌셔진 로투스 쿠키랑도 어울리고 쫄깃한 크로플과도 어울립니다. ✔️크림화이트 : 많이 달지 않은 크림이 킥입니다. ☕️❤️ ✔️라즈베리티 아이스 : 무설탕이래요. 논커피 메뉴로 괜찮네요. 특히 크로플 먹을 때 어울리는 음료 같습니다. 매장 2층도 코지한 바 같은 분위기이지만 3층이 정말 좋아요 참고하세요.', 40, 1, 'GOOD', SYSTIMESTAMP);
