INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '카페 분위기도 아늑하고 감성적이라 사진 찍기 좋고, 연남동에서 여유롭게 즐기기에 넘 좋았어요.카페 인테리어도 넘 엔틱하고 느낌있어요.☺️ 크로플 겉은 바삭하고 속은 촉촉한데 크림까지 푸짐하게 올라가 있어서 넘 맛있어요! 로즈마리향이랑도 넘 잘 어울렸어요. 청포도에이드는 상큼청량하고, 오트라떼는 고소하고 부드러워서 크러플이랑 잘 어울렸어요.', 71, 18, 'GOOD', SYSTIMESTAMP);
