INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '사장님도 친절하시고 세심하시고 디저트도 맛있습니다! 크로플맛집! 크림화이트랑 청포도에에드도 맛있어요 :) 다음에 또 오겠습니다!', 50, 3, 'GOOD', SYSTIMESTAMP);
