INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '여러가지 소품들과 가구들로 꾸며진 공간이 너무 멋졌고 틀어진 음악이 카페와 정말 잘 어울렸어요 그리고 갓 구워진 크로플 와아안전 맛있고 바삭 달콤 했어요 또 밀크 말차와 시그니처 아이스티를 먹었는데 시그니처 아이스티 완전!!!! 특별한 맛이었어요👍', 1, 8, 'GOOD', SYSTIMESTAMP);
