INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '분위기 아늑하고 엔틱한 감성의 미라지커피💓 2층,3층에 위치해있어요~ 크로플과 청포도에이드, 밀크초콜렛 이렇게 주문했는데 크로플이 정말 갓 구워나와서 따끈했고 달달한 크림+메이플시럽+쿠키가 입안에서 조화롭게 퍼졌어요💕 꼭~ 방문하셔서 미라지커피만의 갬성을 즐겨보시길 추천드립니다❣️😊', 355, 33, 'GOOD', SYSTIMESTAMP);
