INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '계획 없이 방문했던 미라지커피🤎 카페 인테리어가 멋지고 구경할게 많아요! 시끌벅적한 분위기가 아니라 대화하기 좋은 카페인거같고 무엇보다 커피가 맛있습니다☺️ 디저트류도 다양한데 사장님께서 엄청 정성껏 만들어주시더라고요! 다음엔 디저트와 함께 커피 한 잔 즐기러 오고싶어요👍', 25, 5, 'GOOD', SYSTIMESTAMP);
