INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '청포도 에이드랑 블루베리 파이가 잘 어울려서 좋았어요! 매장 분위기도 괜찮고 사진도 잘나와서 추천합니다! 맛있는 커피 찾으시는 분들은 꼭 방문하세요:)', 51, 16, 'GOOD', SYSTIMESTAMP);
