INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '사장님이 커피와 디저트에 진심인 곳이에요! 섬세한 라떼아트부터 직접 로스팅한 원두로 내린 커피까지 뭐하나 빠지는게 없는 미라지커피! 여기 블루베리 파이가 대존맛인데 특히 위에 올라간 시그니처 크림이 킥이에요 ϵ( ''Θ'' )϶ ♥', 338, 32, 'GOOD', SYSTIMESTAMP);
