INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '음악좋고 분위기도 넘 좋은데...크로플 미쳤습니당♡ 로즈마리향이 크림에 쏙 베여서 ㅠㅠㅠ 더 맛있어요. 크로플은 무조건 미라지커피로! 음료도 맛있고 직원분도 친절하셔서 강추드려요♡♡', 121, 20, 'GOOD', SYSTIMESTAMP);
