INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '로즈마리향이 은은한 크림이 매력적이에요 ! 바닐라아이스크림맛이라 달달해서 아아랑 너무 잘 어울렸어요 :) 커피도 쓰지않고 맛있는 쌉싸름함이었어서 너무 편안하게 잘 쉬다 왔습니다 👍', 28, 6, 'GOOD', SYSTIMESTAMP);
