INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '2층과 3층의 아늑한 인테리어가 강점인 카페☺ 2층은 3-4인석, 3층은 2인석 위주인데 친구들과 함께 방문해서 2층을 처음 이용해봤어요! 날씨 좋을 때 창문 열어놓고 창가 바람 즐기며 커피한잔하기 좋은 카페입니다☺☺❤', 31, 0, 'GOOD', SYSTIMESTAMP);
