INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '분위기 너무 좋아요 아늑하구 힙하구..💫✨ 사장님도 친절하셔서 자주 오고싶어요 특히 크림라떼 진짜 대존맛♥️ 늦게까지 영업하시는 것도 좋고 크로플 맛집이라던데 다음엔 크로플 먹으러 올게요 ㅎㅎ!', 86, 15, 'GOOD', SYSTIMESTAMP);
