INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '친구랑 2번째 방문했습니다. 오늘 같이 날씨 좋은 날에, 연남동 골목 2층에서 창문 열고 커피 마시니깐 좋네요. 크로플도 맛있고 인테리어 분위기 다 좋습니다.', 88, 18, 'GOOD', SYSTIMESTAMP);
