INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '지나가다 들렸는데 평일이라 그런지 한적하고 분위기 좋았어요~~ 매장도 2,3?층이라서 좋고 자리도 꽤 많은 것 같아요! 의자도 다 편해보이고.. 가까이 산다면 자주 왔을 것 같네요👍 배불러서 크로플은 못먹어봤지만 너무 맛있어보여요 굿', 50, 8, 'GOOD', SYSTIMESTAMP);
