INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '조용하고 아늑한 공간, 편안한 음악까지 모두 마음에 드는 곳입니다. 복잡한 연남동에서 이렇게 코지한 느낌의 카페는 처음인 것 같아요. 영업시간도 길어서 시간에 쫓기지 않고 대화할 수 있답니다! 연남동 분위기 좋은 카페를 찾으시는 분들은 꼭 들러보세요 :)', 46, 0, 'GOOD', SYSTIMESTAMP);
