INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '연남동 소개팅 연남동 데이트코스로 딱인 미라지커피 방문했습니다🙂 분위기도 힙하면서 조용한 느낌이라 특색있는 인테리어 즐기면서 대화 나누기에 좋았고요. 콜드브루도 진하고 맛있는데 시그니처 아이스티도 진하고 맛있어서 기성품이랑 다른 맛이었어요! 콜드브루랑 시그니처 아이스티 추천합니당ㅎㅎ 사장님도 친절하셔서 시간 잘 보내고 왔어요😆', 8, 0, 'GOOD', SYSTIMESTAMP);
