INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '일층은 레트로한 느낌이고 2층은 아늑하고 갬성있는 분위기에요. 디저트는 크로플이랑 음료는 밀크초콜릿이랑 청포도에이드 주문해먹었는데 다 너무 맛있어요. 특히 디저트 크로플 꼭 시켜드세요 👍🙂 넘 맛있습니다.', 28, 1, 'GOOD', SYSTIMESTAMP);
