INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '연남에서 아늑한 아지트 같은 카페를 발견했어요!! 커피 종류도 다양하고, 크로플은 바로 구워주셔서 바삭하게 먹을 수 있는게 매력이에요!! 소품 하나하 신경쓴 게 느껴지는 어딜 둘러봐도 예쁜 공간이에요. 2층은 개방감이 더 있고, 3층은 다락방 같은 분위기라 골라 앉기도 좋아요! 헤이즐넛 크림 콜드블루는 기분좋게 달달해서 식후 마시기 딱 좋더라고요. 모든 공간이 예쁜 카페👍', 26, 10, 'GOOD', SYSTIMESTAMP);
