INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '로즈마리를 저렇게 크림에 넣어놔야 맛있다고 하셔서 후숙(?)해서 먹었습니다!! 진짜 맛있고 바삭하고 크림 안느끼합니다!! 크런치쿠키+크로플+크림+로즈마리 박자가 완벽한 조화를 이룹니다!!!!!다들 여기오셔서 크로플은 무조건 드세요!!!!!!!!!!!!', 196, 29, 'GOOD', SYSTIMESTAMP);
