INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '매번 오게 되는 미라지 카페🥺 주변 친구들 , 고객님들께 항상 추천하느라 입이 아플 지경입니다 시그니처 아이스티 … 겨울 내내 기다렸는데 드디어 다시 나와서 너무 조아요😙🤍 아이스티 꼭 먹어보세요', 34, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '정말 좋아하는 카페에요! 🥹 혼자 책읽으러 자주 오는데 디저트도 맛있고 음료도 맛있어요!! 오늘은 다이어트 시작해서 ㅠㅡㅠ .. 브라우니 먹고 싶지만 참았어요•• 영국에 살 때 자주 먹었던 브라우니 맛이랑 똑같거든요!!🥹🫠 인테리어도 너무 이쁘고 무엇보다 매장 음악이 ••• 진짜 기가 맥히요🫶🏻 그리고 직원분도 너무 친절하시고 이쁘셔서 ,,, ㅎㅎ 🙊 항상 잘 챙겨주셔서 감사해요 🩵🩵 앞으로도 자주 올 것 같습니당 !! ✌🏻😍', 3, 8, 'GOOD', SYSTIMESTAMP);
