INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '미쳤습니다. 커피 맛을 위해 향시럽은 사용하지 않는다는, 커피에 진심인 사장님. 취향저격 분위기 속에서 너무 맛있는 커피와 함께 힐링하고 갑니다. 자주 올게요. 카페해 주셔서 감사합니다.', 4, 3, 'GOOD', SYSTIMESTAMP);
