INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '음료 디저트 다 맛있고 가성비도 좋아요. 공간도 엄청 깔끔하고 편해요. 그리고 무엇보다 사장님이 엄청 세심하고 친절하셨어요. 브라우니랑 블루베리파이 둘 다 추천👍', 7, 8, 'GOOD', SYSTIMESTAMP);
