INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '제 취향에 딱 맞는 밀크티 찾기 어려운데 너무 맛있네요 ㅎ 인테리어도 차분해서 데이트 오기 좋은 장소같습니다. 화장실이 안에 있어서 너무 좋아요!', 22, 7, 'GOOD', SYSTIMESTAMP);
