INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '특별한 음료와 디저트 메뉴가 다양한 곳이에요! 공간도 너무 예쁘고 음악도 좋고, 너무 친절한 곳이라 방문하면 기분이 좋아집니다. 크로플은 크림도 너무 맛있고 양도 많아서 특히나 추천이에요!', 71, 15, 'GOOD', SYSTIMESTAMP);
