INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '여기 분위기가 너어어어무 이뻐요!!! 조명때문인지 엄청 따뜻하고 아늑한 분위기에 의자랑 테이블 색이 알록달록해서 취향저격이에요💙 그리고 크로플 진심 존맛탱-!!! 꼭 주문하세여', 10, 1, 'GOOD', SYSTIMESTAMP);
