INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '와~ 홍대와서 크로플맛집을 발견했네요 기본인 커피는 당연히 맛있어서 디저트까지 맛있으니 자주 올듯요~ 시그니처커피인 하와이안커피 안달고 너무 맛있네요 최근에 라떼에 푹빠졌는데 정말 인생라떼발견! 잘생긴 바리스타 사장님도 친절하셔서 편히 맛있게 잘 먹고갑니다~', 51, 15, 'GOOD', SYSTIMESTAMP);
