INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '검색하고 왔는데 실제가 더 아늑해요~ 커피도 맛있고 사장님이 친절하심. 매장 청결도 너무 좋고 무엇보다 음악선곡이 너무 좋습니다☺️ 스피커가 비싼것같은데 소리가 너무 좋아효~ 담에 또 갈게요ㅎㅎ', 5, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '제 최애 크로플+밀크티 조합이에요 먹어본 밀크티 중 미라지 밀크티가 제일 맛있음🙆‍♂️ ---- 사장님 혹시 여기에 리뷰 남기면 보실까하여 남깁니다! 오늘 12시 반쯤 방문해서 크로플, 아메리카노, 밀크티 주문한 손님입니다 저희가 나갈 때쯤 실수로 컵을 깼는데 혹시 기억하실런지요ㅜㅜ 너무 당황해서 그땐 미처 생각을 못했는데 컵 금액 배상을 해야하지 않나 해서요 ,, ! 방법 댓글 남겨주세요 !!! 리뷰 겸 글 남기고 갑니다😭😭', 14, 10, NULL, SYSTIMESTAMP);
