INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '연남동 카페 중 가장 분위기 좋은 카페입니다. 두 층으로 이루어져 있어, 자리도 많아요. 카페 내부 가구들과 인테리어 소품들이 너무 이쁘고 먀장음악이 좋아서 쉬는 느낌을 받습니다. 데이트 코스로도 좋고, 혼자서 커피 한잔 하러 오기도 추천드려요. 디저트로는 브라우니와 크로플을 추천드립니다. 카페 내에서 만든 크림이 정말 맛있어요', 25, 0, 'GOOD', SYSTIMESTAMP);
