INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '길 지나가다가 예쁜 카페가 보여서 들어가게됐어용!! 올라가니 3층에도 자리가 있다고 안내해주셔서 너무 운치있는 자리에 앉을 수 있었어요!! 너무 친절하신거 같아요 🥹 아무리 예쁜 카페라도 커피가 맛있어야하잖아요? 커피가 진짜 !!! 맛있어요 😋 다음에도 또 오고싶어용 😽', 31, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '커피가 진하면서도 부드럽고 크로플 설명도 해주시고 크로플도 맛이 좋습니다ㅠ 위에 얹어진 크림이 느끼하지 않고 잘어울립니다!! 직원분과 사장님이 친절하시고 음악까지 딱 좋아요~~ 은은한 분위기의 조명까지🥹 최고', 68, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '연남동에서 카페 가고 싶다 하면 거의 무조건 생각나는 곳입니다. 사장님이 멋잘알 맛잘알 느낌이셔서 카페 분위기도 좋고 커피도 너무 맛있어요🥹 크로플 그렇게 좋아하지 않는데 여기서는 필수로 시키고 남김없이 싹싹 다 먹습니다. 카페인데 아늑하고 맛있다...? 안 올 이유가 없지 않나요?', 7, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '여자친구가 단골이라 이번에 같이 와서 커피 너무 맛있게 먹었습니다. 사장님도 매우 친절하셔서 편안하게 여자친구와 좋은 시간 보냈습니다. 😊', 32, 8, 'GOOD', SYSTIMESTAMP);
