INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '제가 이용하는 최애 연남동 카페입니다:) 맛도 좋고 분위기도 좋아서 연남동 오면 들리게 되네요😁😊 인테리어가 너무 이쁘고 고즈넉해서 좋아욤', 5, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '평일 저녁에 방문했어요! 2,3층 모두 이용할 수 있었고, 평일 저녁이라 한가해서 좋았어요. 내부는 앤틱한 조명에 은근 색채가 돋보이는 편안한 무드입니다. 시그니처 커피 2개랑, 커피만 시키기 아쉬워서 브라우니도 추가했습니다! 콜드브루라서 커피가 엄청 진하고 깊은 맛이에요. 브라우니는 산딸기잼이 신의 한 수입니다! 크림과 잼의 조화가 아주 좋아요! 다음에는 책 한 권 들고 혹은 아이패드에 영화 담아서 와야겠어요!', 18, 1, 'GOOD', SYSTIMESTAMP);
