INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '연남동에 이렇게 좋은 카페가 있었다니,,  2,3층 전부 카페라서 3층 공간 되게 멋있고 조용하고 대화 나누기 좋았어요! 사장님도 쏘 친절....🫰 커피랑 크로플은 말모 다 맛있습니다 !', 110, 20, 'GOOD', SYSTIMESTAMP);
