INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '프렌치 클래식 크로플  크로플이 부드럽고 크림이 부드럽고 달달해서 너무 맛있었어요😆 차가운 하와이언 라떼  코코넛향이 은은하게나는 부드러운 라떼였어요😊 헤이즐넛 크림 콜드브루  헤이즐넛 향이 은은하게 나면서 콜드브루 였습니다.', 10, 9, 'GOOD', SYSTIMESTAMP);
