INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '분위기깡패 매장 음악도 재즈풍 너무좋음 데코도 너무 좋음 생각정리하고싶을때오면 좋을듯 그런데 오늘따라 내앞에 헤어지는커플있어서 그들의대화를안듣기위해 어쩔수없이 이어폰끼고음악들음. . 연남동 이라 커피비싼건어쩔수없는듯 디카페인없어서 아쉽 두세시간만 이용해달라는문구도 아쉽', 51, 15, NULL, SYSTIMESTAMP);
