INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '밖에선 몰랐는데 3층에도 카페 공간이 있는 곳이예요. 첨에 2층에 들어갔을때 매장이 아담하네~ 했는데 아니었습니다ㅎㅎㅎ 하와이안라떼랑 콜드브루 마셨는데 기본적으로 커피가 맛있어요~ 그리고 크림도 아주 잘치시는ㅎㅎ 크로플이 이렇게 예쁘게 나오는 곳 첨봤어요. 크림 진짜 듬뿍인데 꼭 드셔보세요! 너무 맛있었답니다 *_*', 15, 1, 'GOOD', SYSTIMESTAMP);
