INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '분위기가 너무 좋은 카페예요!! 쇼파좌석이라 편안하게 앉을 수 있어서 좋았습니다 아이스초코 먹었는데 진해서 맛있었어요! 사장님도 완전 친절하셔서 기분 좋아지는 카페임니다', 9, 1, 'GOOD', SYSTIMESTAMP);
