INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '따뜻한 분위기의 매장 인테리어랑.음악이 인상적! 커피 쌉싸름하니 신선해서 맛나고요 창이 오픈되어있어서 살랑 부는 봄바람이 너무 조아요!', 39, 0, 'GOOD', SYSTIMESTAMP);
