INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '2층에 위치해 있고 분위기도 좋고 아늑하고 예뻐요! 너무 시끄럽지 않은 분위기라 딱 좋아요~ 커피도 맛있어요! 사장님도 친절하시구~ (연남동 주민은 할인도 해주셔요😊 헤헤) 동네 다른 커피집은 대부분 10시까지인데 여긴 11시까지라 넘 좋아요!', 14, 8, 'GOOD', SYSTIMESTAMP);
