INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '크로플 이렇게 맛있는 곳 처음이에여 >< 크림도 1도 안느끼하고 달달한게 좋아요! 커피도 매일 로스팅 하셔서 그런지 풍미가 남달랐어요 퀄리티 높은 카펜데 가성비까지><!!', 80, 13, 'GOOD', SYSTIMESTAMP);
