INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '카페 분위기가 제 스타일 입니다. 인테리어 마음에 들고, 나오는 음악도 전반적으로 마음에 듭니다. 커피는 올 때마다 플랫화이트 먹는데 정말정말 맛있습니다. 제가 느끼기에 사장님이 멋을 아는 분 같아요. 그래서 올 때마다 좋습니다.', 8, 6, 'GOOD', SYSTIMESTAMP);
