INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '카페가 2,3층으로 나누어져있는 특이한 구조인데 인테리어 너무 예쁘고 선곡도 좋아요!! 카페에서 보이는 거리 뷰도 예쁩니다🙌🏻', 6, 4, 'GOOD', SYSTIMESTAMP);
