INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '좌석도 너뮤 좋구, 분위기도 너무 좋아요. 이번에 3번째인가 방문인데 항상 만족하면서 돌아가요. 특히 여자친구가 너무 좋아해요ㅠ 연남동 데이트하실일 있으면 꼭 들러보세요', 15, 1, 'GOOD', SYSTIMESTAMP);
