INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '오랜만에 연남 놀러와서 분조카 찾다가 우연히 들렸는데 너무 좋아서 다음번에도 올 거에요 아메리카노 시켰는데 원두가 너무 맛있네요 부드러워서 원샷했어요', 6, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '미라지커피 가시면 크로플은 반드시!!! 꼭 드셔야 합니다. 크로플과 크림이 입속에서 정말 조화롭게 춤춰요!! 사장님도 정말 친절 하시고 공간의 경우 2층 3층으로 잘 나눠져 있습니다.', 28, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '홍대 위치하고 있는 미라지커피에 왔습니다. 추운 날인데 따뜻한 음료를 먹으니까 좋으네요. 인테리어도 예쁘고 커피 맛있어서 좋습니다. 크로플이 적당히 달다고 해서 기대 했습니다 ㅎㅎ 다음에 또 오도록 하겠습니다! ㅎㅎ', 85, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '디저트도 맛있었고 라떼도 맛있었는데 특히 라떼 아트에 감동받았어요 금손 사장님이 상당히 친절하셨고 내부인테리어도 상당히 이뻤어요 데이트장소 소개팅소로 강추합니다♡', 12, 3, 'GOOD', SYSTIMESTAMP);
