INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '크로플 찐 맛집 크림이 너무 맛있어요 거의 원조인 거 같은데 역시 다름. 오랜만에 갔는데 여전히 아늑하고 빈티지한 멋이 있는 카페 3층에는 대화하기도 좋아서 커플 데이트코스 커피도 맛있고 사장님이 너무 친절하세요', 4, 9, 'GOOD', SYSTIMESTAMP);
