INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '크로플 맛있어서 재방문하게 되는 카페에요! 크림이 존존맛이에요 추천입니당😋 인테리어도 아늑해서 친구랑 와서 수다 떨기 젛아요 ㅎㅎ', 22, 10, 'GOOD', SYSTIMESTAMP);
