INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '아기자기하고 분위기 좋은 카페에요! 주말이라 테이블이 만석이었는데 다행히 금방 자리가 나서 앉을 수 있었어요☺️ 디저트랑 커피도 맛있습니다!', 29, 10, 'GOOD', SYSTIMESTAMP);
