INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '커피 완전 맛있어요!!! 특히 크림화이트 커피에 있는 크림이 진짜 맛있어요 의자도 폭신하고 분위기 좋아서 편하게 쉬고 가기에 너무 좋은 카페예요', 41, 10, 'GOOD', SYSTIMESTAMP);
