INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '콜드브루랑 아아 시켜서 먹었는데 원두 어떤것 사용하시는지 너무 맛있었어요 규모가 큰 카페는 아니지만 아늑하고 분위기도 너무 좋아요! 의자가 폭신한 곳을 선호하는데 미라지는 소파가 좌석이 있어 편했습니다:)', 46, 4, 'GOOD', SYSTIMESTAMP);
