INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '미라지커피 크로플 맛집이예요,, 주문과 동시에 구워주시는데 자르는데 asmr 소리 같았어요,, 위에 올려져 있는 크림이랑 로즈마리의 향이 같이 어우러지면서 달지도 않고 맛있게 먹었어요! 그리고 커피는 좀 진한편인데 원두가 신선한게 느껴졌여요. 분위기도 너무 좋아서 데이트 장소나 모임 장소로 추천해 드려요~!', 31, 2, 'GOOD', SYSTIMESTAMP);
