INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '진짜 맛있고 양 많고 가격도 저렴하고 삼박자를 다 갖춘 카페에요. 나만 알고싶지만.... 사장님을 위해 널리 알리고 싶네요. 크로플이 진짜 맛도리인데 위에 올라간 크림이 진짜 독보적이에요. 고소하면서..여기서만 먹을 수 있는..? 그리고 공간도 우드톤이라 너무 제 취향입니다. 홍대/연남에 이만한 곳 없어요', 99, 23, 'GOOD', SYSTIMESTAMP);
