INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '프렌치클래식크포플 안 먹으면 바보,, 시그니처메뉴답게 정말 마싯슴,, 크림이 너무 달지 않아서 크로플이랑 잘 어울리는거 같아요! 커피는 탄맛과 쓴맛 중간인데, 호불호가 약간 갈릴 수 있을거 같지만 저는 호 입니다~ 정말 커피를 마신다는 느낌이 팍,, 들어요🍀 크리스마스 분위기가 물씬이라 연말 기분내기도 좋네요, 오늘 선택 나잇스🤳🏻', 19, 7, 'GOOD', SYSTIMESTAMP);
