INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '사장님 너무 친절하시고 분위기가 좋아서 데이트나 친구들이랑 놀러왔을 때 오기 좋을 거 같아요.. 인테리어도 예쁘고 고요한 감성입니다', 56, 13, 'GOOD', SYSTIMESTAMP);
