INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '분위기 좋은 연남동 아늑한 디저트 카페입니다! 감성 카페 답지 않게 음료 맛과 양도 많고 크로플이 존맛이에요. 크림  맛있고 양 많고 음료도 맛있고... 분위기 너무 좋은 3층 추천합니다', 96, 22, 'GOOD', SYSTIMESTAMP);
