INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '밥 먹고 근처 카페 괜찮은 곳 찾아보다가 왔는데 분위기도 좋고 사장님도 엄청 친절하셔서 너무 좋아요. 커피도 맛있고 주신 마카롱도 맛있게 먹었어요! 다음에도 연남동을 온다면 여기는 꼭 오고싶네요😊', 43, 0, 'GOOD', SYSTIMESTAMP);
