INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '크로플과 크림, 크런치가 너무 잘 어울려요. 찐 크로플 맛집 인정입니다. 인테리어가 아기자기 예뻐서 사진찍기도 좋았어요. 오래 머물고 싶은 카페예요.', 38, 10, 'GOOD', SYSTIMESTAMP);
