INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '분위기 좋은 이층카페랍니다. 아담하고 따뜻한 분위기라 포토스팟으로도 좋고 디저트 메뉴가 짱짱 유명하더라고요. 음료도 종류가 다양해 고르는 재미가 있었어용. 주문한 메뉴를 가져갈 때 여자분께서 설명을 친절하게 해주셔서 더 맛있게 즐길 수 있었습니다 😀☆', 43, 4, 'GOOD', SYSTIMESTAMP);
