INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '인테리어도 엄청 빈티지하고 예쁘고 좌석이 너무 편했어요! 사장님도 엄청 친절하시고 커피가 진짜 맛있습니다👍🏻 다음에 와선 크로플도 먹어봐야겠어요', 22, 9, 'GOOD', SYSTIMESTAMP);
