INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '카페 또 간 집이에요. 카페 맛집 많다는 연남동에서 2번 이상 온 찐 맛집 크로플 진짜 진짜 맛있어요. 크로 풀 위에 크림이 넉넉하게 올라가서 부드럽게 오래 먹을 수 있었어요. 그리고 여기 아이스티 진짜 맛있으니까 다들 아이스티 드세요. 뿅', 2, 8, 'GOOD', SYSTIMESTAMP);
