INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '분위기 좋은 디저트 맛집🎄❤️ 크리스마스 분위기 뿜뿜한 연남동 카페입니당 데이트 코스로도 너무 좋고 혼자 음악 듣고 분위기 만끽하러 와도 좋은 곳이에요✧ヾ(❀╹◡╹)ﾉﾞ♡ 여기오면 크로플은 무조건 먹기,,, 아이스크림인가? 싶었는데 달콤한 크림... 근데 하나두 안 느끼하고 부드럽고 달콤한 크림이라 왕왕 추천합니당👍👍', 9, 9, 'GOOD', SYSTIMESTAMP);
