INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '2층, 3층으로 나뉘어 있고, 카페 분위기가 좋아요. 주말 낮에 방문 했는데 사람도 그렇게 많지 않아서 여유롭게 즐기다 갈 수 있었어요! 커피 맛도 좋고, 대화하기도 좋아서 데이트 장소로 추천드립니다~~!', 25, 0, 'GOOD', SYSTIMESTAMP);
