INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '양도 많고 크로플에 로즈마리가 포인트.. 단맛 강한 크림 위에 툭툭 털어주면 향도 좋고 맛이 중화되는 느낌이었어요!크로플에 올라가는 크림이 안 녹아서 오래오래 바삭하게 먹을 수 있어서 좋았어요.💛 브라우니는 초코칩이 진짜 댕많아서 초코 좋아하는분들께 강추🍫 크랜베리 쨈도 상콤해서 안 물리는 맛👍 크리스마스 시즌 너무 잘 꾸며 놓으셔서 사진도 잘 나와요🎄❤️', 58, 11, 'GOOD', SYSTIMESTAMP);
