INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '늦게까지 운영해서 좋아요~ 커피도 맛있고 사장님도 친절하세요 음악이 듣기 좋고 차분하게 대화하기도 좋아요 집중력도 좋아지네요 즐거운 추억 만들고 갑니다 짱~👍', 15, 1, 'GOOD', SYSTIMESTAMP);
