INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '분위기도 좋고 소품 인테리어가 전부 마음에 들었던 고즈넉한 카페 미라지커피 ❤️ 친구와 검색해보고 왔는데 역시나 커피가 너무 맛있어요 맛있는 커피 드시고 싶다면 강추!', 3, 10, 'GOOD', SYSTIMESTAMP);
