INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '전에 왔을 때 다락방 같은 느낌이고 아늑했던 기억이 있어서 다시 왔는데 여전히 맛있는 크로플과❣️❣️ 따뜻하고 아늑해요☺️ 부드러운 크림과 로즈마리가 배여든 향이 너무 좋아요!! 커피랑 차도 맛있어요:) 담번에 또 올거에요✨️', 25, 2, 'GOOD', SYSTIMESTAMP);
