INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '사람 많은 핫플 숨겨진 핫플 카페였네여!! 티도 맛있고 크로플도 너무 부드러워요! 사장님도 친절하시고 분위기 좋은 따뜻한 카페네요🤎', 30, 10, 'GOOD', SYSTIMESTAMP);
