INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '홍대, 연남 쪽 오면 고민도 안하고 오는 이 곳...💜 노래도 좋고 인테리어도 이쁘고 맛도 좋습니다ㅠㅠ 다들 고민하지 말고 여기로 오세요:)', 30, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '갓 구운 크로플은 정말 사랑입니당 ❤️🥹 완전 바삭하구 달달해요 크림이 진짜 너무 잘어울려서 매일매일 먹고싶은 맛입니다 한겹한겹 느껴지는 크로플이라서 정말 맛있게 먹었어요ㅠㅠ 커피랑 조합 최공 매장 인테리어도 너무 좋구 카페 선곡도 너무 좋아서 오래 머물고싶은 카페입니다❤️ 크로플 꼭 드세요!!!!', 349, 95, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '여기 크로플이 정말정말정말 맛있어요!! 진한커피랑 바삭한 크로플이 정말 찰떡콩떡입니다!!! 꼭 드셔보세용!!! 인테리어도 예쁘고 연남동 최애카페가 될거같아요~!!', 44, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '✅️ 인테리어가 멋져요 🖼 ​ 아기자기한 소품과 은은하게 흘러나오는 음악, 아늑한 조명 덕에 연남동 데이트코스 뿐만 아니라 연남동 소개팅 하기에도 좋은 분위기의 카페에요 ❤️ ✅️ 음료의 퀄리티가 ''매우'' 좋아요 ☕️ ​ 라떼 아트를 해주셔서 음료를 받을 때부터 기분이 좋았으며 제 최애인 초콜릿라떼 뿐만 아니라 바닐라라떼의 맛 또한 훌륭했던 카페였어요 👍 👍 ✅️ 크로플이 맛있어요 🧇 ​ 이곳의 크로플은 잘 구워진 ''겉바속촉''의 정석이었으며 플레이팅부터 맛까지 수준급이었어요 👍 👍 ✅️ 서비스가 좋아요 🌟 ​ 음식을 수령할 때 메뉴 하나하나 자세하게 설명해주시고 친철하게 응대해주셨으며, 불편한게 없는지 물어봐주시고 음료를 들고 이동할 때 문을 열어주시는 등 세심한 배려가 돋보였어요', 89, 13, 'GOOD', SYSTIMESTAMP);
