INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '연남동에 위치한 크로플 맛집으로 소문난 만큼 정말!!! 크로플이 입에서 살살 녹더라구요 ෆ˙ᵕ˙ෆ 더말할것없이 정말 여심을 사로 잡아야한다!!! 여자친구에게 맛있는 디저트를 맛보게 하고 싶다!!! 하면 무조건 연남동에 위치한 <미라지커피> 매장을 방문해보세요 ㅎㅎㅎㅎㅎㅎ : )', 15, 8, 'GOOD', SYSTIMESTAMP);
