INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '빈티지 인테리어로 아기자기 귀엽고, 편안하고 차분한 분위기였어요 사장님께서 친절하셔서 머무는내내 편안했고, 무엇보다 커피와 크로플이 너무나 맛있어요! 꼭 방문해보시길 추천드려요 :)', 19, 8, 'GOOD', SYSTIMESTAMP);
