INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '분위기 너무 아늑하고 따뜻했어요!! 🫶🏻 대화하기에 좌석도 너무 편해서 좋았습니다 ㅎㅎ 인테리어도 예뻐서 연남동 데이트 장소로도 강추 합니당 ღ ღ ღ 숨겨진 연남동 카페 맛집이에여 !', 3, 8, 'GOOD', SYSTIMESTAMP);
