INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '넘 예쁜 공간이에요!!! 들어오자마자 맛있는 디저트 냄새가 나서 행복했어요 ㅎㅎ 음료도 맛있고 디저트도 맛있고 잘 있다가 갑니다! ❤️다음에 또 방문할게요 혼자오기에도 좋고 친구들이랑 오기에도 좋은 카페였습니다!!!', 14, 7, 'GOOD', SYSTIMESTAMP);
