INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '크로플을 좋아해서 크로플 맛집 검색하니까 나와서 방문했습니다 로즈마리와 크림이 잘어울리는 크로플이에요! 크림도 많이 달지않고 양이 많아요 바삭하고 커피와 잘어울려요 카페 분위기도 좋아서 사진도 잘나오고 평일에 방문하니 조용한 분위기라 편하게 있다가 나왔습니다', 9, 5, 'GOOD', SYSTIMESTAMP);
