INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '분위기 미쳤구요~ 음악도 센치하고 코지한 느낌이 좋아요ㅎㅎ 크로플 위에 크림 얹어주는데 로즈마리향도 향긋하고 넘 맛있었어요!!', 36, 4, 'GOOD', SYSTIMESTAMP);
