INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '음료도 정말 맛있고 크로플도 정말 맛있었어요!! 연말에 친구들이나 연인끼리 와서 수다 떨기 딱 좋은 카페 인거 같아요!! 사장님도 너무 친절하셔서 넘넘 따뜻하게 즐기고 왔답니당ㅎㅎ 강추 드려용!!', 20, 6, 'GOOD', SYSTIMESTAMP);
