INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '크로플이 맛있다고 해서 갔는데 진짜 맛있어요 재료를 안아끼시고 블루베리 파이 안에는 블루베리가 가득해요 어떻게 먹어야 맛있는지설명도 다 해주시고 인테리어도 예뻐서 사진정말 잘 나옵니다 또가고싶어요', 45, 6, 'GOOD', SYSTIMESTAMP);
