INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '2&3층이 카페라 자리가 꽤 많은 편이고 아늑한 느낌의 대화하기 좋은 카페입니다. 화장실이 남녀공용 하나고 약간 냄새가 난건 아쉽습니다.', 28, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '인테리어가 빈티지한 멋이 힐링 그잡채.. ❣️크로플 유행하기전부터 판매한 곳이라 풍성한 크림에 바삭한 크로플이 플레이팅이 엄청 예뻐서 맛과 멋 퀄리티가 기냥 미쳤어요!!! 커피도 신선하고 쓴맛하나 없는 진한맛이라 맛있었습니다ㅎㅎ  6500원 블루베이파이도 플레이팅은 몇만원 받으시는만큼 정성스럽게 내주십니다ㅎㅎ 1층 분위기 엄청 예쁜데 2층도 프라이빗하고 예뻐요 ㅎㅎ 프랑스산 스피커 좋은거라 음악이 빵빵하고 선곡도 죽여주는 카페라서 계절 바뀔때마다 새로운 인테리어 보러 놀러가고싶어요💕 사장님도 잘생기셨어요!', 7, 2, 'GOOD', SYSTIMESTAMP);
