INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '커피가 마시고 싶어서 근처를 배회하다가 마주친 미라지커피.하지만 막상 주문하려니 바닐라 밀크티라는 메뉴에 꽂혀 밀크티를 주문. 테이크아웃으로 주문했는데, 음료 기다리는 동안 내부엔 끊임없이 사람들이 오며가며 북적북적했음. 다른 식당 오픈런 해야되서 앉아서 먹진 못했지만, 인테리어도 느낌있음. (레트로와 맥시멀리즘 그 사이 어느 지점) 바닐라향 팡팡 터지는게 오랜만에 마셔보는 맛좋은 밀트티였음✨', 100, 21, 'GOOD', SYSTIMESTAMP);
