INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '진심으로 너무너무 맛있어요 연남동 죽순인데 미라지 커피가 제일 짱입니다 아 그냥 저 믿고 제발 가서 크로플 저거 좀 드세요 사장님도 너무너무너무 친절하시고 알바 언니도 너무너무너무 이쁘고 인테리어도 완전 감성 넘쳐요 ㅠㅠ 적게 일하고 많이 버세요 🩷', 22, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '분위기도 좋고 디저트도 맛있어요 커피도 엄청 진했구요! 저는 물을 더 요청해서 계속 타먹을 정도로ㅋㅋ 크로플 비주얼 이런 거 처음 봐요! 크로플 위 크림이 정말 맛있더라구요 지금도 생각나는 맛.. 방문 추천합니다 👍 남자 사장님 왕친절하셨음!!', 33, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '크로플 맛집 이라고 해서 왔는데 생크림과 크로플의 조화는 정말 미쳤음 ㅎㅎ 하와이안 라떼는 코코넛 라떼인데 커피의 진한 풍미도 느껴지면서 코코넛의 달달구리까지 극락임 엄마가 시킨 카페라떼도 엄마가 엄청 맛있다며 ㅎㅎ 이 집 커피 맛집이라며 ㅎㅎㅎ 디저트는 물론 커피까지 너무 맛있는 미라지 커피 또 방문 할게요 :)', 28, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '크로플 크림하고 조합 미춰써요!!! 크림 너무많아서 남긴게 아쉬울정도로 크림가득주시고 느끼하지않은 크림이라 크로플하고도 잘어울리더라구요🧡🧡🧡 브라우니두 두께대박😁😁 딸기쨈&크림에 달달함이 두배여서 넘 만족했고 힙한 인테리어도 커피한잔하기 좋았어요😍😍😍😍', 46, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '연남동 크로플 맛집으로 유명해서 다녀온 미라지커피 인생 크로플 찾았습니다. 크림이 너무 달거나 느끼하지 않고 로투와 바삭바삭한 생지가 잘 어우러져서 너무 맛있었어요 커피도 직접 원두를 갈아 내린다고 하시는데 약간의 산미와 진한 맛이 느껴졌어요 연남동 디저트 맛집으로 추천 합니다', 1, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '제가 진짜 사진을 못찍어서 죄송합니다 근데 이거 진짜 너무 맛있어요 나오자마자 친구랑 게눈 감추듯이 말도 안하고 푸파했어요 원래 달달한거 잘 안좋아하는데 이거 물건이네요. 엄청 달지않은데 계속 먹게되네요.. 말차라떼도 녹차 맛 잘 느껴지는 깊은 맛이에요 추천합니다 😝', 14, 9, 'GOOD', SYSTIMESTAMP);
