INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '사진에 담지는 못했지만 커피와 커피잔이 예쁩니다. 맛도 좋았어요. 적당히 시큼한 맛으로 시작해서 고소함이 올라왔다가 부드럽게 마무리 됩니다.', 4, 6, NULL, SYSTIMESTAMP);
