INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '크로플이 정말 고퀄리티고 맛있어요. 크로플이 고소하고 바삭해요. 위에 올라가는 크림도 듬뿍이라 부족하지 않아서 좋았어요.   블루베리파이도 진짜 이제까지 먹어본 파이중에 제일 맛있었어요. 연남동 디저트 카페로 추천해요. 음료도 좋았어요.', 29, 9, 'GOOD', SYSTIMESTAMP);
