INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '이 크로플이 너무 맛나요ㅜㅠㅠㅠ 혼자 와서 작업하기도 좋고 둘이오셔서 수다떨기도 셋이오셔서 나눠먹기도 좋은 곳이예욯ㅎ♥️♥️♥️', 45, 8, NULL, SYSTIMESTAMP);
