INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '커피도 맛있고 디저트도 맛있는 곳 !!!!! 크로플 지금껏 먹었던 것 중 제일 맛있는 듯 해요. 특히 위에 올라가는 크림!!!! 전혀 느끼하지 않고 너무 맛있었어요~! 커피는 라떼 시켰는데 조금 진한 편이었습니다!! 원두가 중강배전? 원두 이상을 쓰는 것 같아요. 참고하세요~', 33, 10, NULL, SYSTIMESTAMP);
