INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '분위기 좋고 크로플, 커피가 맛있는 카페💛 연남동 올때마다 자주오는 카페인데 직원분도 친절하시고 크로플이 아주 아주 맛있어요.~! bgm이 좋아서 일하거나 책읽기에도 좋은 곳입니다.', 50, 5, NULL, SYSTIMESTAMP);
