INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '연남동에 있는 카페 미라지. 디저트류가 플레이팅이 잘 되어 나온다. 커피도 마실만하다. 가게는 2층, 3층. 2층은 메뉴가 나오는 곳이라 테이블이 몇 개 없는데 대신에 3층은 제법 안락하다. 그치만, 가게가 큰 편이 아니라 사람들이 많아지면 북석거리게 되어 좀 불편하다. 여튼간에 인테리어도 괜찮고 특별한 디저트류도 있고 연남동에 와서 간단히 커피나 한잔하러고 한다면 가볼만하다. 어딜 가나 사람이 많으니 말이다.', 35, 9, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '분위기도 좋고 사장님도 친절하셔서 넘 만족스러웠습니다! 아아 처음 마셔보는 맛이었는데 새롭게 맛있었습니당 연남에 늦게까지 하는 카페 거의 없는데, 요기는 늦게까지 해서 좋았습니당〰️😋', 65, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '벌써 다섯번은 넘게 방문했네요! 분위기가 따뜻하고 친절하세요✨️ 하와이안라떼를 먹었는데 베트남에서 먹은 코코넛커피같았고 달지않고 진했어용', 4, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '크로플 넘 맛있어서 한 번 더 시켰는데, 음료가 부족하신거 같다고 아이스티 서비스로 주신 사장님 넘 감사해요🥺 덕분에 맛있게 잘 먹었어요!! 콜드브루 블랙은 묵직하면서 다크초코 맛이 나는데 취저네요~ 크림화이트는 달지 않고, 진하고 고소해서 넘 맛있어요. 다음에 또 올게요😄', 0, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '라떼아트는 예뻤지만 핫초코와 핫 말차라떼가 다 식은 채로 미지근하게 나왔어요. 날씨도 추워서 따끈하게 마시고 힐링하고 싶었는데 말예요...직원이 한명도 아닌데 주변 정리 해야한다고 음료도 한참 늦게 나오고 2층 계단이 가파르길래 음료 좀 받아서 올라간다고 하니 올라갔다가 부르면 다시 내려오라하고...준비가 늦어져서 그렇게 대기시키는 건 십분 이해하지만 한참 기다려 나온 음료가 다 식어있으니 돈만 비싸다는 생각 밖에 안들었네요. 지인 추천을 듣고 친구 데리고 갔는데 아주 민망했습니다; +답변이 황당해서 남깁니다. 첫방문에 이 카페가 핫초코도 미지근하게 내는지는 모르는 일이고요. 방문했을 때 웨이팅 인원 없었고 음료 받아가려 잠깐 앉았을 때 예약석이니 2층에 올라가서 대기해달라 양해를 구하셨음 이해했을겁니다.', 7, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '카페라떼 마셨는데 진짜 맛있어요… 카페라떼 마시러 또 오고 싶을 정도!!! 그리고 바쁘신데 뚝딱뚝딱 혼자서 고군분투하시는 모습이 슈퍼맨 같아요.', 3, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '미라지 커피 진짜 분위기 짱이에요 여기 평일 점저 때와서 전세낸 것처럼 쓰세요 ! 제발요 여기 망하면 안돼 너무 좋아 가즈아 ! 디저트도 맛있어요 ㅎ', 110, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '근처 식당 들렀다가 우연히 가게된 카페인데 찐이었습니다! 커피가 너무 맛있어서 플랫화이트만 두잔 마셨어요. 다른 음료도 맛보고 싶어요. 크로플도 정말 맛있었고 친절하신 사장님의 프로패셔널함이 느껴졌어요. 분위기도 좋아서 오랜만에 만난 지인과 좋은시간 보냈습니다. 커피마시러 또 가고싶은 곳이에요.', 61, 16, 'GOOD', SYSTIMESTAMP);
