INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '연남동크로플맛집 여기에요..🖤 몇년 전부터 종종 오던 곳인데 오랜만에 왔는데 여전히 맛있네요!! 인테리어도 힙하게 이쁘고 카페가 크진 않은데 2층 3층 나눠져있어서 편해요. ㅎㅎㅎ 크로플 진짜 맛있어요!! 위에 크림도 달달하고 비쥬얼도 좋고 다음에 또 올게요😆', 40, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '크로플 맛집에 음료도 맛있네요••❤️ 무엇보다도 분위기가.. 사장님 선곡이 미쳤어요 ㅎㅎㅎ 노트북 작업하기에 무엇보다도 좋은 환경..❤️ 하나하나 섬세하게 신경쓰신게 너무 티가납니다🫧 아지트같은 곳이에요!', 33, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '괜히 “연남동 크로플 진짜 맛있는 미라지 카페”인 게 아니네요. 라떼도 너무 예쁘고 캐모마일 티 처음 먹어봤는데 너무 맛있게 먹었습니다:) .. 우연히 들린 카페였는데, 200% 만족해서 악뮤 노래 부를 뻔 햇서요 ..~ 크리스마스 느낌도 낭낭하고 자리도 넓어서 다들 연남동 가시게 된다면 꼭 방문하시길 ^!^ 사장님도 짱친절 그 잡채', 27, 6, 'GOOD', SYSTIMESTAMP);
