INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '메뉴 하나하나에 사장님의 연구가 들어간게 느껴져요. 혼자서 직접 만드시고 서빙하실때 메뉴에 대한 설명도 자세하게 해주십니다. 정말 친절하신데 부담스럽지 않게 대해주셔서 예쁜 공간에서 편안하게 있을 수 있고 음악 선곡 또한 카페 분위기랑 너무 잘 어울려요.', 23, 2, 'GOOD', SYSTIMESTAMP);
