INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '진한 콜드브루 커피와 환상적인 디저트에 하모니를 맛보고 싶다면 연남 미라지커피로 오세용~ 매력적인 인테리어에 퐁당~ 맛있는 디저트와 커피음료에 퐁당~ 디저트 다이브하실래용~ 즐거운 시간 보내고 갑니당~^^', 29, 7, 'GOOD', SYSTIMESTAMP);
