INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '분위기 너무 좋은 카페네요!!!!!! 소파도 편안하구 노래도 잔잔하고 음료랑 디저트 맛도 좋습니당 사장님이 메뉴 설명도 해주시고ㅎㅎㅎㅎ차분하게 머물고 싶은 곳입니다,, 취향저격 🫶🏻', 49, 7, 'GOOD', SYSTIMESTAMP);
