INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '카페 조명이 넘 예뻐서 사진도 넘 잘나오고 레트로한 소품도 많아서 포토스팟이 많아용💞💞 사진찍고싶은 마음 뿜뿜!! 3층엔 좌석 많고 그루비한 음악이 나와서 멍때리면서 기분좋은 느낌...❣️❣️ 연남동 크로플 맛집답게 크로플도 넘 맛나고 커피도 완전 굳굳><', 9, 10, 'GOOD', SYSTIMESTAMP);
