INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '여기 크로플맛집 음료맛집 분위기맛집 비지엠맛집이네요  매장이 힙하구 디테일하나하나 신경쓰신 게 느껴져요! 의자도 편하고 조용하게 얘기하기 아주 좋습니다!! 사장님 친절하시고 훈남이세요', 86, 12, 'GOOD', SYSTIMESTAMP);
