INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '나만의 아지트 같은 공간으로 너무 편안하고 아늑한 공간이네요~~~ 크로플은 찐찐찐맛탱이에요 ㅎㅎㅎ 크로플 위에 크림이 정말 달지도 않고 느끼하지도 않으면서 로투스 가루까지 너무 완벽합니다!!! ㅎㅎㅎ 친구와 먹는내내 감탄했다눙,, 미라지콜드브루도 직접 로스팅해서 그런지 깊은맛이나요 ㅎㅎ아이스티도 더운 여름철에 시원하고 상큼하고❤️❤️', 29, 2, 'GOOD', SYSTIMESTAMP);
