INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '비오는 날 미라지 오히려 좋아! 분위기도 좋고 사진도 잘 나와요:) 조용한 분위기에 어울리는 음악들도 좋구 커피랑 크로플도 존맛 ㅜㅜ 그리고 사장님께서 너무~ 친절하세용!', 5, 3, 'GOOD', SYSTIMESTAMP);
