INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '여기 진짜 두번 세번 가세요!! 사장님이 신경쓴 인테리어가 너무 감성있고 어느 공간을 찍어도 예쁩니다 연남동에 이런 카페가 있다니..무조건 재방문 할거에요 커피도 밀크티도 맛있었고 크로플이 진짜 짱맛있으니까 꼭 드세용🤎 #연남동크러플맛집', 26, 5, 'GOOD', SYSTIMESTAMP);
