INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '아이스티 있는 카페 찾아왔는데 시그니처 아이스티는 처음 봤어요 ! 허브랑 레몬이랑 가득 있는데 넘 맛있어서 1리터 마시고 싶네요 ㅎㅎㅎ', 67, 11, 'GOOD', SYSTIMESTAMP);
