INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '사장님의 서비스는 최악이라 재방문의사 없음. 아래같은 이유로 추가주문하려다가 기분이 상해 카페옮김 1. 3층짜리, 층마다 홀이작고 계단많음 2. 자리안내와 동시에 일행들 언제오냐고 집요하게 물음..말안하고 그냥가는사람들있다며.. 바꿀 수도있는거 아닌가? 3. 바닐라 밀크티는 먹어본 밀크티중 최악이라 따로 시럽달라하니 설탕안쓰는 어쩌구.. 맛은 없어도 건강에 좋아야,,? 4. 실내가 더워 에어컨 틈.. 작동하지말라는 안내문구가 전혀 없었으며 맘대로 조작하지말라고 화냄; 실내온도 조절 못한 사장 잘못아닌지.. 손님한테 더웠냐며 걱정이 우선은 아닌지.. 보란듯이 손님을 혼내자마자 서툰 글씨체로 이제야 작동금지 포스트잇?을 붙임 5. 친구들끼리 선물교환중에 그걸 먹을거냐며 물음.. 물론 전혀 먹을 생각없었음', 8, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '바닐라라떼 겁나게 맛있구여 시그니쳐 아이스티 존맛탱입니다. 크로플은 로즈마리가 크림의 잡내를 잡아주어 연남동 디저트맛집이에요 연남동카페 미자지커피 강추입니다', 21, 9, 'GOOD', SYSTIMESTAMP);
