INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '주말 연남에 이런 카페가?! 정말 한적한 연남거리를 제대로 표현한 카페인 것 같아요 여유로운 분위기에 감각적인 노래가 아! 내가 연남동을 왔구나! 라는 느낌을 제대로 느끼게 해주는 것 같아 기분이 좋네요 좋은 날과 좋은 공간에서 잘 즐기고갑니다 쿠키가 안된다 해서 크로플을 시켰는데 크로플은 꼭 드셔보셔야해요!! 촠촠함이 남다르고 크림과의 조회가 너무 좋습니다 로즈마리가 향을 잡아줘서 너무 완벽한 플레이팅이였어요 다음에 다시 올 의사 넘칩니다 연남놀러오면 꼭 한번 가보세요!', 43, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '일단 분위기 너무 좋아서 연남동 데이트 장소로 강추해요! 제일 중요한 커피와 디저트가 정말 맛있어서 대만족~~ 브라우니 꼭꼭 드셔보세요!! 그리고 사장님 진짜 친절하셔서 감동이었어요. 정말 좋은 시간 보냈어요. 강추합니다!!!', 1, 10, 'GOOD', SYSTIMESTAMP);
