INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '자리 편한 카페 찾는 분들께 강추드립니다! 요즘 카페 의자 불편한 곳이 넘 많은디 여긴 의자도 푹신하고 분위기도 넘넘 아늑해요☺ 크로플이 메인 메뉴인데 크림이 전혀 느끼하지 않고 jmt입니다.', 34, 1, 'GOOD', SYSTIMESTAMP);
