INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '약속시간 중간에 있을 곳을 찾아헤매다가 만난 카페. 다 가보지 않아 연남동의 수많은 카페중 여기가 제일 좋아! 라고 할 수는 없겠지만 혼자 무료하게 보낼 수 있었던 시간을 행복하고 즐겁게 보낼수 있게 해준 곳입니다 혼자 조용히 앉아있을 곳이 있어 더 좋았던거같아요', 44, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '크로플과 시그니처아이스티 청포도에이드! 와.. 너무 맛있어요~~~👍🏻👍🏻❤️😊 분위기도 좋고 애정가득한 카페라는게 느껴집니다 배고팠는데 진짜 나오자마자 너무 맛있어서 흡입했어요! ㅋㅋㅋㅋㅋ 크로플완전 겉바속촉에 위에 직접 만든 크림도 최고고 음료들도 너무 맛있어서 깜짝 놀랐습니다~~ 다음에 또 놀러갈래요!!!', 43, 2, 'GOOD', SYSTIMESTAMP);
