INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '크로플 맛집답네요,, 크로플 너무 맛있구 시그니처 아이스티도 맛있어요! 인테리어도 너무 멋져요! 연남동에 화이트앤 우드 인테리어 질리는데 독보적인 컨셉 이에요>,<', 42, 1, 'GOOD', SYSTIMESTAMP);
