INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '완전 크로플 맛집! 카페 분위기가 너무 좋고 빈티지 아늑한 아지트 느낌이라 사진도 잘 나와요~ 노래도 재즈로 조용하고 아늑해서 혼자 카페와도 잔잔한 분위기로 좋을 것 같은 연남동 예쁜 카페입니다. 크로플이 쫀득하니 생크림도 맛있어요~ 하와이언 라떼도 코코넛 향 가득해서 맛있었습니다. 또 올 것 같아유~', 27, 7, 'GOOD', SYSTIMESTAMP);
