INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '크로플 미쳤어요🫢 아이스크림 아니고 직접 크림 만들어서 바로 올려주시는데 정말 맛있었습니다ㅜㅜ 2, 3층인데 개인적으로 3층 좌석이 유니크하고 너무 이뻤어요~🥰', 2, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '미라클 카페! 정말 너무 갬성이 넘치는거 같아요 제가 최애로 생각하는 레트로 그리고 올드한 우드 갬성에 정말 너무 편한 배치의 테이블이랑 의자 모든걸 다 가지고 도망가고 싶었습니다 ㅠ 커피랑 크로플을 먹었는데 커피는 향이 좋더라구요! 산미항 맛이 정말 깔끔하고 저의 취향저격😆 대망의 크로플! 나 이거 100개 냉장고에 넣고 먹고싶어 생크림은 진짜! 부드러워서 무쳤다! 로즈마리 향에 크로플에 부드러운 생크림은 다이어트 포기할게요!😭', 41, 4, 'GOOD', SYSTIMESTAMP);
