INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '크로플 정말 바삭해요. 원래 다른 화이트크림 커피 먹으려 했는데 사장님이 크로플이 달아서 음료도 달면 헤비할수 있다 하셔서 가볍게 커피랑 티를 주문했는데 너무 현명했어요. 분위기 짱 좋고 이뻐요! 시간보내기 좋은장소입니다!', 21, 2, 'GOOD', SYSTIMESTAMP);
