INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '콜드브루 맛집 여기였어요. 커피 맛집이라길래 혹하는 마음에 왔는데 완전 대만족.. 크로플 크림이 예술인 크로플 맛집인듯요.. 존맛탱 크로플과 콜드브루 한잔에 홍대카페 베스트 등극이요', 122, 22, 'GOOD', SYSTIMESTAMP);
