INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '여기 진짜 크로플 맛집!!!!!! 크림이 너무 맛있어서 여쭤보니까 100% 생크림이라고 하네여,,, 나중에 연남 가면 또 방문할 거 같아요 그리고 인테리어도 아늑하니 사람이 붐비지도 않아서 넘 좋았어요🩵', 55, 16, 'GOOD', SYSTIMESTAMP);
