INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '일단 사장님이 커피에 진심이셔서 커피맛이 정말 일품입니다. 엄청 가지수가 많진 않지만 베이커리도 딱 알맞게 준비되어있어서 굉장히 만족!! 은은한 팝 음악 잘 듣고 잘 마시고 가요!', 17, 8, 'GOOD', SYSTIMESTAMP);
