INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '공간분위기도 너무 좋고 크로플도 여기 완전 제대로 하는 곳 ㅋㅋㅋ 디저트가 예술적이에요…. 2층이랑 3층자리 있는데 넘 편안해서 두 시간 넘게 있었어요. 연남동에 친구들 놀러오면 여기 데려가면 무조건 반응 좋을 그런 곳!! 🥹💕', 236, 32, 'GOOD', SYSTIMESTAMP);
