INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '린스타 갬성 크로플 찾다가 발견.. 근데 여기 린테리어 맛집이였네..? 화장실 입구부터 화장실 내부는 왜때문 예쁘죠.. 좁지만 아늑허고 자리도 다닥다닥 있지 읺아서 조코 ...  자리더 가때그때 바로 치우고 청결하게 유지되고 이뜸.. 음악은 뭐때문애 계속 좋은 것만 나로쥬...bgm까지 조은데..크로플에 치쥬까지... 크로플 다먹어도 로투스 과자뷰스러기애 치즈 계속 긁어먹고....라떼도 깔끔한 목넘김.. 나 여기 좋아하네..', 36, 10, 'GOOD', SYSTIMESTAMP);
