INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '1층만 보면 살짝 아담한 느낌인데 2층까지 있어서 자리도 넉넉하고 편해요! 크로플 비주얼 미쳤고 바삭하고 맛있어요 음료는 좀 비싼데 연남동이니까.. 그래도 맛있었어서 만족합니다 ! 자몽블랙티 추천. 친구랑 편하게 대화 나눌 수 있어서 좋았습니다~!', 18, 3, 'GOOD', SYSTIMESTAMP);
