INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '시그니처 아이스티 너무 감동이에요 어떻게 이런 맛이 있죠...? 제가 먹었던 아이스티 중에 제일입니다 ㅜㅜ 너무 맛있어요 꼭 드셔보세요 바닐라라떼도 너무 맛있고 크로플도요.. 위에 생크림도 직접 만드시는 것 같아요 너무너무 다! 맛있어요 감동입니댜 ㅜㅜ 💗', 118, 26, 'GOOD', SYSTIMESTAMP);
