INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '브라우니가 정말 맛있는 연남동카페예요. 2 3층 쓰고있어서 분위기 골라서 앉을수있네요. 2층은 힙하고 3층은 편안한 분위기입니당~', 105, 24, 'GOOD', SYSTIMESTAMP);
