INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '음악부터 인테리어까지 완전 좋아요 3층도 분위기 좋고~ 스피커가 좋은지 귀가 즐거워요ㅎㅎ 자리도 편해서 오래 수다떨기도 좋아요 주인남자분도 친절하시고 크로플 완전 추천해요! 느끼한거 없고 우유맛이 강한 생크림인데 입에서 녹아요 크로플도 바삭한데 ㅋㅋ로즈마리 향 입혀서 생크림이랑 먹어주면 최곱니다ㅋ 또먹으러 가야지ㅋㅋ', 17, 1, 'GOOD', SYSTIMESTAMP);
