INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '아이스아메리카노, 핫초콜릿, 플레인크로플 시켰습니다. 진짜 다 맛있어요... 음료 디저트가 다 맛있는 카페 찾기 힘든데 바로 여깁니다... 메뉴 맛이 다 부드러우면서 산뜻하고 가볍게 끝맺어졌어요. 추천합니다🥺.. 크로플+아아 조합이 최강이니까 꼭 드셔보세요', 28, 2, 'GOOD', SYSTIMESTAMP);
