INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '분위기가 너무 좋아요❤️ 연남동에 이런 카페 있는 줄 몰랐어요!! 크로플 맛집이라해서 가봤는데 정말 크로플 짱맛인데다가.. 위에 올라가있눈 크림도 너무 제 취향이에요😊!! 담에 또 방문하고싶어요!', 39, 2, 'GOOD', SYSTIMESTAMP);
