INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '1. 2층이 있어서 자리 넉넉함 2. 노래도 좋고 대화하기도 좋음 3. 크로플이 미친놈 4. 사장님이 젠틀맨을 넘어 킹스맨 5. 소파있음 *데이트 / 오랜만에 부모님 뵐 때 / 동네 친구 만날때 좋음', 5, 0, 'GOOD', SYSTIMESTAMP);
