INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '연남동 미라지커피를 이제야 알게 되다니! 아기자기하면서 귀여운데 2층까지 있어서 좌석도 꽤 넉넉하니 좋아요 💗 직원분께서 친절하게 메뉴 설명도 해주셨어요! 크로플도 음료도 매우 맛있었습니다 :) 다음에 또 오고싶어요 💛💨', 17, 7, 'GOOD', SYSTIMESTAMP);
