INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '크로플 맛있어서 재재방문했던 곳인데 요번에 먹었을 땐 위에 생크림 맛이 좀 변한 느낌이었어요 ㅠㅠ 원래 홍차향? 나면서 넘 맛있었는데 요번엔 그냥 평범한 생크림 맛..? 바뀐 게 맞다면 원래로 돌아와줘요~~!😖', 32, 0, NULL, SYSTIMESTAMP);
