INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '미라지 크로플 진챠 사랑해요…♥︎ 너무 달지도 않고 느끼하지도 않고 너무 빠삭하지도 않고 너무 무르지도 않고 적당히 겉바속쬰 거기에 로투스까지 … 뭐 하나 빠짐없이 조화로워요 늘 생각나는 맛이에요 🥹', 4, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '일단 크로플 뒤집어지게 맛있고 두 조각이나 나와서 친구랑 안싸우고 먹을수 있었어요.커피 산미 적당하고 너무 맛있어요ㅜㅜ좌석 너무 편해서 잠들뻔했네요..친구가 실수로 컵을 부셨는데 오히려 걱정해주시고 괜찮다고 해주셔서 감사했답니다. 담엔 친구 팔을 묶어서 방문하려구요. 디저트가 맛있고 사장님이 친절한 미라지 커피 대박나세요!', 97, 26, 'GOOD', SYSTIMESTAMP);
