INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '연남동 카페 미라지커피 크로플, 미라지콜드브루, 시그니처 아이스티 주문 아이스티 맛있고, 크로플도 맛있어요 크로플 위에 올라간 건 여기서 만든 크림이라고 ~~ 맛있게 잘 먹고 갑니다', 88, 16, 'GOOD', SYSTIMESTAMP);
