INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '크림화이트 묵직하니 맛있어요! 밀크초코는 매우 달달쓰 하고 브라우니는 컵케잌 같은 식감이라 신기했네용 인테리어가 이뻐서 분위기 좋아요~', 43, 7, 'GOOD', SYSTIMESTAMP);
