INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '제 경험 중에서 가장 불친절한 남자 서버였어요. 다른 손님들이 동의해도 음악 소리를 줄이지 못하게 하고 애티튜드 자체가 안되어 있는 직원이었습니다. 서비스 업종이면 직원 교육 잘 시켜야할거 같아요.', 11, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '카페 인테리어도 좋고 커피맛도 좋은데, 그 2층 3명 앉아있을수있는곳에 단체석만 가능하다고 하셨는데 안하시는게좋을거같습니다. 몇몇 손님들이 자리 찾다가 그거 보고 그냥 나가셨어요..', 19, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '여기가 연남동 크로플맛집이라고해서 와 봤어요. 2층과 3층 복층으로 사용중이신데 홀 규모는 아담해요. 연남동 카페들이 아담하고 특색 있어서 좋아요. 오늘 주문한 크로플. 명성처럼 맛짐하네요. 크림이 달지 않으면서도 크로플의 바삭함과 존득함에 잘 어울려요.ㅎㅎ 직원분이 친절하게 메뉴 설명과 식음 설명까지~~ 감동이에요^^', 40, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '크로플이 땡겨서 맛집을 찾다가 발견한 곳 커피는 다소 아쉬웠지만 크로플은 매우만족😗 사장님도 친절하셨고 공간도 이뻤음. 다만 소리가 많이 커서 그것만 개선되면 정말 좋을듯?', 68, 15, NULL, SYSTIMESTAMP);
