INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '사장님 친절하시그요..음료들도 다 맛있구 깔끔하구 크로플 맛있어요 크림이 시그니처같은대 전 좀 느끼햇어요 근데 크림을 아예못먹는 저도 먹을수 있을정더 였어요 :) 분위기도 좋구여', 48, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '크림에 배인 로즈마리향이 너무 향긋하고 맛있어요ㅠㅠ!! 크림이 잔뜩 올라가있어서 크로플 먹는 중에 크림이 모자라거나 하지않아서 더 좋아용ㅎㅎ 커피는 시그니처 콜드브루, 하와이안, 아이스티 먹어봤는데 전부 기본에 충실하면서 디테일이 맛있는 음료라 좋았어요!', 86, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '크로플 맛있는지 몰랐는데..... 미라지에서 크로플 먹고 크로플에 눈떴어요👀 크로플이 이렇게 맛있는 거였나요ㅠㅠㅠㅠㅠㅠ 어쩐지 테이블마다 크로플 하나씩 있더라고요!! 사장님께서 알려주신 크로플 맛있게 먹는 방법 그대로 먹고 크로플에 푹 빠졌어요 미라지크로플은 제 인생 크로플🙊💖 [크로플 먹는 방법] 1. 로즈마리는 향이 베이게 치우지 않는다 2. 크림 가운데를 자른다 3. 크로플을 먹기 좋게 자른 다음 가운데 과자랑 크림 크로플 빵 함께 먹는다 🙊🙊🙊❤🧡💛💚💙💜 주변 상인, 동네분들 할인도 있어요!! 이렇게 맛있는 집이 동네인데 할인까지?!?! 부럽습니다ㅠㅠㅠㅠㅠ', 45, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '크로플 찐맛집이예요! 2,3층 분위기가 다른데 둘다 매력적이고 너무 예뻐요. 음악 선곡 센스가 진심 남다르세요. 음료도 맛있고 디저트도 맛있고 담에 또올려구요 ㅎㅎ', 10, 2, 'GOOD', SYSTIMESTAMP);
