INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '커피도 맛있었지만 무엇보다 크로플이.. 진짜 깜짝 놀랐어요 크림에서 잡내도 안 나고 크로플 위에 뿌려진 가루와의 조합이.. 말로 표현 불가에요 이건 진짜 직접 드셔보셔야 해요 그리고 사장님 너무 친절하셔서 꼭 재방문 하고 싶어요!', 19, 2, 'GOOD', SYSTIMESTAMP);
