INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '맛과 분위기는 물론 좋구요 사장님이 정말 친절하셔요 상투적인 친절이 아닌 진심이 들어간 친절과 배려 굿! 애기가 있어 걱정했는데 전혀 개의치 않으시고 애기 음료도 따로 만들어 주시고 크로플은 정말 맛있어요 크림 굿!', 9, 10, 'GOOD', SYSTIMESTAMP);
