INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '사장님너무 배려심 많고 친절해요 진심으로 감사합니다 커피도 맛있고 크로플 완전 !!!! 우리집앞으로 오세요 매일 먹을수 있어요 잘 먹고 갑니다 감사해요', 21, 2, 'GOOD', SYSTIMESTAMP);
