INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '연남동 와플 맛집이라는데 맛있었지만 제 스탈은 아니었어요.전 크림보다 아이스크림 올라간 와플을 더 좋아해서요. 커피 맛은 좋았고 카페 내부도 분위기 좋아요.', 12, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '와 연남동에 이런 좋은 카페가 숨어 있었다니...! 진짜 역대급 분위기 좋고 크로플 역대급 존맛탱... 그리고 미라지 아이스티 진짜 넘 맛나염...다른 애랑 또와야지~~☺️', 46, 3, 'GOOD', SYSTIMESTAMP);
