INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '커피맛은 아주 훌륭해요👍 플랫화이트 좋아하는데 여태 먹은 커피 중 top3안에 드는 것 같아요 인테리어도 이쁘구 다 좋은데 작업 하려 들어간 곳이라 와이파이 비밀번호 전화로 여쭤봤는데 내려와서 보시라 하더라구요? 3층과 2층 계단도 꽤 높고 사실 왔다갔다가 하기 힘들어요 솔직히 유리문도 두꺼워서 커피 가지고 갈때도 힘들구요 자칫하면 엎겠어요 그리고 카페 안에 이것저것 지시글? 건들지마세요 이런거 하지마세요 라 적힘 쪽지가 참 많습니다 지시하고 통제하시는거 좋아하시나봐요 카페가 커피맛 좋으면 되니깐 그리고 인테리어 좋으니까도 있지만 딱히 서비스가 많이 좋짐 않아요 참고하세요😉', 49, 2, NULL, SYSTIMESTAMP);
