INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '일단 매장이 너무너무예쁘구용 메뉴들도 다 맛있어요~~~ 힙하고 요즘 서타일 카페 찾으시면 강추 직원분께서 메뉴도 친절하고 잘 알려주세용💓💓', 42, 3, 'GOOD', SYSTIMESTAMP);
