INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '조용해서 대화나누기 좋았는데 커피랑 디저트도 기대이상 맛있었어요. 트로플의 만죽, 크림이 맛있고 독특해서 추가해서 먹었습니다. 좋은 시간이었어요', 46, 6, 'GOOD', SYSTIMESTAMP);
