INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '인테리어 너무 분위기있고 예뻐요! 그리고 라떼아트가 예쁘게 나오지 않는다며 다시 내려주신다하시던 사장님..ㅠㅠ 왕친절하세요🥺 코시국에 적절히 환기도 해주시고 플랫화이트 커피도 맛있었습니다ㅎㅎ다음에 꼭 또 들려서 크로플도 맛볼거에용', 16, 1, 'GOOD', SYSTIMESTAMP);
