INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '연남 미라지커피 365일 크리스마스 일 것 같은 공간일 것같아요 ! 친절하신 바리스타님과 직접로스팅하는 공간이라 커피가 궁굼해서 평소엔 안좋아해서 안마시는 드립커피를마셔봤는데....진짜 너무 맛있었어요! 크로플 맛집이라던데.. 진짜 JMT ! 미라지커피 크로플안먹어 본사람 없게 해주세여 🙏', 71, 15, 'GOOD', SYSTIMESTAMP);
