INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '연남동 안쪽에 위치해서 시끄럽지 않고 포근한 분위기의 카페라 데이트 장소로 좋아요. 커피도 진하고 고소하지만 크림이 듬뿍 올라간 바삭한 크로플이 최고! 제가 먹어본 크로플 중에 제일 맛있었답니다 🥲 연남동 카페 찾으시면 미라지커피 추천!', 40, 9, 'GOOD', SYSTIMESTAMP);
