INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '매장이 넘 예뻐서 들어왔는데 유명한 곳이더라구요! 크로플이랑 아메리카노, 청포도 에이드까지 음료나 디저트 모두 깔끔하고 맛있어요 존맛!', 63, 13, 'GOOD', SYSTIMESTAMP);
