INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '일단 인테리어가 너무 힙해서 좋은 미라지커피는 크로플 위에 올려진 크림에 로즈마리 향이 먹는내내 가득해서 너무 맛있고 핸드드립 커피랑 넘 잘 어우러져서 짱 맛있었어용~! 여심저격 크로플 맛집 인정 ㅎ ㅎ 자주 가야겠어용ㅎㅎ', 19, 1, 'GOOD', SYSTIMESTAMP);
