INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '크로플도 너무너무 맛있고 그 위에 올라가있는 크림이 진짜 너무 맛있어요 심지어 크림이 매우 많이 올라가 있어서 맛있는 크림을 왕창 먹을 수 있어요 ㅎㅎ  커피도 엄청 달지 않아서 디저트랑 너무  잘어울립니다 맛있게 잘먹었습니다 감사합니다❤️❤️', 62, 18, 'GOOD', SYSTIMESTAMP);
