INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '크로플이 진짜 예술이예용 ㅠㅠ 먹는 방법 설명해주시는 사장님도 너무 친절하시구 특히 인테리어도 너무 예술 ㅠㅠ연남동에 숨은 예쁜 카페•• 지인들한테도 추천했습니당 !!', 120, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '크로플이 진짜 맛있네요 크로플위에 올라간 크림이 너무 맛있어요.. 아몬드?향이 나는 견과류크림같은데 크로플과의 조합이 장난아니였어요!! 사장님이 혼자 두층으로 된 테이블 메뉴를 받다보니 메뉴와 음료 나오는데 시간이 걸리긴하지만 인테리어도 빈티지하면서 따뜻한 느낌이 좋았습니다', 91, 26, 'GOOD', SYSTIMESTAMP);
