INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '디저트-크로플(바삭한 크로플 위에 얼그레이 크림을 듬뿍 얹어줘요)도 맛있고 하와이안 커피(코코넛 밀크의 고소한 맛과 향이 나고 설탕 빼달라고 하면 빼기도 가능할듯합니다. 원당을 사용해서 덜 달다고 하시기에 저는 안 뺐어요. ) 도 맛있습니다. 디저트와 커피 모두 훌륭하네요. 코로나 방역을 철저하게 지키셔서 그런지 2시간 시간 제한이 있었어요. 영수증 시간대를 확인하시고 1시간 55분쯤 되면 직원이 와서 나가야할때라고 알려주십니다. 나중에 코로나가 좀 사그라들면 다시 방문해서 여유를 즐기고 싶은 곳이네요^_____^', 19, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '저번에 우연히 갔다가 만족해서 또 방문했어요. 크로플 진짜 맛있고 커피도 진해서 좋아요. 인테리어도 제 취향이고 특히 플레이리스트 맛집입니다 👍🏻👍🏻', 61, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '2,3층으로 되어있고 사장님은 2층에 계시는대 겨울코트랑 짐 놔둘곳이 곳이 없어서 빈좌석 끌어다 올려놨더니 2층서 cctv 확인하고 사장님 바로 올라와서는 이러면 안된다고 하시더니 2시간 되니 또 올라와서 나가라고  하시네요. 2층 들어오는 유리문에 손글씨로시간제한 써져 있었다는대 카페 들어오면서일일이 그거 다읽고 들어오시는 분들이  몇이나 될까요? 영수증 달라고했더니 끝까지유리문에 미리 공지 되어있었다고 하시는대그러지 마시고 네이버 카페정보란에 공지해놓으세요. 지금까지 수도없이 많은 카페를가봤지만 호텔 부페도 아니고 2시간 시간제한 두는 카페는 처음 가봤네요. 지금보니 어제 가구 옮기지 말라는 공지는 올리셨네요. cctv로 계속 감시받는 느낌 별로고 이런저런 규칙이 많아서 카페가 아닌학교같은 느낌이에요.', 55, 15, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '크로플 바삭 쫄깃 너무 맛있고 크림이 대박이었음👍🥰바닐라라떼 자몽에이드 둘다 맛있었는데 크로플에는 커피메뉴 추천함 👏👏방문한 날에 콜드브루가 다 나가서 못 먹어 봤는데 앞선 메뉴들을 보면 콜드브루도 넘 기대되서 다음에 다시 방문해서 먹어볼것임!!', 90, 18, 'GOOD', SYSTIMESTAMP);
