INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '들어가자마자 넘 협소해서 자리 없겠다 싶었는데 다행히 이층짜리더라구용 위에는 좌석도 많구 테라스도 있어서 좋았어요! 직접 가져다주시고 먹는 방법까지 알려주셔서 좋았습니당 저희는 크림화이트, 플랫화이트, 크로플 주문했는데 크림화이트는 아이스인데도 거품이 올라가더라구요..? 아이스엔 식감이 안어울렸고 잔에 비해 그리고 타매장들에 비해 얼음이 많았던거 같아요 5개정도 들어가는듯.. 아주 진해서 맛은 있었지만요^^ 그리고 크림화이트는 크림이 정말 맛있었어요! 왜 시그니처인지 알겠다는.. 그리고 크로플은 빵이 두꺼우면서 바삭하니 넘 최고였는데 생크림을 두덩이나 주셔서 넘 헤비하다고 느껴 남겼어용ㅠ 한쪽은 아이스크림 얹어주시거나 추가비용 지불하고 토핑하는 방법도 좋을거 같아영 무튼 개인적인 솔직 후기입니다^^', 41, 8, NULL, SYSTIMESTAMP);
