INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '연남동 올 때마다 오는 곳인데요... 리뷰 올리면 사람 많아질 것 같아서 안 올리려했는데요..... 크로플이 진짜 너무 맛있어서 올립니다... 다들 영접해보시죠.... 역대급 분위기는 물론, 음악도 항상 큐레이팅하셔서 너무 좋네요.... 자그마한 로스터기도 한 몫하구요...👍 서울 인근 카페 top 3로 뽑습니다. 미라지커피 사람 많아져도 맛있게 해주세요!', 62, 15, 'GOOD', SYSTIMESTAMP);
