INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '카페 분위기 좋아요! 2층과 3층 이용할 수 있습니당. 창가 자리 완전 예뻐요. 뷰도 괜찮고요. 그리고 여기 크로플 완전 강추에요! 위에 올라가는 크림이 존맛탱에다가 크로플 바삭바삭 따뜻하니 맛있어요. 굿굿. 음료도 맛있습니다.', 6, 1, 'GOOD', SYSTIMESTAMP);
