INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '음료는 너무 비싼데 1인 1커피여서 두개 시켜야되서 아쉬워요 그리도 크로플 정말......생크림까지 정말 완벽합니다. 맛있어요ㅠㅠ', 46, 10, NULL, SYSTIMESTAMP);
