INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '와 역대급 크로플이었어요!!❤️❤️진짜 사장님도 너무너무 친절하시고 연남동에서 크로플 맛집 찾으면 진짜 최고로 추천합니다!!👍🏻👍🏻 달달하고 꾸덕한 크림과 고소한 버터 크로플에 로즈마리향까지 너무 고급지고 맛있어서 당충전 완전 짱짱하게 됬어요 다음에 꼭 또올께요 :)', 28, 10, 'GOOD', SYSTIMESTAMP);
