INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '사장님도 정말 친절하시고 분위기가 전체적으로 조용해서 얘기하기도 좋아요! 크로플 맛집이라해서 가봤는데 정말 맛집이에요! 로즈마리향 솔솔입니당~', 0, 4, 'GOOD', SYSTIMESTAMP);
