INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '사장님이신지 직원분이신지 혼자서 일하시는 남자분이 너무너무 친절하셨어요! 크로플 두개 시키려니까 양 많을 수 있다고 일단 하나 시키라고 추천하시고 실수로 유리컵이 깨졌는데 바로 치워주시고 자리 옮기라하고 너무 죄송했어요.. 또 방문 하겠습니다! 크로플 진짜 맛있어요 강추', 12, 7, 'GOOD', SYSTIMESTAMP);
