INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '인원이 많아서 크로플 두개 시키려고 했는데 안된다고 하시고‎ﻭﻭ이래저래 안된다고 하시는게 많아서 조금 그랬지만,,,,,,,,크로플도 존맛이고 비앤나도 맛있어요! 특히 크림이 최고 재방문의사 있음', 28, 4, NULL, SYSTIMESTAMP);
