INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미라지커피'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '늦은 밤에 갔더니 사람도 없어서 조용하고 좋았어요~큰 창문 열어놓으니 카페 분위기가 더 좋더라구요~ 음악도 비트도 좋아요ㅠㅠㅠ 그리고 사장님 넘 친절하셨어요! 홍차랑 우유도 더 주시구..ㅎㅎ 자주 올게요!', 48, 10, 'GOOD', SYSTIMESTAMP);
