INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '케이크 먹고 싶어서 찾아왔는데 복숭아 케이크랑 무화과케이크 둘다 너무 맛있어요 :) 과일케이쿠 맛집이에요💓 커피도 산미있고 맛있네요오 ☕️ 확 트인 통창뷰도 너무너무 좋아서 친구들이랑 수다 떨기 좋았습니다 또올게욤🫧', 3, 9, 'GOOD', SYSTIMESTAMP);
