INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '촉촉한 시트, 달콤한 크림, 신선한 과일이 삼위일체로 어우러져요!! 아메리카노도 고소해서 케이크랑 잘 어울리고, 살구홍차밀크티는 밀크티 좋아하시는 분들이라면 강추입니다! (밀크티는 컵에 부을때 과감하게 부어야 안 쏟아요 ㅋㅋ) 특별한 날에 홀케이크 주문하고 싶습니다!', 1, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
