INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '과일 크레이프 맛집:) 친구가 맛있다고 해서 갔는데 다 너무 맛이어 보여서ㅠㅠ고민하다가 크레이프로 먹었는데..진짜 추천👍👍다들 크레이프 하세요ㅠㅠㅠㅠㅠ거기다가 과일도 너무 싱싱하고 크림양도 적당해서 더 맛있었던 것 같아요🍓🍌🥝🍇🍰', 6, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '전날 들어가려고 했는데 꽉 차서 못 들어간 곳이라 다시 한번 시도한 곳입니다. 점심시간 때 들어가니 손님이 적었어요. 그래서 바깥도 보고 아이도 보면서 차랑 케이크를 맛있게 즐길 수 있었습니다. 제철 케이크가 유명한 곳이라고 해서 가 봤더니 무화과 케이크 종류가 제일 많더라고요. 그래서 커피와 무화과 케이크 그리고 히비스커스 밀크티를 같이 주문해서 맛있는 차 시간을 즐기고 왔습니다. 케이크가 너무 달지 않아 어떤 종류의 차와도 잘 어울리는 그런 맛인 것 같아요. 커피도 제가 좋아하는 좀 진한 커피! 장소가 탁 트여 있어서 사람이 많으면 시끄럽게 느껴질 만했는데 오늘은 적정한 사람 수의 카페 안이라서 괜찮았네요. 다음에도 기회가 된다면 대낮에 가는 걸로😜😜😜', 29, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '케잌 종류가 너무너무 많아서 눈 뒤집어지는줄…😇 제일 궁금한 복숭아랑 망고 하나씩 시켰는데 망고가 지이이인짜 너무 맛있어요! 상대적으로 망고가 달아서 그런지 복숭아는 달진 않고 무난무난했어요(딱복느낌) 화장실은 매장 옆에 남여공용이고 나름 깨끗한 편이에요!', 69, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '신선한 생과일로 만든 케이크와 맛있는 커피 그리고 음료도 정말 맛있답니다. 메뉴 하나하나 그냥 만든 것 같지 않아요. 케이크 생각나면 지나다가 꼭 들립니다.', 42, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '사실 다른 카페 가려다 재고소진돼서 이쪽으로 온 거였는데... 진짜 아쉽다는 생각이 하나도!!! 안났어요! 한 20분동안은 먹으면서 계속 맛있다... 만 반복했어요 ㅋㅋㅋㅋ 초코에빠진딸기!! 너무 맛있어서 중간에 베리요거퐁당도 추가로 시켰습니다👍 블루베리 엄청 많이 들어있어요!! 살구밀크티도 살구맛 많이 나서 새롭고 좋았어요 초코케이크를 꼬옥 또 먹어야돼.......😻🥹', 472, 60, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '남자친구 생일 케이크때문에 예약하고 방문했는데, 생각보다 맛있는 딸기 케이크 느낌이라 좋을 것 같아요..! 먹어보고 맛있다고 하면 다음에 또 방문할 의향 있어요 💜 감사함댜', 125, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '생각보다 매장이 작아요. 정말 아쉬운 점은 웨이팅 장소가 너무 비좁아요. 한쪽으로 사람이 지나다닐수 있게 했음에도. 알바생이 자꾸 아래쪽으로 내려가라고. 저희 일행중에 일부는 자리가 없어 바깥에서 기다리는 중이였고요. 제가 자리가 비좁아서 위쪽에 있는거라고 했는데도 파티쉐님 이동 통로라며... 흠…파티쉐보다 가게를 찾아주는 고객을 쫌이라도 생각했으면 싶네요.', 39, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '친구 단골집에 놀러왔어요! 친구가 장담한대로 케이크가 너무 맛있고 뷰도 너무 좋아요~ 여름이라 쾌청한 바깥 뷰 보면서 맛있는 케이크 먹으니깐 여유롭고 행복해요~ 데이트 장소로 추천해요!!', 63, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
