INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '극히 대단한 맛은 아니구 그냥 과일 케이크 맛이었지만 케이크 종류가 너무너무 다양해서 좋았어요 취향 갈리는 사람끼리 가도 종류가 워낙 다양하니 하나쯤은 맞는 케이크가 있겠더라고요~ 이렇게 다양하게 만드시는 거 진짜 힘들 것 같아요', 15, 0, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '친구 생일에 복숭아케이크 사주고 싶어서 찾아보다가 비포블루밍에서 사기로 결정했어요. 네이버 예약으로 전날에도 주문할 수 있어 편했습니다. 방문했을때도 친절하고 빠르게 포장해주셨어요. 케이크 상자는 들고가기 쉽게 손잡이가 있는 비닐에 넣어주셨고, 저는 1시간 이하로 집에 갈 수 있어서 아이스팩 하나를 같이 넣어주셨습니다. 케이크는 안에 복숭아가 가득 들어있었고 당도도 좋아서 맛있었습니다. 케이크시트는 촉촉하고 생크림도 맛있는 우유생크림이었어요. 개인적으로 복숭아에 요거트크림버전도 있으면 맛있을 것 같아요. 모두 만족하긴 했지만 안쪽이 딱히 물복같지는 않았어요. 중간정도? 하지만 달달복숭아였기에 괜찮았습니다. 다음에 또 방문할 것 같아요~', 43, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '계절별로 케익 종류가 바뀌어서 좋아요~!! 무화과 케익 먹고싶어서 갔는데 일찍 품절되서 아쉬운대로 복숭아 케익 먹었어요~!! 다음엔 무화과 케익을!!', 12, 5, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '9/6 토요일 7시 단체로 방문 했습니다 비포블루밍 케이크 항상 맛있어서 친구들과 방문하고 생일 케이크로 10회이상은 포장 주문 해왔습니다 하지만 오늘은 매장에서 식사를 했는데 직원들이 솔직히 너무 불친절하고 별로입니다 단발머리이신 알바생분 음료 따로 따로 한명씩 결제한거 빌지 보고 어이없어하는 표정을 봤어요 서로 보고 야 이거 봐바 하는거 다들리고 저희가 진동벨 번호 하나로도 했는데 주문을 키오스크에 했는데 왜 뭐가 일하면서 기분나쁜가요? 아메리카노도 똑같은 연하게인데 하나는 멀쩡하고 하나는 홍삼맛이 어떻게 나죠? 죄송하다는 말없이 그냥 바꿔주네요 항상 이런식인가요? 의자도 옆에꺼 써도되냐니까 간이 의자  엉덩이 반도 안되는거 구비해둔거 쓰라고 하시고 앞으로 방문은 없을 듯 합니다', 78, 12, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '가게 내부에 사람이 많길래 저번에 못먹어서 아쉬웠던 애들 포장해왔어요✌️ 오레오초코도 쿠키맛 많이 나서 맛있었는데 초코딸기바나나!!! 5점만점에5점. 저는 단걸 엄청 좋아해서 그런가 제 취향에는 얘가 더 맞았어요! 또 먹으러 가야겠다...😻', 25, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '작년에 홀케이크 맛있게 먹었어서 올해도 홀케이크 주문 전에 복숭아 케이크 조각으로 포장해와서 바로 먹었는데 아쉬워요 진열대에는 상태 좋은게 전시돼있어서 주문했는데 좀 시간이 된듯한 케이크로 꺼내셔서 무화과나 다른 종류인줄 알았어요 먹어보니 저 부분은 식감이나 맛도 이상해요', 8, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '세 번째 이용이었습니다. 전에는 너무 맛있었는데 크림부터 다른 집과 다르고 입에 넣자마자 달고 부드럽고 진짜 맛있었는데….. 이번에는 크림이 바뀌었는지 크림맛이 달라졌어서 다른 케이크집과 다를 게 없고 굳이 이 가격을 주고 사 먹어야 하나 싶습니다. 진짜 너무 좋아하고 다른 사람들에게도 추천했던 집이었는데 너무 아쉽네요.', 50, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '너무 유명한 곳이라 한번 와봤어요! 일단 커피 밸런스 넘 좋았고 초당옥수수바치케 크리미한 맛으로 맛있었어요! 근데 옥수수ㅋㅋㅋ 대도 포함되어 있어서 먹기 난감.. 근데 칼 기본으로 같이 안 주셔서 따로 요청했어요. 왜 필요하시냐고 여쭤보시길래 옥수수 말씀드리구.. 대 없이 옥수수 얹어주시거나 칼 기본으로 같이 제공해주심 거 편리하게 이용할 수 있을 것 같아요! 망코케이크는 시트지에 설탕물 바른 느낌으로 달긴 했지만 그래도 당도높은 망고 꽤 들어있어서 맛나게 먹었어요~ 요즘 디저트 맛집 너무 많아서 그런지 엄청 신세계급은 아니라 아쉬움은 있네요. 집에서 넘 멀기도 해서 굳이 막 찾아올 것 같진 않아요🥲', 62, 11, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '저번케잌  사진을  못찍었지만 아주 좋아용  케잌도  맛을본다면  더  좋아할수밖에  없어요 ㅎㅎㅎ 오늘 생일인 친구도  넘 좋아해요~~', 86, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '딸기 철이 지났지만 생일자가 딸기케이크가 먹고 싶다고 하셔서 처음 예약했는데 많이 맛있다고 하네요? 비주얼만 봐도 이미 맛있어보이는! 그런데...먹으면 얼마나 맛있게요 딸기랑 망고만 몇개 먹었는데 제 입맛엔 망고가 더 맛있었어요!! 또 하나의 케익 맛집 저장입니다', 26, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '생일 케이크로 예약해서 먹었는데 너무 실망했어요. 과일이 많이 들어가서 비싼건데 복숭아가 너무 맛없어서 여자친구가 이거 무 아니냐면서 복숭아 다 빼놓은 모습.. 제가 먹어봐도 무슨 무 씹어먹는것 같이 딱딱한 복숭아였네요. 여자친구가 이거 무 핑크색으로 염색한거 아니냐는데..ㅋㅋㅋㅋㅋㅋ 물렁한 복숭아도 케이크 속에 있는데, 다 물러있었어요. 誕生日ケーキとして予約して食べたんですが、本当にがっかりしました。 フルーツがたくさん入っていて高かったのに、桃がすごくまずくて、彼女が「これ大根じゃないの？」って言いながら桃を全部取り除いたんです。僕が食べても、本当に大根をかじってるみたいに固い桃でした。 彼女は「これ、大根をピンクに染めただけなんじゃない？」って言ってました…笑 柔らかい桃もケーキの中にはあったんですが、それは全部ぐにゃぐにゃに崩れてました', 24, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '작년에 먹고 너무 맛있어서 올해 또 방문했어요~~ 무화과 케이크의 달콤한 향과 촉촉한 식감이 입안 가득 퍼져 정말 만족스러웠어요. 과하지 않은 단맛 덕분에 부담 없이 끝까지 맛있게 즐겼어요!!', 125, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '연남 비포블루밍! 저장만 해두고 못가보다가 마침 조각케이크가 필요해서 당장 방문했다 ☆彡 딸기케이크를 먹을까, 과일 크레이프를 먹을까 고민하다가 과일 크레이프?로 골랐는데 진짜 럭키크레이프 .. ෆ 짱맛있다 ..!!! 메이플시럽도 같이 주시는데 뿌려먹어도 짱맛있다 ....!! 비싼만큼 맛있는 케이크 👏👏', 87, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '솔직히 이쁘기만 하고 맛은 기대이하입니다. 복숭아 질이 진짜 안 좋아요. 색깔만 이쁘고 당도 0의 딱복입니다. 생크림과 함께 먹으면 복숭아가 단가? 라고 착각이 들지만 복숭아만 따로 먹어봤을 땐 당도가 아예 없어요. 이게 5만 원..?? 싶은 맛입니다. 시트랑 생크림은 맛있었어요. 하지만 과일을 이렇게 넣어준다!는 컨셉으로 시중보다 비싸게 케이크를 파시는데 이런 맛없는 과일로 케이크를 만드시는 게 이해가 안 가는 맛이었습니다. 기대한 만큼 아쉬움도 크네요.', 87, 13, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '홍대역 바로 앞에 이렇게 멋진 뷰의 카페가 있었다니…! 케이크도 맛있고 홍차에이드도 예쁘고 맛있었어요!! 다음에 친구랑 또 가려고요 😍😍😍😍 초록 글씨의 상호 들어간 컵이 음료랑 어찌나 잘 어울리고 예쁘던지…! 앞으로 종종 가야겠어요 😍', 79, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '비포블루밍 3호 딸기 케이크로 환갑 파티 했어요 !! 🎂🎂 작년 여름 즈음 비포블루밍 카페 갔다가 복숭아 조각케이크 먹고 다음에 홀케이크 필요한 날 있을 때 여기서 해야겠다 했어서 예약해써용🤭 전 날 픽업해서 다음날 아침에 서울에서 4시간 버스 타고 데려 온 아이 ,, 만들고 다음 날부터 과일에서 물이 나와서 빵 시트로 들어간다고 해서 걱정했는데 넘 맛있더라구용 🩵🩵 어른들도 다들 맛있게 드셨어요 !! 연남동 케이크를 다 먹어본다며 ~~ ㅋㅋㅋㅋㅋ 역시 짱임미당 🥰', 17, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '망고케이크를 한 번 맛본 이후로 매년 사게 되네요. 케이크 먹고 싶을 때 종종 조각으로 먹는데 어머니 생일을 맞이해서 1호로 샀습니다. 망고가 한가득이고 크림도 동물성 크림이라 일반 제과점 케이크와 달리 엄청 부드럽고 맛있습니다.', 20, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '가족들 생일때 마다 찾는 케이크 집 입니다. 부모님&친척들과 함께한 생일 파티 다들 맛있다 했어요 과일도 신선하고 크림도 깔끔하며 가벼운 단맛이라 다들 잘 먹었습니다☺️ 과일이 많이 들어가서 결코 비싼 가격이 아니에요! 항상 잘 먹고 있습니다!!!❤️', 13, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '사진이 예뻐보여서 엄마랑 데이트하러 굳이 먼길로 왔는데 앉자마자 사진찍으려고 보니까 수박음료 위에 올라간 수박이 먹을 수 없을 정도로 농익어서 못먹는거니 위에 수박 하나만 바꿔달라고 하니 이미 한번 나간거고 어제 잘라논거라 바꿔줄 없다고 버려는 준다고 해서 버려달라고 했습니다. 저녁에 주문한 음료에 들어간 과일을 어제 잘라논걸 판매한다는 것도 놀랍고 음료도 커피도 다 맛이 놀랍도록 없었습니다. 저처럼 먼길 수고롭게 오시면 많이 후회하십니다.', 14, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '남자친구 생일 기념 케이크로 안성맞춤이었어요. 망고+샤인머스캣 달달하고 도포된 생크림도 망고향이 은은해서 맛있게 잘 먹었습니다.', 4, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '챗gpt 로  케이크맛집검색해서 방문하게되었는데 와우~ 맛있어요 생크림 많이 달지않고 입에서 사르르 촉촉한 시트와 딸기의 달콤함까지 조화가 잘 이루어져 5분순삭했어요~ 홀케이크 찾으러갔다가 다양한 맛과 비주얼의 조각케이크 맛봤어요~ 홍대입구역근처 오면 다른맛도 맛보러 와야겠어요', 41, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), 'ㄹㅇ 홍대 케이크 맛집 1위 먹는 거 좋아해서 근방의 케이크 다 먹어봤는데 여기가 제일 던 달고 맛있어요 느끼함 없고 입안에서 굴러다니는 크림 아니라서 좋아여', 45, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '아빠 생일 케이크로 너무 좋은 선택이였어요! 평소에 케이크 잘 안먹는 사람이 곧잘 먹으니 그만큼 뿌듯한게 없더라구요ㅎㅎ 과일이 아낌없이 들어가서 정말 만족했습니당 오래오래 팔아주세요~!!', 15, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '생일기념으로 예약해서 예약시간보다 1시간정도 일찍방문했는데도 바로 픽업가능해서 너무 좋았어요!! 진짜 딸기 한가득 미친맛이네요🤩🤩🤩', 35, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '발렌타인데이를 맞이해서 순우유 초코딸기 미니 케이크를 예약해서 받았습니다. 한 번 맛본 이후로 평소 기념일 케이크는 여기에서 꼭 사갑니다. 음료를 위한 디저트가 아닌 온전히 케이크 자체가 정말 맛있습니다. 제철 과일을 활용한 케이크들이 정말 최고에요.', 42, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '케이크 예약 후 픽업했습니다. 안내 사항에 써져있는대로 먹기 전에 한시간 정도 차갑게 해뒀다가 먹으니 더 맛있네요! 갤러리아 백화점에도 매장이 생겨서 더 편하게 픽업했습니다. 딸기가 엄청 많이 올라가있었고, 생크림이 너무 달지 않아서 더 좋았어요. 덕분에 즐거운 생일이 되었습니다. 다음에 또 이용할게요 감사합니다!!', 50, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '당일에 바로 가서 망고케이크 포장했는데 진짜 개존맛 친구들도 다 망고 넘 달고 맛있다고 어딘지 알려달라 했어요. 앞으로도 기념일에 사가려고요!!', 14, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '어버이날을 맞아서 구매했어요^^ 저희 가족이 케이크를 많이 안 먹기도하고 가격이 부담되서 조각케이크로 구매했어요! 망고케이크를 구매했습니다~ 케이크 안에 망고가 알차기 들어갔어요! 생크림도 동물성 생크림을 사용한다고 하더라고요! 다만 바닐라시트 향이 너무 강해서 망고맛을 느끼지 못했어요! 식감만 느낄 수 있었어요! 그래서 망고케이크가 아니라 바닐라 케이크 먹는 맛이랄까?..', 49, 8, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '요즘은 케이크 가격이 너무 사악해서... 어버이날 기념 케이크인듯.. 그런데 위에 토핑된 과일들이 좀 말라있다는 느낌? 암튼.. 조각케이크랑 같이 구입했는데 조각 케이크는 맛있었음', 6, 1, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '어버이날에 케이크 예약했는데 뒤늦게 리뷰 남깁니다. 최근 기념일 케이크는 거의 여기서만 사는 것 같아요 가격도 적당하고 딸기도 싱싱하고 생크림도 맛있고 시트도 따로 놀지않고 맛있습니다. 어버이날 케이크는 가운데 화이트초코로 만든 카네이션 장식이 있었는데 그것도 맛있었고 예뻤습니다. 리본 장식도 좋았어요.', 37, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '얼마전 먹은 ㅋㅊ205랑 맛 비교해보고싶어서 방문했어요! 타이밍 좋게 웨이팅 없이 바로 입장 여덟시 다 된 시간이라 케이크 없을까봐 걱정했는데 다행히 많이 있더라구요! 럭키비키잖앙 🍀 제 입맛엔 ㅋㅊ205 크림이 더 가볍고 맛있었어요! 물론 비포블루밍도 넘 맛있게 먹었어요 🥰 개인적으로 초코보다는 생크림이 맛있어요 커피도 맛있었고 잘 떠들다가 갑니당', 44, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '지난 번 크리스마스 때 비포블루밍에서 맛있게 먹었던 기억이 있어서 아버지 생신 케이크 예약했어요! 크림이 너무 달지 않고 조화로운 맛이라고 좋아하셨습니다 다음에도 또 이용할게요!! :)', 50, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '작년에 이어 올해도 선택한 비포블루밍 딸기케이크!!! 남자친구 생일 겸 7주년 맞이해서 예약구매했어요 둘이서 먹는거지만 그래도 미니보단 큰게 좋아서 1호로 선택했고 딸기가 많이 들어가 있어 엄청 묵직해요 들고다니면 신경쓰이고 무거움ㅋㅋ 그래도 역시 맛있었어요 크림이 느끼하지 않고 고소하고 빵도 부드러워서 아주굿 그리고 딸기도 새콤달달한게 딸기도 잘 고르시는 것 같아용 여기 딸케시즌 땐 꼭 드셔보시는 걸 ㅊㅊ 평일임에도 불구하고 내부자리 만석이었고 제가 케이크 픽업하고 나가니 웨이팅도 하더라고요 ㅋㅋ 역시 디저트 맛잽입니닷ㅅㅅ', 28, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '여기가 그렇게 케이크 맛있다고 해서 친구 생일 케이크로 구입했는데 진짜 맛있더라고요… 가게가 집에서 멀어서 그게 제일 슬펐어요… 그치만 다음에 또 인근에서 생일파티하게 된다면 또 살 겁니다✨', 7, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), 'ᴍ ᴇ ɴ ᴜ 그래놀라애플꿀럼블(9500) + 자몽얼그레이(9000) + 카페라떼(5500) // 케익 가격 비싸지만.. 재료 아낌없이 넣은게 느껴지고 중요한건 맛있어요..! 케익 종류 다양하고 방문할 때마다 바껴있는 라인업에 골라먹는 재미가 있습니다~ 꿀럼블은 조금 딱딱해서 먹기에 힘들었고 많이 달달했어요 ㅎㅎ 제 취향에는(단 거 잘 못 먹는) 자몽케익이 좀 더 잘 맞았던 것 같습니다~~~ 다른 케익들도 궁금해여', 49, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '비포블루밍 딸기케이크는 말해 뭐해요😆💖 달콤하고 부드러운 우유 크림에 상큼달달한 딸기가 왕창!! 정말 많다라는 말로도 부족할 정도로 와르르..🍓🍓 제누아즈는 촉촉하고 사르르 녹아요🤤 1호 크기로 샀는데 3~4명이서 먹기 좋아요!! 물리지 않고 꿀떡꿀떡 들어간답니다..🩷 딸기와 크림 그리고 제누아즈가 완벽하게 조화를 이룬 딸기 케이크를 드시고 싶다면 비포블루밍을 추천드립니다☃️🤍 크리스마스 시즌이여서 귀여운 크리스마스 리스를 꽂아주셨어요!! 산타 곰돌이초는 제가 별도로 구매한 거랍니다.. 너무!! 잘 어울리지 않나요??? 케이크의 귀여움을 한층 더 끌어올려주는 깜찍함이예요🐻 덕분에 너무 멋진 크리스마스 이브 파티를 했어요🥰', 29, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '서울 갈때마다 꼭 가서 먹고 사오는 집이 예요 이번에 아들 생일 까지 있어서 특별한 케익으로 주문했네요 너무 좋아하네요 한번 먹으면 계속 생각나서 또 갈께요', 28, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '이미 알 사람들은 다 아는 가게지만 정말 부드럽고 맛있게 케이크를 하는 곳이에요. 흐를 정도로 소프트한 크림과 빵시트가 특징이고, 느끼하거나 미끌거리지 않고 입 안에서 부드럽게 어우러지는 촉감이 좋습니다. 과일도 넉넉하게 넣어주는 건 덤이라 맛있습니다. 매장에서 피스로 아메리카노와 먹기도 좋지만 특별한 날 홀 케이크로 구매하는 것도 추천드리고, 계절마다 과일이 조금씩 달라져서 고르는 재미도 있어요! 연남 쪽 출구랑 가까워서 접근성도 좋으니 복잡하게 골목골목 찾아가시지 말고 들려보셔도 좋을 것 같습니다~', 100, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '케이크 주문 제작보다 맛있을 것 같고 케익도 훨씬 예뻐서 예약하고 방문했습니다. 화요일로 예약 했는데 사정상 수요일에 찾아야 해서 월요일에 전화로 말씀 드렸더니 화요일 예약 취소 도와주시고 엄청 친절하셨어요~ 초도 다양하고 예쁜거 많아서 곰돌이 하트초로 골랐고 1,100원 추가 결제 했어요! 케익은 정말 맛있었습니다. 딸기도 싱싱하고 너무 달지도 물리지도 않는 맛 이었어요. 기분 내고 싶어서 1호케이크 샀는데 미니 샀어야 됫을것 같아요. 둘이서 밥먹고 디저트로 먹으려니 너무 크더라고여 ㅎㅎ', 74, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '크리스마스 모임때 분위기 내고 싶어서 두 판 주문했어요 ~ 이쁜데 맛있고 딸기가 우르르르르 케이크 픽업하러 갔는데 인기가 많은지 매장 안에도 사람 많고 대기하시는 분들도 계시더라구요. 다음에는 방문해서 다양하게 먹어보려구요 ㅎㅎ', 18, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '딸기 케이크를 먹기 위해 방문했습니다 피스타치오 딸기 케이크와 다른거 하나 시켰는데 (이름 기억 안남) 둘다 맛있습니다 케익이 느끼하지 않고 딸기가 신선해서 부담없이 먹을수 있었어요 다만 케익이 시트지와 크림이 여려겹으로 구성되어 있어 예쁘게 자르기는 어려웠습니다. 단면을 예쁘게 자르고 싶으신 분들은 주의하셔야 할거 같아요 커피는 무난한 맛이었습니다. (이상한 산미 등등 특이점이 없이 무난하게 맛있음) 내부 조명이 외부 햇빛보다 약간 어두워 사진은 누르스름한 느낌으로 찍히는것 같아요 !', 8, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '초코딸기 케이크가 너무너무 맛있었어요! 꾸덕함이 강하지 않아서 끝맛이 깔끔한 케이크입니다. 딸기도 많이 들어있어서 좋았어요. 커피류도 다 만족스러워요!', 40, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '진짜 맛있어요~ 할명수 보고 갔던 케익집중에 제일 맛있네요🍓생크림이 달지 않고 빵은 구름처럼 포근해요🍰❤️커피가 살짝 연한 편이지만 케익이 맛있어서 무조건 재방문 100프로입니다🤍', 47, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '딸기케이크 급했는데 예약을 못했어서 고민하던 중 전화드렸는데 1호가 남아있어 겟헸습니다..! 물량이 적지 않은 것 같으니 깜빡하고 예약 못하신 분들은 전화해서 확인해보세요! 맛은 딸기 푸짐하고 크림이랑 조화 미쳤구.. 진짜 맛있어요!!', 0, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '케이크 너무 맛있어요. 제철 생과일과 어우러지는 케이크는 정말 최고에요. 매장에 항상 사람이 붐비기 때문에 포장해가는 것도 방법인 것 같아요.', 37, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '딸기케이크를 먹었는데 크림이 너무 느끼하지않아서 맛있었습니다. 디저트 비주얼도 그렇고 내부에 외국인분들이 많아서 한국같지가 않았어요. 매장안은 좀 울려서 조용한분위기랑은 거리가 멀었고 화장실은 외부에 남녀공용으로 하나 있는데 성별 나눠서 칸이 있었고 화장실자체 문을 잠그고 사용할수 있는 형태였습니다. 아쉬웠던점은 커피맛이 아쉬웠고 디저트는 딸기가 들어간 생크림케이크는 맛이 좋았지만 초코는 스펀지가 아쉽습니다. 다음에도 간다면 생크림케이크를 먹을것같아요.', 50, 6, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '친구가 생일때 사준 이후로 기념일엔 무조건 비포블루밍 케이크 먹어요!! 케이크 안 좋아하는데 비포블루밍 딸기케이크는 한판 퍼먹을 수 있어요 ㅋㅋㅋㅋㅋ큐ㅠㅎ 비싸지만 비싼값하는 맛 !!!!! 제 인생케이크입니다 !', 2, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '친구 생일 케익으로 초코 딸기 픽업해서 파티하고 먹었는데 엄청 맛있어요 너무 느끼하지 않고 그렇다고 너무 달지도 않고 딱 좋은 맛이었어요 ! 남김없이 다 먹은 케익 입니다 !', 31, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '케이크 정말 맛있어요~ 너무 달지 않고 딸기의 단맛을 방해하지 않아요 생크림도 부드럽고 고급스러워요 빵도 단단하면 맛없었을거같은데 부드러워요... 가족 전부 만족했고 다들 정말 좋아하셨어요~! 나중에 또 방문하려구요 ^^*', 30, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '아이랑 같이 가서 구입했습니다. 홍대 근처에 딸기케익 맛집이 많은데 비포블루밍은 처음이었어요~시트지는 굉장히 가벼운 질감이라서 딸기에 포인트를 준 케익같았어요~생크림도 약간 달긴했지만 동물성 특유의 맛이 느꺼져서 좋았습니다. 비싸긴하지만 딸기가 실해서 만족했습니다!', 101, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '손바닥만한 크기의 쁘띠 케이크가 9,500원. 물가가 올라서인지 원래 이 가격인지 모르겠지만 너무 비싸다 맛은 있으나 딸기케이크보다 12,000원짜리 크레이프가 더 나은것 같기도 함 다행히 크림이 느끼하진 않아서 물리지않는 맛', 20, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '요즘 유행하는 딸기케익 스타일~ 딸기많고 크림 너무 느끼하지 않고 맛있게 잘 먹은 듯 합니다! 어렵게 예약했는데 크리스마스 당일에는 현장수량도 여유분이 꽤 있는 듯 했음. 다음에도 재구매 의사 있어요.', 26, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '부모님 생신 케익이었는데 맛보시고 부드럽고 평소 먹는 케익보다 더 맛있다고 하셨습니다 홍대에 자주 놀러가는 편인데 디저트로 자주 이용할 것 같아요 감사합니다:-)', 40, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '미니 케이크지만 딸기가 정말 알차게 들어있어서 마지막까지 맛있게 먹었습니다. 사이즈는 작은편이라 2-3인 용이구요, 케이크 안좋아하시면 그냥 맛보기 용으로 4인도 가능할듯… 케이크 좋아하시는 분은 혼자도 드실수 있는 양이구요ㅋㅋ 저는 둘이 먹었는데 딱 알맞았습니다. 빵시트보다 크림과 딸기 비율이 많은편이니 참고해주시고, 크림도 동물성으로 고급지고 딸기도 싱싱하며 너무 달지 않고 적당해서 강추합니다🫶🍓', 45, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '딸기케이크 맛집으로 유명하다 !는 이유를 알거 같은 맛이었어요!ㅎㅎㅎ회사에서 다같이 먹었는데 모두들 너무 만족했습니다! 딸기가 일단 진짜 너무 맛있고! 시트사이사이에도 딸기가 많아서 조각내면 딸기가 우르르 쏟아지는 그느낌도 넘 좋았어요ㅎㅎ 최근에 딸기케이크 먹을 일이 많았는데, 또 방문해서 다른 케이크도 먹어보고 싶어졌답니다ㅎㅎ', 81, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '분위기가 너무 좋고 캐롤 틀어주셔서 크리스마스 기분 만땅 ! 느낄 수 있어요 !! 뇨끼랑 파스타 모두 새로운 맛이어서 좋았어요-! 패션후르츠 오렌지 에이드 춫헌 !', 39, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '저희 어무니 생신이라 케이크집을 수색 했는데 평소에 과일 케이크를 좋아하셔서 픽하게 된 곳이예용 저희는 귤 케이크로 픽했는데 그외에도 케이크 종류가 진짜 많도라구요 ㅠㅠ 픽업 오는 사람들도 많았고 카페에 사람도 진짜 많았어요 그와중에 친절 ㅠ 덕분에 생일 파티는 잘 했습니당 🧡', 9, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '압구정 갤러리아 저녁 픽업했습니다 ! 예약날짜가 없어서 23(월) 수령했는데 하루 두었다가 크리스마스 이브에 먹으려고용 맛있으면 리뷰 수정해서 다시 올리겠습니다 ! 딸기 풍성해보이고 너무 기대돼요 !', 83, 13, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '크림이 진짜 가볍게 맛있고 딸기도 많이 들어가 있어서 만족스러웠어요 재구매 의사 있습니다 :> 다음엔 제일 작은 사이즈로 먹어보려구요!', 14, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '정말 좋아하는 케익집이라 자주 들리는 곳인데 1월에 먹었던 그 맛이 아닌 거 같네요... 딸기 당도는 어쩔 수 없지만 생크림 맛이 미묘하게 바뀐 거 같아요 크림 텍스처 자체가 가볍고 많이 달지 않고 느끼하지 않았는데 약간 단 맛이 없다고 해야하나요 전체적으로 크림도 시트도 푸석푸석하고 느끼해졌어요. 평소에 돈값한다고 생각했는데 이번에 받은 케익만 그런 건지 모르겠지만 조금 실망스러웠어요. 🥲', 34, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '덕분에 최고의 레이디나잇아웃✨ 끝내주게 보냈습니다🩷 머리털 나고 먹어본 딸기케이크 중 최고였어요🥰 평생 내 크리스마스 케이크 해줄래...?💍', 7, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '왕복 2시간 걸려서 한파 경보에 사온 케익입니다. 솔직히 저는 일정 정도 이상이면 별 차이를 못 느끼는데 여자친구는 굉장히 맛있다네요. 가격을 제외하면 굉장히 훌륭한 퀄리티라고 생각합니다. 근처에서 샀으면 두고두고 한소리 들었을 거 같습니다. 1주년 기념 케익으로 만족스러웠습니다.', 46, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '25 일 드디어 맛보는 케이크💜💜  너무 맛있었어요!! 가족들이 다 좋아했어요! 다음 생일에도 또 사 먹을 계획입니다ㅎ 그땐 더 큰 걸로 사 먹을려구요~~', 75, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '몇년째 여기서 딸기케이크 구매중 진쯔 너무 맛잇어여 생딸기케이크 중에 1등인듯 다른케이크 절대못머거여ㅠㅠ 평생 팔아주세요 해가 갈수록 더 맛잇어짐', 44, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '가족 생신때 다들 맛있다고 극찬하셔서 연말파티겸 가족과 좋은시간 보내려고 또 예약했어요😋 늘 맛있고 만족하는 비주얼입니다 ㅎㅎㅎ 항상 여기만 찾게 되어요😍', 17, 6, 'GOOD', SYSTIMESTAMP);
