INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '존맛탱입니당!!!! 딸기케이크 한판 퍼먹고싶어서 샀는데 둘이 맘껏 먹고 조금 남겼어용 (1호 구매) 달달하고 딸기도 많아서 만족만족!', 20, 2, 'GOOD', SYSTIMESTAMP);
