INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '아버지 생신 겸 케이크를 예약해서 잘 받앗습니다^^ 덕분에 생신케이크로 잘 썻어요♡♡ 가족들 모두 케이크 최고라고!!^^ 다음에도 여기서 예약해야겟어요!!', 0, 6, 'GOOD', SYSTIMESTAMP);
