INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '🍓딸기도 엄청 많이 가득 들어가 있구요 생크림이 맛있더라구요 5명 가족 모두 눈 깜짝할 사이에 다 먹어치웠어요ㅋㅋㅋㅋ 또 생일이🎂있다면 재방문10000% 생크림 지인짜 개존맛탱👍 와👍', 36, 9, 'GOOD', SYSTIMESTAMP);
