INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '진짜 기념일 마다 여기서 케익 주문해요 가격이 죄금 비싼거 같아도 이쁜데 맛잇기까지해서 그만큼 할만 해요 ㅎㅎ 존맛.......👍🏻👍🏻', 109, 23, 'GOOD', SYSTIMESTAMP);
