INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '케이크 종류가 많아요! 비싼 감이 없잖아 있지만 맛있어서 다 용서가 됩니다… 👍🏻 홀케이크 예약이 왜 이렇게까지 빡센지 알겠네요 ㅎㅎ 딸기도 달고 크림과 조화가 좋아요!!', 41, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '친구들이랑 크리스마스 파티하려고 미리 예약 후 픽업했습니다. 올 겨울은 딸기케이크에 꽂혀서 이것저것 먹어보고 있는데 제 기준 지금까지 먹어본 딸기케이크 중에서는 베스트였어요 ㅎㅎ 시트도 폭신하고 딸기도 달고 다 좋은데 크림이 다른 곳이랑은 좀 다른 느낌이었어요. 너무 달지도 느끼하지도 않으면서도 부드럽고 묵직해요. 여럿이서 같이 먹었는데 모두가 불호 없이 호평이었습니다 ㅎㅎ 덕분에 맛있는 크리스마스가 되었네요! 케이크 종류가 많던데 다음 홍대 방문할 기회가 된다면 다른 조각케잌들도 종류별로 먹어보고 싶어요 :)', 26, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '친구들이랑 크리스마스 기념으로 블루밍 케이크 준비했어요! 딸기 자체도 맛있는데 빵도 촉촉하고 크림도 맛있고.. 그냥 다 너무 맛있고 만족스러웠어요 내년 크리스마스에도 블루밍 케이크 먹고싶어요❤💚🎄', 59, 12, 'GOOD', SYSTIMESTAMP);
