INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '진짜 케이크 속까지 딸기가 가득 차있어서 맛있었어요. 크림도 느끼하지 않아 앉은 자리에서 가족들이랑 한판 뚝딱했네요!! 다음에도 꼭 또 먹고 싶어요 ㅎㅎ', 36, 0, 'GOOD', SYSTIMESTAMP);
