INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '친구랑 3호 케익 예약한거 픽업하기전에 귤케이크랑 초코딸기 시켜서 먹었는데~ 넘 부드럽고 맛있었어요~~~ 3호 케이크는 내일 드릴꺼라~~ 좋아하실거 같아요~~!!', 62, 11, 'GOOD', SYSTIMESTAMP);
