INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '파티 겸 집들이를 위해 예약 후 픽업했었어요! 지인들 모두 케이크 극찬을! 종종 파티때 이용하려구요🥰🤍 디자인도 맛도 너무 좋은것 같습니다', 24, 3, 'GOOD', SYSTIMESTAMP);
