INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '아이 생일이라 딸기케잌이 먹고싶다하여 거리도가깝고 평이좋아 이용하게 되었는데 가격은 좀 있지만 딸기도 맛있고 크림및 빵도 질리지않네요 잘먹었습니다^^', 27, 2, 'GOOD', SYSTIMESTAMP);
