INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '인스타에서 딸기케이크 맛집으로 떠서 저장해뒀다가 방문했어요..!! 요 딸기케이크 입에서 살살 녹고 5분 만에 순삭할 수 있는 맛입니다 ㅠㅠㅠ ♥ 너무 맛있어요!!!!! 가격은 살짝 나가지만 가치 있어요!', 2, 8, 'GOOD', SYSTIMESTAMP);
