INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '망고케잌 맛있게 먹은 기억이 있어서 연말케이크로 구입했는데 진짜 너무너무 맛있어요 ㅠㅠ 여러군데에서 사먹어봤지만 딸기케잌 1등이에요', 122, 21, 'GOOD', SYSTIMESTAMP);
