INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '먹다가 맛있어서 찍어서 사진구린점 양해바라고요 맛있네요 딸기생크림케이크란게 대중화가 많이 된만큼 맛이 비슷비슷한데 그럼에도 여긴 크림의 농도나 달기정도도 좋고 시트도 부드러워서 맛있더라고요.. 다만 딸기 자체는 맛이없었음. 다른 케이크또한 먹어보고 싶은 마음^^', 37, 10, NULL, SYSTIMESTAMP);
