INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '딸기케이크 하나만보고 예약하고 매장에서 먹었는데요 진짜 맛있었습니다ㅠㅠ 포장이면 바로 가져갔겠지만 매장에서 먹는다고 조금 웨이팅은 했지만 다 잊어질정도의 맛이였어요', 21, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '케이쿠 디저트맛집이라구해서 방문했는뎅ㅜ 저녁 늦게가서 케이쿠가 한종류밖에없었지만 넘 맛났습니당 시그니처에이드도 맛있었구용 ㅎㅎ 연트럴파크 바로 앞이라 뷰가 좋더라구용 통유리창뷰에요 쉬다가기좋아용👍🏻🫠', 24, 9, 'GOOD', SYSTIMESTAMP);
