INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '케이크 맛집으로 유명한 연남동카페 비포블루밍. 테이블이 생각보다 많았고 전체적으로 깔끔했어요.여름시즌 피치피치 복숭아케이크, 아메리카노, 오렌지캐모마일 주문했어요. 케이크에 과일이 많이 들어있어 좋았고 음료도 맛있었어요. 홍대카페 비포블루밍 후기 끝 !', 14, 8, 'GOOD', SYSTIMESTAMP);
