INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '원래 홍대에만 있어서 꿈만 꾸고 있었는데 이번에 갤러리아점 예약받아서 먹어봤어요 숫자케이크랑 거의 바슷한 맛이에요 맛있어요! 웨이팅도 없이 예약해놓은거 바로 찾아서 좋았어요', 41, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '24일에 픽업했고 오래 걸릴거라 보온팩 구매가능 여부 확인했으나 3시간까지는 괜찮다하셨는데 그래도 혹시 몰라 구매가능한지 물어봣는데 얼음팩하나 넣어주셔서 밥먹고 집가자마자 냉장고에 넣어놓고 다음날 먹을려고 봣는데 곰팡이가…하나만 그런거겟지하고 먹을려는데 겉에 있는 딸기색이 이상해서 먹어보니까 이미 상한딸기들…안쪽에도 상태안좋은게 딱 티나는 딸기; 5만원 넘게주고 사서 기대했는데 곰팡이핀 딸기에 상한딸기들까지ㅋ 후기보면 괜찮은 케이크들도 많은거보면 복불복에서 당첨이였던건지 그러기엔 싼 가격도 아니라; 다들 이럴수도 있다는거 참고하고 구매하시는걸 추천드립니다', 90, 17, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '크리스마스 케이크로 예약 후 구매했어요 딸기케이크 맛집으로 유명해서 기대하고 구매했는데 너무 실망했습니다.. 맨 밑 시트는 너무 축축해서 물 쏟은 줄 알았어요 밑에 케이크 판에도 축축하더라고요 가족들이랑 같이 먹는데 민망할 정도였습니다 너무 기대가 컸나봐요', 73, 17, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '생일 케익 예약으로 샀는데, 너무 맛있었어요! 생크림도 너무 달지 않고 맛있고 딸기가득한 케익으로 가족 모두 만족!!! 다음에 또 사러 갈게오~', 21, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '숙소로 가는 길에 막 찍은 사진이어서 예쁘게 잘 나오지 못했지만 진짜 예쁩니다!!! 친구 생일을 미리 축하해주려고 준비한거고 친구가 케이크 먹고 너무 좋아하더라고요! 생크림이 고소하고 질리지 않으니까 먹고 또 먹고 싶어지네요🤤 미니 사이즈를 주문했지만 네명이서 먹고도 매우 충분한 양이고 딸기는 정말 달고 많이 들어갔고 가성비가 최고입니다!!', 4, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '케이크 맛있어요~~ 딸기케이크 맛있구 얼그레이케이크 엄청 진해서 맛있어요 사람 엄청 많아요. 저희 다음으로 바로 웨이팅 하더라구요', 105, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '혼자 열심히 먹고 왔어요,, ᴍ ᴇ ɴ ᴜ 무화과수원(8500) + 샤인봉봉(8500) + 카페라떼(5500) // 저녁 시간은 조용하니 책읽고 공부하기 좋았는데 7:30pm 넘어가면서부터 사람들 많아지더니 시끌시끌해져요 케익 맛있고 과일 많이 들어있어서 좋았어요!', 49, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
