INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '케이크 맛있다고 얘기 많이 들어서 기대했는데 생각보다 실망했어요 가격에 비해 딸기가 하나도 안 달고 벽면 딸기가 진짜 얇아서 당황했어요... 반개까지는 안 바랬는데 진짜 너무 얇아서 딸기 맛도 안 날 정도... 시트도 너무 축축하고,, 그래도 기념일이니까 모양은 예뻐서 다행이었어요', 4, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '친구랑 연남동 와서 먹어보고 너무 맛있어서 생일케이크로 예약했어요 제 생일에 먹고 싶어서 직접 예약하고 픽업까지 했습니다! 직원분들 다들 친절하시고 케이크도 너무 맛있었어요 다음 번에는 무화과 케이크도 먹어볼게요', 58, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '진짜 너무 너무 맛있어서 다음에도 또 이용하려고 해요! 디자인이 너무 예쁜데다 특히 케이크 빵은 엄청 폭신폭신해서 먹기 좋았고 딸기도.. 말할 필요 없이 진짜 맛있었습니다! 비포블루밍 케이크 덕분에 여자친구랑 크리스마스 알차고 특별하게 보낼 수 있었어요. 감사합니다!', 12, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '홀케이크를 질러버렸어요. 무화과 케이크가 너무너무 먹고 싶어서 저녁 9시 조금 넘어서 매장에 들렀더니 조각케이크는 다 나갔다는 거예요 그래서 4만 9천원짜리 케이크를 사버린... 😋 집가서 동생이랑 어제오늘에 걸쳐서 먹었네요. 근데 진짜 맛있었어요! 너무 달지 않고 적당히 달아서 제 입맛에 딱이었습니다.', 34, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '가장 작은 사이즈로 구매했는데, 두 명이서 나눠먹기 적당했고 딸기, 생크림, 시트의 조화가 좋아서 너무 맛있게 잘 먹었습니다! 🍓🍰', 95, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '케이크 시트가 부드럽고 맛있어서 너무 좋았어요! 딸기도 신선하고 크림이랑 조화도 너무 좋았습니다. 무엇보다 선물받은 생일 당사자가 너무 맛있다고 좋아했어요!!', 86, 18, 'GOOD', SYSTIMESTAMP);
