INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '점심에 카페에서 먹고 저녁에 또 들러서 포장했어요! 근 2년간 먹은 생크림 케이크 중에 원탑입니다... 망고, 딸기케이크 강추!!!', 17, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '역시 케이크.. 맛집이네요 레스토랑 가서 후식으로 몇 입 먹으려고 했는데 정신 차리고 보니 케이크 판 밖에 안 남았더라고요 일부러 미니로 시켰는데 사이즈 더 큰 걸로 시킬 걸 그랬네요 잘 먹었습니다!', 21, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '망원 한강공원 피크닉 갈때 픽업했는데, 와 생크림 돌았고 딸기도 상큼달콤! 너무 맛있었어요. 최근 먹은 케이크 중에 제일 맛있었어요~ 여름이라 딸기 맛이 떨어지면 어쩌나~ 괜한 걱정 마시고 주문하세요! 너무 맛있습니다🩷 내년엔 꼭 철 맞춰서 복숭아 케이크도 먹어볼거예요~', 72, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '진짜 생각한것보다 너무 무거워서 깜짝놀랬는데 그 무거움을 다 잊게해주는 맛이였어요,,💛 생크림이 너무 안달달한편이라 어른들과함께 잘먹었습니다👍🏻', 18, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '가족 생일이라 1호 구매했어요 6명이서 한조각씩 먹으면 딱입니다~~! 차타고 한시간 거리 이동했는데 아이스팩이랑 보냉가방(5,000원)에 잘 패킹해주셔서 흐트러짐없이 맛있게 먹었답니다😋', 1, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '케이크가 많이 달지않고 맛있어요! 밀크티는 흔히 먹 는 맛에 상큼한 과일맛이나서 맛있어요! 다음에 다른 케이크 먹으러 올것같아요 ㅣ', 51, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '크기는 생각보다 더 아담했지만 둘이서 두 번에 나눠먹기 딱 좋았어요! 그리고 최근에 먹어본 케이크 중에 제일 맛있었어요🤤🤤🤤 흰우유를 안먹는 사람이라 생크림케이크 먹을 때마다 크림에서 우유맛이 진하게 나진 않을지 긴장(?)하면서 먹는데 그러지 않고 딱 맛있는 생크림 맛이었어요ㅎㅎ 느끼하지도 않구요! 과일도 정말 팡팡 들어있어서 최고였습니다..✨️10월에 기념일이 또 있어서 그때 또 주문하려 합니다🤍', 123, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '케이크 모양도 너무 예쁘고 예약하고 가니 대기 없이 바로 받았습니다 직원분들도 친절하셔서 좋았습니다 재방문 의사 있습니다 고생하세요', 8, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '생크림과일케이크 중 단연 최고 비포블루밍 무화과케이크를 먹고나서 맛있는 생크림과일케이크를 찾아다녔으나 비포블루밍 이상으로 맛있는곳은 찾지 못했습니다 ! 무화과와 생크림 그리고 시트가 한입에 들어왔을 때 너무 달지않고 굉장히 조화로웠어요 :) 생크림도 무겁지 않고 시트도 촉촉 !!! 사장님께서 배려해주시고 친절히 대해주셔서 가게를 나오면서도 마음도 따뜻했어요 생일인 친구도 너무 맛있다며 만족하며 먹어서 기뻤어요 ! 얼른 무화과의 계절이 왔으면 좋겠습니다 🤎', 43, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '크리스마스 케이크로 먹었는데 너무나 맛있었어요... 🥹🥹 시트 폭신하고 생크림도 부담없고 딸기가 콕콕 박혀있어서 먹는 내내 행복했습니다 🩷', 80, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '동생 생일케이크로 구매했는데 너무 예쁘고 맛있어서 가족 다 같이 맛있게 먹었어요😆🫶 가족들이 다 케이크를 별로 안좋아해서 일부러 작은걸로 구매했는데 한번에 다먹기 좋은 크기였어요! 다음에도 이용할것 같아요👍', 49, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '비포블루밍 복숭아케이크를 먹어봤는데, 저번 망고케이크가 훨씬 더 맛있어요!!!!! 복숭아는...영 아직 복숭아가 비싸서 그런지 별로 들어있지 않은 것 같았구요, 망고는 진짜 거기 모든 사람들이 감탄하면서 먹었거든요! 크림라벨과 비교했을때, 거기는 버터맛이 더 강한 크림! 여기는 우유맛이 더 강한 크림! 키친205는 요거트 가벼운 크림! 하지만 비포블루밍 망케는 진리입니ㅣ다~🤗👍👍👍👍👍', 56, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '케이크가 맛있다고해서 방문했는데 케이크 안에 과일이 정말 잔뜩 들어있고 너무 맛있었어요 모든 커피 디카페인 선택할 수 있어서 너무 좋아요 >.<', 40, 8, 'GOOD', SYSTIMESTAMP);
