INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '복숭아가 엄청 많은데 그게 엄청 달지는 않아서 케이크랑 오히려 잘 어울렸고 씹는 식감이 좋았어요! 특히 크림 부분이 맛있었는데 싼 느낌이 아니라 고급진 느낌? 시트가 폭신해서 먹기 좋았어유  ୧( “̮ )୨ ✧', 18, 4, 'GOOD', SYSTIMESTAMP);
