INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '크림이 느끼하지도 않고 딸기가 정말 듬뿍들어있어요!!! 아비지 생신 케이크로 주문했는데 어른들 모두 만족하시네요 앞으로 케이크는 정착 예정입니다~~~', 43, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '복숭아 케이크가 맛있어요. 밀크티류도 맛있고 평일 애매한 시간대에 칮아가서 웨이팅이 없었지 주말에는 웨이팅이 있을것 같아요. 케이크 크림이 느끼하지 않고 맛있고, 시트도 촉촉하니 좋네요. 남편과 맛있게 먹고 왔습니다! 케이크🎂  모양도 이쁘고 맛도 있어서 선물용으로 좋을 것 같아요.', 57, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '너무 깔끔한맛 진짜 맛있었어요! 딱 제 취향! 무화과 케익이 이렇게 깔끔하고 맛있는줄 몰랐는데 뒷맛도 깔끔하고 맛있었어요! 😋', 10, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '비포블루밍의 케이크를 거의 다 섭렵해서 무화과 케이크에 도전해 봤는데… 네 명이서 앉자마자 한 판을 해치웠다는 사실 ㅎ 항상 맛있는 케이크 감사합니다 1년에 4번은 꼭 먹는 듯 🥺', 95, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '인생케이크입니다.. 크림이며 빵이며 너무 맛있고 부드럽구요 과일이 이렇게 많이 들어간다고? 싶을정도로 두둑해요 겉에만 과일이고 안은 다 빵이겠지~싶었는데 아니였어요..과일 뚜껑 안에 과일 더미...❤️ 너무 맛있게,덕분에 친구들 생일축하 잘 해줬습니다 직원분도 친절하게 응대해주시고 감사했어요 다음에 또 갈게요:)', 31, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '가격대는 좀 있지만 딱 맛있어서 좋아요. 생일날 케잌을 늘 사먹지만 양이 많으면 남는게 아쉬웠는데 여기서 미니로 구매하면 부족하지도 남지도 않아서 가장 좋습니다. 딸기가 제철이 아니라 상큼한데 그게 생크림의 느끼함을 잡아줘서 더 좋아요. 늘 만족합니다.', 0, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '망고 케이크를 먹으러 왔지만 음료나 커피도 맛있네요. 자리는 많고 창가에 밖에 이쁘게 보이지만 사람이 많고 시끄러운 편이에요. 여유롭게 먹고 싶으면 포장이 좋을 것 같아요.', 10, 2, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '아빠 생신이라 사봤는데 가족 다들 너무 맛있다 했어요😋 여름에 망고 케이크도 엄마생신때 잘 먹었는데 과일이 신선해서 진짜 꿀맛입니다!! 👍🏻', 2, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '맛있어보이는 케이크가 많았는데 무화과가 너무 예쁘게 빛나서 무화과 케이크 먹었어요. 아직 무화과 계절이 아니라서 과일 자체는 덜 달았지만 케이크가 달아서 괜찮았어요. 크림은 살짝 고구마?맛이었고 시트 중간에 과일이 풍부해서 좋았어요. 케이크는 제 입엔 좀 단 편이었어요. 음료도 당도가 있는 편이었습니다. 매장이 넓은 편은 아니에요. 혼자 음식을 음미하기보단 여럿이 와서 이야기 하기에 좋아요.', 55, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '맛있었어요 비싼만큼 재료가 맛있고 신선했습니다 초코 케익 너무 존맛탱이었어요 다시 가도 사 먹을 듯(가격은 약간 사악.. 하지만 그만큼의 가치가 있습니다.ㅎ)', 86, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '무화과케이크 미니사이즈 주문했습니다. 2인이서 먹기에 딱 좋은 크기고 부드럽고 촉촉해서 순삭이에요.. 무화과도 달달하고 부드러웠고, 양도 많았어요! 크림은 말해뭐합니까 꾸덕하고 풍미가 좋아요. 싸구려 단맛이아니라 고급지고 적당히 달아서 아주 좋았어요👍👍 예약시간에 상관없이 당일 아무때나 픽업할 수 있어서 좋았네요. 직원분도 친절하시고 매장에서 귀여운 초도 함께 구매할 수 있어요.', 44, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '케이크 진짜진짜 맛있었어요!! 케이크 평소에 좋아하는편은 아닌데 무화과도 너무 맛있고, 피스타치오 크림도 안달고 진짜 딱 적당한 맛 ㅜㅠ 사진찍을새도 없이 케이크 거의 흡입했어요ㅠㅠ 진짜 꼭 드셔보세요', 45, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '어머니가 무화과 좋아하셔서 무화과 나올 때 구매했었는데 진짜 맛있다고 좋아하셨습니다~! 꾸준히 시즌 메뉴랑 신메뉴 나와서 너무 좋아요! 올 크리스마스 케이크도 비포블루밍이에요~!', 4, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '오우~~~인생 케이크 맛집^^ 케이크 시트가 넘 촉촉하고 부드럽고 크림도 느끼함없이 달달해서 입맛에 딱이었네요! 커피와 너무 잘어울려서 굿굿 👍', 24, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '최근에 기념일이 있어서 케이크를 주문했는데 받는 사람이 너무 좋아한 케이크였어요~~ㅎㅎ 디자인이 세련되고 이쁘고 맛도 정말 좋았어요! 특히 케이크 시트가 정말 촉촉하고 부드러웠고 생크림이 정말 고급진 단맛이였어요! 직원분들이 친절하게 응대해주셔서 기분좋게 픽업할 수 있었습니다^^ 다음에 다시 꼭 찾고 싶은 케이크 가게예요~~', 40, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '케익도 이뻤지만 한입먹고 와~ 감탄사 절로 나왔어요. 많이 달지 않은 과일과 생크림이 너무 부드럽고, 다음날 일부러 다른케익 먹으로 재 방문 드린건 안비밀 입니다.', 47, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '일단, 후회는 안합니다~!! 축하하는 자리에 너무나도 어울리는 비주얼이었고, 정말 빵보다 무화과가 더 많은 케이크였습니다. 맛있어서 다른것도 먹어보고 싶어유!', 11, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '전에 친구들이랑 와서 먹어보고 미친 맛이다! 생각 들어서 이번 엄마 생신 때 홀케이크 예약했어요! 케이크 찾으러 간 김에 다른 조각 케이크도 먹었는데 진짜 너무 맛있었고.., 제 친구들도 여기 자꾸 생각난대요 망케 진짜 맛있거든오ㅠㅠㅠㅠㅠㅠㅠ 사장님 저 또 갈거에요 그런줄 아세요', 83, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '딸기 케이크가 맛있어서 종종 사먹었는데, 여름 복숭아가 나와서 궁금한 마음에 예약했어요! 크림은 부드럽고 복숭아는 적당히 촉촉해서 목막히지 않게 먹었습니다 :) 다만 복숭아가 워낙 촉촉해서 옆에 케이크 커버(?)를 제거할 때 뭉게지지 않게 조심하세요! 홍대 케이크는 여기에서 계속 주문할 것 같아요 :D', 11, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '초코딸기랑 망고, 기본 딸기 케이크도 먹어 봤는데 다 맛있었지만 감히 복숭아는 레전드라고 말할 수 있습니다... 요청드리면 무료로 얼음팩도 같이 넣어 주셔서 항상 케이크 녹지 않게 집까지 잘 가지고 갈 수 있었어요 ㅜ 맛은 기본이고 갈 때마다 너무 친절하게 맞이해 주시는데 안 갈 이유 x 케이크 사갈 때마다 주변 사람들에게 항상 칭찬 듣습니다 -_-v', 50, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '점심 2시반쯤에 갔는데 매장은 좁고 사람이 많아서 소란스럽고 서비스가 별로 였습니다. 지하철타야한다고 말했는데도 에이드를 컵에 담아주고 (샤인머스켓 에이드 시켰는데 샤인머스켓을 뚜껑위에 올려줌. 안에 넣고 뚜껑을 닫으려고 했는데 컵이랑 안맞음) 그리고 두명인거 알면서 포크도 하나만 줌..  케익, 홍차 가격대비 그저그랬습니다. 두번은 이용안할거 같네요', 18, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '연트럴파크 한눈에 보이는 뷰에 일찍 갔더니 여유롭게 먹기 좋았어요. 후르츠케이크 먹으러갔는데 없어서 망고케이크 먹었지만 맛있었습니다ㅠ 사람도 금세 꽉차서 늦으면 웨이팅 좀 있어요ㅠ 날좋을 때 가면 넘 좋아요. 또 케이크 당길때 가야겠어요🍰', 36, 0, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '망고케이크 먹으러 갔다가  다 팔려서 아쉬웠어요ㅜㅜ 대신 베리머치, 베리요거퐁당 케이크 맛나게 먹고 왔어요 산미 맛 선택한 체바내추럴커피랑 잘 어울렸고 덜시고 커피항 좋았어요. 조만간 다시 가렵니다.', 59, 14, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '망고케이크 미니 포장했었는데 너무 예쁘고 맛있었어요! 2-3명이 먹기 좋은 크기여서 좋았고 달달한 망고가 듬뿍 들어가 있어서 정말 맛있었어요 딸기케이크도 맛있어 보여서 다음에는 딸기 케이크로 먹어볼게요!', 35, 3, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '크림이 가볍고 달달하고 딸기가 왕많이 올라가있어요. 크림이 많은 편인데 개인적으로 하루 지난 뒤가 시트랑 크림만이 더 조화로워져서 맛있더라고요', 19, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '2년째 같은곳에서 친구 생파를 하네요+_+ 가깝다면 가족생일케이크로도 맞추고 싶은 곳 빵부분이 입안에서 사르르 녹고 생크림은 너무나도 맛있어 자꾸 생각나는 맛 동네 빵집도 못따라가는 맛이에요+_+ 작년엔 딸기케이크를 했기에 올해는 망고케이크를 했는데 아그냥 다 맛있어 다~ 일곱시좀 넘어 갔는데 어느새 손님들이 들어와서 케이크는 전부다 품절 대박 …!!!! 그만큼 맛있는 곳이라 여기 저기 다 추천하네요+_+', 7, 10, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '옥수수 디저트가 급 땡겨서 호다닥 다녀왔습니다. 매장에서 카드 주문은 키오스크로만 가능한데, 기계가 한대라서 기다리는 저도, 기다리게하는 저도 아주 살짝 불편했습니다. 전반적으로 차분한 분위기는 아닙니다. 유독 그 시간에 계셨던 분들이 유쾌하신 분들이셨는지, 꽤나 떠드는 소리들이 크게 느껴졌어요. 금요일 저녁 7시 좀 넘어서 방문했는데 거의 만석이었습니다. 케이크는 맛있었어요! 요즘 디저트 값이 워낙 비싸니까 주문하면서 손을 좀 떨긴했는데,, 조각만 조금 더 크게 주시면 안될까요🥺🥺 개인적으로 같이 시켰던 차는 입맛에 막 맞는편은 아니었습니다ㅎㅎㅎ', 37, 8, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '평일 만석이었는데 매장은 좁은데 테이블이 많아서 개시끄러움티비...^^ 고막 터지는줄 카페에 쉬려고 갔는데 뭔가 편안한 느낌이 없어요..ㅎ 시끄러워서 직원이 부르는것도 안들리는 수준 케이크 먹을거 아니면 굳이 싶음 아아가 5,300원이고 내가먹은음료는 7천원 가시는분들 참고~~', 19, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '예약한 무화과 홀케이크 픽업하면서 피치피치 단품조각이랑 아이스아메리카노 따로 포장했는데, 단품을 복숭아케익으로 안 주시고 무화과 케익으로 주셨네요..... 복숭아 먹고싶었는데ㅠ 사람도 많고 바빠 보이셨는데 담번에는 잘 확인 부탁드려요ㅠ', 43, 8, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '알바생 진짜 싸가지 존나없네요 ㅋㅋㅋㅋㅋ 복숭아케이크 예약하고 갔고 요청사항에 생일케이크니까 촛불 부탁한다고 써놓았는데 케잌만 주시길래 요청사항에 나이랑 초 갯수 적어놓았다고 하니까 원래 요청사항 잘 안 봐요라는 답변이 정상적인 답변인가요? 또 따로 판매하는 귀여운 소품도 삿는데 결제 다 됐나요 물어보니 영수증 나오자마자 쓰레기통에 버리면서(벽쪽으로 걸어가며) 안녕히 가세요 해버리는데 보통 영수증 받을건지 물어보고 그 전에 결제 된건지 물어보면 답변을 해야 정상아닌가요? 무슨 알바생 교육을 이따위로 시키는지 생일케잌사러왔다가 기분만 잡치고 가네요 ㅋㅋ 맛이고 뭐고 고객응대가 이 정도면 잘되긴 글렀네요', 73, 16, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '딸기케이크 좋아하는 우리언니 생일에 선물해 줬습니다. 스트로베리32 케이크도 사줬었는데 비포블루밍 딸기 케이크가 더 맛나다고 하네요(개인적인 취향입니다;;) 생크림이 달지 않고 부드럽고 딱 맛있습니다. 딸기케이크인데 당연히 딸기도 신선하고 좋지만 생크림이 정말 맛있습니다. 완전 강추 👍', 73, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '케익 종류가 다양했고 얼그레이 자몽 케이크 맛있었어요 무난무난한 카페 공간은 협소하고 전체적으로 화이트톤의 모던한 카페 2층 매장에 층고가 낮고 공간이 협소하다보니 대화소리가 많이 울립니다 테이블 간 가까워 아늑함은 없는 느낌', 43, 6, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '생일 케이크용으로  1호 예약했습니다! 네이버 예약으로 하니 예약, 픽업 모두 간편했어요👍🏻 잘 익은 달달한 망고들이 가득 들은데다 화이트 초코? 맛이 나는 크림에 촉촉한 시트까지 어우러져서 너무 맛있게 잘 먹었습니다😋 다른 케이크들 먹으러 또 가야겠어요..🤤', 32, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '무화과 케이크 너무 맛있습니다~ 와이프 생일 케익으로 예약 주문했는데 와이프가 너무 좋아하네요~^^ 맛도 좋고 너무 이쁘다고요~^^', 89, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '살구홍차 밀크티는 처음 먹어보는데 맛있었어요! 케이크 생크림도 느끼한 생크림이 아니라서 너무 좋았습니다! 6시 좀 넘어서 가니 케이크 맛집답게 많이 품절되어있더라고요 다음번에는 일찍 가서 다른 메뉴들도 먹어보고싶네요!', 6, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '솔직히 홀케이크 가격 미쳤다고 생각함 쥐콩만한게 4만원... 진짜 비교불가한 맛으로 승부보는 그런 유명 디저트집도 아닌데ㅎㅎ 급해서 어쩔수없었지만 절대 재방문 의사없는 요즘 딱 감성 플미 엄청 붙이는 그런 디저트 카페st', 7, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '망고가 사실 맛없없이긴 한데 여긴 생크림 자체가 넘 부드럽고 맛있어요! 호로록 한 판 다 먹게 되는 케익이라 기회될때마다 예약합니다ㅎㅎ', 21, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '케이크는 크림이 너무 맛있고, 자몽과 잘 어울려서 또 먹으러가고싶어져요. 밤 9시쯤 갔는데 인기가 많아서 마지막 케이크였고, 뒷분들은 품절되어 못먹었습니다.. 완전 러키비키🍀', 10, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '맛있긴하지만 35,000에 이정도 크기는 쌉에바인듯하네요..^^ 가격에비해 크기가 너무나도 작으니 큰거 선물하실분들 3-4인용으로 가시길…', 80, 12, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '어버이날 케이크에 만족해서 두번째 예약을 했었습니다. 요거트 크림을 베이스로 해서 크림이 물리지도 않고 블루베리도 통째로 가득히 들어 있어서 같이 먹는 부모님이 크게 만족했어요. 특히나 더 맛있다고 말해주셔서 다음에 기회가 된다면 다른 케이크도 사볼까 합니다. 개인적으로 역대급 블루베리 케이크라 생각하기에 꼭 추천드립니다.', 1, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '직원은 매우 불친절해요 눈도 안마주치고 알아듣지도  못하게말하고 안내도 없고 케잌에 초 안주냐고 물으니 짜증스럽게 대답하고 초추가구매해도 시큰둥 예약한거 찾는데 5분도 안걸렸는데 날씨도 더운데 진짜 기분상했네요  다시  가고싶지않아요', 94, 23, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '내돈내산인데요 망고가 잘 익은거 넣으려는 의도는 알겠지만 약간 까맣게 변한것들이 있었어요. 그리고 케익 먹다가 이런게 나왔는데 망고에서 나온게 아니예요. 망고에 가끔 이런게 나올때가 있는데.. 이건 제가 빵 먹다가 발견한거구요. 재방문 의사는 없습니다. 직원도 불친절하던데 전 사실 불친절한건 별로 안따지는데 케익 퀄리티가 별로라서 이마저도 좀 별로', 12, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '친구 생일케이크로 예약하고 방문했어요! 예약하기 어렵지않고, 친절하셔서 좋았구요 케이크 크림이 가벼운 편이고 딸기가 산뜻해서 디저트로 딱이였어요🥰 다른 케이크도 실하니 너무 맛있어보여서 다음엔 매장 이용해보려구요!', 47, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '살구홍차 밀크티가 너무 맛있어요... 너무 달지도 않고 살구향이 은은한게 제가 먹어본 밀크티 중에서 최고입니다 ㅜㅜ 음료 한잔에 8000원이라서 가격은 좀 부담되지만 그만큼 맛있어서 다시 방문할 것 같아요 망고케이크도 맛있었어요~! 친절하시고 좌석도 깔끔해요 👍🏻', 30, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '엄마 생신이셔서 홀케이크 예약했습니다!! 망고도 너무 실하게 들어있고 크림도 시트도 맛있어서 기분좋게 생일파티 마무리했습니다~!! 다음 기념일에도 예약예정입니다^0^', 28, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '세상에 이렇게 물리지 않고 맛있는 케이크는 처음이에요 !!!!!! 크림은 가벼우면서 과일은 묵직하고 빵은 촉촉하고 부드러웠어요😍 케이크 한 조각 겨우 먹는 사람인데, 이건 한 자리에서 한 판 다 먹었네유ㅋㅋㅋㅋ 짱짱 추천입니다 다양한 과일들이 들어있어서 골라먹는 재미도 있고! 과일 당도가 미쳤어요;;', 48, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '특별한날이라 망고맹고케익을 주문했구요, 너무너무너무맛있게 다같이 잘 먹었어요!! 비쥬얼만 맛있는게 아니라, 진짜 맛있었어요❤️❤️', 24, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '케이크 포장도 깔끔하고 보기에는 너무 예뻤는데,, 맛이 너무너무너무너무 별로예요 여름딸기라는걸 감안해도 딸기가 신걸 넘어서 무맛 그자체... 이정도 맛이면 여름에는 그냥 딸기케이크 판매안하시는게 맞는 거 같아요 다른 업종들도 괜히 판매안하는 이유가 있는게 아니겠죠~ 다들 여름에 딸기케이크 먹고싶어서 저처럼 파는 곳 찾고 찾아서 오시는 걸텐데 이런 맛은 너무 실망스럽네요ㅜㅜ', 63, 14, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '케이크를 구매해야 해서 찾아보다가 리뷰에서 평과 케이크 사진을 보고 구매를 결정했었는데, 딸기가 일단 정말 신선하고 맛있어서 70퍼 센트는 먹구 들어가구 케이크 시트 자체도 맛있어서 나머지 부분을 다 채워준 것 같아요 케이크 퀄리티가 좋았어요! 딸기 생크림 케이크를 원래 좋아하는데, 지금까지 중에 탑3에 들어갈 것 같아요!☺️☺️', 39, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '어버이날을 급하게 준비하다가 케이크 예약할 곳을 찾다가 방문하게 되었어요. 금방 예약했는데도 바로 케이크를 가지고 갈 수 있었네요. 맛은 물론이고 카네이션 장식도 생화라 깜짝 놀랐습니다. 같이 구비된 초도 챙겨 가져가니 기억에 오래남을 추억을 하나 만들었습니다. 부모님도 만족하신 딸기 케이크고 다른 케이크도 궁금해집니다. 쇼케이스에 있던 케이크들을 보니 평일에 한번 더 방문하고 싶어집니다. 덕분에 맛있는 케이크 잘 먹었습니다.', 109, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '4번째 방문입니다 ^^ 기념일마다 주문해서 케익은 종류별로 다 먹어봤어요~ 존맛탱👍👍 아! 밀크티도 맛있어서 동생이 항상 주문해서 먹어요ㅋㅋ', 41, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '딸기케이크가 먹고싶어서 찾다가 우연히 가게되었어요. 친한언니랑 가서 둘이 먹고싶은 케이크 하나씩 골라서 먹었는데 케익들이 다 맛있어요!! 먹으면서 수다도 떨다가 배우 조재윤씨도 보고왔네요ㅎㅎ 케익사러 오셔서 직원들도 알아보셨던데 저희는 직원도 아니고 실례일까봐 아는체는 못했지만 신기한 경험이었어요ㅎㅎ 케이크가 맛있어서  집 갈때 초코딸기케이크도 한조각 포장해갔어요. 초코도 맛있는데 생크림딸기가 더 취향이었고 귤케이크도 궁금해서 담에 또 와보려구요', 4, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
