INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '친구 군대 가서 잘 다녀오라는 선물로 케이크 포장해서 선물했는데 정말 맛있었대요! 예쁘고 맛있는 케이크로 선물 하는 사람도, 받는 사람도 기분 좋게 해주셔서 감사합니다 :)', 76, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '박명수 딸기케이크 유튜브보고 남자친구 생일 케이크로 예약해서 먹었는데 진짜 예쁜데 맛도 있었어요 ㅎㅎ 딸기도 한가득들어가는데 딸기도 맛있고 크림도 진짜 맛남 그리고 케이크 픽업하러 갔는데 왜 웨이팅까지 하면서 먹으려하는지 이해가 가더군요 ㅋㅋ', 6, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '생일케이크로 남자친구가 예약한 보늬밤마스크치즈케이크에요 🌰 🤎 한조각에 8,200원이여서 8조각하면 홀케이크로 65,600원입니다~~ 다른 홀케이크보다 비싸 보이지만 데코밤 진짜 완전 크고 실하고 최고급 밤이에요!!! 너무 맛있어요!! 근데 이 밤들이 바닥에도 엄청 많아요 진짜 대박... 그래서 케이크 자체가 엄청 무겁드라구용!?!? 그만큼 밀도 있고 오래 먹을 수 있어요 🤎🤎 바스크치즈케이크도 진짜 너무 맛있구 위에 크림이랑 오레오두 맛나요..ㅠㅠㅠ 다음엔 조각으로 주문해서 커피랑 도장깨기 해보려구요 즌맬 존맛..ㅠㅠㅠㅠ', 14, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '딸기케이크 먹고 싶어서 눈돌아가기 직전에 사먹었네요 버터시트라더니 시트가 폭신하면서도 부드럽고 풍미가 좋아서 입안에서 케이크가 사라져요 진짜 맛있었어요 앉은자리에서 미니케이크 순삭했습니다 서울딸기케이크맛집 인정이에요', 5, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '생일케이크 예약하고 방문했습니다 ! 방문 한 김에 딸기 망고 케이크 주문해서 맛있게 먹고 왔어요:) 정말 맛있..ㅎㅎ❤️💛 또 먹고 싶어요 재방문의사있습니다! 추천드려요b', 48, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '역 나오자마자 있는 카페라 밥먹고 쉬어가기 딱 좋은 곳이에요 제가 갔을 때(토요일) 기준으로는 오후 3시 전에 가야 딱 적당한 것 같아요 한 3시 반부터는 매장 자리가  꽉 차더라구요', 34, 5, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '비싼만큼 과일도 신선하고 빵도 너무 촉촉해서 맛있었어요💖 부모님도 맛있게 드실만큼 너무 달지 않고 느끼하지도 않은 생크림 케이크라 좋았어요:) 부모님이 태어나서 먹은 케이크 중에 가장 맛있었다고 극찬을 해주셔서 괜히 제가 뿌듯했답니다🤭 집과 조금 멀기도 하고 가격대도 있었지만 충분히 가치가 있었어요! 즐거운 추억 선물해주셔서 감사합니다💕', 4, 8, 'GOOD', SYSTIMESTAMP);
