INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '맛있는 케이크가 있는 곳이에요 생크림 초코 딸기 케이크 둘다 맛있어요 근데 내부가 만석이니 많이 시끄럽더라구요 한시간 못채우고 먹고만 나왔네요ㅠ', 51, 17, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '과일로 만드는 맛있는 케이크를 파는 카페! 홀케이크로 주문해서 픽업하러 갔어요. 카페는 평일인데도 워낙 인기가 많아서 만석이고 정신없었어요. 그렇지만 케이크 퀄리티는 끝짱납니다!!', 3, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '포장하러 방문! 평일 오후4시였는데 협소한 공간이지만 생각보단 자리가 많았구 만석이었어요 케잌이 5가지 종류가있었는데 초코딸기랑 귤 포장! 집에 포장해가면 다들 한입씩만 먹어서 한두개만 포장해가는데 엄마가 많이 달지 않고 너무 맛있다면서 한조각 거의 다먹고 아쉬워하시더라구요.. 이렇게 극찬한곳은 처음! 담에 또 다른 종류로도 포장 해야겠어요 ㅎㅎ', 34, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '망고케이크 비주얼 보고 기념일 케이크로 바로 예약했어요 픽업도 빨랐고 무엇보다 망고시루 부럽지 않았습니다!! 망고가 진짜 달고 생크림은 적당히 달아 잘 어울렸어요 겨울에 딸기케이크도 궁금해졌어요', 99, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '친구생일축하해주려고 연남동에서 찾은 조각케이크맛집이에요 모양부터 맛있어보이네요 공휴일 오후에 간거라 종류를 다양하게 못봐서 아쉽네요', 3, 1, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '망고케이크 너무 맛있어요..!!!!!💚 너무 부드럽고 많이 달지도 않으면서 맛있어서 먹는내내 기분 좋았습니다ㅎ.ㅎ 케이크먹고 이렇게까지 만족하는거 처음이에요!!', 27, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '친구생일케익 미리 예약하고 방문 했는데 자리도 딱 있고 픽업 시간 정해둔 시간 이후로 아무때나 상관이 없어서 자연스레 카페에서 주문하는 척 하고 픽업시 케익 말씀드려서 서프라이즈 성공 했습니다🎂딸기케익,블루베리케익 다 맛있고 키오스크로 주문 할 수 있어서 간편했어요:) 또 생각나는 맛ㅎㅎㅎ사람 많은 이유를 알겠더라구요🍓🍓', 48, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '인스타에서 유명한 카페더라고요! 케이크는 타르트 식감일 줄 알았는데, 카스테라같이 푹신하고 부드러운 케이크 시트였어요. 편하게 머물다 가요! 우롱차 맛있습니다.', 3, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '케이크 생크림도 맛있고 샤인 머스캣도 신선한 듯 달아서 맛있었음! 밀크티 맛집이라던데 살구맛이 은은하게 달아서 내 취향이었다 다음에는 딸기 케이크 먹으러 또 방문하고 싶은 카페 늦게 가니 케이크가 많이 안 남아있더라고... 다음엔 더 일찍 가기로.', 41, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '항상 기념일있을때 이용하는데 선물받는 사람들도 좋아하면서 맛있다고 칭찬해줄때마다 뿌듯하고 저의 최에 맛집을 소개해주는데요 이러다가 완전 인기폭팔!!!하시는거 아니에요?!!!!!🫶🫶🫶', 18, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '부모님 생신으로 케이크 사러갔다왔는데 비주얼이 장난이아니네요 딸기가 진짜 많았고 맛있었어요 크림도 엄청 부드러워서 여러개 먹기에 부담이없이 먹었던거같아요', 5, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '홀케익 예약 후 픽업하러갔는데 3층에 위치해있었고 직원분이 친절하게 응대해주셔서 좋았어요. 딸기도 엄청 맛있고, 크림이 느끼하지 않아서 맛있었어요. 시트도 촉촉한 느낌이라 부드러웠습니다. 덕분에 즐거운 생일 챙겨줬네요. 다음에도 또 예약할게용 ㅎㅎ', 106, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '사람이 너모 많아요.. 우아 만석일 줄 몰랐어요 포장하러 간거긴한데 ㅎㅎ… 홀케이크는 고정이 따로 안되있어서 신경써서 잘 들었는데도 살짝 기울어도 치우쳐지더라구요 ㅠ 다행히 망가지진않고 기울기만 했어요 좌석은 많지않고 카운터앞에 테이블 몇개 있어용', 17, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '예약 후 방문해서 웨이팅 없이 바로 입장했는데 사진대로 케이크 잘챙겨주셔서 감사했어용🫠🫶 귤 케이크라는 메뉴가 독특해서 생일 케이크로 구매했는데 후회없는 퀄리티와 맛이라서 가족과 하루만에 클리어했어용!✌️ 다만 치아가 약한 저희 아빠가 먹기에는 귤이 질겼다고 하더라구요 그리고 집까지 1시간 걸리는데 대중교통을 이용하다보니 데코가 떨어지기도 해서 고정력이 조금은 아쉬웠어용... 고정되는 부분에서 개선이 필요할 것 같아용 이 부분 빼고는 다 맘에 들었어요! 생일이나 기념일 때마다 애용하는 곳이에요!! 디저트에 미친년인데 매번 만족스러워요🧡✨️ 덕분에 행복한 생일 보냈어용~🧸🎂', 83, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '썸네일 딸기케이크 사진 보고 우와 하고 갔는데 다른 케익 종류가 엄청 많았어요!!!! 쇼케이스 앞에서 정말 한참 고민하다가 어렵게 골랐습니다 요즘 카페 가격이 다 이렇긴 하지만.. 쪼금 비싼 것 같아요 몇 번 뜨면 순삭ㅠㅠ 그치만 이 카페는 연남 초입에 있고 2층에서 거리를 내다볼 수 있는 뷰가 좋은 것 같아요 의자가 불편해서 아쉽습니다', 30, 2, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '초코 필링이 샘플 사진처럼 흘러내릴정도로 가득 할 줄 알았는데 위에만 있어서 조금 아쉬웠어요 ㅠ 그래도 아버지 생신케이크로 맛나게 먹어서 추천드립니다', 183, 87, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '딸기생크림케이크로 유명해서 예약하고 매장에서 먹었는데 너무 맛있었어요 크림이 딸기랑 정말 잘 어울리는 맛의 크림이고 딸기도 엄청 많이 들어있어요 그리고 딸기도 달고 맛있어요 재방문 의사 있어요👍🏻👍🏻', 26, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '딸기케이크에 딸기가 많아서 좋았어요. 가격대가 조금 있긴 합니다만 디자인이 예쁘기도 하고 맛있어서 선물용으로도 좋을 것 같습니다.', 41, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '저번에 먹었을 때 너무 맛있게 먹어서 기념일겸 먹으려고 예약했습니다~ 맛있는 케이크이지만 케이크에서 기다란 종이 시트? 같은 것이 나왔어요... 먹다가 입에 이상한 이물질이 느껴지길래 뺐는데 저런 게 나와서 좀 당황스럽네요', 105, 25, 'BAD', SYSTIMESTAMP);
