INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '진짜 ... 존맛탱 ..... 인생 딸기케이크됨 ... 좀 가격대가 높긴 하지만 그만큼 만족합니다 별 일 없어도 사먹고 싶네요', 140, 71, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '가을가을한 연트럴파크 뷰를 즐기기에 좋은 디저트카페를 찾아 넘 기쁩니다 :) 시원한 통창으로 보이는 가을 단풍을 보며 향긋한 밀크티와 커피, 달콤한 무화과케이크까지 넘 완벽했어요! 케이크도 맛있지만 밀크티가 정말 마음에 쏙들었어요~ 밀크티 좋아하시는 분들은 꼭 들려보세요 :)', 8, 7, 'GOOD', SYSTIMESTAMP);
