INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '역에서 가까운 카페 찾는데 여기가 케이크 맛집으로 유명하더라고요. 커피 종류별로 원두도 선택할 수 있고, 케이크 종류가 다양해서 좋았네요. 매장이 조금 시끄러운 편이기는 했지만, 덕분에 눈치보이지 않고, 대화하기에는 편했어요.', 2, 10, NULL, SYSTIMESTAMP);
