INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '가격은 조금 비싼 편이지만 너무 맛있어요. 알차게 들어간 딸기도 달콤하고 특히 생크림이 정말 맛있네요. 원래 생크림 느끼해서 안 좋아하는데 이 집 크림은 느끼함없이 상큼하고 맛있어서 놀랐어요. 비주얼도 예뻐서 기념일에 주문하기 딱 좋아요', 72, 13, 'GOOD', SYSTIMESTAMP);
