INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '크리스마스 케이크 예약해서 픽업받아왔어요🍓 금딸기여서 가격이 너무 비쌌지만 그만큼 장식도 예쁘게 잘 되어있어 기분내기 좋았어요 :) 딸기도 맛있었구요 직원분도 친절~', 9, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '딸기가 가득 차 있는 맛있는 케이크였습니다! 티켓팅까지 하면서 먹은 보람이 있네요 👍 덕분에 즐거운 크리스마스 보냈습니다. 감사합니다~', 19, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '딸기케이크 유명해서 먹으러 갔는데요. 자리도 넉넉해서 웨이팅 없이 들어갔습니다. 딸기케이크의 빵은 진짜 촉촉하고 부드럽구요. 딸기도 맛있고 진짜 많이 들어가있었어요! 추천추천 왕 추천 입니당', 46, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '연남동가서 밥먹고 난 뒤 맛있는 후식이 먹고 싶어서 찾아보다가 간 곳인데 밀크티랑 케이크 맛집이더라구요👍 케이크는 가격대가 살짝 있는편인 것 같은데 케이크에 생크림과 과일등이 진짜 푸짐없이 들어가 있어서 그 생각이 쏙 들어가더라구요 저는 밀크티를 선호하지 않는 편이라 스트로베리밀크티를 시켰는데 와 진짜 밀크티맛이 살짝나면서도 딸기우유와 조화롭게 어울려러 넘 맛있어요🥹 진짜 케이크랑 밀크티 맛집이에요. 연남동 가시면 꼭 먹어보세요 강추합니다.', 77, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '케이크 예쁘고 귀엽습니다 가격은 요즘 케익값 생각하면.. 돈 벌면되죠😊😊 좌석은 있지만 오밀조밀이라  앉아 먹기엔 협소한 장소입니다 픽업해서 기념일 보내기엔 좋은 것 같습니다❣️', 16, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '케이크가 솔직히 비싼데 정말 맛있습니다. 크림이 진하고 정말 맛있는데 딸기도 듬뿍 들어서 진짜 맛있게 먹었어요! 요즘처럼 과일 비싼 때에 딸기 질이 정말 좋아서 진짜 맛있게 먹었습니다!', 124, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '🍓먹은 것 - 초코에빠진딸기 (조각)9,000 🪑자리 있음 사진상에는 잘 안보이지만, 딸기가 매우 듬뿍 들어있어 만족스러웠음. 사실 딸기없이 초코시트와 크림만 먹어도 충분히 훌륭한 맛. 시트 윗부분에는 초코코팅이 되어있어 브라우니 같은 식감. 주말 오후 5시 이후 방문하니 이미 케이크는 다 품절이라, 마지막 하나 남은 것을 포장했음. 엘리베이터 없는 작은 건물 3층에 위치해서 접근성은 다소 떨어짐.', 11, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '크리스마스 다음날 하는 곳이 많지않아서 찾다가 겨우 예약했는데 너무너무 맛있습니다!! 무슨 크림 쓰시나요?? 너무 맛있어요🥹 가족들이 다 케이크를 많이 못먹는데 많이 달지않고 적당히 달콤해서 배부른데 반 판이나 바로 먹었어요! 딸기도 엄청 많고 중간에 빵도 있어서 너무 맛있었습니다:)', 9, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '딸기도 엄청 많았고, 무엇보다도 크림이 느끼하지 않고 술술 들어갔어요. 근데 미니가 생각보다 작아서ㅋㅋㅋㅋ혼자서도 그 자리에서 다 먹을 수 있는 양입니다. 손바닥 펴면 손보다 좀더 작은 크기라고 보시면 됩니다.', 14, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '맛있어요 근데 무화과랑 복숭아 케이크 사려고 간건데 없어서 물어보니까 여름 메뉴라고 하더라고여.. 네이버 메뉴에 별 안내없이 올라와 있길래 몰랐음 두조각 포장했는데 케이크 실 사이즈가 넘 작아서 아쉬웠어요.. 한 번 쯤 먹어보는 건 괜찮은듯', 42, 9, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '베리머치, 무화과수원이라는 조각 케이크와 아메리카노 고소, 산미 버전 각각 한 잔씩 주문드렸어요. 지금 딸기철이 아닌데 생딸기 케이크가 있는게 신기했구요. 맛도 좋았어요. 무화과 케이크도 무화과가 너무 신선해서 엄청 맛났구요. 여긴 생과일 케이크 먹으러 오는 곳인거 같아요.', 3, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '요즘 딸기에 꽂혀 있는 사람입니다ㅎㅎㅎ 딸기 케이크 맛있는 곳!! 찾다가 이 곳을 발견해서 처음 먹어봤는데요.. 딸기 싱싱하고 많이 들어있고 가격이 아깝지 않는 맛이네요!!😍🍓 친구 케이크 준비 여기로 하길 잘한 것 같아요~! 진짜 만족스럽습니다:D 강추~~~', 11, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '귀여운 초가 종류별로 엄청 많아서 좋았던 곳•••☃️♥️ 당연히 시그니처 딸기생크림케이크는 존맛탱이였습니다,,,, 근데 라떼가 진짜 띠용스러울 정도로 맛있었어요🙄 우유가 뭔가 다른건지,,, 뭐지,,,? 양이 조금 적은 편이지만 전혀 불만이 없었습니다 후~ 맛있어서 용서됨🥹 재방문 의사 있습니다!', 35, 5, 'GOOD', SYSTIMESTAMP);
