INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '이브에 예약 없이 가서 웨이팅이 조금 있었어요 딸기 케이크 먹고 싶어서 갔는데 딸기 종류는 다 품절이더라구요 ㅠㅠ 아쉬운대로 샤인머스켓 케이크를 먹었는데 맛있었습니다! 특히 크림이 맛있어요! 커피는 그럭저럭 무난합니다', 8, 2, NULL, SYSTIMESTAMP);
