INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '연말파티 때문에 케이크 준비햇는데 다들 너무 예쁘다고 사진 엄청 찍고 식사 배부른 상태에서 디저트로 먹었는데 맛있어서 순삭 당함.. 호텔 케이크 보다 훨 나은것 같음. 다음엔 다른 과일케이크 주문 할께요! (산타할아버지 초는 매장에서 판매합니다)', 79, 18, 'GOOD', SYSTIMESTAMP);
