INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '초코에빠진딸기 케이크 먹었는데 초코가 많이 안달고 진해서 참 맛있었습니다! 저녁시간에 갔더니 홀케익은 없었어서 조각 구매했어요. 홀케익 원하시면 미리 예약하셔야할 것 같아요!', 0, 8, NULL, SYSTIMESTAMP);
