INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '진짜 진짜 진짜 너~~무 맛있어요 ㅠㅠ 친구들이랑 다같이 파티를 하기로 해서 케이크를 고민하다가 저번에 먹었던 비포블루밍이 생각나서 바로 예약했어요 파티에서 케이크 꺼내고 5분만에 다 먹었습니다 ㅎㅎ 그정도로 너무 맛있었고 친구들 모두 만족했어요😍 과일케이크는 케이크 안에 들어가는 과일이 진짜 중요하다고 생각하는데 과일 정말 신선하고 달고요 크림이랑 빵도 너무 맛있어요 다음에도 비포블루밍에서 케이크 사려구요❤️', 3, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '생일케이크로 준비해봤어요! 처음맛보는 딸기 넘치는 케이크였습니다🍓❤️🍓❤️ 빵보다 딸기가 많은 너,,, 🤍 케이크 맨 밑에는 일반 케이크시트가 아닌 카스테라같은 케이크시트여서 맛있었고요! 크림도 산뜻해서 정말 맛있게 먹었어요 생일자도 만족한 케이크였습니다!', 13, 6, 'GOOD', SYSTIMESTAMP);
