INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '연트럴파크뷰가 보이는 깔끔한 카페로 케이크 맛집이네요! 제철딸기가 왕창 박힌 초코케이크도 넘 맛있고 헤이즐넛 라떼도 너무 달지도 않고 맛있어서 재방문 의사 100% 입니다!', 46, 1, 'GOOD', SYSTIMESTAMP);
