INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '크리스마스에 젤 기대했던게 케이크였는데 훌륭한 비주얼 만큼 너무 맛있게 연휴 내내 먹었어요!! 🍓🍰 딸기가 신선하고 크림도 맛있고 시트도 부드럽고 아주 좋았습니다!!', 59, 13, 'GOOD', SYSTIMESTAMP);
