INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '생크림은 달지 않았으나 시트가 너무 퍽퍽해서 맛이 없..우유 없으면 잘 안 넘어 가는맛🥲 커피랑 갸우 넘겼는데 ㅋㅋㅋㅋ 휴 극찬하던 케이크던데 사실 이해가 안가는 맛입니다. 그냥 아쉬울 따름.. 그리고 불친절하다는 글 많이 봤는데 친절하지도 불친절하지도 않은 딱 그 정도 였어요.', 34, 9, 'BAD', SYSTIMESTAMP);
