INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '딸기케이크를 먹고 싶었지만 좀 늦게 가서 샤머 케이크밖에 없더라구요 근데 얘도 맛있었어요!!! 다음에는 일찍 가서 딸기도 먹어봐야겠어요', 23, 8, 'GOOD', SYSTIMESTAMP);
