INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '케익 맛집!!! 음료도 맛집! 통창뷰랑 분위기가 예쁜 카페예요 다른 메뉴들도 다 맛있었는데 케익이 메인이 되고서 없어진게 조금 아쉬워요 언제가도 친절하셔서 좋습니다 감사합니다👍🏻', 26, 5, 'GOOD', SYSTIMESTAMP);
