INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '웨이팅 잠깐 했는데 헷갈리셔서 잘못 입장해서 나갔다가 다시 입장했어요 ㅠㅠ 그래서 그런지 케이크 먹으려고 웨이팅 할 정돈 아니라고 느꼈습니다 가격이 싼것도 아니고.. 작은 장소에 테이블이 많아서 얘기하는데 크게 얘기해야 들릴정도입니다 좀 아쉽네요', 47, 4, 'BAD', SYSTIMESTAMP);
