INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '포장해서 조각케이크 귤이랑 샤인머스캣 사서 밀크티랑 먹어봤는데 진짜 제 스타일이구 넘 맛있었어요 그래서 앞으로 자주 이용하겠어요!! 너무 맛있는 케이크 감사해요', 48, 9, 'GOOD', SYSTIMESTAMP);
