INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '겉에 보이는 딸기 얇게 슬라이스해사 붙여놓는거네요… 통딸기인줄 알았는데.. 딸기가 단맛보단 새콤한 맛이 나서 케익이 전체적으로 달콤하다기 보다는  느끼하지 않은 가벼운 맛이에요. 안에 딸기가 많고 달지 않은 편에 비해 크림이 부족해서 시트+딸기+크림이 전체적으로 어우러지기 보다는 다 따로 노는 느낌이에요ㅠ 기대 많이 했는데 제가 좋아하는 스타일이 아니라 아쉽습니다.', 10, 7, 'BAD', SYSTIMESTAMP);
