INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '남쟈친구 생일 기념으로 샀는데 넘 예쁘고 넘 맛있어서 행복했습니댜 ㅎㅎㅎ 남쟈친구도 만족하고 저도 만족했어요 둘이서 먹을만큼되고 사실 셋이서 먹어도 될 정도였어요!!', 78, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '작년인가부터 알게돼서 딸기 시즌마다 애용하는 가게인데 진짜 부담없이 호로록 먹게되는 부드러운 시트와 가벼우면서 달큰한 크림이랑 살짝 단단하고 새콤한 딸기가 조화로운 딸기 케이크예요🥹 매년 겨울마다 온갖 딸기케이크 가게에서 사다먹지만 여기는 진짜 빠지지 않고 먹어야하는 가게 중 하나입니다. 케이크 좋아하시는 분이라면 혼자 1호는 충분히 해치울 수 있는 매력 넘치고 맛있는 딸기 케이크예요. 다들 꼭 드셔보세요 ㅠ 딸기가 적은가 싶을 수 있는데 시트랑 크림이랑 딸기의 밸런스가 딱 좋아요. 어느 하나가 많아지면 먹을 때 쉽게 물리는데 여긴 안그래요! 이번 해도 맛있는 케이크로 행복하게 보냈습니다.', 30, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '딸기케익이 먹고싶어서 갔는데 품절.. 귤케익도 품절... 선택권이 블루베리와 밤 두가지뿐이라 블루베리 선택했는데 그래도 맛있었어요~', 71, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '생과일?? 케이크로 아주 특색이 있어요!! 친구 생일 케이크를 맞췄는데 너무 예쁘고 재료 듬뿍이어서 맛이 너무 궁금하네요!! 친구도 좋아했어요!!', 60, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '케이크 예약 후 픽업하러 갔고, 사람들 웨이팅 어마무시하게 하는데 전 홀은 이용 안할거라 바로 들어갔어요! 꼭 케이크 예약하고 오시길••• 홀케이크 전날 예약해도 바로 받을 수 있는게 좋았어용 당연히 맛있음!!!', 79, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '룸메 생일이라 급하게 예약했는데 딸기 너무 신선하고 과하게 달지 않아서 둘이 후다닥 해치웠슴다🍓 낮에 볼 일이 많아서 시간 맞춰 갈 수 있나 했는데 영업시간 안에만 찾아가면 되서 편했어요!', 67, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '너무너무 맛있어요! 정말 속이 딸기로 가득차서 딸기를 샀더니 케이크를 주는 수준? ㅋㅋ 생크림도 적당히 달면서 맛있고 빵도 촉촉해서 정망 좋았어요', 12, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '딸기케이크 맛있다고 소문은 익히 들어 알고있었는데 소문값 했고요, 기대하지 않았던 밀크티 종류의 음료들도 맛있어서 깜놀! 가격은 엄청 사악한데 맛은 확실히 있었어요.', 58, 11, 'GOOD', SYSTIMESTAMP);
