INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '조각에 9500원인데 맛이 별로. 시트 두껍고 갈색 껍잔 안 자른 것부터가 불안하긴 했는데 시트에서 계란맛도 너무 많이 나고 크림도 평범.', 109, 24, 'BAD', SYSTIMESTAMP);
