INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '부모님 결혼기념일로 주문했어요! 근데 픽업하는걸 잊어버려서..못 찾아가는건가 폐기되는건가...하고  걱정해서 그냥 문앞에 놔달라고 말씀 드렸는데  우유팩 넣는 곳에 얼음팩이랑 포장해 주셨습니다😄 먹어봤는데 시트도 부드럽고 너무 맛있더라고요...개인적으로 역대급 케이크라고 생각했습니다!! 꼭 한번 드셔보세요!!', 76, 15, 'GOOD', SYSTIMESTAMP);
