INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '친구 생일이라 케익을 예약했는데 친절하셨고 무엇보다 케익이 넘 맛났어요. 친구가 호텔 케익보다 맛나다고 엄청 좋아했어요. 가격대비 다른데 비해 크기는 좀 작지만 양보다 질!맛!! 원하시면 추천합니당^^', 28, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '맛이 대체적으로 아쉬운 편입니다. 딸기는 가득 들었으나 시트가 좀 두껍고 촉촉하지 않았어요. 생크림은 달지 않았는데 뭔가 이맛도 저맛도 아닌듯 싶네요.', 21, 1, 'BAD', SYSTIMESTAMP);
