INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '딸기 케이크 짱이에요 징짜루 넘 맛있어요 직원분께서도 넘 친절하셨구 12시 반쯤 포장하구 밤에 먹었는데도 넘 맛있구 그냥 딸기랑 크림이랑 빵이 다 대박이에요 넘 맛있는 케이크 감사합니다…🍰', 96, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '엄마가 이렇게 맛있는거 못 먹어봐대요 물론 가격은 비싸다고만해뒀어요 나이 드신 분들이 받아드리기 힘들듯 물론 난 젊어서 가능~ 딸기 찐으로 맛있고 빵이랑 크림은 안 달고 딸기를 위한 조연. 주연이 연기 잘하는데 뭐가 필요할까', 60, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '크리스마스 이브에 예약해서 픽업했고! 바로 받았어요! 케이크 크림 별로 좋아하는데 여기 크림은 느끼하지 않아서 좋았어요! 딸기도 가득 들어있어서 넘 좋았고 적당히 달아서 좋았어요!', 43, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '케익종류가 많고 케익이 맛있어요! 미니케익이 저녁먹고 먹기에 양이 맞았어요!! 그리고 위치가 역이랑 가까워서 편했고 금액이 요즘 기준으로는 괜찮았습니다❤️', 7, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '무화과 케잌은 제 취향 아니에용 딸기 케잌 먹고 싶어서 갔는데 아직 딸기 공급이 원활하진 않은 가봐용 아쉬웠어요! 같은 층에 화장실 있고 편리했어용! 좌석은 뭔가 어수선한 느낌! 홀케잌 사러 들리기 좋을 거 같아용', 3, 1, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '이번이 두번째 방문입니당.. 12월달 말에 방문하고 너무 맛나서 1월초에 재방문했오요!!! 개인적으로는 블루베리랑 초코딸기랑 생크림딸기 중 생크림딸기가 가장가장 맛있었어요~~!!! 입맛까다로운 언니도 인정하는맛~👍👍👍 딸기가 달달하구 크림두 맛나서 ㅠㅠ 다음에 또 방문해서 먹고싶습니당~👍👍😊', 40, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '남편이 딸기를 워낙 좋아하는데 딸기케이크로 유명하다고해 방문했어요! 가격대는 있었지만 딸기도 실하고 맛나고 케이크 자체도 맛있어요! 큰사이즈로 샀는데도 한자리에 앉아 다먹었네요!', 7, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '서울 갈때마다 가요! 비포블루밍 원래도 과일케이크로 유명하지만 명수님이 방송에서 이야기 한 후 더 유명해졌어요! 한조각만 먹고 싶었는데 품절되서 한판 사서 전주까지 오느라 보냉백도 팩도 사서 좀 속상하긴 한데 맛은 있었어요! 분명 한조각만 먹으랴고 했는데 다 퍼먹아서 없어져버럈어요….ㅋㅋㅋㅋㅋㅋㅋㅋ 담에 또 서울 가면 또 먹을거예요', 28, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '크리스마스때 예약해서 픽업으로 진행했는데 사람 무지무지 많았지만 바로바로 처리해주셔서 신속하게 픽업할 수 있었습니다! 맛도 좋았어요~ 덕분에 크리스마스 잘 보냈습니다 :)ㅎㅎ', 38, 7, 'GOOD', SYSTIMESTAMP);
