INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '진짜 케이크 너무 맛있어요 ! 생크림은 진해서 치즈향이 살짝 느껴지고 빵 부분 진짜 촉촉... 커피도 맛있어서 만족스러웠어요 ! 다만 매장안에 천류가 없어서 소리가 흡수되는게 적어서 조금만 시끄러워도 울립니다...', 8, 1, 'GOOD', SYSTIMESTAMP);
