INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '무화과 케이크가 먹고 싶어서 갔는데 저녁 먹고 가니까 다 팔려서 없더라구요... 하나 남은 블루베리 케이크를 시켰는데 부드럽고 촉촉하니 맛있었어요! 블루베리가 엄청 크고 실해서 놀랐답니당 ㅎ 다음엔 꼭 무화과 케이크를..!', 121, 19, 'GOOD', SYSTIMESTAMP);
