INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '커피종류가 세가지로 산미있고 고소하고 디카페인이 잇어서 골라먹을 수 잇어서 좋았고 디저트가 보는 재미 먹는 재미까지 있어서 좋았어요 여유롭게 쉬다 갔어요 👍', 39, 1, 'GOOD', SYSTIMESTAMP);
