INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '아메리카노는 그냥 그래용.. 고소한 맛으로 시켰는데 고소하지않아용.. 딸기케이크는 댕맛이에요.. 베리머치라는 디저트인데 아묻따 진행시켜 영차!!! 커피는 노기대 ㅠㅠ', 26, 7, 'BAD', SYSTIMESTAMP);
