INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '여기 두번째 방문인데 홍대 2층 건물에 공원이 보이니 너무 이뻐요!! 지금은 가을 느낌에 단풍을 보니 더 좋네요 ㅎㅎ 여기 케이크 맛있어서 간건데 무화과케이크는 좀 슴슴하니 아쉬웠지만 또 갈거같아요!!', 322, 30, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '딸기가 정말 듬뿍들어간 크림,시트 모두 빠짐없이 맛있었어요!!! 생일인 친구가 너무 좋아했어요😇 같이 파시는 초까지 너무 귀여운 비포블루밍 다음에 또 방문할게요!!🎂', 34, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '기념일 케이크로 할려고 샀는데 기대 하나도 안했거든요 ㅋㅋㅋ 근데 케이크가 진짜 마싯고 부드럽네요??? 빵이 엄청 폭신 해서  초불고 거의 다 먹엇어요 다음에도 또 이용할게요 ~', 81, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '후기 보고 주문했는데 너무 맛있어요!! 앞으로도 특별한 날에 함께 하고 싶은 케이크였어요. 크림이 딸기랑 조화가 좋고 느끼하지 않아서 계속 들어가요!!', 80, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '케이크 존맛탱…작년 생일날 선물받고 반년동안 한 5번은 간 것 같아요 담주에도 방문예정….❣️음료는 가성비 떨어지지만 케이크만큼은 최고입니다', 55, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '케이크 생크림이 엄청 진하고 고소하고 시트도 촉촉하고 케이크로 유명한 이유를 알겠어요. 밀크티도 진하고 맛있는데 살구맛까지 진하고 잘 어우러져서 좋아요! 여태 먹어본 밀크티 중 제일 맛있어요. 카카오 호지차도 향 좋고 진하고 너무 맛있어요. 엄청 친절하시고 인테리어도 좋아서 꼭 또 방문할거예요.', 7, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '2023년 12월 24일 받아간 사람입니다. 미리 인터넷 예약으로 예약을 했고요. 다른 리뷰들을 보면 한결같이 맛있고 좋았다고 하는데 그날 예약해 먹은 케이크는 다른 리뷰에 있던 좋은 후기들과는 다르게 맛이 없었습니다 처음에는 딸기를 먹어보고 기대감에 부풀어 있었습니다만, 막상 먹어본 케이크는 기대 이하 뿐 아닌, 실망에 가까웠습니다. 시트는 굉장히 가벼워서 공허한 느낌에 시트에서 나는 건지 크림에서 나는 건지 모를 쉰내와 시큼한 맛이 났습니다. 좋은 맛이라고는 오로지 딸기뿐이더군요. 원래 이런 맛인 건가 하는 당황스러운 기분에 리뷰에 들어가보니 24일에 받으신 리뷰어 중에서 저와 같은 처지이신 분들이 보여서 씁니다. 원래 이런 맛인지 모르겠습니다만.. 혹, 공정에 문제가 있었다면.. 안타깝네요 😓', 16, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '케이크 시트랑 크림은 괜찮았는데, 딸기 일부를 잘못닦거나 말리신건지 원래상태가 별로인건지 쉰내가 나고 쉰맛이 났어요.. 크리스마스라 빠르게만드셨는지는 모르겠는데 기대했던만큼 실망했네요ㅠㅠ', 8, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '딸기가 철이라 맛있네요 근데 생크림과 빵은... 그냥 파리바게트가 더 나은것 같네요 이쁘긴합니다. 맛보고 그냥 숟가락으로 퍼먹었네요 재구매의사 없습니다.', 12, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '케익 한판은 커녕 한조각도 겨우 먹는 저인데...(물려서) 이건 앉은자리에서 한판 순삭했습니다 딸기케익 넘맛잇어요ㅜㅜ 담에또 사먹을거에여!!!', 9, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '연남동에 혼자 볼일있어 왔다가 케이크 맛집 리뷰 보구 들렸어요(케이크 환장 1인) 블루베리랑 요거트 좋아해서 케이크 맛있게 먹었어요! 커피도 산미 있는거 없는거 고를수 있어서 좋았고 사장님 친절하셨어요:) 작은 홀케이크도 있어서 친구 생파에 주문하면 좋을거 같아요🎂', 58, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '부모님 생신 케이크로 무화과 케이크 1호 구매했어요.무화과가 가득가득 들어있고 크림도 깔끔해서 넘 맛있었어요!! 안에 빵도 퐁신퐁신합니다~~ 다음에도 또 구매할게요 :D', 49, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '케이크 예약해서 픽업한 뒤에 먹고갈지 고민하던 중에 알바생이 와서 오래있을건지 물어봐서 나가라는 소리로 들렸습니다. 조금 더 좋은 표현이 있었을 거라고 생각하는데 마지막에 저희가 버린 쓰레기도 아닌걸 팍 하고 주워가는 태도를 보면서 기분이 별로 좋지 않았습니다.', 14, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '오늘 예약해서 케이크 받아왔습니다! 케이크는 너무 맛있고 딸기도 듬뿍이네요 ㅎㅎ 근데 바쁜건 알겠지만 직원분이 하.. 좀 친절하게 대해주셨음 하네요 서비스는 별로지만 케이크맛은 있어요~', 70, 14, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '연남동에 뷰맛집 카페에요~~ 케이크 맛집인데 복숭아 케이크를 먹어봤는데 우유생크림이라 그런지 너무 촉촉하고 많이 달지도 않아요 ~~ㅎㅎ 연트럴파크 중심에 있어 창가뷰로 구경하기도 좋구여 ㅎㅎ 케이크 다양한 종류가 있고 홀케이크로 미리 예약주문도 받던데 다음에 홀케이크 사러가려고요! ㅎㅎ 너무 맛있어요❤️❤️ 그리고 밀크티 찐맛집!! 제가 밀크티덕후인데 살구홍차 밀크티…한입 드링킹하자마자 제취향👍', 76, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '딸기도 엄청 듬뿍 들어가있고 케이크 자체도 너무 예뻐서 선물하기 좋았습니다 ! 저는 픽업으로 했지만 매장 내부도 예뻤고 다른 케이크들도 맛있어보였어요 👀💖', 373, 57, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '인터넷으로 우연히 알게된 카페인데, 아이돌 팬분들한테는 나름 유명하더라구요. 그래서 기대를 품고 가봤는데 역시나 맛있었습니다. 수요미식회 가로수길 모 카페, 키친 205, 투썸플레이스, 호텔케잌 등 유명한 곳 케잌은 거의 다 먹어봤으나 여기가 제일 맛있는 것 같아요. 과일도 정말 실하고 크림도 너무나 맛있어요. 느끼한걸 못먹는 편인데도 여기 크림 정말 새콤달콤하고 맛있고, 블루베리 알이 엄청크고 무르지않고 엄청 싱싱해요. 그리고 케잌 안에 블루베리가 엄청 많이 들어가있어요. 진짜 너무 맛있어서 또 먹고 싶었는데 뒤에 있는 저녁약속 때문에 더 먹지 못한게 한 입니다. 집에서 거리가 먼게 아니라면 앞으로 생일/기념일 케잌은 다 여기서 하고 싶어요. 정말 죽기직전에 한입 먹고 가고 싶은 맛입니다. 또 먹고싶어요', 44, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '커피가 산미없는 원두, 산미있는 원두, 디카페인 준비되어있어 좋았습니다. 케이크 비주얼에 홀려 찾아간 곳이었는데 초코딸기 케이크는 무난하게 맛있는 맛이었으나 피치피치 케이크는 제가 느끼기엔 조금 애매한 맛이었어요. 전반적으로 너무 달지 않고 부담없이 먹기 좋은 맛이었습니다.', 45, 6, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '후르츠 팡팡 이름값 합니다 과일이 많아 느끼하지 않고 맛있게 달아서 부모님, 임산부, 아이들까지 아주 맛있게 먹었어요 친구에게도 추천 했고, 재방문 의사 넘쳐납니다', 42, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '현금영수증 요청하니 할 줄 모른다고 대답하셔서 황당했는데 케이크 포장하다말고 다른 직원분 교육하시더라구요 가는데 얼마나 걸리는지 여쭤보셔서 오래걸린다 말씀드렸고 약한 케이크 상자 위에 얼음팩 올려주신덕분에 상자가 무너져내렸네요 비닐백 하나 더 덧대주셨으면 이렇게까진 안됐을거같은데..케이크로 유명한곳 아닌가요? 아무리 고정핀이 없대도 케이크도 너무 쉽게 이리저리 쏠렸구요 가족들이 뜨악했고요 다신 이용안할거같아요 넘 속상하네요ㅎㅎ', 47, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '친구 생일케익으로 사갔는데 다들 너무 맛있다고 어디냐고 물어봤어요!! 매우 뿌듯하더라구요~!! 예쁘기도 예쁘고 엄청 맛있어서 행복했습니다☺️☺️', 12, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '픽업하러갔는데 사장님이 너무 친절하셨어요 ㅎㅎ 선물했는데 지인이 너무 맛있대요 ! 과일은 달고 크림이 미쳤다고 했어요💗 담엔 픽업말고 매장 방문해보고싶어요 ✨', 7, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '엄마생신이라 처음 방문해봤는데 케이크가 너무 맛있어서 놀랐어요 :) 사장님도 너무 친절하시고 케이크도 맛있고 재방문의사 100%입니다 ^^', 5, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '크림과 케이크 시트는 정말 맛있었구요. 시즌 끝물이라 그런지 덜 숙성된 망고케이크를 받았는데 매장에서 연락주시고 적절한 조취를 취해주었어요.', 39, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '생일 케이크로 쓰려고 예약해서 찾으러 갔는데 직원분들이 정말 친절하게 안내해주시고 보관방법도 잘 설명해주셔서 케이크와 함께 좋은시간 보냈어요:) 3시간이 넘는 장거리라 보냉가방에 넣어도 조금 걱정했었는데 얼음팩도 큰게 케이크 양쪽으로 있어서 움직이지 않고 더 시원하게 잘 들고 올수 있었습니다! 맛은 다른 리뷰와 같이 너무 맛있었어요:) 케이크 필요할때 재방문할게요!', 15, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '딸기케이크에 반해서 찾아온 카페입니다. 카페가 통창으로 되어있어서 뷰가 참 좋아요 창가에 앉으면 사진이 잘 나올것같아요 딸기케이크는 상큼한 딸기가 케이크에 왕창 들어있어 넘 맛있어요. 베리에이드는 달달하니 맛나고 커피는 디카페인 선택지가 있어서 넘 좋네요', 65, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
