INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '뷰도 넘넘 예쁘고 케이크도 엄청 맛있었어요.. 제일 좋았던건 밀크티 종류가 많았던 것 ! 살구홍차 밀크티는 처음 마셔보는데 사실 마시기 전엔 너무 달면 어쩌지.. 라고 생각했었는데 무슨 ㅠㅠ 은은하게 나서 정말 맛있었어요 .. 🌸', 16, 4, 'GOOD', SYSTIMESTAMP);
