INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '케이크픽업하고 내려오자마자 보니까 쏠려있어요 너무 케이크가 잘 움직이더라구요 이렇게 잘 움짓이는 케이크는 처음 ㅜㅠ 근데 맛은 굉장히 맛있었어요 단.. 케이크 칼로 자르니까 그냥 한번에 다 뭉개져서 먹기 엄청 불편합니다', 123, 23, NULL, SYSTIMESTAMP);
