INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '연트럴파크뷰를 바라보면서 여유있는 시간을 보낼 수 있는 카페 비포밍블루.  애플망고 케이크가 이름값을 하는지 너무나 달콤하고 입에서 사르르륵 녹는다. 적당히 깔끔하고 달달한 케이크의 맛! 베리에이드는 새콤달콤~♡ 살구의 은은한 향과 맛이 제대로 어우러진 살구홍차는 진땅이 PICK!!', 26, 9, 'GOOD', SYSTIMESTAMP);
