INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '크기가 작아서 첨엔 가격이 좀 비싼듯한 생각이 들었는데 속까지 무화과로 가득한~!! 많이 달기만 한 케잌보다 적당한 단맛도 좋았고 시트도 촉촉하고 과일과 크림도 잘어울리고 넘 맛있었어요', 1, 4, 'GOOD', SYSTIMESTAMP);
