INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '무화과랑 복숭아 고민하다가 복숭아로 주문했는데… 정말정말 맛있었습니다… 안에 든 말랑한 복숭아가 정말 맛있었어요. 빵이랑 크림도 안느끼하고 적당히 달아서 너무 맛있게 먹었습니다!! 겨울에 딸기케이크도 꼭 먹고싶어요..', 59, 11, 'GOOD', SYSTIMESTAMP);
