INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '특이한 음료도 있고 케이크도 맛있어요 늦게가서 케이크가 별로 안남아있었지만  다음에는 무화과케이크 먹어보고 싶어요!!  이번에 먹은 블루베리 케이크도 맛있게 잘 먹었어요 ㅎㅎ', 43, 1, 'GOOD', SYSTIMESTAMP);
