INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '무화과 홀케이크 미니 사이즈 선물용으로 구매 했는데 친절하게 도와주시고 전날 예약이 가능해서 덕분에 좋은 선물 할 수 있었어요! 같이 구매한 커피도 맛있게 마셨습니다:)', 45, 6, 'GOOD', SYSTIMESTAMP);
