INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '울딸 최애케잌입니다. 케잌돼지라 가족들이 각종 호텔 케잌부터 유면 제과점 케잌까지 다 사주는데 여기 케잌이 맛나다네요. 빅3안에드는데 딸기초코는 홀케잌이 없어 복숭아를 주문해서 많이 아쉬워합니다. 초코딸기도 홀케잌으로 판매부탁드려요', 50, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '연남동 핫한 카페 "비포블루밍" 특별한 디저트가 있어 방문한 카페~~~~오리지널버터팬케이크 겉바삭속촉촉으로 달콤바삭하게 즐길 수 있다~~ 베리에이드 색깔이 너무 예쁘다♡♡커피만 마시던 내가 고른 예쁜 에이드 잘 골랐다♡♡에이드는 잘못타면 밍밍한데  비포블루밍 에이드는 상큼 달콤 시원~~~~굿굿!!! 데헷~~예쁜 브런치카페~~상큼한 봄 향기 맡으면서  연남동 핫한카페로 맛있는 브런치  드시러 놀러오세용♡♡또와야징~~', 23, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '생일케이크는 여기에서만 사요!! 최애는 딸기케이크였는데 복숭아케이크는 여름에만 먹을 수 있어서 특별한것같아요 ㅎㅎ 복숭아도 왕창 들어있고 믿고 먹는 가게입니당 🥹👍', 69, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '여름에 딸기케이크 파는 곳 거의 없는데 모양도 예쁘고 딸기도 달고 맛났어요. 맛은 웬만한 유명한 케이크 집보다 훨 맛있네요 !!!! 까다로운 엄마 입맛에도 딱이고 사장님도 왕 친절하셔서 포장하는 짧은 순간에도 기분 좋았답니다. 💗 다른 케이크도 먹어보고 싶어서 다음에는 카페에서 커피랑 먹으러 가려구요. ㅎㅎ 잘 먹었습니다 번창하세요 사장님 💗', 8, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '딸기 많이 들어있고 당도와 상큼함이 매우 적절해서 여태까지 먹은 딸기 케이크 중에 순위권에 듭니다 예쁘기도 예뻐서 사진찍기도 너무 좋아요 강추', 68, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '복숭아 케이크 먹으려고 갔는데 없어서 아쉬웠지만 초코 딸기케이크도 맛있게 먹었습니당. 커피도 너무 쓰지 않아서 맛있고용. 홍대에서 디저트 카페 간다면 추천드립니다.', 31, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '와 진짜 케이크 그리고 디저트 너무 맛있어요! 날씨 좋아서 햇살카페라 갔는데 버터팬도 케이크도 진짜 너무 맛있어서 힐링하고 갑니다! 커피도 맛있고 분위기도 좋고! 다음에는 딸기케이크 먹으러 갈게요~ 진짜 최고예요!!', 43, 1, 'GOOD', SYSTIMESTAMP);
