INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '정말 오랜만에 너무너무 맛있는 케이크를 먹었어요! 사장님이 너무너무 친절하시고 감사했어요!! 기념일 케이크로 먹었는데 너무 행복한 기념일이었던 이유중 하나였어요~!!', 17, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '엄마 생일케이크 고민하면서 엄청~ 검색하다가 여기로 예약했는데 케이크 너무 예뻐요!!! 맛도 너무 맛있어서 기분 좋은 생일 보냈습니다~!! 매장 가보니까 맛있어보이는 디저트 완전 많아보여서 카페로 또 방문해보려구요!!💕💕', 27, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '남친 생일때문에 일주일 안으로 주문예약해야했는데 급하게 찾은 딸기케이크집 치고 너무 맛있었어용ㅠㅠ 딸기 끝물이라서 딸기케이크 판매 중단된 곳도 많아서 노심초사했는데ㅠㅠ 끝물이라서 딸기가 좀 작긴해도 정말 달고 크림도 너무 달지도 않아서 안 물리고 계속 들어가는 맛? 부드럽고 빵도 조금 들어있어서 딱 좋았어요! 들고갈때 이동거리 물어보시길래 한시간말씀하니 아이스팩도 넣어주섰엉ㅎ…ㅠㅠ 미니사이즈 주문했는데 딱 2명까지 먹기 젛은 사이즈 입니다!! 비주얼과 맛 두마리 토끼 다 잡았음요.. 다음에 또 먹을 의향 있습니다~!! 추천', 6, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '우연히 보게되어 예뻐서 무작정 사고보니 비주얼만큼이나 맛있는 케이크에 너무 행복했어요ㅠ 느끼한 생크림들이 많아서 걱정했는데 완전 달달한 우유생크림이라 더 많이 먹을 수 있었고 무엇보다 케잌을 별로 좋아하지 않는 부모님도 맛있게 드셔서 특별한 날마다 사가고 싶은 케이크에요🫶🏻 알바생분도 너무 친절하셨구 가게 분위기도 너무 좋았어요!!', 7, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '생일 케이크로 주문했는데 너무 맛있게 먹었어요! 복숭아도 신선하고 크림이랑 빵도 맛있어서 선물받은 지인이 굉장히 만족해했어요. 다음엔 매장 가서 다른 디저트도 먹어보려구요 :)', 30, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '남친 생일에 복승아 케이크를 예약했는데 맛도 디자인도 너무 좋았어요~~~!!생크림도 그냥 평범한 맛이 아니고 복승아에 잘 맞는 덜 달콤한 맛이었어요!!다른 계절에도 또 먹어싶어요~🥰🥰', 32, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '가성비 미침 그 자체!!!! 밑에서 밥먹고 돈쓰고 기분나쁨 그러고 올라와서 예약한 케이크 찾아서 친구 생일 축하해주고 먹었는데 , 1. 저는 케이크를 안좋아함 2.친구한명 입이짧음 3.친구한명 식단조절중 4.친구한명 입맛 떨어짐 이 상태로 과연 이걸 다 먹을 수 있을까 했는데 너뮤 맛있어요. 일단 보이는 🍓딸기만해도 엄청 많죠? 진짜 뻥안치고 속도 🍓딸기로 가득 차 있어요. 딸기는 또 엄청 달달하니 시럽도 안뿌려놨는데 달달함 그 자채!! 게다가 크림도 빵도 그냥 다 너무 맛있어서 딸기와 찰떡 그냥 아주 삼박자 미쳐요 . 우리가 과연 이걸 다 먹을 슈 있을 까? 고민했는데 왜 한건지 모를만큼 너무 맛있고 이건 또 왜 우리동네가 아닐까 아쉽고 직원분들 세상 친절하구 왕 좋아용', 72, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '연남동초입(역근처)에있고 3층이라서 뷰는 좋아요~ 아쉬운점은 일하시는분들이 친절하진않으시고, 케이크값이나 음료값이 좀 비싼거같아요 ㅠㅠ 물가가 많이 올라서겠죠...', 65, 17, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '음료랑 케이크가 가격대가 좀 있지만 대화하기 좋고 연트럴파크 뷰 보면서 시간 보내기 좋은 곳이에요 복숭아케이크 먹고 싶어서 갔는데 케이크도 맛있고 커피랑 에이드도 다 맛있었어요', 2, 10, 'GOOD', SYSTIMESTAMP);
