INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '요번에 신메뉴 자몽얼그레이 나온대서 출시 일주일 전부터 드릉드릉하고 있다가 드디어 실물 영접❤️‍🔥 역시 제 최애조합답게 존맛탱이에요 ( ´ •̥-•̥` ) 곧 망고도 나온다고 하니 또 대기 타야겠어요👻 보틀케이크 먹어보고 넘모 맛있어서 포장도 해갑니당 HeHe❣️', 81, 12, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '3만원대 망고빙수라고 해서 냉동망고려니 했는데 생망고를 직접 깎아서 올려주네요. 맛도 좋고 비주얼도 대박 그리고 3층이라서 연트럴파크 뷰도 좋아요.', 24, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '제가 원래 생크림을 안좋아해서 케이크도 안좋아하는데 생일이라서 우연히 보고 예쁘길래 포장해서 한입 예의상 먹어봤어요. 와....방금 밥먹구 사진왕창찍고 먹은건데도 안느끼하고 딸기도, 케잌시트도 너무 맛있어서 다먹었어요ㅋㅋㅋㅋ 다음번에도 여기서 사먹어야지...❤️', 19, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '연남동에서 뷰도 좋고 맛도 좋은 카페를 찾는다면? 비포블루밍 추천이요!! 딸기케이크 진짜 이쁘고, 맛있어요ㅠㅠㅠ 밀크티도 종류별로 있어서 좋았구, 개인적으로 딸기 시즌이라서 딸기딸기 해서 좋았네용 사장님두 너무 친절하시고 매장도 깔끔했어요! 음료랑 디저트는 말해 뭐해 진짜 맛있어고 개인적으로 홀 케이크도 너무 궁금해서 포장하고 싶었어요! 앞으로 시즌 나올 때 마다 방문해서 다 맛 볼 예정이라는 건 안 비밀이랍니다🤭💗', 103, 23, 'GOOD', SYSTIMESTAMP);
