INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '통창으로 탁 트인 뷰가 멋진 곳! 무엇보다 디저트 맛집답게 디저트가 너무 맛있어요🤍 자몽케이크 먹었는데 크림이 얼그레이 크림이더라구요!! 그래서 더 맛있더라는🫶', 7, 7, 'GOOD', SYSTIMESTAMP);
