INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '깨끗하고 환하고 선곡도 좋은 힐링카페에여.... 😆 들어가자마자 초록초록해서 힐링! 바나나버터팬케이크는 태국에서 먹은 바나나로띠 고급버전같아여 ㅎㅎ', 41, 7, 'GOOD', SYSTIMESTAMP);
