INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '홍대에서 딸케를 먹고싶다면 강추입니다❤️❤️딸케 생크림도 맛잇구 빵 자체도 촉촉해서ㅠ계속 들어가는맛이에요! 살구홍차도 처음엔 잉? 햇는데 이때까지 먹어본 밀크티중 젤 맛있었어요 ㅠㅠ 살구향이 은은하게 나면서도 달짝지끈한맛😍😍 자주 오게될거같아요👏👏💕', 8, 7, 'GOOD', SYSTIMESTAMP);
