INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '[협찬] 3층에 위치해있어서 그간 몰랐던 곳인데, 방문해보니 3층이라 뷰가 너무 좋다고 생각되었던곳! 버터팬도 브런치로 너무 좋고 밀크티를 포함, 티종류도 다양하고! 딸기 가득케이크도 너무 맛있고 예쁜 곳!', 14, 10, 'GOOD', SYSTIMESTAMP);
