INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '딸기 쟁이라 딸기 밀크티 주문했는데 진짜 맛있어요. 케이크 크기는 작지만 안에 딸기도 완전 가득해요. 크림도 진짜 맛있어서 순삭! 케이크는 딱 두종류인것 같은데, 이래서 다들 홀케이크 하나씩 들고 가나봐요. 산미있는 커피를 좋아하는 짝꿍이는 시큼한 맛의 아아를  아주 만족해 하며 커피한잔의 여유를~ 아쉽게도 명당자리는 못잡았지만 뷰가 좋아서 꽃피는 봄엔 정말 예쁠것 같아요.', 81, 16, 'GOOD', SYSTIMESTAMP);
