INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '밀크티가 너무 있었던 비포블루밍 통창 유리가 답답함이 없었던 인테리어와 편한 자리와 테이블 그리고 너무 맛있었던 밀크티! 고급진 유리병의 밀크티와 양도 넉넉👏🏼 미니케익도 폭신한 빵과 상큼하고 신선한 딸기의 조화가 너무 좋았어요!🍰 밀크티는 진짜 앉은자리에서 5병도 마시겠음... 너무 맛있엇 ㅠㅠ🫶🏻', 42, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '요즘 딸기철이 지나서 그런지 딸기케이크가 거의 없어서 찾더라도 맛있을까 하고 걱정했는데 생각보다 맛있더라구요😍!!! 빵도 촉촉하고❤️ 예약하고 매장에 가지러 갔었는데 비오는 꿉꿉한 날에 직원분께서 너무 환하게 웃어주시고 친절하셔서 기분도 좋아졌었어요~ 감사했습니다:)', 93, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '토퍼는 제가 따로 제작한건데 케이크가 너무 예뻐요♡ 갬동 포인트 1 넘나 친절하셨던 사장님!! 덕분에 픽업할때부터 기분이 좋아졌어요♡ 갬동 포인트 2 진짜 산처럼 담겨있는딸기!! 게다가 시지않규 달달 상큼해서 좋았어용..!! 갬동포인트 3 크림이랑 시트가 정말 너무 맛있어요 숟가락 멈출수없듐,, 비포블루밍 케익덕에 한층 더 예쁘게 브라이덜샤워 할수 있었더여><', 15, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '딸기철의 끝물에 주문 후 픽업해서 먹는데 정말 맛있었어요! 주문해서 픽업해갈때 칼 동봉되어있냐구 확인했는데 ㅠㅠ 있다고 해서 가져갔지만 들어가서 보니 없었어요 ㅠㅠ 그 점만 아쉬웠고 케이크 정말 있었습니다! 요하신 분은 꼭 확인하시고 챙겨가세용!', 80, 18, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '여긴 정말 제 최애 밀크티 카페 중에 하나에용❣️ 밀크티 종류가 다양한데 하나같이 다 맛있어서 하나씩 다 드셔보셔도 좋을 것 같아요˙ᵕ˙ 마셔보고 취향에 맞는 밀크티는 티플럼으로 구매해가서 집에서 간편하게 우유만 타먹으면 가성비 갑이라 넘 좋구요❤️ 버터팬도 넘 마싯지만 배불러서 간단히 먹으려고 딸기 케이크 시켰는데 요것두 넘나리 취향저격이었답미당👻', 53, 12, 'GOOD', SYSTIMESTAMP);
