INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '거리가 멀어서 자주는 못오지만  밀크티가 너무 맛있어서 홍대 올때마다 여기로 와요. 살구 밀크티가 저의 최애💜케이크도 늘 품절이여서  오늘 첨 먹는데 너무 맛있습니다 💜', 91, 24, 'GOOD', SYSTIMESTAMP);
