INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '딸기 케이크를 넷이서 순삭했어서 블루베리 케이크 샀는데 이것도 순삭했어요 너무 달지않아서 좋네요 디저트 까다로운 친구가 맛있다고 하네요!', 124, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '엄마 생신이셔서 케이크 예약했습니다. 예약페이지에 있는 사진들이 너무 예뻐서 엄청 기대하고 예약한 거였는데 실물보니까 실물이 더 예쁘더라구요!! 겉으로 보기에도 딸기를 아끼지 않고 쓰신 게 눈에 보이는데 안에 갈라보니까 안까지 딸기로 꽉꽉 차있었어요. 짱...! 거기에 모양만 예쁜 게 아니라 당연히 맛도 있고 과하게 달지 않아서 다른 가족분들도 다 잘 드시더라고요. 덕분에 케이크 사간 제 어깨가 하늘 위로 치솟았네요 희희 덕분에 예쁘고 맛있는 케이크 행복한 기분으로 잘 먹었습니다. 나중에 딸기 케이크 생각나면 또 먹으러 올게요💖💖', 54, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '수많은 연남동 카페에서 재방문한 곳이에요! 딸기케이크가 진짜 맛있었거든요 🥹🥹🍓🍓 홀케이크도 판매하시던데.. 언재한번은 꼭 사고싶었어요 >< 진짜 맛있었고, 통창이라 뷰도 좋았어요!', 37, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '정말 예쁜데 맛도 있는 케이크에요! 크림은 너무 달지 않고 시트도 촉촉하게 너무 맛있었어요.. 단면은 말해뭐해요!! 딸기 가득가득 들어있어서 아빠가 이게 딸기냐 케이크냐라고 하실 정도였어요!!! 할머니 생신파티 케이크였는데 할머니께서도 맛있다고 해주시니까 기분이 정말 좋았어요ㅠㅠ 먼 거리 와서 가져간 보람 제대로 였습니당😍 이런 맛있는 케이크를 파시다니! 덕분에 행복한 하루 보냈어요~ 복 많이 받으시고 행복하세요:)', 48, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '남편 생일이라 전날 부랴부랴 예약했는데 바보같이 픽업날짜를 잘못 선택해서ㅠㅠ 하루 빨리 받을수 있는지 여쭤봤는데 너무 친절하게 응대해 주셨어요 다시한번 감사드립니당 ㅠㅠ 케이크 너무너무 맛있어서 어제 한숨에 다먹어버릴뻔 했어요 촉촉달달한 시트에 담백한 크림의 조화가 환상적임니다!!! 다음에는 초코 츄라이 할게요!!! :) 사장님 대성하세요!!!!', 15, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '산미 없는 커피를 고를 수 있어서 좋았어요! 커피도 달달하게 맛있고, 딸기가 달아서 디저트도 맛있게 먹었어요💖 통 유리창이 있어서 뷰도 좋고, 음료도 직접 가져다 주셔서 좋습니다🥰 다음에 또 방문할게요🌟', 50, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '팬케이크가 먹고싶어서 간곳~~분위기가 따뜻하고 편해서 먹기 좋았어요 근데 여긴 밀크티 맛집이었나봐요 모르고갔는데.. 다양한 밀크티들이 있고 티시럽도 따로 판매하고 특별했답니다. 전 히비스커스 밀크티를 마셨는데..맛좋았어요~^^', 331, 95, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '연트럴파크 바로 앞이라 뷰 환상적이고요 딸기케이크 엄청 맛있어요!!! 하늘 보고 공원보고 딸케 먹으니 여기가 천국❣️❣️ 맑은 날 흐린 날 항상 이쁠 거 같고 봄 되면 또 오고 싶은 카페예요. 베리에이드는 비주얼도 좋고 상큼하니 맛도 좋아요. 은근 개운함! 살구홍차도 향이 적당히 있고 적당히 달아서 이색적인 메뉴~', 43, 6, 'GOOD', SYSTIMESTAMP);
