INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '케이크가 예쁘고 후기도 좋아서 당일 예약해서 구매했어요 ! 선착순으로 구매 할 수 있다고 했는데 다행히 있었습니당! 다음엔 다른것도 사러 올게요', 19, 7, 'GOOD', SYSTIMESTAMP);
