INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '길에서 두 층 올라오시면 카페가 보입니다 오래되지만 관리된 건물의 감성이 좋았고 들어오는 순간 느껴지는 모던하고 깔끔한 인테리어가 눈에 들어옵니다 티와 케이크는 마시기 전에 테이블에 향이 가득할 정도로 향이 좋은편이고 시그니처라고 표기된 살구홍차 밀크티도, 너무 달지 않고, 프렌차이즈 홍차와는 다른 느낌을 줍니다 퀄리티 있는 향과 맛을 느끼고 싶으시다면 추천드립니다', 49, 1, 'GOOD', SYSTIMESTAMP);
