INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '블루베리 케이크 매장에서 먹고 너무 맛있어서 친구 생일선물로 예약했어요 몇년째 여기서만 디저트 먹어요 개맛있음 번창하세요 사장님', 9, 8, 'GOOD', SYSTIMESTAMP);
