INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '팬케이크👍 여기 디저트들 전부 👍👍👍 밀크티도 맛있어요! 제일 꼭대기 층이어서 한 눈에 내려다 보이고 탁 트여서 좋아요. 넓지는 않지만 사람도 많지 않아서 더 좋아요😊😊 퇴근하고 종종 갑니다~', 78, 14, 'GOOD', SYSTIMESTAMP);
