INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '연트럴파크 뷰 보면서 밀크티 마시기 넘 좋아요😛😛 밀크티 종류도 5가지 이상??? 친구랑 히비스커스 밀크티, 살구홍차 밀크티 나눠마셨어요!! 딸기케이크두 같이! 제가 좋아하는 노래도 자주 나와서 조아요 통창 뷰가 뻥 뚫려있어서 좋습니다 비포블루밍💙', 58, 16, 'GOOD', SYSTIMESTAMP);
