INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '베리머치 정말 맛있어요!! 크림이 너무 달것 같아 걱정했는데, 제 입맛에 딱 맞았고 시트는 폭신폭신했어요. 크림이 질리지 않도록 딸기가 입안을 상큼하게 해주어서 정말 최고였습니다👏👏  다음엔 초코를 시도해보려구요! 매우 기대됩니당..!!☺️❤️❤️ p.s. 캐릭터초 곰돌이들이 아기자기 정말 귀여워요ㅠㅠ❤️', 18, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '친구랑 찾아서 왔는데 진짜ㅜ 너무 좋아요 일단 음료가 이쁜데…:&/‘ 너무 맛있어요 음료도 짱이구 케이크도 있던데 먹어보고 싶어요ㅜ 담에 꼭 먹어보기루 매장도 너무 포근하구 사진도잘 나오고 너무너무 짱입니다 담에 와서 또 완전 많이 시켜 먹어볼라구요', 87, 14, 'GOOD', SYSTIMESTAMP);
