INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '딸기케이크랑 밀크티가 너무 맛있는 카페에요. 밀크티도 깔끔한 맛이고 독하지도 않아서 좋아요. 밀크티 전문점이라 다양하고 밀크티 시럽도 팔고 있어요. 케이크도 부드럽고 엄청 달지도 않고 딱 좋아요!', 19, 8, 'GOOD', SYSTIMESTAMP);
