INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '살구 홍차 음료 처음 마셔보는데 음료가 특이하고 맛있어요! 케이크는 더할나위 없이 맛있어요😍😍 홍대입구에서 제일 좋아하는 카페예요!', 28, 10, 'GOOD', SYSTIMESTAMP);
