INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '밀크티 별로 안 좋아하는 편인데 살구홍차 밀크티 향 너무 좋고 달달하니 맛있어요 너무 달지 않아서 좋아요 히비스커스 메뉴는 히비스커스 맛 잘 나고 맛있어용', 56, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '안녕하세요 저는 디저트와 케이크에 환장하는 사람입니다 연말에 가족들끼리 크리스마스를 즐기기 위해 케이크를 예약 주문했었는데요 비포블루밍 덕분에 가족과 따듯하고 성공적인 연말을 마무리할 수 있었습니다 겉보기엔 예쁘고 속은 맛없는 케이크도 많은데요 비포블루밍의 케이크는 제가 먹어본 케이크 중에서 과연 TOP3에 들 정도입니다 부드러운 시트지, 요거트와 우유맛이 나는 달콤한 생크림 덕분에 느끼한걸 싫어하던 저희 부모님마저 정말 잘 드셨습니다 게다가 딸기는 너무나도 달콤하고 상태가 좋았던지라 먹는 내내 정말 행복했어요 생크림 구름 위를 나는 기분을 느꼈어요 케이크 하나만으로 사람이 이렇게나 행복해질 수 있다는 것에 놀라웠네요 다음에는 다른 디저트도 맛보러 자주 방문할게요 감사합니다', 0, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '5시쯤 방문했었는데 사람이 정말 많았어요! 디저트 기대 안 하고 먹었는데 생각보단 맛있었어요. 아이스 아메리카노는 맛이 좀 연한 느낌이었고, 살구 밀크티는 사실 살구가 스쳐지나간 맛이라 여러모로 맛은... 아쉬웠어요ㅠ... 매장이 크지 않은데 사람이 많다보니 대화를 하기 적합한 카페 느낌은 아니었어요. 내부 인테리어가 매우 인스타 스타일이라 사진 찍기 좋을 것 같아요~', 6, 2, NULL, SYSTIMESTAMP);
