INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '5월에 친구 선물로 딸기케이크를 구매했습니다. 정말 보기에도 이쁘고 맛도 좋고, 무척 만족했습니다! 다음에 또 방문하겠습미다 감사합니다', 36, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '밀크티 종류가 많아서 신기했어요! 디저트 종류도 많구 초 같은 것도 옆에 따로 구비되어 있어 구매 가능! 네이버영수증 이벤트도 하는데 저는 나중에 집 와서 따로 쓰고 싶어 패스했습니당ㅎ 음료 한입 마시는데 무슨 비닐? 같은 게 나와서 약간 당황했지만 빨대 분리하면서 들어간 것 같더라구요 말씀드리니 죄송하다고 하시면서 바로 새거로 바꿔주셨어요 다행히 그 후로는 안나왔어용ㅎ 이게 제꺼에서 나온건지 친구꺼에서 나온건지는 모르겠지만 뭐 그럴 수 있죠~ 벌레 이런 것은 아니니까 다행히 첫입에 나왔구 디저트랑 다른 것도 맛있어서 잘 먹었습니다~ 다들 친절하시고 카페 예쁘게 꾸며져 있어서 좋았습니당', 50, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '케익과 타르트가 너무 이쁩니다. 사장님도 친절하시구요. 오늘은 테이크아웃이라 맛보진 못했는데 담에 버터팬 메뉴도 먹어보고 싶어요.', 23, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '정말 기대하고 기대하고 먹었는데도 실망스러움이 없던 케이크,,,, 딸기도 다 달달하고 진짜 딸기 듬뿍들어서 39000원이 정말 타당한 가격이다 생각이 들더라구요.. 시트가 단편이라 딸기 달달함이 조금 느껴지는데 담에는 시트가 조금 덜 달게 나오면 진짜.. 극락일 것 같습니다 사실 저는 그래도 한번 더 사먹으려구요ㅋㅋㅋㅋㅋ진짜 맛있어요ㅠㅠㅠ 가서 보니까 직원분들 딸기 하나하나 손질하시는거보고 오오 진짜 잘샀다 싶기도 하고 계산해주시는 직원분도 친절하셔서 아주 만족입니댜💕 케이크 먹으면 두세입 먹고 마는 남자친구도 4분의 1 먹고 진짜 맛있다고 하더라구요ㅠㅠ 성공적이에요,, 크리스마스 이렇게 행복하게 만들어주셔서 감사해요!', 16, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '색도 색대로 이쁘고 맛도 있었어요!! 저는 개인적으로 아아보다는 아바라 추천!! 너무 맛있었어요! 딸기 음료도 너무 맛있었구요! 케익 이거 노무 맛있었어요!', 88, 16, 'GOOD', SYSTIMESTAMP);
