INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '과제하려고 카페를 찾다가 오게 됬는데, 3층이리 부도 좋고 인테리어도 깔끔해서 좋은 것 같아요. 밀크티 전문점인 줄 잊고 아아로 시킨게 후회됨 ㅋㅋ', 30, 9, 'GOOD', SYSTIMESTAMP);
