INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '크리스마스케이크 예약 픽업했는데 진짜 너무 맛있어서 이서 거의 순삭!!!!! 딸기도 맛있고 생크림도 너무 달지도 느끼하지도 않아서 술술 들어가고 게다가 예쁨은 덤...!!!!! 너무 맛있었어요🫶🏻 빵은 얇은 시트에 촉촉하고 딸기 아낌없이 들어가 있어서 여기서 픽업하길 잘했어요 대만족😋', 49, 6, 'GOOD', SYSTIMESTAMP);
