INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '크리스마스 케이크 예약해서 받았습니다 ! 💗 딸기 좋아하는 딸기귀신이라 큰맘먹고 주문했는데 역시.. 딸기가 한가득 들어있어서 너무 감동이였어여...! 평소에 크림은 걷어내고 먹는편인데 이거는 크림도 맛있어서 먹게되더라구요! 덕분에 너무 행복한 크리스마스 보냈어용! 감사합니다!', 114, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '크리스마스랑 연말이라 오랜만에 딸기케이크를 예약해서 받으러 갔는데 친절하게 알려주셔서 잘 받아왔습니다! 고정핀이 없어서 박스 안에서 조금 움직이긴 했는데 심한 상태는 아니여서 다행이였어요! 딸기케이크.. 너무 맛있어요ㅠ 딱 제가 원하던 딸기케이크로 안에 시트 사이에도 딸기가 콕콕 박혀 있어요! 많이 달지는 않지만 달달구리하니 맛있어요ㅎㅎ 오랜만에 연말분위기 내면서 가족들과 좋은 시간 보냈습니다! 내년부터는 가격인상된다던데..ㅠ 아쉽네요ㅠ 그래도 맛있게 잘 먹었습니다🍓🍓', 95, 22, 'GOOD', SYSTIMESTAMP);
