INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '평점 : 💛💛💛💛💛 완전 강추‼️ 우선 메뉴가 다 맛있어요!! 밀크티 맛집으로 유명해서 갔는데 밀크티도 몇가지 향이 나면서 달달하고 은은하게 맛있어요!! 베리에이드도 먹어본 곳 중에 여기가 제일 맛있던거같아요!! 완전 강추메뉴⭐️ 팬케이크는 가장자리가 특이하게 바삭하고 가운데는 보슬보슬해서 너무 맛있구 후레이크랑 잼도 잘어울려요~!', 2, 6, 'GOOD', SYSTIMESTAMP);
