INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '밀크티 진짜 다 맛있어요!! 전에 왔을때 팬케이크듀 맛있게 먹었는데 오늘 딸기케이크도 맛있어요! 크림 안느끼하고 좋아용!! 근데 케이크 크기는 좀 아쉽...ㅠㅠ', 83, 14, 'GOOD', SYSTIMESTAMP);
