INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '맛있어요!! 공간도 제법 넓구 커피 맛도 좋네요~~ 밀크티 종류도 많아서 좋아요~!!! ( ᵕ̩̩ㅅᵕ̩̩ ) ✧˖°  다음에 올 일 있으면 또 오려구용', 74, 11, 'GOOD', SYSTIMESTAMP);
