INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '케이크가 안 달아서 맛있고 밀크티가 특이한데 맛있어용 베리에이드도 상큼해서 여름에 먹으면 시원할듯,, 다음엔 와서 버터팬 먹어볼래요', 99, 26, 'GOOD', SYSTIMESTAMP);
