INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '예약 없이 방문했는데 운 좋게 홀케이크 구매할 수 있었어요 :) 딸기는 달면서 크기도 적당히 크고, 시트 안에도 많이 들어있었어요! 무엇보다 생크림이 너무 묵직하지도 않고 지나치게 달지 않아서 계속 먹게게 되더라고요! 기대치 않았는데 너무 만족스러운 생일케이크였고요, 재구매의사 완전 있습니다!! :)', 71, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '평일 오후 8시 반쯤 와서 그런지 좌석이 만석이었고 통유리 덕분에 연트럴이 다 보여서 좋았어요.🙂 베리 에이드랑 살구홍차 밀크티 먹었는데 베리 에이드는토핑이 예뻤고 베이스가 되는 베리청? 이 맛있어요.🍓 밀크티는 bottle이 이뻤고 밀크티 맛이 나다가 끝맛에 살구향이 나는게 좋았어요. 🍒', 24, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '원래 케이크 안좋아하는데 연말 기념으로 샀어요 근데 개맛잇어요 진짜 자르면 안에 딸기 계속나오고 보통 데코로 겉부분만 딸기있는데 여기는 안에 가득있어요 크림도 느끼하지않고 먹어도 먹어도 안질리고 빵도 부드럽고 촉촉해요 케이크 안조아하는 사람도 조ㅎ아하게 만드는 마법의 케이크에요 진짜 개마싯으니까 다들 드세요 네이버 지도에 딸기케이크 검색하면 안나오던데 나오면좋겠어요 모든사람들이 케이크맛집인거 알앗으면 좋겟네여 왕최고 개존맛', 45, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '크리스마스이브에 가족끼리 시간보내려 한달전에 예약했는데, 기대  이상이네요. 딸기도 엄청 많고 많이 달지도 않고 넘나 맛있네요. 다음 또 이용할거에요', 62, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '큰 케익은 좀 부담이라 작은 걸루 2개 밀크티 매우 맛있었고 시트케익은 부드럽고 타르트는 아래 초코가 숨어있었어요 맛있게 잘먹었습니다 곰돌이 초 같이 샀는데 넘귀여워요 ♥︎', 112, 25, 'GOOD', SYSTIMESTAMP);
