INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '딸기케이크만 픽업해서 구매했어요 정말정말 맛있어요ㅠㅠㅠㅠ 진짜 크림이 딱 적당히 달고 물리지 않는 맛이라서 커피도 필요없이 계속 들어가요! 딸기도 달고 싱싱하고 맛있어요🥹 케익이 맛있으면 이렇게 행복하구나 하고 오랜만에 느껴봤어요 많이 파세요~~', 55, 15, 'GOOD', SYSTIMESTAMP);
