INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '저녁시간에 가서 디저트가 없어서 아쉬웠지만 밀크티 덕후로서 다양한 밀크티가 있어서 너무 좋았습니다 가격은 꽤 나가서 많이 마시지 못한게 아쉽고 밀크티외의 논커피 음료가 다양하지는 않아서 같이간 친구가 메뉴 고르는걸 어려워 하더라구요 밀크티는 넘나리 왕짱 맛잇엇어요', 22, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '개맛있구.. 4만 2천원.. 그정도의 값어치.. 딸기 개많쿠… 동물성 크림 넘 맛있구.. 시트도 넘 보드랍구.. 딸기 좋아하면 강추.. 진짜 넘넘 맛있당..', 1, 6, 'GOOD', SYSTIMESTAMP);
