INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '배부른 상태로 가서 버터팬 못먹은건 아쉽지만 ,, ㅠㅠ커피는 맛있었어요 원두를 두가지 중에 골라서 마실 수 있는게 좋아요 뷰랑 채광이 좋아서 사진도 잘나옵니다', 49, 6, 'GOOD', SYSTIMESTAMP);
