INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '딸기 케익 두번 사서 지인들과 나눠먹었는데 두번 다 성공요 다른 분께도 추천드렸는데 맨날 케익 남기는 모임에서 다 먹어버렸다고 ㅎㅎㅎ 다른 음료도 다 맛있는거보니 기본적으로 음식을 아주 잘하시는 분들이 만들어주시는 것 같습니다', 10, 8, 'GOOD', SYSTIMESTAMP);
