INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '크리스마스케이크 알아보다가 딸기가정말많길래 예약성공했네요! 촉촉하고 딸기밭이에요 ㅎㅎ 직접만든크림인느낌인게 딱보여요 !몰랐는데 밀크티맛집이요기있네😄', 73, 16, 'GOOD', SYSTIMESTAMP);
