INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '가격대가 좀 있지만 음료는 확실히 맛있었어요. 말차에 제주, 보성, 하동의 맛이 다 느껴진달까.. 창가쪽에 앉으면 햇살도 잘 들어오고 뷰도 좋을 것 같아요.', 36, 4, 'GOOD', SYSTIMESTAMP);
