INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '밀크티 때문에 평소에도 자주 방문 집이에요! 최근에 딸기 케이크도 하셔서 예약없이 갔다가 품절이라ㅠㅠ 따로 예약하고 방문했구요! 다른 케이크 전문점이랑 비교해도 딸기양도 많고 단맛도 강하지 않아서 앉은 자리에서 홀케이크 하나 친구들이랑 다먹었어요ㅠㅠ 살은 찌겠지만 먹는 내내 너무 행복했어요!ㅋㅋ 😋 올해 크리스마스 케이크도 여기서 주문하기로 했고 가성비로도 만족스러워서 완전 추천입니다!! 앞으로도 맛있는 디저트 많이 만들어주세요 사장님!!ㅎㅎ', 17, 0, 'GOOD', SYSTIMESTAMP);
