INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '친구들 망년회 케이크로 샀어요! 넘 맛있어서 크리스마스케이크도 예약했어요 ㅎㅎ 요즘 카페들 케이크 가격 싸야 사만원이라 생각하는데 이가격에 이 딸기 양이라니.. 사장님 대박나세여!', 7, 2, 'GOOD', SYSTIMESTAMP);
