INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '오늘은 약 때매 라떼를 못 마셨지만 커피 & 케이크 맛집이에요!! 특히 케이크는 전국 딸기케이크 도장깨기 다녀본 결과 이 곳이 1등🥹', 32, 1, 'GOOD', SYSTIMESTAMP);
