INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '진짜 이런 엉망인 딸기케이크는 생전 첨봐요. 언제 만들었길래 토핑한 딸기가 다 물렀어요. 먹으려고 꺼내자 마자 대실망. 역시나 옆에 딸기도 다 물렀고 그러니 맛도 실망이죠. 예약까지 한 보람이 없네요.', 336, 36, 'BAD', SYSTIMESTAMP);
