INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '생일케이크 미리 주문하고 픽업해서 먹었어요! :) 너무 예쁘고, 딸기도 가득 들어있어서 너무 맛있어요 !!!!! 크림도 너무 달지 않아서 질리지 않는 것 같아요.', 11, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '비포블루밍에서 케이크 처음 예약하는 것이고 크리스마스 케이크 예약 당일날 원래 예약 시간보다 1시간 일찍가서 받았습니다. 금요일 오후5시에 갔는데 사람이북적북적 하더라구요. 케이크 고정안돼 있으니 조심히 들고 가시라 하셔서 조심조심 들고 갔습니다! 다행이 형태유지 했답니다~ 저녁먹고 디저트로 케이크 먹는데도 딸기가 많이 들어가서 그런지 쑥쑥 잘 들어가더라구요! 생크림하고 딸기랑 케이크 시트랑 조화가 너무 좋았습니다. 모양도 예쁘구요~ 너무 맛있게 잘 먹었어요. 조금 남겨서 다음날 아침에 마져 먹었는데 하루 지나도 맛있더라구요! 너무 만족 스러웠습니다! 바쁘신와중에도 응대 친절히 해주셔서 감사했습니다~', 64, 18, 'GOOD', SYSTIMESTAMP);
