INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '와 여기 뷰가 너무 좋아요! 근데 뷰만 좋은게 아니라 음료랑 디저트도 대박👍 밀크티 맛집이라는데 에이드도 넘 이쁘고 맛있어요. 팬케이크는 꼭 드세요! 비주얼만큼 맛도 좋더라구용💕', 41, 4, 'GOOD', SYSTIMESTAMP);
