INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '딸기 케이크 너무 부드럽고 커피도 다크원두 선택하니 산미없이 깔끔하고 너무 맛있어요! 매장 분위기도 깔끔하고 창문 뷰가 트여있어서 친구랑 방문하길 너무 잘했다고 생각했어요💕', 12, 6, 'GOOD', SYSTIMESTAMP);
