INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '케이크가 너무 먹고싶어서 검색하다가 들린곳인데, 딸기가 진짜 싱싱하고 엄청 달지도 않고, 맛있었어요. 진짜 딸케 미친놈입니다ㅠㅠ', 43, 1, 'GOOD', SYSTIMESTAMP);
