INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '진짜 너어어어무 맛있어요... 리얼... 또 갈게요... 시트가 보들보들하곸ㅋㅋ큐ㅠㅠㅠ 딸기도 달달하니 크리스마스케쿠로 최고...', 36, 4, 'GOOD', SYSTIMESTAMP);
