INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '매장이 깔끔하고 편안한 분위기라 이야기 하기도 좋아요!! 오늘은 배가 불러서 티만 마셨지만 다음에는 밀크티랑 케이크도 먹어보고 싶어요 ☺️🤤 다음에 또 방문할게요!!', 42, 8, 'GOOD', SYSTIMESTAMP);
