INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '유명한 곳이라서 사람이 엄청 많음. 매장이 꽉 차있음. 그래서 시끄러움. 조용한 공간을 찾은 사람들은 비추. 음료 맛은 좋으나 가격이 다소 사악함. 다양한 종류의 음료가 많음. 병은 다시 반납해야함.', 2, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '살구향이 나는 밀크티는 처음먹는데 맛과 향까지 너무맛있었네요 베리에이드도 달콤상콤!! ㅠㅠㅠ 햇살아래서 달콤한딸기케잌까지 좋은시간보냈어요!', 4, 5, 'GOOD', SYSTIMESTAMP);
