INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '사실 밀크티 종류를 좋아하는 편이 아니였는데 살구홍차 밀크티랑 스트로베리 밀크티 둘다 완벽하게 취향 저격이였어요!!! 다음에 꼭 다시 오려구요 :)', 28, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '밀크티 먹어보고 깜짝 놀랐어요~~ 너무 맛있어요^^ 히비스커스 원래도 좋아하는데, 밀크티랑 이렇게 잘 어울릴줄이야 ㅎㅎ 아이스 바나나 버터팬도 맛있었어요 ㅎㅎ 커피도 원두 선택 가능해서 좋았네요 ㅎㅎ 다음에 또 오고 싶어요 ㅎㅎ', 107, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '디저트가 워낙 유명해서 케이크도 구매해봤는데, 너무너무 맛있어요!!! 딸기도 많이 들어있고 빵도 촉촉해서 순삭했습니다ㅎㅎㅎ 비주얼, 맛 둘다 좋아서 분위기 낼 때 좋을 것 같아요! 🥳', 30, 8, 'GOOD', SYSTIMESTAMP);
