INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '연남동을 그렇게 많이 다녔는데 여기를 이제야 오다니요~!!! 밀크티 덕후인데 정말 너무 맛있었어요ㅠ 에이드도 비주얼에 치이고 맛에 치이고~ 버터팬도 처음 접해보고 맛있게 즐기다 왔네요 밀크티 생각날때마다 방문해야겠어요♡', 19, 6, 'GOOD', SYSTIMESTAMP);
