INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '9000원 딸기케이크 옆면이 다 슬라이스딸기였어요…연남동쪽이라 비싼고라생각했는데 이건좀 ㅠ 다카페어딜가도 비싸봐야8000원 딸기 가득들어있는곳들뿐인데…좀 놀랐네용', 15, 1, 'BAD', SYSTIMESTAMP);
