INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비포블루밍'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '딸기도 많고 맛있어서 연말 케이크로 딱이에요!! 저는 2시간 걸려서 좀 녹았는데 그점 빼고는 다 만족해요 2시간 이상 걸린다면 보냉팩 꼭 구매하세요!! 초 종류도 많아서 좋았어요~~', 98, 24, 'GOOD', SYSTIMESTAMP);
