INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '여자친구생일용 케이크를 샀는데 포장도 너무 예쁘고 근데맛이 진짜 미쳤습니다.. 기념일 케이크는 분위기 내는 용으로 조금 먹고 버리는경우가 많았는데 이 케이크는 여친이랑 김탄하면서 먹었어요~~', 26, 5, 'GOOD', SYSTIMESTAMP);
