INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '남자친구 생일 기념으로 구매했는데 예쁜데 맛도있어서 엄청 좋아했어요!! 사장님이 진짜 친절하세요!! 예약부터 픽업할때까지 계속 신경써주셨어요:) 타르트도 사진이랑 똑같이 너무 예쁘고 포장도 신경써서 해주셔서 하루종일 들고 다녀도 안망가졌습니다!! 오래오래 운영해주세요🩶', 47, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '세련된 인테리어에 비주얼 폭팔 디저트가 끌려서 왔어요. 땅콩크림커피 너무 부드럽고 고소해요 특히 크림이 안느끼하고 맛있어요. 바스크치즈케잌은 진짜 부드럽고 사르르 녹는 맛이에요. 타르트랑 디저트류가 품절이 많아서 다음에 또 오려구해요 음악도 좋고 화장실도 남녀 나누어져 있어서 좋았어요.', 44, 2, 'GOOD', SYSTIMESTAMP);
