INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '합정쪽에 카페 어디가지 싶다가 우연히 들렸는데 디저트 종류가 많아서 좋더라구요!! 내부도 힙하게 꾸며져있어서 사진도 잘 나와요 체리타르트랑 얼그레이 밀크티 강추드립니다🥹!! 과일이 무름없이 달고 맛있어요 치즈케이크 같은 느낌의 타르트고 밀크티는 많이 안달아서 좋더라구요 ㅎㅎ', 70, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '합정역 주변에 진짜 맛있는 디저트카페를 찾으시는 분들 계신다면 <미니멀비> 아주 강력추천드려요!!! 커피야 말해뭐해 당연히 맛있는데요, 디저트류가 진짜 흡입하기 시작하면 순삭되더라구요 ㅎㅎ 조각케이크류만 먹어봤지만 다음에 재방문하면 다른 것들도 먹어보고 싶어요♡♥', 43, 6, 'GOOD', SYSTIMESTAMP);
