INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), 'B크림커피 디카페인원두로 변경해 먹었는데 고소하면서 달달한 크림라떼에요 또 먹으러가고 싶을정도로 맛있는 라떼네요 ㅎㅎ 리치 캐모마일 릴렉서도 편안해지고 맛있어서 좋았어요 기대를 품고 대망의 ♥️단호박 치즈케이크♥️한입했는데., 같이 간 친구와 함께 미간이 절로 찌뿌려지고 감탄까지 나왔네요 진짜 너무 맛있어서 핵추천. 단호박을 직접 찌고 으깬 수제케이크! 크림과 함께 먹으니 달달하면서 맛있네요ㅎㅎ 다음 기념일 있을때 여기 단호박치즈케이크 예약하려고요 ❕', 30, 8, 'GOOD', SYSTIMESTAMP);
