INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '친구 생일케이크로 주문했어요. 타르트 너무 이쁘네요ㅠㅜ꼼꼼하게 포장해주셔서 감사해요. 오토바이 타고 갔는데 다행히 안망가졌어요. 다음에도 또 주문하러 갈게요ㅠㅜㅠ 감사합니다.', 80, 14, 'GOOD', SYSTIMESTAMP);
