INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '가족 생일 케이크로 예약했는데 다들 요근래 먹은 케이크 중에 제일 맛있는 케이크라고 하더라구여 앞으로도 케이키 주문할 일 있으면은 미니멀비로 갈 것 같습니당🥺🥺♥️', 50, 7, 'GOOD', SYSTIMESTAMP);
