INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '레몬타르트와 딸기크림라떼, 자두 히비스커스 이렇게 시켜서 먹었는데 소문대로 역시 타르트 존맛탱이에요! ㅎㅎㅎ 디저트와 음료 다 너무 맛있어요💕', 42, 3, 'GOOD', SYSTIMESTAMP);
