INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '예쁘고 맛있어요 ㅎㅎ 체리 겉에만 있는게 아니라 크림치즈? 안에도 박혀있어요 🍒🍒🍒🍒굿~~~~ 1호 사이즈 작을까봐 걱정했었는데 생각보다 안 작아보이고 딱 좋았습니다 다음에는 단호박치즈케이크 주문하러 오겠습니다 🎃', 6, 9, 'GOOD', SYSTIMESTAMP);
