INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '캎0 분위기가 아기자기하니 예뻤고, 혼자서 가기에도 좋은 곳이에요. 특히 디저트 중 과일 타르트가 맛있었는데 싱싱한 과일을 바로 잘라 올려주시는게 좋았어요!', 2, 4, 'GOOD', SYSTIMESTAMP);
