INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '모던하고 예쁜 아이템들이 가득 있어서 사진 엄청 찍었어요❤️ 커피도 맛있고 브라우니도 꾸덕하니 왜이렇게 맛있어요....? 사장님도 넘 친절하시구☺️ 요런 카페는 아지트로 딱이져👍 좋은 카페 발견해서 햅삐합니다 잘 쉬다 갑니다 브금도 다 좋아요 느좋카페☕️', 21, 0, 'GOOD', SYSTIMESTAMP);
