INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '최고의 타르트맛집… 넘 달지도 않고 과일도 신선해서 홀케이크 하나 다 먹을 수 있을 것 같은 맛(진짜로) 삐크림커피도 너무 맛있었어요💗💗', 38, 10, 'GOOD', SYSTIMESTAMP);
