INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '친구 생일 케이크로 바스크 치즈케이크를 구입했는데, 블루베리 토핑으로 심플한 디자인으로 예쁘고 맛도 좋았어요. 크림은 고소하고 부드럽고, 치즈케이크 자체도 진하고 맛있어서 모두 잘 먹었습니다.', 56, 18, 'GOOD', SYSTIMESTAMP);
