INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '생일이라 케이크 포장 예쁘게 해주시고 요요 체리가 너무 예쁜 뽀인트가 되는 거 같아용!! 워낙 바치케를 좋아하는데 여긴 성분도 좋고 안에도 실해서 2명이서 먹기 양이 너무 좋아요!! 사는 곳과 거리만 가까우면 단골될텐데 ㅜㅜㅠ 전국에 생기면 좋겠단 마음😂', 28, 0, 'GOOD', SYSTIMESTAMP);
