INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '엄마랑 같이 방문했어요! 타르트가 너무 맛있어요 커피향도 산뜻하고 매장도 쾌적해서 대화하기 좋았어요 다음에 또 방문하겠습니다♡', 74, 18, 'GOOD', SYSTIMESTAMP);
