INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '케이크가 너무 이쁘고 맛있었어요!! 기념일에 케이크가 너무 잘 어울렸어요 ㅎㅎ 특별한 날에 이쁜 케이크가 필요하다면, 추천드립니다!', 65, 18, 'GOOD', SYSTIMESTAMP);
