INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '오랜만에 만난 친구 취업 기념 겸으로 예약했는데 예쁜데 맛도있어서 디저트 별로 안 좋아하는 친구인데도 엄청 좋아했어요!! 절반 넘게 잘 먹어서 너무 뿌듯했어요 ㅎㅎ 그리구 사장님이 진짜 친절하세요!! 퇴근 시간 차 막힘 이슈와 지하철 이슈로 예약 시간보다 늦었는데도 너무 친절히 대해 주셔서 감사했습니다!!! 타르트도 사진이랑 똑같이 너무 예쁘고 브라우니도 진짜 촉촉하고 맛있고 포장도 예쁘고 신경써서 해주셔서 퇴근길 지하철에 들고 다녀도 무사히 잘 가지고 왔습니다!! 또 방문할게요 사장님 😍🤍', 54, 13, 'GOOD', SYSTIMESTAMP);
