INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '조용하고 깔끔한 분위기의 카페. 커피는 산미 적고 깔끔해서 마시기 편했어요. 바스크 치즈케이크는 겉은 살짝 바삭하고 속은 꾸덕해서 딱 좋았고, 단맛도 과하지 않아서 커피랑 잘 어울렸습니다. 재방문할께요❤️🍰🧋☕️', 39, 8, 'GOOD', SYSTIMESTAMP);
