INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '생일에 케이크사면 잘 안먹게돼서 미니로 주문했는데 너무 맛있어서 다먹었어요!!! 2명이서 먹기 딱이고 무엇보다 넘예뻐요 ㅎㅎㅎ 다음에도 여기서ㅜ살게용 ♥️', 19, 4, 'GOOD', SYSTIMESTAMP);
