INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '보기에도 예쁜데 맛은 더 최곱니다 💚🎂 생각보다 주변에 청포도타르트 파는 곳이 없어서 찾다가 발견한 곳인데 포장도 너무 예쁘게 해주시고 축하받은 남자친구도 너무 만족해했어요 다음엔 다른 종류 케이크도 먹으러 가볼게요 💕', 7, 7, 'GOOD', SYSTIMESTAMP);
