INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '친구 생일이라 예약하고 갔는데, 사장님께서 센스있게 생일인지 물어보고 생일끈으로 포장도 해주셨습니다!!👍👍 케익도 너무 이쁘고, 맛있어서 친구가 넘넘 좋아했습니다!! 이렇게 이쁜 단호박케이크 첨봐요 🥹🥹 담에 합정오면 저를 위한 선물로 사가려구용 😁😁', 15, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '합정근처 예쁘고 맛있는 케이크 찾다가 미니멀비가 생일케이크로 딱일 것 같아서 며칠전부터 예약주문해서 픽업해왔습니당 ㅎㅎㅎ 남자친구 생일이어서 주문했는데 너무너무 좋아했어요 >_< 저는 같이 먹어보진 못했는데 너무 맛있대요!! 정성스럽게 포장도 해주셔서 좋았습니다~ 생일케이크 찾으시는 분들 추천드려요❤️', 57, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '우선 사장님께서 너무 친절하셔서 예약부터 픽업까지 기분좋게 할 수 있었어요! 1호 사이즈는 너무 작지도 부담스럽게 크지도 않아서 선물하기 딱 좋은 것 같아요! 디자인도 너무 예쁘고 친구가 맛도 있다고 합니다 다음에 또또또! 이용할게요:)', 25, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '제 단골집이 될 것 같아요..... 징짜 너무 맛있어서 한 판 다 퍼먹고 친구들이 어디껀지 알려달라고 톡왔자나요 ㅋㅋㅋ맨날 강아지들이랑 산책 다니면서 지나친 곳인데 이런 대박 맛집이었구나💛 번창하세요', 5, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '처음 받았을 때 너무 예뻐서 놀랐어요 기념일에 케이크말고 다른거 고민하고 있었는데 완전 만족해요 심지어 맛도 있음 다음에 또 이용할게요', 40, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '사진은 1호 크기 타르트예요! 너무너무 맛있어서 원래는 조금만 먹고 포장해가려고 했는데, 거의 다 먹고 한조각 정도 남았어요ㅎㅎ.. 타르트쉘도 너무 맛있고.. 크림도 동물성에 살짝 크림치즈향 나는 것 같고.. 타르트 안은 치즈케이크인데, 너모 맛있어요.. 사장님도 넘 친절하시고 좋은 경험이었습니당 ❤️', 0, 0, 'GOOD', SYSTIMESTAMP);
