INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '일반 생크림케익은 더워서 금방 녹을까봐 이 곳을 찾았는데 완전 잘 선택한것같아요! 픽업하고 다음날 파티한건데 빵부분도 전혀 안눅눅하고, 무엇보다 많이 달지않고 적당히 상큼해서 가족모두 잘 먹었습니다. 후식으로 정말 깔끔한 디저트였습니닷', 96, 21, 'GOOD', SYSTIMESTAMP);
