INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '애용하고 애정하는 카페 !! 평소 여기 디저트를 너무 좋아하는데  지인 생일을 맞아 홀케이크는 처음 주문해봤어요!! 아낌없이 들어간 체리도 너무 신선하고 크림이랑 타르트지도 부드럽고 맛있어요ㅠㅠ일단 맛이 미친 건 익히 알았는데 비주얼까지 미쳤네요...(positive) 심플한데 고급져서 기념일에 자주 이용하려고 합니다!! 지인 만족도 1000000🫧🩷', 9, 3, 'GOOD', SYSTIMESTAMP);
