INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '와ㅏㅏ 너무 맛있었어요ㅠㅠㅠ 밑에 치즈인주 알았는데 단호박? 치즈라 다른느낌 ..!!!!! 기념일마다 켘크순이라서 꽤 많은 케이크를 먹어본고 같은데 단연 일등입니다 .. 깜짝 놀랐어요❤️‍🔥❤️‍🔥 다음에도 합정오게되면 무조건 이거 살려고요ㅠㅠㅠ 켘쿠 두조각 이상 먹은거 처음이에요 ,,, 요 메뉴 없애지말아쥬세요ㅠㅠㅠㅠ 단호박치즈 진쨔 체고에요 예쁘규 맛있어요 강추!!', 33, 1, 'GOOD', SYSTIMESTAMP);
