INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '그냥 너무 맛있어요....케이크 필요할때마다 또 주문할 것 같아요🥹😭 미니멀비 케이크 처음 주문해봤는데  이쁘기도 하고 맛있기도 하고 다 만족합니다💗 케이크 좋아하신다면 꼭 큰걸로 주문하세요!!😘❤️', 82, 13, 'GOOD', SYSTIMESTAMP);
