INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '세련된 외관과 감성 가득한 인테리어로 눈길을 사로잡는 디저트 카페, 미니멀비! 내부는 미니멀한 감성이 돋보이는 조용하고 아늑한 분위기라 데이트 장소로도 안성맞춤✨ 특히 딸기치즈타르트는 신선한 생딸기와 진득한 치즈크림이 어우러져 완벽한 밸런스를 자랑하고, 아메시스트 리치는 상큼한 리치 풍미에 달콤함이 더해져 리프레시 하기 딱 좋아요! 분위기 좋은 공간에서 감각적인 디저트와 음료를 즐기고 싶다면, 미니멀비 꼬옥 방문해보세요ㅎㅎㅎ', 33, 5, 'GOOD', SYSTIMESTAMP);
