INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '포장도 이쁘게 해주시구 타르트도 넘 이쁘고 진짜 맛있었어요 ㅎㅎ 사장님께서 넘 친절하셔서 기분좋은 시간 보내고 올 수 있었습니다☺️ 다음에 또 방문할게요~~', 38, 5, 'GOOD', SYSTIMESTAMP);
