INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '단호박 치즈 케이크 미니 구매했습니당! 다른 곳보다 가격도 착하고, 적당히 달아서 부담 없이 맛있게 먹었어요! 🤤 특히 바닥에 로투스가 깔려 있어서 전체적으로 조화가 좋았고 단호박 생크림(?)도 케잌 윗시트에 도포되어 있어서 비주얼도 더 고급스럽고 정성 가득한 느낌이었어요!!!! 남자친구랑 기념일에 맛있게 잘 먹었습니당! 감사합니다 ☺️🤍', 20, 8, 'GOOD', SYSTIMESTAMP);
