INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '체리치즈타르트랑 단호박 미니로 예약하고 픽업했어요...! 와! 제가 먹어본 치즈타르트 중에서 제일 맛있어요... 😍😍 하나도 안느끼하고 촉촉하고 너무너무 맛있게 먹었답니다? 선물용으로도 좋을 것 같고 최고입니다!!', 23, 10, 'GOOD', SYSTIMESTAMP);
