INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '너무너무너무너무X100 맛있었어요. 보통 단호박디저트라해도 단호박맛은 별로 안나서 항상 아쉬웠는데 여기는 진짜 단호박이에요!! 담백하서 너무 좋았어요. 위에 올라가는 크림치즈도 하나도 안느끼하고 좋은 재료를 쓰시는게 티가나는 느낌입니다. 자칭 디저트박사인 제가 인정합니다! 최고에요. 리뷰이벤트로 받은 스콘도 ㄹㅈㄷ… 빵느낌보다는 쿠키처럼 바삭한 식감입니다. 너무 맛있어요!! 단호박치케와 체리타르트중 엄청 고민햤었는데 잘한 선택같습니다. 다음에는 체리타르트도 먹어보려구요!! 사장님께서도 엄청 친절하셨어요! 아 그리고 케이크 양도 엄청 많아요 둘이서 다 못먹고 남겼습니다ㅠㅠ 아직 남긴 케이크가 아른거리네요..ㅠㅠ', 118, 25, 'GOOD', SYSTIMESTAMP);
