INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '매장 엄청쾌적하고 시원하고 예쁜인테리어랑 귀여운디저트도 많은곳이였어욤🫶 사장님도 너무친절하게 안내해주시고🥺 케이크가 넘귀엽고 짱이었답니당ㅎㅎ 감사합니다~!', 65, 18, 'GOOD', SYSTIMESTAMP);
