INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '합정역에 미니벌비 케이크 들고 다니는분이 대다수 ㅋㅋㅋㅋ! 맛도 좋고, 비주얼도 너무 예뻐요 요즘 디저트류 터무니없이 비싼데 가격도 적당해요❤️ 담에 또 방문할게요~~🫶🏻👍🏻🤍', 26, 9, 'GOOD', SYSTIMESTAMP);
