INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '너무 더울때 발견한 카페에요! 커피마시고 싶을때 들리기 좋은 곳입니당 소품이 많아서 볼 재미가 있어요!! 사장님도 친절하세요 ㅎㅎ', 15, 5, 'GOOD', SYSTIMESTAMP);
