INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '바치케 체리 버전으로 예약주문했습니다! 케잌을 좋아하지 않는 편인데도 너무 맛있어서 먹을때마다 감탄했어요ㅠ 예뻐서 사진도 잘 나오고 맛도 엄청나요 와인이랑 곁들이니 더 맛나네요💛 항상 1호 케이크 사서 2명에서 먹으면 다 남기는 바람에 골치가 아팠는데 미니 버전으로 사니 너무 좋았습니다🫶 바치케가 이리 맛있으면 타르트는 또 얼마나 맛있을까요ㅠ 타르트가 기대되는 맛이었습니다 담엔 타르트 주문해보고싶어요 사장님도 엄청 친절하시고 매장도 예뻐요 케잌 덕분에 여러모로 멋진 생일 보낼 수 있었습니다👍', 32, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '처음 주문해봤는데 너무 맛있어서 좋았어요! 픽업 도와주시는데 사장님이 엄청 친절하셨어요 생일케이크라고 물어봐주시고 리본도 생일 리본으로 예쁘게 감아주셨어요 위에 올라간 포도도 무른거 하나 없이 단단하고 달콤하고 크림도 고소하고 안에 들어있는 치즈크림도 느끼하지 않고 맛있었어요 요즘 케이크 비싼데 가격도 합리적이고 여러모로 아주 만족스러운 타르트였어요!', 21, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '인테리어도 아기자기하고 데이트하기 좋은 카페입니다. 실제로 커플이 많더라고요~! 디저트도 맛있고 사장님이 친절하신 곳입니당👍🏻', 58, 14, 'GOOD', SYSTIMESTAMP);
