INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '친구 생일케이크로 주문했어요! 포장도 너무 이뻤구 무엇보다 주문하는 과정에서 너무너무 친절하게 해주셔서 기분 좋게 주문했습니당🤍 받은 친구가 맛도 너무 좋다구 해서 다음에 또 다른 친구 생일때도 주문하려구요!!💛', 27, 4, 'GOOD', SYSTIMESTAMP);
