INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '* 체험권을 일부 제공 받았으나 솔직하게 작성한 리뷰입니다! 합정역 지나다니면서 꼭 한 번 가보고 싶었던 궁금한 카페였는데, 가보니 더 더 좋았어요🥹 사장님이 친절하신 건 물론이고 수제 디저트 종류가 많고, 깔끔하고 담백해서 더 맛있었어요! 원두도 앤트러사이트 원두 쓴다셨는데, 그래서 그런지 더 꼬숩고 맛있는 느낌이더라구요..🤍 산미가 없고, 덜 달아서 제 입맛에 너무 잘 맞았어요..ㅋㅋㅋㅋ 반려동물 동반 카페라 놀러오는 강쥐들 구경하는 재미도 있는 카페예요!🍰', 47, 8, 'GOOD', SYSTIMESTAMP);
