INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '일단 너무 예쁘구요! 생일이라고 하니까 예쁜 리본도 감아주셔서 너무 감사했습니다 ㅎㅎ 1호 기준 2명에서 먹기 딱 적당해요~ 다른 타르트도 다 먹어보고싶어요💛🧡', 67, 12, 'GOOD', SYSTIMESTAMP);
