INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '커피도 맛있고, 디저트들도 너무 맛있어요 !! 분위기도 좋은데 직원분들도 너무 친절하셔서 다음에 또올것 같습니다! 타르트는 꼭드셔보세요!!!', 60, 12, 'GOOD', SYSTIMESTAMP);
