INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '여러분 .. 여기 타르트 찐 맛집이에요 😀❤️ 특히 딸기치즈타르트 미쳤어요 !! 꼭 먹어보셔야해요 상큼한 딸기랑 부드러운 크림치즈타르트의 조합 .. ! 너무 잘 어울러요 ㅎㅎ 그리고 아메리카노도 산미가 적어 호불호갈리지 않을 것 같아요 ㅎㅎ 타르트랑 커피 조합은 맛없없이잖아요 !!!!! 그리고 딸기크림라떼도 상큼하면서 달달하면서 위에 크림 가득 .. 넘 맛있어요 !!', 49, 10, 'GOOD', SYSTIMESTAMP);
