INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '진짜 살면서 먹은 타르트중에 제일 맛있는거 같아요....!!! 5년 넘게 친구들 생일마다 서로 케이크 해줬는데 그중에서 제일 맛있게 먹은 타르트에요 ㅜㅜㅜ 타르트 시트에서 밀가루맛 나거나 퍽퍽한 타르트들도 많이 봤는데 여기는 타르트 시트 자체가 너무 고소하고 맛있어요 체리랑 치즈 조합도 너무 고급지고 맛도 대박이에요 나중에 혼자라도 꼭 다른맛까지 포장해가고 싶을정도로 맛집입니다🥹❤️', 36, 6, 'GOOD', SYSTIMESTAMP);
