INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '케이크 남자친구 생일 기념으로 주문하고 픽업하러 왔다가 분위기 보고 커피까지 마시고 갑니다 :) 사장님도 너무 친절하시고 생일 케이크라고 생일 끈까지 묶어주시는 센스까지 .. 최고 ! 🤍', 18, 9, 'GOOD', SYSTIMESTAMP);
