INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '타르트 찐맛집이에요!! 타르트 치즈가 진짜 맛있었어요!! 시그니처 크림 밀크티랑 딸기라떼도 너무 부드러웠습니다!!🥹🤤 이번에 딸기타르트 먹었는데 다음엔 샤인머스켓 먹어봐야겠어요 ㅎㅎㅎ 타르트 최고👍', 22, 4, 'GOOD', SYSTIMESTAMP);
