INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '두번째 방문입니다! 저번에 먹었던 딸기타르트... 문의답변두 빨리주시고 당일이라 네이버예약못해서 따로 톡문의넣은건데 너무 잘해주셨어요.... 게다가 너무이쁨...맛있어서 담에도 예약해야지 하고 어버이날기념으로 주문했습니다 타르트너무맛있어요~!!! 감사합니다~', 46, 5, 'GOOD', SYSTIMESTAMP);
