INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '단호박 맛 크림에 쿠기같은 시트가 잘 어우러지는 맛이었습니다!! 브라이덜 샤워에 맞게 예쁘게 포장해주셔서 감사했습니다! 예쁜 케이크 덕분에 더욱 즐거운 파티였습니다~', 33, 8, 'GOOD', SYSTIMESTAMP);
