INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '작년 어버이날 케익도 합정에서 주문해서 올해도 예뿌고 맛있는 카페 찾다가 후기가 너무 좋고 비주얼도 예뻐서 주문하게 되었어요!! 사정이 생겨서 픽업시간을 변경 해야 했는데도 친절하게 응대해 주셨고 픽업 가서도 필요한거 세세히 물어봐주시고 잘 안내해주셔서 좋았습니다. 타르트도 바삭바삭했고 치즈케익도 너무 안달아서 맛있었어요!🥺딸기 솔직히 철이 지난것 같아서 안달거라고 생각했는데..달아서 너무너무 맛있었습니다🤩🥰부모님도 좋아하셨어요ㅎㅎ다음 기념일에도 또 방문하겠습니다💃🏻🕺🏻', 55, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '미니스콘 때문에 남기는거 아니고 지인짜 맛있게 먹어서 남기는 리뷰! 남친 생일이라 기성 케익말고 맞춤케익 사주고 싶어서 찾아보다가 예약했어요😊 보기에만 예쁘고 맛은 쏘쏘하면 어쩌지? 하고 걱정했는데 진짜 맛있는 타르트입니다💖 쿠키시트도 너무 맛있고 중간에 크림치즈랑 위에 올라간 생크림.. 그리고 과일 조합이 너무 좋아요👍 전 컬러 때문에 딸기랑 샤인 반반했는데 과일도 비싼거 쓰시는 듯 합니다 ㅎㅎ 진짜 완전 제 스타일 케익 찾아서 매우 기뻐요.. 자주 사먹고싶어요💕 비쥬얼+맛 100점!', 117, 23, 'GOOD', SYSTIMESTAMP);
