INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '분위기도 좋고 사장님이 너무 친절하십니다!! 친구 생일이라 레몬 홀타르트도 주문했는데 너무 이쁘고 맛있어보여요! 리치에이드 상큼하고 맛있어요!!', 26, 6, 'GOOD', SYSTIMESTAMP);
