INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '디저트 종류가 다양하고 딸기치즈타르트가 너무너무 맛있는 카페입니다. 입에 넣자마자 사르르 녹아버리는 마법!!!... 반려동물동반 가능한 카페이고요... 곳곳에 미니미한 장식품들이 전시되어있어서 보는 재미도 쏠쏠합니다. 귀여운 초들도 판매하고 있습니다. 조만간 디저트 먹으러 또 방문예정입니다.', 42, 7, 'GOOD', SYSTIMESTAMP);
