INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '유명한 연예인들도 많이 들린곳 미니멀비 방문💗💗 카페도 너무귀엽고, 디저트도 맛있고 따뜻한 음료가 먹고싶어서 히비스커스 레몬 주문했어요 ㅎㅎ 디저트랑 음료가 다 맛있어서 주문을 너무 잘한것같아요😆💗💗크림도 엄청 부드럽고 달달하니 맛있어요😆😆 혼자오기 너무좋아요💕사장님도 친절하시고 재방문하고싶은곳입니당 ㅎㅎ 카페도 귀여워요 ㅎㅎ', 75, 17, 'GOOD', SYSTIMESTAMP);
