INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '디카페인 맛있는 카페 찾기가 어려운데 여기는 저녁에 와도 맘 놓고 커피 마실 수 있어서 너무 좋음. 사장님들이 커피맛 잡기 위해 노력한 게 보일 정도로 발란스가 좋음. 스콘 중에 얼그레이 스콘이 젤 최애인데 풍미가 가득함. 얼그레이 짱맛나잉🥨🥨🥨항목 중 5개만 골라야 한다는 게 아쉬움. 🥺🐶🥺', 93, 21, 'GOOD', SYSTIMESTAMP);
