INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '글 쓴 게 삭제되고 리뷰가 올라가서ㅠ 아버님 칠순 케이크로 예쁜데 맛있고 좀 특별한 걸로 엄청 검색하다가 찾아냈어요! 픽업하러 갔다가 카페에 반하고, 스콘도 샀는데 맛에 반하고, 케이크는 칭찬도 받았어요🥰 기념일 생길 때 또 주문하러 갈게요~~', 18, 6, 'GOOD', SYSTIMESTAMP);
