INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '딸기치즈타르트 1호 예약했는데 정말 맛있어요 💝 치즈 타르트 위에 있는 크림이 너무 맛있고 딸기랑 너무너무 잘 어울려요... 생일케이크면 리본도 HBD 써있는 걸로 해주시는 센스까지✨..! 원래 리뷰 잘 안 남기는데 맛있어서 남기러 왔습니다... 크기가 엄청 크지는 않지만 가격도 적당하고 무엇보다 맛있어서 재방문 할 것 같아요 🤤🍓❤️', 36, 9, 'GOOD', SYSTIMESTAMP);
