INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '단호박치즈케이크는 부드러운 단호박케이크맛이었어요!!! 약간 당근케이크? 느낌도 나면서 너무 맛있었어요 ㅠㅠㅠ그리고 딸기 타르트도 딸기듬뿍해서 상큼하고 맛있었고 서비스로주신 스콘도 징짜 맛있었어요', 18, 4, 'GOOD', SYSTIMESTAMP);
