INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '치즈케이크가 너무 이뻐서, 선물하기 좋습니다! 선물해서 맛을 모르겠네요 ㅜ 카페안에 커플들이 케이크 먹고있는 거보면 맛있을 듯합니다. 보기좋은 떡이 맛도 좋다', 32, 2, NULL, SYSTIMESTAMP);
