INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '남편생일이라 주문예약후 픽업했어요!!🩷 딸기치즈타르트 정말 최근 먹었던 케이크 중에 정말 최고예요 ㅋㅋ 생일이라 케이크 여러개 선물받았는데, 이것만 다 먹었어요 다음에 기념일이 아니더라도 주기적으로 생각날거같네요!!☺️ 예쁘게 만들어주셔서 너무 감사합니다!! 다음에 또 주문할게요!', 3, 10, 'GOOD', SYSTIMESTAMP);
