INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '약속 잡힌 식당 근처에서 가기 전에 노트북 할 카페 찾다가 너무 귀여운 곳 발견했어요! 코드도 있고 작업하기 좋고 사장님 친절하시고 스콘이 너무 맛있습니다 🤎', 48, 9, 'GOOD', SYSTIMESTAMP);
