INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '처음먹어보는 단호박 치즈케이크였는데, 정말 맛있게 먹었네요. 전혀 달지 않고 재료 본연의 맛은 적당하게 잘 나는 맛이었네요. 재방문 의사있습니다!', 48, 1, 'GOOD', SYSTIMESTAMP);
