INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '친구 생일이라 예약했어요!! 근데 칼퇴도 못하고 비도와서 좀 늦었는데도 친절하게 대해주셔서 너무 죄송하고 감사했어요😭😭 레몬타르트라 너무 새콤하면 어쩌지 했는데 적당한 레몬맛이라 커피랑 진짜 잘어울렸고 타르트지도 너무맛있었어요!!! 재방문 의사 완전 있습니다!!! 솔직히 딸기타르트랑 고민했는데 레몬으로 하길 너무너무너무 잘한 것 같아요 >.<', 86, 12, 'GOOD', SYSTIMESTAMP);
