INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '늘 기념일마다 케이크 맛집찾아 여기저기 예약하면서 먹어봤는데 진짜 여기 서울 강남 찐 케이크맛집이에여☺️ 2년전에 케이크맛집체인점 하나 찾았었는데 거기보다 여기가 더 맛있는거같아여 엄청 달달하고 진짜 꾸덕..딱제취향이었어용 남자친구랑 3주년 기념일로 케이크 예약했는데 늘 큰사이즈는 다못먹으니 작은거 하자~ 해서 그냥 맛집이라니까 한번 주문해서 먹어봤는데 큰걸할껄ㅠ 하고 바로 후회했어요! 곧 돌아오는 남자친구 생일에도 여기서 할거에용 ㅎㅎ 너~무 맛있게 잘먹었습니다아 !', 26, 3, 'GOOD', SYSTIMESTAMP);
