INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '생크림 케익 말고 다른 케익 찾다가 우연히 발견한 타르트케이크 집 미니멀비,,,, 다른 후기들처럼 진짜 맛있습니다🥺🥺 느끼함 없이 과하지 않은 단맛에 물리지 않고 계속 들어갑니다ㅜㅜㅜㅜ 앞으로 자주 애용할 예정이에요🫶🏼', 26, 2, 'GOOD', SYSTIMESTAMP);
