INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '진짜 너무 맛있었어요!! 생크림으누안달고 밑에 파이 안에 있는 크림이 달달해서 딸기랑 잘 어울렸고 냉장고에 넣고 다음날 먹었는데도 파이가 안 딱딱하고 부드럽게 잘려서 정말 좋았습니저 진짜 맛있었어요', 19, 7, 'GOOD', SYSTIMESTAMP);
