INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '급하게 홀케이크가 필요해서 당일에 바로 전화하고 방문했는데 살 수 있어서 너무 다행이었어요🩷 사장님 너무너무 친절하시고 케익도 너무 예쁘네요! 또올게요🩷', 45, 1, 'GOOD', SYSTIMESTAMP);
