INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '친절하신 사장님 덕분에 강아지 데리고 편하게 커피마시고 쉬다갈수 있어서 너무 좋습니당❤️ 땅콩크림커피 제 최애가 되버렸어요 ㅜㅜ🙌🏻 다음에 또 산책할때 들릴게요!!! ~_~ 강아지 너무 기여워해주셔서 감사합니당 !!', 69, 16, 'GOOD', SYSTIMESTAMP);
