INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '아빠 생신 케익으로 주문했는데 온가족 모두 맛있게 잘 먹었습니다!☺️ 사장님도 너무 친절하세요 ㅎㅎ 내부도 너무 예쁘고 조용조용하네요 ! 또 방문할게요☺️', 71, 18, 'GOOD', SYSTIMESTAMP);
