INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '자르고나서 찍어버렸... 체리랑 생크림케익 좋아하시는 부모님 생신 기념으로 서치끝에 예약 후 방문했는데요. 방문 전 예약안내 과정에서 문의드린 부분도 잘 답변해주셨고, 받아본 케익도 너무 맛있고 상태가 좋았습니다. 기념일을 덕분에 잘 보냈습니다. 미니스콘도 감사하고 다음번에 또 방문할게요~!', 46, 8, 'GOOD', SYSTIMESTAMP);
