INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '예약후 이용했습니다 생일케잌 주문했는데 정말 맛있게 다같이 나눠먹었습니다 어르신들도 좋아하시는 맛이더라구요 ㅎㅎ 사진은 못찍었지만 덕분에 행복한 생일파티 했습니다 이번엔 청포도 타르트를 주문했는데, 다음번엔 꼭 딸기타르트도 주문해보고싶어요 ㅎㅎ 서비스스콘도 너무 맛있네요! 디저트맛집 인정합니다 일하시는분들도 넘 친절하고 이쁘세요🥹', 28, 3, 'GOOD', SYSTIMESTAMP);
