INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '커피 다 맛있어요.  분위기도 편하고 사장님들 너무 예쁘시고 친절해요. 애견동반이 되서 강쥐랑 산책하다 커피한잔 하기 좋고요. 하이볼, 데낄라도 있는데 밤에 커피 대신 먹기 좋아요.', 42, 7, 'GOOD', SYSTIMESTAMP);
