INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '미니 케이크가 생각보다 작지 않아요!! 정성이 가득 담긴 비주얼에 먼저 반했고, 한입 먹자마자 ‘오…’ 소리 나왔어요. 치즈는 촉촉하고 부드러웠고, 크림은 전혀 느끼하지 않고 깔끔해서 부담 없이 먹을 수 있어요. 특히 마음에 들었던 건 사이즈! (1~2인 추천드려요) 케이크 자체가 너무 예뻐서 선물용으로도 최고일 듯!!!🥹👍🏻👍🏻👍🏻', 42, 3, NULL, SYSTIMESTAMP);
