INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '다양한종류의 흔치않은 디저트가 많아요 분위기도 힙해서 사진찍고 데이트하기좋고 애견동반도가능 그리고 단호박타르트위에 크림이미쳣어요 꿀맛 이거먹으러맨날올ㅇ래요ㅠㅠ 식후에간거라 시원하고 달달한음료생각나서 한라봉스파클링주문했는데 새콤달콤 팡팡해서 속이 뻥뚫리는 시원함 합정카페 강추', 6, 3, 'GOOD', SYSTIMESTAMP);
