INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '친구 생일이라 2호 사이즈 준비했어요! 둘이 먹으니 양이 많아서 절반은 친구 손에 들려줬네요 ㅋㅋㅋㅋ 딸기타르트 많이 먹어봤는데 여기만큼 가성비 좋고 딸기 큰걸로 많이 올려주는 곳 처음 봤어요! 사장님도 너무 친절하시고 매장도 깨끗해서 다음엔 커피 마시러 가려구여 ㅎㅎ', 20, 10, NULL, SYSTIMESTAMP);
