INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '맛있는 크림스콘이 있는 합정 미니멀비🧡자리도넓직하고 사장님도 친절해요>< 스콘완존 버터풍미가득이에요 ㅎㅎㅎ땅콩크림커피도 꼬소함 낭낭 취향저격입니다!!', 45, 8, 'GOOD', SYSTIMESTAMP);
