INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '합정에서 맛있는 디저트로 추천하는 미니멀비! 가게식구들도 케이크가 예쁘고 맛있다고 늘 칭찬하는 곳이라 올해 크리스마스 케이크도 미니멀에서 예약했어요😍 받자마자 기분 좋아지는 패키지에서부터 귀여운 루돌푸 장식까지~사장님들 쎈쓰 여전하셔용😍 👍👍덕분에 올해도 즐거운 크리스마였습니당😍', 47, 5, NULL, SYSTIMESTAMP);
