INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '친구 생일 축하하려고 샀는데 타르트가 너무 예뻐요.. 요구사항도 잘 반영해주셔서 좋았어요 저는 못 먹어봤지만 친구가 진짜 너무 맛있대요 감사합니다~!', 1, 1, NULL, SYSTIMESTAMP);
