INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '생딸기타르트랑 얼그레이하이볼이 이르케나 잘 어울리는 줄 처음 깨달은 날 ㅋㅋ~~~👏👏👍👍🥰🥰 크림 밀크티의 감미로운 홍차향 만끽~~아지트 감성 합정카페 댕기왔으요~~~', 5, 10, 'GOOD', SYSTIMESTAMP);
