INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '매장 분위기가 넘 좋아요ㅎㅎ 딸기치즈 타르트 먹었는데 위에 올라간 딸기가 지인짜 맛있었어요ㅠㅠ 비주얼도 넘 예뻐서 사진 오백장 찍었고요.. 사장님도 친절하셔서 편안하게 이용하다 갑니다🫶✨✨ 날이 추워서 티만 시켰는데 다음엔 커피 마셔보러 올게욧ㅎㅎㅎ', 7, 4, 'GOOD', SYSTIMESTAMP);
