INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '생일 케이크라고 하니 저렇게 예쁘게 리본도 묶어주시고 안내도 친절히 해주시고 !! 정말 기분 좋은 모임 되게 해주셔서 좋았어요👍', 46, 0, NULL, SYSTIMESTAMP);
