INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '친구 생일 케이크로 사갔는데 비주얼이 너무너무 예뻐서 친구 보자마자 감동 받았습니다. 엄청 뿌듯했고요! 맛은.. 제가 먹어보진 못 했지만 친구가 집 가서 먹어 보고 너무 맛있어서 헐랭방구래요ㅠㅠ 추천추천입니둥❤️‍🔥', 51, 13, NULL, SYSTIMESTAMP);
