INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '어버이날이라서 케이크로 느끼하지 않고 좋아하실만한걸 찾는 중 호박치즈케이크를 보게되었는데 이게 딱이다 싶었어요. 픽업하러 가는 길 역에서는 조금 멀어서 걸어야하지만 주변 가게들도 이뻣고 구경하는 재미가 있었어요. 케이크는 정말 귀여웠고 맛이 진짜 맛있어서 갠적으로는 생신때에도 또 하고싶단 생각이 들었고요, 저는 물론이고 부모님도 정말 좋아하셨습니다. 정말 취향의 케이크였습니다. 후회 없어요!', 45, 8, 'GOOD', SYSTIMESTAMP);
