INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '오늘 가족생일로 딸기타르트를 위해 방문했습니다! 미리 예약하고 방문했고 현장에서 추가로 단호박과 바스크치즈 조각도 구입했어요! 무엇보다 사장님께서 너무 친절하시고 카페 조용하고 아늑합니다! 또 방문할게요', 34, 10, 'GOOD', SYSTIMESTAMP);
