INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '잠깐 책읽으려고 들렀던 카페 ! 추운날씨라 따뜻한 음료 주문했는데 녹아요..🩵 디저트 맛집인 거 같은데 귀여운 디자인의 스콘도 있고 맛도 너무 좋아요ㅠㅡㅠ 🤍혼자 작업하러 오기도 좋고 소소한 대화 나누러오기도 좋은 거 같습니당 ㅎㅎ', 10, 3, 'GOOD', SYSTIMESTAMP);
