INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '사장님 너무 친절하시고 리뷰 서비스 스콘까지 챙겨주셔서 감사합니다💗 덕분에 친구 생일 축하 잘 했어요 ㅎㅎ 센스있게 hbd리본으로 포장해주셔서 감사해요!!', 34, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '사장님~ 너무 친절하시고 케이크도 맛있고 샤인머스켓도 싱싱해서 좋았습니다! 레터링 케이크 말고 다른 케이크 없나 찾아보다가 예약한건데 잘 한것 같아요! 서비스로 주신 스콘도 맛있게 먹겠습니다~ 생일 당사자도 좋아했어요!', 100, 26, 'GOOD', SYSTIMESTAMP);
