INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '친구 생일 케이크 찾다가 단호박홀치즈케이크가 너무 맛있어보여서 예약 후 픽업 했어요~ 생일케이크인지 물어봐주시고 예쁘게 포장까지 해주셔서 감사했습니다!', 30, 8, 'GOOD', SYSTIMESTAMP);
