INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '인테리어도 너무 예쁘고 디저트타임 제대로 즐겼어요💖 특히 저 딸기치즈타르트가 진짜 맛있더라구요,, 너무 제 취향이었어요! 딸기 시즌 끝나기 전에 딸기라떼랑 또 먹으러 가고 싶어요 ㅎㅎ 시그니처 아인슈페너도 크림 쫀쫀하니 최고🥰👍', 104, 26, 'GOOD', SYSTIMESTAMP);
