INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '친구 생일케이크로 준비했는데 친구가 너무 예쁘고 맛있다고 좋아했어요! 합정 근처 예쁜 케이크 알아보다가 우연히 발견하게 됐는데 정말 잘 찾은 것 같아요ㅎㅎ 다음에 또 방문하려구요😍 제가 먹어 본 타르트 중 젤 최고예요♥️♥️♥️', 18, 9, 'GOOD', SYSTIMESTAMP);
