INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '아이 생일케이크로 주문했어요 당일 주문 후 방문했는데 이런 타르트 맛집을 만나다니 ♡ 아이들이 다 먹어서 다음엔 어른 생일케이크로도 주문할께요', 10, 5, 'GOOD', SYSTIMESTAMP);
