INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '단호박 치즈케이크 너무 맛있어요!! 구황작물계 무화과 같은 느낌 ㅎ 너무 달지않아서 좋고 혈당 오르는 느낌 없이 먹을 수 있어서 좋았어요 추천드려요 디카페인 콜드브루도 맛이 깔끔해서 원두 여쭤봤는데 콜롬비아꺼라고 하시네요! 너무 잘쉬다 갑니다 ㅎㅎ', 28, 10, 'GOOD', SYSTIMESTAMP);
