INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '과일타르트가 먹고 싶어서 방문했는데 아쉽게도 품절돼서 스콘을 먹었는데..! 스콘이 아주아주 바삭ㄱ바삭해서 쿠키같아요!!!! 스콘 안좋아하는데 진짜 맛있어요 👍👍 담에는 스콘과 과일홀타르트를 포장해서 갈래요 ~~!!!🤭', 20, 6, 'GOOD', SYSTIMESTAMP);
