INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '친구 생일 기념으로 예약했어요! 생각했던 거보다 기대 이상으로 이쁘게 해주셔서 감사했습니다🩷 특히 생일이라고 생일 리본 달아주셔서 사장님 세심함에 또 방문하고 싶어요☺️', 27, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '어제 예랑 생일인데 일이 많아 급하게 알아보고 예약해두고 구매하러 갔는데도 너무도 친절하고 맛도 딱 좋아하는 진한 바스크 치즈 케이크여서 행복했어요😊 사진 찍으러 갈 때 소품으로도 너무 잘 나오더라구요😊 둘이서 먹기 너무도 좋은 크기와 가격이어서 다음에도 기념일에 구매하러 가려구요😍', 7, 0, 'GOOD', SYSTIMESTAMP);
