INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '친구 생일 케이크로 제격,,! 보기에도 예쁜데 맛이 미쳤더라고요..? 사실 생일파티 장소와 가까워서 예약한건데 맛이.. 미쳤어요 내돈내산 후기니까 절 믿고 딸기치케 사보세요.. 진짜 사장님 솜씨 미쳤으니까,,🍰🌟', 30, 9, 'GOOD', SYSTIMESTAMP);
