INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '리본끈부터 디테일 하나하나 너무 감사합니다! 좋은 선물이 되었어요 주변에서 다들 어디냐고 물어보네요⌯’ㅅ’⌯ 다음에 또 방문하겠습니다♥', 90, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '친구 생일이라 딸기치즈 홀타르트 케이크 예약했어요! 사장님께서 생일용이냐고 여쭤보시고 생일문구 적힌 예쁜 레터링리본으로 묶어주셨어요🤭 감사합니당! 친구가 너무 좋아했어요 다음에도 또 이용하겠습니다😊', 25, 7, 'GOOD', SYSTIMESTAMP);
