INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '딸기타르트진짜너무너무너무너무너무너무너무 맛있어요 . . . 웬ㅁ만한 딸기케이크보다 훨 나아요 . . 친구들이랑 한번먹고 반해서 가족모임에서도 케이크대신 또먹고 . . 다음 딸기타르트모임약속도  잡았답니다 . . 진짜맛있어요 평생 장사해주세요 . . 제 이빨이 다 빠져서 딸치타를 못멋는 그날까지 팔아주세요. . 감사합니다 감사합니다', 3, 10, 'GOOD', SYSTIMESTAMP);
