INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '꺅 넘친절하시구 케이크도 맛있어여ㅎㅎ 포장하고 보관법도 문자로 주셔서 넘 좋아요..🫶🏻 글구 예쁜데 진짜 맛도리라 다음 기념일에도 또 방문 계획 있습니당~~~!! 가격두 넘조아요!!', 39, 10, 'GOOD', SYSTIMESTAMP);
