INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '딸기타르트가 너무 맛있었어요! 꾸덕하고 딸기와 시트의 조화가 100점이었습니당.. 그리고 아메리카노는 산미 없고 적당히 고소해서 좋았습니다!', 28, 7, 'GOOD', SYSTIMESTAMP);
