INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '헉 체리 타르트 너무 맛있어요.. 타르트가 눅눅하지도 않고 그렇다고 딱딱하지도 않고 최고입니다! 다른 디저트도 다 먹어보고 싶어요!', 8, 2, 'GOOD', SYSTIMESTAMP);
