INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '집 근처에 있는 디저트가 맛있는 카페에요. 합정역 성산중학교쪽에 있는데, 케이크, 타르트부터 스콘까지 다양하게 있어요. 샤인머스켓이 올라간 타르트를 주문했는데, 너무 맛있었어요. 커피는 시그리처 B커피인데, 위에 크림이 굿! 자두 히비스커스는 색도 예쁘지만 맛이 새콤해서 비타민 음료를 마시는 것 같았어요. 이날의 최고 발견!', 26, 4, 'GOOD', SYSTIMESTAMP);
