INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '남자 친구 생일 케이크다!☺️🎂🍓🍓🍓 서울에는 맛있는 케이크를 판매하는 곳이 많지만, 진짜 맛있고 과하지 않게 달콤한 케이크를 찾는 건 쉽지 않더라구요..ㅠㅠ 🤨🧐 미니멀비에서 주문한 딸기 치즈케이크🍰🍓🍓🍓 정말 특별했습니다! ✨🫶🏻 제 남자친구는 보통 크림을 좋아하지 않지만😛, 이번 케이크를 먹고 생일에 받은 케이크 중 가장 맛있다고 했네요!!!🤩🥳 직원분들도 매우 친절하고 예의 바르셔서 카페 분위기 또한 좋았습니다. 정말 감사드립니다!!🥰☺️❤️✨🫶🏻🍰', 50, 7, 'GOOD', SYSTIMESTAMP);
