INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '친구 생일이라 케이크 예약했는데 비주얼 최고 👍 픽업 시간보다 빠르게 방문했는데도 사장님 센스 최고임다 ㅠㅠ 이쁘게 준비해주셔서 감사합니다~ 다음에 케이크 먹으러 또 방문하겠습니당 새해 복 많이 받으세요 😄😄', 119, 25, 'GOOD', SYSTIMESTAMP);
