INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '사진으로 봤을 때보다 실물로 보니 케이크가 더 예쁘고, 귀여워요! 사장님도 너무 친절하시고, 세심하셔서 너무 감사했습니다🥰 다음에 또 방문하겠습니다!', 0, 4, 'GOOD', SYSTIMESTAMP);
