INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '재방문이에요! 생일 케이크 대용으로 사전예약하고 청포도타르트 픽업했습니다. 포장도 너무너무 예쁘게 신경써서 해 주셔서 감동이에요 😍 비주얼 너무 예쁘지 않나요? 받는 분도 엄청 만족했어요!! 사장님이 초까지 신경써서 골라주셔서 감동...😳 너무너무 맛있어요 특히 치즈가 너무 달지 않고 담백해서 과일이랑 너무 잘 어울려요 :) 담번엔 딸기 홀타르트로 예약해서 재재방문하러 올거에요. 미니멀비 유명해졌으면 좋겠다...아냐 유명해지지마...ㅠ 아니야 번창하셔야...ㅜㅜㅜㅜㅜ', 94, 19, 'GOOD', SYSTIMESTAMP);
