INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '진짜 타르트 너무 사랑스럽고 맛있어요!!!! 제 친구들은 타르트 별로 안좋아하는데 진짜 먹어본것중에 제일 맛있다면서 행복하게 먹었습니다!! 다음에는 2호 사이즈로 주문해야겠어요 ㅎㅎㅎ 사장님 오래오래 번창하시고 계속 맛있는 타르트 팔아주세요!!!ㅎㅎㅎ', 30, 6, 'GOOD', SYSTIMESTAMP);
