INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '사장님~~ 드뎌 리뷰 남깁니다,,,😭 예쁘고 맛있게 만들어주신 덕분에 가족들끼리 행복한 연말 파티했어요!!!! 감사합니다 ❤️‍🔥🎉 여러분, 여기 타르트 진짜 넘넘 맛있어요ㅠㅠㅠㅠ 선물하기에도 참 좋은 타르트 맛집입니당,,🍓🎂 (미니스콘도 감사해요 사장님,,🥺🙏🏻)', 64, 12, 'GOOD', SYSTIMESTAMP);
