INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '가족들과 넘 맛있게 먹었어요🙈🍓❤️ 다들 이렇게 맛있는 타르트는 첨 먹어본다며 순삭했습니다! 직원분들도 넘 친절하시구 매장 분위기도 넘 좋아서 담엔 매장 방문으로 이용하구싶군요!!', 48, 8, 'GOOD', SYSTIMESTAMP);
