INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '친구가 치즈케익을 좋아해서 미리생일축하 겸 가족이랑 먹으라도 선물했는데, 진짜 맛있게 잘먹었대요ㅋㅋㅋㅋ 친구 부모님께서도 단걸 싫어하시는데 이 케익은 안남기고 잘 드셔서 아주 뿌듯했다구하네용ㅋㅋㅋ 예쁘고 맛있게 만들어주셔서 감사합니다🫶', 10, 10, 'GOOD', SYSTIMESTAMP);
