INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '친구 생일이라 미리 예약하고 픽업했는데! 너무 맛있었어요! 레터링 케이크보다 보기에도 더 이쁜 것 같아용~ 크기는 작지만 후식으로 3명이서 먹고도 남았습니다! 다음에도 또 이용 하겠습니당! 감사합니다~~ 사장님도 친절 하셨어요!! 🥹🥰', 99, 20, 'GOOD', SYSTIMESTAMP);
