INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '친구 생일이라서 미리 예약하고갔습니다! 샤인머스캣 타르트 예약했는데, 비주얼이 미쳤습미다...💘 데코도 예쁘게 잘 되어있어서 받는사람이 행복해할거같아요. 후기 보고 간거였는데, 대만족합니다ㅠㅠ! 늦은 시간인데도 사장님께서 친절하게 응대해주셔서 따수운 저녁이 될 거 같네요! 잘 먹겠습니다 :>', 48, 2, 'GOOD', SYSTIMESTAMP);
