INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '남친이 이렇게 맛있는 케이크 첨이래요... 치즈케이크를 너무 좋아해서 생일에 이 케이크 사준거였는데 한입먹자마자 눈이 땡그래지는 맛이엇어요.. 대박!!!', 37, 0, 'GOOD', SYSTIMESTAMP);
