INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '밥 먹고 왔는데 디저트 맛있어서 허겁지겁 먹었어요ㅋㅋ 과일치즈타르트 꾸덕하고 딸기 엄청 큰거 올라가요!! 미니멀비..커피도 맛있지만 디저트맛집이니까 꼭 디저트도 드시길..🍰', 25, 9, 'GOOD', SYSTIMESTAMP);
