INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '칭구케이크로 주문했는데 크기도 아담하고 포장도 이쁘게해주시고 케이크 1호에는 위에 크림?이 이쁘게 올라가서 괜찮은데 미니는 조금 허전해 보일 수 있어서 생일토퍼를해서 만들어갔는데 귀여움이 2배입니다🥴 맛도 맛있어용!!🎃🧡', 21, 0, 'GOOD', SYSTIMESTAMP);
