INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '디저트가 하나하나 너무 귀엽고 예뻐요! 스콘 밖에 못먹어봤지만 일단 스콘은 너무 맛있었어요!! 밀크티 향과 버터향이 진하게 나서 먹는 내내 행복했답니다. 재방문 의사 100% 꼭 재방문해서 디저트 다 먹어볼거에요.', 85, 13, 'GOOD', SYSTIMESTAMP);
