INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '생일케이크로 주문한건데 너무 예뻐요!!!기분 좋게 선물할게요☺️☺️ 지하철가다가 모르는 분이 케이크 너무 예쁘다고 물어보셨어요!!!!해피벌스데이끈으로 부탁드렸는데 이것도 너무 예뻤어요ㅎㅎ감사합니다', 0, 2, NULL, SYSTIMESTAMP);
