INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '합정역에서 걸어서 10분안쪽에 있구 골목쪽이지만 쉽게 찾을수있어서 너무좋았어요 가게는 들어오자마자 아늑하고 스탭분들도 너무친절히 반겨주셔서 더 좋았습니당 ㅎㅎ 예약했던 케이크는 뭐 말해뭐해...하핳 넘이뻐용 인스타사진그대로에용 정말 맘에들어용🤍 사장님 이쁘게만들어주셔서 감사합니당!🙏', 6, 5, 'GOOD', SYSTIMESTAMP);
