INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '단호박케익 너무 너무 너무 귀엽고 맛있어요.. 🤍 완전 꾸덕한 단호박 맛.. 너무 달지 않고 단호박 케이크랑 크림 밸런스가 최고예요. 한 사람이 케익 하나 다 퍼먹기도 가능할 것 같아요 ㅠㅠ 덕분에 먹으면서 넘 행복했습니다.. 제가 예약일을 착각해서 하루 일찍 픽업했는데도 빠르게 만들어주셔서 너무 감사했어요!!!! 매장두 넓고 친구들이랑얘기하기 편한 분위기예요 ㅎㅎ 꼭 다시 방문하겠습니다 ~~ 홀케익은 미니멀비!!!', 0, 2, 'GOOD', SYSTIMESTAMP);
