INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '남자친구생일 기념으로 미니 치즈케이크 맞췄아용 단 거를 잘 안먹는 삼십대 아저씨라 걱정했는데 작년에 비싸게 레터링 해 준 케이크는 기억도 못하던데 이건 계속 생각날것같다고 싹싹 긁어 먹었숩니당 먹어본 케이크 중에 젤 맛있대여!! 저한테도 인생케이크였어요 달콤하구,,,촉촉하구,,, 💛', 75, 11, 'GOOD', SYSTIMESTAMP);
