INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '매장도 넘 귀엽고 디저트들이 아기자기해요~~ 단호박케이크 픽업했는데 보기에도 예쁘고 진짜 맛있었어요!! 다른 곳에서 한번도 못 본 메뉴라서 도전한 거였는데 너무 잘 선택한 거 같아요ㅎㅎㅎㅎ 스콘 받은것도 맛있어서 여긴 그냥 맛집인것입니다bb 다음엔 다른 메뉴도 먹어보고 싶어요!! 합정 디저트 맛집으로 추천😆', 2, 7, 'GOOD', SYSTIMESTAMP);
