INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '딸기도 너무 신선하고 맛있었어요 ㅠㅠ 남자친구 생일이어서 특별하게 주문했는데 최고의 선택이었습니다 주신 스콘도 맛있구여, 두번째 방문인데 다음에도 미니멀비 이용할게요ㅎㅎㅎ 케이크 잘 먹었습니다😍', 30, 2, 'GOOD', SYSTIMESTAMP);
