INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '딸기 달고 너무 맛있었어요!! 포장도 너무 예쁘게 되어있습니다. 선물 받은 사람도 정말 맛있다고 최고의 딸기타르트라고 했어요. 다음에도 또 사먹고 싶습니다. 생각보다 크기가 작아서 다음에 먹으면 제일 큰 사이즈로 주문하려고요!', 94, 19, 'GOOD', SYSTIMESTAMP);
