INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '생일인지 여쭤보시더니 너무 예쁜 생일끈으로 포장해주신 사장님 ♥ 당일날 케이크 픽업 시간도 바꿨는데 친절하게 응대해주시고 케이크도 맛있고 가격대비 맛이 너무 좋아서 담에 또 오겠습니다 ㅎෆ◟̊◞̊', 50, 6, 'GOOD', SYSTIMESTAMP);
