INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '딸기가 너무 맛있어보여서 예약했는데 타르트 정말 안 눅눅해지고 맛있었어요! 타르트는 눅눅해지면 맛이 없어지는데 바삭했어요 잘 먹었습니댱 !!', 43, 10, 'GOOD', SYSTIMESTAMP);
