INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '미니멀비는 친구들이랑 길 가다가 우연히 들어가서 알게 된 카페인데 그 때도 분위기가 너무 좋고, 스콘이 맛있고, 사장님이 너무 친절하셨던 좋은 기억이 있었어요!! 이번에 부모님 결혼기념일 케익하려고 알아보다가 또 우연히 발견하게 됐는데 그 좋은 기억의 미니멀비이길래 반가운 마음에 바로 예약했습니다!! 가족들이 화려하기만 하고 맛 없는 케이크보다 맛있는 케익 먹는 걸 훨씬 더 선호해서 사실 긴장 좀 했어요..ㅎ 케이크 비주얼이 너무 예뻐서 혹시나 하구.. 근데 한 입 먹고 다들 너무 맛있어서 기절할 뻔 했습니다🫢 단호박치즈케이크 그냥 미쳤어요 너무 맛있고, 전 원래 생크림도 못 먹는데 앉은 자리에서 싹쓸이 완ㅠㅠ 픽업 시간 변경했는데도 너무 친절하게 안내해주셨던 천사 사장님, 오래오래 케이크 해주세요🫶🏻🫶🏻', 27, 0, 'GOOD', SYSTIMESTAMP);
