INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '이집 디저트 찐맛집이네요 ㅠㅠ 귀엽게만 만드시는줄 알았는데 너무 맛있어요,,❤️ 여러분 단호박치즈케잌 꼭 드세여..!!! 커피는 흑임자크림커피 강추드립니다아🥹', 90, 12, 'GOOD', SYSTIMESTAMP);
