INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '진짜 인생 치즈케이크였어요 ㅜㅠ 넘 맛있어서 게속 생각나는 맛!! 다음 기념일에도 케이크는 여기서 먹으려고 합니다 ㅎㅎ 다음엔 큰 사이즈로 주문할게요! 잘 먹었습니당 ㅎㅎ', 7, 5, 'GOOD', SYSTIMESTAMP);
