INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '귀여운 디저트가 있는 미니멀비 합정 카페 !! 스콘부터 타르트까지 종류가 다양했는데 구움과자류 디저트가 맛있어요 ఇ 커피와 밀크티도 달달하고 꾸덕한 크림이 올라가 맛있게 잘먹었습니다 !! 조용하고 야외테이블도 있어서 분위기 즐기기 딱이에요! 잘먹고 갑니당 ~~', 79, 16, 'GOOD', SYSTIMESTAMP);
