INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '🏆디저트 맛집: 바스크 치즈케이크 추천. 속이 촉촉하고 크리미하며 진한 치즈 풍미가 느껴집니다. ☕️크림커피 크림의 밀도가 높고 연유같이 달콤하고 부드러운 풍미가 좋아요. 입에 들어가도 바로 흩어지지 않는 크림! 깔끔하고 감성적인 인테리어에 곳곳의 소품 구경하는 재미가 쏠쏠합니다. 디저트 보관 상태도 좋은 듯 했어요. 스콘이 바삭바삭 눅지지 않았고 케이크도 얼거나 녹지 않았습니다. 잘 다녀갑니다❤️', 5, 5, 'GOOD', SYSTIMESTAMP);
