INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '사장님 너무 친절하시구요 ㅠㅠ 케이크도 너무너무 맛있어요!! 친구 생일이라서 포장했는데 친구도 너무 만족했어요! 포장이랑 케이크 너무 예쁘고 초도 귀염뽀짝합니다! 앞으로 자주 방문할게요!❤️❤️', 6, 3, 'GOOD', SYSTIMESTAMP);
