INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '합정역 근처에 있는 타르트카페!! 살짝 골목 안쪽에 있는데 오히려 조용해서 좋았다 요즘 골목골목 멋진 카페들이 넘무 많아 너무 좋당... 타르트 종류는 체리타르트랑 청포도 타르트랑 복숭아 타르트??? 계절마다 달라지는둣 자두에이드 먹었는데 진짜 찐 자두맛... 시원하니 맛있었당... 딱 여름에 먹기 너무 좋았음 직원분들도 넘 친절!! 인테리어도 깔끔!! 강아지 동반 가능!! 안갈이유가 없음!!', 27, 3, 'GOOD', SYSTIMESTAMP);
