INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '급하게 주문했는데 친절히 도와주셔서 픽업했어요! 일단 맛있고 맛있고 맛있었어용...👍🏻 합정역에서 10분정도 걸었지만 그만큼 가치있었어요.조만간 또 올께요.', 35, 3, 'GOOD', SYSTIMESTAMP);
