INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '친구 생일이라 케이크 알아보던 중! 너무 맛있어 보이고 예뻐서 예약했는데 ㅜ 역시 너무 맛있고 예쁘고 친구도 엄청 좋아했어요‘!!!!ㅎㅎ 다음에 케이크 할 일 있으면 또 예약할게오 ㅎㅎ 사장님도 너무 친절하시고 최고입니당 ㅎ', 41, 10, 'GOOD', SYSTIMESTAMP);
