INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '샤인머스캣 정말 맛있어요!! 타르트는 로투스 쿠키지라 달콤하고 안에는 크림치즈가 가득 들어서 풍미가 깊고 맛있더라고요 💚 어른들도 케이크 맛있다고 하시고 다들 케이크 너무 맛있는 거 잘 사왔다고 하셔서 제가 다 기분이 좋았어요! 앞으로 기념일 케이크는 미니멀비에서 항상 주문하려고요.', 0, 5, 'GOOD', SYSTIMESTAMP);
