INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '아빠 생일케이크로 사다드렸는데 너무너무너무 맛있고 구황작물 안좋아하는 저도 너무너무너무 맛있게 먹었어요! 부모님도 좋아하시네용ㅎㅎ 샤인머스켓 타르트도 완전 추천드려요!! 서비스로 주신 스콘도 왕왕 맛있습니당👍', 115, 21, 'GOOD', SYSTIMESTAMP);
