INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '포장도 너무 예쁘고… 그냥 너무 맛잇습니다. 샤머도 맛있고 크림치즈랑 타르트지도 너무 맛너용 캐이크가 너무 물려서 생일케이크 대신으로 찾았는대 너무 좋은 선택이엇어용. 마니사이즈 둘이 후식으로 먹기 어주 충분해용 사장님도 너무 친절하새요!', 28, 8, 'GOOD', SYSTIMESTAMP);
