INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '샤인머스켓 치즈타르트 두번드세요‼️ 진짜 넘 맛있어요. 조만간 홀케이크로 주문하러갑니다. 디저트 맛있으면 보통 음료는 그냥저냥인데 미니멀비는 음료도 맛있음💗', 49, 3, 'GOOD', SYSTIMESTAMP);
