INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '친구가 워낙 케이크를 많이 받아서 일부러 타르트로 해주려고 연희동에서 예약하고 찾으러 갔는데… 비닐이 재활용처럼 쭈글거리고 사진과 다르게 빨간 하트칩도 없더라구요… 좀 아쉽네요', 10, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '미니 치즈케이크 포장했는데 너무 맛나요!ㅎㅎ 포장도 예쁘게 해주시고 성냥이랑 이것저것 많이 챙겨주셔서 좋았습니다~^^ 사장님도 넘 친절하세요! 또 가면 단호박 치케 먹어보고 싶어요 ㅎㅎ', 52, 17, 'GOOD', SYSTIMESTAMP);
