INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '예약 할때 체리, 청포도 중에 고민했는데 반반도 가능하다고 하셔서 반반으로 했어요 ㅎ.ㅎ 과일이 위아래로 반반 들어가면 더 예쁠 것 같다고 제안해 주셔서 그렇게 했는데 넘 예쁘고 만족스러워요❤️💚 두가지 맛 다 볼 수 있어서 좋았고, 제가 디저트에 매우 진심인 사람인데 레전드로 맛있습니다. 그냥 주문하세요 다들. 엄마 생신 케이크였는데 가족들도 다 너무 맛있게 잘 먹었습니다~~~ 담에 또 주문할꼬에요 번창하세요 사장님🥳', 17, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '홀케이크 주문 후 픽업했습니다! 치즈케이크 평소에 너무 좋아하는데 여기 너무 맛있어서 정말 추천드려요!! 다들 추천하던데 추천하는 이유가 있었어요!!! 사장 님 너무 친절하시고 가게 분위기도 너무 좋습니다!! 다들 치즈케이크 드시러 오세요!!!', 0, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '미니멀비 매장에서 베이커리류를 전부 직접 만들어서 매장에 들어오자마자 빵냄새가 가득했어요 빵 나오는 시간이였나봐요 ㅋㅋㅋㅋ 환풍이 잘되어있어서 냄새가 금방빠지는게 아쉬울정도였네요 아메시스트 리치는 이쁜 자수정빛깔의 리치에이드였는데 나타드 코코가 들어가있어서 씹는맛이 좋은 많이 달지 않은 에이드였어요 b크림커피는 미니멀비 대표 크림커피예요 아래쪽커피는 라떼에 크림이 올라갔는데 원두가 완전 제 취향 체리타르트도 베이직한 타르트라서 좋았어요 추천드려요👍', 2, 7, 'GOOD', SYSTIMESTAMP);
