INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '공간이 너무 아늑해서 좋아요! 너무 친절하시고 디저트 종류가 많아서 좋은것 같아요! 음료 종류도 많고 과일타르트도 샤인머스켓도 있고 딸기도 있어요! 겨울이라 딸기 디저트가 먹고 싶었는데 딱 좋은것 같아요!!', 48, 4, 'GOOD', SYSTIMESTAMP);
