INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '친구 생일케이크로 이용했습니다! 요즘같은 고물가 시대에 합리적인 가격으로 예쁜 케이크를 겥 해서 좋았습니다 ㅎㅎ 사장님이 예쁘세용 홍홍💓', 83, 18, 'GOOD', SYSTIMESTAMP);
