INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '근처에 스콘 파는 카페가 없어서 찾아서 가본 곳인데 기대이상으로 정말 맛있게 먹었습니다 카페 분위기도 너무 시끄럽지않아서 좋았어요! 커피랑 스콘 너무 괜찮아서 혼자와서 재주문 하며 먹었습니다… 추천해오…', 35, 8, 'GOOD', SYSTIMESTAMP);
