INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '단호박 치즈케이크를 주문했는데 한 입 먹고 너무 놀랐어요🫢 지금까지 먹었던 단호박 케이크는 너무 크리미하고, 느끼했었는데요! 미니멀비에서는 단호박 맛도 진하면서 달달고소했어요❤️ 저는 요고 먹으러 미니멀비 재방문 예정🏃 카페라떼는 고소했고, 산미 없는 원두맛을 좋아하는 저에게 딱이었어요!! 망고 아이스티는 진한 아이스티에 망고가 엄청 많이 들어있었어요! 아이스티 자체가 너무 달지도 않고 맛있더라구요!', 58, 18, 'GOOD', SYSTIMESTAMP);
