INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '선물하기에는 이만한게 없어요 또한 사장님도 친절하십니다. 근데  뭔가 뭔가 올라온 이미지랑 비교하면 뭔가  좀 하위같다해야하나... 맛이나 퀄리티, 크기가 가격 생각하면.... 글쎄요.... 딸기가 많은것도 아니고.....아 모르겠습니다 솔직히 개인적으로는 실망스럽긴했는데 그래도 이 근방에서는 선물 홀타르트 필요하시면 강추드립니다', 40, 10, NULL, SYSTIMESTAMP);
