INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '남자친구 생일케이크로 타르트 케이크 2호 주문했는데 너무 맘에들어요 예쁘고 귀엽고ㅠㅠㅠ 서비스로 스콘도 주셨는데 넘 맛나요..💗 요새 케이크 짱 비싼데 이정도면 가성비도 좋은 것 같아요!! 사장님들도 엄청 친절하시구 또 주문할래요 😍😍👍🏻', 46, 4, 'GOOD', SYSTIMESTAMP);
