INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '케이크가 필요해서 전날 급하게 예약했는데 친절하게 응대 해주셨습니다! 케이크 크기와 종류도 다양했어요~ 케이크 역시 너무맛있었고 올라가는 과일이 신선해서 좋았습니다! 카페분위기도 너무좋고 다음에는 카페이용하러 방문할게요~ㅎㅎ 아! 사장님도 너무너무 친절했습니다~ㅎㅎ 번창하세요~', 23, 7, 'GOOD', SYSTIMESTAMP);
