INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '예쁘고 귀여운 디저트가 많고 커피가 맛있는 정말정말 진짜진짜 디저트 찐 맛집! 매장에서 직접 만드는 수제 디저트 다 ! 디저트 고르면서 기분이 좋아지는 힐링타임 이였다 !! 사장님이 예쁘신데 친절하시고 상냥하셔서 더욱더 기분이 좋아지는 카페 !! 또 가고 싶어지는 카페다 !! 디저트 진짜진짜 맛있음 😋 👍', 15, 3, 'GOOD', SYSTIMESTAMP);
