INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '친구 생일 케익으로 구매했어요! 케익을 별로 안좋아하는 친구라 작은걸로 구매했는데 한 입 먹고 다들 너무 맛있다고 칭찬 왕창 받았습니다👍🏻 다음에 또 구매할 것 같아요!! 사장님두 너무 친절하셨어요 최고입니당 ! 🥳💗', 41, 0, 'GOOD', SYSTIMESTAMP);
