INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '조용하고 아늑하고 분위기 좋아요!! 바스크치즈케이크 먹었는데 진짜 맛있었어요..👍 사장님도 친절하셔요 집만 가까웠으면 매일 왔을 듯.. 합정 최고의 카페임', 19, 10, 'GOOD', SYSTIMESTAMP);
