INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '남자친구 생일이어서 예약 후 픽업했어요 단호박 치즈케이크 1호 미니 주문했는데 너무 맛있어서 놀랐어요.. 올라가있는 타임까지 크림이랑 먹으니 향긋해서 밸런스도 최고고.. 치즈케이크도 너무 달지 않고 호박향 그득한 찐 꾸덕 케이크라 완전 만족했어요 남자친구가 디저트 맛없으면 절대 손 안대는 타입인데 정말정말 맛있다고 잘 먹더라구요 그리고 무엇보다 케이크 외관도 너무 이뻤어요.. 빈티지함의 끝판왕..다음엔 타르트류도 구매해보겠습니당 💗 이쁜 케이크 감사해요', 51, 13, 'GOOD', SYSTIMESTAMP);
