INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '합정 골목에 숨어있는 맛있는 디저트 카페! 특히 단호박 케익 꼭 드셔야되여 단호박이 이렇게 맛있는지 처음 알았네요🤩 아메리카노도 산미랑 고소함의 밸런스가 잘 맞춰진 원두여서 누구나 다 선호할 맛입니다! 크림 라떼도 달달하니 맛있었어용!! 예쁜 산호색 라떼도 추천드립니당! 저런 라떼는 보통 너무 단데, 여긴 진짜 프레쉬하더라구요! 콕콕 씹히는 나티드 코코때문에 식감도 재밌어요! 추천드립니당❤️', 19, 2, 'GOOD', SYSTIMESTAMP);
