INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '분위기 좋은 힙한 합정동의 카페 미니멀비, 디저트를 손수다 만드셔서 더 정감있고 맛있어요. 덜 단 음료(카페인프리로)랑 디저트도 추천해주시고 사장님께서 정말 친절하셔서 좋았던 곳입니다. 바스크치즈케이크 정말 진하고 홈베이킹좋아하는대 재료아끼지않고 만든 바스크치즈케이크맛이랑 비슷해서 정말 맛있게 어머니께서 드셨거든요! 데이트로 방문하기도 좋을 디저트카페라 강력히 추천하고싶습니다. #합정역카페 #합정동디저트카페 #합정케이크맛집 #합정케이크카페', 48, 0, 'GOOD', SYSTIMESTAMP);
