INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '친구 생일 케이크로 주문했는데 비주얼도 합격 맛도 합격이에요 친구들이 어디서 샀냐고 너무 맛있다고 했어요! 뿌듯뿌듯 많이 먹어도 안느끼해서 순삭했습니다 재구매 의사 있습니당', 36, 7, NULL, SYSTIMESTAMP);
