INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '거의 주기적으로 찾게되는 미니멀비❤️ 집이랑 가깝고 여유가 된다면 매일 가서 먹고 싶은데 그러지 못해서 항상 먹고 싶어 앓는 곳...🥺 맨날 타르트를 사가고 있지만 가끔 시간이 많으면 음료도 먹고 하는데 음료도 짱짱입니다👍✨️❤️ 사장님두 갈때마다 너무 친절하게 대응해주셔서 진짜 넘 조아용ㅜ 완젼 보석같은곳❤️❤️ 번창하셔서 2호점 3호점 집이랑 가까이 내주셨으면🥹❤️', 40, 2, 'GOOD', SYSTIMESTAMP);
