INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '합정 조용한 카페 찾아서 갔는데 너무 좋았어요! 분위기도 아늑하고 인테리어도 깔끔해서 친구랑 편하게 잘 있다 왔습니다 타르트도 맛있고 시그니처 커피 크림도 너무 맛있었어요!! 다음에 또 올게요 그때는 다른 타르트 먹으러 가겠습니다 ㅎㅎ', 130, 26, 'GOOD', SYSTIMESTAMP);
