INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '친구 생일 때 같이 먹을 귀여운 디저트 찾다 예약 없이 오픈 시간 맞춰서 바로 방문했는데, 일부 디저트들은 만드는 중이라고 해서 조금 기다렸습니다. 근데 사장님이 너무 친절하시고 디저트들도 귀엽고 예뻐서 만족스럽게 구매해서 갔어요 ~', 107, 24, 'GOOD', SYSTIMESTAMP);
