INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '아버지 생신으로 특별한 케잌. 찾다가 알게된 미니멀비! 단호박 홀케이크 미니 어른들 드시기 좋다는 리뷰에 딸기와 고민하다 주문했어요 호박과 크림치즈가 너무 잘어울리는 맛~ 배부르신대 계속 드시더라구요 ㅋㅋ 저도 만족 ! 담에 다른걸로 먹어봐야겠죠?^^ 이쁘게 맛있게 해주셔서 고맙습니다 사장님 너무 친절하세요~기부니가 좋았어요 번창하세요', 21, 4, 'GOOD', SYSTIMESTAMP);
