INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '아기자기하고 분위기도 너무 좋고 오다가다 맛있는 디저트 맛보기 너무 좋을 것 같습니다. 와이프가 좋아해서 포장하러 왔다가 리뷰 남겨보네요~ 색다르고 이색적이면서도 맛있는 스콘 맛보려면 꼭 방문 한번 해보시길 바래요!~^^', 31, 5, 'GOOD', SYSTIMESTAMP);
