INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '친한언니 서프라이즈 생일로 방문했는데 내부도 아늑하고 모임하기 좋았습니다 타르트도 맛있었고 과일도 신선했습니다🥰 합정오면 또 들릴예정입니다 사장님도 친절하셨고 몰래 서프라이즈 동참해주셔서 감사합니다! 타르트 좋아하시는 분들은 드시면 아주 좋아할 만큼 맛있었습니다', 1, 1, 'GOOD', SYSTIMESTAMP);
