INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '정말 힙하고 예쁜 공간이에요!! 음료도 맛있고 오트밀크로 변경했더니 정말 고소하고 맛나요 ㅎㅎㅎ 디저트 진짜 맛있네요! 다음엔 스콘도 먹어보고싶어요 ㅎㅎ', 39, 8, 'GOOD', SYSTIMESTAMP);
