INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '엄마 생신으로 예약했는데, 너무너무 맛있게 잘 먹었어요!! 사진도 예쁘게 나오는 건 덤...🤍🍒 크림치즈일까요...? 저 크림이 정말 세상 맛있습니당 인위적인 단맛이 아니라서 더 좋아요🤭', 31, 6, 'GOOD', SYSTIMESTAMP);
