INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '이전에도 친구 생일파티로 홀타르트 주문해서 생일케이크 했었는데 너무 맛있게 먹고 사이즈도 적당한 가성비 집이라 또 찾았어요 종종 음료 먹으러도 방문 하는데 음악선정도 좋고 자리도 편해서 너무 좋아요💜', 37, 3, 'GOOD', SYSTIMESTAMP);
