INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '반려동물과 함께 놀러왔는데 편안하게 다녀왔어요! 야외에도 테이블이 있어서 좋았고 애견용 물식기도 마련되어있어서 좋았습니다 ㅎㅎ 그리고 커피랑 스콘맛집입니당!', 9, 3, 'GOOD', SYSTIMESTAMP);
