INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '디카페인콜드브루와 바스크 치즈 케이크의 환상 조합! 최고입니다- ㅠㅠ 너무 너무 맛있어요.👍🏻🩷 다른 디저트들도 먹어 보고싶어요- 🙏😊 재방문 의사 1000%!!!! 입니다!', 31, 2, 'GOOD', SYSTIMESTAMP);
