INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '크리스마스때 홈파티 케이크로 처음 먹었었는데 그 이후로 계속 찾고 있는 집입니다ㅠㅜ 이제야 리뷰를 쓰는게 죄송하네욧😢 사진으로는 홀타르트를 올렸지만 홀타르트는 예약제라 홀타르트 말고도 조각으로 파는게 있어서 부담없이 가서 먹을 수 있어요🩷 홍대나 합정쪽은 멀어서 자주는 못 가지만 가면 꼭 생각나고 먹고 싶어서 꼭 하나는 먹고 가고 하나는 포장해서 가게 되는 곳이랍니다😋🩷 사장님도 너무너무 친절하시구 좋으셔서 더 찾게 되는 것 같아요!😍 홀타르트는 너무 예뻐서 기념일 같이 특별한 날 먹으면 너무 좋고 조각은 땡길때 마다 먹으면 좋을 맛입니다🥰 매장도 이쁘구 넓어서 좋아요🫶🏻 집 근처였으면 매일 갔을텐데 너무 아쉬워용ㅜ 사장님 조만간 또 사먹으러 가겠습니다😘🫶🏻', 0, 4, 'GOOD', SYSTIMESTAMP);
