INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '가족들이랑 점심 후 디저트가 땡겨서 방문했어요! 가게 앞에 1대 주차 가능해서 이용했고 내부도 깔끔하고 자리 사이 간격도 좁지 않아서 좋았어요:) 딸기치즈타르트랑 초코칩스콘 구매했는데 딸기치즈타르트 다들 맛있어했어요!! 스콘도 괜찮았구 커피맛도 괜찮고 좋았습니당!! 사장님이 친절하셔서 기분좋게 이용하다갑니다~!', 39, 4, 'GOOD', SYSTIMESTAMP);
