INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '늘 기분 좋은 방문의 미니멀비! 타르트 케익은 그닥 선호하지 않음에도 미니멀비 케익은 역시 달라요👍 타르트시트가 너무 촉촉하고 부드럽습니당😍 딸기 자체도 너무 맛있어서 요 한판! 아쥬 무리없이 혼자 다 먹을수 있겠더라구요😍💜 포장도 너어무 이뻐서 저는 선물용으로 드렸는데 이뿌구 맛있다며 칭찬일색!!', 20, 3, 'GOOD', SYSTIMESTAMP);
