INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '중딩딸 생일이라 특별히 주문했어요~케이크 이뿌고 귀엽고 맛있고 다 했어요~딸이 넘 좋아했어요~대부분 타르트는 크림은 맛있어도 밑에 과자부분이 별로인 집이 많은데,여기는 !!크림에 과자도 너무너무 맛있어요🩷아 그리고 사장님 직원분들 모두 너무 이쁘시고 친절하셨어요 최고최고👍🏻 하나 슬픈건..ㅜ가격이 ..ㅜ요즘 케이크 다 이정도라ㅜㅡㅜ 케이크 사랑하는 사람으로써 물가가 슬픕니다.', 50, 6, 'GOOD', SYSTIMESTAMP);
