INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '중요한 일정 때문에 케이크를 주문 포장을 했는데 케이크도 너무 예쁘지만 일단 진짜 맛있어요...미친 케이크에요🥹같이 케이크 먹은 분들이 미니멀비 이름 다 알려달라고 하더라구요!! 이쁘고 맛있는케이크 원한다면 완전 추천이요👍👍👍 그리고 여자 사장님 2분 계셨는데  너무 이쁘고 친절하세요ㅎㅎ', 25, 7, 'GOOD', SYSTIMESTAMP);
