INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '조각타르트 먹구 넘 맛있어서 홀타르트로 한 번 예약해서 구매해보았어요. 생각했던 크기보다 작아서 다음번엔 더 큰 거로 주문 해 보려구요! 다음 딸기 시즌은 언제인가요?!', 65, 16, 'GOOD', SYSTIMESTAMP);
