INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '아이들과 날씨좋아 나왔다가 발견한 카페인데 너무 마음에 들어요😍 아이들은 플럼에이드와 케이크 시켰어요. 좌석도 넓고 음악도 좋아요:)', 17, 6, 'GOOD', SYSTIMESTAMP);
