INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '소중한 친구의 생일이라 여러 곳 찾아보다 정한 곳이었는데 가격도 다른 곳에 비해 착하고 포장도 추가금 없이 예쁘게 해주시는 것 같아서 예약했는데 너무 친절하셨고 생크림과 크림치즈가 둘 다 같이 있어서 케이크 같기도 하고 타르트 같기도 하고 너무 맛있었어요! 비주얼도 맛도 최고였습니다 ㅎㅎ 다음에 또 예약할 것 같네요', 114, 20, 'GOOD', SYSTIMESTAMP);
