INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '홍대 근처에 살지만 딸기치즈타르트 케익 먹으러 매번 합정까지 오게 되는 맛집 카페입니다🥹 케익은 물론 음료, 분위기도 너무 좋아서 재방문의 발길이 끊이지 않는 곳이네요 :) 기념일마다 오게 되고 올 때마다 행복지수가 올라가는 느낌이에요!! 다음에도 물 흐르듯 다시 올 것 같네요😁', 37, 7, 'GOOD', SYSTIMESTAMP);
