INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '처음 구매해 보는 곳인데도 불구하고 제가 좋아하는 타르트의 맛과 조합인 거 같아요..친구 생일날이라 주문했지만 제가 더 좋아하는 거 같아요 😅😍', 88, 13, 'GOOD', SYSTIMESTAMP);
