INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '주문톡으로도 너무 친절하셨는데 매장방문때도 너무 친절하셨던 사장님~😊 리뷰에 맛도 맛이지만 포장이 너무 예뻐서 주문하게됐는데 받자마자 너무 예뻐서 바로 촬영을 안 할수가 없었어요^^ 서비스로 주신 스콘도 넘넘 맛있게 잘 먹겠습니닷!!💓', 11, 8, 'GOOD', SYSTIMESTAMP);
