INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '단호박치즈케잌 예약하고 카페가서 스콘도 추가 구매했는데 둘 다 대박 맛있었어요..!! 케이크 잘 사왔다고 친구들한테 칭찬받고 ㅎㅎㅎ 스콘은 기본에 충실한 고소하고 너무 맛있는 맛 ㅠㅠ 다음에 또 꼭 사먹을거에요!!!', 31, 4, 'GOOD', SYSTIMESTAMP);
