INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '맛있어요 두번째방문합니다 특히 글루텐프리 버터없이 치즈케이크파는데 일반치즈케이크보다 부드러워요 디저트맛있고 조용한곳찾으시면 추천합니다', 49, 10, 'GOOD', SYSTIMESTAMP);
