INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '분위기도 좋고, 음악도 좋고, 음료도 디저트도 모두 맛있는 카페 ! 스콘 존맛탱..🫢 당인리에서 바로라 오기 좋을듯 👍🏻 잘 먹고 갑니다 😀', 16, 0, 'GOOD', SYSTIMESTAMP);
