INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '늘 기분좋은 방문의 미니멀비💜 😍👍 투명케이스도 너무 예뻐요. 모형이 아닐까싶을 정도로 이쁜 케익 비주얼도 놀라운데 한 입 맛보고나면 아낌없이 그득하게 들어간 부드러운 단호박과 치즈케익 맛에 한번더 놀라고 그저 반하게 됩니다.😍 덕분에 행복한 연말이었어요😝 친절하신 사장님들 올 한해도 대박나셔요😘', 33, 1, 'GOOD', SYSTIMESTAMP);
