INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '케이크 후기가 좋아서 예약했어요!! 그런데 사장님도 매우 친절하시고 카페 내부도 넓더라구요 덕분에 예약시간보다 1시간 먼저 왔는데도 쾌적하게 기다릴 수 있었습니다! 케이크 구매가 아니라 카페 오는 걸로도 추천드려요', 52, 11, 'GOOD', SYSTIMESTAMP);
