INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '라떼 잘 안 먹는데 여기 라떼 정말 고소하고 맛있어요!!ㅎㅎ 테이크아웃 하면 천 원 할인도 해주셔서 합리적인 가격으로 맛난 커피 한 잔 가능하답니당 ㅎ 오늘도 커피 먹고 힘난 오후 보낼게요 ㅎ', 8, 3, 'GOOD', SYSTIMESTAMP);
