INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '매장분위기도 예쁘고 멋스러운데 디저트도 대박!! 모임이 있어 네이버로 예약하고 픽업해갔는데 케익 포장도 너무 예뻐요ㅠㅠ 케익도 너무 부드럽고 맛있어서 한 판 혼자 다 먹을각! 덕분에 맛있고 즐겁게 잘 먹었습니다!', 47, 2, 'GOOD', SYSTIMESTAMP);
