INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '너무 맛있어보여서 포장하러 들렀어요! 딸기 치즈 타르트랑 단호박 치즈 케이크 포장했는데 너무 맛있을것 같아요🙈 다음에는 레몬 판나타르트도 먹으러 오려고요ㅎㅎ 분위기도 너무 좋고 데이트 장소로 강추👍🏻', 9, 6, 'GOOD', SYSTIMESTAMP);
