INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '친구 생일에 케이크 대신 맛있는 디저트 선물하고 싶어서 타르트로 결정했어요!! 당일에 급하게 연락 드렸었는데도 사장님이 엄청 친절하시구 타르트도 엄청 맛있어요 🤤❤️ 다음에는 친구랑 놀러 갈게요오👍🏻', 3, 8, 'GOOD', SYSTIMESTAMP);
