INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '오늘도 커피마시러 미니멀비로 직진 했습니다. 하루의 시작은 미니멀비와 함께 화요일도 미니멀비와 함께 이료일도 미니멀비와 함께 화이 팅!', 26, 4, 'GOOD', SYSTIMESTAMP);
