INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '단호박홀케이크 예약후 픽업했어요 울엄마 말씀에 따르면 소름돋게 맛있다구 ㅎ 어디서 샀냐고 물어보시더라구요 사이즈도 적당하고 맛도 특별하고 넘 맛있었어요', 19, 10, 'GOOD', SYSTIMESTAMP);
