INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '친구 생일이라 케이크 찾던 중에 너무 맛있게 생겨서 바로 예약했습니다! 직접 받아보니까 더 예쁘고 포장도 잘 해주셨네요 제껀 아니지만 맛있을거 같아서 기대 되네요 ㅠㅠ 리본 포장이랑 투명 박스 포장이 너무 예뻐서 기념일에도 방문할거 같아요 사장님 친절하게 응대해주셔서 정말 감사합니다🤍', 3, 5, 'GOOD', SYSTIMESTAMP);
