INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '사진을 못찍어서 너무 죄송해오ㅠㅠㅠ 엄마 생신이셔서 홀케이크로 예약했는데 부모님이 너무 좋아하셨어요! 너무 달거나 자극적이지 않고 그날 먹은 샴페인과도 완전 딱이었습니다!! 맛있게 잘 먹었습니다!!🩷🩷🩷', 38, 8, 'GOOD', SYSTIMESTAMP);
