INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '친구 생일 케이크 때문에 검색해서 우연히 알게된 집인데 타르트가 매우매우 맛있어서 친구가 엄청 행복해했어요 딸기 1호 주문했고 31,000원 선결제 했구요 합정역에서 도보 7-8분 정도? 안에 강아지들이 있더라구요 애견동반 가능 카페인거 같습니다 타르트 안에 크림치즈 같이 치즈타르트 맛이났는데 파이 끝부분도 맛있었고 ㅠㅠ 다음에 또 먹고싶은 맛이에요 같이 먹은 친구들한테 칭찬 많이 받았습니다~~ 또 들를게요!!', 67, 12, 'GOOD', SYSTIMESTAMP);
