INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '생일때 친구들이 예약해줘서 먹엇는데 너무 맛잇어서ㅜㅜ 엄마 생일때 다시 예약하러 왓어요!! 매장두 크고 분위기도 좋아서 담에 커피마시러도 올예정입니다 ㅎㅎ!', 30, 2, 'GOOD', SYSTIMESTAMP);
