INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '청포도타르트 주문했습니다!!! 디자인부터 너무 예뻐서 케이크만으로도 선물 같았어요!! 카페 주인분도 엄청 친절합니다!! 맛있고 예쁜 케이크 주문하고 싶은 분들께 완던 추천드려요!!🥳😊', 50, 6, 'GOOD', SYSTIMESTAMP);
