INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '친구 생일이라 딸기타르트 예약하구 픽업하러 왔어요ㅎㅎ 분위기도 넘 좋구, 포장도 선물하기 너무 좋아서 다음에 또 재방문하고 싶어지네요 ㅎㅎㅎㅎ ♥️', 129, 21, 'GOOD', SYSTIMESTAMP);
