INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '집 근처라 종종 들려서 테이크아웃 하는데 항상 친절하시고 음료 맛있어요~ BGM도 항상 좋고 앉아서 이야기하기 좋은 카페입니다ㅎㅎ크림 올라간 라떼 메뉴 추천해요~', 0, 8, 'GOOD', SYSTIMESTAMP);
