INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '생일 케이크 대신 치즈타르트를 준비해봤어요!! 사진은 2호 사이즈인데 크기가 크진 않지만 5명이 한 번에 먹기 딱 좋았어요~ 적당히 달달하고 딸기는 상큼해서 모두 맛있게 먹었어요🍓🍰👍', 51, 16, 'GOOD', SYSTIMESTAMP);
