INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '주말에 다녀온 합정역 카페 미니멀비~! 앤트러사이트 원두를 사용한다는 곳이라 내심 기대~ 와 커피 맛있다!!! 바닐라라떼 꼭 드세요~>.,< 깊고 적당한 달달함~~ 너무 좋아요! 단호박치즈케이크도 주문했는데 이건 달지 않고 묵직한 맛에 커피와 너무 잘 어울리더라구욥! (지금도 생각남) 사장님도 넘 웃는 모습이 넘 이쁘시고^^ 다음에 또 와야겠어요~~~~ㅂ', 45, 5, 'GOOD', SYSTIMESTAMP);
