INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '엄마 생신때 먹을 케이크로 주문했어요~회사 점심시간 짬내서 방문하느라 12시반 픽업으로 해놓고 조금 일찍 도착했는데 사장님들께서 아직 준비가 덜 되어 약간 당황하신거 같아서 뭔가 죄송스러웠네용ㅠ한 5분쯤 기다리니까 이뿌게 포장해서 주셨어요~ 덕분에 엄마랑 만족스러운 생일파티 했습니다ㅎㅎ엄마가 딸기랑 치즈크림, 타르트 과자 다 맛있다고 하시고 저도 너무 맛있었어용🤤 다음에 다른 기념일때는 다른케이크 구매하러 갈게요~ 서비스로 주신 스콘도 감사합니다ㅎㅎ', 35, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '친구 생일이라 딸기홀타르트 예약 후 찾아갔어요! 예약 방법도 상세히 알려주셨어요 너무 너무 예뻐요!!! 친구가 예쁘면서 맛있다구 너무 좋아했어요 서비스로 주신 스콘도 넘 맛있었어요 감사합니다', 53, 18, 'GOOD', SYSTIMESTAMP);
