INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '친구 생일 기념으로 타르트 픽업해서 매장에서 같이 먹었어요! 타르트 맛있고 사장님 아주 친절하게 포크랑 나이프 챙겨 주셔서 감사했어여! 다음에 또 타르트 예약하러 올게요🥰🥰🥰', 32, 4, 'GOOD', SYSTIMESTAMP);
