INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '단호박케이크 예약해서 픽업했는데 맛이 진짜... 짱입니다. 지인들 기념일 때마다 맛보여주고 싶을 정도에요! 디자인도 예쁘고 완전 만족했어요!', 356, 82, 'GOOD', SYSTIMESTAMP);
