INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '딸기 타르트랑 르뱅쿠키 맛있네요! B크림 커피도 너티하면서 모카 느낌 나는게 맛있었어요😋 디저트 종류도 많아서 다음에 다른걸 먹어봐야겠어요~', 2, 7, 'GOOD', SYSTIMESTAMP);
