INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '친구 생일선물로 미리 예약하고 픽업했는데, 귀여운 하트초도 주시고 친절하셨어요! 무엇보다 진짜 너무 맛있어서 비주얼로도, 맛으로도 최고입니다♥️', 2, 1, 'GOOD', SYSTIMESTAMP);
