INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '전부터 오고싶던 곳이였는데 드디어 오게됐어요! 매장이 깔끔해서 친구랑 머무르기 좋은 것같이요! 술도 팔아서 저녁에 간단하게 대화하면서 한잔해도 정말 좋을 것같아요!! 재방문의사x1000입니다!‘', 48, 2, 'GOOD', SYSTIMESTAMP);
