INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '상수에서 슬쩍 걸어가면서 가본 카페!!! 레몬 한나 타르트 진짜 찐찐찐으로 상콤하고 맛있어요 🍋💛 레몬 러버로서 대추천! 묵직, 꾸덕 쫀득 찐득한 게 너무 맛있어옹!! B 크림 라떼도 달달 고소한 게 맛있었어용 ㅎㅎㅎ 기여운 구움 과자들이 잔뜩이라 지인 선물용까지 사버림 ㅎㅎ. 다음엔 치즈케이크도 먹어보려구요! 기회 되면 시즌 홀케이크도 예약 할고양.. 헤헤 반려동물도 입장 가능이니까 안 갈 이유 업잔하! ❤️ 디저트, 음료, 하이볼 카페 맛집 추천입니당 !!🍪🤎', 90, 15, 'GOOD', SYSTIMESTAMP);
