INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '길 가다 우연히 들어온 카페였어요☕️ 사람 많고 어수선한 걸 힘들어하는 편인데 여긴 한적해서 좋았어요! 사람도 적고 사장님도 친절하세요🫠 노트북이랑 태블릿으로 일하기 좋고 커다란 통 창으로 길고양이들과 산책하는 강아지가 지나가는 모습이 제법 평화롭습니다🍃 리뷰 쓸 생각을 못해서 사진은 없지만 다음에 또 방문하려구요🥺🤍', 14, 6, 'GOOD', SYSTIMESTAMP);
