INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '단호박 치즈케이크 엄청 꾸덕하고 맛있네요! 가장 밑 타르트?층도 맛있어요 ㅎㅎ 맨위에 치즈크림같은게 너무 달지않아서 입맛에 딱 맞았어요! 덕분에 좋은 생일 보냈습니다!', 20, 4, 'GOOD', SYSTIMESTAMP);
