INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '합정 둘러보다가 타르트에 이끌려서 들어왔어요ㅎㅎ 맛은 아직 보지 못했지만, 그냥 봐두 맛있어보여요! 사장님이 친절하시규! 담엔 스콘 종류도 먹우보려구요~~', 73, 15, 'GOOD', SYSTIMESTAMP);
