INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '처음으로 연말케이크로 케이크가 아닌 타르트를 선택해봤는데 너어어무 만족했습니다!! 치즈크림, 딸기, 타르트 파이 모두 완벽하게 맛있었어요🍓🤍 딸기 치즈타르트도 또 먹고싶고 단호박치즈케익도 궁금해서 또 가려고욤〰️', 11, 4, 'GOOD', SYSTIMESTAMP);
