INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '흑임자 크림라떼 너무 맛있어요ㅠ 고소하고 달달함 그 자체 디저트는 단호박치즈케이크밖에 못 먹어봤는데 다른 디저트들도 다 먹어보고 싶어서 또 올거예요..✨ 인테리어도 독특하고 예뻤어요🤍', 10, 5, 'GOOD', SYSTIMESTAMP);
