INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '폭신한 치즈케이크랑 시그니처 음료수를 시켜서 먹었는데 완전 제 취향입니다..🫢 다음에 또 방문하고 찾아올게요 아 그리고 시그니처 크림 라떼는 꼭 드세요 크림 먹다가 기절해요', 17, 0, 'GOOD', SYSTIMESTAMP);
