INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '생일케이크 찾던 중에 일반적인 케이크 타입은 식상하고 색다르게 먹고 싶어서 타르트 타입으로 알아보다가 바로 여기로 골랐어요 !! 1호사이즈인데, 둘이 먹기 딱 좋더라구요 :) 타르트랑 치즈, 딸기의 조화로운 맛 ❤️ 담엔 샤인머스캣으로도 먹어보려구요 ㅎㅎㅎ 사장님두 친절하시구 넘 예쁘셔요,,,😖🫰🏻', 15, 5, 'GOOD', SYSTIMESTAMP);
