INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '타르트도 과일도 많고 맛있었고 저 땅콩 크림 커피도 맛있었어요! 사장님도 너무 친절하셨고 저 스콘?도 귀엽고 맛있었어요! 미니멀비 타르트로 기념일 잘 보내서 다음에는 꼭 딸기 타르트 먹으러 다시 오고싶은 곳이에요! 잘 먹었습니다~!', 31, 1, 'GOOD', SYSTIMESTAMP);
