INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '안녕하세요. 친구 생일이라 케이크예약 했었는데 카페 도착하고 나서 예약 일자가 잘못되었다는걸 알았아요. ㅠㅠ다행히 감사하게도 사장님께서 딸기 사오셔서 새롭게 케이크를 만들어주셨어요ㅠㅠ진짜 바쁘실텐데 너무 감사하고 사장님덕에 친구와 좋은 추억과 맛있는 케이크를 먹을 수 있었습니다. 정말 감사합니다.너무 친절하셔서 후기를 안쓸수가 없네료ㅠㅜㅜ 케이크는 왜이리 맛맀는지 .. 진짜 너무 감사하고 사랑합니다. 복 받으실꺼에요! 처음갔는데도 단골 예약입니다💚 앞으로 잘 부탁 드려요! 💚💚💚', 12, 9, 'GOOD', SYSTIMESTAMP);
