INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '카페 색감이 너무 예뻐서 눈이 즐거운 카페였어요 특히 샤인머스켓치즈타르트는 상큼달콤꾸덕해서 넘 맛있었고 시그니처 비크림커피도 부드럽고 달달하니 딱이더라구요 맛도 멋도 분위기도 다 잡아 한껏 취저당한 힙한 카페니 다들 꼭 가보세용💖', 48, 10, 'GOOD', SYSTIMESTAMP);
