INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '합정역에 타르트 맛집을 추천 받아서 방문했어요. 대표 메뉴인 딸기 치즈타르트와 아이스 라떼로 주문했는데, 달달한 크림에 딸기 데코가 너~무 예뻐요^^ 쿠키시트가 쫀득~쪽득하게 뭉쳐있고, 쿠키가 부드러워서 커피와 궁합이 딱이에요:) 생크림과 딸기의 조합이 크~👍👍👍', 26, 3, 'GOOD', SYSTIMESTAMP);
