INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '다른 곳 과는 차별된 음료가 넘 많아요~ 저는 땅콩 크림커피 시켰는데 다른 음료도 궁금해서 친구들거 다 뺏어먹었어요~ 자두 히비스커스, 한라봉 트로피컬 너무 상큼하구 맛있어영. 땅콩크림커피도 넘 꼬숩고  맛있네요~ 앞으로 합정에서 커피먹으로 여기로 올게요!', 72, 15, 'GOOD', SYSTIMESTAMP);
