INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '포장도 너무 예뻐서 선물받는 기분이고 트렌디해서 사진찍기 좋아요 ㅎㅎ 딸기 타르트도 짱 맛있어요!! 10분 컷 했습니다.. 그리고 사장님도 굉장히 친절하셔서 기분 좋았습니다! 재방문 의사 3000프로에여', 49, 9, 'GOOD', SYSTIMESTAMP);
