INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '기다릴 일이 있어 방문했는데, 흑임자 커피 꼬숩하니 맛나구, 자두히비스커스 자두청이 향도 잘 나구 상콤달달하니 강추 디저트류 다 과하게 달지 않아서 좋았어요 르뱅쿠키 견과류 와장창 들어가지구 좋았습니다! 단호박 치즈케이크도 적당히 달달하고 부드럽고 테이크아웃도 많이 하시더라구요 조용하구 좋아용❤', 27, 6, 'GOOD', SYSTIMESTAMP);
