INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '비크림커피 맛있어영!!! 크림 달짝냠냠 노래넘좋고 블루랑오렌지조합 넘 커여운뎅 어뜩함요 바스크치케추천드립미당~~🔥 잘놀다갈게영~', 102, 19, NULL, SYSTIMESTAMP);
