INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '합정 디저트 카페로 강추드리는 미니멀비는 화이트앤블루의 외관부터 시원시원~하니 멀리서부터 돋보이더라고요 >-< 그리고 오래도록 머무르고 싶어지게 만드는 맛난 디저트, 음료가 잔뜩이라 입이 아주 행복해져여,,, 신상 디저트인 체리치즈타르트는 완전 신선해서,, 상콤달콤,, 최공,, 이런 무더운 여름에 완전 제격이었습니다아 ㅎㅇㅎ', 30, 10, 'GOOD', SYSTIMESTAMP);
