INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '진짜 너무 맛있어요ㅠㅠㅠㅠㅠ! 선물로 사갔는데 다들 너무 좋아하더라구용!!! 사장님도 너무 친절하셔서 또 방문 예정입니다!😝😝😝', 71, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '집근처라 항상 사람이 많아서 궁금했는데 음료도 맛있고 메뉴가 다양해서 좋아요! 분위기도 좋고 직원분도 친절하셔요~ 자주 오게 될 것 같아요ㅎㅎ', 10, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '인테리오도 너무이쁘고 단호박치즈케이크맛있다고 해서 아빠엄마 결혼기념일겸 사러갔습니다 케이크도 너무 이쁘고 담에또 사러올거같네요 맛도 좋네요', 125, 25, 'GOOD', SYSTIMESTAMP);
