INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '합정동디저트맛집이에요 청포도타르트 주문했는데 토핑과일에 시럽안뿌리고 너무 신선했어요!! 과일 본연의 단맛으로 먹을수있어서 좋았고 아래에 치즈케이크도 도톰해서 맛있네용!! 딸기타르트는 시즌끝나서 없다고 하셧는데 딸기타르트 시즌에도 꼭 와야할듯하네요!!', 103, 19, 'GOOD', SYSTIMESTAMP);
