INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '회사 근처라 자주 이용하는데 사장님도 항상 웃는얼굴로 반겨주셔서 피곤하더라도 미니멀비에서 커피 사러가면 항상 힘이납니다!! 커피도 너무너무 맛있어요💕', 14, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '시크한 인테리어와 사랑스러운 메뉴❣️ 주말 오전 산책하다가 홀린듯 들어간 카페에요 🫶🏻 트레이와 접시의 컬러감이 너무 예쁘고 음료도 맛있었어요 🥰 사장님도 너무너무 친절하세요 ❣️❣️ 보석같은 카페를 새로 찾게된것같아 기뻐요 🩷🩵💙', 80, 16, 'GOOD', SYSTIMESTAMP);
