INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '산책 끝나구 갱얼쥐와 어디를 가야할까 고민하던 중에 미니멀비가 애견동반 가능해서 다녀왔어요! 날이 좋아서 야외좌석 앉았는데, 가게 앞 쪽 말고 옆 쪽 입구에도 자리가 넓게 있어서 아이들도 뒹굴면서 먹을 수 있었어요 !! 여기 스콘 넘 맛있네요🫶🏻 새로나온 옥수수 스콘도 꼬숩고 밀크티 스콘도 맛있었어요 위에 토핑으로 잼이랑 크림 추가했는데 넘 맛있어서 포크 내려놓고 손으로 와구와구 먹는데,, 갱얼쥐들도 탐내는 맛 ,, 🍓 담에 산책 끝나구 또 들를 거에요! 🫶🏻', 2, 6, 'GOOD', SYSTIMESTAMP);
