INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '합정 망원카페중 진짜 최고!!! 사장님 두분이 너~무 친절하시구 디저트 넘 예쁜데 가격착해요 ㅠㅠ 게다가 맛도있어서 포장해오려고했는데 지인와서 급히나오느라 ㅠㅠ아쉬워서 또 가려구요~~! 애견동반도 가능해서 순간 애견카펜줄알앗어욬ㅋㅋㅋㅋ 행복해땁니다💛💛 요 동네에 진짜 댕댕이들 산책 엄청 마니하시드라구요~~~~ 오며가며 다 들어오심 !!!! 사장님들도 강아지 넘 이뻐하는게 보이시구 ㅎㅎㅎ 나중에 울 댕댕이 데리고 가도 좋을거같아용 !!!', 94, 20, 'GOOD', SYSTIMESTAMP);
