INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '저번에 오고 너무 좋아서 또 왔어요♥️ 커피위에 크림 올라간거 너무 맛있고 쿠키도 에이드도 진짜 맛있었어요😝 새빛공원 바로 앞 신호등 건너면 카페가 있어서 강아지들이랑 신나게 놀고 아이스아메리카노 마시면서 휴식하기 진쨔 좋은곳..🐕🐩🐩 강아지 마실 수 있는 물도 있고 의자에 줄 묶어둘 수 있어서 너무 편해요 그리고 사장님들이 정말 예쁘시고 예쁘시고 예쁘시고😜 친절하시고 😚😚  추천합니당👊👊', 17, 8, 'GOOD', SYSTIMESTAMP);
