INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '디저트를 엄청 좋아하는데 회사근처에 리뷰좋은곳 찾다가 우연히 들어온곳!!!  맛있는 메뉴가 넘많아서 고민고민하다 르뱅, b크림 시켰어요!!! 너무 맛있어요💕❤️❤️❤️', 34, 4, 'GOOD', SYSTIMESTAMP);
