INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '디저트 종류가 다양해요! 바스크치즈케이크 먹었는데 진하고 부드럽고 맛있어요. 매장은 넓고 깔끔해요. 화장실도 남여 구분되어있고 매장안에 있어서 편리해요.', 61, 17, 'GOOD', SYSTIMESTAMP);
