INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '애정하는 합정동 카페!! 미니멀비~~ 와~~땅콩크림커피 무슨일이래요!! 너무 맛있어요. 제주도 땅콩커피 1도 안부러워용~~ 오늘부터 땅콩크림커피는 합정동 미니멀비 입니다!! 여기 BGM도 취저구 너무 친절하시궁 암튼 올때마다 너무 기분 좋은 곳이에요:)', 48, 8, 'GOOD', SYSTIMESTAMP);
