INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '합정동 골목길안 조용하고 아늑한 카페 수제 디저트도 맛있고 시그니처 음료도 많아요. 위스키나 하이볼도 일부 있습니다. 자리마다 전원콘센트가 있어요. 넘 친절하시고 대화하기 좋습니다.', 39, 8, 'GOOD', SYSTIMESTAMP);
