INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '합정에서 간단하게 스콘이랑 커피타임 갖기 좋은 아늑한 카페에요 ;) 자리 넉넉하고 비지엠이 좋아서 작업하러 오기 좋을 것 같아요!', 118, 20, 'GOOD', SYSTIMESTAMP);
