INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '근처에 반려동물과 갈 수 있는 음식점이 있어서 거기 갔다가 커피 마시러 오기 좋아요~ 애견동물 동반 가능한 카페입니다! 깔끔하고 차분한 분위기에 커피와 간단한 베이커리류가 팔아서 강아지 데리고 와서 커피 한잔 하기 괜찮을 거 같아요!', 27, 9, 'GOOD', SYSTIMESTAMP);
