INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '합정역 디저트카페 미니멀비! 제가 자주오는 합정역 인근에 위치한 반려견 동반 가능 카페입니다🐶 미드센츄리모던 스타일의 감각적인 인테리어와 힙한 음악이 흐르는 미니멀비(MINIMAL B). 내부는 조용하니 편하게 대화하기 좋은 공간이네요. 저는 시그니처 메뉴인 땅콩크림커피, 자두히비스커스 그리고 디저트로 딸기치즈케이크, 밀크티스콘을주문했어요! 고소하고 달콤한 땅콤크림과 진한 커피의 조합이 특색있고 좋았습니다! 그리고 꾸덕꾸덕한 수제 딸기치즈케이크도 맛있었어요! 😄👍 다른 카페와는 달리 ''미니멀비''만의 개성있고 맛있는 커피와 수제 디저트를 맛 볼 수도 있고, 귀여운 댕댕이들도 볼 수 있어서 좋았어요!🐕‍🦺💕', 98, 23, 'GOOD', SYSTIMESTAMP);
