INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '궁금했던 미니멀비의 하이볼! 언제 맛보나 싶었는데 드디어 맛보았습니당 말모말모 샤라락 혼술 하기에도 너무 좋은 보물 같은 곳이네용! 하이볼 안주로 시킨 크림밀크티도 너무 맛있어서 감동. 늘 기분 좋게 다녀갑니다💜', 26, 0, 'GOOD', SYSTIMESTAMP);
