INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '분위기두 좋구 인테리어도 깔끔하구 ㅎㅎㅎㅎ 합정역 주변에 힙한카페 진짜많은거같아요!! 디저트들도 가격 좋구!! 사장님고 친절하시고!! 네이버 영수증리뷰 이벤트 참여하기도 좋을거같아요:)', 69, 15, NULL, SYSTIMESTAMP);
