INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '저는 크림 안좋아해서 하이볼 마시고 친구는 삐크림커피 마셨는데 진짜 진짜 맛있대요 저도 한입 먹어봤는데 정말 맛있었어요 여기오면 이 메뉴 드세용!! 사장님도 너무 친절하시고 인테리어도 예뻐용', 27, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '🔹메뉴추천 : B 크림커피 (시그니처), 레몬하이볼 🔹개인적 의견 : 커피와 술이 함께하는 공간. 일단 크림커피 진짜 너무 맛있음. 먹어본 아인슈페너들 중에서는 손꼽히는 맛인듯. 약간 힙하면서도 조용한 분위기라 대화하기 좋은 공간. 디저트도 하나하나 다 귀여운 느낌이라 커피에 곁들이기 좋음. 홍대 합정 쪽 조용하게 대화하기 좋은 곳이고 소개팅하기 좋은 카페인듯! 시끄러운 메인 거리에서 벗어나 있어서 오히려 더 좋았던 듯🙂👍🏻 바스크 치즈케이크도 잘 구워져서 맛나고 하이볼도 진하게 타주셔서 의외로 치즈케이크와 오묘하게 잘맞았던 듯!😌', 53, 17, 'GOOD', SYSTIMESTAMP);
