INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '딸기치즈케이크 너무 맛있었어요😍 그리고 얼그레이 스콘, 얼그레이 쿠키 얼그레이류 왜이렇게 맛있나요!! 카페 분위기도 아늑하고 완전 디저트 맛집이에요. 사장님도 너무 예쁘시구 친절하셔요❤️', 45, 3, 'GOOD', SYSTIMESTAMP);
