INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '추운날 늦은시간에 방문했는데 친절하게 응대해주셔서 인상깊었어요! 단호박치즈케이크 추천해주셔서 먹었는데 웬걸 이거 요물입니다 엄청 맛있어요! 사이즈가 조금 작아서아쉽지만 다음엔 1인 2케잌 시킬려구요..! 티에이드 추천해주셔서 리치캐모마일 시켰는데 캐모마일 티 베이스에 리치향 시럽이 달콤하고 정신이좀 맑아지는 개운한 맛이었어요! 잘먹었습니다. 아 그리고 마감때 맛보라고 조금 주셨는데,, 여기 스콘 진짜 맛있습니다!!!!', 5, 0, 'GOOD', SYSTIMESTAMP);
