INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '바스크치즈케잌 완전 맛있어용 ! 차별화되어있고 좀 특별해요. 밀가루 안들어가서촉촉 그자체 너무맛있어요. 삐크림커피는 대표메뉴중의 하나라 아아랑 같이 시켜봤는데 크림이 쫀쫀해요. 아메리카노 원두 베이스는 적당히 고소하면서 산미가 조금 있는편에 속합니다. 깔끔하고 맛있어요🧡🧡', 54, 17, 'GOOD', SYSTIMESTAMP);
