INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '분위기 인테리어 너무 취저요..💓스콘도 맛있어용!!사장님도 친절하시고, 저녁먹고 커피 한잔 테이크아웃하려고 들렸는데, 매장도 시원합니다 ㅎㅎ', 31, 9, 'GOOD', SYSTIMESTAMP);
