INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '인테리어가 너무 예뻐요💙🧡 요즘 분위기 잔뜩 나는 인테리어 컬러감과 힙한 음악👍  디저트도 먹음직스럽게 다양하구~ 무엇보다 흑임자크림커피 진짜 최고🫶🏻 달콤 꼬숩과 커피의 완벽한 조화예요!!', 53, 13, 'GOOD', SYSTIMESTAMP);
