INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '진짜 딱 한 입만 먹고 집 가서 각 잡고 먹으려고 했는데 그 자리에서 순삭.. 정말 맛있어요. 다.. 그냥 다 마시따.. 뭐라 설명하기 어려운데 먹을 수록 축적되는(?) 맛있는 맛이에요. 이런 행복은 널리 알려서 더 많이 다 같이 누려야만 해요. 늘 친절하게 맞이해 주셔서 감사합니다◡̈', 10, 0, 'GOOD', SYSTIMESTAMP);
