INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '아인슈페너랑 호박케이크 진짜 너무 맛있어요! 다른 사람한테도 추천 하고 싶어요🥹🥹 공원도 가까이 있으니까 공원 산책 할 겸 꼭 오세요! 福岡に来たけど、近くに公園もあるし、 ケーキと、アインシュペナー、ぜったいオススメです！！！🥹🥹🥹 ぜひ来てください🥹🥹', 52, 17, NULL, SYSTIMESTAMP);
