INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '집앞에 있어서 종종 스콘이 땡길때들르는 집입니다! 직원분도 너무 친절하셔서 항상 가게되는데요! 💕!!! 포인트는 스콘도 고소하고 맛있습니다! 영수증리뷰 하고 미니스콘도 주시는데 오늘은 없다고 다음에 챙겨준다 하시곤 늦게 발견하셔서 저희주시려고 막 뛰어오시더라구요🥲 너무 감사합니다! 맛있게 잘먹고 다음에 또 들르겠습니다!', 37, 5, 'GOOD', SYSTIMESTAMP);
