INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '''스트레스 녹이는 맛'' 딸기치즈타르트 진짜 최근 먹은 것 중 제일 맛있습니다!! 이거 홀사이즈로 판다면 사고 싶네요!! 또올게욤♡', 26, 2, 'GOOD', SYSTIMESTAMP);
