INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '요즘 최애 카페입니다- :) 낮과 밤 다른 느낌으로 힙하고 아늑한 분위기 너무 좋아요. 커피랑 디저트도 정말 맛있고요! 새로운 메뉴인 딸기치즈케이크는 완전 취저! 꾸덕하고 부드러운 치즈와 진한 타르트 상큼한 딸기와 생크림까지 완벽한 조화가 정말 최고입니다! 또 갈게요-! ㅎㅎ', 50, 0, 'GOOD', SYSTIMESTAMP);
