INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '단호박치케에서 알아봤어요... 쿠키도 맛있을거란걸... 역시는 역시네요!!! 이르케 찐하고 부드럽고 맛있는 레드벨벳쿠키는 첨이에요 😭 먹는 입장에서는 너모 감사한 일이지만 오지라퍼는 사장님들 남는게 있을까싶어 괜스레 걱정이 다 될 정도로 디저트 라인이 엄청나네용!!! 👍👍 아메리카노도 완전 제 스타일! 멋진사장님들 만큼이나 쎈스터지고 멋진 공간이라 갈때마다 기분이 좋아요~~ 단골예감!😍👍', 44, 5, 'GOOD', SYSTIMESTAMP);
