INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '비크림커피가 너무 맛있어서 크림커피 종류 다 시켜먹었어요 지난번에 없던 딸기치즈케익도 시켯는데 진짜 맛잇네요 또 먹고 싶어 조만간 재방문 예정입니다 믿고먹는 디저트 카페 내맘대로 단골 등록 완료~!', 32, 9, 'GOOD', SYSTIMESTAMP);
