INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '자두 히비스커스 사진 색감보고 너무 이뻐서 주문하는데 보드카 추가 메뉴가 있어서 사장님들께 물어봤더니 추가된다고 하셔서 추가해서 마셔봤는데..너무 맛있어요! 음료자체가 맛있었고 술맛은 강하게 나지 않아서 알쓰들도 마실 수 있을 것 같아요! 추천합니다😊', 41, 2, 'GOOD', SYSTIMESTAMP);
