INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '아아 마시구 브라우니 포장했습니다 꾸덕하면서 부드러워서 맛있음 ! 소품들이 귀여워서 눈길이 가고, 새로생긴데라 그런지 가게가깔끔하고 화장실도 남여 구분되어있어서 좋음!', 11, 2, 'GOOD', SYSTIMESTAMP);
