INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '반려동물 동반으로 같이 갔는데 카페 분위기도 너무 좋고 앞으로도 자주 방문 할 거 같아요!!! 사장님도 너무너무 친절하셔서 기분 좋게 있다가 나왔습니당 *ଘ(੭*ˊᵕˋ)੭* ੈ♡‧₊˚', 97, 25, 'GOOD', SYSTIMESTAMP);
