INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '커피에 산미가 없는데 맛이 아주 특별하고, 딸기라떼도 맛이 남달라요. 스콘 좋아하시는 분들도 오시면 좋을 것 같습니다! 그리고 조용하고 대화하기 좋아요!!', 4, 10, 'GOOD', SYSTIMESTAMP);
