INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '합정 근처 카페를 찾으신다면,,,,요기를 강추드립니닷!!🙌 커피는 고소하니 맛나고 디저트가 진짜!! 찐으루 맛있습니다!! 친구랑 가서 케이크 먹고 감동의 눈물을 흘리며 다른 메뉴들도 시켜 먹었어요 🥹 그 외에 매장 내부 인테리어도 깔끔하고 화장실도 깨끗해요. 그냥 단점은 없고 장점만 있는 카페.. 추천드립니다👍', 94, 24, 'GOOD', SYSTIMESTAMP);
