INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '카페마다 시그니처 메뉴잇는 곳을 좋아하는데 여기도 특별한 메뉴가 많더라구요! 커피 넘넘 마싯고 디저트듀 다양하게있어용👍🏻👍🏻👍🏻', 42, 3, 'GOOD', SYSTIMESTAMP);
