INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '사장님 두 분 너무너무 친절하세요. 그리고 디저트가 너무 맛있어서 치여버렸어요. 스콘 맨날 생각나요. 솔직히 매일 가기가 창피해서 한 번에 마니 사오고 있답니다. ꒰⸝⸝•｡•⸝⸝꒱', 72, 17, 'GOOD', SYSTIMESTAMP);
