INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '모르는 메뉴 여쭤봤는데 사장님이 너무 친절하게 설명도 잘 해주셔서 주문할때부터 너무 기분이 좋았어요!! 디저트도 너무 귀엽고 맛있어요 너무 달지 않고 좋아요!! 커피는 산미가 살짝 있는 편이예요', 42, 0, 'GOOD', SYSTIMESTAMP);
