INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '커피는 산미가 적어요! 그래서 좋음ㅎ 스콘은 기대를 안했는데 이게왜맛있죠...? 디저트맛집인듯..!! 사장님 넘 친절하시고 생긴지 얼마안됐는데 집이 코앞이라 넘 좋아요ㅎㅎㅎ 다른 디저트랑 커피먹으러 갈의향 10000%', 45, 7, 'GOOD', SYSTIMESTAMP);
