INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '근처 카페중에서 여기 아아가 젤 맛있었음. 몰토베네앞에있어서 몰토베네에서 식사하고 여기서 쿠키사고 아아도 마셨는데 딱 좋았음. 글고 화장실 깨끗하고 남녀분류되잇어서 그게 젤 맘에 듬. 근처 화장실들은 다 남녀공용이라 비추.. 초코칩스콘이랑 레드벨벳쿠키 진짜 존맛.. 매일 와서 사재기하는중', 43, 10, 'GOOD', SYSTIMESTAMP);
