INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '미니멀비'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '이렇게 조용하고 아늑한 분위기 카페 짱 최고👍🏻ㅜㅜ음료를 엎어서 완전 진상 손님 이었을텐데 저희부터 걱정해주시고😭죄송하고 감사합니다 에이드 지쨔 맛있어여!!!! 담에 또 오깨요 사장님', 26, 1, 'GOOD', SYSTIMESTAMP);
