INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '여자친구가 태어난지 9000일 된 날이라 기념으로 주문 제작 했어요 우선 픽업하러 갔을 때 직원분들이 친절하게 맞아주셔서 다음에는 카페를 직접 이용하고 싶더라구요 ㅎㅎ 여자친구가 케이크 너무 귀엽다고 좋아했고, 안에는 부드러운 시트와 블루베리 잼이 있는데, 크림치즈와 조화가 너무 좋아서 맛있었습니다!', 6, 1, 'GOOD', SYSTIMESTAMP);
