INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '#협찬  케이크와 쿠키를 맛보았어요. 케이크는 생각보다 달지 않아서 너무 좋았고, 쿠키는 정말 귀여운 모양으로 눈길을 사로잡았답니다. 매장이 알록달록하게 꾸며져 있어 사진이 특히 잘 나왔고, 분위기도 아늑해서 친구들과 오기 좋은 곳인 것 같아요. 다양한 디저트가 있어 다음에 또 방문해서 다른 메뉴도 도전해보고 싶어요! 정말 만족스러운 경험이었습니다. 😊', 11, 2, 'GOOD', SYSTIMESTAMP);
