INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '합정역 근처 사랑스러운 디저트카페 해피베어데이 합정본점 방문했어요!! 건물부터 예쁜컬러로 눈에 잘 띄고 내부도 아기자기 예쁘게 꾸며놨네요~☺️♥️ 케이크며 쿠키, 파이 등 비주얼 하나하나 너무 예뻐서 보는 재미도 있고, 고르기 어려울 정도로 훌륭해요🥰 비주얼만큼이나 맛도 좋아요~~ 레터링케이크는 특별한 선물로도 좋을거 같아요!! 해피베어데이 합정 추천이에요♥️', 19, 6, 'GOOD', SYSTIMESTAMP);
