INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '초딩 아이가 원해서 예약&픽업 구매 했어요. 합정 본점 네임 레터링 문의드렸고 응답은 바로 해주세요. 생일케이크인데 기본 촛불&성냥을 안줍니다. 따로 구매해야 합니다. 케이크는 미니 사이즈 딱 좋습니다. 크림이 많아서 빵만 골라 먹었어요. 굳이 찾아가서 먹을만큼 맛있지는 않아요 ^^;;', 66, 13, NULL, SYSTIMESTAMP);
