INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '케이크 귀엽져 맛도 있어용 대부분의 레터링케이크 겉면만 예쁘지 맛은 없잖아용? 해피베어데이는 완전 맛있습니다 카페 분위기도 귀엽고 아기자기해서 사진찍기 좋고 직원분들도 친절하고 좋아용', 24, 6, 'GOOD', SYSTIMESTAMP);
