INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '친구생일 당일에 일이많아 만들어주기 어려울 것 같아 급하게 전날 제작주문을 했는데 다음날 시간맞춰 잘 나와서 친구에게 전달해줬네요! 친구가 너무 고마워했어요! 잘먹었다고 인증까지 보내준  :) 여기매장은 첨이지만 일하는 매장 앞 백화점에 있는 곳과 같아서 맛보장되어 주문했는데 주문하길 정말 잘한것 같네요!~ 직원분인지 사장님인지는 잘모르겠지만 먼가 불친절한 느낌이였어서 찾으러갈때 좀 기분이 그랬는데 그래도 친구가 잘먹었다니 기분은 좋네요! 가끔 합정가는데 카페도 이용해봐야겠어요~~', 50, 4, NULL, SYSTIMESTAMP);
