INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '친구 생일 겸 출산 축하하려고 미리 예약하고 받았습니다 디자인 너무 귀여워서 받는 친구가 예쁘다고 좋아했어요😊 예쁘게 잘 만들어주셔서 감사합니다 특별한 날 좋은 선물이 되었어요', 46, 10, 'GOOD', SYSTIMESTAMP);
