INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '남자친구랑 1주년기념으로 케이크 전날 예약하고 방문했어요 케이크가 생각보다 안 달고 크림도 안 느끼하고 맛있더라고요 배불렀는데도 다 먹었어요 근데 초는 따로 사야하는 것 같더라고요 2000원이라 그냥 샀고 따로 주는 일회용 숟가락은 없어서 챙기는게 좋을 것 같아여 ㅎㅎ', 6, 9, 'GOOD', SYSTIMESTAMP);
