INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '10/23 (수) 11시 조금 넘은 시간에 방문했어요! 첫 방문이었는데 생각보다 사람이 많지 않아서 놀랐고, 직원 분이 불친절했어요…. 쿠키 두개는 포장해 가지고 갔고, 매장에서는 푸딩, 케이크를 먹었는데 오래된 것 같이 느껴졌어요…그래도 맛은 있었어요….. 매장 안에 모기와 날파리가 날아다녔고 쿠키 진열해둔 곳에 쿠키 부스러기 같은 게 떨어져 있어서 위생적이지 못하다고 느꼈고, 또 매장 노래 소리가 너무 커요….! 이야기 하는데 노랫 소리가 너무 커서 이야기 조금 하다가 그냥 나왔어요….. 한 번 가본 걸로 만족할래요 🥹', 42, 9, 'BAD', SYSTIMESTAMP);
