INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '마카다미아말차쿠키, 초코오레오케이크, 말차라떼와 아메리카노를 주문했어요! 디저트들이 정말 너무 귀염뽀짝해서 어떤 디저트를 주문할지 행복한 고민을 했네요🐻 다음번에는 미니 도시락케이크를 주문제작해보려구요!', 9, 3, 'GOOD', SYSTIMESTAMP);
