INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '🖤26000원짜리 케이크정말 멋지죠?😖🖤 여러분 주문 하실땐 하트는 빨강이 기본이래요~❤️ 검정으로 분명히 써도 파티쉐마음대로 빨강하트가 짜잔‼️‼️❣️❣️❣️‼️❤️‼️❣️❣️❤️❤️🤣 들고나가면 주문과 다르게 케이크 만들어놔도 환불이 안되니 꼭 속지말고 버리고 나오세요‼️‼️‼️ 주문할땐 이거저거 다 동의해야 한다고 해놓고 해피베어데이는 기본응대도 정말 2️⃣6️⃣0️⃣0️⃣0️⃣원케이크 처럼 멋대로 ‼️‼️아니 아주 멋져요~~~~❣️❣️❣️❣️‼️‼️‼️ 눈물이나요~❤️❤️❤️❤️❤️ 통화로는 환불해준다고 해놓고 연락받지도 않고 모르쇠 시전하네요 사과는 통화로 했다면서 환불해준다고 한건 기억이 안나는마법‼️ 좋은날 기념하려다가 아주 기분을 제가 받은 26000원짜리 !! 케이크처럼 만들어주셨어요🥹🤣❤️❤️❤️ 다들 케이크 여기서 주문하실때 참고하세요❤️❤️‼️ ❤️❤️❤️❤️❤️❤️❤️❤️❤️❤️❤️❤️', 1, 7, 'BAD', SYSTIMESTAMP);
