INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '친구브샤기념 홍대에 사진찍으러온김에 케이크도 주문제작 했서욤 ㅎㅎ 보통 카톡으로 제작문의 하면 한나절걸리는데 여기는 네이버예약으로 간편하게 할수있어서 좋아욤ㅋ 맛은 주인공에게 있어서 모르겠지만 원한대로 제작되어서 좋아요 ! ㅎㅎ 보냉백도 4천원추가하면 구매가능하니 더운날에도 안심하고 픽업할수있어 굿~!', 43, 6, 'GOOD', SYSTIMESTAMP);
