INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '1호 케이크라 사이즈는 작지만 너무 예뻐요. 멋진 선물했습니다. 참고로 레터링이 불가한 상품이고 토퍼는 흰종이에 검은글씨 기본 출력물로 준비해주셔서 특별한 레터링 토퍼는 별도로 준비해야해요. 이전부터 해피베어데이 케이크 맛있고 특별해서 참 좋아했는데 이전 백화점 구매 상황들과는 다르게 픽업으로 찾아간 합정 본점의 직원?알바?분은 상품에 대한 정보도 잘 모르고 응대도 별루여서... 다음에는 다른 지점으로 주문하려고 합니다. 불편한 맘이 생겼으니 이것도 하나의 불친절이겠죠. ㅡㅡ 전날 전화 응대 남자분은 친절하셨는데...', 16, 9, 'BAD', SYSTIMESTAMP);
