INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '진짜 안에 오레오초코? 맛이 너무 맛있어요!!!! 생각 이상으로 너무 맛나요🥹 초코쟁이 남자친구도 옴총 좋아헸네유 많이 파세여', 49, 6, 'GOOD', SYSTIMESTAMP);
