INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '해피베어데이 너무 예쁘고 귀여운 카페입니다 . 아이들과 가도 좋을거 같고 친구들하고 가도 너무 재미있을꺼같은 카페였어요. 특별한날 선물하기 좋은 아이템입니다 . 아무리 생각해도 쿠키들 늠 귀여웠어요 .ㅎㅎㅎ 해피베어데이 홍대디저트카페로 완전 추천드려요', 15, 6, 'GOOD', SYSTIMESTAMP);
