INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '합정생파있어서 검색했는데 너무 만족해여어. 우선 곰돌이가 반겨서 기분좋구 주차 편하구 케이크 보기만해도 기분좋구♡ 친구가 좋아해죠서 더더 좋았네요 맛은 덤ㅎ 컬러 너무 귀엽구 좋은데 사이즈가 좀더 큰게 있음 좋겠어요~ 합정오면 또 갈게요:)', 39, 8, 'GOOD', SYSTIMESTAMP);
