INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '이번엔 도시락케이크 예약으로 방문했었는데요! 매장 외관이나 내부 인테리어가 아기자기하고 예뻐서 다음엔 내부 이용도 해보고 싶다고 생각했었습니다 ㅎㅎ 케이크 디자인도 신청한대로 예쁘게 잘 나왔어요! 감사했습니다 ^0^', 10, 1, 'GOOD', SYSTIMESTAMP);
