INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '디저트 메뉴들이 너무 귀엽구.. 뽀짝해요! 거기에 맛도 좋아서 놀란.. 🩷 가게가 넓고 2층까지 있어서 좋아요!!! 자리도 많구요 그리고 사장님 너무너무 친절하세요 .. 🧏🏻‍♀️ 마음같아선 좋은 키워드 다 주고 싶었는데 5개 가 최대라니... 말도 안돼요 💦☹️☹️', 55, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '외관부터 눈에 확 띄는데 내부에 들어가면 케이크랑 쿠키들 디자인이 미쳤어요!! 동화속에 놀러 온 것처럼 아기자기하고 메뉴가 다 맛잇게 생겨서 선택 장애 올 뻔 했어요ㅜㅜ 고심 끝에 고른 디저트들이 보기에도 이쁜데 맛도 있어요!! 디자인이 이쁘면 맛이 구린 곳이 많은데 해피베어데이는 제 편견을 부셔준 카페에요🫶', 60, 13, 'GOOD', SYSTIMESTAMP);
