INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '동화 속에 온 것 같이 카페가 너무 아기자기하고 예뻐요!!💖 단독 건물이라 내부도 넓고 무엇보다 귀여운 디저트 종류가 많아서 좋았어요 ㅎㅎㅎ 골라먹는 재미도 있고 다 맛있더라구요ㅠㅠㅠ 데이트 장소로 추천드려용!!', 49, 5, 'GOOD', SYSTIMESTAMP);
