INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '통합 센터 상담원 상당히 불친절합니다. 이단 케익 레터링 영문만 되는줄 모르고 주문했는대 한글로 레터링 한것을 영문으로 변경 요청도 안하고 일방적으로 취소해버려요. 몬가 엄청 기분이 나쁘고 평범한 고객을 진상 취급하는 느낌이더군요 문자 내역 보관하고있습니다. 관리자님 회사위주가 아닌 고객 위주의 상담 부타드려요', 24, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '요기 완전 너무 귀여운 카페... 💛 회사 근처라서 자주 방문했었는데 갈때마다 동심으로 돌아가는 느낌이에요 ! 모든 공간이 쏘 큐트 하고,, 인스타 각입니다.. ! 디저트류 종류가 너무 많고, 비주얼 만큼 맛도 좋아요 ! 물론 커피두요 ! 오랜만에 점심시간에 방문해서 힐링 하고 왔습니다 ~ 해피베어데이 최고최고 !!!', 3, 8, 'GOOD', SYSTIMESTAMP);
