INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '다들 잘 모르시는 것 같은데 여기 조용하게 두바이 쿠키를 팔고있어요! 맛은 피스타치오,헤이즐넛 두가지 인데 저는 헤이즐넛 맛 먹어봤어요 헤이즐넛 두바이 초코쿠키-쿠키 자체가 촉촉하고 식감이 좋고 안에 카다이프는 약간 눅눅했어요 그래도 쿠키 자체가 너무 맛있고 안에 헤이즐넛 스프레드가 많이 들어있어서 쫀득하고 맛있었어요!!', 23, 4, 'GOOD', SYSTIMESTAMP);
