INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '매장이 넓구 아늑해요! 그리고 디저트들 너무 귀여워요 ㅠ.ㅠ🥹 매일 하루에 하나씩 먹구 싶어용!! ㅎㅎ 특히 고구마 앙금 들어간 쿠키는 특이하구 계속 손이 갔어요💘 곰돌이 디저트들 귀여워서 어떻게 먹냐싶었지만 맛있게 잘 먹구 왔답니다..><', 43, 8, 'GOOD', SYSTIMESTAMP);
