INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '홍대 디저트 카페 해피베어데이 다녀왔습니당 본점으로 첫 방문 해본겅데 디저트들도 다 너무 귀엽고!! 음료가 맛있었어요! 커피가 디카페인 안되는거는 조금 아쉬웠지만 ㅠㅠ 그래도 덕분에 맛있게 마셨어요 >< 황치즈 휘낭시에 진짜 맛있더라구요! 여기 레터링케이크도 꽤 유명한걸로 알고있는데 픽업케이크 필요할때 찾아야겠어요 히히', 0, 0, 'GOOD', SYSTIMESTAMP);
