INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '친구들 생일 기념으로 예약했는데 주문한 글씨와 다르게 되어서 당황했습니다 대처도 막 좋지 않았구요.. 사진에 나온 초는 한개당 4천원씩하니 참고하세요! 하지만 이런 실수나 대처말고는 케이크 맛도 좋고 예약할 수 있는 케이크 종류가 여러가지라 좋았습니다', 0, 1, NULL, SYSTIMESTAMP);
