INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '합정카페 해피베어데이 아기자기 너무 귀여워요!!!!!! 친구랑 데이트 왔는데 음료도 귀엽고 디저트 종류가 많아서 고르는 재미가 있어요😍😍😍 사진 찍어도 잘나와서 더 좋네요👍', 8, 4, 'GOOD', SYSTIMESTAMP);
