INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '인스타그램에서 본 케이크가 너무 예뻐서 예약주문 후 픽업 실물이 엥? 스러웠음 같이 구매한 초가 예뻐서 살린거지 레터링이나 전체적인 미감퀄리티가 진짜 실망스러웠습니다 ..', 79, 16, 'BAD', SYSTIMESTAMP);
