INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '지난번 다른 지점에서 아이 생일케이크 사고 넘 만족해서 이번에 아이랑 데이트한다고 방문했는데.. 다른 손님들 나가고 저희만 남으니 어느순간 노래도 끄고 나갈때 쿠키 사가려고했더니 직원들은 코빼기도 안보이고.. 투명인간 취급당한거같아서 지금 하루종일 기분 안 좋아요..', 17, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '좋은 퀄리티 케잌에 감사드립니다! 덕분에 즐거운 생일파티 할 수 있었습니다 하지만 초 하나에 2000원은 조금 부담되더라구요! 그래도 상품 만족도는 정말 높았습니다~', 32, 10, NULL, SYSTIMESTAMP);
