INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '컨셉한번 확실한 귀염터지는 카페에요♥ 근처 눈썹문신받으러 갔다가 계획없이 들어간 카페 너무 아기자기하고 귀여운카페라 맛은 당연 없고 비싸겠지? 했는데 약간 비싸긴해도 맛있었어요!! 큐브라떼도 달달하니 맛있구 쿠키도 맛있구 아아도 맛있더라구요!! 분위기는 쫌 부담스럴수도 있지만 여자들끼리가면 좋을것 같아요!!', 85, 12, 'GOOD', SYSTIMESTAMP);
