INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '홍대에가면 여길 꼭 들러야죠 홍대 디저트카페. 해피베어데이 너무좋아하는데요 귀엽고 맛까지있는 곰돌이쿠키 너무좋아요 오늘은 바스크 치즈 케익도 먹었는데요 정말 최고였어요 아직 겨울철이고해서 따듯한 레몬차를 마셨는데요 여름이 되면 시원한 딸기에이드 먹으러 또 갈꺼예요~~~♡♡♡♡♡♡', 27, 7, 'GOOD', SYSTIMESTAMP);
