INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '합정 랜드마크(!) 벽돌과 회색 건물 속 알록달록 존재감 자랑하는 해피베어데이 오랫동안 가보고싶었는데 안에 들어오니 내부는 주택을 개조한거라 더 아늑하고 넓은데다가 색상과 컬러감+ 넘 귀여운 소품들로 포토존이 가득하다. 디저트는 보기도 예쁜데 맛도 좋음.. 커피 빨대까지 귀여븜.. 합정오면 꼭 들러야할 곳!', 12, 5, 'GOOD', SYSTIMESTAMP);
