INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '홍대 카페 해피베어데이 귀여운거 천지에요!! 귀엽기만 하면 모를까 맛까지 좋으니 딴데 갈 필요가 음슴➿🤍🤍 레터링케이크만 맛봤었는데 매장에 다양한 디저트들 모두 맛있었어요>.< 크림메론소다 강추!! 추가한 곰돌이 큐브도 넘나 귀엽ㅠㅠㅠ 귀어운거 너무조아요ㅠㅠㅠㅠ쏴리질러🐻🐾🐻🐾🐻➿', 22, 2, 'GOOD', SYSTIMESTAMP);
