INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '쌉싸름한 아메리카노와 얼그레이케이크가 잘 어울렸던 곳~! 분위기 좋고 직원분들도 친절해서 기분좋게 커피마시기 좋은것 같아요. 여러가지 디저트가 많아서 담에 재방문해봐야겠어요~~', 23, 3, 'GOOD', SYSTIMESTAMP);
