INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), 'https://m.blog.naver.com/lovelalo8694/223326043446 서울 마포구 해피베어데이 카페 데이트 추천 강추 !! 블로그 후기에서 확인해주세요 ㅎ 저희는 정말 아무 생각없이 걷다가 곰돌이에 이끌려 들어가게된 해피베어데이 처음에는 사진만 찍고 가려고 했지만 , 아 안에가 너무 궁금하여 들어가서 보니 와 여기 사진찍을곳이 많다고 생각하여 자리잡고 딸기에이드와 캐모마일티를 시키교 황치즈곰돌이 , 에그타르트를 시켰어요 하지만 저희는 나온것만 자리에 두고 루프탑도 갔다가 사진도 찍고 이리저리 저희 2층에서 사진도 많이 찍다보니 지쳐 먹은 에그타르트 ㅎ 너무 맛있더라고요 음식도 맛있고 뷰도 좋고 데이트 하기 강추 합니다 ㅎ 우연히 들린곳에서 너무 행복했어요 ㅎ', 4, 9, 'GOOD', SYSTIMESTAMP);
