INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '워낙 귀여운 카페로 유명해서 꼭 한번 다녀오고 싶었는데, 평일에 짬이 나서 후다닥 케이크 하나 예약후 방문했습니다! 친구가 사업을 시작한다고 해서 성공을 기원하는 마음에 가보자고라고 부탁드렸는데 귀엽게 잘써주셔서 선물할만하더라구요. 저는 달달한 걸 잘 못먹는 편인데 초코오레오 맛인 도시락케이크는 심하게 달지도 않고 생크림이 느끼한 맛이 덜해서 크림만 먹어도 괜찮았구요. 가장 좋은 점 중 하나는 위레 데코로 올라가는 크림은 아낌 없이 올려주샸지만, 겉에 코팅되는 크림은 적어서 개인적으론 정말 좋았어요. 일단 느끼하지 않은 점이 제일 좋구요. 조만간 또 케이크가 필요할 거 같은데, 그때는 미니나 1호케이크를 이용해보랴구 합니다. 미니케이크도 생각보다 사이즈가 커서 4인까지 먹을 수 있을 것같아요!', 20, 9, NULL, SYSTIMESTAMP);
