INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '아이와 함께 갈만한곳, 홍대 카페 해피베어데이 핫한 감성의 카페라서 사진 찍고 놀기에 정말 좋아요! 베이커리가 예쁜데 맛도 좋아요!', 8, 0, 'GOOD', SYSTIMESTAMP);
