INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '과연 무슨 가격이 진짜일까요? ㅋ 1. 인스타에서 쑥베리케이크 글(1/29일자,초미니 만원 기재-지금은 수정됨) 보고 문의 2. 예약시 갑자기 15000원이라길래 물어봤더니 재료수급 문제로 가격인상 3. 픽업날 진열매대에 비슷한 케이크가 8500원으로 명시되어 판매중 - 설마 저건 아니겠지하며 예약건 받았는데 진열장과 같은, 위 사진의 케이크였음 4. 진열장 케이크랑 똑같은 거 아니냐 했더니 그건 하루지난 케이크라고 함 - 가격은 왜 다르냐 했더니 안내판이 잘못된 거라고 함 (1월 인스타에도 만원이었으면 가격인상된지 최소 3개월째인데 고작 종이쪼가리 안내문을 안바꿨다는 게 이해불가) 5. 별로 언쟁하고 싶지도 않고 시간도 없어서 그냥 받아서 나옴 6. 이후에 사진정리하며 보니 인스타글 사진과 너무 다름;', 68, 17, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '정말 디저트맛집이예용♡♡ 디저트마다 너무 맛있고 커피도 고소하니 굿굿♡ 인테리어도 너무 귀엽고 동화속같은 이미지라 너무 잘 즐기고 왔어용♡', 40, 9, 'GOOD', SYSTIMESTAMP);
