INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '왠만하면 리뷰에는 좋은 말만 하고싶은데 정말 알바분이 싸가지가 없었습니다. 계산하는데 오만상을 다 찌푸리시는데 싸우자는 줄 알았습니다. 인사도 한번 없고 내가 손님이 아니라 불청객인 줄 알았습니다. 돈내고 이런 대우 받을 이유가 없네요.', 28, 3, 'BAD', SYSTIMESTAMP);
