INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '너무 귀여운 곰돌이 디저트들이 한가득이였어요!! 외관부터 동화속 세상에 놀러온 기분이 들더라고요!! 쿠키도 맛있고 크림 메론 소다 짱짱 존맛탱🍈🍒', 6, 8, 'GOOD', SYSTIMESTAMP);
