INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '케이크 너무 귀엽지 않나요? 배경 바꿀 수 없고 저기에 레터링만 가능한 걸로 알고 있는데 딱히 손볼 디자인 없이 너무 너무 귀여워서 만족해요. 다만 케이크 크기가 너~무 작아서 놀랐어요 근데 또 먹다 보니 둘이서 적당한 정도!? 케이크가 너무 귀여워서 다음에 또 주문할 의향 있어요 굿!!!! 그리고 셀카 맛집이에여 모두 인생샷 건지고 가십셔', 44, 4, 'GOOD', SYSTIMESTAMP);
