INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '키워드 5개로 부족하네여 카페도 외관 색감도 독특하고 바로 앞 주차장도 있어요 내부도 동화 속에 들어 온 것 처럼 여기 저기 다 너무 귀여워요 심지어 디저트도 넘나 귀여워서 먹기 미안할 정도 모양만 이쁜 줄 알았는데 맛도 있어서 담엔 남자친구랑 재방문 하려구요💕', 7, 2, 'GOOD', SYSTIMESTAMP);
