INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '들어올때부터 동화속 공주가 된느낌으로 아기자기하니 가게도 예쁜데 심지어 디저트도 넘귀엽구 사랑스럽구 다하는 카페에요 >_< 🩵 홍대 디저트 카페 중에 최고로 맛있는집이에요 🌿 디저트 진짜 하나하나 다먹어보고싶어서 참느라 힘들었어요 🧸 담에와서 다른것도 먹어보려구요 홀케이크마저도 넘 사랑스럽고 귀엽더라구요 ✨', 39, 0, 'GOOD', SYSTIMESTAMP);
