INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '여기는 모든 공간부터 디저트까지 놀라움의 연속이예요!ㅎㅎ 분위기는 거의 동화책 펼쳐놓은 곳에 와있는 기분이예요 디저트접시 고를 수 있는 것까지 심쿵포인트! 얼핏 인테리어랑 비주얼에만 신경쓰는 컨셉카페같아서 오해했어요 미안해용~~ㅎㅎ 알고보면 케이크랑 디저트에 진심! 퀄리티높은 케이크랑 디저트에 반하고 왔어요 먹어본 버터크림케이크 중 원탑!', 32, 10, 'GOOD', SYSTIMESTAMP);
