INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '얼그레이 케이크는 예쁘게 만들어진 만큼 맛있습니다 보기좋은 떡이 맛도좋다라는 말이 맞는거같아요 :) 주차공간은 많은 편은 아니지만 앞에 주차할 공간이 있어요! 아기자기한 인테리어에 소품들도 있어 공간도 넉넉하고 구경하는 즐거움도 있네요 ㅎㅎ 크림메로 소다 꼭 마셔보세요 맛있어욬!! 홍대 합정 카페맛집! 분좋카', 79, 12, 'GOOD', SYSTIMESTAMP);
