INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '홍대 디저트 맛집!! 저는 당일 케이크가 급하게 필요해서 간거였는데 쿠키도 귀엽고 스콘이나 다른 디저트들도 많네요. 매장도 키치한 느낌이라 사진 잘나올 것 같아요!!', 69, 15, 'GOOD', SYSTIMESTAMP);
