INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '곰돌이 쿠키로 유명하다고 해서 기대하고 왔는데, 기대를 충족시키는 비주얼의 귀여운 쿠키와 스콘, 휘낭시에 베이커리 맛집이었어요👍🏻 📍의외의 베스트 메뉴, 밤 휘낭시에 촉촉한 휘낭시에 속에 통밤이 들어있고 겉부분에 살짝 얹어진 초코가 달달해서 라떼류 음료랑 잘 어울렸어요. 합정, 홍대인근에서 이렇게 비주얼부터 맛까지 완벽한 디저트 카페 흔치않다 봅니다..! 다음에는 케이크류도 포장해봐야겠어요.', 42, 1, 'GOOD', SYSTIMESTAMP);
