INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '케이크가 너무 알록달록해서 맛이 없을 줄 알았는데 생각보다 너무 맛있어서 놀랐어요..! 모든 크림이 다 크림치즈로 되어있는지 진짜 맛있었고 특히 저는 얼그레이 케이크가 너무너무너무x100 맛있었어요 담번에 가면 다른 스콘이나 쿠키들도 츄라이 해볼게요!! 늦게 가서 디저트는 많이 나간 상태라 쬐꼼 아쉬웠어요..! 그치만 그만큼 잘 팔리고 맛있다는 뜻..?ㅋㅋㅋㅋㅋ 암튼 친구 생일이라 친구랑 같이 둘 다 퇴근하고 밥먹고 갔는데도 꽤 오래 앉아있을 수 있었어요! 10시까지 영업하시더라구요 친구 이름을 중간에 넣어서 레터링 해달라고 네이버 예약으로 말씀드렸는데 너무 예쁘게 잘 해주셨어요 감사합니다 내부도 너무 귀엽고 디즈니 노래가 계속 나와서 디즈니 공주가 된 기분이었어요 좋은 방문이었슴다!ㅎㅎㅎ', 28, 4, NULL, SYSTIMESTAMP);
