INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '케이크가 넘 기여워서 친구들이랑 연말파티할 때 딱이예요~!! 저희는 케익을 많이 안먹어서 괜찮았는데, 생각보다 케익 크기가 꽤 작아서 예약 고민하시는 분들은 이 점 고려해서 예약하시길 추천드려요☺️ 그래도 디자인이 너무너무 기여워서 저는 담번에 또 주문할게요❤️🎄', 124, 23, 'GOOD', SYSTIMESTAMP);
