INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '미쳐써요!!!!!! 이렇게 크림이 잔뜩 있어서 비주얼만 보곤 “에이 엄청 느끼할듯... 보기만해도” 라고 말했는데 지인이 진짜 맛있다고 칭찬을 칭찬을 ~~ 그래서 먹어봤는데 너무 맛있네요...? 먹으면서 어떻게 이렇게 만들지?! 싶었어요 ㅎㅎ 오랜만에 디저트 맛집 찾은거 같아요 💓💓', 61, 14, 'GOOD', SYSTIMESTAMP);
