INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '인테리어가 정말 특별하다고 생각했던 합정역 카페. 그런데 오늘 내가 느낀바로는 디저트가 더 특별하다.. 모든 디저트가 하나같이 다 맛있었다👍🏻', 1, 9, 'GOOD', SYSTIMESTAMP);
