INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '입구부터 분위기가 너무 좋았어요 🎈 곰돌이 테마의 이색적인 인테리어가 인상적이었어요 🐻 초코 오레오케이크와 황치즈곰돌이쿠키는 너무 맛있었고, 카야스콘은 달달 고소하니 맛있었어요 🥐 소금초코 휘낭시에와 아메리카노도 함께 즐겼는데, 커피의 맛도 아주 좋았어요 ☕️ 특히 아인슈페너는 부드럽고 진한 맛이어서 너무 만족스러웠어요 💕 다음에도 다른 메뉴들도 꼭 시켜먹어보고 싶어요 🌟 홍대 디저트 카페 해피베어데이 추천합니당💓', 9, 10, 'GOOD', SYSTIMESTAMP);
