INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '얼그레이 향이 강해서 케이크가 맛있어요. 하지만 커피는 별로예요 ㅠㅠ 아메리카노가 5천원이라서 다른 음료를 먹게 유도하고요. 근데 그 다른 커피가 맛이 없습니다 ㅠㅠ 디저트는 귀엽고 맛도 있습니다. 그런데 카페에 콘센트를 다 막아놓으셔서 충전을 할 수가 없는 건 흠이에요.', 46, 0, 'BAD', SYSTIMESTAMP);
