INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '너무 귀여운 카페에요! 데이트하기도 좋구 친구들이랑 수다떨러 오기도 좋아요~ 곳곳에 포토존이 있어서 좋고 인테리어도 넘 귀여워요. 케이크도 달달하고 바닐라라떼도 고소하고 맛있었습니다! 데이트맛집 인정😍', 60, 14, 'GOOD', SYSTIMESTAMP);
