INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '당일 레터링케이크 예약인데도 퀄리티가 너무 좋아요! 맛도 선택할 수 있고 디자인도 다양하고 무엇보다 너무너무 맛있어요!ㅎㅎ 덕분에 행복한 생일을 보냈습니당! 한 달 전 부터 예약해야하는 번거로움이 없어서 편하고 좋아요ㅎㅎ', 41, 0, 'GOOD', SYSTIMESTAMP);
