INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '매장 분위기도 아기자기하고 귀여워서 좋고, 무엇보다 음료랑 디저트 종류들 정말 맛있어요🥹 영수증으로 사진도 찍을 수 있어서 특별해요👍 개인적으로 먹었던 블루베리 요거트 스무디 중 1등 케이크는 부드럽고 촉촉하니 꼭 드셔보세용❤️', 78, 11, 'GOOD', SYSTIMESTAMP);
