INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '사랑스러운 공간에서 먹는 수제 디저트! 음료와 디저트 정말 예쁘고 사랑스러워요❤️ 사진도 잘 나와서 친구들과 인생 사진도 건졌어요! 다음에는 레터링 케이크 먹으러 갈게요😍', 10, 10, 'GOOD', SYSTIMESTAMP);
