INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '카페도 너무 이쁘고 디저트 넘 맛있어요!!요긴 커플들 가서 알콜달콩 데이트하면 좋겠어요~~~개인적으로 군 옥수수스콘 맛있어서 먹고 포장도 했네용', 18, 2, 'GOOD', SYSTIMESTAMP);
