INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '케이크가 생각보다 너무너무너무 작아요.... 조각 케이크 수준... 케이크가 좀 높았으면 좋았을 텐데 엄청 얕아요ㅠㅠ 그리고 케이크 담아주신 비닐봉지가 너무 훌렁 거려서 들고 가기 불편했어요! 귀엽게 만들어주신 건 감사해요..ㅎㅅㅎ...', 114, 22, 'BAD', SYSTIMESTAMP);
