INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '동화속에 나오는 집 안으로 들어온 느낌!! 홍대 대형 디저트 카페로 파스텔톤의 색감이 너무 이쁘고 사랑스러워요♡ 해피베어데이라는 가게이름에 맞게 귀여운 곰돌이들이 여기저기 많이 있어요! 크림메론소다, 구름스무디, 레드벨벳케이크, 흑임자스콘, 레몬시트론 주문했는데 메뉴들이 다 너무 이쁘고 맛있었어요. 크림메론소다 위에는 아이스크림 올라가 있고 메론소다맛이 넘 상큼상큼!! 구름스무디는 진짜 구름모양무늬가 있어요. 신기!! 뽕따맛 나요ㅎㅎ 빨대도 핑크색 하트모양 존예ㅎㅎ. 밤에 가도 이뻤는데 낮에 가면 너무 너무 더 이쁠거 같은곳. 다음엔 낮에 또 한번 가보고 싶어요.', 79, 15, 'GOOD', SYSTIMESTAMP);
