INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '외관부터 내부까지 동화 속에 들어온 것 처럼 아기자기하고 넘 예뻐요💕 특히 디저트는 더더 귀여운데 맛도 좋음..❤️ 여기저기 포토존이 가득하니 데이트하러와서 인생샷 찍고가세요😍', 25, 6, 'GOOD', SYSTIMESTAMP);
