INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '구름소다 너무 맛있어여 근데 쿠키 약간 아무맛도 안나용 !당근 저 슈크림 케이크도 간이 조금 약한거같아용 음료는 맛있었어용 디저트는 귀엽기만 했어용', 140, 42, 'BAD', SYSTIMESTAMP);
