INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '예전에 다른 지점에서 레터링케이크 맞췄던 기억이 좋았어서 믿고 이번엔 특별히 본점으로 주문했던건데 레터링이 너무 당황스러운 퀄리티여서... 일단 요청한 대로 글씨는 써있어서 그대로 찾아왔지만 생일축하해주면서도 많이 속상해져서 새로 케이크 다시 사서 했습니다... 이건 레터링이 이건 좀 아니지 않나요?ㅠㅠ... 오히려 디피되어있는 당일케이크가 더 예쁠정도여서요..ㅋㅋ 도시락케이크는 처음이라 후기 사진 겨우 찾아보고 했던건데 포토케이크했던 때와 너무 달라서 실망했습니다. 점바점이 큰건지 주문제품별 차이가 큰건지.. 도시락케이크 하려는 분들 사진 참고하셔요', 59, 13, 'BAD', SYSTIMESTAMP);
