INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '전화드리고 네이버로 예약해서 금요일 오후 6시에 픽업했어요. 레터링 케이크라 맛은 기대 안 했는데 맛있었어요! 그리고 글자 양옆에 하트를 붙여달라고 했는데 글자색이랑 똑같은 보라색으로 써주실 줄 알았거든요. 그런데 예쁜 빨간색으로 써주셔서 너무너무 마음에 들었어요.🥰 케이크를 위해 왕복 6시간을 달렸지만 전혀 후회 없이 만족스러웠습니다. 다만, 케이크를 만들어주신 분께는 정말 감사하지만 카운터에 계신 흑발, 금발 여직원 두 분이 불친절합니다.', 70, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '조금 실망이었어요ㅠ아무리 크리스마스 가격이 붙었다지만 여자 손바닥 10cm만한 크기에, 맛은 평범한 초코케이크인데 가격이 29,000원.. 정말 특별한 날에 돈 상관없이 먹고 싶으신 분들한테 추천드려요!🥲', 1, 6, 'BAD', SYSTIMESTAMP);
