INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '친구 생일이라 케이크도 픽업하고 카페이용도 했어요!! 깜찍한 토끼케이크로 친구도 좋아하고 알록달록 귀여운 카페라 좋았습니다! 들어가면 다리가 엄청 큰 곰돌이 인형보고 흠칫했지만 음료도 맛있고 디저트도 맛있네요:)', 46, 2, 'GOOD', SYSTIMESTAMP);
