INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '세상에서 제일 귀여운 카페를 발견했습니다‼️⁉️ 이 귀여운 곰돌이, 마치 디즈니랜드 랏소베어같아요! 스모어쿠키를 별로 안 좋아하는 편이었는데 여기 스모어쿠키는 적당히 달고 넘 맛있었떠요. 🥰🥰 그치만 오늘의 제 최애는 옥수수 스콘! 진짜 미쵸따. 제가 마지막 남은 하나 주워온건데요. 진심 마지막 하나 남은 이유가 있었어요. 그리고 매장이 너무 귀여워서 자꾸만 구경하게 돼요. 👀👀 홍대에 이런 귀요미 매장이 있다니 흡족 그잡채랄까요! 다음에 홍대 올때 또 올거에용❤️❤️ 이 리뷰는 제품을 제공받아 작성되었으나 솔직리뷰입니다 :D', 44, 4, 'GOOD', SYSTIMESTAMP);
