INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '🐻곰돌이가 마스코트여서 곳곳에서 곰돌이를 찾아볼 수 있어서 귀여웠어요! 데이트코스로 추천 ✨ 쿠키는 곰돌이 스모어 쿠키부터 다양한 모양의 귀여운  빵들이 많아서 구경하는게 재밌더라구요. 해피베어데이 오시면 케이크는 정말 추천드려요!! 너무 귀여운 캐릭터들이 올라가 있어요.🐥 분위기도 좋고, 사진 찍기에 졸은 카페여서 데이트 가신다면 여기 추천드려요~', 1, 7, 'GOOD', SYSTIMESTAMP);
