INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '🧸해피베어데이 본점에 방문했습니다! 입구부터 알록달록한 색감의 건물이 잘 보여요~ 마치 놀이동산에 온 듯한 분위기였습니다. 음료&디저트&식기 등 아기자기하고 예뻐서 눈도 입도 즐거웠던 방문이었습니다🎀 시그니처인 곰돌이 쿠키도 먹었는데요~ 두툼하고 달콤해서 커피랑 잘 어울렸습니다:) 직원분들도 바쁘시지만 친절하셔서 또 방문하고 싶습니다!', 73, 17, 'GOOD', SYSTIMESTAMP);
