INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '너무 귀엽고 인테리어가 예뻐서 사진찍기에 좋은 곳이에요. 디저트 종류도 많고 디저트도 귀여워서 음식사진도 잘 나오는 카페! 합정 디저트카페로 넘 좋았네요.', 8, 5, 'GOOD', SYSTIMESTAMP);
