INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '최고로 귀염뽀쨕한 홍대디저트카페에요!!!만화에서 나올 거 같은 인테리어에 케이크며 쿠키며 평범한 게 없어요 너무 귀여워요 진짜ㅠㅠㅠㅠ케이크가 진짜 미쳤고 적당히 달고 느끼하지 않은 크림에 맛까지 좋아서 친구 생일에 도시락케이크로 사가도 좋을 거 같아요!!홍대에서 꼭 가볼만한 카페에요', 27, 4, 'GOOD', SYSTIMESTAMP);
