INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '합정에 이렇게 넓고 좋은 카페가 있다니,,!🐻🧸❣️ 아기자기하고 동화 속에 온 것 같은 느낌이에요! 다양한 곰돌이 모양쿠키랑 슈, 귀여운 스콘과 케이크가 있어서 취향 따라 골라 먹기도 넘 좋아요🫶🏻🫶🏻 커피도 맛있고 음료도 다 맛있어서 즐거운 디저트 타임 보냈네요👍🏻', 71, 18, 'GOOD', SYSTIMESTAMP);
