INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '정말 아기자기 귀여운 카페예요! 케이크, 음료, 빵 다 맛있는데, 특히 케이크가 귀여움과 맛 모두 갖추고 있었어요 ㅋㅋㅋㅋ 케이크 강추해요!', 5, 1, 'GOOD', SYSTIMESTAMP);
