INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '외관부터 귀염뽀짝한데 디저트도 난리납니다 취향저갹 그자체 본점러버라 본점으로 방문했는데 매장도 크고 좌석도 많아서 오래머무르기 좋더라고요 음료도 특이한 메뉴있고 곰돌이얼음도 있어서 더~욱 귀엽게 느껴져서 기분좋은 카페였어요💓 병아리 초코케이크 예뻐서 먹기 아까울 정도인데 맛있어서 다 먹었네요 다음에 재방문할게요~~', 247, 43, 'GOOD', SYSTIMESTAMP);
