INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '합정 카페 중에서 제가 생각하는 원픽~너무 이쁜카페와 유니크한 케익, 스콘, 음료 등은 누구나 만족할만한곳~인스타감성카페를 찾는다면 무조건 들려야할곳으로 추천이며~하나같이 맛도 좋아 아이들 마음도 감동시킨 매우 만족한곳~~ 강추드립니다^^~', 69, 12, 'GOOD', SYSTIMESTAMP);
