INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '🔹메뉴추천 : 크림라떼, 구름소다스무디, 쿠키류 🔹개인적 의견 : 대애박..🫢 세상 모든 곰도리 덕후들 주목! 곰도리 좋아하는 사람들 여기 가면 말그대로 해피베어데이 보낼 수 있음🐻🐻🐻 곰도리 모양의 귀여운 쿠키들이 맛별로 전시되어 있고 2층까지 공간도 다양함! 곰도리 인형 많고 카페가 파스텔톤으로 알록달록 아기자기하고 미니케이크도 판매함!🧸🩵 음료도 크림라떼 맛있고 구름소다스무디는 뽕따맛인데 이것도 달달하고 어릴 때 먹던 아이스크림 생각나고 맛남🐻 💜장길동의 맛도리로드 팔로우하면 전국 맛집 다 알지롱💜', 70, 11, 'GOOD', SYSTIMESTAMP);
