INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '홍대카페 해피베어데이 본점은 항상 사람 많아서 안 갔다가 한가한 시간대에 방문해 봤는데 널찍해서 시간 보내기 좋았고 디저트나 음료는 믿먹이라 만족스럽게 먹고 왔어요!! 담에는 커피랑 크루와상 먹으로 또 가려구용🥰 카페 너무 예쁘고 포토존 정말 많아요! 강추 강추👍❤️', 78, 12, 'GOOD', SYSTIMESTAMP);
