INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '해피베어데이 케이크만 파는 곳인 줄 알았는데 합정에 카페가 있다는 걸 알고 호다닥 달려왔어요! 다양한 디저트도 많고 음료도 다양하게 많아서 눈호강했답니당. 매장 전체적으로 다채로운 파스텔톤으로 꾸며져 있어서 사진찍기에도 너무 재미나는 공간이었어요! 귀여운 곰돌이 디저트, 조각케이크 종류도 많아서 합정 데이트하기에도 참 좋은 곳 같아용🥰', 14, 7, 'GOOD', SYSTIMESTAMP);
