INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '요즘 노키즈존이 많은데요 엄마아빠도 홍대 가고 싶고 힙하고 핫한 곳 가고 싶거든요 검색해서 아이들 즐거운 한 때 보낼 곳 엄마는 커피 마시며 콧바람 쐴 곳 찾으니  딱이더라구요 주택을 알록달록 예쁘게 단장하여 마당에도 앉을 곳이 있어 아이들도 좋고 저도 한참 쉬어 좋았어요 재방문의사 있어요^^', 38, 9, 'GOOD', SYSTIMESTAMP);
