INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '합정카패 검색하다가 분위기 넘 아기자기하고 이쁜 곳 발견해서 방문했어요✨❤ 주문메뉴 : 얼그레이 케이크 & 초코 쿠키 & 엔초비 크로와상 & 카야 스콘 + 아아 얼그레이 케이크 캐릭터 보기에도 이뿐데 촉촉하고 맛있오요!! 얼그레이 잎(?)도 있어서 좀 더 풍미가 좋았어요 ㅎㅎ 카야잼 스콘은 버터랑 카야잼이 너무 조합이 좋아요! 버터는 역시 맛없을 수 없어여 ㅠㅜ ㅎㅎ 초코쿠키는 마시멜로가 쫀쫀하고 쿠키는 바삭한 편이에요! 마지막으로 대망의 엔초비 크로와상은 꼭 드셔봐야할 메뉴인데 주문 즉시 데워주시고 짭쪼름해서 짱 맛잇어요❤ (강추입니다) 분위기 좋고 맛도 좋은 합정, 홍대 카페로 추천 꾸욱 누르고 가용!!🥰', 14, 9, 'GOOD', SYSTIMESTAMP);
