INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '디저트들이 너무 귀야워요!! 인테리어도 홍대카페중에서도 젤 힙한 것 같아요!!! 다 너무 귀여워서 힐링하다옴🥹❤️ 해피베어데이 다른 지점도 많더라구요!!! 요기 케이크 징자 기엽구 맛남ㅎ', 21, 8, 'GOOD', SYSTIMESTAMP);
