INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '곰돌이쿠키~ 디저트류  그리고 케익 먹기 아까울 정도로 너무 귀여워요~ 크림도 많이 안달고 맛나요~ 동화속에 있는 것처럼 인테리어도 너무 귀엽네요~', 26, 7, 'GOOD', SYSTIMESTAMP);
