INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '디저트 진짜 너무 귀엽구용..😆 내부 인테리어와 외관..알록달록 너무 귀여워서 포토존 가득입니당💕💕 케이크도 얼그레이향 솔솔.. 콘 스콘 취향저격입니다!! 귀여움과 맛 모두있는 곳이에요', 123, 24, 'GOOD', SYSTIMESTAMP);
