INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '합정역 디저트 맛집 해피베어데이 가게 전체적으로 인테리어가 예뻤고, 디지니 노래가 들렸는데 분위기가 잘 어울렸다. 흑임자 스콘 : 흑임자 본연의 맛이 잘 느껴지는 고소한 스콘이었는데, 데코도 귀엽게 잘 되어있었다. 생크림 크루아상 : 크루아상이 굉장히 파삭하고 쫀쫀하게 반죽이 잘 되어있었고, 그 사이에 생크림이랑 바닐라크림이 잘 어울어져 맛있었다.', 74, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '알록달록 너무 이쁜카페인데 애견동반가능하고 주차도 가능해서 최고에요💖💖💖 주택 전체가 카페라서 규모도 크고 화장실도 내부에 있어서 좋았어요. 디저트들 종류도 어찌나 많은지 원래 마니 먹지도 않는데 3개나 주문했네요🤣 너무 먹음직스러워보이는게 많아서 ㅎㅎ 푸리 사진도 너무 잘나오고 자주올게요 !!!', 70, 11, 'GOOD', SYSTIMESTAMP);
