INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '해피베어데이~ 예쁜 디저트 보고 한번은 오고 싶었던 곳인데 역시나!!! 직접 와보니 매장이 정말 귀엽고 동화속 들어온거 같아 너무 행복했어용❤️ 아이스커피에 초코 오레오 케이크 달달하니 맛있게 먹고 왔답니당~~~~', 75, 16, 'GOOD', SYSTIMESTAMP);
