INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '귀여운 레터링 케이크를 주문할 수 있어요! 매장이 키치하고 귀엽고 버터 냄새가 가득합니다❤️ 이렇게 귀여운 케이크들은 녹거나 색이 번질까봐 생크림을 위에 안올리는 곳들이 많은데, 이곳은 생크림를 써서 너무 좋았어요!! 얼그레이 미니케이크 정말 맛있고 귀여워서 선물 받은 친구도 정말 좋아했어요🧸', 11, 8, 'GOOD', SYSTIMESTAMP);
