INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '이쁜 비주얼의 케이크집,,, 당일 홀케이크도 도시락케이크도 가능! 거기에 너무 귀여운 비주얼,,, 맛은 기본입니다! 그냥 비주얼 그자체에 쏙 혼이 나가버리는 곳이예요😳 급할때마다 애용합니다🫠🫠🫠🫠🫠', 52, 15, 'GOOD', SYSTIMESTAMP);
