INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '도심 속 동화나라에 들어온 것 같아요. 제가 마치 앨리스가 된 기분..!! 인테리어 맛집에 음료 맛집에 커피 맛집에 디저트 맛집입니다 쿠키 넘 맛있어서 포장해왔어용 완전 넘나 예뻐요', 74, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '시간은 촉박한 상태에서 이벤트를 해야하는 시점이였는데 우연히 알게되어 급하게 주문하고, 또 다시 급하게 레터링 변경까지 감사하게 해주셔서 너무나 좋았습니다. 힘든 신랑에게 서프라이즈 해주려고 정말 급하게 한거여서 너무나 만족했고 기분좋게 생일 축하파티 했습니다. 케이크도 맛있었고 변경된 레터링으로 신랑에게 깜짝 선물까지 해서 너무나 뜻깊은 생파를 하였습니다. 정말 오랜만에 기분좋고 재밌는 생파였습니다. 감사합니다^^', 3, 5, 'GOOD', SYSTIMESTAMP);
