INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '합정카페 찾으신다면! 해피베어데이로 가세요 :) 인테리어도 귀염뽀짝하고 음료도 맛있어요! 디저트는 말해뭐해ㅠ_ㅠ 귀엽고 당충전하기에 딱 조아요!!', 126, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '맛과 분위기,비쥬얼을 다갖춘 카페찾기가 쉽지않은데 이곳이 그곳입니다!!! 왜인기많은지 알겠어요ㅠ 알록달록 너무예쁜데 케이크 가격도 괜찮고 심지어...진짜맛있어요... 제가 근래다닌 카페통틀어서 젤맛있습니다... 근데 카페공간도 넓고 의자도편하고!!!!! 야외테라스도 해비칠때 가면 너~무 예뻐요 음료도 맛있었습니다!!! 그냥 불만족스러운게 하나도없는 카페였구요!!! 다른케이크 먹으러 재방문의사100%입니다!!! 자세한 리뷰는 요기! https://blog.naver.com/7347kjy/223060449868', 13, 1, 'GOOD', SYSTIMESTAMP);
