INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '매장 내부가 아기자기하고 깔끔해요. 디저트도 다 너무 예쁘고 귀여웠어요 ㅎㅎ 레터링 케이크도 구매할 수 있어 좋았습니다. 근데 하나 아쉬운 점은 마당이 뭔가 지저분한 느낌이 들어서 청소나 정돈이 필요해 보였어요! 매장 이용하는 사람들에겐 내부가 더 중요하지만 디테일이 약간 아쉽습니다.', 17, 3, 'GOOD', SYSTIMESTAMP);
