INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '도시락케이크 예약하고 테이크아웃했어요! 남자친구 생일이라 했는데, 가격도 괜찮고 맛도 있어서 남자친구도 좋아했어요 ㅎㅎ 카페가 곰에게 진심인 것 같았어요 ㅋㅋ 카페가 예쁘게 꾸며져있는데 핑크톤과 청록색톤 섞여서 사진찍어도 예쁘게 잘 나오더라구요 ㅎ 케이크 외에도 곰 쿠키류도 다양해서 먹어보고 싶었습니다 ㅋㅋ 2층으로 되어있어 공간도 넓고, 시끌벅적한 분위기도 아니라서 좋았습니다. 다음에도 케이크 주문할 일 있으면 재주문하고 싶네요 ㅎㅎ', 82, 14, 'GOOD', SYSTIMESTAMP);
