INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '곰돌쓰 모양의 쿠키와 슈가 있는데 크림을 더 좋아해서 슈로 주문- 크림이 댕많이 들어있고 맛도 선택할 수 있어서 고르는 재미가 쏠쏠 ⠀ 남구를 위해서 크림이 없는 식사대용 엔초비크루아상도 뇸뇸 햄,치즈가 들어간 크롸상은 1초컷으로 순삭해버려따ჱ̒ ｰ̀֊ｰ́ ) ⠀ 생일은 아니지만 귀여운 캐릭터와 HBD 레터링으로 기분 좋게 먹을 수 있는 케키!! 자칫 잘 못 먹으면 크림이 녹아서 버글거리는 느낌이 강한데 해피베어데이는 적당히 단단하고 시트랑 조합이 좋아서 맛있게 뇸뇸 할 수 있슴당!', 56, 13, 'GOOD', SYSTIMESTAMP);
