INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '너무 귀여워요! 하루전이라도 레터링 케이크를 주문할 수 있어서 너무 좋았어요! 덕분에 센스있는 사람됬습니당ㅋㅋ 다음에도 케이크사러 올께용', 75, 12, 'GOOD', SYSTIMESTAMP);
