INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '드디어 와봤습니다 합정최고핫플 해피베어데이😍😍 커피도 잘못마시지만 곰돌이 큐브를 위해서 아메리카노랑 라떼 시켜봤어요😆😆 너무귀엽죠진짜😭😭 케이크도 너무 다 귀여운데 힘들게 하나만 골라봣어요 노랑오리 너무귀엽죠🥹🥹 애가 아주 뚱한게 얼른 먹고싶어(?)🤣🤣 초코 오레오크림도 너무 부드럽고 케익자체로도 넘맛있어요❤️❤️ 쿠키도 진짜 너무귀여운게 맛도좋고 말차쿠키는 말차맛이 왜렇게 진한거에요대체😮😮 아주 쿠키맛집👍👍 슈도 진짜 반갈랏더니 크림이 꽉차서 아주 크림대폭발👏👏 다맛있고 공간도이쁘고 역시 홍대 카페 중 최고 핫플이에요🔥🔥', 15, 0, 'GOOD', SYSTIMESTAMP);
