INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '전체적으로 카페 분위기가 캐쥬얼하고 컬러풀해서 인상깊네요 !! ㅎㅎㅎ 독특한 인테리어라서, 컬러풀한 디저트들과 조화가 아주 좋습니다 ㅎㅎ 내부 좌석도 많고 아주 좋네요 ㅎㅎ 디저트도 쿠키랑 케이크 다 부드러우면서 막 달지 않아서 맛있러요 !', 76, 15, 'GOOD', SYSTIMESTAMP);
