INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '진짜 너무너무 귀여워요!! 디즈니 갬성 ✨ 귀염뽀짝한거 좋아하시면 여기 넘나 추천..! 디저트들이 다 넘 귀엽고 사랑스러워용! 게다가 맛도 있답니다 >__< 🤍 2층까지 좌석이 있어서 카페가 진짜 크고 넓어용! 콘센트도 곳곳에 많답니다 (っ’-‘)╮=͟͟͞͞♡', 12, 10, 'GOOD', SYSTIMESTAMP);
