INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '전부터 방문하고 싶었는데 남편과 아들과 같이 갔네요^^ 비온뒤 일요일이라 그랬는지 매장에 사람이 적어서 케익과 음료 맛을 즐겼어요~ 노키즈존일까 걱정했는데 아니여서 아들은 오레오 곰돌이와 구름소다 스무디 먹었네요~ 맛있다해서 일요일 오후를 즐겁게 마무리했어요❤️', 21, 10, 'GOOD', SYSTIMESTAMP);
