INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '선물용으로 돌릴 쿠키를 찾다가 방문했는데 제 기준으로는 가성비&비주얼&사진 맛집입니다!! 누가 받더라도 좋아할 예쁘고 특색 있는 디저트가 가득해서 편하기 선물을 고를 수 있었어요~ 초코스모어/레드벨벳 곰돌이 쿠키는 특색 있는 디자인이라 선물하기 더 좋았고 바닐라 크루아상/생크림 크루아상은 쿠키와 비슷한 가격이었는데, 개별 포장이 가능해 가성비까지 챙긴 느낌이었어요 쿠키 슈/카야 버터잼 스콘도 기본 이상으로 맛있어서 비주얼과 맛을 모두 챙긴 맛집이란 생각이 들었어요 평일 오후에 가니 매장에 좌석이 여유 있어서 대기 없이 바로 착석할 수 있었고 포장도 빠르게 진행되어서 더욱 만족스러웠어요 합정역에서 이동하면 10분 이내로 도착이라 대중교통으로 가기에도 딱 좋은 위치 같아요~', 38, 1, 'GOOD', SYSTIMESTAMP);
