INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '카페가 너무 귀여워요 !! 구름스무디랑 블루베리스무디 너무 맛있어요! 오래오 쿠키 귀염뽀짝해서 심쿵 ㅠㅠ 레몬 시트론 제 입맛에 딱이었습니당. 얼그레이 케이크도 얼그레이향 뿜뿜! 너무 예쁜 카페에서 좋은 추억 만들었어요! 추천합니당', 2, 2, 'GOOD', SYSTIMESTAMP);
