INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '카페가 동화 속에 들어온 듯한 아기자기한 동화 컨셉에 bgm도 디즈니 노래라 너무 좋았어요 🥰 아메리카노에 블럭 추가해서 마셨는데 더 진하게 마시고 귀여워서 좋았어요. 쿠키랑 스콘도 달달해서 존맛탱 ☺️ 단호박도 꾸덕하고 맛있더라고요 홍대 디저트맛집으로 강추에요 💕', 107, 22, 'GOOD', SYSTIMESTAMP);
