INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '카페도 너무 이쁘고 제작 부탁드렸던 케이크 너무맘에 들었어요. 주문할때 관계자분께서 안내도 엄청 친절하게 해주셔서 잘 주문할수 있었어요. 감사합니다.', 0, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), 'https://blog.naver.com/yuna_hobin/222986911478 케이크 정말 안 좋아하는데... 해피베어데이 케이크 먹고 반했어요😍 너무 맛있듐😍❤️ 데이트로 오거나 여자들끼리 오기에 좋은 카페🫶🏻', 85, 12, 'GOOD', SYSTIMESTAMP);
