INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '케이크 정말 아기자기하고 귀엽고 예뻤어요! 맛도 무진장 맛있었구요👍 덕분에 친구 생일 행복하게 보냈습니다! 제가 주문하면서 원하는 문구를 누락했었데 ㅠㅠ 친절히 연락까지 해주시고 잘 대처해주셔서 너무 감사했어요!!', 45, 6, 'GOOD', SYSTIMESTAMP);
