INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '홍대 해피베어데이 너무 좋아하는곳인데요 이렇게 예쁜곰쿠키가또 얼마나 맛있는지 아시나요? 너무 취향저격 카페라서 모르는사람이없음 좋겠구요 곰쿠키 넘 사랑해 💚 💕 😍 😘 💗', 121, 26, 'GOOD', SYSTIMESTAMP);
