INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '이만한게 18,000원(+초2000원)이라니… 높이도 되게 낮아요 카페는 귀엽고 직원분도 친절하셨는데 결제를 해놔서 그렇지 가격 알았음 안 샀을 갓 같아요 조각케익 눌러서 동그랗게 해놓은 정도의 크기입니다 맛은 있어요 장점은 급하게 사려고 할 때 좋아요 미리 찾아보시고 사세용', 116, 20, 'BAD', SYSTIMESTAMP);
