INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '동화속에 놀러온듯한 분위기에 저도 모르게 신이났네요. 디저트는 곰돌이 모양부터 알록달록 장난감같은 케이크까지 정말 귀여웠어요. 모양도 귀여운데 맛있기까지해서 행복한 시간을 보냈네요!!', 94, 22, 'GOOD', SYSTIMESTAMP);
