INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '스콘은 바삭바삭 씹히고 카야쨈이랑 버터가 잘 어울렸어요. 바스크 치즈케익은 꾸덕하진 않아서 한입먹으면 부드럽게 넘어가서 좋았어요 얼그레인 케이크는 그냥 한마디로 얼그레이 그자체였어요 디저트 맛집!♡', 120, 24, 'GOOD', SYSTIMESTAMP);
