INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '근처 방문했다가 케이크가게 검색해서 찾아왔는데 아기자기하고 너무 귀여워요! 귀여운 곰돌이 쿠키랑 케이크뿐만 아니라, 소품들마저 너무 귀여워서 구경하는 재미가 있어요☺️', 28, 0, 'GOOD', SYSTIMESTAMP);
