INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '오레오케이크(병아리)는 맛있는데 레드벨벳케이크(개구리)는 너무 맛이 없어요. 인테리어는 정말 예뻐요. 사진이 너무 잘나오고 매장도 넓어서 한적해요. 근데 색소를 너무 많이 넣은건지 먹으면 입이 퍼래져서…;;; 먹는내내 친구랑 웃었어요. 다먹고도 입술에 퍼렇게 착색돼서 마스크도 못벗었어요ㅋ… 직원분들 친절하진 않아요.', 100, 26, 'BAD', SYSTIMESTAMP);
