INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '생일 케이크 픽업하러 갔었는데, 인테리어에 반해 매장이용도 했네요. 외관도, 안에도 애니메이션에 들어와 있는 기분이네요😀 오레오 초코케이크 꼭 드셔보세요, 너무 맛있어요💜', 13, 3, 'GOOD', SYSTIMESTAMP);
