INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '딱히 두번 방문은 안할것 같습니다. 버터크림케이크, 쿠키 모두 느글느글하고 맛이 평범해요. 이런 맛이라면 굳이 여기까지 와서 살 필욘 없었을 것 같고. 주문한 케이크 중간에 크림이 떨어져나갔는데 죄송하단말없이 파티쉐없다고 수정불가하다는 것도 좀 이해 안갔고요. 디자인은 귀여우니 뭐..', 39, 0, 'BAD', SYSTIMESTAMP);
