INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '이뻐요 컨셉이 귀여워서 소녀감성 있으신분들 좋아하실꺼 같아요 케잌은 오레오초코는 진짜 맛있었는데 레드벨벳은 아쉬웠어요 ㅠㅠ 그리고 일인일조각케잌 하니깐 나중엔 넘달고느끼해서 힘겹 ㅋㅋㅋ외국인들이 많이 와서 사진찍고 가시더라구요~', 33, 0, 'GOOD', SYSTIMESTAMP);
