INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '생크림2호 (지름18cm) 로 예약주문했어요! 네이버 예약주문 할 때도 디테일한 메뉴 설명이 있으면 좋겠습니다. 이런 데코케익 증말 맛 별로던데, 무난하고 부드럽게 잘 먹혔습니다! 기본초 미제공/ 숫자초는 없고, 장식초만 매장에서 구매할 수 있는데 개당 2,000원은 넘넘 비싼 것 같네요ㅠ', 77, 18, NULL, SYSTIMESTAMP);
