INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '커피도 맛있었고 디저트가 예쁘면 모습에 비해(?) 맛은 그저그런곳이 많던데 해피베어데이는 케이크도 촉촉하고 진짜 맛있었어용!😋 그리고 컵이 너무 귀여워서 따로 판매하면 사고 싶었어요 ㅋㅋㅋ 아무튼.. 여기 카페 진짜 귀엽고 맛있고 다함..ᵒ̴̶̷̥́ ·̫ ᵒ̴̶̷̣̥̀', 99, 25, 'GOOD', SYSTIMESTAMP);
