INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '귀여운 케이크가 필요해서 주문했는데, 생각 이상으로 너무 예쁘게 꾸며주셔서 감사했습니다! 도시락 케이크는 처음 먹어보았는데 맛있었습니다! 그리고 장소를 잘못체크해놔서 예약시간보다 늦게 가도될지 양해구했는데 친절하게 응대해주셔서도 감사했어요!! 앞으로 케이크 주문할땐 늘 여기서 예약주문할것같아요! 맛있게 잘먹었습니다^^', 487, 67, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '케이크가 너무예뻐서 아이부터 어른들까지 좋아하실것같아요. 맛은 보지못해서 모르지만 너무귀여워서 만족입니다. 케이크 바닥에 고정핀이 없어서 조심히들고 가라고 하셨으니 구매하시는 분들 참고하세요.', 0, 5, 'GOOD', SYSTIMESTAMP);
