INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '와이프 생일이라 미리 예약하려고 네이버로 결제 했는데, 픽업 당일 사정이 있어 결제 카드 변경하려 했더니 안된다고 해서 정말 어이가 털리긴했는데, 실랑이 하기 귀찮기도 하고 직원분 말도 안통할거 같아서 그냥 나왔어요. 케이크는 귀여워서 선물해주니 엄청 좋아하더라구요', 38, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '어머니 퇴사 기념으로 미니 케이크 했습니다! 맛도 좋고 너무 귀여웠어요ㅠㅠ 하나 아쉬운 점은 중간에 마무리가 좀 덜 되어있어서 아쉬웠습니다 그 부분빼고 모두 다 좋았어요~ 크기는 그리 크지 않습니당 ㅎㅎ', 12, 2, NULL, SYSTIMESTAMP);
