INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '아기자기한 공간도 많고 케이크나 쿠키가 너무 귀여워요 :) 특별한 날 한번씩 레터링 케이크 맞춰서 선물하기 너무 좋고 만족해요♡', 78, 16, 'GOOD', SYSTIMESTAMP);
