INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '해피베어데이 꼭 가고싶어서 찜해뒀다가, 마침 근처 갈 일이 생겨 방문했어요! 주말 이른 오전에 방문해서, 다행히 주차도 수월히 했습니다. 일단 알록달록 색감 덕분에 카페 입구에 들어서면서부터 기분이가 좋아지고, 귀여운 디저트를 보면 또 기분이 좋아지는 곳이었어요😁 디저트가 너무 귀여워서 사실 맛은 기대 안했는데, 먹어보니 너무 맛있더라구요!!! 제가 먹으려했던 레드벨벳치즈케이크 저희 아이가 거의다 먹어버렸어요...😅 라떼에 달달한 디저트의 조합이 좋았습니다!!! 기회가 된다면 또또 방문하고 싶은 곳이에요^^', 3, 5, 'GOOD', SYSTIMESTAMP);
