INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '지난번 친구생일에는 롯데본점에서 보고 구매했었는데 맛도 모양도 난리가 났었더랬죠. 이번에 다른 친구 생일엔 레터링까지 하려고 미리 예약주문했는데 이번에도 난리가 났습니다ㅋㅋㅋ생일주인공은 역시 케이크죠!!!ㅋㅋㅋㅋ 다음에 또 주문하겠습니다. 번창하세요🍀', 0, 9, 'GOOD', SYSTIMESTAMP);
