INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '7시20분쯤 픽업 했고 집에도착하니 3분의1은 녹아서 내려앉았습니다 돈의값어치를 떠나서 디자인때문에 주문한건데 보냉팩도없었고 보냉팩 추가하기도 없었던것같아요 해년마자 수많은 케이크를 사봤지만 이렇게 망가진건 처음입니다 다른주분케익들은 보냉팩이든 망가지지않게 최대한으로 노력하는게보이는데 여기는 조금 아쉽네됴 가족들 잔뜩 기대하고있다가 실망만하고 질책만받았네요 혹여망가질까 조심조심 가져왔는데 속상합니다 저도 가게를 하는 사람으로서 앞으로 이부분에대한 개선책이필요할것같습니다', 28, 4, 'BAD', SYSTIMESTAMP);
