INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '브샤용 케이크 주문했는데 너무 예쁘고 귀염뽀짝해서 친구가 넘넘 맘에들어 했어요ㅎㅎ 실제로 보면 더 귀여워요 ㅠㅠ💜💜 먹기아까움 ㅠ 캐릭터 앞에 케이크 있는거 킬포....귀여움 그잡채.....💜 하트초나 포인트 초 꼭 사서 꽂아주세요ㅎㅎ', 43, 5, 'GOOD', SYSTIMESTAMP);
