INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '만든지 좀 됐는지... 색소는 다 번졌고 맛도 영 아니어서 크리스마스에 부모님께서도 실망하셨어요... ㅎㅎ 예시 이미지랑 생긴 게 너무 달라서 당황했었네요 저는 다시는 안 갈 것 같아요...', 30, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '케이크가 너무 색감이 예쁘고 토끼 디자인이 있어서 토끼띠 아기 임밍아웃할때 썼어요!! 시부모님도 케이크 너무 예쁘다고 좋아하시고 맛도좋아서 좋은시간 보냈답니다👍🏻👍🏻', 14, 3, 'GOOD', SYSTIMESTAMP);
