INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '인테리어가 키치하고 카페 음료랑 디저트가 귀여워요 모양뿐만 아니라 맛도 있고 자리도 많아서 잘 쉬다 왔습니다 카라멜 바스크 치즈 케잌 맛있어요!', 40, 5, 'GOOD', SYSTIMESTAMP);
