INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '컨셉이 무지막지하게 귀여운 카페에요! 건물 들어설 때부터 알록달록 귀염뽀짝하고 SNS 하시는 분들이 많이 오실 것 같은 느낌..? 디저트가 화려해서 맛은 솔직히 기대 안했는데 생각보다 맛있네요?! 다른 디저트 먹으러 한번쯤 더 가볼 것 같아요ㅎㅎㅎ 다시 봐도 귀여움ㅠ', 31, 10, 'GOOD', SYSTIMESTAMP);
