INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '가게 외관부터 너무 귀여운데 안에 인테리어도 너무 귀여웠어요! 테디베어성에 놀러온기분!😆 쿠키가 너무 귀여워서 하나씩 다 사와서 먹었는데 보는데 넘 귀엽❤️ 맛도 맛있었어요😋👍🏻', 43, 8, 'GOOD', SYSTIMESTAMP);
