INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '사람이 많은 편이라 살짝 정신 없지만~ 개구리(레드벨벳) 케이크가 너무 귀여웠어요🐸 크림치즈와 생크림이 만나 사실 느끼해서 다 못먹었지만 개구리가 너무 귀여웠어요..🐸🐸 마카다미아 말차 쿠키는 쏘쏘! 엄청 바삭거나 촉촉한 편 아니고 스콘 같아요. 크림 캔다 소다랑 딸기라떼는 아는 맛입니다! 귀여움을 곁들인..', 15, 9, 'GOOD', SYSTIMESTAMP);
