INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '요청사항 그대로 만들어 주셨고 30분 빨리 갔는데도 바로 찾을 수 있었어요! 받기 전에 레터링 확인하고 포장해주셨고 조금 비싼감이 있지만 선물용으로 좋은 것 같습니다 ㅎㅎ', 0, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '카페 너무 예쁘고 귀엽고 무엇보다 케이크가 너무 맛있어요 미쳤어요 ㅠㅠ 데코가 메인인 케이크인 줄 알았는데 맛이 찐이에요! 크림맛이 예상을 벗어나는 감동그자체의 맛 ㅠㅠ 초코오레오케이크 꼭드세요 두번드세요헝허엉', 37, 5, 'GOOD', SYSTIMESTAMP);
