INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '외관부터 내부 디자인, 식기들, 디저트까지 눈이 매우 즐거운 시간이었습니다~ 입에 넣자마자 녹아 없어지는 엔쵸비 크루와상과 아메리카노의 조합이 감격스러웠어요 ! 다른 디저트들도 먹으러 또 방문할게요  ◡̈', 2, 9, 'GOOD', SYSTIMESTAMP);
