INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '케이크 예쁘고 쿠키들도 예뻐서 선물하기 좋아요 다만 케이크 포장할 때 포장상자보다 밑에 케잌 받침이 너무 작아서 조심히 들고갔는데도 글씨써진 부분이 다 망가졌어요', 34, 4, NULL, SYSTIMESTAMP);
