INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '전날 바로 예약되고 회사근처라 픽업편하고 좋았는데 색깔이 잘못됐어요.. 보여주시면서 확인하라고하셔서 분홍이길래 제가 분홍예약했나요? 파랑이엿던거같은데 하니까 여자알바분이 확신의 ''분홍하셨어요~'' 해서 바로 약속시간이고 급해서 그냥 나갔는데 가는길에 네이버 예약 확인하니 파랑으로 예약한거 맞더라구요. 혹시 남의 케이크일까 좀 쌔해서 나가서 이름확인했는데 멘트는 제대로 되어있었고 가게측에서 색상혼동하셨더라구요~ 뭐 별도로 주문제작도 아니고 색상별 디자인도 크게 다른건 아니지만.. 그냥 좀더 세심하게 확인해주셨으면 좋았을텐뎅 아쉬워요. 그래도 케이크는 귀엽고 축하는 잘 해줬어요~', 67, 12, NULL, SYSTIMESTAMP);
