INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '잠실 롯데백화점에 해피베어데이가 생겼더라구요! 영수증 주소는 아직 마포구로 나오네요. 무튼 귀염뽀짝한 케이크 팔고 맛있는 까눌레도 팔아요 :) 까눌레 맛집이 많지 않은데 하나 발견해서 좋네요.', 71, 14, 'GOOD', SYSTIMESTAMP);
