INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '2년전에 제작케이크로 했었는데 그 사이에 사업규모가 엄청 커졌네요ㅋㅋ 예약하기 편해져서 너무 좋아요~~ 디자인도 맛도 만족해요', 24, 1, 'GOOD', SYSTIMESTAMP);
