INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '케이크 예쁘긴한데ㅠㅠ 블루베리케이크 예약했는데 얼그레이였고,,디자인도 사진이랑 달랐어요,,,생일자가 얼그레이 안먹어서 일부러 다른걸로 시킨건데ㅜ케이크 픽업 때 제가 블루베리케이크라고 말씀드렸을때 한참 찾으시던데 잘못된거 인지하셨음에도 불구하고 그냥 주신거 같더라구요 다음부턴 주의 부탁드리고 실수인지하셨으면 그냥 차라리 솔직하게 말하고 사과하시는게 나을 것 같네요 생일 제대로 못 축하해준거 같아 속상해서 남깁니다…', 19, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '결론 :: 직원❌, 음료❌, 디저트⭕️, 인테리어🔺 디즈니 노래도 종종 흘러나와 분위기와 어울렸지만 스피커가 안좋은지 음질이 별로여서 듣기에 좋진 않았어요. 딸기에이드에서 플라스틱 맛이 나 이상하길래 얘기드리고 음료 다시 받으니 전것보다는 나았지만 여전히 플라스틱+신선하지 않은 딸기맛은 여전했어요. 신선한 딸기보다는 물러져가는 딸기를 쓴 느낌...메론소다는 쏘쏘했어요. 디저트로 시킨 케이크는 귀여운 모양 뿐아니라 맛까지 좋아서 기대이상이었어요. 케이크만 먹거나 테이크아웃 추천 :) 인테리어는 생각보단 아기자기한 느낌이 덜했고, 내부보다 외부가 더 인상적이었어요. 직원분들 얘기하시는 소리 너무 시끄러워요. 몇없는 손님 소리보다 더 시끄러워서 인상이 찌푸려지더라구요. 여러모로..케이크 빼곤 아쉽네요☹️', 29, 4, NULL, SYSTIMESTAMP);
