INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '옥수수 스콘, 카야 버터잼스콘 주문했습니다 옥수수 스콘은 옥수수크림에 구운 옥수수가올라간 일반적인 스콘이었어요 카야버터잼 스콘은 버터링과자 맛이 나는 스콘에 고소한 버터, 달콤한 카야잼의 조합이 잘어울렸어요 적당히 맛 좋았어요.', 77, 13, 'GOOD', SYSTIMESTAMP);
