INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '케이크 색깔이 너무 쨍해서 먹기 부담스러웠는데 먹어보니 많이 안 달고 너무 맛있게 잘 먹었어요~!! 다음에 또 방문할것같아요^^ 다만 스피커 음질이 안 좋은건지 음악음질이 안 좋은건지.. 대화하면서 지지직 거리는 소음이 듣기 거슬렸어요ㅠ 음악을 좀 선명하게 틀어주세요....', 109, 25, 'GOOD', SYSTIMESTAMP);
