INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '카페 자체가 귀엽고 예뻐서 들어갈 때 기분이 좋습니다. 음료는 그냥 그런 것 같고 디저트는 귀엽고 맛있어요. 루프탑이랑 야외에도 귀엽게 꾸며놓아서 사진 찍기 딱이었습니다. 화장실도 깨끗하고 매장도 깨끗해서 더 좋아요!', 49, 10, 'GOOD', SYSTIMESTAMP);
