INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '친구 생일이라 급하게 주문제작 케이크 찾다가 여기서 도시락 케이크 했는데 기대이상으로 너무너무 예뻤어요ㅠㅠ 직원분도 너무 친절하셔서 기분 좋게 방문했습니다!!', 211, 33, 'GOOD', SYSTIMESTAMP);
