INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '카페 외관부터 공간 곳곳의 인테리어가 너무너무 예쁩니다!! 케이크도 예쁘고 다음에 또오고 싶어용 비쥐엠도 디즈니에 동화속에 들어온거 같이 좋았습니다 매장이 따뜻하고 직원분들도 친절하시고 추운날씨에 힐링하고 갔습니다 다음에 친구나 가족도 델꼬오고 싶은곳 입니다', 27, 2, 'GOOD', SYSTIMESTAMP);
