INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '레몬에이드도 너무 맛있고 케이크도 진하고 겉에크림도 맛있었어요!! 인테리어랑 포크, 빨대, 접시 벽지 등 다 나무 아기자기하고 디즈니 음악만 틀어주는 디테일도 넘 좋았어요💗', 1, 0, 'GOOD', SYSTIMESTAMP);
