INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '포토존도 많고 넓고 쾌적하고 조용하고 일회용 흑백종이사진기도 있고 케이크에 불 켜도 돼서 좋았음! 촛불 따로 구매한거지만 넘나 기엽 🌼 디저트들은 덮개(투명 돔형)를 씌워두면 더 위생적이고 좋을듯', 80, 13, 'GOOD', SYSTIMESTAMP);
