INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '디저트가 넘 귀여운 가게...♡ 맛은 무난하게 좋았어요! 케이크 평이 그럭저럭이라 좀 걱정했는데 크림이 많아서 느끼한거 잘 못먹는 사람은 쪼꼼 빨리 물릴 것 같은거 빼면 보는 것도 좋고 맛도 있었어요😋 포장은 따로 고정해주시는게 없이 그냥 종이상자에 담아주셔서 들고 갈 때 크림 안뭉개지게 조심하셔야 해용 !! 갠적으로 케이크는 매장에서 먹는게 좋을 것 같아요♡', 34, 2, 'GOOD', SYSTIMESTAMP);
