INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '우선 카페 분위기가 대박이에요 너무 좋고, 사장님께서 엄청 친절하셔서 부담스럽지 않고 너무 좋았어요ㅎㅎ 그리고 음료수도 엄청 맛있었어요.!! 자주 올꺼에요 아 무엇보다 방역도 철저해서 요즘같은 시국에 가기 좋아요~~', 109, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '사진에 나와있는데로에요ㅠㅠ 진짜 예쁘고 색감도 짱짱입니다... 안에 인테리어도 좋아요!! 한창 붐빌 때 가서 사람이 정말정말 많았네요ㅠㅠㅠ 케이크는 그냥 설탕 맛일줄 알았는데 레드벨벳이였고 진짜 너무 맛있어요..😭 사진찍기도 진짜 예쁘고 안에 샹들리에도 예쁘고 인테리어랑 맛 둘 다 너무 좋은 것 같아요!! 다음에 서울가면 꼭 다시 가고싶은ㅠㅠ', 40, 6, 'GOOD', SYSTIMESTAMP);
