INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '카페 진짜 너무너무 귀엽고 인테리어 이쁘지 디저트 이쁘지 심지어 맛있지... 이런후기 남기지 않고 나만 알고 싶을 정도로 만족스러웠어요. 이쁜 디저트는 맛이없다는 편견을 깨는 곳이에요. 귀여운 케익들 다 촉촉하니 맛있고, 특히 크림소다(메론소다) 너무 맛있었어요. 야태껏 한국에서 먹어본 곳중 제일이에요! 근데 시럽을 너무 많이 넣으셔서 마지막엔 시럽+아이스크림 때문에 달고 느끼해서 좀 남기게 되긴 해요😂 그래도 맛있음...', 10, 10, 'GOOD', SYSTIMESTAMP);
