INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '완전 핫플  가봐야지 하며 계획만 세우다가 드디어 절친이랑 방문했어요 !! 사진에서 보던거보다 더 귀엽고 예뻐요 소품들도 완전 제취향 입니다 ! 사진 오만장 찍었어요 ㅋㅋㅋㅋ 완전 비비드컬러인 음료와 케이크도 잘 막고 가요 사진맛집 분위기맛집 달큰한 디저트도 완전 취저', 3, 5, 'GOOD', SYSTIMESTAMP);
