INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '매장 외관부터 완전 제 스타일이에요 마치 유니콘이 있을것만같은 아기자기함에 들어가기도 전에 반해버렸어요 ㅠㅠ 체고체고 !! 진심 입구 들어가는 순간 미쵸따 외치면서 많이도 담았습니다 사실 너무 예뻐서 맛은 크게 기대 안했는데 졸마탱 ㅜㅜㅜ 완전 반했어요 나중에 친구들이랑 한번 더 오려구요 진짜 꼭 가세요 두번가세요 ! 계속 가세요 제발', 12, 10, 'GOOD', SYSTIMESTAMP);
