INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '너무 예뻐서 홀딱 반했습니다~^^♡  향긋한 커피와 아기자기한 예쁜 케이크를 먹으니  오늘 하루 피로가 싹 풀리는듯 해요!!!  친구한테 사진 보내주니 다음주에 꼭 같이 오자네요 ㅎㅎ', 66, 14, 'GOOD', SYSTIMESTAMP);
