INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '매장 안에 처음 들어갔을때 인형의집같이 되어있어서 완전 놀랐어요. 인테리어 소품이나 테이블 의자들도 너무 잘어울리는 제품이라 먹기전부터 기분 좋았습니다 . 디저트들도 아기자기하고 음료랑 디저트 모두 맛있게 먹었어요 ㅎ 다음이 날이 풀리면 야외에서 먹어야겠네요', 106, 23, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '두번째 방문이에요! 조금 늦은 오후에 방문해서 그런지 사람이 너무 많아서 바글바글했어요. 거의 만석이었고 테이블 정리가 안 된데다가, 아크릴판은 다 깨진채로 바락에 테이블에 굴러다니고... 직원분은 두 분인데 주문은 밀려있고, 급해서 그런지 플라스틱포크로 주시고 케익은 크림이 다 밀려난채 받았습니다. 🥲 (이게 제일 슬픔... 귀여워서 먹는 케익인데 크림이 뭉개져있었어요) 이 넓은 매장에 사람이 꽉 찼는데 직원이 둘... 조금 더 관리가 필요할 것 같아요. 인테리어가 이쁘고 디저트도 맛있어서 재방문했지만 이번엔 너무 도떼기시장같았어요. 조금 더 관리가 필요할 듯 싶어요.', 23, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '아기자기하고 귀엽고 깜찍하고 다하네요♡ 너무너무 기분이 좋아지는 곳 디저트랑 음료도 다 맛있어서 너무 좋아용~ 사진도 완전 이쁘게 나오고 최고 bb', 43, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '카페 너무 이쁜데 심지어 귀엽고 맛있기 까지 해욤; 안들르면 두고두고 후회하실 거예요 꼭 한번 들려보시길 추천드려요 많이 안시끄럽고 사진찍기도 좋아요ㅎㅎ 사장님까지 친절해서 넘 좋음ㅜㅜ', 130, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '아메리카노랑 꿀밤 크로아상, 레드벨벳 케이크 시켜서 먹었는데 비주얼부터 맛까지 완벽했어요! 특히 크로아상 진짜 속이 부드러워서 또 생각나네요,, 카페 내부가 정말 잘 꾸며져 있어서 음식 사진도 잘 나와요~~', 7, 7, 'GOOD', SYSTIMESTAMP);
