INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '처음에 인테리어가 너무 예뻐서 들어가게 되었는데 커피나 디저트 종류도 너무 많고 굉장히 맛있게 잘 먹었습니다!! 특히 여기서 찍은 사진이 너무 잘 나와서 기분이 좋네요 ㅎㅎㅎ 다음에 또 오겠습니다', 4, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '양화쪽 돌다가 목이 말라서 들렷습니다.저희는 딸기 스무디랑 말차라떼 마셧는데 딸기 스무디는 다른 가게처럼 엄청달지는 않고 딸기맛이 잘나서 생과일 주스맛입니다.말차는 부드럽고 맛있어요.한번 들려보시는거 추천드립니다.', 30, 10, 'GOOD', SYSTIMESTAMP);
