INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 합정 본점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '초코 오레오 너무 맛있어요. 인테리어가 컬러풀하고 너무 귀여워서 일부러 찾아서 방문했어요. 포토존도 많이 있고 비누방울 쏘면서 인생샷도 건질수 있습니다. 디저트도 다양하고 맛있어요!!', 76, 12, 'GOOD', SYSTIMESTAMP);
