INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '디저트도 맛있고, 커피도 맛있고 분위기도 좋고 아주 매력이 많은 카페입니다!! 합정동 사는데 자주 찾는 카페라 하면 단연 <지튼> 입니다🩷 부모님 모시고도 자주 오고 데이트하러도 와요~ 공간이 넓지는 않지만 테이블이 6테이블, 바테이블 2개 정도 되어서 꽤 앉을 공간이 있어요. 무엇보다 카페가 꽉 차있어도 울리지 않고 노래도 적당하고 분위기 너무 좋아요><💕 오래오래 맛있는 커피 내려주세요 사장님😝❤️ + 직원분들도 항상 친절하세요 ㅎㅎ💓', 25, 10, 'GOOD', SYSTIMESTAMP);
