INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '주문하면 그라인딩해서 추출해주는 커피 맛이 일품! 디카페인 주문했는데 너무 괜찮아요~ 그리고 까눌레 맛집이라던데. 갠취로 에그타르트 주문했고요. 역시 맛있다는! 매장이 갈끔하고 조용해 머무르기 좋고요. 테이크아웃 할인도 있으니 참고하세요!!', 29, 7, 'GOOD', SYSTIMESTAMP);
