INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '카페에 들어서자마자 고소한 냄새에 이끌려서 바로 에그타르트 주문했습니다🐣 갓 나온 디저트라 너무 맛있고 따수웠어요☺️ 커피는 원두 종류를 고를 수는 없었는데, 기본으로 나오는 커피 맛이 아주 좋습니다 !! 쌉싸름하면서 끝에는 가벼운 산미가 있어요👍 분위기 좋고 조용하고 깔끔해서 기회가 되면 재방문 하고 싶어용', 37, 6, 'GOOD', SYSTIMESTAMP);
