INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '합정역과 가까워 접근성이 좋은 카페입니다 :) 카페 내부는 깔끔하고, 혼자 방문하기에도 좋습니다~ 에그타르트를 먹기 위해 왔는데 케이크, 쿠키, 까눌레 등 다른 종류의 디저트들도 다양했어요! 취향에 맞는 원두로 커피를 골라 마실 수 있고, 디카페인도 있었습니다~ 에그타르트의 필링이 풍성하고 부드러워요! 바삭바삭 맛있게 먹었어요 💛', 86, 15, 'GOOD', SYSTIMESTAMP);
