INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '지나가다 우연히 발견한 카페인데 분위기도 너무 좋고 내부도 깔끔해서 기분좋게 쉬다 갑니다!! 까눌레가 너무너무 맛잇어요~~ 말차 까눌레는 위에만 있는줄 알았는데 안쪽도 크림이더라구요 진짜 왕추천', 2, 9, 'GOOD', SYSTIMESTAMP);
