INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '합정 지튼 ZTTN은 골목 주택을 블랙앤 화이트로 인테리어한 단정하고 편안하게 커피맛을 즐길 수 있게 배려해주는 곳이다 케냐 키린야가 카리루 AA워시드라는 조금 어려운 이름의 커피를 시켰다. 소개글처럼 밝을 산미와 감칠맛을 느낄수 있었다 마시는 동안 정말 기분좋아지는 커피맛이 입안에 계속 남아있다. 커피를 모르는 나도 이 맛을 또 느끼고싶어 다시 오고싶게 한다 양쪽 벽면의 낙서같은 어트 와이언의 작품이 이곳에 의미를 부여해주고 있었다 Make it right and different 짙은 커피, 짙은베이커리 and 짙은 공간 바다는 지튼의 언어가 될거야 이 기록은 윤슬을 타고 흐를거야 우리는 바다로 사랑을 빚어내 Coffee is Energy 감정의 기록들은 수면 깊이 나만의 바다를 이루겠지', 62, 16, 'GOOD', SYSTIMESTAMP);
