INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '지튼 드디어 와봤네요 1인 1메뉴 주문이구요 주차장이 커서 차가지고 올때 추천이요 인절미갸또 케이크가 특별한 맛이라 아껴먹은 건 안비밀 까눌레도 겉은 아주 쫀득쫀득해서 매력있어요', 37, 3, 'GOOD', SYSTIMESTAMP);
