INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '합정역 근처 카페 지튼 방문했어요!! 공간이 깔끔하고 아늑해서 분위기 좋아요😊 쿠키, 타르트, 케이크 등 맛있는 디저트도 많이 준비되어 있네요!! 오픈하자마자 방문해서 오전에 구운 따뜻한 에그타르트 맛볼 수 있었어요~ 바삭한 타르트와 부들부들 필링이 증말 맛있어요♥️ 커피도 정말 맛있네요!! 까눌레 종류가 굉장히 다양한데요~~ 다음 방문때 까눌레 맛보러 들러야 겠어요😊 합정역 카페 지튼 추천이에요👏🏻👍🏻', 22, 5, 'GOOD', SYSTIMESTAMP);
