INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '오랜만에 지튼 :) 오늘따라 왜그리 상냥하신지요..💕ㅎㅎ 기분 좋게 포장해서 맛있게 먹었습니댜 스벅보다 1.5배 정도 진한 플랫화이트를 맛 볼 수 있는 곳! 에그타르트는 말모 >.<', 96, 20, 'GOOD', SYSTIMESTAMP);
