INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '까눌레 먹고싶어서 찾아보다가 맛있어보여서 방문했어용 차가지고 가서 주차할수있는곳 찾고있었는데 건물 뒤에 바로 주차장있어서 편했습니다! 커피도 위에 크림이 많이 달지 않고 까눌레도 바삭바삭해서 맛있었습니당', 81, 18, 'GOOD', SYSTIMESTAMP);
