INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '합정에 혼자 나들이 갔다가 멋져보여서 방문했어요! 저녁 대체할겸 디저트 이것저것 시켜봤는데, 디저트도 맛있고 커피도 너무 맛있어요 …!!🥹 까눌레 엄청 좋아하는데 파는 곳이 생각보다 별로 없어서 슬펐는데 드디어 까눌레 맛집을 찾았습니다 !!! 케이크도 인절미 향 퐉 느껴지고 👍🏻 커피는 갓파더라는 메뉴인데 주문하니 크림을 바로 쳐주시더라구요. 크림도 진짜 맛있어요😻 인생샷 찍기에도 좋아보이는데 다음엔 꼭 일행 데리고 와야쥐', 17, 0, 'GOOD', SYSTIMESTAMP);
