INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '세련되고 모던한 분위기의 카페에요☕ 매장에서 직접 디저트를 만들기 때문에 고소한 냄새가 계속 풍겨서 좋아요😆 실내를 살짝 어둡게 해서 아늑하고 편안한 느낌을 줍니다. 테이블 간격도 넓어서 일행과 이야기 나누기도 쪼아용👍 제가 있을때는 데이트 하는 커플들이 많았고 혼자 시간을 보내는 사람들도 보였어요🖱️ 카페에서 보통 조각 케이크를 많이 취급하고 갸또는 좀 드문 편인데 황치즈, 인절미, 초코 갸또가 있더라고요🍰 꾸덕, 부드럽고, 특히 초코 갸또는  맛이 정말 진했어요🍫 서울 한복판에 있는 카페인데 주차도 가능하고‼️ 합정역에서도 가까워서 약속 장소로도 둣뜨😁 매장 조명이 눈부시도록 밝거나 통창에 커튼, 썬팅 아무것도 안 해서 눈부신👀 그런 공간을 안 좋아한다면 더더욱 지튼을 추천합니다👍', 11, 3, 'GOOD', SYSTIMESTAMP);
