INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '합정역 카페라는 키워드로 검색을 하니 지튼이 많이 나오더라구여. 물론 블로그체험단 글도 있어서 망설여지기는 했지만 그래도 뭔가 괜찮아보여서 친구와 방문했어요. 비오는 일요일에 갔는데요 운이 좋아서 웨이팅은 안했지만 생각보다 내부에 테이블이 많지 않아서 그냥 가는 사람들, 웨이팅 하는 사람들도 꽤 많았어요. 에그타르트는 특별하지는 않고 그냥 무난하게 맛있었어요. 까눌레는 항상 먹을 때마다 내가 왜 주문했을까라는 생각이 드는 디저트인데 역시나 지튼 까눌레도 제 입에는 안 맞았어요. 스모어쿠키는 많이 달아요. 나이 먹어서 너무 단 거는 또 잘 못먹겠더라구요. 근데 지튼, 아메리카노가 진짜 맛있어요. 와..!!!! 원두 밸러스 굿굿굿. 너무 맛있어서 한잔 더 주문했습니다. 커피 맛집이었어요.', 20, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '여기 진짜 디카페인 맛집이에요ㅠㅠㅠ 꾸준히 다니는 몇 안되는 카페인데 디카페인 시켜도 기본 아메처럼 맛있어용ㅋㅋㅋ 임산부여서 디카페인 찾아 헤매는데 여기만한 곳이 없습니당!', 30, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '합정역 근처 분위기 좋은 디저트 맛집 카페 합정 지튼 완전 추천입니다…!🥰 편안하고 모던한 분위기에 노트북 작업하거나 대화 나누기에도 좋아요 커피도 맛있는데 합정 지튼은 갸또와 까눌레를 꼭 드셔야합니다😆 특히 황치즈 덕후라면 황치즈갸또는 꼬옥이요 꾸덕하면서 단짠 황치즈 맛이 진해서 너무 좋아요😁👏 까눌레는 말차맛으로 먹어봤는데 까작하니 제대로네요 ㅎㅎ 주말에는 항상 만석이던데 이유가 있네요 재방문의사 완전 있습니다!!', 4, 9, 'GOOD', SYSTIMESTAMP);
