INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '디저트 퀄리티가 넘 좋은거같아요!! 에그타르트 먹고싶었는데 제가 갈땐 없어서 못먹었어요 ㅜㅜ 인절미 케이크 너무 유니크해서 좋았구 (살짝 꾸덕하면서 엄청 부드럽) 자몽주스랑 워시드 드립도 맛있네요 ㅎㅎ 분위기도 대화하기 좋았어요! 최고~', 5, 10, 'GOOD', SYSTIMESTAMP);
