INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '지튼은 합정도 망원지점도 분위기 좋아요. 합정지점은 역이랑 가까워요. 망원지점에 비해 합정이 자리가 더 몇개없어요. 커피도 디저트도 맛있어요.', 23, 8, 'GOOD', SYSTIMESTAMP);
