INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '까눌레, 라떼, 아메리카노 시켰는데 까눌레가 가격대비 크고 넘 맛있었어요! 임산부라 디카페인으로 시켰는데 디카페인같지않아서 완전 강추해요! 밀크티랑 콜드브루는 별도로 판매하신다길래 나올 때 구입해봤습니다ㅎㅎ 디카페인 별점 만점 주고싶어용>_<', 23, 10, 'GOOD', SYSTIMESTAMP);
