INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '망원점에 이어서 합정점도 방문했어요! 까눌레가 진짜루 맛있어요!! 음료도 맛있고 커피도 맛있었어요 :) 매장이 깔끔하고 쾌적해서 너무 좋습니당', 15, 4, 'GOOD', SYSTIMESTAMP);
