INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '이집 까눌레 대박입니다... 와...진짜맛있어요 겉은 바삭 안은 쫀득... 과하지않게 너무좋은거에요 👍 👍 👍 황치즈케잌도 예술이고 음료도 맛있어요', 12, 4, 'GOOD', SYSTIMESTAMP);
