INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '가게가.. 정전된것처럼 너무 어두워요 문닫은것처럼.. 그리고 직원분인지 사장님인지 손님 있어도 저희보다 너무 크게 떠드시고,, 밥먹고 가까운 카페 찾다가 왔는데 아쉬웠어요 커피맛은 쏘쏘에요', 79, 14, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '여긴 디저트가 다 맛있어서 자리 없으면 무조건 포장이라도 해야합니다😶 달콤한 디저트가 많으니까 커피 좋아하신다면 같이 곁들여 드셔보세요 전 디카페인으로 함께했더니 아주 만족스럽습니다 합정주민으로서 한달에 한번은 꼭 방문합니다 진짜 맛있어요', 3, 6, 'GOOD', SYSTIMESTAMP);
