INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '<황치즈 갸또> 밑에 시트지 꾸덕력 중 황치즈 단짠 비율 : 단=짠 비율, 혹은 약간 단>짠 치즈향 레벨 중 혹은 중하 당도 중 황치즈 입문자에겐 적당할거 같고 진한 황치즈를 기대하는 분에겐 기대에 못미칠 수도 있어오 갸또가 원래 그런 음식인지 모르겠는제 위에 크림 부분이 너무 미끌거리는 느낌이라 아쉬웠어요 거의 버터 느낌 /얼먹하면 근데 맛있을거 같기도해요 !', 31, 0, NULL, SYSTIMESTAMP);
