INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '아아메 딱 무난하게 맛있고 (끝도 없이 들어가는 맛 아시죠 ㅋ) 황티즈 갸또랑 에그타르트도 맛있었어요✨ 생각치도못한 에그타르트가 너무 맛있어서 지금 마이플레이스쓰면서 다시 먹고싶어졌음;;ㅋㅋㅋㅋㅋ 너무 좁지도 넓지도 않고 다닥다닥붙지도 않아서 좋음 게다가 화장실도 내부에 있습니다ㄷ ㄷ짱 편하게 방문하기 좋은 카페로 추천드려요👏🏻', 28, 6, 'GOOD', SYSTIMESTAMP);
