INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '분위기 커피랑 디저트 맛 모두 좋은 카페였어요. 디카페인 드립커피가 있어서 저녁에 커피 타임 갖기에도 좋았네요. 치즈케이크랑 초코쿠키 모두 특색있는 맛이라 멀리서 온 친구 데리고 갔는데 흡족했어요', 22, 5, 'GOOD', SYSTIMESTAMP);
