INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '에그타르트 겉바속촉촉 지대로네요ㅎㅎ 계란비린내도 안나구 JMT이에요🩵 에그타르트랑 인절미갸또 먹어봤는데 인절미갸또는 콩고물 고순맛 낭낭해서 커피랑 완전 잘 어울려요!! 위에 올라간 인절미 크림이 많이 달지 않아서 더 좋은 거 같아요! 브루드 커피 콜롬비아 라카바나 주문했는데 산미 맛 느껴지는 엄청 깔끔한 맛이네요. 인절미 갸또랑 에그타르트랑 꿀조합👍👍', 63, 18, 'GOOD', SYSTIMESTAMP);
