INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '황치즈 케이크 너무 먹어보고 싶어서 왔어요. 폭신한 식감에 황치즈 맛이 아주 찐~하네요😋 산미가 적고 다크한 과테말라 브루잉이랑 함께 먹으니 딱 좋아요. 밀크티도 베르가못 향이 잘 느껴져서 맛있었어요!', 77, 12, 'GOOD', SYSTIMESTAMP);
