INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '디저트랑 음료 너무 맛있었습니다! 특히 초코케이크가 맛있었고 갸또 스타일의 꾸덕한 케이크를 즐길 수 있어서 좋았습니다. 합정역 케이크 드시고 싶으신 분들 방문해 보세용', 38, 10, 'GOOD', SYSTIMESTAMP);
