INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '에그타르트 맛집이라고 해서 포장하러 들렸어요. 에그 타르트 추천추천!! 일단 에그타르트는 다른 가게들보다 크기가 더 커요. 큰데 맛도 있어서 너무 좋았어요ㅎㅎ 에그 타르트 말고도 다른 디저트들도 너무 맛있어 보여서 나중에 다른것도 먹으러 가보고싶어요:)', 55, 12, 'GOOD', SYSTIMESTAMP);
