INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '황치즈케이크 추천추천 입니다. 크림도 너무 달지않게 꾸덕해서 맛있고 시트도 촉촉해서 정말 맛있게 먹었어요 :) 다음엔 초코케이크 먹으러 가려구요!', 24, 6, 'GOOD', SYSTIMESTAMP);
