INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '합정에 주차되는 카페 넘 좋아요>< 요기 분위기도 좋고, 디저트 종류도 다양해서 좋네요! 황치즈케이크 완전 맛있어요🥹💟 뽀또맛좋아하시는분들 완전 취저일듯요!! 초코스모어쿠키도 달달하고 쫀득한 스모어가 맛있어요~! 에그타르트안에 필링 정말 부드럽고 바닐라향가득해요! 밀크티랑 갓파더 마셨는데 갓파더 짱맛도리..크림이랑 커피랑 조화가 정말 좋았어요~ 합정카페로 추천할게요!!✨디저트맛집!', 2, 2, 'GOOD', SYSTIMESTAMP);
