INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '낮에 햇살 들어올 때 창가 자리 앉으면 좋아요! 디저트도 맛있고 커피도 맛있는데, 저 자리 앉아서 먹으면 10배 더 맛있어지는 매직ㅋㅋㅋㅋ 인절미 케이크 너무 달지 않아 좋았고, 에그 타르트는 겉바속촉 제대로라 하나 더 먹을뻔 한 건 안 비밀ㅋㅋ 데이트로 가기 딱 좋은 카페 입니당 ><', 54, 11, 'GOOD', SYSTIMESTAMP);
