INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '까눌레 넘 눔 쫀쫀하구 황치즈케이크 황치즈 그잡체!!!!! 플랫화이트 비율도 너무 좋구 밀크티는 달달한 밀크티였어요 ☕️❤️ 내부 분위기도 넘 좋구 조용해서 다음엔 저녁에 아메리카노에 스콘 먹으러 가보고싶어요! 잘먹었습니당~', 29, 0, 'GOOD', SYSTIMESTAMP);
