INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '황치즈랑 에그타르트 너무 맛있었어요! 수제바닐라랑 모히또샤워도 딱 제 스타일이었구요>.< 내부도 깔끔하고 벽면이 특이해서 사진찍기도 좋은곳이었어요~ 주말에 방문했는데 손님이 많아서 웨이팅이 좀 있더라구요 합정디저트맛집으로 유명한것같습니다 ㅎㅎ 황치즈랑 에그타르트 꼭 드셔보세요 👍🏻👍🏻', 86, 18, 'GOOD', SYSTIMESTAMP);
