INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '몇년째 합정역 근처 디저트 맛집 자리를 지키는 있는곳. 합정 들릴때마다 생각나는 곳이에요. 원두 로스팅이 딱 제 입맛에 맞습니다. 향미 풍부해요. 디저트는 말해뭐합니까  ㅎㅎㅎ 에그타르트 맛있어요👍', 65, 17, 'GOOD', SYSTIMESTAMP);
