INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '커피는... 깔끔하고 맛있어요 또 마시러올만함. 까눌레...음 겉은 찔겨요. 쫀쫀이 아니라 찔김 황치즈 갸또도 세상 느끼.... 맛집이라고해서 와봤는데 돈버림.. 여기 까눌레 맛집이라는 사람들 까눌레 안먹어봤나봐...', 65, 16, 'BAD', SYSTIMESTAMP);
