INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '사장님께서 너무 친절하시고 밀크티랑 황치즈케익이 진짜 JMT이네요..자몽 음료도 넘 맛있고 초코케익도 꾸덕하니 맛도리에요!! 강추합니당🤎', 20, 1, 'GOOD', SYSTIMESTAMP);
