INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '합정동의 지튼 카페에 가시면 갸또는 무조건 드셔야해요 !!!! 전에는 흑임자도 팔았던거같은데 지금은 흑임자는없고 인절미와 마틸다, 황치즈가 있더라구요 ! 마틸다는 찐 다크초코갸또인데 과하게 달지않아서 정말 맛있었고 중간에 살짝 체리같은 상큼한게 씹히는게 킥이었어요 ! 달지않은 다크초코갸또 좋아하시는뷴은 여기서 마틸다 케이크 추천드려요 ! 여기 핸드드립도 잘하더라구요. 저는 브라질로 주문했는데 진짜 포도같은 상큼한 과일향이 나서 신기했어요. 분위기도 좋고 카페도 넓어서 추천드립니다 !', 19, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '🔹메뉴추천 : 플랫화이트 🔹개인적 의견 : 오..! 커피 맛있음! 요즘은 인테리어도 인테리어지만 커피 맛없는 카페는 진짜 너무 싫은데 커피 맛있는 듯! 플랫화이트 비율 좋고 원두는 산미 없이 고소하고 진한 편🫶🏻 디저트는 까눌레, 케이크 종류 있는 듯 했는데 따로 먹어보진 않았지만 주변 테이블 반응보니 나름 맛있는 것 같았음! 음료 가격도 나쁘지 않고 주위에 추천해주고 싶은 가성비 합정 커피 맛있는 카페👍🏻 💜장길동의 맛도리로드💜', 85, 18, 'GOOD', SYSTIMESTAMP);
