INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '디저트가 맛있다고 해서 기대하고 방문한 까페에요. 황치즈 케이크가 뽀또맛이 난다고 해서 엄청 기대했는데 제 입맛에 너무 잘 맞아서..... 집에 갈때 한개 더 사서 포장해갔어요 ㅋㅋㅋㅋ 넘 맛있었어요 진짜 뽀또맛! 인절미케이크도 같이 포장해갔는데 이건 완전 제 입맛 아니었고, 쿠키 종류들은 다 맛있었습니다. 다음에 방문할땐 땡모반 말고 커피 주문해보고 싶어요. 황치즈케이크 먹으러 다시 방문할거에요!', 67, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '케이크 진짜 부드러워요 시트가 꼭 수플레+크림 섞은듯 진짜 부드러워요 그냥 스펀치빵케잌시트가 아닙니다 황치즈케잌은 자극적인 단짠아니구 부드러운 뽀또치즈맛이구 초코케잌 ! 초코 좋아하시면 필수, 땡모반도 맛잇어효 합정 디저트카페 찾으신다면 추천!! ♡', 13, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '조용하고 깔끔. 모던한 분위기의 카페🙋🏻‍♀️ 벽면에 낙서처럼 그림이 그려져있는데 제 스탈이라서 사진 찰칵 찰칵 했어요. 디저트가 너무 예쁘게 플레이팅 되어 있어서 배부른데도 2개나 먹었습니다😂 아메리카노와 먹기 딱인 달달한 디저트였어요. 땡모반 말만 들었지 한번도 못먹어봤는데 여기서 먹어봤는데 맛있어용! 달콤한 디저트와 함께 멋스러운 공간에서 대화하니 행복한 시간이였습니다❤', 6, 2, 'GOOD', SYSTIMESTAMP);
