INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '내돈내산))) 디저트맛집이라고 해서 하루 2카페 클리어💪🏼 인절미케잌이 있길래 먹어봤는데 저거는 좀 호불호 갈릴맛.... 저도 불호.... 근데 초코케잌은 징짜 꾸덕하니 맛있어요 당충전 필요할때 찾게되는맛❤️ 초코케잌 진짜 왕강추강추강추', 3, 4, 'GOOD', SYSTIMESTAMP);
