INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '황치즈 좋아해서 찾아갔는데 꾸덕하고 찐한 황치즈 갸토 여기가 제일 맛있어요💛 황치즈 덕후들은 여기로!!!!!!! 커피도 퀄리티 좋네용', 115, 23, 'GOOD', SYSTIMESTAMP);
