INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '까눌레가 너무 먹고 싶어서 검색하고 갔는데 후기대로 맛있더라구요!!! 포장했는데 종이봉투에 담아주시긴 하지만 까눌레는 종이봉투에 그냥 넣어주셔서 조금 아쉬웠습니다..! 묶음으로 포장해주시더라도 비닐봉투나 종이로 한번 더 포장해주시면 좋을 것 같아요..! 개별포장해주시면 큰 종이봉투는 유료로 받으시거나 하셨으면 합니다…! 그래도 타르트는 충격에 약하다보니 튼튼한 종이박스 트레이?에 담아주셔서 좋았어요!', 3, 1, 'GOOD', SYSTIMESTAMP);
