INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '매장이 블랙 & 화이트 무드로 분위기가 진짜 멋져요!!! 여기카페는 황치즈가 주요메뉴인 것 같아서 황치즈 케이크 시켰는데 완전 진짜 고소한 뽀또맛👍🏻🧡 초코케이크는 초코의 꾸덕함이 아메리카노랑 잘 어울렸네용 직원분들도 친절하시구 다음에 또 방문하러올께요!!', 43, 5, 'GOOD', SYSTIMESTAMP);
