INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '황치즈까눌레,인절미갸또,에그타르트에 갓파더,따뜻한라떼,,,,,🍰 정말 많이 먹었는데,,, 다 후회는 없습니다🐷 그치만 좌석은 불편한 편이고 다 너무 오픈되어 있어서,, 다음엔 카페이용보다는 포장쪽으로•••', 34, 0, NULL, SYSTIMESTAMP);
