INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '연남동에서도 가깝고 합정역에서는 도보 1분 거리인 지튼카페는 방문할 때마다 북적여서 항상 들어갈 때마다 조마조마... 사장님들이 한결같이 친절하시고 매장 인테리어는 힙하고 디저트는 맛있고:) 말모말모. 하이라이트는 아인슈페너인데 갓파더 아인슈페너를 추천드립니다! 새로나온 유자맛 까눌레가 시트러시하고 정말 맛있어요. 합정역 카페 맛집으로 추천', 24, 10, 'GOOD', SYSTIMESTAMP);
