INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '디저트 맛있어요 많이 달지 않고 까눌레도 맛있었는데… 뜨거운 음료를 취급하는 곳인데 테이블이 엄청 흔들거려요. 두번이나 쏟았어요. 케이크 커팅하는데 엄청 흔들려요. 잔잔하게 흔들리는게 아니라 커피를 쏟을정도에요. 까눌레는 커피잔 들고 커팅했어요. 이런 기본부터 좀 신경쓰세요.', 86, 16, 'BAD', SYSTIMESTAMP);
