INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '까눌레가 탄맛도 안나고 겉바속촉 장난 아니라 정말 맛있게 먹었습니다! 강추에요! 인절미 갸또는 무난했지만 달달 고소해서 잘 들어갔고 커트러리들이 귀여웠어요. 좁지만 분위기도 괜찮았고 핸드워시도 괜찮은것으로 비치되어 있기에 신경을 많이 쓴 티거 나서 좋았습니다.', 16, 10, 'GOOD', SYSTIMESTAMP);
