INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '매장은 잘 이용 안하고 매번 디저트 포장해오는 집이에요 디저트 넘 맛있고요 까눌레도 맛있고 타르트도 케이크도 맛있고 체감상 시즌에 따라 바뀌는 케이크 먹는 맛도 있어요 제가 좋아한 맛이 변치 않고 쭉 유지되기를 기원합니다', 74, 16, 'GOOD', SYSTIMESTAMP);
