INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '☕️아메리카노+카페라떼 - 좌석이 6-7개 정도로 막 넓은 편은 아니지만 적당히 감성적이고 아늑한 편인듯! - 커피는 너무 쓰지도 않고 산미가 심하지도 않아서 좋았어요 - 스콘이 유명하던데 갔을 땐 없길래(?) 못 먹었어요! - 바 테이블이 고정이 안되고 돌아가서 이상하긴 함;ㅎㅎ', 71, 12, 'GOOD', SYSTIMESTAMP);
