INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '친절하심! 갸또 종류 케이크들 강추!! 진짜 짱 맛 ㅎㅎ 가격이 싼 편은 아니지만 나쁘지 않았음 재방문 의사 있음 역시 친절해야 재방문 의사가 생기는 듯 ^^', 82, 11, 'GOOD', SYSTIMESTAMP);
