INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '합정 지튼🖤 분위기 완전 힙하고, 디저트가 너무 맛있어서 꾸준히 손님들이 다녀가는 카페였어요! 합정 오랜만에 왔는데 역시 힙하구나 다시 한번 느낀 공간 디저트가 정말 너무 맛있었고 거기에 브루잉 커피까지 너무 잘 어울려서 놀랐어요🫢 앙버터 스콘 강추합니다!특히 팥이 너무 맛있어요', 4, 2, 'GOOD', SYSTIMESTAMP);
