INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '분위기가 좋고 디저트가 맛있어요. 다양한 디저트가 있어서 골라먹는 재미가 있는 것 같아요. 앙버터에 버터가 정말 많아서 튼실해 보였어요. 앙버터 스콘 맛있다윳ㅎㅎ. 다음에 와서 쿠키도 한번 먹어보고 싶어요.', 36, 10, 'GOOD', SYSTIMESTAMP);
