INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '왔던곳중에서 가장 분위기도 좋고 디저트 종류도 많고 골라먹을수있어서 좋았어요~❤️ 케이크 시켜서 먹었는데 존맛…😭 분위기도 조용하고 사진도 잘나와용 ㅎㅎ!! 디저트 카페로 추천합니다 정말☺️☺️☺️☺️ 자몽에이드…존맛이에요 추천', 0, 7, 'GOOD', SYSTIMESTAMP);
