INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '맛있어요! 포장해서 왔는데 빵봉지에서 거기서 파는 디퓨저 냄새가 배어있어서 좀 그랬어요 ㅜㅜ 진열 베이커리들이 이 다 열려있는것만 개선되면 좋을거같아요', 26, 8, NULL, SYSTIMESTAMP);
