INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '☕️ guatemala ice (6.0) ☕️ mojito shower (6.0) 🍋 레몬위켄드케이크 (5.5) 🍋 바닐라까눌레 (3.0) 핸드드립으로만든 아메리카노인 브루잉커피는 총 4종이 있어 기호에 따라 골라먹기 딱인데요😋 산미있는 캐릭터커피를 원한다면❓ => 엘살바도르 산타로사, 에티오피아 아리차 산미없는 마일드한 커피를 원한다면❓ => 과테말라 와이칸 카페인이 없는 커피를 원한다면❓ => 콜롬비아 디카페인 인테리어부터가 햇살맛집에 조명맛집이라 갬성 가득했는데 맛으로 승부하는 곳이라는 후기에 맞게 테이크아웃 손님들도 정말 많았어요!!', 11, 5, 'GOOD', SYSTIMESTAMP);
