INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '커피도, 빵도 너무 맛있어요! 영수증 리뷰는 처음이지만 재방문한 카페랍니다! 빵도 맛이나 퀄리티에 비해 가격도 저렴하고 커피도 너무 맛있어요!! 전에는 라떼도 먹었었는데 라떼랑 스콘, 까눌레 완전 추천합니다 ♥ 그리고 드립 커피, 산미 있는 커피 좋아하시면 꼭 방문해 보셔요 후회 안 하십니다 ♥ 매장 분위기가 음료 즐기기에 딱 좋아요!', 46, 0, 'GOOD', SYSTIMESTAMP);
