INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '지튼 분위기도 좋고 커피+디저트까지 맛있어버리면 반칙아닌가요,,,❤️ 사장님 적게 일하시고 많이 버세요 다음에 또 방문해서 앙버터스콘 먹을래요!! 사람들도 디저트 많이 사가지고 가더라고요 저도 디저트 왕창 쓸어오겠습니다 호', 12, 4, 'GOOD', SYSTIMESTAMP);
