INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '레몬위켄드 케익 예약주문 3번째인데 이번엔 좀 실망입니다.... 레몬위켄드케익은 좀 시원하게 먹어야 맛있는데 한번도 해동해서 주신적이 없는데 미리 해동을 해서 주시면 한여름에 어떻게 가져가라는건지.... 최소 이동이라 해도 30분인데 오늘은 4시간정도 이동해야 되는데 아이스팩 여쭤보니 없다 그러시고 그냥 괜찮을실거라고만 하시니 기분이 확 상하네요...제가 안괜찮은데 무슨 근거로 괜찮다고 하시는지.....전에 계시던 남자직원분은 친절하시고 응대도 잘해주셨는데 오늘은 여자직원분 두명 계셨는데 질문에 답변도 잘 못해주시고 아쉽네요..', 90, 18, 'BAD', SYSTIMESTAMP);
