INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '시그니처 메뉴인 갓파더도 맛있었고 남자친구가 흑임자 좋아해서 흑임자갸또케이크 먹어봤는데 너무 맛있었고, 에그타르트도 굿 잡 !', 48, 1, 'GOOD', SYSTIMESTAMP);
