INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '카페에 5만원 쓰고온 찐 후기..!!!! 여기 까눌레 찐 맛집이에요 까눌레 정석으로 만드시는 듯 까눌레만 파는 전문점 못지 않게 맛있어서 놀랐어요! 빵들이 다 재료 안아끼고 듬뿍 넣어서 맛이없을수가 없어요.. 다 넘 맛있.. 커피는 과테말라 아이스 먹어봤는데 신선한 원두를 쓰셔서 그런지 아이스인데도 맛이 살아있어서 너무 좋았어요 ㅠㅠ 인스타에서 본 적 없는 카페였는데 왜 더 유명하지 않지 싶은 곳이었습니당.. 아! 자리는 비교적 협소해서 2~3명이서 가시는걸 추천드려요! 저는 테이크아웃해서 먹어서 장소적 불편함은 없었습니당 ㅎㅎ', 17, 8, 'GOOD', SYSTIMESTAMP);
