INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '흑임자를 가장 기대했는데 제일 별루였어요. 뭔가.. 애매한 맛이에요. 반면에 당금케이크 엄청 괜찮았고(크림치즈만 좀 더 산미 있었으면..) 까눌레는 정말 빠작하니 맛있고 걔중엔 얼그레이가 가장 맛있었어요', 39, 5, 'GOOD', SYSTIMESTAMP);
