INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '디저트가 많아요! 골라먹는 재미😊 근데 코시국에 디저트가 다 오픈되어 있어서 이건 좀 찝찝했어요ㅠㅠ 뚜껑같은걸로 덮어져있으면 더 좋을 것 같아요...', 55, 16, NULL, SYSTIMESTAMP);
