INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '얼그레이랑 빅토리아케이크 많이 드시길래 따라서 시켰는데 얼그레이 완전 추천해요>_< 빅토리아도 맛있는데 얼그레이가 진짜 미쳤어요🤭', 88, 14, 'GOOD', SYSTIMESTAMP);
