INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '까눌레 1순위고 에그타르트도 크로와상생지로 바삭한 맛에 계란 비린맛도 없는 부드러운 커스터드크림이라 너무 맛있어요.. 포장해서 어머니에게도 드리니 여기 어디냐며 꼭 가겠다고 하셨습니다. 근데 가지마세요, 저만 갈거거든요. 최애 카페 또 갈게요❤️🤤', 27, 7, 'GOOD', SYSTIMESTAMP);
