INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '오픈 초기때부터 갔던거 같아요 일단 늦은시간에 갔어서 빵 없을까봐 노심초사 했는데 젤 먹고싶었고 젤 좋아했던 에그타르트가 없어서 너무 아쉬웠습니다ㅜ 그래도 다른빵들은 많았어서 다행이였고 디카페인 있어서 좋았어요~ 근데 흑임자파운드는 너무 달기도 하고 결정적으로 시트가 많이 말라있어서 너무 아쉬웠습니다,, 조금 보완해야 될거 같아요 게다가 코시국이니 덮개를 씌운다던지.. 그래도 까눌레, 당근파운드 등 포장으로 사갔던 빵은 다 맛있었어요😊 아참 머신 바로 앞에 있는 테이블이 너무 회전해서 먹는내내 불안하고 조금 불편했습니다😭', 28, 4, NULL, SYSTIMESTAMP);
