INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '레몬케이크 사러갔다가 당근케이크가 급 당겨서 바꾼건데 맛있었어요 시트비해 크림치즈가 적어서 중간에 크림치즈가 한층 더 있으면 좋았겠다는 생각이 들었습니다! 플레인 스콘은 고소하니 굳~!', 5, 3, 'GOOD', SYSTIMESTAMP);
