INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '여러명이서 가기엔 공간이 다소 협소하지만 두세명 가기에 좋아요 다양한 베이커리류와 드립음료가 큰 메리트에요. 베이커리 가격도 적당하고 맛있었어요', 6, 1, 'GOOD', SYSTIMESTAMP);
