INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '애플피칸케이크_2.8점 찐득한것보단 꾸덕한 식감을 기대하고 갔어서 그런가 케이크는 파운드느낌이 났어요. 얼그레이무화과케이크_4.5점 얼그레이는 잘못 만들면 향이 부담스러워서 한두입 먹고 버리기 쉬운데 여기는 부담스럽지 않고 적당히 향긋하더라고요. 무화과 양이 적었을뿐 무화과랑 너무 잘 어울렸어요. 말차 마카다미아 쿠키_3.0점 화이트 초콜렛이 맛이 강하게 나서 말차맛은 진하진 않았어요. 맛 없지는 않지만 진한 말차 향을 선호하시면 아쉬운 점이 있을거같아요. [음료] Heavy Butter_ 위에 올라간 버터크림 자체로도 맛있는데 라떼랑 정말 잘 어울렸어요 Ice Americano_ 산미가 강하지않고 블랙 보리 마시는 느낌. 추천_ 음료- Heavy Butter 디저트 - 얼그레이무화과', 115, 20, NULL, SYSTIMESTAMP);
