INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '큰 규모는 아니지만 베이커리와 쿠키 종류가 적당히 있고, 애플피칸케잌 먹었는데 맛있었어요. 쿠키와 플레인스콘은 포장해왔네요 ㅎㅎ', 17, 2, 'GOOD', SYSTIMESTAMP);
