INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '밥먹고 지나가다 우연히 들르게 되었는데 달달한게 땡겨서 빅토리아 케이크랑 커피 주문했습니다. 같이간 일행이 카페인에 예민해서 디카페인 커피 있는거 보고 너무 좋아하더라구요. 저는 필터커피 마실까하다가 아메리카노 주문했고 일행은 디카페인 필터커피 주문했습니다. 달달구리는 역시 크레마있는 아메리카노랑 먹는게 최고네요. 달달한 디저트 땡기면 방문해보세요.', 0, 3, 'GOOD', SYSTIMESTAMP);
