INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '커피가격은 이래야죠. 요새 도를 넘는 곳들 정말 많은데 여기는 서울임에도 좋습니다. 주차도 바로 뒤에 있어 편리하고 인테리어도 깔끔 모던 . 거기에 좌석도 거리가 있어서 많은 인원을 포용하진 못하지만 저는 오히려 좋았어요', 7, 5, 'GOOD', SYSTIMESTAMP);
