INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '한번 갔다가 빵이 너무 생각나서 평일에 재방문 했어요! 스콘, 까눌레, 에그타르트, 쿠키, 파운드케익 다 먹어본 사람으로서 스콘과 에그타르트 강추해요!! 특히 에그타르트..♥️👍♥️ 덧붙이자면 주차도 뒷편에 가능하고 포장도 하나씩 잘해주셔서 넘 좋았어요~ 지인들한테 입소문 좀 냈슴댱ㅎㅎ', 49, 1, 'GOOD', SYSTIMESTAMP);
