INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '커피 라떼도 고소허니 맛있게 먹었고 에그 타르트도 계란 향이 진한게 맛있게 먹었어요! 다음엔 다른 베이커리류도 먹어보고 싶네요👍', 0, 2, 'GOOD', SYSTIMESTAMP);
