INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '케이크가 오래 밖에 있었던건지 겉면 건조. 그래도 맛은 있긴했음. 의자 불편 걍 인스타카페임 남자종업원분이 가게 뒤에서 담배피시는거같던데 담배피실땐 문닫아주시길.. 냄새들어왔음', 18, 3, NULL, SYSTIMESTAMP);
