INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '늦은 오후라 디카페인 마셨는데 넘 맛있습니다ㅠㅠㅠㅠ 아차차 여러분 땡모반을 드세여 여름엔 땡모반이에오🍉🍉🍉🍉🍉🍉🍉🍉🍉🍉🍉🍉🍉 나 왜 서울 안 사냐ㅠㅠㅠㅠㅠㅠㅠ', 22, 4, 'GOOD', SYSTIMESTAMP);
