INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '분위기 맛 너무 좋아요! 공간은 좁은 편이라 늘 만석이어서 못갔다가 다녀왔는데 긷ㅐ만큼 만족입니다. 커피도 디저트도 추천할만 하네요~ 디저트 하나씩 뿌시러 가야겠어요!', 107, 22, 'GOOD', SYSTIMESTAMP);
