INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '디저트 진짜 맛있어용. 가격이 좀 있긴 한데 분위기도 쏘쏘하고 괜찮네요. 매장은 넓은 편이 아니라서 타이밍 안 맞으면 자리 없을 수도 있어요~', 26, 3, NULL, SYSTIMESTAMP);
