INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '바닐라라떼 시럽 수제로 만드신다는데 정말 진하고 맛있었고 밀크티도 먹어본 밀크티중에 제일 맛있었어요! 빵도 다 맛있어보여서 고르는데 한참 걸렸어용 빵도 촉촉하고 넘 맛있었어요 무엇보다 계산해주시는 직원분이 짱 친절하셔서 기분 좋은 시간이었습니당 합정가면 또 갈거예요!!!', 4, 10, 'GOOD', SYSTIMESTAMP);
