INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '이야~ 이집 당근케이크 인정! 5천원도 안되는 가격인데 이렇게 묵직하다니!! 이거 하나에 라떼 한 잔 마시면 한끼는 충분히 될것 같아요. 든든합니다. 까눌레도 겉바속촉 제대로고 묵직한 치즈타르트도 대만족입니다. 포장도 깔끔하고 아주 좋아요!', 3, 6, 'GOOD', SYSTIMESTAMP);
