INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '요즘 언니의 최애 디저트집이라 합정올때마다 들르게 되는 곳입니다. 당케를 평소에 너무 좋아하는데  당케도 맛있구 까눌레도 겉바속촉이라 맛있어요.', 53, 16, 'GOOD', SYSTIMESTAMP);
