INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '갈 때마다 웨이팅, 꽉차있어서 한 번도 앉아서 먹지 못했어요 ㅠㅠ 아쉬운 맘에 까눌레 포장했는데 맛나네요~ 얼그레이 까눌레 추천!', 25, 1, 'GOOD', SYSTIMESTAMP);
