INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '대체로 크리미하고 단맛은 강하지 않은 편이에요. 아메리카노랑 잘어울릴 맛들 무엇보다 포장을 너무 깔끔하게 해주셔서 테이크아웃도 두렵지아나요', 23, 2, NULL, SYSTIMESTAMP);
