INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '커피 진짜 대존맛 레게노입니당,,,ㅇㅅㅇ 합정갈때마다 방문하는데 디저트 종류도 커피랑 어울리는게 많아서 더 자주 가게되는것같아요,,♥시끄럽지않은 조용한 곳을 선호하는 편인데 분위기는 두 말하면 입아프고 깔끔하고 차분한 분위기라 더 좋았어요ㅎㅎㅎㅎㅎㅎㅎㅎ완죤 강추합니닷—!!!!여자친구 데려가면 101% 칭찬받을듯( ๑॔˃̶◡˂̶๑॓)', 37, 1, 'GOOD', SYSTIMESTAMP);
