INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '까눌레가 진짜 맛있었어요. 얼그레이 파운드 크림은 맛있는데 빵부분이 아쉬웠고, 말차쿠키는 말차맛이 거의 안나서 다시 가도 안먹을 것 같아요. 다들 음료에 까눌레 드세요!', 9, 9, NULL, SYSTIMESTAMP);
