INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '직원 분이 안친절하다고 했는데 전 친절했어여^^ 커피, 베이커리 둘 다 만족스러운 곳이었어여 다음에 또 방문할 생각 있네여^^', 34, 9, 'GOOD', SYSTIMESTAMP);
