INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '일단 분위기도 엄청 세련됐고, 음료랑 빵도 진짜 맛있네요. 무화과케이크는 제 입맛에 너무 잘맞았고 플랫화이트도 굿! 직원분들도 젠틀하셔서 좋았네요 담에 합정 갈 때 재방문의사 있습니다 ㅎㅎ', 73, 15, 'GOOD', SYSTIMESTAMP);
