INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '자주 방문하는데 여자 직원 너무 불친절하네요 몇번 참다가 리뷰씁니다. 머리도 항상 풀고있고 말투부터 행동 너무 불쾌하네요; 커피랑 베이커리는 맛있습니다 :)', 7, 3, NULL, SYSTIMESTAMP);
