INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '합정에 카페들많지만 유독너무 유니크한매장이라 사진찍기도좋은데 기본아메리카노자체도 이미 어나더레벨,,,, 시그니쳐음료들도 맛밸런스가너무좋아요 자꾸생각나는맛 ㅠㅠ베이커리도진짜 말일못 ㅠㅠㅠㅠ흐엉 조만간 지튼음료들도장깨기하러 가야겟어요 최고 😘😘', 47, 5, 'GOOD', SYSTIMESTAMP);
