INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '합정 지튼'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '포장해달라고 했더니 날더운데 앙버터스콘을 종이봉투에만 담아주면 어떡합니까?버터 다 녹아서 종이봉투에 기름묻고 난리도 아니었어요 불쾌하네요', 12, 6, 'BAD', SYSTIMESTAMP);
