INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '우연히 홍대를 걸어다니다가 저녁에 카페인과 디저트가 생각나서 들린 모멘트커피! 밖에서 느낌이 여기다!싶어서 연인과 들렸는데 컨셉도좋고 노래도 차분하고 , 아리따운 바리스타 두분이서 같이 오더 받으면서 친절하게,, 맛있는 음료를 주시네요, 말차라떼 너무 맛있네요!  또들리겠습니다 분위 작살ㅎㅎㅎ 향수가느껴지는 느낌 + 일본식디저트스타일 가게', 8, 2, 'GOOD', SYSTIMESTAMP);
