INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '소꼽놀이하기 좋은 카페🪞🍽️ 이전부터 가고 싶어서 저장해둔 카페인데 드디어 가봤습니다 일본 느낌 낭낭하고 빵을 직접 굽는 재미가 있습니다 주문하고 나눠주신 메뉴얼도 귀여웠습니다 토마토잼이 특히 맛있습니다 ⭐️⭐️⭐️다 먹고 추가하려고 하면 각각 추가 요금이 있으니 아껴 드세용ㅎㅎ', 7, 6, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '일본  가정집을  방문한것 같음 이쁜 인테리어가  눈을 사로 잡습니다 입구부터  넘  이뻐요 빵을 구워 먹는 컨셉  독특하네요~~ 음료도  커피도  너무  맛있고, 빵에  토핑조합이  정말  맛있어서  빵을  추가해서  먹었어요!!  추가 리필은 없고,토핑,버터 피그 별로 추가비  내야  합니다ㅎㅎ 또 가서  소꿉놀이  해보고 싶네요 ^^', 47, 9, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '빵굽는 메뉴가 있어서 그런가 실내에서 탄 냄새 많이 나고 에어컨 틀어놔도 내부가 너무 더워요 ㅜㅜ 음료랑 카페 분위기는 좋았어요', 3, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '귀여운 식빵세트가 있어요ㅎㅎ 버터와 5가지 소스를 주시는데 맛있어요~~!! 식빵을 직접 구어먹는 감성과 바로 바삭하게 구어 먹을 수 있어서 더 맛있었던 것 같아요ㅎㅎ나오는데 시간이 좀 걸리고 주말 4시쯤에 50분정도 기다렸습니다. 가게 안에서 번호 적고 웨이팅해요~', 36, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '일요일 오후 1시 전에 카페 도착 손님 한 테이블만 있어서 여유로웠어요. 두시쯤 웨이팅 생겼는데 단체손님들 막 들어오면서 너무 시장통처럼 시끄러워져서 도망나왔어요ㅜㅜ 건물 반지하(?)에 화장실 있는데 남녀 분리되어 있고 깨끗해서 좋아요. 몇년 전 겨울에 야끼빵 세트 먹었던 게 너무 맛있어서 오랜만에 다시 왔는데 여전히 맛있어요. 그래도 역시 빵 구워먹는 분위기 자체는 겨울이 훨씬 좋은 것 같아요. 토마토잼이 진짜 맛도리', 22, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '빵을 구워먹을 수 있는 야끼빵이 유명한 카페예요! 3월 3일 임시 공휴일이어서 사람이 정말 많았어요. 대기 걸고 밖에서 1시간 돌아다니다 들어왔습니다. 빵은 직접 구워먹을 수 있고 소스 토핑들도 맛있었는데 음료는 그냥 그렇습니다! 2인 테이블 좌석 간격이 좁아서 음료나 버너 떨어지지 않도록 주의 하셔야 할 것 같아요.', 12, 1, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '야끼빵 세트 너무 귀여운거 아닌가요 ... 🥺💭 잼 종류도 여러가지고 음료도 맛있었습니다 🍞🍎💛 특히 토마토 잼... 너무 맛있었어용...🍅', 76, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '말차딸기 타르트 너무 귀여운데 안에 딸기도 실해요 따뜻한 카푸치노 시나몬까지 완벽하고 일본 가정집 같은 컨셉에 일본인 분이 운영하시는거 같아요 아늑하도 포근합니다 :)', 26, 10, 'GOOD', SYSTIMESTAMP);
