INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '매장 깔끔! 친절하시고 맛있어요! 개인적으로 식빵  1개씩 자주 뒤집어야지 안타고? 더 맛있는것 같아요! 2개 잘구우신다면 고수..이신겁니다! :)', 37, 4, NULL, SYSTIMESTAMP);
