INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '식빵을 데워서 먹는 것이 신기했어요! 사용방법이 따로 있고 식빵을 구워서 그 위에 버터와 과일소스를 얹어서 먹으면 달달하면서 맛있어용!', 24, 6, NULL, SYSTIMESTAMP);
