INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '일단 입구부터 인스타 갬성이 낭낭하네요,,,📷🤩 찾아보고 간 건 아니고 길가다가 너무 예뻐보여서 검색해보니 메뉴가 독특하더라구욧⁉️그래서 못참고 들어가봤습니당 ㅎㅎ 빵을 구워서 먹을 수 있다는게 좋았어요..!! 그리고 코팅된 종이에 만들어먹는 법이랑 추천법이 적혀있는데 저는 여기에 적혀있는 건 아니지만!! 앙버터처럼 버터에 팥 올려서 먹는게 젤 맛있더라구요🤤🤤(생크림까지 올리면 금상첨화🥰) 다들 카페 요즘 너무 단조로운 곳 많이 갔다, 난 좀 특별한 곳 가고싶다 하시면 너무 추천합니다✨😻 ps. 제가 카페라떼 광이라서 모든 카페의 카페라떼 먹어보는게 소원이구요,,, 엄청 미식가는 아니어도 카페라떼 맛은 잘 아는데 여긴 카페라떼가 진짜 미쳐써요.. 진짜 카페라떼 좋아하시면 꼭 드셔보심이 ㅎㅎ🫶🏻', 43, 0, 'GOOD', SYSTIMESTAMP);
