INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '딸기라떼 넘 귀엽고 예쁘네요 저녁을 먹어야해서 디저트류를 못먹은게 아쉬워요.. 다음엔 꼭 디저트 메뉴를 먹어봐야겠어요 디저트 구성이 흔하지는 않더라구요', 71, 15, NULL, SYSTIMESTAMP);
