INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '귀여운 버터 케이크와 딸기 라테를 마셨습니다. 진하고 달달해서 맛있었어요. 인테리어도 아기자기하고 너무 예뻐요. 1호점도 가 봤는데 둘 다 좋네요.', 94, 21, 'GOOD', SYSTIMESTAMP);
