INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '너무 귀엽고 아기자기한 카페 💛 내부도 아늑하고 일본풍이라 마음까지 편안해져요 사부작 사부작 해먹기 바빠서 색다른 추억 만들기 좋았던 거 같아요 👩🏻‍🍳', 28, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '인스타에서 알아보고 빵을 구워 먹는게 신기해서 가봤어요 역시 인스타 효과인지 웨이팅이있었는데 바로 첫번째라 그런지 20분정도 뒤에 들어갈 수 있었어요 사장님이 일본분 같았어요!! 식빵을 구워먹는 것 외에도 예쁘고 다양한 디저트가있으니 취향껏 즐기기 좋아요! 아기자기하고 색다른 데이트를 하고싶다면 추천드립니당!!', 266, 78, 'GOOD', SYSTIMESTAMP);
