INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '일요일 오전 초등학생 딸아이의 선택으로 오게 되었어요 직접 토스트도 구워 다양한 토핑도 올려 먹을수있는 체험이 재밌어 보였나봐요 평소엔 빵한조각먹으면 끝인데 신나서 빵추가해서 더 먹네요 저한테도 만들어서 먹어보라하구요 신났어요 😄 저는 일단 라떼가 맛나서 편안했답니다 일본소품샵 같은 아기자기한 카페입니다', 84, 13, NULL, SYSTIMESTAMP);
