INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '아이랑 주말아침에 방문했는데 아이가 빵을 엄청 맛있게 잘 먹었어요~~ 구워먹는것도 너무 재밌네요~ 토핑 하나하나 너무 맛있어요~~특히 파인애플쨈!!', 52, 15, 'GOOD', SYSTIMESTAMP);
