INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '유명하다고 해서 가봤는데 안에 들어가자마자 일본 애니 속 같은 분위기여서 너무 따뜻하고 좋았던 것 같아요! 빵을 그릴에 직접 구워먹는 것도 생소했고 각종 잼과 버터, 계란 등 속재료들도 알차게 준비해주셔서 먹는 내내 행복했어요🥺👍🏻 직원분들도 너무 귀여우시고,,,, 덕분에 데이트 잘 했어요😀', 311, 86, 'GOOD', SYSTIMESTAMP);
