INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '진짜 다맛있고 귀엽고 사랑스럽고💛 다하는카페에요 꽁냥꽁냥 소꿉장난하다가 가는 느낌 빵만드시는분도 진짜 일본분이고 일본느낌 확나요 💕👏🏻⭐️ 힐링하고 갑니다', 47, 2, 'GOOD', SYSTIMESTAMP);
