INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '빈티지하면서 귀엽고 아기자기한 홍대입구 디저트카페에요! 아이랑 같이 방문해서 즐거운 시간 보내고 왔어요. 빵도 즉석에서 구워먹고 토핑 골라먹는 재미도 있네요. 커피도 맛있고 디저트 빵도 맛있어요! 분위기 감성 넘 좋네요❤️', 23, 6, 'GOOD', SYSTIMESTAMP);
