INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '이색체험처럼 빵을 구울수있어서 특별한거같아요. 가격대는 좀 쎈편이에요. 빵굽는걸 시켜도 1인1잔 필수니 참고해주세요.🫣 분위기는 좀 시끄러운편인거같아요~ 사람이 많아요. 커피는 맛있어요~', 24, 4, NULL, SYSTIMESTAMP);
