INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '귀엽고 아기자기한 음료와 디저트들이 모여있는 카페에용! 매장도 깔끔하고 식빵을 구워먹을 수 있는 이색적인 곳이에요🥰 완전 신기하고 맛있었어요🥰 연인이랑 친구랑 꼭 필수 방문해야되는 아름다운 공간입니다!!', 19, 2, 'GOOD', SYSTIMESTAMP);
