INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '아늑하고 2인석과 4인석이 있습니다, 나무로 된 인테리어와 차분한 음악으로 아늑하고, 친절하고 청결한 것이 마음에 듭니다 매장 한켠에는 일본 잡지도 있고, 디저트와 소품도 팔고 있고 빵 모양의 캐리커쳐도 귀엽습니다!', 37, 1, 'GOOD', SYSTIMESTAMP);
