INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '야끼빵세트 특이하네요. 미니 식빵을 화로에 직접 구워먹는 느낌은 새롭고 특히 토마토쨈과 계란 반숙  팥쨈은 독특했어요. 인스타용 맛집', 39, 0, 'GOOD', SYSTIMESTAMP);
