INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '음료도 맛있고, 식빵을 구워먹는다는게 참 특이하고 좋았던 거 같아요:) 매장 자체는 크거나 넓진 않았지만, 그래도 인테리어로 아기자기하니 귀엽고, 감성이 있었던 거 같아요! 화로에 식빵을 구워먹는 카페가 있다는게 너무 신기하고 좋았습니다!!! 홍대에서 독특한 카페 가고 싶은 분들께 추천드려요⭐️⭐️⭐️⭐️⭐️', 119, 22, 'GOOD', SYSTIMESTAMP);
