INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '진~~~~~~~~짜 오래 기다렸어요 앞에 한팀인데 40분넘게 기다렸던거같애요 기다리다가 한팀 나갔는데 바로 부르겠지 하고 기다려봤는데 10여분 지나고도 안부르더라구요 뭐지 싶어서 들어가서 물어보더니 손님나간줄몰랐대요… 다들 다 시키는 세트를 한번시켜봤는데 양이 좀 적구 가성비 좀 떨어지는거같애요 여직원분이 친절하구 귀여우셔여', 36, 8, NULL, SYSTIMESTAMP);
