INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '친구들이랑 방문했어요~ 앞에 5팀 정도 있어서 1시간 대기 했지만 너무 재밌는 경험이었어요! 친구들이랑 같이 식빵 구워먹고 토핑들을 식빵에 올려먹는게 어렸을때 소꼽놀이 하는 기분이더라구요ㅎㅎㅎ 카페에서 대화만 나눈게 아니라 재밌게 논 기분이였어요. 다음에는 라끌렛치즈 먹으러 오려구요!', 28, 3, 'GOOD', SYSTIMESTAMP);
