INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '너무 예쁘고 따스한 공간에서 달콤한 디저트타임을 즐길 수 있어서 좋았어요! 카페라떼, 밀크티 음료도 맛있고 야끼방세트 가성비 좋고 맛도 최고였어요~~^^ 딸기보따리는 집에 와서도 계속 생각났네요! 재방문 예정입니당!', 9, 8, 'GOOD', SYSTIMESTAMP);
