INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '소꿉놀이 감성의, 식빵을 구워먹을 수 있는 카페예요❤️ 햇살이 들어오는 창가 자리에서 차분하고 정성스럽게(? ㅋㅋ) 식빵을 구워 맛있게 먹었어요^^ 주문한 야끼세트(14.0)는 식빵 8조각과 토핑(반숙계란, 팥앙금, 과일잼, 생크림, 토마토잼, 버터) 구성이고요, 굽는 재미와 취향에 따라 다양한 조합으로 발라먹는 재미가 있어요 ㅎㅎ 처음엔 2조각을 한꺼번에 올려 구웠는데 좀 타길래.. 불조절을 불 꺼지기 직전으로 바꾸고 한조각씩 구웠더니 타지 않았어요. 라떼(5.5)도 맛있었어요. 아늑한 분위기의 카페에서 머무는 내내 행복했어요. 소꿉놀이 좋아하셨던 분들께 강추드립니다~! ^^', 232, 99, 'GOOD', SYSTIMESTAMP);
