INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '따뜻한 목조 인테리어에 아기자기한 캐릭터가 귀여운 카페에요 딸기보따리는 크레페..로 커스터드크림+신선한 딸기를 감싸고 생크림과 딸기토핑으로 장식한 디저트 같은데 쫄깃하면서 부드럽게 녹아드는 맛이 일품이네요 커피도 잘 어울려서 맛있어요!', 36, 7, 'GOOD', SYSTIMESTAMP);
