INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '전부터 꼭 가보고 싶었던 곳이였는데 드디어 다녀왔네요 웨이팅은 대략 30분이내였고 야끼빵set 로 시켰어요 반숙란에 토마토잼..?이랑 해서 먹어도 맛있고 팥에 버터는 기본중에 기본 빵도 직접 구워먹어서 재밌고 더 맛있었어요 칼피스 soda  맛있어요!', 117, 25, 'GOOD', SYSTIMESTAMP);
