INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '커피와 음료, 디저트 다 수준 이상이네요. 오랜 세월의 내공이 쌓여있는듯한 느낌은 좋은데, 사장님인지 말투가 좀 무섭네요.ㅠㅜ', 23, 9, NULL, SYSTIMESTAMP);
