INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '우왕😍 홍대에 이렇게 분위기좋구 가성비좋구 빵구워먹는 카페가 있다니 왜 이제서야 알게된걸까요😝 신랑이랑 퇴근 후 종종 방문해야겠어여 오늘은 넘 배불러서 다른건 못시켜서 아쉽아쉽😙 담에는 꼭 구워먹는빵 다른메뉴들 다 주문해서 맛볼려구여😋 치즈맛휘낭시에도 부드럽고 넘 넘 맛나염 아포가토도 맛있공 커피라떼도 굳굳💯💯 사장님이 일본분이신듯 분위기가 아늑하고 편하고 오래있어도 불편함이 없어서 좋았고 화장실도 깔끔해서 더 더 좋았어염👍👍👍 조만간 동생들이랑도 ㅈ ㅐ방문할께예~~😊', 5, 5, 'GOOD', SYSTIMESTAMP);
