INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '커피가 부드럽고 너무 맛있었어요 제 최애 라떼인 것 같아요 🩷 음료도 맛있구 빵 구워먹는데 신선하구 좋았어요 예뻐요 다음엔 다른 디저트 먹으러 갈게요~! 분위기도 일본 여행 온 것 같아서 너무너무 좋았습니다 아기자기하고 굿굿 재방문의사 이써요 💙', 46, 5, 'GOOD', SYSTIMESTAMP);
