INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '빵구워먹으러 며칠만에 다시 방문했습니다. 4시퇴근하고 5시쯤 도착하니 자리가 거의 다 차있었고 다행히 빵구워먹는 디저트는 품절되지 않아서 살짝 기다렸다가 자리를 잡고 주문을 하였습니다. 빵은 8개가 나왔고 발라먹는 건 5종류가 나왔는데, 빵굽는 법과 어떤걸 발라먹으면 좋은지에 대한 설명안내서도 같이 나왔습니다. 먹기 전에 잘보고 빵을 구워야 안타게 잘 구울수 있었고, 발라먹는 조합을 잘 맞춰서 먹을 수 있었는데, 취향에 맞게 발라먹어도 좋았습니다. 발라먹는게 좀 남아서 빵을 추가했는데, 4천원에 8개가 더 나왔고, 배부르게 먹을 수 있었습니다. 썸머 아메리카노와 같이 먹었는데 생크림과 아이스크림이 들어가서 빵이랑 커피만 먹다가 나중에는 라떼처럼 섞어서 먹었는데 많이 달지 않고 괜찮았습니다.', 11, 0, 'GOOD', SYSTIMESTAMP);
