INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '모멘트커피에 따뜻하게 빵을 구워먹는 디저트메뉴가 있다고 해서 홍대에 볼일을 마치고 방문을 해봤습니다. 매장내부 분위기는 일본 느낌이 났고, 사장님들은 일본분인듯 했는데, 평일 저녁에 방문하니 이미 구워먹는 빵은 솔드아웃이라고 하셔서 인기가 많다는 것을 실감하였습니다. 아쉬운 마음을 뒤로하고 커피와 멜론소다 그리고 명란마요사라다빵에 강아지 모양이 있는 케이크를 주문하였고, 예쁘게 잘 정리되어서 나온 쟁반을 받아 자리에 가져와서 맛을 보았습니다. 멜론소다는 생크림과 아이스크림이 들어가서 더 달달한 느낌이었고, 사라다빵과 강아지 케이크는 비쥬얼고 귀여웠는데 맛까지 좋았습니다. 그래도 디저트와 같이 먹기엔 커피가 더 좋았습니다. 다음에 낮에 일찍 구워먹는빵을 먹으러 꼭 다시 와봐야겠습니다.', 50, 5, 'GOOD', SYSTIMESTAMP);
