INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '매장 너무 귀엽고 빵도 직접 구워먹어서 그런가 희한하게 맛있음 재방문 의사🙆‍♀️ 단 실내에서 좀 탄내가 많이 나긴 해요 전 후각이 민감하지 않아서 괜찮았지만 민감한 분들은 좀 힘드실수도?', 113, 24, NULL, SYSTIMESTAMP);
