INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '메뉴는 특이한데 딱 그것만 있는 집 웨이팅을 안까지 들어가서 명단을 작성해야하는데 안내가 잘 안되어있어서 사람들은 계속 들락날락 가게는 부산스럽고 찬바람들어오고.. 직원이 응대나 안내도 잘안해줌 살짝 불친절하단 느낌 그리고 빵을 구워먹는 카페라는게 특징인데 온 테이블에서 빵을 태워먹다보니 카페 안에 탄내가 너무 심함 처음 들어왔을때부터 냄새나긴 했는데 중간부터 점점 심해져서 나옴 한시간 조금 있었는데 옷이랑 머리에 탄내 엄청남', 31, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '여기 분위기도 좋고 빵 굽는 거 좋아서 또 갔는데 저녁에 갔더니 품절ㅜㅜ 못 먹어서 아쉬웠지만 덕분에 멍토리아랑 샐러드 빵 먹었는데 반해버려따😍멍토리아 귀여운데 부드럽고 달달하고 완전 완벽한 디저트였다ㅜㅜ 샐러드빵이랑 멜론소다도 취향저격이었숨!!!!! 조만간 낮에 다시 갈 예정>__< 분위기도 맛도 다 합격🤍', 19, 6, 'GOOD', SYSTIMESTAMP);
