INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '일본감성의 아기자기함이 베어있었던 홍대 디저트 카페 야끼빵세트 직접  스토브에 구워먹는 재미가 있었어요. 딸기보따리도 너무 맛있고 폭신한게 딱 적당히 달고 생과일이 너무 신선했어 여기가 홋카이도인지 한국인지 ㅎㅎ', 121, 19, 'GOOD', SYSTIMESTAMP);
