INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '가려던 곳을 못가고 급하게 찾아 방문하였는데 장소가 아늑해서 분위기도 너무 좋고 디저트도 맛있고 커피도 맛있어서 저희가 좋아하는 분위기라 또 방문할꺼 같더라구요~', 37, 9, 'GOOD', SYSTIMESTAMP);
