INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '조용하게 집중하기 딱 좋은 구성...😢✨️✨️ 집에선 먹기 귀찮고 번거롭지만 모멘트 커피에선 기쁜 마음으로 시킬 수 있어서 너무나 좋았어요!!! 특히 토마토 잼과 반숙은 별미입니다☺️🔥❤️❤️', 39, 4, 'GOOD', SYSTIMESTAMP);
