INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '맛있어요! 잼이나 크림 발라먹을 것도 많아서 골라먹는 재미도 있었어요ㅎㅎ 사진도 이쁘게 나옴!! 근데 테이블이 전체적으로 찐득...햇움ㅠ ㅠ', 24, 8, NULL, SYSTIMESTAMP);
