INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '근처에 일이 있어서 방문했는데 입구 위치부터 인터리어까지 일본 로컬 카페에 들어와있는 느낌이었어요. 인테리어도 아늑하고 커피도 맛있었습니다. 다만 매장이 작다보니 수다떠는 손님들이 시끄러우면 신경이 좀 쓰였습니다. 분위기는 정말 좋았어요', 37, 4, NULL, SYSTIMESTAMP);
