INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '가게가 너무너무 예쁘고 사장님이 엄청 친절하셨어요!! 맛도 되게 독특하고 빵 구워서 먹는다는 게 신기하고 그랬고 엄청 디저트도 맛있었습니다 ㅎㅎ 오늘 홍대 와서 들렀던 곳들 중에 여기가 제일 마음에 들어요! 다음에 또 재방문 하고 싶습니다 ❤️', 62, 14, 'GOOD', SYSTIMESTAMP);
