INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '우연히 발견한 카페였는데 내부 인테리어와 메뉴가 일본 느낌이 나는 카페ㅎ 말차라떼와 명란사라다를 맛있게 잘먹었는데 명란 맛은 다소 약하지만 명란사라다빵이 넘 맛있어서 다음에도 사먹고 싶더라구요^^', 44, 6, 'GOOD', SYSTIMESTAMP);
