INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '일본여행을 선물로 안겨주는 곳이지요. 타마고산도를 좋아해서 1호점을 자주 다녔었는데요 1호점이 없어졌습니다. 이번엔 라끌렛치즈빵세트를 먹고 갑니다. 다 좋은데요 부드러운 빵이었음 더  좋겠습니다^^', 18, 1, NULL, SYSTIMESTAMP);
