INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '들어가자마자 외관이 너무 이뻐서 기분 좋은채로 갔는데 역시나 음료도 존맛!! 야끼빵 역시나 너무 이쁜데도 맛있었습니다:-) 매장은 넓은편이 아니여서 웨이팅 있을수더 있습닉당!! 잘먹었습니다^__^', 82, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '너무 맛있고 새로웠어요!! 제가 사진 찍다가 음료수를 다 쏟아버렸는데 새로 다시 가져다 주셨어요 ㅠㅠ 너무 감사합니다 앞으로 홍대 올때마다 자주 들릴 것 같아요 !!', 32, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '식빵을 직접 구워먹을 수 있는 독특한 컨셉이라 예전부터 꼭 가보고싶었는데 드디어 가 본 모멘트커피 ◡̈ 주말  3시쯤 갔는데, 웨이팅 없이 바로 들어갔어요! 식빵 완전 꿀맛ㅠㅠㅠ💙 함께 곁들여먹는 잼이나 계란도 정말 만족스러웠어요☺️', 33, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '다양얀 시그니처 메뉴가 있어서 좋은 카페에여. 간단하지만 직접 만들어 먹는 재미도 있구요. 평일 3-4시정도에 가니  손님이 많이 없어서 편안하게 즐기다 왔어요. 실용적인 굿즈도 다양해서 선물용으로도 좋을 것 같아요.', 128, 26, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '최악! 이 곳은 카페가 아니라 고깃집임 떡구이인지 식빵 구이 인지 뭔지 구워먹는 메뉴가 있는데, 누군가가 구워 먹기 시작하면 순식간에 매장전체가 굽는 연기로 가득참. 이 곳의 공기와 냄새는 삼겹살집을 방불케 함. 이를 대비한 환기 시스템은 따로 없어보이고 문을 열어 둘 생각도 안함. 카페 안 공기 관리는 오직 굽는 손님의 굽기 스킬에 의존해야 함. 두번 갔는데 운이 없던 건지 두번 다 같은 상황이었음 카페가 일본스럽다는 지인의 얘기 듣고 간건데 인정할 수 없음. 내가 아는 일본인들은 절대, 이런 탁한 공기에서 커피를 마시게 내비두지 않을 사람들임. 고즈넉한 곳에서 음악들으며 커피 즐기러 갔다가 연기 봉변 당하고 마음이 안좋아져 한마디 남기고 갑니다', 4, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '⭐ 저녁 5시에 방문,매장안은 한산~ 직접 식빵구울수 있는 야끼세트🔥이거시키러갔어요 먼저 버너와 식빵이 트레이에담겨 나와서 식빵을 굽고있는데  진동벨울려서 나머지세트 메뉴랑 음료 가지구옴 너무 푸짐한거있죠 책상을 가득가득채움ㅎㅎ 트레이에 담겨져있는 List들은 아래와 같아요🔥 잼(귤,토마토!),버터조각,반숙계란,시나몬뿌려진 생크림👍 빵에 반숙계란을 펴발라 생크림과함께먹으면 무~지맛있어요 다시한번가보고싶은곳. 불편한점은 안이 은근 좁아서 테이블마다 간격도 좁음..그것빼고는 인테리어도 예쁘구 로고도 아기자기하고 귀엽구 좋았어요', 28, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '분위기 진짜 좋고 빵 맛있어요ㅎㅎ 세트메뉴는 품절이여서 못먹었어요ㅠㅠ 대신 다음에 또 방문하면 되니까! 지브라 영화속에 들어간 기분❣️', 66, 12, NULL, SYSTIMESTAMP);
