INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '🥈 ♡ 야끼빵세트 (13,500) ♡ 레몬소다 (6,500) ♡ 미숫가루 (6,000) ♥ 맛 - 야끼빵세트 : 빵이 잘타서 빨리 뒤집어야함. 토마토쨈이 매우 맛있었습니다. 살짝 느끼해서 음료는 탄산 든걸로 시키길 추천 - 레몬소다 : 느끼할때 마셔주면 매우 맛있었습니다. - 미숫가루 : 제가 좋아하는 미숫가루맛이에요. ♥ 내부 : 내부는 아주 아기자기하고 뭔가 지브리 마루밑아리에띠 집 분위기여서 취향 저격했습니다. ♥ 총평 : 이색 체험 하고 온거 같아서 신기했음. 아기자기한 분위기라 그런지 남성분이 오시면 굉장히 어색해함. 재미있었지만 가격대비 추천은 안함. 그리고 탄내가 나는데 환기가 안됨. 기관지 안좋은 분들은 힘들거 같아요. 이분들 외에 이런 체험하시고 싶으면 한번쯤 방문하기 좋은곳', 63, 11, NULL, SYSTIMESTAMP);
