INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '너무 귀여워요ㅜ 빵을 구워먹을 수 있다니ㅜㅜ 완전 아기자기하고 소꿉놀이 하는 기분이라 너무 좋았어요..! 다음에 또 가려구요! 최고최고!', 35, 0, 'GOOD', SYSTIMESTAMP);
