INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '주말오후 웨이팅이 있을줄 알았는데 그냥 좌석 1-2개 남은정도였다! 일본 아기자기 갬성쓰 낭낭한 곳 여친들과 함께 온 남친들은 다들 ㅇ.ㅇ? 이런표정 ㅋㅋㅋ 후기대로 휘낭시에가 기대보다 맛있었고 계란말이 빵은...흠.ㅁ...돈아까운데 ㄱㅖ란말이만 맛있어서 먹었음 ㅋㅋㅋ 밥땡기는 맛 ㅎ 썸머아메리카노 아이스크림이 맛있어요 한번 간걸로 만족할게요^^제가 한번 온걸로 만족한다고 했어요 네에? ㅎㅎ몬말인지알져알져?', 23, 1, 'GOOD', SYSTIMESTAMP);
