INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '넘 맛있어요❤️ 귀엽고 예쁘고 최고예요🥺 메뉴는 아포가토랑 크림라떼, 명란사라다, 초코브루통이예요 플레이팅 보기만 해도 행복해지는 곳입니당', 46, 9, 'GOOD', SYSTIMESTAMP);
