INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '인테리어 너무 좋고, 다 나무로 되어서 따뜻한 느낌도 들어요 ㅠㅠ 음료도 맛있고 다 귀엽고 포근한 느낌이 드는 것 같아요 강추 ,,', 25, 2, 'GOOD', SYSTIMESTAMP);
