INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '빵 구워먹는 컨셉이라그런건 알지만 실내에 탄내가 너무나서 좀 불편했어요 그리고 딸기크림라떼? 시켰는데 딸기청이나 냉동딸기도아니고 딸기쨈 넣은거 같은 완전 딸기쨈맛 나서 가격대비 너무 비싸고 돈아까웠어요 딸기쨈넣고 5500원은ㅜㅜ', 22, 2, 'BAD', SYSTIMESTAMP);
