INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '#연남동모먼트 #직접빵구워먹는이색집 #캠핑갬성 분위기도 조용하고, 내가 직접 빵도 구워 먹고, 내 입맛에 맞게 토마토잼, 반숙 올려 먹고, 딱 내스타일 당근크림스프가 있어 좋았아요~~^^ 전 개인적으로 반숙하고 당근크림스프가 좋아요~ 식빵도 부드럽구요~^^', 28, 4, 'GOOD', SYSTIMESTAMP);
