INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '맛있어요!! 알아서 구워먹으니까 원하는대로 먹을 수 있어서 좋고 반숙계란과 토마토잼이 진짜 신의 한 수!! 거기다 커피도 맛있어서 거의 흡입했어요ㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋ', 28, 9, 'GOOD', SYSTIMESTAMP);
