INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '맛은 있었어요 근데 솔직히 너무 가격이 비싸요 가격빼곤 아기자기하게 귀엽구 카페 음악두 일본음악이 나오드라구요ㅋㅋ 빵 구워먹음서 재미는 있었어요!!', 53, 11, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '여기 완전 귀염뽀쨕해요ㅠㅠ 커피양이 많은 편은 아닌데 커피가 맛있어요! 뭔가 홍대&연남동 카페투어할 때 좋을 것 같아요. 음료 종류도 다양하고, 빵 종류도 생각보다 다양하더라구요! 그리고 코스요리처럼 야끼팬세트라는 메뉴도 있던데 직접 빵을 구워먹는데 분위기 있어보였어요~', 40, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '빵을 직접 구워서 먹는다는 것이 큰 메리트가 있습니다 하지만 처음 구울 때 어떻게 타지 않게 구울 수 있는지에 대해 설명해 주셨으면 더 좋았을 것 같습니다 처음 굽는 바람에 빵이 완전히 타버리는 경우가 많았고 까만 숯맛이 나는 빵을 먹는 경우가 다반사였습니다 어떻게 빵을 굽는지에 대한 설명을 해주셨으면 좋겠습니다', 0, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '모멘트커피 2호점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '연남에서 좋아하는 카페 순위 안에 들어요 ㅎㅎ 1호점은 워낙에 자리가 좁아서 항상 들어갈수가 없는 대신 2호점은 좀 더 넓고 답답한 느낌이 없어서 저는 2호점을 더 좋아해요. 카페 음료가 넘 예쁘게나와서 사진 찍는 재미가 있고 커피 맛도 좋아서 연남 올때마다 들리려고 합니당^^', 73, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '친절하시고, 꼼꼼히 포장해주어서 감사합니다!  틴케이스에 쿠키 2개 들어가는 1만원 세트 4개 구매했어요~ 근처에 전시하고 있어서 지인분들이 멀리서 방문해주어서 답례 선물로 드렸는데 모두 좋아해 주셨습니다~ 쿠키도 맛있구요^^ 간단한 선물하기 너무 좋았습니다!', 31, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '🫶쿠키맛집 벤스쿠키🫶 몇 년째 연남동을 지켜주고 있는 벤스쿠키 다녀왔어요🫶 쿠키 자체가 쫀득해서 꾸덕한 쿠키 좋아하시는 분들은 환장할거에요!! 신메뉴로 나온 거 먹어봤는데 츄러스 같은 맛에 꾸덕한 잼까지 들어있어서 더 존맛 .. 다들 벤스쿠키 하나씩 해주세요🫶 제 픽은 마카다미아입니다 후후', 119, 25, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '연남동 벤스쿠키 다른 지점도 매번 보다가 이번에 처음으로 먹어봤는데 너무 맛있네요. 가격이 있지만 충분히 그 가격 할만큼 쫀득쫀득하고 고소하고 맛도 다양해서 어디 선물로 먹기에 완전 딱 좋은거 같습니다. 추천해요^^ -by 스티브잡식 다녀갑니다-', 34, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '친구소개로 가게 됐어요! 쿠키 종류가 많아서 좋아요 달달하고 맛있습니다 ㅎㅎ👍🏻 안에 좌석이 따로 없이 테이크아웃만 가능한 것 같았어요!', 14, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '사진은 일부고 18만원어치샀는데 서비스 없음. 하나씩 선물하려고 종이봉투 요청했는데 빼먹고 안줌. 전화하니 아.. 빼먹었나봐요 죄송해요.. 가 끝이네요 ㅠ 직원 일머리없고 느려요. 덕분에 편지랑 쿠키 못 담아 선물함..', 6, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '품절된 쿠키도 있었지만 종류 꽤 다양한 편이었어요~~ 요즘 크고 두꺼운 쿠키가 많아 상대적으로 얇고 작은 느낌인데 겉바속촉 쿠키고 부드러워요!😽 부담없이 먹기 좋고 포장케이스가 다양합니당 케이스를 구매하지 않음 포장종이에 개별포장해 끈없는 종이봉투에 주세요😊', 127, 22, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '다크초코2, 화이트초코마카다미아2, 레몬1 말차1 피넛버터1 이렇게 7개 시켰는데 말차 대신 화이트초코가 3개 들어있네요.. 많이 아쉽습니다', 4, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '화이트데이 프로모션까지 해서 더 좋은 가성비로 맛있는 쿠키를 먹을 수 있음. 예쁘고 유행하는 디저트 많지만 결국엔 말랑하고 부드러운 벤스쿠키가 제일 맛있더라...', 117, 20, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '초코🍫맛 먹었습니당😋 되게 다양한 맛이 있었는데 오리지널부터 먹어보자! 해서 골랐어요☺️🩷 제가 평소에 좋아하던 쿠키🍪가게보다 천원이나 싼데 맛은 비슷하더라구요!! 앞으로 홍대갈때마다 여기서 쿠키🍪 먹을거에요😍 쿠키🍪 사진은 한입 먹자마자 제 입속으로 사라진 덕분에 찍질 못했네요😭ㅠ 사장님 많이 파세요~😘', 13, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '매장이 정말 좁아서 한 팀씩만 주문을 받는 시스템이라 상당히 춥고 불편했어요 그리고 다른 지점들보다 맛이 좀 덜해요 뭔가 밍밍하달까...', 35, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '매장이 좁은지 한팀씩만 들어오라고 함..그러면 빠르게 진행을 하던가..알바생인가..손 더럽게 느림..추운날 밖에서 엄청 기다림..주문 하는데 말을 못알아듣는건지..외국인인줄..그렇다구 친절하지두 않음..일을 못함..손님 입장에서 속 터짐.. 연말이라서 선물 겸 구매했는데 딱히 기다려서 구매하고 싶지않음.. 친절한 다른 지점가겠음..', 40, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '쿠키치고 비싼편인데 맛있어서 가끔 구매하는데 직원 느려 터짐. 친절하지두 않고.. 춥거나 더울땐 밖에서 대기해야해서 굳이..그럴 가치 없음..다른 친절한 맛있는 매장으로 가겠음.', 71, 14, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '약속 가는길에 친구들에게 선물로 주려고 구입했어요 ㅎㅎ 가격부담없이+예쁜 포장으로 선물할 수 있어서 좋은 것 같아요 쿠키 종류도 다양하고 좀(매우) 달달한 편이지만 맛있어요', 21, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '마주칠때마다 들어가는 벤스쿠키 ㅎㅎㅎ 저는 화이트초콜릿크랜베리, 밀크초콜릿오렌지, 초코청크 메뉴 다 넘 좋아해요 !!! 넘맛있어요 부산에두 생기면 좋겠어요👀', 66, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '수기테라피 원장님 간식거리로 구입...5개 사면 2개 추가증정이라 좋았고 새빨간 예쁜 선물상자에 포장하니 뿌듯... 많이 달지만 여기만의 맛이 있어서 좋다. 버터에 초코를 녹인 찐한 단맛...중독성 갑. 여러개 못먹을 정도지만 자꾸 생각난다. 최애는 코코넛, 마카다미아 청크인가? 더블초코어쩌구도 끝짱... 미소지어지고 양심에 찔리는 맛', 25, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '얼마 전에 먹고 맛있어서 또 구매하러 방문했어요👍 쿠키가 넘넘 맛있는데 개별포장이 안되고 포장 후 무슨 맛인지 확인이 안되서 아쉬워요 그래서 확인하려구 찍은 사진들입니다✌️', 1, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '예전에 지인이 사다줘서 먹어본 이후로 연남에 매장이 생겨서 종종 들릅니다! 테이크아웃만 가능하긴 하지만 요즘같은 고물가 시대에 쿠키값도 합리적이고, 일단 맛있습니다...다양한 맛이 있어서 선택의 폭도 넓고 매장 안에 들어서면 정말 고소한 쿠키냄새가 너무 좋아요! 새로나온 시나몬 츄러스? 쿠키도 맛있고 밀크초콜릿 프랄린, 화이트마카다미아 등 초코+견과류 조합의 클래식 쿠키도 넘 맛있어요! 마침 5+2 행사를 하고 있어서 5개 구입했는데 순삭할 뻔한 걸 겨우 참았네요 :) 종종 들를 예정입니다 ㅎ', 39, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '진짜 쿠키 맛있어요. 특히 초코쿠키류가 많은데 종류 다양해요. 5+2 해서 5개 가격에 7개 박스에 넣어왔내요. 가족들 모두 좋아하고 5가지 종류 가져와서 다 맛 봤는데 모두 맛있습니다. 크기가 커서 쿠키하나와 우유나 커피한잔하면 당충전 완료됩니다. 맛있어서 이번이 두번째 방문이었어요. 홍대갈일있으면 또 들릴예정입니다.', 20, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '해외에서만 먹던 벤스쿠키를 여기서도 보네요ㅜ 너무 좋아요 선물용으로 산건데 딱 적당하고 종류도 많이 있어서 잘 샀다고 생각합니다 가게는 많이 협소해서 빨리 사고 나와야할 것같긴 합니다', 33, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '회사 분들에게 감사인사 할 일이 있어서 벤스 쿠키 사갔어요! 쿠키 개별포장 안되는 것은 아쉽지만 이정도 퀄리티에 이 가격이라니 최고에용 실온에 두고 먹는 것보다 얼려먹는 것이 더 쫀득하고 맛있더라구요', 15, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), 'ben’s box구매(총 7개) 초콜릿 베이스의 쫀득한 쿠키입니다. 정말 다 촉촉 쫀득해요.. 너무 맛있고 선물해줬는데 받는 사람도 만족했습니다. 초콜릿 쿠키 좋아하면 꼭 먹어보길 추천합니다.', 179, 99, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '연남동 놀러갔다가 쿠키 가게보고 너무 맛있어보여서 방문했어요. 쿠키 종류도 많고 크기도 커요. 맛은 진심 맛있어요. 쫀득하고 부드럽고 달달해요. 라떼나 우유에 마심 꿀 맛입니다. 연남동 투어하고 돌아가는 길에보니 쿠키가 다 팔렸더라고요. 인기맛집임을 실감했습니다.', 19, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '쿠키 7개 박스포장후 1분후 다시가서 개별포장 부탁드렸으나 위생법상안된다하시어 한장당 20원씩 140원내고 유산지 같은 종이 구입후 박스는 버리고 알아서 셀프포장하였는데 기분이 썩 좋진않더라구요ㅎㅎㅎ 쿠키는 맛있었는데 한여름 땡볕에 아이스포장도안되고 바로 눈앞에서 쿠키가 실시간으로 녹아내리는데... 여러모로 아쉬웠습니다. 재방문은 안합니다.', 4, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '개인적으로 쿠키 안좋아하지만 지인 선물용으로 맛 골고루~ 한박스 구매했습니다! 선물받은 지인이 너무 맛있다며 뇸뇸 먹다 저도 한조각 먹어보니 정말 맛있더라구요 ㅋㅋㅋㅋ 쿠키 안좋아하는데ㅋㅋ한번씩 사먹게될거같아요!', 24, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '아오 너무 맛있네요. 오렌지 쿠키가 진짜 제 취향이네요♡ 한입 베어물면 상콤한 시트러스향이 촤악 퍼지면서 달달하고 고소한 쿠키맛이 아우러져서 걍 대존맛입니다 ㅠ', 33, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '처음 삼성역에서 먹어보고 맛있었던 벤스쿠키를 홍대지나가다 보고 왔습니다~ 화이트마카다미아와 다크초코로 샀고 화이트는 가족들과 저녁먹고 나눠먹었는데 달달하고 안느끼해 좋았답니다~ 내일 다크를 먹어보겠습니다^^ 가격도 착하고 생각나면 또 오겠습니다~', 30, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '인생을 더 풍요롭게 만들어주는 쿠키🎵 그 중에서도 벤스쿠키! 얼마전에 갔을때보다 촉촉한 느낌이 강해졌네요. 그러나 맛있다는 점은 변함이 없습니다. 밀크초콜릿 앤 프랄린! 페레*** 초콜릿 내부가 쿠키 안팎에 수놓아져 있네요🤗 부드러운 느낌이 강합니다. 익숙한데 고급스럽고 기분 좋은 맛이에요. 애들이 좋아할 듯! 오트밀레이즌! 이름처럼 오트밀과 건포도가 가득 차 있어요. 시나몬향을 머금고 있어 풍미가 좋습니다. 너무 달지않고 식감도 좋고... 그저 행복합니다🤗🤗', 64, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '전에 처음 먹어보고 반한 벤스쿠키🤎 참새가 방앗간 못지나친다고,,ㅋㅋㅋ 홍대에도 벤스쿠키가 있길래 지난번에 사먹었던걸로 집에 데려왔어요 ㅎㅎ', 2, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '런던있을 때 먹었던 벤스쿠키 발견해서 가게되었어요. 쿠키종류 다양하고 5개구매시 2개추가 상품 구매해서 다양한 종류 나름 저렴하게 먹을 수 있어서 좋아요. 맛도 진하고 달달하네요. 커피랑 먹으면 더 맛있어요.', 40, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '쿠키들이 꾸덕 쫀득해요! 딱 제가 좋아하는 스타일!! 당 떨어질 때 먹으면 딱 일 것 같아요! 그리고 무엇보다 직원분들이 너무 친절하셔서 또 오고 싶은 곳이에요!! 쿠키 종류가 너무너무 많아서 고르는데 힘들었어요ㅠㅠㅠ 조금씩 사먹으면서 도장깨기 하려구요🥰❤️', 9, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '무척 맛있네요~ 근데 다름 리뷰에 있는거 처럼 겉바속촉은 아니고 그냥 꾸덕속촉이예요. 날이 덥고, 습도가 높아서 그런가봐요~~', 13, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '드디어 연남에 벤스쿠키가 ㅠㅠ!! 출구 바로 앞에 생겨서 꼭 잊지 않고 사갈 수 있을 것 같아요!! 맨날 코엑스나 압구정 가서만 사먹었는데 ㅜㅜㅜㅜ 쿠키는 진짜 말할 것도 없이 너무 맛있어서 기절 😫🚨마카다미아랑 코코넛 밀크초콜렛 강추입니다!!', 26, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '홍대 주변에 갈 때마다 들르려고 하는 곳이에요 겉바속촉의 정석이자 겉바속촉 그 잡채입니다 겉은 파삭하게 부서지나 너무 과하지 않고 파삭!!!!!!이 아니라 (파사악ㅡ😘) 이 느낌 속은 촉촉과 꾸덕이 딱 알맞게 조화로워요 빈틈을 찾을 수 없을 정도로 속이 꽉 차있는건 덤 사진은 밀크초콜릿 & 오렌지예요 향긋한 오렌지가 초코랑 기분 좋게 어우러져요', 26, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '극강의 달콤함💛 당 처돌이라 저는 넘모 조와요..🤭🫶🏻 홍입 3출로 나오면 바로 코너에 있어서 집 갈 때 종류별로 사왔는데 화이트 마카다미아 젤로 조타룽✨❤️', 43, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '과거 투태원에 아주 작은 가게때부터 매우 맛있게 먹던 쿠키 입니다. 2000원이었던가 했는데 오랜만에 보고 반갑게 들어갔네요. 연남점 방문했는데 스태프분들 아주 친절하시고 마카다미아 하나 사고 다른거 추천받아 구매했습니다.  틴케이스도 예뻐서 선물용으로 좋은 듯 합니다. 번창하세오오', 88, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '오렌지 쿠키 향이 너무 강해서 같이 포장해둔 쿠키들에서 싹다 오렌지 향이 나서 아쉬웠어요..ㅠㅠ 화이트 마카다미아가 제일 맛있었어요', 48, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '영국  옥스포드대학 앞에서 먹었던 벤스쿠키 이태원이태원ㅇㅔ 몇년전 오픈해서 정말 반가웠는데 드뎌 연남동에 오픈오픈했네요..부드러우면서 달달함의 극치를 이루는 쿠키의 대명사..마카다미아 초콜릿이랑 코코넛쿠키 샀는데 역시나 최고입니다..달달한 쿠키좋아하시는분 달려가세요', 26, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '항상 맛있게 먹는 벤스쿠키입니다 코엑스만 갔지 연남점은 처음 이용해보았는데 친절하고 매장도 깨끗하네요 오며가며 자주 갈 듯 해요 ㅎㅎ', 25, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '와 쿠키 맛있어요, 넘 지도 않고 적당한 단맛에 쿠키도 촉촉하고 맛도 다양해서 좋아요ㅎㅎㅎ 실온에서 보관 4일 정도 가능하네용ㅎㅎ 자주 가서 사먹을거 같아용', 60, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '쿠키 맛집... 이태원점에서 먹어보고 연남점도 생겼다해서 바로 방문! 틴케이스 세트로 샀는데 맛있고 눈도 즐거워서 후회 없습니다 🍪', 25, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '역에서 나와서 술집을 찾아가는길에 눈의 띄어서 무심결에 들어갔는데 화이트 초코 마카다미아,,절대 못참지 녹차랑 같이 구매를 했습니다 안에는 정말 촉촉하니 맛있네요 ㅠㅠ왜 2개만 샀을까,,', 150, 44, 'GOOD', SYSTIMESTAMP);
