INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '카카오톡 선물하기에서 받아본 벤스쿠키를 직접 살수있어서 좋았네요~~가격이 저렴하진않지만 맛있어서 또 사게되는 벤스쿠키네용~~♡', 45, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '지나가다 보여서 들어가봤는데 쿠키 종류도 다양하고 균일가(3,300원)더라구요- 화이트초콜릿 맛이 강해 무지 달지만 맛있게 먹었어요😃', 16, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '이태원에도 있는데 연남에도 생겼길래 포장해왔어요. 5개 사면 2개 더 고르니 연남동에 쿠키가게 많이 생겼는데 솔직히 다 거기서 거기거든요? 그거 생각하면 벤스쿠키가 짱이에요 벤스쿠키 예전에는 비싸다고 생각했는데 이제는 싸다고 좋아하면서 사다니.. 근데 벤스쿠키는 원래 맛있습니다. 기분 안좋은 날 먹는겁니다.', 2, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '그냥 지나칠 수 없게 만드는 귀요미 쿠키 가게가 생겼네요. 5개 구매하면 서비스 쿠키 2개 받을 수 있어서 5개 구매해봤어요~', 65, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '마카다미아 쿠키 찾다가 매장이 보여서 들어가 봄.... 친절하고 쿠키 종류 다양했는데 제가 기대한 맛은 아니네요 ㅜㅜ 쿠키가 얇고 마카다미아가 거의 안들었음', 83, 18, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '친구들 선물로 사갔는데 케이스도 너무 예쁘고 다들 맛있다고 패닉했어요... 선물한 보람이 넘치네요 맛있다고 비명지르는 애들 보고 다른 애들도 먹자고하고 그런 상황이 됐습니다 이 혼란을 저만 겪을 순 없으니 여러분도 사드시고 친구 입에도 넣으세요', 10, 5, 'GOOD', SYSTIMESTAMP);
