INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '벤스쿠키 연남점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '너무 맛어요~ 마카다미아 쿠키는 정말 꿀맛이었어요~^^ 단 거 별로 안좋아하는데 다양한 종류가 있고 선물하기에도 참 좋은 아이템이어요~ 더 사올 것을~^^', 25, 5, 'GOOD', SYSTIMESTAMP);
