INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '모든 공간의 조명이나 인테리어, 카페 디자인 요소들이 전부 취향입니다. 넓고 쾌적하고 깔끔한데 편안하고 집중이 잘 돼서 작업하거나 책 읽기 너무 좋은 것 같아요. 예쁜 디저트와 맛있는 음료, 정갈하고 감각적인 플레이팅이 아주 힐링되고 행복해집니다..🤍 다음에 또 오고싶어요! 다른 음료들과 디저트를 꼭 함께 맛보고 싶습니다 :)', 0, 8, 'GOOD', SYSTIMESTAMP);
