INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '날씨가 너무더워도 맛있는커피를 꼭 마시고자 우린 홍대로 gogo🥰오늘 도착한 커피맛집은 💙소각💙카페입니다 ❤️1층에 통창으로 뷰가예쁘고 이색적인 음악이 흐르고있어서  저절로 힐링 💙💚🥰 이곳  시그니처 독점 메뉴는  피치우롱 스파클링은  새콤하고 여름에딱맞는 힐링 음료👍👍👍카페라떼와 흑임자빙수 주문했어요ㆍ 이곳은 흑임자빙수도  달지않고  담백하고 건강한맛 최고입니다🫰🫰🫰사장님의 커피철학이 묻어있는곳 특별함을   원하신다면 한번 방문 추천요👍👍👍사장님 친절하고 매장도 온화느낌 넘좋아요🤩🤩❤️  이곳은 또  메뉴도 다양해요ㆍ케이크  마들렌흑임자 라떼  수박주스 크림라떼  아인슈패너  흑임자라떼    담번에  또다른 메뉴도 경험해보고싶고 이곳은 홍대역1번출구에서  400미터이니  한번 방문해보세요🥰🥰', 38, 4, 'GOOD', SYSTIMESTAMP);
