INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), 'ㄲㅑ✨ 요즘 흔한 디저트만 있는 카페들이 많은데 디저트 비주얼 보고 여긴 무조건 가야된다고 생각했던 카페에요! 디저트 너무너무 예쁘고 복숭아 음료 징짜 굳!!👍✨ 비주얼도 너무 좋고 노트북 작업하기도 정말 좋을거같아요! 재방문 의사 5000000%💖', 9, 2, 'GOOD', SYSTIMESTAMP);
