INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '마음의 안정을 찾고 싶을 때와서 맛있는 차와 디저트 먹으며 힐링하기 좋은 곳이였어요!!_ 소각케이크 3가지맛 다 맛있고 케이크안에 또 다른맛들이 있으니 시켜먹어보세요~~!! 사라지는 촛불들 보면서 내마음의 짐도 같이 날려보내고 좋습니다!', 44, 9, 'GOOD', SYSTIMESTAMP);
