INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '케익을 주문하면 심지에 초를 붙여주는 서비스 덕분에 생일 등의 기념일날 지인과 방문하기 좋네요^^ 인절미맛 소각케이크와 말차라떼, 아인슈패너, 흑임자크림라떼, 디카페인라떼 주문해서 디저트 타임 잘하고 왔어요🤩', 45, 5, 'GOOD', SYSTIMESTAMP);
