INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '깔끔하고 감성적인 공간에서 행복한 주말을 보냈어요 🤍 매장 앞 푸릇한 나무 덕에 힐링이 되는 곳이에요. 커피도 맛있고 디카페인 원두도 맛있어서 너무 만족,, 디카페인 맛있는곳 귀해요,,✨️ 귀엽고 맛있는  무스케이크까지 전 추천이에요!!', 45, 0, 'GOOD', SYSTIMESTAMP);
