INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '내부 분위기도 좋고 직원 분들도 친절하시고 좋았어요 커피도 깔끔하니 맛있었는데, 디저트도 초코가 찐하니 무스 케이크라 너무 맛있었어요 홍대 조용하고 디저트 맛있는 카페 찾으시는 분들께 추천 드립니다.', 28, 3, 'GOOD', SYSTIMESTAMP);
