INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '출근을 일찍 해서 잠깐 머물다 갈 근처 카페를 찾다가 알게 됐어요! 이 근처를 1년 넘게 다니면서 이런 카페가 있는걸 오늘 처음 알게 됐어요! 생각과 걱정이 많은 저는 말그대로 생각을 소각시켜야될 일이 가장 필요하고 중요한데 여러모로 컨셉을 잘 잡으신거 같아요! 먹다가 멍때리다 보면 잠깐 아무 생각이 안 들었어요! 무스케이크 주문하면 캔들에 초를 붙여주시는데 뭔가 초를 자주 키진 않다보니 케이크가 특별해보이고 제 스스로도 여기 있을땐 뭔가 특별한 순간을 보낼수 있는 그런 기분 좋은 착각을 하게 된달까요,, 지금 알게된게 정말 아쉽지만 늦게 알게 된 만큼 다음에 또 오겠습니다! 저는 인절미 무스에다 아메리카노 마셨는데 케이크의 고소함과 커피 자체의 적당히 살짝 들어간듯한 산미가 조화로웠어요! 잘 먹고 갑니다!', 49, 4, 'GOOD', SYSTIMESTAMP);
