INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '컨셉도 특이하고, 거기에 어울리는 디저트가 특색있었던 곳이었어요. 소각케이크는 초를 붙여주시는데, 그래서 더 분위기있고, 기억에 남더라구요. 블랙오크아인슈페너도 시나몬풍미 가득해서 넘 맛있었어요. 집중하기 좋은 분위기에 디저트와 음료 모두 특색있고 맛있어서 또 방문하고 싶은 곳이에요.', 45, 6, 'GOOD', SYSTIMESTAMP);
