INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '오랜만에 또 왓는데 활기찬 사장님과 섬세한 서비스 너무 감사합니다!! 디저트는 처음인데 인절미케이크 넘나 맛있구요 커피는 필터커피 추천드립니다 게이샤 이 비싼걸 ㄷㄷ 가격이 너무 착하네요 재방문 의사 10000%', 8, 2, 'GOOD', SYSTIMESTAMP);
