INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '커피가 맛있다고 해서 들어왔는데 카페 인테리어랑 분위기 등이 너무 좋아서 다음에 또 오고싶네요 마들렌이랑 인절미 케이크도 너무 맛있고 시그니처 커피 2종류 주문했는데 특히 흑임자가 너무 고소해서 계속 생각나는 맛입니다 추가로 흑임자마들렌 추천합니다 정말 고소해요~', 50, 7, 'GOOD', SYSTIMESTAMP);
