INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '인터넷에서 홍대 카페 검색해서 보다가 캔들 케이크가 신기하고 궁금해서 와봤어요! ㅎㅎ 너무 아늑하고 분위기가 좋아요 ㅠ 아메리카노 산미도 선택할 수 있어서 좋았고 케이크도 맛있었습니당~ 덕분에 힐링 듬뿍했어요 ♥', 35, 3, 'GOOD', SYSTIMESTAMP);
