INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '멋진 장소와 멋진 메뉴들이 있는 카페입니다 ,,^^ 말차 레몬 스파클링이 매우 궁금하여 주문했는데,, 독특하고 맛있습니다,,, 다음엔 케이크에 태우는 것도 해보고 싶으네요,,^^ 잘 먹고 갑니다,,,', 40, 10, 'GOOD', SYSTIMESTAMP);
