INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '저희 단골카페 소각인데, 이번에 이벤트 만드셨더라구요!!! 케이크 사면 할 수 있는데 저희는 음료1잔 무료로 당첨됐어용!!!! 여기 분위기도 너무 좋고 수박주스가 진짜 유명한데 꼭 드셔보세용!! 흑임자 빙수도 새로 나왔다고 해서 먹어봤는데 너무 맛있어요 ㅠㅠ 사장님도 너무 친절하시고 더 번창하시면 좋겠어서 진심으로 남깁니다 🫶🏻🫶🏻', 34, 10, 'GOOD', SYSTIMESTAMP);
