INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '홍대입구역 작업하기 좋은 느좋 카페 발견🌱 지나가다가 발견했는데, 분위기도 너무 좋고 통창이어서 탁 트인 느낌이에요:) 원두는 고소한 것과 산미있는 것 중에 선택할 수 있어서 좋았어요! 아이스 아메리카노와 초콜릿 무스 케이크 주문했는데, 무스케이크에 초를 붙여주셔서 하루가 특별해진 기분이었네요✨ 진한 초코와 헤이즐넛, 땅콩의 조합이 잘 어울렸고, 꾸덕달달해서 아메리카노와 찰떡궁합이었답니다. 밖이 보이는 자리에 앉아 여름을 잔뜩 만끽하고 왔네요! 불필요한 것들을 내려놓고 온전히 나 자신을 받아들이는 공간이라는 소각이라는 컨셉도 너무 좋았어요🤍', 34, 0, 'GOOD', SYSTIMESTAMP);
