INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '분위기를 너무 좋아하는데, 카페 무드가 너무 편안하고 좋고, 사장님의 세심한 취향 하나하나가 너무 눈에 들어와요 좋은 사람과 함께오면 행복해질것 같아요! 커피도 물론 맛있습니다:) 최애카페 1순위가 될것 같아요', 111, 26, 'GOOD', SYSTIMESTAMP);
