INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '카페 분위기가 너무 아늑하고 차분해서 잠시 쉬어가기 딱 좋았어요. 따뜻한 음료와 달콤한 디저트가 함께하니 피로가 풀리는 기분이었고, 워드서치 게임도 즐거웠습니다. 소확행 같은 시간, 다음에도 꼭 다시 오고 싶어요!', 0, 4, 'GOOD', SYSTIMESTAMP);
