INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '아메리카노 아이스를 주문했고, 소각 케이크 말차 맛도 함께 먹어봤어요. 커피는 깔끔하고 산미가 적당해서 마시기 좋았고, 케이크는 너무 달지 않아서 정말 입에 잘 맞았어요. 말차 향도 은은하고 식감도 부드러워서 커피랑 잘 어울려요. 달지 않은 디저트를 좋아하신다면 추천합니다!', 1, 1, 'GOOD', SYSTIMESTAMP);
