INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '서울 놀러 왔다 친구 만나기 전 시간이 남아 급하게 홍대카페 검색하고 들어온 곳인데 분위기도 좋고 커피도 너무 맛있어요!! 인테리어도 예쁘고 노래마저 취향저격! 직원분? 사장님?도 너무 친절하셔서 기분 좋은 여행 시작이네요. 감사합니다🫶🏻', 68, 13, 'GOOD', SYSTIMESTAMP);
