INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '또 방문하는 분위기 좋은 홍대카페 소각커피… 매번 이벤트가 늘어나네요 ㅎㅎㅎ 강아지증명사진 가챠가 생겼어요!! 케이크 다른 맛 먹어보러 왔다가 무료 음료까지 ㅎㅎ 나만 알고싶은 카페임니당💛 조용하고 맛있는 소각커피…흥해랏', 112, 20, 'GOOD', SYSTIMESTAMP);
