INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '·˚ ༘ ꒰ 🐾〻‧ 여기 지나치면 바보 🕯️🖤❀༉‧˚ 쩝쩝박사로서 소각은 맛도리의 권위자 수박주스 진짜진짜 걍 당도 100 수박 그 잡채입니다요 꼭 제발 드세요 . 흑임자빙수는 긴 말 하지 않겠습니다 사진으로 이미 설명 완료 . . 케이쿠먹으면 저런 귀요미 사진도 겟 할 수 있슴다 🥹', 45, 7, 'GOOD', SYSTIMESTAMP);
