INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '오랜만에 만나는 분들이랑 밥 먹고 산책하다가 분위기가 너무 좋아 보여서 들어왔어요! 메뉴도 너무 예쁘고 맛있어요. 저는 말차레몬스파클링이란 신메뉴 주문했는데 음료가 너무 예쁘고 상큼해요😀 바닐라무스케이크도 주문했는데 초도 붙여 주셨어요 ㅋㅋ 안에 커피크림?도 들어 있어서 안 달고 맛있어용 ㅎㅎ 낱말퍼즐 종이도 주시고 같이 온 분들이랑 이런저런 할 것도 많아서 재밌었어요. 케이크 주문하고 뽑기도 뽑았어요 ㅋㅋㅋ 탱탱볼이 나왔답니다~~~~~', 16, 10, 'GOOD', SYSTIMESTAMP);
