INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '카페 검색해서 찾아왔는데 어둑하고 아늑한 카페 분위기 제 스타일이에요 ㅎㅎ 사장님 넘 친절하세요! ㅎㅎ 커피, 디저트도 맛있고 친구들이랑 시간 잘 보내다 가용 :)', 52, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '명상코스로 방문했는데 정신없는 일상 속에서 잠시 쉬어가는 시간으로 너무 좋았습니다. 명상코스는 정말 추천드려요. 디저트도 너무 맛있고 평펌하지 않은 새로운 맛과 모양이에요! 커피도 드립커피로 제공되었는데 맛이 깊고 풍부했어요!', 19, 7, 'GOOD', SYSTIMESTAMP);
