INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '근처 볼일이 있어서 왔다가 주변 카페를 검색해서 왔어요 소각 커피 이름을 보자마자 소각 소각 이런 느낌이었는데 소각장이라는 의미를 되새겨보니 공간이 주는 분위기에 편안해졌어요 커피도 맛있고 분위기도 너무 좋아요 주차장도 마련되어 있어서 차로 방문하기도 편리하네요', 13, 4, 'GOOD', SYSTIMESTAMP);
