INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '남자친구랑 데이트 중 우연히 들어오게 된 카페인데 우리집 멍뭉이 가방 밖으로 꺼내도되고 물도 챙겨주셔서 너무 좋았어요!!🙂 홍대 오게된다면 다음에 또 들르고싶은 카페에요!', 89, 17, 'GOOD', SYSTIMESTAMP);
