INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '치열하게 살아온 일상을 뒤로 하고 혼자 떠나온 서울여행에서 어쩌다 마주친 공간. 더위를 식힐 겸 들어섰지만 추천받은 명상코스를 이용해보며, 바쁜 일상 속에 미뤄뒀던 생각을 잠시나마 정리해볼 수 있어서 좋았다. 향긋한 커피와 달콤한 케이크, 친절한 사장님 덕분에 편하게 쉬어갈 수 있었다. 치열한 일상 속 아늑한 휴식에 감사한 경험이었다 : )', 27, 3, 'GOOD', SYSTIMESTAMP);
