INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '친구랑 강아지랑 같이 왔어요. :) 소각이 소각하다- 의미더라구요. 일주일동안 쌓인 업무 스트레스, 사람 스트레스 여기에서 다 소각하고 갑니다! 커피도 에이드도 맛있어요. 또 올게요~', 50, 1, 'GOOD', SYSTIMESTAMP);
