INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '직원분들이 친절하고 디저트도 너무 맛있어요! 마차 레몬 스파클링은 처음 먹어보는 맛인데 특이하고 맛있어요! 마차 좋아하시는 분들 마차라떼 대신 도전해보세요 :)', 2, 5, 'GOOD', SYSTIMESTAMP);
