INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '햇빛이 좋아서 사진이 엄청 예쁘게 나와요!!! 그리고 바깥에 보이는 초록초록한 모습이랑 카페 내부 인테리어랑 너무 잘 어울려서 있는 동안 완전 힐링하고 갑니당 음료도 너무너무 예쁘고 맛있었어요ㅎㅎㅎㅎㅎㅎㅎ', 114, 19, 'GOOD', SYSTIMESTAMP);
