INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '회사 근처인데 사각초가 예뻐보여서 한번 와 보고 싶었거든요. 옆 스벅만 왔다갔다 했는데, 사람도 비교적 적고 혼자 생각 정리하기 좋은 평일이네요 오늘 안그래도 심적으로 힘들었는데, 잊어야할 내용 적고 소각해버리는 이벤트가 있네요ㅎㅎ 맛있는 커피도 마시고 떨쳐내야할 스트레스는 벗어던지러 온 기분~힐링 하고 갈게여', 16, 6, 'GOOD', SYSTIMESTAMP);
