INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '진짜 너무 더워서 주변카페를 찾다 들어갔는데 주문한 메뉴가 나오고부터 사장님의 섬세함이 엄청 느껴졌습니당 단어찾기랑 뽑기랑 편안하고 심심하지 않게 보내다가라는 여러 세심한 장치가….! 원두 맛도 두개중에 고를수 있고 보이는 바깥뷰도 예쁘고 넘 좋네용', 15, 0, 'GOOD', SYSTIMESTAMP);
