INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '흑임자 라떼가 시그니처라 먹어봤는데 너무 고소하고 너무 맛있었어요 이거 먹으러 또 올거 같아요! 주문하면 주시는 진동벨? 같은것도 네모네모해서 너무 귀여웠어요😻', 127, 20, 'GOOD', SYSTIMESTAMP);
