INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '분위기가 좋고 커피도 맛있어요 살짝 조도 낮고 개방감있어서 마음이 편안하더라구요 스토쿠나 소각할 메세지 적는거나 잠깐 20분정도라도 휴대폰 안보고 생각할 시간을 갖게되서 좋았어요! 우연히 지나가다 분위기 좋아보여서 들어온건데 잘먹고갑니다!', 1, 3, 'GOOD', SYSTIMESTAMP);
