INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '정신없는 거리 걷다가 소각커피 딱 들어오자마자 마음에 평화가 찾아옵니다 ㅋㅋ 절제된 인테리어랑 은은한 무드등이 차분함을 주고 좌석 공간도 넓어서 시장느낌 안나서 좋아요 물론 디저트와 커피도 맛있어서 완전 만족합니다 👍👍', 129, 21, 'GOOD', SYSTIMESTAMP);
