INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '회사근처 카페라 지나다니면서 들어와보고 싶었는데 비오는날~ 추천입니다!! 스피커도 좋아 음악듣기 딱좋은 곳이네요~ 여백의 미가 기분좋게 느껴지는 카페인데 커피맛도 좋네요~', 11, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '카페가 아늑하고 조용해서 부담없이 앉아있기 편합니다~ 빙수도 친근하고 익숙한데 이색적인 느낌이예요 👍 깔끔하고 아늑하고 조용한 카페를 찾으시면다면 추천합니다^^', 37, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '가득한 카페에 와서 기분이 좋습니다 강아지도 가능해서 자주 와도 되겠게영 커피가 맛있고 케이크도 달달하지 않아서 잘 먹었습니당!', 1, 9, 'GOOD', SYSTIMESTAMP);
