INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '새롭지만 이쁜 카페!! 소각한다는 의미로 명상할 수도 있고 조용히 작업도 하고 쉬어갈 수 있는 공간이었습니당 커피도 맛있고, 대부분이 사각으로 이루어진 인테리어도 이뻤어요!', 48, 3, 'GOOD', SYSTIMESTAMP);
