INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '소각 이라는 이름에 맞게 오늘 버리고 싶은 메세지를 소각 할 수 있어요. 카페에 와서 이런저런 얘기 하기 보다는 가끔씩 자신을 돌아 보는 시간도 필요한데 글을 쓸 수 있는 카페가 있어서 좋았어요! 마들렌도 너무 맛있어용', 23, 9, NULL, SYSTIMESTAMP);
