INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '와우~ 커피도 넘 예쁘게 담아주시고,  케이크도 넘 예뻐요!^^ 직원분이 맛있게 먹는 방법도 알려주시고 넘 친절하세요!! 음료도 맛있어요!^^', 38, 9, 'GOOD', SYSTIMESTAMP);
