INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '홍대에서 괜찮은 카페찾아보다가 들렸는데 정말 너무 만족스러워요 내부는 우드톤에 깔끔한 인테리어라 차분하게 머물기 좋고 자리도 적당히 있어서 대화하기 좋아요 그리고 피치 우롱 스파클링이 어디서 먹어보지못한 맛으로 진짜 너무 맛있었어요 더위가 싹 내려가는 기분이에요 앞으로 홍대오면 무조건 여기만 올 것같아요 ☺️', 104, 21, 'GOOD', SYSTIMESTAMP);
