INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '돌아다니다가 우연히 마주쳐서 방문했는데 너무 좋았습니다...🖤🤍 케이크가 독특하고 귀여워요! 맛도 너무 좋고 커피랑 잘 어울렸어용!! 메뉴 주문하면 사장님께서 직접 가져다주시는데 정말 친절하십니다... 혼자 오기에도 좋은 것 같아요🖤 다음에 또 오고 싶어요 진짜‼️‼️', 19, 4, 'GOOD', SYSTIMESTAMP);
