INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '집 근처에 새로운 카페가 생겼길래 밥먹구 지나가다 들어 옴 문이 너무 시원하게 열려있어서 우리보고 들어오라고 하는 것 같아요ㅋㅋㅋ 개방성이 있어서 지나가는 사람 구경하는 재미가 있어요 의자도 푹신함 헤헤 산미 하나 고소 하나 시켰는데 커피도 맛있네요☺️ 소각케이크도 궁금함..', 41, 1, 'GOOD', SYSTIMESTAMP);
