INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '아늑하면서 깔끔한 매장 내부에 주문한 흑임자크림라떼, 애플캐모마일, 초코소각케이크까지 다 맛있어요😊 사장님,직원분도 모두 친절하셔서 편하게 카페타임하고 갔어요☺️🤩무조건 재방문각이에요👍👍', 59, 13, 'GOOD', SYSTIMESTAMP);
