INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '독특한 분위기의 카페에요! 차분하면서도 생기있는? 느낌이에요. 커피 원두를 선택할 수 있는데 고소한 원두 추천 ! 최근 먹어본 커피 중에 맛있어요 👍', 103, 26, 'GOOD', SYSTIMESTAMP);
