INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '오크향 나는 시그니처 메뉴 블랙오크 아인슈페너가 인상적이었어요. 시나몬 향이 강하지 않고 부드럽게 어우러졌고, 크림과 함께 먹는 조합도 훌륭했습니다. 진동벨 대신 무드등을 사용하는 점, 직접 음료를 가져다주는 서비스가 독특하고 좋았어요. 소각할 메시지를 적는 감성적인 공간 연출도 인상 깊었습니다. 통유리창과 생화 장식이 분위기를 더해 데이트 코스로도 추천해요.', 25, 0, 'GOOD', SYSTIMESTAMP);
