INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '너무 오고싶었던 곳이었는데 생일 기념으로 와봤습니다!! 매장 분위기도 화이트 우드톤이어서 차분해지는 느낌도 들고 음료도 맛있고 커피도 맛있고 케이크도 너무 귀엽고 맛있어요!!', 47, 3, 'GOOD', SYSTIMESTAMP);
