INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '주차가능/애견동반 가능한 작업카페를 찾다가 방문했습니다. 직원분들 너무 친절하세요! 음료 맛있고 매장도 넘 깨끗합니다! 또 방문할게요 😍', 38, 8, 'GOOD', SYSTIMESTAMP);
