INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '홍대 동교동카페 <소각커피> 날씨 좋은날 방문하기 좋은 카페입니다. 통유리라 조도가 뛰어난만큼 햇살즐기기 좋은 카페입니다. 사장님. 매우 친절하시고 커피까지 너무 맛있습니다. 만족스럽게 즐기다 갑니다 ^^', 33, 8, 'GOOD', SYSTIMESTAMP);
