INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '홍대에서 식사하고 근처 카페 찾다가 들어왔는데 분위기도 아늑하고 매장이 깨끗해서 너무 좋았습니다 ㅎㅎ 맛도 맛이지만 일단 메뉴들이 특별한게 많았고 케이크도 아기자기하고 적당히 달달해서 더 좋더라구요!! 시끄럽지 않고, 과하지 않은 잔잔한 카페를 찾고있다면 소각커피 추천합니다~ 덕분에 가족들과 좋은 시간 보내고 있어요 감사합니다☺️', 21, 8, 'GOOD', SYSTIMESTAMP);
