INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '친구랑 홍대에서 점심 먹고 찾은 카페. 청결하고 화이트톤과 원목의 분위기가 아주 잘 어울리는 소각. 사장님도 친절하고 음료도 케익도 너무 맛나요. 다음에 또 찾아 올듯합니다.', 12, 0, 'GOOD', SYSTIMESTAMP);
