INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '홍대입구역 북적이는 번화가에서 한발자국 벗어나면 만날 수 있는 깔끔한 인테리어 속 여백의 미를 느낄 수 있는 신상카페 소각 홍대입구역에서 성산동으로 넘어가는 큰 길가에 자리 잡은 카페 소각 큰 길가 바쁘게 일상을 보내고 있는 사람들을 보며 잠깐의 여유로움을 즐길 수 있는 쉼터 같은 공간 화려한 오브제는 없이 깔끔함과 잔잔하면서도 몽환적인 음악으로 공간을 채워, 여럿보단 혼자만의 시간을 보내기에 추천드린다. 아직은 핸드드립커피는 없지만 추 후 준비가 될 예정이니 기대를 하셔도 좋을듯하다. 말차와 인절미, 초코와 헤이즐넛의 소각 케이크라는 계속해서 손이 가는 마성을 가진 아이스크림 케이크도 커피와 함께 즐겨보시면 좋을듯하다🍰 더 자세한 정보는 최제로 블로그🙇🏻‍♂️🌼', 3, 3, 'GOOD', SYSTIMESTAMP);
