INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '말차조각케이크는 인절미 맛이 진하고 안에 들어있는 말차의 진한맛이 잘 어울리더라고요. 초로 소각한다는 컨셉도 좋고 분위기 좋아요🩷', 73, 15, 'GOOD', SYSTIMESTAMP);
