INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '회사 근처에 새로 생겨서 방문해봤는데 인테리어도 좋고 분위기도 좋아요! 시그니처 커피인 흑임자 라떼 먹어봤는데 고소하고 맛있어요!! 재방문의사 있습니당👍🏻', 72, 12, 'GOOD', SYSTIMESTAMP);
