INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '여자친구랑 홍대 놀러와서 와봣는데 시그니쳐 메뉴 두종류랑 주사위 모양 케잌이 맛있었어요 !! 다음에 또 올일 있으면 또 올것 같아용 ㅎㅎ 여자친구는 블랙오크 아인슈페너의 로즈마리가 킥이라고 하네요 !', 33, 8, 'GOOD', SYSTIMESTAMP);
