INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '홍대 나왓다가 꼭 와보고 싶었던 소각에 딸램이랑 들렀어요^^ 커피맛은 기대한 만큼 훌륭했고 수박주스는 기대보다 더 맛있네용^^ 딸이 한잔 얼른 마시고 한잔 더 주문한건 안비밀요😉 차분한 분위기에 맛있는 커피와 디져트 일산에서 찾아오길 매우 잘한거 같아요 남편데리고 다시 올께요😎', 38, 7, 'GOOD', SYSTIMESTAMP);
