INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '스터디하기전 들린 분좋카 카페입니다~~~ 새로생겼다해서 궁금반 호기심반으로 들어왔는데 커피맛에 반했어요🩷 카푸치노 추천드립니다! 바테이블도 있어서 분위기 진짜좋아요', 40, 9, 'GOOD', SYSTIMESTAMP);
