INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '분위기도 너무 좋고 감성적인 느낌이 생각을 정리하고 대화하기 좋았어요! 보통 이런 카페는 커피나 디저트가 맛없는 경우도 있는데 커피 산미도 선택 가능하고 디저트도 많이 달지도 않고 맛있었어요! 다음에 또 오고 싶어요!', 244, 61, 'GOOD', SYSTIMESTAMP);
