INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '특별한 케이크가 있어서 좋았어요! 소원 종이도 적으면서 더 특별했던 것 같아요 :-) 커피도 맛있고 디저트도 맛있어요! 감사합니다🤍', 6, 6, 'GOOD', SYSTIMESTAMP);
