INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '홍대 여백의 미가 돋보이는 정갈한 인테리어의 카페🔥 우드 가구들이 진열된 무채색 인테리어 속, 사색 즐기기 좋은 ‘태우고 비우는 쉼의 공간’. 통창 너머 대로변의 풍경을 감상하거나, 몽환적인 음악과 함께 혼자만의 시간을 보내기 좋아 노트북이나 책 한 권 들고 와도 괜찮을 것 같아요 소각에선 화염의 고소함 엠버 블렌드와 불꽃의 산미 블레이즈 브루 원두를 맛볼 수 있고 말차/인절미, 초코/헤이즐넛 등 여러 가지 맛의 소각케이크가 준비되어 있는데 케익은 불도 붙여주셔서 특별한 느낌이었어요! 생일인 친구나 연인 데려가면 좋아할 것 같습니다😊', 25, 4, 'GOOD', SYSTIMESTAMP);
