INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '신상카페라고해서 왔는데 케이크도 부드러운 생초콜릿 느낌으로 찐한 초코맛이 나고 안에는 꾸덕한 헤이즐넛 크림?부분도 있어서 달달하게 맛있게 먹었고 커피는 원두랑 우유도 변경 가능해서 좋았어요! 사장님도 친절하셔서 좋았어용☺️', 16, 1, 'GOOD', SYSTIMESTAMP);
