INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '무척 더웠는데 빙수도 시원하게 맛있게 먹었고, 매장에서 진행하는 글자찾기도 재밌게 했고, 명상하는 것도 너무 좋았어요! 이번엔 친구랑 같이 왔는데, 다음에 혼자서도 와볼 것 같아요!!', 10, 2, 'GOOD', SYSTIMESTAMP);
