INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '우연히 갑자기 행복해지는 소각커피. 커피부터 트레이 컵같은 사소한 디테일부터 컨셉까지 감각을 한가득 느끼고 싶다면 적극 추천합니다', 41, 1, 'GOOD', SYSTIMESTAMP);
