INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '독특한 컨셉의 카페 소각 소각은 카페의 이름처럼 일상의 잡념과 고민을 모두 태워 버릴 수 있는 공간이다. 바쁜 일상 속 잠시 힐링을 하길 원한다면 따뜻한 차 한잔과 소각 케이크를 즐기며 잡념을 모두 태워 버리자..... 카페 소각에선 아메리카노를 선택하면 고소한 맛과 산미를 느낄 수있는 맛 두종류를 선택할 수 있어서 산미있는 커피를 즐기는 사람에게도 매우 좋을 듯하다. 소각케이크를 선택하면 사장님이 직접 초에 불을 붙여 주신다 불이 꺼질때 올라오는 연기를 바라 보는것도 힐링 포인트! 넓은 통창을 통해 바쁘게 지나 다니는 사람과 자동차를 바라보며 향기로운 커피와 달콤한 케이크를 즐기며 힐링 할 수 있는 카페 소각 지치고 힘들다면 꼭 한번 들러 재충전의 시간을 갖는 걸 추천한다.', 17, 8, 'GOOD', SYSTIMESTAMP);
