INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '매번 믿고 먹는 흑임자크림라떼👍🏽 바닐라무스케이크💯 워낙 사람이 많은 동네라.. 홍대에서 차분하게 책읽고 작업하기 좋은 카페 찾기 쉽지 않은데 소각은 언제와도 차분~하니 집중이 잘 되어서 좋아요. 데이트 장소로도 강추해요!', 49, 8, 'GOOD', SYSTIMESTAMP);
