INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '대화하기도 좋고 공간이 개방감 있고 편안했어요!! 좋았습니다 흑임자라떼 너무 맛있어요 단어 찾기도 재밌어요 담에 또 올 것 같아요 짱', 54, 14, 'GOOD', SYSTIMESTAMP);
