INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '모던하면서도 절제미가 넘치는 세련되고 멋진 곳입니다. 우리는 여기 소각에서 흑임자 크림 라떼와 피치 우롱 스파클링을 주문했는데요, 이 메뉴 역시 특별하고 신선한 맛있었습니다. 아늑한 분위기에서 힐링되는 기분으로 사랑하는 사람과 맛있는 음료를 마시니 스트레스가 정말 소각되는 기분이예요... 멋진 곳입니다.', 31, 7, 'GOOD', SYSTIMESTAMP);
