INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '기념일에 남자친구랑 방문했는데 분위기 있고 감성있는 카페였어요! 케이크도 개성있어서 더 맛있었구 사장님도 정말 친절하세요🥹 다음에 꼭 또 오고싶어요ㅠㅠ', 25, 0, 'GOOD', SYSTIMESTAMP);
