INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '제가 케이크 예약을 했는데 회사 일로 제때 픽업을 못했는데 늦은 시간에도 친절하게 케이크 챙겨주셔서 정말 감사했습니다. 중요한 사람에게 주는 케이크였는데 덕분에 기분 좋게 잘 전해줄 수 있었습니다! 정말 감사합니다👍', 54, 13, 'GOOD', SYSTIMESTAMP);
