INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '신상카페에 주차도 가능해서 들려봤는데 조용하고 음악도 좋고 커피도 너무 맛있어요^^ 사장님두 친절하시고 분위기도 너무 좋아서 홍대 오면 또 들릴거예요^^', 8, 2, 'GOOD', SYSTIMESTAMP);
