INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '분위기도 좋고, 무언가 특색있는 공간이라 더 좋았어요. 커피가 정말 맛이 좋았는데, 시그니처 메뉴 정말 만족이었어요. 소각이라는 이름도 신선하였는데, 무언가 마음 비우기를 하기 좋은 공간으로 다가왔어요. 재방문의사 있어요^-^', 30, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '아메리카노+마들렌세트로 주문했는데 맛있는 디저트 조합이라 잘먹었어요😊 오늘도 역시나 친절하시고 편안한 분위기 속에서 혼카 잘하고 갔어요😍', 27, 2, 'GOOD', SYSTIMESTAMP);
