INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '홍대에서 조용한 카페 찾으신다면..소각커피 통창이라 사람들이 지나다니는게 잘 보이는데 멍 때리기도 좋고 분위기도 평화로워서 조용하게 있을 수 있는 카페에요! 라떼..맛집..', 23, 1, 'GOOD', SYSTIMESTAMP);
