INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '회사 다니면서 지나다니면서 보다가 오늘 처음 와봤어요. 천장에 조명이 없이 벽부등으로만 해둔 인테리어가 신박한 것 같고, 소소하게 즐길거리도 있는 것 같네요. 커피 맛도 향도 좋고 다음에 또 올게요', 65, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '명상을 할 수 있는 공간으로 내부가 넓지만 아늑한 분위기가 있으면서 좋아요! 그리고 무엇보다도 디저트 케이크를 주문하면 초를 꽂아 주시고 불도 붙여주셔서 특별한 날이 아니어도 특별한 날이 된거같아 기분이 좋아지는 공간이었습니다 :)', 22, 1, 'GOOD', SYSTIMESTAMP);
