INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '흑임자 크림 라떼 너무 맛있어요🫶🏻 커피도 레몬 마들렌도 맛있고 사장님도 엄청 친절하셔서 자주 올것 같아요! 낮에도 이쁘지만 흐린날이나 저녁에 특히 조명이 돋보여서 연인들이랑 오기에도 딱인것 같아요♥️', 32, 9, 'GOOD', SYSTIMESTAMP);
