INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '비를 피해서 친구들과 소각커피에 들어왔는데 분위기며 인테리어며 너무 예뻤습니다! 무엇보다 커피 맛이 대박적,,,흑임자라떼 대박입니다 제가 먹어본 흑임자커피 중에서 제일 꼬숩고 맛있었어요! 레몬 마들렌도 겉면 파삭하니 너무 맛있구요 흑임자마들렌은 리뷰서비스로 받았는데 역시 미쳤습니다 그냥 이 집 흑임자를 잘해요•• 초코무스케이크도 먹었는데 초까지 붙여주셔서 분위기 대박에 부드럽고 맛나용,,,! 재방문의사 100%입니다', 105, 22, 'GOOD', SYSTIMESTAMP);
