INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '감성 가득한 분위기와 커피의 깊은 맛이 어우러진 곳 소소한 힐링이 필요할 때 찾고 싶은 카페 조용한 공간에서의 커피 한 잔하며 복잡한 하루를 정리하기에 딱 좋은 곳!', 31, 7, 'GOOD', SYSTIMESTAMP);
