INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '조용하고 아늑한 분위기가 좋았숩니당.! 사장님도 친절하시고, 초코무스랑 마들렌은 진하고 부드러워 커피랑 잘 어울렸어욤. ‘오늘 소각하고 싶은 것’을 적는 종이와 단어 찾기 이벤트도 색다르고 좋았어요. 분위기 좋은 혼카, 느좋 카페 찾는 분들께 추천해요!', 130, 25, 'GOOD', SYSTIMESTAMP);
