INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '이런 생뚱맞은 이벤트도 있는 곳이에요 내부는 생각보다 소란스럽긴 한데 특별한 메뉴들이 많이 있어요 소각 해 준다니 특이한 컨셉이긴 해요', 26, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '카페에 혼자 갈 일이 자주 없는 편인데, 혼자 방문하기에도 너무 편안하고 좋았던 공간 ⸜( ◜࿁◝ )⸝ “나”에대해 생각 할 시간이 없는 요즘 오랜맘에 온전히 니를 위한 시간을 가질 수 있었네요 ☕️ 케이크 초가 타서 사리지는 모습을 멍~ 하니 지켜보는 시간도 좋았어요 🕯️✨', 27, 7, 'GOOD', SYSTIMESTAMP);
