INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '헉 밀크티매니아인데 너무맛나네용..? 안달고 흑임자마들렌도 고소고소💚 처음방문했는데 인테리어며 음료며 디저트며 다 넘 취저에요! 단골예약이요 !', 75, 15, 'GOOD', SYSTIMESTAMP);
