INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '인테리어도 예쁜데 커피도 진짜 맛있어요 사람많은 홍대에서 한적하게 즐기기 좋은 카페인 것 같아요 !!! 여기 레몬마들렌도 쫀맛이에요 완전 강추 ,,', 70, 15, 'GOOD', SYSTIMESTAMP);
