INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), 'The coffee was good and the place is very neat and conformable. Specially, I love their cups, espresso cup and saucer and the dish. Things are all very thoughtfully selected and organized.. looked ‘kinda’ too fancy and expensive but it’s actually very reasonable and worth to visit. Definitely my ‘go to’ coffee place!', 36, 9, 'GOOD', SYSTIMESTAMP);
