INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '낮에도 와보고 저녁에도 와봤는데, 낮에는 통창으로 자연광이 들어와서 사진 찍어도 잘나오고 저녁엔 조명이 은은하게 바뀌어서 혼자 책 읽거나 작업하기도 좋을 것 같네요~ 무스케이크 너무 맛있어요! 어디서도 못먹어본 맛!!', 29, 5, 'GOOD', SYSTIMESTAMP);
