INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '분위기가 진짜 좋은데 좋은 와중에 강아지 증명사진 뽑기 있는게 너무 귀여운 고런 카페… 더워서 보이는데 들어온건데 진짜 분좋카 그자체임 ♡', 34, 1, 'GOOD', SYSTIMESTAMP);
