INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '카페가 탁 트이고 너무 깔끔하고 좋아요. 아인슈페너에서 시나몬스틱이 올라갔는데 향이 넘 좋네요❤️❤️ 사장님도 왕친절하심 +주차도 됌 조용하고 짱짱', 9, 10, 'GOOD', SYSTIMESTAMP);
