INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '컨셉이 좋고, 조용히 머물러 갈수 있는 카페입니다. 원두가 맛있어요!  소각이란 주제로 케이크에 불 붙히고 끄는 거 까지 재밋습니다!', 8, 0, 'GOOD', SYSTIMESTAMP);
