INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '영화 보기 전에 잠시 머무를 카페를 찾다가 방문하게 되었어요! 선곡도 잔잔하니 좋았고 바닐라라테와 레몬 마들렌이 아주 맛있었습니다 🍋 좋아하는 책을 가져왔는데 좋은 선택이었어요 꽤 한적해서 책 읽기 좋은 공간인 것 같아요! 작업하기에도 좋을 것 같아요 ! 다음에 또 오고 싶습니다 ♡', 44, 0, 'GOOD', SYSTIMESTAMP);
