INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '한적하고 커피랑 얼그레이티라테 시켰는데 넘 맛있네요~~ 숨은글자찾기 하다가 meditation이랑 sogak이 도저히 안보여서 제 멋대로 찾았네용ㅋㅋㅋ 위 9개 단어 찾으라해서 소각은 큰글자로 메디테이션은 아래 설명으로 찾아버렸습니닼ㅋㅋㅋ 남편이랑 재밌게 놀다 갑니당:) 번창하세요~', 23, 0, 'GOOD', SYSTIMESTAMP);
