INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '소각소각 작업하기 좋고 친구랑 수다 떨려고 왔는데 커피도 맛있고 부위기가 좋아요!! 스도쿠도 재밌고 오늘 소각할 메시지도 좋았어요!!! 걱정이 좀 덜어지는 기분이에요~', 58, 12, 'GOOD', SYSTIMESTAMP);
