INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '# 🌟 홍대에 숨은 감성 카페 ''소각'' 다녀왔어요! 어제 친구랑 새로 오픈했다는 카페 ''소각'' 다녀왔는데 완전 강추임!! 인스타 감성 가득한 이 곳 꼭 가보세요 ㅠㅠ ## 🏠 분위기 들어가자마자 인테리어가 너무 예뻐서 사진 찍느라 정신 없었어요ㅋㅋㅋ 요즘 흔한 카페 느낌 말고 확실히 차별화된 감성이 있더라구요! 창가 자리는 햇살이 완전 예쁘게 들어와서 인생샷 건질 수 있어요📸✨ ### 피치 우롱 스파클링 이거 마시려고 또 갈 것 같아요... 우롱차 베이스에 복숭아 향이 은은하게 퍼지는데 거기에 탄산 더해져서 청량함 폭발! 여름에 마시면 더 맛있을 것 같은데, 벌써부터 단골 메뉴가 될 듯ㅎㅎ 너무 달지 않고 티 베이스라 이것만 마셔도 행복해요🥰', 17, 6, 'GOOD', SYSTIMESTAMP);
