INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '디저트 종류는 몇없지만 서비스로 주신 레몬마들렌도 바닐라무스케이크도 맛있었어요. 수박주스도 맛있었는지 먹다가 테이크아웃해서 갔는데 끝까지 다 먹을 정도였고 공간도 좋았습니다', 87, 16, 'GOOD', SYSTIMESTAMP);
