INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '카페 분위기가 따뜻하고 차분해서 좋네요! 커피맛도 좋습니다. 그리고 소각이라는 이름처럼 자기 고민거리를 제공하는 종이에 적어서 소각해주는 서비스가 있고, 낱말 풀이도 줘서 재밌네요:)', 95, 24, 'GOOD', SYSTIMESTAMP);
