INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '재방문각!!❤️ 세련된 느낌 +맛까지 세련 👏👏 커피 자체가 고급스럽고 신선그자체입니다 오늘 픽 완전 나이스사장님의 서비스는 쌍따봉', 27, 2, 'GOOD', SYSTIMESTAMP);
