INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '감각적인 카페에요:) 식물 우드 인테리어가 편안한 느낌이에요! 퀴즈도 풀고 이벤트로 마들렌도 주시고 즐거운 공간 맛있는 공간이였습니다!!! 또 방문할게요!!!! 해삐!', 107, 23, 'GOOD', SYSTIMESTAMP);
