INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '수박음료를 마셨어요. 진짜 생 수박 먹는 것 같아요. 시럽없이 생 수박만 갈아주시는 느낌!! 카페 분위기 짱짱 좋고 올 때 마다 직원분들이 너무 친절해서 너무 좋아요. 홍대 올 때 마다 항상 소각에 와요 ㅎㅎ', 49, 5, 'GOOD', SYSTIMESTAMP);
