INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '스타벅스 가기전 홀린듯 이끌려 들어간곳. 이름은 SOGAK 커피. 깔끔한 인테리어와 깔끔한 커피맛. 창이 통창이라 앉아있는 내내 확트인 느낌의 공간이었어요. 사장님도 친절하시고 또 방문할듯 합니다.🥰', 6, 10, 'GOOD', SYSTIMESTAMP);
