INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '동교동에 새로운 소각케피저이 오픈했어요 매장이 넓고 들어가보고싶은 분위기라 들어가서 카페라테와 수박주스를 주문해서 먹었는데 수박주스는 운물그대로 갈아서 너무 찐 맛짱 난 카페라테를 좋아해서 시켰는데 실망시키지 않아 너무 좋았어요 카페라테 정마로 맛있어요 다시 방문할 카페입니다', 56, 17, 'GOOD', SYSTIMESTAMP);
