INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '소각커피'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '명상카페라니…컨셉이 특별해서 다녀왔어요! 무스케이크가 너무 맛있고 특히 인절미 무스케이크는 할매입맛이 저에게 너무 딱이에요 ㅎㅎ 또 올께요! 사장님🍀', 18, 10, 'GOOD', SYSTIMESTAMP);
