INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '혼자 합정 탐방하다가 궁굼해서 들렀어요 비건이라 그런지 다디단 디저트가 아닌 건강하게 단 맛이 났는데 얼그레이 케이크는 맛이 좋았고 위에 크림과 너무 잘 어울렸어요 살구케이크는 중간중간 살구가 씹히고 쨈까지 올려주셔서 식감이 최고였습니다! 그릇과 카페 분위기가 이뻐서 공주 느낌내면서 힐링하고 갔어요ㅎㅎ 혼자 힐링하러 오기 딱 좋아요 저만 알고 싶고 이 가게는 유명해지지 않았으면 좋겠어요...', 4, 0, 'GOOD', SYSTIMESTAMP);
