INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '건강한 재료로 만드는데 이렇게 맛있다니!! 역시 찾아서 다녀온 보람이 있네요. 마뽀즈의 자랑 비건 당근케이크와 솔티초코쿠키! 당근케이크는 쌀과 아몬드의 고소함과 당근의 맛이 풍부하게 느껴지는 맛! 솔티초코쿠키는 베이스는 분명 고소한 맛이 느껴지는데, 어느 순간 비건초코의 진한 달콤함과 소금의 짭짤한 맛이 느껴지는 맛으로 둘다 먹고 나서 속도 편안하고 좋네요.', 14, 2, 'GOOD', SYSTIMESTAMP);
