INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '클래식하면서도 러블리한 매장인테리어에 쿠키와 케이크도 정말 예쁘면서 독특해요! 비건이라 자극적인 단맛이 아니라 재료자체의 순수한 단맛이어서 정말 좋았어요.', 55, 14, 'GOOD', SYSTIMESTAMP);
