INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '합정의 비건디저트 맛집 마뽀즈 다녀왔습니다! 마뽀즈의 디저트는 버터, 달걀, 우유, 백설탕, 흰밀가루, 생크림 등을 안쓰고 건강한 디저트를 제공해주십니다! 건강한 재료만 사용하심에도 불구하고 디저트는 정말 맛있었고 일반 케이크와 다르다고 생각되지 않았어요! 매장 분위기는 유럽의 카페에 온듯했고, 사진 찍기도 좋고 연인, 친구, 동료들과 오순도순 이야기하기 좋았어요. 건강하게 먹으면서 힐링하기 좋은 마뽀즈 추천드립니다', 8, 1, 'GOOD', SYSTIMESTAMP);
