INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '그녀의 휴식이라는 라뽀즈에서 나의 휴식이라는 마뽀즈로 상호를 변경한 합정역 비건 케이크 전문점에 다녀왔다. 프랑스 가정집 분위기의 카페여서인지 외국인도 많이 온다. 라떼류는 두유나 아몬드 브리즈로 대체가 가능하여 손님의 취향을 섬세한 곳이란 생각이 든다.', 10, 9, 'GOOD', SYSTIMESTAMP);
