INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '비건 케이크 종류가 많아서 너무 행복하네요. 레몬 코코넛 케이크가 상큼한 레몬 맛과 코코넛 향이 잘 어울리고 쿠키도 솔트가 올라가사 단짠으로 넘 맛있네유 ㅎㅎ 집이랑 가까우면 자주 오고싶은 곳이에요 ㅎㅎ 사장님도 친절하시고 분위기도 넘 좋아서 수다떨다보니 시간가는 줄 모르겠네여 !! 추천합니다.', 96, 22, 'GOOD', SYSTIMESTAMP);
