INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '비건디저트 먹으러 왔던건 아니고 상수카페거리 구경하다가 예뻐서 들어왔어요 비건케이크 판다는 말에 왔는데 생각보다 달더라고요 그래서 더 신기했습니다. 최소한으로 건강을 생각했는데 맛이 달달 하니 계속들어갔어요 친절하시고 잘먹었어요', 45, 6, 'GOOD', SYSTIMESTAMP);
