INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '비건 디저트집 많이 다녀봤는데 마뽀즈처럼 적당하고 깔끔한 단맛을 보여주는 곳은 드물거든요! 너무 맛있었어요. 게다가 음료도 과일 자체의 단맛을 충분히 이끌어내면서 청량감을 줘서 한 잔 금방 비워냈네요. 인위적인 단맛이 없어서 너무 편안한 곳이었습니다.', 18, 8, 'GOOD', SYSTIMESTAMP);
