INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '전부 비건디저트인데 너무 맛있어서 놀랐어요✨ 매장에서 먹고가니 예쁜 접시에 과일들까지 세팅도 완벽하게 해주셨구요! 매장 분위기 자체가 너무 예뻐서 사진도 잘 나오네요:) 좌석 간격이 널찍해서 대화하기도 좋고 자리도 편안해요💕 퇴근하고 완전 힐링하구 갑니당!', 29, 0, 'GOOD', SYSTIMESTAMP);
