INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '저녁이었는데도 사람이 좀 있었어요 1인 운영이시라 바쁘셨지만 친절하세요 비건케이크맛이에요 빵은 아몬드향이나고 블루베리크림은 코코넛향이났어요 그릇이 케이크와 잘 어울리고 독특해서 예뻤어요 선물포장도 많이해가시더라구요 커피와 한잔 하며 잘 먹고갔습니다', 20, 5, 'GOOD', SYSTIMESTAMP);
