INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '비건 카페 종종 가는데 가봤던 곳 중에서 제일 예쁜 것 같아요~ 내부 인테리어도 접시도 취향저격 !! 케이크 종류도 다양하고 음료도 정말 맛있게 먹고 왔어요 맛은 비건 케이크라고 말 안하면 모를 정도로 일반 케이크와 비슷합니다. 데이트하기 좋아요 👍', 15, 1, 'GOOD', SYSTIMESTAMP);
