INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '상수 카페거리에 이런곳이♥️ 분위기도 아늑하고 여유롭고 대화하기도 좋아요 비건케이크라 맛도좋고 유럽에 온느낌!!접시도 이쁘네요 취향저격 마뽀즈에서 여유느끼고갑니다❣️❣️❣️', 43, 10, 'GOOD', SYSTIMESTAMP);
