INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '오랜만애 카페데이트하려고 들린 합정카페 마뽀즈 부담없는 비건디저트와 맛있는 라떼로 행복하게 데이트 했어요 유럽 응접실같은 우아한 분위기에서 도란도란 이야기하기도 좋고 데이트코스로 딱이였어요', 12, 1, 'GOOD', SYSTIMESTAMP);
