INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '합정에서 비건케이크 파는 곳이라 전부터 너무 궁금했는데 드디어 와봤어요 !! 매장이 엄청 귀엽고 아늑하고 귀여운걸로 가득차있어서 너무 행복했어요 .. 🥹💗 비건케이크임에도 달달하고 두더지케이크 너무 취저예요 >< 건강하게 먹을 수 있는 디저트 정말 사랑하는 편인데 마뽀즈는 또 올꺼같아요 🫶🏻😆직원분도 엄청 친절하시고 매장 분위기도 포근해서 추천합니다 !!', 29, 10, 'GOOD', SYSTIMESTAMP);
