INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '비건케이크가 이렇게 맛있다니! 쿠키보다 케이크가 맛있습니다(개인적 취향) 레몬코코넛케이크 먹어보고 맛있어서 두더지케이크 추가해서 먹었는데 둘다 매력있어요! 다음에고 합정오면 여기 또 오려고요', 183, 51, 'GOOD', SYSTIMESTAMP);
