INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '많은 이들과 기쁨을 나누는 날 비건 케이크를 가져갈 수 있어서 좋았습니다. 저 포함 여러 비건이 맛있게 먹을 수 있는 케이크 였어요.', 83, 14, 'GOOD', SYSTIMESTAMP);
