INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '인테리어 외국에 온것처럼 너무 예뻐요, 모두 너무 친절하시고 글루텐프리에 관심많은데 딱 취향저격 메뉴들입니다! 비건디저트여도 맛있어요🩵', 16, 8, 'GOOD', SYSTIMESTAMP);
