INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '두더지 케이크랑 초코 솔티 쿠키 모두 맛있습니다. 코코넛 크림(아마도)이 듬뿍 들어있고 달콤한 바나나와 초콜릿 큐브가 무척 잘 어울려요 *_* 초콜릿 큐브가 코코넛 크림에 파묻혀서 툭툭 씹힐 때 식감이 무척 좋습니다. 시트가 전체적으로 촉촉해서 술술 잘 넘어가네요. 쿠키는 군더더기없이 바삭하고 고소해서 좋습니다. 느끼함없이 뒷맛이 깔끔합니다ㅎㅎ 영업시간 전에 왔는데 사장님께서 후다닥 포장해주셔서 감사했어요 ㅠㅠ', 17, 2, 'GOOD', SYSTIMESTAMP);
