INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '합정상수 꼭 가봐야 되는 벚꽃 맛집 아니 케이크 맛집 아니 둘다 테라스에 앉아 케이크 커피 즐기기 여기가 최고 케이크 한 조각 넘나 아쉬워.. 한 판 혼자 다 먹고 싶다 레알 행복한맛', 96, 19, 'GOOD', SYSTIMESTAMP);
