INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '합정역에 비건카페가 있다해서 가봤는데 왠걸 앞에 벚꽃길이더라고요!! 너무 예뻤고 운치있었고ㅠㅠ 완전 만개했을때 여기 웨이팅 장난아니겠다 싶었어요!! 그리고 글루텐프리 비건케이크여서 밀가루 소화 잘 못시키는 저에게 딱이였고~! 딸기케이크도 너무 맛있었답니다ㅠㅠ 또 가서 케이크 종류별로 쓸어담아오고 싶네요!!!', 15, 8, 'GOOD', SYSTIMESTAMP);
