INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '본의 아니게  비건글루텐식을 해야해서 디저트류는 잊고 사는데 비건글루텐프리 케이크가 있다고해서 갔어요 모든제품이 비건글루텐프리는 아니지만 먹을 수 있는게 있어서 너무 좋아요 커피도 맛있어요.', 115, 20, 'GOOD', SYSTIMESTAMP);
