INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '비건케이크집 라뽀즈🍰🧁 *주차- 안되요. 근처 유료나 공유주차장 이용. *맛- 초코케이크, 바닐라딸기 케이크 주문.🧁 비건케이크라 우유와 버터가 들어가지 않아 식단조절할때 들리는 곳이에요😙 케익시트가 일반적인 케이크와는 달라요. 촉촉하지만 잘 부서지는 비건빵 특유의 식감이고 크림도 우유베이스가 아닌 코코넛 베이스에 빵 처럼 잘 부서지는 질감이고 가벼운 맛이에요. 일반적인 케이크의 맛과는 다르지만 우유랑 버터가 들어가지 않아 전반적으로 라이트하고 산뜻한 느낌으로 먹기에 좋아요! 하지만 비건빵을 즐기지 않는다면 호불호가 있을 수 있으니 참고! (지극히 개인적인 후기입니다)', 74, 15, NULL, SYSTIMESTAMP);
