INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '점심시간에 가면 쇼케이스에 가득 차 있고 아직 자르지도 않은 홀케이크도 있는 걸 보는 게 좋아요.. 피넛크림 초코케이크를 먹었는데 부드럽고 고소한 땅콩크림과 촉촉하고 묵직한 초코맛이 나는 시트에 오독오독 씹히는 땅콩 분태와 초코칩, 상큼한 과일 조각이 잘 어울렸습니다~!', 42, 6, 'GOOD', SYSTIMESTAMP);
