INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '바삭하고 짭쪼름 해요! 단짠단짠이 너무 좋네요😊 안에 호두도 있어서 식감도 다양하고 너무 맛있어요! 일상에 달달한 시간을 라뽀즈에서 보낼 수 있어 너무 좋았어요! 여러분 두더지,쏠티초코쿠키,쌀레몬은 꼭 드셔야합니다.', 13, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '포장해서 가느라 많이 찌그러졌네요;; 라뽀즈 케이크 입맛에 딱 맞는데 이날은 원래 먹던 맛보다 조금 더 달긴했어요 그래도 맛있게 잘 먹었답니다 카페오레 또 먹으러 갈게요🤎', 29, 3, NULL, SYSTIMESTAMP);
