INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '라즈베리와 말차라는 독특한 조합도 눈길이 가지만 이 분홍 크림이 너무 예뻤어요.. 맛은 딸기 요플레가 생각나는 새콤한 크림에 말차 시트였습니다~', 4, 9, 'GOOD', SYSTIMESTAMP);
