INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '새해 앞두고 명절 전에 방문했어요 매장 내 9테이블 중 3테이블만 손님이 있던 차에 나란히 옆자리에 앉아서 2테이블 공간을 차지한다고 눈치를 주셨어용! 옆자리 분은 옆에 짐을 둬도 짐치워달라고 안하는데! 저희한테는 짐치워달라구 하더라구용 ㅜ 음료랑 커피는 맛있었어용', 23, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '두더지 케이크라는 이름이 재밌어서 주문했는데 초코칩이 콕콕 박힌 흰 크림에 잘 익은 바나나를 깔고 그걸 감싸는 초코 시트와 크럼블의 조화가 참 좋았어요... 제 기쁨이었습니다!', 11, 6, 'GOOD', SYSTIMESTAMP);
