INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '비건케이크는 처음 먹어봅니다. 당케는 약간 이질감이 있었고 바닐라스트로베리 케이크는 정말 맛있었어요 일반 케이크랑 크게 다르지 않은 느낌', 18, 0, NULL, SYSTIMESTAMP);
