INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '건강을 위해 비건케이크  먹고 싶어 방문했어요. 포장해오려다가 너무 먹고싶어 매장에서 한 조각 더 먹고왔네요. 깔끔하고 너뮤 달지않은 맛, 건강한 케이크 너무 좋아요', 45, 5, 'GOOD', SYSTIMESTAMP);
