INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '글루텐프리, 비건 케익은 처음인데 부담없이 먹을수 있는 케익이네요 다른 케익 먹을때보다 더 건강한 맛?ㅎ 부드럽고,고소하고,많이 달지 않고 맛있어요~~', 49, 0, 'GOOD', SYSTIMESTAMP);
