INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '합정 올때면 꼭 들리는 카페 중 하나 종류별로 맛보고 있어요. 비건 케이크들 많이 먹어 봤지만, 저는 라뽀즈 너무 맛있어요💓 항상 친절한 사장님과 직원분들 오래오래해주세요오오', 128, 26, 'GOOD', SYSTIMESTAMP);
