INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '라뽀즈는 늘 대접받는 듯한 기분을 느끼게 해주는 카페여서 좋아요☺️ 초코 바나나는 처음이었는데 맛이 엄청 진하구 살짝 꾸덕해서 너무너무 맛있게 먹었습니다🍌🍫 라뽀즈는 크림이 들어간 케이크도 물론 맛있지만 크림 없는 케이크들이 진짜 매력적인거 같아요ㅎㅎㅎ', 37, 6, 'GOOD', SYSTIMESTAMP);
