INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '정말 애정하는 공간인 라뽀즈..💚 일부러 여기 오려구 합정까지 달려올 때도 많은데요_!! 사장님, 직원분들 저엉말 친절하시구 맛이야 뭐.. 여기 디저트 진짜 다 맛있으니 뭘 선택하든 실패란 없습니다🫧🫧🫧 평화롭다라는 말이 딱 맞는 공간이라 혼자 시간 보내고 싶을 때 방문하기 좋습니당🤍 힐링 자안뜩 할 수 있어요>_<', 7, 7, 'GOOD', SYSTIMESTAMP);
