INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '라뽀즈 신메뉴 말차두유케이크…? 와 진짜 고소하고 맛있어요!!🥹 고급진 맛이고 라즈베리 잼이 상큼해서 좋아요 저당인데 비건이라니… 건강 챙기기에 딱이네요 다들 꼭드세요☺️', 27, 3, 'GOOD', SYSTIMESTAMP);
