INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '카페오레 케이크 너무 맛있어요 글루틴프리, 비건 케이크는 처음이었는데 걱정이 무색하게 정말 맛있었어요 심지어 디카페인이라 밤에도 먹을 수 있음...😳 커피맛인데 디카페인...최고예요', 55, 15, 'GOOD', SYSTIMESTAMP);
