INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '우왕.. 라뽀즈 신메뉴 다 너무 맛있는데요..? 아삭아삭하고 시원해요 완전 여름 메뉴로 최고입니당 최근에 먹은 옥수수 디저트 중에 제일 취향에 맞아요🤍🌻 옥수수 좋아하시면 꼭 시키세욤..🥹', 8, 8, 'GOOD', SYSTIMESTAMP);
