INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '카페오레 케이크는 진짜 비건이라고 말 안하면 모를 정도로 맛있어요!! 얼그레이케이크도 처음에는 홍차향이 강했다가 뒤로갈수록 두부?두유?같은 고소한 맛이 올라와요🫶🏻💕 집에갈 때 피넛크림초코케이크 포장해서 남편한테 비건이라고 말 안 하고 줬는데 너무 맛있게 먹더라구요ㅋㅋㅋㅋ 시트도 완전 촉촉🥹', 13, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '그냥 비건 케이크가 아니라 글루텐프리라서 더 좋네요:)) 재료도 다 적혀져 있어서 안심하고 먹을 수 있어서 좋았어요! 단호박케이크 먹었는데 첫입은 약간 두유+콩 맛이 나나하다가 단호박의 달달하고 건강한 맛이 나면서 촉촉+크리미+꾸덕한 식감을 모두 즐길 수 있었습니다. 밀가루 사용하지않은 디저트 찾을때 , 종종 갈 것 같아요!', 6, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '케이크 맛집 ✨️ 단호박 케이크 부드러우면서 꾸덕해요 평소 디저트를 잘 안 드시던 할아버지도 맛있게 먹었답니다 💚 비건케이크라 생소할까봐 일반케이크도 준비했었는데 일반케잌보다 인기가 많았어요 🤭🤭 사장님과 직원분들도 다 너무 친절해요 :)', 95, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '주중 저녁에 방문했는데 매장에서 한분이 혼자 주문 받고 음료 제조까지 하시느라 주문하고 제품 수령히는데 소요 시간이 20분 넘게 걸린 듯 합니다… 표정도 매우 지쳐보이셨구요.. 케익은 통밀의 거친 입자가 그대로 케익에서 느껴지기 때문에 일반적인 제누와즈 같이 입에서 녹는 부드러운 케이크 시트는 아닙니다. 비정제원당의 특유의 강한 단맛으로 인해 상대적으로 레몬의 맛과 향이 묻히는 점이 많이 아쉽네요. 원재료들의 특성에 대한 이해를 바탕으로 좀더 밸런스 있는 케이크로 보완될 수 있다면 훨씬 더 좋겠습니다. 가격대비 양도 많이 작아서 저는 한번의 경험으로 만족하고 다음번엔 같은 가격이라면 일반 케익을 먹을 것 같습니다.', 50, 10, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '홀 케익은 바로 구매할 수 없습니다. 가격 비쌉니다. 세트메뉴나 할인은 없는 것 같습니다. 초도 구매 필요! 동생 생일로 조각 케익 8개로 홀 사이즈 만들기엔 금액이 너무 부담되어 6개로 구매했네요. 보통 케익 다 먹지 못하는데, 처음으로 다 먹었네요! 약간 당분이 과하다는 평은 있었지만 부모님께서도 비건 케익이라 부담 없이 잘 드셨습니다.', 63, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '오늘두 초코케잌 뿌셔뿌셔 👍🏻❤ 음악도 좋고 인테리어도 예쁘고 케잌도 맛있고 ~ 남편과 앉아 얘기 나누다보니 어느새 케잌도 커피도 다 먹어서 따듯한 아메 추가했어요 언제와도 아늑하고 기분 좋은 카페에요 ☺', 39, 2, 'GOOD', SYSTIMESTAMP);
