INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '너무 맛있어요! 소화도 잘 되는 편인 것 같아요. ㅎㅎ 기념일로 케이크 한 판 주문 하려다 다 못 먹을 것 같아서 두 조각만 사갔는데 원하는 종류가 명확하신 분들은 일찍 가세요~~ 품절 된 게 많았어요. 케이크의 높이가 서로 달라서 작은 정사각 도시락케이크용 종이통에 담아주셨는데 가지고 가실 때 하나가 뚜껑쪽에 묻을 수도 있다고 하셨는데 결국 가지고 가다가 흔들렸는지 진짜 집에 가서 열어보니 다 망가져 있었습니다 ^_; 하지만 머 맛 좋으면 됐죠! 조심히 들고 가쎄요들. 덕분에 맛있게 먹었습니다.', 74, 18, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '너어어무 괜찮은 비건카페를 찾았어요💕 케이크 메뉴도 다양하고 음료도 다양하게 있는 곳이에요! 아몬드 브리즈 라떼 , 레드베리티  케이크와 즐기기 너무 좋네요! 여기있는 모든 메뉴 먹어볼게요!', 15, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '매번 픽업만 했었는데 처음으로 매장에서 케이크와 차를 마셔봤어요. 피넛버터케이크 처음먹어봤는데 여태까지 먹었던 비건 피넛버터케이크 중에 제일 맛있어요. 묵직한 시트지에 크리미한 버터 크림, 한국인이 좋아하는 너무 달지 않은 맛까지 완벽해요! 그리고 로네페트 그린 앤젤을 처음 마셔봤는데 살면서 이렇게 맛있는 티는 처음마셔봤어요! 친구도 너무 맛있다고ㅠ 그리고 지인 생일이라서 딸기 바닐라 홀케이크도 주문했는데 너무 예쁘고 맛있어서 행복한 생일파티를 했답니다. 라뽀즈 최고🎂', 15, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '비건 카페인데 유일하게 두 번 온 카페에요!! 진짜 건강한 맛 좋아하는 사람들은 좋아할 거 같은 맛이에요. 평소에 케이크 먹으면 더부룩하고 달고 배부르고 속 안 좋아서 잘 안 먹는데 여기 케이크는 비건이어서 숙숙 잘 들어가요🥹 합정에 데이트하러 오면 무조건 오는 곳인데 집 앞에 있다면 혼자서 자주 갔을 것 같아요 그만큼 분위기도 아주 굿이에요 노트북하기 좋아요👍🏻👍🏻', 95, 23, 'GOOD', SYSTIMESTAMP);
