INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '사장님이 친절하시고 가게가 포근해서 대화하기 좋았어요~ 아몬드브리즈라떼랑 당근케이크 먹었는데 앞으로도 비건 디저트 찾게될 것 같은 맛이었어요🥳 친구가 하나 더 시켜먹은 초코케이크가 꾸덕하니 추천합니다..ㅎㅎ', 49, 2, 'GOOD', SYSTIMESTAMP);
