INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '초코라떼 두유로 먹었는데 시럽맛이 너무 강해서 조금 비추입니다.. 하지만 디저트는 정말 맛있어요. 코코넛크림이 기본이라서 코코넛맛을 좋아하시면 강추입니다. 딸기케이크가 최고네요', 50, 4, NULL, SYSTIMESTAMP);
