INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '처음 먹는 비건 케이크  🍰 피넛 버터 초코 케이크와 아메리카노 ☕ 달달한 케이크 + 따뜻한 커피 = 보증된 맛 고소한 땅콩 크림과 초코의 조화가 좋았다. 평일 저녁 치곤 사람들도 제법 있다. 아기자기한 소품들과 따뜻해 보이는 조명도 좋았다.', 71, 17, 'GOOD', SYSTIMESTAMP);
