INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '직원분이 친절하셔서 좋았고 커피도 무난하게 맛있었어요~~ 분위기도 좋고 혼커하기에 조용하고 너무 잘 쉬다 왔네요~~ 나중에 또 올게요~~!', 74, 13, 'GOOD', SYSTIMESTAMP);
