INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '비건 디저트로는 이미 유명한 곳으로 알고 있어요 :) 평일 오후에 방문했고, 무화과 케이크, 당근 케이크 포장했습니다 :) 비건 케이크에 처음 도전 하시는 분들도 이미 드셔본 분들도 맛있게 드실 수 있어요! 빵이 엄청 촉촉하고 억지스러운 단맛들이 아니라 특히 좋았어요! 가게두 아기자기하고 귀엽습니다 :)', 1, 5, 'GOOD', SYSTIMESTAMP);
