INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '그린엔젤티 진짜 맛있었어요.. 또 마시러 가려구요🥹 현미블루베리홍차케이크 메뉴는 블루베리도 듬뿍 들어있고 식감이 좋아하는 식감이라 차와 맛있게 잘 먹었어요!', 5, 2, 'GOOD', SYSTIMESTAMP);
