INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '아늑하고 따뜻한 분위기 카페 :) 인형도 많고 인테리어가 너무 귀여워요 ! 비건 케이크 찐하고 맛있네요! 차랑 잘 어울려요 다음번에 다른 메뉴들도 먹고 싶어요', 88, 16, 'GOOD', SYSTIMESTAMP);
