INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '요 날은 왠지 초코가 땡겨서 피넛초코케이크 🥜🍫먹었어요 🩷 적당한 달달함에 시트지도 통밀인데 전혀 안 퍽퍽하구 좋았어요!!! 넘 맛있어서 맛 별로 도장깨기 하고 싶은 맘... 🤤 케이크 크기는 생각보다 작은데 둘이서 나눠먹기 딱 좋아요 😉 저녁 6시 넘어서 가니까 품절된 메뉴도 몇몇 보였오요! 직원분도 친절하구 분위기도 좋아서 자주 방문할 것같네요🩷', 43, 4, 'GOOD', SYSTIMESTAMP);
