INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '케이크 쫀쫀맛 ♡♡♡ 제가 넘 조아하는 케이쿠맛집!!! 영수증인증은 처음인듯하지만 오늘도 케잌3조각, 커피 3잔째!! 마지막 커피추가 영수증으로 인증해봅니당 ㅎㅎ 또갈집 또뽀즈~~', 102, 22, 'GOOD', SYSTIMESTAMP);
