INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '비건 까페 라뽀즈,디저트 쇼케이스위를 보니 고전영화가 나온다. 라떼의 코스타는 옛날 영문책자의 한 조각, 홍차라떼(두유)가 향도 강하고 좀 달 거 같아서 마음먹었던 홍차케이크 대신 당근 케이크를 주문. 라떼도 케이크도 단맛이 상당하다. 다른 비건까페들 보면 담백한 맛을 추구하는 곳들만 봐서 조금 색다르게 느껴졌다. 퐈~ 한 단맛이 아닌 경쾌함이 느껴져 신기하고 , 너무 단 걸 먹고나면 느낄 수 있는 불편함? 입안의 맴도는 설탕맛?이 거의 느껴지지 않았다.', 26, 5, 'GOOD', SYSTIMESTAMP);
