INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '선물로 케이쿠 샀는데 크림. 크럼블. 시트 버릴 것 없이 담백하고 달달한 맛.. 초코 케이쿠 별로 안좋아하는데 너무 단맛이 아니라 조아쑴다! 블루베리가 인기있는 이유가 있엇다!', 39, 2, 'GOOD', SYSTIMESTAMP);
