INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '친구 기다리는 겸 있었던 카페인데 분위기도 넘 좋고 조용해서 좋더라구요ㅎㅎ계시던 직원분인지 사장님이신지 모르겠는데 넘 친절하셨어요😆👍💕', 66, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '주문한 메뉴는 초코바나나 케이크와 홍차라떼, 블루베리에이드? 였던 거 같은데 솔직한 감정으로 케이크의 첫 맛은  초코바나나맛 프로틴 가루로 케이크를 만든 듯한 느낌이었으나 먹다보니 은근 손이 가는 듯한 맛이었다. 그치만 홍차 라떼는 정말 맛있었다! 따뜻하게 시켜서 마시는데 너무 맛이 좋아서 나도 모르게 금새 다 마신..? 근처에 갈 일이 있다면 또 재방문해서 맛보고 싶은 맛이며 홍차라떼 말고도 다른 음료도 맛보고 싶어졌다!', 50, 6, 'GOOD', SYSTIMESTAMP);
