INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '가벼운 디저트가 먹고 싶어서 와봤는데 너무 기분좋게 즐기고 가서 리뷰남겨요🥰 요즘 카페 디저트 다 자극적이고... 극단적으로 달아서 항상 디저트 시키고 후회하거든요 근데 디저트에서 정성도 가득 느껴지고 맛도 제 스타일이었어요 ㅎㅎ 인테리어도 편안하고 좋았어요 사장님도 정말 친절하셔서 기분 좋게 먹고 왔습니다🍀', 2, 8, 'GOOD', SYSTIMESTAMP);
