INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '가게 인테리어도 소품도 심지어 케이크도 예뻐서 정물화 속에 들어온 것 같아요.. 골드키위 케이크 먹었어요! 케이크 속 키위도 같이 나온 무화과도 잘 익어서 견과류 든 고소한 시트랑 달달한 크림이랑 어울렸어요~ 딱 이때 찾아가서 이걸 주문한 게 기쁜 맛이었습니다👍', 38, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '주문 메뉴: 피넛크림케이크(8300원) 당근케이크(8500원) 총 16800원 진짜 포장ㅋㅋㅋㅋㅋㅋ매번 포장으로 가져올 때마다 조심히 들고 와도 열면 처참한 모습의 케이크... GF인 것만 골랐고 피넛케이크는 크림이 맛있긴 한데 크림부분 다 먹고나면 빵 부분은 좀 퍼석한 식감이라 초코케이크가 더 맛있어요 당근케이크는 비건 아닌 케이크들보다 훨씬 맛있고 깔끔한 맛인데 개인적으로 순위를 매기자면 1.초코케이크 2.단호박 3.당근 4.말차 5.피넛이고 포장 2개이상으로 했더니 케이크끼리 붙어버려서 2개이상으로 산다면 개별포장이 나을 것 같아요 웬만하면 매장에서 먹는 게 제일 좋겠지만 포장하실 분들은 조심...!!!!', 16, 3, NULL, SYSTIMESTAMP);
