INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '유럽 가정집 같은 인테리어에 비건 케이크라니!! 케이크와 함께 나온 깨알 과일들에게서 감동 받았어용! 뮤직도 좋고 늦게까지 영업해서 좋네요 :)', 39, 9, 'GOOD', SYSTIMESTAMP);
