INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '올 비건 글루텐 프리 카페입니다 ㅎㅎ 비건 친구랑 방문하기 좋았고 저는 비건 아닌데 비건치고 맛있는게 아니라 그냥 맛있었어요!! ㅎㅎ 대화히기도 좋습니다', 44, 3, 'GOOD', SYSTIMESTAMP);
