INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '비건맛집! 분홍빛 단발좌 예쁜 사장님이 반겨주셔서 기분이 좋아유~ 노을이 간식으로 블루베리 주셔서 감동이에유~ 프랑스를 머금은 로멘틱 접시와 영어로 된 종이 받침까지 낭만적이네요. 아메리카노는 고소하면서 부드러웠어요. 탄맛이 살짝 나서 아쉬운 점. 콩크럼블쑥케익 꾸덕 고소 쑥향이 가득혔어요. 너무 맛있어서 단호박케이크 주문혔어요~ 단호박 위에 크림 얹은 케익 같아요. 리얼해서 좋았고 건강하게 케이크를 먹을 수 있음에 감사해요. 라뽀즈 또 놀러 올게유~', 44, 1, 'GOOD', SYSTIMESTAMP);
