INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '디카페인 커피를 마시는데 디카페인 커피가 없더라구요. 하지만 tea가 로네펠트 였어요~ 물도 리필 해 주셔서 디테일이 느껴지는 첫 방문이였어요. 조용히 혼자 다시 가서 책 읽고 싶은 따뜻한 곳이에요.', 74, 18, 'GOOD', SYSTIMESTAMP);
