INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '궁금했던 케이크는 잘 으스러지는 식감이었어요 마른 백설기를 뭉쳐놓은 느낌 •• 말차케이크는 말차 향이 강해서 좋았습니당 다른 케이크 맛보러 또 갈 거예요', 277, 47, NULL, SYSTIMESTAMP);
