INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '너무 좋아하는 곳이에요. 모든 디저트가 다 맛있어요. 이번에는 초코 케이크 먹어봤는데, 초코가 진하고 시트는 촉촉하고 크림은 부드럽고 예쁘기까지!🍰🍫', 107, 23, 'GOOD', SYSTIMESTAMP);
