INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '비건 케잌이지만 맛까지 있는곳은 찾기 힘든데 여기가 거깁니다!! 커피맛도 꽤 좋고 디저트 케잌맛도 굿굿 👍 피넛크림 초코케잌 최고!!! 와이파이도 잘 터지고 사장님 직원님 친절하시고 캐모마일도 맛있습니다 😬', 24, 2, 'GOOD', SYSTIMESTAMP);
