INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '어제 초코케이크를 먹어보고 재방문해야겠다는 생각이 들어 오늘 다시 가서 당근케이크를 사왔습니다. 포장용기를 열어보니 케이크의 일부가 뚜껑에 붙어버린 모습이 다소 웃겼지만 맛만큼은 비건식인데도 정말 좋았네요. 가격만 좀 더 저렴하다면 사람들이 비건 케이크에 많이 도전해 볼텐데 그 점은 많이 아쉽습니다.', 63, 13, NULL, SYSTIMESTAMP);
