INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '비건빵인데 괜찮더라구요! 음료는 완전 맛있어요 아몬드브리즈 녹차라떼 오히려 더 고소해서 맛있구 레드베리차는 티백인데도 너무 달달하고 맛있는 차였습니당!', 16, 7, 'GOOD', SYSTIMESTAMP);
