INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '동물성 안 드시고 비건 좋아하시는 엄마 케익 사다드릴려고 서치하다가 제일 리뷰도 괜찮고 자주 가던골목에 있어서 가봤는데 친절하시구 포장도 예쁘고! 꽃 붙여주심 케익도 맛있어요', 11, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '테이크 아웃했습니다. 직원 분들께서 너무 친절하셔서 감사했고, 인테리어도 멋지네요. 쵹쵹한 케이크라 하나도 빠짐없이 다 맛있게 먹었습니다! 가루 하나도 놓칠 수 없는 맛..🍒', 51, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '최애카페입니다. 글루텐프리인데 아주 맛있습니다 오는 길에 흔들려서 사진이 이상하지만 어느 곳도 라뽀즈를 따라갈 수 없어요. 건강한데 맛있는 케이크를 만드는 곳이에요.', 39, 10, 'GOOD', SYSTIMESTAMP);
