INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '주문한 메뉴중 레몬코코넛 케이크가 의외로 넘 맛있었어요! 크리스피한 식감에 레몬 맛이 강하지 않았어요 바닐라루이보스티도 향이 참 좋았어요 공간이 협소해 아쉬움이 있었지만 비건 디저트 맛집 인정입니다', 31, 4, NULL, SYSTIMESTAMP);
