INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '작년 남편생일에 남편이 좋아하는 라뽀즈케익으로 행복한 시간 보냈던 기억이 있어 합정쪽 가게되면 늘 들리게 되는것 같아요. 오늘은 커피를 마셨지만 사진은 작년 생일때 먹었던 예쁜 케익들입니다^^ 다이어트 중인데 가끔 너무 케익이 먹고싶다면 라뽀즈 가보세요🌸', 13, 6, 'GOOD', SYSTIMESTAMP);
