INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '과거에 먹었던 비건케이크에 대한 기억이 좋아서 갔다가 퀄리티가 떨어져서 실망함... 크림이 실종 수준이고 그러면 빵이 맛있어야 하는데 그냥... 좀 퍽퍽한 빵임', 79, 14, 'BAD', SYSTIMESTAMP);
