INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '와 비건케이크 이래도 되나 ㅋㅋ 건강한데 맛까지 최고...? 성분도 최고 맛도 최고 너무너무 만족!!!! 앞으로 단골 예약합니당💛', 3, 1, 'GOOD', SYSTIMESTAMP);
