INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '두번째 방문이에요 ~ 저번에 단호박케이크랑 통밀스트로베리케이크 넘 맛있게 먹어서 고심해서 골랐는데 이번에 고른 건 제 스타일은 아니었네요^^; 담백한 거 좋아하는데 쿠키가 넘 오일리했어요', 56, 14, NULL, SYSTIMESTAMP);
