INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '와....  케이크가 정말 정말 맛있어요 :) 아직도  아른거리네요♡♡♡ 그런데 포크만으로 먹기에는 불편해서 스푼도 있었으면 좋겠다고 생각했어요~', 41, 3, 'GOOD', SYSTIMESTAMP);
