INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '합정역에서 가까운 위치에 있어요  길 지나다가 우연히 들어간 곳인데 음료보다도 케익크가 인상적이 였어요 당근 케이크 다른 어느집 보다 맛있었어요 살도 안찐다고 하니 더 좋아 ^^', 70, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '가격은 좀 비싸지만 값어치 합니다. 모든 케이크기 아몬드가루를 바탕으로 만들어졌고 케이크마가 재료명이 다  써있어서 믿음직했어요. 카페도 이쁘고 케이크도 이뻐요. 맛은 물론 좋아요 버터 우유 안들어간걸 믿을 수 없을 정도. 건강과 환경을 위해 비건케이크 응원합니다.', 8, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '매장 인테리어가 참 예뻐요 아직 코코넛 레몬케이크랑 르뱅쿠키만 먹어봤는데요 케이크는 약간 퍽퍽한 느낌이어서 아쉬웠고 (갠적으로 촉촉한 케이크 선호해서 개인적으로 아쉬웠어요) 하지만 적당한 레몬맛과 코코넛의 조화는 좋았어요 르뱅 쿠키 또한 갠적인 취향은 아니었어요. 너무 달았거든요. 하지만 라떼 한잔에 쿠키 하나 먹고도 든든해서 좋았습니다', 9, 6, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '이때까지 간 비건케이크집 중에서 제일 맛있어요! 비건이라는 느낌이 전혀 안들정도로 너무너무 맛있어요ㅠ 연말에 종류별로 홀케이크도 하시는거같은데 주문하고싶어요ㅠㅠ 케이크 맛도 맛있고, 예쁘게 담아주셔서 눈도 즐겁고, 매장도 엄청 이뻐요 ❤️❤️🥺', 12, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '토요일 저녁 8-10시 사이에 일하시는 알바하시는 분. 너무 말투가 무례하셔서 기분이 좋지 않았습니다. 화장실을 찾는 저희 부모님이 계산대 옆쪽에 문(아마도 스텝들 사용하는 공간)이 보이자 ‘여긴가?’하고 들어가려는 제스처를 취하자 소리 지르듯이 화장실 거기 아니라고 말하며, 본인이 화가 나는걸 꾹꾹 참아 누르고 있다는 것을 표출하시더군요. 부모님과 오랜만에 함께한 자리였는데, 저희가 딱히 ’진상‘스러운 짓을 한 것도 아닌데 그런 식의 대우를 받는 게 기분이 나빴습니다. 그 분이 사장이 아니라 주인의식을 갖고 일할 수 없다는 것. 이해는 하지만, 최소한의 서비스 마인드는 갖추셔야 하는게 아닌지... 조금 의문스럽네요. 재방문 의사는 없습니다.', 8, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '케이크 종류가 엄청 많아 쇼케이스 앞에서 이것도 맛있겠다, 저거 먹을까.. 정말 고민하다가 통밀딸기 케이크로 골라 먹어봣어요! 바닐라시트에 코코넛 크림이였는데 이렇게 맛있는 코코넛크림 너무 오랜만에 먹었습니다. 거부감 없이 맛있게 즐기다 갈 수 있는 곳이라 비건 디저트를 처음으로 도전하시는 분들이 드시기 좋은 카페인 거 같아요! 물론 커피도 맛있었어요 :) 💕', 21, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '비건이라 속이 편한것 같고 쌀가루 아몬드로 만들었다는데 밀가루 케이크보다 맛있음. 싼가격은 아니지만 또 먹고싶음. 무화과케이크, 당근케이크 강추.', 48, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '합정 비건까페 라뽀즈는 자주 방문하는 곳이예요:: 비건식을 하는 사람은 아니지만, 케익이랑 음료가 정말 맛있고~친절한 사장님과 늘 밝게 대해주는 알바분들 때문에 고민없이 방문하게 되는것 같아요@@ 또 들를게요! 오래오래 번창하세요👏🏻👏🏻👏🏻', 78, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '너무 오래 앉아있어서 죄송했습니다 얘기하다보니 시간가는줄 몰랏네요 그치만 음료를 더 주문하라거나 그만 일어나달라고 하셨으면 그렇게 했을 텐데 그냥 째려보기만 하셔서 뒷통수에 눈이 없는 저는 그런 상황을 전혀 몰랐어요 아무튼 죄송합니다 다신 안 올게요^^;', 30, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '비건 케이크라서 와봤는데 케이크들이 너무 너무 맛있어요 인테리어도 너무 깔끔하고 청결해요 앉아서 서로 대화하기도 좋고 다음에 또 오려구요 ㅎㅎ', 20, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '밀가루와 버터, 우유 알러지땜에 디저트 잘 못먹었습니다. 근데 여기서 피넛초코하고 초코케이크와 같이 먹어봤는데 땅콩향이 어우러져서 고소했고 초코케이크는 촉촉해서 먹기 좋아서 만족했고 끝맛이 느끼하지 않아서 같이 온 일행도 좋아했네요. 담에도 방문해서 다른 케이크 사먹어봐야겠어요. 인테리어도 외국에 온 듯한 느낌이라 분위기 좋았어요.', 1, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '얼마 전에 친구 생일이라 얼그레이, 초코 조각 케이크랑 현미초코르뱅쿠키를 샀어요. 케이크도 완전 맛있지만 라뽀즈에서 초코 쿠키를 제일 좋아해요. 청키하고 세련된 맛이에요.', 45, 7, 'GOOD', SYSTIMESTAMP);
