INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '매장은 조금 협소했지만 앤틱한 유럽풍 분위기가 고풍스럽고 좋았어요. 비건이라 그런지 가격이 조금 사악하긴하네요ㅠ 무화과 케익 맛있어요! 약간 새콤달콤한 식물성크림이랑 고소 담백한 빵이 잘 어울어졌고 먹어도먹어도 질리지않는 맛! 시트 안에 견과류도 들어있어서 식감도 좋았어요. 자몽에이드랑도 너무 잘 어울렸어요. 직접 만든 수제과일청 같은 맛? 저어마시기에는 컵이 조금 작은 느낌이었어요. 가니쉬도 그렇고 컨셉에 맞는 그릇부터 영문 코스터?까지 디테일하게 신경쓴 점이 보여서 좋았구요. 별건 아니지만 테이블까지 직접 가져다주셔서 대접받는 느낌이었네요. 케익 종류가 다양해서 다른 케익도 먹어보고 싶어요 :)', 37, 10, 'GOOD', SYSTIMESTAMP);
