INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '최애 비건케이크 집!!! 여태 먹은 비건 케이크들중에 제일 일반 케이크와 비슷하고, 맛있어요ㅠㅠㅠㅠ홍대가 너무 멀긴 하지만, 그래도 갈 가치가 있는곳', 3, 8, 'GOOD', SYSTIMESTAMP);
