INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '비건 케이크인데 일반 케이크랑 차이를 모르겠어요, 그만큼 맛있어요. 아몬드가루라 빵이 살짝 더 잘게 부서지는 정도? 다음에는 친구 생일 케이크를 주문해보려고요.', 61, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '비건 케이트 특유의 텁텁함이 많이 느껴지지 않았다. 아기자기한 오브제들과 차 받침으로 나오는 책의 일부분을 읽는 재미가 있었다. 포장해간 단호박 홀케이크는 정말 맛있었다😃', 8, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '당일 홀케이크 예약했는데 친절하셔서 기분 좋았어요~ 케이크 앉아서 다 먹어본 적 없는데 세명이서 순삭했네요 ㅎㅎ 케이크는 라뽀즈에서만 주문하기로 다짐했어요 ㅋㅋ 정말 맛있었어요!', 42, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '아기자기한 분위기의 귀여운 카페 분위기가 참 귀엽다. 상수동부근에 위치한 카페.  비건 컨셉의 카페.    한적하진 않지만 아기자기한 볼거리가 넘쳐나는곳.   남성취향은 아니고 20-30대 여성들을 위한 카페인듯', 39, 2, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '직원분들도 친절하시고 매장이 차분하고 깔끔한 분위기예요. 케잌도 맛있습니다! 음료에 우유/두유/아몬드밀크 , 빨대 선택 가능해서 좋아요', 54, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '가려고 했던 곳이 닫아서 우연히 들어왔는데 여기도 비건디저트라서 좋았어요! 캐모마일 주문했는데 따뜻한 물로 한번 더 우릴 수 있게 해주셔서 좋았습니당💗', 95, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '비건 카페여서 찾아왔는데 야외테라스에서 바깥보면서 시원하게 먹기 좋구ㅎㅎ인테리어가 정말 예뻐요 빵이 너무 달지않고 담백하니 맛있고 좋아요 아메리카노는,,으음,,ㅋㅋㅋ 딸기는 차갑게 나오면 더 맛있을 것 같아용', 25, 5, 'GOOD', SYSTIMESTAMP);
