INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '이건 아니잖아요 ...  저 시커먼 에어컨에서 나오는 세균이 둥둥 떠다닌다고 생각하니 입맛이 ...  음료도 주변 카페에 비해 비싼데 매장 관리가 너무 안되어 있어서 놀랐습니다 ..', 48, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '라뽀즈 비건케익 처음에 조각으로 포장해가서 먹고 저랑 여자친구랑 너무 좋아해서♡ 인스타로 홀케익도 두번 예약해서 먹고 오늘은 타르트를 예약해서 사봤는데 이것도 기대됩니다!ㅎㅎ', 13, 8, 'GOOD', SYSTIMESTAMP);
