INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '금~일밖에 안 여는 주변 비건 케이크집에 비해 카페 여는 날이 많고 늦게까지 영업해서 케익 먹고 싶을 때 후딱 다녀오기 조타 좀 달고 크림이 적다. 아몬드 가루를 사용한 것은 아쉬운 점. 넛 알레르기가 있는 사람은 조심해야 한다. 맛은 2.5/5 가격 3/5 통밀 케익은 안 먹어 봤고, 글루텐 프리 케익 중엔 초코가 제일 맛있다.', 108, 23, NULL, SYSTIMESTAMP);
