INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '라뽀즈 사랑합니다😻 진짜 먹고 있는데 또 먹고 싶으면 어떡하냐구요😭😭 진짜 행복했어요! 내일이 제 생일이라 또 사러 갑니다!!!!!', 8, 7, 'GOOD', SYSTIMESTAMP);
