INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '친구와 같이 유자티, 아메리카노, 초코케이크를 먹었는데 초코케이크는 비건이라고 생각 못 할 정도로 부드럽고 달고 맛있었어요!!! 유자티도 맛있구요ㅎㅎ(잘 저어드세요) 가게도 너무 예쁘고 또 가고 싶습니다ㅎㅎ', 27, 9, 'GOOD', SYSTIMESTAMP);
