INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '다른 카페 케이크들과 차별화된 맛이에요ㅎㅎ 단호박 안좋아하는데도 이 케이크는 크림도 맛있고 단호박이 이렇게 맛있는맛이었나 싶었던ㅎㅎ 재방문의사있음! 동생이랑 둘이 갔는데 담엔 엄마도 같이 모셔오고싶었네요:-)', 0, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '저는 비건이 아니지만 비건 베이커리 특유의 맛을 좋아해서 서울 곳곳에 유명하다는 비건 빵집들은 정말 다 먹어봤는데 여기 케익류는 정말 너무 맛있어서 리뷰 남기네요 저는 특히 단호박과 당근케익을 좋아하구요 제 남자친구도 일반 케익은 느끼하고 물려서 선호하지 않는데 여기 케익은 정말 맛있다고 좋아하네요', 48, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '여기 분위기도 너무 좋고 케익 맛도 진짜 좋아서 가끔 생각날때마다 일부러 찾아가는 곳이에요. 코로나 때문에 커피는 안에서 못마시고 미리 주문 해 둔 홀케익만 후딱 챙겨서 왔네요. 홀케익이 보기에는 작아보이는데 딱 들어보면 엄청 묵직함이 느껴지는게 먹기 전부터 뭔가 꽉찬 느낌이에요. 초코케익인데 진짜 이게 비건인가 싶게 맛있어요.  조각케익은 부모님 사다드렸는데 부모님도 칭찬 해 주셨어요. 남편도 먹어보고 진짜 맛있다고 극찬 해 줘서 뿌듯한 선택 이었네요. 나만 알고 싶은 곳이지만 이미 유명하겠죠? 진짜 다들 먹어보면 좋겠는 곳이라서 리뷰 남겨보아요~~~포장도 넘 예쁘고 세심하게 신경 쓴게 느껴집니다', 126, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '사장님 너무친절하시구 맛은 당연히보장이에요 우유.계란알러지있는아이라 채식케이크 먹는데 맛있다고 한조각 다먹는곳은 여기가 2번째에요 ㅎㅎ 쿠키도 맛있다고 잘먹어요 딸기.초코 케이크 둘다 맛있는데 애입맛엔 딸기가 더 맛있다네요 ㅎㅎ', 27, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '비건 중 맛, 크기, 가격 전체적으로 고려했을 때 보통이에요. 가격에 비해 크기 너무 작고요. 안 달다고 추천해주신게 다른 거보다 더 달았어요...', 42, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '역이랑도 가깝고, 디저트 진심 존맛탱입니다 ㅠㅠ! 사장님도 너무 친절하시고 자주 가고싶은 카페입니댜 분위기도 최고 👍🏻 맛도최고 힐링하고갑니다 ♥️', 23, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '카페분위기는 괜찮은데 직원이 좀 많이 지쳐보이네요 말하는데 끊고 뭐물어보는데 ..좀 기분이 나빳어요 ㅎㅎ.. 그래도 내색하지않았는뎅 나중엔 조금힘나셨는지 나중엔 텐션조금올리시더라구요 무슨일이있었던거겠죠~잘들렀다갑니다', 5, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '#합정동 #카페 #합정동카페 #비건디저트 #디저트카페 #카페 #라뽀즈 #자몽에이드 #얼그레이케이크 #통밀케이크 케이크를 건강하게 즐길 수 있는 비건 카페입니다. 아몬드브리즈라떼 메뉴도 있어요. 자몽에이드에 베리류가 들어가 있어서 저 새콤하게 즐길 수 있어요.', 24, 4, 'GOOD', SYSTIMESTAMP);
