INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '저는 비건도 아니고 달달한 디저트를 사랑하는 사람인데도 라뽀즈의 디저트는 비건이지만 정말 정말 너무 맛있습니다@@ 그래서 집도멀고 오늘 일정상 동선이 맞지도 않는데 굳이 찾아와서 진심 너무 맛있는 애플진저케이크와 남편이 사랑하는 통밀 얼그레이 케이크, 밀크티와 아이스아메 마시는 중입니다~ 환상적인 궁합이네요👍👍👍☺️☺️☺️ 합정역 디저트 맛집~~한번 와보세요🎈🎈', 50, 7, 'GOOD', SYSTIMESTAMP);
