INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마뽀즈 비건케이크'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '평소 유당소화 장애가 있어서 케익 한조각도 잘 못 먹는데 비건케익이라 속 부대낌 없이 항상 잘 먹었어요! 아몬드브리즈라떼도 강추에요!', 63, 17, 'GOOD', SYSTIMESTAMP);
