INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '숲다방'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '숲다방의 인테리어는 실제 숲을 실내로 옮겨둔 듯한 분위기를 느낄 수 있어요. 통유리창 너머로 햇살이 쏟아지며 실내 곳곳에는 대형 화분과 우드 가구, 초록 식물이 가득해요. 원목 테이블과 그린톤 소품, 자연광이 어우러져 따스하면서도 차분한 분위기를 연출해요. 전체적으로 편안하고 심플함이 강조된 공간으로, 자연 속 힐링 무드를 만끽하고 싶은 분들께 추천드려요', 72, 11, 'GOOD', SYSTIMESTAMP);
