INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '숲다방'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '예전에 밖에 있는 간판 보고 너무 예뻐서 찍어 뒀었다가 궁금해서 드디어 다녀왔어요!! 생각보다 안에 인테리어 진짜 예뻐서 뭔가 우리만의 아지트에 온 느낌이 들었어요 아늑하고 분위기도 너무 좋고 귀여운 소품들도 많아서 사진도 짱 잘 나옴 ㅎㅎㅎㅎㅎ 사장님도 완전 친절하시고 빙수도 짱 맛있고 걍 짱조음', 0, 1, 'GOOD', SYSTIMESTAMP);
