INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '숲다방'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '저희가 앉은 자리는 커플석이었어요. 별도 공간으로 떨어져있는데, 레트로 느낌의 비디오방? 그런 컨셉이에요 😀 큰 수툴과 소파가 있어서 다리도 편하고요, 조용해서 분위기도 좋습니다. (홍대에 이런 편한 곳이 있을줄이야🥹🥹) 컨셉은레트로인데 전반적으로 아주 깔끔합니다. 개업한지 얼마 안 됐나봐요. 큰 홀에서는 마침 영화 동호회가 대관행사 중이던데, 동호회 모임 자리로도 무드가 괜찮습니다. 메뉴로는 딸기요거트스무디 추천드립니다. ⭐️보다 한 수 위입니다 ㅎㅎ', 15, 9, 'GOOD', SYSTIMESTAMP);
