INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '숲다방'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '🚘 “홍대에서 무료주차 넉넉히 즐기며 감성과 뷰까지 챙긴 카페 찾으시나요? 바로 숲다방이 정답입니다!” 숲다방은 서울에서 보기 드물게 4시간 무료 주차가 가능한 곳이라 자차 이용자들의 성지가 되고 있어요. 레트로 무드가 가득한 인테리어와 넓은 통창으로 펼쳐지는 탁 트인 뷰는 오래 머물고 싶은 공간감을 선사합니다. 홍대입구역과 가까워 접근성도 뛰어나고, 빈티지 소품과 클래식 가구가 감각적 분위기를 더해줘 새로운 감성 카페를 찾는다면 강추! 이곳은 홍대입구역 3번 출구 근처에 위치해 찾기 쉽고, 카페에 들어서는 순간 압도적인 레트로 감성 인테리어가 눈길을 사로잡습니다. 오래된 라디오와 소파, 클래식한 조명 그리고 빈티지 소품들까지, 세월이 담긴 디테일이 카페 분위기를 한껏 살려줘 뉴트로 무드를 제대로 느낌', 7, 0, 'GOOD', SYSTIMESTAMP);
