INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '숲다방'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '인테리어가 너무 잘 되어있고 접근성도 좋은데다 무료주차까지 되어서 너무 좋아요! 엄마랑 같이 방문했는데 레트로한 물건들이 많이 있어서 사진 찍기도 좋고 너무 좋아하셨어요! 다음에 또 오고 싶어요😍 #홍대입구역카페 #레트로카페 #무료주차', 16, 9, 'GOOD', SYSTIMESTAMP);
