INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '숲다방'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '일정 사이에 쉬고 여유 시간 보내려고 잠깐 들렀거든요,,?! 무조건 기다릴 마음의 준비하고 왔는데 다행히 대기 없이 들어왔고, 인테리어가 너무..!!!!!! 예뻐요💞🫢 다음에 혼자 쉬러 또 오고 싶어용..🫶🏻 주차장 들어오는 길은 자동차에 핏하게 맞춘 것처럼 좁아요 ㅋㅋㅋㅋ !! 참고하시면 좋을 것 같습니당', 11, 1, 'GOOD', SYSTIMESTAMP);
