INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '숲다방'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '🌳 홍대입구역 3번 출구에서 1분, 숲다방(카페포레스트)은 도심 속 자연을 닮은 레트로 감성 공간이에요. 통창 너머 홍대경치를 바라보며 아메리카노(0.48만원), 딸기라떼(0.7만원), 수제디저트와 함께 여유를 즐길 수 있어요. 초록 식물, 따뜻한 조명, 레트로 음악 덕분에 혼공·데이트·감성사진 모두 만족! 플러그·와이파이·편안한 좌석으로 편의성도 좋아요. 인기 시간엔 웨이팅이 있으니 참고하세요. #숲다방 #카페포레스트 #홍대카페 #홍대커피맛집 #레트로카페 #홍대데이트코스', 6, 2, 'GOOD', SYSTIMESTAMP);
