INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '숲다방'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '홍대입구 3번 출구 앞이라 찾아오기 편해요 !! 주차도 가능해서 차있는 분들도 오기 좋을 것 같아요~ 시끄럽지않아서 대화하기에도 편안했어요. 음료랑 디저트도 맛있고 다음에 또 올 것 같아요 사진찍을 공간도 꽤 있어서 와서 예쁜 사진 남기시면 좋겠어요 ~', 16, 6, 'GOOD', SYSTIMESTAMP);
