INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '숲다방'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '홍대에 이런 곳이 있는지 몰랐습니다..! 카페 안 분위기도 너무 좋고 너무 느낌 있게 잘 꾸며놓으셔서 놀랐어요! 자리도 많고 다양한 연령층이 모두 즐길 수 있는 공간이라 더 좋은 것 같아요 특히 1인 빙수가 요물이네요 정말 맛있었어요 다음에 또 올게요!!', 44, 6, 'GOOD', SYSTIMESTAMP);
