INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '숲다방'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '가게 분위기가 너무 아늑하고 정겨워요 😊 사장님도 친절하셔서 덕분에 편하게 수다 잔뜩 떨 수 있었어요! 도란도란 이야기 나눌 수 있는 카페 찾으신다면 추천합니다!', 87, 12, 'GOOD', SYSTIMESTAMP);
