INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '숲다방'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '여기 소파도 있어서 아늑하고 레트로 감성 그자체..신청곡도 신청할 수 있고 분위기 정말 사랑스럽고 따뜻하면서도 힙합니다.!!.!!ㅠㅠ 연남동 안에 이런 분위기+레트로 예쁘게 살린 곳 드문데 여기 발굴해서 넘 기쁩니다.. 다음에 또 와야지🥹 메뉴 가격도 괜찮도 달달고소하게 맛있는 건 말모..널리널리 추천하고 싶은데 또 나만 알고 싶기도 한 아지트 같은 곳이예요🫶', 10, 10, 'GOOD', SYSTIMESTAMP);
