INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '숲다방'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '미리 찾아보고 온곳인데, 기대보다 더 공간이 예쁘게 꾸며져있고 음료도ㅠ너무 맛있었어요..!😊  무엇보다 조용한분위기에 노래나오는기 좋았고 사장님이 친절하셔서 기분이 너무 좋았습니다! 다음에 또 올게요오~><', 70, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '숲다방'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '커피도 맛있고, 분위기도 좋고, 인테리어도 너무 이뻐서 구경할게 한가득입니다! 게임도 관심 가지니까 무료로 할수있게 해주시고 노래도 듣고싶은 노래 선곡도 받아주셔서 너무 기분 좋게 쉬다가 갑니다! 다음에 이 동네에 또 오면 방문하고싶어요!', 6, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '숲다방'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '매장 분위기가 정말 좋아요. 전에 한 번 왔는데 마음에 들어서 다른 친구들 데리고 두번째 방문합니다. 처음엔 수박주스에 씨가 올라간 줄 알았는데 초코라 맛있게 먹었습니다 🍉 🌱🌱', 12, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '숲다방'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '홍대애서 나름 조용한 카페라서 이야기하기 편하고, 레트로한 분위기가 좋아요 !! 사장님도 친절하시고 좌석도 편해요 ~~ 청가자리는 사진도 잘 나옵니다 !! 음료도 맛있고, 리뷰쓰면 쿠키도 주세요 💛', 101, 22, 'GOOD', SYSTIMESTAMP);
