INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '숲다방'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '옛 분위기를 느낄 수 있는 감성 좋은 카페예요!!! 남자친구랑 왔는데, 대화하기 너무 좋은 분위기였습니다. 커플들이 와서 노래 들으면서 쉬다 가기 너무 좋을 것 같아요 ❤️❤️', 129, 19, 'GOOD', SYSTIMESTAMP);
