INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '숲다방'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '감성과 분위기의 숲 한가운데서 커피 한 잔 우연히 들른 이곳, 카페 포레스트는 그냥 카페가 아니었습니다. 한 발 들여놓는 순간, 마치 작은 음악 방송국에 들어선 듯한 느낌! 카페 한쪽에는 ''ON AIR'' 사인이 반짝이는 작은 라운지가 있고, 그 안에는 실제 외국인들이 모여 방송 토론을 하는 듯한 풍경이 펼쳐져 있더군요. 이적이면서도 신선한 분위기라 한참을 구경하게 됐어요. 사진으로도 이 감성을 다 담기 어려울 정도로 독특했답니다! 인테리어는 음악감상실과 북카페가 결합된 듯한 세련된  공간이고, 곳곳에 놓인 조명과 식물, 아기자기한 소품들이 정말 마음을 편안하게 해주었던거 같애요 저는 카페라떼 아이스를 주문했는데, 맛도 좋았고 가격도 합리적이었습니다', 127, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '숲다방'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '🥪 식사를 못하고 나올일이 생겨서 치아바타 세트를 주문했습니다. 나오는데 십분정도 걸렸네요. 산미있는 커피를 좋아하지 않는데 여기 커피는 맛있네요. 산미가 너무 강하지 않고 딱 기분좋을 정도입니다. 치아바타는 빵이 딱딱하지않고 먹기좋게 부드러워서 맛있어요. 🎶 적당한 크기로 음악이 나오고 있어서 앉아서 얘기하기도 좋아보입니다. 카페가 너무 조용해도 떠들기 힘들잖아요. 너무 크지는 않고 옆사람에게 얘기가 들리지도 않을만큼 노래가 나옵니다. 2000년대 즈음 노래가 많이 나오는데 전 옛날생각나고 좋네요 🪑 공간이 사진에 보이는것보다 안쪽으로 자리가 조금 더 있어서 널찍하게 앉을 수 있을 것 같습니다. 근처에 오면 친구들 데리고 올 것 같아요 추천ㅎㅎ', 58, 15, 'GOOD', SYSTIMESTAMP);
