INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '숲다방'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '친구가 홍대올때마다 오는 카페라고 해서 방문해봤는데 분위기가 너무 좋고 전체적으로 인테리어가 레트로해서 예뻐요 ♡ 집중하기도 좋아서 나중에 또 올 것 같아요! #홍대입구역카페 #레트로카페 #무료주차', 44, 5, 'GOOD', SYSTIMESTAMP);
