INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '숲다방'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '빙수가 너무너무 맛있어요….. ㅠㅠ 과자 아이스크림이랑 연유 넘 잘 어울려요 ㅠㅠ 옛날 빙수 짱! 다음에 1인아니라 2인 시켜야 겠네요 공간이 아늑하고 사장님이랑 알바생이 너무 친절하십니다:)', 7, 6, 'GOOD', SYSTIMESTAMP);
