INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '숲다방'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '인테리어가 이색적이고 옛날 노래가 나옵니다. 공부하러 왔는데 집중도 잘되고 좋은거 같습니다! 음료도 맛있어서 재방문의사 백퍼입니다', 109, 23, 'GOOD', SYSTIMESTAMP);
