INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '숲다방'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '홍대 놀러왔다가 검색해서 찾다온 홍대카페입니다 우연히 들어왔는데 분위기 너무 좋고.. 다방 컨셉이라 엘피판 여기저기 있어서 분위기 짱 아늑하고 음악도 좋아요 잔잔히 수다떨기 좋은데 작업하시는 분들도 많아 느낌굿입니다 커피도 맛있어용~ 넓어서 좋네요', 117, 21, 'GOOD', SYSTIMESTAMP);
