INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '숲다방'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '레트로스러운 음악다방 컨셉에 편안하고 예쁜 인테리어가 힐링하기 좋아요~ 직원분도 너무 친절하시고 음료도 맛있었습니다ㅎㅎ 오락실 기계가 있어서 이용하면서 재미있게 시간 보냈어요!', 19, 0, 'GOOD', SYSTIMESTAMP);
