INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '숲다방'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '빈티지한 전화기와 클래식 TV, 뉴욕타임즈 신문, 그리고 고전 영화 소품들까지 마치 레트로 영화 속 장면에 들어온 듯한 기분이 들었습니다 한쪽엔 커다란 강아지 인형과 브라운 인형이 반겨주고, 공간마다 배치된 소품 하나하나에 스토리가 느껴졌어요. 맛은 말할 것도 없이 부드럽고 진한 밀크티 풍미가 살아있었고, 단맛과 쌉쌀함의 조화가 딱 직접 만든 듯한 수제 느낌이 강했어요. 한켠에는 ‘숲속 라디오’처럼 꾸며진 녹음 부스 공간도 인상적이었는데요, 실제로 녹음도 하는 것 같더라고요. 사진 찍기 좋은 포인트가 정말 많아서 감성 인생샷 찍기 딱!!', 4, 6, 'GOOD', SYSTIMESTAMP);
