INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '숲다방'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '홍대에 워낙 힙한 곳이 많지만 산만하고 맘 편히 있을 수 있는 곳은 별로 없다 생각했어요 근데 우연히 들러본 곳이 이렇게 보물같을 줄이야.. 전망도 넓고 한쪽은 음악다방처럼 라디오가 흘러나오고 또 한쪽은 힙한 홍대 느낌을 내요 이렇게 두공간이 공존하는데 안정감이 느껴지는게 신기하네요', 38, 5, 'GOOD', SYSTIMESTAMP);
