INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '숲다방'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '그냥 모임때문에 일하러온건데 입장할때부터 일하는 내내 분위기도 인테리어도 너무예뻐서 자연스레 사진부터 찍고 음료 한 입했네요😆 너무예뻐요…….이름에 맞게 숲같은 인테리어가 인상적입니다 :) 음악들도 전부 잔잔하게 나오고 내부도 다들 대화는 해도 사장님이 조곤조곤하셔서 그런지 다른 손님들도 크게 안떠들고 조용한 분위기라 업무하기에 좋았습니다! 다음에 또 자주 오려구요 ㅎㅎ 홍대 6년살면서 이 좋은델 이제알았네요!🥰 자주올게요~~💚', 38, 2, 'GOOD', SYSTIMESTAMP);
