INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '숲다방'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '저 리뷰 잘 안쓰는데요오 너무 좋아서 리뷰 남겨요!!! 친구가 분위기 좋은 카페 추천해줘서 오게 되었는데 들어가자마자 친구들이랑 우와!! 하구 감탄했어요! 금붕어도 귀엽구요 🐟🐠🐡 분위기가 몽글몽글 빈티지하게 예뻐요! 음료도 맛있구요 내부도 시원해서 힐링하러 오기 딱입니다..🩷🥰🥰', 33, 4, 'GOOD', SYSTIMESTAMP);
