INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '숲다방'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '지나가다가 발견하고 들린 카페인데 인테리어도 너무 이쁘고 빙수도 싸고 맛있어요 사장님도 넘 친절하시고 신청곡도 받아주셔서 넘 좋았습니다ㅠㅠ', 12, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '숲다방'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '잠깐 시간 보낼곳이 필요해서 방문했는데 기대이상으로 좋아요. 일단 음악다방 컨셉에 맞게 음악 선곡 좋거 인테리어도 깔끔하고 좋네요. 특히 창문이 있어 밖에 보면서 커피 마시기 좋아요!! 치아버타 세트 시켰는데 사장님이 주문 즉시 만드시고 내용물들이 너무 신선해서 맛있어요 완전 추천이요', 9, 7, 'GOOD', SYSTIMESTAMP);
