INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '숲다방'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '지친 일상 속, 안정감을 느낄 수 있는 공간이라 좋았어요. 레트로 느낌이 물씬 풍기는, 편한 장소를 원하신다면 방문 추천드려요! 여기 치즈케잌이 정말 맛있습니다. 사장님도 친절하셔서 너무 좋았네요. 군인이라 이런 곳을 자주 들리지 못하는데, 오랜만에 좋은 카페에서 안정취할 수 있어 좋았습니다!', 53, 14, 'GOOD', SYSTIMESTAMP);
