INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '숲다방'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '홍대나들이 나왔다가 조용히 차 한잔마시고 싶어 들른 다방 레트로 분위기에 음악까지 완전 감성에 빠지다. 밥을 먹고 와서~ ㅠㅠ 샌드위치셋트메뉴 가성비좋아요. 담에 다시 꼭 더와야겠어요. 사장님~찐!! 친절하세요♡', 72, 15, 'GOOD', SYSTIMESTAMP);
