INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '숲다방'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '맨날 스타벅스만 가다가 자리없고 붐비고 정신없어서 새로운곳 찾아보다가 방문해봄 ! 조용하고 아늑해서 좋아요 사장님께 종종 잠시 공부하러 와도되냐 여쭤보니 흔쾌히 괜찮다고 해주셨어요 **그래도 1인1잔 + 시간길어지면 추가주문하기 조용히 편하게 작업하고 싶은분들 추천해용', 2, 6, 'GOOD', SYSTIMESTAMP);
