INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '숲다방'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '무료상담 보시고 방문하시는 분은 비추합니다. 어떤게 무료상담인지는 모르겠으나 저같은 경우 경매관련하여 건물의 무료상담이라고 광고판을? 보고 방문하였고 10~20분 가량 상담을 받았는데 상담료 5만원 청구하더라구요. 부가세도 손님한테 청구하여 5만5천원 결재했습니다. 상담내용도 지인을 통해 어느정도 알아보고 간 상태라서 저에겐 도움이 되진 않았네요. 방문하시고자 하는분은 상담할 내용이 무료상담인지 미리 연락하시고 방문하시기를 추천드릴게요.', 92, 24, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '다양한 텀블러도 판매하고 무엇보다 3개 층이라 엄청 넓어요!! 홍대입구역에서 약속 있으시다면 여기 꼭 들러 쉬다 가세요!!👍🏻😁', 91, 22, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '3,500원짜리 옥수수빵. 검지손가락 길이정도에 세 마디정도의 폭. 아껴먹지 않는다면 한입에 먹을 수 있을법한 사이즈다. 그러나 아껴먹으려고 나이프로 반을 갈라 구태여 속을 들춰보았다. 길게 늘어지는 빵에 알알이 박혀있는 옥수수를 마주했다. 옥수수 모양을 하고있지만 옥수수는 아닌, 그러나 속에 옥수수를 감추인 옥수수빵. 옥수수가 되고싶었던 빵이었을까, 빵이 되고싶던 옥수수였을까.', 89, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '할리스 커피는 괜첞은데 차량 이용을 해야해서 전화상으로 주차 가능한지 여쭤봤는데 여성분이 주차장이 다 차서 주차 불가라고 하시더군요, 그래서 할리스 전용 주차장이 만석이냐고 여쭤봤고 주위에 주차 가능한 주차장이 있냐고 여쭤봤고 주처장이 먼속이고 다른 주차 공간이 없다고 하셨습니다. 동행을 먼저 내려주고 다른곳에 주차할 생각으로 도착하니 제휴를 맺은 유료 주차장이 바로 옆에 있고 주차 공간도 많았습니다. 무슨 사유로 그렇게 응대했는지는 모르겠으나 할리스 본사에서 알바 혹은 직원분들 주차장 안내에 대한 교육 혹은 시정조차가 필요한거 같습니다.', 47, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '할리스 홍대역 2번 출구점에 왔어요. 1층부터 3층까지 있고 넓고 안락하고 전망도 좋아요. 카푸치노에 시나몬 많이 해서 먹는데 아주 맛있어요.', 95, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '홍대점 할리스 <찐리뷰> 주말이라 역시 사람이 엄청 많아요 3층까지 있어요! 2층에는 여자화장실 3층에는 남자화장실 직원들이 불친절했어요 저희 엄마가 물이 없어서 말씀드렸더니 저기있잖아요ㅡㅡ 이러면서 무시하듯이 대하고 제가 가니까 급 태도가 바뀌더라구요? 알바인지 직원인지는 모르겠지만 교육부터 제대로 받아야될것같네요; 놀러와서 기분만 잡쳤어요', 27, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '청포도케일착즙주스는 건강한 맛이네요 청포도가들어가서 맛있어요 딸기치즈케익할리치노 이름 읽기도 힘드네요 ㅎ 치즈맛이 진하게 나고 요거트맛도 나요', 29, 5, 'GOOD', SYSTIMESTAMP);
