INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '크리스마스가 다가오는 일요일 낮 14:40 방문 그때는 1층에는 손님이 북적이지 않았는데 1시간 정도 후 부터 꽉~~찼다! 카스테라 넘 맛있었음.', 62, 18, 'GOOD', SYSTIMESTAMP);
