INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '홍대입구역에 있는 커피숍에  왔습니다 할리스 커피숍 입니다 3층까지 있어요 밤 열두시까지 영업을 해서 참 좋아요. 오늘도 화이팅!!', 81, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '영어 통역을 하기 위하여 홍대입구역 위워크 갔는데 입장이 안 되었어요 아마도 시스템 오류인듯 합니다 그래서 부랴부랴 홍대입구역 커피숍 중에서 한군데 찾아 갔습니다. 홀리스 커피 입니다.', 18, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '직원들이 너무 불친절. 제가 직원 분들께 서비스 해드리는 줄 알았습니다. 자원봉사도 이거보다는 친절합니다. 손님한테 돈 받고 서비스도 받네요.', 33, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '오픈한지 얼마 안된 할리스 홍대역2번출구점! 편안한 할리스만의 분위기가 좋아요! 앱 쿠폰으로 1,000원 할인되어서 행운이쑥쑥라떼 먹어봤어요!~ 가격은 6,300원 맛있어요!~!!', 41, 0, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '점장으로 보이는 아줌마가 너무 불친절합니다. 다른 직원들은 친절해서 항상 좋은 인식 갖고 있었는데 이젠 아니에요. 고객 응대하는 법 좀 다른 직원들께 배우셔야겠어요~~~아니면 본사에서 교육을 좀 받으시던가', 24, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '첫사진은 6월4일에 방문해서 찍은 사진이고 두번째 사진부터는 6월27일에 방문해서 찍은 사진입니다. 딱보기에 얼음 양부터 너무 차이나지않나요??? 직원에게 가져가서 말을 해보니 정량을 사용했다는 말과함께 주문이 완료되고나서 10분후에 수거해갔다라고 하는데 네번째 사진이 할리스어플에 알림이 뜬 시간이고 다섯번째사진이 음식을 받아 온 후 바로 찍은 사진의 시간입니다. 3층에서 1층까지 다녀온게 4분이에요. 10분이 어디서 나왔는지 모르겠습니다. 4분 안에 3층까지 가지고가는데 빙수의 얼음이 반이나 녹는게 맞는지도모르겠습니다. 만약에 얼음을 눌러 담아 만들어서 그런거라면 맛없어보이게 만든 직원 잘못이 아닌가생각이 듭니다. 오늘 정량이라는 말만 반복하던 알바생의 태도도 그렇고 고객으로서 할리스에 너무 실망했습니다.', 115, 25, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '홍대역에서 가깝고 좌석이 3층까지있어서 엥간하면 주말에도 자리가 있어요ㅋ 3층은 스터디하는 좌석도 있네요 음료도 맛 괜찮아요~!', 42, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '애플망고 치즈 컵빙수  가격이 9천원.. 애플망고와 그냥 망고랑 섞여있고 치즈큐브, 코코넛칩  마지막으로 망고시럽드레즐.  빙수는 눈꽃빙수지만... 우유와물비율이 ...물이더높은듯? 빙질이 부드러운 우유얼음 느낌보다 그냥 얼음느낌이라 겉으로보기에는 일반 설빙같은 눈꽃빙수의 형태지만 먹을때 느낌이 다르다. 너무막달지는 않고 적당히 단망고빙수. 연유느낌은 거의없딘. 안들어간듯?', 37, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '리얼수박생과일쥬스 마셨는데 슬러시처럼 음료가 되어있고 수박도 많이 올려져있어서 좋아요 ~ 음료가 수박맛을 잘 재현해내서 맛있게먹고갑니다', 19, 2, 'GOOD', SYSTIMESTAMP);
