INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '홍대 할리스 중에서 가장 깨끗한 곳이 바로 홍대역2번출구역점입니다. 다른 곳에 비해서 메뉴는 조금 아쉬운데 인테리어와 청결도 면에서는 좋습니다. 시야도 확 트여서 친구들이랑 이야기하기가 참 좋은 곳이다보니 자리 쟁탈전이 벌어지곤 합니다.', 39, 7, 'GOOD', SYSTIMESTAMP);
