INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '할리스 오랜만에 갔는데 메뉴도 다양해지고 좌석도 대학가에 맞게 노트북 자리, 독서실 자리로 구성해놓은 걸 보고 많이 신경쓰고 있다는 게 느껴졌네요, 5월이라 창밖으로 보이는 녹음 덕분에 잘 쉬다 갑니다!', 40, 7, 'GOOD', SYSTIMESTAMP);
