INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '오랜만에 친구랑 카공하러와서 과제했는데 공부하기도 좋고 요즘 나무 초록초록해서 3층 뷰 넘 이뻐용🌿 에어컨 틀어주셔서 넘 시원하고 좋았어요^^', 16, 1, 'GOOD', SYSTIMESTAMP);
