INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '창가자리 뷰 좋은데 직원은 손님이 들어와서 주문을 하려  하건 말건 신경 안쓰네요. 주문해도 힐끗쳐다보고는 자기 일 하다 카운터 앞에서 계속 기다리니  그제야 오네요. 이런 사람을 직원으로 쓰다니 알바구하기가 힘든가봐요.', 46, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '혼자 방문했는데 가게가 엄청 넓직해서 좋았어요 오후 되면 사람이 많아지긴 하지만 어딜가던 사람이 많은 주말 홍대에서 앉을 수 있다는 것만으로도 만족했습니다..!!', 42, 8, 'GOOD', SYSTIMESTAMP);
