INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '오랜만에 홍대역 2번출구 할리스에 방문했어요. 빌딩통으로 사용하고 있으면 카공족들이 엄청 많은 커피숍입니다. 개인적으로 3층을 좋아해서 3층에만 있는데 카공하기좋고 집중할수있어서 너무 좋아요. 오늘도 편안히 작업하다가 갑니다.', 28, 7, 'GOOD', SYSTIMESTAMP);
