INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '오후 3시쯤 방문했는데 자리가 많이 없었어요! ‘딸기 초코 박스’ 먹었는데 생각보다 꾸덕하고 많이 달아서 아.아 필수입니다 💫', 24, 4, NULL, SYSTIMESTAMP);
