INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '3층 건물이라 자리많아서 좋은데 그만큼 사람도 많더라구용 그래도 사장님께서 수시로 자리 체크하면서 관리해주셔서 깔끔하고 쾌적해서 또 올려구요☺️', 23, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '일인일음료. 외부음식안됩니다. 다  당연히 이해해요. 환경생각해 텀블러 들고다니는친구. 친구랑 이야기중 대뜸 텀블러주문받은적 없다며 영수증을 요구하더라구요. 공손하게 물었음 좋겠던데 기분이 나빴습니다. 이미일층에서도  비슷한 상황을본터라 할리스는 이런가보다 생각들게하네요. 글쎄요  저만에 생각일까요.... 영수증이라도 버렸음 cctv 돌리나요', 66, 11, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '커피든 일반 음료든 모두 맛이 별로라는 건 원래 알고 있었지만, 그래도 구조와 자리가 좋아서 이용했었습니다. 하지만 손님들을 대하는 직원 매니저와 점장의 인성을 볼 때면 항상 불쾌해서 더 이상 이용 안 할 계획입니다.', 11, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '할리스의 시그니처메뉴!!! 바닐라딜라이트~ 달달구리 최고^^ 텀블러 300원 할인받아서 먹으니 지구도 살리고 내 주머니 사정도 살리고 1석 2조네요♡', 79, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '친목모임이여서 점심식사후 커피타임가지러 방문했네요~그런데 2층에서 자리잡고 기다리는데 진동벨을 안주셔서 대략난감 이였어여~>< 그래서 얼추기다리다가 내려가보니 이미 나와있었네여 그래서 2층인데 진동벨을 안주셨다고 말하니,,,"저희 직접 불러드리고있어요" 라는 직원분의 한마디에 더큰 대략난감--;;)))2층까지 그 소리가 들린다고 생각하시는건지?!?!ㅜㅜ 그리고 옆에보니 진동벨도 있었다는것ㅜㅜ 담부턴 진동벨 주세여~!!', 8, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '1,2,3층이라 자리가 넓고 디저트류가 많아요! 매장에 아직 에어컨이 나와서 시원합니다~ 1층에 놓여진 인형들이 귀엽네요 ㅋㅋㅋ', 50, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '홍대역 2번 출구에서 엄청 가까운 할리스 바닐라 딜라이트 멤버십혜택 받아 사이즈 업 해서 6100원에 먹었네용. 테이크아웃으로 조용한 편이고 매장도 쾌적한 편이에요. 좋네용.', 18, 7, 'GOOD', SYSTIMESTAMP);
