INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '오랜만에 방문한 할리스 홍대역 2번출구점! 혼자 조용히 커피마시기 너무 좋아요 :) 노트북 들고와서 작업하시는 분들이 많네요. 샌드위치 종류가 좀 더 다양했으면 하는 아쉬움이...', 20, 5, 'GOOD', SYSTIMESTAMP);
