INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '가끔은 카페가 너무 바빠서 어쩔 수 없이 패스오더를 사용하는 바로 옆 카페로 가요. 여기도 빨리 패스오더로 주문이 가능하면 좋겠어요가끔은 카페가 너무 바빠서 어쩔 수 없이 패스오더를 사용하는 바로 옆 카페로 가요. 여기도 빨리 패스오더로 주문이 가능하면 좋겠어요', 27, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '늦게까지 영업해서  밥 먹고 수다 왕창 떨고 싶을 때 와요. 블랙아리아딥라테는 오늘 처음 마셔봤는데 거품이 풍성하게 올라가져 있어서 부드럽고 고소했어요. 할리스 최애 메뉴될 듯~', 50, 5, 'GOOD', SYSTIMESTAMP);
