INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '매장내에서 음료 다 마시고 나오려는데 컵안에 초록색 실털? 인지 수세미같은게 나와서 나가는길에 “이런게 컵에 있었다.” 라고 말하니 “우리는 이런 초록색이 나올게 없다” 하심. 나올게 있던 없던 제공된 음료안에 이런게 나왔으면 “죄송하다. 위생에 주의하겠다.” 이렇게 말해야하는게 정상아닌가요. 제가 일부러 뭔지도 모르는 고명을', 46, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '수박 쿨러 스무디 사진이랑 다르게 생기고 통상 카페에서 낼 수 있는 가장 작은컵에 줌. 양 정말 적고 비싼데 맛은 있음 사람 많음', 435, 70, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), 'kt vvip쿠폰으로 바로 결재 무리없이 사용했어요 연남동에 보기 드문 넓은 공간에 조용하고 쾌적한 할리스 분위기가 북적이지 않고 좌석간격 넓직하고 좌석이 편해서 인근 할리스중 단연 최고예요 주말인데 좌석이 한두자리씩 계속 비어주어 좋네요 주말에 혼석하기 좋은카페 흔치않은데 최애공간입니다', 17, 9, 'GOOD', SYSTIMESTAMP);
