INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '현금으로 계산하려니까 굉장히 불친절로 주문을 받네요 가지고 온 과자 당연히 먹을생각도 없었고 손에 들고있었을 뿐인데 ;; 말투부터 대하는 태도 응대 모두 불친절합니다 날도 덥고 손님 많음으로 바쁜것은 이해하나 서비스직업이면 이런식에 태도는 상당히 불쾌하네요', 26, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '홍대입구 카페중 가장 대화하기 편합니다! 음료가 다양하고 디저트 종류도 다양해서 좋았습니다 🤓 무엇보다 좌석간의 거리가 있어 너무 어수선하지 않고 대화하기 적합한 카페였어요!', 78, 17, 'GOOD', SYSTIMESTAMP);
