INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '노캔 되는 이어폰이나 헤드셋 가져가야 집중 잘돼요 언제나한 두 자리 정도는 있는 곳이라 작업할때 자리가 보장되는 곳! 사실 커피는 별로..', 48, 7, NULL, SYSTIMESTAMP);
