INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '1인용 팥빙수가 잇어서 냉큼 주문~~ 암만 1인용이라지만 푹 들어간 내용물에 조금 실망~~팥이 적다고 생각햇는데 먹어보니 넘넘 달아서 더많아도 안될뻔 햇네요 ㅠㅠ 실내는 깨끗하고 테이블간 거리가 잇어서 맘에 들엇습니다', 67, 18, NULL, SYSTIMESTAMP);
