INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '손님음료주변으로 세제를 뿌려 청소하시네요...일부러 마감시간다됬으니 나가라는뜻인지... 기싸움 손님하고 하지맙시다 교육좀 시켜주세요 저번에도 가방놔두고 어디갔다온 손님이랑 말싸움 거하게 한거 봤는데 브랜드이미지 안챙기시나요?', 21, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '토요일 밤에 갔는데 사람 진짜 많았어요,, 그래도 매장이 넓어서 그런가 앉을 곳은 있었습니다. 망고빙수 주문해서 먹었는데 괜찮았어요!! 밥먹고 3명이 먹으러 갔는데 배불러서 다 못먹음 ㅠㅜㅠ 그리고 망고퓨레인지 시럽인지는 모르겠지만 너무 달아서 안 뿌리고 먹는 게 더 맛있었습니다!', 52, 18, 'GOOD', SYSTIMESTAMP);
