INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '카공하시는 분들이 엄청 많아요. 사람이 많은데… 장시간 노트북이나 태블릿 올려두고 자리 비워두는 비매너 비양심만 좀 없었으면 좋겠어요. 많은 분들이 엄청 서서 기다리다가 그냥 갑니다.', 67, 13, 'BAD', SYSTIMESTAMP);
