INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '복숭아 얼그레이랑 얼그레이 티 둘다 아이스로 주문을 했었는데 실수로 따뜻한 걸로 주셔서 다시 만들어주신 점 감사했습니당! 다만 따뜻한거 만들어진 걸로 얼음만 부어서 맛이 많이 밍밍했어요...ㅜㅜ 얼음도 금방 녹아서 없어지고ㅠ 그래도 부탁드리니 얼음 더 주셔서 감사했습니다 :)', 1, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '화장실 굿 노트북하고 과제하기 좋음 근데 집중해서 공부하긴 어려움 노래가 너무 내취향이라 노래따라가게됨. 12시까진데 11시40분?정도부터 나가라는 안내방송 엄청 크게 나와서 그 방송 나올 땐 아무것도 안들림 수업도 잘 안들려서 못함.', 57, 17, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '7월 할리스앱에 스무디 1잔 구매하면 아메리카노를 주는 쿠폰이 있어서 사용했어요 :) 음 수박 스무디는 냉동 수박이라서 기타 브랜드보다 맛이 떨어져요.', 90, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '외부음식 반입이 안되면 안된다고 문앞에 아주 크게 써 놓으세요...... 외부음식 가져와서 안먹겠다해놓고 먹고 쓰레기버리고기는 무뇌인 사람들이 많아서 그렇게 예민할수있겠다고 백번 생각해봐도 카운터 앞에 자리를 잡았고 만석도 아니었고 바로앞에 앉았으니 먹을일이없다 안먹겠다 하는데도 "외부음식반입금지입니다 주문전에 미리 말씀드리는거에요" 하는건 나가라는 말이죠? 실랑이가 좀 있으니 그제서야 다른 직원분이 맡겨드리겠다 말하는 어이없는 상황.. 그렇게 응대하신 분이 매니저라는게 아이러니하네요 케익 찾으며 아까는 나가라는 식으로 말한게 맞냐니까  그렇게 들리셨고, 불쾌하셨으면 죄송하지만 대부분의 손님은 그렇게 말하면 나간다고? ㅋㅋㅋㅋ매니저님 일을 그렇게 하시면 안되요 때려치우고 집가서 티비나 보세요', 9, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '할리스 홍대역2번출구점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '자리도 편하고 매장도 넓고 친절하고 다 좋아요!! 2-3층 자리들에서는 나무가 보이는 것도 좋습니다! 근데 공부하는 좌석들을 많이 만든 것에 비해 음악이 다 너무 시끄러운 음악만 나와서 항상 아쉬워요ㅜㅜ음악때문에 조금 산만해지는 느낌? 개인적으로는 그냥 가사 없는 음악이나 잔잔한 음악이 나오는게 더 좋을 것 같아요ㅜㅜ 그래도 좋아요 할리스 매장중에 젤 좋아요', 7, 7, 'GOOD', SYSTIMESTAMP);
