INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '1984'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '홍대의 아이덴티티를 간직하고 있는 가장 홍대스러운 카페. 20년간 홍대를 사랑해온 한 사람으로서, 최후의 보루로 문화를 지키는 등대로 계속 이어나갔으면 하는 마음. 출판사가 하는 카페라 아우라부터 다르다', 89, 12, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '1984'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '차분하고 감성적인 카페 ‘1984’✨ 혼자 업무하거나 공부하기에 좋은 분위기에 친구들과 소소한 일상의 스몰톡 하기 좋은 카페입니다☺️', 6, 0, 'GOOD', SYSTIMESTAMP);
