INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '1984'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '많은 것들을 파는 만물상같은 카페 : ) 책도 팔고 옷도 팔고 신발도 팔고... 굿즈도 팔고... 커피에 알콜에... 등등 많은 것들을 파는데 조잡하지 않고 좋아요. 커피맛은 조금 아쉬웠지만 이만한 분위기에  조용하고 작업도 할수 있고 집중력도 높아지는 연남동에 카페가 쉽지 않다는거.. 알만한 사람은 다 알쥬 ㅋ 무튼 재방문해보고 싶긴 합니다. 집이랑 멀어서 아쉽지만 : ) 헌 책을 가져오면 음료가 무료라고 해서 집에서 코~ 자는 책들을 깨워서 데려와야겠어요 ㅋ', 497, 50, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '1984'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '의자가 되게 편합니다 음악도 시끄럽지않아서 좋아요 다만 접객태도가 아쉽습니다 제가 뭔가 실수를했거나 오면안되는데 방문한줄알았어요... 먹고가는데 종이컵에 주는것도 별로입니다', 42, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '1984'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '커피 음악 그리고 책 세개로 이미 종결나는 카페 꽤나 오래전부터 있던 카페인데 갈때마다 항상 한켠에 있는 판매한 책들을 구경하는 재미가 있음 커피는 그냥 한국인이면 누구나 좋아할 맛이고 케이크와 함께 구매해도 만원초반대니깐 홍대에서 가성비 나쁘지 않았음 카페에는 대부분이 작업러와 독서하시는 분들이라 분위기는 매우 조용한 편이고 자리는 생각보다 빨리 나는 편은 아님 일단 오늘 재즈 노래들으면서 책을 보니깐 그냥 이 자체가 힐링되는 느낌이고 집중하기 좋았음 테이블에 놓여있는 카세트에서 오랜만에 테이프 갬성을 느끼니깐 갬성까지 챙길수 있는 카페임', 60, 16, 'GOOD', SYSTIMESTAMP);
