INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '1984'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '까페에서 옷은 처음 사봅니다 복합공간같은 느낌인데 후드 디자인이 이쁘고 재밌어보이는데다가 가격도 합리적이어서 좋았어요! 다음에 또 가보고싶습니다! ❤', 82, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '1984'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '아이스 우롱차, 하이볼, 휘낭시에 시켰는데, 우롱차는 괜찮았대요. 휘낭시에도 맛있었어요 하이볼은 제가 아는 하이볼이 아니더라고요. 하이볼이라기보다 진토닉같은ㅜ 분위기가 차분하고 구경할 상품도 있이서 아이가 좋아해서 가는데, 하이볼은 시키지 말아야겠어요.', 11, 7, NULL, SYSTIMESTAMP);
