INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '1984'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '독특한 북카페 두번째 온듯한데 그때랑 또 달라진 느낌이에요 내부엔 소품과 옷 신발등도 구매할 수 있어요 편집샵 북카페 복합문화공간 느낌입니다. 커피는 좀 진한 편? 작업하기 좋고 대화하기도 좋고 야외 자리도 있어서 날좋을땜 바람쐬기도 좋구요 와서 책을 읽어본 적은 없지만 다양한 장르가 구비되어있어 흥미로운 공간이에요', 89, 16, 'GOOD', SYSTIMESTAMP);
