INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '1984'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '책읽기 좋았어요. 거의 오는 손님이 혼자 챡을 보거나 일을 하고 있어서 조용히 혼자만의 시간을 보내기 좋았네요 읽고 싶은 책 한권 들고 방문해보세요. 근데 실내가 좀 어두워 저처럼 나이가 있어 노안이 있는 분은 좀 힘드네요 ㅎㅎ 편짒샾이랑 같이 되어있어 책읽다가 구경도 한번씩~ 가격은 ㅜㅜ 지하철역이랑도 가까워 더 좋았어요 참! 고소한 맛 좋아하는 저에겐 커피는 별루였어요', 1, 3, NULL, SYSTIMESTAMP);
