INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '1984'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '카세트 테이프를 청음할 수 있고 책도 놓여있습니다. 레트로한 분위기와 야외테이블도 있습니다. 매장이 넓도 짙은 우드 테이블과 나무가 차분함을 더해줍니다. 따뜻한 레몬차도 몸을 녹여줘서 좋네요 즐길 거리가 다양하게 많은 1984 매력적인 공간입니다', 95, 20, 'GOOD', SYSTIMESTAMP);
