INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '1984'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '사장인지 알바인지 모르겠는데 일하시는 여성분 응대가 너무 매너없음. 커피맛 인테리어등은 괜찮으나 직원 응대가 불만족스러워 다신 안갈듯. 기본적인 인삿말정도는 하시길', 8, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '1984'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '갈때마다 불친절해요 말투도 불친절하고 커피 탁탁 놓고 영수증은 꾸겨서 던지고 생 난리네 몇번 더 가면 다를 줄 알았는데 매번 같으니 뭐 다시 갈 일은 없을 것 같네요', 37, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '1984'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '아조씨 연남 탐방,, 낭만 가득,,, 카페,,, 방문,, 좋은 점: 매장이 넓고,,, 굿즈도 팔아서,,, 구경할게 많아서 좋읍니다,,, 음악,,, 잘 나오고,,, 창밖 분위기까지 하면,,, 낭만 가득입니다,,, 책 좋아하시면,,, 더 좋아할 공간입니다,,, 아쉬운 점: 분위기 좋지만,,, 커피나 디저트 맛 자체는 평범한 것 같읍니다,,, 행복은,,, 어디에나 있는 것,,, ^^', 37, 10, NULL, SYSTIMESTAMP);
