INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '1984'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '커피는 진하고 맛있는데 직원분이 불친절하네요 마감 40분 전에 들어왔더니 성가신 티 팍팍 나시고 45분에 커피 걷어요~ 하시고 뭐 나가라는 줄 알았어요', 115, 23, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '1984'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '홍대 2번출구랑 가까운 카페. 플리도 느낌있고 한 켠엔 편집샵처럼 꾸며져 있어서 프랜차이즈 카페와 다른 멋이 있다. 개인작업하거나 친구랑 대화하기 좋음😌', 48, 1, 'GOOD', SYSTIMESTAMP);
