INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '1984'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '주말 홍대는 어딜가나 만석이라, 그나마 한적한 곳 찾아 들어갔는데 ㅎㅎ 여긴 응대하는 직원들이 다 죽상을 쓰고 있네요~ 사근사근하게 웃는건 바라지도 않아요 😅 주문받은 파란색 후드 입은 남자분.. 어찌나 한숨을 푹푹 쉬며 못마땅한 표정과 말투로 주문을 받는지~ 뭐 잘못한줄요 ^^ 앉으려는 테이블에 전 손님이 음료잔을 놓고 갔길래~ 치워달라고 했더니 잔만 가져가고 테이블은 닦지도 않네요~ 커피 한잔 마시면서 대단한 퍼피독 서비스 바라지도 않아요^^ 직원들이 기본적인 서비스 응대 마인드라도 갖추었으면 :)', 17, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '1984'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '불친절..의 끝판왕...입니다.. 추워서 근처 카페 검색후 후기가 좋아서 들어왔으나 주문할때부터 내내 기분이 안좋으신지 표정이 안좋으시더라구요 음료나올때도 트레이에 나오지도 않고 음료잔만 덜렁 주시고 이렇게 나오는곳 처음본것 같아요 분위기도 좋고 가기전에 기대했는데 저말고 다른분들도 이런 리뷰가 있는거 보면 조금 개선하는게 좋을것 같네요', 50, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '1984'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '연남동에서 정말 오래된 카페이자 소품샵으로 늘 새로운 책들과 아이템, 팝업스토어가 있어서 문화생활 하는 느낌이 들어요. 오래오래 머물러주세요😀', 20, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '1984'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '음료도 맛나고 다양한 구경거리들이 많아요. 음악도 여유롭고 좋고 좌석도 참 다양해서 좋아요. 책은 구매해야지만 읽을수 있어서 아쉬웠지만 다양한 소품 및 책들 재미나게 구경하고 가요. 노트북하거나 혼공 및 독서하러도 많이들 오시던데 테라스도 활짝 열어있고 그만큼 차분하고 분위기 좋은 곳이였어요.', 11, 7, 'GOOD', SYSTIMESTAMP);
