INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '1984'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '1984 예전에 엄청 친절하고 좋았던 기억에 재방문했어요. 오늘은 다른 분이셨는데 그 친절함은 없어져서 아쉬웠어요.. 넘 졸려서 잠깨려고 커피 시켰는데 푹신한 쇼파에서 살짝이지만 푹 잠들었어요ㅋ 커피는 산미 거의 없고 쌉싸름해서 제 스타일입니다.', 19, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '1984'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '6500원에 이 양이라면 좀 비싼..ㅠㅠ (음료 종류에 따라 컵과 양이 다른듯하다) 양이 적어서 얼음도 무척 빨리 녹고🥲 근데 커피류는 아메리카노 리필이 된다더군요? 공간은 참 멋있는데요! 그냥 홍대 쪽 왔을 때 멋진 곳에서 작업/과제하고 싶을 때 오시면 좋을 듯 하다!!', 39, 7, NULL, SYSTIMESTAMP);
