INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '1984'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '매장에 작은 편집샵도 있구 노래도 감성적인게 나와서 너무너무 좋았어용🥺 직원분들도 엄청 친절하시고 조용하게 공부하다 가기에 너무너무 좋은 곳이에요😚 다음에도 또 올 것 같아요!! 그리고 넛츠크림라떼가 너무 맛있어요~~다른 곳에서 먹었던거랑 차원이 달라요 강추합니다🥳', 108, 21, 'GOOD', SYSTIMESTAMP);
