INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '1984'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '홍대 근처 힙한 북카페. 커피는 비싸도 리필이 한 번 더 가능함. 커피맛도 좋음. 책은 물론 카공족에게도 편리한 시설. 야외 테라스까지 완벽 그잡채.', 43, 1, 'GOOD', SYSTIMESTAMP);
