INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '1984'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '다양한 책들과 소품이 있어 또다른 경험을 할 수 있는 카페 1984♡ 우롱차는 생각보다 진하게 덖어져서 풍미가 좋았고, 호두파이 따뜻하게 구워주셔서 잘 먹었어요! 조용한 분위기로 집중하기 좋아요', 130, 21, NULL, SYSTIMESTAMP);
