INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '1984'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '홍대에 이렇게 분위기 좋은 곳이 있는줄 왜 지굼까지 몰랏쬬 ??? 뭔가에 집중하기 아쥬 좋은 분위기*__* 그리고 책이랑 다양한 소품들도 있어서 구경하는 재미도 쏠쏠해욥', 6, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '1984'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '홍대1984  늘 오는곳 오늘은 남편이랑 같이 나들이나왔는데 역시 조용하고 커피마시기좋은곳이예요 야외테라스  에서 먹는커피맛 ㆍㆍ최고', 46, 0, 'GOOD', SYSTIMESTAMP);
