INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '1984'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '구경하는 재미가 있어요. 혼자 온 사람들이 많아요. 독서와 비지엠이 어울리진 않아요. 가져온 책이 없으면 포장 안된 책을 골라 읽고 깨끗이 갖다놓으면 돼요', 50, 10, NULL, SYSTIMESTAMP);
