INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '1984'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '화장실 냄새 너무 불쾌해요 깨끗해보이는데 마스크 뚫고 들어오는 냄새때문에 토할거같아요,, 그리고 화장실에 누구있는지 확인 도와달라 부탁드렸는데 20분 가량 넘게 그냥 기다리게 해서 너무 불편했어요. 아무도 안에 없는데 화장실 키가 없으니 기다리라고 하셔서 기다렸는데 20분넘어간다고 확인부탁드렸는데 안해주셔서 다른분한테 또 부탁드렸어요. 30분만에 겨우 화장실을 들어 갔는데 냄새에 눈물 좔좔이네요.. 그래도 쥬스는 먹을만해요. 책은 좋은게 많네요-!', 58, 15, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '1984'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '친구랑 같이 왔어요 분위기가 되게 좋은거같아요 원래 카페가면 1시간도 안있고 오는데 여기는 볼거리가 많았어요 책도 읽고 셀카찍으면서 2시간 넘게 시간 보내다가 왔습니당', 1, 2, 'GOOD', SYSTIMESTAMP);
