INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '1984'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '동교동 최애 까페. 1984 샌드위치가 특별히 맛있는 이유, 사과가 들어가서 그런듯. 건강착즙주스도 맛있음... 모양이 너무 귀여워서 오늘 처음으로 치즈케익도 주문함 (치즈케이크는 음... 투머치 스윗)', 3, 5, NULL, SYSTIMESTAMP);
