INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '1984'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '깔끔하고 상태 좋은 프라이탁 제품 구입했습니다:) 프라이탁 구매할 생각으로 방문했는데 여러가지 볼 것도 많고 음료,케이크가 맛있었습니다ㅎㅎ 직원분들도 친절하셨어요! 홍대 갈 때마다 방문하게 될 것 같아요', 215, 40, 'GOOD', SYSTIMESTAMP);
