INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '1984'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '제가 진짜 라떼를 너무 좋아해서 라떼종류는 거의 다 먹어봤고 쌀라떼 먹었는데 생각보다 너무 맛있었어용  라떼에서 쌀맛나니 신기하네요 ㅋㅋ', 25, 0, 'GOOD', SYSTIMESTAMP);
