INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '유포테이블카페&마치아소비'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '환락의 거리 개봉 이벤트로 방문했어요. 두번째 방문이네요. 음료는 다키 규타로 두 잔 주문했고, 다키가 훨씬 맛있었습니다😅 굿즈는 첫방문때와 크게 달라지지 않았습니다만, 무한성 개봉하면 굿즈 종류도 많아지고 바뀔거 같아요. 먼거리로 왔는데 여기오면 뭔가 마음이 편안해 지네요.', 49, 7, NULL, SYSTIMESTAMP);
