INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '유포테이블카페&마치아소비'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '에어컨 고장으로 충공깽스러운 경험을 하게됨 체계가 아직도 안잡혀있는듯하고 알바생은 불친절함(특히 남자직원분) 매장은 좁은데 사람은 많아 도떼기 시장수준 경악스러운 테이블 몇대와 매장구조 서큘레이터 몇대만이 돌아가고있는 ..기대가 큰 만큼 실망감도 컸음 더워서 굿즈구경이고 뭐고 보이는거 집어들자마자 나옴...😓같이 간 사람은 가격에 경악하고 랜덤굿즈 중복에 경악하고..뜨악스러운 하루였음', 44, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '유포테이블카페&마치아소비'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '남성 직원의 태도 정말 최악이었습니다! 남성 직원의 태도 정말 최악이었습니다! 남성 직원의 태도 정말 최악이었습니다! 남성 직원의 태도 정말 최악이었습니다! 남성 직원의 태도 정말 최악이었습니다!', 36, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '유포테이블카페&마치아소비'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '다키 규타로 팬인데 혈귀 굿즈가 많진 않았어요. 환락의 거리 끝난지 2~3년 지나서 그런걸 수도 있지만 아쉬웠습니다. 거의 탄지로 일행이나 하시라 굿즈들이 많아서 캐릭터 덕후들 탕진하기 좋아요. 음료도 생각보다 나쁘지 않았어요. 재방문 의사 있습니다.', 38, 10, NULL, SYSTIMESTAMP);
