INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '유포테이블카페&마치아소비'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '매장 안 미츠리 너무 예쁘고.. 랜덤이 너무 많은건 아쉽지만 캐릭터들 생일때마다 메뉴랑 굿즈 일부 새로 나오는게 좋은 거 같아요! +캔뱃지 더 다양하게 입고되었으면..갈수록 줄어드네요ㅠ', 26, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '유포테이블카페&마치아소비'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '예약제가 사라지고 자율 입장이라 자리 없으면 어쩌나 싶은 마음에 11시 05분 도착! 11시 30분 1등으로 입장했어요😆😆 정말 와보고 싶었던 유포테이블 카페✨ 들어서는 순간 가슴이 두근두근 뜁니다!! 😍 유포테이블 카페에서만 볼 수 있는 굿즈들 구경하는 재미도 있고요☺️ 음료 마시고 받은 코스터도 너무 맘에 들어요☺️ 따님이랑 행복한 시간 보내고 왔습니다🥰', 67, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '유포테이블카페&마치아소비'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '아이가 귀멸의칼날 팬이라서 갔어요. 음료와 파르페는 팬심으로 먹었는데 맛은... 근데 그거 먹고 받은 런천매트가 너무 예쁨요. 확실히 굿즈 퀄리티가 좋아요.', 7, 0, NULL, SYSTIMESTAMP);
