INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '유포테이블카페&마치아소비'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '저번엔 대기 없었는데 이번엔 대기손님도 있고 매장 엄청 복잡했어요! 3주? 마다 굿즈들이나 분위기 바뀌는것도 인기의 한 몫인거같아용ㅋㅋ 랜덤코스터는 좀 일찍가야 원하는 캐릭터 얻을 수 있으니 빨리가세요!', 74, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '유포테이블카페&마치아소비'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '콥샐러드와 사네미음료, 미츠리의 벌꿀팬케이크까지 맛있게 막었어요:) 옆에서 굿즈와 등신대 보면서 호록호록 먹기 딱👍 아쉬운건 랜뽑에 몽땅 실패한것뿐.....', 95, 26, NULL, SYSTIMESTAMP);
