INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '유포테이블카페&마치아소비'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '저는 귀멸의칼날 팬이라 종종 방문합니다! 늘~ 그랬듯 자율입장이 너무 좋구요 이번엔 우즈이의 훈련주먹밥 보단 바다의집야끼소바가 맛있었습니다!', 43, 0, NULL, SYSTIMESTAMP);
