INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '유포테이블카페&마치아소비'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '오픈 시간에 맞춰서 갔는데 재료 준비가 덜 된 상태라 음식을 좀 오래 기다렸습니다 일하시는 분들은 친절하셨고 귀멸의 칼날로 가득 차 있어서 귀칼 좋아하시는 분들은 한번쯤 방문해도 괜찮으실 듯 합니다', 6, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '유포테이블카페&마치아소비'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '예약없이 방문할수 있어 너무 좋구요, 이번 음료는 맛있었어요! 이번 다이닝은 그냥 쏘쏘 했습니다~^^ 그래도 이번 콜라보는 개인적으로 너무 좋았습니다 렌고쿠 팬이라ㅎㅎ', 86, 18, NULL, SYSTIMESTAMP);
