INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '유포테이블카페&마치아소비'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '2023서울팝콘 가보면서 한국에 매장이 있다는 사실 알게되어 홍대쪽으로 가보았습니다 처음에 못 찾다가 뭔가 미술그림이 익숙한게 보여서 자세히 보니 유포테이블 매장을 찾을 수 있게 되었습니다 매장에 들어오면 귀멸의 칼날에 대한 다양한 굿즈와 자료가 있어 식사 매뉴 시키고 기다리는 동안 많은 구경을 할 수 있어 좋았습니다 직원분들도 친절하시고 매장이 크지 않지만 알짜배기로 있어 한국에만 있는 페이트 상품 일부 등이 있어서 시간 되시면 가보는 것을 추천합니다', 110, 25, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '유포테이블카페&마치아소비'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '역시 갓유포터블 카페를 가면 항상 지갑 열리게 할정도로 굿즈가 너무 예뻐요 >_< 디저트랑 음료가 좀 비싼편이지만요 랜덤 굿즈 구매했는데 좋아하는 캐릭터 렌코쿠가 나와서 행복하네요', 2, 6, NULL, SYSTIMESTAMP);
