INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '유포테이블카페&마치아소비'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '이번 다이닝 맛있어요-! 옆에 세워두는 이미지도 원하는 캐릭터로 고를 수 있어서 너무 좋았습니다ㅎㅎ 이제 예약없이 이용가능해서 편하게 갈 수있으니 좋네요ㅎㅎ', 13, 0, NULL, SYSTIMESTAMP);
