INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '유포테이블카페&마치아소비'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '일본 애니메이션을 좋아하는 딸램과 굿즈 & 피규어 투어를 했어요. 특히 귀멸의칼날을 좋아해서 유포테이블에 왔는데 너무 좋아해서 뿌듯했습니다.', 48, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '유포테이블카페&마치아소비'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '이제는 예약하지 않아도 되서 너무 좋아요, 작년? 부터인가 갈때면 여사장님으로 보이시는 분이 계시는데 친절하고 설명도 잘 해주셔서 좋습니다. 예전에 느꼈던 불친절한 느낌은 이제 못느낍니다. 맛으로가는건 아니지만 이번 도공마을2 식사메뉴는 진짜 맛이가 없습니다 ㅜ ㅜ', 32, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '유포테이블카페&마치아소비'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '무이치로 피규어를 들고 갔는데 무이치로 매트로 주셨어요~! 제가 무이치로 팬인 거 알고 챙겨주신 것 같아요ㅎㅎ 친구는 미츠리 좋아한다고 둘이 얘기하고 있었는데 이야기를 들으셨는지 센스있게 미츠리로 챙겨주셨답니다ㅎㅎ 직원분도 친절하시고 센스 넘치셨어요~! 무이치로 짱💜ㅋㅋ', 32, 7, NULL, SYSTIMESTAMP);
