INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '유포테이블카페&마치아소비'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '귀멸의칼날 팬이라면 정말 너무 덕질하기 좋은(?)^^곳입니다 음식이 맛없다는 평을 많이 봤는데, 개인적으로 이번에 3번째 방문인데 저는 갈때마다 괜찮았습니다 조만간 또 갈겁니다ㅎ', 19, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '유포테이블카페&마치아소비'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '귀멸의 칼날 덕질하시는 분들이라면 앉아서 음료 마시면서 구경하시는 것만으로도 충분히 즐거울 것 같습니다 일하시는 분들도 친절하시고 굿즈 구경도 재밌어요', 56, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '유포테이블카페&마치아소비'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '일단 음식 사진만 올리겠음 ..... 굿즈 넘  반갑고 좋고 막 사고싶고 그런데 이가격에 저 음식들을 또 먹지는 않을듯 ~~~~ 그냥 음식가격은 굿즈 가격이다 뭐 이런 마음으로 가야 될 듯 .', 95, 22, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '유포테이블카페&마치아소비'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '추첨해서 당첨!! >_< 제 최애는 렌고쿠 인데 자리가 렌고쿠 자리에 앉아서 렌고쿠 오므라이스랑 렌고쿠 우롱차도 마시고 앞에 렌고쿠 덕에 외롭지 않게 잘 먹고 가네요 ㅎㅎ 렌고쿠 관련된 굿즈도 구매하고 너무 천국이예요 다음에도 올께요 ㅎㅎ', 42, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '유포테이블카페&마치아소비'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '친절한 서비스 좋은 응대 감사합니다 지난번에 갔을때는 직원들이 굉장히 산만하고 불친절하여 심기가 불편하였는데 이번엔 정말 꼼꼼하고 하나하나 다 챙겨주셔서 즐거운 시간을 보냈습니다 다시 한 번 감사드립니다', 28, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '유포테이블카페&마치아소비'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '갈때마다 불쾌하고 기분이 안좋아지는 곳.이 맛에 몇만원 주고 서비스라도 좋으면 용서도 되는데..직원들도 맛도 애니가 명작만큼 비극적인 장소. 가지마세요.', 19, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '유포테이블카페&마치아소비'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '귀멸 메뉴는 같이 하는 이벤트인 월희에 비해 왜 이렇게 양도 적고 조촐한가요.... 음료는 늘 맛이 밍밍하고 물 탄것 같고,,, 아무리 그래도 귀멸 메뉴는 가격이 너무 비싸지 않나요 ㅠ 고명이라도 더 넣어주든가 맛이 좋아지면 좋겠습니다 제발요..... 돈 아까운 맛이에요 . 굿즈는 많이 들어와서 만족스럽습니다', 7, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '유포테이블카페&마치아소비'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '최애를 위해 방문했다 내 장르에 이런 카페가 있어서 넘 행복하다 근데 디저트 맛이 최악임. 별 반개도 아까움ㅋㅋㅋㅋㅋㅋㅋ 만이천원으로 런천매트를 돈주고 사세요...!!!!!!!! 밥은 먹을만했음ㅋㅋㅋ 밥이 질어서 아쉬웠지만 나머지 다 맛남.  굿즈는 많이 없음. 일찍가지않으면 다 팔리고 없다. 글을 쓰는 와중에도 디저트에 대한 분노가 치밀어오름', 75, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '유포테이블카페&마치아소비'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '야마카케우동은 마를 믹서로 거칠게 갈아서 특유의 식감이라곤 느껴지지 않고 얼마나 미리 준비해둿나 갈변도 심하다ㅠㅠ 강판에 가는게 그렇게나 힘든일인가..', 84, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '유포테이블카페&마치아소비'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '가격대비 점점 질이 낮아지있음 진짜 귀칼생각해서 가는듯 굿즈입고도 너무 늦고 메리트가 점점 없어짐 귀칼 이치방 쿠지라도 1인1회 할수있도록 쿠지 들여왔으면 좋겠음', 101, 23, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '유포테이블카페&마치아소비'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '저번주 방문 엄청 불친절한 직원분 계셨음 표정이 엄청 개빡친다는걸 보여주는거같았고 말은친절한거같으면서 안같은느낌 최소한 일한다면 일터에서는 고쳐야되는거지 조금은 보는 내내 불편하고 짜증났음  이번 시즌 메뉴는 괜찮았고 굿즈재고파악부탁드림 없고늦고 굿즈도 종류가 심하게 없음 이젠 귀칼의리로가는거같음 그래도 시즌메뉴괜춘함', 5, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '유포테이블카페&마치아소비'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '무난무난하고 이번여람방학크림소다가 맛있네요 그리고 매번 다른 직원분들인지모르겠는데 표정썩어서 대하시는 분봤구요  이번엔 뭔가 한꺼번에 다꺼내오는식뭔가 정리가 안된다는 기분을 받았습니다. 그리고 굿즈좀 넓혀주거나 디저트메뉴가 몇개더있고 굿즈가격도좀내렸으면 좋겠네요….일본내가격도 비슷한지 모르겠지만 아무리 그렇다해도 좀 저건 아닌데 하는 부분이 없지않아 있네요….', 28, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '유포테이블카페&마치아소비'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '귀칼덕후라서 너무 기대하고 갔는데, 굿즈가 많은 편이 아니었어요😞 부족한 굿즈들 재고파악해주셨으면 좋겠는데 그런게 없었고ㅠ 그리고 직원분들이 뭐랄까… 되게 힘이 없다고 해야할까요? 의욕도 없으시고ㅠㅠ 그래서 카페 이용 방법을 말씀해주시는데 뭔가 힘빠지는 느낌…ㅎ 그리고 카운터에서 계산하실 때 제가 이치방쿠리 여쭤봤는데 이름이 기억이 안나서 뽑기라고 했더니 다짜고짜 어떤거인지 알려줘야 안내해드린다고 약간 짜증섞이고 귀찮아 하시는 말투로 말씀하시더라구요… 저도 서비스직에 종사하는 사람이라 그런지 몰라도 조금 말투적인 부분이 날카로워서 덕질하러 갔는데도 기분이 좋지는 않았던 것 같습니다! 그래도 당첨 되면 또 갈꺼에용😆 그리고 음식은 맛있어요!! 맛없다는 후기들이 많아서요~', 25, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '유포테이블카페&마치아소비'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '좋지만,이용 룰이 꽤나 엄격합니다. 일본에서 콜라보 카페 좀 다녀봤지만, 뭔가 다른느낌이네요..코로나때문일지도 모르겠습니다만, 좀 불친절하고 불편해서 막 행복하진 않았습니다. 좋아하면 지는거죠 뭐…', 3, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '유포테이블카페&마치아소비'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '유포테이블 없으면 어떻게 살았을지... 페이트 카페로 현재 다닌지 약 3년이 다되어가는데 아직 그대로 건재해줘서 고마운 카페입니다 귀멸 당시에는 너무 복잡하고 ㅠㅠ 힘들어서 한동안 가지 못했지만 헤븐즈필 이후에 다시 가고 있어요! 이번에는 늦었지만 신부님 생일 다녀왔네요. 디저트는 어디든 콜라보 카페의 딱 그정도지만 식사류는 매번 괜찮았습니다! 에미야밥 복각 언젠가 한번 더 해주면 좋겠다는 간절한 바람이 있습니다', 77, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '유포테이블카페&마치아소비'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '음식맛은 기대할 수 없고 애니메이션 관련 상품 구매하는 것이 가능한 곳인데요. 카페 운영방식을 추첨제로 바꾸시면서 이용하실 분들이 당첨이 안되어 겪을 어려움을 아시면서 그렇게 하셨다는 것과 경험이 좋지않아 위 별점을 드립니다. 소통이 전혀 없으셔서 추첨하시는 것에 신뢰도 안듭니다. 물품을 사고 싶은 분들의 마음을 아시고 몇년간 운영하셨다면서 이렇게 하실 수가 있나요. 몇시간 추위와 힘든 마음으로 떨면서 기다리던 분들을 돌려보내면서 차후에 이용하라고 하셨는데 이용방식을 원복해주셔야 가능하겠네요. 운영하시는 분의 편의만 생각하시는 것 같구요. 여기는 한국이라는 것을 고려하셨으면 합니다.', 89, 16, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '유포테이블카페&마치아소비'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '벌써 방문 2번째내요^^ 제가 젠이츠하고 생일이 똑같아서 "젠이츠 생일전은 꼭 가야겠다" 라고 생각해서 딱갔는대 처음에는 사람이 많이 있을줄 알았는대 처음에는 저 혼자라서 조금 당황스러웠어요^^💦 그래도 음식은 맛있었던것 같아요 조금 비싸기는 했지만 맛있으니깐 괜찮아요~🌼 다먹고 굿즈도 몇게샀는대 굿즈 사진도 너무 예뻐서 마음에 들었어요 주교동에서 홍대까지 힘들게 간 보람이 있내요^^', 59, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '솔티드 스카치 라떼 7,000원 통카빈체리 에끌레어 5,800원 블루베리 에끌레어 5,800원 바닐라 피칸 바 에끌레어 5,800원 매장이 넓은데도 주말에는 사람이 많아요!🫢 자리 생겨서 겨우 앉았답니당! 에끌레어 맛집이라 애정하는 카페예요! 비가 오는날이라 그런지 에끌레어가 덜 바삭해서 아쉬웠지만, 그래도 맛나용!👍 매장 깔끔하고 데이트하기 좋아요~!🥰', 22, 0, 'GOOD', SYSTIMESTAMP);
