INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '바스크치즈 케이크가 먹고 싶어서 찾은 카페 딸기케이크도 같이 시켰는데 딸기케이크 크림이 그냥 생우유가 아니라 분명 흰색인데 생딸기맛 크림이라는게 진짜 미친맛도리 포인트임.. 감격스러워요', 32, 3, 'GOOD', SYSTIMESTAMP);
