INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '합정역 근처에서 카페를 찾다가 후기가 좋아서 방문하였습니다 인테리어가 멋지고 인기가 많은 카페에요 따뜻한 차를 마셨는데 만족스러운 맛이었습니다 외부에서 커피 한잔 할 수 있는 좌석도 있어서 날씨가 선선해질때 다시 방문하면 좋을 것 같아요', 26, 6, 'GOOD', SYSTIMESTAMP);
