INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '언니들이랑 빠른 저녁 먹고 지나가다 우연히 들렸어요 일반 가정집을 최소한으로 인테리어 변경하여 카페로 개조한 카페네요 옛날에 꽤 살던 양옥집 같아요^^ 잠깐 짬내서 들렸는데 커피맛도 좋고 이쁜 미니케익도 있네요 다음에 여유있게 시간내서 와보고 싶네요', 54, 15, 'GOOD', SYSTIMESTAMP);
