INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '에클레어 먹고 맛있어서 바로 치즈케익 사왔는데 치즈케익도 너무 맛있었어요ㅜ 레몬케익(?)도 맛보고 싶은데 품절이라 못 먹어서 다시 가보려합니다!', 33, 2, 'GOOD', SYSTIMESTAMP);
