INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '에클레어 1개 5,800원 솔티드스카치라떼 7,000원 예전 에클레어 맛있게 먹은 기억이 있어서 재방문했어요! 블루베리를 못먹어서 아쉽지만, 여기 에클레어 최고예용! 시그니처 커피인 솔티드스카치라떼도 맛나요! 친절하고 매장도 예뻐서 날 좋아지면 야외에서 즐기러 또 올래용!🥰', 108, 24, 'GOOD', SYSTIMESTAMP);
