INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '바닐라피칸/티라미수/딸기/블루베리 에클레어 5,800원 솔티드스카치라떼 7,000원 에클레어 비주얼 보고 반해서 방문한 카페! 일단 매장이 너무 예쁘고 넓어요! 에클레어가 너무 맛있어서 행복해서 웃음이 절로 나와요! 티라미수는 그냥 맛있었고 피칸은 위에 피칸이 너무 특별해요! 딸기, 블루베리도 정말 맛있어요! 완전 1등! 안에 잼도 들어있어서 좋아용! 커피마저 왜이렇게 맛있는지.....🤤 너무 맛있어서 에클레어 포장도 했네용 합정 방문하면 또또또또 갈거예요!!!🥰👍', 80, 15, 'GOOD', SYSTIMESTAMP);
