INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '근처 갔다가 들러 본 머씨! 아 이집 에끌레어는 정말 최고댜 (다른집 에끌레어는 안먹어봐서 모르겠디만..ㅎㅎ) 정말 최고당 >.< 매운 식사 후 절로 생각나는 에끌레어 바스크치즈케익도 맛 죠음😋', 79, 15, 'GOOD', SYSTIMESTAMP);
