INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '가격이나 음료, 푸드 질은 대체로 커피빈이랑 비슷한 수준 이에요. 좌석은 오래 앉아있기엔 약간 불편한데 주택을 개조한 카페라 감성 있어서 그런지 인기 좋네요.', 46, 1, NULL, SYSTIMESTAMP);
