INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '카페 찾다가 우연히 발견한 분좋카!! 주택개조형이라 외관 보자마자 가보고 싶더라고용 사진도 잘 나오고 날씨 좋을 때 야외에 있으면 더더 좋아용', 84, 15, 'GOOD', SYSTIMESTAMP);
