INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '인테리어 넘 예뻐요!! 조금더 따듯했으면 야외도 너무 좋을것 같아요💛 커피도 맛있고!! 에끌레어 기대이상!! 굿굿❤️ 도란도란 얘기넘 잘하고가용 ㅎㅎ 2층자리도 너무 좋네용!!👍', 58, 14, 'GOOD', SYSTIMESTAMP);
