INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '단독주택을 리모델링해서 빈티지와 모던함을 갖춘 감성 넘치는 카페 분위기. 3개층 각각 분위기도 살짝 달라서 좋고, 구석구석 포토존도 있습니다. 커피 향도 좋고 진해서 맛있어요  바닐라 라떼도 당달함이 딱 좋은 스타일. 그리고 스트로베리소다가 숨은 맛도리 음료. 제일먼저 바닥을 드러냈어요. 초코라떼는 가루가 너무 안녹고 덩어리져서 좀 아쉬웠습니다. 멋진 분위기에 비해 아쉬운점은 손님들이 많아서 그렇겠지만 소음이 좀 신경쓰이더라고요.', 19, 9, NULL, SYSTIMESTAMP);
