INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '여기 일단 인테리어가 너무 멋져서 사람들이 많이 들어오더라고요~! 저도 저 멀리서 보고 멋지다하면서 뭔가에 이끌림듯 들어갔어요 (ㅋㅋ) 일단 디저트는 에끌레어가 메인인 것 같은데 상당히 퀄리티가 좋았어요 ☺️ 그리고 추천하는 커피를 마셨는데 이것도 원두를 특별한 걸 쓰시는지 향이 평소 먹는 커피보다 훨씬 향긋하고 좋더라고요 🩵 주말은 2시간 이용시간이 있는것만 참고하시고 방문하세요~!', 19, 8, 'GOOD', SYSTIMESTAMP);
