INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '음료 디저트 모두 먹을만하고 실내 인테리어, 그리고 뷰가 예뻐요. 앞 가로수가 벚꽃나무인데 매장에 있는 큰 창으로 벚꽃 나무 뷰를 볼 수 있어서 좋았어요! ☺️', 10, 0, 'GOOD', SYSTIMESTAMP);
