INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '여기 치즈케이크 맛집입니다!?!👍👍👍 진짜 부드럽고 촉촉한 바스크 치즈 케이크에요😁 커피도 깔끔하고 고소해서 좋아요☕️ 에클레어는 무난히 맛있었어요. 넓어보이는 외관에 비해 실내에는 자리가 별로 없습니다…하지만 야외 좌석이 많고 조경도 예뻐서 날 풀리면 밖에 앉는게 좋을것 같아요.', 15, 3, NULL, SYSTIMESTAMP);
