INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '합정에서 보기 드문 대형 카페. 주차장 뷰긴 하지만 테라스 자리가 있어 요즘같은 계절에 선선한 바람 맞으며 차 한 잔 하기 좋아요.', 11, 10, 'GOOD', SYSTIMESTAMP);
