INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '좋은점 : 합정 카페들 일찍 닫는 것이 많은데 여긴 밤까지 운영해요 합정 밥집과 술집 많은 길목에 있어서 접근성 좋아요 아쉬운점 : 커피에서 탄맛이 나서 아쉬웠어요 종이빨대에요 쟁반색과 빨대 색이 같아서 못보고  스트로 챙겨가려고 어디있는지 여쭤봤는데 남자직원분이 "눈 앞에 있어요"라고 하시더라구요 친절하진않아요 테이블 간 간격이 가까워서 옆테이블 사람들 이야기가 너무 잘 들려요 밖에서 볼땐 단독 주택을 개조한듯한 카페인데 내부는 노출콘크리트입니다 여자화장실 칸이 두개인데 하나는 고장나서 못쓰고 세면대 뒤쪽 인테리어 마감이 덜 되어있는건지 물이 고여있어요', 9, 4, NULL, SYSTIMESTAMP);
