INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '합정역 앞에 있어 접근성이 좋아요. 안에 분위기도 좋아요. 2층까지 있는데 생각보다는 공간이 크진 않네요. 중형 사이즈이고 밖에 테라스도 있습니다.', 44, 1, 'GOOD', SYSTIMESTAMP);
