INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '합정 오면 머씨커피는 꼭 들르게 되는데 에클레어 맛집입니다🫶 공간이 넓진 않지만, 아늑하고 따뜻한 카페 2층에서 아메리카노 한잔에 에클레어 한 입!! 이게 행복이져👌', 292, 60, 'GOOD', SYSTIMESTAMP);
