INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '커피와 케이크가 맛있어요. 원두 종류도 세가지나 있어 좋아하는 스타일로 마실 수 있는 점이 마음에 들었어요. 무화과 케이크도 달지 않고 깔끔하니 맛있어요. 자리는 불편했지만 대화하기는 좋았어요.', 1, 5, 'GOOD', SYSTIMESTAMP);
