INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '합정역 근처 커다란 주택을 개조해서 만든 정원이 딸린 카페 더워서 정원쪽 자리는 이용이 어려웠지만 봄 가을엔 갬성 넘치는 분위기를 줄 것같다. 2층에도 테라스가 딸려있어서 기분좋게 이야기나누며 차를 한잔 할 수 있다. 주택을 세련되게 개조해서 곳곳에 거울을 두어 더 넓어보이고, 주변 건물들에 영향을 덜 받게 인테리어요소로 잘 사용했다. 근처 미팅있을때 마다 들릴예정!', 86, 18, 'GOOD', SYSTIMESTAMP);
