INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '디저트도 다 맛있는데 커피가 너무맛있어요 머씨블랜딩 추천드리고 다음엔 다른것도 먹어볼겁니다 리뷰이벤도 없는데 남겨요! 감성카페 ? 공장형 대형카페처럼 예쁘게 생겨서 얕잡아봤다가 느낌있는 공간에서 예쁘고 맛있는 디저트와 커피로 힐링하고가요', 43, 3, 'GOOD', SYSTIMESTAMP);
