INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '🫢너무 맛있어서 놀라버린 에끌레어! 밤이라 디카페인 아메리카노 마셨는데, 다른 카페의 디카페인처럼 신맛이 강하지 않아 부드럽고 맛있었어요~ 디저트 먹으러 또 갈래용 >.<', 99, 19, 'GOOD', SYSTIMESTAMP);
