INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '주택을 개조한 넓은 카페 ‼️ 커피도 디카페인, 원두종류 두가지가 있어 선택지가 넓어 좋았어요👍🏻 여기저기 예쁘게 꾸며놓으셔서 좌석도 다양하고 포토존도 많아요☺️ 대화하기에 좋아서 친목 / 데이트 무슨 목적이든 다 좋을 거 같아요! 멋진 테라스와 야외공간도 멋집니다. 모든 좌석이 색다르게 예뻐요❤️', 78, 12, 'GOOD', SYSTIMESTAMP);
