INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '합정동 주택개조한카페. 우연히 방문했는데 분위기 인테리어 멎찜요 입구야외공간도 너무 이쁘고 커피도 너무 맛있어여 2층에서 봐라보는 뷰도 대박스. 햇살좋아 사진도 엄청 잘나옴여 합정동 오면 커피마시러 자주 방문할듯요', 114, 21, 'GOOD', SYSTIMESTAMP);
