INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '합정!!! 메르시 디저트 맛집! 레몬타르트 너무 맛있잖아오! 🍋🍋 완전 내스타일!! 일반 가정 집을 카페로 만들어놓으니 더 분위기있어요! 커피도 맛있고, 디저트가 최고최고♥️', 18, 2, 'GOOD', SYSTIMESTAMP);
