INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '주택 개조 카페라서 공간이 넓고 인테리어가 예뻐용!!평일 낮에 왔는데 주변카페중에 여기만 사람이 많이 있네용!레몬파이랑 에끌레어 맛있어요', 4, 1, 'GOOD', SYSTIMESTAMP);
