INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '다시는 가고싶지 않네요.직원들의 서비스가 엉망진창이고 사장님이 직원들 인성교육부터 다시해야 될꺼 같아요.여자알바분이 주문을 받고 잘못나와서 말씀드렸고 얘기를 듣고도 옆으로 도망;안경쓰신남자분께 대신 떠 넘기는태도로 일관하였고 남자2 여자1 고객인 저희를 불투명하게 처다보며 직원의 태도가 잘못이 없다는 액션.영수증을 보여줬는데도 메뉴도 제대로 확인못함 저희가 다시 취소후 재주문 요청 (이것도 직원이 잘못했으면 다시 재문의 해야하는거 아닌가요?)재주문후 진동벨안줘서달라고함;2층에서1층까지개고생하기싫어서결제후에도 사과가 없길래 문의함.저희가 사과받아야 하는거 아니냐고 주문이 잘못나왔고 그걸 직원이 제대로 파악도 못하고 저희가 3번이나 2층에서 왔다갔다 했다고.결국 어쩌란태도로 대충 죄송합니다 한마디 받음;', 92, 20, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '평일 낮에 방문했는데 손님들도 좀 있었지만 조용했고 수다 떨기도 좋았어요ㅎㅎ 커피도, 레몬케이크도 너무 상큼하니 맛있었어요!ㅎㅎ👍', 34, 10, 'GOOD', SYSTIMESTAMP);
