INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '테라스 감나무주변 자리가 좋은곳. 더운날인데 신기하게 2층테라스 감나무엔 바람이 머무는자리 에클레어 디저트 맛있어보였으나 입이 달아서 음료만 주문했는데  여름추천음료 썬라이즈(?) 엄청 달아요ㅋ 가지고있는 생수 붓고 지인 아메 뺏어먹기ㅋㅋㅋ', 62, 17, 'GOOD', SYSTIMESTAMP);
