INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '인테리어 너무 예뻐서 계속 사진찍음. 크레이프 케잌 맛있었고 커피랑 차 종류도 깔끔하고 입에 붙게 맛있었음. 공간 환하고 예쁜데 음악도 딱이라 늘어지게 앉아있고 싶을 정도', 5, 9, 'GOOD', SYSTIMESTAMP);
