INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '친구랑 돌아다니다가 그냥 들어간곳이에요 주택을 개조했는데 자리를 최대한 많이 만드려고 노력하신 것 같아요! 음료도 맛있고 신나게 웃긴 이야기들 하다가 갑니다 날도 너무 좋아서 야외자리도 요즘 딱이에요~!~!~! 음~~~~ 마싯다~~~~~', 26, 10, 'GOOD', SYSTIMESTAMP);
