INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '술집이 많은 거리여서 정신 없었는데 카페에 들어선 순간부터 차분한 분위기가 마음에 들었어요~ 조용하게 대화하기 좋은 카페입니다', 36, 7, 'GOOD', SYSTIMESTAMP);
