INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '레몬파이 왜이렇게 맛있나요!!! 촉촉한 크림과 중간에 레몬필링이 너무 잘어울러지고 파이와 크림사이에 초코도 발라져있는데 이게 또 맛의 풍미를 올려주는 장치인듯👍 커피원두도 2종류가 있어서 원하는 맛으로 고를 수 있답니다 커피 왜이렇게 맛있는거죠?! 디저트만 보고 간 집이었는데 커피맛집이었구먼요! 날씨좋을 때 오면 야외에 앉아서 먹고싶더라구요 분위기도 너무 좋았어요💕', 46, 10, 'GOOD', SYSTIMESTAMP);
