INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '주택을 개조한 듯한 인테리어! 날씨가 좋으면 밖에서 먹기 너무 좋을 것 같아요! 커피도 전반적으로 괜찮습니다. 실내도 2층으로 되어있어 꽤 넓어요 다만 몇몇 좌석의 의자와 테이블이 생각보다 불편합니다.', 14, 4, 'GOOD', SYSTIMESTAMP);
