INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '카페에 사람이 많은데 그만큼 매장이 커서 좋았습니다 1, 2 층이랑 지하 같은 별관도 있어요 디저트 종류가 많진 않지만 맛있고 커피 원두 설명도 있어서 좋았어요 외부 인테리어가 예뻐서 마구마구 사진 찍게 됩니다 날씨 좋고 밝을 때 오면 더 예쁠 것 같아요', 9, 2, 'GOOD', SYSTIMESTAMP);
