INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '그렇다. 날 좋은 봄날이라 그런지 모든 사람이 머씨커피로 왔다.(ㅎㅎ) 귓청이 떨어져 나가는 줄 알았고, 바로 앞에 있는 사람이랑 대화하는데 목소리가 쉬었다.🥲 맛있는 케이크와 커피 덕에 좋은 시간 보냈지만 밥값보다 더 비싼 음료값은 조금 버거운 감이 있었다. 하허..', 5, 4, NULL, SYSTIMESTAMP);
