INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '2층 전원주택을 개조한 카페인데,  너무 귀여웠어요~ 테라스자리들도 갬성한가득이고, 내부에도  좌석 꽤 많아요.  바스크치즈케잌 진하고 너무 맛있었구요, 바닐라빈라떼도 달지 않고 짱맛!! 베리썬라이즈는 새콤달콤 건강한맛^^  일단 분위기도 좋지만 음료,디저트가 다 맛있어서 추천!!근처에 은근히 밥먹을 곳도 많더라구요,  주차장은 따로 없지만 카페 바로 앞에 유료주차장이 있어서 괜찮았어요~', 11, 3, 'GOOD', SYSTIMESTAMP);
