INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '인테리어가 무척 멋있어요! 공간도 널찍한데 테이블이 불편하고 다닥다닥 붙어 있어요... 아 그리고 2시간 타임리밋이 있습니다 ㅠㅠ 그래도 막 엄청 단속하진 않는 거 같았어요. 평일 저녁에 사람이 많지 않아서 대화 나누기 좋아요~ 1층은 자리가 불편하지만 2층은 편해요', 17, 5, NULL, SYSTIMESTAMP);
