INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '예전에 지나가다 본곳인데 이번에 방문~~1 2층 야외 지하 다양하게 자리배치 되있는데도 사람이 엄청나네요ㅎ 생각보다 커피가 맛났고 디저트도 괜츈~~ㅎ', 129, 26, 'GOOD', SYSTIMESTAMP);
