INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '첫 방문인지라 잘 몰라서 원두선택을 못 하고 있었는데.. 한숨 쉬시며 눈치주시는 그 느낌에 마음이 좀 속상하였어요. 오랜만에 만나는 친구와 추천받아서 방문하게 된 거였거든요 :-)…. 다음에는 더 좋은 모습으로 가게 이용해보고 싶습니다', 32, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '커피가 맛있고 합정역이랑 가깝습니다 주택개조한 카페인데 예뿌고 맛있어 자주갑니다 특히 이 집은 빵이 코딱지만한테 퀄리티가 뛰어나요 엄청 맛있으니 꼭 디저트를 드셔보시길 권합니다 솔티드 뭔 라떼도 맛있음', 19, 1, 'GOOD', SYSTIMESTAMP);
