INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '합정역이랑 가까워서 와본 머씨커피입니다. 여기는 테라스가 예뻐서 날씨 좋을 때 오면 정말 좋을 것 같아요 ㅎㅎ 원두도 맛있고, 디카페인 원두도 있어서 좋습니다. 프랜차이즈 아닌데도 디카페인 있어서 굿 ㅎㅎ 디저트류도 있는데 맛있어요! 바스크치케 추천.', 16, 10, 'GOOD', SYSTIMESTAMP);
