INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '맛있어요!!!! 레몬파이가 진짜 치트키입니다 🍋딴건 모르겠구 여기 오시면 레몬파이!!꼬옥 드셔보세요 인테리어는 흔한 인스타 갬성 카페 스타일이긴 한데, 2층까지 있아사 넓고 날만 안 추우면 마당에서 드셔도 좋을 것 같네영', 34, 10, 'GOOD', SYSTIMESTAMP);
