INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '카페가 너무 예쁜거 아니냐구요오오 합정에 이런 곳이 있을 줄이여ㅜㅜ 너무 좋았습니다!! 배불러서 디저트눈 못먹고 커피랑 음료맘 마셨눈데 다음엔 케이크도 먹으러ㅠ올게뇨', 25, 8, 'GOOD', SYSTIMESTAMP);
