INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '매장 넓고 깨끗해서 좋아요 에클레어는 생각보다 진짜 작아여ㅠㅠ 블루베리보다 티라미수가 훨씬 맛있었고 바스크치즈케이크는 크림처럼 녹아내릴 정도로 촉촉한데 진짜 맛있었어요!!! 커피도 원두 고를 수 있는데 디카페인 커피가 더 찐하고 다크한 맛이었던거같아요. 재방문의사⭕️⭕️⭕️', 51, 14, 'GOOD', SYSTIMESTAMP);
