INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '지하까지 있어서 너무 놀랐어요 엄청 넓네요 어디 앉을지 구경하는 재미도 있어요 ㅎ 근데 자리마다 에어컨이 안 닿는 곳이 많아서 그건 좀 아쉽네요 음료는 맛있었어요', 36, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '바스크 치즈케이크 맛있어요!! 존맛 그리고 솔티드스카치라떼 대존맛이에요!! 크림이 진짜 맛있어서 크림만 퍼먹고 싶은 맛이었어요.', 9, 9, 'GOOD', SYSTIMESTAMP);
