INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '세명이서 디카케인컾두잔,핫쵸코한잔,치즈케잌을 주문했는데...두시간만 이용가능하십니다.라고해서 기분이 안좋았어요. 손님도 없었는데....나이가 든사람이라 그랬을까요??', 36, 6, 'BAD', SYSTIMESTAMP);
