INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '커피 맛있고 인테리어 좋고 넓고 시원하고 친절하세요 실수로 바닥에 커피 다 흘렸는데 너무나 친절하게 닦으시곤 새 커피로 가져다 주셨네요ㅜㅜ 스윗 그 자체~ 감사합니다 🩵', 81, 17, 'GOOD', SYSTIMESTAMP);
