INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '일단 매장이 넓고 뷰가 좋아요. 아인슈페너만 먹다가 이번이 에끌레어 주문해봤는데 우와… ㅠㅠㅠ 단연 먹어본 에끌레어중에 최고였어요 좀 작고 비싼감이 있지만 전혀 아깝지 않은 소비였어요. 기분 안좋을때 입에 하나물어가면 좋을듯 꼭드세요ㅠㅠㅠ', 36, 6, 'GOOD', SYSTIMESTAMP);
