INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '20분 남았는데 마감하신다고 해서 모든 손님 휘릿 도망치듯 나가야하는.. 당황.. 커피맛 쏘쏘 앞에 공영주차장 있어서 주차는 편합니다(주차자리가 있을 시) 낮에 가야 좋은 곳(?)인 것 같아요 :)', 35, 5, NULL, SYSTIMESTAMP);
