INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '민''s 리뷰 👋 별점 : 4.3 / 5 장점 : 주택을 개조해서 만드신거 같아서 예쁨🌻 원두를 골라서 아메리카노를 즐길수있는 장점⭐️ 에끌레어 조금 작아보여 걱정했는데 속이 꽉꽉🌕 세련과 힙 그사이 어딘가 .. 💫 탁트인 바깥 테라스 보유중 👍 단점 : 가격이 쪼금쪼금 비싼…? 편인가..? 🙄 종이빨대💧', 45, 9, 'GOOD', SYSTIMESTAMP);
