INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '📍메뉴: 아이스아메리카노 원데이클래스 가는 길에 테이크아웃 했는데 매장에서 이용할걸 그랬어요! 내부가 예뻐서 잠깐 앉아서 사진찍고, 구경하다가 왔어용 ☕️☕️ 커피도 맛있었습니다 :)', 2, 10, 'GOOD', SYSTIMESTAMP);
