INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '합정역이랑 가까워서 접근성도 좋고, 친절하시고, 레몬 파이가 정말 맛있었습니다. 사실 조명이 살짝 어둡지는 않은가 생각했는데 소규모로 만났을 때 오히려 어두운 조명이 분위기를 연출 할 수 있는것도 같아서 만족한 카페였습니다~', 55, 18, 'GOOD', SYSTIMESTAMP);
