INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '2층 테라스석에서 마시다가 추워서 안쪽자리 생겼을때 바로 옮김ㅋㅋ 근데 여긴 자리도 다양하고 좌석도 많은편 디저트나 커피가 비싸지만 요즘 물가 생각하면 그러려니하게됩니다 수다떨기 좋고 사람이 많아도 생각보다 시끄럽지 않아요', 27, 3, 'GOOD', SYSTIMESTAMP);
