INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '테라스의 계절에 오기 딱 좋은 카페예요🫶 선선하고 탁 트여서 좋아요ㅠㅠ 아아 맛있구 솔티드스카치라떼는 소금 알갱이가 큰 편이라 너무 짜요ㅋㅋ + 화장실 관리 안 됨', 36, 0, 'GOOD', SYSTIMESTAMP);
