INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '이 곳 레몬케이크 좋아해서 포장해봤습니다. 케이크야 내점해서 여러번 먹어 말해 뭐해 입니다만 포장은 손잡이 없는 상자이니 꼭 담아갈 봉투 추가구매 요청하시거나 가져가세요. 그리고 담아갈 봉투 추가 구매는 사진속 얇은 비닐로 1장에 300원 추가입니다.', 63, 18, NULL, SYSTIMESTAMP);
