INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '합정역 근처에 위치해서 좋아요. 심지어 대형카페라 자리도 많고요. 저는 스카치라떼를 도전해봤는데,,,,오우.,너무 달았어요ㅠㅠ 진짜 스카치캔디를 녹인것같아요...아.아파인 저에게는 너무 달았습니다! 다른건 맛있었어요.', 18, 0, 'GOOD', SYSTIMESTAMP);
