INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '사람이 많은 이유가 있는 것 같아요! 지하벙커 같은 곳 앉았는데 외풍이 들어와서 춥기는 했지만 ㅜㅜ 그래도 앉을자리가 있다는 것에 만족이요! 커피와 디저트 둘다 맛있었어요!', 1, 8, 'GOOD', SYSTIMESTAMP);
