INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '무엇보다 인테리어가 좋습니다 카페인듯 단독주택인듯한 감성이 좋고 내부에서도 야외에서도 어디서든 얘기를 나눌 수 있는 넓은 공간과 분위기가 좋으며 대화하기도 좋습니다~', 43, 7, 'GOOD', SYSTIMESTAMP);
