INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '☕️ 머씨 블랜드 / 멕시코 치아파스 디카페인 🧁카페 티라미슈 에끌레어 저녁에 들렀는데 날씨가 조금 쌀쌀했지만 따듯한 커피 마시면서 창가쪽에 앉아 이야기하기 좋았어요. 에끌레어 촉촉하니 부드럽고 너무 맛있게 먹었어요. 디저트 때문에라도 다시 생각날듯한…! ✨', 33, 7, 'GOOD', SYSTIMESTAMP);
