INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '단짠의 정석 솔티드 스카치 라떼~! 추억의 캬라멜 풍미가 아련하게 느껴집니다. 두 입에 순삭각 에클레어는  맛도 모양도 예쁘고, 주택을 개조한 인테리어도 아주 멋들어지네요.', 18, 9, 'GOOD', SYSTIMESTAMP);
