INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '전원주택을 개조한 카페라 고즈넉한 분위기입니다. 커피는 아메리카노도 마셔봤고, 에이드류도 마셔봤는데 시그니처인 스카치라떼는 저에게는 좀 많이 달았습니다ㅠㅠ 아이스로 다시 마셔보고 싶네요!', 2, 1, NULL, SYSTIMESTAMP);
