INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '합정가면 꼭가는 머씨커피 주택을 리모델링한 감성있는 인테리어도 좋고 디저트메뉴랑 커피도 괜찮아요 날씨가추워서 지금은 밖에 못나가지만 날씨좋으면 밖에앉으면 굿이에요', 60, 13, 'GOOD', SYSTIMESTAMP);
