INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '언젠가 가보겠다고 저장해뒀다가 근처 온김에 들렀어요. 구옥을 개조해서 동선이 편하진 않지만 조용히 대화하기 좋아요. 음료 맛도 괜찮고 날 좋은 계절에 또 들려보고 싶어요!', 32, 7, 'GOOD', SYSTIMESTAMP);
