INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '테이블마다 예쁜자리 가득 감나무가 바로앞에 있어 갬성가득이에요ㅎ 스카치라떼?  시그니처메뉴 달콤하니 맛있고요 디저트 기대안했는데 엄청 맛있게먹엇어요 라떼는 작은얼음이 빨리녹아서 금방연해져 아쉽, 찐한 라떼좋아하심  플랫화이트추천해여 아메리카노도 괜찮았어요!!!!', 73, 16, 'GOOD', SYSTIMESTAMP);
