INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '합정에 이렇게 예쁜 카페에 있는지 뮬랐어요ㅜㅜ 진짜 제가 좋아하는 분위기 가득한 카페예요 🤍 여긴 자주 올 것 같아요 !! 자리도 넓고, 디저트도 맛있어요 레몬파이를 처음 먹어봤는데 상큼하니 생크림이랑 잘어울려요 🍋🥧', 12, 2, 'GOOD', SYSTIMESTAMP);
