INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '음료는 깜빡 잊고 사진을 못 찍었지만 개인 카페 치고 가격이 무난했습니다! 치즈케이크도 맛이 있었고 정원이 잘 가꾸어져있어 날씨 좋은 날은 사진찍기 아주 좋을것 같았어요! 2층에도 좌석이 마련되어있지만 저희는 1층 자리에 앉았는데 채광도 아주 좋고 화분도 잘 가꾸어져 있어서 아주 쾌적했습니다! 식물 좋아하시고 채광 좋은 곳에서 사진 찍는것 좋아하시는 분들에게 추천드려요~~', 38, 0, 'GOOD', SYSTIMESTAMP);
