INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '에끌레어 악마의 디저트라 정말 순삭하고. 레몬케이크도 넘 맛있었어요! 근데 커피랑 밀크티는 가격에 비해 양이 터무니없이 적어요!! 물도없고, 2층에 테이블은 좁았어요. 그래도 분위기랑 디저트 먹으러 간거라ㅋㅋㅋ', 19, 6, NULL, SYSTIMESTAMP);
