INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '합정에 테라스 카페가 있다니! 맑은 날 햇살 가득 들어올 때 재방문하고 싶습니다. 아메리카노는 산도가 높고 쓴 편이라 다음엔 라떼로 마셔야겠어요', 49, 8, NULL, SYSTIMESTAMP);
