INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '바리스타님 추천 커피 오늘은 ‘코스타 티카’ 약간의 산미가 느껴지지만 적당한 농도의 커피가 부드럽게 목넘김을 좋게 합니다. 좋아요~', 12, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '친구들과 떠들기 좋았고요. 바리스타추천 원두로 아메리카노 주문했는데 너무 잘한 선택이었다!! 회사 출근하며 먹는, 프랜차이즈 커피맛이 아니어서 연차쓰는 맛을 느끼게 해주는 훌륭한 맛☕️', 84, 17, 'GOOD', SYSTIMESTAMP);
