INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '사진을 못 찍어요..죄송해요 그 저희는 2층에 올라가면 좌석 쭉 있고 안쪽으로 들어가보면 저희가 있던 작은 공간이 나오고 바로 옆은 테라스가 있어요 이 날은 사람도 많고 그래서 자리가 없어서 앉은 거랍니다ㅎㅎ 매장 보시면 예뻐서 사진도 잘 나올 것 같아요', 41, 5, NULL, SYSTIMESTAMP);
