INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '무화과, 티라미슈 에클레르 둘 다 맛있어요. 키위드래곤 소다 취저. 키위 씹혀서 넘 맛있어요. 사람 너무 많고, 자리 간격이 좁아서 시끄러워요. 그래도 맛있어서 재방문은 할 것 같아요.', 25, 10, NULL, SYSTIMESTAMP);
