INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '에끌레어도 너무 맛있고 뷰도 너무 좋았어요~ 직원분도 친절하셔서 더욱 좋았습니다 :) 주택개조카페라 예전 친구집이 떠올라서 정겨웠고 인테리어도 너무 취향이라 에끌레어도 또 먹을 겸 재방문할게요 !!', 34, 9, 'GOOD', SYSTIMESTAMP);
