INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '깔끔하고 좋아요! 2층도 있던데 가보진 못했어요 공간이 엄청 넓진 않지만 자리 넉넉하고 분위기도 좋았어요~ 저녁먹고 딱 카페갈 시간 맞아떨어지면 사람 붐벼요! 디저트 이름 기억 안나는데 저 블루베리 넘 맛있었어요ㅎ 추천!', 42, 6, 'GOOD', SYSTIMESTAMP);
