INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '개인 주택안에서 커피를 마시는 거 같은 느낌이 드는 카페! 실내는 물론 야외테라스에도 테이블이 많아서 분위기 느끼기엔 짱짱인것같은 카페예요ෆ 합정역 갬성 카페로 강추합니다 !! 커피의 원두 종류도 많고 디저트 종류도 은근 많아용~ 밤늦게 방문이라서 디저트 종류 별로 없을까봐 조마조마했는데ㅠㅠ 원하는 레몬파이랑 치즈케이크 둘 다 시켜서 맛있게 먹었네용 ㅎㅎ', 85, 13, 'GOOD', SYSTIMESTAMP);
