INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '합정역 분위기 좋은 카페😍 걷다가 들어왔는데 너무 좋았어요!!!밖 테라스 자리도 좋아보였지만 모기밥 될까 무서워서 실내에서 마셨습니다!!솔티드라떼는 단짠의 맛이 극강!', 43, 0, 'GOOD', SYSTIMESTAMP);
