INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '인테리어도 예쁘고 커피 디저트도 넘 맛있어요^^ 직원분도 친절하셔서 좋았습니다! 집 근방은 아니지만 가을에 다시 가봐야겠어요!! 또 가고 싶은 카페입니다^^', 22, 10, 'GOOD', SYSTIMESTAMP);
