INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '예쁜카페 머시 합정점~♡♡♡ 커피는 3가지원두중 선택할수있어요. 커피는 정말 맛있고(산미추천) 음료랑 케잌 다다 맛있어요 ^^', 22, 3, 'GOOD', SYSTIMESTAMP);
