INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '합정동 근처 카페 서칭 중에 분위기에 반해서 간 곳인데 진짜 5월에서 6초까지 오면 너무 좋을 카페...! 단독주택 개조해서 만든 카페같은데 조경을 굉장히 ㅇㅖ쁘게 해놔서 날씨만 덜 더우면 테라스에 앉아서 피크닉 느낌으로다가 즐길 수 있을듯! 카페는 원두를 고를 수 있었는데 확실히 산미는 내 취향은 아니었지만 그래두 괜찮았어요 햇살맛집카페로 추천', 35, 10, NULL, SYSTIMESTAMP);
