INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '실내가 꽤 넓은 카페예요! 2층 짜리고, 밖에 테라스나 1층 마당같은곳도 자리있어요. 날씨가 괜찮아서 테라스에서 마셨는데 좋았어요! 가격에 비해 음료수 양이 적어서 아쉬웠습니다🥲 밀크티는 거의 종이컵 사이즈...', 40, 2, 'BAD', SYSTIMESTAMP);
