INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '원래 루프트 커피였는데 오랜만에 가서 매장이 바뀌었더라구요 ! 커피도 맛있구 조용하고 감성있어서 좋더라구요 ㅎㅎ 다음엔 디저트도 먹으러 오려구요!', 23, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '뷰도 좋구 날씨도 좋구 친절하구 다 좋았는데 솔직히 밀크티는 별로였어요 싱거운 ㅜㅜ 레몬티는 괜찮았구요 밀크티 좀 찐해야할꺼 같은 ㅜㅜ', 12, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '좌석이 진짜 다양하고 인테리어도 화사해서 밝고 예뻤어요! 야외석은 봄이나 가을에 앉으면 너무너무 좋을 것 같아요 ㅎㅎㅎ 아메리카노는 원두를 선택할 수 있었는데 머씨 원두 넘 고소하고 맛있었어요! 저는 저녁이라 디카페인 마셨는데 디카페인도 고소해서 맛있었습니다 ㅎㅎ 화장실도 깨끗하구 좋았습니다. 다음에는 디저트 메뉴들도 먹어볼게요!', 15, 4, 'GOOD', SYSTIMESTAMP);
