INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '재방문 의사 ★★★☆☆ 한줄평: 인스타 갬성의 카페... 다들 아시죠? 맛 ★★★☆☆ 접근성(주차포함) ★☆☆☆☆ 분위기 ★★★★☆ 가격 ★★☆☆☆ 친절 ★★★★☆ 청결 ★★★★★ 갬성만 보고 갔는데 커피가 생각보다 맛있습니다! 다만 요런 매장은 앉을 수 있는 자리가 생각보다 많지 않아서 아쉬워요ㅎㅎ', 46, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '예쁘고 편안한곳이네요. 커피도 맘에 들었어요 근데 에끌레어 먹어보려고 했는데 너무작은데 비싸요 ㅠㅠ 암튼 기분좋게 쉬다 왔어요^^', 302, 81, NULL, SYSTIMESTAMP);
