INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '바스크치즈케익 모에요..? 왜케 부드럽고 맛나요.. 진심 인생케익;; 머씨 아메리카노도 넘 맛있었어요 인테리어 보고 찾아간건데 디저트랑 아아가 넘 맛있었어요 ㅠㅠ😊💛💛💛', 35, 8, 'GOOD', SYSTIMESTAMP);
