INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '커피도 너무 맛있었고 레몬파이랑 바스크치즈케이크는 .. 꼭 드셔보세요. 인테리어도 너무 잘 되어 있어서 보기 좋았어요! 넓어서 더 좋았습니다. 날 좋을 때 야외좌석 가보고 싶어요.', 22, 8, 'GOOD', SYSTIMESTAMP);
