INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '토요일 오후 3시쯤 방문하니 자리가 없어서 다른곳으로 가려다가 딱 한자리 났다길래 냉큼 자리잡고 티라미슈 먹고싶어서 시켰는데 똑 떨어져서 아쉬웠습니다 ㅠ 커피가 깊고 진해서 맛있어요 ! 아쉬운만큼 또 방문하겠습니다!!', 15, 4, NULL, SYSTIMESTAMP);
