INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '밀크티는 정말 별로… 얼음이 다 녹아 나와서 오잉 했어요. 디카페인라떼는 맛있었어여~ 치즈케익 완전 대박 핵핵 맛있음 밀크티 때문에 오잉 하다가 치케 먹고 마음 풀림 다시갈듯', 36, 0, NULL, SYSTIMESTAMP);
