INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '머씨커피'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '음료 주문하고 25분 동안 앞에서 기다렸는데 너무 안나와서 물어봤더니 주문이 누락되었다며 어떻게 해줄까요? 물어봄. 둘이서 디저트 2개 음료 2잔 시켰는데 서비스로 더 달라고 할 것도 아니고 오래 기다려서 미안하다는 말부터 하셔야 하는거 아닌가요...ㅠㅠㅠ', 82, 11, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '오늘은 게스트이신 루리,위즈님을 필두로 하쿠님, 주디님, 유메이님, 니니님, 쿠로님, 하루님께서 챙겨주셨습니다. 오늘도 역시 다들 밝은 분들이셨습니다!! 다만 역시 게스트 께서 있으신 날이다 보니 평소보다 많이 붐볐습니다. 그럼에도 메이드분들께서 열심히 돌아다니며 챙겨주셨습니다! 오늘은 오피스룩데이로 다들 정장룩으로 오셨습니다. 다들 이쁘셨슴다. 다음에 오시는 분들도 좋은 추억 만드시고 가시면 좋겠습니다. 그럼 이만...', 87, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '마지텐시 늘 잘 즐기고 있어요! 항상 재밌게 해주시죠 늘 감사하게 해주시는 곳이 되었네요:) 마텐에서는 라이브공연 및 다양한 음식들이 즐비해있어서 항상 새로운것들에 감사하며 즐기고 있어요 새로운 체험을 경험해보시고 싶으신 분들께서는 오셔도 좋을것 같아요!', 7, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '방문해보는 마지텐시 메이드카페 늘 즐겁고 활기찬 메이드분들께서 맞이해 주시니 감사드리고 잘 대해주시는게 좋아요! 이색체험 카페를 원하시는 분들께서 방문해보셔도 좋을것 같아요 음식도 맛있고 라이브도 즐거워요 그리고 체키라는 것도 있어서 많은 것들이 즐기는 시간이 될수 있다고 생각합니다!', 82, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '마지텐시는 항상 최고랍니다:) 친절하신 메이드 분들이 계셔주셔서 행복하고 그 시간들이 늘 아깝지 않은 순간들이 였어요! 유니메이드님이 가장좋았어요 너무 귀엽고 친절하시고 사랑스러웠어요 근데 개인적으로 챠마메이드님이 좋았어요! 😀', 4, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '아이스크림이 맛있습니다 메이드들이 친절하고 상냥하고 예쁘고 귀엽고 카리스마있고 아무튼 자기들끼리 다하는 최고의 메이드카페 현실에서 벗어나 행복한시간을 즐기기에 최고의 장소!!! 이 리뷰를 본 당신 지금바로 예약ㄱ', 0, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '마텐데 놀러갔는데 오랜만에 뵙는 스이님, 비비님, 사화님, 로제님, 주디님, 하루을 보고 신입이신 미사님을 뵙네용! 요즘 감기가 유행이니깐 마지텐시앤데비 사장님과 메이드분들은 조심해주세요.. 아프시면.. 안돼요😭 다음에는 모두다 건강한 모습으로 만나자요!^^ 오늘도 행복한 하루에요!', 120, 20, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '오랜만에 보시는 분들도 계시고 처음보시는분들도 계시는데 오랫만에 가는데도 재밌게 놀아주셔서 좋은거같아요! 못간다고 이야기했는데 1명은 못믿고 3명은 믿어서 깜짝 놀래는 모습이 너무 재밌던거같아요! 다음에 또 놀러와야징 ㅎ', 19, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '올만의 마텐데 귀가 올만에 뵙는데도 기억해주시고 즐겁게 대화를 나눠주시는 여러분들께 항상 감사함을 전합니다. 놀러 나왔다가 어디갈까 아님 집에 갈까 고민중이였는데 오출완을 확인하니 오랜만에 뵙는 분들이 다들 출근 하시길래 바로 달려왔습니다.담에또 만나요.', 19, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '코미가 오늘도 너무 예쁘구요 새로 염색했는데 너무 어울리구요 맘에들구요 한정체키도 너무 귀엽구요 세상에서 제일이구요 코미 최고 마텐 최고', 49, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '우주최강미소녀들이 가득합니다 브금선정이 훌륭하고 최고의 힐링공간 마지텐시최고 최고의 메이드카페 아 안에 있는데도 더시오고싶다 빨리 부자가되어 일안하고 공부안하고 행복하게 메이드카페오고싶습니다', 20, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '마지텐시는 언제가도 최고라고 생각합니다 항상 친절하신 메이드 분들의 이 대접 항상 최고라서 뭐라고 두말 할 필요가 없다라고 할수 있죠! 특히나 코미님 이라는 메이드분의 라이브와 귀여운 표정을 볼 수 있는 것 이것만으로도 굉장히 추천해볼만합니다! 마지텐시 영원하라:)', 7, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '마지텐시앤데비 메이드카페에는 텐시타임때는 미성년자도 출입이 가능하지만 데지타임에는 미성년자가 출입을 못해요. 왜냐면 데비타임에는 주류들을 팔아서 미성년자가 아닌 성인만 손님으로 받아주지만 텐시타임과 다르게 데비타임도 재미가있어요! 다음에도 시간이 될때.. 데비타임을 즐기러 가야겠어요! 손님이 주류나 음식을 가져와서 메뉴판에있는 콜키지로 선택후 자신이 가져온 음식과 주류를 드시면 됩니다! 텐시는 텐시타임에 매력이 있고 데비는 데비타임의 매력이 있어서 너무 재밌게 놀았던거같아요!', 14, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '마지 텐시 메이드 카페에서 메이드로 마지막 근무를 하시는 아키님의 명함입니다 비록 오래 보지는 못 하였지만 열심히 일하시는 모습과 응대하시는 모습이 인상 깊었습니다 다른 일을 하시더라도 앞으로의 앞날이 행복하셨으면 좋겠습니다', 72, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '님들 제가요 오늘 하루 메이드라는 분을 만나 뵈었거든요? 근데 더 쩌는 게 뭔지 아세요? 진짜 엄청 아름답다는 거예요! 와 이건 사람이 아니고 무슨 루브르 박물관에 전시해야할 엄청난 조각 미모인 거에요 진짜 속는셈 치고 한 번만 와보세요 진짜 겁나 예쁩니다.', 20, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '오늘도 코미가 너무 귀엽구요 오늘도 코미가 너무 예쁘구요 오늘도 코미가 너무 잘해주구요 오늘도 코미가 너무 착하구요 의젓한 코미가 있는 마지텐시 최고', 39, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '처음 방문해본 메이드카페였는데, 기대 이상으로 정말 즐거운 시간이었습니다. 메이드 분들 모두 친절하시고, 밝고 유쾌한 분위기로 응대해 주셔서 자연스럽게 기분이 좋아졌어요. 다들 예쁘시기도 하고, 손님들과 소통하는 모습도 재치 있고 재미있어서 지루할 틈이 없었습니다. 무엇보다도 카페 내부가 깔끔하고 에어컨도 빵빵하게 나와서, 한여름 무더위에도 시원하게 시간을 보낼 수 있었어요. 더운 날씨에 어디 갈지 고민된다면, 이곳처럼 시원하고 기분 좋은 공간에서 쉬어가는 것도 정말 좋은 선택일 것 같습니다.', 85, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '진짜.. 오랜만에 보시는 사화님이랑 신입이신 니니님, 차차님을 보았는데.. 뉴비에 행동이 커엽..다라고해야할까? 암튼 너무 재미있어서 담에 와서 또 오랜만에 보시는 분들이랑 대화를하면서 놀다와야겠어요!', 126, 20, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '라이브도 볼 수 있고 메이드가 많아요 근데 메이드들이 저한테 말걸어줘요 대박이에요 그리고 돈 내면 같이 사진도 찍어줘요 또 오고 싶어요', 17, 5, 'GOOD', SYSTIMESTAMP);
