INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '코미가 오늘도 너무 예쁘고 귀엽고 착하고 상냥하고 그냥 코미가 최고에요 미쳤어요 너무좋아요 야무진 코미가 일하는 마지텐시 최고', 27, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '일 메이드카페 집 일 메이드카페 집 평생 오고싶다 부자백수하면서 메이드카페 오고싶다 재밌다 즐겁다 맛있다! 다들 놀러오세요 마지텐시데비', 112, 21, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '메이드카페 처음 와봤는데 느낌좋고 평일 주간에 왔더니 사람이 없어서 혼자 만끽하기 좋았어요. 다들 얘기가 편해서 마음놓고 토크했습니다. 음료는 블루소다 먹었는데 적당히 달달해서 괜찮았던것 같아요. 지나치게 달지 않았어서 좋았어요.', 41, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '메이드카페 처음 가봤습니당 혼자가는거 무서워서 긴장하고 갔는데 너무 재밌었어요 짱👍 들어가자마자 친절하게 설명해주신 츄츄님과 엄청 밝아서 에너지 넘처보이시는 류님, 열심히 가게 정리하시면서도 계속 말 걸어주셔서 감사했던 도룡님, 첫출근하셔서 고장나보이셨던 루아님, 체키 같이 찍어주신 사화님까지 메이드분들이 너무 예쁘셨어요 즐거운 시간을 보냈습니다 굿👍', 75, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '코미가 말아주는 니지산지 니지산지 잘 모르는데 코미덕분에 흥미가 생길지도? 오늘도 코미가 너무너무 귀엽고 예쁘고 여기는 천국이 분명합니다', 288, 32, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '역시 더운날씨에는 시원한 음료수가 최고인거 같아요 언제나 메이드분들도 친절하시고 외모도 다들 너무 예쁘셔서 눈이 즐겁습니다 다음주도 방문할예정입니다!!', 20, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '마지텐시도 벌써 여러번 방문 하지만 그럴때마다 친절한 메이드분들 덕분에 항상 즐겁네요:) 여기에 한번 오신다면! 정말 좋은 경험을 하고 가실 수 있다고 장담할 수 있습니다!', 22, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '멘탈 복구겸 간만에 서울 나들이. 이번에도 편하게 잘 쉬다 가요 부담없이 편하게 얘기하면서 쉬기 좋아요 가만히 쉬고 있는데 유잼상황 계속 생겨서 웃겼음. 매번 다음엔 디저트도 먹어봐야지 해놓고 뭔가 먹고와서 포만감때문에 못먹는게 좀 아쉽기도', 88, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '처음 방문했는데 분위기부터 완전 다른 세상에 온 느낌이었어요! 컨셉이 너무 재밌어서 시간 가는 줄 몰랐고, 모든 직원분들이 정말 친절하게 대해주셔서 기분이 끝까지 좋았어요. 덕분에 하루 종일 웃으면서 즐길 수 있었습니다. 다음에 또 오고 싶은, 진짜 강력 추천하는 메이드카페예요! 💖', 11, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '비비님 라이브가 너무 훌륭했어요~~~! 살짝덥다니까 바로 선풍기도 틀이주시고~ 다른손님이 주문한 라이브도 같이봐서 너무 즇았어요~ 얼그레이키도 적당한 달달함으로 딱 알맞게 만들어주셔서좋았어요!!!!! 감사합니다메텐데최고', 46, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '올만에 올리는 마텐데 리뷰 오늘은 루리님의 오출완을 보고 왔습니다. 이야 올만에 여러 메이드분들과 이야기하면서 마텐을 즐기고 비가와서 따듯한 보리차 한잔으로 느긋하게 즐기고 있는 중입니다. 이제 무엇을 간식으로 먹을지 고민을 더 해보면서 더욱 즐거운 마텐을 즐길예정입니다. 다른 분들도 더운날 잠시 더위를 피할곳이나 추운날에는 추위를 피할곳이 있다면 잠시 들려서 휴식을 즐겨주세요.', 48, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '항상 렌님이 잘 반겨주셔서 재미나게 놀고왔습니다 테루님 프리렌 귀여우시고 하루님 코스도 항상 멋지셔요 샤샤님은 항상 밝게 반겨주셔서 행복하고 쿠로님은 기억도 잘해주셔서 감동이었습니다 마텐으로 놀러오세요', 32, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '예쁜 언니들이 많아요 계속 말도 걸어주시고 친절해요 대화가 재미있어요 메이드 카페는 처음이라 긴장했는데 금방 긴장도 풀어져서 재미있게 놀았어요 초코 파르페 맛있어요 메론소다도 맛있어요❤️', 20, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
