INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '메이드분들이 너무 열심히 일하시고 분위기도 좋아요! 언제 방문해도 마음 편하게 커피 한잔 할 수 있어서 좋아요! 음료로 아미리카노 시켰는데 아주 맛있었어요!!! 그리고 내부도 시원하고 너무 좋아요 화장실도 깔끔!!!!!', 87, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '서울권은 처음 방문해본 메이드카페. 처음 방문한 사람도 잘 대해주셔서 좋았습니다. 완전히 I이신분들도 충분히 오셔서 즐기는데 문제가 없을것 같습니다. 콘셉트도 따끈따끈하게 살아있어 여행 겸으로도 방문하기 좋은것 같습니다.', 82, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '오늘은 1주년이 되는 날입니다 기념도 하면서 다들 맛있게 드시라고 케이크를 사왔습니다 항상 감사드리고 앞으로도 잘 부탁드리겠습니다', 31, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '메이드님들이 재밌고 음료가 맛있습니다 혼자와도 어색하지 않게 대화를 잘 해주십니다 다른 카페보다 체키도 잘 꾸미고 라이브도 잘하세요!!', 45, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '항상 즐겁게 잘 방문하고 있습니다!!! 오늘은 특의데이로 평소와 다른 모습을 볼 수 있어 너무 좋았네요!!! 메이드분들도 친절하시고, 음식도 맛있고, 라이브도 멋진 마텐으로 오세요~~~', 38, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '오늘은 18일에 놀다오시는 메이드분들에게 전달할 선물과 요즘들어 너무 아파보이신 스이님에게 쇠고기야채죽이랑 타이레놀, 판콜을 드리며.. 다음에 만날때는 꼭 건강한 모습으로 보기를... 18일에 잘 놀다오시구..', 31, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '이날은 퇴근하고 가보았습니다. 방문하니 그동안 방문 했던 날들보다 방문해주신 분들이 적었습니다. 매장입장에서는 안좋았지만 방문했던 저의 입장에서는 메이드분들과 대화를 더 편하게 길게 할 수 있어서 좋았습니다. 가는 날이 정말 운에 따라 달라지는거 같습니다. 저는 사람이 많은 것보다는 적은걸 선호하여 더 좋았습니다. 또 방문하겠습니다.', 17, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '어제에 이어 또 방문했어요 음식이 너무 맛있구 메이드 분들 이 누무너무 친절하세요. 손님분들도 많이 북적북적이면서도 메이드분들이 너무 잘 대해주셔서 시간가는줄 모르겠어요!!! 앞으로 이런 날들이 계속되면 좋겠네요~~~~ 감사합니다!!!!', 0, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '손님분들이 오시면 메이드분들이 인사를 위해서 알려주는 필수요소입니다 손님이 왔다는걸 알 수 밖에 없는 종소리에 모두의 시선이 집중되지만 없어서는 안될 최고의 소품입니다', 90, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '메이드카페 가게 사정으로 로제린 집사카페에 올라와서 매장을 즐기고있는데.. 매장 분위기가 메이드카페와 달라서 뭔가.. 조용해서 좋다고해야하나? 아무튼 뭔가 조용한 분위기에 바집에온거같아서 너무너무 좋아요!!🥰 다음에는 로제린 집사카페를 가봐야겠어요!^^', 63, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '항상 방문해도 최고의 메이드 카페라고 생각될만큼 즐겁습니다!:) 마지텐시의 장점은 무엇보다도 친절하고 아름다우신 메이드 분들이라고 생각해요! 👍 언제가도 친절하십니당~!', 41, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '오늘 다른 곳 가려다가 마텐을 들렸습니다. 평일에 개강이라 그런지 사람이 별로 없었습니다. 메이드분들이 친절하고 재밌습니다 특히 샤샤님이 아주 섹시하십니다', 52, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '매장이 청결하고 깨끗합니다. 더운여름날 에어컨도 빵빵하게 "잔말말고 에어컨 파워냉방으로 틀어"주셔서 넘 시원합니다. 메이드 분들도 친절하시고 반겨주시니 내향적이신분도 오셔도될거같아요!!', 53, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '메이드분들이 항상 친절하게 맞아주셔서 너무 감사해요!!  음료도 맛있게 말아주시고 에어컨도 너무 시원해서 좋아요!! 음악도 제 취향이고~ 손님들도 행복해보여서 좋아요~!!!  늘 방문항때마다 행복한 시간 보내구 있어요~~~!!!', 77, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '주디 예쁘다..아름답다...귀엽다....나...심장이..안 좋아지기 시작했어..사람이...아니야....조각이야..조각상이...말을해...여러분들...심장 조심하세요...', 50, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '자주방문하는 마지텐시 메이드카페!! 음식도 맛있고, 라이브도 너무 멋있어요!!! 항상 재밌게 잘 놀아주셔서 너무 고마워요!!! 또 방문할게요!!!', 47, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '네, 휴가쓰고 다녀온 메이드카페입니다. 시작부터 끝까지 있어보았고 즐거웠습니다. 평소에는 매일 회사집회사집에서 이렇게 한번씩가서 사람들의 기운을 받기좋은곳입니다. 많은 메이드분들이 활기차고 기분 좋게 대화할 수 있는 시간을 줍니다. 4번째와서 이젠 정말 많이 익숙해진 듯 합니다.(물론 입장시, 퇴장시, 음식나왔을 시에 하는 행동?은 아직도 힘듭니다) 사람과 대화 연습하기 좋습니다. 추천 드립니다.', 55, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '메이드 분들 다 착하고 친절하셔요 먼저 다가와주셔서 대화도 해주시고 평소에 사람이랑 대화하고 사람 냄새가 그리운 사람들은 강추 김치볶음밥도 맛있어용', 26, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '메이드카페에서 체키라는 사진과 편지로 추억을 남길 수 있는 컨텐츠를 신청할때 사진을 찍을때 각도의 조절을 위해서 밟고 올라갈 수 있는 발판으로 메이드 카페에는 필수입니다', 109, 25, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '마지텐시는 언제나 와도 재밌다!! 메이드들 다들 넘 친절하구 방치없이 항상 재밌게 해줌!! 다른 메이드카페와 다르게 혼자 가도 다들 넘 잘 놀아줘서 마지텐시는 최고의 메이드카페!!', 46, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '메이드님들이 친절하고 음료수 종류도 다양해요❤️ 여러가지 컨셉 메이드님들이 많고 초보자는 세트로 시키는 게 좋대요! 메이드님들이랑 사진 찍는게 너무 좋은 추억이었어요!', 2, 4, 'GOOD', SYSTIMESTAMP);
