INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '메이드분들이 밝고 친절하게 응대해주셔서 너무 편하게 재미있게 즐길 수 있었습니다. 콘셉트도 잘 살아 있어서 색다른 경험이었어요. 사진도 예쁘게 찍고 좋은 추억 만들고 갑니다!', 44, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '오늘은 마텐데 사복데이래요 메이드분들의 평상복? 아니면 메이드복말고 다른복장도 볼수있어 아주 새로운경험이 되는 날이에요 이런 ㅇㅇ데이에오시면 많은 재밋는경험도 할수있으니 추천드려요 그리고 오시면 인생네컷 기계도있어서 인생네컷 하나씩 찍으시는것도 추천드립니다. 그리고 제육도 파니 끼니때우기에도 좋은 메뉴가 있어요.✨️✨️ 오늘은 봇치랑 료도 있었다는 사실!! \\(✨️ 3✨️ )//이거 완전 럭키비키자나!!', 34, 3, 'GOOD', SYSTIMESTAMP);
