INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '음, 이날은 게스트날이였고 평소보다 정말 사람이 많았습니다. 이 부분은 어쩔 수 없다고 생각합니다. 평소에 뵐 수 없었던 코스어(모델) 분이 게스트로 그것도 메이드로 만날 수 있으니 팬 입장에서는 정말 행복하고 좋은시간을 가질 수 있는 장소라고 생각합니다. 다만 다른 메이드분을 보러 오셨다면 가능하면 게스트가 없는 날로 하는게 좋은 듯 합니다. 평소보다 바쁘기 때문에 메이드분들도 바쁘셔서 평소처럼 대화하기도 어렵고, 많이 소란스럽다고 느껴지기도 합니다. 물론 메이드분들이 오신분들 한분한분 챙겨주시기 위해 바쁘게 움직여주시기 때문에 그럼에도 대화할때는 한명한명 집중해서 해주시기 때문에 이날도 결국 만족스럽게 있다가 나왔습니다. 제 개인 생각이므로 게스트가 계신던 안계시던 오면 좋습니다.', 18, 10, NULL, SYSTIMESTAMP);
