INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '그림을 정말 잘 그리는 메이드분들이 계셔서 캐리커쳐를 주문하신다면 아주 멋진 예쁜 그림을 받으실 수 있습니다 원하시는 물건에 받게 된다면 특별한 추억을 가져갈 수 있습니다', 116, 26, 'GOOD', SYSTIMESTAMP);
