INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '오랜만에 왔는데 여유있고 자주보던 분들 계셔서 좋네요 블루소다도 오랜만에 마셔서 맛있고 더운 날 시간보내기가 좋아요 매장 밝기가 더 밝아진거 같아서 있기 더 좋은거 같아요 다음에도 또 올 예정입니다 :-)', 29, 10, 'GOOD', SYSTIMESTAMP);
