INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '메이드분들이 다 친절하시고, 라이브 공연이 너무 재밌어요!!! 친구분들하고도 연인분들하고도 좋은 외출이 될 수 있겠네요!!! 꼭 추천합니다ㅎㅎ', 6, 1, 'GOOD', SYSTIMESTAMP);
