INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '좋습니다. 처음 가보았는데 다들 친절하였고, 대화하기 좋았습니다. 분위기는 메이드분들마다 달라서 말씀드리기 어려우나 계셨던 분들 모두 활기차셨습니다. 제가 갔을 때는 신규 인원도 있어서 더 새롭다고 느꼈습니다.', 19, 2, 'GOOD', SYSTIMESTAMP);
