INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '주디님이 섹시하고 렌님이 바쁘고 테루님이 귀엽고 바다님이 맹하고 로제님이 맛있고 사화님이 웃기고 아키님이 쉬고계시고 코미님이 깨끗하고 샤샤님이 앞머리가없어요ㅜ 그치만 체키는찍었어요!! 다들 정말 잘놀아주셔서 시간가는줄 몰랐어요 매일매일 오고싶어요~!~! 돈과시간만있다면...', 92, 24, 'GOOD', SYSTIMESTAMP);
