INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '다들 너무 친절하시고 오랫동안 있어도 부담 없고 계속 대화를 걸어주셔서 지루하지않은 즐거운 시간이었어요 음료도 맛있고 다들 예쁘셔서 재방문 의사 있습니다!🥰', 4, 9, 'GOOD', SYSTIMESTAMP);
