INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '정말 다들 너무 친절하시구 이야기 잘 해주셔서 지루할 틈도 없이 시간보내서 좋았어요!그리고 공간도 넓고 시원해서 좋았구.. 시간이 빨리간거 같아요! 다들 너무 예쁘셔서 행복했어요!!👍다음에 또 오고싶은 곳이었어요!!', 431, 61, 'GOOD', SYSTIMESTAMP);
