INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '마지텐시 여러번 방문하지만 늘 좋네요! 항상 친절히 말씀해주시고 최고의 대접으로 즐겁게 만들고 최고의 서비스를 받아서 감동ㅠ😭 너무 좋습니당!!', 26, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '마지텐시 메이드카페는 상수역에서 아주 가까운데 메이드들과 함께 재밌는 컨텐츠와 맛있는 음식, 좋은 분위기를 즐길 수 있는 곳입니다.', 1, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '정말 재밌고 다들 친절하시고 예쁘세요 특히 시로님은 귀엽고 쿠로님은 예쁘시고 사화님은 퇴폐미스럽게 예쁘시고 코미님은 아름다우세요 다들 복장이 잘어울리시는거 같아요', 66, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '오자마자 귀여운 그림에 그렇지 못한 멘트를 적어주시는 메이드분이 계십니다 반전매력...? 이라고 해야하요?? 그래도 즐거우면 됐다고 생각합니다 다들 즐겨요~', 44, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '마지텐시 메이드카페는 상수역에서 아주 가까운데 메이드님들과 함께 재밌는 컨텐츠와 맛있는 음식, 좋은 분위기를 즐길 수 있는 곳입니다.', 37, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '어제 방문하고 오늘도 왔어요 뽑기도 해봤는데 재밌네요 다음에 오면 종종 뽑을 거 같아요 ㅋㅋ 그리고 오늘 니니님 정말 예뻐요~', 105, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '항상 방문 할때마다 너무 친절하게 해주셔서 감사드려요~:) 메이드 분들 친절히 대화해주셔서 천천히 여유롭게 머물다 가기 좋은 장소에요 너무 착하신 분들이 많아서 좋아요😀', 23, 9, 'GOOD', SYSTIMESTAMP);
