INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '마지텐시 메이드카페는 상수역에서 아주 가까운데 메이드와 함께 재밌는 컨텐츠와 맛있는 음식, 좋은 분위기를 즐길 수 있는 곳입니다.', 48, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '메이드카페 처음 가봤는데 분위기가 독특하고 직원분들 응대가 친절하고 컨셉이 확고해서 재미있습니다 ! 특별한 경험 원하시는 분들께 추천합니다 !', 28, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '아이스크림 먹고 있으면 미소녀가 말걸어줍니다. 이거 진짜 대박입니다... 그리고 같이 사진도? 찍을 수 있습니다. 메뉴에 떡볶이 추가되면 좋겠습니다.', 38, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '자주 들리고 있습니다 메이드들이랑 대화하기 좋고 음식이 정말 맛있습니다 라이브도 재밌어서 꼭 들어보셨으면 좋겠습니다 즐거운 시간 보내다 갑니다', 4, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '잠시도 지루할 틈이 업서요 순수 재미를 원하신다면 마텐을 추천드립니다 그리고 라이브가 쌈@뽕해요 그리고 김렌이 귀엽습니다 +샤샤가 매혹적이에요', 5, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '마지텐시 메이드카페는 상수역에서 아주 가까운데 메이드들과 함께 재밌는 컨텐츠와 맛있는 음식, 좋은 분위기를 즐길 수 있는 곳입니다.', 47, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '3번째 방문하게 된 메이드카페. 처음보다는 확실히 긴장도 좀 덜하고 메이드분들이 말걸거나 하는거에 거부감이 조금 줄었습니다.(메이드분들의 문제가 아닌 제가 여자랑 말을 잘 못합니다 ㅎㅎ) 갈때마다 메이드분들이 많으셔서 새로운분도 보게 되고, 대화할때 메이드분에 따라 각각 새로운 느낌 입니다. 라이브를 진행시 정말 정성을 다해 해주십니다. 계속 방문할 것 같습니다.', 42, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '날씨도 덥고해서 시원한 음료수 마시러 메이드카페 왔습니다!! 메이드분들도 다 친절핫고 음료수도 시원해서 맛있게 마셨습니다 심심할때 또 놀러갈생각입니다', 89, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '마지텐시 메이드카페는 상수역에서 아주 가까운데 메이드들과 함께 재밌는 컨텐츠와 맛있는 음식, 좋은 분위기를 즐길 수 있는 곳입니다.', 31, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '너무나도 즐거운 시간입니다 다들 즐겁게 즐기고 이렇게 너무 시간가는 줄도 모르고 좋은시간 보내다가 나가네요 다들 기운차도 활기차게 일하는 모습이 너무나도 보기좋아요. 매일매일 오고싶어요~', 31, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '메이드 카페는 처음이라 그리고 혼자가서 많이 떨렸는데 친절하게 설명해 주시고 감사했습니다.라이브도 엄청 잘 하세요! 메이드분이랑 같이 체키나 인생네컷 찍고 꾸며주면서 같이 대화하는 시간이 좋았습니다', 64, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '메이드 분들이 친절하시고 칭찬해주시고 함께 대화해주셔서 너무 감사하고 좋은 시간을 보내네용🫡 덕분에 행복한 시간 보내게 되네요!', 2, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '2번째 방문~!! 1번째 방문이 너무 재미있어서 다시 왔습니다 여전히 라이브 완벽했고요 제가 보장합니다 라이브는 여기가 탑이에요 ㅎㅎ 그리고 메이드 분들도 엄청 친절하시고 재미있으세요!! 처음오시는 분들도 오시기 편할정도로 너무 좋습니다 꼭 한번 오세요!!', 79, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '메이드 카페 처음 와봤는데, 생각했던것 보다 전부 친절 하시고 크게 부담스럽지 않았습니다. 말 주변에 없어서 걱정했는데, 말을 안하고 있어도 와서 말을 잘 걸어주십니다. 다음에 기회가 된다면 한번 더 와보겠습니다.', 7, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '메이드분들 다 친절하시고 김치볶음밥(오므라이스) 맛있습니다 라이브도 가끔 하시는데 잘하시더라구요 메이드카페 처음이신 분들도 와도 좋을듯', 18, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '코미가 오늘도 너무 예뻐요 코미가 오늘도 너무 귀여워요 코미가 오늘도 너무 상냥해요 코미가 오늘도 너무 재밌어요 코미가 오늘도 너무 좋아요', 33, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '그제 방문하고 오늘도 방문했지만. 오늘도 비슷하네요 시간 추가 관련 이야기 전달도 부족하고  그 이어폰 왜 계속 끼는지 모르겠고 메이드들은 계속 네? 네? 이러고 대화가 자연스럽게 연결도 안되고.  메이드카페 기본적인 목적이 자신이 좋아하는 메이드하고 대화하며서 음료 마시고  사진찍고 하려고 가는거 아닌가요?  대화가 안되면 가는 목적이 없어지는것 같은데 저만 불편한건지 모르겠네요', 39, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '대화하기 편하게끔 다들 신경 많이 써주셔서 별 생각 없이 혼자 와도 좋은 시간 보낼 수 있어 좋아요. 다들 예쁘시기도 하고 메뉴도 잘 나오는 듯.', 48, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '두번째 방문인데 인테리어도 좋고 집사님들 재밌어요. 다들 분위기도 화목한거같고 좋네요. 술은 안 마셔봤는데 다음에는 마셔보고싶네요.', 26, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '오랜만에 마텐데 방문 오늘 지뢰데이였는데 다들 잘어울리네요 오늘도 덕분에 재밌게놀고갑니다 마텐데는 갈때마다 재밌네요 이제 메이드들이랑도 어느정도 친해진거같아서 친밀감도 높고', 50, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '너무 친절하고 재밌어요 오랜만에 방문했는데 다들 친절하게 해주셔서 오래있다가 가네요 다음에 또 올게요 음료가 맛있어요 블루소다를 추천드려요 꼭 드셔보세요', 16, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '꽤나 자주 오게 되는 마텐! 일찍 와서 그런지 메이드들이랑 대화도 많이 하고 새로 온 신입 메이드분도 있어서 친해 질 수 있어서 재밌었어요', 43, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '전체적으로 다좋았는데 메이드분들이다 이어폰을 한쪽씩 끼고계시다보니 대화를 잘못들어서 이야기하면 네? 이러니  대화도 잘안되고 조금 불편했습니다 무슨이유에서 착용한건지 모르겠지만 안좋은것같습니다. 대화보단 보는걸로 만족하라는건지 모르겠네요', 20, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '오랫만에 놀러왔는데 방가운 분들이 있으니깐 피곤한기운이 싸악~ 사라지는 듯한 느낌이라서 뭔가 회복이되어서 좋다. 다음에는 또 언제 올까? 오늘은 야간알바끝나고 수원까지 다녀와서 피로가 많았지만 카페에 놀러오니깐 피로회복이 많이되어서 좋았슴다. 다음에 또 놀러 오겠슴다! 메뉴를 외워버린 고인물같지만 같지않은둣한 고인물이가!', 13, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '메이드카페를 자주갔었는데 오랜만에 뵙는 메이드분들도 계셔서 너무 좋았습니다. 요즘 바빠서 자주 보지못했었는데.. 8~9월에는 좀 더 많이 뵐수있도록 노력해볼게요!', 12, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '금요일 오픈 시간이라 사람이 많을 줄 알았는데 한적해서 좋았고 메이드분들과 여러 주제로 대화할 수 있어서 좋았어요 늘 코미님 보러 오는데 언제 봐도 예쁘고 귀여우신 거 같아요', 7, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '거의 한달만에 가는 마지텐시메이드카페! 오랫만에 갔어도 재밌다요! 요즘 현생이 너무 바빠서 전처럼 자주 못갔지만.. 너무 오랜만에 보는분도 있어서 뭔가 새롭다? 암튼 재밌어서 좋았어요!!', 55, 15, 'GOOD', SYSTIMESTAMP);
