INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '메이드분들이 친절하시고 여러 주제로 대화할 수 있어서 좋았어요 항상 코미님 보러 오는데 볼 때마다 늘 예쁘고 너무 귀여우신 거 같아요 ! 앞으로도 종종 올 거 같아요 !', 48, 7, 'GOOD', SYSTIMESTAMP);
