INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '메이드분들이 바쁠때 티비로 심심하지 않도록 애니를 틀어줍니다 그러면 어느순간 본인의 자리에 와서 이야기를 해주시는 메이드분이 계실겁니다', 1, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '짝짝짝! 라이브와 함께 하는 즐거운 마지텐시ㅎㅎ 이외에도 즐거운 컨텐츠가 너무 많아서 즐길 거리가 너무 많아 행복한 시간이였어요!', 30, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '메이드카페 놀러 왔습니다 오늘은 날씨가 더워서 서비스로 음료수 한잔 받았어요 메이드분들도 너무 친절하고 에어컨도 시원하게 나와서 편하게 쉬다갑니다', 5, 8, 'GOOD', SYSTIMESTAMP);
