INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '이걸 보시는 당신 오늘 샤샤님 생일 입니다 지금 당장 예약해서 축하해주고 체키 찍고가십시오! 그리고 샤샤님 생일 축하드려요 ㅎ', 61, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '재 친구 밈형이가 너무 좋아해요^^ 메이드카페 맛들려서 vip가 되겠다고 하네요~~ 우리 민형이 많이 예뻐해주시고~ 음료도 맛있게 주문도 걸어주시고 신세 많이 지겠습니다!', 18, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '마지텐시 메이드카페는 상수역에서 아주 가까운데 메이드님들과 함께 재밌는 컨텐츠와 맛있는 음식, 좋은 분위기를 즐길 수 있는 곳입니다.', 35, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '마지텐시데비 카페에서 추억을 만들어 가져갈 수 있는 체키에 들어가는 예쁜 사진을 찍어서 함께 마음 따뜻하게 즐기는 행복을 가져가세요', 27, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '메이드들이 예쁘고 귀엽고 웃겨요 ㅋ.ㅋ 오시가 있을 때 가면 좋아요 네컷사진기가 있는게 너무 너무!! 장점... 체키나 라이브, 사진이 저렴해서 좋아요 다음에 또 올게요', 16, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '쥬디님 초 카와이 메챠 카와이 대박 다른 메이드카페보다 더 친절하시고 시간 가는 줄 모르고 봤습니다. 다음에도 꼭 지인데려와서 신고식 시켜주고 싶네요 마지텐시 짱 굿굿', 2, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '마지텐시  메이드카페는 상수역에서 아주 가까운데 메이드님들과 함께 재밌는 컨텐츠와 맛있는 음식, 좋은 분위기를 즐길 수 있는 곳입니다.', 78, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '밖에서 음식을 배달 시켜서 먹을 수 있는 매우 좋은 마지텐시 매장에서 즐겁게 시간을 보내며 행복한 하루를 마무리 할 수 있어서 좋습니다 다들 마지텐시에 놀러 오세요', 27, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '메카 자주 가는데 여기 직원들 다 말도 잘걸어주고 엄청 친절합니다!! 특히 니니님 겁나 이뻐요!!! 다들 보러가세요! 다른 메이드 분들도 하나하나 겁나 친절해요!!! 또 방문 할것같아요!!! 아무튼 니니님 짱👍🏻', 39, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '이제는 완전히 즐기는 메이드카페 너무 재밌어요ㅎㅎ 메이드 분들이 너무 친절하셔서 좋아여~~ 그리고 오시면 여성스럽고 아름다우신 샤샤님이 일을 열심히 하고 계십니다', 33, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '메이드분들이 너무 친절하고 좋아요! 혼자 오신 분들도 계시고 여럿이 오신 분들도 계신데, 모두 즐겁게 시간 보내시고 가시는 것 같아요! 명함도 너무 귀엽고 체키도 정성껏 꾸며주셔서 좋았어요!', 55, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '갈 때 마다 너무 편안한 마텐데! 오늘도 정말 재밌게 놀다 갑니다 여러 메이드카페 가봤지만 메이드카페 입문하시려는 분들에게 가장 추천하는 곳은 역시 마텐인 거 같아요 ㅎㅎ 강추합니다', 39, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '저번 방문 이후에 만족스러워서 재방문하였습니다. 처음 뵙는 근무자 분들이 많아서 어색할 것 같았는데 다들 친절하게 잘 해주셔서 즐거운 시간을 보냈어요.', 30, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '애옭 얼굴이 다 했다 사람 얼굴이 이렇게 아름다울 수가 있는지 사랑하는 여러분들 이 글을 읽는 우리 모두 애옭을 숭배하며 그녀를 사랑하고 아껴주십니다 모두 전지전능하시고 고귀한 애옭님에게 기도를 올립시다 애멘..', 77, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '평일 15~17시 방문했습니다. 평일 두 번째 타임인데도 사람이 꽉 찬게 인기가 정말 많네요. 초코 파르페 리뷰 보고 시켰는데 만족스러웠습니다!', 78, 13, 'GOOD', SYSTIMESTAMP);
