INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '오늘 처음으로 방문하는 코스프레 메이드라 궁금하고 들어와보니 예쁘고 귀여운 메이드분들이 친철하게 대접해 드리고 대화도 어색하지 않게 해수셔서 있는건 만으로 행복하고 힐링하고 가고 왔습니다. 음식과 디저트들도 제 입맛에 맞게 맛있게 먹었고 메이드 라이브도 재미있게 보고 왔습니다. 만약 제방문 하면은 주말에 코스프레 게스트들 오는데 한번 와보고 싶습니다. 오늘 메이드분들과 즐겁게 놀다갑니다.~ㅎ', 98, 22, 'GOOD', SYSTIMESTAMP);
