INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '메이드 카페 처음 가보는데 매장이 너무 예뻤어요! 초반엔 낯설고 어색했지만 말을 많이 걸어주시고, 웃으면서 다들 천사처럼 인사해주시니까 절말 다른 세계에 와있는 것처럼 행복했습니다! 메뉴는 소문대로 정말 맛있었어요! 정말 뜻깊고 즐거운 추억을 남겨주셔서 감사합니다! 다음에 기회가 된다면 또 가고 싶습니다ㅠ!! 최고에요💖', 159, 39, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '오늘 마지텐시 메이드카페 왔는데 예쁘시고 잘생기신분들이 너무 많네요~ 다들 너무 친절하시고 너무 좋네요 ㅎㅎ 다음에도 방문 많이 할거 같아요 ! 앞으로 많이 방문하지 않을까요??? ❤️', 14, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '메이드카페 굉장히 즐거워요 색다른 재미를 느낄 수 있고 메이드 분들이 편안하게 분위기를 이끌어주셔셔 어색하지 않고 대화도 너무 즐거웠어요 또 올게요', 20, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '오늘 코미님 출근하셔가주고 왔는데 사복데이여가주고 메이드분들 사복 모습들을 볼 수 있어서 새로운 느낌이었어요 ! 꽤 오랜만에 방문한 거 같은데 코미님은 언제 봐도 정말 귀여우신 거 같아요 !', 29, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '처음 가보는 메이드 카페... 쑥스러울 수 있지만 직원분들이 너무 친절하게 잘 응대해주셔서 긴장하지않고 재밌게 잘 놀다갑니다!!!', 106, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '메이드 카페에 익숙해지고 있습니다 처음엔 좀 쉽지 않았는데 어느 정도 익숙해지니 재밌네요 +주디 님이 섹시하고, 쿄코 님은 잘생겼고 샤샤 님이 매혹적이에요', 13, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '코미귀여워코미귀여워코미귀여워코미귀여워코미귀여워코미귀여워코미귀여워코미귀여워코미귀여워코미귀여워코미귀여워코미귀여워코미귀여워코미귀여워코미귀여워코미귀여워코미귀여워코미귀여워코미귀여워코미귀여워코미귀여워코미귀여워코미귀여워코미귀여워코미귀여워', 21, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '지금처럼 마지텐시가 웃는 모습으로 계속해서 자리를 지켜주면서 행복하게 웃으며 손님들과 그리고 메이드분들과 집사님들이 오래오래 함께하면 좋겠습니다', 7, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '오늘은 돌핀 데 이여서 매장에 손님들이 꽉 차있었다. 이렇게 많은 손님들이 분비는 건 너무 오랜만이어서.. 살짝.. 메이드 분들이랑 대화를 자주 못해서 살짝... 아쉬운 느낌이 많았지만.. 4시부터는 3시 타임보다는 많이 대화를 할 수 있어서 좋았었다. 오랜만에 보는 메이드 분들도 있어서 생존신고하러도 간 거 같은 기분? 이 들긴 했지만 그래도 나름 재미있었고 새로 나온 메뉴 다코야키도 먹어보았다. 메이드 분 한 분께서 다코야키 보고 문어라고 하셔서 살짝 빵 터지기 긴했다. 6월에는 좀 자주 나오려고 했는데.. 가능할까?', 49, 5, 'GOOD', SYSTIMESTAMP);
