INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '오늘 포함하여 두번째 방문 입니다 오늘도 메이드분들 친절 하시고 이야기 하는게 이렇게 재미 있는거 처음 입니다.메이드 분들 좋아하시는분 에게 강력 추천합니다.^^', 14, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '간만에 방문! 다들 다가와서 말걸어주셔서 편하게 대화할 수 있었습니다 라이브도 즐거워요! 미소녀가 말아주는 음료와 라이브 이것은 귀하네요 배불러서 음식은 못시켰는데 다음엔 음식도 먹어볼 생각임다', 69, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '코미 얼굴이 다했다. 진짜 사람이 어떻게 저리 귀여울수가 있나 저렇게 태어나면 무슨 기분일까 너무 행복할 것 같아 코미 얼굴은 국가에서 보호하고 홍보를 해야한다. 대한민국 발전을 위해서라면 코미를 지켜야 한다. 대한민국의 국보 0호는 이제부터 코미다 아름답다. 귀엽다. 예쁘다. 사랑스럽다.', 0, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '맛있는 간식을 드리기 위해서 사왔는데 만족하신 모습을 보고 행복함을 느꼈습니다 오늘은 자유복으로 코스를 하신분들도 있고 사복을 입고 오시는 분들도 계셔서 각자의 매력을 볼 수 있습니다', 37, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '메이드가 착해요 메이드가 예뻐요 메이드가 친절해요 카리나가 돌아다녀요 말이 안되는 것 같아요 카리나가 한교동을 끝내주게 잘 그려요 진짜 말이 안되는것 같아요 …', 23, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '재밌게 잘 놀다갑니다! 음식도 맛있었고 분위기도 좋고 라이브 쇼도 재밌었습니다 재있어서 이틀 연속으로 왔네요 기회되면 또 들리겠습니다!', 39, 9, 'GOOD', SYSTIMESTAMP);
