INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '재미를 위해서  방문 했는데  러무 재밋고 유익햇어요 언제나 심심하거나  시간 남을때 방문하면  좋은결과를 얻을거라생각합니다  고민상담도 잘해주시네요', 17, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '음식도 맛있고 이색적인? 경험을 하기에 좋은 곳이라고 생각합니다. 보드게임들도 종류가 많아서 즐기기 좋습니다. 친절하게 응대도 잘해주셔서 있는시간 내내 편하고 재밋는 시간 보낸 것 같습니다.', 401, 31, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '카페 내부는 아기자기하고 깔끔했어요. 테이블마다 귀여운 소품들이 놓여 있고, 직원분들(메이드님들!)은 각자 개성 넘치는 복장을 입고 계셨어요. 주문은 메뉴판에 있는 ‘아이스 아메리카노+체키2장’를 시켰는데, 아이스아메리카노에 간단한 마법(?) 주문도 외워주셨습니다. 약간 부끄럽긴 했지만 은근히 재미있더라고요.', 77, 15, 'GOOD', SYSTIMESTAMP);
