INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '요즘 날씨도 많이 더워서 시원하게 음료수 한잔하러 왔어요 파인애플주스 시켰는대 너무 맛있고 시원하고 메이드분도 옆에서 친절하게 대해주셔서 즐겁게 놀다갑니다', 18, 10, 'GOOD', SYSTIMESTAMP);
