INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '메이드분들 너무 예쁘시구 너무 재미잇엇어용 음식도 다 맛잇고 다음엔 꼭 더 오랜시간 더 잇고 싶어용 담에 또 올게요 진짜 너무 재미잇어용', 89, 15, 'GOOD', SYSTIMESTAMP);
