INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '메이드분들이 친절하고 라이브가 맛있어요 홍대에서 메이드카페 체험해보고싶으신분들은 마지텐시앤데비 방문해주세요! 컨셉도 좋고 특별한 이벤트데이도 많아서 즐거워요', 52, 11, 'GOOD', SYSTIMESTAMP);
