INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '메이드 분들이 밝고 친절하게 응대해 주셔서 재밌게 즐길 수 있어서 좋았어요 ! 오늘도 코미님 보러 왔는데 언제 봐도 정말 귀여우신 거 같아요 앞으로도 자주 올 거 같아요 !', 38, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '메이드분들 다들 진짜 너무너무 귀엽고 아름다워요 올 때마다 즐거운 추억 잔뜩 만들고 가서 돈 하나도 안 아깝구... 매일오고싶어여 혼자 와도 하나도 안 어색하고 편해요 더더 번창하셧으면좋겟단마음이에요 🫰🏻🫰🏻🫰🏻', 6, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '문화생활 너무 좋아요 ! 퇴근하시고 오시는분들도 계시고 다른 메이드카페에 비해 너무 프리하게 다가와서 편했습니다 번창하세요 사장님', 36, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '몇 번 방문해 봤는데 메이드님들 친절하시고 손님들 정말 잘 대해주시고 컨셉도 좋습니다. 리뷰 연장 이벤트 하고 있으니 방문 꼭 해 주시고 좋은 리뷰도 남겨주세요', 46, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '시험 끝나고 메카 왔어욥 호호 마텐은 언제 와도 항상 쟈밌네연 음료도 다 맛있고요 다들 너무 예쁘세요 진짜 다음에도 또 방문할게요 굳굳 최고에요 딸기라떼도 참 맛있어욥', 103, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '샤샤님이 귀엽고 예뻐요 대화를 편하게 잘 이끌어주셔서 즐거운 시간 보낼 수 있었어요. 그리고 여기 밥이 맛있거든요? 김치볶음밥 오므라이스 꼭 드셔보세요. 케찹으로 귀여운 그림도 그려주시니까 이득입니다', 80, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '홍대에 여러 메이드 카페를 가봤는데 마지텐시가 가장 편하고 이야기하기 좋아요. 라이브 퀄리티 좋은 분들도 많아서 오시면 꼭 한 번 시켜보시길 추천드려요. 텐시랑 데비로 밤낮 컨셉이 다른 점도 정말 좋습니다.', 38, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '매번 올때마다 메이드들이 너무 친절하고 음식도 맛있고 서비스정신도 최고에용 주변의 지인들에게도 추천하는 메이드카페인데 낯가리는 사람들이 많아서 진입장벽이 조금 있지만 일단 한번 발을 들이는 순간 절대 못헤어나올 최고의 카페 개추해요!!!', 77, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '카페 내부는 아기자기하고 깔끔했어요. 테이블마다 귀여운 소품들이 놓여 있고, 직원분들(메이드님들!)은 각자 개성 넘치는 복장을 입고 계셨어요. 주문은 메뉴판에 있는 ‘아이스 아메리카노+체키2장’를 시켰는데, 아이스아메리카노에 간단한 마법(?) 주문도 외워주셨습니다. 약간 부끄럽긴 했지만 은근히 재미있더라고요.', 24, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '자주 가는 단골 메이드 카페인데, 갈 때마다 친근하게 맞아줘서 정말 편안한 분위기예요. 메이드 분들 한 분 한 분 다 개성이 뚜렷하고, 이름도 외워주셔서 갈수록 더 정이 갑니다. 초코 파르페랑 김치볶음밥이 특히 맛있어요.', 27, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '혼자 가도 부담 없이 즐길 수 있는 분위기였어요. 주문한 김치볶음밥에에 직접 케첩으로 그림을 그려주는데 재밌고요. 일상이 지루할때 자주 찾게 됩니다 스이님은 고로시당하는걸 좋아하시니 마구 바쁘게만들고 고로시해주면 서로 재밌게 놀 수 있을것같아요', 40, 0, 'GOOD', SYSTIMESTAMP);
