INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '술이 맛있고, 분위기에 취할 수 있는 메이드?카페입니다. 직뤈 분들이 하나 같이 친절하고, 아름답고, 열정적이라, 재미있게 놀다갈 수 있습니다.', 4, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '메이드님들이 착하고 재미있었고 매우 즐거운 경험이였다 메이드님들이 자꾸 말도 걸어주시고 재밌는 말도 해주셔서 너무 감사했다 재방문 하겠습니다!', 52, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '메이드카페의 재미는 그 테마와 분위기에서 비롯되며, 세라복을 입은 메이드들이 친절하게 대하는 모습과 아기자기한 장식들이 조화를 이루어 젊은 층에게 많은 인기를 끌고 있습니다. 전통적인 카페 경험과는 다른 특별한 순간을 찾고 있는 사람들에게 추천할 만한 장소입니다.', 6, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '오늘 새로운 메이드님들을 볼 수 있어서 즐거웠습니다 지인과 같이 왔지만 같이 즐길 수 있고 이야기하며 웃고 함께 좋은 추억을 쌓을 수 있어서 행복한 시간을 보냈습니다', 60, 15, 'GOOD', SYSTIMESTAMP);
