INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '마텐 메이드분들이 너무 착하고 귀엽고 예뻐요... 또 오고싶어요 그리고 옷들이 너무 귀여어서 구경하능데 정신 나갈 것 같아요 후엥 또오고싶따 미소녀천국!!', 30, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '진심 너무너무너무너무 아름답습니다... 음식이 맛있고 메이드분들이 너무 상냥해요. 너무너무 상냥해서 진심 마지텐시라 눈물 날 거 같애요. 정신이 치유가 되...♡', 13, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '처음해본 메이케리커쳐 맘에든닷^^ 시요졸업해서 라이브세트할일없어진줄알았더니 메이짱이 라이브연습을시작 이제 라이브set할일 생기겠닷 메이짱보기위한 마지텐시^^ 메이하고이야기할때 시간이짧긴했지만 기뻤다^^', 58, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '오늘은 다양한 모습으로 즐겁게 놀수있는 날입니다. 아직 안오신분들은 꼭 워크인이나 예약을 하셔서 잠시 놀고가시는걸 추천합니다!!! 신기한 체험들도 많이 있으니 즐겁고 행복한 하루들을 보내시기바랍니다. 항상 재미있게 놀아주시는 메이드님들 감사합니다.', 73, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '듀가나디오므라이스가 너무 맛있어요 꼭 시키세요 그리고 라면도 진짜 너무 잘끓이세요 음식도 맛있는데 미녀 메이드직원분들이 친절하게 대해주세요😍', 53, 11, 'GOOD', SYSTIMESTAMP);
