INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '인테리어가 예뿌고 메론소다가 마싯어요 직원분들도 너무 친절하시구기엽고예뻐요 특히 류님, 샤샤님 너무기엽고예쁘구사랑스럽습미다,,,,,,,😻😻😻😻', 27, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '창문이 얼리는지 몰랐네요. 창가에 앉아 시원했습니다. 사진은 없지만 파르페 양 많고 맛도 좋아 추천합니다. 메이드분들은 언제나 귀여워요', 24, 7, 'GOOD', SYSTIMESTAMP);
