INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '처음으로 마지텐시 메이드카페에 방문했어요 메이드분들이 너무 친절히 반겨주시고 매장 분위기도 너무 좋았어요 메이드 분들도 얘기를 잘 해주셔서 시간가는 줄 몰랐네요 하나부터 열까지 너무 마음에 들었어요 당연히 재방문 의사 있고요 ㅎㅎ 진짜 한번 방문드리는걸 강추 드립니다!! ㅎㅎ 너무 좋았어요!!! ㅎㅎ', 82, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '세 번째 방문인데, 여러 번 보게 된 분도 있고 처음 뵙는 분도 있어서 친근함과 새로움을 모두 느낄 수 있어서 좋았어요. 앞선 두 번보다 시간이 너무 빨리 가서 놀랐는데 그만큼 재밌게 논 것 같아요.', 48, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '오늘은 로쿠님의 예쁜 가방을 보고 너무 감명을 받아서 사진을 남겼습니다 역시 메이드 카페답게 가방마저 남다르기에 재미있는 기억이 남을거 같습니다', 15, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '마텐 놀러 올때마다 재미있게 놀고 다들 친절하셔서 재미있게 다닙니다 음식도 맛있고 지인들이랑 재미있게 놀수도 있고 라이브도 재미있습니다', 8, 10, 'GOOD', SYSTIMESTAMP);
