INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '오늘 제 여자친구가 생일이라서 방문했읍니다. (참고로 샤샤입니다~) 메이드들이 너무너무 예쁘고 착하고 친절하고 정말 예쁘고 (x2) 저를 울끈불끈하게 만드네요.^^ 더 자주 들리겟습니다.', 22, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '메이드 카페에 처음 왔는데 친절하게 다들 잘 대해주시고 오므라이스를 먹었는데 정말 맛있었습니다 오므라이스 그림도 정말 잘 그려주십니다 다시 방문 할거같아요!', 47, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '다들 너무 친절하시고 재밌게 잘 놀다가요~~~!!!!! 올 때마다 컨셉이 조금씩 다른 느낌도 있어서 색다른 재미도 느끼는 거 같아욬ㅋㅋㅋㅋㅋ 깔끔하고 조명이 은은해서 편안하게 있다 갑니다', 10, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '추천을 받아서 보리차를 시켰는데 어느분의 명언이 생각나는 맛입니다 ”꼬소하이 쳐 쥑이네!“ 정말 고소하고 맛이 깊고 추천하는 맛입니다 다들 한번 드셔보세요', 33, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '메이드들이 유쾌합니다 맛있어지는 주문을 받으면 평범한 커피도 미슐랭 맛집급 커피가 된다고 하네요. 매장이 깨끗하고 내부에 인생네컷 기계가 있어서 함께 인생네컷도 촬영할 수 있어요', 251, 82, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '이번에 벌써 6번째 방문입니다.언제나 그렇듯 메이드분들이 이쁘시고 처음오더라도 친절하게 안내해주셔서 너무 좋습니다.음식이랑 디저트들도 진짜 맛있고 오늘 너무 재미있고 행복한 하루였습니다!', 26, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '일주일만에 왔는데 너무 재미있어요 출근하신분들도 자주 뵙던 분들이라 더 즐겁네요~ 오늘도 와서 많이 이야기하고 체키도 찍고 주중에 또 올거 같아요 오늘도 유리님은 최고 그리고 텐시복입으신 스이님 최고다!!', 8, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '시간 날 때 마다 자주 들리는 카페입니다. 점원분들 조곤조곤 말을 걸어주셔서 편하게 있을 수 있습니다! 여기 로쿠님이 만들어주시는 김치볶음밥이 진짜 맛있습니다. 강추드립니다.', 13, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '저번에 최애를 보러갔당헜다가 오늘도 최애보러 왔어요 올때마다 늘 최고의 시간을 보내고 갑니다 음료도 맛있고 밥도 맛있어요 올때마다 친절하셔서 오는 보람이 있어요 덕분에 행복한 시간 보내고 갑니다', 62, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '몸건강회복필요한데 주말방문하는사람위해서 출근하는메이짱 대단해욧 내가아니면 시킬일없는 라이브까지 기분좋은하루였다 내동생(인싸)이야기로 놀란메이ㅋㅋ', 34, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '화장실이 깨끗하고 좋은 향기가 나요 메이드들이 명함에 싸인 해주시는데 너무 귀엽네요. 매장을 청결하게 유지하는 것 같아서 기분이 좋아요. 네루님 처음뵙는데 귀여우십니다 ㅎ', 0, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '갈 때마다 너무 즐거운 마지텐시 메이드카페입니다, 메이드분들이 너무 친절하고 멋지셔서 언제나 즐거운 시간을 보내는 것 같아요, 서울 올 때 마다 마텐데 덕분에 너무 즐거운 시간 보내는 것 같네요 ㅎㅎ', 42, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '부산에서 마텐으로 오신 새로운 맴버이신 렌님께서 라이브를 하실때 미끄러지지 않도록 가져오신거라면서 재미있게 이야기를 풀어주셔서 즐거운 날이었습니다', 6, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '오늘 너무 재미있었습니당~ 거의 10번 이상 놀러온것 같은데 놀러올때마다 넘 재미있고 즐겁게 놀고 칸텐츠도 다양하고 음식도 맛있어서 놀고 갈때마다 넘 즐거워요 다음에도 놀러올께요 음식이 맛있어요', 46, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '메이드카페는 처음와봤는데 다들 너무 귀여우시고 친절하시고 분위기도 좋습니다💖💖 볶음밥에 루피도 완전 고퀄로 그려주셔서 기분좋게 먹었습니당🤤🤤 볶음밥이 귀여울뿐아니라 맛도 정말좋아요🥰', 16, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '항상 올때마다 느끼는건데 제가 갈때는 항상 바빠보이는건 기분탓일까요..?🥺 다음에는 한가하지도않고 바쁘지도않은 그런 시간타임으로 와야겠어요!!', 17, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '메이드카페를 안 와본 당신!! 인생을 손해보고 계신겁니다 ….. 항상 미소녀들과 맛있는 음식들과 함께 할 수있는 멋진 곳 입니다 ..', 15, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '오늘은 에이스테 데이라서 카운터씨와 카운터로 가서 지박령을 하고싶다는 즐거운 이야기를 하면서 웃음이 가득한 시간을 보낼 수 있습니다 다른분들도 멋지고 예쁜 코스를 하셔서 다들 보러오세요', 31, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '오랜만에 방문했습니다! 에이스테 데이라서 메이드, 집사분들께서 코스프레하시고 맞이해주셔서 즐거운 시간 보낼 수 있었습니다!! 메이드 스이님이랑 집사 노아님 진짜 잘생기셨어요', 19, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '자주 오는데 진짜 재미있어요! 메이들분들도 친절하고 음식도 엄청 맛있습니다 오시면 후회 없이 놀수 있습니다 지인들이랑 와도 재미있게 놀수 있는것같아요 오늘도 재미있게 놀고가요', 84, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '주말 연휴 끝나고 온 평일 여유롭고 자주뵙던분들을 보니까 좋아요 딸기라떼는 달달하고 너무 맛있고 체키도 매번 찍던건데 오늘 찍으니까 더 잘나오더라구여 한교동 체키는 귀하고도 귀합니다~', 16, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '메이드분들도 너무너무 친절하시구 낯가리는 편인데도 너무 편하게 말걸어주셔서 넘 좋았어용😻😻 음료두 맛나구 매장도 깨끗하고 넘 좋아요!! 처음 오시는분들도 편하게 즐기실수 있으실꺼 가타용😻♥️♥️ 다음에 또 재방문 할께요! 추천추천!!', 46, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '오늘도 메이드분들과 재밌게 대화할 수 있어서 좋았어요 이번 달에 코미님 출근이 너무 적어서 아쉬웠는데 오늘 와서 보니 너무 좋았던 거 같아요 코미님이 너무 예쁘고 귀여운 거 같아요 !', 118, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '메이드카페의 매력 중 하나는 친절하고 에너지 넘치는 서비스입니다. 메이드들은 고객에게 친절하게 다가고, 종종 특별한 퍼포먼스나 이벤트를 선보이기도 합니다. 메뉴 주문 시, 귀여운 제스처나 말을 해주며 고객을 즐겁게 해줍니다.', 2, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '메이드카페는 처음이었는데 메이드님들이 친절하시고 재밌어요! 시간가는줄 모르고 대화했어요 그리고 오므라이스가 너무 맛있어요 루리 메이드님 카나토 집사님 최고입이다😁😁😁 다음에 또 방문하고싶어요~^^', 5, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '음료수가 친절하고 집사님들 태도가 맛있네요...... 처음 와봤는데 집사웅니들 (예쁘고 멋지면 다 언니다)이 다 멋져서 신기한 경험이었습니다^^대화하기 좋아요', 50, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '비가 오면서 날씨가 많이 시원해졌는데 그래도 더위를 뚫고 오면서 즐겁게 이야기하고 재미있는 슬라임? 을 가지고 놀 수 있어서 더욱 즐거웠습니다', 87, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '스이님이 참 귀엽습니다. 진짜임 다들 대화 잘해주시고 잘 놀아주셔서 저같은 아싸도 가기 좋아요. 목 아파서 따뜻한 우유 부탁하니까 주셨어요 최고임 스이님 ㄹㅇ 진진 귀엽고 예쁘시니까 꼭 보러오세연', 33, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '항상 잘 방문하고 있습니다 .. 예쁜메이드분들이 많으시고 늘 메뉴가 맛있어요 .. 항상 친절하게 맞아주셔서 재밌게 놀다갑니다 감사합니다 … 그리고 김치볶음밥이마힛어요 굿굿', 23, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '3번째 방문이에요〰️ 항상 친절한 메이드들과 즐겁게 놀다갑니다. 오무라이스 진짜 진짜 맛있고 아망추 추천💛메이드들의 라이브도 너무 멋졌어요 또 오고 싶습니다', 35, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '마지텐시 메이드카페! 자주 가지는 않지만 한번씩 갈 때마다 아름다운 메이드분들이 맞이해주고 분위기 좋은 카페입니다. 커피도 맛있고 체키도 재밌게 찍어 주십니다.', 27, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '오랜만에 오는 곳인데도 역시 신나고 즐겁게 놀았던 것 같습니다!! 다들 너무나도 친절하시고 그만큼 즐겁게 잘 놀았어요 ㅎㅎ 다음에도 또 오겠습니다!! 파이팅!!', 3, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '갈때마다 반가운 얼굴들이 있어서 즐겁네요. 늘 반겨주셔서 감사할 따름입니다. 평일엔 사람이 많지 않아서 여유롭게 즐길 수 있어서 좋아요. 평일에 많이 놀러오시길 바랍니다.', 8, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '지인들과 자주 오는 편인데 진짜 다들 친절 하시고 음식도 맛있어요 놀러올때마다 재미있게 놀다 가요 지인들이랑 와도 이야기하기 너무 좋아요!', 86, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '파자마 데이라 메이드 분들이 너무 귀엽습니다. 이벤트 끝나기 전에 꼭 놀러오세요. 손을 꼭 씻어 질병관리에 만전을 기하도록 합시다.', 51, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '너무 자주 오는 것 같아서 4월달에는 좀 줄여야 할 것 같은 생각이 들지만 올때마다 재밌게 놀고 가서 참 좋네요ㅋㅋ오늘 히요님 생일이신데 참 아리따우시네요..보면서 눈 호강 하는 중입니다. 쓰껄하게 놀고 가겠습니다', 21, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '친구들끼리 처음 메아드 카페 와봐요 사실 항마력 딸릴까봐 조금 걱정했는데 메이드님들 말빨(?)도 너무 좋으시고 재밌으세요 부끄럼 많이 타도 다 부담스럽지 않게 말 걸어 주시니까 부담감 전혀 안가져도됨 티키타카하면 1시간 순삭임 네이버리뷰쓰고 1시간 연장 받으셈', 40, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '오늘도 자고 일어나서 집 앞에 있는 마텐 방문!! 너무 좋다 주디 히카리는 너무 이쁘고 감튀는 너무 맛있다 주디 히카리야 사랑한데이~', 46, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '이거 보여주려고 어그로 끌었다!! 사실 나x토랑은 다른 애니지만 근무하시는 분들이 같은 코스라서 생각나서 찍었습니다 오늘도 역시나 즐거운 마텐이군요 여러분도 즐기러 오세요', 49, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '메이드님께서 매장에 신고오신 신발이 신기하고 재미있어서 계속해서 보게됩니다 탐나는 신발을 발견하긴 처음인거 같습니다 어디서 구매하신거지... 알아야겠습니다', 12, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '마지텐시&데비 메이드카페 주변에서 찍은 만개한 벚꽃과 청량한 하늘처럼 해맑은 날을 메이드분들과 함께 할 수 있어서 행운이라고 생각합니다 다들 봄의 기운을 받으며 즐거운 하루를 보내세요', 47, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '메이드 카페 처음 와보는데 너무너무너무 다들 상냥하시고 ...꿈같은 행복이었어요.. 수험생의 행복을 책임지셨답니당😆 오므라이스 기대 정말 안했는데 진짜 개.. 존맛입니다. 그림도 너무 귀엽게 그려주시고.. 여기 진짜 맛집에다가 좋은 메이드 카페입니다!! 다음번에도 친구랑 오기로 했어요! 진짜 너무 꿈같은 시간이었습니다:>', 43, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '따뜻한 음료를 마시며 아리따운 미소녀들과 좋은 시간을 보냅니다... 구성도 알차서 재미있는 시간을 보낼 수 있습니다 추천합니다~!', 41, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '다들 너무 친절하시고 예쁘셔서 마음도 눈도 편안하고 행복하게 즐기다 갑니다..!!!🥰🥰 매번 한결같이 대해주셔서 좋아요!! 라이브 공연 진짜 맛도리입니다...!!!😘❤️', 17, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '단순한 카페 방문이 아니라, 판타지 세계 여행 다녀온 느낌이에요! 메이드분들의 섬세한 응대, 디테일한 세계관, 그리고 분위기까지 완벽했어요 이런 서비스는 진짜 넘 맘에 들엇어요. 완전 추천해용', 39, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '오랜만에 방문했는데 메이드분들과 집사님들의 사복을 볼 수 있는 특별한 날입니다 그렇기에 더욱 특별하고 즐거운 시간을 보낼 수 있었습니다 다음에 또 방문하겠습니다!', 48, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '오랜만에 방문하였습니다! 사복 데이여서 평소와 다른 의상을 입고 계셔서 신선한 기분으로 즐길 수 있었습니다!! 라이브도 즐거워서 빠르게 시간이 흘러갔어여', 11, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '이번에는 챠마님 보러왔어요.. ( ´ ▽ ` ).｡ｏ♡ 오늘로 4번째인데 여전히 다들 너무 이쁘시고 친절하시고 아름다우셔서.. 아주 행복합ㄴ니다.. 시간 날때마다 오는거가타요', 28, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '유메님이 귀엽고 주디님이 섹시하고 요루님이 예쁩니다. (당근 흔드는 중) 다들 친절하구여 또 오고싶어요 평일에 오니 대화도 많이 할 수 있고 즐겁습니다!!💗', 35, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '메이드쨩들 다들 귀엽고 착해요🥹 체키찍을때 무대에 있는 인형 들고 찍으면 짱 기엽고 잘나옴 여기 딸기라떼 맛집이에요 다들 딸기라떼 드세요 !!!', 65, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '간만에 왔는데 여전히 시끌시끌(좋은 의미로)하고 좋은 곳입니다. 바빠서 예전처럼 자주오진 못 하는데 시간 날때마다 들러서 좋은 에너지 받고 갑니다. 스타레일 가족들 화이팅', 40, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '비가오고 추운날이라서 매장이 따뜻해서 매우 좋습니다 마치 이 인형처럼 누워서 잠들고싶습니다 같이 즐겁게 이야기하는 마지텐시가 너무 좋습니다', 76, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '오랜만에 왔는데 사복데이라 재밌었습니당! 다들 예뿌시고 잘 놀아주셔서 즐겁게 놀았어요. 류님 진짜 완전 예쁘시고 라이브도 잘하셔서 ㄹㅇ 최고니까 꼭 꼭 보러오세요 강추드림미다!-!', 45, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '메이드분들이 너무 친절하게 잘 대해주셔서 넘 재밌었어요!! 메이드분들이 다들 이쁘고..너무 잘생기셔서..너무너무..행복했어요..!!🥺💖 다음에두 또 방문하구싶어요~!!!', 31, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '첫 마텐데 방문입니다. 유명한 메이드 카페라서 이전부터 이름은 들어봤어요. 합정역과 상수역 사이에 위치해있는데 쾌적하고 음료도 맛있어요. 메이드분들, 집사분들도 친절하셔서 즐겁게 즐겼답니다. 강추 드려요^_^', 14, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '카페에 들어서면서 느낀 첫 인상은 어땠는지, 예를 들어 조명이나 인테리어에 대해 언급해보세요. "천사 테마의 부드러운 조명이 공간을 환상적으로 만들어 주었고, 고급스러운 데코가 인상적이었다."', 20, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '색다른 컨텐츠가 다양하게있는 마지텐시데비 메이드 카페에서 즐겁게 시간을 보내면서 멋지고 귀여운 라이브와 같이 찍을 수 있는 체키 및 인생네컷으로 즐거운 추억을 만들어가세요', 32, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '다들 세라복 입으셔서 놀러왔는데 너무 귀여워서 행복했어여. 텐션이 완젼 높아서 재밌게 잘 놀아주셔서 편하게 놀고왔습니다! 오늘 츄츄님 얼굴 폼이 지려서 앙 개꿀딱스였습니다 마니 올거가타요', 12, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '지하돌분들이 계셔서 라이브가 더 신난 구성으로 되어 매장의 분위기가 더 밝고 활기차졌습니다 매번 집사님들과 메이드분들께 감사합니다', 23, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '가게에 들어가자 메이드가 상냥하게 맞아주며, “주인님(혹은 아가씨), 어서 오세요!“라고 인사했어요. 기본적으로 메이드들은 귀여운 콘셉트를 유지하며 손님들에게 친절하게 응대했어요. 주문을 할 때도 정성스럽게 설명해주었고, 음식이 나오면 직접 테이블에서 귀여운 주문(?)을 외우면서 제공해 주었어요.', 14, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '하루여신님이 1월 31일 졸업이라서 졸업 전에 시간 내서 방문했다. 하루여신님이 러블리즈 로고를 그려준 오므라이스도 먹어보고 황홀했다. 이번 설연휴에는 하루여신님을 두 번이나 볼 수 있어서 너무 럭키비키한 휴일인 것 같습니다ㅎㅎ 마텐데에서 하루여신님의 마지막 Jpop 라이브도 너무 멋져서 눈물이 날 뻔 했네요ㅋㅋㅋ 홍대는 노원이랑 너무 멀지만, 길게 쉴 수 있는 기회가 있다면 또 놀러올게요~', 2, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '한달반만에 왔는데 너무나 새로워요. 항상느끼지 만 올때마다 너무너무나^^~~힐링이 되고 후회를 하지 않아요 그리고 메이드분들 친절함은 변함없네요^^~~', 0, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '올만의 텐시 오픈타임의 방문입니다. 여기서 초코케익을 첨 먹어봤는데 심하게 달지않고 적당한 달달함으로 손이 자주 가고 약간 시큼한 메론소다로 달달함을 중화시켜서 좋습니다. 개인적으로 완전 강추!!! 아직 남아있는 귀여운 별님과의 체키찰영과 약간 시크(?)하게보이는 류집사님이 기다리고있습니다.', 37, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '마지텐시데비! 간만에 찾은 텐시 타임은 메이드분들의 높은 텐션 덕분에 오늘도 마텐에서의 시간은 너무나 즐거웠습니다! 조만간 또 놀러올게요!', 9, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '메이드카페 친구랑 처음 와보는데 예상보다 훨씬 재밌었어요 계속 있고 싶어요 맨날 오고 싶어요... ㅠ 김볶 오므라이스 너무 맛있고 케찹아트가 넘 귀여워용 // 어색해해도 말 잘 걸어주셔서 좋앗어요 ❤️❤️', 130, 20, 'GOOD', SYSTIMESTAMP);
