INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '메이드 분들은 모두 친절하고 대화도 재밌게 해주셔서 좋았어요. 음식은 기대 이상으로 맛있었고, 귀여운 플레이팅 덕분에 눈도 즐거웠습니다. 다음에도 친구랑 꼭 다시 가고 싶네요!', 39, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '늘 재밌게 놀다갑니다. 메이드들의 친절한 서비스가 좋아서 늘 다시 찾습니다 음식 맛은 무난했지만, 특별한 주문을 외우면 맛있어짐 진짜임 또 오겠습니다', 75, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '오늘부로 마지텐시데비 지지를 철회한다 오늘부터 지지관계에서 벗어나 마텐데와 나는 한몸으로 일체가 된다 마텐제에 대한 공격은 나에 대한 공격으로 간주한다 마지텐시메이드카페 나의 사랑 나의 빛 나의 어둠 나의 삶 나의 기쁨 나의 슬픔 나의 안식 나의 영혼 마지텐시데비 나...', 36, 4, NULL, SYSTIMESTAMP);
