INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '분위기가 정말 일본 느낌 그대로라 색다르고 귀여웠어요! 메이드 분들이 친절하고 게임이나 대화도 즐거웠어요. 음식도 맛있고, 체험 자체가 추억으로 남을 정도로 재밌었어요!', 11, 8, 'GOOD', SYSTIMESTAMP);
