INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '그냥 눈물줄줄흘리며 행복해하고있습니다 다들 이쁘고 잘생기시구...ㅠㅠ 하 너무 좋아요 음료는 초코라떼 추천드리고요 갠적으로 양송이 스프는 추천안함', 40, 7, 'GOOD', SYSTIMESTAMP);
