INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '처음으로 와본 메이드카페였는데 코스프레데이여서 진짜 재밌었어요!! 메이드분들이 계속 와쥬셔서 심심할 틈이 없었습니다~~~ 낯 가리는 편인데 다들 텐션도 높으시구 잘해주셔서 불편하지 않게 놀았습니다// 다음에 또 오려구요 그리고 오무라이스가 진짜 개.맛있어요', 77, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '들어오자마자 강렬하게 맞이해주는 오리 인형옷이 있습니다 놀랄 수 있지만 색다른 재미가 될 수 있어서 즐거움을 가질 수 있습니다 오늘의 스이님은 예쁘십니다', 2, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '미하 집사님 귀여워요🤤 최고의 집사!! 인생의 집사!! 다른 메이드님들도 전부 친절하고 귀여워용ㅎㅎ 매일매일 오고 싶은 기분입니다…❣️', 23, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '리카온 이라는 메이드/집사 분이 너무 재밌고 체키 꾸미는 게 남달라요 너무 잘생기고 친절하시고 얘기하는게 너무 재밌어서 시간 가는 줄 몰랐네요 요즘 인생이 힘들었는데 덕분에 힘을 얻어 갑니다 세상에 이런 곳이 있다는게 얼마나 복지고 행복인지 다시한번 주님께 감사드립니다', 70, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '색다르고 재미있는 경험이었어요. 메이드분들이 “주인님~”이라고 반겨줘서 조금 민망했지만 금방 분위기에 적응했습니다 오므라이스에 직접 그림도 그려주시고, 간단한 게임도 즐길 수 있어서 좋았어요. 음식도 괜찮았고, 전반적으로 유쾌한 시간이었습니다!', 1, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '진~~~~짜 다시 올생각이 없었는데도 다시오게 만드는 마성의 메이드카페에요!! 한번 와보시면 알거에요!! 매력 넘치시는 분들이라 다시 올 수 밖에 없음을!!', 21, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '메이드들이 너무 귀엽고 착해요 계속 와주면서 대화해줘서 시간이 눈 깜짝 할 새 지나갔어요 이러다 단골 될 거 같아요 ㅋㅋㅋ 다음에는 데비 타임도 한번 와볼 생각이에요!! 이런 메이드 카페는 처음인데 뉴비에게도 추천해요!!', 29, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '다시 재방문 했습니다 아주아주 맘에 들어요 특히나 메이드들이 너무 잘해줘서 뭔가 이것저것 부탁하기가 미안할정도 분위기도 좋고 메이드들도 좋고 또 다시 자주 올거같은 그런 메이드카페 입니다 개추개추👍', 46, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '마지텐시에 벌써 세 번째 방문이다. 처음 그 신비로운 분위기에 반해서 갔던 기억이 아직도 생생한데, 이제는 익숙한 공간이 되었다. 하지만 매번 올 때마다 새롭다 이번에는 양송이 수프를 주문했다. 맛있다', 33, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '만우절 기념으로 파자마 입으셔서 방문했는데 다들 텐션도 진짜 높고 잘 놀아주셔서 재밌게 놀아주셔서 잘 즐기다가 왔습니다. 류님이 너무 예쁘셔서 행볻했어요 다들 많이 놀라오십쇼 ㅅㅅ', 1, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '메이드님집사님들이너무너무아름답고친절하세요 딸기라떼가 특히 맛있습니당 메이드카페 처음 와 봐서 어색할까봐 걱정했는데 너무 재밌고 시간이 너무빨리가요🥹🥹', 76, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '카페 내부는 아기자기한 인테리어로 꾸며져 있으며, 직원들은 메이드복을 입고 고객을 맞이합니다. 일반적인 카페와는 다른 귀여운 분위기로, 고객은 마치 애니메이션 세계에 와 있는 듯한 기분을 느낄 수 있습니다.', 126, 19, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '일상에 새로운 경험을 할 수 있는 즐거운 경험이었습니다 쵸님께서 마지텐시로 오셔서 더욱 즐겁고 활기찬 분위기가 될거같습니다 앞으로도 오래 보면서 신나는 나날이 되기를 바랍니다', 30, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '오랜만에 와서 조금 낯설었지만 반갑게 맞이해주시는 메이드분들이 친절하다. 오므라이스도 정말 맛있기 때문에 안 오신 분들은 꼭 한번 오시길 바란다', 17, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '매장안에 인생네컷을 찍을 수 있는 기계가 있어서 매우 합리적인 가격에 원하는 메이드분들이나 집사분들과 찍을 수 있습니다 매우 행복한 추억을 만들어 가실 수 있으니 추천합니다', 83, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '예쁜 메이드분들과 신나는 시간을 보내고 싶다? 그럼 무조건 마지 텐시 데비로 놀러와야죠! 오늘도 메이드분들 덕분에 하루의 스트레스 잘 날리고 갑니다ㅎㅎ', 28, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '메이드카페의 매력 중 하나는 친절하고 에너지 넘치는 서비스입니다. 메이드들은 고객에게 친절하게 다가고, 종종 특별한 퍼포먼스나 이벤트를 선보이기도 합니다. 메뉴 주문 시, 귀여운 제스처나 말을 해주며 고객을 즐겁게 해줍니다.', 8, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '처음 방문했을 때 메이드분들이 친절하게 맞아주셔서 긴장이 풀렸어요. 분위기도 따뜻하고 편안했습니다. 가격도 부담스럽지 않고, 메이드분들이 친근하게 대해주셔서 정말 좋았어요. 특히 테루님 반응이 정말 최고입니다.', 68, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '항상 방문할때마다 즐거운 시간을 보낼 수 있어서 행복합니다 웃음이 끊이지않는 밝은 분위기와 예쁜 인형들이 많은 마지텐시&데비에서 메이드분들과 집사분들과 재미있는 시간을 보내도록하세요', 19, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '오늘도 잔잔하게 메이드와 함께하는 데빌타임이 너무좋습니다 무드있네요 ! 가볍게 놀기 너무 좋아요 ㅎㅎ 여기 메이드분들 다들 말잘 걸어주시고 이야기 하기 좋아요! 외롭지않게 잘 놀아주셔서 즐거운 시간 됬습니다 감사합니당 브이~ V', 20, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '모두 친절하고 대화도 많이 하는데 재미가 있어서 시간 가는줄 모르고 지내요 음식도 맛있고 메뉴도 다양해서 놀러와서 먹고 놀다가 가기 편하고 좋아요 컨텐츠도 다양하고 게임도 하기에 강추 합니다 분위기도 밝고 깨끗한 느낌이라 마음도 편해요', 22, 1, 'GOOD', SYSTIMESTAMP);
