INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '3일 연속으로 마텐도 너무 행복하고 연속 라이브 3개도 너무 귀엽ㄱ구 ,, 처음보는 분들도 많고 손님도 많고 분위기도 좋고,, 음료도 마싯고,, 이렇게 좋은 메캎 어디 없으니까 빨리오세여', 65, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '오늘은 양지뢰데이로 각자 생각하시는 양지뢰의 모습을 볼 수 있으면서 서로의 개성이 드러납니다 메이드복도 좋지만 이런 특별한날이 있어서 새로운 컨텐츠로 즐거움을 얻을 수 있습니다 특히 스이님이 정말 귀엽고 예쁘십니다', 62, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '한국 메이드 카페는 처음 와봤는데 주변 메이드 분들이 말 많이 걸어주셔서 심심할 틈이 없어서 좋았습니다 ㅎㅎ 리뷰 쓰면 시간연장도 할 수 있어서 좋고 생각보다 가격도 저렴했습니다', 41, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '처음 놀러왔는데 주디가 섹시하대요ㅋㅋㅋㅋ 재밌어요 이색체험으로 추천해여 말도 많이 걸어주시고 즐길 마음만 들고 오시면 정말 재밌게 놀 수 있습니다 시간 엄청 빨리 가요 저도 연장 중입니다', 17, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '오늘은 스페셜 게스트가 오셔서 더욱 북적거리면서도 바쁜 시간이었습니다 그래도 평소와는 다른 매장의 모습을 보면서 즐거움이 배가 되는 시간이었습니다', 22, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '오랜만에 심심해서 마텐데에 방문 히카리는 역시 이뻤고 사이다는 맛있다. 히카리야 주디야 졸업하지 말고 평생 메카판에 남아줘!!!', 60, 12, 'GOOD', SYSTIMESTAMP);
