INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '오늘도 미즈님 보러 왔는데 변치않고 너무 아름다웠습니다. 사복 패션 센스가 뛰어나서 귀여움도 더 부각되는거 같습니다.  저번엔 휴식시간이랑 겹쳐서 이야기를 많이 못했는데 이번엔 엄청 이야기해서 너무 즐거웠어요.', 2, 9, 'GOOD', SYSTIMESTAMP);
