INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '오늘은 금요일 데빌타임이있는날 5시까지 하니까 새벽에 놀다가 잠시 들러서 쉬었다 가는건 어떨지??? 메이드&집사분들 많이 있으니까 대화하기도 좋고 재미있게 부담없이 즐길수있습니다. 놀러오세요 ㅇㅅㅇ', 108, 22, 'GOOD', SYSTIMESTAMP);
