INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '키드 집사님이 그림 그려주셨는데 솔직히 별 생각 없었는데 너무 잘 그려주셔서 좋았어요 ㅠㅠ 그리고 다른 메이드분들도 너무 친절하세요 어제 기분이 너무 안좋았는데 여기 오니까 많이 풀려요 😊 다음에 또 올께요 감사합니다 ㅎㅎ', 47, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '서울 온 김에 꼭 가보고싶었던 곳이라 마지텐시 방문했는데 다들 너무 친절해서 재밌게 놀았어요🥺 라이브도 봤는데 다들 너무 예쁘시고 춤도 너무 잘추셔서 깜짝 놀랐어요! 테이블도 많아 이용하기 좋아요! +초코라떼 맛있으니 꼭 드셔용!', 38, 10, 'GOOD', SYSTIMESTAMP);
