INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '마지텐시 처음으로 와봤는데 컨셉도 엄청 독특하고 재미있어요!!! 무엇보다 스이나 비비가 엄청 예쁘고 친절해서 시간 가는 줄 모르고 있었네요..😆 최고에요!!', 22, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '오랜만에 방문한 거 같은데 즐거운 시간 보낸 거 같아요 오늘 출근하신 메이드분들도 많아서 메이드들과 대화를 많이 할 수 있어서 좋았던 거 같아요 :) 코미님은 언제 봐도 귀엽고 예쁘신 거 같아요 !', 16, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), 'マジ天使 메이드 카페에 처음 방문한 사람입니다. 메이드들이 친절하고 재밌는 사람이 가득한 곳입니다. 다음에 또 방문하고 싶을 정도로 아늑하고 편안한 곳이었습니다. 🙂🙂 한번도 방문한 경험이 없으시다면 오시는걸 추천드려요 ^^7', 12, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '너무 재밌게 놀고 가서 기억에 남을 것 같아요 한번씩 오면 좋을 것 같아요. 애니를 사랑하는 사람이라면 한번쯤 와서 놀고 가면 좋을 것 같아요 너무 재밌는 경험이었던 것 같아요 이런 문화가 생기면 많은 사람이 올 것 같아요 감사합니다^^', 72, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '재미있게 즐기고 행복한 추억을 남기고 왔습니다 시선에 따라 별로 안좋아 하실분들도 많겠지만 즐겁고 편안한 분위기에서 재미있게 즐기고 왔습니다>.<', 3, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '메이드분들이 친절하시고 매장분위기가 좋아요 아메리카노 양이 많아서 좋아요 김치볶음밥이랑 메론소다가 유명하다고 그래서 다음에 오면 먹어보려고요', 13, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '오늘도 방믄해서 즐거웠습니다 오늘 마텐 덕분에 즐거운 일조 많고 즐거운 추억도 많이 생겨서 너무 즐거운 하루였습니다 이 즐거운 추억을 가지고 또 다른 날에도 방문하겠습니다', 310, 66, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '오늘 생일이였어 한번 들렸는데 메이드분들이 친절하게 알려 주시고 생일축하 노래도 불러주셔서 너무 행복한 생일이 된거같은 그런 느낌적인 확신이 듭니다~재미있었어요~!!', 28, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '오늘 우연히 왔는데 호스트부 코스프레 하고계셔서 신기하고 귀여우셨어요 다들 대화도 잘해주시구 재밌게 놀아주셔서 행복한 시간 보냈습니다 특히 로쿠님이 쌈@뽕하게 해주셔서 앙기모링 했습니다', 105, 19, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '카페 내부는 아기자기한 인테리어로 꾸며져 있으며, 직원들은 메이드복을 입고 고객을 맞이합니다. 일반적인 카페와는 다른 귀여운 분위기로, 고객은 마치 애니메이션 세계에 와 있는 듯한 기분을 느낄 수 있습니다.', 44, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '일상에 지친 마음을 달래러 메이드카페에 다녀왔어요. 메이드분들이 정말 친절하시고, 카페 분위기도 아늑해서 힐링되는 시간이었어요. 특히 음료에 귀여운 데코까지 해주시니 기분이 절로 좋아지더라고요. 다음엔 친구랑 꼭 다시 방문할 예정이에요!', 18, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '메이드들이 1분1초도 심심치 않게 해줘서 연장까지 해버리게 됐네요 ㅋㅋㅋ 일단 메이드들이 너무 귀여워서 입장할때부터 너무 설레는 마음이였어요!! 라이브까진 구매할 생각 없었는데 다른 손님분이 라이브 한거 보고 이건 무조건 해야겠다싶어서 저도 홀린듯 구매해버렸어요!! 다음에는 데비타임으로 올게요!!', 67, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '시요님 나를보자마자라이브할수있게되서 기뻐하셨다 발렌타인 나는솔로라서기대안했는데 선물까지 시요+메이님께셔서 라이브세트를주문할수 있었다ㅎㅎ', 42, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '감튀도 맛있고 칵테일도 맛있어요!! 칵테일 잘 몰라서 물어봤는데 설명도 잘해주구 추천해줘서 맛있는걸로 먹었어요♥ 그리고 메이드님들이 너무 잘 놀아줘서 좋아요//', 48, 8, 'GOOD', SYSTIMESTAMP);
