INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '언제 와도 마음 편하게 이야기 나누고 스트레스 풀고 갈 수 있는 곳이에요 그냥 있으면 편해지고 얘기하다보면 즐거워지는 곳이에요 그래서 더 자주 놀러오게 되는 것 같네요', 10, 0, 'GOOD', SYSTIMESTAMP);
