INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '메이드분들 다 너무너무 친절하시고 음료도 맛있고 라이브 관람하기 최고였어요!! 저는 갸루 데이에 다녀왔는데 다들 갸루 너무 잘 어울리시고 예쁘고 귀엽고 친절해요 ㅠㅠ 재방문의사 100%', 83, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '초코라떼가 맛있습니다 단오시라 다른 메이드분들은 잘 기억 못해드렸는데 그래도 다들 착하셔서 자주 와서 놀아주셨어요 낯 가리시는 분들도 오시면 대화하기 좋으실거에요', 6, 2, 'GOOD', SYSTIMESTAMP);
