INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '다들 너무 친절하시고 아름다우셔서 너무 만족스러웠습니다!! 재방문 의사 완전 가득! 라이브도 너무 잘해주시고 너무 최고였어요💕', 214, 77, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '두번째 방문이었는데 메이드분들이 잘해주시고 말도 많이 걸어주셔서 재미있게 놀았습니다 !! 그리고 체키도 예쁘게 꾸며주셔서 기분좋게 놀다나왔습니다 !! 다음에 또 방문하겠습니당 🤍🤍🤍🤍 메이드분들이 너무 예뻐요 ... 🤍🤍🤍🤍🤍🤤', 66, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '2일 연속... 일정이 붕 떠서 재방문! 늘 친절하게 맞아주셔서 진짜 좋습니다. 항상 즐겁게 얘기해주셔서 나름의 행복감을 충전하고 갑니다. 초코 파르페가 맛있어요.', 58, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '서울 올 일이 있어서 볼일 보고나서 돌아가기 전에 애매하게 남은 시간을 보내기위해 와봤습니다. 다른 메이드카페와 맛있어지는 주문이 특이한게 재미있고, 컨셉의 특성상 시간을 잘 맞추어가면 하루에 두가지 컨셉을 즐길수 있다는것도 재미있습니다!', 104, 21, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '오늘은 초코라떼가 끌려서 시켰지만 맛있으면서 메이드분들이 예쁘시지만 데비복장이 어울려서 매우 예쁘십니다 미하님이 정말 예쁘시고 복장이 본인의 스타일에 맞게 너무 잘 어울리십니다', 42, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '어쩌다보니 2번째 오게되었는데 여전히 좋네요! 오늘은 데비데이라고 하셔서 다들 악마컨셉같은 걸로 하고 계셨어요! 미하씨가 가지고 다니던 가방에 대해서 듣기도 하고 여러가지 이야기를 들었는데 꽤나 즐거웠어요~ 초코파르페 맛있네요 아마 바닐라 시리얼 바닐라 크림?순이라 호다닥 먹어야하긴해요', 47, 10, 'GOOD', SYSTIMESTAMP);
