INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '지인분과 재미있게 즐기고 왔습니다 요번이 2번째 방문 이였는데 오늘은 메이드 분들이 많아서 더 즐거웠던거 같습니다 메이드 분들 모두 친절하고 귀엽습니다 👍', 43, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '가야지 가야지 하고 있었는데 마침내 갈 기회가 되서 갔더니 예상했던 것보다 메이드 친구들도 친절하고 라이브 공연도 즐겁고 무엇보다도 손님 니즈 파악이 확실한게 좋습니다 다른 분들에게도 추천👍', 36, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '메이드분들 다들 너무 친절하시고 귀여우심 .. 초코 파르페 예쁘고 마싯어요 매장도 청결해서 오래있기에도 넘 조아요 * 메이드 류 넘 이쁨', 106, 22, 'GOOD', SYSTIMESTAMP);
