INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '메이드카페 라는 곳을 처음 와보는데요, 입장 후 분위기에 놀랐지만, 자리에 앉고 나서 메이드분들이 친절하고 밝게 재밌게 얘기해주셔서 긴장도 많이 없어지고 즐거웠어요. 너무너무 만족스럽고 즐거운 경험이었습니다. 그리고 음식 겁나맛있네요', 64, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '오랜만에 방문했는데도 어색하지 않은 친정집같은 편안함이 있는 곳입니다. 늘 느끼지만 주방 이모님이 아름다우시고 디저트가 맛있습니다. 다음에도 또 방문할 것 같습니다.', 72, 17, 'GOOD', SYSTIMESTAMP);
