INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '지방에서도 자꾸만 올라오게 만드는 마텐데의 매력 홍대에 그 많은 메이드카페들이 있지만 영원히 여기만 와요 내 사랑들이 다 여깄으니까♡', 83, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '카페인데 칵테일을 왜이리 잘말죠… 너무 맛있어요 다들 친절하셔서 늘 기분좋게 있다가 갑니당.. 혼자와도 재밌어요.. 그리구 메이드님이 너무 예뻐요..♥ 라이브도 진짜 최고 완전 짱임 대박임', 69, 14, 'GOOD', SYSTIMESTAMP);
