INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '한국의 메이드카페는 독특한 분위기와 특별한 서비스를 제공하는 장소로, 많은 사람들에게 이색적인 경험을 선사합니다. 주로 젊은 층과 일본 문화 팬들 사이에서 인기가 많습니다.', 83, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '아메리카노가 맛있고 메이드가 귀여워요 집사들이 잘생겼고 모두가 달려와서 그림도 그려줘요 대박 오늘 혼자서 놀러왔는데 얼굴구경이 넘 재밌어요 다음에 놀러오면 라이브를 시켜야겠어요 수리님 잘생겼어요 소녀가 되...', 12, 7, 'GOOD', SYSTIMESTAMP);
