INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '꼭 보고 싶은 곡이 있어서 메이드에게 신청곡으로 부탁했는데 너무 고퀄리티로 준비해줘서 행복했습니다. 린코 메이드 라이브도 잘하고 좋아해서 강추합니다!', 48, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '재방문인데 다들 기억해 주시고 너무 즐겁습니다. 메이드분들이 다들 친절하시고 인테리어도 너무 이뻐서 또 오게 됐어요ㅎㅎ 너무 좋습니다', 23, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '오늘은 츠바키, 키치, 시우, 로쿠, 시요, 유아, 몽슬님이 놀아주셨는데 너무 재밌었어요~ 오늘은 손님이 별로 없으셔서 직원분들이랑 대화 열심히 했네요! 음식도 맛있고 분위기도 편한해서 잘 즐기다 갑니다 ㅎㅎㅎ 많이 방문해서 촛불 같은것도 받았네요 다들 한 번씩 방문해보셔도 좋을듯합니다! 다음에 또 방문할게요! 그리고 몽슬이가 이쁘도 유아도 이뻐요!! 다들 많이 놀러와서 즐고보세요~~~~', 77, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '츠바키님 보려구 방문했어요.. (•̀ᴗ•́)و 김치볶음밥이 새로 생겼길래 먹어봤는데 너무 맛있었어요!!! 시간이 안돼서 많이 못 오는데 시간 날때마다 올게요.. ( ´ ▽ ` ).｡ｏ♡', 45, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '올때마다 후회한 적 한 번도 없습니다....🥹 메이드카페 오직 마텐데만 와요...♡ 메이드분들도 집사분들도 너무너무 예쁘고 잘생겼어요 다들 친절하시고 집 갈때마다 그냥 여기서 살고싶어요 진짜돈만있으면맨날올텐데', 68, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '친구의 소개로 첫 방문 했지만 지금은 거의 매주 방문하고 있는 마지텐시, 리뷰보고 방문하는 사람이 많아지면 제 자리가 줄어들 것 같아 두렵지만 혼자 알기엔 아까운 곳입니다. 특히 파르페는 명물이니 꼭 드셔보시기 바랍니다.', 45, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '자주 오는데 음료가 엄청 맛있고 혼자 오기도 괜찮아요 컨텐츠도 많고 오늘 코스데이인데 다들 잘어울리시고 매번 친절하세요 특히 유리님 최고', 37, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '오늘도 즐겁게 즐겼습니다! 코스프레 데이라 다양한 모습도 많이 보고 재밌게 해주셔서 잘 즐기다가 왔습니다. 힐링 조아요~ 다음에도 또 오고싶네요 마니 오세요', 12, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '낮타이과 밤타임 다르다고 해서 궁금함에 밤타임 재방문 했습니다.. 음료도 맛있고 직원분들 모두 너무 귀엽고 친절하세요..! 즐거운 시간이었습니다!', 13, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '오늘도 시간이 나서 방문했는데, 친절한 메이드분들 덕분에  재밌게 시간 보내고 갑니다. 그리고 오늘 미트볼 메뉴도 처음 주문했는데, 상당히 맛있습니다. 다른 방문자분들께도 추천 드립니다.', 87, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '오늘 너무 재미있었습니당~ 거의 10번 이상 놀러온것 같은데 놀러올때마다 넘 재미있고 즐겁게 놀고 칸텐츠도 다양하고 음식도 맛있어서 놀고 갈때마다 넘 즐거워요 다음에도 놀러올께요', 23, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '천국에 온 듯.. 너무 귀엽구 예쁘고 멋진 집사 메이드가 가득!! 편안하고 귀여운 분위기에 다들 대화도 너무 잘하시고 공연도 최고였습니다!! 오므라이스(ver. 김볶밥 / 김볶밥이 정말 맛있어요!!)과 블루소다가 너무너무 맛있고..  오므라이스 케챱 아트가 끝내줍니다😍😍🥰 다들 해피에너지 가득 채워가세요~~', 18, 0, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '늘 친절하게 맞아주셔서 좋은거 같아요. 일정 끝나고나, 퇴근하고 쉴 겸 놀 겸 편하게 들어오기 편해요. 메뉴들도 다 맛있습니다. 김치볶음밥 진짜 추천입니다.', 38, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '마텐 진짜 재미있고 쵸라는 사람도 진짜 재미있고 담음에 오면 메이드분들이 재미있고 진짜 메이드분들 자체 잘생기고 이뻐서 너무 조아여', 68, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '마지텐시 재밌어요 다들 친절하고 재밌게 잘해주는데 사키님 예뻐요 사키님 재밌어요 친절하세요 같이 놀면 시간 가는 줄 모르고 재밌게 놀 수 있어서 너무 좋아요 자주 오세요 여러분', 29, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '메이드 카페는 처음 방문했는데 다들 친절하시고 분위기도 편한 분위기라서 너무 좋았어요! 처음이라 살짝 긴장했는데 너무 편안하게 대해주셔서 힐링하고 갔어요! 무엇보다 넘 예쁘십니다!', 5, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '메이드 카페는 첫 방문이었는데 수많은 온나노코들이 반겨주셔서 너무 행복했어요 소심해서 말을 잘 못했는데 분위기도 빨리 풀어주시고 입시 상담도 해주셨어요완전 추천합니당', 27, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '츠바키 폼미 나 미쳐 츠바키 폼미 나 미쳐 츠바키 폼미 나 미쳐 츠바키 폼미 나 미쳐 츠바키 폼미 나 미쳐 츠바키 폼미 나 미쳐 츠바키 폼미 나 미쳐 츠바키 폼미 나 미쳐 츠바키 폼미 나 미쳐 츠바키 폼미 나 미쳐 츠바키 폼미 나 미쳐', 28, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '메이드가 친절하고, 음식이 맛있으며, 체키도 예쁘게 찍어주고, 편지도 가슴 설레게 매우 잘 써주신 답니다. 또, 규정상 못 찍었지만 라이브가 굉장해요~.', 13, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '세라복 데이에 방문했습니다! 메이드분들 한분 한분 컨셉이 다르고 확실해서 질리지 않고 재미있어요. 심심하지 않게 말도 잘 걸어주시고 특별의상 입는 날 방문하시면 좋은 것 같아요👍👍', 11, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '평일치고 상당히 혼잡한 날이네요... 그만큼 이 메이드카페가 재밌다는 얘기겠죠?? 딸기라떼 주문했는데 우유보다 딸기 시럽이 더 많더라구요. 달달한 음료 좋아하시는 분께 추천드려요', 23, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '예약 없이 바로 입장했는데 너무 친절하게 잘 설명해주셔서 좋았어요 (´▽`ʃƪ)♡  라이브도 너무 훌륭했어요 초코 파르페도 너무 맛있었구요 다음에 꼭 또 올게요!!!', 50, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '정말 귀여우십니다. 친절하게 말도 붙여주시고, 정말 너무 아리따우셔요. 첫 메이드카페 탐방이었는데, 다음에 또 와야겠어요... 감사합니다!!!🐢🐢💖', 19, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '맛있어요 홍대 부근 제일 맛집 이만큼 맛있는 맛집은 없다 웨이팅 없이 들어왔는데 한 시간 기다려도 안 아까운 맛 ㅠㅠ 담에 꼭 남친이랑 오고시퍼용 ㅠ', 35, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '인생네컷 기계가 실내에 있어서 밖에 나가지 않아도 되고 컨텐츠 비용이 그만큼 싸서 좋습니다 메이드분들과 집사분들도 많으셔서 여러가지 취향의 메이드를 만나볼 수 있었습니다', 23, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '처음 들어올때 수치스러웠는데 메이드분들이 명함도 써주시고 모두 너무 잘 대해주셔서 잘 즐기고있습니다 파르페와 음료도 너무 맛있고 서비스도 좋은거같습니다 다음에 기회가 된다면 재방문 하고싶습니다~', 21, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '음식과 음료가 맛있고 메이드 분들이 친절해서 좋고 다음에도 오고싶게 만드는 그런 곳입니다 천의 왔는데도 요루 히요 스이 샤샤 루이님 전부 잘 설명해주시고 친절해서 좋아요', 10, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '오랸만에 오는 마지텐시 ㅇㅅㅇ 평일이라서 자리도 넉넉하고 메이드복보다는 특의가 더 많은 메카라서 더 오는걸 추천함. 소소하게 바뀐것도 있고 졸옵하신분들도 많고 새로오신분들도 많으니까 마니 놀러오세요.', 6, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '오늘은 쵸님 로쿠님 로제님 루이님 렌님께서 에일리언 스테이지 코스프레를 단체로 해주셨습니다. 메뉴도 맛있었고 재미있게 놀다 갑니다.', 9, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '미즈님이 귀엽고 친절하세요 미즈님 보러 다시 올 거 같아요 체키 엄청 잘 꾸미셔서 사진 찍는 거 좋아하신다면 미즈님이랑 체키 찍어봐도 좋을 것 같아요. 항상 응원하니다 화이팅!', 70, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '설연휴라 하루여신님이랑 네포님 보러 들렸는데, 너무 즐겁게 놀다 갑니다ㅎㅎ 메론소다도 맛있었고 시요님이랑 아이님, 우기님도 정말 예쁘시고 잘 놀아주셔서 너무 즐거웠습니다. 한복 코스프레도 다들 너무 잘 어울리셔서 놀랐습니다~', 25, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '늘 재밌는 경험 만들어줘서 고마워요. 예쁘고 귀여운 메이드분들이 친절하게 응대해주고 음식도 맛있어서 만족스러운 시간 보내고 갑니다', 76, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '딸기라떼에 들어가는 시럽이 다른걸로 바뀌어서 꾸덕하게 맛있어졌습니다 전에도 맛있었지만 바뀐 지금도 다른 맛으로 맛있습니다 그리고 역시나 말하지만 메이드분들과 집사님들이 예쁘고 멋지십니다', 83, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '기존에 다니던 메이드카페 직원분의 소개로 처음 오게 되었어요. 기존에 다니던 메이드 카페랑은 좀 분위기가 많이 다르기는한데 메이드분들께서 너무 친절하시고 밝은 분들이 많아서 많이 웃을수 있었어요. 요즘 우울한 마음도 있고 그랬는데 메이드분들의 웃음을 보고 힐링하고 갑니다. 앞으로도 이 카페 잘 되었으면해요. 응원합니당', 22, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '처음와본 메이드 카페.... 좀 정신없고 기빨리지만.... 다들 친절하시고 예쁘셔서 나름 힐링되는곳!!!!! 오늘 만난 어여쁜 스이님도... 친절하신 메이님도.... 멋쟁이 노아님도.... 이름처럼 반짝반짝하신 별(STAR)님도... 그리고...멋진? 예쁜? 명월님도!!! 오늘 너무 즐거웠습니당!!! 기회가 되면 다시 방문할게요 그때까지 모두 즐거운일만 가득하시길!!!!', 0, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '오늘은 텐시타임과 데비타임을 둘 다 즐겼는데, 너무 재밌네요 ! 데비때 메이드분들이 반말 써주시는게 은근 킥인거 같아요ㅋㅋㄹㅎㄹㅋ (탁자에 있는 포켓몬 카드는 나도 왜 있는지 몰루...) 생각보다 재밌어서 앞으로도 방문 많이 할거같아요! 데비때 시요메이드님을 뵀는데 너무 이쁘심..♡', 106, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '오늘은 예상보다 바쁠 것 같아서 예약 후 방문했습니다. 항상 친절하게 맞이해 준 메이드님들 덕분에 좋은 기억을 갖고 있습니다. 오늘 주문한 음식(아쉽게도 먹느라 사진 못 찍었습니다.)도 맛있게 잘 먹었습니다. 항상 올때마다 만족합니다.ㅎㅎ', 8, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '한복데이가 얼마 안남음.. 매장이 사람이 많거나 예약이 많으면 네이저 리뷰이벤트가 불가능할수도있다는걸. 간단하게 드실수있는 메뉴로 시작하고 체키 한장정도 하면 딱 기분좋게 이용하고 갈수있습니다. 모두 라이브 잘하니까 보러오세요.', 52, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '서울 모지텐시 메이드카페! 너무 좋아요! 메이드 체키님과 함께 얘기도 하고 재밌는 시간 가져서 좋아용! 연인과 함께와도 재밌습니다 ㅎㅎ 모지텐시 메이드카페 추천드립니다!!', 35, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '다들 너무 친절하시두 귀엽고 아름다우셔서 행복한 시간 보낼수 잇엇어요…>_<♡ 시간만 된다면 365일 오고 싶은 곳 라이브도 즐거웟구 체키찍은 것도 넘 귀여워요 좋은 시간 보낼 수 잇게 해주신 모든 메이드님들께 감사합니다✨💕', 31, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '오래간만에 오는 마텐데!! 오랜만에 와도 너무 반겨주시고 즐거운 곳인거 같아요 ㅎㅎ 덕분에 잘 놀다가 갑니다!! 다음에 또 올게요!! 마텐데 파이팅!!', 18, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '메이드가 예쁘고 음식이 맛있어요 라이브가 너무너무 재밌어요 그리고 슈와가 귀여워요 눈치도 빨라서 알아서 잘해 줘요 칵테일도 맛있습니다', 46, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '오늘 시간 한가해서 메이드 카페 놀러왔습니다. 메이드분들도 다들 친절하시고 음식이랑 음료수도 맛있고 재밌게 놀다가요 다음에 또 시간 나면 놀러 오고 싶네요', 123, 26, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '몇번째 방문인지 모르겠지만 올때마다 꿀잼임ㅋㅋㅋㅋㅋ 메이드분들도 잘 놀아주세요! 항상 아쉽지 않게 놀다가요! 늘 재미있게 놀아 주시는 메이드 분들 감사해요! 츠바키는 진짜 여신님 이심...ㅠㅠ', 85, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '메이드분들 다 너무 귀엽고 이쁘고… 암튼 좋아요 얼굴이 맛있고 음식이 친절해요 시험기간이라 이제 한동안 못 와서 아쉬워요 ㅠㅠ', 49, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '진짜 재미있고 재미있고 그양 재미상 가보는것도 좋고요 추억으로 가는것도 좋고요 메이드분들 착하고요 재미있고요 시간 때우기 좋음요.', 10, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '메이드분들 모두 친절하시구 이쁘세요😍❤️🤍👍🏻 마법의 주문도 재밌게 외쳤구 들어오자마자 기억에 남는 환영인사도 너무 좋았어용!!! 다음에두 꼭 오겠습니닷👍🏻👍🏻', 1, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '메이드카페에 왔습니다 메이드분들 집사님 다 예쁘시고 친절해서 편하게 놀다 갑니다 가볍게 와서 커피 한잔하기에 너무 좋은거 같아요!!', 90, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '메이드분들 너무 이쁘세여… 다 친절하시구 음식도 진짜 맛있어요ㅜㅠ 여기서 찍은사진들 집에서 매일매일보고있는데 볼때마다 행복한것… 메이드 좋아하시면 꼭 오세요❤️❤️', 26, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '오늘 마텐데에서 유리, 쵸리, 메이 메이드님 그리고 로쿠, 노아, 미하, 키드 집사님들이 너무 잘 놀아주셔서 감사했어요 ! 오늘 눈이 오는데도 불구하고, 사람이 엄청 많아서 너무 재밌었어요! 한복데이라 좀 보기힘든 그림들을 볼 수 있었어요 ! 이왕 오실거면 한복데이 때, 방문하는걸 추천드려요 !', 49, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '메이드들 너무 다 이쁘고 즐거워요! 같이 대화하느라 시간이 훅훅 지나갑니다...! 메이드들 라이브도 너무 좋고 웃는게 다들 이뻐요! 웃게 만들어드리는 손님 되고싶습니다! ㅎㅎ 이뻐요~!', 90, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '오늘의 메뉴는 오무라이스~ 스크램블 에그에 토치로 구운 맛있는 김치볶음밥~ 중독되는 볶음밥이네요 술도 취하진 않지만 메론하이볼 먹으려다 내일 일한다고 검거당해서 술도 단속해주는 친절하고 상냥한 집사,메이드분들~ 다음에는 뭘 먹을까 고민합니다', 24, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '따뜻하구 분위기도 좋아요!! 오므라이스계란이 부드럽고말랑해서 맛있구 음료도 맛있습니당! 라이브쇼도 잘 봤어요 텐시타임데비타임 다른 매력이 있어서 좋아용', 108, 19, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '메이드카페는 처음이었는데 집사 분들이랑 메이드 분들이 친절하게 대해주셔서 덕분에 잘 놀다갑니다💗 체키 찍고 게임하고 라이브 구경하다가 몇시간이 후딱 지나가서 놀랐어요ㅋㅋ 가게에 있는 인생네컷 사진 진짜 잘나와요 꼭 이용해보세요 (완전추천!!!) 그리고 김치볶음밥과 초코케이크가 진짜 맛있습니다... 🤤🤤🤤', 118, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '여기는 초보자가 오기에는 괜찮은 곳이에요 짜파게티도 맛있고 간편하게 콜라 한잔만 시켜서 분위기만 보러오셔도되고 메이드 분들도 방치 없이 잘 돌아다녀주고 대화도 재밌게 해주니까 메카체험을 허고싶다 하시면 부담없이 왔다가 가셔도 됩니다.', 85, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '세라복 츠바키는 진리야 세라복 츠바키는 진리야 세라복 츠바키는 진리야 세라복 츠바키는 진리야 세라복 츠바키는 진리야 세라복 츠바키는 진리야 세라복 츠바키는 진리야 세라복 츠바키는 진리야 세라복 츠바키는 진리야 세라복 츠바키는 진리야', 46, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '키드님이 오늘 졸업이라서 많이 슬프지만 정이 들었던만큼 즐겁고 소중한 추억을 가져갈 수 있어서 웃으며 마지막을 보내줄 수 있어 다행이라고 생각합니다 앞으로 밝고 행복한 나날이 가득하길 바라며 다음에 만나게 되어도 웃으며 볼 수 있기를 바랍니다', 57, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '일정 다 끝내고 편하게 놀러오기 좋아요! 늘 재밌게 웃다가 집에 가는거 같아서 좋습니다. 메뉴들도 맛있어서 간식 먹기도 좋아요!', 40, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '오늘 너무 재미있었습니당~ 거의 10번 이상 놀러온것 같은데 놀러올때마다 넘 재미있고 즐겁게 놀고 칸텐츠도 다양하고 음식도 맛있어서 놀고 갈때마다 넘 즐거워요 다음에도 놀러올께요', 32, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '오늘도 재밌게 놀고 갑니다~ 비오는 날이라 축 쳐질 수 있는데도 뢀발하게 재밌게 맞이해줘서 고마워요~ 오랜만에 왔는데도 기억해줘서 고마워요!', 16, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '처음으로 메이드 카페 와봐서 넘나 재밌게 놀수 있었고 음식도 맛있었구요!! 메이드분들이랑 대화 하면서 더욱 재밌는 시간을 보낼수 있어서 나중에 또 오고싶어질 정도로 정말 재밌는 시간이였습니다!!♡', 46, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '코베니미즈 당신만 보고 왔어 당신이 고점이 될때마다 난 정말 세상이 무너지는 것 같아 제발 나만 봐줘 나만 봐줘 나만 봐줘 (농담입니다) 오늘 코스프레 데이라서 다양한 코스프레를 봤는데 아리따우신 분들이 너무 많아서 정말 행복합니다..미즈님 다음에 재밌게 놀아요', 31, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '서울 메이드카페는 처음이라 추천 받아서 온 곳 입니다 ! 크기 기대는 안했는데 메이드분들이 너무 예쁘시고 친절하셔서 너무 좋았습니다 ! 음료도 음식도 맛있고 가성비도 좋은 것 같습니다 ㅎ 또 방문하게 될 것 같습니다 !', 10, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '궁금해서 처음 와 봤는데 잘 챙겨주셔서 감사합니다 !! 라이브도 재밌었고 기회되면 또 올 거 같아요 좋은 시간 감사합니다 !!', 81, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '마지텐시 류 메이드 라이브는 단순히 ‘카페 이벤트’가 아니라, 홍대 밤 공기를 씹어 먹는 하나의 작은 콘서트다. 다음에도 류가 마이크 잡는 날, 당신의 주말 계획은 이미 정해졌다.', 83, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '고생 끝에 왔는데 다들 친절하게 반겨주시고 놀아주셔서 좋아요. 짜파게티 맛있어요. 인형이 되게 많아서 귀엽고 좋네요. 라이브도 하나 봤는데 귀엽네요.', 79, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '텐시만 오다가 데비는 처음 와보는데 텐시 때랑 느낌이 색 달라서 재밌게 즐길 수 있었어요 ! 코미님이 너무 귀엽고 친절하게 잘 해주셔서 앞으로도 계속 올 거 같아요 !', 8, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '시간을 때우거나  특별한  하루를 보내고 싶으면  꼭 와야하는곳입니다  한번오면 다음에도 또  오고싶어지는곳이니  꼭 방문해보세요', 17, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '오늘은 오후의 텐시가 아닌 저녁의 데비 시간의 양지뢰 모습을 보니까 분위기와 모습들이 즐겁습니다 역시 최고의 메이드 카페라고 생각합니다 항상 최고입니다', 42, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '메이드분들 다들 너무 친절하고 음식이 너무 맛있었어요 보통 메이드 카페는 음식 퀄리티는 기대 안 하는데 여기는 음식도 참 맛있네요.... 메이드분들이 말 잘 끌어가셔서 말 잘 못하는 분들도 잘할 것 같아요~~', 82, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '오늘 친구랑 각자 최애 보러 왔어요!! 오픈 하자마자 와서 사람이 없었어서 좋았어요!! 메이드분들과 집사분들 다 예쁘고 잘생기셨어요!! 음식도 맛있었는데 프라페는 단거 못 드시는분은 비추천합니다. 코스프레 하신 분들도 있어서 너무 재미있었어요!! 다음에 또 올께용~^0^', 33, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '히요님이 출근한지 얼마 안돼셨는데 친절하게 해주셨어요 그리고 류 님은 라이브 실력이 너무 좋아서 반해버렸어요. 오늘 코스프레도 다들 퀄리티가 높아서 좋았어요', 89, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '오늘도 방믄해서 즐거웠습니다 오늘 마텐 덕분에 즐거운 일조 많고 즐거운 추억도 많이 생겨서 너무 즐거운 하루였습니다 이 즐거운 추억을 가지고 또 다른 날에도 방문하겠습니다', 14, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '오늘 일정이 없어져서.. 허무한 마음을 달래러 왔어요.. 한가한 시간대에 가니까 소녀들을 독점할 수 있어서 너무 행복했답니다..♥ 주방초보의 특제 아망추도 맛있었어요..^_^ 또와야딩', 72, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '3번째 방문했습니다 파인애플 주스 먹었는데 주문도 같이 외우고 즐거운 시간이었습니다 메이드분들이 친절하시고 대화도 잘해주셔서 즐거웠어요', 19, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '2번째 방문인데 저번보다 재밌고 또 선물도 전달할수있어서 기뻣네요 오늘은 저번에 못본 새로운분들도 많아서  새로운느낌으로 놀다갑니다', 89, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '처음 와봤는데, 정말 재밌네요. 여집사 분들이 정말 잘생기고 아름다우세요. 라이브도 다들 춤 잘 추고 아주 좋아요. 다음에 또 다시 오고싶내요. 인형도 많아요.', 40, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '1. 카페 소개 - 장소와 분위기: "천사 카페는 입구부터 환상적인 분위기를 자아냈습니다. 천사의 이미지로 꾸며진 인테리어와 부드러운 조명 덕분에 마치 꿈속에 있는 듯한 기분이 들었습니다." 2. 직원 서비스 - *메이드의 복장과 태도*: "메이드들은 귀여운 천사 복장을 하고 있었고, 언제나 미소를 지으며 친절하게 서비스를 제공했습니다. 요청할 때마다 기분 좋게 응대해 주었습니다." 3. 메뉴 및 음식 - **특별한 메뉴**: "메뉴는 다양했으며, 특히 ‘천사 케이크’가 인상 깊었습니다. 예쁘게 장식된 디저트는 맛도 훌륭했습니다. 음료도 천사 테마에 맞춘 창의적인 이름이 많아서 재미있었습니다.', 3, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '메이드분들이랑 게임하기로 젠가했는데 같이하니 재밌었고  모든 메이드분들이 너무 친절하시고 에너지가 넘치셔서 오길 잘한거같아요!😊', 40, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '피자 처음먹어봤는데 맛있네요!! 메이드분들이 추천해주셔서 먹었는데 저도 추천하고싶어요. 다음에는 다른 메뉴도 먹어봐야겠어요. 오늘도 감사하게 다들 친절하시네용', 40, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '시간 잘 맞아서 독점 당하면 기가 많이 빨리긴하는데 그래도 그만큼 재밌게 놀기 아주 좋은 곳이에요 자주 오다보면 메이드와 하는 티키타카가 아주 즐거워요 놀리기 재밌는 분들도 몇분 있구요 놀러와서 꼭 놀려봐주세요', 29, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '마텐데는 언제 와도 후와후와 미소녀들이 가득해서 좋아요 😽😽 특히 코미님이 너무 귀여웠습니다!! 재밌는 얘기를 많이 할 수 있어서 좋았어요 더 자주 오겟습니다 ^^ 🩷', 23, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '너무 이쁜 메이드분들이 잔뜩 이뻐서,, 미소녀 수혈 받고 왔어요...🥹🥹🩷 다음에 배고플때 오므라이스도 시켜먹어보겠습니다...🩷🩶', 52, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '메이드들이 너무 귀엽고 친절합니다 자주오는곳인데 너무너무 좋습니다 체키도 잘찍으시고 좋습니다 이쁜메이드가 너무너무 많아서 좋습니다 강추', 18, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '메캎 자체가 처음인 사람인데 다들 너무 친절하시구 분위기도 짱이에여..💓 다들 짱예쁘시구 진심 그냥 짱짱짱이라서 할 말이 없내요..💕 그보다 여기 오므라이스(김볶밥)이 짱임.!.!! 자주 오겠습니다아💝', 14, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '오늘은 사복데이날 눈,비가 와서 적당히 즐길수있고 함 이제는 개강시즌이라 2월보다는 자리가 널널해서 워크인으로도 편하게 올수있어요. 처음 메카 오는분들도 오셔서 재미있게 대화 하고싶으신 분들은 와주세요.', 28, 5, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '💝천사같은 미소녀들이 가득해용...💝 다들 너무 친절하고 예쁘고 라이브도 잘하고 아주 기특한(?) 메이드들이었어용 ㅠㅠㅠ 진짜 너무 귀엽고 예쁘고... 즐겁고 행복한 시간 보내고 갑니당 완전 라뷰 ㅠㅠ  명함 다 모으는 그날까지~~~🩷', 50, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '사복데이래서+좋아하는 메이드 코미님이 특이한 옷 입으신대서 한번 더 왔다! 이틀 연속으로 왔는데도 다들 너무 잘 놀아주시고 귀엽고 예쁘시고 정신나갈거같은 텐션 마음에들었어요', 57, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '메이드 카페는 많이 다니는데 공간이 되게 편안한 느낌이고 의자도 푹신푹신해서 좋아요! 노래도 시끄럽게 나오는 게 아니라 조용조용하게 나와서 좋구 가게 안에 인생네컷이 잇는 것두 좋습니당 다들 완전 친절하세요 👍', 10, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '너무 좋았고 즐거웠습니다!! 아는언니랑 방문했는데 너무 좋았구요 오렌지주스 맛있고 명함도 이쁘게 꾸며줘서 나중에 또 올거에요!! 또', 40, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '가게도 깨끗해 보이고 음료수도 맛있고 다들 너무 친절하셔서 올 때 마다 마음이 편해지는 느낌이에요 시간 날 때 와서 가볍게 음료수도 마시고 오늘도 힐링 하고 갑니다.', 3, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '단순히 메이드 복장을 입는 게 아니라, 각자 캐릭터가 있어서 설정을 듣는 재미도 있었습니다. 처음엔 남성 손님이 많을 줄 알았는데, 생각보다 여성 방문객도 많아서 편하게 즐길 수 있었어요. 별이가 귀여워요', 17, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '한국에 제일가는 미소녀들 총집합소.. 나를 애니 캐릭터로 만들어준 츄츄쨩 고마워 🥹🥹 지루하지 않게 다들 잘 말해주시고 다들 너무 귀여우세요 ~~!! (네무짱 귀여움 한도 초과.. 카와이모노가 탁상이루요ㅜㅜ) 포보스 선정 2025년 1분기 최고의 발견이에요 재방문의사 2473952%입니다 (숫자의미없음)', 53, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '처음으로 가본 메이드카페였어요! 깔끔하고 분홍빛이라 예쁘네요! 음료는 아이스 아메리카노랑 코코아케이크를 시켰는데  커피 정말 괜찮아요 엄청 검은색인데 맛있어요! 케이크도 엄청 달달해서 당충전 잘했던 거 같아요. 잔이 비어있으면 물 채워주시는 거 같아서 배려가 느껴져서 좋아요 :3 그리고 인형 안고 있어도 된다고 하셔서 다리 위에 얹어두고 있었어요', 18, 3, 'GOOD', SYSTIMESTAMP);
