INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '저녁에 메이드 카페 놀러왔습니다 음료수도 맛있고 메이드분들도 예쁘시고 친절하시고 음식도 너무 맛있어요!! 심심하거나 시간 날 때 와서 놀다가기 좋습니다!!', 42, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '분의가 되게 좋고 음료수 및 음식이 되게 맛있습니다!그리고 알바분들이 되게 예쁘시고 친절하셔서 즐겁게 즐기다가 왔습니다!다음에 또 올께요', 13, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '요즘 이벤트로 특별한 복장 입는 날이 많이 생겼습니다 평일에도 자주 하니까 다들 많이 오세요! 아 그리고 종료공지 전까지 연장료 할인있어요!', 39, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '월급받고 바로 후다다 와버렸어요. 오니까 에이스테가 보였어요. 우와우와 저는 여기 계속 오다가 등급이 올라가버렸죠. 오늘의 메뉴의 아포가토~ 아이스크림이 아주 맛있어요 여기에 커피까지 섞이면 부드러운 크림의 하모니♡ 너무 맛있어요', 85, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '1. 카페 소개 - **장소와 분위기**: "천사 카페는 입구부터 환상적인 분위기를 자아냈습니다. 천사의 이미지로 꾸며진 인테리어와 부드러운 조명 덕분에 마치 꿈속에 있는 듯한 기분이 들었습니다." 2. 직원 서비스 - **메이드의 복장과 태도**: "메이드들은 귀여운 천사 복장을 하고 있었고, 언제나 미소를 지으며 친절하게 서비스를 제공했습니다. 요청할 때마다 기분 좋게 응대해 주었습니다."', 49, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '음식이 맛있고 메이드 분들이 친절하고 재밋어요. 처음엔 거부감이 조금 들 수도 있겠지만 막상 와서 진짜 재밋게 있었습니다! 게임이 진짜 재밋어요!', 4, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '메이드카페 살면서 처음 와봤는데 분위기 정말 좋았고, 오늘 생일 기념으로 온 건데 친구 덕분에 생일 축하도 받고 케이크도 주셔서 잊지 못 할 생일이 될 것 같아요! 정말 감사합니다 :) 잘 즐기다 가요 (_ _)', 27, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '메이드랑 집사들이 너무 예쁘고 착하고 잘생기고…. 매번 오고 싶네요 ㅎㅎ 라이브도 다들 잘 해요 체키도 잘꾸미고 대화도 잘 해주심 항목 5개만 고르는 게 너무 아쉬울 정도입니다-!!', 41, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '서비스도 너무 좋고 음식도 너무 맛있었어요 가게 분위기도 너무 좋아요 디저트도 음식도 다 맛있고 메이드 분들이 정성껏 챙겨주십니다! 다음에 또 방문하겠습니다 너무 좋았어용', 32, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '메이드, 집사분들께서 계속 오셔서 말 걸어주셔서 심심할 틈이 없습니다👍👍 특별의상데이에 와서 더 특별한 경험이 된 것 같아요! 미하집사님이 친절해요🤍🤍🤍', 43, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '너무맛있어요 쵸리님이 술을 진짜 맛있게 말아주셨구여 또 미즈님이 너무너무 ㅇㅖ쁘세요 미즈님 최고예요~~~ 그리구 류님도 진자 멋있구 예쁘고요 시우님이 진짜 여자 마음에 불을 질러용 짱짱 최고의 메이드카페~ 메이드카페 여러군데 가봤는데 젤 잼네유 ㅋㅋ', 88, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '오늘도 예약해서 방문했습니다. 항상 올 때마다 느끼는 것 이지만, 메이드분들이 다들 재밌으시고, 음식 맛도 훌륭해서 항상 좋은 추억을 남기게 됩니다.', 5, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '샤샤가 이뻐요,히카리님이 귀여워요,사장님 외모가 이빠이해요^^ 처음 와봤는데 인테리어가 너무 좋아요 메이드분들도 친절하고 다들 친하게 대해주셔서 너무 좋았어요^^', 15, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '마텐데 너무 좋아요 말도 많이 걸어주시고 친절하고 무엇보다 제 최애가 있어서 최고예요 행복하시려면 마텐데 오시긔~ 음식도 맛있어요', 24, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '평일 데빌은 처음 와봤는데 메이드 분들이 밤인데도 텐션이 좋으셔서 엄청 즐겁게 놀았던 것 같습니다!! 자주 와서는 즐겁게 놀 것 같네요 ㅎㅎ 재미있게 놀아주셔서 감사합니다!!', 65, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '메이드가 너무 재밌고 음료수가 달달구리하게 너무 맛있어용 라이브도 너무 화려하게 잘하는데 그저 갓 메이드 그리고 마텐에 카리나가 2명!!', 61, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '김치볶음밥이 맛있고 물이 시원해요. 오늘도 즐거웠습니다. 오늘 또 교복이벤트라고 다들 교복을 입고 계셔서 재밌게 놀았던 것 같아요. 인형이 많고 귀엽네요.', 3, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '오늘도 방문했습니다! 방문할때마다 메이드분들이 엄청 친절하게 상대해주시고 잘 놀아주세요! 항상 아쉽지않게 재미있게 놀다가네요! 또 방문할게요!', 35, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '일일메이드분 오신 날에 갔는데 평일인데도 메이드분들 많이 계시고 말도 자주 걸어주셔서 즐거웠습니다! 컨텐츠도 다양하고 음료도 종류 많아요👍👍', 29, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '메이드카페 처음와봤는데 인테리어도 이쁘고 메이드들이 다들 친절하고 아름답습니다. 음료도 맛있고 분위기도 좋아서 다음에도 또 올거 같아요', 13, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '5번째 방문인데 매번 올때마다 언니들이 반겨주고 편하게 해줘서 진짜 너무 행복하게 방문해요!!!생일인 언니와 둘이서 찍엇는데 아주 이쁘게꾸며주셔서 감사하게 보관해료!!', 33, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '메이드 분들 너무 예쁘고 친절하세요 낯가려서 아무것도 못 하고 있으면 계속 말 걸어주셔서 낯가림 1초 컷 당했습니다ㅋㅋ 텐션도 높으셔서 재밌었어요 3번째 방문이지만 또 방문할 의향 있습니다♡ 재밌게 놀다가요.', 45, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '최고의 경험 마지텐시!!! 메이드카페는 처음인데 말도 잘 걸어주시고!!! 너무 행복한 시간이었어용 👻👻👻 서브컬쳐를 좋아하신다면 강추입니다🤩', 21, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '아 재미있어요 그냥 맛들리면 끝장남 여기 메이드들 각자 개성이랑 매력이 다 다르고 각양 각색으로 즐거워요.항상 즐겁게 놀며 주말을 알차게 보내는중 ㅎㅎ', 0, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '데비 타임으로 왔는데, 너무 잼밋써요 내일이 출근..출..근...이긴 하지만 오늘 이 시간만큼은 후회되지 않고 즐겁게 보내다 가요.', 1, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '목요일 평일 혼자 왔는데 내부가 넓고 여유롭습니다. 서브컬쳐 좋아하시는분들에게 추천 드립니다. 음료는 맛있고 메이드분들은 귀엽습니다.', 50, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '친구랑 같이 놀러왔는데 메이드 분들이 친절하고 공연을 너무 잘하세요. 음식들도 맛있고 오므라이스에 그림도 너무 이쁘게 고퀄로 그려주셔요 강추합니다!!', 30, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '오늘 신입메이드 코미님 인스타보니 상당히 귀여우시길래 보러왔는데 코미님뿐만 아니라 다른분들도 다들 친절하게 잘 대해주시고 많이 떠들어서 좋았어요', 103, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '집근처에 맛있는 치킨이 있어서 패키지로 들고 왔어요. 출석도장 열심히 찍어서 음료도 주문하고 오랜만에 본다고 알아줘저 너무 좋아요 날 기억해주다니 이야기도 많이 걸어줘서 너무 좋아요.', 24, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '서울에 볼 일 있어 올라온 김에 들렀어요. 메이드분들이 귀여운 복장으로 즐겁게 일하고 계셔서 보기 좋아요! 지하 아이돌분들이 많이 계셔서 지하돌 관심 있으신 분들은 방문해보세요', 11, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '텐시짱분들이 나무 친절하셔서 처음 메이드 카페 가는거였는데 최고였어요!!! 다음번에 또 기회가 되면 또 오고싶어요( ﾉ^ω^)ﾉ♡♡ 메론소다도 맛있고 최고였습니다!!(* ´ ▽ ` *)♡', 21, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '오늘도 마지텐시 메이드카페에 방문 했는데 , 오늘도 너무 재밌었어요 ! 쵸리, 시요, 유리, 메이 메이드님 그리고 노아, 미하, 로쿠, 미로 집사님들 덕분에 재밌게 즐겼어요 ! 유리님의 해피 라이브도 멋있었어요! (데이식스 해피 아님 !) 인테리어도 완전히 바뀌고 매장이 너무 에뻐졌어요🥰 메이드분들도 너무 이쁘고.. 집사분들은 예쁘고,, 잘생기시고 그냥 다 해드시는..🤯 앞으로도 자주 방문하고 싶어요!!!!', 44, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '아망추가 친절하고 쵸리가…… 너무 아름다운 메이드와 함께 또 웃음 가득한 시간 보냈습니다.. 아망추 개추드려요 맛있슨 오늘 폭주기니도 보고… 치파오 데이 너무 좋네요 또 와야딩', 94, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '메이드카페 처음?이었는데. 다들 잘 놀아주셨어요 .. 오므라이스가 재밌고 라이브가 맛있어요 1. 나는 오타쿠다 2. 미소녀언니들이나데나데해줬으면좋겠다 3. 돈이많다 그런 당신께 추천드립니다 🫵。', 32, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '처음 방문했는데 다들 너뮤ㅜ친절하게 대해 주셨어요 🙈 매장도 넓고 밝아서 분위기가 조아요 굿굿 첫 만남에 조은 기억으로 남았어요 앞으로 자주 방문할 것 가타요', 47, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '메이드분들이 친절하시고 여러 주제로 대화할 수 있어서 재밌었습니다 :) 그리고 코미님이 너무 귀엽고 귀여워요 !! 시간되면 앞으로도 올 거 같고 데비 타임도 기회가 되면 와보려고 생각하고 있습니다.', 103, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '마지텐시데비 메이드 카페에놀러왔습니다 오늘은 스이님과 시화님이 오란고교 코스프레를 하셨네요 역시나 퀼리티가 좋습니다 눈이 즐거우니 월요일의 피로가 풀리네요', 9, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '야간에 방문했는데 늦은 시간까지도 메이드분들이 친절하시고 텐션이 높으셨습니다. 체키도 잘 나오고 라이브공연도 재미있었어요! 재방문 의사 있습니다', 31, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '올때마다 최고지만 메이드분들 최고입니다. 미즈님은 매번 올때마다 별명지어주셔서 재밌으시고 귀여우시며 키치님은 항상 밝으시고 텐션 높으시고 재밌으심 쵸리님은 그냥 여신 츠바키님 바쁘실때도 잘챙겨주시고 노아님은 제가 감히 평가를 할수가 없어욧 로쿠님은 뵐때마다 유머넘치시고 매력넘쳐욧 슈와님은 2번째 뵙는데 제가 더 자주 뵈야 할거 같아요', 62, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '자주 오는데 올 때마다 메이드 분들이 다들 친하게 말 건네주셔서 좋습니다!! 정말 다들 이쁘구 재밌어요...! 메이드짱들 전부 아름다워서 눈이 즐겁고 라이브도  즐겁습니다!', 9, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '마지텐시 올 때마다 마주치는 분이 있습니다. 낮에 와도 밤에 와도 계시는 걸 보면 카페에서 사시는 것 같아요, 늘 친절하게 응대해주시고 옷도 늘 잘 어울리세요, 그래도 잠은 집에가서 주무세요. 화이팅.', 36, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '메이드 카페 놀러왔습니다!! 매장이 깨끗하고 파인애플 주스도 너무 맛있어요 항상 오면 메이드분들이 너무 잘해주셔서 즐겁게 놀다가요', 47, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '오직 메카를 위해 에이스테 봤는데 진짜 쥰님너무 용안 미쳤구요 와 내 앞에서 cp 존재 재현실화 와! 오시가 한명 더 생겼구요 인생의 질 상승', 46, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '아 즐겁다 신난다 예쁜 메이드들과 즐거운 시간을 보낼수있는곳.신나게 놀고 다음날 또 오고싶은곳.텐시와 데비가 다른맛이라 좋아요', 17, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '오늘 너무 재미있었습니당~ 거의 10번 이상 놀러온것 같은데 놀러올때마다 넘 재미있고 즐겁게 놀고 칸텐츠도 다양하고 음식도 맛있어서 놀고 갈때마다 넘 즐거워요 다음에도 놀러올께요', 45, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '메이드분들이 친절하고 집사분들은 잘생기고 멋있는 곳입니다. 여기는 집!사! 분들이 있기 때문에 더욱 빛나는 곳이니 안 오신 사람들은 한번 쯤은 와봐야 한다고 생각합니다', 40, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '인테리어가 예쁘고 다들 친절해요. 라이브도 다들 잘 하시고 재밌어요. 오늘 키치 메이드 님이 정말 친절하기 잘 해주셨어요. 패스포트에 그림도 그려주시고 재밌게 해주셔요.', 17, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '메이드분들이 친절하고 되게 많아요 계속 말 걸어쥬셔서 안 심심하고 재밌었어요 연인이나 친구랑 와도 좋을 거 같아요 담에 또 올게요', 32, 3, 'GOOD', SYSTIMESTAMP);
