INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '힐링하러 메이드 카페 왔습니다 음료수도 맛있고 메이드분들도 다들 예쁘고 친절하셔서 즐겁게 놀다갑니다! 시간 날 때 한번씩 놀러오기 좋은거 같아요', 6, 0, 'GOOD', SYSTIMESTAMP);
