INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '코스프레 데이 때 방문했습니다. 베이글을 시켰는데 약간 딱딱했지만 먹을만 했습니다. 크림치즈도 맛있었구요. 활력 넘치는 분위기가 좋아요.', 11, 8, 'GOOD', SYSTIMESTAMP);
