INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '텐시들이 너무너무 귀엽고 깜찍해요💗 좋은 분위기의 메이드카페!!! 음료가 맜있고 시우집사의 얼굴이 짜릿해요👍 라이브도 너무너무 잘하고 다시 방문하고싶네요!', 18, 7, 'GOOD', SYSTIMESTAMP);
