INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '2번째 방문입니다^^ 첫번째 방문날 데비때 시간에 왔는데 이쁜 악마컨셉으로 살갑게 맞아주고 대화도 재미있게 해줘서 마지때 한번 가볼까해서 방문했는데 메이드분들도 나름 컨셉있고 관심가져다주고 공유도 잘해줘서 감동적이었고 분위기도 재미있는 분위기라 한층더 업그레이드 된 기분이네~~~용~~~', 14, 4, 'GOOD', SYSTIMESTAMP);
