INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '바쁜 와중에도 잘 챙겨주셔서 재밌게 놀았습니다.. 직장에서 받은 스트레스 다 풀렸어요 늘 그렇듯 다들 친절하시고 음료도 맛있고 오란고교 코스프레가 너무 좋았어요..♥', 42, 8, 'GOOD', SYSTIMESTAMP);
