INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '오늘 너무 재미있었습니당~ 거의 10번 이상 놀러온것 같은데 놀러올때마다 넘 재미있고 즐겁게 놀고 칸텐츠도 다양하고 음식도 맛있어서 놀고 갈때마다 넘 즐거워요 다음에도 놀러올께요', 30, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '헤ㅔ헤ㅔ헿 다들 너무 이쁘고 친절해오 재밌어욧!!!!!! 라이브도 잘하시고 평일이라 사람도 없다보니 널널해서 넘 조앗아용 히히', 10, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '메이드분들 넘 친절하구 이쁘구 귀여워요 ㅠㅠㅠ 라이브무대할때 아이컨택하면서 윙크해주시는순간 끝났어요 ㅠㅠㅠㅠ 최고에요 테루님 요정이세요 엘님 너무이뿌구 츠바키님 귀엽구 하쿠님도이뿌고 행복한시간감사합니다 지인분 생일 축하두해주시고 재밋엏어요', 17, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '한국에서 메이드 카페는 처음으로 와봤는데 메이드 분들이 모두 예쁘고 귀여우셨어요~!! 다들 친절하게 먼저 말 걸어주셔서 편하게 즐길 수 있었던것 같아요🤍 그리고 친구의 다른 모습을 볼 수 있어요(*^^*)', 5, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '귀여워… 귀엽습니다… 친구가 처음 방문한 메이드카페였는데 미소녀들이 제 눈 앞에서 걸어다니는걸 보니 정신이 혼미해졌어요ㅜㅜ 너무너무 좋아서 매일 오고싶어요 ㅠㅅㅠ 사랑해요 다들 돈 열심히 벌어올게요', 10, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '오늘 코스프레 데이라 메이드 집사분들이 코스프레를 하고 계시네요 ㅋㅋㅋ 여러 코스프레를 봤는데 항상 봽던 분들이었는데 뭔가 색다른 모습을 보이 또 새롭네요 ㅋㅋ 내일도 코스프레 데이라는게 내일도 방문 할거 같아용~ 마텐데 많은 관심 부탁드려요 !', 8, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '메이드분들이 너무 친절하고 예쁘신대 대화도 잘해주세요. 별님 애기같아서 말도 잘해주고 체키도 너무 귀엽게 찍어주세요!! 진짜 진짜 귀여우니까 별님 보러오세여', 86, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '메이드분들이 활발하게 돌아다니시면서 행복하게 즐기는걸 보실 수 있으십니다 라이브를 보시면 즐거움을 두배로 가져가실 수 있으십니다', 27, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '메이드 카페는 처음이라 긴장을 하구 왔는데 분위기도 좋고 메이드분들도 너무 친절하셔서 행복한 시간이 되었습니다! 내성적이라 걱정을 많이했는데 적극적으로 대화해주셔서 행복사 했어요~ 생일이라고 했더니 케이크도 서비스로 주셔서  너무 감사했습니다!!!', 17, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '정말 초마지텐시 아름다운 텐시분들께서 저를 공주님으로 만들어주셨어요 🥹🥹🥹💕💕💕 사랑스러운 천사분들과 함께 즐거운 시간을 맞이했습니다!! 여러분 라이브 무대가 짱입니다!!!  저는 테루님 라이브를 했는데 너무너무 좋았어요ㅜㅠ 그리고 김치볶음밥 오므라이스 미친듯이 맛있어요!! 진짜 오지게 맛있습니다..  예쁘고 힐링된 메이드 카페에는 여기가 짱이에요.....💕 다들 풀코스로 쭉!!!  즐겨주세요ㅜㅜㅜㅜ!! 하...  또 간다. 기다려줘 텐시타치🤍😆🤍✨️', 20, 9, 'GOOD', SYSTIMESTAMP);
