INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '음식 기다리는시간에도 안지루하게 계속 말걸어주셔서 너무좋았어요ㅜㅠㅠ 네번째방문인데 갈때마다 행복하네요 친절하고 재밌게 말 이어가주셔서 올때마다 대만족하고 가용 다음에 또 올게용💗💗', 35, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '음식과 음료가 맛있고 메이드들이 이쁘고 귀여웠습니다 맛있는 주문을 해주셔서 훨씬 맛있어서 행복했습니다 라이브 보고 팬이 되어서 좋았습니다!!', 30, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '내부 인테리어가 아기자기하고, 쾌적해요. 이번이 3번째 방문인데, 밝고 활기찬 분위기라 끝나까지 재미있게 즐기다 가요. 너무 재밋슴니다', 24, 1, 'GOOD', SYSTIMESTAMP);
