INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '어김없이 오늘도 와서 리뷰를 작성중인데 아망추는 언제나 먹어도 맛있고 안오면 어색할 정도로 매우 일상이 되었네요 너무 재미넘침다~!', 13, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '지난 주말에 이어서 방문했습니다! 밀크티 맛있었고 집사데이라는 행사날이여서 재밌는 시간 보냈습니다! 베이스 연주하시는 메이드분 덕분에 라이브쇼도 즐거웠습니다!', 32, 5, 'GOOD', SYSTIMESTAMP);
