INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '처음 왔는데 신기한거 같아요 친구들이랑 왔는데 직원분들이 친절하고 좋은 분위기 인거 같아요030 라이브 봤는데 춤들 잘추시네요 •>• 재밌게 즐기다 갑니다@&₩', 102, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '메론소다 진짜 맛있어요 달고 아이스크림이 특히 마음에 들어요. 아포카토에 들어가는 아이스크림이라 맛있어요. 김치볶음밥에 부들부들 오무라이스까지 마음에 들어요. 대화도 편하고 화장실도 깨끗해서 좋아요.', 10, 2, 'GOOD', SYSTIMESTAMP);
