INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '다들 너무 반응도 좋으시고 재밌게 놀아주셔서 시간 가는 줄 모르고 즐기고 있어요 체키 찍는 것도 라이브 보는 것도 다 너무 즐거워서 자주 오게되는 곳이에요 놀러오기 너무 좋아요', 4, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '살면서 처음 방문해본 메이드 카페였는데 직원분들 모두다 아름다우시고 친절하시고 노래도 잘하시고 춤도 잘추시고 음식도 맛있습니다! 강추!!', 6, 1, 'GOOD', SYSTIMESTAMP);
