INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '친구와 둘이서 다녀왔습니다! 일하시는 분들이 다들 친절하시고 예쁩니다. 음료수가 정말 맛있어요! 초코 파르페 추천합니다. 매장이 청결하고 쾌적합니다. 장소가 협소하지 않아요~ 잘 다녀갑니다! 감사합니다.', 17, 0, 'GOOD', SYSTIMESTAMP);
