INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '오늘 처음 방문인데 너무 힐링 받고 갑니다. 행복이란 이런걸까요....? 사하라 사막같은 일상속에 풍성한 오아시스 같은 이 공간... 오늘 있었던 일들 모두 꿈 같아서 다시 꾸고싶네요. 무조건 다시 방문하고싶어요. 하... 아직도 꿈속에 있는것만 같습니다...!!!', 32, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '두번째로 방문하는 메이드카페인데 이름도 기억해주시고 .. 메이드 분들도 너무너무 착하셨습니다 ㅠㅠ 너무 귀여우시고 .. 라이브공연도 너무 좋아았어요 !! 매장도 청결하고 음식도 맛있어여 ㅜㅜ 메이드 첫 방문 하시는분들께 너무너무 추천드려요 ..', 6, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '마지텐시 메이드카페 두 번째 방문하였습니다. 메이드분들 다 예쁘고 귀여우시네요! 특히 딸기라떼 맛집입니다. 데비도 있다는데 그 것도 한번 경험해보고 싶네요. 시간 나시면 한번쯤 방문해서 체험해보세요!', 65, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '오늘은 마지텐시 데비 메이드카페에 왔습니다 매장도 청결하고 메이드분들도 너무 아름답고 귀엽고 말도 잘하셔서 좋았습니다 ^_^  다음에도 방문해서 힐링하고 갈 예정입니다!!', 124, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '오늘도왔습니다 너무 좋습니다!!! 오시가 있어서 너무 행복합니다!! 다음에 또 올게요!! ㅎㅎ 음료수도 맛있습니다!! 항상 행복하네요 ㅎㅎㅎㅎ', 7, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '처음으로 메이드카페 와봤는데 메이드분들도 전부 친절하시고 음식도 너무 맛있었어요ㅎㅎ♡ 발렌타인데이라고 초콜릿도 받았어요…😭💕 전원 미소녀에 너무 행복했어요😻', 22, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '2번째 방문하는데 이번에도 메이드 분들 잘 해주셔가주고 덕분에 즐거운 시간 보냈어요 ! 그리고 코미님이 너무 귀여우셔서 자주 보러 올 거 같아요 :)', 18, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '처음 방문했는데 편안하고 아늑한 분위기라서 정말 좋았어요⸜❤︎⸝ 방문하자마자 귀엽게 반겨주시고 재밌는 이야기도 많이 해주시고 유쾌하신 메이드분들이 정말 많아요..🥺 다들 친절하시고 귀여우셔서 너무 좋은 시간 보내고 가요!! 감사합니다!', 26, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '두번째 방문이에요! 저번에 왔을 때 너무 재밌게 놀다가서 또 오고 싶었어요😳 음식도 맛있고 좋아요 다음에 또 놀러오겠습니다! 재밌게 놀다가용🩵', 19, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '두 번째 방문인데, 여전히 분위기 확실하고 메이드들도 다 예뻤어요. 컨셉에 충실해서 응대도 귀엽고, 주문할 때마다 특별한 느낌이 있어요.', 11, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '오늘도 잘 즐기다 갑니다 외출금지인데 몰래 나왔어요! 그래도 재밌어요!! 체키 포즈 다들 귀엽게 해주셔서 오늘도 힐링하고 갑니다~~', 50, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '하루 쉬고왔지만 매번 너무 재미있어요 로쿠님은 설명 필요없을정도로 재미와 친절하시고 아망추가 너무 맛있어요 ㅠㅠ 그리고 린코님 흥이 넘치시고 밝으신분이라 너무 재미있어요~!', 32, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '초호화 레전드 메이드 웅니들과 함께하는 마지텐시 메이드 카페 심지어 야간에는 천사 메이드들이 악마가 된다?! 색다른 컨셉으로 즐거움을 선사하는 마지텐시 메이드 카페 새벽까지 운영해서 힘든 하루를 마무리하기에 정말 적합한 곳입니다. 매일같이 와서 즐기고 싶지만 주머니 사정이 여유롭지 못 하여 더 열심히 살아야겠다는 생각도 드는 게 인생의 목표를 만들고 사회적 성공을 위해 노력하며 살 수 있게 만들어주는 곳이기에 사회에 지친 초년생들의 열정을 불태울 곳으로도 적합합니다.', 78, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '이번에 처음 방문해보았는데 메이드분들 모두 친절하시고, 혼자 있지 않도록 자주 오셨어요~ 메뉴도 맛있어 보이고 너무 좋은시간이였어요~ 좋은 추억 남겨주셔서 감사합니다:)', 9, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '오늘 너무 재미있었습니당~ 거의 10번 이상 놀러온것 같은데 놀러올때마다 넘 재미있고 즐겁게 놀고 칸텐츠도 다양하고 음식도 맛있어서 놀고 갈때마다 넘 즐거워요 다음에도 놀러올께요', 26, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '메이드랑 여집사가 너무너무 예쁘고 잘생겼어요 음료도 맛있고 음식도 맛있어서 좋아요!! 친구랑 놀러오기 좋아요 얘기하다 보면 시간 금방 가요 밤에 놀러오기 추천해요~', 53, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '오늘도 정말 재밌었구 다들 텐션이 진짜 좋아요! 특히 라이브 무대가 정말 멋지구 대화도 잘해즈시는데 미모가 ㄹㅇ 쩔어요. 특히 네무님 얼굴이 전설이다. 무조건 보러가세연 그냥 개이쁨;;;', 75, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '친절하고 대화하기 좋아요 재미있어서 시간이 금방 가요 먹을거도 많이 있고 메뉴도 다양하고 분위기도 밝아서 기분이 좋아요 리뷰쓰면 1시간 추가도 해주네요', 19, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '오늘도 어김없이 온 마지텐시 날씨가 추운만큼 손님이 적음 날씨가 혹독하면 손님이 적어서 놀러오기 편함 더 이야기도 많이 할수있고 메카가 아직은 낯설거나 망설이신다면 이런 날씨에 오시는걸 추천 물론 아직도 네이버 리뷰 이벤트도 하고있으니까 1시간 연장 도ㅠ하시구 예쁜 메이드 친구들 만나러 오세요', 21, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '음식과 술이 맛깔나요 메이드 분들도 친절하시고 아름다우시고 예쁘시고 재밌으시고 좋으신분들 뿐이에요 혼자라도 오셔서 재밌게 놀고가시면 좋을듯해요', 37, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '매장 넓고 메이드가 모두 착해요 잠시라도 쉴 틈 없이 이야기하고 재미있게 놀고 갑니다!! 라이브도 되게 멋지고 볼맛났어요 다음에 또 갈게요!!', 45, 3, 'GOOD', SYSTIMESTAMP);
