INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '세트 메뉴들이 가성비가 좋고 메이드분들도 많아서 계속 테이블에서 같이 대화해주십니다. 홍대에서 이색체험을 하고 싶은 분들이라면 꼭 방문하는 것을 강추합니다!', 12, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '낮에방문했다가 너무 재밌어서 저녁에 한번 더 왔어요 역시나 재밌네요!!! 술도 맛잇구 모두 친절해서 오늘도 재밌있게 놀다가요!!', 9, 4, 'GOOD', SYSTIMESTAMP);
