INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '너무너무 잘생기고,, 진짜 잘생기고,,,, 춤이 미쳤고,,, 그냥 꼭 오세요,,, 제 진심을 진짜 다 쓰기엔,, 사회적 이미지를 위해🥹', 17, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '불닭볶은면을 야무지게 끠려주시고 계란 후라이도 정확히 반쯤 익혀주셔서 맛있게 먹었습니다 그리고 잘 놀아주셔서정말 재밌게 놀다 갑니다 암튼 개꿀 따락지 싹싹 김치합니다', 31, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '오늘도 메이드분들이 너무 재미있게 놀어주셔서 시간가는지 몰랐네요! 항상 재미있게 놀아주셔서 고마워요! 또 올게요! 츠바키는 여신이고 진리다....ㅠㅠㅠㅠ', 45, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '내 집 같은 편안한 마지텐시데비 직원이 예쁘고 잘생겼어요 남녀노소 오셔서 사심채우고 가기 좋아요 대화하기도 편하고 놀기 좋아서 자주 오게되네요', 18, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '오늘 너무 재미있었습니당~ 거의 10번 이상 놀러온것 같은데 놀러올때마다 넘 재미있고 즐겁게 놀고 칸텐츠도 다양하고 음식도 맛있어서 놀고 갈때마다 넘 즐거워요 다음에도 놀러올께요', 70, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '오늘 마텐데 방문했는데 평일이랑 주말은 확실히 느낌이 다른거 같아요 ! 오늘 하루 시요 츄츄 하쿠 우기 메이드님이 다들 잘 대해 주셔서 너무 좋았어요 ! 앞으로도 자주 방문 할게요 !!', 94, 25, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '치파오데이라서 평소 메이드복과는 다른 느낌이고 다들 즐기시며 일을 하셔서 손님들도 매우 즐겁습니다 오늘도 메이드분둘을 봐서 너무 좋습니다', 46, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '첫 번째 메이드카페 방문이었는데, 입장부터 정말 친절하게 맞이해주셔서 기분 좋게 시작할 수 있었습니다. 처음이라 그런지 조금 어색하고 긴장된 마음도 있었지만, 그런 분위기를 미하 집사님께서 정말 편안하게 풀어주셔서 금방 적응할 수 있었습니다. 미하 집사님은 친절하고 세심하게 대해주셔서 어색함이 사라지고, 점점 더 즐거운 시간으로 바뀌었어요. 덕분에 메이드카페에서의 경험이 정말 즐겁고 특별한 시간이 되었답니다. 이런 친절한 서비스 덕분에 다시 방문하고 싶은 마음이 들었고, 다음에는 더 여유롭게 즐길 수 있을 것 같아요. 정말 감사했습니다!', 104, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '에르님이 제일 예쁘구 친절하구 양갈래가 잘 어울리는 최고 미소녀였어용 ㅎ.ㅎ 칵테일 짱맛있음 사장님 인센티브좀 주세요 (많이) (협박 아님)', 2, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '눈오는날에도 오는 마지텐시 눈이 많이오는 날인만큼 사람들이 없네요^^ 평일이라서 독점도 가능!!! 이런날 음료 한잔 시키고 메이드들이랑 대화도 하고 네이버 리뷰도해서 추가 1시간 받아서 메이드들이랑 재밌게 노세요^^', 77, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '오늘 코스데이라서 저도 코스프레를 하고 왔어요!! 코스데이  때 코스프레 하고 가면 음료 하나 무료라서 좋았어요!! 라이브도 재미있고!! 오늘은 사람이 좀 많았어요ㅠㅠ 다음에는 사람 적을 때 오고 싶어요!', 30, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '역시 명불허전 항상 와도 즐겁게 즐길 수 있고 매번 새롭게 행복을 느끼게 됩니다 이만큼 즐겁게 즐길 수 있는 메이드카페는 없다고 생각됩니다 매우 추천해요!!', 126, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '이.. 이거느. 초초초초..초 절정 미소녀잖냐!!!//♥♥ 너무너무 천사들이 떠도는 동산에 난입한 느낌이라서 소인.. 너무 행복하옵니다. 소녀들은 천사 그 자체이옵니다★(♥', 167, 61, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '인테리어가 예쁘고 처음 와봤는데 음료가 맛있고 분위기가 좋고 메이드님들이 재밌는데 특히 루리님이 친절하고 예쁘고 재밌어요 ! 네무님은 웃겨요(예뻐요)', 25, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '4시 예약 후 방문했습니다!! 미트볼 너무 맛있고 메이드니이랑 집사님도 예쁘고 잘생겼어요!! 라이브도 완벽하고 가게 내부에 인생네컷이 있는 것도 좋았습니다 :) 다음에 또 방문할게요!', 15, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '아아 죽지도 않고 돌아온 율쨩이옵시다 저번에 왔다가 멧챠키레카와이한 텐시들 사이에서 힐링받아 다시 재방문했습다 오늘도 여전히 행복하군요••• 다음에 또 오겠소 기다려 마이럽들~~🥹🫶', 4, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '어제.일요일 점심시간때 제가 어딘지 장소 찾아가서 홍대점 주변에 거기 카와이쪽 골목에내려가고 옆에방향에서 좌외전 꺾어서 더직진가다보면. 바로 옆건물에생긴 마지앤텐시 보이게있어요! 처음이란 제 새로 주인님으로 임명해주시니까. 친절하다보면서 더욱 한시간마다. 쉬울 편한대로는 메이드 첫인사하고 대환영인거 너무 고급이 비슷하게.야무지고 만족한뿐이예요! 👍 😊', 284, 44, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '자정 넘어가는 데비 타임을 처음 겪어봤는데 사람이 많은 지라 괜히 긴장을 했으나 메이드 분들과 조금식 대화를 나눠보니 어느 새 예약했던 4시간이 금방 지나갔습니다. 특히 기억나는 건 작년에 갔던 데비 타임에 메이드 한 분이 오므라이스를 먹고 입을 닦을 휴지가 없어 못 닦고 있었는데 그걸 캐치해서 슬며시 휴지를 건네준 메이드 분이  기억나네요. 데비 타임이라고 막 매도하는 게 아닌 그런 섬세함도 있어서 정말 좋은 거 같고 분위기가 쾌활해서 본인이 소극적인 성격이여도 충분히 즐길 수 있을 거라고 생각합니다! 다음에 또 갈 생각 있냐고 물어보면 무조건 예스입니다.', 74, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '메이드 카페라는 곳을 처음 와봤는데 메이드,집사분들 모두 친절하게 응대해주시고 음식도 맛 양 모두 좋았어요 공연도 정말 귀여웠고 체키도 이쁘게 잘 꾸며주십니다 정말 재밋는 시간이였습니다!!', 49, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '메이드카페 살면서 한번쯤 갈만합니다 마지텐시 메이드카페는 독특한 컨셉과 다양한 프로그램으로 방문객들에게 특별한 경험을 제공합니다. 홍대에서 이색적인 카페를 찾고 계시다면, 마지텐시를 방문해보시는 것을 추천드립니다.', 7, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '매번 자주오지만 너무 재미지고 미하님이 너무너무너무 친절해요 mbti가 angel이신데 약간(?) 낯을 가리시는데 살짝 쑥스러워하는 모습이 귀여..워요.. 머리가 깨질거같아요', 23, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '야간에 방문했는데 가게 분위기가 좋고 메이드분들이 전부 친절하세요! 얼그레이 밀크티가 달달하고 맛있습니다. 재방문 의사 있습니다.', 103, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '메이드분들도 모두 친절하시구 쾌적하고 좋았어요! 음료나 음식 모두 맛있었습니다!! 체키도 잘 나오고 다른 메이드카페도 가봤지만 마지텐시가 젤 좋은 거 같아여!!😻😻', 37, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '올만의 텐시 오픈타임의 방문입니다. 이 집 딸기라떼는 레전드입니다. 음료 한잔 시키실거면 무조건 딸기라떼로 드시구요 친절하고 예쁜 메이드들과 즐거운 시간을 보낼 수 있어 좋았습니다.', 9, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '시간이 한가해서 놀러왔습니다 몇번 와봤지만 메이드 분들도 친절하고 음료수도 시원하고 맛있어요 한번씩 놀러오면 좋을거 같습니다!!', 10, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '메이드분들이 정말 귀엽고 음식도 맛있어요! 낯을 많이 가리는데도 메이드분들이 대화를 잘 이끌어주셔서 즐거운 시간 보낼 수 있었습니다!', 18, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '음식이 맛있고 라이브 공연이 재밌어요 메이드분들이 심심하지 않게 잘 놀아주시고 그중 엘님이 친절하시고  재밌으세요 친구랑 친목 다지기 좋은거 같아요!', 27, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '아이랑가기좋구요 음료가 친절하고 메이드가 맛있습니다 반려동물과 가기 좋구요 진대하기좋구요  요리도 친절합니다 다음에 또 방문하고싶어요', 418, 82, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '처음 와본 메이드카페인데 다들 친절하셔서 재밌게 즐긴 것 같습니다 폴라로이드 사진도 예쁘게 꾸며주셔서 좋은 기억으로 남을 것 같아요', 88, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '오늘도 너무너무 재미있게 놀고 가요! 엔저나 항상 메이드분들이 반갑에 맞이해주시고 심심하지 않게 잘 놀아주세요! 그래서 올때마다 대대대대대만족중입니다!', 28, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '가 본 메이드 카페 중에서 제일 마음 편히 있을 수 있는 곳이었습니다. 메이드 분들 한 분 한 분이 모두 친절하시고, 특히나 라이브 실력이 좋아서 놀랐습니다... 음식도 준수한 편이라 맛으로도 꽤 만족한 하루였습니다. 추천합니다', 51, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '쟈주 다니는데 항상 재밌고 친절하셔서 너무 좋아요!! 대화하기도 편하고 음료도 맛있어요 특히 아망추...♡ 앞으로도 자주자주 다닐 예정입니다!', 14, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '친구가 소개 해줘서 왔는데 재미있고 구경하는 재미가 좋아요 마실거 (술) 김치볶음밥 맛도리 입니다 혼자와도 좋고 같이와도 좋습니다!', 68, 15, NULL, SYSTIMESTAMP);
