INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '아포가토랑 딸기라떼 시켰는데 딸기라떼가 딸기청이 많이 들어가서 좋았어요 친구랑은 두번째 오는건데 항상 친절하게 다들 말 걸어주시고 얘기도 많이 해주시고 좋아요 또 올거예요', 88, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '대학 동기랑 함께 방문했습니다! 처음 메이드 카페(이하 ‘메카’)에 와서 긴장도 많이 하고 몸이 굳어 있었는데, 다들 친절하게 접객해주신 덕분에 즐거운 시간 보냈습니다! 아이스 망고에 파르페 디저트도 예상치 못했지만 매우 맛있었습니다 :)', 27, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '메이드 카페에 다녀왔는데 정말 재미있었어요! 메이드분들이 친절하고 분위기도 아기자기해서 즐거운 시간이었어요. 특히 류님이 너무 귀엽고 서비스도 최고였습니다! 다음에 또 가고 싶어요.', 39, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '다른곳에서는 짜계치지만 여기는 짜계 ㅋ 더 비싼데 여기는 8천원 음료랑 같은 가격이라 배고플때 시켜서 먹기 딱좋움. 더불어서 네이버 이벤트로 1시간 추가 가능하니까 1시간 이용하고  이벤트하세요. 가끔가다 사장님이 미쳤어요 이벤트 하니까 잘 노리고 오세요', 73, 15, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '벌써 세번째 방문합니다 제가 리뷰같은 거 자주 안쓰는데 오면서 리뷰 3번이나 썼다는 것은 이곳이 특별하다는 것을 증명하는 거라고 생각합니다 이번이 끝도 아니고 사실 앞으로 더 올 생각입니다 마텐데 화이팅~', 294, 80, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '류님이 친절하고 다정하고 귀엽고 멋있고 밥도 잘 먹고 엄마 말도 잘 듣고 숏컷이 잘 어울려요 그리고 바쿠고 카츠키랑 잘 어울리는 거 같아요 ㄹㅇ!!!', 115, 22, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '파르페 강추 맛있어요!! 메이드들이 라이브도 잘하고 방치 없이 모두 잘 챙겨주세요 ~~ 👍👍👍 매장 디자인도 깨끗하고 분홍색으로 귀여워요 다음에 또 올 예정입니다', 18, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '메이드 집사언니들 너무 귀엽구..예쁘구.. 잘생기구.. 오길 100번 잘했다구 생각해요// 이벤트로 리뷰작성하면 1시간 무료 연장까지!! 입장료랑 세트메뉴도 많이 안비싸고 경험삼아+시간 떼우러+메이드들 보러 오기 정말 좋아요! 다음에 시간나면 또 올게요♡♡', 68, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '이제 곧 리뷰 이벤트가 마감됩니다 30일까지라고하니까 빨리빨리 오세요! 랜덤으로 서비스 라이브도 볼수있으니까 그런 재미도? 볼수있답니다^^', 46, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '메이드들이 예쁘고 재밌게 잘 놀아줘요. 처음이라 많이 긴장했었는데 다들 잘 맞춰주시고 공연도 구경했는데 춤도 다들 너무 잘 추십니다. 음료도 맛있고 다음에 또 올 거 같습니다', 7, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '메이드분들도 너무 예쁘고 친절하세요! 음식도 맛있고 가게 분위기도 좋아요. 노래선종도 너무 좋아요. 재방문 의사 100%입니다', 45, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '마지텐시 너무 재밌어요 특히 미즈란 친구 너무 사랑스럽고 고백하고 싶고 벗꽃보러 가고 싶은상대 입니다. 간다면 전 항상 마지텐시 갈거 같습니다!!', 121, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '서코날도 마지텐시데비! 텐시에는 소프트한맛 데비에는 매운맛으로 즐기러 오세요 데비때는 맛있는 칵테일과 함께~ 메이드가 친절하고 사장님이 맛있어요', 65, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '오랜만에 쓰는 네이버 리뷰 주말에는 쓰지를 못하니까 평일에 와서 쓰는 귀찮음 ㅇㅅㅇ 데비 타임(금토일)도 추가시간으로 바뀌어서 이제는 메뉴 컨텐츠 선택 안해도됩니다. 리뷰인베트는 계속하니까 와서 하며누이득 ^^', 89, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '오눌로 한복데이 시간이 지났다. 데비로 오면 연장비 없이 시간을 보낼수있다 대신 메뉴 하나는 시켜야함 음료를 시키면 좋겠됴??? 많이많이 놀러오세요', 51, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '처음 예약해서 왔는데 귀여우시고, 예쁘신 분들도 너무 많아서 재밌고 즐겁게 시간 보내고 왔습니다. 특히 히요님이 예쁘시네요 아주아주 최고였어요. 카리나 닮으셨어요', 74, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '마지텐시 처음 와보는데 메이드 분들이 잘 대해주시고 좋았는데 특히 신입 메이드 코미님이 되게 열심히 하고 잘 해주셨어요 ! 재밌어가주고 앞으로도 자주 올 거 같아요 :)', 42, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '친구와 함께 두 번째 방문 했습니다! 로쿠 집사님 영업으로 한 번 더 오게 된 거였는데 다른 집사분들도 관심 많이 가져주셔서 행복했어요😍 2월 3일이 집사데이라서 메이드 분들도 집사 컨셉으로 오셨더라구요! 다들 너무 예쁘고 잘 생기셔서 눈이 호강했습니다🥹✨✨ 말도 잘 붙여 주시고, 친절하셔서 심심하지 않았어요! 음료도 금방 나왔고 매장 분위기도 좋아서 또 방문할 것 같아요🩷', 24, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '메이드가 친절하고 사장님이 맛있어요 오무라이스 김치볶음밥 퓨전 요리 무쳤습니다 ENFP라면 무조건 추천 홍대 클럽거리 한복판의 오아시스...', 75, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '처음 온 메이드 카페인데 처음인 사람이어도 잘 참여할 수 있게 대화를 이끌어 주셔서 좋아요~ 메이드 분들이나 집사 분들도 각자의 매력이 있네요 ㅎㅎ', 16, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '다들 너무 귀여웠어요 오늘 특히 미니언즈 데이라 그런지 미니언즈 잠옷이 너무 잘 어울리고 별님의 라이브쇼도 진짜 굉장히 엄청나게 귀여웠어오', 22, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '처음엔 살짝 어색할 수도 있는데, 메이드 분들이 워낙 친절하고 분위기도 활기차서 금방 편해져요. 특히 체키 찍을 때 이것저것 포즈도 제안해주고, 수다도 많이 걸어줘서 정말 재밌게 놀다 올 수 있어요!', 47, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '류 기여어요💜류류류류류류ㅠ류류ㅠ류류류류류ㅠ류 너무 기엽버요 메이드들이 다 착하고 기엽고 음식이 징쨔 맛있어욤!!! 메뉴도 다양하고 분위기가 죠아요', 20, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '재밌고 메이드가 예쁘고요 동료들이 재밌게 놀아줘서 조았서요.ᐟ.ᐟ.ᐟ ㅎㅎㅎㅎ 일단 너무 넓고 조앗다에요。。。 메이드들이 넘 켜엽슨', 24, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '직원 분들이 많이 친절하십니다. 확실히 어색하지 않게 잘 해주십니다. 이런 공간이 생소한 사람에게 어떻게 이 문화를 즐기는 지 자세히 알려주셔서 이해가 잘 되었습니다', 5, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '메이드와 여집사들이 너무 예뻐서 혼술하기도 너무 재밌고 안주들도 너무 맛있고 무엇보다 드링크가 너무 맛있어요 라이브도 진짜 짱입니다 추천!', 84, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '노아사마가 잘생기셨고 시요삐가 굉장히 귀엽습니다 그리고 고능햄수타도 있어요 정말 빈틈없이 말걸어줘서 시간가는줄을 몰라요 그리고 로쿠님이 쌈@뽕합니다', 15, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '지인이랑 같이 왔는데 다들 너무 유잼녀심 극i인 저에게도 말을 많이 걸어주셔서 부담스러운 재미가 있었습니다 게스트인 분들도 다들 너무 예뽀요 재방문의사 있음', 36, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '말이 필요없슴다 그냥 G.O.A.T 임다 평일에도 오기 좋습니다 장점이 수없이 많지만 글로 적는것보다는 직접 오는게 최고입니다', 33, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '음식이랑 음료는 항상 맛있어욥>< 코스프레 이벤트날 방문했는데 평소랑 다른 느낌이라 더 재미있었어요ㅋㅋ 여자 집사도 있는 메이드카페라서 더 재밌고 색다른 것 같아요😍🩷🩷🩷다른곳보다 퀄리티도 높고 추천합니당', 129, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '와우 너무 친절하고, 너무 깨끗해서 놀랐어요~ 근데! 처음 메이드카페 방문인데도 어색하지않게 말을 잘해주셔서 넘무넘무 고마워요!', 9, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '오랜만에 찾은 마지텐시 메이드 카페. 한결같이 친절한 메이드 분들과 여전히 맛있는 단골 메뉴 짜파게티가 분위기를 더욱 정겹게 하네요. 코스데이도 많이 하니까 스케쥴 잘 보고 찾아가시길!', 56, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '메이드카페가 처음이라 걱정했는데 생각 외로 너무 재밌게 잘 즐겼습니다 😻 디저트 중 파르페를 주문했는데 너무 맛있더라고요… 앞으로도 방문하면 파르페만 주문할것같아요 🫶 메이드님 한분한분 오셔서 작은 카드에 직접 싸인해주시는데 너무너무 귀여워요 …', 13, 8, 'GOOD', SYSTIMESTAMP);
