INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '메이드카페는 거의 처음이었는데 메이드님들이 계속 잘 놀아주시고 재밌었어요! 음식도 정말 맛있네요 특히 오무라이스... 강추합니당 담에도 또 올 듯해요', 5, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '오늘 처음 방문해봤는데 낯을 많이 가리지만 메이님별님 린코님이 너무 잘놀아주시구 분위기 풀어주셔서 생각보다 너무 잘 즐기고왔습디다... 낯가려도 장난 잘 쳐주시고 친절하게 리드해주셔서 너무 감사합니다.', 8, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '매장이 귀엽고 음식이 맛있어요 특히 파르페 짱짱!! 무엇보다 메이드분들이 귀엽고 친절해서 좋아요 라이브도 정말 잘하시고 시간 가는줄 몰라요', 40, 3, 'GOOD', SYSTIMESTAMP);
