INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '메이드 카페를 살면서 처음 와봤는데 너무 친절하고 분위기가 좋았습니다 메이드 분들도 너무 너무 이쁘시고 많이 많이 친절하셔서 좋았습니다', 12, 10, NULL, SYSTIMESTAMP);
