INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '이젠 여기 방문 횟수를 기다리는게 의미있나 싶습니다 그냥 일주일의 피로를 풀러오기 딱 좋은 곳은 홍대에 여기밖에 없다고 생각합니다 마텐데 ㅎㅇㅌ', 59, 18, 'GOOD', SYSTIMESTAMP);
