INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '가게 인테리어가 화사하고 분위기가 편안하고 반려동물 햄스터가 굉장히 눈에 띄고 귀여워요. 별이님이 소악마같은 느낌으로 잘 챙겨주셔서 재밌게 즐길 수 있었어요. 쵸리님이 무심한듯 챙겨주셔서 좋았어요. 피자가 이븐하게 익어서 가산점 드리겠습니다👍', 74, 13, 'GOOD', SYSTIMESTAMP);
