INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '오늘도 리뷰를 쓰는.. 이제부터 평일에  월~목은 4시부터 데비(새벽 5시까지) 하니까 꼭 기억하시구 와주시면 될거같네요 평일에만 네이버 리뷰 1시간연장 하는게 좋우니까 와서 가성비 챙기세요.', 49, 2, NULL, SYSTIMESTAMP);
