INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '다들 정말 친철하셔서 힐링하고 가는거같네요! 분위기도 좋고 잔잔하게 흘러나오는 노래도 정말 제 취향입니다 ㅎㅎ 앞으로도 종종 방문 하겠습니다!', 80, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '처음 와봤는데 너무 신세계 입니다. 너무너무 즐거운 시간 보냈고, 재방문 의사 58000% !!! 이런 재밌고 좋은 곳을 이제야 알아서 너무 아쉽습니다. 다들 꼭 한번씩은 와보세용~~~', 63, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '오므라이스 너무 맛있고 짜파게티 개 맛있고 행복했고 잘생긴 여자들의 집합소 ㄹㅈㄷ 텐시 타임이랑 데비 타임 둘 다 재밌어연^♡^ 앙기모띠 많이 가십셔', 52, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '라면이랑 김치볶음밥오므라이스도 먹었는데 정말 맛있고 양도 많아서 친구랑 배부르게 시간 보내고 좋은 추억 쌓았어요💕💕 다들 친절하시고 재밌었습니다 첫 메이드카페였는데 다행이에요!!', 3, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '마지텐시에 유명한 햄스터를 보고왔어요 너무 귀여워요 작고 아담하고 귀여워요 그냥 귀여워요 다른분들도 오셔서 햄스터 보러왔다고 하시고 햄스터님 보고가셔요 완전 햄스터 최고', 52, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '언제나 힘든 업무를 끝내고 들리면 친절하게 반겨주는 직원분들이 기분좋은 느낌 ~! 음식도 정말 맛있어요 라이브보며 즐거운시간 보내고 왔어요', 42, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '정말 친절하시고 좋아요! 이번엔 남자친구랑 방문했는데, 남자친구도 만족하고 좋았어요 다음에 또 같이 올 것 같아요ㅎㅎㅎ 데이트로도 좋은 것 같아요 방문 추천합니당~', 9, 10, 'GOOD', SYSTIMESTAMP);
