INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '역시 여기만큼 메이드 분들이 신나게 만들어주는데는 찾기 쉽지 않은 것 같아요!! ㅎㅎ 덕분에 오늘도 재미있게 놀다가 갑니다!! 😁😁', 8, 0, 'GOOD', SYSTIMESTAMP);
