INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '5번째 방문인데 올때마다 귀여운 메이드들도 많고 컨텐츠도 넘 많아서 시간 보내면서 놀기에도 엄청 좋습니다 그리구 음식도 맛있어서 여기서 놀다 보면 시간이 순삭 다음에도 방문할께요', 16, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '언제 와도 즐거운곳이네요 다들 항상 친절하게 대해주시고 야무지게 놀아주셔서 오게되는 곳이에요 사람 많아도 챙겨주려고 하시는 친절한 곳 게다가 다들 예쁘고 귀여우신 분들이라서 눈호강도 제대로 할 수 있어요', 55, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '음식이 정말 맛있습니다. 분위기도 좋고, 메이드 분들도 엄청 친절하셔서, 재밌게 시간 보냈습니다. 다른분들께도 꼭 방문 추천드립니다!', 113, 25, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '오늘은 집사데이라 유독 손님분들이 많았던거 같아요 ! 유리, 노아, 미하, 유아, 키드,로쿠 집사님들이 너무 재밌었어요~ 다음에도 또 오고싶어요~', 18, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '홍대 최고의 메이드 카페는 역시 마지텐시데비. 앗 메캎 타이어보다 싸다. 최고야 마지텐시 우왕ㅋ 호고곡 마지텐시! 마지텐시! 짱짱 오므라이스 짱맛!!!!', 46, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '일요일마다 오는 마텐데 너무 재밌습니다..사장님 제발 번창하셔서 성공하세요. 오늘 메이드분들하고 얘기도 재밌고 올때마다 새로운 메이드분들과도 얘기할 수 있어서 항상 새롭읍니다..나오님 넘 귀여워요 진짜 나오님 뽑아주신 사장님 최곱니다..', 18, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '단골이 되면 벗어날 수 없다 한번쯤 찍먹해보는건 어떠신지 떠들다 가는것만으로도 만족도 200% 여기 김치볶음밥 맛집이기도 함!', 46, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '비쵸리 쵸리 이뻐 쵸리 귀여워 쵸리 섹시해 쵸리 최고 나 키모해지꺼야 내꺼야내꺼야내꺼야내꺼야내꺼야내꺼야내꺼야내꺼야내꺼야내꺼야내꺼야내꺼야내꺼야내꺼야내꺼', 13, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '드디어 10번째 입장하고 단골이 되어버렸어요ㅋㅋㅋ여기 음식 몇 가지 제외하면 다 점령해서 먹었는데 맛있고 음료랑 데빌타임에 칵테일이 너무 취적했어요. 메론,청포도 추천합니다. 👍', 13, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '하하 오늘 정말 재밌었습니다! 그리고 저의 소중한 물건을 되찾아준 것.. 저에게 친절을 베풀다니.. 반드시 대가를 치르게 될 겁니다..', 4, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '아늑하고 편안한 분위기 속에서 즐거운 시간을 보냈습니다.  메이드 분들의 친절한 서비스와 정성이 돋보였습니다.  다음에도 꼭 다시 방문하고 싶습니다.', 56, 14, 'GOOD', SYSTIMESTAMP);
