INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '설날 전이라 한복을 입고 계셨어요!  메이드분들도 귀엽고 친절하십니다! 라이브 무대도 있어서 무대도 하시는 것 같습니다. 다음 번에는 라이브 무대도 보고싶네요', 44, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '메이드들이 친절하고 음료가 맛잇어요 굿.. 매장 분위기도 좋고 코스프레가 너무 귀여웠어요!! 가게가 청결해요~ 소다 맛있었습니다 사진에도 귀엽게 나오니 추천드려요', 43, 7, 'GOOD', SYSTIMESTAMP);
