INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '메이드분들이 말 걸어주셔서 좋았어요~ 친구가 체키 찍으러 갔을 때 친절하게 말걸어주셔서 너무 웃겼어요 ㅋㅋㅋㅋ 다음에도 방문하고 싶어요~👍💞🪽👼', 1, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '오랜만에 들른 메이드카페, 메이드분들 친절했고 메론소다도 맛있습니다. 일요일 오전 근무 하고 나서 그런지 매우 마음에 들었습니다. 기회있으면 다시 들르고 싶습니다.', 30, 0, 'GOOD', SYSTIMESTAMP);
