INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '여기 김치볶음밥이 먹고 싶어서 왔어요. ㅋㅋㅋ그리고 다들 친근하게 해주셔서 바로 적응이 가능해서 좋아요. 사람이 비교적 없는 시간에 오면 더 많이 이야기하게 되서 즐겁기도 해요. 조금 다른 곳이랑 다르게 독특한 부분들도 있어서 오는 이유이기도 해요.', 43, 4, 'GOOD', SYSTIMESTAMP);
