INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '미소녀들과 함께 할 수 있는 마지텐시데비 사심채우기 위해서 자주 방문하게 되는 곳이에요 얘기 할때도 편하게 할 수 있고 컨텐츠도 재밌어서 놀다가기 너무 좋은 곳이에요', 38, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '기대하지 않고 갔는데 메이드분들이 너무 친절하셨고 혼자와도 심심하지 않게 재미있게 놀아주십니다!^^ 김치볶음밥은 너무 맛있어요! 최고입니다~ 다음에도 꼭 다시 방문할거에요^^', 42, 0, 'GOOD', SYSTIMESTAMP);
