INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '어제에 이어 오늘도 방문한 마지마지 데비데비 너무 좋아요!!! 라이브도 기대하고 있으니까 계속 보고 싶어요 다니기 좋습니다!!!!', 28, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '메이드분들 대응도 친절하시고 음료도 맛있어요! 메이드분들이랑 함께할 수 있는 컨텐츠도 다양해서 심심하지 않습니다👍 라이브쇼 추천드려요!', 50, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '메이드분들이랑 게임하기로 젠가했는데 같이하니 재밌었고 모든 메이드분들이 너무 친절하시고 에너지가 넘치셔서 오길 잘한거같아요!😊', 36, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '사람들이 다 예쁘고 친절해요…. 정말 너무 행복한 시간이고 더 있고싶습니다 이곳이 저의 고향이고 제 무덤이고 제 영혼 저의 삶 저의 행복합니다~~~~^^!!!!🩷🩷🩷🩷🩷🩷🩷', 97, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '몇 번째 방문했는지 기억도 안 나요 너무 많이 와서 올 때마다 너무 행복해요 그냥 여기서 살고 싶어요 24시간 운영했으면 좋겠어요', 28, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '다들 너무 친절하시고 예쁘고 너무 좋아요 손떨려서 좋다는 말밖에 못하겠어요. 한번 방문 했다가 너무 좋아서 또 왔어요. 음식도 너무 맛있고 진짜 너무 너무 예뻐요', 2, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '어제 방문하고 오늘도 방문하는! 항상 얘기 너무 잘 들어주고 재밌게 얘기해줘서 너무 좋아요! 너무 커져서 못오게 될까봐 걱정이예요~', 3, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '처음 용기내서 방문했는데 너무 재미있어요!!! 달마다 컨셉이 바뀐다고 시간되면 또 와보고 싶어요 재밌게 놀다갑니다~~!!! (~♡’ㅅ‘)~♡♡⁼³₌₃', 102, 20, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '메이드분들이 정말친절해서 정말 기분좋은 하루가되었습니다. 라이브도 너무 잘하시구 음식도 메이드카페 아닌거같이 너무 맛있어요 정말시간날때마다 가고싶어요', 20, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '최근 홍대에 위치한 메이드카페 ''마지텐시&데비''를 두 번째로 방문하였습니다. 카페는 홍대 클럽거리 근처에 위치해 있어 접근성이 좋습니다. 입구에서 벨을 누르면 자동문이 열리는 구조로, 들어서면 오른쪽에 계산대와 키친, 정면에는 체키(사진 촬영) 공간, 왼쪽으로는 공연 무대가 배치되어 있습니다. 전체적으로 아담한 크기의 카페이지만, 테이블이 효율적으로 배치되어 있어 아늑한 분위기를 자아냅니다. 메이드분들이 적극적으로 손님과 소통하며 방치되는 느낌이 없도록 세심하게 신경 쓰는 점이 인상적이었습니다.', 25, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '마지텐시 놀러왔습니다. 연휴 마지막날인데 꿀꿀함 털고! 다시 일상으로 돌아갈 준비 해야죠!! 늘 그랬듯이 천사님들이 맛있고 음료가 아름다웠습니다. 아차차 거꾸로 썼네용>.<', 48, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '진짜 신세계ㅋㅋ 직원분들 텐션 장난 아니고, 주문할 때마다 귀여운 멘트 날려줘서 혼자 가도 덜 어색할 듯. 분위기도 아기자기해서 사진 찍기 딱 좋음. 색다른 경험 해보고 싶으면 한 번쯤 가볼 만함!', 11, 0, 'GOOD', SYSTIMESTAMP);
