INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '마지텐시 메이드카페'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '오늘은 오므라이스를 시켜봤어요! 햄스터닮은 츠바키님이 햄스터로 그림 그려주시니까 더 맛있네요~ 안에 김치볶음밥으로 바꿀 수 있다고 하니까 다들 오므라이스 한번씩 드셔보세요!', 13, 3, 'GOOD', SYSTIMESTAMP);
