INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언플러그드 홍대'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '이런 인디 공연 처음인데 너무 멋졌어요ㅜㅜ♥️♥️ 멋진 공간에 최고의 공연 설레고 여운남는 공연이었어요👍🏻✨✨ 또 방문하고 싶습니당 🥰🥰', 54, 16, NULL, SYSTIMESTAMP);
