INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언플러그드 홍대'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '기대하고 갔는데 직원분들 손님 오신건지 웃고 떠드는 소리가 가게 음악 소리보다 더 커요 몇십분 내내 이야기 하면서 저한텐 안녕히 가시라고 인사도 안해주심 꿔다놓은 보릿자루마냥 버티다가 음악 잘 들리지도 않고 진짜 너무 시끄러워서 좀 속상한 마음으로 그냥 나왔는데 아직까지도 진짜 기분 최악..............', 50, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언플러그드 홍대'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '갑자기 공연이 보고 싶어져서 방문했는데, 너무 좋았습니다. 소공연장이라 가까이서 노래를 감상할 수 있어서 좋았고, 분위기도 아늑해요. 공연 좋아하시는 분들은 꼭 한 번 방문하세요!', 128, 20, 'GOOD', SYSTIMESTAMP);
