INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언플러그드 홍대'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '감성돋는 핫플 ~친절하고 칵테일 안주 모두최고~^^ 이런분위기 찾기 힘들죠 자리없어 몇번을 되돌아갔는데 ~자주가고 싶어요 평일도 더 늦게까지 오픈해주심 안될까요? ^^', 26, 4, 'GOOD', SYSTIMESTAMP);
