INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언플러그드 홍대'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '커피맛, 분위기, 공연 모든게 다 최고였습니다~ 소품하나하나 다 갬성 터짐요~ 귀여운 강아지들도 볼 수 있고ㅠㅠ 아는 지인이 뮤지션이라 그친구 덕에 너무 좋은 곳을 알게 되었네요! 조만간 또 방문하겠습니다🥰', 44, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언플러그드 홍대'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '작년이랑 좀 매장이 바뀌었어요 그래도 따뜻한 분위기로 최애까페입니다. 댕댕이들 귀여운건 덤이고 음료도 처음먹어봤는데 맛있네요! 멜론소다 추천해요. 사장님도 잘 신경써주셔서 감사했어요', 48, 2, 'GOOD', SYSTIMESTAMP);
