INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언플러그드 홍대'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '엘피인테리어+기타+멍멍이=취저 분위기도 좋은데 사장님도 친절하셔유 무조건 재방문 . 좀 더 길게 머물 수 있을 때 다시 올예정입니당', 20, 9, 'GOOD', SYSTIMESTAMP);
