INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언플러그드 홍대'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '기억은 안나지만 아마 5-6년 전에 오고 다시 왔는데 아직도 카페가 있어서 반갑고 좋음. 업자들 용어들이 난무하는 카페라 신선한 기분', 22, 5, NULL, SYSTIMESTAMP);
