INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언플러그드 홍대'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '공간은 생각보다 협소하지만 분위기로 4점 드려요. 분위기 좋아요. 코아 Koa -연유맛이 나는 커피우유 커피c69 - 산미 있는걸 못 마시는데 못 마실 정도는 아니에요.', 55, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언플러그드 홍대'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '에이치얼랏의 음악은 말할 것도 없고, 언플러그드의 공간도 너무 포근하고 좋았습니다. 앞으로도 멋지고 따뜻한 무대 많이 열어주세요.', 82, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언플러그드 홍대'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '쇼케이스만 보는 줄 알았더니 조규현의 토크쇼도 관람했네요ㅋㅋ 분위기,노래 전부 다 좋았습니다 집이 멀어서 왕복 5시간이 걸려서 힘들었는데 관람 후에는 그 힘든 거 다 좋아졌네요 또 공연이 있었음 좋겠습니다', 86, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '언플러그드 홍대'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '2주전에도 여기에 갔었는데 너무나도 좋았습니다^^ 시설도 좋고, 공연장 분위기도 좋아서 인디 공연을 즐기기에 딱 알맞은거 같아요^^ ㅎㅎ 다음 번에도 이곳에서 또 공연을 보고 싶습니다. ^^', 20, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '탭커피 (배치브루)로 빠르고 간편하게 필터 커피를 즐길 수 있어서 정말 좋았어요. 가격도 2,800원으로 부담 없고, 1,000원만 추가하면 리필까지 되니 가성비가 최고네요. 집에서 원두로 주문했던 카라멜로를 매장에서 마시니 또 다른 매력이 느껴졌습니다. 탭커피로 신선하고 맛있는 커피를 저렴하게 즐길 수 있어 만족스러워요.', 2, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '예전엔예저에 자리없어서 그냥 나온 경험있었는데 이번엔 운좋게 바에 앉음. 무릎은 닿지만 의자가 편했음. 드립커피는 출시된 지 얼마 안 되었다는 썸머링 블랜드 아이스 - 설명해주셨던 것처럼 자스민, 허브등 풀잎 뉘앙스가 좋았고, 디저트 라구바 퐁신퐁신하고 쫄깃한 식감에 바나나잼도 달콤새콤한 맛이라 곁들이기 좋았고 혼커하면서 먹으니 매우 포만감 듦. (※컨디션 저하로 미각이 둔해져 새콤은 본인만 느낀것일 수도 있음)  왠만한 프토보다 맛있었다. 다른분들도 드시길래 궁금해서 마셔본 탭커피 카라멜로 아이스 (배치브루 라고 하심) 매우 착한가격에 마실 수 있는 가격대비 괜찮은 커피였다. 모두 친절하시고, 화장실도 관리가 잘 되어있었고, 바 의자도 이 정도면 편한 편이라 머무르기 좋아서 또 와보고 싶은 곳.', 13, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '바쁜 아침 향긋한 커피를 빠르게 받을 수 있는 합정 대표 카페 라운지 클라리멘토입니다. 탭 커피_누베그리스 블렌드로 마셔봤습니다. 요즘은 원두를 고르는 카페가 많아 산미 있는 커피를 많이 즐겼었는데 오랜만에 묵직한 커피로 아침을 시작하니 또 다른 느낌이네요!! 다양한 원두의 향미를 맡아 보실 수 있으니 직접 방문해 보시길 추천드립니다.', 36, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '파트너분들이 친절하시고, 분위기도 너무 좋고, 커피는 말할 필요 없이 맛있어요! 바스크치즈케이크와 말돈소금을 같이 제공한다는 점이 매우 독특했습니다! 케이크에 소금? 했는데 막상 같이 먹어보니 부담스럽지 않은 말돈 소금의 짠맛이 바스크치즈케이크의 단맛과 감칠맛을 배로 끌어올려주네요! 디저트 추천해요!', 17, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '2호선 합정역 인근에 있는 라운지 클라리멘토에 다녀왔습니다. 예전에 고양시 도래울 쪽에 있는 ''클라리멘토''를 간 적이 있었습니다. 커피도 맛있고 매장도 마음에 들었었는데 교통이 불편한 것이 단점이었습니다. 그런데 마포에 매장이 생겨 너무나도 기쁘네요. 이곳은 미리 내려두고 정수기처럼 바로 제공해주는 탭커피 메뉴가 있는 것이 특징입니다. 덕분에 맛있는 커피를 출근 시에 빠르게 받아 갈 수 있겠다는 생각이 드네요. 탭 리필 시에는 원두도 다시 선택할 수 있는 것 같았습니다!! 지하 1층에 마련된 라운지 공간은 오전 11시부터 오픈이니 참고하시면 되겠습니다.', 51, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '만석이어서, 구석 자리에 앉아 커피를 마시다 왔어요. 가게 직원 분들께서 손님들과 담소를 나누는 모습이 정겨워 보였습니다. 왠지 정말 커피를 사랑하는 분들께서 일하시는 것 같아, 다음에 다시 방문하고 싶어졌어요.', 9, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '지난 번 처음 왔을 때, 직원분들께서 손님들과 친근하게 이야기를 나누시던 모습이 기억에 남아 다시 방문했어요. 이번에도 좋은 기억을 가지고 왔습니다. 탭커피 말고 다른 것도 마셔보고 싶어지네요.', 149, 53, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '라운지 같이  잘 꾸몄다 타 카페 대비 바리스타들이 과하게 친절해서 너무 좋다.  퇴장시 좋은 하루 되세요  한 마디가 작지만 크다. 커피가 맛있다.  담배뷰는 ㅠ', 34, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '종종 들르는 클라리멘토입니다. 점심을 조금 넘은 시각에 들렀어요. 바리스타님 환대들이 이상적이셨고 그래서인지 바 주변에 대화하는 사람들이 많았어요. 바 뒤편에는 원두와 커피도구들이 있었어요. 이번에는 새로나온 소울펀치 블렌드를 마셨어요. 포도포도한 느낌에 후미에 들어오는 초콜릿 뉘앙스가 인상적이었습니다. 저는 UFO라는 커피드리퍼를 자주 사용하는데 여기서 전용필터(타입a)도 판메하시더라구요. 멜로드립도 있었어요', 49, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '맛있는 아바 마시고 싶어서 남편이 찾은 카페인데 진짜 커피 맛있구요 직원분들 진짜 너무 친절하시고 더우니깐 먹으라고 라벤더 물도 주시더라구요 완전 센스👍🏻커피원두에 대해서 설명도 잘해주셔서 남편은 추천하신 커피로! 핸드드립커피로 주문했는데 커피 너무 맛있다고 감탄! 커피잔도 신기했어요 😳🩵☕️🫖  아이스 바닐라라떼 맛있다고 자신있게 추천해주시는데 진짜 맛있게 잘마셨습니당👍🏻 지하에도 자리 있더라구요 넓은 자리 재즈바 분위기로 되어 있어요 저희는 1층에 앉았습니당😋☕️ 라운지 클라리멤토 커피맛집인정', 101, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '벌써 제가 클라리를 방문한지 거의 1년이 다되어가네요. 1주년 행사로 다양한 상품도 주고!! 변함없이 커피도 너무 맛있어요. 다들 너무 친절하시고 좋은 공간입니다!!합정 근처 사시는 분들은 너무 추천합니다!!!', 23, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '● Honduras Finca El Puente 52D SL28 Washed(Hot) ● 라떼(Ice) 오랜만에 라운지 클라리멘토에 방문을 했습니다. 경기도 고양시에 위치한 본점에 처음 방문했을 때, 눈 앞에서 볼 수 있었던 로스팅 기계와 다양한 종류의 드립 커피, 시그니처 디저트가 인상적이었던 기억이 납니다. 합정역 인근에 오픈한 <라운지 클라리멘토>에서는 여러 종류의 배치 브루를 탭으로 경험할 수 있으며, 취향에 맞는 원두를 핸드드립으로 주문이 가능합니다. 이번에 경험한 온두라스 커피와 라떼는, 그 어디에서도 맛볼 수 없는 독특한 향과 풍미를 지니고 있어서 너무 놀라웠습니다. 다음 방문 때, 어떤 메뉴를 선택해야 할지 벌써부터 고민이 됩니다.', 3, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '직원분들이 매우 친절하셔서 좋았습니다!! 탭으로 마시는 배치브루도 너무 맛있었어요! 특히 필터로 먹은거렁 이벤트 탭으로 먹은 파젠다엄 보다도 카라멜로가 정말 맛있었어요!! 에티오피아 취향에 가까운건지...!', 130, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '버터스카치 진짜 인생커피 👍🏻👍🏻👍🏻🫶🏻🫶🏻🫶🏻 너무 맛있어서 자꾸 생각나 또 온 카페입니다 꼭 먹어보셔야 해요 버터스카치!!! 인테리어 , 분위기 , 서비스 전부 완벽한 곳👏🏻', 29, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '@clarimento 커피 마셔야하는데 18:00 넘어서.. 걍 차가운 밀크티로.. 참 여긴 친절하고 커피에 진심인 곳.. 18,000원짜리 파나마게이샤 소비층이 있나보다 충전이 필요한 시간.. 가죽쇼파 좋다.', 41, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '1층은 라운지 ,지하는 재즈바! 1층에서는 커피관련해서 여쭤보면 자세히 알려주시고, 지하는 조용하고 따뜻하게 즐기기 좋은 공간입니다. 두 공간에 매력이 너무 다르게 좋아서 기분에 따라 이용하기 좋습니다! 주문도 아래서 가능하고 주문하면 가져다 주시니 편안해서 좋네요!', 6, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '역시 커피는 너무 맛있어요! 직원분들 너무 친절하시고 테이블도 잘닦아주시고 물도 같이 주셔서 좋았어요. 다음엔 점심시간피해 종종 가고싶어요 너무 맛있음!!', 96, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '커피 너무 맛있어서 감동했어요ㅠㅠ 핸드드립커피 먼저 블렌딩으로 선택해서 마셨는데 첫 입의 향긋하고 쥬시함에 반해서 바로 단골해야겠다 결심했습니다😌🤎 그 다음으로 플랫화이트랑 탭커피도 마셔봤는데 아 진짜 맛있어요!!!👍🏻 바리스타님들 모두 아주 친절하시고 설명 하나하나 해주셔서 감사했어요 합정올때마다 올게용 충성충성🫡', 188, 66, 'GOOD', SYSTIMESTAMP);
