INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '처음으로 클라리멘토에서 열리는 퍼블릭커핑에 와봤습니다. 사람이 많았지만 아직 초심자 입장에서 질문을 할 때 잘 알려주셔서 좋았어요. 작년에도 자주 구매하고 가끔 매장방문도 했지만 역시 커피가 맛있었네요 ㅎㅎ 이번 커핑 덕분에 월픽에서 구매할 선택지를 취향에 맞게 줄일 수 있어서 더욱 좋았습니다.', 31, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '원두를 구입하고 커피맛도 직접 보고싶어서 퇴근하자마자 바로 달려왔어요!! 바리스타분들 친절하게 설명해주시고 커피도 맛나게 내려주셔서 덕분에 잘즐기다갑니다! 영업시간에 쫒기긴했지만 다음에 여유있을때 다시 와서 마셔보고싶습니다!~~', 49, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '지하 생긴 이후로 리뷰 처음쓰네요! 커피는 여전히 맛있고!!! 1층은 공항 라운지 느낌이라면 지하는 재즈바 느낌의 좀 더 차분한 공간의 느낌이에요! 1층은 커피에 대해 궁금한거 있으면 다 친절하게 알려주시고, 지하는 지인과 이야기하러 오기 참 좋겠다 싶어요! 언제나 추천합니다!', 29, 5, 'GOOD', SYSTIMESTAMP);
