INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '✔️배치브루로 맛있는 커피를 저렴한 가격에 맛볼 수 있는 곳 처음에 잘못 계산된 줄 알았어요 😂 탭커피 리필도 1000원에 하실 수 있어요 👍 ✨네이버 리뷰적고 필터커피 한 잔 받아가세요 ✨ ✔️Caramelo: 에티오피아 특유의 직관적인 과일느낌이 잘 느껴졌습니다. ✔️old school: 삥타이거 콜라보블렌드 핸드드립. 자두노트가 잘 느껴지며 고소한 견과류느낌으로 깔끔한 피니쉬.', 1, 7, 'GOOD', SYSTIMESTAMP);
