INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '커피가 굉장히 맛있네요. 탭커피가 생소한데 정말 맛있게 즐겼습니다. 리필도 가능한 게 인상적이에요! 친절하고 전문적인 바에서 좋은 시간을 보내고 갑니다.', 14, 5, 'GOOD', SYSTIMESTAMP);
