INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '원두구매해서 먹고 있는데 궁금해서 와봤어요 매장은 첫방문인데 커피 맛있네요 ㅎㅎ 1층, 지하 매장도 있어서 넓고 쾌적해서 좋네요 종종 이쪽 오면 들를게요!!!', 89, 11, 'GOOD', SYSTIMESTAMP);
