INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '필터커피 개맛도리 😋 아직 IMF 버전은 못 마셔봤지만 줍줍 성공했던 포톤 게이샤 마셔보니 줍줍하길 잘 했다 생각 들 정도로 짱 ୧ʕ•̀ᴥ•́ʔ୨ 그저 행복-', 0, 1, 'GOOD', SYSTIMESTAMP);
