INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '사진 속 잔 개수만 보셔도 아시겠죠•• 저의 방앗간입니다 🐣 스페셜티에 입문하신 분들.. 용기내어 이것 저것 질문해보세요 너무나 친절한 눈빛으로, 오히려 제게 호기심을 갖고 대답해주시고 질문해주십니다 따뜻하고 다정한 그리고 맛있는 !! 저의 공간입니다 ♡', 115, 19, 'GOOD', SYSTIMESTAMP);
