INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '드디어 라구바ㅏ!! 방문하실 때 주문가능하다면 슬며시 추천 드립니다. 퐁싯퐁싯한 프렌치토스트가 꽤 맛있거든요. 함께한 커피는 과테말라 엘 인헤르또 레전더리 게이샤였는데요. 따뜻하게 주문하셔서 식어갈 때까지의 변화를 느껴 보셔요! 넘무 맛있습니다ㅏㅏ:-)', 18, 8, 'GOOD', SYSTIMESTAMP);
