INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '진심을 다하는게 느껴져 마음까지 따뜻해지는 곳 :) 커피도 맛있고 공간도 아늑하고.. 갠적으로 빛이 잘드는 오후 시간을 정말 좋아해요! 늘 맛있는 커피를 내어주시는 곳에서 월드챔프와 함께 이벤트를! 정말 너무너무 맛있게 그리고 즐겁게 즐기다 갑니다:D', 10, 10, 'GOOD', SYSTIMESTAMP);
