INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '커피에 진심이신 지인분의 추천으로 오게 되었어요~~ 저도 저장은 해두고 드디어 와봤는데 커피도 너무 맛있고 원두 시향부터 자세한 설명까지 해주시고 ~ 게이샤 #106 으로 먹었은데 커알못인 저도 맛과 향이 너무 디테일하게 느껴진 좋은 시간이었어요 ㅎㅎ 루베그리스 드립도 추가 또 해요 너무 좋다👍 추천합니다!', 46, 6, 'GOOD', SYSTIMESTAMP);
