INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '커피는 사실 말 안해도 이미 맛있는거 다 아실거라 생각합니다 ☺️ 분위기도 너무 좋습니다. 지하 라운지도 전혀 지하느낌 안나고 너무 아늑하고 편안해요 :) 1주년 룰렛 이벤트도 너무 재밌었어요 제 동네였다면 매일 오고 싶을 정도 너무 좋아요.', 29, 0, 'GOOD', SYSTIMESTAMP);
