INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '맛있는 커피가 마시고 싶었는데, 만족스러워요 욘두라스 게이샤 마셨어요☕️✨ 바리스타분들이 너무 친절해서 숨만 쉬어도 기분이 좋아지는 공간이에요 밝은 견과류, 플레이버 향미 다 너무 좋았습니당', 14, 1, 'GOOD', SYSTIMESTAMP);
