INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '첫 방문 때 디카페인 라떼를 마시고 반해버려서 (마셔본 디카페인 라떼 중에서 제일 맛있었음) 또 방문 이번에는 디카페인 플랫화이트랑 라구바 (라운지 구운 바나나)를 주문했는데....뭐죠? 이거 뭐죠??? 구운 바나나라서 바나나 나올줄 알았는데 바나나같이 생긴 브리오슈 프렌치토스트 느낌의 디저트인데 정말 영혼을 팔아버릴뻔했어요...플랫화이트는 말해모해 요즘 합정 최애 원탑 카페입니다아🙌🏻👍🏼♥️', 10, 9, 'GOOD', SYSTIMESTAMP);
