INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '브루잉 마시러 왔어요. 주말에 사람이 많은데, 일찍 왔더니 약간 여유 있네요. 커피는 차처럼 부드럽게 마시기 편해요. 언스페셜티 블렌디드 비올레타랑 엘인헤르또 게이샤 마시고 갑니다!', 46, 2, 'GOOD', SYSTIMESTAMP);
