INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '언제나 사랑이 넘치는 클라리멘토✨ 라운지 매장의 1주년을 축하합니다😆 합정에서 맛있고 다양한 커피를 합리적인 가격에 경험해볼 수 있어서 꼭 추천드립니다!', 34, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '소문으로만 들었던 클라리멘토를 드디어 방문했습니다! 사장님부터 직원분들까지 너무 에너지가 넘쳐서 이용하는 동안 기분이 좋은 매장으로 기억에 남을 거 같습니다. 다른 곳에서는 커피 노트 설명을 봐도 맛이 안 느껴지는 경우가 많았는데 여기는 설명 그대로 다 느껴저서 신기했습니다. 인테리어도 너무 멋져서 재방문 의사 100번 있습니다! 잘 머물다 갑니다:)', 50, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '굿굿 커피도 맛있고 직원들 너무 친절하세요. 서로간의 분위기도 좋아보이고 매장도 너무 이뻐요. 정말 라운지 입니다. 다음번엔 바에 앉아볼래요. ☕️🫶🤭👍', 27, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '커피가 너무 맛있어요!! 요즘 에스프레소에 빠졌는데 커피 좋아하시는 분들께 추천합니다 ㅎㅎ 이따 지하공간 오픈하면 가보려구요! 위에도 인테리어가 너무 예뻐서 기대중입니다 😆', 17, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '어제도 오고 오늘도 또 왔습니다.. 맛있는 스페셜티 커피를 합리적인 가격에 즐길 수 있고, 배치브루 탭 커피는 엄청난 가성비를 자랑합니다.. 물론 디저트나 다른 음료들도 다 맛있어요! 또 커피에 관련된 궁금증이 있으시다면 바리스타님들께 여쭤보시면 엄청 친절하고 자세히 알려주실 거예요✨', 28, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '서울 시내에서 이런 저렴한 가격에 훌륭한 탭커피를 즐길수 있다니 너무 좋아요. 심지어 리필도 가능!! 그리고 바리스타 분들이 다들 친절하고 파이팅 넘치셔서 올때마다 기분이 좋아지는 곳입니다.', 2, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '서울에서 제가 가장 애정하는 카페 중 한 곳이에요! 항상 밝게 맞아주시는 바리스타님들과 아늑한 매장 분위기도 너무 좋고, 맛있는 스페셜티 커피를 합리적인 가격에 즐길 수 있어서 강력 추천드려요. 아, 디저트나 다른 음료들도 다 너무너무 맛있어요!!', 46, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '커피가 생각날때면 늘 방문하는 라운지 클라리멘토!! 작년 5월 중순에 처음 갔다가 너무너무 좋아하는 곳이 되었어요,,♥ 합정역 2번 출구랑 정말 가깝고 홍대도 가까워서 접근성이 정말 좋다고 생각해요 ㅎㅎ 언제나 다양한 가격대의 필터커피 라인업이 있어서 좋아요!! 어느 시간대에 가도 늘 친절하신 직원분들이 맞아주셔서 방문 할 때 마다 기분이 좋아져요 ㅎㅎㅎ 필터커피를 즐겨마시는 편인데 항상 좋은 퀄리티를 유지하시는 것 같아요!! 커피랑 같이 주시는 카드에 있는 맛들이 정말 잘 느껴집니다👍🏻👍🏻 새로 생긴 라구바도 너무너무 맛있어요🤤🤤 1층은 공항 라운지같은 느낌에 매장에서 커피를 마시면 정말 편안하고 제대로 된 휴식시간을 가지는 기분이에요🫶🏻🫶🏻 합정 근처 카페를 찾으신다면 라운지 클라리멘토 정말 추천합니다!!', 29, 10, 'GOOD', SYSTIMESTAMP);
