INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '지하 공간은 조금 답답한 느낌인데 1층에 공간이 좁아 어쩔 수 없이 이용하게 되네요ㅠㅠ 카라멜로 원두를 먼저 구매했는데 맛있어서 다시 방문했어요', 55, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '맛있는 커피와 멋진 공간이 있는 곳 탭커피의 가성비는 말이 필요없을 정도 거기다 맛까지 좋으니 금상첨화 그리고 직원분들이 너무나도 친절하셔요..! 다음에는 드립마시러 오겠습니다', 123, 20, 'GOOD', SYSTIMESTAMP);
