INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '고퀄리티 커피에 .. 친절하시기까지 .. 클챔이 내려주시는 필터커피 꼭 드세요 🫡 혼자 와서 시간보내기도 좋구 지인들 데려오기도 너무 좋은곳 ! 자주 올게요 💜', 12, 6, 'GOOD', SYSTIMESTAMP);
