INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '합정역 2번출구에서 도보로 가까운거리에 있어요 커피에 진심인 매장입니다! 드립커피 넘 맛있고 탭커피도 깔끔하고 부담없이 마실수있어서 자주 이용하는곳이에요 지하에 넓은 좌석도 있어서 편하게 쉬고가기도 좋아요 :) 강추!!', 21, 9, 'GOOD', SYSTIMESTAMP);
