INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '1주년 경품으로 아벤시 서버를 타 왔습니다 서빙받을 때 이 서버로 주시던데 집에서도 클라리멘토랑 똑가튼 환경을 즐길 수 있게 되어 좋습니다 풍족한 인심 라운지클라리멘토 아자아자 화이팅', 49, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '버터스카치라떼 여러분들이 아는 그 스카치 캔디 맛이구요, 커피는 뭘 선택해야할지 잘 모르겠었는데 직원분이 너무 친절하게 설명해주셔서 편히 선택할 수 있었고, 신맛나는 커피 좋아하는 친구가 맛있다고 하네요ㅎㅎ 그리고 바나나 디저트 꼭 꼭 드세요!! 담백 달달 그 자체💛', 37, 0, 'GOOD', SYSTIMESTAMP);
