INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '찾기 힘든 원두부터 다양하게 구비하고 있어 스페셜티 좋아하면 근처에서는 꼭 방문해야 할 곳 입니다. 전체적으로 라이트하면서도 원두의 특징을 잘 살아있게 내려 주시네요 :)', 24, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '#합정 #파나마돈벤지게이샤 #101 이 아이는 뭔가 한방이 없는.. 기록되어 있는대로 식으면 우롱차 느낌이 있는.. 아쉽지만.. 특별히 대안이 없는.. 이름모를 파나마 게이샤 섞인거 마실까도 했으나.. #커피인쇄소 가 일요일은 휴무일이라.. 안전하게 아침커피로 선택.. 라운지클라리멘토 첫 방문인데 상당히 안정되어 있는 인테리어 나무와 가죽.. 잘 배치되어 있어서 좋다. 👍 원두는 12/5 에 볶았고 10일차.. 85g에 35,000원에 판매.. 10프로 적립 괜춘..', 13, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '4월 월픽하고 있는 클라리멘토 오랜만에 합정 스윽 가서 스윽- 108번 TAP WATER 야르 ୧ʕ•̀ᴥ•́ʔ୨ 담주 월픽 원두 리스트도 기대가 됩니다', 42, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), 'Lounge Clarimento is my go-to cafe. Great coffee, chill ambiance, and friendly staff. I’ve been to plenty of cafes, but the consistent quality here keeps me coming back.', 100, 26, 'GOOD', SYSTIMESTAMP);
