INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '퍼블릭 컵핑으로 처음 가봤는데..참여 인원이 많았지만..진행이 원활해서 편하게 경험하고 왔습니다.  그날 나와 있던 사람들 모두가 친철하고 활기차서 모습이 좋았습니다.', 34, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '가장 기억에 남을 크리스마스 이브🎄 평소 클라리멘토를 좋아하는 단골이에요!! 이번에 특별한 코스가 있다고 해서 다녀왔습니다👀 진짜 상상 그 이상이에요!! 모든 음료에 담긴 이야기부터 제공받는 과정, 음료에 맛까지!! 하나도 흠 잡을게 없고 완벽한 코스였습니다!! 같이 갔던 친구도 가장 기억에 남을 순간이라고 좋아했어요!! 원래도 클라리멘토 늘 추천하고 좋아하던 브랜드였지만 덕분에 친구한테 뿌듯했어요🤭🤭 물론 평소에 클라리멘토도 기분 좋은 경험을 가져가게 되는 장소에요! 합정에 오신다면 꼭 가보세요🤗🤗', 12, 2, 'GOOD', SYSTIMESTAMP);
