INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '커피가 너무너무 맛있습니다 아이스로 마셨는데도 섬세한 맛이 다 느껴져요! + 직원분들 모두 친절하셔서 기분이 절로 좋아지는 곳이에요 추천드립니다~! 많은 분들께 추천드려요', 113, 20, 'GOOD', SYSTIMESTAMP);
