INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '운동하는 곳 옆에 굉장한 퀄리티의 커피를 항상 즐길 수 있어서 최고입니다!!! ㅠㅠ 매니저님도 늘 친절하시고 반겨주셔서 기분좋게 하루 시작합니다! ☕️✨감사해용', 41, 6, 'GOOD', SYSTIMESTAMP);
