INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '탭 커피 가성비가 미쳤습니다 웬만한 카페의 싱글 필터로 나와도 손색 없는 맛이에요. 배치 브루라서 나오는 속도도 빠르고 좋습니다! 바에 앉으면 바리스타 분들의 친절한 응대도 있는데.. 2,800원은 상당하네요!!', 79, 14, 'GOOD', SYSTIMESTAMP);
