INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '안스타님 쇼츠보고 방문했는데 커피 맛있어요! 바리스타분들 엄청 친절하시고 설명도 꼼꼼하게 해주셔서 기분 좋게 커피 마시고 갑니다! 감사합니다~🙂', 16, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '라이트한 로스팅 다양한 과일의 산미와 청량감 적절한 고소함과 단맛이 있는 커피 개성있다고 느꼈고 클라리멘토 만의 명확한 방향성이 고스란히 베어있어서 좋았습니다.', 30, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '로스팅 맛집이라 커피는 당연히 맛있었고 인테리어도 라운지 같이 이쁘고 직원분들이 많이 친절한 곳입니다. 합정역 코 앞이라 위치도 너무 좋았음', 29, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '매 번 달라지는 필터커피가 정말 예술이에요👍 106번 한잔, 플랫 화이트 한잔 마셨는데 플랫화이트는 농축우유로 만들어주셔서 인위적이지 않은 달콤한 맛이라 디저트 같은 느낌이에요. 모든 직원이 정말 친절하고, 최매니저님 잘생겼어요. 아이돌 재질 🔥', 50, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '어제 매장에서 마실 시간이 없어서 테이크아웃했는데 초콜릿도 챙겨주시는 친절한 미녀(?)직원분이 계십니다 마음이 따뜻해진 하루네요 탭커피는 금방 나와서 테이크아웃하기도 좋아요!', 0, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '다 개맛도리😋 원두 갈갈쇼에 시원한 에이드 까쥐 100번 파나마 게이샤 왕궁금했는데 짱맛있었던…! ୧ʕ•̀ᴥ•́ʔ୨ 나 세로 푼타 좋아하네,,, 요즘 빠진 지역 농축 우유 사용하는 라떼도 굳굳', 38, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '주말 오후 합정역 돌아다니다가 맛있는 커피 마시고 싶어서 찾아 들어갔는데요 내부는 아담한 편이라 오히려 시끄럽지 않고 좋았어요!종이필터로 내린 탭커피 정말 깔끔했고, 당충전가득 버터스카치 라때와 디저트 없음 섭섭하니 얼그레이 티그레까지 먹고 나왔어요 :) 사장님 정말 친절하시고 다음번엔 산미있는 커피 마시러 오고싶내요!!', 39, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '평상시 커피는 잘 몰랐는데 직원분께서 커피 설명도 잘해주고 향도 너무 좋아서 재방문의사 100%입니다🫶 특히 명함같이 생긴 카드에 커피원두 설명이 써있는게 마시면서 맛의 노트 잡을 때도 도움이 돼서 커피 초보자도 방문하기에 너무 좋은 것 같아요☺️ 안에 매장 분위기도 있으면 힐링이랑 치유되는 기분이랑 잘 쉬다 갑니당✨️✨️', 110, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '출근전 힐링하러 항상 들러서 커피한잔 마시고 출근합니다 커피에 진심인 바리스타분들이어서 커피맛은 물론이고 너무너무 친절합니다 ~ 근처 이만한곳이 없어요 ㅎ', 34, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '커피를 잘 모르는데도 커피가 주는 맛을 다 느낄 수 있는 곳이었어요! 혼자 와서 작업하는데 분위기도 커피도 다 마음에 듭니다😌. 걸음하는데 아깝지 않아요! 오는 길이 맛있는 커피를 마실 수 있다 생각하면 즐거울 것 같아요🫶🏻', 19, 2, 'GOOD', SYSTIMESTAMP);
