INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '일단 들어가면서부터 친절하게 맞아주셔서 너무 좋았고 바자리에 앉아서 지켜보니 모든 손님께 일관성있게 친절하시더라구요 바리스타님들은 커피맛뿐 아니라 경험과 분위기 서비스를 주시는 분들이라 생각해서 모든게 만족스러운 카페였어요 편안하게 있을 수 있고 두분바리스타님 케미도 좋아서 훈훈했어요 특히나 중요한 커피맛 라떼 향이살아있으면서 우유와의 조화도 좋았고 끝에는 두유맛도 나서 신기했어요 드립은85번 먹었는데 산미가 강하지 않으면서도 목넘김이 편안해서 맛있게 마셨어요:) 담에 서울에 올때도 꼭 들리려고 합니다!', 81, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '너어어어무 맛있어서 어머니도 모시고 왔어요! ㅎㅎ 오랜만에 마셔도 행복해지는 라운지클라리멘토 ㅠㅠ 레몬에이드에 들어가는 레몬셔벗도 직접 만드시더라구요!  디테일하게 신경쓰는 모습들이 멋져요!! 최고', 241, 68, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '하 진짜 너무 많이 쓰면 알바같아서 쓰기 싫은데… 너무 맛있어요. 71번 너무 제스타일…✨ 매번 라인업이 이렇게 맛있을수가 있나 싶네요 증말 그리고 오시면 꼭 바쪽에 앉으세요. 그러면 바리스타님들이 커피 이런저런거 설명 많이 해주셔서 넘 좋아요. 가끔 서비스로 주시는데 다 맛있어요. 맛커는 라운지클라리멘토!!!', 46, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '오픈때부터 가고 싶었지만 발길이 닿지는 않던 라운지클라리멘토에 다녀왔습니다. 저는 원두 후기 이벤트로 받은 탭카피,아메리카노 쿠폰으로 쪼꼬미 블렌드를 시켰고. 유료로 코스타히카 하시엔다 코피이 타카라 모모이로 게이샤를 핫 필터커피로 주문했습니다. 유명인사도 많이 다녀가서 싸인도 많네요 제가 다녀간 시간에 싱가포르 브루어스컵 챔피언까지 다녀가셨어요. 직원분들도 정말 처음보는 사이인데 호스피탈리티가 참 좋으셨어요. 다만 공간이 좁기도 하고 단차가 있어서 작업하기에는 어려웠어요. 유일한 단점이랄까. 잠시 대화하고 지나가기에는 좋은 분위기에요. 작은 공항 라운지 온 느낌', 73, 18, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '진짜 너무 더운데 입장과 동시에 시원한 물도 챙겨주시고 너무 좋아요 ㅠㅠ 77번 세상 맛있어요. 얼음물과 함께 마시는 뜨커란.. 행복🍀 매장도 너무 시원하니 이건 꼭 뜨커로 드셔보시길 추천합니다.', 126, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '종이필터로 내린 탭커피 처음 마셔봤어요! 완전 깔끔한 맛과 향입니다 ❤️ 카페 분위기도 차분하고 깔끔하구 사장님도 친절하시구 귀여우세요 히히 🫶🏻', 4, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '합정에 오픈한 클라리멘토! 이전에는 행사로 왔었는데, 이번에 제대로 방문했네요. 탭커피 처음 마셔봤는데 이 가격에 이 맛이라니,,,, 말도 안됩니다ㅠ 브루잉도 마셔봤는데, 최근에 마신 에티 중에 제일 맛있었어요. 비싸기만 한 커피보다 훨씬 좋았습니다. 식은 후에는 조금 연해지긴 하지만 향이 쭉 이어져서 은은하게 끝까지 맛있게 잘 먹었어요. 처음 입장했을 때는 거의 차있었는데, 직장인분들이 쭉 빠지니 정말 여유롭고 평화로운 분위기라 더 좋았습니다. 나오는 노래도 카페에 어울리게 넘 좋구요…! 다음에 또 옵니다! 추천드려요👍🏻', 76, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '맛있는 커피가 마시고 싶을 때면 어김없이 찾는 곳 바리스타 분들도 너무 친절하셔서 다녀오면 늘 기분이 좋아요. 오늘도 맛있는 커피 잘 마셨습니다 ㅎㅎ', 50, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '합정역 도보로 5 분거리에 카페입니다. 탭커피와 라떼 핸드드립을 마셨는데, 전체적으로 맛이 좋았습니다. 커피를 내려주시는 바리스타님이 친절하시고, 설명도 잘해주셔서 편하게 마실 수 있었습니다 바 테이블이랑 소파테이블 이 구비되어있어서 편하게 커피마시기에도 좋습니다. 브루잉 커피도 다양하게 바뀌어 주기적으로 가서 마시고 싶을 만큼 맛이 좋았습니다.', 46, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '커피에 진심인 지인추천으로 방문한 카페로 생소한 탭커피 처음 경험해봤어요! 필터커피를 지향하는 사장님께서 빠르고 신선하게 제공하기위해 들인 머신ㅇㅣ라고 하셨어요. 종류가 다양한 만큼 커피향과 맛에 대해 상세히 적혀있어 취향에 따라 선택할 수 있어요~ 종종와서 하나하나 다 맛보고 싶은 곳입니다!', 34, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '유튜브 보고 방문했는데 인테리어도 너무 좋고 커피도 맛있고 직원분들도 너무 친절해서 대만족하고 갑니다!!! 다음에 합정올 일 있으면 꼭 재방문하겠습니다😄', 123, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '최애카페의 리뷰 이벤트시작 이건 못참지. 이벤트와 별개로 동네 사람들이 여기 맛있는거 알았으면 좋겠어요. 아니 서울 사람 모두가 알았으면 좋겠어요. 아니!!!! 전국 모든 사람이 알았으면 좋겠어요!!!! 커피 너무 맛있고 직원분들 친절하고 쉬고 간다는 느낌이 너무 좋아요. 진짜 거의 쉬는 날은 여기서 살아요.', 40, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '좋은원두 셀렉션이 있고 그래서인지 커피맛도 좋아서 두번째 방문합니다! 인테리어도 분위기있고 원두종류도 친절하게 설명해주셔서 여기 방문할때마다 즐겁게 시간 보내고 있어요! 또 오겠습니다!', 36, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '본점만 가봤었는데~ 유튜브보다가 궁금해서 방문했어요! 커피가 정말 맛있어요. 산미가 있으면서 끝맛이 달콤해서 더 맛있게 먹었습니다!', 29, 1, 'GOOD', SYSTIMESTAMP);
