INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '합정역 바로 근처에 새롭게 오픈을 한 커피맛집 라운지클라리멘토 고양시에서 넘어 온 카페로 벌써부터 많은 사람들에게 사랑을 받고 있는 카페 여러 유명한 바리스타 챔피언분들을 초청하며, 운이 좋다면 보고 경험도 할 수 있는 공간 내부 공간은 협소한 편이지만 좁지만 멋지고 고급스러운 내부 더 자세한 정보는 최제로 블로그🙇🏻‍♂️🌼', 23, 5, 'GOOD', SYSTIMESTAMP);
