INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '추천으로 방문한 신상카페입니다. 컨셉이 좀 독특한데 탭 커피네요 탭비어는 가봤는데 탭커피라니. 가격도 착한거 같아 마셧는데 괜찬네요 인테리어도 꽤나 공을 들인듯합니다. 여기저기 신경쓴 느낌이 많이 들고 의자나 테이블도 고급스럽네요 심지어 간단해보이는 스피커도 꽤나 좋은거 같습니다. 탭커피말고도 다양한 메뉴가 있는데 필터커피가 꽤나 가격도 착하고 맛있네요 파나마 게이샤가 7000원에 이정도의 맛이라니 아쉬운건 매장이 생각보다 작아 많은 방문객은 힘들듯합니다.', 71, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '맛있는 커피, 훌륭한 디저트가 매력인 카페입니다 오픈 이후로 한달에 한번 이상은 방문하고 있는데 바뀌는 필터 커피는 무엇 하나 빠짐없이 특색있는 맛이 있습니다 바테이블에서 바리스타분들과 즐기는 커피 토크도, 안쪽 소파에서 혼자 또는 여럿과 즐기는 일상적인 대화에도 충분히 만족스러운 경험을 제공합니다', 16, 2, 'GOOD', SYSTIMESTAMP);
