INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '요즘 저의 최애 커피 맛집입니다!! 거리가 멀어서 자주는 못가지만 주기적으로 방문하는 그런 곳이에요. - 직원분들도 친절하시구, 커피도 너무 맛있어서 좋아하는 공간입니다 ☺️ 더더 유명해졌으면 하지만, 제가 앉을 자리는 있었으면,, 하는 그런 곳이에요 🫶🏻', 0, 8, 'GOOD', SYSTIMESTAMP);
