INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '바리스타님들 모두 E가 분명해요 재미있게 마시고 얘기하고 왔습니다 커피 너무 맛있어요 전체적으로 클린한 에프터가 강점인거 같아요 ^^', 8, 4, 'GOOD', SYSTIMESTAMP);
