INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '68번 커피랑 탭 메뉴 하나 마셨는데 맛있어서 원두도 구매했어요! 커피 몇 잔 더 맛 볼 기회도 있었고 직원분들 너무 친절하게 응대해주시고 맛있는 커피로 즐거운 경험하고 갔습니다. 공간도 너무 멋졌어요. 다음에 또 방문하겠습니다 🤸‍♂️🤸‍♂️', 15, 9, 'GOOD', SYSTIMESTAMP);
