INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '커피는 인터리어 더할 나위 없습니다. 실수로 커피를 쏟았는데 친절하게 응대해주시고 쏟은 커피까지 한잔 더 무료로 내려주셨어요 흑흑 커피 맛과 인테리어에 친절에 한번더 감동 받은 곳입니다.', 14, 10, 'GOOD', SYSTIMESTAMP);
