INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '이타다키 게이샤 개맛도리😋 8월 홈바클 탐방 겸 오랜만에 호다닥 이타다키 내려주신 거 마셔보고,,, 잘 내려봐야겠다 맘 먹었습니다ㅋㅋㅌㅌㅋㅋ 진짜 GMDR ୧ʕ•̀ᴥ•́ʔ୨ 덕분에 생일 행복하게 보내고 갑니다', 44, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '지나가다 자리가 있을까 싶었는데 사장님이 정말 친절하게 안내해주셔서 들어오게됬어요. 아메리 65번 과 디카프 플랫화이크 시켰는데 , 필터 커피는 설명대로 향과 산미가 살아있네요. 플랫화이트는 정말 딱 원하는 고소함의 진한 라떼여서 놀랐습니다. 양도 좋구요.. 이 주변에선 꼭 여기오셔서 커피한잔 드셔보시면 좋을것 같습니다 :) 고소한 찐 플랫화이트 를 찾으신다면 추천해요. ( 물론 필터커피두요!)', 46, 1, 'GOOD', SYSTIMESTAMP);
