INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '오랜만에 와도 맛있는 (실은 어제도 옴) 라운지클라리멘토. 커피 좋아하는 친구들 데리고오면 다 맛있다고 하는 커피 맛집. 디저트 바뀌었는데 다음에 한번 먹어봐야겠어요~', 14, 3, 'GOOD', SYSTIMESTAMP);
