INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '더운 여름 날 문을 연 순간부터 너무 좋았습니다. 너무 친절한 직원분부터 맛있는 커피와 편안한 의자에 앉아서 시간을 보냈습니다. 음악도 너무 좋았습니다. 🥰', 16, 8, 'GOOD', SYSTIMESTAMP);
