INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '브루잉 메뉴 다 마싯어요. 특히 이타다키.. 깔끔하고 맛있네요 ㅎㅎ 바리스타분들도 친절하시고 추천도 잘해주세요 앞으로도 합정올때면 자주 들릴거 같아요!', 47, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '남자친구의 추천으로 함께 방문했습니다, 소통을 좋아하시는 분들이라면 개인적으로 바에 앉으시는 걸 추천드려요! 주문한 원두를 갈아주시고 커피를 내리시기 전에 향을 맡아볼 수 있어서 좋았습니다 :) 뒤이어 커피를 마시며 느낀 점들을 공유하며 공감할 수 있게 여러 말씀들을 해주셔서 도슨트님과 매니저님의 따뜻한 마음 또한 느끼고 갑니다! 에티오피아 두완초 맛있어요!!!!!!🧡', 33, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '두번째 방문입니다 ☺️ 탭 커피는 처음인데 너무 신기하고 커피맛도 좋아요 👍 필터커피 메뉴가 많아서 선택하는 재미가 있어요. 깔끔한 인테리어 맘에 들어요!!', 125, 24, 'GOOD', SYSTIMESTAMP);
