INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '커피 만드시는 모습을 보면서 커피를 먹으니까 너무 재밌고 커피 맛 별로 넘버링한 카드가 나오는 것도 재밌어요! 이야기꺼리가 더 생겨서 좋네요:) 노래와 멋진 바리스타님들 그리고 예쁜 공간! 합정에 오면 자주 들러야겠어요', 85, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '분위기 좋고 아담하며 매장이 깔끔합니다~~ 커피맛집으로 인터넷으로 커피 주문하고 근처온김에 직접 들러보고 싶어서 와봤는데 사장님들 친절하시고 넘 좋아요!', 18, 0, 'GOOD', SYSTIMESTAMP);
