INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '오픈첫날엔 메뉴소진으로 휘낭시에만 포장해갔었지만 이번엔 먹어볼 수 있었슴니다 웰컴드링크?로 주셨던 커피(설명해주셨는데 에티오피아인지 어딘지 기억이 가물가물...)가 과일즙같은 느낌이 너무 인상적이라 개인적으로 라노리아보다 맛있게 먹었슴니다 담번엔 따뜻한거도 마셔봐야겠슴', 18, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '커피도 좋고 매장 계시는 분들 서비스도 너무 좋아서 다음에 또 방문하고 싶어요~ 커피잔도 적당한 온도로 따듯하게 만들어서 주시고, 서비스에 신경을 많이 쓰신다는 기분이 들어서 좋았습니다.', 43, 0, 'GOOD', SYSTIMESTAMP);
