INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '잘생기신 사장님께서 친절하게 커피에 대해 설명해주셔서 너무 좋았습니다! 커피에 정말 열정적이신거 같아요! 직원분들도 다 선남선녀시고, 커피맛은 말할 것도 없이 제 취향이었어요! 자주 방문할 것 같습니다 :)', 61, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '일단 커피가 완전 맛있어요. 인테리어도 평범하지 않고 좋아요. 쇼파 좌석에 앉았는데 우리 집 안방마냥 푹신하고 좋았어요ㅋㅋ 합정역 갈 때마다 생각날 듯해요💭', 29, 2, 'GOOD', SYSTIMESTAMP);
