INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '아이덴티티커피랩의 추천을 받고 갔던 라운지클라리멘토!! 티라이크 스타일의 커피가 너무 맛있었어요🥹 거기에 바리스타님들의 엄청난 환대와 설명까지.. 너무 좋았어서 금방 재방문할 예정:)', 28, 0, 'GOOD', SYSTIMESTAMP);
