INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '매번 친절하시고 커피도 음료도 다 만족스러워요 합정오면 일부러라도 꼭 들리게 만드는 장소입니댜 너무 조앆!!!!!!!!!!!!', 24, 4, 'GOOD', SYSTIMESTAMP);
