INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '아메리카노 대신 배치브루가 있어 필터커피 입문하시는 분들에게도 좋고, 로스팅 자체도 잘하는 카페라 커피를 좋아하시는 분들도 만족할만한 카페입니다.', 60, 18, 'GOOD', SYSTIMESTAMP);
