INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '커피 개맛도리😋 TAB 가격 혜자그잡채;; 어떻게 그 가격에 이 맛이 나는지 짱좋아서 kijul ୧ʕ•̀ᴥ•́ʔ୨ 핸드 드립도 짱맛나고 우디한 인테리어 + 대화하기 좋은 공간 힐링하기 최고!!!', 26, 3, 'GOOD', SYSTIMESTAMP);
