INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '들어오자마자 커피향에 한번 취하고 시작하는것 같아요 필터로 내려주시는 모습 보면서 마시니 더 맛있는거같아요😍 앞으로 단골 예약할게요 ㅠ', 14, 7, 'GOOD', SYSTIMESTAMP);
