INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '유명한 로스터리에서 하는 곳이다 보니 커피 진짜 맛있습니다! 이상적인 에티오피아 무산소였네요. 호스피탈리토도 훌륭하고 호텔 라운지 느낌이 물씬 납니다.', 370, 72, 'GOOD', SYSTIMESTAMP);
