INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '★3.9 파나마 어노니머스 게이샤. 기대가 커서 그런가 필터의 깔끔한 느낌은 좋은데 아로마들이 좀 소소하다. 온도에 따라 다채로운 변화를 보여주기보단 단조로운 맛이 유지된다. 머신 필터 커피들도 마셔봤는데 깨끗함은 좋은데 향미는 좀 가라앉은 느낌. 궁금해서 다른 분이 내린 같은 커피를 마셔봤는데 이번엔 산미가 강하게 돌출한다. 요즘 머신 필터 커피들이 좀 나오는데 직접 내린 것같이 맛있을 때도, 좀 아쉬울 때도 있어 일관성이 떨어지는 면이 보인다. 커피 브루잉에 좀 즉흥적인 부분이 있는 것 같다.', 121, 26, 'BAD', SYSTIMESTAMP);
