INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '라운지 클라리멘토'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '맛있는 커피 저렴하게 먹을 수 있어서 좋아요 👍 탭?커피라고 하는 메뉴 기계도 신기하고 맛있네요 !! 자주 들르겠습니다 :>!!!!!', 0, 5, 'GOOD', SYSTIMESTAMP);
