INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '직접 로스팅을 해서 향 좋은 여러 원두를 소개하는 홍대의 말릭커피입니다. 이곳은 네이버 스마트스토어를 통해 원두를 판매하는 등 커피를 좋아하시는 분들께 이미 사랑을 받는 곳입니다. 거기에 더해 매장에서만 맛볼 수 있는 체리파이가 인기입니다. 매장이 지상보다 조금 낮은데 창이 넓어 실내 공간은 꽤나 명랑한 분위기였습니다. 커피 애호가이시거나 홍대에서 데이트 코스를 고민하시던 분들께 방문해 보시길 추천드립니다.', 12, 10, 'GOOD', SYSTIMESTAMP);
