INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '홍대 근처 커피 최애 카페. 아이스라떼 , 체리파이 너무 맛있어요. 아이스크림과 곁들여먹는 체리시럽 듬뿍 올라간 체리파이 시그니처. 겉은 페스츄리 질감, 속은 부드러운 체리파이 꼭 드셔보세요~', 40, 6, 'GOOD', SYSTIMESTAMP);
