INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '근처 왔다가 찜해둔 커피 집에 왔어요 약간 반지하 느낌인데 창이 커서 그런느껨이 없고 손님이 가득차 있어요! 다양한 굿즈도 판매하고 디저트류도 꽤 있고 커피도 에스프레소만 마셨지만, 묵직하고 디저트와 어우러지는 맛이 좋았습니다', 24, 3, 'GOOD', SYSTIMESTAMP);
