INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '여기 까눌레 너무 맛있어요🥹 한국서 먹어본 까눌레 중에 TOP3에 들어가는 듯...👍 제가 홍대에서 제일 좋아하는 장소들 중 하나이고, 한국에서는 가장 좋아하는 카페입니다🤭 까눌레에섬크림블륄레가 느껴지는 엄청난 JMT. . .! 평소에 즐겨먹던 수제 체리파이와 수제 스콘도 무서울정도로 맛있는데 까눌레도 맛있다니...여긴 커피전문점을 넘어서 베이커리전문맛집이라구요...!🥹 사장님 꿈빛파티시엘 주인공이시냐며😂 다음엔 치즈케이크도 꼭 먹어봐야겠어요💪', 42, 7, 'GOOD', SYSTIMESTAMP);
