INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '커피가 맛있고 스콘도 정말 맛있어요. 바삭한 편이고 식감이 좋습니다. 커피랑 잘어울리고 클로티드크림이랑 딸기잼이랑 먹으면 너무 맛있어요!', 37, 9, 'GOOD', SYSTIMESTAMP);
