INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '따뜻한 우드톤의 인테리어의 작은 카페인데 구움 디저트류도 있고, 특히 휘낭시에 덕후 자매는 말릭 카페 기절이요 ㅎㅎ 넘넘 맛있는데.. 늦게 갔더니 한 개 남아서 사이좋게 나눠먹었숨당 하핫 말릭 카페 추천이요오', 200, 84, 'GOOD', SYSTIMESTAMP);
