INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '올해 블루리본을 받은 코지한 커피집 발견 복잡한 홍대 거리 한복판에서 다른 세상에 들어온 것같은 기분을 준다. 반지하처럼 살짝 도로보다 낮은 가게를 통유리창을 통해 들여다보면 아늑한 느낌을 준다. 원목 인테리어에 작은 소품 을 아기자기하게 배치해놔서 볼거리를 준다', 26, 2, 'GOOD', SYSTIMESTAMP);
