INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '필터 드립커피로 페루 마셨는데, 와아.... 진~~짜아!! 눈이 쨍하고 커질 만큼 맛있었어요!! 완전 취저취저😭 페루 아이스로 드세요!!! 완전 맛있었습니다🥹', 18, 9, 'GOOD', SYSTIMESTAMP);
