INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '홍대 골목 커피 강자 말릭..💖 커피에 너무너무 진심이신 사장님이 환대해주셔서 늘 기분이 좋아요. 아니근데 인테리어까지 느좋이라고…', 79, 17, 'GOOD', SYSTIMESTAMP);
