INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '커피가 티라이크한 느낌이라 정말 깔끔하고, 디저트도 하나같이 맛있어요! 매장 분위기도 너무 좋고, 직원분들께서 커피 정보도 너무 친절하게 설명해주셔서 만족스러웠습니다 :) 동네 주민이었다면 바로 단골 됐을 것 같아요!!', 34, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
