INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '홍대 커피 찐 맛집^_^ 서비스최고 진짜열나맛있어 디카페인커피도 진짜 너어어어어어어어어어무맛있어요 스콘 까눌레 꼭 드셔보세요오오오옹^_^', 44, 2, 'GOOD', SYSTIMESTAMP);
