INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '블루리본 스티커 보고 방문했어요 말릭커피 입구부터 취향저격😊 핸드드립 먹으려다가 시그니쳐 너티크림라떼로😎 달달하니 고소하고 맛있어요 인테리어도 아기자기하고 플레이 리스트도 좋아요😘', 29, 10, 'GOOD', SYSTIMESTAMP);
