INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '저 개인 의견으론 드립커피중엔 과테말라 게이샤 커피가 최고 였어요. 과테말라인데 다크 초코렛이나 견과류보다 과일향 이며🍇 꽃향이며 🌸 끝까지 향이 풍부하게 여러가지 맛이 났어요. 그 어디 게이샤 커피 보다 여기가 원탑입니다. 콜롬비아 게이샤는 좀 흙향 나는게 예멘 모카 마타리 느낌이었어요. 또 마시고 싶네요. 과테말라 게이샤^^. 직원분들 모두 친절허세요. 힐링하고 갑니당', 15, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '홍대에서 제일 만족스러운 카페를 찾았어요! 이런곳에서 무산소발효 커피를 만족스럽게 마셔서 너무 행벅했어요! 아메리카노는 애플쥬스 블렌딩으로 마셨는데 진짜 네이밍 완전 찰떡이었습니당..👍🏻 에프터에 남는 향이 정말 애플쥬스여서 재밌었어요! 다음에 또 맛있는 커피 마시러 갈게요! **11월 26일 화요일 검은 우산 가져가신분 보시면 꼭 매장에 가져다 주시거나 연락주세요!! 손잡이에 마스킹테이프 감아놔서 헷갈릴수없는데 왜 바꿔가져가신거에요🥲**', 30, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '주말 오후에 갔더니 꽤나 사람들은 많았지만 은근 회전율 좋아서 바로 자리를 겟할 수 있었고 내 뒤로 사람들이 많았지만 조금 웨이팅을 하니 바로 앉을 수 있었던 같음 원두가 꽤나 종류가 많아서 뭐 마실까 고민이 많이 생기게 되는 집임 이번엔 에티오피아 종류를 선택했는데, 적절한 산미가 있어서 취향저격했음 드디어 체리파이 성공을 했는데 여기 커피도 커피지만, 디저트들을 꽤나 잘해서 갈때마다 시키는 메뉴들 다 성공했음 체리파이는 비주얼 도랐고, 윗부분이 미친듯이 쫀쫀하면서 안에 들어있는 체리필링이랑 너무 잘 어울렸음 휘낭시에는 견과류 향이 고소히 나면서 겉부분은 바삭 안은 적당히 촉촉하니 꽤나 맛있었음', 37, 1, 'GOOD', SYSTIMESTAMP);
