INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '제목은 커피집인데 베이커리가 더 유명한 듯 하다 우리도 체리파이땜 가게 된 핫커피가 미지근한커피;;;물론 요청하니 다시 해주셨는데 ... 음...', 83, 15, NULL, SYSTIMESTAMP);
