INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '인테리어 분위기만 좋은 곳일거라 생각했는데 예상 외의 커피 맛집 ! 직접 로스팅한 커피빈 향이 너무 좋고 여러 종류의 핸드드립 커피를 마실 수 있어요. 디저트로 선택한 피낭시에도 맛있었어요. 단골도 많은 걸보니 카피 맛집 인가봐요. 추천합니다.', 34, 6, 'GOOD', SYSTIMESTAMP);
