INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '인테리어와 소품에 커피 맛까지 모두 잡은 카페입니다. 온라인으로 원두 구매 후 에스프레소로 먹어본 경험이 좋아서 방문했습니다. 좋은 날 아늑하고 편안한 시간을 보낼 수 있었습니다.', 55, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '여기 아이스티가 넘 너무너무너무 먹고싶어서 다시왔습니다 저희 동네에 이런곳이 없다는게 슬플 뿐이고 ㅠㅠㅠ 아이스티 꼭 드세요 ㅠㅠㅠ', 35, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '드립커피(인도바드라)랑 디카페인 아메리카노, 휘낭시에 주문했는데 휘낭시에 맛있고 커피맛도 깔끔하고 맛있네요😊 분위기도 좋고 친절해요!!🤩 다만 일회용잔에 줘서 아쉬웠어요🙃 재방문때는 머그잔에 마시고 싶네요:)', 67, 17, NULL, SYSTIMESTAMP);
