INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '안스타님 유튜브 보고 방문했습니다 대중적인 커피 메뉴도 파시고 스페셜티 메뉴도 있었는데 분위기도 따뜻하고 커피맛도 좋고 응대도 좋아서 만족스러웠습니다 다만 매장 입구 문이 꾹 밀어서 닫겼는지 확인이 필수라 매장손님들 이욤하시면서 덜 닫기는 경우가 부지기순데 추운 날씨에는 자꾸 문열려잇으면서 찬 공기가 들어오더라구요ㅠㅠㅠ 문 좀 고쳐주셨으면...', 22, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '인생 커피집과 치즈케이크집을 찾아냄 그렇게 홍대입구역을 갔는데 이렇게 취향저격인 곳을 늦게 발견한 내 자신 안타까웠음 ㅠ!! 커피랑 체리파이 먹을라고 달려갔지만 체리파이는 이미 솔드아웃이고 내부에는 자리가 꽤 있었지만 거의 만석이었음 나 이후로도 사람들이 꽤 많이 들어왔음 커피원두 종류는 뭐를 골라야할지 고민이 될 정도로 종류가 다양했고 기본적으로 과일향이 은은하게 나서 기분 좋게 즐길수 있는 맛이었음 또 드립커피 치곤 가격이 꽤나 저렴하다고 생각이 드는 집이었음 나중에 원두 도장깨기할 예정임 체리파이대신 치즈케이크 골랐는데, 위에 올라간 시나몬이랑 입에서 녹아버리는 치즈케이크 질감 미쳐버림 하나 더 시킬뻔함 다음 홍대방문시 여기 또 올거임!!', 22, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '아이스 핸드드립(에티오피아 타미루 봄베 72hr 무산소 내추럴) 한잔 먹었습니다. 커피는 맛있었는데, 바리스타님 바쁘셔서 그런지 약간 불친절하셨습니다. 커피에 대해서 좀 물어보고 싶었는데 주문 밀렸다는 말만 하시더라구요. 커피는 맛있었습니다. 아이스로 향을 잘 살리기가 쉽지 않은데 드립 실력은 굉장했어요.', 34, 3, NULL, SYSTIMESTAMP);
