INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '추운 날씨에 우연히 들어간 카페였습니다. 커피에 진심이 모습이 담겨져있는 분주함이 보기 좋아보였습니다.  아늑한 공간. 대화하기 좋은 곳이었습니다', 23, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '매장 분위기가 차분하고 커피 맛에 집중하기 좋았습니다. 컵노트에 나와있는 아로마 플레이버가 잘 느껴졌고 직원분들도 상세한 설명과 친절한 서비스로 전반적으로 매우 만족했습니다 :)', 32, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '비싼홍차티백과아이스티의 콜라보로 고급진 맛이 나는 아이스티와 에티오피아 코체레가 맛있는 드립커피 아이스티 맛집 오늘 손님이 많아 피곤하신가보다...', 32, 10, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '다양한 싱글오리진 드립커피 시켰는데, 전반적으로 연하고 티라이크한 느낌이라서 요런 느낌 좋아하시면 홍대에서 가기 좋은 카페일 거 같아요. 게이샤가 많아서 게이샤 좋아하면 추천드립니당😙', 22, 3, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '유튜브에서 본지 한달쯤 돼서 이젠 괜찮겠지하고 추석 중 방문 필터커피가 유명하지만 나는 라떼파이므로 라떼 마심—딱히 임팩트 없었음 늦더위에 10분 정도 기다렸고 주문후 커피 받기까지 16분 걸린게 아니었다면 더 맛있었을 수도 직원 두분이 쉴새없이 필터 커피 내리느라 넘 바쁘고 매장컵도 다 나가서 일회용잔에 나오고 외부 화장실도 다른 업장과 같이 쓰는건지 최근에 간 카페 화장실 중 기억에 찐하게 남음😅 통창뷰는 예뻤고 평정심을 잃기 힘든 업무 상황에서 유독 친절하셨던 직원 한분이 매우 귀해보였음 카페 자체가 예쁘고 통창 좋아해서 홍대 동선 생기면 재방 트라이할 수도', 9, 10, 'GOOD', SYSTIMESTAMP);
