INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '인도 바드라 Hot 으로 주문했는데 향이 고소 + 담백 한 맛 루즈 피에로 Ice로 주문 했는데 향은 생각보다 산미가 강함 은은한 산미가 아니라 대놓고 산미 그 잡채 은은한 산미는 좋아하지만 취향은 아니어서 내가 루즈피에로 주문했는데 바꿔마심ㅋㅎㅋㅎㅋㅎ 카페 우드+갈색 느낌이라 따뜻하고 인테리어 감각있어서 혼자 작업하거나 둘이 대화하기 좋음! 공간은 작은 편 2인석 8개(?) 정도 였음 (정확하지 않음) 참고 해서 방문 하세엽', 50, 3, 'GOOD', SYSTIMESTAMP);
