INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '분위기좋아요 음악도 가게 분위기랑 맞게 나와서 혼자가서 뭘 하기 좋은 느낌 체리파이 쫀쫀하니 맛있어요 까눌레는 그냥 만든 느낌... 커피 첫 맛은 향이 풍부해서 좋았는데 오래 가진 않더라구요 저어먹으라고 티스푼도 같이 주셨는데 왜 주신지는 모르겠어요ㅎ 무난합니다', 31, 8, NULL, SYSTIMESTAMP);
