INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '유튜브로 안스타님이 방문해서 궁금해서 방문했습니다 알고보니 유명인들이 많이 다녀갔더라구요!(방문했다고 사인을 걸어두는 등 하지 않으셨어요😭😭 그만큼 자부심있으시다는거같아여) 드립시켜먹었고, 원두도 왕창 샀는데 정말,, 근래에 먹었던 원두고 드립중에서 가장 좋았고 깔끔했습니다🩷(왜 유명인들이 가는지 이해가 됨..👍🏻) 근처 들릴 일 있으면 또 들릴게용', 50, 3, 'GOOD', SYSTIMESTAMP);
