INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '라떼맛집 인정!! 컵도 너무 귀여움 그러나... 매장이 작고 손님이 많아서 서비스는 별로임... 화장실도 밖에있는데 불이 안들어옴 ㅜㅜ', 47, 2, NULL, SYSTIMESTAMP);
