INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '말릭 체고십니다 집근처 수많은 카페 제치고 제기준 1뜽 전세계일뜽 커피를 내릴줄은 알지만 많은나라 커피 다먹어봤는데 영국커피 맛잇어서 영국 갈 정도로 커피 좋아하는대 영국갈생각 싹 사라짐 게이샤 원두 남편이 내려줫는데 파나마 온것같앗음 감사해요 파나마 안가게 해주셔서 저믿고 가보세요 캬 휴무날 또 가야징 홍대는 말릭아니면 안감 (집슈니라) 짱짱', 46, 4, 'GOOD', SYSTIMESTAMP);
