INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '일단.. 여기 들어가자마자 커피향이 확~ 나서 너무 좋았어요 ㅋㅋ 친구랑 다른 카페들 너무 사람들 많아서 포기하려다가 우연히 이 카페를 발견해서 들렀는데.. 첫인상이 너무 좋았습니다 ㅋㅋ 제 취향저격 이더라구요 인테리어도 그렇고요 ㅎㅎ 우선 사장님이신지 직원분이신지 다들 훈훈하심돠! ㅋㅋ 커피를 좋아하시는게 느껴졌슴당 분위기 아늑하고 차분하고 좋더라구요! 번창하세여!', 90, 18, 'GOOD', SYSTIMESTAMP);
