INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '홍대 번화가에 있는 매장은 아니지만 커피에 진심이신 분들이 운영하는곳이라 그런지 커피가 너무 맛있어요. 특히, 시그니처 너트커피는 완전 고소함과 커피의 향기가 한꺼번에 훅~~입안에 퍼지며 아주 맛있어요. 양이 적은게 아쉽네요. 👍 👍 👍 👍 👍', 33, 4, 'GOOD', SYSTIMESTAMP);
