INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '이 집 맛커!!!!!!!! 찐이네요☕️🤎 젠다이아가 마신 커피래서 궁금해서 갔다가 반했슴다! 맛커 인정☕️🤎 까눌레도 맛있어요◡̈ 재방문 의사 있슴다☕️☕️☕️☕️☕️', 6, 8, 'GOOD', SYSTIMESTAMP);
