INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '행사가 궁금해서 원두 살 겸 간곳. 첫날이라 그런지 계산대 앞 원두포대가 많이 쌓아넣고 있었고 로스팅 준비하느라 직원분들 손님 와도 정신이 없어보였어요. 행사 원두가 안 보이길래 그냥 드립백 사갔는데 날짜가 2달전인걸 보고 많이 안 사가는가 실망했네요.', 28, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '인테리어가 너무 예뻤어용 원목에 디테일이 많은 가구들이 배치되어 있어서 외국에 있는 카페에 온 것 같았습니다 자리도 의자와 테이블이 너무 높거나 낮지 않아 편안했어요 완전 큰 컵에 아메리카노가 나와 왠지 더 기분이 좋아졌답니당 카페에 오시는 분들도 다들 여유롭고 행복해 보여 남자친구와 좋은 기운 받았어요 ㅎㅎ', 68, 12, 'GOOD', SYSTIMESTAMP);
