INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '커피도 아이스티도 미쳤어요.. 디저트는 다나가서 못먹어봤는데 여기 엄청나군요.. 내가 알던 아이스티 맛이 아녜요 ㄷ ㄷ 대박..!', 11, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '너티크림라떼가 시그니처라고 해서 먹었봤어요. 땅콩향이 진하게 나는 크림이었는데 천천히 먹다보니 밑에 커피랑 나름 잘 어울렸어요. 반지하로 된 카페였고, 테이블간의 거리가 있어서 대화하기 좋을 듯 해요', 82, 13, 'GOOD', SYSTIMESTAMP);
