INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '인근에서 점심먹고 커피한잔 하러 찾은 곳.. 새로 생긴 곳인줄 알았는데 7~8년 된곳이라네요 ㅎ 최근 리뉴얼해서 눈에 띄인듯요.. 조용히 커피한잔 하기 좋고.. 물론 커피맛 좋고요 ㅎ 홍대 뒷골목 감성이 느껴지는 장소입니다', 124, 21, 'GOOD', SYSTIMESTAMP);
