INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '드립 커피 너무너무 맛있어요!! 디저트 종류도 웬만한 빵집보다 맛있습니다 진심으로...🥹 바쁘신데도 불구하고 늘 친절하게 맞이해주십니다☺️', 16, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '아이스티 마셨는데 립톤이 아닌 다른 맛이였어요 그냥 위에있어 먹어봤는데 마음에 쏙 들었습니다!! 그리고 까눌레랑 제빵류를 직접만드시더라구요!!!! 간만에 마음에 드는 카페 발견했습니다', 49, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '커피 맛집이라고 해서 방문해서 드립커피 테이크아웃해서 마셔봤습니다 ! ㅎㅎ 적당히 상큼하고 밸런스 좋은 커피라 서울을 다시 오게되면 방문할 것 같아요 ㅎ 잘 마셨습니다 !', 74, 16, 'GOOD', SYSTIMESTAMP);
