INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '꺅 카페 분위기 완전 제 스타일💛💛 아메리카노는 물론이고 휘낭시에 짱맛이더라구요. 왜 휘낭시에 맛집으로 유명한지 알거 같았어요!! 홍대 가면 또 가고싶은 취향저격 카페에요👍🏻👍🏻👍🏻', 216, 89, 'GOOD', SYSTIMESTAMP);
