INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '사장님이 너~무 친절하시고 아침에 스콘이 없었지만 치즈케익이라도 든든하게 잘 먹었어요!! 제가 간 날 전에 젠데이야님도 방문 왔다더니.... 완전 홀리우드 인정하는 카페더라고요', 49, 4, 'GOOD', SYSTIMESTAMP);
