INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '기다리는동안 맛볼수 있게 내어주신 온두라스도 너무 맛있었는데 주문한 페루게이샤는 아이스로 마셔도 달고 깔끔해서 한입 마시고는 ‘오길 잘했다!’ 라고 생각했습니다😊 바쁘신데도 불구하고 친절한 말릭커피 최고였어요👍', 28, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '홍대 앞 커피 맛있는 카페입니다. 커피 주문할 때 사장님께서 친절하게 알려주셔서, 커피고르기가 편했습니다! 좋은 원두로 맛있게 커피도 마시고, 휘낭시에도 굿굿굿 👍 귀여운 사과와 멍멍이가 곳곳에 있어 넘 귀여워요!', 15, 6, 'GOOD', SYSTIMESTAMP);
