INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '커피도 직접 로스팅 해주시고 자몽에이드도 맛나는 곳~ 커피에 조예가 있는 분들은 자주 찾으시는거 같습니다. 자몽에이드는 신선해요~ 여기 자몽에이드 마시면 다른 곳에서는 못 마셔요~', 118, 20, 'GOOD', SYSTIMESTAMP);
