INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '역시 맛잇어욤 빨대로 먹는것보단 그냥 바로 입으로 들이붓는게 맛잇어요 . 크림이랑 속에잇는 커피랑 같이 마셔지는게 고소하고 좋아요.!!', 14, 2, 'GOOD', SYSTIMESTAMP);
