INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '원두도 다 직접 로스팅하시고 디저트도 다 맛있어요💕 엄청 친절하시고 일회용품 사용 많이 안 하셔서 좋았어요👍👍 인테리어도 이쁘고 판매하는 소품도 아기자기해서 또 가고 싶어요!! 주말이면 사람 터지겠죠? 평일 낮이라 여유롭게 이용해서 좋았어요', 8, 6, 'GOOD', SYSTIMESTAMP);
