INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '나만 알고 싶은 카페! 홍대 근처에 살았다면 매일 가고 싶을 거예요 ㅠㅁㅠ 나오는 트레이도 너무 예쁘고 사장님이 커피에 진심이셔서 커피 좋아하시는 분들은 꼭 가셔서 새로운 커피도 시도해보세요! 매번 아메리카노만 마셔봤는데 시식주신 콜롬비아 원두 덕에 저의 커피의 세계가 넓어졌어요..! 다음에 가면 드립커피 마셔보고싶어요 ~~ 번창하세요!!', 39, 1, 'GOOD', SYSTIMESTAMP);
