INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '홍대 찐 커피 맛집! 디카페인 커피 일단 너무 너무 맛잇다. 드립도 맛있고 에스프레소 커피도 맛있다.  근처에 맛있는 커피 먹고싶을때 가는 곳! 디저트도 맛있는데 나오는 시간이 있어서 일찍 가면 디저트는 못먹을 수 도 있다!', 21, 3, 'GOOD', SYSTIMESTAMP);
