INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '저번에 한번왔었는데 비엔나가 너무 맛있어서 재방문 했어요 ㅎㅅㅎ 그때도 까눌레가 아직 굽는중이라 못먹었는데 오늘도 ㅠㅠ 담엔꼭 먹어보고싶어욤 ...커피가 진짜 너무 맛잇어요 ........ 크림커피류 짱임 ㄷ ㄷ 맛에비해 손님이 적은편인듯.. 진짜 넘 맛잇어요...', 114, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '대한민국에서 가장 멋지고 자주 가고 좋은 카페를 대보라고 한다면 저는 바로 이 곳... <말릭커피>를 말 할 것 입니다... 그만큼 커피 맛 최고! 음료 맛 최고! 디저트 최고! 아니 커피가 맛있는데 디저트까지 맛있을 수 있다고?! 하시겠지만요 그것이 사실이고 진실입니다... 게다가 매장 인테리어도 귀여워서 인스타 감성 카페 뚝딱! 근데 사장님도 무지무지 친절하심 대박대박 홍대에 왔는데 말릭커피에 안 온다?! 진짜 핵손해... 커피를 좋아한다?! 근데 인스타감성도 놓치고 싶지 않다?! 그렇다면 저는 이 곳을 추천할게요!!! 실제로 저는 음료와 디저트를 맛 보고 귓가에서 샹투스가 울렸습니다.. 덜덜 천국 무료 방문 완전 가능~ 분위기와 음악도 좋아서 집중하기도 좋아욤^^ 모두들 꼭 한 번 방문해보세요~♥︎♥︎', 113, 26, 'GOOD', SYSTIMESTAMP);
