INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '커피 환상적. 커피가 너무 맛있어서 디저트는 괜시리 기대를 안했는데요.. 휘낭시에 진짜 기절.. 까눌레 안좋아하는데 까눌레 먹고 놀랐어요 .. 스콘도 맛있습니다만 휘낭시에 강추할게요', 25, 4, 'GOOD', SYSTIMESTAMP);
