INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '어떤 메뉴를 골라도 절대 실패 없는 곳!! 커피 에이드 디저트 분위기 친절함 어느 하나도 모자람 없는 만족도를 느낄 수 있었습니다. 홍대에 와서 안 들리면 아쉬울 정도로 멋진 곳!!!', 66, 17, 'GOOD', SYSTIMESTAMP);
