INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '사장님 친절하시구 크림종류 좋아하는데 다음에 꼭 가게 되면 크림종류 꼭 먹어보고싶어여 ~! 에이드와 커피 너무너무 맛있었습니당 ~!', 40, 7, 'GOOD', SYSTIMESTAMP);
