INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '커피가 친절하고 사장님이 맛있는 곳 :)ㅎㅎ 로스팅실이 바로옆에 있어서 좀 시끄럽지만....! 그것을 감안하고 계속 찾아갈 만한 멋진 곳. ! 한겨울에 라떼를 테이크아웃 하고 충격먹은 이후로 단골이 되었다. 인생라떼는 이런 인연인 거겠지..?', 50, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '자몽에이드 진짜 맛있게 잘 먹었습니다!!! 과육 진짜 듬뿍,, 시거나 달거나 하면 말씀해달라고 하셨는데 전혀 안 그렇고  딱 적당한 신맛과 단맛이라 넘 맛있었어요 ㅎㅎ아담한 가게지만 시원하고 쾌적하고 아늑했어요! ㅎㅎ 넘나 친절하신 사장님 커피 연구 계속하시는 모습이 인상깊었습니다. 번창하세용!!!!', 49, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '일하는 곳에서 가까워 좋은 카페〰️😊 갈때마다 스콘을 꼭 고르게 되는 것 같아요🤦🏻‍♀️ 쿠폰이 있어서 좋고 친구들이 제가 일하는 매장 놀러올때 여기서 커피 사오는데 맛있다 그래용ㅎ 사이즈업.. 원해요..⸝⸝ʚ̴̶̷̆ ̯ʚ̴̶̷̆⸝⸝ 😭 아아! 스콘 담을 용기들고 가면 500원 할인 가능입니다!!! ˃̵͈̑ᴗ˂̵͈̑ 이것은 TMI ! 저도 종종 가는 카펜데 울 매장 고객님중 한분께서 이근처 커피 맛집있다며 홍대오면 이카페만 간다고 이곳 말씀하시길래 바로 저도 안다며 재잘재잘 ㅋㅋㅋ~ 🙄👍🏻 또들릴게요~!', 89, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'MEETING');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '여기 커피 마시다보면 커피의 맛을 알게됨. 그럼 다른 커피 마실 수 없게 됨 ㅠㅠ 그래서 다른커피들 내내 버리고 한시간 걸려서 일주일에 몇번씩 여기로 커피 마시러 가야함 ㅠㅠㅠㅠ 왕복 한시간 반을 투자해도 언더크레마 커피를 마시면 기분 좋아짐. :)', 16, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '오픈 초반부터 갔던곳인데 홍대 숨은 카페 맛집이라고해야할까..분위기도 좋고 이번에 방문하니 인테리어도 바뀌었더라구요 나만알고싶은 카페 커피맛은 물론 훌륭합니다.', 90, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '말릭커피'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '나의 인생카페. 인생커피!!! 커피 맛없으면 절대 못마시고 버리는 1인… 여기 커피 마시고 나면 다른 커피 다 맛없음요 ㅠㅠㅠㅠ  플랫화이트는 진한 커피향과 함께 향긋함 가득.(일반 카페 우유맛만 나는 커피랑 차원이 다름)  드립 완전 깔끔하고 산뜻향긋. 직접 담그시는 자몽티도 완전 꿀맛. 매일 생각나는 커피 :)', 76, 16, 'GOOD', SYSTIMESTAMP);
