INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), 'set메뉴가 많아서 디저트 선택하기 수월해서 좋아요 납작복숭아 먹어보고 싶었는데 요거트 월드에 있다고 해서 방문했는데 오길 잘했어요~ 물복 달고 맛있어요:) 건마시멜로우 꼭 추가해서 드셔보세요 넘 맛있어요^^ 포켓몬 캐릭터랑 콜라보 하고있어서 키링도 겟~~ 에어컨 빵빵해서 친구들과 디저트먹을겸 잠시 쉬었다 가기 너무 좋네요', 43, 6, 'GOOD', SYSTIMESTAMP);
