INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '요아* 같은 요거트전문점이네요. 홍대 정문 바로 앞이라 위치 좋고, 매장도 넓고 깔끔해요. 지인과 조용히 대화 나눌 곳 찾았는데 딱 좋았어요. 초코월드는 꽤 달아요. 1인메뉴엔 없는데 저당메뉴 많더라구요. 다음에 저당으로 먹으려구요.', 12, 7, 'GOOD', SYSTIMESTAMP);
