INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '지난 요월데이 때 먹고 너무 맛있어서 다시 먹으려했는데 마침 8월 요월데이 메뉴도 두바이생초코월드라 바로 먹으러 왔어요! 저당이라 부담없이 먹을 수 있어서 더 좋습니다!!', 30, 5, 'GOOD', SYSTIMESTAMP);
