INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '토핑이 화려하고 제맘대로 조합도 할수있어서 너어어무. 맛있게 먹었어요 우연히 발견하고. 들어왔는데 주변에도 추천해줄거에요. 👍', 11, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '가게가 되게 깔끔해서 마음에 들었던 요거트 월드! 늦게 가서인지 과일 종류가 품절인 게 많아서 아쉽지만.. 그래도 맛있었습니당ㅎㅎ', 19, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '“플레인 요거트 아이스크림의 깔끔한 맛에 다양한 토핑을 더하니 조합이 훨씬 풍성해졌습니다. 상큼한 자몽이 요거트의 새콤함과 잘 어울리고, 코코넛젤리는 쫄깃한 식감을 더해 씹는 재미가 있었습니다. 연유가 은은한 단맛을 보태줘 부드럽게 마무리되고, 벌꿀집은 달콤함과 고급스러운 풍미를 살려줬습니다. 2인용으로 넉넉해 함께 나누어 먹기 좋았고, 토핑 덕분에 먹는 내내 지루하지 않았습니다. 기본 메뉴보다 확실히 특별한 맛을 즐길 수 있어 만족도 최고 입니다.!”', 30, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '요거트 아이스크림이 상큼하니 맛나고  매장이 깨끗해서  편하게  있었네요 주말인데도 사람이 적당해서 조용하니 좋았어요 가족과함께 맛있게먹고가요', 17, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '날씨가 좋아 홍대 나들이 왔는데 북적이는 사람들 틈에 지쳤어요ㅎ 조용한 곳을 찾다 한적한 골목에 상큼한 요거트 카페가 있네요. 커피도 맛있고 요거트충전하니 다시 기분이 업 되네요. 맛있고 조용하고 깨끗합니다 좋아요^^', 42, 9, 'GOOD', SYSTIMESTAMP);
