INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '요아정 비슷한 느낌의 요거트월드 홍대직영점!! 요거트는 말 그대로 요거트였는데 위에 올라간 토핑들이 넘 적어서 아쉬웠습니다. 요거트 맛 자체는 요거트 그 자체였는데, 토핑의 양이 겉만 채워져있어서 나중엔 요거트만 있던 게 살짝 아쉽더라구요! 그래도 시원하게 잘먹긴했숩니다~ 초코요거트는 옛날에 맥도날드의 초코콘이 생각나서 딱딱하게 굳은 초콜릿이 옛 생각이 많이 나는 맛이였습니다! - 개인적으로 추천하는 메뉴  : 초코요거트~', 20, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '아이와 갈만한 카페 찾다가 왔는데 커피도 맛있고 아이도 요거트 아이스크림 맛있다고 하네요^^ 직원분들도 친절하시고 덕분에 즐거운 시간 보내고 와요!', 19, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '화이트의 시원함과 달콤한 아이스크림이 기분좋은 곳^^♡ 맛난 토핑 마구마구 추가하다간 사악한 가격  함정에 ㅋㅋㅋ 조심해야함~', 62, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '요아정!! 첨 먹어봐용 맛있구 이정도 가격이면 그냥 아이스크림 먹는 가격이랑 비슷하니까 막 비싸다는 생각은 안 들어용! 원래 가려던 곳이 문 닫아서 지나가던 길에 온건데 진짜 넘 맛있구 또 오고 싶네용❤️', 46, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '일단 입구 들어오자마자 보이는 매장 인테리어가 너무 깔끔하고 예뻐서 원래 포장 하려고 했는데 바로 매장에 자리 잡았어요!! 매장도 생각보다 넓어서 좋고 친구들끼리 와서 기분 좋게 얘기하기 딱 좋은 것 같은 곳!!😁😁', 46, 5, 'GOOD', SYSTIMESTAMP);
