INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '원래 요거트 아이스크림 자주 시켜먹는데 오늘은 그릭요거트 시켜봤어요!! 배달도 포장도 항상 깔끔하고 맛있고 재료도 신선해서 너무 좋아요 ㅠ 매장도 넓어서 가끔 매장에서 먹기도 해요 제발 없어지지 말고 계속 여기 있어줘요..', 31, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '그릭요거트 가게에서 중요하게 생각하는게 과일 신선함인데요, 요거트도 맛있지만 제철 신선한 과일로 준비해주셔서 든든하지만 가볍게 먹기 좋아요', 128, 19, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '저 요거트월드 진짜 사랑하는데 이런 행사도 해주다니 ㅠㅠ 요월데이길래 새로운 딸기 메뉴 할인 가격으로 먹어봤어용~~ 너무 맛있어용', 42, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '초당옥수수 머선일인가요 ..요월 인생메뉴 찾았어요..!! 옥수수 향이 은근히 느껴지는데, 먹어도 먹어도 안질리는 존맛탱메뉴에요. 시즌메뉴라 사라질까봐 걱정돼서 자주 먹으러 오려구요🌽 저당 요거트 아이스크림도 있고, 역시 홍대직영점 최고네요 매장도 넓고, 깔끔해서 맛있게 먹고 갑니다 또 올게요', 8, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '비주얼이 메뉴판과는 조금 달라서 당황했으나 구성과 맛보고 완전 반했어요!! 생각보다 아이스크림 양도 많고 구성도 알차서 종종 방문할것같아요!!', 103, 20, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '친한 지인분들과 들렀습니다~ 저당 옵션!! 아주 산뜻하고 충분히 달콤해서 이 옵션으로 고르길 잘한거같아요 과일들 듬뿍 얹고도 가격이 만족스럽습니다 💜🤍💙🐇🐈‍⬛ 잘 먹고갑니다~~', 52, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '술쟁이도 푹 빠지게한 요거트맛집이네요 제철과일을 그냥 때려박은 여름 신메뉴가 나왔는데 와.. 이렇게 푸짐할수가 있나요?? 디저트와 음료 종류도 다양한데 넘나 사랑하는 크로플에 요거트를 얹은 요거플 하나 시켜서 아아와 같이 뇸뇸 먹고왔네요 낮 데이트할때 들려도 좋지만 영업시간이 새벽 2시까지라 술먹고 요거트로 해장하고 들어가기에도 딱이에요', 29, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '요거트월드! 집 근처에 생겨서 와봤는데 너무너무 맛있네요. 로투스월드 잘 먹고 갑니다. 양도 푸짐하고 토핑도 많아서 딱 맛있는 요거트 아이스크림! 앞으로도 종종 올 것 같아요!!', 46, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '어제 먹고 맛있어서 또 왔어여 ㅋ 영수증 리뷰시 그래놀라 무료니까 다들 츄라이 츄라이!! 그릭00없어져서 온건데 사실 더 맛있어서 놀랬어여', 63, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '홍대 앞에 생긴 요거트월드 이제 매번 시켜먹지 않아도 되겠어용!!!! 푸짐한 토핑에 상큼함>_< 가게 안도 넓어서 완전 추천합니당👍', 25, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '요거트월드에서 처음 먹어봤는데 달달하고 산뜻하니 맛있더라구요 왜 요거트월드가 더 맛있다하는지 알거같은 맛! 양도 더 많은거 같아요 과일폭탄으로 먹으려다가 집에 쌓인채 썩어가는 과일이 떠올라 요거트아이스크림이랑 파인애플만 사갑니다. 파인애플도 정말 맛있더라구요!', 21, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '진짜 자주 1인 포장하러 오는데 너무너무 맛있고 생각보다 양도 꽤 넉넉합니다! 그리고 사장님도 정말 친절하셔서 올때마다 기분 좋아요. 다만 벌집꿀이랑 저당 요거트아이스크림이 없는 경우가 종종 있어서... 많이 들여넣어주세요..', 80, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '요거트월드는 진짜 좋아하는 최애 요거트 집인데 홍대점도 좋네요. 취식 가능한 공간도 넓고, 요거트아이스크림도 잘 나와요! 홍대 바로 앞에 있고 시원해서 만족. 저희는 멜론에 해바라기씨 초코브라우니 같이 먹었는데 다 맛있어서 잘 먹고 가요!', 36, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), 'ㅇㅈ너무너무너무너무너무 맛있어요:) 요거트월드최고!!!!!!!!!!! 진짜 중독되는 맛…매장도 청결하고 재료도 신선하고 아;; 요거트월드 누가먹냐;; 안녕하세요 ’누‘ 입니다^^~~', 24, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '진짜 맛있어요!! 1인용 컵이 5000원이 안넘는데 크게만 시캬야되고 비싼 다른 요거트 아이스크림 지점보다 훨씬 가성비있고 종류도 다양해요 요거트 러버로서 너무좋아요 1인요거트 유지해주세요💚🍀🥹', 24, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '저당 요거트 아이스크림 판매한다해서 방문했는데 저당은 품절로 뜨더라고요ㅠㅠ 그래서 일반 요거트 아이스크림으로 먹었는데 맛있네요ㅎㅎ 개인적으로 요아정보다 더 맛있는 것 같아요. 아이스크림이 더 부드럽고 맛이 깔끔해요. 다음에는 요거트 아이스크림 먹고 싶으면 여기서 사 먹을 것 같슴니당', 26, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '요거트 전문점이라 그런지 꾸덕하고 맛있었어요 ! 리뷰 이벤트로 주신 그래놀라 양도 푸짐 했고 둘이서 먹어도 배불렀어요 ㅎㅎ 재방문 의사 있습니당 !!', 25, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '취향에따라 토핑을 골라 요거트 아이스크림을 만들어먹으니 아이가 좋아했어요. 매장 깨끗하고 다 좋았는데 테이블간의 간격이 너무 좁아서 대화할 때 좀 불편한 느낌은 있었습니다. 오후 네시반쯤가니 한두자리빼고는 좌석이 다 차있더군요. 요즘 인기이긴 한듯합니다.', 481, 100, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '종종 와서 그릭요거트 포장해가는데 먹을때마다 맛있어서 계속 오게돼요! 저는 기본에 꿀만 먹는게 맛있어서 항상 이렇게 먹는 것 같습니다👍🏻', 91, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '리뷰이벤트로 그래놀라받았는데 넘 푸짐하구 맛있었어요..요거트아이스크림을 여기서 처음먹어봤는데 진짜 맛있네요 요거트 아이스크림 특유의 신맛을 정말 삻어하는데 그런 신맛도 안나고 과일도 신성하고 맛있었어요!! 주변 들를일 있으면 또 방문하겠습니다~~', 23, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '너무너무너무너무너무 맛있어요ㅠㅠ 음식이 맛있고 사장님이 친절합니다:) 맨날맨날 먹고싶은 맛 중독 된거같아요ㅜㅜ 번창하세요 사장님ᰔ', 8, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '자리가 넓어서 조금 기다렸는데 금방 앉을 수 있었어요!  요아정 먹고싶었는데 자리가 너무 없어서 일로왔는데 훨 좋았아요 맛잇구 사람 많아요! 화장실은 밖에 있어서 조금 불편할 수 있어요ㅠ', 43, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '요즘 요거트월드 없으면 못 살아… 항상 배달로만 먹다가 처음으로 매장에서 먹어봤는데 가게 분위기도 너무 좋고 점원 분들도 친절하셔서 매장에서 잘 쉬다 갑니다! 맛은 더 이상 말할 것도 없어서… 홍대 오셨을 때 꼭 들러보세요!', 10, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '요거트아이스크림 먹고싶었는데 홍대에 생겼길래 가봤어요 아이스크림이랑 토핑도 다 맛있고 특히 그래놀라가 맛의 한수네요 그런데 직원들 응대가 좀.. 멍하니 놀면서 수다 떨 시간에 테이블 한 번 더 닦아주면 좋겠네요 메뉴가 아이스크림이라 흘리는 경우가 많은데 한번씩 매장 둘러보면서 테이블 좀 닦으면 괜찮겠어요 매장이 크지도 않던데..', 83, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '너무 맛있어서ᆢ요거트월드 검색했어요. 단맛이 싫어서 블루베리시럽은 빼고 꿀만 부탁드렸는데요. 산미없는 맛있는 그릭요거트에요. 제가 먹어본것중에 제일 맛있었구요. 체리도 넘 실하고 싱싱하고 살짝 편의도 봐주시는 센스👍 왼쪽에 뿌려진것도 넘 맛있어서 잘 배분해 먹었어요. 꿀도 맛있어서 꿀꺽~~~~~ 저희동네는 없고 용산이랑 홍대가 있던데 역시 직영점이였네요. 또 찾아가고싶은 꽉찬 그릭요거트였습니다. 차에서 먹다가 찍은사진이라 죄송해요~', 127, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '50퍼 할인 하길래 들어갔어요!! 할인 품목 먹으려다가 제일 좋아하는 그릭요거트도 팔길래 냅다 그릭으로 먹었습니더ㅜㅜ 너무 맛있어요 꾸덕하고 달콤하고 진심 그릭 좋아해서 많이 먹으러 다니는데 그릭 맛집 인정...☆', 37, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '치즈 크럼블, 초코, 치즈의 조화가 상당합니다. 특히 상큼한 요거트와의 조합이 훌륭합니다. 그레놀라는 굳이 추가할 필요 없을 것 같습니다. 그래도 맛잇습니다.', 6, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '홍대에 일이 있어서 처음 방문했는데 인테리어가 깔끔하고 냉방시설이 잘 되있어서 좋았습니다. 빙수월드 싱글컵을 시켰는데 맛있습니다.', 33, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '산미없는 요거트맛이에요! 넘 시원하구 매장이 넓어서 먹고 갈 수 있어서 짱 좋!❤️❤️ 선택할 수 있는 토핑도 많아서 좋슴둥✊🏻', 36, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '다시 요거트 아이스크림이 돌아온 것이 너무 좋아요ㅠㅠ 요아정갔다가 거기는 배달 전문 매장인지 몰라서 허탕치는 바람에 너무 더웠었는데🥲 요월이라도 있어서 행복했습니다.. 더 자주 갈 것 같아요', 33, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '소식좌이면서 다양한 걸 먹어보고 싶어하는 저에겐 싱글컵이 있는 요거트 월드가 딱인 것 같아요💗 맨날 출석체크하게 될 듯… 너무 맛있고 토핑이 가득해요', 2, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '요거트 월드 정말 사랑합니다. ㄹㅇ 미친맛;; 이렇게 맛있으니까 맨날 올 수밖에 없잖아요,,,,🫶🏻✨ 직원분들도 다들 너무 친절하고 정말 매일매일 오게 만드네요,,요거트 월드에 중독이 되…..🩵🩵 적게 일하시고 돈 많이 버세요 사랑합니다💓', 30, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '미리 얼려놓은 요거트에 주문한대로 토핑 뿌려서 주셨어요. 맛있지만 바로 해주셨다면 더 맛있었을텐데 하는 아쉬움이 살짝 있네요ㅠ', 46, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '미리 아이스크림 짜놓고 냉동실 넣어놨다가 주나봐요 매장에서먹으면 요거트아이스크림이 소프트아이스크림처럼 부드러워야하는데 딱딱해요 배달많고 바쁜건 이해하지만 매장까지와서 먹는 메리트가 사라지네요', 103, 21, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '양도 많고 실내가 너무 쾌적해요 !! 더울 때 들렀다 가기 정말 좋아요 🥰 배달보다 방문해서 먹는게 더 맛있는 것 같아요 ㅎㅎ', 21, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '매장 오픈 1주일도 안 되었다고 하더라구요! 요거트도 맛있구(완전 꾸덕) 체리랑 바나나 베리류 다 신선했어요! 그레놀라는 달달한 편입니다! 사장님 친절하세요! 재방문 의사 있는 곳!', 21, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '맛있어요! 요거트 아이스크림 좋아하는데 먹고 갈 수있어서 좋아요! 저당이있어서 부담없어서 너무 좋아요! 토핑도 다양하고 과일 종류도 많아서 만족스럽습니다!', 56, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '메론에 초코가 이렇게 잘 어울리는건지,, 이제 알았숩니다,, 치케 추가는 아묻따 필수고요,, 양도 많고 토핑 추가하니까 배터져죽을뻔 했스요,,😇 역시 요거트월드 체고,,', 38, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '초당옥수수월드 이렇게 맛있는거였다니,,,;; 매일 먹고싶은데요? 진짜 사장님 적게 일하시고 돈 많이 버세욤~🍀🐒🫶🏻 요월드 짱🩵🩵', 3, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '늘 믿고 먹는 요거트월드! 역시나 맛있어요🥵 사장님도 친절하시고 알바생분도 귀여우세요~! (비밀인데 제 입맛으로는 요아정보다.. 요월이 싸고 맛있는 듯😋)', 45, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '이렇게 양 없는 요거트아이스크림은 처음 토핑밑에 아이스크림 있는거 아님 저 봉우리 세개가 다임 이렇게해서 만이천원? 배달해서 먹은 1인분 아이스크림도 이정도양은 아니였음… 더운날 굳이 찾아서 먹으러왔는데 좀 많이 실망이네요', 9, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '돌아다니는 중에 너무 더워서 들어왔는데 더위가 바로 날아가는 맛이에요ㅠㅠ 세트로 되어있는 메뉴도 많아서 고르기도 편했어요:) 생긴지 얼마 안됐는지 매장이 깔끔하고 좋았습니당!', 7, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '요월드…왜 자꾸 날 일주일에 한 번 이상 오게 만드는 거야…자중해!!! 자중하라구!!!!! 살찌면 책임질 거냐구!!!! 🩵🩵 살쪄도 먹겠어. 요월드 너라면..🫶🏻', 18, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '사장님 그거 아세요? 요월드 좋아하는 사람 손가락 반으로 접어! 했더니 지구가 반으로 접힌거;;; 진짜 미치게 마시ㄸr,,;;', 55, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '요거트월드 홍대직영점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '요거트월드 좋아하지마. -그게뭔데 요거월드 좋아하지말라고 -그거 어떻게 하는건데!!!!! 직원분들도 다 너무 친절하시고 요거트아이스크림도 너무 맛있어요ㅜᰔ  사장님 행복하세요:)', 66, 13, 'GOOD', SYSTIMESTAMP);
