INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '나만 알고싶은 홍대맛집😍 그래도 맛있는건 널리알려야쥬?😂🤣 친한 언니와 너무 맛있게 잘 먹었습니다ㅎㅎ 오늘 점심은 티와이티디서 해결!🧡', 42, 3, 'GOOD', SYSTIMESTAMP);
