INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '여기 레몬에이드 맛있습니다 디저트 빵종류도 너무 맛있습니다 근처 다른 카페보다 가성비 좋고 맛있습니다 그리고 여기 인테리어가 톡특하면서 분위기 좋습니다', 90, 15, 'GOOD', SYSTIMESTAMP);
