INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '3.21 ~ 3.23 공항철도 캐릭터 이벤트가 있어 다녀왔습니다. 1인 1주문 해야 해당 카페에서 진행중인 공항철도 이벤트에 참여할 수 있어 시그니쳐 음료인 TYTD랑 피자베이글 주문했는데 TYTD는 Only Ice 음료인데 카라멜 마끼야또 맛과 유사해서 맛있었고 피자베이글은 진짜 피자 먹는것처럼 치즈 아래 토핑도 많아서 좋았습니다. 그리고 내부는 살짝 앤틱스러운 느낌이고 공간대비 테이블도 많이 구비되어 있어서 여유롭게 커피 한 잔 즐길 수 있습니다. 잠봉뵈르며 소금빵이며 판매중인 디저트들 왜 이리 맛있어 보이던지......', 20, 5, 'GOOD', SYSTIMESTAMP);
