INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '베이커리가 맛있는 TYTD 추천드려요☺️ 저는 잠봉뵈르와 바질 토마토 크런치를 먹어봤는데, 둘다 만족스러웠어요! 잠봉뵈르는 빵이 두꺼워보이는데 딱딱하지 않고 소스가 잘 배어서 겉바속촉 그자체! 정말 맛있어요😋 바질 토마토 크런치는 늦은 오후에 가면 품절인 경우가 많으니 참고하세요!🥺 전 두번이나 못먹음... ✅️1인 자리가 있어요 ✅️내부 조명은 어두운 편이에요 ✅️노트북 하기에 적합한 곳은 아니에요', 26, 3, 'GOOD', SYSTIMESTAMP);
