INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '분위기가 아늑하고 좋네요 쿠키 맛있었어요 지금 리뷰 하면은 선물을 주십니다 주차공간이 있어서 들어오기가 편했어요 입구에 있는분이 엄청 큰데 재밌어요', 127, 24, 'GOOD', SYSTIMESTAMP);
