INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '무화과랑 크림치즈좋아해서 무화과 크치로 먹었어요 생각한 맛이고 넘 맛있었어용 바게트 딱딱하댓는데 딱딱해서 포크 나이프 의미가 없어용 썰다가 포기했어요 전 저런 식감 좋아해서 좋았어요 할라피뇨 한개먹고 너무매워서 식겁쳤어요 .. 포크나이프 티슈 물티슈 다 셀프고 안내가 없어서 계속 왔다갔다 거리면수 가질러 다녔어여 ….', 37, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '요가 운동 끝나보니 너무 배고파서 찾다가 발견한 곳이였어요. 원래는 잠봉뵈르를 먹으러 왔지만 품절이라 크루와상 샌드위치를 주문했습니다. 손님이 적어서 그런지 문 앞 쪽 에어컨은 꺼져있어 아주 쾌적하진 않았습니다.', 5, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '날씨 좋은 날 창가자리에 앉아 샌드위치 먹으면 행복해 지는 곳이에요. 한가한 골목 안에 분위기도 맛도 좋은 집. 지나가다 담에 와봐야지 하고 찜 해놨다 방문했는디 역시 좋네요👍🏼', 37, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '커피랑 베이커리 맛있다고 해서 일부러 찾아왔어요~ 평일 일찍 왔더니 조용하고, 인테리어도 이뻐서 사진도 잘 나와요~ 루꼴라크림치즈바게트랑 아메 먹었는데, 둘다 맛있어요~ 바게트는 너무 딱딱하지 않아서 먹기 괜찮아요~ 일반적인 샌드위치 말고, 다른맛을 원하신다면 루꼴라크림치즈바게트 추천드려요~', 29, 7, 'GOOD', SYSTIMESTAMP);
