INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '지나다니면서 늘 궁금했던 곳이라 들어왔는데 오늘이 3주년 기념이라 생화 향기와 3주년 기념 굿즈 받아서 기분이 좋았어요 스텝 분들도 친절하시고 핸드드립 커피와 에그 타르트가 엄청 맛있었어요 인테리어도 멋져서 또 찾고 싶고 머물고 싶은 카페예요', 39, 1, 'GOOD', SYSTIMESTAMP);
