INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '오늘의 커피 마셨는데 간만에 한입하고 하.. 맛있다.. 라고 느낀 드립이었어요... 그리고 직원분이 넘 친절하셔요 빵은 먹고 싶을 때 바로 사야 할듯해요 왜냐면 이따 먹을라고 눈으로 찜해놨는데 정신 차리고 나니 다 나가버려서 너무 슬펐답니다', 34, 5, 'GOOD', SYSTIMESTAMP);
