INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '분위기 좋은 카페 커피도 좋았어요. 그리고 8/6일 2명 예약에 대해 예약금 만원 환불 바랍니다. 전화 드렸는데 아직 환불이 안되고 있네요.', 28, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '배달로 시켜먹어보다가 우연히 걷다가 카페를 찾음!! ㅋㅋ 매장에서는 소시지빵과 잠바르?빵 소시지빵은 바삭해요 잠바르는 약간 시큼한 소스?가 신기했어요 배달로 비엘티 주문했는데 전 갠적으로 약간의 야채가 있는 싱싱한?ㅋㅋㅋ 샌드위치가 맛나네요 👍', 66, 13, 'GOOD', SYSTIMESTAMP);
