INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '방문했을 때 나가는 손님이 많아서 좋은 자리에서 먹을 수 있었어요. 어떤 메뉴를 시켜도 평균이상으로 맛있을 것 같아요. 다만 빵은 부스러기 때문에 깔끔하게 먹기 힘들었네요. 직원 분들도 친절하셨고, 매장 분위기도 좋아서 또 방문할 예정입니다.', 83, 12, NULL, SYSTIMESTAMP);
