INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '오랜만에 방문했는데, 여전히 사람도 많고 그만큼 에그타르트도 맛있습니다!! 사이즈가 아쉽지 않아서 좋아요~ 다음엔 잠봉뵈르 먹어봐야겠어요◠‿◠', 58, 15, 'GOOD', SYSTIMESTAMP);
