INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '빠삭한 바게트 식감의 샌드위치가 꽤 맛있고 너무 달지 않은 디저트 좋아하면 딸기 타르트 적극 추천해요!!! 안의 크림도 인위적인 단맛보단 은은하게 달달하고 딸기도 신선해서 맛있어요! 드립 커피도 원두맛이 잘 느껴져서 괜찮아요. 평일 오후 2시쯤에 다행히 자리 있었어요. 인테리어도 너무나도 이뻐서 맛 & 멋 다 갖춘 장소에요', 24, 2, 'GOOD', SYSTIMESTAMP);
