INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '빵 종류가 많은데 식사되는 빵이 많은 것 같아요. 간단히 먹고 싶었는데 좋았어요. 사람 많은 연남동에서 시끄럽지 않은 곳이라 종종 이용합니다~~', 34, 5, 'GOOD', SYSTIMESTAMP);
