INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '다양한 디저트가 눈을 사로잡는 곳인데 커피가 진짜 맛나더라구요. 이런 커피 맛집 좋아!!! 바질 크런치는 엄청 바삭하면서도 꾸덕한 크림치즈가 잔뜩 들어서 고소고소~ 거기에 풍부한 바질향이 풍미를 더해줬어요. 반해버렸어요^^ 손님이 많은 이유가 다 있네요!', 2, 6, 'GOOD', SYSTIMESTAMP);
