INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '매장이 예쁘고 분위기 좋아요~ 평일 2시에 왔는데 샌드위치종류는 하나밖에 없더라구요 일찍 와야할거 같아요 빵 맛있어서 다음에 또 올거같습니다!', 90, 13, NULL, SYSTIMESTAMP);
