INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '저녁에 시나몬 크림치즈 퀸아망과 딸기 크림치즈 퀸아망을 사서 집에 와서 먹으려고 하는데 딸기에 곰팡이가 피어서 딸기 크림치즈 퀸아망은 안 먹고 그냥 버렸네요.. 티와이티디 자주 가는 곳인데 이번에 좀 실망했어요…ㅠㅠ', 0, 5, 'BAD', SYSTIMESTAMP);
