INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '출근하는 아카데미 근처라 종종 들르는데~ 크리스마스라고 이벤트도 하고~ 당첨까지 되니 기분이 너무 좋더라구요. 커피향이 너무 좋고 디져트는 모양만 좋은게 아니라 진심 넘 맛있어요~ 오늘은 에그타르트 다음엔  초코 바나나 먹으러 가려구요~', 96, 24, 'GOOD', SYSTIMESTAMP);
