INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '커피가 맛있는 곳. 지나갈 때마다 들르게 되는거 같아요^^ 오늘은 루꼴라바게트샌드위치 먹었는데… 정말이지… 너무!! 맛있어요! 맛을 음미하느라 천천히… 씹었네요. 자주 오고 싶은 곳이예요~', 118, 20, 'GOOD', SYSTIMESTAMP);
