INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '친구따라 방문했는데 가게 분위기도 좋고 커피랑 빵도 정말 맛있어요. 빵 너무 맛있어서 ㅠㅠ 품절되기 전에 추가 포장했어요 히히 🙂', 29, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '네이버예약 후 방문, 예약시 샌드위치 선택하면 선결제해야해서 예약금+샌드위치 결제했는데 주문할때부터 결제했다고 얘기했는데도 새로결제해야한다고 해서 이미 결제했다고 말함. 그랬더니 이번엔 음료는 결제해야한다고 해서 예약금따로 결제했으니 차액만 하면되는거아니냐 했더니 사장님한테 물어보겠다고함. 결국 음료는 새로 결제하고 예약금은 나갈때 취소해주겠다고함. 결제를 이미 다했는데 계속 다시 결제해야한다는것도 그렇고 차액만 하면 간단한걸 굳이 새로 결제하고 취소는 또 나갈때해준다는게 이해불가. 모든걸 사장님한테 물어봐야하는 직원의 대응과 대처가 불만족스럽고 양해를 구하거나 친절하지도 않음 재방문의사 없음 돈아까움', 54, 14, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), 'BELT 샌드위치랑 디카페인 라떼 시켰어요.! 샌드위치 맛집이에요..! 바게트가 정말 맛있어요 🥹 안에 들어가 있는 소스랑 재료들도 너무 잘 어우러져서 앉자마자 다 먹었습니당 🫶', 16, 1, 'GOOD', SYSTIMESTAMP);
