INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '나무(?)카페를 찾고 있다가 발견한 카페! 적당한 베이커리와 색다른 메뉴를 찾고 있었는데 잘 방문 한 것 같아요 😆 잠봉뵈르 샌드위치는 너무 맛있어서 다 먹었고 자두라떼는 정말 자두로만 만들었는지 너무 맛있었고 크림도 너무 부드러워서 맛있게 먹었어요ㅎㅎ', 21, 7, 'GOOD', SYSTIMESTAMP);
