INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '홍대 연남동 티와이티디 커피 진하고 맛있네요 루꼴라 샌드위치와 보슬비에 커피 좋네요 ^*^ * 주말이용시 2시간 변경 에스프레소 3,000₩ 애플파이 4,900₩ 루꼴라 샌드위치 8,800₩', 6, 9, 'GOOD', SYSTIMESTAMP);
