INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '잠봉뵈르 먹고싶어서 방문했는데 가게도 너무 예쁘고 감성있어요 ㅎㅎ 빵 종류 많아서 다 먹어보고싶었어요ㅠㅠ 커피도 빵도 다 맛있어요 ♥️', 9, 8, 'GOOD', SYSTIMESTAMP);
