INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '자주 빵이랑 커피를 먹으러 오는 카페인데, 항상 맛있고 직원분들도 친절하셔서 좋아요! 커피도 맛있는데 딸기라떼가 유명하단 이야길 들어서 오늘 먹어봤어요. 정말 맛있더라구요! 잡 잠봉뵈르도 항상 맛있습니다ㅎㅎ 다음에 또 올게요!!', 4, 6, 'GOOD', SYSTIMESTAMP);
