INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '겉에 바게트가 바삭한 스타일의 잠봉뵈르를 좋아하는데.. 너무 딱 취향에 맞았어요 커피도 맛나고 인테리어도 예쁜 공간이었습니다. 다른 샌드위치도 맛나보이더라구요 궁금해서 먹어보러 또 가려고요', 37, 9, 'GOOD', SYSTIMESTAMP);
