INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '바게트 샌드위치 너무 좋아하는데, 서울에서 근래 먹은것중 제일 맛있었어요. 잠봉 전문으로 하는데보다 맛이 좋네요 !  가게 분위기도 너무 좋아서 커피도 두번 시켜먹었어요^^* 재방문의사 100000%입니당', 26, 4, 'GOOD', SYSTIMESTAMP);
