INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '커피도 빵도 다 취향이라 너무 맛있게 먹고 왔어요ㅠㅠ 🥖🥓🧈 한국으로 치면 거의 뭐 쌀밥에 스팸 조합이랄까? 약속된 맛있는 맛! 💥🌱🍅 고소하고 상큼하고 바삭한 게 진짜 미쳤음 동네에 있으면 매일 갈 것 같아요ㅠㅠㅠ', 31, 6, 'GOOD', SYSTIMESTAMP);
