INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '약속시간보다 일찍 와서 끼니 때울 겸 방문했고 너무 시끄럽지도 않고 혼자오기도 좋은 카페였어요. 아메리카노랑 BELT 샌드위치 먹었는데 커피도 맛있구 진짜 오랜만에 너무 맛있게 먹은 샌듸치라서 감동..ㅜ 다른 빵들도 넘 궁금해요 자주 와야겠어요!', 83, 11, 'GOOD', SYSTIMESTAMP);
