INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '우연히 지나가다 들러서 샌드위치 먹었는데....진짜 요근래 먹은것 중 가장 맛있었어요😆💕💕 최애 바게트 샌드위치....!!! 다른 메뉴도 다 맛있어보여요  🥯 🥐 🥖', 1, 2, 'GOOD', SYSTIMESTAMP);
