INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '바게트 샌드위치가 먹고 싶어서 찾은 집인데 완전 성공한 것 같아요! 루꼴라도 엄청 맛있는데 잠봉이 달고 징짜 맛있었어요! 근데 샌드위치 뿐만 아니라 아메리카노도 되게 맛있었어요! 가게 분위기도 좋아서 나중에 또 오고 싶었어요!', 2, 3, 'GOOD', SYSTIMESTAMP);
