INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '친구들과 점심으로 샌드위치를 먹기 위해 방문! 빵이 다소 딱딱한 느낌이 있었으나, 맛이 매우 좋았다! 카페 내부가 넓고 사장님도 친절해서 다음에 또 방문하고싶은 곳.', 9, 3, 'GOOD', SYSTIMESTAMP);
