INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '잠봉뵈르가 먹고 싶어서 포장하러 들린 tytd! 일단 빵 종류가 많아서 홀려서 정신차리기 힘들었어요ㅋㅋ 목표한 잠봉뵈르 골라서 포장했는데 샌드위치 반으로 잘라서 넣어주셔서 먹을때 너무 편했고, 직원분이 아주 친절하셨어요:) 맛은 말모말모 너무 맛있었어요ㅠㅠ 버터는 부드럽고 잠봉뵈르는 짭짤하고 맛있고 중간에 양파소스?같은것도 넘 잘어울리고 재방문 의사 완전 있어요!!', 48, 4, 'GOOD', SYSTIMESTAMP);
