INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '연남동 베이커리 카페 중에 진심 제일 맛있어요!! 커피랑 음료도 훌륭한데 빵이 진짜 최고 ㅋㅋ 잠봉뵈르 맛집이라고 들었는데 정말 맛있고 오시는 손님들마다 다 잠봉뵈르 찾아요 ㅋㅋ 에그포테이토 베이글이랑 소금빵도 재료 안아끼고 팍팍 만드신게 느껴지고 최고최고!! 커피도 맛있는데 다른 카페에서는 보기 힘든 자두크림라떼도 맛있어요', 47, 3, 'GOOD', SYSTIMESTAMP);
