INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '라떼랑 잠봉 포장했어요! 준비 빨랐고 자주 매장에서 먹던 음식이라 맛은 알고 있는데 전시되어있는 빵이 너무 오픈되어있어서 조금 멈칫 했어요 ㅠㅠ 덮개가 있었으면 더 좋았을 것 같아요!', 50, 4, NULL, SYSTIMESTAMP);
