INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '직원분이 친절하게 안내해주시고 빈려동물 데리고 가기 마음이 편한 곳 같네요 나들이 나오기 좋을 것 같고 여름에 산책하다 날씨가 더우니 강아지하고 쉬는 게 좋읗 듯 하네여', 77, 15, 'GOOD', SYSTIMESTAMP);
