INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '베이커리 카페라서 바로바로 나오는 베이커리를 커피와 함께 마시니 정말 맛있어요. 특히 베이커리의 종류도 가득해서 좋은곳. 분위기도 아늑하고 갬성 느낌 가득하고 커피도 맛있어요. 직원분들도 너무 친절하세요.', 15, 5, 'GOOD', SYSTIMESTAMP);
