INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '연남동에서 제일 좋아하는 카페입니다. 반려동물과 함께 가면 너무나 반갑게 맞춰주시고 빵과 코피가 너무너무 맛있는 것은 두말하면 잔소리. 오래오래 있어주세요. 💕', 119, 23, 'GOOD', SYSTIMESTAMP);
