INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '자두에이드는 처음 보는 메뉴라 마셔봤는데 너무 달지 않고 맛있었러요. 애플파이도 맛있고 브런치하기 좋은 것 같아요. 카페 분위기도 너무 좋아요.', 20, 2, 'GOOD', SYSTIMESTAMP);
