INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '연남동 디저트 맛집 티와피디 완전 추천드립니다 :) 디저트는 매장에서 직접 다 만드시더라고요👍🏻 비주얼이랑 맛 둘다 최고였습니다!!!! 자두크림라떼는 완전 매력적😊 레몬에이드는 상큼하니 딱 좋아요! 음료랑 디저트 둘다 맛있는 곳 티와이티디였습니다!!!', 73, 13, 'GOOD', SYSTIMESTAMP);
