INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '빵 종류가 다양하면서도 먹음직스러운게 많고 커피맛도 좋았던 연남동 카페 티와이티디에요 :) 간단한 샌드위치도 있어서 간단 식사도 가능해요. 시그니처 커피는 비쥬얼도 좋으면서 크런치 씹히는 식감도 좋고, 디카페인 커피 주문도 가능합니다~', 49, 6, 'GOOD', SYSTIMESTAMP);
