INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '카페도 너무 예쁘고 베이커리도 다양한 베이커리가 있는데 매장에서 다 굽는다고 해서 더 인상적이었던 곳이었어요 크림이 가득 해서 달달한 거 좋아하시는 분들은 이 카페가 천국이실 것 같애요', 24, 2, 'GOOD', SYSTIMESTAMP);
