INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '연남동에 이런데가 있다니…💖 디저트 너무 다양해서 고르는데 한참 걸렸지만 실패란 없는 카페 같아요~ 다음에 다시 방문해서 다른 디저트들도 먹어봐야겠어요!!', 42, 10, 'GOOD', SYSTIMESTAMP);
