INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '커피는 맛있었습니다 빵은 밑에 유선지가 깔려있었는데 겉에 탕후루처럼 코팅된 디저트 특성상 떼어내도 빵부분에 붙어 깔끔하게 먹을수없었어요... 이런점들은 개선해야할듯', 0, 2, NULL, SYSTIMESTAMP);
