INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '원래 자주 이용하던곳이지만~ 광야 식사 후 도보 3분이면 갈수있는 거리라 지인들과 함께 커피 마시러 또 갔죠~ 커피도 맛있지만 디저트도 빼놓을 수 없는데요~ 크리스마스 시즌 느낌나는 디저트들이 많이 늘었더라구요~ 특히 말차레드빈 크로와상 이뻐서 집었는데 말차 쵸코와 단팥과 크림이 조화롭고 너무 달지않고 딱 좋았어요. 애플파이는뭐~ 늘 애정합니다ㅎㅎ', 43, 3, 'GOOD', SYSTIMESTAMP);
