INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '소금빵 맛집입니다,, 소금빵 왜 먹나 싶을정도로 안 좋아하는데 여기꺼는 버터풍미도 너무 좋아서 항상 사먹어요 ㅋㅋ 근데,, 빵 집는 집게가 너무 불편해서 ㅠㅠ 진짜 아예 잘 잡히지도않아서… 바꿔주셨으면 하는 바램입니당… ㅠ3ㅠ', 8, 4, NULL, SYSTIMESTAMP);
