INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '샤브로 기다리면서 갔는데 자두크림라떼 맛있었어요! 분위기도 아늑하고 사람 많더라구요 ㅎㅎ 좌석은 불편하였지만 대화하기 좋았어요!', 0, 10, 'GOOD', SYSTIMESTAMP);
