INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '토요일 오전에 포장 방문 했어요 오전에 포장 방문 많이하는데 직원분이 담배피고 손을 안 씻으시더라구요 앉아서 기다리라고 해서 포장모습을 못봐서 그런건지 빵먹는데 찝찝 다른 소금빵집을 찾으려고요... 포장시간은 대략 10분정도 걸렸습니다', 122, 25, 'BAD', SYSTIMESTAMP);
