INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '이전 리뷰에도 있듯이 빵들 위에 초파리인지 벌레가 날라다녀서 거북했어요. 위생관리에 신경을 쓰셔야 할듯. 맛은 그냥 그랬어요.', 50, 9, 'BAD', SYSTIMESTAMP);
