INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '이 동네 카페야 진짜 많지만, 여기가 커피맛집👍 한 잔 더 마시고 싶단 생각이 드는 🤭 힙스러운 분위기인데 왠지 모르게 편하긴 합니다ㅋ 디져트도 다양하고 다 맛있네요👌', 20, 0, 'GOOD', SYSTIMESTAMP);
