INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '바로옆에 오뎅바 아이시떼루오뎅 웨이팅할때 머물기 딱 좋은 곳이에요!!! 커피도 맛있고 분위기도 좋아요~ 카페에서 수다떨고 있으면 오뎅바 사장님이 전화주셔서 바로 갈수있어서 딱이에요!!!', 14, 8, 'GOOD', SYSTIMESTAMP);
