INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '오랜만에 가도 늘 편하고 좋네요 메뉴도 계속 신메뉴가 생겨서 항상 발전하려고 노력하는 곳 같아요! 부모님과 남자친구 모두 좋아하는 곳입니다👍', 27, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '주말 늦은 오후에 방문했더니 베이커리가 많이 소진돼서 포장도 못해왔네요ㅠㅠ다음엔 일찍좀 방문 해야겠어요~직원분들 친철하시고 인테리어도 너무 좋아요~커피도 빵도 구우우웃👍', 58, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '피치 우롱티..? 진짜 무슨 맛인지 모르겠는데 커피는 그럭저럭. 베이글이 너무 맛있어보여서 사려했는데 무슨 초파리들이 매장에 너무 많이 날라다니네요(직원분들이 전기채로 잡고다니시긴하는데..;;)  입맛 뚝 떨어졌지만 배고파서 그냥 사먹었어요 디저트도 그닥 맛있진 않았네요', 24, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '세상에나.. 너무 맛있어서 사진찍을 생각도 못하고 다 먹어버렸어오..ㅠㅠ 빵 먹다가 마싰어서 또 시켜서 더먹었어요 에그마요 소금빵이랑 크림치즈베이글(안에 무화과 들었음) 개존맛탱 몇개 포장해갑니다', 50, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '겉에서 보고 작은 카페일 거라고 예상했는데 창가석과 테이블석이 고루고루 잘 구성되어 좌석이 은근 많아요. 개인이든 3-4명 정도의 단체이든 방문하기에 나쁘지 않아요. 매장 안쪽으로 베이킹 공간, 화장실까지 다 갖추어진 넓은 공간이 있고, 무엇보다 빵 종류가 꽤 많은 편으로 나름 작지 않은 가게예요. 매장 음악소리가 크게 틀어져 있고, 구조 상 소리가 울리는 편이라 집중이 필요한 작업보다는 대화 나누는 공간으로 더 걸맞아요. 베이커리랑 커피 맛이 준수하고, 직원분들 친절도가 정말 높은 편이어서 기분 좋은 시간 보내고 왔어요!', 40, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '여기 잠봉뵈르 진짜맛있어요 슴슴슨 잠봉뵈르스타일은 아니고 안에 타르타르소스같은게 들어가서 짭짤하고 한국맛이 많이나는 스타일의 잠봉뵈르입니다! 빵정말 맛있는데 항상가면 날파리가 너무 날라다녀서 직원분이 계속 부채질 하고계시더라구요ㅠ 어디가문제인건지는 모르겠지만 꼭 개선해야될 문제같아요', 75, 12, 'BAD', SYSTIMESTAMP);
