INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '소금빵먹으러 갓는데 따숩게구워 잘라주시니먹기 편하고 맛잇엇어요 ㅎㄹ 엔틱한 분위기가 멋잇엇습니다 다른빵듳도 맛잇어보이던데 다음에먹어봐야죠', 6, 2, 'GOOD', SYSTIMESTAMP);
