INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '집앞에 친구들 왔다길래 여기서 봤습니다. 비싼데 괜찮아요. 테라스를 열어 놓으셔서 그런지 모기를 잔뜩 뜯겼지만 ㅠㅠ 가볍게 디저트와 차 마시기 무난한 곳입니당', 19, 8, 'BAD', SYSTIMESTAMP);
