INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '이번이 세번째 재방문이에요. 분위기 좋은 연남동 디저트 카페💓 인테리어도 멋지고 귀여운 댕댕이도 있어요~ 베이커리 종류도 다양해서 좋아요', 40, 10, 'GOOD', SYSTIMESTAMP);
