INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '연남동 갈때마다 들르는 이곳 바로 tytd. 애플파이와 딸기페스츄리는 나의 최애 디저트. 커피와 함께한 나의 최애 디저트는 어디서도 맛볼수 없는 행복을 주는 작품. 감성을 불러 일으키는 음악소리의 편안함과 실내인테리어 분위기는 나를 tytd로 빠져들게함. 💗뽐뽐💗', 33, 0, 'GOOD', SYSTIMESTAMP);
