INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '사진 속 음료는 아이스 루이보스 애플 레몬 티와 아이스 스트로베리 라떼입니다. 딸기 시즌이라 딸기라떼를 주문했는데 딸기가 듬뿍 들어있어서 맛뿐만 아니라 식감까지 너무 만족스러웠어요. 겨울 지나기 전에 드셔보시는 거 추천 드려요!!', 22, 5, 'GOOD', SYSTIMESTAMP);
