INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '반려동물 동반 가능했던 tytd!! 시그니쳐였던 바질 크런치빵이 정말 인상깊게 맛있었고! 넛티크림이 올라간 시그니쳐 음료도 맛있었어요!👍👍', 37, 4, 'GOOD', SYSTIMESTAMP);
