INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '가자마자 최애카페 후보로 등극💛 너무너무 예쁘고 && 빈티지 느낌 낭낭 포토존 거울 너무 탐나 디저트 맛있고 빵도 잘라주세용 최고❣️ 소파라 의자도 왕편함', 30, 5, 'GOOD', SYSTIMESTAMP);
