INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '이 동네에서 유명한 까페에요 항상 사람이 많아요 근처에 늦게까지 하는 곳 많이 없는데 늦게까지 해서 좋아요 빵 종류가 다양한데 다 맛있어요 크림 크로와상은 달달한데 크림도 많이 들었고 패스츄리 식감도 좋았어요', 55, 17, 'GOOD', SYSTIMESTAMP);
