INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '연남 최애카페! 빵 종류도 많고 커피도 맛나고 강쥐가 넘 귀요미임 ㅠㅠ. ㅠㅠ 직원분들듀 친절하셔유 빵 맛있어서 자주 포장하러 들릴거 같아요!!!! 인테리어도 갬성 오짐', 65, 15, 'GOOD', SYSTIMESTAMP);
