INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), 'Tytd 커피 & 소금빵 추천 소금빵 꽤 사이즈 크고 제 기준 소금빵 넘버투 맛집이에요 잘라서 나와서 먹기 좋아요 커피도 맛나유 아인슈페너류는 시간지나면 커피부분이 밍밍해지는데 여기는 안 그래요', 8, 3, 'GOOD', SYSTIMESTAMP);
