INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '휘낭시에 식감이 제가 아는 겉바속촉 보다는 부드러운 파운드케익 같은 느낌이였어요! 그래도 무화과 맛은 톡톡 씹히는게 맛있었어요!!', 25, 0, 'GOOD', SYSTIMESTAMP);
