INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '홍대 최애빵집중하나! 바질크런치 파삭파삭하니 안에 바질 크림도 맛있어요. 과하지않은 맛이라 더 좋았던 듯🙂 커피랑 먹기 딱이쥬', 14, 4, NULL, SYSTIMESTAMP);
