INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '구석진곳에있는데 엄청 사람많아요 ㅎㅎ 좌석도많아서 회전률은 좋네요 빵종류 많아서 고르기 행복했고 다 기본이상이라 맛있었어요 ㅎㅎㅎ', 28, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '오틀리 라떼와 함께 베이커리 라인 중에서 누텔라 바나나 페스츄리를 주문했습니다. 테이크아웃하면 음료는 500원 할인됩니다. 베이커리는 테이크아웃 하면 종이봉투에 예쁘게 담아주시는데 이 빵은 생각보다 크고 묵직합니다. 이 페스츄리는 정말 진한 초코 그 자체입니다. 바나나 조각들이 더 쫀득한 식감을 만들어줘요. 평소에 초코바나나를 좋아하시는 분들이라면 드셔보는 것을 강추드립니다!!', 77, 11, 'GOOD', SYSTIMESTAMP);
