INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '디저트 만드는 곳이 통창으로 분리되어 있어 디저트가 맛이 없을 수가 없고 소금빵은 식어서 그런지 그냥 그랬고 까눌레와 빨미카레는 존맛입니다 ! 카야 크로와상도 맛있는데 오늘 매장 방문 했을땐 없더라구요 ㅠㅠㅠㅠ 애매하게 대기업 프렌차이즈 가기는 싫을때 종종 오는 카페라 추천해요 🫶🏻', 66, 11, 'GOOD', SYSTIMESTAMP);
