INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '티와티디 카페의 시그니처 커피인 tytd는 헤이즐넛 베이스로 너티맛이 나요. 그래서 일반 카페라떼보다는 훨씬 더 달달한 편입니다. 오틀리 라떼는 산미 없이 고소하며 진합니다. 빈티지한 유럽풍 인테리어를 갖춘 카페예요. 인기가 많은 카페라 그런지 특히 오후에는 좀더 시끌벅적합니다. 자유롭게 대화하는 걸 좋아하시는 분들은 충분히 그 분위기도 즐길 수 있을 것 같아요. 개인적으로 몇몇 의자나 테이블이 조금 불편했어요. 균형이 맞지 않아 두 번이나 쏟을 뻔 했습니다. 그래도 카페 내에 이용할 수 있는 좌석이 많으니 카페를 천천히 즐기실 분들에게는 사전에 꼭 확인하고 이용하는 걸 추천드려요!', 49, 1, NULL, SYSTIMESTAMP);
