INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '산미 없이 고소한 오틀리 라떼와 따뜻한 애플 베리 티를 주문했어요. 두 음료 모두 진하고 맛있었어요. 오후에 대화하기 좋은 카페입니다!', 16, 3, 'GOOD', SYSTIMESTAMP);
