INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '여기 근처 오면 뽑기식으로 카페 하나 골라서 들어가는데 여기 완전 맛집이에요 시그니처라떼랑 아이스아메리카노 다 추천합니다 디저트도 진짜 맛있어요 크루와상 피넛으로 먹었는데 굿굿 쿠키도 안에 마시멜로 너무 맛있구요 분위기 엔틱하고 좋은데 수다떨기 좋음', 85, 11, 'GOOD', SYSTIMESTAMP);
