INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '바닐라라떼는 느끼함이나 부담스러움 없이 맛있고, 소금빵이 겉바속촉 버터향 고소하구 맛있어요..! 직접 잘라주시기 까지 해서 먹기 넘 편하구 인테리어도 예쁩니다. 무엇보다 다닥다닥 붙어있는 좁은 카페가 아니라 쾌적하고 좋습니다 :)', 3, 5, 'GOOD', SYSTIMESTAMP);
