INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '소금빵 먹고 싶어 방문했는데 오후5시쯤가니 품절인지 없어 아쉬웠습니다. 대신 치아바타랑 피자빵 먹었눈데 쫄깃하구 맛있었어용 ㅎㅎ 다음에는 소금빵 먹으러 일찍 방문해봐야겠어요', 84, 17, NULL, SYSTIMESTAMP);
