INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '홍대 올때마다 빵이랑 커피 맛있어서 방문해요! 항상 맛있어서 단체주문도 했네요 직원분들도 항상 친절하시고 맛도 항상 좋아서 홍대 원픽이예용!!', 63, 15, 'GOOD', SYSTIMESTAMP);
