INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '커피도 맛있는데 디저트도 진짜 맛있어요 요즘 티와이티디 까눌래에 빠져서 자주 시먹고있어요. 소금빵도 겉바속촉 딱 제가 좋아하는 스타일입니다. 시그니처 음료 tytd도 꼭 드셔뵤세요', 30, 4, 'GOOD', SYSTIMESTAMP);
