INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '조용한 카페를 찾다가 빵도 맛있어보여서 방문했어요. 늦은 시간에 가서 빵 종류가 거의 품절이었지만 맛있었어요! 헤이즐넛 콘파냐에 들어가는 헤이즐넛 크림이 정말 고소하고 맛있어서 추천하고 싶어요💛', 67, 18, 'GOOD', SYSTIMESTAMP);
