INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '여기 분위기, 인테리어, 커피는 좋은데 남자 사장님이 너무 불쾌합니다. 빵을 만들고, 계속 진열하러 왔다갔다 하시는데, 단 한번도 마스크를 제대로 쓰신 적이 없어요. 항상 턱에 걸쳐놓고 계셔서 빵 먹기가 찝찝합니다. 그리고 매장에 귀여운 개가 있는데, 심하게 짖은 것도 아닌데 남자 사장님이 와서 개 턱을 잡고 흔들면서 주둥이를 좀 때리셨는데 보기 너무 힘들었습니다. 저도 개를 키우는 입장이라 그런지 작은 개가 조금 짖는다고 그렇게 때리시는건 옳지 않다고 생각해요. 그리고 개를 데려오시는건 본인 욕심 아닌가요? 본인이 원해서 끌고오면서 ㅠㅠ 개가 소리를 낼 수도 있죠 ㅠㅠ 때리지 말아주세요.', 35, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '커피가 정말 맛있어요. 빵도 종류가 많았는데 다 맛있어보였어요. 분위기가 조용해서 친구들과 대화하면서 커피한잔 하기 넘 좋았어요', 4, 6, 'GOOD', SYSTIMESTAMP);
