INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '매장에 가보니 강아지가 있더라구여 오픈형매장이라 이런거에 민감하신분들은 방문 고려해보시고 바질 크런치가 엄청 맛있고 소금빵은 그저그랬어요,, 다른빵들도 맛있어 보였어요', 89, 12, 'GOOD', SYSTIMESTAMP);
