INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '여기 연유 라떼 진짜 맛있어요 ☕️ 원두가 딱 제 입맛이었어요~! 달달한 연유랑 원두 조합 최고 ☺️ 사장님도 넘 친절하셔서 기분 좋게 먹고 나왔숨당 🫶🏻', 85, 12, 'GOOD', SYSTIMESTAMP);
