INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '메인이 소금빵인듯 해서 먹어봤는데 다른데보다 더 고소하고 더 짭조롬해서 제입맛에는 맛있었습니다. 커피도 평타 이상은 하는듯 해서 다음엔 좀더 다양한 디저트를 먹어보고싶네요', 41, 9, 'GOOD', SYSTIMESTAMP);
