INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '자리마다 의자가 조금씩 다 다른데, 테이블이 낮아서 앉기 불편한 자리도 있더라고요 오후에 갔더니 디저트 종류는 거의 매진이었습니다', 32, 6, NULL, SYSTIMESTAMP);
