INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '카야 크로아상이랑 레몬 얼그레이 스콘 먹엇어용 무난무난합니다! 제가 앉은 자리는 테이블이 넘 낮아서 아쉬웠어요ㅜㅜ 내부 인테리어는 러프한 콘크리트 벽 느낌!? 강아지 두마리가 잇던데 넘 귀여워요🥰', 24, 1, 'GOOD', SYSTIMESTAMP);
