INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '음료도 맛있었고,  에그마요 들어간 소금빵 먹어봤는데 너무 맛있게 먹었습니다!! 맛있어서 그냥 흡입했어요! 그 날 바로 먹기를 강력추천해요 ㅎㅎ 분위기도 좋았어요. 저녁~밤 타임이었는데 딱 좋았습니다!! 다음에도 방문할게요~!!', 48, 6, 'GOOD', SYSTIMESTAMP);
