INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '신메뉴 헤이즐럿 콘파냐!! 처음먹어보는 메뉴인데 넘넘 마싯네요~ 위에 뿌려진 토핑과자가 에스프레소랑 너무 잘어울려요! ㅎㅎ 올때마다 느끼지만 분위기 유럽온 느낌 무엇..?ㅋㅋ', 59, 11, 'GOOD', SYSTIMESTAMP);
