INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '하,, 사진 안 찍은게 너무 아숩.. 우선 사장님은 너무너무 친절하시고 쿨내 개쩜ㅠ 빵들도 다 평타 이상이고 커피맛도 너무 좋아여... 집앞에 이런 카페 있었으면 주말 오픈해서 맨날 갈텐데..ㅠㅠ 너무 좋앙😭👍', 9, 8, 'GOOD', SYSTIMESTAMP);
