INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '바질크런치 너무 맛있는데 먹다보면 살짝 물려서 여럿이 갔을 때 시키면 좋고 샌드위치, 계란소금빵 같은 식사빵도 맛있습니다! 대만족', 43, 4, 'GOOD', SYSTIMESTAMP);
