INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '보통 베이커리 카페는 커피가 별로인 곳이 많았는데 여기는 빵도 맛있는데 커피나 음료가 정말 👍🏼👍🏼 맛있어요.  특히 바질크런치 완전 추천드려요 !!!!', 1, 0, 'GOOD', SYSTIMESTAMP);
