INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '연트럴파크 홍대입구 코앞인데 막상 또 번잡하지는 않아서 노트북 작업하기 딱 좋음👍🏻 스피커 짱짱하고 브금도 내 스탈이네유 날씨 따뜻해져서 출입문 열어놓으니 살랑살랑 바람불고 넘 좋음😍', 36, 10, 'GOOD', SYSTIMESTAMP);
