INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '오다가다 궁금해서 방문해봤는데 인테리어며 빵,커피 너무 맛있고 갬성 가득한 곳이에영 ㅠ 심지어 갱얼쥐들도 있어서 넘 만족... 직원분들도 친절하시구 다음에 또 방문의사 있어요~!', 40, 5, 'GOOD', SYSTIMESTAMP);
