INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '홍대연남 tytd에 커피가 고파 들렸는데 제빵실에서 갓 만든 신선하고도 건강한 빵이 좋아 올때마다 테이크아웃을 꼬~옥 하게 되네요. 언제 들려보아도 기분이 좋아지는 카페중에 카페입니당!!!', 9, 8, 'GOOD', SYSTIMESTAMP);
