INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '홍대서 인생커피 만나고 왓어요,,티와티디 시그니처.. 존맛탱👍🏻 앞 &뒤 통유리창 너무 특이하고 넓찍해보였으며,카운터가 중앙이라는점도 독특했고  세면대 우리집으로 훔치고 오고팠음요 ㅠㅠ 빵수니 빵 털어왔다구뇨,.. 또 갈게요 ㅜㅜㅜ쌰쟝님 💓', 47, 10, 'GOOD', SYSTIMESTAMP);
