INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '가격대는 살짝 있는 것 같은데 깔끔하고 괜찮아요 라우겐 베이글은 쫀득했고 아몬드 크라상은 많이 달지 않으면서 가벼운 타입이었습니당 근처라면 한번쯤 들러볼만 해요~ 근데 빵은 뭘로 덮어주시는 게 좋지 않을까 싶어요', 20, 7, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '이곳저곳 빵지순례 하는거 좋아하는 빵순이 1인 홍대에 새로운 베이커리 오픈해서 다녀왓는대 우선 베이커리 종류가 많아서 좋았어요 소금빵부터 휘낭시에 에그타르드 잠봉뵈르까지 여러종류 먹어봤는대 제 원픽은 잠봉뵈르 ! 진짜 존맛입니다 ㅠ 다른 베이커리도 넘넘 맛있어서 빵수니는 여기에 돗자리 폈습니다 커피도 넘 맛있고 코시국에 잠시나마 유럽 분위기를 느낄 수 있어서 행복했어요 ㅠ ㅠ 집이랑 쫌만 가까웠다면 방앗간이었을텐대,, 거리가 좀 있지만 조만간 또 방문할예정임당👍🏻', 11, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '4월 4일 군입대 앞둔 조카가 친구들과 집에서 모임한다기에 베이커리카페 tytd에 들려서 테이크아웃을 하였어요. 카페에서 직접 구운 빵들이 맛도 텍스쳐도 고급지고 신선하다고 모두 좋아합니다**) 홍대역에서 2~3분거리이고 코앞에 연트럴파크도 있어서 지인들과 모임하기 딱 좋은 카페네요. 맘에 드는 카페로 찜하였어요 지주 오게 될 것 같아요.😀', 6, 0, 'GOOD', SYSTIMESTAMP);
