INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '커피맛도 좋고먹어본 빵들이  다 맛있어요.그중에 누텔라 바나나 취향저격에 커피랑 먹기 좋았어요. 직원분들도 친절하고 연남동이지만 그나마 한가하고 기다리지 않아서 좋았어요. 아쉬운건 의자가  작고딱딱해서 좀불편했어요.', 90, 17, NULL, SYSTIMESTAMP);
