INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '빵좀 먹었봐다는 빵순이에요 ㅎ 이집 진짜 디저트면 디저트 커피면 커피 빼 놓을게 없는 맛집입니다 잠봉뵈르는 씨겨자가 들어있어서 느끼한 맛을 잡아줘요ㅎ 특이하고 너무 맛있게 먹었어요 !!그리고 바질 크런치 핵강추입니다 꼭 먹어보세요 ~좋은 분위기에서 힐링했습니다 또 방문의사있어요  ㅎ추천해요', 9, 0, 'GOOD', SYSTIMESTAMP);
