INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '노출 콘크리트 인테리어, 낮은 테이블이 특징이라 사진이 엄청 잘 나오지만 아주 편하진 않아요! 참고하시면 좋을 듯해요 커피 너무너무 맛있어서 행복한 시간이었습니다 ♡', 21, 7, 'GOOD', SYSTIMESTAMP);
