INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '연트럴파크 옆에 새로생긴 카페 있다며 친구 추천으로 갓는데 자리가 편해서 너무 좋았답니다! 자주 갈듯용 ! 시그니처 커피 핵맛.. 빵은 넘 달지않고 맛잇엇어용 💞', 35, 9, 'GOOD', SYSTIMESTAMP);
