INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '홍대역 근처에 분위기 좋은 빈티지한 카페가 생겼더라고요! 여기 빵이 너무 너무 너무 제 스타일이에요 ㅠㅠ 특히 잠봉뵈르 진짜 맛있구요! 다른 빵들도 너무 맛있어서 포장해갔네요! 사장님도 친절하시고 커피도 넘 맛있어요 💜👍🏻 또 올게요!', 89, 15, 'GOOD', SYSTIMESTAMP);
