INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '새로오픈해서 와봤어요 연남동에 주차장있는카페 잘없는데 좋은것같아요 빵&커피 모두 훌륭해요:) 아들도잘먹네요 재방문의사있어요❤️', 28, 4, 'GOOD', SYSTIMESTAMP);
