INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '홍대 베이커리맛집으로 소문난 곳이라 해서 방문해보았습니다 빵 종류가 많아서 고르는데 오래걸렸네요ㅋㅋ 애플파이 넘마싯어서 강추합니다! 번창하세욤👍', 4, 7, 'GOOD', SYSTIMESTAMP);
