INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '별로예요! 1. 딸기라떼 시켰는데, 너무 연하고, 우유비린내가 나고 (이게 말이됨..?), 과육은 큰데 빨대입구는 좁아서 먹기 불편했음. 가격도 퀄리티에 비해 너무 비싸요! 과육 쪼끔에 우유만 한가득이였음 2. 문을 열어놔서 완전 모기 파티입니다… 3. 1인석 인테리어만 보면 책 읽기 좋은 분위기 일것같아보이는데, 전혀 아님……….', 51, 15, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '홍대(tytd**)매장내에서 베이커리를 직접 구워내는 카페!! 잠봉뵈르와 라떼 한잔으로 코로나 우울감 훅 떨치고~ 이국적인 신선한 분위기에서 만땅 충전하고 가네요~ 나만의 공간을 득템한 이 기분 ㅎㅎ 자주 들리게 될 것 같아요~', 108, 25, 'GOOD', SYSTIMESTAMP);
