INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '분위기 좋고~ 인테리어도 멋지고~ 라떼와 디저트!! 맛이 너~무 너~~무 좋아서 자주 와요.ㅎㅎ 집에 오는 길에 맛난 빵을 테이크아웃해서 왔네요. tytd카페 방문하시면 만족하실거예요. 강추해용~', 27, 3, 'GOOD', SYSTIMESTAMP);
