INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '짧은 사이에 두번째 방문이네요ㅎㅎ 프랑스식 샌드위치가 있는지 몰랐는데 정말 너무 맛있어요~~ 재료도 끝부분까지 두께하나 얇아지지 않고 푸짐하게 채워주셔서 진짜 감동했습니다.. ㅜㅜ 여기저기 지인들한테 소문낼 예정이에요! 최근 가본 카페중 제일 맛있고 가성비 좋은 것 같아요 :-)', 46, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '지나가다 들렀는데 인테리어 너무 예쁘고 분위기도 좋았어요 아예 빵을 굽고있는 베이커리 존이 있어서 먹기전부터 기대 엄청했는데 역시나 👍 맛있었어요 연남동 들르면 또 가려구요', 27, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '가게도 깔끔하고 디저트 종류도 많아서 좋아요! 시그니처 라떼 (tytd) 가 헤이즐넛 맛으로 고소하면서 쓰지않아 맛나게 먹었습니당 >.< 커피 못 드시는 분들도 먹을 수 있는 논커피류들도 많아요! 베이커리들도 색다르고 맛났어요! 특히 저 바질 크런치가 크림치즈+바질 맛에 겉이 바삭해서 특별하게 느껴졌습니다💛', 84, 16, 'GOOD', SYSTIMESTAMP);
