INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '오랜만에 딸이랑 홍대에 놀러왔다가 방문하게된 카페 tytd 분위기도 좋고 무엇보다 아메리카노 커피맛이 아주 좋았어요~👍 베이커리 종류도 다양하고 너무 맛있어서 집에가는길에 커피랑 빵을 한가득 테이크아웃했네요❤', 32, 8, 'GOOD', SYSTIMESTAMP);
