INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '홍대에 이런 카페가 있었다니..❤️ 우연히 지나가다 들른곳인데 인테리어 넘 갬성있네요ㅎㅎㅎ 셋이가서 음료3개에 빵3개 시켜먹고 잠봉뵈르까지 포장해왔어요!ㅋㅋ 홍대가면 또갈거에요^^', 16, 7, 'GOOD', SYSTIMESTAMP);
