INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '소금빵, 휘낭시에 이렇게 베이커리류 정말 맛있었어요! 다른 빵도 너무 먹고 싶은 비쥬얼이었지만 참았습니다… 스트로베리라떼도 맛있었어요!👍🏻', 100, 20, 'GOOD', SYSTIMESTAMP);
