INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '새로 생긴 곳이라 가봤는데 커피는 특징없는 무난한 맛이었어요. 디저트류는 얼그레이 퀸 아망이 5200원으로 조금 가격대가 있는 편🙂', 77, 18, NULL, SYSTIMESTAMP);
