INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '완전 파리같음 빵 너무 맛있어서 카페 나갈 때 포장으로 바리바리 사서 포장해왔어요 커피도 진짜 제 스타일.. 홍대에 이런 카페 생겨서 너무 좋음 ㅜ', 97, 22, 'GOOD', SYSTIMESTAMP);
