INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '가게에 강아지가 한 마리 있더라고요. 저를 보더니 왕 짖으면서 확! 달려들었는데, 물리지는 않았지만 상당히 놀랬습니다. 그런데 한마디도 사과 안하시더라구요. 매우 무서웠습니다. 또 제가 잘못들었다고 믿고싶지만, 가게에 놀러오신 지인이랑 농담투로 이렇게 지나가면 물어? 하면서 깔깔 웃으시던데……..새로 가게 여신 것 같은데 맛과 분위기도 중요하지만 손님에게 위협이 되는 강아지 교육부터 시키셨으면 좋겠네요. 목줄이라도 묶고 계시던지요..', 74, 11, 'BAD', SYSTIMESTAMP);
