INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '연남동에 베이커리 카페가 생겼다고 해서 작업 할 겸 와봤어요 새로 생긴 카페에 가면 시그니처 메뉴를 꼭 시켜 먹어보곤 하는데 헤이즐넛 향이 좋았어요 다음엔 친구들이랑 와서 빵도 먹어볼게요', 44, 0, 'GOOD', SYSTIMESTAMP);
