INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), 'tytd의 맛있다고 입소문이 솔솔난 프랑스식 샌드위치 ''잠봉 뵈르''를 투표하러 나갔다가 포장해 와서~ 구남친과 점심으로 먹었습니다.... ''잠봉 뵈르''가 기가막혀!!!아아~ㅎ', 122, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '티와이티디'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '라우겐 베이글이 너무 맛있습니다. 짭쪼름+딱딱한 듯 부드럽게 씹히는 식감+버터의 느끼함과 단 맛. 벌써 3번 방문에 7개째..', 41, 1, 'GOOD', SYSTIMESTAMP);
