INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '단골카페에요 홍대입구역에서도 걸어서 5분거리에 있고 건물전체가 카페라서 자리도 많고 조용해요 무화과 티라미수는 품절이라 무화과 밀크 케이크 먹었는데, 크림 진짜 미쳤고 무화과가 듬뿍 올라가서 완전 만족했어요👍 자리에서 QR코드 주문도 편리하고, 분위기도 예뻐서 강추합니다', 94, 20, 'GOOD', SYSTIMESTAMP);
