INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '음료 종류가 엄청 다양해서 유혹이 많았습니다.. ❤️ 그치만 케익 먹으려고 아아 주문했는데 커피도 맛있었어요. 연남동 숲길이 내려다보여 초록색 가득한 창밖 뷰도 너무 예뻤고 가게 안팎에 가득한 토끼들도 귀여워요 🐰 잔잔한 음악이 흘러나와 대화하기도 좋아서 행복한 시간 보내고 갑니다!', 6, 10, 'GOOD', SYSTIMESTAMP);
