INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '연남동 올 때마다 들르는 단골 카페예요. 조용한 분위기라 극내향인 분들 쉬었다 가기 딱 좋아요. 키오스크나 자리에서 QR로 주문할 수 있어서 편하게 이용할 수 있어요. 1층부터 4층까지 층마다 분위기도 달라요. 데이트나 모임하기 좋은 분위기의 카페예요. 콘센트가 없어 작업하기엔 다소 불편하지만, 대화 나누기엔 최적이에요. 홍대입구랑도 가까워서 접근성 좋고, 인테리어 예쁘고 자리도 많아요. 직원분들도 친절해서 올 때마다 기분 좋아지는 곳이에요. 수박주스랑 휘낭시에 먹었는데, 시럽 없이 주문한 수박주스가 진짜 역대급! 휘낭시에도 고소하고 맛있었어요. 네이버 리뷰 작성 이벤트로  단호박 휘낭시에 받을 수 있어요. 조용히  쉬고 싶을 때 강추하는 카페예요 :)', 78, 14, 'GOOD', SYSTIMESTAMP);
