INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '카페 내부가 아기자기하고 감각적으로 꾸며져 있어서 눈길이 가더라고요. 분위기도 차분하고 조용해서 대화하기에 참 좋았습니다. 커피는 고소하고 풍미가 진해서 맛있게 즐길 수 있었어요. 다음에도 꼭 다시 오고 싶은 곳이에요!', 43, 1, 'GOOD', SYSTIMESTAMP);
