INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '연남동에 위치한 카페드레빗은 외관부터 따뜻하고 감각적인 분위기가 인상적인 곳이에요. 초록색 포인트 도어와 깔끔한 건물 디자인이 프렌치 감성을 물씬 풍깁니다. 내부는 세련되면서도 편안한 공간으로, 여유롭게 커피 한 잔 즐기기 좋았습니다. 오늘은 아메리카노, 아이스 아메리카노, 그리고 라떼를 주문했는데, 원두의 풍미가 깔끔하고 쓴맛이 과하지 않아 마시기 편했어요. 아이스 라떼는 부드러운 우유와 에스프레소의 밸런스가 좋았고, 아이스 아메리카노는 산뜻하면서도 깊은 향이 느껴졌습니다. 매장 분위기와 커피 맛 모두 만족스러워서 친구와 대화하거나 혼자 책 읽으며 시간을 보내기 좋은 카페였습니다.', 57, 17, 'GOOD', SYSTIMESTAMP);
