INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '분위기 좋은 카페가 있다는 지인의 말에 찾아왔습니다! 지인이 가보고 싶다고 해서 왔는데 쾌적하고 넓고, 가게 인테리어의 토끼들도 너무 귀엽네요 🐰🍀 사진 찍기에도 좋을 것 같아요! 날이 좀 선선해지면 루프탑 가러 또 한 번 와야 겠네요 🥰', 127, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '너무 귀여운 카페에요. 매장이 4층까지 있고 귀요운 인테리어에 소녀들의 감성을 자극하는 곳이에요, 데이트 오신 분들도 많이 계셨고 분위기가 좋아서 커플들끼리 오기 좋을것 같구 친구들끼리 귀여운 감성 즐기러 오시는 분들도 많았답니다. 음료가 일단 기본적으로 너무 맛있어요 아메리카노도 고소한 맛 산미있는맛 골라서 시킬 수 있었구요, 말차 딸기 라떼도 시켰는데 쌉쌀달달하니 맛있었어요! 무화과 티라미수도 시쿘는데 부드럽고 크림이 특히나 너무 맛있었구여 강추입니당👍👍👍', 30, 5, 'GOOD', SYSTIMESTAMP);
