INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '지나가다가 보고 들어갔는데 넘넘 만족스러웠습니다. 내부가 4층까지 있어서 넓어서 이용하기 좋아요!! 당근케이쿠 흰토끼 래빗라떼 넘 맛있어요 꼭 드세여!!!! 4층은 사람이 없어서 조용해서 더 좋았어요 층마다 포토존도 있으니 꼭 찍으시길 .. 🐰🐇', 77, 15, 'GOOD', SYSTIMESTAMP);
