INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '분위기 너무 좋아요. 커피 음료 종류 다양하고 토끼 컨셉의 카페라 귀엽고 구경하는 재미가 있어요. 수다 떨기 좋은 곳이라 평일임에도 손님 꽤 있어요. 차분한 분위기보단 좀 활기찬 느낌. 햇살 내리쬐는 오후에 오면 분위기 맛집. 연남동 3층짜리 건물이라 공간 넓진 않아도 분리는 잘 된 편.', 5, 10, 'GOOD', SYSTIMESTAMP);
