INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '무화과 얼그레이 케이크 완전 맛있어요😋 토끼로 가득한 인테리어도 너무 귀엽고 예쁩니당ㅎㅎ🐇🐇 테이블 간격도 멀어서 대화하기도 좋아요!!', 494, 45, 'GOOD', SYSTIMESTAMP);
