INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '말차이치고라떼가 있어서 신기해서 시켜봤어요! 생각보다 맛있고 기본적인 디저트들도 기대이상인 편. 그리고 무엇보다 4층까지 있어서 웬만하면 자리를 찾을 수 있습니다ㅋㅋㅋ', 29, 5, 'GOOD', SYSTIMESTAMP);
