INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '귀여운 토끼들도 많고 창문으로 숲길이 보여서 뷰도 너무 좋아요 ㅎㅎ 케이크 종류도 많아서 먹고 싶었지만 배가 불러서 집에 갈 때 테이크아웃 해갈랴고요~~', 16, 9, 'GOOD', SYSTIMESTAMP);
