INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '연남동에 있는 귀여운 래빗카페였는데 디저트도 커피도 맛있고 4층으로 이루어져 있어서 그런지 자리도 널널했어요!! 3층엔 토끼 포토존도 있어서 사진 왕창 찍었어요 ㅎㅎ', 16, 5, 'GOOD', SYSTIMESTAMP);
