INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '산미 없는 다크 원두 마셨는데 고소하고 맛있어요 당근케이크도 녹여서 파는 거 아니고 직접 만들어서 파는 맛 나요 ㅎㅎ 가게도 귀엽고 예뻐요 강추합니당', 98, 19, 'GOOD', SYSTIMESTAMP);
