INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '매장도 넓고 여기저기 귀여운 토끼 포토존이 많아서 좋아요!!💗 케이크도 맛있고 음료도 맛있었어요 😋 좋은 하루 보내고 갑니다>_<', 2, 0, 'GOOD', SYSTIMESTAMP);
