INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '아이랑 마포순환열차타고 내려서 걷다가 발견한 토끼카페에요~~ 아이가 너무 좋아했어요~~ 메뉴에 아이스크림이 있다면 더 좋겠어요^^', 90, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '부드러운 시트에 촉촉하게 스며든 당근 향이 좋암ㅅ습니다. 과하지 않은 단맛이라 끝까지 질리지 않고 즐길 수 있었고, 예쁜 플레이트에 정성껏 담겨 나오는 비주얼도 만족스러웠습니다. 감성적인 인테리어와 잔잔한 감성이 마음에 들었습니다', 67, 15, 'GOOD', SYSTIMESTAMP);
