INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '음료랑 디저트도 너무 맛있고 아기자기한 토끼 소품들이 너무 귀여워요 ♡♡ 위에 층에서 뷰가 너무 조아서 사진도 잘 나옵니당 ㅎㅎ', 356, 63, 'GOOD', SYSTIMESTAMP);
