INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '홍대에 이렇게 귀여운 곳이 있는줄 몰랐네용 음료랑 디저트가 너무 귀엽고 맛도있어요!!!! 공간도 넓어서 데이트 하기 좋아요~~ 요즘 너무 더운데 시원해서 편하게 놀다가용', 35, 4, 'GOOD', SYSTIMESTAMP);
