INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '평소에 테라스 분위기가 너무 좋아보여서 나중에 가야겠다고 생각했던 카페에요 드디어 방문했는데 진짜 테라스쪽 분위기가 너무 좋더라구요ㅋㅋㅋㅋ 티라미수도 너어무 맛있....❤️ 요즘 날씨 너무 더운데 바람이 솔솔불어서 여유롭게 커피 한잔과 디저트를 먹기 딱이었습니당', 115, 24, 'GOOD', SYSTIMESTAMP);
