INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '홍대 놀러왔을때 오기 좋은 카페 같아요! 사진 찍을 곳도 많구 역에서도 가까워요~ 친구랑 이야기 나누기도 좋았어요. 디저트 종류랑 음료종류가 많아요! 다음에 또 오고싶어요', 13, 2, 'GOOD', SYSTIMESTAMP);
