INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '친구 만나기 전에 시간이 떠서 카페를 찾다가 들어오게 됐는데 안에 인테리어도 너무 예쁘고 창밖 풍경도 너무 너무 맘에 드네요!!!', 42, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '귀여운 휘낭시에도 있고 제가 좋아하는 티 종류도 많아서 좋아요! 디카페인 옵션이 없는 카페도 은근 많은데 여기는 디카페인 옵션도 있습니다 👍🏻', 37, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '친구랑 방문했는데 아기자기한 분위기가 너무 좋았어요 토끼인형이 넘 귀엽고 여러 시그니처 음료들이 있어 누구와도 방문해도 좋을 것 같아요:)', 31, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '연남동 카페 <CAFE DE RABBIT>. 건물 하나 전체가 다 카페인데, 4층에 있는 테라스가 백미예요. 😍 작년 초에 개업했대요. 아이스 카페라떼 주문했는데 커피 맛도 부드럽고 괜찮아요. 🥤❤️ 직원 분도 친절하시고요. 🥰 야외 카페의 계절이 와서 좋네요. 😘', 4, 5, 'GOOD', SYSTIMESTAMP);
