INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '연남동에서 벌써 n번째 방문 중인 카페입니당 ㅎㅎ 가끔 홍대입구역 들릴 때마다 생각나는데 올 때마다 맛있는 커피와 다양한 디저트랑 케이크를 아늑하고 편안한 분위기에서 즐길 수 있어서 애용하고 있어용🥹🩷', 11, 2, 'GOOD', SYSTIMESTAMP);
