INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '처음 방문한 홍대 피터레빗 카페 디저트도 맛나고 커피 밀크티 다 좋아요 다만 테이블이 가까워 대화하기 좀 어려워요 정신이 없네요', 11, 0, NULL, SYSTIMESTAMP);
