INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '한 여름에 여유롭게 방문하기 좋은 카페에요!! ㅎㅎ 주말에 데이트 할 때마다 꼭 오는 거 같아요 ㅎㅎ 디저트도 엄청 맛있어서 강추!! 마들렌도 케이크도 진짜 넘넘 맛있어요 ㅎㅎ 지금 시즌은 꿀밤 케이크 나왔던데 진짜 괜찮더라고요💕 꼭 드셔보세용 ㅎㅎ', 11, 1, 'GOOD', SYSTIMESTAMP);
