INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '이름처럼 래빗들로 가득채워진 숲속 귀여운 토끼집같은 카페^^ 위치도 좋고 평일이라 편하게 대화할수있어서 편했어요! 디저트나 음료도 갠찮네욥', 43, 3, NULL, SYSTIMESTAMP);
