INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '홍대에서 놀다가 쉴만한 조용한 카페를 찾았는데 여기가 좋다고 해서 왔어요!케익이랑 음료도  너무 맛있고 이쁘고 분위기도 좋고 아주 맘에 듭니다ㅎㅎ 담에 또 방문할게요!', 59, 16, 'GOOD', SYSTIMESTAMP);
