INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '수박주스 시럽빼고 먹었는데 맛있었어요! 건강한 맛! 뷰도 예뻐서 넘 힐링이고 행복했어요 4층에서 공부했는데 조용하고 깨끗해서 좋았습니다 ㅎㅎ', 22, 10, 'GOOD', SYSTIMESTAMP);
