INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '너무 더웠는데 달달한 음료 맛있게 잘 먹었습니다! 아기자기한 인테리어가 귀여워요!! 티라미수랑 수박 주스를 모두 판매하는 매장 찾다가 발견했어요ㅎㅎㅎ', 21, 10, 'GOOD', SYSTIMESTAMP);
