INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '여기 가끔 오는데 뷰 좋고, 디저트 맛있어요. 1인 팥빙수 메뉴도 좋은걸요? 추천! 시원하게 머물다 가기 좋은 연남동 경의선숲길 뷰 카페!', 62, 15, NULL, SYSTIMESTAMP);
