INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '카페 곳곳에 토끼 장식이 가득해서 들어서는 순간부터 기분이 좋아졌어요. 인형, 장식 소품 하나하나가 정성스럽게 꾸며져 있어서 사진 찍기에도 딱 좋고, 전체적인 분위기가 따뜻하고 아늑했어요. 디저트랑 음료도 예쁘고 맛있어서 더 만족스러웠어요. 귀여운 분위기 좋아하시는 분들께 추천해요!', 11, 8, 'GOOD', SYSTIMESTAMP);
