INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '음료 디저트 종류도 다양하고 매장 곳곳에 토끼인형이 많아서 너무너무 예쁘고 귀여운 곳이에요!! 친구나 데이트 하러 오기 너무 좋네용🤍🤍 다음에 또 방문하겠습니당✨✨✨', 69, 17, 'GOOD', SYSTIMESTAMP);
