INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '귀여운 토끼가 가득한 동화 속 세상같은 카페 드 래빗이에요. 스트로베리 초코라떼와 흑임자크림라떼 주문했고 사실 뷰가 좋아서 음료가 맛있을까? 했는데 흑임자크림라떼 크림이 쫀쫀하고 커피가 진해서 너무 맛있었어요! 연휴에 여유로운 시간 보내기 좋았습니다. 초록초록 푸릇푸릇한 풍경도 예뻐요~ :)', 81, 16, 'GOOD', SYSTIMESTAMP);
