INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '홍대입구 근처 에어컨 빵빵한 카페 찾다가 들어왔는데 대만족이에요. 4층까지 전부 카페라 자리 넉넉하고 뷰도 좋아요. 에어컨 시원해서 걷느라 더위먹은 몸 식히기 딱이에요 루프탑도 있어서 분위기까지 완벽해요. 커피맛, 디저트맛 다 잡은 여름 필수 카페 추천해요.', 37, 1, 'GOOD', SYSTIMESTAMP);
