INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '더운 여름날 오아시스같은 곳!! 무엇보다 곳곳에 있는 토끼들이 너무 귀여웠어요!! 커피랑 케익도....그리고 음료도 최고입니다!!', 120, 20, 'GOOD', SYSTIMESTAMP);
