INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '밖에서 봤을 때 분위기가 좋아보여서 처음 와봤는데 정말 분위기가 좋아요 음료도 예쁘게 잘 나오고 분위기도 차분하니 햇빛도 잘 들어오고 좋아요! 데이트할 때 엄청 좋을 듯합니다', 3, 7, 'GOOD', SYSTIMESTAMP);
