INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '4층까지 있는 대형 카페로 경의선숲길 뷰가 정말 예뻐요 주말에 사람 많았는데 운좋게 루프탑 야외 자리 앉아서 따뜻하고 예쁜뷰 즐길수 있어서 좋았어요 각층마다도 큰창 문 열어놔서 지금 딱 좋은 날씨에 야외느낌 즐길수 있고 음료도 예쁘고 맛있어요👍💕', 92, 22, 'GOOD', SYSTIMESTAMP);
