INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '티라미수 먹고 계속 생각나서 결국 다시 방문한 카페 드 래빗🥰 오리지널 고민하다 이번엔 딸기로 시켰는데 오늘 입맛이 다른건지 오리지널이랑 조금 다른건지 좀 더 촉촉하고 약간 새콤한 느낌이었지만 그래도 최고!!👍👍 핑거쿠키로 만든 완벽 티라미수, 드시고 싶다면 카페 드 래빗으로 오세요🥹👏👏 커피도 종류별로 고를 수 있어 좋고 고소하니 맛있어요!! 자리도 층별로 많아서 여유 있고 자리마다 거리 있어서 답답하지 않아 좋아요!!', 16, 0, 'GOOD', SYSTIMESTAMP);
