INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '케 이 크 꼭 드 세 요 케이크 존맛 케이크 최고 케이크 만세 아 다먹어볼걸 ㅠㅠㅠ 근처살고싶다 맨날가게 커피도 진해서 너무 좋았어요 신맛없는 커피 최고 사장님맛잘알👍', 84, 18, 'GOOD', SYSTIMESTAMP);
