INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '아메리카노, , 귤말차케이크까지 다맛있어용 카페 내부도 감성 넘치고, 뷰맛집임 디저트도 비주얼 합격! 맛있게 힐링 완료했어요 ☕🍊', 43, 7, 'GOOD', SYSTIMESTAMP);
