INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '🐰 좋아하시면 강추하는 홍대에 위치한 루프탑의 카페 디저트가 너무 맛있어서…함께 온 친구가 흡입한 카페입니다 ㅋㅋㅋ 모양이 예뻐서 선물용으로 좋을 것 같아요 날씨가 너무 뜨거울 때는…실내에서 드세용 저도 조금 뜨거웠거든요 ㅜ ㅋㅋ 그래도 기분 좋은 신상카페입니다', 23, 6, 'GOOD', SYSTIMESTAMP);
