INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '연남동 작은 정원... 토끼가 인사해줄것같은 동화속 아기자기함이 엿보이는 이곳... 음료도 디저트도 무엇 하나 놓칠게 없는 숨은 맛집... 그렇게 휴무날의 잔잔한 여유로움은 내가 나에게 준 선물?!^-^ 강추!', 23, 2, 'GOOD', SYSTIMESTAMP);
