INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '카페드레빗 인테리어도 예쁘고 테라스도 있어서 날씨 좋은 날에 오기 딱이네요!!🐰💗💗 음료도 맛있고 디저트도 맛있어서 추천해용!!👍', 66, 12, 'GOOD', SYSTIMESTAMP);
