INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '이렇게 좋은 날씨를 맛있는 디저트와 함께 즐기기 좋은 곳입니다… 뷰도 좋고 매장 내 벽이 뻥 뚫려있어서 바람 잘통하고 너무 좋아요~ 케이크가 조금 비싸지만 정말 맛있어요!! 앉은자리에서 한판도 먹겠어요 ㅋㅋ', 8, 9, 'GOOD', SYSTIMESTAMP);
