INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '인테리어 감성 대박!! 통창이 날 좋은날에도 넘 이쁠거같고 비오는날도 감성 넘칠거 같아요 컵디자인도 신경 많이쓰시고 케이크랑 음료다 넘 맛있어요 자리가 넓어서 모임에도 좋아용', 37, 7, 'GOOD', SYSTIMESTAMP);
