INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '카페 이름처럼 내부에 토끼로 가득 꾸며져 있어 귀엽고 4층까지 있어 좌석도 많아 좋았어요~ 음료랑 케잌도 너무 맛있게 잘 먹고 가요 감사합니다 :)', 4, 5, 'GOOD', SYSTIMESTAMP);
