INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '🔴🔴 위치 🔴🔴 홍대 거리 한 가운데 있어서 찾기는 쉬워요. 🔶️🔶️ 맛 🔶️🔶️ 케잌도 부드러워요. 빵이랑 크림 둘다. 진짜 진짜 맛있어서 갈 때마다 케잌은 사요. 🟡🟡 분위기 🟡🟡 인기가 많은 곳이라 조용한 편은 아니지만 테라스로 나가면 훨씬 조용해져요. 편하게 수다 떨기는 좋은 곳 맞아요. 💚💚 이용방법 💚💚 자리를 먼저 잡고 주문하셔요. 사람들이 많은 시간 대에 가시면 조금 기다리실 수도 있어요. 매장이 큰 만큼 빨리 빠지기는 해요. 🔵🔵 총평 🔵🔵 매장 안도 깨끗하고 친절하시고 음료랑 음식 둘 다 엄청 빨리 나오는 편이라 너무너무 좋았어요. 별 다섯개 남겨요.⭐️⭐️⭐️⭐️⭐️', 30, 0, 'GOOD', SYSTIMESTAMP);
