INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '봄에 꼭 오는 연남동 카페에요😀 특별한 음료, 맛있는 디저트, 직원분들도 친절해서 만족하고 갑니다. 홍대역에서도 가깝고 1-4층 카페여서 자리도 많고 사람도 많아요. 테이블 크고 넓어서 사람은 많은데 불편하지 않고 편안한 분위기여서 좋았어요. 층마다 화장실이 있어서 편안해요😀 커피도 맛있고 케익까지 맛집이에요. 인테리어도 아기자기하고 귀엽고 토끼 좋아하거나 역에서 걸어서 가깝고 통창으로 연트럴파크 보고 싶으면 강추합니다!!!!!', 41, 3, 'GOOD', SYSTIMESTAMP);
