INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '분위기도 괜찮고 음악이 잔잔해서 대화하기 좋아요! 인테리어도 초록초록하고 예뻐서 날씨좋은날 특히 강추! 맛있는 티 많아서 커피못드시는분들도 좋을것같아요', 76, 13, 'GOOD', SYSTIMESTAMP);
