INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '오늘은 혼자 나들이온 연남동 토끼카페왔어요! 연남동 걷다가 예쁜.카페가 보여서 들어옴! 카페 드.래빗! 이름에서 알수 있듯이 카페에 토끼가.가득해요! 시그니처.메뉴들도 있고 예쁜 디저트🍮와 커피도 있어요 저는 래빗라떼 그리고 생딸기 치즈케이크 주문했어요 휘낭시에도 조금 땡김 네이버영수증리뷰하면 휘낭시에를 빋을수있어요 한 팀당 한개입니다. 생딸기가 듬뿍올라간.치즈케이크는.비주얼부터 합격! 부드러운 치즈케이크 위에 딸기🍓크림이 올라가있고 그 위에 생 딸기🍓가 있어요 접시도 딸기딸기한 예쁜 접시라서 👍🏻 커피☕맛도 굿굿 밀크티 먹으려고 했는데 시그니처 라떼가 있어서 그걸로 주문했어요 비주얼도 좋고 커피맛도 좋아요😄 4층까지있고 2.3.4층 좌석이고 4층에는.루프탑도 있어서 좋음 치즈케이크 위 딸기크림에는 딸기있음😍', 6, 9, 'GOOD', SYSTIMESTAMP);
