INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '이름에 토끼가 들어가는 카페답게 가게에 토끼가 많아서 너무 귀여운 곳이에요! 생딸기 발로나 티라미슈는 품절이라 기본으로 먹었는데, 기본도 너무 맛있어요! 경의선숲길 뷰도 너무 예쁘고 커피도 맛있어용', 14, 4, 'GOOD', SYSTIMESTAMP);
