INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '날씨가 넘 따뜻해서 테라스에는 못앉았지만 창가에서도 내부에도 화분도 크고 나무가 멋있어서 대화하기 너무 좋아요~! 바닐라빈라떼 강추!!!👍🏼', 30, 3, 'GOOD', SYSTIMESTAMP);
