INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '토끼 디자인의 귀엽고 맛있는 디저트랑 케이크가 있음 2층부터 4층까지 테이블이 많이 있음에도 사람들이 정말 많이 방문하는 공간 흰 토끼라떼랑 휘낭시에 정말 맛있게 먹었음 외국인 방문객이 많은 연남동이라 터치메뉴판은 영어, 프랑스어, 일본어, 중국어로 볼 수 있음 콘센트 사용할 수 있는 자리가 없는게 아쉽지만 방문자가 많으니 어쩔수 없다고 생각함', 50, 5, 'GOOD', SYSTIMESTAMP);
