INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '홍대 거리를 걷다가 감성적인 외관이 너무 좋아서 들어갔어요! 아기자기한 인테리어에 따뜻한 조명이 어우러져 정말 분위기 있어요! 평일 낮인데도 꽤 사람이 많았고, 다들 조용히 대화를 나누거나 작업 중이더라고요. 공부나 노트북 작업하기에도 괜찮은 분위기에요!!', 61, 13, 'GOOD', SYSTIMESTAMP);
