INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '뷰가 너무 좋아서 지나가다가 들어오게 되었어요. 내부 4층까지 앉을 수 있는 좌석이 많아서 좋았어요. 커피도 맛있고 음악도 좋아서 분위기도 굿굿^^', 19, 4, 'GOOD', SYSTIMESTAMP);
