INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '3층 통창뷰가 너무 예뻐서 좋아하는 카페입니다 주말이나 평일 낮에 사람이 바글거리지 않아서 더 자주오게 되는 것 같아요 분위기 좋습미다 경의선 숲길보면서 멍때리기 좋아요 🌳🌳🌳', 1, 0, 'GOOD', SYSTIMESTAMP);
