INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '카페 분위기도 좋고 자리도 엄청 많아서 사람 많은데도 바로 입장할수 있었어요 커피뿐만 아니라 휘낭시에도 종류 엄청 많아서 골라 먹을수 있습니다!', 47, 8, 'GOOD', SYSTIMESTAMP);
