INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '음료랑 커피두 맛있고 완전 카페 인테리어가 인스카감성이라 사진두 잘나와요! 📸 코코넛 요거트 스무디가 특히 너무 시원하고 맛있드라구용 ㅎㅎ 홍대 나들이 나오셨으면 카페 드 래빗 추천드려요오🙌🌀', 13, 6, 'GOOD', SYSTIMESTAMP);
