INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '건물 통째로 사용하는 카페라 4층까지 있어서 좋아요 층 올라갈수록 자리가 있어서 여유로워짐 ㅎㅎ 생크림딸기케이크랑 커피 맛났고 얘기하기도 작업하기도(3,4층) 좋은 카페! 아기자기 토끼 소품이 많아요 🐰☘️☕️🍰', 40, 10, 'GOOD', SYSTIMESTAMP);
