INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '그냥 지나가다 들렀는데 평일이라 그런지 사람도 별로 없고 2층 창가자리에서 보이는 공원뷰가 좋았어요! 당근케이크도 꽤 맛있었는데 커피는 샷이 하나가 들어가는 건지 좀 싱겁더라구요. 다음엔 샷추가를 해야할 것 같아요.', 27, 8, NULL, SYSTIMESTAMP);
