INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '데이트하다가 발견한 카페에요!! 딸기쇼콜라가 너무 꾸덕하고 맛있고 매장 곳곳에 토끼들이 귀여워요🤭 4층까지있어서 주말 저녁인데도 자리걱정 없었네용!!', 8, 9, 'GOOD', SYSTIMESTAMP);
