INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '홍제폭포를 다녀오고 요거트 마시러 카페드레빗에 왔어요~ 코코넛요거트는 첨인데 넘넘 맛나네요~^^ 봄바람 살랑살랑 오늘 날씨에 루프탑 분위기도 좋아요~', 24, 7, 'GOOD', SYSTIMESTAMP);
