INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '오늘은 운좋게도? 손님들이 많지 않아서 원하는 자리에서 여유롭게 시간 보낼수 있었어요^^ 하우스 와인과 홍차 마셨고 휴지의 토끼 그림이 맘에 들어서 사진 찍어보았어요. 경의선 숲길이 내려다보이는 위치라서 봄, 가을에는 더 운치있을 것이고 지금도 충분히 눈과 마음이 즐거운 시간 보낼 수 있어요. 다양하고 귀여운 토끼 캐릭터들로 꾸며져 있는 점도 맘에 들어요^^', 34, 7, 'GOOD', SYSTIMESTAMP);
