INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '간만에 홍대 데이트왔다가 인테리어도 이쁘고 메뉴도 다양해보여서 왔는데 너무너무 잘 선택한 듯?? 일단 토끼들이 너무 귀여운데 동물모양 휘낭시에가 킬포임 ㅋㅋㅋ 날씨도 좋아서 자리도 창가가 틔여있어 여유롭게 시간보내기에 딱인 것 같아여', 90, 12, 'GOOD', SYSTIMESTAMP);
