INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '홍대 나들이 나왔다가 연남동 산책길에 방문했어요. 카페 이름처럼 토끼 장식이 여기저기 많고, 2 3층에 햇빛도 잘 들고 분위기가 좋네요. 빛이 좋아서 사진도 잘 나오겠어요. 아쉽게도 전 커피를 못먹는 상태라 딸기라떼를 주문했는데 달달하니 좋아요', 54, 12, 'GOOD', SYSTIMESTAMP);
