INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '토끼 테마 카페라 너무 귀엽고 좋아요. 홍차도 티팟으로 주시고 당근케이크도 너무 귀엽고 맛있어요. 4층 까지 있는 대형 카페고 루프탑까지 있어서 혼자든 데이트든 너무 좋을 거 같아요! 담에 또 올게요~', 42, 6, 'GOOD', SYSTIMESTAMP);
