INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '처음으로..이런 미친 크림을 먹어봅니다 딸기는 겁나 싱싱한데 크림이 너무 맛있어서ㅠㅠ 진짜 뭔 이런 케이크가 있나 싶네요 커피는 진짜 뭔 이런..하나도 안시구요 산미가 없아서 너무 좋았어요 그냥 돈방석에 앉아주세요,,,그럼🫧🥹다들 요 카페 와보세요 후회 안합니다 정말', 29, 2, 'GOOD', SYSTIMESTAMP);
