INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '연남동카페 디저트맛집 카페드래빗! 크리스마스 분위기 물씬 나서 아늑하고 좋았어요 ㅎㅎ 겨울 맞이해서 딸기 케이크 처럼 딸기 듬뿍 들어간 디저트들 있어서 좋았습니다!! 연남동에서 보기 쉽지 않은 통건물 카페 인데, 연트럴 파크 바로 앞에 있어서 채광 엄청 밝고 따스한 느낌이에요☀️☀️ 분위기 진짜 최고 ㅎㅎ 바람에 흔들리는 나무들 구경하면서 여유롭게 시간 즐기실 수 있는 곳이에요 디저트 종류도 많은데, 토끼 컨셉의 카페 답게 귀여운 디저트 들이 있었어요 !! 음료도 종류 진짜 많아서 선택의 폭이 넓어서 좋았고, 이쁜곳에서 먹는 이쁜 디저트라 굿❤️‍🔥 직원분들도 너무너무 친절하시구, 카페 건물 전체가 구석구석 깔끔하게 되어있어서 관리도 잘 하시는 것 같아서 쾌적했습니다!! 연남동 대형카페로 겅력 추천합니다!!!', 8, 1, 'GOOD', SYSTIMESTAMP);
