INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '일단은 음료가 이쁘고 바닐라빈라떼 크림이 되게 맛있었어요! 음료가 전체적으로 마실만 하구 인테리어가 이쁜거 같아요 주변에 보이는 토끼인형도 귀엽네여', 86, 16, 'GOOD', SYSTIMESTAMP);
