INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '연남동 올때 마다 들리는 카페에요. 지금은 핫플카페가 된것 같아요~~ 발로나 초코라떼, 말차망고 정말 맛있어요. 3면이 다 전면창이라 연트럴파크 뷰 맛집카페 직원분들도 친절하고 층마다 화장실이 있고 무엇보다 조용한 분위기라 이야기하기 편해요.', 48, 8, 'GOOD', SYSTIMESTAMP);
