INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '토끼 천국인 연남동 감성카페! 실내 세 층과 루프탑 좌석이 있어용 휘낭시에 시켰는데 넘 맛있구.. 시그니처 선셋 에이드도 상큼달달해서 맛있어용! 케이크도 맛있어 보여서 다음엔 케이크도 먹으려고 합니당 ☺️', 18, 10, 'GOOD', SYSTIMESTAMP);
