INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '연남동 좋은 스팟에 위치한 카페 드 레빗 건물이 다 카페건물이라 자리도 많고  디저트도 많고 친구들 만나기 딱 좋아요🥰 귀여운 토끼들도 많아서 사진찍으면서 시간보냈어요ㅎㅎ', 2, 0, 'GOOD', SYSTIMESTAMP);
