INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '뷰도 너무 좋고 오늘같이 날씨 좋은날에 창문 열려있으니까 분위기가 넘 좋네용 경의선 숲길 오면 카페는 맨날 여기로 올 것 같아요,,!! 커피도 맛있구 담에는 디저트도 시켜봐야겠어용', 50, 2, 'GOOD', SYSTIMESTAMP);
