INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '매장이 엄청 넓고 뷰가 좋아요🩷 토끼 컨셉이라 인형도 매장 디자인도 귀엽고 예쁘네요 메뉴가 다양해서 자주 와서 도장깨기 하고 싶어요😍👍', 95, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '토끼 컨셉에 맞는 카페에요! 2층 3층 4층으로되어있어서 자리도 많고 연남동거리도 보이는 뷰가 있어요 커피도 토끼얼굴컵에 토끼귀는 토끼크림으로 데코되어있어서 귀엽습니다.', 63, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '딸기 티라미수 먹으러 방문했어요. 촉촉한 시트에 정말 맛있는 크림 딸기 완벽해요. 매장에 따뜻하게 햇빛이 들어와서 아늑하고 이야기 하기 편안해요. 건물 전체가 카페고 자리가 대부분 창가자리여서 좋아요. 바로 앞이 연트럴파크여서 뷰 맛집이에요. 크리스마스 재즈가 나와서 크리스마스 분위기 좋아요. 라떼도 하트로 아트해주어서 사진이 잘 나오네요. 직원분들도 친절해요. 딸기 먹으러 겨울에 자주 놀러올것 같아요.', 71, 16, 'GOOD', SYSTIMESTAMP);
