INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '연남동에 위치한 데이트코스 카페드레빗 너무 귀여운 소품들과 공간들이 인상적이라서 좋은 곳 인것 같아요. 역이랑 가까워서 더 좋습니다:) 중간 중간 소품들도 보는 재미가 있는 것 같습니다!', 25, 4, 'GOOD', SYSTIMESTAMP);
