INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '인테리어 귀엽고 예뻐서 들어왔는데 커피랑 디저트도 맛있고 분위기도 편하고 좋아서 너무 만족스러워요~다음에 또 올거 같아요~^^', 50, 9, 'GOOD', SYSTIMESTAMP);
