INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '아기와 유모차로 방문했어요. 잠깐 야외테이블에 앉아 쉬었다 가려고 했는데 비가 내리기 시작해 난감했습니다. 그때 친절하게 옆에 테라스(아마 잠시 운영하지 않으신던 공간 같던데)에 어닝으로 비 막아주시고 테이블 깨끗하게 닦아 자리 마련해주셨어요. 그 뒤에 비가 더 많이 오는 순간도 있었지만 비 그칠 때까지 잘 쉬고 갈 수 있었습니다. 음료도 디저트도 참 맛있었어요ㅎ 바스크 케익도 원래 좋아했지만 생크림과 함께라 더 좋았습니다. 다음번에 또 방문하겠습니다!!', 83, 13, 'GOOD', SYSTIMESTAMP);
