INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '매장이 조용하고 분위기도 좋아요! 그리고 4층까지 있어서 들어가자마자 자리도 잡을 수 있었어요 커피랑 딸기 티라미수도 너무 맛있어요!', 16, 7, 'GOOD', SYSTIMESTAMP);
