INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '귀여운 토끼들이 가득 가득 이어서 너무 분위기 좋은 카페 네요~ 4층 까지 있고 화장실도 청결하고~ 외국 분들도 많이 오시는거 같은데 대화하기 좋은 곳이라 잘 다녀왔습니다~ 케이크는 보들보들 달달 해서 당충전 최고!!', 17, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '귀여운 토끼 인형이 가득한 카페에요. 식물 인테리어도 잔뜩 있어서 좋고 매장이 넓지는 않은데 3개층에 센스있게 자리를 많이 마련해뒀네요. 케이크도 맛있고 커피도 괜찮아요.', 129, 20, 'GOOD', SYSTIMESTAMP);
