INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '토끼 소품이 많아서 귀여워요- 경의선숲길 뷰도 괜찮네요. 흰토끼 래빗라떼 달달하고 맛있어요. 자세한 후기 남겼습니다. https://m.blog.naver.com/arhan05/223885855764', 47, 5, 'GOOD', SYSTIMESTAMP);
