INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '동화나라에 온 듯 인형과 예쁜 색감의 가구가 맘을 사로잡았어요. 우연하게 들어온 카페 드 래빗 이름답게 곳곳에 토끼인형들 발견하는 재미까지 예쁜 찻잔에 티와 맛있는 케잌을 좋은 사람들과 즐거운 시간을 보냈답니다~', 55, 13, 'GOOD', SYSTIMESTAMP);
