INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '딸기생크림케잌 너무 맛있어서 오자마자 사진 찍을 틈 없이 순삭했네요. 커피도 맛있고 조용히 대화하며 데이트하기 좋아요! 화장실도 깨끗해서 사용하기도 좋았네요!!', 66, 11, 'GOOD', SYSTIMESTAMP);
