INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '이름처럼 인테리어가 토끼로 가득한 귀여운 카페였어요. 아기자기한 소품들이 잘 꾸며져 있어요. 음료나 디저트는 무난했습니다.  복층이고 자리가 많아요. 주말 점심시간에 자리 금방 차네요.', 41, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '높은 층에서 연남동 숲길 뷰를 즐길 수 있는 곳!  커피와 케이크가 너무 맛있어요.🫰🏻 평일에도 사람이 몰려서 조용한 분위기는 아닙니다!', 29, 4, 'GOOD', SYSTIMESTAMP);
