INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '잠깐 쉬려고 머물렀는데 4층에서 잠시 휴식을 보내서 좋았어요! 휴일이라 사람이 좀 있었지만 평일에 다시 한번 와보고 싶을 만큼 넓고 예쁜 장식들이 있었어요! 창가에서 잘 쉬었다 가요😆', 38, 5, 'GOOD', SYSTIMESTAMP);
