INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '메뉴 맛있게 잘 먹었습니다! 메뉴 하나하나가 너무 예쁘고, 토끼가 틈새로 디자인에 있어서 넘 귀여워서 먹는 맛이 나네요 :) 여기 와서 다른 메뉴도 먹어보고 싶어요 !', 50, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '친한동생들과 일상으로부터 잠시나마 벗어나고파 힐링중에 알게된곳...디저트,음료는맛도멋도 인정^ ^ 무엇보다 뷰가 힐링 그자체예요~~~ 맛보지못한 디저트는 포장해와서 먹었는데 많이 달지도않고 각각의 맛이 달라서 넘좋았습니다^ ^ 입으로 맛있고 눈으로 맛있는 또 가보고싶은 맛집입니다^ ^', 66, 15, 'GOOD', SYSTIMESTAMP);
