INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '우선 토끼를 소재로 예쁘고 아기자기하게 꾸며놓아서 분위기가 따뜻해요. 디저트도 맛있구요! 나중에 또 방문하고 싶은 카페네요 :)', 9, 10, 'GOOD', SYSTIMESTAMP);
