INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '진짜 너무 맛있어요...고급지고 특히 양이 진짜 많아서 계단 오르고 내리기 힘들 정도로 양이 혜자입니다.. 인테리어도 너무 이쁘고 휘낭시에도 개꿀맛입니자 연말을 따뜻하게 보낼 수 있었어용', 39, 4, NULL, SYSTIMESTAMP);
