INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '신기한 음료수가 많고 맛있어요! 디저트도 귀여워서 힐링되네요 매장은 세로로 큽니다. 4층까지 있는데 생각보다 좁지만 아늑해요~', 8, 0, 'GOOD', SYSTIMESTAMP);
