INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '케이크도 너무 맛있고 카페도 분위기가 너무 좋네요!! 여자친구랑 데이트하러 왔는데 음료도 너무 좋아요!! 곳곳에 있는 토끼 인형이 사실 진짜 너무 사기에요 ㅠㅠ 심장에 안좋네요 ㅠㅠ 귀여운건 사랑입니다💗', 119, 26, 'GOOD', SYSTIMESTAMP);
