INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '카페가 귀여워요! 4층까지 있는 카페이고, 초콜릿이나 말차, 커피 활용한 메뉴들이 다양하게 있어요! 생딸기 발로나 티라미수는 엄청 달지 않고, 커피맛도 나면서 맛있어요! 발로나 초코라떼는 폭신폭신 맛있네요! 분위기 좋아요~!', 8, 9, 'GOOD', SYSTIMESTAMP);
