INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '카페가 넘이뻐요!! 단풍이 아직까지 있다니ㅎㅎ 기분좋아요. 주변에 사주볼 일 있어서 우연히 들렸는데 만족하고 레빗라떼 추천해용ㅎㅎ 매장 내 크리스마스느낌 넘 좋고 재즈음악까지 완벽해요❤️🤍❤️', 151, 100, 'GOOD', SYSTIMESTAMP);
