INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '2층에 창가에 다찌석 있어서 바깥보기 좋은데 아무해도 3층이 좋긴해여. 3층은 다찌석없고 일반 테이블. 특별한 메뉴가 있어요. 말차망고는 달콤한 망고에 은은한 말차. 로즈뭐시기는 시고 산미도 쎄요.. 그리고 좀 소란스러워요.. 조용한카페는 아닙니다. 친구랑 대화하는데 소리가 안 들릴정도.. 물론 이건 그당시 그룹이 시끄럽게해서 그렇지만요.. 공간은 작은데 사람이 몰려서 그런가봐요. 커피와 뷰는 좋습니다', 57, 12, NULL, SYSTIMESTAMP);
