INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '핵 맛있음 카페도 넓고 대기시간 없이 바로 입장가능!! 강아지도 들어올 ㅜ 있다고 해서 보고싶었는데 아쉽게 없었음 ㅠ ㅎ 커피도 맛있었움^^', 54, 12, 'GOOD', SYSTIMESTAMP);
