INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '커피가 진하고 맛있어요!! 디저트도 달콤하니 맛나네요 토끼 컨셉의 인테리어도 너무너무 귀여워요 ㅎㅎ 안에 분위기도 대화하기 넘 좋습니다!', 24, 10, 'GOOD', SYSTIMESTAMP);
