INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '생딸기티라미슈 부드럽고 달지 않아요. 말차이티고라떼는 아이스이니 참고하세요. 발로나쵸코라떼는 달달해요. 토끼컨셉의 카페 인테리어가 예쁘고 자리도 많아요.', 62, 18, 'GOOD', SYSTIMESTAMP);
