INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '일본에서 놀러온 언니와 방문했는데, 인테리어도 예쁘고 디저트도 맛있네요. 가을한정메뉴인 무화과케이크 보드랍고 달달하니 잘시켰어요. 쑥라떼 주문하니 위에 크림이 귀엽게 세 덩이 올라갔네요. 아메리카노도 원두를 다크 밀크 선택 할 수 있었답니다! 3,4층은 창이 모두 열려서 야외에서 마시는 듯한 기분이었어요. :)', 123, 26, 'GOOD', SYSTIMESTAMP);
