INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '진짜 맛있어 보이는 것들 엄청 많고 실제로 너무 맛있어요ㅠㅠㅠ 사람 많은데 자리도 많아서 앉을 공간이 있었습니다 다음에 또 오고 싶어요!!🥹❤️', 7, 3, 'GOOD', SYSTIMESTAMP);
