INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '커페가 좁도 높은 형태의 구조입니다. 대신 층별로 느낌이 조금씩 달라 오히려 좋은 것 같습니다. 겨울이라 테라스 이용은 안했지만 봄 가을에는 테라스에서 연트럴파크 보는 뷰로 즐기는 것도 좋을것 같습니다. 말차가 진하지 않다고 느꼈는데 잘 섞으면 찐하고 좋습니다. 디저트도 좋아요!', 38, 3, 'GOOD', SYSTIMESTAMP);
