INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '토끼 컨셉에 충실한 메뉴들이 귀엽고 맛있네요! 사람이 많지만 그만큼 홀이 넓어서 자리 충분합니다~ 데이트하기 좋은 아늑한 분위기인것 같아요', 2, 10, 'GOOD', SYSTIMESTAMP);
