INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '가을정취를 가득 느낄수 있는 테라스창가자리가 좋아요. 무엇보다 커피맛도  좋고 디카페인 원두로 선택 할 수도 있네요. 연남동에서 추천하고픈 예쁜카페입니다.', 61, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'TERRACE');
