INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '날씨가 너무 추워서 친구랑 어디 카페를 갈까 고민하던 와중 마침 가깝게 있어서 방문한 곳이에요! 쑥래빗라떼가 생소해서 한 번 주문해봤는데 쑥향이 거부감 없이 은은하게 나면서 위에 크림도 넘 맛있어요...ㅠㅠㅠ 매장도 아늑하고 좋습니다 ㅎㅎ', 56, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '카페에 토끼 아이템이 가득해서 너무 귀엽고 예뻐요. 매장이 4층짜리고 자리도 많아요. 휘낭시에도 귀여워서 사진을 안 찍을 수가 없네요 🐰', 243, 79, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '카페 드 래빗 🐇✨ 무화과 티라미수의 비주얼에 먼저 한 번, 맛에 두 번 반했어요! 크리미한 마스카포네와 촉촉한 시트에 신선한 무화과가 올라가니 디저트가 이렇게 우아할 수 있나 싶을 정도로 감동. 아메리카노는 디저트의 단맛을 깔끔하게 잡아줘서 조합이 최고였어요. 잔잔한 조명 아래서 티라미수 한 입, 커피 한 모금하며 힐링했던 시간. 디저트도 커피도 다 놓치지 않는 연남동 감성 카페💗 #카페드래빗 #연남동카페 #무화과티라미수 #커피맛집 #연남동데이트', 13, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
