INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '안락하고 넓은 카페! 디저트도 다양해요. 케이크 종류가 많아요. 우드톤과 식물의 적절하게 조화로운 차분한 인테리어입니다. 루프탑이 있어서 따뜻한 날씨에 이용하게 좋을 거 같아요. 실내에 화장실이 있고 여남 구분 되어 있어요!', 100, 19, 'GOOD', SYSTIMESTAMP);
