INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '카페가 너무 귀여워요,,♥️ 여러층으로 돼 있어서 이용하기에 좋아요 래빗이어서 그런지 휘낭시에 모양도 너무 너무 귀여운 토끼예요', 58, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '토끼를 위한 토끼에 의한 토끼로 이루어진 곳~ .ᐟ 너무너무 귀엽고 너무좋아요 디저트도 맛잇고 디저트 예쁘기만 할줄알았는데 커피도 넘 맛있어요 홍대 오면 친구들이랑 자주 오게될것같아요 토끼카페 최고><', 76, 13, 'GOOD', SYSTIMESTAMP);
