INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '바닐라빈라떼가 적당히 달고 맛있네용 ! 케이크의 크림두 맛있어용! ㅎ0ㅎ 토끼도 귀엽고 장소도 넓고 대화하기 좋아서 또 올 것 같아용!', 55, 13, 'GOOD', SYSTIMESTAMP);
