INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '가까워서 와본 곳인데 카페가 굉장히 크고 쾌적해요! 이층 뷰가 좋아서 가을느낌 낭낭하게 느낄 수 있음🍁케이크랑 음료 종류도 많아요 무화과 티라미수 시켰는데조합이 생각보다 맛있었어요 시그니처 커피도 맛있음 합정 카페로 추천드려용!!', 35, 2, 'GOOD', SYSTIMESTAMP);
