INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '날이좀 선선해져서 따뜻하고 이쁜 라떼와 카푸치노가 먹고싶었는데... 살면서 이렇게 이도저도아닌 커피는처음입니다. 핫도아닌 아이스도아닌.. 아트도못한거 보면 답나오네요 디저트 너무맛있어서 그나마 위안이되었어요', 19, 2, 'BAD', SYSTIMESTAMP);
