INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '케이크 맛있음! 로즈치노?는 시큼한 맛이 나요,, 특이한거 좋아하면 좋아할듯 토마토바질소다는 토마토랑 탄산수랑 같이 먹는 느낌남 이것도 신기😮', 47, 0, 'GOOD', SYSTIMESTAMP);
