INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '산미있는 커피를 좋아하는데 원두를 고를수있어서 좋았어요!! 커피도 맛있었구요 디저트도 맛있습니다! 야외테이블은 애견동반이되서 반려동물과 산책하고 방문하니까 좋더라구용💓', 60, 12, 'GOOD', SYSTIMESTAMP);
