INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '커피랑 에이드 둘 다 맛있었어요 주말에 사람이 정말 많았지만 좌석도 많은편이에요 아메리카노는 원두 선택도 가능해서 좋은것같아요', 66, 15, 'GOOD', SYSTIMESTAMP);
