INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '인테리어, 소품들 너무 아기자기하고 예뻐요! 눈오는 날씨에 창밖 바라보며 커피와 디저트를 즐기니 너무 좋습니다! 카푸치노도 부드럽고 맛있습니다!', 40, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '다신 안 온다고 다짐했었지만... 7월 15일에 그만한 악평을 남겨놓고 후속리뷰를 안 쓰는 건 예의가 아니라 생각되어 오늘 다시 방문했습니다. 창문 모두 닫혀 있었고 에어컨도 모든 층에 틀어져 있었네요. 쾌적했어요. 커피는 여전히 밍숭... 맹숭... 한 느낌이었지만 밤치즈케이크라는 디저트는 제 입에 맞아서 마음에 들었습니다. 전반적으로 괜찮아졌네요. 가끔 들를게요!', 81, 18, NULL, SYSTIMESTAMP);
