INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '발로나 초코라떼는 맛있어요ㅎ 인테리어도 토끼토끼해서 러블리합니다 시그니처 메뉴인 로즈치노? 제 입맛에는 좀 안 맞았어요 홍삼맛도 나는것 같고 다들 시키실때 참고하세요.', 34, 1, 'GOOD', SYSTIMESTAMP);
