INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '인절미컵빙수랑 래빗라떼 아이스 먹었습니다! 빙수도 미숫가루 맛 나면서 팥이랑 떡이 많고, 라떼도 위에 크림두 맛있어요😋 나중에 디저트도 먹어보고 싶네요 ㅎㅎ', 123, 22, 'GOOD', SYSTIMESTAMP);
