INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '두번째 방문이에요! 토끼 컨셉이 너무 귀엽고 연리단길 뷰가 좋아요. 날씨가 좋아서 문을 열어놓아서 시원해요. 자주 올 거 같아요.', 29, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '홍대에 놀러왔다가 외관이 멋있어서 와봤는데 완전 만족스러워요~~! 쑥토끼 주문했는데 쑥크림이 상당히 특이해서 좋네요 ㅎㅎ 크림 올라간 쑥음료는 처음인데 맛있었어요 ~~ 토끼 인테리어도 많고 사진찍기 좋아요 ㅎㅎ 다음에 또 방문할게요 ㅎㅎㅎ ^^', 36, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '무화과 티라미수 가을 시즌 한정메뉴로 판매하는데 꼭 먹어보세요!!! 달달하구 맛있어요 빨대로 하트라서 너무 귀엽고 소품도 아기자기하고 음료도 맛있어요 ❣️❣️ 다음에 또 방문 할게요!!!!', 13, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '연남동 연트럴파크 바로 앞에 위치해서 푸릇푸릇한 뷰를 볼수있어요! 창도 다 개방되어있어서 가을날씨에 오기 넘 좋네요❤️ 말차이치고라떼 먹었는데 달달하고 이색적인 매뉴가 맛있어요!', 36, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '친구랑 오랜만에 홍대가서 밥먹고 배는 찢어져 터져도 카페는 꼭 간다!해서 찾아온 카페 드 래빗🐰 진짜 너무배불러서 빵종류 안골랐는데 갑자기 빙수를 고르는 패기,, 여기 빵이 이쁘고 귀엽고 그르든뎅,, 인절미컵빙수 1인 빙수지만 밥 두둑하게 먹고 온 2인이 먹기좋은양! 밑에 얼음도 대충갈아서 인절미가루 뿌린 그런거아니고 인절미인지 미숫가루인지 넣고 갈아서 만든 개맛있는 얼음!!! 음료는.. 양심적으로다가 아메리카노🤣', 50, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '4층건물이구  2~4층에 좌석이 있고 테라스좋아요:) 쌀휘낭시에가 쫀득하고 맛있고 커피는 연한편이에요 친구들과 이야기 나누기 좋아요:)', 8, 3, 'GOOD', SYSTIMESTAMP);
