INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '가게가 층이 많아 넓고 웨이팅 없이 이용할 수 있었어요. 디저트 종류가 다양하고 독특한 메뉴가 많은 것 같아요 자몽요거트스무디가 정말 맛있더라구요. 자몽 쓴 맛이 하나도 나지 않았어요.', 38, 1, 'GOOD', SYSTIMESTAMP);
