INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '야외 테라스가 있는 카페를 찾다가 방문하게 되었어요. 카페 앞 나무들도 너무 예쁘고 내부도 아기자기하고 음료도 다양해서 너무 좋아요!', 90, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'TERRACE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '휘낭시에가 귀여운 모양이 많아서 너무 좋아요!! 토끼모양이 너무 귀어워서 좋더라구요!🤍💛 뷰도 좋고 모양도 너무 귀여운 휘낭시에라서 기분 좋게 있다가요🤍✨☺️', 23, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '여기 맛있다고 해서 와봤는데 진짜 맛도 좋고 뷰도 좋아요! 요즘같이 선선할 때 오기 딱 좋은 것 같습니다 ㅎㅎㅎ 그리고 무화과 티라미수 진짜 맛있었어요!! 강추~', 9, 1, 'GOOD', SYSTIMESTAMP);
