INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '아이스 아메리카노, 아이스카라멜 라떼, 꿀수박 주스, 말차 팥 생크림 케이크 시켰어요. 시그니처 토끼 라떼는 맛을 못봤지만 음료 모두 맛있었고 말차 팥 생크림 케이크도 맛있네요. 토끼 가득한 인테리어가 사랑스러운 공간었습니다.', 16, 6, 'GOOD', SYSTIMESTAMP);
