INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '분위기 너무 좋고 음료도 담백하고 맛있습니다! 무화과티라미수는 달달해서 맛있구요!! 연남동 공원도 보이고 여유 부릴 수 있는 곳이라 좋습니다😍', 34, 9, 'GOOD', SYSTIMESTAMP);
