INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '경의선숲길이 내려다보이는 뷰가 너무 예쁜 카페에요 지금 한창 단풍철이라 더 좋아요. 개방감도 있고 날 좋을 때 테라스나 루프탑 즐기기도 좋은 것 같아요. 디저트나 음료 메뉴도 다양하게 있답니다:)', 11, 0, 'GOOD', SYSTIMESTAMP);
