INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '무화과티라미수에 이끌려 홀린듯 들어갔어요ㅠㅠㅠ무화과 티라미수는 품절이라 밀크케이크로 대체 했는데 후회없는 선택이었습니다🙂커피도 맛있고 뷰도 좋고 곳곳에 귀여운 소품도 많아 즐거운 시간 보냈습니다❤️❤️❤️', 35, 4, 'GOOD', SYSTIMESTAMP);
