INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '오랜만에 데이트하러 연남동에 와서 예쁜카페 서치하다가 찾게된 “카페 드 래빗”!! 토끼인형부터 포스터까지 토끼를 많이 사랑하시나봐욬ㅋㅋㅋㅋㅋㅋ커피도 맛있고 음료도 맛있어요! 아 그리고 여기 두바이 초콜릿도 한정수량으로 판매하고 있으니 와서 드셔보세요!ㅎㅎ 저희는 솔드아웃으로 못먹었지만😭', 5, 9, 'GOOD', SYSTIMESTAMP);
