INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '휘낭시에 종류에 따라 단호박이랑 황치즈 맛이 나는데 예뻐서 먹기 아쉬웠어요~ 말차망고주스는 말 그대로 말차 + 망고 조합이라 신기했습니다', 35, 8, 'GOOD', SYSTIMESTAMP);
