INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '토끼 인테리어가 너무 귀여워요🖤 길가다가 들어왓는데 쾌적하고 뷰가 조아요! 샌드위치 오늘은 안 되어서 담에 다시 먹으러 올게요~~~~', 45, 3, 'GOOD', SYSTIMESTAMP);
