INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '연트럴파크 지나면서 친구가 아는 카페를  못 찾아 3-4층 되는 카페가 있어 들어왔어요. 아기자기한 디저트와 음료를 파는데 좀 비싼 편이에요. 하지만 카페 내부는 깨끗하고 작은 인절미빙수는 떡이 작아 아쉽지만 맛나고 자몽쥬스는 좀 맛이 연해요. 그래도 사진이 잘 나오고 여러층이 있고 비가 와서 사람들이 첨엔 많진 않았는데 2층에 사람들이 유입이 되더라구요. 비오는 창 밖 분윅도 좋고 어느때든 뷰도 괜찮을 듯 싶어요ㅎㅎ', 13, 2, 'GOOD', SYSTIMESTAMP);
