INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '친구들이랑 카페 찾다가 들어왔눈데 인테리어가 너무 예쁘고 귀여웠어요!! 디저트랑 음료도 다 맛있어보여요 담에 또 올거 같아요~', 11, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '급하게 간곳인데  분위기 너무 좋고 맛있는 케이크 있어서 좋어요ㅎㅎ 밤 10시까지 하는것도 너무 장점이고 안갈이유가 없읎니다~', 1, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '연남동 예쁜 카페. 카페드래빗이예요^^ 자리도 넓고 엄청 깔끔하고 귀여운 디저트도 많아요. 음료도 넘 맛있어서 너무 좋아요^^', 83, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '장점: 카페도 예쁘고, 4층까진가 있어서 조용하면서도 사람들도 조용조용 이야기 하는 분위기였고, 층이 많아서 직원들과 분리되어있어서 좋았어요. 스무디 가는 소리 같은 게 시끄러운데, 이렇게 층이 분리되어있는 카페는 조용해서 좋아요. 단점: 직원들이 불친절해요. 기분이 나쁠 정도는  아니지만, 직원들 때문에 다시 찾아가고싶지는 않은 까페에요. 들어올 때  나갈 때 인사 해주면 기분이 좋잖아요. 사람마다 중요시 여기는 포인트가 다르기는 하지만 저는 그래요. 그리고 청소하러 몇분에 한번씩 층을 도시는데 발을 엄청 크게 쿵쿵 거리면서 올라오셔서 다들 한번씩 돌아보는 수준이었습니다. 리뷰이벤트 하려다가 뭔가 잔잔한 불친절함에.. 그냥 안하고 솔직리뷰 남깁니다 그래도 카페 위치랑 분위기는 좋아요', 50, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '화장실에 들어간지 30초도 안됐는데 누가 문을 쾅쾅쾅 두드려서 사람이 들어가 있다는 뜻으로 똑똑 했습니다. 그러더니 쾅쾅쾅쾅 막 두드리면서 “나오세요!!! 사람들 못 가잖아요!!!!” 이렇게 화내면서 소리를 지르는 겁니다. 그래서 문 열고 “저 화장실 방금 들어왔는데요?” 하니까 머리 묶은 알바생이 “아 그래요?” 하더니 사과 한 마디 없이 그냥 쌩 가서 기분이 엄청 나빳네요 화장실 옆에 앉았는데 화장실 나오고 30분동안 여자 화장실 가는 사람 한명도 없었음 ㅋㅋ;', 107, 26, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '분위기가 너무 좋아요!! 매장도 넓고 자리도 많고 디자트도 양도 많고 너무 좋습니다!! 친구랑 잘 수다떨다가 가요 다음에 올 때 또 올 것 같아요!!', 59, 16, 'GOOD', SYSTIMESTAMP);
