INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '크리스마스 분위기 낭낭하고 매장이 포근해요!! 음료가 친절하고 매니져 님이 달콤해요!! 친구, 연인 과 오기 좋은 곳 입니다~ :)♡', 29, 3, 'GOOD', SYSTIMESTAMP);
