INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '1,2,3층까지가 아마 실내 공간이고, 위에는 테라스가 있는 걸로 알고 있어요. 여름이라 에어컨을 엄청 빵빵하게 틀어놓으셨고, 음료도 맛있어요', 49, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '귀여운 곳이라서 아이와 가려고 눈여겨보다가 방문햇어요 5세아이 마실 수박쥬스 희낭시에 있습니다 토끼소품에 눈돌아가는 아니 앉혀서 즐거운 시간보내고 갑니다', 90, 12, 'GOOD', SYSTIMESTAMP);
