INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '레몬아메리카노랑 자몽소다 마셨어요. 레몬아메리카노가 생각보다 단맛이 강했는데 상큼하고 맛있었어요! 바깥 바람이 좋아서 앉아서 잘 놀다가요!', 22, 3, 'GOOD', SYSTIMESTAMP);
