INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '연남도 거리 걷다 4층 루프탑까지 있는 카페 드 래빗이랴 카페로 왔어요. 맛난 디저트들과 다양한 음료, 1인 빙수까지 있더라고요. 복숭아 요거트 스무디 상큼하고 시원하니 맛났고 아메리카노도 구수하고 맛있었어요. 인테리어 예쁘고 에어컨 빵빵해서 좋았어요^^', 21, 7, 'GOOD', SYSTIMESTAMP);
