INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '연남동에 약속이 있어 왔다가 좀 일찍 도착하여 여트럴파크 걷다 커피한잔 하려고 들어왔어요.~~ 커피맛이 굳입니다.바로옆에 할리스도 있어서 어디를 가야할까 망설였는데... 잘 온것 같아요.~~^^*', 4, 3, 'GOOD', SYSTIMESTAMP);
