INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 드 래빗'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '연남동 그린그린 안정적 분위기의 카페 드 래빗이에요❤️ 층마다 창문이 활짝 열려있는 통건물(1~4층) 카페가 눈에 띄어 들어갔어요. 망고스무디(7.2), 자몽소다(6.5), 말차 아인슈페너(7.2), 래빗라떼(6.8) 주문, 바람 솔솔 들어오는 창가 자리에서 좋은 시간 보냈어요^^', 4, 3, 'GOOD', SYSTIMESTAMP);
