INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '진동벨이 영수증에 찍힌거랑 달라서 직원분께 말씀 드렸는데 눈 마주치고 말씀 드렸는데도 불구하고 아무말도 안하시고 그냥 지나쳐서 카운터 들어가셨어요;; 번호가 밀려 어영부영 픽업대에 나온 디저트박스 직접 열어보고 제꺼가 맞는지 셀프 확인 했습니다. 바쁜 시간대도 아니었는데 응대가 정말 아쉬웠습니다.', 65, 11, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '외부에서 봤을 때부터 좋아보였어요. 딱봐도 보이져,, 넓고 오전에가니 사람도 없어서 조용하고 집중하기 좋았습니다. 시설이 넘 좋아서 음료 사진은 찍지도 못했네여 ㅋ,ㅋ,ㅋ', 33, 5, 'GOOD', SYSTIMESTAMP);
