INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '2층은 넓고 깨끗해서 좋아요. 다만 진동벨도 있는데 메뉴 나오는 걸 알려주는 화면에서 나오는 알림 소리가 너무 커서 조용히 시간 보내기엔 시끄러웠습니다.', 57, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '홍대입구 사거리 인근 컴포드커피 건너편에 최근 오픈한 나름 신규 대형점. 투썸의 홍대지역 주력 매장으로 봐야겠네요. 다른 투썸에 가고 싶지 않을만큼 아주 넓고 쾌적합니다. 신촌 1호점 폐점으로 힘들었는데 여기로 정착해보고 싶네요. 2층 올라가는 계단길이 무척 예쁘지만, 매우 멀고 험난하다는 게 유일한 흠.', 32, 8, 'GOOD', SYSTIMESTAMP);
