INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대서교점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '쿠폰이 4월달까지 홍대점만 되네요ㅡ알았으면 안샀을텐데ㅡ 다른점은 안되는거보니 오픈해서 고객유치하려는거같은데 좀 속은느낌이랄까ㅡㅡ 문의할때 말씀을 안해주셨고 그닥 설명을 자세하게 안해주시더라고요', 20, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '카페 구조가 2층,3층.4층 구조인데 층별마다 내부가 넓어서 좋네요~ 각각 색깔별로 좌석종류 표시가 되어있는거 같아서 보기도 좋고 알록달록해서 좋은거같아요~~ 커피도 맛있었어요~~', 22, 9, 'GOOD', SYSTIMESTAMP);
