INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '연휴마지막날 젊음의거리 홍대 와써요. 돌아댕기다 투썸왔는데 2~4층까지 넓네요. 진동벨도 키오스키옆에서 자동으로 주문후가져와써요. 바나나커피 궁금해서 먹어봤는데 바나나우유에 커피섞은맛이네요 ㅎㅎ 초코쿠키요거트는 위는 초코릿 아래는 초코콘프레이크가 요거트를 감싸고 있네요. 잘먹고 갑니다~♡', 8, 8, 'GOOD', SYSTIMESTAMP);
