INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '책상도 안닦여져있고 바닥도 더러워서 치워달라고 카운터에 문의했는데 올라오시지도 않고 기다리다 휴지로 치우려고했지만 그 때 오셔서 제가쓰던휴지로만 닦고 가셨습니다. 걸레를 물어봤는데 아래도 닦냐고하셔서 저희는 책상 위에를 닦아달라고 했는데 서비스가 영좋지 않고 먹고 싶은 기분이 전혀들지 않는 곳입니다. 서비스를 기대하고서 오시는 건 매우 비추입니다. 직원들 상태가 좋지않네요', 22, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '2 ~ 4층 규모로 이루어진 대형 투썸이에요. 엘베랑 계단 모두 있고, 엘베는 조금 좁을 수 있어요. 주문은 2층에서만 하고 사람이 주말이라 엄청 많았어요. 그래서 자리 찾기는 쉽지 않았어요. 메뉴도 다양하고, 키오스크는 2개 있어서 사람 많을 땐 줄 서서 주문했어요. 인테리어는 분위기도 좋고 깔끔했어요.', 57, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '매일 투썸의 수박주스를 먹고 있습니다 . 근데 점바점인지 홍대점은 수박주스가 너무 달지가 않고 얼음을 많이 넣었는지 너무 싱겁습니다..그래도 깍두기수박은 3조각 올려주셨네요.. 저희 동네 투썸은 수박주스가 엄청 달고 맛있지만 깍두기 수박은 2조각 올려주시는데... 레시피가 잘못된건지 얼음양을 조절하셔야 될거 같네요 ㅠㅠ', 11, 0, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '아르바이트생이 무례합니다. 대답할때 뒤도 안 돌아보네요. 돈 내고 이런 대우를 받아야 하는건가요? 홀케이크 사는데 케이크 칼도 안주고... 대충 손으로 잘라먹으라는 뜻 잘 알겠습니다..', 49, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '커피랑 디저트 맛있긴한데 남자직원이 일하기싫은건지 저녁이라 응대하기 귀찮은건지...ㅋㅋ 서비스직에서 일했어서 최대한 손님입장으로 갔을때 친절하게하는편인데 저뿐만아니라 앞사람, 뒷사람한테 세상 귀찮아하는응대태도가 기억에남네요', 17, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '솔티드 카라멜 케이크 바뀌어서 살짝 걱정되었는데 이것도 맛있었습니다 스초생 프라페는 딸기가 없는지 산딸기로 나왔는데 산딸기도 나쁘지 않아서 좋았어요', 5, 4, 'GOOD', SYSTIMESTAMP);
