INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '복숭아가 가득 들었고 음료는 상큼달달하니 맛있어요 하지만 복숭아 큰 조각은 얼어있던거라 맛 없으니 먹지마세요 커피는 제가 먹은게 아니라 잘 모르겠고 케이크는 맛있어요 스누피는 초코인데 이런 류 초코 특 별로 맛 없으니 되도록 안 먹는걸 추천드려요', 317, 52, NULL, SYSTIMESTAMP);
