INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '입장 후 인원많아서 투썸오더로 주문한 후 4층자리에 착석 각 층마다 꽉차있었고,특히 오더와 픽업이 이루어지는 2층은 매우 붐빔 약 15분후 음료픽업 핫초코는  맛이 밍밍한가(?)싶었는데,잘 녹지 않은 상태였네요. 카페라떼는 맛있었어요. 여자 화장실은 4층인데 비번이 있고,영수증에 비번 적혀져 있었어요.', 32, 0, NULL, SYSTIMESTAMP);
