INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '종업원들이 불친절해요 계산전에 화장실 비번을 물으니 안가르쳐주네요 여럿이가서 화장실 가고싶은 사람은 얘기해놓고 나머지가 고르는 중에 미리 화장실 좀 먼저쓰자했더니끝까지 안가르쳐주네요 어차피 안먹고 갈것도 아니고 급한 한사람만 먼저 좀 쓰겠다는건데 주문 끝내고 영수증 하단에 비번 나오니 그거보고 가래요😂', 108, 20, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '여기 키오스크 매장인데 까페모카에 생크림 빼는 옵션이 없어서 매번 직원분께 말씀드려야해요 ㅠ 직원분은 친절하십니다 !! -> 한 분만 고객들 응대해서 너무 힘들어보여요', 81, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '모바일쿠폰 쓸 거 있어서 방문했어용 디카페인 말고 원두 두 가지 중에 고르는 거였는데 산미 없는 걸로 추천 받아서 마셔봤드니, 꽤 진하더라구요. 좀 써서 얼음 녹여먹으니 괜찮았어요~ 계단이 꽤 좁고 가파른 거 같아서 음료 엎기 쉬울 거 같아요. 2층에서 잘 쉬다 갑니다요~', 30, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '아아랑 스크램블에그 샌드위치 단품으로 시키니까 조금 더 할인 받을 수 있게 세트메뉴로 바꿔주시는 센스쟁이 여직원분 감사합니다.파니니도 맛있고 애플망고도 애들 입맛에 딱이네요^^ 2,3,4층 구성되어 있어서 생각보다 매장넓고 폭염에 휴가철이라 사람없네요~', 6, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '다 좋은데 시킨 음료마다 너무 달았어요 전 그린티 라떼 핫을 주문했는데 마시다 마시다 도저히 안되서 가지고 있던 생수를 부어 섞어 마셨다는...', 21, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '❤️커피는역씌 투썸❤️ 음료도 너무 맛있고 바쁜 매장인데 직원분들이 빠르게 음료를 내어주셔서 너무 좋아요 홍대오면 개인카페 가기 싫으면 항상 여기만 와요 ㅎ 엘리베이터도 있고 화장실도 남녀 구분되있고 깨끗해서 쉬어가시 너무 좋고 특히 시원하다 못해 추워서 좋음😆👍', 74, 11, 'GOOD', SYSTIMESTAMP);
