INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '다녀본 서비스 매장 중 최악입니다 직원같으신 키 작고 좀 통통한 ㅈ으로 시작하시는 분 서비스 직인데 표정도 너무 안 좋고 말도 잘 안 들리고 뭐라고 하시는지; 바쁜 매장이라 그런 건 이해하지만 메뉴가 안 될 딴 정확한 설명과 이유, 손님이 괜찮다고 달라는데도 표정 구린 거, 오래 있을 거라고 얘기했는데도 무시하는 표정과 말투 참... 서비스 신경쓰셔야할듯;', 81, 11, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '아니 손님들이 앞에서 떡하니 기다리고 있는데 알바생들은 음료 만들지도 않고 서로 얘기하면서 웃느라 바쁘고 어떻게 만드는지 숙지가 덜 되면 빨리 보고 만들던가 해야지 이게 맞나요;; 일요일 오후 8시쯤 알바생분들 교육좀 다시 시키세요', 5, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '제일 기대했던건 블루베라파르페였는데 맛나네요 ㅎㅎ 요거트아이스크림이라 기대했는데 걍 아이스크림이라.. 그리고 과자들은 그닥.. ㅎㅎ 그래도 블루베리 부분은 먹을만했어요~ 티라미수 부드럽고 맛나고요~ 화장실이 영수증에 있는 번호를 키락에 눌러야 들어갈 수 있는걸 나중에 알아서 앞사람 나오길 앞에서 기다리며 나옴과 동시에 들어갔고 들어가서 잘 안잠겨 좀 고생했네욤 ㅎㅎ; 남자 화장실도 여자화장실도 여럿 그러더라고요 ㅎㅎㅎ 좀 고치길요~', 68, 12, NULL, SYSTIMESTAMP);
