INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '특정시간만되면 사람이 터져나서 조용히 있긴 힘들고 화장실 근처 좌석은 외국 관광객들이 너무 많다. 그 외엔 친절한 스탭들이 있고 푸드맛은 그냥그랬다.', 34, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '☕️ 👍 맛있어 보이는 케익도 많은 투썸ㅋ 다만 매장의 화장실 만큼은 깨끗히 관리 해주세요ㅜㅜ 카페 매장 내부 화장실이라 믿고 들어갔는데 바닥이 넘 지저분했어요ㅜㅜ', 91, 24, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '와..ㅋㅋㅋㅋ 스트로베리 초콜릿 프라페를 시켰는데 이미지에는 분명 생 딸기였는데 프라페에 올라온건 걍 산에서 따온 것 같이 생긴 냉동딸기ㅋㅋㅋㅋㅋ 따지려다가 말았네요. 별로에요. 생 딸기 올라간게 예뻐서 샀는데 냉동딸기 두조각 나오고^^ 참 맛있겠네요ㅌㅌㅋㅋㅋㅋ', 7, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '케잌 재고도 없으면서 주문받더니 나중에 사과의 말하나 없이 아까 주문한 케잌 재고 없으니까 있는 거 중에 다시 고르라니 당황스럽네요… 음료도 깜빡하고 나중에 준비해주고요. 서로 의사소통도 안되고 정신없고 기본 서비스정신도 없어서 실망…했지만 그 와중에 음료는 맛있어요.', 10, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '하아아압 💨 ⭐️⭐️ 무난무난합니다 2~3층 까지 있어서 좋아요. 그 대신 키오스크 주문이 필수고, 카톡으로 음료 완성 알람을 받아야 합니다. 이번에 신메뉴가 많이 나온 것 같아서 좋았어요!', 14, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '날씨가 추웠던 그날. 투썸 방문해서 커피를 시켰지만. . 너무 미지근하네요. 손님의 회전률을 생각해서 매장입장에서는 미지근하게 만들어서 판매한다는건 나쁜게 아니지만. . 손님입장에서는 . . 이건 아닌듯. .', 12, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '친구들 합동 생일파티가 있어서 케이크 구매했어요. 각자 케이크 취향이 달라서 고민하던 중 레드벨벳, 고구마밀크생크림, 초콜릿수플레, 퀸즈캐롯 4가지 종류를 동시에 맛볼 수 있는 ‘마이 투썸 하트’ 로 결정했어요! 너무 맛있었고 친구들 반응도 좋았네요.👍 직원분들도 바쁜 와중에 친절하셨어요. 매장도 2-4층이라 넓어서 홍대에서 단체모임 하기 좋아요.', 23, 6, 'GOOD', SYSTIMESTAMP);
