INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '사람이 너~~~무 많아요! 일층에서 다들 담배피는데 담배 연기가 너무 올라와서 괴로웠어요ㅠㅠ 음료도 나오는데 너무 오래걸리더라고요.. 흙흙..', 47, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '홍대에 갈때마다 늦게까지 영업해서 늘 방문하는 곳이에요💕 항상 깔끔하고 밝은 분위기 넘나 좋아요❤️ 늦게까지 얘기하기 굿굿 😁', 12, 6, 'GOOD', SYSTIMESTAMP);
