INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '10월 9일 15시경 메뉴 픽업을 기다리고 있는데 알바생이 쟁반이 없었는지 반납대에서 쟁반을 가져오더니 뻔히 앞에서 보고 있는데에도 불구하고 닦는 시늉도 없이 음료와 디저트를 올리더라구요. 그래서 원래 쟁반 안닦고 주냐고 물어보니 그럼 닦아드려요? 되물어보더군요. 당연히 네라고 했더니 주방에서 다시 쟁반을 가져오더니 기분나빴는지 쟁반을 던지듯이 두고 닦더니 음료만 올려두고 말도 없이 그냥 가시더라구요. 남이 쓰던 쟁반을 닦아서 나가는건 기본아닌가요? 교육을 어떻게 시켰는지는 모르겠지만 위생,말투,서비스 모두 엉망이네요. 식약처 등급 매우우수라고 적혀있는것 좀 부끄러워 하셔야겠네요. 사람이 많아 바쁜걸 떠나서 이건 뭐 최악이네요. 누군지 성함까지 알아왔지만 따로 말씀은 안드릴게요. 앞으론 주의부탁해요.', 9, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '너무 더워서 투썸와서 티라미수빙수먹었어요 ㅎ 처음먹어보는데 진짜 맛있네요 ㅎㅎ 새로운 느낌의 빙수였습니다 실내 인테리어도 너무좋고 앉아서 얘기하기 편한 구조에요~', 66, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '투썸 좋아하는데요 직원분들이 너무 바쁘셔 보이긴 하셨어요 계속 음료주문은 아닌데 무얼 만드시고 계시더라구여 그래서 조금 기다리다가 안되겠다 싶어서 주문해도 되냐고 여쭤봤는데 아무도 안받아주셨어요ㅠㅠ 민망했어요 ㅋㅋㅋ 3번째쯤 외치니까 주문 받아주셨네요,,, ㅠㅠ 넘 바쁘셔서 그런거겠죠? 쨋든 민망했네여 ㅎㅎ', 9, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '매장에서 먹어서 유리컵에 받았는데 음료 기다리면서 어쩌다 설거지하는 모습 보게 됐는데 퐁퐁도 안하고 맨손으로 컵 닦으시던데 좀 찝찝하네요.. 그냥 일회용 컵이 더 위생적이고 기분 안 나쁠 거 같아요', 50, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '인테리어가 깔끔하고 테이블 배치도 나름 괜찮네요. 그런데 손님이 많아서인지 직원들이 기본적으로 화가 있어 보여서 안타깝네요… 물론 그 중에서도 몇 분은 친절하셨는데 손님이 진짜 많아서 이해는 됐습니다.', 42, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '아니 ㅋㅋㅋ 음료나왔는데 불러주지도않고 다른사람들은 쟁반에주면서 떡하니 올려두고서 쟁반없나요? 이러니까 던져주는거 실화 … 나뭐 잘못했나요? ㅋㅋㅋㅋㅋㅋㅋ 나한테왜그래요', 2, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '4층까지 있어서 넓고 좋아요 (다만 그만큼 사람이 많아 조용하진 않아요.. 그리고 4층이라 그런지 여자화장실이 수압이 너무 약하니..휴지X)', 29, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '남편이 배가 아파서 화장실이 넘 급했는데 주문하는 과정에 못 참아서 화장실 비번부터 알려달라니까 안된다고 영수증에 써있다구..덕분에 바지에 실수 할뻔..주문 안하는것도아니고 카운터에서 주문을 하고 있는데두 안된다는건 몬지..좀 융통성이 없네요..짜증이 확나서 음료 한잔만 주문했음. 화장실만 이용하는 사람들 때문에 그런건 이해하겠지만 상황에 맞게 해야할것 같아요', 75, 15, 'BAD', SYSTIMESTAMP);
