INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '키오스크 진짜 그지 같음.. 터치가 잘 안먹혀서 한참 걸려요.. 그리고 직원들 아무것도 안하면서 줄 길게 서 있어도 포스기로 주문 안받아주더라구요;;', 64, 14, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '홍대 중심에 커다란 투썸!!! 사층건물에서 2-3-4 쪼로록! 공간도 넓고 좌석 간 거리도 넓고! 다 좋아용 후후 콤부도 맛있어요!', 36, 10, 'GOOD', SYSTIMESTAMP);
