INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '케이크 너무 딱딱하고 맛없어요 오랜된 듯 직원은 계산도 엉터리 주문 실수도 인정 안하고 사과도 없고 다시는 이용하고 싶지 않아요~ㅠㅠ', 45, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '처음에 잘못주문했는데 넘 친절하셔서 감동 먹었어요 ㅠㅠ 홍대라 바쁘실텐데 체크해주시고 이벤트 몰랐는데 먼저 캐치하셔서 사이즈업도 해주셔서 정말 감사합니다! 감동이예요!', 10, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '딸하고 홍대 옷 사러 왔다가 커피가 먹고싶어 찾은곳이 투썸플레이스 이다 커피 시키고 화장실에 가서 보니 경악을 금치 못함 넘~~ 더러워서 볼일을 보기가 싫었다 그러나 급하니 보고는 왔지만 넘 찜찜하다 어떠한 이유라도 업장은 고객에게 깨끗한 화장실을 제공해야 한다고 생각한다 제발 좀 개선이 되었으면 바램이다 다음에 또한번 왔을때는 실망이 없었으면 한다', 438, 33, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '여자 화장실이 너무 더러웠어요.... 요즘 같은 시국에 화장실에 비누가 없었어요. 왜 4층 화장실은 개방 안하는지... 빙수는 냉동과일을 사용한 우유빙수라서 시원했어요.', 11, 8, 'BAD', SYSTIMESTAMP);
