INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대예술의거리점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '너무 바쁘셔서 그런 건지 얼음 덩어리가 너무 커서 버블티 먹을 때 쓰는 빨대로도 안 올라오네요ㅜㅜ빨대를 숟가락 용도로 썼습니다ㅜㅜ테이블이 지저분해서 닦고싶었는데 음료 반납하는 곳에 넵킨도 없어서 화장실에서 휴지 뜯어서 닦았어요ㅜ다음에 왔을 땐 시정되어있으면 좋겠네요', 41, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '커피 라떼가 너무 맛있어요 특히, 디저트가 다 맛있고 쿠키가 쫀득거리고 고소해요 다른곳에 없는맛이에요 여기 올때마다 자주 먹어요 분위기도 너무좋고 대화하기도 편하고 자꾸만 머무르고 싶은곳이네요 예전에 찍었던 사진 다시 한번 투척해봅니다 포장보다는 카페에서 먹어야 사진이 훨씬더 이뻐요 ㅎㅎ 공명라떼 진짜 맛있고 브라우니 맛집이에용', 36, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
