INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '홍대 온 김에 친구랑 방문했어요:) 빵이 맛있다고 해서 레몬마들렌과 바닐라 마들렌도 주문했는데 크기도 크고 맛있어보이더라구요:) 원두도 기본, 산미, 디카페인에 예쁜 이름으로 선택이 가능해서 주문부터 기분이 좋았습니다. 매장도 넓고 깔끔한 분위기라 이용하기 너무 좋은 공간인데 평일에 방문하니 꽤 널널하게 이용할 수 있는 정도 큰 장점인 것 같아요ㅎㅎ 홍대에서 대형 카페 찾으시거나 가기 좋은 카페 찾는 중이시라면 한 번 방문해보세요~!', 245, 38, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '연남동 올 때 이따금씩 들리곤 합니다. 홍대 연남동 카페 중 좋아하는 곳인데 넓고 다양한 좌석, 좋은 음악, 향 좋은 커피와 음료 그리고 참 먹음직스러운 베이커리들로 행복해 지는 곳이에요! 도로가를 바라보며 좋은 음악 들으며 이쁘기도 하고 여러 맛이 느껴지는 공명라떼 한 잔 하니 오늘 하루 힐링하는 느낌이에요~ 부드러운 생크림에 커피와 설탕 시나몬이 어우러진 공명라떼 추천합니다! 집에 갈 때 베이커리 포장도 해야겠어요 :D 또 올게요!', 33, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
