INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '브라우니가 정석 그 자체였습니다! 쫀뜩 꾸덕~ 홍대 원두의 산미 또한 풍부해서 맛있었고, 연남 공명 라떼의 크림은 묵직함이 있어서 브라우니를 찍어먹으니 정말 맛있었습니당ㅎㅎ 연남동 카페 중 규모도 있는 편이라 편히 쉬다 갑니다 :)', 50, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '예전부터 와보고싶었던 카페였는데 평일이라 마침 자리가 있어서 바로 방문했어요 ~ 홍대에서 드물게 내부가 넓은 카페라 갑갑하지 않아서 너무 좋아요. 커피가 진짜 맛있고 직원분이 너무너무너무 친절하셔서 기분이 좋아지는 카페였습니다 💗', 67, 18, 'GOOD', SYSTIMESTAMP);
