INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '연남동 카페 중에 작업할 수 있는 넓은 카페 찾기 쉽지 않은데 드디어 찾았어요!! 구매할 때 번호만 입력하면 15% 적립도 돼서 가성비도 좋습니다,, 콘센트 있는 좌석도 꽤 있고 분위기도 너무 좋아서 작업하러 오시든 대화하러 오시든 뭐든 다 좋습니다 🤤🤤🤤🤤', 18, 2, 'GOOD', SYSTIMESTAMP);
