INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '예전에 회사주변이라 처음 생겼을때 와봤었는데 그때도 회의하거나 끝나고 약속 잡았을때 종종 왔었던 곳입니다. 크게 변하지 않고 아직도 운영을 하고 있어서 반가운 마음에 다시 와봤습니다. 라떼는 아직도 고소하고 맛있어요. 커피맛집인데 에이드도 청량하니 맛있어보였어요. 비스킷슈가 유명해서 다들 집으시던데 다음에 와서 먹어봐야겠어요. 좌석이 넓어서 혼자오기에도 좋고 여럿이 오기에도 좋은 곳입니다.', 6, 8, 'GOOD', SYSTIMESTAMP);
