INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '연남동 카페 찾다고 온 곳인데 분위기도 좋고 자리도 많아서 좋았어요 디저트가 맛있고 음료가 정말 맛잇어요 여럿이서 오기에도 좋은거 같아요! 👍', 109, 24, 'GOOD', SYSTIMESTAMP);
