INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '또또또간집 카페 공명! 연남동 카페 중에 장소가 넓고 쾌적해서 좋아해요 그리고 생크림 스콘이 진ㅋ자진짜진짜 맛있고, 포장도 깔끔하니 선물하기도 좋아요! 무엇보다 15퍼센트 적립해주는 게 미쳤어요', 39, 4, 'GOOD', SYSTIMESTAMP);
