INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '넓고 편안한 분위기의 홍대 카페를 찾다가 발견했어요! 직원분들도 친절하시고 원두 종류가 여러개인 것도 좋았어요 베이커리 종류도 많아서 다음엔 먹어보려고요! 연남동 카페 홍대 카페 찾고 계시면 추천입니다👍', 18, 8, 'GOOD', SYSTIMESTAMP);
