INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '버스 타고 지날 때마다 항상 사람이 많았어서 언제 한번 가봐야지 했는데 평일 낮에 처음으로 방문해봤어요. 평일 낮이라 그런지 좌석은 반 넘게 여유가 있었어요. 좌석 종류가 여러 개라 혼자 작업하기에도 좋았어요! 공명라떼 위 크림이 진짜 맛도리에요,,, 연남동 대표 카페 인정!!!', 43, 3, 'GOOD', SYSTIMESTAMP);
