INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '연남동오면 항상 공명 카페를 찾아요. 매장도 넓고 무엇보다 커피맛이 정말 부드럽고 좋아요. 스콘, 쿠키, 슈 등 다양한 디저트도 있으니까 다음에도 재방문해서 다 먹어보려구요 !!!', 11, 1, 'GOOD', SYSTIMESTAMP);
