INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '크림 맛집 이에요! 커피랑 스콘에 크림이 많아보여서 다먹을 수 있을까 했는데 생각보다 많이 달지않고 맛있어서 다 먹었어요! 그리고 매장 분위기 차분하니 너무 좋고 공간도 아주 넓어서 여유롭게 머물기 좋았어요 :) #연남동 카페', 79, 11, 'GOOD', SYSTIMESTAMP);
