INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '연남동이 사무실인 친한 지인과 업무미팅을 했습니다 밖에서 봤을땐 여기가 카페인지 뭔지 딱 눈에 들어오지 않았는데 들어가보니 연남동에서 흔치않은 대형카페군요! 아주 맘에 들어요 😸 커피와 베이커리 맛도 평균이상입니다. 재방문 의사 아주 많아요!', 127, 26, 'GOOD', SYSTIMESTAMP);
