INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '홍대 공명카페 다녀왔는데, 분위기부터 음료까지 하나하나 다 만족! 시그니처 공명라떼는 진한 커피에 부드러운 크림 올라가서 달달하면서도 고소함 가득하구요ㅎㅎ아인슈페너도 깔끔한 끝맛이라 커피 좋아하는 사람들 취향 저격일 듯. 특히 비스켓 슈는 겉은 바삭, 속은 촉촉해서 커피랑 찰떡궁합! 크림이 달콤하고 고소한 맛이 입안 가득 퍼지는 느낌이 넘 맛있어요ㅎㅎ', 21, 8, 'GOOD', SYSTIMESTAMP);
