INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '일이 있어 연남동 왔다가 널찍한 카페 오고 싶어서 왔어요. 커피원두 고를 수 있어 좋네요~~ 산미 있는 것으로 골랐는데 맛있어요~', 4, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '여자친구가 좋다고 해서 처음 와봤는데, 데이트로도 참 좋은 장소에요! 스콘이 참 맛있었고 커피도 맛있었어요. 분위기도 차분하면서 산뜻해서 대화나누기도 좋고, 무엇보다 노래도 힙하고 좋아요. 메뉴판도 신기했고..ㅋㅋ 앞으로도 연남점 말고도 다른 지점들도 가보고 싶네요', 50, 7, 'GOOD', SYSTIMESTAMP);
