INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '직원분들 여전히 친절하시구요 디저트도 맛있어요! 에어컨 빵빵하게 틀어주셔서 있다보면 추워집니다ㅋ 덕분에 커피를 더 마시게 되구요 점심시간이 훌쩍 지났는데도 손님이 많네요 앞으로 연남동 약속장소는 이곳으로! ㅋ', 16, 6, 'GOOD', SYSTIMESTAMP);
