INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '연남동에서 더위를 피해 들어왔던 카페공명! 내부 분위기도 예쁘고 대화하기도 너무 좋았어요 :) 연남동 카페 중에서 넓고 쾌적함으로는 최고인거 같아요...! 아이스아메리카노 맛도 좋고 공명 라떼 크림도 은은한 시나몬 향이 좋았습니다🤗', 16, 3, 'GOOD', SYSTIMESTAMP);
