INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '혼자서도 종종 오는데 오늘은 친구랑 같이 왔어요ㅎㅎ 매장도 커서 친구랑 앉아서 수다 떨고 가기 넘 좋고, 잠깐 노트북으로 할 거 하다 가기도 좋네요! 디저트도 맛있어서 매번 올 때마다 다른 종류로 사먹는 재미도 있어요ㅋㅋㅋㅋ 홍대 오면 들르기 좋은 카페 같아요!💗', 92, 19, 'GOOD', SYSTIMESTAMP);
