INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '비오는 일요일에 방문! 매장이 넓고 분위기가 좋아서 더 감성 넘쳤어요✨ 연남동 카페갈때나 홍대 카페 찾을때마다 방문하는데 오늘은 웨이팅 없이 들어와서 더더 좋았습니당☺️ 자몽실한 자몽에이드 존맛탱!!!!!💕', 88, 11, 'GOOD', SYSTIMESTAMP);
