INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '좌석이 많은데 사람이 많아서 저희도 앞에서 기다리다가 들어갔어요. 4인테이블은 인원이 정해져있고 소파테이블이 인기가 많았어요. 커피는 컵 사이즈보다 양이 적어요. 공명라떼는 컵 겉부분에 흑설탕이 있고 위에는 시나몬 가루가 뿌려져있어요. 홍대 카페 맛집으로 추천해요!', 90, 14, 'GOOD', SYSTIMESTAMP);
