INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '제주도에서 서울놀러왔다가 검색해서 찾아왔어요! 분위기좋은 카페네요~최애 아인슈패너도 맛있고,아이에게는 우유스콘이랑 밀크티 주문해줬는데 말도없이 와구와구 먹는중요~!! 다음에도 방문할께요!!', 7, 0, 'GOOD', SYSTIMESTAMP);
