INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '연남 카페 검색해보다가 스콘이 맛있어 보여서 방문하게 됐는데, 맘모스랑 우유 생크림 둘다 맛있어요! 커피도 향이 좋아요 무엇보다 매장이 넓어서 사람이 많아도 대화하기 좋은 것 같아요 다음에 또 방문하겠습니다 :)', 72, 17, 'GOOD', SYSTIMESTAMP);
