INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '연남동 카페 중에 대형카페 잘 없는데 여기는 넓은편이라 여유로운 분위기가 좋아서 자주 옵니다! 커피도 맛있고 디카페인도 있어서 좋아요! 디저트는 스콘 최고!!!', 23, 0, 'GOOD', SYSTIMESTAMP);
