INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '홍대점 갔다 맛있어서 또 왔어요 분위기도 좋고 직원분들이 꼼꼼하신 것 같아요 음악소리가 커서 작업 및 공부는 어렵겠지만 대화하기 좋을 것 같아요', 49, 10, NULL, SYSTIMESTAMP);
