INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '스콘 원래 안좋아하는데 여기 스콘은 진짜 맛있어용 ㅎㅎ라즈베리랑 고구마가 맛있는데 오늘은 라즈베리로 시켰어용 ㅎㅎ스콘이 촉촉하고 크림이 많이 달지않아서 좋은것같아요❤️', 125, 23, 'GOOD', SYSTIMESTAMP);
