INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '연남동에서 점심먹고 홍대카페 검색후 방문 복쟙하지않고 넓어서  맘에 들어요 시그니처 메뉴 공명라떼 핫인줄 알았는데 아이스라떼 ^^ 달달한것 먹고 싶을때 괜찮은것 같아요 혼자방문해도 좋고 여럿이 방문해도 좋은 카페입니다 다음번에 지인이랑 같이 와야겠어요~~~ 다', 25, 10, 'GOOD', SYSTIMESTAMP);
