INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '시원하고 넓은 홍대 연남동 카페 공명이에요! 디저트도 종류가 많은데 모두 맛있고 커피도 원두를 선택할 수 있어 더 좋아요 편하게 대화하기도 좋은 분위기 좋은 카페예용', 1, 6, 'GOOD', SYSTIMESTAMP);
