INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '크림을 정말 아끼지 않고 듬뿍 넣은 메뉴들이 많아요!! 생크림이나 초코크림 듬뿍 든 스콘이나 공명라떼, 말차라떼에 크림을 아낌없이 넣어주셔서 너무 부드럽고 당 떨어질 때 생각날 맛!! 베이커리류도 다양하고 퀄리티가 좋아요👍👍', 38, 5, 'GOOD', SYSTIMESTAMP);
