INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '연남동카페 중에서 요즘 핫하다고 해서 찾아온 공명! 일간 카페 넓고 천고 높고 분위기 넘 좋아요^^ 특히 커피 향이 진짜 미춌습니다! 아메리카노도 향 너무 좋고 공명라떼 유니크하네요! 디저트 라인업도 빵빵하구 좋네요~!', 40, 3, 'GOOD', SYSTIMESTAMP);
