INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '연남동 카페 1위 공명 !! 항상 카카오라떼만 먹었는데 이번에는 새로운 메뉴를 먹어 보았어요! 사과 유자차인데요! 굉장히 맛있네요! 무더운 여름에 이 메뉴 추천해요!', 11, 5, 'GOOD', SYSTIMESTAMP);
