INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '비스킷 슈가 정말 부드럽고 안에 크림이 너무 달지 않고 맛있습니다!! 개인적으로 제가 너~~~무 좋아하는 초코나무숲 스콘도 맛있어서 평소 초코나무숲 즐겨 드시는 분들도 너무 좋아하실 거 같아요💝 퍽퍽한 걸 평소에 싫어하는데 여기는 스콘도 부드럽고 촉촉해서 진짜 짱맛🥖', 68, 14, 'GOOD', SYSTIMESTAMP);
