INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '마싯서요! 전 초코라떼 너무 좋아하는데 비싼 돈 주고 맛은 제티맛 날까봐걱정 많이 하거든요.. 근데 이건 너무 쓰지도않고 살짝 쌉쌀한 카카오맛이 딱 나서 너무 조앗어요ㅠㅜ 제가 먹고있는 빵은 라임 치아씨드 파운드케이크 마싯사용 살짝 신 하얀색? 시럽? 시럽은 아니고 고첸데.. 여튼 거기에 고소한 빵이 잘 어올려서 너무 좋아요! 추찬추천 합니당😻🫶', 8, 7, 'GOOD', SYSTIMESTAMP);
