INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '연남동 카페 & 홍대 카페중에 손가락안에 드는 디저트 맛집이에요!! 슈가 종류별로 많은데 배불러서 다못먹어본게 한이네요ㅠㅠㅜ 나중에 또와서 다먹어볼게요!!', 80, 13, 'GOOD', SYSTIMESTAMP);
