INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '홍대입구역에서 가까워 방문하기 좋은 홍대 카페입니다. 크림 잔뜩 들어간 스콘은 겉이 바삭하고 속은 부드러워요. 크림이 가득 들어가지만 느끼하지 않네요. 우유크림이 많이 달지 않고 초코크림보다 식감도 더 부드러운 게 정말 맛있습니다.', 31, 7, 'GOOD', SYSTIMESTAMP);
