INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '#협찬 여기는 베이커리맛집이에요 커피도 맛있었지만 베이커리가 어마어마합니다! 여기오실때는 밥은 간단히 드시고 오셔야해요!! 크림으로 가득한 곳이라서 아메리카노는 필수 디저트는1인1디저트합시다!!', 36, 7, 'GOOD', SYSTIMESTAMP);
