INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '분위기도 좋고 일정 주기별로 읽을 수 있는 책도 바꿔 전시해둔 것이 좋습니다 홍대 연남 합정으로 원두 종류가 있는 것도, 메뉴판이 책꽂이처럼 구성되어있는 것도 신선해요 커피나 디저트 맛도 너무 좋습니다 :)', 2, 5, 'GOOD', SYSTIMESTAMP);
