INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '홍대 주변에 무수히 카페가 많지만 바리스타로서 커피가 맛있는 카페를 찾기란 그리쉬운 일이 아닌데, 공명의 아메리카노는 충분히 맛있다♡ 여기에 더해 매장 넓고 자리 많고 쾌적하다. 우유케익은 기대에는 살짝 미치지 못한다^^ 메뉴판이 책장 형식으로 재미있게 만들어져 있고, 스텝이 친절하다.', 24, 0, 'GOOD', SYSTIMESTAMP);
