INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '디저트가 달달하고 너무 맛있어요. 홍대카페인데 대기가 없어서 편히 쉬다 갑니다. 커피가 진짜 최고에요 👍 다음에 또  방문하겠습니다.', 86, 17, 'GOOD', SYSTIMESTAMP);
