INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '연남동 카페 중 최애 입니다 소음이 없는건 아니지만 넓고 쾌적하며 카공하기에도 좋고 친구들과 놀러오기에도 아주 좋습니다 접근성도 좋고 커피는 물론 음료, 디저트도 깔끔해요! 편의를 위한 것들이 느껴집니다', 114, 26, 'GOOD', SYSTIMESTAMP);
