INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '소문으로만 들어본 공명에 처음 왔는데 층고 높고 테이블도 많고 시원시원해요! 인테리어도 우드톤이라 차분하고 멋스럽네요 ㅎㅎ 시그니처인 공명라떼랑 공명밀크티를 시켰는데 라떼 크림 꾸덕하니 맛있고 밀크티도 진하니 맛있네요! 앞으로 자주 올 것 같아요~', 118, 20, 'GOOD', SYSTIMESTAMP);
