INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '공명에는 맛있는 매뉴 많지만 최애커피는 공명라떼예요. 꾸덕한 크림 잔뜩 올려주시는데 크림이 정말 찰지고 맛나요! 매장도 넓고 쾌적해서 더운 여름에 시원한 음료 마시며 더위를 피하기 최적의 장소입니다.', 1, 9, 'GOOD', SYSTIMESTAMP);
