INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '지나가다 쿠키슈가 맛있어보여서 들렀어요. 말차/초코 쿠키슈, 공명라떼, 플랫화이트 주문했는데 다 너무 맛있네요. 다음에 또 오고 싶어요.', 11, 1, 'GOOD', SYSTIMESTAMP);
