INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '연남동 카페 찾다가 우연히 들른곳인데 음료도 맛있고 베이커리 종류도 다양해서 정말 좋습니당! 층고도 높고 좌석도 다양하고 넓어서 홍대 올때마다 주기적으로 올 것 같습니다💕', 28, 6, 'GOOD', SYSTIMESTAMP);
