INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '투표하고 들른 연남동 ㅜㅜ 생각보다 센 햇빛에 너무 더워서 쉴곳을 찾다가 일전에 스타처리해둔 곳이라 들렀는데 넓직하고 편안하게 쉬고가기 좋은 카페에요! 연남동에 이렇게 넓적하고 쾌적한 느낌의 카페가 없는데 잘 찾아왔다 싶어요😊 디저트도 맛잇어 보였는데 배부름 이슈로 이번엔 패스햇는데 담에 먹어보고 싶어요😎', 85, 16, 'GOOD', SYSTIMESTAMP);
