INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '연남동 카페 중에서 책읽을만한 곳을 찾다가 북카페 키워드로 검색 후 찾아오게 되었어요! 다양한 디저트들이 많고 커피원두도 세가지나 돼서 좋네요. 혼카페하시는 분들도 많아서 추천합니당 ~~', 24, 5, 'GOOD', SYSTIMESTAMP);
