INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '사장님께서 유튜브에 나오셨을 때 알게 된 카페인데 너무 괜찮아 보이더라구요..! 연남동 카페에 갈 일 있을 때 가보려구 저장해놨다가 이제서야 왔는데 디저트 너무 맛있구 커피도 맛있어요 ㅎ 매장도 넓구 좌석도 편해서 대만족!!', 28, 4, 'GOOD', SYSTIMESTAMP);
