INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '연남동 주변에 사진이 이뻐서 방문했는데 북카페느낌으로 너무이쁘고 생각보다 내부도 넓어서 사람이 빠지면 바로 앉을수 있어서 좋아요 스콘이나 쿠키도 하나같티 맛있고 음료도 네이버 지금행사중이라서 8천원이상맘 사면 무료니까 꼭 참고해서 주문하세요 대관이나 그런것도 하고 쿠키도 맛있게 잘먹었어요 ㅎㅎ 주말이 오면 사람이 많아서 좀 시끄럽지만 평일에 오면 한적하고 공부하기 딱 좋을거같아요!!!', 41, 4, 'GOOD', SYSTIMESTAMP);
