INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '비스킷 슈 먹었는데 달달하고 맛있었어요! 디저트 종류도 많고 시그니처 커피 ‘연남’ 너무 맛있어요:) 분위기 좋아서 책읽는데 집중도 잘 되었습니당😊', 35, 8, 'GOOD', SYSTIMESTAMP);
