INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '홍대에서 큰 카페를 찾고 있었는데 좌석들도 많아서 좋았어요! 다만 좌석들 간격이 넓은 편은 아닌지라 더 조용한 카페 찾으시는 분들은 다른 곳도 괜찮으실 것 같아요 그렇다고 너무 시끄러운 곳도 아니기는 하니 참고만 해주세요! 음료도 맛있었구 특히 디저트 맛집답게 스콘과 비스킷슈도 맛있게 잘 먹었습니다 앞으로 자주 방문할 것 같아요👍☕️', 90, 13, 'GOOD', SYSTIMESTAMP);
