INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '커피로 힐링했어요~ 베리 에이드는 블루베리가 많이 들어있고 너무 맛있었어요. 휴일이라서 사람이 정말 많아서 자리 전쟁이 있었지만 음료가 맛있어서 ^^ . 재방문 의사 있어요 ~', 4, 0, 'GOOD', SYSTIMESTAMP);
