INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '스콘도 진짜 미친맛인데 레몬 마들렌도 미친맛이네옄ㅋㅋㅋㅋㅋㅋ오노ㅠㅠ다이어트 어카져.. 아모루겠당..넘 맛있어요😭❤️ 공간도 넓어서 더 최고입니다ㅎㅎ 따봉', 23, 5, 'GOOD', SYSTIMESTAMP);
