INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '커피가 맛있어요~ 세가지 원두 중 ''연남''을 먹어봤는데 바디감있고 산미 은은하니 좋아요 추천요! 라임파운드 케잌 부드럽고 많이 달지 않네요^^ 순삭해버려서 사진은..ㅋㅋ 공간이 넓고 쾌적하고 테이블들이 개성있고 재밌어요 다음에 또 방문의사 있어요', 39, 6, 'GOOD', SYSTIMESTAMP);
