INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '시그니처 음료가 너무 특이하고 맛있어요!! 바리스타님이 추천하신 음료도 마셔봤는데 역시 추천하신 이유가 있네요👍👍 디저트 너무 다양하고 다 너어무 맛있게 생겨서 전부 담고 싶은 걸 참았습니다…❤️❤️ 직원분도 너무 친절하시고 재방문 의사 너무너무 있습니다!!', 116, 21, 'GOOD', SYSTIMESTAMP);
