INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '날이 너무 더워서 예약없이 왔는데 그냥 들어왔는데 매장도 크고 시원해서 좋아요! 바닐라빈 라떼 시켜먹었는데 적당히 달달하고 맛있어요 ㅎㅎ!! :) 다음 번에 올 땐, 디저트도 시켜먹어볼려고요☺️', 1, 0, 'GOOD', SYSTIMESTAMP);
