INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '연남동 카페 찾다가 비스킷 슈가 맛있어보여 들어왔는데 디저트가 종류도 많고 맛있어서 좋았고 시그니처 라떼인 공명 라떼가 시나몬향 나면서 맛있었어요 !!', 32, 4, 'GOOD', SYSTIMESTAMP);
