INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '네이버 지도에서 연남동 카페 찾다가 발견하고 우연히 들어오게 되었는데 너무 만족합니다! 들어오자마자 넓은 공간도 인상적이었고 전체적인 분위기도 개인 일에 집중하기 좋더라구요 그리고 콜드브루에 공명 바리스타 추천이 적혀있어서 그걸로 선택했는데 오랜만에 정말 맛있는 콜드브루를 마실 수 있어서 좋았습니다. 마지막에 카카오, 초코 맛이 인상적이었어요 다음에 또 들를 것 같아요 ㅎㅎ', 69, 18, 'GOOD', SYSTIMESTAMP);
