INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '원두는 3가지로 고를수있어용 산미가 약한게 연남이라고 해서 주문했는데 산미가 있긴했어용(그래도 맛있었어용🙃) 디저트가 달아서 아메리카노랑 먹으면 조합이 좋아요 원래 달달한 라떼 먹는편인데 아메리카노 시키길 잘했어여^0^ 주말 오픈시간에 갔는데 사람없어서 좋았습니당 책 읽기 좋은곳! 다음에 또 올게여', 92, 24, 'GOOD', SYSTIMESTAMP);
