INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '감성적인 분위기와 넓은 공간 덕분에 여유롭게 즐기기 좋은 카페였어요! 티라미수 마들렌과 에스프레소 쿠키는 달지 않아 커피와 잘 어울렸고, 바스크 치즈케이크는 부드럽고 진한 풍미가 너무 좋았어요!! 아메리카노는 깔끔하고, 아이스티는 상큼해서 음료도 맘에 들었고, 사진 찍기 좋은 인테리어도 만족스러웠습니다!!', 50, 10, 'GOOD', SYSTIMESTAMP);
