INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '맘모스콘, 우유케이크, 공명라떼 시켰다. 너무크림이 많이 든 메뉴를 시킨 것 같다. 좀 느끼했다. 맛있었지만 다 못먹고 맘모스콘 중간에 포장했다. 스콘과 우유케이크, 비스킷슈가 유명한 곳이다. 다 먹어봤는데 개인적으로 비스킷슈가 재일 맛있었다. 커피는 지난번 방문시 시켰던 콜드블루가 라떼보다 더 괜찮았다.', 102, 22, 'GOOD', SYSTIMESTAMP);
