INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '피스타치오 마들렌 부드럽고 고소하고 플랫화이트랑 잘 어울립니다. 오늘은 연남동 미용실 왔다가 책 읽으러 들렀는데 종종 꿀꿀한 날 디저트 먹으러 들러야겠어요^^ 담엔 스콘도 먹어봐야지..! #연남동카페 #홍대카페 #카페공명', 97, 19, 'GOOD', SYSTIMESTAMP);
