INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '홍대입구역에서 좀 걸으면 동교동에 가까운 카페 공명 연남점 나와요! 스콘이나 음료종류가 다른카페에선 볼수없는 새로운게 많아서 방문해서 먹었어요. 피스타치오 크림 라떼 완전 추천해요. 커피 못마시는분들 이 음료드세요. 달달하고 스트레스 풀리는맛임 키얏 🩷🩷  디저트도 맛있는거 많고 그중에 초코나무숲 스콘 짱 맛있어요. 디저트,커피값이 깡패긴 한데 맛있어서 패스.', 106, 23, 'GOOD', SYSTIMESTAMP);
