INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '홍대 카페 찾다가 들어왔는데 분위기가 엄청 좋아요!! 친구랑 떠들기도 좋고 그렇게 시끄러운 편은 아니라 혼자서 오시는 분들에게도 딱 좋은 카페인 거 같어요', 450, 90, 'GOOD', SYSTIMESTAMP);
