INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '연남동 카페를 검색하다 알게된 카페 공명! 리뷰보고 왔는데 사람많아서 웨이팅 길까봐 걱정했는데 운 좋게 딱 한자리 남아서 바로 입장했습니다! 디저트가 너무 맛있고 커피 맛도 죠아요 🤍', 28, 2, 'GOOD', SYSTIMESTAMP);
