INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '커피와 디저트 모두 넘 만족스럽습니다! 아이스라떼 디카페인은 균형감있는 맛이구요, 공명라떼 아이스는 시나몬가루가 올라가있고 달달하면서 깊은 맛이납니다. 비스키 슈는 겉바속촉해서 안에 크림이 꽉차있고 많이 달진 않아요. 모두 입맛에 잘 맞아요!', 29, 3, 'GOOD', SYSTIMESTAMP);
