INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '컴퓨터 작업하기 딱 좋은 카페예요. 넓은 책상이 곳곳에 배치되어 있고, 좌석마다 전원도 충분해서 노트북 작업이 아주 편해요. 에어컨도 빵빵하게 돌아가서 한여름에도 시원하게 집중할 수 있었고요. 사람 간 간격도 넉넉해서 오랜 시간 머물러도 눈치 안 보이고 좋았어요. 작업용 카페 찾는 분들께 강추합니다! 연남동 카페, 홍대 카페 중에서 일하기 좋은 카펭예요', 36, 5, 'GOOD', SYSTIMESTAMP);
