INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '회사 근처여서 종종 오는 곳입니다. 베이커리 케이크가 있어서 커피에 같이 먹기 좋아요. 분위기 괜찮고 역이랑 가까워서 좋습니다. 연남동 카페 추천합니다.', 46, 0, 'GOOD', SYSTIMESTAMP);
