INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '연남동 카페 공명 2번째 방문🫶 저번이 커피랑 스콘이 너무 맛있어서 또 왔어요 라떼는 공명라떼가 최고👍 언제 먹어도 크림이 산뜻하고 느끼한거 하나 없이 맛있어요! 다음에 또 다른 디저트 먹으러 올게요🙌', 50, 1, 'GOOD', SYSTIMESTAMP);
