INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '메뉴들 다 맛있어요! 평일 점심에 왔는데 자리도 널널하고 디저트들 종류도 다양해요~~ 우유케이크 진짜 맛있어요! 공명라떼도 그렇고 크림류 메뉴가 맛있어요~~', 36, 3, 'GOOD', SYSTIMESTAMP);
