INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '친구들이랑 연남동 카페 찾다가 들어온 곳인데 분위기도 좋고 커피랑 디저트도 맛있어요. 카페가 넓어서 자리도 많은 편이고, 특히 직원분들이 너무너무 친절하세요. 홍대 카페 찾으시는 분들이라면 여기 정말정말 추천드려요. 서울에 주차 자리 찾기가 어려운데 바로 옆에 주차장도 크게 있어서 주차 걱정도 없었어요! 인테리어가 책으로 되어 있는 점도 좋은 거 같아요 ㅎㅎ', 118, 23, 'GOOD', SYSTIMESTAMP);
