INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '공명 벌써 4번째 방문!! 인데 새로운 몽블랑 슈 나와서 적어봐요 ❤️ 신상 나와서 후다닥 먹으러 왔는데 몽블랑 좋아하시는 분들은 진짜 마싯게 잘 드실 수 있는 맛이랍니다 🤎🤎 밤 좋아하시면 꼭 이 디저트 시켜서 드셔보세요!! 음료는 공명 라떼 추천 ✨✨', 49, 0, 'GOOD', SYSTIMESTAMP);
