INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '홍대 입구를 지나다닐 때 책 읽기 좋은 카페 같아서 꼭 한 번 가봐야지 했던 곳이에요. 손님들 대부분이 노트북작업 , 독서를 하고 있어서 책 읽기 좋고 브라우니도 꾸덕하고 너무 맛있습니다. ㅎㅎ 다음에 또 올게요~~~~', 26, 1, 'GOOD', SYSTIMESTAMP);
