INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '[내돈내산] 루이보스차, 디카페인 아이스아메리카노 주문했습니다. 루이보스차는 딱 맛있고 진한 맛이고 디카페인 아이스아메리카노는 쓴맛이 없고 살짝 단맛이 느껴지는 원두였습니다. 콜드브루랑 비슷한 맛이에요. 매장 넓고 푹신한 의자 많아서 좋았어요. 조금 시끄럽긴한데 대화가 어려울 정도는 아니었습니다. 근데 다 좋은데, 트레이랑 음료 컵이 깨긴했어요ㅋㅋㅋ 살짝 노감성', 61, 16, NULL, SYSTIMESTAMP);
