INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '홍대 카페 올 때마다 방문하는 공명! 올때마다 사람많아서 자리 없을까봐 걱정하며 오는데 운좋게 자리 잘 찾아서 앉았어요! 다들 친절하시고 커피도 너무 맛있어요~', 27, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '무더운 봄날, 오후에 잠깐 홍대쪽에 잠깐 들렸다가, 더위도 피하고 잠깐 쉬기 위하여 서치하여 나온 공명을 오게 되었습니다. 몰랐는데 되게 유명한 카페였기에 반 정도 기대하고 방문하였는데 웬걸.. 반 이상 좋았던 카페가 되어버렸다. 일단 나 같은 학생들도 과제나 홀로 시간 보내기에 카페가 주는 분위기와 여유로움이 너무 좋았고, 메뉴를 고르다가 추천 받은 시그니처 커피 연남라떼를 기미상궁 해봤는데. 와 진자.. 너무 맛있었다. 비주얼은 시나몬 가루와 크림 범벅이라 헤비할 것 같다 느꼈는데 의외로 엄청 달지 않고 한국인이 좋아할만한 당도였다(핵맛잇다..👍🏻 직원분들도 너무 친절하시고 타지에서 온 나는 우리 광주에도 생겼으면 좋겠다라구 생각했다 ㅠ 서울 올 때마다 또 들릴 것 같다. 더위를 행복하게 식히고 간다.🧊', 8, 5, 'GOOD', SYSTIMESTAMP);
