INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '집 근처라 가끔 찾아옵니다. 친구들이랑 대화하기에 좋아요.  주말에는 자리가 없는게 흠입니다.  거의 열번쯤 왔는데 처음 리뷰 남기네요.  스벅이나 이런 거 말고 이런 카페가 오래오래 잘 됐으면 좋겠습니다.', 30, 1, 'GOOD', SYSTIMESTAMP);
