INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '연남동카페 공명카페 비오는날 약속 식사 후 방문했어요. 매장 크기도 넓고 조용하게 음료마시며 시간보내기 좋은 곳이에요. 분위기도 좋고 음료도 맛있어요 스콘맛집이라는데 스콘먹으러 또 오고싶네요', 50, 7, 'GOOD', SYSTIMESTAMP);
