INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '카페 분위기가 가볍지 않아 대화하기 좋고 잔잔한 여유를 즐기다 갈 수 있어요! 홍대에서 카페를 간다면 추천드리며, 연인과 진솔한 이야기하기 좋은 분위기와 책읽기 좋은 분위기를 가지고 있어요!', 107, 20, 'GOOD', SYSTIMESTAMP);
