INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '벌써 분위기로 압살. 넓고, 편하고, 무엇보다 조용해서 좋아요. 커피맛도 최고! 처음 와봤는데, 앞으로 연남동 카페 올 땐 여기만 찾을 거 같아요.', 47, 1, 'GOOD', SYSTIMESTAMP);
