INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '빵들이 폭력적으로 맛있게 생겼다. 원두는 고소한 맛고 산미있는 맛, 디카페인 중에 고를 수 있다. 모든 커피에 해당된다. 아이스티는 달고 맛있다. 카페라떼는 평범하다. 자리는 많은데 뭐랄까 공간이 좀 울린다. 그래서 전혀 조용하진 않다.', 1, 6, NULL, SYSTIMESTAMP);
