INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '카페가 넓고 쾌적해서 좋아요! 인테리어도 괜찮구요ㅎㅎ 공명라떼는 크림을 되게 포슬포슬하게 올려줘서 귀엽네요ㅋㅋㅋ 커피양이 좀더 늘어났으면 좋겠어요!', 25, 1, 'GOOD', SYSTIMESTAMP);
