INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '연남동 카페 방문하였습니다. 카페 공명 연남점으로 카페 분위기가 고급스럽고, 커피 디저트 모두 맛있습니다. 시그니처 커피인 공명라떼를 주문하였는데 너무 맛있네요. 다음에 또 방문하겠습니다.', 29, 4, 'GOOD', SYSTIMESTAMP);
