INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '외국인 친구들과 함께 방문했어요. 커피와 음료도 맛있고 디저트도 다 맛있었어요. 키오스크 예약 시스템이 있고 안에서 직원 분이 자리 정리를 잘해주셔서 정신없는 와중에도 차분하게 잘 마시고 왔습니다.', 28, 0, 'GOOD', SYSTIMESTAMP);
