INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '연남동 골목 속 아늑한 2층 카페 ‘공명’에서 여유로운 오후를 보냈어요. 공간은 따뜻한 분위기에 조용해서 친구나 연인과 오붓하게 이야기 나누기 딱 좋아요.', 74, 11, 'GOOD', SYSTIMESTAMP);
