INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '책 읽으면서 여유 부릴 수 있어서 좋아요~ 책 저자랑 사장님 이름이랑 똑같네요 ㅋ.ㅋ 사장님 책 힐링됩니다👍 카페라떼도 넘 맛있어요❤️', 31, 7, 'GOOD', SYSTIMESTAMP);
