INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '넓은 공간이 주는 편안함이 참 좋습니다.  은은한 커피 향이 기분을 더욱 향긋하게 만들어주네요.  따뜻한 음료 한 잔과 함께 여유로운 시간을 보내기 좋은 곳 같습니다.  섬세한 인테리어 덕분에 더욱 아늑한 분위기를 느낄 수 있습니다.  다음에도 다시 방문하고 싶은 매력적인 공간입니다.', 40, 9, 'GOOD', SYSTIMESTAMP);
