INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '홍대 카페 어디 갈지 고민하다가 매번 지나가기만 하고 들려본 적은 없어서 이번에 방문했는데 넘 깔끔하고 조용하고 분위기가 좋았어요 커피도 맛있고 브레드 종류도 다 입맛에 맞아서 좋았어용', 37, 2, 'GOOD', SYSTIMESTAMP);
