INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '재재재재재재방문 하는 카페공명연남점 (하트하트) 연남동 오면 꼭 와요 넘넘 맛있으니까 ㅎㅎ 공명라떼 필수에용 ㅎㅎ 홍대연남 카페 완전 추천!!!! #연남동카페 #홍대카페', 64, 16, 'GOOD', SYSTIMESTAMP);
