INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '자주 왔는데 리뷰는 처음 남겨요~공명라떼가 맛있어서 친구들 오면 데려 오는 곳이에요. 디저트도 다양하고 맛있어요. 늘 사람들이 많고 주말 오후는 인기가 많아서 자리 잡기 힘드니 빨리 오셔야 해요~동네에 이런 카페가 있어서 아주 좋아요!', 48, 1, 'GOOD', SYSTIMESTAMP);
