INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '주처가 된다고해서 일부러 왔는데 건물 유료주차장 이용해야하고 30분에 2,000원이네요. 커피는 무난하고 크림스콘 맛있게 먹었어요. 넓고 분위기 좋아서 차 없이 친구들 만나서 수다떨면서 차마시기 좋은것 같아요.', 26, 2, 'GOOD', SYSTIMESTAMP);
