INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '크기는 큰 편이고 겉에 쿠키가 빠작빠작한 게 아쥬 제 스탈입니다 쟌맛임ㅠㅠ 크림도 너무 맛있어요 지점이 더 많아지면 좋겠어요💜 제 유튜브에도 올림ㅋㅋ 연남동 오시면 꼭 가주세요', 20, 5, 'GOOD', SYSTIMESTAMP);
