INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '처음 방문했는데 들어가자마자 넓은 장소와 향긋한 커피향이 저를 반겨주었습니다. 홍대에 많은 디저트 카페 중 분위기 있는 곳을 찾으신다면 단연코 이곳입니다.', 32, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '달달한 디저트가 땡겨서 연남동 카페 검색하다가 왔는데 주변에 다른 카페들은 공간도 좁고 의자도 불편했는데 여기는 넓어서 너무너무 좋았어요! 그리고 단게 땡겨서 와서 저희는 브라우니랑 초코나무스콘? 시켰는데 둘다 달달하니 입맛에 딱 맞아서 대만족이었습니당ㅜㅜ🥹', 30, 9, 'GOOD', SYSTIMESTAMP);
