INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '혼자 노트북으로 작업하기도 분위기 너무 좋고 친구들 만나기도 좋은 연남동 카페 추천! 디저트 종류도 다양하고 감각적인 공간이에요!', 3, 1, 'GOOD', SYSTIMESTAMP);
