INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '연남동에 카페 많은데 평점 좋길래 와봤어요! 들어오자마자 보이는 디저트들 구경하다가 겨우 골라서 먹었는데요! 디저트도 맛있고 아메리카노도 원두 3개 고를 수 있어서 좋아요ㅎㅎ #연남동카페', 35, 9, 'GOOD', SYSTIMESTAMP);
