INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '연남동 카페 공명 방문했어요! 비스킷슈 맛있다고 해서 기대 돼요 카페 분위기도 너무 좋고 데이트하기 좋은 곳인것 같아요 직원 분들도 친절하세요 :)', 50, 3, 'GOOD', SYSTIMESTAMP);
