INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '친구들과 연초 모임으로 만나 카페 찾아보던 중 음료가 맛있어 보여 픽!했던 곳👍 커피를 못마시는 저는 ”딸기바닐라라떼“를 선택했어요! 딸기무스와 바닐라의 조합이 적절하고 딸기 말린 후레이크(?)가 크리스피하게 씹혀 맛있더라구요!!! 강추👍 사람들이 많아 부담없이 수다떨기 좋네요 다만, 시끄러울 수 있음 주의‼️', 22, 9, 'GOOD', SYSTIMESTAMP);
