INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '소중한 사람들 만날 때마다 방문하는 공명입니다:) 오늘은 주말이라 사람이 많긴하지만 여전히 맛있고 편안하네요! 대화하기 좋은 카페 찾으시는 분 추천합니다!', 22, 7, 'GOOD', SYSTIMESTAMP);
