INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '스콘 디저트류가 맛있는 연남동 카페 공명🍮 오랜만에 방문했는데 배불러서 스콘은 못시켰지만 ㅠ 아메리카노 디카페인인데도 너무 맛있구요☕️ 스콘 보니까 못 참겠어서 포장해가려구용🤣 홍대 카페 찾으신다면 추천추천!!', 14, 10, 'GOOD', SYSTIMESTAMP);
