INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '디저트가 다양하고 커피가 맛있는 카페입니다! 바닐라빈라떼 맛나요❣️ 출판사에서 운영하는 만큼 메뉴판과 인테리어 곳곳에 책이 있어서 재밌어요ㅎㅎㅎ', 87, 15, NULL, SYSTIMESTAMP);
