INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '홍대에서 지인들과 이야기 하러 왔다가 다같이 왔는데 카페 인테리어가 너무 예쁘고 매장도 넓어서 쾌적해서 좋았어요 좋았어요 홍대에 온다면 꼭 한번 방문하면 좋으실거 같아요!! 그리고 여기 디저트 진짜 너무 맛있어요ㅠㅠㅠ', 36, 9, 'GOOD', SYSTIMESTAMP);
