INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '연남동데이트 홍대역 내리자마자 카페인주유를위해 연남동카페 찾아보다들어온 공명  탁월한선택이었던거같아요 인테리어도 이쁘고 메뉴판이 책으로있는건 신선하네요 커피도 너무맛있고 디저트가 쵝오에요^^', 12, 3, 'GOOD', SYSTIMESTAMP);
