INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '전에 쿠키슈 먹고 반해서 다시 왔어요 ㅠㅠㅠ 진짜 제 인생 쿠키슈 겉은 바삭한데 크림은 넘쳐나고 시간이 지나도 눅눅해지지가 않아요 그땐 좀 시간이 지나고 먹었어서 오늘은 바로 먹기 도전 !!! 이번엔 까눌래가 있길래 같이 구매해 봤는데 생긴것 부터 넘나 맛있는거 있죠 >< 다른 디저트도 많지만 내 통장 잔고 문제로 오늘은 이 정도만 🥹 다음에 또 올게요 내 단골 맛집 !!', 25, 0, 'GOOD', SYSTIMESTAMP);
