INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '연남동에서 점심데이트하고 연남동카페 공명 추천이요!! 인절미 좋아해서 인절이쑥쑥케이크 시켰는데 할미입맛 저격!!! 시그니처로 공명라떼 시켰는데 올라가는 크림 맛있고 아메리카노도 원두 선택가능해서 입맛에 맛게 드시면 될거같아요!', 49, 5, 'GOOD', SYSTIMESTAMP);
