INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '일요일 아침부터 연남동 카페 방문했습니다~ 처음 와봤는데 커피도 맛있고 디저트도 달지 않아서 너무너무 좋아요🫶 제가 시나몬 못먹는데 직원분이 메뉴 주문과 동시에 말씀해주셔서 빼고 시켰어요! 너무 친절하시고 카페 공간도 넓어서 좋습니당🙌', 5, 7, 'GOOD', SYSTIMESTAMP);
