INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '라즈베리 스콘이 짱이고 아메리카노 고소합니다 제가 커피맛에 아주 예민한데 여기 아메리카노 만큼 맛있는 곳을 본 적 없을 정도예요 연남 오시면 꼭 카페 공명 오셔서 스콘 시키세요 저는 예전에도 와봤는데 바치케도 짱맛있음 추천 재방문 의사 100%', 41, 5, 'GOOD', SYSTIMESTAMP);
