INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '저번에도 한 번 왔었는데 연남동 카페 중에서 여기가 제일 편한 것 같아요 대화하기도 좋고 분위기도 좋아서 친구 뿐만 아니라 부모님 모시고 와도 좋을 분위기입니다!', 42, 4, 'GOOD', SYSTIMESTAMP);
