INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '아늑하고 감성적인 분위기가 정말 마음에 들었어요. 조용히 쉬어가기에도, 친구랑 수다 떨기에도 딱 좋은 공간이에요. 음료도, 디저트도 너무 맛있어서 하나하나 만족스러웠어요. 다음에도 꼭 다시 방문하고 싶어요.', 21, 5, 'GOOD', SYSTIMESTAMP);
