INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '지나가다 들렀는데 음료도 디저트도 너무 맛있어요 아니? 사실 맛없었어요 아메리카노에서 어떻게 에센스 맛이 나요? 매머드커피에서 1600원짜리 아메리카노 마시는 게 백배천배는 낫겠어요!', 1, 9, 'BAD', SYSTIMESTAMP);
