INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '오늘은 기분좋게 남편과 데이트 하는날이라 그런지 커피가 특별하게 맛있는거같아요^^ ㅎㅎ 직원분들 친절하셔서 더 맛있게 느껴지네요~ 공간이나 테이블간격도 넓어 대화에 방해받지 않았습니다. 홍대에서 아이픽업 기다리는데 홍대카페는 여기로 와야겠습니다~~', 94, 23, 'GOOD', SYSTIMESTAMP);
