INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '맨날  버스타고 지나가면서 보기만하다 친구랑 홍대 데이트하면서 첫 방문해봅니다! 친구도 홍대 카페 중에서도 핫플로 알고 있더라구요..! 빵도 다 맛있구 커피도 맛있습니다👍🏻', 38, 3, 'GOOD', SYSTIMESTAMP);
