INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '연남동 카페 공명 왔는데요 와... 여기 스콘이..  스콘이 진짜 너무너무 맛있어요 ㅋㅋㅋㅋㅋㅋㅋ 딱 겉바속촉이고, 고소함의 끝판왕 스콘입니다 ㅋㅋㅋㅋ', 40, 0, 'GOOD', SYSTIMESTAMP);
