INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '공간넓찍하니 조아요. 홍대 카페들 너무 좁고 오래 앉아있기 눈치보인적이 많았는데, 적당히 시끌 하니 차라리 맘도 편하구요, 멤버십 적립두 꿀~~! 오래오래 장사해주세요!', 48, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '이전부터 오고 싶어서 저장해둔 홍대 카페인데 드디어 들렸네요! 매장 내부도 엄청 넓고 깔끔하고, 디저트 종류도 다양해서 좋은 거 같아요 커피랑 쿠키도 맛있었습니다!! 🤍', 101, 21, 'GOOD', SYSTIMESTAMP);
