INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '홍대 카페 중 널찍하게 이용할 수 있는/어느정도 작업 가능한 곳을 찾고 있었는데, 공명이 좋아보여서 와봤어요~ 시그니쳐 라떼가 특이해서 마음에 드네요 🥰', 6, 10, 'GOOD', SYSTIMESTAMP);
