INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '메뉴판이 신기해서 놀랐던 연남동 카페 공명 ! 시그니처 라떼 너무 맛있어요 🫶🏻🫶🏻 디저트류도 엄청 다양한데 비주얼도 미쳐버림 🤤🤤 충전기 꽂을 곳도 많아서 자리 눈치싸움 안 해도 됨 ! 👍🏻👍🏻', 38, 3, 'GOOD', SYSTIMESTAMP);
