INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '연남동 카페에서 생크림 스콘먹으러 옵니드 꼭 옵니다 드셔보셔요!!!진짜 맛있습니다 음료도 뭐 그냥 드시고 싶은거 다 드셔도 맛있어요!', 29, 5, 'GOOD', SYSTIMESTAMP);
