INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '주말에는 사람 많지만 매장 자리 많으니까 자리 바로 잡을 수 있는 점이 너무 좋아요. 다만 좀 시끄러울 수도 있습니다… 근데 아마 다 거의 비슷합니다! 초코나무숲 스콘을 시켰는데 너무 달지 않고 맛있어요! 아이스 아메리카노 같이 먹으면 찰떡궁합인 디저트입니당~ 음료 종료도 많은데 디저트 안 먹으면 커피 하나 시켜도 될 것 같네요… 근데 디저트 비주얼 보고 안 먹을 수가 없어요!!! 다음에 홍대에 오면 다른 디저트도 먹어보고 싶네요.', 41, 6, NULL, SYSTIMESTAMP);
