INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '연남동 카페 찾다가 디저트가 제일 맛나보이고 특색있어보여서 왔어요! 메뉴 다 너무 맛있고 분위기 너무 좋습니당!! 홍대 카페 찾고있다면 강추해용', 5, 10, 'GOOD', SYSTIMESTAMP);
