INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '디저트도 맛있고 커피도 맛있기 어려운데, 그걸 둘 다 해내면서 노트북 하기도 좋은 이런 곳.. 너무 소중해요ㅠ 가끔 디저트만 배달로 시켜먹을만큼 jmt 인 곳입니다', 13, 9, 'GOOD', SYSTIMESTAMP);
