INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '사람이 정말 많고 넓어요. 떠들어도 주변이 소란스러워서 괜찮아요 ㅎㅎ 디카페인으로만 먹었는데 카페라떼 무난무난 맛있어요. 공명커피도 시나몬향 은은하게 나서 괜찮네요 무난한 커피맛!', 28, 10, 'GOOD', SYSTIMESTAMP);
