INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '연남동 카페 알아보다가 분위기 아늑해보이고 시그니처 라떼가 있어서 방문해봤는데 생각보다 엄청 넓어서 놀랐습니다..!! 그리고 베이커리 종류가 많고 깔끔하게 쇼케이스가 꽉 차있어서 보는 것 많으로도 기분이 좋았어요. 공명라떼는 큰 기대없이 시켰는데 첫 인상은 크림이 달다 그리고 시나몬이 톡톡하다 였는데, 밑에 라떼가 굉장히 부드러워서 생각 이상으로 같이 간 일행도 그렇고 음료 자체에 만족했습니다. 추천드려요~!!🩷', 7, 4, 'GOOD', SYSTIMESTAMP);
