INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '커피,음료가 다 맛있고 특히 디저트 맛집이에요! 카페 갈 때 디저트 중요시 하는데 종류도 다양하게 골라 먹을 수 있어서 좋아요✨✨', 1, 4, 'GOOD', SYSTIMESTAMP);
