INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '공간도 넓고 카페음료도 맛있고 이야기나누기에도 좋고 노트북 작업하기에도 좋은 공간리에요! 홍대 특히 연남동 근처에 이렇게 큰 대형 카페가 없어서 자주 오게됩니다!!', 32, 2, 'GOOD', SYSTIMESTAMP);
