INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '주말 점심때쯤 오니까 사람이 많이 없어서 바로 입장했어요! 홍대카페중 가장 분위기 있고 멋있는 곳이에요😃 베이커리 종류도 다양해요 올때마다 사람 많아서 자리를 못잡아 아쉬웠지만 이렇게 또 일찍 오니 조용하고 좋은 것 같습니다:)', 35, 10, 'GOOD', SYSTIMESTAMP);
