INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '공명카페 커피가 맛있어요 디저트도 다 맛있고 분위기도 고급져요 이 건물 일하러 가끔오는데 올때마다 여기 커피먹는게 루틴이에요 감사합니다', 4, 5, 'GOOD', SYSTIMESTAMP);
