INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '공명 연남점~~ 매장이 넓직하고 인테리어가 감각적이예요.. 1인이 이용해도 좋고 친구들과 모이기위해 약속장소로 이용해도 좋은것같아요~~  특히 공명라떼 맛있어요~~~ 재방문의사 있어요~~', 47, 8, 'GOOD', SYSTIMESTAMP);
