INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '친구랑 오랜만에 홍대에 놀러왔는데 우연히 길가다 발견한 카페라 큰 기대 없이 들어왔어요 근데 음료도 맛있고, 가게 인테리어도 너무 좋아서 친구랑 오길 잘했다고 만족중이에요ㅎㅎ 홍대 카페 찾으시는 분들은 오셔도 좋을 것 같아요!', 49, 2, 'GOOD', SYSTIMESTAMP);
