INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '연남동 카페를 찾다가 이전에 와보고 싶었던 곳이라 방문하게 되었습니다. 스콘이 고소하고 우유크림이 산뜻해 조화가 좋네요~ 추천합니다!', 32, 5, 'GOOD', SYSTIMESTAMP);
