INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '홍대카페추천에 제일 많은 카페여서 와봤는데 음료도 너무 맛있고 디저트 종류도 엄청 많아요!! 좌석도 다양하게 많고 의자가 편해 홍대에서 놀다가 다리아플때 오래 쉬기에도 좋은것같아요! 연남동카페 엄청 많은데 저는 연남동쪽 오면 공명 또 방문할거같아여😆 멤버십포인트 적립이나 선물용 기프티콘도 판매중이여서 단골할거같아뎌!!', 4, 1, 'GOOD', SYSTIMESTAMP);
