INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '벌써 세 번째 방문!!!! 비스킷슈가 시그니처 꼭 드셔야해요! 커피는 연남과 홍대 두 개 각각 넘 다른 매력이 있어요! 비스킷슈는 꼭 드세요!', 10, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '주말이라 그런지 만석인데 웨이팅 시스템이 있어서 2인석에 자리 못맡고 다른 3인석 테이블 지정 받았어요. 키오스크로 이용 안내가 잘 보이면 좋겠어요 자몽, 레몬에이드에 과일 많이 담아줘서 비주얼이 더 좋고 시그니처 라떼도 괜찮아요', 13, 9, 'GOOD', SYSTIMESTAMP);
