INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '6명 정도 독서모임 할 홍대카페(연남동카페)를 추천받고 방문했었는데, 그 당시에는 사람이 꽉 차 있어서 못 왔다가 오늘 드디어 와봤습니다!! 방문 전에는 그냥 넓고 조용한 카페인줄만 알았는데 베이커리 종류 너무 많아서 눈 돌아갈뻔 했고,, 공부하기 좋은 자리랑 대화하기 좋은 자리랑 단체모임하기 좋은 자리로 구획이 잘 나뉘어져있어서 좋았습니다. 홍대입구역에서 가까운 카페 중에 이정도로 쾌적한 대형카페는 없는 것 같아요. 아 메뉴가 책으로 되어있는 것도 너무 신박했습니다.ㅋㅋㅋ', 44, 4, 'GOOD', SYSTIMESTAMP);
