INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '바리스타픽 공명밀크티랑 시그니처 메뉴인 공명 라떼 주문했고 생크림 스콘이랑 같이 먹었습니다 생크림이랑 먹는 스콘은 새로웠는데 생각보다 크림이 맛있고 잘 어울려서 되게 잘 먹었어요 공명 라떼는 시나몬 맛이 나는데 전에 코젤 가게에서 먹은 맥주 처럼 컵 표면에 시나몬 설탕같은게 발려있어서 식감과 맛에 새로움을 주었고 역시 크림이 묵직해서 맛있었어요! 밀크티도 향긋하고 맛있네요 매장이 커서 사람이 많은데도 답답한 느낌은 덜했습니다 추천합니다 :)', 8, 9, 'GOOD', SYSTIMESTAMP);
