INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '라떼가 왜 대표메뉴인지 알겠어요.. 라떼 별로 안 좋아하는데도 맛있었어요ㅠㅠㅠ 그리고 베리믹스 에이드능 그냥 블루베리 그자체.. 상콤하고 달콤하고 커피 안 드시는분들 꼭 드세요!!!!! 빵도 추천!!!!!!!', 42, 1, 'GOOD', SYSTIMESTAMP);
