INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '여기 디저트가 진짜 뚱뚱하고 풍성해서 맛있어요. 종류도 다양하고 원두도 선택할 수 있어서 취향껏 먹을 수 있어서 누구에게나 만족스러운 선택이 될 것 같아요! 또 올게요!', 79, 11, 'GOOD', SYSTIMESTAMP);
