INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '홍대 카페 검색해서 왔는데, 너무 쾌적하니 좋네요! 디저트 종류도 많고 자리도 넓직하니 많아서 미팅 장소로 잘 이용했어요! 연남동 카페 강추합니다', 20, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '친구가 케이크 맛집이라고 해서 와봤어요 카페도 넓고 음료도 케이크도 맛있어요 밀크티 추천이라해서 먹었는데 향도 진하고 맛있네요 엄청 단 느낌이 아니라 굳굳 왜 추천메뉴인지 알것 같아요', 53, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '샤인머스켓 에이드, 피스타치오 카페 라떼, 공명 라떼 모두 맛있어요 디저트는 우유생크림 스콘이랑 말차 까눌레 먹었는데 모두 성공적이네요 ㅎㅎ 분위기도 좋구 아주 만족합니다!!!', 95, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '연남공명카페 다녀왔습니다. 공간이 넓고 쾌적해서 친구랑 여유롭게 이야기 나누기 정말 좋았어요. 음료는 전반적으로 밸런스가 좋고 맛도 깔끔했습니다. 직원분도 친절하고 응대가 빠른 편이어서 기분 좋게 머무를 수 있었어요. 햇살 잘 드는 창가 자리에서 여유롭게 시간을 보내기 딱 좋은 곳입니다. 재방문 의사 충분히 있어요. 다음엔 다른 메뉴도 마셔보고 싶네요.', 117, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '말차..진짜 넘 존맛.. 초코랑 말차의 조합이라나 진짜 넘 핼복하고 개맛릿어요 ㅠㅠㅠㅠㅠ 매장도 쾌적하고 좋네영 ㅎㅎㅎ 인기많은 이우를 알겟어용', 4, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '좌석이 편한 장소를 찾다가 왔는데 사람들이 많아서 이야기 소리가 잘 안들리는 경향이 있긴하지만 디저트도 음료도 너무 맛있고 분위기가 좋아요..! 다음에 와서 다른 디저트도 먹어보고싶네요. 책으로 메뉴판을 표현한게 너무 아이디어가 좋았습니다!', 40, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '연남동 공먕 다녀왔어요! 혼자 카공하려고 갔는데 자리도 널찍하고 조용해서 집중하기 딱 좋았어요. 진짜 좋았던 건 디저트… 초코나무 숲이라는 크림빵 먹었는데, 초코가 꾸덕~하게 들어있고 빵은 폭신해서 완전 제 스타일. 대전 본점 디저트라던데, 괜히 유명한 게 아니더라고요! 쿠키도 하나 같이 시켰는데, 겉바속쫀 그 자체… 커피랑 찰떡이었어요. 전체적으로 분위기 차분하고 사람들 다 조용히 있어서 혼자 공부하러 가기 너무 좋은 곳이었어요. 다음엔 친구랑 같이 와도 좋을 것 같아요🍪🌳', 19, 10, 'GOOD', SYSTIMESTAMP);
