INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '연남동의 빛.... 디저트 진짜 맛있고(크림 들어가는것들 진짜 강추), 음료 맛있고, 매장 넓고 정갈한 분위기인데 좌석도 다양해서 편하게 오기 진짜 좋아요... 연남동에 몇없는 혼자랑 다인원 다 커버되고 맛있는 카페 제발 영원하길', 29, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '친구 추천으로 방문해봤는데 매장이 커서 좋고 메뉴판도 책으로 되어있어서 멋있고 빵 종류도 많고 메뉴들도 트렌드하고 너무 맛있어요..♡ #연남동카페 #홍대카페', 9, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '연남동 카페 중에서 매장 넓고 좌석끼리 적당히 잘 띄워져있어서 대화하기 좋은 것 같아요! 디저트도 다양해서 좋습니당 맛있어용💓', 37, 10, 'GOOD', SYSTIMESTAMP);
