INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '커피는 깊고 부드러운 맛이 나서 만족스러웠고, 디저트는도 너무 맛있어요. 연남동 디저트 맛집으로도 충분히 손꼽힐 만큼 정성 가득한 맛이었어요. 연남동 데이트 코스나 혼자 힐링하기 좋은 장소 찾고 있다면 꼭 한 번 들러보세요. 감성적인 분위기, 맛있는 커피, 아늑한 공간까지 삼박자 고루 갖춘 연남동 카페였답니다! #연남동카페 #연남동데이트 #감성카페 #서울카페투어 #카페추천', 103, 22, 'GOOD', SYSTIMESTAMP);
