INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '공명라떼 크림이 진하고 쫀쫀해요! 라떼도 진한 편이고 초코나무숲 스콘은 정말 특색이 있네요 크림이 맛있어서 다음에 다른 크림 들어간 디저트를 먹어보고 싶어요 홍대 카페 중에서 이렇게 편하게 앉을 수 있는 규모의 카페가 있다는 게 넘나 행복합니당', 48, 1, 'GOOD', SYSTIMESTAMP);
