INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '연남동카페 공명 연남점 분위기 너무 좋아요💕 카공하기 좋은 넓은 카페에 독서하는 분들도 많았어요! 스콘 종류도 다양하고 큼직하더라구요!! 공명라떼 크림 달달하고 넘 맛있어용💗💗', 105, 19, 'GOOD', SYSTIMESTAMP);
