INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '공명크림라떼는 항상 먹을때마다 맛있어요. 공명 스콘을 특히 맛있게 먹고 좋아라하는데 오늘은 쑥쑥케이크를 선택했네요. 요즘 케이크 가격이 많이 올랐는데 크기나 맛이 같이 올라가지는 않아서 속상할때가 종종 있어요. 그럼에도 항상 만족하면서 방문하는 공명입니다~', 17, 7, NULL, SYSTIMESTAMP);
