INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '#연남동카페 #홍대카페 커피도 디저트도 맛있다는 카페 공명 명성답게 다양한 디저트들이 있어서 고심끝에 디저트 세개 골랐어요 커피도 시그니처 메뉴부터 다양합니다 메뉴판이 책이어서 신기했어요:-) 홍대 연남 오시면 방문 추천', 35, 0, 'GOOD', SYSTIMESTAMP);
