INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '연남동 카페, 홍대 카페 오고싶으면 무조건 1순위로 고려할 곳 입니다! 배달로 초코나무 스콘, 🥐🥐🍫고구마 스콘만 🍠시켜먹었는데 이렇게 이쁘고 아늑한 카페 있는 줄 알았으면 직접 들릴걸 그랬어요ㅠ☺️ 내부도 넓고 편한 좌석이라서 남자친구도 다음에 또 오자고하네용🥺', 30, 9, 'GOOD', SYSTIMESTAMP);
