INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '작업하기도 좋고, 넓어서 자리 걱정 없는 홍대 카페는 공명이 유일한 것 같아요.. 근데다가 스콘도 맛있고, 올때마다 스콘 맛 다양하게 먹는데 다 맛있더라고요 ♥ 다음에 또 올게요', 57, 13, 'GOOD', SYSTIMESTAMP);
