INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 연남점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '연남동 카페중에 카페 공명이 유명하다고 해서 친구랑 방문했어요! 항상 지나가다 사람많길래 궁금했던 곳인데 자리도 넓고 테이블도 많고 다양한 테이블로 공간이 나눠져있어서 원하는 자리에 앉을 수 있어서 좋아요! 평일 오전에 왔더니 자리 많아요!☺️', 10, 3, 'GOOD', SYSTIMESTAMP);
