INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '🩵🐻 더 그릭베어 홍대상수점 🐻🩵 애플 피넛버터청크 보울, 요거트는 꾸덕이로 선택하였습니다. 쪽뜩하고 꾸덕한 그릭요거트가 크림치즈처럼 고소하고 담백해요~! 아침 식사 대용으로도 좋은 사과와 피넛버터가 들어가 있어서 건강하게 먹을 수 있습니다~! 더불어 여름시즌 메뉴 100%수박 주스 수박만으로도 시원하게 더위를 물리쳐줍니다~!🍉🩵👍🏻', 33, 2, NULL, SYSTIMESTAMP);
