INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '이전하기전부터 가고싶었는데 이전하고 드디어방문했어요!! 인테리어도 아기자기하니 너무 귀엽고 보울의 요거트+싱싱한 재료는 맛없을수없는 조합이였습니다‼️‼️ 배달시켜 먹기에도 좋고 포장하기도좋고 건강하게 먹고싶을때 먹어야겠어요 상수 카페 더그릭베어🐻요거트보울뿐만아니라 음료도 너무 맛있어서 자주가야겟어요', 34, 4, 'GOOD', SYSTIMESTAMP);
