INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '더그릭베어 매장이 더 예뻐졌네용 오랜만에 왔더니, 근처로 옮겨져 있어요 😆😊 신메뉴 수박 트로피칼 보울, 리얼 수박 주스 주문했는데.. 건강하고 맛있는 맛에 좋았어요~ 커피 맛집이기도 해서.. 라테 주문했는데, 고소하게 맛있어서 만족했어요 😊', 45, 1, 'GOOD', SYSTIMESTAMP);
