INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '💰 가격: 딸기 오레오청크 보울(8,900) 그릭요거트+딸기+청포도+오레오청크+코코넛청크+초코그래놀라+딸기잼, 그릭요거트 선택 꾸덕이 😋 맛: 쫀득쫀득한 그릭요거트와 새콤한 과일의 조합의 건강한 맛, 달달한 오레오,코코넛 청크와 초코그래놀라는 아삭하면서 고소한 맛 연출 📋 총평: 메뉴가 고민된다면, 구성된 조합메뉴 중에서 골라보자! 실패는 없을 것으로 예상됨', 76, 16, NULL, SYSTIMESTAMP);
