INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '꾸덕~ 하고 새콤한 요거트와 신선한 토핑이 잘 어우러집니다. 처음 받고선 양이 적은거 아냐? 라고 생각했는데 꾸덕한데다 높게 쌓여서 그래보였을 뿐, 양도 꽤 되더라구요.', 37, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '#협찬 뷰맛집이네요 요거트 맛보고 고를 수 있는 부분도 처음 알았어요! 감사합니당~~ 외국분들도 많이 오셔서 신기했어요 다음엔 매장에서 먹어야겠네요!!', 12, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '맛있어용 ㅎㅎ 치즈의 고소한 맛이 나는것 같은 크리미 그릭요거트! 갠적으로 시럽(시나몬) 은 안넣어도 당이 충분해사 담엔 빼고 먹어보려구요!', 26, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '베이글에 그릭요거트 조합이라니..! 크림치즈같은 그릭요거트가 나오는데 정~말 맛있어요. 건강해지는 느낌! 내부가 좀 특이하네요. 네명오긴 좀 그렇고 둘이서 앉기엔 좋은 곳 같아요. 베이글을 계속 시켜먹었네요. 겉바속촉🩷', 1, 7, 'GOOD', SYSTIMESTAMP);
