INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '약간의 메뉴 실수가 좀 있음. 3번 방문했는데 한번은 주문한 재료가 안들어가있고 한번은 그릭요거트 종류가 다르게 나옴.. 그냥 먹긴했는데 주문서 좀 잘 보고 조리해주면 좋겠음', 50, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '퍽퍽꾸덕은 별로 안 좋아해서 골든크리미로 시켰어요 신맛 아주 조금 나고 크림치즈같은 고소한 향이 강하게 나요. 적당히 꾸덕하고 맛있어요', 35, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '간단히 혼자 먹으려고 들렷는데 요거트 진짜 넘 맛있어요! 2층에 먹고갈 공간도 있구요 ㅎㅎ 직원분들도 친절하세용 다음엔 다른맛으로도 먹어보랴구요', 23, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '그릭요거트 좋아하는 분이라면 여기 두번 세번 가세요~! 양도 푸짐하고 그릭요거트도 꾸덕하니 완전 맛잇엇어요!! 바질베이글도 너무 괜찮더라구요💙 너무 만족스러워서 그래놀라도 추가로 구입해왓어요!!! 요거트 사러가야지ㅎㅋ', 19, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '저녁밥 대신으로 그릭요거트 시켜서 먹었습니다 부드러움과 꾸덕함 정도도 정할 수 있어서 저는 꾸덕한 그릭요거트로 시켰어요 초코토핑과 과일토핑이 있는데 개인적으로는 과일토핑이 더 맛있었습니다 수박주스는 평범하고 베이글도 바삭하게 구워줘서 크림치즈 발라먹으니 든든하네요 간식으로도 괜찮을거 같고 밥 대용으로 먹어도 생각보다 든든해서 괜찮을 것 같습니다 기본적으로 그릭요거트가 신맛이 조금 있지만 신거 싫어하시는 분들도 한번쯤 도전해볼만한 맛이에여', 16, 4, 'GOOD', SYSTIMESTAMP);
