INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '그릭요거트 식감이 먹기 딱 좋았어요. 복숭아 토핑은 약간 딱딱한 황도였어요. 복숭아가 제가 생각한 것과  조금 달라서(말캉하고 달달한 🍑) 아쉬웠지만 요거트 보울 자체는 조합도 양도 괜찮았어요!', 15, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '여기 동네가 처음이고 여행 왔다가 숙소근처에 그릭요거트 전문점이있길래 방문했습니다. 주문하는데 사람 때문에 기분이 나쁜적은 처음이네요 그릭요거트는 정말 맛있었고 직원들도 친절했어요 리뷰 안쓰려다가 자주 오시는분인지 보시고 인성똑바로 사시라고 남깁니다. 키오스키 한대있었고 일요일 오후 8시 한가할때 방문했습니다 매장에 아무도 없었고 키오스키보면서 고민하고 있는데 5분정도 넘게 있다가 선택상항이 많아서 누르고 주문하고있었습니다. 근데 저도 사람인지라 뒤통수가 따가워서 결제 끝나고 돌아보니 어떤 여자분이 노려보고계시더라구요? 솔직히 기분나빠서 뭐라하려다가 참았는데 주문하는데 1시간이 걸린것도 아니고 개념밥말아 처먹었나 왜 노려보는지 ; 동네수준떨어트리지마시고 개념챙기고 사세요', 11, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '친구들이랑 놀러갔는데 각자 취향에 맞게 커스텀해 먹을 수 있던게 좋았어요 신맛없는 촉촉한 그릭요거트라니!! 정말 제 입맛을 저격했습니다 친구들도 동의하면서 디카페 아메리카노도 비싸지않아 좋았구 직원분들도 친절하셔서 넘 좋았습니당♡♡♡', 66, 14, 'GOOD', SYSTIMESTAMP);
