INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '홍대 올때마다 포장하는데 너무 맛있어요 가격대비 양도 적절하고 요거트에서 적당히 신맛이 나요! 꾸덕한식감 좋아해서 꾸덕이로 주문했는데 완전 꾸덕해요! 과일도 신선하고 그래놀라도 맛있습니다~ 다이어트하거나 간단한 한끼 식사로 좋은거같아요➰💗', 30, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '요거트 정기배송 시켜먹는 요거트에 미친 자로써 감히 말씀드리자면 완전 꾸덕포슬포슬하고 산미도 없고 넘 맛도리에요💙💙💙💙 요거트 집인데 커피도 넘 맛있어요😄😄 2층에 먹고갈 수 있는 좌석도 있고 인테리어도 깔끔하고 넘 예쁘네요💕 조용한 분위기여서 혼자 머무르기 좋아요~', 47, 3, 'GOOD', SYSTIMESTAMP);
