INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '상수역 2번 출구 바로 앞이라 방문하기 좋았어요!! 화이트&블루로 귀여운 인테리어에 그릭요거트와 바질 베이글 등 건강한 맛의 음식도 아주 만족스러었습니다ㅎㅎ 콘센트가 여러개 있어서 노트북 하기에도 좋았어용!!^^', 10, 3, 'GOOD', SYSTIMESTAMP);
