INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '그릭요거트 너무너무 맛있어요!! 토핑도 다양하게 추가할 수 있고 요거트 젤라또도 너무 맛있어용 매일매일 먹고 싶은 맛이에요 상수역 바로 앞에 있어서 접근성도 좋고 자주 방문할 거 같아요!! 곰돌이도 귀엽네용😍', 14, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '홍대상수 그릭요거트 맛집이라해서 방문했어요! 토핑종류도 많아서 다양하게 고를 수 있고 재료들도 다 신선했어요! 그릭요거트도 꾸덕하고 취향저격!', 81, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '그릭요거트 토핑도 다양하고 커피도 너무 맛있었어요! 매장도 깔끔하고 귀여워요🩵 앞으로 자주 방문할 것 같아야, 직원 분들도 되게 성실하신(?) 것 같아서 좋았습니당 ㅎㅎ', 27, 10, 'GOOD', SYSTIMESTAMP);
