INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '다이어트 시작해서 한 끼라도 클린하게 먹으려고 방문했어요! 그릭요거트 라지로 변경하니까 완전 배뻥하게 먹을 수 있더라고요. 과일이 새콤달콤하고 맛있어서 개인적으로 과일토핑 강추 드립니당 💛💚 매장까지 예뻐서 힐링이에요 ㅎ 화장실도 안에 있네요.', 39, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '상수역 바로 앞에 있는 더그릭베어 요거트집이에여! 1층에서 주문하고 2층 가있으면 직접 가져다주시는데 2층이 채광도 좋고 깔끔해서 짱좋아요 요거트 말고도 커피, 스무디, 차 종류도 있는데 아직 사람들이 잘 모르나봐요 2층에는 잘 안올라오는데 한가하고 여유로워서 아는사람만 아는 분위기맛집이에요 🤍 특히 코코넛청크가 짱맛이에용', 3, 8, NULL, SYSTIMESTAMP);
