INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '사장님께서 넘 친절하셔서 정말 좋았어요! 맛보기 스푼도 주시고 네이버 이벤트 안내도 친절히 해주시고 서비스로 꿀도 주셨어요. 정말 감사합니다 얼그레이 그래놀라 정말 맛있어요! 다만 요거트와 먹으니 얼그레이 향은 좀 약했어요. 키위가 싱싱하고 달달하니 좋았어요! 꾸덕이로 시켰는데 과일과의 조화가 정말 좋은거같아요. 넘 맛있어요! 개인적으로 촉촉이는 그래놀라, 꾸덕이는 생과일이 참 잘어울리는것 같아요! 그리고 올리브 베이글 짱 맛있음 제가 올리브 좋아해서 더 맛있는거 같아요! 스팀토스트기? 로 굽는다고 본것 같은데 그래서 그런지 부드러워서 씹기 좋았어요!! 넘 만족스러워요. 2층 쾌적하고 햇볕이 잘들어요! 넘 추워서 충동적으로 들어온건데 아주 따스하고 행복한 시간이 되었어요!', 33, 1, 'GOOD', SYSTIMESTAMP);
