INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '상수역 바로 앞에 위치해있는것도 너무 마음에 들고! 그래놀라 맛 종류 많은것도 너무 마음에 들어요! 심지어 다이어터에게 너무 좋은 ㅎㅎㅎ다크초코로 구매했는데 한자리에서 다 먹은게 소름돋고 계속 생각날정도로 너무너무 맛있는 맛이였어요!! 요거트도 엄청 꾸덕하고 좋아용 ㅎㅎㅎㅎ분위기도 좋고 그냥 너무너무 추천하는 곳이에요!', 12, 2, NULL, SYSTIMESTAMP);
