INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '더그릭베어 상수점! 인테리어도 너무 예쁘고 카페에서 쉬다가기 딱 좋은곳인것 같아요 그릭요거트도 어찌나 맛있던지 냠냠 먹고 계속 생각났답니다 또 방문 예정!! 그래놀라도 너무 맛잇어요', 31, 5, 'GOOD', SYSTIMESTAMP);
