INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '그릭요거트가 2종류 있어서 넘 좋았어요 >< 꾸덕한맛이랑 부드러운 맛 중에 좋아하는 걸로 조합해서 먹기 좋고, 인테리어도 너무 귀여워용💓', 20, 1, NULL, SYSTIMESTAMP);
