INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '☆ 피치무화과 보울 ☆ 피치 무화과 보울은 건무화과의 단단한 표면 안 자글자글 달콤함이 통통 튀는 듯한 식감이 참 좋습니다. 백도 복숭아가 지나치게 단단하거나 무르지 않아서 편안하게 넘어가서 만족스럽습니다. - 이름은 ''꾸덕이''라서 뭉텅이로 한방에 푹 퍼올릴 수 있을 것 같지만 막상 숟가락으로 휙휙 저어보면 포슬포슬하게 자잘자잘 덩어리 생기면서 뭉치는 질감입니다. 이 꾸덕이가 중독성 있어서 방문을 부르는 매력이 있습니다. 아메리카노는 약간 신맛이 있어서 요거트와 잘 어울렸습니다. - 생크림 같은 크리미와 발효된 치즈 같은 꾸덕이 중 커스텀할 수 있고, 매장에서 먹으면 일하시는 분이 가져다 주는 시스템입니다.', 3, 4, 'GOOD', SYSTIMESTAMP);
