INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '항상 믿고 먹는 더그릭! 오늘도 기대만땅하고 왔는데 첫 입 베어물고 넘 맛있어서 나자빠질뻔 했어요 ㅋㅋ 다만 평소보다 토핑양이 요거트 양에 비해 적게 느껴져서 아쉬웠지만 (저넉식사대용이었어서 ㅠ)  대체적으로 만족스러운 방문이었습니다!! 보니 이제 그래놀라도 저렇게 패키지로 판매하던데 담번엔 저런 제품들도 함 사볼까봐요 ㅎ', 119, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '알바인지 사장인지 응대가 너무 별로에요. 급해서 미리 주문해놓으려고 전화했더니 와서 키오스크라고 주문하라 함. 전화주문은 안 받으시냐하니까 짜증난 목소리로 뭐 주문할꺼냐고 물어봄. 메뉴 이름 긴거 여러개 줄줄 다 말하니까 다 듣고도 여전히 와서 키오스크로 주문하라고 함. 그럴꺼면 애초에 왜 물어본지도 모르겠고 매우 불친절했음. 매장에 가보니 사람이 많은 것도 아니고 충분히 전화로 주문받을 수 있는 상황인데 이해가 안 됨. 응대가 별로여서 그런지 전혀 맛있게 먹지도 않았거 주문시간+음식 나오는 시간 다 해서 계속 기다리느라 결국 버스 놓침. 다신 방문 할 예정 없음.', 53, 14, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '요거트 종류는 꾸덕한 거랑 (꾸덕을 넘어서 포슬포슬해요) 부드럽고 크리미한 거 둘 중에 선택할 수 있고 토핑도 다양합니다! 2층에 먹고갈 수 있는 장소도 따로 있어서 좋아요 혼밥하기 완전 좋아용', 17, 0, 'GOOD', SYSTIMESTAMP);
