INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '솔직히 아직 먹지않아서 맛 리뷰는 못하겠고, 맞은편 스벅에서 뭘 적다가 9시(21시)마감이라 나오게ㅡ되면서 10시까지라는 말에 포장주문을 하고, 테이블을 이용하게 되었다. 키오스크 주문이 기본이고, 다양한 토핑이나 커스터마이징이 가능하다. 내 경우 이것저것 토핑 추가하니 9,900원이 나왔음요 ㅋㅋ 1층에 주방이 있고, 2층에 테이블이 있어 편하게 할거 하셔도 될듯요~', 18, 8, NULL, SYSTIMESTAMP);
