INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '네이버보고 너무 맛있어보여서 찾아갔는데 복숭아 자두 보울시켰는데 사진과 복숭아 색깔이 달라서 너무 속상했어요…저 복숭아가 더 달아서 그렇다고 말씀하셨지만 미리 사전고지없이 네이버보고 온 손님입장으로선 대처가 너무 아쉽네요. 사진속 그릇도 다르고 양도 적고 가격대비 아쉬웠습니다🥲', 3, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '직원분들도 너무 친절하고 매장도 너무 깨끗하고 예쁘고 그릭요거트도 너무 맛있어요 ㅜㅜ 과일도 너무 신선하고 토핑들도 다 넘 맛있어서 오늘 처음 와봤지만 조만간 단골이 될 것 같은 예감이 ㅎㅎ 비오는 날 창밖의 뷰도 즐기면서 정말 맛있고 행복한 식사 했습니다!!', 59, 15, 'GOOD', SYSTIMESTAMP);
