INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '캬라멜쿠키랑 시나몬 그래놀라 샀어요! 캬라멜쿠키 생각보다 거의 안달아서 부담없이 먹기 좋아용 그래놀라는 여기가 제일 맛있는듯..', 82, 13, 'GOOD', SYSTIMESTAMP);
