INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '약속 시간이 남아서 잠시 업무 보러 들어왔는데 음료가 딱 딸끔하게 맛있었구 다음엔 제대로 요거트 먹으러 와야겠어요! 직원분들 친절하신데 1층에서 2층으로 다져다 주시느라 계속 왔다갔다 하시던데,,,👍', 49, 6, 'GOOD', SYSTIMESTAMP);
