INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '항상 올때마다 매장 분위기도 너무 좋고 청결해서 힐링되요! 오늘은 커스터마이징 먹었는데 다음번엔 토핑을 좀 더 넉넉하게 해야겠어요! 꾸덕꾸덕이 거의 크림치즈 질감이어서 특이했는데 그래도 항상 맛있습니다 😊', 42, 3, 'GOOD', SYSTIMESTAMP);
