INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '다회 용기 가져가면 300원 할인되니 포장할 사람은 꼭 챙길 것!! 얼그레이 그래놀라 맛있다. 골든 크리미랑 하얀 꾸덕이 중에 개인적으로는 담백한 골든 크리미가 더 좋았음! 2층에서 식사하면서 잠시 쉬어가기 좋은 듯.', 7, 5, 'GOOD', SYSTIMESTAMP);
