INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '요 근처에 그릭요거트 파는 곳이 없어서 배달만 시켜봤는게 앞으로는 여기로 와야겠어요! 바나나 사과 시나몬 들어간거였는데 은근 든든하고 맛있어요 원래 꾸덕한거 좋아하는데 크리미한걸로 시켜봤는데 넘 만족😋 담엔 꾸덕한거 다른 종류로 막어바야겠어요😆', 47, 0, 'GOOD', SYSTIMESTAMP);
