INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '스트로베리 치즈케잌 요거트 너무 맛있네요...! 그래놀라랑 아몬드 등등 재료가 가득 들어 있어요 🤍 자몽주스도 달달 청량 💕 매장이 아기자기하고 귀엽고 인테리어도 넘 예뻐요✨', 36, 7, 'GOOD', SYSTIMESTAMP);
