INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '☆ 스트로베리 치즈케익 보울 ☆ 공들여서 기획한 것이 느껴지는 곳입니다. 하늘색과 흰색 조합으로 산토리니를 연상시키는 인테리어도 그렇고, 그릭요거트 종류를 두 가지 중에서 선택할 수 있는 것도 인상적입니다. ''골든크리미''는 아이스크림 같이 질펀하고 부드러운 식감이고, ''하얀꾸덕이''는 수분 없이 푸슬푸슬 리코타치즈 같은 식감입니다. - 골든크리미로 <스트로베리 치즈케익 보울>을 먹었습니다. 생딸기가 자잘자잘하게 나와서 맛이 좀 묻히는 것 같아 아쉽긴 했지만 생각보다 튀는 재료 없이 맛있게 먹었습니다. - 매장 2층 넓은 공간에서 편하게 앉아서 먹고 갈 수 있고, 키오스크가 매장 안팎에 각각 있어서 주문도 편합니다. 상수역 2번출구 바로 앞에 있습니다. 인기가 많을 것 같아요.', 38, 9, 'GOOD', SYSTIMESTAMP);
