INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '두번째 방문입니다. 홍대에 놀러오게 되었는데 상수역 출구 바로 앞이라 일단 가까워서 좋고 빛도 잘 들고 무엇보다 꿀이 한 포씩 같이 나옵니다. 맛있어요! 여동생이 만족해해서 더 만족스러운 요거트였어요^^/', 22, 10, 'GOOD', SYSTIMESTAMP);
