INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '그릭 요거트 사러 자주 가는 단골집 맞은편 스벅에 사람 너무 많은데 같은 시각 한가해서 좋았음 창가 자리 좋구 화장실 깨끗해서 더 좋구. 다만 딸기요거트가 너무 적어서 아쉽 ㅠㅠ ㅋㅋ 그치만 그릭요거트 넘 맛나고 가격도 좋아서 자주 감🙂', 50, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '처음 먹어 보고 그냥 그릭 요거트네 했다가 이상하게 자꾸 생각 나는 맛ㅎㅎㅎ 집 앞이라 그릭 요거트에 그레놀라랑 꿀만 추가하고 집에 있는 과일 넣으면 진짜 맛있음!! 어제 두개 먹고 오늘은 큰 거로 사서 연달아 이틀째 먹는 중👍', 68, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '신선하고 건강하면서 이렇게 맛있는 디저트가 있다니ㅠㅠㅠ요거트 쳐돌이는 너무 행벅합니다~~특히 베스트 메뉴인 바나나치즈케이크는 꼭 드셔주십쇼,,그 조화가 너무 맛있어요', 35, 2, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '너무너무 맛있게 잘먹었습니다! 🦦 항상친절하시구..! 대용량도 맛있어서 사서 아침으로 자주먹어요! 이런곳이 가까이있어서 최고에요ㅎㅎ 사람들데리고 많이오겠습니다..!', 79, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '비싸지않고 한끼 간단하게 먹을정도의 양이라 좋았어요. 꾸덕하고 시지않고 그래놀라도 많아서 좋아요. 매장의자는 딱딱해서 조금 불편했어요.', 51, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '요거트 좋아하는데  상수역바로앞에 생김ㆍ심지어 가격착하고맛있음ㆍㆍ꾸덕이 맛있어서포장추가하고 ㅎ 재료신선 ♡♡친절은 서비스인듯 너무친절해서 기분까지 좋았음  내아지트로 찜♡♡', 45, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '집앞에 생겼는데 이제서야 와보네요! 운동 끝나고 가벼운 식사로 딱이예요. 음악도 사랑스러운 음악이 흘러 나오네요!! 망고 키위 시켰는데 망고는 조금 냉동 상태로 나와서 조금더 해동하고 나왔으면 좋았을 거 같아요. 미리 꾸덕이랑 크리미 맛 보게 해줘서 저의 취향을 확인해서 주문할 수 있었던 게 좋았어요. 언니분도 친절하셨어요!! 이것저것 제가 만들어 먹을 수 있고 아니면 선택할 수 있는 메뉴가 있어서 나중에 취향이 생기면 제가 바꿔서 먹을 거 같아요! 그릭요거트도 맛있었어요 저는 꾸덕이보다 크리미 🧁 간단히 가볍게 아침 식사 대용으로 좋은 거 같아요 ♥️', 42, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '저는 꾸덕한걸 좋아하는데 크리미한 곳밖에 없어서 아쉬워했는데 이런거까지 결정할수있는 곳을 찾았어요 맛도 좋고 건강하게 먹는 느낌!!! 다음에 또 오고 싶은 곳이에요 집갈때 또 포장해서 갈겁니다 ㅎ', 60, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '동네라서 종종 이용하는데~ 아이가 먹더니 오늘은 좀 가루맛이 나~ 하더라구요. 그래서 먹어봤더니 정말 오늘은 좀 다르네요. 뭔가 달라요. 먹는 질감이. 왜일까요?? 동네라서 자주 이용해서 후기 남겨봅니다.', 0, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '그릭요거트보울+ 아아세트하니까 할인 가성비 쵝고! 햇살 받으면서 혼자 작업하러 오기 좋아요👍🏻일단 그릭요거트 꾸덕이가 내 취향...  우유맛나서 고소하고 맛있음...🤤', 6, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'WIFI');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '그릭요거트 좋아해서 공사할때마다 오픈언제하나 목빠지게 기다렸는데 기대 이상입니다 ㅠㅠ🥹 누텔라볼 달달한게 미쳣구요...애플시나몬 과일도 엄청 푸짐하고 한끼 먹기 충분히 배불렀어요ㅎㅎ 담엔 테이크아웃해서 집에서 먹어보려구요 ! 직원들도 너무 친절합니다 ㅎㅎ 단골할께요😉', 66, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '전에 먹고 맛있어서 또 샀습니다 직원분들이 정말 친절하고 인테리어도 예뻐요!! 그릭요거트는 적당히 꾸덕해서 너무 좋아요 ㅜㅜ 그릭데이보다 부드러운 편이에요!', 34, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '저번에 먹어보고 맛있어서 또 포장해왔어요. 꾸덕이에 청포도랑 사과 커스텀하고 싸온 바나나랑 같이 먹었는데 맛없을 수가 없는 조합이었어요ㅠ 특히 따로 포장해주신 그래놀라 뿌려먹었는데 진짜 맛있었어요! 다음엔 매장에서 먹어보고 싶어요', 40, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '토요일 저녁에 방문했는데.. 남자 직원분 행동에 의문이 들어서 리뷰 남깁니다. 키오스크로 주문하고 요거트는 자리로 가져다 주셨는데요. 테이블 위에 물건이 있어서 놓을 자리가 부족하다면.. 그것을 치울때까진 기다려 주실 수 있지 않을까요? 구입한 새책을 읽으려고 두었는데 그 책위에 쟁반을 바로 올려두시더라구요. 저한테 어디둘까 물어보는 제스쳐를 취하신 것도 아니였구요.  손님이 들어오건 다 먹은쟁반을 올려두건 반응도 없으시고 인사도 없으시고.. 손님들의 소지품은 받침대가 아닙니다. 카페같은 공간을 방문하면서 이런 상식밖의 경험은 처음이라 남깁니다. 친절은 아니더라도 기본 개념적으로 일하게끔 교양은 시켜주셔야하지 않을까요. 다시 가고 싶지 않아요', 2, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '건강한 맛.. 식사 대용으로 좋은 것 같아요! 대체로 과일은 좀 순한맛이었어요 의자는 좀 불편해서 오래 있을만한 곳은 아니지만 인테리어가 예쁘고 볕이 잘 들어요! 음악 선곡도 좋고 친절해서 좋았어요', 9, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '상수역 2번출구 앞, 밖이 보이는 뷰의 그릭요거트 점입니다. 근처에 그릭요거트로 검색했는데 상수역 근처엔 이곳뿐인거 같아요. 키오스크로 주문할 때 다양한 변경사항 적용이 이해하기 쉽게 되어있어요. 저는 아몬드 대신 코코넛청크로 변경(추가요금없음)에 꾸덕이로 먹었습니다. 용량 변경이나 시럽을 아가베로 변경하거나 하는 것이 쉬워서 커스텀이 간편한거 같아요! 그릭요거트 맛은 크리미한 질감 보다는 좀 더 치즈처럼 부서지는 맛이고 신맛은 거의 느껴지지 않는 단단한 맛입니다. :) 저는 인터넷으로 그릭데이나 룩트 마마스레시피 오그릭 같은 다양한 그릭요거트 먹어봤는데 여기가 상급이라고 느껴지네요! 상수에서 간편하고 건강한 식사 찾으신다면 한 번 방문해 보세요.', 45, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '꾸덕이요거트만 포장해와서 그래놀라, 파인애플, 청포도, 바나나랑 같이 먹었는데 신맛이 거의 없어 진짜 맛있었어요! 회사 근처에는 가까운 그릭요거트 집이 없어서 배달비 내기 아까워 그릭요거트를 먹고 싶어도 못먹을 때가 많았는데 이제 자주 먹을 수 있을 것 같아서 너무 좋아요 :) 매장 직원분도 친절하게 응대해주셨고, 요거트 포장해주시는 내부 공간도 청결해보였어요. 자주 방문할게요!', 19, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '인테리어 대박,, 상수역 근처에 그릭요거트집이 없어서 항상 멀리까지갓엇는데 너무너무너무너무 행복해요 ㅠㅠㅠㅠ😻😻❤️❤️❤️ 인테리어도 진짜 너무 이쁘고 사장님 너무 착하십니다 요거트 진짜 대븍 맛있어요,, 오래오래 저 졸업할때까지 해주세요', 17, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '근처에 그릭요거트 가게가 생겨서 방문을 했는데, 그릭요거트를 먹어보지 않아서 직원분께 여쭈어보니, 작은 수저에 시식도 하게 해주시고 친절하게 직원분이 알려주셔서 덕분에 맛있게 먹었습니다!!:)👍🏻👍🏻 앞으로 자주 방문해서 먹어보겠습니다!😎', 35, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '커스텀도 다양하게 할수있고 무엇보다 양이 적당해서 좋아요! 가격도 정말 타사대비 저렴하구요! 꿀도 스틱으로 주셔서 깔끔하게 먹을수 있습니다 개인적으로 초코 토핑해서 먹는데 이거 너무 맛있어요! 사장님도 정말정말 친절하세요!', 18, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '2번째 그릭요거트👏🏻 역시나 제일 좋아하는 조합으로 서비스로 주신 것까지 너무맛있게 먹었습니다!!  앞으로도 계속 자주 이용해서 먹겠습니다 사장님 번창하세요!!😎', 90, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '꾸덕이 맛있고 그래놀라도 맛있어요!!! 상수에 맛있는 요거트 집 생겨서 넘 좋아유 담엔 크리미도 먹어볼거에요 자주 찾게될 것 같아요! 😀😀', 72, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '너무 만족스럽게 맛있게 먹었습니다! 일단 꾸덕이!!!!!!너무 좋고,,,그래놀라도 너무너무 맛있었습니다,,,최고최고,,,재방문의사 완전 있어효,,,🥹🤍', 63, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '요거트 평소에도 좋아하는데, 제철과일 자체가 우선 신선하고, 추가로 주는 꿀과 함께 먹으니 정말 아침마다 생각날거같네요ㅠㅠ 커피도 그냥 와우! 메뉴 다 도전할 예정!!', 34, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '크리미, 꾸덕이 둘다 먹어봤는데 크리미는 산미가 좀 있지만 먹을수록 땡기는 맛이고, 꾸덕이는 크림치즈 그자체 풍미가 미쳤어요😍 과일도 싱싱하고 너무 맛있어요 상수에 드디어 그릭요거트 맛집이생겼네요! 앞으로 그릭요거트 생각날때마다 올것같아요! 그리고 사장님도 너무친절하세용🥰🥰🥰', 68, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '무더운 여름의 한 일요일, 약속 장소인 상수역에 한시간 일찍 도착했다. 아침부터 스타벅스 그릭요거트가 땡겨서 출구로 나왔는데, 무심코 돌아본 곳에 있던 파란 곰돌이. 새로운 곳을 찾아다니는 걸 싫어하는 성격이지만 홀린 듯 횡단보도를 건너 주문했던 더그릭베어. 평소보다 먹고 싶어서였는 지는 몰라도 그렇게 감탄하면서 허겁지겁 먹은 그릭 요거트는 처음이다. 자리에 앉은 지 10분이나 되었을까. 빈 그릇 앞에 앉아있기 어색해서, 내려가서 딸기 그릭요거트 드링크를 하나 사왔다. 음료수도 훌륭하다. 맛집을 우연하게 처음 발견한 고독한 미식가의 기분이 이럴까.', 23, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '오레오 청크 보울은 정말 언제 먹어도 맛있습니다~ 이번엔 크리미 대신 꾸덕이 먹어보았는데 정말 꾸덕꾸덕하네요 ㅎㅎ 아메리카노도 고소하면서 깔끔하게 맛있어서 추천드려요~', 25, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '원래 그릭 요거트 별로 안좋아하는 사람인데, 여기 한번 가보고 마음이 바뀌었습니다. 더불어 커피까지도 맛있어서 계속 방문할 수 밖에 없을 것 같네요!', 18, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '우연히 발견해서 갔는데 가오픈이었네요! 요거트는 토핑 조합이 무난하고 추가가능해서 좋았어요 음료는 딸기청 같은게 너무 달았어요ㅠ 그래도 맛있고 친절하셔서 좋았어요~!', 7, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '그릭요거트 집에서 만들어 먹을정도로 너무 좋아하는데 여기는 다른곳보다 신맛도 덜하고 식감이 제가 딱 좋아하는 꾸덕!!!! 피넛버터랑 요거트랑 어울릴까 생각하고 시켜봤는데 진짜 짱맛있음', 7, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '상수역 바로앞에 그릭요거트집이 생겨서 방문했는데 넘 맛있네요👍🏻👍🏻요거크 종류가 2가지(부드러운것과 꾸덕인것)고 과일도 원하는걸로 선택가능해서 좋은거같아요 재방문의사 있습니다!', 122, 20, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '드디어 상수에 요거트 집이 .. 💟 먹고 갈수있는 공간도 있고 매장내 화장실도 있네요 좋아요 진짜 너무 .. 왜 이제야 생긴거죠 ,,ㅠㅠ', 45, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PLUG');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '첫 방문했어요! 그릭요거트 종류가 두 종류였는데 사장님이 너무너무 친절하게 알려주시고 맛보기도 할 수 있게 해주셔서 좋았어요 :) 요거트가 엄청 꾸덕하고 고소하네용 자주 갈 것 같아요☺️☺️', 49, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '최근에 학교 근처에 오픈해서 방문했는데 사장님께서 친절하시구 요거트 맛도 좋았습니다! 부드러운 질감이랑 꾸덕한 질감을 고를 수 있었고, 저는 꾸덕한 요거트 선택했는데 텁텁하지 않고 깔끔해서 종종 사먹기 좋은 것 같습니다~~', 31, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더그릭베어 홍대상수점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '가게 분위기가 너무 좋고 깔끔해요😉 직원분도 친절하시고요! 그리고 초코스무디가 정말 맛있어요ㅠㅠ 다음에는 그릭요거트도 먹으러 올게요 꼭 대박나세요!', 37, 0, 'GOOD', SYSTIMESTAMP);
