INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '매장이 어마어마하게 크고 종류도 많아요. 홀에 손님은 없지만 온라인주문을 많이 하나봐요. 저도 온라인으로 주문후 픽업해서 사진관에서 아이랑 촬영용으로 주문했답니다. 친절하고 조용한 베이커리카페예요~~', 2, 0, 'GOOD', SYSTIMESTAMP);
