INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '친구에게 축하 케이크를 선물하기 위해 예약을 알아보던 중 너무 귀여운 케이크를 보고 반해 바로 주문했어요! 실제로 받은 케이크도 너무 귀엽고 퀄리티도 좋더라구요~ 친구도 좋아했어요 ㅎㅎ 당일예약도 가능하다는 점이 큰 강점이네요 아 그리고 커피맛이 되게 좋더라구요 👍🏻 넘 제 스타일이었 ㅠㅠ', 118, 21, 'GOOD', SYSTIMESTAMP);
