INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '사진 찍을때 진짜 예쁘게 나오는 케이크입니다 넘 예뽀요!!!!👍👍👍 근데 가격대비 작고 안에 크림이랑 시트만 있어서 맛 측면에서는 좀 아쉬웠답니다..🥲', 34, 4, NULL, SYSTIMESTAMP);
