INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '남자친구한테 프로포즈용으로 주문했는데 실물이 너무 예쁘고 꽃도 파란색이라 세트같고 너무 예쁘더라구요 원하는 문구도 예쁜 글씨체로 넣어주셔서 더 분위기있는 선물이 된것같아요! 케이크 필요할때 또 재방문할게요💕', 17, 5, 'GOOD', SYSTIMESTAMP);
