INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '먹어보진 않아서 맛은 모르겠지만 날씨때문에 걱정되서 전화로 문의했을때 엄청 친절하셨고 종류 많고 요즘 추가금 진짜 많은데 추가금 없고 사이즈는 1호도 작긴한데 그건 내 선택이고... 합정점은 기본초 안줬는데 여긴 기본초도 주시고 이벤트 있을때마다 이용할듯해요', 116, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '이건 쫌 아니지 않나요...?! 선물하기 민망할 정도로 레터링이 하나도 안 보였어요.... 케이크도 울툴불퉁... 샘플 사진이랑 너무 다르고..... 만드신 분도 이건 아니라고 생각하셨을 거 같은데 너무 대충 만든 느낌이라서 실망했습니다.', 22, 5, 'BAD', SYSTIMESTAMP);
