INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '매장이 아기자기하고 귀여워서 문 열고 들어가면 다른 세상 온 것 같아요. 디저트들도 예쁘고 귀여워서 눈길이 가요. 저는 딸기생크림 케이크를 구매 했는데 사진과 똑같아요. 딸기 많이 들고 생크림이 부드러우면서도 많이 달지 않아서 친구들과 맛있게 먹었어요.', 1, 4, 'GOOD', SYSTIMESTAMP);
