INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '어버이날 기념으로 레터링 케이크 처음 예약해봤는데 글씨 예쁘게 써주셨어요! 부모님이 드시더니 먹어본 케이크 중 제일 맛있다고 하셨어요 ㅎㅎ 좋은 추억 쌓을 기회 만들어주셔서 감사합니당! 해피베어데이!', 10, 3, 'GOOD', SYSTIMESTAMP);
