INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '아이가 너무 좋아하는 케이크집. 작년에 더현대에서 블루베리 케이크 만족스러웠는지. 이번엔 오레오 케이크로 사달라고 해서 성수동까지 왔어요 ㅎㅎ 너무 예쁜데 맛도 부드럽고 너무 좋아서 모든 친구들까지만족한 케이크였어요!!', 43, 4, 'GOOD', SYSTIMESTAMP);
