INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '카페가 너무 예뻐요 ㅎㅎㅎ 동화나라 같은 느낌 ㅎㅎㅎㅎ 타르트도 너무 예쁘구 포크도 너무 귀여워요 ㅎㅎㅎ 예뻐서 먹기아까웟어요...ㅠㅠㅎ 타르트에 작은  꽃도 장식되어있어서 너무 예뻣어요!!!^^* 세심한것 까지도 신경쓰시는것 같았어용^^ 곧 크리스마스라 크리스마스 트리와 대형인형까지 ㅎ 사장님도 너무 친절하시구, 인테리어 짱짱! 화장실 타일색 마저도 이뻐서...ㅎㅎㅎ 사장님의 진심이 너무 잘 보엿던 예쁜 가게였어요 ㅎ', 90, 14, 'GOOD', SYSTIMESTAMP);
