INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '합정 본점에서 예전에 디저트 맛있게 먹었던 기억이 있어서 친구생일겸 도시락 미니 케이크 주문해봤어요~ 케이크 너무이쁘구 가격도 싸요!', 33, 2, 'GOOD', SYSTIMESTAMP);
