INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '알바분이 사장님인줄 알았어요 너무 일 잘하시고 센스가 좋으시더라구요! 크렘당쥬랑 딸기 케이크 포장 해갔고 맛있게 먹었어요!🍰🍦 쿠키도 있고 케익도 다양하고 주문제작도 하시는거 같아요 디자인도 다양해요✨', 24, 10, 'GOOD', SYSTIMESTAMP);
