INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '리뷰 다시 수정합니다. 제 리뷰 답글에 마치 처음부터 40자인데 제가 못본것처럼 말씀하시네요? 네이버메뉴에서 1호 사이즈 45글자 확인하고 글자수 맞게 요청하였고, 당일 아침에 다  만드시고 연락주셨죠;; 빵크기는 작고 크림 듬뿍인건 둘째치고 답글이 좀 짜치시네요 네이버 메뉴에 45글자라고 해서 글자수 적었는데, 40글자라고 네이버에 업데이트가 안됐다고 해서 40글자로 만들고나서 얘기해주거라고요. 생각한 멘트가 하나 빠져서 섭섭하네요', 11, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '친구 생일이라 급하게 당일 아침에 예약했는데 너무 예쁘게 잘 준비해주셔서 마음에 들었어요😍 블루베리 크림치즈 골랐는데 크림도 너무 맛있어서 친구들이랑 다 감동했어용ㅎㅎ 가격도 비싸지 않아서 만족합니다!', 45, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '원래 후기 잘 안올리는 편인데 사장님도 너무 친절하시고 케이크가 너무 예뻤어요! 부모님 결혼 기념일에 작은 이벤트로 처음 해봤는데 좋아하셔서 정말 뿌듯합니다🤍 보통 예쁜 케이크는 맛이 없다고 하던데 이 케이크는 다들 너무 맛있다고 잘사왔다고 하면서 먹네요!!! 당일 제작 해주신다는 점도 너무 큰 장점 같아요 사장님 손이 엄청 빠르신가봐요 ㅎㅎㅎ 다음에 또 방문하고싶습니다!😆', 25, 0, 'GOOD', SYSTIMESTAMP);
