INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '기념일을 위해서 레터링케이크 주문했다가 쿠키슈랑 크루키가 귀여워서 같이주문!! 크루키도 맛있고 쿠키슈도 안에 말차크림 듬뿍! 케이크도 얼그레이 주문했는데 달지않고 맛있었어용 ㅎㅎ', 24, 6, 'GOOD', SYSTIMESTAMP);
