INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '케익 너무 귀엽고 이뻐요! 카페도 인테리어 참 예쁘고요!! 직원분도 친절하시구 생축도 같이해주셨어용 ㅎㅎ 감사합니다! 좋은 추억 만들어가요🥰', 20, 8, 'GOOD', SYSTIMESTAMP);
