INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '케이크가 귀여워요 글씨체두 넘 귀엽고요 ㅋㅋㅋ마감이 생각보다 빠르더라고요.. 예약시간보다 조금 늦어서 마감 전에 간당간당하게 갔는데 ㄴ전화로 확인해즈시고~~그랬습니당', 32, 8, 'GOOD', SYSTIMESTAMP);
