INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '생일일때 케이크 준비못하신분들? 여기서 맛별로 종류별로 바로 구매 가능합니다! 주문제작도 가능하고 카페 내부도 엄청 뽀짝하게 꾸며져있어요🤭 케이크.. 진짜 맛있어요ㅎㅎㅎ 쿠키도 맛있겠죠? 못먹어봤어요 저대신 후기 남겨주세요ㅎㅁㅎ 매장 좌석도 많아서 데이트하고 포토존에서 사진찍기 추천합니당 주말에는 스무디를 안해요! 참고해주세용..!', 72, 11, 'GOOD', SYSTIMESTAMP);
