INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '레터링케이크 구매했어용 특이하구이쁜거찾다가 발견했는데 곧 결혼하는 친구가 엄청 좋아해줬습니다!! ㅎㅎㅎ 예브게만들어주셔서 감사합니다', 87, 14, 'GOOD', SYSTIMESTAMP);
