INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '내가.. 시간이없어서 당일 수령가능한곳에서 구매했는데 와… 이건 아닌듯 ㅋㅋ 27000원의 값어치 1도없음 그냥 다른곳에서 도시락 케이크 당일수령 상품 사세요 진짜 없어보이는 케이크…', 10, 10, 'BAD', SYSTIMESTAMP);
