INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '작년 친구 생일에 주문했어요. 케이크가 정말 귀엽고 맛있다고 무척 기뻐했어요. 생일 당일날 주문했는데 오전에 받을 수 있어서 좋았습니다.', 12, 0, 'GOOD', SYSTIMESTAMP);
