INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '이벤트 케이크용으로 주변 레터링 케이크샵을 뒤지다가 너무 귀엽고 예쁜 샵이 있어서 주문했습니다. 너무 예쁘게 레터링 해주셔서 아까워서 못먹었어요ㅠㅠ 받은 사람도 상당히 좋아해주어서 뿌듯했습니다. 다른 디자인들도 다 너무 독보적이고 깜찍해요💓', 25, 1, 'GOOD', SYSTIMESTAMP);
