INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '좋은날을 기념하려고 해피베어데이 상수점에 다녀왔어요 ㅎ 오며가며 많이 봤던곳인데 직접 가서보니 넘 이쁘네요 ~ 동화같은 느낌 그대로입니다 쿠키종류도 많아 담번엔 매장에서 먹어보려구요 ㅎ 얼그레이케잌 짱 맛있어요 ㅎ', 4, 5, 'GOOD', SYSTIMESTAMP);
