INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '다행히 받으신 분은 만족하셨습니다만.... 사진과 많이 다르네요. 알파벳 초콜릿도 사진처럼 깔끔하게 나오지 않고.. 뒷부분 초콜릿이 지저분하게 붙어있습니다. 색상도 하늘색에 가깝습니다. 1호도 아주 작습니다.', 21, 8, 'BAD', SYSTIMESTAMP);
