INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '6시30분 예약 방문했는데 부득이하게 마감 7시에 도착했어요ㅜㅜ 미리 문자 드리니 기다려주신다고 편하게 오시라고 친절하게 답변해주시고 케이크 사진도 찍고 갈수 있게 해주셔서 넘 좋았습니다!̆̈ 홍대나 상수에서 케이크 필요하시면 요기 정말 추천합니다:)', 7, 2, 'GOOD', SYSTIMESTAMP);
