INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '기념일인데 급하게 필요해서 찾다가 당일 픽업도 되길래 전날에 예약했어요! 케이크 너무 귀엽고 맛도 맛있었어요ㅎㅎ 직원분도 친절하세요', 73, 13, 'GOOD', SYSTIMESTAMP);
