INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '레터링 추가도 무료로 해주시고 케잌 너무 맛있규오!!! 디자인마다 맛이 다른게 별미였어요 ㅎㅎ 기다리지 않고 급한 때 방문해서 구매 가능한 점도 좋고 매장과 다른 디저트들도 예뻤습니다 ㅎㅎ', 20, 7, 'GOOD', SYSTIMESTAMP);
