INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '레터링을 실수했는데 바로 수정해주셨어요ㅠㅠ 가격대비도 좋고 맛도 있고 귀엽고 다 좋았어요~! ㅎㅎ 감사합니다 이쁜 추억 만들었어용', 38, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '초 안주셨고 케이크칼이나 성냥없고 말그대로 박스이 케이크만 받았습니다 테이프도 안붙여 주셔서 뚜껑 열리려고 하고 총판? 하시는 분이 각 지점에 전달하는 방식인거 같은데 이게 너무 답답한 구조인거 같습니다 분명 달라고 요청했었고 알겠다고 하셨는데 못받아서 다른거라도 달라했더니 막상 받으러 방문 하니까 알바분이 모양초 하나만 가져가시는 걸로 전달받았다 하시고.. 아무리 당일제작 케이크라도 기본적인게 너무나 안돼있어요.. 케이크가 보통 기념일에 주문 하는데 4만원주고 이건좀.. 파바만큼도 못하면.. 그냥 전시된거 사고 그자리에서 초 가져가고 하죠.. 좀 실망 많이 했습니다', 34, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '같이 운동하는 중학생 생일이어서 급하게 주문했습니다! 당일 예약인데도 레터링도 수정 가능해서 좋았습니다 직원분들도 친절하고 케이크도 너무 예뻐요! 모두 좋아했습니다', 57, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '두 번째 이용입니다! 친구 생일이라 급하게 예약하고 갔어요 저번에는 생크림 요번에는 레드벨벳 케이크로 예약했는데 케이크는 다 맛있어요😋 가성비 갑이고 가끔씩 그냥 이집 케이크가 먹고 싶어서 생각날 때도 있어요:) 급하게 케이크 필요하신 분들 여기서 사시면 만족도 높을 것 같아요!!', 80, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '친구 생일 케이크로 주문한건데 너무 귀엽네용 중간에 소주 초는 음식점에서 주신거라 매장에는 없습니다! 기본 초 안 주는 곳들도 많은데 기본 초 주셔서 좋았어용 그리고 카운터 쪽에 귀여운 초들이 많더라구요! ☺️ 다음에도 이용하께용', 40, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '생크림 2호 구매했습니다! 케이크 디자인은 하나라서 고를수는 없습니다 참고 부탁드립니다. 저는 글씨릉 전부 14글자로 했더니 사실 너무 작아서 사진찍을때 하나도 안보여서 비추해여ㅠ 두꺼운 글씨라 잘 안보입니다 ㅠㅠ 그냥 짧게 쓰시는게 좋아요! 맛은 신선하고 토끼도 귀여워서 좋은 기념일 보냈습니다!', 8, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '상수동 디저트 카페로 유명한 해피베어데이 상수점 다녀왔는대 매장 내부가 층고도 높고 매장도 넓어서 좋아요! 내부 인테리어도 예쁘고 귀여운 곰돌이들이 많아서 사진 찍기 너무 좋고 디저트도 다양한데 전부 다 맛있어서 커피랑 잘 어울리네여! 평일 낮에 와서 힐링 제대로 하고갑니닷', 41, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '홍대데이트코스로 해피베어데이 상수점 방문했어여 동화속인듯한 분위기 기여운 곰돌이가 가득 기엽뽀짝 케익 촉촉하고 부드러운쿠키까지 데이트 인생샷 와르르 남기고 왔어여 화사하고 이쁜 인테리어 자주 올듯하네여 번창하세요', 33, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '재작년에 이어 또 여기 들려서 케이크 주문하는데 맛있고 받는 사람들도 만족합니다! 상수점 직원분도 친절하시고 접객매너도 좋으셔서 재재방문의사 있어요 ·͜·', 42, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '같은 케이크 맞나요? 너무 충격적이라 받자마자 가게에가 사진 찍었습니다. 3만5천원 짜리를 이렇게 만드실거면 도안을 저렇게 당당하게 올려두시면 안되죠... 글자도 저렇게 테두리 다 보이게 만드시고, 케이크 길이도 사진과 다르고 심지어 비대칭이네요. 남자친구 첫 생일이었는데 너무 미안하고 창피했어요 6월에 구매했고 지금 새로운 레터링 케이크 알아보다가 이 지점이 다시 뜨길래 리뷰 작성합니다.', 106, 26, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '삐져있는 남편을 위해 서프라이즈 도시락케이크 주문했어요:) 귀염뽀짝한 컬러에 레터링도 넘 사랑스러웠어요♡   케이크 넘 맛있었고 디저트 카페라 커피 기대안했었는데 아메리카노도 넘 맛있네요!! 달달하게 당충전하며 데이트하기에 넘 좋은 곳으로 추천해용!!', 2, 9, 'GOOD', SYSTIMESTAMP);
