INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '픽업 2일전에 예약했는데 원하는대로 넘 귀엽게 나왔구 사이즈도 작을줄 알았는데 3-4명이 먹기 크기도 딱 괜찮았어여~~12:30분예약했는데 사장님이 배려해 주셔셔 늦게 갔는데 친절하게 응대해주시고 담에 또 방문할거예여~~~', 27, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '예약할때 케이크 사진이 잘 보이는 상세사진이 있었으면 좋겠어요ㅠㅠ너무 작은 사진에 인스타 찾아봐도 안나와서 고르기 어려웠어요ㅠ 케이크는 귀엽고 맛도 있었습니다!', 89, 14, 'GOOD', SYSTIMESTAMP);
