INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '케이크 예약하고 영업마감시간 조금지나 도착했는데, 기다려주셔서 너므 감사합니다~^^ 덕분에 즐건생일파티했어요~~~^^ 플라워케이크 너무 예뻐요~~~', 43, 5, 'GOOD', SYSTIMESTAMP);
