INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '설연휴 방문 했어요. 명절이라 안붐벼서 좋았고 귀엽고 맛있는거 잔뜩있어서 아이가 무척 좋아했네요 아이랑 느긋하게 데이트 하고 갑니다ㅎㅎ 메론소다 맛있다고- 추운데 다 먹음ㅎㅎ 귀여운거 좋아하는 사람들 좋아할것 같아요', 17, 1, 'GOOD', SYSTIMESTAMP);
