INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '상수역 골목에 있는 큰 집같은 카페! 내부도 넓고 곰돌이 쿠키들이 너무 귀엽고 맛있습니다. 케이크도 알록달록 예뻐서 기념일 케이크로도 강력 추천합니다👍🏻👍🏻👍🏻 음료도 재료를 안아끼고 넣어줘서 좋았슴니당!', 42, 1, 'GOOD', SYSTIMESTAMP);
