INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '귀요미 곰돌이가 가득한 분위기 좋은 상수역 카페~ 사진 찍을 포토존도 많구 맛있고 귀여운 디저트가 있어 데이트하기 딱 좋았어요. 진한 커피 맛과 구름이 동동 떠 있는 비주얼 좋은 소다 음료까지 즐기고 왔답니다.', 98, 24, 'GOOD', SYSTIMESTAMP);
