INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '분위기 너무 좋고 귀여운 캐릭터로 가득해서 너무 이뻐용💕💕정말 너무 맛있는 음료와 아메리카노!!  고소하고 음료수도 너무 맛있어 원샷해버렸어용ㅎㅎㅎ 쿠키도 정말 귀여워서 먹기 아까울 정도!!🥰🥰', 65, 14, 'GOOD', SYSTIMESTAMP);
