INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '홍대 상수 에서 당일 레터링 이 가능한 🐻✨️ 귀여운 케이크 와 매일 제작되는 다양한 곰돌이 쿠키 그리고  음료를 즐길 수 있는동화 속 에 온 듯한 상수 디자트 카페 💛 곳곳이 포토존📷', 14, 2, 'GOOD', SYSTIMESTAMP);
