INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '100일 케이크루 전날에 급하게 예약했는데 너무 귀엽구 예쁜 케이크 잘 받았어요🩵💘 맛도 너무 맛있었구 덕분에 좋은 하루 보냈네용 픽업하면서 오레오 스콘이랑 크림소다두 먹었는데 둘다 너무 맛있었습니당😆🫶🏻🫶🏻', 49, 6, 'GOOD', SYSTIMESTAMP);
