INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '레터링 케이크는 꾸덕한 치즈가 많이 있을거란 생각을 완전히 없앤 케이크 였습니다~☺️☺️진짜 생크림 케이크도 너무 맛있고 다음 기념일이나 행사때도 꼭 들러서 하나씩 살게요! 맛있는 케이크 감사합니다 ㅎㅎ', 44, 4, 'GOOD', SYSTIMESTAMP);
