INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '너무나도 귀여운 쿠키들이 많이 있었어요!! ㅋㅋㅋㅋ 보기 좋은 떡이 먹기도 좋다고 디자인이 이뻐서 그런가 더 먹음직스럽게 보이더라구요! ㅋㅋㅋㅋㅋ 음료도 다양한 편이고 매장도 넓고 테이블이 많아서 좋았습니다. 상수 데이트 갔을 때 디저트 먹기 딱인것 같아요!! 추천합니다. * 이 글은 서비스를 제공받아 작성된 글입니다.', 38, 4, 'GOOD', SYSTIMESTAMP);
