INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '곰돌이들이 예쁘고 쿠키도 예쁘고 신기한 메뉴 많아서 좋았어요. 둘이서 쿠키 세개랑 음료 두잔 시켰어요. 쿠키맛이 좋아서 쿠키 두개는 나중에 포장했어요. 다만 아쉬운점이 물 달라고 하면 왜 싫어하시는거같죠? 대답도 없이 물 주는게 이상했어요 ㅋㅋ 한번 더 달라했더니 대답을 안하시더라구여.  얻어마시는 기분이라 주지말라했어요 ㅎㅎ 물을 판매하시지 왜 그냥 주시나요? 불편했어요ㅜ', 13, 3, 'BAD', SYSTIMESTAMP);
