INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '디자인 케이크 주문했는데 다른 곳보다 저렴하고 너무 예뻤어요! 원래 디자인 케이크 맛 없어서 안좋아했는데 여기껀 참 맛있네요❤️', 13, 4, 'GOOD', SYSTIMESTAMP);
