INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '커피 반, 크림 반으로 다른 카페에 비해 크림을 많이 주셔서 좋았고, 커피는 약간의 산미가 있으나 진하지 않아 마시기 편하다. 크림도 무겁거나 느끼하지 않고 가벼운 질감이라 만족스러웠어요 곰돌이 모양이 넘 귀여움!! 썰 때는 상당히 부드럽게 썰리는데 씹을 때는 바삭바삭하다. 겉의 바삭함 90%, 속의 꾸덕함 10% 비율의 식감이랄까?! 말랑한 마시멜로우랑 같이 먹으면 완벽한 식감!! 흑임자 크림맛이 생각 이상으로 찐했어요🐻 스콘이라 퍽퍽할 줄 알았는데 쿠키보다 상대적으로 부드러웠어요~~ 귀여운 개구리와 알록달록한 색감이 어우러져 일단눈으로 만족!! 비쥬얼 끝판왕임! 맛으로도! 새콤한 크림치즈가 달달한 시트지와 만나 완벽한 궁합을 이뤄 맛있었어요!', 21, 2, 'GOOD', SYSTIMESTAMP);
