INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '카페 인테리어도 아기자기하니 이뻤는데 디저트들까지 이렇게 귀엽따뇨 ㅠㅠ 케이크는 진짜 너무 귀여워서 맛은 기대도 안햇는데 너무맛있어요!! 단거 안좋아해서 케이크 안먹는 제 남자친구도 이거 맛있다 하면서 한조각운 먹더라구요!! 맛도 좋거 분위기내기도 최고인카페🫶🏻🫶🏻 케이쿠 디저트맛집 추쳔👍', 66, 18, 'GOOD', SYSTIMESTAMP);
