INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '최애 생일이라 기념으로 레터링케이크 판매하는곳중 오늘 운영하는데가 여기 있더라구요 🥹 심지어 맛도 있고 직원분도 너무너무 착하셨어서 좋았어요 ㅠㅠ 제가 1시간정도 일찍 갔는데도 되게 착하게 이야기해주시고 , 그래서 되게 금방 나왔어요 👍👍 다음에 또 기회되면 사러 올게요 👏', 0, 0, 'GOOD', SYSTIMESTAMP);
