INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '친구 생일이라서 급하게 당일 예약 가능한 곳 찾다가 알게됐어요! 알록달록 너무 이쁘고 귀여웠어요! 생일 주인공도 좋아하고 뿌듯했습니다😊', 295, 32, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '당일 레터링 케이크 예약이 가능한 곳이 있다는게 너무 좋아요~ 문구도 예쁘고 잘 적어주셔서 감사합니다 도시락 케이크 너무 귀여워요!!💛 급하게 레터링 케이크 필요하신 분들에게 강추입니다:)', 12, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '리뷰가너무늦었지만^^; 급하게 준비하느라.. 수령 전날 케잌 예약할 수 있어서 좋았어요. 산타케이크는 물론이고 상자까지 귀여워서 역할 톡톡히 다 했습니다.😎', 13, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '카페들어오자마자 아기자기 귀여운  곰돌이 케잌 친구들이 인사하네요! 너무 이쁜 디저트들 보며 음료 뭐먹을까 생각하는데 카페들어가고 문에서 부터 행복하더라고요! 좋은 에너지를 주는 카페공간이였어요', 477, 29, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '여기서 도시락 케이크만 5개가 넘게 주문했었는데,  이번엔 네이버포인트도 쌓였겠다싶어 미니케이크로 주문해봤어용. 그냥 예전부터 미니케이크로 할껄~이라는 생각이 들었네요 ㅎㅎ 너무 예쁘고 너무 맛있고, 5명이서 한조각씩 나눠도 맛보기에 충분했어용 ㅎㅎ 감사합니다 항상~~담엔 제 합격케이크 사러오게되었으면 ㅠㅠㅠ', 12, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '동화 한 장면 같은 곳 “해피배어데이” 🐻 귀여운 곰돌이 인형들이 가득한 곳 쿠키부터 맛있는 레터링 케이크까지 당일 레터링 주문케이크가 가능합니다 (단, 당일 오후 5시까지는 예약해야합니당!)', 34, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '커다란 트리가 있어서 연말 분위기 많이나고 좋았어요! 케이크도 맛있고 특히 슈가 맛있었어요! 넘 제스타일:) 사진잔뜩 찍고가요', 16, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '하루 전에 급하게 예약하고 찾으러 갔는데 합정점으로 착각해서 방문....ㅋㅋㅋㅋ 직원분께서 친절히 상수점 알려주셔서 7분 거리 이동했습니다. 상수점 직원분도 친절하셔서 무사히 픽업 성공!! 사실 이렇게 색상이 화려하고 크림이 많이 올라간 케이크는 겉은  예쁘지만 맛은 별로일 거라는 선입견이 좀 있었는데 어우 너무 맛있었어요. 선물한 친구들도 예쁘고 맛있다고 해줘서 뿌듯했고요. 당일 레터링 케이크는 앞으로 해피베어데이 이용할 것 같아요. 좋은 경험이었습니다.', 0, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '상수점에도 오픈했다고 해서 방문했는데 역시나😍 곰돌이 디저트 너무 예쁘고 미리 예약한 케이크도 졸귀💕 랍니다.  레터링까지 완벽하게 해주셔서 너무너무 만족스러워요. 오레오케이크가 유명해서 오레오로 주문했는데 맛도 👍👍👍', 93, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '카페 입구부터 너무 기분좋아지고 행복한 곰돌이 월드로 들어가는 느낌이에요💗 곳곳에 곰돌이들이 많아서 곰돌이 덕후는 행복해요 케이크랑 쿠키들 너무 귀여워서 못먹겠어요 아까워서 ㅠㅠ 결국 먹었는데 넘 맛있었어요😋 모양만 이쁘구 맛없는곳 은근히 많은데 해피베어데이는 비주얼이랑 맛 다 잡음💕', 117, 26, 'GOOD', SYSTIMESTAMP);
