INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '두번째 방문이예요 매번 급하게 일정을 맞추느라 지인들 대표로 케이크 픽업하게 되는데 매번 너무 감사히 잘 애용중입니다 고구마 스콘은 픽업하러갔다가 먹었는데 물건이고 맛도리네요 감탄하고 먹다가 약속시간 늦을뻔했지만 너무 맛있습니다 🥰🫶', 57, 13, 'GOOD', SYSTIMESTAMP);
