INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '매장이 이쁘고 디저트들도 많아요 ㅎㅎ 케익맛은 엄청 특별하다! 이건 아니였지만 크림치즈 베이스에 맛있게 먹을 정도입니다 음료는 시그니처를 시켰는데 아이스크림에 탄산 느낌! 맛있어요ㅠ 썸 탈 때 오면 좋은 분위기 이끌어 갈 수 있을듯해요', 42, 1, 'GOOD', SYSTIMESTAMP);
