INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '당일 레터링 케이크 가능하면서 매장에서 먹을 수 있는 곳으로 찾았어요 케이크듀 바로 꺼내주시고 쿠키들도 귀여웠어요 음료도 다양해서 맛있었습니다', 35, 0, 'GOOD', SYSTIMESTAMP);
