INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '모여!!! 카페 왜케 예쁘고 큼직한겨!!! 쾌적하고 진짜 너무 좋은데요 😆 수박주스 또 먹고싶다요 후레시한 맛이 스벅 수박주스보다 백배 맛있잖아요! 리얼 수박 그 잡채!! 그리고 얼그레이 케이크 최고 맛있어요 ㅠㅠ 광광 울어.. 시원해서 완전 맛도리! 너무 달지 않아 좋았어요! 🍰🍉', 247, 33, 'GOOD', SYSTIMESTAMP);
