INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '말리랑 카페 ☕️ 미친 케이크 가게.. 왤케 맛있죠? 오레오맛 안 좋아하는데 여긴 미쳤어요 그냥 퍼먹어버림ㅠ 커피랑 찰떡쿵 제발 케이크 먹고 가세요.. 🏡 인테리어도 넘 예쁨 데이트 코스로도 좋고 부모님 모시고 와도 좋을 거 같아요 🐶 말리랑 편하게 있었으니까 이곳은 펫프렌들리!', 20, 3, 'GOOD', SYSTIMESTAMP);
