INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '와ㅠ 진심 유명한데는 이유가 있나봐요ㅠ 상수 카페 해피베어데이 진짜 케이크도 이쁜데 카페는 더이뻐요ㅠ 완전 사진찍기 넘 좋은 분위기에 외국같은 인테리어ㅠ 진짜 외관부터 맘에 안드는거 하나도 없어요ㅠㅠ 짱짱 ㅠ 최고 힐링 하고 인생 사진 건지고 갑니당 ㅠㅠ 케이크도 넘나리 맛있어요ㅠ 그리구 넘 귀여워요ㅠ 가격도 막 그렇게 안비싼데 왤캐 귀여워요ㅠ 못먹게써어ㅠㅠ (그리곤 다먹었어요…;;) 행복함니당💓', 48, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '두명이서 조촐한 생일 파티라 미니 사이즈로 적당~ 물림 정도로 먹었어요! 크림이 느끼하지 않고 적당히 달아서 맛있게 먹었습니다!', 23, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '케이크 픽업하러 갔다가 공간이 아늑하고 디저트가 맛있어보여서 쿠키도 먹은 공간 💛 에어컨도 시원하게 틀어주시고, 층고가 높아서 공간감이 있는 카페예요! 디저트 맛있고, 당일 예약한 케이크도 예쁘게 만들어주셔서 친구가 감동했어요 💖', 124, 26, 'GOOD', SYSTIMESTAMP);
