INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '케이크가 넘 깜찍하고 귀여워요~( ≧∀≦)ノ 💓문구도 새길 수 있어서 곧 군대가는 동생을 위해 ''군생활 응원해'' 새겨주었어요. 선물받은 동생도 넘 감동이래요~😉✌️ 💓케이크🍰도 같이 먹었는데 너무 달지 않아서 남녀노소 즐기기 좋았어요. 음료수도 케이크랑 너무 잘 어울렸답니다＼(^^)／ 💓디저트가 모두 곰돌이 🐻 모양이라 너무 귀여워요.  깨물어주고 싶은 귀여움이라는 말이 찰떡같이 어울리는 곳이랍니다. 💓곳곳에 곰돌이 포토존이 있어 깜찍한 사진을 남기기 너무 좋은 카페에요. 상수역 인근 감성카페, 디저트가 맛있는 카페 찾으신다면 방문 추천드려요.', 5, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '애견동반이 가능해서 르네와 함께했답니다❤️ 매장이 크고 넓고 귀여운 소품으로 가득했어요😆😆 쿠키들도 맛있고 귀여운데 케이크는 더 귀엽고 더 맛있음요 ㅠㅠ 블루베리치즈케이크 주문했는데 꾸덕꾸덕한 치즈케이크에 달콤한 크림 때문에 행복했어요👍👍 음료도 너무 맛있고 시원하게 잘 마셨답니다 하트빨대랑 곰돌이 포크도 완전 취저 ㅋㅋㅋ 특별한 날에 케이크 주문하기 너무 좋을 거 같아요 해피베어데이 덕분에 맛있고 달달한 하루였네요😊😊💕 쿠키 포장도 가능해서 집에서 맛있게 잘 먹었습니다!!', 46, 6, 'GOOD', SYSTIMESTAMP);
