INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '다른 곳 도시락 케이크나 레터링 케이크 맛은 별로고 디자인 예뻐서 사는 경우가 대부분인데 해피베어데이는 디자인도 넘 귀엽고 너무 맛있어서 그 자리에서 다 먹었어용 기념일때마다 자주 주문하겠습니당!', 126, 26, 'GOOD', SYSTIMESTAMP);
