INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '귀염뽀짝의 절정이네요 ㅠㅠㅠㅠ 우연히 상수 골목에 밥먹으러 갔다가 눈여겨 봤던 곳!!! 친구한테 가자고 가자고 노래부르다 드뎌 다녀왔네요 ㅠㅠㅠ 하나같이 귀여움 터지는 메뉴들에 나약한 제 위만 원망스러울 뿐 재방문 각 세우고 있슴둥 ....', 13, 1, 'GOOD', SYSTIMESTAMP);
