INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '케이크 받으러 방문했는데 천장도 높고 인테리어가 완전 생일 느낌 뿜뿜나서 동화속에 있는 느낌이들었어요!ㅎㅎ 케이크도 요청대로 글씨체와 색감모두 만족스럽습니다. 레드벨벳 케이크인데 맛도 너무 쫀득하고 전체적으로 만족스러워용 다음에 또 방문의사있습니다. 덕분에 예쁜생일 보냈어요!♡', 36, 6, 'GOOD', SYSTIMESTAMP);
