INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '홍대데이트하기 좋은 카페! 내부 진짜 귀엽고 넓어요~ 무엇보다 케이크랑 쿠키 종류도 많아서 좋음! 커피랑 환상궁합ㅋㅎㅎ 또 갈거여요👍🏻', 25, 7, 'GOOD', SYSTIMESTAMP);
