INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '좋아하는 매장이라 케이크 선물하려고 들렀는데 급하게 요청했음에도 편리하게 픽업할 수 있어 좋았어요!🥰 음료랑 디저트는 믿먹인 곳이라 맛은 말할 필요 없이 짱맛👍ㅋㅋㅋ 매장 너무 예뻐서 매일 가고 싶은 곳입니당 강추 강추❤️', 26, 0, 'GOOD', SYSTIMESTAMP);
