INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '넘넘 귀여운 곰돌이 카페🐻🧸 곳곳에 곰인형이 가득해서 행복해지는 기분!! 디저트도 너무 맛있는데 특히 곰돌이 쿠키 너무 맛도리에욤🤍🤎✨ 디저트 종류가 다양하고 음료도 맛있어요~ 사진도 예쁘게 나와서 데이트 코스로 강추!!!', 28, 8, 'GOOD', SYSTIMESTAMP);
