INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '친구 생일이라서 도시락 케이크를 주문했어요. 야외에서 생파할 작은 케이크랑 레터링이 필요해서 주문하거라서 사실 맛은 큰 기대를 안했었는데 맛도 너무 맛있어요!!! 맛있어서 다 쓱쓱 먹었어요!!! 앞으로 도시락 케이크 주문할 때 여기서 하려고요. 네이버 예약으로 픽업 시간까지 예약 쉽게할 수 있어서 아주 좋습니다👍', 24, 4, 'GOOD', SYSTIMESTAMP);
