INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '카페 진짜 예뻐요!! 인테리어 완전 마음에 들어요!! 친국 생일케이크 급하게 예약했는데 생일 전달 예약가능한다니 너무 편했어요 추천추천!', 49, 3, 'GOOD', SYSTIMESTAMP);
