INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '라떼랑 매실에이드 마셨는데 라떼는 산미가 없고 엄청 고소해요!! 이렇게 맛있는 오랜만..❤️ 케이크는 또 왜이리 귀여운지 ㅎㅎㅎㅎ  매장이 귀엽게 꾸며져있어서 사진 찍으면 잘 나와요 상수역디저트가 드시고 싶으시면 여기로 !!!', 14, 8, 'GOOD', SYSTIMESTAMP);
