INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '저는 다음에도 꼭 여기서 주문제작 맡기고 싶어요..💖 가격도 너무너무 착하고 무엇보다 케이크가 정말 맛있었어요!!! 부드럽고 촉촉하고👍🏻 색 조합도 정말 여기가 제일 예뻐요.. 사장님께서 요청사항도 잘 받아주셔서 친구의 20번째 생일을 뜻깊게 축하해줬답니다❤️ 사장님 진심으로 감사합니다! 더욱 특별한 날을 만들 수 있게 해주셔서 감사해요💓 당일케이크였지만 맛도 가격도 퀄리티도 최상이었습니다🫶🏻💖💖💖', 6, 4, 'GOOD', SYSTIMESTAMP);
