INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '곧 저의 생일 겸으로 해피베어데이 상수점에 방문했는데 귀여운 곰돌이들 인테리어부터해서 엄청 시원하고 케이크 비주얼 진짜 역대급 귀여움 아닌가요 이렇게 귀여운 케이크 처음봐요 귀여운 케이크 1등💕 생크림이 많아서 느끼하지 않을까 걱정했는데 하나도 느끼하지도 않고 너무 맛있었어요 음료수까지 맛있어요 비주얼부터 맛까지 너무 완벽 :)', 10, 6, 'GOOD', SYSTIMESTAMP);
