INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '케이크 모양이 완전하지 않습니다. 특히 테두리의 왼쪽 하단 보시면 분홍색 위에 노란 색이 저렇게 올라와있는 어떻게 보면 망쳐서 다시 해야 하는 작업을 그냥 상품으로 내보냈습니다. 아마도 당일에 필요하다는 주문케이크의 특성상 취소하거나 다시 해달라고 할 수 있는 상황이 거의 없을테니 그냥 내보내셨겠죠. 이렇게는 영업하지 않으셨으면 합니다.', 2, 4, 'BAD', SYSTIMESTAMP);
