INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '진짜 여기 셀카 넘 잘나오네요... 디저트 맛집인데 셀카 맛집이라서 인생샷까지 폭풍으로 건지고 갑니당... 행복 그 잡채~~~! 전 오레오케이크 미니 사이즈 했는데 넘 맛있어서 폭풍 흡입했어욬ㅋ⫬ㅋ⫬ㅋ⫬', 56, 13, 'GOOD', SYSTIMESTAMP);
