INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '너무나 귀여운 공간. 귀여운 곰돌이 쿠키슈부터 귀여운 스콘들 그리고 케이크도 여러가지라 ... 세상 귀여움에 충격먹은 카페. 크림캔디소다는 진짜 너무 맛있어서 한 3잔째 먹어본 것 같습니다. 쿠앤크프라페도 처음 시켜봤는데 역시... 이집은 다 맛이', 16, 8, 'GOOD', SYSTIMESTAMP);
