INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '당일 급하게 시간도 픽업시간 얼마 안 남기고 예약했는데 친절하게 픽업 가능하게 해주셔서 감동~😊 케이크가 너무 달거나하지않아서 맛있게 잘 먹었네요~ 어른들 입맛에도 괜찮은것 같습니다~ 추천!', 3, 6, 'GOOD', SYSTIMESTAMP);
