INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '쿠키로 유명한 해피베어데이! 쿠키맛집인줄 알았는데 케이크도 너무 맛있어서놀랐어요 오레오 케이크 추천합니다 꾸덕하고 진해서 맛있고 위에 데코크림도 느끼하지않고 맛있어요 생각보다 양도 많아서 생일케이크로 자주 사러올거같아요 인테리어도 넘 귀여워용 !!🐻💟', 86, 17, 'GOOD', SYSTIMESTAMP);
