INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '덕분에 아주 보람차게 생일을 축하해줬어요❣️ 실물도 너무 귀엽고 맛도 좋고 아주 가게를 방문한 보람이 넘칩니다ㅠㅠㅠㅠ 다음번에도 기회가 되면 꼭꼭 재방문하겠습니다😋', 44, 2, 'GOOD', SYSTIMESTAMP);
