INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '당일 레터링 문구 주문되는 시스템 최고에요 급하게 낮에 주문해서 저녁에 픽업해서 생파했는데 받는사람이 감동해서 눙물흘림..🥹 도시락 케이쿠 너무너무 귀엽고 이쁘고 다해~~~ 내가 갖고싶더라능❤️❤️❤️ 앞으로 자주 이용할 예정이애오', 62, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '외부너무 귀엽고 내부도 귀엽고 아기자기 사랑스러운 소품들까지 당일가능 레터링케이크에 스콘쿠키 쿠키슈까지 너무 좋았어요!! 즐루베리치즈케이크 속 크림치즈도 너무맛있고 빵도 카스테라처럼부드럽고, 음료도 맛있었습니다.내부공간도 넓고 층고도 넓어서 머무르기에도 너무 좋습니다👍🏻❤️', 8, 1, 'GOOD', SYSTIMESTAMP);
