INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '일단 직원분들이 친절하시고 매장이 넘 이뻐요 아기자기 ㅎㅎ 해피베어데이 진작 와보고 싶었는데 드디어 와서 좋더라두요! 디저트도 이쁘고 맛도 있어요!!! 슈크림빵이랑 케익사서 빵은 매장에서 먹구 케익은 가져가려구 해요 선물용으로도 넘 이쁜거 같구 담에 또 오려구요❤️', 17, 6, 'GOOD', SYSTIMESTAMP);
