INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '가게 외부부터 내부까지 동화속 같더라구요~ 요즘 핫한곳이라 방문해봤는데, 인기많은 이유를 알겠더라구요!! 카페도 넓고 디저트 메뉴들 하나같이 너무 귀여워요!! 솔직히 디저트가 예뻐서 맛은 기대도 안했는데 맛까지 완전 굿굿!! 레드벨벳케이크 먹어봤는데 찐하고 맛있더라구요~ 재방문 의사 완전 있습니다!', 15, 1, 'GOOD', SYSTIMESTAMP);
