INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '홍대에 아이와 같이 갈 귀여운 카페를 발견해서 주말에 시간보내려고 왔어요~외관부터가 깜찍해서 완전 기대하고 왔어요! 딸기 요거트 스무디랑 크림 라떼, 각각 블루베리 케잌과 초코 오레오 케잌을 골랐어요~쿠키들과 슈들도 너무 귀엽고 깜찍해서 먹고 싶었어용! 크림 라떼는 부드럽고 진한 커피맛이라 역시 기대했던대로 맛있었어요~크림이 내내 살아있어요, 딸기요거트스무디는 진한 딸기맛과 어우러진 요거트라 상큼하고 좋았어요! 하트 모양 빨대라 너무 특별해서 단독샷도 따로 찍었어요~포크도 곰돌이 모양이고 쟁반도 곰돌이 모양이라 인테리어를 비롯해서 신경 많이 쓰신거 같고 사진 엄청 찍었어요! 곰돌이들 사이에서 찍은 샷들 넘나 마음에 듭니당~', 96, 23, 'GOOD', SYSTIMESTAMP);
