INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '도시락케이크 픽업 예약 했어요 늦을거같아서 전화드렸더니 영업시간 내에 오면 된다고 하시더라구요 케이크 맛있었고 너무 귀여워요 ㅠㅠ 초는 기본초 하나 주시구요 성냥도 주시는데 불 붙이는게.. 없더라구요..? 제가 받은거만 불량인지 ㅠㅠ', 44, 8, NULL, SYSTIMESTAMP);
