INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '당일 레터링 케이크 되는 곳 알아보다가 디자인이 너무 귀여워서 급하게 예약했습니다. 몇 글자 안되는데도 기본 디자인이 워낙 귀여워서 급하게 주문한 티도 하나도 안나고 너무 예뻐요!!! 무엇보다 디자인이 예쁘면 맛은 별로 기대 안하게 되는데 케익이 너무 맛있어요;; 먹어본 레터링 케이크 중에 제일 맛있었던 것 같아요. 덕분에 좋은 선물했습니다! 번창하세요', 18, 1, 'GOOD', SYSTIMESTAMP);
