INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '정말 기념일 케이크로 여기만큼 이쁘고 귀여운 곳 없어요! 남자친구와 함께 와서 서프라이즈 해줬는데 넘 이쁘고 레드벨벳 시트도 맛있어요 인테리어부터 심쿵하고 가요', 20, 7, 'GOOD', SYSTIMESTAMP);
