INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '친구 생일 케이크로 미리 예약해서 픽업만 하려다가 내부가 넘 예뿌고 귀여워서 커피까지 마시고 갔늠데 이렇게 귀엽고 또 귀엽기 있나여 .. ❤️🤎❤️ 귀여운거에 환장하시는 분들은 무조건 가보세여!!! 케익도 귀여운만큼 마싰구 귀요미 쿠키들도 잔뜩있었다눙😚', 12, 3, 'GOOD', SYSTIMESTAMP);
