INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '너무 귀여운 디저트가 많아용 ㅠㅠ 맛도 최고에요 지방에서 올라와서 케이크 예약 당일에한건데도 진짜 너무너무 귀엽게 해주시고 퀄리티 좋아용 색감도  귀염뽀짝해서 생일 주인공 친구가 너무 취향저격이라고 좋아햇어요 ㅠㅠ 짱!!', 48, 3, 'GOOD', SYSTIMESTAMP);
