INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '케이크 픽업 갔는데 매장이 진짜 너무 귀엽고 예뻐요! 케이크도 너무 귀엽고 미니라 가격도 괜찮아서 앞으로도 여기서 케이크할 것 같아요!💓💓💓', 81, 18, 'GOOD', SYSTIMESTAMP);
