INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '이야 여기 진짜 귀엽고 맛있고 다한다. 당일 주문제작 케이크도 가능한 해피베어데이. 자세한 후기는 하단 링크 타면 블로그에서 확인할 수 있어요 :) https://m.blog.naver.com/yamuzzini/223070198868', 13, 6, 'GOOD', SYSTIMESTAMP);
