INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '카페 자체가 넓고 루프탑까지 구비되어 날씨 좋은 날가서 사진찍기에도 딱인 곳 ! 무엇보다 안에 귀여운 소품도 많고 쿠키들도 귀엽 ​ 특히나 쿠키가 쫀득해서 쿠키 꼭!!! 사오는 거 추천 어린아이들한테 사주기에도 좋고 친구들한테 하나씩 사주는 것도 괜찮고 무엇보다 케이크 퀄리티가 ... 주문제작 맡겨도 문제 없을 듯 재방문 의사 ⭕️', 33, 10, 'GOOD', SYSTIMESTAMP);
