INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '직원 분들이 친절하고 디저트가 정말 맛잇네요. 말차 프라페와 레몬에이드 시켜먹었는데 에이드류들은 청에다가 그냥 물타는 것이 아니라 기계로 직접 갈아서 주시고, 말차 프라페도 진해서 맛있었습니다.', 3, 5, 'GOOD', SYSTIMESTAMP);
