INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '레터링케이크가 너무 귀엽고 예약없이 가도 당일케익에 레터링도 적어주셔서 너무 좋은거 같아요! 케익말고도 쿠키 종류도 있어서 좋아요 ㅎ 인테리어도 아기자기하면서 이뻐요', 121, 26, NULL, SYSTIMESTAMP);
