INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '쿠키랑 슈 적당히 달고 넘 맛있었어요 케이크도 너무 귀여워용 당일예약으로 이렇게 예쁜 케이크를 살 수 있는 게 넘 좋은 것 같아요 생일 당사자도 되게 좋아했어요 ʕ”̮ॽु⋆⁺₊⋆ ♡̷̷̷  인테리어도 깔끔하고 좋아요 .ᐟ .ᐟ', 30, 2, 'GOOD', SYSTIMESTAMP);
