INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '완전 귀여운 케이크들이 잔뜩 있어요... 넘 귀여운데 맛도 좋음!!! 쿠키슈랑 쿠키에도 다 곰돌이 그려져 있어서 귀여워요 ㅎㅎㅎ 분위기도 크리스마스 같아서 좋고!! 매장도 넓어서 맛있는 거 먹으면서 수다떨기 딱 좋을 듯?!?', 12, 6, 'GOOD', SYSTIMESTAMP);
