INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '상수역디저트 찾다가 발견한 해피베어데이😊 케이크가 귀엽고 맛있어요 크림메론소다가 너무 맛있어요✨ 비주얼도 맛있는데 진짜 맛도 있어서 추천합니다🍰🎂', 50, 8, 'GOOD', SYSTIMESTAMP);
