INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '곰돌이 디저트 너무 귀여워요 ฅᐢ..ᐢ₎♡ 나이프로 잘라 먹기가 아까울 정도로 깜찍하네요.! 디저트 종류도 다양하고 케이크랑 내부도 아기자기해서 여성분들이 진짜 좋아하실 것 같은 카페에요🐻💗 메론 소다도 달달하니 좋고 구름 소다는 딱 뽕따 맛이라 맛있게 먹고 왔어요 ☁️🤤 홍대 상수역 디저트 맛집 추천합니다 !!!', 5, 7, 'GOOD', SYSTIMESTAMP);
