INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '곰돌이 천국! 해피베어데이! 가게 곳곳이 포토스팟이에요 ㅎㅎ 프사 건지기 쌉가능❤️ 케이크 맛은 말모말모 넘나 맛있쥬 둘이와서 한판 싹스리하고가요 ㅎㅎ 담에 또 올게요', 11, 1, 'GOOD', SYSTIMESTAMP);
