INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '카페 인테리어가 너무 이뻐요. 색감과 소품이 잘 어울려서 어디서 사진 찍어도 포토존이에요. 골목에서부터 이쁜 외관이 너무 눈에 띄어서 들어왔는데 인테리어 맛집에 디저트 맛집이에요. 특히 딸기 에이드가 큼직한 딸리가 씹혀서 너무 맛있어요~!!!', 35, 0, 'GOOD', SYSTIMESTAMP);
