INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '매장 인테리어가 독특하고 예뻐서 사진 찍기 좋아요. 네이버 예약을 이용해서 간편하게 도시락 케이크 주문했는데 디자인만 귀여운 게 아니라 맛도 좋아서 만족했습니다.', 331, 48, 'GOOD', SYSTIMESTAMP);
