INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '디저트도 예쁘고 매장도 넘넘 예쁜 해피베어데이상수점🍰 동화속에 온듯한 느낌이었어요💛 매장도 파스텔색감에 어디서 찍어도 넘 예쁘게 나오고 디저트도 완전 맛있음!! 특히 생크림케이크 입에서 살살 녹는 부드러운 케이크였고요🍰 황치즈쿠키도 진짜 맛있어요 꼭 드셔보세요!!!😎 딸기라떼도 딸기과육이 톡톡씹히는게 아쥬 존맛탱 아메리카노도 포장해서 가져갔는데요, 쿠키랑 아메리카노가 진짜 잘어울렸어요👍🏻 상수 해피베어데이 강추드려요!!😉', 21, 7, 'GOOD', SYSTIMESTAMP);
