INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '상수동 디저트 특별한 곳 갈때 해피베어데이 추천해요. 귀어운 곰돌이 인형들로 꾸며진 대형트리와 위로 탁트인 대형 창고형 카페가 시원한 개방감을 줘요. 색감 선명하고 예쁜 곰돌이 케이크와 곰돌이 바닐라 슈도 정말 달콤했어요 상수역 데이트하기 좋은 카페였어요', 17, 1, 'GOOD', SYSTIMESTAMP);
