INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '이름대로 입구부터 커여운 곰돌이들이 저희를 반겨줍니당 내부인테리어도 너무 기엽고 빈티지해서 사진 찍기에 굿입니다! 글고 디저트들도 진짜 넘넘 귀여워서 선물하기에 딱 좋습니다!!', 12, 3, 'GOOD', SYSTIMESTAMP);
