INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '케이크 디자인이 몽실몽실 귀여워요! 디자인은 정해져있는거라 문구만 정해서 알려드리면 되는데 저같이 디자인 결정 못하는 분들에게는 안성맞춤..! 귀여운 깜짝 서프라이즈 성공했어요😆', 46, 2, 'GOOD', SYSTIMESTAMP);
