INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '그동안 본점만 가보고 상수점은 처음 가봤는데 상수점도 하늘하늘해서 넘 예뻐요! 선물용으로 레터링케익 주문했는데 받으신 분이 너무 좋아하셨어요! 제가 해피베어데이를 좋아하는 이유는 케익이 너무 예쁜데 맛있기까지 해서 입니당..!! 비주얼은 너무 예쁜데 맛없는 케익 많잖아요.. 그런데 해피베어데이 케익은 한번도 실패가 없었어용!!', 9, 6, 'GOOD', SYSTIMESTAMP);
