INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '100일 케이크를 미리 예약하지 못해서 당일 예약이 가능한 곳으로 알아보다가 찾게 되었는데 매장도 너무 귀엽고 무엇보다 가격대비 퀄리티가 너무 좋았어요!! 안에 시트도 달달한 초코에 오레오 크림이라 맛있게 먹을 수 있었습니다 ㅎㅅㅎ', 81, 12, 'GOOD', SYSTIMESTAMP);
