INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '레터링 케이크 넘넘 귀여워요! 한가지 아쉬운 점은 도시락 케이크 알았지만 다른곳보다 더 작은 느낌이에요 (불평X 참고O) 넘 귀여워서 담에는 도시락말고 미니케이크로 구매할거 같아요!!:)', 39, 2, 'GOOD', SYSTIMESTAMP);
