INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '아기자기한 곰돌이들이 반겨줘요!!ㅎㅎ 디자인이 예쁜 케익들이 있어서 친구들이랑 모임하기도 좋을 거 같아요!! 다양한 쿠키 다 맛 보려면 또또 방문 해야 될 듯 합니다 ㅎㅎㅎ 맛난 쿠키 드시러 와보세영!!!', 30, 3, 'GOOD', SYSTIMESTAMP);
