INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '홍대에 있는 곰돌이테마 카페입니다. 곰돌이인형좋아하고 데이트코스론 딱입니다. 여친님이 매우 좋아할법한곳! 시그니쳐케이크도 맛있고 예뻐요', 37, 8, 'GOOD', SYSTIMESTAMP);
