INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '주문제작 케이크(블루베리크림치즈)를 테이크아웃하러 가서 얼그레이케이크와 밀크티라떼, 아이스아메리카노를 먹었습니다. 달달하고 향이 좋은 얼그레이라떼 너무 맛있고, 케이크도 정말 부드럽고 맛있었어요! 대형 트리가 있고 bgm으로 캐롤이 계속 흘러나와서 크리스마스 분위기 제대로 느끼고 왔습니다. 케이크와 음료도 맛있지만, 인테리어도 정말 멋진 카페에요!!', 6, 3, 'GOOD', SYSTIMESTAMP);
