INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '귀여운거 천지인 카페에요… 💗🐻🧸 정말 정말 귀여운 곰돌이 카페라서 곰도리를 너무 좋아하는 제겐 천국이었어요… 케이크랑 쿠키도 곰도리라 너무 기엽고 인테리어도 곰돌이 천국입니다🥰💗💕 귀여운거 좋아하면 꼭 가보세용🧸🧸', 89, 17, 'GOOD', SYSTIMESTAMP);
