INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '상수역에 귀엽고 아기자기하고 디저트 맛있는 카페 찾았다 ! 사진도 짱 잘 나오고, 커피며 음료며 모두 아기자기한 잔에 나오고, 쿠키랑 슈랑 케이크 모조리 귀엽고 맛있다 아기자기한 거 좋아하는 분들 대강추 다음에 또 올게요 !!', 4, 10, 'GOOD', SYSTIMESTAMP);
