INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '레터링 케이크로 유명한 곳이라 생일 기념우로 주문제작 했는데 실제로 보니 더 귀엽네요 🐰 생일 초도 따로 구매해서 꽂았어요 🕯 도시락케이크는 생각했던 거에 비해서는 사이즈가 좀 작았어요~ 그래도 맛은 괜찮았습니다 !', 45, 8, 'GOOD', SYSTIMESTAMP);
