INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '귀엽고 맛있고 아가자기하고 완전 취향저격 카페 발견이요💖 인형의 집같은 감성적이고 재미있는 인테리어에 디저트들이랑 소품도 하나같이 다 귀여워서 눈이 즐거워져요! 비주얼도 예쁜데 맛도 넘 좋아서 더 좋더라구요!! 케이크랑 쿠키, 쿠키슈 다 귀여운데 넘 맛있구요. 생각보다 많이 달지 않고 커피랑 궁합이 좋아요😋 쿠키슈 안에 크림이 잔뜩 있어서 진짜 맛있었어요!! 케이크도 넘 예뻐서 나중에 레터링 주문제작 해봐야겠어요🥰', 82, 17, 'GOOD', SYSTIMESTAMP);
