INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '너무 귀여워서 선물하기 좋은 케이크입니다. 당일 예약도 되고, 케익 종류와 레터링까지 선택 가능해서 너무 좋아요~ 생각보다 크기가 작긴해서 잘 고려해서 주문하셔야 할 것 같아요. 저는 블루베리 크림치즈 케이크로 주문했는데 안에 블루베리가 들어 있어서 괜찮았어요. 선물로 완전 추천합니다.👍', 42, 1, 'GOOD', SYSTIMESTAMP);
