INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '너무너무 아기자기 예쁜 상수역 카페! 인테리어도 귀여운데, 맛도 장난아니에요 👍🏻👍🏻 쿠키슈 먹고 맛있어서 쿠키 테이크아웃도 했다는 ㅎㅎ 아메리카노도 산미없는 딱 제스타일! 넘 잘먹었습니다아어', 111, 22, 'GOOD', SYSTIMESTAMP);
