INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '상수에갔는데요 이렇게 예쁜카페가 있었다니 실내도 넓고 천정도 높아서 시원시원한 시야가 좋은 동화속같은곳이였어요 너무 귀엽귀엽고  사랑스러운 디져트로 들어가서 정신못차리게 구경하고 주문했어요 저는 불루베리치즈 케익먹었는데 상상그이상으으로맛있었어요 그리고 곰돌이 쿠키 너무 예뻐서 모두다 사고싶었어요 쿠키도 맛있구요 다음에 선물할일도 있는데 꼭 해피베어데이 상수점에가서 사야겟어요 크리스마스 분위기로 너무 예뻤던 곳 재방문의사 백만번입니닷!!!!!!!♥*♥', 21, 6, 'GOOD', SYSTIMESTAMP);
