INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '케이크 픽업갔는데 너무 친절하셔서 감동 완전 받았어요 도시락 케이크 들고 멀리 간다고 하니까 신경써서 포장해주시고 친절하게 응대해주셔서 넘 좋았어요 받은 친구도 만족해서 뿌듯했어요 또 이용할 것 같아요 친절한 응대로 기분 좋게 픽업했어요 감사합니다!', 97, 26, 'GOOD', SYSTIMESTAMP);
