INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '귀여운 인테리어가 한 몫하는 곳 본점으로 갔는데 대관해줬다고 상수점으로 옴 새로 오픈해서 그런가 응대가 매끄럽지 않은 듯하다 아기자기한 인테리어와 귀여운 디저트 보는 맛이 큼', 30, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '크리스마스 케이크 큰건 남길거같아 도시락케이크 주문했어요. 너무 귀엽고 입짧은 두명이서 먹기에 좋아요 세명도 가능.. 초는 다른 곳에서 따로 주문한 거니 참고하세요 도시락케이크 말고 큰 케익도 다 너무 귀여웠어요', 108, 20, 'GOOD', SYSTIMESTAMP);
