INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '친구 생일이여서 주문했는데 이쁩니다 미니인데도 많이 작지않아서 괜찮은데 맛이.. 약간 저희 옛날에 케이크맛?ㅋㅋ 크림치즈인데 버터케이크맛이나요ㅋㅋㅋ 그래도 가격대비 괜찮아요 담엔 오레오로 주문해볼라구요', 60, 13, NULL, SYSTIMESTAMP);
