INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '받은 친구가 너무 좋아했어요!! 당일 케이크 급하게 알아봤는데 너무 예뻐서 사진 많이 찍었습니다! 사정생겨서 30분 늦었는데도 친절하게 케이크 전달해주셔서 진짜 죄송했는데 감사했습니다..!', 8, 5, 'GOOD', SYSTIMESTAMP);
