INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '진짜최고에요 ㅜㅜ당일에 생일케이크가 급햇는데 도시락말구 미니사이즈로도 잇어서 ㄴ좋앗어요!💝케이크일단넘귀엽고 예뿌구 맛도존마탱..얼그레이맛으루 햇는데 다들 먹고 머지이거왤케맛잇냐구 놀랫어요🤍🤍🤍픽업시간이 예정보다늦어졋는데 양해해주시고ㅜㅜ감사합니다!!!덕분에 친구생일파티 잘햇아용🎂✨✨', 40, 9, 'GOOD', SYSTIMESTAMP);
