INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '당일에 급하게 레터링케이크 찾다가 주문했는데 너무 친절하시고 시간도 예약시간보다 늦을 것 같다고 말씀드렸는데 흔쾌히 괜찮다고 하셧음 ㅠㅠ 진짜 맛도 좋고 디자인도 쵝오', 48, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '인테리어가 정말 예쁘고(인스타 감성) 사진이 잘 나올 듯합니다. 도시락케이크 당일 주문제작을 했는데 너무 작다보니 케이크 디자인 자체는 너무 예쁜데 레터링이 잘 읽히지 않는다는 단점이 있네요. 그리고 맛은 좋았어요. 만약 선물을 하실 계획이라면 도시락케이크보다는 더 큰 케이크를 하는 게 좋을 것 같습니다!', 50, 7, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '아기자기한 카페내부가 넘 이뻐요! 해피베어데이라는 이름처럼 곰돌이 천국이에요! 곰돌이 덕후들은 꼭꼭 가보세요! 레터링케이크도 넘 맛있어요! ❤️', 24, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '잠실롯백 지하 해피베어데이에서 휘낭시에랑 까눌레 자주 먹었는데 까눌레 이제 안나온다고하셔서 넘 슬펐습니다ㅠㅠ 까눌레 다시 나오길 기다릴게용🙏', 41, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '차 가지고는 가지 마세요...... 골목에 갇혀서 못나올 뻔 했어요 ㅠㅠ 케이크 특별한 날 하기 좋고 이쁘지만 얼그레이 케익은 얼그레이 잎이 겁나 많이 들어있어요 향은 많이 나서 좋은데 개인적으로 얼그레이 잎이 씹혀도 너무 많이 씹혀서 불호 입니다...', 84, 14, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '먹기에 아까울 비쥬얼이예요. 생크림은 아니지만 일반 느끼한 크림이 아니어서 좋았고 쿠키슈는 종류별로 다 맛있었어요. 도식락사이즈케이크는 선물용으로도 부담없어서 좋으네요.', 257, 94, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '케이크가 너무 귀여워요 근데 예약한 사진과는 색이 달라서 다른 케이크인 줄 알았네요 공지를 해주시면 좋을 것 같아요 그리고 예전에 주문했을 때 오레오 케이크가 정말 맛있어서 다시 한 번 시킨건데 요번은 너무 실망했어요 레드벨벳은 한 입 먹었을 때 뭐지? 싶을 정도로 이도 저도 아닌 맛이었어요 시트 밑 부분은 타서 색도 갈색이었고 그거 때문인지 케익을 먹는데 탄맛, 쓴맛만 나고 크림들은 너무 짰어요 달콤함이 하나도 없는 케이크라 정말로 실망했어요 덕분에 생일인 분에게 원래 이런 레터링 케이크는 맛을 포기해야 한다는 말만 들었네요 정말 급하게 주문 케이크 필요할 때 좋은 곳 말고는 장점이 없을 것 같네요', 62, 17, 'BAD', SYSTIMESTAMP);
