INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '당일 예약이 된다는 점이 가장 좋았어요! 도시락 케익 맛 없던 적이 많은데 초코오레오 맛이라 맛도 있었습니다~~ 다음에는 더 큰 사이즈 이용 의향도!', 11, 1, 'GOOD', SYSTIMESTAMP);
