INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '화려하고 예쁜 케이크라서 친구들 반응이 정말 좋았어요!!! 심지어 꾸덕한 오레오맛이라 다들 미친듯이 먹었어요! 다음에 꼭 또 주문할게요:)', 87, 11, 'GOOD', SYSTIMESTAMP);
