INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '당일 레터링 가능한 곳 찾다가 주문하게 된 동생 합격 케이크! 글씨 뭉게지지 않게 신경 써달라고 했는데 신경써주신 것 같아 아주 만족했어요😚 귀여운 초도 덤으로 구매하고 아주 기분 좋은 선물 할 수 있어서 너무 기분 좋았습니당', 52, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '먹어본 레터링케익 중에 젤 맛있어요!!! 보통 레터링케익은 예쁜거지 맛있진 않았는데 얼그레이 케익 맛도 찐하고 진짜 부드럽고 맛있어요!!! 당일 예약해서 받을수 있는거도 넘 좋고 디자인도 넘 깜찍해요 선물용으로 자주 구매할듯용', 91, 22, 'GOOD', SYSTIMESTAMP);
