INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '케이크 주문제작했는데 주문제작해본 것 중에 가장 저렴하고 퀄리티가 좋았어요 디자인 선택에 제한이 있었지만 그 이상으로 퀄리티가 좋았습니당 맛도 좋아요!', 129, 20, 'GOOD', SYSTIMESTAMP);
