INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '도시락케이크 주문제작 했는데 글씨도 선명하게 써주시고 케이크도 너무 이뻣어요 ㅎㅎ 케이크 맛은 기대 안했는데 솔직히 다른곳보다 맛있어서 주문제작이 아니여도 그냥 사 먹고 싶더라구요 ㅎㅎㅎ 다음에 또 주문제작 필요할 때 방문할 의향 있습니당', 72, 13, 'GOOD', SYSTIMESTAMP);
