INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '먼저 당일 주문이 가능해서 너무 좋았고 ㅠㅠ 무엇보다 넘뮤귀여워요 ㅠㅠㅠ 퀄리티 무슨일...?! 가게에 예쁜초도 팔고 여러모로 완전 만족합니다 ❤️', 18, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '다른것보다 케익 하나 예약하려고 사장님이랑 디엠이나 카톡으로 씨름하지 않고 네이버 예약으로 간편하게 주문할수 있어 너무 좋고 편리합니다. 앞으로도 합정에서 케익 살일 있으면 꼭 여기서 하려구요… 케익 픽업은 상수점인데 네이버지도에 검색하면 합정점이 제일 위에 뜨니까 픽업하시는 분들 꼭 상수점으로 찍고 가셔용 ㅎㅎ 케익 너무 귀엽고 당일도 예약 가능해서 정말 좋습니다~', 16, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '매장은 시작하신지 얼마 되지 않아서 물건들이 놓여져 있었지만 당일에 도시락 케이크를 준비하기에 너무 좋습니다 친구가 맛있고 귀엽다구 하네요! 그런데 매장에 큰 푸들이를 풀어놓으셨는데 푸들이 짖어대구 다가와서 무서웠어요 ㅠㅠ 동물을 싫어하거나 무서워 하는 사람은 좀 그럴듯요 ㅠ 사장님께서 푸들이 고객에게 다가오지 못하게 다른곳에 두셔야 할 거 같아요 다른건 다 만족스럽습니다~', 320, 73, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '당일 주문이 가능해서 좋았어요. 레터링 케이크 한번 예약할려면 주문하는게 복잡하고 어려웠는데 네이버 예약으로 간편하게 주문할 수 있어서 좋았어요! 선물 받은 친구도 좋아했어요<', 90, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '돈이 아깝지않게 도시락케이크의 쿠키앤크림맛이 좋았구요, 시중에 파는 케익보다 더 폭신폭신해서 남자친구가 엄청 좋아했어요 ㅋㅋㅋ 디자인도 귀여우니 깔끔하고 주문제작도 간단하게 남친 이니셜로 하니깐 깔끔했숩니당 담에 엄마생일도 축하하러 올게요 ㅋㅋ 땡큐합니다.', 21, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '저번에 도시락케이크 예약했는데 만족해서 또 예약했습니다. 이번엔 미니케이크로 구매했는데 크니까 더 귀엽네요🐥 가격도 괜찮고, 예약도 하루 전에 가능하니 너무 좋네요', 35, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '너무 귀엽고 너무너무 이쁜데다가 한참 전에 예약 하지 않아도 가능해서 좋아요. 다만 비가 폭우같았는데 ㅜ 흔들림에 예민한 케이크라고 비닐봉투같은게 없어서 아쉽습니다 ㅠㅜ 물론 디자인 케이크라 흔들림에 주의해야하긴 하지만 조심히 들고 걷는 정도의 흔들림에 망가지진 않으니까 비닐봉투 옵션은 있었으면 좋겠어요~! 상자가 비에 젖어 테두리부분은 다 축축해져서 찢어지진않을까 엄청 걱정하며 들고갔답니다 ㅜ', 13, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '리뷰에 글씨 뭉치고 중심 안 맞는 사진이 너무 많아서 당황했어요 분명 인스타 21년도 도시락 케이크 사진은 글씨도 예쁘고 깔끔한 사진인데 최근 리뷰는 글씨가 너무 뭉친 거 같더라구요 주문 고민하다가 글씨 좀 신경써서 부탁드린다고 남겼는데 리뷰처럼 중심이 맞지 않고 삐뚤하거나 심하게 뭉치고 하지는 않아서 괜찮았어요 D가 좀 O 처럼 보이기는 했지만 깔끔해서 상관없었네요 데코는 좀 군데군데 떨어진 거 같긴 했어요 매장에서 찍은 사진도 구슬 같은게 떨어진 거 보면 들고오면서 떨어진 거 같지는 않아요 크림은 버터크림이라 조금 느끼한 맛이긴 하지만 안에 오레오 크림은 맛있었습니다 픽업 도와주시는 직원분은 친절한 느낌은 아니었어요 퇴근 전이라 그러신 건지 :(', 46, 1, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '3월 22일에 주문했었는데 조금 늦은 리뷰로 올립니다..! 오전에 인스타그램 통해서 당일케이크로 주문하고 오후에 픽업했는데 너무 맛있게 잘 만들어주셨어요:) 덕분에 친구들이랑 좋은 추억 남겼습니다 감사합니다💕', 85, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '케이크가 너무너무 귀여웠지만 현장에서 딱 받아서 확인했을때 글씨랑 곰돌이?랑 데코들이 조금 뭉게진감이있었어요 그리고 어려운 요청사항은 아니였는데 안들어주셔서 조금 아쉬웠습니다 색감이나 케이크 자체는 너무 러블리하고 귀여웠어요~', 25, 8, NULL, SYSTIMESTAMP);
