INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '비주얼도 귀엽고 레터링도 마음에 들게 해주시고 예약/픽업이 편해서 너무 좋은거 같아요! 선물 받은 사람도 너무 귀엽다고 만족했어요 >.<', 35, 4, 'GOOD', SYSTIMESTAMP);
