INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '(레터링 이름은 가렸어요!) 양해를 구하고 픽업시간 늦췄는데, 친절하게 늦춰주셔서 너무 좋았어요!! 케익도 너무 맛있고 귀여워요!! 케익받은 친구가 엄청 좋아했어요ㅎㅎ 다음에도 친구생일에 방문할 의사있습니다!!😊', 93, 19, 'GOOD', SYSTIMESTAMP);
