INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '케이크 왕기여워서 인스타에서 보자마자 예약했어요! 진챠...최고예요 생각보단 작은데 원래 도시락케이크가 작고 귀여운게 특징이라 보고서도 우와너무귀엽자나!!했답니다.. 시간변경도 친절하게 일곱시 전까지 오면 된다고 하셔서 편하게 갔습니당 받는 사람이 아주아주 좋아했어요♡̷̷∘°', 48, 2, 'GOOD', SYSTIMESTAMP);
