INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '친구생일마다 매번 잘 이용하고있어요 보통 프렌차이즈에서 사면 케이크가 남거나 들고 다니기 힘든데 여기는 맛도 있고 디자인도 귀여워서 가성비가 훨씬 좋아요', 17, 10, 'GOOD', SYSTIMESTAMP);
