INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '도시락케이크 주문했어요 친구 (이름은 가릴게요) 생일 케이크로 주문했고 받은 친구가 너무 좋아해서 너무 만족스러워요 위에 이름은 크림치즈 같고 시트는 오레오입니다 맛도 비주얼도 짱!', 12, 5, 'GOOD', SYSTIMESTAMP);
