INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '일이 생겨 급하게 시간을 바꾸게 되었는데 흔쾌히 들어주셔서 감사합니다 ㅠㅠ 바로 선물해서 사진은 못 찍었는데 지인이 케이크 받고 너무 예쁘다며 좋아하고 맛있었다며 폭풍 칭찬해줬어요 :)', 17, 6, 'GOOD', SYSTIMESTAMP);
