INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '예뻤어요~ 선물로 준거라 저는 따로 맛을 보지 않았는데 워낙 얼그레이 케이크를 좋아하는 친구라 얼그레이로 주문했었습니다. 그런데 친구가 맛있는데 오레오 맛으로 주문했냐고 하더라구요~ 아마 바뀐듯 싶습니다....! 그것 외에는 괜찮았습니다', 73, 17, NULL, SYSTIMESTAMP);
