INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '디자인도 너무 예쁘고 아기자기해요 카페도 이용해봐도 좋을 것 같아요 다만 픽업은 픽업만 딱 하고 가게 해서 호다닥 나와야하네요 ..!', 19, 0, 'GOOD', SYSTIMESTAMP);
