INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '레터링 케이크 여러번 의뢰했었는데 이런곳 처음이에요 ㅋㅋㅋㅋ여러모로 너무너무 불편했습니다.서비스 부분에서 개선이 될 필요성이 있다고 생각이 듭니다.', 43, 10, 'BAD', SYSTIMESTAMP);
