INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '해피베어데이 상수점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '서비스면에서 실망하였습니다. 저는 상수점으로 7시30분에 예약을 하였는데, 따로 설명 및 사과도 없이 합정점으로 픽업 오라고 통보하셔서 당황스러웠어요;; 이후에 답장도 없으셔서 어쩔수 없이 합정점으로 갔는데 기분이 좋진 않네요. 케이크로 파티는 잘 마무리 했습니다.', 34, 5, 'BAD', SYSTIMESTAMP);
