INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '녹턴'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '밖은 푸릇하고 안은 우드톤이라 녹턴 이름 잘 지은 것 같아요 ㅎㅎ 예쁘고 작업하기 좋은 카페.. 티라미수 품절이라 못 먹었지만 담엔 디저트도 먹어보려구용! +결국 브라우니 시켜먹었는데 종맛 ㅎ 위에 초코코팅 맛있고 아이스크림도 맛있능거 쓰시는듯 해용 ㅎㅎ', 16, 2, 'GOOD', SYSTIMESTAMP);
