INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '녹턴'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '새로 생긴 카페인데, 공간이 넓고 인테리어도 매우 멋집니다. 밤에는 바로 운영된다고 들었는데, 와서 위스키나 칵테일 한잔 마시기도 정말 좋을 것 같은 분위기에요! 디저트랑 음료도 맛있어서 데이트 하기에도, 친구랑 오기에도 좋은 장소입니다 :)', 112, 19, 'GOOD', SYSTIMESTAMP);
