INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '녹턴'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '고급스러운 느낌이고 인테리어에 힘을 좀 쓴 느낌인데 감각적이고 편안해요 레드블랙썸머라는 특별한 메뉴도 있어서 시켜봤는데 상큼하고 맛있네요☺️', 2, 10, 'GOOD', SYSTIMESTAMP);
