INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '녹턴'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '새로 생긴 카페가 있길래 잠시 책읽으려고 왔어요~ 오후 7시까지는 카페, 그 이후엔 위스키바로 운영된다고 하네요 :) 라떼 고소하니 맛있고, 혼자앉는 바 좌석과, 테이블좌석이 골고루 있어서 혼자여도 부담스럽지 않아서 좋았어요 디저트 종류도 케이크, 브라우니, 크로와상, 휘낭시에 있었고 담엔 저녁에도 와보고싶어요', 450, 50, 'GOOD', SYSTIMESTAMP);
