INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '녹턴'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '얘기하기 좋아요. 약한산미와 고소한 맛이 잘 어우러져있어서 커피도 맛있네요. 디카페인도 있어서 선택폭이 넓어 좋아요. 주말인데 너무 번잡스럽지않고 편안한 분위기네요.', 72, 14, 'GOOD', SYSTIMESTAMP);
