INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '녹턴'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '합정 신상 카페라 해서 방문 했어요 ! 주말에 핫플이네요 ㅎㅎ 일찍 와야 할것 같아용:) 인테리어가 좋고 무드가 좋아요 ! 바깥 뷰가 보여서 리프레쉬 되는 기분이네요 ㅎㅎ', 74, 11, 'GOOD', SYSTIMESTAMP);
