INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '녹턴'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '분위기가 정말 좋은 카페겸 bar입니다. 커피도 맛있고 쾌적하고 음악도 좋고 깔끔하고 고급져요. 저녁에 술 한잔 하러 오고 싶어지는 곳. 시원해지면 야외에 앉아서 차를 마시러 와야겠어요', 37, 2, 'GOOD', SYSTIMESTAMP);
