INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '녹턴'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '생긴지 진짜 얼마 안된 따끈따끈한 카페가 있길래 방문해봤습니다! 바도 같이 해서 그런지 인테리어가 되게 팬시..?해서 ㅋㅋㅋ 놀랐어요.. 신박한 음료 메뉴들이 많아보이더라구요! 입소문 타기 전에 얼른 자주 와야겠어요 ㅎㅎ', 10, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '녹턴'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '생각보다 좌석이 많은데 간격도 넓어서 너무 쾌적해요! 이 동네 놀러올 때 방문할 좋은 카페가 하나 더 생긴 것 같아서 기분 좋아요! 😊', 10, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '카와이가 방문 6번째! 지금 카와이가는 마츠리 🎇이벤트 중이랍니다! 마츠리 느낌나는 내부 인테리어와 추가된 메뉴들 못참고 몇개 시켰는데 야끼소바 완전 맛도리!! 추천👍 당고도 진짜 일본에 그 소스에 졸여 구운 숯불향 나는 당고였답니다!!🍡 다들 카와이가 오셔서 진정한 마츠리를 즐겨보세요🎶', 23, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '홍대 오면 무조건 가야 되는 필수 코스입니다! 국내 메이드카페 중 단연 탑으로 꼽는 곳입니다 귀엽고 재미있고 흥 많은 메이드 분들께서 최고의 텐션과 입담, 서비스로 맞이해 주십니다 매번 정말 즐거운 경험입니다 재방문인데 더욱 좋아진 것 같네요 ^^ 다시 올 의향 만땅임다 ㅋ', 77, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '항상 느끼는거지만 여긴 컨ᩚ텐츠가 정말 다양해서 재밌어요👍 항상 올때마다 너무 재밌고 귀엽고 이쁜 메이드집사님들이 가득한 곳이에요❤️❤️', 87, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '오랜만에 왔는데 여전히 너무 좋습니다!! 신입분들도 많이 오시고 오랜만에 보는 분들도 있어서 너무 반갑고 좋았어요(ฅ’ω’ฅ)♥ 새로운 메뉴도 생기고 재밌게 즐겼습니당🩵', 5, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '오랜만에 친구랑 방문했어요! 마츠리 때 못 가서 너무 아쉬웠는데 남아있는 메뉴가 있어서 맛있게 먹었습니다💗 새로운 메이드님이랑 집사님도 보고 대화도 많이 해서 재밌었어요! 다음에 또 올게요💕', 35, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '마츠리의 즐거움이 아직도 느껴질정도로 즐거웠어요 거기에 다양한 음료와 먹을거리가 있고 또 친절한 집사 메이드 분들께서 함께하셔서 더 좋았던 것 같아요 다음에도 또 들를거에요 루비루비꿍❤️', 27, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '오늘은 제가 처음으로 이곳에 방문한 날로부터 1년이 지난 날이자, 루비엘님을 처음 뵌지도 1년이 된 기념비적인 날이라 찾아오게 되었어요 감회가 남다르고 너무 좋았어요(〃´𓎟`〃)🩷🪽 앞으로도 승승장구하길 바라며 잘 부탁드립니다(*˙˘˙)♡', 55, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '오늘도 카와이에서의 행복하게 해주시고 편안하게 해주셔서 감사드립니다:) 늘 카와이는 즐거운 기억들을 만들어주셔서 좋네요 카와이가의 놀러오신다면 메이드분들과 집사분들이 계셔주시기 때문에 감사드려요!', 23, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '나타 메이드님의 타로...! 너무 재밌었습니다 진짜 꼭 해보세요... 너무 다정하시구 쏙쏙 들어맞음...!  그리고 오므라이스 넘 맛있었습니다 ㅎㅎ', 30, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '카와이 메이드 카페는 늘 즐겁게 해주고 편안한 장소로 만들어주어서 너무 좋습니다! 행복을 주는 장소가 되어주고 늘 배려해주시는 메이드 분들 집사분들과 함께여서 더욱 오래 편하게 있을수 있는 장소인것 같습니다!', 274, 77, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '카와이는 늘 즐겁게 해주셔서 감사드립니다 너무 행복해요:) 카와이의 장점은 편한 자리와 분위기 맛있는 음식들도 있는게 너무 좋아요 주방에 계신 분이 아주 카와이하다고 생각하기 때문에 메이드분들 집사분들과 함께 즐거운 시간을 보내고싶으시다면 추천드립니다:)!', 0, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '카와이가 늘 감사드립니다! 항상 이곳에 있으면 너무 편하고 기쁩니다....저를 행복하게 해주시는 메이드분들 집사분들이 계시기에 저는 오늘도 하루를 살아갈 힘들 얻어가는 것 같습니다! 늘 감사드리고 카와이가 더욱 사람의 온기로 가득한 휼륭한 저택이 되길바랍니다:)', 22, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '오늘 오랜만에 방문을 하였는데, 여름 마츠리 컨셉도 좋고 주문한 음식, 음료, 술 다 맛있게 먹었습니다! 오랜만에 뵙는 집사님들 메이드님들도 뵐 수 있어 좋았습니다!', 42, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '카와이는 항상 즐겁게 해주시고 늘 감사드리고 있습니다! 항상 새로운 경험을 하게 해주시고 행복하게 만드는 분위기를 형성되게 해주시는 카와이가의 집사 메이드 분들께는 너무 감사드리고 있습니다! 정말 최고의 장소입니다!', 4, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '카와이는 언제든 즐겁네요 감사합니다:) 늘 감사할 수 있게 해주셔서 좋아요 늘 카와이가와 함께할 수 있는 영광을 주셔서 감사드립니다! 카와이의 장점은 항상 친절함! 그리고 카와이만 느낄 수 있는 좋은 분위기가 있다고 생각되니 오실 분들은 언제나 추천해봅니다!', 23, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '카와이는 늘 좋아요~! 항상 가는게 즐겁고 행복한 시간을 보낼 수 있도록 해줘서 감사할 따름입니다! 카와이에 대한 즐거운 시간들은 모두 메이드 분들과 집사분들의 최고의 대접을 받기 때문이라고 생각합니다:)', 16, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '이번에 카와이에서 새롭고 재미있는 이벤트를 열었습니다 여름을 기념해서 마츠리(축제)를 즐길 수 있도록 인테리어를 꾸몄고 색다른 컨텐츠와 높은 퀄리티의 체키를 받아보실 수 있고 많은 음식이 생겨서 꼭 한번 드셔보시면 좋겠습니다', 41, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '항상 최고의 메이드 카페로 있어주셔서 감사합니다! 너무 좋은 대우를 해주셔서 감사드릴 따름입니다 늘 최고이니 걱정마시고 여유롭게 오셔도 될듯 합니다! 카와이는 항상 편안하고 좋은 장소로 남아있어주길:)', 57, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '오늘도 즐거운 카와이 입니다 사진의 음료는 루비엘 집사님의 시크릿 칵테일입니다 다양한 버전중에서도 가장 도수 높게 만든 술이어서 천천히 마시는 중입니다 원래는 원샷용 챌린지 술이라는데 술이 세지못해 암타깝지만 원샷챌린지는 디음기회에 오늘도 침절하게 반겨주는 메이드님들과 집사님들 덕에 매우 즐거운시간 보냈습니다', 88, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '늘 카와이에서 감사하며 시간을 보내고 있습니다! 이렇게 친절한 대접을 받으며 메이드 분들 집사분들과 함께할 수 있다니 정말 행복한 시간들이고 많은 추억들을 쌓을 수 있는 장소여서 기쁘고 행복한 장소입니다!', 36, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '오늘 친한동생이랑 같이 처음오게됐는데 처음에 주문외울때까진 너무 창피하면서도 새롭고 재밌었는데 캐리커쳐 그려주면서 같이 대화하는데 너무 편안하고 즐겁더라구요 다음에 또 방문할 의사있습니다 너무 즐기다 갑니닷😆⭐️✨', 17, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '메이드카페는 처음와봤는데 집사분들이랑 메이드 분들 다 너무 귀여우십니당….🤤🤤🥺 체키라는 것도 처음 찍어봤는데 정성어린 편지에 감동받았어요 🩷 다른 친구들이랑 또 올게요 !!!!!!!! 야호', 0, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '오늘은 메이드복을입고 최애와 함께 인생네컷을 찍고왔어요 마츠리 인테리어도 컨텐츠들도 너무 좋았는데 특히 당고, 야키소바가 정말 맛있었어요( ¤̴̶̷̤́ ‧̫̮ ¤̴̶̷̤̀ )❤🪽 궁금하신 분들은 마츠리가 마치기전에 어서 오셔서 즐겨주신다면 좋을것 같아요!! 오늘도 감사했습니다!(〃´𓎟`〃)🌸', 49, 7, 'GOOD', SYSTIMESTAMP);
