INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '추적추적 비가 오는 오늘도 카와이가 5번째 방문!! 오늘도 밝은 인사와 ❤️ 함께 인사로 맞이해주시네요! 안내를 받고 들어가 앉았습니다!!!👍  다들 친절하셔서 진짜 에너지 빵빵😆 받아갑니다.  시그니처 칵테일과 맛있는 음식과 함께 즐기는 작은 힐링!! 이 곳에서는 칵테일이랑 다양한 음식들을 팔고있어요 좌석도 완전. 편합니다!!👍 다들 놀러오세요!!', 58, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '카와이가 항상 최고랍니다:) 늘 너무 감사드리고 갈때마다 친절히 대해주시는 메이드 집사분들 덕분에 즐겁게 즐기고  갈수 있게 됩니다:)! 카와이가에 방문하신다면 꼭 얼그레이 밀크티를 드셔보세요 명물이랍니다><☆', 75, 11, 'GOOD', SYSTIMESTAMP);
