INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '색다른 이색체험하러 와봤는데 생각보다 너무 재밌었어요! 음료말고도 칵테일도 시켜봤는데 좋았고 집사분과 메이드님들 라이브도 해주시고 잘 놀다갑니다☺️', 68, 11, 'GOOD', SYSTIMESTAMP);
