INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '친절하고 재미있는 집사 메이드가 있어서 좋았어요 다양한 음료 음식들도 많아서 좋았어요 앞으로도 자주 오고 싶어요 또봐요오 루비루비꿍❤️', 31, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '이색 카페 중 최고라고 생각됩니다! 메이드 분과 집사분들이 함께계셔서 취향에 맞춰 즐기실 수도 있고 맛있는 음식들과 음료들도 있으니 원하시는 대로 즐기시면 되는 자유로운 곳입니다!', 32, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '마츠리가 굉장히 즐겁고 재미있어요 친절한 집사와 메이드와 함께 이야기할 수 있어서 좋았어요 먹을거리도 마실거리도 많아서 좋았아요 또 오고 싶어요 루비루비꿍❤️', 24, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '메이드집사님들의 포토카드가 리뉴얼되었어요! 다른 사진을 보니 너무 다들 이쁘고 사복입은 모습을 보니 새로웠어요! 포토카드 퀄ᩚ도 더 너무 좋아져서 구경하는 재미가있었어용', 12, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '이런 장소가 존재한다는게 믿기지 않을 정도로 각 메이드와 집사들의 캐릭터성이 확실함과 동시에 친절함을 겸비해서 앉아만 있어도 편하고 즐거운 곳. 하지만 컨텐츠와 함께라면 더 재밌는게 말안됨', 74, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '마츠리가 즐거워요 친절한 집사 메이드들과 함께 이야기도 할 수 있고 다양한 음식과 음료들을 먹어볼 수 있어서 더 좋았어요 앞으로도 자주 올게요 루비루비꿍❤️', 45, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '냥냥 카와이 오늘은 다같이 보드게임을 즐겼어요 !! 너무너무 즐거웠습니다 벌칙도 걸면서 하니까 더 재미있고 좋았어요 ㉪㉪ 다음에도 컨텐츠 또 시키고 싶어요 !', 31, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '아카가 귀엽고 이쁘고 착하고 저점탈출을 해서 고점이 되길 바라는 1일차 입니다 음료도 다 맛있고 분위기도 좋고 편안하게 해줘서 좋습니다 ㅎ', 102, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '오늘도 너무 즐거웠어요 ! 귀여운 곰돌이 같은 메이드가 있더라구요 할리갈리 내기도 즐거웠습니다 애교내기.. 저는 걸리고 싶지 않지만 또 하고 싶네요!', 121, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '오늘 처음오신 집사님 너무 멋있었고 에이든집사님 잘생겼고 피로집사님도 잘생기고 마술계속 보여주시는게 너무 귀여우셔요 나타님 타로도 너무재밌고 엘프님이라 너무이쁘고 아토님 오늘 완전 카ᩚ드켑터체리에 사쿠라처럼 너무귀엽고 이뻤어요 진짜 쵸카와이☆*:.｡. o(≧▽≦)o .｡.:*☆주방요정 모아님 멀리서 지켜보기만했지만 역시 너무귀여우세요 소동물요정님이 고양이귀라니...(*≧∀≦*)', 25, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '우오 이것이 마츠리군요 새 음료와 음식들도 맛있고 다양한 것 같아요 집사 메이드분들도 복장도 바뀌었고 더 재미있어요 앞으로 더 자주 오고 싶어요 루비루비꿍❤️', 3, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '8월동안 마츠리 이벤트 진행중인 카와이!! 특별한 메뉴들이 많아져서 좋았어요ㅎ 특히 당고랑 키리모찌가 정말 맛있었어요 또 올게요~!', 24, 3, 'GOOD', SYSTIMESTAMP);
