INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '사실 혼자 가서 조금.. 부끄러웠는데 하나도 안부끄럽게 다가와서 계속 다들 말 걸어주시고.. 집사님들이나 메이드분들 다 너무 예쁘고 착하셔요… 분위기도 진짜 좋고 메뉴도 다 맛있고 비쥬얼도 너무 예뻐요.. 밥먹고 있는데 안심심하게 마술도 해주시고.. 재밌습니다.. 한번 와보세요..', 18, 4, 'GOOD', SYSTIMESTAMP);
