INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '오늘 촬영이 있어서 좋은 구경 하고 가서 재밌었어요 메이드집사님들도 다 너무 친절하시고 촬영에만 너무 집중하시는게 아니라 모두에게 응대를 해주셔서 너무좋았어요', 82, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '카와이의 새벽을 또 즐기러 왔습니다!!! 다들 피치트리+밀키스 조합 드셔보세요. 레전두존맛탱. 오늘도 즐겁고 행복한 카와이 방문이었습니다!', 63, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '단순한 컨셉 카페가 아니라, 디저트도 굉장히 신경 써서 만든 느낌이었어요. 케이크 정말 맛있습니다! 생각보다 너무 만족스러워서 다음에 또 오고 싶어요. 친구들도 데리고 와야겠습니다', 24, 4, 'GOOD', SYSTIMESTAMP);
