INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '친절하고 마음씨 좋은 집사 메이드 분들과 이야기할 수 있어서 좋았어요 맛있는 음료들도 다양한 것도 좋았어요 앞으로도 자주 와서 즐길 생각이에요 자주 올게요 루비루비꿍❤️', 19, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '친절하고 좋은 모습으로 응하시는 집사 메이드분들이 자리하셔서 좋았어요 음료도 음식도 다양하고 맛있어서 좋았어요 앞으로 더 자주 오고 싶어요 루비루비꿍❤️', 12, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '카와이의 야간타임은 언제나 즐겁습니다!! 맛있는 칵테일과 안주들, 친절하고 재미있는 메이드님 집사님들과 새벽을 보내서 좋았네용 또 올게요!', 43, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '카와이 홍대점에 갔다왔어요. 메이드 중에 특히 아토님이 예쁘고 친절하게 상대해주셔서 좋았어요. 다른 분들에게도 추천하고 싶어요!! 상수역 근처라서 주변에 있는 분들께 추천하고 싶어요.', 53, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '모아님이 귀엽고 이쁘고 친절하구요 아이스크림이 맛있어요 이거 쓰면 아이스크림 준대요 맞아요 그래서 분량채우는 중이에요 어..또.. 칵테일이랑 위스키 맛집이에요 와서 바틀시키는걸 추천해요', 22, 8, 'GOOD', SYSTIMESTAMP);
