INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '저번에 키리코 님이랑 보구 키리코 님 보구 싶어서 방문했어요! 넘넘 귀여운 키리코 님이 머리 땋아주시구 나타 님도 오늘 처음 봤는데 넘 예쁘셔서 눈이 행복해요 미서녀들은 언제나 옳다!!!! 루비엘 님두 넘 재미있으셔서 보면 항상 기분이 좋아져요 (*^^*)', 89, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '친절하고 따뜻한 집사 메이드분들과 즐겁게 이야기도 할 수 있고 음료도 음식도 다양하고 맛있어서 좋았어요 또 오고 싶을 정도로 좋았어요 앞으로도 자주 올게요 루비루비 못말리는 루비쨩❤️', 19, 4, NULL, SYSTIMESTAMP);
