INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '오늘 원래 올 계획 없다가 방문했는데 처음 보는 메이드 분도 있구 오길 잘했다는 생각만 들어요... 다들 왤케 귀엽구 예쁜 거지???? 행복하당 😍🩷', 64, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '친절한 메이드들 집사들과 함께 오늘도 즐겁게 즐겼습니다! 곧 등급이 올라갈 것 같은데 새로운 등급엔 어떤 특별 메뉴가 있을지 기대됩니다 또 올게요!', 46, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '처음 발을 들였을 때, 이 감각은 뭐랄까...... like, is the 귀족의 저택? 본인이 real 도련님이 된 느낌? 그러한 부르주아의 풍미를 느낄 수 있는 공들인 인테리어가 대단히 멋졌습니다. 그리고 김치가 들어간 오므라이스는 저같은 늙은이 입에도 술술 들어가는, 깔끔하고 감칠맛 터지는 좋은 맛이었습니다. 여기서 만큼은, 나도 real 중세의 북부대공....☆', 32, 3, 'GOOD', SYSTIMESTAMP);
