INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '오늘도 카와이 메이드카페 출석 완료!!! 오늘은 제이님 루비엘님 피로님 그리고 헤카님까지 계셨는데 다들 넘 예쁘고 잘생기고 친절하셔서 시간가는줄 몰랐어요 짱!!!', 57, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '친절한 집사 메이드가 함께 하시고 조명도 멋있어요 음료도 다양하고 할 것도 많아서 좋아요 다른 분들하고 같이 와도 더 좋을 것 같아요 앞으로도 자주 올게요 루비루비꿍❤️', 65, 14, 'GOOD', SYSTIMESTAMP);
