INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '오늘 처음으로 카와이 메이드카페 홍대점을 방문을 해보았는 데요 처음 방문하였지만 직원들이 굉장히 친절하고 대화를 많이 해서 재밌게 놀다가 가는 거 같습니다 기회가 된다면 꼭 다시 방문하고 싶습니다', 40, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '음료는 전반적으로 달달한 편입니다. 혹시나 단 음료를 좋아하지 않는다면 커피류로 찾아보시면 좋겠네요. 새벽 늦은 시간까지 영업을 해서 홍대 인근에서 놀다가 첫 차를 기다릴 겸해서 놀러오셔도 좋을 거라 생각해요. 처음 오시는 분들도 부담없이 시간 보내다가 가시기에 좋습니다. 조금의 항마력을 포기한다면 특별한 경험이 되리라 생각합니다.', 10, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '역시 카와이는 야간 ! 오늘도 저택 방문 재밌게 즐기다 갑니다 다들 너무 귀여우세요 냥냥 카와이 ~ 다음에도 와서 더 즐거운 시간 보내고 싶어요 !', 26, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '오늘은? 술 한잔 햇습니다........ 힘든 일이 있었거덩요..... 하지만? 그런 삶의 애환을 사르르 녹여줄? 스윗한 카와이의 음료라면? 당신도? 오늘 하루를 행복하게 보낼 수 있다. 양도 많이 줘서 얼큰하게 취할 수 있는 달콤한 카와이의 칵테일을 추천합니다. 마 한잔 해.', 34, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '카와이 두번째 방문…! 실수할까봐 머뭇거렸는데 메이드 분들이랑 집사 분들이 심심하지 않게 계속 오셔서 친절하게 이야기 걸어주시고 음식도 맛있어서 좋았어요!', 49, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '카와이 메이드카페는 상수역에서 아주 가까운데 메이드와 집사님들과 함께 재밌는 컨텐츠와 맛있는 음식, 좋은 분위기를 즐길 수 있는 곳입니다.', 21, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '오늘은 니코님 에이든님 로키님 츠키토님이 재미있고 즐거웠습니다 다들 체키도 잘꾸미시고 응대도 잘해주셔서 너무 행복한 하루였습니다', 13, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '오늘도 카와이 메캎이 카와이 했다.. 오늘은 집사님들 밖에 없긴 했는데 여집사님 남집사님들 골고루 있어서 신선하고 재밌네요 내일 또와야징', 35, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '친절하고 따뜻한 집사 메이드 분들하고 재미있게 이야기할 수 있어서 좋았어요 다양하고 맛있는 음료와 먹을것들이 있어서 더 좋았어요 루비루비꿍❤️💖', 17, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '귀여운 메이드님과 멋진 집사장들과 게임도 하고 맛있는 음료도 먹고 너무 좋았습니다 휴가 나온 날들중에 가장 최고인 것 같습니다', 12, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '냥냥 카와이 *^^* 오늘 히토님의 벌칙 댄스 라이브 너무 즐거웠어요 !! 머핀님 아카님 루비엘님 류크님도 너무 재밌고 좋았습니다', 29, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '오늘도 즐거운 카와이가~~ 오늘은 피로님 아토님 요미님 니코님 계셨는데 다들 넘 잘생기고 예쁘고 귀엽고 친절하셔서 오늘도 대만족!!! 조만간 또 옵니다', 6, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '친절하고 따뜻한 집사 메이드가 함께하셔서 더 좋았어요 다양하고 맛있는 음료 음식들도 있어서 좋았어요 즐거워서 또 오고 싶어요 자주 올게요 루비루비꿍❤️', 51, 14, NULL, SYSTIMESTAMP);
