INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '오늘 너무 재밌고 좋았어요 역시 카와이 최고 ! 의자가 정말 편안해서 깜빡 잠들 뻔 했지 뭐예요 ㉪㉪ 다들 너무 친절하고 멋졌습니다', 74, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '메이드 카페를 한 번쯤은 가봐야하지 하다가 홍대 온 김에 방문하게 되었어요 앞에 도착해서 초인종 누르니 얼마되지 않아 바로 집사님께서 마중나와 주시고 처음부터 다들 친절하게 맞이해주셔서 좋았어요! 메뉴들도 다 스토리텔링이 되어있어서 보는 맛이 있고 맛도 있어요- 무엇보다 집사님이 너무 예쁘셔요;)', 28, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '오늘의 게스트 시안님과 함께 아토 메이드님, 요미 메이드님, 히요 메이드님, 루비엘 집사님과 즐거운 대화와 컨텐츠 즐겼습니다! 언제나 감사드려요🥰🥰', 36, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '친구들이랑 메이드 카페에 가보고 싶어서 이곳저곳 찾다가 카와이 메이드 카페가 상당히 예쁜 분들도 많으시고 인테리어도 고급지길래 선택하여 예약 후 들렸습니다!🥰 들어서자마자 어서오세요 아가씨 하시며 인사해주시는 메이드, 집사 분들의 모습에 정말 귀족 아가씨가 된 기분을 느끼며 아름다운 내부로 들어섰어요!🩷 자리를 안내해주시고 앉아서 맛있는 음료수와 음식을 먹고 있으니 잔잔한 클래식과 친절한 대우까지 어우러져 기분이 좋아졌어요!!! 정말 너무 만족스럽습니다 다음에도 꼭 다시 들리고 싶어요🥺🥺🙏', 48, 9, 'GOOD', SYSTIMESTAMP);
