INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '다들 텐션이 장난 아니시더라구요너집사님, 메이드님들 다 너무재밌고 이쁘고 친절하셔서 너무 재밌게 잘 놀다가요 야간인데도 다들 지친기색하나없이 너무 밝으셔서 기분이 좋더라구요ㅎㅎㅎ', 26, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '친절한 집사 메이드분들과 함께 이야기도 할 수 있고 맛있는 음료수도 잔뜩 마셔볼 수 있고 시원하고 다 좋아요 담에도 또 오고 싶을 정도에요 감사합니다 루비루비꿍❤️', 43, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '너무 친절하시고 재미있어요! 메뉴도 맛있고 이벤트도 독특해서 처음 방문했는데도 즐겁게 놀았어요. 다들 너무 예브시고 잘생기셨어요. 특정한 코스튬이나 의상도 있고 이벤트 기간도 있어서 행복했어요.', 9, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '재방문으로 왔는데 여전히 메이드 집사님들이 전부 좋은 마인드로 임하시는 것 같아서 매장에 시간을 보내는 동안 즐겁게 보냈어요‼️🙇 정말 좋은 휴식시간이었습니다! 힐링되네요‼️', 0, 10, 'GOOD', SYSTIMESTAMP);
