INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '해카님 하고 아토님하고 피로님하고 리카님하고 이뻐요 ㅋㅋㅋㅋㅋ 마술도 너무 재밌었고 다들 친절하게 응대해주셔서 현생의 스트레스를 잘 해소하고 하고 갑니다', 72, 11, 'GOOD', SYSTIMESTAMP);
