INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '카와이 메이드카페는 상수역에서 아주 가까운 곳에 있는 곳입니다 집사님과 메이드님이 친절하게 대해 주시며 분위기 좋은 카페이니 다들 방문해 보십시오', 71, 18, 'GOOD', SYSTIMESTAMP);
