INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '우왕 이렇게 좋은 곳은 처음이에요 친절한 집사 메이드 분들과 함께 이야기도 할 수 있고 맛있는 음료들도 다양하게 있어서 굉장히 좋았어요 앞으로도 자주 올게요 루비루비꿍꿍❤️', 83, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '토요일 일정을 끝내고 방문한 일상.. 사진속 술은 제꺼는 아니고 방문증명컷 제이팝플리로 서브컬쳐쪽좋아하시면 좋아하실것같습니다 얼그레이 밀크티는 항상먹고있지만 맛있으니 강추합니다👍', 36, 2, 'GOOD', SYSTIMESTAMP);
