INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '아직 저택을 방문한적이 없는 미래의 아가씨 도련님들을 위해 소개를 드려봐요 여기 집사 메이드님들께서 한 순간도 놓침없이 재미 있는 이야기와 즐길거리로 채워주세요 여러분들도 꼭 찾아 즐겨보시길 바래요', 52, 16, NULL, SYSTIMESTAMP);
