INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '맛있는 음료를 마시고 가요 다양하게 음료들이 많아서 좋았어요 다른 분들하고 자주와서 있고 싶어요 집사 메이드분들도 쟈미있어요 좋았어요 또 올게요 루비루비꿍❤️', 88, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '진심 메카중 최강이라고 생각합니다 메카중에서도 돋보적인 컨셉과 출중한 외모의 메이드집사분들 그리고 카미응대!!!! 이런 카와이를 경험해보지 못하셨다면?!?!? 인생을 손해보고 있는것이라 할 수 있죠 당장 오시길', 78, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '오늘도 카와이에 방문했습니다 탐정삘나는 메이드복을 입으신 메이드님과 체키를 찍었는데 굉장히 정성스럽게 꾸며주셨습니다 오늘 추천할 메뉴는 집사/메이드가 구워주는 마시멜로입니다. PS.주방 요정님이 매우 귀엽습니다.', 25, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '친한 지인분이랑 놀러왔는데 집사, 메이드 분들 모두 친절하시고 응대도 잘해주셔서 너무 재밌게 즐겼어요. 컨텐츠도 다양하고 직원분들도 적극적으로 놀아주셔가지고 다시 방문하고 싶네요. 체키도 정말 잘 찍어주시고 잘 꾸며주십니다.', 81, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '이 정도로 일상적이고 편안한 분위기를 느낄 수 있는 곳은 별로 없다고 생각해요. 야간에 방문해도 편하고 친절하고 재미있게 이야기해주고 그저 GOAT', 43, 5, NULL, SYSTIMESTAMP);
