INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '입담이 재미있어요! 집사와 메이드분들이 진지하게 컨셉에 임해주십니다. 서브컬쳐에 관심있는 메이드 분이 있으셔서 서브컬쳐 관련 잡담도 잘 받아주셔요 컨셉도 다양합니다! 서브컬쳐쪽으로 만난 친구들 데려가기 좋은 데에요!', 33, 3, NULL, SYSTIMESTAMP);
