INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '메이드분들과 집사님들이 너무 친절하시고 재밌게 얘기나눠주셔서 즐거웠어요! 음료도 맛있어서 계속 마시게 되네요🥹 다음에 또 오고싶어요~!!!♥︎♥︎', 13, 3, 'GOOD', SYSTIMESTAMP);
