INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '메이드카페에서 처음으로 체키 찍었어요 ㅎㅎ 새벽이었는데 다들 대응도 좋으시고 친절하셔서 시간가는 줄 모르고 놀았습니다! 다음에 또 방문하고 싶어요!! 칵테일도 넘넘 맛있는... 🫶🏻', 80, 12, 'GOOD', SYSTIMESTAMP);
