INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '편안하고 메이드 집사님들이 너무재밌어요 졸업이신 루미메이드님 졸업 축하드리고 아쉬워요 이쁘고재밌으신분을 못보다니ㅠ 그래도 다른 귀엽고 이쁜 메이드집사님들이 많아서 또 갈거에요', 14, 8, 'GOOD', SYSTIMESTAMP);
