INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '평소에 혼자 이색적인 카페를 찾아가는걸 좋아하는 사람으로서 분위기가 넘 취향 저격이 었습니다 그리고 집사 님 메이드 님 모두 친절하시구 이야기 도 잘 통하고 모든것이 만족스러웠습니다  재방문 의사 100% 입니다~', 89, 18, 'GOOD', SYSTIMESTAMP);
