INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '카와이 메이드카페 방문했는데 직원분들이 모두 친절하고 응대가 인상적이었습니다. 테마도 잘 살려서 색다른 경험이었어요. 음식도 만족스럽고 좋은 추억이 되었습니다. 뺨 맞은 친구도 너무 만족스러워 하네요.', 20, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '언제나 집사와 메이드가 친근하고 친절해요 >< 인간적이어서 좋음여. 차분한 인테리어도 좋아요. 컨셉 다양한데 뚝딱이신분도 노련하신분도 있는데 개기여우심', 14, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '너무 재밌었어요 ! 인테리어 예뻐서 마음이 들고 음식이 맛있고 음료도 맛있었어요. 테디 집사님 유우 모아 메이드님 재밌으셨어요 !', 14, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '이색적인 경험! 홍대에서 일본 메이드카페 문화를 체험할 수 있는 유일한 곳. 분위기도 좋고, 직원들도 친절해서 만족스러웠어요.', 61, 12, 'GOOD', SYSTIMESTAMP);
