INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '"카와이 집사카페"는 애완동물 카페 중에서 특별히 고양이와 관련된 테마를 가진 곳으로, 일본의 "카와이" 문화에서 영감을 받은 디자인과 분위기를 자랑합니다. 이 카페는 고양이를 좋아하는 사람들에게 안락하고 귀여운 분위기를 제공합니다. 카페 내부는 고양이와 관련된 다양한 소품들로 꾸며져 있으며, 방문객들은 고양이들과 함께 편안하게 시간을 보낼 수 있습니다.', 144, 66, 'GOOD', SYSTIMESTAMP);
