INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '모모땅 게스트여서 와봤는데 인테리어나 집사,메이드분들 rp도 개성있고 재밌었습니다.특히 흰담비인 유리 메이드님과 날다람쥐 아리 메이드님이 친절하게 방치하지 않고 케어해주셔서 좋았어요', 37, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '정통 메이드 카페 생각하고 갔는데 이름처럼 카와이 했어요 여자 메이드분들은 컨셉이 동물 남자분들은 오래된 생명체인데 분홍머리 분은 무슨 컨셉인지 모르겠어요 그리고 LAHel 너무 유머러스한 개그 해주시고 연세가 다들 개성있었어요 그리고 가장 기억에 남는 표범 쿠션…!', 24, 6, NULL, SYSTIMESTAMP);
