INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '우리 메이드분들 집사분들 덕분에 크게 웃고 재밌게 즐기다 갑니다. 저와 아가씨는 이제 잠시 외출하고 오겠습니다. 다시 오면 그때도 잘 부탁 드립니다', 12, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메이드카페 집사카페 카와이 홍대점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '오늘도 너무 너무 행복한 하루...♡ 새로운 곳을 탐방해서 왔는데 생각보다 넘나 만족해씀미다 인테리어도 너무 예쁘고 특히 제이님이 진짜 너무 아름다우셔서 용안이 감사해써오 로키님 라이브 너무 잘해여!!! 다이너마이트 추천합니다 담에 또 올게용💖🙊', 72, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '합정에서  편하게 커피한잔 할수있고,  분위기좋은 카페를 찾았네요^^  초코크러플 너무 맛있었어요 ㅎㅎ  위에 올려져있는 아이스크림이 완전 👍 사장님이 친절하셔서 주문할때부터 기분이 좋았습니다 ^ 디저트 맛있고,  분위기 좋은 카페 찾는다면 방문해보세요~~ 😃', 82, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '합정 디저트 천국입니다.. 케이크랑 크로플이랑 종류가 엄청 많은데 진짜 다 맛있어보여서 한참 골랐어요.. 한참만에 고른 로투스 크로플도 맛있어서 추천드려요ㅎㅎ 그리고 내부가 예쁘게 잘 꾸며져있어서 그냥 카메라 들이대도 사진 기가맥히게 나옵니다,,,', 145, 91, 'GOOD', SYSTIMESTAMP);
