INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '크로플을 접어놓으니 넘 예쁘고 특이하더라구요! 크로플은 선물용으로도 좋아보여요. 오리랑 민트가 포인트로 인테리어 되어 있는데 문앞에 빼꼼오리도 넘 귀엽고ㅋㅋㅋㅋㅋ 아기자기한 맛으로 방문하기 좋은거 같아요. 크로플 겉에 슈가코팅 되어 있어서 까눌레 맛이랑 식감도 나용~ 외국인 직원분도 오래 일하신 것처럼 메뉴 잘 만드시고 센스있고 친절하셨습니다~!', 22, 9, 'GOOD', SYSTIMESTAMP);
