INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '친절하신 푸른눈의 매니저님이 반겨주시는 곳🩷 애플크로플 너무너무 맛있어요! 티와 피스타치오크림라떼는 시그니처라는 이름에 걸맞게 훌륭합니다! 위에 뜬 크림 먼저 먹고 커피랑 섞어마시면 풍부한 맛을 느낄 수 있어요😋 남자분들도 많이 오시는것같으니 편견없이 방문해보세요💙', 32, 7, 'GOOD', SYSTIMESTAMP);
