INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '빙수는 설빙에 비해서 양이 많은 편은 아니였어요! 다만 카카오 가루가 얼음 층층이 있었구, 우유빙수였어요! 크로플은 바삭하고 달달하구 진짜 최고였습니다ㅠㅠ 다음에 근처에 오면 또 방문하고 싶어요!!', 20, 9, 'GOOD', SYSTIMESTAMP);
