INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '맛있어 보이는 다양한 케이크, 크로플이 한 가득이에요ㅠㅠ 저땐 배불러서 못 먹었는데 다음엔 꼭 디저트 먹어보려고요! 매장이 너무 예쁘게 꾸며져있고, 같이 간 외국인친구도 너무 좋아했습니다ㅎ', 34, 2, 'GOOD', SYSTIMESTAMP);
