INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '합정 벚꽃길에 시선을 사로 잡는 민트색 카페 케이크 맛집 79파운야드 합정점! 🫶 입짧은햇님 디저트 맛집이라더니 진짜 케이크가 무겁고 알차고 다양하고 혼자 다해...❤️ 딥슬립 피스타치오와 함께 먹었는데 와 진짜 먹어 본 피스타치오 음료 중 원탑입니다 👍 피스타치오가 느끼할 수도 있는데 완전 깔끔 그 자체인데 디카페인이기까지,,, 이건 꼭 같이 드셔 보세요 😋', 7, 3, 'GOOD', SYSTIMESTAMP);
