INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '입짧은햇님 디저트맛집이라고해서 와이프랑 같이 왔는데 여자분들이 좋아할 키치한 인테리어네요 생딸기라떼랑 피스타치오크림라떼랑 블루베리치즈케이크 먹었는데 아주 맛있어요 와이프가 완전 반해버렸어요^^ 다행입니다^^', 3, 7, 'GOOD', SYSTIMESTAMP);
