INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '햇님 덕에 방문한 79파운야드 합정점. 맛있어보이는 케익이 다양해요~ 레몬타르트 달달하면서도 상큼하니 맛좋고 미숫가루 라떼는 고소하면서도 달달하니 좋아요~ 실내도 은근 넓어서 방문하기 좋은 카페랍니다!', 97, 22, 'GOOD', SYSTIMESTAMP);
