INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '🍓 크로플 겉은 바삭하면서 크림도 느끼하지 않고 딸기 향이 상큼 달콤하게 느껴 정말 맛있어요 음료수도  딸기 🍓 가득하네요 진심추천    직원분들도 너무 친절하세요 특히 외국인 직원분 👍 👍 진짜 친절하세요!!!', 31, 1, 'GOOD', SYSTIMESTAMP);
