INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '아기자기 동화속 공간의 느낌^^ 거기다 느껴지는 포근함^^ 더해볼까요? 와플 엄청 맛나네요^^ 여자가 오면 동화속 공주같은 남자가 오면 동화속 왕자같은 느낌으로 앉아 있을수 있는 예전에  충주인가에서 만났던 파운야드가 아늑한 느낌이라면 합정의 파운야드는 포근한 느낌~ 암튼 좋다^^', 57, 16, 'GOOD', SYSTIMESTAMP);
