INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '합정에서 진짜 맛도뤼 디저트 파는 곳 찾았어요..💕 크로플 한창 유행할 때 핫했던 79파운야드가 합정에도 있는 줄 몰랐는데, 디저트 선택지도 많구 무엇보다 두바이 크로플처럼 유행하는 음식도, 생딸기 케이크처럼 스테디하게 맛있는 시즌디저트도 있어서 너무 행복해요🫶🏻', 10, 3, 'GOOD', SYSTIMESTAMP);
