INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '홍대 얼라이브홀에서 양준일 콘서트하는데 대기중인 카페 너무 친절하고 좋아요. 양준일 노해도 하루종일 틀어주고 행복했네요. 고맙습니다.', 8, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '예쁜 인테리어에 맛있는 디저트가 가득해 데이트에 꼭 방문하면 좋을것같은 카페에요 얼그레이크림 타르트는 진한 홍차맛 크림에 레몬이 레이어드층으로 들어가 얼그레이크림와 레몬의 상큼한 조화가 넘 좋아요  요즘 핫하다는 두바이초코가 들어간 두바이초콜릿크로플은 정말 맛나요 꼭 드셔야 하는 디저트로 적극 추천드리구요 한손으로 잡고 한입에 깨물어 드셔야 진차 맛있게 드실수 있어요 바삭한 크로플도 정말 맛난데 두바이 초코의 피스타치오의 고소함과 초코의 달콤함이 넘 맛있게 섞여 남녀노소 다 좋아할 맛!!  아이들은 무조건 하나씩 먹게되는 마성의 맛이랍니다~^^  기본인 아메리카노도 정말 고급스럽고 호불호 갈리지않게  맛있구요 자몽주스도 상큼해서 달콤한 디저트와 정말 잘 어울리네요  상수역 합정역 맛집카페로 추천요!!', 69, 16, 'GOOD', SYSTIMESTAMP);
