INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '초딩 딸랑구랑 데이트하기 좋아요!!!>//<  서점 데이트 후 책읽으며 커피 한잔 하기도 좋고 분위기 대애애애박!! 진짜 오랜만에 기분 전환했네용!!><', 62, 16, NULL, SYSTIMESTAMP);
