INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '민트구스 홀케이크 기프티콘 (19,800원) 받아서 케이크랑 교환하려고 갔는데..... 대부분의 케이크는 단종이라고 하고, 오직 얼그도그만 (얼그레이맛) 구입 가능했음. 케이크 가격은 23,000원이라고 하며 추가 결제 요구. 선물받은 기프티콘으로 케이크 교환함에 있어 최악의 경험.', 40, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '완전 디저트맛집 인정입니당!! 크로플 진짜 맛있어요!!! 그리고 사과에이드 넘 예뻐버린답니당 ㅎㅎㅎ 가게도 너무 아기자기 하구 너무 예뻐요💓💓💓💓💓', 0, 7, 'GOOD', SYSTIMESTAMP);
