INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '커피맛미쳤음 한번만 먹어봐여 진짜 ! 커피가 맛있으면 디저트가 별로고 디저트가 맛있으면 커피는 그냥그런데 여기는 디저트도 커피도 너무너무 맛나 혼자서도 친구들이랑 데이트하러 또가구품', 27, 0, 'GOOD', SYSTIMESTAMP);
