INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '아기자기  넘 예쁜 카페예요  사장님의 섬세함이 느껴지는 인테리어에   찍는 사진마다 넘 예뻐요 음료와  크로플 케익류도 다 넘 맛있네요', 0, 10, 'GOOD', SYSTIMESTAMP);
