INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '로투스크로플과 무슨 찰떡 먹었는데 역시 79파운야드는 크로플 맛집이네요! 로투스잼하고 바삭한 크로플과 크림, 그리고 로투스크럼블까지 너무 맛있었어요! 친구랑 ‘와 진짜 맛있다’ 하면서 허겁지겁 3분 컷,,, 👍 (찰떡은 조심스레 비추드려요)', 64, 18, 'GOOD', SYSTIMESTAMP);
