INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '매장 분위기가 엄청 예뻐요! 디저트도 예쁜데 맛까지 있어서 다른 메뉴도 먹고싶게 하는 매력이 있습니다! 그리고 바스크 치즈 케이크 진짜 맛있어요 꼭 드세요🫨 커피를 잘 못먹어서 자몽 음료로 시켰는데 생자몽 들어가서 달달씁쓸하니 맛있었습니다!', 17, 6, 'GOOD', SYSTIMESTAMP);
