INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '외관이 민트색이길래 끌려서 들어왔더니 너무너무너무...이쁜 카페를 찾았습니다 ㅠㅠㅠㅠ 밖에서 먹을 수도 있고 내부 또한 꽃과 풀로 꾸며져있어서 화사하면서도 푸근한 인테리어 🍀🍀 크로플과 빙수도 먹을 수 있어서 너무 좋었고 음료도 너무 맛있어요 !!!! 무엇보다...외국인언니 직원분께서 한국말도 잘하시는데 인상이 좋으셔서 반해버렸답니다 >_<', 81, 11, 'GOOD', SYSTIMESTAMP);
