INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '🤎티라미수 케이크가 맛있는 79파운야드 합정점🤎 티라미수 케이크랑 플레인 요거트 스무디 먹었어용~! 여기 크로플 맛집인줄 알았는데 티라미수 케이크도 맛집이네요', 31, 2, 'GOOD', SYSTIMESTAMP);
