INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '체인이지만 지점마다 조금 다른듯~ 합정 점은 더 예쁘네요 커피가 좀 탄맛이 나서ᆢ 그건좀 개취랑 안맞았네요 그래도 맛있는 케잌들로 즐거운타임~', 45, 6, 'GOOD', SYSTIMESTAMP);
