INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '💞💙디저트러버인 제가 너무너무 좋아하는 크로플 맛집이에요💞💙 야기 크로플이 면 혼자 10개도 먹겠어요 진짜ㅠㅠㅠ 넘나 맛있어서 매일 먹고파욧😁😁', 50, 9, 'GOOD', SYSTIMESTAMP);
