INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '합정 지나다니면서 자주 본 디저트카페인데 이용해보는건 처음이었어요 디저트 종류도 다양하구 체인점인만큼 맛도 보장되서 넘 맛있더라구요 입짧은 햇님이 크로플 시켜먹는 곳이라구 하던데 왜인지 알거 같아요 ㅎㅎ 특히 크로플 종류가 많았어요! 커피도 연하게 타달라고 하니 세심하게 신경 써주셨습니다:)', 11, 1, 'GOOD', SYSTIMESTAMP);
