INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '합정역에 입짧은햇님이 극찬한 79파운야드 카페에 다녀왔어요! ㅎㅎ 내부 인테리어도 정원마냥 싱그러운 풀잎과 아늑한 분위기가 너무 좋았어요. 그리고 크로플과 케이크 종류도 다양해서 결정하기 힘들었어요;;ㅋㅋㅋㅋ 저는 더블딸기크로플과 밀크티, 딸기라떼 먹었는데 크로플과 음료가 맛있어욤 ㅎㅎㅎ 평일임에도 사람이 정말 많았는데 크로플 맛집이라 인기가 많은 곳이에요~~', 2, 5, 'GOOD', SYSTIMESTAMP);
