INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '3년 가까이 처음 생겼을때부터 합정에 들르면 꼭 들러서 힐링하고 가는 곳. 전면 통창에 문을 열어놓고 계신데 날씨가 좋은 요즘 선선한 바람 맞으며 꼬수운 아메리카노와 맛있는 빵 한조각 먹으면 그 자체로 힐링인 카페다. 여기 커피는 찐한편이라 단독으로 먹는 것 보다 디저트와 함께 했을때 더욱 고소하고 풍미가 좋다. 3년간 자리 잡기까지 여기 사장님의 다양한 노력이 돋보이는 곳이라 들를때마다 리뷰를 적는다. 매번 올때마다 뭘 그렇게 손님 편의성을 위한걸 잔뜩 해놓으시는지.. 아무튼 합정이나 홍대에 들르는 사람들은 꼭 한번 들러보시길.', 49, 8, 'GOOD', SYSTIMESTAMP);
