INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '밤에 커피 못마셔서 차로 마셨는데 처음보는 이름이라서 골라봤는대 맛있었어요 샤먼- 바닐라향 루이보스차인데 향도 좋고 산큼해서 너무 맛있어고 케이크도 너무 맛있고 치랑 너무 잘어울렸어요~ 숍 분위기 완전 좋아요 추천추천', 22, 0, 'GOOD', SYSTIMESTAMP);
