INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '다양한 디저트 종류들도 많았고 거위를 컨셉으로 한 가게 인테리어가 귀엽고 특색있었어요! 야외테라스도 있어서 애견동반이 가능하더라고요!', 108, 23, 'GOOD', SYSTIMESTAMP);
