INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '진짜 제가 요즘 좋아하는 최애 카폐예용 여기 딸기크로플은 진심 넘뮤넘뮤 맛있쥽니다. 크로플이 쫀득하면서 달콤해서 아주 기분 좋아지는 맛입니다요! 남친이랑도 오고, 회사사람들이랑도 오고 널리널리 알리고 싶은 곳입니당 딸기티, 딸기라떼도 먹어봤는데 맛있구용 딸기파티입니다 요기는!!😃', 46, 0, 'GOOD', SYSTIMESTAMP);
