INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '인테리어가 예뻐서 들어갔는데 언니가 갑자기 아아에서 이상한 맛이 난다고 하더라고요. 근데 제가 먹었을 때는 별 문제없어서 뭐지? 했는데 알고보니 제가 먹는 아인슈페너가 너무 맛없어서 상대적으로 괜찮은 거였어요.. 집에서 카누에 파바 생크림 올려 먹는 맛이에요..ㅎㅎ 글고 매장에 크로플 덩어리 같은 거 의자랑 책상에 많아서 소지품에 달라 붙어요…', 111, 21, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '부모님과 식사후 커피나 마실까 가볍게 찾다가 바깥 인테리어가 예뻐서 들어간 이곳은 신세계였어요. 소품 하나하나 너무 아기자기하고 귀엽고 사진 찍으면 어디든 화보 느낌 🥹 그렇다고 매장만 예쁘냐? 아니요! 디저트도 음료도 예쁜데 맛있기까지! 특히 꿀밤라떼는 진짜 꿀밤 그대로의 그 꾸덕달달한 진한 맛! 같이 간 부모님도 사진 여기저기 찍으시면서 너무 예쁘다 즐거워하셨어요. 예쁜 공간에서 맛있는 음료와 디저트 먹고있으니 가족끼리 함께 하는 시간마저 더 달달해지는 느낌이었습니다. 내년에 한국 오면 또 오고싶은 곳. 그때는 오리소다 먹어보고싶네요 ☺️ 아, 강아지와 오면 뒤쪽 테라스에 앉을수 있는 자리가 있고 추울때를 대비해 난로도 준비되어있어요 👍🏻', 2, 0, 'GOOD', SYSTIMESTAMP);
