INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '급 10명 생파를 했는데, 가게 안쪽 뒷 야외 공간 같은 곳이 꽤 넓어서 좋더라구요. 아늑하고. 직원 남자분 아주 친절 하셨구요. 크로플 맛집 입니당! 케익은 넘 이뻤어용! 맛은 soso 가게가 아기자기 막찍어도 예뻐요', 43, 1, NULL, SYSTIMESTAMP);
