INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '플랫화이트 5000 밀크크로플 3300 가격은 저렴한 편인데 크로플 종류도 다양하고 참 맛있음 배만 안부르면 더 먹을만한 맛과 가격대 매장이 오리인지 거위인지 참 귀여운 디자인 매장 크기는 야외 포함하면 큰편 화장실 매우 깨끗함 만족', 15, 0, 'GOOD', SYSTIMESTAMP);
