INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '디저트의 종류가 아주 많아서 좋아요! 외국인 친구들하고 같이 왔는데 친구들이 아주 좋아했어요. 직원분들도 친절하고 디저트 맛도 많고 분위기도 아주 좋아서 마음에 듭니다. 다음에 또 올 거예요!', 116, 23, 'GOOD', SYSTIMESTAMP);
