INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '아이스크림 너무 쫀-득하고, 크로플도 바삭하고 커서 너무 좋아요! 다만 시나몬가루가 들어가서 깜짝놀랐지만 조화롭게 잘어울려서 맛있게 먹었어요. 분위기는 차분하고 대화하기 좋았습니다! 화장실깨끗 / 식기류깨끗✨', 85, 18, 'GOOD', SYSTIMESTAMP);
