INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '크로플 너무 바삭하고 맛있어요! 먹고 맛있어서 포장해 갔어요~ 케이크도 진짜 부드럽고 달달해요 아이스크림이랑 음료도 달달하고 상큼한 음료여서 맛있어요!! 진짜 너무 맛있어요ㅠㅠ 다음에 또 오고 싶어요', 128, 26, 'GOOD', SYSTIMESTAMP);
