INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '아몬드 바닐라라떼 달콤고소하고 맛있어요~ 티라미수가 담백하네요. 인테리어도 예쁘고 사장님 친절하세요. 크로플 맛집이라 종류가 많아요. 다음엔 크로플 먹어보고 싶네요!', 24, 9, 'GOOD', SYSTIMESTAMP);
