INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '그냥 걷다가 보이는 카페 들어갔는데 생각보다 좋았어요! 크로플이나 와플 종류도 엄청 많고, 음료 메뉴도 다양하더라구요. 커피도 괜찮고, 아이가 딸기라떼 엄청 잘 마시더라구요 ㅎㅎ 다행..🥹 크로플은 시그니처 먹어봤는데 역시 맛있네요!', 47, 9, NULL, SYSTIMESTAMP);
