INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '사장님 추천메뉴 바닐라크로플 바닐라 아이스크림 쫀득쫀득 일반아이스크림과 다르게 빠르게 녹지 않아서 크로플에 올려 먹으니 너무 맛있었어요. 증명사진의 웨이팅을 기다리며 맛집을 찾아가던중 추운 날씨에 우연히 찾아 들어간 숨은 맛집이었어요.', 49, 9, 'GOOD', SYSTIMESTAMP);
