INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '오리 소다 너무 귀엽고 예뻐요 ㅋㅋㅋ 오리를 좋아해서 방문해봤는데 곳곳에 있는 오리 인형이랑 소품들이 넘 취향저격이에요! 소다는 달달 상큼한 맛이고 크로플은 생크림이 부드럽고 엄청 달아요! 귀여운 오리들이 많아서 매우 만족❤️', 63, 18, 'GOOD', SYSTIMESTAMP);
