INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '기념일 케이크 필요해서 지나가다 케이크가 귀여워서 들어왔어용 밖에 인테리어도 넘 맘에 들어서 어왔는데 안에는 더 분위기있네요 케이크도 넘 귀엽고, 안에 오리들로 포인트 된 소품 구경할 수 있어서 좋았어용 음료는 못먹었지만 케이크 기대가 많이됩니다~~ 배불러서 다른 디저트는 못먹었지만 다음에는 크림크로플 먹어보고싶네용 ^^', 91, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '망고빙수가 진짜 맛있어요...!!!! 음료는 맛있긴한데 막 엄청 맛있다는 아니었고....그저 귀여웠어요....😉 망고빙수 추천입니다🩷🩷🩷', 92, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '음료 양도 많고 너무 친절하세요 음료수 흘리고 컵을 깨트렸는데 다친 곳은 없으시냐고 물어봐주시고 ㅜㅜ 너무 친절하심…. 감사하고 죄송했습니다', 17, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '디저트류가 다양하고 맛있어요❤️ 빙수, 크로플, 조각케익, 각종 스무디랑 음료 없는게 없어서 좋았어요🥰!! 더운날 시원하게 당충전하기에 딱 좋아요.', 86, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '나이가 조금 더 있으신 사장님... 제 음료 만들때 왼손 약지또는 검지로 왼쪽 귀를 만지더라구요.. 그손으로 옆으로 기울여진 팥을 또 맨손으로 만지셨어요.. 근데 또 왼손으로 귀를 만지고 떡도 그 손으로 직접 만지시고 제 음료에 올리셨어요.. 전 비위가 강합니다.. 그리고 당이 떨어져서 별말 안했지만 참... 제발 다음 손님들을 위해 장갑을 끼시던지.. 아니면 귀를 안만져주시면 감사하겠습니다', 27, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '엄마랑 산책하다 들렀는데 주말에도 조용해서 대화하기 넘 좋네요 ^^ 음료도 맛있고 인테리어랑 소품들도 아기자기하고 예뻐요 ☺ 야외테이블도 있어서 따뜻한 봄햇살을 만끽하기에도 좋습니다 🙂 리뷰 써서 에코백도 받았어용 ㅎㅎ', 18, 7, 'GOOD', SYSTIMESTAMP);
