INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '너무 더워서 시킨 수박주스 시럽이 없고 수박으로만 갈은 시원한 수박주스 같아요~~ 배 슬러시는 갈아먹는 배 음료수맛과 ㅎㅎ  비슷한 맛이고 얼음 슬러시에 씹히는 맛이 있는 시원한 음료수 입니당^^ 더운날 몸을 춥게 만드는것 같아요~~~', 85, 17, 'GOOD', SYSTIMESTAMP);
