INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '크로플이 맛있기로 소문자자한 "79파운야드"의 또하나의 엄지척이 있으니, 바로 케이크!!  귀여운 요 케이크들은 맛도 최고! 디자인도 귀욤귀욤! 게다가 가성비도 좋아서 굿굿! 친구 생일케이크로 귀여운 강아지(얼그레이도그) 낙점했어요~!😊', 50, 2, 'GOOD', SYSTIMESTAMP);
