INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '늦은 시간까지 열려있어서 케이크 사서 12시 땡하고 생일파티할 수 있었어요!! 얼그레이 케이크 샀는데, 강아지 디자인도 귀엽고 크림도 맛있었어요~ 가성비 괜찮은 것 같아요! 다른 맛 케잌들도 궁금합니다:)', 75, 18, 'GOOD', SYSTIMESTAMP);
