INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '언제나 맛있는건 알고 있었는데.. 입짧은햇님님께서 최근에 이곳에서 시킨 크로플 다른곳에 비해 너무 맛있다고 올리신거 보고.. 오랜만에 왔어요! 간만에 와도 변함 없이 친절하시고 너무 맛있네요.. 잘 먹고 갑니다!', 29, 10, 'GOOD', SYSTIMESTAMP);
