INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '크로플이 맛있네요! 잘 안잘려서 뭉개서 먹었네요 ㅋㅋㅋ 직원분은 친절하시지는 않았어요 ㅠ 아쉽 카페 내부에 야외도 있고 은근 매장이 큰거 같습니다~ 사람이 많아서 자리가 없을 수 있어요!ㅎㅎ', 60, 13, NULL, SYSTIMESTAMP);
