INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '진짜 체고최고 맛도 좋고 너무너무 예뻐요♥️🤍 완전 추천합니다 >.< 합정인들 다 79로 모여라 ㅎㅎㅎㅎ예쁘고 깜찍한 케이크 감사합니다아❗️😍🥳', 67, 11, 'GOOD', SYSTIMESTAMP);
