INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '외관이 민트민트하고 식물이 촤르르~~ 예뻐서 들어가봤어여 개인적으로 카페는 맛있는 디저트가 있는곳이 좋아서ㅋㅋㅋ 일단 디저트뭐있나 구경해봐야겠다 했는데 내부도 예쁘고 디저트도 예쁘고 맛나보여서ㅋ 로투스크로플 초코 비스킷슈 안에 크림 가득가득 맛났고 꾸덕한 치케를 좋아해서 레어치케는 몽글퐁신한 푸딩 같아서 이건 걍 그랬어요ㅜ 평일 14시전까진 아메리카노 2000원할인도하고 디카페인도 있어서 넘 좋았어요 디카페인 아아는 산미살짝있어서 별로다라고 생각했는데 끝맛이 넘 맛났어여ㅜ 마셔봤던 디카페인 아아중 젤 맛났어요 일하시는분들 친절하셨구요 😊😛', 79, 14, 'GOOD', SYSTIMESTAMP);
