INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '사진은 못찍었지만 급하게 친구 생일축하케익을 사야해서 마감 직전에 갔는데도 친절하게 대응해주시고 예쁘게 포장해주셔서 감사해요 조각케이크도 예쁘고 친구가 맛있게 먹었다네요!! 또 들르겠습니당~~', 28, 1, 'GOOD', SYSTIMESTAMP);
