INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '늦은시간이라 케이크 재고있는지 확인전화 드렸는데 굉장히 불친절하게 따지면서 무슨케익 찾냐고 말을해야 알지않겠냐며 따짐;ㅋㅋ 그러더니 걍 전화끊음 매장 방문하니 화난듯이 전화한사람이냐고 째려보면서 응대하심; 당연히 손님입장에서 무슨 케익이 있는지 모르는 상황인데 기분 상당히 나쁘고 이용 두번다신안할듯 ----------답변후 저도 답변남기죠------- 택시이동중에 전화하여 택시 사장님조차 알바생놈일거라고 그래서 그렇게 응대할거라고 하셨네요 ㅋㅋ 케익재고 있냐고 한뒤 무슨케익찾냐고 화내서 블로그보니 19800원 같은거 있던데 남았냐 한걸 이렇게 본인마음대로 글을 써놓네요 ㅋㅋ 누가보면 내가 잘못한줄알겠넼ㅋㅋ  똑바로 응대하셔야할거에욬ㅋㅋ 마감시간에 방문해서 빡친듯 ㅋㅋ 아글고 케익도 얼어있어서 썰지도못함', 30, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '전부터 계속 가보고싶었던 79파운야드! 이번에 어쩌다가 들어가게 되었는데 디저트들도 너무 맛있고, 예쁘게 나왔어요! 다음에 다른 디저트 먹으러 꼭 갈거에요ㅎㅎ', 37, 5, 'GOOD', SYSTIMESTAMP);
