INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '크로플 종류가 다양하고, 아기자기한 분위기 그리고 음료까지 맛있어용❤️ 합정가면 꼭 가보면 좋은 카페에욤 화장실도 안에 있어서 너무 편해용', 29, 1, 'GOOD', SYSTIMESTAMP);
