INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '디저트 맛있는거 엄청 많아요!!!! 홀케이크도 디자인 엄청 귀여운 토끼랑 오리랑 강아지에요!!!! 오늘은 크로플이랑 케이크 포장만 했는데 담에는 홀케이크도 사려구요🐰🐶🐥', 10, 3, 'GOOD', SYSTIMESTAMP);
