INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '1. 밀크크로플 가격도 싸고 맛있었어요 근데 좀 딱딱해서 잘 안썰렸어요 2. 티라미수 이건 그냥 그랬어요 3. 아메리카노 원두가 셔요 원래 아이스크림 크로플을 먹으려했는데 비가 많이 와서 너무 추워서 안 시켰어요 크로플 먹고 싶어서 서치하는 중에 엄청 평이 좋아서 갔는데 쏘쏘였어요^^ 담에는 아이스크림 크로플 도전해볼게요!', 32, 4, NULL, SYSTIMESTAMP);
