INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '크로플이 진짜진짜 맛있어요!! 쿠키슈 좋아하는데.. 여기 쿠키슈는 바로 크림을 넣어주는게 아닌 내장보관에서 꺼내기에 조금 눅눅해요ㅜㅜ 아쉽지만 크로플먹으러 또 가고싶네요 ㅎㅎ', 17, 3, 'GOOD', SYSTIMESTAMP);
