INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '레몬케이크가 진짜 너무너무 맛있었어요,, 크림도 레몬맛♡,, 야외에도 자리가 있어서 먹을 수 있음! 글고 인테리어가 넘 기여웠어요 특히 거위 넘 기여븜 제 취향이에요 아 그리고 커피양 넘 많아서 깜짝 놀랬슴♡,,,, 또 가고 싶어요 레몬케이크 먹으러,,', 38, 4, 'GOOD', SYSTIMESTAMP);
