INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '커피도 맛있고 음료도 맛있고... 크림을 올려주는데 일반 생크림이 아니고 부드럽고 특이해서 너무 너무 인상 깊었던~~~ 디저트도 특이한게 많았지만 저녁때문에 못 먹은게 좀 아쉬웠는데 기회가 되면 담에는 크로플도 한번 먹어보고 싶네요~^^', 11, 7, 'GOOD', SYSTIMESTAMP);
