INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '에메랄드와 화이트, 골드가 조화롭게 배치된 인테리어가 비쥬얼을 만족시킵니다. 커피도 좋고 아이스크림이 얹어진 바닐라 크로플이 정말 맛있습니다. 아이스크림이 다른 곳보다 더 쫀득쫀득한 식감을갖고 있는듯해요. 좋은 곳이 생겼네요^^', 41, 0, 'GOOD', SYSTIMESTAMP);
