INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '다른지점에서 크로플 먹고 반해서 합정에서 카페 찾다가 바로 들어갔어요 ㅎㅎ 더티초코크로플은 첨 먹었는데 초코도 두껍게 발라져있고 완전 달달 디저트더라구요. 사장님도 엄청 친절하셨어요~', 17, 10, 'GOOD', SYSTIMESTAMP);
