INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '초코케잌은 덜꾸덕해서 아쉬웠는데 크로플이랑 빅토리아케잌은 짱맛있었어요! 취향에 안맞는거지 초코케잌도 나쁘지않았습니당. 진짜 짱맛있!', 389, 30, 'GOOD', SYSTIMESTAMP);
