INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '79파운야드 합정점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '합정 홍대 부근에 크로플 맛집이 생겨서 너무 행복합니다! 테라스도 너무 이쁘고 무엇보다 바닐라 크로플에 아이스크림을 너무 퍼주셔서 깜짝 놀랬습니다! 잘 먹었습니다~ 번창하세요!', 121, 26, 'GOOD', SYSTIMESTAMP);
