INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '망고빙수먹고싶어 시켰는데 망고가 너무 딱딱하게 얼어있네요 녹지도 않아서 망고는 거의 못먹고 있었어요 그렇게 붐비지 않아서 좋긴해요', 110, 19, 'BAD', SYSTIMESTAMP);
