INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '🤎진한 커피를 좋아해서 내 취향에 맞는 투썸프레이스❣️ 💛케이크도 맛있다❣️초코도 생크림도👍❣️ 🤎사진 초코는 클래식가토쇼콜라(7200) 생크림🍓는 예전에 먹었던 🍰🤳오늘 없었다❣️ 💛맛있게 잘 먹었어요😊❣️', 29, 1, 'GOOD', SYSTIMESTAMP);
