INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '여긴 서비스업 하면서 서비스업 정신을 버리기로했나보죠..본인의 선택인것을..추잡스럽고  불쾌한 이슈가 있었습니다! 장기 단골이지만 상종 안할랍니다..게다가 여긴 고객을 위한 운영 방침이 제대로 명시가 안되어있다보니, 가게대표 말처럼 저같은 선량한 고객이 피해봤어요ㅠㅠ왕 억울행 다른 알바생들도 쉬쉬하며 방침을 잘 모르더라고요! 다른 고객분들이 저같은 피해를 안보도록 하루빨리 제대로 된 직원 교육과(기본적인 당연한 서비스정신 포함) 소비자로서 돈쓰고 즐겁게 편히 있다 갈 수 있도록  얼른 조치를 취하시길.. 본사와도 얘기가 된 부분이나, 말로만이 아닌, “실천“을 꼭 하셨으면해서 공익을 위해 이렇게 여기에 리뷰도 남겨요! 답글은 남기시려나..?전 이거 안지울거고..그리고 매장청결도 신경좀..인력이 이래서 중요', 26, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '분명히 나보다 뒤에 주문한 사람도 먼저 음료를 받고 케이크 포장에 음료 6,7잔 시킨사람도 다 받아가는데 아메리카노 한잔시킨 내 음료가 나오지 않아서 음료가 누락된 것 같다고 물어보니 바로 드리겠다고 하고 바로 줌. 그리고 끝 엥 ???  물어봐야 주는 시스템이었나봄...ㅎ;;; 직원의 사과? 당연히 없음 매장 바빠보여 아무말 안했지만 직원들의 친절도를 올릴 필요가 있다고 생각해서 리뷰 적습니다', 76, 18, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '함께 한 지인도 투썸플레이스를 좋아해서 홍대입구에 가서도 이곳을 찾아 갔어요. 분위기가 편하고 디저트가 맛있어서 그런 모양이예요.', 125, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '홍대에서 친구를 기다리며 혼자 들렀던 카페입니다. 여느 카페에서는 쿠폰 사용 시 직원분들이 직접 계산해주셨는데, 이곳에서는 키오스크로만 처리가 가능하다고 안내를 받아 처음엔 조금 당황했어요. 기계로 쿠폰 사용이 익숙하지 않아 뒤에 줄이 길게 늘어선 상황에서 직원분께 도움을 요청했지만, 마치 왜 못하냐는 듯 코웃음을 치셨고 무시하는 것처럼 느껴져 실망스러웠네요. 맛있는 디저트를 즐기려던 기분이 상했고, 홍대에서 많이 놀아서 예전에 방문한 경험이 있는 곳이라 더 아쉬웠습니다.', 21, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '매장 넓어서 좋기는 한데 얼음 조금 달라니까 음료가 절반도 안 되더라...... 투썸 얼음으로 장사하지 마셈 진짜 기분나쁨 안 갈거임', 14, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '처음 방문~  카페라떼와 아이스카라멜마키아또 주문. 라떼 한잔은 시나몬가루 뿌렸어요. 투썸이 원두가 진한편인데 이곳은 딱 적당합니다. 테이블 간격이 좁은 편이라 사람이 많아 좀 시끄럽고 정신없기는 하네요. 전에 앉았던 자리는 테이블이 지저분한 곳이 많네요.', 49, 0, 'GOOD', SYSTIMESTAMP);
