INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '동네에는 떠먹는 스초생 자주 떨어지는데 여기는 재고 많아서 좋았어요~! 다만 직원분들이 매우 바빠 보이시고 조금은 복잡시러워요🥹', 14, 7, 'BAD', SYSTIMESTAMP);
