INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '기존에 시켰던 쉬폰 케이크가 조금 딱딱하고 크림도 눅눅한 느낌이 들어 말씀드렸더니 확인 후 흔쾌히 다른 제품으로 바꿔주셨어요 ..! (케익에 문제가 있기보단 원래 그런 제품인거 같아 다른 메뉴로 바꾸는걸 제안 하셨어요) 이미 1/3정도 먹은 상태라 곤란하실 수 있는 부분이셨는데 다른 케익으로 바로 바꿔주신 배려에 너무 감사드려용 직원분도 친절하시고 대처도 빠르셨어요 !!☺️', 42, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '스초생을 좋아하는 아들의 생일이라 저녁후 스초생을 먹으러 갔는데;;  홀케잌을 매장에서 먹는데 접시가 필요해서 부탁 드렸더니 홀케잌에서는 접시를 줄수 없다며 규정에 안된다며 거절하심;;  아니 매장에서 음료 밎 케잌을 홀케잌 먹는데 규정 따져가면서  접시를 줄수없다는게. 정말 속상하고 기분이 별로였어요.  기본적으로 조각 케잌 먹을때 접시에 올려주는건 되는데  홀케익을 매장에서 먹으면서 나눠먹기 위해 접시 1개만 부탁드린게 그렇게 어렵고 힘든것인지;;  직원분의 거절이 속상하고 투썸의 고객  응대가 융통성이 없음에 한탄스럽네요. 다시는 가고싶지 않은 투썸 매장이 됐습니다.', 30, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '라떼 너무 맛이없네요. 음료도 만들고 시간이 지나고 주셔서그런지 우유거품도 다 굳어서 먹기힘들고 투썸에서 마셨던 라떼중에 제일 맛이 없었네요.', 119, 21, 'BAD', SYSTIMESTAMP);
