INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '케이크 포장해서 먹으려고 까보니 바닥이 저렇더라구요. 언제 쏟은지 모를 커피가 케이스 바닥에 흥건하고 케이크에도 스며들었습니다. 맛이 이상한건 아니라 그냥 먹지만 솔직히 화나내요. 이정도면 포장하며 확인을 안한거 아닌가요? 기분좋으려고 샀다가 오히려 화만 누적합니다. 앞으로는 이런 일 없도록 똑바로 확인 부탁드립니다', 33, 8, 'BAD', SYSTIMESTAMP);
