INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '익선동에서 밥먹구 홍대쪽으로 와서 돌아보다 들른 카페서  제부는오늘, 울아들은 내일 생일이라 조각케익으로 서로 축하했어요 초는 서로 나이 앞자리ㅋㅋ 의자도 편하구 아인슈페너도맛있구 케익도 다 맛있었어요  뭐든 맛있네요♡', 3, 0, 'GOOD', SYSTIMESTAMP);
