INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '매장 더럽고 알바인지 직원인지 진짜 불친절해요 일하는 사람 다 불친절한 곳은 처음;; 바쁜 건 알겠는데 홍대 카패는 다른 곳들도 다 바빠요 왜 이런 대우 받으면서 이용해야하는지 모르겠네요 ㅋㅋ 다신 안 갈 것 같아요 직원 교육 잘시키세요', 4, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '12/23 알바가 너무 기분 나빠요 화장실 물어보는데 쳐다도 안보고 손짓으로 건성 대답하네요 가까워서 가끔 가는데 이딴데가 다 있나 싶네요', 456, 39, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '날이 너무 더워서 아이스커피 마시러 갔습니다 투썸오더에 쿠키가 없어서 현장에서 주문했습니다. 사람이 꽤 많은데도 책상 위가 깨끗하더라고요. 생각보다 관리를 하나보다.. 싶었습니다. 디카페인 아이스라떼 얼음적게 로 주문했는데 커피맛이 좀 밍밍한 느낌이었어요. 스벅에 익숙해서 그런가.. 말차쿠키는 바삭보다는 촉촉한 쿠키였습니다. 캐슈넛은 맛이 없었고요ㅋ 쿠키 뒷면에 코코아가루같은게 뿌려져있어서 물어봤더니 말차에도 발뭐시기 가루인데 뿌려져있는게 맞다고 하네요😅', 61, 14, NULL, SYSTIMESTAMP);
