INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '무조건 키오스크 주문해여한다고 해서 한참 기다리고 주문하니 애플페이는 키오스크주문이 불가능하다고 하네요. 본사직영점인데 키오스크 달랑한대는 말이 안되네요. 직원들 대응도 엉망입니다.', 47, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '폴드포크 샌드 위치 세트, 에그샌드위치 세트를 먹었습니당^^ 폴드포크는 간이 너무 세서 짜다는 느낌이 들고 에그샌드 위치는 간이 싱거워서 커피랑 궁합이 잘 맞았어요^~^ 제 입맛에는 에그샌드 위치가 맛있네요 ^~^', 16, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '아니 손님이 자기들 친구인지 ㅋㅋㅋ 주문하려는데 표정은 다들 썩어있고 지나가는 사람한테 길을 물어봐도 다들 이표정은 아니에요 째려보는줄알았네; 표정 썩어있다가 자기들끼리 킥킥대고 뭐 말하는거 하나하나 끝맺음 제대로 말하지도 않고 말끝 흐리고 말투도 딱딱하니 반말듣는기분+시비거시는줄..; 누가 일부러 아양떨고 애교부리래요? 서비스직 종사하면 말투정도는 평타라도 해야하는거 아닌가? 영수증달라니까 뭔 수건 건네듯이 한손으로 찍 내미는데 주문 저쪽에서 받으라고 말하는 사람이나 주문받는사람이나 음식내주는 사람이나 하나같이 사람 대하는게 너무 기분나쁜데요 직원들 교육좀 제대로 시키셨으면', 86, 12, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), 'ㄷㅔㄴㄷㅔㄴ cafe리유저블컵 아아내꼬☕️프렌차이즈카페중 #조각케이크 맛집이죠:) 이번 신메뉴인가봐요😋#떠먹는옥수수크림치즈 🌽🍰또 머꼬 싶어라🤤', 30, 3, 'GOOD', SYSTIMESTAMP);
