INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '커피 머신 하나 원두 채우는 데 3-4명 다같이 있고 손님 온 거 확인하신 것 같은데 주문은 안 받으시나요...... 다른 분도 케이크 흘러내리신 것 같은데 저도 케이크 흘러내렸거든요 ㅠㅜ 사람 많아서 바쁘신 건 아는데 잘 담아주셔야 하지 않을까요', 53, 11, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '매장이 넓고 좌석이 많아서 이야기하기는 좋아요. 음료맛은 그냥 투썸 맛입니다. ㅎㅎㅎ 친절함은 그냥 그래요. 홍대가 뭐 다 그렇지 싶어요.', 91, 25, NULL, SYSTIMESTAMP);
