INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '이곳 투썸 단골입니다. 양팔문신 알바언니... 난 호프집 바에 온줄... 음료랑 케잌포장 손님한테 밀어서주던데.. 그건 아니잖아~  무식하긴...', 0, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '케이크가 맛있어서 종종 들르는데 갈때마나 직원분들이 불친절해서 기분이 안좋아집니다. 리뷰같은 거 안쓰는데 굳이 인증하고 남깁니다.', 24, 6, 'BAD', SYSTIMESTAMP);
