INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '커피랑 케이크 페어링 세트 시켰는데 할인 안 해주고 제가 영수증 요청 하니 그제서 계산 잘못 해서 다시 결재 한다고 하고 사과 한마디 없네요.', 69, 17, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '주말에 방문했는데 사람이 너~~~무 많아요ㅜㅠ 셀 수도 없이 사람들 들어왔다 나갔다 하니 테이블 관리도 안되고.. 주문 지옥 때문인지 직원분들 표정도 어둡고 친절하지 않은 느낌ㅠㅠ', 114, 24, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '여자직원 엄청 싸가지없네요 주문기다리는데 뚫어져라보더니 주문하세요? 이러고 주문하고나서 음료가지러갔는데 뭐 사람도 없고 음료랑 빨대만 덜렁 있어서 가지고왔는데 빨대가 다 젖어서 포장이 안 뜯길정도라서 다시받으러갔더니 한숨만 푹푹쉬구요 ㅋㅋ 직원관리 다시 하시든가 하세요..', 17, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '투썸플레이스 홍대입구역점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '직원들이전체적으로띠꺼움.. 남자직원도 빨대어딨냐고 물어보니까 그냥 가르키기만하고 여자직원은 계산받는데 말투가.. 서비스직하면 안될듯 전체적으로 카페도 더럽고 테이블 안닦나봄', 39, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '근처 볼일 보러 왔다가~ 카페인 수혈이 시급해서 들렸네요;;; 리뷰가 넘 좋길래, 커피맛 궁금해서 무작정 왔는데!! 몹시_성공적~♡.♡ 특히,시그니쳐인 플랜멜번 진심 미쳤어요!! 일본 갔을때 반했던 맛이랑 똑같은곳을 우연히 찾다니~!! 진심. 감동쓰ㅎㅎ 꼬숩고 풍미가득🫶🏻 콜린스 밤크림라떼도 굿굿 에그타르트 별 기대없었는데, 페스츄리 겉바속촉 ~♡ 크리미한데 완전 쫀득해요 👍🏻 커피랑 꼭 같이 드셔보세요~❣️ 아늑하고 음악도 좋음:) 화장실도 내부에 있어 편하고, 테라스 자리도 있네요 ㅎㅎ 카페앞, 주차도 2대 가능하다고 해요~!!', 376, 42, 'GOOD', SYSTIMESTAMP);
