INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '에그타르트 맛집이라는 동네언니의 얘기를 듣고 찾아 간 곳 분위기 아늑하고 세련된 느낌 좌석이 많지 않아 일찍 가지 않으면 웨이팅 해야 할 장소 사장님 친절하시고 에그타르트의 바삭함과 촉촉함이 아아와 환상 조화를 이루네요~ 다음에 재방문 예정', 11, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '신촌 골목 안에 조용히 자리한 콜린스커피에 다녀왔어요. 외관부터 벽돌 건물과 큰 통창 덕분에 따뜻한 분위기가 느껴집니다. 안으로 들어서면 노출 콘크리트와 블랙 톤 가구가 깔끔하게 배치되어 있어요. 햇살이 통창으로 들어와서 공간이 환하고 아늑합니다. 음악도 차분하게 흘러나와서 혼자 앉아 있어도 편안했어요. 좌석은 2~3인 위주라 소규모로 오기 좋은 느낌이에요. 골목에 있어 그런지 신촌의 북적거림에서 벗어나 여유를 즐길 수 있습니다. 카공 분위기보다는 담소 나누거나 휴식하기에 알맞았어요. 특별히 화려하지 않지만 차분하고 무난한 감성이 좋았습니다. 다음에도 조용히 쉬고 싶을 때 다시 방문할 것 같아요.', 9, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'INDUSTRIAL');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '주차가되는 커피집 찾다가 즉흥적으로 방문 알고보니 에그타르트를 직접구워줌 10분소요 음식에 진심이 담긴곳 갓나와서 맛있음 예약이 반이었고 자리는 몇없지만 거의 만석이됨 테라스자리도있음 특히 봄과가을에 더욱더인기있을듯 현재 네이버예약시 에그타르트. 한개나 커피가격의 10프로 할인적용이벤트중', 20, 7, 'GOOD', SYSTIMESTAMP);
