INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '에그타르트 맛집이라고 했는데 완전 타르트가 바삭바삭하고 안에는 필링이 부드러워서 그냥 타르트만 먹어도 너무 맛있었어요! 그리고 플랫화이트를 이곳 스타일로 바꿔서 숙성우유를 사용한 플랫 멜번을 먹어봤는데 극강의 진하고 고소함이 묵직한 라떼 좋아하는 사람한테는 완전 강추였어요', 47, 2, 'GOOD', SYSTIMESTAMP);
