INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '˗ˋˏ 와 ˎˊ˗ ☕️🥧 가끔 지나가다가 궁금했던 카페인데 그냥 스윽 - 와봤는데 핸드드립 너무 맛있고, 특히⭐️ 여기 에그타르트 바로 구워 주시는데 와.. 근래 먹었던 에그타르트 싹- 잊게해요 따듯한 바삭함 최고! 카페도 테이블 간격 넓고 쾌적하며 음악도 좋습니다 🎶', 87, 16, 'GOOD', SYSTIMESTAMP);
