INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '와 플랫멜번 시그니처 메뉴 중 하나인데 꼭 드셔보세요,,,, 그냥 먹었던 플랫화이트보다 훨씬 고소하고 진해요!!! (숙성우유를 쓴다고 하는데 그래서 깊은 맛이 나나봐요ㅜㅜㅜㅜㅜㅜ) 갓 구워주신 에그타르트도 너무 맛있네요ㅜㅜㅜㅜ🤍🤍🤍🤍🤍🤍🤍 조용한 분위기라서 노트북 작업하기도 좋고 가게도 깔끔하고 모든게 취저,,,,🤍🤍🤍🤍', 42, 8, 'GOOD', SYSTIMESTAMP);
