INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '분위기 너무 좋고 사장님이 정말 친절하세요~~ 차분히 대화하기 좋은곳이라 작업하거나 데이트할때 추천드려요! 음료 종류가 많아서 좋았어요 :) 에그타르트는 주문 즉시 구워주셔서 따끈하게 먹기 좋을것 같아요', 30, 9, 'GOOD', SYSTIMESTAMP);
