INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '콜린스커피 눈여겨보다 이번에 방문해봤어요. 콜린스크림커피와 핸드드립 산미있는 원두 아이스로 선택 원두 2. 산미블렌딩 (콜롬비아, 과테말라, 에티오피아 블렌딩) 선택 콜린스크림커피는 은은한 버터스카치크림이 올라가있고 덜 달아서 좋아요. 에그타르트가 바삭바삭 따끈하게 나오고 고소해서 맛있어요. #신촌카페 #신촌역카페 #콜린스커피', 43, 1, 'GOOD', SYSTIMESTAMP);
