INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '숙성우유라서 확실히 꼬소하고 진해요. 커피의 깊은맛이 느껴져요. 배불러서 에그타르트는 한개만 주문했는데 바로 구워주시는거라 따뜻하고 더 신선해요.', 63, 15, 'GOOD', SYSTIMESTAMP);
