INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '분위기가 너무 좋고, 모던하고 깔끔해서 담에 꼭 다시 오고 싶어요~! 커피, 스무디 메뉴도 너무 맛있어서 너무 만족했습니당 담에 또 방문할게용', 9, 6, 'GOOD', SYSTIMESTAMP);
