INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '신촌에서 주차 가능한 카페! 적당한 규모의 공간과 이색적인 커피가 너무 맘에 드네요 ☕️ 크림라테 시켰는데 완전 만족스럽네요. 담엔 후기 좋은 플랫 마시러 와야 겠어요! 에그타르트도 👍', 10, 5, 'GOOD', SYSTIMESTAMP);
