INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '사장님 혼자 하시느라 대기 시간이 조금 있지만 말씀해주신 대기 시간에 비해 금방 나옵니다! 에그타르트만 따로 판매하시는것 같은데 그 이유를 알 정도로 너무 맛있네요 어떤 분 리뷰에 쓰신 것처럼 슈크림 느낌이 나는 부드럽고 달콤한 에그타르트입니다! 따로 한박스 사서 가져가 먹고 싶을 정도로 맛있습니다! 담번에 또 에그타르트랑 커피한잔 하러 올것 같네요! 좌석도 코드 마련된 좌석도 있고 업무보기 좋습니다!', 2, 0, 'GOOD', SYSTIMESTAMP);
