INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '요즘 분위기 좋은 카페로 다녀오기 딱 좋아요!! 인테리어 쏙 맘에 들었습니다..!!! 디저트류도 많고 시그니처도,  커피도 다양해서 좋았어요 최고!! 추천합니다아💕', 40, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '신촌역에 오랜만에 데이트하러 나왔는데 근처 콜린스커피가 있길래 들어와봤어요!! 매장 내부 인테리어 엄청 깔끔하고 모던하게 잘 꾸며져 있더라구요 커피도 맛있어서 종종 올 것 같아요😁', 36, 0, 'GOOD', SYSTIMESTAMP);
