INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '인터넷 검색하고  왔는데  분위기 좋고 밖에 비가 와서인지 카페 분위기와  잘 어울립니다. 친구들과 만남의 장소로 추천드려요.', 11, 2, 'GOOD', SYSTIMESTAMP);
