INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '평일 오후에 왔더니 한적하고 분위기가 좋습니다👍 잔잔한 음악이 나와서 집중해서 일하거나 카공하기에도 좋은 것 같아요📚 요즘 카페들 기본 가격에 비해 비싸지도 않고 딱 적당합니다🙂 테이블마다 좌석이 붙어있지도 않고 방석도 있어요🙃', 46, 2, 'GOOD', SYSTIMESTAMP);
