INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '남자친구랑 신촌 돌아다니다가 라떼가 맛있어 보여서 들린 카페에요 ! 라떼 맛집인 줄 알았는데 에그타르트도 너무 맛있는데요 ?! 라떼 부드러운 크림이랑 결이 살아 있는 에그타르트 완전 잘 어울려요 😍 남자친구도 집 가면서 에그타르트 너무 맛있었다고 ㅋㅋㅋㅋ 에그타르트 좋아하시면 꼭 드시러 와보세요 !!', 65, 11, 'GOOD', SYSTIMESTAMP);
