INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '커피가 맛있어용!! 되게 깊이있는 맛이라고해야되낭?? 맛있구 에그타르트 겉바속부!! 겉은 바삭 속은 부드러워요!! 맛있어용🤤🤤🤤 슈크림? 달달한거 좋아하는사람 무조건추천!!!', 50, 0, 'GOOD', SYSTIMESTAMP);
