INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '숨은 라떼 맛집이라해서 찾아왔어요^^ 예쁜 하트를 품은 적당히 산미느껴지는 플랫화이트와 달콤하고 고소한 귀여운 에그타르트까지 👍 촉촉히 내리는 비와 잘 어울리는 분위기도 좋네요 😊', 18, 8, 'GOOD', SYSTIMESTAMP);
