INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '분위기가 좋고 조용해서 대화하기 좋은 카페였습니다. 카페 시그니처 메뉴인 콜린스 크림라떼와 스카치 플랫화이트 주문해서 먹었는데 정말 맛있었어요!! 자주 오고 싶어요~', 46, 0, 'GOOD', SYSTIMESTAMP);
