INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '에그타르트랑 소금빵 맛집이라해서 방문했어요. 시그니처 밤라떼와 밀크티 주문했는데 둘다 맛이 진하고 향긋했습니다. 매장 분위기도 좋고 화장실도 깨끗했어요.', 6, 8, 'GOOD', SYSTIMESTAMP);
