INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '에그타르트가 유명하다고 해서 방문했아영!! 주문하면 바로 구워준다고 하셔서 더 좋은 것 같아용!! 카페도 깔끔하고 사장님도 친절하십니당 ㅎㅎ 한 박스씩 판매를 해서 선물용으로도 좋을 것 같아요ㅎㅎ 다음에 남자친구 부모님에게도 선물해야겠아용😊😊 맛있게 잘 먹겠습니다!!🫶🏼🫶🏼', 92, 23, 'GOOD', SYSTIMESTAMP);
