INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '분위기도 좋고 맛있는 메뉴도 많아서 좋아요! 시그니처 밤라떼랑 크림라떼 시켜봤는데 비주얼도 좋고 맛도 좋네요! 빵 종류도 다 맛있어 보여요.', 32, 3, 'GOOD', SYSTIMESTAMP);
