INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '에그타르트 좋아하는 아이들을 위해 방문했는데 정말 맛있어요~ 복잡한 신촌에 있는 카페같지 않게 시끄럽고 하지 않아 가족단위 방문으로 좋았어요~~', 28, 2, 'GOOD', SYSTIMESTAMP);
