INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '사장님도 너무 친절하시고 커피도 너무 맛있어요!!! 특히 밤크림라떼 맛집입니다 ㅠㅠ 라떼 좋아하는데 여기 진자 맛있어요!!!! 신촌 오면 꼭 이 카페 올 것 같아요!!!', 29, 1, 'GOOD', SYSTIMESTAMP);
