INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '혼자 공부할 만한 조용한 분위기의 편안한 카페를 찾고 있었는데 제가 기대한 이상이여서 너무 좋았어요!! 잔잔한 팝송이 나와서 더 좋았던 것 같아요~ 얼그레이티를 시켜서 먹었는데 향긋하고 시원해서 제 입맛에 잘 맞았어요!', 4, 8, 'GOOD', SYSTIMESTAMP);
