INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '엄마랑 근처에서 밥 먹고 커피 마실 겸! 에그타르트 먹으러 방문했어요!! 타르트도 따뜻하게 바로 구워주셨고, 리뷰 타르트도 받았습니다!! 잘 머물다 갑니다..!!🧌🧌', 17, 6, 'GOOD', SYSTIMESTAMP);
