INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '크림이 고소하고 묵직해서 너무 맛있어요ㅎㅎ! 크림이랑 커피 같이 먹으면 카라멜 라떼맛나서 좋아요. 서비스로 주신 에그타르트도 맛있네용 감사합니다', 42, 3, 'GOOD', SYSTIMESTAMP);
