INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '여자친구와 신촌에서 데이트 중 방문했어요☺️ 신촌카페를 찾아보던 중 디저트 사진에 꽂혀서 왔습니다 😇 시그니처 커피도 너무 맛있는데 여자친구가 히비스커스 망고주스가 정말 맛있다고 좋아하네요ㅎㅎ 디저트도 정말 맛있었습니다 최고!!🥰 다음에 신촌에 또 방문하게 되면 또 올게요☺️👍!!', 34, 4, 'GOOD', SYSTIMESTAMP);
