INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '찾아따 라떼맛집!!( ＾ω＾ ) 신촌역 근처에 조용한 골목에 있는 콜린스커피... 밤크림라떼랑 에그타르트 넘 맛있어요..에그타르트 좋아하는 편이 아니라 별로 기대안했는데 엥 존마탱!!! 사장님도 친절하시구 조용해서 책 읽기도 좋아요 라떼 꼭 드셔보세여 다음에 또 와야딩', 21, 8, 'GOOD', SYSTIMESTAMP);
