INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '에그타르트에 진심이신 것 같아 메뉴에 에그타르트만 보고 왔어요. 10분 데워주는 에그타르트는 감동이네요ㅎㅎ 잘 먹고갑니다. 매장도 넓고 층고가 높아서 편안하게 있었네요. 감사합니다.', 21, 10, 'GOOD', SYSTIMESTAMP);
