INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '아늑하고 시원해요… 케익 너무 이쁘네요..매장 내 많이 시끄럽지 않고 좋아요  밤라떼먹으러 왔는데 품절되어 아쉽습니다ㅜㅜ 다음번에 밤라떼 먹으러 올게요!', 78, 17, 'GOOD', SYSTIMESTAMP);
