INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '핸드드립커피랑 콜린스크림라떼 시켰는데 꼭 와셔 드셔보셔야해요. 핸드드립은 먹을수록 커피향이 은으하게 올라오고 라떼도 크림이 고소하니 넘 맛있습니다. 인테리어도 너무 감각적이고 멋져요.', 35, 6, 'GOOD', SYSTIMESTAMP);
