INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '우연히 가는길에 들렸어요 빙수도 작은사이즈가 있어서 오랜만에 빙수 먹었습니당 따뜻하고 조용한 작은 카페에요 꽤 오래 혼자 머물기도 좋은 곳인것 같아요!', 28, 3, 'GOOD', SYSTIMESTAMP);
