INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '☕️크림라떼☕️ 맛집이라고 해서 방문했습니다 저는 밤크림라떼릉 마셨는데,  많이 달지않아서 질리지 않고 속도 편안하게 마실 수 있어서 너무 좋았습니다 분위기도 노래도 너무 좋고 직원분도 친절합니다 !! 무엇보다 화장실이 안에 있어서 좋아요🤍 🍪에그타르트🍪 안에 슈크림이 들어가 있어서 크리미한 에그타르트 좋아하시면 맛있게 먹을 수 있을 것 같아요! 저는 좀 더 계란향이 많이 나는 에그타르트를 선호해서 그저그랬지만 남자친구는 아주 맛있게 먹었답니다 ㅎㅎ 바로 구워주셔서 맛있게 먹을 수 있어요!! 집이 근처라 단골 될 수 있을 것 같아요 -🩷', 41, 9, 'GOOD', SYSTIMESTAMP);
