INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '신촌 주변에 거주하며 계속 가보고싶던곳이였는데 오늘에서야 방문을 했습니다! 카페 인테리어 깔끔하게 이쁘고 들어가자마자 빵냄새랑 커피냄새가 기분좋게 나는 곳입니다. 저는 자주올거같아요 신촌 메인거리쪽이 아니라 매장 및 주변 거리들도 너무 시끄럽지 않고 조용해요 모든 부분에서 추천드립니다!', 29, 4, 'GOOD', SYSTIMESTAMP);
