INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '커피가 정말 맛있어요. 여러번 갔는데 갈때마다 맛있어서 거리만 가까우면 맨날가고싶어요. 그리고 테라스가 정말 이뻐서 날씨 좋은날 가면 정말 좋더라구요.', 0, 9, 'GOOD', SYSTIMESTAMP);
