INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '건물 내부의 층고가 높아서 탁트인 느낌이라 매장이 넓게 느껴져요. 시그니처는 디카페인이 안돼서 아쉽지만 샷코코너라떼도 은은하게 코코넛향이 나면서 맛있어요.', 1, 5, 'GOOD', SYSTIMESTAMP);
