INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '아담하고 분위기 좋은 카페. 아직 안먹어봤지만 에그타르트 맛있을 것 같아요. 테라스에도 좌석이 있어서 날씨 좋은 날은 밖에서 드셔도 될 것 같아요.', 3, 5, 'GOOD', SYSTIMESTAMP);
