INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '친구랑 아침부터 한잔(?)하러 왔는데 분위기도 좋고 노래도 좋고 커피도 넘넘 맛있네요 🤸 플랫화이트 짱짱 ! 달지않고 깔끔해서 마음에 들어요~!', 55, 14, 'GOOD', SYSTIMESTAMP);
