INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '전부터 눈여겨 보다가 비오는 날 방문하게 됐네요. 시그니처 밤크림라떼 궁금했었는데 기대한만큼 아주 맛있어요. 비 오는 날 좋은 음악 들으며 잘 쉬었다가 갈 수 있는 곳이예요~', 24, 10, 'GOOD', SYSTIMESTAMP);
