INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '콜린스커피  너무 좋아하는 곳이예요💖 커피&음료는 단골집이 없이, 아무곳이나 보이는 곳으로 보통 들어가는데, 콜인스커피는 자꾸 찾게되는 카페예요 😍 음료도 다양하고, 커피도 종류가 다양해요 무엇보다 맛이 좋아 자꾸 생각나는 카페입니다❣️ 특별하게 미숫가루가 너무 맛있는 카페인데, 직접 만드는 미숫가루 더라구요!! 일반 시중에 판매하는 미숫가루랑 맛자체가 달라요!! 이번에 새롭게 집에서 만들어 먹을수 있게 미숫가루 집에서도 만들어 먹을수 있게 판매시작 하셔서 넉넉하게 두개 사왔어요  😄👍🏻 (저도 사장님께 미숫가루 판매요청 했는데, 다른 고객님들도 저와 같은 마음 이셨더라구요..❤️) 그외에 음료들도 너무 맛있어서 골라먹는 재미가 있어요❣️❣️ (양도 많아 좋아용💖💖)', 124, 22, 'GOOD', SYSTIMESTAMP);
