INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '처음와봤는데 매장도 이쁘고 분위기도 좋고 처음 들어오자마자 느낀 커피향도 너무 좋았어요! 화장실에서도 좋은 냄새 난다는...ㅎㅎㅎ 아 커피도 물론 맛있습니당!', 38, 3, 'GOOD', SYSTIMESTAMP);
