INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '오랜만에 왔습니다. 커피 맛있게 잘먹구갑니다. 늘 맛있는커피 감사합니다~항상 사장님이 계신거같은데 친절하게 응대해주셔서 감사해요', 6, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '카페 분위기 괜찮은 편. 사람들이 맛있다던 라떼는 보통. (나쁘진 않지만 맛있는 건 모르겠음) 쿠키는  파×바×뜨나 뚜×쥬×  정도라 담에는 안 먹을듯. 배달 주문은 많이 들어오는 것 같네요', 119, 24, NULL, SYSTIMESTAMP);
