INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '농협 하나로마트에 엄마랑 장보러 올 때마다 들리는 카페에요 지금 바깥이 공사중이라 밖에 앉지는 못했지만 좋아요 :) 커피도 맛있어요!', 23, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '커피 너무너무 맛있어요!!!👍🏻 카페 분위기도 좋고 무엇보다 사장님이 너무 친절하십니다 ㅎㅎ!! 재방문 의사 100%예요(•̀ᴗ•́)و 디저트도 종류별로 팔던데 담에 꼭 먹어보겠슴니다!', 35, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '친구가 에그타르트 추천해줘서 먹어봤는데 맛있어서 구매해서 다른 친구랑 먹었는데 역시 맛있다고 하더라구요 친구가 100개도 먹을 수 있다고 했어요 서비스 주신것도 너무 맛있었어요 카페 분위기도 좋구요 또 방문하겠습니다~!!!!', 35, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '콜린스커피'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '커피가 너무 맛있었어요! 사장님도 친절하시고 카페도 너무 예쁩니당~나중에 코로나 지나가면 꼭 카페에서 디저트랑 커피 마셔보려구요! 또방문하겠습니다~^^', 32, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '케이크 맛집이라고 들어서 왔는데 정말 종류가 많더라구요! 케이크류는 가게 밖 통창에서 전시되어 있어서 보고 고르시면 됩니다! 그 밖의 빵과 디저트는 가져오면 되구요~ 기본으로 먹고자 딸기케이크랑 가족픽 무화과 스콘을 시켰는게 달지 않고 폭신폭신해요. 다른 케이크맛에 궁금해지는..! 아 그리고 카페라떼 아이스로 시키시면 음료 위에 커피 큐브를 조금 올려주시는데 예쁘고 더 맛있어보여요ㅎㅎ', 9, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '여기 케이크는 꼭 찾아가서 사 먹어야 하는 그런 디저트입니다. 먹었을 때 절대 무겁지 않은, 그리고 푸석거리지도 달지도 않은, 하지만 입 안에 들어가면 가볍게 사르르 녹아드는 그런 맛을 지닌 마법의 케이크입니다. 가격이 좀 있기는 하지만 누가 먹어도 비쌀 만하다는 걸 인정할 수밖에 없을걸요. 커피도 같이 샀는데 얼음마저 커피로 되어 있어서 시원하게 즐길 수 있었습니다. 갈 때마다 사러 가게 될 것 같아요.😍😍😍', 24, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '1인 1케이크 필수인 케이크 맛집입니다! 시중에 파는 케이크들은 그저 달기만 하고 특별한 맛이 없는데 여기 케이크는 많이 달지 않으면서 원물의 맛과 향이 풍부하게 느껴져요. 정말 너무 맛있습니다. 🥹', 47, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '케이크 진짜 맛있어요🎂 하나도 안느끼하고 촉촉 폭신 레전드... 너무 달기만 한 것도 아니고 본연의 단 맛을 느낄 수 있는 그런 스타일이라 무한대로 들어감🔥 홍대 상수 올 일 생기면 무조건 재방문할 거예요! 사장님도 직원분들도 넘 넘 친절하시구 최고입니다🩷', 80, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '사실 신라호텔 출신 파티쉐님이 운영하시는 가게라는 팜플렛 보고 이끌려 왔는데 저도 호텔셰프로 근무중이고 디저트를 경험해본 사람으로써 개인 업장에서 다양한 케이크와 디저트를 한번에 많은 종류를 최소 인원으로 맛과 퀄리티를 뽐내기 힘들거든요..? 근데 정말 맛있습니댜.. 딸기시즌 답게 딸기케이크가 정말 많았고 딸기가 정말 듬뿍 들어가 있어서 입안에서 너무 달지도 않고 부드럽고 폭신한 케크가 녹는게 정말 맛있고 커피와 다양한 음료와 티도 너무 좋고 사장님과 질원의 친절함까지 더해져 정말 따뜻한 카페에용 진짜 강추드립니댜💖', 42, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '케이크 포장해서 집에서 먹었어요. 케이크 크기만큼 가격도 쎈데, 케이크가 맛있어요. 화이트얼그레이는 아래부분은 달지만 위쪽 크림이 상대적으로 덜 달아서 함께 먹었을 때 밸런스가 아주 좋았어요.', 36, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '크리스마스 케이크 선물하려고 미리 예약해서 샀고, 맛이 궁금해서 다음 날 오픈 시간에 가서 구입했습니다. 일단 좋은 재료를 사용한다는 점이 마음에 들었고, 케이크를 들었을 때의 묵직함이 좋았습니다. 맛은 단맛이 좀 강한 편이라 제가 좋아하는 맛은 아니었지만, 그래도 매장에  다양한 케이크가 있으니 다음에 다른 케이크들을 먹어보고 싶습니다. 다른 케이크를 먹어 봐야 맛을 얘기할 수 있을 것 같습니다.', 4, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '네이버로 쳐봤을때 음? 케이크가 꽤 비싼 편이군? 했는데 웬걸 케이크가 겁나 커요ㅋㅋㅋㅋ 겁나 크고 겁나 맛있음 ..🍰💓 종류도 많아서 또 가서 다른 케이크도 먹어보고 싶은 늬낌', 73, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '워낙 고전 디저트가게라 3번은 넘게 갔는데 맨날 테이크아웃만해서 2층은 한번도 안가봤네요 ㅎㅎ 하나하나 다 맛있습니다. 네모난 타입케익은 비싸게 느껴질수 있는데 엄청 묵직해서 4명이서 먹어도 될 정도에요. 밤케익 맛있는데 이날은 없었네요. 또 나오길! ☺️', 36, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '서울 오면 꼭 오고싶었는데 기대한 것 이상으로 정말 맛있습니다 커피도 부드럽고 케이크는 설명하기 어려울정도로 진짜 너무 맛있어요!!!!', 27, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '상수 카페 검색하다 눈에 띄어서 갔는데 커피맛집에 케이크 맛집이예요! 금액대가 좀 있긴 하지만 다른곳에 비해 케이크 크기가 크고 고급스럽게 맛있어요!', 7, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '진짜 여기 고민하시는 분들 왜 안 드세요,,제가 딸기케이크 너무 좋아해서 여기저기 다 먹어봤거든요 어지간한 호텔케이크도 다 섭렵했는데 여기 정말 찐🥹♥️일단 딸기 정말 가득가득 들어있고 크림 부드럽고 시트는 당연 말모 입 안에서 그냥 녹아요,,🍓🍰사장님도 정말 친절하세요 먹고 감동해서 2년째 방문중입니다,,조각케이크도 정말 큼직하고 양이 많아서 꼭 같이 사오는데 다들 드셔보셨으면 좋겠어요 저의 크리스마스 전통이 꼭 딸기케이크를 먹으며 나홀로 집에를 보는건데 올해도 성공입니다🎄', 20, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '저는 이곳의 케익을 먹기전의 저와 아닌저로 구분합니다. 정말 케익맛있어요. 하나하나 어쩜부드럽고 많이안달은데 내부의 과일이 달콤한지 또어서 가고싶어요!!!!', 25, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '사장님께서 명령조로 이층 올라가라 하시더니 주문 하려니까 사장님과 알바생 두분 다 듣고 그냥 지나치시네요 커피는 하나 빼고 아예 안된다고 하시고 음료도 몇개 안되네요 ㅋㅋ 주문 다 받고 나니까 복잡하게 시키지 말라고 말하시고 ㅋㅋㅋ 그럼 메뉴판은 왜 있나요~ 아메리카노 하나만 파시지 왜 여러개 써놓으셨어요 ㅠㅠ 덕분에 하루종일 기분 나쁠 거 같습니다!!', 48, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '너무 늦은 시간에 가서 포장해왔어요! 항상 믿고 먹는 딸기 듬뿍 생크림 케이크는 홀케이크🎂 그리고 또 맛있는 딸기 크레이프 케이크는 조각케이크🍰 기념일에 항상 생각나는 케이크, 주변인에게도 부담없이 추천할 수 있는 케이크 맛집이에요🥰', 0, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '망고빙수가 먹고싶을때에는 언제든 방문~~~~ 물론 예전보다 망고 크기,양은 줄었지만 진짜 다른 망고빙수랑은 맛이 달라요 짱짱!!', 88, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '팥빙수 1인이랑 망고빙수 2인 먹었습니다!! 조금 작은 감이 있고 우유얼음이라 그런지 에어컨 바람때문이지 금방 녹았어요 그치만 팥빙수 ..!! 진자 맛있었어요 위는 우유얼음이고 안에는 연유가 뿌려져서 섞어드시라는 설명이 있었고요 떡은 완전 쫄깃말랑 ㅜㅜ 팥도 알알이 씹히고 적당히 달아서 얼음이랑 딱!! 어울렸어요 망고빙수는 제취향은 아니었지만 같이 간 친구들은 맛있다고 좋아했어요 팥빙수 먹으러 또 갈급니당', 10, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '케이크맛집이라고 해서 찾아간 곳인데 정말 맛집이 맞네요ㅎㅎㅎ 특히 녹차초콜릿케이크 정말 맛있었습니다^^ 커피 위에 커피얼음을 올려주셔서 끝까지 밍밍하지 않아서 너무 좋았어요👍 다음에 또 방문하겠습니다~^^', 84, 14, 'GOOD', SYSTIMESTAMP);
