INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '상수역 근처 조용한 골목길에 숨은 디저트맛집💓 망고빙수 너무너무 맛있네요. 적당히 달고 상큼~ 눈꽃빙수 스탈이라 이 시리지 않게 넘 잘 먹었어요. 대화하며 머물다 가기 좋은 카페, 담에 케이크 먹으러 재방문하려고요👍', 16, 1, 'GOOD', SYSTIMESTAMP);
