INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '나만 알고 싶은 홍대, 상수 디저트 카페를 찾고 계시다면 달콤한거짓말 홍대점이 좋은 대안이 될 수 있겠습니다. 굉장히 넓은 홀을 운영중에 있으며 앤틱, 빈티지한 느낌이 예술이었습니다. 거기다 신라호텔 출신의 파티쉐님이 만들어주시는 케이크, 마카롱, 구움과자, 쿠키 등을 만날 수 있는 공간이기때문에 저처럼 디저트 좋아하는 분들에게는 정말 취향저격 공간이 되지 않을까 생각하고 저는 조각 케이크를 종류별로 포장해서 돌아왔습니다. 좋은 재료와 제철 과일을 사용해 만든 조각케이크를 포장해서 왔는데 풍미가 남달랐으며 재료간의 케미가 너무나 훌륭해 맛을 음미하는 재미가 쏠쏠했습니다. 선물, 답례품으로도 너무나 좋을 것 같고 차별화되는 케이크를 기대하는 분들은 꼭 방문하셨으면 좋겠습니다. 맛있게 잘 먹었습니다:)', 5, 9, 'GOOD', SYSTIMESTAMP);
