INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '초코딸기듬뿍케이크 정말 맛있게 먹었습니다! 생크림도 느끼하지 않고 딸기도 밸런스 좋게 들어가있고 코팅된 초콜릿도 엄청 맛있었어요. 매장이 넓고 직원분들이 친절하셔서 친구들과 편하게 쉬다가 갑니다.', 4, 0, 'GOOD', SYSTIMESTAMP);
