INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '사장님 굉장히 친절하셔서 기분이 좋았어요! 케이크를 비롯한 베이커리 종류도 다양한데 하나같이 다 예쁘고, 좋은 재료로 만들어서 느끼하지 않고 맛있습니다 :) 앤틱한 분위기가 근사한 상수 디저트숍으로 추천합니다.', 41, 10, 'GOOD', SYSTIMESTAMP);
