INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '돈이 전혀 아깝지 않은 최고의 케이크입니다 홍대 합정 상수 부근에서 단연 여기를 최고의 케이크집으로 꼽겠습니다 케이크를 공기처럼 마시게 되는 황홀한 경험을 할 수 있습니다 딸기 들어간 케이크를 특히 추천합니다', 69, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '상수동 케이크 맛집으로 알게되어 포장하러 방문했어요!! 샤인머스켓듬뿍,딸기크레이프,화이트얼그레이 포장😊 아직 맛은 안봐서 모르겠지만 보기만해도 맛있어요 ㅋㅋㅋ 케이크 뿐만 아니라 쿠키도 종류가 엄청 많고 다 맛있어보여요!! 사장님과 직원분들도 친절하셔서 좋았습니다!', 13, 1, 'GOOD', SYSTIMESTAMP);
