INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '초코쿠키,딸기크레이프케이크,자허트르테 포장 주문했어요. 2층 매장에 테이블 많아서 먹고 갈까하다가 포장주문했는데 깔끔하게 포장 빨리 해주셔서 좋았어요.', 4, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '친구가 딸기케이크 먹고싶다고해서 찾아가봤어요! 매장은 약간 옛스러움이 느껴지는데 조용한 분위기에 수다떨기 좋았고 음료도 자리에 갖다주셔서 좋았어요! 케이크로 유명한 곳인데, 종류도 많고 가격대는 조금 있는 편이지만 케이크 높이가 높고(ㅋㅋㅋ) 값어치하는 맛이에요 진짜 폭신하고 딸기도 신선하고 엄청 달지도 않아서 넘 맛있었어요! 음료는 얼그레이 라떼 주문했는데 이것도 너무 맛있었네요 적당히 텁텁한 얼그레이향이 나면서 달달해서 디저트로 딱이었습니다:)', 82, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '홍대 케이크 맛집 달콤한 거짓말에 다녀왔어요! 퇴근하고 저녁 시간에 가서 케이크가 많이 없을 줄 알고 걱정했는데 다행히 케이크 종류가 많이 있어서 좋았어요!! 제가 좋아하는 딸기 케이크와 샤인머스캣 케이크를 골랐는데 넘 잘 선택했네요ㅎㅎ 동물성 생크림과 유기농 밀가루를 사용하셔서 그런지 먹고나서도 속이 편하더라구요 너무 달지 않아서 계속 먹어도 물리지 않았답니다! 입에 넣자마자 완전 사르르 녹는 느낌이에요💜 사장님도 친절하셔서 기분이 좋더라구요~ 케이크뿐만 아니라 다른 디저트들도 많아서 구경하는 재미가 있었어요 다음에는 다른 케이크들도 한 번 먹어봐야겠어요! 맛나게 잘 먹었습니다👍', 5, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '오렌지,딸기 모두 과일이 듬뿍이고 생크림이 너무 달지 않아 풍미가 고급스러워요 오렌지는 안쪽에 샌드된 크림에 오렌지가 섞여서 상큼하고 딸기는 아주 정석으로 훌륭합니다 👍🏻', 4, 3, 'GOOD', SYSTIMESTAMP);
