INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '상수역 앞에 이렇게 이쁜 집이 있다니~! 케이크들이 다 너무 이뻐요! 그리고 음료수도 너무 이쁘고 맛있어요 ㅎㅎ 분위기도 넘 좋구~ 다음에 또 상수역 놀러오면 방문할 거에요!', 31, 9, 'GOOD', SYSTIMESTAMP);
