INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '딸기크레이프 케이크 먹었는데 크림이 진하고 맛있었고 딸기랑도 잘 어울렸어요ㅎㅎ 크레이프 사이사이에 샌딩된 크림은 은은한 딸기맛이 나는 크림이어서 더 생딸기랑 잘 어울리는 것 같아요. 신선한 제철 딸기맛이 물씬 나네요', 24, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '홍대 케이크 맛집으로 유명하다고 해서, 조각케이크 3가지 포장해왔는데 하나도 빠짐없이 다 너무 예쁘고 맛있었어요!❤️ 신라호텔 출신 파티쉐가 만드신다고 해서 엄청 기대했거든요 👍👍👍👍 카페는 전체적으로 앤틱한 분위기이고 1층에서 주문하고 2층에서 드실수 있어요. 케이크 뿐 아니라 수제 구움과자들도 엄청 많더라구요^^', 41, 3, 'GOOD', SYSTIMESTAMP);
