INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '딸케 먹고 싶어서 검색해서 왔습니다 딸기가 많이 들어가서 좋았구 무난무난한 맛이였어요 커피는 드립커피였는데 그냥저냥... 그냥 일반 커피랑 다른게 없네여', 25, 1, NULL, SYSTIMESTAMP);
