INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '와..케이크 한입 먹고 딱 감동.. 가격아 좀 비싼가 했는데 가격이상의 맛이에요. 딱 생크림 고급스럽고 한입먹자마자 오랜지 과육이 가득 씹히는데 넘 맛있어요', 42, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '홍대 케이크 맛집 달콤한거짓말🫶🏻 신라호텔파티쉐 출신인 사장님이 만드신 케이크라서 그런지 프랜차이즈 케이크와는 정말 차원이 달랐어요...! 대표메뉴인 딸기 생크림 케이크는 말해 무엇... 퐁신퐁신한 빵에 부드러운 생크림이 입안에서 그냥 녹아요 녹아!! 크레이프도 진짜 맛없없 조합💕 근데 무엇보다 연뽕쓰 원픽 초코바나나!!!! 바나나 달달함 미쳤구요 초코케이크 스초생과 비교할 수가 없어요 ㅠㅠ 리뷰쓰는데 또 먹고싶어요!!😭 * 이 글은 제품만을 제공받아 솔직하게 작성한 글입니다.', 23, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '친구가 가자해서 방문했는데 리뷰만큼의 감동의 맛은 못느꼈어요~ 평범... 매장은 좀 낡았네요 의자도 푹 꺼지고 중구난방같음 날벌레도 많고 ㅜㅜ 흠 재방문 의사는 없습니다', 17, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '유명한 케이크 맛집이라고 해서 다녀왔습니다~ 신라 호텔 출신 파티쉐님이라고 해서 기대를 많이 했는데요~~ 동물성 생크림이라서 크림 자체도 너무 맛있고 빵 시트도 폭시폭신하니 맛있드라구요! 무엇보다 샤인머스켓을 아끼지 않고 풍성하게 넣어 주셔서 집에와서 드립 커피랑 같이 먹었더니 순식간에 없어지더라구요! 상수역에 가면 또 방문해야겠습니다.', 26, 1, 'GOOD', SYSTIMESTAMP);
