INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '미친맛. 이걸로 설명 가능 진짜 맛있음🥹🥹 크레이프딸기&생크림딸기 케이크 먹었는데  적당히 단맛, 부드러움, 과일양 다 만족함 동생이랑 1인 1케이크🍰 한 후에 너무 맛있어서 한입 먹자마자 포장하자! 소리침....ㅋㅋ 실제로도... 포장...😂 눈오는날 30분 걸어서 가느라 진짜 힘들었는데 다음에 또 올거임...ㅎ', 140, 74, 'GOOD', SYSTIMESTAMP);
