INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '딸기생크림 레몬케이크 밤케이크 포장해서 먹었는데 진짜 너무맛있어서 정신차려보니 이미 순삭이었네요....!!! 하나하나 진짜 맛의 조합이 최고예요!!', 28, 9, 'GOOD', SYSTIMESTAMP);
