INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '매장 분위기가 너무 좋네요! 케이크가 하나도 빠짐 없이, 먹음직스러워보여서 고르는데 한참 고민했어요 ㅎㅎ 먹고 가기에도 좋은 환경이고 픽업하고 가도 좋아요! 포장도 깔끔하게 해주십니다 :)', 13, 8, 'GOOD', SYSTIMESTAMP);
