INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '신라호텔 출신사장님이 만든다고해서 방문했어요! 근데 진짜 홍대에서 먹었던 케이크중에 제일 맛있는거같아요!! 얼그레이랑 딸기크레이프랑 단호박케이크 포장했는데 얼그레이에서 진짜 고급스러운 맛나고 생크림에도 얼그레이맛이 진하게 나서 넘 좋았어요!! 비주얼도 예쁘고 매장에도 1층 2층있고 야외좌석도 있어서 좋았어요', 14, 7, 'GOOD', SYSTIMESTAMP);
