INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '친한 언니가 단골이라 같이 갔는데, 거를 타선이 없습니당 디저트 다 맛있구 쿠키 케익 음료 다 짱이에요! 사장님 완전 다저트에 자부심 있으시고 친절하심 또 갈게요!!', 81, 13, 'GOOD', SYSTIMESTAMP);
