INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '딸기 크레이프 너무 기대를 해서 그런지 무난했어요😅 생크림이 아니라 딸기크림이 샌드되어있습니다. 레몬치즈생크림은 정신이 번쩍드는 상큼함입니다😜 케이크들이 달지 않아 부담없는 맛입니당💕', 60, 16, NULL, SYSTIMESTAMP);
