INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '신라호텔 출신 파티쉐님이 직접 만드는 홍대 케이크 맛집이아고 해서 다녀왔어요 ㅎㅎ 세상에.. 생크림케이크가 이렇게 맛있을 줄이야 ㅋㅋㅋ 너무 맛있었고 내부에 자리도 넓어서 좋았습니다! 다음에 또가려구요', 3, 3, 'GOOD', SYSTIMESTAMP);
