INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '상수카페 찾던중 카페 이름이 눈에 띄어서 왔는데 오..케잌 맛집이네요ㅎ 직접 수제로 만들어서 정말 맛나네요! 커피도 맛있고 대화하기도 좋고 재방문의사 있어용ㅎㅎ', 56, 17, 'GOOD', SYSTIMESTAMP);
