INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '집앞에 안가봤던 카페방문, 달콤한거짓말. 신라호텔 출신이시라는데, 맛은 이미 보장이지. 근데 디져트가격이 그렇게 쎈줄 몰랐다.. 망고도 지금 제철이 아니라 맛은 덜했고, 케잌은 너무 맛있었다. 2층에 가는동안 인테리어가 되게 엔티크 했었다. 잘먹었습니다!', 38, 2, NULL, SYSTIMESTAMP);
