INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '크레이프도 맛있고 생딸기도 달달하고 너무 좋았어요! 생크림은 전혀 안 느끼하고 동물성 쓰셔서 그런지 확실히 달고 부드러워요. 시트에는 딸기잼이 넉넉히 발라져 있어서 촉촉하고 뻑뻑한 느낌은 전혀 없었어요! 중고등학생 때부터 지금까지 못해도 1년에 한번씩은 꼭 방문하는 매장이에요ㅎㅎ 이번엔 연말 케이크 여기서 구매하려구용🥰', 26, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '연말 모임에 케이크 찾고 있었는데 전날인데도 예약주문 가능해서 좋았어요. 딸기 상태도 좋았고 케이크도 맛있었고 양도 많아서 정말 최고입니다. 같이 먹은 친구들도 나중에 케이크 주문할일 있으면 여기서 하고 싶다고 했어요ㅎ 저도 또 먹으러 갈것 같아요 진짜정말진심대박 최고', 23, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'MEETING');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '여기 케이크 제 인생케이크ㅠㅠㅠㅠ 크레이프케이크 여태까지 맛있게먹어본적이없는데 한번 먹어봤거든요 진심 존맛,, 친구들한테도 얘기했더니 제가 크레이프케이크 맛있다고한곳 처음이라고 홍대가면 들려본대요 다른케이크도 다 맛있지만 딸기크레이프 진짜 ㅜㅜㅜㅜㅜ 홍대갈때마다 사올거에요!!', 16, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '상수가면 꼭 포장해오는 케이크맛집! 종류도 다양한데 크기도 크고 덜 달고 맛있어서 어른들도 좋아함! 가을 시즌에 맞춰나온 알밤크림케이크 강추!', 26, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '상수역에서 케이크 맛집 찾다가 발견한 달콤한 거짓말! 상수역 골목에 숨어있는데 사장님이 신라호텔 출신 파티쉐 사장님이 운영하셔서 그런지 케이크 종류도 다양하고 정말 다 호텔 디저트마냥 비주얼도 이쁘고 맛도 풍부해요ㅠ 얼그레이 맛이 이렇게 고급지게 나는 얼그레이 케이크 오랜만이에요! 레몬치즈 생크림 케이크도 달콤하고 쌉쌀한 신맛이 조화로워서 무작정 단 그런 케이크랑 다르더라구요! 초코 바나나케이크도 원래 바나나 빵에 들어가는거 별로 선호하지 않는데 비주얼에 반해서 사왔는데 초코크림이랑 바나나랑 정말 잘어울리더라구요! 홍대 케이크 맛집 인정입니다! 장인 사장님도 친절하시고 케이크도 정말 잘핫네요!!최고!', 15, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '자리가없어 화장실앞 좌석에 앉았는데 화장실 통풍이 안되는지 문이 열릴때마다 냄새가 나더라고요ㅠㅠ 마침 음식이 나오기전 옆의 다른 자리가 비어 이동했더니 서빙하러 오신 젊은 탈색머리 직원분이 짜증스러운 어투와 표정으로 자리 옮기지 말라고 하셔서 좀 황당했어요. 음식 나온뒤 옮긴것도 아닌데;; 바빠서 신경질적이 되실수 있는건 이해하지만 친구와 즐거운얘기 하러가서 그런 응대를 받으니 계속 마음이 안좋더라고요. 애정하는 가게인데 아쉽습니다.', 37, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '케이크 3개 포장해왔는데 전부 다 맛있어서 행복했어요. 훌륭한 비주얼과 기대를 져버리지 않는 맛! 달콤한 거짓말은 아마 맛있으면 살안쪄..가 아닐까ㅋㅋ 근처 들르면 꼭 다시가고 싶은 디저트 맛집입니다!', 23, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '가족들과 식사후 디저트로  먹고싶어서 케이크샀는데 완전 존맛탱 사장님께서 신라호텔출신 파티쉐라고 하시더니 진짜 케이크맛이  고급스러워요!!^^ 최고당 부드럽고 다양하고 고급스러운 맛남!!!ㅋㅋ 고급 케이크 선물할때 짱 좋을것같아용', 81, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '케이크 맛집으로 유명한 가게라 시간될때 바로 방문했습니다 역시 사람 사는 거 다 똑같다고 복숭아홍차생크림을 노리고 갔는데 하나밖에 안남았더라구요 제가 겟챠했습니다✨ 생크림이 진짜 맛있고 시트도 폭신하니 맛있어요 딸기 크레이프도 유명한 이유가 있더라구요 존맛탱..💝 빙수도 맛있다던데 다음엔 빙수 먹으러 방문하겠습니다☺️', 122, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '몽블랑, 자허토르테, 크레이프까지 맛있는 케이크가 많아서 고르느라 고민했어요. 카페에서 먹어도 좋지만 한시간 거리 걸리는 포장도 전혀 망가지는 거 없이 잘 가져올 수 있어서 좋네요! 수제 캐러멜이나 브라우니도 맛있어보이는 게 많고 이제 빙수도 개시했더라고요 홍대케이크 제일 좋아하는 곳인데 다음엔 매장서 먹으러 갈게요!', 122, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '뽁뽁이로 포장해주셔서 흔들리지않고 가지고올수있었어요 😄 엄청 고급스러운 달달함인데 우유맛 가득 느껴지는 진한 생크림이 부담스럽지도 자극스럽지도 않아서 계속 먹게되더라구요 디저트 좋아하시는분들은 오시면 너무 좋아하실듯', 61, 12, 'GOOD', SYSTIMESTAMP);
