INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '달콤한거짓말 홍대케이크로 워낙에 유명하죠 크레이프케이크는 진짜 명불허전~ 서울에서 제일맛있는거 같아요. 동 물성생크림 사용하는 고퀄 케이크맛집입니다.', 8, 5, 'GOOD', SYSTIMESTAMP);
