INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '다양한 곳의 케이크를 먹어봤지만 딸기 생크림 케이크는 달콤한 거짓말이 최고에요🍰 친구들한테 추천해줘도 후기가 항상 좋아서 믿고 추천해주고 있어요😆 10년 넘게 꾸준히 찾을 수 밖에 없는 곳이에요😍', 0, 2, 'GOOD', SYSTIMESTAMP);
