INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '홍대 케이크 맛집이에요~ 전문 셰프님이 만드시는 디저트라 정말 맛있어요 엄청 달지도 않고 딱 좋아서 커피랑 잘어울린답니다 게다가 2층이 아늑해서 편안하게 수다떨 수 있어요!', 92, 25, 'GOOD', SYSTIMESTAMP);
