INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '평일 저녁에 가니까 사람도 많지 않고 분위기 있어서 좋았어요!! 빙수랑 크레이프 케이크 시켰는데 다음엔 일반 케이크도 먹어보고 싶어요', 7, 6, 'GOOD', SYSTIMESTAMP);
