INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '크림이 많이 달지 않고 고소해서 계속 들어가요!! 신선한 과일 부드러운 시트 고소한 크림이 완뵥히 조화로웠어요!! 늦게까지 영업해서 담에 2차로 케이크 먹으러 또 갈게요🧡🧡', 16, 4, 'GOOD', SYSTIMESTAMP);
