INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '커피가 일반얼음 뿐만이 아니라 커피얼음까지 함께 있더라구요!! 센스있는 세팅에 감동했습니당 케이크도 달지 않고 과일 역시 맛있는 과일만 사용하신 덕에 최고였습니다😋', 37, 4, 'GOOD', SYSTIMESTAMP);
