INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '예전에 포장해서 먹었던 빙수와 케익이 맛있어서 다시 방문했습니다. 크레이프케익 넘 부드럽고 초코케익은 초코맛이 고급스러웠습니다. 요거트음료도 찐하고 달콤해서 맛있었습니다.^^', 22, 4, 'GOOD', SYSTIMESTAMP);
