INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '케이크가 맛있어요. 개인적으로 녹차들어간 케이크를 추천합니다. 테이블마다 케이크가 꼭 들어가있던데 먹고서 이유를 알게 됬어요!', 12, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '합정역에서 상수역 가는 방향에 작은 골목길에 위치한 가정집을 개조한 카페에요. 분위기부터 남다르고 파티쉐가 만든 수제 케이크가 하나같이 맛이 좋더라고요. 2층 카페 공간이 넓고 테라스와 산장같은 느낌이 편안하고 오래 머물다 갈 수 있을 것 같아요. 케이크와 디저트류가 풍성해서 꼭 추천하고 싶어요.', 48, 4, 'GOOD', SYSTIMESTAMP);
