INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '일단 사장님이 친절하세요! 빙수가 뚝배기에 나온거 너무 웃겼어요 ㅋㅋㅋ 딸기케잌도 맛있는데 제 입맛엔 망고빙수가 더 맛있었어요! 아메리카노도 산미 없어서 제 취향이었어요~ 자리가 편하고 좌석이 띄엄띄엄 있어서 얘기하기 좋았어요!', 21, 9, 'GOOD', SYSTIMESTAMP);
