INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '홍대에 디저트집 정말 많이 다녔었는데 제일 맛있었던 곳이에요❤️ 딸기크레이프 케이크는 인생케이크 등극했습니다,,🥹 겹겹이 쌓인게 촉촉하고 부드러운게 너무 맛있어요.. 자허토르소는 꾸덕한데 진한 달달함이 좋았고 얼그레이도 엄청 찐해서 다 커피랑 찰떡이더라고요!! 매장도 넓고 예뻤는데 다음엔 매장 이용해봐야겠어요🙌', 36, 0, 'GOOD', SYSTIMESTAMP);
