INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '친구 생일로 부랴부랴 케이크집 찾다 방문한 곳이에요! 맛이 어떨지 아무 확신 없는채로 구매했었는데 결론은 최고였습니다! 친구가 정말 요근래 먹은 케이크 중 최고였다고 너무 만족해서 제가 더 기뻤습니당!!!! 아무래도 저도 따로 가서 사먹어봐야겠어요..!! 그러므로 추천하는 디저트집입니댜~!~!~!!~', 20, 10, 'GOOD', SYSTIMESTAMP);
