INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '케익이 너무 예쁘고 신라호텔 출신 파티쉐가 만드셨다고 하더니 정말 맛있었어요😆 다음에는 특별한날에 홀케이크로 주문해서 선물해야 겠어요 선물용으로도 너무 좋은 예쁜 케익이에요😍', 14, 3, 'GOOD', SYSTIMESTAMP);
