INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '조각케이크 자허토르테, 치즈파레트, 레몬치즈생크림을 테이크아웃 했어요! 너무 친절하게 응대해주신 사잠님 덕분에 편안한 시간도 즐기고요. 다음날 직원들과 나눠 먹는데 다들 칭찬 일색이네요🫶 번창하세용', 51, 14, 'GOOD', SYSTIMESTAMP);
