INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '친구 추천으로 같이 가봤는데 생크림 케이크 너무 맛있네요! 폭신폭신하구 맛있었어요! 아이스 커피에 얼음을 커피로 얼려서 그런지 비주얼도 좋았어요😊', 35, 2, 'GOOD', SYSTIMESTAMP);
