INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '약속이 있어서 포장으로 이용 했는데요. 케익이 움직이지 않게 포장도 잘해주셨고 한참 걸어왔는데도 모양이 손상되지 않았어요. 케익 종류도 다양하고 맛있습니다. 예뻐서 선물하기도 좋을 것 같아요. 다음엔 시간만 된다면 2층에서 맛있는 디저트 타임을 갖고 싶어요.', 36, 6, 'GOOD', SYSTIMESTAMP);
