INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '홍대 케이크 맛집으로 유명해서 케이크 종류도 많고 비주얼도 예쁜데 다맛있어요! 동물성크림이라 고소하고 부드러워요😊 특히 딸기 들어간 케이크는 꼭 드셔보세요 최고입니다:) 스콘, 브라우니, 쿠키, 파운드, 카라멜, 피칸파이 등 다양한 디저트들도 있어서 다음에 꼭 먹어봐야겠어요!', 7, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '딸기케이크 너무 맛있어요!! ㅎㅎㅎ 케익 맛집이 확실하네용 생크림은 달지 않게 맛있구 딸기철이 아닌데도 이렇게 맛있을 수 있나욬ㅋㅋㄱㄱ', 94, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '홍대 상수역 가까이에 이런 케이크집이 있었다뇨!! 케이크 종류도 많고 무엇보다.. 완전 맛있다는거🤩 딸기듬뿍생크림, 초코딸기듬뿍 생크림이 정말 사르르 녹는게! 정말 부드럽고 촉촉해요!!! 치즈파레트는 크림치즈 맛이 진하게 나는 달달한 케이크라 달콤한 디저트 땡기신다면 딱 좋음 :) 담엔 홀케이크로 포장해가도 좋겠다고 생각했어요🤩', 44, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '홍대에서 발견한 케이크 맛집이에요! 너무 맛있어서 먹는 내내 기분이 좋았 어요! 저는 테이크아웃 했는데 포장도 꼼꼼히 잘 해주시고 집에서 먹어도 케이크 변형 없었구요 !! 생크림도 고소하고 생과일도 듬뿍 들어 있어서 너무 맛있었어요❤️ 직원분들도 모두 친절했습니다 : ) 왕추천 합니다~ 또 방문할게요 👍🏻', 29, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '여기 얼그레이라떼 진짜 존맛탱이에요. 여기 처음 왔을때 이거 먹고 다른집 밀크티 못 먹었어요. 여기만큼 맛있는 얼그레이라떼 못 봤어요. 꼭드세요. 딸기 생크림 케익두 최고.... 멀어서 자주는 못와도 홍대오면 여기 먹을 생각에 행복해요. 아 이미 지하철 탔는데 밀크티 한잔 더 시켜서 테이크아웃 해올걸,...또 먹고싶다...아...', 53, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '레몬치즈생크림. 알밤크림케익.딸기크레이프  3가지 모두 정말 맛있어요~^^ 고급진 케이크라서 순삭했어요~ 홍대 케이크 맛집 인정해요!  재방문 또 할래요~😊😀', 28, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '홍대부근에서 가장 맛있는 디저트카페라고 생각해서 종종 가요. 그런데 이번에는 앞에서 케이크 고르고있었는데 알바인지뭔지 모르겠는 여자 직원이 곧 영업종료인데 먹고갈꺼냐고 짜증내듯이 물어봐서 기분 나빴어요.', 43, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '상수역 디저트 맛집 달콤한 거짓말! 정말 먹음직스럽게 생긴 케이크가 많아서 잠시 결정장애가 왔더랍니다. 치즈파레트, 화이트얼그레이, 딸기크레이프 포장해서 집에 와서 먹었는데 정말 맛있었어요. 재방문의사가 백퍼있어요^^', 16, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '내부도 아늑하고 대화하기 좋아요 :) 무엇보다 케익이랑 커피가 정말 맛있어 사장님 납치하고 싶어지는 곳..😊 신라호텔 파티쉐 출신이라던데 그래서인지 케익맛이 고급의 끝이에요ㅎㅎ 이번엔 포장만해왔는데 다음엔 꼭 앉아서 커피랑 같이 먹고올꺼에요!!!', 42, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '케이크 맛집이라서 평소에 맛있게 먹었었는데 집에서 가족들이라 먹으려고 따로 사왔어요 초코랑 기본 생크림 케이크만 먹다가 다른맛도 사왔는데 생각보다 맛있고 좋았어요! 그치만 진리는 초코케익!!ㅋㅋㅋㅎㅎ 다음에 또갈께요', 114, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '합정으로 이사온 후 여기 저장해 놓고 계속 먹어봐야지 하다가 바빠서 못 오다가,, 드디어 오늘 포장해 와서 먹게 되었습니다. 기대한 만큼 역시 맛있었고 그야말로 순삭했습니다. 일부러 시간을 내서라도 다른 케이크도 하나씩 도장깨기 하려고 합니다!!! 다음에는 레몬케이크 먹어야징 🍋', 68, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '딸기듬뿍생크림, 자허토르테(초코케익) 정말 맛있어요! 생크림이 달지도 않고 담백하면서 부드러워요~ 리얼브라우니(레드벨벳)는 맛이 특이해서 저희한테는 좀 낯선 맛이었어요. 음료도 맛있고,, 무엇보다 사장님이 엄청 친절하셨어요~^^ 다음에 또 가고 싶은 카페에요. 친구들이 가까운 카페 가자고 했는데, 제가 친구들한테 케익 맛집이 있다고 데리고 간 거 였거든요. 혹시나 입에 안맞을까봐 저혼자 내심 걱정했었는데, 사장님이랑 알바생분이 처음 온 저희한테 친절하게 설명도 해주시고 케익 넘 맛있고 뜨거운 물도 챙겨주셔서 친구들도 넘넘 대만족이었어요!! 감사합니다 ~^^', 9, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '사진 찍을 생각이 없었는데도 이건 남겨야겠다하고 찍었어요 🥹🥹케이크 진짜 맛있어요 😮‍💨❤️❤️친구 소개로 간 카페였는데 종류도 진짜 많구 친절하세요!! 친구는 얼그레이 케이크가 최애라고 다음에 오면 꼭 먹어보라고 해서 또 찾아 가려구요!! 친절하시구 종류도 많구 좌석도 편하구 정말 맛있게먹었습니다 ㅎㅎ 👍👍', 80, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '케이크 진짜 존맛도리에요ㅠㅜ 특히 알밤크림케이크...밤 안 좋아하는 저도 엄청 맛있게 먹엇음다. 적당히 달달해서 계속먹게되는 맛이에요!!!어르신들 선물로 드려도 좋아하실것같아요', 82, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '호텔신라에서 하셨던 파티쉐분이 하는곳이라 기대했는데 역시나 좋았어요👍👍 요새 케이크 가격 보통 9000원대인데 7천원대라 착하고 재료도 좋은걸 쓰는게 느껴졌고 동물성이라 크림 느끼하지않고 단백하면서 고소해요~👏👏 가니까 딸기듬뿍 없어서 여쭤보니 20분정도면 새로 나온다고하셔서 커피 먼저 드리겠다고 정말 친절하시더라구요🤗 여기 케이크 단골해야겠어요~! 정말 케이크맛으론 최고~! 너무 과하게 달지않고 담백하면서 고소해서 취저~🥰', 9, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '케이크맛집이네요 디저트 맛나다고 소문이 나서 방문했는데 오우 비주얼도 예술이더라구요 매장에서 먹어도 되지만 포장해 왔어요 같이간 동생한테는 아이들 주라고 포장선물했더니 사진도 보내왔네요 맛있어서 애들이 넘 좋아한다구요 저도 오후에 당 떨어질 때 커피랑 먹었는데 인생 케이크, 인생 디저트네요 어쩜 많이 달지는 않으면서도 맛난지... 담에 가면 다른 아이들로 델고 와야겠어요 딸기도  무척 싱싱하고 달아서 굿', 4, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '케이크 맛집이에요. 비주얼도 너무 예쁘고 종류도 다양하고 크림이 진짜 맛있어요. 녹차케이크는 꾸덕해서 맛있었고 알밤케이크는 특이하면서도 달달하고 부드러워서 좋았어요 케이크 최고입니당😋😋😋😋😋', 34, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '몇 년만에 다시 찾은 골목사이에 숨겨진 비밀의 장소같은 달콤한거짓말 다행히도 케이크의 맛은 변함없이 쫀득하니 부드러웠어요 :)', 66, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '크림이 너무 맛있구요..특히 화이트 말차 초콜릿 케이크 너무 맛있어요 완전 진한 말차+화이트초코도 먹어본것중 최고 ㅠㅠ 벨기에산 초콜릿이 이런거군요.. 너무 장인정신 느껴지고 맛있어서 감격', 48, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '할무니 생신이신데 그저그런 케이크들 말고 정말 퀄리티 있는 맛있는 케이크 드리고 싶었어요! 눈도 즐겁고 맛도 있고 할머니도 저도 너무 만족 했어요! 다음이는 홀케이크도 사러 가고 싶어요!🥰🥰', 3, 4, 'GOOD', SYSTIMESTAMP);
