INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '옛날부터 가보고 싶던 곳 드디어 가봤네요 케이크 비주얼은 최곤데 맛은 기대 이하.. 크레이프 먹었는데 굳이 찾아가서 먹을 맛은 아닙니다.. 편의점 크레이프가 나을듯한 맛..', 10, 1, 'BAD', SYSTIMESTAMP);
