INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '레몬생크림케이크 먹었는데 시고달고 맛있었어요! 음료도 낫베드ㅎㅎ 직원분께서 직접 가져다주셨고 1층,2층있고 적당히 아기자기한 느낌이예요 대화하기 좋았어요! 근데 전체적으로 가격이 후덜덜하긴합니당..!', 114, 23, 'GOOD', SYSTIMESTAMP);
