INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '케이크류는 다 맛있는 것 같아요. 제 입맛에는 말차가 가장 맛있었어요 너무 달지 않고 향도 느껴졌구요! 집에 레몬쿠키랑 피넛브라우니를 사갔는데 피넛브라우니는 많~이 다니까 참고하세요! 대화하기 좋고 사장님이 자리 편하게 친절하게 살펴주셔서 좋은기억으로 남아 있어요. 다만.. 2층 창가자리가, 창가에 외풍이 들기도 하고 거미줄이나 먼지가 많아서 청소해주셨으면 좋겠어요. ㅠㅠ', 94, 23, NULL, SYSTIMESTAMP);
