INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '유명하다는 딸기케이크는 다 먹어보는 중인데 정말 크림이 신선하고 너무 맛있어요!!!!!!! 하루만에 다 먹어버려서 또 사러 가야해요 ㅠㅠㅠㅠㅠㅠㅠㅠ', 111, 19, 'GOOD', SYSTIMESTAMP);
