INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '딸기생크림케이크 생각나면 무조건 여기 옵니다. 너무너무 맛있어요ㅜㅜㅜ딸기 엄청 듬뿍! 매장에서는 처음 먹어봤는데 2층에 꽤 자리가 많고 좋아요. 초코딸기도 맛있더라구요. 초코시트에 생크림에 딸기.. 최고', 64, 11, 'GOOD', SYSTIMESTAMP);
