INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '골목 구석에 숨어있는 가게인데, 어렵사리 찾아들어가보니 여자들이 귀신같이 찾아모여 케이크사고 있어서 웃겼습니다.ㅎㅎ 케이크맛집입니다. 크림도 빵도 부드럽고 맛있어요.', 4, 7, 'GOOD', SYSTIMESTAMP);
