INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '처음 와봤는데 케이크랑 커피 너무 맛있어요! 크레이프케이크 맛집이네용 ㅎㅎ 분위기도 조용하고 아늑해서 혼자서 책 읽기도 좋은 곳 같네요. 다음에 또 갈래요!', 62, 14, 'GOOD', SYSTIMESTAMP);
