INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '카페 디자인이 뭔가 친근하면서 로컬한 분위기..!! 디저트가 너무 달지 않아서 좋았어요! 생크림 맛있었습니당..🥰 비슷한 가격대의 맛있는 디저트가 많았는데 1인 1메뉴에 음료와 케이크만 적용되는 부분이 아쉬웠어요..😢 담에 언제 한번 브라우니 포장해 가서 먹어보고 싶네요😊', 38, 10, NULL, SYSTIMESTAMP);
