INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '케익 다 맛있어요 ㅋㅋ특히 무지개색 치즈파레트!! 당근케익에 있는 치즈크림이 가득 있는데 완전 맛있네요ㅋㅋ골목 구석에 있는데 금방 만석되고 기다려야함ㅋㅋ포장해서 선물하기도 좋음', 43, 2, 'GOOD', SYSTIMESTAMP);
