INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '이렇게 예쁘고 맛있고 무거운 케이크 처음이예용ㅋㅋㅋㅋㅋ 치즈가 꽉꽉 들어가있고 시트도 무지개색 사진 완전 예쁘게나와용 ㅎㅎ 친구 생일파티 잘 했어용!! 감사합니당', 235, 53, 'GOOD', SYSTIMESTAMP);
