INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '조각 케이크가 일단 다른 곳보다 무지 큽니다. 왕조각.ㅋㅋㅋㅋㅋ 그리고 정말 맛있어요. 특히 딸기 생크림 대존맛  여러분 딸기생크림 꼭 사세요.', 146, 91, 'GOOD', SYSTIMESTAMP);
