INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '케이크 종류가 진짜 많아서 좋아요 ! 초코딸기케이크 개인적으로 강추합니다 크림과 시트 비율이 좋아서 느끼하지 않고 과일도 아낌없이 넣어서 만족스러워요 :) 레몬케이크도 상큼하니 입가심돼서 추천해요', 51, 15, 'GOOD', SYSTIMESTAMP);
