INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '케이크가 진짜 너무너무 맛있어요 .. 생크림이 너무 달지 않아서 술술 들어가는 신기한 맛.. 다른 케이크들도 궁금해지는 맛입니당 .. 음료도 맛있고 담에 또 오고싶어요!!!!🥹🤍', 33, 5, 'GOOD', SYSTIMESTAMP);
