INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '골목길에 살짝 숨어져있었군요!!! 딸기생크림을먹고팠는데 크레이프를 주셨지만 담에 와서 또 먹어볼게요~~ㅎㅎ 얼그레이티도 짱맛!!! 수제카라멜도 너무 맛있네용ㅎㅎ인테리어도멋있고~~~신라호텔출신이시고..노년멋지게보내시는거같아부럽네요ㅠㅜㅎㅎ사장님 번창하세요~~~', 44, 5, 'GOOD', SYSTIMESTAMP);
