INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '아이랑 먹을 조각케잌 사러갔는데 종류 다양하고 시트가 촉촉하고 너무 맛있어요. 생크림도 많이 먹어도 안느끼해요👍 포시즌이랑 조선호텔. 신라호텔 케잌 다 먹어봤는데 신라호텔 파티쉐 출신이라 그런지 호텔 케잌 못지않은 너무 맛난 케잌이었네요. 자주 갈듯요', 42, 8, 'GOOD', SYSTIMESTAMP);
