INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '빙수를 기대하고 갔는데 케이크가 더 맛있었어요!!! 같이파는 브라우니랑 쿠키들도 너무 맛있어보였습니다. 카페 넓어서 일행들과 대화하기 좋았어요!', 130, 22, 'GOOD', SYSTIMESTAMP);
