INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '레몬, 얼그레이, 녹차 이렇게 세 가지 조각 케이크 포장주문했어요! 신라호텔 출신 파티쉐라고 하셨는데 진짜 맞네요... 다 재료 본연의 맛이 살아있으면서 너무 맛있더라구요 ㅠㅠ 특히 얼그레이는 다쿠아즈 시트에 얼그레이를 적셔놓으셔서 얼그레이 그 자체...❤ 아이디어도 대박이고 맛은 더 대박이었습니다!!👍', 60, 12, 'GOOD', SYSTIMESTAMP);
