INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '정말 너무 달지도 않고 입에서 살살 녹는 생크림 같아요! 왜 케이크로 유명한 지 알게 됐어요! 가격은 좀 있지만 생각 날 때 사먹을 것 같아요!', 41, 6, 'GOOD', SYSTIMESTAMP);
