INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '제가 먹어봤던 케익 중에 가장 맛있어요.. 진짜 맛있네요ㅠㅠㅠㅠ 주변에 널리널리.. 알리는 중입니다만 제가 홍대 근처 갈 때마다 한 조각씩 사 먹으려고요!다른 종류 케익들도 기대되는 맛이네용💐', 22, 0, 'GOOD', SYSTIMESTAMP);
