INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '케이크가 유명하다고해서 갔는데 역시나 맛있었습니다. 그리고 특별하게 느껴진건 카라멜!!! 딱딱할까봐 걱정했는데 부드럽고 맛있어요 솔티 카라멜 꼭 꼭 먹어봐야하는 디저트예요', 41, 1, 'GOOD', SYSTIMESTAMP);
