INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '옛날부터 가끔씩 가던 카페인데 디저트 종류도 많고 분위기도 편해요! 비 많이 왔었는데 전철역까지 우산 빌려주셔서 친구들 보내고 와서 돌려드렸어요. 너무너무 감사했습니다!', 46, 0, 'GOOD', SYSTIMESTAMP);
