INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '포장해서 집와서 친구들과 먹었는데 왜이리 맛있나요 ㅠㅠ 감탄하면서 먹음 크림도 무겁지 않고, 가벼우면서 상큼해요,, 진짜 짱입니다요 사장님의 내공이 느껴지는 맛! 다른 메뉴도 먹어보고 싶네요,, 합정이나 상수오면 자주 올 것 같아요❤️ 케익 맛집임다 🎂🍰🧁', 21, 5, 'GOOD', SYSTIMESTAMP);
