INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '케이크 맛집이라고 그래서 한번 꼭 가보고 싶었는데 케이크랑 디저트가 진짜 맛있어요…재방문 의사 100퍼 한번은 갔다가 문 안열려있어서 (네이버에는 운영중이라고 되어있었는데 닫힘) 그래서 못가서 담날 가보니까 열려있더라구요 쉬는날이 언젠지 모르겠어요.', 32, 6, 'GOOD', SYSTIMESTAMP);
