INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '음....흠...케잌.달지않쿠  맛있는데  그냥쏘쏘인데요 ㅎㅎㅎ평이너무좋아서 너무기대가컷나봐용 특히...카페분위기가  너무올드해서 ㅠㅠ 맛이더안나용 ㅠㅠ너무친절하셧는데  죄송해요 ㅠㅠ', 36, 2, NULL, SYSTIMESTAMP);
