INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '포장만 하느라 잘 몰랐는데 응대가 좋은 곳은 아니다. 그리고 여러 개 사도 가게 방침이라며 끈 없는 작은 종이봉투만 주니 가방 챙겨가시길. 친환경정책 다 좋은데 계산 전에 생각해볼 시간을 주든지 작은 가방 하나 들고 왔다가 손에 주섬주섬... 결제취소하고 싶었다.', 39, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '딸기 케이크 진심 존맛👍 신라호텔 출신 파티쉐 라고 하시던데 제 인생 케잌이 신라호텔 딸기 케이크 인데 진짜 딱 그 맛이었음. 딸기 완전 듬뿍. 초코 케잌도 농도 엄청 진하고 맛있어요', 48, 3, 'GOOD', SYSTIMESTAMP);
