INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '히♡♡♡ 여기 넘 유명하죠 예전에 홀케이크 주문한  적도 있는데 오랜만에 가봤어용 여전히 넘 맛난 케이크들...!! 또 갈께요', 39, 10, 'GOOD', SYSTIMESTAMP);
