INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '호텔 빠띠쉐 출신이신 분이 하시는곳이라 맛있다고 해서 찾아갔는데 정말 맛있습니다 케익도 케익이지만 자두음료가 유니크하네요 더운 여름에 가면 완샷각 주차가 안되니 차는 두고 가세요', 224, 82, 'GOOD', SYSTIMESTAMP);
