INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '가격이 좀 있지만 맛있고 알찬 맛이에요!~~ 케이크 넘 예쁘고 귀여워요...♥ 생크림이 느끼하지 않고 맛있었습니다~ 케이크 포장했는데, 움직이지 않게 포장을 잘 해주셨어요! 다만 케이크 상자 손잡이가 뾰족해서 들고갈때 손이 좀 아픈..ㅎㅎ', 33, 3, 'GOOD', SYSTIMESTAMP);
