INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '저번에 조각케익과 브라우니 등 구매했는데 맛있게 잘 먹었어요! 얼그레이 케익이 특히 인상적이었어요 ㅎㅎ 얼그레이 향도 좋고 너무 달지 않고 맛있었어요. 이번에 마카롱 구매해서 친구한테 선물하려고 합니다 ㅎㅎ 마카롱도 큼직한데, 친구가 좋아했으면 좋겠네요.', 0, 10, 'GOOD', SYSTIMESTAMP);
