INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '디저트 맛집! 신라호텔 출신 피티쉐가 만들었다는 입간판 보고 들어갔는데 정말 맛있어요! 👍👍 여러가지 디저트 판매하고 있는데 다 먹어보고 싶네요 :)', 27, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '금일 5/31(화) 18시 25분경 방문하였습니다. 방문 당시 아이스아메리카노 2잔, 파운드케이크 1개, 딸기조각케이크 1개, 딸기홀케이크 1개를 결제하였습니다. 여자 알바분께서 결제를 직접 진행하셨고, 결제한 케이크에 대해 추후 가져갈 수 있게 냉장 보관해준다기에 저희는 두시간 넘게 카페에서 머물렀으며, 20시 35분경 집에 가기 위해 결제 영수증을 보여드리고 결제한 케이크를 수령하려는 순간 알바분은 무슨말을 하냐는 식으로 반응하고, 사장님께서 이름을 적어두지 않아 알바가 다른 손님에게 해당 케이크를 판매하였다고 하시는데 9시가 다 되어가는 시점에서 어르신이 드실 케이크를 치즈 케이크로 구매하기도 그렇고 기존 결제 취소후 재결제 진행하였으며, 사장님과 해당 알바분의 대응에 조금 아쉬움과 실망감이 남습니다', 9, 2, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '사장님이 정말 친절하십니다! 디저트가 다 맛있어보여서 삼만원넘게 긁었네요ㅋㅋ 돈쓴 보람이 있는 맛이었어요 딸기 케이크가 짱맛이었어요 커피에 얼음도 특별하게 올라가있어서 녹아도 맛있었어요! 커피 추천도 해주시고 디저트도 맛있지만 사장님 친절하셔서 다시 가고싶은 곳이네요 자리까지 가져다 주셔서 주문하고 편히 얘기 나누고 있을 수 있어서 좋았습니다!^^', 38, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '아아가 너무 연합니다. 사진은 조금 마시고 찍었습니다. 보리차 마시는줄 알았네요. 신경 써서 커피 얼음 넣어주시는 것은 좋은데 샷 제대로 들어갔나 의심스러울 정도네요. 다른 테이블보니 색이 다르던데 다들 샷 추가하셨나 생각이 들었네요. 커피가 이러니 기분이 나빠서 케이크도 절반정도 먹고 금방 일어났네요. 신라 출신이시면 패스트리부띠끄에서 일하셨다는 것인데 경력에 비해 케이크도 실망스러웠네요. 저는 재방문할 일 없을 것 같습니다', 67, 15, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '분위기 너무 좋고 입구는 유럽느낌 폴폴~ 합정 달콤한 거짓말에서 힐링하고 갑니다 ~ 물론, 홀케잌도 눈에 들어왔는데 무적권 기념일에 달 거에서 홀케잌 구매할그에용', 9, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '진심 직원분들 너무 착하셔요 ㅠㅠ 미친거 아니냐고ㅠㅠ 이런 친절함 너무 좋아요😭😭👍🏻 저 여기 다시 와도 되죠? 첫방문인데도 불구하고 들어오자마자부터 너무 기분 좋아졌어요!! 아 그리고 몰랐는데 여기 2층도 있더라구요! 진심 놀램🤭 2층도 이뽀이뽀영🥰 진심 여기 올만한 가치 1000000•••%‼️ ((소근)사장님 뿐만이 아니라 직원분들도 다 착하셔요❤)', 47, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '자리가 좀 좁았지만 직원분들이 친절하시고 자리로 케이크를 가져다 주셔소 편했습니다 웨이팅이 있어도 생각보다 오래 기다리지 않았어요', 31, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '신라호텔 출신의 파티셰 사장님이 운영하신다고 해서 기대했는데 솔직히 말하면 기대했던 만큼의 맛은 아니었어요 물론 재료나 여타 환경을 생각하면 신라호텔 수준의 퀄리티를 기대할 순 없겠지만 워낙 맛있는 케익이나 디저트가 많은 주변 상권을 생각하면 꼭 이곳에 와야겠다는 생각까지는 들지 않았어요 하지만 케익이나 마카롱 모두 훌륭한 맛이었고 레몬케익은 상큼하면서도 부드러운 맛이 매력적이었어요👍🏼', 23, 8, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '최근 1년간 가본 디저트 카페중에 가장 취향에 잘맞는 카페였음.  인테리어도 멋지고 선물용 쿠키나 호두가 정말 맛있음.  부모님 선물용으로 좋아보임', 41, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '달거 마카롱이 짱입니다. 요즘 나오는 뚱카롱들이랑 다르게 꼬끄랑 비율도 좋고 크기도 크고 맛도 좋아요! 오늘은 케이크 사가지만 다음엔 마카롱 사러 또 갈게요~', 110, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '커피 케이크 맛있고 분위고 좋고 다 좋습니다!(화이트초코녹차강추) 정말 다 좋은데ㅠㅠ사장님 이 리뷰 꼭 봐주셨으면 좋겠는게, 음악소리가 너무 카페랑 안어울리고 소리가 큽니다...덕분에 다른분들도 대화할 때 막 목소리가 올라가는 것 같아서ㅎㅎ 노래를 재즈 피아노 같은 카페에 어울리는 잔잔한 음악으로 깔아주시면 훨~씬 좋을 것 같습니다', 21, 3, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '사장님은 친절해보이셨지만 알바생 여자분 너무 불친절해요 인사 1도 없고 .. 뭔가 너무 불친절해서 케익 맛 까지 별로였어요 네명이서 35,000원 쿠키두종류 캐익 세종류 시켰는ㄷㅔ 1인 1주문이라면서 캐익이나 음료를 더시키라고 하더라고요 뭐 이런곳이 다 있나 싶습니다 ㅡㅡ', 16, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '사장님은 매우 친절하신듯 하나 알바생이 상당히 불친절함. 주변 음식점 방문전 시간이 남아서 인터넷 검색해서 케이크 사러 방문해서 케이크 이외 견과류 쿠키까지 총 삼만육천원 가량 구매했으나 1인1메뉴 원칙이고 견과류 쿠키는 메뉴에 포함안된다며 앉아서 취식하는 것은 불가능하다며 매우 불친절하게 이야기함. 아메리카노 한잔 시키는 손님보다 최소 그 금액 이상은 구매한거 같고 시간이 남아서 잠시 앉았다 가려했는데 그러지 못하고 그냥 포장해서 나옴. 단순 1인1메뉴 원칙보다 금액적으로도 합리적으로 판단했으면 좋겠음', 10, 7, 'BAD', SYSTIMESTAMP);
