INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '케익 맛있음 가성비최고 요새 카페들 가면 좀 빡빡하단 생각이 드네요 사람 한명도 없는데 굳이 2인석에 앉으라고 말하는건... 쫌', 27, 0, NULL, SYSTIMESTAMP);
