INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '홍대 근처에 케이크맛집을 찾다가 이런곳이 있는지 몰랐는데 생일기념으로 예약했어요. 기대하고 먹었는데 정말 살살 녹네요. 한판 다 먹고싶었지만 참았어요ㅎㅎ 일반 생크림인데 딸기도 꽉 차있고 진짜 딸기생크림먹은것중 느끼하지도않고 맛있어요! 다음주 친구생일도 예약했어요! 차도 같이시켰는데 다 물어보라고 해주시고 설명해주고 직접 물리필도 해주시고 케이크 녹는다면서 냉장보관도 해주시는 센스까지 친절하셔요. 재예약의사 있습니다. 딸기케이크 강추요', 9, 10, 'GOOD', SYSTIMESTAMP);
