INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '여기 케이크는 우유맛이 나여 생크림도 딸기도 그득그득해서 케이크가 무거울정도ㅋㅋㅋㅋ 좀 비싸지만^_ㅠ 맛있어서 또 사러 올거같아요:)', 18, 5, 'GOOD', SYSTIMESTAMP);
