INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '달콤한거짓말'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '1인 1메뉴를 주문해야 합니다. 팥빙수가 주력 메뉴이지만 다양한 제과제품과 케이크가 준비되어 있습니다. 하우스커피를 취급하여 블랙아이스커피를 드신다 하더라도 원두를 선택할 수 있습니다. 1층 야외에도 자리가 있어 선선한 가을에 방문하기 좋은 곳입니다.', 4, 9, NULL, SYSTIMESTAMP);
