INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '다음은 작당모의에 갔어요~ 복숭아에이드로 주문했어요~ 제철이라 그런지 맛이 있어요~ 상큼하고요~ㅎㅎ 분위기는 음악에 맞게 조용하고 아늑한 분위기였어요~ 인테리어를 잘 꾸며놔서 사진찍을 곳이 많아요~ㅎㅎ', 9, 6, 'GOOD', SYSTIMESTAMP);
