INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '작년 무화과시즌에는 친구랑 왔는데 이번엔 언니랑 반차쓰고 왔어요~! 다른시간대에는 모르겠는데 평일 두시에는 여유있네요 ㅎㅎ 디저트도 맛있고 커피도 맛있어요! 작당모의 티라미수 강강강추합니다👍', 76, 17, 'GOOD', SYSTIMESTAMP);
