INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '이번 복숭아시즌 디저트와 라떼.너무 잘 먹었습니다!! 정말 너무 맛있았는데ㅠ 제가 디저트 먹는 속도가 엄청나게 느려서(중세 티타임 수준) 널널한 시간제한까지 넘겨버린 거 있죠... 남겨야 했지만 그래도 정말 잘 먹었어요~', 23, 4, 'GOOD', SYSTIMESTAMP);
