INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '전체적으로 무난한 맛이었습니다. 특별히 인상적인 메뉴는 없었지만, 친구랑 편하게 이야기 나누기엔 괜찮았어요. 인테리어도 깔끔한 편이지만 특별히 기억에 남을 정도는 아니었습니다. 스벅 질렸을 때 가는 무난한 카페 느낌', 42, 2, NULL, SYSTIMESTAMP);
