INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '운이 좋아서 대기 안하고 바로 들어갔습니다 저희 뒤부터는 대기 있었어요🥲 시그니처 홍차 마셨는데 너무 상큼하고 맛있었어요! 이번에는 아쉽게 디저트를 못 먹어서 다음에 또 와서 디저트도 먹고 가려구용😋', 4, 5, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '7시 반쯤 평일 저녁에 방문해서인지 예약 없이 바로 들어갈 수 있었습니다 자리도 널널했구요 커피를 마시고 싶었지만 밤이라 커피 대신 초코즐넛을 마셨습니다🍫 크림이 정말 맛있어서 그냥 아인슈페너를 마실 걸 조금 후회했네요ㅠㅠ 다음에 방문할 기회가 생긴다면 티라미수도 먹어보고 싶습니다! 분위기는 훌륭하지만 테이블이 조금 낮고, 사람 많을 때 방문하면 앞사람 목소리가 잘 안 들리네요 그리고 2층 화장실 앞 자리에 앉게 되었는데 사람들이 왔다 갔다 하면서 문 열고 다니면 화장실 냄새가 좀 나서... 해당 자리에 앉는 것은 비추천합니다🥺 직원분들이 정말 친절하시고, 카페인데 백설공주 영화랑 콜라보하는 게 신기했어요🍎', 9, 4, NULL, SYSTIMESTAMP);
