INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '작당모의 엄청 오랜만에 방문했는데 여전히 맛있네요!! 거의 5년도 전에 방문했던 거 같은데 연남동에서 이렇게 오래된 거 보면 확실히 맛있긴한가봐요ㅋㅋ 비싸서 그런가ㅠㅠ 디저트랑 음료랑 둘다 엄청 비싸지만 맛나요~.~', 26, 9, 'GOOD', SYSTIMESTAMP);
