INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '매장 캐치테이블 웨이팅 등록하여 20분 정도 기다린 후 입장했습니다! 직접 가져다 주시는 방식이고, 치우는 것도 두고 가면 정리 해주십니다. 굉장히 편하고, 분위기도 좋고 최애카페 등극할 거 같아요🤍', 118, 20, 'GOOD', SYSTIMESTAMP);
