INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '작당모의 항상 웨이팅이 길어서 못 가보다가 평일 한적한 시간대에 웨이팅 없이 입장했는데 그래도 사람이 많았어요 인기가 많네요 ㅎㅎ 티라미수가 역시 맛있었어요👍', 90, 13, 'GOOD', SYSTIMESTAMP);
