INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '예약하고 이용했습니다! 앞에 두팀 있다고 떴는데 거의 5분만에 입장했어요😆 자리는 어딜 앉든! 사진 잘 나오겠더라구요✨️ 달달하구 분위기 이뻐서 힐링하고 갑니다~🙈❤️ 데이트 할때 가면 넘 좋을 것 같아요!😚', 0, 5, 'GOOD', SYSTIMESTAMP);
