INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '진짜 별루예여… 카페는 이쁜데 음료가 진짜 😖 밀크티도 여러 티 블렌딩 한건데 이도저도 아닌 맛이고 자몽에이드도 달기만하고 향도 없고 자몽맛이 아니예요 분위기는 너무 좋은데 진짜 음료 두개다 실패여서 아쉽네요 가격도 비싼데 ㅠ 음료 진짜 아쉽네요', 43, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '딸기 시즌 메뉴가 디저트 종류뿐만 아니라 음료 종류로도 다양해서 선택할 때 고민이 많았어요. 늦은 시간에 오니 품절된 디저트도 몇 있어 다음에는 낮에도 방문하고 싶네요. 가게 분위기 어둡고 아늑하지만 소리가 많이 울려요.', 70, 13, NULL, SYSTIMESTAMP);
