INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '작당모의에서 타르트랑 티라미수 먹었는데, 아아랑 조합도 너무 좋고 많이 안달아서 너무 맛있게 먹었어요!❤️🍓🍰 사람이 많아서 웨이팅 있으니 참고하시고, 디저트 꼭꼭 드세요!', 44, 2, 'GOOD', SYSTIMESTAMP);
