INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '디저트에 진심인 연남동 강추 카페 분위기도 고풍스럽고, 매장이 꽉 차면 카페스럽지 않게 웨이팅까지 걸고 갈 수 있는 매장의 세심한 배려가 좋았어요! 직원분들도 친절하고 제일 중요한 맛은 적당히 달달하면서 물리지 않아서 편하게 먹을 수 있었어요!🍰☕️', 73, 12, 'GOOD', SYSTIMESTAMP);
