INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '커피 무난하고 디저트 맛있어요! 근데 이제 가격이 너무 비싼...ㅎㅎ 재방문할지는 모르겠어요 근데 무난합니다 전반적인 카페 분위기도 그렇고 아 상이 너무 낮아서 좀 불편했어요.', 42, 4, NULL, SYSTIMESTAMP);
