INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '플레이트 케이크 맛도리입니다!!!!🔥🔥🔥🔥 크림치즈 & 딸기 & 무화과 조합 맛도리입니다. 평소 케이크는 먹다보면 물려서 못먹는데 마지막 한입까지 야무지게 먹었습니다👍🏻 담백하고 적당히 달아서 딸기 & 크림치즈 느낌 좋아하시는 분들께 강추해여! 아인슈페너는 고소함의 풍미가 깊고 견과류 향이 진하게 나서 좋았고 아아는 산미 적은 고소한 원두여서 매우 맛도리하게 마셨네여. 금요일 3시 기준 만석이고 주말에는 웨이팅 있을듯 하니 미리미리 가시는거 추천드려여! 1층에서 주문하고 테이블 번호 받아서 올라가는 방식이고 메뉴도 가져다주셔서 편합니다! 라스고🔥🔥', 120, 21, 'GOOD', SYSTIMESTAMP);
