INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '기대 안 하고 방문했는데 인테리어도 괜찮고 디저트 맛이 좋더라고요 작당모의 플레이트인가? 그거 크림도 맛나고 시트도 괜찮았어요💖💖 저녁시간에 방문하니 분위기도 좋고 사진도 잘 나오더라고요 근데 그만큼 커플들이 많아서 애정행각을 2번이나 봤습니다 ㅜㅜ 여튼 강추! 커피맛은 평범해요', 76, 11, NULL, SYSTIMESTAMP);
