INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '그 유명한 작당모의! 예전에 웨이팅 때문에 못갔는데 평일 오후에 가니 웨이팅이 없어서 다녀왔습니다. 내부가 예쁘긴한데 디저트 맛은 쏘쏘해서 몇시간 기다릴정도는 아닌듯🤔', 48, 3, NULL, SYSTIMESTAMP);
