INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '클래식 티라미수는 정말 맛있게 잘 먹었습니다! 다만 무화과 올라간 티라미수는 너무 달고 빵이 촉촉하다 못해 축축하고 시럽에 절인 느낌이라 개인적으로는 입맛에 맞지 않았습니다. 직원분 중 되게 친절한 분이 있으시고 되게 아닌 분도 있어서 기분이 묘했습니다. 🙌커피는 맛있었습니다🙌', 75, 14, NULL, SYSTIMESTAMP);
