INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '친구랑 약속시간 기다리면서 우연히 방문했는데 음료도 너무 맛있고 카페 분위기도 너무 예뻐서 다음번에듀 연남동오게되면 재방문할게요🫶🏻👍🏻', 6, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '여기 티라미수 진짜 초 대박 맛있거든요..? 적당히 포슬하고 부드럽고 크림이 진짜 개마싯어요. 하나도 안 느끼하고 만이천원이라서 놀랄 수 있지만 양도 진짜 많아요.. ‼️❤️ 내부공간 너무 따뜻하게 잘 꾸며져 있어서 데이트 하기도 좋을 거 같아요. 주문 후 테이블로 가져다주시는것도 센스만점 🫶🏻🫢 진짜 티라미수.. 잊지모태..', 50, 0, 'GOOD', SYSTIMESTAMP);
