INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '앞에 대기가 5팀 있어서 기다려야 했지만 기다린 보람이 있었어요. 티라미수랑 타르트 다 맛있었고 자몽 음료도 좋았어요. 처음에는 안 달다고 생각했는데 밑으로 갈 수록 달아지더라구요ㅋㅋㅋ 잘 섞어서 드셔야 합니다;;', 35, 2, NULL, SYSTIMESTAMP);
