INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '금요일 오후 대기없이 방문했고, 앞에 웨이팅 1팀 있었어요 ㅎㅎ 복숭아 다쿠아즈롤이 넘 귀엽고 크림도 생각보다 쫀득?시원하고 맛있어요 🍑 메뉴 주문하면 직접 자리로 가져다 주십니당 🙂 햇살도 좋고 친구들이랑 좋은 시간 보내다 감니당 🥰 한가한? 시간에 오면 더 분위기 있고 여유를 만끽하기에 좋을 것 같아요 :-)', 18, 0, 'GOOD', SYSTIMESTAMP);
