INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '친구들이랑 오랜만에 만나서 작당모의를 찾았어요! 가격대가 다른 카페에 비해 좀 있는 편이지만 분위기나 비주얼 생각하면 적당한 것 같아요 특히 크림 올라간 음료들이 맛있더라고요😍 공간도 아늑하고 예쁘고 다음에 연남에 또 방문하게 되면 또 오고 싶어요!', 0, 5, 'GOOD', SYSTIMESTAMP);
