INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '공간도 예쁘고, 음료, 디저트, 다 예뻐요🤎 복숭아 라떼 넘 맛있고요 🍑 디저트도 다 맛있어보여서 뭘 먹을지 고민했네요. 한창 더운 날이었지만 냉방을 워낙 잘 해주셔서 실내가 약간 추웠으니 참고하세요 😂', 39, 5, 'GOOD', SYSTIMESTAMP);
