INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '무더위에 대기시간이 쫌 길긴 했으나 대기한 시간만큼 맛있었기에 너무 만족합니다~ 티라미슈도 복숭아 에이드도 너무너무 맛있어서 돌아오는길에는 티라미슈 포장도 해왔네요~', 14, 5, 'GOOD', SYSTIMESTAMP);
