INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '시스템이 딱 잘 잡혀있는 카페! 저희가 들어오고 만석되서 뒤에 웨이팅 생겼어요! 에이드는 이프로맛으로 맛있었구 무난한 아아와 다쿠아즈 옆애 딱복 짱맛... 크림도 부드러운 우유생크림 맛이에요❗️❕', 84, 12, 'GOOD', SYSTIMESTAMP);
