INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '4팀 대기이고 15분 정도 기다리라는 안내받았는데 10분만에 전화받고 왔어요. 디저트는 제겐 단맛이 강해서 커피와 먹어야겠단 생각이 들었어요. 작당모의 에이드는 지금껏 먹어본 어떤 음료와도 다른 맛이었어요. 이 에이드 마시러 또 가고싶을 정도에요.', 22, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '(한줄요약) 정말, 소곤소곤 구석에서 좋은 "이야기" 할 수 있는 곳 (분위기) 아니, 가게 이름이 작당모의여서 너무 웃깁니다. 작당모의의 뜻은 "뭔가 부정적인 일을 꾸미다"인데, 여기서는 좋은의미로 부정적인 걱정들을 날릴 수 있습니다. (맛과 양) 커피 좋구요. 디저트 좋구요. 분위기보다 어쩜 좋습니다.', 19, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '홍대입구역에서 15~20분 거리에 위치한 디저트카페. 한여름 무더위에 식사후 방문했는데 입구 대기등록 하니 50분후 입장가능! 많은 사람들이 왔다가 대기보고 돌아간다. 시그니처는 아인슈페너 작당모의 커피 등. 커피는 6~7천원. 대표 디저트로 보이는 복숭아테마의 티라미수와 케잌들이 8000~12000원이다. 맛은 있지만 와~하는 정도는 아니다. 내부 인테리어도 그냥 그런...  주문하고 자리에 앉으면 배달이 된다는것이 특징이라면 특징. 주문할 때 실내정숙과 2시간 시간제한 등이 적힌 유의사항(둣면은 테이블넘버)을 주는데 이걸 테이블 위에 세워둔다. 요즘 진상들이 많은데 이곳은 철저히 단속하나보다. 카페를 나오면서 ''50분을 대기하고 입장하는 이곳의 차별성은 무얼까?''라는 영원히 풀지 못할것만같은 의문이 든다', 80, 18, NULL, SYSTIMESTAMP);
