INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '다쿠아즈 너무 맛있어요. 인테리어도 아늑해요. 사람이 많아서 꽤 복작복작한데 그건 손님을 타는거라 ㅋㅋ 사진 찍기도 좋고 맘에듭니다:)', 22, 7, 'GOOD', SYSTIMESTAMP);
