INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '밖에서 볼때는 평범해보였는데 안에는 분위기도 아늑하고 좋네요 음료도 생각보다 맛있었어요 7시 좀 넘어서 갔는데 디저트가 판매완료되서 그게 아쉬웠어요', 43, 5, 'GOOD', SYSTIMESTAMP);
