INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '커피는 무난했고 디저트가 맛있었어요! ㅈㄷㅁㅇ타르트 먹었는데 고소할줄 알았는데 엄청 달아요 초당옥수수인가봐요..!! 맛있었습니당 아 음료(이름기억안남)도 생각보다 달아요! 직원분들은 엄청 친절하셨고 카페는 좀 아늑하고 어두운 분위기에요', 11, 0, 'GOOD', SYSTIMESTAMP);
