INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '타르트가 건강한 맛이었고 견과류가 많이 올라가있어서 다만 과일본연의 맛의 집중하기가 어려웠네요. 레몬에이드도 달지않고 신맛이 강해서 저는 되게 만족했습니다ㅎㅎ', 74, 17, 'GOOD', SYSTIMESTAMP);
