INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '오랜만에 방문한 작당모의 확장해서 자리도넓고편해지고 뭔가 색달랐어요😆 연남동에서는 다 자리간격도좁고 매장도좁아서 불편한데 제가좋아하는 작당모의가 점점넓어져서(?) 너무좋아요 이번복숭아시즌은 홍차가 진짜진짜최고! 직원분들도여전히친절해서 잘쉬다갑니당🫶', 11, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '연남에서 디저트 정말 맛있게 먹은 곳! 유명한 곳이라 웨이팅 후 입장했고 1층 주문 2층 먹는 곳으로 나뉘어져있어요! 가격대는 있지만 충분히 맛이 좋습니다~ 다만 식사하는 공간은 소음이 많이 울리고 실내 이용시간이 정해져 있어요! ㅎㅎㅎ', 14, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '지나가는 길에 우연히 들어온 카페인데 생각보다 분위기가 괜찮네요 좌석간 거리도 적당히 떨어져 있어서 좋고 카운터에서 직원들이 확인하고 안내를 해주는 방식이 맘에 들었어요ㅎㅎ', 8, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '음료랑 디자트가 예쁜데 너!!!무!! 달아요 말차라떼는 쫌 마싯었어요 ~~ 🌿 직원들 친절해서 굿 조용하댔는데 주말 저녁에갔더니 좀 시끌벅적….', 64, 17, NULL, SYSTIMESTAMP);
