INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '초당옥수수를 이용한 디저트 라인이 정말 새롭게 맛있었습니다! 직원분들이 친절하시고, 직접 서빙을 해주셔서 더 좋았구요~ 다만 매장 내 말 소리가 좀 울리는 경향이 있어서 조용히 쉬고 싶으신 분들에게는 사람이 없는 시간대 방문 추천!', 41, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '메뉴 - 작당모의 플레이트 , 아이스 아메리카노 평점 - 4.5/5 혼자 가서 작당모의 플레이트랑 아아 시켰는데 아아 너무 쓰지 않고 적당히 고소해서 제 취향이었어요 ! 플레이트는 생크림 그득그득 케이크 느낌 ? 딸기랑 생크림 , 빵의 조화가 잘 어울려서 좋았어요 ㅎㅎ 조용한 분위기에 혼카하기도 나쁘지 않은 곳 같습니다 💗', 35, 8, 'GOOD', SYSTIMESTAMP);
