INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '앞에 웨이팅 걸고 한 30분정도 떠돌아 다니다 들어갔어요! 디저트 두개 시키다보니 가격이 밥값만큼 나왔지만. . . .맛있어요! 다쿠아즈보다 오리지널 티라미수 더 추천드립니다! 커피랑 먹기 딱 좋아요. 음료양은 디저트 먹다보면 조금 부족해요. 빨리 드시는 분들은 천천히 드셔야할듯..😊 그릇이 예뻐서 사진찍을 맛 나요.', 49, 7, 'GOOD', SYSTIMESTAMP);
