INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '인스타맛집인가했는데 와진짜 찐으로맛있어요 더워뒤1질뻔했는데 참고 기다린 보람이 있을정도 라떼치고 커피맛은 안났지만 크림이 매우 고급지고 맛있었습니다 재방문의향 매우있습니다', 26, 8, 'GOOD', SYSTIMESTAMP);
