INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '생일을 맞아 언니랑 조카랑 연남동 데이트 나왔어요. 평일에도 웨이팅이 있다는 카페인데 비가오는 이른 저녁이라 웨이팅 없었고 제철과일 딸기가 듬뿍. 맛도 괜찮아요^^', 47, 2, 'GOOD', SYSTIMESTAMP);
