INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '생각보다 사람이 많아서 웨이팅 20분 정도 했습니다. 매장 분위기는 너무 아늑하고, 따뜻한 느낌을 주어서 좋았습니다. 조용하게 대화하기도 좋았고, 디저트, 음료 모두 자극적이지 않아서 먹기 좋았습니다😋', 55, 11, 'GOOD', SYSTIMESTAMP);
