INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '✔️ 주말 14시 기준, 대기 30분 하고 입장했어요 ✨ -> 카페가실 분들은 현장 태블릿 pc로 웨이팅 등록부터 하고 주변 구경하는 것을 추천드릴게요 ! 🍓저는 작당모의 플레이트, 딸기에이드, 말차슈페너를 주문했는데요 🍰디저트는 기대를 너무 했나 ,, 생각보다 평범했어요! 아몬드 파운드 케이크에 마스카포네 치즈 + 블루베리 딸기 있는 조합인데 딱 예상가능한 맛이예요 🍭 담에 가면 딸기 티라미수 먹어봐야겠어욤 .. ☕️ 그런데 음료가 대박이예요 ㅋㅋ 딸기에이드는 한 입 마시는 순간 입 안에서 딸기가 굴러다니는 것 같구 말차슈페너는 말차의 씁쓸함이 제대로 느껴져서 대만족 ❤️ 음료가 맛있으며 친구랑 단 둘이 도란도란 수다 떨기 좋았던 작당모의 후기였습니다 ❤️', 35, 2, 'GOOD', SYSTIMESTAMP);
