INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '티라미슈 맛집👍 직원분들 엄청 친절하셨어요! 아아 원두도 선택할 수 있고 매장이 갬성가득해서 옆에서 사진찍는 소리밖에안들림ㅋㅋㅋㅋ 가격이 쪼꼼 사악하지만 분위기도 ,맛도 좋았어용 ㅎㅎ', 20, 5, 'GOOD', SYSTIMESTAMP);
