INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '디저트가 너무너무 맛있었어요! 커피랑 티도 좋았어요🤭 매장은 조용한 분위기라 여러 명이서 가면 얘기하기에는 조금 부담이 있을 것 같아요ㅠ 그리고 자리가 없어서 웨이팅도 아마 길게 해야 하는 것 같더라구요! 디저트는 정말 추천해요 🍓 매장도 예쁩니다!!', 50, 1, 'GOOD', SYSTIMESTAMP);
