INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '연남동에 있는 카페들 중에서도 비싼 편이고 매장이 엄청 협소하지가 않은데도 불구하고 입장과 동시에 자리에 있는 안내문구를 읽어달라고 얘기합니다 테이블에는 2시간 제한이 있다는 내용과 정숙해달라는 내용이 적혀있는데, 솔직히 가격만큼 메리트가 있는 지 모르겠어요 티라미수 사이즈가 확실히 크긴하지만 가격이 만원 넘는 걸 생각하면 확실히 비싼 편이기도 하고.. 무엇보다 좌석이 편하지도 않아서 오래 있기도 힘든데 회전율 높히려고 시간제한에 가격은 비싸다는 점에서 다시 가고 싶지는 않네요 다른 더 좋은 카페들 주변에 많으니 다른 곳으로 가시길 추천합니다', 27, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '작당모의 라는 이름이 좋아서 선택하게 되었는데 딸기 관련 메뉴가 많아서 정말 좋았어요!! 근데 디저트는 생각보다 많이 달아서ㅠㅠ음료랑 같이 드시는걸 추천드릴게요! 하나하나 예쁘고 인테리어도 예뻐서 사진이 잘나와요👍', 78, 16, 'GOOD', SYSTIMESTAMP);
