INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '여기 그냥 지나가다가 보여서 들어왔는데 인테리어도 너무 예쁘고 커피랑 타르트도 너무 맛있어요!!!! 원두도 선택가능해서 좋아용 ㅎㅎ', 53, 12, 'GOOD', SYSTIMESTAMP);
