INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '바닐라라떼가 진짜 존맛이에요 다른 카페가면 크림이 달아도 약간 가벼운 크림인데 여긴 크림 자체가 약간 꾸덕한 느낌이 난다고 해야하나 묵직하고 달달함이 끝판왕입니다🫶🏻 아주 맛있구, 다음엔 디저트랑 같이 먹으러 와야겠어요👋🏻', 46, 8, 'GOOD', SYSTIMESTAMP);
