INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '커피 원두 ‘작당’이랑 ‘모의’ 중에 취향 따라 선택할 수 있는 게 좋았어요 직원분들도 완전 친절하셨고 화장실 깔끔함 짐 놓을 수 있는 의자가 따로 더 있어서 좋아요 근데 솔직히 좌석이 그리 편하지는 않아서 웨이팅 할 만한 카페인지는 잘 모르겠어요 두 시간 이용 제한 있어요! 작당모의 티라미수도 사실 무슨 맛인지 잘 모르겠는데 달아서 좋긴 했어요 그냥 오리지널 티라미수나 다른 디저트 종류 먹는 걸 추천드려요', 28, 10, NULL, SYSTIMESTAMP);
