INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '기분좋게 커피를 마시고 나오면서 빈잔을 들고 ''어디에 놓을까요?''했더니,  ㅎ ''앉으셨던 테이블에 두시면 저희가 치우겠습니다. '' 그냥 감사합니다. 하고 받으면 될것을... 구지 손님보고 다시 갖다 놓으라니... 호의가 오지랖이 되는 순간 기분이 잡쳤습니다. 서비스는 규정이 아니라 배려입니다.', 72, 13, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '주문한거 자리로 직접 가져다주시면서 디저트 어떻게 먹어야 맛있다고 설명해주시고 가시는 친절함 :) 분위기도 좋고 음료랑 디저트도 맛있고☺️ 재방문해서 다른메뉴도 먹어보려구요~', 63, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '오리지널 티라미수의 정석을 맛 볼 수 있어서 너무나 영광이었던 작당모의...🥹💖✨️✨️ 당연하지만 믿고먹고 너무나도 만족스럽습니다. 아인슈페너? 초코 드리즐? 작당모의 라떼? 그냥 작당모의는 아무거나 시켜도 존맛인듯 전 메뉴가 이렇게 맛있기 쉽지 않은데 그걸 해냅니다👏 솔직히 테이블이랑 의자가 마냥 편하지는 않지만 어쩌면 웨이팅을 예상하고 2시간을 상정한 고려일수도...🤔', 36, 5, NULL, SYSTIMESTAMP);
