INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '따뜻한 분위기에 너무 떠들석하지 않아서 좋아요! 딸기 메뉴도 많고 디저트도 맛있어요 ❤︎ 커피도 원두 두종류인데 너무 맛있어요 !!', 80, 11, 'GOOD', SYSTIMESTAMP);
