INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), 'Overrated… cost is a bit high and staff wasn’t that kind with us as foreigners. They have rules for not speaking loudly and to only stay 2 hours… but 😤😤 I don’t recommend it and I won’t visit it again', 106, 25, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '작당모의는 예전부터 연남동에서 가고 싶었던 카페에서 찜콩 해뒀던 곳인데 이렇게 낮에 방문해서 너무 좋았어요 -! 햇살 맛집, 디저트 맛집이랄까요 : ) 전 오픈하자마자 갔는데도 손님이 반정도는 차있었고 구석탱이에 자리 잡아서 천천히 커피랑 디저트 즐기면서 나왔어요 ! 시즌별로 과일이 바껴서 타르트를 만드시는 거 같은데, 이번에 갔을때는 가을의 상징 무화과가 있더라구요 !! 🩷🩷 적당한 달달함에 직접 만든 타르트지까지 넘 조용히 잘 있다가 온 거 같아요 ! 손님은 많은데 화장실이 한칸뿐이라 좀 아숩긴해요 ㅠㅠ', 9, 0, NULL, SYSTIMESTAMP);
