INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '도란도란 오순도순 시간 보낼 수 있는 곳인줄 알았는데 .. 너무나도 핫플 .. 게다가 공간도 작고 테이블도 낮아요 .. 인스타 사진 건지긴 제격 !', 21, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '늦게가면 웨이팅이 있어요. 음료와 디저트가 대체적으로 비싸요. 가격에 비해 다른 카페와 차별화된 맛의 느낌은 없어요. 디저트랑 같이 먹으면 좋을거같아요.', 102, 21, NULL, SYSTIMESTAMP);
