INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '오랜만에 재방문했어요~예전에는 없었던 시즌티라미수먹었는데 너무맛있어서 리뷰남기려고 먹다가 사진남겼네요!! 직원분들도여전히친절해서 기분좋게 먹다갑니다~', 114, 19, 'GOOD', SYSTIMESTAMP);
