INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '음료도 맛있고 카페도 예뻐요. 케이크도 너무 맛있어 보였는데 밥먹으러 가야되서 아쉬웠어요. 유명한 곳이라 사람 많고 웨이팅있고 조용하지는 않습니다. 그래도 한번은 더 가서 케이크를 먹어봐야겠어요.', 31, 7, NULL, SYSTIMESTAMP);
