INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '음료랑 디저트 둘 다 맛있고 테이블마다 다 잘 꾸며져있고 구석진 자리도 있어서 혼자와도 힐링하기 좋은 공간인거 같아요 다음에 친구랑 같이 오고 싶네요 😊', 48, 3, 'GOOD', SYSTIMESTAMP);
