INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '딸기시즌이라 잘 먹고 왔습니다! 근데 매장 2시간이용이라 쫓겨났네요 ㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋㅋ 웨이팅 있을경우 2시간이용제한이라고 적혀있긴한데 기분은 별로네요 그래서 다른 카페 또 갔습니당', 8, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '웨이팅을 꼬옥..해야만 하는 요즘 카페,,,🥹 나가면 들어오는 시스템이라 안은 생각모다 심플하고 편하더라구요~! 끊임없이 들어오는 손님들 덕에 디저트는 그저 프레쉬 그 잡채,,^^* 다만,, 갔을 때 복숭아가 최고 달달 맛있어!! 는 아니라서 굳이 복숭아 아닌 일반적인 티라미수였오도 좋았을 듯 싶어요 ㅎ', 42, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '무화가 시리즈가 있다는게 넘 맘에 들어요! 음료 위에 크림이 넘 맛있어요! 🥹 매장은 사람이 꽉 찼는데도 조명 때문인지 어수선하지 않고 아늑해요. 특히 담요가 있어서 넘 좋았어요! ㅎㅎ 오늘은 먹고 싶었던 디저트가 다 떨어져서, 다음에 디저트 먹으러 가보려구요! 😆', 15, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '작당모의 홍차 너무 맛있어용~! 인테리어 예쁘구요! 크게 떠들지는 못하는 곳이라 저는 혼자갔는데 자리 살짝 지정되어있어서 좀 불편한 자리 앉았어요.', 439, 58, NULL, SYSTIMESTAMP);
