INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '음료, 디저트 둘다 맛있어요! 무화과 시즌이라 그런지 무화과 음료랑 케이크 잘먹었습니다. 참고로 5인부터는 안받아요. 1테이블 최대 4명이라고 합니다! + 테이블 시간 제한 2시간이에요~', 23, 0, 'GOOD', SYSTIMESTAMP);
