INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '항상 웨이팅 하는 곳! 귱금해서 가봤어요~ 저녁먹을 애매한 시간에가니 금방들어가더라구요. 음료랑 디저트 맛있는데 가격이 사악해요ㅠㅠ', 32, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '딸기 디저트를 먹고싶었는데 없어서 아쉬웠네요 웨이팅을 생각보다 오래 기다리지 않아서 좋았네요 조용해서 대화하기 굿 화장실이 한칸이라 아쉽네요', 40, 1, 'GOOD', SYSTIMESTAMP);
