INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '실내인테리어가 예쁘고 조용하니 대화하기 편했어요 커피가 맛있고 특히 타르트가 맛있어요 타르트를 안 좋아하는데 먹으면서 맛있다를 연발했네요  강추합니다', 6, 6, 'GOOD', SYSTIMESTAMP);
