INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '유명한 이유가 있는 카페에요 음료도 맛있지만 특히 작당 타르트가 정말 맛있어요🫶🤍 복숭아도 많이 올라가있고 요거트 크림도 최고네요 ㅎㅎ 가격대가 좀 있는 편인데, 맛있어서 용서가능한 맛..? 근데 밀크티는 티백 밀크티 맛이 강해서 다른 거 드시는거 추천해욥😆', 34, 1, 'GOOD', SYSTIMESTAMP);
