INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '맛있어서 사람들이 많은 이유를 알 것 같아요. 다만 48분 웨이팅이라 해서 다른곳에 가던 중이엇는데 갑자기 웨이팅 10분만에 전화와서 5분안에 오지 않으명 웨이팅이 끊어진다고 해서 뛰어와 방문했어요ㅠ 최소 10분은 대기가능해야하는 거 아닌가요? 맛있긴한데 자리도 불편해요.', 7, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '카페 분위기도 좋고, 무엇보다 메뉴 비쥬얼이 완전 취향저격이에요💖💖 먹기 아까운 비쥬얼인데 맛도 너무 좋았습니당! 연남동 카페 ㅈㄷㅁㅇ 추천👍🏻👍🏻', 1, 8, 'GOOD', SYSTIMESTAMP);
