INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '제철 과일을 이용한 음료와 디저트를 파는 곳으로 몇년 전부터 가보고 싶었던 곳이었어요 추석 연휴 첫날 2시쯤 웨이팅 걸고 45분쯤? 입장했어요 작당모의 홍차, 에이드, 티라미슈 주문했고 시즌 과일은 무화과 입니다 곧이어 예쁜 음료와 디저트를 점원분이 자리로 가져다주세요 결론을 말씀드리면 음료와 디저트가 다 과하게? 달아요 티라미슈는 크림층이 두꺼워서 크림 80%에 밑에 빵 20%를 먹는 느낌이에요. 크림과 빵 둘다 달아서 좀 먹다가 먹기 포기했어요ㅠ 음료도 청을 많이 쓰신건지 좀 많이 달았는데 비율만 조금 줄이면 더 맛있을 것 같았습니다 ㅠ', 49, 9, NULL, SYSTIMESTAMP);
