INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '친구픽으로 방문하게된 작당모의! 어엇. 이게왠걸.. 너무맛있어용;;; 저랑 친구 둘다 복숭아엄청좋아하는데, 과일차, 에이드, 타르트모두 너무너무맛있슴니당 ! 가게 인테리어도 아기자기해서 수다떨기좋아용! 웨이팅 걸어놓고 방문하시먄 편해요~ ㅎㅎ', 85, 15, 'GOOD', SYSTIMESTAMP);
