INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '리뷰가 좋아 궁금했던곳인데 드디어 가봤네요. 디저트는 쑥관련 베이커리류들만 있어서 패스하고 음료만 시켰습니다. 맛있어요. 카페 정책이 특이하고 친절하시지만 왠지  눈치보이는 곳이네요.ㅎㅎ', 29, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '카페가 예쁘고 분위기가 좋았어요. 주말에 가서 그런지  웨이팅 있었는데 테이블링 걸어놓고 딴데 구경하고 와서 괜찮았어요. 음료는 무난했고 티라미수가 괜찮았어요.', 36, 5, 'GOOD', SYSTIMESTAMP);
