INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '1시 반쯤 갔고 손님이 한명도 없었어요 들어가니까 손님도 없는데 인원 수에 맞는 자리에 앉으라고 하시더라구요 거기까진 그럴 수 있다고 생각했어요 저희가 들어온지 한시간? 한시간 반 정도 될 때부터 손님이 계속 들어왔고 2시간이 될 무렵 손님이 꽉차서 밖에 한두팀 정도 웨이팅이 있었어요 저희한테 나가달라고 말씀하시더군요 음료랑 케익이 어느 정도 남아있었고 저희가 처음 매장에 들어와서 한시간 정도는 손님이 1도 없었는데 말이죠 내쫓는 기준이 결제 시간 기준이신가봐요 저희는 서둘러 먹고 나왔지만 해당 매장을 다시 방문하지 않을 생각입니다 아메리카노 두잔에 케익 하나 해서 23,600원이 나왔는데 그 정도의 맛이라고 생각되지도 않습니다 방문하실 분들 참고하시길 바랍니다', 40, 1, 'BAD', SYSTIMESTAMP);
