INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '말차라떼는 맛있고 디저트는 그저그랬어요. 은은하게 음악이 흐르고 20~30대가 많이찾는곳. 적당한 테이블간의 거리. 둘이서 차분히 대화할수있는곳', 79, 16, 'GOOD', SYSTIMESTAMP);
