INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '두시간 시간 제한이 있고 2인은 4인석에앉으면 안되고 큰소리로 얘기하면 안되고 벤치 의자는 약해서 앉으면 안되고 등등 이용시 제약이 참 많은 카페입니다.', 76, 13, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '✨️홍차✨️ 애플티백을 사용했고 다진 사과와 띄워진 라즈베리 종류의 과일 식감 덕분에 홍차보다는 따뜻한 화채를 먹는듯한 기분이었습니다! 🥀티라미수🥀 농후한 콩포트의 맛과 절묘하게 씹히는 베리 종류가 마스카포네 크림의 조화를 잘 이룬것 같았습니다만 저에겐 너무 달았습니다🥲 ✔️ 디저트 퀄리티 good ✔️ 조용한 공간감, 사색에 잠기며 디저트와 음료에 딱 집중하기 좋아요☺️🌷🩷🩷 ✔️ 이가 썩을것 같은 단맛을 원한다면 당장 여기로..🤞', 7, 3, 'GOOD', SYSTIMESTAMP);
