INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '복숭아 티라미수 엄청느끼했어요...비주얼만 예쁘고 빵밑부분의 복숭아퓌레가 안느껴져서 치즈의느끼한맛만 났어요 느끼한맛을 좋아하신다면 모를까 관상용디저트라고밖엔 표현못하겠어요', 20, 2, 'BAD', SYSTIMESTAMP);
