INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '카페 분위기도 최고 커피맛과 디저트 다 너무 맛있어서 자주 갑니다.  항상 직원분들이 친절하게 대해주시고 설명해주시는 부분이 최고로 좋았어요.', 57, 12, 'GOOD', SYSTIMESTAMP);
