INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '디저트 맛집이래서 간건데 맛 없어서 먹기 힘들었어요... 망고가 맛이 없는데 1차 망침, 코코넛 향이 너무 세고 안 어울려서 2차 망침, 이걸 같이 먹으니 그냥 최악...... 그나마 홍차는 그런대로 먹을만했어요 너무 달 뿐. 초코즐넛은 그냥 먹을만한 초코라떼였고 위에 올라간 크림도 그냥 그랬어요. 기대 많이 하고 간건데 가격을 전혀 따라오지 못하는 맛이라 실망만 하고 왔습니다. 비쥬얼에만 공들이지말고 맛도 좀 신경 써주시길...', 44, 3, 'BAD', SYSTIMESTAMP);
