INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '사장님과 진원분들 친절하세요~ 초코즐넛은 초코에몽에 크림 올라간 맛 같았어요.. ZM에이드는 다이스로 썬 무화과를 설탕에 절인 거 같았고요. 탄산수에 케인슈가시럽으로 간을 맞춘 거 같았네요. 달기만 했고 뭔가 심심했달까..? 데코로 들어가는 무화과는 당연 절여지지 않았고요~ 무화과 자체가 그렇게 맛있지 않아요~', 18, 6, 'GOOD', SYSTIMESTAMP);
