INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '커피가 진짜 고소하고 디저트도 너무너무 맛있었어요 :) 저 티라미수 밑에 잼같은게 너무 맛있더라고요 !! 직원분들도 되게 친절하시고 분위기도 좋아요 !', 35, 2, 'GOOD', SYSTIMESTAMP);
