INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '커피는 원두 선택할 수 있고, 음료는 무난ㅎㅐ욤 디저트가 유명한 카페인지 모르고 방문했는데 다음번에 다시 방문해서 디저트 먹어봐야겠어요!', 41, 3, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '클래식 티라미슈 드세요. 아이스아메리카노 한입 쪽쪽하고 티라미슈 한입 슝당 베어물면 극락입니다. 거의 티라미슈 떡이라고 부를 수 있을 정도로 빵이랑 크림이 엄청 꾸덕하고 달달해요. 진한 단맛과 커피맛을 즐기신다면 추천해요. 카페 분위기도 이뻐요.', 48, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
