INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '카페와 디저트 비주얼은 좋은데 단 거 못 드시면 ㄴㄴ 웨이팅 있는데 안이나 바로 앞에서 못 기다리니까 웨이팅 걸고 근처 가실 곳 알아두시는 게 좋을 것 같아요.', 60, 11, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '딸기 시즌이라 딸기 음료랑 디저트가 많아서 행복했어요,, 홍차랑 은근 잘 어울려서 좋았고 디저트도 맛있었어요. 화장실도 깨끗하고, 홍대 근처라 접근성도 좋았습니다. 근데 평일 오후인데도 사람이 꽤 많더라구요. 웨이팅이 있었는지 2시간 됐다고 정리해달라고 하셔서 아쉬웠습니다 ㅠㅠ', 32, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '시즌에이드 너무맛있었어요!! 조용한분위기라 대화하기도좋았고 계시던 직원분들 모두모두 친절해서 너무기분좋게 다녀왔어요 :) 너무 다 좋았던곳이라 리뷰남기고싶었어요 제 첫 네이버리뷰랍니다 🙂 꼭 재방문할거에요~!', 45, 0, 'GOOD', SYSTIMESTAMP);
