INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '다쿠아즈..뭡니까 너무 맛있어요 두번세번 드세요 그리고 카페이름 너무 찰떡이네요 작당모의하기 좋게 오순도순 붙어서 앉는 형태에요 그리고 곳곳이 사진스팟이라 카메라를 놓을 수 없어요!', 38, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '예전에 딸기 다쿠아즈를 맛있게 먹은 기억에 갔는데 이젠 없는듯하네요 ㅠ.ㅠ 딸기를 정말 좋아해서 너무 만족합니다 딸기 음료는 딸기시럽 쓰는 곳은 맛없기 마련인데 맛있는 딸기청을 쓰는 것 같아요 직원분도 친절하시고 추천해요', 8, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '아인슈페너 존맛탱 디저트도 존맛탱... 아아는 내가 안 마셔서 모르겠으나 전체적으로 맛있음! 카페 분위기도 너무 좋음! 2시간 할당제? 라서 시간 다되면 나가야함 그래서인지 웨이팅 시스템이 아주 잘 되어있음👍', 73, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '카페분위기 자체는 차분하고 너무좋아요~그런데 매장컨셉자체가 조용한 컨셉이었더라구요 저희가 잘 모르고 메뉴를 고르느라 원래 목소리대로 주문했는데김병지머리하신분이 표정이바로개썩으면서 뒤로가시고 다른분이 메뉴를 받아주시더라구요. 대체적으로 매장직원분들 기분이 안좋아보이시고 특히 그 키 제일 작으신 남자분이 가장 불친절하더라구요. 주문 다하고 테이블에 앉고 나서야 저 넵킨보다 작은 안내문구 하나보고 작게말해야하는지 그제서야 알았어요 ㅎㅎ 앞으로는 카페컨셉잘 모르는 손님들 받기 싫으시면 매장앞에 대문짝만하게 안내문을 하나 만들어서 세워두세요 괜히 손님들기분 잡치지시 마시구요^^ 키작으신 알바분 엠지의표본이시고 인스타 감성충인건 알겠는데 조금도 시크해보이지않고 버릇없어보여요 앞으로는 보다 친절한 알바생되시길 바랄게요~', 44, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '예전에 딸기시즌때 맛있어서 다시 재방문 한 곳인데 웨이팅이 있어서 신청하려고 전화번호 까지 입력했더니 두 분이면 바로 들어가심 된다고 했다가 다시 웨이팅 신청해야한다고 번복해서 웨이팅 순서 뒤로 밀림 주말이라 힘드신거 알겠는데 말투도 그렇고 솔직히 기분 나빴네요.', 78, 16, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '웨이팅이 납득이 되는 카페입니다 시즌마다 달라지는 디저트로 여러번 방문해도 질리지않고, 테이블마다 셋팅이 달라 찍는 각도마다 포토존이 되는 매력이 있네요 우드톤의 인테리어와 감성적인소품, 플랜테리어로 공간을 즐기기에 좋아요 카페전문 유튜버 유리소리TV', 24, 3, 'GOOD', SYSTIMESTAMP);
