INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '음료 달달 시원하니 맛있고 다쿠아즈도 맛있었어요 그리고 무엇보다도 대화하기 편한 카페인것 같아요~! 사람이 많은데도 소리가 울리지 않는다고 해야하나 무튼 같이온 친구랑 대화하기가 수월했어요:)', 38, 5, 'GOOD', SYSTIMESTAMP);
