INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '15분? 정도 웨이팅 하고 들어갔어요 ! 너무 친절하시구 음료도 디저트도 맛있어요! 카페 분위기도 너무 예쁘고 인테리어도 예뻐요 ㅎㅎ🍓❤️🤍', 32, 4, 'GOOD', SYSTIMESTAMP);
