INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '매장이 청결하고 전체적인 인테리어도 깔끔하고 아늑해서 좋아요. 근데 응대해주시는 남자직원분은 불쾌하네요. 처음방문이라 너무 많아서 조금 바삐 메뉴를 고르긴 했으나, 꼭 기분나쁜 티를 표정으로 드러내셔야 하셨는지.. 계절에이드 하나 먹고 가지만, 재방문은 하고싶지 않네요.', 80, 16, 'BAD', SYSTIMESTAMP);
