INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '이름이 뭔가 웃겨서 간 카페인데 진짜 뭔가 작당모의하기 좋은 분위기더라구요 밥먹고 바로 가서 배가 많이 불렀는데 소화에 도움된다는 티(이름 까먹음ㅠㅠ)랑 같이 마셔서 그런지 ‘작당모의 티라미수’ 배부른지도 모르는채 진짜 흡입했어요💚💜🤍 헤헷 넘나 맛있는것 ㅠ 과일까지 함께니까 그야말로 환상~ ㅎㅎ 또 먹고싶어요ㅠㅠㅠ 먹으면서도 하나 더 먹고싶었어요....😊💓🥹', 24, 1, 'GOOD', SYSTIMESTAMP);
