INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '음식이 넘 예쁘게나와요ㅠㅠ!! 근데 맛도 맛있어요!! 케익 플레이팅이 대박이에요 딸기랑 블루베리도 달고 좋은거 쓰는것같고 케익에 있는 크림하고 홍차도 진짜 맛있어요! 완전 인스타감성이에요', 60, 18, 'GOOD', SYSTIMESTAMP);
