INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '예전부터 가보고싶었던 카페였는데, 이번에 가보게되었어요 웨이팅이있었지만 다행히 친구랑2명이서 가서  웨이팅 안하고 바로들어갔어요ㅎㅎ 시즌메뉴로 제철과일사용해서 너무 맛있었고 직원분들 응대도 다들 친절하셔서 좋았어요~', 9, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '웨이팅해서 갈 곳은 아닙니다.. 음료는 괜찮았는데 티라미수 저게 12000원인데 맛있지도 않아요 빵이 설탕에 절여있다해야하나? 퍽퍽하고 정말 별로였어요 .. 티라미슈는 빵이 부드럽지 않나요..? 다쿠아즈도 별로고..자리도 불편한곳 줘서 더 별로였어요 재방문 x', 20, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '돈내고 찌린내와 독한 방향제 냄새 맡다왔어요 이자리 너무한거 아닌가요? 심지어 벽에 딱붙었던거 앞으로좀 밀은거에요...자리 없어서 어쩔수없이 앉았는데 웨이팅있어서 자리도 못바꾼다고하고 사람많은데라 들락날락미쳤고 문 여닫을때마다 구린내와 함께 찬바람이..... 사장님 보신다면 카페에 똥냄새나는 화장실 앞자리는 없애주세요', 49, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '음료와 디저트는 그럭저럭 먹을 만 했으나 가격이 맛에 비해 조금 비싼 감이 있네요. 외국에서 오랜만에 놀러온 친구와 오래 이야기하고 싶었지만 2시간 시간제한이 있어서 금방 나올 수 밖에 없었어요. 좌석도 인원 수에 맞는 좌석에 만 앉게 되어있어요, 기다려서 갈만큼에 가치는 못 느꼈습니다', 83, 16, 'BAD', SYSTIMESTAMP);
