INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '좋아요,맛있어요 홍차 생각보다 평범했었네욤 평일이라 기다리지 않고 바로 이용했습니다 분위기는 좋았지만 날씨가 추워서 인지 가게안에서도 추위를 느꼈습니다?창가 위치 탓인가?흠🤔', 34, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '수다떨기에는 테이블 간격이 좁아서 점점 목소리가 커질수밖에없어용.. 인테리어가 예쁘고 커피가 맛있어서많이들 오시는 것 같아요 이용시간 2시간 제한이고 실제로도 이용시간 다 됐다고 알려줘요. 커피가 맛있었지만 이제는 테이크아웃할것같아요', 63, 13, NULL, SYSTIMESTAMP);
