INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '인테리어가 이쁜 분의기 좋은 카페에요~ 무화과 타르트랑 티라미슈 맛나요!! 근데 웨이팅도 없는데 카페 이용시간이 2시간 제한이라 좀 아쉬워요,,', 63, 13, NULL, SYSTIMESTAMP);
