INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '무화과 타르트 먹으려고 달려갔어요 무화과랑 코코넛 조합은 상상도 못했는데 진심 맛있어서 눈물 흘렸어요,,, 사람들이 많이 오니까 포장만 하실 분들은 오픈 시간 맞춰서 가세요~', 22, 6, 'GOOD', SYSTIMESTAMP);
