INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '웨이팅 있는 경우 매장 이용시간 2시간 이에요. 아메리카노랑 딸기라떼 먹었는데 둘다 맛있었어요. 대화하기 괜찮은 곳 같아요. 화장실은 1개고 남여공용인거 같더라구요', 32, 9, 'GOOD', SYSTIMESTAMP);
