INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '바닐라빈크림커피 진짜 맛있고 에이드는 이쁜데 맛은 쏘쏘였어요ㅋㅋ걍 커피마실껄 아쉽ㅜ 근데 티라미슈가 진짜 짱 맛있네요... 다쿠아즈도 먹을껄..후회했음ㅜ 직원분도 친절하고 인테리어도 이쁘고 나중에 또가고싶은 카페', 58, 13, NULL, SYSTIMESTAMP);
