INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '작당 원두 진짜 맛있어요!!! 바닐라리쉬도 달달하니 마음까지 녹여준답니당 사장님, 직원분들도 친절하시구  사장님 잘생기겼어요!! 연남동 오면 꼭 한번 들리시길 바랍니다‼️‼️', 103, 22, 'GOOD', SYSTIMESTAMP);
