INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '인테리어가 너무 이쁘고 원두 고를수있어서 좋아요‼️‼️ 산미가 싫으신분들은 작당으로 마셔보세여‼️‼️ 전 작당으로 마셨는데 고소하니 좋았어여〰️‼️ 잘마셨습니당🫶🏻', 17, 5, 'GOOD', SYSTIMESTAMP);
