INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '금요일 오후였는데 운좋게 웨이팅 안하고 들어갔어요. 워낙 유명한 곳이라서 기대하고 갔는데 기대한만큼 ZM플레이트는 맛있더라구요! 무화과최고.. 🤤 아메리카노도 이만하면 괜찮았고 좋았어요. 그런데 의자가 좀 불편하기도 했고 파리인지 뭔지 날벌레들이 날아다녀서 비위생적으로 느껴졌어요ㅠ  그게 좀 아쉬웠네요 그래도 디저트 맛집인건 ㅇㅈ', 16, 7, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
