INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '친구와 보울케이크 먹었는데, 첫 맛이 "이 맛 어디서 느껴봤는데.."라고 생각했는데 친구가 이것좀 보라고 해서 자세히 보다가 크림과 견과류 사이를 벌려봤더니.... 곰팡이가 크림치즈 윗부분과 내부 사이사이에 피어 있었고, 견과류 부분도 곰팡이가 있었다. 첫 한입 먹었을때가 곰팡이를 먹은 것... 너무 놀래서 디저트 들고 가서 곰팡이 있다고 말하니.. 제대로 된 사과가 없었고, 사장의 ''소분을 해놨는데.. ''라는 말과 환불해주겠다는 말.. 혹시 식중독 걸릴까해서 명함 받아왔는데, 다행히 나는 2입정도 먹었고, 친구는 몸이 건강해서 별 탈은 없었지만..너무 기분이 상했다. 얼마나 관리를 제대로 안하면 곰팡이가 나는지 .. 곰팡이가 있다는 것은 이미 모든 디저트에 곰팡이 포자가 퍼져있다는 뜻인데.. 끔찍하다', 39, 1, 'BAD', SYSTIMESTAMP);
