INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '홍대에 있는 수많은 카페 중 .... 이 곳을 고른 이유는.... 가게이름이 너무 귀여워요 ㅎㅎㅎㅎㅎ 작당모의 방문했더니 자리도 딱 하나 남아있어서 언능 주문했죠 겨울한정메뉴도 넘 기엽구 다른 디저트들도 너무 귀여워욘 맛도 짱 조아요 글구 직원분들이 너무너무 친절하세여 !!!!! 짱짱^ㅁ^', 47, 9, 'GOOD', SYSTIMESTAMP);
