INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '가게가 예쁘고 아주 친절하네요. 무엇보다 사진찍으러 가기 좋은곳 이네요^^ 인테리어가 예쁘지만 의자는 나무의자라딱딱해서 오래 앉아있긴 힘들지만 꽃차 메뉴가 있어서 아주 잘 먹었어요!', 34, 1, 'GOOD', SYSTIMESTAMP);
