INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '평일 오후 6시 쯤에 가서 그런지 사람은 꽤 많았는데 자리는 남아있었구 꾸덕한 크림 라떼 원하신다면 코코넛 크림 라떼랑 플랫더블화이트 추천 드립니다😋 메뉴 사진은 있는데 이름은 몰라서 직원분께 여쭤보니까 친절하게 알려주시고 음료도 추천해주셔서 좋았어요. 무화과 타르트 화이트 초코? 부분이 좀 달긴 한데 맛있어용', 39, 4, 'GOOD', SYSTIMESTAMP);
