INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '유명한 집이라 그런지 웨이팅 있었습니다. 산미가 있는 커피와 그렇지 않은 커피 중에 고를 수 있어서 좋았습니다. 디저트에 제철 과일이 올라가는데, 디저트가 다 맛있었고, 특히 크림이 진짜 맛있어요… 재방문 의사 너무 있습니다 !', 61, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '제철타르트 먹었어요! 은은한 단맛이였어요.커피 산미없는거 좋아해서 작당아아로 주문했었는데, 작당아아는 제 기준엔  맛이 연한편입니다. 카페인함량면에서 덜걱정되는맛 ㅎㅎ', 6, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '우연히 찾은 가겐데 엄~~~ 청 유명한 카페더라구요! ㅎㅎ 웨이팅도 있고... 다른 디저트도 먹어보고싶었는데 점심을 먹은 후라 타르트만 먹었어요! 엄! 청 달콤하고 맛있어요!!', 49, 1, 'GOOD', SYSTIMESTAMP);
