INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '아... 테이크 아웃 해왔는데 카광이라 어지간한 카페 다 가봤는데 ... 테일러 커피보다 비싸고 어지간한 이름있는 카페 정도 가격인데 6000원이면 맛이 받쳐줘야 하는데 메가커피 맛 정도라 좀 충격이였음 ㅎㅎㅎ 할인도 없고 좀... 뭐랄까 인스타 사진용으로 소꿉장난 하는 친구들 뒷통수 후려치는 맛과 가격이랄까 가격 비싼건 인정하는데 맛이 안받쳐 주는건 근래에 연남동에서 보기힘든... 넘사벽 뒷통수 맞는 느낌이네요 ㅎ', 46, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '재방문한 장소인데 원래 카페 자체가 엄숙까진 아니더라도 다른 손님에 피해가지 않는게 취지 아닌가요? 대화가 시끄럽게 이어지는 테이블에 아무런 조취를 취하지 않으셔서 좀 당혹스럽네요.', 6, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '절대 이 가격 주고 먹을 맛은 아니네요 자리도 엄청 협소한데 한시간 반 제한 걸려있고요.. 전 이 돈 주고 여기서 먹을바에 다른 곳 가겠습니다', 15, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '간판만 보고 들어갔는데 다쿠아즈 맛집이다 하나에 4500원,, 티라미슈 만원,, 가격은 사악하지만 맛있는 녀석이었다 다쿠아즈 맛집이라 가면 푸석한 빵 사이에 크림이 들어간 느낌을 받았었는데 여기는 촉촉하고 달달한게 더 먹고 싶었다 바닐라빈 커피는 크림이 맛있었고 홍차는 기억은 안나지만 맛이 있었다 여기서 다쿠아즈가 압도적으로 맛있었기에 다쿠아즈 추천한다', 58, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '#티라미수(10000원) : 첨에는 맛있고 너무 달지 않아서 괜찮네 하지만 점점 갈수록 맛은 떨어지고 물기같이 뭐가 나오면서 축축했다 #작당아아(5500원) : 우리가 다 아는 아메리카노 차가운 맛이면 더 비율이나 맛이 좋았다 #모의아아(5500원) : 신맛이 나면서 아메리카노가 맞냐 싶은맛? 저는 별로였어요 달딜한 케익엔 역시 알던 아메리카노를 먹는게 제일 좋아용 13시40분쯤 갔는데 다 차서 웨이팅 번호치는데서 치고  주변에서 연락올때까지  기다리다가 들어갔어요 주문하면 직접자리까지 가져다 주시고 친절해요 #사진맛집 #분위기맛집 🧡인스타) 하은🐰(@haeun08_06)🧡', 13, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '연남동에서 가본 카페 중 가장 아쉬움이 많이 남는 곳. 비싼 가격, 평범한 맛, 불편한 테이블과 의자, 친절하다고 보기 어려운 서비스. 무엇하나 특별하다 느껴지는 점이 없어서 왜 이렇게까지 핫한 카페인지 의구심이 들었어요. 개인적으로 가장 실망스러웠던 부분은 ''제한시간'' 인데요, 비싼 돈 내고 이용하면서 들어온지 1시간59분 되자마자 나가달라는게 황당했어요. 시간 채워지길 기다렸다는 듯이 나가달라는게 호텔 체크아웃인줄 알았네요,, 조용하고 아늑한 공간을 추구한다 라는 방향성이 아니라, 그냥 더 많은 수익창조를 위해 회전을 돌린다 가 맞는 것 같아요, 적어도 제가 받은 느낌은 그랬습니다. 가실 분들은 철저한 제한시간이 있어 여유로운 대화를 나누기 어렵다는 점 참고하시면 좋을 것 같아요 :)', 54, 15, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '매장분위기 음식 전반적으로 괜찮습니다! 추천해용ㅎㅎ 티라미수 두명이 먹기에 넘 커서 못먹었는데 아쉬워요ㅠ 담에 또 와서 먹어보려구용', 42, 0, NULL, SYSTIMESTAMP);
