INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '선택할 키워드 진짜 많은데.. 직원분들 마스크 정말 정말 철저히 하셔서 너무 좋았구요 무화과케이크 진짜 맛있어요 돈이 아깝지 않았을정도로 에이드도 시간 지날수록 더 맛있어요 웨이팅 해서 들어간 카페는 오랜만인이 그럴 가치가 있어요 또 가고 싶어요 분위기도 감성적이고 존예에요', 12, 3, 'GOOD', SYSTIMESTAMP);
