INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '원두도 산미 있는 것, 없는 것 구분 되어 있어서 좋았구 직원분들도 친절히 알려주셔서 기분좋게 다녀왔어요~ 디져트도 하나하나 다 맛있었고 인테리어도 참 예뻤습니당❤', 13, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '딸기라떼는 딸기청+상단에 단 묽은 휘핑크림이 올려져있음. 한번은 먹을만함 딸기초코타르트는 초코가 진하고 딸기와 잘 어우러진다. 타르트지는 과자타입으로 아주 단단바삭 ...창가자리는 추워..', 46, 10, NULL, SYSTIMESTAMP);
