INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '엄청 귀여운 탁자에 앉아서 오밀조밀 먹었어요! 음료들 다 맛있는데 작당모의 홍차 달달한데 향이 기가막혀요,,, 댑악 다쿠아즈 귀여워', 4, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '인테리어가 멋져요! 미녀와 야수에 나오는 찻잔이 된느낌이랄까..디저트도 전반적으로 꽤나 괜찮은 편이었어요! 눈이 즐거운 카페입니다. 역시 연남동은 갬성을 먹고 자란다~~~~', 32, 6, 'GOOD', SYSTIMESTAMP);
