INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '웨이팅 있어서 한참 기다려야 함. sns에 올리기는 좋지만 가격에 비해 맛있는지는 모르겠음. 모든 음료에 딸기가 부족한 느낌이 듦. 플레이팅 하나는 끝내줌.', 228, 76, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '인테리어도 디저트도 다 너무 예뻤어요>.< 조명 약하고 자리 협소한 게 조금 단점이었지만, 그걸 다 잊을 만큼 만족스러운 카페였답니다 무화과 파운드케잌이랑 라떼 다 존맛 ㅜ!! 다른 과일 시즌 때도 가볼래요💓', 30, 1, 'GOOD', SYSTIMESTAMP);
