INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '평일 낮에 방문했는데도 웨이팅이 조금 있었어요! 직원분들 정말 친절하시구 티라미수가 존맛탱이었습니당,, 홍차 주문했는데 아마드티 사용하시길래 괜히 반가웠어요ㅎㅎ', 82, 17, 'GOOD', SYSTIMESTAMP);
