INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '딸기에이드는 흔히 예상 가능한 딸기청+탄산수 맛이고 아메리카노는 고소하다는 작당 원두로 했는데 고소한 맛보다는 쓴 맛이 강했고 티라미수는 카스테라 커피에 담궈서 겉에 살짝 생크림 바르고 위에 코코아 파우더 올린 맛. 아주 예상가는 맛이고 맛집카페인지는 모르겠다 ㅠㅜ', 51, 11, 'BAD', SYSTIMESTAMP);
