INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '디저트는 이쁘지만 맛은 그저 그렇고, 이쁘기만 한 카페라 이야기하기 불편해요. 직원들이 이용 규칙 설명할 때 느낌이, 명품매장에서 일하는 직원같은 태도에요. 창밖에 맞은편 건물 바로 보여서 담배 피우는 모습 직관 가능해요', 4, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '카운터 앞에 앉아있으면 계속 마스크 써달라고 하시던데 화장실앞 테이블쪽, 사각지대에 계신 분들도 좀 보고 말하세요. 불편하게 카페를 다녀왔네요', 40, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '가격대가 조금 있었지만 맛있었어요~ 말차슈페너가 맛있네요!! 가게가 넓지 않은데 핫플이라 사람은 매우 많아서 그런 점은 불편했지만 음료와 디저트가 맛있어서 괜찮았네요', 80, 12, 'GOOD', SYSTIMESTAMP);
