INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '연남동하면 작당모의죠,,핫플,,❤️‍🔥 컴포트미 케이크 꼭꼭 드세요ㅠㅠㅠㅠ 거짓말 안하고 초코라떼도 지금까지 먹어본 초코라떼 중에 제일 맛있어요.....🤦🏻‍♀️💛 분위기도 너무 좋고 직원분들도 친절해서 담에 또 올게요 ㅎㅎ', 1, 8, 'GOOD', SYSTIMESTAMP);
