INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '티라미수 맛있어요. 근데 티라미수 하나에 만원은 솔직히 너무 비싸다고 생각합니다.. 심지어 1인1메뉴인데 티라미수는 1인메뉴로도 안쳐준다니…. 양이 많아서 둘이서는 먹다가 지쳐요. 차라리 반으로 나눠서 5천원에 팔든가, 1인메뉴로 쳐주기라도 하면 좋겠네요', 27, 4, 'BAD', SYSTIMESTAMP);
