INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '새로운 시즌이 기대되서 자주 갑니다. 매장 이용시간이 최대 2시간이니 알고 가시면 좋아요. 웨이팅 입장 카톡 못봤었는데 전화 해주셨어요!', 114, 21, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '테이블은 별로 많지는 않은데 카페 분위기 쟝 조와오,, 원두 두개중에 고를 수 있눈데 전 산미있는거 안조와해서 산미없는걸로 골랐서욥 직원분들 친절하세오(з´⌣`ε)', 46, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '음료와 디저트 항상 맛있어용. 다만 의자가 항상불편!!! 그리고 대기순서 5분지났다고 연락없이 취소되서 이부분이 좀 안좋았습니다.', 121, 21, 'BAD', SYSTIMESTAMP);
