INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '커피 너무 맛있어요!! 여자 직원분 너무 친절하셨어요ㅠㅠ 사진 찍는다고 하니까 구도도 이쁘게 잡아주셨어요ㅎㅎ 근데 남자직원분?이신가 커피마시면서 얘기 잠깐 하는데 마스크쓰고 얘기하라고 눈치주셔서 좀 그랬네요 다른 손님들도 마스크 벗고 잘만 얘기하시던데 저희한테만 그러셔서 좀 당황스러웠네요', 34, 9, NULL, SYSTIMESTAMP);
