INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '날씨가 매우 더워서 나와 친구는 특별히이 가게에 갔어요. 그런데 매우 실망했어요 . 웨이터는 태도가 불친절했고, 계속 우리를 방해했어서, 이 집은 정말 비추천이에요. 그리고 위생도 안 좋고 벌레가 많아요. 나는 모두 다섯 마리의 벌레를 죽였다，너무 피곤해서 사진다 찍기 싫어요. 다시 한번 강조해요~그 여종업원과 빨간 머리 남자 종업원은 정말 싫다. 예의가 없어여.', 14, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '커피랑 디저트 예쁘고 맛도있어요! 백도복숭아 철인데 복숭아 맛있어요! 신기한게 좁은거같은데 넓고 좌석이 많은데 앉아보면 생각보다 옆테이블이랑 거리가 있어서 대화소리 들리거나 울리지 않아서 좋았어요🙂 착석시간 제한있다던데 2시간전에 나와서 그건 모르겠고 밖에 웨이팅 하는분들이 있어서 혹시나 오래 앉아있을 사람들은 힘드실듯', 8, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '분위기랑 비주얼은 굳. 맛이나 양은 특별하진않음..사진찍으러 가는곳.. 코로나 검열 굉장히 빡셈. 2시간 시간채우면 나가라하고 음식 잠깐이라도 안먹고 있으면 마스크쓰라고 달려옴... 시국이 시국인지라 맞긴하지만...그냥...그렇다구요...', 56, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '바닐라빈크림라떼 맛있어요. 티라미슈가 커서 다른 걸 먹지 못해 아쉬운. 평일 오픈 시간이라 사람 없어서 좋았는데 아래층 공사소리가 꽤 시끄러워요.', 59, 12, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '사진은 너무 예쁘게 나오는데 케익맛은 텁텁하고 딸기도 달지 않았어요ㅠ 빵은 좀 부드러운 것으로 바꾸시면 좋을 거 같습니다! 가격이 그렇게 비싸진 않았지만.. 그래도 가격 대비 케익맛은 별로였네요ㅠ 음료는 쏘쏘 괜찮아요!', 48, 9, NULL, SYSTIMESTAMP);
