INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '두번째 방문으로 이번엔 안 먹어본거 시켜봐야지 하고 티라미슈 주문했는데 진짜 맛있네요.. 너무 맛있어요. 디저트도 다 이뻐서 무조건 추천합니다.', 54, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '인테리어부터 디저트까지 진짜 이뻤고 신경 많이 쓰신거 같았습니다. 대기가 항상 있는 카페라 기대했는데 솔직히 기대 이상입니다. 인스타용 사진만 노려 모양 본새만 이쁘고 맛에 신경 안쓰는 다른 카페들과는 달리 타르트도 진짜 맛있고 좀 독특했습니다. 연남동 돌아다니면 작당모의가 항상 눈에 띄어 언제가보지 고민만 했었는데 오늘 드디어 소원 풀었네요. 재방문 꼭 해야겠어요. 기다리는데에는 다 이유가 있는 듯.', 45, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '오픈 했을때 부터 자주 갔는데 커피와 디저트 맛도 사장님의 디테일 등의 초심을 잃지않는 카페인거 같아요! 코로나 이후에도 방역수칙 준수하면서 운영하는 모습이 좋았습니다', 78, 18, 'GOOD', SYSTIMESTAMP);
