INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '여자친구가 찾아서 방문했는데 테이블도 띄워서 운영하시고 일단 방역수칙이 철저해서 편하게 있다왔어요 카프레제 샐러드는 딱 먹기 좋았고 여자친구는 야채들어간 샌드위치가 맛있다고했는데 전 브라운? 치즈랑 그래놀라들어간 샌드위치가 제일 좋았어요 직원분들 친절하고 분위기 좋고 깨끗해서 코로나 끝나면 편하게 자주오고싶네요 번창하세요^^', 89, 13, 'GOOD', SYSTIMESTAMP);
