INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '인테리어가 넘 예뻐요 따뜻하고 군데군데 신경 쓰신게 느껴지고 자리마다 느낌이 달라서 또 오고 싶은 곳이였답니다. 좋은건 테이블마다 좌석 간격도 적당히 있어서 좋았구요!', 56, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '여기 리뷰 다 알바인건지.. 리뷰만 믿고 갔다가^^;; 별 5개줘야 위로 올라가나요? 브런치 메뉴 너무해서요ㅠㅠ 샐러드 저 작은 접시 하나 나와서 깜짝놀랐네요 (7500원) 정말 식전 에피타이저라고 할 만큼 아니 그보다 적구요 인당 브런치 메뉴는 무조건 시켜야 함 친구가 2.5 단계 때문에 급조한 메뉴라고 하는데ㅋㅋ 정답인 것 같네요~ 샌드위치는 샌드위치가 아니예요 바게트빵에 생크림 발라져 있..ㅋㅋ 말잇못ㅠ빵이 너무 질겨서 칼질안됨 장점 : 카페 분위기는 좋아요! 화장실 깨끗해요 직원분들 친절한 편 음료 맛있는데 브런치(브라운)는 놉 결론 : 웃돈내고 홍대 장소이용이 가능 아, 많이 추워요~ 담요 덮어야되어요 그리고 갠적으론 샐러드에 치즈 푸석', 3, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '작당모의는 조용한 카페라고 해서 다녀왔지만, 일반 카페와 같은 시끌 벅적 한 느낌이었어요. 업장의 분위기나 근무하시는 직원분들의 서비스는 정말 좋았어요! 음료는 밀크티가 정말 맛있어서 추천드려요.', 78, 17, 'GOOD', SYSTIMESTAMP);
