INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '작당모의 오랜만에 갔는데 확장하셨더라구요! 브런치 메뉴 판매하셔서 카페에 앉아서 먹었는데 안전수칙 굉장히 잘 지키시는것같았어요 역시 맛있어요', 40, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '2시간30 이용시간과 4명이상입장안돼요 복숭아시즌으로 복숭아음료나 디저트먹었는데 장마철이라 복숭아가 맛있지않았지만 향긋하고 좋았어요ㅎㅎ 음료는 조금 많이 달았어요ㅎ 디저트 그냥 파운드케잌잘라서 플레이팅 이쁘게 해주셨어요~ 플레이팅 이뻐요~ 친구들이랑 사진찍으러 가는 인별 카페', 25, 8, 'GOOD', SYSTIMESTAMP);
