INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '#ZM에이드 #ZM과일차 #ZM보울케이크 #연남동 작당모의 여름메뉴를 먹었는데 맛있더라구요 바로 저녁을 먹어야하는데도 불구하고 맛있어서 다먹었네요 과일 산뜻 달콤함 좋았고 예쁘기도 넘 예뻐요 ㅋ 가을 메뉴도 벌써부터 기대되네요 😋', 78, 13, 'GOOD', SYSTIMESTAMP);
