INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '브런치 시키면 매장에서 먹을 수 있더라구요 안전수칙 지켜가면서 먹고 나왔어요 직원분들 다 친절 하고 음료,브런치 다 맛있었어요 가격도 나쁘지 않아요 짱짱', 30, 7, 'GOOD', SYSTIMESTAMP);
