INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '카페 안 분위기가 따스하고 편안합니다. 사진도 예쁘게 잘 나오고, 조용한 카페를 추구한다고 하시던데 덕분에 어머님 모시고 도란도란 얘기 잘하다가 갑니다. 요새 핫플이라고 하는 카페들 너무 시끄러워서ㅠㅠ... 여름 시즌 디저트 너무 맛있게 잘먹었습니다. 주변에 예쁜 소품샵도 많으니 한번씩 들려보셔도 좋을 것 같아요! 또 방문하겠습니다^^', 49, 10, 'GOOD', SYSTIMESTAMP);
