INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '실내 장소가 협소해서 별하나 뺏어요...ㅎㅎㅎ 벽보고 마시고 목소리도 조용조용해야하네요... 대신 분위기는 아늑하고 조용해요 ㅎㅎㅎ', 24, 10, 'GOOD', SYSTIMESTAMP);
