INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '음료와 케익 너무예뻐요 하지만 너무 달아서 특히 케익 ㅜ ㅜ 다남겼어요 ....7월13일월요일오후1시경에 갔었는데 케익이 너무 달아 포장 가능여부물었더니 저희포장안되는데요 라고 퉁명스럽게 답하셔서..... 응대가 마이너스요인이라는생각이들었습니다....두번은 안갈것같아요', 3, 10, 'BAD', SYSTIMESTAMP);
