INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '커피맛이 좋아요~ 티라미수도 맛있어요. 양이 많아 좀 남겼어요. 티라미수는 인터넷에 나온 가격보다 500원 더 비싼 8천원이였어요', 16, 5, NULL, SYSTIMESTAMP);
