INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '메뉴들은 가격대비 별로였어요 티라미수는 크림은 맛있는데 밑에 빵 부분이 너무 싱거웠고 망고라떼는 평범했는데 망고베이스가 너무 적어서 나중에는 밍밍했어요 그리고 2시간 30분 시간 제한이 있는데 시간이 다 되기도 전에 나가라고 해서 불쾌했습니다 재방문은 안 할거 같아요', 44, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '분위기도 좋고 커피도 에이드도 케이크도 맛있엇어요!! 또 가고싶어요ㅠㅠㅠ 너무 예쁘게 잘 꾸며져있어거 진짜 취향저격 음료랑 디저트류가 전체적으로 가격대가 있는편이지만 전 좋아용 ㅜ', 46, 1, 'GOOD', SYSTIMESTAMP);
