INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '분위기도 좋고 특히 소곤소곤 말해야하는 카페규칙이 좋았습니다 미리 그렇게 말씀해주시니 다들 매너있게 이용가능한,,ㅎㅎ 저는 망고를 좋아하지 않아서 메뉴를 완전히 즐기지는 못했지만 망고를 싫어하는 제가 맛봐도 맛있다는 것을 알 수 있었습니다 특히 타르트,,,,정말 최고,,,,', 28, 1, 'GOOD', SYSTIMESTAMP);
