INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '연남동 카페들 어딜가도 시끄러운데ㅜ 여긴 노래도 조용하고 전체적으로 차분한 분위기입니다. 커피를 못마시는데, 차 종류가 많아서 좋았어요! 딸기라떼랑 블루밍오렌지티 추천합니당 ^_^b', 46, 3, 'GOOD', SYSTIMESTAMP);
