INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '분위기 깔끔 과일음료 굿굿 #연남동 #작당모의 #카페 #연남동핫플 #연남동카페 #분위기좋은카페 #연남동케이크 #연남동커피 #연남동맛집 #커피맛집 #에이드맛집', 21, 7, 'GOOD', SYSTIMESTAMP);
