INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '3시간인가 시간 제한이 있었어요! 그래도 그정도면 충분히 먹고 떠들 수 있는 합리적인 시간이라고 생각해요~ 벌써 3번째 방문인데 갈때마다 분위기도 좋고 커피도 맛있어요!! 코코넛커피 추천합니다! 일본인들도 많이 오던데 연남동 핫플인가봐요~ 주말엔 웨이팅이 있을 수 있습니다!', 36, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '작당모의'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '머리띠 하신 직원 분 얼마나 친절하시던지.. 창가자리 있다고 먼저 말씀해주시고 너무 친절하세요 덕분에 좋은자리 겟! 너무 감사합니다~~ 근데 마스크를 써야지만 음료를 테이블에 놔주시는 건 너무 융통성 없다고 느꼈네요ㅎㅎ 아니면 직접 가져가게 하는 것도 좋겠네요 그 짓은 참 융통성 없던 짓이었어요~!', 118, 22, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '우연하게 본 행복이라는 이름의 커피 페어링 디저트가 궁금해서 방문했습니다  7,8월 시즌 디저트로 복숭아아몬드크림으로 구운 타르트위에 복숭아 와인절임 글라사주로 코팅되어 씨를 빼고 마스카포네 크림으로 채우고 천도복숭아잼과 천도복숭아 와인절임으로 구성되어 복숭아의 다양한 버젼의 맛을 담은 이쁜 디져트였네요 추천해준 과일향 살짝 나는 커피와의 페어링도 좋았습니다 여성들이 좋아할만한 이쁜 디저트였네요 잘 먹었습니다', 18, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '일년만에 다시 찾아온 행복 시즌… 올해는 일이 많아서 이리저리 가기 힘들었는데, 그래도 행복은 먹어야겠어서 방문 했습니다. 역시나 명성이 유명해져 이제 대기가 길어졌네요… 복숭아는 정말 맛있고, 어우러진 크림들도 최고였습니다. 이번에 페어링된 커피는 작년보다 더욱 산뜻한 복숭아 향이 어우러져서. 언제나 맛있게 먹을 수 있었습니다.', 76, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '이미커피 복숭아 🍑 디져트 🍨 시즌이 돌아왔습니다, 기갼은 대략 지금부터 8월말로 예상됩니다, 오늘도 11시남짓 매장 에 도착을 해서 페이히어 웨이팅에 등록을 해두고서 12시에 오픈할때까지 기다립니다, 순서대로 입장해서 자리를잡고서 주문을합니다 오늘은 행복 🍑 디져트하고 어울리는 냉커피를 페어링 합니다, 커피에 얼음은 안들어갑니다, 잠시후에 복숭아 디져트하고 커피를 받고 안내카드와 서버분이 커피와 디져트 설명을 해줍니다, 설명은 목소리만 나오는 영상은 유튜브에 업로드 합니다,  복숭아를 나이프로 반을 갈라서 드시면됩니다 맨아래부분은 과자 🍪 이니 나이프로 바닥 받침대까지 잘라서 드셔도 됩니다,  복숭아 안쪽과 접시바닥의 치즈가 단맛이 있으니 소스처럼 드시면 됩니다, 오늘도 먹는시간 만큼은 좋은시간이었습니다', 93, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '행복먹으러 이미에 방문했는데 작년보다 복숭아가 더 물복같은 느낌으로 달게 느껴졌다. 타르트속에서 함께 씹히는 복숭아절임의 맛이 좋았고 의외로 수박멜론무스가 맛있었다. 확실히 위에올려진 수박과 함께 무스를 먹으면 더 먹는게 식감도 살고 맛도 더 풍부해지는듯. 함께 페어링으로 추천해주시는 커피가 디저트랑 정말 잘어울려서 여름에 생각날것같다. 마시면서 멜론향이 난다고나할까. 독특하고 여름의 맛을 담은 디저트같다.', 20, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '유튜브에서 영상을 보고 방문을 했습니다,12시 오픈이라서 조금전에 갑니다, 처음이라서 디저트와 커피를 추천받고 비가 살짝와서 따뜻한 커피로 해달라고 했습니다, 커피와 디져트를 페어링 추천해주는 카페^^, 홀직원분이 설명을  잘해줍니다, 포도향 스키틀즈향이 나는 커피와 생크림 자두디져트 입니다 안내카드도 같이 줍니다, 조용한 분위기입니다, ❤🧡💛💚💙🤎💜💜🤎💙💚💛🧡❤ ✅️네이버리뷰 누적 총 조회수가 500만 회를 돌파했습니다 리뷰어순위 300등입니다 대한민국 도시거리와 둘레길을 걸어 다니면서 음식점과 경치를 소개하는 리뷰어 & 유튜버 ✅️네이버검색:먹고걷고햇빛듬뿍 네이버블로그 & 네이버클립 🛑유튜브검색 1)음식먹고햇빛듬뿍 (음식점,카페) 2)걸으면서햇빛가득 (도시풍경,둘레길풍경) ❤🧡💛💚💙🤎💜💜🤎💙💚💛🧡', 39, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '비주얼부터 맛까지 완벽했던 행복🍑 달달하면서 향긋한 복숭아와 고소한 크림치즈 조합이 좋았고 바삭하게 씹히는 타르트까지 최고였어요👍🏻 드립커피를 별로 안 좋아해서 개인적으로 커피는 아쉬웠지만 행복 너무 맛있게 먹었습니다 굿굿 토요일 기준 12시 18분에 웨이팅 대기 걸었는데 17번이었고 1시간 30분 정도 기다렸어요!! 오픈런 하시는 걸 추천해요👍🏻', 98, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '서울출장중에 시간낭비하지 않으려고 중간에 어디갈지 엄청 고민했음 카페 검색결과 이 인근에선 가고싶은곳이 여기밖에 없었음 마침 오픈시간즈음 시간이 비어서 들름 11:39 도착 앞에 3팀 있었음 드립커피라 그런지 조금 대기시간이 있긴한데 디저트도 커피도 너무 좋았음 사장님 이렇게 해서 남는게 있으신가요? 또 가고 싶음', 44, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '미당농원 복숭아로 만든 행복! 토요일 11시40분쯤 도착해 대기번호7번 받고 12시 오픈과 동시에 입장(8번까지는 바로 입장 할수 있는듯) 주문을 순서대로 받아서 실제 커피와 행복을 받기까지는 대략 30~40분 걸린듯. 복숭아 디저트 행복을 먹으니 생복숭아 먹을때와 또다른 맛 또다른 느낌^^* 손수 손질하고 안에 크림치즈까지 넣는 힘든 작업을 생각하니 가격이 전혀 아깝지 않은.. 드립 내리시는 여직원분이 넘 멋지셨어요!! 직원분들의 여유로움 덕에 전혀 복잡하거나 바빠보이지 않아 넘 좋았습니다 ㅎㅎ', 50, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '카페를 오픈런 해보기는 처음. 11시55분 도착. 앞에 4팀 대기중. 12시 정각에 오픈. 세 종류의 디저트에서 원하는 것을 고르면 이에 맞는 커피를 추천해주는데 커피는 네 종류. 디저트 2개 & 커피 2잔 주문 33,800원. 선택의 폭과 가성비는 좀 떨어지지만 그만큼 커피와 디저트가 맛있을 거라는 기대를 가져본다. Deep Redwine은 풍미와 맛이 아주 좋다♡', 52, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '시즌마다 디저트 메뉴가 달라지는 곳이라 해서 방문했어요 복숭아는 끝나서 아쉽게 먹지 못했지만🥹 디저트도 커피도 다 맛있었습니다', 37, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '☕️디저트를 고르면 핸드드립커피 페어링 해줌 체리파리브레스트&딥레드와인 >>>       카라멜 🍒🍷생체리와 초코크림 맛없없!! 비싸지만 맛있다.. 🍯 카라멜디저트: 아몬드의 고소함과 단맛이 잘 어우러졌지만, 익숙한 조합이라 인상적이진 않음. 카라멜 풍미도 기대보다 평범 ⏳ 핸드드립이라 시간이 많이 걸리니 여유롭게 방문하는 걸 추천! 커피랑 디저트 하나하나 설명해줘서 더 좋았음 🥂 고급스러운 커피잔 디테일', 43, 2, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '기다림도 조화로운 이미커피에 행복을 맞으러 다녀왔습니다. 더위와 대기에 포기하지 마세요. 일 년에 한 번 오는 왕 큰 복이니까요. 황도보다 백도, 물복보다 딱복을 더 좋아하는데 제때 늦지 않게 다녀왔습니다. 시즌 동안 뒤로는 황도로 변경될 예정이라는 안내를 받아서요. 이래도 행복, 저래도 행복일테지만 가장 좋아하는 것을 고르려면 지금 만남이 조화도 ‘딱’, 이라는 생각이 듭니다. 그야말로 먹고 마셨어요. 페어링 커피까지 너무 몽땅 다 복숭아다 싶지요. 붉음 안에 노랑, 초록, 나무색이 모두 있으니 색이 만들어지는 과정 역시 조화임을 느낍니다. 산뜻한 질감, 경쾌한 목 넘김, 따뜻한 커피지만 시원한 차를 마신 듯한 잔상을 남깁니다. 의자 밑 바구니, 나란한 기물들, 정갈히 놓인 정경 속 행복을 누렸습니다.🍑', 63, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '둘이 바 자리에 앉아서 스페셜티 커피와 좋은 분위기까지 잘 즐기고 왔습니다! 코리아 커피위크에서 부스 보고, 꼭 가봐야지 했는데 대기가 길어서 몇 번 실패했다가 이번에 갔네요! 매월 바뀌는 페어링과 원두가 넘 좋고, 핸드드립도 잘 내려주셔서 커피 잘 모르는 친구도 정말 맛있다고 좋아했어요~☕️ 디저트와 커피도 정말 잘 어울렸답니다! 이미양과점도 따로 운영하실 정도니 당연히 맛있겠죠.. 시즌에 맞는 과일을 활용한 디저트들이 계절을 온전히 즐기게 하는 것 같아 더 좋았습니다.  담에는 디저트 두개 다 뿌수러 갈거예요...🫶', 25, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '지나가다가 좋아보이는데? 하고 생각 없이 들어갔어요. 그런데 디저트를 고르면 어울리는 커피를 추천해 주는 특별한 곳이었습니다. 물론 디저트는 필수는 아니라 안 드셔도 되는데 드시는걸 추천합니다! 카라멜 크림이랑 아몬드가 있는 디저트였는데 넘 맛있었어요!! 핸드드립 커피를 와인잔? 같은 잔에 담아주는데 그게 또 예뻤고, 다른 병에 추가 커피를 더 담아줘요. 그래서 생각보다 양이 되게 많았습니다. 그리고 직원 분이 너무 너무 친절하시고, 고급 레스토랑처럼? 디저트와 커피에 대해 설명해 주셔서 좋았어요!!', 31, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
