INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '한잔 한잔 원두를 즉석에서 갈아서 핸드 드립으로 내려줘요 커피와 어울리는 디저트를 페어링 해서 설명해줘서 특별했어요 커피의 신선함이 입안에 계속남아요 청포도  판나코타  크림 달지 않고 부드러워요 애플청포도 식감 상쾌해요 갠적으로 넘 달지 않아 좋았어요 재방문 할거예요', 26, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '디저트를 고르면 어울리는 커피를 추천해주심. 커피만 주문해도 됨. 전부 핸드드립인데 커피가 정말 맛있음. 디카페인 있지만 음료는 전부 커피뿐이라 커피 안마시는 일행이 있다면 방문하기 곤란할듯. 디저트는 정말 작지만 정말 비쌈. 직원분들 친절하시고 자세히 설명해주셔서 재미있었음. 가게 분위기가 전체적으로 차분 조용해서, 시끄럽고 사람 많은 카페 싫은 분들에게 추천. 좌석 간격과 테이블도 넓어서 좋음. 다만 그만큼 자리가 많진 않아서 웨이팅 있기도 함.', 39, 9, 'GOOD', SYSTIMESTAMP);
