INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '주말이라 웨이팅이 길어 1시반쯤 예약걸어두고 4시반쯤 입장했어요 그치만 그만큼 디저트도 맛있고, 페어링해주신 커피도 맛있었습니다! 디저트와 커피에 대해 설명해주시는 점도 좋았어요', 83, 16, 'GOOD', SYSTIMESTAMP);
