INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '디저트를 고르면 커피를 페어링 해주십니다. 분위기있고 대접받는 기분을 만들어 주는 카페입니다. 이런 가게들이 많아졌으면 좋겠어요', 13, 1, NULL, SYSTIMESTAMP);
