INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '금요일 3시 30분 방문했을 때 웨이팅 앞에 4팀 있어서 3-40분 정도 기다렸어요. 평소 커피 잘 안 마시고 특유의 시고 쓴 맛 싫어합니다. 근데 여기는 커피가 너무 깔끔하고 디저트랑 같이 먹으니 잘 어울렸어요. 케이크도 달지 않고 부드럽고 촉촉해서 맛있게 먹었습니다. 시간 여유 있을 때 또 방문해보고 싶어요. 프랑스인 친구랑 같이 갔는데 친구도 너무 좋아했습니다!', 118, 20, 'GOOD', SYSTIMESTAMP);
