INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '이미 커피 너무 궁금하고 마셔보고싶었어요 웨이팅 조금 하고 들어갔어요 커피 너~~~무 맛있었어요 주문후 디저트랑 커피에 대해 설명도 해주시고 좋았어요 직원분들이 엄청 친절하세여', 87, 12, 'GOOD', SYSTIMESTAMP);
