INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '금요일 퇴근 후에 조용히 시간을 보내고 싶어서 오랜만에 방문했습니다. 월간페어링 바닐라 망고 타르트와 함께, 페어링된 합 블렌드를 대신하여 디카페인 원두를 골랐는데. 산뜻한 맛의 원두가 달고 부드러운 바닐라 크림 및 고소한 아몬드와도 잘 어우러지는 맛이어서 조용히 잘 보낼 수 있었네요.', 260, 64, 'GOOD', SYSTIMESTAMP);
