INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '두번째 방문, 커피만 먹을때 보단 확실히 디저트와 함께하는 느낌이 와우임, 커피의 과일향은 정말 이것이 커피인가 싶음. 산딸기 케잌의 부드러움은 진짜임', 51, 16, 'GOOD', SYSTIMESTAMP);
