INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '디저트를 고르면 그 디저트에 어울리는 커피를 추천.페어링해주는 홍대에서 정말 소중하게 애정하는 진짜 보석같은 커피집. 디저트의 라인업도 시즌별로 새로운 디저트가 나올때에 맞춰 하나씩 음미해보는 재미도 있고. 무엇보다 정말 커피가!! 향부터 끝맛까지 어쩌면 이렇게 한잔에 다양한 향과 맛이 터지는지! 감탄하며 마시는 !! (저는 오늘 흰꽃이 올려진 커스터드 크림이 든 다쿠아즈에 (파인애플과 망고 과육이 든) 열대 과일향 가득한 커피를 맞춰주셨어요 ! 와. 정말 꽃밭에서 마시는것 같았어요.(커피보다 차에 가까운 느낌)정말 이미 커피는 꼭! 경험해보세요. 늘 마시던 까만 커피가 다른 표정과 다른 감각으로 다가옵니다.', 22, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
