INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '디저트를 고르면 그에 어울리는 커피를 내어주시는 게 독특하고 새로운 경험이었어요. 무엇보다 페어링된 커피가 진짜진짜 맛있었습니다. 적혀있는 노트 하나하나가 살아있는 것 같았어요. 저렴하진 않지만 충분히 가치있다고 느꼈습니다.', 0, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
