INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '와우! 베리굿! 베리나이스🩶 블루라벤더당쥬 8.3 블루베리초코릿(디저트하면 2,000원 할인) 디카페인 7.0 이렇게 주문했어용!! 디저트와 페어링 좋은 원두를 골라주는 색다른 디저트 카페얘요~! 디저트가 3종류여서 좀 아쉬웠지만 달마다 바뀐다고 하네요~! 몇번 더 와야할 이유예요.. ㅋ 커피맛이 산뜻 고급 깔끔 아주 맛있어요~! 디저트는 조금 아쉬운게 너무 깔끔 산뜻해서~ 맛이 없다기보다…. 그날 뭔가 더 해비한게 먹고 싶었나봄 ㅋ 사장님 너무 친절하십니다~! 소스윗🖤 조용하고 분위기도 좋고.. 대화하기 데이트하기 좋아요 혼자오기도 좋은데 카공하기는 안 좋음요~!', 72, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
