INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '디저트 맛집이라 찾아갔어요. 곁들어 먹으니 맛이 꽤 괜찮았어요. 초콜릿 케잌을 좋아하진 않는데 저녁때 갔더니 이것만 남아있어 주문했습니다. 얼그레이 케이크나 복숭아 케잌을  먹고싶었는데.. 결과적으론 초코 케잌도 맛밌었어요. 저녁을 배부르게 먹었는데도 맛있게 먹었습니다. 초콜릿베이스 케이크에 산딸기 시럽과 산딸기가 어우러진 디저트였어요. 여기에 어울리는 산미가 있는 와인맛이 들여진 커피를 권해주셨습니다. 두 맛이 잘 어우러져 기분 좋게 먹었어요. 아늑하고 편안한 인테리어도 마음에 들고요. 데이트하기 좋은곳이었습니다~~^^', 42, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '드립커피도 맛나고 디저트도 맛있어요. 디저트를 고르면 커피를 페어링해준다는데 저녁에 방문한터라 디카페인으로 마셨어요. 커피 맛과 디자트와의 조화가 좋았어요. 단 직원분의 커피를 설명하는데 목소리가 너무 작아서 듣기 어려웠고, 다른 테이블의 목소리도 커서 뭐라고 설명하는지 안들리더라구요. 어차피 설명카드가 있어서 그거 읽으면 되는 터라 안들려도 그려려니 했고요. 디저트에 페어링하는 커피를 추천해주는게 컨셉이래도 고객의 취향에 따른 커피 선택도 리스펙하는 태도도 같이 갖췄으면 하는 바람이에요. 커피&디저트 모두 맛있고 좋지만, 직원분들의 응대는 좀 아쉬웠어요. 홍대 연남 일대에 널린게 카페들이고 맛도 쳐지지 않아서 여길 굳이 찾아가지는 않을듯.', 85, 18, NULL, SYSTIMESTAMP);
