INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '핸드드립 커피가 일품입니다. 그래서 커피 나오는데 시간이 좀 걸리며, 주말 웨이팅이 있어요. 블루리본에 오래 등재된 곳입니다.', 11, 1, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '늦은 시간에 방문해서 디저트 초이스가 없었지만 너무 맛있었습니다 케잌도 커피에 매치해주는 커피까지 갓벽한 곳이네요 또 가고 싶은 맛집입니다', 3, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '디저트를 선택하면 어울리는 커피를 추천해주는 곳! 드립커피만 있지만 아이스도 가능. 처음 이용하는 방법을 설명해주셨던 직원분이 너무 친절하셨고, 제가 산미있는 커피를 안좋아하는데 디저트와 잘 어울리는 커피라고 하셔서 도전해봤더니 너무 맛있었어요! 디저트와 커피에 대해서도 잘 설명해주셔서 뭔가 대접받는 기분이었어요. 기회가 된다면 다른 디저트 나왔을때 또 방문해보고싶어요.', 45, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '핸드드립전문 카페네요 딸기맛초콜릿 커피는 커피향과 커피맛이 강하게 나는데 신기하게 딸기향과 초콜릿맛이 나요 합블렌드커피와 커피맛이 확 비교가됩니다 디저트와 같이 먹어도 좋을것같아요', 47, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '여기 너무 맛있어요ㅜㅜ 감자큐브 먼저 먹으라고 설명해주시는데 직원분들도 친절하시구 제과 자부심 있으신 거 같아서 믿음이 가네요 자꾸 생각나는 맛이에요', 19, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '커피가 정말 맛있고 디저트랑 어울리는 커피를 추천해주셔서 디저트랑 먹으니 너무 잘 어울립니다 커피와 디저트의 맛이 더 풍부해지는거 같아요 매달 디저트가 바껴서 디저트 좋아하시면 매달 가볼만한거 같아여 디저트도 예쁘고 맛도 예뻐요 다만 평일이였는데도 대기가 길어답니다', 0, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '금요일 늦은 저녁, 1월 첫 주간 페어링 체리 포레누아 몽블랑과 디카페인 커피입니다. 포레누아 케이크의 맛을 살리면서, 크런키한 맛도 동시에 전해집니다. 통 체리가 밖에도, 안에도 들어 있어서 과육을 온전히 즐길 수 있으며, 겉에 어우러진 크림들이 부드럽고 달고 진한 초콜릿 맛으로 다가옵니다. 함께한 커피는 디카페인이라 정식 페어링은 아니지만, 약간의 산미가 있어 산뜻하게 마무리지을 수 있었습니다.', 73, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '조용히 즐기고 온 크리스마스 사일런트 파티, 크사파. 항상 고민하다가, 이번에는 일정적으로 맞아서 참석할 수 있었는데. 정말 좋은 시간이었습니다. 이어지는 코스들과 그날의 날씨가 너무 어우러졌네요. 따뜻한 칠리콘카르네와 함께하는 와인, 이어지는 에그노그와 슈톨렌, 마무리까지도 완벽한 하루였습니다. 조용히, 카톡으로만 소통하고 시간을 보내는 것도 역시 색다르니 재밌네요. 식사를 하고 방문했다면 정말 다 먹기 힘들었을 거 같단 생각이 들 정도로 푸짐하고 맛있었습니다.', 6, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '고급스런 핸드드립 카페 발견, 심플하면서도 깊이있는 아늑함이 커피맛과 아주 잘 어울리는듯, 특히 정말 신기할정도의. 과일향이 느껴지는. 딸기맛초콜릿 커피는 꼭한번.드셔보시길', 18, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '연남에 이미 카페가 두 곳 있는데 동교 쪽 이미 카페에 오게 됐어요. 카페가 넓지는 않아서 이트인하려면 웨이팅 등록하고 기다려야 해서 디저트만 포장했어요. 포장 기다리면서 앉아서 구경만 했는데 오페라 케이크 나오는 세팅이 이뻐서 찰칵 📸 테이크 아웃했던 딸기 몽블랑과 바닐라 무스.. 몽블랑 특유의 꾸덕함 선호하지 않는데 딸기맛 크림이 부드럽게 풀어져서 산뜻했어요. 엘더플라워 향과 파인애플 인서트가 더해진 바닐라 무스도 산뜻하고 가볍게 녹았어요. 다음에 커피 페어링으로 먹어보고 싶고 다른 매장도 가보려고 해요', 16, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '늦게 도착해서 어쩌나 싶었는데 그런 걱정이 무색해지게 코스 순서대로 착착 내어주셨고, 저번에 올드맨션에서도 느꼈듯이 모두들 세심하고 친절하셔서 좋은 시간 보내고 올 수 있었어요. 사실 그동안 슈톨렌에 대해서 매력을 크게 못 느끼고 있었는데 이미커피의 초코 슈톨렌..! 🍫 이젠 구할 수 없지만 당장 주문하고 싶어지는 맛이었어요ㅠㅠ 중간에 재미난 퀴즈와 유려한 말 솜씨 덕분에 크사파가 더 재미있었고, 모델이 영 엉성한데도 불구하고 너무나 정성스레 찍어주셔서 송구스러웠던 기념사진까지 감사드립니다.', 6, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '영상 7도라서 밖에서 웨이팅 가능했어요. 웨이팅 의자에 앉아 카페 문 열릴때마다 나는 커피 향이 예술😇 디저트와 페어링해서 먹는 곳이기에 디저트를 먼저 고르면, 직원분이 어울리는 커피를 추천해줘요. 오페라 라는 커피시럽시트+커피크림+가나슈 디저트와 견과류처럼 고소한 합블렌드 커피를 마셨어요. 결과는 대만족 😋 디저트가 주기적으로 바뀌는 것 같은데 다음 계절에 또가보려구요 ☕️', 61, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '카페 특성상 자리가 빨리 비워지는 게 아니라 웨이팅이 조금 길 수 있어서 추운 요즘에는 조금 각오하셔야합니다. 3명이서 갔고 2명 자리만 나서 추가로 기다려야될 거 같았는데 융통성 있게 2명 자리에 먼저 앉게 해 주시고 3명 이상 앉을 수 있는 자리가 비게 되면 바꿔주셔서 추위에 더 떨지 않아도 되었습니다. 디저트 많이 달지 않으면서 커피와 궁합이 잘 맞아서 좋았습니다. 여기는 드립 커피만 하는 곳이고 엄마는 신맛 없는 거 좋아하셔서 합블랜드, 저는 신맛 적당히 나도 괜찮아서 에티오피아, 동생은 나머지 신맛 강한 거 마셨어요. 동생이 본인거 맛 안보여준다고 그래서 합블랜드랑 에티오피아만 번갈나가면서 맛 봤는데 엄마랑 합의된게 신맛이 살짝 가미되서 밸런스가 더 좋은 에티오피아가 더 맛있다고 결론내렸습니다ㅎㅎ', 73, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '이미 커피에 다녀왔습니다. 심플한 나무느낌 최대한 꾸밈을 절제한 늬낌의 카페로 저녁시간에 방문하니 조명과 함께 기분 좋은 카페 였어요~ 방문하자마자 넘 친절하게 설명을 넘 잘 해주시더라구요^^ 편안하고 좋았습니다. 드립커피 전문점인지 모르고 방문했어요~ 깔끔하고 좋았습니다^^ 한켠에 놓인 큰 트리가 넘 예쁘고 좋았답니다 드립커피 전문점이라니! 쉽게 찾아보기 힘든 카페라 독특하고 좋았답니다^^', 35, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '슈톨렌 타르트와 리치베리무스 케이크 중에 고민하다가 리치 무스로 골랐는데, 페어링한 커피는 정말 말씀대로 베리가 섞인 초코퍼지를 먹는 느낌이 들어 신선했네요. 리치크림도 맛있었구요. 다만 역시 슈톨렌 타르트를 맛보지 못한 건 아쉬워서 다음에도 방문할 예정입니다.', 3, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '몽블랑이 먹고싶어서 방문했습니다. 마침 제가 홍대에 볼일이 있을때 체리몽블랑이 또 나온다고 sns에 올라와서 방문해서 먹어야겠다싶어서 가자마자 웨이팅신청하고 볼일보러 다녔던것같아요. 역시나 친절하셨고요, 커피도 어울리는걸로 추천받아서 잘먹었습니다. 디저트 속에 들어가는 딸기랑 체리가 정말 맛이 좋더라구요. 딸기는 정석적으로 잘만든 디저트였고 체리는 설명에도 적혀져있는걸 나중에 봤는데 식감이 재밌어서 잘먹었어요. 하단부분이  타르트가 아니고 사브레같은 거였는데 확실히 먹는재미가 있고 맛도 있었습니다. 다음에 또 방문하고싶네요~', 9, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '가향커피로 페어링이라니....가향커피라고 안알려주고 스페셜티인거처럼 우리는 복숭아 디져트가 있는데 이 커피에서 복숭아 맛이나 그래서 커피와 디저트 페어링하기에 너무 좋아라고 소개하는 그런 카페..', 52, 13, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '혼자서도 즐거운 크리스마스 사일런트 파티! 처음이었는데 지각까지 해서 초반에 허겁지겁이었지만 맛있는 음식에 음료에 행복해질 수 밖에 없는 시간이었다 정말!', 95, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '디저트와 어울리는 커피를 같이 페어링하셔서 주시는데, 디저트가 정말 특이하고 맛있어요! 각 재료의 맛이 잘 살아있는 방식으로 조합되어 즐길 수 있었습니다. 내부의 인테리어도 좋았어요.', 30, 0, 'GOOD', SYSTIMESTAMP);
