INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '크리스마스 사일런트 파티 다녀왔어요 새로운 경험! 다 좋앗는데 그중 원픽을 고르라면 페어링된 글뤼바인이 너무 맛잇엇네요 초코슈톨렌은 슈톨렌 특유의 향긋한 럼향이 느껴지질 않아서 아쉽고 역시 클래식이 베스트!입니당ㅎㅎ', 68, 18, 'GOOD', SYSTIMESTAMP);
