INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '디저트를 시키면 어울리는 핸드드립커피를 페어링 시켜주세요 🌟 다른 커피 친구꺼 한입 먹어봤는데 확실히 페어링 시켜준 커피가 디저트랑 더 잘 어울렸어요 커피로 어떻게 이런맛을 내지? 신비한 맛의 세계였습니다', 11, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '오렌지 다쿠아즈와 가을의 별미 몽블랑을 먹기위해 방문했네요. 사실 타르트타탕과 몽블랑 사이에서 고민을 좀 많이 했는데, 괜찮은 선택이었어요~ 일단 다쿠아즈와 페어링되는 커피도 오렌지향이 산뜻하게 나는데, 이게 이전에 오-치즈퐁 때와 같은 페어링 커피인듯 합니다. 산뜻한 맛과 향이 달콤한 다쿠아즈 크림과 어우러집니다. 다쿠아즈, 크림, 오렌지필과 함께 한입 가득 먹으면. 다양한 맛이 어우러져서 입안이 즐겁네요. 몽블랑은 정말 말해 뭐해. 의 맛인데, 이제 안쪽에 들어있는 밤이 정말 알차네요. 타르트지가 단단하지만 그렇기에 부드러운 크림과 어우러진다 생각합니다.', 41, 1, 'GOOD', SYSTIMESTAMP);
