INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '디저트 맛부터 플레이팅, 설명까즤 어디하나 빠짐없이 완전한 카페 였어요! 설명받고 먹는 내내 대우 받는 기분이었달까... 블루리본으로 유명하던데 역시 유명한데는 이유가 있는거겠죠! 지금은 가을 시즌이랑 몽블랑이랑 가을 과일이 들어간 디졑트까지 딱 계절감에 맞는 메뉴들이었습니다! 근처에 살았다면 자주 갔을거 같아요! 시즌별로 가서 다른 메뉴들도 맛보고 싶습니다!', 41, 2, 'GOOD', SYSTIMESTAMP);
