INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '항상 매달 시즌마다 바뀌는 페어링 좋은 디저트와 커피 조화가 너무 좋고, 설명도 너무 잘해주셔서 맛을 보는 재미가 배가 되는거 같아요', 40, 4, 'GOOD', SYSTIMESTAMP);
