INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '매년 오는 이미커피의 사일런트 파티인데 분위기도 좋고 플레이팅도 세심하게 신경써주셧어요ㅎㅎ 내년에도 기회가되면 또 참가하고싶습니다^^', 1, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '홍대입구역에서 가까우면서 연남동에서도 데이트하다가 찾아오기 좋은 이미커피! 음커피라고 읽을 수도 있는 곳이라고 생각해요 커피도 맛있지만 여기만의 디저트가 끝내주는데 디저트를 고르면 페어링해주는 핸드드립 커피라서 더욱 특별하고 맛있는 것 같아요~ 분위기도 차분하고 조용해서 앉아있는 것만으로도 힐링되는 듯한 기분이 드는 이미커피입니다', 24, 4, 'GOOD', SYSTIMESTAMP);
