INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '기대만큼 커피도 케이크도 맛있는 곳이다. 주마다 달마다 컨셉이 바뀐다고 하는데 멀어서 자주 못 가는 게 너무 아쉽다. 가까운데 살았더하면 달에 두번정도는 꼭 갔을 거 같다.', 24, 1, 'GOOD', SYSTIMESTAMP);
