INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '믿고 먹는 이미커피 가을 시즌 메뉴 먹으러 방문했어요! 몽블랑과 타르트 타탕을 주문했는데 타르트 타탕은 많이 달달한 편이었고 애플파이와 비슷한 맛이었어요. 제 기억엔 몽블랑이 더 맛있었던거 같아요 커피와 잘 어울렸습니다', 4, 0, 'GOOD', SYSTIMESTAMP);
