INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '페어링 디저트 이미커피 드디어 와봤어용~~ 케이크가 맛있습니다. 이날 먹은 음료는 다소 산미가 강해서 페어링과 상관없이 선호 원두 고르셔도 좋을 것 같아요.', 50, 9, 'GOOD', SYSTIMESTAMP);
