INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '저희는 테이크아웃 해서 주문하고 조금 기다려소 받았지만 가시면 대기줄이 있도라구요 블루리본 받은 매장 꼭 가보고 싶어서 여기를 처음으로 와보게 됐는데 드립으로만 운영을 하고 계시고 음료나 원두 설명의 대한 종이를 사진처럼 꽂아서 주시는데 그게 좋았어요 분위기도 좋고 먹는 내내 내 입에 원두향수를 뿌린 것 마냥 나는 향이 정말 고급지고 진하게 느껴서 그 향을 계속 느끼고 싶어서 마시게 되는 것 같아요 다른 커피를 먹고 그냥 맛있네가 아니라 느껴지는 풍미나 향의 깊이가 정말 깊고 음료마다 스타일이 명확하게 느껴졌어요 정말 맛있게 먹었고 2014년부터 매년 블루리본 받으실만 하구나 싶도라구요 매장이 커지면 커지는 대로 잘 되실 것 같아 응원합니다:) 덕분에 향기로운 시간이 됐어요❤️', 25, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '아담한 카페에 어마무시한 분위기 가격은 있는편이예요 하지만 한 잔 같은 두 잔 주시니까😌 케이크 계절과일 쓰시고 원두랑 디저트 설명도 해줘서 더더더 좋네요 🎀🎀🎀🎀🎀🎀🎀🎀🎀💙', 23, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '평소 디저트를 즐기는 편이 아닌데 하나하나 설명해주시니 또 다르게 느껴지더라구요! 새로운 경험 다른 구성도 궁금해서 또 가볼래요!', 144, 31, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '벼르고 벼르다 와봤는데 ''커피와 디저트 페어링이 좋다/맛있다''를 넘어 너무 만족스러워서 리뷰 남겨요. (원래 리뷰 1년에 하나 남길까 말까 함) 추천받은 커피의 묵직하지만 과하지 않은 산미와 살짝 스쳐가는 단맛이 제 취향이었고, 같이 주문한 배 시나몬 베린느는 다섯가지 재료가 과한거 아닌가 싶었는데 설명해주신대로 오묘하게 잘 어울려요. 내용물 따로 따로 먹으면 그냥 달달한 느낌인데 다 한꺼번에 먹으면 단맛이 죽으면서 식감도 살고 입안에서 조화를 이룹니다. 그리고 전 생면부지의 사람과 사적인 대화 극히 꺼려하는 I인데, 가끔씩 직원분이 슥 던지는 질문과 이어지는 스몰토크가 전혀 부담스럽지 않을만큼 대화의 주제와 타이밍이 너무 절묘했어요. 친절하고 배려넘치는 서비스 감사합니다. 읽던 책 재방문해서 다 읽을게요!', 24, 9, 'GOOD', SYSTIMESTAMP);
