INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '디저트를 먼저 선택하고 그 디저트에 맞게 페어링 해준 커피를 먹는다는게 색다른 경험이였습니다ㅎㅎ 디저트가 맛있었고 페어링해준 커피랑 같이 먹으니 맛의 매력이 더 증가되는 느낌이였어요! 다음에 또 방문할께요~', 42, 2, 'GOOD', SYSTIMESTAMP);
