INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '잠실 크리스마스 마켓 에서 뱅쇼 와, 에그 노그를 팔아서 방문하게 되었습니다. 에그 노그 경우는 알콜을 살짝 탄 맛으로 알콜의 높지는 맛을 느끼지 못해 좀 아쉬웠지만 잘 접할 수 없는 음식을 먹었다는데 의의를 두고 있습니다.. 백쇼는 라즈베리의 라이트한 맛이 뱅쇼의 묵직한 향신료와 별로 어울리지는 않았어요 그렇지만 차별화 된 맛을 추구 했다는 점에서 시식하고 구매 할 가치는 있었습니다.', 26, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '여름에 복숭아 먹었던 좋은 기억이 있어서 몽블랑 2종을 포장했는데, 디저트 설명지나 비주얼에 미치지 못하는 맛이라 조금 아쉬웠음', 18, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '평일 4시 넘어서 도착했는데, 웨이팅 한 팀 있었어요! 전 테이크아웃이어서 안에 들어가서 바로 주문하고 10분이내로 받았습니다 :) 커피가 진짜 산미도, 고소함도!! 너무 조화로웠고 디저트는 몽블랑이 맛있다고해서 두개 사왔는데 가격대비 ,, 조금 아쉬웠습니당🥲', 113, 19, 'BAD', SYSTIMESTAMP);
