INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '딱 밤만 들어간 기본 몽블랑인데 겉에 크림이 진짜 찐 밤맛이라 너무 맛있네요ㅎㅎ 크림만 왕창 퍼먹고 싶은 맛… 안에도 큰 통밤이 들어있고 밤 맛이 진하게 나서 맛있게 잘 먹었어요😆', 9, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '행복 시즌에 맞춰서 방문했네요. 예년에 비해 더 달고 과육이 가득한 복숭아 맛을 느낄 수 있어 좋았습니다. 페어링 한 커피가 바뀌었는데, 블랙티 향이 은은히 퍼지고. 추가한 디카페인 커피도 과일 향이 은은해서. 너무 잘 어우러졌습니다.', 36, 10, 'GOOD', SYSTIMESTAMP);
