INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '이미커피에서 마련해주신 특별한 이벤트 덕분에 더 특별한 크리스마스를 보낼 수 있었습니다. 정성스러운 음식과 디저트, 음료까지 맛있게 잘 먹었습니다. 감사합니다.', 34, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '디저트와 커피 페어링이 궁금해서 와봤는데 웨이팅 할 정돈 아닌것 같습니다 9팀 정도 앞에 있었는데 2시간정도 대기했습니다 오후 늦게 가서 그런지 디저트는 말라있고… 특별한 맛은 아니었어요 커피도 무난했습니다. 밤 몽블랑과 커피 페어링은 굉장히 클래식한 조합이었고, 블루베리&사파이어 들어간 파이와 커피 조합은 좀 색다른 조합이었어요 무엇보다 이곳 회전율이 너무 안좋아서 웨이팅할 정도는 아니다..싶었어요 안에 공석이 나더라도 한참기다려야 해요', 30, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '공휴일이라 그런가 오픈하고 5분 지났을 때 갔는데 가게는 꽉 찼고 웨이팅도 꽤 있었어요! 포장하는데도 대기 등록해두고 좀 기다렸네요ㅎㅎ 행복 먹었는데 이런 통복숭아로 만든 타르트중에 제일 맛있게 먹었어요!! 안에 크림도 느끼하지 않고 좋았고 완전 말랑말랑한 복숭아라 부드럽게 슥슥 잘려요! 밑에 빵 부분에도 복숭아 조각이 들어있어서 넘 맛있어유ㅠㅠ 백도크림을 따로 작은 통에 담아주시는데 이거 없어도 크림이 딱 적당해서 좋았습니당ㅎㅎ (그래두 크림도 맛있어서 다 먹음^^)', 25, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '여름이 오면 항상 생각나는 이미커피의 행복 항상 핫해지는 시즌이기 때문에 첫날에 바로 방문했습니다. 오픈 30분 전에 도착했고 대기번호 4번이었어요. 1인1행복을 주문 할 수 있기 때문에 하나씩 드시는 분들이 많았고요 커피와 메뉴를 서브 받을 때까지 기다리는 시간이 좀 길었지만 맛있는 메뉴를 먹을 수 있다는 생각에 기다리는 시간도 행복했답니다. 메뉴는 행복 하나와 페어링 바닐라 말차를 주문했고요 행복에는 피치블랙티, 말차메뉴에는 주블랜드가 함께 나왔습니다. 페어링 구성은 작년과 비슷한 느낌이고요 역시나 행복은 언제 먹어도 행복해지는 맛입니다. 바닐라말차는 말차향에 은은한 유자향이 더해져 상큼한 맛도 있었고요 바닥에 바삭한 크런키함도 좋았습니다.', 50, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '제가 좋아하는 카페인데 친구에게 소개시켜 주려고 데려갔어요! 바닐라통카빈과 무화과베린느를 주문했고 하나는 페어링된 커피 그대로 주문하고 하나는 산미있는 원두로 바꿨습니다. 디저트는 원래 바닐라를 좋아해서 넘 맛있게 먹었고요 무화과베린느는 좀 특이했어요. 바질페스토도 들어있고 치즈도 들어있어서 일반적인 달달한 디저트와는 다른 짭쪼름한 맛이나서 처음엔 좀 적응이 안되었지만? 먹다보니 커피랑 조합이 좋아서 계속 먹게 되더라고요! 다음 메뉴는 또 뭐가 나올지 매번 기대하게 되는 곳입니다.', 46, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '평일 오후 2시에 방문해서 30분 정도 웨이팅했습니다! 들어가니 생각했던 것보다 넓고 여유있는 분위기라 괜찮았어요. 디저트는 조금 가격대가 있긴 했지만 정갈한 매장 분위기와 맛있는 커피를 즐길수 있는 것 덕분에 상쇄되었어요 ㅋㅋ 다음에는 페어링 없이 커피만 마시다 와보려구요! 피치 요거트는 산미 있는 커피였는데 필터커피라 연해서 더 제 스타일이었습니다', 51, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '1시간 30분 가량 대기했고 대기 시간이 길어질수록 쌀쌀해졌습니다. 내부에는 웨이팅을 위한 대기석이 없음에도 퇴점한 고객들의 자리를 정리하고 다음 손님을 안내하기까지의 시간도 꽤나 소요되더군요. 날마다 직원분들의 스테이션이 다른듯한데 지난 방문때와 달리 굉장히 불친절하셨습니다. 안내받은 자리가 출입문에 가까워 다른 좌석을 부탁드렸더니 4인석이어서...라며 말끝을 흐렸고 이전 방문에 자리를 안내해주시는 분께서는 손님이 많아지면 그때는 테이블을 분리해드려도 되냐고 정중히 여쭤보셨어서 아쉬웠습니다. 그래서 바테이블 좌석에 앉아도 되냐고 했더니 좌석을 정리하면 이동하라고 하더군요. 여기서부터가 가장 문제라고 생각되네요. 오래된 버디고객인지 강아지를 동반한 고객만을 신경쓰느라 좌석을 정리하고 앉으라는 말도없었습니다.', 82, 13, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '디저트에 맞는 커피도 추천해주시고 메뉴 설명도 직접 해주셔서 알고 먹으니까 훨씬 더 맛있었어요 웨이팅 있는게 납득될 정도로 정말 만족스러웠어요 또 방문할게요', 35, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '다즐링 플럼을 맛봤네요. 정말 산뜻하게 어우러지는 맛이었습니다. 설명대로 다즐링 크림과 자두는 따로 먹는 것이 더 어울리는듯 하네요. 산뜻하고 가벼운 디저트에 향이 은은한 커피가 조화로워요. 다만 쿠키가 너무 단단해서. 디저트 칼로는 잘리지 않고 포크로도 부서지는 것이 아쉬웠습니다. 그렇지만 커피와 페어링은 정말 최고였어요', 2, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '이미커피를 처음 알게해준 메뉴를 드디어 먹어봤습니다🍑 맛있고 손이 많이 갈게 보이는 메뉴였습니다 개인적으론 안에 들어간 천도복숭아 와인절임이 정말 맛있었어요 다만 예상가능했던 맛이어서, 저에게 이미커피는 재밌고 신기하고 맛있는 메뉴를 기대하고 가는곳이라 다음에 가면 다른메뉴를 도전할것 같아요 웨이팅은 평일 오픈 30분전에 가니 3번째 순서였습니다', 21, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '혼자 가더라도 언제나 친절하고 즐겁게 커피와 디저트를 즐길 수 있습니다. 둘세 타르트와 버터팝콘(본래는 주 블렌드 페어링)을 즐겼는데, 정말 설명대로 옥수수 강냉이의 향이 나서 신기하네요. 둘세 타르트는 베일리스 가나슈가 향긋하게 퍼지면서 무스와 너무 잘 어울립니다.', 41, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '격주~달마다 바뀌는 디저트도 바리스타분들이 정성껏 내려주시는 커피도 넘 맛있어서 친구나 가족과 갈때마다 거기 카페 좋더라~ 이런 얘깃거리가  돼요 하나하나 설명해주시는 것도 듣기 좋고 시설도 편안함', 14, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '친절한 직원분들에게 메뉴 추천받아서 먹은 몽블랑&드립커피 세트가 너무 만족스러웠어요!! 근처 가실일있으면 웨이팅 하시더라도 가보시길 바래요 :)', 4, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '디저트를 먼저 선택하고 어울리는 커피를 내려주시는데 맛 좋았어요! 웨이팅은 10분 정도 했는데 이건 복불복! 매장이 생각보다 시끄러워서 아쉽 그래도 커피가 맛있네요!', 5, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '오랜만에 홍대근처로 퇴근길이 되면서 포장해서 집에 들고와서 먹었습니다. 많이 달지 않고 맛있어요? 다만 먹었는데 안 먹은느낌? 분명 크기도 큰데 몇입 못 먹듯 사르르 녹아서 아쉬웠어요ㅋㅋㅋ 다음에는 매장 가서 잘 어울리는 커피와 같이 먹고 싶네요:)', 46, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '언제나 가슴설레게 하는 디저트의 이미입니다. 항상 매력젹인 디저트가 나오는데 가끔 놓치는 경우가 있어 아쉽네요 이번 딸기 시즌의 메뉴들은 못 먹고 새로 나온 초코 다쿠아즈디저트가 눈길을 끌어 방문했습니다. 오렌지의 향과 초콜렛의 맛이 너무 좋네요 가격은 살짝 있지만 그만큼 고급스럽고 맛있습니다. 운좋게 대기가 1팀뿐이라 금방 들어갓네요 항상 미리 대기를 걸어놓고 주변을 돌아다니시길 바랍니다. 다른 메뉴도 먹어보고싶은데 욕심을 조금 내려놓으려 합니다.', 112, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '웨이팅은 매장앞 태블릿으로 예약접수를 했어요. 홍대근처라서 기다리는동안 다른 볼일을 봤었고 제차례에 들어갔을때 첫인상은  매장내부는 청결하고 직원분들이 정말 친절하셨어요. 메뉴도 설명 잘해주시고 좌석도 불편하지 않아서 좋았어요. 테이블 밑에 짐가방을 둘수있는 큰 바구니가 있어서 짐이 많아도 괜찮았던것같아요. 가격이 싸지는 않지만 그만큼 방문했을때 기분은 좋아질수 있는 서비스를 받을 수 있어서 재방문의사 있습니다.', 20, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '다즐링 플럼 로즈 🍑 바나나 코코 브레드 🍌 주문했어요! 디저트도 페어링커피도 모두 마음에 들었습니다 ... 직원분들도 친절하셔서 웨이팅한게 하나도 후회되지 않았어요 아주 좋았습니닷 !!', 32, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '주간 페어링 산딸기 리치로즈를 함께했습니다. 설명대로 산뜻한 산딸기의 맛과 함께 은은한 장미향, 그리고 리치의 맛과 향이 다양하고 함께 나는 것이… 설명해주시는 그대로입니다. 페어링한 커피는 향이 은은하게 어우러지면서, 디저트의 맛을 정리해주네요', 73, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '재방문 의사는 없습니다. 주문한 커피와 디저트, 그리고 페어링도 나쁘지 않았지만 이 곳말고도 이 정도 수준의 커피와 디저트는 더 좋은 환경에서 즐길 수 있으니까요. 운영시스템은 음….', 73, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '복숭아를 좋아하는분이라면 한번쯤 가볼만한곳 좋은 복숭아로 만들어서 너무 달지도 밍밍하지도 않은 잘익은 복숭아맛이 난다 어디서나 느껴볼수 있는맛 다만 아래쿠키부분과 닿는곳은 눅눅해서 맛이 조금 떨어지니 복숭아만 딱 즐기는게 좋은것같다 특별한건 느끼진못했다 안에 들어있는 치즈크림도 맛이 약해서 잘 느껴지지도 않고 그로인해 딱 복숭아의 맛만 느낄수 있었다 디저트류 3가지와 음료 4가지가 있고 1인 기준으로 1디저트에 1음료까지 무조건 시켜야한다', 108, 26, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '오랜만에 홍대나들이를 온 김에 블루리본을 엄청 받은 카페를 발견하고 왔는데,, 엄청난 대기시간! 1시간 10분만에 들어갔음. 특이한 컨셉답게 신선함 물씬! 페어링 된 커피는 엄청 특이했음. 커피가 깔끔하고 향이 복합적으로 맴돌아서 미식가들에게는 넘 좋겠다는 생각. 사실 커피는 맛이 있다고는 말 못하는데(맛이 없다기보단 담에 꼭 또 와서 먹어야겠다는 생각은 안듬), 디저트는  고급스러운 맛이었음. 그리고 설명대로 페어링한 이유가 있었음. 맛이 강화되거나 조화를 이루거나 하는 부분이 있어서 신기했음. 커피보단 디저트가 더 와닿았고, 디저트가 월별로, 주별로 바뀌는 것이 좋았음. 올때마다 다른 맛을 기대할 수 있다는 게 좋았음.', 53, 17, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '홍대 꼭 가봐야하는 이미카페 드립커피와 페어링 디저트가 매주 매달 바뀌어요~ 웨이팅 있긴한데 기다릴 가치 있는카페 살짝가격대는 있지만 또 그럴가치가 있어요 저는 4월에 갔다왔고요 5월 되었으니 디저트먹으러 다시 가볼까해요', 43, 3, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '비오는 날이기에, 초콜릿 다쿠아즈로 추천 받았습니다. 진한 초콜릿 크림과, 바삭한 다쿠아즈. 그 사이에 숨은 오렌지 정과가 맛을 깔끔하게 마무리 해줍니다. 진한 향의 주 블렌딩과 함께하니 확실히 디저트의 단맛과 향이 더 올라오는 느낌이 들어 좋네요.', 10, 2, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '웨이팅이 길어서 다른 곳 구경하다가 들어갈 수 있었어요. 연락 오면 10분 내로만 가면 돼서 웨이팅은 할 만 했어요. 케이크와 어울리는 커피와 페어링을 해서 나와서 특별했어요. 설명도 자세히 해주셔서 좋았습니다.', 10, 8, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '새로운걸 접하고싶을때 방문해요 매달 메뉴가 바뀌고 2주마다 바뀌는 메뉴도 있어서 꾸준히 가고있어요 이번에 먹어본 메뉴는 초코오렌지 다쿠아즌데 개인적으로 초코는 강하지 않게 잔잔하게 깔리고 오렌지필의 존재감이 크게 느껴져 과일이 들어간 초콜렛을 좋아하는 입장에선 매우 만족스러웠습니다', 116, 21, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '2024년 3월 주간 페어링 오치퐁과 월간 페어링 바닐라 통카빈 타르트 함께 하고 왔습니다. 오렌지 안에 가득찬 크림치즈는 상큼해서. 단순히 무게감 있는 맛이 아니라 매력적입니다. 페어링된 커피 또한 산뜻해서. 디저트는 크림치즈보다는 무게감 있는 무스 케이크 같기도 하네요. 그리도 바닐라 통카빈 타르트는 부드럽고 향긋한 향이 가득 채우는 맛입니다.', 78, 15, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '지나갈때마다 대기하는 분들이 많아 궁금했었는데 오늘 비로소 방문..식사시간이라 대기2번 15분 정도 기다리다가 입장..디저트 먼저 쵸이스 하니 직원분의 추천 페어링 커피 주문..디저트와 커피에 대한 직원분의 친절한 설명이 좋았고 맛의 디테일을 느낄수 있어 좋았습니다..가격대가 있는 만큼 커피나 디저트 맛이 다르네요..추천합니다.^^', 54, 17, NULL, SYSTIMESTAMP);
