INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '친구랑 처음가보고 주간메뉴인 판나코타가 계속 생각나 판매 마지막날 가서 먹고왔어요 원래 향이 과한 커피는 선호하지 않는데 이곳은 디저트와 페어링돼서 나와 그 이유가 납득이 가고 디저트와 함께할때 새롭게 느껴지는 맛이 있어 좋았습니다 그리고 깔끔한 인테리어가 너무 좋아요 직원분들이 메뉴 설명해주는것도 메뉴 설명서를 주는것도 디저트랑 커피의 향과맛을 더 생각하며 먹을 수 있게 해줘 좋습니다 앞으로도 꾸준히 갈것 같아요 이때 이후로도 다른친구와 또 방문했는데 영수증이 없어 그냥 여기다 사진추가해요 이번에도 주간메뉴인 오치퐁이 왜 가장 제 취향인지... 끝나기전에 한번더 가야할것 같아요', 39, 10, NULL, SYSTIMESTAMP);
