INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '디저트가 맛있는건 당연하고 페어링되는 커피가 정말 잘어울려요 평소였으면 안 마셨을 커피들도 디저트와 먹으니까 잘 들어가네요☺️ 직원분들이 디저트와 커피에 대한 설명을 와서 해주십니다 화장실은 가게 외부 건물 화장실인데 많이 깨끗하지는 않아서 아쉬워요🥲', 31, 1, NULL, SYSTIMESTAMP);
