INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '여기는 디저트만은 확실히 맛있어요. 대기 많아서 입장 못하다가 오늘은 대기 없어서 겸사겸사 다른 카페 갔다가 들렸어요. 당충전은 좋습니다', 14, 2, NULL, SYSTIMESTAMP);
