INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '2월 페어링, 딸기 몽블랑을 맛보러 갔습니다. 함께 페어링된 커피가 묵직해서. 딸기향이 짙게 퍼지는 몽블랑과 정말 잘 어우러집니다. 반으로 직접 잘라주셔서, 굉장히 깔끔하게 잘 잘렸고, 단면도 굉장히 이뻤어요. 비주얼만큼 맛있었습니다', 34, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '드디어 와 본 이미 카페!! 오픈런 하고 웨이팅 없이 바로 들어왔습니당😊 입장하자마자 테이블이 꽉 차더라구용~! 디저트에 따라 커피 종류를 다르게 패어링 해주신게 색다르고, 실제로도 디저트랑 커피를 맛있게 먹고 갔어요👍', 26, 0, 'GOOD', SYSTIMESTAMP);
