INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '디저트와 커피 페어링이 훌륭합니다...👏 평소라면 안 마실 커피도 디저트와 함께하니 설명해주신대로 서로의 장단점을 살려주고 잡아주네요 디저트가 수시로 바뀐다하니 잘 살펴보고 꾸준히 방문할 것 같아요☺️', 2, 6, 'GOOD', SYSTIMESTAMP);
