INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '커피와 디저트를 페어링해주는 카페☕️ ​ 좌석이 꽤 많았고 테이블마다 간격이 넓어서 조용한 분위기였어요. ​ 격주 혹은 매달 디저트 라인업이 달라지며, 달라진 디저트에 맞게 커피 원두도 바뀝니다. ​ 디저트와 커피를 가져다주시며 페어링과 커피에 대한 설명을 해주시는데 설명을 차분히 잘해주셔서 전문성이 돋보여요 밀푀유 카라멜은 누네띄네와 거의 비슷한 맛과 식감이었고, 가운데에 있는 크림이 특히 부드러웠어요.​ ​합(合) 블랜드는 고소한 향과 맛의 커피였습니다. 달달한 밀푀유 카라멜의 맛을 해치지도 않으면서 무난하게 잘 어울렸어요. 에티오피아는 역시 산미가 강한 편! 확실히 단독으로 마셨을 때가 더 깊은 풍미를 즐길 수 있습니다.', 64, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '주간 페어링 바질 아이스크림과 커피 파운드. 바질로 만드는 디저트는 언제나 색다른 거 같습니다. 묵직하면서도, 아이스크림답게 부드럽게 풀어지는 것이… 정말 맛있고. 페어링된 딸기맛 초콜릿이 아니라 디카페인과도 굉장히 잘 어우러집니다. 에스프레소 파운드는 합 블렌드와 함께 하는데, 딱 적당한 단맛에 커피향이 은은히 퍼져 맛있었습니다.', 39, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '치즈와 무화과. 정말 잘 어울립니다. 커피와도 향긋하게 맞아들어서, 물리지 않고 먹을 수 있고. 식전 에피타이저를 먹는 느낌도 들었습니다. 파프리카 가루가 뿌려져 재밌어요', 113, 26, 'GOOD', SYSTIMESTAMP);
