INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '커피로 대접받는 느낌이 든 카페는 처음인 거 같아요 배부른 상태에서 와서 디저트는 안 먹었지만 커피맛도 새롭고 맛있었어요 최근 대회에서 사용하셨던 원두로 내린 커피도 시음하게 해주셨는데 처음 느껴보는 향이랑 맛이라 기억에 오래남네요!! 다음엔 디저트도 같이 먹으러 오겠습니당', 88, 14, 'GOOD', SYSTIMESTAMP);
