INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '커피가 유명해서 찾아간 이미커피☕️ 평일에도 사람이 많고 웨이팅 있었어요. 디저트와 페어링 되는 커피는 할인되고 핸드드립 커피를 취향대로 먹을수 있어서 좋아요!!', 25, 5, 'GOOD', SYSTIMESTAMP);
