INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '언제나 대접받는 느낌이 드는 이미커피🕊️ 이번 디저트 딸기피스타치오 타르트는 정말 꼭 드셔야 합니다..🩷 한시간 넘게 기다렸지만 너무 감동적인 맛이었어요! 매장 얼른 넓혀주세요🥹', 22, 7, 'GOOD', SYSTIMESTAMP);
