INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '최근에 먹었던것 중에 가장 맛있는 디저트였어요 치즈맛도 강하고 무화과절임도 달콤해서 전반적으로 지금까지 이미커피에서 먹었던 디저트들에 비해 맛이 진한편이었어요', 79, 18, 'GOOD', SYSTIMESTAMP);
