INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '12월 페어링. 스파이시 오페라와 에그노그. 정말 맛있었습니다. 개인적으로 시나몬 계열 특유의 스파이시한 맛과 향을 못먹는 편인데, 이미커피의 디저트에서는 그것을 무난히 넘어갈 수 있어 좋습니다. 함께 하는 에그노그는 부드럽고 따뜻하게 마지막까지 넘어가고. 오페라는 부드러우면서 달아서 맛있습니다. 설명해주신대로 향과 맛이 느껴지는 것이 장점입니다.', 24, 7, 'GOOD', SYSTIMESTAMP);
