INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '🍰 맛스러운 디저트 3가지 중 고르기 힘들었지만 초코 바나나 쇼트 케이크 달지도 않으면서의 초코와 바나나 합 역시 맛있었어요. ☕️이에 맞는 블랜드 커피 추천으로 평소 산미있는 커피 성호했던 저에게 고소한 커피 맛있음을 제대로 느낄 수 있었어요. 🚶🏻‍♂️때에 따라 다르지만, 웨이팅 할 때 4팀있어서 금방 들어갈 줄 알았으나 거의 40여분 기다린 후 들어갔어요😅', 6, 1, NULL, SYSTIMESTAMP);
