INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '디저트와 페어링되는 커피를 추천해줘서 먹는게 좋았다 맛이  더 강해지는게 느껴져서 재밌었다 다 먹고 다시 처음 먹었던 다른커피를 먹으니 맛이 다른게 확 느껴졌다', 50, 1, 'GOOD', SYSTIMESTAMP);
