INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '여전한 인기쟁이 이미! 블루베리자스민에 포인트는 둘다였다 어느 것 하나도 놓지지 않을거야 라는 듯 각각의 색도 또 그 조화도 와 역시 이미!!!', 26, 6, 'GOOD', SYSTIMESTAMP);
