INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '이미커피의 오치퐁! 예전부터 좋아했던 메뉴인데 오랜만에 보니 더 반갑더라구요. 딸기와 피스타치오 조합의 프레지에도 맛있었어요. 페어링한 커피와 조합이 👍', 31, 10, 'GOOD', SYSTIMESTAMP);
