INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '지난 번에 방문했을 때 웨이팅 줄이 너무 길어서 다음 기회를 노렸는데 12시 오픈런을 땡 하자마자 왔어요 12:10 분부터는 웨이팅이 생기더라구요 이미커피 웨이팅 없이 즐기고 싶으시다면 오픈런!! 하세요', 22, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '새로운 디저트가 나왔는데 딱 제스타일 같아 두근대며 방문 역시나 맛있네요 사과를 절여서 크림과 같이 나오는데 너무나 맛있습니다. 같이 페어링된 커피랑도 잘 어울리네요 보통 이미는 몽블랑이 항상 메인인데 주간이랑 월간 디저트도 항상 마음에 듭니다  특히 계절에 맞춘 주간 디저트는 은근 취향저격이 많더군요  여름엔 복숭아로 저격하더니 지금은 사과 좋습니다 다만 항상 혼자와서 바에 앉고 싶은데 쉽지가 않네요 혼자 오시면 바 자리 강추입니다 어차피 예약이 가능하니 미리 등록하고 연남동 구경하셔도 될듯합니다', 40, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
