INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '예전 이미커피 로스터스때부터 좋아했던 에스프레소 카라멜 파운드케이크 페어링이 나와서 다녀왔어요. 예전보다 비주얼이나 구성이 살짝 달라졌지만 여전히 맛있었어요 :)', 43, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '전에 구로 이미에 간 적이 있어서 생각이 나서 간 곳~ 오늘부터 나온 케이크를 먹었는데 밑이가 시나몬빵 같고 단편.빵 부분 좀 푸석푸석? 바는 햇빛 들어와서 분위기는 좋은데 안쪽은 많이 어둡네요. 평일 1시쯤 갔는데 자리는 바만 있었고 1시반 지나니 웨이팅 생겼어요. 사조용한 분위기일까? 했는데 사람이 많아서 시끌벅적하네요.직원분들 친절하셨어요.', 40, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '이미커피의 몽블랑과 합블랜드의 조화는 가을의 정석입니다. 너무 달지 않아서 담백한 밤 본연의 맛이 잘 느껴졌고 타르트가 특히 맛있었습니다 타르트만 따로사서 과자처럼 매일매일 먹고싶어요', 27, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '무화과가 굉장히 특이한 맛을 선사했습니다. 디저트보다는 애피타이저, 아뮤즈 같기도 한. 디저트 치고는 짭짤한 맛이 신기합니다. 치즈와 향긋하게 어우러지는 바질페스토. 페어링된 커피와 어우러졌습니다. 립파이 콜라보 디저트… 벌 모양 같고 귀여웠습니다~ 디저트답게 달고 부드러워, 무스케이크 같은 느낌이 들었습니다. 확실히 합 블렌딩이 어울리는 맛이었습니다.', 76, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '- 페어링 행복 ice, 페어링 바닐라 다쿠아즈 ice 2년 전부터 너무너무 가보고 싶었던 이미💖 특히나 여름에 먹을 수 있는'' 행복을 주는 복숭아''를 먹고 싶었는데 부산인이라 쉽사리 가지 못했는데 드디어 영접했습니다..! 커피와 정성이 들어간 디저트와 친절한 직원분들까지 다 너무 만족했어요✨ 거의 2시간 기다렸는데 후회 없는 선택이었습니다🫶🏻 서울 살았으면 매번 디저트 라인업이 바뀔 때마다 가고싶네요🥹 여름때마다 생각나는 복숭아 디저트라 또 먹고싶네요🤤', 68, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '행복 시즌이라 하여 방문 했습니다…! 복숭아 안에 채워진 마스카포네 치즈와 파운드 케이크, 타르트지가 어우러져 좋습니다. 페어링 한 커피는 확실히 커피보다는 산뜻하고 가벼워서 디저트와 잘 어우러져요. 향긋함이 배가 되어 오늘도 맛있게 즐겼습니다.', 69, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '워낙 유명한 곳이라서 땡볕에서 40분 정도 기다렸다가 들어갔는데 메뉴는 그달의 디저트랑 디저트에 맞춰서 먹는 커피뿐이에요 가격은 비싸지만 디저트는 정말 맛있어요 희한하게 커피도 잘 어울리더라고요  매달 바뀌는 디저트 먹으러 가고싶지만 그건 힘들 것 같고 가끔 가보고싶어요', 12, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '서비스 최악. 대기 0팀 상태에서 30분동안 3팀이 나갔는데 부르지를 않아 직원에게 항의했더니 1분만에 들어갔어요. 겨울에 밖에서 손님들이 추위에 떨고 있는데 테이블 청소를 안하고 안 들여보낸 것임. 밑에 댓글중에 어떤 분이 20분동안 청소를 하지않아 추운 바깥에서 오랫동안 대기했다는 컴플레인 글보고 긴가민가 했는데 납득이 갔습니다.', 4, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '전부터 방문해보고 싶었던 카페 였어요. 원하던 페어링 디저트가 없어서 아쉬웠지만 이번에 먹었던 파운드와 커피가 너무 잘어울리고 너무 맛있었어요!', 22, 6, 'GOOD', SYSTIMESTAMP);
