INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '회사 쉬는시간에 혼자 갔는데... 디저트 맛 미쳤습니다... 그냥 달기만 한 디저트 아닙니다... 저 이거 먹으러 매주 갈 것 같아요 사장님...', 35, 4, 'GOOD', SYSTIMESTAMP);
