INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '올해 마신 필터 중 3손가락 안에 들 정도로 맛있었습니다 페어링 되는 디저트와 완전 찰떡맞춤 가격은 좀 있는 편이지만 매장의 운영방식을 생각하면 납득이 가더군요', 74, 12, 'GOOD', SYSTIMESTAMP);
