INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '디저트와 커피를 페어링해서 파는 곳 행복시즌은 놓치지말고 가줘야죠! 주말 오픈런은 눈치싸움이 치열할거 같아 평일 쉬는 날 다녀왔습니다. 벌써 8월이라 백도는 이미 끝났고 황도 시즌이었어요! 2년전에는 백도를 먹었던거 같은데 오랜만에 먹은 ''행복''은 기대 이상이었습니다. 예전에도 맛있었지만 이번에는 아래 타르트며 같이 제공되는 잼과 크림까지 맛의 조화가 완벽했어요. 거기다 피치블렌드 커피까지 한 모금 마셔주면 입안 가득 행복이 퍼지는 느낌입니다. 또 다른 디저트는 바닐라빈 무스와 말차무스, 헤이즐넛크림까지 3박자 조합에 말차크루스티앙 위에 있는 유자가나슈가 킥이었네요! 함께 페어링된 커피는 다소 묵직하고 쌉싸름해서 디저트의 단맛을 중화해주는 느낌이었답니다. 가격대는 있지만 무조건 추천👍🏼', 128, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
