INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '여기 디저트는 항상 크림류가 엄청 고급져요. 입에서 뭉쳐짐이 하나도 느껴지지 않고, 엄청 부드럽고 풍미깊어서 사르르녹습니다. 커피는 따뜻한걸로 시키면 엄청 예쁜 잔에 담아줍니다. 꼭 따뜻한걸로 시키는걸 추천드립니다', 42, 10, 'GOOD', SYSTIMESTAMP);
