INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '커피도 디저트도 고급스럽습니다...디저트가 너무 맛있어서 포장도 해봤는데, 역시 매장의 그 분위기 속에서 커피랑 같이 먹는게 제일 맛있어요', 23, 1, 'GOOD', SYSTIMESTAMP);
