INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '커피 디저트 페어링으로 새로운 경험들이 모여서 좋은 생각들을 할수있게 해줘요 그리고 궁금한것들 질문드리면 저어어엉말 친절하게 답변해주셔서 너무 편안하고 생각할수있는 포인트들이 많아서 좋아요! 일단 맛잇습니다👍', 24, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '30분웨이팅하고 들어갔어요. 테이블자체가 적어요 일단 커피맛, 케이크맛 다 괜찮은편이긴하나 개인적으론 웨이팅한 시간이 좀 아까웠어요. 요즘 커피디저트 맛있게하는곳 많아서 큰 특별함을 느끼진 못했지만 케이크에들어간 재료들을 설명해주셔서 좀더 그 본연의 맛을 느끼게되는점은 좋았어요. 설명 자체를 자세하게 해주셔서 이런거에 친절함이나 대접받는 느낌을 좋아하신다면 만족해하실수도 있겠어요. 디저트를 고르고 그에 맞는 커피를 페어링해준다는 컨셉이라 인원수대로 디저트를 시켜야되다보니 원치않아도 사람수만큼 케이크를 다 먹어야해요. 페어링이라고 해봤자 3가지케이크에 3가지 커피(+디카페인)밖에없어서 선택의폭 자체가 크지않아요.', 6, 8, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '웨이팅이 있던 이미. 디저트와 커피의 맛도 추천해준 페어링도 좋았습니다. 테이블 간격도 넓어서 충분히 맛을 즐기고 머무르다 갈 수 있는 곳입니다.', 29, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '이번주 디저트는 플럼베리! 새콤한 편일거라는 예상과 달리 산미높은 커피와 산뜻+달콤한 디저트의 페어링이었어요. 커피같은 경우엔 살짝 식었을 때 자두만을 더 강하게 느낄 수 있었습니다. 무화과 베린느는 바질페스토+무화과+잼+ 크림+치즈의 조합이 조화로웠어요!! 바질페스토와 무화과의 조합만으로도 와인을 떠오르게 하는데, 오늘은 그라다파다노 치즈까지 짠맛까지 곁들여져 더 좋았습니다:)', 49, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '데이트 하시는분들께는 비추합니다 목걸이 하시고 머리 묶고 계산대 보시는 여자직원분 정말 분친절 합니다 가격도 착한것도 아니고 이정도 이정도 맛에 이정도 커피를 만드는 집은 많습니다 굳이 불친절한 서비스를 감수하며 갈 필요 없다고 생각해요. 전에 무슨 기분 안 좋은 일이 있으셨는지 그냥 태도가 원래 그런거신지... 정색하고 짜증난듯 말하면 누가 좋아라 합니까 생각좀 하세요 가는말이 좋아야 오는 말이 좋은겁니다 인생 그렇게 살지 마세요 ㅡㅡ', 9, 1, 'BAD', SYSTIMESTAMP);
