INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '완벽한 디저트와 완벽한 커피였어요..! 사실 가격을 안 보고 그냥 결제해서 이 작은 디저트가 16,000원이나 하는지 몰랐는데요... 그래도 굉장히 맛있었으니 납득합니다 😊', 23, 2, 'GOOD', SYSTIMESTAMP);
