INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '플로랑탱과 시트러스 타르트 페어링된 커피는 고소한 맛과 산뜻한 과일. 정말 둘 다 너무 잘 어울리고, 맛이 어우러진다. 특히 플로랑탱의 고소함이 커피의 고소함과 어우러져, 함께 먹으면 맛이 배가 된다. 시트러스 타르트에 페어링된 커피는 가벼우며 산뜻하고, 시트러스의 달달함과 향긋함을 증폭시켜서 맛있었습니다.', 33, 5, 'GOOD', SYSTIMESTAMP);
