INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '디저트에 어울리는 페어링 커피. 설명대로 향이 너무 신기하고 정말 잘 어울렸습니다. 크림 브륄레와 페어링 한 커피는 말씀대로 청주의 향이 느껴지고, 같이한 디카페인에서는 가벼운 복숭아의 느낌이 나서 재밌었어요!', 52, 11, 'GOOD', SYSTIMESTAMP);
