INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '연남동 핫플이라 웨이팅 쪼꼼 있었어요🫶🏻 이쁘고 맛도 좋은데 복숭아가 어디서 왔는지 소스는 또 어떻게 만든건지 세세히 설명해주셔서 듣고 먹으니 두배로 더 맛있었어요 🥰🥰 정말 친절하고 예쁜 곳이에요 🍑', 14, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '이미커피 .. 디저트에 맞게 페어링 해주신 커피들 다 매력적이고 맛있었어요 ㅜㅜ 1시간 반만 이용할 수 있는 게 아쉬웠지만 또 방문할 것 같아요 다음달 이미 커피만의 메뉴를 기대하고 있겠습니다 💕', 47, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '가게도 디저트도 고급집니다... 그 기간에만 먹을 수 있는 디저트와 커피의 조화가 좋습니다. 주말엔 웨이팅이 있지만 기다린 보람이 충분히 있는 맛입니다. 이 가격에 이런 서비스를 받을 수 있는게 행운인것 같습니다', 35, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '이 디저트 하나만 보고 갔어요! 만사처넌..! 여기서 거의 3만원 썼네요 일단 커피는 맛있었어요 웨이팅 한시간 했구요 다들 친절하세요 재방문의사는 없을 것 같아요 ㅎㅎ', 23, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '디저트를 고르면 커피를 페어링 해주는 카페. 디저트가 주, 달마다 바뀌는 특징이 있습니다…! 방문했을 땐 메론 수박 판나코타가 주간 디저트. 페어링한 커피는 적당히 산뜻하고 끝맛이 향긋했습니다. 커피와 디저트에 대한 설명도 자세하게 해주시며, 사진을 찍을 경우에는 편하게 찍어도 된다고 덧붙여서 정말 편하게 찍을 수 있습니다.', 8, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '드디어 성공한 행복 :) 디저트에 맞춰 커피 페어링을 해주시는데 오늘 마셨던 피치 블렌드가 처음부터 끝맛까지 너-무 맛있었다.', 26, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '요즘 복숭아디저트 때문인지 평일에도 웨이팅이 많은편이에요 여유두고 방문하시는걸 추천합니다. 다른디저트도 항살 맛있고 직원분들이 모두 친절하세요', 86, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '고르는 디저트랑 커피랑 페어링 해준다는 게 특별하고 신기했어요 디저트도 매주 또는 매달 바뀐다고 하니 계속 찾아가보고 싶어요!', 45, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '평일 점심때갔는데 앞에 7팀있어서 1시간정도 대기한것같아요. 복숭아메뉴가 특이해서 기다리고 먹었는데 너무 기대했는지 그냥 복숭아였네요^^하하 커피는 맛있었습니다 양도많구요', 17, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '벌써 여러번 방문했던 곳이고 다녀올때마다 만족도 높은 카페에요. 하지만 늘 웨이팅은 평일에도 예외는 없는편. 그래도 주말보다는 덜기다리며 2시쯤 평일에 도착하면 2팀정도만 기다렸다가 들어갈 수 있어서 좋았어요. 이번에 주문한 디저트들은 먹고나서 먹기전 예상과 너무 달라서 즐겁게 놀랬어요. 화이트초콜렛은 특유의 짙은 향때문에 싫어해서 잘 먹지 않는데 이미 디저트는 대부분 한가지 맛으로만 강하게 오는 느낌이 아니라 다른 재료와 조화가 좋아서 모험삼아 발렌타인주문. 너무 고급스럽고 우아한 맛에 걱정이 날아갔어요. 커피랑도 정말 찰떡궁합. 위스키와 고급초콜렛느낌 블루베리 카시스는 해동이 덜되어 나와 약간 멈칫했지만 불쾌할정돈 아니고 발렌타인에 비하면 무난한 맛이었어요. 발렌타인 추천', 15, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '아아~원래 이리 맛있는건가? 늘 라떼만 마시는데 이곳은 라떼없는곳~ 혹시나해서 시켜봣는데 커피라기보단 우와~맛있다~이 느낌~앞으로 매주 마실듯~♡ 커피란 이런거징~', 16, 3, 'GOOD', SYSTIMESTAMP);
