INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '빠다코코넛 커피 정말 맛있네요. 풍미가 좋은 커피 오랜만이었어요ㅋ 디저트는 스파이시초코타르트보단 코코파인몽블랑이 더 맛있었습니다.', 21, 8, 'GOOD', SYSTIMESTAMP);
