INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '이미가 이미하는 카케. 제대로 커피하는 곳 이미. 설명이 필요없는 카페라고 생각함. 디저트를 고르면 커피를 추천해주는 매력적인 카페임. 커피를 먼저 골랐는데, 원래 그에 페어링 돼있는 디저트 같이 먹음. 겨울에는 딸기 못참지 다음에 홍대오면 또 올거얌 아니 홍대 살고싶다 이미때문에....', 30, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '추천받아서 방문했는데 그만큼 특별한 공간이었던것 같습니다. 커피와 디저트 페어링이라는 점도 좋았고, 원두 중 포도젤리는 향이 정말 포도향이 나서 너무 신기했어요. 커피 양도 다른 인스타 감성 까페만큼 조금 주시는게 아니라 넉넉히 주셔서 그점이 제일 좋았어요. 설명도 참 친절해 해주셔서 예쁜 공간 즐기며 너무 좋은 마음으로 머물다 갔습니다.', 6, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '디저트를 먼저 고르면 그에 어울리는 커피를 추천해주는 방식이라 너무 신기하네요~ 물론 디저트를 먹지 않아도 음료는 주문 가능해요. 디저트나 커피의 설명을 디테일하게 해주셔서 너무 좋습니다! 자스민 딸기 몽블랑을 먹었는데 너무 맛있어요~! 1월 한정이라고 하니, 어서 드셔보시길', 35, 4, 'GOOD', SYSTIMESTAMP);
