INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '진짜 친절해요 !! 하나하나 자세하게 설명해주시고 , 추천도 잘 해주세요 :) 케이크랑 커피 조합이 진짜 좋고 커피 맛이 다른 곳과 차별화된 맛이라 더 좋았어요 최고의 맛집 👍🏻👍🏻', 21, 3, 'GOOD', SYSTIMESTAMP);
