INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '너무 너무 맛있어요!! 디저트 먼저 주문하고 디저트랑 맞는 커피로 맞춰주세요!! 메뉴 나올때 친절하시게 자세히 설명해주셔서 너무 좋아요!! 근처에 오시면 꼭 방문하세요! 저번주 주말에 대기 좀 있어서 평일 저녁에 방문했는데 대기 없이 바로 입장했어요! 재방문 200%!!!!', 65, 18, 'GOOD', SYSTIMESTAMP);
