INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '한달에 한번씩 일부러라도 찾는 까페인데 갈때마다 디저트가 새로운게 나와서 정말 맘에듭니다ㅎㅎ 작년쯤 지인에게 추천받아서 가는곳인데 갈때마다 힐링됩니다!!', 6, 5, 'GOOD', SYSTIMESTAMP);
