INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '이미는 항상 좋죠 ~ 두말하면 잔소리네요! 여전히 친절하시고 커피와 디저트가 참 맛있어요! 딸기메뉴가 하길 기대하면서 갔지만 안했어도 좋았어요!☺️', 43, 7, 'GOOD', SYSTIMESTAMP);
