INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '올때마다 만족해요 디저트 맛있고 커피도 너무 좋아요. 디저트 커피 자세히 설명해주셔서 맛을 집중할수있고 노래도 좋아서 분위기 최고입니다!', 75, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '2년 전에 오렌지빙수 먹으러 몇번 갔던 곳인데 오랜만에 방문했더니 인테리어며 메뉴며 완전 리뉴얼 되었네요.😮 디저트를 고르면 거기에 어울리는 커피를 페어링해주는 방식으로 바뀌었는데 마치 파인다이닝에서 어울리는 와인 페어링 해주는 느낌이라 좋았어요. 그리고 서빙 해주시면서 디저트와 커피에 대한 스토리 텔링도 함께 해주셔서 더욱 대접 받는 느낌이었어요. 여기 몽블랑은 예전에 먹어보았어서 타르트 타탕으로 결정했는데 산미있는 커피와 함께하니 새콤 달콤한 사과 맛이 극대화 되는 느낌이었어요. 썰지 않은 사과를 통째로 구워 내서 그런지 식감도 더욱 풍부했던 거 같아요. 바닐라 빈이 콕콕 박힌 크림과의 조화도 너무 좋았어요. ^^', 8, 0, 'GOOD', SYSTIMESTAMP);
