INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '행복 오픈런 성공~🍑🫶🏻 복숭아가 너무 달고 맛있어요🥹 디저트랑 음료가 페어링이 너무 잘되네요. 인생 디저트 카페가 됐어요. 그리고 직원분들이 너무 친절하셔서 인상 깊어요!! 담에 또 올게요!!', 43, 6, 'GOOD', SYSTIMESTAMP);
