INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '인테리어도 이쁘고 설명을 아주 잘해주십니다! 문제는 커피마시러 갔는데 디저트 고르면 추천해주신다고 하시며 디저트 고르라는 느낌이 조금 강하게 들었습니다 추천만 해주시는게 아니고 커피는 당연하게 그 디저트에 추천커피를 주시려고 하시더라구요.반 강제적으로 그렇게 먹었는데,,,따로 먹었을때 너무 맛있었지만 그렇게 레이어가 좋은지는,,,,😞설명해주시는건 너무 좋았지만 살짝 강요하는 느낌이라아쉬웠습니다 그리고 그 강요하시면서 주문받으시는 분께서 다른직원들 하시는거 보시면서 평가지 같은 부분 쓰셨는데 조금 보기 좋지는 않았습니다ㅠㅠ 먼가 눈치보이는 방문이었습니다 커피는 존맛탱,,,👍🏻', 397, 29, NULL, SYSTIMESTAMP);
