INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '디저트는 완벽 그 자체! 입니다! 친절한 설명과 추천 좋았습니다! 커피 페어링도 너무 어울렸지만 개인별 차이가 있어 향과 맛이 세게 느껴졌습니다. 다음에 가게 되면 조금 연하게 마셔보고 싶네요! 그래도 그럴만한 페이링의 이유인 것 같아서 좋았습니다!', 18, 7, 'GOOD', SYSTIMESTAMP);
