INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '바닐라 오페라랑 멜론 무스 페어링 해서 주문했습니다. 메로나 맛과 향이 확실해서 재밌었네요:)) 바닐라 오페라도 크런키한 식감이 좋았고, 산미 없는 커피와 잘 어울려서 좋았습니다!', 12, 9, 'GOOD', SYSTIMESTAMP);
