INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '고급진 드립커피를 분위기 좋은 공간에서 즐길 수 있는 공간입니다. 주문할 때, 그리고 커피가 나왔을 때 원두에 대해 자세하고 친절하게 설명해 주시는데 넘 좋았어요. 커피 맛도 물론 매우 좋았구요😊 다음에는 디저트 메뉴와 오늘 못 마셔본 다른 원두도 맛보도 싶습니다!', 27, 5, 'GOOD', SYSTIMESTAMP);
