INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '커피 하나하나 잘 어울리는 디저트로 설명해주시는게 부담없이 너무 좋았어요, 커피도 너무 맛있고 분위기도 너무 좋아서 정말 자주 올거에요', 12, 1, 'GOOD', SYSTIMESTAMP);
