INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '커피 디저트 페어링 조합은 진짜 최고입니다ㅜㅜ 너무 맛있어요!!!!!!!💗 메뉴 하나하나 설명 친절하게 해주셔서 귀로 듣고 눈으로 보고 입으로 먹는 오감만족', 0, 10, 'GOOD', SYSTIMESTAMP);
