INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '복숭아에 진심이라 행복이를 안 먹고 지나갈 수 없었어요. 라인업이 바뀔때마다 다녀가보세요. 이미커피는 커피도 맛있고 디저트도 맛있습니다. 대기번호 받고 기다린 시간이 보람될 행복이를 만나실꺼라고 장담할께요!', 30, 5, 'GOOD', SYSTIMESTAMP);
