INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '여름의 행복을 맛보러 이미커피에 방문했어요. 달콤하고 버터리한, 다채로운 풍미가 가득한 행복 디저트를 먹으며 행복을 고스란히 느낄 수 있는 시간이었습니다⁎ˇ◡ˇ⁎ 같이 페어링해주신 복숭아홍차 원두도 깔끔한 복숭아향이 한가득이어서 복숭아 디저트를 제대로 즐긴 날이었어요🍑', 176, 56, 'GOOD', SYSTIMESTAMP);
