INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '항상 맛있는 커피 땡길때 찾는 곳이에요! 변함없는 맛에 재방문하게되었네요. 웨이팅이 심해서 테이크아웃했어요ㅜㅠ 기회되면 매장에서 여유롭게 먹고싶네요🫶', 21, 2, 'GOOD', SYSTIMESTAMP);
