INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '디카페인 콜롬비아 라스 플로레스 원두 사러 갔는데 없어서 아쉽 ㅜ 리치&망고스틴 맛 나는 디카페인 너무 좋음🥭 주블렌드도 구수하고 맛있었어요 몽블랑 달달하고 좋았어요', 122, 22, 'GOOD', SYSTIMESTAMP);
