INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '신선한 무화과 타르트와 페어링된 커피 모두 정말 맛있었어요. 복숭아 시즌 놓쳐서 아쉬웠는데 역시! 이미커피의 제철 과일과의 페어링 아이디어 존중해요^^', 56, 14, 'GOOD', SYSTIMESTAMP);
