INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '수요일 낮 3시에 갔는데 대기번호11번 받고 그냥 갈까하다가 꼭 가보고 싶어서 1시간 40분 기다리고 들어갔어요! 순서되면 연락주셔서 대기 걸어두고 다른 곳 다녀올 수 있어서 좋아요! 무엇보다 디저트가 진짜 너무 맛있고 커피도 너무 잘 어울렸어요!!!! 월간,주간 메뉴가 바뀐다니 다음에 또 가고 싶어요😭😭 그리고 직원분들이 너무 친절하셔요 분위기, 맛, 친절함 뭐 하나 부족한게 없네용', 18, 6, 'GOOD', SYSTIMESTAMP);
