INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '오랜 먹킷리스트였던 이미커피! 먹고 싶은 디저트를 고르면 어울리는 커피를 페어링해줍니다. 섬세한 디저트의 맛과 향을 머금은 커피를 온전히 즐길 수 있는 공간이어서 너무 만족스러웠습니다.🤍', 125, 21, 'GOOD', SYSTIMESTAMP);
