INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '커피(6000~)지나가다 마시러 방문 ...했으나 주말에 웨이팅 있어 45분이상 대기 시 7팀정도 밖에 빠지지 않아 취식불가ㅠ 디저트만 포장했으나 매장에서 먹지 못한게 아쉬울 정도로 달지않고 은은한 바닐라향이 올라오는 맛. 디저트 선택 시 커피 추천해주는 특색있는 곳으로 직원분들 친절하시고 웨이팅 어플로 대기 가능하니 참고하세요 ~', 30, 9, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
