INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '페어링 너무 적절하고 맛있고 정말 다 좋아요! 그런데 화장실은 좀 관리 잘 해주셔야 할 것 같아요..ㅠㅠ 한 번 다녀왔는데 거미 파리 모기를 각각 몇마리씩 봤구 손 닿는 곳에도 거미줄이 있곤 해서... 커피랑 페어링디저트 다 너무 좋았는데 마음의 거리가 확 떨어지려 했습니다ㅠ 화장실 관리 개선하시면 훨씬 좋을 것 같아요!', 39, 8, NULL, SYSTIMESTAMP);
