INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '일단 매장 분위기가 너무 좋아요. 입구부터 블루리본이 붙어있어 믿음이 갑니다. 쇼콜라,바질망고, 아스파한 전부 페어링해서 마셨어요 그 중 아스파한 케이크는 매우 향긋하고 상큼해서 준비해주신 커피랑 잘 어울리더라구요 최고의 맛이었어요👍🏻 저는 사실 얼음가득 아아를 선호하는 편인데 이미커피는 (얼음두개정도?)시원한 정도로만 제공되더라구요 아직 커피를 잘 몰라 적응하기 힘든 아이스 커피였어요ㅎㅎ 제가 갔던 일행빼고는 전부 혼자 오신 분들이라 저도 나중에 혼자 방문해볼 예정이예요 잘먹고갑니다!', 42, 5, 'GOOD', SYSTIMESTAMP);
