INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '웨이팅이  있다는말에  오픈시간  맞춰서  입장 !!! 이왕간거  3가지  디저트  다  시킴 ㅎㅎ 디저트와  어울리는  커피도  좋지만  갠적으로  라떼  좋아해서  라떼시킴!!  라떼는  병에  미리  담겨있고 칭구가  고른  시나몬케잌에  어울리는  커피 페어링해줬는데  오~~  맛있음 ^^ 디저트는  조금씩  바뀐다는데.... 언제  또  가볼지는....미정 ㅎ', 42, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
