INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '디저트 맛있어요! 그런데 이번 바닐라 밀페유는 진짜 너무 맛있네요💛 갈때마다 친절한 설명에 감동하고, 그 설명 그대로 맛이 느껴져서 신기하고 너무 좋아요😍 디저트와 커피가 계속 바뀌기때문에 주기적으로 가줘야 합니당👍🏻', 14, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '매달/격주로 바뀌는 페어링 디저트가 고급스럽고 맛있습니다. 특히 이번 주의 카시스 오페라가 너무 달지 않고 깔끔하게 맛있었어서 추천합니다 ^_^', 87, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '모든게 완벽한 곳! 맛있는 커피에 맛있는 디저트가 함께 있는 최고의 카페🤍 특히나 페어링 디저트를 설명받을 때 기분이 아주 좋고 재밌어요ㅎㅎ 자주 오고싶어요! 다음 디저트는 뭘지 궁금해져용', 66, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '디저트를 정하면 디저트에 어울리는 커피를 페어링 해주는 카페. 단순히 커피를 마시기 보다 주인이 추천해준 디저트와 커피를 마시면서 한번 더 맛을 음미하게 되는 곳. 평소 커피와 디저트를 즐기는 사람이라면 가보는 것을 추천. 딸기 케이크는 가격이 있는 편이지만 양이 어마어마하기때문에 혼자 먹기엔 버거웠음. 핸드드립 커피도 양이 많은 편. 퀄리티도 높고 맛있었기때문에 금액이 높지만 아깝지 않다. 어느 리뷰에서 책 읽기 좋다고 해서 책을 가져갔는데 손님들도 많고.. 정말 시끄러워서 귀가 아플 지경. 단점은 제빙기? 소리가 매우 요란하다는 점. 웨이팅도 길지 않아서 기다릴만한 곳.', 48, 9, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
