INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '예전에 자주갔는데 오랜만에 갔더니 시스템이 바뀜 커피에 중점적으로 뭔가 하려는 느낌 오치퐁 못먹어서 아쉽지만 그래도 디저트 맛있었음', 50, 8, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '디저트는 맛있는데. 커피는 모르겠습니다. 설명에 비해 맛이 너무 떨어져요. 금액에 비해 맛이…너무 과금하신 것 같습니다. 오치퐁을 먹고 커피를 마시는게 되려 디저트 맛도 망치고 커피맛도 닝닝했어요. 페어링의 뜻이 무엇이었나요.?. 직원분들 설명 땐 조용조용 말씀하시더니 직원분들끼리 사담하시는 소리가 점점 커져서. 동행인과 대화가 어려웠습니다. 직원분들의 목소리 커짐에 손님들도 다같이 목소리가 커져 시장통 같아졌어요. 펜도 주셨으면 적을 말이 많았는데. 아쉽네요.', 29, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '커피 정말 맛없고 친절함이 과해서 별로였다. 디저트와 어울리는 커피라길래 먹고 마셔보니 오히려 중화되어 맹물 마시는 느낌. 내가 커피 잘 모르는데 여기 커피는 나랑 안맞는건 알겠다. 두번 다시 안감. 즉흥적으로 들어가면 항상 망함. 검색 한번이라도 해볼껄. 아 디저트는 맛있었음.', 49, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '칭찬할게 너무너무 많은곳!!! 정말 인테리어도 차분하니 디저트와 커피를 온전히 느낄수있는곳이에요!!! 디저트와 어울리는 커피를 내려주시는데 정말 잘어울려서 신기했어요!!! 웨이팅을 하긴 했지만 그 시간들이 아깝지 않았어요!!!', 54, 16, 'GOOD', SYSTIMESTAMP);
