INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '입간판에 끌려서 들어갔는데...분위기 좋고, 커피 맛있고...다만 다소 시끄러워 일얘기나 대화하기는 좀 힘들더라구요. 그래도 정성스레 준비된 음료가 인상적이었어요', 41, 4, NULL, SYSTIMESTAMP);
