INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '🍓페어링 프리지에, 19,500 🥭페어링 망고무스, 14,000 디저트들이 엄청 맛있었어요! 네이밍이 귀여운 커피들도 재밌었습니다.', 38, 8, 'GOOD', SYSTIMESTAMP);
