INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '페어링 시스템의 효과가 의문이네요. 디카페인 한종류밖에 없어서 디저트를 다른것 시켜도 페어링 커피가 한종류. 커피는 나쁘지 않았습니다. 디저트와 공간의 특별함은 못느꼈어요.', 16, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '디저트 맛집. 가격이 비싼만큼 설명과 정성이 있네요. 커피는 제 취향이 아니지만.. 디카페인도 있는줄 몰랐는데 다음엔 디카페인 먹어봐야겠어요. 디저트가 진짜 굿', 32, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), 'Coffee: Colombia Loco Series #11 Dessert: Rosemary Plum Dacquoise 페어링세트: 14,000원 주(住) 블랜드 (India+Ethiopia+Colombia): 6000원 콜롬비아 로코 시리즈는, 첫 모금부터 예사롭지 않았습니다. 날카로운 산미와, 후추, 마라탕의 매운맛이 살짝 제거된 맛이, 굉장히 독특하고 신비로웠습니다. 페어링한 로즈마리 플럼 다쿠아즈는, 산뜻하고 깔끔한 크림, 자두의 상큼함, 그리고, 다쿠아즈의 푹신한 식감이, 커피와 잘 어울려서 맛있었습니다. 주(住) 블랜드는, 콜롬비아와는 달리, 강배전된 원두가 사용되었습니다. 묵직함이 살짝 제거된, 가벼운 느낌의 질감과, 입안에 여운이 남는, 단맛이 인상적이었습니다.', 20, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '홍대 텃주대감인 이미가 얼마전 리뉴얼이 끝나고 방문 했습니다. 너무너무 좋아하는 곳입니다 여름에는 복숭아 디저크로 유명한 곳입니다 리뉴얼 후 지금은 커피도 디저트도 더 업그레이드 된 느낌이에요 이미의 마스코트 보리도 간간히 상주 합니다', 69, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '나만 알고 싶은 카페인데 이미 너무 유명해서 이미커피.. 디저트를 고르면 어울리는 커피를 페어링 해줍니다.. 같이 먹어보면 정말 후회없을 매칭이에요. 보통은 커피나 디저트 한 쪽이 맛을 덮거나 가려서 충분히 둘 다 즐기기 어려울거라 생각하지만 이곳은 서로의 맛을 보완해주고 더 맛있게 해주는거 같아요ㅠ 주말이라 대기가 길었지만 충분히 만족합니다', 8, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '평일인데도 한시간 반 넘게 기다려서 진짜 진짜화가 많이 났지만 주문한 디저트 메뉴, 커피 둘 다맛있어서 화가 다 풀렸네요..ㅠㅠ 다 먹고 또 포장해서 가고싶은 맛입니다....', 8, 8, 'GOOD', SYSTIMESTAMP);
