INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '자주 가는데 아주 불친절한 직원이 한명 있어서 그분 있으면 기분이 나쁨ㅋㅋ 기분좋게 비싼커피 케이크 먹으러 가는건데 왜 기분나빠져야하는지모르겠음', 38, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이미커피'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '직원분들 모두 매우 친절하셨으며 드립 커피는 4종류 디저트류는 3종류가 있었으며 주문은 디저트를 고르면 그 맛에 따른 커피를 추천해주시는 방식으로 진행되었습니다. 달과 주로 나뉘에 바뀌는 커피와 디저트가 있었으며 커피는 맛이 좋아 한번에 다 맛을 보게 된 매장이였습니다. 다음 달에 한번 더 들려볼 생각입니다~! 잘 마시고 편히 쉬다 갔습니다. 감사드려요^^ 추가로 화장실은 따로 분리되어 있지 않아 조금 불편함이 있습니다.', 35, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '카페 공명 지점별 친구와 도장깨기 중인 1인 입니다~ 공명마다 컨셉이 다 달라서 가는 곳마다 다른 분위기를 느끼고 즐기고 올 수 있어서 좋아요~ 커피 맛 좋은 것은 기본이고 디저트도요 >< 날이 얼른 선선해지길 바랄 뿐이에요! 그래야 홍대점은 야외 좌석에서 시간 보내기 너무 좋을 거 같아서요 😉', 47, 7, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'TERRACE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '사랑해 마지않는 공간🌷 평일 낮에 두세 시간 공부하다 가기도 좋고, 저녁에 친구와 와서 떠들다 가기도 좋은 카페 공명입니다아☺️ 공간이 넓어 평일에는 대기가 없고(주말은 잘 모르겠어요), 와이파이/좌석/화장실/담요/충전기 등 이용자 편의도 최대로 고려해주신 느낌입니다! 직원 분들도 친절하셔서 기분이 좋고, 디저트가 예뻐서 나가는 길에 선물 포장해가기도 딱이에요! 포인트 적립도 많이 해주셔서(무려 15%!...) 9월 중에도 벌써 세 번째 방문이에요! 이미 유명했지만 더 번창하시길 빕니다🙏(제 자리 있을 정도까지만)', 18, 4, 'GOOD', SYSTIMESTAMP);
