INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '홍대 카페 공명 다녀왔어요 ☕ 아치형 창문과 벽돌 인테리어가 감성적이고 분위기 좋아요. 아메리카노랑 밀크티 모두 맛있고, 라즈베리 스콘은 상큼+달콤 조합이 딱이었어요. 분위기, 맛 다 만족스러워서 홍대 오시면 추천합니다 👍', 16, 3, 'GOOD', SYSTIMESTAMP);
