INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '꼭 와보고 싶었던 홍대공명에 왔어요. 화창한 금요일 오전이라 조용하고 햇살이 가득 내려 앉아 예뻐요. 공간 하나하나가 예쁘고 편안해 보입니다. 직원분도 친절하시고 말차라떼 진하고 맛있어요. 겉바속촉의 까눌레도 너무 좋아요', 50, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '카페공명은 좌석이 30석 이상이라 혼잡한 느낌 없이 넉넉하게 이용할 수 있었어요. 클래식한 인테리어가 고급스럽고 깔끔해서 분위기도 좋았습니다. 매장이 전반적으로 시원하게 유지되어 여름에도 시원해서 쾌적했고, 특히 평일에는 사람도 적어 조용히 커피 즐기기 좋았어요. 주말엔 웨이팅이 심했으니 방문 계획에 참고하시면 좋을 것 같아요.', 92, 21, 'GOOD', SYSTIMESTAMP);
