INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '연남점 에서 스콘이랑 공명라떼 너무 맛있게 먹어서 홍대점 방문했어여🎀 먹고 집가서도 다시 생각나는 맛이라 한번 가면 또 가게되는 찐맛집 입니다🩷', 125, 26, 'GOOD', SYSTIMESTAMP);
