INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '분위기도 차분하고 메뉴 맛도 너무 좋았어여 골목에 위치하고 있는데 다른 세계 온느낌처럼 나는 곳이 있거든요 그게 바로 공명카페~~ 공명라떼라고 시그니처 메뉴가 있었는데 크림이 꼬소하고 맛있더라구요! 진짜 찐한 맛이고 적당히 달달해서 커피랑 잘어울렸어요 약간 계피향도 나는게 카페 분위기랑 잘어울리는 맛있이었어요 여기 빵도 잘하네요....너무좋다..🥰🥰', 33, 8, 'GOOD', SYSTIMESTAMP);
