INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '연남점은 많이 갔었는데 홍대점은 처음이에요 까눌레를 홍대점에서만 판다고 하더라구요! 늦은 시간에 와서 디저트가 가득가득하지는 않았지만 최애 바닐라 까눌레는 남아 있어서 좋았어요🥹❤️', 39, 5, 'GOOD', SYSTIMESTAMP);
