INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '추천받아서 처음와봣는데 분위기도좋고 디저트가 너무맛잇어요!!! 바리스타 추천이라는 사과유자차도 마셔봣는데 유자청이 들어잇어서 놀랏어요 ㅎㅎ 달달상콤하니 맛잇습니다! 커피 못마시는분들은 요거 마셔도 좋을것같아요~', 108, 23, 'GOOD', SYSTIMESTAMP);
