INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '우유생크림스콘은 우유의 고소함이 잘 느껴지고 비스킷슈는 겉은 바삭한데 안에 슈크림이 넘 부드러워요💗 바스크치즈케이크 포장해가려고 했더니 500원 포장비를 따로 받는다 그래서 당황스러웠어요😅 결국 포장은 해왓지만,, 그래도 역시 맛은 있어요!!!!', 36, 5, NULL, SYSTIMESTAMP);
