INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '원두 고소한거 산미있는거 디카페인 선택할 수 있고 디저트도 다양해요. 쿠키랑 구움과자류도 맛있고 오늘은 우유케이크 시켜봤는데 우유맛 진한 동물성 생크림이라 맛있게 잘 먹었어요~ 매장도 넓고 노래소리도 크지 않게 딱 적당한 음량으로 틀어주셔서 대화나누기도 편했어요~', 26, 9, 'GOOD', SYSTIMESTAMP);
