INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '스콘도 맛있고 에이드도 맛있어요! 커피 맛있다는 이야기가 많아서 다음에는 커피로 마셔보려구요! 무엇보다 인테리어가 너무 멋있어서 좋았어요!', 50, 10, 'GOOD', SYSTIMESTAMP);
