INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '인테리어가 너무 예뻐서 사진 찍기 좋은 곳이에요. 라떼랑 망고에이드 시켰는데 라떼 고소하고 부들럽고 맛있더라고요. 에이드는 달콤한 망고 맛이 너무 좋더라고요. 더운 날에 마시니까 시원해서 기분 짱 ㅎ. 여자들이 정말 좋아할 것 같은 곳이에요', 16, 6, 'GOOD', SYSTIMESTAMP);
