INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '여기 매번 오고 싶었는데 드디어 와요!!!! 스콘 종류도 다양하고 쿠키도 맛있어보여요:) 매장도 너무 넓고 예뻐서 홍대 데이트 코스로 추천드립니다!!!! 슈 종류도 다 맛있어보여요:) 공명 최고!!🤍🥺💕', 45, 4, 'GOOD', SYSTIMESTAMP);
