INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '홍대점 와보고 싶었는데 평일 낮이어서 자리도 많았어요 친절하시고 바스크 치즈케잌도 맛있네요 커피는  산미가 살짝있는 누구나 마시기 편한 정도의 맛이었어요 적립도 되고 알림받기  하심 커피도 한잔 주셔요^^', 35, 9, 'GOOD', SYSTIMESTAMP);
