INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '카페 공명 연남, 망원점에 이어 홍대점을 방문했는데 세 지점 전부 따뜻한 분위기의 인테리어가 마음을 편안하게 하고, 음악소리도 크지 않고 잔잔해서 작업하기에 최적화된 카페 인것 같아요 ㅎㅎ 직원분들도 친절하시고 전반적으로 만족스러운 느낌의 카페 예요 ~ . ~', 55, 17, 'GOOD', SYSTIMESTAMP);
