INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '예전부터 지도에 찜해뒀던 곳인데 드디어 와봤어요. 아늑한 인테리어에 다양한 디저트와 음료를 맛볼 수 있고 골목에 있지만 찾기 쉬워요. 날이 좋다면 밖에 앉아도 좋을 것 같아요. 직원분들도 다 친절하시고 음료도 맛있고 편히 쉬기 좋아요 !', 104, 23, 'GOOD', SYSTIMESTAMP);
