INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '서울 올라오면 꼭 가는 카페입니다! 홍대에는 공명 같은 카페는 없는 거 같습니다. 처음 오시면 시그니처인 공병라떼 꼭 드시고 다른 매뉴도 차차 드셔보기를 추천합니다~', 6, 5, 'GOOD', SYSTIMESTAMP);
