INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '요즘 분위기 좋은 카페 찾다가 완전 취향저격 카페 발견했어요! 통유리창으로 햇살 가득 들어오고, 플랜테리어 감성에 디저트까지 완벽… 커플끼리 조용히 수다 떨기 딱 좋고, 사진도 잘 나와서 인생샷 건졌어요. 데이트 장소 찾는 분들 강추해요 :)', 37, 10, 'GOOD', SYSTIMESTAMP);
