INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '저번에는 만석이라 그냥 돌아갔었는데 오늘은 운좋게 자리잡았어요😁 내부가 넓고 자리도 많아서 이용하기 좋아요 디카페인 아메리카노로 마셔봤는데 여태 마셔봤던 디카페인중에 깔끔하고 입맛에 맞아서 좋았어요 다음에 또 오고싶어요👍', 72, 11, 'GOOD', SYSTIMESTAMP);
