INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '디저트 맛있고 커피 맛있고 인테리어 좋아요 !!!! 완벽한 삼박자를 갖춘 카페라서 또 오고 싶어요. 아이스 아메리카노 맛도리 짱짱짱😍 연남 원두도 산미 있는 편이니 참고하세요!', 19, 6, 'GOOD', SYSTIMESTAMP);
