INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '홍대 골목의 분위기를 반전시키는 카페 너무 예쁜 건물에 이끌려 들어온 카페 공명. 배부른 상태에서도 디저트와 커피가 정말 만족스러웠어요. 아메리카노는 끝맛까지 깔끔해서 좋았고, 라즈베리잼스콘과 우유케이크는 너무 달지도 않고 제 입맛에 딱 맛있었어요! 이번엔 아메리카노 시켰지만 다음엔 라떼도 시도해보겠습니다^^ 힐링하고 가요!', 124, 20, 'GOOD', SYSTIMESTAMP);
