INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '배달로 공명 알게 됐는데 쿠키슈랑 스콘 진짜 다 맛있더라고요!! 매장 방문은 처음인데 분위기 너무 좋고 친절하시고 음료도 맛있어서 좋았어요!!!! 디저트는 말모!!', 44, 3, 'GOOD', SYSTIMESTAMP);
