INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '여자친구가 몇일전부터 슈가 들어간 디저트를 먹고싶어했는데 그런 니즈에 맞춰 찾아간 카페에요! 분위기도 좋고 음료도 맛있는데 디저트와 라떼가 대박이에요! 여자친구가 너무 맛있어서 박수까지 치고 난리났네요 ㅎㅎ 느긋하게 시간 보내기 좋은곳같습니다!', 21, 6, 'GOOD', SYSTIMESTAMP);
