INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '슈 맛집이라고 추천받아서 왔는데 한 번 먹고 다른 슈는 이제 못먹을 거 같아요 커피도 시그니쳐 메뉴가 있어서 먹었는데 색다르고 맛있어요!!!', 112, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '촉촉하게 봄비가 내리던 날, 상수 골목 안쪽의 조용한 감성 카페에서 아메리카노와 우유생크림 스콘을 즐겼습니다. 스콘은 겉은 바삭하고 속은 은근 촉촉한 식감에 삼삼한 단맛이 퍼졌고, 우유생크림은 꾸덕하지 않고 부드러워 입안 가득 산뜻하게 녹아들었습니다. 아메리카노는 산미보다는 고소한 밸런스 쪽에 가까워 스콘과 커피를 머금었을 때의 버터향과도 잘 어울렸습니다. 창밖 빗소리와 함께 연인 또는 친구들과 느긋하게 머물기 좋은, 그리고 분위기마저 촉촉하게 스며드는 공간이었습니다.', 129, 23, 'GOOD', SYSTIMESTAMP);
