INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '연남점만 많이 다녀봤지 홍대점은 처음이에요! 공명은 책 맛집+ 커피맛집 + 그리고 베이커리 맛집이잖아용❤ 방문한 날에도 비가 조금씩 오는데 갓 구운 스콘냄새가 폴폴이라 못 참고 공명에 와버렸네요! 크림 빵빵한 스콘도 맛있지만 우유크림케이크를 먹었어요! 비가 마니 오진 않아서 바깥 테라스에 앉아 친구랑 담소를 나누는데 너무 좋네요! 간만에 힐링다운 힐링을 했어요❤', 15, 5, 'GOOD', SYSTIMESTAMP);
