INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '피스타치오 크림라떼를 먹었는데 너무 맛있었고 카페가 조용하고 자리도 많아서 너무 좋았어요.. 사용은 하지 않았지만 담요가 구비 되어있다는 점이 너무 좋았어요..   혼자 왔는데 집중해서 작업하기 좋았어요🩵', 5, 2, 'GOOD', SYSTIMESTAMP);
