INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '그동안 와보고 싶었던 곳인데 카페 인테리어도 분위기도 너무 좋아요!! 무엇보다 디저트가 너무 맛있어요🩷 데이트 하러 왔는데 성공적이네요ㅎㅎㅎ', 4, 1, 'GOOD', SYSTIMESTAMP);
