INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '홍대 공명에서 마신 콜드브루는 깊고 깔끔한 풍미가 인상적이었습니다. 생크림 스콘은 겉은 바삭하고 속은 촉촉해서 밀크티와 정말 잘 어울렸습니다. 카페 분위기는 조용하고 아늑해서 혼자 방문하기에도 무척 편안했습니다. 직원분들도 친절하시고, 주문도 빠르게 나와 전체적인 만족도가 높았습니다. 다음에 방문하면 다른 디저트도 꼭 맛보고 싶다는 생각이 들었습니다.', 7, 2, 'GOOD', SYSTIMESTAMP);
