INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '네이버에 리뷰도 많고 평이 좋아서 와봤는데요! 인테리어도 너무 많고 커플들끼리 오면 너무 좋을 듯싶네용 저도 여자친구랑 와서 커피랑 에이드 마시면서 수다떨다가 와요! 다음에도 올 것 같아용', 4, 0, 'GOOD', SYSTIMESTAMP);
