INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '매장이 넓고 예뻐서 여럿이 함께 모여 커피 마시기 좋을 것 같아요. 날씨 좋은 날 야외 테이블에서 먹으면👍👍👍 베이커리류도 맛있어보여요.', 20, 2, 'GOOD', SYSTIMESTAMP);
