INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '비오는 날 혼자 방문했는데 직원분들이 친절하시고 분위기도 차분하고 넓고 깨끗해서 정말 좋았습니다! 초코나무숲 스콘을 먹었는데 적당히 달고 크림이 안느끼해서 다른 스콘도 또 먹고싶네요 ㅎㅎ 아메리카노도 디카페인으로 시켰는데 맛있었어요! 다음에 꼭 친구랑 다시 오려구요 :)', 37, 7, 'GOOD', SYSTIMESTAMP);
