INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '전에 친구랑같이 한번와보고 너무 좋아서 다시왔습ㄴ다!!그때는 날이좋아서 루프탑에앉아서 먹고 옆에 잠시나온 사모예드 3마리도 보고 너무좋았는데 오늘은 비가와서 안에앉았네요ㅠㅠ안에도 너무아늑하고 좋습니다!!디저트도 맛있고 커피원두도 선택할수있어서 좋아요🥹🩶', 19, 6, 'GOOD', SYSTIMESTAMP);
