INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '홍대에서 핫플 카페라고 해서 방문했는데 왜 인기 있는지 알겠더라구요:) 인테리어도 너무 멋있고 건물 자체가 너무 멋있었어요ㅎㅎ  음료도 눈과 입 둘다 사로잡는 곳이었습니다🫶❤️ 추천해드리고 싶네요 꼭 한 번 와보세요!! 감사합니다!!', 21, 2, 'GOOD', SYSTIMESTAMP);
