INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '힙하고 분위기 좋은 카페에요. 공간이 많고 넓고 특별한 날에도 일상에도 잘 어울리네요~ 각 공간마다 특색이 있으니 다른날 다른 공간 다른 디저트로 먹으러 재방문하고 싶어요.', 8, 2, 'GOOD', SYSTIMESTAMP);
