INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '네이버 검색하다가 근처길래 왔어요🙂 마들렌 종류가 많고 크림스콘들이 있어서 좋았어요~ 연남 아메리카노가 기본, 홍대 아메리카노가 산미 있는 아메리카노였어요 근데 연남아메도 생각외로 산미있는 느낌이었어요 라즈베리스콘은 부드럽고 느끼할수있는 맛을 잼이 잡아줘서 맛있었어요😋😋 좌석이 쪼끔 애매하긴했지만 전반적으로 무난무난하니 한번쯤 오기 좋은거같아요', 0, 1, 'GOOD', SYSTIMESTAMP);
