INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '디저트가 맛있어서 자주 오는 곳이에요 적립도 15프로나 돼서 서너번만 와도 공짜커피 먹는 기분😎👍 분위기도 좋고 다 좋고 오래오래 있어주세요!!', 0, 4, 'GOOD', SYSTIMESTAMP);
