INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '지점을 막론하고 카페 공명은 홍대 부근에 오면 믿고 가는 카페 중 하나입니다. 오늘은 간만에 2호점에 커피 한 잔 하러 왔는데, 밝은 햇살에 분위기가 더욱 살아나는 풍경이 오길 잘했다는 생각이 들게 합니다. 아메리카노는 물양을 적게한 것을 좋아하는데, 다크 블랜드(연남)의 풍미가 깊이 있게 기분좋게 입 안을 감싸줍니다. 믿고 마시는 한 잔, 훌륭합니다🤩', 31, 8, 'GOOD', SYSTIMESTAMP);
