INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '커피와 비스킷슈의 조합이 너무 잘맞아요 :) 크림스콘도 맛있어 보여서 다음 방문에 먹어보려 합니다 ! 분위기도 좋아서 혼자 오기에도 , 대화하기에도 좋아 보입니다 ㅎㅎ', 28, 1, 'GOOD', SYSTIMESTAMP);
