INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '너무 더워서 그냥 들어왔는데 분위기도 좋고 대화하기에도 좋아요! 넓어서 편하게 앉을 수 있고 직원분들도 친절하십니다ㅎㅎ 음료 받고 나서 다시 리뷰 추가했어요.. 애플망고 에이드 음료가 너무 맛있어요 그리고 영수증 리뷰로 받은 쿠키도 진짜 맛있습니다!! 다음에 재방문할 예정이예요', 129, 22, 'GOOD', SYSTIMESTAMP);
