INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '연남에 있는 공명만 가봤다가 홍대점은 처음왔는데, 평일에 오니 한적하고 좋습니다 ✨☺️ 아메리카노 원두 고르는게 좋았고, 연남 원두로 주문했는데 약간의 산미와 고소함이 어우러져 맛있었어요! 디저트류도 다양해서 페어링하기 좋숩니다🥰', 41, 4, 'GOOD', SYSTIMESTAMP);
