INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '꼭 한번쯤 와보고싶던카페였는데 !! 마침 제생일에 이렇게 예쁜카페에 오게되서 너무좋았어요 🥹💓 진짜 인테리어 하나하나 다 제취향이어서 머무르는 내내 기분이 참좋았어요ㅎㅎ 사진도 인생샷 건지기에 최적인거같아요 😗👍🏻 여름엔 또 다른감성일거같아서 재방문의사 1000%입니댜❤️‍🔥👻', 37, 1, 'GOOD', SYSTIMESTAMP);
