INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '친구랑 만나서 같이 주문하려다가 다른 분들의 메뉴를 보고 도저히 못참고 먼저 주문해버렸습니다ㅎㅎ 마들렌 러버 인데 진짜 기본 바닐라로 시켜봤는데 실망 전혀 없는 맛 너무 맛있어요 친구 오면 라떼 한잔 더 시켜 마시려구요', 13, 6, 'GOOD', SYSTIMESTAMP);
