INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '크림스콘으로 유명한 공명! 첫 방문했는데 매장도 큰 편이고 인테리어도 좋고 디저트들이 너무 맛있어보이고 좋아요 ◠‿◠ 친구랑 수다떨기도 좋아요! 추천합니다😍', 25, 4, 'GOOD', SYSTIMESTAMP);
