INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '윤씨밀방에서 밥먹고 주변에 이쁜 카페를 발견해서 우연히 오게되었어요. 매장이 굉장히 넓어서 웨이팅없이 들어갔고 쿠키와 피스타치오크림라떼를 주문했습니다 디저트 종류가 많고 맛있어보이는게 많아서 고민을 많이 했어요!ㅋㅋㅋ 또 원산지 표기도 신뢰가 가서 좋았습니다 홍대 주변에 세군데나 있어서 이 근처에 오면 또 와보려고해요', 3, 8, 'GOOD', SYSTIMESTAMP);
