INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '카페 분위기가 너무 좋아요. 3층까지 있어서 원하는 곳에서 원하는 분위기로 시간 보낼 수 있고, 커피랑 디저트도 맛있어요. 주문 받아주신 직원 분이 너무 친절하셔서 기분 좋게 있다 왔어요~', 34, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '음료 되게 맛있고, 빵도 적당히 달고 정말 맛있어요 야외 테라스도 있고 인테리어도 멋있어요 손님 분들도 다들 매너있어서 좋아요', 43, 2, 'GOOD', SYSTIMESTAMP);
