INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '식전에 커피 한 잔 하려고 들렀는데 분위기가 너무 아늑하고 좋네요. 날씨 좀 더 따뜻해지면 야외석에서 앉아서 마셔도 너무 좋을 것 같아요ㅎㅎ', 31, 3, 'GOOD', SYSTIMESTAMP);
