INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '연말 친구모임 헤어지기 아쉬워서 좀 늦은시간까지 하는 카페를 찾다 들러봤어요 전에 근처 지나다가 트리에 다람쥐가 잔뜩 열린(ㅋㅋ) 카페를 본 기억이 있는데 그곳이 바로 공명이었네요! 베이커리 메뉴도 다양해서 뭘 맛봐야하나 고민했는데 스콘 비주얼에 다들 눈이 돌아가서 바로 픽!ㅋㅋㅋ 담백한 스콘에 도톰한 크림과 잼이 곁들여지니 티푸드로 완전 잘어울리네요😚', 3, 10, 'GOOD', SYSTIMESTAMP);
