INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '사춘기소녀들을 데리고 네 가족이 방문했어요. 비가 촉촉 오는 날이었는데 분위기도 아늑하고 빵과 쿠키,커피향이 참 좋았어요~ 또 오고 싶어요', 119, 26, 'GOOD', SYSTIMESTAMP);
