INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '연남점만 이용하다가 기분전환하려고 홍대점 이용했는데 자리도 많고 눈치도 안 보이고 사람도 적당히 많고 커피, 디저트, 음료 모두 맛있고, 직원분도 친절해요!! 늦게까지 영업해서 좋습니다!! 깔끔하고 쾌적해서 실내외 모두 이용하기 좋습니다👍👍', 0, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '벌써 10번넘게 방문한 학교앞에서 젤 조은카페입니다 포인트도 15퍼센트씩 쌓아줘서 야무지게 이용중이에요..음료랑 디저트 넘맛있고 밤10시에 예약해서 랜덤디저트박스 가져가는것도 넘 조아용 대형카페라 자리도 많고 카공하기에 너무 좋아요 시험기간이라 또 매일 올예정...', 4, 5, 'GOOD', SYSTIMESTAMP);
