INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '홍대에 이런 넓고 조용한 카페가 있는 줄 몰랐네요..! 작업하기 좋고 야외석에서 햇살과 함께 담소 나누기도 좋은 카페인 것 같습니다🪽 꽃 피는 계절에 친구들이랑 함께 놀러와야겠습니다 ㅎㅎ', 49, 7, 'GOOD', SYSTIMESTAMP);
