INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '연남점보다 좀 더 조용하고, 아늑한 분위기라 좋아요 ㅎㅎ 따뜻하고, 편안하고,, 디저트도 맛있고 나들이 오시면 다들 만족하실 것 같아요 ㅎㅎ 넓어서 이야기하기도 좋습니다', 82, 13, 'GOOD', SYSTIMESTAMP);
