INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '일요일 오후에 예약없이 왔는데, 운이 좋게 자리가 있어 잠시 쉬었다 갔습니다. 디저트 종류가 다양했는데, 맛도 음료와 어울려 굉장히 좋았습니다. 커피 또한 향과 맛을 둘다 잡은 훌륭한 음료였습니다. 다음에 또 방문할 계획입니다!', 13, 4, 'GOOD', SYSTIMESTAMP);
