INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '깊은 향과 맛의 커피를 즐길 수 있어 마음의 여유를 느낍니다. 아늑한 인테리어와 정성 어린 서비스가 좋고 , 친구와의 만남에도 좋아요. 작업하기도 굿입니당', 74, 17, 'GOOD', SYSTIMESTAMP);
