INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '일 끝나고 자주 오는 곳인데 스콘이며 까눌레며 너무 맛있어요🥺❤️.. 다른 친구들한테도 자주 추천하는 곳입니다!! 정말 맛있으니까 꼭 꼭 와보셧으면 좋겟어요 원두 이름도 연남 홍대 합정 이렇게 지역 이름으로 있어서 신선하고 재밌습니당ㅎㅎ', 21, 8, 'GOOD', SYSTIMESTAMP);
