INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '커피가 맛있는 카페입니다! 카페라떼가 추천메뉴라고 하셔서 시켰는데 추천하시는 이유가 있어요. 우유 특유의 달달함이 잘 느껴지는 맛난 라떼네요! 아트도 멋있어요☕️', 60, 11, 'GOOD', SYSTIMESTAMP);
