INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '카페 분위기도 좋고 메뉴판이 특이해서 눈이 즐거운 카페였어요! 디저트도 맛있어보이고 2층 곳곳에 콘센트도 많아서 공부하기 좋아요 짱😍', 118, 23, 'GOOD', SYSTIMESTAMP);
