INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '건물 전체를 사용하고있어서 연남점보다 더 편했어요 맛은 똑같은데 아메리카노는 샷이 하나 빠졌나? 싶었어요 집앞이였으면 진짜 자주 왔을텐데ㅜㅜ', 67, 13, NULL, SYSTIMESTAMP);
