INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '매장 인테리어가 너무 예뻐서 사진찍기에도 좋을 것 같아요:) 서비스로 주신 쿠키도 고소바삭하니 너무 맛있었어요. 항상 사람이 많았는데, 오늘은 평일이라 그런지 거의 없어서 여유롭게 마시다 갈 수 있었습니다💙', 39, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '항상 와보고 싶었던 곳 공명 와봤는데 직원분들 다 너무 친절하시고 오늘은 평소보다 사람이 덜 해서 분위기 있게 맛있는 커피랑 디저트 먹고 갈 수 있을 것 같아요!! 또 올게요🤍', 28, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '커피맛도 공간도 너무 좋은 곳이에요. 원두도 선택할 수 있어요. 카피맛집 인정! 라떼도 아메리카노도 모두 맛있어요. 우유케이크는 입에 넣는 순간 정말 사르르륵 녹아요 평일에 방문해서 웨이팅 없이 방문했습니다.', 25, 7, 'GOOD', SYSTIMESTAMP);
