INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '처음와보는데 너무 깔끔하고 시원하고 디저트들 냄새가 장난아니에요!!! 무조건 하나이상은 먹게되는것같아요!!! 굿 (b ᵔ▽ᵔ)b (b ᵔ▽ᵔ)b', 95, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '처음 와봤는데 공간을 너무 잘해놓으셨어요! 클스마스 지났는데도 설레는 인테리어와 디저트/음료 다 맛있고 만족스러웠습니다🤠 공간상 특정자리는 시끄러울수 있는데 단체석이 분리가 잘되어있어서 편안하게 얘기할수 있어서 좋았어요^^ 다음에 또 방문하려구요!', 7, 10, 'GOOD', SYSTIMESTAMP);
