INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '크으ㅠㅠ 서울 온김에 고른 카페인데 선택하길 너무 잘했어유 초코나무숲 진짜 달구 최고 꾸덕 존마탱이에요!!!❤❤ 레몬마들렌도 맛있구 커피도 그냥 다 최고ㅠㅠ 천안에도 내주시면 안대나요^-T 크크', 4, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '근처에 볼일있으면 항상 들리는곳이에용 원래 계단이 조금 가팔라서 위험한거같았는데 몇달 안온사이에 계단 공사하셔서 훨씬 안전하고 편해졌어요 ㅎㅎ 커피도 맛있고 분위기도 넘 좋습니당', 41, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '처음 와 본 곳인데 인테리어가 정말 멋져요! 야외 공간이 마음에 들어서 밖에서 먹었어요. 까눌레도 맛있고 직원 분들도 친절하십니다 ㅎㅎ', 130, 22, 'GOOD', SYSTIMESTAMP);
