INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '디저트도 다양하고 커피 제외 다른 메뉴도 많아서 좋은거 같아요~~ 카페도 넓어서 다인원이 오기도 좋아요! 날 좋을때는 야외좌석 이용해도 좋을거 같습니다 (*´∇｀)ﾉ', 3, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '카페 공간도 넓고 테라스도 예쁘고 가족들과 함께오기 좋은 곳입니다! 음료 디저트 모두 보기에도 예쁘고 맛있어요:) 홍대에 오신다면 들러보시길 추천합니다~', 26, 8, 'GOOD', SYSTIMESTAMP);
