INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '레몬마들렌 너무 맛있어서 쌓아놓고먹고싶어요 분위기도 좋고 책상도 넓고 커피도 맛있어서 홍대 올때마다 여기 꼭 가요 그리고 초코까눌레 짱 바삭합니다 꼭 드십시오..', 46, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '오늘이 두번째 방문인데 너무 좋아요~ 첫번째 방문했을때 먹은 차와 빵이 계속 생각나서 왠만하면 갔던곳보다 새로운곳 찾아 다니는데 또 오게되네요^^ 직원분들도 친절하시고 오늘 음악 선곡도 넘 좋아요~', 38, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '날이 너무 좋아서 루프탑으로 올라왔어요 카페도 넓고 날이 엄청 좋아서 지금 오는 분들은 루프탑도 추천드려요!!! 디저트랑 커피도 맛있고 테이블 간격도 넓어서 홍대 오시면 꼭 들려보세요☺️', 71, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'TERRACE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '공명 카페 리뷰 아늑한 분위기와 감각적인 인테리어가 돋보이는 곳입니다. 커피 맛도 훌륭하고, 디저트도 정성이 느껴집니다. 인기가 많은 곳이라 그런지 자리가 금방 차지만, 기다릴 가치가 충분합니다. 겨울철에는 조금 더 따뜻한 공간이 있었으면 좋겠지만, 전체적으로 만족스러운 카페입니다. 다음에는 좀 더 여유롭게 방문하고 싶습니다.', 28, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '#내돈내산💰 #인생카페☕️ 연남점 홍대점 모두 좋아요♥️ 좋아하는 작가님 카페라서 더더욱 좋은데 까눌레 미쳐씀..연남은 종류별로 있어서 찐으로 다먹어봤는데 여기는 바닐라뿐이라 아쉽🥹 그래도 맛있었어요!!! 애정하는 공명카페 다음에 또 갈게요💓💓', 19, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '배달만 주문해서 먹다가 매장와서 구입했아요 ! 매장 엄청 넓고 커요 예쁘고 깔끔해요 비스킷슈랑 맘모스콘이 젤 맛있어요 ~~~!', 2, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '커피도 맛있고 디저트도 맛있고 분위기도 맛있는 느좋 카페에요 !!! 비온 뒤의 쌀쌀함을 카페 안에서 맞이하니 분위기가 배는 좋아지는거 같아요 !!', 28, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '베이커리 커피 맛있고 무엇보다 공간이 넓고 분위기가 좋아서 카공하기 좋아요!  테이블마다 콘센트 구비되어있는거나 냅킨에 와이파이 비번 적혀있는것 등 하나하나 다 너무 편해요~', 7, 10, 'GOOD', SYSTIMESTAMP);
