INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '카페공명 처음 방문해보는데, 커피도 책 이름으로 선택할 수 있어 신선했어요. 자리도 2층까지 있어서 넓었고, 야외 자리도 날 좋을 땐 방문하기 좋아 보입니다. 추천합니다.', 44, 8, 'GOOD', SYSTIMESTAMP);
