INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '홍대에서 유명한 카페 공명에 방문했는데 분위기 너무 좋고 매장도 넓어서 좋아요! 무엇보다 디저트 종류와 음료 종류도 다양해서 오길 잘한것같아요!', 6, 4, 'GOOD', SYSTIMESTAMP);
