INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '사실 책 읽고 사장님이 운영하는 카페가 궁금해서 방문하게 되었어요. 혼자오다보니까 혹시나 자리 차지하기가 부담스러워서 걱정했는데 평일이라 다행스럽게 혼자 앉아도 편안하네요! 딸기바닐라랑 딸기초코 고민하다가 딸기초코라떼 선택했는데 투x 스초생 케이크 그대로 음료로 옮겨놓은 것처럼 딸기랑 초코 조합이 절묘하게 잘 어울립니다. 혼자만의 시간 잘 즐기다가 갈 예정입니다! 그리고 깜짝 이벤트도 감사합니다😍', 9, 2, 'GOOD', SYSTIMESTAMP);
