INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '매번 연남점만 가다가 여자친구가 홍대점이 예쁘다며 데려왔습니다. 무척이나 넓고 좋네요 ㅎㅎ 특히 저녁에도 늦게까지 영업해서 평일 저녁에도 퇴근 이후 식사하고 오기 좋은 것 같아요!', 5, 4, 'GOOD', SYSTIMESTAMP);
