INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '인스타에서 보고 분위기가 좋아보여 방문했습니다 인테리어가 참 예쁘고 따뜻한 것 같아요 디저트류 종류도 많고 고르는게 힘들었어요 ㅎㅎ', 7, 3, 'GOOD', SYSTIMESTAMP);
