INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '주말 저녁 홍대와 상수를 잇는 거리의 핫플이어서 그런지 사람은 정말 많더라구요ㅎㅎ 야외도 있고 실내도 있고 실내는 3층까지 있었는데 2층 이용해봤어요. 실내 전체적으로 아늑하고 라이트가 은은하게 비춰지는 분위기랄까 뭔기 더 연말 분위기 나는 실내 분위기에 야외는 크리스마스 데코로 꾸며져 있었어요 ㅎㅎ 아메리카노 적당한 바디감과 약한 산미였는데 원두를 3가지 고를 수 있더라구요. 연남, 홍대, 합정 이게 좀 유니크했어요. 해당 매장마다 각각의 유니크함이 묻어있는 원두를 사용하고 또 그 원두를 매장마다 고를 수 있었구요. 공명 라테는 아이스만 가능하고 꾸덕한 크림 가득 그리고 시나몬이 잘 어울리는 라테라 맛있었어요 :) 주말보단 평일에 이용하면 좀 더 조용하게 즐길 수 있지 않을까 생각해봐요!', 61, 11, 'GOOD', SYSTIMESTAMP);
