INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '날씨 좋은날 카페 공명 테라스석에 앉아서 커피랑 디저트 먹으니 완전 힐링이네요🥰🥰 직원분들도 친절하고 디카페인도 있고 카페도 넘 예쁩니당', 10, 7, 'GOOD', SYSTIMESTAMP);
