INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '밀크티 맛나요 아인슈페인 존맛 까눌레는 좀 딱딱스 ㅎㅎ 자리가 분위기 있고 좋아용 ㅎㅎㅎㅎ 햇빛도 잘들고 굿굿 편안해요 넓고 조음', 19, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '유럽 감성 분위기가 멋스럽고, 무엇보다 파티셰가 매일 직접 만드는 베이커리 디저트가 너무 맛있고, 공명에서 직접 로스팅하고 블렌딩한 매력적인 커피를 즐길수 있는 이곳! 좋은 사람들과 다가오는 연말 모임 장소로 홍대카페 카페 공명 홍대점 최고네요.', 66, 16, 'GOOD', SYSTIMESTAMP);
