INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '사진보고 디저트가 맛있어보여서 찾아왔어요. 조금 일찍 와서 수월하게 들어갔는데 금방 사람들이 찼어요! 자리 먼저 잡고 주문하셔야 할 것 같아요 공간이 2층 테라스까지 있긴한데 2층은 계단 조금 조심하셔야 해요!!!', 7, 9, 'GOOD', SYSTIMESTAMP);
