INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '몇년 째 준비하던 시험에 연이어 실패하고 힘들어 하는 중에 친구가 선물해 준 ''결국 무엇이든 해내는 사람'' 책. 나는 강인한 사람이라 토닥여주는 에세이는 나한테 필요 없을 것이라고 생각해서 1년을 보지 않다가, 마음이 너무 힘들어서 꺼내보게 됐다. 책에 마음에 드는 글귀가 많아서 작가가 운영하는 카페에 와보고 싶어서 오게됐다. 사람이 많다고 해서 주말 11시에 오픈런했는데 조용하게 책 읽고 즐기기 너무 좋았다. 커피랑 디저트가 맛있는건 책을 읽어봤다면 보장된 것이었달까. 조용히 내일을 준비하러 자주, 오고싶은 카페다❤', 45, 1, 'GOOD', SYSTIMESTAMP);
