INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '홍대에서 카페 고민하기 싫을 때 항상 오는 곳입니다! 올 때마다 실패는 안하는 것 같아요 분위기 좋고 편하게 쉬어가기 좋습니당', 17, 2, 'GOOD', SYSTIMESTAMP);
