INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '직원분이 친절하고 카페 분위기가 좋아요ㅎㅎ 음료도 맛있고 케이크 맛이 아주 좋아요 다음에 홍대 놀러오면 또 들릴 예정입니다ㅎㅎ', 122, 20, 'GOOD', SYSTIMESTAMP);
