INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '오전 일찍 왔더니 대기없이 들어갈수 있었어요~ 자리간격도 널찍하고 루프탑도 있어서 대화하기 좋아요😍 디저트는 크림 듬뿍듬뿍 들어있어서 취저❣️❣️구움과자도 다양하게 있어서 빵순이들한테 추천이에요👍', 44, 9, 'GOOD', SYSTIMESTAMP);
