INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '너무너무 맛있어요!! 진짜 매일 가고 싶을 정도로 감동적인 맛인 거 같아요 ㅎㅎ❤️ 합정에 이렇게 최고 맛집 카페가 있는지 몰랐는데, 정말 매일 매일 오고 싶을 정도로 감동이네요 😗🥳 다음에 또 올게요 ~ 😻', 86, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '홍대에 잠시 들를일이 생겨 머물곳을 찾다가 우연히 찾게된 곳이에요. 이름이 마음에 들어 저도 모르게 이미 들어와있었어요 밖에서부터 분위기가 느껴졌고 안에도 마찬가지로 따듯하고 편안한 분위기였어요 다음에도 또 찾을거같아요', 91, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '처음엔 혼자오고 좋아서 친구들 데려오다보니 세번째 방문입니당!! 분위기도 좋고 디저트도 맛잇구 작업하기도 좋고 대화하기도 좋아영💕', 47, 3, 'GOOD', SYSTIMESTAMP);
