INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '평일 낮에 와서 대기 없이 이용했어요 !!! 인기가 많은데 그만큼 매장도 넓고 쾌적해요 음료도 너무 예쁘고 맛까지 있어서 다음에 홍대 오면 꼭 다시 오고 싶어요 ... 😍🩷', 107, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '홍대오면 꼭 오고 싶던 카페 공명!! 인테리어도 너무 이쁘고 디저트도 너무 맛있어요 ㅠㅠㅜ 크림 스콘 꼭 먹기...😍 커피 원두도 고를수 있어서 좋아요오!!👍', 22, 0, 'GOOD', SYSTIMESTAMP);
