INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '주택을 카페로 바꿨다고 들었는데 분위기가 미쳣습니다… 벽돌로 낼 수 있는 분위기는 다 냈고 커피도 원두를 고를 수 있어서 좋았어요😄 디저트 가지수도 많고 무려 커피가 고소하고 맛있어요', 44, 10, 'GOOD', SYSTIMESTAMP);
