INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '1월부터 일 시작이라 여유를 즐길 날이 많지 않아 정말 좋은 카페를 가보고 싶다 하고 찾아온 곳인데 공간이 기분 좋게 해주는 힘이 있네요 너무 좋습니다 산미 안 좋아하는 저에게 basic 원두 딱 좋고 조명도 햇살도 다 좋습니다 12월에도 평일에 자주 와야겠다고 맘먹었어요!!', 31, 6, 'GOOD', SYSTIMESTAMP);
