INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '먹어보고 싶은 메뉴가 정말 많아서 고르기가 힘들었는데 직원분들께서 하나하나 친절하게 설명해주셔서 완전 만족하는 선택할 수 있었습니다😌 딸기 초코 라떼는 비주얼도 예쁜데 초코맛과 딸기의 상큼함이 느껴져서 맛있었고, 바스크 몽블랑 케이크는 꾸덕하고 달달하니 몽블랑의 매력에 빠져버렸습니당🙃🥰 또 와서 다른 메뉴도 먹어보고 싶어요!', 35, 9, 'GOOD', SYSTIMESTAMP);
