INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '벌써 몇 번째 방문인지 모르겠네요 ㅎㅎ 공명 먹으러 항상 강원도에서 올라오는데 올 때 마다 후회없는 거 같아요ㅠㅠ 오랜만에 왔는데 분위기가 많이 바뀐 거 같아 더 좋네요 !! 제발 공명 모르는 사람 없게 해주세요🙇🏻‍♂️', 96, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '입구부터 겨울분위기 낭낭하구요, 내부에도 따뜻하고 부드러운 느낌으로 잘 꾸며져 있어요. 크리스마스 시즌엔 특히 좋을 것 같은! 커피맛도 좋습니다^^', 10, 9, 'GOOD', SYSTIMESTAMP);
