INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '2층 가는 계단이 조금 위험했던거 빼고 다 완벽해요. 자리도 많고, 인테리어도 정말 예뻐요. 야외 테이블도 너무 이쁘고 날씨 좋은 날 가서 피크닉 느낌도 나고 좋았어요!!', 10, 5, 'GOOD', SYSTIMESTAMP);
