INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '슈가 정말 맛있어서 추가로 포장해갑니다~! 분위기도 너무 좋고 공간이 넓어서 좋네여!! 이런 곳이 있을 줄 몰랐는데 정말 맛있네여!! 다음에 또 올게요!!', 78, 16, 'GOOD', SYSTIMESTAMP);
