INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '디저트 맛있는거 먹으면서 조용한 곳 찾고있었는데 마침 찾았네요! 여기 시그니처 디저트가 생크림 스콘, 쿠키슈라고 했지만 배불러서 구움과자류만 시켰어요. 사이즈는 아담하지만 맛은 알차네요! 오전에 오면 조용하게 머물다 갈 수 있어요! 다음에 또 방문하려 합니다😋', 60, 18, 'GOOD', SYSTIMESTAMP);
