INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '크리스마스 인테리어가 멋져요. 들어오는 입구도 너무 예쁘고 매장 들어서면 달콤 고소하게 퍼지는 베이커리향이 너무 좋네요. 커피도 맛있고 마들렌도 맛있었습니다.', 37, 6, 'GOOD', SYSTIMESTAMP);
