INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '카페 공명은 많이 들어 알고 있던 카페인데, 작업하기 좋을 것 같아서 왔어요. 평일이라 그런가 사람이 많지 않았고 직원분들도 친절하셨습니다! 무엇보다 디저트들이 다 맛있어보여용..', 1, 6, 'GOOD', SYSTIMESTAMP);
