INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '인테리어가 앤틱하면서 좋아요 아늑하고 따뜻한 분위기라 연인 친구 가족 누구와 와도 좋을듯 해요 매장두 넓어요!! 홍대 어딜가나 시끄럽고 복잡한 느낌인데 여긴 사람 많긴 한데 막 어지럽지 않은 분위기라 강추! 커피맛도 좋으네요^^ 상큼한 라즈베리 스콘 같이 곁들어 드시길 추천!!', 83, 11, 'GOOD', SYSTIMESTAMP);
