INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '크림이 맛있는 카페 공명🧁 마들렌, 쿠키,스콘 먹어봤는데 마들렌과 쿠키는 SOSO 하고 스콘과 생크림 들어간 종류가 맛있어요. 공명라떼 도 사진에는 없지만 맛있어요. 생크림이 예전의 공명 연남점만 있을 때의 그 맛은 아니라서 조금 아쉽지만 날씨 좋은 날 테라스쪽에 앉아서 커피한잔 하기 좋은 곳.', 34, 0, 'GOOD', SYSTIMESTAMP);
