INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '옛날집을 개조한 독특한 인테리어 덕분에 분위기가 정말 색달랐습니다. 플랫화이트랑 공명라떼 주문했는데, 공명라떼는 크림 먼저 떠먹고 계피가루 섞어 마시는 게 포인트더라고요. 디저트로는 레몬마들렌이랑 비스킷슈 먹었는데, 둘 다 맛도 좋고 커피랑 잘 어울렸습니다. 조용히 대화 나누기 좋은 공간이라 데이트하기 딱 좋았어요', 10, 6, 'GOOD', SYSTIMESTAMP);
