INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '오랜만에 간 홍대 아는 언니와 야외에서 커피 마시고 싶어서 야외 자리에 앉았어요. 주택을 개조해서 내부에 각각의 룸들이 있어 프라이빗하게 즐길 수 있더라구요. 물론 옥상이나 1층 야외는 개방감있어 좋아요. 마들렌이 너무 맛있게 생겼더라구요. 전 다른 메뉴를 주문했지만요. 공명라떼도 맛있는데 양이 좀 적어요 ^^', 47, 3, 'GOOD', SYSTIMESTAMP);
