INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '말차라떼의 크림이 정말 맛있어요👍👍👍👍 무엇보다 디저트가 진짜 맛있었는데, 치즈 케이크가 베스트인 것 같아요 부드럽고 하나도 안 느끼함...초코나무 숲 스콘도 많이 안 달고 맛있어용 사람이 많은 이유가 있어요👍', 22, 4, 'GOOD', SYSTIMESTAMP);
