INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '공명이라는 이름에 걸맞는 입구의 카페에요. 2층부터 외부, 테라스까지 앉을 자리가 굉장히 많아요. 분위기가 차분해서 이야기 나누기도 좋습니다. 비스킷슈와 플랫화이트, 아아 주문했는데요. 비스킷슈는 크림보다 겉이 넘 달았어요. 당을 끌어올리기엔 충분한 단 맛입니다. 커피 양은 작지만 맛은 좋았습니다.', 32, 5, 'GOOD', SYSTIMESTAMP);
