INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '혼자와서 카공하거나 수다떨기 좋을 것 같은 카페,, 마들렌,쿠키도 왕달달하니 맛있다. 아인슈페너는 내스타일이 왕아니었다. 라떼아니고 아아에다가 크림올린거였다.. 심히 아쉬운 맛. 오늘 비와서 더 좋있다. 창밖으로 비가 추적추적 내리는군. 원래는 한강가려고 했지만 언니들과 좋았던 시간. 열심히 공부하자!!!!', 51, 12, 'GOOD', SYSTIMESTAMP);
