INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '번잡한 홍대 거리에 숨겨진 고요한 힐링 공간🌿☕ 자연스러운 우드톤 인테리어와 은은한 조명에 아늑한 느낌♥️ 커피의 깊고 깔끔한 맛은 물론, 디저트와의 조화가 정말 환상적! 무엇보다 넓고 여유로운 좌석 배치 덕분에 조용히 책을 읽거나 작업을 하기에도 딱 좋은 환경이에요 홍대입구역에서 도보 10분 거리로 접근성도 좋아 데이트 장소는 물론 혼자만의 시간을 보내기에도 제격>< 홍대 특유의 활기와는 또 다른 차분함을 느끼고 싶다면 카페 공명에서 커피 한 잔의 여유를 즐겨보세요! ☕💚', 99, 25, 'GOOD', SYSTIMESTAMP);
