INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '친구가 마들렌이 미친맛이라그래서 와봤는데 매장도 넓고 분위기도 좋고 메뉴도 맛나고 넘 좋네용 사람 엄청 많아서 자리잡기 필수입니다!! 사진 맛집 디저트 맛집 또올게용', 40, 9, 'GOOD', SYSTIMESTAMP);
