INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '항상 와보고 싶던 카페였는데! 처음 방문해봤어요 ㅎㅎ 분위기도 너무 좋고 카운터 직원 분도 너무 친절하세요!! 앞으로 마니 오려구욤☺️🍀‼️💕🤍', 34, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '음식이 나오는 속도가 빨라서 금방 먹을 수 있어 좋았습니다~좌석이 넓고 분위기도 따뜻해서 기분도 너무 좋았어용 👍곧 크리스마스라 인테리어 신경쓰신 것 같은데 건물 빨간 벽돌이랑 크리스마스 인테리어가 너무 잘 어울려서 연말 분위기를 물씬 냈습니다~~!!', 18, 0, 'GOOD', SYSTIMESTAMP);
