INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '분위기 좋은 까페 찾아서 왔는데 크리스마스 분위기도 물씬 나고 인테리어도 너무 멋져요! 다음에 재방문 해서 다른 디저트도 더 먹어 보고 싶습니다!!', 54, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '우와 정말 멋진 공간이에요!! 인테리어가 정말 멋짐니다. 건물 전체가 다 카페에요. 1층은 테라스, 주문하는 곳이 있고, 2층은 커피 마시는 공간, 3층은 야외 테라스에요. 날이 좀 시원해 지면 3층 테라스에 앉아 시원한 바람쐐며 커피마시면 좋을것 같아요. 비스킷, 슈, 유자 코코넛 마들렌, 아메리카노 주문했어요 커피는 단맛과 산미가 적절히 있어 맛있었고, 디저트랑도 잘 어울렸어요. 슈는 겉은 바삭하고 속은 바닐라 빈이 콕 박힌 부드러운 슈크림이 가득차있어요. 다음에는 생크림 가득든 스콘이랑, 크림 가득 올라간 시그니쳐 공명커피를 먹어보고싶어요. 창가에 앉아 디저트와 커피 마시며, 책 읽었어요. 음악도 좋고 볕도 따스하고, 내부는 시원해서, 편히 잘쉬고 재충전 하고왔어요.', 80, 14, 'GOOD', SYSTIMESTAMP);
