INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '공명 홍대점은 처음인데 야외 공간이 너무 멋지네요! 아늑한 분위기에 직원분들도 친절하셔서 마음이 편하더라구요. 디저트 종류도 정말 많고 음료메뉴를 책 커버로 표시하신게 재밌었습니다ㅎㅎ 또 방문하고 싶어요🩷', 17, 0, 'GOOD', SYSTIMESTAMP);
