INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '크림라떼 크림이 진짜 찐 👍👍 살면서 먹어본 크림라떼 중에서 공명라떼가 가장 맛있어요 〰️〰️ 우유생크림도 부드러워서 스콘이랑 너무 잘 어울리고 마들렌도 너무 잘하는거 같아요!! 맛잇게 잘 먹구 갑니당🙇‍♀️', 10, 1, 'GOOD', SYSTIMESTAMP);
