INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 공명 홍대점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '까페 외관이 빨간벽돌로 되어있어서 이색적이고 예뻤어요! 실내도 빨간벽돌의 느낌도 있고 빈티지한 느낌도 있어서 인테리어가 예뻤습니다! 바닐라까눌레, 레몬마들렌, 까페라떼 연남 을 시켰는데 까눌레,마들렌도 너무 잘구워져서 맛있고, 까페라떼도 맛있었어요!! 디저트맛집&커피맛집으로 추천해요! 또 방문하고 싶어요~^^', 4, 7, 'GOOD', SYSTIMESTAMP);
