INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '몇달전에 처음 먹어보고 맛있어서 오랜만에 재방문!! 직원분들도 친절하시고 매장도 꽤 넓고 케이크 종류도 많은데 넘 맛있써욤ㅎㅎ 화장실도 있고 깔끔한편이라 좋은것 같아여 연남 놀러갈때마다 자주 가고싶은곳!', 43, 6, 'GOOD', SYSTIMESTAMP);
