INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '연남동카페 중에서 케이크 맛집으로 유명해서 다녀왔어요. 빨간문 입구 찾는 재미도 있고 내부 분위기도 깔끔해서 좋았어요! 시그니처 라떼랑 말차라떼, 그리고 딸기복숭아케이크랑 얼그레이무화과 케이크 먹었는데 확실히 1인 1케이크 해야 하는 이유가 있더라구요 😆 홀케이크도 당일 구매 가능하다 해서 다음엔 생일케이크도 여기서 할까 싶어요!', 59, 18, 'GOOD', SYSTIMESTAMP);
