INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '❤️빨간문이 반겨주는 연남동에 위치한 펫어케이크!🍰🎂다양한 종류들의 조각케익들과 함께 조각들을 모아서 작은 케이크로도 가능하다는! 😲완전 positive 매장분위기도 너무 좋고 맛있는 디저트까지! 현장에서 구매도 가능한 홀케이크도 있고! 맛있는 메론케이크와 복숭아요커트 케익까지! 아아와 너무 잘 어울려용🥺✨ 홍대 연남동근방에 케익디저트맛집 찾는다면 펫어케이크 연남점 추천합니다!', 26, 5, 'GOOD', SYSTIMESTAMP);
