INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '방이동 쪽 팻어케이크는 많이 방문했었는데 연남점은 처음이에요! 케이크 종류도 많고 시즌 메뉴인 복숭아 케이크가 있어서 주문했어요:) 남자친구는 디저트를 별로 좋아하지 않는데도 100% 동물성 생크림을 사용하는 팻어케이크 수제케이크를 먹더니 초코가나슈 케이크가 많이 안 달아서 좋다고 한 조각을 다 먹더라구요!! 매장도 넓어서 채광 잘 즐기다갑니다~~', 120, 25, 'GOOD', SYSTIMESTAMP);
