INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '연남동에서 케이크 크고 맛있는곳을 찾았습니다! 원두도 너무 제스타일이더라고요! 🙂 분위기 좋고 매장도 커서 대화 많이 하고 즐기는 공간으로 너무 추천드립니다!👍 연남동 돌아다니시는분들 케이크드세요🍰☕️', 1, 8, 'GOOD', SYSTIMESTAMP);
