INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '연남점에도 팻어케이크가 있다니 💛 냉큼 달려왔는데 매장도 넓고 케이쿠도 진짜 넘 맛있는거 아닙니까 ㅠㅠ 무화과 좋아하면 무조건 드셔보시길✨ 시그니처 라떼도 연유랑 생크림 들어가있어서 달달하고 ❤️ 주말 12시에 왔는데도 사람이 없고 매장도 쾌적해서 넘 좋아요 정말 ,, 담에 또 오겠습니다😎', 71, 18, 'GOOD', SYSTIMESTAMP);
