INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '잠실쪽에서 유명한 카페라고 들었는데 연남에도 생긴지는 몰랐네요!! 연남 한복판에 위치해있어서 찾기도 쉬웠어요! 2층에 있지만 빨간 문으로 찾으면 될듯해용 생과일케이크가 종류별로 많아서 골라먹는 재미가 있구요! 얼그레이 무화가 엄~청 찐해서 얼그레이 덕후들은 분명 좋아하실것 같아요~ 복숭아도 물복+딱복 조합이라 물리지 않아용 인테리어도 유럽 시골 집에 들어온 느낌이라 제 취향저격! 외국인들도 많으시더라구요~~ 연남에서 카페 찾으시면 추천!', 14, 8, 'GOOD', SYSTIMESTAMP);
