INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '연남동 과일케이크 맛집 팻어케이크 🍰 생각보다 카페 내부도 넓어서 친구랑 수다떨기에 좋은 곳이였어요~! 과일케이크 종류 짱많아서 좋아요 ㅎㅎㅎ 생일케이크 초도 예쁜것들 팔고있어서 다음엔 친구생일때 테이크아웃 해가려구요!!', 87, 15, 'GOOD', SYSTIMESTAMP);
