INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '케이크 먹고 싶어서 근처 카페를 급하게 찾았는데 생각보다 너무 시원하고 케이크도 너무 맛있어요 저희는 복숭아요거트 조각케익 시켰는데 진짜 맛있어요 느끼한거 없고 복숭아도 실하구 적당히 달면서 맛있어요🥰 연남오면 또 올거 같아요! 특별한 날엔 홀케이크 구매하고싶어요 케이크 안에 있는 복숭아도 적당한 당도와 식감이 미쳤어요😍😍😍', 41, 9, 'GOOD', SYSTIMESTAMP);
