INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '케이크 종류가 너무 많아서 행복한 고민 😍 케이크 맛집을 이제야 알앗다니요... 조각케이크 퀄리티가 미쳐서 이제 생일케이크 자그맣게 할때는 요기에서 사야겟어요 ㅠㅠ 초코가나슈는 당땡길때 진짜 드셔봐....후회없음', 39, 6, 'GOOD', SYSTIMESTAMP);
