INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '공간 인테리어도 너무 예쁘고 과일생크림케이크 천국 🍓🍑🍰 생크림이랑 시트가 진짜 부드러워서 한조각 순삭시켰어요ㅠㅠ 사진도 진짜 잘 나와서 그런지 외국인들도 많이 있네요 ㅎㅎㅎ 여자들이면 진짜 좋아할 홍대카페 원탑🫶', 1, 10, 'GOOD', SYSTIMESTAMP);
