INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '펫어케이크 유명해서 쉬는날 꼭 오고싶었는데 오늘 드디어 다녀왔습니당 ㅎㅎ 분위기가 알프스분위기(?) 처럼 차분하고 인테리어도 너무 이뻤어요 😝 사진이 잘 나와서 기분이 좋았뜸 >_< 생과일케이크도 역시나 맛있구용 ~ 🎂 커피가 생각보다 양이 많았고 사장님도 친절하고 과일케이크도 너무 맛있어서 다음에 또 올 생각입니당 사장님 번창하세용 🔥🔥', 48, 9, 'GOOD', SYSTIMESTAMP);
