INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '잠실점도 방문하고 연남점도 두 번째 방문인데 근처 오면 케이크가 맛있어서 또 찾게 되는 카페인 것 같아요🥰 인테리어도 예쁘고 좌석도 은근 많아서 좋아요!! 케이크랑 음료 다 너무 맛있습니다 ჱ̒ .ｰ̀֊ｰ́ )', 15, 3, 'GOOD', SYSTIMESTAMP);
