INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '주말에 왔다가 웨이팅이 있어 평일에 다시 방문했어요~ 가끔 당도가 덜한 복숭아 케이크를 먹고 실망했었는데, 팻어케이크 연남점 복숭아케이크는 달고 너무맛있어요~ 분위기도 좋고 사장님도 친절하세요 ㅎㅎ 아메리카노는 산미없는 깔끔한 맛이에요~', 10, 8, 'GOOD', SYSTIMESTAMP);
