INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '무화과 케이크 미쳤습니다. 진짜 한입 먹자마자 “와…” 소리 나옴. 무화과가 달콤 터지고 크림은 가볍게 훅 감싸주는데, 시트까지 촉촉해서 끝까지 행복함. 이건 그냥 계절 통째로 케이크에 박아 넣은 맛임. 비주얼도 예술이라 사진 찍고 먹으면 두 번 행복. 솔직히 이런 건 매일 먹어야 함.', 60, 11, 'GOOD', SYSTIMESTAMP);
