INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '너무 맛있어요 친구들이랑 잠실, 홍대에서 만날 일이 있으면 꼭 데려오는 가게에요 과일+요거트 케이크 있으면 꼭 시켜드세요... 초코도 맛있음 리치한 초코 좋아하시면 추천드려요 ㅠㅠ..  집 앞이면 맨날 왔을거예요', 64, 12, 'GOOD', SYSTIMESTAMP);
