INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '고풍스러운 앤티크한 분위기에요! 너무 예쁘다... 🙊🩷... 케이크도 하나같이 너무 맛있어보여서 주문을 부르는 비쥬얼이에요!!!', 0, 6, 'GOOD', SYSTIMESTAMP);
