INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '아늑한 분위기의 예쁜 카페에요. 내부가 되게 빛 잘 드는 인테리어라서 오래 머물러도 좋았어요! 대화를 나누기에 좋은 공간이었고 케이크랑 커피도 맛이 좋아서 추천합니당.', 47, 2, 'GOOD', SYSTIMESTAMP);
