INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '오늘 카페에서 복숭아 생크림 케이크랑 아이스 아메리카노 세트로 먹었는데, 진짜 여름에 딱 어울리는 조합이었어요. 크림은 가볍고 부드러워서 전혀 느끼하지 않고, 스펀지 시트도 촉촉해서 술술 넘어갔어요.케이크 속에도 복숭아 과육이 듬뿍 들어 있어서 씹는 재미가 있었고, 전체적으로 과일의 산뜻한 단맛이 잘 살아있었어요.보기에도 예쁘고 맛도 산뜻해서 사진 찍고 싶고 또 먹고 싶은 메뉴였어요. 여름 디저트로 완전 강추합니다', 4, 2, 'GOOD', SYSTIMESTAMP);
