INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '케이크 먹고싶어서 찾아왔어요! 기대한만큼 맛있네용 다른 곳들은 케이크 구매해도 1인1음료 강요하는 곳이 많은데 여기는 케이크 포함 1인 1메뉴라서 너뮤 조아써요,,🥺 다음에 또 올게요!', 39, 5, 'GOOD', SYSTIMESTAMP);
