INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '와보고 싶었던 카페였는데 우연히 홍대에 올 기회가 생겨서 와봤어용 ! 12시에 방문했는데 사람도 없구 조용하니 지인이랑 편안히 쉴 수 있었습니당😍 케이크도 너무 예뻐요 !!💗', 28, 5, 'GOOD', SYSTIMESTAMP);
