INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '작년에 친구 통해서 알게 되었는데 케이크 진짜 레알 맛도리여서 올해도 몇 번이나 왔는지 모르겠어요 ㅎㅎ 처음으로 남자친구랑 왔는데 인테리어도 예쁘고 디저트랑 음료도 맛있어서 즐겁게 데이트 하다 갑니당 🩷🫶🏻', 125, 26, 'GOOD', SYSTIMESTAMP);
