INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '새로 생겼을때부터 자주 오는 카페인데 홍대에서 먹어본 케이크 중에 제일 맛있어요.. 매번 만나는 지인들도 항상 데려오는데 다들 하나같이 맛있다구 해요 추천합니다🥹🥹😍😍', 67, 18, 'GOOD', SYSTIMESTAMP);
