INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '토요일 오후에 방문했는데, 웨이팅 4번째 순서였어요! 생크림이랑 초코 크림이 느끼하지 않아서 맛있게 잘 먹었어요 ㅎㅎ 케이크 종류가 많아서 더 먹어 보고 싶었는데, 배가 너무 불러서 못 먹은 게 아쉽네용 ㅠㅠ', 44, 3, 'GOOD', SYSTIMESTAMP);
