INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '케이크가 부드럽고 맛있어요…!! 무화과 철을 맞아 무화과 케키 먹으러 다니는데 과일도 많고 크림도 꼬숩고 맛있네요… 연남동에서 맛있는 커피와 케키를 드시고 싶다면 추천…', 66, 12, 'GOOD', SYSTIMESTAMP);
