INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '이 더운 날씨에 팻어케이크 먹으려구 15분 걸었어요! 계절과일인 복숭아 케이크랑 케이크의 근본 초코케이크 먹었는데 진짜 맛있었어요🥹 케이크 드시규 싶으시면 한번 꼭 와보세용', 33, 0, 'GOOD', SYSTIMESTAMP);
