INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '구매 당시 연남동에서 제일 먼저 복숭아 케이크을 오픈한 카페였어요. 선택권 없이 고른 카페인데 유명한 곳은 이유가 있더라구요👍🏻 크림도 부드럽고 시트도 촉촉하고 무엇보다 복숭아가 너무 맛있었어요! 복숭아와 케이크가 잘 어울려서 맛있게 먹었네용><', 48, 2, 'GOOD', SYSTIMESTAMP);
