INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '과일이 진짜 층층이 가득 담겨서 일단 비주얼이 미쳤고. 비주얼만큼 맛도 브라보👍 내부도 넓고 예뻐서, 연남에서 잠시 쉬어갈 곳으로 베스트입니다!', 41, 2, 'GOOD', SYSTIMESTAMP);
