INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '카페 찾다가 들렸는데 청포도 케익 먹어보고 또 생각 나서 생일 케익까지 예약했다 청포도 케익은 크림이 요거트로 되어 있는데 기분 좋은 상큼 달달이라 기대 이상이었다 생일 케익은 망고로! 맛을 떠나서 안에 과일이 진짜 듬뿍 들었다... 이렇게 많이 있어도 되나? 싶을 정도! 가격은 살짝 비싸긴 하지만 기념일에는 좋은 선택 같다', 98, 20, 'GOOD', SYSTIMESTAMP);
