INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '엄마가 생일초 불자마자 사진 찍는데, 다 찍기도 전에 들어오는 숟가락..... 과일에 미친 우리 가족들 너무 만족💘 매장으로 복숭아 케이크 먹으러 또 갈께요 :)', 38, 2, 'GOOD', SYSTIMESTAMP);
