INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '남자친구 생일이어서 미리 예약했습니다.🎂 가나슈초코딸기를 하려고 했는데 이틀전에는 예약해야하나봐요~ 기본 생크림딸기도 동물성생크림이라 느끼하지도않고 우유맛이 진해서 넘 맛있었어요🍓 처음에는 사이즈가 좀 작다고 느꼈는데 안에 딸기도 많이 들어있네요~ 둘이서 미니사이즈가 딱 알맞네요👍👍 다음엔 초코케익 도전하려구요👍🍫', 83, 13, 'GOOD', SYSTIMESTAMP);
