INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '케이크에 과일이 듬뿍 들어있고 크기가 짱 커요!! 카페 분위기도 좋고 비 오는 날씬데 기분 좋게 먹을 수 있을 것 같아요 짱 좋음 최고 분좋카 찾으시면 강추❤️❤️', 5, 0, 'GOOD', SYSTIMESTAMP);
