INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '벌써 세번째 방문이에용!! 딸기케이크를 정말 좋아하는데 여기는 딸케를 여름에도 팔아서 좋은 것 같아요 오늘은 좀 늦게 방문해서 딸케가 없길래 블루베리케익으로 시켰는데 이것도 맛있네요 좋아요', 47, 5, 'GOOD', SYSTIMESTAMP);
