INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '여기 케이크 너무 맛있어서 몇번이고 재구매해요..! 솔직히 딸기케이크 감동 그자체ㅜ 여러 유명 홍대 케이크 집 가봤지만 여기가 최고에요ㅠ', 60, 18, 'GOOD', SYSTIMESTAMP);
