INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '케이크 종류도 많고 과일도 잔뜩 넣어주는 인스타 광고 보고 너무 먹어보고 싶어서 홀케이크 예약해서 구매했어요! 광고처럼 과일이 엄청 잔뜩은 아니었지만 그래도 맛있었습니다 ㅎㅎ 특히 기대 안했던 라즈베리케이크가 엄청 맛있었어요 모둠 케이크 하시면 라즈베리 케이크 한 번 추가해 보셔요 맛 장담합니다!!', 42, 7, 'GOOD', SYSTIMESTAMP);
