INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '복숭아케이크 안에 복숭아가 단맛이 없고 물컹한게 식감이 전혀 없었어요 작년에는 송파쪽에서 샀었는데 비교가 좀 되네요 아쉬웠습니다', 43, 9, 'BAD', SYSTIMESTAMP);
