INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '집에 딸기좋아 인간과 망고좋아 인간이 있어서 SNS에서 망고딸기 케이크를 보고 바로 이거다!싶어 어버이날 기념으로 예약했습니다. 케이크에 들어있는 과일의 양은 만족스럽지만 과일의 당도는 복불복이 있다는게 아쉬웠어요. 특히 딸기철이 아니라 그런지 딸기가 썩 달지않음 하지만 망고딸기 케이크는 처음보기도하고 두가지 색이 있는만큼 사진은 예쁘게 나와서 좋아요. 한번 먹어본걸로 만족하지만 다른 조합의 과일케이크가 나온다면 먹어볼거같긴함👍 마지막으로 초를 챙겨주셨는데 집에 오니 없어져있더라고요. 케이크 상자 안에 끼워주시거나 테이프를 여러 개 붙여주면 좋을것 같습니다!', 33, 5, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '남자친구 생일케이크로 사러왔는데 너무 예쁘고 맛있었어요! 비주얼만 예쁜게아니라 맛이 진짜 .. 태어나서 먹은 케이크중 젤 맛있었어요🤍 1도 안느끼하고 달달 고소한 우유크림에 부드러움 ㅠㅠ 과일도 듬뿍 들어가고 가격대비 퀄리티 너무 좋아서 다음 기념일에도 여기서 케이크 구매하기로 했어요!! 직원분도 친절하셔서 너무 좋았습니다💕', 2, 4, 'GOOD', SYSTIMESTAMP);
