INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '지난달 한국에 들어갔다가 잠실점에서 먹어보고 너무 맛있어서 이번 엄마 생신때 픽업부탁해 생일케이크 해드렸는데 엄마께서 상큼달달하니 너무맛있다고 싹 드신거보고 타국에서 잠시나마 행복했네요 적당히 달달하고 상큼해서 끝까지 물리지 않고 먹기에 좋은 맛입니다 감사드려요', 32, 10, 'GOOD', SYSTIMESTAMP);
