INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '케이크가 맛있고 분위기가 좋아요! 전부 맛있어보여서 고민하고 있었는데 직원분들이 친절하게 설명해줘서 좋았어요🫶 매장이 밝은 분위기라서 비오는 날도 여유를 즐기고 갔습니다 다음에 또 방문할게요🧡', 14, 9, 'GOOD', SYSTIMESTAMP);
