INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '케이크 맛도리인건 이미 유명하니까 말모말모구용 디저트 맛집이라 커피는 기대안하고 시켰는데 생각보다 엄청 맛있어서 놀랐슴미다 개인적으로 저는 골드키위 케이크가 여기 원탑이라고 생각해요 다들 제발 먹어주세용 짱맛임미다!!!!', 11, 0, 'GOOD', SYSTIMESTAMP);
