INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '동물성크림이라 한개도 느끼함없이 완전 꿀떡꿀떡 넘어가는 케이크에 커피도 향긋하니 맛있는 연남동 디저트맛집 팻어케이크에요🤍 카페 인테리어도 예쁘고 친절하셔서 기분좋게 다녀왔습니당🥰', 15, 3, 'GOOD', SYSTIMESTAMP);
