INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '케이크 맛집이에요!!!! 특히 골드키위 케이크가 제 베스트에요 ㅠㅠ 부드러운 골드키위가 시트랑 생크림이랑 너무 잘어울려서 앉은 자리에서 홀케잌도 전부 먹겠더라구요.. 연남에 위치한 카페인데도 꽤 넓은 공간이라 더욱 좋았습니다!!!!👀', 105, 19, 'GOOD', SYSTIMESTAMP);
