INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '근처에 갈 일이 있어서 둘러보다가 케잌 맛집이라고 유명하길래 홀케잌 포장예약한번 해봤어요 네이버예약되서 너무 편하고 가자마자 바로 주셔서 대기도 안해도 되고 집에와서 부모님이랑 먹었는데 진짜 과일이 드으으으음뿍이라 시트는 많지않았어요 과일>>>>크림>>시트 정도? 동물성 생크림이라 더 느끼함도 없고 시트도 부드럽고 너무 맛있었어요 😍', 0, 2, 'GOOD', SYSTIMESTAMP);
