INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '너무맛있어요 과일 가득입니다 매장 전화 받으신 남자분도 너무 친절하셔서 맘이 편했구요 단거 싫어하는 어무니도2조각이나 드셨어요 크림이 너무 맛있고 과일은 신선하고 그냥 맛있어요 제발 사드세요ㅠ', 73, 17, 'GOOD', SYSTIMESTAMP);
