INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '딸기케이크도 먹고 싶고 망고케이크도 먹고 싶었는데 둘 다 먹을 수 있는 케이크가 이번에 출시돼서 구매해보았어요! 딸기랑 망고는 신선하고 당도 높았고 부드러운 진한 생크림과 너무 잘 어울렸어요!!! 빵시트도 촉촉해서 아이랑 같이 먹기 너무 좋았어요:)', 67, 14, 'GOOD', SYSTIMESTAMP);
