INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '기념일 케이크로 구매했어요!! 전화로 이것저것 여쭤봤는데 남자선생님께서 엄청 친절하게ㅜ알려주셔서 기분이 좋았습니다!! 미리 예약을 하진 못했지만 당일케이크가 있더라구요 미니-초코딸기케이크 주문했는데 초코가 다크초콜릿이라서 덜 달고 딸기도 많이 들어가서 정말 물리지 않고 맛있게 먹었습니다 ㅠㅠㅜ 2-3인정도 같이 먹어도 충분한 사이즈에요!!!⭐️⭐️⭐️⭐️⭐️🥰', 44, 8, 'GOOD', SYSTIMESTAMP);
