INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '남자친구 생일케이크로 사러왔는데 너무 예쁘고 맛있었어요~ 매장도 분위기 좋고 깔끔했고 직원분도 친절하셨어요 ㅎㅎ 케이크 예쁜건 말모말모 ㅠㅠ 비쥬얼만큼이나 맛도 너무 좋아서 다음 기념일도 팻어케이크에서 주문하려구요!💕', 42, 8, 'GOOD', SYSTIMESTAMP);
