INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '친구가 생일이라 친구주려고 망고미니 예약한김에 매장 이용도 하고 왔습니다. 친구 폰으로 찍어서 홀케이크 사진은 못 찍었는데 피스타치오딸기도 맛있었어요. 잠실에 있을 때 너무 멀어서 아쉬웠었는데 연남에 있어서 너무 좋네용', 12, 4, 'GOOD', SYSTIMESTAMP);
