INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '항상 애용하고 있어요 빵보다 과일이 더 푸짐해요 크림도 동물성생크림이라 느끼하지 않고 고소하고 부드러움 ㅠㅠㅠㅠ 덕분에 동생 생일파티 잘했어요 담번에 또 예약할게요~~~', 50, 8, 'GOOD', SYSTIMESTAMP);
