INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '잠실케이크 맛집 팻어케이크가 연남동에 생겼길래 다녀왔어요! 잠실점에서 몇번 사먹어봤는데 똑같이 맛있네요👍 시트는 촉촉하고 크림은 신선하고 딸기는 달달하고 진짜 케이크맛집이라고 할만해요🍰♥️ 크리스마스 분위기로 잘 꾸며놨으니 꼭 가보세요🫶🏻🫶🏻', 114, 26, 'GOOD', SYSTIMESTAMP);
