INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '케이크 커피 너무 맛있어서 2분만에 흡입 삽가능...... 우유말먹 하고싶음 ㅠㅠㅠㅠㅠㅠㅠㅠ 과일도 완전 듬뿍이라 따지고보면 비싼것도 아닌것같아욤!! 기념일이나 특별한 날에 꼭 구입하러 올게요~!', 40, 8, 'GOOD', SYSTIMESTAMP);
