INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '진짜 거짓말 하나도 안보태고 여태 먹은 딸기 케익중 젤입니다.. 여자친구도 너무 좋아했구요!! 딸기가 너무 많아서 감탄했어요.  왜케 푸딩같지란 생각이 들었던게 빵은 진짜 최소한이고 딸기를 넣기위해 생크림과 빵이 있는 느낌이랄까.. 케익 안쪽에도 딸기 한가득입니다. 돈 하나도 안아까웠고 내년에도 예약 도전합니다👊 그만 알려졌으면 좋겠..ㅋㅋ아무튼 너무 행복한 크리스마스를 선사해주셔서 감사합니다', 15, 9, 'GOOD', SYSTIMESTAMP);
