INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '이렇게 딸기가 아낌없이 듬뿍 들어있는 케이크는 처음이었어요 🍓 무엇보다 조카들이 넘 맛있게 먹어서 순삭했다는 ㅎㅎ 다음엔 다른 케이크도 맛봐야겠어요! :)', 21, 5, 'GOOD', SYSTIMESTAMP);
