INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '평일 늦은저녁에 방문했는데 진짜 아무도 없어서 너무 좋았어요ㅋㅋㅋ 인테리어도 진짜 예뻐서 사진두 왕짱 찍었어요! 조각케이크 기본8-9000원이라 비싸긴한데 완전 맛있어요! 종류고르기 힘들었는데 보기드문(?) 얼그레이무화과로 골랐어요 적당히 달면서 무화과가 진짜 많이 들어있드라구요ㅎㅎ 그리고 기본적으로 라떼가 맛있었어요!! 여기서 어떤케이크를 먹어도 기본적으로 만족하실 것 같아요💯 직원분들도 친절하시고 무튼 굿굿', 425, 63, 'GOOD', SYSTIMESTAMP);
