INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '여자친구 덕분에 팻어케이크를 알게되옸는데 망고딸기는 케이크 자주 안먹는 저도 극락이였습니다 너무 맛있는 케이크에 감사드리며 자주 찾아가도록 할게요❣️', 56, 12, 'GOOD', SYSTIMESTAMP);
