INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '크리스마스트리가 예쁜 연남동 카페를 찾으신다면 여기 추천 드릴게요!!시그니처 딸기 케이크가 사진이 굉장히 잘 나오고 예뻐요..ㅎㅎ트리도 연말에 사진 찍기 적격이에요👍🏻👍🏻', 47, 5, 'GOOD', SYSTIMESTAMP);
