INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '연남동 크리스마스 트리 카페 ♥️ 큰 트리와 곳곳의 오너먼트가 사랑스럽고 즐거운 겨울 분위기를 자아내요! ✔️ 라떼 ✔️ 딸기 생크림 케이크 시트와 크림이 부드럽고 가벼워요. 식감이 촉촉하면서 맛도 담백한 느낌! 크림의 당도가 적당해서 딸기 과즙과 섞이며 더 산뜻해집니다. 밸런스가 좋은 딸기 쇼트케이크에요 ㅎㅎ 누가 먹어도 호불호 나뉘지 않을 거 같아요. 라떼는 양이 넉넉하고 끝맛이 부드러운 고소함이 밀려와서 좋았어요. 캐롤+크리스마스 장식으로 설레는 분위기가 가득하네요 😚 내부 화장실도 깨끗하고 남녀가 분리되어 있답니다. 연남동에서 좌석 넓고, 채광 좋은 카페를 찾으신다면 케이크 맛집 팻어케이크를 추천합니다 🫶🏻', 21, 3, 'GOOD', SYSTIMESTAMP);
