INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '자주 보는 유튜버가 추천해서 먹어봤는데 예뻐서 사진도 잘 나오고 무엇보다 너무 맛있었어요 ( ˶ˆ⤙ˆ˵ )🍰🍓 앞으로 제 인생의 모든 기념일을 팻어케이크와 함께하고 싶어요..', 87, 17, 'GOOD', SYSTIMESTAMP);
