INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '부드러운 케이크 시트, 진한 우유의 풍미가 느껴지는 크림, 잘 익은 달달한 골드키위의 합이 너무 완벽했어요! 다음에는 다른 과일케이크를 꼭 먹어보고 싶어요!!', 25, 5, 'GOOD', SYSTIMESTAMP);
