INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '맛있는 딸기 생크림 케이크 덕분에 친구 생일 파티가 달콤해졌네요🍓 크림이 특히 맛있었고 매장 방문했을 때 매니저님이 친절하게 안내해주신 게 기억에 남아서 재방문 의사 있습니다❣️', 89, 12, 'GOOD', SYSTIMESTAMP);
