INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '초코러버 생일자를 위한 꾸덕초코가나슈 케이크! 결론 대만족했습니다. 비싸긴 하지만 케이크 정말 맛있드라고요🤎🙌🏻 초코초코~🍫🍓 안에까지 다 꾸덕한 스타일은 아니고 저 꾸덕 가나슈는 겉에만 발라져있습니다. 안에는 초코시트와 상대적으로 가벼운 초코 크림! 아주 술술 넘어갑니다. 하지만 사실 저는 마틸다 케이크 같은 미친꾸덕초코폭탄을 생각했어서 약간 아쉬웠..(😅) 네 맛있어요. (😫😫😫)', 68, 15, 'GOOD', SYSTIMESTAMP);
