INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '★홍대 데이트맛집, 크리스마스데이트 딱일듯 트리예쁨 공간넓음 사진잘나옴 직원분들 친절함 ☆인스타 케이크예약보고 궁금해서 직접 방문했는데, 맛없는건 아니지만 인생... 딸기케이크는 아님.. 맛있으면 미니케이크로 사가려고 했는데 한조각이면 충분할듯 분위기 즐기러 가세요.', 16, 9, NULL, SYSTIMESTAMP);
