INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '여자친구 생일 기념으로 팻어케이크 예약해서 사서 줬눈데 되게 좋아하는게 보였습니다. 맛도 엄청맛있어서 다시 방문하게 되었네요. 가나슈가 되게 맛있다고합니다. 방문하시게 된다면 꼭 드셔보세요.', 47, 5, 'GOOD', SYSTIMESTAMP);
