INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '케이크 맛집으로 검색해 처음으로 방문했어요~ 저희는 주말인데 조금 이른 점심 때에 도착해 빈 좌석이 많아 여유롭게 앉았어요. 케이크에 들어간 과일도 풍부하고 크림도 맛있어서 1인 1음료 1조각 했어요ㅎㅎㅎ 커피 맛은 무난합니다😊', 18, 3, 'GOOD', SYSTIMESTAMP);
