INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '케이크 존맛 카페 종료가 진짜 다양해서 고르는데 엄청 고민했어요 연남동 케이크 맛집으로 유명하길래 궁금했는데 기대 이상 왜 이렇게 맛있는지.. 하나만 먹은 거 너무 후회될 정도로 맛있었어요ㅎ 곧 친구 생일인데 무조건 여기서 사갈거에요', 32, 9, 'GOOD', SYSTIMESTAMP);
