INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '송리단길 케이크 맛집이라 역시 넘 맛있어요 케이크가 안 달고 맛있는 거 넘 좋아요 크림도 느끼하지 않고 시트도 부드럽고 생과일 상태도 아주 좋네요 조각케이크 8500-9000원 사이 딸기 귤 무화과 키위 블루베리 등 종류도 많아서 다 먹어보고 싶어서 또 갈거에요 시그니처커피도 은은하게 달아서 대존맛', 43, 6, 'GOOD', SYSTIMESTAMP);
