INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '연남에서 찾은 보물같은 신상 카페❤️ 지나가다 빨간 입구가 예뻐서 들어갔는데 세상에 인테리어가 꼭 동화속에 들어온 것 같은...!!! 인테리어는 물론이고 케이크도 너무 맛있어서 반해버렸네요. 다음엔 홀 케이크 사러 갈거예요!!!!!😍', 41, 5, 'GOOD', SYSTIMESTAMP);
