INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '케이크 픽업 하러 갔는데 비가 많이 와 포장 비닐 하나 더 받을 수 있을지 공손히 여쭈었는데 다른 직원이 주려고 하자, 듬직한 여자 직원이 막더라구요 비닐 하나에 얼마나 한다고 기분 팍 상했어요 좋은 날이라 웃으며 나왔지만 직원 교육 좀 해야 할 거 같네요.. 케이크 맛은 좋았습니다', 15, 8, NULL, SYSTIMESTAMP);
