INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '크리스마스 케이크 예약해서 샀는데 너무 맛있었고, 딸기도 많아서 좋았어요! 막 달지도 않아서 금방 먹었어욤:) 남자친구랑 미니로 사서 같이 먹었는데 금방 먹더라구요 1호를 사서 먹어도 괜찮을 것 같아요❤️', 91, 24, 'GOOD', SYSTIMESTAMP);
