INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '생크림케이크 먹고싶어서 4만원어치 쓸어왔어요😺♥️ 요거트생크림 파는 곳이 많이 없어서 아쉬웠는데 팻어케이크엔 요거트생크림 종류가 많아서 신나게 골랐습니다😆♥️', 48, 6, NULL, SYSTIMESTAMP);
