INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '팻어케이크 최고👍🩷 잠실점 방문했을 때 케이크 먹어보고 반했는데 연남점에 생겼다니 너무 좋아요🥹 벌써 크리스마스 분위기 낭낭하고 인테리어 너무 예뻐요!!! 케이크는 말해모해,, 제가 또 케이크 접수하러 오겠습니당✨', 115, 23, 'GOOD', SYSTIMESTAMP);
