INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '케이크가 정말 맛있어요!! 입에서 사르륵 녹아버리는 진짜 부드러운 케이크♡♡♡ 이벤트용으로 홀케이크 사가시는 분도 있던데 부럽...! 조각케이크로 먹은 게 아쉽더라구요. 연남동 옷맛집 옆입니다. #연남동카페 #연남동케이크 #딸기케이크  #협찬', 81, 18, 'GOOD', SYSTIMESTAMP);
