INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '생일기념 케익 주문하고 예약된 시간에 픽업하러 갔습니다. 케익 과일도 듬뿍들어있고, 동물성생크림 많이 달지 않고 너무 맛있어요.. 근데 케익 픽업시 차가지고 가면 헬입니다.. 골목 나오는게 너무 힘들어요... 동물성생크림 특성상 실온에 오래 들고 다니면 케익이 다 무너지는데...ㅡ.ㅡ;  주차가 단점이네요..', 46, 6, 'BAD', SYSTIMESTAMP);
