INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '케이크를 많이 못먹어서 생일케이크로 먹으려고 구매했는데 저녁 평일 7시 30분쯤에 가니까 1조각 남아있어서 헐레벌떡 구매했어요 직원분들 다 친절하셨고 귀여운 초도 많아서 꽃모양 초도 같이 구매했습니다~! 동물성생크림에 초코시트 케이크를 너무너무 좋아하는데 딸기도 싱싱한게 실하게 들어가있어서 느끼하지 않게 자리에서 뚝딱 해치웠어요 너무 이쁘고 맛있는 케이크에요💖', 111, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '진짜 사르르 녹는 식감과 딸기 당도가 너무 맘에 들었어요😉 남자친구랑 각자 집에 초코 하나 생크림 하나 각각 들고 갔는데 다들 너무 맛있다고 좋아하셨어요☺️ 다음 크리스마스 때도 또 뵐게요:)', 34, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '오랜만에 이렇게 맛있는 케이크를 먹은 것 같아요. 골드키위 케이크 먹었는데, 너무 달지않고 정말 부드러웠어요. 다소 비싼 케익값이 아깝지 않았습니다. 실내 인테리어도 좋았어요. #시선가는대로 #클파원챌린지', 5, 5, 'GOOD', SYSTIMESTAMP);
