INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '케이크 진짜 진짜 맛있어요 홍대 케이크 맛집 검색하면 바로 나오는 곳이라 기대하기도 했는데 그 기대보다 더 맛있었던..🥹🥹 딸기도 완전 달달한 딸기고 초코랑도 잘 어울렸어요 짱‘ㅜ', 103, 22, 'GOOD', SYSTIMESTAMP);
