INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '잠실에서도 유명한 케이크맛집이 연남동에도 생겼다고 해서 다녀왔어요 부드러운 크림과 싱싱한과일 조합의 케이크를 한입먹자마자 행복해짐🥰 동화속에 들어가는듯한 빨간문부터 아늑한 인테리어까지 갓벽❤️', 27, 8, 'GOOD', SYSTIMESTAMP);
