INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '케이크 포장 예약했습니다. 주말이라 사람은 많았지만 저는 포장만 할거라 금방 수령 후 나올 수 있었습니다. 딸기 새콤달콤하니 맛있고 초코 진짜 맛있어요. 생크림이랑 고민했는데 초코딸기 하길 잘했다고 느꼈습니다^^', 87, 18, 'GOOD', SYSTIMESTAMP);
