INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '케이크가 느끼하지 않고 정말 맛있어요. 디카페인 아메리카노도 고소하고 진해서 추천해요. 크리스마스 분위기가 물씬 풍겨서 기분 좋았습니다.', 30, 2, 'GOOD', SYSTIMESTAMP);
