INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '잠실에서 먹고 반했던 케이크였는데 연남점에도 생겨서 너무 기뻐요! 전에 생딸기케이크를 맛있게 먹어서 이번에는 초코딸기로 주문했는데 초코딸기도 어마무시하게 맛있습니다❤️ 아메리카노도 고소하고 케이크와 너무 잘 어울렸어요!', 59, 12, 'GOOD', SYSTIMESTAMP);
