INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '친구와의 새해 기념 파티에 팻어케이크 초코딸기와 함께했습니다 🤍 케이크 시트에 예민해서 지금까지 만족한 케이크가 몇 없는데 팻어케이크는 대만족이었습니다 !! 첫입부터 막입까지 끝까지 촉촉했어요 :) 생크림도 느끼하거나 달지 않고 술술 넘어가는 맛이었습니다 ! 딸기도 신선하고 단단해서 좋았어요 🍓', 24, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '당일 케이크 구매해서 샀는데 매장이 정신없어보이더라구요. 1호로 주문하고 급하게 가느라 확인안했는데 1호 사이즈가 원래 이렇게 작은가요? 진열되어잇던거랑 사진으로 비교하는데 차이가 너무 나는 것 같아 좀 당황스러워서요 😂 제가 산건 가장 밑에 4만8천원 짜리인데 막상 받은언 3만 7천원짜리 같은데 아니겠죠..? 맞게 주신거이길 바라며..', 9, 0, NULL, SYSTIMESTAMP);
