INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '케잌 예약 후 선물~ 딸기가 딸기가 너무 많아서 이런케잌은 처음이라며 모두 감동하고 먹었다고.극찬에 가까운 칭찬을 받았어요 덕분에 선물한 보람을 느꼈어요', 66, 12, 'GOOD', SYSTIMESTAMP);
