INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '역시 팻어케이크!! 연남에서 보니까 더 반가워서 냉큼 들어왔어요! 잠실에서 먹어보고 맛있어서 잠실 갈 때마다 먹었는데 집이랑 가까운 곳에 생기니 너무 좋아요. 인테리어도 너무 예쁘고 직원들도 친절해서 늘 기분 좋게 먹고 가는데. 오늘도 역시!!! 잘 먹었습니다!! 또 올게요👍👍', 28, 0, 'GOOD', SYSTIMESTAMP);
