INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '케이크 맛집이라고 해서 방문했어요. 겨울 맞이 인테리어도 예쁘고, 케이크 종류도 많아요. 다 먹어보고 싶었는데 가나슈 케이크 케이크 주문했어요. 라떼 시키면 아트도 해주시는 것 같은데 일단 커피 케이크 모두 맛있었어요. 직원분들고 넘 친절하시구요. 크리스마스 케이크 먹으러 또 올것같아요.❤️', 2, 8, 'GOOD', SYSTIMESTAMP);
