INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '인테리어가 넘넘 예뻐서 기분좋은 카페였어요. 연말 분위기가 물씬 느껴져 데이트장소나 친구들 모임하기도 딱 좋을 것 같습니다. 생과일 케이크들도 엄청 신선해보이더라구요!', 0, 0, 'GOOD', SYSTIMESTAMP);
