INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '부모님이랑 할머니 입맛에 맞는 케이크 찾기 어려웠는데 부모님이랑 할머니가 너무 맛있었다고 해줘서 너무 좋았어요!  빵도 촉촉하고 과일도 가득 생크림도 안 느끼해서 그 자리에서 한판 순삭했어요! 다음에 기념일 있으면 다른 과일케이크도 사서 먹어보고 싶어요!', 2, 1, 'GOOD', SYSTIMESTAMP);
