INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '비주얼이 예쁘고 무난한 맛일거라고 생각했는데 케이크가 넘 맛있어서 한 조각 더 먹었어요 운 좋게 자리가 있었는데 뒤로는 웨이팅 생기더라구요', 17, 9, 'GOOD', SYSTIMESTAMP);
