INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '지나가다 우연히 방문한 카페인데 일단 분위기가 너무 좋아요! 케이크 종류도 다양한데 친절한 직원분이 케이크랑 음료 추천도 해주십니다^0^b 굿 케이크 정말 맛있어요 한입 먹고 와... 했습니다 굿굿 다음에 또 방문해서 다른 케이크 먹어보고싶네요!!!!', 25, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '기념일이라서 딸기 생크림케이크 예약 주문해서 바로 받았어요 너무 달지도 않고 안에 딸기가 많이 들어있어서 안느끼하고 맛있어서 한번에 다 먹었어요 다음번엔 망고케이크도 주문해보려구요', 28, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '남편이랑 데이트하다가 우연히 발견하고 완전 반해버렸네요 일단 과일이 듬뿍 들어간 케이크의 비주얼부터 너무 예뻐요 초코가나슈는 진한 초콜릿 풍미가 입안 가득 느껴지고 귤 요거트 조각 케이크는 상큼한 귤과 부드러운 요거트 크림의 조합이 너무 맛있더라구요 산미가 적고 고소한 맛이 강한 아메리카노랑 같이 먹기에도 딱 좋았어요✨', 277, 71, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '선물용으로 구매한 홀케이크 예뻐요~ 카페에서 초코 딸기 조각 먹었는데 맛있었어요. 그리고 초에 불 붙일 라이터를 빌려주셔서 좋았어요. 매장이용을 위해 캐치테이블 예약을 했는데 2인으로 오시는분들은 계속 들어가는데 4인석자리가 없어서 계속 입장 허락이 안나더라고요. 2인이 와서 4인석 자리에 앉아있는 상황에도 관리를 안하셔서 밖에서 많이 기다렸어요. 문의에 대응하는 부분에서 아쉬웠습니다. 사람 많은 연말에 여럿이 가기엔 좀 힘들 것 같아요.', 39, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '사실 저는 케이크 덕후라..과일을 듬뿍 넣은 케이크로 유명한 곳이 있다해서 친구들과 바로 달려 갔어요ㅎㅎ초코딸기 조각 케이크는 상큼한 딸기가 가득 올려져 있었는데 달콤함과 상큼함에 정말 맛있더라구요 음료도 고소한 라떼에 달콤한 바닐라 향이 더해져 부드럽고 달콤한 맛이 최고였어요 맛있는 디저트와 음료를 먹으며 제대로 힐링하고 왔네요🥰', 123, 23, 'GOOD', SYSTIMESTAMP);
