INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '귤 요거트 케이크 포장했었는데 정말정말 너어어무 맛있어서 케이크 사야할 때마다 여기로 와요! 귤 요거트 케이크 한번 먹으면 다른 케이크는 생각이 안 날 정도에요,, 🫶🤤', 24, 5, 'GOOD', SYSTIMESTAMP);
