INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '제 사랑 팻어케이크가 연남에도 생겼다니 너무 감동적이다,,,,여긴 망고케이크도 짱인데 올 여름은 못 먹고 지나가버렸네요 내년엔 꼭 망케 먹어야지,,,,,,,팻어케이크짱♡♡♡🥹', 23, 10, 'GOOD', SYSTIMESTAMP);
