INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '케이크가 유명한 만큼 손님들도 정말 많고 그만큼 케이크가 맛있더라고요 ! 다른맛 홀케이크도 먹어보고 싶어요 ㅎㅎ 과일이 엄청 큽니다 !!', 28, 2, 'GOOD', SYSTIMESTAMP);
