INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '디저트맛집이네요. 생크림이 느끼하거나 물리지 않고 부드럽게 맛있어요. 무엇보다 과일케이크에 과일이 많아서 맛있더라구요. 케이크도 맛있는데 함께 마신 커피도 진짜 맛있습니다. 카페라떼 달지 않고 너무 맛있어요. 앞으로 땡길 때마다 방문해서 커피와 디저트 먹으려구요', 245, 69, 'GOOD', SYSTIMESTAMP);
