INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '여기 진심 카페 맛집이에요,,>< 친구 추천으로 와봤는데 커피도 맛있고 케이크가 미쳤어요 !!!! 시그니처라떼 먹었는데 향도 좋고 진한게 완전 제 스탈이더라구요:) 단거 땡길때 또 먹으러 와야겠어요 내부도 깔끔하고 다들 친절하셔서 또 오고 싶은 그런 카페입니당 ㅎㅎ 담엔 남자친구랑 와야겠어요 ~~', 47, 3, 'GOOD', SYSTIMESTAMP);
