INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '친구 생일축하해줄겸 방문해서 딸기케이크랑 커피 주문했는데 완전 취향저격이었어요! 송리단길에서 워낙 유명한 카페였는데 연남점에도 생겨서 기쁘네요ㅜㅜ👍 케이크랑 함께 먹은 커피도 탄맛없이 꼬소해서 굳굳 입니다! ^^', 15, 5, 'GOOD', SYSTIMESTAMP);
