INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '햇살 맛집~케이크 맛집~커피 맛집이네용! 우연히 지나가다가 들렸는데 제 원픽이 될 카페네요 ㅠㅠ 진짜 분위기도 너무 좋고 맛있어서 한두번으로 그만 갈 카페가 아닙니다..! 특히 케이크 미쳤어요! 다들 가보시는걸 강추..👍🏻', 28, 8, 'GOOD', SYSTIMESTAMP);
