INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '너무 예뻐요 우선, 과일케이크 정말 맛있고 딸기말고 자주 안보이는 샤인머스켓으로 먹어봤습니당^^ 짱맛 다음에도 꼭 오고 싶어요 여심저격인 곳임', 15, 6, 'GOOD', SYSTIMESTAMP);
