INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '연남에도 생겼다길래 가봤어요~! 비싼 감이 있지만 역시나 맛있어요! 귤케익은 요거트크림이라 새콤달콤했고 딸기케익은 말모❣️손님 많아서 주말엔 웨이팅 걸어야했어요! 또 먹고싶다 ㅎㅎ', 72, 16, 'GOOD', SYSTIMESTAMP);
