INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '급하게 케익이 필요했었는데 먹음직스러운 홀케이크들이 많아서 바로 구입했어요 !! 가격대도 합리적이고 먹어보니까 맛까지 좋아서 케이크 주문하러 자주 올 것 같아요 !! 너무너무 맛있게 잘 먹었습니다👍🏻👍🏻', 2, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '2년연속 남자친구 생일때마다 가던 딸기케이크 집이 문을 닫아서 집에서 그나마 가까운 곳으로 선택했는데 좀 많이 실망했어요.. 케이크 당일 생산이 맞나 싶을정도로 속에 들어간 딸기들은 다 물컹했고 상큼하고 신맛이 아닌 쉰냄새가 나고 혀가 애리고 쓰다고 느껴질정도로 오래된 딸기맛이 나요 공지에 하루지나기 전에 다 먹으라고 물론 써있지만 바로 다음날 먹는데도 케이크가 물때문에 다 무너지고 빵도 딸기에서 나온 물에 젖어 으스러질 정도로 딸기 상태가 많이 별로네요 디자인은 좋았는데 맛이랑 상태가 너무 별로에요', 98, 19, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '여긴 딸기케이크 맛집이네요 커피도 맛있는데 함께 먹은 딸기조각케이크가 잊혀지지 않아요ㅜ 분위기 너무 좋고 디저트와 커피까지 맛있으니 앞으로 자주 오려구요^^', 50, 8, 'GOOD', SYSTIMESTAMP);
