INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '귤요거트케이크 생일 기념으로 먹었어요 진심 너무 맛있어서 돌아버리는줄.. 제 생에 처음으로 케이크 한 판을 앉은 자리에서 다 먹은 날이었어요 미쳤습니다 진짜로... 커피 한 모금 안 마시고 케이크만 우적우적 먹게 되는 맛이에요 완벽에 가까운 맛입니다 매장도 예뻐요 친절하시구오', 45, 4, 'GOOD', SYSTIMESTAMP);
