INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '초코딸기케이크는 이제 여기에서만 사먹어야겠어요.... 과하게 달지 않고 딱 적당히 달달한 맛에 시트도 너무 부드러워요!💚 과일을 매일 직접 받아와서 만드신다는데 신선함이 한 입 먹자마자 느껴집니다.ㅎㅎ 맛도 맛이지만 친절하게 응대해주셔서 기분좋게 다녀왔어요.', 5, 7, 'GOOD', SYSTIMESTAMP);
