INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '어머니 생신이라 귤케이크를 구매했는데, 정말 귤이 한가득 들어있고, 특히  빵시트 부분이 너무 맛있어요ㅠ! 직원분들도 친절하시고 좋으셨어요!', 26, 5, 'GOOD', SYSTIMESTAMP);
