INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '카페 분위기도 예쁘고 커피랑 디저트 맛도 좋아요! 케이크가 진짜 찐 맛있어여. 동물성 크림이라 다먹을때까지 느끼하거나 물리지도 않아서 넘나 맛도리! 커피 원두도 부드럽고 고소해서 맛있습니다.', 56, 14, 'GOOD', SYSTIMESTAMP);
