INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '너무 먹어보고싶었던 케이크인데 송파점은 멀어서 인스타로만 구경하던 곳이예요~ 연남점 오픈하셨다길래 냉큼 예약해서 사먹어봤는데 역시나 맛도 좋네요😊💕 담엔 조각케이크으로도 여러개먹어보고싶어요🤤❣️', 45, 9, 'GOOD', SYSTIMESTAMP);
