INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '팻어케이크 연남점 저의 최애 홀케이크맛집이에요! :) 아메리카노랑 같이 케이크 한입 먹어주면 진짜 오늘 하루의 피곤이 다 풀리는 것 같아요~ 특히 여긴 생크림하고 과일이 너무맛있어요 ㅠ0ㅠ 오늘도 달콤하게 진짜 너무 맛있게먹었어요! 또 올게요', 8, 6, 'GOOD', SYSTIMESTAMP);
