INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '송파까지 너무 멀었는데 연남점 오픈해서 좋아요!! 직원분들 모두 친절하시고, 키위 진짜 안까지 가득이고 크림도 너무 많지않아서 느끼하지않고 맛있었어요!! 다음엔 다른 케이크 먹어볼게용🤍', 19, 8, 'GOOD', SYSTIMESTAMP);
