INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '임신중인데 귤요거트 케이크 사진으로 보고 너무 맛있어 보여서 예약하고 방문해서 포장해 왔어요!! 요거트 케이크 자체는 맛있었는데 귤 자체로는 덜 달 아서 아쉬웠어요!!', 15, 2, NULL, SYSTIMESTAMP);
