INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '케이크가 너무 예뻐서 놀랐어요! 팻어케이크 꼭 가보고 싶었는데 연남에 생겨 얼마나 행복한지 몰라용 딸기케이크 진짜 존맛탱입니다! 먹고 넘 맛나서 포장도 했어요! 아포카토도 강추! 인테리어도 연말 분위기 낭낭하고 넘 예뻐용', 118, 23, 'GOOD', SYSTIMESTAMP);
