INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '송리단길에서 워낙 유명한 카페인데 연남동에서 오픈했다고 해서 남자친구랑 냅다 먹으러 왔습니당 ^^ 피넛버터라떼랑 아포가토 고민하다가 아포가토에 과일 케이크 먹었는데 이렇게 잘 어울릴 수가 있나요,, 진짜 먹으면서 감탄했어요 과일 자체가 신선해서 케이크 퀄리티가 미쳤더라구요 분위기도 좋아서 셀카도 잘나와요 ㅎㅎㅎ😝💜', 29, 0, 'GOOD', SYSTIMESTAMP);
