INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '신선한 제철 과일로 만든 케이크가 유명하다고 들어서 방문했는데 진짜 진짜 너무 신선하고 너무 맛있고 케이크 시트 자체가 맛있는 집이더라구요!! 그리고 음료도 제 입에 딱 맞아서 너무 맛있게 먹고 왔어요! 분위기도 좋고 또 가고 싶네용!!', 0, 10, 'GOOD', SYSTIMESTAMP);
