INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '빵순이, 빵돌이라면 모를 수 없는 곳이라고 생각해요 ㅎㅎㅎ 특히 여기는 케이크가 넘넘 맛있음,, 계절에 따라서 과일들이 바뀌는데 상콤달콤하니 넘 맛있어요 😣❤', 42, 10, 'GOOD', SYSTIMESTAMP);
