INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '원래 아메리카노만 마시는편인데 펫어케이크 아포가토에 빠져서 거의 한달째... 틈만나면 아포가토를 먹으러 오는 것 같아요 ㅎㅎㅎ 진심 너무 맛있습니다 분위기도 좋고 전체적으로 커피메뉴가 다 맛있어서 좋아요!', 7, 1, 'GOOD', SYSTIMESTAMP);
