INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '친구랑 연남동 놀러갔다가 후식으로 케이크먹으러 갔는데 진짜 겁나 맛있었어요!!!!! 인생케이크,,🥰🧡 커피도 넘 맛있더라구요! 카페 분위기도 넘 예뻐서 인생샷 찍고왔네요👍👍💜', 22, 10, 'GOOD', SYSTIMESTAMP);
