INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '팻어케이크 연남점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '남편이랑 산책하다가 커피마시고 싶어서 들어갔는데 케이크에 반하고 왔네요ㅎㅎ 과일이 엄청 달고 신선하더라구요! 커피는 시그니처라떼 시켰는데 시그니처 타이틀이 붙은 이유를 알겠어요 짱맛있네요!!ㅎㅎㅎ 이번 크리스마스때 케이크는 여기서 홀케익 살거에요~ㅎㅎ', 32, 5, 'GOOD', SYSTIMESTAMP);
