INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내맘대로폰케이스 홍대점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '더운 날씨 실내에서 놀만한 곳을 찾고 있었는데 폰케이스를 만들 수 있는 곳이 있다고 해서 찾아왔어요! 제 취향을 반영해서 폰케이스를 만들 수 있어서 좋았습니당~비즈를 원하는대로 골라서 만들 수 있다는 것도 좋았고 생크림 짜서 비즈 붙이는 것도 재밌었어요! 추천합니다!', 106, 23, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내맘대로폰케이스 홍대점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '친구들과 폰꾸 하러 왔는데  넘 좋았습니다ㅎㅎ 각자 취향 때려박아 욕심 그득그득한 폰케이스를 만들었어요!! 친절하시고 무제한 파츠도 종류가 많아서 파츠 고르고 덜어내기가 힘들정도 였어용ㅎㅎ  이 가격에 파츠 가득한 폰케이스를 만들다니 가성비도 좋숩니다!!', 30, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내맘대로폰케이스 홍대점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '사장님이 정말 친절하시고 재밌게 만들 수 있어서 좋은 것 같아요 친구들하고 추억만들고 싶을때 오시면 좋을 것 같아요 진짜 사장님 최고입니다 ㅠㅠ', 81, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내맘대로폰케이스 홍대점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '처음에는 예쁘게 만들기가 어려울 것 깉아서 걱정도 많이 했었는데, 사장님이 친절하게 만드는 방법도 설명해 주셔서 큰 어려움 없이 만들 수 이ㅆ었어요!!', 4, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내맘대로폰케이스 홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '요즘 이런 데코덴 케이스에 빠져서 만드려고 오게 됐어요･ᴗ･ 파츠 종류가 정말 많더라구여!! 그래서 그만큼 고민하는 시간두 길었는데 예쁜 직원분께서 추천해주시구 함께 고민해주셔서 원하던 만큼 예쁜 케이스를 만들 수 있게 된 것 같아요 ㅎㅎ 매장 관리도 정말 잘 되어있고 편안한 분위기라 혼자 오기에도, 친구랑 오기에도 너무 좋은 것 같아욧~~ 만드는 동안 너무 재밌었구 시간도 금방갔슴다 조만간 또 와서 만들고 싶어요!! 추천합니당♥️', 407, 82, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내맘대로폰케이스 홍대점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '지인이랑 스트레스 풀고싶어 홍대 나들이 나왔었습니다! 평소 데코덴 탑꾸 자주하기도 했고 지인이랑 같이 해보고싶어 가보자고 했어요. 파츠 종류도 다양했고 무제한이라는게 너무 좋았던것 같아요!👍 들고갈 수 있게 살짝 말려서 포장도 해주시면서 친절하게 주의사항도 안내해주셔서 좋았습니다😊 다음번에 다른 친구들 데리고 또 방문해보고 싶습니다~!!', 76, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내맘대로폰케이스 홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '혼자 와서만들었는데, 시간 가는줄 모르고 재밌게 만들었어요! 🤍매장도 청결하고 파츠랑 비즈가 종류도 다양하고 귀여운 파츠들이 많아서 걸리는데 오래걸렸어요🤭😳 직원분도 친절하게 만드는 법부터 잘 만들 수 있는 방법까지 알려주셔서 더욱 더 잘 만들 수 있었어용 😊🌟덕분에 소중한 추억 만들고 가요~🥰', 21, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내맘대로폰케이스 홍대점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '엄마의 노랗게 물든 케이스를 보고 눙물 💧 깜짝선물로 엄마와 어울리며 제 취향을 담아 만들어드리고 싶어서 세번째 방문해봤어요 〰️저번에 방문했을때와는 다른 파츠들이 많이 입고되어있어서 두근두근 ..🤍 노래도 잔잔하구 혼자 앉을수 있는 테이블도 많아서 집중하며 만들었구 파츠들도 다양한만큼 필링모양을 낼 수 있는 깍지들도 여러 종류있어서 좋았어욤 >.< 누군가에게 선물해본적은 처음인데 받는분을 생각하며 만들다보니 색다르고 기분이도 좋았고 직원분이 설명도 꼼꼼히 잘해주시고 친절하시더라구요 (ps.트와이스 나연닮은 분) :)저처럼 소중한 누군가에게 선물할때나 가족들 혹은 연인 어느누구와 방문해도 추억도 쌓으며 힐링할 수 있을것같아요 ! 파츠도 매번 바꿔주시는 사장님 센스에 갬동 .. 🫠 항상 번창하시구 건강하세요 💗', 12, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내맘대로폰케이스 홍대점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '폰케이스가 너무 심심해보여서 방문하게 되었는데 일단 제 취향을 반영해서 만들수 있다는 점이 가장 큰 메리트였어요 🤍 파츠들도 다양하게 많아서 하나하나 고민하면서 고르것도 너무 재미있더라구요 제가 방문했을때 외국인분들도 계셨는데 케이스 제외하고도 키링이나 모루인형 등등 만들수 있는 제품들의 범위가 넓어서 아이들 데리고 와도 좋을것 같았어요 ! 오랜만에 사부작사부작 만들어봤는데 만드는 순간에는 잡생각도 사라지고 행복했어요 목금 마감 직원분(?)도 너무 친절하시고 트와이스 나연님이랑 똑같이 생기셔서 #기절초풍 꼭 방문해보세용 :) 정말 작은 소확행으로 힐링하구 갑니당 ! 사장님 번창하세용 😋💗', 125, 24, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내맘대로폰케이스 홍대점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '처음 만들어보는데 설명도 잘해주시고 어려워만 했는데 막상 시작하니 의외로 쉽더라고요 우리집 꼬맹이도 너무 좋아하고 유익한 시간이였어요', 39, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내맘대로폰케이스 홍대점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '진짜진짜 가보고 싶었는데 드디어 가볼 수 있게되어 너무 좋았습니다.! 친구랑 같이 가서 케이스 만들었는데 친구도 너무너무 좋아하더라구요!! 케이스만 만들 수 있는게 아니라 슬라임도 만들 수 있고 다양하게 즐길 수 있더라고요 다음에 한번 더 가봐야 할것 같아요😻', 55, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내맘대로폰케이스 홍대점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '큰 아이가 폰 케이스 만들러 가고 싶다고 해서 검색 후에 다녀왔어요~ 파츠 종류도 다양하고 두 아이들 다 너무 재미있어하고 좋아했어요. 직접 만들었다며 뿌듯해하더라고요~ 직원분도 설명도 잘 해주시고 친절하세요^^ 아이들이 또 가고 싶다고 하네요. 다음에 가면 저도 폰 케이스 만들려고요😊', 25, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내맘대로폰케이스 홍대점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '아이랑 같이 갔었는데 이색데이트 잘하고 왔어요파츠 종류도 많고, 무제한이라 고르는데 한참 고민되더라구요ㅎㅎ 아이도, 저도 재밌었던 시간이었어요😀 다음엔 더 예쁘게 잘할 수 있을 거 같아요! 나중에 또 방문할 예정입니다', 103, 23, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내맘대로폰케이스 홍대점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '친구랑 즉흥으로 왔는데 파츠가 다양해서 너무 좋았고 새로운 경험이라 재밌었어요!! 다음에 또 방문해서 다른 컨셉으로 만들어보고 싶고 매장 내에 음악이 시끄럽지 않아서 적당하게 떠들면서 만드는데에 집중도 할 수 있었고 중요한건 사장님이 진짜 친절👏👏👏👏👏👏👏 그래서 더욱 재방문 의사 10000% 다음에 또 올게요!!', 38, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내맘대로폰케이스 홍대점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '친구하고 같이 왔는데 자유로운 분위기에서 편하게 만들었고 재료도 많아서 선택의 폭도 넓었어요! 직원분도 너무 친절하시고 마무리도 꼼꼼하게 해주셨어요.. 아기자기한거 좋아하시는 분들 추천해요!!', 11, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내맘대로폰케이스 홍대점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '친구들하고 즐거운 시간 보냈어요!! 셋 다 넘넘 만족 ㅜㅜ 파츠 종류도 다양하고 넘 재미있어서 시간가는 줄 모르고 했네요!! 케이스도 넘 예뻐서 만족 ˙ᵕ˙ 재방문 할 것 같아요 💕', 38, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내맘대로폰케이스 홍대점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '처음으로 폰케이스 꾸며봤는데 너무 재밌었어요!! 시간 가는줄 모르고 데코했네요>< 직원분께서도 너무 친절하셔서 기분 좋게 만들고 왔습니다! 굿굿🧡', 39, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내맘대로폰케이스 홍대점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '애들만 하는줄알았던 데코덴 폰케이스 도전! 홍대에 있다 그래서 맛집도 갈겸 들렸어요 별 기대없이 갔다가 너무 신나게 즐겨버렸지모에요 🙊룰루루~ 고르는재미🤡 예전에 동대문에서 재료만 재료만 왕창샀다가 쓰고난 나머지는 버렸던🤧 여기서는 말그대로 내맘대로 골라서 사용해서 오히려 저렴한 느낌이에요 예쁜캐릭터들도 많아서 내 최애 피글렛이랑 짝궁 푸우는 주인공 자리로 콩콩! 눌러담기ㅋ  욕심쟁이처럼 크림컬러는 친구들꺼 다갖다쓰고ㅋ 직원분도 너무 친절하셔서 간만에 기분좋게 스트레스 풀고 잘 놀다가요~ 주말에 할거 없으면 여기꼬고', 64, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내맘대로폰케이스 홍대점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '앙증맞고 귀여운 캐릭터들이 가득가득한 곳에서 예쁘게 나만의 폰케이스를 꾸밀수 있어 너무 좋았어요. 힐링타임 ~^^♡♡ 친절하게 설명 추천해주셔서 아이랑 잼나게 활동했어요.', 27, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내맘대로폰케이스 홍대점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '딸아이와 홍대 데이트 왔는데, 폰케이스만들기 체험 재밌어요. 귀여운 파츠가 많아서 고르는 재미가 있음^^ 처음 만드는데 어렵지 않게 했네요.', 9, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내맘대로폰케이스 홍대점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '아주좋아용 진짜ㅋㅋㅋㅋ 아주 특이한 경험이었어요ㅎㅎ 남자친구랑 아주 특별한 데이트가 되었답니당ㅎㅎㅎ 여러분도 꼭 방문해서 이렇게 이쁜 케이스 만들어조셔요', 3, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내맘대로폰케이스 홍대점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '폰케이스 꾸미기 체험 하고 싶어서 찾아 갔어요! 귀여운 파츠들이 많았고 어떻게 만들지 막막할 때는 만들어져있는 샘플들 참고해서 만들었어요! 만드는데에 약 1시간 정도 걸렸던것 같은데 데이트 하거나 친구랑 한번쯤 오기 좋은것 같네요~', 43, 10, 'GOOD', SYSTIMESTAMP);
