INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내맘대로폰케이스 홍대점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '파츠가 예쁘고 귀여운게 많았어요! 무엇보다 파츠를 무제한으로 쓸수 있어 좋았어요 크림 색도 예뻤고 다음에 또 와서 하고싶어요! 방학하고 처음으로 놀러왔는데 재밌어요!꼭 가보세욧', 36, 2, 'GOOD', SYSTIMESTAMP);
