INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '내맘대로폰케이스 홍대점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '친구랑 와서 폰 꾸미기 완전 좋아용 시간도 빨리가고 원하는 대로 만들 수 있어서 넘넘 좋아용🥰💗 홍대 와서 특별한걸 하고 싶을 때 오면 좋을 것 같아요 !!', 5, 10, 'GOOD', SYSTIMESTAMP);
