INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '운동 가기 전에 두유로 바꾼 말차라떼에 디카페인 샷 하나 추가해서 마셨어요. 두유 덕분에 부드럽고 고소한 맛이 더 살아나서 부담 없이 마시기 좋았고, 디카페인이라 운동 전에도 편하게 즐길 수 있었어요. 가볍지만 만족도 높은 조합이라 앞으로도 자주 마시게 될 것 같아요.', 66, 16, 'GOOD', SYSTIMESTAMP);
