INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '홍대 오후 일정 마치고 스타벅스(홍대동교점) 방문했네요 날씨가 더워져서 시원한곳에서 매거진랜드 에서 구입한 잡지 볼겸 스벅에 들렸네요 🌼〰️ 이곳은 2F에서 내려보는 View 가 좋아 커피 마시고 밖 횡단보도 오가는 사람풍경 있어 좋네요 🌸〰️ 오늘은  magazine 6권 구입해 내용이 궁금해 완독하려고 스벅에 왔네요 🌺〰️ 매장이 넒고 쾌적해 스텝분들도 친절하게 인사 해 주시고 매우 만족합니다 💕 📮아메리카노(ICE.G)       5,300₩', 12, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '홍대입구역 4번출구로 나오자마자 왼쪽편에 바로있어서 접근성이 엄청좋네요. 매장도 1,2층이고 2층에 자리많아요. 사람많을때는 엄청시끄러울것같아요. 좌석이 매우 가깝게 배치된편이에요. 관광객이많아서그런지 머그컵이나 텀블러가 도시별로 많이 준비되어있어서 구매하기좋을듯해요. 엄청 예쁘네요', 62, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '정말 주말에 사람이 어마무시하게 많습니다… 테이크아웃 음료였는데 거의 20분 걸린 것 같아요. 그래도 음료는 맛있고 직원분들도 친절해요', 38, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), 'R 닉네임 파트너분 인사가 너무 활기차서 기분이 좋아졌네요! 덕분에 남은 하루를 기분 좋게 보낼 수 있을것만 같아 감사함에 리뷰 남겨봅니다!', 0, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '새로나온 케이크인데 피스타치오와ㅜ딸기의 조화 나쁘지 않더라구요 스벅 새로나온 케이크 먹을 때마다 실망스러웠는데 이번건 soso 하네요 또 사 먹고 싶어요', 59, 14, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '슈크림 말차 라떼 선출시 기간에 무료 사이즈업 쿠폰을 사용하여 먹어 보았습니다. 슈크림 라떼도 원체 좋아해서 매년 봄이면 슈크림 시즌을 기다리는데 슈크림 말차 라떼는 덜 달아서 오히려 슈크림과 더욱 조화롭게 어우러지는 느낌이 있었어요. 슈크림 시즌 동안 애용하게 될 듯합니다. 바나나와 베이글을 곁들이니 든든한 한끼 식사가 되었어요.', 10, 1, 'GOOD', SYSTIMESTAMP);
