INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '애경 바로 옆 .. 어쩜 항상 사람이 이렇게 많을수 있는지 싶을 정도로 붐벼요 ㅜㅜ 그래도 자리만 잡을 수 있다면 좌석은 편하답니다', 33, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '홍대입구역에서 동생 기다리며 들렀어요 ㅋ 4번출구 바로 옆에 있네요! 유동인구에 비해 크게 사람이 없는 편이네요~ 오늘 진짜 춥네요. 따뜻한거 먹고 움직여야지💪🏻', 80, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), 'I recently visited the Starbucks at Hongdae and it’s my favorite among the four in the area. This location offers a cozy, quiet atmosphere, perfect for relaxing or working. The comfortable seating and warm lighting make it inviting. Plus, its convenient location makes it easy to stop by for your favorite classic drink.', 3, 8, 'GOOD', SYSTIMESTAMP);
