INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '밀레앙 스타벅스 플랑 궁금한 차에 별 더 준다 해서 주문했지만 가격에 비해 크기에 놀라고(너무 작아서) 맛(너무 평범해서)에 한 번 더 놀랐습니다. 이건 정말 아니올시다, 입니다. 다시는 주문 안 하려고 적어놓아요.ㅜㅜ', 41, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '스타벅스의 대표 맛도리 푸드 [치킨 머쉬룸 샌드위치] 저녁을 먹기엔 부담스러울 때 스벅에서 연인과 함께 도란도란 이야기 나누기에 딱 좋은 간편 푸드로 추천합니다 💓 따뜻하게 데워먹는 빵이라 조금 기다려야하지만 그만큼 안에 토핑으로 들어간 버섯과 치킨이 아주 잘 익어서 넘넘 맛있어 하는 제  최애픽입니다!! 특이 이번에 스벅 25주년을 맞이하여 새로 나온 베어리스타 마스카포네 도넛까지 만나보고 왔는데 실물로 만나보니 더욱 맛있어 보이더라구요! 다음엔 이 디저트를 도전해 볼까 합니다~', 10, 0, 'GOOD', SYSTIMESTAMP);
