INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '다른 카페의 녹차 라떼 생각하고 제주 말차 라떼 주문했는데 너무 떫어서 시럽 추가하고 뜨거운 물 추가해서 먹었어요🥲 블루베리 치즈 케이크도 정말 진~~~한 치즈입니다 :)', 71, 11, 'GOOD', SYSTIMESTAMP);
