INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '영수증 리뷰 안하는데 이제껏 가본 스벅중에 가장 친절하게 응대해주셔서 감동받았습니다~ 주문 받으셨던 직원분, 픽업대에 계셨던 직원분들 모두 친절하셨습니다👍🏻', 14, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '신입 파트너 교육하시면서 만들어주신 라떼인데 물론 처음부터 잘 할수 없지만 피쳐안에 개거품처럼 스팀 우유를 봐버려서 (라떼아트 그런거 전혀 바라지 않음) 무튼 저는 돈주고 마시는 건데 기분이 좋지는 않네요..', 6, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '홍대입구역   통창뷰 스타벅스~ 홍대에 나옴 예전엔 홍대리저브매장만 갔었는데 요즘엔 홍대동교점만 이용해요 항상 사람이 바글바글하지만 오늘따라 비바람치니 사람이 더욱더 많네요 까페가 넓고  통유리로 되어있어서 힐링되어 즐겨찾게 되네요 직원들도 친절하시고~오늘도 맛있는 말차라떼 마시고 갑니다', 49, 6, 'GOOD', SYSTIMESTAMP);
