INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '스타벅스 클래식 밀크티 블랜디드 신메뉴로 나왔길래 궁금해서 주문해봤어용 원래 먹던 밀크티가 더 차가운 느낌이네요 ㅋㅋㅋ 날씨가 더운데 한입 마시니까 더위가 싹 달아나네요 ㅎㅎㅎ 평일 낮에 와도 거의 만석이라 겨우 앉았네욤', 65, 15, NULL, SYSTIMESTAMP);
