INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '유자민트티랑 소금빵 주문했어용 ㅎㅎ 스타벅스 소금빵은 그냥 짭잘한 식빵 먹는 것 같아서 담엔 안 먹을 것 같아요 ㅋㅋㅋ 유자 민트티 따뜻하게 마시는 것도 맛있었어용 💗', 99, 19, 'GOOD', SYSTIMESTAMP);
