INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '“홍대입구역 근방 새로 생긴 스벅 매장” 새로 오픈한지 얼마 안되서 공간이 넓고 깔끔합니다 인근 다른 홍대 매장들보다 테이블이 많아서 좋아요! 맛이야 스벅이니까 검증되어 있죠!', 0, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '새로 생긴 스벅 홍대동교점 친절하시고 디저트종류도 많아요 매장이 넓어서 이용하기 편리하고 2층 창가자리 통유리라 뷰도 탁 트여있어서 좋아요 미리 아메리카노 뽑아 놓지않아 다른지점보다 아메리카노 맛있어요', 12, 8, 'GOOD', SYSTIMESTAMP);
