INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '항상 사람많은 곳이예요:) 북적거리고 시끄러워서 편하게 대화하거나 공부할 곳으로는 추천하지 않지만 친구 기다릴 때 잠깐 들어와 있기에는 좋은 거 같아요~', 68, 12, NULL, SYSTIMESTAMP);
