INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '블루베리치즈타르트보다 이게 더 맛있는거같아요! 치즈함량이 더 높아서 그런가😋 음료는 이번 신상 만다린이었는데 탄산이 적당히 들어간 맛이라 청량감이 있어서 여름 메뉴로 너무 맛있더라구요! 스벅 이번 여름 음료 짱짱👏👏', 49, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '여기엔 추억이 서려있는 곳이라 이 장소에 스타벅스가 생겼다는 것을 알고 방문했어요. 주말이라 그런지 사람 많아서 좌석 구하기가 힘들었어요', 82, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), 'AK프라자 바로 옆에있고 홍대역에서 가까워서 접근성이 좋아요. 평일인데도 만석이고 사람 꽉차있었는데 직원분들 힘드셨을텐데도 웃으면서 주문 잘 받아주셔서 감사했어요. 별쿠로 벤티먹었는데 돌체라떼도 달지않고 맛있었어요!!! 굿👍', 39, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '스타벅스 기프티콘이 생겨서 방문했어요 홍대에 스타벅스가 많네요 그럼에도 자리 잡느라 혼났어요 많이 더웠던 날인데 쾌적하게 시간 보내서 좋았습니다 :)', 25, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '계산대 직원 불친절ㅡㅡ 계산대 직원 실수로 계산 취소하고 다시 재결재는 했는데 사과 한마디도 없고, 말투도 별로임 기분 나빠서 음료까지 맛없어짐', 101, 23, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '오픈한지 그리 오래되지 않은 홍대동교점 스벅~ 홍대입구역에서 경의선 숩길 쪽으로 올라오는 길쪽에 자리하고 있어요. 매장 넓고 만남의 장소로 좋아요. 원래도 까페로 사용하던 공간이었는데 스벅이 들어왔네요.', 119, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'MEETING');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '마감 30분 전에갓는데도 친쩔하셧다 ㅠ ㅡㅠ 홍대입구역 바로 근처다보니까 5분전에 오시는 분도 계셔ㄸㅏ 힘내세요 ㅠ ㅡㅜ!!!!', 49, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '홍대 빵집 블랑이 스타벅스로 바뀜. 2층은 사람이 엄청 많은데 구석 구석 자리를 만들어놔서 혼자 공부하고 업무하는 홍대인들에게 좋을듯. 직원분들도 친절하시고 좋네요^^', 18, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '블랑이 떠나고 스벅이 생겨서 너무 또 다행이라는 생각이 들어요 2층 건물에 비해 좌석은 또 그리 많지 않지만 역시 깨끗하고 좋아요!!', 4, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '스타벅스 홍대동교점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '✔️그릭요거트그래놀라 ✔️파스트라미햄치즈샌드위치 ✔️바비큐치킨샌드위치 제가 제일 좋아하는 조합이에요❣️ 바비큐치킨샌드위치는 맛도 있고 고단백 저지방 샌드위치이고 파스트라미는 제가 적양배추를 좋아해요 샌드위치 나눠먹고 후식으로 그릭요거트그래놀라 먹어주면 끝납니다 샌드위치로 든든하고 맛있고 건강하게 속 채우고 요거트 그래놀라로 달달하게 마무리하면 포만감+만족감 장난 아니에요 파스트라미샌드위치 잘 없는데 홍대동교점은 샌드위치 종류가 많아서 그런지 있어서 좋았어요 *제 리뷰를 더 보고 싶으시면 프로필을 눌러 네이버 플레이스로 들어와 보세요:)', 20, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이덴티티커피랩'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '리뷰 이벤트 없으면 잘 안 쓰는데 그냥 가면 염치 없을 정도로 서비스를 받아서..ㅋㅋㅋ 감사해서 씁니다! 주문해서 마신 음료 두 잔 다 맛있게 잘 마셨는데, 바 테이블 쪽이 좀 더 편할 것 같아서 옮긴 다음 따듯하게 한 잔, 다른 원두로 시원하게 한 잔 더 서비스로 주시면서 원두 설명도 해주셔서 감사했습니다😭  서비스로 마신 커피 맛과 친절함에 감동받고 갑니다! 감사했습니당-!', 7, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이덴티티커피랩'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '사장님이 정말 친절하시고 커피 설명도 잘해주셔서 개인 취향에 맞춰서 먹기 좋아요 커피도 쓴 맛이 거의 없고 라떼아트도 예쁘게 해주셔서 커피 마시면서 대화하기 좋았어요 :) 가격도 분위기와 퀄리티를 고려하면 정말 최고이니 커피 마시러 방문해보시길 추천드립니다 ^&^', 95, 21, 'GOOD', SYSTIMESTAMP);
