INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이덴티티커피랩'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '평일에도 항상 인기 많은 아이덴티티 커피 랩 💗 화이트오크 6.000 바닐라빈라떼 5.000 화이트 오크가 대표 커피 중 하나 이던데 오렌지 맛이 느껴지는 크림 커피인데 정말 진하고 맛있었어요! 바닐라빈 라떼도 달달하게 맛있었구요 인테리어도 창이 크고 감각적인 나무들과 어우러져서 여유로운 느낌이라 참 좋아요!', 68, 12, 'GOOD', SYSTIMESTAMP);
