INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이덴티티커피랩'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '에티오피아 하로 와추 내추럴. 풍부한 향과 그에 어울리는 산미가 조화로워 첫 모금부터 끝 모금까지 내내 만족스러웠다. 투웨이컵의 유용한 쓸모를 재확인한 날!', 75, 11, 'GOOD', SYSTIMESTAMP);
