INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이덴티티커피랩'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '필터커피 따뜻한 걸로 주문. 투웨이컵에 주셨는데 림의 생김새가 달라서 어느쪽으로 마시느냐에 따라 그립감과 텍스쳐가 다르다고 설명해주셨다. 뜨거울때는 흰색 식었을때는 살구색 쪽으로 마셔보라고 하셨는데 소소한 재미가 있었다. 비스코티는 달달 짭조름했고, 개인적으로는 커피가 진하게 느껴져 아이스로 마시면 좋을 거 같았다.', 91, 23, 'GOOD', SYSTIMESTAMP);
