INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이덴티티커피랩'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '자주 이용하는 텤아웃 카페입니다 직원들 전부 친절하고 미드센츄리 라떼가 입에맞아서 그것만마시고있습니다. 특히 매장에 안경안쓰시고 살짝 덩치있는 남자바리스타님 너무너무 친절하시고 좋으시네요 칭찬하고싶어서 리뷰남깁니다. 테이크아웃 천원할인 참좋은거같아요 요즘같이 커피값비싼 시대에 잘이용합니다', 30, 1, 'GOOD', SYSTIMESTAMP);
