INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이덴티티커피랩'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '서교동카페 중 커피맛집을 추천해달라하면 감히 아이덴티티커피랩을 추천해드리죠,,커피 좋아하는 사람이라면 한번가지않는다는,,공간도 깔끔하구 이뻐요, 흠이라면 사람이 언제나 많다는거?ㅎㅎ커피진짜 맛있어요:) 더 많은 정보가 필요하다면 ‘유키키의 이모저모 일상일기’ 놀러오세요!', 44, 6, 'GOOD', SYSTIMESTAMP);
