INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이덴티티커피랩'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '매번 믿고 마시는 아이덴티티커피랩입니다! 오늘은 ✅카페라떼(미드센츄리)와 ✅브루잉커피(예맨 마타리 사예 무산소 내추럴)를 마셨어요! 아이덴티티커피랩의 미드센츄리 블렌드는 믿고 마시는 원두예요👍 꽃과 과일이 느껴지고 아메리카노, 라떼 모두 잘어울려요😊 이번에 마신 브루잉커피는 포도, 체리 등의 향미가 느껴졌고 무산소 프로세싱의 맛도 잘 느껴졌어요! 제대로된 브루잉커피를 드시고 싶으시다면 아이덴티티커피랩 추천해요🤩', 431, 48, 'GOOD', SYSTIMESTAMP);
