INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이덴티티커피랩'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '12월에만 맛볼 수 있는 워터릴리가 맛있네요 :) 커피가 맛있어서 원두도 구매했어요. 홍대입구 갈 일 있으면 또 들를 것 같아요!', 38, 8, 'GOOD', SYSTIMESTAMP);
