INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이덴티티커피랩'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '유명한 카페라고 하길래 가봤는데 너무 좋았습니당 친절하시고 커피도 너무 맛있어요ㅜㅜ 먼 지역에 있지만 냉큼 쿠폰도 받았네요.. 서울 오면 꼭 들릴게요!', 6, 5, 'GOOD', SYSTIMESTAMP);
