INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이덴티티커피랩'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '원두 품질이나 맛은 준수하지만 웨이팅 관리가 처참... 인원 구분없이 무조건 웨이팅 순서대로 연락한다고 함 웨이팅 시 카운터 자리 중 한 자리가 계속 남아있었고 한 시간 이후 연락이 와서 보니 동일한 자리 계속 남아 있었습니다 이해가 안가는건 메뉴 결제 중 뒤에서 1인 웨이팅 작성하는데 이미 테이블에 앉은 인원이 일행(1인)이라고 옆자리 앉으면 안되냐 하니 그건 또 웨이팅 순서 상관없이 앉혀주네요 그러면 저는 왜 한시간 기다린거죠?', 9, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이덴티티커피랩'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '내사랑 아이덴티티!!!! 세인트알리에서 충격적으로 맛있는 롱블랙을 마시고 한국에도 맛있는 커피가 있다는 자부심을 느끼기위해 ㅎㅎㅎ 바로 아이덴티티로~ 어휴!!!! 페루 라떼 몬가요♡♡♡♡♡  말그대로 미쳤네요 싱글오리진이 라떼에 이렇게 잘어울릴 일인가요? 라떼가 상큼하면서도 달달하면서도 크리미하면서도 산뜻하면서도 요거트하면서도 취즈하면서도 하튼 걍 미쳤어요♡♡♡♡♡♡ 드립두 맛있었는데 라떼가 워낙 강력해서 ㅎㅎㅎ 며칠내로 걍 또 마시러 올께요 ㅎㅎㅎ', 49, 2, 'GOOD', SYSTIMESTAMP);
