INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이덴티티커피랩'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '재재재방문!! 홍입 합정가면 생각나는 곳! 커피도 디저트도 맛있는 카페입니당♥️♥️ 여유롭고 한적한 오후에 향긋한 화이트오크+비스코티 먹으면 행복해지는 마법..!! 커피 한 잔 더 먹고 싶다면 디카페인 아아까지!! 제 최애메뉴에요ㅠㅠ 샌드는 달달하니 아아랑 잘어울리고 비스코티는 말해모해 맛별로 쌓아두고 먹고싶어요🥹 다들 꼭 먹어주면 되,,,🍀 담에 또 갈게용!!', 37, 0, 'GOOD', SYSTIMESTAMP);
