INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이덴티티커피랩'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '오랜만에 방문했는데..기억해주시고 반갑게 인사해주셔서 감사했어요~🙏🌿🌼 커피를  너무 예쁘게 정성스럽게 만들어 주셔서 한동안 계속 보고 사진으로 기록을 안 할 수가 없었어요~🌼🌿 건강하고 깔끔한 맛을 내기가 쉽지 않은데...너무 맛있었어요~☺🙏🌼🌿 가격대도 다른 곳보다 낮게 측정된 편이고 공간도 뷰도 너무 예쁘게 만들어 놓고 편안하게 시간 보낼 수 있게 만들어주셔서 감사드립니다~🙏🌼🌿', 109, 19, 'GOOD', SYSTIMESTAMP);
