INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이덴티티커피랩'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '처음에는 필터 두 잔, 그 다음에는 아메리카노, 소다 주문했습니다. 두 번째 음료 주문 할 때는 20퍼센트 할인도 해주셨습니다. 책을 읽거나 간단한 업무 하기에도 좋을거 같아요. 직원분들도 다정하시고 응대도 좋았습니다.', 10, 5, 'GOOD', SYSTIMESTAMP);
