INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이덴티티커피랩'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '커피 너어무 맛있어요..  ! 이번에도 카드에 적힌 향과 컵노트 전부가 잘 느껴져서 신기했습니다 보나마나 에스프레소나 다른 커피메뉴들도 맛있을 것 같아요 그리고 사진은 없지만 매장도 채광이 좋아서 밝은 느낌이고 바리스타분들도 왕친절하십니다! 커피를 좋아한다면 꼭 가보세요 서울에 산다면 매일 방문하고 싶어요', 101, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이덴티티커피랩'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '집에서 티티랩의 미드센추리 블렌드를 맛있게 먹고 있는데 매장에서의 경험도 정말 좋았네요. 커피도 디저트도 음료도 맛있고 직원분들도 친절하셨고요. 콜롬비아 라 팔마 & 엘 투칸 히어로즈 게이샤 락틱 워시드는 복숭아, 리치 향미도 잘 느껴지고 좋았고, 독특한 프로세싱 과정을 통해 락틱산이 많이 생성된거라 그런지 요구르트 같은 산미와 단맛도 느껴져서 독특한 매력이 있었어요. 그리고 화이트오크는 쫀득한 식감과 오렌지 리큐르의 향긋한 맛과 에스프레소 크림이 잘 어울러져서 맛있었네요.', 100, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이덴티티커피랩'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '사진은 막 찍었지만… 사실은 감동의 카페였어요. 다른 유명 카페에서 실망을 맛본차에 날씨도 춥고 집에 가기 전에 한번 들러보자라는 심정으로 들어갔거든요. 사진찍어대는 여성손님이 그득한 이전 카페와 달리 젊은 남성분들 가득 ㅎㅎㅎ 엄청 성실하고 친절한 스태프 분들과 컵노트 그대로의 드립커피에 감동하며 ㅠㅠ 라떼아트에 또 흐믓하며 정말 여유롭고 느긋하게 ‘커피를 즐겼습니다’. 기대하지 않았는데 디저트도 정말 놀랍게 맛있었습니다. 화려하고 먹기 번거로운 디저트 대신 한입씩 딱딱 먹기 좋은 미니 쿠키, 포크로 찍어 먹기 좋은 촉촉한 르뱅쿠키는 커피에 집중할 수 있도록 계산이 철처하게 되어있나 싶을 정도로 완벽했어요. 사진찍는 카페 아니고 진짜 카페여서 감사할 지경>_< 편안함 속에 철저한 철학이 느껴집니다.', 4, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이덴티티커피랩'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '영수증리뷰는 2번째지만 오늘 3번째 방문인데 스탬프 왜 오늘에서야 ㅠ 내 아까운 스탬프 4잔!!!!!! 안그래두 맛있어서 더 자주 마시고 싶은데 스탬프까지 찍어주시면... 더 열심히 와야죠 ㅎㅎㅎ', 19, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이덴티티커피랩'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '[아이덴티티커피랩/홍대입구] 기다렸습니다. 티티의 새 공간을!✨ 원두를 주문해서 맛보는 것도 좋지만 카페에 와서 공간을 누리는 일도 멋지니까요. 만드는 분의 성품이 들어가다보니 역시 아이덴티티커피랩의 분위기는 예쁘고 세련되었으며 무척 포근하네요. 커피가 맛있는 건 말할 필요도 없죠. 편안한 분위기와 친절로 응대해주신 바리스타님들의 서비스도 감사합니다. 창 너머로 보이는 티티는 마치 다른 세계같이 보이는군요🌿 와보신 분들은 아시겠지만 커피 맛도 넘사입니다. 다른 두 블렌드는 접해본 적이 있는데 처음 본 키치블렌드! 궁금했었는데 필터커피에서 눈을 못 떼겠더군요. 저는 결국.. 페루 아이스를 주문했습니다ㅎㅎㅎ 또.. 올 수 있겠지요..🥺', 28, 4, 'GOOD', SYSTIMESTAMP);
