INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이덴티티커피랩'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '단정하고 깔끔한 인테리어의 커피맛집! 연희동에서 서교동으로 옮긴 유명 카페로 커피가 특히 유명한 곳이어서 다들 필터커피를 마시고 있었어요 마감직전에 가서 시그니처인 커피플래터나 몇몇 필터커피는 품절되어서 커피쉐이크 마셨는데 시원하고 달달한 라떼 슬러쉬 맛이었어요 거의 만석일 정도로 핫플인 곳이라 당분간 못 오겠지만 다음에 가면 필터커피 마셔보고 싶어요🥲', 55, 14, NULL, SYSTIMESTAMP);
