INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이덴티티커피랩'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '처음방문했는데여  마지막오더시간이 곧이긴해서 테이크아웃 아아했는데여 직원분들 엄청 친절하시더라고여 테이크아웃은 천원할인되어서 3천원에  마셨어여  들어가는문도 크고여 스무스하게 들어갈수있고 안에 매장도 깔끔하고  조용히 마실수있는 분위기더라고여 다음엔 좀더 길게 마시다 가보려고여 ! 친절한응대가 커피맛도 좋았지만 더 기억에 남네여 ~~', 85, 15, 'GOOD', SYSTIMESTAMP);
