INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이덴티티커피랩'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '원두구매로만 접하던 카페에 와서 직접 마셔보니 감개무량 ㅎㅎㅎ  역시나 커피 진짜 너모너모 맛있네요!!!! 비스코티랑 라떼두 완전 맛있게 잘 어울리구♡  홍제동일땐  멀어서 못갔는데 이제 단골될 듯요^^*', 328, 80, 'GOOD', SYSTIMESTAMP);
