INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이덴티티커피랩'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '예전에 효창공원에 있을 때 한 번, 홍제역에 있을 때 한 번. 그리고 이번에 새로 오픈한 곳에 가봤는데요, 커피가 늘 맛있어요. 필터커피 종류도 많지만 그냥 아메리카노도 맛있어요. 산미있는 원두로 선택했는데 맛있게 잘 마셨습니다. 다음에 또 가면 좀 더 오래 있고 싶어요.', 8, 2, 'GOOD', SYSTIMESTAMP);
