INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이덴티티커피랩'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '깔끔하고 쾌적한 공간에서 더위 피해서 쉬었다 가기 딱이었어요. 커피 플래터 좋은 가격에 세 가지의 맛있는 커피 즐길 수 있어서 좋았습니다.', 59, 16, 'GOOD', SYSTIMESTAMP);
