INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이덴티티커피랩'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '새로 오픈 하시고 처음 방문인데 핸드드립 아주 신경써서 내려주시는 모습이 인상적 이었습니다. 봄베 내추럴 좋아하는 원두인데 산미가 너무 튀지 않고 밸런스와 단맛이 좋았습니다. 근처 오면 또 방문하겠습니다🙏🏼', 104, 24, 'GOOD', SYSTIMESTAMP);
