INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이덴티티커피랩'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '아이덴티티 커피는 ... 늘 감탄 나오게 하는 맛있는 커피! 맛있다 는 말보다 좀 더 좋은 단어를 찾고 싶네요. 항상 커피가 아름답습니다.', 3, 1, 'GOOD', SYSTIMESTAMP);
