INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이덴티티커피랩'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '극진하게 대접 받는 기분을 느낄 수 있도록 모든 직원분들이 굉장히 친절하고 상냥하셨습니다. 커피 플래터는 이미 커피를 좋아하시는분들도 즐기기에 충분한 메뉴인것 같아요 ! 🖤', 12, 3, 'GOOD', SYSTIMESTAMP);
