INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이덴티티커피랩'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '산미있는 커피 좋아해서 미드센츄리 핫라떼 텤아웃했습니다.  기다리는 시간동안 앉을수 있는 공간하고 테이크아웃 1000원 할인이 좋은거 같습니다. 잘마셨습니다', 3, 1, 'GOOD', SYSTIMESTAMP);
