INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이덴티티커피랩'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '옮긴 장소가 집에서 가까워서 좋은데 갈때마다 빈자리가 없어요.하지만 맛있는 커피때문에 자리 날때까지 기다립니다. 제가 정말 좋아하는 커피숍중 한 곳입니다.', 65, 14, 'GOOD', SYSTIMESTAMP);
