INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이덴티티커피랩'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '서교동 신상카페!!! 커피플래터가 있는 게 정말 신기했고 한 번에 세 가지 원두를 맛 볼 수 있어서 좋았음ㅎㅎ 직원분들 너-무 친절하시구 커피맛은 말해 뭐해요💖 단골카페 될 듯요', 36, 1, 'GOOD', SYSTIMESTAMP);
