INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이덴티티커피랩'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '커피값이 많이올라서 부담스러운데 테이크아웃 할인이 있어서 종종 이용합니다 산미있는 커피좋아해서 원두 선택할수있는부분이 좋습니다 잘마셨습니다', 84, 15, 'GOOD', SYSTIMESTAMP);
