INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이덴티티커피랩'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '영수증에 매장주소가 일치하지않네요  실제는 마포에 있는데  영수증은 경기도 고양시 일산동구로 적혀있습니다 테이크아웃 할인 좋은거같아요 양은 작은편이라 아쉽지만 커피맛은 산미있고 좋아요', 56, 12, NULL, SYSTIMESTAMP);
