INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아이덴티티커피랩'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '안스타 YouTube 이상순님 추천으로 갔는데... 인생커피를 만났어요! 바리스타님 세분 모두 세상 친절하시고 찐 커피 experts! 원두사러 또 커피 마시러 자주 갈께요!', 72, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '우와~ 주술회전 어쩔.. 이등신 너무 귀여워.. 판다그림도 너무 귀엽구.. 다행히 중간에 와서 너무 좋네요. 초6여아 아이가 좋아해서 콜라보 미션 뜨면 골라보는 재미로 나들이 합니다.. 이번에 시킨 음료는 너무 발랄하고 무겁네요. 그래도 초코케이크는 나름 고급져서 맛있어요.. ㅎ,ㅎ 다음에도 새로운 콜라보 나오면 또 놀러와야죠~ ㅎㅎ', 103, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '현재 니지산지와 명방 콜라보 카페가 함께 진행중인걸 알고 x에서 정보숙지 후 네이버에서부터 예약을 진행하고 방문하려 하였으나. 네이버예약 쪽에서 확인시 명일방주 콜라보카페 예약밖에 확인이 불가능 했습니다. 그러므로 니지산지 콜캎 입장에는 예약이 별도로 필요하지 않은걸로 판단되어 비예약후 매장을 방문하였지만, 예약을 하지않아 매장과 굿즈구매를 할 수 없다는 답변이 돌아왔습니다. 왜 예약을 하지않고 방문을 하였냐는 짜증스러운 직원의 태도도 난감했지만 처음뵙는 손님에게 "주문을 하셨으면 진동벨을 챙기셨어야지요;;"라는 짜증스러운 직원의 행보는 고객으로써 어떻게 받아들여야 하나요? 타지에서 방문하였음에도 사전에 이러한 정보가 온라인상으로 기제되어있지 않아 빈손으로 돌아오고 짜증스러운 직원의 언행은 정말불쾌하네요', 4, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '즐겁게 잘 다녀왔습니다. 그런데 그라떼 줄이랑 카페 이용줄이랑 잘 구분해 놔야 할 것 같아요. 저도 그렇고 다른 분들도 이 줄이 맞아? 저 줄은 뭐야? 이러면서 허둥지둥 했어요. 그리고 개인적인 사담인데 왜 시부야 사변에 스쿠나가 없는 거죠..?🥺', 52, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '콜카 첨 갔는데 재밌었어요! 음료도 기대 안 했는데 생각보다 맛있어서 놀람ㅋㅋ 종이코스터지만 특전 최애캐 나와서 더 좋았습니다:) 판매 굿즈들이 랜덤 위주인 건 아쉽네요ㅠ', 5, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '남자 직원이 묘하게 불친절하심... 그리고 테이크 아웃 음료 쓰레기를 버려달라 했더니 건물 에스컬레이터 옆 쓰레기통에 버리라고 하셨는데... 2사진 이게 맞나요 아무리 봐도 얼음과 크림이 들어있는 플라스틱 컵을 버릴만한 쓰레기 통이 아닌데... ㅠ  그밖에는 콜라보 귀여웠어요. 근데 맛은 하나도 없음 ㅋㅋ 그냥 눈호강 용~', 17, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '매장은 넓은데 의자 없는게 너무 아쉬워요. 그리고 아츠시 초코우유 너무너무너무 맛없습니다.. 알 수 없는 박하향..? 초코 우유가 아니였어요. 😭 콜라보 카페에서 식음료 맛은 기대하면 안되는 걸 알지만 가본 콜카 음료 중 가장 최악이었습니당..', 79, 18, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '- 케이크 맛있었음. 진짜 의외 - 봇치 너무 귀여움. 잘 꾸며둠 - 굿즈 계산 직원 친절함 - 내부 좀 좁음. 사람 많으면 예약해도 웨이팅 할 수 있음 - 음료/케이크 좀 비싼편임 - 내부는 네이버 예약해야 이용 가능함 - 영수증 하나로 굿즈 한 번 구매 가능함. 가챠 실패하면 메뉴 새로 시키고 다시 구입해야 함 - 굿즈들 다 가챠임..; 이건 좀 서운 봇치 입덕하자마자 카페를 가다니 그래도 행복했다', 43, 5, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '등신대도 모두 너무 이쁘고 책상도 이뻤습니다만… 한 직원 분이 너무 불친절하더라고요. 제가 웬만하면 다 그럴 이유가 있으셨겠지 오늘은 날씨가 너무 더워서 그러시겠지. 라며 그러려니 넘어갈테지만 이건 너무하다 싶어서 처음으로 리뷰까지 써봅니다. 우선 말투에서 무례함이 느껴집니다. 절대로 손님을 응대하는 직원 말투가 아니에요. 설명도 들으라는 건지 말라는 건지 모르겠는 말투도 응하시곤 대뜸 저에게 가르치려 드는 말투로 짜증내며 뭐라고 하셔서 당황했네요. 제가 너무 예민한가? 싶어서 그 상황에 있던 친구에게 물어보니 친구 역시 말투가 너무 무례해서 말투 왜 그러냐 말하려다가 말았다고 하더라고요.. 좋아하는 캐릭터들을 보게 되어 뜻깊은 경험이었지만 이런 불친절 탓에 속상한 기분이네요…', 38, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '은혼-주술회전-문스독까지 세번째 콜라보 카페 방문인데 항상 맛은 없어도 너무 없어요... 이렇게 맛없기도 힘들겠다 싶을 정도고요 ㅎㅎㅎ 이용 시간이 50분으로 짧은데 음료나 굿즈나 계산대가 하나고 굉장히 느려서... 기다리는 시간만 길었고 메뉴가 나왔을 땐 이미 30분이라서 후다닥 사진 찍고 후다닥 먹고 굿즈 사고 나오니까 종료 시간이었어요. 다른 데서 하는 콜라보 카페도 종종 가는데 이용 시간은 제일 짧고 계산 시간은 오래 걸려요.', 41, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '메뉴는 무난한 맛. 고죠 음료 달달하니  좋아하는 맛이었어요 디피 귀여웠는데 포스터가 다 였구요. 굿즈도 생각보다 구입할만한것은 없어 보였어요. 아크릴 코스터로 업그레이드 했는데 이게 제일 괜찮았어요. 재방문 하려고 합니다.', 19, 2, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '메뉴, 굿즈 구매하는데 30분걸렸고 주문한 메뉴 나오는데도 20분 걸렸어요(메뉴 하나 잘못나와서 더 기다림) 이용시간이 50분인데 기다리는데만 시간 다 갔네요.. 이용 인원을 줄이던가 포스기를 더 놓든가 해서 운영방식을 바꿔야할것같아요 음식은 맛있었고 직원분들이 친절한건 좋았어요', 100, 26, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '제가 좋아하는 장르 콜라보 할 때 마다 가는데 진짜 음료가 너무너무너무 맛없어요 ㅋㅋ... 그나마 커피 메뉴가 제일 맛있고 요거트 파우더 들어간 음료는 가루가 느껴져서 텁텁하고.. 음료 퀄리티 좀 높여주세요 제발 실험적인 이상한 음료 적당히 만들고', 104, 21, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '늘 앉을 자리는 없는…그 곳 https://blog.naver.com/comma_make/223876498345 < 상세후기는 여기', 2, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '애니메이트 카페 잠실점 첫 오픈날 봇치 콜라보 카페 예약해서 다녀왔어요..! 🩷🎸 애니메이트 제일 안쪽에 카페가 위치해 있고 규모는 기존 홍대점 규모 보다도 작습니다. 역시나 서서 먹어야 하구요 주문은 키오스크 주문으로 운영됩니다. 특전은 메뉴 나올때 같이 받을 수 있구요 테이크아웃이 가능하지만 입구 위치가 좋은 편이 아니라 어수선한 느낌.. 그래도 봇치 콜라보 카페 좋았습니다! 키타가 3키타 ☺️❤️❤️', 72, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '🩷 생각보다 애니메이트 자체가 좀 작아서 혼잡했습니다.. 직원 분들도 넘 바빠 보이시고 입장 어떻게 해야되는지 제대로 안 알려주시는 분이 많아서 당황스러웠어요ㅠ 렌티큘러 카드도 소진됐다는 말을 안 해주셔서 좀 아쉬웠습니다.. 직원 분들이 알아봐야한다고만 말씀하시고 재고 파악은 바로 안 해주시고 결제할 때 카운터로 가니까 그제서야 조심스럽게 알려주셔서.. 전체적으로 다들 다른 일 하다가 카페 들려서 정리하시고 분담이 제대로 안 돼있는 느낌이라 너무 어수선했어요ㅠ 🩷 케이크는 냉동이긴 한데 은근 먹을 만 했습니다,, 키쿠리 음료 비쥬얼이 많이 아쉬워요ㅠㅋㅋㅋ 맥주가 맞나..? 니지카 음료가 오히려 맥주 색감인 www', 26, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '음식은 뭐 항상 콜카 그 음식이고 직원분들 다 친절하셨어요 주문도 친절하게 받아주시고 물어보면 친절하게 답변해주시고^^ 근데 음료 주시는분? 이 분이 저 특전도 주셨는데 불친절 하시더라구요 ㅠ 다른분들이 매니저라고 부르시던데 그러면 매니저분이라는건데 이렇게 불친절해도 되나요 제가 싸인하고 펜드릴라 했더니 귀찮고 짜증난다는 듯이 그건 앞에 두세요 하고 휙 가버리시더라구요 ㅠ 손님 상대 하기 싫으시면 뒤에서 음료 만드시면 되실꺼 같아요!☺️', 127, 24, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '제 최애를 보러 갔는데...제 최애가 너무 귀여웠습니다 가성비는 모르겠고 그냥 쵸소우가 너무 귀엽습니다 쵸소우야150년전부터너를좋아했어나랑사귀자 ㄴ 이제 누가 형아 해주냐', 47, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '초5 여아 아이와 갔다왔어요.. 자리도 바로 했는데 원형이어도 다 같이 서서 즐기니깐 은근 재밌어요. 예약해서 가야 되지만. 그래도 사람들한테 치이지 않아서 좋구요. 직원분들 친절하구요. 음료도 맛있어요.. 그냥 막 골라온 쿠키도 너무 이쁘구요. 위에 포스트랑 쿠키랑 세트라서 더 기분도 좋았어요. 애니이야기 몰라도 괜찮아요.. 너무 즐겁게 놀다왔어요. 다음 캐릭터 나오면 또 가고 싶네요.. 오늘은 날씨도 좋아서 배경도 이쁘게 나와서 너무 좋아요. 대신 약과쿠키 넘 딱딱해서 조심조심 씹으세요~ 딸기케이크 품절이라서 아쉽다는거? ㅋㅋ 매장도 깔끔하고 굿즈도 종류별루 많고 가격도 적당해서 딱 좋았어요. 너무 좋은 인상만 받아서 더 좋았어요.', 20, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '좋아요~ 매장 안쪽에 한참 들어와야 하네요 오실 분들 참고하세요~ 봇치 굿즈는 영수증당 한 번밖에 살 수 없는 점이 좀 아쉽습니다~', 86, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '첫 날, 첫 시간대 방문이라 그런진 몰라도 엄청 혼잡하고 응대도 잘 안됨 30분 넘게 기다려서 음료 겨우 주문했는데 주문한게 이용시간 넘어서까지도 안나왔음,, 원래 11:50까지인데 12:05에 음료 겨우 나오고 10분 빨고 쫓겨남ㅋㅋㅋㅋ 제대로 구경도 못하고 굿즈만 사고 튀어나옴 에휴', 7, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '새로 오픈했다길래 홍대 안가고 잠실로 와봤는데 너무 좁아서 아쉽네요ㅜㅜ 테이크아웃 전용인 건 알고 있었는데 막상 와보니 주변에 아무것도 없고 밖으로 나가서 먹을 수 밖에 없는 것도 아쉽네요 (토요일 하루만 제한된거지만) 매장으로 재입장이 불가능해서 밖으로 나갈 수 밖에 없음 그래도 직원분들은 전부 친절해서 좋았습니다', 41, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '..애니메이트 자체가 지하에 있어서 불쾌한 냄새가 납니다.. 심지어 순환률이 빠르지만 그 불쾌한 냄새를 맡으며 기다리는게 좀 힘들어요… 하지만 직원분들도 친절하시고, 빠르게 준비하시려고 하는 모습이 보이는게 좋았어요.. 아직 초반이라 우왕좌오아하지만 후에는 잘 될 것 같습니다.', 38, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '4인석으로 예약해야 원모양 얼굴 테이블 이용 가능,,, 랜덤키링 두개 깠는데 료만 두개나왓어요 키쿠리 있으신분 교환해요,,,,,,,,🥹🥹🥹🥹🥹🥹', 89, 18, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '모든 음료가 내 입맛에는 괜찮은 듯. . (6종류  주문후 시음함 ).망고 음료는 좋다는 평이 들립디다. 약과는 엄청달달! ! 메뉴음료 한잔당 컵홀더 1개증정받음 ㅡ컵홀더가 매우 튼튼ㅡ 최애로 교환함. 카페이용은. 먼저 입장할 때 받은 메뉴종이판에 입장때  받은 연필로 음료당 주문할 숫자를 체킹한 후 계산대에서 메뉴만 주문합니다. 그리고 50분 이용시간전에. 굿즈를 바구니에 담아서 굿즈계산대 메뉴구입 영수증과 함께 보여주면 굿즈를  계산 할 수 있음 그리고 특전받는 곳으로 가서 특전을 받음 (메뉴 구입 영수증 하나로 굿즈 1번만 구입) 메뉴계산대, 굿즈계산대, 특전받는곳ㅡ 3번 방문함 ㅡ직원분 모두 친절하셔요. 5만원 주문시ㅡ2만원당 코스터2장+ 3만원당 엽서1장+5만원장 등신대추첨권 1장 받습니다.', 6, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '긴토키의 "동심으로 돌아가라 요녀석아" 당분 MAX 딸기 드링크 ~ ㄴ위에 퍼먹었을땐 맛있던데 ㅎ ㄴ 섞으니까 약 맛남 ~ㅠ 엘리자베스의 정체불명 푸딩 ~ ㄴ 위에는 맛있는데 맨 밑에 깔린건 맛 없음 ㅠ', 43, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '소금 레몬 음료는 놀라울 정도로 맛이 미묘했는데 청포도 에이드는 맛있었어요. 음료 세 잔 시켰는데 빨대는 두 개 뿐이고 샌드위치 메뉴에 포크 없는 게 (셀프인데 못 봐서 못 챙겼을 수도 있지만 별도의 안내를 받지 못했습니다) 조금 당황스러웠지만 그래도 잘 머물다 왔습니다. 굿즈가 귀여웠어요.', 10, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '깜박하고 신분증을 지참하고 가지 않아서 입장까지 오래걸렸는데 직원분께서 끝까지 천천히 기다려 주셨어서 정말 감사했습니다 ㅠ.ㅠ💗 비록 좁은 공간이었지만 예쁘게 꾸며져있어서 제한시간동안 정말 좋은 시간을 보낸 것 같아요!', 12, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '생각보다 맛있었어요 히지카타 커피는 섞어먹지 않으면 밍밍하지 않고요 위에 아이스크림이 괜찮았네요 그리고 카구라 음료가 달지 않고 맛있었어요!', 94, 19, 'GOOD', SYSTIMESTAMP);
