INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '은혼 20주년 기념 콜라보 카페 방문 딸아이가 좋아하는 은혼때문에 홍대 애니메이트 카페 방문 다른 곳에서 맛볼수 없는 음로에 굿즈까지 아이가 좋아하니 그걸로 만족^^', 46, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '봇치더락 스페셜이벤트라 가봤는데 예약하니 편하네요. 굿즈도 다양하고 음료나 디저트가 귀여워요. 또 가서 랜덤아이템 쓸어올까 생각중이에요.', 60, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '직원분들 친절하시고 봇치로 한가득 꾸며져있는 카페 내부가 맘에 들었습니다 음료맛은 😅🙂‍↔️ … 그래도 조았어요 좋아하는것이한가득', 24, 0, NULL, SYSTIMESTAMP);
