INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '봇치 팬들이면 진짜 좋아할만한 재미난 구성을 가지고 있어서 좋았어요! 굿즈도 예쁜 것들도 많고.. 강추드릴 수 있을 거 같아요!', 24, 3, 'GOOD', SYSTIMESTAMP);
