INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '콜라보 카페인데 너무 별로임 음료 맛 없는 거야 둘째치고 걍 뭐지? 영상 틀어주는 거 화질이 너무함 해당 애니메이션의 노래도 안 틀어주고 뭐지..? 왜 하는 거지 싶음 왜 하는 거임 한국에서? 첨 가보는건데 다음엔 한국에서 하는 콜라보카페 절대 안 갈듯', 1, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '중요하게 생각하는 사람하고 같이 놀러오기 참 놓았습니다~ 음료는 서로 이게 뭘까 갸웃하면서 마셨었네요 ㅋㅋㅋㅋ 그래도 좋은 시간이 되었다 생각합니다.', 37, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '카무이 음료 은근 맛있어요~ 커피는 약간 보리차 맛인데 먹을만하대요 온 순서대로 번호표를 나눠주고 원형테이블은 그 번호대로 탁자가 달라져요.', 37, 1, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '키드 러버인 콜라보 방문했어요🩷❤ 진짜 캐릭터 너무너무~~~이쁘고 귀여워용🥰 음료도 너무맛있고 너무좋았습니당😍 키드님❤진짜 너무 귀엽네용ㅎㅎ(ฅ’ω’ฅ)♥ 코난 극장판도 너무 재미있고 시크릿이있어서 진짜놀랐어용ㅎㅎ다시 보러갑니당(๑・ω-)～♥”', 2, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '전부 스탠딩 좌석이였고, 직원분들이 정말 친절하셨습니다. 하지만 키링, 스티커, 캔뱃지까지 몇개 빼곤 다 랜덤 상품이였습니다. 그리고 매장이 조금 협소했지만 그래도 쾌적했습니다.', 53, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '직원분들 다 되게 친절하시고 혼자 4인석 이용했는데도 딱 만족했네요. 일찍 간다고 좋은 자리 골라 앉는 게 아니라 넘 좋았습니다 :) 굿굿 (신분증을 놓고 와버려서 당황했는데 짜증 한 번 안 내고 너무 밝고 다정히 기다려주신 직원분들,, 너무 감사했어요)', 32, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '우열을 가리기 힘들지만 음료중에선 청포도가 제일 나앗던 것 같아요 굿즈는 꼭 한번에 구매하세요!! 하나 사고 더 사려다가 빠꾸 먹었어요 두번째부턴 테이크아웃 하면서 사야된다네요 알고 계시면 좋을 것 같아요 아이나나 콜캎이라니 청국장음료가 나와도 행복하게 먹을 수 있어요 애니메이트 감사합니다💙💙', 31, 10, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '즐겁게놀다갑니다.예약제에서 자율입장으로바꼈네요 얼른 티켓풍특전이 입고됐으면좋겠습니다ㅜㅜ 랜덤특성상 원하는 코스터가 안나와서 계속가고있는데 티켓풍특전도 너무늦게오면 힘들꺼같아요. 그리고 의자좀진짜 놔줬으면좋겠어요 옆에 애니메이트 굿즈쇼핑하느라 계속서있어서 힘든데ㅜㅜ 카페에서까지 서있어야하니 다리가 너무아프네요.', 2, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '이번에 하이큐 콜라보를 한다고 해서 방문했습니다. 하이큐 팬으로써 꼭 가봐야 할 콜라보 카페였어요. 음료 시키면 주시는 코스터도 그렇고 아기자기하고 예뻐서 맘에 들었습니다. 식음료 구매하면 살 수 있는 애니메이트 한정 굿즈도 있어서 구매했는데 정말이지 맘에 드는 굿즈였어요❤️ 콜라보가 끝나기 전에 다시 방문하고 싶네요 😭', 7, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '좋아하는 캐릭터 콜라보 카페로 방문하였습니다. 직원분들 친절하시고 독특한 메뉴가 인상적이었습니다. 나쁘지 않은 음료와 샌드위치, 샐러드로 제공된 상추가 굉장히 야들야들해서 맛있었네요. 다만 의자가 없는 점이 너무 아쉬웠습니다... 의자를 구비하는 인테리어로 전환하면 더 만족스럽지 않을까 싶네요.', 40, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '좋아하는 장르의 애니메이트 콜라보카페를 정식으로 해주셔서 감사합니다. 일본애니메이트카페 그대로의 메뉴 고증?을거친거겠지만 레몬드링크가 많이 아쉬워요 재료몇개빼도맛있을듯ㅠㅠ 음식보단 디저트 파르페 못 갖고온것도 아쉽고요 매번다른장르포함해서 콜라보카페 느끼는거지만 낮은 식탁과 의자 너무필요합니다. 서서먹는거 디스크환자에게는 고문이네요. 어차피 이용시간제한도 있는데 적극반영해주셔서 개선됐으면합니다. 하루빨리한국한정특전이 입고되길바라며... 다음부턴 준비성철저하게하셔서 바로바로특전주셨으면좋겠어요ㅜㅠ 카페이용당일날특전없다고 공지때린건 좀 ㅠㅠ 노쇼방지차원에서 이번 아이나나 콜카부터 선예약금받은거같은데...', 30, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '콜카 처음이라 신기하고 재밌었음~ 예약안한 사람들이 계속 들어오는걸 앞에서 관리가 안되는게 살짝 아쉬운 부분? 가볍게 덕심 채우면서 즐기기 좋았다!', 82, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '첫번째 짤처럼 사진의 메뉴가 이루어진 것 같아서 좋았어요 맛은 보장 못하지만요ㅎㅎ 꾸민게 뭔가 좀 부족해보였지만 그래도 좋은 경험이었습니다! 다음에도 은혼 콜라보 카페 해주세요🫶🏻', 18, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '예약하고 이용했습니다! 코난 카페는 처음인데 재밌네요~ 괴도키드 음료와 디저트 잘 먹었습니다! 굿즈도 살 수 있고 코난 극장판 광고가 계속 나와서 좋았어요!', 73, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '매장 내 모든 자리에 의자가 없는 것이 가장 치명적인 단점입니다. (ㅠ_ㅜ;) 다른 부분은 큰 생각 없었고, 좋아하는 분들끼리 모여 좋아하는 것을 나누는 모습을 볼 수 있어 좋았습니다.', 2, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '케이크는 중간이 없이 너무 달며 드링크는 섞이지 않아 아무런 맛도 없으며 인테리어는 입간판에 브로마이드 몇개 해놓은 수준, 의자는없고 굿즈는 랜덤,총체적 난국', 7, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '좋아하는 장르 콜라보 카페에 방문하여 좋았어요~  음악도 나오고 재밌었어용. 청포도 음료랑 레몬 마셨는데, 청포도 음료는 맛있었어요! 테이블에 의자가 없어서 불편했습니다😥 테이크아웃 하는 게 나을 듯..? 티켓풍 카드 준비가 안 되어서 다시 받으러 가야 하는 게 아쉬워요. 이용안내에 대해서 직원분들이 친절하게 응대해주셨습니다! 좋은 추억으로 남았습니다🩵', 39, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '아이나나 콜라보때 친구랑 다녀왔습니다 2인이어서 별생각없이 바테이블했는데 그냥 4인용 동그란 테이블로 예약하는게 나을것같아요! ㅠㅠ(사진은 좌석 비어있길래 사진만 후다닥찍은거) 블로그로도 리뷰남겼으니 자세한건 여기로~~ https://m.blog.naver.com/jungfinen/223567698235', 11, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '직원분들도 친절하시고 음료도 생각보다 맛있어요! 그런데 제가 2번째 방문인데 저번에도 그렇고 포토카드를 연속으로 주시는건지, 중복이 너무 심합니다...  저뿐만 아니라 주변분들도 2,3중복 나온분들이 꽤 많았어요. 주실때 조금만 섞어주심 좋을 것 같아요 ㅜㅜ', 33, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '지인 2명이랑 방문했습니다. 최애가 선전한 음료를 마실 수 있어서 좋네요>< 직원분들도 친절하셨어요! 아이나나 콜라보 기획 들여와주셔서 감사합니다. 다만 명색이 카페인데 의자가 없다는 사실은 많이 아쉬웠습니다ㅠㅠ 뭐 미리 안내됐었고 알고 간거라 감내해야하는 부분이었지만....수요일부터 콜라보 시작이었는데, 일요일임에도 특전이 마련 안됐다는 점이 의아했습니다. 또 다시 방문해야 받을 수 있다니.....아이나나 좋아하시는 분들이랑 같은 공간에 있을 수 있어서 힐링했지만 특전 관련해서는 속상해요ㅠ', 43, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '음료는 작년보다 더 맛있었습니다~ 디저트가 더 있었으면 하는 바람... 그리고 굿즈 제한이 있는데요 그 제한 안에서 처음구매하면 더 못사게 하지말고 구매 더 할수 있게 해주면 좋겠네요~ 언제 또 올줄 모르는데 원하는 굿즈가 안나오면 조금 속상할듯하네요! 아 그리고 퇴장할때 금액별로 하는 특전은 좀 중복이 많네요 4만원 당 주는 카드도 3장다 집사 나왔구요.... 2만원당 받는 것도 8장 중 집사 모미지가 5장이라구요:... 아무리 랜덤이지만 이건 중복이 너무 심하네오....', 64, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '제가 콜라보 카페를 자주 와본것은 아니지만..원래 의자가 없나요??^^;; 특전이 구비가 안된점이라든가 조금 아쉬운점은 있었으나 분위기가 넘 좋았습니다. 음료수는 아래에 젤리가 깔려있는 무난한 아이스 홍차를 마셨습니다.', 37, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '코난과 콜라보해서 방문! 전메뉴를 다 시켜본 사람으로서 벚꽃음료 빼고는 다 마실만 합니다! 하지만 벚꽃은… 크림 자체는 맛있는데 음료랑 섞이니 너무 느끼했어요. 다른 음료는 맛있습니당', 94, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '의자가 없는 게 너무 충격적이였어요 빨리 먹고 나가라는걸까요? 몇걸음만 가도 다른 카페 인테리어 구성이 보일텐데 신기하네요 음료와 음식이 4개씩 있는데 청포도 라임 드링크는 먹을만했지만 솔티 레몬 드링크는 먹고 깜짝 놀랐어요 굿즈도 800엔이라고 대놓고 써있는데 인건비 통관비 다 생각해도 가격이 좀 아니지않나싶네요 특전도 미리 준비되어있지 않았고 그럼 다른 지역에 오는 사람들은 특전 받으러 두 번 와야겠네요 일하시는 직원 수도 적어서 메뉴가 나오는데 오래 걸렸습니다 장르 좋아하는 사람이라면 가겠지만 여러가지로 자주 올 곳은 아니네요', 119, 25, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '콜라보 카페는 처음인데, 생각보다 더 좋았어요🧡 좌석 모두 스탠딩이었기에, 오래 서있는거 싫어하거나 어렵게 느껴지시는 분들은 고민 해보셔야 할 것 같아요. 밴드팬의 짬이있어, 저는 괜찮았습니다 :) 주문한 메뉴도 엄청 빨리 나와요 5분안에 나온듯! 직원분들도 친절하셔서 좋았습니다🥰 기대를 낮추고가서 그런지는 모르겠지만, 정말 괜찮았어요. 시간되면 또 가보려고요! 근데 굿즈는 개비싸용🖤🖤', 90, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '오늘 콜카 너무 좋았어요! 단호박스프 너무 맛있었고, 켄마 음료도 맛있었어요! 특전도 켄마가 나오고 홀로그램도 켄마 나오고!! 브로마이드.. 그게 리에프여서 조금 슬펐지만 리에프도 좋으니까요!! 암튼 한 번 더 방문할게요😊', 17, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '안내주신 직원분들과 주문 받으시는 분들 모두 친절하시고 좋았습니다!! 매장도 청결한 편이고 제가 착각한 부분도 친절히 안내주셔서 정말 감사드렸습니다. 단지 음식이 맛이 너무 없었어요. 콜라보카페 특성상 퀄리티는 떨어진다 해도 이건 보안을 해주셨으면 좋겠습니다. 조리 직원 문제가 아니라 메뉴 선정 자체가 어떤 자신감으로 한건지 모르겠네요. 이번 메뉴는 힘이 많이 들어간 것 같습니다. 주문 메뉴: PLAY GAME!!! 솔티 레몬 드링크 네버그린 레몬 페퍼 펜네 냉파스타', 18, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '내부가 너무 예쁘게 잘 꾸며져 있어서 좋았고 랜덤인 굿즈가 많았는데 전 히나타 잘 나와서 만족했어요 확실히 실물로 보니까 더 예쁘고 방문하길 잘한 것 같아요 응모 이벤트도 있었는데 제발 당첨되면 좋겠네요 카라스노 드링크는 예상보다 괜찮았어요', 62, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '콜라보카페 때문에 갔는데 입장때 직원분이 실수로 체크 안하신 부분을 다른 직원분께 고객이 확인 안해준거라고 얘기하셔서 전달받으신 직원분이  저와 친구 실수로 생각하시고 약간 진상 대하듯이 일처리 하시더라구요 많이 불쾌해서 빨리 나왔습니다.  큰 돈은 아니라지만 왜 제 돈 쓰고 제가 불쾌해야하는지도 모르겠네요.', 4, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '7월 26일부터 8월 25일까지 명탐정 코난 카페 합니다. 미란이 음료는 작년이 훨씬 더 맛있었고요 장미 음료도 그저 그랬어요', 424, 97, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '이용 안내의 설명이 너무 미흡해서 카페를 이용하는데 기분이 좋지않았네요ㅠ 굿즈 1인 n개 구매 가능이라고 설명되어있으나 n개 미만으로 굿즈 구매하고 n개에 맞춰서 또 구매하려고했더니 영수증 1개당 1번밖에 사용 못한다고 하네요 (n개를 구매해도 그 이하 갯수를 구매해도 그 영수증으로 확인 받았으면 끝) 굿즈 구매를 또 하려면 새로운 음료를 결제해서 영수증을 새로 받으라는데 이게 무슨 심보인지ㅠ 기분 좋게 갔다가 기분 팍 상해서 돌아왔네요', 14, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '위치를 이전하고 새단장 했다길래 좀 나아진 줄 알았는데... 대체 이용시간 제한도 있는 예약제인데 왜 의자를 안두는 거죠? 입장 전에도 줄서서 기다리고, 들어가서도 서있어야하고. 심지어 이 날씨에 에어컨을 왜 제대로 안틀어요? 줄서는 곳이 더 시원하네요. 덥고 다리 아프고 진짜ㅋㅋ 어차피 제한시간도 있는데 빨리빨리 내보내야 하는 이유라도 있는지? 게다가 특전 준비가 안 된걸 오픈 전날 sns로 공지 하나 띄우면 다인가요? 예약자들한테 개별 안내를 주던가 해야죠... 교환권으로 주는 것도 화가 나네요. 시간과 교통비를 왜 고객이 낭비해야 되는지? 배송을 해주던가 해야 되는 거 아닌가요. 오타쿠 장사 참 쉽네요.', 16, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '프로세카 콜라보카페 다녀왔습니다 메뉴가 다양하고 다른 콜라보카페에 비해 퀄리티가 좋아요 인테리어도 잘 해놨고 다양한 이벤트도 준비되어 있어 좋은 추억 만들었습니다 무엇보다 직원분들이 바쁜와중에도 굉장히 친절하셔서 기분 좋았어요!', 116, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '코난 전시회 보러 가는 김에 예약해서 방문했는데... 원래 콜라보 카페가 거의 그런듯 맛은 그냥 그렇다 근데 아이스크림이 다 녹아 있는 거는 좀...🥲', 29, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), 'ㅋㅋ인간적으로 카페라면 의자는 있어야..ㅋㅋㅋㅋ 의자 없는 카페는 처음이었네요.. 하루종일 돌아다니느라 다리 아팠는데 또 서서 한시간 있었음... 하이큐 재밌게 봐서 카페도 예약까지 해가며 와본건데 너무 충격이에요.. 디저트도 다 녹아서 나왔음ㅎ 맛도 그닥 ..ㅋㅋ', 48, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '아쉬운 점이 많습니다 일단 의자가 없어서 불편한거 있고 테이블이 작아서 혼자나 2명이 적당하더군요 그 이상이면 따로 예약하는게 좋습니다 음식은 중간이고.. 계산하실때 신중한게 하시기를.. 제가 실수로 물건 잘못잡아서 바로 환불후 재구매 신청하니 고객단순변심으로 안된다고 합니다 저의 실수이기는 하지만 시간이 많이 지난것도 아니고 바로 저의 뒤팀 계산할 정도 시간인데 이런점에서 단순변심이 아닌 실수인데 저의 실수기는 하지만 매장 나갔다 온 것도 아니고 구입을 안하는것도 아닌데 이정도는 해줄수 있다고 보거든요 조금 그랬습니다', 84, 11, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '4인 테이블 너무 작습니다… 트레이가 2개 올라가면 꽉차는데 이게 4인 테이블이 맞나요? (심지어 흔들림ㅜㅜ) 그리고 의자가 없다니 진짜 말도 안됩니다. 일본 애니메이트카페 만큼을 바라는 게 아니에요. 솔직히 음식 맛잇게 먹겠다고 가는 것도 아닌데 좌석에 의자도 없다? 배짱 장사가 너무 지나칩니다. 개선하세요;;', 8, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '메뉴가 메뉴판에 있는 퀄리티랑 다른 느낌이라서 당혹스럽지만 처음에 갔던 날과 달리 2주년 기념 디저트 플레이트랑 2주년 기념 드링크를 마시게 되서 좋았네요 다만 아쉬운건 제가 받은 특전 중에 코스터 빼고 나머지 것들이 맘에 안 들었습니다', 33, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '너무 좋아요 여전히 의자는 없지만 전에 열었을때 비해 행사가 많았어요 굿즈들도 예뻤습니다 4만원 이상 구매시 주는 티켓도 디자인이 마음에들어요', 21, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '하이큐 콜라보카페 잘다녀왔습니다 음료맛은 음.. 굿즈가 너무너무 귀엽고요 이것저것물어봤는데 직원분들이 친절하게 알려주셨어요 감사합니다~', 47, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '진짜 팬심이 없으면 가지마세요 예약했었는데도 줄 서야 되고 의자도 없도 어떻게 카페라고 할수 있을까요 ? 게다가 에어컨이 하나도 안 시원하고 안 트는거 같아요 그래도 특점하고 굿즈는 운이 좋게 최애가 나왔으니 다행입니다 진짜 오타쿠의 돈을 버는게 너무 쉽네요', 14, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '처음이자 마지막 애니메이트 카페 홍대점에 다녀왔습니다! 직원분들이 너무 친절하시고 매장도 깔끔하고 음악도 좋고 그리고 음료가 다 너무 맛있게 마시고 왔습니다!! 너무너무 좋았습니다! 다음에도 플레이브 한다면 다시 오고 싶어요!! 💙💜🩷❤️🖤', 3, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '예전부터 그랬던건 알지만 진짜 내내 서있어야 하는거 너무 불편합니다 의자만 생기면 좋겠네요; 파스타 같은 음식 메뉴도 있는데 그걸 서서 먹어야 합니다', 45, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '앉는 곳 없는건 뭐 나쁘진 않았는데 음료가 너무 밍밍해서 별로였어요 아무리 콜라보 카페라서 맛은 기대하지 않는다지만... 특전도 굿즈도 다 예약수령이고 이정도 물량도 예상 못한 주최측이 좀 안일한게 아닌지... 다시 와야되는게 귀찮아요', 47, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '어렵사리 예약까지 하고 갔는데 사고 싶었던게 하나도 없어서 너무 어이없었어요ㅜㅜ 예약은 했지만 지방에서 오는 손님들 너무 허무하시겠어요..물건이  빠지면 바로바로 채워 주심 안되나요ㅜㅜ 의자가 없어서 진짜 너무 힘들었어요 직원분들은 다른 후기보다 오늘은 친절하셨어요 가격에 비해 진짜 음료도 그닥이고 일년에 한번인걸 감사해야 겠어요', 27, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '음료 위에 올려진 데코레이션이 3일차인데도 준비가 안됐다니....더 신경 써야 할 것 같음 사과 음료 진짜 맛있어서 숟가락 받아서 다 퍼먹어야 합니다.', 107, 25, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '플레이브 콜라보 카페 다녀왔어요😽 건물 안에 있는지 모르고 밖에서 한참 헤매다가 들어갔네요…ㅎ 애들 얼굴을 크게 볼 수 있어서 좋았어요! 일러 굿즈가 대다수고 거의 다 랜덤으로 뽑는 거라서 더 재밌었어요. 현장 교환도 많이 하시더라구요. 음료는 사진 찍는 동안 얼음이 다 녹아서 그런지 딱히 맛있다는 생각이 들지는 않았지만 케이크는 아스테룸이라는 설정이 귀여워서 맛있게 먹었어요~ 쓴 가격별로 특전을 챙겨주는 것도 좋았어요. 특전도 예쁘더라구요!! 아기자기한 공간에 플리분들끼리 모여서 노래도 듣고 수다도 떨어서 재밌었어요!! ㅎㅎ 삼왜는 실물이 짱이네요 🫰🏻', 34, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '예약 후 확인만 하고 들어와서 주문하는데 시간이 좀 걸렸어요. 포스 1대로만 계산하고 바로 옆 굿즈 쇼핑 후 마지막 나갈 때 특전 받을 수 있는 시스템! 음료맛은 다들 아시겠지만 그저 그랬어요. 네코마 음료는 우리가 아는 석류맛...', 23, 6, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '팬 상대로 장사하는 곳이고 1시간 단위로 예약해서 들어가는 시스템이라 회전률이 좋고 객단가도 높을 텐데 막상 들어가 보니 의자가 없어서 황당했음 빨리 나가라는 건지 뭔지 발바닥 터지는 줄 알았음 4인까지 이용 가능한 테이블인데 쟁반 올리니 꽉참 음료는 물 같고 아이스크림은 다 녹아서 나옴', 39, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '회전율을 높이기 위함인지 의자가 없이 그냥 서서 먹는 테이블이라는 게 큰 단점. 그리고 아이스크림이 반 쯤 녹아서 나옵니다. 한 번 쯤 즐기기에는 좋은데 아쉬운 점이 크네요.', 122, 19, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '하인성 음료가 맛있었어요.  매장도 더 넓어졌음! 바에는 캐릭터가 없어서 조끔 아쉬웠어용! 그래도 좋았음! 주문 받는 형식도 바꼈는데 이 부분은 좋아용', 41, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '직원분들 넘 친절하고 좋아요!! 내년에도 코난 해주세요!!!! 다만 아쉬운 점은 살짝 모자른 가격으로 금액별 특전을 못 받을 때는 1-2개 추가 구매 할 수 있게 해줬으면 하는 바램이 ㅠㅜ 있네요 ㅠㅠ 몇 천원 땜에 특전 하나 더 못 받은 건 좀 속상 ㅜㅜ 물론 처음부터 잘 계산 하면 좋았겠지먼요 ㅠㅠ', 18, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '콜라보 카페 열어준건 고맙지만......운영이 많이 미숙해보입니다. 콜라보 카페니까 맛은 원래 기대도 안하는데 아무리 그래도 디저트는 다 녹아서 나오고.... 직원들은 정신이 없고... 직원이 턱없이 부족해요.... 1회차여서 제시간에 들어갓는데도 13분에 주문한게 35분에야 나왓습니다. 직원분들은 고군분투 해주시는데 손님과 카페 모두를 위해서라도 직원들좀 늘려주세요.... 음료재료가 계속 수급이 됐다 안됐다 하는것도 이해되지 않는 부분입니다..... 하이큐 판이 작은 판도 아니고 이거 준비하실때 이미 충분히 예상을 할 수 있으셨을 텐데.... 너무 급하게 후다닥 하느라 제대로 즐기진 못했지만 직원분들을 탓하고 싶지는 않고, 이거 기획하고 준비하신 분들께선 다음번에는 좀 더 제대로 준비해주시면 좋을것같습니다', 37, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '아무리 짧은 시간 이용이라지만, 전석이 의자하나 없이 스탠딩석이라는 것과 아이스크림 메뉴가 이미 녹아져서 나오는건 좀 심한 것 같습니다. ㅠ 이벤트에 치중을 둔 카페라지만 이런 부분들은 개선됐으면 좋겠어서 리뷰 남겨봅니다.', 17, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '친구가 못가게되서 대신 가게되었는데 직원분들이 다 친절하셨습니다. 음료는 좀 아쉽긴했으나 늦게갔음에도 품절되는 물건이 많이 없어서 좋았습니다. 판매에 대한 안내를 앞에 고지해놔도 좋지않을까 싶습니다(줄에 혼돈이 생기는걸 방지)', 86, 12, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '직원분들이 정말 친절하게 안내도 해주고 공지도 해주셔서 즐겁게 이벤트카페를 즐길 수 있었어요! 다정하신 분들과 함께 제가 좋아하는 아이돌 카페를 누린다는 건 무척 행복한 경험이네요 :) 다음에도 좋은 기회로 애니메이트 카페 홍대점을 방문하고 싶어요!', 62, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '여러가지 엄청 바빴지만 특전도 많이 받고 좋았어요. 애초에 음식 목적이 아니라 기대 안 했는데 버싱이랑 원더쇼 드링크 둘다 앵간했고 디저트도 꽤 괜찮았어요.', 9, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '콜라보 이벤트 해서 너무 좋지만, 등신대도 있어서 좋지만, 의자 없고 음식은… 맛이 너무..너무하다…하하하ㅠ 직원분들 전부 친절하셔서 좋았다 근데 아니 맛이…', 12, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '첫방문때보다는 안정된분위기였어요. 그런데 식자제가부족해지는건 문제가 많지않을까요. 특전도 순서 많이 예민한데....첫주문인데 코스터는 중간에 어정쩡하게 받았어요. 좀 신경써주세요😅', 28, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '애니메이트 카페 이틀만에 일부 메뉴 품절, 픽 품절. 픽 쿠폰 주면서 영수증이랑 같이 들고 오라고 함. 50분에 나가라고 하면서 정작 50분에 나와서 증정품 받으려고 하니 그 많은 직원들 카운터에 아무도 없고 안에서 얘기나 하고 있고 대놓고 폰하는 직원도 봄. 일 잘하고 쉬는거면 모르겠는데 일처리 개못하는데 폰 보고 얘기하고 할 시간이 있나? 그리고 4인석도 개작은 테이블 하나면 대체 4인석 예약 왜 받는거임? 일 못하고 좌석도 없고 테이블 작아서 불편하고 최악. 대체 왜 확장한다고 난리쳤던 것이며 직원은 왜 그렇게 많이 뽑아놨나 싶을정도. 이전에 콜라보들도 이랬는데 불만이 없었던걸까 의문이 들정도임.', 108, 23, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '카페 내부가 진짜.... 너무너무너무 더워요  ㅠㅠㅠㅠ 에어컨을 안트는건지 진짜 더워 죽는줄알았습니다... 직원분들은 친절하시고 좋아요 .  ㅠㅠㅠ', 38, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '아무리 콜라보 카페라도 그렇지 이름이 카페인데 테이블에 의자가 없음 시간 제한도 있으면서 음료가 너무 늦게 나와서 늦게 주문한 사람은 얼마 즐기지도 못하고 내쫓김', 12, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '놀러가서 잠시 시간 떼울겸 갔는데 여전히 볼거리도 많고 책도 여러 종류가 모여있어서 좋았습니다. 이벤트 카페도 하는 것 같으 구경하기 좋습니다. 책은 확실히 신간이나 초회한정판이 많아 그런걸 노리는 경우에는 자주 오고 싶네요', 6, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), 'Ak홍대입구점 주차 진짜 최악입니다.. 금액대 구매내역은 공짜인데 자리가없어서 인근에 주차했더니 25,000원 나왔습니다. 주차 문제좀 해결하는게 어떨까요?', 75, 12, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PARKING');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '모든메뉴 시키고 전부 A세트로 시켰는데도 코스터가 쿠로오가 안나옴 이럴수가 있나...? 굿즈까지 7만원 넘게사서 반짝거리는 홀로그램 코스터 3개를 주셨는데 거기서도 쿠로오가 안나옴 이럴수가 있나....???', 201, 66, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '하이큐 콜라보 카페여서 방문하게 되었습니다. 테일블이 작고 높아서 앉을 수 없는게 제일 큰 단점이었어요 장점은 덕질하기 좋다.. 말곤 잘 모르겠습니다', 40, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '갈 때마다 느끼는 거지만, 오타쿠들 상대로 최대한 등쳐먹으려는 양심 없는 카페임. 그렇다고 맛있냐? 대체 뭣 때문인지 모르겠지만 늘 언제나 항상 맛이 없었다. 환율은 이렇게 낮은데 가격도 왜 이렇게 비싼지 모르겠음. 엔간하면 다시 안 가려고 함.', 36, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '디저트세트랑 버츄얼 싱어 음료는 먹을만하지만 레오니 음료는 밍밍한 맛이였어요.. 직원분들 안내랑 구매할때 조금 불친절했다고 생각될수도 있습니다. 코스터 받는 시간이 45분 이였는데 45분이라는 공지를 안해주셔서 그냥 가신분도 있으신것 같았어요. 그리고 굿즈 구매시 꼭 바구니에 잘 넣어가세요 안그러면 화내십니다. 콜라보라고 해서 왔지 그다지 또오고싶진 않았어요', 73, 11, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '음료가 새콤달콤하고..이번에 프세카가 2주년이라서 콜라보 한게 제일 좋았어요!! 혼자였긴하지만 좋은 추억? 남기고 갑니다-!!', 88, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '하이큐 더쿠라 한번 가봤습니다 음료는 맛있지는 않아요 서서 먹어야해서 편한 공간도 아니고 그냥 콜라보 분위기 느끼고 굿즈 사고 특전 받고 그런거 즐기러 가는 곳 같아요', 4, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '4인 테이블 예약이었고 예약확인후 음료 주문서 받아서 기재> 줄 따라서 음료 결제하고 > 굿즈 담아서 결제 후 진동벨 받음>음료 수령>영수증 지참하여 특전 수령 순으로 진행되었어요. 마감 시간전에 예약회차 마감 시간 다되어간다고 공지해주시는 편입니다. 직원분들 정말 친절하세요👍 좌석이 전부 스탠딩인건 좀 아쉬운 부분이지만 인원 수용 생각하면 어느정도 이해는됩니다😂😂😂', 11, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '자리는 의자가 없고 좁습니당.. 단체로 오면 안될듯요 음식은 가격에 비해 퀄은 떨어집니다 그래도 맛은 좋았어유 특히 2주년 기념 음료! 그리고 케잌은 그냥 포켓몬빵 같은 맛..? 비추비추~ 그냥 음료만 여러잔 시키세요 생각했던것보다 매장도 작고 볼 것도 없었습니다 그냥 가벽에 족자봉 몇 개 걸고 소리 안나는 티비로 뮤비 틀어주는게 끝.. 굿즈도 재고 안채워주고 진짜 생각했던것보단 별로였습니당 ㅎㅎㅎㅎㅎㅎ', 27, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '매장 리뉴얼 되고 쾌적하고 넓어졌어요!! 전에는 사실 불친절 건도 많았는데🤣 다들 굉장히 바빠 보이셨지만 친절했고 진짜 메뉴 체크 하게 하신거 넘 좋은것 같아용 개 빠른 피드백 감사합니다 품절은 어쩔수 없지만ㅜ 그리고 노아 쌍둥이 인거 웃겨서 다른 플리랑 찍음요ㅋㅋㅋㅋㅋㅋ', 49, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '굿즈 품절이라 예약 해야한다는데 택배수령이 안 된다고 하더라고요 방문자 한정으로라도 온라인구매같은 방안을 내주셨으면 좋겠네요 직원분들은 친절하셨습니다. 의자는 안 두는 이유가 궁금하네요 있으면 좋을 것 같습니다 음료수는 모모점거가 맛있었어요', 22, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '아이가 기념굿즈 너무  갖고 싶어해서 날잡고 기차타고 갔다왔는데요 굿즈가 없어서 예약해놓고 왔거든요 지방에서 그거 찾으로 직접 와야한다해서 정말 안사고 싶었지만 그 굿즈 사겠다고 아이가 너무 부풀어 있었고 거기에 들인 시간과 돈이 너무 아까워 예약구매를 해준긴 했는데 이거 제품도 동시에 준비되는게 아니라 각각 준비 되는건가요? 햐....... 문자받고 30일이내에 수령해가라고 하는데 랜덤코스터랑 단체 아크릴 스탠드 2개 구매했는데 문자에는 랜덤코스터만 있고 단체아크릴 스탠드 내용은 없는데 이거 찾을려면 2번 가야 되는건가요? 여기 문의사항은 어디다 해야해요? 02, 0507 전화연결도 안되고... 관계자분들 보시면 답글 좀 달아주세요.', 36, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '총 리뷰평점 ⭐️ - 카페음료 1. 흑임자드링크 ⭐️⭐️⭐️ 2. 블루소다 ⭐️ - 내부 인테리어 1. 의자 없음 2. 에어컨 틀지않아 더움', 10, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '10분이내 대기 후 빠르게 입장했어요!! 저는 친구와 4인용 테이블을 이용했는데 둘이 쓰기에도 공간이 조금 부족하다는 느낌이었네요. 또, 의자가 없는 스탠딩이라 다리가 좀 아팠어요. 음료는.. 아무래도 콜라보 카페이다보니 맛이 조금.. 네.. 그래도 먹을만 했어요. 그래도 음료는 주문하면 금방 나와서 마시는데 시간이 부족하진 않았네요! TV에서 3D mv도 틀어주는데 보면서 굉장히 행복했어요❤️❤️ 다만 노래는 안나온다는 점.. 노래도 같이 틀어주세요...!!😭😭 제가 갔을 때가 일요일이라 그런지 메뉴마다 하나씩 주는 코스터가 다 품절돼서 못받았네요...ㅠㅠ 이 점 꼭 참고해주세요!! 프덕으로서 굉장히 즐거운 시간 보냈습니다!!', 4, 7, NULL, SYSTIMESTAMP);
