INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '리모델링하고 더 넓어지고 깔끔해진 것 같아요 옆에 창문있는 공간이라 그런지 더 개방감도 생기고 좋아졌네요 ㅎㅎ 좋아하는거 콜라보카페할때마다 방문했엇는데 리뉴얼 후 마음에들어요! 맛은 뭐.. 콜라보카페니까요🤔 목축이기는 좋아요!', 24, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '전체적으로 준비가 미흡한 단계에서 오픈한것이 아닌가 생각되었습니다. 1) 메뉴소진 : 재료 수급문제로 2일차인데 음료주문이 어렵다? 2) 메뉴위의 픽이 없음 : ..? 그냥 평범한 음료 마시고 온 사람 됨 (나중에 트위터에 공지뜨면 픽받으러오라고함. 무려 트위터 공지를 놓치지않고 봐야하고, 교통비내고 또가야함) 3) 매장내 동선  : 줄세우는 스태프없어서 우왕좌왕, 줄과 가까운 테이블은 사람들에 둘러싸여서 이용. 사진도 도저히 찍을 각이안나옴. 등신대 예쁘게 찍으려면 테이블 네 개 사이로 꾸역꾸역 들어가야함 주문후 굿즈 고르는 사람들로 굿즈구매없어도 줄에서 벗어나질못함 두 번 다시 안가요', 62, 18, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '테이블이 사인용치고 작아서 아쉽지만 잘 구경하고 왔어요 2일차는 입장도 딜레이 없이 들어가고 음료도 빨리 나와서 잘 이용했습니다 이용시간만 좀더 길면 좋을거 같아요 음료를 많이 남기고 왔네요🥲', 5, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '음료 자체는 약간 애매,,한 맛? 이었는데 이쁘게 꾸며져있어서 눈은 행복했던 곳이었어요! 갠적으로 예준이 음료가 가장 괜찮았던 거 같은?? 얘들도 귀엽고 사진도 많아서 한번쯤 가기 좋은 것 같아용🥰', 198, 79, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '음료는 콜라보카페인걸 감안하면 평범했고 메뉴구매 특전을 늦게 받는다는 공지가 올라와있지 않아 불편했으며 직원분이 이걸 뒤늦게 안내해주실때 불친절한 태도때문에 앞으로 안 갈 것 같네요..', 2, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '메뉴 사진이랑 실제 음료랑 생김새가 너무 달라서 약간 당황했습니다.. 콜라보 카페라서 맛은 기대하지 않았지만 안내된 재료 자체가 빠진 건 조금 아닌듯 싶었습니다.. (레오니드 메뉴에 스프링클도 시럽도 없었어요😅) 특전 배부나 구입 영수증 합산 관련해서도 사전 안내가 미흡해서 현장에서 하나씩 물어봐야했고, 굿즈 판매도 전날에 갑작스레 예약 수령으로 전환 공지가 올라와서 여러모로 번거로웠네요. 좋아하는 게임 콜라보 카페라 기대했는데 아쉬운 점이 많았습니다. 남은 기간은 좀 더 체계적으로 운영되었으면 좋겠습니다.', 18, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '플레이브 노래나오고 좋았어요 4인테이블이지만 2인이서 써도 되기도 하고 테이블 자체가 그렇게 큰 편은 아니였어요 진짜 4명이서 쓰기엔 애매한..?기존에 있던 애니메이트 카페 테이블 크기랑 똑같아요', 55, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '예약하고 갔는데도 무한대기💦 디피가 그렇게 화려한 것도 아닌데 테이블엔 굳이 의자를 빼놓고 (이거 덕후학대임) 의자도 없어 다리아파 죽겠는데 45분간 강제로 기다려야 특전을 나눠주는 이해할 수 없는 시스템 음료 픽은 없다고 나중가서야 교환권?을 나눠주는데 그거 하나받자고 다시 오라는겅미? 주문받기 전 미리 고지해줫으면함', 115, 24, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '규모는 작았으나 사진 전시라던지 굿즈 구매할 수 있어서 좋았어요. 다만 못챙긴 저도 불찰이지만 직원분이 음료포카를 안챙주셔서 3장 날라갔네요 ㅜㅜ 저도 정신없고 직원분도 정신없으셔서 그랬겠지만 아쉬워요 흑흑 방문하시는 분들은 저같은 실수 하시지 마세요!!', 74, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '제가 원하는 자리에서 카페를 이용할 수 있어서 좋았어요 ૮꒰ྀི∩´ ᵕ `∩꒱ྀིა ˚.* 온통 플레이브라 좋았습니다 음료도 빨리 나와서 이용하기 편했어요❣️', 2, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '카페가 아닌데 카페로 잡히네요 이번에 클램프 작품 세계적으로 순회 전시라고 해서 다녀왔는데 행사 자체는 열린 거에 감사한데 아쉬움이 많습니다. 굿즈 라인업 첫날에 간건데 인기 굿즈는 바로 품절이고.. 라인업 추가 라든지 품절 굿즈 재입고가 절실할 것 같네요', 94, 22, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '이곳 층층마다 볼꺼리 엄청 많고 좋아요 ^^☺️👍🏻👍🏻👍🏻 맨위층에 애니메이트가있는데 이곳은 카페도있고 만화책 들이 엄청많은곳이예요 ^^ 너무너무 좋구 빨리 신간이 나왔으면 좋겠어요 ㅎ☺️💛💛', 41, 1, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '스탠딩 너무 불편해요....서서 대기하다가 들어가는데 앉지도 못하고...심지어 테이블이 키 작은 동생에게는 좀 높았어요... 1시간 이용인데 들어가자마자 음료 주문하고 굿즈 샀는데도 기다리는 줄에서 30분 넘게 날라갔어요...ㅋㅋㅋㅋㅋ 남은 30분 미만의 시간을 이용해서 사진 찍고 문제 풀고 굿즈 불량인지 확인하고 해야되는데 솔직히 시간 너무 부족했어요...저도 빨리 나가고 싶은데 제대로 한 게 하나도 없는데 어떻게 나가나요...ㅜ 진짜 눈치 엄청 보였음....ㅜㅜ 음료 솔직히 너무 맛없었어요...시럽을 너무 싼 거 쓰는 거 같았고 음료가 무맛이에요 진짜.... 다른 콜라보 카페들도 여러군데 다녀봤지만 이렇게까지 최악인 곳은 처음이었어요...ㅜㅜ 다음에는 제발 제대로 준비해서 진행해주세요🥺', 35, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '예약하고 즐겁게 다녀왔습니다! 직원분들 다들 친절하시고 매장 잘 꾸며져있고 깔끔해서 좋았어요 의자가 없던건 아쉬웠지만 재밌었습니당', 44, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '카페 인테리어가 모두 플레이브라 좋았어요💙💜💗❤️🖤 노래도 플레이브 노래만 나오고, 미리 메뉴 선택 후 입장해서 음료가 빨리 나오는 것도 좋았어요 °₊•*・.｡ ꪔ̤̻ꪔ͈̮ꪔ̤̮', 15, 7, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '지인이랑 같이 가게되었는데 사실 전반전보다는 메뉴 맛이 좀 제 취향이 아니었는데 메구미 디저트는 먹어볼만합니다. 굿즈들도 너무예쁘고 DP가 상당히 귀엽습니다. 다만 협소한 공간이다보니 전시라는 부분은 없다고보시면돼요.', 86, 17, NULL, SYSTIMESTAMP);
