INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '오후 3시타임으로 동생이랑 같이 다녀왔어요! 오랜만에 나들이도 할겸 우리 플레이브 1주년 기념도 할겸 다녀온건데 음료랑 디저트 저랑 동생은 만족하고 갑니다요~!', 53, 15, NULL, SYSTIMESTAMP);
