INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '회옥옥절편과 다름없이 비슷한 것 같아서 큰 차이는 못 느꼈지만 확실히 분위기나 음료로 인해 선택권이 많아진 건 좋았어요! 다만 다음에 또 한다면 다양한 종류의 음료와 디저트를 많이 내 주시면 좋겠다고 생각합니다 ㅜㅜ 그래도 예약 시스템과 그 외의 다른 것들은 모두 만족합니다 잘 다녀왔어요!', 81, 16, NULL, SYSTIMESTAMP);
