INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '즐거운 시간 보냈습니다. 다만 금액별 사은품이 다 떨어져 교환권으로 받았습니다. 다시 한 번 방문해야 되겠네요:) 플레이브 화이팅!!!', 15, 10, NULL, SYSTIMESTAMP);
