INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '주술회전 독서회?이벤트 중인데 품절물품이 많아서 아쉬웠어요 그래도 다른 거 구매했습니다 다른 애니굿즈도 종류가 더 많았으면 좋겠어요', 43, 6, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '표받아주시는 직원분 완젼 친절하세영ㅎㅎ 한분망 불친절 굿즈 계산해주시는분 처음가서 잘몰라서 질문했어여 질문하면 안되나요 한심하단듯하게 말하세요ㅠ 예약제이고 이용 인원이 정해져있어서 다른카페에비해 안바쁘시자나요 우리가 시끄럽게 군것도 아니고 다조용하던데ㅠ 이용시간 인원이 정해져 있는데 왜.. 의자는 다뺀거에요?? 45분동안 서있어야함 덕후 학대야 ㅠ 테이블도 높아서 키작은 저에겐 이용이 불편했습니다 남는공간도 많던데 굿즈 사는곳은 왜 카웆터쪽히에 해놔서 붐비지 않아도 되는 임원을 붐비게 하나요 음료주문먼저 하고 굿즈는 다른곳에두고 고르게 하지 줄이 같아서 옆에분이 기다려리니까 미안해서 아무거나 막집음 하.. 굿즈사려고 가는건데ㅠ', 73, 18, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '주문받는데 20분 특전 받는데 20분 음료 나오는데 20분 가뜩이나 앉을 수도 없는데 다먹기도 전에 쫓아냄 불쾌한 경험 하고왔습니다~', 26, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '주술회전 콜라보 카페 미쳤나!! 너무너무 행복했다 일단 테이블이 다 캐릭터들로 되어있어서 카와이~ 또한 음료 나름 맛있었어용~ 근데 신분증 필수라 좀 하아.. 진짜 급당황!! 그래도 직원분들이 관리 잘 해주셔서 재밌게 다녀왔습니다 :)', 17, 2, 'GOOD', SYSTIMESTAMP);
