INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '음 2번째 방문인데 첫번째보단 설명도 잘해주시고 음식도 첫번째보단 일찍 나왔습니다! 애니메이트.. 시간 예약제이면 앉아서 먹을 수 있게 해주셨음 하네요ㅠㅠ', 51, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), 'It was nice! I did reservation so it was perfect. Just wished the beverages tastes would be better. The dessert was delicious. :) I had enough time to take lots of pictures.', 125, 20, 'GOOD', SYSTIMESTAMP);
