INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '카페 운영이 체계적으로 잘되어있어 정말 편하게 다녀왔습니다. 케이크가 생각도 못했는데 정말 맛있어요! 여기저기 신경많이 써준 티가 나서 정말 좋았어요', 1, 1, 'GOOD', SYSTIMESTAMP);
