INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '플레이브 콜라보 방문했어요 여기저기 이쁘게 잘 꾸며놓아서 사진 찍기 즐거웠어요 직원분들이 굉장히 친절하셔서 편하게 이용했습니다~', 48, 1, 'GOOD', SYSTIMESTAMP);
