INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '좋아하는 가수를 볼수있고, 굿즈구입도 할수있어서 좋았습니다. 아쉬운점이 있다면, 의자도 없이 스텐딩인것과 음료맛이 좀 아쉬웠습니다..', 20, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '플레이브 콜라보카페 다녀왔는데 매장도 더 넓어지고 메뉴들도 전부 다 맛있었어요 디저트가 하나밖에 없어서 너무 아쉬웠지만 우리 플레이브 얼굴 많이 볼 수 있어서 좋았어요💙💜🩷❤️🖤', 33, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '애니메이트 카페가 새로 확장오픈해서 이전보다는 더 넓고 쾌적해져서 좋았어요! 창가가 있어서 햇빛도 잘 들어와서 더 좋았습니다 ◡̈ 다만 계산대 직원 배치는 조금 아쉬웠어요. 계산 후 계산완료 스티커 부착까지 한 분이 다 하고 계셔서 계산이 너무 밀려 정작 카페는 많이 둘러보지 못한게 아쉬웠습니다. 사람이 몰리는 시간대나 예약타임때는 2인 1조 형식으로 하시는 것도 좋을 것 같아요. 이 부분을 제외하곤 직원분들 다들 너무 친절하시고 디피도 예뻐서 너무 즐거운 시간 보내고 왔습니다 😊', 222, 94, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '플레이브 친구들을 좋아하는 딸을 위해 다녀왔어요 돌쟁이 아기도 같이 가야해서 이모찬스를 써서 다녀왔네요 좌석이 없어서 조금 힘들었지만 아이가 행복해하니 저도 좋네요ㅋㅋ', 46, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '의자없이1시간동안서서구경하고음료를마신다니 다리가너무아팟어요 물건도품절이많아서나중에 교환권을주시다니너무하네요 입장권예매도엄청난시간을투자해서 예약도겨우겨우잡앗구요', 48, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '올 예약제로 운영되어 쾌적하게 잘 다녀왔습니다😊 그러나 구매금액별 특전이 모두 떨어져서 종이코스터, 체키, 아크릴코스터 다 나중에 다시 받으러 가야 하네요🥹', 16, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '주술회전하나만 보고 간 카페 고죠 라무네 소다플로트는 소다의 청량함도 느껴지고맛있는데 나나미 초코바나나는 밍밍 그자체 맛이나긴하는데 물많이 탄맛....당이 줄어서 좋아해야하는건지.. 콜라보카페 서비스업하기에는 남자직원분은 기계적인 친절함 여자직원들은 다 불친절...우리뿐만 아니라 다른 분들이 질문했을때도 말투가 귀찮고 퉁명스러운게 다 느껴짐 나는 네이버예약을 통해서 입장했지만 네이버예약으로 바뀐줄 모르셨던 다른분들은 직원분께 입장 어떻게 하냐고 여쭤봤지만 아 네이버로 예약하셔야 돼요ㅡㅡ라는 귀찮은듯한 표정과 말투가 나에게까지 느껴짐 네이버예약으로 바뀌었다고 공지를 카페입구에 크게 적어놓거나 예약 못한분들의 테이크아웃도 어떻게 진행되는지 좀 적어놔야할듯 테이크아웃 엄청오래기다리고 설명은 불친절 돈내고 을됨..', 10, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '그냥 주술회전하나만 보고 간 카페 고죠 라무네 소다플로트는 소다의 청량함도 느껴지고맛있는데 나나미 초코바나나는 밍밍 그자체 맛이나긴하는데 물많이 탄맛....당이 줄어서 좋아해야하는건지 생각했음 남자직원분은 기계적인 친절함이 느껴졌음 여자직원들은 다 불친절....우리뿐만 아니라 다른 분들이 질문했을때도 말투가 귀찮고 퉁명스러운게 다 느껴짐 콜라보카페 서비스업하기에는 좀 아니신듯 함', 29, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '양나리 복제친필메시지 카드 받을 겸 니지산지 콜라보 카페 갔습니다! 이번 일러가 잘 뽑히기도 했고 디피도 예뻤습니다! 굿즈도 하나같이 다 예뻐서 맘에 들어용', 57, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '음료 구매시 받을 수 있는 포카 한장도 못받았습니다. 6잔이나 마셨는데도. 그날 입장도 늦고 지방에서 올라가서 정신없이 사진찍느라 포카 받았는지 안받았는지도 몰랐네요. 심지어 12시타임 예약이였는데 시간 맞춰 가도 입구에 라인 걸어두셔서 못들어가고 있다가 앞에 분들이 라인 넘어서 들어가는거 보고 따라 들어갔더니 그제야 입장내용 확인 해주셨습니다. 굿즈도 음료 구매하고 구매하려고 하는데 영수증 하나당1인으로 잡고 구매 가능하다고 해서 다 사지도 못했습니다. 이럴거면 둘이가서 영수증 나눠서 결제했을건데. 아. 영수증 나눠 받아도 어차피 포카 안주셨으니 소용없나요? 그 포카 다시 받자고 돌아가기도 힘들고 콜라보하는것만 아니였어도 다시 방문하고싶지는 않습니다.', 17, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '플레이브 콜카 처음으로 가봤어요. 다 좋은데... 아쉬운게 있다면은 ... 의자가 없었다는거... 4인석이었는데 가는데 1시간 반 걸렸는데  다같이 서서 먹어서 다리가 아팠어요ㅠ...', 12, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '스쿠나 좋아해서 걱정했는데 뽑기운 너무 좋아서 최애템 나왔어요. 나머지도 메구미와 고죠라서 폭설을 뚫고 달려가길 정말 잘했다고 생각했습니다^^ 음료는 좀 단편이었고 등신대나 지하철 벽면은 사진 찍기 좋아요. 부탁도 차마 못 드렸는데 다들 잘 찍으라고 테이블도 뒤로 치워주시고...직원분들도 친절, 다정하시고... 완전 감동이었습니다. 유일한 단점이라면 옆 애니메이트까지 들리는 바람에 텅장이 됐다는 거예요ㅠ.ㅠ', 41, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '주술회전 콜라보 카페로 다녀왔습니다! 실물 신분증 안 가져갔는데 다행히 임시 신분증 사진으로 잘 들어갔구요 음료는 밀크티는 맛있는데 모과차는...... 의자가 없어서 불편했지만 주술회전이라 남자친구가 방방 뛰는 모습을 볼 수 있어서 행복했어요 구리고 포토존가서 사진찍는데 사진찍으라고 만든곳에 사진찍는걸 눈치주는 손님이 계십니다... 좀 아쉬웠지만 굿', 1, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '주술회전 콜라보카페 ~ 후시구로 메구미의 옥견 돌체라떼 게토스구루의 주령구 티 세트 ㄴ 떡 반 먹었는데 맛있었음 !! 고죠 사토루의 라무네 소다 플로트 ㄴ 요거 먹었는데 맛있음 🤭🤭', 122, 26, 'GOOD', SYSTIMESTAMP);
