INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '유동인구가 많은 곳이지만, 사전예약을 통해 입장하여 이용하였기에 크게 붐비지 않고 쾌적하게 이용할 수 있었습니다. 콜라보 음료도 맛있었습니다!', 20, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'COLDBREW');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '사고 싶은 물건들이 정말 많아요 만화책 뿐만 아니라 다양한 굿즈들이 있어서 돈쓰고 나오기 정말 좋은 공간입니다 다만 사람이 조금 많아요', 43, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '제가 물음표 살인마로 많이 여쭤봤는데 하나하나 자세하게 설명해주시고 직원분들 다 친절했습니다! 음식 맛은 뭐~ 콜라보 카페가는데 맛이 그리 중요합니까 우리 애들 굿즈만 잘 있으면 되죠😊', 55, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '일하시는 분이 정말 불친절해요. 놀러가서 기분 안 좋게 오네요 ㅎㅎ 이벤트 카페라 힘드실 거 아는데 손님한테 그러시는 거 보니 아직 직업의식이 많이 부족하신 것 같네요. 서비스직인데 그렇게 짜증내면서 대하시는 분 처음 봐요 ㅎㅎ 어떤 직원 한 분만 유독 그렇더라고용~', 39, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '다들 최차애가 안나오는지 제가간 타임에 주령이 실시간 생성되는 것 같았습니다.. 뭐 카페맛이야 콜라보카페니까...하는데 특전도 원하는게 잘 안나와서 전 나중에 주령이될것같습니다.. 그래도 좋아하는 장르 열리면 기쁘네요', 37, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '고죠 사토루가 있는데 어찌 안가볼 수 있을까요? 👁️👄👁️ 죽도록 사랑해~~~ 🩵 굿즈 품절 된 것은 주문 가능하니 관심있으시면 꼭 가보세요 🫣', 58, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '토게 테이블은 건졌지만 똥손이라 슬퍼요ㅜ_ㅜ 모과티는 윗부분이 싱거워서 저을 수 있는 스푼이나 스틱도 같이 주시면 좋을것 같아용 직원분들도 친절하시구 주술회전 덕질하고 싶으면 여기 오기 나쁘지 않은것 같네여', 70, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '니지산지 콜라보카페 다녀왔습니다 마지막타임으로 예약해서인지 콜라보 메뉴일부가 품절이어서 아쉬웠습니다 그래도 재밌는 추억남기고갑니다', 44, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '솔직히..뭘 바라고 간건 아니지만 메뉴도 별로없고 진짜 별로네요.. 1. 굿즈를 추가구매하려면 메뉴 한가지는 무조건 다시시켜야한다함.오기 전부터 메뉴랑 굿즈 살거까지 다 생각하고 와야하나?이건 뭐..어이없지만 참았음. 2. 직원 응대가 별로임. 3명이 메뉴3개먹고 더 시키려 하니까 직원1이(편의상 존칭제거) 30분 지나서 시키려면 테이크아웃 해야해요.지금 당장 짐 치워서 나가야해요.이러길래 벌써 30분이 지났나?그럼 어차피 더 할것도 없으니 테이크아웃 해가자. 해서 짐챙겨서 테이크아웃 하려하니 직원2가 안돼요.(이유 설명도 없었음)이래서 ''어 왜안되지?뭔가 대기줄?그런게 끝났나?'' 하고 그냥 나가는데 정작 우리 나갈 때 남자 한명 들어와서 시킴 어리다고 무시하는건지..이런데 많이 안와본것같아그러는건지?', 23, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '주말 11시에 도착, 오후 5시 대기번호 받았고 오래 기다려 들어갔네요 스탠딩이라 아쉽긴 했지만 정해짐 인원만 들어와 쾌적하게 이용했네요 음료랑 디저트류는 생각보다 맛있었어요!! 특전도 퀄 괜찮고 예뻐요!', 15, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '기존 웨이팅인 밖에서 하는 웨이팅 너무 춥고 줄이 너무 길었는데 예약제로 바껴서 훨씬 수월하긴 해요! 포토존이랑 바로 앞 테이블이 가까워서 사진 찍는덴 좀 불편하고 통로나 사이사이가 좁다는 단점이 있지만 이곳에 머무르면서 시간 굉장히 빨리 가고 진짜 재밌었어요 좀만 더 기간 연장 해주세요ㅠㅠㅠ', 46, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '굿즈 사러 다녀왔어요 직원분들 친절해요 근데 여긴 왜 의자가 없어요? 그냥 진심 궁금해서 그리고 음료 컨셉 맞게 만드는 건 알겠는데 맛이 좀 애매해요 뭐 먹으러 가는 거 아니긴 한데 그래도 😭', 36, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '콜라보 카페 디저트 맛이었고 직원분들 설명도 친절해서 좋았어요 메뉴들도 콜카 치고는 정말 빨리 나오는 편이였습니다 근데 입구 입장 안내 멘트는 주문하고 테이블 잡는 건데 오신 분들이 입장과 동시에 우르르르 테이블로 돌진해서 뭔가 싶었어요 기분 좋게 안내 지켜서 이용합시다', 108, 23, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '돈과 시간을 쓰고 불쾌한 경험 했습니다..ㅠㅠ 직원분이 ”굿즈 예약하실건 없으시죠?“ 라고 물어보셨는데 굿즈 예약제에 대해 잘 모르는 상태여서 얼떨결에 ’그렇다‘고 대답했지만 꼭 구하고 싶은 굿즈가 있어서 다시 여쭤보려고 하니까 남자 직원분이 굉장히 꼽주듯이 ”제가 이미 말했잖아요“ 이런식으로 대답해서 너무 상처받았습니다… 오타쿠인 이상 애니메이트 안갈수도 없는데 솔직히 돋받고 일하고, 명색이 카페인데 조금만 더 매너있게 행동해주셨으면 합니다. 이상 아침부터 일어나서 설레는 마음으로 카페갔다가 굿즈도 못사고 상처받은 고2였습니다…….', 39, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '네이버를 통한 예약이 늦게나마 가능하게 되어서 추운 겨울에 대기없이 편하게 다녀왔네요. 공간제약이 있다지만 50분제한에 전체 입식테이블 운영은 아쉽구요. 예약자는 신분증 확인하니까 꼭 챙기시고! 카페 굿즈 구입하실 분들은 굿즈만 추가주문 불가니 미리 확인해놓으셨다가 음료 주문하실때 굿즈도 같이 구매하세요.', 49, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '다음날 영수증 보니까 사지도 않은 굿즈가 찍혀있네요ㅠㅠ 매장에 전화해도 계속 안받고.. ㅠ 참고로 방문하실분들 매장은 작고 스탠딩 테이블입니다! 밀크티는 크림이 맛있었고, 소다는 달달한 뽕따 그 자체입니다. 전 그냥 고죠 빨대 픽 주길래 선택했어요ㅎㅎ 다들 굿즈 수량 잘 확인하세요.. 만천원 날리게생김😭 글고 테이블마다 캐릭터가 있는데 원하는 캐릭터가 있다면 입장하자마자 후다닥 들가셔요! 안그럼 남은 캐릭 자리 앉아야함ㅋㅋㅋㅋ', 14, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '별로에요. 7.6내고 3만원은 불만족에 4만원은 먹튀당할 빤 했어요 1.메뉴가 맛없고 적어요. 그나마 먹을만한건 그날 3번째타임 갔는데도 매진났어요. 매번 매진나는 메뉴가 있으면 재료를 좀 더 조달해왔어도 되지 않았나..합니다 2.직원분은 불친절하구요. 3.스탠딩 테이블인데도 매장이 좁아요. 4.매장 내 구조도 불편해서 계속 돌아서다녔습니다. 5.품절났던 상품 2종(회옥아크릴1 시부야아크릴4)을 시켰는데 받을 수 있음에도 연락은 회옥만 와서 시부야아크릴4개를 그대로 날릴뻔 했습니다. 처음 말씀드렸던 직원분은 연락 안오면 그냥 안된다 했는데 x에 가능하다 써있다고 다른분께 말씀드리니 그제야 오류같다고 주시네요. 이런 억울한 오류 생기지 않도록 주의좀 해주세요.', 86, 12, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '알바생분들 진짜 불친절합니다. 손님 받는 중에 옆 직원이랑 떠드시는데 당황했어요. 손님 다 받고 이야기 하는거면 상관 안하죠, 아님 업무관련 이야기면 이해합니다. 하지만 앞에서 대놓고 이야기하셔서 내용이 들렸는데 그것도 아니더라고요. 참 태도가 다녀본 카페들중에 여러모로 최고였네요 ^^', 0, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '메구미 달라 했는데  아포가토냐고 한번 물어봐 주시지 음료 두잔 맞냐고 물어보고 파르페도 심지어 주문 받고 없었음ㅋㅋㅋㅋㅋㅋ 가지 마셈 여기 굿즈도 맨날 품절 됨 보통 죄송하다고 해야 하는거 아님?? 손님이 잘못했다고 하는 말투부터 고쳐먹으셈', 48, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '예약으로 해서 웨이팅 없이 이용하는 건 너무 좋았어요 그치만 미리 예약 받는 거면 디저트나 음료 재료는 어느정도 넉넉히 확보를 하고 오픈 하셔야하지 않나 싶습니다. 오후 7시에 갔는데 주문할 수 있는 음료도 몇 개 없고 디저트는 아예 다 품절이더군요 ..; ㅠ 직원분들도 막 불친절하시진 않았지만 그렇다고 친절하신 편도 아니였어요.. 그리고 의자가 없습니다 !! 알고 가세용', 25, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '사람이 너무 많아서 계산줄만 20분 대기했어요 책 종류는 많지만 사랑들이 몰려서 힝드네요 굿즈랑 책 계산 하는곳을 따로 분리했으면 좋겠어요', 4, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '3시에 예약하고 지하철 문제로 조금 늦어서 3시 7분에 카페에 도착햇는데 20분까지 입장 가능하다고 해서 도착해서 주변 둘러봤는데 출구라고 적혀 있는데 들어갈 수 없게 펜스 쳐져있었고 예약 대기 줄에 15분까지 서 있어도 쳐다도 안보길래 펜스 넘어 들어가니 안에 들어가서 앞에 와서 주문 해야 된다고 하더라구요 현장에 돌아다니는 관계자분도 없고 카운터가 멀어서 줄서는 곳에서 부르기도 곤란한 거리라 전화도 했었는데 받지도 않아 불편하고 아쉬웠습니다', 82, 18, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '앞으로도 계속 예약제면 좋을거같습니다! 밖에서 따로 시간 안보내도 되고 ㅜㅜ 너무 편리하고 좋았어요. 만약에 예약제로 된다면 지금처럼 일주일 단위로 받으시면 좋을 것 같습니다!', 15, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '주술회전 콜라보해서 방문 했어요 부산점인데 왜 홍대점으로 찍히는진 모르겟지만 ㅇㅅㅇ 좀 통통하신 여성분이 응대 해주셨는데 진짜 너무너무너무 불친절 했습니다 설거지 하고 있으시길래 부르면 좀 그럴 거 같아서 메뉴 보면서 기다리고 있었더니 갑자기 오셔서 한 숨 쉬면서 엄청 싸가지 없는 말투로 (하, 주문 하실거에요? )라고 하시더군요 ㅎ 엄청 무안하도라고요 ^^* 저도 서비스직 으로 일 하는 입장으로서 사람 응대하는 일이 힘든건 압니다만, 참 돈은 돈대로 쓰고 기분은 기분대로 안 좋은 경험이었습니다^^', 37, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '그냥 대기 겁나 길어요. 안에서 직원분들 쉬고 계시는데 테이크 아웃을 왜 안 받는지 모르겠네요.. 밖에서 보면 떠드는 걸로 보이는데ㅎㅎ 그게 아니면 왜 이렇게 오래 걸리는지 설명이라도 제대로 해주시던가.. 애니메이트는 어차피 사람들 많이 오니까 손님이 을인 기분 들어요^^', 19, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '분위기도 좋고 음료도 맛났고 직원분들도 다들 친절하셨어요 특히, 남자 직원분 너무 친절하셔서 완전 감동ㅠㅠ 행사가 연장되거나 다음에 또 진행되길 간절히 바래봅니다. 고죠 너무 좋아여~~', 45, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '친구들이랑 2시즌 다갔었는데 너무 좋았습니다. 다만 약간 좁았던게 아쉽네요. 또 다른 시즌으로 연다면 무조건 갈거같아요 ㅎㅎ 주술회전 팬으로써 매우만족합니다.', 4, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '명탐정 코난 이후 두 번짼데 아직도 너무 허술하다. 테이블 이용자 우선시 하는 건 이해되지만 테이크아웃 사람들은 테이블 이용자의 주문이 끝날 때까지 주문도 못한다. 테이크 아웃은 한 타임에 3팀 들어가는 거 보고 화가 났다. 테이크 아웃이면 좀 빨리 순환될 줄 알았는데, 주문 받는 게 거의 3~40분 쯤에 주문할 수 있게 된다. 6번째란 문구를 30분 내내 보고 있다 참지 못해 물어보니 테이블 이용자 주문 후 주방 정비 후 시간 남으면 테이크 아웃 주문을 받겠다고 했다. 테이크 아웃 사람들은 계속 기다리란 소리인 것 같았다. 막상 순서가 되서 주문을 하니 1분도 안 걸린다. 좀 더 효율적으로 했음 좋겠다. 캐캐체나 슈슈룬이 더 체계적이다. 보고 배웠으면 좋겠다.', 0, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '주술회전 회옥.옥절때 오픈런으로 방문하고 그때 오픈런 기다리는게 너무 힘들었는데 오늘 시부야사변 은 네이버 예약된다는 공지사항 후 예약후 다녀왔습니다 일단 예약하고 가니 더할나위없이 좋았습니다 기다림도 없고 번잡스러움도 없고 지난번 음료위에 올라가는 스티커(?) 같은것도 못받았었는데 오늘 그당시 영수증 챙겨가 보여주고 받았습니다!앞으로 사람 몰리는건 예약으로 해주심 좋을거같아요! 직원분들 은 진짜 친절하세요ㅎ', 11, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '주술회전 회옥.옥절때 오픈런으로 방문하고 그때 오픈런 기다리는게 너무 힘들었는데 오늘 시부야사변 은 네이버 예약된다는 공지사항 후 예약후 다녀왔습니다 일단 예약하고 가니 더할나위없이 좋았습니다 기다림도 없고 번잡스러움도 없고 지난번 음료위에 올라가는 스티커(?) 같은것도 못받았었는데 오늘 그당시 영수증 챙겨가 보여주고 받았습니다!앞으로 사람 몰리는건 예약으로 해주심 좋을거같아요! 직원분들 은 진짜 친절하세요ㅎ', 22, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '존버하다가 힘들게 예약성공해서 갔는데 고죠센세 자리 뺏겨서 ㅠㅠ 아쉽지만은 굿즈도 품절사태고 그래도 한번 이라도 테이블에 먹을수가 있어서 매우 행복했어요', 39, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '애니메이트 카페 홍대점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '두번째 존버해서 네이버 테이블 예약 성공하고 ㅠㅠ 드디어 다녀왔네요 ㅎㅎ 스쿠나 파르페 먹고싶었는데 아쉽게 매진되고 다음에 도전 해봐야줘 >_<  사멸회유편도 해줬으면 좋겠어요', 61, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '벌써 여섯번째 방문이네요ㅎㅎ 이번에 사장님 처음 뵀는데 너무 친절하게 잘 해주셔서 감사했구 반가웠어요! 이번에도 너무너무 재밌게 그림 그리다 갑니다 미니 이젤 선물 너무 감사드려요ㅠㅜ 집에 그림 예쁘게 전시해두겠습니당 미니캔버스 이벤트하시길래 친한 동생이랑 같이 하러 갔는데 동생도 정말 좋아하더라구요! 일정 때문에 베어브릭 체험을 못해서 아쉬웠으니까 다음엔 베어브릭 하러 또 찾아가겠습니당!ㅎㅎ', 2, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '분위기도 좋고, 딸기라떼는 사장님께서 직접 만드신 청이래요! 드로잉카페 처음이라 어떻게할지 고민하니까 여러가지 제안해주시면서 도와주셨습니다. 친절하고 공간도 너무 좋아요 :> 다음에는 도안 생각을 꼼꼼히 하고 또 하고 싶어요', 87, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '더워서 그냥 들어온 카페인데 드로잉을 할 수 있었어요. 아이가 체험하고 그리는 것 좋아해서 도안 선택해서 채색했습니다. 아이도 재미있어하고  홍대앞에서 미술 체험이라 더 의미있는 시간 보낸것 같습니다. 아이와 시원하게 시간 보내는 곳으로 추천합니다.', 42, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '베어브릭 꾸미기 하고싶어서 찾아봤는데 요기가 젤 가격도 착해서 예약했는데 일단..!! 아샷추랑 딸기라떼 시켰믄데 음료 너무 맛있고요 😭 사장님이 정말 너무너무너무너무 x 100000 친절하셔서 감동만 받고 갑니다..❤️ ❤️ ❤️장소도 넓고 세상 cozy해서 미친 데이트 코스에요.. (전 친구와 왔지만^^) 남친 생기면 또 올게요..!!! 요즘 힐링이 필요했는데 시간 가는지도 모르고 넘 행복했어요.. 스토리에 올리니 주변에서 어디에서 했는지 물어봐서 소문내는즁입니당.. 💥😍', 32, 0, 'GOOD', SYSTIMESTAMP);
