INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '아이들이 미술을 너무 좋아하는데 유화를 해본 적 없었는데 가서 편안하게 그림 그릴 수 있어 좋았습니다^^ 차분하게 한 작품씩 완성할 수 있어요♡ 작품한 것들을 집에 걸어 놓으니 정말 멋져요! 다음에 또 방문하겠습니다.', 67, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '남자친구랑 귀멸의칼날 캐릭터하나씩 만들었어요! 코쿠시보랑 아카자~!🥰🥰 음료랑 케이크도 넘넘 맛있고 사장님 완전 짱친절하세용~~! 초보자도 넘 잼나게할수있고 가격도 이정도면 엄청 저렴해서 부담없는 데이트코스로 짱이에요~~! 담에 또 올게용🍒🍒', 4, 5, 'GOOD', SYSTIMESTAMP);
