INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '우선 사장님이 너무 친절하시고 싼 가격에 이 정도의 퀄리티를 즐길 수 있어서 좋았습니다...!! 다음에 또 오고 싶어요🫶🫶🫶 생각보다 어려웠지만 친구랑 서로 피드백 해주면서 하니까 두 시간 순삭...!😻다음엔 캔버스도 도전하러 오겠습니당👏', 81, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '금요일날 방문했었는데 완성을 다 못해서 일요일날 또 방문했어요!! 중간중간 사장님께서 그림도 봐주시고 칭찬을 너무 잘해주셔서 기분좋게 마무리할수있었어요!! 아무날도 아닌날을 특별하게 보낼수있어서 더 좋은거같아요 집에 장식처럼 둘거라 큰걸로해서 오래걸렸지만 작으면 금방 끝날거같았어요 ㅎㅎ 하지만 이걸 직접 생각해서 하는게 조금 어렵다 생각했는데 하다보니 너무 쉽고 재밌게해서 또 하고싶다 생각했어요 ㅎㅎ 비오고, 더울때 실내데이트로 딱이에요!!', 94, 19, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '솜씨 뽐내겠다고 어려운 명화를 선택하는 바람에 3번째 방문 후 완성했습니다 🥹 사장님이 너무 친절하고 다정하세요! 계속 폭풍 친찬 해주셔서 방문 할때마다 어깨가 으쓱으쓱해요 😆 인테리어가 통창이라 뷰가 너무 이뻐서 데이트 하거나 기분전환할때 너무 좋아요! 저는 혼자도 갔었는데 흘러나오는 재즈 들으면서 시간가는줄 모르고 집중할 수 있었습니다 완전 추천! 곧 다시 놀러 갈게요 💕', 7, 9, 'GOOD', SYSTIMESTAMP);
