INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '처음 진행하는 거라서, 조금 어려웠는데 엄청 친절하게 설명해주시니 금방금방 진행했습니다! 일단 제일 좋은게… 도안이 진짜 많아요! 동생이랑 같이 왔는데, 고르는 재미가 쏠쏠해영ㅋㅋㅋㅋ 시간 가는 줄도 모르고 왔습니당!! 다음에 또 와서 할거에용!!! 그리고 된다면 평일에 오는걸 완전 추천해요!!!', 35, 4, 'GOOD', SYSTIMESTAMP);
