INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '남자친구랑 200일 기념으로 이색데이트 해보자고 해서 찾은 드로잉카페!! 들어가자마자 사장님이 엄청 친절하게 응대해주셔서 너무 좋았어요!! 저는 도안 없는걸로 남자친구는 도안 있는걸로 해서 그림을 그렸는데 거의 마지막 타임에 들어간거라 더이상 손님이 안오셔서 그림을 완성해서 갈 수 있게 배려해 주셨어요!! 앞으로 기념일이나 그림 그리고 싶을때 또 방문할거 같아요ㅎㅎㅎ', 126, 22, 'GOOD', SYSTIMESTAMP);
