INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '홍대와서 뜻깊게 뭘 할 수 있을까 찾아보았는데, 남자친구랑 데이트하기 너무 좋았어요♡ 둘다 똥손인데 조용히 원하는 걸 집중하면서 몰입해 보는 경험이 좋았던 것 같아요. 나만의 피규어를 만든 것 같아서 뿌듯했습니다^^', 51, 17, 'GOOD', SYSTIMESTAMP);
