INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '다같이모여서 캔버스 그림도 그리고 베어브릭도 그렸는데 재밌고 음료도 마시고 좋아요 또 홍대에서 이만큼 조용한 카페는 찾기힘들거요 ㅎㅎ 강추합니다 담에 또 오고싶어요 !! 시간이 조금 초과했는데 뒤에 예약자가 없어서 더 그릴수있었어요 ㅎ.ㅎ', 78, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '친구랑 둘이서 갔는데 정말 좋았습니다….🥹 카페 분위기가 그림 그리는데에 집중하기 좋고 사장님도 너무 친절하셨어요! 평소에 열린 공간에서 그림을 잘 못 그리는데 그것도 잊은채로 편안하게 그림 그렸어요ㅠㅠ 다음에 다시 오겠습니다!!💕', 41, 7, 'GOOD', SYSTIMESTAMP);
