INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '제대로 그림 그려본게 고등학교 졸업후 처음 입니다 사장님께서 친절하시고 설명 상세히 해주셔서 어렵지않게 그려볼 수 있었습니다 전면 유리창이라 햇빛 잘들어오고 분위기 좋았습니다 그림이 마음을 치유한다고 하던데 정말 그랬습니다 차분해지고 보람있는 경험입니다 다음에 또 그려보고 싶어요', 9, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '날씨가 많이 더워서 실내데이트를 찾던 중 어반스페이스드로잉카페를 찾게돼서 예약을 하고 왔는데 사장님께서 엄청 친절히 안내해주셔서 너무 수월하게 할수있었어요!! 근데 시간이 너무 오래걸려서 ㅜㅜ 금요일날 방문했는데 완성을 못해서 사장님께 말씀드렸더니 한번 정도는 맡겨주실수있다고하셔서 맡기고 왔어요!! ㅎㅎ', 94, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '단체예약으로 다녀왔는데 사장님도 친절하시고 음료도 맛있었어요! 중간중간 스몰토크도 먼저 걸어주셔서 덕분에 즐겁게 체험하고 갑니다. 정말 재밌었어요~~!!', 119, 20, 'GOOD', SYSTIMESTAMP);
