INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '드로잉 카페 가고싶어서 찾아보다가 브릭베어 행사중이길래 방문했어요! 크기는 대형으로 했고 대형인데도 가격이 행사중이라  정말 저렴하고 알차게 이색데이트 즐겼습니다!  생각한거보다 더 재밌고 시간이 잘가요! 다음에 또 올 것 같습니당!  직원분들도 친절하세요!', 37, 3, 'GOOD', SYSTIMESTAMP);
