INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '처음으로 드로잉카페를 와봤는데 모든 것이 잘 준비되어 있어서 너무나 편리하게 즐겼습니다 차도 마시고 새로운 즐거움도 찾고. 무엇보다 사장님께서 친절하셔서 처음 가셔도 쉽게 해볼 수 있어서 참 좋아요~ 또 방문 하겠습니다~~', 11, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '힙한 분위기에서 그림에 집중할 수 있는 공간이에요. 다양한 재료를 자유롭게 쓸 수 있어 초보자도 부담 없이 시작할 수 있고, 그림이 서툴러도 편안하게 머물 수 있도록 배려된 분위기가 인상적입니다. 음악도 적당히 깔려 있어서 몰입하기 좋아요. 사장님도 친절하고, 완성한 작품은 가져갈 수 있어 뿌듯함도 느껴져요. 혼자 오기도 좋고 친구와 함께 와도 부담 없는 분위기라 재방문 의사 있어요.', 35, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '사장밈도 너무 친절하시구 재밋는 경험이었어요!!!! 재방문 의사 200!!! 시간 가는줄 모르고 놀다 왔습니다 특히 여름에 에어컨 빵빵해서 실내데이트로 매우 추천해용❤️', 14, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '사장님께서 너무 친절하셨어요! 베어브릭 너무 귀엽고 저는 소형 했는데 크기도 다양했습니다 물감 색도 많고 도구들 많아서 충분히 원하는 컬러로 디자인 가능했구요! 음료도 맛있고 시설도 쾌적해서 너무 좋았어요 감사합니다☺️', 117, 21, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '베어브릭 처음 만들어봤는데 너무 재밌게 만들었어요 ㅎㅎㅎ 원래 소형 예약했었는데 실수로 중형으로 주셔서 추가요금 없이 큰 사이즈로 했네요 감사합니다 🥰 분위기도 좋고 사장님도 친절하셨어요 🤓', 33, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '예약 안하고 들어갔는데, 바로 할 수 있었어요 ~ 시원한 에어컨 아래서 그림 그리면서 얘기도 하고 좋은 추억 만들었습니다 ~ 사장님 너무 친절하시고 좋아요 !! 여름날 최고의 드로잉카페 🥰', 7, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '당일날 예약 하고 갔는데 사장님이 너무 친절하셨어요 음료랑 팥빙수도 너무 맛있었고 시간 가는줄도 모르고 했어요 인테리어도 너무 예뻐용 덕분에 재밌게 즐기다 갑니당 다음에는 그림 그리러 다시 방문 하겠습니다!', 6, 2, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '그림으로 할까 하다 브릭베어 “대”로 결정!!! 처음 해봤는데 너뮤 맘에들어요!!!! 대박!! 소 소이즈 고민하다 큰걸로 했는데 대만족!', 40, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '두번째 방문 !! 이번에는 좀 더 큰 베어로 선택했는데, 시간은 더 걸렸지만 재미도 두배였어요 ~ 친구와 좋은 시간 보내고 보람있네요 :) (집에 와서 화분 옆에 놓고 사진 한장 더 남겨요 ~)', 13, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '정말 좋아하는 친구랑 즉흥적으로 왔는데 사장님이 정말정말 밝고 친절하셔서 기분 좋게 데이트 했어요 !! 그림에 자신 없었는데 그림 그리는 것도 도안이 있어서 좋았어요 :) 물감도 원하는 대로 짤 수 있어서 좋았고 평소에 경험하지 못하는 특별한 경험이었어요 🎨🤍 강추합니다', 89, 17, 'GOOD', SYSTIMESTAMP);
