INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '드로잉 카페 항상 지나가면서 궁금했었는데 이번에 방문했어요 😊 사장님이 너무 친절하시고 잘 챙겨주시는것같아요!! 물감도 다양하게 많고 자리도 편하고 분위기 좋아요! 🥰 시간 나면 또 오겠습니다!!', 20, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '홍대에서 즐길거리를 찾다가 방문했습니다! 저는 키우던 고양이를 색 칠했어용 모형이 굴곡져서 힘조절하며 그리기 힘들었지만 다 그리고나니 엄청 뿌듯하고 재밌었어요! 지금은 프로모션중이라 저렴하게 왔지만 없어도 충분히와서 좋은시간 보내고 갈 것 같아요!', 49, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '홍대에서 독특한 경험을 만들수도 있는데 인테리어가 너무 이쁘고 음식이 맛있어요 👍🏻 크로플이 시나몬이랑 잘 어울려서 좋았어요. 음료도 담백하게 달달한 편이고요 ㅎㅎ 직원분들이 친절하셔서 재밌게 즐기고 왔습니다!', 23, 10, 'GOOD', SYSTIMESTAMP);
