INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '아이들과 홍대에서 뭐할까하다가 검색해서 왔는데 너무 좋아요. 사장님도 너무 친절하시고 아이들더 너무 좋아하고 재미있게 시간 보내고 가네요!! 자주 올거같아요^^', 17, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '남자친구랑 무슨 데이트 하지~? 하다가 드로잉 카페에 왔어요!!!!! 평일에 와서 그런지 사람도 많이 없고 조용한 분위기에서 집중해서 그림 그릴 수 있어서 좋았어요!! 사장님도 친절하시고 차분하셔서 분위기가 따뜻하고 편한 느낌이었어요. 진짜 너무 집중도 잘 되고 행복한 하루였던 것 같아요. 행복하뉴시간 보내게 해주셔서 감사합니다:) 다음에 또 올게요!!!', 45, 2, 'GOOD', SYSTIMESTAMP);
