INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '지인한테 추천 받아서 남자친구랑 같이 왔는데 생각보다 재밌고 남자친구랑 즐거운 추억 만들어서 너무 좋아요! 가족, 연인, 친구들이랑 와도 너무 좋을거 같아요!! 사장님도 너무 친절하시고 사진도 어떻게 찍으면 예쁘게 나오는지 알려주셔서 너무 좋았어요!!!! 다음에 또 오고싶은 가게에요~! 좋은 추억 만들고 갑니당!❤️ 번창하세요 사장님!!!', 39, 3, 'GOOD', SYSTIMESTAMP);
