INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '친한 언니랑 같이 왔어요! 저는 제 애착인형을 그리고 언니는 풍경을 그렸어요! 물감 종류도 많고 시설도 좋아요~ 역에서 멀지 않아서 접근성도 좋네요! 덕분에 좋은 추억 쌓고 갑니다 감사해요', 6, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '여자친구랑 같이 그렸는데 사장님이 칭찬을 칭찬을~~ 정말 스트레스가 싸악 풀리네요!! 데이트를 할 거라면 어반스페이스 드로잉카페 앤 펍~~~', 34, 9, 'GOOD', SYSTIMESTAMP);
