INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '남자친구와 드로잉카페에서 데이트 하고 왔어요! 저는 고양이 집사라 고양이 그림을 선택했는데 사장님께서도 고양이 집사셔서 반가웠습니다 😺 분위기도 좋고 넓은 공간에서 차분하게 집중할 수 있어서 좋았어요~ 그리고 사장님 너무너무 친절하십니다! 다음에 또 방문할게요❣️💓', 70, 18, 'GOOD', SYSTIMESTAMP);
