INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '친구들이랑 홍대에서 놀거리 뭐 있을까 하다가 발견한 곳으로 예약 없이 이용할 수 있을까 했는데 그냥 방문해서 할 수 있어서 너무 좋았어요 고를수있는 선택지도 다양하고 저렴한 가격에 친절하신 사장님과 그림그리기에 좋은 도구들까지 자유롭게 이용할 수 있어서 친구들이랑 놀기에 딱이었어요~~', 44, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '손재주 없는 사람들도 쉽고 재밌게 체험할 수 있어서 너무 좋았습니다!! 사장님께서 너무 잘했다고 칭찬도 많이 해주셔서 감사했습니다..🤍', 27, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '🎨 어반스페이스 드로잉카페 앤 펍 - 온 가족이 함께 즐길 수 있는 창의적인 공간! 카페 분위기가 밝고 아늑하며, 어른과 아이 모두에게 잘 어울리는 공간이에요. 커피를 마시면서 그림 그리기나 색칠하기 같은 재미있는 활동도 할 수 있어요. 직원분들도 친절하고 응대가 매우 좋았어요. 휴식도 되고 창의력도 키울 수 있는 정말 멋진 장소예요. ⭐ 평점: 5/5 – 꼭 다시 방문하고 싶어요!', 14, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '평일 1시 여자친구랑 처음 와봤는데, 사장님 느긋한 말투부터 분위기까지 편안함을 주는 곳이에요. 덕분에 그림에만 집중할 수 있었고 정말 특별한 시간, 특별한 경험, 행복한 기억으로 남을 거 같아 기분이 너무 좋았어요.! 사장님도 너무 친절하셔서 다음에 기회가 된다면 또 방문할 수 있도록 하겠습니다. 늘 좋은 하루 보내시길 바라며 행복한 하루의 일부분을 만들어주셔서 감사합니다~', 126, 22, 'GOOD', SYSTIMESTAMP);
