INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '그림을 아무리 그려도 질리지 않는 깔끔한 인테리어에 창가자리는 탁 트인뷰, 친절한 직원분, 무료하던 주말이 알록달록해지는 다양한 아크릴물감들까지 입시에 지친 삶속 고민들을 털어버리기에 좋은것 같습니다~!!', 22, 0, 'GOOD', SYSTIMESTAMP);
