INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '조용한 분위기에서 편하게 그림 그릴 수 있어서 좋았습니다. 가격도 싼 가격에 친구랑 좋은 추억을 쌓을 수 있어서 좋아요. 사장님도 친절하십니다.', 21, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '쾌적한 메장에 친절한 사장님이 계셔서 좋은시간 보내고 갔습니다! 디져트와 크로플도 맛있었고 그림을 쉽게그리기 위한 도구들과 도안이 준비돼있어 부담없이 방문할 수 있는곳인것 같습니다! 번창하세요~^^', 51, 11, 'GOOD', SYSTIMESTAMP);
