INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '사장님이 너무 친절하시고 드로잉카페여서 그림도 같이 그릴수있는 카페라 너무너무 좋은것같아요! 일때문에 드로잉은 못했지만 다음번에 드로잉도 하러 오고싶네요 ㅎㅎ', 7, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '남자친구한테 드로잉카페 가자고 졸라서 간건데, 남자친구가 저보다 더 좋아했어요🩷 토욜 7시였는데 아무도 없어서 저희끼리 너무 편하게 이용했고, 도안이 엄청 많아서 저처럼 그림 못그리시는 분들도 도안 골라서 열심히 색칠만 하면 돼서 재밌어요!! 그리고 직원분이 너무 친절하셔서 있는 내내 기분이 좋았어요 서비스도 너무 감사합니다 ☺️☺️ 다음에 드로잉 카페 데이트 하고싶을때 또 갈게요! 홍대입구역 내리자마자 너무 시끄러워서 기빨렸는데 들어가자마자 조용하고 아늑한 느좋 분위기에 너무너무 만족했던 하루였어요~!!! 번창하세요 🔥🔥', 75, 11, 'GOOD', SYSTIMESTAMP);
