INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '두번째 방문입니다😆 올때마다 진짜 마음편하게 재밌게 그리고 가요! 직원분도 너무 친절하시구 좋습니당 오래오래 있어주세요! 그림 또 그리러 올게요!', 23, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '그림 동아리 친구들이랑 이용했는데 분위기도 좋고 저희끼리만 사용해서 더 아늑하고 아지트에 온 기분이었어요!! 덕분에 좋은 추억 많이 만들었습니다🙌⭐️❤️🫶🏻', 58, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '구 소마 드로잉카페 일때부터 종종 드로잉 하러 왔던 곳이였는데 어반으로 바뀌고는 처음가봤습니다! 그전에도 분위기가 진짜 좋았는데 바뀌고 나서 가게도 1층에 있고 내부 인테리어도 너무 예쁘고 좋았습니다ㅎㅎ', 66, 17, 'GOOD', SYSTIMESTAMP);
