INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '원래 가려던 곳 있었는데 가는 길에 분위기가 확 끌려서 여친 꼬셔서 즉흥 입장! 매장 깔끔하고 사장님도 친절하십니다! 게다가 드로잉 카페라는 컨셉에 맞게 인테리어나 음악이 감성적이예요 여친이 그림 그리는 거 좋아하는데 딱 그런 분위기라고 좋아하네요! 테이블에 인당 한명씩 쓸 수 있도록 작은 종이 있는데 드로잉 감성은 있는데 그림을 하나 그리기에 부담 있으시면 그 감성 그대로 끄적이면 해소돼요! 만족스러운 카페였습니다!', 18, 3, 'GOOD', SYSTIMESTAMP);
