INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '오랜만에 친구들이랑 만나는데 맨날하는 카페탐방과 수다말고, 특별한 걸 하고 싶어서 찾은 곳입니다. 통유리창의 1층이 안그래도 깔끔한 내부를 더 쾌적하게 느껴지게 했어요. 사장님인지 직원분인지 친절히 안내해주셨고, 노래도 잔잔해서 편안한 기분으로 제법 긴 시간 집중할 수 있었어요 :) 그림 그리는 건 좋아하고 제법 잘한다고 여겼는데 물감 사용은 정말 어렵더라고요. 그치만 즐거웠습니다! 그리고 제가 이 날 카드를 잃어버렸는데, 사장님께서 마감 시간에도 따로 연락 주시고, 다음날에도 꼼꼼하게 찾아봐주신 후에 연락 주셔서 정말 감사했어요. 물론 다른 곳에서 잃어버려서 찾지는 못했지만 배려와 친절에 무척 감사했던 기억이 오래 남네요 :) 다음에도 또 방문하고 싶습니다✨🎵', 18, 6, 'GOOD', SYSTIMESTAMP);
