INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '그냥 갑자기 그림그리고싶어서 당일예약하고 바로 다녀왔어요! 손이 너무 덜덜 떨려서 채색을 못하겠어서, 혹시 마카있냐 여쭤봤고ㅠ 없다고 하셔서 포기하고 있었는데 잠시있다 바로 구매해와서 주셔서 겨우 시간안에 끝낼 수 있었어요 💓 정말 감사했습니다 집앞인데 너무 좋은 기억으로 남아서 조만간 또 그리러 가려고해요~', 19, 5, 'GOOD', SYSTIMESTAMP);
