INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '제 인생 첫 드로잉 카페예요! 그림 그리는걸 너무너무 좋아하는데 진짜 즐거운 시간 보냈어요! 사장님도 엄청 친절하세요! 서울 놀러가면 또 가고 싶습니다🥹', 38, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '여기 너무 좋아요 🫶🫶 제가 드로잉카페를 좋아해서 용산 부산 여기저기 많이 다녔는데 여기가 제일 좋았던 것 같아요! 사장님도 너무너무 친절하시구 서비스도 완전 좋아서 완전 반했답니다,, 다음에 또 오기로 하고 그림 보관하고 나왔어요! 드로잉카페 어디갈지 고민중이라면 여기로 추천드립니다!', 30, 1, 'GOOD', SYSTIMESTAMP);
