INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '평일 저녁에 방문했는데 평일이라 그런지 저희만 있었어요!  친절하게 이용방법 안내해주셨고 도안을 고를수도 있는데 저는 직접 그려보았습니다. 음악 잔잔히 나오면서 친구랑 도란도란 얘기하면서 그림그리는데 정말 힐링이었어요 ㅠㅠㅠ 다음에 또 와서 그때는 도안으로 그려보려고요!', 34, 9, 'GOOD', SYSTIMESTAMP);
