INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '예약하고 방문했구요 드로잉카페는 처음이었는데 마음에 드는 도안을 고르고 도안이 그려진 캔버스에 색을 칠하는거라 어렵지는 않았어요😊 음료랑 케이크도 맛있고 음악들으면서 그림에 집중하다보니 시간 가는줄도 몰랐네요! 사장님, 직원분도 친절하시고 인증샷도 열심히 찍어주셔서 감사했어요👍👍', 50, 5, 'GOOD', SYSTIMESTAMP);
