INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '여자친구가 좋아하는 것을 같이 해보고 싶어 방문했습니다! 그림 종류가 많아서 실력에 따라 그림을 마음껏 고를 수 있고, 그림도 풍경,인물 등 다양한 주제가 있어 고르는 맛이 있습니다. 붓이랑 물감, 앞치마, 토시 등 드로잉 하는데 필요한 장비들은 모두 구비되어 있어서 정말 몸만 가도 돼서 편해요! 사장님께서도 친절하셔서 손쉽게 가르쳐주시고 음악도 차분하니 집중하기 좋습니다. 남자분들도 여자친구분들과 한 번 방문해보시는걸 추천드려요!', 8, 9, 'GOOD', SYSTIMESTAMP);
