INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '홍대에서 지나가다 궁금해서 방문했는데 깔끔하고 저는 오후에 갔는데 분위기 너무 좋았어요😊 (사진 왕창 찍음ㅎ) 이런 거 소질 없어서 걱정하고 갔는데 직원분도 친절하시고 어렵지 않게 할 수 있어서 재밌었어요ㅎ 다음에 또 올게요!!!:) 소마드로잉에서 어반스페이스로 이전하신거래요!', 33, 5, 'GOOD', SYSTIMESTAMP);
