INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '드로잉 카페는 처음인데 정말 재미있었어요-!! 이색카페라 음료나 디저트는 기대 안했는데 넘 맛있었습니다ㅎㅎ 친구랑 즐거운 추억 쌓고 가요-!!💞', 179, 33, 'GOOD', SYSTIMESTAMP);
