INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '약속시간까지 2시간정도 시간이 남아서 카페 찾아보다가 다른분이 쓰신 블로그보고 궁금해서 처음와봤어요 사장님 말씀 들어보니 소마드로잉에서 여기 어반 스페이스로 이전하셔서 아직 가오픈이간이라고 하시더라구요! 혼자서 하기 좀 민망했는데 도안도 이쁜걸로 꼼꼼히 같이 고민해서 찾아주시고 그림 그릴때도 중간에 오셔서  도와주셨어오 ㅜ 초코바나나라떼(?) 마셨는데 잔도 너무 이쁘고 맛있더라구요 마지막에 사진도 이쁘게 찍어주시구 사진 들고있는것도 찍어주셨는데 민망해서 그림만 찍은걸로 올려요  덕분에 너무 재밌구 좋은 경험 했습니다😆 다음에는 친구 꼭 데리고 올게요!!', 45, 0, 'GOOD', SYSTIMESTAMP);
