INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '예전에 드로잉 카페 가서 시간가는지 모르고 그리던 기억이 있어서 찾아 갔는데 , 소마 드로잉에서 어반스페이스로 이름을 바꾸셨네요? 저번보다 훨씬 분위기도 좋은거 같아요. 사장님도 여전히 친절하시고, 커피맛도 좋구요. 이번에도 오랜만에 홍대와서 즐겁게 시간 보내다 가네요 ^^', 18, 4, 'GOOD', SYSTIMESTAMP);
