INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '도안 선택지가 많아요. 원한다면 개인 자유도안으로 선택할 수도 있습니다. 내부가 깔끔한 화이트톤이고, 넓고, 선곡도 잘해주셔서👍👍 그림에 집중하기 좋았어요. 직원분이 정말 친절하십니다! 즐거운 시간이었습니다~', 242, 59, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '평일에 가서 그런지 모르겠는데 대기없이 바로 입장했어요 ! 월래 소마드로잉 다른 지역에서 한번 가봤는데 여기 지역에도 있다해서 놀러온김에 찾아보니까 바로 옆건물인 어반 스페이스로 이전했다구 하더라구요 혼자서도 조용히 이용가능했구 커피도 맛있고 사장님이 팁도 알려주시구 친절하셨어요. 가족끼리 오거나 연인끼리 와도 재밌게 즐길 수 있을 것 같아요 !!', 43, 10, 'GOOD', SYSTIMESTAMP);
