INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '친구랑 와서 좋은 시간 보내고 갔어요! 음악도 잔잔하니 집중하기 좋았고 사용방법도 너무 친절하게 설명해주셔서 너무 편하게 이용할 수 있었습니다~', 91, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '원래 소마드로잉카페 위치에서 옮기셨다고 하네요. 방문하시는 분들 참고해주세요! 저희 대부분이 그림 초등학교 이후로 안그려본 초짜들이었는데 사장님이 너무 친절하게 팁도 주시고 도안들도 너무 예뻐서 재밌게 그렸습니다!! 즐거운 시간 보낼 수 있게 해주셔서 감사했습니다!', 47, 6, 'GOOD', SYSTIMESTAMP);
