INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '주말에 아이들 데리고 놀러갔었는데 사장님도 엄청 친절하시고 음료도 맛있고 카페분위기가 예뻐서 사진도 잘나오고 아이들이 너무 좋아해요.담에 또 방문 예정이에요 ㅋㅋ', 15, 6, 'GOOD', SYSTIMESTAMP);
