INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '사장님이 너무 친절하시고 분위기 있고 재밌어요ㅠㅠ 최고에욧 나중에 남자친규가 생긴다면 꼭 같이 오고 싶네요 ㅎ.ㅎ.. 재밌는 추억 만들고 갑니다!! 다음에 또 와서 다른거도 해보고 싶어욧ㅎㅎ', 115, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '어반스페이스드로잉카페 앤 펍'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '주말에 예약 없이 갔는데도 자리 충분했습니다. 약간 비싸긴한데 물감이나 붓 자유롭게 사용할 수 있었던 거 생각하면 괜찮은 것 같아요. 오래 얘기하기에 정말 좋고 뿌듯한 결과물도 만들 수 있는 장소라 정말 추천합니다! 그리고 사장님께서 정말 친절하시고 도움 많이 주세요😄😄', 41, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 사운드웨이브 합정점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '손그림들이 건물에 가려져서 안보여서 아쉬웠습니다 블라인드나 커텐해서 보일수있게하면 좋을텐데 그리고 좌석문제도 아쉬웠습니다 시간제한이 있는게 아니니 제가 입장하고 나서도 있던분들이 교환 목적으로 안가고 계속있으니 뒤에 오신분들이 자리를 기다리는 상황이 생겼습니다 요부분은 개선이 필요할거같습니다 화장실은 한칸씩 각각 있는데 여화장실 물쪽뚜껑 깨졌고 휴지도 꽉차있는데 정리가 아쉬웠습니다 계단쪽에도 멤버들 얼굴이 있는데 어두워서 잘안보였는데 저녁되면 보여질것같네요 그외로는 이렇게 꽉차게 꾸며진게 간만이라서 너무 좋았습니다', 29, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 사운드웨이브 합정점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '메뉴 종류가 너무 적어서 아쉽습니다 생각보다 꾸며놓은게 별로 없어서 볼게많이 없는 느낌 이었습니다 한직원분은 친절하지만 다른분은 너무 뾰루퉁해 계시네요 음.. 직원분들의 설명도 좀 부족한듯 합니다 써놓기만 한다고 다 알진않아여 생일이라 조용히 나옵니다', 37, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 사운드웨이브 합정점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '아이브앨범사러 아이와 함께 왔어요~처음 가본곳인데 다른데하고 다르게 앉을수 있는 테이블이 많아서 좋았어요.학생들과 부모님들이 같이 많이 오셨어요.아이가 한참동안 포카교환한다고 안가서 카페라떼,아이스초코라떼 주문해서 시원하게 마셨어요.사람이 많아서 그런지 실내가 많이 더워서 좀 불편했어요.', 11, 7, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 사운드웨이브 합정점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '아이가 스키즈를 좋아해서 같이 방문했어요 메뉴가 다 품절이라 음료만 마시고 왔어요 그리고 카페 예약이 너무 힘들어요ㅠㅠ 다음엔 좀 쉬웠음 좋겠어요ㅠㅠ', 23, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 사운드웨이브 합정점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '바로 앞에서 컵케잌 아이스크림 다 품절되서 못 먹었습니다 타임마다 인원수도 제한하면서 물량은 충분하지 않아서 이럴거면 그 고생을 하며 예약은 왜 했나 싶더라구요 이쁘게 꾸며놓긴 했어요', 53, 18, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 사운드웨이브 합정점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '사운드웨이브 럭드를 하기 위해 방문하였습니다. 앨범을 구매하구 럭드를 하고 지인들과 즐거운 시간을 보냈습니다. 항상 친절한 직원 언니들 너무 좋아요:)', 51, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 사운드웨이브 합정점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '진짜 팝업 체계 개별로 사람 몰릴줄도 몰랐을까? 1인당 품목을 1개씩으로 라도 줄였어야지 세계적 인기 아티스트의 인형 팝업인데 사재기도 몰릴걸 과연 몰랐을까? 첫 타임에 들어갔는데도 텅텅파크네요 여유롭게 구경은 커녕 전투적으로 물건 집기 바쁘고 품절나고 ..이런일 다신 겪고싶지 않음', 26, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 사운드웨이브 합정점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '20230528 김재환 생카방문!♥ 음료수 디저트  너무맛있고 재환이의 사진으로 가득한 카페! 너무 이쁘고 너무 행복하당!!😉👍❤', 44, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 사운드웨이브 합정점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '팝업 마지막날 .. 사복 직원 정말 불친절 내가 괜히 비오는날 밤부터 기다린줄 아나 인형 한개도 못사서 좀 사게해달라니까 끝이래놓고 뒷타임은 인형꺼내주고 정말 체계없는것', 19, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 사운드웨이브 합정점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '아이브땜에 갔지만 웨이팅을 이따위로 하면 어쩌자는거죠...개고생했어요 저보다 뒤에계시던 분이 입장할때 앞에 ㄱ메시고 .... 10시30분에 와서 7시30분에 입장을 했어요.', 55, 12, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 사운드웨이브 합정점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '주문 많이 밀린건 알겠는데 여자사장님인지 알바생인지 한숨 푹푹쉬고 짜증내면서 공격적으로 말하시고.. 인력충원을 하든지 장사하기 싫으시면 이벤트를 받지마세요..', 41, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 사운드웨이브 합정점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '케플러 데뷔 1주년 기념 카페 다녀왔지요 💞 케플러 모두 귀엽고 예뻐서 사진보는데 시간가는 줄도 모르고 행복한 하루였어요~ 그리고 케플리안(케플러 팬덤) 실제로 첨 봤는데 모두 예쁘고 친절해서 천사같았다구용 ㅠㅠ 포토카드 나눔도 받고 최고최고 ! 저는 왕복 8시간 걸렸지만 다녀오길 잘한듯 해요. 케플러가 에너지 뿜뿜 하니 케플리안도 에너지 뿜뿜 한다구요. 케플러 케플리안 사랑행 ❤️ https://m.blog.naver.com/wldnwlsghd/222982897100 자세한 후기는 지농츄 블로그에도 올려봤지요, 궁금하면 논너오세용 💞', 87, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 사운드웨이브 합정점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '방탄소년단 진 솔로 싱글 The Astronaut 발매기념 럭키드로우 이벤트 하러 방문했습니드 매장 전체 예쁘게 앨범 전시와 뮤직비디오 들어놔줘서 좋았어요 !', 12, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 사운드웨이브 합정점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '럭드하러 갔는데 너무너무 재밌었어요~!!! 앨범까서 현장에 있는 다른 분들이랑 바로 포카교환도 하고 좋아욯ㅎㅎㅎ 덕분에 유진이 드볼하고 왔어요…🥺💫 손님 너무 몰려서 직원분들도 피곤하실텐데 넘 친절하게 응대해주셨습니다아☺️', 34, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 사운드웨이브 합정점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '공간은 좀 협소했지만 넘 갖고 싶었던 인형이랑 쿠션 재고 넉넉하게 채워져 있어서 행복했습니다ㅠ 카페도 아기자기하게 잘 꾸며놓으셨더라구용ㅎㅎ 음료랑 마카롱 쿠키 세트도 넘 귀여웠어요!!', 56, 15, 'GOOD', SYSTIMESTAMP);
