INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 사운드웨이브 합정점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '3층 카페에서 음료수 마시고 집에 갈려고 1층 내려온다 지하 있어서 구경 했는데 재고 엄청 많이 있는데 왜~~~ 진열도 안하고 판매도 안하는지 궁금하네요 재고 없다는 직원분이 애기 거짓말 미니 파우처 엄청 박스도 보이고 2층 없어서 못 구매한  물건 지하  다 있네요', 30, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '카페 사운드웨이브 합정점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '정동원 팝업카페여서 방문했는데 여자직원분 왜이리화가나있나요? 젊은분들도 방문 하겠지만 나이가 좀 있으신분들이 좀 더 올텐데..  반응이 느리거나 이해를 못했으면 한번 더 말해주면 되는걸 화내듯이 말하니까 기분 나빴습니다. 뭐 저희가 잘못한거 있는거마냥 말투가 공격적이시네요. 과연 저만 그렇게 느꼈을까 싶어요 좀 뒤늦게 오신분도 어이없어하는 느낌이던데 .. 처음에는 이렇게 느꼈고 그후에는 물어보면 응대 잘해주시긴 했으나 처음에 임팩트가 넘 강했네요..; 아무튼 같이 온 가족이 정동원군 좋아해서 방문했는데 저거 외에는 괜찮았습니다.', 21, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '컴포즈커피 홍대삼거리점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '⭐️ 내돈내산리뷰 ⭐️ 테이블 4인석 1개 , 2인석 1개로 넓진않음 직원분들 친절함 음료 점바점 가끔있는데 여기 컴포즈 ㅈㄴ 맛있음 쿠키초코프라페 곡물라떼 두개다 넘 존맛탱 시간떼우다갈려고간건데 괜찮네요 방문 ㄱㄱ', 14, 3, 'GOOD', SYSTIMESTAMP);
