INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '컴포즈커피 홍대삼거리점'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '이 근처에서 여름근처까지 생활을 할 것 같아서 방문했어요. 거의 매일 올 것 같습니다. 저는 엄청 놀란게 프랜차이즈 카페는 대부분 불친절한데 너무 상냥하셔서 놀랐어요. 자주 오게 될 것 같아요. 깨끗하고 깔끔합니다 :)', 50, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '컴포즈커피 홍대삼거리점'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '사장님 엄청 친절하셔요. 음료야 뭐 점바점이기도 하고 다 비슷한데 목소리도 표정도 말투도 상냥하시고 음료 한잔에 기분이 너무 좋아요!!', 37, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '컴포즈커피 홍대삼거리점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '원래 컴포즈는 잘 안 갔었는데 6월 초까지는 상수역에서 지내야 될 것 같아 한 번 먹어봤어요. 사장님 진짜 친절하시고 알바생 분들도 대부분 친절한 편입니다. 매장도 깔끔하게 잘 운영돼 있고 최근에 아메리카노가 300원이 올랐지만 뭐 괜찮습니다 요즘 커피를 1800원에 팔면 남는 것도 많지 않을 거예요. 어쨌든 6월초까지 잘 부탁합니다. 평일에는 매일 갈 거거든', 111, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '컴포즈커피 홍대삼거리점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '치아바타샌드위치 맛있어서 세번이나 시켰는데,  포장비닐 안에 있는 그대로 전자렌지에 돌려도 괜찮은 비닐인가요? 처음 시켰을때 직원분은 집게에 직접 빼서 접시에 담아서 돌려서 포장해주셨는데, 다른 직원은 그냥 비닐채로 넣어서 돌리고 포장하더라고요.', 0, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '컴포즈커피 홍대삼거리점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '회사 점심시간에 자주 가는 카페입니다!! 🍕🍹 요즘은 앱으로 미리미리 주문 가능한 패스오더 많이 쓰던데 여기서도 패스오더 쓰면 더 좋을 것 같아요', 14, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '컴포즈커피 홍대삼거리점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '오베이 매장을 돌고 건너편 컴포즈 커피숍에서 프랜차이즈 가격 착하고 커피 맛있네요. 여기 커피맛 인정. 괜찮습니다. 원두가 괜찮은듯 하네요', 28, 5, 'GOOD', SYSTIMESTAMP);
