INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '컴포즈커피 홍대삼거리점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '어머니가 컴포즈 커피만 드세요. ☕️ 카페라떼가 맛있는 곳이라며 어디를 가도 컴포즈를 찾습니다. 이 날은 홍대에 놀러갔다가 잠시 들렀어요. 매장에서 먹어서 머그컵에 주셨는데 급히 가야해서 종이컵을 부탁드렸어요. 종업원분이 친절하게 종이컵에 담아서 주셨습니다. 번거로우셨을텐데 감사합니다.🥰', 8, 6, 'GOOD', SYSTIMESTAMP);
