INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '컴포즈커피 홍대삼거리점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '매장 안에 시원하고 자리도 편해요. 매장이 청결하고 음료도 맛있었어요! 주변에 이런곳이 있는 줄 오늘 처음 알았네요. 앞으로 자주 들리려구요😍🥳', 29, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '컴포즈커피 홍대삼거리점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '친구랑 종종 디저트도 먹을 겸 방문하는 곳인데 사장님도 친절하시고 좋아요. 무엇보다 가성비도 좋고 음료도 맛있어서 추천해요~! 요즘엔 아이스 티에 빠졌는데 달달하니 맛있어요~', 6, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '컴포즈커피 홍대삼거리점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '사장님도 친절하시고, 매장도 깔끔해요! 생각보다 디저트류도 다양해서 놀랬어요. 항상 커피만 마시다가 초코 케이크(꾸덕하고 찐함)랑 크림 롤케이크 먹고 넘 맛있어서 다른 맛도 먹어보려고 포장 해왔네요~ 가성비 좋아요👍', 45, 5, 'GOOD', SYSTIMESTAMP);
