INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '컴포즈커피 홍대삼거리점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '꽂히면 계속 먹는 습관이 있는데 이번달에만 세번가서 디저트랑 음료 폭풍 먹음. 음료도 맛있고 의외의 디저트 맛집임. 가격이 싸서 오히려 사실 기대를 안했는데 비싼 개인카페보다 백천만배 맛있음. 특히 찐한 꾸덕 초코케익 개맛', 20, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '컴포즈커피 홍대삼거리점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '요즘 자주 방문했었는데 오늘처럼 기분이 더러운적이 처음이네요. 그전에 방문했을 때 친절하게 응대해 주시고 가성비도 좋아서 자주 갔는데 2월4일 오전 11시 45분 근무하시는 분은 사장님이신 건지 직원분인지 손님 대하는 태도가 너무 불쾌했습니다. 표정부터 말투 일하기 싫으셨던 건가요? 설명 똑바로 해주세요. 키오스크 쿠폰 사용물어봤을 때부터 표정 안 좋고 하면 된다고 해서 했더니 사이드 메뉴는 또다시 따로 결제해야 된다고 하네요? 제가 다시 하는 것까진 아무 문제 없는데 그 표정 말투 너무 기분 나빠서 화가 나네요. 저도 근처에서 자영업 했어서 주변 사람들한테도 컴포즈 생겼다고 이용해 보라고 했었는데 잘못된 생각이었네요. 저는 앞으로  안 갈 테지만 오늘 불친절하신 그분 계속 그런 태도로는 안될 것 같습니다', 13, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '우연히 방문한 곳인데 분위기가 미쳤어요. 월요일 오후 8시즘 방문했고 손님들은 별로 없었어요 그래서 그런지 평일에 퇴근하고 와서 음료 한잔에 독서 혹은 할거라면 좋을 것 같더라구요 ㅎㅎ 좌석들도 편안했고 책 그리고 잡지, 엽서 등 볼거리가 다양해서 좋았어요 또 방문할거에요', 46, 10, 'GOOD', SYSTIMESTAMP);
