INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '홍대 예술인들을 위한 공간으로 작업하기 좋은 곳 👍 평소엔 디저트 카페 어쩔땐 예술마켓 제대로 복합문화공간 🙉 독특한 분위기로 책읽기도 좋은 곳 👏', 9, 4, 'GOOD', SYSTIMESTAMP);
