INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '로즈마리 라떼 괜찮아요 저는 노트북 작업하러 왔는데 나중에 영화나 공연 보러 와보고 싶네요. 메뉴가 다양하고 가게 분위기에서 예술가들의 멋이 느껴져요', 125, 21, 'GOOD', SYSTIMESTAMP);
