INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '홍대입구역 도보 15분 정도에 위치한 카페입니다. 지하에 위치하지만 창문이 뚫려있어 독특한 풍경을 볼 수 있습니다. 멋진 분위기와 구경거리가 있고, 음료 종류도 다양하니 근처시라면 들려봐도 좋을듯해요', 61, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '전형적인 인스타 (🙏🙏) 카페... 재방문 의사는 없습니다 ^^ 공간은 정말 멋진데, 좌석이 정말 불편하고 무엇보다 직원이 굉장히 퉁명스럽고 불친절해서 당황했어요. 원래 그런 거에 예민한 편도 아닌데 빨리 나가고 싶게 만들더라고요. 음료도 값이 비싼 편임에도 불구하고 그만큼 정성이 전혀 없었고요 (카페에서 음료 한 번도 남기지 않는데 여긴 반 이상 남김!) 몇몇 분들은 와서 노트북으로 작업하고 계시던데, 노래 소리가 커서 이야기할 만한 곳은 아니고...개인적으로 카공도 딱히ㅠ 꽤 유명해서 벼르고 벼르다가 갔는데 실망이 컸습니다', 19, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '재미있는 공간이네요. 자유로워요. 정리벽이 있으신 분이나 차분한 걸 좋아하시면 정신없다고 느끼실 수 있겠지만, 저는 이런 분위기를 편안해 해서요.', 25, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '평소엔 카페지만, 나는 공연장으로 처음 방문하게 된 공상온도. 공연 시작 전, 카페라는 사실을 알고 술보다는 커피를 한번 주문해봤다. 늘 먹던 라떼. 저녁 공연이라 따뜻한 라떼를 주문했다. 두툼한 밀크폼의 묵직한 밀도가 우유의 지방층이 꽤 진한건가라는 생각이 들었다. 평소엔 테이블과 의자가 세팅되어있었겠지만, 공연을 위해 벽쪽으로 밀어넣어 하나의 무대를 만드는 공간. 세상에는 다양한 공간이 많고 본인이 추구하는 무언가를 위해 힘써서 고생하는 노력이 보인다. 어떻게 알고 찾아왔을까. 좁고 높은 공간을 채운 사람들.', 10, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '디저트가 너무나도 제입맛에 딱 맞았어요🥹 그래서 첫 방문에 단골이 되고 싶은 생각을 했습니다.👍👍 디저트 모두 강추!!! 집 근처면 자주 가고 싶어요ㅎㅎ 차분한 분위기의 카페로 저는 좋아하는 분위기였어요~ 친구와 조용조용 이야기 나누고 나왔는데 힐링됐던 시간이라 머물렀던 이 공간이 더 좋게 느껴졌어요!', 83, 11, 'GOOD', SYSTIMESTAMP);
