INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '직접 읽어볼 수 있는 책들이 많아서 좋았어요! 혼자서 조용히 책 읽거나 작업하기 좋은 카페예요. 라떼도 맛있고 음악도 좋아서 만족한 카페입니다!', 33, 0, 'GOOD', SYSTIMESTAMP);
