INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '전체적인 공간느낌이 좋았어요. 작은 서점느낌이며 가정집에서 커피를 마시는 여유가 느껴졌어요. 아메리카노 주문 했는데 제 취향은 아니였지만 아늑한 분위기가 좋았어요. 주말이라 사람이 많았고 평일에 오면 혼자만의 시간을 보낼 수 있을 것 같아요.', 27, 6, NULL, SYSTIMESTAMP);
