INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '분위기 조용하고, 플레이리스트 잔잔하고 너무 좋습니다. 공상온도에 반했어요. 오래오래 그 자리를 지켜주시기를 바랍니다🫶🏼 홍대 갈때마다 들르고 싶어요. 비건 코코넛 까눌레 맛있어요!', 9, 7, 'GOOD', SYSTIMESTAMP);
