INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '언제 가도 좋은 공상온도 오래 머물고 싶어요 음악도 분위기도 음식도 맛있고 비오는 날 특히 힐링되는 곳 그래서 집근처가 아니어도 내 마음속 최애공간 하트', 6, 6, 'GOOD', SYSTIMESTAMP);
