INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '조용하고 테이블이 잘되어있어서 작업하거나 책읽기 좋은 공간이에요. 그리고 음료 짱맛있어요!!! 음료만 시켜도 안주처럼 과자를 주는ㅋㅋㅋ 베리 레몬 얼그레이 아이스티 짱맛👍👍👍 샤케라또도 커피 단맛 살짝 났다가 짱 맛있어요. 레몬스무디도👍👍 상큼하고', 72, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
