INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '옛날 홍대감성이 그대로 묻어있는 분위기좋은카페이자 서울 독립서점, 공연장 대관도 가능한 복합문화공간이에요~! 커피도 맛있고 친절함이 기본 매너로 장착되어있는 힙한 사장님까지♡ 다락방 스타일의 카페가 너무 개성 넘쳐서 오래 있고 싶은 곳이에요 ㅎㅎ', 6, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '공상온도 역시 라떼 맛집입니다🤍사실 그냥 맛집..! 로즈마리 라떼 먹을 때마다 입이 즐거워요-* 레몬 얼그레이 파운드는 다 먹고는 너무 맛있어서 하나 더 먹고 싶었는데 꾹 참았지만😌 다음엔 두 개를..☺️ 맛있는 음식들과 함께 책도 잘 읽고 편안히 머물다 가요 모두 공상온도 하세요 ◡̈', 85, 14, 'GOOD', SYSTIMESTAMP);
