INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '올 때마다 책을 읽기도, 개인작업을 하기도 너무 좋은 공간이라고 느껴요-* 다른 행사들로도 종종 방문했지만 사장님은 늘 깔끔히 친절하세요☺️  맛있는 후르트링과 디저트와 함께라면 책 한 권이 뚝딱! 음료도 맛있구요ㅎㅎ 책을 빠르게 읽는 편은 아닌지라, 마음이 급해질 수도 있었지만 공간이 주는 여유로움 덕분에 편안하게 독서했습니다 다들 공상온도 하세요 ◡̈', 261, 89, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '평상시엔 카페로, 때때로 공연장 등으로 활용되는 공간이며 공간대여도 가능합니다. 작은 서점으로도 운영되는데, 일부 책은 테이블로 가져가서 읽을 수도 있어요. 디저트와 음료도 맛있고요. 디저트는 카페에서 직접 만드는 수제 디저트에요. 분위기 편안하고 아늑해서 책 읽으며 머물기에 좋습니다.', 0, 8, 'GOOD', SYSTIMESTAMP);
