INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '작업하기 좋은 공간이에요! 책도 읽을 수 있고, 정말 유니크한 카페입니다. 디저트 크림브륄레 추천드려요!!! 좌석이 편해서 정말 좋은 것 같아요. 작업실 느낌 뿜뿜입니다.', 95, 19, 'GOOD', SYSTIMESTAMP);
