INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '2층 테이블 엄청 삐걱거립니다. 2층 와이파이 30분을 시도해도 안잡힙니다. (제가 이용할 때 그랬었는데 다른 분들도 이용시 참고하세요) 이러한 불편을 이유로 1층으로 자리를 옮기면 자리 옮기지 말라고 뭐라 합니다. 그래서 2층 와이파이 안잡혀서 (며칠전에 와이파이 잡혔던) 1층으로 좌석 옮긴다고 얘기하면, 1층이랑 2층이랑 와이파이 똑같을거라고 퉁명스럽게 핀잔줍니다. 허나 1층 옮기자마자 와이파이 바로 잡힙니다. 결국 들을 이유 없는 핀잔이었던 건데 뭐라 합디다. 해당 매장 와이파이 컨디션 및 고객 응대가 이러하오니 노트북으로 작업하실 분들은 참고하세요', 1, 2, 'BAD', SYSTIMESTAMP);
