INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '편하게 작업하고 싶을 때 종종 방문하는데, 올때마다 음악이 독특하고 좋은게 넘넘 많이 나와서 중간중간 노래 찾기 동원해서 줍줍하고있습니다!!', 89, 14, 'GOOD', SYSTIMESTAMP);
