INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '도란도란 이야기 나누고 맛있는것 먹고 책 구경하니 시간가는 줄 모르겠더라구요. 남자친구와 서로 책선물도 하며 좋은 시간 보냈어요 ^^ 브라우니, 비건코코넛까눌레 엄지척입니다~👍', 76, 12, 'GOOD', SYSTIMESTAMP);
