INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '몇몇의 리뷰를 보면 사장님께서 억울하셨는지 url첨부하여 답변을 하셨더라구요. 가보면 굉장한 장문의 반박글이 있던데요. 저라면 그것들을 쓸 시간에 응대 수준을 바꿔보겠습니다. 저도 국내의 과한 서비스 시스템을 지양하고 있지만 여기는 기본 이하에요. 갈때마다 기분이 나빠지는 마법의 카페같습니다. 너무나 분위기도 좋고 음료도 맛있고 다 좋은데요. 사람들이 말하는 단점들, 문제점들을 아예 모르시는 것 같아요. 물론 사람들의 말들이 다 맞는 말도 아닐거고 분명 왜곡되거나 과장된 부분도 있을겁니다. 그러나 제가 몇번 손님으로써 겪어본바로는요. 얼추 보여요.. 저는 앞으로 다시 가지 않겠지만 막연히 바란다면 막은 귀는 뚫고 감은 눈은 뜨셨음해요.', 1, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '1. 구운까망베르 12,000원 2. 브라우니 콩포트 7,000원 흥미로운 메뉴가 많아 고르기 힘들었어서 혹 저희같은 분들에게 도움이 됐음 좋겠다 싶어 메뉴별 사진과 이름 순서대로 올려요! 지하에 있는 매장이었는데 공간이 재밌고 지인과 얘기나누기 괜찮았어요. 음료 종류도 카페와 바 모두 아우르고 있어서 좋았고, (알콜을 마셨기에) 안주(?)도 달달한것과 짭짤한거 모두 있어 누구든 자기 취향껏 고를 수 있을 것 같아요!', 24, 4, 'GOOD', SYSTIMESTAMP);
