INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '나름 알려진 곳인 것 같아요. 책도 볼 수 있고 작업하기 좋아서 기분이 좋았어요. 음악도 좋고 느낌도 색다르고/ https://m.blog.naver.com/rememberdevant/222841953711', 9, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '공상온도의 미트소스 덮밥을 좋아하는데, 식사 메뉴만 주문하는 건 안 된다고 해서 할 수 없이 음료를 같이 주문했어요. 식사 메뉴가 저렴한 것도 아닌데 왜 1인 1음료 주문을 고집하시는 건지 저로서는 이해가 되지 않습니다. 가끔 생각나서 오는데 올 때마다 갸우뚱 하게 되고 기분이 좋지 않네요.', 89, 18, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '들어가기 전, 문 앞에 이용 안내가 적혀있기에 보고 들어가거나 주문 전 설명을 듣고 이용할 수 있어요. 코로나로 테이블 간 이동이 불가능한 점, 카운터엔 메뉴판이 없고 각 테이블에 배치된 메뉴판을 이용하여 주문 메뉴를 고른 후 주문할 것, 큰 소리 지양, 샘플이라는 스티커가 붙은 책만 볼 수 있음. 잔잔한 인디 음악이 나오고 벽면에 영상을 빔 프로젝터로 채워주십니다. 1인 1음료 주문하면, 주문 수에 맞춰 후르츠링 시리얼과 사탕 챙겨주셔요. 화장실은 공용입니다.', 83, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '쉐이크 시켰는데 얼음이 별로 안 들어갔는지 쉐이크 부분 반, 라떼 반인 것 같았어요ㅋㅋ 그래도 맛있었습니다. 커피는 산미 있는 원두. 조용히 얘기하거나 책 읽기 좋은 곳이에요. 목소리 큰 사람들은 말하기 힘들 것 같은 고요한 분위기; 대화하시려면 다른 곳 추천!', 44, 3, 'GOOD', SYSTIMESTAMP);
