INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '추가.인생 최악의 카페. 저는 다 먹고 나가면서 내가먹은 잔 정도는 가져다놓으려고 카운터쪽에 올려두었더니 주인장 하는 말 "거기 두시면 안돼요"내가 잘못 들었나 머뭇거렸더니 다시한번 거기두면 안된다해서 다먹은 잔 카운터에서  도로 앉았던 자리에 가져다놓음. 보통 이런경우에는 그냥 냅두시면 치워드린다고 하거나 고객이 다먹은 잔 카운터에 가져다 놓으면 별말이 없는것이 그간 내가 겪은 카페들인데. 자기 맘에 안드는 고객한테만 그런것인지 주인장 기분따라 그런것인지 아니면 모든손님에게 그런것인지도 궁금. 글읽는 여러분도 한번 치워보세요. 그러면 주인장이 그 잔 다시 앉았던 자리에 도로 가져다 놓으라 하는지 아니면 그냥 냅두는지. 불친절한 대응에 누구에게도 추천하고 싶지 않은 곳. https://url.kr/fb5', 43, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '예술복합공간이라는 목적에 맞게 일반카페보다 자유분방한 분위기의 카페였고 그래서 대화하기 좋으면서도 색달라서 좋았답니다. 그리고 디저트가 너무 맛있어서 감동받은 홍대 카페 공상온도였어요 😍', 324, 93, 'GOOD', SYSTIMESTAMP);
