INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '디저트며 음료 다 맛있는데요. 그 중에 저희가 먹은 크림브륄레와 기네스바나나파운드 정말 최고에요 ! 너무 맛있음요 !!  자유스러운 분위기에 편히 앉아 책도 보고 핸드폰으로 이것저것 할 수 있어서 좋았어요~ !! #자유스러운분위기카페 #홍대스러운카페', 22, 4, 'GOOD', SYSTIMESTAMP);
