INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '예술적인 인테리어가 돋보여요! 음료도 맛있고 조용히 책보면서 공부하기 좋아요^^ 살살녹는 푸딩이랑 아이스 아인슈페너 완전 맛있어요👍👍', 30, 0, 'GOOD', SYSTIMESTAMP);
