INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '분위기도 좋고 여기 커피 맛집이에요! 특히 좀 색다른 커피 먹고 싶으신 분 샤케라또 추천해요 ㅎㅎ 이탈리아식 커피라는데 산미도 살짝 있으면서 약간의 달달한? 맛이 나서 넘 맘에 드네요! 아인슈페너, 스프랑 크림브륄레도 맛있게 먹었습니다 ㅎ', 34, 10, 'GOOD', SYSTIMESTAMP);
