INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '크... 홍대 스멜로 가득한 공상온도 여길 찾은 나는 보물찾기에서 1등한 기분!  영감을 받고 힐링을하고 예술 감각을 키울 수 있는 최적의 공간♡ 음료랑 디저트는 또 깜짝놀라게 고퀄이예요! 핵추천해요!!!', 69, 16, 'GOOD', SYSTIMESTAMP);
