INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '이전하기 전에 예전에 방문했던 곳은 제 기억에 되게 어두웠던걸로 기억하는데 조명도 밝아졌고 책 종류도 더 많이 비치 되어있어서 좋네요!! 다만 종업원분께서 조금만 더 친절했으면 하는 바람이네요😭😭', 43, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '공간에서 매력을 느낄 수도 있구나 감탄하고 갑니다. 음료와 디저트도 맛있었어요! 특히 크림브륄레가 정말 맛있었어요... 책방처럼 책도 볼 수 있고 예술하는 사람들의 제작물을 접하고 구매할 수도 있었습니다! #홍대디저트카페 로 강추에요! 너무 복작거리지 않고 조용히 생각에 잠기다 오거나 책을 읽고 오면 시간 금방 가요,,, 추천추천', 22, 4, 'GOOD', SYSTIMESTAMP);
