INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '크림브륄래 잘한대서 먹으러 간건데 탄맛이 심해서 못먹었습니다. 일하시는 머리 긴 남자분께 여쭤보니 이것보다 더 태워서 나가는경우도 있다네요. 크림브륄래를 좋아해서 여기저기 다녀봤는데 이 정도는 처음이라 여쭤봤다 했더니 거기가 어딘데요? 그럼 제가 가서 배워야겠네요 하면서 비꼬는데 그냥 나오려다 불쾌해서 크림 브륄레만 환불받았습니다. 다신 안갑니다.', 62, 14, 'BAD', SYSTIMESTAMP);
