INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '갈 때마다 대감동ㅜ 메뉴도장깨기중이에요 브라우니 이쁘고 맛있고 크림브륄레 먹을 때마다 프랑스갓던거 생각나고 좋아요 직원분이 기네스바나나케이크 추천해주셔서 조만간 또 가려고요ㅋㅋㅋ 단골될 예정~^ㅇ^', 97, 24, 'GOOD', SYSTIMESTAMP);
