INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '공상온도'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '동네카페인데 완전 편하고 힙하고 화장실도 깨끗하고 음료도 맛있어요!! 용량도 크고 공부해도 눈치안보이고 ㅠㅠ 기본으로 주시는 사탕이랑 과자도 감동이고 독립서적도 있고 종종 카페에서 공연도 하고 여기 레몬에이드랑 짜파게티 젤 좋아합니다 어디 카페에서 짜파게티 끓여줍니까 ㅠㅠ 진짜 최고에요', 20, 9, 'GOOD', SYSTIMESTAMP);
