INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '실바니안 포토존을 찍지 못한게 아쉬워서 재방문 했어요! 바닐라 모카 달달하고 맛있어용! 사막여우 아기 셰프와 유령 냥이와 음료샷도 찍고 매장 둘러보고 포토존에서 실바니안 패밀리들과 사진도 찍고 왔네용~~👍', 30, 5, 'GOOD', SYSTIMESTAMP);
