INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '사막여우 사러 끝물에 왔지만, 사람들도 많고 아기자기한 실바니안 캐릭터들이 너무 귀여워요! 덕분에 힐링도 하고 가족들과 행복한 티타임 즐겼습니다 ☺️', 30, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '홍대 엔제리너스 매장이 엄청나게 넓은데 좌석도 굉장히 많아서 좋고 좌석종류도 되게 다양해서 고르는 재미도 있어요~~ 특히 쇼파좌석이 푹신하고 내집같이 편안한거같아서 이점이 너무 좋아요~ 그리고 인테리어도 세련되면서도 깔끔하고 현대적이고 모던해서 보기에도 호강이 되면서 좋아요~ 창도 통창이어서 바깥구경하기도 너무 좋네요~ 실바니안 패밀리 이벤트라 아기곰돌이로 카페를 꾸며놓은거 같은데 너무너무 귀여워요💗💗 커피도 맛있었어요~~', 43, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
