INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '엔제리너스 매장 수가 줄어서 찾기 힘든데.. 홍대에 일이 있어 왔다가 커피 한잔 할겸 엔제리너스 홍대L7점 방문했어요~ 홍대입구역 1번 출구 근처에 있어서 찾기도 쉽고 2층 매장이 넓어서 자리도 많아요. 타 브랜드 커피숍 보다 조용하니 대화하기 좋아요~😃', 109, 24, 'GOOD', SYSTIMESTAMP);
