INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '솔직한 후기 일단 덥기도 하고 팝업 구경하러 들어와서 시켜 먹었는데 음료가 흠.. 다른 프렌차이즈점 커피가 더 맛있고 쌀듯ㅎㅎ 일단 블루베리음료는 인위적인 블루베리 맛이 났고 아이스티는 그냥 아이스티임 그냥 팝업 구경하러 옴. 케이크는 생크림 좋아하면 맛있게 먹을듯 👍🏻', 42, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), 'Nice and clean. The cakes are tasty and the vibes is elegant, yet relax. Good for a romantic date, meeting friends, or just resting. The bathroom''s are super clean and have a good smell. The drinks are good, too. I''d come back here if I am in the area!', 50, 5, 'GOOD', SYSTIMESTAMP);
