INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '매장이 엄청 넓어가지고 너무 좋은데 전등도 너무 예쁘고 인테리어도 너무 예쁩니다~ 보기만해도 힐링이 됩니다~ 장시간 있기도 너무 좋아요~ 늦은 시간까지 영업해서 좋아요~~ 아이스티 너무 맛있어요~', 61, 11, 'GOOD', SYSTIMESTAMP);
