INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '백날 홍대 걸어다녀도 엔제리너스 있는 줄도 몰랐삼; ㅋㅋ.. 실바니안패밀리 보려고 후다닥 다녀왔어요~!♡ 알차게 꾸며놔서 기뻤어요', 60, 18, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '홍대 L7점은 처음 이용해봤는데 입구부터 인테리어가 설레게하고 기대하게 되는 그런 인테리어인거 같고 들어갔더니 매장부터 엄청 넓직한거에다 쾌적하고 힐링되는 인테리어인거같아서 너무 좋네요! 게다가 통창까지 되어있어 개방감이 좋고 보기도 시원해서 기분이 좋아져요~ 그리고 다른지점과 다르게 카페 내에 공간분리가 되어있어서 이점도 너무 좋아요! 아이스티로 시켜먹었더니 진하면서 너무 맛있었어요!', 41, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '실바니안 주말 후기 •8시02분 매장도착! 아무도 없어서 음료 시키고 영수증 뽑아놓음 •인테리어 아기자기하게 잘 꾸며져 있음 •9시쯤 되면 사람이 좀 모이는데 서로 눈치게임중 대기줄 서있는 사람 없었음 테이블 앉아서 기다리고 있음 •9시 30분부터 줄섰는데 1등으로 받고 나옴 토끼가 인기가 없는건지 아니면 잘 모르는건지 백화점이나 인기많은 팝업 웨이팅에 비해 여유롭네요', 53, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '캐나다에서 함께살적에 친했던 지인이 왔어요. 홍대에서 젊은기운 느끼려고 만나서 밥도 먹고 가볍게 치맥도 하고 집으로 돌아가기전에 아쉬워서 앤제리너스 들왔는데 이곳 앤제리너스 들어와보고 홀딱 반했어요.매장안도 크고 깔끔하고 인테리어에 신경도 많이 쓴거 같고 오늘의 기록을 남기고자 사진도 많이 찍었습니다. 재방문의사 백퍼인곳!', 15, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '금요일은 딸과의 데이트! 줄곧 좋아하는 홍대입구에서의 데이트 엔제리너스 케익이 맛있어서 자꾸만 주문하고 싶어져요. 통창 밖으로 도시의 풍경을 내다보는걸 너무 좋아라 합니다! 이곳은 매장이 진짜 넓은게 특히 맘에 들어요.', 50, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '무슨 운영이 이렇게 개판인지 실바니안 다시는 여기랑 콜라보 하지 마세요 키오스크 주문만 받고 응대 하는 알바 아무도 없고 바쁜건 알겠는데 그러면 알바 파트 타임이라도 구해서 늘리던가 사장이 돈욕심이 심한지 키오스크 주문 못하는 고객이라도 있으면 어쩌려고 ㅋㅋ 음료 두개 결제해서 하나만 부분 취소 부탁 하니까 그것도 전체 취소 하고 다시 줄서서 주문 받아야 한다질 않나 도대체 운영 이따위로 할거면 콜라보 하지 마세요 받을 깜냥 안돼보이니까', 126, 19, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '디카치노크러쉬는 부드러운 거품과 자잘한 얼음알갱이에 진한 커피맛의 조합이 독특하면서 맛있습니다. 우유고구마케익은 맛있지만 윗부분이 말라있어 아쉬웠습니다.', 5, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '이준혁씨 밀키바닐라엔젤 신메뉴 먹어보러 왔는데, 진짜 너무 맛있어요!!! 밀바엔 정말 모두에게 추천해주고 싶어요~~~ 당떨어졌을때 한입 먹으면 짱 달아서 바로 정신이 번쩍들고 피로가 회복되는 느낌!!! 집근처에 엔젤리너스가 없어서 여기까지 찾아온 보람이 있어요~~~ 자리도 넘 편하고 넓어서 주말에 잘 쉬다 갑니다 ㅎㅎ 담에 또 올게요!!', 127, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '엔제리너스에서 아이들과 시원한 음료도ㅈ마시고 실바니안도 보고 이쁜 사진도 찍는데 실바니안을 구매안할 수 없더라고요~!! 너무 좋아요~!', 85, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '실바니안이랑 콜라보 했다고 해서 처음 오픈한 날부터 지금까지 피규어 구매 하려고 계속 잘 가고 있는 중인데 , 직원 분들은 항상 불친절 하시네요 리뷰 써야지 써야지 하다가 이제야 쓰는데 첫 날 콜라보 했을 때도 피규어 재고 소진 됐는지 여쭤보니 쳐다보지도 않으면서 저 쪽에 물어봐야한다고 하시고, 피규어 2개 구매 하러 왔는데 음료는 제 스타일이 아니라 하나는 안 주셔도 된다고 주문하고 미리 말씀 드리니 순서대로 나가고 있어서 나오면 말씀 다시 달라고 하시더라고요 음료가 이미 나오면 말하는게 무슨 소용인가요 ? 결국 음료 2잔 다 나와버려서 한 잔은 괜찮다고 하니 그냥 반응도 없으시더라고요 실바니안이랑 콜라보해서 가고 있는 건데, 콜라보 끝나면 오지도 않을 거 같네요', 20, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '홍대입구역사거리 호텔 L7홍대 2층에 위치한 대형 카페. 엔제리너스는 카페라떼가 특히 맛나답니다. 오늘은 어떤 라떼아트를 만나게 될까 항상 기대되는 L7홍대.', 4, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '커피수혈이 시급한때 눈에 뙇!!! 생딸기우유크림 타워브레드...  역시 10살 6살 아이둘은 엄청 좋아해요... 5분만에 반통을 먹었네요....  대도로 앞에 있는데 매장이 넓고 곳곳에 테이블이 있어서 좋아요. 운좋게 매장 정면쪽에 앉아서 뷰도 좋고 조용하니 분위기도 좋고 음악도 좋고... 오랫만에 기분이 좋네요', 62, 14, 'GOOD', SYSTIMESTAMP);
