INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '간만에 홍대에서 친구 만나 차한잔 했습니다. 엔젤리너스 정말 오랜만인데 여기 꾀나 넓네요~~ 조용하니 긴시간 머물다가 나왔습니다. 커피 치즈케익 잘 마시고 먹고 나왔담니다~ㅎㅎ', 22, 7, 'GOOD', SYSTIMESTAMP);
