INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '해외거주하는 지인 가족이 한국 들어올 때면 만나는 장소, 엔지리너스. 공간이 예쁘게 꾸며져 있고 공간 여유가 있어서 편히 이야기 나누기 좋아요. 신메뉴인 허니브레드도 완전 혜자롭네요.', 2, 10, 'GOOD', SYSTIMESTAMP);
