INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '매장 인테리어도 깔끔하고 통창이라 창문 근처엔 덥긴 하지만 밖이 잘 보여서 좋았고요 커피도 산미가 없어서 좋고 샌드위치도 맛있어요~', 43, 3, 'GOOD', SYSTIMESTAMP);
