INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '2024년 마지막은 엔제리너스와 함께... 엔제리너스 스탬프 이벤트 아메리카노 무료쿠폰 사용. 스탬프 10장 단위로 모은 거 연말인 오늘까지 쿠폰발행 하셔야 해요.', 30, 8, NULL, SYSTIMESTAMP);
