INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '엔제리너스 정말 오랜만에 방문했는데, 타워 브레드라는 메뉴가 있어서 도전해봣어용 허니브레드 상위호환 느낌입니다 ,, 가성비 미쳤어요 매장도 엄청 넓구 콘센트 자리도 꽤 있어서 카공하기 좋앗어요 💖💖💖', 42, 5, 'GOOD', SYSTIMESTAMP);
