INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '엔제리너스 L7홍대의 2025 신메뉴 타워브레드 런칭했어요. 메가 사이즈 허니브레드인데요. 상상했던 것 이상의 압도적 볼륨에 깜놀. 혼자 먹다 진짜 목막혀 죽을 뻔함. ㅋㅋㅋ 런칭기념 SNS 리뷰 이벤트 진행한다고 하니 많은 참여를...', 44, 9, NULL, SYSTIMESTAMP);
