INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '반미 포장해서 영화관에서 먹었어요 속 그득그득 넣어줘서 넘 맛있었어요 디저트 종류도 많고 매장도 넓고 자리도 많아서 매장이용도 좋을듯', 5, 5, 'GOOD', SYSTIMESTAMP);
