INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '홍대에서 커피가 맛있는 카페 중 하나(내 기준). 매장도 넓고, 독립적인 공간도 있고, 큰 테이블 좌석도 있고 해서 작업하기 좋은 곳. 다만 아쉬운 점이 있다면 마시던 커피 테이크아웃하면 얼음 추가로 더 넣어주시지 않고 그대로 준다는 것. 그럼에도 불구하고 계속 방문할 예정이다.', 12, 1, NULL, SYSTIMESTAMP);
