INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '먹다가 찍었지만.. 엔젤리너스 가본 곳 중에 제일 좋어요! 쾌적하고 깔끔하고 커피도 맛있어요 ㅎㅎ 이벤트 덕분에 맛있는 디저트도 먹을 수 있었어요 👍🏻', 78, 16, 'GOOD', SYSTIMESTAMP);
