INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '서울에 몇 안 남은 프랜차이즈 엔제리너스! 홍대점은 매장도 넓고 인테리어도 잠실점 못지 않아서 혼자 오기도 좋습니다. 좌석 여유롭고요! 부디 폐점하지 말아주시길..!', 92, 21, 'GOOD', SYSTIMESTAMP);
