INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '제일 뷰가 좋은 엔젤리너스 홍대점 !.! 매장이 쾌적하고 좋아요 커피도 맛있어요 저는 개인적으로 시트러스 + 라떼 좋아합니다 산미에 카페라떼 강력추천합니당 ㅎㅎ - 죨맛 커피러버 죨밍이가 -', 33, 10, 'GOOD', SYSTIMESTAMP);
