INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '엔젤리너스 반미가 유명한건 알고 있었는데 아니! 생각보다 더 푸짐하고 아주 맛있었어요! 아이스 아메리카노에 불고기 반미 세트가 만원이었는데 가성비가 너무 좋아요 불고기가 엄청난 고퀄리티의 고기는 아니지만 부드럽게 맛있는 불고기였고! 계란후라이 토마토, 오이, 양상추, 양배추까지 아주 아쉽지 않게 들어있어 든든하고 맛있게 먹었어요!', 14, 1, 'GOOD', SYSTIMESTAMP);
