INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '홍대 엔제리너스 매번 올 때 마다 느끼지만 친절하셔요 ! 평소에 너티크림 커피를 좋아했는데 나인티 세컨즈? 마셔봤어요. 커피 설명 여쭤봤는데 친절히 알려주셨고 시나몬 파우더도 뿌려드리냐고 먼저 여쭤봐주셔서  더 맛있게 마셨습니다 ! 감사합니다 ♥ 아 선물하려고 마들렌 세트도 포장 구매했는데 이건 무인 키오스크에서는 구매할 수 없어 직접 앞에서 포스 주문 했습니다 ! 날씨가 좋아서 통창 유리 보면서 여유롭게 시간 보냈어요 ~~~~ ㅠㅠ !! 🫶🏻', 72, 14, 'GOOD', SYSTIMESTAMP);
