INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '가게가 일단 너무 이쁘고요 공간도 넓고 좌석도 많아요! 혼자 작엊하러 오신 분들을 위한 죄석도 많아서 앞으로 자주 방문할 거 같아요 음료랑 디저트는 엔젤리너스니까 믿고 먹습니다', 58, 12, 'GOOD', SYSTIMESTAMP);
