INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '약속이 딜레이되서 잠깐 들렀는데 분위기 넘 좋고 힐링되네요 ^^ 엔젤리너스는 첨 와뵈서 제 입에 맞는 커피는 찾아봐야할듯 ㅠ 베이글은 치즈를 따로 구매해야한다네요;; 귀차나서 그냥 먹었는데 바삭?하니 빵만 먹어도 괜찮긴 했음! 작업 공간으로도 좋은듯', 39, 5, 'GOOD', SYSTIMESTAMP);
