INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '보노보노민트초코라떼랑 포로리레드빈라떼를 먹어봤는데요. 보노보노 민트초코라떼는 보노보노의 대표 색상인 하늘색을 연상하게 하는 민트 베이스에 초코 시럽을 더해 달콤함을 더한 라떼이고 포로피 레드빈라떼는 포로리의 대표 색상인 분홍색을 연상하게하는 할매니얼을 겨냥한 달콤고소한 팥의 풍미를 살린 라떼였어요.', 64, 14, 'GOOD', SYSTIMESTAMP);
