INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '샐러드랑 반미 먹으러 자주 가는데 ,갈 때마다 직원분들이 친절해서 좋아요 매장이 넓어서 답답한 느낌도 없고 , 커피도 디저트나 샌드위치류 모두 맘에 들어요 다만, 매장이 넓은 편이라 직원분들이 자주 청소해도 조금 지저분해져서 아쉬워요.', 3, 9, NULL, SYSTIMESTAMP);
