INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '와 매장이 넓고 편한 쇼파가 많아서 너무 좋아요! 요즘 카페에 편한 좌석이 그리 많지 않아 찾다가 보물을 발견했네요 ㅜ 사람들이 적당히 있어서 더 좋았어요!!!! 또 방문하겠습니당 ⭐️', 53, 16, 'GOOD', SYSTIMESTAMP);
