INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '반미 샌드위치를 판다기에 가봤는데 매장이 너무 예쁘던데요? 데이트하기에도 카공하기에도 너무 좋아보이던 곳! 메뉴도 다 맛있어요', 105, 24, 'GOOD', SYSTIMESTAMP);
