INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '메뉴구성 넘 좋고 공간이 넓고 조용해서 자주 찾아요. 근데 노래 선곡만 좀 바꿔주시면 안 될까요ㅜㅠ 너무 옛날 느낌의 가요가… 촌스러워서 참을 수 없어요…… 와 진짜 어떻게 이렇게 촌스러운 노래만 골라서 트는 건지…. 도대체 누가 선곡하는 건지…… 기분이 안 좋아질 정도로…. 이상한 노래들….. 이렇게 이상한 노래를 한번에 틀어주는 카페는 여기가 첨이에요… 홍대에 케이팝 좋아서 온 외국인 여행객들이 와서 듣고 놀라겠음……', 43, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '뜨거운 냉커피 주세요! 저도 한 번 해 보았습니다. 너티치노 크러쉬 아이스아메리카노와 슬러쉬의 중간 느낌 진하고 고소한 아아를 오랫동안 시원하게 먹을 수 있어 좋아요.', 58, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '빙수가 맛있어서 여름마다 방문하는 곳입니다. 일단 공간이 어마어마하게 넓습니다. 사진이 없어서 아쉽지만, 크게 네 컨셉으로 공간이 나뉘어져 있어서 목적에 맞게 공간을 사용할 수 있습니다. 음료도 베이커리류도 메뉴는 다양하지만, 커피맛은 크게 기대하지 마세요.', 4, 3, NULL, SYSTIMESTAMP);
