INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '홍대입구사거리 L7홍대 호텔 2층에 있는 다이닝 특화 엔제리너스 직영점. 엘리베이터 이용가능, 주차장 사용가능. 의외로 배리어프리 카페랍니다.', 4, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PARKING');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '엔제리너스 반미 먹으러 왔습니당! 깊티있어서 온거라 큰 기대 안 했는데 바게트 빵 바삭하니 맛있고 채소는 완전 신선하고 고기도 달달짭짤하니 너무 맛있더리구여! 그리고 고수는 선택할 수 있어서 좋았습니다! 홍대에서 한적하고 큰 카페 잘 없는데 사람이 많지 않고 조용한 분위기라서 공부하기도 좋을 것 같습니당! 집 근처에 엔제리너스 있으면 써브웨이 대신 맨날 가고 싶은 맛이었어요!! 왕왕추천입니당😽', 28, 2, 'GOOD', SYSTIMESTAMP);
