INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '케익 먹고 싶어서 들렀다가 메뉴에서 커피 시키니 반미가 할인 된다고 뜨길래 고민고민하다가 반미 시켜서 먹었어요. ㅎ 새로 나온 반미 메뉴도 있어서 맛있게 먹었습니다. 점심시간이여서 그런지 점심 먹으러 오신 분들도 많고, 과제 하러 오신 분들도 많았습니다. 크리스마스 느낌 나는 엔젤리너스 좋아용~ 반미샌드위치 먹으러 엔젤리너스로 오게 되네요 ㅎㅎ', 27, 1, 'GOOD', SYSTIMESTAMP);
