INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '반미맛집 엔제리너스!! 새우 크랩 반미 먹었는데 역시 너무 실하고 든든하고… 소스나 이런거 취향 갈리겠지만 음료랑 같이 시키면 할인도 되니까 너무 좋아용 킹성비 굿굿 매장도 쾌적하고 넓어서 좋아요 직원분들도 친절하십니다☺️', 90, 13, 'GOOD', SYSTIMESTAMP);
