INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '디저트 종류도 많고, 치즈케이크 맛있습니다👍 와인에이드 특이해서 주문했는데, 와인 잘 못드시는 분들도 마실 수 있을고 같아요. 매장 넓고 자리 많고, 인테리어가 이뻐서 연인끼리 오기도 좋을거 같아요~', 98, 22, 'GOOD', SYSTIMESTAMP);
