INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '디저트 종류도 다양하고 커피 종류도 다양해서 좋았어요 . 그런데 쇼파 좌석은 청소가 너무 안 되어 있었어요. 부스러기가 좌석에 그대로 남아있어 앉을 수가 없더라구요', 11, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '홍대 2호선 바로 앞이라 오기도 편하고 좌석도 넓고 콘센트도 많아서 카공하기 좋아요 디저트랑 식사류도 다양해서 출출할 때 한번에 해결 가능해서 굿', 89, 13, 'GOOD', SYSTIMESTAMP);
