INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '커피랑 반미도 맛있는데 매장 분위기랑 스케일에 압도 되는 곳입니다 👍👍 집중하기도 좋고 다른 곳과 다르게 확 트여있어서 자주 가게 되는 거 같습니다 :)', 90, 11, 'GOOD', SYSTIMESTAMP);
