INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '새로 나온 베이글이랑 크림치즈 먹었는데 가성비 좋고 맛있네요. 특히 크림치즈가 핸드크래프트라 퀄리티가 타카페와는 비교불가로 좋아요.양도 많아서 진짜 잔뜩 쳐발쳐발 가능. 게다가베이글 가격이 무려 2500원으로 너무 착함. 안먹으면 대손해.', 23, 5, 'GOOD', SYSTIMESTAMP);
