INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '호텔에 있는 엔제리너스라서 그런지 롯데잇츠앱으로 주문하려고 시도하면 전부 불가라고 뜨네요. 그런데 키오스크로 할인쿠폰 사용은 가능하네요. 호텔이라서 잇츠앱이 안되는 것인지? 알수는 없지만 커피 할인주문으로 만족해야 겠네요. 다른 엔제리너스와 다른컨셉이고 인테리어도 다양하고 다릅니다. 테이블말고 쇼파가 많은 홀매장은 회색 패브릭 쇼파인데 너무 더럽습니다. 쇼파의 특성상 때가 많이 타는 이유도 있겠지만 외국인들이 많이 이용하는 곳이니 때가타지않는 패브릭으로 천갈이를 하던지 하셔야 겠어요. 분위기는 좋아요', 3, 2, 'BAD', SYSTIMESTAMP);
