INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '엔제리너스 홍대점은 홍대부근 들릴때마다 가장 재방문하고 싶은 카페입니다!! :) 음식도 맛있고 여러모로 먹을게 정말 많아요! 직원분들도 정말 친절하시고 넘 좋습니다❣️', 50, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '회사근처에 L7엔젤리너스가 있어서 행복합니다 🥹♥️ 진짜진짜 최고의 카페입니다. 특히 뇨끼 ㅜㅜㅜ이것땜에 계속오게되고 반미덕에 또오고 브런치덕에 또 옵니다 ㅜㅜ 국내 엔젤리너스중에 최고 원탑 🌷', 48, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '빌리엔젤인줄 알고 잘못 들어왔는데 엄청 예쁜 엔젤리너스였어요 ㅋㅋ 좌석 엄청 넓고 편해요!  카공족들이 자리 차지 많이하는 듯 ㅠㅠ 좌석 날 때까지 기다려야 했어요', 16, 9, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '1004데이를 맞이하여 축하하러 특별히 찾았네요. 슈크림이 없어 페이스트리로1004데이 자축. 딱 저녁먹을 시간이어서 파스타 달리려고 했는데 키오스크에 다이닝 메뉴 다 막아놔서 강제 반미행. 훈제베이컨은 누린내 나고 여전히 별로네요. ㅠ.ㅠ 다이닝 라스트오더 시간을 알려?주세요.', 6, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '엔제리너스 홍대7점은 인테리어가 므찝니다 외곽의 베이커리 카페 정도의 규모네요 입구가 넘 이뻐서 사진도 찰칵 포토존 ㅎ 주문한 싵타래 팥빙수와 라떼 라떼는 스타벅스라떼 샷추가한 정도의 맛이구 올 여름 처음 먹는 팥빙수는 큼직한 찰떡과 우유얼음이 팥과 어우러져 다 아는 맛 ㅋㅋ 맛있으면  0칼로리 였음돠 단점은 의자가 등받이가 없어서 편히 앉아서 수다떨기가 불편합니다', 37, 9, NULL, SYSTIMESTAMP);
