INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '몇 달만에 재방문했는데 여전히 넓고 쾌적하긴 하지만 몇몇 시설은 더 아쉬워졌어요. 전에는 바에 티슈가 있었는데 치워서 없네요. 화장실 변기도 누가 험하게 썼는지 시트가 움직여서 다이나믹했습니다..올때마다 쓴소리 해서 유감이지만 개선되길 바라는 뜻에서 남겨요.', 5, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '샐러드도 팔더라고요! 큰길가에는 샐러드파는 곳 없어서 편의점 다니고했었는데참고하시면 좋을듯합니다👍🏻 스벅처럼 과일메뉴도 있어요', 3, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '실타래 팥빙수 18000원 ㄷㄷ😱 증말 비싼데 맛있긴 엄청 맛있어요 엔젤리너스 로고랑 카페디자인 바뀐거 넘 맘에 들어요 더운날 잘 쉬다 갑니당', 16, 4, 'GOOD', SYSTIMESTAMP);
