INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '엔제리너스 직영점이라 커피 퀄리티가 확실히 좋습니다. 환경의날 이벤트로 잇츠앱 픽업 주문 시 아메리카노 50%할인 중. 축복스런 행사네요.', 23, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '홍대  전철역에서 가깝고 모 호텔 1층에 자리잡은 이 엔절리너스 카페는 타지역 까페와는 다른 다이닝카페로써 호텔 투숙객도 조식을 먹기위해 이용 되는 곳으로 매장도 넓고 공간도 프론트를 중심으로 섹선이 네군데로 나뉘어져 있어 혼자 이용하는 고객과 다수모임자의 공간, 연인들 이용하기 좋은 공간, 커뮤니티를 위한 대여공간 등으로 활용도 높게 배려된 공간 같다. 내가 방문한 날도 저녁시간에 영어스터디를 위해 한쪽 공간이 예약 되어있었다. 촬영을 다 할 수 없어 커피만 사진을 남겨 아쉽지만 내부가 참 아기자기하고 이뿐 카페다. 케익이나 커피는 다 아는 맛.', 8, 5, 'GOOD', SYSTIMESTAMP);
