INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '신메뉴 하와이안 갈릭 쉬림프 반미 먹으러 방문했다가 라떼에 감동 먹음. 홍대점 카페라떼 퀄리티가 엄청 좋네요. 벨베티폼 라떼 미쳤다.', 54, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '이집 파스타 겁나 맛있어요 😭 파스타 전문점 못지않구요 소고농도도 진하고 면도 쫄깃하니 식감이 좋았어요 위에 원두가루가 파스타의 풍미를 한층 높여주는 역할을 했어요 거부감 없이 드셔도 될 듯 의외로 잘어울립니다 리프애플 갓구워져 나와서인지 엄청 맛있었어용 😆 그런데 갓구워진 거 아니라 하더라도 맛있는 맛!! 나날이 성장 발전해가는 엔제리너스 짱!! 👍', 15, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '키오스크 ux가 너무 복잡함. 한귝 사람도 주문하기 복잡한데 외국인들도 한참 서 있음. Ux디자인을 더 간소화할 필요가 있음. 너무 세세하게 나눠서 분류하니 더 복잡하게 느껴지고 단계도 많음', 17, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '매장 쾌적하고 인테리어가 멋져요! 롯데GRS 무슨 촬영한다고 하여 자리이동 요청받아서 한 번 옮겼는데 그 외엔 전체적으로 좋았습니다.', 8, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '벅적벅적한 홍대에서 유일?하게 널널하게 편히 숨돌릴만한 공간. 일단 위치도 좋고 넓고 쾌적함. 테이블사이도 넓고 공간도 각양각색으로 꾸며놓음. 여기 좋음!', 4, 8, 'GOOD', SYSTIMESTAMP);
