INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '홍대점 다이닝 푸드 추천드려용 파스타는 특히 파스타 전문매장 못지않게 맛있었고 위에 원두가루 얹어졌다고는 하나 파스타 맛에 지장 없습니다! 피자도 바질페스토라서 바질소스 베이스입니다 토마토베이스 좋아하시면 페퍼로니피자 드시면 좋아요 ㅋ 맛있는데 피자 치즈가 늘어나지 않아서..음... 근데 먼저나오는 메뉴는 센스껏 먼저 챙겨주면 좋을텐데 메뉴가 동시에 나오는 것도 아니고 나중에 완성되는 거 기다렸다가 진동벨 울려주시니 그동안에 피자가 식은 듯 했어요 파스타는 뜨끈뜨끈했거든요 직원분의 센스가 부족해서 그런 점은 아쉬웠어요 피클은 요청시에만 주십니다 수제느낌나서 좋았어요 😆', 45, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '진짜 너어어어무 맛있게 먹었어요 특히 스파이시치킨샌드위치? 포카치아빵이 정말 맛있었어요ㅠ 구워주신 것 같은데, 빵은 바삭하고 안에 내용물은 신선했어요! 갓만든 그런 느낌 ㅜ 불고기반미는 소스가 많지는 않았는데 그래서 오히려 좋았던 것이 재료 본연의 맛을 느낄 수 있어서 좋았어요. 불고기가 간이 안되어 있는 것이 아니었기에.', 72, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '머쉬룸파스타 맛있길래 이틀만에 또 먹어봄 🤤 진심 파스타 만드시는 셰프분 따로 있는 듯한 느낌 그정도로 파스타가게와 비교해도 손색이 없을 정도입니다 다만 파스타 가게가 아닌 카페라서 그런가 피클은 요청 시에만 주시네요 ㅋ 피클 좋아하시는 분들 꼭 요청하세요!! 쉬림프 반미에 들어있는 쉬림프 살이 탱글탱글합니다 먹다보니 부서져서 막판에 썰어 먹었어요 물티슈도 요청시 주시는 줄 알았는데 이번엔 센스있게 잘챙겨주셨네요~ 근데 이런 부분은 직원바이직원인 듯 ㅋ 오픈한 지 10분 지나서 오니까 한적하니 자리도 많고 좋았어요 편하게 먹고갑니다~~', 74, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '홍대 공연을 보기 위해 왔다가 너무 덥고 앉아서 쉴려고 카페를 찾던 중 예전에 1박했었고 가본 적이 있는 L7호텔 건물에 있는 엔제리너스를 찾았다 여전히 사람이 많았고 자리도 거의 없었다 처음 먹어 보는 음료인데 맛있었고 더워서 벌컥벌컥 마셨다. 저녁단체 예약석에 앉았다가 의자도 불편하고쇼핑하기 위해서 다 마신 후 얼른 나왔다.', 33, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '미묘하게 비가 내리는 날이라 그런지 손님 별로 없고 편안했어요. 덕분에 프론트야드 일찍 마감하는 모습을 오랜만에 볼수 있었네요.', 0, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '파스타 전문점 못지 않네요!! 👍 원두가루 토핑이지만 원두 맛 안납니다 ㅋ 쉬림프 반미는 반미 시리즈 중에 제일 비싸지만 그만한 값을 하는 게 새우가 겁나 탱탱하고 신선하다는 게 느껴집니다!! 식자재 관리 잘하는 가게인 듯', 9, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '비오는 날 먹는 파스타 맛있네요 😆 면도 쫄깃쫄깃하고 반미도 맛있고 엔제리너스 점점 성장하는 느낌!! 😆 롯데잇츠 멤버쉽 혜택도 쏠쏠해용', 92, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '잇츠오더로 엔제리너스 4월 픽업세트 이용했네요. 행사 덕분에 햄치즈 오븐 토스트 오랜만에 먹었는데, 역시 매장에서 먹는게 더 맛있음.', 4, 10, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '홍대 엔제리너스 인테리어 너무예쁘고ㅠㅠ 집이랑 가깝기만 하다면 진짜 매일 가고싶은 곳입니다. 에그반미 처음 먹어봤는데 왜 이제야 먹어본거죠ㅠㅠ 속도 알차고 푸짐하고 맛있는 가성비갑 엔제리너스 반미 최고!!👍 담엔 불고기도 먹어볼거양!', 58, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '올때마다 너무 기분좋게 커피도 마시고 대화도 할 수 있는 곳!! 낮이던 밤이던 통 유리창 덕에 너무 분위기 있어요!! 비록 등받이 없이 낮은 쇼파 좌석도 많아 불편한 점도 있지만 그만큼 다른 편에는 기본 테이블도 있어서 잘 이용할 수 있습니다 :) 음료는  엔젤이라 그럭저럭 ㅜㅜ 대화와 분위기를 보러 가는 맛인 것 같아요 ㅎㅎㅎ', 12, 5, NULL, SYSTIMESTAMP);
