INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '엔제리너스 멤버십 적립을 열심히 하면 엔제리너스 X 아소부 콜라보 르바통 텀블러를 누구나 받을 수있어요. 플래티넘 등급 무조건 찍으시길...', 11, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '파스타 겁나 맛있긴한데 매장이 넘 그림같다보니 사진찍는 사람 많음 사진 찍는 건 좋은데 양해구하고 찍었음 좋겠네요 비켜줄 여유도 없이 본인들 사진 찍고있음 눈치라도 주면 비켜줬을텐데 하필이면 외국인이라 말도 못하고 답답했음 ㅠㅠ', 1, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '쉬림프 알리오올리오 별 기대 안하고 먹었는데 제 입맛에 맞았어요 😆 그치만 호불호 갈릴 수 있는 메뉴같아요 ㅋ 페퍼론치노 들어있고 붉어보여서 매워보이지만 전혀 맵지 않고 느끼한 거 잡아주는 역할 면삶기정도 최적이고 셰프 따로 고용하시나봐요? ㅎㄷㄷ', 117, 25, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '롯데잇츠 스탬프카드 도장 10개 채워서 사용 차 방문했네요. 신메뉴 황치즈 버터바의 포크사 안들어가는 딴딴함과 엄청날듯한 칼로리에 감탄했네요.', 17, 5, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '잇츠오더 메뉴준비완료 픽업대기 알림 와서 픽업대 가보면 하나도 준비가 안되어 있음. 뭔가 많이 잘못된듯한 느낌. 캐셔나 키오스크로 주문하는 것보단 빨리 제공되길 다들 기대할텐데요.', 121, 21, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '엔젤리너스 L7 홍대점 커피는 대형커피체인점 중 최고 😂🤣😍 토스트도 맛있었고, 밀크티도 향이 정말 진해서 만족! 프렌치토스트는... 제 취향은 아니네요.', 104, 19, 'GOOD', SYSTIMESTAMP);
