INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '엔젤리너스 커피 좋아해요 산미있는거 너티한거 고를 수 있어서 더 좋아요 케이크 등 디저트와 함께 하면 더 완벽 홍대입구 근처에서 당도 보충하고 못다한 얘기도 하고 쉬어가고 싶을 때 들르기 좋아요', 2, 3, 'GOOD', SYSTIMESTAMP);
