INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '엔제리너스 L7홍대 1주년 축하 방문. 인스타그램 1주년 축하 댓글을 직원에게 제시하면 아메리카노를 무료로 받으실 수 있답니다. 시트론 아메리카노를 먼저 권해주는 센스 넘 바람직스럽네요. 초심을 잃지 않는 엔홍이 되었음 합니다.', 52, 15, 'GOOD', SYSTIMESTAMP);
