INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '디저트랑 커피가 맛있고 매장이 넓어서 좋아요 다만 좌석 시트에 빵 부스러기가 너무 많고, 구석구석 먼지가 많이 쌓여 있는게 보여요…', 8, 5, NULL, SYSTIMESTAMP);
