INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '불친절한 알바생땜에 다음엔 안 가려구요! 휴일이고 더운 낮에 새로 들어온 손님들 자리 찾다가 없어서 나가는데 매장 돌다보니 한 사람이 4인까지도 앉을 수 있는 테이블을 쓰고 있어서 혹시 직원이 가서 테이블을 떼어쓰도록 물어봐줄 수 있는지 문의했더니 들어온지 얼마 안 된 듯한 알바생이 뒤에 다른 알바생에게 제 질문을 어떻게 처리해야할 지 물었는데 ”자리를 만들어주라고? 하..“라고 되묻고 저에게 답변하면서 ”손님에게 강요할 순 없으니 물어봐드리긴 할게요“ 라거 말하며 인상을 찌푸리더며 말하더라구요.. 말이 아 다르고 어 다르다고 저는 막무가내로 해달라고 하지 않고 대신 물어봐줄 수 있냐고 물었는데 강요할 수 없다는 답을 들으니 좀 억울하고 황당했어요😂😂', 61, 17, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '스파클링 음료시켰는데 뚜껑따자마자 콜라터지는것처럼 5초가량 음료분사되서 옷이랑 노트북 주변 가방까지 젖었어요. 홍대본사인데 이정도면 누가 흔들어놓은 것 아닌이상 이러지는 않을텐데 재고관리를 안하시나요? 그것도 카운터 바로옆에 있었는데 아무런조취도 사과도 없고 닦아달라고하니까 물티슈있다고 하더니 마지못해 행주들고 오시는데... 처음으로 리뷰씁니다..5.31 저녁 cctv돌려서 확인하시면 다나올거에요. 아는데 컴플레인걸까봐 가만히 계신건지..저는 혼자닦고 없는것처럼 조용히 젖은 노트북에 젖은 음료먹는데 서럽더라고요...가서 음료라도 교환할걸 그랬네요..정말 너무하시네요..다안닦은 사진이랑 영상 올리면 어떻게 될까요? 실망이네요', 39, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '네고왕 트래픽 때문에 롯데잇츠앱을 제대로 쓸 수가 없는 상황이 이어지고 있네요. 잇츠오더는 당분간 쓸 수 없다고 보시는게 맞을듯... 쿠폰 이용하실 분들은 쿠폰을 미리 캡쳐 하시고 매장에서 키오스크 주문하시는게 정신 건강에 이롭습니다.', 84, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '다른 앤제리너스 매장보다 커피가 맛있어요. 인테리어도 색다른 분위기라 멋져요 요즘 딸기가 맛있는가봐요. 딸기주스  정말 맛있어요', 74, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '바질의 감칠맛과 크림이 잘 어우러지는 맛이었습니다 파스타 면도 쫄깃하고 버섯의 쫄깃한 식감도 한몫했고 토마토의 상콤함이 뒷맛을 깔끔하게 해줘요 😊', 36, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '롯데잇츠앱 엔제리너스 멤버십 적립 받으시면 멤버십 등급이 쭉쭉 올라가서 쿠폰이 마구 들어와요. 1번만 적립해도 웰컴 아메리카노 무료쿠폰 주고, 다음 단계인 에그마요반미 무료쿠폰 또한 정말 받기 쉬워요. 계산하실 때 잊지 말고 적립 받으세요.', 8, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '저녁 8시 넘어서 갔더니 다이닝 메뉴가 품절되서 아쉬웠어요 흑흑 😭 훈제오리 샐러드 소스는 고소한 참깨소스 느낌이었습니다 호불호 안갈릴 소스 바질마요 샌드위치는 맛있지만 다소 퍽퍽합니다', 43, 1, NULL, SYSTIMESTAMP);
