INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '롯데잇츠 앱 리뉴얼 기념으로 이벤트 하고 있어요. 덕분에 스탬프카드도 부활했고요. 파스타가 티켓타임 빠른 편이고 가성비도 좋아요', 15, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '불고기 에그마요 반미 너무 맛있어요~ 빵이 크고 잘 안잘려서 불편하긴 해도 맛있으면 장땡이죠ㅎㅎ 커피도 고소한맛 산미있는맛 고를 수 있어서 좋았습니다', 37, 8, NULL, SYSTIMESTAMP);
