INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '엔제리너스 L7홍대점 오늘부터 1주년 행사합니다. 인스타그램 이벤트 참여시 아메리카노 무료, 딜리버리 이용시 배달팁 무료에요. 하루 먼저 방문해서 1주년 이벤트 참여 못해서 아쉽네요. ㅋㅋㅋ', 26, 3, NULL, SYSTIMESTAMP);
