INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '공간이 정말 넓어요! 좌석도 많고 큰 테이블도 많아서 카공하기에도 좋아요 간단하게 먹을 수 있는 음식까지 종류가 엄청 많더라구용 전에 불고기반미 맛있게 먹어서 이번에 에그마요 반미도 먹어봤는데 저는 너무 느끼했어요ㅠㅠ', 26, 7, NULL, SYSTIMESTAMP);
