INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '서머너즈워 크로니클 콜라보 메뉴 먹으러 방문. 행사 메뉴는 햄치즈 토스트, 에그마요 토스트 2종이고요. 아메리카노랑 묶어서 8천원이니 토스트 샌드위치가 3천원인 셈네요. 뭔 겜인지도 모르면서 로비 공간에 자리한 서머너즈워 크로니클 캐릭터와 함께 기념사진 찍음.', 31, 0, NULL, SYSTIMESTAMP);
