INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '롯데호텔2층에 있는 엔젤리너스. 파스타주문시 1리터 아이스아메리카노가 3천원. 특수한 매장이라 할인카드혜택은 없다. 뷰좋고 메뉴많고 분위기 쾌적하고  자리넓고 넘넘좋다.오전7시부터라니 더더욱이 편리하다. 브런치먹으러 자주 와야겠다.', 49, 10, 'GOOD', SYSTIMESTAMP);
