INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '홍대 대로변에 있는 카페중에는 조용한 편이에요 좌석 도 따닥따닥 붙어있는 편도 아니구요. 충전할 수 있는 좌석도 있고 큰 테이블도 있지만 광장히 테이블이 작은 좌석도 있으니 참고!', 2, 4, NULL, SYSTIMESTAMP);
