INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '반미 ㅈㅁ 비엔나처럼 크림빵빵한 커피 있어서 좋아요 요리는 안 먹어봤는데 밥도 같이 처리할 수 있어서 좋은 것 같아요~ 인테리어도 너무 멋지고사진찍을맛 나지만 카운터 오른쪽은 전선 방해가 있는지 와이파이가 안되요ㅠㅜ', 27, 3, NULL, SYSTIMESTAMP);
