INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '엔제리너스 크로니클세트 먹으러 방문. 햄치즈 토스트랑 에그마요 반미 중 선택할 수 있어요. 21시 넘어서 방문했는데 손님이 많아서 놀랐네요. 인기가 더 많아지면 곤란한데 하면서 걱정을...', 42, 5, NULL, SYSTIMESTAMP);
