INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '토스트세트 먹으러 방문. 기존 햄치즈 토스트에 딜리버리 전용이었던 카야잼과 블루베리 2종이 추가되었어요. 8천원이란 세트 가격 설정은 살짝 아쉽.', 38, 3, NULL, SYSTIMESTAMP);
