INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '새로나온 가나 마운틴?도 맛있고 반미샌드위치 어딜가나 맛난 것 같아요 빵ㅣ 진짜 겉바속촉이라 빵만 사가고 싶을지경이예요! 홍대점 매장 너무 예쁘고 좌석에 코드 다 있고 화장실도 깨끗하고 주말에도 청소하고 계셔서 놀랐ㅓ요 브런치 메뉴도 있고 진짜 짱인듯..앞으로 종종 애용할 것 같아요~', 44, 4, 'GOOD', SYSTIMESTAMP);
