INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '고급스러운 인테리어와 차분한 분위기의 다이닝 카페로 커피를 즐기고, 대화를 나누기에 매우 적합한 장소. 샌드위치류가 맛있는데 재료가 신선하고 빵이 참 맛있다. 커피는 예전 엔제리너스가 그렇게 맛있는 편이 아니었는데 오랜만에 가봤더니 그동안 많이 노력해왔던 것이 느껴졌다. 물론 아직은 부족하지만 좋은 방향으로 발전하고 있는 것 같아서 반갑다. 예전에는 다른 사람에게 추천할 정도의 커피맛은 아니었지만 지금은 평범보다는 약간 좋은 정도의 커피라고 말할 수 있겠다', 38, 6, NULL, SYSTIMESTAMP);
