INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '네고왕 리턴즈 마지막날이라 그런지 손님이 정말 많네요. 어디 앉아야 하나 자리 찾아보기 처음. 생각보다 샌드위치는 빨리 나오네요. 델리 주문 쳐내기 스피드 굿.', 48, 3, NULL, SYSTIMESTAMP);
