INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '공간이 넓고 좌석도 많고 쾌적하고 제가 갔을때는 조용해서 공부하기 좋았어요 아침 7시에 오픈하고 간단히 식사를 해결할수있어서 좋아요', 18, 4, 'GOOD', SYSTIMESTAMP);
