INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '엔젤리너스 분위기 너무 조아요! 이쁘게 잘 꾸며놨어요 컵도 갬성적이고 이쁘네용! 에그마요샌드위치도 넘 맛있고 양도 많아요. 넘 많아서 다는 못 먹었네요ㅠ 커피도 맛있어요! 혼밥하기 너무 조아서 재방문의사 있습니다. 다만 매장이 좀 추워요ㅠ', 12, 0, NULL, SYSTIMESTAMP);
