INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '그리너리하고 화이트톤에 조명으로 가득해서 예쁘고 통유리라 역시 시야도 좋습니다! 허리가 불편한 좌석이지만 잠깐 티타임으로는 좋을 것 같습니다!', 19, 10, 'GOOD', SYSTIMESTAMP);
