INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '진짜 맛있었어요 기대 안했는데 바질 향도 좋고 버섯 향도 살아있고 풍미가   와진짜 최고의엔젤리너스 매뉴다 라고 볼 수 있어요 진짜 최고 가심비도최고 진짜 존맛탱 진짜 맛있었어요 짱', 20, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '쪄죽뜨 아메리카노 쿠폰 사용하려고 방문했네요. 시트론 아메리카노는 역시 뜨거워야 제맛인득... 엔홍은 여전히 시원하고 쾌적. 직원분들도 친절하고...', 6, 9, 'GOOD', SYSTIMESTAMP);
