INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '자리도 넓고 콘센트 많아요 스벅은 콘센트 자리 없애는 추세인데 반대로 엔젤은 콘센트 좌석 넓혀주고 자리도 훨씬 편해요 인테리어도 깔끔하구 음식도 훨씬 퀄리티있어요 ㅋㅋ', 34, 5, 'GOOD', SYSTIMESTAMP);
