INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '호텔 건물 안에 있는 엔제리너스라 그런가 인테리어도 멋지고 깔끔하네요. 다른 매장에는 없는 메뉴도 있는거 같아요(엔제리너스는 많이 안가봐서 아닐 수도 있습니다) 공간 넓어서 좋아요. 커피는 무난했습니다~', 117, 22, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '딸기스노우/ 퍼플블루오션 밖에서 봤을때 너무 예뻐보여서 충돌적으로 들어온 곳 1층은 사진찍는 공간같았고 2층에 있는곳인데 인테리어가 너무 예뻤어요 취향적! 날씨가 습하고 더워서 시원한 음료! 컵이 습기가 안맺히는거여서 좋았던~얼음도 귀욤귀욤 하고~ 맛있기도 하고~시원하고 느긋하게 있다가 갔습니당!ㅎ', 13, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '네고왕보고 포장해옴 반미에그 진짜 커요 맛있음!! 서브웨이 에그마요가 빵이 부드러워서 그런지 먹기는 더 편함 그치만 바게트에 비닐로 포장돼 있어서 나름 먹는 스킬이 생김 커피는 걍 쏘쏘', 21, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '네고왕 광희챤스 케이크세트 먹으러 방문. 네고왕 할인이 오후9시라서 헐레벌떡 왔는데 아메리카노 마시면서 릴렉스. 번트 치즈켁 많이 부스러져서 먹기 힘들. ㅠ.ㅠ', 58, 12, NULL, SYSTIMESTAMP);
