INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '크림 종류로만 두 가지 시켰더니 쪼끔 느끼했지만 맛은 최고! 음식도 음료도 양이 많아서 좋았네요. 매장 인테리어도 멋지고 직원분들도 다 친절하십니다!', 23, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '직원분들이 너무너무 친절하십니다. 제가 바보같이 세트가아닌 비싸게 따로따로구매했는데 귀찮을수도있는데 더싼방법을 알려주시고 환불처리도 도와주시고 더 싸게 맛나게먹을수있게 해주셨어요 이름표는 못봤지만 7월15일7시 근무자분들 모두모두 친절하셨어요!! 모두모두 복받으세요!!! 이분들 덕분에 자주올거같아요 감사합니다', 59, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '이전에 엔제리너스 건물 지나다니면서 볼 때는 패션관련 건물인가 싶었는데 알고보 엔제리너스였네요ㅋㅋㅋㅋ 건물 외부 내부가 전혀 프랜차이즈 카페같지않고 예뻐요! 엔제리너스 반미 최고 존맛입니다ㅠㅠ', 10, 3, 'GOOD', SYSTIMESTAMP);
