INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '불고기 반미 먹으려고 방문. 고수 빠지고 더 매워진듯 해서 아쉽... 프리미엄 빙수 시작했어요. 옆 테이블에서 블루베리빙수 먹는데 맛있어 보이네요.', 33, 5, NULL, SYSTIMESTAMP);
