INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '키워드를 5개밖에 못고르는게 아쉬울정도로 넓고 깨끗하고 인테리어도 진짜 예뻐요! 그리고 키오스크 있는줄도 모르고 직원분께 메뉴 말했는데 친절하게 답해주셔서 너무 감사했어요ㅠㅠ 너무너무 친절하시고 음료도 맛있었어요ㅎㅎ 최고입니당', 83, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '퍼먹는 스푼 케이크류 50%할인 중이에요. 7500원인데 6월한정 3750원. 키오스크에서 자동할인이에요. 기왕이면 스푼케이크 드시길...', 79, 15, NULL, SYSTIMESTAMP);
