INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '엔젤리너스 매장이 이렇게 이쁘기 있나요..??? 커피 사진은 까먹고 안찍었지만 ㅋㅋㅋ 메뉴도 처음 보는 거 엄청 많구여 분위기 좋네요 !!자주 갈래용!', 101, 26, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '매번 지나다니면서 보기만 했는데 들어와봄😉 엠버 아메리카노 시켰는데 왜 산미가 강한지는 모르겠음;;;;; 아메리카노를 먹는게 아니였음', 66, 13, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '이런 엔제리너스는 처음이에요. 강추해요. 사진도 잘 나오고, 완전 마음에 들어요. 음료맛은 이전과 똑같은 ㅡㅡ; 이렇게 넓게 잘해놓았음에도 화장실은 완전 초소형!!! 규모와 상이한 화장실에 한 번 더 놀랐네요.', 1, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '기존의 엔젤리너스 매장의 프리미엄버전같은. 달달한 느낌의 인테리어와 대형 통창에 홍대 도로뷰를 만끽할수 있고. 시그니처 메뉴라인의 샹그리아는 적당한 신맛+ 상큼함의 조합.', 61, 16, 'GOOD', SYSTIMESTAMP);
