INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '어쩌다 들렸는데 음~ 초큼 비싼대비 매장안도 널널하고 메뉴가 새로워서 좋네요. 흑임자라떼 유자콤 다 맛났고 귀여운치즈케이크. 생긴것도 이뿌고 맛도 상콤함 👍 굿', 37, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '현미라이스샐러드가 있었는데 없어졌었거든요. 다시 생겨서 주문했더니 현미밥 못 먹겠어요. 생쌀 씹는 기분이에요. 그리고 점심 시간에 제발 자리 좀 둘러 보세요. 자리가 더러워서 빈 자리가 많음에도 앉을 곳이 없어요.', 3, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '상그리아 시켰는데 완전 셔요!!!! 깔라만시 뿌려놓은 듯…😭😭 파인애플 어쩌고저쩌고 써있길래 시켰는데 맛 보고 끄암짝 놀랐네요… 결국 다 못 마셨어요 테이크아웃해서 집에서 유리컵에 담아봤어요 그래도 인테리어는 너무 예쁘고 좌석이 편안해서 다음에 또 갈 거 같아요', 93, 24, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '키오스크 전용 페이저가 생겨서 편해요. 주문 후 녹색불 들어오면 집어가면 되는 방식. 이제 더이상 자그마한 모니터를 주시하지 않아도 되서 편하네요.', 123, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '조식을 엔젤리너스 카페에서 한다고? 했는데 후기를 보니 잘나오길래 왔어요. 매장안에 포토존도 많고 디저트도 맛있어보이는거 많아서 다음엔 그냥 카페로 방문할 예정이에요', 12, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '인테리어 이쁘고 좋았어요 사진과같은 장소에 앉아서 창밖을 보면 반짝이고 이쁩니다. 음료맛은 쏘쏘이지만 늦은시간이었어서인지 손님이 많지않아 조용했어요. 다만 음악타입을 좀 바꿔보면 좋지않을까합니다. 인테리어는 고급스럽고 좋은데 음악은 가볍거나 소음처럼 들리는경우가 대부분이에요. 차라리 클래식 혹은 잔잔한 연주곡이나 재즈같은게 좋지않을까 합니다', 14, 10, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '반미샌드위치 먹었는데 오랜만에 먹으니 볼륨이 이 정도였나 하고 깜놀. 진짜 배불러요. L7홍대 단독 인스타그램 인증샷 이벤트 진행중이라고 하니 참여해보세요.', 27, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '2층에 위치하고 생각보다 아주 넖어요~ 새로생겨서 깔끔하고요~ 사진 잘 나와요~ 맛은...음..엔제리너스커피 맛 입니다~  치즈케잌 달고 맛있어요~', 32, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '완벽한 카페에요. 딱 한가지 흠은 의자가 조금 불편해요. 등을 온전히 기댈 수 있는 의자가 없네요. 의자까지 편하면 커피한잔 사고 눌러앉는 손님이 많아서 망할거 같아요. 너무 좋은 카페여요.', 309, 76, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '샌드위치 먹다가 자켓 입은 팔 소매에 벌레 붙은 거 보고 식겁했어요. 서둘러 벌레 털어 내고 벌레 피해서 자리 옮기는데, 자리마다 머리카락, 반미 가루, 음식 소스가 있어서, 자리 옮기기 힘들었네요.', 34, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '시설이 너무 이뻐용!! 인테리어가 이렇게 이뿌다니,,, 힐링되고 좋아요 ㅎㅎ 사진도 잘나오고 , 키오스크도 있어서 편합니다 ! 직원분도 친절하시구 의자도 폭신해용', 428, 97, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엔제리너스 L7홍대점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '반미 내용이 매우 알차서 속에 든 햄, 달걀, 오이가 밖으로 다 나왔어요. 반미 시킬 땐 방역 차원에서 손 닦고 먹을 수 있게 물티슈를 기본으로 주셨으면 좋겠어요. 키오스크에서 (세트 쿠폰 사용 시) 원두 선택, 샷 개수 선택할 수 있었으면 좋겠어요. 그리고 카페답게 디카페인도 판매했으면 좋겠어요.', 17, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '주변에 약속이 있어서 왔다가 시간이 좀 남아서 아벨롭에 왔어용 !! 시오빵과 카페라떼 주문했는데 너무 맛있게 잘 먹었어요!! 여러 공간이 있고, 1-2인석부터 다인석까지 다양한 좌석이 구분되어 있어 좋아요!! 저는 1-2인석으로 이루어진 공간에서 시간을 보냈습니다☺️ 혼자만의 시간을 보내기에도 너무 좋은 분위기라 자주 올 것 같아요! 자리마다 충전도 가능해서 작업하기에도 좋울 것 같아요🤍 다음엔 케이크도 먹어보고 싶네요🤭☘️', 0, 5, 'GOOD', SYSTIMESTAMP);
