INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '오전 일정 마치고 홍대 Coffee & Bakery Avelop 방문했네요 🌺〰️ 날씨도 좋아서 커피도 마시고 애플주스 생각나서 왔네요 🌸〰️ 아벨롭 현관에 들어서면 cafe 느낌보다 정원있는 멋진별장 느낌이 나서 좋네요 🌼〰️ 홍대 가시면 들려보시는거 추천합니다 💕 📮얘플주스.  6,000₩', 29, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '일단 공간 너무 이뻐요!! 사진찍기 진짜 좋은 것 같습니다! 음식도 맛있어요! 아벨롭 브렉퍼스트 맛있어요!! 소시지도 맛있어...!!! 음료는 말해모해~~~!!! 에이드 달지않고 딱 좋았습니다!! 하루죙일 있고싶은 공간!!! 다음에 친구랑 또 오려구용👍', 4, 8, 'GOOD', SYSTIMESTAMP);
