INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '공간도 너무 멋지구  테라스도 있어서 지금 날씨에 오기 딱 좋아요!! 심지어 대형카페라 홍대올때마다 들릴듯!! 커피도 너무 맛있고 디저트 퀄이 엄청나서 싹 다 도장깨기러하러 재방문하려구요😆', 12, 9, 'GOOD', SYSTIMESTAMP);
