INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '서울 여행가서 혼자 방문한 카페인데 크로플 진짜 너무 맛있고 음료도 하나같이 맛있어서 너무 좋더라구요💗 주택을 개조한 카페라서 아늑하고 조용한 분위기가 아주 맘에 쏙 들었습니당', 13, 1, 'GOOD', SYSTIMESTAMP);
