INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '홍대 주택을 개조한 감성 가득한 2층 카페예요. 공간마다 분위기가 달라 포토스팟으로 좋고, 크로플은 따끈하게 구워줘서 아이스크림이랑 꿀조합이에요. 초콜릿 라떼는 진한 초코 맛이 인상적이었어요. 분위기+맛 모두 만족!', 16, 4, 'GOOD', SYSTIMESTAMP);
