INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '카페 인테리어도 예쁘고 커피&디저트맛도 좋아요! 1층, 2층으로 구성되어 있어서 좌석도 생각보다 많이 있어요 연인이든 친구든 누구랑 와도 좋을 곳이에요!', 45, 2, 'GOOD', SYSTIMESTAMP);
