INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '친구가 여기 크로플맛집이라고 해서 궁금해서 와봤어요 근데 음식도 비쥬얼 짱이고 커피도 맛있네요!!!! 직장인이나 평일 이벤트하는것도 좋고 근처 살면 자주오게될거같아요 맘에들어용!!!!', 107, 25, 'GOOD', SYSTIMESTAMP);
