INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '주택을 개조한 느낌이 제 취향이었어요 ㅎㅎ 빈티지하고 깔끔하고 힙한 BGM도 좋았어요! 밀크티와 브런치를 점심으로 먹었는데 JMT🤍', 19, 1, 'GOOD', SYSTIMESTAMP);
