INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '약속시간 남아 우연히 오게되었는데 자주 올거같아요 오전에 이렇게 일찍 오픈하는 곳이 있다니 너무 좋아요 여유롭고 분위기 너무 좋고 기분 좋아지는 곳이예요', 45, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '주택을 개조해 아늑하고 넓은 공간의 아벨롭 🏡 넓은 테라스부터 탁 트인 창과 우드톤의 아늑함이 가득했던 카페! 브런치 메뉴들도 다양하고 빵과 케이크도 있어서 모임이나 데이트하는 분들도 많이 오시더라구요! 1, 2층에 테라스까지 있는 공간이라 원하는 느낌의 자리로 편하게 선택 가능하고 층고도 높아서 개방감 있게 시원했어요! 홍대입구 근처 브런치와 디저트, 음료와 함께 햇살 가득 즐기러 오기 좋은 카페 찾으신다면 추천드려요 😊', 53, 11, 'GOOD', SYSTIMESTAMP);
