INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '오틀리로 우유 변경 했다. 아침 점심 다 거르고 마시는 음료로도 맛있다. 첫 맛이라 강하거나 인위적으로 느껴지면 먹기 힘든데 그런게 없고, 블루베리가 많이 들어가있어서 맛있게 먹을 수 있다. 콤펙트한 크기라서 너무 빨리 마신 것 같다. 약간 블루베리 요거트 맛 같다.', 11, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '캐롯 오픈 샌드위치 너무 맛있어요!! 커피도 원두 두가지 중에 선택 가능해서 좋았습니다. 월요일이라 기분전환 하러왔는데 좋은 선택이었어요ㅎㅎ 인테리어도 넘 예쁘고 다른 메뉴들도 다 먹어보고 싶네요ㅜㅜ', 56, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '근처에서 밥 먹으면서 미리 찾아본 카페인데 자리마다 분위기도 다르고 이야기하기 좋고 무엇보다 음료가 맛있어요 레몬 민트티 맹물인 곳 너무 많은데 진-짜 너무 맛있어서 꼭 드셔봤으면 좋겠어요 진-짜류', 29, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '근처에 일정이 있어서 남은 시간동안 작업할만한 곳을 찾다가 들렀습니다. 인테리어가 예쁘고, 여기서만 볼 수 있는 특색 메뉴가 있습니다. 2층으로 가면 독특한 구조를 가진 공간이 있어서 고르는 재미가 있습니다. 직원분들도 친절하십니다!', 46, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'STUDY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '홍대를 거닐다 예쁜 카페를 발견해서 방문했어요. 더위에 단비 같은 시원하고 예쁜 인테리어로 쾌적하게 맛있는 음료와 함께 쉬어가기 좋았어요:)', 9, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '인테리어가 너무 예쁘고 디저트가 다양해서 좋아요! 음료도 다 맛있고 조용한 분위기 즐기기 좋은 것 같습니다 다음에 또 방문하려고 해요!', 88, 16, 'GOOD', SYSTIMESTAMP);
