INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '골목 안쪽에 예쁘게 자리잡은 카페예요⭐️ 친구가 찾아보고 추천해줬는데 카페 안에 인테리어도 예쁘고 커피도 베이커리도 맛있어요! 직원분들도 친절하시고 카페도 엄청엄청 시원해서 머물렀다가기 좋은 공간입니다!', 15, 6, 'GOOD', SYSTIMESTAMP);
