INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '점심식사후 근처카페로~ 아마도 조카가  조용한곳  찾은듯  양옥딥을  개조한듯해요  2층으로  올라와서  조용하게  커피 마시고  있어요 캐롯오픈샌드위히  맛나네요 소금커피도  별미  더운날  딱인듯 조용하게  혼자  있고 싶을때  평일에는  좋은걸요', 113, 21, 'GOOD', SYSTIMESTAMP);
