INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '다니는 미용실 근처라 루틴처럼 늘 머리하고 아벨롭카페 들러요! 오늘은 소금빵이 없어서 모카빵을 시켜보았습니다^_^ 아벨롭라떼 맛있어요 ! 벌써 3번째 리뷰 … 🥐💖', 85, 18, 'GOOD', SYSTIMESTAMP);
