INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '금요일 오전 오후 일정 마치고 Hongdae Magazine Land  서적 하나 구입해서 Cafe Avelop 왔네요 ☕️〰️ 나오는데 날씨도 화창하고 일정 마치고 책하나 사서 커피 마시러 가야지 했죠 🥤➿ 요즘 자주하는 스트레스 푸는 저만에 노하우죠 ➿ Cafe Avelop 에스프레소 & 애플주스 👀👍 최고 좋아하는 Best Drink 😁🍹 🍎 사과주스                6,000₩', 10, 4, 'GOOD', SYSTIMESTAMP);
