INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '홍대에서 이런 대형카페 찾기 어려운데 엄청 넓어서 좋았어요! 데이트하러 방문했어요. 평일 점심시간 출출해서 캐롯샌드위치 시켰는데 너무 만족스럽게 먹었어요! 소금빵에 치즈소스가 깔려있고 새콤한 당근라페와 야채가 가득 들어있었어요. 많은 기대 안했는데 엄청 맛있더라고요 2인이서 먹기 좋았습니다 넓은 공간에서 맛있는 브런치 먹으니 행복해지더라고요. 감사합니다', 15, 8, 'GOOD', SYSTIMESTAMP);
