INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '주택을 개조해서 만든 카페인데 내부 인테리어가 이쁘고 커피도 맛이 좋네요. 야외 테이블석도 넉넉하고 테라스도 있어 날씨 좋을때 오면 좋을것 같아요. 카페에서 사진찍는 거 좋아하시는 분들이 오시면 좋을 정도로 포토 스팟도 많고 베이커리류도 많이 취급해서 다음에는 디저트류도 맛보러 와야겠어요.', 65, 16, 'GOOD', SYSTIMESTAMP);
