INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '블루베리 라떼랑 치즈케이크 크로플이 유명하대서 홍대 온김에 들렀어요 ㅎ 가격대도 굉장히 합리적이라서 좋았고 , 공간도 넓고 주택을 개조해서 그런지 인테리어가 엄청 독특하고 세련됐어요 ㅎ 소금빵이랑 샌드위치도 있었는데 , 다음에 먹어보려구요 ㅎ전 블루베리라떼랑 말차라떼 추천입니당 ㅎ 1층이랑 2층에 좌석이 다양하게 있어서 단체모임도 가능할것 같아요 ㅎ', 10, 6, 'GOOD', SYSTIMESTAMP);
