INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '오늘 비가 와서 운치있는 창가자리에서 빗소리들으면서 플랫화이트 마시고싶었는데 진짜로 실현 햇네요~~-♡ 분위기 넘넘 좋고 아늑~~♡♡ 남친도조아하고 홍대. 합정 커피데이트장소 추천합니다~~~~', 62, 11, 'GOOD', SYSTIMESTAMP);
