INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '분위기가 예뻐서 지나가다가 점찍어두고 시간 날 때책 읽으려고 혼자 왔어요. 넓고 층도 2개로 되어있어서 여유롭게 즐길 수 있었어요', 40, 6, 'GOOD', SYSTIMESTAMP);
