INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '홍대 한복판인데도 조용하고 평화로운 정원뷰 덕분에 도심 속 힐링!! 야외 좌석 분위기 너무 좋고, 브런치 플레이팅도 예쁘고 맛도 좋아요!~~ 아이스 아메리카노도 진하고 깔끔 🔥 조용히 이야기 나누기 딱 좋은 공간이에요.', 5, 2, 'GOOD', SYSTIMESTAMP);
