INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '지나가다가 카페가 넘 예뻐보여서 들어왔는데 진짜 넘넘 조아써요♥️ 음료랑 디저트, 빵이 다양했는데 소금커피가 넘 맛있었어요😋 매장도 깔끔하고 넓어서 친구들이랑 와서 즐겁게 대화하다가 갔습니당!! 소파 있는 공간 넘 재밌고 편안했어요☺️ 사장님도 넘 친절하셨어요!!', 54, 12, 'GOOD', SYSTIMESTAMP);
