INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '카페가 넓고 분위기가 정말 좋았어요! 공간이 방들로 구분되어 있고, 날 좋을땐 테라스나 바깥 자리도 좋을 것 같아요. 시그니처 아벨롭라떼 달달하니 맛있고, 히비스루비도 상큼했어요. 홍대 합정카페로 만족스러웠습니다👍', 64, 12, 'GOOD', SYSTIMESTAMP);
