INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '캐롯 샌드위치 너무 맛있어요ㅜㅜ!! 미국에서 가볍게 즐기는 브렉퍼스트 같은 느낌이에요. 당근맛이 별로 안 나서 채소 싫어하는 분들도 맛있게 먹을 수 있을것 같아요.  크로플은 달달해서 커피와 잘 어울려요. 뷰도 너무 좋고, 쾌적하고, 자리도 넓어서 넘넘 좋았습니다! 다음에 또 오고 싶은 곳이에용ㅎㅎ', 35, 7, 'GOOD', SYSTIMESTAMP);
