INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '주택을 개조해서 만든 홍대근처의 카페에 왔습니다! 역시 1인 1음료 였지만 음료랑 디저트 모두 맛있었어요😊내부 인테리어가 아주 오래된 할머니집에 떨어진듯한 느낌으로 너무 신선했어요ㅎㅎ 할머니집에서 도란도란 대화하는거 같아서 분위기가 좋았습니다 사람도 없어서 사람들이랑 얘기하기 너무 좋은곳이었습니다', 37, 4, 'GOOD', SYSTIMESTAMP);
