INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '요즘 날씨에 즐기기 너무 좋은 야외테이블과 테라스가 진짜 예쁜 홍대카페예요! 가정집분위기이면서 공간도 넓은 홍대대형카페인데, 베이커리도 커피도 정말 맛있습니당 ㅎㅎ 저는 아메리카노 위에 크림이 올라간 소금커피 마시고 완전 반해버려서 또 먹고싶어서 간만에 재방문했는데 이번에도 대만족이에요! 홍대 분위기 예쁘고 넓고 빵도 커피도 맛있는 카페로 추천드려용', 67, 14, 'GOOD', SYSTIMESTAMP);
