INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '2층 독채로 운영중인 카페인데, 햇살까지도 인테리어 인것처럼 예뻐요 ✨ 혼자 노트북작업하러 왔다가 넘 만족..! 짭조롬한 크림이 듬뿍 올라가는 소금커피가 시그니처 메뉴길래 시켜봤는데 평범한 아인슈페너와는 확실히 다른 느낌이에요 소금빵, 크로와상, 케이크도 다 맛있어보이는데 아침이라서 크로와상만 주문했거든요 버터맛 대박이고 ㅠㅠ 외국 나온 줄 알았어요 다음에는 소금빵도 먹어볼 예정입니다아-!', 81, 18, 'GOOD', SYSTIMESTAMP);
