INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '홍대 카페는 다 비슷하다고 생각했는데 아벨롭은 확실히 달랐어요! 분위기부터 뭔가 고급스럽고 세련돼서 그냥 사진만 찍어도 인생샷이 나오더라구요 ㅎㅎ 라떼도 맛이 진하고 달달해서 과제하다가 잠시 쉬기 딱 좋았어요!', 14, 4, 'GOOD', SYSTIMESTAMP);
