INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '인테리어가 고급지고 분위기가 적당히 조용해서 대화나누기 참 좋은 카페인 것 같습니다 창살로 들어오는 햇빛이 정말 예쁘고 따스해요 특색메뉴가 있어서 더욱 좋았어요 소금빵이 정말 맛있습니다 💯', 112, 21, 'GOOD', SYSTIMESTAMP);
