INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '커피도 너무 맛있고 인테리어가 멋져서 사진 찍을 것이 많아요. 자석도 많고 넓어서 추천 드립니다. 옛날 집을 이렇게 개조 했다니 놀라워요 ㅎㅎ', 43, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'RETRO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '오랜만에 홍대 놀러가서 분위기 좋은 홍대카페 찾다가 발견해서 다녀왔어요!! 제가 많이 걷는 거 싫어하는데 홍대입구역카페라서 역에서 10분만 걸으면 도착해서 좋았어요〰️ 카페 분위기도 넘 좋고.. 음료도 맛있었어요! 디저트류도 맘에 드는 걸로 고를 수 있게 종류가 많아서 완전 맛있게 먹고 나왔습니다아🤤🩷', 114, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '연습하고 아점하러 왔는데 빵도 바삭하소 뷰드럽고 소스가 킥임. 상큼한맛도 나서 느끼하지않고 뷰드러운데, 신선한느낌도 들어서 너무 좋아요 너무 만족함', 2, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '인테리어도 너무 이쁘고 커피랑 디저트도 완전 맛있네요!! 사진찍기 좋아하는 친구랑 사진도 많이찍고 우선 커피가 너무 제스타일이라 좋았오요!! ㅎㅎ 또 차마시러 올게용✨️', 40, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '너무 예쁘고 넓은 홍대입구역 인근 카페입니다🥰 시그니처 커피들이 맛있었고 주택 개조한 카페라 분위기가 좋았어요 날씨 조금 선선해지면 테라스에서도 앉아있다 가고 싶네요', 19, 5, 'GOOD', SYSTIMESTAMP);
