INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '홍대카페 찾는 도중 분위기 좋아서 방문 해봤어요.ᐟ.ᐟ 홍대입구역 근처 카페여서 오고가기 정말 편했고 요기 분위기 진짜 무슨 일 ㅜㅜ 사진 엄청 잘 나와요🫶🏻 메뉴도 많고 다양해서 뭐 먹을지 한참 고민했네요.. 홍대입구역카페 찾으신다면 요기 진짜 강추강추 합니다 ~~~', 41, 1, 'GOOD', SYSTIMESTAMP);
