INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '여자친구랑 같이 왔어요 커피가 산미랑 고소, 이렇게 2가지 잇고 되게 진해서 맛있어요👍 1층은 조용한 분위기고 2층이 왁자지껄한 분위기에요😄', 38, 2, NULL, SYSTIMESTAMP);
