INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '맨날 오는 아벨롭 카페 좋아요. 이 근처오면 방문하는데, 날씨가 좋아서 테라스에 왔습니다. 커피도 맛있고 디저트도 다양해서 좋습니다. 또 방문 할게요.', 29, 1, 'GOOD', SYSTIMESTAMP);
