INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '친구가 홍대카페 아벨롭 추천해줘서 다녀왔는데 너무 좋았어요! 인테리어 구경하는 재미도 있고 그리고 소금커피 완전 최고였어요ㅠㅠ! 달달하면서 짭짤하면서도 근데 두맛이 조화가 기가막혀서서 집에와서도 계속 생각나더라구요.. 아벨롭때문에 또 홍대 갈 예정이에요!', 26, 8, 'GOOD', SYSTIMESTAMP);
