INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '발로나 초코라떼 진하고 맛있어요. 조용한 골목에 있고 넓어서 쾌적합니다. 노트북 사용하기 용이한 책상들도 꽤 있고 다양한 자리가 있어서 대화하기도, 작업하기도 좋아요', 14, 2, 'GOOD', SYSTIMESTAMP);
