INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '아벨룸 홍대본점 다녀왔는데 분위기 완전 힙했어요. 홍대카페 중에서 이렇게 감성 뿜뿜하는 곳은 처음 본 듯해요! 홍대입구역카페 찾는 분들한테는 위치도 딱 좋아서 편했구요💛 디저트랑 음료도 예쁘고 맛있어서 사진 찍느라 바빴답니다 다음에 또 가고 싶은 곳으로 딱 정했어요 ✨', 2, 5, 'GOOD', SYSTIMESTAMP);
