INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '분위기가 너무 좋고 예쁩니다 ㅎㅎ 우드톤의 따뜻한 공간, 빈티지한 포스터와 소품들, 그리고 각기 다른 무드를 가진 좌석들 덕분에 마치 작은 전시 공간처럼 구경하는 재미도 가득했어요. ​2층으로 올라가면 또 다른 분위기의 공간이 펼쳐지는데, 클래식한 복도부터 천장에 클라우드처럼 퍼진 인테리어, 반짝이는 샹들리에, 독특한 구조의 테이블과 좌석들까지—☺️🧡 ​ 공간마다 확실한 개성이 느껴져서 좋았습니다. (제가 좋아하는 비틀즈 음악도 흘러나와서 행복했어요 !) 커피도 정말 맛있고, 애플파이도 맛있었습니당 히히 또 방문하고 싶어요 ❤️ 유럽풍 카페 너무너무 좋네요 ~~ 직원분들도 친절하셔요!!', 30, 1, 'GOOD', SYSTIMESTAMP);
