INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '분위기에 취해 ~~^^ 좋은곳에 오게되서 기쁘네요 🧡 좋은시간 함께하게되서 너무좋아요😊 ☕️커피를 빵과 함께 먹을수있는곳 👍👍👍 담에 또 와야죠!🥐🥯', 31, 8, 'GOOD', SYSTIMESTAMP);
