INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '주택을 개조해서 그런지 인테리어랑 분위기가 너무 좋아요~! 크로플도 진짜 달달하고 쫀쫀하달까 너무 맛잇어요 ㅠ 그리고 아벨롭 라떼 너무 내스타일🧡 컵 사이드에 발려진 시나몬 가루랑 크림이랑 같이 커피를 마시니 너무 달달하면서도 맛잇네요👍🏻', 91, 21, 'GOOD', SYSTIMESTAMP);
