INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '남편과 점심식사후 홍대카페 검색해서 방문했는데 카페 분의기가 너무 좋았어요 ! 직원분들도 너무 친절하고 음료랑 디저트까지 완벽 그자체👏🏻', 14, 10, 'GOOD', SYSTIMESTAMP);
