INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '카페 분위기가 너무 좋아요*⸌☻ັ⸍* 음식도 커피도 너무 맛있고 플레이팅이 예뻐 기분이 좋아지는 것 같아요! 회사 근처에 이렇게 예쁜 곳이 있는 줄 알았으면 자주 왔을 텐데🥹 앞으로 자주 올게요!', 88, 12, 'GOOD', SYSTIMESTAMP);
