INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '벌써 4-5번째 방문이에요! 대형카페라 자리 걱정도 없고 분위기도 좋아요 소금빵 맛집에다가 커피도 맛있어서 혼카페 하러 자주 옵니당 추천드려요 ~.~', 111, 19, 'GOOD', SYSTIMESTAMP);
