INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '꺄악!!!!!! 지인들과 방문한 아벨롭!!!!! 오마이갓!!!! 라떼 맛집!!!! 따뜻한 커피 마시고 싶어서 주문한 라떼 완전 맛나요!! 지인들은 소금커피 엄청 맛나고 아이스라떼도 넘넘 비주얼 짱!!!! 아~~~ 기분좋은 토요일 시작할 수 있게 기쁨을 선사해 주어서 고마워요🙏 아웅 넘넘 맛나요!!!!', 6, 4, 'GOOD', SYSTIMESTAMP);
