INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '브런치 먹으러 방문했어요~! 매장 분위기도 좋고 음식도 맛있었어요! 주택을 개조해서 만들어서 그런지 아늑한 분위기라 데이트하기에 좋은 장소인것 같아요 다음에는 디저트 먹으러 오려구요~!', 6, 10, 'GOOD', SYSTIMESTAMP);
