INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '여행 중 오전 시간에 잠깐 들렀는데, 메뉴가 너무 많아 오래 앉아있을 수밖에 없었어요! 깔끔하고 맛있어요 정말 추천합니당 :)', 57, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '독서모임 하러 방문 했는데 4인 이상 사용할 수 있는 룸이 있어서 편했어요! 인테리어도 예쁘고 분위기 있습니다 ㅎㅎ~~ 음료랑 빵도 맛있어요 💕 또 올게요', 42, 2, 'GOOD', SYSTIMESTAMP);
