INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '여기 인테리어도 너무 예쁘고 커피도 고소하구 맛있네용… 아니 크로플이 진짜 무친놈이니 다들 시켜드세요. 진짜 맛있습니다. 🥵👍', 20, 4, 'GOOD', SYSTIMESTAMP);
