INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '홍대 이층 가옥을 리모델링 해서 만든 마당이 넓은 이층 테라스가 뷰가 좋은곳 커피와 베이커리가 High level 👏💬 이네요. Cafe & Bakery Avelop 👍😎🤓 마당에 테이블이 8개 정도 되네요 넓고 여유가 있어 좋았네요 👏👏👏 다양한 Dessert Menu로 운영 하시네요🎶 밖에서 포스터로 보니 다음에 주문해서 시식 해보고 싶은 마음이 생기네요 🏅😒➿ 오늘은 초행이라 많은 정보을 올린진 못하고 I''ll come back and upload it next time 😀💬💬 📮 에스프레소 Double            5,000₩', 20, 2, 'GOOD', SYSTIMESTAMP);
