INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '넓고 층고가 높아서 쾌적하고 카페 소품 하나하나 이쁜게 많아서 나도 모르게 사진찍고 있더라고요. 아벨롭라떼 시나몬향과 달달함이 너무 좋았어요. 다음에 날씨가 좀 더 선선해지면 야외에도 꼭 한번 앉아보고 싶네요', 23, 3, 'GOOD', SYSTIMESTAMP);
