INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '브런치랑 애플파이 먹고싶어서 방문했습니다! 홍대입구역에서 거리는 조금 있는데 슬슬 산책하면서 오기 좋은 것 같아요 음식 모두 맛있었고 분위기도 너무 좋은 것 같아요! 재방문의사 있습니다~😊', 28, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '어렸을 적 살던 집 거실에 앉아서 창밖을 내다보던 익숙함&여유를 느낄수있음. 얼그레이 케이크에 시그니쳐 라떼 맛있게 먹었어요. 한적한 시간대에 또 오고싶어요♡', 46, 0, 'GOOD', SYSTIMESTAMP);
