INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '리뷰가 좋아서 방문했는데 매장도 넓고 구옥 인테리어가 너무 예뻐요 😋 커피도 맛있고 특히 크로플이 진짜 대박이에요!! 사진 잘 나오는 커피 맛집. 다음이 오면 다른 브런치 메뉴도 먹어보려구요.', 95, 23, 'GOOD', SYSTIMESTAMP);
