INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '아벨롭 라떼는 한 모금 마시는 순간 행복해지는 맛이에요. 우유와 커피의 밸런스가 완벽해서 매일 마시고 싶을 정도입니다. 홍대에서 커피 제대로 즐기고 싶으신 분들께 강추합니다.', 37, 2, 'GOOD', SYSTIMESTAMP);
