INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '날씨좋아서 테라스 카페 찾다가 왔는데 내부가 더 예쁘고 좋아서 내부에서 커피한잔 즐기는중☀️ 커피도 맛있고 여유즐기기에 딱 좋은곳🤠', 105, 24, 'GOOD', SYSTIMESTAMP);
