INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '인테리어가 공간별로 감성이 달라서 신기하고 감동이였어요 :) 사진찍기에도 굉장히 좋아서 데이트코스나 친구들모임으로도 강추드립니다 👍 커피랑 디저트 모두 맛있어요^^', 27, 0, 'GOOD', SYSTIMESTAMP);
