INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '맛있다고 해서 가봤는데, 기대 이상이었습니다. 진한 커피향과 부드러운 우유 거품이 어울려서 너무 좋았어요. 분위기까지 좋아서 책 읽으면서 힐링하기 딱 좋은 곳입니다.', 62, 17, 'GOOD', SYSTIMESTAMP);
