INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '토요일 오전에 갔는데 1층은 조용해서 혼자 책 읽기 딱 좋았어요. 사람 많을 줄 알았는데 시간대 잘 맞추면 여유 있더라고요. 라떼 부드럽고 따뜻해서 만족, 특히 테이블 간격이 넓은 게 제일 마음에 들었어요. 홍대 근처에서 카페 찾는 분들께 추천드려요.', 0, 3, 'GOOD', SYSTIMESTAMP);
