INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '너무 예쁘고 감성 넘치는 카페 아벨롭❣️ 시그니처인 아벨롭라떼/카페라떼 커피도 고소해서 맛있고 패션후르츠에이드는 상큼 시원! 번트 치즈케이크도 꼭 드세요 존맛👍', 42, 4, 'GOOD', SYSTIMESTAMP);
