INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '치즈 베리 크로플은 정말 색다르고 맛있었어용!!! 아아 두 잔은 산미와 고소한 거 하나씩 시켰는데 둘 다 만족했슴당 다양한 메뉴가 있어서 조은 것 같아요!!  감성 가득한 분위기에서 여유롭게 즐기기 딱 좋은 카페인 것 같아용 메뉴 하나하나에 정성이 느껴져서 다음에도 꼭 다시 오고 싶숩니덩', 24, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '친구들이랑 홍대입구역 카페 검색해서 갔는데 매장 분위기도 너무 좋고 디저트도 진짜 맛있었어요😄 에이드도 맛있고 커피도 향이 장난아니에요☕️', 25, 3, 'GOOD', SYSTIMESTAMP);
