INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '카페가 넘 이쁘고 음료도 맛있습니다😀 이젠 더워서 밖엔 못앉지만 야외자리도 있어서 좋습니다~ 평일에 오니까 한적하고 넘 좋아용ㅎㅎ', 58, 13, 'GOOD', SYSTIMESTAMP);
