INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '이 카페는 음료 맛도 맛인데, 건물 자체가 진짜 매력있어요. 김중업 건축가가 설계한 주택을 현대적으로 리모델링 했다고 하던데, 외관부터 클래식하면서도 세련됐어요. 내부도 우드의 따뜻한 느낌과 모던한 현대적인 느낌이 돋보이게 꾸며져 있어서 친구들이랑 사진 찍기에도 좋았어요 😎 커피랑 디저트도 짱 👍🏻❤', 11, 8, 'GOOD', SYSTIMESTAMP);
