INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '복층 구조에 테라스까지 있어서 공간이 엄청 여유롭고 분위기 있었어요. 사진 찍기 좋은 포인트가 곳곳에 있고, 커피도 꽤 괜찮았어요. 시나몬 좋아하시면 여기 대표 메뉴인 아벨롭 라떼 추천드려요!! 평일 오전엔 조용해서 노트북 하기에도 좋았습니다.', 40, 6, 'GOOD', SYSTIMESTAMP);
