INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '크로플 넘 맛있어용 역이랑 가까운데도 사람들 북적거리는 거리에 있는게 아니라 한적하고 조아요 자리도 많구 카페가 커서그런지 조용하고 분위기 좋았어요! 데이트 하기 좋아여 초코크로플 추천🍫', 11, 4, 'GOOD', SYSTIMESTAMP);
