INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '커피도 맛있고 너무 친절하세요. 우드톤의 고풍스러운 분위기에 좌석도 다양하고 좌석 간의 가격이 띄엄띄엄 떨어져 있어서 이야기 나누기도 좋고 책 읽는 사람들도 볼 수 있었어요.', 17, 3, 'GOOD', SYSTIMESTAMP);
