INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '홍대 데이트하다가 친구가 좋았다고 추천해준게 기억나서 들어갔는데 일단 인테리어가 엄청 넓은데도 아늑하도 감성적이어서 데이트하기 넘 좋았어용 ☺️ 디저트 종류도 다양하고 커피 맛도 너무 좋더라두요!! 💜', 22, 6, 'GOOD', SYSTIMESTAMP);
