INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '라떼 맛집으로 소문난 아벨롭 홍대본점에 다녀왔어요. 라떼가 진하면서도 부드럽고, 고소한 맛이 오래 남아 정말 만족했습니다. 분위기도 좋아서 커피 마시며 오래 머물고 싶었어요.', 16, 1, 'GOOD', SYSTIMESTAMP);
