INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '2층 주택 개조한 카페라 분위기 짱짱ㅋㅋㅋ 1층과 2층에 각각 야외 자리 있고 내부도 인테리어 넘 예뻐요. 디저트 종류가 많아서 좋아요!! 커피 주스 빵 다 맛있음~~', 43, 10, 'GOOD', SYSTIMESTAMP);
