INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '인테리어나 소품들도 느낌있고 빵도 가격에 비해 사이즈가 큰 편이라 좋았어요. 다음에는 브런치 메뉴도 먹어보려고요~홍대 상수 합정 근처 분좋카 찾으시면 꼭 와보시길 추천드립니다!', 10, 2, 'GOOD', SYSTIMESTAMP);
