INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '주택을 개조한 곳이라 친근한 듯 독특한 느낌을 주는 곳이에요. 커피도 훌륭하고 디저트 종류도 다양해서 먹는 재미, 보는 재미가 있고 친구들이랑 홍대 근처 놀러 가면 꼭 가게 돼요', 28, 5, 'GOOD', SYSTIMESTAMP);
