INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '시나몬크림라떼 맛있더라구요!! 그리고 베이커리류도 맛잇었어요 ㅎㅎ매장이 주택을 개조한거 같아요 인테리어도 이쁘고 생각보다 엄청 넓어서 좋았어요 ㅎㅎ데이트나 모임으로도 딱인거같아요 ㅎㅎ', 53, 14, 'GOOD', SYSTIMESTAMP);
