INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '아벨롭은 카페라기보단 세련된 라이프스타일 공간 같았어요^^ 우드톤 인테리어와 햇살 좋은 테라스가 고급스러웠고, 메뉴도 플레이팅이 예뻤어요!! Salt coffee도 특이하고 맛있었고, 전체적으로 고급진 느낌이었어요>_< 데이트나 모임에 강추~!!', 8, 0, 'GOOD', SYSTIMESTAMP);
