INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '아벨롭 첨 가봤는데 공간도 메뉴도 세련미가 가득했어요🙂 클래식한 건물과 트렌디한 인테리어가 잘 어울렸고, 크로플을 비롯한 디저트들이 고급스럽고 사진찍기에 넘 예쁘더라고요!! 커피맛 잘 모르는 1인이지만ㅎㅎ 커피도 고소하고 맛있었고, 디저트와 잘 어울려 대만족👍🏼 홍대에서 감각적인 브런치 카페 찾는다면 추천해요!', 59, 14, 'GOOD', SYSTIMESTAMP);
