INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '친구랑 홍대 들려서 브런치 먹으러왔는데 너무 맛있어요! 내부 인테리어도 감성있고 커피도 맛있구 꼭 와야하는 곳이네요ㅎ 다음에도 올게요!', 28, 1, 'GOOD', SYSTIMESTAMP);
