INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '분위기도 너무 좋고 일단 노래가.. 플리가 너무 취향저격이에요..✨또 커피 블랜드를 선택할 수 있어서 너무 좋고 또 커피가 너무 맛있네요..🤭 분위기도 좋고 이뻐서 정말 느좋카페입니다..🫶🏻', 44, 3, 'GOOD', SYSTIMESTAMP);
