INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '주택을 개조해서 고즈넉한 매력이 넘치는 공간이었어요, 플레이팅 아주 예술인브런치와 고소한 라떼 한잔으로 하루를 시작했습니다, 가까워서 정말 자주 찾아올 것같아요, 요즘 이렇게 감성있는 카페 많이 없는데 찾게되어 반가웠습니다 😊', 46, 3, 'GOOD', SYSTIMESTAMP);
