INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '주택을 개조한 넓은 카페라고 하길래 어떨지 궁금해서 이번 쉬는날에 다녀오게 되엇는데 인테리어가 진짜 너무 예쁘더라구요ㅎㅎ 헤이즐넛 라떼는 향도 좋고 맛도 최고였어요ㅎㅎ', 73, 11, 'GOOD', SYSTIMESTAMP);
