INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '홍대 오면 꼭 들러야 할 감성 카페 같아요~! 시그니처 음료가 독특하면서도 맛이 진해서 기분 전환하기 딱 좋았어요 ㅋㅋ 인테리어도 감각적이라 사진 찍기에도 최고였습니다~~^^', 4, 1, 'GOOD', SYSTIMESTAMP);
