INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '카페가 너무 예뻐요ㅠㅠ 주택 개조해서 만들었대요. 사진 찍는 거 좋아하시는 분들한테 엄청 좋을 것 같아요! 저는 눈에 열심히 담았습니다..ㅎㅎ 음료도 디저트도 정말 다 예뻤어요~ 맛도 좋았습니다 ㅎㅎ 우연히 발견한 예쁘고 조용한 곳에서 힐링 잘 하다 가요!', 67, 16, 'GOOD', SYSTIMESTAMP);
