INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '우연히 지나가다가 들렀는데 분위기도 좋고 음료/디저트 모두 맛있었어요! 마당, 테라스 등 야외공간이 넓게 있고 방방마다 다른 컨셉으로 실내공간도 재밌었어요. 작업하러 오는 조용한 분위기의 카페는 아니고 잠깐 얘기하러, 기분전환하러 오기 좋은 카페입니다!', 49, 2, 'GOOD', SYSTIMESTAMP);
