INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '친절하게 응대해주셔서 기분 좋게 마실 수 있었어요 카페 인테리어도 좋고 직원분들 너무 친절하게 대해주셔서 편안한 시간 보냈네요', 4, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '너무 만족스러웠어요. 직원분들의 친절함이 인상적이었고 카페에 온 기분을 제대로 느낄 수 있었어요. 편안하게 힐링할 수 있었어요 ㅎㅎ', 26, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '다이어트중인데 카페에서 샐러드도 판매한다고 추천해서 방문했는데 완전 대만족 ! 시나몬 커피도 완전 내스퇄 인테리어랑 분의기도 최고 👍🏻 완전 맛집 인정 :)', 50, 5, 'GOOD', SYSTIMESTAMP);
