INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '분리된 공간 마다 분위기가 달라서 다음에 다른 곳에도 앉아보고싶어요🤍 가볍게 브런치와 커피 마시기에 좋은 따뜻하고 아늑한 카페에요!~ 다음에 더 날이 따뜻해지면 다시와서 테라스에 앉아보고싶네요ㅎㅎ', 9, 0, NULL, SYSTIMESTAMP);
