INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '진짜 커피부터 디저트까지 와벽했던 카페!! 너무너무너무 맛있어요!! 제 남자친구가 해외에서 왔는데 크로플 먹고 너무 맛잇었다고!!ㅋㅋ 혼자서 다먹었어요… 한입 먹었는데 진짜 말 못할정도로 너무 맛있게 먹었어요 또 올께요~~', 116, 19, 'GOOD', SYSTIMESTAMP);
