INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '말차라떼랑 치즈케이크, 크로플 맛집이에요. 주택을 개조해서 아늑한 집 분위기라 좋아요. 공간도 넓어서 단체모임하기에도 좋아요!! 다음에 또 방문할게요~', 44, 7, 'GOOD', SYSTIMESTAMP);
