INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '홍대 쪽 카페 찾다가 리뷰 좋아서 방문했어요. 시그니처 커피 아벨롭 라떼랑 솔트 커피, 말차라떼 다 맛있어요 ㅎㅎ 인테리어도 아늑하고 넓어서 좋네요 👍🏼', 1, 9, 'GOOD', SYSTIMESTAMP);
