INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '조용하고 아늑한 분위기에 반해서 또 가고 싶은 카페예요. 인테리어 하나하나 신경 쓴 게 느껴지고, 조명이 부드러워서 머무는 내내 마음이 편했어요. 직원분들도 정말 친절하시고, 커피랑 디저트 맛도 기대 이상이라 감동했어요. 혼자 조용히 책 읽기에도 좋고, 친구랑 도란도란 이야기 나누기에도 완벽한 곳!', 23, 6, 'GOOD', SYSTIMESTAMP);
