INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '주말 아침 건너뛰고, 점심을 샌드위치와 블루베리 라떼로 먹었습니다, 달달 상콤하면서 든든한 블루베리 라떼와 당근라페 가득 들어간 소금빵 샌드위치가 딱 취향이었습니다 : )', 41, 4, 'GOOD', SYSTIMESTAMP);
