INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '음료도 맛있고 디저트 초코가 진짜 미쳤어요… 공간도 다양하게 넓고 야외 공간도 있어서 지금 같은 날씨에 어디 너무 좋아요! 홍대 시끄러운 골목이랑도 떨어져있어서 친구들이랑 데이트하기 딱 좋아용🪽🫧🍀🍧', 7, 10, 'GOOD', SYSTIMESTAMP);
