INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '가정집을 개조해서 아늑한 느낌을 주는 인테리어에 1층, 2층 , 야외까지 좌석이 넓게 분포되어.있습니다. 시그니처인 소금커피는 살짝 짭쪼름하며 땅콩버터같은 맛이 나요. 황치즈로투스 크로플, 캐롯샌드위치 모두 맛있게 먹었습다. 샌드위치는 치즈를 조금은 줄여도 되지 않을까 싶어요 ㅎㅎ', 47, 9, 'GOOD', SYSTIMESTAMP);
