INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '인터넷 검색 후 방문했는데 매장 인테리어도 너무 예쁘고, 커피가 지인짜 맛있어요!!!! 지금도 벌써 두번째로 마시고 있답니다아👍👍 케익 종류도 다양하고, 분위기도 좋아요~!', 4, 6, 'GOOD', SYSTIMESTAMP);
