INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '홍대 종종 올 때마다 들리는 카페입니다! 매장은 전원 주택처럼 되어있는데 분위기도 좋고 익숙한 팝송이 흘러나오는 곳입니다. 베이커리도 맛있고 커피도 무난하게 좋네요! 시그니처 커피는 시나몬이 잔뜩 들어간 라떼인데 시나몬을 좋아하는 저로썬 만족스러웠습니다ㅎㅎ 다음에 올때는 먹었었던 판단라떼 먹으러 올게요!!', 47, 3, 'GOOD', SYSTIMESTAMP);
