INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '말차 라떼도 너무너무 맛있고 연유브레드도 너무 맛있었어요!! 연유브레드 너무 많을까봐 걱정 했는데 맛있어서 순삭했습니다!! 너무 좋아요. 공간도 너무 예쁘게 잘 되어있습니다!! ☘️ 연유브레드 꼭 드세요🤍', 55, 13, 'GOOD', SYSTIMESTAMP);
