INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '날씨 좋은 날 아벨롭 와서 커피 마셨는데 너무 좋네요!! 카페가 옛날 주택을 개조한 곳이라 레트로하면서 멋있어요 ㅎㅎ 커피도 괜찮고 직장인 할인되서 자주 올 것 같아요', 28, 10, 'GOOD', SYSTIMESTAMP);
