INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '서교동의 분위기 좋은 까페를 소개합니다.  이곳은 까페 아벨롭 홍대 본점입니다. 서교동 직장인 이라면 할인도 해준다는 점이 마음에 드네요. 이층 창가에 자리 잡고 까페라떼와 아이스티를 시켰습니다.  날씨가 조금 풀리긴 했지만 여전히 창가의 햇살이 너무 좋습니다. 모던한 도시적인 인테리어와 음악이 마음은 편안하게 해주는 곳입니다. 네명이 오면 아주 좋은 공간이 있는데 오늘은 두명이라 다음에 이용해야 겠네요. 따뜻한 까페라떼에 나무잎으로 수를 놓아 기분 좋게 힐링 하고 갑니다. #홍대까페 #아벨롭홍대본점 #예쁜까페', 5, 1, 'GOOD', SYSTIMESTAMP);
