INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '엄청 크게 카페가 있어 한번 들어봤는데 다양한 빵이랑 음료가 있어서 넘 좋았고 특히 빵이 오픈이 되어있는 게 아니라 덮개로 다 되어있어 위생적이라 제일 맘에 들었어요! 음료수도 맛있고 커피도 산미 없는게 제 스타일이에요 테라스랑 다양한 의자가 있어서 좋아요어요!!!', 71, 15, 'GOOD', SYSTIMESTAMP);
