INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '카페 예뻐서 왔는데 크로플이 너무 맛있어요~!!! 음료도 물론 맛있는데 크로플이 미쳤어요! 다들 블루베리 크로플 꼭 시켜드세요👍', 15, 9, 'GOOD', SYSTIMESTAMP);
