INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '주말이라 사람이 많아서 자리가 막 많이 남아있지는 않아요! 커피 진하고 직원분들이 넘...친절하십니닷ㅎㅎ카공하기엔 북적북적해서 여긴 대화하러 오시기 좋을 것 같아요!', 10, 6, 'GOOD', SYSTIMESTAMP);
