INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '맛있는 커피 찾아서 왔는데 커피 진하고 맛있어요! 인테리어가 너무 예뻐서 그런지 분위기 너무 좋아요~~~~디저트도 맛있고 좋아용🩷🩷', 78, 18, 'GOOD', SYSTIMESTAMP);
