INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '처음으로 방문했는데 커피와 디저트가 너무 맛있었어요~~ 사람들도 많아서 자리를 잡는데 조금 걸렸지만 방 안에 자리도 많아서 금방 자리를 잡을 수 있었습니다!! 밖에 통창도 있어서 탁 트인 개방감에 저까지 시원해집니다♥️', 49, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '카페 외관부터 너무 예쁜 곳,, 어디서든 사진 찍어도 너무 예쁘게 잘 나와용 커피랑 음료도 너무 맛있어여 ㅎㅎ 담에는 브런치 먹으러 또 방문할게요! 데이트 장소로 딱입니다,,💙💙', 114, 19, 'GOOD', SYSTIMESTAMP);
