INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '기대 안하고 걍 시켰는데 넘 맛있어요! 그리구 보통 휴무일에 다른카페는 자리 없는데 여기는 적당히 자리 차있고 그렇게 시끄럽지도 않아서 좋았어요~ ㅎㅎ', 39, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '커피 마시기 싫어서 레몬 민트티 시켜봤는데 너무 상큼하고 향긋해서 잘 마셨습니다! 인테리어가 잘 되어 있고 날씨가 선선해서 야외 자리에 앉는 걸 추천드려용', 93, 22, 'GOOD', SYSTIMESTAMP);
