INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '평일 낮 혼자왔는데 가게 넘 이쁘구 음식도 맛났어요 근데 남자직원분  불친절하셨어요. 인사도 안받아주시고 질문대답도 안해주시고 고개로 끄덕 한번하시고.. 주문 받을 때도 한숨쉬시고 ..허.. 속상했어요 ㅠ', 44, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '연남 카페 자리 없어서 여까지 온 케이스..ㅎ 근데 너무 넓고 인테리어 예쁘고 밖에 앉았는데 초록초록 감성 짱이고.. 크로플 맛있고 커피도 맛있고 행복합니다.. 또 와야지👍', 24, 6, 'GOOD', SYSTIMESTAMP);
