INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '아이스아메리카노, 사과쥬스, 애플 시나몬 크로플 주문했습니다‼️ 애플시나몬크로플 완전 달달 하니 맛이써용~~사과쥬스는 건강한맛🍎 아아는 무난무난☕️ 주택을 개조해서 만든 구조라서 더 예쁘고 고급져요. 날이 좋아서 마당에서 먹기에도 딱입니다.', 3, 10, 'GOOD', SYSTIMESTAMP);
