INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '대박👏👏🙏 홍대에서 이런 대형카페 찾기 어려운데 엄청 넓어서 좋았어요! 평일 점심시간 출출해서 캐롯샌드위치 시켰는데 너무 만족스럽게 먹었어요! 소금빵에 치즈소스가 깔려있고 많은 기대 안했는데 엄 청 맛있더라고요 2인이서 먹기 좋았습니다', 41, 2, 'GOOD', SYSTIMESTAMP);
