INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '크로플에 시나몬애플잼 아낌없이 듬뿍 뿌려주시고 맛있어요. 말차갸또도 진하고 커피도 맛있어요. 분위기도 조용하게 도란도란 이야기나누기 좋습니다. 날씨가 좋아 테라스에 앉았는데 분위기나 음악 너무 좋네요.', 21, 6, 'GOOD', SYSTIMESTAMP);
