INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '연유브레드 부드럽고 달달하니 너무 맛있었어요ㅎㅎ 아벨롭라떼도 시그니처라 시켜봤는데 크림이 완전 제 스타일ఌ 라떼도 아트 예쁘게 해주셔서 넘 좋았어요 다들 친절하시고 사진 찍을 공간도 많아서 다음에 또 방문할거예요ఌ', 120, 20, 'GOOD', SYSTIMESTAMP);
