INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '아벨롭커피가 시나몬크림라떼라 시나몬 좋아해서 찾아왔어요:) 분위기도 좋고 사람들은 많은데 많이 시끄럽진 않아요 ! 원두도 선택가능해서 좋아요', 40, 7, 'GOOD', SYSTIMESTAMP);
