INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '올해는 유명한 카페를 찾아다니는 계획을 가지고 이쁜 카페 다니고 있습니다. 개인주택을 리모델링하여 만든 카페인데 아기자기하니 이쁘네요.', 48, 4, 'GOOD', SYSTIMESTAMP);
