INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '공간이 넓고, 조도가 낮아 분위기가 좋습니다. 특히 시그니처 메뉴인 소금커피와 아벨롭 라떼는 위에 올리간 크림이 아주 맛있습니다 ㅎㅎㅎ 공간 대관도 가능하다고 하니 행사용으로도 너무 좋을듯!!', 2, 1, 'GOOD', SYSTIMESTAMP);
