INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '홍대에서 조용히 디저트 즐기고 싶을 때 딱 좋은 곳! 케이크는 부드럽고 달지 않아서 좋았고, 티도 향이 은은해서 케이크랑 정말 잘 어울렸어요. 매장 분위기도 아늑해서 친구랑 수다 떨기 딱 좋았어요. 다음엔 다른 케이크도 먹어보고 싶네요', 27, 9, 'GOOD', SYSTIMESTAMP);
