INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '평일 한시 반쯤 왔는데 웨이팅 없이 한적했어요~!! 커피도 맛있고 브런치 메뉴가 넘 맛나요!! 2층 공간도 햇살 예쁘고 다음에 또 오고싶어요❤️🥰😍👍🏻👍🏻', 25, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '우선 대형카페 러버로서 너무 쾌적하고 좋았고 느낌있는 음악도 계속 틀어주셔서 대화나누기에도 좋았어요 시그니처 메뉴인 아벨롭라떼와 소금커피는 쫀득한 크림이 인상깊었고 직원분들도 친절하시고 크로플도 달달하고 바삭하고 양도 많아서 맛있게 먹었어요~ 합정/홍대역 가면 또 찾게될 카페에요', 0, 10, 'GOOD', SYSTIMESTAMP);
