INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '오늘 내 인생에서 최대로 꾸미고 인생사진 남겨야지 하고 찾아온 카페 .. ✨기대 안했는데 고구마케이크 진심 넘 맛있었어용 .. 🩷🩷', 82, 13, 'GOOD', SYSTIMESTAMP);
