INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '일단 매장 분위기 국밥입니다.. 쾌적하고 인테리어 등등 하나하나 신경 쓰신게 눈에 보이고 노래도 잔잔하면서 모든점이 맘에 들어여 아 커피도 쥰맛탱입니다🥵👍', 70, 14, 'GOOD', SYSTIMESTAMP);
