INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '주택을 개조한 대형카페같아요!! 홍대에도 이렇게 크고 분위기있는 카페가 있다니 💖💖 커피도 맛있고 디저트도 맛있는게 가득❤️💝 산미있는 커피와 카페 분위기를 원한다면 아벨롭이 최고🤹🤹‍♂️', 41, 9, 'GOOD', SYSTIMESTAMP);
