INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '가족이랑 오랜만에 외출해서 카페 찾다가 우연히 알게 됐는데 인테리어도 예쁘고 부모님도 좋아하셨어요 ! 🩵 우선 레몬민트티 강추,,,,!!!!!', 60, 12, 'GOOD', SYSTIMESTAMP);
