INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '커다란 2층 대주택을 개조한 카페예요. 엔틱한 내부인테리어가 맘에드는데, 커피도 향이 진하고 맛있어요.  시그니처인 아벨롭 라떼 느끼하지 않고 깊은 크림맛이 인상적이네요^^', 70, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '커피가 고소하고 맛있어요! 사실 요새 카페들이 커피 맛집 찾기 너무 힘든데 원두 맛이 깊어서 좋았어요👍 디저트까지도 맛있고 카페 자체도 공간이 작지 않고 커서 꼭 추천드립니다☺️ 인테리어도 잘해놓으셔서 눈도 즐거워요 ㅎㅎ', 2, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '대형카페에서 아늑함을 찾기 조금 힘든데 여기는 넓은 매장임에도 불구하고 아늑함을 느낄 수 있어서 좋아요! 다양한 브런치와 크로플을 맛볼 수 있다는 점이 가장 좋은 것 같아요👍🏻', 0, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '2층도 있고 테라스까지 있어서 자리가 많아서 좋아요!! 시그니처 소금커피 먹었는데 비주얼도 이쁜데 크림도 꾸덕하면서 땅콩버터향이 나는데 너무 맛있어요~~~', 58, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'TERRACE');
