INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '후기가 너무 늦었지만,, 24년도 마지막 주말을 아벨롭과 함께 해서 너무 행복했어요! 근교에만 대형카페가 있는 줄 알았는데 홍대 합정 부근에 대형카페가 있다니 ㅎㅎ 그것도 주택 개조 감성으로 참 매력적이였는데요! 내부도 예쁘게 크리스마스 느낌으로 꾸며두셔서 연말 느낌 제대로 느끼고 왔어요~ 또 여기 케이크를 비롯해서 베이커리 류가 다양하게 준비되어 있고 커피와 음료도 다양하더라구요! 그래서 고민했지만 그 끝에 애플 시나몬 크로플에 아메리카노 그리고 밀크티 주문했는데 다 너무 맛있었어요! 특히 애플 시나몬 크로플 가격 값 충분히 할 만큼 양도 많고 토핑이 푸짐해서 제일 만족했어요~ 물론 케이크도 궁금하지만요! 또 올게요~', 49, 0, 'GOOD', SYSTIMESTAMP);
