INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '올 때마다 항상 친절하게 대해주시고 커피 그리고 음료 디저트까지 모두 완벽하게 맛있습니다!!! 또 날씨 풀렸을때는 밖에서도 먹을 수 있어 분위기도 좋고 너무 좋아요: )', 63, 16, 'GOOD', SYSTIMESTAMP);
