INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '회사 근처라 가끔 테이크아웃하러 들렀는데 오늘은 친구랑 시간 보내러 왔어요! 2층에 공간이 나뉘어 있어서 좋고, 특히 채광이 잘 들어오는 곳이 너무 좋아요~ 매장 음악이랑 분위기도 좋고 친절하게 응대해주셔서 더 좋았어요~ 자주 오고 싶은 곳이네요! 기본적으로 커피가 맛있네요! 근처 오시면 방문 추천해요!', 0, 2, 'GOOD', SYSTIMESTAMP);
