INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '데이트 왔는데, 평일에 와서 그런지 조용하고 넘 좋았어요! 이런 컨셉의 카페 좋네요 ㅎㅎ 크로플도 맛있었습니다 ㅎㅎ 담에 또 올게요!', 27, 8, 'GOOD', SYSTIMESTAMP);
