INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '밖이 짱 추운데 실내 넓고 따듯해요! 분위기 진짜 좋아서 데이트 하기에도 모임하기에도 좋아요!!! 디저트 섹시푸드!! 다 맛있어요 일단 넓고 공간 많아서 너무 좋았어요', 24, 7, 'GOOD', SYSTIMESTAMP);
