INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '홍대놀러왔다가 우연히 지나가는길에 들렸어요~ 2층으로 올라가니까 공간마다 인테리어가 달라서 신기하더라구요ㅎㅎㅎ예쁜 사진 많이 건졌어요^^ 대화하기 조용해서 수다떨기 좋아요 👍', 116, 26, 'GOOD', SYSTIMESTAMP);
