INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '추천으로 처음 와봤는데 분위기가 너무 좋아요! 1층 2층이라 좌석도 많네요!  빵냄새 못참아 ㅜㅜ 시그니처 아벨롭 라떼 시켜먹었습니다~ 다음에 또 올거에요 ㅜㅜ 뷰맛집', 37, 3, 'GOOD', SYSTIMESTAMP);
