INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '치즈베리크로플 진짜 맛있어요!!! 블루베리가 한가득 올려져있어서 넘 행복했답니다. 크로플 맛집 아벨롭!! 평소에 말차라떼 좋아하는데, 이 집 말차라떼 맛집이기도 하네요>_< 남자친구가 아메리카노도 맛있대요!! 그리고 카페 분위기가 넘 좋아요!! 인테리어가 엄청 예쁘답니다 꼭 방문해 보세요💖', 14, 8, 'GOOD', SYSTIMESTAMP);
