INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '좌석도 많고 맛있는 디저트도 많은 아벨롭에 친구들이랑 왔어요. 건물도 의미있는 건물이래요 다섯명도 앉을 수 있고 너무 좋아요✨ 원두도 고를 수 있어서 최고☕️', 89, 17, 'GOOD', SYSTIMESTAMP);
