INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '청첩장 주려고 친구 만나러 주말 아침에 방문했는데 대화하기 좋은 분위기에 크리스마스 분위기로 꾸며져 있어 둘다 너무 좋아했어요 데이트 할만한 곳으로도 좋을거 같아요 시오빵 맛있답니다 크림도 안달고 부드러워요', 2, 4, 'GOOD', SYSTIMESTAMP);
