INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '홍대에 몇없는 2층짜리 대형카페 아벨롭에 갔습니다. 내부 너무너무 고딕앤틱해서 예뻐요. 특이하고 맛있는 음료도 다양하고 디저트빵이나 케이크 맛있어 보여요!', 104, 24, 'GOOD', SYSTIMESTAMP);
