INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '지나가다 들어온 카페인데 분위기 좋고 좌석도 많아요!! 케이크, 빵, 크로플 같은 디저트 종류도 많고 음료 종류도 다양해서 좋네영 다만 늦게 오시면 인기메뉴는 다 팔릴수도 있어요 ㅜㅜ 담엔 일찍 와서 초코 브레드 푸딩 먹어보려구요 ! 홍대역 근처 카페 방문 시 강추합니다', 42, 8, 'GOOD', SYSTIMESTAMP);
