INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '애플 시나몬 크로플 맛있다는 리뷰 보고 왔는데 인기 있는 이유가 있네요 맛있었어요! 날씨가 추워서 따뜻한 커피 마셨는데 커피도 맛있고 분위기가 좋아서 대화하기 좋아요 창가쪽 앉았는데 채광이 너무 좋아서 사진도 👍', 32, 0, 'GOOD', SYSTIMESTAMP);
