INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '아벨롭의 커피와 분위기를 참 좋아해요. 깔끔하고 차분한 느낌이어서 커피랑 캐롯샌드위치 먹으면서 잠깐 책을 읽는 여유도 부려보곤 해요. 여긴 커플이 데이트도 많이 오더라고요.', 26, 10, 'GOOD', SYSTIMESTAMP);
