INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '홍대에 있는 카페들 중에 넓고 조용하고 대화하기 좋은 카페 찾고 있었는데 분위기도 좋고 조용하고 데이트하기 좋아요. 디저트도 맛있어요.', 49, 7, 'GOOD', SYSTIMESTAMP);
