INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '지나가다가 분위기 너무 좋아서 저장해 놓았다가 방문했는데 기대보다 좋았어요 친구들이랑 얘기하기도 좋고 생각보다 크로플 양이 많아요', 12, 2, 'GOOD', SYSTIMESTAMP);
