INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '주택을 개조한 카페라서 분위기도 독특하다고 느꼈는데 인테리어가 딱 제가 좋아하는 스타일이었어요. 마실 커피와 음료 종류도 다양하고 디저트까지 있었어 아주 알차요ㅋㅎ 좌석도 여러 가지가 있어서 좋아하는 스타일로 앉을 수 있어요ㅋㅎ', 129, 26, 'GOOD', SYSTIMESTAMP);
