INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '입구 들어오자마자 반겨주는 눈곰돌이에 기분이 좋아졌고 멋진 인테리어에 맛있는 음료까지.. 다음에 또 방문하고 싶은 곳이에요! 오늘은 배불러 빵 못먹었지만 담엔 빵도!!', 9, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '서교동에 이런 분위기좋은 카페가 있다니!☕️ 저만 빼고 다들 알고계셨는지 완전 핫플이더라구요 ! 커피 맛도 너무 좋고 분위기맛집입니닷', 41, 8, 'GOOD', SYSTIMESTAMP);
