INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '들어오기전에는 가정적인 분위기였는데 들어와보니까 인테리어도 화려하고 구조가 예뻐요! 꿀밤 케이크도 맛있고 아벨롭 커피 진짜 맛있습니다😋', 49, 7, 'GOOD', SYSTIMESTAMP);
