INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '시나몬 애플 크로플이랑 시오빵 먹었는데 둘다 너무 맛있었습니다! 애플잼도 듬뿍 얹어주시는데 너무 바삭하고 시오빵도 지금까지 먹어봤던 소금빵 중 3위 안에 들정도로 너무 맛있어요!! 디저트도 맛있는데 뷰까지 예뻐서 다음에도 또 방문할거 같아요~ (원래 귀찮아서 리뷰 잘 안 남기는데 집 와서도 생각나서 남깁니다ㅎ)', 36, 2, 'GOOD', SYSTIMESTAMP);
