INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '일요일 저녁에 갔는데 직원들이 너무 불친절했어요.  근데 일도 제대로 못하시네요 메뉴도 잘못줘놓고 맞다고 우겨서 두번 왔다갔다함 ..ㅋㅋ 일을 못할거면 친절하시던가.. 그 날 그 시간에 있던 분들 중에 사장님이 있으신거면 문제 심각 다른 사람들 리뷰에 친절하다는 직원은 전 못봤네요. 본인들이 어떤 표정으로 일하는지 꼭 알고계셔야 될 것 같아요 이런 리뷰 잘 안 쓰는데 태어나서 처음 겪는 황당함과 분노에 반성하시라고 작성합니다;;', 77, 15, 'BAD', SYSTIMESTAMP);
