INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '빵 종류도 많고, 홍대 주변 예쁜 주택 카페입니다. 주말에 데이크 코스로 딱인 느좋카페에요💫💛 추천드려요~♥  커피도 맛있습니다!', 46, 0, 'GOOD', SYSTIMESTAMP);
