INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '날이 풀려서 나왔는데. 짙은 우드 인테리어에 세련된 느낌이라 마음에 듭니다. 따뜻해지면 테라스 오고싶어요. 직원분들 친절해오.', 23, 4, 'GOOD', SYSTIMESTAMP);
