INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '카페 자체 분위기도 너무 좋고 샹들리에 보고 정말 너무 예뻐서 감탄했습니다ㅠㅠ... 친구랑 같이 잔잔하게 대화하거나 힐링하러 오시면 너무 좋을 거 같아요!!', 20, 7, 'GOOD', SYSTIMESTAMP);
