INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '내부는 단순하면서도 세련된 디자인으로 꾸며져 있으며, 각 공간마다 편안함과 실용성이 잘 조화되어 있어요! 특히 창가 자리에서 즐기는 커피 한 잔은 일상의 여유♥️', 2, 8, 'GOOD', SYSTIMESTAMP);
