INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '아벨롭 홍대본점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '크리스마스 분위기가 물씬 느껴져서 크리스마스카페로 딱이에요~ 다양한 소금빵과 케이크가 있어요. 2층 분위기가 예뻐요. 낮도 예쁘지만 밤에 분위기가 더 있을 것 같아서 다음엔 밤에 와보려구요~~', 20, 3, 'GOOD', SYSTIMESTAMP);
