INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '친구 생일케이크로 주문했는데 친구가 귀엽다고 너무 좋아했어요! 다른 브라우니케이크집 많이 생겼지만 원조는 다릅니당...🥹 레터링이 진짜 귀여워요!! 당일케이크 가능한 것도 넘 좋은 것 같아요😙🤍', 39, 7, 'GOOD', SYSTIMESTAMP);
