INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '여름이라 생크림 녹을까봐 걱정하던 찰나에 브라우니 케이크 발견 ..💗💗💗 레터링도 가능한데 귀엽기까지 해서 너무 만족스러워요 ㅠㅠㅠ 쏘 큐뚜 ..🤍 큰 틀에 벗어나지 않으면 나름?! 커스텀도 가능한것도 너무 좋아욯ㅎㅎㅎ 여름에 기념일용 또는 파티용 케이크 고민하고 계시다면 무소식으로 달려오세욧 !!!!!!', 47, 1, 'GOOD', SYSTIMESTAMP);
