INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '주문제작 브라우니 했어요 케이크보다 안흔해서 더 예쁘고 귀여운 것 같아요 🌀🌀🌀 주문제작은 인스타 디엠으로 예약했어요 !! 카페 안 분위기도 예쁘고 너무 귀여운게 딱 좋아요 🥹🥹', 18, 8, 'GOOD', SYSTIMESTAMP);
