INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '너무너무 맛있습니다 💗💗 카페 들어오시면 맛있는 냄새에 계속 있고싶어져요 // 브라우니 디자인도 너무 기엽고 주문한 그대로 나왔습니당 다음 기념일에도 또 오고싶어요 🫶🏻', 39, 5, 'GOOD', SYSTIMESTAMP);
