INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '오랜만에 혼자 카페 왔는데 만족스러워효 쿠키 귀여워서 샀는데 많이 안 달아요! 바나나 푸딩은 바나나 우유 같음~~ 무무라떼 크림라떼인데 크림도 꾸덕하고 맛있고 커피도 맛있음!!!!', 38, 10, 'GOOD', SYSTIMESTAMP);
