INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '3층에 있는 조용하고 귀여운 카페 무소식 💗 자리도 꽤 넓고 작업하기도 좋았어요! 3층이지만 올라갈 가치가 있어요. 초코라떼와 쿠키 조합은 사랑입니다 🤍 초코라떼와 모모라떼는 엄청 달달해서 당충전하기 좋아요.', 46, 2, 'GOOD', SYSTIMESTAMP);
