INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '역시 홍대에 오면 이런 힙한 카페는 와줘야합니다. 무심한듯하지만 센스 있는 디자인과 공간구성 그리고 사진을. 대충 찍어도 잘나오는 분위기 그리고 따뜻한 커피는 내공이 깊게 느껴집니다. 소개팅이나 데이트 이후 어디 갈지 모를때 이곳에 오세요. 그루브 있는 음악에 커피 한잔!!!', 31, 0, 'GOOD', SYSTIMESTAMP);
