INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '나만 알고 싶은 귀엽고 힙한 카페인데 아마 모두들 알고 있을 것 같아요,,, 왜냐면 귀여우니까ㅜㅜ🖤 귀엽기만 해도 좋은데 음료랑 디저트 모두 맛있어요~ 시그니처 쿠키인 레오, 순이 쿠키 너무 귀엽죠ㅎㅎ 까망이 레오쿠키는 진한 초코맛이고, 일반 버터쿠키인줄 알았던 순이 쿠키는 고소한 피넛버터 맛이 나서 좋았어요! 푸딩도 여러 가지 맛이 있는데 저는 말차푸딩 테이크아웃 했어요~ 맛 보고 너무 맛있어서 다음에는 다른 맛 푸딩도 맛 보고 싶어요🍮 자주 방문하고 싶은 카페 무소식 입니다🍀✨', 33, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
