INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '인스타보고 케이크가 넘 귀여워서 친구 생일기념 예약했는데요!!! 생각했던거 만큼 너무너무 귀여워요…🥹💗 솔직히 맛은 기대 안했는데 적당히 꾸덕하고 진짜 맛있었어요 요즘 레터링케이크 진짜 비싼데 가성비도 좋고 맛도있고 귀엽고 이거 외않헤..?;;;; 픽업하러 갔을때 매장도 예뿌더라구용 다음에 다른 디저트도 먹으러 올게요~~~!!!!', 20, 0, 'GOOD', SYSTIMESTAMP);
