INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '친구랑 만나기 전 시간이 남아서 찾아갔는데 쿠키가 넘넘 귀엽고 지이이인짜 맛있었어요ㅠㅠ 친구들 주는 것도 두 장씩 포장했었는데 제가 먹을 것도 사갈걸 후회 중입니다..ㅎㅎ 너무 부드럽지 않고 너무 딱딱하지 않고 적당하고 좋았습니다! 혼자서도 충분히 올 수 있는 분위기여서 좋았지만 다음은 남자친구랑도 오고 싶어요 :)', 42, 4, 'GOOD', SYSTIMESTAMP);
