INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '쿠키가 너무 귀여워요. 💦 매장도 깔끔하고 친절하셔서 재방문 의사 있습니다! 홍대 입구역에서 걸어오기엔 거리가 있어서, 지하철 이용시 합정역에서 내리시는 걸 추천해요.', 1, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '초코라떼 (& 강아지 라떼아트)•레트로베리티•바나나푸딩 먹었어요!! 무소식은 좌석 간 간격도 넓고 바깥의 풍경도 푸릇푸릇해서 🌳 언제 와도 쾌적하고 좋은 것 같아요 ,,, 푸딩 종류는 처음 먹어보았는데 쿠키만큼 맛있고 조았습니다 👍🏻', 41, 5, 'GOOD', SYSTIMESTAMP);
