INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '멜론소다 넘 좋아해서 먹으러왔습니당 초코케이크랑 바나나푸딩이 너무 맛있어용 노래 선곡도 좋고 의자도 편해요! 숨겨진 아지트 같은 느낌…★', 29, 0, 'GOOD', SYSTIMESTAMP);
