INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '커피가…커피가 너무 마싯어요사장님… 사실 귀욤둥이 쿠키를 위해 달려왔지만 솔드아웃이슈로 🥹🥹 커피만 마셨는데 원두가 너무..너무좋아요!!!! 둥가둥가 너무 칭찬해주고 싶은 커피예요..🤤 다음엔 꼭 쿠키를!!!! 바나나 푸딩도 크림에 바닐라 향이 진해서 바나나랑 너무 잘어울렸어요🤍', 47, 8, 'GOOD', SYSTIMESTAMP);
