INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '정말 너무 오고 싶던 카페였는데 이렇게 오게되서 너무 좋아요 💓 인스타에서 봤던거 처럼 인테리어가 너무 멋지고 20대들한테 굉장히 인기 있을 장소입니다 ! 시그니처 쿠키 먹고싶었는데 품절이라 아쉬웠어요.. 다음에 또 와서 꼭 먹어볼려고요 :)', 38, 3, 'GOOD', SYSTIMESTAMP);
