INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '쿠키랑 라떼가 넘 귀여워서 왔는데 쿠키는 늦게갔더니 품절이라 아쉬웠지만 라떼 넘 기엽고마싯서요~~~~ 혼자 잘 놀다갑미다 내부 넓고 생각보다 힙함 글고 충전기 콘센트가 여러곳에 있어서 좋아야', 0, 9, 'GOOD', SYSTIMESTAMP);
