INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '출입구에서 잠시 주춤하면서 들어가게 되는 곳 입구가 꽤나 찾기 힘들고 맞나 하는 생각이 들음 귀여운 쿠키 모양을 보고선 바로 달려감 마포 힙쟁이들 성지인듯 어떻게 알고 오시는지... 쿠키맛은 무난한 맛인데 특별히 뛰어난 맛은 없음 귀여움으로 먹는 맛 커피도 무난 메론소다도 무난 양이 마음에 들음', 27, 1, NULL, SYSTIMESTAMP);
