INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '주말에 와도 너무 붐비거나 시끄럽지 않았어요. 콘센트도 있고 의자가 편해서 작업하기 좋아요. 3층이라 채광도 좋고 넓어서 공간이 트인 느낌입니다:)', 4, 4, 'GOOD', SYSTIMESTAMP);
