INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '메론소다 처음 먹어봤는데, 모양도 예쁘고 맛있어요💚 처음엔 바닐라 아이스크림 퍼먹는 재미~ 나중엔 아이스크림이 일부 녹으면서 소다랑 만나 메로나맛이 나더라구요! 완전 제 취향🫶 남편은 치즈케이크가 진한 치즈맛에 꾸덕하다고 좋아하고, 저는 촉촉하고 부드러운 딸기케이크에 반했어요😍 딸기도 듬뿍 들어가 있는데 크림은 일반 생크림이 아닌가봐요! 입안에서 살살 녹아요👅 사장님도 친절하시구, 새해 첫날 아직 떠나보내지 못한 크리스마스 트리 너무 예뻐서 사진 남겨용🎄🌲🎄🌲', 82, 16, 'GOOD', SYSTIMESTAMP);
