INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '치즈 케이크가 너므 맛있어요 三 _( ◜◡‾)ﾉ 크리스마스 시즌이라 귀여운 트리도 있고 사장님표 플레이리스트까지 분위기 완벽. (♡)', 48, 1, 'GOOD', SYSTIMESTAMP);
