INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '홍대 상마 근처에 무소식만큼 넓고 쾌적하고 조은 카페 없는 느낌 ... 🥹🤍☕️ 쿠키도 귀엽고 커피는 맛있고 공간은 예쁘고 ♡', 21, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '라떼도 맛있고 쿠키도 넘 기여워요… 🐾 홍대 근처에서 여유롭게 집중하기 좋은 카페 찾기 힘들었는데 무소식을 알게 되어 넘 좋네요! 🖤', 31, 4, 'GOOD', SYSTIMESTAMP);
