INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '메론소다가 너어어무 먹고싶어서 엄선해서 온 무소식! 완전 무채색의 매장인테리어에 쨍한 메론소다가 일단 이뻐서 흡-족 ㅋㅋ 그리고 귀여워서 레오 쿠키도 하나 시켰다...쫀귕.. 메론소다는 역시 일본의 그 탄산감을 따라갈순 없지만 아이스크림도 섞이니 무난하게 맛있었다 레오는 아주 하찮고 귀여운게 먹기 넘 미안했지만...하면서 냅다리 귀떼어먹기ㅋㅋㅋㅋㅋ 먹혀도 귀엽구나 레오야ㅠㅠ 쿠키는 딱 상상했던 버터초코쿠키 고맛이었다 전체적으로 무난했고 노래크기가 좀 컸다..? 고런 조금의 아쉬움이 있지만 메론소다 먹고싶으면 가끔 생각날것같다 ㅎㅎ', 67, 11, 'GOOD', SYSTIMESTAMP);
