INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '커피랑 디저트가 너무 맛있고 분위기도 인서타 올리기 딱 좋은 분위기의 감성 충만한 카페예요😀 힙한 노래도 많이 알아갑니다👍🏻 아 그리고 사장님도 친절하십니다 완전 인싸 재질이심🙏🏻  제가 홍대 안 살아서 아쉽네요 ㅠㅠ 홍대 살았음 맨날 왔다..', 21, 1, 'GOOD', SYSTIMESTAMP);
