INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '자리 없을까봐 걱정했는데 사람두 별로 없고 시원해서 좋았어요..💙 순이쿠키 너무 귀여워서 주문해봤어요🐶 카페가 전체적으로 무채색 톤에 조금씩 포인트있는 인테리어가 좋았습니다!!', 14, 8, 'GOOD', SYSTIMESTAMP);
