INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '힙스러운 공간의 카페에요. 귀여운 강아지와 고양이얼굴의 쿠키를 팔구요 디저트들이 맛있습니다! 채광도 좋고 셀카도 잘나와서 재방문의사가 높은 카페에요!', 32, 6, 'GOOD', SYSTIMESTAMP);
