INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '플랫화이트가 바보 같아요 쿠키가 대두에요 매장이 귀여워요 ♥ ... 사진도 잘 나오구용 주말이나 붐비는 시간대 이후에는 쿠키가 솔드아웃인 경우나 자리가 없는 경우가 꽤 있드라구요 ?... 이 점 고려하시면 좋을 듯!', 115, 23, NULL, SYSTIMESTAMP);
