INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '무채색 인테리어라 분위기가 너무 좋았고 딸기케이크에 딸기도 듬뿍 들어가있어서 너무 맛있었어요!! 초코케이크도 부드러우면서 달달하니 맛있었고 커피고 고소하고 진해서 디저트랑 같이 먹었을 때 맛조합이 꿀이였어요! 항상 올 때마다 손님이 엄청 많은데 운좋게 한 자리 남아서 겨우 앉았는데 앉자마자 그 뒤로 웨이팅이 줄줄...찾기도쉽고 일단 시끄러운 분위기가 아니라서 좋았고 사장님들도 매번 친절하게 맞아주셔서 감사했어용 ᰔ 더 자주 갈께요 ♡ ♡ ♡', 12, 9, 'GOOD', SYSTIMESTAMP);
