INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '사장님이 친절하시고 카페 인테리어가 너무 귀여웠아요ㅜㅜ 어디서 찍어도 사진이 잘나와요 케이크도 맛있어요🤤👍 선물용 쿠키만 사러갔다가 카페 분위기가 너무 좋아서 커피마시러 다시 갔어요 쿠키도 넘 귀엽', 110, 24, 'GOOD', SYSTIMESTAMP);
