INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '3층이라서 강제운동시켜주는 카페..! 그래도 인테리어 멋지구나 디저트 다 맛있구 음료도 다 맛나서 좋아요! 요즘은 늦게 가면 순이는 매진이더라구요… 그래도 종종 레오라도 구매하면… 그렇게 행복할 수가 없습니다', 37, 1, 'GOOD', SYSTIMESTAMP);
