INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '막상 홍대 오면 예쁜 카페 찾으려면 연남동 넘어가야해서 너무 귀찮았는데 이렇게 가까운 곳에 이쁜 카페가 생겨서너무 좋아요 ㅠㅠ 홍대 오면 맨날 여기만 가요 ㅎㅎ 커피랑 디저트도 너무 막있고 인스타 갬성샷 찍으러 와도 될듯. ㅎ ㅎ', 43, 6, 'GOOD', SYSTIMESTAMP);
