INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '순이와 레오 쿠키가 있다? = 방문 이유 충분 특별한 맛은 아니지만 맛있어요!!! 게다가 비주얼이 존재가치 다 하는 걸!!! 케이크 종류도 있는데 혼자 가서 배부를까봐 못 먹었어요ㅠ 케이크도 맛나다는데 담에는 친구랑 가서 케이크랑 쿠키 둘다 먹을게요!!! 인테리어는 깔끔하고 도시남자 스타일…☆ 킹치만…카페가 3층이나 건… 디저트를 오래 먹고 건강하기 위해 조금이라도 운동하라는 설계이신걸까요… 사장님도 친절하시구 순이와 레오를 손수 하나하나 만드시는게 멋있고… 귀여우십니다…', 14, 1, 'GOOD', SYSTIMESTAMP);
