INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '홍대 한복판에 이런 카페가 있다니..💗 완전 힙하고 멋있구 음료도 맛있고 디저트도 존맛이에용>.< 토마토바질 첨 먹어보는데 개도른맛...👍✨ 분위기 너무 좋아욤,,,✨✨✨', 70, 14, 'GOOD', SYSTIMESTAMP);
