INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '너무 귀여워...원래 이런 분위기 카페는 디저트 별로 기대 안 하는데 초코케이크 진하고 너무 내 취향이였다.. 다음에 또 오고싶음💗', 10, 3, 'GOOD', SYSTIMESTAMP);
