INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '바닐라빈라떼 바질토마토에이드 맛있어요 치즈케이크 초코케이쿠도 맛있음! 특히 치즈케이크 존맛 무슨애플 바닐라 어쩌구는 그냥쏘쏘!', 84, 14, 'GOOD', SYSTIMESTAMP);
