INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '새로 오픈한 카페라서 다녀왔는데 너무너무 좋았어요~! 위치도 홍대랑 상수역 중간 지점에 있어서 다른 곳에서 놀다가 가기에도 넘 좋아요! 그리고 무엇보다 메뉴가 너무 독특하고 맛있어요 . 바질토마토에이드 두번 세번 드세요... 태어나서 처음 먹어보는 맛이었습니다...존마탱🍅 다른 카페에는 없는 메뉴도 많고 음료도 너무 맛있고 케이크도 너무 맛있어서 먹으면서 계속 주문했습니다ㅠㅠ  카페 제대로 뿌시고 왔네요😂 카페 분위기도 좋고 통창이라 햇빛도 잘 들어오고 선곡도 너무 좋아서 오랜만에 넘 맘에 드는 카페 찾았네용ㅎㅎ 자주 갈거같아요 👍🏻', 3, 9, 'GOOD', SYSTIMESTAMP);
