INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '무소식'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '아들이랑 카페데이트 하고 왔어요 🖤 인테리어도 깔끔하고 넓어서 아이와 가기 좋았어요 ! 무엇보다 아들래미가 초코케이크를 너무 맛있다며 허겁지겁 밥퍼먹듯 먹었어요 ㅋㅋㅋㅋㅋ 토마토바질에이드 이름만 보고 거르면 안돼는 맛입니다 ! 진짜 맛있고 시원하고 여름에 제격이에오 ! ㅋㅋㅋㅋ 단짠 단짠 솔트아인슈페너도 맛있었어요~ 크림 아낌없이 부어주셔서 개인적으로 너무 좋았어요 ㅋㅋㅋㅋ 다음엔 여유롭게 아들래미 놓고 가야겠네요 🤪', 15, 8, 'GOOD', SYSTIMESTAMP);
