INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 합정중앙점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '합정빕스 저녁먹으러 걸어가는데 중간에 BYD 근처에 딱 있네요! 9월이지만 여전히 더워서 시원한 아아 샀어요. 메가커피는 늘 동겅에서 잘 발견되어서 좋아요! 친절하시고 커피도 맛있네요^^', 35, 7, 'GOOD', SYSTIMESTAMP);
