INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 합정중앙점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '자주. 왕메가카페라떼를 자주 마시는데요. 여기 합정중앙점은 좀 이상한거같습니다. 제가알고있기로는 .에스프레소  3샷또는 4샷 으로 알고있는데요.  1리터 대용량이니까 음료 제조하는거 지켜봤는데.  에스프레소 1번만 넣어주더라고요.  1번이 1샷인지 2샷인지 3샷인지4샷인지  몇샷인지??? 커피 글라인딩1번해서. 1리터나 되는 커피에.  제가알고있는 카페인함량이 400인데.  흐리멍텅해서.  커피맛이 안나요. 제조와 다르게 하니까.  맛이없어지고. 손님이 빌길을 끊게 되는듯합니다.', 43, 0, 'BAD', SYSTIMESTAMP);
