INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 합정중앙점'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '합정에 스케줄이 있어 가던도중에 보여서 들렀는데 케잌이랑 차가 정말 잘어울리고 맛있었어요 특히 저당 생크림 케잌 완전 취향이에요', 8, 2, 'GOOD', SYSTIMESTAMP);
