INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 합정중앙점'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '평일 오후 통통한 알바생 성격 더러움. 주문실수하고 끝까지 사과 한마디 안하고 음료 더 늦게 만들어주길래 왜 그러냐고 그랬더니 대놓고 쌩깜 ㅋㅋㅋㅋ 이렇게 4가지없는 알바생 첨 보았다 자영업하는 사장님들이나 같이 알바하시는분들 진~짜 힘드시겠다', 340, 50, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 합정중앙점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '메가에세 젤 좋아하는 딸기 쿠키 프라페를 이렇게 기분 나쁘고 맛없게 먹을줄이야! 맛은 둘째치고 프라페 인데 얼음이 제대로 갈리지 않아서 잔얼음 잔치~딸기맛도 제대로 나지 않고 맹물에 섞인 휘핑크림맛만 나고 문제는 잔얼음을 깨서 씹어 먹느라 처음에는 몇모금은 그러려니 했는데 결국 끝까지 얼음 대사태 이왕 먹었으니 먹자 하면서도 이번주에 딸기 쿠키 프라페만 4잔째 마시는데 합정중앙점은 정말 환불 받고 싶네요ㅠㅠ 손님들이 많이 없어서 그런건지 두세분 직원분들끼리 잼나게 수다중 이셔서 다시 만들어 달라고 하기에도 그렇고 테이크아웃도 아닌데 내부 키오스크에 대기자가 주문중 이길래 계산대에서 주문 가능하냐고 했더니 굳이 다시 밖으로 나가서 키오스크 이용하라는건 손님이 많은것도 아니고 주문이 밀린것도 아니고 돈아깝네요', 27, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 합정중앙점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '출근할 때 여기서 라떼를 자주 사먹는데 오늘은 유난히 커피가 받자마자 식어있었어요ㅠ 라떼 단체 주문 이후 받은 주문이라 그런건지.. 다음에는 평소처럼 따뜻하게 나왔으면 좋겠습니다ㅠ 아침에 출근한다고 바빠서 따로 요청은 못드렸어요.', 74, 11, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 합정중앙점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '미리 가지 마세요 기분 나쁜일 생깁니다 7시28분이다 7시30분부터라고 문은 열어놓고 들어와서 기다린다고 나가랜다 아침부터 이 불쾌한일인지 알바인지 주인인지 그저 영업과 서비스의 자세가 안된점에 한탄이 위치덕에 잘되니까 친절할 필요까지는 없는건가', 61, 18, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 합정중앙점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '라떼가 너무 맛없어요. 탄 맛 쓴 맛 너무 강하게 났고요, 우유+물+에스프레소 맛이었어요. 맹맹하고도 탄 맛ㅜㅜ 라떼 특유의 고소함은 도대체 어디로 갔는지? 보통 프랜차이즈 라떼 맛은 다 비슷비슷 무난했는데, 이 지점 라떼는 진짜 제가 먹어본 라떼중에 제일 맛이없없어요 …. 화요일 오후 6:40 쯤 이었는데 이 타임엔… 앞으로 갈 일 없을 것 같아요…', 1, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 합정중앙점'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '항상 애용하고 있는 곳인데 처음으로 리뷰 남겨봐요 늘 사람이 많은데 빠르게 메뉴가 나와서 좋더라구요 직원분들이 다 친절해서 더 자주 찾게 되네요 늘 좋은 서비스를 받는것 같아서 리뷰를 쓰고싶었어요 프랜차이즈이지만 내적친밀감이 생긴 느낌ㅋㅋ 마침 영수증을 안버려서 ㅎㅎ 쓰게 되었네요 2024년에도 자주 갈게요~', 40, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 합정중앙점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '가성비좋은 메가커피에서 이번 겨울시즌으로 나온 음료와 간식세트 먹어봤는데요 특히 따끈따끈 간식꾸러미가 다양한 간식으로 음료와 함께하기 좋았어요', 73, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 합정중앙점'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '결혼식장 갔다가 뒷풀이겸해서 카페 왔어요~ 테이블이 적지 않는 카페입니다!ㅎ 매장에 사람이 많아서 답답하거나 자리가 없다면 옆에 파리바게트 방문 추천이요^^ 2층이라 넓더라구요~', 63, 13, NULL, SYSTIMESTAMP);
