INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 합정중앙점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '이날 아이스크림이 없었는지 얼린 우유가 올라가 있는것 같았어요… 서걱 서걱하고… 아이스크림은 아니였답니다…?? 그래서 그런지 달달하라고 시럽 많이 뿌려주신것 같은데 .. 그래서 괜찮게 먹긴했는데 그래도 재료가 없어서 안 될것 같으면 미리 말해주셨으면 좋았을 것 같아요…. 사진은 우유상태를 찍으려고 해서 저모양인것이고 원래는 예쁘게 잘 나왓답니다!!!!', 124, 23, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 합정중앙점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '초코쿠키 프라페위에 휘핑대신 아이스크림으로 변경했는데 저희아이기 맛있다고 하네요. 라떼에 얼음 빼달라고 늦게 요청했음에도 친절하게 응해주셔서 넘 감사드렸어요..', 39, 1, 'GOOD', SYSTIMESTAMP);
