INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 합정중앙점'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '안에서 마신 적은 없지만, 생각보다 좌석이 많아서 음료 나올 때까지 대기하기 좋아요. 키오스크도 안팎으로 있어서 주문하기도 편해요.', 114, 21, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 합정중앙점'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '이날 빵이 너무 눅눅했어요… 원래 메가는 따뜻 바삭한 빵과 시원한 아이스크림 조합으로 맛있었는데 이날은 밀가루맛….?? 안 익은 것 같은 그런 …맛 …', 8, 10, 'BAD', SYSTIMESTAMP);
