INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 합정중앙점'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '매장은 생각보다 넓었어요.. 지나만 다녔는데.. 화장실은 밖으로 나가서 건물로 들어가는데, 뭔가 휑하니 밤에 혼자는 무섭네요 ㄷㄷㄷ 근데 아직 문닫을시간도 아니고, 손님이 있는데 바닥쓸고 주방에선 우당탕탕 난리더라구요~ 청소후에도 막 손님들 들어오고..  결국 또 청소를 해야했겠죠? 꼭 했기를..', 18, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 합정중앙점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '대용량 아메리카노를 여기 프랜차이즈만 판매해서 두달에 한번쯤 이용해요 커피 중독이라 달달한커피 아니면 다 좋아해서 또 마시고 싶어요 특히 더운날에요', 11, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 합정중앙점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '맛있긴 한데,, 7시 정각에 시킨 음료와 허니브레드가 7시 30분에 나왔어요 ㅠㅠㅠㅠㅠ 너무 당황했지만 직원 분이 친절하셨고 크림도 많이 올려 주셔서 만족스러웠습니다. 저녁에 주문이 많은 매장이라 시간 여유 두고 주문하시길 추천 드려요! ^^', 18, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 합정중앙점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '오후 1시쯤에 가서 콘치즈샌드위치인가 시켰는데 해동 안된상태로 주셨더라구요. 말할까 했는데 그냥 먹었어요ㅋㅋ 딸기쨤이 얼어서 이 시려웠음...', 66, 15, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 합정중앙점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '맛있긴한데 샌드위치가 속이 덜 해동되어 나와서 아쉬워요 ㅠㅠ 아이스크림 느낌? 그래도 2천원대임을 감안하면 괜찮습니다. 생크림카스테라도 가성비 좋고, 역시 메가커피는 가격대비 좋은 것 같습니다~!', 35, 8, 'GOOD', SYSTIMESTAMP);
