INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 합정중앙점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '홍대입구역 2출 근처에 있는 곳인데 다른 메가커피는 대기가 겁내 긴데 여기는 괜찮은 편이에요ㅠㅠ 음료도 빨리 나와서 넘 조아요!!', 55, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더 누크'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '선선하게 기분 좋은 날엔...☁️ 공간도 넓고 작업하기도 대화나누기도 좋아요! 슈크림 넘 맛있어서 순식간에 호로롭해버렸네요😳😆 (다 마시고서야 사진이 생각난..) 비오는 날은 좀 아쉽지만, 오늘 같은 선선한 날엔 기분좋은 노래 틀어놓고 야외테라스에 있는 것도 기분도 상쾌지는 것같아서 환기가 되서 좋네요ㅎㅎ', 36, 0, 'GOOD', SYSTIMESTAMP);
