INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더 누크'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '아포가토 맛있어 보여서 시켰는데 맛있어요!!! 매장도 넓고 쾌적해서 좋았습니다:) 사장님들도 친절하시구 좋네요:) 맛있는 음료 감사합니다!!', 3, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더 누크'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '제가 아침에 방문했는데 광교&홍보촬영하는날 이라고 하더라구요! 1층부터 2층 과 테라스까지 통으로 카페로 되어있는데요 인테리어를 각각 다르게 해놓아서 다른느낌을 갖을수있는 카페였고, 셋트메뉴에서 배를 채운다는것보다는 간식정도로 생각하면 좋을것 같아요! 직원분이 너무 친절하셔서 사장님인줄 알았습니다^^', 24, 0, NULL, SYSTIMESTAMP);
