INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더 누크'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '사진못찍어서 아쉬운데 아이스크림 크로플 너무 맛있음요!! 바삭한데 고소하면서 바닐라아이스크림 조합까지 담에도 가면 또 먹으려구용', 11, 5, 'GOOD', SYSTIMESTAMP);
