INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더 누크'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '더누크 카페에 오니 자리도 넓고 대화나누기 좋은것 같아요! 쾌적한 환경이라 자주 와서 대화도 나누고 모임도 해도 괜찮을것 같아서 담에 또 방문 예정이에요 :)', 13, 10, 'GOOD', SYSTIMESTAMP);
