INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더 누크'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '젤라또 아이스크림 맛있어요😊😊 주문 후 나오는 데 다소 오래 걸리긴 했지만....^-^ 콘 과자를 얹어주시는 줄 알았는데 쫀득한 마시멜로라서 반전 매력💕 공간이 나뉘어 있는데, 이 날 날씨가 워낙 좋아서 활짝 열린 통창 뷰 테이블 앉았어요. 분위기 넘 좋음 !!', 43, 4, 'GOOD', SYSTIMESTAMP);
