INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더 누크'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '2층까지 넓은 매장, 비번 없는 와이파이, 6인석 자리, 키오스크 주문, 분리된 세 공간으로 오래 머무르기 눈치 안보이고 좋습니다~ 음료가 맛있진 않지만 평범한 맛이예요~! 화장실 2층에 있고 깔끔한 편입니다.', 27, 5, NULL, SYSTIMESTAMP);
