INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더 누크'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '여자 알바생 3분..? 사장님도 계신진 모르겠는데 너무 시끄럽고 웃는 소리가 노래소리보다 커서 상대와 대화할 때 좀 거슬리는 면이 있었습니다 .. 그리고 햄버거가 냉동인 것 같은데 다 데워지지도 않은 상태로 나왔어요 음식 픽업 받는데 바로 또 자기들끼리 웃고 ..ㅠ 손님들이 그러면 그러려니 하는데 일하시는 분들끼리 도가 지나치시니깐 이건 카페가 아니라 그냥 놀이터 온 줄 알았어요', 65, 14, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '더 누크'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '커피가 맛나네요~!!  가오픈기간 이벤트로 빵을 서비스로 주시는데 맛나요 2층 인테리어 끝나면 넓고 쾌적한 곳이라 자주 갈 것 같아요!', 13, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 동교점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '더운 낮시간대 사람이 엄청 많았는데 직원은 한 명. 하지만 요청사항도 척척 빠르게 준비해주시니 참 감사한 마음이 들 정도였는데 너무 바쁘고 복잡해서 인사도 못한게 아쉬워 리뷰남기네요ㅎㅎ 고마웠어요 깔끔하게 적당히 친절하면서도 빠릿빠릿 하고 성실함이 멋져보였습니다!', 16, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 동교점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '홍대를 지나가는 메가러버님들아아아아!! 다같이 혼쭐내쥬자아아!! 동교 점장님을 #내돈내산 #돈쭐 내 주세요 제바알! 오늘 낮부터 밤까지 종일.. 인천. 부평. 월미도. 영정도. 홍대. 합정. 연남. 연희. 아현……. 매장 일일이 전화 돌리고 부탁했는데 “재고소진” 이라는 멘트로 정말 저녁 9시 다 되도록 팥빙프라페… 뺀 먹음… 희망 0.0000001% 없이 그냥 지나다 전화함 종일 근무와 서비스로 지친 듯 한 남성 직원분의 매우 상냥하규 친절하규 정중하신 목소리.. 매장 오시면 주문 가능하다 하심… 아니 그 힙하고 사람 많이 왕래하는 동교점에…?? 주문하다 실수도..  정말 혼자 1인 응대하셔도 단 1초의 찌푸림도 없이 프로패셔널하게 응대해주셔서 인사 드리고 보니 점장님.!! 감사합니다ㅠ', 43, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 동교점'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '카페가 커서 오랬동안 머물면서 이야기하기 좋아요! 좌석마다 콘센트도 있고 키오스크로 편리하게 주문 가능합니다! 큐브라떼 시켰는데 일반 라떼보단 좀 달달하네요. 딸기 요정 핑크 츄러스는 너무 물컹물컹해서 별로였어요ㅜ 나오는데도 20분 가까이 걸렸어요', 3, 8, NULL, SYSTIMESTAMP);
