INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 동교점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '키오스크가 켜져있어서 마감인줄 모르고 결제했는데 너무 친절하시게도 음료만들어 주셨어요ㅠㅠ 결제취소하셔도됐을텐데 마감 후인지모르고 결제하게되었는데 빨리 퇴근하고싶으셨을텐데도 커피 내려주셔서 진짜 감사합니다 ㅠㅠ 성함을 알았으면 칭찬글이라도 올리고싶은데 아쉽게 성함을 몰라서 월요일 10시 50분경이었습니다! 감사합니다👍', 0, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 동교점'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '저녁시간에는 매장이 매우 바쁘다보니, 분위기는 별로였어요. 포장으로 들고 나가는게 좋습니다. 키오스크 주문하나, 주문이 많으면 오래 기다릴수 있어요', 20, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 동교점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '허니브래드 시켰는데 빵이 딱딱하고 차갑다고하니깐 죄송하다는말도없이 쫌 싫은 내색으로  데워주시네요 ;; 그럼 진작에 잘 구워주시기..', 42, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 동교점'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '점심 먹고 대화하려고 방문했는데 음료 가격도 착하고 매장이 넓어서 좋아요. 직원분들 모두 친절해서 주문하고 음료 받아서 마시는 데 불편함이 없어요. 아침에도 한번씩 방문하는데 직원분 모두 신속 친절 최고입니다! 덕분에 지각 안하고 오전에 모닝커피 마시고 있어요ㅎㅎㅎ', 50, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 동교점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '커피가 진짜 맛있어요~ 직원분께서도 너무 친절하십니다~ 사장님 그런데 왜 패스오더 앱에서 전화로만 주문이 가능한가요? 너무너무 불편해요 정말.. 앱으로 미리 주문할 수 있는 기능도 오픈해주세요!', 14, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 동교점'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '편하게 앉아서 얘기할 수 있는 소파 좌석은 물론이고 노트북 할 수 있는 콘센트 테이블도 있었던 공간을 잘쓴 매장 아아메+마카롱 4,100원이라 가성비도 좋아요', 75, 15, 'GOOD', SYSTIMESTAMP);
