INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 동교점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '포장시 천원 할인이라고 하지만 이미 메뉴판 가격과 동일합니다. 실은 그가격은 다른 매장과 같은 가격입니다;; 그냥 매장에 먹으면 천원 더 받는다. 라고 하시는게 혼선을 줄일거 같네요.', 19, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 동교점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '19일 오후 아홉시 넘어서 음료 주문했는데 매장에 계시던 여자직원분이 휘핑크림 관련해서 여쭤봤더니 음료 만들어주시다가도 친절하게 메뉴 설명해주시고 메뉴 바꿀 수 있도록 결제도 다시 해주시고 헷갈리지 않게 음료도 구분해주셔서 넘넘 감사하고 기뻤어요 💗메가 짱', 33, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 동교점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '처음 배우시는 것 같은 분들이 해주셔서 오래걸린건 이해했는데요...죠리퐁 들어간 플레인 퐁크러쉬를 샀지만.. 허니퐁트로쉬에 들어가는 죠리퐁이 들어가서 다 남겼어요.. 신경써주시길 부탁드립니다..ㅠㅠ 연습 많이 해주세요', 23, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 동교점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '장소가 넓어서 좋습니다. 케이크와 아이스아메리카노가 잘 어울립니다. 여럿이 온 손님들이 너무 큰목소리로 떠들어서 조용히 차를 마시고 싶은 마음에 속상하네요.', 6, 7, NULL, SYSTIMESTAMP);
