INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 동교점'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '체인이라 해도 일하는 사람에 누구냐에 따라 다른 듯... 음료 한잔을 던지듯 놔주셔서 뚜껑밖으로 음료가...   ㅡ..ㅡ; 나는 음료를 줬으니 알아서 휴지로 처리 하란건가요... 날씨가 더운데 일하시는 분들도 힘들겠지란 생각으로 그냥 조용히 왔지만... 그냥 담부턴 방문하지 않을 듯...', 30, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '메가MGC커피 동교점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '직원 6명이 카운터에서 북적이는데 아아 하나 테이크아웃 받는데 10분 기다림... 수다만 떨고있고 너무 느리네요. 기다리는 사람 생각 좀 합시다', 4, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '동물성 생크림이라 산뜻하고 하나도 안느끼해서 그냥 계속 먹게 되는 홍대 푸하하 크림빵🥹 고민하다 6가지 맛 전부 포장해왔는데, 전 소금 크림맛이 제일 맛있었어요😋 일본 여행 후, 말차에 푹 빠진 남자친구는 말차맛이 진짜 일본 현지맛 같다고 인정👍🏻 살짝 씁쓸한 끝맛이 좋다고 합니다ㅎㅎㅎ 더 자세한 정보와 솔직한 후기는 ''다잇어터'' 블로그 한번 방문해주세요💛', 60, 14, 'GOOD', SYSTIMESTAMP);
