INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '우리 아빠가 좋아하는 크림빵🧁 리얼딸기크림빵! 속에 완전 크림 가아득:) 생활의 달인에 나왔었대요!! 매장이 엄청 조그만한데 그래서 더더 좋아용ㅎㅎ 친절하게 봉투에도 담아주셨어요~ 담엔 딴 맛 도전🫶', 28, 10, 'GOOD', SYSTIMESTAMP);
