INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '홀린듯 세개를 다먹었어요. 사이즈는 그렇게크진않아서 혼자서 3개먹기 가능합니다!!! 개인적으로 리얼딸기강추하고요 딸기 덜단팥 말차팥 요렇게 세개는 필수에요😆', 13, 10, 'GOOD', SYSTIMESTAMP);
