INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '푸하하 크림빵은 빵도 부들부들 크림도 듬뿍 들었는데 하나도 느끼하지 않고 깔끔하고 부드러워 정말 좋아하는 연남 디저트 맛집이에요! 종류도 다양한데 뭐 하나 맛없는 맛이 없어요ㅎㅎ 말차도 진짜 맛있고 팥 들어간 것도 정말 맛있어요!!!', 15, 8, 'GOOD', SYSTIMESTAMP);
