INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '푸하하 크림빵의 빵은 크림을 담기위한 도구랄까? 진짜 크림을 아낌없이 넣어줍니다♡  1시간 이상의 거리라면 500원 추가해서 보냉포장도 가능해요. 가격이 참 합리적인것 같아요!!', 2, 5, 'GOOD', SYSTIMESTAMP);
