INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '하도 유명해서 꼭 가봐야지 하고 있다가 드뎌 가봤어요! 제주 말차 크림빵 크림이 가득 들어가있더라구요 👍 디저트 카페나 빵가게에서 비싸게 파는데 이 정도면 적당한 가격인 것 같아요~', 9, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '많이 달지않고 크림이 듬뿍 들어있어 맛있어요 다만, 빵이 너무 맛없.. 혜자스런 크림을 빵이 다 갉아먹는 느낌이랄까.. 저렴한 빵맛이 나요 빵을 좀더 보완하면 좋을것 같아요', 40, 6, NULL, SYSTIMESTAMP);
