INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '저는 원래 크림류 빵을 별로 좋아하는 사람이 아닌데요, 이 곳만큼은 너무 맛있어서 부디 사라지지 않길 바라는 가게입니다. 한 입 하자마자 정말 신선하고 시원하고 맛있는 크림이 팡 터지면서 입 안을 즐거움으로 채워줍니다. 세트 2개를 사서 집으로 들고가서 먹었구요, 아주 맛있게 먹었습니다.  거의 모든 종류 맛을 다 먹어봤는데, 저는 개인적으로 푸하하크림빵 기본 소금크림빵 맛이 가장 맛있었습니다! 냉장보관 3일, 냉동보관 7일 의 기간을 가진다고 합니다. 강추합니다! 꼭 오래 오래 장사해주세요~', 26, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '직장동료들이 추천하길래 주변에 간 김에 들렀는데 정말 맛있었어요!! 걸어가면서 먹었는데 금세 다 먹었어요 다음에 또 먹어보고싶어요😋', 70, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '크림빵이 유명하다고 해서 방문했는데 맛있네요^^ 소금크림빵은 짭쪼름하면서 우유크림이 고소 담백하고 말차크림빵은 말차 맛이 찐하네요 크림빵 맛집 인정👍', 0, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '크림빵이 먹고 싶어 구매해봤어요🐰🩷 저는 얼려둔 뒤에 에프에 돌려먹는 방법이 제일 맛있었어요! 겉은 바삭따뜻하지만 크림이 아이스크림처람 부드럽게 얼려져있어 최고랍니다..🥹', 43, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '느끼함 없고 모든 크림빵이 산뜻. 빵은 폭신. 소금크림이랑 리얼딸기는 꼭 드세요 빵 정말 부드럽고 폭신한데다가 소금크림은 꼭 구름먹는 듯한 촉촉 부드러움이 더해져서 식감 최강이예요 짭짤한 건 빵 아랫부분에서 잘 느껴지고 크림은 특제 비법이라 그런지 고소함&우유 맛이 유독 나요 리얼딸기는 딸기의 특징 중 상큼한 맛을 부각시킨 맛이예요 말차는 진하고 단팥은 통단팥에 호두가 오독오독 좋은 재료들로 만들은 게 먹어보면 알겠더라구요', 100, 20, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '크림이 많이 들어가고 빵결은 부들부들한 맛있는 빵이었어요. 사자마자 바로 먹다시피한 소금크림빵은 정말 푸하하 할 맛이었는데 냉장고에 잠시 들어갔다 나온 애들은 ㅠㅠ', 20, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '소금크림 하나만 사서 문앞에 앉아서 먹었는데, 아이가 너무 맛있다고 해서 바로 초코랑 소금크림빵 추가로 구입했어요. 맛있네요!! 소금크림빵은 단짠 맛있었어요. 빵도 부드럽고 크림도 부드럽고요. 초코맛 문앞에 앉아서 바로 먹었는데 빵이랑 크림이 소금크림이랑 다른 느낌이었어요.', 96, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '소금크림빵, 리얼딸기크림빵, 말차단말크림빵 구매! 개인적으로 소금크림빵 너무 취저였어요 크림이 쫀쫀한 식감이라 신기하고 맛있게 먹었습니당 말차단말크림빵은 쏘쏘, 말차크림만으로도 충분한거 같아 다음에 말차크림빵 예정 딸기는 구냥 딸기크림빵 느낌^^', 6, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '연남동에서 꽤나 오래되고 유명한 크림빵 맛집이에요. 먹으면 푸하하 웃음이 난다고 해서 푸하하크림빵인데 진실인지 거짓인지는 드셔보시면 압니다. 생크림이 꾸덕할꺼라고 생각하셨다면 천만의 말씀 구름을 먹는듯한 부드러운 생크림이 특징입니다. 장점은 부드럽고 맛있다는거고 단점은 너무 금방 먹어버린다는거에요. 개인적으로는 살짝 얼려서 먹는걸 좋아합니다. 썸녀분과 데이트를 끝마칠때쯤 한박스 포장해서 선물하면 바로 매너 샹남자 되는겁니다. 추천하는 맛은 초코입니다.', 92, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
