INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '엄청 먹어보고 싶었던 푸하하크림빵..! 진짜 푸하하크림빵 먹고 나면 맛있어서 ‘푸하하‘ 함..! 여기 있는 빵들 다 먹어보는 게 목표 ! 존 맛 탱 !', 0, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '요즘 편의점에서 푸하하크림빵이 여기저기서 보여 한번 와봤습니다 생각보다 한산하여 슥 가보았는데 6~7개 정도의 다양한 크림빵이 있었습니다 초코크림빵이 굉장히 끌렸지만 쓸데없이 근본없는 근본론이 발동해 기본메뉴이자 대표메뉴인 소금크림빵을 골라버렸습니다 뭐 두 개 골라버려도 되지않나 싶었지만 크림빵 특성상 한 개 먹고 두 번째 먹을 때는 분명 두번 째 먹는 크림빵이 아무래도 감흥이 덜 하는 건 어쩔 수 없기도 했고 다른 빵집도 가 볼 예정이었어서 불가피했네요 그렇다고 포장해서 들고가는건 귀찮기도 하고 다른 빵집에 입장할 때 타 매장 빵을 가지고 가는게 좀 그래서 어쩔 수 없이 하나만 골랐습니다 또 포장을 한다면 집가기전 마지막 일정에서 하는 편이기도 했구요 암튼 먹어보니 당연하지만 크림빵 맛이었습니다', 86, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '자주 다니는 편집샵 근처에 있어서 찾기 수월했어요 빵지순례하려고 찾다가 소금크림빵 먹어보고 싶어서 갔고 대만족입니다 집에 와서 제일 먼저 시식🩷', 30, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '빵 선물 하려고 구매했어요 ! 다양한 맛의 크림이 있어서 취향껏 고르기도 좋고 부드럽고 넘 달지 않아서 어르신들 입맛에도 딱 맞더라구요 ෆ(˶’ᵕ‘˶)ෆ 저는 그릭요거트 크림빵이 제일 맛있어요 👍🏻', 85, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '너무 가보고 싶던 곳이어서 포장해서 왔습니다. 예상보다 덜단팥생크림빵? 그게 너무 맛있었어요! 그 외는 크림은 많은데, 맛은 연한 느낌?이에요 저는 맛있게 먹었지만 진하고 꾸덕한 크림을 좋아하시면 조금 불호일 것 같아요', 30, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '크림소금빵, 딸기크림빵, 팥크림빵 3가지 샀어요 팥 크림빵은 써놓은대로 안달아서 좋았어요 부드러운생크림 생각날땐 딱이예요 근데 딸기크림은 다른크림느낌이예요 부드럽게 녹는다기보다 저에게는 느끼한 크림이라 담번엔 뺄거예요', 414, 50, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '최애 크림빵집이라 홍대 근처 들리면 되게 자주 구매해오는 가게입니다. 누르면 폭 들어가고 씹었을 때 퍽퍽하지 않은 촉촉한 빵시트에 맛있고 고소한 크림이 들어있어서 조화가 좋습니다. 특히 소금크림빵의 경우 느끼해질 즈음 소금이 맛을 잡아주어서 물리지 않고 순삭이 가능합니다ㅋㅋㅋ 푸하하의 메뉴를 전부 먹어봤고 모두 평균 이상으로 맛있었지만, 제일 추천드리는 맛은 메인인 소금크림빵과 단팥크림빵이에요! (다른 것도 맛있지만 굳이 고르라면 이 둘이 최고입니다.) 그리고 요거트나 말차의 경우 단맛이 적고 정말 요거트, 녹차맛이라 호불호가 탈 수 있으니 참고 후 구매하세요~', 25, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '옛날 생각나서 오랜만에 다시 왔는데 소금크림빵 말고는 말차크림빵은 생각보다 별로였다. 한두번 사먹을 정도긴한데 개인적으로 소금크림빵이 근본', 26, 5, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '맛있다고 들어서 홍대 온김에 들러서 포장해갔어요! 단팥크림빵이 맛있네요~~ 하나 이상 먹기엔 양이 꽤 많아서... 양 적으시면 간식용으로는 둘이서 하나 나눠먹어도 괜찮을 거 같아요!', 17, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '부모님도 부드러워서 잘드실정도로 부드러운 빵입니다. 냉동실에 보관했다가 아이스크림처럼 먹어도 맛있습니다. 말차는 씁쓸한 맛이 강해서 호불호가 강할수 있지만.... 저는 말차를 좋아해서 극호였습니다', 46, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '맛있다는 지인언니 말에 사와서 먹었는데 맛있네요. ㅎㅎ 크림이 아주 많아서 촉촉하고 부드러워요~!!아아랑 먹으면 더 맛있을꺼같아요 !!', 44, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '소금크림빵 리얼딸기크림빵으로 포장해왔습니다. 생크림이 많이 달지 않고 크림 양도  푸짐하니 많이 들어 있어요. 느끼하지 않고 깔끔해서 좋아요. 가격도 적당합니다.', 44, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '여기가 그렇게 유명한지 몰랐는데 마침 지나가는길에 [같이다닌 친한지인이 말해줘서] 빵수니답게(?🥯욕심부려 6개사서 세트구성가로 할인구매😋종이상자에 가득 담아주셨어요*^^*🛍️ 절대 보통의 크림빵이 아닙니다🤩작은 빵속에 그냥 적당하고 무난한크림이겠거니 했는데 한입 무는 순간 Fuhaha- 넘치듯이 많아서 겁나놀랬어요😱  #소금크림빵 소금빵맛이 안낫어요😓#덜단팥크림빵 🤎단팥에 호두견과류가들어있어서 존맛탱🫶🏻#리얼딸기크림빵 🍓상큼한맛은 덜한🩷#그릭요거트크림빵 🤍젤 요거트다운맛과 역시#말차단팥크림빵 🌿💚원…ㄹ… 래..는 음… 👉🏻👈🏻나눠먹으려고샀는데 삼일걸쳐 내 뱃속으로🫨', 45, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '아침에 가서 푸하하세트 2개 겟! 친구네 가벼운 집들이용으로 샀어요. 더운 날씨엔 보관에 좀 유의해야 해서 보냉팩 추가하시는 게 좋지만 30분 정도는 괜찮아요~ 저는 오늘은 보냉팩 없이 가져왔어요ㅎㅎ 크림 가득해서 실패하지 않는 선물입니다ㅠㅠ', 9, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '초코씌운 크림빵이 맛있오요! 시즌 ? 제품 같은데 진짜 너무너무 맛있구 푸하하 크림이 찐이에요. 초코크림빵은 조그맣지만 2천원이라 큰빵먹기는 부담스러울때 먹기도 좋아요. 남자친구가 좋아해서 퇴근하고 갈때 5개씩 사가고했는데 먹어도 먹어도 질리지 않는 맛', 66, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '요즘 이런 생크림빵 많이 나와서 평범했다. 연세크림빵이 더 맛있다. 소금우유맛 그럭저럭 맛있다. 녹차 엄청 좋아하는데 푸석푸석 빵에 단맛이 적은 씁쓸 푸석한 크림이어서 아쉽다,, (오늘빵이 아니었나..?) 약간 호불호가 갈릴 수도 있는 재질 🥛🌿🥲', 16, 0, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '홍대가면 꼭 사오는 푸하하 크림빵 크림이 달지 않아서 자꾸 먹게되요. 한박스에 6개 인데 집에 오자마자 세개 바로 먹었어요. 맛있는 푸하하크림빵 추천합니다', 48, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '홍대입구 스시집에서 밥먹고 남편 좋아하는 푸하하크림빵집에서 3박스 사서 아들들 나눠주고 나니 마음이 푸근하다. 빵에 들어있는 크림이 달지않고 부드러워 입에서 살살 녹아  2개를 바로 꿀꺽했더니 다이어트 걱정되네. 정말 맛있는 크림빵이라 적극 추천합니다', 6, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '너무 맛있어요오🥹 그릭요거트 크림빵 얼먹하니 천국이더라고요 모두 얼먹해보시길!! 6개 세트 사서 가족들이랑 나눠먹기 좋아요 특히 말차단팥크림빵은 부모님이 좋아하시는 맛! 다음엔 그릭요거트 왕창 사갈 거예용', 66, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '소금맛매니이인데 이번엔 말차로 사서 먹었어요 크림이 부드러워요 몇년전엔 항상 줄서서 사서 먹었는데 바로구매했어요 예전보다 빵이 부드러움이 덜한 느낌이예요', 7, 1, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '진짜 맛있어요 🫶🫶소금크림빵🫶🫶 매우 추천합니다 진짜진짜 크림이에요 후다닥 먹어버려서 사진이 없네요 정말 맛있어요 지나가실일 있으면 꼭 드셔보시길 추천해요', 32, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '근처 떡볶이 맛집을 가다 알게된 빵집 리뷰를 찾아보니 괜찮다는 글들이 많아서 리얼딸기크림빵과 제주말차크림빵을 구입했어요 빵이 좀 더 부드러움 좋겠다는 생각이 들었어요', 47, 6, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '크림빵 먹고 싶어서 가봤는데 생각했던 정도의 무난한 크림빵인ㅎㅎ 시그니처라는 소금크림빵은 기대했는데 생각보다 짠맛이 없어서 좀 아쉬웠다는!', 48, 7, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '매장에서는 먹을수 없고 테이크아웃만 가능합니다. 그냥 생크림빵맛이라 뭐 특별한건 없어요..크림소금빵인데 소금빵의 매력은 없어요,,참고로 바로안먹고 냉장보관후 먹으면 빵이 살짝 젖어 축축해지네요', 500, 59, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '크림빵 안에 크림이 꽈-악 차있어서 놀랐어요!! ‘리얼딸기, 제주말차, 그릭요거트’ 이렇게 포장해서 집에서 먹었는데 다 성공적이더라고요!! 리얼딸기는 인공딸기맛이 아니라서 좋았아요! 제주말차는 씁쓸한 맛을 잘 살린 말차크림이었고요! 그릭요거트는 크림이 안느끼해서 입맛에 맞았어요! 전체적으로 빵피가 얇은 편입니다!! 크림 한가득 머금고 있으면 행복해지는 크림빵입니다🥰', 63, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '오랜만에 사먹었는데 예전보다 맛있게 먹었습니다! 그런데 점원분이 안계셔서 10분 -15분 정도 기다렸는데 옆에 상품 받으시느라 그러셨더라구요? 충분히 기다릴 수 있는데 뻔히 봤을텐데 아무 말도 없으시고 10분 넘게 기다렸으면 적어도 뭐라 말을 해야 하는거 아닌가 싶었는데 10초 기다린 것처럼 대하셔서 좀 당황스러웠습니다. 다시 빵 넣어놓고 집에 가야하나 여러번 고민 했습니다.', 82, 12, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '홍대입구 작은카페에서 푸하하크림빵을 일삼아 가서 헤매다가 겨우 샀다 너무 먹고 싶어서 ~  내 입맛엔 크림도  아주 부드럽고 빵은 적게 들고''살살 녹는다', 42, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '집에와서 얼먹하고 있는데 소금크림빵은 그냥 맛도리구여,, 아니 그릭요거트가 진짜 의외의 미친넘이에효 😍 그리고 말차도 넘무 찐하고 맛있고 크림이 특히 막 되게 느끼하지가 않아요 그래서 사실 크림 좋아는 하지만 많이는 못먹는데 여기 크림 말모에여 ,.. 참 막 한꺼번에 먹어버리고 싶은데 꾹 참고 하루에 하나씩만 먹고 있답니다 ㅠㅠㅠㅠ 너무 맛있어요 또 먹고싶,,어여🤩', 38, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '홍대에 들렸다가 남자친구가 생각나서 푸하하 크림빵을 사갔어요! 녹차 싫어하는 제 친구 넘넘 마싯게 먹더라구요❤️ 푸하하 크림빵은 진짜 워낙 유명해서ㅜㅠ 홍대가면 항상 몇개씩 사서 주변 사람들 나눠주는 것 같아요 ! 그릭요거트 맛은 아직 저도 못먹어봤는데 조만간 가서 또 왕창 쓸어올까바요 ㅎㅎ ! 짱짱맛 강추에욭👍🏻🤩 + 추가금액 지불하면 보냉백도 추가 가능합니다용!', 26, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '크림빵 맛있어요! 🧂소금크림 🫘덜단팥크림 🌿말차크림 🌿🫘말차단팥크림 🍦그릭요거트크림 🍓딸기크림 이렇게 6종있는데, 크림 자체가 맛있었어요! <소금크림빵>이랑 <덜단팥크림빵>이 제 최애입니다- fuhaha😄 말차는 쌉쌀한 찐한 녹차맛에 그릭요거트는 살짝 새콤한 맛이 있는 크림이었어요! 딸기크림은 달달하기보다 신맛이 좀 쎄서 제 스타일은 아니었던것으류.. 취향탈거 같아요! 어쨋든 맛있는 크림빵집입니다🫶', 16, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '맛있어요! 6종세트로 구매해서 냉동실에 얼렸다가 해동해서 먹었는데 그대로예요! 넘 맛있어요😆✨ 딸기크림은 기대하지않았는데 정말 맛있더라구요 ㅎㅎㅎ', 11, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '요새 크림빵 제품이 편의점에도 많이 등장했는데 먹다보면 느끼하고 또 안찾게되는데 푸하하 크림빵은 몇년만에 먹어도 맛있어요! 느끼하지않고 적당한 그 선을 잘 지키는 크림빵!', 35, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '제가 우리나라에서 제일 좋아하는 크림빵 맛집 이랄까요 .. 진짜 맛있어서 평상시에 6개씩은 꼭 사서 집에 가는 거 같아요 !! 존맛 진짜', 86, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '엄청 퐁신퐁신 한 크림 빵 맛이에요 개인적으로는 얼먹 하는 것보다, 최대한 빨리 드시는 게 맛있는 거 같아요! 소금 크림 빵이 최애입니다', 40, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '크림 꽉꽉 채워서 듬뿍듬뿍♡ 크림빵은 푸하하가 짱입니다. 같이 갔던 친구들도 몇개씩 사갔는데 다들 맛있다고 하네요. 선물용으로도 좋아요.', 53, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '연남동 갈때마다 종종 사먹었는데 처음으로 리뷰 남기네요:) 기분탓인지는 몰라도 예전보다 맛이 덜한건지 아니면 포장해서 가지고오느라 그런건지.. 생크림들어간빵만 크림이 엄청 녹아있고 양이 좀 적다는 느낌이 들었어요 ㅠㅠ 크림 자체는 맛있어요! 녹차크림은 항상 먹었던 건데 여전히 맛있었구요 딸기크림은 처음 먹어봤는데 생각보다 괜찮았습니다!', 47, 3, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '모든 맛 먹어보고 싶었는데 젤 유명한 소금크림빵 먼저 샀어요. 크림이 정말 푸하하하고 빵피는 적당한두께에 약간 짭짤한맛 나면서 맛있더라구요🤍 많이 달지않아 아빠도 좋아하셨어요! 다음엔 다른맛들도 먹어볼게요🥰', 18, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '빵지순례 하는 거 좋아해서 연남에 머리하러 간 김에 들린 푸하하 크림빵! 크림 많은 빵을 선호하는 편은 아닌데 유명하다니까 한 번 가보자 해서 가본 곳이에용 처음이니까 소금크림빵이랑 말차만 사고 맛있으면 더 사러 와야징 했는데....... 집에서 먹어보고 바로 후회했잖아요 더 사올걸... 녹차 씁쓸한 맛, 단 맛 다 좋아하는 사람인데 푸하하는 진한 맛이에요! 녹차 디저트 단맛을 좋아하시는 분들은 조금 안 맞으실 수도 있을 것 같아요 그치만 소금 크림빵은 찐입니다 대표메뉴인 이유가 있어요...ㅠ', 19, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '홍대 놀러갔다가 집에 가는길에 호기심에 지하철역 근처 골목에 들어갔다가 크림빵집 있는거 보고 환호성을 질렀네요!! 빵이 달지 않고 가벼운 느낌에다 크림도 듬뿍이라 넘 맛있었어용 ㅠㅠ', 34, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '연남동에 위치한 크림빵 맛집으로 소문난 푸하하크림빵 크림빵을 먹으면 푸하하 웃음이 나서 푸하하크림빵?! 아무튼 빵돌이든 빵순이든 연남동 빵지순례 고고 연남동빵집 푸하하크림빵 매일 09:00 - 22:00 - 생활의 달인 515회 소금크림빵 출연 소금 크림빵 ₩2,800 천일염 간수를 생크림으로 처이한 특허받은 소금이 뿌려진 크림빵 리얼딸기 크림빵 ₩2,800 상큼한 생딸기 조각과 부드러운 크림이 조화를 이루는 크림빵 덜단팥 크림빵 ₩3,000 몸에 좋은 단팥에서 설탕을 줄여 더욱 건강하고 풍성한 맛의 크림빵(호두포함제품) 제주말차 크림빵 ₩3,300 쌉싸름한 유기농 제주말차로 만든 고급스러운 풍미의 크림빵 그릭요거트 크림빵 ₩2,800 그릭요거트로 만든 생크림이 묵직하고 상큼하게 어우러진 크림빵', 452, 59, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '전부터 넘 궁금했었는데 드디어 다녀왔어요~~!!!! 소금크림빵이랑 리얼딸기 먹어봤는데 소금크림빵이 맛났어용~ 리얼딸기는 후레쉬베리?같기도하고 걍 쏘쏘였고 소금크림빵은 또 먹어보고싶어요옹~~~ 포장밖에안되서 아쉬워요ㅜㅜㅜ', 11, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '크림빵 대체적으로 다 맛있어요 포장했는데 소금크림빵이 약간 터져서 어라 했는데 안 터진 빵이 훨씬 맛있더라구요 가끔 생각날 맛이에요', 18, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '하얗고 깔끔한 인테리어….. 리얼딸기, 그릭요거트 크림빵 2800 제주말차단팥크림빵 3300….을 선택했습니다 사진상에서는 촉촉하고 엄청 맛있어 보였는데 제가 먹었던 크림빵에서 역대 최악이었어요 ㅜㅜ….딸기는 딸기쨈맛 말차단팥은 말차가 너무 지나치게 썼어요 단팥은 맛있는데 전반적으로 빵이 너무 퍽퍽하고… 퍼석한 느낌 생크림도 쫀득한 생크림이 아니네요 같이 먹었던 사람도 왜 유명한지 모르겠다구.. 진짜 먹으면서 놀람 포장은 귀여워요…', 5, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '크림빵 맛있다는 말에 바로 달려가서~ ㅎ 경의선숲길 지나 연트럴파크 지나서 구불구불~~ 도착한 빵집이 너무 작아서 살짝 실망?? 테이블이나 좌석도 없고 진열장에 빵만 있다. 자세히보니 싸인받은 박스들이 쌓여있네 ㅎㅎ 소금크림빵과 딸기 크림빵을 사들고와서 먹어보니~ 크림이 듬뿍든게 맛이 있긴하네 ~~♡ 근데 이거 맛들이면 클라겠다 싶어서 오늘까지만 먹는걸로 ㅎㅎ', 54, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '크림 잔뜩 들어있는 크림빵 맛집 시그니처 메뉴인 소금이 살짝 뿌려진 소금크림빵은 크림의 단맛을 더 끌어올려주는 매력이 있어서 종종 생각나요. 다른 종류도 다 먹어봤지만 기본 소금크림빵이 제일 맛있어요.', 90, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '맛있는 크림빵~ 줄서서 먹는 이유가 있네요 저는 개인적으로 소금크림빵이 제일 맛있었어요 푸하하 6종 16천원 연남동 홍대투어할때. 가볼만한 곳 앉아서 먹거나 할수 있는 장소가 없어서 아쉽네요 집에 가져와서 먹어도 맛있긴 해요 ㅋ', 22, 0, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '덜단단팥크림빵의 단면입니다. 가끔 크림빵 먹고싶을땐 항상 여기서 사먹습니다. 부드러운 크림과 씹히는 팥과의 조화가좋습니다. 맛있어요!!', 69, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '저희 중딩 아들이 그러는데 덜단팥크림빵은 일단 크림이 느끼하지 않고 적당히 달고 고소함이 조화로운 빵이라고 합니다~!저도 격하게 공감요~ㅎㅎ', 9, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '크림빵으로 정말 유명한 푸하하크림빵입니다!! 소금크림빵이 젤 맛있어요~~ 다른 크림빵과는 차별성 있는 맛 👍 그리고 말차단팥도 유명한 거 같아서 시켰는데 말차크림이 생각보다 달지 않고 팥도 적당히 들어가서 알맞은 단맛이 나면서 조합이 진짜 좋아요~ 인생크림빵입니다♡', 90, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '근처 들른 김에, 리뷰 많은 푸하하크림빵집 들러 크림빵 구매했어요. 소금크림빵 부드럽고, 녹차 말차를 좋아해서, 제주말차크림빵도 맛나네요~', 22, 5, 'GOOD', SYSTIMESTAMP);
