INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '먼저 아쉬운점은 말차크림이 제 입엔 조금 쓴맛이 강했고 빵이 조금은 퍼석퍼석해서 자꾸 우유를 먹게 되는 맛이었어요 그래도 크림이 매우 많이 들어있고 괜찮은 크림빵이네요', 59, 18, NULL, SYSTIMESTAMP);
