INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '가격이 비싼 편은 아니지만 그만큼 빵 맛은 떨어져요 .. 크림이 느끼한 편은 아니지만 빵피가 편의점 빵 같아요,, 또 먹을 것 같지는 않네요', 83, 14, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '유튭에서인가 많이 보였전 빵집이라 한번 찾아가 봤는데 좁지만 깔끔하고 크림빵 맛은 단맛이 별로 없고 담백한 맛..? 뭔가 좀 아쉬웠어요. 그래도 맛있게 먹었습니다!', 34, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '크림이 많이 들어 있어서 좋았어요! 빵피는 담백하고 가벼운 질감이고 겉면이 건조한 느낌입니다. 그릭요거트는 은은하게 요거트 향이 나는 크림었고 리얼딸기는 딸기가 오독오독 씹히고 상콤달달함이 더 강했습니다.😆 그릭요거트랑 리얼딸기 중에서는 딸기가 더 맛있었어요. 완전 내스타일🍓🍞사실 그릭요거트가 소금크림인줄 알고 결제했는데 알고보니 그릭요거트였던...ㅋㅋㅋㅋ😅다음에는 꼭 소금크림빵도 먹어봐야겠어요.', 9, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '🍪 먹은 것 - 소금크림빵 2,500원 - 리얼 딸기크림빵 2,500원 - 단팥크림빵 2,700원 🪑자리 없음✖ 포장만 가능 💛 재방문의사 있음 가격에 비해 훌륭한 맛. 베이직한 소금크림빵이 가장 취향이었음. 먹을 때 볼에 묻을 정도로 크림이 한가득 들어있어 좋았음. 차갑게 먹어야 더 맛이 좋음.', 32, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '블로그 뒤져보니 기본이 제일 맛있대서 기본 6개 세트 샀어요! 빵도 부드럽고 크림이 많이 안 달아서 먹기 좋아요. 팀원들이랑 나눠 먹으려고 한 박스 샀는데, 산 지 좀 지나서 냉기가 빠진 상태로 먹었는데도 맛있었어요! 다음에는 사자마자 바로 시원한 상태에서 먹어봐야겠어요', 2, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '크림빵 종류별로 싹다 사왔는데 제 입맛엔 오리지널인 단팥크림빵이랑 소금크림빵이 젤루 맛있었어요!! 빵은 퍼석퍼석해서 제 타입은 아니었는데 안에 크림이 너무 부드럽고 입에서 사르르 녹는 달달함 >_<  넘맛있어요~👍 남은 빵들은 냉장고에 하루 넣어두고 다음날 먹었는데 사자마자 바로 먹었을때보다 크림이 보들보들하지 않고 살짝 굳은 느낌이라 맛도 크림의 질감도 좀 떨어지네요~ 크림빵 사온날 바로 드시길 강추합니다 ㅎㅎ', 11, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '급하게 친구 줄 케이크 사려고 갔었어요! 적당한 크기의 미니당근케이크 구매했는데, 가격도 그렇게 비싸지 않았고 맛도 있었습니당 ㅎㅎ 그리고 사장님이 친절하셨구요! 감사합니다🧡', 117, 21, 'GOOD', SYSTIMESTAMP);
