INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '2500원인데 가격도 싸고 크림도 많고 맛까지 좋은🥺💜 딸기크림이 상큼하고 크림 양도 많아서 맛있었어요 다음에 다른 메뉴들도 뿌시러 올게요🌝', 81, 14, 'GOOD', SYSTIMESTAMP);
