INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '2-3달 전보다 가격이 오른 거 같기는 하더라고요.가까운 편의점에서 연세크림빵 먹다가 여기가 생각나서 지하철 타고 왔어요.크림빵 생각나면 종종 올게요', 7, 7, NULL, SYSTIMESTAMP);
