INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '계산하시는 직원분, 계산하면서 한숨 푹푹 쉬고 기운 없는 목소리로 안녕히 가라 하는데 힘든 사람 더 힘들게 괜히 왔나 마음이 편치 못했습니다. 오랜만에 들렀는데 기분이 좋지 못했네요.', 45, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '크림 맛있어요.. 대신 동물성지방이고 그릭요거트 메뉴도 생크림이 반 들어가있대요 유당불내증 있으신분들은 먹으면 안될듯ㅠㅠ 맛은 있어요', 36, 10, NULL, SYSTIMESTAMP);
