INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '완전 친절하구 완전 맛있어서 몇년전부터 꼭 생각날때마다 들르는 맛난 빵집! 유명해지면 맛없어지거나 불친절해지는 경우 많던데 여기는 안그래서 좋아요 최고예요', 24, 6, 'GOOD', SYSTIMESTAMP);
