INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '빵도 손님이 셀프로 가져 오고 알바는 딱 계산만 하면서 알바 왜이렇게 불친절함? 알바는 하는 일도 없고 가만히 앉아있다 계산만 하면서도 불친절...', 18, 2, 'BAD', SYSTIMESTAMP);
