INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '크림빵들 맛있네요  특히 소금 크림빵,리얼딸기 크림빵,덜단팥 크림빵,그릭 요거트 크림빵 이 재일 무난하면서도 제 입에 맞는거 같네요', 9, 5, NULL, SYSTIMESTAMP);
