INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '리얼딸기크림빵은 하얀크림에 딸기 조각이 들어가는줄 알았는데 하얀크림이 아니네욥ㅠㅠ 그치만 기본적으로 크림이랑 빵이 맛있어서 담엔 소금으로 먹어보려구요', 23, 3, NULL, SYSTIMESTAMP);
