INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '웬만하면 이런말 안하는데 토요일 4시 30분경에 있던 직원? 알바분? 정말 불친절하네요^^ 빵 맛은 둘째치고 응대가 정말 불친절해서 다시는 가고싶지않아요ㅎㅎ', 12, 9, 'BAD', SYSTIMESTAMP);
