INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '빵 자체는 푸석푸석 별로라는 말 공감이에요 개인적으로 소금크림>그릭요거트>=딸기 순으로 맛있었어요 크림은 전부 부드럽고 맛있어요', 52, 11, NULL, SYSTIMESTAMP);
