INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '기대가 컸나봐요.  소금크림빵만 먹어봤는데 크림빵 자체는 다른데서 파는 크림빵과 별로 다르지 않았어요. 요즘 맛있는 빵집이 많아져서인지 맛은 평범하고 소금맛은 아주 약해서 특별하다고 느껴지지는 않았고 그냥 많이 먹어본 맛있는 크림빵 정도 였어요.', 113, 26, NULL, SYSTIMESTAMP);
