INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '신경 좀 써 주시길요... 넘나 맛있어서 아이들 먹이고픈 마음에 사들고 왔더니... 크림과 빵사이에 크림과 빵이 범벅된 머리카락이...  잡아당기니 쭉~뽑혀나오내요.', 41, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '아직도 불친절 알바생들이 있네. 바쁘지도 않은데 바쁜척 말하고 응대며 말투는 일하기 싫어서 그런가 소님오면 그래도 한번씩 사주고 하는데.. 빵은 푸석푸석 해진지는 오래된듯.. 초심을 잃으면 뭐든 변질되는 건 시간 문제 인듯', 27, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '전에 먹어보고 맛있어서 재방문했는데 직원분 태도 진짜 마음이 안드네요 ^^ 31일 오후2시30분에 방문했습니다 ^^ 저도 요식업 쪽에서 고객응대 해봐서 진짜 힘든건 알지만 아닌건 아니에요 왜 내가 내돈 내고 기분이 나빠야하나요?', 92, 26, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '[생활의달인] 크림빵(2500~) 구매하러 방문 (그릭요거트 매진) 맛은 전체적으로 다 크림이 적어서 사진이랑 매우 달라(제주도에서 파는 것보다도 적음) 많이 아쉬웠어요. 소금은 소금맛아니고 그냥 크림빵. 리얼딸기는 딸기맛(인공x).말차는 진해서 취향이었고 덜단팥은 제 입맛엔 적당히 단맛(좀 덜 달아도 될 듯) 제주도에서 맛있게 먹어서 본점 간건데...아쉬워요 근처 사는 사람 아니라면 굳이 찾아가서 먹을 정도는 아닌 듯 합니다.', 87, 11, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '4종세트랑 소금크림이랑 말차단팥하면 9700+2500+2800=15,000원 아닌가요? 저도 확인 안한 실수있지만, 구매하기전에 4종세트산다고 말했던거같은데 근처 사는 것도 아니라서 다시 갈 수도 없는데 아쉽네요 하지만 빵은 맛있습니다', 23, 1, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '유명해서 진짜 먹어보고 싶었는데 맛있었어요 ! 크림빵 종류가 많은게 좋았고 크림도 폭신 폭신해요 막 달거나 그러진 않았어요 !', 1, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '소금크림빵이라 달달짭짤생각했는뎅 달아용! (맛있게 달아용!) 예상했던맛과는 달라서 아쉽 ㅠㅠ 알바생분은 목소리가 작으셔서 조큼 크게 말씀해주샤도 될거같아용! 저는 친절함을 느꼇는데 난친은 목소리가 작아서 인삿말도 안들렸데용!', 18, 3, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '진짜 불친절해요! 뭘 물어보면 이해도 못하고 짜증가득한투로 응대하는 직원 덕분에 좋은 기분으로 갔다가 기분상한곳입니다 배달로도 연남점은 이용안하고싶네요 직원교육부터가 엉망..', 11, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '소금,말차,요거트 크림빵 포장해서 먹었고요. 소금은 배합이 아쉬웠어요. 짭짜름하면서 부드러운 크림이 느껴져야하는데 그냥 크림빵같은 느낌. 말차는 말차맛이 진하고, 그리달지 않아요. 요거트는 그나마 낫네요. 매장안이 좁아 조금 기다려서 샀는데, 마트 크림빵 빵 부드럽고 좋네요;; 이곳은 빵도 아쉽고 크림도 아쉬워요.', 40, 1, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '부모님 사다드리려고 방문했어요 6종세트 14,500원 / 보냉팩 무료이벤트하고 계시더라구요 ㅎㅎ 늘 맛있어서 크림빵 좋아하시는 어른들 사다드리기 딱이에요', 6, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '크림은 맛있는데 빵부분이 너무 별로에요 그리고 출입명부작성 안내 제대로 해주셨으면 좋겠어요 안내가 없어서 제가 두리번거리면서 찾아서 썼네요', 24, 8, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '동네 볼 일이 있어 갔다가 우연히 발견하고 가 본 곳인데 상호명이 웃음을 주네요. 리뷰가 좋아 가보았는데 만족스러웠습니다. 앗! 저도 쓴 맛 제법 좋아하는 편하데 제주녹차? 진짜 진짜 쓰네요ㅜㅠ 나머지는 좋았습니다.', 34, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '일요일 알바 인성문제가 심하네요 많이 사니까 계산이안되서 가격몇번물어봤다고 성질을 부리는데 뭐죠? 다신 오고싶지않은곳입니다 빵사는데 기분나쁘긴 살면서 처음이네요....여기 가는분들 조심하세요', 40, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '기대를 좀 많이 했나봐요 그냥 그럭저럭한 크림빵이었어요 크림 양은 진짜 많지만 가격도 그만큼 있다는 거? 개인적으로 단팥이 맛있네요', 28, 7, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '말차 단팥크림빵 2,800원. 크림이 듬뿍 들어잇어서 즐거워요. 녹차 쌉싸름한 맛이 달콤한 크림과 어우러져 기분이 좋네요. 촉촉해서 음료 없이도 잘먹엇어요.', 13, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '크림빵은 다 맛있었어요 ~ 근데 직원이 상당히 무뚝뚝하고 친절하지 못하다는 느낌을 강하게 받았네요 웬만큼 아니면 이런 말 잘 안 하는데 손님인 제가 더 친절하게 말했던 것 같네요 ㅎㅎ', 63, 18, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '푸하하크림빵'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '워낙 빵을, 특히 크림을 좋아하다보니 맛있었어요. 너무 달지도 않고 뭉근하고 부드러운 크림의 식감!! 단팥크림/딸기크림/말차크림 먹어봤었는데 다 맛났어요. 근데 공장식으로 대량생산?인지 빵피 자체는 쫄깃 폭신 보다는 조금 푸석해요. 그리고 크림도 소금크림빵이나 단팥그림처럼 첨가해서 섞지 않고 그대로 들어간 종류가 더 크림 식감은 좋더라구요. 재구매 의사는 있습니다.', 31, 10, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '여행와서 블로거로서 급서치 식사용으로 사가려고옴. 더위를물리치고 갔는데 내외분이 넘친절하고 우유식빵1,밤식빵1,소보루1. 일단사서 가게안에서 소보루뜯어먹자마자.안달고맛나고 똑같은조합 또 결제함 덜달고 괜찮네요 소분해서 냉동실넣어두고 잘먹을께요 갓나온거라 포장한쪽은 열고 포장해주심 건강하세용', 8, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '요즘은 흔해진 프리미엄 식빵전문점 밀땡이나 화이트땡땡 등이 있기전부터 이미 오래된 식빵 맛집 김진환 제과점이 있었드랬죠..! 꾸준히 식빵 만들어주셔서 감사합니다. 원래라면 빵이 없었을 시간에 방문했는데 날씨가너무 더워서인지 마감 시간 전에도 빵이 조금 남아 있어서 좋았어요! 시나몬베리를 못 사서 아쉬웠지만 식빵 든든히 사와서 행복합니당♡ 사모님도 늘 친절하고 밝게 맞아주세요!!', 21, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '우유식빵 5000원, 밤식빵 4700원에 구매했어요 ! (25.07.22) 더운날이라 그런지 오후12:30분쯤 도착해도 빵이 넉넉히 있더라구요 ~ 빵은 포장만 가능하고, 맛 자체가 깔끔하고 너무 꼬숩습니다 ~~ 위치가 애매해서 자주는 못 가겠지만 신촌과 홍대입구 쪽 갈일 있으면 또 들릴게요 !!', 70, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '가보고 싶던 식빵가게! 근처 병원 갈 일이 있어 들렀어요. 내부 작업실에서는 세월과 내공이 느껴져 멋있었고, 우유식빵은 기본에 충실하고 담백하니 맛있었어요.', 75, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '우유식빵,시나몬베리,소보루,모카모닝빵 사와서 먹어봤네요. 재방문 한다면 소보루 정도만 사오지 않을까 싶습니다. 30년전 먹던 옛날 빵맛을 좋아하는 분이라면 우유식빵,소보루 등 다 좋아하실거 같은데 모카모닝빵은 굉장히 실망스러운 맛ㅜㅜ 호두 모카빵 아닙니다~~ 모닝빵은 비추비추.. 요즘 워낙 맛난 빵들이 많다보니 저는 조~~금 아쉬웠어요 추억의 맛 정도^^;;', 36, 2, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '우유식빵과 밤식빵이 먹고싶을땐 무조건 김진환제과점으로 가요 부드럽고 촉촉하고  담백해서 계속 손이 가요 이번에 방문했을땐 시나몬베리도 구매했는데 완전 제스타일이네요 시나몬향과 상큼한 베리의 조합이 잘 어울리네요 집 가까운 곳에 맛있는 빵집이 있어서 너무 행복해요', 35, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '토요일 오전 10시30분에 방문했습니다. 밤식빵,앙금빵,하나는 기억이 안나네요. 오래된 가게는 이유가 있는 법 이지요. 오전에 방문하니 갓 구워져나온 빵을 먹으니 너무 맛있었어요. 밤식빵도 옹골찬게 맛있더라구요. 요즘 빵 가격이 터무니 없이 비싼 경우가 많은데 김진환베이커리는 가격도 맛도 좋다고 느꼈습니다.', 0, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '모카앙금빵, 모카완두빵. 합정 홍대 신촌 이대라인 생활 8년차로서 이곳은 빵을 바로 만들어서 팔기 때문에 맛있다. 빵을 사면서 빵을 만드는 모습을 볼 수 있어서 좋다. 진정한 오픈 키친 이랑께 ㅋ 이곳은 다른 일부 빵집처럼 다른 곳에서 빵을 만들고 옮겨서 파는...방부제 덩어리 빵이 아니다.', 24, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '갓나온 밤식빵과 소보로는 천국행 티켓 아닌가요? 평일 오전 매번 품절되어 구경도 못했었는데, 운이 좋게 구매 할 수 있었어요 ! 겉바속촉의 정석 소보로와 밤이 정말 가득가득 들어 놀란 밤식빵.. 달달한 맛에 중독되어 길 한가운데서 다뜯어먹을 정도로 좋았어요. 빵이 다 사라지기 전까진 정말 정신 못차리고 먹을 정도로 맛있습니다. 요즘같은 시대에 저렴한 가격까지. 문이 열려있으면 꼭 한번 먹어보세요.', 128, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '인스타에서 보고 방문했어요~ 때마침 일하는 곳과 가까워서 다녀왔는데 지금껏 몰랐던게 아쉬울 정도예요ㅎ 식빵이 겉바속촉이라니😋 맨빵만 먹어도 너무 맛있어요~ 잼 발라먹고 결국은 맨빵만ㅎㅎ 담백하니 맛있네요~ 다른 빵도 먹으러 갈께요~', 6, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '모카앙금빵. 따뜻할 때 먹어야 최고다. 방부제 맛이 안나서 빵먹으러는 이곳만 찾는다. 요즘 다른 빵집들은 빵인지 방부제덩어리인지 정체를 알 수 없는 겉만 이쁜것들을 팔아대고있다. 쩝.', 5, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '<김진환제과점>동네 안쪽 이렇게 숨어있는 보석같은 찐빵집이 있지요.신촌사거리 안쪽에 김진환제과점!빵을 세팅,진열하는 공간도 없이 바로 나온 빵을 포장해서 하는.전 여기 밤식빵 애정합니다.먼곳에서 이것때문에 주말에 온다는게 그 증명!4500원.밤도 토실하고 빵 자체에 수분과 식감 탄력 최고! 밤식빵 사이즈도 딱 적당해요.빵 안은 촉촉하면서 쫄깃하고.밤도 달고 많이 들어서 든든.식빵 위에 사르르 소보로와 아몬드가루가 살짝 뿌려져서 고소해요.', 64, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '십 몇년전부터 다니던 빵집인데 집 이사가고 결혼도 하고... 댕댕이도 생기구... 암튼 이런저런 일로 못가봤는데 참 오랜만에 다시 갔습니다. 정말 예전엔 이런 경의선숲길도 없었어요.. 댕댕이 산책겸 경의선숲길을 종종 갑니다.. 간 김에 한번 가볼까싶어서 다녀왔습니다. 고소한 식빵 냄새가 골목길에 가득합니다. 댕댕이 앞에 주차(?)해두고 신랑이 들어가서 식빵이랑 소보로빵. 완두앙금빵 등등을 사오며 쥔아주머니와 웃으며 이야기합니다. 아마 소보로가 많이 올라간 빵을 고르며 제 이야기를 한 거 같아요~ 제가 ㅎㅎㅎ 소보로만 떼어 먹거든요 ㅎㅎㅎ 정말 고소한 소보로를 차 안에서 떼어먹으며 집에 왔습니다^^ 댕댕이랑 신랑이랑 소보로빵 나눠먹으며 행복했네요~ 오래오래 계속 계셔주세요♡', 104, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PET');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '방앗간 드나들 듯 매일 가는 빵집이에요. 매번 사먹는 구성도 다르게 한 번은 밤 식빵 한 번은 모카 빵 한 번은 소보루 한 번은 식빵 다양하게 골라 먹을 수 있어 좋아요. 맛도 최고입니다. 밤 실하게 박힌 것 좀 보세요.', 18, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '10년전에 이곳을 알게 되어 뜨끈한 빵 뜯어먹으며 한개를 순삭했던 기억이!! 신촌에 갈 일이 있어 오랜만에 검색하니 아직 있어 감사하며 가서 사왔는데 역시나 맛있다!!!', 74, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '신촌가서 여유되면 꼭 가는 김진환제과점! 우유식빵, 밤식빵 필수~ 갓나온 식빵 바로 먹으면 폭신폭신.. 순식간에 없어져서 꼭 두봉지씩 사와야해요', 77, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '우유 식빵을 사람들이 많이 사가길래 구매해 봤어요~ 경의선 숲길 걸어가는데 여기서 식빵사서 가시는 분을 2명이나 봤어요 저도 먹어보니 부드럽고 맛있더라고요 소보로 빵도 많이 사가던데 다음엔 그거 먹으러 가봐야 겠어요', 82, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '아직 빵 안먹어 봤지만 위생상태가 좋지 않습니다. 특히 카드 만지고 그 상태 그대로 다시 빵을 만지고 포장하세요...기본적으로 위생에 대한 인지가 없는것같습니다.', 80, 11, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '사장은 엄청 바쁘고 어떤 아저씨가 들어오더니 손도 안 씻고 빵을 만지길래 한마디 했더니 일단 가볍게 무시하심 그리고 돈 만지고 빵만지고 아주 더러워요', 53, 16, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '오랜 내공의 식빵전문집! 한결같이 기본기 탄탄한 맛과 좋은 가격으로 만날수있어요 기본식빵은 물론 시나몬베리, 밤식빵 다 맛져요!!', 40, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '야간 근무 끝나고 출출하면 이 집 빵이 꼭 생각나서 들르게 됩니다. 밤 식빵 밤도 실하고 달달하니 한끼 식사 대용으로 최고에요.', 58, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '여기 유명한 건 알고 있었지만 가야지하먄서 그동안 못 깄었는데 이번에 사왔습니다. 새벽 운동하고 아침으로 식빵을 먹고 있는데 여러 군데 식빵 먹어봤지만 근처 식빵 중에는 제일 만족스러워요:) 도제 식빵만큼은 아니지만 기름없이 구우면 바삭하니 토스트 해먹기 좋은 식빵입니다. 제가 좋아하는 식빵 종류라 기뻤어요. 현재 있는 식빵이 다 떨어지면 또 사러 갈 예정입니다.', 14, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '그냥 먹어도 맛나지만 자르지 말고 통으로 가져와서 집에서 두툼하게 찢어서 버터 올리고 구워보세요. 물론 갓 나온 빵 그냥 먹는게 젤 맛나죠. 아무튼, 통으로 찢어드세요. 다릅니다.', 42, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '대학생때 자주 왔던 집인데 진짜 십몇년 만에 다시왔네요! 여전히 영업하고 계셔서 옛추억에 잠김🥹 세월이 흘러 여러 훌륭한 빵집들이 많아졌지만 그래도 촉촉한 식빵 한입 먹는 순간 역시는 역시다! 밤빵도 맛있었어요 ㅠㅠㅠ 오래오래 장사해주세요❤️ 근처 우유집에서 우유랑 같이먹으니 꿀맛', 33, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '참새방앗간처럼 매일 드나드는 제과점, 어떤 메뉴 하나 빠지지않고 너무 맛있어요. 한동안 밤식빵에 꽂혔다가 요즘은 호두모카빵이 최애입니다. 쉬는 날을 걱정해서 냉동실에도 비상으로 쟁여두고 먹어요 ㅎㅎ', 16, 1, 'GOOD', SYSTIMESTAMP);
