INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '빵굽는 냄새가 어찌나 향기로운지 그냥 지나칠 수가 없게 만드는 마력이 있어요. 닭가슴살처럼 결대로 찢어지는 글루텐이 아주 매력적입니다. 식빵은 기본이고 밤빵도 예술입니다.', 29, 1, 'GOOD', SYSTIMESTAMP);
