INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '참새방앗간처럼 매일 드나드는 제과점, 어떤 메뉴 하나 빠지지않고 너무 맛있어요. 한동안 밤식빵에 꽂혔다가 요즘은 호두모카빵이 최애입니다. 쉬는 날을 걱정해서 냉동실에도 비상으로 쟁여두고 먹어요 ㅎㅎ', 25, 0, 'GOOD', SYSTIMESTAMP);
