INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '이집은 오후에 가면 빵들이 없어지는 유명한 가게더라고요. 그래서 먹어 봤는데 정말 유명 할만한 맛이었어요. 빵들이 하나같이 부드럽고 맛있었어요. ^^ 사장님 또 뵈요. ^^', 6, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '참새방앗간처럼 매일 드나드는 제과점, 어떤 메뉴 하나 빠지지않고 너무 맛있어요. 한동안 밤식빵에 꽂혔다가 요즘은 호두모카빵이 최애입니다. 쉬는 날을 걱정해서 냉동실에도 비상으로 쟁여두고 먹어요 ㅎㅎ', 30, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '참새방앗간처럼 매일 드나드는 제과점, 어떤 메뉴 하나 빠지지않고 너무 맛있어요. 한동안 밤식빵에 꽂혔다가 요즘은 호두모카빵이 최애입니다. 쉬는 날을 걱정해서 냉동실에도 비상으로 쟁여두고 먹어요 ㅎㅎ', 114, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '애정하는 식빵집!!! 빵집 입구에 가득 쌓여있는 통식빵들만 봐도 행복한 곳이에요. 지인들에게 한번씩 선물로 사다줄정도로, 여러사람에게 맛보여주고 싶은 식빵이에요. 노부부 사장님이 운영하시는 곳이라 빵 만들고 판매하시는일이 힘에 부치시면 어쩌나 싶어 걱정되다가도 오래오래 맛있는 식빵 맛보여주시기를 바라는 이기적인 손님이 되고는 합니다.', 63, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '여러번 지나갔는데 문닫혀있었는데 드디어 식빵ㅈ구매했어요. 추천받아 밤식빵도ㅈ구매했고 크지않아 좋았어요. 일찍 문열고 2시츰 닫는거같아요.', 23, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '식빵, 소보로, 호두모카 구매. 오래전 서교동 살때 식빵 사러 가끔 갔었는데, 방송 나오고 핫해져서 오랫만에 갔더니 가격 많이 올랐네요ㅠ 소보로 작아졌어요, 호두모카는 달지않아 순삭예요!', 39, 1, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '저녁을 과하게 먹어서 당일에 못 먹고 다음날 식빵 먹었는데도 너무 촉촉하고 맛있어서 한번에 3개 사오길 잘한것 같아요!! 다음에 또 식빵 사러 갈게요!!', 88, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '다들 맛잇다고 극찬해서 맨날 도전햇지만 늦게가서 품절이엇는데 오늘는 운좋게 일찍갓더니잇어서.구매했어용 넘넘 맛잇네용 우유식빵이넫 고소하고 밤식빵도 삿어욬ㅋㅋ굿굿', 17, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '오랜만에 제대로 된 빵을 먹은 것 같아요! 소보루와 완두빵, 우유식빵을 구매 했습니다. 완두빵을 먹었을 때 오오! 빵도 쫄깃 촉촉하면서 맛있다라고 생각했습니다. 소보루 빵을 먹었을 때 와.. 이렇게 촉촉하고 쫄깃한 소보루 빵 언제 먹어봤더라 하면서 다 먹었는데 마지막으로 우유식빵 정말 촉촉하고 쫄깃하고 슴슴한 맛이 일품이었습니다!! 밤식빵을 구매하고 싶었지만 직전에 다 팔렸다고 해서 우유식빵을 샀는데 또 사러갈 것 같아요!! 너무 맛있게 잘 먹었습니다🫶', 17, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '우유식빵하면 생각나는 이 곳! 이날은 모카모닝빵이 더 먹고싶었는데, 늦게 갔더니 품절이네요ㅜㅜ 그래도 좋아하는 우유식빵 사 와서 맛있게 먹었습니다^^', 16, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '시간 날 때마다 들러서 빵을 사는 곳입니다 우리 동네거든요 빵은 담백하고 특별히 맛있다고 느끼지 않는데 매일 먹을 수 있을 거 같애요 빵을 좋아하시는 분들은 여기 빵 만족하시더리구요. 저는 빵보다 면을 좋아해서 아직까지는 잘 모르겠지만 밤 늦게 먹어도 맛있어요 저는 개인적으로 밤식빵 추천 드립니다', 24, 9, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '신촌의 올드 갱스터 그 자체입니다. 동네의 명물. 늦게 가면 아무 빵도 없다. 힙스터란 말이 존재하기 이전에도 이곳은 힙한 빵집이었습니다.', 116, 26, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '길 가다가 빵 봉지 보고 검색해서 찾아갔어요. 역시 제 판단은 틀리지 않았습니다. 이렇게 맛있는 생 우유식빵 오랜만에 먹어봐요.', 27, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '경의선길 산책의 즐거움😊 갓 구운 네모네모 식빵이 있기 때문이죠!! 재료비가 오르면서 식빵값도 조금 올랐지만, 이 정도 맛에 이가격이면 선녀입니다❤️ 노부부 두분이서 하시는데, 만드시는 노고를 보면 저는 감사히 사먹지만, 과연 이 가격에 수익이 나오실까 걱정되는 마음입니다.', 9, 10, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '식빵 2천원대 팔던때부터 다닌 빵집. 요즘은 프리미엄 베이커리 때문에 입맛을 올려놔서 예전만큼의 감동은 아니지만 닭살처럼 찢어지는 쫀득한 식빵은 긴세월 한결같은 맛이라 애정하는 집입니다. 소보로는 땅콩맛이 없어지고 얇아져서 쏘소 모카완두빵은 다른곳에는 없는빵이라 먹어볼만 합니다. 다음번에는 식빵만 구입할듯 싶어요', 16, 0, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '식빵이 유명하다고 해서 꼭 한번 가보고 싶던 곳이예요 소보루, 밤식빵, 일반 식빵 다 부드럽고 맛있습니다. 시간이 잘 안맞지만 기회되면 꼭 다시 가보고 싶어요', 1, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '친구가 10년전 좋아했던 식빵집! 아직도 그 골목. 그 자리에 우뚝 있어 반겨준 김진환제과점. 건물은 세월의 흔적이 있지만 따뜻하게 반겨주시는 사장님 부부~아이들 줄 소보루도 구입했어요. 이웃들 나눠먹으려고 여러개 들고 왔어용~♡', 45, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '아침에 갓나온 고소한 빵냄새가 기분 좋게해요.오늘은 점심지나서 방문했는데 빵이 몇개 안남았더라구요. 컷팅된것1개 통식빵1개 구매했어요.아침의 따뜻하고 촉촉한 감동은 아니지만 쫄깃한 식감은 여전히 좋았어요. 혼자먹기에 양이 많아서 냉동실에 보관했다가 해동후 렌지에 10초 돌리니 아침에 먹었던 맛이랑 똑같았어요.계속생각나니깐 냉동실에 소분해서 넣어두고 먹어도 굿~굿~! 아무것도 안바르고 안굽고 그냥 먹어도 정말 맛난 식빵이에요.', 38, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '식빵이 정말 맛있어요 아무것도 안들어있는 기본 식빵인데 뭔가 다른느낌! 일찍 소진되니 늦어도 점심시간전에는 가야 안전하게 살수있는어요 ㅎㅎ', 30, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '식빵으로 토스트를 먹고 싶을땐  항상 여길 갑니다. 특히 아침에 가서 갓나온 따끈따끈한 식빵을 결따라 찢어서 먹으면 부드럽고 쫄깃한것이  최고입니다. 두번째로 좋아하는건 소보로빵입니다.  다른 체인빵집보다 훨씬 맛잇고 가격도 저렴해요 밤식빵이야  밤폭탄식빵들이 있어서 임팩트가 덜하지만 가격이 용서합니다. 사장님이 동경에서 배우고 오신걸로 아는데  확실히 동네 빵집과는 다릅니다.  같은 메뉴인데도요 식빵을 제외하곤 빠르게 매진되니 한시전에는 가시는게 좋습니다.', 11, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '식빵 전문점으로 매번 신촌을 갈때마다 들렀지만 빵이 없거나 문을 닫은 상태, 이번엔 경의선숲길로 산책갔다가 득탬. 유명한건 알지만 이제 처음 사온 식빵. 예전엔 식빵만 팔았는데, 지금도 다른 빵도 좀 있네.', 37, 10, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '백만년 만에 들른 김진환 제과점. 종류가 다양해져 골라먹는 재미가 있네요. 정겨운 추억의 그 맛 그대로라 반가웠습니다. 밤식빵 많이 달긴 하지만 밤도 나름 실하고요! 근처가면 또 들를게요 ㅎㅎ', 43, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '지나가다 빵냄새가 너무 좋아서 그냥 들어가서 밤식빵을 샀는데.. 빵이 너무 맛있어요!! 매장에서 초고수의 느낌이 남 다음에는 식빵을 꼭 사야겠어여', 19, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '말하면 다 아는 동네 유명 빵 맛집이죠. 처음 이사와서 경의선숲길 산책하는데 하나씩 들고 가시는 빵봉지 보고 검색해서 찾아갔었던 곳이에요ㅎㅎ 쫄깃한 식빵 찢어서 커피랑 먹으면 입가에 웃음이 나요ㅎㅎ 매장에 포장만 가능하고 몇종류 없지만 빵들은 다 자기만의 맛이 있어요. 유명 빵집이 자꾸 생기는며 점점 사악해지는 빵값에 착해져 보이는 곳이기도 하답니다~~', 117, 21, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '식빵 맛있어요 평일 12시 30분인데도 우유식빵이랑 밤식빵 밖에 안 남았네요 호두모카빵 궁금했는데ㅎㅎ 밤식빵 밤 살캉하고 살짝 달달해요 모카앙금빵 모카향 나는데 식빵이 제일 맛있네요', 68, 12, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '밤식빵도 맛있는데 빵오나오는 시간대가 안맞아서 우유식빵만 사왔어요~ 너무 쫄깃쫄깃하고 부드러워서 냄비를 필요도없이 그냥 먹어도 맛있어요~', 9, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '오래된 식빵맛집. 우유식빵보다 밤식빵이 더 쫄깃하고 맛있었어요! 굳이굳이 찾아갈정도까지는 아닌데 가까우면 일주일마다 갈듯합니다. 뽀송쫄깃우유식빵 :)', 34, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '지인소개로 알게되서 아침부터 방문.도제식빵 좋아하는 1인으로 이 빵을 접했을때..개인적으로 식감이 더 좋아요. 촉감은 부들부들 야들야들 촉촉함이 느껴지는데 입안에 넣었을때 쫄깃함이 감동이네요. 왜 길빵하는 알겠어요.사자마자 그 자리에서 계속 뜯어먹게 되네요. 굽지않고 쨈.버터  바르지않아도  그냥 그 자체로 존재감이 확실해서  오랫동안 유지하고 아직도 줄을서는지 알겠네요. 소보르랑 밤식빵도 맛나는데 여기는 식빵이 1등!!', 29, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '이집 빵이 좋아서 다닌지 10년째 되네요... 멀어서 매번 일부러 오지는 못하지만 근처 오게되면... 남편이랑 차타고 가면 꼭 들리는 집이에요... 오랫만에 통식빵, 식빵, 아몬드소보로2, 앙금빵1, 완두빵 샀어요.... 아주 좋아요~', 58, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '오래된 동네 빵집인가봐요 이른 아침에도 품절된 빵이 많고 사람들이 계속 ㅇ와요 근처만 가도 이 집 빵봉투 들고 다니는 사람이 많네요 식빵이랑 단팥방이랑 몇종류 없긴해요', 39, 1, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '말도 안되는 가격과 맛과 양이예요. 갓 나온 빵은 앉은 자리에서 다 먹을 수 있어요. 전국 최고의 식빵집입니다. 소보루빵도 맛있어요.', 74, 18, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '우유식빵, 밤식빵, 호두식빵, 소보루까지 14500원. 가격이 착한 빵이네요. 밤식빵에 밤도 많이 들었어요. 지나는 길이라면 한 번 들러볼 만한.', 39, 6, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '오전에 갔는데 벌써 우유식빵 나온 게 다 팔리고 20분이나 기다려야 한다기에 일단 소보로빵과 밤식빵을 데려왔다. 밤식빵은 처음인데 이것도 참 맛있다. 역시나 소보로빵은 사자마자 바로 먹었을 때 개꿀. 안은 포삭포삭 부드럽고 겉은 갓구운 바삭함이 그대로다.', 138, 92, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '우유가 듬뿍 들어간 일본식 식빵 으로 유명한 곳이이예요~ 뜨끈한 갓나온 식빵을 통째로 뜯어먹는 맛이 정말 좋구요~ 식빵반죽으로 만든 달달한 밤을 쏟아부은것 같은 밤식빵, 아몬드가루 넉넉하게 넣은 소보로, 단팥빵~ 오픈 부터 지굼까지 쭉 단골이네요~', 83, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '평이 너무 좋아서 기대 한가득하고 아침 일찍 방문한 곳. 물론 맛은 있었다. 하지만 굳이 찾아가서 먹을 정도는 아니고 근처고 지나가던 길이고 식빵이 필요하면 사먹을 정도', 47, 6, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '추억이 들어 있어서 그런지 아직 까지도 제 인생 에서 가장 맛있는 식빵이에요 흰우유랑 먹으면 걸어다니면서 식빵 한통 이 뭐야 두통 뚝딱이에요', 37, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '식빵의 신세계를 알려준 추억의 빵집. 아몬드소보로빵이 특히 맛있어서 자주 갔는데 오랫만에 방문한 오늘은 빵의 쫀득한 식감도 아몬드의 고소함도 예전같지 않아서 조금 아쉬웠습니다.', 52, 13, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '신촌역/식빵맛집☞김진환제과점 -동경제과제빵학교출신, 96년부터 오로지 식빵만을 주력으로 만들어온 식빵장인이 직접 만들고 판매하는 빵집! 우유식빵(4.4/통식빵): -겉은 크리스피×속은 보들 촉촉(축축아님)★아주 탱탱×고소한향×달짝지근맛 *다큐영화 펠리칸베이커리가 떠오르는 ★평일 낮3시. 매대에 8개 정도 식빵이 남아있었습니다. *통식빵or슬라이스된 것을 고를것이냐 우물쭈물하는데..사장님이 오셔서 도와주셨습니다. ★식빵선택가이드 -쨈을 바를거면☞슬라이스. -빵만 먹을거면★통식빵! ★★통식빵 맛있게 먹는법을 알려주셨습니다★★ *바로 먹을만큼만 도톰하게 컷팅해서☞★전자렌지에 15초(절대오래데우지말기)데운후.결대로 뜯어먹기! ★꼭 렌지 데워드세요! 식빵이 살아나요! 맛이 달라요', 43, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '겉바속촉 옛날식 소보로빵을 찾는다면 이 빵집이 정답이다. 소보로빵과 함께 불티나게 팔리는 우유식빵 또한 이집 대표선수다. 보통 오후에 가면 이 둘은 품절되는 경우가 다반사다. 경의선 철길공원 근처에서 오랜기간 빵돌이 빵순이들의 사랑을 받고 있는 집이니 근처에 들른다면 꼭 먹어보길 강추!!!', 48, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '코로나19걸리고 난 후, 미묘한 맛을 잘 못느꼈는데...이곳 식빵 먹고 잃었던 미각이 돌아오는 느낌!! 그냥 식빵하나만으로도 이렇게 맛있구나 느낄수 있는~', 40, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '댕댕이랑 아침산책하며~ 오랜만에 이 제과점에 들렸어요~ 예전에 참 자주 갔었는데..아직도 하시네요^^ 앙금빵이랑 식빵이랑 소보로 사서~ 룰루랄라♡ 소보로빵은 보슬보슬 너무 맛나요^^ 소보로가 바싹하지않으면 속상한데 여긴 참 바싹해서 좋습니다♡ 앙금빵도 앙금이 너무 달지않아서 좋네요!! 앙금빵 사이사이에 있는 견과류가 씹히는 느낌이 좋아요!! 작은 가게지만 소소한 정이 느껴집니다. 언니가 친절하세요^^ 식빵은 아직 못먹어봤지만....부드럽고 쫄깃한 식감이 기억이 나네요^^', 34, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '매번 산책길에 보았는데 빵이 없었어요 오늘은 운좋게 유명한 우유식빵과 소보로빵까지 구매하여 먹어보았어요 식빵은 촉촉하고 퐁신?한게 맛나며 소보로빵은 겉은 바삭하니 맛있었어요', 28, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '우유식빵으로 유명한 김진환 제과점입니다 금방 나온 식빵을 통/조각으로 가져가실수 있어요 매장에 테이블이 없어서 경의선숲길에서 식빵 먹었는데 빵도 따끈, 빵냄새도 너무 좋고 넘 맛있었어요 👏🏻', 44, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '오랜만에 들렀는데 여전히 맛있네요. 우유식빵, 소보로만 있었는데 이젠 종류도 좀 다양해졌고. 밤식빵이 쪼매난게 딱 1인분용 ㅋ 식빵은 통째로 뜯어먹어야 제 맛', 13, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '유명해서 가봤는데 명불허전 이네요 맛있어요 일단 맛있는빵 맛없는빵 귀신같이 골라내는 울딸줬는데 안 남기고 빵 하나를 다 먹네요 자식입에 들어가는게 젤 행복한 애미 ㅋ 담어 또 갈께요 번창하세요', 15, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '우유식빵(4200)사러 방문 맛은 촉촉하고 부드러운 식감으로 우유향이 살짝 나는 맛! 사장님 가족분들? 친절하진 않으심. 종류 8가지이고 주력 메뉴 식빵임. 가게 한쪽에서 계속 제빵하고 계시는게 보이고 코시국이지만 마스크는 안 쓰시고..아쉬움ㅠ', 45, 10, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '식빵이 땡겨서 옛 기억을 더듬어 검색하고 출근 길에 들러 빵 구매를 했습니다. 맛있네요~  코 끝이 찡할 정도로 추억의 맛입니다^^', 41, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '식빵이 진짜 맛있어요 먹어보면 다른 식빵이랑 달라서 다들 어디서 샀냐고 물어볼정도에요 부드럽고 촉촉해서 맛있고 나온지 얼마 안된 따끈한 통식빵 뜯어먹는것도 별미에요 식빵 좋아하시는 분들은 꼭 드셔보세요 취향따라 통식빵이나 컷팅된걸로 구매할 수 있어요 소보루 빵이나 모카식빵 이런 빵도 소량 팔긴하는데 가장 맛있는건 기본 식빵입니다 오래오래 장사해주세요', 41, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '가성비 그리고 가장 빼놓을수 없는 맛!! 통으로 먹을수 있는 식빵이라니🍞 진짜 식빵 맛집이 진정한 빵맛집 소보루도 궁금했는데 늦게 가서 그런지 품절이었네요 🥲 여튼 빵순이 입장에선 행복합니다💕 살작 렌지에 데펴서 커피 or 우유랑 먹음 금상첨화', 69, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '8시부터 영업한다고 안내되어있어 일찍갔더니 11시반경되어 빵이 나오기시작~많이기다렸고 주인분들이 매우 무뚝뚝하여 인상에 깊이 남았네요~내돈내고 시간걸려 구입하러갔는데 가사까지하고 사와야되는걸까요? ㅎㅎ', 5, 0, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '식빵만 팔기도 소보로빵이 추가되고 지금은 밤식빵 등 소소한 몇 가지가 추가되었는데요. 여전히 다 맛있습니다♡♡ 진짜 우리동네의 자랑이예요. 향도 얼마나 좋은지~~', 12, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '오랜만에 들렀더니 직원 분이 굉장히 친절하시네요. 우유식빵이야 워낙 유명하고, 소보로가 많이 달지 않으면서 겉바속촉이라 맛있어요.', 76, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '제 입맛에는 밤식빵이랑 팥빵이 제일 맛있습니다! 빵들이 다 옛날스타일이고 식빵이 촉촉해서 토스트해먹기 좋습니다 아침에 창문열면 빵냄새가 나고 지나가다가 사람들 줄안서있으면 저도 모르게 들어가서 사게 됩니다ㅎㅎ 일요일 휴무에 보통 세시면 솔드아웃이라 참고하세용', 102, 25, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '식빵을 뜯어먹는게 이렇게 맛있었나..! 아침에 근처를 지날때면 빵냄새에 홀려 사먹는경우 무척 많아욬ㅋㅋㅋㅋ 소보루도 맛있고 완두앙금빵도 좋습니다. 저역시 김세권에 거주함에 감사하며…!', 41, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '바닥에떨어진거 한쪽에올려둬따가 아줌마가 제차례에 뒤돌아털어서 포함해주신거같아서 기분이 안좋았어요 뒤로 몇분기다리셔서 그냥받긴했는데 그렇게하실꺼면 손님없을때하셨어야죠ㅜㅜ', 125, 22, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '쫀득한 식감의 맛있는 우유식빵 ! 매우 맛있고 모카완두빵이 특히나 내 스타일! 달달한 완두 가득하고 마지막 모카의 쌉쌀한 맛이 좋음! 쇼콜라는 보들보들 부드럽고 가벼운 빵이었다! 다크한 초코맛이 맛있음! 식빵 제외한 모든 빵에 호두가 들어가있고 전체적으로 식감이 매우 좋고 담백함! 그리고 사장님이 매우 친근+친절 하셔서 기분이 매우 좋았어요', 10, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '집 주변에 김진환 베이커리가 있다는 건, 김세권에 산다는 건,, 주말 아침의 확실한 행복. 오래 빵 구워주세요. 감사합니다. 우유식빵과 소보로 추천👍', 34, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '식빵장인의 식빵가게. 고소한 빵냄새 솔솔. 특별하진 않지만 ,클래식한 갓구운 식빵을 느낄 수 있음. 처음 식히고 상온에 3~4일 보관했는데 파x바게트 식빵과는 다르게 빠르게 곰팡이가 핀 것을 보아 신선한듯.', 32, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '정말 빵 매니아라면 김진환베이커리 식빵을 영접해야하죠^^ 오늘 제가 마지막빵을 기적처럼 사게됐답니다. 사장님도너무너무 친절하시고 인상도 너무 좋으시고 저이쁘다고 소보로빵도 하나 슥 주심ㅋㅋㅋ최고!', 38, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '소보로빵이랑 밤식빵 맛있어서 매주 사먹었어요 빵이 너무 맛있어요..ㅋㅋㅋ 근데 주인아저씨 손님들 앞에서 코파시는건 지저분해 보여용', 34, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '보드랍고 쫀득한 클래식 식빵이 있는 곳. 썰어서 토스트로 먹어도 좋고, 통으로 뜯어먹어도 맛있어요. 아 물론 밤식빵과 소보루도 별미입니다.', 28, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'CLASSIC');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '항상 가려고 했는데 가깝지만 위치가 애매해서 못가고 있었어요. 식빵은 어릴 때 제빵기로 엄마가 만들어주던 느낌 쫄깃합니다 소보루 맛있대서 샀는데 그냥 보통 맛인 것 같아요.', 114, 22, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '아주 옛날에 이름 알려지기 전부터 사먹었는데, 식빵전문점이 많이 생겨서인지 찢어먹는 쫀득한 맛이 있는데,,,,이상하게 맛이 옛날보다 떨어지네요. 사장님이 다 직접하시는 거 같은데 말이죠...', 265, 90, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '아 여기 진짜 그냥지나칠수가 없다. 모카식빵은 정말 냉동시켜가지고 커피마실때 꼭 같이 먹어줘야만할것같음. 소보루 갓나온 따뜻한거 먹고 너무 맛남. 밤식빵엔 밤이 너무마나', 26, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
