INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '김진환 제과점'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '회사끝나고 가면 항상 재료소진이네요ㅠ 정말 맛있는 빵집 특히 소보루빵 정말 최고로 맛있어요 어르신들도 호불호없이 다 좋아합니다', 8, 4, 'GOOD', SYSTIMESTAMP);
