INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '케이크가 진짜,,,,,,,,,,,,너어어어무 촉촉하고 맛있어요,,,,,,,,,,에바임 진짜 너어어무 맛있어요🤦🏻‍♀️ 카페라떼는 괜찮았는데 아인슈페너는 산미가 더 느껴지더라구요 라떼 오트밀크로 바꿔 먹었는데 너무 꼬소하구 부드럽고 굳굳❤️❤️❤️❤️❤️', 68, 13, 'GOOD', SYSTIMESTAMP);
