INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '친절한 느낌을 받기 어려운 응대. 평범한 커피맛. 디저트는 맛있었어요. 공간은 깔끔한 느낌이예요. 통창이라 시원시원한 뷰입니다. 한번 와본걸로 족행', 16, 3, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '따스한 햇빛이 가득 들어오는 화이트 톤의 이쁜 카페입니다. 케익은 너무 달지 않게 촉촉하니 정말 맛있습니다. 딸기도 큼지막하니 좋았네요 일요일 1시쯤 갔을땐 한산하니 좋았는데 2시부터 사람이 많아져 북적북적하더라고요 그래서 그런지 매장 이용 제한 시간이 있었습니다 평일 3시간, 주말 2시간', 33, 8, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '분위기도 돟고, 재즈음악 흘러나와서 편한 분위기예요! 다들 독서하거나 대화하고 시끄러운분위기가 아니라 좋습니다. 커피도 산미가 없고 고소해서 맛있구요!! 특히나 케이크 디저트 종류 진짜 맛있어요❤️❤️❤️❤️ 케이크 진짜 촉촉하고 딸기도 왕커서 맛있어요! 왕추천추천입니다!', 432, 29, 'GOOD', SYSTIMESTAMP);
