INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '가게가 깔끔하고 예뻐서 시간 보내기 좋았어요 라테도 꼬숩고 맛있더라구요! 원하던 케이크 종류는 없었지만 바나나브레드도 곁들여먹기 좋았어요', 65, 15, 'GOOD', SYSTIMESTAMP);
