INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '두번째 방문하는 이혜와서울카페 인데 ~여전히 차분한분위기에 사장님은 너무 친절하시고 예쁘세요 ^^🩵 오늘은 아메리카노와 얼그레이케이크한조각 같이 시켜봤는데~굿  👍 아메리카노는 산미있는 맛이고 ,얼그레이케이크는 얼그레이향이 너무 강하지않아서 좋았어요. 촉촉 한 쉬폰 빵에 크림도 부드러워서 입안에서 녹아버리는 맛이였어요 ㅎㅎ 저번에는 밀크티랑 버터토스트를 먹었는데 모든 디저트와커피 모두 완벽한 곳같아요 ㅎㅎ☺️', 12, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
