INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '주말 1시 반 정도에 갔는데 다행히 손님이 별로 없어서 조용히 시간 보냈는데 2,3시 될수록 만석이더니 웨이팅까지 있습니다. 주말에 혼자 조용히 시간 보내려면 2시 전에 다녀오면 좋을 것 같고, 2시 이후로는 웨이팅 있을 수 있습니다. 버터 토스트 진짜 단짠 조합으로 너무 맛있었어요. 계속 생각나는 맛입니다. 햇볕 좋은 날 방문하니깐 더 좋았어요.', 11, 0, NULL, SYSTIMESTAMP);
