INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'NATURE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '연남동 골목 안 쪽에 있는 조용한 카페. 커피 맛은 생각보다 연해서 조금 아쉬웠지만, 검은숲 케이크는 맛있게 먹었어요🙂 초코 크림이 꾸덕하고 달달해요🍫 공부하러 오는 분들도 있고 카페가 전반적으로 분위기가 차분해서 좋았습니다', 27, 3, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
