INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '저는 12-1시 사이에 평일에 방문했어요. 리뷰에서도 혼자 오시는 분들 많다고 본 것 같은데, 제가 갔을 때도 혼자 오신 분 1좌석 있었어요. 주말이 아닌 때에 조용하게 커피 한잔 하실 분께 완전 추천합니다! 그리고 저는 라떼를 시켜서 아주 특별한 맛까진 아니었어요. 다만 디저트가 맛있었어용👍👍👍(케이크도 맛있다고들 하시더라구요) 오시면 느끼실 거예요. 자주 찾게 될 것 같은 카페란걸! 저도 오늘 첫방문했는데 다시 오고 싶다고 생각했어요!', 46, 8, 'GOOD', SYSTIMESTAMP);
