INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '처음에 카페 위치 찾는데 조금 힘들었는데 한 건물 위에 카페 이름이 작게 적혀있었어요! 버터토스트가 유명한 것 같아서 먹었는데 맛있었어요 ◡̈ 혼자 조용히 책 읽으시는 분도 계셨는데 혼자 와도 좋을 것 같아요', 118, 22, NULL, SYSTIMESTAMP);
