INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '친절하다는 리뷰가 많은데 의아합니다.. 제가 갔을 땐 다른 분이 계셨던걸까요? 꼭 와보고 싶었던 카페인데 디저트는 맛있었어요 근데 모든 응대가 전부 불친절해서 기분 별로였어요', 44, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '프렌치 토스트 먹으러 방문한건데 토스트도 맛있었지만 얼그레이케이크가 너무 맛있었어요!!🤍 다음에 홀케이크 이용해보고 싶어요! 커피도 당연히 맛있었습니다😊', 59, 16, 'GOOD', SYSTIMESTAMP);
