INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '1.깔끔한 화이트톤 실내인테리어 2. 친절한 사장님 3. 넓지않은 매장 4. 디저트가 맛있음 5. 2층이라 채광이 좋고 뷰가 괜춘함', 65, 17, 'GOOD', SYSTIMESTAMP);
