INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '아 사진이없네요ㅠ 토스트라길래 기본적으로 생각하는 버터토스트 생각했는데 완전 미니버전이에요 물가상승을 절실히 느꼈답니다 (내월급빼고 다올라ㅠ) 커피랑 토스트는 너무 맛있었어요', 26, 3, NULL, SYSTIMESTAMP);
