INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '얼그레이 케이크 빵 자체가 부드럽고 얼그레이 음료랑 잘 어울려요ㅎㅎ 연남동 카페  다른곳은 시끄럽고 정신없는 분위기인데 여긴 대화하기도 좋고 창이 탁 트여서 좋아요😊😊', 37, 7, 'GOOD', SYSTIMESTAMP);
