INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '통창의 밝은 채광과 조용한 음악이 흐르는 카페예요. 책 읽기도 좋고 혼자 가서 작업하고 시간 보내기에도 좋아요〜 아메리카노는 산미없이 디저트랑 곁들이기 좋은 무난한 맛이고 디저트로 같이 먹은 바나나브레드도 촉촉하니 맛있어요！어쩜 찾아오는 손님들도 다 카페랑 어울리는 분위기인지..홍대에서 혼자 카페가고 싶을때 제일 먼저 생각날 것 같아요😌', 80, 18, 'GOOD', SYSTIMESTAMP);
