INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '예전부터 가고 싶어서 카카오맵에 저장해뒀었는데 조용하고 너무 좋았어요 ! 디저트랑 음료 맛있고 창가에 앉았더니 멋진 뷰도 있습니더 ... 카페 인테리어도 예쁘고 사장님도 친절하셨어요 너무 좋은 공간 ..', 19, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
