INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '깔끔한 분위기가 정말 마음에 드는 카페예요!! 2층 올라가는 길이 어두운데, 매장 들어서는 순간 느껴지는 화사함에 반해버렸어요. 비 오는 날에 방문했는데도 창이 트여 있는데다 화이트톤 인테리어 덕에 매장이 정말 밝았어요. 좌석마다 메뉴판이 놓여 있는 센스도 마음에 들고, 매장 관리도 정말 잘 되어 있어요. 매장에 전용 화장실이 있어서 머무르기도 편하고, 좌석도 골고루 있어서 혼자서도 방문하기 좋아요. 무엇보다 디저트가 정말 맛있어요... 케익이 하나도 안느끼하고, 당도도 과하지 않게 적당하고, 시트가 정말 폭신하고 부드러워요. 케익이랑 커피 가격이 꽤 쎈편인데도 돈이 아깝지 않았어요. 이 정도 퀄리티의 케익이라면 빵도 기대돼요. 재방문 의사 무조건 있고, 기회가 된다면 홀케익도 주문해보고 싶어요!', 34, 1, 'GOOD', SYSTIMESTAMP);
