INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '가기 전에 생각한 느낌이랑 가서 딱 봤을 때 느낌이 좀 달랐는데, 또 앉아서 머무는 느낌도 달랐어요 ㅎㅎㅎ 자두티 청을 엄청 잘 담으셨나봐요 진짜 맛있게 먹었습니다.', 17, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '여긴 진짜 몰라서 못가지, 알고 지나친다면 ㅜㅜㅜ 안돼!!  꼭 가세요, 여기가 바로 빵 맛집 뷰 맛집 입니다. 진짜 사장님이 직접 만드시는 빵 그리고 가격도 너무 착해요ㅜㅜㅜ 꼭 가세요!! 무조건 가야해요! 빵입니다. 메모하세요!', 29, 5, 'GOOD', SYSTIMESTAMP);
