INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '아메리카노는 보통 아메리카노 맛이었구 홍차 라떼 달달하고 맛있었어요. 그리고 빵 진짜 맛있어요. 맛있게 구워주셔서 구울 때부터 냄새가 식욕을 자극합니다!', 44, 10, 'GOOD', SYSTIMESTAMP);
