INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '버터토스트 비주얼보고 찾아갔습니다! 쫀득달달하니 정말 맛있어요,,🤤 사장님도 친절하셔서 기분 좋게 커피 마시고 나왔네요! 다음에 또 방문하고 싶어요~!', 95, 19, 'GOOD', SYSTIMESTAMP);
