INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '분위기도 너무 좋고 깔끔해요 ☕️ 그리고 테이블 간격도 적당히 있어서 다닥다닥 안 붙어있어도 되서 좋아요☺️ 치아바타도 너무 맛있고, 커피 산미가 적당히 있어서 계속 맛을 음미하게 되네요 자주 올거 같아요', 50, 7, 'GOOD', SYSTIMESTAMP);
