INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '인테리어가 깔끔하고 분위기가 너무 좋아요...🤍 주말 오후에 방문해서 사람들이 많았는데 개인적으로 평일 오전에 혼자 방문해서 책읽거나 노트북 작업해도 너무 좋을 거 같아요🫧', 29, 8, 'GOOD', SYSTIMESTAMP);
