INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '아아랑 케이크 먹었는데 맛있고 얼그레이 케이크는 촉촉 그 자체!! 카페가 넓지는 않은데 테이블 간격이 적당해서 답답한 느낌 없고 조용하고 분위기 좋고 깔끔해요', 65, 14, 'GOOD', SYSTIMESTAMP);
