INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '의자도 편하고 인테리어도 예뻐요 겨울에 카페 가면 발이 시린 경우가 많았는데 그런거 전혀 없이 아주 따땃했어요 사진도 잘나오고 분위기도 좋아요! 테이블도 높아서 은근 카공 하기도 좋을것같고 다시 갈 것 같아요', 50, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '정갈하고 담백함의 극치 ❤️‍🔥❤️‍🔥❤️‍🔥❤️‍🔥(4/5) 화이트톤의 심플하고 깔끔한 무드의 카페. 디저트부터 인테리어까지 하나같이 군더더기 없는 깔끔함을 자랑함. 단짠단짠의 버터 토스트가 제일 인상깊다. 단순한 맛으로도 이렇게 짜릿한 맛을 낼 수 있는가에 대한 놀라움의 연속. 다만 아메리카노 커피맛은 조금..애매한 편 주말 2시에 방문했을 때 자리가 꽤 있었지만 얼마 지나지않아 꽉 찼고, 웨이팅까지 하던 새로운 홍대 핫플.', 42, 5, NULL, SYSTIMESTAMP);
