INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '가져다주시는데, 보통 플랫화이트나 아인슈페너 같이 컵작은거 제외하고 입대고마시기 어려운 아메리카노나 라떼는 빨대 안내해주시거나 같이 제공해주시는데, 없어서여쭤보니 바로옆에잇는데 거기서 가져가라고 하고 마시더군요. 전반적으로 조근조근하고 편안한분위기는 아니었고 힘빠지고 불편한느낌이 들었어요. 재방문 의사는없어요', 54, 16, 'BAD', SYSTIMESTAMP);
