INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '케이크 비주얼 보고 꽂혀서 왔는데 너무 맛있어요.. 앞으로 초코케이크 먹고플때 여기 올까봐요🤎 주말이라 사람이 많아서 좌석은 못찍었지만 아늑한 공간이에요ㅎㅎ', 128, 22, 'GOOD', SYSTIMESTAMP);
