INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '연남동 가기전 주택가에 위치한 이층카페예요 단짠 토스트 먹어보고 싶어서 찾아갔는데 맛은 있어요 겉은 바사삭 달달이 속은 포슬포슬하면서 부더러움! 단지 아쉬운건 크기가 작아여 ㅋㅋㅋㅠ 평일 한낮에 오면 조용하게 노트북하기 좋은 곳 같지만 주말은 역시나 사람이 많네요 창가는 사진찍기엔 좋지만 노트북하기엔 자리가 초콤불편함', 43, 9, NULL, SYSTIMESTAMP);
