INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '매우 친절하시구 밀크티도 적당히 달아서 좋구 토스트 크기도 적당한데다가 맛나서 좋아요! 다음에는 토스트도 시키면서 케이크도 같이 주문해서 먹고싶네요!!!', 5, 7, 'GOOD', SYSTIMESTAMP);
