INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '페어 티 마시고 반했습니다..!🤤🤎 처음 먹어보는 맛인데 은은한 바닐라 향에 아삭하게 씹히는 배가 너무 잘 어울려요!!! 민트 레몬에이드도 너무 향긋 상큼하구🥹 집들이 선물로 디저트도 사갔는데 완벽 그 잡채였어요🤤👍', 42, 0, 'GOOD', SYSTIMESTAMP);
