INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '오랜만에 참새방앗간 들렀는데 신메뉴가 또 나왔네요! 올리브 치아바타 샌듸츼 너무 담백하고 맛있어요🥹 사진을 못찍었지만 같이 주신 토마토 피클도 짱맛..🫒🥖🍅✨사장님 적게 일하고 많이 버세요👍', 28, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '정.. 말 .. 좋아요🛋️ 요즘 연남동에서 보기 드문 쾌적한 좌석과 채광 덕에 책읽기 좋은 공간이에요 배가 부른 탓에 디저트 못먹은 것이 아쉬워서라도 다음에 꼭 다시 재방문 하고 싶어요 + 화장실도 예뻐서 세세하게 신경쓰신게 느껴져서 놀랐어요 짱!', 55, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '연남토마에서 밥먹구 바로 근처라 온 카페인데 넘넘 기대 이상이에요 !!❤️ 통창으로 보이는 뷰도 좋고 인테리어도 깔끔해서 너무 좋네요..북유럽 감성 낭낭 사장님도 친절하시두 넘 맛있게 잘먹었더여!!', 122, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MOOD', 'MODERN');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '날씨가 덥고 습해서 고소하고 시원한 커피가 마시고 싶어서 또 왔어요! 한 모금 들이키자마자 바깥 날씨가 싹 잊혀졌어요 ㅋㅋ 새로 나온 검은숲케이크는 겉에 크림이 살짝 달콤쌉싸름하지만 속에 촉촉한 시트랑 은은한 체리가 씹히면서 조화로워요🍒🍒 과일이 들어간 케이크는 별로 좋아하지 않았는데 맛있는 걸 못먹어봐서 그런것같아요!! 이혜와 서울 케이크를 먹고나니 과일 케이크도 맛있다는걸 알았어요🫣', 42, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '오잉 여긴가? 여기 맞나..? 하면서 들어갔는데 맞았어요! ㅎ 당근케잌, 브라우니+아이스크림, 청포도에이드, 밀크티 먹었고 다 맛있었어요! 당근케잌은 크림치즈가 좀 짠 편이었는데(단 음료를 먹어서 더 그렇게 느껴진 걸 수도 있어요) 시트에 견과류가 완전 많이 들어가 있어서 좋았어요ㅠㅠ 브라우니는 포슬한 편인데 많이 달지 않아 호불호 없이 다 즐길 수 있을 것 같아요! 그리고 아이스크림도 브라우니랑 같이 먹기에 적당히 달달해요. 제일 기대했던 거는 청포도에이드였는데 달달상큼하고 탄산이 약하게 있어서 정말 좋았어요! 아 그리고 씨도 없어서 먹기도 편했어요;) 나올 때 싸주신 바나나브레드는 바나나맛이 은은하고 식감은 포슬포슬하니 맛있었구 쿠키는 초코칩 완전 한가득.. ♡ 감사합니다 🤤🤤 다음에 또 방문할게요!', 48, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '''이혜와''가 무슨 뜻일까 찾아보니 ''잘 자''라는 뜻이라고 하네요. 자기 전 건네는 ''잘 자''라는 기분좋은 인삿말처럼 편안함을 주는 카페입니다. 커피도 너무 맛있었고 당근 케이크도 너무 달지 않고 견과류도 듬뿍 들어가 건강한 케이크 같은 느낌이 들어 좋았습니다. 흘러나오는 노래들과 인테리어 분위기도 너무 잘 어우러지는 것 같아요. 홍대 근처에서 커피를 마시고 싶어진다면, 이 카페가 일순위가 될 것 같아요.', 11, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '지나가다가 궁금해서 가보고 싶었는데 드디어 다녀왔어요. 일단 화장실이 깨끗해서 너무 좋았구요. 인테리어 소품 하나 하나 다 신경쓰신게 아주 잘 느껴졌어요. 아기자기아기자기하니 너무 예뻤어요! 그리고 카페 실내가 조용해서 좋았어요. 개인적으로 음악 너무 크게 틀어놓구 대화소리 시끄러운걸 안 좋아해서.. 다들 한명씩 오신 분들이고 작업하시더라구요! 커피가 부드러웠는데 제가 약을 복용하는 중이라 안 진해서 오히려 좋았어요. 찻잔도 이쁘구 같이 주신 설탕도 처음 보는 설탕이었는데 커피랑 잘 어울리더라구요! 가격이 좀 쎄서 자주는 못가겠지만 종종 갈게요 :)', 35, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '지나가다가 카페가 새로생긴 것 같아서 들어와봤는데 신상카페라 그런지 너무 깔끔하고 이쁘고 사장님 친절하시네요! 음료랑 디저트도 다 맛있어요! 베이킹을 매일 아침 직접 하신다고 하시더라구요!! 갓구운 디저트라 그런가 더 맛있구 또 먹으러 와야겠네요ㅋㅋ 사장님 번창하세요!', 58, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '자주 지나가는곳에 공사를 하고 있었는데 카페가 오픈했네요!! 오픈 하신지 몇일되신거 같은데 이제 왔네요!! 가게도 깔끔하고 사장님도 친절하시고 음료도 맛있어요!! 디저트도 맛있어서 내일 직원들 줄려고 포장도 했습니다!! 자주 올게요! 번창하세요!!', 25, 4, 'GOOD', SYSTIMESTAMP);
