INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '커피와 바나나브레드 너무 맛있어요! 공간도 넓고 차분하고 깨끗해서 좋아요 특히 음악이 너무 시끄럽지 않아서 좋습니다,, 오늘 처음 왔는데 다음에 연남동 오면 또 오고 싶어요!', 20, 1, 'GOOD', SYSTIMESTAMP);
