INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '지나가다 간판보고 들렸는데 너무 맛있어요!! 쇼콜라떼 크림 많이 달지도않고 초코랑 잘어울리고 당근케이크 쳐돌이로써 여기가 이제 1등이에요 ( ˃̣̣̥᷄⌓˂̣̣̥᷅ ) 생긴지 얼마안돼서 인테리어도 깨끗하고 가구들이 너무 예뻐용 화장실도 완전 굿', 20, 9, 'GOOD', SYSTIMESTAMP);
