INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '작업실 근처라 지나가다가 입간판 보고 들어왔는데 일단 디저트가 너무 맛있어요! 당케처돌이 잘 먹고갑니다.., 🫧🙂 2층이라 오히려 더 좋은 느낌?  자주 오겠습니다아 !', 25, 0, 'GOOD', SYSTIMESTAMP);
