INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '근처 카페 중에 가장 예쁘고 편안한 분위기가 있는 곳이에요. 작업하기에도 좋고, 수다 떨기도 편안합니다. 아, 그리고 음악이 막 분산되지 않고 부드럽게 들려서 오래 머물러 있기 너무 좋아요.', 63, 17, 'GOOD', SYSTIMESTAMP);
