INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '포슬 당케 맛있게 잘 먹고 왔습니다 히히 아메리카노는 산미가 없었어요 개취로 디저트랑 먹는 아아는 산미있는걸 조아해서 쪼꼼 아쉽스,, 그치만 조용하고 콘센트도 있고 바석이 있어서 혼자 가기도 좋았어요!', 77, 18, 'GOOD', SYSTIMESTAMP);
