INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '연남동 이 일대에 이 정도로 예쁜 카페 없어요. 처음 가 봤는데 오픈한 지 얼마 안 된 곳이더라고요. 2층에 있어서 더 독립되고 조용하고 편안해요. 디저트 다 맛있고 재료에 돈을 안 아끼시는지 당근 케이크 안에 들어간 호두가 존재감있게 씹혀서 감동…❤️ 콘센트 곳곳에 설치돼 있어서 좋고 참, 카페에서 틀어놓은 음악도 넘 울리지 않게 들려서 같이 간 친구랑 대화하는데도 방해가 안 돼서 좋았어요. 다음에 또 갈 거에요 🙂', 91, 26, 'GOOD', SYSTIMESTAMP);
