INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '길가다 더워서 들어왔는데 너무 시원하고 음료 진짜 맛있어요-! 쿠키가 진짜 제 인생쿸희 😛💛 분위기도 좋아서 집중하거나 대화하기 좋아요 ~! 자주올게요', 37, 1, 'GOOD', SYSTIMESTAMP);
