INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '이혜와 서울'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '디저트도 커피도 최고! 매장 인테리어도 너무 예쁘고 깔끔해서 좋아요 ♥ 사람 많은 연남동에 치여서 걷고 걷다가 찾은 카페인데 조용하니 완전 만족스럽습니당', 65, 15, 'GOOD', SYSTIMESTAMP);
