INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엘로 커피바'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '합정역 카페 어딜갈까 하다가, 감도 높은 인테리어와 특이한 티가 있는 엘로에 방문해봤어요! 널직하고 쾌적한 공간 + 창으로 흔들리는 나무 감상 + 완전 맛있는 음료까지.. 보기에듀 넘 이쁜 피치우롱 스파클링 티 먹었어요! 대만 어제 다녀와서 우롱티 반갑게 마셨네요 ㅎㅎ너무 친절하시구 오픈 샌디치두 저렴하고,, 담에 또 방문할게요 🗯️👍', 106, 25, 'GOOD', SYSTIMESTAMP);
