INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엘로 커피바'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '합정역에서 잠깐 작업할 카페 찾다가 들렸는데, 일단 바닐라 라떼 너무 맛있어요!!!! 뭐랄까 부드러우면서 진한 단맛,,? 막 시럽 넣어서 단 느낌보다는 달달한 크림을 섞은 듯한 부드러운 단맛이 나서 너무 취저였어요! 밀크티도 맛있다던데 다음에 또 방문해서 마셔보고 싶어요! 공간은 엄청 크지 않지만 층고가 높아서 답답하지 않았어요 🌿', 59, 17, 'GOOD', SYSTIMESTAMP);
