INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엘로 커피바'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '합정역 근처 일찍 문 여는 카페 엘로 커피바~ 카페 곳곳에 놓여진 예쁜 그림 그리고 통창 밖으로 보여지는 다양한 풍경이 마치 작은 갤러리 같은 느낌을 준다 이 안에서 창 밖을 보면 건물 앞 주차장 공간도 멋진 배경 같이 느껴진다 그리고 제일 마음에 들었던 카운터 뒤쪽 통창 풍경... 나무잎이 바람에 살랑 살랑 흔들리는 모습을 보고 있으면 눈과 마음이 정화되는 기분이 든다. 기본 커피인 H블렌드는 메뉴에 쓰여 있듯이 달콤함과 고소함이 잘 어우러진 밸런스 좋은 커피! 아침 출근길, 점심 먹고 나른 할 때 언제 마셔도 부담없이 잘 어울리는 맛이다 그리고 함께 마셨던 밀크티~ 평소 우유 종류를 안 좋아 하는데 이건 정말 내 입맛에 딱 맞았다. 합정역 근처에서 조용하고 아늑한 카페를 찾는다면 엘로커피바 추천', 89, 16, 'GOOD', SYSTIMESTAMP);
