INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엘로 커피바'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '건축할때부터 눈여겨보던 건물인데 정말 예쁘고 프리미엄음료로 단장한 카페가 생겨서 와봤어요 새로생긴 건물에 깔끔하고 모던한 감성이 더해져서 계속 머물고 싶은 공간이라 완전 추천이요 !!! 밀크티도 근래에 마셔본것중에 원탑이에여 !!! 마냥 달지 않고 부드러운데 깔끔하고 달근한게 제 취향이에요~ 아메리카노도 산미가 있는편이라 고급원두로 만든게 느껴져요 화장실도 진짜 깨끗해서 좋아요👍🏼', 28, 9, 'GOOD', SYSTIMESTAMP);
