INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엘로 커피바'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '전체적으로 아주 깔끔하고 만족스러웠어요💕 공간은 층고가 높은데 분위기 자체는 아늑하게 느껴져요. 음악도 좋고 인테리어도 좋고! 필터커피 한잔, 카페라떼 한잔, 스콘 하나 주문했어요. 필터커피는 평소에 다른 카페들에서 마셔본 적 없는 원두들이라서 좋았고, 정말 정성스럽게 내려주셨어요! 스콘도 다시 따뜻하게 데워서 주셨어요. 하나하나 다 맛있어서 만족스러운 하루의 시작이었어요 ☕️❤️', 3, 8, 'GOOD', SYSTIMESTAMP);
