INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엘로 커피바'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '카페가 너어무 이쁘고 편안하구 사장님이 너무 친절하세요;) 배불러서 디저트는 못먹어봤지만 나중에 와서 꼭 먹어보고싶어요! 요 근처에 카페가 많아 정착할 카페는 없었는데 여긴 다시 와볼것 같아요🥂', 5, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엘로 커피바'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '말차라떼 속든든해지고 좋아요ᩚ 아주맛있었슴니다 매장도 엄청 깔끔 힐링하기좋은 분위기! 커피도 뒷맛도 넘좋고 분위기도 짱임 사진찍기최고최고 건물이 호텔로비처럼 고급스러워서 놀러온거같았어요ᩚㅎㅎ 사장님도 친절하네요ᩚ 자주올거같아요ᩚ~~', 35, 2, 'GOOD', SYSTIMESTAMP);
