INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엘로 커피바'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '커피도 맛있고, 처음보는 신기한 메뉴도 많은 곳. 드립 커피(필터 커피) 원두가 주기적으로 바뀌어서 질리지 않게 즐길 수 있을 거 같아요! 이른 아침부터 열고, 은은하게 풍기는 스콘, 커피 향이랑 함께 책 읽기 딱 좋은 곳!', 34, 8, 'GOOD', SYSTIMESTAMP);
