INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엘로 커피바'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '비 오는날 외출했는데 옷이 젖기도 했고, 커피도 한잔 마실겸 적당히 들어가서 쉴만한 카페를 찾다가 발견했어요. 아아만 마시는데 원두맛이 괜찮네요. 먹을만한 디저트도 몇 가지 있어요. 사장님이 친절하고 혼자 와도 부담스럽지 않은 분위기입니다~', 53, 14, 'GOOD', SYSTIMESTAMP);
