INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엘로 커피바'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '우연히 걷다가 들어온 곳인데 주택가 근처라 한적해서 좋아요~ 만삭 임산부라 애기 나오기전에 데이트할겸 카페갔는데 엄청 친절하게 맞이해주셔서 넘 기분 좋게 음료 마시고 가요 ㅎㅎ', 44, 1, 'GOOD', SYSTIMESTAMP);
