INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엘로 커피바'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '음료도 맛이 좋고, 매장도 넓고 따뜻한 분위기예요. 음료를 만드시는 과정이나 커피를 내리시는 모습을 볼 수 있어서 눈도 즐거웠어요!', 37, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엘로 커피바'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '합정에 이런 스페셜티 커피 카페가 있는지 몰랐습니다 ☺️ 시바리스트 필터를 사용하는 곳 찾기 쉽지 않은데… 덕분에 아침부터 훌륭한 커피 한 잔 합니다✌️', 73, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엘로 커피바'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '골목 지나가다 우연히 발견해서 들어간 곳이라 반신반의했는네 라떼가 너무 맛있어요 ··· 시음으로 받은 밀크티도 얼그레이 향이랑 단맛 밸런스가 완전 적당해서 진짜 맛있었어요! 샌드위치가 좀 달았는데 ㅜㅜ 라떼랑 같이 먹으니까 또 괜찮았아요 ㅎㅎ 아무튼 라떼가 정말 맛있어서 합정 갈 때마다 자주 방문할 것 같아요 !! 사장님들도 친절하셔서 좋았습니다 ૮ ට ̫ ට ა ♡', 13, 1, 'GOOD', SYSTIMESTAMP);
