INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엘로 커피바'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '근처에 새로 카페 생겨서 와봤어요!! 깔끔하고 모던한 인테리어라 대화하기에 좋습니다~ 커피 블렌딩도 고소한 맛 살아있고 맛있어요👍👍 ello 세계관을 채우는 한 명의 손님이 되어보겠습니다!', 16, 8, 'GOOD', SYSTIMESTAMP);
