INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '엘로 커피바'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '말차빈라떼 달달하고 씁쓸하지 않고 부드러워서 좋았어요!! 루꼴라 햄 샌드위치랑 먹으면 단짠 조합으로 최고...♡ 카페 주변에 소음이 없어서 좋아요 다음엔 책 읽으러 가야겠어요 (^з^)-☆', 125, 25, 'GOOD', SYSTIMESTAMP);
