INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '남자친구랑 가챠샵 데이트 도중에 방문했어요 ㅎㅎ 아이들이 좋아할만한 곳인 것 같아요~ 예약 없이 방문할경우 1시간 이용제한도 있더라구요?? 포토존도 아기자기한 시나모롤로 잘 꾸며져 있었고, 커피는 캐릭터 카페 치고 맛있더라구요👍👍 시그니처인 시나모롤 모카 초코 라떼도 맛났는데, 엄~~청 달았어요!! 😆 확실히 아이들이 좋아할 것 같아요 ㅋㅋㅋ 위에 올라가 있는 아이스크림도 단단하지만 맛났구요 아이스크림이 단단해서 조금 흘리고 먹어야 하지만, 맛나게 잘 먹고 좋은 시간 보내다 갑니다 :)', 11, 1, 'GOOD', SYSTIMESTAMP);
