INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '캐치 테이블로 미리 예약하고 방문했습니다! 직원분들도 너무 친절하시고 카페도 너무 귀여워서 힐링 하고 왔습니다 ㅠㅠ 포토존에서 인생샷도 건지고 가세요! 와플은 쫀득하고 생크림이 달달하니 맛있었습니다 ^^', 2, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '아이들과 마지막 방학을 어떻게 보낼까하고 고민하던 중 이곳을 알게되어서 예약해서 왔어요. 이용시간은 한 시간이고, 1인 1주문인데 쿠키같은 것 제외하면 와플 같은것도 1주문에 속한다고해서 음료 좋아하지 않은 첫 째는 와플로 대신해서 주문해서 맛있게 즐기고 구경하고 사진도 많이 찍었어요. 이 공간 자체에 있는 것만으로도 너무 행복해하고 설레하는 얼굴을 보니 저도 함께 행복했습니다.', 86, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '시나모롤카페 가봤는데, 1시간제한인게 아쉽긴한데 그래도 갈만했어요 한번쯤??? 우리애기는 시나모롤을 그다지안좋아했는데 좋아하는아기들은 엄청좋아할거같네용', 63, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '예약하고 아이와 함께 방문했어요,,, ㅎㅎ 지난번에 우연히 스위트카페가 있는걸 알아서,,, 아이데리고 서프라이즈로 방문했어요,, 아이가 너무 좋아해요~! 예약제 라서 사람이 많치 않아서 좋구요,, 아이가 좋아하는 캐릭터 카페라,, 좋네요,, ㅎㅎ', 23, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '오랜만에 시나모롤 스위트 카페 방문했는데 무조건 1인1메뉴 주문인데 음료와푸드 이렇게는 안되는게 정말로 짜증났음 친구랑 산리오 러버스 클럽도 가야되서 1개로 나눠 먹고 가려고 했는데 그렇게 안되서 짜증났다 그래도 뱃지는 마음에 드는게 나와서 좋았다. 음료1개 쿠키 한개 이렇게 해도 1인1메뉴인데 안된다는게 이해가 많이 안되었다. 음료든 푸드든 1개로 해주면 좋겠다.', 26, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '평일에 방문하니 별도 예약 없이 바로 입장할 수 있어 좋았습니다. 시나모롤 좋아하시는 분, 귀여운 캐릭터 좋아하시는 분이라면 방문 하면 좋아하실거에요. 옆테이블에 아이와 함께 방문하신 분도 계셨는데 아이가 행복하다고 말하는 걸 듣고 귀여웠네요. 비주얼만 귀여울줄알고 큰 기대 안했는데 생각보다 카페 음료도 와플도 맛있었습니다  :)', 32, 7, 'GOOD', SYSTIMESTAMP);
