INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '시나모롤 스위트카페♡ 미리 예약해야 갈 수 있는 홍대에서 유명한 시나모롤 스위트카페~ 캐치테이블앱에서 빈자리 예약을 선착순으로 빠르게 예약했답니다!! 1인1메뉴이고 한시간동안 머물수 있어요~ 와플이랑 음료 모두 비싸긴 하지만 맛있고 여름 한정메뉴 블루베리 사고펄도 아이가 맛있다며 잘 먹었어요!! 사진 찍을 수 있는 룸이 있는데 아이사진을 백만장 찍은 듯 해요^^ 포토카드를 뽑을 수 있는 기계가 있는데 시나모롤 전용동전을 넣으면 귀여운 시나모롤 포토카드가 나온답니다!! 시나모롤 스위트카페 전용 네임스티커도  뽑아주고 사진을 넣어서 마그네틱 시나모롤 포토카트를 만들 수 있어서 만들어주고 굿즈샵에서 시나모롤 인형도 사줬답니다!! 시간가는 줄 모르게 맛있거도 먹고 아이와 행복한 시간을 보낼 수 있어서 좋았어요^^', 26, 9, 'GOOD', SYSTIMESTAMP);
