INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '홍대 ak몰2층~~시나모롤😍🥰 예약후 입장~ 한시간 이용 가능^^ 어디서도 예쁜 시나모롤 가득😄 음료도 예쁘고 맛남~냠냠^^굿즈샵도 같이 있네용👍', 50, 7, 'GOOD', SYSTIMESTAMP);
