INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '딸래미 데려오신 부모님들이 젤 많았고 혼자 방문하거나 데이트도 생각보다 많았음! 주말인데도 북적거리지않아 좋았고 포토존도 잘되어있어서 시나모롤 팬 어린이 데려오기 아주 좋은 장소. 음료, 디저트가 맛이 참(...) 없..으나 테마카페치곤 저렴하고 입장료도 없어서 감수할만 하다고 생각됨.', 51, 13, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '일요일 오후 예약 없이 갔어요~ 주변 구경하다보면 시간 금방 가요~ 주차는 발렛해주셔서 편한데 주차대기만 한시간이에요. 카페내부는 어디든 사진찍으면 잘나와요 ㅎㅎ 뒤쪽 표지판 있는곳이 시나모롤 룸 이라서 사진 많이 찍고 왔어요~ 생각보단 작고 아담해요 ㅋㅋ', 14, 3, NULL, SYSTIMESTAMP);
