INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '시나모롤 좋아하는 시나덕후 딸램과 처음 방문했어요~ 아이가 너무 너무 좋아했구 와플이 좀 비싸긴했지만 귀엽고 맛도 괜찮았어요^^', 75, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '시나모롤 좋아하는 울 아이를 위해 갔어요... 1인 1메뉴인데...1시간안에 다 먹으려니 너무..촉박하고ㅜ가격대비 좀 아쉽네요', 44, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '홍대 ak플라자 2층에 있어요 음료는 가격대비 보통맛이이요 쿠키가 맛이 평범합니다 사진찍으로 가는거죠 아이는 매우 좋아해요 음료랑 음식의 맛을 끌어올리면 어른들도 아주 기쁘게 돈을 쓸 것 같아요 까페 주변에 굳즈 매장이 많아서 순식간에 쇼핑하게 되어요', 125, 24, NULL, SYSTIMESTAMP);
