INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '그린애플티 제 입맛엔 안맞았지만 4월의 메뉴라서 엽서 받았어요 혼자 갔지만 한정 코스터 받으려고 메뉴 2개 시켰습니다,, 이벤트 있을 때만 가고있어요', 54, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '홍대 시나모롤 스위트카페 금요일 예약 후 방문 후기입니다. 서울여행을 준비하며 매일 1곳 여긴 꼭 가야지 정했었는데요. 롯데월드 다음으로 정한곳이 바로 시나모롤 스위트카페였읍니다. (저희 딸이 아~~~주 좋아하거든요) 여행갔다와서 어디가 제일 좋았냐 물었을때 정말 한치의 고민도 없이 요길 말하더라구요 ㅎㅎㅎ 캐치테이블에서 예약하실수 있구요 주말에는 예약이 다소 힘들다 들었읍니다. (예약 오픈시 마감?) 전 방문 일주일 전쯤 예약했는데 금요일이라 그런진 모르겠지만 막 서버 과부하 걸리고 그렇진 않았어요. 유치원, 초등학생 자녀를 두신분들은 사진찍기도 좋고 MD샵에 살것도 많으니 서울 놀러가신다면 필히 방문해보시면 후회 없으실겁니다 ㅎㅎㅎㅎㅎㅎㅎㅎㅎ', 10, 10, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '아이가 시나모늘 좋아해서 예약해서 다녀왔어요. 시간 맞춰가니, 대기없이 입장 가능했고, 주문한 음식도 빠르게 나왔어요. 작은 공간을 엄청 아기자기하게 꾸몄네요.. 좋았는지, 아이는 다음에도 오고싶다고 했어요^^', 89, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '아이와 갔어요 미리 예약했는데, 예약시간 못맞춰가서 취소하고 현장대기 할 생각으로 갔어요. 그런데 바로 입장했네요 ㅎ 허무하게 ! 아이는 정말 좋아했구요! 아이가 좋아하니 가볼만 하지만 이 가격에.. 이 맛이면..^^ 두번은 안가요..ㅎ 한번이면 충분하네요.', 49, 10, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '생각보다 규모는 작지만 7세 여아 환장하네요 ㅋㅋㅋㅋ계속 사진찍고 이쁘다며 감탄연발😆😆 메뉴가 전체적으로 비싼감이 있지만 커피에도, 와플에도 시나모롤 모양이 있으니 한번쯤 먹어볼만해요. 카페이용시간이 1시간밖에 안되서 기프트샵..옆에 소품샵들… 못된고양이.. 1층엔 아트박스까지 ㅜㅜㅜㅜ 탈탈털려서 두번은 안가요 😂😂😂😂', 15, 9, NULL, SYSTIMESTAMP);
