INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '주말에 아이가 너무 좋아하는 시나모롤 까페에 갔습니다~ 캐릭터 디저트라 너무 비싼게 흠이지만 아이는 정말 좋아하내요~~ 단것만 먹으니까 좀 느끼했지만 ㅋㅋ 아무튼 귀엽고 아기자기하고 좋았어요~!!', 9, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '요즘 핫한 시나모롤카페를 방문해 보았습니다. 2주전 예약 어플을 통해 예약 후 이용하였으며, 쉽지 않은 예약이었습니다^^ 아침 첫타임 예약이라, 이른시간 아이와 함께 방문 하였으며, 예약자 확인 후에 방문할 수 있었습니다. 들어가서 메인 메뉴인 와플과, 잔이 이쁜 마시멜로 핫초코를 주문하였습니다. 메뉴가 나오는 동안 카페 여기저기를 돌며, 아이와 함꼐 구경/사진활영을 하였습니다. 카페 규모가 생각했던것보다는 작아서 놀랬지만, 좋아하는 아이를 보니 같이 기분이 좋았습니다. 주문한 와플은 다른 카페와는 달리 쫀득쫀득한 식감이 좋았으며, 사이드로 나온 과일도 맛있었습니다. 힘들게 예약한 만큼 보람 있었고 즐거운 시간 보냈습니다.', 49, 3, 'GOOD', SYSTIMESTAMP);
