INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '7시니까 예약 안하고 들어감 솔티드카라멜라떼맛있어요!! 기대안했는데 카페 음료들 다 기대이상에 값 합니다. 아기자기 귀여워서 구경하는 맛 있을 듯 요.', 7, 1, NULL, SYSTIMESTAMP);
