INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '예약자리난걸 기다렸는데  없어서 웨이팅으로 예약하고 기다렸는데 생각보다 바로됨~ 자리도 널널했음.초코 케익은 너무 달아서 .ㅠ 사진찍는곳은 공간이 좁아서  크게  뭐는 없음^^;;인스타옹정도~~아이는좋아했어요~', 11, 0, NULL, SYSTIMESTAMP);
