INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '사진찍기도 좋고 아이와 함께 가기 좋아요 음료의 맛은 그닥이네요 ㅜㅜ 가격도 싸지 않는데 뭔가 아쉽네요 좀더 개선되면 좋겠어요 특히 음료부분이요 네임스티커하려고 했는데 고장나서 아쉬웠어요', 57, 17, NULL, SYSTIMESTAMP);
