INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '일요일 주말 예약을 못해서 현장예약을 노리고왔는데 오픈런하자마자 매장에 왔는데 현장대기 없이 바로 들어왓어요 럭키!! 아이들이 너무 좋아해요 음료,디저트 가격이 사악하긴 햇지만 맛은 나쁘지 않아요', 98, 20, 'GOOD', SYSTIMESTAMP);
