INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '카페모카 마셨었는데 엄청 맛있었어요~ 그림도 귀엽구요ㅎㅎ 빨대 꽂아먹어서 저 그림 망가졌긴했었는데 매장 인테리어도 완전 맘에들었고 어린이들이 많아서 시끌벅적 했답니다~~ 지갑을 잃어버렸었는데 매장직원분께서 찾으러오라고 연락까지 해주시고 사진도 찍기 좋았어요♡', 45, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '아이가 너무 좋아해요~! 오픈시간 맞춰가서 기다림 별로없이 들어갔네요~음료랑 와플 가격이 조금사악해서 그렇지 ㅎ아이가 여기저기 사진 찍고 너무 좋아했어요~!딸이랑 데이트하기 좋은곳이네요~!', 47, 1, 'GOOD', SYSTIMESTAMP);
