INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '오늘 헬로키티 생일이라구 시나모롤카페도 키티생일 기념으로 바꼈는데 넘귀여워요ㅠㅠㅠㅠㅠ 글구 시나모롤 특전 매트 갖구팠는데 받아서 기쁘네요><', 65, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '조카들이 캐나다에서 와서 시나모롤 캐릭터를 좋아해서 방문했는데 직원들 완전 불친절 미리 예약했지만 테이블도 붙이지 못하고 앞접시도 안주는 이런 카페 첨 봐네요~ㅠㅠ (가족이 두테이블로 나눠있어서 붙였다가 원상복구하겠다고 했지만 안된다고) 가격 비싼거야 어쩔 수없지만 그만큼에 서비스는 꽝 다시는 안올듯 와플은 시키지마세요. 딱딱하고 차가운 벽돌입니다', 19, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '정말 마음에 들었어요!! 시나모롤팬은 아닌데도 귀여워서 사진만 몇십장 찍은거 같네요! 예약하고 간건데 카페에 파는것들 너무 맛있었네요 와플도 맛있고^^', 1, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '아이가 시나모롤 너무 좋아해서 예약후 방문했어요. 주말엔 주차가 무지 힘들고 . 막상 카페는 그닥 ..볼건없고 . 와플은 핫케잌과 와플의 중간인 저려미맛. 인테리어는 안쪽에 시나모롤 방하나 볼만해요. 예약하고 갈거면... 홍대앞에. 산리오카페가 훨 볼것이 많네요 . 역시 샵에서 탈탈털리고 갑니다.', 7, 10, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PARKING');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '아이들이 너무 좋아했어요~ 사진찍을수 있는 곳이 크거나 엄청 다양한건 아니었지만 찍으면 예쁘게 잘나오고 아이들은 너무 좋다고 다음에 또 가자 하네요', 2, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '아주 어렵게 예약 성공 🩵🫶🏻 음료 귀엽긴 한데 ㅜㅜ 맛은 ...... ㅜㅁㅜ 생과일 와플도 ..가격대비 ..흠 ... 애기가 너무 좋아해서 좋은 추억으로 🩵🫶🏻 한정 메뉴들 드셔 보세요 근데 아이스가 올라간 메뉴들은 너무 빨리 녹아 내려서 당황 🫠🫠🫠🫠 나오자 마자 찍은건데 ... 아기가 초콜릿을 다 빼먹고 ㅋㅋㅋㅋㅋㅋㅋㅋㅋ 아스크림은 녹았지만 애기기만 신난 다면 좋아여', 19, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '스윗피치소다 마시구싶었는데 오늘 마셔서 정말 맛있었네요ㅠㅠㅠㅠㅠ 포토존 리뉴얼된 모습도 더 이쁘구 귀여워졌어요>< 시나모롤 방이 된 분위기?ㅎㅎ 담에도 또가구싶네요ㅠㅠㅠㅠ', 52, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '오랜만에 예약해서 방문했는데 샤인머스캣 소다 달콤하고 톡쏘는게 맛있었네요ㅠㅠㅜㅠㅠㅜ특전 코스터 시나모롤 넘귀엽구 아크릴스탠드 사서 받은 특전 부채도 시나모롤이 넘 푹신해보여요ㅠㅠㅠㅠ평소에 시나모롤을 워낙 좋아해서 다음에도 기회되면 또 방문하고싶네요ㅎㅎ', 115, 24, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '사심 가득한 방문 이였는데 주말에 동반으로 가고 싶었으나 평일에 한자리 겨우 구해서 혼자라도 겨우 시간내서 행복하게 즐기고 왔습니다. 혼자 왔지만 친철한 안내 덕분에 안뻘쭘하고 즐길 수 있었어요 감사드립니다!!', 49, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '시나모롤 카페에 오시면 포토존도 있고 숍도 있기도 하지만 시나모롤 덕후인 사람들이 오시면 좋아할 것 같습니다.저도 시나모롤 덕후인데 정말 꿈에 그리던 시나모롤 카페에 와서 일단 너무나 좋았습니다(정말 시나모롤 덕후 추천!!!)', 0, 7, 'GOOD', SYSTIMESTAMP);
