INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '시나모롤은 못참지! 예약하고 갔더니 , 북적이지 않고 괜찮았어요:) 파르페는 별로지만 맛으로 먹는 곳 아니라 멋으로 먹는 곳 잘 놀다 갑니다 ㅋㅋㅋㅋ 친절하세요:)', 77, 12, 'GOOD', SYSTIMESTAMP);
