INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '메뉴가 적고 음료 위에 시나모롤 모양의 아이스크림이 얹어지면 3천원 가량 더 비싼 게 아쉬웠지만 맛도 있고 비주얼이 예뻐서 괜찮았네요~ 이곳은 무조건 예약해야하는 곳인데 성공하면 네임카드, 포토카드 제작과 함께 곳곳의 포토타임에서 사진 찍을 수 있어 아이들, 시나모롤 캐릭터 좋아하시는 분들은 꼭 가보세요!', 32, 10, 'GOOD', SYSTIMESTAMP);
