INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '평일 한시간 기다려서 들어왔어요. 음료들이 너무 달다고 해서 카푸치노 주문했는데 생각보다 맛이 괜찮았어요. 아이가 가고싶어해서 온건데 좋아했어요. 근데 두번은 안 와도 될것같아요. 한번 와본걸로 충분합니다.', 8, 9, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '캐치테이블로 2주전 예약하고, 오늘 드뎌 입장했네요. 주말이라 사람이 꽉찼어요. 솔직히 생각보다 규모가 적어서 좀 실망은 했지만 아이가 너므너므좋아해요. 와플가격은..좀..;;; 재미있게 놀았어요~♡', 2, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '이 캐릭터에 빠진 아이가 있다면 한번쯤 가볼만한 곳이네요^^ 월요일에 예약없이 20분 대기, 옆에 기프트샵에서 구경하다보니 시간 금방 가네요. 아이가 너~~~~~~~무 좋아했어요. 에어컨 빵빵해서 찬음료먹음 너무 추워졍🥲', 26, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '일본 애니메이션을 좋아하는 딸램과 굿즈 & 피규어 투어를 했어요. 시나모롤카페가 있다는 것도 알게 되어 AK플라자 오픈 30분전에 갔는데 정문쪽에 시나모롤 직원분이 계셔서 현장 예약후에 AK플라자 안에 둘러보다가 카톡 받고 방문했는데 딸램이 너무 좋아하네요. 가능하다면 오픈런하세요, 엄빠도 아이도 덜 피곤합니다.', 16, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '어렵게 예약해서 갔는데..매장에 손님이 없네요 텅텅 아이가 좋아해서 저도 좋긴했지만 가성비는...시나모롤 좋아하면 한번쯤은 올만합니다.', 15, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '초4아이와 홍대 데이트로 예약해서 평일에 갔는데 평일은 예약하지 않아도 될거 같아요. 여자아이라면 한번쯤 가서 구경하고 사진찍고 메뉴도 귀엽고 맛있어서 좋았어요~ 쇼핑몰 내에 있어서 한시간 이용 후에도 구경할곳 많아서 좋았어요', 9, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '엄청 기대하고 기다리던 시나모롤 스위트 카페^^ 비가 와서 갈까말까 고민했지만 힘들게 예약한만큼 다녀오길 정말 잘했어요. 예약제여서인지 혼잡하지 않구..  아기자기한 모습이 넘 예뻤어요^^ 음료도 마시고 포토존에서 사진도  많이 찍구^^  생각했던거 보다 규모는 크지않지만 충분히 느끼고 즐길수 있어 좋았어요^^ 시나모롤을 좋아하면 꼭 한번 가보면 좋을듯해요^^', 84, 16, 'GOOD', SYSTIMESTAMP);
