INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '조카들이 시나모롤을 좋아하여 방문하였습니다. 사진 찍을 곳이 생각보다 적더라고요 예약해서 가는 방법도 있지만 현장 웨이팅도 시간대 잘맞추면 안기다리고 들어갈수 있습니다. 음료 맛은 괜찮았습니다. 딸기파르페에 견과류가 들어가 있습니다.', 84, 17, NULL, SYSTIMESTAMP);
