INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '귀엽고 어딜찍어도 사진이 잘 나와요. 주문한 모든 메뉴에 아이스크림이 들어가서 별로였어요. 음료수에 아이스크림은 어울리지않아요.', 13, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '음료 가격은 비싸지만 한번쯤 와볼만해요 ㅎㅎ 너무 귀여워요 딸보다  제가더 신남 현장 대기도 있어서 좀 기다렸어요 자세한 내용은 블로그에 후기 남겨놨습니다^^ ㅎㅎ', 25, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '뽀짝한 디저트도 먹고 포토존에서 사진도 찍고、시나모롤 네임 스티커와 포토카드 및 굿즈들을 구매할 수 있는 이색카페 ෆ̇ 미니 와플: 시원한 아이스크림 말모 ⸝⸝ᵕ ᵕ⸝⸝ 딸기가 없어서 아쉬웠어요。양이 꽤 많지만 가격은 더 비싸요。가장 맛있었어요！ 아이스크림 라떼: 시나모롤 모양 초콜릿이 있는 것 빼고는 평범해요！ 딸기 바나나 파르페: 아이스크림 + 바나나 + 초코 볼 + 냉동딸기 느낌？윗부분이 맛있고 아래는 쉐이크처럼 이것저것 다 섞어 마시는 거예요！마카롱은 눅눅했어요。 예약제로 한정된 인원을 수용하다 보니 포토존에서 사진도 비교적 기다리지 않고 찍을 수 있어요。네 군데 정도 마련되어 있고 시나모롤 천지라 귀여워요🩵 굿즈는 가격이 많이 사악하지만 종류가 다양해서 좋았어요。포토카드는 꼭 만들어보시길ꜝꜝ', 88, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '대기시간 2시간30분.. 현장에서 대기하고 들어갔어요ㅎㅎㅎ인기가 장난이 아니네요! 코스터 4장 받았는데 시나모롤 안나와서 아쉬웠어요🥺인원수대로 음식을 시켜야해서 아이스크림라떼와 자몽에이드 그리고 피치소다랑 와플세트 시켜먹었어요. 소다에 푸른빛이 안나서 아이가 왜 우리 건 푸른빛이 없냐고..ㅎ 와플세트가 생각보다 비쌋지만 맛은 있었습니다~~! 포토존이 마련되어 있어서 아이들이 얼마나 좋아하던지 사진도 많이 찍고 왔어요😊 바로 옆에 소품샵이 붙어있어서 참새가 방앗간을 지나칠 수가 없쥬..ㅎㅎ초딩딸들이 각자 사고싶은거 하나씩 사들고 왔답니다💙 가성비로 따지면 별로지만 딸들이 엄청 좋아해서 그걸로 만족합니다! 가격은솔직히 소품까지 사면 놀이공원 다녀오시는게 훨 나은 것 같기도 해요..😋', 6, 6, 'GOOD', SYSTIMESTAMP);
