INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '예약부터 경쟁이 치열했던 시나모롤 카페. 평일이라 사람이 적어서 이용하기 편했어요. 시나모롤 컨셉의 포토존도 귀엽고. 와플은 생각보다 맛있어서 놀랐습니다~ 음료는 가격이 되지만 생각보다 정말 괜찮아서 좋았네요~ 한 시간 이용이 너무 짧게 느껴져서 아쉬웠다는게 가장 크지만… ㅋㅋ 다음에 또 기회가 되면 오고 싶어지네요~!!', 48, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '한번은 가기 좋은 곳 같네요~ 너무 힘들게 예약 한것 치고 응대부터 디저트 까지 그냥 그랬어요 아이들도 처음에 와~~!!! 하고 몇번 구경 하더니 시큰둥 하네요 ㅠㅠ', 42, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '월요일 오후인데 매장앞에서 웨이팅걸어놓고 total 1시간 20분만에 들어감.앞에서 구경하며 기다릴 수 있을줄 알았는데 아이들과 기다리면 10분이 한시간처럼 지침.3시 30분부터 카페에 사람 없고, 웨이팅1,2번째라 금방 앉을줄 알았는데,인터넷 예약손님이 우선이라.고구마 얹은채 40분 기다림.두번올거 같지 않지만 무조건 인터넷으로 예약해될거 같음. 음료는 예쁜데 와플(18000₩)은 플레이팅이 아쉬움.', 40, 5, 'BAD', SYSTIMESTAMP);
