INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '너무 이쁜까페에요 근데 와플가격 너무 사악하네요 와플 2개에 아이스크림조금 바나나 조금 18000원이라니..음료도 좀..그래도 이뻐서리~~~ ㅎㅎ이쁘게 플레이팅 해주셨지만', 54, 14, 'GOOD', SYSTIMESTAMP);
