INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '저처럼 시나모롤 카페만 오려고 홍대오는거면 실망하실수도 있어요😅 홍대 코스중 산리오캐릭터 좋아해서 1시간 머무를 곳으로는 좋을듯 싶어요~', 16, 9, 'BAD', SYSTIMESTAMP);
