INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '아이들이 너무 좋아해요~ 시간제한있어서 한시간 알차게 실내에서 먹고 마시고 사진찍고 나와서 굿즈샵에서 한참 쇼핑하고 왔어요^^', 4, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '미쿠 시나모롤 머그컵은 품절이에요ㅠㅠ 노트북파우치는 음 고민후 다음에 사기로~ 비싸지만 티셔츠랑 키링 파우치 넘 갖고싶었는데 고민하다가 오늘 샀어요.!!', 50, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '예약이 어려워서 그렇지..다 맛있었어요. 다만..주문한 세개 모두 아이스크림 한덩이씩.. 총 세덩이라 힘들었을뿐..ㅎㅎㅎ또 가고싶은데~~~ 예약이 쉽지않네요ㅎ', 70, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '딸아이가 가고싶어했던 시나모롤 카페.. 비바람을 뚫고 갔네요 진짜 10시반에 오픈하더라구요 1시간이라는 정하진 시간안에 사진찍으랴 와플먹으랴.. 짧았지만 덕분에 아이들에게 기억할만한 어린이날 기념여행이 된 것 같아요', 109, 22, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '네이버 예약 계속 실패해서 그냥 매장 웨이팅 하려고 방문했는데 토요일 점심에 가니 138분 기다리고 들어갔답니다 웨이팅 해놓고 홍대 한바퀴 돌고오니 딱 좋더라고요 시나모롤 좋아하는 자녀가 있다면 방문 추천~! 한번쯤은 좋을거같아요 ㅋㅋㅋ 음료는 맛 없어서 많이 남기고 왔어요~~~*** 꼬맹이가 좋아하니 그걸로 충분.', 32, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '주차는 suv라 주차타워에 못해 옆에 주차장? 같은곳에했구요. 와플은 의외의 맛😆 애들이 좋아하면 된겁니다! 산리오러버스가 더 낫다는점은 꼭 말하고 싶어요!', 10, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PARKING');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '너무 귀엽고 사랑스러워요! 사진 찍으러 다녀가기 좋은 곳. 다만 모든 메뉴 맛이 진짜.. 별로라서 재방문은 없을 것 같아요. 예약제라서 미친듯이 카페 내부도 포토존도 그다지 붐비지도 않고요. 주말임에도 자리가 잘 나는편입니다. 1인 1메뉴인데 36개월 미만은 미포함이라는 이야기를 해주시면 좋겠습니다 주차는 건물 주차장에 대면 할인가능하지만 특정 차량은 건물 주차 불가능이라서 다른 공영주차장에 세웠기때문에 일절 할인 못받았습니다.', 80, 11, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '현장 예약도 있고 또 네이버 예약도 있는데 예약 하면서까지 갈만한곳은 아니고 한번정도는 갈만하다. 오천원이상이면 띠부띠부씰을 주는데 어차피 음료 하나만해도 오천원 넘어서 받을 수있다. 열심히 예약해서 갈정도는 아니고 예약 매진될정까지는 아닌것 같다.', 11, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '아이가 시나모롤을 좋아해 예약 후 방문했어요 예약할 때 이른 시간은 빠르게 매진되서 마지먹 타임으로 예약했더니 사람이 많이 없어 너무 좋더라구요  음료나 와플은 굳이 이 돈주고 먹어야 할 까 싶긴 했는데 아이가 좋아하는 캐릭터 값이다 생각하니 마음이 조금 편하네요', 23, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '5명 합석 안 된다고 하시더니 무거운 음료 5잔 한 트레이에 주시네요. 합석은 안 되는데 트레이는 한 개만 써야 하나봐요 개당 8000원이 넘는 음료에 얼음이 3분의 2네요 빨개가 안 들어가요 ^^ 아이스크림 올라가는 음료는 꼭 얼음 적게 달라고 하세요 안 그러면 저 꼴 납니다. 친절하지도 않고 저렴하지도 않은데 맛도 그닥. 이 돈 내고 절대 안 올 듯 예약 왜 했는 지 시간이 아까움', 2, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '딸아이가 데려가 달라고 해서  갔는데 포토존 작게 되어있어서 사진도 찍고 먹고싶어하던 아기자기한 저 아이들도 먹었어요. 예쁘게 찍은 사진으로 포토카드도 하나 만들어주고 네임스티커도 하나 해서 돌아왔어요', 24, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '아이가 너무 좋아하는 시나모롤이라서 학교 체험학습 쓰고 다녀왔네요ㅎ 예쁘고 귀여운 포토존에서 사진 많이 찍고왔어요~ 와플도 맛있고 음료도 맛있었어요~♡ 띠부실보고 어찌나 좋아하던지 세상을 다 가진 행복한 표정이 절로 나오더라고요~! 카페 테이블매트와 냅킨까지 야무지게 챙겨온 딸이에요💙', 25, 4, 'GOOD', SYSTIMESTAMP);
