INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '생각보다 규모는 작은데 아이는 좋아해요. 카페는 예약제라그런지 주말인데 많이 붐비는 느낌은 아니었어요. 사진찍기 좋아요. 포토카드도 있지만, 3천원이고 아주 고화질은 아니에요. 메뉴들의 가격은 사악하고, 맛집은 아니지만 시나모롤을 좋아하는 아이들이 즐기기에는 너무 좋은 곳이에요.', 30, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '대기 1시간 30분 걸림. 네이버 예약자 위주로 먼저 들어가고 현장 예약자 이후 1시간마다 입장. 30명 대기 기준 2시간 30분만에 금요일 입장함. 입장 10분전 안쪽 자리가 궁금해 들어가자 마음대로 들어오며 안된다고 나가라함. 자리 좋은 곳 찾아야한다는 리뷰보고 돌아보니 그자리가 그자리임. 20평 내외 될 정도 홀로 규모가 생각보다 작고 사진 찍을 장소가 많지도 않음. 캐릭터가 귀엽게 구성되어있으나 시간 기다리며 가진 않게 될 것 같고 대기장소는 좁고 앉을 곳이 없어 건물 한바퀴돌고 와야하는데 돌고 와도 시간남음. 음료는 아이스크림 있으면 8천 이상 아이스크림 없으면 5천원대 가격. 와플도 18천원은 좀 과한듯. 다만 와플 식감은쫀쫀함. 대기하는데 질문에 대한 직원 말투에 까칠함이 있음. 이건 고쳐야 함', 5, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '산리오까페 예약실패하고   여긴  줄서서 갈수있다하여 오픈런했어요  10시도착했는데  건물에11시에 들어갈수있더라구요 대기15번인데 1시간정도 기다렸어요 후문에서 대기하면 바로  올라갈수있어요', 19, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '아이가 너무 좋아하지만 가격이 너무 너무 사악해요 접근성 좋아서 좋고 실내에있어서 좋은건 장점 포토찍는데도 그닥 많지도 않고 그래도 예약제이고 인원을 많이 받지않아서 한적하게 사진찍거나 먹거나 할수잇어서 좋음 재방문은 음 가격이 좀더 내리면 하겠지만 그전엔 안할거같아요 한번쯤은 가볼만한 곳이였음요 기념품샵도 작은데 귀엽... 시나모롤은 귀엽 인정', 21, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '작년에는 웨이팅이 길었던 걸로 기억하는데 평일이라 그런지 거의 대기 없이 들어갈 수 있었습니다. 음료는 평범하지만 비주얼이 좋았고 와플은 나름 맛있었습니다. 시나모롤 팬이시면 한 번쯤은 방문해도 나쁘지 않을 것 같습니다.', 11, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '후기에 비해 와플이 맛있어서 놀랐어요 하지만 역시 가격은 사악합니다 와플에 음료 3개 저게 4만 1천원 ㅎ 음료는 진짜 컵에 얼음만 가득해서 캔 제품 주문해서 얼음컵 요청해서 드시는게 낫네요 조카를 위해 네이버 예약 열정적으로 해서 다녀왔어요 한번 쯤은 갈 만 하네요', 4, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '아이가 너무  가고싶어서 평일로 예약하고 왔는데 사람 많지않고 좋았어요 와플이 너무 달달했는데 아이 입맛엔 딱이에요^^ 커피 한잔하고 신나게 놀다왔어요', 4, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '캐치테이블에서 예약 하고 바로 들어왔어요 캐치테이블 예약이 어려웠지만 예약 후는 바로 들어오네요 생각보다 카페는 soso 볼게 많지는 않아요 그냥 카페 인테리어 음료는 다른 후기들처럼 맛은 없네요 ㅎㅎ', 8, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '초딩 딸래미와 네이버예약 후 방문했습니다~~예약하기가 정말어렵네요~~3번째 성공해서 방문했구요~~곳곳에 귀여운 사진포인트가있어서 포토타임갖기 좋아요~~와플은 넘 더워서 아이스크림이 금방녹아서 아쉬웠습니다~', 19, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '예약하기 진짜 힘드네요 ㅎㅎ 현장대기도 많았어요 지하철2호선 홍대입구 4번 출구 바로 앞 AK플라자 2층 젤 끝쪽에 있어요~ ㅎㅎ 1시간 이용가능한대 포토존이 크지 않다보니 대부분 주문한 음료만 마시고 나가시더라구요 와플은 진짜 맛잇네요 파르페 먹고 싶었는데 애들이 안먹 😭 직원분들 불친절하단 리뷰가 잇던대 전 괜찮았어요~^^ 리버스클럽은 포토존이 잘되있구 시나모롤카페는 음식이 잘되잇네요 ㅎㅎ ✔️카페이용금액 5000원당 띠부씰 1장 랜덤 ✔️시나모롤만 알고 갔는데 다른 친구들도 쉬폰이랑 모카도 알게되서 좋았어요♥', 36, 2, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '아이가 좋아해서 갔어요. 7살아이가 엄마 이게 다야 할정도로 크진않아요 ㅋㅋ 그래도 요즘 마멜이랑 시나모롤 좋아해서 좋아는 했어요. 카페에서 5천원당 띠부실한장 굿즈샵에서는 1만원당 띠부실 한장 주시더라구요. 인형이 4만원대가 있고 1만원대가 있어서 여쭤보니 비싼건 일본에서 온거래요. 비싸도 넘 비싸요 ㅠ.ㅠ', 55, 14, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '딸램생일이라 다녀왔어여. 딸램이 눈돌아갔네요 ㅎㅎㅎㅎㅎㅎ 너무이뿌고 맛도있고 너무좋아요. 카페이용시간이 쪼끔만 더 있었으면 좋겠어요~~ 구경하고 사진찍고나면 먹을시간이 부족하더라구요~~~~', 76, 16, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '메뉴 퀄리티가 사진만큼 너무 좋았어요. 저렴한 가격은 아니지만, 양이랑 이것저것 생각하면 비싼 가격도 아닌 것 같아요. 시나모롤 좋아하는 아이라면 한 번 쯤 가보는 걸 추천해요.  포토존이 크진 않지만, 그래도 알차고 아기자기하게 잘되있더라구요^^', 43, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '방학을 맞아 딸아이와 왔어요^^ 예약이 힘들었지만 좋아하는 딸을 보니 보람이 있네요!! 전반적으로 맛은 맛없지도 맛있지도 않아요 시나모롤 사진찍으러 오는거죠 ㅋㅋㅋ', 36, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '어른인 제 눈에는 아쉬운게 많았는데 시나모롤 좋아하는 조카 말로는 산리오카페보다 훨씬 더 좋다고 합니다. 자녀분의 절대 원픽이 시나모롤 이라면 한번쯤 가보시길 추천드려요 공간이나 굿즈의 아쉬움과는 별개로 음료는 생각보단 나쁘진 않았구요 직원분들은 정말 친절하셨습니다. 아이가 시나모롤 카페와서 행복했다 하니 그걸로 만족합니다.', 22, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '웨이팅은 힘들지만 아이들 데리고 오기 좋네요 주차는 오래걸리지만 웨이팅시간 겸사겸사 기다리면 될거같아요 1시간밖에 있을수없지만 아이들의 만족도 생각하면 괜찮아요', 35, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '와플 딱딱하다는 리뷰 있어서 조금 걱정했지만 부드러웠구요, 아이가 너무 좋아해서 만족만족합니다. 예약만 쉬우면 재방문하고 싶네요^^', 30, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '딸이  시나모롤  엄청 좋아해서 예약 몇번 시도끝에 성공해서 다녀왔어요~ 기대가 컸었는데..아이가 좋아하니  뭐..만족해요. .그런데 음료랑  와플 값은 너무비싸요..ㅠ..', 39, 10, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '사진찍는테마도 달랑2개  테이블도 비어있는데도 예약해야된다하고  음료는그냥탄산수맛 아이스크림때매 넘치고 먹기 불편 빵은 눅눅하고 시럽때매 그냥 단맛만남아요 비싸기도하고 아이들이 볼껄이가없네요', 26, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '초등 아이들의 핫플이라 방문했어요. 시나모롤 좋아하는 아이라면 한번쯤 방문해보면 좋을 곳! 시간제한 1시간인데 포토존에서 사진찍고 음료마시기에는 적절한 것 같아요. 메뉴는 비싸고 맛은.. 여긴 눈으로 먹는데니까 어쩔수 없겠죠. 그나마 금액 5천원당 랜덤띠부씰 1장씩 증정해주니 아이들이 좋아해요. (옆 기프트샵은 1만원당 1장 증정) 띠부씰 퀄은 포*몬 띠부씰보단 허접해요. 인스에서 올려진 코스터 증정행사는 조기마감됐다해서 아쉬웠어요.', 32, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '7살 아이가 너무 가고싶었는데 다행이 예약되서 오늘 방문했습니다 딸아이는 대만족 ㅎ 저희부부도 기대했던것보다 와플도 맛있고 과일도 싱싱했고 모든음료도 맛있었습니다', 43, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
