INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '평일에 가서 그런지 사람 많지않고 조용하니 좋았어요 ak프라자 2층이라 주차하기 편했구요 음료두개랑 와플해서 3만원 정도 나왔는데 스티커 6개 주셨어요 ㅎㅎ', 8, 9, 'GOOD', SYSTIMESTAMP);
