INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '어렵게 예약해서 갔는데. 안내와는 다르게 1시간 이용 제한이 있네요. 분명 아직까지 1시간 30분으로 기재 되어 있으면서요. 사기 당한 기분 ㅠㅠ 음료 가격은 사악 합니다. 사진 찍고, 음료 먹는데 코로 먹는줄 알았네요. 여유를 즐기실 분은 오지 마시길. 애들이랑 잠깐 사진 찍으러 오실분만 오세요. 음료는 달기만 하고 맛은 참 없네요.', 6, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '테이블간 간격이 넓고 매장이 생각보다 한산해서 좋았어요 아이와 사진찍기도 좋았구요. 단점은 긋즈샵 물품들이 터무니 없이 굉장히 비쌌어요 특히 소형인형이요 36000원이 넘더라구요 그래서 안 샀는데 인터넷 검색하니 10000원도 채 안되는 가격에 판매하더라구요 맘에 드는 인형은 차라리 인터넷 구매를 하시는게 현명한 소비라고 생각합니다.', 37, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '평일에 예약없이 갔는데, 대기 많이 안하고 들어갔어요 아이가 너무 좋아해서.. 아이가 원하는거 다 주문했는데.. 와플은 영..별로네요.. 음료도 파르페말고 커피시킬껄 그랬나봐요ㅜㅜ 4만원에 띠부실 8개받아왔네요 ^^;;', 14, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '너~~~무 비쌈... 그래도 아이들이 좋아해서 다행 😌 예약제라 그런지 좌석 엄청 넓고 사람도 없고 1시간 즐기다 오기 좋음 AK플라자몰 안이라 구경하며 기다리기 좋음', 34, 0, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '정말정말 운좋게 예약창이 떴을때 예약했어요! 포토존이 정~말 헉 할정도 작았지만 카페 내부 인테리어가 전부 시나모롤이라 아기자기 귀여웠어요ㅎㅎ 1시간 제한이라 뭘먹고 왔는지도 기억이안나요.. 정신없이 사진찍고 포토카드뽑기하고 커피는 원샷하고 나온듯해요~ 한번정도 기분전환할겸 다녀오긴 좋은듯해요!', 16, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '평일에 홍대 간 김에 혹시나 하고 들렀다가 30분 정도 기다려서 들어갔어요~ 음료만 3잔 시켜서 먹었는데.. 레모네이드 초코 좋아하는 아이들인데 남겼어요 시나모롤의 화이트초코?가 별로라네요 레모네이드는.. 음.. 이날만 별로였던건지ㅠㅠ 카페는 정말 예쁘고 직원분들 친절하고 음료도 귀여워서 아이들은 정말 좋아했어요~', 37, 2, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '예약제인데 아이가 가고싶다고해서 급하게 가다보니 웨이팅 했네요. 주말이라 4시간 넘게 기다렸는데 그래도 아이가 행복해해서 뿌듯하고 좋았네요~^^ 기념으로 한번 데려가서 사진도 찍어주고 하면 좋은 경험이 될 것 같아요!! 예약 필수', 32, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '초딩 아이들의 최애캐릭! 드디어 다녀왔네요^^ 직원 응대도 너무 친절했고, 예약제이다보니 붐비지 않아 아이 사진 너무 예쁘게 잘 찍어줄 수 있었어요! 이용시간 한시간이라 적겠다 싶었는데.. 사실 매장도 많이 큰편은 아니고 충분히 사진찍고 음료마시고 즐기기에 딱이었습니다~ 아이와 좋은추억 쌓고 갑니다', 78, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '곳곳에 사진찍을 곳이 있는데 아주넓은 편은 아니예요~ 와플은 기대 안했는데 괜찮네요^^ 음식메뉴가 생각보다 많지 않아 아쉬웠어요~ 시나모롤 케릭터 카페인만큼 시나몬롤 같은 디저트를 팔았으면 어땠을까 하는 아쉬움이 있네요^^', 90, 17, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '시나모롤 좋아하는 딸을 위해 평일 1시 예약이 되길래 급 다녀왔어요 아기자기하게 사진 찍을 수 있네요 1인 1주문인데 아이 입이 짧아서 하나는 딸기라떼 했는데 나중에 밖에서 놀다가 주니깐 잘 먹더라구요 테이크아웃 가능하게 나온거라 좋아요', 44, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00075@test.com'), '아이 곧 생일이라 예약하고갔어요 음료가 비싸고 탄산 못먹는 아이들은 먹을게 없긴하네요 그래도 애들은 너무 좋아해요 사진도 많이찍고  즐거운시간이었어요', 3, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '힘들게 예약했는데 평일이라 그런지 1/3정도만 테이블이 채워졌어요.여유롭게 사찍찍고 음식도 먹을수있었어요. 처음해보는 네임스티커, 포토카드도 새로운 경험이었고 와플은 맛있었어요.음료도 평균적이였는데 애는 맛없다 하더라구요^^; 굿즈샵은 생각보단 작았고 봉제인형,가방,키링등이 비싸고 다른건 가격 괜찮았던것 같아요~~^^', 54, 17, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '개인적으로 아이들이나 산리오 좋아하세는분이라면 좋아할곳입니다 다만 커피 기대하지마세여 음료 기대하지마세여 그냥 시나모롤 귀여운거 하나만 보고 가실분들은 추천이여 커피,음료는 아닙니다', 46, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '깔끔하고 귀여운 곳이었어요. 주차도 직원분이 해주셨구요. 와플도 쫀득하고 맛있었고, 커피도 나름 맛있었어요. 시나모롤 벚꽃에디션도 구입하고 돈을 팡팡 쓰고 왔지만 요새 유행인 시나모롤 보고왔으니 만족입니다. 이건뭐.. 연예인 보고온 느낌입니다. 아. 산리오카페도 가봤는데, 산리오카페보다 깔끔했어요. 거긴 낡은주택같은곳이었고 여긴 ak몰이라 더 깔끔~~', 8, 4, 'GOOD', SYSTIMESTAMP);
