INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '커피 초코라떼 와플세트까지 ㅋ 다 맛나게 잘 먹었어요 ㅋ 우리 애가 너무 좋아했어요.. 주차가 살짝 아쉬웠지만 그래도 공영주차장이 멀지않아 다행이다 했어요', 24, 10, 'GOOD', SYSTIMESTAMP);
