INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '생각보다 작아서^^; 실망 제공된 음료 품질에 만족도 업~ 간신히 예약성공해서 간것에 비해 슬프지만 그래도 사진은 이쁘게 나오네요~', 33, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '산리오한국유행전부터 좋아하던아이. 시나모롤만 유독좋아했는데 카페생기고 너무너무너무 좋아해서 아빠사무실근처라 방앗간처럼갑니당 가격이좀 사악하지만 아이가좋다면야 가야지욤🥲', 52, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '좌석 간격은 여유롭고 포토존도 사람 몰리지 않아 사진 찍기 좋아요. 음료나 굿즈가 다양하지 않고 가격 대비 별로에요. 시나모롤을 좋아한다면 한번쯤 와볼만 해요.', 115, 19, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
