INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '조카가 시나모롤 왕팬이랑 언니랑 남친이랑 다녀왔어요! 네이버예약하고 가야되는데 쫌 늦어서 전화로 양해구햇더니 해주셧어요ㅜㅠㅠ 테이크아웃ㅇ 안되는게 흠이긴하지만 조카는 만족했답니다', 15, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '너무나 만족스럽습니다^^ 시나모롤 좋아하는 딸 덕분에 온가족이 예쁜곳에서 맛있는 음료마시며 즐거운 시간 보냈네요~ 몰 자체에서 볼거리가 많아 미리 도착해서 층별로 구경하고 예약시간 맞춰서 들어가서 편했구요~ 붐비지 않아서 더 좋았습니다. : 음료의 데코와 퀄리티도 휼륭하구요 테이블마다 다~ 있던 와플은 왜 다~ 주문하는지 먹어보니 알겠더라구요 쫀득하니 어른들 입맛에 더 찰떡✔️ 2주전에 다른 캐릭터 카페 갔을땐 북새통이였는데 시나모롤을 좋아하는 아이가 있다면 여기는 꼭 와야할 곳이에요! 최근 일본에있는 산리오몰 다녀온 친구가 제 사진 보더니 인테리어, 음료의 퀄이 우리나라가 훨씬 좋다고 하던데요???🫰🏻만족스런 방문이였습니다. 예약이 치열했지만 전 안전빵이 좋아요', 16, 7, 'GOOD', SYSTIMESTAMP);
