INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '아이가 가고싶어해서 치열한 주말 예약에 성공하여 다녀왔어요! 현장대기는 힘들어 보였어요  ㅠㅠ 아이가 좋아하니 한번쯤 가볼만하네요^^', 14, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '딸이 시나모롤을 좋아해서 꼭 한번 가봐야지 한 곳이에요. 이번에 어렵게 예약해서 방문했는데 12시타임이라 그런지 그리 복작복작하지 않고 나름 여유 있었어요. 포토존도 귀엽고 와플이나 음료도 괜찮았어요. 아이가 잘먹고 넘 좋아해서 뿌듯했어요.', 44, 3, 'GOOD', SYSTIMESTAMP);
