INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '한번은 가볼만한 곳₍₍ ( ๑॔˃̶◡ ˂̶๑॓)◞♡ 아이가 좋아하는 캐릭터라 사진 많⍤⃝𓂭 남기고 왔습니다ෆ╹ .̮ ╹ෆ 아이가 초코라떼 맛있다고 좋아했습니다👍🏻', 70, 17, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '아이와 예약하고 어제 방문했어요. 그렇게 붐비거나 포토존으로 인한 불편함 없이 여유있고 한산하게 즐거운 시간을 보냈어요. 음료도 쿠키도 다 괜찮았어요. 소소하고 사랑스러운 소품들과 벽화, 거울, 산리오들과 함께한 기분 좋은 추억이네요. 주변에 벚꽃이 가득한 연남동 밤거리를 걸으며 집으로 돌아오니, 행복한 봄밤이구나 싶었습니다.', 26, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'REST');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '정말 예약 열리는시간에 딱 들어가서 예약해서 간곳.. 애들이 좋아해서 갔지만ㅋㅋㅋ굳이 두번 갈 곳은 아님ㅋㅋㅋ갔다왔다는 점에 의미를…^^', 68, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '일단 아이들이 너무 좋아합니다 다만 30분 입장은 테이블 선택 폭이 좁아서 불편해요 이용 시간이 한시간인데 테이블 두개가 붙어진 네모 테이블은 정각 입장하신 분들이 다 앉으셔서 어쩔수 없이 동그란 테이블밖에 남아있지 않아 그 자리밖에 선택할수 없었습니다 그런데 자리이동이 안되고 와플과 음료 네잔을 시켰는데 작은 동그란 테이블에 모두 놓아야 해서 너무 좁았습니다 그러다가 정시 입장하신 분들은 또 넓은 테이블로 가서 앉으셨어요 4인 입장이면 30분 입장은 비추 정시입장하세요 넓은 테이블이 없습니다 ㅜㅜ 동그란 테이블에 앉는다면 와플과 음료를 시키지 말고 음료만 마신다면 괜찮을거 같아요', 22, 0, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '아이가 좋아해서 예약 후 방문하였습니다 역시나 아이가 좋아했습니다 1시간 즐길 정도의 크기입니다 조금더 밝았으면 사진이 더 잘 나올 것 같습니다', 9, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '포토존이 넓진 않아요 까페는 자리 넉넉해요~ 푸드평이 별로라 걱정했는데, 생각보단 먹을만해요 ㅎㅎ 직원들이 다 친절해서 좋았어요!! 주차 진짜 너무 편해요 발렛!! 볼거리가 많지는 않아서 1시간도 안되서 후딱 놀다 나왔어요!', 64, 18, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PARKING');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '산리오카페보다 작고 서비스도 실망스럽네요. 가격대비 서비스를 비롯 와플 가격이 비싼편인데 너무 딱딱해서 먹을게 거의 없더라구요. 다신 안갈듯요~', 20, 5, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '블로그들 보고 속는셈치고 시켰는데 생각보다 너무 맛있었어오 와플 쫄깃쫄깃하고 생크림 추가했는데 그 위에 뿌려진 시럽도 맛있고 울애기도 잘 먹었어영 금요일 10시 전에 도착했는데 10시 40분쯤 직원분이 예약하는 패드 가지고 오셔서 우린세번째였는데 대기시간 20분 떴구요 AK플라자 자체가 11시 오픈이다 보니 패드로 예약한 사람들은 카톡알림오면 가면 되니까 좋았어요 포토카드도 제작해서 좋은추억 많이 만들었어요~~', 37, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '드디어 예약성공해서 왔어요~~~ 평일 이른시간에 예약해서 그런지 좌석 널널하고 원하는 자리에 앉았어요 ㅎㅎ 포토존 많고 조명이 좋아서 그런지 셀카 엄청 잘나와요! 맛은 무난했지만 디저트 비주얼만큼은 환상적이였네요~ 크리스마스 이벤트 기간이라 한정판 코스터도 받았네요 히히 ㅎㅎ 산리오 너무 귀여워요 시나모롤 사랑해!!!', 45, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '딸기라떼가 맛있었고 초코라떼는 제가 생각하는것보다 덜 달아서 아쉬웠어요. 하지만 어린이층 타켓 위주라고 본다면 적절한 맛인 것 같아요~ 아래에 깔린 종이도 굿즈처럼 챙겨가시면 좋아요. 음료하나에 랜덤 씰 스티커 하나를 줘서 좋았어요', 80, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '공간이 작아서 1시간안에 먹고 사진찍고 다합니다. 와플은 생각보다 맛있지만 넘 비싸고 음료는 귀엽지만 비싼데 맛도 그냥 그래요. 보이는 모든 것이 다 비쌉니다. 가성비는 정말 별로고 엄마 입장에선 넘 돈 아깝지만 시나모롤 좋아하는 아이가 있다면 한번 가볼만합니다.', 5, 9, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '사진 찍기는 좋아요. 메뉴에도 시나모롤이 있어 귀엽지만 가격대비 맛은 아쉽네요. 파르페에 얼음이 들어있어 먹다보니 물맛나고, 와플은 너무 바삭해요. 1시간 이용이라 여유있게 먹을 수 있는 카페는 아닙니다. 랜덤 띠부실도 아쉽고, 힘들게 예약해서 와서인지 다소 실망스럽네요. 한 번 경험으로 충분한 것 같습니다.^^', 14, 8, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '딸아이가 계속 보챘던 시나모롤카페..  친구들과 같이다녀왔네요. 인테리어가 아이들이 좋아할만합니다. 음료도 와플도 휴지한장까지도 아이들취향저격이었어요ㅎ 전 덕분에 아이들이 포토존돌아다니는동안 그림그리며 힐링의시간 가졌네요ㅎㅎ', 31, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '지루한 방학기간에 간만에 아이도 기분 전환하고 즐겁게 쇼핑도했어요^^ 각오하고 왔지만? 눈돌아가는 소품샵덕분에 받은 세뱃돈 꽤 썼네요 ㅋㅋ주차도 발렛이라 쉽다고하고 식사는 5층가시면 놀이방있는 식당있으니 망설이지말고 다녀오세요^^', 11, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PARKING');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '카페는 널찍 하고 사진도 이쁘게 나오고 좋습니다. 와플은 괜찮은데 커피는 조금 그렇네요. 벽쪽 좌석은 천장에서 나오는 에어컨이 바로 떨어져서 냅킨이나 빨대가 날려서 그냥 둘 수 없을 정도이니 참고하시기 바랍니다. 애기가 좋아한다는 거 외에는 기대했던 것 보다는 실망스러웠습니다.', 41, 0, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '아이가 너무 가고싶어했는데 운좋게 예약을 하고 방문했어요.^^ 너무 아기자기하고 예뻐서 인기가 많은 이유를 알겠더라구요. 근데 생각보다 공간이 너무 작아서 살짝 아쉬웠어요.사진찍을 공간이 조금만 더 넓고 다양했으면 더 좋았겠다 싶더라구요~ 그래도 덕분에  "엄마최고!" 소리 들었습니다~^^', 79, 18, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '시나모롤 덕후 필수 방문지..! 생각보다 아이들이 많았고 꽤 쾌적했습니다 제한시간 2시간인가 있고 와플은 찰와플이라 쫀득합니당 금액에따라 코스터랑 띠부씰 랜덤증정 해줍니다!!', 47, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '1. 산리오 덕후 아이들이 좋아한다. 포토존은 적어도 귀엽다. 2. 음료값 와플값이 너어무 비싸다. 아무리 캐릭터 값이라지만 내용물도 부실;; 3. 36개월이상 1인 1메뉴 필수다. 하지만 18000원짜리 와플도 1메뉴… 3500원짜리 쿠키는 1메뉴로 취급도 안해줌… 4. 친절하지 않다. 1시간 시간 제한으로 사진찍느라 고대로 남은 음료 테이크아웃 가능하냐고 했더니 포장 매장이 아니라서 불가하다. 파르페 긴 수저 하나 더달라고 했더니 파르페 수저는 1잔당 1개다.주장하셨어요. 결론=캐릭터에 환장하는 아이들을 볼모로 부모들 돈쓰는 호구로 만드는 카페입니다. 알고 예상하고 제 손으로 힘들게 예약해서 왔지만 오는 길이 참 씁쓸하네요. 이 리뷰 꼭 사장님과 직원분들 보셨으면 좋겠습니다.', 39, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '별로예요.. 7시예약이라 사람이 없는데도 벽쪽에 앉으려니 4인은 가운데 앉아야된다며 못앉게 하네요. 와플.초코라떼는 품절이고 1인1메뉴 시키라는데 애기들먹을것도 없어서 그냥 나왔어요. 사진찍는곳도 별거 없어요', 18, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '시나모롤 생일 다가오길래 미리 예약해서 갔다왔구 와플 첨먹어봤는데 정말 맛있었어요ㅠㅠㅠ아이스크림이랑 생크림까지 꿀조합이었음(*´∀｀)ノ 담에 또가구싶네요ㅠㅠㅠㅠㅠ', 47, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '평일 방문이었구요. 1시간 이용제한 있는데 시간이 너무 짧은 거 같아요. 음료 맛은 기대 마세요. 모카나 라떼가 이렇게 맛없기도 쉽지 않은데... 와플도 너무 딱딱해서 먹는데 잇몸을 계속 긁더라구요. 성인들도 많지만 카페 특성상 아이들도 많았는데 엄마 아빠들 애들 따라 다니랴 커피 마시랴 정신 하나도 없어 보입니다. 아이가 있음 한시간 반으로 시간을 늘려주던지 보는 사람이 다 안타까움. 음료는 인당 시켜야 하는데 보면 애들은 음료 다 버리거나 나기기 전에 호다닥 마심.', 90, 15, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '아이들이 가고 싶어해서 갔어요 주말엔 예약도 힘든데 평일 오전에 갔더니 예약없이도 들어갈수 있더라구요 자리도 많이 남았구요 와플에 음료2잔 먹었더니 3만원이 넘었어요 한번은 가볼만 하지만 두번은 안갈듯해요 ㅠㅠ', 13, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '직원들은 리뷰와 다르게 친절하고 메뉴도 비싸다고 느껴지지만 코스터 띠부실 캐릭터값 생각하면 양도 적당하니 괜찮았습니다! 다만 와플은 딱딱해서 보완해야할거 같습니다!', 34, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '치열한 예약 성공해서 다녀왔어요.(현장대기도 가능하지만 주말엔 사람이 정말많더라구요) 정말아이가 좋아했어요. 디저트류가 비싼편이긴하지만 주문하면 주는 띠부실을 아이가 너무좋아했어요. 사진맛집 인정합니다. 초딩들의 최애성지네요.', 40, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '초딩 조카가 시나모롤 노래를해서 다녀왔어요. 지하철역 바로 앞이라 교통은 너무 좋아요~ 매장은 생각보다 작고 테이블도 작아요. 2인테이블에 음료랑 와플트레이 두개 올려놓지 못할정도? 그래도 음료랑 와플은 맛있었어요 조카가 좋아하면 그걸로 된거죠뭐…ㅎㅎㅎ', 122, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '치열한 예약성공해서 아이랑 갔다왔어요 아이가 엄청 좋아했습니다^^ 초저학년 아이까지는 한번쯤 꼭 갔다올만한거 같네요 디저트도 잘 먹고 왔습니다', 32, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '어렵게 예약해서 다녀왔어요! 평일 첫타임으로 가니 사람도 별로 없고, 좋았어요~ 포토존도 잘 되어있고 굿즈샵도 작지만 알차게 구성되어 있어요:) 디저트,음료는 생각보다 비싸지만 사진찍고 하기엔 한번쯤은 드셔볼만 해요~ 카페도 생각보다 넓고 괜찮아요~! 한번쯤 예약하고 다녀오세요~ 추천해요👍', 36, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
