INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '리뷰와같이 조명이 바닥을 향해 사진이이쁘게 나오진않아요ㅠㅡㅠ 전 예약하고갔지만 오늘 12시이후까지 현장대기 별로 없었어요. 네임스티커 이쁜사진인화등이 시나모롤로 나와좋았어요.쇼핑하기좋은곳이라서 띠부씰이아니면 꼭 시나모롤 카페옆상점에서 살필요는 없는것같아요^^ 아이랑가면 두개가 필요할때가있는데 그런요구사항은 모두 안되는 곳이예요ㅜ 구매후지급되는것들을 똑같은걸로 변경등을 부탁해도 안되더라구요. 이해도하고서운하기도한 그런 애매모호한 마음이생기네요. ㅣ사진이 좀 잘나오게 조명위치를 바꿔주면 좋겠어요ㅜㅡㅜ 너무 어둡어둡;;; 음료가 예쁘고 먹을만해요.와플은 괜찮았어요^^ 소비하러간공간이니까 아끼지않고 썻는데 쓴만큼의 만족감은 떨어지는 곳이라고말하고싶네요 주차는 기계식주차 발렛이라 좋아요. 5만에3시간 5만원은순삭가능', 98, 23, NULL, SYSTIMESTAMP);
