INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '아이가 너무 원해서 가본 곳입니다. 굿즈와 포토존 땜에 가는 곳인걸 알긴했지만.... 음료가 너~~~무 맛이 없어요. 레모네이드는 정말 심각할 정도라 깜짝 놀랐고 다 남겼어요. 편의점에서 파는 음료수가 더 맛있어요.... 커피도 그닥....ㅜㅡ 입장권 대신이라지만 비싸고 맛도 없으니 기분이 안 좋더라구요.. 맛있게 만들면 아이도 엄마도 기분이 좋을꺼 같은데 신경을 더 써주셨으면.... 그리고 와플은 가격이 2배인데 아이들 2명이 와플하나 시킬수 있음 좋겠네요.. 와플도 1인1개라니... 가서 기분이 이렇게 안 좋은 곳도 없었던 듯해요..별로 추천하고 싶지 않습니다.', 1, 5, 'BAD', SYSTIMESTAMP);
