INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '시나모롤을 좋아해서 간 카페였고 인테리어는 너무나 귀엽고 곳곳에 포토존이 많아서 좋았습니다...메뉴는 와플 1개라서 아쉬웠지만 맛있어서 다행이였고 거울을 깨끗이 닦아주신다면 참 좋을것같습니다', 4, 2, 'GOOD', SYSTIMESTAMP);
