INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '7세 여자아이가 좋아했어요! 평일이라 예약도 수월하고 오픈시간에 와서 붐비지 않아서 사진도 많이 찍고 잘 즐겼어요~ 와플이 맛있었네요!', 95, 23, 'GOOD', SYSTIMESTAMP);
