INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '1.입소문에 비해 구경거리가없고 실망스러움 2.어린아이들까지 1인1메뉴 시켜야하는 방식이 이해불가 그렇다고 아이들이 마실수있는 음료가 많지않음 3.직원의 불친절함', 35, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '시나모롤 좋아하는 딸아이와 데이트 다녀왔어요~ 사진도 이쁘게나오고 힘들게 예약하고 간곳이라 더 특별했어요~ 디저트도 아이들이 좋아할맛과 모양으로 아이가 좋아하니 엄마도 같이 힐링 할수있어 더 좋아요~', 48, 4, 'GOOD', SYSTIMESTAMP);
