INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '30초컷 예약성공으로 다녀왔어요. 블로그서 본건 1시간30분 이용이였던것 같은데 잘못봤나? 1시간 이용이고 그뒤로 줄이 쭉 서있어서 먹는데 다급해지더라고요.와플이15분 걸린다고; 기다리는동안 사진찍었는데 올린사진이 전부입니다. 와플은 식빵만하게 크지만 크로플처럼 바삭보단 떡식감 이에요. 몇입 먹었던니 배가 확부름. 커피는 그냥저냥. 라떼가 엄청 맛있거나 하진 않아요.크림라떼는 안달고 아이스크림은 투게더맛. 데코는.이쁜데 맛은 상상되는 맛 그이상은 아닙니다. 참고로 2층 화장실 사람 많아서 화장실이라도 중간에 다녀오면 나가야할시간. 1테이블서 6만원 매상 올려줬는데 1시간 이용시간 제한은 좀 야박하네요. 재방문의사는 없어요.한번이면됐다.남편분들은 떼놓고가세요ㅎㅎ', 14, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '매장 내 인테리어도 예쁘고 디저트 와플과 음료 맛과 퀄리티도 좋았습니다. 직원들이 다 친절하셔서 편안하게 잘 즐기다 왔습니다. 포토카드 처음 만들어봤는데 랜덤 카드그림 예뻐서 만족스럽습니다. 캐릭터 숍에 상품이 많진 않았지만 시나모롤과 친구들 캐릭터제품만으로 되어있어 기념될만한 선물 골라왔네요~아이들에겐 더 없는 선물같은 하루였습니다.^^', 84, 12, 'GOOD', SYSTIMESTAMP);
