INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00084@test.com'), '예약하기 하늘의 별따기였는데 평일 자리예약이 갑자기떠서 하루땡땡이치고 딸이랑 데이트했어용 한번쯤올만해요 ㅎㅎ 일단 애들이 좋아해서 저도 좋네요 ^^ 팬케이크는 가격대가 높지만 맛있었어요 굿즈 가격은 말도안되게 사악해요..ㅎ', 41, 7, NULL, SYSTIMESTAMP);
