INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '워낙 인기가 좋은 곳이라 기대를 마니하고 왔는데 생각보다는 아담하고 별거가 없더라구요..ㅎㅎ 그래도 딸이 엄청 좋아해서 좋았습니다 디저트가 좀 작은 버젼도 하나 있으면 좋을듯합니다', 123, 25, NULL, SYSTIMESTAMP);
