INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '아이가 원해서 샵만 보러갔어요 방학이라 그런지 평일인데도 웨이팅이 180분이더라구요 집에 오니 카톡으로 순번되었다고 연락오네요 아이가 좋아해요 다른곳에서 살수 없는 제품들이 있었네요', 119, 24, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '오픈시간부터 현장대기가 엄청납니다 예약성공해서 어찌나 다행이던지 첫 타임에 가서 사진도 많이 찍고 와플 음료 다 맛보고 즐기다 왔어요 아이에게 좋은 추억이 될 것 같아요', 54, 14, 'GOOD', SYSTIMESTAMP);
