INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '아이가 시나모롤을 좋아해서 왔어요 예약 없이 갔더니 1시간 40분 대기 후 들어갔네요 근처에 구경도 하고 점심도 먹고 하니 기다릴만 했어요 음료랑 와플은 비쌌지만… 맛있었어요', 24, 5, NULL, SYSTIMESTAMP);
