INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '아이가 시나모롤을 너무좋아해서 네이버 예약 오픈 기다렸다가 예약후 방문 했어요 ~ 음료 너무 귀엽고 가격도 비싸지 않아 좋았어요 결제금액별로 띠부씰과 컵홀더를 줘서 아이가 너무좋아했고 주차는 안되지만 주변 주차장 이용하면 별 무리 없어요~~~인테리어는 ㅎㅎㅎ별거 없었지만 아이가 너무좋아해요~~ 가볼만 합니다', 42, 4, 'GOOD', SYSTIMESTAMP);
