INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '너무 좋은 시간이었어요. 좀 비싸다고 생각했었는데 음료랑 디저트 퀄 보고 생각이 사라졌네요ㅎㅎ 연인 간의 데이트 장소로 최고!!!!', 7, 1, 'GOOD', SYSTIMESTAMP);
