INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '아이의 최애캐릭터에 가봤는데...온통 시나모롤로 아기자기해요^^ 예상했던것 보다 공간을 작았지만 맛있는 디저트에 포토존까지 있어 좋았어요^^', 49, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '11시 오픈시간 예약하신 분들은 딱 맞춰서 가셔도 됩니다.  10시반까지 미리 도착했다가 계속 기다렸네요. 에이케이몰 오픈시간이 11시라서 딱 11시에 문열어줍니다.', 64, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '1인 1메뉴에요. 아이들은 거의 파르페를 먹긴 해요. 오픈런으로 다녀왔고 11기 오픈인데 10시 20분에 도착해서 줄서서 대기표 16번 받았어요. 80분 대기하다가 들어갔습니다.', 20, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00095@test.com'), '진짜 인간적으로 음료맛 좀..!!! 만원 가까이 하는 음료들이 메가커피보다도 맛이 너무 떨어져요 맛있게 못 만들거면 그냥 사이다 콜라 오렌지주스 팝시다 인간적으로 가격도 비싼데 좀 신경 좀 씁시다', 27, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '2월 23일 오전에 입구에 계신 직원분께서 너무 친절하게 해주셔서 편하게 이용 할 수있었어요. 감사합니다. 다 맛있어요 그런데... 파르페는 맛이 없었어요ㅜㅜ', 52, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '아이와 딱 한번만 오기 좋은곳이네요 ~ 3500원 계산하고 받지 못한 쿠키가 아른거립니다. 음료 주실때 같이 주시는줄.. 쿠키는 앞에 두신거 하나 들고 오는거였나봐요 아이들과 간거라 정신이 없었는데ㅜ 와플은 생각보다 맛있었어요 네임스티커 만들어온건 이쁘네요.', 16, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '아이둘과 방문했어요. 저녁 시간이라 그런지 생각보다 사람이 많지 않아서 좋았어요. 아이들이랑 1시간 내내 사진 찍느라 바빴네요^^;; 음료는..달아요ㅋㅋㅋㅋㅋㅋㅋㅋ', 7, 2, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '아이들이 좋아하는 곳이에요. 디저트랑 음료 가격이 정말 비싸요ㅠ 7세아이 둘 어른둘 해서 54000원 나왔네요 ㅋㅋㅋ커피 하나시켜서 나눠마셨는뎁 ㅠ', 4, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '시나모롤카페의 존재만으로도 감사합니다 근데 이번에 와플이 너무 딱딱해서 먹기가 힘들었어요 아기랑 갔는데 딱딱해서 먹일수가 없었어요 ㅠㅠ 평일 낮타임에 갔는데 사람이 그렇게 붐볐던 것도 아니었는데 미리 제조해놓는건 바쁜 타임에 한해서만 해주셨음 좋겠어요 ㅠㅠ 그것빼고는 만족합니다', 58, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '시나모롤에 완전 빠진 여자아이들에게 천국이네요. 다양하진 않지만 굿즈들 퀄리티도 좋고 좋은 시간 보내고 갑니다. 직원분들도 친절해요. 예약만 쉽다면 좋을텐데 너무 치열해요ㅜㅜ', 80, 14, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '사진도 대충 찍어도 다 잘나오고 특히 음료랑 와플이 캐릭터가 뚜렷해서 더 👍 포토존이 작은듯도 하지만 알차게 찍을수도 있어서 더 좋아요. 포토카드도 이쁘고 만족합니다. 와플도 음료도 맛있었어요. 양이 많아서 아주 배불렀지요^^ 네이버예약하기가 쉽진 않지만 오길 넘넘 좋아요.', 45, 0, 'GOOD', SYSTIMESTAMP);
