INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '아이들은 난리납니다 산리오가 요즘 유행이라 저는 음료도 와플도 맛있었는데( 달아서 당뇨걸릴 것 같지만ㅋㅋ) 리뷰에 별로라는 분들이 계셔서 밍밍할까 싶었어요 아이도 즐거워하고 띠부씰도 모으고 좋았어요', 64, 16, NULL, SYSTIMESTAMP);
