INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '아이가 시나모롤을 너무 좋아하니까 광클해서 예약하고 와봤어요^^ 까페분위기도 좋고 인테리어도 이뻐서 사진찍기넘 좋네요^0^ 디저트들은 다 비싸지만 그래도 한번쯤 와볼맨 해요 ㅎㅎ', 111, 22, 'GOOD', SYSTIMESTAMP);
