INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '조용하니 사진찍고 먹기에는 편했으나, 음료맛 가격에 비해 너무 별로 였습니다. 아이꺼라도 가져가려고 했는데 테이크아웃도 안되고 직원분들도 내부적으로 채용하신건지 대행을 낀건지 친절함도 없어서 그냥 모든게 별로였습니다. 지난 산리오러버는 음료도 직원들도 완구구매부분도 너무 완벽했거든요. 아무리 이벤트성이여도 그만큼 더 정성이 있어야된다고 생각합니다. 왠만하면 리뷰 안남기는데 즐거운 마음으로 갔다가 서비스가 너무 별로여서 리뷰남깁니다. 예약하고 설레고 가는 사람들 생각해서라도 신경써주세요.', 9, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '초딩 딸래미들과 같이 갔는데 먹고 싶은 생크림케익은 못 먹어서 상당히 아쉽고 전반적으러 가격대가 있음 초딩 딸래미들은 엄청 조아함', 132, 93, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '아이들이 많아서 다 큰 성인은 포토존 찍은땐 조금 민망함;; 그렇지만 너무 귀여움. 음료가 비싸지만 귀엽고 맛있음. 굿굿~~ 직원분들이 친절해요.', 21, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '일곱살 여아 취향이에요^^ 사진 찍느라 정신없이^^ 1인 1메뉴라 조금 부담스러웠지만 아이들이 즐겁게 놀 수 있어서 마음은 편했어요 -와플이 18천원인데 이것도 1메뉴인지라- 음료는 아이스크림 녹기전에 먹으니 잘 먹었어요. 와플은 생각보다 맛있었네요^^ 약간 찰떡 같은 느낌이라 저한테는 잘 맞았어요^^ 1시간 이용이라 짧다 생각했는데, 아이들 집중력 등 봤을 때 짧지 않았어요^^ 다행이다 싶었어요. 그리고 교통은 공항철도 탔는데 안내에는 70m 이격이라 했으나 전혀~~ 진짜 가까워요. 에스컬레이터 올라오니 옆이 건물이었어요. 대중교통 강추합니다^^', 51, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '딸이 너무 가고싶어해서 다녀왔어요~ 파스텔톤에 시나모롤이 잘 꾸며져 있어서 사진찍기 너무 좋아요~ 하지만 공간이 조금 더 넓었으면 좋겠고, 기프트샵도 종류가 더 다양했으면 좋겠어요~', 9, 8, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '9살 딸아이를 위해서... 예약성공.. 아아 마시고 싶었는데 엄마의 커피도 딸아이가 원하는 캐릭터 모양으로 한가지씩 모두 주문... ㅎ 파르페 소다 모카 와플.. 가격은 사악하지만 맛은 있었어요.. 소다만 빼구요.. 12살 아들왈.. 왜 에이드에 아이스크림을.. 사이다에 우유타먹는거 같다고 ㅋ 파르페 소다 모카 와플... 음료 음식 가격이 사악하긴하지만 맛은 있었어요.. 카페내부는 너무 큰 기대를했었는지 생각보다 작았어요.. 포토존도 샵도요.. 한번쯤은 가봐야하는곳인데 다녀와서 마음이 편합니다', 127, 19, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '조금더 청결했면 하는 아쉬움이  있었어요 탁자는 깨끗한데 바닥이 많이 끈적거려서 움직일때마다 신발이 붙어 기분이 상했어요  사진찍는곳이 생각보다 많이 작았어요 그가격과 그 시간 그 예약을 생각하면 좀 많이 아쉬워요', 46, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '다들 좋다좋다해서 어렵게 예약해서 갔는데... 입소문난거에비해 왜 다들 좋다는지 모르겠네요. 뭐든게 비싸고..  기프트샵도 종류도 별루없어요. 어렵게 예약한거에비해 그냥 현장으로도 들어갈수있더라고요..  사진찍기에도 넓지않아요.. 아무튼 다음에 또 가지않을거 같아요.', 23, 6, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '아이가 엄청 좋아하네요 백화점 안에 있어서 춥게 기다리지 않아도 되고 테이블 정리하시는것 보다 사진 먼저 찍을수 있게 배려해주시고 주문도 상냥히  받아주시고 엄청 친절하세요 즐겁게 있다 왔습니다', 54, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '아기자기하게 예쁘고 특색있어요~! 그런데 방문객수에 비해 직원수가 부족하신 것 같아요ㅠ 음료/음식을 직접 픽업드랍 하는 것까진 이해하는데 자리 청소 등을 신경쓰실 겨를도 없더라고요. 회사 측에서 예약을 조금 텀을 두고 받으셨으면 하는 아쉬움이 있네요~ 그래도 아이들이 좋아하고 부모들도 어릴 때 추억이 떠올라서 즐거운 경험이긴 합니다!', 12, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '아이가 좋아하니 저도 행복한 시간이었어요. 입장 방법이 좀 개선 되었으면 합니다. 샵은 너무 작아서 계산 하기도 힘들더라구요. 아이들이 방문 하는 곳이니 친절한 마인드도 필요합니다.저희 아이가 여기 일하는 언니들은 힘든가봐 하며 표정이 어둡다고 하더라구요. 저희가 물건을 사고 카페 값을 지불 하는 금액에 미소와 친절은 값은 미포함 인가봅니다. 손님 많이 받고 연장 운영 하고 다 좋지만 카페 분위기에 맞는 영업 방법도 필요하다고 봐요', 33, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '7살이 된 딸이 너무 좋아했어요. 주말예약은 오픈1분만에 예약이 완료되어서 금요일 저녁시간에 다녀왔어요. 오산에서 간거라 일부러 같은건물에 숙소도 예약해서 오랜만에 세식구가 서울나들이 하고 왔어요~사진도 많이 찍고 시나모롤 아이스크림도 맛있었고, 띠부씰과 컵받침도 잘 받아왔어요. 물티슈도 기념으로 2장 받아왔어요^~^', 48, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '제가 시나모롤 좋아해서 산리오 팬인 지인이랑 같이가려고 예약 뜬 순간 예약했는데 11시 매진.. 그래서 후다닥 12시로 다시 예약해서 갈 수 있게된 시나모롤 스위트 카페 !! 들어가는 입구부터 시나모롤 팬은 죽습니다.. 너무 귀엽고 아기자기해요 🥰  너무너무 귀여운 캐릭터였지만.. 조명 때문인지 사진이 어둡게 나온건 아쉽네요.. 여기 음료 맛있어요 👍👍 와플은 양이 많아서 패쓰 했지만 여럿이 왔을때에는 나눠먹어도 괜찮을 것 같은 사이즈였어요 🥰 다음에 다시 예약해서 방문해보고 싶어요 🥰', 37, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '초딩 조카랑 같이 방문했는데 엄청 좋아합니다. 다만 캐릭터 값 때문인지 음료와 푸드 가격이 좀 비싼감이 있습니다. 와플이 생각보다 속이 꽉 찼고 쫄깃하고 떡 같은 식감이라 맛있어요! 솔직히 음식은 기대 안하고 갔는데 와플은 진짜 한 입 먹고 놀람ㅎㅎㅎ 조카에게 이모 최고 라는 말을 듣고 싶다면 한 번 정도는 가볼만 합니당.', 90, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '아이가 시나모롤을 너무 좋아해서 방문했어요. 평일 오전에는 사람이 별로 없어서 좋았네요. 아기자기한 포토존과 음료가 있어서 너무 좋았습니다. 다만 오픈 전 비예약자 대기권을 특정한 곳에서 사전공지 없이 나눠준게 아쉽고, 자리가 있음에도 들어가지 못하게 하는게 불편하네요', 32, 5, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '입장후 1시간 시간제이고, 예약한 수고에 비하면 짧다 생각했는데.. 1시간이면 충분해요 ㅋㅋ 커피는 생각보다 괜찮고 와플도 맛있었어요~ 포토존이 좀 더 넓었으면 좋았겠지만 아이가 좋아해서 만족합니다 :)', 40, 7, 'GOOD', SYSTIMESTAMP);
