INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '예약을 안 하고 가면 웨이팅 3시간 45분은 진짜였어요... ㅠㅠ 산리오 러버스 클럽도 다녀왔지만, 이쪽은 포토존이나 포토카드 이용하시려면 꼭 예약해서 가세요. 역 가깝고 시나모롤 굿즈도 가득해서 좋아요. 굿즈는 시나모롤만 팝니다. 한 번쯤은 이벤트성으로 가볼만 합니다!', 12, 8, NULL, SYSTIMESTAMP);
