INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '아이가 꼭 가야한다고 해서 예약도 성공해서 다녀왔어요~ 띠부씰 많이 받아주려고 이것저것 주문했는데 파르페는 바나나를 안좋아해서인지 저희스타일은 아니였어요.. 와플은 맛있는데 계속 먹으니 니글니글 느끼해져서 둘이서는 다 못먹겠더라구요~ 한번쯤 가볼만 한데 두번은 안갈것 같아요 ㅎㅎ', 24, 4, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '산리오 카페보다 훨씬 쾌적하고 좋아요 메뉴도 귀엽고 띠부씰도 골고루 귀엽게 나왔어요 어린 사촌이랑 사진 많이 찍었습니다 포토카드도 귀여워요', 117, 26, 'GOOD', SYSTIMESTAMP);
