INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '시나모롤 좋아하는 딸과 함께  네이버예약후 방문했어요 대기는 따로 없이 한가하고 주문과 음식나오는 시간도 오래기다리지 않았어요 주문액수에 따라 띠부실도 챙겨주시고 아이가 너무 좋아했네요 다만 가격에 비해 와플과 파르페는 맛이 좀... 와플에 바삭함은 없고 가운데 캐릭터부분이 두꺼워서 인지 마치 쫄깃쫄깃 떡을 먹는 느낌이네요  혹시 덜 익은게 아닐까 여쭤봤더니 원래 붕어빵같은 식감이라고 ^^;; 비주얼로 먹는거다 생각해야겠어요 인테리어도 예쁘고 포토존도 아주 작게 마련되어있어 아이와 좋은 추억은 쌓고 왔네요.. 재방문 의사는 글쎄요...', 45, 9, NULL, SYSTIMESTAMP);
