INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '아이가 엄청 좋아하더라구요 커피나 와플이 엄청 맛있는건 아니어서 좀 아쉬웠지만 아이가 신나하는것만으로도 만족했던 곳이네요 한번쯤은 가볼만한 곳입니다', 108, 20, NULL, SYSTIMESTAMP);
