INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '아이들 정말 좋아합니다! 운좋게 예약해서 잘 다녀왔어요. 와플 생각보다 크고 맛있어요. 커피는 무난하고, 피치소다 맛있네요! 1시간 이용은 좀 아쉬운것 같아요ㅜㅜ', 72, 16, NULL, SYSTIMESTAMP);
