INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '시나모롤 좋아하면 한번쯤 가도 괜찮은 까페에요 안에 파는 것들 쇼핑하면 돈이 엄청 나가요 응대해주는 직원분이 친절하시지 않고 지쳐보이시네요 너무 많은 고객을 상대하셨나', 122, 24, NULL, SYSTIMESTAMP);
