INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '생각이상으로 너무 좋았어요!! 주말이였는데 제가 좀 늦은타임에 예약이였어서인지는 모르겠지만 사람이 엄청 많지않아서좋았고 포토존도 아주 잘되있어서 사진찍기에 넘넘 좋더라고요 ㅎㅎ 음료도 맛있고 쿠키도 맛있었어요.이용시간도 한시간이면 부족했을거같은데 한시간반이라 그래도 넉넉히 있다가 갔어요!', 49, 6, 'GOOD', SYSTIMESTAMP);
