INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), 'ak앤몰 주차 발렛된다고 해서 자차로 갔는데 평일 4시 예약 기준 만차라서 주차장출구쪽에 길주차 몇대 되어있는 곳에 길주차하고 불안해하며 입장했는데 다행히 단속은 안 당했어요 마음이 불안했을뿐ㅠ 아이가 너무 좋아해서 뿌듯한 하루였어요', 85, 15, NULL, SYSTIMESTAMP);
