INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '딸아이가 좋아하는 시나모롤카페 경기도 사는데 힘들게 갔어요 갔는데 세상 귀여운 인테리어 보고 힘든게 다 사라졌답니다 딸도 행복해하는 모습 보여주니 다녀오길 잘 한것 같아요', 49, 0, 'GOOD', SYSTIMESTAMP);
