INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '음료값이너무비싸고 와플을먹었는데 미리구워놨는지 너무딱딱하고질겨서 씹기도힘들뿐만아니라 칼로도안썰어지더군요ㅜㅜ 비싸게받더라도 메뉴질을떨어트려파는행위는 너무별로였습니다. 애땜에한번가는거지만 다신가고싶지않아요.', 76, 17, 'BAD', SYSTIMESTAMP);
