INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '유명세에 힘입어 와봤어요. 포토뷰가 굉장히 넓고 와플은 꼭 드세요. 카페에서 많이 사면 띠부실줘요. 몰 안에 있어서 화장실도 자유롭고요. 시나모롤 아이템을 더욱 더 많이 가져다주세요.', 47, 8, NULL, SYSTIMESTAMP);
