INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '한시간 부족할줄 알았는데 괜찮았어요 디저트 예쁘고 귀엽고 와플맛은 그냥그냥이었지만 전체적으로 한번 가볼만하고요 컵을 사고싶었는데 비싸서 고민하다 돌아왔네요 ㅜㅜ', 3, 10, NULL, SYSTIMESTAMP);
