INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '주차 편하고, 찾기도 쉬워요 예약하고 왔더니 대기없이 바로 들어와서 너무 좋았어요! 와플, 맛 없을줄 알았는데 생각보다 맛있어서 놀랬어요☺️ 여자아이들의 천국 시나모롤카페입니다', 9, 0, 'GOOD', SYSTIMESTAMP);
