INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '완전 귀엽구 좋았어요!>< 그치만 아이스 아메리카노는 산미가 너무 강해서 먹기가 조금 힘들었구, 파르페 위에 올라간 마카롱은 좀 많이 딱딱했어서 어린아이들이 스스로 먹기엔 확실히 어려워보였어요😂 파르페는 무난하게 먹을만했어요! 곳곳에 사진찍기 좋을만한 곳이 많아서 여기저기 사진 촬영하기에도 좋았네요!', 5, 4, NULL, SYSTIMESTAMP);
