INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '현장접수로 3시간 넘게 대기하고 들어갔네요. 아이가 좋아함..  음료 소다는 무맛..  아이가 맛없다고함..  시나모롤이 뭔지.. 20만원 넘게 구매했는데 주차비가 3시간 밖에 적용이 안되네요. 주차비만 추가로 만원 냄', 71, 12, 'BAD', SYSTIMESTAMP);
