INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '귀엽고 귀엽고 귀엽고… 콜라보카페라 음료나 디저트는 진짜 비싸요 씰 스티커랑 코스터가 귀여워요 와플은 가장자리는 바삭한데 속이 좀 많이 말랑 쫀득이었어여 어쩌다 한 번은 가볼만하지만 포토존이 생각보다 작아요', 73, 15, NULL, SYSTIMESTAMP);
