INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '아이들이 정말 좋아했어요. 또 가고싶다고하고 음료랑 와플 푸짐해서 배부르게 먹었는데 종류가 좀 더 다양하면 좋겠어요~^^ 아이가 재방문 하고싶어해서 또 가볼까합니다.', 66, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '딸이 가고 싶다고 해서 겨우 취소 예약 하고 갔어요~ 아이는 엄청 좋아하고 사진 찍고 잘 보고 왔어요. 대신 메뉴를 기대하기 보단 아이가 좋아하는 시나모롤 보러 가는 그런.. 곳이에요~', 42, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '아이들만 좋아하는것이 아닌, 어른이들도 신났던곳 사진찍이 예쁜 음료와 평소 아이가 좋아했던 시나모롤 함께 사진찍고 오니 좋았어요. 사진찍을수 있는 공간이 좀 더 있었음 좋겠다라는 생각에 공간이 협소했네요.', 0, 9, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '아이가 셋이라 1인당 4명예약만 가능하다길래 남편과 제 이름으로 각각 예약해서 방문했습니다. 평일 7시 마지막 타임이라 사람도 없었는데 최대 4명만 앉을 수 있으니 가족이라도 2명 3명 따로 앉아야 한다고 하더라구요… 테이블도 붙이면 안된다고 하고.. 결국 애들이 엄마랑 앉는다고 해서 아빠만 혼자 옆테이블에 덩그러니… ㅠㅠㅋㅋ 바닥엔 전 타임에 떨어진 쓰레기도 청소가 안되어 있고 테이블도 음료 흘려진게 닦여있지도 않고 음료랑 와플 주문해서 먹는데 따로 덜어먹을 접시 없다며 플라스틱컵을 주더라구요.. 와플은 미리 만들어 놓은거 데워줘서 과자처럼 딱딱하고… 휴지도 비치되어 있는게 없고.. 아이들이 좋아해서 방문하는 곳인데.. 위생 음식 다 별로였습니다. 직원들이 친절하지도 않고.. 다신 방문 안할꺼같아요.', 121, 21, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '아이가 너무 원해서 어렵게 예약하고 갔는데 어른눈으로 봤을땐 생각보다 별로 였어용 앞쪽에 입장도와주는 직원이 없어서 제가 여기저기 직원을 찾으러 다녀야했고 입장하는 입구쪽에 대기줄도 같이 있어서 들어가기 불편했어요 음료도 1인1주문이라 어린아이음료도 시켜야해서 음.. 와플도 18000원이면 저렴한 가격이 아닌데 시중 커피집에서 먹는.와플과는 달라요 무슨 떡 먹는줄.... 찰기가 엄청나요 다 남기고와서 애들은 좋아했지만 두번은.안갈듯해용!', 21, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '시나모롤과 사랑에 빠진 아이와 평일 첫타임으로 다녀왔어요💛 포토존이 다양하진 않았지만, 넓지 않아 오히려 여유롭게 예쁘게 사진 찍을 수 있어서 좋았어요. 예쁜 사진 포토카드 만드는것도 너무나 재미있었네요😆 시나모롤 와플과 스윗피치소다 보기에도 예쁘지만,정말 맛있었어요!! 그리고 랜덤띠부씰도 즐거웠습니당^^ 아! 그리고 직원분들 엄청 친절하셨어요! 기프트샵에서 사고싶었던 시나모롤 물건들 잔뜩 사서 기분 좋은 하루 보냈습니다❤️', 23, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'AMERICANO');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '아이가 너무 기대하던 곳이에요. 금요일 일찍도착해 현장 예약으로 대기 6번으로 기다렸는데 11시 20분쯤 기다리고 들어갈 수 있었어요. 와플이랑 음료 주문해 띠부실 받았고 인형 하나 구입해 총 7개 받았어요~~ㅎㅎ 돈을 많이 썼단 얘기죠ㅎㅎ 아이가 너무 좋아했던 터라 기분좋게 쓰고 왔어요. 감사합니다', 20, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '문앞에서부터 시나모롤 도배가 되어있어요. 아이가 시나모롤을 너무 좋아해서 갔는데 음료도 시나모롤이고 와플도 시나모롤이예요 ㅎㅎ 포토존도 민트민트 너무 예뻐요~ 와플과 음료들 시켰는데 초코라떼랑 딸기라떼는 진하고 맛나요 스윗피치소다였나 음료가 참 예쁜데 제 스타일은 아니었어요 ㅎㅎ 와플은 맛있었는데 와플과 과일을 안먹는 첫째는 초코라떼외에는 먹을게 없었어요ㅠ 와플과 음료 다 가격대가 높지만 자릿세라 생각하고 먹었어요. 그리고 컵이 너무 예쁘다 생각했는데 옆에 샵에서 판매하길래 사왔어요~ 산리오를 너무 좋아하는 딸아이때문에 산러클을 자주 갔었는데. 그곳은 갈때마다 주차전쟁에 공영이어도 비싸서 주차비에만 만원이상 냈었는데 스위트샵은 주차비지원은 없지만 ak몰에서 5만원만 사도 애경주차타워 3시간 무료라좋아요.', 26, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '8살된 아이가 좋아해서 데리고왔는데 역시나 너무 즐거워하네요^^ 엄마인 저도 아이와 데이트하며 좋은 시간을 가졌습니다. 다른 후기보고 와플주문했는데 역시나 맛있었어요^^ 한번쯤 가면 아이와 좋은추억이될듯해요^^', 55, 12, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '와플이 의외로 바삭쫀득하고 맛있었고 비싸지만 음료도 예뻤어요. 인테리어는 산리오카페에 비해 덜 예뻤지만 찍은 사진보니 만족스럽습니다.', 29, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '하나같이 귀엽고 아기자기 해서 딸이 엄청 좋아했어요. 띠부실과 코스터 받고 엄청 신나서 날라다니더라구요. 와플도 맛있고 파르페도 에이드도 맛나게 먹고 굿즈샵가서 왕창사고 돌아왔어요~^^ 딸한테 최고소리 엄청 들었네요', 72, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '아이스크림 라떼에 초콜릿을 토핑해서 시나모롤 모양을 만들었네~ 그래서 진짜 시나모롤 같네~ 먹고 싶은 것을 골라서 막 골라 먹었다~!!', 32, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '아이가 너무 가고 싶어해서 예약해서 방문했어요~~평일이라 그런지 사람이 많지는 않았어요~~음료는 아이스크림라떼는 평범했구요~아이가 마신 딸바파르페는 맛있다고 해요~아이는 만족했어요~~', 6, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '아이와 다녀오기괜찮아요 매장은생각보다작은데사진은잘나오네요 아기자기한게예뻐요 두번세번방문할껀아니고 딸가지신분들한번정도는방문하면좋을꺼같아요~^^ 와플은생각보다맛있는데가격이...만팔천....', 126, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '가격대비 음식은 좀 아까워요~ 아이들이 좋아하니 어쩔수 없이 가지만 다음에 가면 음식은 안먹고 싶네요 와플은 가격을 좀 내려야 할듯요', 30, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '예약 후 방문 AK플라자내에 위치하고 있어 대기시간동안 여기저기 둘러보기 좋네요. 평일 저녁시간대라 붐비지않아서 여유롭게 아이랑 즐기고 왔네요.', 73, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00009@test.com'), '매장안은 작고 북적한데 예약하고 가니 편했어요 음료가격대 비싼편인데 양많고 먹을만하고 코스터, 띠부실 가격대로 주니 너무 좋았습니다', 35, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '8살 딸이 너무 좋아 하는 시나모롤 이라 열심이 지켜보다 예약 하고 다녀왔어요. 토요일에 갔는데도 붐비지 않아 좋았어요~ 딸이 너무 좋아 해서 만족 합니다 😊', 48, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '아이가 정말 좋아합니다 음료 와플 컵 스푼모든게 다 시나모롤이라 너무 귀여워요 한가지 아쉬운점은 굿즈샵에 종류가 다양했음합니다', 46, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '아이가 시나모롤 좋아해서 예약하고 갔어요~ 네이버예약 자리 표시 있는곳에 앉으면 된다고 해서 편하게 앉았구요~테이블이 많이 없고 간격도 넓어서 쾌적한 느낌이었어요~ 포토존도 막 줄서서 찍는게 아니라서 여유있어 좋았는데 조명때문인지 얼굴이 너무 어둡게 나오네요 ㅜ 와플 아이스크림 맛있었구요~ 레몬에이드랑 딸기라떼도 맛있었어요', 0, 0, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '1인1메뉴인데 와플이 2만원인데 1인으로 계산해서 넘 당황스러웠는데 그조차 한참전에 미리 만든 와플을 데워주는거에 더 놀람 ㅡ ㅡ 음료는 넘 맛없고 와플도 가격에 비해 완전 별로네요... 음료 다 남김 ㅠㅠ 그냥 사진찍는 비용치곤 넘 비싸고 별로여서 다시는 가고싶지 않음. 산리오 러버스가 훨씬 만족스러웠음.', 11, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '별루예요 애가 좋아해서 가긴갔는데 테이블도 못 붙히게 해 음료도 별루 비싸기만해 포토존은 딱 3군데고 너무 아쉬웠어요~ 한번 가봤으니 다신 안가겠네요', 0, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '1. 카페메뉴 한개당 코스터 한개씩 지급 2. 인스타에 필수해시태그 포함해서 글 올리면 코스터 1개 추가지급 3. 카페메뉴 5000원당 띠부띠부씰 1개씩 지급 4. 네이버 예약하기 개 빡셈 ㅠ 이번에 드디어 예약 성공해서 다녀왔습니다! ㅠ 확실히 시간별로 사람 얼마 안받아서 카페 내부 자체는 굉장히 쾌적하고 좋아요 입장하면 테이블에 네이버 예약좌석 자리에 앉으면 됩니당', 9, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '아이들이 많이 좋아해요 산리오카페보다 더 좋아했어요 음료도 시나몰롤띠부씰도 아이들이 많이 좋아했어요 그리고 인형도 하나씩 사고요 ㅎㅎㅎ', 6, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '11살 우리 딸아이가 너무 가고 싶어해서 예약해서 방문했는데, 실내 인테리어도 예쁘고 음료랑 와플도 맛있었어요~~(많이 비쌌지만요...ㅋ)', 16, 8, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '너무나도 귀여운 시나모롤카페~ 아이가 가고싶다고해서 네이버예약하고 방문했는데 생각보다 너무 만족스러웠어요 !! 홀도 넓게 트여서 답답하지않고 좋았어요!', 43, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '직원분들 친절하시네요 ak몰안에 있구요 주말이라 화장실 줄이 매우 길었어요. 이 까페 근처에도 아기자기한 샵이 많아 구경할게 많았습니다. 사진찍을 공간은 생각보다 넓진않았어요. 음료가 귀여워요', 17, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '아이도 좋아하고 즐거운 시간이었지만 시간이 종료되고 남은 음료가 많았는데도 불구하고 테이크아웃잔에 옮겨담아줄수 없다고 하는건 개선되었으면 합니다', 1, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '어제 두번째 방문했어요~ 예약없이 오픈시간 전에 줄서서 대기표 받아 갔는데 네이버 예약자리로 거진 빼놔서 벽석 앉으려면 꼭 예약하고 가야되요. 어린이들 데려온 가족단위 손님이 많으시더라구요. 산리오 캐릭터 좋아해서 종종 방문할것 같아요. 다음번엔 꼭 예약하고 가야겠습니다.', 23, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '애기 데리고 가서 아주 알차게 보내고 왔네요~! 카페 이용객만 이용가능해서인지 포토존 너무 여유로웠어요. 직원분들 응대도 친절해서 좋았고요. 와플 별로란 리뷰가 많아서 시켜야하나 말아야하나 고민 3초 했는데 아이가 잘 먹어서 시키길 잘했네요. 😊 전반적으로 좋았지만 기프트샵에 상품 종류가 별거 없어서 아쉬웠어요. 참고로 카페에 아기 의자가 없지만  포토존에서 노느라 잠시도 가만히 안 앉아있어서 아기 의자 없는건 전혀 문제가 안되욬ㅋ 말 잘 듣고 가만히 잘 있는 아기라면 예쁜사진 많이 찍을 수 있을 듯! 우리 애기는..🤦‍♀️', 60, 13, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '막둥이가 시나모롤에 푹 빠져서 예약하고 다녀왔는데 아이가 넘 좋아했어요 ~ 캐릭터 값이 들어가서 가격이 확실히 비싼 감이 있는데, 마시고 사진 찍으면서 좋아하는 아이보면 전혀 비싸다는 생각이 안들어요 ㅎㅎ 아이가 시나모롤을 좋아한다면 특별한 추억 심어주기 좋을 것 같아요~ 랜덤 코스터 3종 중에 중복이 있어서 아쉬워했는데 감사하게도 옆자리 이쁜 언니 두명이 안쓴다고 챙겨줘서 아이는 완전 행복하게 나왔네요 🥰 포토존에서 사진찍고 앞에 있는 포토카드 만드는 곳에서 포토카드 만들고 스티커 네임택 만들고 굿즈 샵에서 갖고 싶다는 거 사주면 행복해서 기절합니다 ㅋㅋ 다 해도 생각보다 얼마 안나오니까 풀코스로 즐기게 해주시는거 추천!', 1, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '아이와 함께 왔는데 아기자기해서 넘 좋아하네요 예약제이다보니 조용해서 사진찍기도 편하고 좋아요 근데 가격이 좀 나가는편이라 자주는 못올거같아요ㅠ', 55, 15, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '넘넘 즐거운 경험이였고 음료수가 예상보다 훨씬 맛있더라고요!! 그리고 직원분들도 너무 친절해서 기분 좋았습니다ㅎㅎㅎ재방문 꼭 할겁니당...❤️', 63, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '넘귀여운데 생각한거보다 많이작더라구요ㅋㅋㅋㅋ 포토존도 그냥 원룸같은곳에 모아져있고ㅋㅋㅋ 한번가고 만족합니다 산리오카페가 더좋았어요', 18, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '시나모롤 같이 사진찍을곳 몇개 있고 귀엽게 잘되있음, 그래도 음식파는 카페인데 앞접시로 쓸만한것도 없다고 안주고 (커피에 아이스크림 덜어주려고 물어봄) 인원수대로 음료 시켰는데 애들 레몬에이드 아예 안먹어서 테이크아웃 해달랬더니 그.래.도 카페인데 테이크아웃 잔이없다는건 처음봄 음료를 돈내고 산건데 이해할수없고 마인드가 사장이배가불렀음 기본은 지키시길', 47, 9, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '아이들과 함께간 시나모롤카페~~ 여약하기 힘들었지만 방학마지막 이벤트로 좋았어요 메뉴 가격이 비싼편이지만 예쁜사진찍고 좋았어요', 9, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '중2 초5 딸아이들과 예약 방문했어요. 여자아이들이 좋아하는 분위기와 음료에 정신없이 사진 찍어줬어요 ㅎ 할로윈 한정으로 흑임자라떼도 주문했는데 고소한데 크림을 많이 섞으니 좀 느끼하더라구요 ㅋ 아이스크림이 캐릭터모양으로 올려져 있으니 더 귀엽고 맛있더라구요~ 스티커랑 코스터도 받고 아이들과 재미난 시간 보내고 왔네요 ㅎ', 39, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '메뉴부터 카페 내부까지 넘넘 귀여워요. 와플은 눅눅함 없고 겉은 바삭하고 안은 쫄깃한게 매력있었어요. 음료도 토핑이 넘 귀엽고, 가격대는 좀 있지만 볼거리 있고 띠부씰과 티코스터 받은 것 생각하면 나쁘지 않아요. 아이들 사이에서 요즘 너무 유행이라 한번쯤 데리고 가볼만 해요.', 125, 20, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '예약시간 열리자마자 부리나케 예약해서 드디어 가봄 ㅠㅠ 산러클보다는 가게가 작지만 산러클보다 있을 수 있는 시간이 길고, 음료 와플 다 맛있고 띠부씰이랑 코스터도 챙겨주시고 완전 대대대만족 또 언제 갈지는 모르겠지만 또 가고싶어욥', 44, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '울 딸이 가고 싶다고 해서 인스타그램도 가입(사전 공지가 여기만 나오니까요)하고 알람까지 맞춰 놓구 대기 40분만에  겨우 평일 오후 7시 예약 성공함. 여기가 뭐라고.. 근데 어제 방문하고 잘 왔다 싶었어요. 과정은 힘들었으나 막상 가보니 예약제라서 카페가 한산하고 사진 찍을때도 붐비지 않고 너무 좋더라구요. 한시간동안 거기서 뭐하나 싶었는데 사진 찍고 음료 마시니 시간이 순삭 ㅎㅎ  제가 더 좋아함 ㅎㅎ', 34, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '시나모롤을 너무 좋아하는 초딩 딸과 함께 예약 후 방문했는데 너무 만족스러웠어요^^일단 예약제여서 오기 전에는 예약하기 힘들어서 불편 했지만 이유가 있더라구요!예약제인만큼 안에 사람이 붐비지 않아서 여유있게 사진찍고 좋네요^^', 88, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '산리오 러버스샵보다 기프트샵 물건 가격이 천원정도 저렴해요. 병 오렌지주스샀는데 랜덤이라, 그림을 고를수없대요. (진열이 그림대로 되어있으나 안꺼내줌) 생각보다 좁고 음료가격이 비쌈 와플은 가격대비 괜찮음 방학이라 한번 와보긴했지만 일부러 오픈런해서 기다리며 들어올정도는 아님', 22, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00027@test.com'), '시나모롤 좋아하는 아이 데리고 한번정도 갈말한데요 너무 비싸고 불친절했어요 티슈 좀 달라고 하니까 왜 째려보시는건지 모르겠어요', 112, 24, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '여기는 아이만 좋아해요 생각보다 작네요 아이들만 좋아했어요 디저트 종류가 별로 없어요 한번가면 만족스럽습니다 또 가고 싶지는 않네요…', 55, 12, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '딸아이가 너무 가고싶었던 카페라 오늘가보았어요 전체적인 분위기도 좋고 사진도 잘나오고 예쁜것 같아요 좌석도 많고 홀도 넓고요 음료는 가성비로 따지자면 별로예요 가격이 비싼듯;;; 특히 와플가격은 ㅜㅜ 다양한 메뉴가 더 나오고 가격이 좀더 저렴하면 넘 좋을듯요', 19, 3, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '11시예약인데 일찍 갈 필요가 없어요 딱 시간맞춰가는게 좋겠네요 다른데 구경도 못하고ㅜㅜ 그래도 맛나게먹고 사진 많이 찍고가요 기프트샵은 생각보다 작네요', 37, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '느낌점을 여러가지로 말하자면 최악 of 최악 힘들게 예약을 해서 간 곳 치곤 포토존(사진 찍힌 곳이 끝) 서비스가 최악이다. 갑 중에 갑이다 1. 자리가 협소해 음식 나오기 전 자리 변경 요청 -> 이동불가 , 의자도 움직일 수 없음 2. 쟁반 용지 변경 요청  (쌍둥이라 똑같은 용지로 변경 요청) -> 음료 추가주문에만 가능하고 작은용지에서 큰용지로도 변경불가 뭐든 추가 주문을 강요하고 요청사항이 뭐든 전부 불가불가 불가 (맛이 없음) 1시간 이용만 가능함에도 서비스도 공간도 별로다 별로 추천하지 않음 만약 꼭 가야한다면 예약하지말고 옆에 기프트샵에 가는걸 추천합니다 다 평이 좋은것만 있는지 이해 불가입니다', 28, 8, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '아는 동생과 함께 방문해서 와플과 아이스크림 라떼 마셨는데 와플 맛있었고 아이스크림 라떼도 달지 않았고 맛있었어요! 정말 최고입니다!!!', 46, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'LATTE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '와플도 맛있고 아이스크림라떼 레몬에이드 다 맛있어요~~ 인테리어도 너무 예쁘고 포토존도 잘 되어있고 친절해서 너무 좋았어요~!! 네이버로 예약해서 방문했는데 아이가 너무 좋아하네요^^', 7, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '예약하기 너무힘든 시나모롤카페 드디어 오늘 갔다왔어요^^ 주말이라 사람들이 많았지만 예약해서 그런지 봐로 들어가 시키고 한시간동안 여유롭게 맛있게 먹고 사진도 찍고왔어요 울딸이 넘좋아하니 저또한 오늘 행북한 하루를 보냈네요.담에 또 기회가되면 또한번 가보고싶네요^^', 6, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '아이가 좋아하여 네이버 예약 후 다녀왔어요. 평일이여도 방학이라 사람들이 많더라구요. 한 번쯤 와볼만한 거 같아요.. 포토존이 생각보다 작더라구요..와플가격은 조금 비싼듯해요..', 32, 6, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '항상 일본 시나모롤 카페만 보고 너무너무 가보고 싶었는데 한국에도 이렇게 시나모롤만을 위한 스위트 카페가 열려서 너무 행복했어요!!🐶💙 시나모롤 모양의 귀여운 음료들 .. 사실 그냥 귀여울 줄만 알았는데 맛도 있어서 놀란..!🍦 힘들게 예약한만큼, 다양하고 귀엽게 꾸며진 포토존을 여유롭게 즐길 수 있어서 좋았어요 ( ु ´͈ ᵕ `͈ )ु 있기만 해도 행복한 곳이라 다음에 또 방문하고 싶습니당☁️', 43, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '잼민이가 좋아할거 같아 알람해두고 예약 겨우 했어요 기차타고 전철타고 전철역 내려서 가까운게 가장 큰 메리트였고 생각보다 빈자리가 많아서 이제 올 사람들 다 온건가 싶엇어요 주말 아니라 그런가... 메뉴는 인당 시켜야하는게 좀 그랬는데 사진 찍는 값인가 싶기엔 너무 비싼감이 있고 맛도 그냥저냥쏘쏘예요 사진은 너무 잘 나오고 인테리어 맛으로 모든걸 다 감수해도 되겠다 싶은데 먹고 사진 찍고 나가자고... 시간을 보내기에 그닥 오래 걸리진 않겠더라구여 경험치고 갈 만 했어요', 118, 23, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '빨리 방문하고픈맘에 매일 예약 들어오다가 4시로 겨우 잡았지만 현장대기 가능해서 11시 오픈맞춰도착했음. 평일이라서 그런지 바로 입장가능 애들 취향 맞춰 음료 시킴 바나나파르페는 씨리얼이 먹기 불편 퍽퍽 다른건 맛있음 와플도 과일,아이스크림 있어서 비싸다는 생각 잊게해줌 사진찍기 이쁘고 90분 까페 이용가능해서 먹기 여유로움 굿즈도 비싸지않아서 몇개골라도 부담없었음 아이들 행복한 시간보냄 띠부씰 엄청 주셔서 (금액 맞춰 주셨겠지만 만원,오천원단위 맞춰주시니ㅋㅋ ) 좋았음', 27, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '7살 여아랑 갔는데 생각보다 너무 좁고..음료도 너무 비싸고 사진찍는공간이 너무 좁아서..음료값에 비해 별로 였어요 그냥 딱 한번만 가볼만한곳?? 가장큰게 주차도 ak는 큰차는 주차도 못해서 주차할곳을 한참을 돌아 다녔네요..ㅠ', 42, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PARKING');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '초반에 갔을 때랑 인터리어 바뀐부분이 없어서 아쉬웠어요ㅠ 새롭게 좀 더 꾸며주면 아이가 더 흥미 가지고 좋아할거같아요~ 직원분들은 친절해요^^', 55, 11, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '아이가 너무 가고싶대서 아이 생일맞아 어렵게 예약 성공하고 갔으나 솔직히..너무 별로였음. 두번은 안갈듯.. 음료도 비싸고 맛도 그닥..달고 달고  ㅋ 어쩔수 없이 주문한 와플도 모양만 이쁨. 둘이 먹기에 양은 많으나 맛은 없음.다들 남기고 버리드라 . 돈만 비싼곳.. 포토존..정말 작음. 그냥 방 한칸 끝. 너무 기대하고 가지 마시길..  그래도 아이는 좋아함', 38, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '완전 귀여워요! 연령대도 다양하고 커플,친구,가족끼리 많이옵니다 혼자오셔도 카페가 엄청 귀엽게 꾸며져있어서 놀러오기좋아요~ 사진 많이 찍고가세요! ☺️☺️', 10, 3, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '귀여운 것들로 가득 찬 공간이네요! 네이버 예약 후 방문하여 복잡하지 않고 좋았어요. 시나모롤 와플 맛있고 양 많아요. 굿즈샵에 물건이 좀 적어서 아쉬웠어요. 특히 키링 품절...ㅠㅠ 언제 입고될지 알 수 없어 너무 아쉬웠네요. 그치만 사진 찍고 추억 만들기 좋은 특별한 공간이라 한 번쯤 가볼 만 해요!', 25, 4, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '예약하기 너무 힘들었지만 잘 꾸며져 있어서 조카가 너무 좋아했어요! 신분증이랑 예약 화면 확인한다고 해서 제가 따라갔는데 현장에서는 신분증은 따로 확인 안하시고 네이버 예약 화면만 확인하셨습니당 재밌었러요!', 18, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '더보기 눌러서 메뉴판 참고하세요 ㄱ 2번째 방문이였어요! 역시 예약 개빡센곳.. 예약 빡세다보니까 산러클보다는 확실히 애들 적고 약간 좀 걸러진 느낌..? 저번에 와플 먹어봐서 이번엔 와플 안먹고 음료만 시켰는데 레몬에이드 너무 노맛 ㅠ 파르페는 그나마 먹을만했어요. 근데 마카롱은 좀 딱딱해서 ㅜ 베어먹기 좀 힘들어욤', 42, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00050@test.com'), '너무 귀엽고 예뻐요 네이버 예약은 힘들지만 그래도 안은 북적이지 않아 좋았습니다 초등딸이 너무 좋아했고 입내밀던 아빠는 와플이 쫀득해서 맛있다며 좋아했습니다^^ 여기저기 사진도 찍고 즐거운 가족 데이트 하기에 너무 행복한 곳입니다 주차가 가능해서 너무너무 좋았습니다^^', 23, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PARKING');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'DATE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '메뉴 가격이 좀 센 편이에요 위 사진에 있는 메뉴 3개 총 33500원이었어요 가격대 비해서 맛은 그냥 그랬어요 그리고 12월부터 이용시간이 기존 1시간 30분에서 1시간으로 변경되었다네요 이런건 공지를 좀 해주셨으면 좋았을 것 같아요~ 저희는 경험삼아 한번 방문으로 만족하고, 더 가지는 않을 것 같아요 * 주차 AK 몰에 발렛 주차(무료) 이용했고, AK 몰에서 5만원 이상 구입 시 3시간 무료 주차인데, 여기 주문한 금액만 해도 3만원이 넘고 기프트샵에서 몇 개 구입하니 5만원 그 이상으로 훨씬 더 지출을 해서 주차비는 안들었어요 3시간까지 무료라 주변에 있는 카카오프렌즈샵도 들러서 구경하고 나왔어요', 40, 9, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'FACILITY', 'PARKING');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '음료가 비싸지만 시나모롤 데코가 너무 귀엽고 맛은 있었고 제한시간 1시간이 생각보다 짧아 아쉽기도 했지만 사진 찍기가 좋고 아이가 너무 좋아해서 만족합니다~', 72, 16, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '시나모롤 좋아하는 아이가 있으면 가볼만해요. 아기자기하게 잘 꾸며져있고 예뻐요. 다만 음료랑 와플 가격이 비싼 편이고 굿즈샵이 생각보다 작아 아쉬었어요.', 47, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00049@test.com'), '늦둥이 동생이 너무 가고싶어해서 해봤는데 한번에 티켓팅 성공해서 잘 다녀왔어요! 좀 아쉬운 점은 포토존이 꽤 클거라고 생각하고 갔는데 그건 아니더라구요ㅜㅜ그냥 블로그에 나오는 포토스팟 두군데정도? 그래도 이것저것 사와서 동생이 너무 좋아하는 모습 보니까 뿌듯해용', 50, 1, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '좋아요 아이가 좋아하네요 음료마다 아이스크림 올라간거 너무 별로예요 아이스크림 올라간 음료는 3개 인데 스푼 하나 없이 주고 스푼 요청하니까 달랑 하나 주고 센스부족 인건지 아이스크림 입으로 그냥 먹으라는 뜻? 아이때문에 갔는데 음료 맛없고 다 버리게 생겼네요 한번은 경험 해볼만', 106, 25, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '분위기 좋고 예약제 운영이라 북적이지 않고 사진찍을 수 있어서 좋아요!! 생각보다 규모는 작지만 특별메뉴가 있어 아이들 엄청 좋아합니다~ 음료도 와플도 평균맛은 하니 한번쯤 가 볼만 해요!', 3, 9, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '예약하고 다녀왔는데 생각보다 카페안은 꽤넓어요~그런데 굿즈판매 하는곳은 좀 좁더라구여~우리 두 아이들이 워낙 시나모롤을 좋아해 잘다녀왔네요~음료도 맛있어요', 24, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '와플이랑 파르페 두개 27,500원인데 와플은 그럭저럭 괜찮았는데 파르페 정말 맛없고 별로였어요 같이간 일행이 시킨 음료도 별로ㅜㅜ 가격비싸고 맛은 없네요 애들이 좋아하니까 사진찍을려고 갔어요~ 평일에는 예약안하고 그냥 대기해서 들어가도 널널해요 한번은 가도 굳이 두번은 안갈 것같네요', 15, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '시나모롤 좋아하는 분이라면 너무너무 맘에들 곳입니다 저두 시나모롤 덕후라 넘 만족스러웠어요! 와플도 바삭하도 음료도 기대이상이었어용 또 갈거에요~♡', 126, 23, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '가격대비 음료나 음식은 그냥 그랬고 그래도 띠부씰이랑 티코스터 챙겨줘서 아이들은 좋았어요. 앞에서 입장 체크 해주시는 분의 서비스는 정말 별로였어요 빈 자리가 많은데 연락도 오지 않는 타임별 예약 손님들 자리라며 앉아있던 사람들을 내쫓으시더라구요. 물론 가게의 규칙이라는게 있겠지만 어느정도의 융통성은 적용할 수 있는거 아닐까요? 유독 우리가 있었던 타임대의 직원분이 그러셨던건지는 모르겠지만 아이도 그렇고 어른도 그렇고 별로 좋은 느낌으로 기억되지는 않을것 같네요.', 7, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '아이들이 너무좋아하구요~~ 들어가자마자 사진찍기 바뻐요~~ 메뉴는 특별한데 맛은 그냥 가격대비 soso 토요일에 저녁늦게 갔는데 .. 직원이 자리를 비우고 티켓검사안하니깐 그냥 막들어와서 메뉴주문하더라고요 몇개월동안 예약을 시도한 1인으로서 억울(?)하도라규요 ㅜㅜ 아이들이 행복했다니 그걸로 만족합니다~', 39, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '아기자기하고 너무 귀여워서 시간가는줄도 몰랐네요ㅎ 1시간30분이 너무 짧았어요ㅎ 아이가 좋아해서 맛있는 디저트에 아이스크림라떼 먹고 왔어요ㅎ', 25, 1, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '앞에서 안내는 60분 이라거 하고 공지는 90분이라 정확한 이용시간을 모르겠어요- 그리고 음료값은 사악해요 애기는 좋아합니다 ^^;', 46, 2, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '예약해서 다녀온 보람이 있어요! 음식도 넘 예쁘고 내부, 외부 포토스팟이 넘쳐나서 주문해놓고 열심히 구경하고 사진찍다보면 시간 금방 갑니다!', 13, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '두번째 방문이에요. 구매금액5천원당 띠부씰을 주니 애들이 더더욱 좋아하네요. 음료랑 와플도 맛있는데 포토존 소품이 너무 지저분해요. 사진상으로는 잘 안나오긴 하지만요.', 44, 10, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '정신없어요..조명이 안이뻐서 사진은 이쁘게 안나와요. 띠부실 3개중에 두개 중복이 나와서 센스있게 좀 바꿔주면 좋을텐데 그럼점도 아쉽고 굿즈도 생각보다 별로없어서 이래저래 아쉬웠어요.그래도 아이들은 엄청 좋아했네요.', 488, 67, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '산리오러버스보다 깨끗하고 공간도 넓어서 더 나음. 미예약자가 왜 못들어가냐고 진상부리는 소리를 듣자니 매우 짜증남. 나도 초등아이델꾸 어렵게 예약해서 갔건만 애둘 데리고와서 빈자리 있는데 왜 못들어가냐고 ㅈㄹㅈㄹ 챙피하다. 1시간 이용시간은 좀 불편했다. 와플이랑 커피먹고 좀 천천히 움직이고 픈데,, 케릭터샾은 물건이 너무 없어서 허탈 ㅜ 작정하고 물건 사주려고 들어갔건만 가짓수가 적음. 그래도 초등아이에게 행복한 시간이었음이 분명함.', 32, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '와플은 맛은 있는데 가성비가 떨어져용 하지만 ..귀엽고.. 여기 올때마다 꼬옥 먹음..ㅎ 한정메뉴는 첨인데 별로였슴..😢,,,, 아쉽.. 띠부씰 언제 다 모으죠..🥺', 24, 8, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '가격대비 와플 너무 맛이 없어요. 비싼건 뭐 어쩔수 없다지만.. 너무 맛이없음.. 와플인지.. 물먹인 빵인지..한번쯤 호기심으로 가기만.. 다신 안갈듯', 13, 4, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '아이가 가고싶어해서 방문은 했지만 재방문 생각은 없어요. 1인 1메뉴라는 원칙을 이해하지만 그것은 1인이 먹을 수 있는 양일 경우라고 생각합니다. 아이가 다 먹지도 못하는 와플의 양을 잡아놓고 18,000원 하는 와플을 시켜야 한다니 말이에요. 와플 양을 반으로 줄이고 가격을 낮추거나 와플메뉴는 2메뉴로 인정해주면 좋을 것 같습니다.', 14, 0, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '음료도 다 맛있고요 ㅋ와플이이뻤는데 쫌 생각보단 딱딱했어요 ㅋㅋ 그래도 이뻐서 만족 했구요 오픈 6월달부터 티켓팅 했는데 ㅠㅠㅠㅠ 티켓팅이 안되가지구여 흑흑 엄청 3개월을 계속 티켓팅 노오오오력 하구 기다리다가 어제 월요일날꺼가 되가지고 넘 3개월간 어렵게 왔네요 ㅋㅋ 티켓팅이아니라 피켓팅이더라고요 나의 노력이 빛을 발하는 날이었어요 넘 이뻐요 피나는 티켓팅을 알람을 꼭 꼭 맞쳐놓고 기다리다가 ㅋ 이번에 딱 운좋게 되가지구요 친구랑 인생샷찍고 넘 좋네요 ^^', 20, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '귀엽고 예뻐요 딸들이랑 갔는데 포토존도 많고 사진이 잘 나오네요. 기념품 파는곳은 종류는 많지는 않은데 몇가지 샀더니 8만원이 넘네요.ㅎㅎ 좋은 추억 만들었습니다.', 88, 11, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '여긴 예약하고 갈 정도의 감동도, 추억도, 가성비도 없는 곳입니다. 예약해서 갔더니 착석 가능시간은 단 1시간 밖에 안되고 포토존이라고 해봤자 10평 남짓된 공간 한곳 뿐인데다, 음료랑 와플하나 시키면 금액이 25000원이 훌쩍 넘어가더군요 딱히 놀 공간도 없고 비싼돈주고 예약해가면서 여길 왜 갔는지 후회될 뿐입니다 다시는 갈 일이 없을겁니다', 2, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '네이버 예약만 받는게 아니고 현장대기도 받는데 이상한게 중간중간 들어가는 현장대기자들이 좋은 자리 차지하고 있음 네이버 예약자들은 별로인 자리 앉아야되는데 네이버 예약만 받아서 한시간반되면 전타임사람들  다 퇴장한후 예약자들이 들어가는게 맞다고 본다 아이가 좋아해서 어쩔수없이 갔는데 다시는 가고 싶지 않다', 2, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '캐릭터카페는 맛 보다는 캐릭터 그 자체로 목적을 띄고 가는것! 시나모롤을 좋아하는 아이를 위해 가는 것으로 아이는 대 만족했어요. 오픈런으로 현장 대기로 방문했어요. Ak몰이 11시 오픈이라, 10시 반쯤에 도착하니 몰 오른쪽 게이트로 대기줄이 있습니다. 약20분 정도 기다리니 50분쯤에 카페직원이 와서 대기접수 해주셨어요. 이후엔 약 50분 정도 기다려서 입장.12시쯤 예약하면100분정도 대기. 카톡으로 오니 카페이용 전에 굿즈샵을 미리 들리는걸 추천할게요. 어차피 살거, 미리 기분좋게 사면 됩니다. 굿즈마다 가격이 타 매장과 차이나지만,ㅋㅋㅇ만큼 비싸진 않아요. 아이가 그동안 모은 용돈3만원으로 키링, 작은 인형,머그컵,스티커 등등 샀어요. 와플은 배불러서 남겼어요. 다소 느끼해서 점심은 콩나물국밥!', 37, 5, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '포토존, 포토카드, 코스터, 띠부띠부씰 다 너~무 귀여웠어요💕 제가 간 날은 사람이 적어서 조용히 잘 즐기다 왔습니다 당연하겠지만 음식맛은 그냥 그래요! 맛 기대하고 가지 마세요', 22, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '매장청결하고 너무예뻣어요 그리고 메뉴는 가격사악하지만 음료.커피.와플 다아깝지않았어요 맛있었음 직원들은 음 힘드신건지 전체적으로 밝은에너지는없었어요 그치만 딱히 불친절도아니었으니 괜찮았으나 살짝조금만 밝으면좋겠어요 ^^', 26, 8, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '아이 때문에 예약해서 갔는데 기대보다 별로였어요. 전체적으로 너무 작아서 사진 찍기도 별로고 메뉴는 유아여도 1개 주문이 필수여서 좀 그래요. 사진찍는곳은 조명을 다시 조정해얄 것 같아요.', 86, 16, 'BAD', SYSTIMESTAMP);
