INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00059@test.com'), '너무 귀여워요!! 포토존이 많지는 않지만 너무 귀여워서ㅋㅋㅋ 한시간 반 짧으면 어쩌나했는데 음료랑 마시고 좀 수다하다가 포토존 사진 찍고 포카뽑고 나오면 알맞은거같기는 해요ㅎㅎㅎ', 45, 9, 'GOOD', SYSTIMESTAMP);
