INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '예약이 힘들었지만, 좋아하는 캐릭터 예쁘게 잘 구경하고왔어요. 커피,와플 맛있고~ 컵받침, 금액별 띠부씰을 주셔서 좋았습니다. 캐릭터 상품이 많지를 않아서 아쉬워요. 인형,키링 왔네요.', 21, 0, 'GOOD', SYSTIMESTAMP);
