INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '네이버예약하고 아이들이 정말 기대하고 전철타고 한시간 반걸려 갔어요~ 가기전 후기 보고 크지는 않다는 소리 들었는데 아기자기 좋아하게 잘 꾸며져 있더라고요 음식은 좀 금액이 나가서 아쉽지만 사진용으로는 잘나오네요 ㅎ 포토존 에서도 사진 이쁘게 잘찍어서 좋았네요 아이들이 신나해서 좋았어요', 22, 9, NULL, SYSTIMESTAMP);
