INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '아이가 가고파해서 갔는데 아기자기한게 귀엽네요! 붐비지도 않고 편하게 즐기다 왔어요! 굿즈샵이 좀 작아 아쉬웠지만 사진찍기좋고 ak몰 안에 같이 구경하기 좋아서 추천합니다!', 25, 6, 'GOOD', SYSTIMESTAMP);
