INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '입구부터 시나모롤이 반겨주니아이가 너무좋아해요 사진찍기 너무 좋았고 음료가 조금 비싼감이 있지만 띠뿌실을 금액별로 주시니 쏘쏘네요', 162, 94, NULL, SYSTIMESTAMP);
