INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '예약제로 해서 그런지  사람이 많지 않아 좋았어요 딸아이가 무척 좋아했어요 시나모롤 띠부실 , 컵받침대를 랜덤으로 줘서 갖고싶은 것을 못가져서 속상했어요', 38, 0, NULL, SYSTIMESTAMP);
