INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '포토존은 정말 너무 이쁜데 저녁 늦은 시간 예약하면 소다 음료 못먹는 아이들은 캐릭터있는 음료 먹을거 없고요, 심지어 와플도 없었고, 테이블도 위생상태가 좋지 않습니다. 그냥 카페 들어가고 밖에서 사진 찍고 가게 구경하는게 훨씬 좋아요 힘들게 예약해서 의미없는 카페 음료/음식 먹는거 가성비 너무 떨어진요 실망스러워요', 61, 15, 'BAD', SYSTIMESTAMP);
