INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '힘들게 예약하고 평일이라 아이 체험학습 내고 다녀왔어요 역시나 시나모롤 엄청 시리 좋아하는 딸 너무 행복하대요..와플 음료에 사진까지 찍으니 환장하죠 딸이 행복하다는데 애미는 힘들어도 예약 하길 잘했다 생각했어요', 16, 6, 'GOOD', SYSTIMESTAMP);
