INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '아이가 너무 좋아했어요. 굿즈도 다 사주고 싶게 너무 예뻣고 음료도 와플도 안사줄 수 없는 비쥬얼이었어요 다만 포토존 조명이 아쉬웠어요 얼굴이 어두컴컴하게 나오더라구요😭😭', 27, 2, NULL, SYSTIMESTAMP);
