INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '분위기 하구 포토존 도 너무 예쁘고 음료 도 넘 맛있었어요!! 💕💕 ㅠㅜㅜ 직원 분들도 친절 하셨어요!! 여러분들도 한번 가보세요~~!! 다음에 오면 와플 먹고 싶네요!! ㅠㅜ', 45, 0, 'GOOD', SYSTIMESTAMP);
