INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '시나모롤 정말정말 좋아하는데 정말쾌적하고 좋았습니다! 네이버예약시스템 시간을 정시에 풀지않아서 오래기다릴까봐..꽤기다려서 예약한것만 빼면 좋았어요! 평일에는 그래도 예약하시면 대기시간은 많지 않은것같아요. 주말은 어떨지모르겠지만 평일에 나름 즐겁게 다녀왔네요! 음료는 그럭저럭이지만 보는재미가있고 와플은 맛있는데 받고 바로드셔야 딱딱해지지않아요!  꽤 가볼만한곳이라고 생각합니다! 시나모롤좋아하시면 꼭 가세요~!', 63, 18, NULL, SYSTIMESTAMP);
