INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '1인 1메뉴 사실 너무 아까워요. 보통 보면 초등 저학년인데 아이들이 다 못 먹어요. 가격도 비싸고 커피값도 비싼데 라떼가 너무 맛이 없어요 ㅠ 한번 갔으니 만족하지만 두번은 안갈 것 같아요.', 18, 5, 'BAD', SYSTIMESTAMP);
