INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '아이가 워낙 캐릭터 좋아해서 다녀왔는데 제 기준에 사진찍을곳이 엄청 많은곳도 아니고 음료도 비싸고 ㅎㅎ 그랬네요.. 한번은 가봤지만 또 예약해서 가보진않을것 같아요 파스텔톤으로 예쁘긴하더라구요', 58, 16, NULL, SYSTIMESTAMP);
