INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '아이들이 좋아해서 오긴 했는데 진짜 비싸네요 저게 18,000원이라니 직원응대도 별로고 알려주면 다 할텐데 왜 핸드폰을 그리 만지는지 너무 불쾌하네요 거기에 신분증까지 보여 달라는데 어이가 없더라구여 애들끼리 오면 못오겠네요 신분증도 핸드폰도 없어서', 115, 25, 'BAD', SYSTIMESTAMP);
