INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '기프트샵이 너무 작아서 너무 실망스러웠어요 안에 카페는 너무 이쁘고 아이들이 좋아하는데요 나오는 음료는 넘쳐서 쏟아지고 스푼하나 더 달라고 했더니 안된다고 하시네요 야박합니다 사진은  포토존 아니면 칙칙하게 나오지만 너무 귀여워요', 87, 17, 'BAD', SYSTIMESTAMP);
