INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '유명한 카페라 예약을 열심히 해봤어요 ㅎㅎ 주말은 1분 컷이라고 하던데 다행히 예약에 성공해서 아이들과 재미있게 다녀왔어요. 화장실은 몰에 있는 화장실을 써야해서 줄이 너무 길어 이용 안했구요. 비싸긴 했지만 커피랑 와플, 포도에이드 맛있었어요.', 41, 1, NULL, SYSTIMESTAMP);
