INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '아이가 시나모롤를 너무 좋아해 다녀왔는데  조금 작다고 생각했어요 와플이랑 음료  괜찮더라구요 여기 저기  다른 상점에서 상품 볼수있어서 좋아요 아이가 또 가고싶다고 노래를하네요~', 129, 26, 'GOOD', SYSTIMESTAMP);
