INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '위치도 홍대입구역 4번출구에서 나오면 바로여서 너무 좋았고 음식들 맛부터 모양까지 너무 최고였어오!! 한번 더 방문해보고 싶은 카페입니다💙', 31, 1, 'GOOD', SYSTIMESTAMP);
