INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '아이들을 위한 카페인데 이제 겨울인데 따뜻한 음료가 커피밖에 없는게 너무 아쉬웠어요.. 생각보다 볼게 없어 너무 실망했지만.. 띠부띠실 티코스터 증정으로 받고 아이들은 너무 좋아했어요', 90, 12, NULL, SYSTIMESTAMP);
