INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '멀리서 찾아왔는데 규모가 작고 메뉴도 적어서 아쉬웠어요. 그래도 현장서 찍은 사진을 시나모롤포토카드로 출력해서 보관할 수 있는건 매우 좋았어요.', 44, 5, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '와플 쫄깃하고 맛있어요 카페가 생각보다 작았지만 아기자기하게 잘 꾸며져 있고 너무 귀여워요 아이가 시간 다 채우고 있다가 나온 카페는 여기가 처음이예요', 69, 11, 'GOOD', SYSTIMESTAMP);
