INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '생각보다 포토존이 작긴 했지만 그래도 아이가 좋아했어요 와플이 엄청 쫄깃하고 맛있어요 결제하면 띠부씰이랑 코스터 주는것도 좋네요', 1, 10, 'GOOD', SYSTIMESTAMP);
