INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '가운데 테이블은 비는데, 일부러 안 채우는건지, 모르겠네요,,현장 예약한 일행도있었는데, 대기가 너무 오래걸렸네요,,,,,,,,,,, 빈자리 ㅠ ㅜ', 33, 9, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '시나모롤 엄청 좋아하고 예약 성공해서 가고싶은곳이었는데 카페라떼에 시나모롤 얼굴 모양의 화이트 초콜릿 장식이 귀여워서 맛있었어요!! 담에 또 가게 된다면 와플도 먹고싶어요💕💕💕', 86, 16, 'GOOD', SYSTIMESTAMP);
