INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '아이가 가고싶어해서  예약해서 간곳. 처음가본곳이고  문이 열려잇어서 들어간것 뿐인데 어케 들어왓냐며.. 아직 오픈전이라 들어오심 안됀다고..열려잇어 들어왓고 몰랏을뿐인데 들어도 가기전에 기분 상햇네요.. 친절까진 아니더라도.. 말투는 좀.. 그거 외엔 주문받으신분은 친절하셧고 아이도 좋아하고 해서 괜찮앗습니다~', 40, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '아이들이 정말 좋아했어요^^ 근처 구경도하고 운좋게 예약해서 갔는데 시간맞춰가면 기다리지않고 바로 들어갈 수 있어서 좋고  안에도 사람 몰리지않도 좋았어요', 11, 4, 'GOOD', SYSTIMESTAMP);
