INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '너무 예쁜 카페입니다~~ 덕분에 아이들과 좋은 추억 만들고 왔습니다 큰 기대없이 갔던 아이들이 너무 즐겁고 행복했다고 해요~~ 직원분들도 너무 친절하고 좋았습니다 또 방문할께요^^', 26, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '5살 딸도 좋아하는 시나모롤. 산리오카페랑 2시간 텀두고 예약했는데 둘다 성공했어요~ 산리오보다 시나모롤카페가 더 아기자기하고 예쁘고 만족스러웠습니다~', 15, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00098@test.com'), '기대 이상은 아니였지만 아이들이 좋아하네요! 잠시 아이들의 힐링 장소. 어렵게 예약했는데.. 막상 가보니 현장 예매가 더 많았네요. 제가 간 날이 그랬나봐요!', 159, 78, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '와플 맛있었어욥!! 제가 갔을때는 테이블이 많이 남았었네욤. 사진진짜 잘 나오구 홍대입구역5범출구에서 멀지 않아서 가기도 편했어요', 10, 5, 'GOOD', SYSTIMESTAMP);
