INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '귀여운거 좋아하는 6쨜 아이들이랑 즐거운 데이트 했어요~ 가격은 좀 사악하긴 하지만 넘나 귀여워요! 와플도 한개씩 들고 순삭 하더라구요 당 떨어져서 모카 시켰는데 프린팅 보고 또 귀여워서 깜놀!ㅋ 에이드도 귀엽게 나오는거 같아요 카페 이용자만 들어갈수 있는 포토존에서 사진도 많이 찍고 포토카드도 뽑았어요 6쨜 둥이들과 데이트 성공적! 작지만 알차요 손님은 20대 여자분들 많았던거 같아요 아이가 또 가고싶다고 했는데 이젠 예약제로 바뀌었네요ㅠㅜ', 186, 69, 'GOOD', SYSTIMESTAMP);
