INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '아이가 시나모롤을 좋아해서 검색하다가 알게 됐어요. 많이 넓거나 사진 찍는곳이 많거나 하는건 아니지만 사진도 잘나오고 아이도 좋아하고 저도 만족했어요~ 순환이 잘되고 테이블도 바로 소독하는 모습을 보고 청결하구나 란걸 느꼈어요. 아이와 좋은 데이트 했어요. 감사합니다 😄', 122, 24, 'GOOD', SYSTIMESTAMP);
