INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '와플은 가격대비 진짜.. 예약을하고 갔지만, 직원들 또한 정신없어서 대처가 좀 아쉽네요. 그럼에도 불구하고 사진은 잘 나오고 아이들이 참 좋아했어요', 52, 17, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00053@test.com'), '조카가 시나모롤을 너무 좋아해서 미리 예약하고 방문했어요. 곳곳에 예쁘게 꾸며져 사진도 찍고 시나모롤이 있는 음료와 와플도 먹고 왔어요. 좀 비싸지만 언제 또 와볼까싶어 주문해서 먹었는데 맛도 괜찮고 분위기도 좋았어요.', 49, 8, 'GOOD', SYSTIMESTAMP);
