INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '카페가 너무너무 귀여워요ㅠㅠ 근데 카페 열린지 초반에 안갔더니 기본으로 주는 상품?들은 다 품절이라 못받았어요..ㅠㅠ 그리고 굿즈샵도 키링이 젤 인기 많은것 같은데 다 품절이고 나머지는 인터넷에 쉽게 구할 수 있는 제품들이라 아쉬웠어요ㅜㅜ 그래도 캐릭터가 귀여워서 재밌게 잘 놀다 왔습니다~', 33, 0, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '시나모롤 카페 너무너무너무 가보고싶어서 지인이랑 같이 갔어요🥺🥺 예약도 정말 운이 좋았던건지 5시에 예약이 잡혀져서 그래. 예약 못잡은것보단 낫지 하며 잘 다녀갔네요ㅠㅠ 그리고 님들 꼭 가면 샤인머스캣 소다 사세요.. 바닐라 아이스크림 녹으면서 같이 섞으면 맛있어요....지인은 스윗피치소다를 시켰는데 많이 달다구리하다 해서 단거 싫어하시면 샤인머스캣이 더 나을것 같네용👍🏻👍🏻 와플도 바삭 촉촉해서 맛있었어요.. ㅠㅠ너무 행복한 시간이엿어요. 이용시간이 1시간 30분으로 제한이 되는데 그래도 넉넉히 수다 떨고 놀기에 적절한 시간이였네요~♡♡', 55, 13, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'TALK');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '이용시간 한시간에 비해 음료가격은 비싼편인거 같고요 사진찍는곳도 생각보다 많진 않고요 아이가 가고 싶어 갔지만한번으로 만족하렵니다', 78, 12, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00054@test.com'), '만족스러웠습니다 평일엔빈자리가 많더라구요 예약을하고갓는데 예약시간전 도착해서 들어가고싶었지만 빈자리도많았는데 꼭 예약시간에만 들어갈수있다고하셔서 조금아쉬웠습니다 현장대기할껄그랬나봐요 그점만빼고는 다좋았습니다:)', 174, 51, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '시나모롤이 깜찍하고, 사진 찍는 곳이 많아서 아이가 좋아했어요~ 아빠들도 많이 와 있드라구요ㅋㅋㅋ 좋아하는 아이를 위해 묵묵히 사진 찍어주고, 노력하는 아빠들의 모습이 넘 웃기고 보기 좋았어요. 어머님들~여기 정말 강추드립니다~~!!!', 78, 15, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '11시 예약하고 방문해서 그런지 사람도 별로 없고 괜찮았어요! 가격은 일반 카페보다 1000-2000원 정도 더 비싼 느낌? 맛있어서 한번쯤은 와볼만 한 곳 같습니다 ㅋㅋ 특히 와플이랑 스윗피치소다가 너무 맛있었어요.. 그치만 조명이 천장 여기저기에 작게 배치되어 있어서 사진 찍기에는 좋진 않았던 것 같아요 😔', 128, 24, 'BAD', SYSTIMESTAMP);
