INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '아이는 좋아했어요~ 음료 와플 너무 귀여웠는데 와플 가운데 부분빼고는 너무 딱딱해서 자를때도 불편했고, 모서리 부분 먹는데 입안이 아프더라구요ㅠ 생각보다 살만한 것도 없었고, 포토존은 조명이 별로인지 찍을때마다 얼굴에 그늘같은게 져서 배경은 이쁜데 얼굴은 화사하게 안나오더라구요.. 그래도 한번쯤은 가볼만 해요', 18, 1, 'GOOD', SYSTIMESTAMP);
