INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '아이가 넘 가고싶어해서 네이버오픈시간 대기해서 예약하고갔는데,,, 생각보다 매장도 작고 메뉴도 별로였어요ㅠ 무엇보다 예약시간 2분전이라 매장안에 사람들도없고해서 입장하면안되냐했더니 앞에 계신 직원분이 안된다고,,, 매장  브레이크타임도 아니고 오후타임에 매장이 비여있었는데 왜 안된다고하는지 이해가 안가네요^^:;  밖에서 아이가 계속서성이다 2분뒤에 들어갔는데 청소가 되있는것도 아니고,,, 스토어샵에서 계산하는데 직원분이 어디가셨는지 보이지도않고,,, 기대를 너무많이한듯하네요ㅡ아이는 포토존이 이쁘다고 하니 그걸로만족합니다', 64, 14, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '시나모롤 좋아하는 사람에겐 완전 천국이였습니다! 사진도 너무 이쁘게 잘나오고 포토존 꾸며진게 귀여웠어요! 음료는 스윗피치소다 먹었는데 상큼하고 달달하고 진짜 맛있었습니다.', 26, 3, 'GOOD', SYSTIMESTAMP);
