INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '딱 한번만 가면 될거같아요 카페 직원분 아무리 힘들다고 하셔도 너무 불친절하신거같아요 방문한 시간대에 손님이 많은것도 아니였는데 좀 많이 불친절하시더라구요? 또 와플 반죽도 가운데 캐릭터 부분은 설익었어요 그냥 남기고 나왔네요', 5, 8, 'BAD', SYSTIMESTAMP);
