INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00045@test.com'), '귀여워요❣️ 사진찍으러 가는 것만으로도 가치가 있는 곳!! 카페 이용 하는 사람만 들어갈 수 있는 포토존이 있습니다!! 예약 안 하고 가서 못 가는 줄 알았는데 가먄 테이블링 처럼 줄서는 앱이 준비 되어있어서 들어갈 수 있었습니다!! 와플은 약간 질깃? 쫄깃? 떡 같은 식감이었는데 같이 데코 되어있는 자두가 맛있더라구요! 음료는 평범합니당', 11, 3, 'GOOD', SYSTIMESTAMP);
