INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '와플은 첨 먹어보는데 와플맛집이네요 바삭하니 너무 맛있었어요!! 그리고 코스터랑 띠부실도 받아서 너무너무 좋았어요!!!><진짜 시나모롤 조아하는 저한텐 여기가 천국같아요..', 15, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '아이가 시나모롤 캐릭터에 빠져서 어렵게 네이버 예약하고 전날 홀리데이인익스프레스에 1박하고 11시 예약시간 맞춰 체크아웃했어요. 생각했던 것만큼 너무 좋아하네요~ 디저트도 맛있고 이정도면 저는 만족이에요~ 사진도 많이 찍고 좋은 추억 남겼네요. 네이버 예약하고 오면 예약자 신분증 확인 하네요. 예약양도 안 받으시는게 좋을 것 같아요', 6, 2, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'PURPOSE', 'PHOTO');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '카페가 깨끗하니 좋더라구용^^ 직원분 들도 완전 친절해서 좋았어요. 다만 음료가 조금 아쉬워요 ㅋㅋㅋ 피치소다와 청포도. 하앍ㅋㅋ 와플은 가격이 나가도 귀엽고 맛나용!! 시나모롤 샵에서 귀여운 것들 잔뜩 살 준비 했는데 열쇠고리 등등 아기자기한 제품들이 넘 부족해 보여요ㅠㅠㅠㅠ 그게 아쉬웠지만 아이들이 좋아해서 한번쯤 가보는건 추천합니다^^', 28, 2, NULL, SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '매장 불청결하고 코스터도 랜덤이라며 중복되는걸로 주고 바꿔달래도 안바꿔주시네요 음료랑 와플 맛도 그냥 그랬어요 직원분들도 불친절하고 재방문할일은 없을듯합니다', 306, 59, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '사진 찍기 너무 좋고 진짜 너무 귀여워서 친구랑 1시간 30분동안 너무 재밌었어요 다만 위생은 진짜 노답입니다 바닥에 시나모롤 귀(화이트초콜릿)랑  이것저것 흘린 흔적 있었는데 하나도 안 닦아져있어서 그 부분은 정말 별로였어요 그리고 가격 역시 창렬이지만 인테리어 값이라 치고... 와플 맛있다해서 엄청 기대했는데 그냥저냥 먹을만 했습니다~~ 그치만 예약해서 한 번 쯤 올만한 곳 인정!!! 사진 정말 잘 나옵니다,,,💗', 93, 21, NULL, SYSTIMESTAMP);
