INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '그동안 여러 번 갔었는데 9월~10월에 비해 많은 게 달라져서 당황스러웠어요 일단 이용시간이 1시간으로 줄었구요 이 날 자리도 많이 비어있었는데 입장시간은 분 단위로 칼같이 지키시고 이름과 전화번호까지 물어보시면서 막상 테이블에 남아있는 쓰레기들은 치워주지도 않으셔서 직접 청소하고 앉았네요 애들이 신발 신고 올라가서 그런지 소파에는 시커먼 얼룩들이 있었고 시즌 음료는 너무 묽은 맛이었습니다', 41, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '너무 귀엽고 맛있는데 디저트랑 음료 종류가 좀 더 다양했으면 좋겠어요ㅠㅠㅠ(디저트랑 음료가 전체적으로 다 달아서 티 같은게 있으면 훨씬 더 좋을 것 같아용)', 43, 4, NULL, SYSTIMESTAMP);
