INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '딸 생일 기념으로 예약해서 가긴 했는데 두번은 안갈 것 같아요. 음료도 너무 비싸고 꼭 1인 1메뉴... 결국 애들 파르페는 먹지도 않고 다 버렸습니다. 와플은 맛있었어요', 32, 2, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00032@test.com'), '음식 맛있고 사진 잘나오고 시나모롤 물건을 샀는데 물건이 좀비싸긴 한데 이쁘구 시나모롤 스티커..? 암튼그거랑 시나모롤 받침대..? 그거도 주셔서 행복했다. 시나모롤을 좋아하는 사람들이 가면 진짜 좋아할만한 곳이다.  최고였당♡', 30, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '평소에 카페와 다른 분위기라 직원분들도 귀엽게보이고 모든것이 다 귀여워져서 마음이 몽글몽글해져요 바쁘실텐데 엄청 친절하셔서 감동받았어요.. 🥺 실은 사진찍을용도로 와플과 파르페를 시켰는데요 파르페는 마시면 마실수록 진가를 발휘해서 딸바주스가 됩니다 정말 맛있어요 와플은 촘촘한 과일들이 상큼하고 달달한 바나나와 와플과 조화로워서 맛있게 먹었어요 기대안했는데 지금 이 글을 보셨다면 조금은 기대를 해봐도 좋습니다.. 다만 단것을 먹으니 커피를 마신다는 납득이가지만 커피를 맛으로 마실 생각이라면 오늘은 다른 음료를 택하는게... 무엇보다 도망치려는 시나모롤이 최고로 귀엽습니다 🧸✨', 38, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '예약놓쳐서 현장대기했는데 3시간정도 걸렸어요 모바일로 실시간 대기인원 확인가능하니까 다른거하다오면돼요! 포토존이 대부분 역광인게 아쉽긴했는데 일단 귀여워서 만족이고 늦은 시간에 입장하게 되니까 캐릭터얼굴 들어간 메뉴들은 거의 다 소진이더라구요 평소에 와플 별로 안 좋아하는데 와플이 진짜 쫀득하고 맛있었어요', 44, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '어린 가족들이 많아 조금 어수선했어요 네이버에 등록해야 좋은 자리를 차지할수 있고 현장방문은 비추천 합니다 두시간 걸린다고 해서 그정도 가늠했지만 실상은 4-5시간 기다려야 합니다 그리고 음식 가격은 좀 비싼편이고 포토존이 아쉬웠어요 가격만큼 만족스럽지 못했습니다', 90, 14, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '티켓팅을 너무 늦은 시간에 해서 2시쯤 갔더니 웨이팅 50분 정도여서 근처에서 밥먹고 오니 딱이었습니당 음료랑 와플 다 맛있었어용', 24, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '산리오카페를 먼저 다녀온 후 아이들이 시나모롤두 가고 싶다고 해서 다녀왔는데 개인적으로는 산리오카페가 더 나은것 같아요.. 빈 테이블이 있어 앉으려고 하니 사장님이 오시기로 했다면서 다른자리 앉으라 하고 저희 나갈때까지 아무도 오지 않았음..  손님을 위한게 아니라 사장을 위한 카페인가 의구심이 들었네요.. 사진 찍을곳도 몇개 없고 좀 실망스러웠네요.. 두번은 안갈 것 같아요..', 14, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '네이버 예약하기가 너무 어려워서 현장 웨이팅하고 들어갔어요 오픈런하니 오래 기다리지 않고 들어갈수 있었어요 아기자기해서 아이가 너무 좋아하더라구요^^', 85, 17, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '개인적으로 너무 좋았어요! 와플도 먹고싶었는데 깜박하고 안한게 한이 될줄은 ㅠㅠ.. 정말 좋아요! 굿즈샵도 포토존도 예뻤습니다!', 48, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '네이버 예약하고가면 예약자석이라고 되있는곳만 앉을수있는데 그게 딱 정해진게 아니라 그때그때 비는자리에 두시는거라 자리복불복 심하네요. 한번 앉으면 다른 빈자리가 있어도 옮길수 없고, 네명이 1인1음료에 와플까지 시키니 원형테이블이 좁아서 매우 불편했어요. 네이버로 힘들게 예약한 예약자의 좋은점이라곤 1도 없었습니다. 아이스크림라떼는 달달한거 좋아하면 먹을만했으나 아이들이 먹으려고 시킨 레몬에이드, 샤인머스켓 소다는 너무맛이없어서 다남겼어요. 굿즈샵은 생각보다 너무 작았고 아이들이 사고싶었던 키링은 재고소진이라 아예 없었어요. 주말에 간거라 사람은 많았는데 물건은 없고. 더 들여놓지 않으신건지 뭔지... 아쉬운점이 많았네요.', 32, 7, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'ADE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '너무너무 궁금해서 갔다 왔습니다. 너무 귀엽고.. 만족스럽고... 사랑스럽습니당 큰 기대가 없었는데 와플이 생각보다 맛있어서 놀랐습니다! 함께 주는 생크림과 아이스크림도 무척이나 맛이 좋았어요', 11, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'DESSERT');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '디저트와 음료들이 시나모롤로 꾸며져 있어서 너무 예뻤고 포토존에 들어가는 순간 너무 행복했어요🫶🏻 다음에도 또 가고싶다는~~👍🏻👍🏻', 18, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '음료가 비싼데 맛은 별로예요. 티슈는 조금씩 주고 쟁반에 까는 예쁜 종이 한 장 더 달랬더니  줄수 없다고 해서 기분 별로예요. 어른2,어린이3 가서 5잔 마셨고 아이가 3명이라 3장 받으려고 했는데 ... 따져서  받긴 했지만 사장님 지시라는데 사장님 너무 짠돌이같아요. 음료값 비싸게 받으면서...', 27, 3, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '인테리어가 너무 귀여워요!! 예약하고 오신분도 많은데 평일에가서 그런가 웨이팅 많지않았어요!! 와플이랑 커피는 먹을만해요!ㅎㅎ', 27, 1, 'GOOD', SYSTIMESTAMP);
