INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '11시 첫타임으로 가시면 굳이 미리 가 있을 필요가 없어요 몰 자체 오픈이 11시여서 10분 전에 도착해도 들어갈 수가 없어요', 25, 6, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '아이가 특히좋아하는 캐릭터라 엄청 좋아했어요 사진찍을만한 곳들도 아기자기 잘 꾸며놓고 굿즈도 여럿 샀어요 음식은 달고 좀느끼했지만 귀엽고 예뻐서 아이가 환호했구요 다만 음료위 아이스크림이 흘러 떨어질거같은데다 아이가 섞어먹어싶어하지않아 작은 그릇이나 뭐라도있나 여쭤봤는데 아무런 도움 안주시더라구요 야박하단 리뷰들 가끔 봤지만 저도 좀느꼈어요 시나모롤 좋아하는 친구들에겐 천국이에요 네이버예약이 예쁜자리 선점에 도움이되니까 추천해요', 19, 9, 'BAD', SYSTIMESTAMP);
