INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '샤인머스캣보다 피치~가 맛있어요. 와플은 가격보고 포기했어요. 월요일 저녁에 가니 자리가 널널해요. 시나모롤 보러 가는 곳입니다. 인테리어는 매우 만족합니다.', 44, 3, 'GOOD', SYSTIMESTAMP);
