INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '커피가 맛없다는 말이 있어서 아이스크림이 얹어진 -피치와 샤인머스켓 에이드를 시켰는데 무난했다 와플은 적당히 먹을 만 했다 값이 조금 비싸긴 하지만 캐릭터 카페라는 특수성이 있으니까...다만 즐길 장소가 다채롭지 않았다 사진만 몇장 찍으면 끝나는 수준 시나모롤 키링 만들기 체험이라던가...시나모롤 미끄럼틀이라던가 아쉬웠다. 이건 캐릭터카페 두번밖아 안가본 사람이라 너무 많이 기대한 건가...싶기도 하고 커피 비싼 거 뭐라 안할테니 기왕이면 맛난 걸로 주세용', 15, 10, NULL, SYSTIMESTAMP);
