INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '제가산리오 중에서 시나모롤을 제일 좋아했는데 이렇게 시나모롤만있는  곳은 있을줄 몰랐는데 여기 있었네요 이렇게 시나모롤 카페를 만들어 주셔서 감사합니다', 2, 4, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '진짜 귀여워요 아이때문에 가긴 했는데 커피 한잔도 잘 마시고 (가격이 좀 ㅋㅋ) 사진 잘 찍고 왔어요 다음에 아이가 또 가자는데.. ㅋㅋ 암튼 한번 가볼곳으로는 강추해요!', 32, 4, 'GOOD', SYSTIMESTAMP);
