INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00067@test.com'), '네이버예약으로 대기없이 바로 입장하니 편했어요. 조용하고 북적이지 않아 대화하기 편했고 이용시간이 여유있어요. 주문한 메뉴는 금방 나오고 티코스터와 띠부씰 선물도 마음에 들어요.', 35, 9, 'GOOD', SYSTIMESTAMP);
