INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00066@test.com'), '조카들이 시나모롤 좋아해서 별도 예약 없이 갔는데 웨이팅 있지만 30분 안에 들어갔어요 ◡̈ 가격대가 있는 편이지만 포토존이 따로 있는거 생각하면 괜찮은거같아요! 사진도 잔뜩 찍고 왔어요 ㅎㅎ', 32, 4, 'GOOD', SYSTIMESTAMP);
