INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '6세딸이 시나모롤 너무 좋아해서 갔는데 대만족이에요. 단, 포토존 조명이 얼굴 아래로 비추게 해놔서 얼굴에 그림자 생겨요. 조명 위치  맞춰주세요^^', 39, 5, NULL, SYSTIMESTAMP);
