INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '시나모롤 스위트카페'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '다 좋은데 인간적으로 4살,6살아이랑 갔는데 18000짜리 와플이랑 9500짜리 음료시키려 했더니 무조건 인당 1개는 시키라고 하시던데... 그 조건까지는 알겠으나 18000짜리를 1인으로 한다는게 좀 이해되지않네요. 1만원짜리  하프와플이든 크로플이든 만드시면 좋을것 같습니다. 와플외에 베이커리류는 1도없으면서 와플을 시켜도, 미취학  아이도 1메뉴라서 거의 남기고왔네요.', 111, 23, 'BAD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'BAKERY');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비하인드'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '단걸 잘 안 좋아해서 기대도 안한 프렌치토스트 웬걸 너무 맛있어서 흡입해버렸어요 에그타르트 속처럼 너무 부드럽고 맛있는데 메이플 시럽 향까지..❤️ 너무너무 맛있었어요ㅠㅠ 가격이 비싸지만 돈이 아깝지 않은 맛이에요', 70, 12, 'GOOD', SYSTIMESTAMP);
