INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비하인드'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '내사랑 프렌치토스트 맛집이였는데 뭔가 맛도 모양도 많이 변하긴햇음 ㅜ 그래도 맛있지만 !!! 그래서 공간이 추억이 주는 애정하는곳 :)', 3, 8, NULL, SYSTIMESTAMP);
