INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비하인드'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '* 매실차 6,500원 * 아메 5,500원(+디카페인 500원 추가) * 바닐라 아이스크림 토스트 8,500원 토스트 맛집. 바닐라 아이스크림 토스트 정말 맛있다~ 분위기 좋고 실내 조도는 밝지 않음. 작업하는 사람도 보였다. 토스트 먹으러 다시 오고 싶은 곳.', 80, 13, 'GOOD', SYSTIMESTAMP);
