INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비하인드'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '산미 없는 커피를 좋아해서 맛있었습니다. 프렌치토스트도 크기에 비해 비싸다는 생각이 들었지만 맛있었습니다! 메뉴로 불러주시면 픽업하러 가야되는데 메뉴가 동일한 분들이 계서서 헷갈릴 수 있을 것 같아요ㅠㅠ 진동벨 도입이나 가져다주시거나 닉네임을 받아서 불러주시면 좋을 것 같습니다!', 53, 17, NULL, SYSTIMESTAMP);
