INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비하인드'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '오 그냥 길 걷다가 들어간 카페였는데 아늑한 분위기도 좋고 음악도 좋았어요. 프렌치토스트는 크기에 비해 가격은 좀 있지만 넘 맛있었어요! 커피도 좋았습니다.', 44, 4, 'GOOD', SYSTIMESTAMP);
