INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비하인드'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '아늑하고 따듯함을 주는 합정 카페 라벤더 홍차를 마셨는데 향이 정말 좋았음🩵 은은한 조명과 사장님만의 취향이 더해진 카페로 시간 보내기 좋은 공간이었음', 40, 2, 'GOOD', SYSTIMESTAMP);
