INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비하인드'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '프토 맛집,,,,ෆ 겉은 빠쟉하니 속은 촉촉 퐁실해서 커피랑 찰떡궁합이었어요! 프토 먹으러 재방문,,,ㅎㅎ 아이스크림 추가해서도 먹어봤는데 저는 그냥 프토가 본연의 따뜻하고 달콤한 느낌을 잘 전달하는 거 같아서 플레인에 한 표 ˃̵͈̑ᴗ˂̵͈̑ 지인들에게 엄청 추천했답니당 ◡̈', 14, 6, 'GOOD', SYSTIMESTAMP);
