INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비하인드'), (SELECT member_id FROM member WHERE email = 'user00091@test.com'), '전 정말 아껴먹으려 했는데 너무 맛있어서 후다닥 먹어버렸어요 원래는 그냥 프렌치토스트를 먹으려 했는데 솔드아웃이더군요… 저는 “프렌치토스트”를 먹기 위해 찾아보고 간 거였기에 아이스크림 올려진 거로 시켰는데 어머나 세상에 너무 맛있었어요 막 바이럴 된 것이 아닌 동네 주민들의 단골집 느낌이라 매장 분위기도 고즈넉하게 좋았고, 플레이리스트도 넘 좋아서 기분 좋은 시간 보냈어요! 그리고 토스트에 캬라멜라이징(아닐 수도) 같은 것이 되어있어서 달콤바삭했어요 짱… 다음에는 토스트만도 먹어보고 싶어요 왜 먹는 과정을 찍었냐면 한 입 먹을 때마다 맛있어서… 놀라서 어쩔 수 없었어요 근처에 일 있을 때마다 오고 싶은 곳이에요 왕추천합니다', 21, 3, 'GOOD', SYSTIMESTAMP);
