INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비하인드'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '매장 테이블 수가 많은 편은 아니지만 분위기가 좋고 인테리어도 좋아요. 차분하고 조용한 분위기로 아늑한 느낌도 있고 책 읽기 더 좋을 것 같은 분위기입니다. 프렌치토스는 양이 작지만 맛보기로 딱 적당한 사이즈고 아이스크림 올라간 버전 추천합니다!', 42, 8, 'GOOD', SYSTIMESTAMP);
