INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비하인드'), (SELECT member_id FROM member WHERE email = 'user00044@test.com'), '드디어 말로만 듣던 비하인드를 방문해보았네요, 카페 분위기도 조용하고 아늑한데다 커피맛도 좋고 특히나 시그니처 메뉴인 프렌치토스트가 무척 맛있습니다. 그냥 커피만 마시고 오기엔 아까운 곳이에요. 아이스크림 올린 것보단 일반 프렌치토스트를 추천합니다.', 30, 10, 'GOOD', SYSTIMESTAMP);
