INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비하인드'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '🔹메뉴추천 : 아메리카노 🔹개인적 의견 : 분위기가 다한 곳! 뭔가 레트로 감성도 있으면서 술집 같기도 하고 오묘한 느낌! 소개팅 하고 2차로 오면 좋을 것 같은 곳! 밖에서 보고 술집인 줄 알았는데 들어와도 조명이 엄청 밝은 느낌은 아니라서 사진도 잘 나오고 조용한 분위기라 사람들도 너무 시끄럽게 떠들지 않는 듯! 따로 디저트를 못 먹어봤는데 한 번 더 방문의사 있음! 개인카페지만 디카페인 원두 있어서 디카페인 선호자들에게도 좋은 듯😊 💛장길동의 맛도리로드💛', 23, 1, 'GOOD', SYSTIMESTAMP);
