INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비하인드'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '카페가 넓지는 않지만 적당한 공간으로 아늑하니 혼자 있기에도 부담없는 분위기 입니다 프렌치 토스트 맛집이네요 사이즈가 크지 않아서 배고픈 상태이면 1인 1접시 필수 아이스크림 올려져 있는걸로 추천하는 후기 보고 시켰는데 안먹었으면 후회했을 듯 촉촉한 토스트랑 차가운 아이스크림 조합은 맛없없😛', 44, 5, 'GOOD', SYSTIMESTAMP);
