INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비하인드'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '시끄러운 홍대 속 분좋카.. 무려 4번째 재방문🌟🌟🌟🌟 적당한 층고 적당한 실내향..(인센스향 세면 멀미남ㅜ) 1인 카공족을 위한 테이블과 콘센트 나머지는 대화하기 좋은 소파들인데 공간 분리가 잘되어있어서 집중 잘됨 여기 프토가 맛있다는데 꼭 먹어보는게 소원쓰', 78, 14, 'GOOD', SYSTIMESTAMP);
