INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비하인드'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '프렌치 토스트 먹으러 한번씩 옴 바닐라라떼는 내 기준 별로 달지 않은 편임.. 약간의 커피 쌉싸름한 맛이 느껴짐ㅠ 더 달았으면 좋겠음', 17, 5, NULL, SYSTIMESTAMP);
