INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비하인드'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '분위기가 힙해요!! 자리도 적당히 있는데 콘서트 자리는 많지 않습니닷 커피가 대부분 진해서 조금씩 녹여서 먹어도 좋을 거 같아요 ㅎㅎ 전반적으로 좋습니당 👍🏻👍🏻', 15, 10, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비하인드'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '보통 카페에는 케이크, 모두가 아는 베이커리류가 전부인데, 이곳은 토스트를 합니다..?! 일반 토스트와 아이스크림이 올라간 토스트가 있는데, 크로플을 떠올리며 아이스크림이 올라간 메뉴로 선택했습니다! 가격도 나름 합리적이고, 토스트 위에 초코 가루 뿌려진 것이 신의 한 수👍 이런 디저트에 초코가루를 뿌리면 웬만하면 업그레이드 되겠다 싶었습니다👍👍👍 음료도 너무 달지 않은 것이 좋았고 분위기도 좋아 만족했습니다 :) 잘 먹고 갑니다!', 81, 14, 'GOOD', SYSTIMESTAMP);
