INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비하인드'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '프렌치토스트 맛있다고 해서 찾아갔어요 양이 적어서 넘 아쉬움 토로ㅋㅋ 머핀사이즈 크기라 1인 1토스트 필수고요 부드럽고 맛있네욤 🤭', 19, 3, NULL, SYSTIMESTAMP);
