INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비하인드'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '약간의 대기가 있을수있지만 기다려서 먹을 가치가 있다고 생각함 프렌치토스트가 짱맛이에요.. 개인적으론 아이스크림보다 기본 프렌치토스트가 더 좋았어요 그외엔 화장실 주의문구가 웃겼네요 가오가 정신을 지배한다', 0, 0, 'GOOD', SYSTIMESTAMP);
