INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비하인드'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '지나가다가 고즈넉하니 좋아보여서 들어왔습니다. 약간 어둑어둑한 분위기에 아담하고 편안한 느낌이에요. 저녁이라 차 종류를 마셨지만 다음엔 낮에 와서 커피도 한 번 마셔보고싶어요.', 34, 8, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비하인드'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '분위기 정말 좋고 인테리어 하나하나 신경쓴게 느껴져요, 바닐라 아몬드 라떼를 시킨 달달이러버는 그냥 마셨어요.. 아몬드 향이 은은하게 남아 좋아하시는 분은 정말 좋아할거 같아요! 저는 음..그랬어요ㅎㅎ 편안한 분위기에 대화하고 잘 쉬다 갔어요!!', 36, 5, 'GOOD', SYSTIMESTAMP);
