INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비하인드'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '크림 커피맛있었어요.  디져트도 꽤 괜찮았어요. 아메리카노는 그냥 그냥… 앞마당 보이는 작은 카페에요. 분위기도 따뜻하고 괜찮아요.', 295, 75, 'GOOD', SYSTIMESTAMP);
