INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비하인드'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '믿고 가는 비하인드 ,,! 누굴 데려가도 다 만족하는 곳이에요 ㅎㅎ 다른 건 몰라도 프렌치 토스트는 꼭 먹어보시길 바라요! 제 최애는 바닐라 아이스크림 맛입니다 :)', 85, 14, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비하인드'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '프렌치 토스트가 맛있어서 애정하는 곳이었는데 코로나로 한참 못 가다가 오랜만에 갔는데 크기가 좀 눈에 띠게 작아졌네요 ㅠㅠ 아쉽', 4, 10, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비하인드'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '분위기 좋고 괜찮은데 생각보다 장소가 많이 작습니다. 되게 맛있다는 후기 보고 프렌치토스트 시켰는데 괜찮긴 한데 막 독보적이다 이런 건 아니에요. 장소가 너무 작아서 요즘 같은 때 자주 가긴 어렵지 않나 싶은 곳…', 12, 1, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비하인드'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '믿고 먹는 비하인드 프렌치토스트 .... 1인 1개 시키는 걸 추천드려요! 양이 적은데 너무 맛있어서 진짜 순삭이에요 ㅠ_ㅠ  바닐라 아이스크림 올라간 것과 블루베리 크림치즈가 최애 두 가지 맛 입니다 ☻', 8, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '비하인드'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '비하인드 십년전부터 단골임 그런데 방문한 날 메탈같은 시끄러운 노래를 틀어서 대화하기 어려웠음ㅠ 별 하나 뺌 프렌치토스트가 맛있음', 29, 10, 'BAD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '동화 속에 나올 것만 같은 예쁜 케이크와 귀여움 가득한 소품과 인테리어가 매력있는 장소였어요!! 아메리카노랑 먹고싶었는데 동생이 모르고 메론소다를 두개나 주문해서 달달조합 부담스럽지 않을까... 걱정했지만 생각보다 톡쏘고 상쾌한 소다였어서 꽤 어울렸습니다!', 62, 13, 'GOOD', SYSTIMESTAMP);
