INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00080@test.com'), '전부터 너무 오고 싶었던 곳인데 드디어 방문했네요🥰 매장 빈티지 인테리어가 예쁘고 사진도 잘나와요💕 케이크 디자인도 다 예뻐서 어떤거 먹을지 한참 고민했어요😂 케이크도 크림 안에 초코칩이 씹혀서 맛있었어요❣️ 다음에 또 방문하고 싶어요👍', 103, 26, 'GOOD', SYSTIMESTAMP);
