INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '보통의 날에도 특별한 날에도 언제나 기분 좋은 날을 만들어주는 베니케이크 입니다:) 항상 오면 1인 1케이크 하는데요.. 진짜 너무 맛있고 커피랑 궁합이 좋아요! 유튜브 보고 정말 예쁜 케이크를 만드시는구나 생각했는데 카페가 있다고 해서 와봤더니 정말 좋아요 분위기가 좋고 매장 음악도 너무 잘 어울려요! 다음에 또 올게요 ~ ^_^', 16, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
