INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '홍대 상수의 대표 케이크카페 베니케이크!!! 🍰 알고보니 저 어렸을때 자주 봤었던 케이크 레터링 영상 .. 가게였던 것이에요 ㄷㄷ 아직까지도 몰랐었다는게 놀라울따름..😮 카페 분위기도 좋은데 케이크 정말 맛있어요!!🤍 라즈베리 케이크에서 크림까지도 라즈베리 맛나고 망고케이크도 크림에서 망고맛나요! 이런 케이크는 진짜 처음.. 진짜 맛있어서 나중에 재방문할 생각이에요ㅠㅠ 홀케이크도 귀엽고 푸딩케이크도 탐났어요', 39, 7, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '드디어 너무 와 보고 싶었던 베니케이크에 왔어요 ㅠㅠ 초코라즈베리케이크에 아아 시켜먹었는데 라즈베리맛이 새콤달콤 라즈베리 씨가 톡톡 초코맛이 달콤씁쓸 진한 게 조화롭게 맛있어요 ㅠㅠ 크림은 크림치즈라 느끼하지 않고 더 맛있네요 ㅠㅠ 아아는 산미가 있는 맛! 혼자 너무 여유롭고 눈과 혀가 즐거운 행복한 티타임 즐겼어요 다른 맛도 다 먹어보고 싶어요 ㅠㅠ', 49, 5, 'GOOD', SYSTIMESTAMP);
