INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '케이크는 다 너무 유니크하고 예쁘고 진짜 맛있어요. 근데 여자 사장님은 너무 친절하신데 남자 분께서 제조하시던 음료 컵 바닥에 떨어뜨렸던 거 그냥 그대로 다시 써서 사용하시는 것 같더라고요... 조금 충격이었네요...', 124, 23, 'BAD', SYSTIMESTAMP);
