INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '제가 운영하는 모임 기념일이나 행사 할때마다 미리 주문해서 이용하고 있어요. 케이크도 너무 예뻐서 기본디자인만 해도 충분해요. 안에 시트도 다양한데 이번엔 기본맛인 요거트복숭아 했어요. 매번 모임 분위기 살리는데 베니케이크가 큰 도움 주고 있어요 ♥️ 가게도 아기자기하고 예뻐요', 77, 13, 'GOOD', SYSTIMESTAMP);
