INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '베니케이크 먹으러 멀리서 찾아왔어요. 유튜브에서만 보다가 실제 방문하니 예쁜 케이크만큼 맛도 너무 좋아요. 빈티지한 감성에 방문한이 모두 즐거이 쉬다 갑니다.', 111, 20, 'GOOD', SYSTIMESTAMP);
