INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '인테리어 너무너무 귀엽고 케이크는 더더욱 귀여운 곳입니다! 귀염뽀짝한 디저트들이 맛도 좋고 분위기도 너무 좋았어요 🥰 꼭 또 방문하고 싶습니다', 7, 3, 'GOOD', SYSTIMESTAMP);
