INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '당일 케이크 급하게 찾아봐야했는데 레터링까지 즉시 가능하고 너무 예쁘고 귀여워요 ㅜㅜㅜㅜ 북적북적 사람들도 많이 찾아주시는 것 보니 안먹어봐도 맛은 알 것 같아요 🗯️🐰🧡 좋은 케이크 선물이 되어서 감사한 하루 !', 14, 8, 'GOOD', SYSTIMESTAMP);
