INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00072@test.com'), '오레오 바나나 스플릿을 처음 먹어봤어요! 아이스크림이 너무 부드럽고 맛있었습니다 ㅎㅎ 예쁜 케이크도 나중에 먹어보고싶어요~ 인테리어도 아기자기하고 귀엽습니다', 19, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '인테리어부터 음료, 디저트까지 너무 마음에 들어요! 곳곳에 귀여운 포인트들이 많아요 그리고 케이크가 전부 너무 예뻐서 다음에 오면 못 먹어본 케이크 시켜먹어보고 싶어요ㅎㅎ 잘먹고 갑니당~', 47, 8, 'GOOD', SYSTIMESTAMP);
