INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00096@test.com'), '아 진짜 입이 너무 행복해요.... 주문제작 케이크 예약해놓고 겸사겸사 다른케이크도 먹어보고 싶어서 방문 했는데 ... 케이크맛집 ㅠㅠㅠㅠㅠ크림이 상콤해서 느끼하지도 않고 한조각 순삭 하는 맛입니다 메론소다도 짱 존맛 청량 달달 그자체 커피 고소하니 아주 굿이고요! 집앞에 베니케이크 있었으면 매일 한조각씩 사먹었을듯 엉엉 ㅠㅠㅠㅠㅠ 잘먹고 잘쉬다 갑니다 😭🩷', 39, 6, 'GOOD', SYSTIMESTAMP);
