INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '카페 인테리어를 너무 예쁘게 꾸며나서 사진 찍기 너무 좋아요!!!! 자리도 많아서 좋습니당~ 디저트는 배불러서 못 먹었지만 케이크도 너무 예뻐요ㅠㅠ>< 사장님도 너무 귀여우시고 예쁘시고 친절하세요!!!! 커피도 맛있어용🤍', 4, 10, 'GOOD', SYSTIMESTAMP);
