INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '오 엠 지져스크라이스트 진짜 너무너무너무 귀여워요 !!!!!!! 게다가 정말 맛있음 ㅠㅠ 아늑하고 조용하고 하이틴스럽고 예쁘고 귀엽고 ㅋㅋㅋㅋㅋ 특히 들어오는데 작은 햄쮜가 들어갈만한 문이 진짜 핵졸귀탱 ㅋㅋㅋ 🩵🩵🩵', 8, 6, 'GOOD', SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '100일 기념으로 방문했어요! 얼그레이 초코케이크랑 복숭아요거트랑 고민하다가 얼그레이 초코케이크 시켰습니다.기념으로 토끼초까지 사서 불어줬어요. 케이크는 고소한 얼그레이크림과 위에 발려진 초코생크림이 너무 달지 않아서 좋았어요. 빵과 크림의 비율도 좋아서 먹는내내 행복했습니다. 위에 러브유라고 써져있어요. 공주컨셉의 카페라 여성분들이 좋아하실거 같아요 아메리카노랑 밀크티 시켜서 같이 먹었습니더', 12, 6, 'GOOD', SYSTIMESTAMP);
