INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '케이크 맛집이라고 해서 찾아왔어요!! 케이크들이 넘 예쁘고 인테리어도 아기자기하고 볼게 많아요! 디카페인은 없지만 티 종류가 다양해요💕', 88, 16, 'GOOD', SYSTIMESTAMP);
