INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '매장 자체가 아기자기하게 꾸며놓아 사진 찍기 좋았습니다. 아메리카노 고소한 게 정말 맛있어요 메론 소다는 여름에 먹기 딱 좋은 청량하고 시원하면서 달달한 맛이구요 케이크는 가게 이름에 케이크가 들어가는 만큼 정말 맛있네요 퀄리티가 정말 높고, 달달한 맛도 과하지 않게 맛있는 단 맛입니다. 주변 데이트로 들렀는데 좋은 추억이 됐습니다.', 11, 0, 'GOOD', SYSTIMESTAMP);
