INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00076@test.com'), '케이크가 너무 예뻐요!! 요즘 물가 생각하면 케이크 가성비도 대박 좋아요 ㅎㅎ 인테리어도 너무 아기자기해서 귀여운 것 좋아하신다? 무조건 여기!!!', 40, 0, 'GOOD', SYSTIMESTAMP);
