INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00071@test.com'), '코로나때 우연히 유투브알고리즘 타서 케이크만드는영상보면서 힐링했는데 드디어 실물영접했네요🧸🩷 인테리어 너무 이쁘고 케익 비주얼도 맛도 맛있었어요!! 인형의집에 온 느낌이었어요🫶 힐링하고 갑니당', 18, 1, 'GOOD', SYSTIMESTAMP);
