INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '고마운분께 귀여운 케잌 선물해드리려거 들렀어요 항상 귀여운 노래와 케이크가 있는곳!! 홍대에서 젤 예쁜케잌 파는곳이에요❤️‍🔥🪽🪽', 99, 21, 'GOOD', SYSTIMESTAMP);
