INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '여긴 천국입니다. 케이크가 너무 귀여웠어요. 게다가 맛있어요. 달달한걸 좋아하는 분은 무조건 오셔야 한다고 생각합니다. 컨셉도 확실하고 디저트랑 음료도 너무 맛있어요. 초콜릿 좋아하하시는 분들은 초코 러버 케이크랑 초코 얼그레이 크림 라떼 꼭 드셔보세요. 진하고 달고 맛있어서 추가로 충동구매 할 뻔한거 겨우 참았습니다.', 24, 6, 'GOOD', SYSTIMESTAMP);
