INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '감성 맛집 ! 케이크 달달하고 맛있습니다 ! 음료도 맛있고 독특해서 좋았흡니다 ! 가게 분위기도 예뻐서 즐거움이 가득합니다 ! 직원분들도 모두 친절하게 대해주셔서 기분좋게 먹고 갑니다 ! 결론 = 너무 좋아요 !', 31, 8, 'GOOD', SYSTIMESTAMP);
