INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '너무 예뻐서 맛있을까? 했는데 맛있네요 그리고 진짜 예뻐요 가게도 이쁘구요.. 동생데려왔는데 몰랐는데 동생이 베니케이크 유튜브 팬이래요 ㅎㅎ 복숭아 요거트 케이크, 바노피파이 둘다 맛있는데 바노피파이가 좀더 특별한 느낌? 파이지에 발려있는게 되게 맛있어요', 51, 18, 'GOOD', SYSTIMESTAMP);
