INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '아이 생일이면 항상 맞춤 케이크로 파티해주는데 올해도 실망없이 해주시네요. 맛은 말할것도 없는게 친구들도 항상 좋아하고 평소에도 집에 오면 찾아요. 항상 기대한만큼 값을 합니다.', 50, 8, 'GOOD', SYSTIMESTAMP);
