INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '케이크 구경가다가 너무귀여운 곳이 있어서 케이크 하나 구매하구 가요!! 너무너무 예쁘고 데이트하기 좋아보입니다! 성수 귀요미 케이크 맛집! 극 추천!', 70, 13, 'GOOD', SYSTIMESTAMP);
