INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00018@test.com'), '베니케이크! 매번 기념일에 케이크 사러 방문하고 있어요! 특히 바나나푸딩 케이크 너무 맛있어요…가격도 다른곳보다 저렴하고 좋은것같아요! 이번에도 친구 퇴사 기념으로 방문했는데 너무 만족스러워요!다음에도 방문할게요🤤❤️', 83, 13, 'GOOD', SYSTIMESTAMP);
