INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '처음에 예쁜 케이크에 반해서 찾아왔는데 예쁜 만큼 맛이 정말 좋아서 놀랐어요! 이번에는 기념일 케이크 주문제작했습니다~ 러블리하고 맛있는 베니케이크 최고에요!', 63, 18, 'GOOD', SYSTIMESTAMP);
