INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00062@test.com'), '너무 가보고싶던 베니케이크🤎 사실 너무 예뻐서 예쁜만큼 맛있을까? 싶었는데 너무너무 맛있었어요🫶🏻 얼그레이초코, 얼그레이귤 먹어보았는데 많이 달지않고 부드러웠어요~ 얼그레이귤은 속에 달고 맛난 통귤이~!!  아이들이 비쥬얼 보고 고른거라 얼그레이 호불호가 있지 않을까했는데 너무 맛있다며^^ 예쁘고 귀여운데다 너무 맛있는 베니케이크~ 집에서 거리가 멀지만 자주 방문하고 싶어요🤎', 85, 12, 'GOOD', SYSTIMESTAMP);
