INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '베니케이크 인스타만 보다가 드디어 왔는데 초코케이크가 너무 달지 않고 맛있기가 쉽지 않은데 너무 맛있었고 복숭아요거트케이크도 너무 맛있었어요 음료는 말해뭐해입니다 >_< 인테리어도 너무 예쁘고 잘 쉬고 힐링하다가 갑니다 :)', 50, 0, 'GOOD', SYSTIMESTAMP);
