INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '벌써 몇 번 째 방문하는지 모를 베니케이크 늘 얼그레이 초코 케이크를 주문해서 먹습니다. 인테리어와 배경음악도 유성영화 초기 시절 빈티지 풍이라 좋아요~ 특이한 컨셉에 맛있는 디저트 찾으시는 분들에게 추천해요.', 1, 2, 'GOOD', SYSTIMESTAMP);
