INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '케이크 유튜브에서 보던대로 너무 예뻤고 맛도 있어서 놀랐어요 보통 인스타 케잌집은 예쁘기만하고 맛은 없는데 베니는 맛도 있어서 다음에 또 가려고요', 31, 5, 'GOOD', SYSTIMESTAMP);
