INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '항상 자주가는 베니케이크 🎂 친구들이나 부모님과 오거나 누구랑 와도 다들 좋아해요🥰 미국 할머니집 인테리어느낌인데 케이크는 디자인도 예쁘지만 맛도있어요ㅎㅎ 제 최애는 복숭아케이크와 딸기케이크, 얼그레이초코입니다😋😋 기념일케이크나 가족들이나 친구 생일케이크 저는 여기서 해요🍓🍓 딸기랑 복숭아케이크 하나도 물리지않고 크림과 시트의 조화가 괜찮습니다👍 케이크별로안좋아하는 아부지 남동생 남자친구 등등도 잘 먹는 편인 케이크집입니다👍😉', 7, 7, 'GOOD', SYSTIMESTAMP);
