INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '한 몇년전에 자른 장소에 있을때 방문했었는데 그때 케익이 너무 맛있어서 이사간곳으로 오랜만에 들렀어요! 여전히 너무 맛있구 매장 분위기가 너무 예뻐요!', 1, 3, 'GOOD', SYSTIMESTAMP);
