INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '베니케이크 너무 예뻐요,,,,,🩷 꼭 동화에 나올 것만 같은 인테리어와 디저트들🫶🏻 케이크도 예쁜데 맛있고 커피도 맛이 좋더라구요. 마침 당일 구매할 수 있는 보틀케이크가 있어서 구매했어요! 레터링 문구 요청 드릴 수 있답니당😉 상수,홍대,합정 카페 찾고 계신 분들은 요기 꼭 방문해보세용,, 한번 들리구 반해서 전 자주 갈거 같아요😃💓 초와 엽서도 판매하고 있어서 케이크랑 같이 구매할 수 있으니 좋네용👍', 5, 7, 'GOOD', SYSTIMESTAMP);
