INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '케이크 너무 귀여워서 하루만에 결정해서 냅다 온..말차무스 너무 달지 않을까 싶었는데 딸기 상큼한 맛이랑 잘어울려서 맛있었어요😋 인테리어도 귀여우니 꼭 한 번 방문하시길😄', 3, 6, 'GOOD', SYSTIMESTAMP);
