INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '커스텀 케이크 주문했는데 사장님께서 잘 만들어주셨어요. 기본맛인 복숭아요거트를 선택했는데 상큼하고 맛있었습니다. 특별한 날을 기념하고 싶을 때 또 찾고싶어요 :)', 35, 9, 'GOOD', SYSTIMESTAMP);
