INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00055@test.com'), '케이크랑 음료가 진짜 너무너무 귀여운데 맛까지 있어요🥹 카페 분위기도 아기자기 따스하고 머무는 동안 기분까지 몽글몽글해졌습니다🫧 덕분에 좋은 시간 보냈어요 감사합니다🍀✨️', 41, 8, 'GOOD', SYSTIMESTAMP);
