INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '가게인테리어 넘 이쁘고 빈티지 미국 감성이에여 생각보다 곳곳 좌석이 많고 지하도잇어요 바나나 타르트 진짜 최고존맛 대박임 대박 얼그레이 초코케이크도 맛잇는데 바나나타르트는 다른데서 못먹어보는 맛인걱같아여 케이크 시켜도 1인 1음료임다 바나나 타르트 바나나 좋아하면 꼭 꼭 필수 드셔보삼 크림도 맛잇음', 59, 14, 'GOOD', SYSTIMESTAMP);
