INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '너무 귀여워요,, 케이크도 너무 맛있어요!! 크림 달지 않고 부드럽고, 망고 케이크 먹었는데 진짜 녹아요ㅠ✨ 아기자기 소품들도 많고, 진열되어있는 레터링 케이크 넘 귀엽네용', 43, 1, 'GOOD', SYSTIMESTAMP);
