INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '최고의 카페 케이크 천재의 카페 !!!!!!! 🤍🤍 주문제작 케이크는 2번 먹어봤는데 카페는 처음 와봤어요 !! 외관부터 크리스마스로 꾸며놨는데 너무 아름답고 그냥 살고싶은 기분이 들 뿐 .. 케이크 종류도 진짜 많았음 가격은 평균적으로 한 8,300원 정도 하는거 같습니다 .. 매장이 아기자기 하게 꾸며져 있어서 있는 내내 너무 행복해요 ~ 케이크맛은 말모 넘 맛있음 !!!! 복숭아요거트 젤 조아하는데 이 날은 레몬라즈베리랑 얼그레이 초코 케이크 먹었어요!  레몬 라즈베리 상큼하고 너무 좋음 얼그레이 초코 아아랑 먹음 최고 얼그레이 좋아한다면 꼭 드셔보시길 .. 하지만 복숭아 요거트 진짜 맛있어요 그리고 무엇보다 케이크가 너무 아름다움 ..... 강추 베니케이크 짱 !!!!!🤍', 85, 16, 'GOOD', SYSTIMESTAMP);
