INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '으앙 초코라즈베리케이크먹고싶었는데 품절이라니 아쉬워오!!! 다음에 꼭 일찍 가서 주문할게요 브릅! 초코얼그레이케이크랑 딸기케이크 넘나 존맛탱!!!! 재방문의사있름!', 44, 6, 'GOOD', SYSTIMESTAMP);
