INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '회사 팀장님이 한번 사주셨는데 너무 맛있어서 모임때마다 사가고 있습니다. 갈때마다 너무 친절하시고 케이크도 많이 달지않고 맛있어요!! 치열한 주말 보내고 따뜻한 연말을 보낼 수 있었으면 좋겠습니다.', 65, 12, 'GOOD', SYSTIMESTAMP);
