INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '1인 1케이크 할만큼 케이크가 마싯어요 사진 잘나올거같은 인테리어들이 가득이고 지하는 이쁘긴 한데 한팀이 먼저 들어가면 소리가 좀 웅웅 거려서 두번째 팀이 들어가기 빡세여 그래도 뭐… 맛있응께', 32, 3, 'GOOD', SYSTIMESTAMP);
