INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '상수역에서 카페갈 때 베니케이크만 기억하면 되겠어요 카페 너무너무너무 예뻐요!!!! 할로윈느낌 물씬나요! 케이크가 진짜 장난아니에요. 기념일 케이크준비로 강추합니다!!!!! 레터링도 가능해요! 케이크가 찐으로 맛나요!!!', 20, 3, 'GOOD', SYSTIMESTAMP);
