INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00099@test.com'), '해리포터케이크 주문후 방문했습니다 디자인 이쁜케이크종류별로 많아요 초코맛 진짜 맛있어서 깜짝놀랐어요 행복한 기념일 보낼수있었네요 감사합니다🙆‍♀️', 4, 9, 'GOOD', SYSTIMESTAMP);
