INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00081@test.com'), '케이크랑 인테리어가 멋진데 심지어 맛있는곳❣️ 직장근처 레터링케이크 맛집 알아보다 알게되었는데 진짜맛있어요 후회안하세요👍👍 그래서 남친데리구 왔어요🥰 케익은 꼭먹어 봐야합니다 인테리어도 아늑하고 좋네요', 2, 6, 'GOOD', SYSTIMESTAMP);
