INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '근처에 일정있어서 왔다가 시간이 남아서 찾아왔는데 상수동에 이런곳이 있다니....매장도 너무 예쁘고 커피랑 케잌도 너무 맛있어요. 스피커에서 나오는 음악들으며 가만히 앉아있으니 외국에 온 느낌이에요. 인테리어도 외국 감성이고 가정집에 초대받아 간 기분이랄까..웨이팅만 아니면 하루종일 있고싶을정도로 분위기가 정말 좋아요 😀', 33, 4, 'GOOD', SYSTIMESTAMP);
