INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '이곳을 사랑하는 사람으로서.. 진짜 여기 케이크만 몇번을 먹은건지 세상에 이번 바노피 케이크 진짜 끝내줍니다...최고. 신상 귀여운 바노피 먹을지 예쁜 샤인머스켓 먹을지.. 고민하다 결국 늘 최애인 복숭아 요거트랑 라즈베리 갸또. 그리고 직원분의 추천으로 귀여운 바노피를 먹게 되었는데요. 세상마상에 아니 제 최애 자리를 위협하다니. 늘  먹을때마다 최애 자리는 위협당했지만 아무튼 진심 와.대박. 바노피 진짜 미친놈입니다 너무 맛있어요 쫀득 달콤 카라멜인지 뭐시기와 바나나 바삭 파사삭 타르트 부드러운 크림. 저는 또 다시 사랑에 빠지고 말았습니다.', 48, 0, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '아기자기한 소품들로 가득한 미국 레트로 컨셉 인테리어가 특이하고 예뻐요 ㅎㅎ 진짜 미국 가정집에 있는 듯한 기분 !! 벌써 할로윈 분위기로 꾸며놓으셨더라구요 🎃🎃🦹🏻‍♀️🧙🏻‍♀️🧌🧟 케이크 비주얼도 독보적 !!! 느끼하지 않고 산뜻한 생크림케이크, 너무 달지 않으면서 적당히 꾸덕함 얼그레이 초코케이크 모두 만족스러웠어요!! 케이크 비주얼도 넘 예쁘답니다 커피도 맛있어용!!', 34, 1, 'GOOD', SYSTIMESTAMP);
