INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '여러 번 재방문했어요! 케이크 귀엽고 맛있고 인테리어 너무 아기 자기하고 아늑해요! 멜론케이크는 크림이 생멜론향이 솔솔 나서 조오온맛이고 레몬코코넛크림파이는 레몬맛이 시지 않고 은은해서 상큼달콤사르르하고 맛있어요!! 다음에 또 올게요!', 80, 14, 'GOOD', SYSTIMESTAMP);
