INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00035@test.com'), '케이크가 너무 귀여운디 진짜 너무부드럽고 한입먹자마다 너무 맛있어요😭🥰💕💕 정말 너무너무 예쁜 미쿡빈티지느낌의 케이크카페에요💕올드재즈부터 소품하나하나 너무 귀엽고 또올거에요🙏🏄🏻‍♀️너무특별한 경험!', 29, 8, 'GOOD', SYSTIMESTAMP);
