INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00030@test.com'), '너무 너무 귀엽고 사랑스러운 공간이에요🩵 지인 추천으로 와봤는데 케이크도 넘 맛있구 라떼도 맛있어요🥹 친구 생일에 쓸 케이크도 주문해놨는데 넘 기대되요!', 96, 19, 'GOOD', SYSTIMESTAMP);
