INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '직원분이 너무너무 친절하시고 지금 할로윈이라 컨셉에 맞춰서 꾸며둔것도 정말 예뻐요. 음료랑 케이크도 맛있어욥. 레터링케이크도 주문했는데 만족합니당.', 109, 23, 'GOOD', SYSTIMESTAMP);
