INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '👉친척언니가 완전! 강추해서 방문했어요^^ 여기 메론케이크가 그렇게 맛있다고… 메론케이크는 따로 포장하고 아이스아메리카노만 먹고 왔어요! 👉커피는 고소한 커피였어요! 끝맛이 달달한 향이 났어요~ 첫입은 고소 끝맛은 달달 딱 입에 넣었을 때 메론 향이 은은하게 퍼짐! 그후 엄청나게 단 생크림 맛이 느껴졌다. 바로 메론이 씹히지 않았고 두 번째 먹을 때 씹혔다. 시트가 단건지 크림이 단건지 약간 분간이 가지 않았다. 케이크 바닥은 오버 쿠킹이 되어서 질기고 너무 퍽퍽하였다. 너무 달아서 멜론이 메론향이 나는 멜론식감 물먹는 느낌? 실망.. 지극히 개인적인 의견입니다^^ 너무 단것보다 적당히 달고 입에서 조화로운 맛을 내는 디저트를 좋아합니다. 어떤 매장을 깍아내리거나 비방하는 것이 아닙니다!!', 63, 17, 'BAD', SYSTIMESTAMP);
