INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '네이버에 찜해논 가게♡ 멀리서부터 가게가 한눈에 들어와요!! 할로윈 장식으로 전체를 꾸며노셨는데 너무 아기자기하고 귀여움 ㅜㅜ 케이크도 너무 귀엽고  다 맛있어보여서  결정장애 오는곳이예요...😵‍💫 레몬코코넛 크림파이 랑 라즈베리 갸또 쇼콜라 먹었는데 레몬은 상큼하고 라즈베리는 꾸덕꾸덕!!😋 둘다 넘나리 맛나요♡', 6, 5, 'GOOD', SYSTIMESTAMP);
