INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '매장 소품들이랑 인케리어가 아기자기해서 이뻐요 , 케이크들도 디자인이 너무 이뻐요!! 전에 매장에서 커스텀케이크로 구매했을때도 너무 만족했는데 이전하면서 매장도 이용할 수 있어서 기뻐요 ♡ 완전 추천합니다 !!!', 76, 13, 'GOOD', SYSTIMESTAMP);
