INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '크리스마스 케이크 예약했는데 완전 만족해요! 가족들도 다 이쁘다고 좋아했어요 🥹 자르기 아까울정도.. 진짜 맛도 있어서 담에 또 케이크 주문 할 일 있으면 베니케이크로!!', 118, 24, 'GOOD', SYSTIMESTAMP);
