INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00024@test.com'), '항상 와보고 싶었던 곳인데 인테리어도 너무 예쁘고 케익 하나하나 다 정성 들어간 곳이예요💗💗 포장해서 가는데 친구 생일이나 기념일 선물하기 좋아요👍👍', 27, 3, 'GOOD', SYSTIMESTAMP);
