INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00014@test.com'), '고딩 때부터 유튜브 구독했던 베니케이크~~우연히 방문했는데 역시 너무 맛있네요!!! 유튜브 보고 군침 좔좔 흘리던 어린이는 혼자서 케이크 두조각 해치우는 어른이가 되었습니다~!! 또 방문하고 싶어용🩷특히 레몬코코넛파이가 제 입맛에 딱 맞았어요!', 101, 20, 'GOOD', SYSTIMESTAMP);
