INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '너무 귀엽고 분위기가 좋아용 전부터 케이크가 너무 귀여워서 오고싶었는데 직접 와서 보니까 더 귀여워요! 나중에 홀케잌주문하러도 오고싶어요. 분위기도 케잌이랑 너무 잘 어울리고 미국 온 듯한 느낌이예요', 14, 6, 'GOOD', SYSTIMESTAMP);
