INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '첫 방문이예요! 10월이라 할로윈 컨셉으로 꾸며져 있었어요👻 복숭아 요거트 케이크와 아메리카노를 먹었는데 맛있었어요! 친구의 한 마디 : 케이크가 신선해🍑', 81, 17, 'GOOD', SYSTIMESTAMP);
