INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), '가게도 너무너무 예쁘고 음료도 맛있고 케이크는 정말 최고에요!!😍🩵💛 베니케이크 유명해서 홍대에서 몇 번 픽업해서 이용했었는데 이사 온 뒤 가게 방문은 처음인데 넘 아기자기하구...귀엽고 좋아요ㅠㅠ🧡🧡 케이크 예쁘고 맛있습니다 :) 안내도 친절하게 안내해주시구 덕분에 잘 받았습니다^^ 베니케이크 꼭 오세요 :) 🍰🍰', 47, 6, 'GOOD', SYSTIMESTAMP);
