INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '역시 유명한대로 케이크가 진짜 눈물나게 맛있습니다 🎂🍰🍈🍹 카페도 아기자기 러블리하니 넘 이쁘고 귀여워요!! 🩷💛💚후회안할카페 .. 다음에 또 갈 의향 1000000000%입니다', 8, 6, 'GOOD', SYSTIMESTAMP);
