INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '홍대에 빈티지 카퍼 찾다가 발견했어요. 단독주택 처럼 대문 있고 앞에 마당 있어서 밖에서 사진 찍기도 좋고요. 카페 1층, 지하에 좌석 있어서 자리는 많아요. 옛날 유럽 가정집 느낌으로 인테리어가 너무 귀엽고 빈티지 해요. 그리고 케이크도 맛있습니다! 망고 케이크랑 복숭아 요거트 케이크 시켰는데 친구는 망고 케이크가 좀 더 맛있다고 해요! 사진 찍기도 좋고 음악 분위기도 좋고 얘기 나누기 정말 좋은 곳이에요.', 84, 14, 'GOOD', SYSTIMESTAMP);
