INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '케이크 전체적으로 생긴거에비해 너무달아! 느낌이아니고 맛있게 달아서 먹기좋아욧 개인호로 펌킨파이 추천...b 무난한건 생크림요거트 초코러버가 조아할 찐한 초코와 라즈베리...(맛남) 다음에 또올지둣 ~ 할로윈시즌엔 할로윈느낌낭낭해서조아요', 45, 5, 'GOOD', SYSTIMESTAMP);
