INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00092@test.com'), '케이크도 이쁘고 속이 꽉 차있는데 맛있습니당😋 (종류별로 다 먹어보고싶네용....🤭) 아메리카노도 케이크랑 잘 어울리고 고소하니 맛있었어요!', 74, 12, 'GOOD', SYSTIMESTAMP);
