INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '음료랑 케이크가 진짜 완전 맛있어요🥹 상수에 있는줄 몰랐는데 알게되어서 자주 올 것 같아요! 분위기도 좋고 대화하기도 좋습니다!!! 분위기 좋고 맛있는 카페로 강추합니다💕', 76, 15, 'GOOD', SYSTIMESTAMP);
