INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00094@test.com'), '빈티지 케이크 너무 예뻐요 맛도 있고 사랑스러워요 직원분들도 너무 친절하세요 ♡ 샤머 조각 케이크 급해서 전화드렸는데 딱 하나 살 수 있었어요 감사합니다 최애 생일 축하도 잘 하고 잘 먹고 갑니다 💕', 9, 6, 'GOOD', SYSTIMESTAMP);
