INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '넘 이쁘고 동화속에 들어온 기분 이에요 바나나푸딩 진짜좋아하는데. 넘 맛있어요 모양만 이쁜게아니네요~ 아기자기 귀엽고. 이쁜 케익 사러 다음에 또 오고싶어요', 10, 10, 'GOOD', SYSTIMESTAMP);
