INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '메론소다 처음먹어봤는데 메론시럽에 사이다 맛이에용ㅎㅎㅎ너무 굿굿 아메리카노가 진짜 맛있어요 산미없고 원래 아메리카노 못먹는데 여기 아메리카노는 맛있어요 그리고 케이크도 진짜 맛있어요 초코케이크부분이 진하고 굿굿 라즈베리도 톡톡 씹혀용ㅎㅎㅎ굿굿🔥🔥', 53, 13, 'GOOD', SYSTIMESTAMP);
