INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '저도 드디어 와봤습니당😭 친구가 여기 케이크 먹고 싶다고 해서 알게 됐는데 진짜 넘넘 예뻐용😍 연예인분들도 여기서 주문하는 이유가 있네여..🥹 케이크 디자인도 진짜 예쁘고 인테리어도 짱이에요👍 딸기라떼도 달구 에이드도 레전드 짱 맛있어요 케이크 너무 귀여워요 어떻게 이렇게 만들 수 있는 건지.. 저는 손재주가 1도 없어서 이렇게는 절대 못 만들 것 같은데 최고입니다!!👍 앞으로 이 주변 오게 되면 여기는 무조건 들릴 것 같아요 여러분들도 꼭 와보세요 되게 귀엽구 예쁘구 맛있고 최고 짱이에용🩷 아 글구 직원분들도 정말 친절하셔서 기분 좋게 먹었습니다!!😁', 114, 19, 'GOOD', SYSTIMESTAMP);
