INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00058@test.com'), '아기자기 귀어운 인테리어에 귀엽고 맛있는 케이크들♡ 당일홀케이크 되는곳 얼마없는데 다음에 홀케이크 필요하면 여기에서 주문해야겠어요♡', 47, 2, 'GOOD', SYSTIMESTAMP);
