INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), 'n년전부터 팔로우했던 베니케이크 드디어왔어요!! 보기만했던케이크 실제로 먹었는데 넘 맛있어요 ㅠㅠㅠ 시트 넘 부드럽자넝.. 늦게가서 다른 종류의 케이크를 못먹었지만 초코라도 있어서 다행.. 매장도 넘 이쁘고 오늘 착장이랑 잘어울리는 느낌이라 만족200% 다음엔 남칭구랑 오고싶네영', 1, 4, 'GOOD', SYSTIMESTAMP);
