INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00017@test.com'), '빨리 먹고싶어서 대충 찍었는데도 이쁘게 나와요 인테리어 미쳤어요!!!! 음료수도 케잌도 너무 맛있습니다🥹🥹🥹 커피는 친구들 왈 산미 있는 맛이라고 합니다 동네였으면 매일 와서 종류별로 먹어보고 싶은 곳이에요', 13, 2, 'GOOD', SYSTIMESTAMP);
