INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00008@test.com'), '유튜브 보고 왔어용❤️❤️ 케이크는 역시 너무 귀엽고 이뿌고 진짜 맛있어요!! 인테리어도 베니케이크답게 빈티지스럽고 사진고 정말 잘나와요💕💕👍👍 데이트나 사진 건지고싶으신 분들 짱추천드려요😆😆', 126, 23, 'GOOD', SYSTIMESTAMP);
