INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '상수 카페거리에 왔는데 지나가다 귀여운 카페가 있어서 들어왔어요~! 왔는데 코코넛크림파이가 있어서 바로 주문했는데 고소하고 달달해서 너무 맛있었습니다😃 코코넛 파이 좋아하시는 분들은 완전 강추🙌 메론소다도 근본 아이스크림 올라가있는걸보니 인기 있는 이유가 있습니다🙌👍', 16, 0, 'GOOD', SYSTIMESTAMP);
