INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00078@test.com'), '인스타랑 유튜브에서 보고 예전부터 와보고 싶었던 카페였어요! 홀케이크는 양이 부담스러운데 이렇게 조각으로 먹어볼 수 있는 오프라인 매장이 있어서 너무 좋아요. 케이크가 주력인 매장이니 커피는 기대 안했는데 커피도 너무 맛있어요. 케이크는 복숭아 요거트 케이크인데 식감이 재밌고 크림도 빵도 다 맛있네요!!! 맛이 묵직하지 않아서 여름이랑 너무 잘어울리는 맛이에요. 근데 사실 이 매장에서 제일 감동적이었던 건 친절한 직원분이셨습니다. 이것저것 여쭤봤는데 너무 친절하고 귀여운 말로 안내해주셔서 감사했어요!! 맛도 미관도 중요하지만 친절한 직원분이 이 좋은것들을 잔뜩 만끽할 수 있게 해주시네요.', 9, 4, 'GOOD', SYSTIMESTAMP);
