INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '주변 지나가다가 홀린 듯이 들어왔어요 평소에 이름 많이 들었어서 궁금했는데 유명한 이유가 있어요🤤 라즈베리갸또쇼콜라 상큼하면서 초콜릿은 꾸덕해서 순삭했어욤… 덕분에 혼자만의 시간 잘 즐기고 갑니당', 113, 21, 'GOOD', SYSTIMESTAMP);
