INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '매장도 이쁘고 무엇보다 케이크가 진짜 너무 맛있어요. 직원분들이 친절하셔서 더 좋았어요. 케이크 데코가 매번 바뀌는것 같아 나중에 한번 더 와보고 싶어요!! 바나나케이크 진짜 너무 맛있어요🌟', 51, 12, 'GOOD', SYSTIMESTAMP);
