INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '커피 완전 진하고 맛있어요! 케이크랑 먹으면 진짜 맛있을 것 같은데 다음에는 배 좀 비우고 케이크도 먹으러 와야겠어요ㅎㅎ 매장이 아기자기하고 케이크도 넘 귀엽고 맛있어보여요!', 8, 4, 'GOOD', SYSTIMESTAMP);
