INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00090@test.com'), '시즌마다 새로운 디저트도 있고 분위기도 아기자기해서 너무 좋아요!! 디저트 디자인도 정말 예쁘구 ㅠㅠ!! 저녁 시간대라 사람이 많이 없어서 잘있다가 갑니다 ㅎㅎ 팝업도 작게하는데 이벤트로 정말 귀여운,,랜덤팩도 주셨어요! 감사합니다~', 3, 2, 'GOOD', SYSTIMESTAMP);
