INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '아이랑 방문했는데 인테리어도 아기자기하고 케이크도 귀엽고 아늑해서 아이도 좋아하네요! 딸기라떼도 진하고 맛있고 커피도 맛있어요 케이크 포장해서 먹어보고 맛있어서 바나나푸딩먹으러 다시 왔어요❤️', 30, 6, 'GOOD', SYSTIMESTAMP);
