INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '진짜 맛있어요 🥹… 카운터가 분리 된 방 형태로 좌석이 되어있는데 프라이빗하고 너무 좋았습니다 인테리어를 배우신 분인가 싶을 정도로 아기자기하고 좋아요 케이크도 제가 먹은 것중 제일 맛잇었고 음료도 정말 좋은 재료 써서 맛있게 해주셔서 감동적이었습니다 생일 장소로 정말 훌륭한 곳이었어요 🩷…', 0, 9, 'GOOD', SYSTIMESTAMP);
