INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00060@test.com'), '두 번째 방문이에오! 역시 케이크 너뮤 예쁘고 너무 맛있고 직원분들도 다 너무 친절했고 친구랑 이야기하기도 너무 좋아서 자주 올 것 같아요 ~.~ 케이크 비주얼 다시봐도 미쳤당… 🎂🍰🎂🍰🎂🍰🍴🍴🍴', 44, 10, 'GOOD', SYSTIMESTAMP);
