INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00074@test.com'), '남칭구랑 두번째로 방문하는 베니케이크〰️💕 복숭아요거트케이크 넘나 상콤하고 피치얼그레이도 달달해서 좋네요 저번과 달리 지하 층 이용했는데 분위기도 좋고 인테리어 예쁘네요 다음에 또 오겠습니당👍👍🥰', 18, 1, 'GOOD', SYSTIMESTAMP);
