INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '골목길 구경하다 발견한 카페 ! 아늑하고 공간도 넓어보여서 들어갔는데 인테리어도 아기자기 포인트가 너무 많아요! 디저트와 음료도 너무 예쁘네요 🧡 잠시 방문한 것 만으로도 기분이 너무 좋아지는 장소였습니다. 다음에 또 올게요 💜', 19, 3, 'GOOD', SYSTIMESTAMP);
