INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '인스타에서만 구경하다가 동생이랑 처음 방문하게되었어요 매장도 너무 귀엽고 케이크랑 음료도 넘 맛있어요~ 다음에 또 방문하겠습니다~ 많이 파세요~~', 121, 19, 'GOOD', SYSTIMESTAMP);
