INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '직원분이 너무 친절하시고 케이크가 예쁜데 맛있어서 항상 믿고 먹어요.ᐟ 가까워서 자주 찾아먹는 편인데 커스텀 케이크가 필요해서 당일 레터링 부탁드렸는데 금방 해주셔서 좋았습니다 :) 급하게 생일 케이크 필요하신 분들, 맛있는 케이크 먹고싶다하시는 분들 베니케이크 추천드려요~~.ᐟ', 44, 3, 'GOOD', SYSTIMESTAMP);
