INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '인테리어가 전체적으로 귀여운 편입니다. 케이크카페답게 종류도 다양하고 다 맛있어 보여서 고르는데 한참 걸렸네요… 가격대는 조금 비싸지만 그만큼의 가치가 있습니다!! 내부도 엄청 시원하고 직원분들도 친절해서 편하게 쉬다 갑니다~!! 카페전문 유튜브 유리소리TV', 136, 98, 'GOOD', SYSTIMESTAMP);
