INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '우연히 왔는데 제가 유튜브에서 보던 곳이었네요!🐰멜론소다 먹고싶었는데 품절이라 아쉽지만 메론케이크 넘 맛있어요! 공간도 아기자기 귀엽구 ㅎㅎ', 36, 8, 'GOOD', SYSTIMESTAMP);
