INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00069@test.com'), '지나가다가 예뻐서 들렀는데 맛있어요! 옛날 미국영화에 나오는 인테리어를 통째로 옮겨둔것 같아요 🫡 뉴욕 매그놀리아에서 파는 바나나푸딩보다 훨씬 맛있고 아늑해서 좋아요! 커피도 최고(양도많음)', 64, 14, 'GOOD', SYSTIMESTAMP);
