INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '메론소다가 너무 귀여워용🍈🍦 인테리어도 너무 아기자기하고 생각보다 아담한데 카페 분위기가 시끄럽지 않아서 좋아요. 책 읽기에도 적절한 소음과 외국에 온 듯한 아기자기한 분위기가 너무 좋아요.', 107, 21, 'GOOD', SYSTIMESTAMP);
