INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00093@test.com'), '인테리어가 되게 아기자기하고 디저트랑 커피가 맛있어요! 특히 복숭아케이크가 맛있어용 ㅎㅎ 바닐라라떼에 바닐라빈도 쓰는데 다른 카페에 비해 커피가 저렴해요 ㅎㅎ', 35, 1, 'GOOD', SYSTIMESTAMP);
