INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '매장 분위기 아기자기 너무 귀여워요.. 소품,음악까지 옛날 느낌나고 케이크는 보던대로 예쁘네요! 생크림이라 느끼하지도 않고 얼그레이초코는 케이크 안에 오독오독 씹히는 초콜렛 청크가 재밌었어요. 먹는게 아까울 정도로ㅠㅠ 맛있고 예쁜 케이크네요😍 늘 오고 싶었던 곳인데 이번에 멀리 온 김에 들린 보람이 있었어요. 번창하세요💓', 31, 10, 'GOOD', SYSTIMESTAMP);
