INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '디저트 디자인이 귀엽고 넘 맛잇어요 ㅠ 👍🏻👍🏻!! 커피도 맛있고, 인테리어도 아늑하고 예뻐서 계속 사진 찍고 싶은 곳입니다❣️', 12, 0, 'GOOD', SYSTIMESTAMP);
