INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '지난번에 왔다가 너무 좋아서 또 방문했어요🥹🩷 아랫층에서 느긋하게 머물렀는데 케이크도 음료도 너무 맛있고 좋았어요! 음악도 좋고, 분위기도 딱 제 취향ㅠㅠ 친구나 자매끼리 와서 수다떨기도 좋은 것 같네용♡ 여기 방문하면 넘 맛있어서 1인1케이크도 가능....♡', 28, 0, 'GOOD', SYSTIMESTAMP);
