INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00004@test.com'), '유튜브에서 보던 비주얼 그대로에요 🥹 매장도 귀엽고 쾌적합니다. 덥지만 않으면 테라스도 이용할 수 있을 거 같아요. 사장님도 매우 친절하시고 케이크가 무진장 귀엽습니다 😚 망고 케이크 너무 추천드립니다!', 9, 6, 'GOOD', SYSTIMESTAMP);
