INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00028@test.com'), '날이 더워 눈에 보이는 카페 중에 핑크핑크한 베니케이크가 보여 남편을 놀려주려고 큰 기대없이 들어왔는데 오~👍 생각보다 커피도 맛있고 엄청 달것 처럼 생겼지만 보기와는 다르게 상콤달콤 신선한 크림 의 레몬코코넛파이는 커피와도 잘 어울렸습니다. 다음에는 초코바나나 어쩌고저쩌고 케이크랑 옆테이블에서 엄청 맛있다를 연발하는 저 복숭아 요거트 어쩌고 케이크를 맛봐야겠습니다. 스텝분들이 엄청 친절해서 극소심 I형 아줌마 아저씨도 맘편히 쉬었다 갑니당.', 15, 3, 'GOOD', SYSTIMESTAMP);
