INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00005@test.com'), '너무 귀엽고 예쁜카페를 발견했어요!ㅋㅋ케이크 다 이쁘고 먹음직스러워서… 어떤걸 먹어야할지 고민많이됐어요 메론케잌안에 진짜 메론이 박혀있어서 매우 맛있는!! 커피, 메론라떼 시켰는데 메뉴 선택 완전 만족입니당ㅋㅋ 아이와 나들이 왔다가 기분 좋아졌어요', 5, 10, 'GOOD', SYSTIMESTAMP);
