INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00001@test.com'), '베니케이크 맨날 유튜브로만 멍때리면서 보는 제 최애채널이라 매장도 가보구싶었는데 직접 오니까 더더 기분 좋네요ㅠㅠㅠ 인테리어 하나하나 너무 귀엽구 케이크 고르는데 너무 오래걸렸어요ㅠㅠㅠ 진짜 가만히 있어도 행복해지는 곳🐻🧡', 10, 3, 'GOOD', SYSTIMESTAMP);
