INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '한결같이 예쁘고 맛있는 케이크 맛집인 홍대카페에요❤️ 사장님도 직원분들도 넘 친절하시고 바나나 푸딩이랑 복숭아 케이크는 여기가 젤 맛있어요🫶🏻 곳곳이 포토존이라 기분 좋아지는 카페😍 데이트 코스로 강추합니당👍🏻', 28, 9, 'GOOD', SYSTIMESTAMP);
