INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00007@test.com'), '매장이 너무 예뻐요 ,, 케이크도 왜이렇게 이뻐요? 심지어 별로 안 달아요 ,, 나중에 레터링케이크 꼭 주문해서 가져가고싶어요', 50, 3, 'GOOD', SYSTIMESTAMP);
