INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '맛잘알 친구가 주변에 많으면 인생을 효율적이고 합리적으로 살 수 있는 것 같습니다 🫶🏻 또 친구따라 왔는데 역시나 너무나 성공적 💖 맛도 맛있지만 비쥬얼도 맛집 ♡⃛ 역시 실버버튼은 아무나 받는 게 아닌 것 같습니다 😋 제가 골랐던 복숭아 요거트는 상큼달달이고, 얼그레이 초코는 🤦🏻‍♀️ 와따입니다 친구가 고른 건데 역시 안목이 수준급이에요 최고야 친구들 우리 우정 영원하자 🍀 여기도 영원히 장사하시면 좋겠어요♥️', 23, 7, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00034@test.com'), '아이 생일케이크가 필요해서 당일방문했는데 운좋게 원하는 케이크를 바로 구매 할수있었습니다^^ 레터링도 바로 해주셔서 넘 감사했어요😊 스텝분들도 친절하시고 매장도 너무 예뻐서 기분이 좋아지는 곳이였어요😊 또 방문하고 싶어지는 카페였습니다^^', 2, 7, 'GOOD', SYSTIMESTAMP);
