INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '미국 가정집 카페로 특별한 디저트와 커피 그리고 음료가 있어요. ※추천메뉴 메론소다 바나나푸딩 ※ 매장 ㆍ지하 및 1층과 2층으로 된 주택형 카페 ㆍ깨끗한 공용 1인 화장실 : B+ ㆍ아메리카노 산미와 스모키한 맛 ㆍ종이 빨대 아님 ㆍ네이버 리뷰이벤트 있음', 32, 4, 'GOOD', SYSTIMESTAMP);
