INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00038@test.com'), '케이크가 절묘하게 달콤하고 상큼해서 정말 맛있어요 얼그레이 초코 크림라떼도 진한 얼그레이크림과 초코가 어우려져서 달콤씁씁해서 부담없는 단맛이에요 담겨진 컵도 예뼈요 하지만 역역 초코초코 조합은 너무 슈가러시하네요', 72, 18, 'GOOD', SYSTIMESTAMP);
