INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '베니케이크 너무 맛있고 이뻐요!! 케이크가 너무 달지도 않고 촉촉하고 메론이 진짜 싱싱하고 아낌없이 들어가 있었고, 음료도 정말 맛있어용.. 근데 카페 분위기까지 아기자기 미국빈티지 감성🐻💗 완전 취향저격 제대로 당하고 갑니당!! 최고에요💗💗 담에 또 올게용ㅎㅎ', 9, 1, 'GOOD', SYSTIMESTAMP);
