INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '카페 음료가 맛있고, 분위기가 너무 예뻐요! 구석구석 있는 장식품이 고풍스러워서 유럽의 방 안에 들어와있는 기분이 들었습니다 바닥에 있는 카펫도 그 분위기를 한껏 강조해준 것 같아 좋았습니다! 리뷰 이벤트 하면 예쁘고 귀여운 엽서도 주니 다들 리뷰 이벤트도 꼭 해주시면 좋을 것 같아요! 다음에도 친구랑 방문하러 올게요 :>', 7, 5, 'GOOD', SYSTIMESTAMP);
