INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00070@test.com'), '친구들이랑 서울 나들이 와서 방문했어요💕 유튜브로 케이크 만드는 영상은 봐왔는데 이번에 직접 방문해서 좋았습니다! 평일이라 그런가 웨이팅은 따로 없었고 단거 좋아하는 저한텐 맛있었어요👍', 40, 10, 'GOOD', SYSTIMESTAMP);
