INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00021@test.com'), '귀여운 디저트와 인테리어 때문에 꼭 한 번 와보고 싶었는데 기대 이상으로 귀엽고 맛있어요!🥺🎀 예쁘고 감각적인 소품들 덕분에 눈이 즐거웠는데 그보다 더 귀여운 케이크가...!🩷 다 맛있지만 그중에 얼그레이 초코 케이크 강추합니다🌟🌟🌟', 11, 1, 'GOOD', SYSTIMESTAMP);
