INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00026@test.com'), '완전 맛있는거같아요 케이크도  크림치즈를 쓴거같아서더 맛있는거같네요!! 복숭아요거트케이크에눈 복숭아도 많이들어서 좋앗구 얼그레이 초코에는 얼그레이 맛이 생각보다 강해서 좋앗던거같아요!! 매장분위기도 좋고 디자인도 귀여워서 좋은거같아요!!', 81, 13, 'GOOD', SYSTIMESTAMP);
