INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '지인 축하 케익으로 예약 케익 찾을겸 왔는데 그냥 지나칠수 없어서 커피랑 디저트 시켜서 먹었는데 와우 꾸덕과 달콤 짱💖✨ 매장이 진짜 너무 귀여워용🐻🌟', 36, 2, 'GOOD', SYSTIMESTAMP);
