INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00012@test.com'), '진짜 케이크 너무너무 다 맛있어보여요 이범엔 레터링 케이크랑 바노피파이 , 얼그레이 초코 샀는데 다음엔 바나나 푸딩도 꼭 사먹으려구요 음료도 맛있어보이는데 픽업한거라 ㅠㅠ̑̈ 아쉽지만 담에 다시 방문할때 푸딩이랑 먹어야겟어요', 63, 18, 'GOOD', SYSTIMESTAMP);
