INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00011@test.com'), '일단 케이크 정말 너무너무 뽀쟉하구요 ㅜ 맛이 다양해서 다른 곳과는 차별화 돼서 좋구요 심지어 정말루 맛있서요 🥹 인테리어도 감성 쩔어요 . . . 🤍 뭐 하나 빠지지 않는 베니케이크 절대 지켜 🔥 맨날 유튜브로만 구경하다가 실제로 보니까 너무 감동적인 거 있죠 . . 평생 돈길만 걸으십쇼 사장님 🫶', 31, 2, 'GOOD', SYSTIMESTAMP);
