INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '찐 케이크 맛집이네요!! 매장 곳곳에 곰돌이랑 케이크 모형이 반겨주는데 케이크가 생크림인데 전혀 안 물려요. 케이크 안에 들은 내용물도 맛있구요 이 시간에 벌써 얼그레이초코는 거의 다 팔렸어요', 41, 7, 'GOOD', SYSTIMESTAMP);
