INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '분위기 너무 포근하고 감성적이라 예뻐요💗 잔잔하게 나오는 음악도 너무 편안하네요😊 그리고 케이크! 케이크가 너무너무 맛있습니다!! 오렌지 에이드도 청량하고 머뮤 좋아효❣️', 66, 18, 'GOOD', SYSTIMESTAMP);
