INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '카페가 너무 예뻐서 홀린듯 들어간 베니케이크! 케이크가  다 맛있어보이고 예뻐서 어떤걸 먹어야 할지 고르는 것도 힘들었어요. 케이크 맛집으로 유명한데 크림이 살살 녹으면서 딸기도 신선하고 너무 좋았어요 그리고 카페 인테리어가 너무 예뻐서 가면 사진 찍고 싶어지는 귀엽고 사랑스러운 인형의 집 같은 공간이에요 :)', 20, 3, 'GOOD', SYSTIMESTAMP);
