INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00029@test.com'), '노래도 넘 좋고 아기자기한 소품도 많아서 좋아요 케잌과 음료도 금방나오고 넘 맛있습니다 케잌은 선물하기도 넘 좋은것 같고 초도 다양하게 있어서 좋았습니다', 39, 4, 'GOOD', SYSTIMESTAMP);
