INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00003@test.com'), '바노피 파이 너무 맛있었어요!🧸💗 바나나도 큼직하게 들어가서 좋았고 밑에 깔린 쿠키 같은 것도 맛있었어요! 파이 크림 위에 올라간 깜찍한 곰돌이 쿠키까지 완벽🥺💗오늘 하루 제대로 힐링하고 갑니다!🔆 오늘 언니들이랑 만나서 밥 먹고 걷다가 발견해서 그냥 들어 간건데 너무너무 좋았어요! + 귀엽고 깜찍한 이색 케이크가 많아요! + 귀여운 소품과 엽서까지 구경할 수있는 요소가 많아서 좋았어요!', 27, 3, 'GOOD', SYSTIMESTAMP);
