INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00037@test.com'), '디즈니가 생각나는 카페예요. 들어가면 동심 세계로 돌아온 거 같아 힐링이 됩니다ㅎㅎ 케이크들도 레터링 케이크 전문점답게 다들 감성 있고 사장님 실력이 대단해요! YouTube도 운영 하시더라구요? 무려 40만 구독자를 가지고 계시더라구요..! 다음에 또 방문 하겠습니다🧸', 1, 0, 'GOOD', SYSTIMESTAMP);
