INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00015@test.com'), '강추!!!!  홀케이크는 너무 많고 작은케익은 안예쁜게 많거나 비싸고.. 작으면서 예쁘고 맛있는 곳 있었으면 좋겠다 생각했었는데 바로 여기네요! 예쁘기만한게 아니고 맛도 있어요. 가격도 합리적이구요~! 강력추천합니당!! 성수나 강남권에도 매장 내주세요 ㅎㅎ', 38, 5, 'GOOD', SYSTIMESTAMP);
