INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00056@test.com'), '유튜브 영상으로 즐겨봤는데 처음으로 매장 방문해 봤습니다! 매장 안팎으로 예쁘고 빈티지한 무드가 도드라진 장소예요!✨ 어느 곳에서나 사진을 찍어도 잘 나오고, 음료와 디저트 모두 맛있어요!👍 상수역에서도 걸어서 멀지 않고, 길치인 저도 쉽게 찾아올 정도라 좋아요! 다음에도 또 방문해 다른 디저트도 맛보고 싶어요! ㅎㅎ', 8, 8, 'GOOD', SYSTIMESTAMP);
