INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '생일 케이크 사러갔다가 음료도 마시고 나왔어용 일단 당일 레터링 케이크가 된다는 게 젤 좋습니다!! 매장은 지하랑 1층으로 되어있는데 약간 옛날 미국 느낌으로 인테리어를 하셨더라구요😎 엄청 편한 좌석이 있는 건 아니지만 화장실도 안에 있고 깔끔하고 전체적으로 괜찮았습니다!', 23, 2, 'GOOD', SYSTIMESTAMP);
