INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00079@test.com'), '와...!! 언니 따라 온 곳인데 귀여운 소품 천지에 케이크랑 음료도 맛있고. 레몬코코넛파이는 과한 단맛이나 신맛 없어서 아메리카노랑 마시기 딱 좋았어요. 둘이 조합 굿굿. 다음에 또 올게요 ><', 46, 1, 'GOOD', SYSTIMESTAMP);
