INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00033@test.com'), '케이크 느끼하지도 않고 너무 달지도 않아서 너무 맛있었어요ㅠㅜ 복숭아요거트케이크랑 메론소다 비주얼도 예쁘고 진짜 넘무 맛있게 먹었숩니당🥹🩷', 2, 6, 'GOOD', SYSTIMESTAMP);
