INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00023@test.com'), '사장님 유튜브 초창기때부터 봐왔던 골수팬인데... 이렇게 우연한 기회로 매장 오게 되어 너무 기뻐요🥹🥹 성덕이 된 기분... 💕💕 보기에도 너무 예쁜 케이크 너무 맛있구 인테리어도 제가 너무 좋아하는 빈티지 가득가득이라 너무 행복했어요 💕 베니케이크 타지역에도 분점 내쥬세요...🥹', 30, 7, 'GOOD', SYSTIMESTAMP);
