INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00013@test.com'), '친구들이랑 카페 찾으면서 케이크가 너무 이뻐서 왔습니당. 😍 얼그레이 초코케익 그렇게 막 달지도 않이 좋기했습니당 엄청 단 케이크를 좋아하지 않는데 이건 맛있더라고요🤭 인테리어도 이쁘고 해서 추천🥰🩷', 54, 11, 'GOOD', SYSTIMESTAMP);
