INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00052@test.com'), '진짜 유튜브로 보거 너무너무 와보고싶던 곳이였는데 직접와서 먹어보니깐 진짜 더더더더더더더더 맛있고 분위기도 최고였어요ㅠㅠ최고에요 다음에 또오고싶어요ㅠㅍ', 14, 10, 'GOOD', SYSTIMESTAMP);
