INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '유투브에서 보고 찜해둔 곳인데 아이 생일겸 와봤어요. 케이크가 정말 예쁘고 맛도 좋아요. 조용한 분위기도 마음에 들고 아기자기한 인테리어도 예쁩니다. 다음에 다른 케이크도 먹어보고 싶네요.', 12, 4, 'GOOD', SYSTIMESTAMP);
