INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00031@test.com'), '케이크가 과하게 달지 않아 좋았어요! 예쁘고 귀여운 케이크는 맛이 없을 거라는 편견이 있었는데 그 편견 여기서 깨트리고 갑니당', 46, 6, 'GOOD', SYSTIMESTAMP);
