INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '유명한 곳이라 오고 싶었는데! 기대했던 거 이상으로 좋았어요..🥰 일단 카페 구석구석 다 너무 예쁘고 아기자기 해요 ㅠㅠ 넘넘 귀엽.. 그리고 무엇보다도 케이크가 너무 맛있어요!! 제철과일 케이크도 어떨지 궁금하네용.. 앤틱한 분위기에 어울리는 배경음악도 좋아요🎼 앞으로 자주 올 거 같아요!🤎🤎', 61, 18, 'GOOD', SYSTIMESTAMP);
