INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '주말 오후에 근처에서 식사하고 왔어요😍 케이크가 정말 맛있었어요!ㅎㅎ어린 아이를 데려오기에는 조금 아쉽지만, 데이트하거나, 가볍게와서 이야기하기에는 너무 좋을거같아요👍🥰 케이크는 꼭 드셔보세요😘', 105, 21, 'GOOD', SYSTIMESTAMP);
