INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00002@test.com'), '케익좋아해서 검색해서 찾아갔어요. 내부도 아기자기 이뿌고 지하에도 좌석있다는데 귀찮아서 안가봤네요.ㅎ 메론음료도 맛있고 커피. 케익도 맛있어요. 케익은 너무 이뻐서 보는것만으로도 힐링이네요. 직원분들도 친절하시고 잘쉬다갑니다~^^', 22, 3, 'GOOD', SYSTIMESTAMP);
