INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00019@test.com'), '직원분이 너무 친절하시고 인원 수에 맞춰서 편한자리도 알려주셔서 들어오자마자 기분이 좋았습니다. 당일케이크도 팔고 있고, 케이크 모양이 아기자기해서 너무 귀여웠어요❤️', 6, 5, 'GOOD', SYSTIMESTAMP);
