INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00068@test.com'), '너무 아기자기하고 귀여운 카페에요! 약간 영국 가정집온 느낌! 노래도 LP노래같고 케이크는 특히 복숭아 요거가 빙그레 요플레 요거트가 맛있어진 맛이라서 좋았어요! 초코케잌도 맛있어요ㅋㅋㅋㅋ', 108, 21, 'GOOD', SYSTIMESTAMP);
