INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00083@test.com'), '급하게 당일로 부탁드렸는데 해주셨어요! 급하게 레터링케이크 필요하신분들은 여기서해도 좋을 거 같아요 당일케이크치고 디자인도 너무 아기자기하고 예쁘네요!', 70, 13, 'GOOD', SYSTIMESTAMP);
