INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00061@test.com'), '음식점 웨이팅하면서 근처 카페 온건데 뜻밖에 맛집 발견했어요 :)) 인테리어도 빈티지하면서 아기자기하게 잘 꾸며져있고, 케이크들도 귀엽고 맛있어서 나중에 친구 케이크로도 좋을거 같아요!!! 바닐라라떼도 꼬숩고 맛있습니당 ㅎㅎ 케이크가 다 귀여워서 직원분한테 추천 받았는데 성공적😋', 15, 0, 'GOOD', SYSTIMESTAMP);
