INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00051@test.com'), '사람이 많았는데 직원분도 너무 친절하게 응대해주셨고 디저트가 진짜 너무너무 맛있어요.....ㅜㅜㅜㅜ🥹 사장님 옆집 살고 싶어요,,, 타르트지를 안좋아해서 파이를 안좋아하는데 베니케이크 바노피파이 먹고 걍 인생 파이가 되... 케이크도 맛있고 직원분도 너무 친절하시고 인테리어도 너무 예뻐서 나중에 재방문 할거에요😊', 87, 13, 'GOOD', SYSTIMESTAMP);
