INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '케이크가 너무맛나요~ 얼그레이초코 라즈베리갸또쇼콜라먹었는데 많이 달지않은데도 맛이 진했어요~커피도 쏟았는데 친절하게 다 닦아주시고 커피 그냥주신다고 했는데 죄송해서 계산은 했어요~담에 또 홍대올일있으면 오려구요~!', 46, 6, 'GOOD', SYSTIMESTAMP);
