INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00039@test.com'), '베니케이크 처음 와 봤는데,,!! 딱 매장에 도착하자마자 케이크 비주얼에 눈이 황홀했습니다🔅 비주얼만큼 음료랑 케이크도 너무 맛있었습니다🖤 직원분들도 친절하셔서 더더욱 좋았습니다..매장도 편안하여서..더더욱 완벽한 카페 같네요..🥰베니케이크 있는 케이크들 다 하나씩 먹어보는 게 저의 위시리스트가 되었네요💫 베니케이크 최고😉💛', 6, 7, 'GOOD', SYSTIMESTAMP);
