INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00047@test.com'), '케이크 종류도 다양하구 맛있어요!!! 인테리어 너~무 귀엽구 아기자기해서 취향저격이에요 옛날부터 꼭 오고싶었는데 기대에 왕 만족!! 사장님도 넘 친절하시구 ㅜㅜ 금손이셔요 🩵🩵 다음에 홀케잌 주문도 해보고싶네용 >.<', 22, 4, 'GOOD', SYSTIMESTAMP);
