INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00022@test.com'), '맛있어요! 이쁜케이크중에서도 진짜 맛있는거 찾기힘든데 맛있습니다ㅎㅎ 전 여기 복숭아케이크랑 우유케이크 좋아합니다🥰 겨울철에 나오는 딸기케이크도 맛있어요 저 토끼부분은 우유소금처럼 단짠단짠 맛이나요! 우유케이크는 우유푸딩이 들어가져있구, 복숭아케이크는 단맛이 나는데도 상큼한 끝맛으로 케이크안좋아하는 울 아빠 남동생 남친도 좋아해요👍 초코러버나 다른 초코들도 진하고 맛있어요 멜론소다는 이쁘고 맛납니당🍓 추천해요!!', 28, 3, 'GOOD', SYSTIMESTAMP);
