INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00016@test.com'), '상수 카페 검색하다 베니 케이크 발견해서 바로 와봤어요! 😆😆😆 내부 인테리어 갬성 낭낭하고 디저트는 말모말모… 바나나 푸딩이랑 얼그레이 초코 추천해요!! 🍌🍫', 27, 3, 'GOOD', SYSTIMESTAMP);
