INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00036@test.com'), '친구 생일 축하해 주려고 케이크가 필요했는데 당일 보틀 케이크가 가능해서 편리했어요 디자인도 예쁘고!! 다음에 또 오고 싶아용', 14, 1, 'GOOD', SYSTIMESTAMP);
