INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00020@test.com'), '인테리어도 예쁘고 케이크도 맛있어요! 바나나 케이크 밑에 타르트지 같은 부분이 진짜 맛있었어요😋 얼그레이도 향이 진한데 부담스럽게 강한 맛은 아니라서 좋아씁니당', 30, 5, 'GOOD', SYSTIMESTAMP);
