INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00087@test.com'), '전부터 오고싶었던 베니케이크에 드디어왔어요 :) 내일이 생일인데 , 다행히 휴무전날이라 미리 혼자 생일기념하고 싶었어요 !! 케이크와 음료 너무너무 맛있었구요 ~~ 담엔 커피도 먹으러 오려구요 !! 아기자기하게 잘 되어있어 혼자나 친구들 몇명과 오기 딱 좋은것같네요 :) 잘 즐기다 갑니다 ! 😘', 59, 11, 'GOOD', SYSTIMESTAMP);
