INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00100@test.com'), '으아 케이크 너무너무 이쁘구 카페 인테리어도 너무 예뻐요ㅠㅠ!! 케이크 픽업하러 왔는데 조금 일찍 도착해서 그냥 기다리는김에 케이크도 한조각 시켜서 먹으면서 기다렸어요ㅎㅎ케이크 실제로 보니까 너무 이뻐서 안시킬수가 없었어요🥹♥️', 26, 1, 'GOOD', SYSTIMESTAMP);
