INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00063@test.com'), '인스타에서 보고 저장해놨다가 마침 근처 온 김에 왔는데 예쁜데 맛있기까지..ㅠㅠ 케이크가 다 넘 예뻐서 진짜 선택장애 옵니다,, 복숭아요거트케이크 햇는데 진짜 맛있었어요💕홀케이크 포장하시는 분들 많던데! 다음에 친구 생일케익해주면 엄청 좋아할거같아서 마음속에 담아두고 갑니다😆', 42, 1, 'GOOD', SYSTIMESTAMP);
