INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00064@test.com'), '드디어 방문해본 베니케이크!!! 유튜브에서 케이크 만드는 영상만 보다가 이렇게 직접 먹어보다니 너무 감격적이에오..💗🍰 내부 분위기도 너무 아기자기+빈티지+예쁨 인데다 케이크들도 다 너무 졸구탱예쁨.. 커피도 맛있고.. 데이트 하러오기에도 딱 좋을 듯해요!! 이런 분위기 좋아하는 분들 짱추강추><🤎💗🤎', 30, 10, 'GOOD', SYSTIMESTAMP);
