INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00006@test.com'), '오랜만에 쉬는날 맛있는 케이크 먹고싶어서 왔어요!! 평일이라 웨이팅 없었고, 먹고싶었던 케이크가 품절이라 다른케이크를 먹었지만 그래도 너무 맛있었어요!!! 분위기도 좋고 힐링하고 가요~~~', 38, 8, 'GOOD', SYSTIMESTAMP);
