INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00048@test.com'), '근처로 밥먹으러 왓다가 들렸는데 가게도 이쁘고 케이크들도 이뻐요 ㅠㅠㅠ 그리고 진짜 조오나 마싯어요❤️ 보통 이런케이크는 크림이 느끼하고 맛없는데 광고가 아니고 엄청 달지않은데 깔끔하게 달아여 ㅠㅠ', 33, 1, 'GOOD', SYSTIMESTAMP);
