INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00073@test.com'), '급하게 레터링 케이크가 필요해서 당일에 예약하고 픽업했어요. 너무 친절하게 대해주시고 케이크도 너무 예뻐서 덕분에 소중한 마음 전달할 수 있었습니다!', 49, 5, 'GOOD', SYSTIMESTAMP);
