INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00088@test.com'), '인테리어부터 진짜 너무 예뻐요 .. 우연히 발견했는데 오길 잘했어요  분위기도 아늑하면서 귀여운 포근한 느낌이에용 디저트도 어디서 보지 못했던 귀여운 조각케이크들이 많더라구요 다시 방문할 생각 58000%입니다 💗', 497, 55, 'GOOD', SYSTIMESTAMP);
