INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00097@test.com'), '빈티지하고 따뜻한 분위기가 정말 좋은 곳이에요! 예쁜 인테리어에 맛있고 귀여운 케이크까지.. 완벽하게 마음에 드는 카페입니다 ♥️', 1, 10, 'GOOD', SYSTIMESTAMP);
