INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00082@test.com'), '일요일 오후 4시후반대 4명에서 방문했는데 웨이팅 없이 입장했습니다! 1층이라 지하1층으로 되어있는데 곳곳에 인테리어가 너무 이뻐요!!정말 동화속에 들어온 느낌입니다🤍 밀크티도 진하고 맛있고 케이크들도 넘 맛있어요!! 가격이 저렴한 편은 아니지만 이 돈주고 사먹을만해요!! 초코얼그레이케이크라 딸기케이크 추천드려요!💖', 18, 8, 'GOOD', SYSTIMESTAMP);
