INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00046@test.com'), '건물이 화려해서 들어왔는데 음료도 맛있고 무엇보다 케이크가 진짜 맛있었어요!! 케이크 종류가 다양해서 다른것도 먹어보러 올 거 같아요😆 🍰••• 라즈베리 가또 쇼콜라•••추천!!!', 10, 7, 'GOOD', SYSTIMESTAMP);
