INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00025@test.com'), '유튜브 보고 방문했어요!! 케이크, 메론소다 모두 넘 예쁘고 맛도 좋았습니다🥰 인테리어도 아기자기하고 귀여워요 다음에도 꼭 방문하고 싶어요❤️', 12, 6, 'GOOD', SYSTIMESTAMP);
