INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00041@test.com'), '친구의 청첩장을 받으려고 만났어요! 정말 기쁜 날 아름다운 장소에서 맛있는 것들을 먹을 수 있어 감사합니다☺️☺️ 메론소다 짱맛!!😊😊', 47, 5, NULL, SYSTIMESTAMP);
INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00077@test.com'), '처음 입구부터 너무 귀엽고 아기자기해서 기분 좋게 들어왔어요. 들어와서도 분위기가 되게 차분하고, 사장님도 너무 친절하시고, 케잌도 종류가 많았어요. 그리고 인테리어도 기분 좋아질만큼 너무 예뻐요!!!. 케잌도 음료도 너무너무 맛있고 좋습니다^~^**. 데이트 하면서 와도 너무 좋을 것 같아요.', 22, 3, 'GOOD', SYSTIMESTAMP);
INSERT INTO review_tag (review_id, category_code, code) VALUES ((SELECT MAX(review_id) FROM review), 'MENU', 'CAKE');
