INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00010@test.com'), '홀케이크 예약한거 픽업하러 잠시 들렀었구요, 입구부터 빈티지한 매력과 들어가자마자 따듯하고 편안한 분위기에 기분이 좋아졌어요💕 주문한 케이크도 사진과 똑같은 디자인으로 제가 원하는 문구로 제작이 되었고 주문하는 과정도 너무 친절하시고 빨라서 호다닥 예약 하게 되었습니다!!!! 너무 예뻐요! 진열대에 케이크 나열되어있는데 그냥 눌러 앉아서 먹고싶어 혼났습니당😂😂 픽업전 양초가 너무 예뻐서 구매하고 가려는데 엽서디자인도 너무 귀여워서 데려왔어요. 가족과 맛있게 케이크 먹고 다음엔 먹으러 와야겠습니다 💕 보통은 레터링케잌은 맛을 보장하지 않아서 모양새 차리는 용으로 구매해왔는데 ㅠㅠ여러군데 찾아보니까 맛도 보장된 곳이라, 믿고 주문해서 샀어요💕 특별한날 자주 이용하기 좋아요!! 다들 베니케이크 하세요🐰🐰🍀🍀☘️☘️', 24, 8, 'GOOD', SYSTIMESTAMP);
