INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00085@test.com'), 'ㅠㅠ 케이크 너무 귀여워요 근처에 이자카야 기다리면서 왔는데 진짜 귀여우어어어엉 음료도 맛있고 아이스아메리카노는 약간 산미가 있어요! 라즈베리 갸또는 꾸덕해요! 약간 상큼한거 안좋아시면 비추 저처럼 상큼한거 좋아하시면 추천!!!! 재방문 의사 무조건 있습니다! ❤️ 블로그에도 올려서 자랑할꺼예요!', 14, 3, 'GOOD', SYSTIMESTAMP);
