INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00086@test.com'), '일단 케이크가 귀엽고요, 초코 러버는 밑 크림층에 다양한 초코가 있어서 당 충전 필요할 때 딱입니다. 우유케이크는 눈사람이 아까워서 친구들이 먹어줬어요;ㅅ; 우유 푸딩이 있어서 부들부들하고 맛있어요! 달지 않은 케이크 찾는다면 추천입니다:) 공간마다 예뻐서 맘에 드는 하나만 올립니다. 다음엔 다른 케이크도 먹어봐야겠어요.', 10, 5, 'GOOD', SYSTIMESTAMP);
