INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00043@test.com'), '매장이 너무 예뻐요!! 기념일 케이크듀 만들었는데 만족스럽게 잘 나왔어요♥️♥️ 예상시간보다 일찍 찾으러 왔는데요 빠르게 주셔서 좋았어요!! ᩚ 알차게 놀다가요', 43, 1, 'GOOD', SYSTIMESTAMP);
