INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00065@test.com'), '라즈베리 가또 쇼콜라 케이크 너무 맛잇어요 ... 거기에 딸기라떼의 조합은 구냥 짱짱 !! 사장님두 너무 친절하시구 홍대오면 담에 또 방문할게요 🖤', 39, 6, 'GOOD', SYSTIMESTAMP);
