INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00042@test.com'), '소중한 사람 생일이라 꽃다발 예약한거 찾으러 근처 왔다가 생일인데 케이크 없으면 서운할거 같아서 검색해서 왔는데 홍대에서 걸어오기엔 조금 멀고 상수역이 진짜 가까워요! 분위기도 너무 제가 좋아하는 차분하고 아늑한 분위기고 인테리어가 너무 예뻐서 손민수 하고 싶은것들이 너무 많았습니다ㅠ 온김에 음료도 한잔 마시고 가려고 시켰는데 빨대가 하트라 너무 귀여웠어요🥰담에 소중한 사람하고 같이 오고 싶어지는 곳이였습니다!', 73, 17, 'GOOD', SYSTIMESTAMP);
