INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00089@test.com'), '예전부터 근처 지나갈때마다 궁금했던 카페 드뎌 다녀왔어요:) 딸기 케이크는 너무 달콤하지 않아서 제 입맛에 맞았어여🤍 🍰 카페내 분위기도 서양 느낀이 나서 되게 힐링 되요 다시 방문하고 싶습니다❣️❣️❣️', 95, 20, 'GOOD', SYSTIMESTAMP);
