INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00040@test.com'), '꼭 와보고싶었던 베니케이크 드디어와봐써요!!!❤ 내부 외부 인테리어 모두 너무너무귀엽고 사랑스러워요~ 케이크 비주얼 미쳤고 너무 동화같았어요🥹🫶 매장 분위기 너무 최고에요!!! 또 오고싶은곳이에요~✨', 46, 2, 'GOOD', SYSTIMESTAMP);
