INSERT INTO review (cafe_id, member_id, content, good, bad, sentiment, created_at) VALUES ((SELECT cafe_id FROM cafe WHERE name = '베니케이크'), (SELECT member_id FROM member WHERE email = 'user00057@test.com'), '항상 와보고싶었는데 드디어 와보네요.. 상상 그 이상으로 인테리어도 예쁘고 케이크는 말고.. 다음에 또 와보고싶습니다ㅠㅜ!! 당일보틀케이크 사러왔는데 아이디어 너무 좋아여.. 제가 왔을땐 2번 디자인 말고 1번만 있었지만 저처럼 귀차니즘러에게는 최고의 선택..♡', 24, 7, 'GOOD', SYSTIMESTAMP);
